import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) {
        FastScanner scanner = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out));

        try {
            int n = scanner.nextInt();
            int m = scanner.nextInt();

            char[][] grid = new char[n][];
            for (int i = 0; i < n; i++) {
                grid[i] = scanner.next().toCharArray();
            }

            // Compute directional consecutive counts
            int[][] left = computeDirectionalCounts(grid, true, true);
            int[][] right = computeDirectionalCounts(grid, true, false);
            int[][] up = computeDirectionalCounts(grid, false, true);
            int[][] down = computeDirectionalCounts(grid, false, false);

            // Difference arrays for coverage counting
            int[][] horizontalDiff = new int[n][m];
            int[][] verticalDiff = new int[n][m];
            List<Position> validPositions = new ArrayList<>();

            // Identify valid positions and apply difference array updates
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    int maxReach = Math.min(Math.min(left[i][j], right[i][j]),
                                            Math.min(up[i][j], down[i][j]));

                    if (maxReach > 0) {
                        validPositions.add(new Position(i, j, maxReach));

                        // Horizontal coverage: [j - maxReach, j + maxReach]
                        int hStart = Math.max(0, j - maxReach);
                        int hEnd = Math.min(m - 1, j + maxReach);
                        horizontalDiff[i][hStart]++;
                        if (hEnd + 1 < m) {
                            horizontalDiff[i][hEnd + 1]--;
                        }

                        // Vertical coverage: [i - maxReach, i + maxReach]
                        int vStart = Math.max(0, i - maxReach);
                        int vEnd = Math.min(n - 1, i + maxReach);
                        verticalDiff[vStart][j]++;
                        if (vEnd + 1 < n) {
                            verticalDiff[vEnd + 1][j]--;
                        }
                    }
                }
            }

            // Compute prefix sums to get actual coverage counts
            for (int i = 0; i < n; i++) {
                for (int j = 1; j < m; j++) {
                    horizontalDiff[i][j] += horizontalDiff[i][j - 1];
                }
            }

            for (int j = 0; j < m; j++) {
                for (int i = 1; i < n; i++) {
                    verticalDiff[i][j] += verticalDiff[i - 1][j];
                }
            }

            // Check if any '*' cell has zero coverage
            boolean hasUncoveredStar = false;
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    if (grid[i][j] == '*' && horizontalDiff[i][j] + verticalDiff[i][j] == 0) {
                        hasUncoveredStar = true;
                        break;
                    }
                }
                if (hasUncoveredStar) break;
            }

            // Output results
            if (hasUncoveredStar) {
                out.println("-1");
            } else {
                out.println(validPositions.size());
                for (Position pos : validPositions) {
                    out.println(pos);
                }
            }
        } finally {
            out.flush();
            out.close();
        }
    }

    /**
     * Computes directional consecutive non-empty cell counts.
     *
     * @param grid The input character grid
     * @param horizontal true if processing rows, false if processing columns
     * @param forward true if scanning left-to-right or top-to-bottom, false otherwise
     * @return 2D array where each cell stores the count of consecutive non-'.' cells
     *         in the specified direction, or 0 if count < 2
     */
    private static int[][] computeDirectionalCounts(char[][] grid, boolean horizontal, boolean forward) {
        int n = grid.length;
        int m = grid[0].length;
        int[][] counts = new int[n][m];

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                int row = horizontal ? i : j;
                int col = horizontal ? j : i;
                int start = forward ? 0 : m - 1;
                int end = forward ? m : -1;
                int step = forward ? 1 : -1;

                int consecutiveCount = 0;
                for (int k = start; k != end; k += step) {
                    int r = horizontal ? row : k;
                    int c = horizontal ? k : col;

                    if (grid[r][c] == '.') {
                        consecutiveCount = 0;
                    } else {
                        consecutiveCount++;
                        if (consecutiveCount >= 2) {
                            counts[r][c] = consecutiveCount - 1;
                        }
                    }
                }
            }
        }
        return counts;
    }

    /**
     * Represents a valid position with its coverage radius.
     * Coordinates are 1-indexed in the output.
     */
    private static class Position {
        final int x, y, size;

        Position(int x, int y, int size) {
            this.x = x + 1;
            this.y = y + 1;
            this.size = size;
        }

        @Override
        public String toString() {
            return x + " " + y + " " + size;
        }
    }

    /**
     * Fast input scanner using BufferedReader and StringTokenizer.
     * Replaces the custom InputReader for better maintainability and standard compliance.
     */
    private static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input", e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            String token = next();
            return token == null ? 0 : Integer.parseInt(token);
        }
    }
}

import java.io.*;
import java.util.*;

public class StarGridProcessor {

    /** Represents a potential star center at (row, col) */
    public static class StarCenter {
        final int row, col;
        public StarCenter(int row, int col) { this.row = row; this.col = col; }
        @Override public String toString() { return row + " " + col; }
    }

    /** Represents a continuous line of stars from (startRow, startCol) to (endRow, endCol) inclusive */
    public static class Line {
        final int startRow, endRow, startCol, endCol;
        public Line(int startRow, int startCol, int endRow, int endCol) {
            this.startRow = startRow; this.endRow = endRow;
            this.startCol = startCol; this.endCol = endCol;
        }
        @Override public String toString() { return startRow + "," + startCol + " " + endRow + "," + endCol; }
    }

    /** Represents a detected star with its center coordinates (1-based) and arm length */
    public static class Star {
        final int row, col, size;
        public Star(int row, int col, int size) { this.row = row; this.col = col; this.size = size; }
        @Override public String toString() { return row + " " + col + " " + size; }
    }

    public static void main(String[] args) throws IOException {
        FastScanner sc = new FastScanner();
        PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out));

        try {
            int n = sc.nextInt();
            int m = sc.nextInt();
            sc.nextLine(); // Consume the newline after reading m

            char[][] grid = new char[n][m];
            for (int i = 0; i < n; i++) {
                String line = sc.nextLine();
                // Skip empty lines that may occur due to newline consumption
                while (line != null && line.length() < m) {
                    line = sc.nextLine();
                }
                if (line != null) {
                    grid[i] = line.toCharArray();
                }
            }

            // Step 1: Find all valid star centers
            List<StarCenter> starCenters = findStarCenters(grid, n, m);

            // Step 2: Detect horizontal and vertical lines of stars
            Map<Integer, List<Line>> horizontalLines = detectLines(grid, n, m, true);
            Map<Integer, List<Line>> verticalLines = detectLines(grid, n, m, false);

            // Step 3: Calculate stars and remove their arms from the grid
            List<Star> stars = new ArrayList<>();
            for (StarCenter center : starCenters) {
                Line hLine = findLineInRange(horizontalLines.get(center.row), center.col, true);
                Line vLine = findLineInRange(verticalLines.get(center.col), center.row, false);

                if (hLine == null || vLine == null) continue;

                int hArm = Math.min(center.col - hLine.startCol, hLine.endCol - center.col);
                int vArm = Math.min(center.row - vLine.startRow, vLine.endRow - center.row);
                int size = Math.min(hArm, vArm);

                stars.add(new Star(center.row + 1, center.col + 1, size));

                // Remove the star's arms
                for (int k = center.row - size; k <= center.row + size; k++) {
                    grid[k][center.col] = '.';
                }
                for (int k = center.col - size; k <= center.col + size; k++) {
                    grid[center.row][k] = '.';
                }
            }

            // Step 4: Validate that all stars have been removed
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    if (grid[i][j] == '*') {
                        out.println(-1);
                        return;
                    }
                }
            }

            // Step 5: Output results
            out.println(stars.size());
            for (Star star : stars) {
                out.println(star);
            }

        } finally {
            out.flush();
        }
    }

    /** Finds all grid positions that are '*' surrounded by '*' in all 4 cardinal directions */
    private static List<StarCenter> findStarCenters(char[][] grid, int n, int m) {
        List<StarCenter> centers = new ArrayList<>();
        for (int i = 1; i < n - 1; i++) {
            for (int j = 1; j < m - 1; j++) {
                if (grid[i][j] == '*' &&
                    grid[i][j - 1] == '*' && grid[i][j + 1] == '*' &&
                    grid[i - 1][j] == '*' && grid[i + 1][j] == '*') {
                    centers.add(new StarCenter(i, j));
                }
            }
        }
        return centers;
    }

    /** Detects continuous lines of '*'s. If horizontal=true, scans rows; otherwise scans columns. */
    private static Map<Integer, List<Line>> detectLines(char[][] grid, int n, int m, boolean horizontal) {
        Map<Integer, List<Line>> lines = new HashMap<>();

        if (horizontal) {
            for (int row = 0; row < n; row++) {
                int start = -1;
                for (int col = 0; col < m; col++) {
                    if (grid[row][col] == '*') {
                        if (start == -1) start = col;
                    } else {
                        if (start != -1) {
                            int length = col - start;
                            if (length >= 2) {
                                lines.computeIfAbsent(row, k -> new ArrayList<>())
                                     .add(new Line(row, start, row, col - 1));
                            }
                            start = -1;
                        }
                    }
                }
                if (start != -1) {
                    int length = m - start;
                    if (length >= 2) {
                        lines.computeIfAbsent(row, k -> new ArrayList<>())
                             .add(new Line(row, start, row, m - 1));
                    }
                }
            }
        } else {
            for (int col = 0; col < m; col++) {
                int start = -1;
                for (int row = 0; row < n; row++) {
                    if (grid[row][col] == '*') {
                        if (start == -1) start = row;
                    } else {
                        if (start != -1) {
                            int length = row - start;
                            if (length >= 2) {
                                lines.computeIfAbsent(col, k -> new ArrayList<>())
                                     .add(new Line(start, col, row - 1, col));
                            }
                            start = -1;
                        }
                    }
                }
                if (start != -1) {
                    int length = n - start;
                    if (length >= 2) {
                        lines.computeIfAbsent(col, k -> new ArrayList<>())
                             .add(new Line(start, col, n - 1, col));
                    }
                }
            }
        }
        return lines;
    }

    /** Finds a line that strictly contains the given position */
    private static Line findLineInRange(List<Line> lines, int pos, boolean horizontal) {
        if (lines == null) return null;
        for (Line line : lines) {
            if (horizontal) {
                if (pos > line.startCol && pos < line.endCol) return line;
            } else {
                if (pos > line.startRow && pos < line.endRow) return line;
            }
        }
        return null;
    }

    /** Fast I/O helper class optimized for competitive programming */
    public static class FastScanner {
        BufferedReader br;
        StringTokenizer st;

        public FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        String nextLine() {
            String str = "";
            try {
                str = br.readLine();
            } catch (IOException e) {
                throw new RuntimeException(e);
            }
            return str;
        }
    }
}

import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        FastScanner scanner = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out));

        try {
            int n = scanner.nextInt();
            int m = scanner.nextInt();

            char[][] grid = new char[n][m];
            for (int i = 0; i < n; i++) {
                String row = scanner.next();
                grid[i] = row.toCharArray();
            }

            boolean[][] marked = new boolean[n][m];
            StringBuilder resultLines = new StringBuilder();
            int crossCount = 0;

            // Scan grid to find valid cross centers
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    if (grid[i][j] == '*') {
                        int radius = computeCrossRadius(grid, i, j, n, m);
                        if (radius > 0) {
                            markCross(marked, i, j, radius, n, m);
                            resultLines.append(i + 1).append(' ')
                                       .append(j + 1).append(' ')
                                       .append(radius).append('\n');
                            crossCount++;
                        }
                    }
                }
            }

            // Verify every '*' is covered by at least one cross
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    if (grid[i][j] == '*' && !marked[i][j]) {
                        out.println("-1");
                        out.flush();
                        return;
                    }
                }
            }

            out.println(crossCount);
            out.print(resultLines);
        } finally {
            out.flush();
        }
    }

    /**
     * Computes the maximum radius of a cross centered at (row, col).
     * The radius is limited by the shortest consecutive '*' sequence in any of the 4 cardinal directions.
     */
    private static int computeCrossRadius(char[][] grid, int row, int col, int n, int m) {
        int minRadius = Integer.MAX_VALUE;
        int[][] directions = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};

        for (int[] dir : directions) {
            int count = 0;
            int r = row + dir[0];
            int c = col + dir[1];

            while (r >= 0 && r < n && c >= 0 && c < m && grid[r][c] == '*') {
                count++;
                r += dir[0];
                c += dir[1];
            }
            minRadius = Math.min(minRadius, count);
        }
        return minRadius;
    }

    /**
     * Marks the center and arms of a cross in the marked array.
     */
    private static void markCross(boolean[][] marked, int row, int col, int radius, int n, int m) {
        marked[row][col] = true; // Mark center

        int[][] directions = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};
        for (int[] dir : directions) {
            for (int k = 1; k <= radius; k++) {
                int r = row + dir[0] * k;
                int c = col + dir[1] * k;
                if (r >= 0 && r < n && c >= 0 && c < m) {
                    marked[r][c] = true;
                }
            }
        }
    }

    /**
     * Fast input reader for competitive programming style inputs.
     * Replaces the original bit-level parser with a standard, readable, and maintainable implementation.
     */
    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            String s = next();
            if (s == null) throw new NoSuchElementException();
            return Integer.parseInt(s);
        }
    }
}

import java.io.*;
import java.util.*;

public class TankSolver {
    private static final FastScanner fs = new FastScanner();
    private static final PrintWriter out = new PrintWriter(System.out);

    // Direction vectors for Up, Down, Left, Right
    private static final int[] DR = {-1, 1, 0, 0};
    private static final int[] DC = {0, 0, -1, 1};

    public static void main(String[] args) {
        // Original hardcoded t = 1. Kept for compatibility, but structured properly.
        int t = 1;
        for (int test = 0; test < t; test++) {
            solveTestCase();
        }
        out.flush();
    }

    private static void solveTestCase() {
        int n = fs.nextInt();
        int m = fs.nextInt();
        char[][] grid = new char[n][m];
        boolean[][] visited = new boolean[n][m];

        for (int i = 0; i < n; i++) {
            grid[i] = fs.next().toCharArray();
        }

        int solutionCount = 0;
        StringBuilder result = new StringBuilder();

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == '*') {
                    int minDist = calculateMinConsecutiveStars(grid, i, j);

                    // Skip positions with no adjacent stars or invalid distances
                    if (minDist == 0) {
                        continue;
                    }

                    visited[i][j] = true;
                    markDirections(visited, i, j, minDist);

                    result.append(i + 1).append(' ')
                          .append(j + 1).append(' ')
                          .append(minDist).append('\n');
                    solutionCount++;
                }
            }
        }

        // Verify all '*' are covered by the selected positions
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == '*' && !visited[i][j]) {
                    out.println("-1");
                    return;
                }
            }
        }

        out.println(solutionCount);
        out.print(result);
    }

    /**
     * Calculates the minimum number of consecutive '*' cells in any of the 4 directions
     * from the given starting position.
     */
    private static int calculateMinConsecutiveStars(char[][] grid, int row, int col) {
        int minDistance = Integer.MAX_VALUE;
        int n = grid.length;
        int m = grid[0].length;

        for (int d = 0; d < 4; d++) {
            int consecutive = 0;
            int r = row + DR[d];
            int c = col + DC[d];

            while (r >= 0 && r < n && c >= 0 && c < m && grid[r][c] == '*') {
                consecutive++;
                r += DR[d];
                c += DC[d];
            }
            minDistance = Math.min(minDistance, consecutive);
        }

        return minDistance;
    }

    /**
     * Marks cells in all 4 directions up to the specified distance.
     */
    private static void markDirections(boolean[][] visited, int row, int col, int distance) {
        for (int d = 0; d < 4; d++) {
            int r = row + DR[d];
            int c = col + DC[d];
            for (int k = 0; k < distance; k++) {
                if (r >= 0 && r < visited.length && c >= 0 && c < visited[0].length) {
                    visited[r][c] = true;
                }
                r += DR[d];
                c += DC[d];
            }
        }
    }

    /**
     * Fast I/O utility for competitive programming.
     */
    private static class FastScanner {
        private final BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        private StringTokenizer st = new StringTokenizer("");

        public String next() {
            while (!st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        public String nextLine() {
            try {
                return br.readLine();
            } catch (IOException e) {
                throw new RuntimeException(e);
            }
            return "";
        }

        public int nextInt() {
            String s = next();
            return s == null ? 0 : Integer.parseInt(s);
        }

        public long nextLong() {
            String s = next();
            return s == null ? 0L : Long.parseLong(s);
        }

        public double nextDouble() {
            String s = next();
            return s == null ? 0.0 : Double.parseDouble(s);
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.ArrayList;
import java.util.List;

public class Main {

    public static void main(String[] args) throws IOException {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter writer = new PrintWriter(System.out);

        try {
            String[] dimensions = reader.readLine().trim().split("\\s+");
            int width = Integer.parseInt(dimensions[1]);
            int height = Integer.parseInt(dimensions[0]);

            Grid grid = new Grid(width, height);
            grid.readInput(reader);
            grid.buildDpTables();
            grid.solve();

            if (!grid.isSolvable()) {
                writer.println(-1);
            } else {
                List<int[]> placements = grid.getPlacements();
                writer.println(placements.size());
                for (int[] placement : placements) {
                    writer.println(placement[0] + " " + placement[1] + " " + placement[2]);
                }
            }
        } finally {
            writer.flush();
            writer.close();
            reader.close();
        }
    }
}

class Grid {
    private final int width;
    private final int height;
    private final char[][] field;
    private final boolean[][] visited;
    private final int[][] dpLeft;
    private final int[][] dpRight;
    private final int[][] dpUp;
    private final int[][] dpDown;
    private final List<int[]> placements;
    private boolean isSolvable;

    public Grid(int width, int height) {
        this.width = width;
        this.height = height;
        this.field = new char[height][];
        this.visited = new boolean[height][width];
        this.dpLeft = new int[height][width];
        this.dpRight = new int[height][width];
        this.dpUp = new int[height][width];
        this.dpDown = new int[height][width];
        this.placements = new ArrayList<>();
        this.isSolvable = true;
    }

    public void readInput(BufferedReader reader) throws IOException {
        for (int r = 0; r < height; r++) {
            String line = reader.readLine();
            field[r] = (line != null) ? line.toCharArray() : new char[0];
        }
    }

    public void buildDpTables() {
        // dpLeft[r][c] stores the number of consecutive '*' ending at (r,c) going left
        for (int r = 0; r < height; r++) {
            for (int c = 0; c < width; c++) {
                if (field[r][c] == '*') {
                    dpLeft[r][c] = (c > 0) ? dpLeft[r][c - 1] + 1 : 1;
                }
            }
        }

        // dpRight[r][c] stores the number of consecutive '*' ending at (r,c) going right
        for (int r = 0; r < height; r++) {
            for (int c = width - 1; c >= 0; c--) {
                if (field[r][c] == '*') {
                    dpRight[r][c] = (c < width - 1) ? dpRight[r][c + 1] + 1 : 1;
                }
            }
        }

        // dpUp[r][c] stores the number of consecutive '*' ending at (r,c) going up
        for (int c = 0; c < width; c++) {
            for (int r = 0; r < height; r++) {
                if (field[r][c] == '*') {
                    dpUp[r][c] = (r > 0) ? dpUp[r - 1][c] + 1 : 1;
                }
            }
        }

        // dpDown[r][c] stores the number of consecutive '*' ending at (r,c) going down
        for (int c = 0; c < width; c++) {
            for (int r = height - 1; r >= 0; r--) {
                if (field[r][c] == '*') {
                    dpDown[r][c] = (r < height - 1) ? dpDown[r + 1][c] + 1 : 1;
                }
            }
        }
    }

    public void solve() {
        // Only interior cells can serve as centers for a cross with radius >= 1
        for (int r = 1; r < height - 1; r++) {
            for (int c = 1; c < width - 1; c++) {
                if (field[r][c] == '*') {
                    // DP tables include the center cell, so we subtract 1 to get the valid radius
                    int radius = Math.min(Math.min(dpLeft[r][c], dpRight[r][c]),
                                          Math.min(dpUp[r][c], dpDown[r][c])) - 1;

                    if (radius > 0) {
                        markCoverage(r, c, radius);
                        placements.add(new int[]{r + 1, c + 1, radius});
                    }
                }
            }
        }

        // Verify that every '*' cell in the grid has been covered by at least one cross
        for (int r = 0; r < height; r++) {
            for (int c = 0; c < width; c++) {
                if (field[r][c] == '*' && !visited[r][c]) {
                    isSolvable = false;
                    return;
                }
            }
        }
    }

    private void markCoverage(int centerR, int centerC, int radius) {
        // Mark vertical line of the cross
        for (int r = centerR - radius; r <= centerR + radius; r++) {
            visited[r][centerC] = true;
        }
        // Mark horizontal line of the cross
        for (int c = centerC - radius; c <= centerC + radius; c++) {
            visited[centerR][c] = true;
        }
    }

    public boolean isSolvable() {
        return isSolvable;
    }

    public List<int[]> getPlacements() {
        return placements;
    }
}

import java.io.*;
import java.util.*;

public class StarsDrawing {
    private int rows;
    private int cols;
    private char[][] grid;

    // Directions: up, down, right, left
    private static final int[][] DIRECTIONS = {{-1, 0}, {1, 0}, {0, 1}, {0, -1}};

    public static void main(String[] args) throws IOException {
        // Use try-with-resources for automatic and safe resource management
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
             PrintWriter pw = new PrintWriter(new BufferedOutputStream(System.out))) {

            StarsDrawing solver = new StarsDrawing();
            solver.solve(br, pw);
            pw.flush();
        }
    }

    public void solve(BufferedReader br, PrintWriter pw) throws IOException {
        String line = br.readLine();
        if (line == null) return;

        StringTokenizer st = new StringTokenizer(line);
        rows = Integer.parseInt(st.nextToken());
        cols = Integer.parseInt(st.nextToken());
        grid = new char[rows][cols];

        for (int i = 0; i < rows; i++) {
            String rowLine = br.readLine();
            if (rowLine != null) {
                grid[i] = rowLine.trim().toCharArray();
            }
        }

        List<StarInfo> validStars = new ArrayList<>();
        boolean starFound = false;

        // Phase 1: Identify valid stars and calculate minimum directional distance
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == '*') {
                    starFound = true;
                    int minDist = findMinConsecutiveStars(i, j);
                    if (minDist > 0) {
                        validStars.add(new StarInfo(i, j, minDist));
                    }
                }
            }
        }

        int count = validStars.size();
        // If stars exist but none met the criteria, output -1
        if (count == 0 && starFound) {
            pw.println(-1);
            return;
        }

        // Phase 2: Mark processed stars in all four directions
        for (StarInfo star : validStars) {
            markStarsInAllDirections(star.r, star.c, star.dist);
        }

        // Phase 3: Verify all original stars were processed
        if (!areAllStarsProcessed()) {
            pw.println(-1);
            return;
        }

        // Phase 4: Output results
        pw.println(count);
        for (StarInfo star : validStars) {
            pw.println((star.r + 1) + " " + (star.c + 1) + " " + star.dist);
        }
    }

    private boolean isValid(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols && grid[r][c] == '*';
    }

    private int findMinConsecutiveStars(int r, int c) {
        int minDist = Integer.MAX_VALUE;
        for (int[] dir : DIRECTIONS) {
            int dist = countConsecutiveStars(r, c, dir[0], dir[1]);
            if (dist < minDist) {
                minDist = dist;
            }
        }
        return minDist;
    }

    // Replaces recursive move() to prevent StackOverflowError on large grids
    private int countConsecutiveStars(int r, int c, int dr, int dc) {
        int count = 0;
        int currR = r + dr;
        int currC = c + dc;
        while (isValid(currR, currC)) {
            count++;
            currR += dr;
            currC += dc;
        }
        return count;
    }

    private void markStarsInAllDirections(int r, int c, int dist) {
        for (int[] dir : DIRECTIONS) {
            markInDirection(r, c, dir[0], dir[1], dist);
        }
    }

    // Replaces recursive mark() with an iterative approach
    // Original logic marks (dist + 1) cells starting from the current position
    private void markInDirection(int r, int c, int dr, int dc, int dist) {
        int currR = r;
        int currC = c;
        for (int step = 0; step <= dist; step++) {
            if (isValid(currR, currC)) {
                grid[currR][currC] = '#';
            }
            currR += dr;
            currC += dc;
        }
    }

    private boolean areAllStarsProcessed() {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == '*') {
                    return false;
                }
            }
        }
        return true;
    }

    // Replaces generic Triple with a strongly-typed, immutable data class
    private static final class StarInfo {
        final int r, c, dist;

        StarInfo(int r, int c, int dist) {
            this.r = r;
            this.c = c;
            this.dist = dist;
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.Arrays;
import java.util.StringTokenizer;

public class Main {
    public static void main(String[] args) {
        InputReader in = new InputReader(System.in);
        PrintWriter out = new PrintWriter(System.out);
        new Solver().solve(in, out);
        out.flush();
        out.close();
    }

    /**
     * Encapsulates the problem-solving logic.
     */
    static class Solver {
        private static final char BARRIER = '.';
        private static final char OBSTACLE = '*';

        // Directional indices for the 3D distance array
        private static final int DIR_LEFT = 0;
        private static final int DIR_RIGHT = 1;
        private static final int DIR_UP = 2;
        private static final int DIR_DOWN = 3;

        private int positiveCellCount = 0;

        public void solve(InputReader in, PrintWriter out) {
            int originalN = in.nextInt();
            int originalM = in.nextInt();

            // Padding is added to simplify boundary checks and avoid index-out-of-bounds
            int n = originalN + 2;
            int m = originalM + 2;

            char[][] grid = readGrid(in, n, m);
            int[][][] directionalDistances = computeDirectionalDistances(grid, n, m);
            int[][] minDistances = computeMinDistances(directionalDistances, n, m);
            boolean[][] coverage = computeCoverage(minDistances, n, m);

            if (!validateAndPrint(coverage, minDistances, grid, n, m, out)) {
                out.println(-1);
            }
        }

        /**
         * Reads the grid from input, applying border padding.
         */
        private char[][] readGrid(InputReader in, int n, int m) {
            char[][] grid = new char[n][m];
            Arrays.fill(grid[0], BARRIER);
            Arrays.fill(grid[n - 1], BARRIER);

            for (int i = 1; i < n - 1; i++) {
                grid[i][0] = BARRIER;
                grid[i][m - 1] = BARRIER;
                String rowStr = in.next();
                for (int j = 1; j < m - 1; j++) {
                    grid[i][j] = rowStr.charAt(j - 1);
                }
            }
            return grid;
        }

        /**
         * Computes the distance to the nearest obstacle in all four cardinal directions.
         */
        private int[][][] computeDirectionalDistances(char[][] grid, int n, int m) {
            int[][][] dist = new int[4][n][m];

            // Initialize all distances to -1
            for (int d = 0; d < 4; d++) {
                for (int i = 0; i < n; i++) {
                    Arrays.fill(dist[d][i], -1);
                }
            }

            // Left to Right
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    if (grid[i][j] == OBSTACLE) {
                        dist[DIR_LEFT][i][j] = dist[DIR_LEFT][i][j - 1] + 1;
                    }
                }
            }

            // Right to Left
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    if (grid[i][m - 1 - j] == OBSTACLE) {
                        dist[DIR_RIGHT][i][m - 1 - j] = dist[DIR_RIGHT][i][m - j] + 1;
                    }
                }
            }

            // Top to Bottom
            for (int j = 0; j < m; j++) {
                for (int i = 0; i < n; i++) {
                    if (grid[i][j] == OBSTACLE) {
                        dist[DIR_UP][i][j] = dist[DIR_UP][i - 1][j] + 1;
                    }
                }
            }

            // Bottom to Top
            for (int j = 0; j < m; j++) {
                for (int i = 0; i < n; i++) {
                    if (grid[n - 1 - i][j] == OBSTACLE) {
                        dist[DIR_DOWN][n - 1 - i][j] = dist[DIR_DOWN][n - i][j] + 1;
                    }
                }
            }

            return dist;
        }

        /**
         * Computes the minimum distance to an obstacle across all directions.
         * Sets distance to -1 if it is 0 (directly on an obstacle).
         */
        private int[][] computeMinDistances(int[][][] dist, int n, int m) {
            int[][] minDist = new int[n][m];
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    int min = Math.min(Math.min(dist[DIR_LEFT][i][j], dist[DIR_RIGHT][i][j]),
                                       Math.min(dist[DIR_UP][i][j], dist[DIR_DOWN][i][j]));

                    if (min == 0) {
                        minDist[i][j] = -1;
                    } else if (min > 0) {
                        minDist[i][j] = min;
                        positiveCellCount++;
                    } else {
                        minDist[i][j] = min;
                    }
                }
            }
            return minDist;
        }

        /**
         * Determines which cells are covered based on the minimum distance propagation.
         */
        private boolean[][] computeCoverage(int[][] minDist, int n, int m) {
            boolean[][] coverage = new boolean[n][m];

            // Row-wise coverage propagation
            for (int i = 0; i < n; i++) {
                int maxLeft = -1;
                int maxRight = -1;
                for (int j = 0; j < m; j++) {
                    maxLeft = Math.max(maxLeft, minDist[i][j]);
                    maxRight = Math.max(maxRight, minDist[i][m - 1 - j]);

                    if (maxLeft >= 0) {
                        coverage[i][j] = true;
                        maxLeft--;
                    }
                    if (maxRight >= 0) {
                        coverage[i][m - 1 - j] = true;
                        maxRight--;
                    }
                }
            }

            // Column-wise coverage propagation
            for (int j = 0; j < m; j++) {
                int maxTop = -1;
                int maxBottom = -1;
                for (int i = 0; i < n; i++) {
                    maxTop = Math.max(maxTop, minDist[i][j]);
                    maxBottom = Math.max(maxBottom, minDist[n - 1 - i][j]);

                    if (maxTop >= 0) {
                        coverage[i][j] = true;
                        maxTop--;
                    }
                    if (maxBottom >= 0) {
                        coverage[n - 1 - i][j] = true;
                        maxBottom--;
                    }
                }
            }

            return coverage;
        }

        /**
         * Validates that all obstacles are covered and prints the result.
         * Returns true if valid, false otherwise.
         */
        private boolean validateAndPrint(boolean[][] coverage, int[][] minDist, char[][] grid, int n, int m, PrintWriter out) {
            // Ensure every obstacle is marked as covered
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    if (grid[i][j] == OBSTACLE && !coverage[i][j]) {
                        return false;
                    }
                }
            }

            out.println(positiveCellCount);
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    if (minDist[i][j] > 0) {
                        out.print(i);
                        out.print(' ');
                        out.print(j);
                        out.print(' ');
                        out.println(minDist[i][j]);
                    }
                }
            }
            return true;
        }
    }

    /**
     * Efficient input reader for competitive programming contexts.
     */
    static class InputReader {
        private final BufferedReader br;
        private StringTokenizer st;

        public InputReader(InputStream stream) {
            br = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) {
                        return null;
                    }
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input", e);
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            String token = next();
            return (token == null) ? 0 : Integer.parseInt(token);
        }
    }
}

import java.io.BufferedInputStream;
import java.io.BufferedOutputStream;
import java.io.PrintWriter;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.Scanner;

public class GridStarMatcher {

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(new BufferedInputStream(System.in));
             PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out))) {
            solve(scanner, out);
        }
    }

    public static void solve(Scanner scanner, PrintWriter out) {
        int rows = scanner.nextInt();
        int cols = scanner.nextInt();

        boolean[][] grid = new boolean[rows][cols];
        for (int i = 0; i < rows; i++) {
            String line = scanner.next();
            for (int j = 0; j < cols; j++) {
                grid[i][j] = line.charAt(j) == '*';
            }
        }

        List<CrossPattern> foundPatterns = new ArrayList<>();
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                int radius = 0;
                while (isCrossFilled(grid, r, c, radius + 1)) {
                    radius++;
                }
                if (radius > 0) {
                    foundPatterns.add(new CrossPattern(r, c, radius));
                }
            }
        }

        boolean[][] reconstructedGrid = new boolean[rows][cols];
        for (CrossPattern pattern : foundPatterns) {
            markCrossOnGrid(reconstructedGrid, pattern);
        }

        if (Arrays.deepEquals(grid, reconstructedGrid)) {
            out.println(foundPatterns.size());
            for (CrossPattern pattern : foundPatterns) {
                // Output uses 1-based indexing for row and column
                out.printf("%d %d %d%n", pattern.row + 1, pattern.col + 1, pattern.radius);
            }
        } else {
            out.println("-1");
        }
    }

    /**
     * Checks if a cross of the given radius centered at (centerRow, centerCol) 
     * is completely filled with true values and fits within the grid bounds.
     */
    private static boolean isCrossFilled(boolean[][] grid, int centerRow, int centerCol, int radius) {
        int top = centerRow - radius;
        int bottom = centerRow + radius;
        int left = centerCol - radius;
        int right = centerCol + radius;

        // Boundary checks
        if (top < 0 || bottom >= grid.length || left < 0 || right >= grid[0].length) {
            return false;
        }

        // Check horizontal line
        for (int c = left; c <= right; c++) {
            if (!grid[centerRow][c]) {
                return false;
            }
        }
        // Check vertical line
        for (int r = top; r <= bottom; r++) {
            if (!grid[r][centerCol]) {
                return false;
            }
        }
        return true;
    }

    /**
     * Marks the cells of a cross pattern on the target grid.
     */
    private static void markCrossOnGrid(boolean[][] grid, CrossPattern pattern) {
        int top = pattern.row - pattern.radius;
        int bottom = pattern.row + pattern.radius;
        int left = pattern.col - pattern.radius;
        int right = pattern.col + pattern.radius;

        for (int c = left; c <= right; c++) {
            grid[pattern.row][c] = true;
        }
        for (int r = top; r <= bottom; r++) {
            grid[r][pattern.col] = true;
        }
    }

    /**
     * Represents a detected cross/star pattern in the grid.
     */
    private static class CrossPattern {
        final int row;
        final int col;
        final int radius;

        CrossPattern(int row, int col, int radius) {
            this.row = row;
            this.col = col;
            this.radius = radius;
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

/**
 * Solves the grid coverage problem by finding maximal squares centered at '*' cells.
 * Uses directional distance propagation and difference arrays to efficiently track coverage,
 * then validates that every '*' cell is covered by at least one square.
 */
public class Main {
    private FastScanner scanner;
    private PrintWriter writer;

    public static void main(String[] args) {
        new Main().run();
    }

    private void run() {
        scanner = new FastScanner(System.in);
        writer = new PrintWriter(System.out);
        try {
            solve();
        } finally {
            writer.flush();
            writer.close();
        }
    }

    private void solve() throws IOException {
        int n = scanner.nextInt();
        int m = scanner.nextInt();
        boolean[][] grid = readGrid(n, m);

        int[][] distLeft = new int[n][m];
        int[][] distRight = new int[n][m];
        int[][] distUp = new int[n][m];
        int[][] distDown = new int[n][m];

        computeHorizontalDistances(grid, distLeft, distRight, n, m);
        computeVerticalDistances(grid, distUp, distDown, n, m);

        int[] resultRows = new int[n * m];
        int[] resultCols = new int[n * m];
        int[] resultRadii = new int[n * m];
        int squareCount = 0;

        int[][] coverageLR = new int[n][m];
        int[][] coverageUD = new int[n][m];

        // Identify valid squares and mark coverage using difference arrays
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j]) {
                    int maxRadius = Math.min(Math.min(distLeft[i][j], distRight[i][j]),
                                             Math.min(distUp[i][j], distDown[i][j]));

                    if (maxRadius > 0) {
                        resultRows[squareCount] = i;
                        resultCols[squareCount] = j;
                        resultRadii[squareCount] = maxRadius;

                        // Horizontal range update
                        int startCol = j - maxRadius;
                        int endCol = j + maxRadius;
                        coverageLR[i][startCol]++;
                        if (endCol + 1 < m) {
                            coverageLR[i][endCol + 1]--;
                        }

                        // Vertical range update
                        int startRow = i - maxRadius;
                        int endRow = i + maxRadius;
                        coverageUD[startRow][j]++;
                        if (endRow + 1 < n) {
                            coverageUD[endRow + 1][j]--;
                        }
                        squareCount++;
                    }
                }
            }
        }

        // Compute prefix sums to resolve difference arrays into actual coverage counts
        for (int i = 0; i < n; i++) {
            for (int j = 1; j < m; j++) {
                coverageLR[i][j] += coverageLR[i][j - 1];
            }
        }
        for (int i = 1; i < n; i++) {
            for (int j = 0; j < m; j++) {
                coverageUD[i][j] += coverageUD[i - 1][j];
            }
        }

        // Validate that every '*' cell is covered by at least one square
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] && coverageLR[i][j] == 0 && coverageUD[i][j] == 0) {
                    writer.println(-1);
                    return;
                }
            }
        }

        // Output results
        writer.println(squareCount);
        for (int i = 0; i < squareCount; i++) {
            // Convert 0-based indices to 1-based for output
            writer.println((resultRows[i] + 1) + " " + (resultCols[i] + 1) + " " + resultRadii[i]);
        }
    }

    private boolean[][] readGrid(int n, int m) throws IOException {
        boolean[][] grid = new boolean[n][m];
        for (int i = 0; i < n; i++) {
            String row = scanner.next();
            for (int j = 0; j < m; j++) {
                grid[i][j] = row.charAt(j) == '*';
            }
        }
        return grid;
    }

    private void computeHorizontalDistances(boolean[][] grid, int[][] distLeft, int[][] distRight, int n, int m) {
        for (int i = 0; i < n; i++) {
            for (int j = 1; j < m; j++) {
                distLeft[i][j] = grid[i][j - 1] ? distLeft[i][j - 1] + 1 : 0;
            }
            for (int j = m - 2; j >= 0; j--) {
                distRight[i][j] = grid[i][j + 1] ? distRight[i][j + 1] + 1 : 0;
            }
        }
    }

    private void computeVerticalDistances(boolean[][] grid, int[][] distUp, int[][] distDown, int n, int m) {
        for (int j = 0; j < m; j++) {
            for (int i = 1; i < n; i++) {
                distUp[i][j] = grid[i - 1][j] ? distUp[i - 1][j] + 1 : 0;
            }
            for (int i = n - 2; i >= 0; i--) {
                distDown[i][j] = grid[i + 1][j] ? distDown[i + 1][j] + 1 : 0;
            }
        }
    }

    /**
     * FastScanner utility for efficient competitive programming input parsing.
     */
    static class FastScanner {
        private StringTokenizer st;
        private BufferedReader br;

        FastScanner(InputStream s) {
            br = new BufferedReader(new InputStreamReader(s));
        }

        String next() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) return null;
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

        boolean hasNext() throws IOException {
            return br.ready() || (st != null && st.hasMoreTokens());
        }

        int nextInt() throws IOException {
            String s = next();
            return s == null ? 0 : Integer.parseInt(s);
        }

        long nextLong() throws IOException {
            String s = next();
            return s == null ? 0L : Long.parseLong(s);
        }

        double nextDouble() throws IOException {
            String s = next();
            return s == null ? 0.0 : Double.parseDouble(s.replace(',', '.'));
        }

        String nextLine() throws IOException {
            return br.readLine();
        }

        boolean hasNextLine() throws IOException {
            return br.ready();
        }
    }
}

import java.io.PrintWriter;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.Scanner;

public class E1015 {

    /**
     * Solves the problem using grid parsing, segment identification,
     * distance calculation, and Fenwick Tree-based range updates.
     */
    public void solve(Scanner in, PrintWriter out) {
        int n = in.nextInt();
        int m = in.nextInt();
        boolean[][] grid = new boolean[n][m];

        // Parse the input grid
        for (int i = 0; i < n; i++) {
            String line = in.next();
            for (int j = 0; j < m; j++) {
                grid[i][j] = line.charAt(j) == '*';
            }
        }

        // Initialize segment ID matrices with -1
        int[][] horizontalSegmentIds = new int[n][m];
        int[][] verticalSegmentIds = new int[n][m];
        for (int i = 0; i < n; i++) {
            Arrays.fill(horizontalSegmentIds[i], -1);
            Arrays.fill(verticalSegmentIds[i], -1);
        }

        // Identify horizontal and vertical contiguous segments
        List<Integer> horizontalStartCols = new ArrayList<>();
        List<Integer> horizontalEndCols = new ArrayList<>();
        identifySegments(grid, n, m, horizontalSegmentIds, horizontalStartCols, horizontalEndCols, true);

        List<Integer> verticalStartRows = new ArrayList<>();
        List<Integer> verticalEndRows = new ArrayList<>();
        identifySegments(grid, n, m, verticalSegmentIds, verticalStartRows, verticalEndRows, false);

        // Prepare Fenwick Trees for row and column range updates
        FenwickTree[] rowTrees = new FenwickTree[n];
        FenwickTree[] colTrees = new FenwickTree[m];
        for (int i = 0; i < n; i++) rowTrees[i] = new FenwickTree(m);
        for (int i = 0; i < m; i++) colTrees[i] = new FenwickTree(n);

        List<String> resultLines = new ArrayList<>();

        // Process each cell, calculate minimum distance, and apply range updates
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < m; c++) {
                if (!grid[r][c]) continue;

                int hId = horizontalSegmentIds[r][c];
                int vId = verticalSegmentIds[r][c];
                if (hId == -1 || vId == -1) continue;

                int vStart = verticalStartRows.get(vId);
                int vEnd = verticalEndRows.get(vId);
                int hStart = horizontalStartCols.get(hId);
                int hEnd = horizontalEndCols.get(hId);

                int minDist = Math.min(Math.min(r - vStart, vEnd - r),
                                       Math.min(c - hStart, hEnd - c));

                if (minDist == 0) continue;

                resultLines.add((r + 1) + " " + (c + 1) + " " + minDist);

                // Apply difference array updates using Fenwick Trees
                rowTrees[r].addRange(c - minDist, c + minDist, 1);
                colTrees[c].addRange(r - minDist, r + minDist, 1);
            }
        }

        // Verify that every '*' cell is covered by at least one update range
        boolean isPossible = true;
        for (int r = 0; r < n && isPossible; r++) {
            for (int c = 0; c < m && isPossible; c++) {
                if (grid[r][c]) {
                    long rowCoverage = rowTrees[r].query(c);
                    long colCoverage = colTrees[c].query(r);
                    if (rowCoverage + colCoverage <= 0) {
                        isPossible = false;
                    }
                }
            }
        }

        // Output results
        if (!isPossible) {
            out.println(-1);
        } else {
            out.println(resultLines.size());
            for (String line : resultLines) {
                out.println(line);
            }
        }
    }

    /**
     * Identifies contiguous segments of '*' characters in the grid.
     *
     * @param grid          The boolean grid representing the input
     * @param n             Number of rows
     * @param m             Number of columns
     * @param segmentIds    2D array to store segment IDs for each cell
     * @param starts        List to store starting indices of segments
     * @param ends          List to store ending indices of segments
     * @param isHorizontal  If true, scans row-wise; otherwise column-wise
     */
    private void identifySegments(boolean[][] grid, int n, int m, int[][] segmentIds,
                                  List<Integer> starts, List<Integer> ends, boolean isHorizontal) {
        int idCounter = 0;

        if (isHorizontal) {
            for (int i = 0; i < n; i++) {
                int j = 0;
                while (j < m) {
                    if (!grid[i][j]) {
                        j++;
                        continue;
                    }
                    int currentId = idCounter++;
                    int start = j;
                    while (j < m && grid[i][j]) {
                        segmentIds[i][j] = currentId;
                        j++;
                    }
                    starts.add(start);
                    ends.add(j - 1);
                }
            }
        } else {
            for (int j = 0; j < m; j++) {
                int i = 0;
                while (i < n) {
                    if (!grid[i][j]) {
                        i++;
                        continue;
                    }
                    int currentId = idCounter++;
                    int start = i;
                    while (i < n && grid[i][j]) {
                        segmentIds[i][j] = currentId;
                        i++;
                    }
                    starts.add(start);
                    ends.add(i - 1);
                }
            }
        }
    }

    /**
     * Standard Fenwick Tree (Binary Indexed Tree) implementation.
     * Uses 0-based indexing externally and 1-based internally.
     */
    private static class FenwickTree {
        private final int size;
        private final long[] tree;

        public FenwickTree(int size) {
            this.size = size;
            this.tree = new long[size + 1];
        }

        /**
         * Adds a value to a specific index.
         */
        public void add(int index, long value) {
            for (++index; index <= size; index += index & -index) {
                tree[index] += value;
            }
        }

        /**
         * Applies a range update using the difference array technique.
         * Safely clamps indices to valid bounds.
         */
        public void addRange(int from, int to, long value) {
            add(Math.max(0, from), value);
            if (to + 1 < size) {
                add(to + 1, -value);
            }
        }

        /**
         * Returns the prefix sum from index 0 to the given index.
         */
        public long query(int index) {
            long sum = 0;
            for (++index; index > 0; index -= index & -index) {
                sum += tree[index];
            }
            return sum;
        }
    }

    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        PrintWriter out = new PrintWriter(System.out);
        new E1015().solve(in, out);
        in.close();
        out.close();
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.ArrayList;
import java.util.StringTokenizer;

public class Solution {

    /**
     * FastReader class for efficient input reading.
     * Uses BufferedReader and StringTokenizer for performance.
     */
    static class FastReader {
        BufferedReader br;
        StringTokenizer st;

        public FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            String s = next();
            return s == null ? 0 : Integer.parseInt(s);
        }

        long nextLong() {
            String s = next();
            return s == null ? 0L : Long.parseLong(s);
        }

        double nextDouble() {
            String s = next();
            return s == null ? 0.0 : Double.parseDouble(s);
        }
    }

    /**
     * Data class representing a Star pattern found in the grid.
     */
    static class Star {
        int x, y, r;

        public Star(int x, int y, int r) {
            this.x = x;
            this.y = y;
            this.r = r;
        }
    }

    /**
     * Finds a star pattern centered at (x, y).
     * A star is defined as having consecutive 1s in all 4 directions (up, down, left, right)
     * with a minimum arm length.
     *
     * @param grid  The grid to search
     * @param x     X-coordinate of the center
     * @param y     Y-coordinate of the center
     * @param rows  Number of rows in the grid
     * @param cols  Number of columns in the grid
     * @return      A Star object if found, null otherwise.
     */
    static Star findStar(int[][] grid, int x, int y, int rows, int cols) {
        int minArmLength = Integer.MAX_VALUE;

        // Check Up
        int i = x;
        int count = 0;
        while (i >= 1) {
            if (grid[i][y] == 0) break;
            i--;
            count++;
        }
        minArmLength = Math.min(minArmLength, count);

        // Check Down
        i = x;
        count = 0;
        while (i <= rows) {
            if (grid[i][y] == 0) break;
            i++;
            count++;
        }
        minArmLength = Math.min(minArmLength, count);

        // Check Left
        int j = y;
        count = 0;
        while (j >= 1) {
            if (grid[x][j] == 0) break;
            j--;
            count++;
        }
        minArmLength = Math.min(minArmLength, count);

        // Check Right
        j = y;
        count = 0;
        while (j <= cols) {
            if (grid[x][j] == 0) break;
            j++;
            count++;
        }
        minArmLength = Math.min(minArmLength, count);

        // If the minimum arm length is greater than 1, we found a valid star.
        // The radius 'r' stored is (length - 1) based on original logic.
        if (minArmLength > 1) {
            return new Star(x, y, minArmLength - 1);
        }
        return null;
    }

    /**
     * Marks the star pattern in the grid with value 2.
     *
     * @param grid The grid to modify
     * @param star The star pattern to mark
     */
    static void markStar(int[][] grid, Star star) {
        int x = star.x;
        int y = star.y;
        int r = star.r;

        // Mark vertical line (up and down)
        for (int i = 0; i <= r; i++) {
            grid[x + i][y] = 2;
            grid[x - i][y] = 2;
        }

        // Mark horizontal line (left and right)
        // Start from 1 to avoid re-marking the center, though not strictly necessary
        for (int i = 1; i <= r; i++) {
            grid[x][y + i] = 2;
            grid[x][y - i] = 2;
        }
    }

    /**
     * Checks if there are any unmarked stars (value 1) remaining in the grid.
     *
     * @param grid The grid to check
     * @param rows Number of rows
     * @param cols Number of columns
     * @return     True if any unmarked stars remain, false otherwise.
     */
    static boolean hasRemainingStars(int[][] grid, int rows, int cols) {
        for (int i = 1; i <= rows; i++) {
            for (int j = 1; j <= cols; j++) {
                if (grid[i][j] == 1) {
                    return true;
                }
            }
        }
        return false;
    }

    public static void main(String[] args) {
        FastReader sc = new FastReader();
        PrintWriter out = new PrintWriter(System.out);

        // Read dimensions
        // Using next() to robustly handle whitespace/newlines
        String nStr = sc.next();
        String mStr = sc.next();

        if (nStr != null && mStr != null) {
            int rows = Integer.parseInt(nStr);
            int cols = Integer.parseInt(mStr);

            // Initialize grid with padding (1-based indexing used in logic)
            // Size is (rows + 2) x (cols + 2) to handle boundaries safely
            int[][] grid = new int[rows + 2][cols + 2];

            // Read grid data
            // Using next() because grid rows are typically continuous strings without spaces
            for (int i = 1; i <= rows; i++) {
                String rowStr = sc.next();
                if (rowStr != null) {
                    for (int j = 1; j <= cols; j++) {
                        if (j <= rowStr.length()) {
                            grid[i][j] = (rowStr.charAt(j - 1) == '*' ? 1 : 0);
                        } else {
                            grid[i][j] = 0;
                        }
                    }
                }
            }

            ArrayList<Star> foundStars = new ArrayList<>();

            // Iterate through the grid to find stars
            for (int i = 1; i <= rows; i++) {
                for (int j = 1; j <= cols; j++) {
                    // Only check if the cell is a potential star (value 1)
                    if (grid[i][j] == 1) {
                        Star currentStar = findStar(grid, i, j, rows, cols);
                        if (currentStar != null) {
                            markStar(grid, currentStar);
                            foundStars.add(currentStar);
                        }
                    }
                }
            }

            // Check if all stars were marked
            if (hasRemainingStars(grid, rows, cols)) {
                out.println(-1);
            } else {
                out.println(foundStars.size());
                for (Star star : foundStars) {
                    out.println(star.x + " " + star.y + " " + star.r);
                }
            }
        }

        out.flush();
        out.close();
    }
}

import java.io.ByteArrayInputStream;
import java.io.File;
import java.io.FileInputStream;
import java.io.FileNotFoundException;
import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.InputMismatchException;
import java.util.List;

/**
 * Solves a grid covering problem by placing optimal cross-shaped patterns.
 * Refactored for maintainability, type safety, and explicit bounds checking.
 */
public class GridCoveringSolver {

    /** Direction constants for grid traversal */
    public enum Direction { UP, DOWN, LEFT, RIGHT }

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out);
        try {
            Solver.solve(scanner, out);
        } finally {
            out.flush();
        }
    }

    /** Encapsulates the core solving logic */
    public static class Solver {
        private static final int[] DR = {-1, 0, 0, 1};
        private static final int[] DC = {0, -1, 1, 0};

        /** Entry point for the solver */
        public static void solve(FastScanner scanner, PrintWriter out) {
            int n = scanner.nextInt();
            int m = scanner.nextInt();

            boolean[][] grid = readGrid(scanner, n, m);
            int[][][] distances = computeDistances(grid, n, m);
            List<Command> commands = findCommands(grid, n, m, distances);

            if (!isFullyCovered(grid, n, m, commands)) {
                out.println(-1);
            } else {
                out.println(commands.size());
                for (Command cmd : commands) {
                    out.printf("%d %d %d%n", cmd.row, cmd.col, cmd.armLength);
                }
            }
        }

        /** Reads the N x M grid from input */
        private static boolean[][] readGrid(FastScanner scanner, int n, int m) {
            boolean[][] grid = new boolean[n][m];
            for (int i = 0; i < n; i++) {
                String line = scanner.next();
                for (int j = 0; j < m; j++) {
                    grid[i][j] = line.charAt(j) == '*';
                }
            }
            return grid;
        }

        /** Computes the length of continuous empty segments in all four directions */
        private static int[][][] computeDistances(boolean[][] grid, int n, int m) {
            int[][][] distances = new int[4][n][m];

            // Process rows for LEFT and RIGHT directions
            for (int r = 0; r < n; r++) {
                computeSegmentLengths(grid[r], 
                    distances[Direction.LEFT.ordinal()][r], 
                    distances[Direction.RIGHT.ordinal()][r]);
            }

            // Process columns for UP and DOWN directions
            for (int c = 0; c < m; c++) {
                boolean[] col = new boolean[n];
                for (int i = 0; i < n; i++) col[i] = grid[i][c];
                computeSegmentLengths(col, 
                    distances[Direction.UP.ordinal()][c], 
                    distances[Direction.DOWN.ordinal()][c]);
            }
            return distances;
        }

        /** Calculates contiguous segment lengths for a 1D array */
        private static void computeSegmentLengths(boolean[] arr, int[] left, int[] right) {
            int len = arr.length;
            int p = 0, q = 0;

            while (p < len && !arr[p]) p++;
            while (p < len) {
                while (q < p) q++;
                while (q + 1 < len && arr[q + 1]) q++;
                while (p <= q) {
                    int segmentLen = q - p + 1;
                    left[p] = segmentLen;
                    right[p] = segmentLen;
                    p++;
                }
                while (p < len && !arr[p]) p++;
            }
        }

        /** Finds optimal cross commands and marks covered cells */
        private static List<Command> findCommands(boolean[][] grid, int n, int m, int[][][] distances) {
            List<Command> commands = new ArrayList<>();
            int[][] covered = new int[n][m];

            for (int r = 0; r < n; r++) {
                for (int c = 0; c < m; c++) {
                    if (grid[r][c]) continue;

                    int minLen = Math.min(Math.min(distances[Direction.UP.ordinal()][r][c],
                                                   distances[Direction.DOWN.ordinal()][r][c]),
                                          Math.min(distances[Direction.LEFT.ordinal()][r][c],
                                                   distances[Direction.RIGHT.ordinal()][r][c]));

                    if (minLen < 2) continue;

                    commands.add(new Command(r + 1, c + 1, minLen - 1));

                    // Mark cells covered by the cross
                    for (int arm = 0; arm < minLen; arm++) {
                        for (int dir = 0; dir < 4; dir++) {
                            int nr = r + arm * DR[dir];
                            int nc = c + arm * DC[dir];
                            if (nr >= 0 && nr < n && nc >= 0 && nc < m) {
                                covered[nr][nc] = 1;
                            }
                        }
                    }
                }
            }
            return commands;
        }

        /** Validates that all non-obstacle cells are covered */
        private static boolean isFullyCovered(boolean[][] grid, int n, int m, List<Command> commands) {
            int[][] covered = new int[n][m];
            for (Command cmd : commands) {
                int r = cmd.row - 1;
                int c = cmd.col - 1;
                for (int arm = 0; arm <= cmd.armLength; arm++) {
                    for (int dir = 0; dir < 4; dir++) {
                        int nr = r + arm * DR[dir];
                        int nc = c + arm * DC[dir];
                        if (nr >= 0 && nr < n && nc >= 0 && nc < m) {
                            covered[nr][nc] = 1;
                        }
                    }
                }
            }

            for (int r = 0; r < n; r++) {
                for (int c = 0; c < m; c++) {
                    if (!grid[r][c] && covered[r][c] == 0) {
                        return false;
                    }
                }
            }
            return true;
        }

        /** Immutable command representation */
        public static class Command {
            public final int row;
            public final int col;
            public final int armLength;

            public Command(int row, int col, int armLength) {
                this.row = row;
                this.col = col;
                this.armLength = armLength;
            }
        }
    }

    /** High-performance input scanner for competitive programming */
    public static class FastScanner {
        private final InputStream stream;
        private final byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;

        public FastScanner(InputStream stream) {
            this.stream = stream;
        }

        public FastScanner(File f) throws FileNotFoundException {
            this(new FileInputStream(f));
        }

        public FastScanner(String s) {
            this.stream = new ByteArrayInputStream(s.getBytes(StandardCharsets.UTF_8));
        }

        int read() {
            if (numChars == -1) {
                throw new InputMismatchException();
            }
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0) {
                    return -1;
                }
            }
            return buf[curChar++];
        }

        boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        boolean isEndline(int c) {
            return c == '\n' || c == '\r' || c == -1;
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }

        public double nextDouble() {
            return Double.parseDouble(next());
        }

        public String next() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            StringBuilder res = new StringBuilder();
            do {
                res.appendCodePoint(c);
                c = read();
            } while (!isSpaceChar(c));
            return res.toString();
        }

        public String nextLine() {
            int c = read();
            while (isEndline(c)) {
                c = read();
            }
            StringBuilder res = new StringBuilder();
            do {
                res.appendCodePoint(c);
                c = read();
            } while (!isEndline(c));
            return res.toString();
        }

        public int[] nextIntArray(int n) {
            int[] ret = new int[n];
            for (int i = 0; i < n; i++) {
                ret[i] = nextInt();
            }
            return ret;
        }

        public int[][] next2DIntArray(int n, int m) {
            int[][] ret = new int[n][];
            for (int i = 0; i < n; i++) {
                ret[i] = nextIntArray(m);
            }
            return ret;
        }

        public long[] nextLongArray(int n) {
            long[] ret = new long[n];
            for (int i = 0; i < n; i++) {
                ret[i] = nextLong();
            }
            return ret;
        }

        public long[][] next2DLongArray(int n, int m) {
            long[][] ret = new long[n][];
            for (int i = 0; i < n; i++) {
                ret[i] = nextLongArray(m);
            }
            return ret;
        }

        public double[] nextDoubleArray(int n) {
            double[] ret = new double[n];
            for (int i = 0; i < n; i++) {
                ret[i] = nextDouble();
            }
            return ret;
        }

        public double[][] next2DDoubleArray(int n, int m) {
            double[][] ret = new double[n][];
            for (int i = 0; i < n; i++) {
                ret[i] = nextDoubleArray(m);
            }
            return ret;
        }
    }
}

import java.util.Scanner;

public class E1 {

    private char[][] board;
    private boolean[][] hit;
    private int rows;
    private int cols;

    public static void main(String[] args) {
        E1 solver = new E1();
        solver.run();
    }

    /**
     * Entry point for the program. Handles input reading and delegates processing.
     */
    public void run() {
        try (Scanner scanner = new Scanner(System.in)) {
            if (!scanner.hasNextInt()) {
                return;
            }
            this.rows = scanner.nextInt();
            this.cols = scanner.nextInt();

            this.board = new char[rows][cols];
            this.hit = new boolean[rows][cols]; // Boolean arrays default to false

            for (int i = 0; i < rows; i++) {
                this.board[i] = scanner.next().toCharArray();
            }

            processGrid();
        }
    }

    /**
     * Core logic: scans the grid for cross patterns, marks them, and verifies coverage.
     */
    private void processGrid() {
        StringBuilder output = new StringBuilder();
        int patternCount = 0;

        // Iterate over potential cross centers (avoiding boundary rows/columns)
        for (int i = 1; i < rows - 1; i++) {
            for (int j = 1; j < cols - 1; j++) {
                if (isCrossCenter(i, j)) {
                    int armLength = calculateArmLength(i, j);
                    markCrossAsHit(i, j, armLength);

                    output.append(i + 1).append(" ")
                          .append(j + 1).append(" ")
                          .append(armLength).append("\n");
                    patternCount++;
                }
            }
        }

        if (!areAllStarsCovered()) {
            System.out.println("-1");
        } else {
            System.out.print(patternCount + "\n");
            System.out.print(output);
        }
    }

    /**
     * Checks if the cell at (r, c) is the center of a valid cross pattern.
     * A valid center must have '*' in all four cardinal directions.
     */
    private boolean isCrossCenter(int r, int c) {
        return board[r][c] == '*' &&
               board[r - 1][c] == '*' &&
               board[r + 1][c] == '*' &&
               board[r][c - 1] == '*' &&
               board[r][c + 1] == '*';
    }

    /**
     * Calculates the minimum arm length of the cross centered at (r, c).
     * The arm length is the number of consecutive '*' cells in any single direction
     * from the center before hitting a boundary or a non-'*' cell.
     */
    private int calculateArmLength(int r, int c) {
        int minExtent = Integer.MAX_VALUE;

        // Check Up
        int up = 0;
        while (r - up - 1 >= 0 && board[r - up - 1][c] == '*') {
            up++;
        }
        minExtent = Math.min(minExtent, up);

        // Check Down
        int down = 0;
        while (r + down + 1 < rows && board[r + down + 1][c] == '*') {
            down++;
        }
        minExtent = Math.min(minExtent, down);

        // Check Left
        int left = 0;
        while (c - left - 1 >= 0 && board[r][c - left - 1] == '*') {
            left++;
        }
        minExtent = Math.min(minExtent, left);

        // Check Right
        int right = 0;
        while (c + right + 1 < cols && board[r][c + right + 1] == '*') {
            right++;
        }
        minExtent = Math.min(minExtent, right);

        return minExtent;
    }

    /**
     * Marks all cells belonging to the cross (center and arms) as hit.
     */
    private void markCrossAsHit(int r, int c, int armLength) {
        for (int i = 0; i <= armLength; i++) {
            hit[r + i][c] = true;
            hit[r - i][c] = true;
            hit[r][c + i] = true;
            hit[r][c - i] = true;
        }
    }

    /**
     * Verifies that every '*' on the board has been covered by a detected cross.
     */
    private boolean areAllStarsCovered() {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (board[i][j] == '*' && !hit[i][j]) {
                    return false;
                }
            }
        }
        return true;
    }
}

import java.io.*;
import java.util.StringTokenizer;

public class Main {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out));

        try {
            int n = reader.nextInt();
            int m = reader.nextInt();

            // Basic validation to prevent malformed input issues
            if (n <= 0 || m <= 0) {
                out.println(0);
                return;
            }

            char[][] grid = new char[n][];
            for (int i = 0; i < n; i++) {
                grid[i] = reader.next().toCharArray();
            }

            GridProcessor processor = new GridProcessor(grid, n, m);
            int crossCount = processor.process();

            out.println(crossCount);
            out.print(processor.getOutput());
        } finally {
            out.flush();
            out.close();
        }
    }

    /**
     * Encapsulates grid processing logic to eliminate global mutable state.
     */
    static class GridProcessor {
        private final char[][] grid;
        private final int rows;
        private final int cols;
        private final char EMPTY = '.';
        private final char PROCESSED = 'n';

        private int crossCount = 0;
        private final StringBuilder output = new StringBuilder();

        public GridProcessor(char[][] grid, int rows, int cols) {
            this.grid = grid;
            this.rows = rows;
            this.cols = cols;
        }

        /**
         * Iterates through the grid, finds valid crosses, and records them.
         */
        public int process() {
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    // Only process cells that are not empty
                    if (grid[i][j] != EMPTY) {
                        findAndMarkLargestCross(i, j);
                    }
                }
            }
            return crossCount;
        }

        public String getOutput() {
            return output.toString();
        }

        private void findAndMarkLargestCross(int centerR, int centerC) {
            // Calculate maximum possible cross size based on grid boundaries
            int maxPossibleSize = Math.min(Math.min(centerR, rows - 1 - centerR),
                                           Math.min(centerC, cols - 1 - centerC));

            int bestSize = 0;
            // Find the largest valid cross size
            for (int size = 1; size <= maxPossibleSize; size++) {
                if (isValidCross(centerR, centerC, size)) {
                    bestSize = size;
                } else {
                    // Cross arms cannot be extended further
                    break;
                }
            }

            if (bestSize > 0) {
                markCross(centerR, centerC, bestSize);
                crossCount++;
                output.append(centerR + 1).append(' ')
                      .append(centerC + 1).append(' ')
                      .append(bestSize).append('\n');
            }
        }

        /**
         * Validates if all four arms of a cross at the given size are empty.
         * The center cell itself can be any character.
         */
        private boolean isValidCross(int r, int c, int size) {
            return grid[r - size][c] == EMPTY &&
                   grid[r + size][c] == EMPTY &&
                   grid[r][c - size] == EMPTY &&
                   grid[r][c + size] == EMPTY;
        }

        /**
         * Marks the center and all four arms of the cross as processed.
         */
        private void markCross(int r, int c, int size) {
            grid[r][c] = PROCESSED;
            grid[r - size][c] = PROCESSED;
            grid[r + size][c] = PROCESSED;
            grid[r][c - size] = PROCESSED;
            grid[r][c + size] = PROCESSED;
        }
    }

    /**
     * Fast input reader for competitive programming / high-performance scenarios.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input stream", e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            String token = next();
            if (token == null) throw new RuntimeException("Unexpected end of input");
            return Integer.parseInt(token);
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;

/**
 * Analyzes a 2D grid to identify cross patterns, validates complete coverage,
 * and outputs the results. Refactored for maintainability, readability, and
 * adherence to Java best practices.
 */
public class CrossPatternAnalyzer {

    private final int[][] grid;
    private final boolean[][] visited;
    private final int[][] crossRadii;
    private final int rows;
    private final int cols;

    /**
     * Initializes the analyzer with grid dimensions.
     */
    public CrossPatternAnalyzer(int rows, int cols) {
        this.rows = rows;
        this.cols = cols;
        this.grid = new int[rows][cols];
        this.visited = new boolean[rows][cols];
        this.crossRadii = new int[rows][cols];
    }

    /**
     * Reads the grid data from the provided reader.
     */
    public void readGrid(BufferedReader reader) throws IOException {
        for (int i = 0; i < rows; i++) {
            String line = reader.readLine();
            if (line == null) {
                throw new IOException("Unexpected end of input while reading grid row " + i);
            }
            for (int j = 0; j < cols; j++) {
                grid[i][j] = (line.charAt(j) == '.') ? 0 : 1;
            }
        }
    }

    /**
     * Computes the maximum cross radius for every cell in the grid.
     */
    public void calculateCrossRadii() {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                calculateCenter(r, c);
            }
        }
    }

    /**
     * Determines the largest cross centered at (r, c) and marks covered cells.
     */
    private void calculateCenter(int r, int c) {
        if (grid[r][c] != 1) {
            return;
        }

        int radius = 0;
        for (int i = 1; ; i++) {
            boolean withinBounds = r - i >= 0 && c - i >= 0 && r + i < rows && c + i < cols;
            if (!withinBounds) {
                break;
            }

            boolean armsExist = grid[r - i][c] == 1 && grid[r][c - i] == 1 &&
                                grid[r][c + i] == 1 && grid[r + i][c] == 1;

            if (armsExist) {
                radius++;
                visited[r][c] = true;
                visited[r - i][c] = true;
                visited[r + i][c] = true;
                visited[r][c - i] = true;
                visited[r][c + i] = true;
            } else {
                break;
            }
        }
        crossRadii[r][c] = radius;
    }

    /**
     * Validates that all '1' cells are covered by crosses and prints the results.
     */
    public void analyzeAndPrint() {
        // Validation pass: ensure every '1' is part of at least one cross
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == 1 && !visited[i][j]) {
                    System.out.println(-1);
                    return;
                }
            }
        }

        // Count valid crosses
        int validCrossCount = 0;
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (crossRadii[i][j] > 0) {
                    validCrossCount++;
                }
            }
        }

        System.out.println(validCrossCount);
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (crossRadii[i][j] > 0) {
                    System.out.println((i + 1) + " " + (j + 1) + " " + crossRadii[i][j]);
                }
            }
        }
    }

    public static void main(String[] args) throws IOException {
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(System.in))) {
            String line = reader.readLine();
            if (line == null || line.trim().isEmpty()) {
                return;
            }

            String[] dimensions = line.trim().split("\\s+");
            int n = Integer.parseInt(dimensions[0]);
            int m = Integer.parseInt(dimensions[1]);

            CrossPatternAnalyzer analyzer = new CrossPatternAnalyzer(n, m);
            analyzer.readGrid(reader);
            analyzer.calculateCrossRadii();
            analyzer.analyzeAndPrint();
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.ArrayList;
import java.util.List;
import java.util.StringTokenizer;

public class CFA {
    public static void main(String[] args) {
        FastScanner scanner = new FastScanner();
        PrintWriter out = new PrintWriter(System.out);
        try {
            new CFA().solve(scanner, out);
        } finally {
            out.flush();
            out.close();
        }
    }

    /**
     * Solves the problem by identifying valid crosses in the grid.
     * A valid cross requires an arm length (radius) of at least 2.
     * If any '*' cell is not covered by a valid cross, outputs -1.
     */
    void solve(FastScanner scanner, PrintWriter out) {
        int n = scanner.nextInt();
        int m = scanner.nextInt();
        char[][] grid = new char[n][m];
        for (int i = 0; i < n; i++) {
            grid[i] = scanner.next().toCharArray();
        }

        List<int[]> crosses = new ArrayList<>();
        boolean[][] visited = new boolean[n][m];

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                // Only process unvisited '*' to avoid duplicate cross detection
                if (grid[i][j] == '*' && !visited[i][j]) {
                    int top = i;
                    while (top > 0 && grid[top - 1][j] == '*') top--;
                    int bottom = i;
                    while (bottom < n - 1 && grid[bottom + 1][j] == '*') bottom++;
                    int left = j;
                    while (left > 0 && grid[i][left - 1] == '*') left--;
                    int right = j;
                    while (right < m - 1 && grid[i][right + 1] == '*') right++;

                    // Calculate the maximum arm length from the center
                    int radius = Math.min(bottom - i, Math.min(i - top, Math.min(right - j, j - left)));

                    // A valid cross requires at least one cell in each direction from the center
                    if (radius <= 1) {
                        continue;
                    }

                    // Mark all cells of the cross as visited
                    for (int k = 0; k < radius; k++) {
                        visited[i + k][j] = true;
                        visited[i - k][j] = true;
                        visited[i][j + k] = true;
                        visited[i][j - k] = true;
                    }
                    crosses.add(new int[]{i + 1, j + 1, radius});
                }
            }
        }

        // Verify that every '*' in the grid belongs to a valid cross
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == '*' && !visited[i][j]) {
                    out.println(-1);
                    return;
                }
            }
        }

        out.println(crosses.size());
        for (int[] cross : crosses) {
            out.println(cross[0] + " " + cross[1] + " " + (cross[2] - 1));
        }
    }

    /**
     * Fast input reader optimized for competitive programming and bulk reads.
     */
    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        public String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input", e);
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            String token = next();
            if (token == null) {
                throw new RuntimeException("Unexpected end of input");
            }
            return Integer.parseInt(token);
        }
    }
}

import java.io.*;
import java.util.*;

public class Main {

    /**
     * Fast I/O helper for competitive programming.
     * Handles tokenization and IOExceptions gracefully.
     */
    static class FastReader {
        BufferedReader br;
        StringTokenizer st;

        public FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    e.printStackTrace();
                    return null;
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            String s = next();
            return s == null ? 0 : Integer.parseInt(s);
        }

        long nextLong() {
            String s = next();
            return s == null ? 0L : Long.parseLong(s);
        }

        double nextDouble() {
            String s = next();
            return s == null ? 0.0 : Double.parseDouble(s);
        }

        String nextLine() {
            String str = "";
            try {
                str = br.readLine();
            } catch (IOException e) {
                e.printStackTrace();
            }
            return str;
        }
    }

    /**
     * Represents a valid cross shape found in the grid.
     */
    static class Cross {
        final int row;
        final int col;
        final int arm;

        Cross(int row, int col, int arm) {
            this.row = row;
            this.col = col;
            this.arm = arm;
        }
    }

    public static void main(String[] args) {
        FastReader sc = new FastReader();
        PrintWriter out = new PrintWriter(System.out);

        // Original hardcoded t=1, kept loop structure for flexibility
        int t = 1;
        while (t-- > 0) {
            String nStr = sc.next();
            if (nStr == null) break;
            int n = Integer.parseInt(nStr);
            int m = sc.nextInt();

            // 1-based indexing for convenience to match original boundary logic
            char[][] grid = new char[n + 1][m + 1];
            for (int i = 1; i <= n; i++) {
                String line = sc.next();
                for (int j = 1; j <= m; j++) {
                    grid[i][j] = line.charAt(j - 1);
                }
            }

            // DP arrays to store consecutive '*' counts in 4 directions
            // Size n+2/m+2 prevents boundary checks during computation
            int[][] left = new int[n + 2][m + 2];
            int[][] up = new int[n + 2][m + 2];
            int[][] right = new int[n + 2][m + 2];
            int[][] down = new int[n + 2][m + 2];

            // Pass 1: Compute consecutive '*' counts moving Left and Up
            for (int i = 1; i <= n; i++) {
                for (int j = 1; j <= m; j++) {
                    if (grid[i][j] == '*') {
                        left[i][j] = 1 + left[i][j - 1];
                        up[i][j] = 1 + up[i - 1][j];
                    }
                }
            }

            // Pass 2: Compute consecutive '*' counts moving Right and Down
            for (int i = n; i >= 1; i--) {
                for (int j = m; j >= 1; j--) {
                    if (grid[i][j] == '*') {
                        right[i][j] = 1 + right[i][j + 1];
                        down[i][j] = 1 + down[i + 1][j];
                    }
                }
            }

            List<Cross> crosses = new ArrayList<>();
            boolean[][] covered = new boolean[n + 2][m + 2];

            // Identify valid crosses and mark covered cells
            for (int i = 1; i <= n; i++) {
                for (int j = 1; j <= m; j++) {
                    if (grid[i][j] == '*') {
                        // The arm length is limited by the shortest direction
                        int minConsecutive = Math.min(left[i][j], Math.min(right[i][j], Math.min(up[i][j], down[i][j])));

                        // Arm length must be at least 1 to form a valid cross (minConsecutive > 1 means arm >= 1)
                        if (minConsecutive > 1) {
                            int armLength = minConsecutive - 1;
                            crosses.add(new Cross(i, j, armLength));

                            // Mark the center and 4 arms as covered
                            covered[i][j] = true;
                            for (int k = 1; k <= armLength; k++) {
                                covered[i - k][j] = true;
                                covered[i + k][j] = true;
                                covered[i][j - k] = true;
                                covered[i][j + k] = true;
                            }
                        }
                    }
                }
            }

            // Verify that all '.' cells are covered by at least one cross
            boolean allDotsCovered = true;
            for (int i = 1; i <= n; i++) {
                for (int j = 1; j <= m; j++) {
                    if (grid[i][j] == '.' && !covered[i][j]) {
                        allDotsCovered = false;
                        break;
                    }
                }
                if (!allDotsCovered) break;
            }

            if (!allDotsCovered) {
                out.println("-1");
            } else {
                out.println(crosses.size());
                for (Cross c : crosses) {
                    out.println(c.row + " " + c.col + " " + c.arm);
                }
            }
        }

        out.flush();
        out.close();
    }
}

import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) {
        FastScanner sc = new FastScanner();
        PrintWriter pw = new PrintWriter(System.out);
        try {
            solve(sc, pw);
        } finally {
            pw.flush();
        }
    }

    private static void solve(FastScanner sc, PrintWriter pw) {
        int N = sc.ni();
        int M = sc.ni();

        boolean[][] grid = readGrid(sc, N, M);

        // Data structures to store column indices of stars per row, and their local order
        List<List<Integer>> rowStarCols = new ArrayList<>(N);
        List<Map<Integer, Integer>> rowStarIndexMap = new ArrayList<>(N);
        for (int i = 0; i < N; i++) {
            rowStarCols.add(new ArrayList<>());
            rowStarIndexMap.add(new HashMap<>());
        }

        // Data structures to store row indices of stars per column, and their local order
        List<List<Integer>> colStarRows = new ArrayList<>(M);
        List<Map<Integer, Integer>> colStarIndexMap = new ArrayList<>(M);
        for (int j = 0; j < M; j++) {
            colStarRows.add(new ArrayList<>());
            colStarIndexMap.add(new HashMap<>());
        }

        // Populate indices
        for (int i = 0; i < N; i++) {
            int idx = 0;
            for (int j = 0; j < M; j++) {
                if (grid[i][j]) {
                    rowStarCols.get(i).add(j);
                    rowStarIndexMap.get(i).put(j, idx++);
                }
            }
        }

        for (int j = 0; j < M; j++) {
            int idx = 0;
            for (int i = 0; i < N; i++) {
                if (grid[i][j]) {
                    colStarRows.get(j).add(i);
                    colStarIndexMap.get(j).put(i, idx++);
                }
            }
        }

        // Initialize Fenwick Trees (Binary Indexed Trees) for range updates
        FenwickTree[] rowBITs = new FenwickTree[N];
        FenwickTree[] colBITs = new FenwickTree[M];
        for (int i = 0; i < N; i++) rowBITs[i] = new FenwickTree(M);
        for (int j = 0; j < M; j++) colBITs[j] = new FenwickTree(N);

        List<Star> stars = new ArrayList<>();

        // Process each star to calculate coverage size and update BITs
        for (int i = 0; i < N; i++) {
            for (int j = 0; j < M; j++) {
                if (grid[i][j]) {
                    int rowIdx = rowStarIndexMap.get(i).get(j);
                    int colIdx = colStarIndexMap.get(j).get(i);

                    int left = findContiguousExtent(rowStarCols.get(i), rowIdx, true);
                    int right = findContiguousExtent(rowStarCols.get(i), rowIdx, false);
                    int up = findContiguousExtent(colStarRows.get(j), colIdx, true);
                    int down = findContiguousExtent(colStarRows.get(j), colIdx, false);

                    int size = Math.min(Math.min(left, right), Math.min(up, down));
                    if (size > 0) {
                        stars.add(new Star(i, j, size));
                        // Range update: add 1 to [j-size, j+size]
                        rowBITs[i].update(j - size, 1);
                        rowBITs[i].update(j + size + 1, -1);
                        // Range update: add 1 to [i-size, i+size]
                        colBITs[j].update(i - size, 1);
                        colBITs[j].update(i + size + 1, -1);
                    }
                }
            }
        }

        if (isValidGrid(grid, rowBITs, colBITs)) {
            pw.println(stars.size());
            for (Star star : stars) {
                pw.println(star);
            }
        } else {
            pw.println(-1);
        }
    }

    private static boolean[][] readGrid(FastScanner sc, int N, int M) {
        boolean[][] grid = new boolean[N][M];
        for (int i = 0; i < N; i++) {
            String line = sc.next();
            for (int j = 0; j < M; j++) {
                grid[i][j] = line.charAt(j) == '*';
            }
        }
        return grid;
    }

    /**
     * Finds the length of the contiguous segment of indices around localIdx.
     * If searchLeft is true, finds how far left the contiguous segment extends.
     * Otherwise, finds how far right it extends.
     */
    private static int findContiguousExtent(List<Integer> indices, int localIdx, boolean searchLeft) {
        int val = indices.get(localIdx);
        int low, high;
        if (searchLeft) {
            low = 0;
            high = localIdx;
            while (low < high) {
                int mid = (low + high) >>> 1;
                // Check if indices are consecutive: indices[mid] should be val - (localIdx - mid)
                if (indices.get(mid) == val - (localIdx - mid)) {
                    high = mid;
                } else {
                    low = mid + 1;
                }
            }
            return localIdx - low;
        } else {
            low = localIdx;
            high = indices.size() - 1;
            while (low < high) {
                int mid = (low + high + 1) >>> 1;
                // Check if indices are consecutive: indices[mid] should be val + (mid - localIdx)
                if (indices.get(mid) == val + (mid - localIdx)) {
                    low = mid;
                } else {
                    high = mid - 1;
                }
            }
            return low - localIdx;
        }
    }

    private static boolean isValidGrid(boolean[][] grid, FenwickTree[] rowBITs, FenwickTree[] colBITs) {
        for (int i = 0; i < grid.length; i++) {
            for (int j = 0; j < grid[i].length; j++) {
                if (grid[i][j]) {
                    // A star is valid only if it's covered by at least one interval in both dimensions
                    if (rowBITs[i].query(j) == 0 && colBITs[j].query(i) == 0) {
                        return false;
                    }
                }
            }
        }
        return true;
    }

    /**
     * Standard Fenwick Tree (Binary Indexed Tree) implementation.
     * Supports point query and range update via difference array technique.
     */
    static class FenwickTree {
        private final int[] tree;

        public FenwickTree(int size) {
            this.tree = new int[size + 2]; // +2 for safe 1-based indexing
        }

        public void update(int idx, int delta) {
            idx++; // Convert 0-based index to 1-based
            while (idx < tree.length) {
                tree[idx] += delta;
                idx += idx & (-idx);
            }
        }

        public int query(int idx) {
            idx++; // Convert 0-based index to 1-based
            int sum = 0;
            while (idx > 0) {
                sum += tree[idx];
                idx -= idx & (-idx);
            }
            return sum;
        }
    }

    static class Star {
        final int row;
        final int col;
        final int size;

        Star(int row, int col, int size) {
            this.row = row;
            this.col = col;
            this.size = size;
        }

        @Override
        public String toString() {
            // Output uses 1-based indexing as per original logic
            return (row + 1) + " " + (col + 1) + " " + size;
        }
    }

    static class FastScanner {
        BufferedReader br;
        StringTokenizer st;

        public FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
            return st.nextToken();
        }

        int ni() {
            String s = next();
            return s == null ? 0 : Integer.parseInt(s);
        }

        long nl() {
            String s = next();
            return s == null ? 0L : Long.parseLong(s);
        }

        double nd() {
            String s = next();
            return s == null ? 0.0 : Double.parseDouble(s);
        }

        String nextLine() {
            String str = "";
            try {
                str = br.readLine();
            } catch (IOException e) {
                e.printStackTrace();
            }
            return str;
        }
    }
}

import java.io.*;
import java.util.*;

public class Main {

    /** Represents a star pattern found in the grid. */
    static class Star {
        final int row, col, armLength;

        Star(int row, int col, int armLength) {
            this.row = row;
            this.col = col;
            this.armLength = armLength;
        }
    }

    /** Stores the number of consecutive stars in each direction from a cell. */
    static class Count {
        int left, right, top, bottom;
