    public static void main(String[] args) {
        FastScanner in = new FastScanner(System.in);
        FastOutput out = new FastOutput(System.out);
        try {
            new Main().run(in, out);
        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    /** Orchestrates the main execution flow. */
    public void run(FastScanner in, FastOutput out) {
        int n = in.nextInt();
        int m = in.nextInt();

        boolean[][] grid = readGrid(in, n, m);
        Count[][] counts = computeCounts(grid, n, m);
        int[][] vertDiff = new int[n][m];
        int[][] horizDiff = new int[n][m];
        List<Star> stars = findStars(counts, grid, n, m, vertDiff, horizDiff);

        if (!validateGrid(grid, vertDiff, horizDiff, n, m)) {
            out.println("-1");
            return;
        }

        out.println(stars.size());
        for (Star star : stars) {
            out.print(star.row + 1, star.col + 1, star.armLength);
        }
        out.finish();
    }

    /** Reads the input grid into a boolean matrix. */
    private boolean[][] readGrid(FastScanner in, int n, int m) {
        boolean[][] grid = new boolean[n][m];
        for (int i = 0; i < n; i++) {
            String line = in.next();
            for (int j = 0; j < m; j++) {
                grid[i][j] = line.charAt(j) == '*';
            }
        }
        return grid;
    }

    /** Computes consecutive star counts in all four directions for each cell. */
    private Count[][] computeCounts(boolean[][] grid, int n, int m) {
        Count[][] counts = new Count[n][m];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                counts[i][j] = new Count();
            }
        }

        // Horizontal counts
        for (int i = 0; i < n; i++) {
            int consecutive = 0;
            for (int j = 0; j < m; j++) {
                counts[i][j].left = consecutive;
                if (grid[i][j]) {
                    consecutive++;
                } else {
                    consecutive = 0;
                }
            }
            consecutive = 0;
            for (int j = m - 1; j >= 0; j--) {
                counts[i][j].right = consecutive;
                if (grid[i][j]) {
                    consecutive++;
                } else {
                    consecutive = 0;
                }
            }
        }

        // Vertical counts
        for (int j = 0; j < m; j++) {
            int consecutive = 0;
            for (int i = 0; i < n; i++) {
                counts[i][j].top = consecutive;
                if (grid[i][j]) {
                    consecutive++;
                } else {
                    consecutive = 0;
                }
            }
            consecutive = 0;
            for (int i = n - 1; i >= 0; i--) {
                counts[i][j].bottom = consecutive;
                if (grid[i][j]) {
                    consecutive++;
                } else {
                    consecutive = 0;
                }
            }
        }
        return counts;
    }

    /** Identifies valid stars and updates difference arrays for coverage validation. */
    private List<Star> findStars(Count[][] counts, boolean[][] grid, int n, int m,
                                 int[][] vertDiff, int[][] horizDiff) {
        List<Star> stars = new ArrayList<>();
        for (int i = 1; i < n - 1; i++) {
            for (int j = 1; j < m - 1; j++) {
                if (!grid[i][j]) continue;

                Count c = counts[i][j];
                int armLength = Math.min(Math.min(Math.min(c.top, c.bottom), c.left), c.right);
                if (armLength < 1) continue;

                stars.add(new Star(i, j, armLength));

                // Update difference arrays for vertical coverage
                vertDiff[i - armLength][j]++;
                if (i + armLength + 1 < n) vertDiff[i + armLength + 1][j]--;

                // Update difference arrays for horizontal coverage
                horizDiff[i][j - armLength]++;
                if (j + armLength + 1 < m) horizDiff[i][j + armLength + 1]--;
            }
        }
        return stars;
    }

    /** Validates that the computed star coverage matches the original grid. */
    private boolean validateGrid(boolean[][] grid, int[][] vertDiff, int[][] horizDiff, int n, int m) {
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                // Compute prefix sums in-place
                if (i > 0) vertDiff[i][j] += vertDiff[i - 1][j];
                if (j > 0) horizDiff[i][j] += horizDiff[i][j - 1];

                boolean isCovered = vertDiff[i][j] + horizDiff[i][j] > 0;
                if (isCovered != grid[i][j]) {
                    return false;
                }
            }
        }
        return true;
    }
}

/** High-performance input scanner for competitive programming. */
class FastScanner {
    private final BufferedReader br;
    private StringTokenizer st;

    FastScanner(InputStream stream) {
        br = new BufferedReader(new InputStreamReader(stream));
    }

    FastScanner(File file) {
        try {
            br = new BufferedReader(new FileReader(file));
        } catch (FileNotFoundException e) {
            throw new RuntimeException(e);
        }
    }

    String next() {
        while (st == null || !st.hasMoreTokens()) {
            try {
                String line = br.readLine();
                if (line == null) throw new EOFException();
                st = new StringTokenizer(line);
            } catch (IOException e) {
                throw new RuntimeException(e);
            }
        }
        return st.nextToken();
    }

    int nextInt() {
        return Integer.parseInt(next());
    }

    long nextLong() {
        return Long.parseLong(next());
    }
}

/** High-performance output writer for competitive programming. */
class FastOutput {
    private final BufferedWriter bf;

    public FastOutput(OutputStream outputStream) {
        bf = new BufferedWriter(new OutputStreamWriter(outputStream));
    }

    public void print(Object s) {
        try {
            bf.write(s.toString());
        } catch (IOException e) {
            throw new RuntimeException(e);
        }
    }

    public void println(Object s) {
        print(s);
        print("\n");
    }

    public void print(Object... os) {
        printd(" ", os);
    }

    public void printd(String delimiter, Object... os) {
        for (Object o : os) {
            print(o);
            print(delimiter);
        }
    }

    public void flush() {
        try {
            bf.flush();
        } catch (IOException e) {
            throw new RuntimeException(e);
        }
    }

    public void close() {
        try {
            bf.close();
        } catch (IOException e) {
            throw new RuntimeException(e);
        }
    }

    public void finish() {
        flush();
        close();
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.ArrayList;
import java.util.List;
import java.util.StringTokenizer;

/**
 * Solves a grid-based star coverage problem.
 * Identifies maximal contiguous line segments of stars and verifies 
 * whether every star is covered by at least one segment.
 */
public class StarGridSolver {

    // Direction vectors: down, up, left, right
    private static final int[] DX = {1, -1, 0, 0};
    private static final int[] DY = {0, 0, -1, 1};

    public static void main(String[] args) {
        FastReader scanner = new FastReader();
        try (PrintWriter out = new PrintWriter(System.out)) {
            int n = scanner.nextInt();
            int m = scanner.nextInt();
            char[][] grid = new char[n][m];

            for (int i = 0; i < n; i++) {
                grid[i] = scanner.next().toCharArray();
            }

            solve(grid, n, m, out);
        }
    }

    /**
     * Core algorithm to find valid star lines and verify coverage.
     */
    private static void solve(char[][] grid, int n, int m, PrintWriter out) {
        int[][] coverageCount = new int[n][m];
        List<StarLine> validLines = new ArrayList<>();

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == '*') {
                    int maxExtension = 0;
                    boolean allDirectionsValid = true;

                    // Expand outward in all 4 directions until a boundary or non-star is hit
                    while (allDirectionsValid) {
                        maxExtension++;
                        for (int k = 0; k < 4; k++) {
                            allDirectionsValid &= isWithinBoundsAndStar(i, j, maxExtension, k, grid);
                        }
                        if (allDirectionsValid) {
                            for (int k = 0; k < 4; k++) {
                                int xNew = i + DX[k] * maxExtension;
                                int yNew = j + DY[k] * maxExtension;
                                coverageCount[xNew][yNew]++;
                            }
                        }
                    }

                    maxExtension--; // Step back to the last valid distance
                    if (maxExtension > 0) {
                        coverageCount[i][j]++;
                        validLines.add(new StarLine(i + 1, j + 1, maxExtension));
                    }
                }
            }
        }

        // Verify every star is covered by at least one line
        boolean allStarsCovered = true;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == '*' && coverageCount[i][j] == 0) {
                    allStarsCovered = false;
                    break;
                }
            }
            if (!allStarsCovered) break;
        }

        if (!allStarsCovered) {
            out.println(-1);
        } else {
            out.println(validLines.size());
            for (StarLine line : validLines) {
                out.println(line.row + " " + line.col + " " + line.length);
            }
        }
    }

    /**
     * Checks if a cell at a given directional offset is within bounds and contains a star.
     */
    private static boolean isWithinBoundsAndStar(int x, int y, int curr, int d, char[][] grid) {
        int xNew = x + DX[d] * curr;
        int yNew = y + DY[d] * curr;

        return xNew >= 0 && xNew < grid.length &&
               yNew >= 0 && yNew < grid[0].length &&
               grid[xNew][yNew] == '*';
    }

    /**
     * Represents a contiguous line segment of stars.
     * Coordinates are 1-based to match competitive programming output conventions.
     */
    private static class StarLine {
        final int row;
        final int col;
        final int length;

        StarLine(int row, int col, int length) {
            this.row = row;
            this.col = col;
            this.length = length;
        }
    }

    /**
     * Optimized fast I/O reader for competitive programming and large inputs.
     */
    static class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) {
                        throw new IOException("End of input stream");
                    }
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        long nextLong() {
            return Long.parseLong(next());
        }

        int[] readArray(int n) {
            int[] arr = new int[n];
            for (int i = 0; i < n; i++) {
                arr[i] = nextInt();
            }
            return arr;
        }
    }
}

import java.io.PrintWriter;
import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

public class Main {
    private static final char EMPTY_CELL = '.';

    private final int rows;
    private final int cols;
    private final char[][] grid;
    private final boolean[][] covered;
    private final List<Star> foundStars;
    private final Scanner scanner;
    private final PrintWriter printer;

    /**
     * Initializes the processor with input/output streams and reads the grid.
     */
    public Main(Scanner scanner, PrintWriter printer) {
        this.scanner = scanner;
        this.printer = printer;
        this.rows = scanner.nextInt();
        this.cols = scanner.nextInt();
        this.grid = new char[rows][cols];
        this.covered = new boolean[rows][cols];
        this.foundStars = new ArrayList<>();
        readGrid();
    }

    /**
     * Reads the grid from input and marks initially empty cells as covered.
     */
    private void readGrid() {
        scanner.nextLine(); // Consume the rest of the first line after reading dimensions
        for (int i = 0; i < rows; i++) {
            String line = scanner.nextLine();
            grid[i] = line.toCharArray();
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == EMPTY_CELL) {
                    covered[i][j] = true;
                }
            }
        }
    }

    /**
     * Processes the grid to find and mark stars using a greedy approach.
     */
    public void process() {
        for (int i = 1; i < rows - 1; i++) {
            for (int j = 1; j < cols - 1; j++) {
                if (grid[i][j] == EMPTY_CELL) continue;
                int maxLength = calculateMaxStarLength(i, j);
                if (maxLength > 0) {
                    markStar(i, j, maxLength);
                }
            }
        }
    }

    /**
     * Calculates the maximum possible length of a star centered at (row, col).
     */
    private int calculateMaxStarLength(int row, int col) {
        int maxPossible = Math.min(Math.min(row, col),
                                   Math.min(rows - 1 - row, cols - 1 - col));
        int currentLen = 0;
        for (int i = 1; i <= maxPossible; i++) {
            if (grid[row - i][col] == EMPTY_CELL ||
                grid[row + i][col] == EMPTY_CELL ||
                grid[row][col - i] == EMPTY_CELL ||
                grid[row][col + i] == EMPTY_CELL) {
                break;
            }
            currentLen = i;
        }
        return currentLen;
    }

    /**
     * Records a star and marks all its cells as covered.
     */
    private void markStar(int row, int col, int length) {
        foundStars.add(new Star(row + 1, col + 1, length));
        covered[row][col] = true;
        for (int i = 1; i <= length; i++) {
            covered[row + i][col] = true;
            covered[row - i][col] = true;
            covered[row][col + i] = true;
            covered[row][col - i] = true;
        }
    }

    /**
     * Checks if all cells are covered and prints the result.
     */
    public void printResult() {
        boolean allCovered = true;
        outerLoop:
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (!covered[i][j]) {
                    allCovered = false;
                    break outerLoop;
                }
            }
        }

        if (allCovered) {
            printer.println(foundStars.size());
            for (Star star : foundStars) {
                printer.println(star);
            }
        } else {
            printer.println(-1);
        }
    }

    public static void main(String[] args) {
        // Use try-with-resources for automatic and safe resource cleanup
        try (Scanner scanner = new Scanner(System.in);
             PrintWriter printer = new PrintWriter(System.out)) {
            Main processor = new Main(scanner, printer);
            processor.process();
            processor.printResult();
        }
    }

    /**
     * Represents a found star with its 1-based coordinates and arm length.
     */
    private static class Star {
        final int row;
        final int col;
        final int length;

        Star(int row, int col, int length) {
            this.row = row;
            this.col = col;
            this.length = length;
        }

        @Override
        public String toString() {
            return row + " " + col + " " + length;
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

/**
 * Refactored version of the original Grid Processor.
 * Improvements:
 * 1. Descriptive class and variable names.
 * 2. Encapsulation of logic into methods (SOLID principles).
 * 3. Removal of static global state.
 * 4. Cleaner Input/Output handling using standard libraries and a helper class.
 * 5. Removed complex label-based control flow in favor of structured loops.
 */
public class GridProcessor {

    // Directions: Up, Down, Left, Right
    private static final int[] DR = {-1, 1, 0, 0};
    private static final int[] DC = {0, 0, -1, 1};

    public static void main(String[] args) {
        // Use try-with-resources for automatic resource management
        try (FastScanner sc = new FastScanner(System.in);
             PrintWriter out = new PrintWriter(System.out)) {

            String nStr = sc.next();
            if (nStr != null) {
                int rows = Integer.parseInt(nStr);
                int cols = sc.nextInt();

                char[][] grid = new char[rows][cols];
                for (int i = 0; i < rows; i++) {
                    String line = sc.nextLine();
                    if (line != null) {
                        grid[i] = line.toCharArray();
                    }
                }

                solve(grid, rows, cols, out);
            }
        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    /**
     * Main logic to process the grid.
     */
    private static void solve(char[][] grid, int rows, int cols, PrintWriter out) {
        boolean[][] covered = new boolean[rows][cols];
        int validPointsCount = 0;
        StringBuilder outputBuilder = new StringBuilder();

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                // Skip empty cells
                if (grid[r][c] == '.') {
                    continue;
                }

                // Find the maximum radius where the cross shape is valid
                int maxRadius = findMaxRadius(grid, r, c, rows, cols);

                if (maxRadius > 0) {
                    validPointsCount++;
                    // 1-based indexing for output
                    outputBuilder.append(r + 1).append(" ")
                                 .append(c + 1).append(" ")
                                 .append(maxRadius).append("\n");

                    // Mark the area as covered
                    markCovered(covered, r, c, maxRadius);
                }
            }
        }

        // Verify all '*' are covered
        if (!isFullyCovered(grid, covered)) {
            out.println(-1);
            return;
        }

        out.println(validPointsCount);
        out.print(outputBuilder);
    }

    /**
     * Calculates the maximum radius for a valid cross shape centered at (r, c).
     */
    private static int findMaxRadius(char[][] grid, int r, int c, int rows, int cols) {
        // Optimization: Calculate max possible radius based on boundaries
        // Distance to top edge is r, bottom edge is rows - 1 - r
        // Distance to left edge is c, right edge is cols - 1 - c
        int maxPossibleRadius = Math.min(Math.min(r, rows - 1 - r), Math.min(c, cols - 1 - c));

        int radius = 0;
        for (int dist = 1; dist <= maxPossibleRadius; dist++) {
            boolean valid = true;
            for (int k = 0; k < 4; k++) {
                int nr = r + DR[k] * dist;
                int nc = c + DC[k] * dist;

                // Bounds check (redundant due to optimization but safe)
                if (nr < 0 || nr >= rows || nc < 0 || nc >= cols) {
                    valid = false;
                    break;
                }

                // Check if cell is empty
                if (grid[nr][nc] == '.') {
                    valid = false;
                    break;
                }
            }

            if (valid) {
                radius = dist;
            } else {
                break; // Cannot extend further
            }
        }
        return radius;
    }

    /**
     * Marks the center and all points along the 4 directions up to radius as covered.
     */
    private static void markCovered(boolean[][] covered, int r, int c, int radius) {
        for (int k = 0; k <= radius; k++) {
            for (int dir = 0; dir < 4; dir++) {
                int nr = r + DR[dir] * k;
                int nc = c + DC[dir] * k;

                if (nr >= 0 && nr < covered.length && nc >= 0 && nc < covered[0].length) {
                    covered[nr][nc] = true;
                }
            }
        }
    }

    /**
     * Checks if all '*' cells in the grid are covered.
     */
    private static boolean isFullyCovered(char[][] grid, boolean[][] covered) {
        for (int r = 0; r < grid.length; r++) {
            for (int c = 0; c < grid[0].length; c++) {
                if (grid[r][c] == '*' && !covered[r][c]) {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Helper class for fast input reading.
     */
    static class FastScanner {
        BufferedReader br;
        StringTokenizer st;

        public FastScanner(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            String s = next();
            if (s == null) throw new RuntimeException("End of input");
            return Integer.parseInt(s);
        }

        String nextLine() {
            try {
                return br.readLine();
            } catch (IOException e) {
                return null;
            }
        }
    }
}

import java.io.*;
import java.util.*;

public class GridPlacementSolver {

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out));

        try {
            solve(scanner, out);
        } finally {
            out.flush();
        }
    }

    /**
     * Core solver logic: reads input, processes grid, and writes output.
     */
    private static void solve(FastScanner scanner, PrintWriter out) {
        if (!scanner.hasMoreTokens()) return;

        int n = scanner.nextInt();
        int m = scanner.nextInt();

        char[][] grid = new char[n][];
        for (int i = 0; i < n; i++) {
            grid[i] = scanner.next().toCharArray();
        }

        // Step 1: Compute minimum distance to nearest '*' in each of the 4 cardinal directions
        int[][] distances = computeDirectionalDistances(grid, n, m);

        // Step 2: Mark cells covered by valid placements using difference arrays
        applyDifferenceArrays(grid, distances, n, m);

        // Step 3: Verify no '*' remains after marking covered cells
        if (gridContainsStar(grid, n, m)) {
            out.println(-1);
            return;
        }

        // Step 4: Collect and output valid placements
        List<String> validPlacements = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (distances[i][j] > 1) {
                    validPlacements.add((i + 1) + " " + (j + 1) + " " + (distances[i][j] - 1));
                }
            }
        }

        out.println(validPlacements.size());
        for (String placement : validPlacements) {
            out.println(placement);
        }
    }

    /**
     * Computes the minimum distance to a '*' in the up, down, left, and right directions for each cell.
     */
    private static int[][] computeDirectionalDistances(char[][] grid, int n, int m) {
        int[][] distances = new int[n][m];
        int maxPossibleDist = Math.max(n, m) + 1;
        for (int[] row : distances) {
            Arrays.fill(row, maxPossibleDist);
        }

        // Left pass
        for (int i = 0; i < n; i++) {
            int count = 0;
            for (int j = 0; j < m; j++) {
                count = grid[i][j] == '*' ? 0 : count + 1;
                distances[i][j] = Math.min(distances[i][j], count);
            }
        }

        // Right pass
        for (int i = 0; i < n; i++) {
            int count = 0;
            for (int j = m - 1; j >= 0; j--) {
                count = grid[i][j] == '*' ? 0 : count + 1;
                distances[i][j] = Math.min(distances[i][j], count);
            }
        }

        // Up pass
        for (int j = 0; j < m; j++) {
            int count = 0;
            for (int i = 0; i < n; i++) {
                count = grid[i][j] == '*' ? 0 : count + 1;
                distances[i][j] = Math.min(distances[i][j], count);
            }
        }

        // Down pass
        for (int j = 0; j < m; j++) {
            int count = 0;
            for (int i = n - 1; i >= 0; i--) {
                count = grid[i][j] == '*' ? 0 : count + 1;
                distances[i][j] = Math.min(distances[i][j], count);
            }
        }

        return distances;
    }

    /**
     * Uses a difference array technique to mark cells that are covered by the radius
     * of any valid placement (distance > 1). Covered cells are set to '.'.
     */
    private static void applyDifferenceArrays(char[][] grid, int[][] distances, int n, int m) {
        int[] diff = new int[Math.max(n, m) + 2];

        // Process horizontal ranges (rows)
        for (int i = 0; i < n; i++) {
            Arrays.fill(diff, 0);
            for (int j = 0; j < m; j++) {
                int k = distances[i][j];
                if (k > 1) {
                    int left = Math.max(0, j - k + 1);
                    int right = Math.min(m - 1, j + k - 1);
                    diff[left]++;
                    diff[right + 1]--;
                }
            }
            int current = 0;
            for (int j = 0; j < m; j++) {
                current += diff[j];
                if (current > 0) {
                    grid[i][j] = '.';
                }
            }
        }

        // Process vertical ranges (columns)
        for (int j = 0; j < m; j++) {
            Arrays.fill(diff, 0);
            for (int i = 0; i < n; i++) {
                int k = distances[i][j];
                if (k > 1) {
                    int top = Math.max(0, i - k + 1);
                    int bottom = Math.min(n - 1, i + k - 1);
                    diff[top]++;
                    diff[bottom + 1]--;
                }
            }
            int current = 0;
            for (int i = 0; i < n; i++) {
                current += diff[i];
                if (current > 0) {
                    grid[i][j] = '.';
                }
            }
        }
    }

    /**
     * Checks if the grid still contains any '*' characters.
     */
    private static boolean gridContainsStar(char[][] grid, int n, int m) {
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == '*') {
                    return true;
                }
            }
        }
        return false;
    }

    /**
     * A lightweight fast scanner for efficient input reading.
     */
    private static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        boolean hasMoreTokens() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return false;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return true;
        }

        String next() {
            if (hasMoreTokens()) return st.nextToken();
            throw new NoSuchElementException();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.ArrayList;
import java.util.List;
import java.util.StringTokenizer;

/**
 * Refactored solution for finding cross patterns in a grid.
 * 
 * Improvements made:
 * 1. Naming Conventions: Renamed variables and methods to be descriptive (e.g., 'grid' instead of 'a', 'visited' instead of 'v').
 * 2. Code Cleanup: Removed unused methods (modular arithmetic, unused parsers) and constants.
 * 3. Structure: Encapsulated Fast I/O logic cleanly.
 * 4. Logic Clarity: Simplified the cross-expansion loop and coordinate handling.
 * 5. Resource Management: Ensured PrintWriter is flushed and closed properly.
 */
public class Main {
    // Fast I/O components
    private static final BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
    private static PrintWriter writer = new PrintWriter(System.out);
    private static StringTokenizer tokenizer;

    /**
     * Reads the next token from the input.
     * @return The next token string.
     */
    private static String next() {
        while (tokenizer == null || !tokenizer.hasMoreTokens()) {
            try {
                String line = reader.readLine();
                if (line == null) {
                    return null;
                }
                tokenizer = new StringTokenizer(line);
            } catch (IOException e) {
                throw new RuntimeException("Error reading input", e);
            }
        }
        return tokenizer.nextToken();
    }

    /**
     * Reads the next integer from the input.
     * @return The next integer.
     */
    private static int nextInt() {
        String s = next();
        if (s == null) {
            throw new RuntimeException("End of input reached unexpectedly");
        }
        return Integer.parseInt(s);
    }

    public static void main(String[] args) {
        try {
            solve();
        } catch (Exception e) {
            // In a real application, handle exceptions properly.
            // For CP/Scripting, printing stack trace or ignoring is common.
            e.printStackTrace();
        } finally {
            writer.flush();
            writer.close();
        }
    }

    private static void solve() {
        // Read grid dimensions
        // Note: The original code had a loop for test cases hardcoded to 1.
        // We execute the logic once.
        int n = nextInt();
        int m = nextInt();

        char[][] grid = new char[n][m];
        for (int i = 0; i < n; i++) {
            String row = next();
            grid[i] = row.toCharArray();
        }

        boolean[][] visited = new boolean[n][m];
        List<int[]> foundCrosses = new ArrayList<>();

        // Iterate through the grid to find potential cross centers
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                // We only care about asterisks.
                // The original code skipped '.', effectively treating any non-'.' as a candidate,
                // but logic relied on '*' checks. Explicit check is safer.
                if (grid[i][j] != '*') {
                    continue;
                }

                // Attempt to expand a cross centered at (i, j)
                int span = 0;

                // Initial neighbors
                int upRow = i - 1;
                int downRow = i + 1;
                int leftCol = j - 1;
                int rightCol = j + 1;

                // Expand outwards as long as all 4 directions contain '*'
                while (true) {
                    boolean upValid = (upRow >= 0 && grid[upRow][j] == '*');
                    boolean downValid = (downRow < n && grid[downRow][j] == '*');
                    boolean leftValid = (leftCol >= 0 && grid[i][leftCol] == '*');
                    boolean rightValid = (rightCol < m && grid[i][rightCol] == '*');

                    if (upValid && downValid && leftValid && rightValid) {
                        span++;

                        // Mark the center and the 4 arms as visited
                        visited[i][j] = true;
                        visited[upRow][j] = true;
                        visited[downRow][j] = true;
                        visited[i][leftCol] = true;
                        visited[i][rightCol] = true;

                        // Move to next layer
                        upRow--;
                        downRow++;
                        leftCol--;
                        rightCol++;
                    } else {
                        // Cannot expand further
                        break;
                    }
                }

                // If a valid cross (radius >= 1) was found
                if (span > 0) {
                    // Store result: row, col, span. 
                    // Output requires 1-based indexing.
                    foundCrosses.add(new int[]{i + 1, j + 1, span});
                }
            }
        }

        // Validation: Every '*' in the grid must have been visited (part of a found cross)
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == '*' && !visited[i][j]) {
                    writer.println("-1");
                    return;
                }
            }
        }

        // Output results
        writer.println(foundCrosses.size());
        for (int[] cross : foundCrosses) {
            writer.println(cross[0] + " " + cross[1] + " " + cross[2]);
        }
    }
}

import java.util.Scanner;

public class GridCrossProcessor {
    // Constants to replace magic characters and improve readability
    private static final char EMPTY_CELL = '.';
    private static final char MARKED_CELL = '#';
    private static final char TARGET_CELL = '*';

    private final int rows;
    private final int cols;
    private final char[][] grid;
    private final StringBuilder output;

    public GridCrossProcessor(int rows, int cols, char[][] grid) {
        this.rows = rows;
        this.cols = cols;
        this.grid = grid;
        this.output = new StringBuilder();
    }

    /**
     * Processes the grid to find and mark valid cross patterns.
     * @return The number of crosses found.
     */
    public int process() {
        int crossCount = 0;
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == EMPTY_CELL) {
                    continue;
                }

                int maxLevel = findMaxCrossLevel(i, j);
                if (maxLevel == 0) {
                    continue;
                }

                crossCount++;
                output.append(i + 1).append(" ")
                      .append(j + 1).append(" ")
                      .append(maxLevel).append("\n");
                markCross(i, j, maxLevel);
            }
        }
        return crossCount;
    }

    /**
     * Determines the maximum valid cross level centered at (i, j).
     */
    private int findMaxCrossLevel(int i, int j) {
        int level = 0;
        while (isValidCrossAt(i, j, level + 1)) {
            level++;
        }
        return level;
    }

    /**
     * Checks if a cross of size k is valid at (i, j).
     * A cross is valid if all four directional endpoints are within bounds
     * and contain either a target '*' or a previously marked '#'.
     */
    private boolean isValidCrossAt(int i, int j, int k) {
        if (i - k < 0 || i + k >= rows || j - k < 0 || j + k >= cols) {
            return false;
        }
        return isTargetOrMarked(i - k, j) &&
               isTargetOrMarked(i + k, j) &&
               isTargetOrMarked(i, j - k) &&
               isTargetOrMarked(i, j + k);
    }

    /**
     * Helper to check if a cell is a target or already marked.
     */
    private boolean isTargetOrMarked(int r, int c) {
        char cell = grid[r][c];
        return cell == TARGET_CELL || cell == MARKED_CELL;
    }

    /**
     * Marks all cells involved in a cross of the given level.
     */
    private void markCross(int i, int j, int level) {
        for (int k = 0; k <= level; k++) {
            grid[i - k][j] = MARKED_CELL;
            grid[i + k][j] = MARKED_CELL;
            grid[i][j - k] = MARKED_CELL;
            grid[i][j + k] = MARKED_CELL;
        }
    }

    /**
     * Validates that no target cells remain unmarked after processing.
     */
    public boolean hasRemainingTargets() {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == TARGET_CELL) {
                    return true;
                }
            }
        }
        return false;
    }

    /**
     * Returns the formatted output string generated during processing.
     */
    public String getOutput() {
        return output.toString();
    }

    public static void main(String[] args) {
        // Use try-with-resources for automatic resource management
        try (Scanner scanner = new Scanner(System.in)) {
            if (!scanner.hasNextInt()) {
                return;
            }
            int n = scanner.nextInt();
            int m = scanner.nextInt();

            char[][] grid = new char[n][m];
            for (int i = 0; i < n; i++) {
                grid[i] = scanner.next().toCharArray();
            }

            GridCrossProcessor processor = new GridCrossProcessor(n, m, grid);
            int ans = processor.process();

            if (processor.hasRemainingTargets()) {
                System.out.println(-1);
            } else {
                System.out.println(ans);
                System.out.print(processor.getOutput());
            }
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.ArrayList;
import java.util.InputMismatchException;
import java.util.List;
import java.util.StringTokenizer;

/**
 * Solves the star grid coverage problem.
 * Identifies maximal square stars centered at '*' cells and verifies
 * if all '*' cells are covered by at least one star using a 2D difference array technique.
 */
public class StarGridCoverage {

    /**
     * Represents a star with its center coordinates and size.
     * Coordinates are stored as 1-based for output compatibility.
     */
    private static class Star {
        final int row;
        final int col;
        final int size;

        Star(int row, int col, int size) {
            this.row = row;
            this.col = col;
            this.size = size;
        }

        void display(PrintWriter out) {
            out.println(row + " " + col + " " + size);
        }
    }

    public static void main(String[] args) {
        // Use try-with-resources for automatic and safe resource management
        try (FastScanner scanner = new FastScanner(System.in);
             PrintWriter out = new PrintWriter(System.out)) {
            solve(scanner, out);
            out.flush();
        } catch (Exception e) {
            // In competitive programming contexts, unexpected EOF or malformed input
            // typically results in termination. Production code would log this properly.
        }
    }

    private static void solve(FastScanner scanner, PrintWriter out) {
        int n = scanner.nextInt();
        int m = scanner.nextInt();
        char[][] grid = readGrid(scanner, n, m);

        // Compute contiguous '*' segments in four directions
        int[][] up = computeDirection(grid, n, m, -1, 0);
        int[][] down = computeDirection(grid, n, m, 1, 0);
        int[][] left = computeDirection(grid, n, m, 0, -1);
        int[][] right = computeDirection(grid, n, m, 0, 1);

        List<Star> stars = new ArrayList<>();
        int[][] rowDiff = new int[n][m];
        int[][] colDiff = new int[n][m];

        // Identify valid stars and apply difference array updates
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == '*') {
                    int size = Math.min(Math.min(left[i][j], right[i][j]),
                                        Math.min(up[i][j], down[i][j]));
                    if (size > 0) {
                        // Store with 1-based indexing for output
                        stars.add(new Star(i + 1, j + 1, size));

                        // Update horizontal difference array
                        rowDiff[i][j - size]++;
                        if (j + size + 1 < m) {
                            rowDiff[i][j + size + 1]--;
                        }

                        // Update vertical difference array
                        colDiff[i - size][j]++;
                        if (i + size + 1 < n) {
                            colDiff[i + size + 1][j]--;
                        }
                    }
                }
            }
        }

        // Compute prefix sums to resolve difference arrays into actual coverage counts
        for (int i = 0; i < n; i++) {
            for (int j = 1; j < m; j++) {
                rowDiff[i][j] += rowDiff[i][j - 1];
            }
        }

        for (int j = 0; j < m; j++) {
            for (int i = 1; i < n; i++) {
                colDiff[i][j] += colDiff[i - 1][j];
            }
        }

        // Verify if all '*' cells are covered by at least one star's span
        boolean isCovered = true;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == '*' && colDiff[i][j] <= 0 && rowDiff[i][j] <= 0) {
                    isCovered = false;
                    break;
                }
            }
            if (!isCovered) break;
        }

        if (!isCovered) {
            out.println(-1);
        } else {
            out.println(stars.size());
            for (Star star : stars) {
                star.display(out);
            }
        }
    }

    private static char[][] readGrid(FastScanner scanner, int n, int m) {
        char[][] grid = new char[n][m];
        for (int i = 0; i < n; i++) {
            grid[i] = scanner.next().toCharArray();
        }
        return grid;
    }

    /**
     * Computes the length of contiguous '*' segments ending at each cell
     * in the specified direction.
     *
     * @param dRow Row step (-1 for up, 1 for down, 0 otherwise)
     * @param dCol Column step (-1 for left, 1 for right, 0 otherwise)
     */
    private static int[][] computeDirection(char[][] grid, int n, int m, int dRow, int dCol) {
        int[][] dir = new int[n][m];
        int startRow = dRow < 0 ? n - 1 : 0;
        int endRow = dRow < 0 ? -1 : n;
        int stepRow = dRow;
        int startCol = dCol < 0 ? m - 1 : 0;
        int endCol = dCol < 0 ? -1 : m;
        int stepCol = dCol;

        for (int i = startRow; i != endRow; i += stepRow) {
            for (int j = startCol; j != endCol; j += stepCol) {
                if (grid[i][j] == '*') {
                    int prevI = i - dRow;
                    int prevJ = j - dCol;
                    if (isValid(prevI, prevJ, n, m) && grid[prevI][prevJ] == '*') {
                        dir[i][j] = dir[prevI][prevJ] + 1;
                    }
                }
            }
        }
        return dir;
    }

    private static boolean isValid(int r, int c, int n, int m) {
        return r >= 0 && r < n && c >= 0 && c < m;
    }

    /**
     * Fast input reader using BufferedReader and StringTokenizer.
     * Replaces the custom byte-buffer implementation for better maintainability
     * and standard Java practice.
     */
    private static class FastScanner {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        FastScanner(InputStream stream) {
            this.reader = new BufferedReader(new InputStreamReader(stream));
            this.tokenizer = new StringTokenizer("");
        }

        String next() {
            while (!tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) throw new InputMismatchException();
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new InputMismatchException(e);
                }
            }
            return tokenizer.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.util.Scanner;
import java.util.Arrays;

public class Solution {
    // Direction vectors: up, down, left, right
    private static final int[] DX = {-1, 1, 0, 0};
    private static final int[] DY = {0, 0, -1, 1};

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        if (!sc.hasNextInt()) {
            return;
        }

        int n = sc.nextInt();
        int m = sc.nextInt();
        sc.nextLine(); // Consume the rest of the line after integers

        char[][] grid = new char[n][];
        for (int i = 0; i < n; i++) {
            grid[i] = sc.next().toCharArray();
        }

        // directions[dir][i][j] stores the length of consecutive '*'s starting at (i,j) in direction dir
        int[][][] directions = new int[4][n][m];
        computeDirections(grid, directions, n, m);

        char[][] copy = new char[n][m];
        for (char[] row : copy) {
            Arrays.fill(row, '.');
        }

        StringBuilder output = new StringBuilder();
        int count = 0;

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] != '*') {
                    continue;
                }

                // Find the minimum consecutive '*' length in all 4 directions
                int minLen = directions[0][i][j]; // up
                minLen = Math.min(minLen, directions[1][i][j]); // down
                minLen = Math.min(minLen, directions[2][i][j]); // left
                minLen = Math.min(minLen, directions[3][i][j]); // right

                // The center cell counts as 1, so the arm length is minLen - 1
                int size = minLen - 1;
                if (size >= 1) {
                    markCross(copy, i, j, size);
                    count++;
                    output.append(i + 1).append(" ").append(j + 1).append(" ").append(size).append("\n");
                }
            }
        }

        // Verify if the reconstructed grid matches the original
        if (Arrays.deepEquals(grid, copy)) {
            System.out.println(count);
            System.out.print(output);
        } else {
            System.out.println(-1);
        }
    }

    /**
     * Computes the length of consecutive '*' sequences in all 4 directions for each cell.
     * Uses dynamic programming with direction-aware iteration order.
     */
    private static void computeDirections(char[][] grid, int[][][] directions, int n, int m) {
        for (int dir = 0; dir < 4; dir++) {
            int dx = DX[dir];
            int dy = DY[dir];
            int[][] arr = directions[dir];

            // Determine iteration order based on direction to ensure dependencies are computed first
            int startI = (dx < 0) ? n - 1 : 0;
            int endI = (dx < 0) ? -1 : n;
            int stepI = (dx < 0) ? -1 : 1;

            int startJ = (dy < 0) ? m - 1 : 0;
            int endJ = (dy < 0) ? -1 : m;
            int stepJ = (dy < 0) ? -1 : 1;

            for (int i = startI; i != endI; i += stepI) {
                for (int j = startJ; j != endJ; j += stepJ) {
                    if (grid[i][j] == '*') {
                        arr[i][j] = 1;
                        int prevI = i - dx;
                        int prevJ = j - dy;
                        if (prevI >= 0 && prevI < n && prevJ >= 0 && prevJ < m) {
                            arr[i][j] += arr[prevI][prevJ];
                        }
                    }
                }
            }
        }
    }

    /**
     * Marks a cross pattern of '*' characters on the copy grid centered at (row, col) with arm length 'size'.
     * Includes bounds checking for safety.
     */
    private static void markCross(char[][] copy, int row, int col, int size) {
        copy[row][col] = '*';
        for (int k = 1; k <= size; k++) {
            // Mark in all 4 directions with explicit bounds checking
            if (row - k >= 0) copy[row - k][col] = '*';
            if (row + k < copy.length) copy[row + k][col] = '*';
            if (col - k >= 0) copy[row][col - k] = '*';
            if (col + k < copy[0].length) copy[row][col + k] = '*';
        }
    }
}

