/**
 * Solves the cross pattern detection problem.
 * Reads a character grid, identifies maximal cross shapes, marks their coverage,
 * and verifies if the original grid can be completely covered by these crosses.
 */
class CrossPatternSolver {
    private final FastReader reader;
    private final PrintWriter out;

    public CrossPatternSolver(FastReader reader, PrintWriter out) {
        this.reader = reader;
        this.out = out;
    }

    public void solve() {
        int n = reader.nextInt();
        int m = reader.nextInt();
        char[][] grid = readGrid(n);
        char[][] markedGrid = new char[n][m];
        for (char[] row : markedGrid) {
            Arrays.fill(row, '.');
        }

        int crossCount = 0;
        StringBuilder output = new StringBuilder();

        // Iterate through potential cross centers (excluding grid borders)
        for (int i = 1; i < n - 1; i++) {
            for (int j = 1; j < m - 1; j++) {
                if (grid[i][j] == '.') continue;

                int radius = 1;
                // Expand radius while boundaries are valid and arms contain '*'
                while (isWithinBounds(i, j, radius, n, m)) {
                    if (grid[i - radius][j] == '*' &&
                        grid[i + radius][j] == '*' &&
                        grid[i][j - radius] == '*' &&
                        grid[i][j + radius] == '*') {
                        markCross(markedGrid, i, j, radius);
                        radius++;
                    } else {
                        break;
                    }
                }

                // radius > 1 indicates at least a 3x3 cross was successfully found
                if (radius > 1) {
                    crossCount++;
                    output.append(i + 1).append(" ").append(j + 1).append(" ").append(radius - 1).append("\n");
                }
            }
        }

        if (!isGridIdentical(grid, markedGrid)) {
            out.println(-1);
        } else {
            out.println(crossCount);
            out.print(output);
        }
    }

    private char[][] readGrid(int n) {
        char[][] grid = new char[n][];
        for (int i = 0; i < n; i++) {
            grid[i] = reader.next().toCharArray();
        }
        return grid;
    }

    private boolean isWithinBounds(int row, int col, int radius, int n, int m) {
        return row - radius >= 0 && row + radius < n &&
               col - radius >= 0 && col + radius < m;
    }

    private void markCross(char[][] grid, int row, int col, int radius) {
        grid[row][col] = '*';
        grid[row - radius][col] = '*';
        grid[row + radius][col] = '*';
        grid[row][col - radius] = '*';
        grid[row][col + radius] = '*';
    }

    private boolean isGridIdentical(char[][] original, char[][] marked) {
        for (int i = 0; i < original.length; i++) {
            for (int j = 0; j < original[i].length; j++) {
                if (original[i][j] != marked[i][j]) {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Fast I/O helper class optimized for competitive programming.
     */
    static class FastReader {
        BufferedReader br;
        StringTokenizer st;

        public FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            String s = next();
            return s == null ? 0 : Integer.parseInt(s);
        }

        long nextLong() {
            String s = next();
            return s == null ? 0L : Long.parseLong(s);
        }

        double nextDouble() {
            String s = next();
            return s == null ? 0.0 : Double.parseDouble(s);
        }

        String nextLine() {
            String str = "";
            try {
                str = br.readLine();
            } catch (IOException e) {
                e.printStackTrace();
            }
            return str;
        }
    }
}

import java.util.Scanner;

/**
 * Refactored version of StarsDrawingEasy.
 * 
 * Refactoring Improvements:
 * 1. Encapsulation: Moved logic into a class instance to avoid static state pollution.
 * 2. Readability: Switched from 1-based indexing (with dummy rows/cols) to standard 0-based indexing.
 *    Output coordinates are converted back to 1-based.
 * 3. Naming: Used descriptive names (e.g., REPLACEMENT_CHAR, getMaxRadius, checkCross).
 * 4. Structure: Extracted helper methods for readability (checkDirection, applyDirection).
 * 5. Magic Numbers: Removed hardcoded assumptions about array sizes by using dynamic dimensions.
 * 6. Input Handling: Cleaner reading of the grid.
 */
public class StarsDrawingEasy {

    // Constants
    private static final char REPLACEMENT_CHAR = 'X';

    // State
    private char[][] grid;
    private int rows;
    private int cols;

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        // Read dimensions
        if (!sc.hasNextInt()) {
            sc.close();
            return;
        }
        int n = sc.nextInt();
        int m = sc.nextInt();

        // Read grid
        // Note: Original code used 1-based indexing with a dummy row 0.
        // We use 0-based indexing here for cleaner Java practices.
        char[][] grid = new char[n][m];
        for (int i = 0; i < n; i++) {
            if (sc.hasNext()) {
                String rowStr = sc.next();
                grid[i] = rowStr.toCharArray();
            } else {
                // Fallback for malformed input, though unlikely in valid test cases
                grid[i] = new char[m];
            }
        }
        sc.close();

        // Solve
        StarsDrawingEasy solver = new StarsDrawingEasy(grid);
        solver.solve();
    }

    public StarsDrawingEasy(char[][] grid) {
        this.grid = grid;
        this.rows = grid.length;
        this.cols = (rows > 0 && grid[0] != null) ? grid[0].length : 0;
    }

    public void solve() {
        int operationsCount = 0;
        StringBuilder resultOutput = new StringBuilder();

        // Iterate through the grid
        // Original: loops 1 to n, 1 to m.
        // Refactored: loops 0 to rows-1, 0 to cols-1.
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {

                char currentChar = grid[r][c];

                // Logic: Process cells that are Stars or already 'X's.
                // Skip spaces or other characters.
                if (currentChar != '*' && currentChar != REPLACEMENT_CHAR) {
                    continue;
                }

                // Calculate max radius based on distance to borders
                int maxRadius = getMaxRadius(r, c);

                // Try to find the largest valid cross radius (greedy approach)
                for (int rad = maxRadius; rad >= 1; rad--) {
                    if (checkCross(r, c, rad)) {
                        // Valid cross found
                        operationsCount++;

                        // Format output: 1-based coordinates
                        resultOutput.append(r + 1).append(" ")
                                    .append(c + 1).append(" ")
                                    .append(rad).append("\n");

                        // Apply modification
                        applyCross(r, c, rad);

                        // Move to next cell
                        break;
                    }
                }
            }
        }

        // Validate: Check if any stars remain
        if (hasNoStars()) {
            System.out.println(operationsCount);
            // Using println to match original behavior (appending newline)
            System.out.println(resultOutput); 
        } else {
            System.out.println(-1);
        }
    }

    /**
     * Calculates the maximum radius of a cross centered at (r, c).
     * Radius is limited by the distance to the nearest grid border.
     */
    private int getMaxRadius(int r, int c) {
        int top = r;
        int bottom = rows - 1 - r;
        int left = c;
        int right = cols - 1 - c;

        return Math.min(Math.min(top, bottom), Math.min(left, right));
    }

    /**
     * Checks if a cross of the given radius centered at (r, c) is valid.
     * A valid cross requires all cells in the 4 arms (up, down, left, right)
     * to be either '*' or 'X'.
     */
    private boolean checkCross(int r, int c, int rad) {
        return checkDirection(r, c, -1, 0, rad) && 
               checkDirection(r, c, 1, 0, rad) && 
               checkDirection(r, c, 0, -1, rad) && 
               checkDirection(r, c, 0, 1, rad);
    }

    /**
     * Checks a single direction of the cross.
     * Returns true if all cells in the arm are valid ('*' or 'X').
     */
    private boolean checkDirection(int r, int c, int dr, int dc, int rad) {
        for (int i = 1; i <= rad; i++) {
            int nr = r + i * dr;
            int nc = c + i * dc;

            // Bounds check (redundant if radius is correct, but safe)
            if (nr < 0 || nr >= rows || nc < 0 || nc >= cols) {
                return false;
            }

            char cell = grid[nr][nc];
            if (cell != '*' && cell != REPLACEMENT_CHAR) {
                return false;
            }
        }
        return true;
    }

    /**
     * Applies the cross pattern by setting the center and arms to 'X'.
     */
    private void applyCross(int r, int c, int rad) {
        grid[r][c] = REPLACEMENT_CHAR;
        applyDirection(r, c, -1, 0, rad);
        applyDirection(r, c, 1, 0, rad);
        applyDirection(r, c, 0, -1, rad);
        applyDirection(r, c, 0, 1, rad);
    }

    /**
     * Sets cells in a specific direction to 'X'.
     */
    private void applyDirection(int r, int c, int dr, int dc, int rad) {
        for (int i = 1; i <= rad; i++) {
            int nr = r + i * dr;
            int nc = c + i * dc;

            if (nr >= 0 && nr < rows && nc >= 0 && nc < cols) {
                grid[nr][nc] = REPLACEMENT_CHAR;
            }
        }
    }

    /**
     * Checks if the grid contains any stars ('*').
     * Returns true if the grid is valid (no stars left).
     */
    private boolean hasNoStars() {
        for (char[] row : grid) {
            for (char cell : row) {
                if (cell == '*') {
                    return false;
                }
            }
        }
        return true;
    }
}

import java.io.PrintWriter;
import java.util.Scanner;

public class StarsDrawing {

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        PrintWriter pw = new PrintWriter(System.out);

        if (!sc.hasNextInt()) {
            pw.flush();
            return;
        }

        int n = sc.nextInt();
        int m = sc.nextInt();
        char[][] grid = new char[n][m];

        for (int i = 0; i < n; i++) {
            grid[i] = sc.next().toCharArray();
        }

        // Compute consecutive '*' counts in all 4 directions
        int[][] up = new int[n][m];
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < m; c++) {
                if (grid[r][c] == '*') {
                    up[r][c] = (r > 0 && grid[r - 1][c] == '*') ? up[r - 1][c] + 1 : 0;
                }
            }
        }

        int[][] down = new int[n][m];
        for (int r = n - 1; r >= 0; r--) {
            for (int c = 0; c < m; c++) {
                if (grid[r][c] == '*') {
                    down[r][c] = (r < n - 1 && grid[r + 1][c] == '*') ? down[r + 1][c] + 1 : 0;
                }
            }
        }

        int[][] left = new int[n][m];
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < m; c++) {
                if (grid[r][c] == '*') {
                    left[r][c] = (c > 0 && grid[r][c - 1] == '*') ? left[r][c - 1] + 1 : 0;
                }
            }
        }

        int[][] right = new int[n][m];
        for (int r = 0; r < n; r++) {
            for (int c = m - 1; c >= 0; c--) {
                if (grid[r][c] == '*') {
                    right[r][c] = (c < m - 1 && grid[r][c + 1] == '*') ? right[r][c + 1] + 1 : 0;
                }
            }
        }

        int count = 0;
        boolean starFound = false;
        StringBuilder output = new StringBuilder();

        for (int r = 0; r < n; r++) {
            for (int c = 0; c < m; c++) {
                if (grid[r][c] == '*') {
                    starFound = true;
                    int min = Math.min(Math.min(up[r][c], down[r][c]), Math.min(left[r][c], right[r][c]));

                    if (min > 0) {
                        count++;
                        // Mark the cross shape with '#'
                        for (int k = 0; k <= min; k++) {
                            grid[r + k][c] = '#';
                            grid[r - k][c] = '#';
                            grid[r][c + k] = '#';
                            grid[r][c - k] = '#';
                        }
                        output.append(r + 1).append(' ').append(c + 1).append(' ').append(min).append('\n');
                    }
                }
            }
        }

        // Check if any '*' remains unmarked
        boolean allMarked = true;
        outer:
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < m; c++) {
                if (grid[r][c] == '*') {
                    allMarked = false;
                    break outer;
                }
            }
        }

        if ((count == 0 && starFound) || !allMarked) {
            pw.println(-1);
        } else {
            pw.println(count);
            pw.print(output);
        }

        pw.flush();
        sc.close();
    }
}

import java.io.*;
import java.util.*;

public class Main {
    // Fast I/O components (encapsulated to avoid global mutable state leakage)
    private static final BufferedReader BR = new BufferedReader(new InputStreamReader(System.in));
    private static final PrintWriter OUT = new PrintWriter(System.out);
    private static StringTokenizer ST = new StringTokenizer("");

    public static void main(String[] args) throws IOException {
        // Read number of test cases from input (standard competitive programming format)
        int numTestCases = nextInt();
        for (int t = 0; t < numTestCases; t++) {
            int rows = nextInt();
            int cols = nextInt();
            solveTestCase(rows, cols);
        }
        OUT.flush();
    }

    /**
     * Processes a single test case: reads the grid, detects star patterns,
     * validates coverage, and writes the result.
     */
    private static void solveTestCase(int rows, int cols) throws IOException {
        char[][] grid = new char[rows][cols];
        boolean[][] visited = new boolean[rows][cols];

        // Read grid rows
        for (int r = 0; r < rows; r++) {
            grid[r] = next().toCharArray();
        }

        List<Point> results = new ArrayList<>();
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '*') {
                    int layers = countCrossLayers(grid, visited, rows, cols, r, c);
                    if (layers > 0) {
                        results.add(new Point(r + 1, c + 1, layers));
                    }
                }
            }
        }

        // Validate that all '*' cells were covered by detected patterns
        boolean allCovered = true;
        for (int r = 0; r < rows && allCovered; r++) {
            for (int c = 0; c < cols && allCovered; c++) {
                if (grid[r][c] == '*' && !visited[r][c]) {
                    allCovered = false;
                }
            }
        }

        if (allCovered) {
            OUT.println(results.size());
            for (Point p : results) {
                OUT.println(p.row() + " " + p.col() + " " + p.layers());
            }
        } else {
            OUT.println(-1);
        }
    }

    /**
     * Counts the number of concentric cross layers centered at (r, c).
     * Marks the arms of each detected layer as visited.
     * If at least one layer is found, marks the center cell as visited.
     */
    private static int countCrossLayers(char[][] grid, boolean[][] visited, int rows, int cols, int r, int c) {
        int layers = 0;
        int top = r - 1;
        int bottom = r + 1;
        int left = c - 1;
        int right = c + 1;

        while (top >= 0 && bottom < rows && left >= 0 && right < cols &&
               grid[top][c] == '*' && grid[bottom][c] == '*' &&
               grid[r][left] == '*' && grid[r][right] == '*') {
            visited[top][c] = true;
            visited[bottom][c] = true;
            visited[r][left] = true;
            visited[r][right] = true;
            layers++;
            top--;
            bottom++;
            left--;
            right++;
        }
        if (layers > 0) {
            visited[r][c] = true;
        }
        return layers;
    }

    // ================= Fast I/O Helpers =================

    private static String next() throws IOException {
        while (!ST.hasMoreTokens()) {
            String line = BR.readLine();
            if (line == null) throw new EOFException("Unexpected end of input");
            ST = new StringTokenizer(line);
        }
        return ST.nextToken();
    }

    private static int nextInt() throws IOException {
        return Integer.parseInt(next());
    }

    private static double nextDouble() throws IOException {
        return Double.parseDouble(next());
    }

    private static long nextLong() throws IOException {
        return Long.parseLong(next());
    }

    // ================= Data Structures =================

    /**
     * Immutable data holder for result coordinates and pattern depth.
     */
    private static class Point {
        private final int row;
        private final int col;
        private final int layers;

        public Point(int row, int col, int layers) {
            this.row = row;
            this.col = col;
            this.layers = layers;
        }

        public int row() { return row; }
        public int col() { return col; }
        public int layers() { return layers; }
    }
}

import java.io.*;
import java.util.*;

/**
 * Refactored solution for grid reconstruction.
 * 
 * Problem Context (Inferred):
 * Given a grid of '*' and '.', determine if it can be represented as a union of 
 * "plus" shapes (crosses) of stars. If so, output the parameters of these crosses.
 * 
 * Algorithm:
 * 1. Precompute the length of consecutive stars in all 4 directions (Left, Right, Up, Down) for each cell.
 * 2. Identify potential "Star" centers. A cell (r, c) can be the center of a cross of radius k 
 *    if the consecutive star lengths in all 4 directions are at least k+1.
 *    The maximum radius is min(l, r, u, d) - 1.
 * 3. Collect all maximal crosses (where radius > 0).
 * 4. Use a 2D Difference Array (Sweep Line) technique to efficiently mark the cells covered 
 *    by these crosses on a target grid.
 *    - Horizontal segments are marked in a 'horizontalDiff' array.
 *    - Vertical segments are marked in a 'verticalDiff' array.
 * 5. Compute prefix sums to determine the actual coverage.
 * 6. Compare the reconstructed grid with the original grid.
 */
public class GridReconstruction {

    /**
     * Represents a cross shape (plus sign) of stars.
     */
    static class Star {
        final int row;
        final int col;
        final int radius;

        Star(int row, int col, int radius) {
            this.row = row;
            this.col = col;
            this.radius = radius;
        }
    }

    public static void main(String[] args) {
        // Use BufferedReader for fast input reading
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        // Use PrintWriter for fast output writing
        PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out));

        try {
            solve(br, out);
        } catch (IOException e) {
            e.printStackTrace();
        } finally {
            out.flush();
            out.close();
        }
    }

    private static void solve(BufferedReader br, PrintWriter out) throws IOException {
        StringTokenizer st = new StringTokenizer("");

        // Helper logic to read the next token (for n and m)
        // We manage the tokenizer state here to handle potential empty lines
        while (!st.hasMoreTokens()) {
            String line = br.readLine();
            if (line == null) return; // End of input
            st = new StringTokenizer(line);
        }

        int n = Integer.parseInt(st.nextToken());
        int m = Integer.parseInt(st.nextToken());

        char[][] grid = new char[n][m];
        for (int i = 0; i < n; i++) {
            // Read the grid row. 
            // We use readLine() to capture the full line content, 
            // matching the behavior of the original Scanner.nextLine().
            String rowStr = br.readLine();

            // Skip empty lines if any occur between rows (robustness)
            while (rowStr != null && rowStr.trim().isEmpty()) {
                rowStr = br.readLine();
            }

            if (rowStr == null) break;

            // Fill the grid row. 
            // Assuming valid input where the row string has at least m characters.
            for (int j = 0; j < m; j++) {
                if (j < rowStr.length()) {
                    grid[i][j] = rowStr.charAt(j);
                } else {
                    grid[i][j] = '.'; // Default to empty if string is short
                }
            }
        }

        // Arrays to store the length of consecutive stars in each direction
        int[][] left = new int[n][m];
        int[][] up = new int[n][m];
        int[][] right = new int[n][m];
        int[][] down = new int[n][m];

        // 1. Compute Left and Up consecutive stars (Forward pass)
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                boolean isStar = grid[i][j] == '*';

                // Left: consecutive stars ending at (i, j) coming from left
                if (isStar) {
                    left[i][j] = (j > 0) ? left[i][j - 1] + 1 : 1;
                } else {
                    left[i][j] = 0;
                }

                // Up: consecutive stars ending at (i, j) coming from up
                if (isStar) {
                    up[i][j] = (i > 0) ? up[i - 1][j] + 1 : 1;
                } else {
                    up[i][j] = 0;
                }
            }
        }

        // 2. Compute Right and Down consecutive stars (Backward pass)
        for (int i = n - 1; i >= 0; i--) {
            for (int j = m - 1; j >= 0; j--) {
                boolean isStar = grid[i][j] == '*';

                // Right: consecutive stars starting at (i, j) going right
                if (isStar) {
                    right[i][j] = (j < m - 1) ? right[i][j + 1] + 1 : 1;
                } else {
                    right[i][j] = 0;
                }

                // Down: consecutive stars starting at (i, j) going down
                if (isStar) {
                    down[i][j] = (i < n - 1) ? down[i + 1][j] + 1 : 1;
                } else {
                    down[i][j] = 0;
                }
            }
        }

        // 3. Identify potential Star centers
        // A star at (i, j) can form a cross of radius k if it has at least k stars
        // in all 4 directions (including itself).
        // The max radius is min(left, right, up, down) - 1.
        List<Star> stars = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == '*') {
                    int minLen = Math.min(Math.min(left[i][j], right[i][j]), 
                                          Math.min(up[i][j], down[i][j]));

                    int radius = minLen - 1;
                    // Original logic: only consider stars with radius > 0
                    if (radius > 0) {
                        stars.add(new Star(i, j, radius));
                    }
                }
            }
        }

        // 4. Reconstruct the grid using 2D Difference Arrays
        char[][] reconstructedGrid = new char[n][m];
        for (int i = 0; i < n; i++) {
            Arrays.fill(reconstructedGrid[i], '.');
        }

        // Difference arrays for horizontal and vertical coverage
        // hDiff[i][j] stores the difference for horizontal segment at row i, col j
        // vDiff[i][j] stores the difference for vertical segment at row i, col j
        int[][] hDiff = new int[n][m];
        int[][] vDiff = new int[n][m];

        for (Star s : stars) {
            int r = s.row;
            int c = s.col;
            int rad = s.radius;

            // Horizontal segment: row r, columns [c - rad, c + rad]
            int hStart = c - rad;
            int hEnd = c + rad;

            // Update difference array for range [hStart, hEnd]
            hDiff[r][hStart]++;
            if (hEnd + 1 < m) {
                hDiff[r][hEnd + 1]--;
            }

            // Vertical segment: column c, rows [r - rad, r + rad]
            int vStart = r - rad;
            int vEnd = r + rad;

            // Update difference array for range [vStart, vEnd]
            vDiff[vStart][c]++;
            if (vEnd + 1 < n) {
                vDiff[vEnd + 1][c]--;
            }
        }

        // 5. Compute Prefix Sums to determine coverage
        // Horizontal accumulation
        for (int i = 0; i < n; i++) {
            int currentVal = 0;
            for (int j = 0; j < m; j++) {
                currentVal += hDiff[i][j];
                if (currentVal > 0) {
                    reconstructedGrid[i][j] = '*';
                }
            }
        }

        // Vertical accumulation
        // We iterate columns to process vertical lines. 
        // Note: Accessing vDiff[i][j] in a column-major loop (j outer, i inner) 
        // might be cache-unfriendly for row-major arrays, but acceptable for N, M <= 1000.
        for (int j = 0; j < m; j++) {
            int currentVal = 0;
            for (int i = 0; i < n; i++) {
                currentVal += vDiff[i][j];
                if (currentVal > 0) {
                    reconstructedGrid[i][j] = '*';
                }
            }
        }

        // 6. Compare original grid with reconstructed grid
        boolean matches = true;
        for (int i = 0; i < n; i++) {
            if (!Arrays.equals(grid[i], reconstructedGrid[i])) {
                matches = false;
                break;
            }
        }

        // 7. Output results
        if (matches) {
            out.println(stars.size());
            for (Star s : stars) {
                // Output 1-based coordinates
                out.println((s.row + 1) + " " + (s.col + 1) + " " + s.radius);
            }
        } else {
            out.println("-1");
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Reconstructs a character grid from cross patterns and verifies if the original
 * grid can be perfectly represented by these crosses.
 */
public class GridCrossReconstructor {

    /**
     * Immutable data class representing a valid cross pattern found in the grid.
     */
    static class Cross {
        final int row;
        final int col;
        final int radius;

        Cross(int row, int col, int radius) {
            this.row = row;
            this.col = col;
            this.radius = radius;
        }
    }

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out));

        try {
            int n = scanner.nextInt();
            int m = scanner.nextInt();

            char[][] grid = new char[n][];
            for (int i = 0; i < n; i++) {
                grid[i] = scanner.next().toCharArray();
            }

            List<Cross> crosses = findCrosses(grid, n, m);
            char[][] reconstructed = reconstructGrid(grid, crosses, n, m);

            if (isGridsEqual(grid, reconstructed, n, m)) {
                out.println(crosses.size());
                for (Cross c : crosses) {
                    // Output uses 1-based indexing as per original logic
                    out.println((c.row + 1) + " " + (c.col + 1) + " " + c.radius);
                }
            } else {
                out.println(-1);
            }
        } finally {
            out.flush();
        }
    }

    /**
     * Identifies all valid cross patterns in the grid.
     * A cross is valid if all cells within radius k in the four cardinal directions
     * are non-dot characters.
     */
    private static List<Cross> findCrosses(char[][] grid, int n, int m) {
        List<Cross> result = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == '.') continue;

                int maxRadius = 0;
                int k = 1;
                while (true) {
                    // Check boundaries
                    if (i + k >= n || i - k < 0 || j + k >= m || j - k < 0) break;
                    // Check if any of the four directions at distance k is a dot
                    if (grid[i + k][j] == '.' || grid[i - k][j] == '.' ||
                        grid[i][j + k] == '.' || grid[i][j - k] == '.') break;

                    maxRadius = k;
                    k++;
                }
                if (maxRadius > 0) {
                    result.add(new Cross(i, j, maxRadius));
                }
            }
        }
        return result;
    }

    /**
     * Reconstructs the grid by placing '*' characters for each identified cross.
     */
    private static char[][] reconstructGrid(char[][] original, List<Cross> crosses, int n, int m) {
        char[][] reconstructed = new char[n][m];
        for (char[] row : reconstructed) {
            Arrays.fill(row, '.');
        }

        for (Cross c : crosses) {
            reconstructed[c.row][c.col] = '*';
            for (int k = 1; k <= c.radius; k++) {
                reconstructed[c.row + k][c.col] = '*';
                reconstructed[c.row - k][c.col] = '*';
                reconstructed[c.row][c.col + k] = '*';
                reconstructed[c.row][c.col - k] = '*';
            }
        }
        return reconstructed;
    }

    /**
     * Compares two grids to check if they are identical.
     */
    private static boolean isGridsEqual(char[][] a, char[][] b, int n, int m) {
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (a[i][j] != b[i][j]) return false;
            }
        }
        return true;
    }

    /**
     * Fast I/O helper class using BufferedReader and StringTokenizer.
     * Replaces the custom InputReader for better maintainability and reliability.
     */
    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input", e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            String s = next();
            if (s == null) throw new NoSuchElementException("No more tokens");
            return Integer.parseInt(s);
        }
    }
}

import java.io.*;
import java.util.*;

public class DrawingStars {
    // Lines must be strictly longer than 2 characters (i.e., length >= 3)
    private static final int MIN_LINE_LENGTH = 3;

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner();
        PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out));

        try {
            int n = scanner.nextInt();
            int m = scanner.nextInt();
            char[][] grid = readGrid(scanner, n, m);

            // Detect horizontal and vertical lines of '*'
            List<Line> horizontalLines = detectLines(grid, n, m, true);
            List<Line> verticalLines = detectLines(grid, n, m, false);

            // Prepare sweep-line events for horizontal lines
            PriorityQueue<Event> sweepEvents = new PriorityQueue<>();
            for (int i = 0; i < horizontalLines.size(); i++) {
                sweepEvents.add(new Event(horizontalLines.get(i).l, 1, i));
                sweepEvents.add(new Event(horizontalLines.get(i).r, 0, i));
            }

            // Sort vertical lines by column (x), then by start row (l)
            verticalLines.sort(Comparator.comparingInt(l -> l.x).thenComparingInt(l -> l.l));

            // Difference arrays for range updates
            int[][] horizDiff = new int[n][m + 1];
            int[][] vertDiff = new int[n + 1][m];
            StringBuilder output = new StringBuilder();

            // Process intersections and populate difference arrays
            int validIntersections = processIntersections(verticalLines, sweepEvents, horizontalLines, 
                                                          horizDiff, vertDiff, output, n, m);

            // Compute actual coverage counts from difference arrays
            int[][] horizCoverage = buildCoverageArray(horizDiff, n, m);
            int[][] vertCoverage = buildCoverageArray(vertDiff, n, m);

            // Validate that every '*' is covered by at least one valid line
            if (!isGridFullyCovered(grid, horizCoverage, vertCoverage, n, m)) {
                out.println(-1);
            } else {
                out.println(validIntersections);
                out.print(output);
            }
        } finally {
            out.flush();
        }
    }

    /**
     * Reads the character grid from input.
     */
    private static char[][] readGrid(FastScanner scanner, int n, int m) {
        char[][] grid = new char[n][];
        for (int i = 0; i < n; i++) {
            grid[i] = scanner.next().toCharArray();
        }
        return grid;
    }

    /**
     * Detects horizontal or vertical lines of '*' that meet the minimum length requirement.
     * @param horizontal true for horizontal lines, false for vertical
     */
    private static List<Line> detectLines(char[][] grid, int n, int m, boolean horizontal) {
        List<Line> lines = new ArrayList<>();
        int limit = horizontal ? m : n;

        for (int coord = 0; coord < (horizontal ? n : m); coord++) {
            int prevStart = -1;
            for (int pos = 0; pos < limit; pos++) {
                char cell = grid[horizontal ? coord : pos][horizontal ? pos : coord];

                if (cell == '*') {
                    if (prevStart == -1) prevStart = pos;
                } else {
                    if (prevStart != -1) {
                        if (pos - prevStart >= MIN_LINE_LENGTH) {
                            lines.add(new Line(prevStart, pos, coord));
                        }
                        prevStart = -1;
                    }
                }
            }
            // Handle line ending at the grid boundary
            if (prevStart != -1 && limit - prevStart >= MIN_LINE_LENGTH) {
                lines.add(new Line(prevStart, limit, coord));
            }
        }
        return lines;
    }

    /**
     * Executes the sweep-line algorithm to find valid intersection points,
     * calculates maximum square radii, and applies difference array updates.
     */
    private static int processIntersections(List<Line> verticalLines, PriorityQueue<Event> events,
                                            List<Line> horizontalLines, int[][] horizDiff, int[][] vertDiff,
                                            StringBuilder output, int n, int m) {
        int validCount = 0;
        Line[] activeHorizontal = new Line[n];

        for (Line vertLine : verticalLines) {
            // Advance sweep-line to current vertical line's column
            while (!events.isEmpty() && events.peek().x <= vertLine.x) {
                Event evt = events.poll();
                Line hLine = horizontalLines.get(evt.ind);
                activeHorizontal[hLine.x] = (evt.type == 1) ? hLine : null;
            }

            // Check intersections along the active portion of the vertical line
            for (int row = vertLine.l; row < vertLine.r; row++) {
                Line hLine = activeHorizontal[row];
                if (hLine == null) continue;

                // Calculate maximum radius for a cross centered at (row, vertLine.x)
                int verticalDist = Math.min(vertLine.r - row - 1, row - vertLine.l);
                int horizontalDist = Math.min(hLine.r - vertLine.x - 1, vertLine.x - hLine.l);
                int radius = Math.min(verticalDist, horizontalDist);

                if (radius > 0) {
                    // Apply range updates using difference arrays
                    vertDiff[row - radius][vertLine.x]++;
                    vertDiff[row + radius + 1][vertLine.x]--;
                    horizDiff[row][vertLine.x - radius]++;
                    horizDiff[row][vertLine.x + radius + 1]--;

                    validCount++;
                    output.append(row + 1).append(' ').append(vertLine.x + 1).append(' ').append(radius).append('\n');
                }
            }
        }
        return validCount;
    }

    /**
     * Computes prefix sums from a difference array to get actual coverage counts.
     * Handles both horizontal ([n][m]) and vertical ([m][n]) coverage structures.
     */
    private static int[][] buildCoverageArray(int[][] diff, int n, int m) {
        int[][] coverage = new int[n][m];
        for (int i = 0; i < n; i++) {
            int current = 0;
            for (int j = 0; j < m; j++) {
                current += diff[i][j];
                coverage[i][j] = current;
            }
        }
        return coverage;
    }

    /**
     * Verifies that every '*' cell in the grid is covered by at least one valid horizontal or vertical line.
     */
    private static boolean isGridFullyCovered(char[][] grid, int[][] horizCoverage, int[][] vertCoverage, int n, int m) {
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == '*') {
                    // Note: vertCoverage is stored transposed as [m][n] in the original logic
                    if (horizCoverage[i][j] <= 0 && vertCoverage[j][i] <= 0) {
                        return false;
                    }
                }
            }
        }
        return true;
    }

    /**
     * Represents a line segment in the grid.
     * x: fixed coordinate (row for horizontal, column for vertical)
     * l, r: start and end coordinates (exclusive bound for r)
     */
    private static class Line {
        final int l, r, x;
        Line(int l, int r, int x) {
            this.l = l; this.r = r; this.x = x;
        }
    }

    /**
     * Represents a sweep-line event for horizontal line segments.
     * type: 1 = start, 0 = end
     */
    private static class Event implements Comparable<Event> {
        final int x, type, ind;
        Event(int x, int type, int ind) {
            this.x = x; this.type = type; this.ind = ind;
        }

        @Override
        public int compareTo(Event o) {
            int xCmp = Integer.compare(this.x, o.x);
            return xCmp != 0 ? xCmp : Integer.compare(this.type, o.type);
        }
    }

    /**
     * Optimized fast I/O scanner for competitive programming.
     */
    public static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner() {
            this.br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) throw new EOFException("Unexpected end of input");
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input", e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Analyzes a 2D character grid to find maximum-sized cross patterns centered at '*' characters.
 * Validates if the original grid can be perfectly reconstructed from the found crosses.
 */
public class CrossGridAnalyzer {

    /** Represents a cross pattern found in the grid. */
    private static class Cross {
        final int row;
        final int col;
        final int size;

        Cross(int row, int col, int size) {
            this.row = row;
            this.col = col;
            this.size = size;
        }
    }

    public static void main(String[] args) throws IOException {
        FastScanner sc = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out));

        int n = sc.nextInt();
        int m = sc.nextInt();

        char[][] grid = new char[n][m];
        for (int i = 0; i < n; i++) {
            String line = sc.next();
            grid[i] = line.toCharArray();
        }

        // 1. Compute 2D prefix sums for rows and columns
        int[][] rowPrefix = computePrefixSums(grid, false);
        int[][] colPrefix = computePrefixSums(grid, true);

        // 2. Find maximum valid cross size for each '*'
        List<Cross> crosses = findCrosses(grid, rowPrefix, colPrefix, n, m);

        // 3. Validate reconstruction
        if (!validateReconstruction(grid, crosses, n, m)) {
            out.println("-1");
        } else {
            out.println(crosses.size());
            for (Cross c : crosses) {
                // Output 1-based coordinates as in original
                out.println((c.row + 1) + " " + (c.col + 1) + " " + c.size);
            }
        }

        out.flush();
        out.close();
    }

    /**
     * Computes prefix sum arrays.
     * @param grid Input grid
     * @param computeColumnSums If true, computes vertical prefix sums; otherwise horizontal.
     * @return 2D array of prefix sums
     */
    private static int[][] computePrefixSums(char[][] grid, boolean computeColumnSums) {
        int n = grid.length;
        int m = grid[0].length;
        int[][] prefix = new int[n][m];

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                prefix[i][j] = (grid[i][j] == '*' ? 1 : 0);
            }
        }

        if (!computeColumnSums) {
            // Row-wise prefix sums
            for (int i = 0; i < n; i++) {
                for (int j = 1; j < m; j++) {
                    prefix[i][j] += prefix[i][j - 1];
                }
            }
        } else {
            // Column-wise prefix sums
            for (int j = 0; j < m; j++) {
                for (int i = 1; i < n; i++) {
                    prefix[i][j] += prefix[i - 1][j];
                }
            }
        }
        return prefix;
    }

    /**
     * Finds all valid crosses using binary search for maximum size.
     */
    private static List<Cross> findCrosses(char[][] grid, int[][] rowPrefix, int[][] colPrefix, int n, int m) {
        List<Cross> crosses = new ArrayList<>();

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] != '*') continue;

                // Maximum possible cross size is limited by distance to grid boundaries
                int maxPossible = Math.min(Math.min(i, n - 1 - i), Math.min(j, m - 1 - j));

                int lo = 1, hi = maxPossible;
                int bestSize = 0;

                while (lo <= hi) {
                    int mid = lo + (hi - lo) / 2;
                    if (checkCross(grid, rowPrefix, colPrefix, i, j, mid, n, m)) {
                        bestSize = mid;
                        lo = mid + 1; // Try larger size
                    } else {
                        hi = mid - 1; // Try smaller size
                    }
                }

                if (bestSize > 0) {
                    crosses.add(new Cross(i, j, bestSize));
                }
            }
        }
        return crosses;
    }

    /**
     * Checks if a cross of given size exists at (r, c) using prefix sums.
     * Precondition: r ± k and c ± k are within grid bounds.
     */
    private static boolean checkCross(char[][] grid, int[][] rowPrefix, int[][] colPrefix, 
                                      int r, int c, int k, int n, int m) {
        // Verify endpoints are '*'
        if (grid[r][c + k] != '*' || grid[r][c - k] != '*' ||
            grid[r + k][c] != '*' || grid[r - k][c] != '*') {
            return false;
        }

        // Verify horizontal arm length
        int rowCount = rowPrefix[r][c + k];
        if (c - k - 1 >= 0) rowCount -= rowPrefix[r][c - k - 1];
        if (rowCount != 2 * k + 1) return false;

        // Verify vertical arm length
        int colCount = colPrefix[r + k][c];
        if (r - k - 1 >= 0) colCount -= colPrefix[r - k - 1][c];
        if (colCount != 2 * k + 1) return false;

        return true;
    }

    /**
     * Reconstructs the grid from found crosses and validates against original.
     */
    private static boolean validateReconstruction(char[][] original, List<Cross> crosses, int n, int m) {
        char[][] reconstructed = new char[n][m];
        for (char[] row : reconstructed) {
            Arrays.fill(row, '.');
        }

        for (Cross c : crosses) {
            for (int k = -c.size; k <= c.size; k++) {
                reconstructed[c.row + k][c.col] = '*';
                reconstructed[c.row][c.col + k] = '*';
            }
        }

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (original[i][j] != reconstructed[i][j]) {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Fast I/O helper for competitive programming / performance-critical inputs.
     */
    private static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input", e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            String token = next();
            return token == null ? 0 : Integer.parseInt(token);
        }
    }
}

import java.io.BufferedInputStream;
import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;

public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        PrintWriter out = new PrintWriter(System.out);
        FastScanner in = new FastScanner(inputStream);
        StarDrawingSolver solver = new StarDrawingSolver();
        solver.solve(in, out);
        out.flush();
        out.close();
    }

    /**
     * Solves the Star Drawing (Easy Edition) problem.
     * Finds the largest cross centered at each cell that fits within the grid
     * and only covers '*' characters, then verifies if the entire grid can be formed.
     */
    static class StarDrawingSolver {
        public void solve(FastScanner in, PrintWriter out) {
            int n = in.nextInt();
            int m = in.nextInt();
            char[][] grid = new char[n][m];
            char[][] filledGrid = new char[n][m];

            // Read input grid and initialize filled grid
            for (int i = 0; i < n; i++) {
                String row = in.next();
                grid[i] = row.toCharArray();
                for (int j = 0; j < m; j++) {
                    filledGrid[i][j] = '.';
                }
            }

            int starCount = 0;
            int[][] maxRadii = new int[n][m];

            // Determine maximum valid cross radius for each cell
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    int maxK = 0;
                    // Dynamic limit ensures we never check out-of-bounds coordinates
                    int limit = Math.min(Math.min(i, n - 1 - i), Math.min(j, m - 1 - j));

                    for (int k = 1; k <= limit; k++) {
                        if (isValidCross(i, j, k, grid, n, m)) {
                            maxK = k;
                        } else {
                            break;
                        }
                    }
                    maxRadii[i][j] = maxK;
                    if (maxK > 0) {
                        starCount++;
                        markCross(i, j, maxK, filledGrid);
                    }
                }
            }

            // Verify if the constructed grid matches the original input
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    if (grid[i][j] != filledGrid[i][j]) {
                        out.println(-1);
                        return;
                    }
                }
            }

            // Output results
            out.println(starCount);
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    if (maxRadii[i][j] > 0) {
                        // Output uses 1-based indexing as per original logic
                        out.println((i + 1) + " " + (j + 1) + " " + maxRadii[i][j]);
                    }
                }
            }
        }

        /**
         * Checks if a cross of given radius centered at (row, col) 
         * is valid (only covers '*' characters).
         */
        private boolean isValidCross(int row, int col, int radius, char[][] grid, int n, int m) {
            // Check vertical line
            for (int i = row - radius; i <= row + radius; i++) {
                if (grid[i][col] != '*') return false;
            }
            // Check horizontal line
            for (int i = col - radius; i <= col + radius; i++) {
                if (grid[row][i] != '*') return false;
            }
            return true;
        }

        /**
         * Marks a cross of given radius centered at (row, col) 
         * in the filledGrid.
         */
        private void markCross(int row, int col, int radius, char[][] filledGrid) {
            for (int i = row - radius; i <= row + radius; i++) {
                filledGrid[i][col] = '*';
            }
            for (int i = col - radius; i <= col + radius; i++) {
                filledGrid[row][i] = '*';
            }
        }
    }

    /**
     * Fast I/O scanner optimized for competitive programming environments.
     */
    static class FastScanner {
        private final BufferedInputStream in;
        private final byte[] buffer = new byte[4 * 1024];
        private int bufferIndex = 0;
        private int bufferSize = 0;

        public FastScanner(InputStream inputStream) {
            this.in = new BufferedInputStream(inputStream);
        }

        private int readByte() {
            if (bufferIndex >= bufferSize) {
                bufferIndex = 0;
                try {
                    bufferSize = in.read(buffer);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input", e);
                }
                if (bufferSize <= 0) {
                    return -1;
                }
            }
            return buffer[bufferIndex++];
        }

        public int nextInt() {
            int c = readByte();
            while (isWhitespace(c)) c = readByte();
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = readByte();
            }
            int result = 0;
            while (c != -1 && !isWhitespace(c)) {
                if (c >= '0' && c <= '9') {
                    result = result * 10 + (c - '0');
                }
                c = readByte();
            }
            return result * sign;
        }

        public String next() {
            int c = readByte();
            while (isWhitespace(c)) c = readByte();
            StringBuilder sb = new StringBuilder();
            while (c != -1 && !isWhitespace(c)) {
                sb.appendCodePoint(c);
                c = readByte();
            }
            return sb.toString();
        }

        private boolean isWhitespace(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.ArrayList;
import java.util.List;
import java.util.StringTokenizer;

public class Solution {

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner();
        PrintWriter out = new PrintWriter(System.out);

        try {
            // Read dimensions
            String nStr = scanner.next();
            if (nStr == null) return;
            int n = Integer.parseInt(nStr);
            int m = scanner.nextInt();

            char[][] grid = new char[n][];
            for (int i = 0; i < n; i++) {
                grid[i] = scanner.next().toCharArray();
            }

            int[][] rightDist = new int[n][m];
            int[][] leftDist = new int[n][m];
            int[][] downDist = new int[n][m];
            int[][] upDist = new int[n][m];

            // Precompute contiguous distances in all four directions
            calculateRightDistances(grid, n, m, rightDist);
            calculateLeftDistances(grid, n, m, leftDist);
            calculateDownDistances(grid, n, m, downDist);
            calculateUpDistances(grid, n, m, upDist);

            boolean[][] visited = new boolean[n][m];
            List<int[]> processedStars = new ArrayList<>();

            // Identify and process valid star patterns
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    if (grid[i][j] == '*') {
                        int minArm = min(upDist[i][j], downDist[i][j], leftDist[i][j], rightDist[i][j]);
                        if (minArm > 0) {
                            markAndRecord(i, j, minArm, visited, processedStars);
                        }
                    }
                }
            }

            // Verify that every '*' in the grid was covered by a pattern
            boolean allVisited = true;
            outerLoop:
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    if (grid[i][j] == '*' && !visited[i][j]) {
                        allVisited = false;
                        break outerLoop;
                    }
                }
            }

            if (!allVisited) {
                out.println(-1);
            } else {
                out.println(processedStars.size());
                for (int[] star : processedStars) {
                    // Output 1-based coordinates for rows and columns
                    out.println((star[0] + 1) + " " + (star[1] + 1) + " " + star[2]);
                }
            }
        } finally {
            out.close();
        }
    }

    /**
     * Returns the minimum of four integers.
     */
    private static int min(int a, int b, int c, int d) {
        return Math.min(Math.min(a, b), Math.min(c, d));
    }

    /**
     * Marks all cells in the cross pattern as visited and records the star's properties.
     */
    private static void markAndRecord(int r, int c, int size, boolean[][] visited, List<int[]> result) {
        visited[r][c] = true;
        for (int k = 1; k <= size; k++) {
            visited[r + k][c] = true;
            visited[r - k][c] = true;
            visited[r][c + k] = true;
            visited[r][c - k] = true;
        }
        result.add(new int[]{r, c, size});
    }

    private static void calculateRightDistances(char[][] grid, int n, int m, int[][] dist) {
        for (int i = 0; i < n; i++) {
            int rightEnd = 0;
            for (int j = 0; j < m; j++) {
                if (rightEnd < j) rightEnd = j;
                while (rightEnd < m - 1 && grid[i][rightEnd + 1] == '*') {
                    rightEnd++;
                }
                dist[i][j] = rightEnd - j;
            }
        }
    }

    private static void calculateLeftDistances(char[][] grid, int n, int m, int[][] dist) {
        for (int i = 0; i < n; i++) {
            int leftEnd = m - 1;
            for (int j = m - 1; j >= 0; j--) {
                if (leftEnd > j) leftEnd = j;
                while (leftEnd > 0 && grid[i][leftEnd - 1] == '*') {
                    leftEnd--;
                }
                dist[i][j] = j - leftEnd;
            }
        }
    }

    private static void calculateDownDistances(char[][] grid, int n, int m, int[][] dist) {
        for (int j = 0; j < m; j++) {
            int downEnd = 0;
            for (int i = 0; i < n; i++) {
                if (downEnd < i) downEnd = i;
                while (downEnd < n - 1 && grid[downEnd + 1][j] == '*') {
                    downEnd++;
                }
                dist[i][j] = downEnd - i;
            }
        }
    }

    private static void calculateUpDistances(char[][] grid, int n, int m, int[][] dist) {
        for (int j = 0; j < m; j++) {
            int upEnd = n - 1;
            for (int i = n - 1; i >= 0; i--) {
                if (upEnd > i) upEnd = i;
                while (upEnd > 0 && grid[upEnd - 1][j] == '*') {
                    upEnd--;
                }
                dist[i][j] = i - upEnd;
            }
        }
    }

    /**
     * Fast I/O utility for competitive programming and high-throughput scenarios.
     */
    static class FastScanner {
        private final BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        private StringTokenizer st = new StringTokenizer("");

        String next() {
            while (!st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            String s = next();
            return s == null ? 0 : Integer.parseInt(s);
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.ArrayList;
import java.util.List;
import java.util.StringTokenizer;

/**
 * Refactored solution for identifying valid cross patterns in a grid.
 * 
 * Improvements made:
 * 1. Class Naming: Renamed 'Q4' to 'GridCrossSolver' for clarity.
 * 2. Input Handling: Replaced the verbose custom FastScanner with a standard 
 *    BufferedReader and StringTokenizer pattern, which is more readable and 
 *    sufficiently performant.
 * 3. Data Structures: Replaced parallel ArrayLists (rowAns, colAns, sizeAns) 
 *    with a dedicated 'CrossPattern' class to encapsulate related data.
 * 4. Variable Naming: Renamed short/magic variables (r, c, fs, fill, flag) 
 *    to descriptive names (rows, cols, scanner, isCellCovered, allValid).
 * 5. Structure: Removed static IO fields; IO resources are now managed locally 
 *    within the main method to reduce coupling.
 * 6. Readability: Added comments and formatted code for better maintainability.
 */
public class GridCrossSolver {

    /**
     * Represents a valid cross pattern found in the grid.
     */
    static class CrossPattern {
        final int row;      // 1-based row index
        final int col;      // 1-based column index
        final int radius;   // The arm length k

        public CrossPattern(int row, int col, int radius) {
            this.row = row;
            this.col = col;
            this.radius = radius;
        }
    }

    public static void main(String[] args) throws IOException {
        // Initialize IO
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter out = new PrintWriter(System.out);

        FastReader scanner = new FastReader(br);

        // Read grid dimensions
        String rStr = scanner.next();
        if (rStr == null) {
            out.flush();
            return;
        }
        int rows = Integer.parseInt(rStr);
        int cols = scanner.nextInt();

        // Read grid content
        char[][] grid = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            String line = scanner.next();
            // Ensure we handle the line correctly, though standard input is expected to be well-formed
            if (line != null && line.length() >= cols) {
                grid[i] = line.substring(0, cols).toCharArray();
            } else if (line != null) {
                grid[i] = line.toCharArray();
            } else {
                grid[i] = new char[cols]; // Fallback for empty lines
            }
        }

        // Data structures to track coverage and results
        boolean[][] isCellCovered = new boolean[rows][cols];
        List<CrossPattern> foundCrosses = new ArrayList<>();

        // Initialize coverage: Dots are considered "covered" (valid) by default.
        // Asterisks must be part of a valid cross to be covered.
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == '.') {
                    isCellCovered[i][j] = true;
                }
            }
        }

        // Scan the grid to find valid cross patterns
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                // We only look for centers of crosses at asterisk positions
                if (grid[i][j] == '*') {

                    // Calculate maximum possible radius based on grid boundaries
                    // Distance to top (i), left (j), bottom (rows-1-i), right (cols-1-j)
                    int maxRadius = Math.min(Math.min(i, j), Math.min(rows - 1 - i, cols - 1 - j));
                    int bestRadius = -1;

                    // Check for valid arms extending from the center
                    for (int k = 1; k <= maxRadius; k++) {
                        // Check the four directions: Top, Bottom, Left, Right
                        boolean isArmValid = true;

                        if (grid[i - k][j] != '*') isArmValid = false;
                        if (grid[i + k][j] != '*') isArmValid = false;
                        if (grid[i][j - k] != '*') isArmValid = false;
                        if (grid[i][j + k] != '*') isArmValid = false;

                        if (isArmValid) {
                            bestRadius = k; // Update to the largest valid radius found so far
                        } else {
                            break; // If an arm is missing, larger radii cannot exist
                        }
                    }

                    // If a valid cross was found (radius >= 1)
                    if (bestRadius > 0) {
                        // Mark all cells involved in this cross as covered
                        isCellCovered[i][j] = true; // Center
                        for (int k = 1; k <= bestRadius; k++) {
                            isCellCovered[i - k][j] = true;
                            isCellCovered[i + k][j] = true;
                            isCellCovered[i][j - k] = true;
                            isCellCovered[i][j + k] = true;
                        }

                        // Store the result (using 1-based indexing for output)
                        foundCrosses.add(new CrossPattern(i + 1, j + 1, bestRadius));
                    }
                }
            }
        }

        // Verify that every cell in the grid is covered
        boolean allValid = true;
        outerLoop:
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (!isCellCovered[i][j]) {
                    allValid = false;
                    break outerLoop;
                }
            }
        }

        // Output results
        if (allValid) {
            out.println(foundCrosses.size());
            for (CrossPattern cross : foundCrosses) {
                out.println(cross.row + " " + cross.col + " " + cross.radius);
            }
        } else {
            out.println("-1");
        }

        out.flush();
        out.close();
    }

    /**
     * Helper class for fast input reading using BufferedReader and StringTokenizer.
     */
    static class FastReader {
        BufferedReader br;
        StringTokenizer st;

        public FastReader(BufferedReader br) {
            this.br = br;
        }

        String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    e.printStackTrace();
                    return null;
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            String s = next();
            if (s == null) throw new RuntimeException("End of input");
            return Integer.parseInt(s);
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.ArrayList;
import java.util.List;
import java.util.StringTokenizer;

public class PlusSignCovering {

    public static void main(String[] args) {
        FastScanner sc = new FastScanner();
        PrintWriter out = new PrintWriter(System.out);

        try {
            int n = sc.nextInt();
            int m = sc.nextInt();
            int[][] grid = parseGrid(sc, n, m);

            List<Cross> crosses = new ArrayList<>();
            boolean[][] visited = new boolean[n][m];

            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    if (grid[i][j] == 1) {
                        int radius = calculateMaxRadius(i, j, grid);
                        if (radius > 0) {
                            crosses.add(new Cross(i + 1, j + 1, radius));
                            markCoverage(i, j, radius, visited);
                        }
                    }
                }
            }

            if (isFullyCovered(grid, visited)) {
                out.println(crosses.size());
                for (Cross cross : crosses) {
                    out.println(cross.row + " " + cross.col + " " + cross.radius);
                }
            } else {
                out.println(-1);
            }
        } catch (Exception e) {
            e.printStackTrace();
        } finally {
            out.flush();
            out.close();
        }
    }

    private static int[][] parseGrid(FastScanner sc, int n, int m) {
        int[][] grid = new int[n][m];
        for (int i = 0; i < n; i++) {
            String row = sc.next();
            for (int j = 0; j < m; j++) {
                grid[i][j] = (row.charAt(j) == '.') ? 0 : 1;
            }
        }
        return grid;
    }

    private static int calculateMaxRadius(int i, int j, int[][] grid) {
        int up = countOnesInDirection(i, j, -1, 0, grid);
        int down = countOnesInDirection(i, j, 1, 0, grid);
        int left = countOnesInDirection(i, j, 0, -1, grid);
        int right = countOnesInDirection(i, j, 0, 1, grid);
        return Math.min(Math.min(up, left), Math.min(down, right));
    }

    private static int countOnesInDirection(int startRow, int startCol, int dr, int dc, int[][] grid) {
        int count = 0;
        for (int r = startRow, c = startCol; isValid(r, c, grid); r += dr, c += dc) {
            if (grid[r][c] == 1) {
                count++;
            } else {
                break;
            }
        }
        return count - 1; // Exclude the center cell itself
    }

    private static boolean isValid(int r, int c, int[][] grid) {
        return r >= 0 && r < grid.length && c >= 0 && c < grid[0].length;
    }

    private static void markCoverage(int centerRow, int centerCol, int radius, boolean[][] visited) {
        visited[centerRow][centerCol] = true;
        for (int k = 1; k <= radius; k++) {
            visited[centerRow - k][centerCol] = true;
            visited[centerRow + k][centerCol] = true;
            visited[centerRow][centerCol - k] = true;
            visited[centerRow][centerCol + k] = true;
        }
    }

    private static boolean isFullyCovered(int[][] grid, boolean[][] visited) {
        for (int i = 0; i < grid.length; i++) {
            for (int j = 0; j < grid[0].length; j++) {
                if (grid[i][j] == 1 && !visited[i][j]) {
                    return false;
                }
            }
        }
        return true;
    }

    static class Cross {
        int row;
        int col;
        int radius;

        public Cross(int row, int col, int radius) {
            this.row = row;
            this.col = col;
            this.radius = radius;
        }
    }

    static class FastScanner {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer("");

        String next() {
            while (!st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            String s = next();
            return (s == null) ? 0 : Integer.parseInt(s);
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.ArrayList;
import java.util.StringTokenizer;

/**
 * Solves the cross pattern detection problem on a 2D grid.
 * Identifies valid cross shapes formed by '*' characters and verifies
 * that all '*' characters are consumed by exactly one cross.
 */
public class CrossPatternSolver {

    /** Represents a detected cross pattern in the grid */
    static class Cross {
        final int row;
        final int col;
        final int length; // Number of stars on each arm (excluding center)

        Cross(int row, int col, int length) {
            this.row = row;
            this.col = col;
            this.length = length;
        }
    }

    /** Fast I/O helper class for competitive programming style inputs */
    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) throw new IOException("Unexpected end of input");
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input", e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }
    }

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner();
        PrintWriter out = new PrintWriter(System.out);

        try {
            int n = scanner.nextInt();
            int m = scanner.nextInt();

            int[][] grid = new int[n][m];
            boolean hasStar = false;

            // Read grid and convert characters to binary representation
            for (int i = 0; i < n; i++) {
                String line = scanner.next();
                for (int j = 0; j < m; j++) {
                    grid[i][j] = (line.charAt(j) == '*') ? 1 : 0;
                    if (grid[i][j] == 1) hasStar = true;
                }
            }

            // If no stars exist, output 0 and exit
            if (!hasStar) {
                out.println(0);
                out.flush();
                return;
            }

            // Compute directional distances for each cell
            int[][] left = new int[n][m];
            int[][] right = new int[n][m];
            int[][] up = new int[n][m];
            int[][] down = new int[n][m];

            computeDistancesForward(grid, left, up);
            computeDistancesBackward(grid, right, down);

            ArrayList<Cross> crosses = new ArrayList<>();
            boolean[][] consumed = new boolean[n][m];

            // Identify crosses and mark consumed cells
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    if (grid[i][j] == 1 && !consumed[i][j]) {
                        int minDist = Math.min(left[i][j], Math.min(right[i][j], Math.min(up[i][j], down[i][j])));

                        // A valid cross requires at least one '*' on each side of the center
                        if (minDist > 1) {
                            int armLength = minDist - 1;
                            crosses.add(new Cross(i + 1, j + 1, armLength));

                            // Mark the center and its arms as consumed
                            for (int k = 1; k <= armLength; k++) {
                                consumed[i - k][j] = true;
                                consumed[i + k][j] = true;
                                consumed[i][j - k] = true;
                                consumed[i][j + k] = true;
                            }
                            consumed[i][j] = true; // Center star
                        }
                    }
                }
            }

            if (crosses.isEmpty()) {
                out.println(-1);
            } else {
                // Verify all '*' in the grid were consumed by a valid cross
                if (areAllStarsConsumed(grid, consumed, n, m)) {
                    out.println(crosses.size());
                    for (Cross c : crosses) {
                        out.println(c.row + " " + c.col + " " + c.length);
                    }
                } else {
                    out.println(-1);
                }
            }

        } catch (Exception e) {
            e.printStackTrace();
        } finally {
            out.flush();
        }
    }

    /** Computes consecutive '*' counts from the left and top edges */
    private static void computeDistancesForward(int[][] grid, int[][] left, int[][] up) {
        int n = grid.length;
        int m = grid[0].length;

        for (int i = 0; i < n; i++) {
            left[i][0] = grid[i][0];
            for (int j = 1; j < m; j++) {
                left[i][j] = (grid[i][j] == 0) ? 0 : left[i][j - 1] + 1;
            }
        }

        for (int j = 0; j < m; j++) {
            up[0][j] = grid[0][j];
            for (int i = 1; i < n; i++) {
                up[i][j] = (grid[i][j] == 0) ? 0 : up[i - 1][j] + 1;
            }
        }
    }

    /** Computes consecutive '*' counts from the right and bottom edges */
    private static void computeDistancesBackward(int[][] grid, int[][] right, int[][] down) {
        int n = grid.length;
        int m = grid[0].length;

        for (int i = 0; i < n; i++) {
            right[i][m - 1] = grid[i][m - 1];
            for (int j = m - 2; j >= 0; j--) {
                right[i][j] = (grid[i][j] == 0) ? 0 : right[i][j + 1] + 1;
            }
        }

        for (int j = 0; j < m; j++) {
            down[n - 1][j] = grid[n - 1][j];
            for (int i = n - 2; i >= 0; i--) {
                down[i][j] = (grid[i][j] == 0) ? 0 : down[i + 1][j] + 1;
            }
        }
    }

    /** Checks if every '*' in the grid has been marked as consumed */
    private static boolean areAllStarsConsumed(int[][] grid, boolean[][] consumed, int n, int m) {
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == 1 && !consumed[i][j]) {
                    return false;
                }
            }
        }
        return true;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.ArrayList;
import java.util.StringTokenizer;

public class Solution {

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner();
        PrintWriter out = new PrintWriter(System.out);

        // Original code hardcodes 1 test case. Structured here for easy extension.
        int testCases = 1;
        for (int t = 0; t < testCases; t++) {
            solve(scanner, out);
        }

        out.flush();
        out.close();
    }

    /**
     * Orchestrates the solution for a single test case.
     */
    private static void solve(FastScanner scanner, PrintWriter out) {
        int n = scanner.nextInt();
        int m = scanner.nextInt();

        char[][] grid = new char[n][];
        for (int i = 0; i < n; i++) {
            grid[i] = scanner.next().toCharArray();
        }

        // 1. Compute distances to the nearest edge/obstacle in all 4 directions
        int[][] distUp = new int[n][m];
        int[][] distDown = new int[n][m];
        int[][] distLeft = new int[n][m];
        int[][] distRight = new int[n][m];

        computeDirectionalDistances(grid, n, m, distUp, distDown, distLeft, distRight);

        // 2. Identify valid squares and mark coverage using difference arrays
        ArrayList<Square> validSquares = new ArrayList<>();
        int[][] verticalCoverage = new int[n][m];
        int[][] horizontalCoverage = new int[n][m];

        identifyAndMarkSquares(grid, n, m, distUp, distDown, distLeft, distRight,
                verticalCoverage, horizontalCoverage, validSquares);

        // 3. Convert difference arrays to actual coverage counts via prefix sums
        computePrefixSums(n, m, verticalCoverage, horizontalCoverage);

        // 4. Validate that every '*' cell is covered by at least one square in both dimensions
        if (hasUncoveredStar(grid, n, m, verticalCoverage, horizontalCoverage)) {
            out.println(-1);
            return;
        }

        // 5. Output results
        out.println(validSquares.size());
        for (Square sq : validSquares) {
            out.println(sq.row + " " + sq.col + " " + sq.size);
        }
    }

    /**
     * Calculates the number of consecutive '*' cells extending from each position
     * in the four cardinal directions.
     */
    private static void computeDirectionalDistances(char[][] grid, int n, int m,
                                                    int[][] distUp, int[][] distDown,
                                                    int[][] distLeft, int[][] distRight) {
        // Forward pass: Up & Left
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == '*') {
                    distUp[i][j] = (i > 0) ? distUp[i - 1][j] + 1 : 1;
                    distLeft[i][j] = (j > 0) ? distLeft[i][j - 1] + 1 : 1;
                } else {
                    distUp[i][j] = 0;
                    distLeft[i][j] = 0;
                }
            }
        }

        // Backward pass: Down & Right
        for (int i = n - 1; i >= 0; i--) {
            for (int j = m - 1; j >= 0; j--) {
                if (grid[i][j] == '*') {
                    distDown[i][j] = (i < n - 1) ? distDown[i + 1][j] + 1 : 1;
                    distRight[i][j] = (j < m - 1) ? distRight[i][j + 1] + 1 : 1;
                } else {
                    distDown[i][j] = 0;
                    distRight[i][j] = 0;
                }
            }
        }
    }

    /**
     * Finds maximal squares centered at '*' cells and applies difference array updates.
     */
    private static void identifyAndMarkSquares(char[][] grid, int n, int m,
                                               int[][] distUp, int[][] distDown,
                                               int[][] distLeft, int[][] distRight,
                                               int[][] verticalCoverage, int[][] horizontalCoverage,
                                               ArrayList<Square> validSquares) {
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == '*') {
                    // The maximum square size is limited by the shortest distance to an edge/obstacle
                    int size = Math.min(Math.min(distUp[i][j], distDown[i][j]),
                            Math.min(distLeft[i][j], distRight[i][j])) - 1;

                    if (size > 0) {
                        applyDifferenceArrays(i, j, size, n, m, verticalCoverage, horizontalCoverage);
                        validSquares.add(new Square(i + 1, j + 1, size));
                    }
                }
            }
        }
    }

    /**
     * Applies range updates to difference arrays for vertical and horizontal coverage.
     * This allows O(1) marking of square spans before computing prefix sums.
     */
    private static void applyDifferenceArrays(int row, int col, int size, int n, int m,
                                              int[][] verticalCoverage, int[][] horizontalCoverage) {
        // Vertical span: marks column 'col' from row 'row-size' to 'row+size'
        int top = row - size;
        int bottomExclusive = row + size + 1;
        verticalCoverage[top][col]++;
        if (bottomExclusive < n) {
            verticalCoverage[bottomExclusive][col]--;
        }

        // Horizontal span: marks row 'row' from col 'col-size' to 'col+size'
        int left = col - size;
        int rightExclusive = col + size + 1;
        horizontalCoverage[row][left]++;
        if (rightExclusive < m) {
            horizontalCoverage[row][rightExclusive]--;
        }
    }

    /**
     * Computes prefix sums to convert difference arrays into actual coverage counts.
     */
    private static void computePrefixSums(int n, int m, int[][] verticalCoverage, int[][] horizontalCoverage) {
        // Column-wise prefix sums for vertical coverage
        for (int j = 0; j < m; j++) {
            for (int i = 1; i < n; i++) {
                verticalCoverage[i][j] += verticalCoverage[i - 1][j];
            }
        }
        // Row-wise prefix sums for horizontal coverage
        for (int i = 0; i < n; i++) {
            for (int j = 1; j < m; j++) {
                horizontalCoverage[i][j] += horizontalCoverage[i][j - 1];
            }
        }
    }

    /**
     * Checks if any '*' cell remains uncovered in both vertical and horizontal dimensions.
     */
    private static boolean hasUncoveredStar(char[][] grid, int n, int m,
                                            int[][] verticalCoverage, int[][] horizontalCoverage) {
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == '*' && verticalCoverage[i][j] == 0 && horizontalCoverage[i][j] == 0) {
                    return true;
                }
            }
        }
        return false;
    }

    /**
     * Immutable value class representing a valid square.
     */
    private static class Square {
        final int row;
        final int col;
        final int size;

        Square(int row, int col, int size) {
            this.row = row;
            this.col = col;
            this.size = size;
        }
    }

    /**
     * Optimized input reader for competitive programming / fast I/O scenarios.
     */
    private static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        public String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    e.printStackTrace();
                    return null;
                }
            }
            return st.nextToken();
        }

        public String nextLine() throws IOException {
            return br.readLine();
        }

        public int nextInt() {
            String token = next();
            if (token == null) throw new IllegalArgumentException("Unexpected end of input");
            return Integer.parseInt(token);
        }
    }
}

import java.io.*;
import java.util.StringTokenizer;

/**
 * Analyzes a 2D grid to identify star patterns, clears overlapping influences,
 * and outputs the results. Refactored for maintainability, readability, and resource safety.
 */
public class ProblemE {

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner(System.in);
        // Use try-with-resources to guarantee proper flushing and closing of output
        try (PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out))) {
            int n = scanner.nextInt();
            int m = scanner.nextInt();

            boolean[][] grid = readGrid(scanner, n, m);
            int[][] stars = identifyStarCenters(grid, n, m);
            clearStarInfluences(grid, stars, n, m);

            if (hasRemainingStars(grid, n, m)) {
                out.println(-1);
            } else {
                int count = countStars(stars, n, m);
                out.println(count);
                printStarDetails(stars, n, m, out);
            }
        }
    }

    /**
     * Reads the grid dimensions and character data from the scanner.
     */
    private static boolean[][] readGrid(FastScanner scanner, int n, int m) {
        boolean[][] grid = new boolean[n][m];
        for (int i = 0; i < n; i++) {
            String line = scanner.next();
            for (int j = 0; j < m; j++) {
                grid[i][j] = line.charAt(j) == '*';
            }
        }
        return grid;
    }

    /**
     * Computes directional consecutive '*' counts and identifies valid star centers.
     * A star center is valid if it has consecutive '*' in all four directions with min length > 1.
     */
    private static int[][] identifyStarCenters(boolean[][] grid, int n, int m) {
        int[][] top = new int[n][m];
        int[][] left = new int[n][m];

        // Forward passes: top and left
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j]) {
                    top[i][j] = (i == 0) ? 1 : top[i - 1][j] + 1;
                    left[i][j] = (j == 0) ? 1 : left[i][j - 1] + 1;
                }
            }
        }

        int[][] bottom = new int[n][m];
        int[][] right = new int[n][m];

        // Backward passes: bottom and right
        for (int i = n - 1; i >= 0; i--) {
            for (int j = m - 1; j >= 0; j--) {
                if (grid[i][j]) {
                    bottom[i][j] = (i == n - 1) ? 1 : bottom[i + 1][j] + 1;
                    right[i][j] = (j == m - 1) ? 1 : right[i][j + 1] + 1;
                }
            }
        }

        // Determine star sizes
        int[][] stars = new int[n][m];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j]) {
                    int minConsecutive = Math.min(
                            Math.min(top[i][j], bottom[i][j]),
                            Math.min(left[i][j], right[i][j])
                    );
                    if (minConsecutive > 1) {
                        stars[i][j] = minConsecutive - 1;
                    }
                }
            }
        }
        return stars;
    }

    /**
     * Clears grid cells influenced by identified stars in all four cardinal directions.
     */
    private static void clearStarInfluences(boolean[][] grid, int[][] stars, int n, int m) {
        clearRows(grid, stars, n, m);
        clearCols(grid, stars, n, m);
    }

    private static void clearRows(boolean[][] grid, int[][] stars, int n, int m) {
        for (int i = 0; i < n; i++) {
            clearLine(grid, stars, i, 0, m, 1);   // Left to Right
            clearLine(grid, stars, i, m - 1, -1, -1); // Right to Left
        }
    }

    private static void clearCols(boolean[][] grid, int[][] stars, int n, int m) {
        for (int j = 0; j < m; j++) {
            clearLine(grid, stars, j, 0, n, 1);   // Top to Bottom
            clearLine(grid, stars, j, n - 1, -1, -1); // Bottom to Top
        }
    }

    /**
     * Propagates star influence along a single row or column.
     * @param fixedIdx Index of the fixed axis (row or column)
     * @param start    Starting index for the iteration
     * @param end      Exclusive end index for the iteration
     * @param step     Direction step (+1 or -1)
     */
    private static void clearLine(boolean[][] grid, int[][] stars, int fixedIdx, int start, int end, int step) {
        int activeRange = 0;
        for (int idx = start; idx != end; idx += step) {
            if (activeRange > 0) {
                activeRange--;
                grid[idx][fixedIdx] = false;
            }
            if (stars[idx][fixedIdx] > 0) {
                activeRange = Math.max(activeRange, stars[idx][fixedIdx]);
                grid[idx][fixedIdx] = false;
            }
        }
    }

    /**
     * Checks if any '*' remains in the grid after influence clearing.
     */
    private static boolean hasRemainingStars(boolean[][] grid, int n, int m) {
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j]) {
                    return true;
                }
            }
        }
        return false;
    }

    /**
     * Counts the number of valid star centers.
     */
    private static int countStars(int[][] stars, int n, int m) {
        int count = 0;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (stars[i][j] > 0) {
                    count++;
                }
            }
        }
        return count;
    }

    /**
     * Outputs the 1-based coordinates and size of each star center.
     */
    private static void printStarDetails(int[][] stars, int n, int m, PrintWriter out) {
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (stars[i][j] > 0) {
                    out.println((i + 1) + " " + (j + 1) + " " + stars[i][j]);
                }
            }
        }
    }

    /**
     * Fast input scanner for competitive programming / high-throughput I/O.
     */
    private static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        public String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) {
                        return null;
                    }
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input stream", e);
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.*;
import java.util.*;

public class Main {
    private static final char WALL = '#';
    private static final char EMPTY = '.';

    public static void main(String[] args) {
        FastReader sc = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            int rows = sc.nextInt();
            int cols = sc.nextInt();

            boolean[][] grid = readGrid(rows, cols, sc);

            // Compute directional distances for each cell
            int[][] rightDist = computeRightDists(grid, rows, cols);
            int[][] topDist = computeTopDists(grid, rows, cols);
            int[][] leftDist = computeLeftDists(grid, rows, cols);
            int[][] bottomDist = computeBottomDists(grid, rows, cols);

            boolean[][] covered = new boolean[rows][cols];
            int crossCount = 0;
            StringBuilder result = new StringBuilder();

            // Iterate over each cell to place crosses
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c]) {
                        // Find the maximum radius for a cross centered at (r, c)
                        int minDist = Math.min(Math.min(rightDist[r][c], leftDist[r][c]),
                                               Math.min(topDist[r][c], bottomDist[r][c]));
                        int radius = minDist - 1;

                        if (radius > 0) {
                            crossCount++;
                            result.append(r + 1).append(' ').append(c + 1).append(' ').append(radius).append('\n');
                            markCross(covered, r, c, radius, rows, cols);
                        }
                    }
                }
            }

            // Verify if all wall cells are covered by at least one cross
            if (allWallsCovered(grid, covered, rows, cols)) {
                out.println(crossCount);
                out.print(result);
            } else {
                out.println(-1);
            }
        } catch (Exception e) {
            out.println(-1);
        } finally {
            out.flush();
        }
    }

    private static boolean[][] readGrid(int rows, int cols, FastReader sc) {
        boolean[][] grid = new boolean[rows][cols];
        for (int r = 0; r < rows; r++) {
            String line = sc.next();
            for (int c = 0; c < cols; c++) {
                grid[r][c] = line.charAt(c) == WALL;
            }
        }
        return grid;
    }

    private static int[][] computeRightDists(boolean[][] grid, int rows, int cols) {
        int[][] dist = new int[rows][cols];
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c]) {
                    dist[r][c] = (c > 0) ? dist[r][c - 1] + 1 : 1;
                }
            }
        }
        return dist;
    }

    private static int[][] computeTopDists(boolean[][] grid, int rows, int cols) {
        int[][] dist = new int[rows][cols];
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c]) {
                    dist[r][c] = (r > 0) ? dist[r - 1][c] + 1 : 1;
                }
            }
        }
        return dist;
    }

    private static int[][] computeLeftDists(boolean[][] grid, int rows, int cols) {
        int[][] dist = new int[rows][cols];
        for (int r = 0; r < rows; r++) {
            for (int c = cols - 1; c >= 0; c--) {
                if (grid[r][c]) {
                    dist[r][c] = (c < cols - 1) ? dist[r][c + 1] + 1 : 1;
                }
            }
        }
        return dist;
    }

    private static int[][] computeBottomDists(boolean[][] grid, int rows, int cols) {
        int[][] dist = new int[rows][cols];
        for (int r = rows - 1; r >= 0; r--) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c]) {
                    dist[r][c] = (r < rows - 1) ? dist[r + 1][c] + 1 : 1;
                }
            }
        }
        return dist;
    }

    private static void markCross(boolean[][] covered, int centerR, int centerC, int radius, int rows, int cols) {
        // Mark vertical arm with safe boundary checks
        int rStart = Math.max(0, centerR - radius);
        int rEnd = Math.min(rows - 1, centerR + radius);
        for (int r = rStart; r <= rEnd; r++) {
            covered[r][centerC] = true;
        }

        // Mark horizontal arm with safe boundary checks
        int cStart = Math.max(0, centerC - radius);
        int cEnd = Math.min(cols - 1, centerC + radius);
        for (int c = cStart; c <= cEnd; c++) {
            covered[centerR][c] = true;
        }
    }

    private static boolean allWallsCovered(boolean[][] grid, boolean[][] covered, int rows, int cols) {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] && !covered[r][c]) {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Fast I/O helper class for competitive programming style input reading.
     */
    private static class FastReader {
        BufferedReader br;
        StringTokenizer st;

        public FastReader(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            String s = next();
            if (s == null) throw new NoSuchElementException();
            return Integer.parseInt(s);
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayList;
import java.util.List;
import java.util.StringTokenizer;

/**
 * Solution class to process grid patterns and identify crosses.
 * Refactored for better maintainability, readability, and structure.
 */
public class Solution {

    /**
     * FastReader class for efficient input handling.
     * Encapsulates BufferedReader and StringTokenizer logic to avoid cluttering the main logic.
     */
    static class FastReader {
        BufferedReader br;
        StringTokenizer st;

        public FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    e.printStackTrace();
                    return null;
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            String s = next();
            return (s == null) ? 0 : Integer.parseInt(s);
        }
    }

    /**
     * Helper class to store cross coordinates and radius.
     * Made static to avoid implicit reference to the outer class instance.
     */
    static class Triplet {
        int x, y, radius;

        public Triplet(int x, int y, int radius) {
            this.x = x;
            this.y = y;
            this.radius = radius;
        }
    }

    public static void main(String[] args) {
        new Solution().run();
    }

    public void run() {
        FastReader sc = new FastReader();

        // Read dimensions n and m
        String nStr = sc.next();
        if (nStr == null) return; // Handle empty input gracefully
        int n = Integer.parseInt(nStr);
        int m = sc.nextInt();

        // Read the grid
        // Using int[][] for grid (0 for empty, 1 for star)
        int[][] grid = new int[n][m];
        for (int i = 0; i < n; i++) {
            String row = sc.next();
            // Ensure we don't go out of bounds if row string is short
            int len = (row != null) ? row.length() : 0;
            for (int j = 0; j < m && j < len; j++) {
                if (row.charAt(j) == '*') {
                    grid[i][j] = 1;
                }
            }
        }

        // Arrays to store distance to nearest edge/non-star in each direction
        // up[i][j] stores the number of consecutive stars ending at (i, j) going upwards
        int[][] up = new int[n][m];
        int[][] down = new int[n][m];
        int[][] left = new int[n][m];
        int[][] right = new int[n][m];

        // Compute Up distances
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == 1) {
                    up[i][j] = (i > 0 ? up[i - 1][j] : 0) + 1;
                }
            }
        }

        // Compute Down distances
        for (int i = n - 1; i >= 0; i--) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == 1) {
                    down[i][j] = (i < n - 1 ? down[i + 1][j] : 0) + 1;
                }
            }
        }

        // Compute Left distances
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == 1) {
                    left[i][j] = (j > 0 ? left[i][j - 1] : 0) + 1;
                }
            }
        }

        // Compute Right distances
        for (int i = 0; i < n; i++) {
            for (int j = m - 1; j >= 0; j--) {
                if (grid[i][j] == 1) {
                    right[i][j] = (j < m - 1 ? right[i][j + 1] : 0) + 1;
                }
            }
        }

        List<Triplet> crosses = new ArrayList<>();
        int[][] map = new int[n][m]; // To store the reconstructed pattern

        // Identify crosses and mark the map
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == 1) {
                    // Find the limiting distance (radius + 1)
                    int minDist = Math.min(up[i][j], down[i][j]);
                    minDist = Math.min(minDist, Math.min(left[i][j], right[i][j]));

                    // The radius is minDist - 1 (since minDist includes the center cell)
                    // Based on original logic: if (min >= 1) after decrement, 
                    // this implies radius >= 1.
                    int radius = minDist - 1;

                    if (radius >= 1) {
                        // Store 1-based coordinates
                        crosses.add(new Triplet(i + 1, j + 1, radius));

                        // Mark horizontal arm
                        for (int k = j - radius; k <= j + radius; k++) {
                            map[i][k] = 1;
                        }
                        // Mark vertical arm
                        for (int k = i - radius; k <= i + radius; k++) {
                            map[k][j] = 1;
                        }
                    }
                }
            }
        }

        // Validate if the reconstructed map matches the original grid
        boolean ok = true;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (map[i][j] != grid[i][j]) {
                    ok = false;
                    break;
                }
            }
            if (!ok) break;
        }

        // Prepare output
        StringBuilder sb = new StringBuilder();
        if (!ok) {
            sb.append("-1\n");
        } else {
            sb.append(crosses.size()).append("\n");
            for (Triplet t : crosses) {
                sb.append(t.x).append(" ").append(t.y).append(" ").append(t.radius).append("\n");
            }
        }
        System.out.print(sb);
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.ArrayList;
import java.util.List;
import java.util.PriorityQueue;
import java.util.StringTokenizer;

/**
 * Solves a grid-based star coverage problem.
 * Computes directional star counts, identifies maximal star patterns,
 * marks covered regions, and validates full coverage.
 */
public class Main {

    // Direction indices for the DP table
    private static final int DIR_LEFT = 0;
    private static final int DIR_RIGHT = 1;
    private static final int DIR_UP = 2;
    private static final int DIR_DOWN = 3;

    /**
     * Represents a contiguous interval [start, end].
     * Used to track covered segments in rows or columns.
     */
    private static class Interval implements Comparable<Interval> {
        int start, end;

        public Interval(int start, int end) {
            this.start = start;
            this.end = end;
        }

        @Override
        public int compareTo(Interval o) {
            return Integer.compare(this.start, o.start);
        }
    }

    /**
     * Represents a discovered star pattern at a specific grid coordinate.
     */
    private static class StarPattern {
        int row, col, size;

        public StarPattern(int row, int col, int size) {
            this.row = row;
            this.col = col;
            this.size = size;
        }
    }

    public static void main(String[] args) {
        FastReader sc = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            String nStr = sc.next();
            if (nStr == null) return;
            int n = Integer.parseInt(nStr);
            int m = sc.nextInt();

            String[] grid = new String[n];
            for (int i = 0; i < n; i++) {
                grid[i] = sc.nextLine();
            }

            if (n == 0 || m == 0 || grid[0] == null || grid[0].length() < m) {
                out.println(-1);
                return;
            }

            int[][][] dp = computeDirectionCounts(grid);
            List<StarPattern> stars = new ArrayList<>();
            List<PriorityQueue<Interval>> rows = new ArrayList<>(n);
            List<PriorityQueue<Interval>> cols = new ArrayList<>(m);

            for (int i = 0; i < n; i++) rows.add(new PriorityQueue<>());
            for (int j = 0; j < m; j++) cols.add(new PriorityQueue<>());

            findStars(grid, dp, stars, rows, cols);
            boolean[][] ans = markCoveredCells(grid, rows, cols);

            if (!isAllStarsCovered(grid, ans)) {
                out.println(-1);
            } else {
                out.println(stars.size());
                for (StarPattern star : stars) {
                    // Output uses 1-based indexing as per typical competitive programming conventions
                    out.println((star.row + 1) + " " + (star.col + 1) + " " + star.size);
                }
            }
        } catch (Exception e) {
            out.println(-1);
        } finally {
            out.flush();
        }
    }

    /**
     * Computes the number of consecutive '*' characters in all four directions
     * for each cell in the grid using dynamic programming.
     */
    private static int[][][] computeDirectionCounts(String[] grid) {
        int n = grid.length;
        int m = grid[0].length();
        int[][][] dp = new int[n][m][4];

        // Left to Right
        for (int i = 0; i < n; i++) {
            for (int j = 1; j < m; j++) {
                dp[i][j][DIR_LEFT] = (grid[i].charAt(j - 1) == '*' ? dp[i][j - 1][DIR_LEFT] + 1 : 0);
            }
        }

        // Right to Left
        for (int i = 0; i < n; i++) {
            for (int j = m - 2; j >= 0; j--) {
                dp[i][j][DIR_RIGHT] = (grid[i].charAt(j + 1) == '*' ? dp[i][j + 1][DIR_RIGHT] + 1 : 0);
            }
        }

        // Top to Bottom
        for (int i = 1; i < n; i++) {
            for (int j = 0; j < m; j++) {
                dp[i][j][DIR_UP] = (grid[i - 1].charAt(j) == '*' ? dp[i - 1][j][DIR_UP] + 1 : 0);
            }
        }

        // Bottom to Top
        for (int i = n - 2; i >= 0; i--) {
            for (int j = 0; j < m; j++) {
                dp[i][j][DIR_DOWN] = (grid[i + 1].charAt(j) == '*' ? dp[i + 1][j][DIR_DOWN] + 1 : 0);
            }
        }

        return dp;
    }

    /**
     * Identifies valid star patterns and populates row/column interval queues.
     */
    private static void findStars(String[] grid, int[][][] dp,
                                  List<StarPattern> stars,
                                  List<PriorityQueue<Interval>> rows,
                                  List<PriorityQueue<Interval>> cols) {
        int n = grid.length;
        int m = grid[0].length();

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i].charAt(j) == '*') {
                    int maxSize = Math.min(Math.min(dp[i][j][DIR_LEFT], dp[i][j][DIR_RIGHT]),
                            Math.min(dp[i][j][DIR_UP], dp[i][j][DIR_DOWN]));

                    if (maxSize > 0) {
                        stars.add(new StarPattern(i, j, maxSize));
                        rows.get(i).add(new Interval(j - maxSize, j + maxSize));
                        cols.get(j).add(new Interval(i - maxSize, i + maxSize));
                    }
                }
            }
        }
    }

    /**
     * Processes interval queues to mark all covered cells in the answer matrix.
     * Uses a greedy sweep-line approach to merge overlapping intervals.
     */
    private static boolean[][] markCoveredCells(String[] grid,
                                                List<PriorityQueue<Interval>> rows,
                                                List<PriorityQueue<Interval>> cols) {
        int n = grid.length;
        int m = grid[0].length();
        boolean[][] ans = new boolean[n][m];

        // Process row intervals
        for (int i = 0; i < n; i++) {
            int maxEnd = 0;
            PriorityQueue<Interval> pq = rows.get(i);
            while (!pq.isEmpty()) {
                Interval curr = pq.poll();
                int start = Math.max(curr.start, maxEnd);
                int end = curr.end;
                for (int j = start; j <= end; j++) {
                    if (j >= 0 && j < m) {
                        ans[i][j] = true;
                    }
                }
                maxEnd = Math.max(maxEnd, end);
            }
        }

        // Process column intervals
        for (int j = 0; j < m; j++) {
            int maxEnd = 0;
            PriorityQueue<Interval> pq = cols.get(j);
            while (!pq.isEmpty()) {
                Interval curr = pq.poll();
                int start = Math.max(curr.start, maxEnd);
                int end = curr.end;
                for (int i = start; i <= end; i++) {
                    if (i >= 0 && i < n) {
                        ans[i][j] = true;
                    }
                }
                maxEnd = Math.max(maxEnd, end);
            }
        }

        return ans;
    }

    /**
     * Validates that every '*' in the original grid is marked as covered.
     */
    private static boolean isAllStarsCovered(String[] grid, boolean[][] ans) {
        int n = grid.length;
        int m = grid[0].length();
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i].charAt(j) == '*' && !ans[i][j]) {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Fast I/O helper for competitive programming and large inputs.
     */
    static class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastReader(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in), 32768);
        }

        public String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            String s = next();
            return (s == null) ? 0 : Integer.parseInt(s);
        }

        public String nextLine() {
            // Consume remaining tokens on the current line if any
            if (st != null && st.hasMoreTokens()) {
                StringBuilder sb = new StringBuilder();
                while (st.hasMoreTokens()) {
                    sb.append(st.nextToken()).append(" ");
                }
                try {
                    String line = br.readLine();
                    return sb.toString().trim() + (line != null ? " " + line : "");
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            try {
                return br.readLine();
            } catch (IOException e) {
                throw new RuntimeException(e);
            }
        }
    }
}

import java.io.IOException;
import java.util.InputMismatchException;

public class E1015 {

    // Direction constants: UP, LEFT, RIGHT, DOWN
    private static final int UP = 0;
    private static final int LEFT = 1;
    private static final int RIGHT = 2;
    private static final int DOWN = 3;

    // Corresponding row and column deltas for each direction
    private static final int[] DR = {-1, 0, 0, 1};
    private static final int[] DC = {0, -1, 1, 0};

    public static void main(String[] args) {
        FasterScanner scanner = new FasterScanner();
        int n = scanner.nextInt();
        int m = scanner.nextInt();

        char[][] grid = new char[n][m];
        for (int i = 0; i < n; i++) {
            grid[i] = scanner.nextLine().toCharArray();
        }

        // Precompute the length of consecutive '*' arms in all 4 directions
        int[][][] armLengths = calculateArmLengths(grid, n, m);

        // Find valid crosses, record them, and mark covered cells
        CrossResult result = findAndMarkCrosses(grid, armLengths);

        // Validate that all '*' have been converted to '#'
        if (isFullyCovered(grid)) {
            System.out.println(result.count + "\n" + result.output);
        } else {
            System.out.println(-1);
        }
    }

    /**
     * Calculates the number of consecutive '*' cells extending from each '*' 
     * in the four cardinal directions.
     */
    private static int[][][] calculateArmLengths(char[][] grid, int n, int m) {
        int[][][] armLengths = new int[n][m][4];

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] != '*') continue;

                for (int d = 0; d < 4; d++) {
                    int count = 0;
                    int r = i + DR[d];
                    int c = j + DC[d];

                    while (r >= 0 && r < n && c >= 0 && c < m && grid[r][c] == '*') {
                        count++;
                        r += DR[d];
                        c += DC[d];
                    }
                    armLengths[i][j][d] = count;
                }
            }
        }
        return armLengths;
    }

    /**
     * Identifies valid cross shapes, records their coordinates and size,
     * and marks all participating '*' cells as '#' to prevent reuse.
     */
    private static CrossResult findAndMarkCrosses(char[][] grid, int[][][] armLengths) {
        StringBuilder output = new StringBuilder();
        int count = 0;

        for (int i = 0; i < grid.length; i++) {
            for (int j = 0; j < grid[i].length; j++) {
                // Skip already marked cells or non-star cells
                if (grid[i][j] != '*') continue;

                // A valid cross requires at least 1 '*' in all 4 directions
                int minArm = Math.min(Math.min(armLengths[i][j][UP], armLengths[i][j][LEFT]),
                                      Math.min(armLengths[i][j][RIGHT], armLengths[i][j][DOWN]));

                if (minArm > 0) {
                    count++;
                    output.append(i + 1).append(" ").append(j + 1).append(" ").append(minArm).append("\n");

                    // Mark center
                    grid[i][j] = '#';

                    // Mark arms
                    for (int d = 0; d < 4; d++) {
                        int r = i + DR[d];
                        int c = j + DC[d];
                        for (int k = 0; k < minArm; k++) {
                            grid[r][c] = '#';
                            r += DR[d];
                            c += DC[d];
                        }
                    }
                }
            }
        }
        return new CrossResult(count, output.toString());
    }

    /**
     * Checks if the grid contains any remaining unmarked '*' cells.
     */
    private static boolean isFullyCovered(char[][] grid) {
        for (char[] row : grid) {
            for (char cell : row) {
                if (cell == '*') return false;
            }
        }
        return true;
    }

    /**
     * Simple data carrier for cross-finding results.
     */
    private static class CrossResult {
        final int count;
        final String output;

        CrossResult(int count, String output) {
            this.count = count;
            this.output = output;
        }
    }

    /**
     * High-performance input scanner commonly used in competitive programming.
     */
    public static class FasterScanner {
        private byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;

        public int read() {
            if (numChars == -1)
                throw new InputMismatchException();
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = System.in.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0)
                    return -1;
            }
            return buf[curChar++];
        }

        public String nextLine() {
            int c = read();
            while (isSpaceChar(c))
                c = read();
            StringBuilder res = new StringBuilder();
            do {
                res.appendCodePoint(c);
                c = read();
            } while (!isEndOfLine(c));
            return res.toString();
        }

        public String nextString() {
            int c = read();
            while (isSpaceChar(c))
                c = read();
            StringBuilder res = new StringBuilder();
            do {
                res.appendCodePoint(c);
                c = read();
            } while (!isSpaceChar(c));
            return res.toString();
        }

        public long nextLong() {
            int c = read();
            while (isSpaceChar(c))
                c = read();
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            long res = 0;
            do {
                if (c < '0' || c > '9')
                    throw new InputMismatchException();
                res *= 10;
                res += c - '0';
                c = read();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public int nextInt() {
            int c = read();
            while (isSpaceChar(c))
                c = read();
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9')
                    throw new InputMismatchException();
                res *= 10;
                res += c - '0';
                c = read();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public int[] nextIntArray(int n) {
            int[] arr = new int[n];
            for (int i = 0; i < n; i++) {
                arr[i] = nextInt();
            }
            return arr;
        }

        public long[] nextLongArray(int n) {
            long[] arr = new long[n];
            for (int i = 0; i < n; i++) {
                arr[i] = nextLong();
            }
            return arr;
        }

        private boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        private boolean isEndOfLine(int c) {
            return c == '\n' || c == '\r' || c == -1;
        }
    }
}

import java.io.*;
import java.util.*;

public class StarsDrawing_CF1015E {

    public static void main(String[] args) {
        FastScanner sc = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            int rows = sc.nextInt();
            int cols = sc.nextInt();
            char[][] grid = new char[rows][cols];

            for (int i = 0; i < rows; i++) {
                grid[i] = sc.next().toCharArray();
            }

            // 1. Calculate consecutive stars in all four directions
            int[][] right = computeConsecutive(grid, Direction.RIGHT);
            int[][] left = computeConsecutive(grid, Direction.LEFT);
            int[][] down = computeConsecutive(grid, Direction.DOWN);
            int[][] up = computeConsecutive(grid, Direction.UP);

            // 2. Determine the maximum valid radius for each potential star center
            int[][] maxRadius = computeMaxRadius(grid, right, left, down, up);

            // 3. Validate coverage and format output
            validateAndOutput(rows, cols, grid, maxRadius, out);
        } catch (Exception e) {
            out.println(-1);
        } finally {
            out.flush();
            out.close();
        }
    }

    /**
     * Computes the number of consecutive stars ending at each cell in a given direction.
     */
    private static int[][] computeConsecutive(char[][] grid, Direction dir) {
        int rows = grid.length;
        int cols = grid[0].length;
        int[][] result = new int[rows][cols];

        if (dir == Direction.RIGHT) {
            for (int i = 0; i < rows; i++) {
                int count = 0;
                for (int j = 0; j < cols; j++) {
                    count = (grid[i][j] == '*') ? count + 1 : 0;
                    result[i][j] = count;
                }
            }
        } else if (dir == Direction.LEFT) {
            for (int i = 0; i < rows; i++) {
                int count = 0;
                for (int j = cols - 1; j >= 0; j--) {
                    count = (grid[i][j] == '*') ? count + 1 : 0;
                    result[i][j] = count;
                }
            }
        } else if (dir == Direction.DOWN) {
            for (int j = 0; j < cols; j++) {
                int count = 0;
                for (int i = 0; i < rows; i++) {
                    count = (grid[i][j] == '*') ? count + 1 : 0;
                    result[i][j] = count;
                }
            }
        } else if (dir == Direction.UP) {
            for (int j = 0; j < cols; j++) {
                int count = 0;
                for (int i = rows - 1; i >= 0; i--) {
                    count = (grid[i][j] == '*') ? count + 1 : 0;
                    result[i][j] = count;
                }
            }
        }
        return result;
    }

    /**
     * Calculates the maximum valid radius for a star centered at each grid cell.
     */
    private static int[][] computeMaxRadius(char[][] grid, int[][] right, int[][] left, int[][] down, int[][] up) {
        int rows = grid.length;
        int cols = grid[0].length;
        int[][] radius = new int[rows][cols];

        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == '*') {
                    radius[i][j] = Math.min(Math.min(right[i][j], left[i][j]), Math.min(down[i][j], up[i][j])) - 1;
                }
            }
        }
        return radius;
    }

    /**
     * Validates that every '*' is covered by at least one star using Segment Trees,
     * and prints the result.
     */
    private static void validateAndOutput(int rows, int cols, char[][] grid, int[][] maxRadius, PrintWriter out) {
        // Segment trees require power-of-2 logical sizes for efficient 1-based indexing
        int rowTreeSize = 1; while (rowTreeSize < cols) rowTreeSize <<= 1;
        int colTreeSize = 1; while (colTreeSize < rows) colTreeSize <<= 1;

        SegmentTree[] rowTrees = new SegmentTree[rows];
        SegmentTree[] colTrees = new SegmentTree[cols];

        for (int i = 0; i < rows; i++) rowTrees[i] = new SegmentTree(rowTreeSize);
        for (int j = 0; j < cols; j++) colTrees[j] = new SegmentTree(colTreeSize);

        // Apply range updates for each valid star
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                int r = maxRadius[i][j];
                if (r > 0) {
                    // Convert 0-based grid indices to 1-based Segment Tree indices
                    int left = j + 1 - r;
                    int right = j + 1 + r;
                    int top = i + 1 - r;
                    int bottom = i + 1 + r;

                    rowTrees[i].updateRange(left, right, 1);
                    colTrees[j].updateRange(top, bottom, 1);
                }
            }
        }

        // Validation: Every '*' must be covered by at least one star in its row and column
        boolean valid = true;
        for (int i = 0; i < rows && valid; i++) {
            for (int j = 0; j < cols && valid; j++) {
                if (grid[i][j] == '*') {
                    if (rowTrees[i].query(j + 1) < 1 || colTrees[j].query(i + 1) < 1) {
                        valid = false;
                    }
                }
            }
        }

        if (!valid) {
            out.println(-1);
        } else {
            StringBuilder sb = new StringBuilder();
            int count = 0;
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (maxRadius[i][j] > 0) {
                        sb.append(i + 1).append(' ').append(j + 1).append(' ').append(maxRadius[i][j]).append('\n');
                        count++;
                    }
                }
            }
            out.println(count);
            out.print(sb);
        }
    }

    /**
     * Segment Tree supporting Range Updates and Range/Point Queries with Lazy Propagation.
     * Uses 1-based indexing for all public API methods.
     */
    static class SegmentTree {
        private final int size;
        private final int[] tree;
        private final int[] lazy;

        public SegmentTree(int n) {
            this.size = n;
            this.tree = new int[n << 1];
            this.lazy = new int[n << 1];
        }

        public void updateRange(int l, int r, int val) {
            updateRange(1, 1, size, l, r, val);
        }

        private void updateRange(int node, int start, int end, int l, int r, int val) {
            if (l > end || r < start) return;
            if (l <= start && end <= r) {
                tree[node] += val * (end - start + 1);
                lazy[node] += val;
                return;
            }
            propagate(node, start, end);
            int mid = (start + end) / 2;
            updateRange(node << 1, start, mid, l, r, val);
            updateRange((node << 1) + 1, mid + 1, end, l, r, val);
            tree[node] = tree[node << 1] + tree[(node << 1) + 1];
        }

        private void propagate(int node, int start, int end) {
            if (lazy[node] == 0) return;
            int mid = (start + end) / 2;
            int leftChild = node << 1;
            int rightChild = (node << 1) + 1;

            lazy[leftChild] += lazy[node];
            tree[leftChild] += lazy[node] * (mid - start + 1);

            lazy[rightChild] += lazy[node];
            tree[rightChild] += lazy[node] * (end - mid);

            lazy[node] = 0;
        }

        public int query(int idx) {
            return query(1, 1, size, idx, idx);
        }

        public int query(int l, int r) {
            return query(1, 1, size, l, r);
        }

        private int query(int node, int start, int end, int l, int r) {
            if (l > end || r < start) return 0;
            if (l <= start && end <= r) return tree[node];
            propagate(node, start, end);
            int mid = (start + end) / 2;
            return query(node << 1, start, mid, l, r) + query((node << 1) + 1, mid + 1, end, l, r);
        }
    }

    /**
     * Fast I/O helper for competitive programming environments.
     */
    static class FastScanner {
        BufferedReader br;
        StringTokenizer st;

        public FastScanner(InputStream s) {
            br = new BufferedReader(new InputStreamReader(s));
        }

        public String next() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) return null;
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

        public int nextInt() throws IOException {
            String val = next();
            return val == null ? 0 : Integer.parseInt(val);
        }
    }

    private static enum Direction { RIGHT, LEFT, DOWN, UP }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.ArrayList;
import java.util.List;
import java.util.StringTokenizer;

/**
 * Solves the grid star-cross coverage problem.
 * Identifies all valid star crosses, marks grid coverage, and verifies
 * that every '*' in the grid is covered by at least one cross.
 */
public class StarCrossSolver {

    private static final char STAR_CHAR = '*';

    public static void main(String[] args) throws IOException {
        // Use try-with-resources for automatic resource management and flushing
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
             PrintWriter pw = new PrintWriter(System.out)) {
            new StarCrossSolver().solve(br, pw);
        }
    }

    public void solve(BufferedReader br, PrintWriter pw) throws IOException {
        FastScanner scanner = new FastScanner(br);
        int n = scanner.nextInt();
        int m = scanner.nextInt();

        char[][] grid = new char[n][m];
        for (int i = 0; i < n; i++) {
            grid[i] = scanner.next().toCharArray();
        }

        // Precompute consecutive star counts in all four cardinal directions
        int[][] rowPrefix = new int[n][m];
        int[][] rowSuffix = new int[n][m];
        int[][] colPrefix = new int[n][m];
        int[][] colSuffix = new int[n][m];

        computeDirectionalCounts(grid, rowPrefix, rowSuffix, colPrefix, colSuffix);

        // Arrays to mark the starting position and length of horizontal/vertical segments
        int[][] horizontalSegmentStarts = new int[n][m];
        int[][] verticalSegmentStarts = new int[n][m];
        List<Star> foundStars = new ArrayList<>();

        // Identify all valid star crosses
        for (int i = 1; i < n - 1; i++) {
            for (int j = 1; j < m - 1; j++) {
                if (grid[i][j] == STAR_CHAR) {
                    int minExtent = Math.min(rowPrefix[i][j - 1], rowSuffix[i][j + 1]);
                    minExtent = Math.min(minExtent, Math.min(colPrefix[i - 1][j], colSuffix[i + 1][j]));

                    if (minExtent > 0) {
                        int length = 2 * minExtent + 1;
                        // Mark horizontal segment starting at (i, j - minExtent)
                        horizontalSegmentStarts[i][j - minExtent] =
                                Math.max(horizontalSegmentStarts[i][j - minExtent], length);
                        // Mark vertical segment starting at (i - minExtent, j)
                        verticalSegmentStarts[i - minExtent][j] =
                                Math.max(verticalSegmentStarts[i - minExtent][j], length);

                        foundStars.add(new Star(i + 1, j + 1, minExtent));
                    }
                }
            }
        }

        // Determine which grid cells are covered by at least one segment
        boolean[][] isCovered = new boolean[n][m];
        markHorizontalCoverage(horizontalSegmentStarts, isCovered);
        markVerticalCoverage(verticalSegmentStarts, isCovered);

        // Verify that every '*' in the grid is covered
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == STAR_CHAR && !isCovered[i][j]) {
                    pw.println(-1);
                    return;
                }
            }
        }

        // Output results
        pw.println(foundStars.size());
        for (Star star : foundStars) {
            pw.println(star.x + " " + star.y + " " + star.s);
        }
    }

    /**
     * Computes the number of consecutive stars ending/starting at each cell
     * for rows (left-to-right, right-to-left) and columns (top-to-bottom, bottom-to-top).
     */
    private void computeDirectionalCounts(char[][] grid, int[][] rowPrefix, int[][] rowSuffix,
                                          int[][] colPrefix, int[][] colSuffix) {
        int n = grid.length;
        int m = grid[0].length;

        for (int i = 0; i < n; i++) {
            for (int j = 0, k = m - 1; j < m; j++, k--) {
                if (grid[i][j] == STAR_CHAR) {
                    rowPrefix[i][j] = (j == 0 ? 0 : rowPrefix[i][j - 1]) + 1;
                }
                if (grid[i][k] == STAR_CHAR) {
                    rowSuffix[i][k] = (k + 1 == m ? 0 : rowSuffix[i][k + 1]) + 1;
                }
            }
        }

        for (int j = 0; j < m; j++) {
            for (int i = 0, k = n - 1; i < n; i++, k--) {
                if (grid[i][j] == STAR_CHAR) {
                    colPrefix[i][j] = (i == 0 ? 0 : colPrefix[i - 1][j]) + 1;
                }
                if (grid[k][j] == STAR_CHAR) {
                    colSuffix[k][j] = (k + 1 == n ? 0 : colSuffix[k + 1][j]) + 1;
                }
            }
        }
    }

    /**
     * Propagates horizontal segment coverage across the grid.
     * Uses a sliding window approach based on stored segment lengths.
     */
    private void markHorizontalCoverage(int[][] starts, boolean[][] covered) {
        int n = covered.length;
        int m = covered[0].length;
        for (int i = 0; i < n; i++) {
            int active = 0;
            for (int j = 0; j < m; j++) {
                active = Math.max(active, starts[i][j]);
                if (active > 0) {
                    covered[i][j] = true;
                    active--;
                }
            }
        }
    }

    /**
     * Propagates vertical segment coverage across the grid.
     * Uses a sliding window approach based on stored segment lengths.
     */
    private void markVerticalCoverage(int[][] starts, boolean[][] covered) {
        int n = covered.length;
        int m = covered[0].length;
        for (int j = 0; j < m; j++) {
            int active = 0;
            for (int i = 0; i < n; i++) {
                active = Math.max(active, starts[i][j]);
                if (active > 0) {
                    covered[i][j] = true;
                    active--;
                }
            }
        }
    }

    /**
     * Immutable data class representing a found star cross.
     */
    public static class Star {
        final int x, y, s;

        public Star(int x, int y, int s) {
            this.x = x;
            this.y = y;
            this.s = s;
        }
    }

    /**
     * Fast input scanner using BufferedReader and StringTokenizer.
     * Replaces the original FastReader with a cleaner, exception-safe implementation.
     */
    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner(BufferedReader br) {
            this.br = br;
        }

        public String next() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) {
                    throw new IOException("Unexpected end of input");
                }
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}

import java.io.BufferedReader;
import java.io.BufferedOutputStream;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.OutputStream;
import java.io.PrintWriter;
import java.util.ArrayList;
import java.util.StringTokenizer;

public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;

        FastScanner in = new FastScanner(inputStream);
        PrintWriter out = new PrintWriter(new BufferedOutputStream(outputStream));

        StarGridSolver solver = new StarGridSolver();
        solver.solve(in, out);

        out.flush();
        out.close();
    }

    static class StarGridSolver {
        public void solve(FastScanner in, PrintWriter out) {
            int n = in.nextInt();
            int m = in.nextInt();

            char[][] grid = new char[n][m];
            for (int i = 0; i < n; i++) {
                grid[i] = in.next().toCharArray();
            }

            ArrayList<Star> stars = new ArrayList<>();
            boolean[][] visited = new boolean[n][m];

            // Identify all valid stars
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    if (grid[i][j] == '*') {
                        int armLength = findStarArmLength(grid, i, j, n, m);
                        if (armLength >= 0) {
                            stars.add(new Star(i + 1, j + 1, armLength));
                            markVisited(visited, i, j, armLength);
                        }
                    }
                }
            }

            // Verify that every '*' belongs to a valid star
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    if (grid[i][j] == '*' && !visited[i][j]) {
                        out.println(-1);
                        return;
                    }
                }
            }

            out.println(stars.size());
            for (Star star : stars) {
                out.println(star);
            }
        }

        /**
         * Calculates the maximum arm length of a star centered at (i, j).
         * Returns the arm length (number of '*' in one direction from center, excluding center).
         */
        private int findStarArmLength(char[][] grid, int i, int j, int n, int m) {
            // Maximum possible arm length is constrained by distance to grid edges
            int maxPossible = Math.min(Math.min(i, n - 1 - i), Math.min(j, m - 1 - j));
            int armLength = 0;

            while (armLength <= maxPossible) {
                if (grid[i + armLength][j] != '*' ||
                    grid[i - armLength][j] != '*' ||
                    grid[i][j + armLength] != '*' ||
                    grid[i][j - armLength] != '*') {
                    break;
                }
                armLength++;
            }
            return armLength - 1;
        }

        /**
         * Marks all cells belonging to a star as visited.
         * Bounds are guaranteed safe because armLength is validated by findStarArmLength.
         */
        private void markVisited(boolean[][] visited, int i, int j, int armLength) {
            for (int k = 0; k <= armLength; k++) {
                visited[i + k][j] = true;
                visited[i - k][j] = true;
                visited[i][j + k] = true;
                visited[i][j - k] = true;
            }
        }

        /**
         * Represents a detected star with 1-based coordinates.
         */
        static class Star {
            final int row;
            final int col;
            final int armLength;

            Star(int row, int col, int armLength) {
                this.row = row;
                this.col = col;
                this.armLength = armLength;
            }

            @Override
            public String toString() {
                return row + " " + col + " " + armLength;
            }
        }
    }

    /**
     * Fast input reader optimized for competitive programming.
     */
    static class FastScanner {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastScanner(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input", e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.OutputStream;
import java.io.PrintWriter;
import java.util.ArrayList;
import java.util.List;
import java.util.StringTokenizer;

public class Main {
    private static final char STAR = '*';
    private static final char EMPTY = '.';

    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        Task solver = new Task();
        solver.solve(1, in, out);
        out.close();
    }

    static class Task {
        public void solve(int testNumber, InputReader in, PrintWriter out) {
            int n = in.nextInt();
            int m = in.nextInt();
            char[][] grid = readGrid(in, n, m);

            List<Cross> crosses = findCrosses(grid, n, m);
            boolean[][] covered = new boolean[n][m];

            for (Cross cross : crosses) {
                cross.ray = extendRay(grid, covered, cross.x, cross.y, n, m);
            }

            if (hasUncoveredStars(grid, covered, n, m)) {
                out.println(-1);
            } else {
                out.println(crosses.size());
                for (Cross cross : crosses) {
                    out.println((cross.x + 1) + " " + (cross.y + 1) + " " + cross.ray);
                }
            }
        }

        private char[][] readGrid(InputReader in, int n, int m) {
            char[][] grid = new char[n][m];
            for (int i = 0; i < n; i++) {
                grid[i] = in.next().toCharArray();
            }
            return grid;
        }

        private List<Cross> findCrosses(char[][] grid, int n, int m) {
            List<Cross> crosses = new ArrayList<>();
            for (int i = 1; i < n - 1; i++) {
                for (int j = 1; j < m - 1; j++) {
                    if (isCrossCenter(grid, i, j)) {
                        crosses.add(new Cross(i, j));
                    }
                }
            }
            return crosses;
        }

        private boolean isCrossCenter(char[][] grid, int x, int y) {
            return grid[x][y] == STAR &&
                   grid[x - 1][y] == STAR && grid[x + 1][y] == STAR &&
                   grid[x][y - 1] == STAR && grid[x][y + 1] == STAR;
        }

        private int extendRay(char[][] grid, boolean[][] covered, int x, int y, int n, int m) {
            covered[x][y] = true;
            int maxRay = 0;
            // Calculate maximum possible ray length based on distance to grid boundaries
            int maxPossible = Math.min(Math.min(x, n - 1 - x), Math.min(y, m - 1 - y));

            for (int j = 1; j <= maxPossible; j++) {
                if (grid[x - j][y] != EMPTY && grid[x + j][y] != EMPTY &&
                    grid[x][y - j] != EMPTY && grid[x][y + j] != EMPTY) {
                    covered[x - j][y] = true;
                    covered[x + j][y] = true;
                    covered[x][y - j] = true;
                    covered[x][y + j] = true;
                    maxRay = j;
                } else {
                    break;
                }
            }
            return maxRay;
        }

        private boolean hasUncoveredStars(char[][] grid, boolean[][] covered, int n, int m) {
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    if (grid[i][j] == STAR && !covered[i][j]) {
                        return true;
                    }
                }
            }
            return false;
        }
    }

    static class Cross {
        final int x, y;
        int ray;

        Cross(int x, int y) {
            this.x = x;
            this.y = y;
        }
    }

    static class InputReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public Long nextLong() {
            return Long.parseLong(next());
        }

        public Double nextDouble() {
            return Double.parseDouble(next());
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.ArrayList;
import java.util.StringTokenizer;

/**
 * Analyzes a grid of stars and dots to determine if all stars can be covered
 * by cross-shaped patterns. Outputs the number of crosses and their details,
 * or -1 if complete coverage is impossible.
 */
public class StarGridAnalyzer {

    private static final char STAR = '*';
    private static final char EMPTY = '.';

    public static void main(String[] args) throws IOException {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter out = new PrintWriter(System.out);

        String line = reader.readLine();
        if (line == null) {
            out.flush();
            return;
        }
        StringTokenizer st = new StringTokenizer(line);
        int rows = Integer.parseInt(st.nextToken());
        int cols = Integer.parseInt(st.nextToken());

        char[][] grid = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            grid[i] = reader.readLine().toCharArray();
        }

        // Corners cannot be part of any cross. If a corner contains a star,
        // complete coverage is impossible.
        if (isCornerStar(grid, rows, cols)) {
            out.println(-1);
            out.flush();
            return;
        }

        // Precompute consecutive star counts in all 4 directions
        int[][] up = computeDirectionCounts(grid, -1, 0);
        int[][] down = computeDirectionCounts(grid, 1, 0);
        int[][] left = computeDirectionCounts(grid, 0, -1);
        int[][] right = computeDirectionCounts(grid, 0, 1);

        boolean[][] isCovered = new boolean[rows][cols];
        ArrayList<String> coverDetails = new ArrayList<>();

        // Identify valid cross centers and mark their coverage
        for (int row = 1; row < rows - 1; row++) {
            for (int col = 1; col < cols - 1; col++) {
                if (isCrossCenter(grid, row, col)) {
                    int armLength = calculateArmLength(up, down, left, right, row, col);
                    markCrossCoverage(row, col, armLength, isCovered);
                    coverDetails.add(formatCover(row + 1, col + 1, armLength));
                }
            }
        }

        // Verify if every star in the grid is covered by at least one cross
        if (verifyCoverage(grid, isCovered)) {
            out.println(coverDetails.size());
            for (String detail : coverDetails) {
                out.println(detail);
            }
        } else {
            out.println(-1);
        }

        out.flush();
    }

    /**
     * Checks if any corner of the grid contains a star.
     */
    private static boolean isCornerStar(char[][] grid, int rows, int cols) {
        return grid[0][0] == STAR || grid[0][cols - 1] == STAR ||
               grid[rows - 1][0] == STAR || grid[rows - 1][cols - 1] == STAR;
    }

    /**
     * Computes the count of consecutive stars in a given direction for each cell.
     * Traversal order is determined by the direction vector to ensure correct DP dependency.
     *
     * @param dr Direction row step (-1 for up, 1 for down)
     * @param dc Direction col step (-1 for left, 1 for right)
     */
    private static int[][] computeDirectionCounts(char[][] grid, int dr, int dc) {
        int rows = grid.length;
        int cols = grid[0].length;
        int[][] counts = new int[rows][cols];

        int startR = dr == 1 ? rows - 1 : 0;
        int endR = dr == 1 ? -1 : rows;
        int stepR = dr == 1 ? -1 : 1;

        int startC = dc == 1 ? cols - 1 : 0;
        int endC = dc == 1 ? -1 : cols;
        int stepC = dc == 1 ? -1 : 1;

        for (int r = startR; r != endR; r += stepR) {
            for (int c = startC; c != endC; c += stepC) {
                if (grid[r][c] == EMPTY) {
                    counts[r][c] = 0;
                } else {
                    int prevR = r + dr;
                    int prevC = c + dc;
                    if (prevR < 0 || prevR >= rows || prevC < 0 || prevC >= cols) {
                        counts[r][c] = 1;
                    } else {
                        counts[r][c] = counts[prevR][prevC] + 1;
                    }
                }
            }
        }
        return counts;
    }

    /**
     * Checks if a cell is the center of a valid cross (center and all 4 orthogonal neighbors are stars).
     */
    private static boolean isCrossCenter(char[][] grid, int row, int col) {
        return grid[row][col] == STAR &&
               grid[row - 1][col] == STAR && grid[row + 1][col] == STAR &&
               grid[row][col - 1] == STAR && grid[row][col + 1] == STAR;
    }

    /**
     * Calculates the maximum arm length for a cross centered at (row, col).
     * The length is limited by the shortest consecutive star sequence in any of the 4 directions.
     */
    private static int calculateArmLength(int[][] up, int[][] down, int[][] left, int[][] right, int row, int col) {
        return Math.min(Math.min(up[row][col], down[row][col]),
                        Math.min(left[row][col], right[row][col])) - 1;
    }

    /**
     * Marks all cells covered by a cross centered at (row, col) with the given arm length.
     */
    private static void markCrossCoverage(int row, int col, int armLength, boolean[][] isCovered) {
        for (int offset = 0; offset <= armLength; offset++) {
            isCovered[row + offset][col] = true;
            isCovered[row - offset][col] = true;
            isCovered[row][col + offset] = true;
            isCovered[row][col - offset] = true;
        }
    }

    /**
     * Verifies that every star in the grid is covered by at least one cross.
     */
    private static boolean verifyCoverage(char[][] grid, boolean[][] isCovered) {
        for (int i = 0; i < grid.length; i++) {
            for (int j = 0; j < grid[0].length; j++) {
                if (grid[i][j] == STAR && !isCovered[i][j]) {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Formats the output string for a single cross cover.
     */
    private static String formatCover(int row, int col, int armLength) {
        return row + " " + col + " " + armLength;
    }
}

import java.io.*;
import java.util.*;

/**
 * Solves the grid cross-filling problem.
 * Reads a grid of characters, computes directional consecutive counts,
 * applies cross operations, and verifies full coverage.
 */
public class E984 {

    /**
     * Fast input scanner optimized for competitive programming.
     */
    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer tokenizer;

        public FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input", e);
                }
            }
            return tokenizer.nextToken();
        }

        int nextInt() {
            String token = next();
            return token == null ? 0 : Integer.parseInt(token);
        }
    }

    /**
     * Represents a single cross-filling operation.
     */
    static class Operation {
        final int row, col, size;

        Operation(int row, int col, int size) {
            this.row = row;
            this.col = col;
            this.size = size;
        }
    }

    public static void main(String[] args) {
        new E984().run();
    }

    /**
     * Entry point that initializes I/O and delegates to the solver.
     */
    public void run() {
        FastScanner scanner = new FastScanner();
        PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out));

        try {
            solve(scanner, out);
        } catch (Exception e) {
            e.printStackTrace();
            out.println(-1);
        } finally {
            out.flush();
        }
    }

    /**
     * Core algorithm: reads input, computes directional counts, applies crosses,
     * verifies coverage, and prints results.
     */
    private void solve(FastScanner scanner, PrintWriter out) {
        String nStr = scanner.next();
        if (nStr == null) return;

        int n = Integer.parseInt(nStr);
        int m = scanner.nextInt();

        char[][] grid = new char[n][m];
        for (int i = 0; i < n; i++) {
            String row = scanner.next();
            grid[i] = row.toCharArray();
        }

        // Compute consecutive '*' counts in all four cardinal directions
        int[][] leftToRight = computeDirectionalCounts(grid, 0, 1);
        int[][] rightToLeft = computeDirectionalCounts(grid, 0, -1);
        int[][] upToDown = computeDirectionalCounts(grid, 1, 0);
        int[][] downToUp = computeDirectionalCounts(grid, -1, 0);

        // Tracks which cells have been covered by cross operations
        char[][] covered = new char[n][m];
        for (char[] row : covered) {
            Arrays.fill(row, '.');
        }

        List<Operation> operations = new ArrayList<>();

        // Process each '*' in the grid
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == '*') {
                    applyCross(i, j, leftToRight, rightToLeft, upToDown, downToUp, covered, operations);
                }
            }
        }

        // Verify if all '*' in the original grid are covered
        if (!isFullyCovered(grid, covered)) {
            out.println(-1);
        } else {
            out.println(operations.size());
            for (Operation op : operations) {
                // Output uses 1-based indexing as per original logic
                out.println((op.row + 1) + " " + (op.col + 1) + " " + op.size);
            }
        }
    }

    /**
     * Computes the number of consecutive '*' cells in a given direction.
     * Iterates in the specified direction and accumulates counts.
     */
    private int[][] computeDirectionalCounts(char[][] grid, int dr, int dc) {
        int n = grid.length;
        int m = grid[0].length;
        int[][] counts = new int[n][m];

        int rStart = dr > 0 ? 0 : n - 1;
        int rEnd = dr > 0 ? n : -1;
        int rStep = dr > 0 ? 1 : -1;

        int cStart = dc > 0 ? 0 : m - 1;
        int cEnd = dc > 0 ? m : -1;
        int cStep = dc > 0 ? 1 : -1;

        for (int r = rStart; r != rEnd; r += rStep) {
            for (int c = cStart; c != cEnd; c += cStep) {
                if (grid[r][c] == '*') {
                    int prevR = r - dr;
                    int prevC = c - dc;
                    int prevCount = (prevR >= 0 && prevR < n && prevC >= 0 && prevC < m)
                            ? counts[prevR][prevC] : 0;
                    counts[r][c] = prevCount + 1;
                }
            }
        }
        return counts;
    }

    /**
     * Determines the maximum cross size centered at (r, c) and applies it.
     */
    private void applyCross(int r, int c, int[][] lr, int[][] rl, int[][] ud, int[][] du,
                            char[][] covered, List<Operation> operations) {
        // Find the limiting factor in all four directions
        int k = Math.min(lr[r][c], Math.min(rl[r][c], Math.min(ud[r][c], du[r][c])));
        k--; // Decrement to get arm length (excluding center)

        if (k > 0) {
            operations.add(new Operation(r, c, k));
            mark(covered, r, c); // Mark center

            // Mark arms extending from the center
            for (int i = 1; i <= k; i++) {
                mark(covered, r + i, c);
                mark(covered, r - i, c);
                mark(covered, r, c + i);
                mark(covered, r, c - i);
            }
        }
    }

    /**
     * Safely marks a cell in the covered grid if it's within bounds.
     */
    private void mark(char[][] covered, int r, int c) {
        if (r >= 0 && r < covered.length && c >= 0 && c < covered[0].length) {
            covered[r][c] = '*';
        }
    }

    /**
     * Checks if every '*' in the original grid has been marked in the covered grid.
     */
    private boolean isFullyCovered(char[][] grid, char[][] covered) {
        for (int i = 0; i < grid.length; i++) {
            for (int j = 0; j < grid[0].length; j++) {
                if (grid[i][j] == '*' && covered[i][j] != '*') {
                    return false;
                }
            }
        }
        return true;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

/**
 * Main entry point for the Star Grid Drawing problem solver.
 * Refactored for improved maintainability, readability, and separation of concerns.
 */
public class Main {
    public static void main(String[] args) {
        FastScanner scanner = new FastScanner();
        PrintWriter out = new PrintWriter(System.out);
        StarGridProcessor processor = new StarGridProcessor();
        processor.process(scanner, out);
        out.flush();
        out.close();
    }
}

/**
 * Handles the core logic for processing the star grid.
 * Breaks down the original monolithic solve() method into focused, reusable methods.
 */
class StarGridProcessor {

    /**
     * Orchestrates the reading, processing, validation, and output phases.
     */
    public void process(FastScanner scanner, PrintWriter out) {
        int n = scanner.nextInt();
        int m = scanner.nextInt();
        char[][] grid = readGrid(scanner, n, m);

        // Compute contiguous star counts in all four directions
        int[][] left = computeHorizontalCounts(grid, n, m, false);
        int[][] right = computeHorizontalCounts(grid, n, m, true);
        int[][] up = computeVerticalCounts(grid, n, m, false);
        int[][] down = computeVerticalCounts(grid, n, m, true);

        StringBuilder outputLines = new StringBuilder();
        int processedStarCount = 0;
        boolean[][] covered = new boolean[n][m];

        // Identify valid stars and mark their contiguous lengths
        processedStarCount = processAndMarkStars(grid, n, m, left, right, up, down, outputLines, covered);

        // Mark all stars covered by horizontal or vertical segments
        markCoveredStars(grid, n, m, left, right, up, down, covered);

        // Validate that every star in the grid is covered
        if (!allStarsCovered(grid, n, m, covered)) {
            out.println("-1");
            return;
        }

        out.println(processedStarCount);
        out.println(outputLines);
    }

    private char[][] readGrid(FastScanner scanner, int n, int m) {
        char[][] grid = new char[n][];
        for (int i = 0; i < n; i++) {
            grid[i] = scanner.next().toCharArray();
        }
        return grid;
    }

    /**
     * Computes contiguous star counts horizontally.
     * @param reverse If true, computes from right to left (for 'right' array).
     */
    private int[][] computeHorizontalCounts(char[][] grid, int n, int m, boolean reverse) {
        int[][] counts = new int[n][m];
        for (int i = 0; i < n; i++) {
            if (reverse) {
                for (int j = m - 2; j >= 0; j--) {
                    if (grid[i][j + 1] == '*' && grid[i][j] == '*') {
                        counts[i][j] = counts[i][j + 1] + 1;
                    }
                }
            } else {
                for (int j = 1; j < m; j++) {
                    if (grid[i][j - 1] == '*' && grid[i][j] == '*') {
                        counts[i][j] = counts[i][j - 1] + 1;
                    }
                }
            }
        }
        return counts;
    }

    /**
     * Computes contiguous star counts vertically.
     * @param reverse If true, computes from bottom to top (for 'down' array).
     */
    private int[][] computeVerticalCounts(char[][] grid, int n, int m, boolean reverse) {
        int[][] counts = new int[n][m];
        for (int j = 0; j < m; j++) {
            if (reverse) {
                for (int i = n - 2; i >= 0; i--) {
                    if (grid[i + 1][j] == '*' && grid[i][j] == '*') {
                        counts[i][j] = counts[i + 1][j] + 1;
                    }
                }
            } else {
                for (int i = 1; i < n; i++) {
                    if (grid[i - 1][j] == '*' && grid[i][j] == '*') {
                        counts[i][j] = counts[i - 1][j] + 1;
                    }
                }
            }
        }
        return counts;
    }

    /**
     * Processes each cell to find valid stars, appends output, and updates count arrays.
     * Sets count arrays to minContiguous + 1 if valid, else 0.
     */
    private int processAndMarkStars(char[][] grid, int n, int m, int[][] left, int[][] right,
                                    int[][] up, int[][] down, StringBuilder output, boolean[][] covered) {
        int count = 0;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                int minContiguous = Math.min(Math.min(left[i][j], right[i][j]),
                                             Math.min(up[i][j], down[i][j]));
                if (minContiguous > 0) {
                    output.append(i + 1).append(' ').append(j + 1).append(' ').append(minContiguous).append('\n');
                    count++;
                    // Mark as processed by setting all directional counts to minContiguous + 1
                    left[i][j] = right[i][j] = up[i][j] = down[i][j] = minContiguous + 1;
                } else {
                    left[i][j] = right[i][j] = up[i][j] = down[i][j] = 0;
                }
            }
        }
        return count;
    }

    /**
     * Marks grid cells as covered if they belong to a contiguous horizontal or vertical segment.
     */
    private void markCoveredStars(char[][] grid, int n, int m, int[][] left, int[][] right,
                                  int[][] up, int[][] down, boolean[][] covered) {
        // Horizontal coverage
        for (int i = 0; i < n; i++) {
            int maxRight = 0;
            for (int j = 0; j < m; j++) {
                maxRight = Math.max(maxRight, right[i][j]);
                if (maxRight > 0) {
                    covered[i][j] = true;
                    maxRight--;
                }
            }
            int maxLeft = 0;
            for (int j = m - 1; j >= 0; j--) {
                maxLeft = Math.max(maxLeft, left[i][j]);
                if (maxLeft > 0) {
                    covered[i][j] = true;
                    maxLeft--;
                }
            }
        }

        // Vertical coverage
        for (int j = 0; j < m; j++) {
            int maxUp = 0;
            for (int i = 0; i < n; i++) {
                maxUp = Math.max(maxUp, up[i][j]);
                if (maxUp > 0) {
                    covered[i][j] = true;
                    maxUp--;
                }
            }
            int maxDown = 0;
            for (int i = n - 1; i >= 0; i--) {
                maxDown = Math.max(maxDown, down[i][j]);
                if (maxDown > 0) {
                    covered[i][j] = true;
                    maxDown--;
                }
            }
        }
    }

    /**
     * Checks if every '*' in the grid has been marked as covered.
     */
    private boolean allStarsCovered(char[][] grid, int n, int m, boolean[][] covered) {
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == '*' && !covered[i][j]) {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Fast I/O helper class using BufferedReader and StringTokenizer.
     * Replaces the original byte-based InputReader for better readability and maintainability.
     */
    static class FastScanner {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastScanner() {
            reader = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.util.Scanner;
import java.util.ArrayList;
import java.util.List;
import java.util.Arrays;

public class Solution {

    /**
     * Represents a plus shape found in the grid.
     * Stores the center coordinates and the radius (arm length).
     */
    private static class Plus {
        final int row;
        final int col;
        final int size; // Radius of the plus

        public Plus(int row, int col, int size) {
            this.row = row;
            this.col = col;
            this.size = size;
        }
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        // Read dimensions
        if (!scanner.hasNextInt()) {
            scanner.close();
            return;
        }
        int rows = scanner.nextInt();
        int cols = scanner.nextInt();

        // Read grid
        char[][] originalGrid = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            if (scanner.hasNext()) {
                String line = scanner.next();
                originalGrid[i] = line.toCharArray();
            }
        }
        scanner.close();

        // 1. Find all valid pluses
        List<Plus> pluses = findPluses(originalGrid);

        // 2. Reconstruct the grid using the found pluses
        char[][] reconstructedGrid = new char[rows][cols];
        // Initialize grid with '.'
        for (char[] row : reconstructedGrid) {
            Arrays.fill(row, '.');
        }

        for (Plus p : pluses) {
            drawPlus(reconstructedGrid, p);
        }

        // 3. Verify if the reconstruction matches the original grid
        if (isGridsEqual(originalGrid, reconstructedGrid)) {
            System.out.println(pluses.size());
            for (Plus p : pluses) {
                // Output 1-based coordinates and size
                System.out.println((p.row + 1) + " " + (p.col + 1) + " " + p.size);
            }
        } else {
            System.out.println(-1);
        }
    }

    /**
     * Scans the grid to find all valid plus shapes.
     * A plus is defined by a center '*' and equal length arms of '*' in all 4 directions.
     */
    private static List<Plus> findPluses(char[][] grid) {
        List<Plus> pluses = new ArrayList<>();
        int rows = grid.length;
        int cols = grid[0].length;

        // Iterate through the grid, excluding the borders as a plus center
        // must have neighbors in all 4 directions.
        for (int r = 1; r < rows - 1; r++) {
            for (int c = 1; c < cols - 1; c++) {
                if (grid[r][c] == '*') {
                    int radius = 0;

                    // Try to expand the radius of the plus
                    while (true) {
                        int nextRadius = radius + 1;

                        // Check boundaries for the next layer
                        if (r - nextRadius < 0 || r + nextRadius >= rows ||
                            c - nextRadius < 0 || c + nextRadius >= cols) {
                            break;
                        }

                        // Check if the required characters exist at the next radius
                        if (grid[r - nextRadius][c] == '*' &&
                            grid[r + nextRadius][c] == '*' &&
                            grid[r][c - nextRadius] == '*' &&
                            grid[r][c + nextRadius] == '*') {
                            radius = nextRadius;
                        } else {
                            break;
                        }
                    }

                    // If a valid plus with radius > 0 was found
                    if (radius > 0) {
                        pluses.add(new Plus(r, c, radius));
                    }
                }
            }
        }
        return pluses;
    }

    /**
     * Draws a plus shape onto the target grid.
     */
    private static void drawPlus(char[][] grid, Plus p) {
        int r = p.row;
        int c = p.col;
        int size = p.size;

        // Draw the vertical and horizontal arms
        // The loop runs from 0 to size inclusive to cover the center and all arms
        for (int i = 0; i <= size; i++) {
            grid[r - i][c] = '*'; // Up
            grid[r + i][c] = '*'; // Down
            grid[r][c - i] = '*'; // Left
            grid[r][c + i] = '*'; // Right
        }
    }

    /**
     * Compares two grids to see if they are identical.
     */
    private static boolean isGridsEqual(char[][] g1, char[][] g2) {
        for (int i = 0; i < g1.length; i++) {
            for (int j = 0; j < g1[0].length; j++) {
                if (g1[i][j] != g2[i][j]) {
                    return false;
                }
            }
        }
        return true;
    }
}

import java.io.*;
import java.util.*;

public class StarsDrawing {

    /**
     * Represents a maximal star shape found in the grid.
     * Coordinates are stored in 0-based indexing internally.
     */
    private static class Star {
        final int x, y, radius;

        Star(int x, int y, int radius) {
            this.x = x;
            this.y = y;
            this.radius = radius;
        }
    }

    public static void main(String[] args) throws IOException {
        FastScanner sc = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out));

        int n = sc.nextInt();
        int m = sc.nextInt();

        char[][] grid = new char[n][m];
        for (int i = 0; i < n; i++) {
            grid[i] = sc.next().toCharArray();
        }

        // Arrays to store continuous '*' counts in each direction
        int[][] up = new int[n][m];
        int[][] left = new int[n][m];
        int[][] down = new int[n][m];
        int[][] right = new int[n][m];

        // Forward pass: compute up and left continuous counts
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == '*') {
                    up[i][j] = (i > 0 ? up[i - 1][j] : 0) + 1;
                    left[i][j] = (j > 0 ? left[i][j - 1] : 0) + 1;
                }
            }
        }

        // Backward pass: compute down and right continuous counts
        for (int i = n - 1; i >= 0; i--) {
            for (int j = m - 1; j >= 0; j--) {
                if (grid[i][j] == '*') {
                    down[i][j] = (i < n - 1 ? down[i + 1][j] : 0) + 1;
                    right[i][j] = (j < m - 1 ? right[i][j + 1] : 0) + 1;
                }
            }
        }

        // Difference arrays for tracking vertical and horizontal coverage
        int[][] vertDiff = new int[n + 1][m + 1];
        int[][] horizDiff = new int[n + 1][m + 1];
        List<Star> stars = new ArrayList<>();

        // Identify maximal stars and mark their coverage using difference arrays
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == '*') {
                    int maxRadius = Math.min(Math.min(up[i][j], down[i][j]),
                                             Math.min(left[i][j], right[i][j])) - 1;

                    if (maxRadius > 0) {
                        stars.add(new Star(i, j, maxRadius));

                        // Mark vertical coverage range [i-maxRadius, i+maxRadius]
                        vertDiff[i - maxRadius][j]++;
                        vertDiff[i + maxRadius + 1][j]--;

                        // Mark horizontal coverage range [j-maxRadius, j+maxRadius]
                        horizDiff[i][j - maxRadius]++;
                        horizDiff[i][j + maxRadius + 1]--;
                    }
                }
            }
        }

        // Compute prefix sums to resolve actual coverage counts
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (i > 0) vertDiff[i][j] += vertDiff[i - 1][j];
                if (j > 0) horizDiff[i][j] += horizDiff[i][j - 1];
            }
        }

        // Verify that every '*' cell is covered by at least one star
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == '*' && (vertDiff[i][j] + horizDiff[i][j] == 0)) {
                    out.println("-1");
                    out.flush();
                    return;
                }
            }
        }

        // Output results (convert to 1-based indexing as expected by the problem)
        out.println(stars.size());
        for (Star star : stars) {
            out.println((star.x + 1) + " " + (star.y + 1) + " " + star.radius);
        }

        out.flush();
    }

    /**
     * Efficient scanner using BufferedReader and StringTokenizer.
     * Replaces verbose custom byte-by-byte I/O with standard, maintainable Java I/O.
     */
    private static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        public String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) throw new IOException("End of input");
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.OutputStream;
import java.io.PrintWriter;
import java.util.ArrayList;
import java.util.List;
import java.util.StringTokenizer;

public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        FastScanner in = new FastScanner(inputStream);
        PrintWriter out = new PrintWriter(outputStream);

        new GridStarSolver().solve(in, out);

        out.close();
    }

    /**
     * Solves the grid star coverage problem.
     * Reads an n x m grid, identifies valid "stars" (cells with radius > 0),
     * marks all cells covered by these stars, and verifies full coverage.
     */
    static class GridStarSolver {
        private int rows;
        private int cols;
        private int[][] grid;
        private boolean[][] isCovered;

        public void solve(FastScanner in, PrintWriter out) {
            rows = in.nextInt();
            cols = in.nextInt();

            grid = new int[rows][cols];
            for (int i = 0; i < rows; i++) {
                // Use next() instead of nextLine() to avoid newline consumption bugs
                String rowStr = in.next();
                for (int j = 0; j < cols; j++) {
                    grid[i][j] = (rowStr.charAt(j) == '.') ? 0 : 1;
                }
            }

            // Precompute consecutive ones in all four directions
            int[][] consecutiveUp = computeDirectionalConsecutiveOnes(rows, cols, 1, 0, -1, 0);
            int[][] consecutiveDown = computeDirectionalConsecutiveOnes(rows, cols, rows - 2, 0, 1, 0);
            int[][] consecutiveLeft = computeDirectionalConsecutiveOnes(rows, cols, 0, 1, 0, -1);
            int[][] consecutiveRight = computeDirectionalConsecutiveOnes(rows, cols, 0, cols - 2, 0, 1);

            isCovered = new boolean[rows][cols];
            List<StarInfo> stars = new ArrayList<>();

            // Identify stars and mark coverage
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] == 1) {
                        int radius = Math.min(
                            Math.min(consecutiveUp[r][c], consecutiveDown[r][c]),
                            Math.min(consecutiveLeft[r][c], consecutiveRight[r][c])
                        );

                        if (radius > 0) {
                            markCrossCoverage(r, c, radius);
                            stars.add(new StarInfo(r + 1, c + 1, radius));
                        }
                    }
                }
            }

            // Verify all '1' cells are covered
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] == 1 && !isCovered[r][c]) {
                        out.println(-1);
                        return;
                    }
                }
            }

            // Output results
            out.println(stars.size());
            for (StarInfo star : stars) {
                out.println(star.x + " " + star.y + " " + star.radius);
            }
        }

        /**
         * Computes the number of consecutive 1s in a specific direction for each cell.
         * @param startRow Starting row index for the traversal
         * @param stepRow Step value for row iteration (1 or -1)
         * @param startCol Starting column index for the traversal
         * @param stepCol Step value for column iteration (1 or -1)
         */
        private int[][] computeDirectionalConsecutiveOnes(int rows, int cols, int startRow, int stepRow, int startCol, int stepCol) {
            int[][] dist = new int[rows][cols];
            for (int r = startRow; r >= 0 && r < rows; r += stepRow) {
                for (int c = startCol; c >= 0 && c < cols; c += stepCol) {
                    int nextR = r + stepRow;
                    int nextC = c + stepCol;
                    if (nextR >= 0 && nextR < rows && nextC >= 0 && nextC < cols) {
                        if (grid[nextR][nextC] == 1) {
                            dist[r][c] = dist[nextR][nextC] + 1;
                        }
                    }
                }
            }
            return dist;
        }

        /**
         * Marks a cross-shaped region centered at (r, c) with the given radius.
         * Bounds are clamped to grid dimensions.
         */
        private void markCrossCoverage(int r, int c, int radius) {
            int minR = Math.max(0, r - radius);
            int maxR = Math.min(rows - 1, r + radius);
            for (int i = minR; i <= maxR; i++) {
                isCovered[i][c] = true;
            }

            int minC = Math.max(0, c - radius);
            int maxC = Math.min(cols - 1, c + radius);
            for (int i = minC; i <= maxC; i++) {
                isCovered[r][i] = true;
            }
        }

        /** Immutable data holder for star coordinates and radius. */
        static class StarInfo {
            final int x;
            final int y;
            final int radius;

            StarInfo(int x, int y, int radius) {
                this.x = x;
                this.y = y;
                this.radius = radius;
            }
        }
    }

    /** High-performance input scanner for competitive programming. */
    static class FastScanner {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastScanner(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input", e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.PrintWriter;
import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

/**
 * Analyzes a 2D character grid to find and mark cross patterns formed by '*' characters.
 * Outputs the total number of crosses found, or -1 if any '*' remains unmarked.
 */
public class CrossPatternAnalyzer {

    private final int rows;
    private final int cols;
    private final char[][] grid;
    private final boolean[][] marked;
    private final List<String> crossDetails;

    /**
     * Constructs the analyzer with specified grid dimensions.
     *
     * @param rows Number of rows in the grid
     * @param cols Number of columns in the grid
     */
    public CrossPatternAnalyzer(int rows, int cols) {
        this.rows = rows;
        this.cols = cols;
        this.grid = new char[rows][cols];
        this.marked = new boolean[rows][cols];
        this.crossDetails = new ArrayList<>();
    }

    /**
     * Executes the cross pattern analysis pipeline.
     *
     * @param scanner Input scanner
     * @param out     Output writer
     */
    public void analyze(Scanner scanner, PrintWriter out) {
        readGrid(scanner);
        findAndMarkCrosses();
        outputResults(out);
    }

    private void readGrid(Scanner scanner) {
        for (int i = 0; i < rows; i++) {
            String line = scanner.nextLine();
            for (int j = 0; j < cols && j < line.length(); j++) {
                grid[i][j] = line.charAt(j);
            }
        }
    }

    private void findAndMarkCrosses() {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == '*' && hasCrossCenter(i, j)) {
                    markCrossAndRecord(i, j);
                }
            }
        }
    }

    /**
     * Checks if a cell can serve as the center of a cross.
     */
    private boolean hasCrossCenter(int row, int col) {
        return row > 0 && row < rows - 1 &&
               col > 0 && col < cols - 1 &&
               grid[row][col] == '*' &&
               grid[row][col - 1] == '*' &&
               grid[row][col + 1] == '*' &&
               grid[row + 1][col] == '*' &&
               grid[row - 1][col] == '*';
    }

    /**
     * Calculates the maximum cross extent from the center and records it.
     */
    private void markCrossAndRecord(int row, int col) {
        int extent = calculateMaxCrossExtent(row, col);
        markCellsInAllDirections(row, col, extent);
        crossDetails.add(formatCrossRecord(row, col, extent));
    }

    private int calculateMaxCrossExtent(int row, int col) {
        int right = countStarsInDirection(row, col, 0, 1);
        int left = countStarsInDirection(row, col, 0, -1);
        int down = countStarsInDirection(row, col, 1, 0);
        int up = countStarsInDirection(row, col, -1, 0);
        return Math.min(Math.min(right, left), Math.min(up, down));
    }

    private int countStarsInDirection(int row, int col, int dr, int dc) {
        int count = 0;
        for (int r = row, c = col; r >= 0 && r < rows && c >= 0 && c < cols && grid[r][c] == '*'; r += dr, c += dc) {
            count++;
        }
        return count;
    }

    private void markCellsInAllDirections(int row, int col, int extent) {
        markInDirection(row, col, 0, 1, extent);
        markInDirection(row, col, 0, -1, extent);
        markInDirection(row, col, 1, 0, extent);
        markInDirection(row, col, -1, 0, extent);
    }

    private void markInDirection(int row, int col, int dr, int dc, int limit) {
        for (int count = 0, r = row, c = col; count < limit && r >= 0 && r < rows && c >= 0 && c < cols && grid[r][c] == '*'; r += dr, c += dc, count++) {
            marked[r][c] = true;
        }
    }

    private String formatCrossRecord(int row, int col, int extent) {
        return (row + 1) + " " + (col + 1) + " " + (extent - 1);
    }

    private void outputResults(PrintWriter out) {
        if (!allStarsMarked()) {
            out.println(-1);
            return;
        }

        out.println(crossDetails.size());
        for (String detail : crossDetails) {
            out.println(detail);
        }
    }

    private boolean allStarsMarked() {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == '*' && !marked[i][j]) {
                    return false;
                }
            }
        }
        return true;
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        PrintWriter out = new PrintWriter(System.out);
        try {
            if (!scanner.hasNextInt()) {
                return;
            }
            int n = scanner.nextInt();
            int m = scanner.nextInt();
            scanner.nextLine(); // Consume the newline after the dimensions
            CrossPatternAnalyzer analyzer = new CrossPatternAnalyzer(n, m);
            analyzer.analyze(scanner, out);
        } finally {
            out.flush();
            scanner.close();
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Solves a grid-based problem by finding maximal squares of '*' characters
 * and validating coverage using a 2D difference array (sweep-line) technique.
 */
public class GridSquareSolver {

    /** Represents a square found in the grid */
    public static class Square {
        final int row;
        final int col;
        final int radius;

        public Square(int row, int col, int radius) {
            this.row = row;
            this.col = col;
            this.radius = radius;
        }
    }

    /** Fast I/O Scanner optimized for competitive programming */
    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) throw new IOException("Unexpected end of input");
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        String nextLine() {
            try {
                return br.readLine();
            } catch (IOException e) {
                throw new RuntimeException(e);
            }
        }
    }

    public static void main(String[] args) {
        FastScanner sc = new FastScanner();
        PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out));

        try {
            int n = sc.nextInt();
            int m = sc.nextInt();
            sc.nextLine(); // Consume the newline after reading m

            char[][] grid = new char[n][m];
            for (int i = 0; i < n; i++) {
                grid[i] = sc.nextLine().toCharArray();
            }

            // 1. Compute directional continuity arrays
            int[][] up = new int[n][m];
            int[][] down = new int[n][m];
            int[][] left = new int[n][m];
            int[][] right = new int[n][m];
            computeDirectionalArrays(grid, up, down, left, right);

            // 2. Identify all valid squares centered at each '*'
            List<Square> squares = findSquares(grid, up, down, left, right);

            // 3. Apply sweep-line difference arrays for horizontal/vertical coverage
            int[][] hCoverage = new int[n][m];
            int[][] vCoverage = new int[n][m];
            applySweepLine(squares, hCoverage, vCoverage);
            computePrefixSums(hCoverage, vCoverage, n, m);

            // 4. Validate coverage and produce output
            if (!validateCoverage(grid, hCoverage, vCoverage, n, m)) {
                out.println(-1);
            } else {
                out.println(squares.size());
                for (Square sq : squares) {
                    out.println((sq.row + 1) + " " + (sq.col + 1) + " " + sq.radius);
                }
            }
        } catch (Exception e) {
            e.printStackTrace();
        } finally {
            out.flush();
            out.close();
        }
    }

    /**
     * Fills directional arrays with the length of consecutive '*' characters
     * extending from each cell in each direction. Returns -1 for non-'*' cells.
     */
    private static void computeDirectionalArrays(char[][] grid, int[][] up, int[][] down, 
                                                 int[][] left, int[][] right) {
        int n = grid.length;
        int m = grid[0].length;

        // Forward pass (top-left to bottom-right)
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] != '*') {
                    up[i][j] = down[i][j] = left[i][j] = right[i][j] = -1;
                    continue;
                }
                up[i][j] = (i == 0) ? 0 : 1 + up[i - 1][j];
                left[i][j] = (j == 0) ? 0 : 1 + left[i][j - 1];
            }
        }

        // Backward pass (bottom-right to top-left)
        for (int i = n - 1; i >= 0; i--) {
            for (int j = m - 1; j >= 0; j--) {
                if (grid[i][j] != '*') continue;
                down[i][j] = (i == n - 1) ? 0 : 1 + down[i + 1][j];
                right[i][j] = (j == m - 1) ? 0 : 1 + right[i][j + 1];
            }
        }
    }

    /**
     * Finds all maximal squares of '*' characters.
     * The radius is the maximum distance from the center to any edge of the square.
     */
    private static List<Square> findSquares(char[][] grid, int[][] up, int[][] down, 
                                            int[][] left, int[][] right) {
        List<Square> squares = new ArrayList<>();
        int n = grid.length;
        int m = grid[0].length;

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == '*') {
                    int radius = Math.min(Math.min(up[i][j], down[i][j]), 
                                          Math.min(left[i][j], right[i][j]));
                    if (radius > 0) {
                        squares.add(new Square(i, j, radius));
                    }
                }
            }
        }
        return squares;
    }

    /**
     * Applies a 2D difference array technique to mark horizontal and vertical 
     * line coverage for each identified square.
     */
    private static void applySweepLine(List<Square> squares, int[][] hCoverage, int[][] vCoverage) {
        for (Square sq : squares) {
            int r = sq.row;
            int c = sq.col;
            int rad = sq.radius;

            // Horizontal coverage mark
            hCoverage[r][c - rad]++;
            if (c + rad + 1 < hCoverage[0].length) {
                hCoverage[r][c + rad + 1]--;
            }

            // Vertical coverage mark
            vCoverage[r - rad][c]++;
            if (r + rad + 1 < vCoverage.length) {
                vCoverage[r + rad + 1][c]--;
            }
        }
    }

    /**
     * Computes prefix sums over the difference arrays to determine actual coverage counts.
     */
    private static void computePrefixSums(int[][] hCoverage, int[][] vCoverage, int n, int m) {
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (j > 0) hCoverage[i][j] += hCoverage[i][j - 1];
                if (i > 0) vCoverage[i][j] += vCoverage[i - 1][j];
            }
        }
    }

    /**
     * Validates that every '*' cell is covered by at least one horizontal and one vertical line.
     */
    private static boolean validateCoverage(char[][] grid, int[][] hCoverage, int[][] vCoverage, 
                                            int n, int m) {
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == '*' && hCoverage[i][j] <= 0 && vCoverage[i][j] <= 0) {
                    return false;
                }
            }
        }
        return true;
    }
}

import java.io.BufferedReader;
import java.io.EOFException;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.OutputStreamWriter;
import java.io.PrintWriter;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.StringTokenizer;

/**
 * Solves a grid pattern problem by finding and validating cross shapes.
 * Refactored for maintainability, testability, and clear separation of concerns.
 */
public class CrossPatternSolver {

    public static void main(String[] args) {
        // try-with-resources ensures streams are closed even if an exception occurs
        try (BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
             PrintWriter out = new PrintWriter(new OutputStreamWriter(System.out))) {

            FastScanner scanner = new FastScanner(in);
            CrossPatternSolver solver = new CrossPatternSolver();
            solver.solve(scanner, out);
            out.flush();
        } catch (IOException e) {
            System.err.println("I/O error: " + e.getMessage());
            System.exit(1);
        }
    }

    /**
     * Orchestrates the grid processing, cross detection, validation, and output.
     */
    void solve(FastScanner in, PrintWriter out) throws IOException {
        int n = in.nextInt();
        int m = in.nextInt();
        char[][] grid = new char[n][m];
        for (int i = 0; i < n; i++) {
            grid[i] = in.next().toCharArray();
        }

        int[][] upCount = new int[n][m];
        int[][] downCount = new int[n][m];
        int[][] leftCount = new int[n][m];
        int[][] rightCount = new int[n][m];

        // Compute contiguous non-dot distances in all four directions
        computeVerticalDistances(grid, upCount, downCount);
        computeHorizontalDistances(grid, leftCount, rightCount);

        // Initialize result grid with empty cells
        char[][] resultGrid = new char[n][m];
        for (int i = 0; i < n; i++) {
            Arrays.fill(resultGrid[i], '.');
        }

        List<Cross> crosses = new ArrayList<>();

        // Identify valid cross centers and mark them
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                int minDist = Math.min(Math.min(upCount[i][j], downCount[i][j]),
                                       Math.min(leftCount[i][j], rightCount[i][j]));

                // A cross requires at least 2 cells in every direction (size > 1)
                if (minDist > 1) {
                    markCross(resultGrid, i, j, minDist);
                    crosses.add(new Cross(i + 1, j + 1, minDist - 1));
                }
            }
        }

        // Validate if the generated pattern exactly matches the original grid
        if (!isValid(grid, resultGrid)) {
            out.println(-1);
        } else {
            out.println(crosses.size());
            for (Cross cross : crosses) {
                out.println(cross.row + " " + cross.col + " " + cross.size);
            }
        }
    }

    /**
     * Computes upward and downward contiguous non-dot counts for each column.
     */
    private void computeVerticalDistances(char[][] grid, int[][] upCount, int[][] downCount) {
        int n = grid.length;
        int m = grid[0].length;

        for (int j = 0; j < m; j++) {
            int count = 0;
            for (int i = 0; i < n; i++) {
                count = grid[i][j] == '.' ? 0 : count + 1;
                upCount[i][j] = count;
            }

            count = 0;
            for (int i = n - 1; i >= 0; i--) {
                count = grid[i][j] == '.' ? 0 : count + 1;
                downCount[i][j] = count;
            }
        }
    }

    /**
     * Computes leftward and rightward contiguous non-dot counts for each row.
     */
    private void computeHorizontalDistances(char[][] grid, int[][] leftCount, int[][] rightCount) {
        int n = grid.length;
        int m = grid[0].length;

        for (int i = 0; i < n; i++) {
            int count = 0;
            for (int j = 0; j < m; j++) {
                count = grid[i][j] == '.' ? 0 : count + 1;
                leftCount[i][j] = count;
            }

            count = 0;
            for (int j = m - 1; j >= 0; j--) {
                count = grid[i][j] == '.' ? 0 : count + 1;
                rightCount[i][j] = count;
            }
        }
    }

    /**
     * Marks a cross shape centered at (centerRow, centerCol) with the given size.
     * Bounds are guaranteed safe by the distance arrays.
     */
    private void markCross(char[][] grid, int centerRow, int centerCol, int size) {
        for (int k = 0; k < size; k++) {
            grid[centerRow + k][centerCol] = '*';
            grid[centerRow - k][centerCol] = '*';
            grid[centerRow][centerCol + k] = '*';
            grid[centerRow][centerCol - k] = '*';
        }
    }

    /**
     * Validates that the generated pattern exactly matches the original input grid.
     */
    private boolean isValid(char[][] original, char[][] generated) {
        for (int i = 0; i < original.length; i++) {
            for (int j = 0; j < original[0].length; j++) {
                if (original[i][j] != generated[i][j]) {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Immutable data class to store cross pattern metadata.
     */
    private static class Cross {
        final int row;
        final int col;
        final int size;

        Cross(int row, int col, int size) {
            this.row = row;
            this.col = col;
            this.size = size;
        }
    }

    /**
     * Lightweight fast I/O scanner for competitive programming style inputs.
     */
    private static class FastScanner {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        FastScanner(BufferedReader reader) {
            this.reader = reader;
        }

        String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                String line = reader.readLine();
                if (line == null) {
                    throw new EOFException("Unexpected end of input");
                }
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Analyzes a grid to identify valid star clusters and calculates their coverage.
 * Refactored for maintainability, readability, and adherence to Java best practices.
 */
public class StarPatternAnalyzer {

    private static final int MAX_SIZE = 150;
    private static final int INFINITE = 100000;

    // Direction vectors: Up, Down, Left, Right
    private static final int[][] DIRECTIONS = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};

    /**
     * Holds the result of a valid cluster analysis.
     */
    private static class Result {
        final int row;
        final int col;
        final int size;

        Result(int row, int col, int size) {
            this.row = row;
            this.col = col;
            this.size = size;
        }
    }

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out);
        try {
            int t = 1; // Original code assumes a single test case
            while (t-- > 0) {
                process(scanner, out);
            }
        } catch (IOException e) {
            System.err.println("Input/Output error: " + e.getMessage());
        } finally {
            out.flush();
            out.close();
        }
    }

    /**
     * Orchestrates the reading, processing, and output of the grid analysis.
     */
    private static void process(FastScanner scanner, PrintWriter out) throws IOException {
        int n = scanner.nextInt();
        int m = scanner.nextInt();

        char[][] grid = new char[n][m];
        int[][] coverage = new int[n][m]; // Tracks which '*' cells have been covered

        // Read grid and initialize coverage array
        for (int i = 0; i < n; i++) {
            String line = scanner.next();
            for (int j = 0; j < m; j++) {
                grid[i][j] = line.charAt(j);
                if (grid[i][j] == '*') {
                    coverage[i][j] = 1;
                }
            }
        }

        List<Result> results = new ArrayList<>();
        // Identify valid clusters and calculate coverage
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (isValid(i, j, grid, n, m)) {
                    int size = calculateCoverage(i, j, grid, n, m, coverage);
                    // Output uses 1-based indexing to match original behavior
                    results.add(new Result(i + 1, j + 1, size));
                }
            }
        }

        // Verify all '*' cells were covered
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (coverage[i][j] != 0) {
                    out.println(-1);
                    return;
                }
            }
        }

        // Output results
        out.println(results.size());
        for (Result r : results) {
            out.println(r.row + " " + r.col + " " + r.size);
        }
    }

    /**
     * Checks if a cell is a valid cluster center.
     * Conditions: Not on border, not '.', and all 4 adjacent cells are '*'
     */
    private static boolean isValid(int i, int j, char[][] grid, int n, int m) {
        if (i == 0 || i == n - 1 || j == 0 || j == m - 1) {
            return false;
        }
        if (grid[i][j] == '.') {
            return false;
        }
        return grid[i - 1][j] == '*' && grid[i + 1][j] == '*' &&
               grid[i][j + 1] == '*' && grid[i][j - 1] == '*';
    }

    /**
     * Calculates the minimum distance to a non-'*' cell in all 4 directions
     * and marks covered cells in the coverage array.
     */
    private static int calculateCoverage(int i, int j, char[][] grid, int n, int m, int[][] coverage) {
        int minDist = INFINITE;

        // Find minimum distance to boundary or non-'*' in each direction
        for (int[] dir : DIRECTIONS) {
            int count = 0;
            int r = i + dir[0];
            int c = j + dir[1];
            while (r >= 0 && r < n && c >= 0 && c < m && grid[r][c] == '*') {
                count++;
                r += dir[0];
                c += dir[1];
            }
            minDist = Math.min(minDist, count);
        }

        // Mark covered cells (including the center cell at offset 0)
        for (int[] dir : DIRECTIONS) {
            for (int k = 0; k <= minDist; k++) {
                coverage[i + dir[0] * k][j + dir[1] * k] = 0;
            }
        }

        return minDist;
    }

    /**
     * High-performance input scanner for competitive programming style tasks.
     */
    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        FastScanner(File file) throws FileNotFoundException {
            br = new BufferedReader(new FileReader(file));
        }

        String next() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) {
                    throw new EOFException("End of input reached");
                }
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        long nextLong() throws IOException {
            return Long.parseLong(next());
        }

        double nextDouble() throws IOException {
            return Double.parseDouble(next());
        }

        String nextLine() throws IOException {
            return br.readLine();
        }
    }
}

import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

/**
 * Refactored Grid Cross Analyzer.
 * 
 * Changes made to increase maintainability and code quality:
 * 1. Renamed class to 'GridCrossAnalyzer' for better context.
 * 2. Extracted logic into a dedicated 'solve' method.
 * 3. Created a 'Cross' inner class to store cross data (row, col, radius) 
 *    instead of parallel ArrayLists.
 * 4. Improved variable naming (e.g., 'grid' instead of 'a', 'isCovered' instead of 'check').
 * 5. Removed redundant imports and magic numbers.
 * 6. Enhanced readability with clear loop structures and comments.
 */
public class GridCrossAnalyzer {

    /**
     * Helper class to store information about a found cross pattern.
     */
    private static class Cross {
        int row;
        int col;
        int radius;

        public Cross(int row, int col, int radius) {
            this.row = row;
            this.col = col;
            this.radius = radius;
        }
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        // The original code used a loop with ttt=1, effectively running once.
        // We structure the input reading to handle the single test case as per original behavior.
        if (scanner.hasNextInt()) {
            int n = scanner.nextInt();
            int m = scanner.nextInt();

            String[] grid = new String[n];
            for (int i = 0; i < n; i++) {
                grid[i] = scanner.next();
            }

            solve(n, m, grid);
        }

        scanner.close();
    }

    private static void solve(int n, int m, String[] grid) {
        List<Cross> crosses = new ArrayList<>();
        boolean[][] isCovered = new boolean[n][m];

        // Iterate through the grid to find potential centers of crosses.
        // Centers cannot be on the border (indices 1 to n-2, 1 to m-2)
        // because a cross requires neighbors in all 4 directions.
        for (int i = 1; i < n - 1; i++) {
            for (int j = 1; j < m - 1; j++) {
                // Only potential centers are asterisks
                if (grid[i].charAt(j) == '*') {
                    int radius = 0;

                    // Try to expand the cross outwards to find the maximum radius
                    while (true) {
                        int k = radius + 1;

                        // Check boundaries for the points at distance k
                        if (i - k < 0 || i + k >= n || j - k < 0 || j + k >= m) {
                            break;
                        }

                        // Check if the 4 points at distance k are asterisks.
                        // If any is '.', the cross cannot extend to this radius.
                        if (grid[i].charAt(j - k) == '.' ||
                            grid[i].charAt(j + k) == '.' ||
                            grid[i - k].charAt(j) == '.' ||
                            grid[i + k].charAt(j) == '.') {
                            break;
                        }

                        // Valid ring found at distance k
                        radius = k;

                        // Mark the center and the 4 points of the current ring as covered
                        isCovered[i][j] = true;
                        isCovered[i][j - k] = true;
                        isCovered[i][j + k] = true;
                        isCovered[i - k][j] = true;
                        isCovered[i + k][j] = true;
                    }

                    // If a valid cross (radius > 0) was found, store it
                    if (radius > 0) {
                        crosses.add(new Cross(i, j, radius));
                    }
                }
            }
        }

        // Verify that every asterisk in the grid is covered by at least one cross
        boolean allAsterisksCovered = true;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i].charAt(j) == '*' && !isCovered[i][j]) {
                    allAsterisksCovered = false;
                    break;
                }
            }
            if (!allAsterisksCovered) break;
        }

        if (!allAsterisksCovered) {
            System.out.println(-1);
        } else {
            System.out.println(crosses.size());
            for (Cross cross : crosses) {
                // Output requires 1-based indexing
                System.out.println((cross.row + 1) + " " + (cross.col + 1) + " " + cross.radius);
            }
        }
    }
}

import java.io.InputStream;
import java.io.OutputStream;
import java.io.PrintWriter;
import java.util.ArrayList;
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        Scanner in = new Scanner(inputStream);
        PrintWriter out = new PrintWriter(outputStream);

        GridCrossSolver solver = new GridCrossSolver();
        solver.solve(in, out);

        out.close();
    }

    /**
     * Solves the grid cross coverage problem.
     * Identifies maximum-radius crosses centered at obstacles and verifies
     * if their union exactly covers all obstacles in the grid.
     */
    static class GridCrossSolver {
        public void solve(Scanner in, PrintWriter out) {
            if (!in.hasNextInt()) return;
            int n = in.nextInt();
            int m = in.nextInt();

            boolean[][] grid = new boolean[n][m];
            ArrayList<Point> obstaclePositions = new ArrayList<>();

            // Read grid and collect obstacle coordinates
            for (int i = 0; i < n; i++) {
                String gridRow = in.next();
                for (int j = 0; j < m; j++) {
                    boolean isObstacle = gridRow.charAt(j) != '.';
                    grid[i][j] = isObstacle;
                    if (isObstacle) {
                        obstaclePositions.add(new Point(i, j));
                    }
                }
            }

            ArrayList<Cross> validCrosses = new ArrayList<>();

            // Find maximum radius crosses centered at each obstacle
            for (Point center : obstaclePositions) {
                int radius = 0;
                while (true) {
                    int nextRadius = radius + 1;

                    // Check if the next layer is within grid bounds
                    if (center.row + nextRadius >= n || center.row - nextRadius < 0 ||
                        center.col + nextRadius >= m || center.col - nextRadius < 0) {
                        break;
                    }

                    // Check if all four directions at the next radius are obstacles
                    if (grid[center.row + nextRadius][center.col] &&
                        grid[center.row - nextRadius][center.col] &&
                        grid[center.row][center.col + nextRadius] &&
                        grid[center.row][center.col - nextRadius]) {
                        radius = nextRadius;
                    } else {
                        break;
                    }
                }

                if (radius > 0) {
                    validCrosses.add(new Cross(center.row, center.col, radius));
                }
            }

            // Build coverage grid from valid crosses
            boolean[][] coverageGrid = new boolean[n][m];
            for (Cross cross : validCrosses) {
                coverageGrid[cross.row][cross.col] = true;
                for (int k = 1; k <= cross.radius; k++) {
                    coverageGrid[cross.row + k][cross.col] = true;
                    coverageGrid[cross.row - k][cross.col] = true;
                    coverageGrid[cross.row][cross.col + k] = true;
                    coverageGrid[cross.row][cross.col - k] = true;
                }
            }

            // Verify if the coverage grid exactly matches the original grid
            boolean isFullyCovered = true;
            outerLoop:
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    if (grid[i][j] != coverageGrid[i][j]) {
                        isFullyCovered = false;
                        break outerLoop;
                    }
                }
            }

            // Output results
            if (isFullyCovered) {
                out.println(validCrosses.size());
                for (Cross cross : validCrosses) {
                    // Output 1-based indexing as per original specification
                    out.println((cross.row + 1) + " " + (cross.col + 1) + " " + cross.radius);
                }
            } else {
                out.println("-1");
            }
        }
    }

    /**
     * Represents a coordinate point in the grid.
     */
    static class Point {
        final int row;
        final int col;

        Point(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    /**
     * Represents a valid cross shape with a center and radius.
     */
    static class Cross {
        final int row;
        final int col;
        final int radius;

        Cross(int row, int col, int radius) {
            this.row = row;
            this.col = col;
            this.radius = radius;
        }
    }
}

import java.io.BufferedReader;
import java.io.BufferedOutputStream;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.ArrayList;
import java.util.List;
import java.util.StringTokenizer;

/**
 * Solves the problem of placing crosses on a grid to cover all asterisks.
 * Uses a greedy approach, placing the largest possible crosses first.
 */
public class CrossGridSolver {

    /**
     * Represents a placed cross on the grid.
     */
    private static class CrossPlacement {
        final int row;
        final int col;
        final int radius;

        public CrossPlacement(int row, int col, int radius) {
            this.row = row;
            this.col = col;
            this.radius = radius;
        }
    }

    /**
     * FastScanner utility for efficient input reading.
     */
    private static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) {
                        return null;
                    }
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            String s = next();
            if (s == null) {
                throw new RuntimeException("Unexpected end of input");
            }
            return Integer.parseInt(s);
        }

        long nextLong() {
            String s = next();
            if (s == null) {
                throw new RuntimeException("Unexpected end of input");
            }
            return Long.parseLong(s);
        }

        double nextDouble() {
            String s = next();
            if (s == null) {
                throw new RuntimeException("Unexpected end of input");
            }
            return Double.parseDouble(s);
        }
    }

    public static void main(String[] args) {
        // Use try-with-resources to ensure the output stream is closed properly
        try (PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out))) {
            FastScanner scanner = new FastScanner();
            solve(scanner, out);
        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    private static void solve(FastScanner scanner, PrintWriter out) {
        // 1. Read Input
        int rows = scanner.nextInt();
        int cols = scanner.nextInt();

        char[][] grid = new char[rows][cols];
        for (int r = 0; r < rows; r++) {
            String line = scanner.next();
            if (line != null) {
                grid[r] = line.toCharArray();
            }
        }

        // 2. Precompute distances for each cell
        // up[r][c] stores the number of consecutive '*' ending at (r,c) going upwards
        int[][] up = new int[rows][cols];
        int[][] down = new int[rows][cols];
        int[][] left = new int[rows][cols];
        int[][] right = new int[rows][cols];

        // Calculate Up and Left distances (Top-Left to Bottom-Right)
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '*') {
                    up[r][c] = 1;
                    left[r][c] = 1;
                    if (r > 0) up[r][c] += up[r - 1][c];
                    if (c > 0) left[r][c] += left[r][c - 1];
                }
            }
        }

        // Calculate Down and Right distances (Bottom-Right to Top-Left)
        for (int r = rows - 1; r >= 0; r--) {
            for (int c = cols - 1; c >= 0; c--) {
                if (grid[r][c] == '*') {
                    down[r][c] = 1;
                    right[r][c] = 1;
                    if (r + 1 < rows) down[r][c] += down[r + 1][c];
                    if (c + 1 < cols) right[r][c] += right[r][c + 1];
                }
            }
        }

        // 3. Place Crosses (Greedy approach: largest size first)
        List<CrossPlacement> placements = new ArrayList<>();
        boolean[][] covered = new boolean[rows][cols];

        // The maximum possible radius is limited by the grid dimensions
        int maxSize = Math.min((rows - 1) / 2, (cols - 1) / 2);

        for (int size = maxSize; size >= 1; size--) {
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] == '*') {
                        // Check if cell (r, c) can be the center of a cross of 'size'
                        // We need 'size' stars in all 4 directions + the center itself
                        if (up[r][c] >= size + 1 && down[r][c] >= size + 1 &&
                            left[r][c] >= size + 1 && right[r][c] >= size + 1) {

                            // Place the cross
                            // Note: Output requires 1-based indexing
                            placements.add(new CrossPlacement(r + 1, c + 1, size));

                            // Mark the center as covered
                            covered[r][c] = true;

                            // Mark the arms of the cross as covered
                            // Bounds checks are implicitly satisfied by the distance checks above
                            for (int offset = 1; offset <= size; offset++) {
                                covered[r + offset][c] = true;
                                covered[r - offset][c] = true;
                                covered[r][c + offset] = true;
                                covered[r][c - offset] = true;
                            }
                        }
                    }
                }
            }
        }

        // 4. Verification: Check if all '*' are covered
        boolean isPossible = true;
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '*' && !covered[r][c]) {
                    isPossible = false;
                    break;
                }
            }
            if (!isPossible) {
                break;
            }
        }

        // 5. Output Results
        if (isPossible) {
            out.println(placements.size());
            for (CrossPlacement p : placements) {
                out.println(p.row + " " + p.col + " " + p.radius);
            }
        } else {
            out.println(-1);
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayList;
import java.util.List;
import java.util.StringTokenizer;

/**
 * Solves a grid pattern problem by identifying maximal cross/diamond shapes of '*' characters.
 * Refactored for readability, maintainability, and adherence to Java best practices.
 */
public class StarPatternSolver {

    /**
     * Immutable record to store discovered star pattern information.
     */
    static class StarInfo {
        final int row;
        final int col;
        final int radius;

        StarInfo(int row, int col, int radius) {
            this.row = row;
            this.col = col;
            this.radius = radius;
        }
    }

    public static void main(String[] args) throws IOException {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));

        // Robust input parsing for dimensions
        String line = reader.readLine();
        if (line == null) return;
        StringTokenizer tokenizer = new StringTokenizer(line);
        int rows = Integer.parseInt(tokenizer.nextToken());
        int cols = Integer.parseInt(tokenizer.nextToken());

        char[][] grid = new char[rows][cols];
        boolean[][] isStar = new boolean[rows][cols];

        // Read grid and track star positions explicitly
        for (int r = 0; r < rows; r++) {
            String rowStr = reader.readLine().trim().replace(" ", "");
            for (int c = 0; c < cols && c < rowStr.length(); c++) {
                grid[r][c] = rowStr.charAt(c);
                isStar[r][c] = (rowStr.charAt(c) == '*');
            }
        }

        boolean[][] isCovered = new boolean[rows][cols];
        List<StarInfo> discoveredPatterns = new ArrayList<>();

        // Scan interior cells for pattern centers
        for (int r = 1; r < rows - 1; r++) {
            for (int c = 1; c < cols - 1; c++) {
                if (isStar[r][c]) {
                    int radius = findPatternRadius(r, c, grid, isCovered, rows, cols);
                    if (radius > 0) {
                        isCovered[r][c] = true;
                        discoveredPatterns.add(new StarInfo(r + 1, c + 1, radius));
                    }
                }
            }
        }

        // Verify all '*' characters in the grid are covered by at least one pattern
        boolean allStarsCovered = true;
        outerLoop:
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (isStar[r][c] && !isCovered[r][c]) {
                    allStarsCovered = false;
                    break outerLoop;
                }
            }
        }

        // Output results
        if (!allStarsCovered) {
            System.out.println("-1");
        } else {
            System.out.println(discoveredPatterns.size());
            for (StarInfo pattern : discoveredPatterns) {
                System.out.println(pattern.row + " " + pattern.col + " " + pattern.radius);
            }
        }
    }

    /**
     * Expands outward from a center point to find the maximum radius of a cross-shaped '*' pattern.
     * Marks all discovered '*' cells as covered in the isCovered matrix.
     *
     * @param centerRow    The row index of the pattern center
     * @param centerCol    The column index of the pattern center
     * @param grid         The character grid
     * @param isCovered    Boolean matrix tracking covered '*' cells
     * @param totalRows    Total number of rows in the grid
     * @param totalCols    Total number of columns in the grid
     * @return             The maximum valid radius found (0 if no pattern exists)
     */
    private static int findPatternRadius(int centerRow, int centerCol, char[][] grid, 
                                         boolean[][] isCovered, int totalRows, int totalCols) {
        int radius = 1;

        while (true) {
            boolean allBoundaryStars = true;

            // Check the four cardinal directions at the current radius
            int[] dr = {-1, 1, 0, 0};
            int[] dc = {0, 0, -1, 1};

            for (int d = 0; d < 4; d++) {
                int r = centerRow + dr[d] * radius;
                int c = centerCol + dc[d] * radius;

                // Boundary or non-star check
                if (r < 0 || r >= totalRows || c < 0 || c >= totalCols || grid[r][c] != '*') {
                    allBoundaryStars = false;
                    break;
                }
            }

            if (!allBoundaryStars) {
                break;
            }

            // Mark discovered cells as covered
            for (int d = 0; d < 4; d++) {
                int r = centerRow + dr[d] * radius;
                int c = centerCol + dc[d] * radius;
                isCovered[r][c] = true;
            }

            radius++;
        }

        return radius - 1;
    }
}

import java.io.*;
import java.util.*;

public class E {

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner();
        int height = scanner.nextInt();
        int width = scanner.nextInt();

        // 1. Read and parse the grid
        boolean[][] grid = readGrid(scanner, height, width);

        // 2. Compute consecutive star counts in all 4 directions
        int[][] left = computeConsecutiveStars(grid, true, true);
        int[][] right = computeConsecutiveStars(grid, true, false);
        int[][] up = computeConsecutiveStars(grid, false, true);
        int[][] down = computeConsecutiveStars(grid, false, false);

        // 3. Identify valid squares and prepare sweep-line events
        List<List<Event>> eventsPerCol = new ArrayList<>(width);
        List<List<Event>> eventsPerRow = new ArrayList<>(height);
        for (int i = 0; i < width; i++) eventsPerCol.add(new ArrayList<>());
        for (int i = 0; i < height; i++) eventsPerRow.add(new ArrayList<>());

        List<Square> squares = new ArrayList<>();
        int starCount = 0;

        for (int x = 0; x < width; x++) {
            for (int y = 0; y < height; y++) {
                int radius = Math.min(Math.min(left[y][x], right[y][x]), Math.min(up[y][x], down[y][x]));
                if (radius >= 2) {
                    starCount++;
                    int startX = x - radius + 1;
                    int endX = x + radius - 1;
                    int startY = y - radius + 1;
                    int endY = y + radius - 1;

                    // Add sweep-line events for column and row projections
                    eventsPerCol.get(x).add(new Event(startY, 1));
                    eventsPerCol.get(x).add(new Event(endY + 1, -1));
                    eventsPerRow.get(y).add(new Event(startX, 1));
                    eventsPerRow.get(y).add(new Event(endX + 1, -1));

                    squares.add(new Square(y, x, radius));
                }
            }
        }

        // 4. Apply sweep-line algorithm to determine covered cells
        boolean[][] covered = new boolean[height][width];
        applySweepLine(eventsPerCol, covered, height, true);
        applySweepLine(eventsPerRow, covered, width, false);

        // 5. Verify that the union of squares exactly covers all '*' cells
        if (!verifyCoverage(grid, covered)) {
            System.out.println("-1");
            return;
        }

        // 6. Output results
        try (PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out))) {
            out.println(starCount);
            for (Square sq : squares) {
                out.println((sq.centerY + 1) + " " + (sq.centerX + 1) + " " + (sq.radius - 1));
            }
        }
    }

    /**
     * Reads the grid from input.
     * Coordinates: grid[row][col]
     */
    private static boolean[][] readGrid(FastScanner scanner, int height, int width) {
        boolean[][] grid = new boolean[height][width];
        for (int y = 0; y < height; y++) {
            String line = scanner.next();
            for (int x = 0; x < width; x++) {
                grid[y][x] = line.charAt(x) == '*';
            }
        }
        return grid;
    }

    /**
     * Computes the number of consecutive '*' cells in a given direction.
     * @param horizontal true for left/right, false for up/down
     * @param forward true for forward pass (left/up), false for backward pass (right/down)
     */
    private static int[][] computeConsecutiveStars(boolean[][] grid, boolean horizontal, boolean forward) {
        int h = grid.length;
        int w = grid[0].length;
        int[][] counts = new int[h][w];

        int start = forward ? 0 : (horizontal ? w - 1 : h - 1);
        int end = forward ? (horizontal ? w : h) : -1;
        int step = forward ? 1 : -1;

        if (horizontal) {
            for (int x = start; x != end; x += step) {
                for (int y = 0; y < h; y++) {
                    if (grid[y][x]) {
                        int prev = forward ? (x == 0 ? 0 : counts[y][x - 1]) : (x == w - 1 ? 0 : counts[y][x + 1]);
                        counts[y][x] = prev + 1;
                    }
                }
            }
        } else {
            for (int y = start; y != end; y += step) {
                for (int x = 0; x < w; x++) {
                    if (grid[y][x]) {
                        int prev = forward ? (y == 0 ? 0 : counts[y - 1][x]) : (y == h - 1 ? 0 : counts[y + 1][x]);
                        counts[y][x] = prev + 1;
                    }
                }
            }
        }
        return counts;
    }

    /**
     * Applies the sweep-line algorithm to mark covered cells in the grid.
     * @param events List of events per axis (column or row)
     * @param painted 2D array to mark covered cells
     * @param length Dimension size along the sweep direction
     * @param isColumnSweep true if sweeping columns (x-axis fixed), false for rows (y-axis fixed)
     */
    private static void applySweepLine(List<List<Event>> events, boolean[][] painted, int length, boolean isColumnSweep) {
        for (int axis = 0; axis < events.size(); axis++) {
            List<Event> eventList = events.get(axis);
            Collections.sort(eventList);

            int idx = 0;
            int activeCount = 0;
            for (int pos = 0; pos < length; pos++) {
                while (idx < eventList.size() && eventList.get(idx).pos == pos) {
                    activeCount += eventList.get(idx).delta;
                    idx++;
                }
                if (activeCount > 0) {
                    if (isColumnSweep) {
                        painted[pos][axis] = true; // pos is y, axis is x
                    } else {
                        painted[axis][pos] = true; // axis is y, pos is x
                    }
                }
            }
        }
    }

    /**
     * Verifies that every '*' in the original grid is covered, and no '.' is covered.
     */
    private static boolean verifyCoverage(boolean[][] grid, boolean[][] covered) {
        for (int y = 0; y < grid.length; y++) {
            for (int x = 0; x < grid[0].length; x++) {
                if (grid[y][x] != covered[y][x]) {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Represents an event for the sweep-line algorithm.
     */
    private static class Event implements Comparable<Event> {
        final int pos;
        final int delta;

        Event(int pos, int delta) {
            this.pos = pos;
            this.delta = delta;
        }

        @Override
        public int compareTo(Event other) {
            return Integer.compare(this.pos, other.pos);
        }
    }

    /**
     * Represents a valid square found in the grid.
     */
    private static class Square {
        final int centerY;
        final int centerX;
        final int radius;

        Square(int centerY, int centerX, int radius) {
            this.centerY = centerY;
            this.centerX = centerX;
            this.radius = radius;
        }
    }

    /**
     * Fast I/O utility for competitive programming.
     */
    static class FastScanner {
        BufferedReader br;
        StringTokenizer st;

        FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) throw new IOException("Unexpected end of input");
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    e.printStackTrace();
                    return null;
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        long nextLong() {
            return Long.parseLong(next());
        }

        double nextDouble() {
            return Double.parseDouble(next());
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

public class F_CF {

    public static void main(String[] args) {
        FastScanner fs = new FastScanner();
        PrintWriter pw = new PrintWriter(System.out);

        int t = 1;
        for (int tc = 0; tc < t; tc++) {
            int n = fs.nextInt();
            int m = fs.nextInt();

            // 1. Parse input grid
            boolean[][] isStar = new boolean[n][m];
            for (int i = 0; i < n; i++) {
                String line = fs.next();
                for (int j = 0; j < m; j++) {
                    isStar[i][j] = line.charAt(j) == '*';
                }
            }

            // 2. Compute directional distances to the nearest '*'
            int[][] left = new int[n][m];
            int[][] right = new int[n][m];
            int[][] up = new int[n][m];
            int[][] down = new int[n][m];

            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    if (isStar[i][j]) {
                        left[i][j] = (j > 0) ? left[i][j - 1] + 1 : 1;
                    }
                }
                for (int j = m - 1; j >= 0; j--) {
                    if (isStar[i][j]) {
                        right[i][j] = (j < m - 1) ? right[i][j + 1] + 1 : 1;
                    }
                }
            }

            for (int j = 0; j < m; j++) {
                for (int i = 0; i < n; i++) {
                    if (isStar[i][j]) {
                        up[i][j] = (i > 0) ? up[i - 1][j] + 1 : 1;
                    }
                }
                for (int i = n - 1; i >= 0; i--) {
                    if (isStar[i][j]) {
                        down[i][j] = (i < n - 1) ? down[i + 1][j] + 1 : 1;
                    }
                }
            }

            // 3. Find valid squares and apply 2D difference arrays
            int squareCount = 0;
            StringBuilder output = new StringBuilder();
            int[][] rowDiff = new int[n][m];
            int[][] colDiff = new int[n][m];

            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    if (!isStar[i][j]) continue;

                    // Maximum square radius centered at (i, j)
                    int radius = Math.min(Math.min(left[i][j], right[i][j]),
                                          Math.min(up[i][j], down[i][j])) - 1;

                    if (radius > 0) {
                        squareCount++;
                        output.append(i + 1).append(' ').append(j + 1).append(' ').append(radius).append('\n');

                        // Mark covered rows in column difference array
                        colDiff[i][j - radius]++;
                        if (j + radius + 1 < m) colDiff[i][j + radius + 1]--;

                        // Mark covered columns in row difference array
                        rowDiff[i - radius][j]++;
                        if (i + radius + 1 < n) rowDiff[i + radius + 1][j]--;
                    }
                }
            }

            // 4. Compute prefix sums to determine coverage
            boolean[][] isCovered = new boolean[n][m];
            int currentSum = 0;

            // Process column differences
            for (int j = 0; j < m; j++) {
                currentSum = 0;
                for (int i = 0; i < n; i++) {
                    currentSum += colDiff[i][j];
                    if (currentSum > 0) isCovered[i][j] = true;
                }
            }

            // Process row differences and verify all '*' are covered
            boolean allCovered = true;
            for (int j = 0; j < m; j++) {
                currentSum = 0;
                for (int i = 0; i < n; i++) {
                    currentSum += rowDiff[i][j];
                    if (currentSum > 0) isCovered[i][j] = true;

                    if (isStar[i][j] && !isCovered[i][j]) {
                        allCovered = false;
                        break;
                    }
                }
                if (!allCovered) break;
            }

            // 5. Output results
            if (allCovered) {
                pw.println(squareCount);
                pw.print(output);
            } else {
                pw.println(-1);
            }
        }
        pw.flush();
        pw.close();
    }

    /**
     * Fast I/O helper for competitive programming.
     */
    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in), 32768);
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input", e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        long nextLong() {
            return Long.parseLong(next());
        }

        double nextDouble() {
            return Double.parseDouble(next());
        }

        String nextLine() {
            String str = "";
            try {
                str = br.readLine();
            } catch (IOException e) {
                throw new RuntimeException("Failed to read line", e);
            }
            return str;
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.ArrayList;
import java.util.List;
import java.util.StringTokenizer;

/**
 * Refactored solution for grid star coverage problem.
 * 
 * Improvements:
 * - Removed unused algorithms (Sieve, DFS, DP, GCD) and dead code.
 * - Replaced global mutable state with local variables and instance methods.
 * - Fixed coordinate storage bug (flattened list -> paired coordinates).
 * - Extracted repetitive directional scanning into reusable helpers.
 * - Applied try-with-resources for proper I/O cleanup.
 * - Improved naming conventions and added JavaDoc.
 */
public class Main {

    public static void main(String[] args) throws IOException {
        try (PrintWriter out = new PrintWriter(System.out)) {
            new Main().solve(new FastScanner(System.in), out);
        }
    }

    private void solve(FastScanner scanner, PrintWriter out) throws IOException {
        int n = scanner.nextInt();
        int m = scanner.nextInt();
        char[][] grid = new char[n][m];

        for (int i = 0; i < n; i++) {
            grid[i] = scanner.nextLine().toCharArray();
        }

        List<int[]> centers = findCenters(grid, n, m);

        if (centers.isEmpty()) {
            out.println(hasStar(grid, n, m) ? -1 : 0);
            return;
        }

        boolean[][] isCovered = new boolean[n][m];
        StringBuilder output = new StringBuilder();

        for (int[] center : centers) {
            int r = center[0];
            int c = center[1];
            int minArmLength = calculateMinArmLength(grid, n, m, r, c);
            int radius = Math.max(0, minArmLength - 1);

            markCross(isCovered, r, c, radius);

            output.append(r + 1).append(' ')
                  .append(c + 1).append(' ')
                  .append(radius).append('\n');
        }

        if (!isFullyCovered(grid, isCovered, n, m)) {
            out.println(-1);
            return;
        }

        out.println(centers.size());
        out.print(output);
    }

    private List<int[]> findCenters(char[][] grid, int n, int m) {
        List<int[]> centers = new ArrayList<>();
        for (int i = 1; i < n - 1; i++) {
            for (int j = 1; j < m - 1; j++) {
                if (grid[i][j] == '*' &&
                    grid[i + 1][j] == '*' && grid[i - 1][j] == '*' &&
                    grid[i][j + 1] == '*' && grid[i][j - 1] == '*') {
                    centers.add(new int[]{i, j});
                }
            }
        }
        return centers;
    }

    private boolean hasStar(char[][] grid, int n, int m) {
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == '*') return true;
            }
        }
        return false;
    }

    private int calculateMinArmLength(char[][] grid, int n, int m, int r, int c) {
        int min = Integer.MAX_VALUE;
        min = Math.min(min, countConsecutive(grid, r, c, -1, 0, n, m)); // Up
        min = Math.min(min, countConsecutive(grid, r, c, 1, 0, n, m));  // Down
        min = Math.min(min, countConsecutive(grid, r, c, 0, -1, n, m)); // Left
        min = Math.min(min, countConsecutive(grid, r, c, 0, 1, n, m));  // Right
        return min;
    }

    private int countConsecutive(char[][] grid, int startR, int startC, int dr, int dc, int n, int m) {
        int count = 0;
        for (int r = startR, c = startC; 
             r >= 0 && r < n && c >= 0 && c < m && grid[r][c] == '*'; 
             r += dr, c += dc) {
            count++;
        }
        return count;
    }

    private void markCross(boolean[][] isCovered, int r, int c, int radius) {
        for (int i = r - radius; i <= r + radius; i++) {
            isCovered[i][c] = true;
        }
        for (int j = c - radius; j <= c + radius; j++) {
            isCovered[r][j] = true;
        }
    }

    private boolean isFullyCovered(char[][] grid, boolean[][] isCovered, int n, int m) {
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == '*' && !isCovered[i][j]) {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Fast input scanner optimized for competitive programming.
     */
    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner(InputStream input) {
            br = new BufferedReader(new InputStreamReader(input));
        }

        public String next() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) throw new IOException("Unexpected end of input");
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        public long nextLong() throws IOException {
            return Long.parseLong(next());
        }

        public String nextLine() throws IOException {
            return br.readLine();
        }

        public double nextDouble() throws IOException {
            return Double.parseDouble(next());
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.ArrayList;
import java.util.List;
import java.util.StringTokenizer;

/**
 * Main entry point for the Star Grid Drawing solver.
 * Sets up fast I/O and delegates problem-solving to the dedicated solver class.
 */
public class Main {
    public static void main(String[] args) {
        FastScanner scanner = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out);

        StarGridSolver solver = new StarGridSolver();
        solver.solve(1, scanner, out);

        out.close();
    }

    /**
     * Solves the star grid drawing problem.
     * Identifies maximal star shapes covering all '*' cells and outputs their coordinates and lengths.
     */
    static class StarGridSolver {
        public void solve(int testNumber, FastScanner in, PrintWriter out) {
            int n = in.nextInt();
            int m = in.nextInt();
            char[][] grid = new char[n][];
            for (int i = 0; i < n; i++) {
                grid[i] = in.next().toCharArray();
            }

            List<StarPlacement> placements = new ArrayList<>();
            findAndPlaceStars(grid, placements);

            if (allStarsCovered(grid)) {
                out.println(placements.size());
                for (StarPlacement s : placements) {
                    out.printf("%d %d %d%n", s.row + 1, s.col + 1, s.length);
                }
            } else {
                out.println(-1);
            }
        }

        /**
         * Checks if every '*' cell in the grid has been covered.
         */
        private boolean allStarsCovered(char[][] grid) {
            for (char[] row : grid) {
                for (char cell : row) {
                    if (cell == '*') {
                        return false;
                    }
                }
            }
            return true;
        }

        /**
         * Iterates through the grid to find and place maximal stars.
         * Greedily selects the largest valid star centered on each '*' cell.
         */
        private void findAndPlaceStars(char[][] grid, List<StarPlacement> placements) {
            int maxLen = Math.min(grid.length, grid[0].length);
            for (int r = 0; r < grid.length; r++) {
                for (int c = 0; c < grid[0].length; c++) {
                    if (grid[r][c] == '*') {
                        for (int k = maxLen; k >= 1; k--) {
                            if (canPlaceStar(grid, r, c, k)) {
                                placements.add(new StarPlacement(r, c, k));
                                markStarsAsCovered(grid, r, c, k);
                                break;
                            }
                        }
                    }
                }
            }
        }

        /**
         * Validates if a star of length k can be placed at (r, c).
         * A valid star must consist entirely of '*' cells within bounds.
         */
        private boolean canPlaceStar(char[][] grid, int r, int c, int k) {
            int rows = grid.length;
            int cols = grid[0].length;

            // Validate vertical arm
            for (int i = r - k; i <= r + k; i++) {
                if (i < 0 || i >= rows || grid[i][c] != '*') {
                    return false;
                }
            }

            // Validate horizontal arm
            for (int i = c - k; i <= c + k; i++) {
                if (i < 0 || i >= cols || grid[r][i] != '*') {
                    return false;
                }
            }

            return true;
        }

        /**
         * Marks the cells covered by a star as '.' (covered).
         * Assumes bounds and validity have already been verified by canPlaceStar().
         */
        private void markStarsAsCovered(char[][] grid, int r, int c, int k) {
            for (int i = r - k; i <= r + k; i++) {
                grid[i][c] = '.';
            }
            for (int i = c - k; i <= c + k; i++) {
                grid[r][i] = '.';
            }
        }
    }

    /**
     * Immutable data class representing a placed star.
     */
    static class StarPlacement {
        final int row;
        final int col;
        final int length;

        StarPlacement(int row, int col, int length) {
            this.row = row;
            this.col = col;
            this.length = length;
        }
    }

    /**
     * Fast input reader for competitive programming scenarios.
     * Wraps BufferedReader and StringTokenizer for efficient token parsing.
     */
    static class FastScanner {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        FastScanner(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
            tokenizer = null;
        }

        String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input", e);
                }
            }
            return tokenizer.nextToken();
        }

        int nextInt() {
            String token = next();
            if (token == null) throw new RuntimeException("Unexpected end of input");
            return Integer.parseInt(token);
        }
    }
}

import java.util.*;

public class Main {

    public static void main(String[] args) {
        // Use try-with-resources to automatically close the scanner
        try (Scanner scanner = new Scanner(System.in)) {
            if (!scanner.hasNextInt()) return;

            int n = scanner.nextInt();
            int m = scanner.nextInt();
            scanner.nextLine(); // Consume the newline left by nextInt()

            char[][] grid = new char[n][m];
            boolean[][] isStar = new boolean[n][m];
            boolean[][] isCovered = new boolean[n][m];

            readGrid(scanner, grid, isStar, n, m);

            List<Star> stars = findLargestStars(grid, isStar, isCovered, n, m);
            validateCoverage(grid, isStar, isCovered, n, m);
            printResults(stars, n, m);
        }
    }

    /**
     * Reads the grid from input and populates star position tracking.
     */
    private static void readGrid(Scanner scanner, char[][] grid, boolean[][] isStar, int n, int m) {
        for (int i = 0; i < n; i++) {
            String line = scanner.nextLine();
            for (int j = 0; j < m; j++) {
                grid[i][j] = line.charAt(j);
                if (grid[i][j] == '*') {
                    isStar[i][j] = true;
                }
            }
        }
    }

    /**
     * Finds the largest valid cross centered at each '*' cell.
     * Uses a Map to ensure only the largest star per center is kept.
     */
    private static List<Star> findLargestStars(char[][] grid, boolean[][] isStar, boolean[][] isCovered, int n, int m) {
        List<Star> stars = new ArrayList<>();
        Map<Point, Star> starMap = new HashMap<>();

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == '*') {
                    int maxSize = 0;
                    // Expand size until the cross becomes invalid
                    for (int size = 1; ; size++) {
                        if (!isValidCross(grid, isStar, isCovered, i, j, size, n, m)) {
                            break;
                        }
                        maxSize = size;
                    }

                    if (maxSize > 0) {
                        Point center = new Point(i, j);
                        Star newStar = new Star(i, j, maxSize);
                        // Keep the largest size if a star already exists at this center
                        starMap.merge(center, newStar, (existing, replacement) -> replacement);

                        // Mark cells as covered immediately to prevent arm overlap with future stars
                        for (int k = -maxSize; k <= maxSize; k++) {
                            isCovered[i][j + k] = true;
                            isCovered[i + k][j] = true;
                        }
                    }
                }
            }
        }
        return new ArrayList<>(starMap.values());
    }

    /**
     * Validates if a cross of a given size can be placed at (r, c).
     * Checks boundaries and ensures no overlap with existing stars or covered cells.
     */
    private static boolean isValidCross(char[][] grid, boolean[][] isStar, boolean[][] isCovered, int r, int c, int size, int n, int m) {
        // Check boundary constraints
        if (r - size < 0 || r + size >= n || c - size < 0 || c + size >= m) {
            return false;
        }

        // Check vertical and horizontal arms for overlapping stars or already covered cells
        for (int k = -size; k <= size; k++) {
            if (k == 0) continue; // Skip the center itself
            if (isStar[r][c + k] || isStar[r + k][c] || isCovered[r][c + k] || isCovered[r + k][c]) {
                return false;
            }
        }
        return true;
    }

    /**
     * Verifies that every '*' cell in the grid is covered by at least one star.
     */
    private static void validateCoverage(char[][] grid, boolean[][] isStar, boolean[][] isCovered, int n, int m) {
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (isStar[i][j] && !isCovered[i][j]) {
                    System.out.println(-1);
                    return;
                }
            }
        }
    }

    /**
     * Outputs the count of stars and their details.
     */
    private static void printResults(List<Star> stars, int n, int m) {
        System.out.println(stars.size());
        for (Star star : stars) {
            System.out.println(star);
        }
    }

    /**
     * Represents a star cross on the grid.
     */
    private static class Star {
        final int i, j, size;

        Star(int i, int j, int size) {
            this.i = i;
            this.j = j;
            this.size = size;
        }

        @Override
        public boolean equals(Object o) {
            if (this == o) return true;
            if (!(o instanceof Star)) return false;
            Star star = (Star) o;
            return i == star.i && j == star.j;
        }

        @Override
        public int hashCode() {
            return Objects.hash(i, j);
        }

        @Override
        public String toString() {
            // Outputting 1-based indices to maintain compatibility with original behavior
            return (i + 1) + " " + (j + 1) + " " + size;
        }
    }

    /**
     * Simple coordinate class used as a map key for star centers.
     */
    private static class Point {
        final int x, y;

        Point(int x, int y) {
            this.x = x;
            this.y = y;
        }

        @Override
        public boolean equals(Object o) {
            if (this == o) return true;
            if (!(o instanceof Point)) return false;
            Point point = (Point) o;
            return x == point.x && y == point.y;
        }

        @Override
        public int hashCode() {
            return Objects.hash(x, y);
        }
    }
}

import java.util.*;

public class problem1015E1 {

    /**
     * Represents a valid star cross found in the grid.
     * Coordinates are stored in 0-based indexing for internal consistency.
     */
    private static class Cross {
        final int r, c, len;

        Cross(int r, int c, int len) {
            this.r = r;
            this.c = c;
            this.len = len;
        }
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        if (!scanner.hasNextInt()) return;

        int n = scanner.nextInt();
        int m = scanner.nextInt();

        char[][] grid = new char[n][m];
        for (int i = 0; i < n; i++) {
            grid[i] = scanner.next().toCharArray();
        }

        // 1. Identify all valid crosses
        List<Cross> crosses = findCrosses(grid, n, m);

        // 2. Validate that every '*' in the grid is covered by a cross
        if (!isFullyCovered(grid, n, m, crosses)) {
            System.out.println(-1);
            return;
        }

        // 3. Output results (convert to 1-based indexing here)
        System.out.println(crosses.size());
        for (Cross cross : crosses) {
            System.out.println((cross.r + 1) + " " + (cross.c + 1) + " " + cross.len);
        }
    }

    /**
     * Scans the grid to find all valid star crosses.
     */
    private static List<Cross> findCrosses(char[][] grid, int n, int m) {
        List<Cross> crosses = new ArrayList<>();

        // Boundaries are excluded since a cross needs space in all 4 directions
        for (int i = 1; i < n - 1; i++) {
            for (int j = 1; j < m - 1; j++) {
                if (grid[i][j] == '*') {
                    int offset = 1;
                    while (isValidArm(grid, n, m, i, j, offset)) {
                        offset++;
                    }
                    int armLength = offset - 1;

                    // A valid cross must have at least one arm segment (length >= 1)
                    if (armLength > 0) {
                        crosses.add(new Cross(i, j, armLength));
                    }
                }
            }
        }
        return crosses;
    }

    /**
     * Checks if the four arms extend validly at the given offset from the center.
     */
    private static boolean isValidArm(char[][] grid, int n, int m, int centerR, int centerC, int offset) {
        return centerR - offset >= 0 && centerR + offset < n &&
               centerC - offset >= 0 && centerC + offset < m &&
               grid[centerR - offset][centerC] == '*' &&
               grid[centerR + offset][centerC] == '*' &&
               grid[centerR][centerC - offset] == '*' &&
               grid[centerR][centerC + offset] == '*';
    }

    /**
     * Verifies that all '*' characters in the grid are covered by the detected crosses.
     */
    private static boolean isFullyCovered(char[][] grid, int n, int m, List<Cross> crosses) {
        boolean[][] covered = new boolean[n][m];
        int totalStars = 0;

        // Count total stars and initialize coverage grid
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == '*') {
                    totalStars++;
                }
            }
        }

        // Mark covered positions
        for (Cross cross : crosses) {
            covered[cross.r][cross.c] = true;
            for (int k = 1; k <= cross.len; k++) {
                covered[cross.r - k][cross.c] = true;
                covered[cross.r + k][cross.c] = true;
                covered[cross.r][cross.c - k] = true;
                covered[cross.r][cross.c + k] = true;
            }
        }

        // Verify every star is covered
        int coveredStars = 0;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == '*' && covered[i][j]) {
                    coveredStars++;
                }
            }
        }

        return coveredStars == totalStars;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.ArrayList;
import java.util.List;
import java.util.StringTokenizer;

public class Main {
    public static void main(String[] args) {
        FastScanner in = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out);
        Solver.solve(1, in, out);
        out.flush();
        out.close();
    }

    static class Solver {
        public static void solve(int testNumber, FastScanner in, PrintWriter out) {
            int n = in.nextInt();
            int m = in.nextInt();

            char[][] grid = new char[n][m];
            for (int i = 0; i < n; i++) {
                grid[i] = in.next().toCharArray();
            }

            boolean[][] isCovered = new boolean[n][m];
            List<Star> stars = new ArrayList<>();

            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    if (grid[i][j] != '.') {
                        int armLength = calculateMaxArmLength(grid, i, j, n, m);
                        if (armLength > 0) {
                            isCovered[i][j] = true;
                            stars.add(new Star(i + 1, j + 1, armLength));
                            markCross(isCovered, i, j, armLength);
                        }
                    }
                }
            }

            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    if (grid[i][j] != '.' && !isCovered[i][j]) {
                        out.println(-1);
                        return;
                    }
                }
            }

            out.println(stars.size());
            for (Star star : stars) {
                out.println(star.x + " " + star.y + " " + star.r);
            }
        }

        private static int calculateMaxArmLength(char[][] grid, int row, int col, int n, int m) {
            int up = 0, down = 0, left = 0, right = 0;

            for (int i = row - 1; i >= 0; i--) {
                if (grid[i][col] != '.') up++;
                else break;
            }
            for (int i = row + 1; i < n; i++) {
                if (grid[i][col] != '.') down++;
                else break;
            }
            for (int i = col - 1; i >= 0; i--) {
                if (grid[row][i] != '.') left++;
                else break;
            }
            for (int i = col + 1; i < m; i++) {
                if (grid[row][i] != '.') right++;
                else break;
            }

            return Math.min(Math.min(up, down), Math.min(left, right));
        }

        private static void markCross(boolean[][] isCovered, int row, int col, int armLength) {
            for (int i = row - armLength; i <= row + armLength; i++) {
                isCovered[i][col] = true;
            }
            for (int i = col - armLength; i <= col + armLength; i++) {
                isCovered[row][i] = true;
            }
        }

        static class Star {
            final int x;
            final int y;
            final int r;

            Star(int x, int y, int r) {
                this.x = x;
                this.y = y;
                this.r = r;
            }
        }
    }

    static class FastScanner {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastScanner(InputStream stream) {
            this.reader = new BufferedReader(new InputStreamReader(stream));
            this.tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input", e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public String nextLine() {
            try {
                return reader.readLine();
            } catch (IOException e) {
                throw new RuntimeException("Failed to read line", e);
            }
        }
    }
}

import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.ArrayList;
import java.util.InputMismatchException;
import java.util.List;

public class E501 {

    public static void main(String[] args) {
        FastScanner in = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            int exitCode = solve(in, out);
            if (exitCode == -1) {
                out.println("-1");
            }
        } finally {
            out.flush();
            out.close();
        }
    }

    /**
     * Orchestrates the grid processing pipeline.
     * @return 0 on success, -1 if reconstruction fails validation
     */
    private static int solve(FastScanner in, PrintWriter out) {
        int R = in.nextInt();
        int C = in.nextInt();

        boolean[][] board = readGrid(in, R, C);

        // Compute consecutive '*' counts in four directions
        int[][] up = new int[R][C];
        int[][] left = new int[R][C];
        for (int i = 1; i < R - 1; i++) {
            for (int j = 1; j < C - 1; j++) {
                if (board[i][j]) {
                    if (board[i - 1][j]) up[i][j] = up[i - 1][j] + 1;
                    if (board[i][j - 1]) left[i][j] = left[i][j - 1] + 1;
                }
            }
        }

        int[][] down = new int[R][C];
        int[][] right = new int[R][C];
        for (int i = R - 2; i >= 1; i--) {
            for (int j = C - 2; j >= 1; j--) {
                if (board[i][j]) {
                    if (board[i + 1][j]) down[i][j] = down[i + 1][j] + 1;
                    if (board[i][j + 1]) right[i][j] = right[i][j + 1] + 1;
                }
            }
        }

        // Identify valid crosses
        List<Cross> crosses = new ArrayList<>();
        for (int i = 1; i < R - 1; i++) {
            for (int j = 1; j < C - 1; j++) {
                if (board[i][j]) {
                    int radius = Math.min(Math.min(up[i][j], left[i][j]), Math.min(down[i][j], right[i][j]));
                    if (radius > 0) {
                        // Store 1-based coordinates for output format
                        crosses.add(new Cross(i + 1, j + 1, radius));
                    }
                }
            }
        }

        // Reconstruct the board from detected crosses
        boolean[][] reconstructed = new boolean[R][C];
        for (Cross cross : crosses) {
            int centerR = cross.row() - 1;
            int centerC = cross.col() - 1;
            int radius = cross.radius();

            reconstructed[centerR][centerC] = true;
            for (int d = 1; d <= radius; d++) {
                reconstructed[centerR - d][centerC] = true;
                reconstructed[centerR + d][centerC] = true;
                reconstructed[centerR][centerC - d] = true;
                reconstructed[centerR][centerC + d] = true;
            }
        }

        // Validate that reconstruction exactly matches the original board
        for (int i = 0; i < R; i++) {
            for (int j = 0; j < C; j++) {
                if (board[i][j] != reconstructed[i][j]) {
                    return -1;
                }
            }
        }

        // Output results
        out.println(crosses.size());
        for (Cross cross : crosses) {
            out.println(cross.row() + " " + cross.col() + " " + cross.radius());
        }

        return 0;
    }

    private static boolean[][] readGrid(FastScanner in, int R, int C) {
        boolean[][] board = new boolean[R][C];
        for (int i = 0; i < R; i++) {
            String row = in.next();
            for (int j = 0; j < C; j++) {
                board[i][j] = row.charAt(j) == '*';
            }
        }
        return board;
    }

    /**
     * Represents a detected cross on the grid.
     */
    private static class Cross {
        final int row;
        final int col;
        final int radius;

        public Cross(int row, int col, int radius) {
            this.row = row;
            this.col = col;
            this.radius = radius;
        }
    }

    /**
     * High-performance input scanner for competitive programming.
     */
    public static class FastScanner {
        private InputStream stream;
        private byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;

        public FastScanner(InputStream stream) {
            this.stream = stream;
        }

        int read() {
            if (numChars == -1)
                throw new InputMismatchException();
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0)
                    return -1;
            }
            return buf[curChar++];
        }

        boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        boolean isEndline(int c) {
            return c == '\n' || c == '\r' || c == -1;
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }

        public double nextDouble() {
            return Double.parseDouble(next());
        }

        public String next() {
            int c = read();
            while (isSpaceChar(c))
                c = read();
            StringBuilder res = new StringBuilder();
            do {
                res.appendCodePoint(c);
                c = read();
            } while (!isSpaceChar(c));
            return res.toString();
        }

        public String nextLine() {
            int c = read();
            while (isEndline(c))
                c = read();
            StringBuilder res = new StringBuilder();
            do {
                res.appendCodePoint(c);
                c = read();
            } while (!isEndline(c));
            return res.toString();
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Processes a character grid to find and mark star crosses.
 * Refactored for maintainability, type safety, and separation of concerns.
 */
public class StarGridProcessor {

    public static void main(String[] args) throws IOException {
        // try-with-resources ensures proper cleanup of I/O streams
        try (FastScanner sc = new FastScanner();
             PrintWriter out = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)))) {

            if (!sc.hasNext()) {
                return;
            }

            int n = sc.nextInt();
            int m = sc.nextInt();

            // Read grid rows safely without newline consumption issues
            char[][] grid = new char[n][];
            for (int i = 0; i < n; i++) {
                grid[i] = sc.next().toCharArray();
            }

            CrossDetector detector = new CrossDetector(grid);
            List<Star> foundCrosses = detector.findCrosses();

            if (detector.hasRemainingStars()) {
                out.println(-1);
            } else {
                out.println(foundCrosses.size());
                for (Star star : foundCrosses) {
                    out.println(star);
                }
            }
        }
    }

    /**
     * Encapsulates all logic for detecting and painting star crosses on the grid.
     */
    static class CrossDetector {
        private final char[][] grid;
        private final int rows;
        private final int cols;
        private final int[][] left;
        private final int[][] right;
        private final int[][] top;
        private final int[][] bottom;

        public CrossDetector(char[][] grid) {
            this.grid = grid;
            this.rows = grid.length;
            this.cols = grid[0].length;
            this.left = new int[rows][cols];
            this.right = new int[rows][cols];
            this.top = new int[rows][cols];
            this.bottom = new int[rows][cols];
            computeDirectionCounts();
        }

        private void computeDirectionCounts() {
            // Left: propagate count from left to right
            for (int i = 0; i < rows; i++) {
                for (int j = 1; j < cols; j++) {
                    if (grid[i][j] == '*' && grid[i][j - 1] == '*') {
                        left[i][j] = left[i][j - 1] + 1;
                    }
                }
            }

            // Right: propagate count from right to left
            for (int i = 0; i < rows; i++) {
                for (int j = cols - 2; j >= 0; j--) {
                    if (grid[i][j] == '*' && grid[i][j + 1] == '*') {
                        right[i][j] = right[i][j + 1] + 1;
                    }
                }
            }

            // Top: propagate count from top to bottom
            for (int i = 1; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j] == '*' && grid[i - 1][j] == '*') {
                        top[i][j] = top[i - 1][j] + 1;
                    }
                }
            }

            // Bottom: propagate count from bottom to top
            for (int i = rows - 2; i >= 0; i--) {
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j] == '*' && grid[i + 1][j] == '*') {
                        bottom[i][j] = bottom[i + 1][j] + 1;
                    }
                }
            }
        }

        /**
         * Finds all valid crosses, records them, and paints them over in the grid.
         */
        public List<Star> findCrosses() {
            List<Star> crosses = new ArrayList<>();

            // Crosses must have at least one cell margin from the edges
            for (int i = 1; i < rows - 1; i++) {
                for (int j = 1; j < cols - 1; j++) {
                    int l = left[i][j];
                    int r = right[i][j];
                    int t = top[i][j];
                    int b = bottom[i][j];

                    // A valid cross requires stars in all four directions
                    if (l == 0 || r == 0 || t == 0 || b == 0) {
                        continue;
                    }

                    int size = Math.min(Math.min(l, r), Math.min(t, b));
                    crosses.add(new Star(i, j, size));
                    paintCross(i, j, size);
                }
            }
            return crosses;
        }

        /**
         * Marks the cross centered at (i, j) with the given size as empty ('.').
         */
        private void paintCross(int i, int j, int size) {
            for (int k = i - size; k <= i + size; k++) {
                grid[k][j] = '.';
            }
            for (int k = j - size; k <= j + size; k++) {
                grid[i][k] = '.';
            }
        }

        /**
         * Checks if any '*' characters remain in the grid.
         */
        public boolean hasRemainingStars() {
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j] == '*') {
                        return true;
                    }
                }
            }
            return false;
        }
    }

    /**
     * Represents a detected star cross with its 0-based center coordinates and arm length.
     */
    static class Star {
        final int x;
        final int y;
        final int size;

        Star(int x, int y, int size) {
            this.x = x;
            this.y = y;
            this.size = size;
        }

        @Override
        public String toString() {
            // Output uses 1-based indexing as per original specification
            return (x + 1) + " " + (y + 1) + " " + size;
        }
    }

    /**
     * High-performance scanner for competitive programming / fast I/O.
     * Handles tokenization and newline consumption safely.
     */
    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        public boolean hasNext() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) {
                        return false;
                    }
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    return false;
                }
            }
            return true;
        }

        public String next() {
            if (hasNext()) {
                return st.nextToken();
            }
            throw new NoSuchElementException("No more tokens available.");
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.ArrayList;
import java.util.List;
import java.util.StringTokenizer;

public class Main {

    /**
     * Helper class to store information about a found cross.
     */
    private static class Cross {
        int x, y, size;

        public Cross(int x, int y, int size) {
            this.x = x;
            this.y = y;
            this.size = size;
        }
    }

    FastScanner in;
    PrintWriter out;

    private void solve() throws IOException {
        // Read grid dimensions
        String nStr = in.next();
        if (nStr == null) return; // Handle empty input gracefully
        int rows = Integer.parseInt(nStr);
        int cols = in.nextInt();

        // Grid to identify obstacles ('*')
        boolean[][] isObstacle = new boolean[rows][cols];
        // Grid to track if a cell is covered by a cross
        boolean[][] isCovered = new boolean[rows][cols];

        // Parse the input grid
        for (int i = 0; i < rows; i++) {
            String line = in.next();
            for (int j = 0; j < cols; j++) {
                char c = line.charAt(j);
                boolean isStar = (c == '*');
                isObstacle[i][j] = isStar;

                // Initialize coverage: 
                // Non-obstacle cells are considered "covered" (true) by default in the original logic.
                // Obstacle cells ('*') are "uncovered" (false) initially.
                isCovered[i][j] = !isStar;
            }
        }

        List<Cross> foundCrosses = new ArrayList<>();

        // Iterate through every cell to find potential cross centers
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                // A cross must be centered on an obstacle ('*')
                if (isObstacle[i][j]) {
                    int maxRadius = 0;
                    int dist = 1;

                    // Expand outwards to find the maximum valid radius
                    while (true) {
                        boolean valid = true;

                        // Check Top
                        if (i - dist < 0 || !isObstacle[i - dist][j]) valid = false;
                        // Check Bottom
                        else if (i + dist >= rows || !isObstacle[i + dist][j]) valid = false;
                        // Check Left
                        else if (j - dist < 0 || !isObstacle[i][j - dist]) valid = false;
                        // Check Right
                        else if (j + dist >= cols || !isObstacle[i][j + dist]) valid = false;

                        if (valid) {
                            // Mark the arm cells as covered
                            isCovered[i - dist][j] = true;
                            isCovered[i + dist][j] = true;
                            isCovered[i][j - dist] = true;
                            isCovered[i][j + dist] = true;

                            // Mark the center as covered.
                            // In the original code, this was explicitly handled when l==1.
                            // Here, since dist starts at 1, this executes for the first step.
                            isCovered[i][j] = true;

                            maxRadius = dist;
                            dist++;
                        } else {
                            // Expansion failed at this distance
                            break;
                        }
                    }

                    // If a valid cross was found (radius >= 1), record it
                    if (maxRadius > 0) {
                        foundCrosses.add(new Cross(i, j, maxRadius));
                    }
                }
            }
        }

        // Verify that all cells are covered.
        // In the original logic, non-obstacle cells were pre-marked true.
        // Obstacle cells needed to be marked true by the cross expansion.
        // If any cell is false, the configuration is invalid.
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (!isCovered[i][j]) {
                    out.println(-1);
                    return;
                }
            }
        }

        // Output the results
        out.println(foundCrosses.size());
        for (Cross c : foundCrosses) {
            // Convert 0-based indices to 1-based for output
            out.println((c.x + 1) + " " + (c.y + 1) + " " + c.size);
        }
    }

    /**
     * FastScanner class for efficient input reading.
     */
    static class FastScanner {
        BufferedReader br;
        StringTokenizer st;

        FastScanner(InputStream s) {
            br = new BufferedReader(new InputStreamReader(s));
        }

        String next() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) return null;
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

        int nextInt() throws IOException {
            String s = next();
            if (s == null) throw new IOException("Unexpected end of input");
            return Integer.parseInt(s);
        }
    }

    private void run() throws IOException {
        in = new FastScanner(System.in);
        out = new PrintWriter(System.out);

        try {
            solve();
        } finally {
            out.flush();
            out.close();
        }
    }

    public static void main(String[] args) throws IOException {
        new Main().run();
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayList;
import java.util.List;
import java.util.StringTokenizer;

/**
 * Refactored solution for the Cross Pattern problem (originally E501).
 * 
 * This version improves maintainability by:
 * 1. Encapsulating state within a class instance rather than using static globals.
 * 2. Using descriptive variable and method names.
 * 3. Separating concerns: Input reading, Grid processing, and Output formatting.
 * 4. Adding comments to explain the logic.
 */
public class CrossPatternSolver {

    // Instance variables to hold problem state
    private int rows;
    private int cols;
    private char[][] grid;
    private int[][] starIdMap; // Maps (row, col) to a unique ID for tracking coverage
    private boolean[] starCovered;
    private List<String> results;

    public static void main(String[] args) throws IOException {
        CrossPatternSolver solver = new CrossPatternSolver();
        solver.solve();
    }

    /**
     * Main execution flow.
     */
    private void solve() throws IOException {
        readInput();
        mapStars();
        findAndMarkCrosses();
        verifyAndPrintOutput();
    }

    /**
     * Reads dimensions and grid from standard input.
     */
    private void readInput() throws IOException {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        String line = reader.readLine();
        if (line == null) return;

        StringTokenizer st = new StringTokenizer(line);
        this.rows = Integer.parseInt(st.nextToken());
        this.cols = Integer.parseInt(st.nextToken());

        this.grid = new char[rows][cols];
    }

    /**
     * Parses the grid, assigning unique IDs to stars ('*') for efficient tracking.
     */
    private void mapStars() throws IOException {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        this.starIdMap = new int[rows][cols];
        int starCount = 0;

        for (int r = 0; r < rows; r++) {
            String rowLine = reader.readLine();
            if (rowLine != null) {
                for (int c = 0; c < cols; c++) {
                    grid[r][c] = rowLine.charAt(c);
                    if (grid[r][c] == '*') {
                        starIdMap[r][c] = starCount++;
                    } else {
                        starIdMap[r][c] = -1; // Mark empty space
                    }
                }
            }
        }

        // Initialize coverage tracker
        this.starCovered = new boolean[starCount];
        this.results = new ArrayList<>();
    }

    /**
     * Iterates through the grid to find valid cross patterns and marks covered stars.
     */
    private void findAndMarkCrosses() {
        // Iterate through potential centers. 
        // A center cannot be on the border (index 0 or max-1) as it needs neighbors.
        for (int r = 1; r < rows - 1; r++) {
            for (int c = 1; c < cols - 1; c++) {
                // Check if current cell and its immediate neighbors form a cross of size 1
                if (isCenterValid(r, c)) {
                    int radius = 1;
                    // Expand the cross as much as possible
                    while (isCrossTipValid(r, c, radius)) {
                        radius++;
                    }

                    // The loop exits when radius is invalid, so valid size is radius - 1
                    int validSize = radius - 1;

                    // Mark all stars in this cross as covered
                    markCross(r, c, validSize);

                    // Store result (1-based indexing for output)
                    results.add((r + 1) + " " + (c + 1) + " " + validSize);
                }
            }
        }
    }

    /**
     * Checks if the cell at (r, c) and its 4 immediate neighbors are stars.
     */
    private boolean isCenterValid(int r, int c) {
        return grid[r][c] == '*' &&
               grid[r - 1][c] == '*' && grid[r + 1][c] == '*' &&
               grid[r][c - 1] == '*' && grid[r][c + 1] == '*';
    }

    /**
     * Checks if the tips of a cross of a given radius at (r, c) are valid stars.
     */
    private boolean isCrossTipValid(int r, int c, int radius) {
        // Check bounds for the tips of the cross
        if (r < radius || r >= rows - radius || 
            c < radius || c >= cols - radius) {
            return false;
        }

        // Check if the tips are stars
        return grid[r + radius][c] == '*' &&
               grid[r - radius][c] == '*' &&
               grid[r][c + radius] == '*' &&
               grid[r][c - radius] == '*';
    }

    /**
     * Marks all stars belonging to a cross centered at (r, c) with the given size.
     */
    private void markCross(int r, int c, int size) {
        // Mark the center and all arms
        // The cross consists of points (r, c) +/- (k, 0) and (r, c) +/- (0, k) for 0 <= k <= size
        for (int k = 0; k <= size; k++) {
            // Vertical arm
            markStarIfStar(r - k, c);
            markStarIfStar(r + k, c);

            // Horizontal arm
            markStarIfStar(r, c - k);
            markStarIfStar(r, c + k);
        }
    }

    /**
     * Helper to mark a star as covered if the cell contains a star.
     */
    private void markStarIfStar(int r, int c) {
        int id = starIdMap[r][c];
        if (id != -1) {
            starCovered[id] = true;
        }
    }

    /**
     * Verifies if all stars in the grid were covered by at least one cross.
     * Prints the results or -1 if coverage is incomplete.
     */
    private void verifyAndPrintOutput() {
        boolean allCovered = true;
        for (boolean covered : starCovered) {
            if (!covered) {
                allCovered = false;
                break;
            }
        }

        if (allCovered) {
            System.out.println(results.size());
            for (String result : results) {
                System.out.println(result);
            }
        } else {
            System.out.println(-1);
        }
    }
}

import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.Scanner;

public class CrossPatternAnalyzer {

    public static void main(String[] args) {
        // Use try-with-resources to automatically close the Scanner
        try (Scanner scanner = new Scanner(System.in)) {
            if (!scanner.hasNextInt()) {
                return;
            }

            int n = scanner.nextInt();
            int m = scanner.nextInt();

            char[][] originalGrid = new char[n][m];
            for (int i = 0; i < n; i++) {
                originalGrid[i] = scanner.next().toCharArray();
            }

            List<Cross> crosses = findCrosses(originalGrid);
            char[][] drawnGrid = drawCrosses(originalGrid, crosses);

            if (!validateGrids(originalGrid, drawnGrid)) {
                System.out.println(-1);
            } else {
                System.out.println(crosses.size());
                for (Cross cross : crosses) {
                    System.out.println(cross);
                }
            }
        }
    }

    /**
     * Scans the grid to find all valid cross patterns.
     * Only checks interior cells to avoid boundary issues during expansion.
     */
    private static List<Cross> findCrosses(char[][] grid) {
        List<Cross> crosses = new ArrayList<>();
        int rows = grid.length;
        int cols = grid[0].length;

        for (int i = 1; i < rows - 1; i++) {
            for (int j = 1; j < cols - 1; j++) {
                if (grid[i][j] == '*') {
                    Cross cross = findCrossRadius(grid, i, j);
                    if (cross != null) {
                        crosses.add(cross);
                    }
                }
            }
        }
        return crosses;
    }

    /**
     * Determines the maximum radius of a cross centered at (centerRow, centerCol).
     * Returns null if no cross (radius 0) is found.
     */
    private static Cross findCrossRadius(char[][] grid, int centerRow, int centerCol) {
        int radius = 0;
        while (true) {
            int nextRadius = radius + 1;
            int up = centerRow - nextRadius;
            int down = centerRow + nextRadius;
            int left = centerCol - nextRadius;
            int right = centerCol + nextRadius;

            // Check boundaries before accessing array
            if (up < 0 || down >= grid.length || left < 0 || right >= grid[0].length) {
                return radius > 0 ? new Cross(centerRow, centerCol, radius) : null;
            }

            char expected = grid[centerRow][centerCol];
            // Verify all four directions match the center character
            if (grid[up][centerCol] == expected &&
                grid[down][centerCol] == expected &&
                grid[centerRow][left] == expected &&
                grid[centerRow][right] == expected) {
                radius = nextRadius;
            } else {
                return radius > 0 ? new Cross(centerRow, centerCol, radius) : null;
            }
        }
    }

    /**
     * Creates a new grid and draws all found crosses onto it.
     */
    private static char[][] drawCrosses(char[][] originalGrid, List<Cross> crosses) {
        char[][] drawnGrid = new char[originalGrid.length][originalGrid[0].length];
        for (char[] row : drawnGrid) {
            Arrays.fill(row, '.');
        }

        for (Cross cross : crosses) {
            drawSingleCross(cross, drawnGrid);
        }
        return drawnGrid;
    }

    /**
     * Draws a single cross pattern onto the target grid.
     */
    private static void drawSingleCross(Cross cross, char[][] grid) {
        int r = cross.row;
        int c = cross.col;
        grid[r][c] = '*';
        for (int i = 1; i <= cross.radius; i++) {
            grid[r - i][c] = '*';
            grid[r + i][c] = '*';
            grid[r][c - i] = '*';
            grid[r][c + i] = '*';
        }
    }

    /**
     * Validates that the drawn grid exactly matches the original grid.
     */
    private static boolean validateGrids(char[][] original, char[][] drawn) {
        for (int i = 0; i < original.length; i++) {
            if (!Arrays.equals(original[i], drawn[i])) {
                return false;
            }
        }
        return true;
    }

    /**
     * Immutable data class representing a cross pattern.
     * Coordinates are stored 0-indexed internally and converted to 1-indexed in toString().
     */
    private static class Cross {
        final int row;
        final int col;
        final int radius;

        public Cross(int row, int col, int radius) {
            this.row = row;
            this.col = col;
            this.radius = radius;
        }

        @Override
        public String toString() {
            // Output format: 1-based row, 1-based column, radius
            return (row + 1) + " " + (col + 1) + " " + radius;
        }
    }
}

import java.io.*;
import java.util.*;

public class Main {
    // Configuration flags (typically toggled via command line or IDE in CP environments)
    public static boolean MULTIPLE_TEST_CASES = false;
    public static boolean USE_MEMORY_THREAD = false;

    private FastReader in;
    private PrintWriter out;

    public static void main(String[] args) throws Exception {
        if (USE_MEMORY_THREAD) {
            new Thread(null, new Runnable() {
                public void run() {
                    try {
                        new Main().run();
                    } catch (Exception e) {
                        e.printStackTrace();
                    }
                }
            }, "1", 1 << 28).start();
        } else {
            new Main().run();
        }
    }

    /**
     * Initializes I/O, handles test case loop, and ensures resources are flushed/closed.
     */
    public void run() throws Exception {
        in = new FastReader();
        out = new PrintWriter(System.out);
        int testCases = MULTIPLE_TEST_CASES ? in.nextInt() : 1;
        for (int t = 1; t <= testCases; t++) {
            solve(t);
        }
        out.flush();
        out.close();
    }

    /**
     * Reads input for a single test case and delegates to the core processing logic.
     */
    private void solve(int testCase) throws Exception {
        int rows = in.nextInt();
        int cols = in.nextInt();
        char[][] grid = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            grid[i] = in.next().toCharArray();
        }
        processGrid(grid, rows, cols);
    }

    /**
     * Core algorithm: processes the grid, calculates valid star positions,
     * marks covered cells, and writes the final result.
     */
    private void processGrid(char[][] grid, int rows, int cols) {
        boolean[][] isCovered = new boolean[rows][cols];
        StringBuilder results = new StringBuilder();
        int coveredStarCount = 0;

        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == '*') {
                    int minDistance = calculateMinDistanceToDot(grid, i, j, rows, cols);
                    if (minDistance > 0) {
                        coveredStarCount++;
                        results.append(i + 1).append(' ').append(j + 1).append(' ').append(minDistance).append('\n');
                        markCoveredCells(isCovered, i, j, minDistance);
                    }
                }
            }
        }

        boolean hasUncoveredStar = false;
        outerLoop:
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == '*' && !isCovered[i][j]) {
                    hasUncoveredStar = true;
                    break outerLoop;
                }
            }
        }

        if (hasUncoveredStar) {
            out.println(-1);
        } else {
            out.println(coveredStarCount);
            out.print(results);
        }
    }

    /**
     * Calculates the minimum distance from a star to the nearest '.' in any of the 4 cardinal directions.
     * Returns 0 if the star is on the boundary or adjacent to a '.' in any direction.
     */
    private int calculateMinDistanceToDot(char[][] grid, int r, int c, int rows, int cols) {
        int minDist = Integer.MAX_VALUE;

        // Check Up
        for (int i = r - 1; i >= 0; i--) {
            if (grid[i][c] == '.') break;
            minDist = Math.min(minDist, r - i);
        }
        // Check Down
        for (int i = r + 1; i < rows; i++) {
            if (grid[i][c] == '.') break;
            minDist = Math.min(minDist, i - r);
        }
        // Check Left
        for (int j = c - 1; j >= 0; j--) {
            if (grid[r][j] == '.') break;
            minDist = Math.min(minDist, c - j);
        }
        // Check Right
        for (int j = c + 1; j < cols; j++) {
            if (grid[r][j] == '.') break;
            minDist = Math.min(minDist, j - c);
        }

        // If no direction was traversed (e.g., star is on the edge), minDist remains MAX_VALUE.
        // This correctly translates to a distance of 0.
        return minDist == Integer.MAX_VALUE ? 0 : minDist;
    }

    /**
     * Marks cells as covered based on the minimum distance from a valid star position.
     */
    private void markCoveredCells(boolean[][] isCovered, int r, int c, int minDist) {
        for (int k = 1; k <= minDist; k++) {
            isCovered[r][c - k] = true;
            isCovered[r][c + k] = true;
            isCovered[r - k][c] = true;
            isCovered[r + k][c] = true;
        }
    }

    /**
     * Optimized Fast I/O reader for competitive programming.
     */
    static class FastReader {
        private BufferedReader br;
        private StringTokenizer st;

        public FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        public FastReader(String filePath) throws FileNotFoundException {
            br = new BufferedReader(new FileReader(filePath));
        }

        String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    e.printStackTrace();
                    return null;
                }
            }
            return st.nextToken();
        }

        String nextLine() {
            String str = "";
            try {
                str = br.readLine();
            } catch (IOException e) {
                e.printStackTrace();
            }
            return str;
        }

        int nextInt() {
            String s = next();
            return s == null ? 0 : Integer.parseInt(s);
        }

        long nextLong() {
            String s = next();
            return s == null ? 0L : Long.parseLong(s);
        }

        double nextDouble() {
            String s = next();
            return s == null ? 0.0 : Double.parseDouble(s);
        }
    }
}

import java.io.*;
import java.util.*;

public class Main {
    private static final int INF = Integer.MAX_VALUE;

    public static void main(String[] args) {
        new Main().run();
    }

    public void run() {
        FastReader in = new FastReader();
        PrintWriter out = new PrintWriter(System.out);
        try {
            // Set to true if the input format starts with the number of test cases
            boolean multipleTestCases = false;
            int t = multipleTestCases ? in.nextInt() : 1;

            for (int tc = 1; tc <= t; tc++) {
                solve(in, out, tc);
            }
        } catch (IOException e) {
            e.printStackTrace();
        } finally {
            out.flush();
            out.close();
        }
    }

    private void solve(FastReader in, PrintWriter out, int testCase) throws IOException {
        int rows = in.nextInt();
        int cols = in.nextInt();
        char[][] grid = new char[rows][cols];

        for (int i = 0; i < rows; i++) {
            String line = in.next();
            grid[i] = line.toCharArray();
        }

        int[][] minDistances = calculateMinDistances(grid);
        int asteriskCount = 0;
        int[][] hDiff = new int[rows][cols];
        int[][] vDiff = new int[rows][cols];
        StringBuilder result = new StringBuilder();

        // Process each asterisk: calculate distance, mark coverage ranges, and record output
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == '*') {
                    asteriskCount++;
                    int dist = minDistances[i][j];

                    // Update horizontal difference array
                    int hStart = Math.max(0, j - dist);
                    int hEnd = Math.min(cols - 1, j + dist);
                    hDiff[i][hStart]++;
                    if (hEnd + 1 < cols) hDiff[i][hEnd + 1]--;

                    // Update vertical difference array
                    int vStart = Math.max(0, i - dist);
                    int vEnd = Math.min(rows - 1, i + dist);
                    vDiff[vStart][j]++;
                    if (vEnd + 1 < rows) vDiff[vEnd + 1][j]--;

                    // Record result (1-based indexing)
                    result.append((i + 1)).append(' ').append((j + 1)).append(' ').append(dist).append('\n');
                }
            }
        }

        // Compute prefix sums and validate coverage
        boolean isValid = true;
        for (int i = 0; i < rows; i++) {
            int currentH = 0;
            int currentV = 0;
            for (int j = 0; j < cols; j++) {
                currentH += hDiff[i][j];
                currentV += vDiff[i][j];

                // If an asterisk has zero coverage in both directions, the configuration is invalid
                if (grid[i][j] == '*' && Math.max(currentH, currentV) == 0) {
                    isValid = false;
                    break;
                }
            }
            if (!isValid) break;
        }

        if (!isValid) {
            out.println(-1);
        } else {
            out.println(asteriskCount);
            out.print(result);
        }
    }

    /**
     * Calculates the minimum distance from each cell to the nearest '.' in all 4 directions.
     * Uses four directional passes instead of grid rotation for better readability and performance.
     */
    private int[][] calculateMinDistances(char[][] grid) {
        int rows = grid.length;
        int cols = grid[0].length;
        int[][] distances = new int[rows][cols];

        for (int[] row : distances) {
            Arrays.fill(row, INF);
        }

        // Top to Bottom
        for (int j = 0; j < cols; j++) {
            int d = 0;
            for (int i = 0; i < rows; i++) {
                if (grid[i][j] == '.') d = 0;
                else d = (i > 0) ? d + 1 : 1;
                distances[i][j] = Math.min(distances[i][j], d);
            }
        }
        // Bottom to Top
        for (int j = 0; j < cols; j++) {
            int d = 0;
            for (int i = rows - 1; i >= 0; i--) {
                if (grid[i][j] == '.') d = 0;
                else d = (i < rows - 1) ? d + 1 : 1;
                distances[i][j] = Math.min(distances[i][j], d);
            }
        }
        // Left to Right
        for (int i = 0; i < rows; i++) {
            int d = 0;
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == '.') d = 0;
                else d = (j > 0) ? d + 1 : 1;
                distances[i][j] = Math.min(distances[i][j], d);
            }
        }
        // Right to Left
        for (int i = 0; i < rows; i++) {
            int d = 0;
            for (int j = cols - 1; j >= 0; j--) {
                if (grid[i][j] == '.') d = 0;
                else d = (j < cols - 1) ? d + 1 : 1;
                distances[i][j] = Math.min(distances[i][j], d);
            }
        }

        // Adjust distances to match original logic (subtract 1)
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (distances[i][j] != INF) {
                    distances[i][j]--;
                }
            }
        }
        return distances;
    }

    /**
     * Optimized Fast I/O reader for competitive programming.
     */
    static class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            String s = next();
            return s == null ? 0 : Integer.parseInt(s);
        }

        String nextLine() {
            String str = "";
            try {
                str = br.readLine();
            } catch (IOException e) {
                e.printStackTrace();
            }
            return str;
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Refactored solution for the star grid coverage problem.
 * Improvements:
 * - Separated concerns into logical methods (I/O, grid processing, sweep-line, validation)
 * - Removed unused utility methods and redundant wrappers
 * - Eliminated duplicated sweep-line logic
 * - Used descriptive naming and modern Java practices
 * - Added proper type safety and suppressed unchecked warnings where necessary
 */
public class Main {

    public static void main(String[] args) throws IOException {
        FastScanner sc = new FastScanner();
        PrintWriter out = new PrintWriter(System.out);

        // Original code hardcoded t=1; kept for compatibility
        int t = 1;
        while (t-- > 0) {
            solve(sc, out);
        }

        out.flush();
        out.close();
    }

    private static void solve(FastScanner sc, PrintWriter out) throws IOException {
        // 1. Read dimensions and grid
        int width = sc.nextInt();
        int height = sc.nextInt();
        boolean[][] grid = new boolean[width][height];

        for (int y = 0; y < height; y++) {
            String line = sc.next();
            for (int x = 0; x < width; x++) {
                grid[x][y] = line.charAt(x) == '*';
            }
        }

        // 2. Compute consecutive star counts in all 4 directions
        int[][] left = new int[width][height];
        int[][] right = new int[width][height];
        int[][] up = new int[width][height];
        int[][] down = new int[width][height];

        for (int x = 0; x < width; x++) {
            for (int y = 0; y < height; y++) {
                if (grid[x][y]) {
                    left[x][y] = (x > 0 ? left[x - 1][y] : 0) + 1;
                    up[x][y] = (y > 0 ? up[x][y - 1] : 0) + 1;
                }
            }
        }

        for (int x = width - 1; x >= 0; x--) {
            for (int y = height - 1; y >= 0; y--) {
                if (grid[x][y]) {
                    right[x][y] = (x < width - 1 ? right[x + 1][y] : 0) + 1;
                    down[x][y] = (y < height - 1 ? down[x][y + 1] : 0) + 1;
                }
            }
        }

        // 3. Identify valid star centers and generate sweep-line events
        @SuppressWarnings("unchecked")
        List<SweepEvent>[] eventsX = new ArrayList[width];
        @SuppressWarnings("unchecked")
        List<SweepEvent>[] eventsY = new ArrayList[height];
        for (int i = 0; i < width; i++) eventsX[i] = new ArrayList<>();
        for (int i = 0; i < height; i++) eventsY[i] = new ArrayList<>();

        List<StarInfo> validStars = new ArrayList<>();
        int starCount = 0;

        for (int x = 0; x < width; x++) {
            for (int y = 0; y < height; y++) {
                if (!grid[x][y]) continue;

                int radius = Math.min(Math.min(left[x][y], right[x][y]), 
                                      Math.min(up[x][y], down[x][y]));

                if (radius >= 2) {
                    starCount++;
                    int startX = x - radius + 1;
                    int endX = x + radius - 1;
                    int startY = y - radius + 1;
                    int endY = y + radius - 1;

                    // X-axis sweep: mark vertical spans for each column x
                    eventsX[x].add(new SweepEvent(startY, 1));
                    eventsX[x].add(new SweepEvent(endY + 1, -1));

                    // Y-axis sweep: mark horizontal spans for each row y
                    eventsY[y].add(new SweepEvent(startX, 1));
                    eventsY[y].add(new SweepEvent(endX + 1, -1));

                    validStars.add(new StarInfo(y + 1, x + 1, radius - 1));
                }
            }
        }

        // 4. Apply sweep-line algorithm to determine covered cells
        boolean[][] painted = new boolean[width][height];
        applySweepLine(eventsX, painted, width, height);
        applySweepLine(eventsY, painted, height, width);

        // 5. Validate coverage and output results
        for (int x = 0; x < width; x++) {
            for (int y = 0; y < height; y++) {
                if (grid[x][y] != painted[x][y]) {
                    out.println(-1);
                    return;
                }
            }
        }

        out.println(starCount);
        for (StarInfo star : validStars) {
            out.println(star.y + " " + star.x + " " + star.radius);
        }
    }

    /**
     * Processes sweep-line events to mark covered cells in the painted grid.
     * Handles both X-axis and Y-axis sweeps generically.
     */
    private static void applySweepLine(List<SweepEvent>[] events, boolean[][] painted, 
                                       int outerDim, int innerDim) {
        for (int i = 0; i < outerDim; i++) {
            Collections.sort(events[i]);
            int eventIdx = 0;
            int activeSegments = 0;

            for (int j = 0; j < innerDim; j++) {
                while (eventIdx < events[i].size() && events[i].get(eventIdx).coordinate == j) {
                    activeSegments += events[i].get(eventIdx).delta;
                    eventIdx++;
                }
                if (activeSegments > 0) {
                    painted[i][j] = true;
                }
            }
        }
    }

    /** Represents a sweep-line event with a coordinate and delta change */
    static class SweepEvent implements Comparable<SweepEvent> {
        final int coordinate;
        final int delta;

        SweepEvent(int coordinate, int delta) {
            this.coordinate = coordinate;
            this.delta = delta;
        }

        @Override
        public int compareTo(SweepEvent other) {
            return Integer.compare(this.coordinate, other.coordinate);
        }
    }

    /** Stores validated star information for output */
    static class StarInfo {
        final int y, x, radius;

        StarInfo(int y, int x, int radius) {
            this.y = y;
            this.x = x;
            this.radius = radius;
        }
    }

    /** High-performance input scanner for competitive programming */
    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        FastScanner(String filePath) throws FileNotFoundException {
            br = new BufferedReader(new FileReader(filePath));
        }

        String next() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) throw new EOFException("Unexpected end of input");
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        long nextLong() throws IOException {
            return Long.parseLong(next());
        }

        double nextDouble() throws IOException {
            return Double.parseDouble(next());
        }

        String nextLine() throws IOException {
            return br.readLine();
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.ArrayList;
import java.util.List;
import java.util.StringTokenizer;

public class E1 implements AutoCloseable {

    private final InputReader in;
    private final PrintWriter out;

    public E1() {
        this.in = new InputReader(System.in);
        this.out = new PrintWriter(System.out);
    }

    public void solve() {
        int n = in.nextInt();
        int m = in.nextInt();

        if (n == 0 || m == 0) {
            out.println(0);
            return;
        }

        char[][] grid = readGrid(n, m);
        List<Cross> crosses = findCrosses(grid);
        boolean[][] covered = markCoveredCells(grid, crosses);
        boolean allStarsCovered = allStarsAreCovered(grid, covered);

        if (allStarsCovered) {
            out.println(crosses.size());
            for (Cross cross : crosses) {
                out.println(cross.row() + " " + cross.col() + " " + cross.size());
            }
        } else {
            out.println(-1);
        }
    }

    private char[][] readGrid(int n, int m) {
        char[][] grid = new char[n][m];
        for (int i = 0; i < n; i++) {
            grid[i] = in.next().toCharArray();
        }
        return grid;
    }

    /**
     * Represents a valid cross pattern found in the grid.
     * Coordinates are 1-based to match the original output format.
     */
    private record Cross(int row, int col, int size) {}

    private List<Cross> findCrosses(char[][] grid) {
        List<Cross> crosses = new ArrayList<>();
        int n = grid.length;
        int m = grid[0].length;

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == '*') {
                    int radius = 0;
                    int up = i - 1, down = i + 1;
                    int left = j - 1, right = j + 1;

                    // Expand outward while all four arms contain '*'
                    while (up >= 0 && down < n && left >= 0 && right < m) {
                        if (grid[up][j] == '*' && grid[down][j] == '*' &&
                            grid[i][left] == '*' && grid[i][right] == '*') {
                            radius++;
                            up--;
                            down++;
                            left--;
                            right++;
                        } else {
                            break;
                        }
                    }

                    // A valid cross must have at least one expansion layer
                    if (radius > 0) {
                        crosses.add(new Cross(i + 1, j + 1, radius));
                    }
                }
            }
        }
        return crosses;
    }

    private boolean[][] markCoveredCells(char[][] grid, List<Cross> crosses) {
        boolean[][] covered = new boolean[grid.length][grid[0].length];

        for (Cross cross : crosses) {
            // Convert 1-based coordinates to 0-based
            int r = cross.row() - 1;
            int c = cross.col() - 1;
            int size = cross.size();

            // Mark center
            covered[r][c] = true;
            // Mark all arms up to the cross radius
            for (int k = 1; k <= size; k++) {
                covered[r - k][c] = true;
                covered[r + k][c] = true;
                covered[r][c - k] = true;
                covered[r][c + k] = true;
            }
        }
        return covered;
    }

    private boolean allStarsAreCovered(char[][] grid, boolean[][] covered) {
        for (int i = 0; i < grid.length; i++) {
            for (int j = 0; j < grid[i].length; j++) {
                if (grid[i][j] == '*' && !covered[i][j]) {
                    return false;
                }
            }
        }
        return true;
    }

    @Override
    public void close() throws IOException {
        in.close();
        out.close();
    }

    /**
     * Fast input reader for competitive programming / large I/O scenarios.
     */
    static class InputReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) {
                        throw new IOException("Unexpected end of input");
                    }
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input stream", e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }

        public void close() throws IOException {
            reader.close();
        }
    }

    public static void main(String[] args) {
        try (E1 solver = new E1()) {
            solver.solve();
        } catch (IOException e) {
            throw new RuntimeException("IO error during execution", e);
        }
    }
}

import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

public class Main {

    /**
     * Represents a detected star pattern in the grid.
     * Coordinates are stored as 0-based indices internally.
     */
    public static class Star {
        final int row;
        final int col;
        final int length;

        public Star(int row, int col, int length) {
            this.row = row;
            this.col = col;
            this.length = length;
        }
    }

    public void run() {
        try (Scanner scanner = new Scanner(System.in)) {
            int rows = scanner.nextInt();
            int cols = scanner.nextInt();

            boolean[][] originalGrid = new boolean[rows][cols];
            boolean[][] processedGrid = new boolean[rows][cols];

            // Initialize grids from input
            for (int i = 0; i < rows; i++) {
                String line = scanner.next();
                for (int j = 0; j < cols; j++) {
                    boolean isStar = line.charAt(j) == '*';
                    originalGrid[i][j] = isStar;
                    processedGrid[i][j] = isStar;
                }
            }

            List<Star> stars = new ArrayList<>();

            // Iterate through potential star centers (excluding borders)
            for (int i = 1; i < rows - 1; i++) {
                for (int j = 1; j < cols - 1; j++) {
                    if (!originalGrid[i][j]) {
                        continue;
                    }

                    int length = 0;
                    while (true) {
                        int nextLength = length + 1;

                        // Check grid boundaries
                        if (i - nextLength < 0 || i + nextLength >= rows ||
                            j - nextLength < 0 || j + nextLength >= cols) {
                            break;
                        }

                        // Check if all four arms at the next length are '*'
                        if (!originalGrid[i - nextLength][j] ||
                            !originalGrid[i + nextLength][j] ||
                            !originalGrid[i][j - nextLength] ||
                            !originalGrid[i][j + nextLength]) {
                            break;
                        }

                        // Mark arms as processed to prevent double-counting
                        processedGrid[i - nextLength][j] = false;
                        processedGrid[i + nextLength][j] = false;
                        processedGrid[i][j - nextLength] = false;
                        processedGrid[i][j + nextLength] = false;

                        length = nextLength;
                    }

                    // Record valid star and mark center as processed
                    if (length > 0) {
                        processedGrid[i][j] = false;
                        stars.add(new Star(i, j, length));
                    }
                }
            }

            // Check if any '*' characters remain unprocessed
            for (boolean[] row : processedGrid) {
                for (boolean cell : row) {
                    if (cell) {
                        System.out.println("-1");
                        return;
                    }
                }
            }

            // Output results
            System.out.println(stars.size());
            StringBuilder output = new StringBuilder();
            for (Star star : stars) {
                output.append(star.row + 1).append(' ')
                      .append(star.col + 1).append(' ')
                      .append(star.length).append('\n');
            }
            System.out.print(output);
        }
    }

    public static void main(String[] args) {
        new Main().run();
    }
}

import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.ArrayList;
import java.util.List;
import java.util.PriorityQueue;

/**
 * Main entry point for the star covering solver.
 * Reads a grid, identifies optimal star shapes, and greedily covers all '*' characters.
 */
public class Main {

    public static void main(String[] args) throws IOException {
        FastScanner scanner = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out);
        StarCoverer solver = new StarCoverer();
        solver.solve(1, scanner, out);
        out.close();
    }

    /**
    * Solver that identifies and covers star-shaped patterns in a 2D grid.
    */
    static class StarCoverer {

        public void solve(int testNumber, FastScanner scanner, PrintWriter out) {
            int rows = scanner.nextInt();
            int cols = scanner.nextInt();
            char[][] grid = new char[rows][];
            for (int i = 0; i < rows; i++) {
                grid[i] = scanner.nextCharArray();
            }

            // Priority queue to process stars from largest to smallest
            PriorityQueue<Star> starQueue = new PriorityQueue<>();
            for (int i = 1; i < rows - 1; i++) {
                for (int j = 1; j < cols - 1; j++) {
                    if (isStarCenter(grid, i, j)) {
                        int radius = 0;
                        while (canExtend(grid, i, j, radius)) {
                            radius++;
                        }
                        if (radius > 0) {
                            starQueue.add(new Star(i, j, radius));
                        }
                    }
                }
            }

            int count = 0;
            List<Star> selectedStars = new ArrayList<>(starQueue.size());

            // Greedily cover stars until the grid is empty or no candidates remain
            while (!starQueue.isEmpty() && hasRemainingStars(grid)) {
                Star currentStar = starQueue.poll();
                selectedStars.add(currentStar);
                count++;
                coverStar(grid, currentStar);
            }

            if (hasRemainingStars(grid)) {
                out.println(-1);
            } else {
                out.println(count);
                for (Star star : selectedStars) {
                    // Output uses 1-based indexing and radius-1 for size
                    out.println((star.row + 1) + " " + (star.col + 1) + " " + (star.radius - 1));
                }
            }
        }

        /**
         * Checks if the cell at (r, c) can serve as the center of a star.
         */
        private boolean isStarCenter(char[][] grid, int r, int c) {
            return grid[r][c] == '*' && checkArm(grid, r, c, 1);
        }

        /**
         * Verifies if a star of the given radius can be formed at (r, c).
         */
        private boolean canExtend(char[][] grid, int r, int c, int radius) {
            if (r - radius < 0 || r + radius >= grid.length ||
                c - radius < 0 || c + radius >= grid[0].length) {
                return false;
            }
            if (radius == 0) {
                return grid[r][c] == '*';
            }
            return grid[r - radius][c] == '*' &&
                   grid[r][c - radius] == '*' &&
                   grid[r + radius][c] == '*' &&
                   grid[r][c + radius] == '*';
        }

        /**
         * Checks if all four arms of a star exist at the given delta distance.
         */
        private boolean checkArm(char[][] grid, int r, int c, int delta) {
            return grid[r - delta][c] == '*' &&
                   grid[r][c - delta] == '*' &&
                   grid[r + delta][c] == '*' &&
                   grid[r][c + delta] == '*';
        }

        /**
         * Checks if any '*' characters remain in the grid.
         */
        private boolean hasRemainingStars(char[][] grid) {
            for (char[] row : grid) {
                for (char cell : row) {
                    if (cell == '*') {
                        return true;
                    }
                }
            }
            return false;
        }

        /**
         * Marks all cells of a star as covered ('.').
         */
        private void coverStar(char[][] grid, Star star) {
            int r = star.row;
            int c = star.col;
            for (int d = 0; d < star.radius; d++) {
                grid[r + d][c] = '.';
                grid[r - d][c] = '.';
                grid[r][c + d] = '.';
                grid[r][c - d] = '.';
            }
        }

        /**
         * Represents a star pattern found in the grid.
         */
        static class Star implements Comparable<Star> {
            final int row;
            final int col;
            final int radius;

            Star(int row, int col, int radius) {
                this.row = row;
                this.col = col;
                this.radius = radius;
            }

            @Override
            public int compareTo(Star other) {
                // Descending order by radius for greedy selection
                return Integer.compare(other.radius, this.radius);
            }
        }
    }

    /**
     * Fast I/O helper for competitive programming scenarios.
     */
    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0;
        private int buflen = 0;

        public FastScanner(InputStream in) {
            this.in = in;
        }

        private int readByte() throws IOException {
            if (ptr >= buflen) {
                ptr = 0;
                buflen = in.read(buffer);
                if (buflen <= 0) {
                    return -1;
                }
            }
            return buffer[ptr++] & 0xFF;
        }

        public int nextInt() throws IOException {
            int c = readByte();
            while (isSpaceChar(c)) {
                c = readByte();
            }
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = readByte();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9') {
                    throw new IOException("Invalid integer format");
                }
                res = res * 10 + (c - '0');
                c = readByte();
            } while (!isSpaceChar(c) && c != -1);
            return res * sgn;
        }

        public char[] nextCharArray() throws IOException {
            int c = readByte();
            while (isSpaceChar(c)) {
                c = readByte();
            }
            StringBuilder sb = new StringBuilder();
            while (!isSpaceChar(c) && c != -1) {
                sb.append((char) c);
                c = readByte();
            }
            return sb.toString().toCharArray();
        }

        private static boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }
    }
}

import java.io.BufferedReader;
import java.io.BufferedOutputStream;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.ArrayList;
import java.util.List;
import java.util.StringTokenizer;

public class Codeforces {

    /**
     * Helper class to store information about a valid star center.
     * Represents a star at (row, col) that is the center of a cross of size 'size'.
     */
    static class StarInfo {
        int row, col, size;

        public StarInfo(int row, int col, int size) {
            this.row = row;
            this.col = col;
            this.size = size;
        }

        @Override
        public String toString() {
            return row + " " + col + " " + size;
        }
    }

    public static void main(String[] args) throws IOException {
        // Use try-with-resources to ensure resources are closed properly
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
             PrintWriter pw = new PrintWriter(new BufferedOutputStream(System.out))) {

            // Read input dimensions
            String line = br.readLine();
            if (line == null) return;

            StringTokenizer st = new StringTokenizer(line);
            int n = Integer.parseInt(st.nextToken());
            int m = Integer.parseInt(st.nextToken());

            // Read the grid
            char[][] grid = new char[n][];
            for (int i = 0; i < n; i++) {
                grid[i] = br.readLine().toCharArray();
            }

            List<StarInfo> validStars = new ArrayList<>();
            boolean[][] isVisited = new boolean[n][m];

            // Direction vectors: Up, Down, Left, Right
            int[] dr = {-1, 1, 0, 0};
            int[] dc = {0, 0, -1, 1};

            // Iterate through each cell to find valid star centers
            for (int r = 0; r < n; r++) {
                for (int c = 0; c < m; c++) {
                    if (grid[r][c] == '*') {
                        // Calculate the minimum consecutive stars in all 4 directions
                        int minSpan = Integer.MAX_VALUE;

                        for (int d = 0; d < 4; d++) {
                            int count = 0;
                            int nr = r + dr[d];
                            int nc = c + dc[d];

                            // Count consecutive stars in the current direction
                            while (nr >= 0 && nr < n && nc >= 0 && nc < m && grid[nr][nc] == '*') {
                                count++;
                                nr += dr[d];
                                nc += dc[d];
                            }
                            minSpan = Math.min(minSpan, count);
                        }

                        // If the star is part of a cross (minSpan > 0), record it
                        if (minSpan > 0) {
                            // Store 1-based coordinates as per original logic
                            validStars.add(new StarInfo(r + 1, c + 1, minSpan));

                            // Mark the cross shape as visited
                            // The cross extends minSpan cells in each direction from the center (r, c)

                            // Mark vertical line
                            for (int k = r - minSpan; k <= r + minSpan; k++) {
                                if (k >= 0 && k < n) {
                                    isVisited[k][c] = true;
                                }
                            }

                            // Mark horizontal line
                            for (int k = c - minSpan; k <= c + minSpan; k++) {
                                if (k >= 0 && k < m) {
                                    isVisited[r][k] = true;
                                }
                            }
                        }
                    }
                }
            }

            // Check if all stars in the grid have been visited
            boolean allStarsCovered = true;
            outerLoop:
            for (int r = 0; r < n; r++) {
                for (int c = 0; c < m; c++) {
                    if (grid[r][c] == '*' && !isVisited[r][c]) {
                        allStarsCovered = false;
                        break outerLoop;
                    }
                }
            }

            if (!allStarsCovered) {
                pw.println("-1");
            } else {
                // Output the number of valid star centers
                pw.println(validStars.size());
                // Output each center's details
                for (StarInfo star : validStars) {
                    pw.println(star);
                }
            }
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Solves grid-based cross pattern detection problems.
 * Refactored for maintainability, bug fixes, and code quality.
 */
public class GridCrossSolver {

    public static void main(String[] args) {
        FastReader reader = new FastReader();
        PrintWriter out = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)));

        try {
            // Original code hardcoded t=1. Kept for compatibility but structured for extensibility.
            int testCases = 1;
            GridPatternSolver solver = new GridPatternSolver();
            for (int i = 1; i <= testCases; i++) {
                solver.solve(i, reader, out);
            }
        } finally {
            out.flush();
            out.close();
        }
    }

    /**
     * Contains the core algorithm for detecting valid cross patterns in a grid.
     */
    static class GridPatternSolver {
        public void solve(int testNumber, FastReader reader, PrintWriter out) {
            int n = reader.nextInt();
            int m = reader.nextInt();

            boolean[][] inputGrid = new boolean[n][m];
            // Use next() instead of nextLine() to safely skip whitespace/newlines after integers
            for (int i = 0; i < n; i++) {
                String line = reader.next();
                for (int j = 0; j < m && j < line.length(); j++) {
                    inputGrid[i][j] = line.charAt(j) == '*';
                }
            }

            boolean[][] coveredCells = new boolean[n][m];
            List<CrossRecord> validCrosses = new ArrayList<>();

            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    if (inputGrid[i][j]) {
                        int armLength = 0;
                        // Expand cross arms outward until boundaries or non-star cells are hit
                        while (true) {
                            int nextArmLength = armLength + 1;
                            if (isCrossValid(inputGrid, i, j, nextArmLength)) {
                                armLength = nextArmLength;
                                markCross(coveredCells, i, j, armLength);
                            } else {
                                break;
                            }
                        }
                        // Only record crosses with at least one arm in each direction (size >= 3)
                        if (armLength > 0) {
                            validCrosses.add(new CrossRecord(i + 1, j + 1, armLength));
                        }
                    }
                }
            }

            // Verify that the input grid exactly matches the covered cells
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    if (inputGrid[i][j] != coveredCells[i][j]) {
                        out.println(-1);
                        return;
                    }
                }
            }

            out.println(validCrosses.size());
            for (CrossRecord record : validCrosses) {
                out.println(record.row + " " + record.col + " " + record.armLength);
            }
        }

        /**
         * Checks if all four arms at the given distance are within bounds and contain '*'.
         */
        private boolean isCrossValid(boolean[][] grid, int row, int col, int armLength) {
            return isWithinBoundsAndStar(grid, row + armLength, col) &&
                   isWithinBoundsAndStar(grid, row - armLength, col) &&
                   isWithinBoundsAndStar(grid, row, col + armLength) &&
                   isWithinBoundsAndStar(grid, row, col - armLength);
        }

        /**
         * Marks the center and four arms at the specified distance as covered.
         */
        private void markCross(boolean[][] covered, int row, int col, int armLength) {
            covered[row][col] = true;
            covered[row + armLength][col] = true;
            covered[row - armLength][col] = true;
            covered[row][col + armLength] = true;
            covered[row][col - armLength] = true;
        }

        /**
         * Boundary and content check helper.
         */
        private boolean isWithinBoundsAndStar(boolean[][] grid, int x, int y) {
            return x >= 0 && x < grid.length && y >= 0 && y < grid[0].length && grid[x][y];
        }
    }

    /**
     * Immutable record class representing a valid cross pattern.
     * Replaces the original 'tup' class. Comparable removed as sorting was unused.
     */
    static class CrossRecord {
        final int row;
        final int col;
        final int armLength;

        CrossRecord(int row, int col, int armLength) {
            this.row = row;
            this.col = col;
            this.armLength = armLength;
        }
    }

    /**
     * Fast I/O helper class for competitive programming style inputs.
     * Fixed newline consumption issues and improved exception handling.
     */
    static class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        public FastReader(String filePath) throws FileNotFoundException {
            br = new BufferedReader(new FileReader(new File(filePath)));
        }

        public String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input stream", e);
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            String s = next();
            return s == null ? 0 : Integer.parseInt(s);
        }

        public long nextLong() {
            String s = next();
            return s == null ? 0L : Long.parseLong(s);
        }

        public double nextDouble() {
            String s = next();
            return s == null ? 0.0 : Double.parseDouble(s);
        }

        public String nextLine() {
            try {
                // Consume any remaining tokens in the current line to align with br.readLine()
                while (st != null && st.hasMoreTokens()) {
                    st.nextToken();
                }
                return br.readLine();
            } catch (IOException e) {
                throw new RuntimeException("Error reading line", e);
            }
        }
    }
}

import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

/**
 * Solves the cross-pattern covering problem on a 2D grid.
 * Identifies the largest cross patterns centered at '*' cells and verifies
 * if all '*' cells are covered by the identified patterns.
 */
public class CrossPatternSolver {

    /**
     * Represents a cross pattern found on the grid.
     * Coordinates are 1-based for output compatibility.
     */
    private static class CrossPattern {
        final int x;
        final int y;
        final int size;

        public CrossPattern(int x, int y, int size) {
            this.x = x;
            this.y = y;
            this.size = size;
        }

        @Override
        public String toString() {
            return x + " " + y + " " + size;
        }
    }

    /**
     * Encapsulates the result of the solving process.
     */
    private static class SolutionResult {
        final List<CrossPattern> patterns;
        final boolean isValid;

        public SolutionResult(List<CrossPattern> patterns, boolean isValid) {
            this.patterns = patterns;
            this.isValid = isValid;
        }
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        if (!scanner.hasNextInt()) {
            return;
        }

        int n = scanner.nextInt();
        int m = scanner.nextInt();

        boolean[][] board = readBoard(scanner, n, m);
        scanner.close();

        SolutionResult result = solve(board, n, m);

        if (!result.isValid) {
            System.out.println(-1);
        } else {
            System.out.println(result.patterns.size());
            for (CrossPattern pattern : result.patterns) {
                System.out.println(pattern);
            }
        }
    }

    /**
     * Reads the grid from the scanner and converts it to a boolean matrix.
     */
    private static boolean[][] readBoard(Scanner scanner, int n, int m) {
        boolean[][] board = new boolean[n][m];
        for (int i = 0; i < n; i++) {
            String row = scanner.next();
            for (int j = 0; j < m; j++) {
                board[i][j] = row.charAt(j) == '*';
            }
        }
        return board;
    }

    /**
     * Core algorithm to find cross patterns and validate coverage.
     */
    private static SolutionResult solve(boolean[][] board, int n, int m) {
        boolean[][] covered = new boolean[n][m];
        List<CrossPattern> patterns = new ArrayList<>();

        // Only inner cells can be centers of a valid cross (size >= 1)
        for (int i = 1; i < n - 1; i++) {
            for (int j = 1; j < m - 1; j++) {
                if (!board[i][j]) {
                    continue;
                }

                // Calculate maximum possible radius based on grid boundaries
                int maxRadius = Math.min(Math.min(i, n - i - 1), Math.min(j, m - j - 1));
                int foundRadius = 0;

                // Find the largest valid cross radius at this center
                for (int k = 1; k <= maxRadius; k++) {
                    if (board[i + k][j] && board[i - k][j] &&
                        board[i][j + k] && board[i][j - k]) {
                        foundRadius = k;
                    } else {
                        break;
                    }
                }

                // If a valid cross exists, mark its cells and store the pattern
                if (foundRadius > 0) {
                    covered[i][j] = true;
                    covered[i + foundRadius][j] = true;
                    covered[i - foundRadius][j] = true;
                    covered[i][j + foundRadius] = true;
                    covered[i][j - foundRadius] = true;

                    // Convert to 1-based indexing for output
                    patterns.add(new CrossPattern(i + 1, j + 1, foundRadius));
                }
            }
        }

        // Verify that every '*' cell in the original board is covered
        boolean allCovered = true;
        outerLoop:
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (board[i][j] && !covered[i][j]) {
                    allCovered = false;
                    break outerLoop;
                }
            }
        }

        return new SolutionResult(patterns, allCovered);
    }
}

import java.io.*;
import java.util.*;

public class Main {

    public static void main(String[] args) throws IOException {
        FastScanner sc = new FastScanner(System.in);
        PrintWriter pw = new PrintWriter(new BufferedOutputStream(System.out));

        try {
            long startTime = System.currentTimeMillis();
            long memoryStart = getUsedMemory();

            Solver solver = new Solver();
            solver.solve(sc, pw);

            long endTime = System.currentTimeMillis();
            long memoryEnd = getUsedMemory();

            System.err.println("Memory increased: " + (memoryEnd - memoryStart) / 1_000_000 + " MB");
            System.err.println("Time used: " + (endTime - startTime) + " ms.");
        } catch (Exception e) {
            System.err.println("An error occurred: " + e.getMessage());
            e.printStackTrace();
        } finally {
            pw.flush();
            pw.close();
        }
    }

    /**
     * Calculates currently used heap memory in bytes.
     */
    private static long getUsedMemory() {
        Runtime runtime = Runtime.getRuntime();
        return runtime.totalMemory() - runtime.freeMemory();
    }

    /**
     * Encapsulates the core algorithm for processing the grid.
     */
    static class Solver {

        public void solve(FastScanner sc, PrintWriter pw) {
            int n = sc.nextInt();
            int m = sc.nextInt();

            // Read input grid and convert to 0/1 matrix
            int[][] matrix = new int[n][m];
            for (int i = 0; i < n; i++) {
                String row = sc.next();
                for (int j = 0; j < m; j++) {
                    matrix[i][j] = (row.charAt(j) == '.') ? 0 : 1;
                }
            }

            // Compute prefix sums for rows and columns
            int[][] rowPrefix = new int[n][m + 1];
            int[][] colPrefix = new int[m][n + 1];

            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    rowPrefix[i][j + 1] = rowPrefix[i][j] + matrix[i][j];
                }
            }

            for (int j = 0; j < m; j++) {
                for (int i = 0; i < n; i++) {
                    colPrefix[j][i + 1] = colPrefix[j][i] + matrix[i][j];
                }
            }

            // Difference arrays for efficient range updates
            int[][] rowDiff = new int[n][m + 1];
            int[][] colDiff = new int[m][n + 1];
            List<int[]> validSquares = new ArrayList<>();

            // Find maximal valid squares and apply range updates
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    if (matrix[i][j] == 1) {
                        int k = findMaxRadius(rowPrefix[i], colPrefix[j], i, j, n, m);
                        if (k > 0) {
                            validSquares.add(new int[]{i, j, k});

                            // Update row difference array for range [j-k, j+k]
                            rowDiff[i][j - k]++;
                            rowDiff[i][j + k + 1]--;

                            // Update column difference array for range [i-k, i+k]
                            colDiff[j][i - k]++;
                            colDiff[j][i + k + 1]--;
                        }
                    }
                }
            }

            // Reconstruct the result matrix from difference arrays
            int[][] resultMatrix = new int[n][m];
            for (int i = 0; i < n; i++) {
                int currentVal = 0;
                for (int j = 0; j < m; j++) {
                    currentVal += rowDiff[i][j];
                    if (currentVal > 0) {
                        resultMatrix[i][j] = 1;
                    }
                }
            }

            for (int j = 0; j < m; j++) {
                int currentVal = 0;
                for (int i = 0; i < n; i++) {
                    currentVal += colDiff[j][i];
                    if (currentVal > 0) {
                        resultMatrix[i][j] = 1;
                    }
                }
            }

            // Validate the reconstructed matrix against the original
            boolean isValid = true;
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    if (resultMatrix[i][j] == 1 && matrix[i][j] == 0) {
                        throw new IllegalStateException("Validation failed: result contains 1 where input has 0.");
                    }
                    if (resultMatrix[i][j] == 0 && matrix[i][j] == 1) {
                        isValid = false;
                    }
                }
            }

            // Output results
            if (!isValid) {
                pw.println(-1);
            } else {
                pw.println(validSquares.size());
                for (int[] sq : validSquares) {
                    pw.println((sq[0] + 1) + " " + (sq[1] + 1) + " " + sq[2]);
                }
            }
        }

        /**
         * Binary search to find the maximum radius k such that 
         * the square centered at (i, j) with radius k contains only 1s.
         */
        private int findMaxRadius(int[] rowP, int[] colP, int i, int j, int n, int m) {
            int maxK = Math.min(Math.min(i, n - 1 - i), Math.min(j, m - 1 - j));
            int lo = 0, hi = maxK;

            while (lo <= hi) {
                int mid = (lo + hi) >>> 1;
                int rs = getPrefixSum(rowP, j - mid, j + mid + 1);
                int cs = getPrefixSum(colP, i - mid, i + mid + 1);
                int expected = 2 * mid + 1;

                if (rs != expected || cs != expected) {
                    hi = mid - 1;
                } else {
                    lo = mid + 1;
                }
            }
            return hi;
        }

        /**
         * Safely retrieves the sum of elements in the prefix array 
         * within the half-open interval [from, to).
         */
        private int getPrefixSum(int[] prefix, int from, int to) {
            if (from >= to) return 0;

            from = Math.max(0, from);
            to = Math.min(prefix.length - 1, to);

            return prefix[to] - prefix[from];
        }
    }

    /**
     * Fast I/O utility class to replace java.util.Scanner for performance.
     */
    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        public String next() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) throw new EOFException("End of input stream reached.");
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        public long nextLong() throws IOException {
            return Long.parseLong(next());
        }

        public double nextDouble() throws IOException {
            return Double.parseDouble(next());
        }
    }
}

import java.util.Scanner;

public class Main {

    public static void main(String[] args) {
        // Use try-with-resources to automatically close the scanner
        try (Scanner scanner = new Scanner(System.in)) {
            if (!scanner.hasNextInt()) {
                return;
            }
            int rows = scanner.nextInt();
            int cols = scanner.nextInt();

            char[][] grid = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                String line = scanner.next();
                grid[i] = line.toCharArray();
            }

            // Directional DP arrays
            int[][] up = new int[rows][cols];
            int[][] down = new int[rows][cols];
            int[][] left = new int[rows][cols];
            int[][] right = new int[rows][cols];

            computeDirections(grid, up, down, left, right);

            int count = 0;
            StringBuilder result = new StringBuilder();

            // Identify and mark crosses
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    // Only process unmarked stars
                    if (grid[i][j] == '*') {
                        int radius = Math.min(Math.min(up[i][j], down[i][j]),
                                              Math.min(left[i][j], right[i][j]));

                        if (radius > 0) {
                            count++;
                            markCross(grid, i, j, radius);
                            result.append(i + 1).append(" ")
                                  .append(j + 1).append(" ")
                                  .append(radius).append("\n");
                        }
                    }
                }
            }

            // Verify if all stars were covered
            if (hasUncoveredStars(grid)) {
                System.out.println(-1);
            } else {
                System.out.println(count);
                System.out.print(result);
            }
        }
    }

    /**
     * Computes the number of consecutive '*' characters in all four directions
     * for each cell in the grid.
     */
    private static void computeDirections(char[][] grid, int[][] up, int[][] down, 
                                          int[][] left, int[][] right) {
        int rows = grid.length;
        int cols = grid[0].length;

        // Top-left to bottom-right pass
        for (int i = 1; i < rows; i++) {
            for (int j = 1; j < cols; j++) {
                up[i][j] = (grid[i - 1][j] == '*') ? up[i - 1][j] + 1 : 0;
                left[i][j] = (grid[i][j - 1] == '*') ? left[i][j - 1] + 1 : 0;
            }
        }

        // Bottom-right to top-left pass
        for (int i = rows - 2; i >= 0; i--) {
            for (int j = cols - 2; j >= 0; j--) {
                down[i][j] = (grid[i + 1][j] == '*') ? down[i + 1][j] + 1 : 0;
                right[i][j] = (grid[i][j + 1] == '*') ? right[i][j + 1] + 1 : 0;
            }
        }
    }

    /**
     * Marks a cross of given radius centered at (row, col) with 'x'.
     */
    private static void markCross(char[][] grid, int row, int col, int radius) {
        for (int i = row - radius; i <= row + radius; i++) {
            grid[i][col] = 'x';
        }
        for (int j = col - radius; j <= col + radius; j++) {
            grid[row][j] = 'x';
        }
    }

    /**
     * Checks if any '*' remains uncovered in the grid.
     */
    private static boolean hasUncoveredStars(char[][] grid) {
        for (char[] row : grid) {
            for (char cell : row) {
                if (cell == '*') {
                    return true;
                }
            }
        }
        return false;
    }
}

import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) {
        FastScanner scanner = new FastScanner(System.in);
        // try-with-resources ensures the writer is properly flushed and closed
        try (PrintWriter writer = new PrintWriter(new BufferedOutputStream(System.out))) {
            solve(scanner, writer);
        }
    }

    private static void solve(FastScanner scanner, PrintWriter writer) {
        int n = scanner.nextInt();
        int m = scanner.nextInt();

        char[][] originalGrid = new char[n][m];
        for (int i = 0; i < n; i++) {
            originalGrid[i] = scanner.next().toCharArray();
        }

        // Calculate the maximum cross length centered at each '*'
        int[][] maxCrossLength = computeMaxCrossLengths(originalGrid, n, m);

        // Initialize reconstruction buffer
        char[][] reconstructedGrid = new char[n][m];
        for (char[] row : reconstructedGrid) {
            Arrays.fill(row, '.');
        }

        List<String> resultLines = new ArrayList<>();
        int validStarsCount = 0;

        // Place crosses and collect results
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                // Only process '*' cells that can form a cross with at least one arm in each direction
                if (originalGrid[i][j] != '*' || maxCrossLength[i][j] < 1) {
                    continue;
                }

                validStarsCount++;
                resultLines.add((i + 1) + " " + (j + 1) + " " + maxCrossLength[i][j]);
                drawCross(reconstructedGrid, i, j, maxCrossLength[i][j]);
            }
        }

        // Verify if the reconstruction matches the original grid
        if (gridsMatch(originalGrid, reconstructedGrid)) {
            writer.println(validStarsCount);
            for (String line : resultLines) {
                writer.println(line);
            }
        } else {
            writer.println(-1);
        }
    }

    /**
     * Computes the maximum cross length (radius) for each cell.
     * The value represents the minimum consecutive '*' count in all 4 cardinal directions.
     */
    private static int[][] computeMaxCrossLengths(char[][] grid, int n, int m) {
        int[][] maxCrossLength = new int[n][m];

        // Horizontal passes: Left-to-Right, then Right-to-Left
        for (int i = 0; i < n; i++) {
            int consecutive = -1;
            for (int j = 0; j < m; j++) {
                consecutive = (grid[i][j] == '*') ? consecutive + 1 : -1;
                maxCrossLength[i][j] = consecutive; // Initialize with L->R pass
            }
            consecutive = -1;
            for (int j = m - 1; j >= 0; j--) {
                consecutive = (grid[i][j] == '*') ? consecutive + 1 : -1;
                maxCrossLength[i][j] = Math.min(maxCrossLength[i][j], consecutive); // Min with R->L pass
            }
        }

        // Vertical passes: Top-to-Bottom, then Bottom-to-Top
        for (int j = 0; j < m; j++) {
            int consecutive = -1;
            for (int i = 0; i < n; i++) {
                consecutive = (grid[i][j] == '*') ? consecutive + 1 : -1;
                maxCrossLength[i][j] = Math.min(maxCrossLength[i][j], consecutive); // Min with T->B pass
            }
            consecutive = -1;
            for (int i = n - 1; i >= 0; i--) {
                consecutive = (grid[i][j] == '*') ? consecutive + 1 : -1;
                maxCrossLength[i][j] = Math.min(maxCrossLength[i][j], consecutive); // Min with B->T pass
            }
        }

        return maxCrossLength;
    }

    /**
     * Marks a cross shape in the target grid centered at (centerRow, centerCol)
     * with the given radius. Bounds are guaranteed by the maxCrossLength calculation.
     */
    private static void drawCross(char[][] grid, int centerRow, int centerCol, int radius) {
        for (int k = 1; k <= radius; k++) {
            grid[centerRow - k][centerCol] = '*';
            grid[centerRow + k][centerCol] = '*';
            grid[centerRow][centerCol - k] = '*';
            grid[centerRow][centerCol + k] = '*';
        }
    }

    /**
     * Checks if two character grids are identical.
     */
    private static boolean gridsMatch(char[][] grid1, char[][] grid2) {
        for (int i = 0; i < grid1.length; i++) {
            for (int j = 0; j < grid1[i].length; j++) {
                if (grid1[i][j] != grid2[i][j]) {
                    return false;
                }
            }
        }
        return true;
    }
}

class FastScanner {
    private BufferedReader reader = null;
    private StringTokenizer tokenizer = null;

    public FastScanner(InputStream in) {
        reader = new BufferedReader(new InputStreamReader(in));
        tokenizer = null;
    }

    public String next() {
        if (tokenizer == null || !tokenizer.hasMoreTokens()) {
            try {
                tokenizer = new StringTokenizer(reader.readLine());
            } catch (IOException e) {
                throw new RuntimeException(e);
            }
        }
        return tokenizer.nextToken();
    }

    public String nextLine() {
        if (tokenizer == null || !tokenizer.hasMoreTokens()) {
            try {
                return reader.readLine();
            } catch (IOException e) {
                throw new RuntimeException(e);
            }
        }
        return tokenizer.nextToken("\n");
    }

    public long nextLong() {
        return Long.parseLong(next());
    }

    public int nextInt() {
        return Integer.parseInt(next());
    }

    public double nextDouble() {
        return Double.parseDouble(next());
    }

    public String[] nextArray(int n) {
        String[] a = new String[n];
        for (int i = 0; i < n; i++)
            a[i] = next();
        return a;
    }

    public int[] nextIntArray(int n) {
        int[] a = new int[n];
        for (int i = 0; i < n; i++)
            a[i] = nextInt();
        return a;
    }

    public long[] nextLongArray(int n) {
        long[] a = new long[n];
        for (int i = 0; i < n; i++)
            a[i] = nextLong();
        return a;
    } 
}

import java.io.BufferedOutputStream;
import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.StringTokenizer;

public class Main {
    public static void main(String[] args) {
        FastScanner in = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out));
        StarGridProcessor solver = new StarGridProcessor();
        solver.solve(in, out);
        out.flush();
        out.close();
    }

    /**
     * Processes the star grid to determine valid star positions based on
     * their distance to contiguous segment boundaries.
     */
    static class StarGridProcessor {
        public void solve(FastScanner in, PrintWriter out) {
            int n = in.nextInt();
            int m = in.nextInt();

            // 1-based indexing simplifies boundary checks and difference array logic
            char[][] grid = new char[n + 1][m + 1];
            // segmentBounds[i][j][0..3] stores left, right, top, bottom boundaries of contiguous '*' segments
            int[][][] segmentBounds = new int[n + 2][m + 2][4];

            // Initialize boundaries with -1
            for (int[][] row : segmentBounds) {
                for (int[] col : row) {
                    Arrays.fill(col, -1);
                }
            }

            // Read grid and initialize self-referencing boundaries
            for (int i = 1; i <= n; i++) {
                String row = in.next();
                for (int j = 1; j <= m; j++) {
                    grid[i][j] = row.charAt(j - 1);
                    if (grid[i][j] == '*') {
                        segmentBounds[i][j][0] = j; // Left
                        segmentBounds[i][j][2] = i; // Top
                    }
                }
            }

            // Compute full segment boundaries
            computeSegmentBounds(grid, segmentBounds, n, m);

            // Calculate coverage using difference arrays
            int[][][] diffArray = new int[n + 2][m + 2][2];
            ArrayList<StarInfo> validStars = new ArrayList<>();

            for (int i = 1; i <= n; i++) {
                for (int j = 1; j <= m; j++) {
                    if (grid[i][j] != '*') continue;

                    int left = segmentBounds[i][j][0];
                    int right = segmentBounds[i][j][1];
                    int top = segmentBounds[i][j][2];
                    int bottom = segmentBounds[i][j][3];

                    int distToHorizontal = Math.min(j - left, right - j);
                    int distToVertical = Math.min(i - top, bottom - i);
                    int minDist = Math.min(distToHorizontal, distToVertical);

                    if (minDist == 0) continue;

                    // Mark horizontal coverage range
                    diffArray[i][j - minDist][0]++;
                    diffArray[i][j + minDist + 1][0]--;

                    // Mark vertical coverage range
                    diffArray[i - minDist][j][1]++;
                    diffArray[i + minDist + 1][j][1]--;

                    validStars.add(new StarInfo(i, j, minDist));
                }
            }

            // Resolve difference arrays and verify all '*' are covered
            for (int i = 1; i <= n; i++) {
                for (int j = 1; j <= m; j++) {
                    diffArray[i][j][0] += diffArray[i][j - 1][0];
                    diffArray[i][j][1] += diffArray[i - 1][j][1];

                    if (grid[i][j] == '*' && (diffArray[i][j][0] + diffArray[i][j][1] == 0)) {
                        out.println(-1);
                        return;
                    }
                }
            }

            // Output results
            out.println(validStars.size());
            for (StarInfo star : validStars) {
                out.println(star);
            }
        }

        /**
         * Computes the left, right, top, and bottom boundaries for each '*' 
         * in contiguous horizontal and vertical segments.
         */
        private void computeSegmentBounds(char[][] grid, int[][][] bounds, int n, int m) {
            // Forward pass: propagate left and top boundaries
            for (int i = 1; i <= n; i++) {
                for (int j = 1; j <= m; j++) {
                    if (grid[i][j] == '*') {
                        if (bounds[i][j - 1][0] != -1) {
                            bounds[i][j][0] = bounds[i][j - 1][0];
                        }
                        if (bounds[i - 1][j][2] != -1) {
                            bounds[i][j][2] = bounds[i - 1][j][2];
                        }
                    }
                }
            }

            // Backward pass: propagate right and bottom boundaries
            for (int i = n; i >= 1; i--) {
                for (int j = m; j >= 1; j--) {
                    if (grid[i][j] == '*') {
                        if (bounds[i][j + 1][1] != -1) {
                            bounds[i][j][1] = bounds[i][j + 1][1];
                        }
                        if (bounds[i + 1][j][3] != -1) {
                            bounds[i][j][3] = bounds[i + 1][j][3];
                        }
                    }
                }
            }
        }
    }

    /**
     * Represents a valid star with its coordinates and minimum distance to segment boundaries.
     */
    static class StarInfo {
        final int x;
        final int y;
        final int distance;

        StarInfo(int x, int y, int distance) {
            this.x = x;
            this.y = y;
            this.distance = distance;
        }

        @Override
        public String toString() {
            return x + " " + y + " " + distance;
        }
    }

    /**
     * Fast input reader optimized for competitive programming environments.
     */
    static class FastScanner {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        FastScanner(InputStream inputStream) {
            reader = new BufferedReader(new InputStreamReader(inputStream));
        }

        String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input", e);
                }
            }
            return tokenizer.nextToken();
        }

        int nextInt() {
            String token = next();
            if (token == null) throw new RuntimeException("Unexpected end of input");
            return Integer.parseInt(token);
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayList;
import java.util.StringTokenizer;

public class StarsDrawingEasy {

    public static void main(String[] args) {
        new StarsDrawingEasy().solve();
    }

    public void solve() {
        FastIO io = new FastIO();
        int n = io.nextInt();
        int m = io.nextInt();

        char[][] grid = new char[n][m];
        for (int i = 0; i < n; i++) {
            grid[i] = io.next().toCharArray();
        }

        ArrayList<int[]> crosses = new ArrayList<>();
        boolean[][] covered = new boolean[n][m];
        boolean foundCross = true;

        // Greedily find and mark crosses until no more can be found
        while (foundCross) {
            foundCross = false;
            for (int i = 1; i < n - 1; i++) {
                for (int j = 1; j < m - 1; j++) {
                    // Check if current cell can be a center of a cross
                    if (grid[i][j] == '*' && !covered[i][j] &&
                        grid[i - 1][j] == '*' && grid[i + 1][j] == '*' &&
                        grid[i][j - 1] == '*' && grid[i][j + 1] == '*') {

                        int up = 0, down = 0, left = 0, right = 0;

                        // Calculate arm lengths in each direction
                        for (int k = i - 1; k >= 0 && grid[k][j] == '*'; k--, up++);
                        for (int k = i + 1; k < n && grid[k][j] == '*'; k++, down++);
                        for (int k = j - 1; k >= 0 && grid[i][k] == '*'; k--, left++);
                        for (int k = j + 1; k < m && grid[i][k] == '*'; k++, right++);

                        int radius = Math.min(Math.min(up, down), Math.min(left, right));

                        if (radius > 0) {
                            // Record the cross (1-based coordinates)
                            crosses.add(new int[]{i + 1, j + 1, radius});
                            foundCross = true;

                            // Mark all cells belonging to this cross as covered
                            for (int k = i - radius; k <= i + radius; k++) {
                                covered[k][j] = true;
                            }
                            for (int k = j - radius; k <= j + radius; k++) {
                                covered[i][k] = true;
                            }
                        }
                    }
                }
            }
        }

        // Verify that all '*' cells have been covered
        boolean allCovered = true;
        outer:
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == '*' && !covered[i][j]) {
                    allCovered = false;
                    break outer;
                }
            }
        }

        if (allCovered) {
            System.out.println(crosses.size());
            for (int[] cross : crosses) {
                System.out.println(cross[0] + " " + cross[1] + " " + cross[2]);
            }
        } else {
            System.out.println(-1);
        }
    }

    /**
     * Fast I/O helper class optimized for competitive programming.
     */
    static class FastIO {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastIO() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) {
                        throw new IOException("End of input");
                    }
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.ArrayList;
import java.util.List;
import java.util.StringTokenizer;

public class StarGridSolver {

    public static void main(String[] args) throws IOException {
        FastScanner scanner = new FastScanner();
        PrintWriter writer = new PrintWriter(System.out);
        try {
            new GridAnalyzer().analyze(scanner, writer);
        } finally {
            writer.flush();
        }
    }

    /**
     * Analyzes the grid to find valid plus signs and verifies if all stars are covered.
     */
    static class GridAnalyzer {
        void analyze(FastScanner scanner, PrintWriter writer) throws IOException {
            int rows = scanner.nextInt();
            int cols = scanner.nextInt();

            boolean[][] grid = new boolean[rows][cols];
            for (int i = 0; i < rows; i++) {
                String line = scanner.next();
                for (int j = 0; j < cols; j++) {
                    grid[i][j] = line.charAt(j) == '*';
                }
            }

            List<PlusSign> validPlusSigns = new ArrayList<>();
            boolean[][] covered = new boolean[rows][cols];

            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j]) {
                        int maxRadius = calculateMaxRadius(grid, i, j);
                        if (maxRadius > 0) {
                            markCovered(covered, i, j, maxRadius);
                            validPlusSigns.add(new PlusSign(i, j, maxRadius));
                        }
                    }
                }
            }

            if (isAllStarsCovered(grid, covered)) {
                writer.println(validPlusSigns.size());
                for (PlusSign sign : validPlusSigns) {
                    writer.println((sign.row + 1) + " " + (sign.col + 1) + " " + sign.radius);
                }
            } else {
                writer.println(-1);
            }
        }

        private int calculateMaxRadius(boolean[][] grid, int r, int c) {
            int maxPossible = Math.min(Math.min(grid.length - r - 1, grid[0].length - c - 1), Math.min(r, c));
            int radius = 0;
            while (radius < maxPossible) {
                if (grid[r][c + radius + 1] && grid[r][c - radius - 1] &&
                    grid[r + radius + 1][c] && grid[r - radius - 1][c]) {
                    radius++;
                } else {
                    break;
                }
            }
            return radius;
        }

        private void markCovered(boolean[][] covered, int r, int c, int radius) {
            covered[r][c] = true;
            for (int k = 1; k <= radius; k++) {
                covered[r][c + k] = true;
                covered[r][c - k] = true;
                covered[r + k][c] = true;
                covered[r - k][c] = true;
            }
        }

        private boolean isAllStarsCovered(boolean[][] grid, boolean[][] covered) {
            for (int i = 0; i < grid.length; i++) {
                for (int j = 0; j < grid[0].length; j++) {
                    if (grid[i][j] && !covered[i][j]) {
                        return false;
                    }
                }
            }
            return true;
        }
    }

    /**
     * Immutable data class representing a valid plus sign found in the grid.
     */
    static class PlusSign {
        final int row;
        final int col;
        final int radius;

        PlusSign(int row, int col, int radius) {
            this.row = row;
            this.col = col;
            this.radius = radius;
        }
    }

    /**
     * Lightweight fast I/O scanner optimized for competitive programming and bulk reads.
     */
    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner() {
            this(System.in);
        }

        public FastScanner(InputStream in) {
            this.br = new BufferedReader(new InputStreamReader(in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) {
                        throw new IOException("Unexpected end of input");
                    }
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input", e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            String token = next();
            if (token == null) {
                throw new RuntimeException("End of input");
            }
            return Integer.parseInt(token);
        }
    }
}

import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

/**
 * Solves a grid coverage problem where inner '*' cells are marked by cross-shaped
 * extensions reaching the nearest non-'*' cell or grid boundary.
 */
public class StarCoverageSolver {

    // Direction vectors: Down, Left, Up, Right
    private static final int[] DR = {1, 0, -1, 0};
    private static final int[] DC = {0, -1, 0, 1};

    /**
     * Represents a valid coverage result with 1-based coordinates and distance.
     */
    private static class CoverageResult {
        final int row;
        final int col;
        final int distance;

        CoverageResult(int row, int col, int distance) {
            this.row = row;
            this.col = col;
            this.distance = distance;
        }
    }

    /**
     * Checks if coordinates are within grid bounds.
     */
    private static boolean isValid(int r, int c, int rows, int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /**
     * Counts consecutive '*' characters in a specific direction starting from a given cell.
     */
    private static int countConsecutiveStars(String[] grid, int startRow, int startCol, 
                                             int dirIndex, int rows, int cols) {
        int count = 0;
        int r = startRow + DR[dirIndex];
        int c = startCol + DC[dirIndex];

        while (isValid(r, c, rows, cols) && grid[r].charAt(c) == '*') {
            count++;
            r += DR[dirIndex];
            c += DC[dirIndex];
        }
        return count;
    }

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            if (!scanner.hasNextInt()) {
                return;
            }
            int n = scanner.nextInt();
            int m = scanner.nextInt();
            String[] grid = new String[n];
            for (int i = 0; i < n; i++) {
                grid[i] = scanner.next();
            }

            boolean[][] covered = new boolean[n][m];
            List<CoverageResult> results = new ArrayList<>();

            // Iterate over inner cells (excluding borders)
            for (int i = 1; i < n - 1; i++) {
                for (int j = 1; j < m - 1; j++) {
                    if (grid[i].charAt(j) == '*') {
                        int minDistance = Integer.MAX_VALUE;

                        // Find minimum distance to non-'*' or boundary in all 4 directions
                        for (int dir = 0; dir < 4; dir++) {
                            int dist = countConsecutiveStars(grid, i, j, dir, n, m);
                            if (dist < minDistance) {
                                minDistance = dist;
                            }
                        }

                        // Only process if at least one direction contains stars
                        if (minDistance > 0) {
                            covered[i][j] = true;
                            // Mark cross shape up to minDistance
                            for (int k = 1; k <= minDistance; k++) {
                                covered[i + k][j] = true;
                                covered[i][j + k] = true;
                                covered[i - k][j] = true;
                                covered[i][j - k] = true;
                            }
                            results.add(new CoverageResult(i + 1, j + 1, minDistance));
                        }
                    }
                }
            }

            // Verify that all '*' cells are covered
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    if (grid[i].charAt(j) == '*' && !covered[i][j]) {
                        System.out.println(-1);
                        return;
                    }
                }
            }

            // Output results
            System.out.println(results.size());
            for (CoverageResult res : results) {
                System.out.println(res.row + " " + res.col + " " + res.distance);
            }
        }
    }
}

import java.io.*;
import java.util.*;

public class P1015E2 {
    // Direction vectors: up, right, down, left
    private static final int[][] DIRECTIONS = {{-1, 0}, {0, 1}, {1, 0}, {0, -1}};

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out));
        try {
            new Solver().solve(scanner, out);
        } finally {
            out.flush();
            out.close();
        }
    }

    /**
     * Encapsulates the problem-solving logic to eliminate static state,
     * improve testability, and separate concerns.
     */
    private static class Solver {
        private int n, m;
        private char[][] grid;
        private boolean[][] covered;
        private int[][] up, down, left, right;
        private List<Star> stars = new ArrayList<>();

        void solve(FastScanner in, PrintWriter out) {
            readInput(in);
            computeDistances();
            findAndPlaceStars();
            verifyAndOutput(out);
        }

        private void readInput(FastScanner in) {
            n = in.nextInt();
            m = in.nextInt();
            grid = new char[n][m];
            // Using next() instead of nextLine() avoids newline consumption issues
            // and safely handles whitespace/newlines between tokens.
            for (int i = 0; i < n; i++) {
                grid[i] = in.next().toCharArray();
            }
        }

        private void computeDistances() {
            up = new int[n][m];
            down = new int[n][m];
            left = new int[n][m];
            right = new int[n][m];

            // Compute horizontal distances (left-to-right, then right-to-left)
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    if (grid[i][j] == '*') {
                        left[i][j] = (j == 0) ? 1 : left[i][j - 1] + 1;
                    }
                }
                for (int j = m - 1; j >= 0; j--) {
                    if (grid[i][j] == '*') {
                        right[i][j] = (j == m - 1) ? 1 : right[i][j + 1] + 1;
                    }
                }
            }

            // Compute vertical distances (top-to-bottom, then bottom-to-top)
            for (int j = 0; j < m; j++) {
                for (int i = 0; i < n; i++) {
                    if (grid[i][j] == '*') {
                        up[i][j] = (i == 0) ? 1 : up[i - 1][j] + 1;
                    }
                }
                for (int i = n - 1; i >= 0; i--) {
                    if (grid[i][j] == '*') {
                        down[i][j] = (i == n - 1) ? 1 : down[i + 1][j] + 1;
                    }
                }
            }
        }

        private void findAndPlaceStars() {
            covered = new boolean[n][m];
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    if (grid[i][j] != '*') continue;

                    int ray = rayLength(i, j);
                    if (ray < 1) continue;

                    fillStar(i, j, ray);
                    stars.add(new Star(i, j, ray));
                }
            }
        }

        private int rayLength(int i, int j) {
            return Math.min(up[i][j], Math.min(down[i][j], Math.min(left[i][j], right[i][j]))) - 1;
        }

        private void fillStar(int i, int j, int ray) {
            covered[i][j] = true;
            for (int[] dir : DIRECTIONS) {
                int di = dir[0];
                int dj = dir[1];
                for (int k = 1; k <= ray; k++) {
                    covered[i + di * k][j + dj * k] = true;
                }
            }
        }

        private void verifyAndOutput(PrintWriter out) {
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    if (grid[i][j] == '*' && !covered[i][j]) {
                        out.println(-1);
                        return;
                    }
                }
            }
            out.println(stars.size());
            for (Star s : stars) {
                out.println(s);
            }
        }
    }

    /**
     * Immutable data class representing a placed star.
     */
    private static final class Star {
        final int row, col, ray;

        Star(int row, int col, int ray) {
            this.row = row;
            this.col = col;
            this.ray = ray;
        }

        @Override
        public String toString() {
            // Output requires 1-based indexing
            return (row + 1) + " " + (col + 1) + " " + ray;
        }
    }

    /**
     * Fast input reader using standard Java I/O.
     * Replaces the custom byte-buffer scanner with BufferedReader/StringTokenizer
     * for significantly better maintainability and readability without sacrificing performance.
     */
    private static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) throw new EOFException();
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input", e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.*;
import java.util.*;

public class Main {
    private static final char STAR = '*';

    public static void main(String[] args) {
        // Use try-with-resources for automatic and safe resource management
        try (FastScanner sc = new FastScanner(System.in);
             PrintWriter pw = new PrintWriter(System.out)) {

            int height = sc.nextInt();
            int width = sc.nextInt();
            char[][] grid = new char[height][];
            for (int i = 0; i < height; i++) {
                grid[i] = sc.next().toCharArray();
            }

            List<Cord> result = solve(grid, height, width);
            if (result == null) {
                pw.println(-1);
            } else {
                pw.println(result.size());
                for (Cord c : result) {
                    pw.println((c.h + 1) + " " + (c.w + 1) + " " + c.size);
                }
            }
            pw.flush();
        } catch (IOException e) {
            throw new RuntimeException("I/O error occurred while processing input", e);
        }
    }

    /**
     * Solves the grid problem by identifying valid square centers and verifying coverage.
     * Returns null if any '*' cell remains uncovered by the generated squares.
     */
    private static List<Cord> solve(char[][] grid, int height, int width) {
        int[][] up = new int[height][width];
        int[][] down = new int[height][width];
        int[][] left = new int[height][width];
        int[][] right = new int[height][width];

        // Compute consecutive '*' counts in each direction
        computeDirectionCounts(grid, height, width, up, true, true);
        computeDirectionCounts(grid, height, width, down, true, false);
        computeDirectionCounts(grid, height, width, left, false, true);
        computeDirectionCounts(grid, height, width, right, false, false);

        // Difference arrays for efficient range coverage tracking
        int[][] rowmask = new int[height][width + 1];
        int[][] colmask = new int[height + 1][width];
        List<Cord> squares = new ArrayList<>();

        for (int h = 0; h < height; h++) {
            for (int w = 0; w < width; w++) {
                if (grid[h][w] != STAR) continue;

                int size = Math.min(Math.min(left[h][w], right[h][w]),
                                    Math.min(up[h][w], down[h][w]));
                if (size >= 1) {
                    squares.add(new Cord(h, w, size));
                    // Apply difference array updates for the square centered at (h, w)
                    rowmask[h][w - size]++;
                    rowmask[h][w + size + 1]--;
                    colmask[h - size][w]++;
                    colmask[h + size + 1][w]--;
                }
            }
        }

        // Compute prefix sums to resolve actual coverage counts
        for (int h = 0; h < height; h++) {
            for (int w = 1; w <= width; w++) {
                rowmask[h][w] += rowmask[h][w - 1];
            }
        }
        for (int w = 0; w < width; w++) {
            for (int h = 1; h <= height; h++) {
                colmask[h][w] += colmask[h - 1][w];
            }
        }

        // Verify that every '*' cell is covered by at least one square
        for (int h = 0; h < height; h++) {
            for (int w = 0; w < width; w++) {
                if (grid[h][w] == STAR && rowmask[h][w] == 0 && colmask[h][w] == 0) {
                    return null; // Coverage condition failed
                }
            }
        }

        return squares;
    }

    /**
     * Computes consecutive '*' counts in a specific direction for each cell.
     *
     * @param grid    The input character grid
     * @param height  Number of rows
     * @param width   Number of columns
     * @param counts  Output array to store counts
     * @param vertical If true, iterate vertically; otherwise horizontally
     * @param forward If true, iterate forward; otherwise backward
     */
    private static void computeDirectionCounts(char[][] grid, int height, int width,
                                               int[][] counts, boolean vertical, boolean forward) {
        if (vertical) {
            for (int w = 0; w < width; w++) {
                int count = 0;
                int start = forward ? 0 : height - 1;
                int end = forward ? height : -1;
                int step = forward ? 1 : -1;
                for (int h = start; h != end; h += step) {
                    counts[h][w] = count;
                    count = grid[h][w] == STAR ? count + 1 : 0;
                }
            }
        } else {
            for (int h = 0; h < height; h++) {
                int count = 0;
                int start = forward ? 0 : width - 1;
                int end = forward ? width : -1;
                int step = forward ? 1 : -1;
                for (int w = start; w != end; w += step) {
                    counts[h][w] = count;
                    count = grid[h][w] == STAR ? count + 1 : 0;
                }
            }
        }
    }

    /**
     * Represents a square center in the grid along with its radius/size.
     */
    static class Cord {
        final int h;
        final int w;
        final int size;

        Cord(int h, int w, int size) {
            this.h = h;
            this.w = w;
            this.size = size;
        }
    }

    /**
     * FastScanner for efficient competitive programming-style input reading.
     */
    static class FastScanner {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        FastScanner(InputStream in) {
            reader = new BufferedReader(new InputStreamReader(in));
            tokenizer = null;
        }

        String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input", e);
                }
            }
            return tokenizer.nextToken();
        }

        int nextInt() {
            String token = next();
            if (token == null) throw new NoSuchElementException("Unexpected end of input");
            return Integer.parseInt(token);
        }
    }
}

import java.util.Scanner;

public class PasswordModifier {

    // Constants for replacement characters to improve readability and maintainability
    private static final char REPLACEMENT_DIGIT = '0';
    private static final char REPLACEMENT_UPPER = 'A';
    private static final char REPLACEMENT_LOWER = 'a';

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        // Check if input exists to prevent NoSuchElementException
        if (scanner.hasNextInt()) {
            int testCases = scanner.nextInt();

            for (int i = 0; i < testCases; i++) {
                String password = scanner.next();
                String modifiedPassword = modifyPassword(password);
                System.out.println(modifiedPassword);
            }
        }

        scanner.close();
    }

    /**
     * Modifies the password string to satisfy strength requirements.
     * The logic ensures the presence of at least one digit, one uppercase,
     * and one lowercase letter by replacing existing characters if necessary.
     */
    private static String modifyPassword(String password) {
        char[] chars = password.toCharArray();
        int digitCount = 0;
        int upperCount = 0;
        int lowerCount = 0;

        // 1. Count the occurrences of each character type
        for (char c : chars) {
            if (Character.isDigit(c)) {
                digitCount++;
            } else if (Character.isUpperCase(c)) {
                upperCount++;
            } else if (Character.isLowerCase(c)) {
                lowerCount++;
            }
        }

        // 2. Apply modification rules based on missing types
        // The logic is structured to prioritize specific replacements based on
        // the counts of available character types to preserve existing diversity.

        // Case: Missing Digit (digitCount == 0)
        if (digitCount == 0) {
            if (upperCount > 1 && lowerCount > 1) {
                // If we have surplus of both other types, replace the first character
                chars[0] = REPLACEMENT_DIGIT;
            } else if (upperCount > 1) {
                // If we have surplus Uppercase, replace the first Uppercase with a Digit
                int index = findFirstIndex(chars, 'u');
                if (index != -1) chars[index] = REPLACEMENT_DIGIT;
            } else if (lowerCount > 1) {
                // If we have surplus Lowercase, replace the first Lowercase with a Digit
                int index = findFirstIndex(chars, 'l');
                if (index != -1) chars[index] = REPLACEMENT_DIGIT;
            }
        }
        // Case: Missing Lowercase (lowerCount == 0)
        else if (lowerCount == 0) {
            if (upperCount > 1 && digitCount > 1) {
                chars[0] = REPLACEMENT_LOWER;
            } else if (upperCount > 1) {
                int index = findFirstIndex(chars, 'u');
                if (index != -1) chars[index] = REPLACEMENT_LOWER;
            } else if (digitCount > 1) {
                int index = findFirstIndex(chars, 'd');
                if (index != -1) chars[index] = REPLACEMENT_LOWER;
            }
        }
        // Case: Missing Uppercase (upperCount == 0)
        else if (upperCount == 0) {
            if (lowerCount > 1 && digitCount > 1) {
                chars[0] = REPLACEMENT_UPPER;
            } else if (digitCount > 1) {
                int index = findFirstIndex(chars, 'd');
                if (index != -1) chars[index] = REPLACEMENT_UPPER;
            } else if (lowerCount > 1) {
                int index = findFirstIndex(chars, 'l');
                if (index != -1) chars[index] = REPLACEMENT_UPPER;
            }
        }
        // Case: Missing Digit and Lowercase (Needs both)
        // Original Logic: digi==0 && smalls==0 && caps>1 -> ch[0]='a', ch[1]='0'
        else if (digitCount == 0 && lowerCount == 0) {
            if (upperCount > 1) {
                chars[0] = REPLACEMENT_LOWER;
                chars[1] = REPLACEMENT_DIGIT;
            }
        }
        // Case: Missing Digit and Uppercase (Needs both)
        // Original Logic: digi==0 && caps==0 && smalls>1 -> ch[0]='A', ch[1]='0'
        else if (digitCount == 0 && upperCount == 0) {
            if (lowerCount > 1) {
                chars[0] = REPLACEMENT_UPPER;
                chars[1] = REPLACEMENT_DIGIT;
            }
        }
        // Case: Missing Lowercase and Uppercase (Needs both)
        // Original Logic: digi>1 && smalls==0 && caps==0 -> ch[0]='a', ch[1]='A'
        else if (lowerCount == 0 && upperCount == 0) {
            if (digitCount > 1) {
                chars[0] = REPLACEMENT_LOWER;
                chars[1] = REPLACEMENT_UPPER;
            }
        }

        return new String(chars);
    }

    /**
     * Helper method to find the index of the first character matching a specific type.
     * 
     * @param chars The character array to search.
     * @param type  'd' for digit, 'u' for uppercase, 'l' for lowercase.
     * @return The index of the first match, or -1 if not found.
     */
    private static int findFirstIndex(char[] chars, char type) {
        for (int i = 0; i < chars.length; i++) {
            char c = chars[i];
            if (type == 'd' && Character.isDigit(c)) return i;
            if (type == 'u' && Character.isUpperCase(c)) return i;
            if (type == 'l' && Character.isLowerCase(c)) return i;
        }
        return -1;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

public class Main {
    public static void main(String[] args) {
        FastReader reader = new FastReader();
        PrintWriter writer = new PrintWriter(System.out);

        try {
            // Read number of test cases
            String tStr = reader.next();
            if (tStr != null) {
                int T = Integer.parseInt(tStr);
                for (int i = 0; i < T; i++) {
                    String s = reader.next();
                    if (s != null) {
                        processString(s, writer);
                    }
                }
            }
        } catch (Exception e) {
            // In a production environment, proper error handling/logging would be here.
            // For competitive programming context, we often assume valid input format.
        } finally {
            writer.flush();
            writer.close();
        }
    }

    /**
     * Processes the string according to the problem logic and prints the result.
     * Logic:
     * 1. If string contains Lowercase, Uppercase, and Other (Digit/Char), print as is.
     * 2. If missing 2 types (e.g., only Lowercase), prepend specific characters and truncate first 2.
     * 3. If missing 1 type, replace the last occurrence of a redundant character type (count > 1)
     *    with the required missing character type.
     */
    private static void processString(String s, PrintWriter writer) {
        int lowerCount = 0;
        int upperCount = 0;
        int otherCount = 0;

        int lastLowerIndex = -1;
        int lastUpperIndex = -1;
        int lastOtherIndex = -1;

        // Analyze string to count types and find last indices
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            // Using ASCII range checks to match original logic precisely
            if (c >= 'a' && c <= 'z') {
                lowerCount++;
                lastLowerIndex = i;
            } else if (c >= 'A' && c <= 'Z') {
                upperCount++;
                lastUpperIndex = i;
            } else {
                otherCount++;
                lastOtherIndex = i;
            }
        }

        // Case 1: String is already valid (has Lower, Upper, Other)
        if (lowerCount > 0 && upperCount > 0 && otherCount > 0) {
            writer.println(s);
            return;
        }

        // Case 2: Missing Uppercase and Other (Only Lowercase present)
        // Requires adding 'A' and '1'. Original logic: "A1" + substring(2)
        if (lowerCount > 0 && upperCount == 0 && otherCount == 0) {
            writer.println("A1" + s.substring(2, s.length()));
            return;
        }

        // Case 3: Missing Lowercase and Other (Only Uppercase present)
        // Requires adding 'a' and '1'. Original logic: "a1" + substring(2)
        if (lowerCount == 0 && upperCount > 0 && otherCount == 0) {
            writer.println("a1" + s.substring(2, s.length()));
            return;
        }

        // Case 4: Missing Lowercase and Uppercase (Only Other present)
        // Requires adding 'a' and 'A'. Original logic: "aA" + substring(2)
        if (lowerCount == 0 && upperCount == 0 && otherCount > 0) {
            writer.println("aA" + s.substring(2, s.length()));
            return;
        }

        // Case 5: Missing Other (Has Lowercase and Uppercase)
        // Need to introduce a digit/other char ('1').
        // Priority: Replace last Lowercase if count > 1, else replace last Uppercase if count > 1.
        if (lowerCount > 0 && upperCount > 0 && otherCount == 0) {
            if (lowerCount > 1) {
                writer.println(replaceChar(s, lastLowerIndex, '1'));
            } else if (upperCount > 1) {
                writer.println(replaceChar(s, lastUpperIndex, '1'));
            }
            // If counts are 1, original code prints nothing.
            return;
        }

        // Case 6: Missing Uppercase (Has Lowercase and Other)
        // Need to introduce Uppercase ('A').
        // Priority: Replace last Lowercase if count > 1, else replace last Other if count > 1.
        if (lowerCount > 0 && upperCount == 0 && otherCount > 0) {
            if (lowerCount > 1) {
                writer.println(replaceChar(s, lastLowerIndex, 'A'));
            } else if (otherCount > 1) {
                writer.println(replaceChar(s, lastOtherIndex, 'A'));
            }
            return;
        }

        // Case 7: Missing Lowercase (Has Uppercase and Other)
        // Need to introduce Lowercase ('a').
        // Priority: Replace last Uppercase if count > 1, else replace last Other if count > 1.
        if (lowerCount == 0 && upperCount > 0 && otherCount > 0) {
            if (upperCount > 1) {
                writer.println(replaceChar(s, lastUpperIndex, 'a'));
            } else if (otherCount > 1) {
                writer.println(replaceChar(s, lastOtherIndex, 'a'));
            }
            return;
        }

        // Fallback (should not be reached with valid logic flow above, 
        // but handles empty string or unexpected states gracefully)
        // Original code would print nothing in some edge cases.
    }

    /**
     * Helper method to replace a character at a specific index.
     * Uses StringBuilder for cleaner and slightly more efficient string manipulation.
     */
    private static String replaceChar(String s, int index, char replacement) {
        StringBuilder sb = new StringBuilder(s);
        sb.setCharAt(index, replacement);
        return sb.toString();
    }

    /**
     * FastReader class for efficient input reading.
     */
    static class FastReader {
        BufferedReader br;
        StringTokenizer st;

        public FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) {
                        return null;
                    }
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    e.printStackTrace();
                    return null;
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            String s = next();
            if (s == null) return 0; // Handle end of input gracefully
            return Integer.parseInt(s);
        }
    }
}

import java.util.Scanner;

/**
 * Refactored solution for ensuring strings contain at least one lowercase,
 * one uppercase, and one digit character.
 */
public class Main {

    public static void main(String[] args) {
        // Use try-with-resources for automatic resource management
        try (Scanner scanner = new Scanner(System.in)) {
            if (scanner.hasNextInt()) {
                int testCases = scanner.nextInt();
                while (testCases-- > 0 && scanner.hasNext()) {
                    String input = scanner.next();
                    System.out.println(modifyString(input));
                }
            }
        }
    }

    /**
     * Modifies the input string to ensure it contains at least one lowercase,
     * one uppercase, and one digit character.
     *
     * @param s the input string to process
     * @return the modified string satisfying the character type constraints
     */
    private static String modifyString(String s) {
        int lowerCount = 0;
        int upperCount = 0;
        int digitCount = 0;

        // Count character types in a single pass
        for (char c : s.toCharArray()) {
            if (Character.isLowerCase(c)) lowerCount++;
            else if (Character.isUpperCase(c)) upperCount++;
            else if (Character.isDigit(c)) digitCount++;
        }

        boolean hasLower = lowerCount > 0;
        boolean hasUpper = upperCount > 0;
        boolean hasDigit = digitCount > 0;

        // If all types are present, return as is
        if (hasLower && hasUpper && hasDigit) {
            return s;
        }

        StringBuilder result = new StringBuilder();

        // Case 1: Missing exactly two types
        if (!hasLower && !hasUpper) {
            result.append("aA").append(s, 2, s.length());
        } else if (!hasLower && !hasDigit) {
            result.append("a1").append(s, 2, s.length());
        } else if (!hasUpper && !hasDigit) {
            result.append("A1").append(s, 2, s.length());
        }
        // Case 2: Missing exactly one type
        else {
            char missingChar;
            if (!hasLower) missingChar = 'a';
            else if (!hasUpper) missingChar = 'A';
            else missingChar = '1';

            // Find the first character that does not belong to the missing type
            // Since exactly one type is missing, the other two types must have at least one character each.
            char charToReplace = 0;
            for (char c : s.toCharArray()) {
                if (missingChar == 'a' && !Character.isLowerCase(c)) {
                    charToReplace = c;
                    break;
                } else if (missingChar == 'A' && !Character.isUpperCase(c)) {
                    charToReplace = c;
                    break;
                } else if (missingChar == '1' && !Character.isDigit(c)) {
                    charToReplace = c;
                    break;
                }
            }

            // Replace the first occurrence of the identified character
            boolean replaced = false;
            for (char c : s.toCharArray()) {
                if (!replaced && c == charToReplace) {
                    result.append(missingChar);
                    replaced = true;
                } else {
                    result.append(c);
                }
            }
        }

        return result.toString();
    }
}

