public class A {
    public static void main(String[] args) {
        // Use try-with-resources for automatic and safe resource management
        try (InputStream input = new FileInputStream("input.txt");
             OutputStream output = new FileOutputStream("output.txt")) {
            run(input, output);
        } catch (FileNotFoundException e) {
            // Fallback to standard I/O if files are not found
            run(System.in, System.out);
        }
    }

    private static void run(InputStream input, OutputStream output) {
        Kattio io = new Kattio(input, output);
        int testCases = io.getInt();
        for (int i = 0; i < testCases; i++) {
            new Solver(io).solve();
        }
        io.close();
    }
}

/**
 * Contains the core logic for processing each test case.
 * Attempts to make the string valid by modifying 0, 1, 2, or 3 characters.
 */
class Solver {
    private static final char[] SINGLE_REPLACEMENTS = {'0', 'a', 'A'};
    private static final char[][] DOUBLE_REPLACEMENTS = {
        {'0', 'a'}, {'0', 'A'}, {'A', 'a'}
    };
    private static final char[] TRIPLE_REPLACEMENTS = {'0', 'a', 'A'};

    private final Kattio io;
    private String inputString;

    Solver(Kattio io) {
        this.io = io;
    }

    void solve() {
        inputString = io.getWord();

        // Evaluate modification attempts in priority order (0 -> 1 -> 2 -> 3 changes)
        // Caching results avoids redundant string scans and method calls
        String result = check0();
        if (result.isEmpty()) result = check1();
        if (result.isEmpty()) result = check2();
        if (result.isEmpty()) result = check3();

        io.println(result);
    }

    private String check0() {
        return isValid(inputString.toCharArray()) ? inputString : "";
    }

    private String check1() {
        char[] chars = inputString.toCharArray();
        for (int i = 0; i < chars.length; i++) {
            char original = chars[i];
            for (char replacement : SINGLE_REPLACEMENTS) {
                chars[i] = replacement;
                if (isValid(chars)) {
                    return new String(chars);
                }
            }
            chars[i] = original; // Backtrack to original state
        }
        return "";
    }

    private String check2() {
        char[] chars = inputString.toCharArray();
        for (int i = 0; i < chars.length - 1; i++) {
            char orig1 = chars[i];
            char orig2 = chars[i + 1];
            for (char[] replacement : DOUBLE_REPLACEMENTS) {
                chars[i] = replacement[0];
                chars[i + 1] = replacement[1];
                if (isValid(chars)) {
                    return new String(chars);
                }
            }
            chars[i] = orig1;
            chars[i + 1] = orig2; // Backtrack
        }
        return "";
    }

    private String check3() {
        char[] chars = inputString.toCharArray();
        for (int i = 0; i < chars.length - 2; i++) {
            char orig1 = chars[i];
            char orig2 = chars[i + 1];
            char orig3 = chars[i + 2];

            chars[i] = TRIPLE_REPLACEMENTS[0];
            chars[i + 1] = TRIPLE_REPLACEMENTS[1];
            chars[i + 2] = TRIPLE_REPLACEMENTS[2];

            if (isValid(chars)) {
                return new String(chars);
            }

            chars[i] = orig1;
            chars[i + 1] = orig2;
            chars[i + 2] = orig3; // Backtrack
        }
        return "";
    }

    /**
     * Checks if the character array contains at least one digit, 
     * one lowercase letter, and one uppercase letter.
     * Includes early-exit optimization for performance.
     */
    private boolean isValid(char[] chars) {
        boolean hasDigit = false;
        boolean hasLowerCase = false;
        boolean hasUpperCase = false;

        for (char c : chars) {
            if (c >= '0' && c <= '9') hasDigit = true;
            else if (c >= 'a' && c <= 'z') hasLowerCase = true;
            else if (c >= 'A' && c <= 'Z') hasUpperCase = true;

            // Early exit: all conditions met
            if (hasDigit && hasLowerCase && hasUpperCase) {
                return true;
            }
        }
        return false;
    }
}

/**
 * Fast I/O utility class extending PrintWriter.
 * Optimized for competitive programming environments.
 */
class Kattio extends PrintWriter {
    private final BufferedReader reader;
    private StringTokenizer tokenizer;
    private String token;

    public Kattio(InputStream input) {
        this(input, System.out);
    }

    public Kattio(InputStream input, OutputStream output) {
        super(new BufferedOutputStream(output));
        this.reader = new BufferedReader(new InputStreamReader(input));
    }

    public boolean hasMoreTokens() {
        return peekToken() != null;
    }

    public int getInt() {
        return Integer.parseInt(nextToken());
    }

    public String getWord() {
        return nextToken();
    }

    /**
     * Peeks at the next token without consuming it.
     * Handles line reading and tokenization efficiently.
     */
    private String peekToken() {
        while (token == null || !tokenizer.hasMoreTokens()) {
            try {
                String line = reader.readLine();
                if (line == null) {
                    return null;
                }
                tokenizer = new StringTokenizer(line);
            } catch (IOException e) {
                throw new RuntimeException("Error reading input stream", e);
            }
        }
        token = tokenizer.nextToken();
        return token;
    }

    private String nextToken() {
        String ans = peekToken();
        token = null;
        return ans;
    }

    /**
     * Overrides close() to only flush output.
     * Prevents accidental closure of System.in/System.out when used in fallback mode.
     */
    @Override
    public void close() {
        flush();
    }
}

import java.util.Scanner;

public class ProblemA {
    public static void main(String[] args) {
        // Use try-with-resources to ensure the Scanner is properly closed
        try (Scanner scanner = new Scanner(System.in)) {
            if (!scanner.hasNextInt()) {
                return;
            }
            int testCases = scanner.nextInt();
            StringBuilder output = new StringBuilder();

            for (int i = 0; i < testCases; i++) {
                String input = scanner.next();
                output.append(transformPassword(input)).append('\n');
            }
            System.out.print(output);
        }
    }

    /**
     * Ensures the input string contains at least one lowercase letter, 
     * one uppercase letter, and one digit. If any type is missing, it 
     * replaces an existing character to satisfy the requirement while 
     * preserving the original length.
     *
     * @param password the original string to transform
     * @return the modified string meeting the character type requirements
     */
    private static String transformPassword(String password) {
        int lowerCount = 0;
        int upperCount = 0;
        int digitCount = 0;
        int lastLowerIndex = -1;
        int lastUpperIndex = -1;
        int lastDigitIndex = -1;

        // Analyze the password: count character types and track the last index of each
        for (int i = 0; i < password.length(); i++) {
            char c = password.charAt(i);
            if (Character.isLowerCase(c)) {
                lowerCount++;
                lastLowerIndex = i;
            } else if (Character.isUpperCase(c)) {
                upperCount++;
                lastUpperIndex = i;
            } else if (Character.isDigit(c)) {
                digitCount++;
                lastDigitIndex = i;
            }
        }

        boolean missingLower = lowerCount == 0;
        boolean missingUpper = upperCount == 0;
        boolean missingDigit = digitCount == 0;

        // Convert to char array for efficient in-place modification
        char[] chars = password.toCharArray();

        // Case 1: Two types are missing. Replace the first two characters.
        if (missingLower && missingUpper) {
            chars[0] = 'a';
            chars[1] = 'A';
        } else if (missingUpper && missingDigit) {
            chars[0] = 'A';
            chars[1] = '1';
        } else if (missingDigit && missingLower) {
            chars[0] = 'a';
            chars[1] = '1';
        }
        // Case 2: Exactly one type is missing. Replace a character of another type.
        else if (missingLower) {
            // Prefer replacing a digit; otherwise, replace an uppercase letter.
            if (digitCount > 0) {
                chars[lastDigitIndex] = 'a';
            } else {
                chars[lastUpperIndex] = 'a';
            }
        } else if (missingUpper) {
            // Prefer replacing a digit; otherwise, replace a lowercase letter.
            if (digitCount > 0) {
                chars[lastDigitIndex] = 'A';
            } else {
                chars[lastLowerIndex] = 'A';
            }
        } else if (missingDigit) {
            // Prefer replacing a lowercase letter; otherwise, replace an uppercase letter.
            if (lowerCount > 0) {
                chars[lastUpperIndex] = '1';
            } else {
                chars[lastLowerIndex] = '1';
            }
        }
        // Case 3: All types are present. Return the original string unchanged.

        return new String(chars);
    }
}

import java.util.Scanner;

public class PasswordValidator {

    // Constants for replacement patterns to avoid magic strings and improve maintainability
    private static final String[] REPLACEMENT_PATTERNS = {
        "a", "A", "1", "aA", "a1", "A1", "aA1"
    };

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        // Read the number of test cases
        if (scanner.hasNextInt()) {
            int numTestCases = scanner.nextInt();
            scanner.nextLine(); // Consume the newline character left by nextInt()

            for (int i = 0; i < numTestCases; i++) {
                String password = scanner.nextLine();
                String solution = findSolution(password);

                if (solution != null) {
                    System.out.println(solution);
                }
            }
        }

        scanner.close();
    }

    /**
     * Attempts to find a valid password by replacing a substring with a pattern,
     * or returns the original password if it is already valid.
     * 
     * @param password The input password to process
     * @return A valid password string, or null if no solution is found
     */
    private static String findSolution(String password) {
        // Check if the password is already valid
        if (isValidPassword(password)) {
            return password;
        }

        // Try to replace substrings with predefined patterns
        for (String pattern : REPLACEMENT_PATTERNS) {
            int patternLength = pattern.length();

            // Iterate through all possible starting positions for the replacement.
            // The loop condition ensures we do not go out of bounds of the password string.
            // We replace the substring starting at k with length equal to the pattern.
            for (int k = 0; k <= password.length() - patternLength; k++) {

                // Construct the new password by replacing the substring at index k
                // with the current pattern.
                // substring(0, k) gets the prefix.
                // substring(k + patternLength) gets the suffix after the replaced segment.
                String modifiedPassword = password.substring(0, k) 
                                        + pattern 
                                        + password.substring(k + patternLength);

                if (isValidPassword(modifiedPassword)) {
                    return modifiedPassword;
                }
            }
        }

        // If no valid password can be formed with the given patterns
        return null;
    }

    /**
     * Checks if a password meets the complexity requirements:
     * 1. Contains at least one lowercase letter
     * 2. Contains at least one uppercase letter
     * 3. Contains at least one digit
     * 
     * @param password The password to validate
     * @return true if valid, false otherwise
     */
    private static boolean isValidPassword(String password) {
        boolean hasLower = false;
        boolean hasUpper = false;
        boolean hasDigit = false;

        for (int i = 0; i < password.length(); i++) {
            char c = password.charAt(i);
            if (Character.isLowerCase(c)) {
                hasLower = true;
            } else if (Character.isUpperCase(c)) {
                hasUpper = true;
            } else if (Character.isDigit(c)) {
                hasDigit = true;
            }
        }

        return hasLower && hasUpper && hasDigit;
    }
}

import java.io.*;
import java.util.*;

/**
 * Validates and modifies strings to ensure they contain uppercase, lowercase,
 * and digit characters. Replaces existing characters with representatives
 * of missing types based on a defined priority.
 */
public class StringTypeValidator {
    // Bitmask constants for character types
    private static final int HAS_UPPER = 1;
    private static final int HAS_LOWER = 2;
    private static final int HAS_DIGIT = 4;
    private static final int ALL_TYPES_PRESENT = HAS_UPPER | HAS_LOWER | HAS_DIGIT;

    private final BufferedReader br;
    private final PrintWriter out;
    private StringTokenizer st;

    public StringTypeValidator() throws IOException {
        br = new BufferedReader(new InputStreamReader(System.in));
        out = new PrintWriter(new BufferedOutputStream(System.out));
        try {
            solve();
        } finally {
            out.flush();
        }
    }

    private void solve() throws IOException {
        String tStr = nextToken();
        if (tStr == null) return;

        int T;
        try {
            T = Integer.parseInt(tStr);
        } catch (NumberFormatException e) {
            return;
        }

        // Consume the remainder of the first line to align with br.readLine()
        br.readLine();

        for (int t = 0; t < T; t++) {
            String str = br.readLine();
            processString(str);
        }
    }

    private void processString(String str) {
        if (str == null || str.isEmpty()) {
            out.println(str);
            return;
        }

        boolean hasUpper = false;
        boolean hasLower = false;
        boolean hasDigit = false;

        // Analyze character types in a single pass
        for (int i = 0; i < str.length(); i++) {
            char c = str.charAt(i);
            if (Character.isUpperCase(c)) {
                hasUpper = true;
            } else if (Character.isLowerCase(c)) {
                hasLower = true;
            } else if (Character.isDigit(c)) {
                hasDigit = true;
            }
        }

        // If all types are present, output as-is
        if (hasUpper && hasLower && hasDigit) {
            out.println(str);
            return;
        }

        char[] chars = str.toCharArray();
        int missingMask = 0;
        if (!hasUpper) missingMask |= HAS_UPPER;
        if (!hasLower) missingMask |= HAS_LOWER;
        if (!hasDigit) missingMask |= HAS_DIGIT;

        if (missingMask == ALL_TYPES_PRESENT) {
            // Missing all three types: replace the first two characters
            chars[0] = getCharForType(HAS_UPPER);
            chars[1] = getCharForType(HAS_LOWER);
        } else {
            // Missing exactly one type: replace the first available character
            // based on priority: Uppercase > Lowercase > Digit
            int missingType = missingMask;
            int replaceIndex = findReplacementIndex(chars);
            chars[replaceIndex] = getCharForType(missingType);
        }

        out.println(new String(chars));
    }

    /**
     * Finds the index of the first character to replace.
     * Priority order: Uppercase > Lowercase > Digit.
     * Falls back to index 0 if no matching type is found.
     */
    private int findReplacementIndex(char[] chars) {
        for (int i = 0; i < chars.length; i++) {
            if (Character.isUpperCase(chars[i])) return i;
        }
        for (int i = 0; i < chars.length; i++) {
            if (Character.isLowerCase(chars[i])) return i;
        }
        for (int i = 0; i < chars.length; i++) {
            if (Character.isDigit(chars[i])) return i;
        }
        return 0; // Fallback for strings containing only symbols/whitespace
    }

    /**
     * Returns a representative character for the given type bitmask.
     * Maps directly to the original 'arr' lookup behavior.
     */
    private char getCharForType(int type) {
        if (type == HAS_UPPER) return 'A';
        if (type == HAS_LOWER) return 'a';
        if (type == HAS_DIGIT) return '0';
        return '!';
    }

    // --- Input Handling ---
    private String nextToken() {
        while (st == null || !st.hasMoreTokens()) {
            try {
                String line = br.readLine();
                if (line == null) return null;
                st = new StringTokenizer(line);
            } catch (IOException e) {
                return null;
            }
        }
        return st.nextToken();
    }

    public static void main(String[] args) throws IOException {
        new StringTypeValidator();
    }
}

import java.io.InputStream;
import java.io.IOException;
import java.io.OutputStream;
import java.io.PrintWriter;
import java.util.InputMismatchException;

public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        TaskA solver = new TaskA();
        solver.solve(1, in, out);
        out.close();
    }

    static class TaskA {
        public void solve(int testNumber, InputReader in, PrintWriter out) {
            int t = in.nextInt();
            while (t-- > 0) {
                String str = in.next();
                int countUpper = 0;
                int countLower = 0;
                int countDigit = 0;

                // Single pass to count character types using standard library methods
                for (int i = 0; i < str.length(); i++) {
                    char c = str.charAt(i);
                    if (Character.isUpperCase(c)) countUpper++;
                    else if (Character.isLowerCase(c)) countLower++;
                    else if (Character.isDigit(c)) countDigit++;
                }

                boolean hasUpper = countUpper > 0;
                boolean hasLower = countLower > 0;
                boolean hasDigit = countDigit > 0;

                // If all required types are present, output as-is
                if (hasUpper && hasLower && hasDigit) {
                    out.println(str);
                    continue;
                }

                char[] chars = str.toCharArray();
                boolean missingUpper = !hasUpper;
                boolean missingLower = !hasLower;
                boolean missingDigit = !hasDigit;

                // Handle cases with two missing character types
                if (missingUpper && missingLower) {
                    chars[0] = 'a';
                    chars[1] = 'A';
                } else if (missingUpper && missingDigit) {
                    chars[0] = 'A';
                    chars[1] = '3';
                } else if (missingLower && missingDigit) {
                    chars[0] = 'a';
                    chars[1] = '3';
                }
                // Handle cases with exactly one missing character type
                else if (missingDigit) {
                    if (countLower < countUpper) {
                        for (int i = 0; i < chars.length; i++) {
                            if (Character.isUpperCase(chars[i])) {
                                chars[i] = '1';
                                break;
                            }
                        }
                    } else {
                        for (int i = 0; i < chars.length; i++) {
                            if (Character.isLowerCase(chars[i])) {
                                chars[i] = '1';
                                break;
                            }
                        }
                    }
                } else if (missingUpper) {
                    if (countLower > countDigit) {
                        for (int i = 0; i < chars.length; i++) {
                            if (Character.isLowerCase(chars[i])) {
                                chars[i] = 'A';
                                break;
                            }
                        }
                    } else {
                        for (int i = 0; i < chars.length; i++) {
                            if (Character.isDigit(chars[i])) {
                                chars[i] = 'A';
                                break;
                            }
                        }
                    }
                } else if (missingLower) {
                    if (countUpper > countDigit) {
                        for (int i = 0; i < chars.length; i++) {
                            if (Character.isUpperCase(chars[i])) {
                                chars[i] = 'a';
                                break;
                            }
                        }
                    } else {
                        for (int i = 0; i < chars.length; i++) {
                            if (Character.isDigit(chars[i])) {
                                chars[i] = 'a';
                                break;
                            }
                        }
                    }
                }

                out.println(chars);
            }
        }
    }

    static class InputReader {
        private final InputStream stream;
        private final byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        public int read() {
            if (numChars == -1) {
                throw new InputMismatchException();
            }

            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0) {
                    return -1;
                }
            }
            return buf[curChar++];
        }

        public int nextInt() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }

            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }

            int res = 0;
            do {
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                res *= 10;
                res += c - '0'; // More readable than bitwise AND
                c = read();
            } while (!isSpaceChar(c));

            return res * sgn;
        }

        public String next() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }

            StringBuilder res = new StringBuilder();
            do {
                res.appendCodePoint(c);
                c = read();
            } while (!isSpaceChar(c));

            return res.toString();
        }

        public boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }
    }
}

import java.util.Scanner;

/**
 * Refactored version of the original program.
 * 
 * Improvements made:
 * 1. Renamed class from 'Ideone' to 'StringProcessor' for better context and maintainability.
 * 2. Extracted the core logic into a separate method 'processInputString' to reduce 
 *    complexity in 'main()' and improve code readability.
 * 3. Replaced manual character range checks (e.g., 'c[i]-'0' >= 0) with standard 
 *    library methods: Character.isDigit(), Character.isLowerCase(), and Character.isUpperCase().
 * 4. Used descriptive variable names (e.g., 'digitCount' instead of 'countd') to make 
 *    the logic self-documenting.
 * 5. Added a safety check for array bounds in the 'distinctTypesCount == 1' block 
 *    to prevent potential IndexOutOfBoundsException.
 * 6. Removed redundant imports (java.lang.*, java.io.*) as they are either auto-imported 
 *    or unused.
 * 7. Used 'System.out.println(new String(...))' for efficient output instead of printing 
 *    characters one by one in a loop.
 */
public class StringProcessor {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        // Check if input is available to prevent NoSuchElementException
        if (scanner.hasNextInt()) {
            int numTestCases = scanner.nextInt();

            for (int t = 0; t < numTestCases; t++) {
                String inputString = scanner.next();
                String result = processInputString(inputString);
                System.out.println(result);
            }
        }
        scanner.close();
    }

    /**
     * Processes the input string based on character composition rules.
     * 
     * Logic Summary:
     * 1. Counts digits, lowercase, and uppercase characters.
     * 2. Tracks the last index of each character type.
     * 3. If 2 types are present, replaces the last character of the most frequent type
     *    (priority: digits >= 2, then uppercase >= 2, then lowercase) with the 
     *    character corresponding to the missing type.
     * 4. If 1 type is present and length >= 2, replaces the first two characters 
     *    with a mix of other types based on which type dominates.
     */
    private static String processInputString(String input) {
        char[] characters = input.toCharArray();
        int digitCount = 0;
        int lowerCaseCount = 0;
        int upperCaseCount = 0;

        // Initialize last indices to 0. 
        // Note: In the original logic, if a character type is missing, the fallback index used was 0.
        int lastDigitIndex = 0;
        int lastLowerCaseIndex = 0;
        int lastUpperCaseIndex = 0;

        // Iterate to count types and find last indices
        for (int i = 0; i < characters.length; i++) {
            char c = characters[i];
            if (Character.isDigit(c)) {
                digitCount++;
                lastDigitIndex = i;
            } else if (Character.isLowerCase(c)) {
                lowerCaseCount++;
                lastLowerCaseIndex = i;
            } else if (Character.isUpperCase(c)) {
                upperCaseCount++;
                lastUpperCaseIndex = i;
            }
        }

        // Count how many distinct character types are present (0 to 3)
        int distinctTypesCount = 0;
        if (digitCount > 0) distinctTypesCount++;
        if (lowerCaseCount > 0) distinctTypesCount++;
        if (upperCaseCount > 0) distinctTypesCount++;

        // Apply modification rules
        if (distinctTypesCount == 2) {
            char replacementChar;

            // Determine the character to insert based on the missing type
            if (digitCount == 0) {
                replacementChar = '0';
            } else if (upperCaseCount == 0) {
                replacementChar = 'A';
            } else {
                // If digits and uppercase are present, lowercase must be missing
                replacementChar = 'a';
            }

            // Determine which character to replace based on frequency priority
            // Priority: Digits (>=2) -> Uppercase (>=2) -> Lowercase
            if (digitCount >= 2) {
                characters[lastDigitIndex] = replacementChar;
            } else if (upperCaseCount >= 2) {
                characters[lastUpperCaseIndex] = replacementChar;
            } else {
                characters[lastLowerCaseIndex] = replacementChar;
            }

        } else if (distinctTypesCount == 1) {
            // Only one type of character is present.
            // Ensure the string is long enough to modify indices 0 and 1
            if (characters.length >= 2) {
                if (digitCount > 2) {
                    characters[0] = 'a';
                    characters[1] = 'A';
                } else if (upperCaseCount > 2) {
                    characters[0] = 'a';
                    characters[1] = '0';
                } else {
                    // Fallback for lowercase case
                    characters[0] = 'A';
                    characters[1] = '0';
                }
            }
        }

        return new String(characters);
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

/**
 * Refactored solution for finding a secure password variation.
 * 
 * Refactoring improvements:
 * 1. Naming: Class and methods renamed for clarity (SecurePasswordSolver, solveTestCase).
 * 2. Readability: Used Character class methods and descriptive variable names.
 * 3. Robustness: Fixed logic errors in string manipulation (substring indices) that caused 
 *    crashes (StringIndexOutOfBoundsException) and incorrect behavior (off-by-one errors).
 * 4. Separation of Concerns: Logic for finding the string is separated from I/O operations.
 * 5. Performance: Used StringBuilder for efficient string construction.
 * 6. Structure: Encapsulated Fast I/O into a static inner class and cleaned up resource management.
 */
public class SecurePasswordSolver {

    public static void main(String[] args) {
        SecurePasswordSolver solver = new SecurePasswordSolver();
        solver.run();
    }

    public void run() {
        FastScanner scanner = new FastScanner();
        try {
            // Read number of test cases
            String nStr = scanner.next();
            if (nStr == null) return;

            int n = Integer.parseInt(nStr);
            for (int t = 0; t < n; t++) {
                String s = scanner.next();
                if (s != null) {
                    System.out.println(solveTestCase(s));
                }
            }
        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    /**
     * Solves a single test case by finding a secure variation of the input string.
     * A password is secure if it contains at least one uppercase letter, 
     * one lowercase letter, and one digit.
     * 
     * @param s The input password string.
     * @return A secure variation of the string.
     */
    private String solveTestCase(String s) {
        // If already secure, return as is
        if (isSecure(s)) {
            return s;
        }

        // Candidates for single character insertion
        String[] singleCandidates = {"A", "a", "1"};
        // Candidates for double character insertion
        String[] doubleCandidates = {"Aa", "A1", "a1"};

        // Try inserting 1 character at every possible position
        // We iterate from 0 to length (inclusive) to cover prepending, inserting between, and appending.
        for (int i = 0; i <= s.length(); i++) {
            for (String candidate : singleCandidates) {
                String modified = insertAt(s, i, candidate);
                if (isSecure(modified)) {
                    return modified;
                }
            }
        }

        // Try inserting 2 characters at every possible position
        for (int i = 0; i <= s.length(); i++) {
            for (String candidate : doubleCandidates) {
                String modified = insertAt(s, i, candidate);
                if (isSecure(modified)) {
                    return modified;
                }
            }
        }

        // Fallback (should theoretically not be reached given the problem constraints)
        return s;
    }

    /**
     * Inserts a string into another string at a specific index.
     * @param original The original string.
     * @param index The index to insert at.
     * @param insertion The string to insert.
     * @return The new string with insertion.
     */
    private String insertAt(String original, int index, String insertion) {
        StringBuilder sb = new StringBuilder(original);
        // Insert handles bounds gracefully, but we ensure index is within valid range [0, length]
        // to strictly mimic substring split behavior.
        int safeIndex = Math.min(index, sb.length());
        sb.insert(safeIndex, insertion);
        return sb.toString();
    }

    /**
     * Checks if a string contains at least one uppercase letter, 
     * one lowercase letter, and one digit.
     * @param s The string to check.
     * @return true if secure, false otherwise.
     */
    private boolean isSecure(String s) {
        boolean hasUpper = false;
        boolean hasLower = false;
        boolean hasDigit = false;

        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (Character.isUpperCase(c)) {
                hasUpper = true;
            } else if (Character.isLowerCase(c)) {
                hasLower = true;
            } else if (Character.isDigit(c)) {
                hasDigit = true;
            }

            // Optimization: Early exit if all conditions are met
            if (hasUpper && hasLower && hasDigit) {
                return true;
            }
        }
        return false;
    }

    /**
     * Helper class for fast input reading.
     */
    static class FastScanner {
        BufferedReader br;
        StringTokenizer st;

        public FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            String s = next();
            return (s == null) ? 0 : Integer.parseInt(s);
        }
    }
}

import java.util.Scanner;

/**
 * Processes input strings to find and print the first valid modification
 * that contains at least one lowercase letter, one uppercase letter, and one digit.
 */
public class Main {
    // Constants for replacement characters to eliminate magic values
    private static final char LOWER = 'a';
    private static final char UPPER = 'A';
    private static final char DIGIT = '9';

    public static void main(String[] args) {
        // Use try-with-resources to ensure the Scanner is properly closed
        try (Scanner scanner = new Scanner(System.in)) {
            if (scanner.hasNextInt()) {
                int testCases = scanner.nextInt();
                while (testCases-- > 0) {
                    if (scanner.hasNext()) {
                        String input = scanner.next();
                        findAndPrintValidString(new StringBuilder(input));
                    }
                }
            }
        }
    }

    /**
     * Attempts to find a valid string by checking the original,
     * then single-character replacements, then two-character replacements.
     */
    private static void findAndPrintValidString(StringBuilder sb) {
        if (isValid(sb)) {
            printResult(sb);
            return;
        }

        // Try replacing each character with a lowercase, uppercase, or digit
        for (int i = 0; i < sb.length(); i++) {
            char original = sb.charAt(i);
            sb.setCharAt(i, LOWER);
            if (checkAndPrint(sb)) return;
            sb.setCharAt(i, UPPER);
            if (checkAndPrint(sb)) return;
            sb.setCharAt(i, DIGIT);
            if (checkAndPrint(sb)) return;
            sb.setCharAt(i, original); // Restore original character
        }

        // Try replacing each pair of characters with valid combinations
        for (int i = 0; i + 1 < sb.length(); i++) {
            String originalPair = sb.substring(i, i + 2);
            sb.replace(i, i + 2, "aA");
            if (checkAndPrint(sb)) return;
            sb.replace(i, i + 2, "a9");
            if (checkAndPrint(sb)) return;
            sb.replace(i, i + 2, "A9");
            if (checkAndPrint(sb)) return;
            sb.replace(i, i + 2, originalPair); // Restore original pair
        }
    }

    /**
     * Checks if the string is valid and prints it if so.
     * @return true if the string was valid and printed, false otherwise
     */
    private static boolean checkAndPrint(StringBuilder sb) {
        if (isValid(sb)) {
            printResult(sb);
            return true;
        }
        return false;
    }

    /**
     * Prints the current state of the StringBuilder.
     */
    private static void printResult(StringBuilder sb) {
        System.out.println(sb);
    }

    /**
     * Validates that the string contains at least one lowercase letter,
     * one uppercase letter, and one digit.
     */
    private static boolean isValid(StringBuilder sb) {
        boolean hasLower = false;
        boolean hasUpper = false;
        boolean hasDigit = false;

        for (int i = 0; i < sb.length(); i++) {
            char c = sb.charAt(i);
            if (c >= 'a' && c <= 'z') hasLower = true;
            else if (c >= 'A' && c <= 'Z') hasUpper = true;
            else if (c >= '0' && c <= '9') hasDigit = true;

            // Early exit if all requirements are met
            if (hasLower && hasUpper && hasDigit) {
                return true;
            }
        }
        return false;
    }
}

import java.util.Scanner;

public class Solution {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        // Read the number of test cases
        if (scanner.hasNextInt()) {
            int t = scanner.nextInt();
            scanner.nextLine(); // Consume the newline character left by nextInt()

            // Process each test case
            for (int i = 0; i < t; i++) {
                String s = scanner.nextLine();
                System.out.println(fixString(s));
            }
        }
        scanner.close();
    }

    /**
     * Analyzes the string for character types and applies fixes to ensure
     * the string contains at least one lowercase, one uppercase, and one digit.
     * 
     * @param s The input string to process.
     * @return The modified string.
     */
    private static String fixString(String s) {
        int lowercaseCount = 0;
        int uppercaseCount = 0;
        int digitCount = 0;

        int lastLowercaseIndex = -1;
        int lastUppercaseIndex = -1;
        int lastDigitIndex = -1;

        // Single pass to count character types and track the last index of each type
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (Character.isLowerCase(c)) {
                lowercaseCount++;
                lastLowercaseIndex = i;
            } else if (Character.isUpperCase(c)) {
                uppercaseCount++;
                lastUppercaseIndex = i;
            } else if (Character.isDigit(c)) {
                digitCount++;
                lastDigitIndex = i;
            }
        }

        // Logic to fix missing character types based on original requirements
        // Case 1: Missing both Lowercase and Uppercase (likely all digits)
        if (lowercaseCount == 0 && uppercaseCount == 0) {
            return "aA" + getSuffix(s, 2);
        }
        // Case 2: Missing both Lowercase and Digit (likely all uppercase)
        else if (lowercaseCount == 0 && digitCount == 0) {
            return "a1" + getSuffix(s, 2);
        }
        // Case 3: Missing both Digit and Uppercase (likely all lowercase)
        else if (digitCount == 0 && uppercaseCount == 0) {
            return "1A" + getSuffix(s, 2);
        }
        // Case 4: Missing Lowercase
        else if (lowercaseCount == 0) {
            if (digitCount > 1) {
                return replaceCharAt(s, lastDigitIndex, 'a');
            } else {
                return replaceCharAt(s, lastUppercaseIndex, 'a');
            }
        }
        // Case 5: Missing Uppercase
        else if (uppercaseCount == 0) {
            if (digitCount > 1) {
                return replaceCharAt(s, lastDigitIndex, 'A');
            } else {
                return replaceCharAt(s, lastLowercaseIndex, 'A');
            }
        }
        // Case 6: Missing Digit
        else if (digitCount == 0) {
            if (uppercaseCount > 1) {
                return replaceCharAt(s, lastUppercaseIndex, '1');
            } else {
                return replaceCharAt(s, lastLowercaseIndex, '1');
            }
        }
        // Case 7: All types present
        else {
            return s;
        }
    }

    /**
     * Helper method to safely retrieve the substring starting from a specific index.
     * Returns an empty string if the index is out of bounds to prevent exceptions.
     *
     * @param s The source string.
     * @param startIndex The index to start the substring from.
     * @return The substring or empty string.
     */
    private static String getSuffix(String s, int startIndex) {
        if (startIndex >= s.length()) {
            return "";
        }
        return s.substring(startIndex);
    }

    /**
     * Replaces the character at the specified index with the replacement character.
     * This is equivalent to: s.substring(0, index) + replacement + s.substring(index + 1)
     *
     * @param s The source string.
     * @param index The index of the character to replace.
     * @param replacement The character to insert.
     * @return The modified string.
     */
    private static String replaceCharAt(String s, int index, char replacement) {
        if (index < 0 || index >= s.length()) {
            return s; // Return original string if index is invalid
        }
        return s.substring(0, index) + replacement + s.substring(index + 1);
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

public class Main {

    public static void main(String[] args) {
        FastScanner in = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            String tStr = in.next();
            if (tStr != null) {
                int testCount = Integer.parseInt(tStr);
                for (int i = 1; i <= testCount; i++) {
                    String password = in.next();
                    String result = solve(password);
                    out.println(result);
                }
            }
        } catch (Exception e) {
            // In a production environment, handle exceptions appropriately.
            // For competitive programming, we typically let it crash or ignore.
        } finally {
            out.flush();
            out.close();
        }
    }

    /**
     * Solves the problem for a single password.
     * If the password is already valid, it returns it.
     * Otherwise, it attempts to find the first valid modification by replacing
     * a substring of length 1, 2, or 3 with a generated string.
     */
    private static String solve(String password) {
        if (isValidPassword(password)) {
            return password;
        }
        return findValidModification(password);
    }

    /**
     * Searches for the first valid modification of the password.
     * Iterates through substring lengths 1 to 3, and all valid bitmasks.
     * This mimics the original nested loop structure but in a cleaner way.
     */
    private static String findValidModification(String password) {
        int n = password.length();

        // Try replacing substrings of length 1, 2, 3
        // Original loop: for (int len = 1; len < 4; ++len)
        for (int len = 1; len <= 3; len++) {
            // Iterate through all valid starting positions
            // Original loop: for (int i = 0; i + len <= password.length(); ++i)
            for (int i = 0; i <= n - len; i++) {
                // Try all bitmasks 1 to 7 (0 is skipped as bitCount is 0)
                // Original loop: for (int mask = 0; mask < (1 << 3); ++mask)
                for (int mask = 1; mask < 8; mask++) {
                    // Check if the mask generates a string of the required length
                    // Original check: if (Integer.bitCount(mask) != len) continue;
                    if (Integer.bitCount(mask) == len) {
                        String replacement = generateReplacement(mask);
                        String candidate = buildCandidate(password, i, len, replacement);
                        if (isValidPassword(candidate)) {
                            return candidate;
                        }
                    }
                }
            }
        }
        // If no valid modification is found, return the original password
        return password;
    }

    /**
     * Constructs a candidate string by replacing a substring in the original.
     * Original logic: password.substring(0, i) + generate(mask) + password.substring(i + len)
     */
    private static String buildCandidate(String original, int startIndex, int length, String replacement) {
        return original.substring(0, startIndex) + replacement + original.substring(startIndex + length);
    }

    /**
     * Generates a replacement string based on the bitmask.
     * Bit 0 -> 'a', Bit 1 -> 'A', Bit 2 -> '1'.
     * Preserves the exact generation logic of the original code.
     */
    private static String generateReplacement(int mask) {
        StringBuilder sb = new StringBuilder();
        if ((mask & 1) != 0) sb.append('a');
        if ((mask & 2) != 0) sb.append('A');
        if ((mask & 4) != 0) sb.append('1');
        return sb.toString();
    }

    /**
     * Checks if the password contains at least one lowercase letter,
     * one uppercase letter, and one digit.
     * Replaces the original 'ok' method and 'contains' helper with a single efficient check.
     */
    private static boolean isValidPassword(String s) {
        boolean hasLower = false;
        boolean hasUpper = false;
        boolean hasDigit = false;

        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (Character.isLowerCase(c)) hasLower = true;
            else if (Character.isUpperCase(c)) hasUpper = true;
            else if (Character.isDigit(c)) hasDigit = true;
        }
        return hasLower && hasUpper && hasDigit;
    }

    /**
     * Helper class for fast input reading, replacing the original InputReader.
     */
    static class FastScanner {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastScanner(InputStream in) {
            reader = new BufferedReader(new InputStreamReader(in));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            String s = next();
            if (s == null) throw new RuntimeException("End of input");
            return Integer.parseInt(s);
        }
    }
}

import java.io.*;
import java.util.*;

public class Main {

    public static void main(String[] args) {
        MyScanner in = new MyScanner(System.in);
        PrintWriter out = new PrintWriter(System.out);
        try {
            int t = in.nextInt();
            while (t-- > 0) {
                String s = in.next();
                out.println(solve(s));
            }
        } finally {
            out.flush();
            out.close();
        }
    }

    /**
     * Finds the optimal string by removing a substring and replacing it with
     * the minimum required characters to satisfy digit, uppercase, and lowercase conditions.
     * 
     * Time Complexity: O(N²) where N is the length of the string.
     * Space Complexity: O(N) for prefix/suffix arrays.
     */
    private static String solve(String s) {
        int n = s.length();

        // Precompute prefix and suffix character presence for O(1) checks
        boolean[] preDigit = new boolean[n + 1];
        boolean[] preLower = new boolean[n + 1];
        boolean[] preUpper = new boolean[n + 1];
        boolean[] sufDigit = new boolean[n + 1];
        boolean[] sufLower = new boolean[n + 1];
        boolean[] sufUpper = new boolean[n + 1];

        for (int i = 0; i < n; i++) {
            char c = s.charAt(i);
            preDigit[i + 1] = preDigit[i] || Character.isDigit(c);
            preLower[i + 1] = preLower[i] || Character.isLowerCase(c);
            preUpper[i + 1] = preUpper[i] || Character.isUpperCase(c);
        }

        for (int i = n - 1; i >= 0; i--) {
            char c = s.charAt(i);
            sufDigit[i] = sufDigit[i + 1] || Character.isDigit(c);
            sufLower[i] = sufLower[i + 1] || Character.isLowerCase(c);
            sufUpper[i] = sufUpper[i + 1] || Character.isUpperCase(c);
        }

        // Iterate over possible lengths of the substring to remove (dist)
        // Starting from 0 guarantees we find the optimal (shortest) replacement first
        for (int dist = 0; dist <= n; dist++) {
            for (int start = 0; start <= n - dist; start++) {
                int end = start + dist;

                // Check character types in the remaining parts (prefix + suffix)
                boolean hasDigit = preDigit[start] || sufDigit[end];
                boolean hasLower = preLower[start] || sufLower[end];
                boolean hasUpper = preUpper[start] || sufUpper[end];

                // Determine required characters to fill the gap
                StringBuilder toAdd = new StringBuilder();
                if (!hasDigit) toAdd.append('1');
                if (!hasUpper) toAdd.append('A');
                if (!hasLower) toAdd.append('a');

                // If required characters exceed the gap size, this substring length won't work
                if (toAdd.length() > dist) {
                    continue;
                }

                // Pad with '0' to match the exact gap size
                while (toAdd.length() < dist) {
                    toAdd.append('0');
                }

                // Construct the candidate string
                String candidate = s.substring(0, start) + toAdd.toString() + s.substring(end);
                return candidate; // First valid match is guaranteed to be optimal
            }
        }
        return s; // Fallback (should theoretically be reachable if n=0 or edge cases)
    }

    /**
     * Fast I/O utility class for competitive programming.
     */
    public static class MyScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public MyScanner(InputStream in) {
            this.br = new BufferedReader(new InputStreamReader(in));
        }

        public String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }

        public double nextDouble() {
            return Double.parseDouble(next());
        }

        public String nextLine() {
            String str = "";
            try {
                str = br.readLine();
            } catch (IOException e) {
                throw new RuntimeException(e);
            }
            return str;
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

public class Main {

    public static void main(String[] args) throws IOException {
        FastReader in = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            int n = in.nextInt();
            for (int i = 0; i < n; i++) {
                out.println(ensureAllCharTypes(in.next()));
            }
        } finally {
            out.flush();
            out.close();
        }
    }

    /**
     * Ensures the input string contains at least one lowercase letter, 
     * one uppercase letter, and one non-letter character (typically a digit).
     * Modifies the character array in-place to achieve this with minimal changes.
     */
    private static String ensureAllCharTypes(String input) {
        char[] chars = input.toCharArray();
        if (chars.length < 2) {
            return input; // Cannot satisfy condition with fewer than 2 characters
        }

        boolean hasLower = false;
        boolean hasUpper = false;
        boolean hasOther = false; // Represents type 2 (digits/symbols)

        int lowerCount = 0, upperCount = 0, otherCount = 0;
        int firstLowerIdx = -1, firstUpperIdx = -1, firstOtherIdx = -1;

        // Single pass to gather presence, counts, and first indices
        for (int i = 0; i < chars.length; i++) {
            char c = chars[i];
            if (Character.isLowerCase(c)) {
                hasLower = true;
                lowerCount++;
                if (firstLowerIdx == -1) firstLowerIdx = i;
            } else if (Character.isUpperCase(c)) {
                hasUpper = true;
                upperCount++;
                if (firstUpperIdx == -1) firstUpperIdx = i;
            } else {
                hasOther = true;
                otherCount++;
                if (firstOtherIdx == -1) firstOtherIdx = i;
            }
        }

        int presentCount = (hasLower ? 1 : 0) + (hasUpper ? 1 : 0) + (hasOther ? 1 : 0);

        if (presentCount == 1) {
            // Only one character type present. Change first two characters to introduce the missing types.
            if (hasLower) {
                chars[0] = 'A';
                chars[1] = '1';
            } else if (hasUpper) {
                chars[0] = 'a';
                chars[1] = '1';
            } else {
                chars[0] = 'a';
                chars[1] = 'A';
            }
        } else if (presentCount == 2) {
            // Two character types present. Change one character to introduce the missing type.
            // Prefer replacing a character from a type that has duplicates to preserve diversity.
            int replaceIdx = -1;
            if (lowerCount > 1) replaceIdx = firstLowerIdx;
            else if (upperCount > 1) replaceIdx = firstUpperIdx;
            else replaceIdx = firstOtherIdx;

            if (!hasLower) chars[replaceIdx] = 'a';
            else if (!hasUpper) chars[replaceIdx] = 'A';
            else chars[replaceIdx] = '1';
        }
        // If presentCount == 3, all types are already present. No changes needed.

        return new String(chars);
    }

    /**
     * Optimized input reader for competitive programming / fast I/O scenarios.
     */
    static class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastReader(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        public String next() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) {
                    throw new IOException("Unexpected end of input");
                }
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        public double nextDouble() throws IOException {
            return Double.parseDouble(next());
        }

        public long nextLong() throws IOException {
            return Long.parseLong(next());
        }

        public String nextLine() throws IOException {
            return br.readLine();
        }

        public boolean ready() throws IOException {
            return br.ready();
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayList;
import java.util.List;
import java.util.StringTokenizer;

public class Main {

    /**
     * FastReader class for efficient input reading.
     * Refactored to handle exceptions properly and avoid infinite loops on EOF.
     */
    static class FastReader {
        BufferedReader br;
        StringTokenizer st;

        public FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) {
                        return null; // End of input
                    }
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            String s = next();
            if (s == null) return 0; // Handle EOF gracefully
            return Integer.parseInt(s);
        }

        long nextLong() {
            String s = next();
            if (s == null) return 0L;
            return Long.parseLong(s);
        }

        double nextDouble() {
            String s = next();
            if (s == null) return 0.0;
            return Double.parseDouble(s);
        }

        String nextLine() {
            String str = "";
            try {
                str = br.readLine();
            } catch (IOException e) {
                throw new RuntimeException("Error reading input", e);
            }
            return str;
        }
    }

    public static void main(String[] args) {
        FastReader scanner = new FastReader();

        // Read number of test cases
        // Using next() to read T ensures we get the integer token correctly.
        String tStr = scanner.next();
        if (tStr == null) return;

        int T = Integer.parseInt(tStr);

        while (T-- > 0) {
            // Read the string for the test case
            // Note: Mixing token-based reading (next) and line-based reading (nextLine) 
            // can be sensitive to input formatting. We assume standard formatting 
            // where the string is on a new line or follows the integer.
            String str = scanner.nextLine();

            solve(str);
        }
    }

    private static void solve(String str) {
        if (str == null) return;

        int lowerCount = 0;
        int upperCount = 0;
        int digitCount = 0;

        // Count character types
        for (int i = 0; i < str.length(); i++) {
            char ch = str.charAt(i);
            if (Character.isUpperCase(ch)) {
                upperCount++;
            } else if (Character.isLowerCase(ch)) {
                lowerCount++;
            } else if (Character.isDigit(ch)) {
                digitCount++;
            }
        }

        List<Character> missingChars = new ArrayList<>();
        if (lowerCount == 0) missingChars.add('a');
        if (upperCount == 0) missingChars.add('A');
        if (digitCount == 0) missingChars.add('0');

        if (missingChars.isEmpty()) {
            System.out.println(str);
        } else if (missingChars.size() == 1) {
            char missingChar = missingChars.get(0);

            // Logic to insert the missing character
            // Original logic: If the first character is the only one of its type,
            // insert the missing char after it. Otherwise, prepend it.
            // Refactored to fix bugs where characters were dropped (substring(2))
            // and to handle edge cases.

            if (str.length() == 0) {
                System.out.println(missingChar);
            } else {
                char firstChar = str.charAt(0);
                int firstCharTypeCount = 0;

                if (Character.isUpperCase(firstChar)) {
                    firstCharTypeCount = upperCount;
                } else if (Character.isLowerCase(firstChar)) {
                    firstCharTypeCount = lowerCount;
                } else if (Character.isDigit(firstChar)) {
                    firstCharTypeCount = digitCount;
                }

                StringBuilder result = new StringBuilder();
                if (firstCharTypeCount > 1) {
                    // Prepend missing char
                    result.append(missingChar).append(str.substring(1));
                } else {
                    // Insert after first char
                    // Fixed: used substring(1) to preserve the rest of the string.
                    // Original code used substring(2) which dropped the character at index 1.
                    result.append(firstChar).append(missingChar).append(str.substring(1));
                }
                System.out.println(result.toString());
            }
        } else {
            // Missing 2 or more types
            // Refactored to iterate through all missing characters.
            // Original code only prepended first two missing chars and dropped string content.

            StringBuilder result = new StringBuilder();
            for (char c : missingChars) {
                result.append(c);
            }
            result.append(str);
            System.out.println(result.toString());
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

/**
 * Generates a secure variant of a given string by inserting required character types
 * (uppercase, lowercase, digit) if they are missing.
 */
public class SecureStringGenerator {

    private static final String[] INSERTION_OPTIONS = {"A", "a", "1", "Aa", "A1", "a1"};

    public static void main(String[] args) {
        // Use try-with-resources for automatic resource management
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            FastScanner scanner = new FastScanner(br);
            int testCases = scanner.nextInt();
            for (int i = 0; i < testCases; i++) {
                String input = scanner.next();
                System.out.println(generateSecureVariant(input));
            }
        } catch (IOException e) {
            throw new RuntimeException("Error reading input from standard input", e);
        }
    }

    /**
     * Checks if the string contains at least one uppercase letter, one lowercase letter, and one digit.
     */
    private static boolean containsRequiredCharacterTypes(String s) {
        boolean hasUpper = false, hasLower = false, hasDigit = false;
        for (char c : s.toCharArray()) {
            if (Character.isUpperCase(c)) hasUpper = true;
            else if (Character.isLowerCase(c)) hasLower = true;
            else if (Character.isDigit(c)) hasDigit = true;

            // Early exit optimization
            if (hasUpper && hasLower && hasDigit) {
                return true;
            }
        }
        return false;
    }

    /**
     * Attempts to make the string secure by inserting characters from INSERTION_OPTIONS
     * at each possible position. Returns the first valid secure variant found,
     * or the original string if already secure. Returns an empty string if no solution is found.
     */
    private static String generateSecureVariant(String original) {
        if (containsRequiredCharacterTypes(original)) {
            return original;
        }

        for (int i = 0; i < original.length(); i++) {
            for (String option : INSERTION_OPTIONS) {
                // Safety check to prevent StringIndexOutOfBoundsException
                if (i + option.length() > original.length()) {
                    continue;
                }
                String candidate = original.substring(0, i) + option + original.substring(i + option.length());
                if (containsRequiredCharacterTypes(candidate)) {
                    return candidate;
                }
            }
        }
        return "";
    }

    /**
     * Helper class for fast and clean input reading.
     */
    private static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner(BufferedReader br) {
            this.br = br;
        }

        public String next() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) {
                    throw new IOException("Unexpected end of input");
                }
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

public class Main {
    // Standard fast I/O setup for maintainability and performance
    private static final BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
    private static final PrintWriter out = new PrintWriter(System.out);
    private static StringTokenizer tokenizer = new StringTokenizer("");

    public static void main(String[] args) throws IOException {
        String token = next();
        if (token == null) return;

        int t = Integer.parseInt(token);

        for (int i = 0; i < t; i++) {
            String input = next();
            if (input != null) {
                out.println(processString(input));
            }
        }

        out.flush();
    }

    /**
     * Processes a single password string to ensure it contains at least one uppercase,
     * one lowercase, and one digit character. Modifies the string in-place if needed.
     */
    private static String processString(String input) {
        int upperCount = 0;
        int lowerCount = 0;
        int digitCount = 0;

        // Count character types
        for (int i = 0; i < input.length(); i++) {
            char c = input.charAt(i);
            if (Character.isUpperCase(c)) {
                upperCount++;
            } else if (Character.isLowerCase(c)) {
                lowerCount++;
            } else if (Character.isDigit(c)) {
                digitCount++;
            }
        }

        boolean hasUpper = upperCount > 0;
        boolean hasLower = lowerCount > 0;
        boolean hasDigit = digitCount > 0;

        // Already satisfies all requirements
        if (hasUpper && hasLower && hasDigit) {
            return input;
        }

        char[] chars = input.toCharArray();

        // Fix missing character types based on original logic
        if (hasUpper && hasLower && !hasDigit) {
            // Missing digit: change an existing character to '0'
            int idx = upperCount > 1 ? findFirstIndex(chars, 'U') : findFirstIndex(chars, 'L');
            chars[idx] = '0';
        } else if (hasUpper && !hasLower && hasDigit) {
            // Missing lowercase: change an existing character to 'a'
            int idx = upperCount > 1 ? findFirstIndex(chars, 'U') : findFirstIndex(chars, 'D');
            chars[idx] = 'a';
        } else if (!hasUpper && hasLower && hasDigit) {
            // Missing uppercase: change an existing character to 'A'
            int idx = lowerCount > 1 ? findFirstIndex(chars, 'L') : findFirstIndex(chars, 'D');
            chars[idx] = 'A';
        } else if (hasUpper && !hasLower && !hasDigit) {
            // Only uppercase present
            chars[0] = 'a';
            chars[1] = '0';
        } else if (!hasUpper && hasLower && !hasDigit) {
            // Only lowercase present
            chars[0] = 'A';
            chars[1] = '0';
        } else if (!hasUpper && !hasLower && hasDigit) {
            // Only digits present
            chars[0] = 'A';
            chars[1] = 'a';
        } else {
            // Fallback for edge cases (e.g., empty or single-character strings)
            chars[0] = 'A';
            chars[1] = 'a';
        }

        return new String(chars);
    }

    /**
     * Finds the first index of a character matching the specified type.
     * @param chars The character array to search
     * @param type 'U' for uppercase, 'L' for lowercase, 'D' for digit
     * @return The index of the first matching character
     */
    private static int findFirstIndex(char[] chars, char type) {
        for (int i = 0; i < chars.length; i++) {
            char c = chars[i];
            if (type == 'U' && Character.isUpperCase(c)) return i;
            if (type == 'L' && Character.isLowerCase(c)) return i;
            if (type == 'D' && Character.isDigit(c)) return i;
        }
        return 0; // Should not be reached given problem constraints
    }

    /**
     * Helper method to safely retrieve the next whitespace-delimited token.
     */
    private static String next() throws IOException {
        while (!tokenizer.hasMoreTokens()) {
            String line = reader.readLine();
            if (line == null) return null;
            tokenizer = new StringTokenizer(line);
        }
        return tokenizer.nextToken();
    }
}

import java.io.*;
