/**
 * Main solution class for processing character strings.
 * Ensures each string contains at least one lowercase letter, 
 * one uppercase letter, and one digit.
 */
public class Main {

    public static void main(String[] args) {
        Main solver = new Main();
        solver.run();
    }

    /**
     * Entry point for the application. Sets up I/O streams and executes the solver.
     */
    public void run() {
        FastScanner in = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            solve(in, out);
        } catch (IOException e) {
            System.err.println("I/O Error: " + e.getMessage());
        } finally {
            out.flush();
            out.close();
        }
    }

    /**
     * Reads test cases and processes each string to satisfy character requirements.
     *
     * @param in  FastScanner for efficient input reading
     * @param out PrintWriter for buffered output
     * @throws IOException if an I/O error occurs during reading
     */
    private void solve(FastScanner in, PrintWriter out) throws IOException {
        int testCases = in.nextInt();
        while (testCases-- > 0) {
            String input = in.next();
            char[] chars = input.toCharArray();
            ensureRequiredCharacters(chars);
            out.println(chars);
        }
    }

    /**
     * Modifies the character array to guarantee at least one lowercase, 
     * one uppercase, and one digit. Preserves existing characters where possible.
     *
     * @param chars the mutable character array to modify
     */
    private void ensureRequiredCharacters(char[] chars) {
        int lowercaseCount = 0;
        int uppercaseCount = 0;
        int digitCount = 0;

        // Count occurrences of each character type
        for (char c : chars) {
            if (Character.isLowerCase(c)) lowercaseCount++;
            else if (Character.isUpperCase(c)) uppercaseCount++;
            else if (Character.isDigit(c)) digitCount++;
        }

        // If all required types are present, no modification is needed
        if (lowercaseCount > 0 && uppercaseCount > 0 && digitCount > 0) {
            return;
        }

        boolean missingLower = lowercaseCount == 0;
        boolean missingUpper = uppercaseCount == 0;
        boolean missingDigit = digitCount == 0;

        // Handle cases where two character types are missing
        if (missingLower && missingUpper) {
            chars[0] = 'a';
            chars[1] = '1';
        } else if (missingLower && missingDigit) {
            chars[0] = 'a';
            chars[1] = 'A';
        } else if (missingUpper && missingDigit) {
            chars[0] = 'A';
            chars[1] = '1';
        } else {
            // Exactly one type is missing: replace a character of a different type
            if (missingLower) {
                chars[findFirstNonLowerCase(chars)] = 'a';
            } else if (missingUpper) {
                chars[findFirstNonUpperCase(chars)] = 'A';
            } else {
                chars[findFirstNonDigit(chars)] = '1';
            }
        }
    }

    /**
     * Finds the index of the first character that is not a lowercase letter.
     *
     * @param chars the character array to search
     * @return index of the first non-lowercase character
     */
    private int findFirstNonLowerCase(char[] chars) {
        for (int i = 0; i < chars.length; i++) {
            if (!Character.isLowerCase(chars[i])) return i;
        }
        return 0; // Fallback (should not occur if missingLower is true)
    }

    /**
     * Finds the index of the first character that is not an uppercase letter.
     *
     * @param chars the character array to search
     * @return index of the first non-uppercase character
     */
    private int findFirstNonUpperCase(char[] chars) {
        for (int i = 0; i < chars.length; i++) {
            if (!Character.isUpperCase(chars[i])) return i;
        }
        return 0;
    }

    /**
     * Finds the index of the first character that is not a digit.
     *
     * @param chars the character array to search
     * @return index of the first non-digit character
     */
    private int findFirstNonDigit(char[] chars) {
        for (int i = 0; i < chars.length; i++) {
            if (!Character.isDigit(chars[i])) return i;
        }
        return 0;
    }

    /**
     * High-performance input scanner for competitive programming and fast I/O.
     */
    private static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1024];
        private int ptr = 0;
        private int buflen = 0;

        public FastScanner(InputStream in) {
            this.in = in;
        }

        private byte readByte() throws IOException {
            if (ptr >= buflen) {
                ptr = 0;
                buflen = in.read(buffer);
                if (buflen <= 0) return -1;
            }
            return buffer[ptr++];
        }

        private int skip() throws IOException {
            int b;
            while ((b = readByte()) != -1 && !isSpaceChar(b)) {
                // Skip whitespace
            }
            return b;
        }

        private boolean isSpaceChar(int c) {
            return !(c >= 33 && c <= 126);
        }

        public String next() throws IOException {
            int b = skip();
            if (b == -1) throw new NoSuchElementException("End of input");
            StringBuilder sb = new StringBuilder();
            while (b != -1 && !isSpaceChar(b)) {
                sb.appendCodePoint(b);
                b = readByte();
            }
            return sb.toString();
        }

        public int nextInt() throws IOException {
            int b = skip();
            if (b == -1) throw new NoSuchElementException("End of input");
            int sign = 1;
            if (b == '-') {
                sign = -1;
                b = readByte();
            }
            int res = 0;
            while (b >= '0' && b <= '9') {
                res = res * 10 + (b - '0');
                b = readByte();
            }
            return res * sign;
        }
    }
}

import java.io.*;
import java.util.*;
import java.util.function.Predicate;

public class EducationalR51A {
    // Set this string to override input for local testing
    private static final String TEST_INPUT = "";
    private static final int STACK_SIZE = 1 << 26; // 64MB thread stack

    public static void main(String[] args) {
        new Thread(null, () -> {
            try {
                solve();
            } catch (IOException e) {
                e.printStackTrace();
            }
        }, "solution", STACK_SIZE).start();
    }

    private static void solve() throws IOException {
        FastScanner in = new FastScanner(TEST_INPUT);
        PrintWriter out = new PrintWriter(System.out);

        int t = in.nextInt();
        while (t-- > 0) {
            String s = in.next();
            char[] arr = s.toCharArray();
            fixPassword(arr);
            out.println(arr);
        }
        out.flush();
    }

    /**
     * Modifies the character array to ensure it contains at least one lowercase,
     * one uppercase, and one digit.
     */
    private static void fixPassword(char[] arr) {
        boolean hasLower = false, hasUpper = false, hasDigit = false;
        for (char c : arr) {
            if (Character.isLowerCase(c)) hasLower = true;
            else if (Character.isUpperCase(c)) hasUpper = true;
            else if (Character.isDigit(c)) hasDigit = true;
        }

        // Handle cases where two character types are missing
        if (!hasLower && !hasUpper) {
            arr[0] = 'a';
            arr[1] = 'A';
        } else if (!hasLower && !hasDigit) {
            arr[0] = 'a';
            arr[1] = '1';
        } else if (!hasUpper && !hasDigit) {
            arr[0] = 'A';
            arr[1] = '1';
        } else {
            // Exactly one character type is missing
            if (!hasLower) {
                replaceFirst(arr, c -> Character.isUpperCase(c) || Character.isDigit(c), 'a');
            } else if (!hasUpper) {
                replaceFirst(arr, c -> Character.isLowerCase(c) || Character.isDigit(c), 'A');
            } else if (!hasDigit) {
                replaceFirst(arr, c -> Character.isLowerCase(c) || Character.isUpperCase(c), '1');
            }
        }
    }

    /**
     * Replaces the first character matching the condition with the replacement value.
     */
    private static void replaceFirst(char[] arr, Predicate<Character> condition, char replacement) {
        for (int i = 0; i < arr.length; i++) {
            if (condition.test(arr[i])) {
                arr[i] = replacement;
                break;
            }
        }
    }

    /**
     * Fast I/O scanner optimized for competitive programming.
     * Encapsulates byte-buffer reading logic for clean separation of concerns.
     */
    static class FastScanner {
        private final InputStream is;
        private final byte[] buffer = new byte[1024];
        private int ptr = 0;
        private int buflen = 0;

        public FastScanner(String testInput) {
            this.is = testInput.isEmpty() ? System.in : new ByteArrayInputStream(testInput.getBytes());
        }

        private byte readByte() throws IOException {
            if (ptr >= buflen) {
                ptr = 0;
                buflen = is.read(buffer);
                if (buflen <= 0) return -1;
            }
            return buffer[ptr++];
        }

        public String next() throws IOException {
            byte c = readByte();
            while (c <= ' ') {
                if (c == -1) throw new EOFException("End of input");
                c = readByte();
            }
            StringBuilder sb = new StringBuilder();
            while (c > ' ') {
                sb.append((char) c);
                c = readByte();
            }
            return sb.toString();
        }

        public int nextInt() throws IOException {
            byte c = readByte();
            while (c <= ' ') {
                if (c == -1) throw new EOFException("End of input");
                c = readByte();
            }
            boolean negative = false;
            if (c == '-') {
                negative = true;
                c = readByte();
            }
            int result = 0;
            while (c >= '0' && c <= '9') {
                result = result * 10 + (c - '0');
                c = readByte();
            }
            return negative ? -result : result;
        }
    }
}

import java.io.*;
import java.util.*;

public class Main {
    private static boolean DEBUG_FLAG = false;

    public static void main(String[] args) throws IOException {
        if (args.length > 0 && args[0].equalsIgnoreCase("d")) {
            DEBUG_FLAG = true;
        }

        InputReader in = new InputReader();
        PrintWriter out = new PrintWriter(System.out);
        int t = in.nextInt();
        long start = System.nanoTime();

        while (t-- > 0) {
            new Main().solve(in, out);
        }

        long end = System.nanoTime();
        debug("\nTime: " + (end - start) / 1e6 + " ms\n\n");
        out.close();
    }

    private void solve(InputReader in, PrintWriter out) {
        char[] s = in.next().toCharArray();
        int n = s.length;
        int lowerCount = 0, upperCount = 0, digitCount = 0;

        // Count character types
        for (char c : s) {
            if (Character.isLowerCase(c)) lowerCount++;
            else if (Character.isUpperCase(c)) upperCount++;
            else if (Character.isDigit(c)) digitCount++;
        }

        // Already satisfies the condition
        if (lowerCount > 0 && upperCount > 0 && digitCount > 0) {
            out.println(s);
            return;
        }

        boolean missingLower = (lowerCount == 0);
        boolean missingUpper = (upperCount == 0);
        boolean missingDigit = (digitCount == 0);

        // Case: Two types missing (only one type present)
        if (missingLower && missingUpper) {
            s[findFirst(s, 2, 1)] = 'a';
            s[findFirst(s, 2, 2)] = 'A';
        } else if (missingLower && missingDigit) {
            s[findFirst(s, 1, 1)] = 'a';
            s[findFirst(s, 1, 2)] = '0';
        } else if (missingUpper && missingDigit) {
            s[findFirst(s, 0, 1)] = 'A';
            s[findFirst(s, 0, 2)] = '0';
        } else {
            // Case: Exactly one type missing
            char replacement;
            if (missingLower) replacement = 'a';
            else if (missingUpper) replacement = 'A';
            else replacement = '0';

            int replaceIndex = -1;
            // Prioritize replacing a character from a type that has duplicates
            if (missingDigit) {
                if (lowerCount > 1) replaceIndex = findFirst(s, 0, 1);
                else if (upperCount > 1) replaceIndex = findFirst(s, 1, 1);
            } else if (missingLower) {
                if (digitCount > 1) replaceIndex = findFirst(s, 2, 1);
                else if (upperCount > 1) replaceIndex = findFirst(s, 1, 1);
            } else {
                if (lowerCount > 1) replaceIndex = findFirst(s, 0, 1);
                else if (digitCount > 1) replaceIndex = findFirst(s, 2, 1);
            }

            if (replaceIndex != -1) {
                s[replaceIndex] = replacement;
            }
        }
        out.println(s);
    }

    /**
     * Finds the index of the nth occurrence of a character type.
     * type: 0 = lowercase, 1 = uppercase, 2 = digit
     */
    private static int findFirst(char[] arr, int type, int occurrence) {
        int count = 0;
        for (int i = 0; i < arr.length; i++) {
            boolean match = false;
            if (type == 0 && Character.isLowerCase(arr[i])) match = true;
            else if (type == 1 && Character.isUpperCase(arr[i])) match = true;
            else if (type == 2 && Character.isDigit(arr[i])) match = true;

            if (match) {
                count++;
                if (count == occurrence) return i;
            }
        }
        return -1; // Should not occur given problem constraints (n >= 3)
    }

    private static void debug(String s) {
        if (DEBUG_FLAG) System.out.print(s);
    }

    public static void show(Object... o) {
        System.out.println(Arrays.deepToString(o));
    }

    static class InputReader {
        private BufferedReader br;
        private StringTokenizer st;

        public InputReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            String s = next();
            return s == null ? 0 : Integer.parseInt(s);
        }

        long nextLong() {
            String s = next();
            return s == null ? 0L : Long.parseLong(s);
        }

        double nextDouble() {
            String s = next();
            return s == null ? 0.0 : Double.parseDouble(s);
        }
    }
}

