    /**
     * Solves the password validation/fixing problem.
     * Ensures each string contains at least one lowercase letter, 
     * one uppercase letter, and one digit.
     */
    static class PasswordFixer {
        public void solve(InputReader in, PrintWriter out) {
            int t = in.nextInt();
            while (t-- > 0) {
                String s = in.nextToken();
                char[] chars = s.toCharArray();

                int lowerCount = 0;
                int upperCount = 0;
                int digitCount = 0;

                // Count character types in a single pass
                for (char c : chars) {
                    if (Character.isLowerCase(c)) lowerCount++;
                    else if (Character.isUpperCase(c)) upperCount++;
                    else if (Character.isDigit(c)) digitCount++;
                }

                boolean missingLower = lowerCount == 0;
                boolean missingUpper = upperCount == 0;
                boolean missingDigit = digitCount == 0;

                // Already satisfies all requirements
                if (!missingLower && !missingUpper && !missingDigit) {
                    out.println(s);
                    continue;
                }

                // Handle cases where exactly two character types are missing
                if (missingLower && missingUpper) {
                    chars[0] = 'a';
                    chars[1] = '1';
                    out.println(chars);
                    continue;
                }
                if (missingLower && missingDigit) {
                    chars[0] = 'a';
                    chars[1] = 'A';
                    out.println(chars);
                    continue;
                }
                if (missingUpper && missingDigit) {
                    chars[0] = 'A';
                    chars[1] = '1';
                    out.println(chars);
                    continue;
                }

                // Handle case where exactly one character type is missing
                char missingChar = missingLower ? 'a' : (missingUpper ? 'A' : '1');

                // Determine which existing character type to replace
                // Preference goes to the most abundant type to minimize structural changes
                char sourceType = missingLower ? (upperCount > digitCount ? 'U' : 'D')
                                : (missingUpper ? (lowerCount > digitCount ? 'L' : 'D')
                                : (upperCount > lowerCount ? 'U' : 'L'));

                for (int i = 0; i < chars.length; i++) {
                    char c = chars[i];
                    boolean isSource = (sourceType == 'U' && Character.isUpperCase(c))
                                    || (sourceType == 'L' && Character.isLowerCase(c))
                                    || (sourceType == 'D' && Character.isDigit(c));

                    if (isSource) {
                        chars[i] = missingChar;
                        break;
                    }
                }

                out.println(chars);
            }
        }
    }

    /**
     * Fast input reader for competitive programming and performance-critical applications.
     */
    static class InputReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
            tokenizer = null;
        }

        public String nextToken() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input", e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            String token = nextToken();
            return token == null ? 0 : Integer.parseInt(token);
        }
    }
}

import java.util.Scanner;

public class Main {

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            if (scanner.hasNextInt()) {
                int n = scanner.nextInt();
                scanner.nextLine(); // Consume the newline character after the integer

                for (int i = 0; i < n; i++) {
                    if (scanner.hasNextLine()) {
                        String input = scanner.nextLine();
                        System.out.println(convert(input));
                    }
                }
            }
        }
    }

    /**
     * Enum to represent character categories for clearer logic.
     */
    private enum CharType {
        LOWER, UPPER, DIGIT
    }

    /**
     * Ensures the input string contains at least one lowercase letter,
     * one uppercase letter, and one digit. If missing, replaces characters
     * according to the original algorithm's rules.
     */
    private static String convert(String str) {
        if (str == null || str.isEmpty()) {
            return str;
        }

        int lowerCount = 0;
        int upperCount = 0;
        int digitCount = 0;

        // Count occurrences of each character type
        for (int i = 0; i < str.length(); i++) {
            char ch = str.charAt(i);
            if (ch >= 'a' && ch <= 'z') lowerCount++;
            else if (ch >= 'A' && ch <= 'Z') upperCount++;
            else if (ch >= '0' && ch <= '9') digitCount++;
        }

        boolean hasLower = lowerCount > 0;
        boolean hasUpper = upperCount > 0;
        boolean hasDigit = digitCount > 0;

        // If all required character types are present, return unchanged
        if (hasLower && hasUpper && hasDigit) {
            return str;
        }

        StringBuilder sb = new StringBuilder(str);
        int replaceIdx = 0;

        // Case 1: Missing digit
        if (!hasDigit && hasLower && hasUpper) {
            replaceIdx = findFirstIndexByType(str, lowerCount > upperCount ? CharType.LOWER : CharType.UPPER);
            sb.replace(replaceIdx, replaceIdx + 1, "1");
        }
        // Case 2: Missing uppercase
        else if (!hasUpper && hasLower && hasDigit) {
            replaceIdx = findFirstIndexByType(str, lowerCount > digitCount ? CharType.LOWER : CharType.DIGIT);
            sb.replace(replaceIdx, replaceIdx + 1, "A");
        }
        // Case 3: Missing lowercase
        else if (!hasLower && hasUpper && hasDigit) {
            replaceIdx = findFirstIndexByType(str, upperCount > digitCount ? CharType.UPPER : CharType.DIGIT);
            sb.replace(replaceIdx, replaceIdx + 1, "a");
        }
        // Case 4: Missing lowercase and uppercase
        else if (!hasLower && !hasUpper && hasDigit) {
            sb.replace(0, Math.min(2, sb.length()), "aA");
        }
        // Case 5: Missing lowercase and digit
        else if (!hasLower && !hasDigit && hasUpper) {
            sb.replace(0, Math.min(2, sb.length()), "a0");
        }
        // Case 6: Missing uppercase and digit
        else if (!hasUpper && !hasDigit && hasLower) {
            sb.replace(0, Math.min(2, sb.length()), "A0");
        }
        // Case 7: All missing or empty string
        else {
            return str;
        }

        return sb.toString();
    }

    /**
     * Finds the index of the first character matching the specified type.
     */
    private static int findFirstIndexByType(String str, CharType type) {
        for (int i = 0; i < str.length(); i++) {
            char ch = str.charAt(i);
            if ((type == CharType.LOWER && ch >= 'a' && ch <= 'z') ||
                (type == CharType.UPPER && ch >= 'A' && ch <= 'Z') ||
                (type == CharType.DIGIT && ch >= '0' && ch <= '9')) {
                return i;
            }
        }
        return 0; // Fallback; logically unreachable given precondition checks
    }
}

import java.io.IOException;
import java.io.InputStream;

public class Main {
    public static void main(String[] args) throws IOException {
        FastReader reader = new FastReader(System.in);
        StringBuilder output = new StringBuilder();

        int t = reader.nextInt();
        while (t-- > 0) {
            String input = reader.next();
            output.append(processString(input)).append('\n');
        }

        System.out.print(output);
    }

    /**
     * Ensures the input string contains at least one lowercase, one uppercase,
     * and one digit. Modifies the string according to the following rules:
     * 1. If two types are missing, inserts the required characters at the beginning.
     * 2. If one type is missing, replaces the first character of a type with count > 1.
     * 3. If all types are present, returns the string unchanged.
     */
    private static String processString(String input) {
        int lowerCount = 0;
        int upperCount = 0;
        int digitCount = 0;

        // Count character types
        for (int i = 0; i < input.length(); i++) {
            char c = input.charAt(i);
            if (c >= 'a' && c <= 'z') lowerCount++;
            else if (c >= 'A' && c <= 'Z') upperCount++;
            else if (c >= '0' && c <= '9') digitCount++;
        }

        boolean missingLower = lowerCount == 0;
        boolean missingUpper = upperCount == 0;
        boolean missingDigit = digitCount == 0;

        StringBuilder sb = new StringBuilder(input);

        // Case 1: Missing two character types -> insert at the beginning
        if (missingLower && missingUpper) {
            sb.insert(0, "aA");
        } else if (missingLower && missingDigit) {
            sb.insert(0, "a1");
        } else if (missingUpper && missingDigit) {
            sb.insert(0, "A1");
        } 
        // Case 2: Missing exactly one character type -> replace first redundant character
        else {
            char replacement;
            if (missingLower) replacement = 'a';
            else if (missingUpper) replacement = 'A';
            else replacement = '1';

            int replaceIndex = -1;
            for (int i = 0; i < sb.length(); i++) {
                char c = sb.charAt(i);
                boolean isLower = c >= 'a' && c <= 'z';
                boolean isUpper = c >= 'A' && c <= 'Z';
                boolean isDigit = c >= '0' && c <= '9';

                boolean shouldReplace = false;
                if (missingLower && (isUpper && upperCount > 1 || isDigit && digitCount > 1)) {
                    shouldReplace = true;
                } else if (missingUpper && (isLower && lowerCount > 1 || isDigit && digitCount > 1)) {
                    shouldReplace = true;
                } else if (missingDigit && (isLower && lowerCount > 1 || isUpper && upperCount > 1)) {
                    shouldReplace = true;
                }

                if (shouldReplace) {
                    replaceIndex = i;
                    break;
                }
            }

            // Fallback: replace the first character if no count > 1 is found
            if (replaceIndex != -1) {
                sb.setCharAt(replaceIndex, replacement);
            } else {
                sb.setCharAt(0, replacement);
            }
        }

        return sb.toString();
    }

    /**
     * Fast I/O helper for competitive programming environments.
     */
    static class FastReader {
        private final byte[] buf = new byte[2048];
        private int index, total;
        private final InputStream in;

        FastReader(InputStream is) {
            in = is;
        }

        private int scan() throws IOException {
            if (index >= total) {
                index = 0;
                total = in.read(buf);
                if (total <= 0) {
                    return -1;
                }
            }
            return buf[index++];
        }

        String next() throws IOException {
            int c;
            for (c = scan(); c <= 32; c = scan());
            StringBuilder sb = new StringBuilder();
            for (; c > 32; c = scan()) {
                sb.append((char) c);
            }
            return sb.toString();
        }

        int nextInt() throws IOException {
            int c, val = 0;
            for (c = scan(); c <= 32; c = scan());
            boolean neg = c == '-';
            if (c == '-' || c == '+') {
                c = scan();
            }
            for (; c >= '0' && c <= '9'; c = scan()) {
                val = (val << 3) + (val << 1) + (c & 15);
            }
            return neg ? -val : val;
        }

        long nextLong() throws IOException {
            int c;
            long val = 0;
            for (c = scan(); c <= 32; c = scan());
            boolean neg = c == '-';
            if (c == '-' || c == '+') {
                c = scan();
            }
            for (; c >= '0' && c <= '9'; c = scan()) {
                val = (val << 3) + (val << 1) + (c & 15);
            }
            return neg ? -val : val;
        }
    }
}

import java.util.Scanner;

/**
 * Solves the "Vasya and Password" problem.
 * Ensures each password contains at least one lowercase letter, 
 * one uppercase letter, and one digit by replacing characters as needed.
 */
public class VasyaAndPassword {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        // Safely read the number of test cases
        if (scanner.hasNextInt()) {
            int testCases = scanner.nextInt();
            while (testCases-- > 0) {
                String password = scanner.next();
                System.out.println(strengthenPassword(password));
            }
        }
        scanner.close();
    }

    /**
     * Modifies the password to satisfy all character type requirements.
     * 
     * @param password The input password string
     * @return A valid password containing lowercase, uppercase, and digits
     */
    private static String strengthenPassword(String password) {
        char[] chars = password.toCharArray();
        boolean hasLower = false, hasUpper = false, hasDigit = false;
        int lowerCount = 0, upperCount = 0, digitCount = 0;

        // Count character types
        for (char c : chars) {
            if (Character.isLowerCase(c)) {
                hasLower = true;
                lowerCount++;
            } else if (Character.isUpperCase(c)) {
                hasUpper = true;
                upperCount++;
            } else if (Character.isDigit(c)) {
                hasDigit = true;
                digitCount++;
            }
        }

        // Already satisfies all requirements
        if (hasLower && hasUpper && hasDigit) {
            return password;
        }

        int missingCount = (hasLower ? 0 : 1) + (hasUpper ? 0 : 1) + (hasDigit ? 0 : 1);

        if (missingCount == 1) {
            // Exactly one type is missing
            char missingChar = !hasLower ? 'a' : (!hasUpper ? 'A' : '1');
            char replaceCategory = 0; // 'l', 'u', or 'd'

            // Prefer replacing a character from a category that appears multiple times
            // to minimize the impact on the password's entropy
            if (lowerCount >= 2) replaceCategory = 'l';
            else if (upperCount >= 2) replaceCategory = 'u';
            else if (digitCount >= 2) replaceCategory = 'd';

            for (int i = 0; i < chars.length; i++) {
                boolean isReplaceable = (replaceCategory == 'l' && Character.isLowerCase(chars[i])) ||
                                        (replaceCategory == 'u' && Character.isUpperCase(chars[i])) ||
                                        (replaceCategory == 'd' && Character.isDigit(chars[i]));

                if (isReplaceable) {
                    chars[i] = missingChar;
                    return new String(chars);
                }
            }

            // Fallback: All existing types appear exactly once (implies password length == 3)
            // Replace the first character to satisfy the missing requirement
            chars[0] = missingChar;
            return new String(chars);

        } else if (missingCount == 2) {
            // Exactly two types are missing. Replace the first two characters.
            if (!hasLower && !hasUpper) {
                chars[0] = 'a';
                chars[1] = 'A';
            } else if (!hasLower && !hasDigit) {
                chars[0] = 'a';
                chars[1] = '1';
            } else { // !hasUpper && !hasDigit
                chars[0] = 'A';
                chars[1] = '1';
            }
            return new String(chars);
        }

        return password;
    }
}

import java.io.*;
import java.util.function.Predicate;

/**
 * Transforms input strings based on character composition rules.
 * 
 * Rules:
 * 1. Contains digits, uppercase, and lowercase: print as-is.
 * 2. Missing digits & uppercase: prepend "2A", skip first 2 chars.
 * 3. Missing digits & lowercase: prepend "2a", skip first 2 chars.
 * 4. Missing uppercase & lowercase: prepend "aA", skip first 2 chars.
 * 5. Missing digits only:
 *    - Exactly 1 lowercase: replace first lowercase with '1'.
 *    - Exactly 1 uppercase: replace first uppercase with '1'.
 *    - Otherwise: prepend '1', skip first char.
 * 6. Missing uppercase only:
 *    - Exactly 1 lowercase: replace first lowercase with 'A'.
 *    - Exactly 1 digit: replace first digit with 'A'.
 *    - Otherwise: prepend 'A', skip first char.
 * 7. Missing lowercase only:
 *    - Exactly 1 lowercase: replace first lowercase with 'a'.
 *    - Exactly 1 digit: replace first digit with 'a'.
 *    - Otherwise: prepend 'a', skip first char.
 */
public class StringTransformer {

    public static void main(String[] args) throws IOException {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out));

        try {
            String firstLine = reader.readLine();
            if (firstLine != null && !firstLine.trim().isEmpty()) {
                int n = Integer.parseInt(firstLine.trim());
                for (int i = 0; i < n; i++) {
                    String inputLine = reader.readLine();
                    if (inputLine == null) break;
                    out.println(transform(inputLine));
                }
            }
        } finally {
            out.flush();
        }
    }

    private static String transform(String line) {
        boolean hasDigit = false;
        boolean hasUpper = false;
        boolean hasLower = false;
        int countDigit = 0;
        int countUpper = 0;
        int countLower = 0;

        // Count character types
        for (int i = 0; i < line.length(); i++) {
            char c = line.charAt(i);
            if (Character.isDigit(c)) {
                hasDigit = true;
                countDigit++;
            } else if (Character.isUpperCase(c)) {
                hasUpper = true;
                countUpper++;
            } else if (Character.isLowerCase(c)) {
                hasLower = true;
                countLower++;
            }
        }

        // Rule 1: All three types present
        if (hasDigit && hasUpper && hasLower) {
            return line;
        }

        // Rules 2-4: Missing two types
        if (!hasDigit && !hasUpper) {
            return "2A" + safeSubstring(line, 2);
        }
        if (!hasDigit && !hasLower) {
            return "2a" + safeSubstring(line, 2);
        }
        if (!hasUpper && !hasLower) {
            return "aA" + safeSubstring(line, 2);
        }

        // Rule 5: Missing digits only
        if (!hasDigit) {
            if (countLower == 1) {
                return replaceFirstOfType(line, Character::isLowerCase, '1');
            }
            if (countUpper == 1) {
                return replaceFirstOfType(line, Character::isUpperCase, '1');
            }
            return "1" + safeSubstring(line, 1);
        }

        // Rule 6: Missing uppercase only
        if (!hasUpper) {
            if (countLower == 1) {
                return replaceFirstOfType(line, Character::isLowerCase, 'A');
            }
            if (countDigit == 1) {
                return replaceFirstOfType(line, Character::isDigit, 'A');
            }
            return "A" + safeSubstring(line, 1);
        }

        // Rule 7: Missing lowercase only
        if (!hasLower) {
            if (countLower == 1) {
                return replaceFirstOfType(line, Character::isLowerCase, 'a');
            }
            if (countDigit == 1) {
                return replaceFirstOfType(line, Character::isDigit, 'a');
            }
            return "a" + safeSubstring(line, 1);
        }

        return line;
    }

    /**
     * Finds the index of the first character matching the predicate.
     */
    private static int findFirstIndex(String str, Predicate<Character> predicate) {
        for (int i = 0; i < str.length(); i++) {
            if (predicate.test(str.charAt(i))) {
                return i;
            }
        }
        return -1;
    }

    /**
     * Replaces the first occurrence of a character matching the predicate.
     */
    private static String replaceFirstOfType(String str, Predicate<Character> predicate, char replacement) {
        int idx = findFirstIndex(str, predicate);
        if (idx == -1) return str;
        return str.substring(0, idx) + replacement + str.substring(idx + 1);
    }

    /**
     * Safely returns a substring starting at 'start', avoiding IndexOutOfBoundsException.
     */
    private static String safeSubstring(String str, int start) {
        return start < str.length() ? str.substring(start) : "";
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;

/**
 * Refactored version of the Submit class.
 * Improvements made:
 * 1. Separation of Concerns: I/O handling is separated from business logic.
 * 2. Resource Management: Used try-with-resources for BufferedReader to prevent leaks.
 * 3. Readability: Replaced magic numbers and single-letter variables with descriptive names.
 * 4. Performance: Used char arrays for string manipulation instead of repeated substring concatenation.
 * 5. Robustness: Added bounds checking for string access and input validation.
 * 6. Structure: Extracted helper methods (isValid, tryFix, applyFallback) for modularity.
 */
public class Submit {

    public static void main(String[] args) throws IOException {
        // Use try-with-resources to ensure the BufferedReader is closed automatically
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(System.in))) {
            String line = reader.readLine();
            // Check for null or empty input to prevent crashes
            if (line != null && !line.trim().isEmpty()) {
                int testCases = Integer.parseInt(line.trim());
                while (testCases-- > 0) {
                    String input = reader.readLine();
                    if (input != null) {
                        process(input);
                    }
                }
            }
        }
    }

    /**
     * Processes a single test case string.
     * @param str The input string to validate or fix.
     */
    public static void process(String str) {
        // 1. Check if the string is already valid
        if (isValid(str)) {
            System.out.println(str);
            return;
        }

        // 2. Attempt to fix the string with minimal modifications based on specific rules
        String fixedStr = tryFix(str);
        if (fixedStr != null && isValid(fixedStr)) {
            System.out.println(fixedStr);
            return;
        }

        // 3. Fallback logic if the specific fix rules didn't result in a valid string
        System.out.println(applyFallback(str));
    }

    /**
     * Checks if the string contains at least one digit, one lowercase letter, and one uppercase letter.
     * @param str The string to validate.
     * @return true if valid, false otherwise.
     */
    private static boolean isValid(String str) {
        boolean hasDigit = false;
        boolean hasLower = false;
        boolean hasUpper = false;

        for (int i = 0; i < str.length(); i++) {
            char c = str.charAt(i);
            if (c >= '0' && c <= '9') {
                hasDigit = true;
            } else if (c >= 'a' && c <= 'z') {
                hasLower = true;
            } else if (c >= 'A' && c <= 'Z') {
                hasUpper = true;
            }
        }
        return hasDigit && hasLower && hasUpper;
    }

    /**
     * Attempts to fix the string by replacing the first character of an excess category
     * with a character from a missing category, based on specific priority rules.
     * Returns the modified string, or null if no specific rule was triggered.
     * @param str The input string.
     * @return The fixed string or null.
     */
    private static String tryFix(String str) {
        int digitCount = 0;
        int lowerCount = 0;
        int upperCount = 0;
        int firstDigitIndex = -1;
        int firstLowerIndex = -1;
        int firstUpperIndex = -1;

        // Count types and find first occurrences of each category
        for (int i = 0; i < str.length(); i++) {
            char c = str.charAt(i);
            if (c >= '0' && c <= '9') {
                digitCount++;
                if (firstDigitIndex == -1) firstDigitIndex = i;
            } else if (c >= 'a' && c <= 'z') {
                lowerCount++;
                if (firstLowerIndex == -1) firstLowerIndex = i;
            } else if (c >= 'A' && c <= 'Z') {
                upperCount++;
                if (firstUpperIndex == -1) firstUpperIndex = i;
            }
        }

        // Convert to char array for mutable operations (more efficient than substring concatenation)
        char[] chars = str.toCharArray();

        // Priority Rules (mimicking original logic order)

        // Rule 1: Too many digits, missing lowercase -> change first digit to 'a'
        if (digitCount > 1 && lowerCount == 0) {
            chars[firstDigitIndex] = 'a';
            return new String(chars);
        }

        // Rule 2: Too many digits, missing uppercase -> change first digit to 'A'
        if (digitCount > 1 && upperCount == 0) {
            chars[firstDigitIndex] = 'A';
            return new String(chars);
        }

        // Rule 3: Too many lowercase, missing digit -> change first lowercase to '0'
        if (lowerCount > 1 && digitCount == 0) {
            chars[firstLowerIndex] = '0';
            return new String(chars);
        }

        // Rule 4: Too many lowercase, missing uppercase -> change first lowercase to 'A'
        if (lowerCount > 1 && upperCount == 0) {
            chars[firstLowerIndex] = 'A';
            return new String(chars);
        }

        // Rule 5: Too many uppercase, missing digit -> change first uppercase to '0'
        if (upperCount > 1 && digitCount == 0) {
            chars[firstUpperIndex] = '0';
            return new String(chars);
        }

        // Rule 6: Too many uppercase, missing lowercase -> change first uppercase to 'a'
        if (upperCount > 1 && lowerCount == 0) {
            chars[firstUpperIndex] = 'a';
            return new String(chars);
        }

        return null;
    }

    /**
     * Applies a hardcoded fallback logic if the specific fix rules fail.
     * Relies on the character at index 2 to determine the prefix.
     * @param str The input string.
     * @return The fallback modified string.
     */
    private static String applyFallback(String str) {
        // Safety check for string length. 
        // The original logic assumed str.length() >= 3.
        if (str.length() < 3) {
            return str; 
        }

        char charAt2 = str.charAt(2);

        if (charAt2 >= 'a' && charAt2 <= 'z') {
            return "A1" + str.substring(2);
        } else if (charAt2 >= 'A' && charAt2 <= 'Z') {
            return "a1" + str.substring(2);
        } else {
            // charAt2 is likely a digit or other character
            return "aA" + str.substring(2);
        }
    }
}

import java.util.Scanner;

public class Task1051A {

    /**
     * Represents the specific character type(s) missing from the password.
     */
    public enum PasswordIssue {
        NONE,
        MISSING_DIGIT,
        MISSING_LOWERCASE,
        MISSING_UPPERCASE,
        MISSING_DIGIT_UPPERCASE,
        MISSING_DIGIT_LOWERCASE,
        MISSING_UPPERCASE_LOWERCASE
    }

    /**
     * Analyzes the password and returns the issue type based on missing character categories.
     */
    public static PasswordIssue analyzePassword(String s) {
        boolean hasLower = false, hasUpper = false, hasDigit = false;

        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (Character.isLowerCase(c)) hasLower = true;
            else if (Character.isUpperCase(c)) hasUpper = true;
            else if (Character.isDigit(c)) hasDigit = true;
        }

        if (hasLower && hasUpper && hasDigit) {
            return PasswordIssue.NONE;
        }
        if (!hasDigit) {
            if (!hasUpper) return PasswordIssue.MISSING_DIGIT_UPPERCASE;
            if (!hasLower) return PasswordIssue.MISSING_DIGIT_LOWERCASE;
            return PasswordIssue.MISSING_DIGIT;
        } else {
            if (!hasLower) {
                if (!hasUpper) return PasswordIssue.MISSING_UPPERCASE_LOWERCASE;
                return PasswordIssue.MISSING_LOWERCASE;
            } else {
                return PasswordIssue.MISSING_UPPERCASE;
            }
        }
    }

    /**
     * Finds the optimal index to replace in order to fix a missing character type.
     * It locates the shortest distance between two identical characters of the tracked types
     * to break consecutive identical character runs.
     *
     * @param s          The password string
     * @param trackUpper Whether to track uppercase letters
     * @param trackDigit Whether to track digits
     * @return The index of the character to replace
     */
    private static int findReplacementIndex(String s, boolean trackUpper, boolean trackDigit) {
        int lastUpper = -1;
        int lastDigit = -1;
        int minDist = s.length();
        int replaceIdx = 0;

        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            boolean isUpper = Character.isUpperCase(c);
            boolean isDigit = Character.isDigit(c);

            if (trackUpper && isUpper) {
                if (lastUpper != -1) {
                    int dist = i - lastUpper;
                    if (dist < minDist) {
                        minDist = dist;
                        replaceIdx = lastUpper;
                    }
                }
                lastUpper = i;
            }

            if (trackDigit && isDigit) {
                if (lastDigit != -1) {
                    int dist = i - lastDigit;
                    if (dist < minDist) {
                        minDist = dist;
                        replaceIdx = lastDigit;
                    }
                }
                lastDigit = i;
            }
        }
        return replaceIdx;
    }

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            if (scanner.hasNextInt()) {
                int t = scanner.nextInt();
                while (t-- > 0) {
                    String password = scanner.next();
                    PasswordIssue issue = analyzePassword(password);

                    if (issue == PasswordIssue.NONE) {
                        System.out.println(password);
                    } else {
                        String replacement;
                        int index;

                        switch (issue) {
                            case MISSING_DIGIT_UPPERCASE:
                                replacement = "1A";
                                index = 2;
                                break;
                            case MISSING_DIGIT_LOWERCASE:
                                replacement = "1a";
                                index = 2;
                                break;
                            case MISSING_UPPERCASE_LOWERCASE:
                                replacement = "aA";
                                index = 2;
                                break;
                            case MISSING_DIGIT:
                                // Track uppercase & digits to find optimal replacement spot
                                index = findReplacementIndex(password, true, true);
                                replacement = "1";
                                break;
                            case MISSING_LOWERCASE:
                                // Track uppercase & digits to find optimal replacement spot
                                index = findReplacementIndex(password, true, true);
                                replacement = "a";
                                break;
                            case MISSING_UPPERCASE:
                                // Track lowercase & digits to find optimal replacement spot
                                index = findReplacementIndex(password, false, true);
                                replacement = "A";
                                break;
                            default:
                                replacement = "";
                                index = 0;
                        }

                        StringBuilder sb = new StringBuilder(password);
                        sb.setCharAt(index, replacement.charAt(0));
                        System.out.println(sb.toString());
                    }
                }
            }
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

/**
 * A program to process strings based on character type requirements.
 * It validates or modifies strings to ensure they contain uppercase, lowercase, and digits.
 */
public class PasswordStrength {

    public static void main(String[] args) {
        try (FastScanner scanner = new FastScanner()) {
            new PasswordStrength().init(scanner);
        } catch (IOException e) {
            System.err.println("Error reading input: " + e.getMessage());
            e.printStackTrace();
        }
    }

    void init(FastScanner scanner) {
        solve(scanner);
    }

    void solve(FastScanner scanner) {
        if (!scanner.hasMoreTokens()) return;

        int numTestCases = scanner.nextInt();
        for (int t = 0; t < numTestCases; t++) {
            String inputString = scanner.next();
            processString(inputString);
        }
    }

    /**
     * Processes a single string to ensure it meets complexity requirements.
     * Requirements: Must contain at least one uppercase, one lowercase, and one digit.
     */
    private void processString(String inputString) {
        int[] charCounts = countCharacterTypes(inputString);
        int typesPresentCount = (charCounts[0] > 0 ? 1 : 0) + 
                                (charCounts[1] > 0 ? 1 : 0) + 
                                (charCounts[2] > 0 ? 1 : 0);

        if (typesPresentCount == 3) {
            // Already valid
            System.out.println(inputString);
        } else if (typesPresentCount == 1) {
            // Missing 2 types. Replace the first 2 characters with the missing types.
            StringBuilder missingChars = new StringBuilder();
            if (charCounts[0] == 0) missingChars.append('A');
            if (charCounts[1] == 0) missingChars.append('a');
            if (charCounts[2] == 0) missingChars.append('1');

            // Append the rest of the string starting from index 2.
            // Added safety check to prevent IndexOutOfBoundsException if string length < 2.
            String suffix = (inputString.length() > 2) ? inputString.substring(2) : "";
            System.out.println(missingChars.toString() + suffix);
        } else {
            // Missing 1 type (typesPresentCount == 2). Replace one existing character.
            char missingChar = getMissingChar(charCounts);
            int replacementIndex = findReplacementIndex(inputString, charCounts, missingChar);

            if (replacementIndex != -1) {
                StringBuilder sb = new StringBuilder(inputString);
                sb.setCharAt(replacementIndex, missingChar);
                System.out.println(sb.toString());
            } else {
                // Fallback if no suitable replacement found (should not happen with valid inputs)
                System.out.println(inputString);
            }
        }
    }

    /**
     * Counts the occurrences of Uppercase, Lowercase, and Digits.
     * Returns an int array: [upperCount, lowerCount, digitCount]
     */
    private int[] countCharacterTypes(String s) {
        int upper = 0;
        int lower = 0;
        int digit = 0;

        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (Character.isUpperCase(c)) {
                upper++;
            } else if (Character.isLowerCase(c)) {
                lower++;
            } else if (Character.isDigit(c)) {
                digit++;
            }
        }
        return new int[]{upper, lower, digit};
    }

    private char getMissingChar(int[] counts) {
        if (counts[0] == 0) return 'A';
        if (counts[1] == 0) return 'a';
        return '1';
    }

    /**
     * Finds the index of a character that can be replaced to satisfy the missing type requirement.
     * Prioritizes replacement based on specific rules to maintain original behavior.
     */
    private int findReplacementIndex(String s, int[] counts, char replacementChar) {
        // counts[0] = Upper, counts[1] = Lower, counts[2] = Digit

        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            boolean canReplace = false;

            if (replacementChar == 'A') { // Missing Upper
                // Priority: Lower (if count > 1), then Digit (if count > 1)
                if (Character.isLowerCase(c) && counts[1] > 1) canReplace = true;
                else if (Character.isDigit(c) && counts[2] > 1) canReplace = true;
            } else if (replacementChar == 'a') { // Missing Lower
                // Priority: Upper (if count > 1), then Digit (if count > 1)
                if (Character.isUpperCase(c) && counts[0] > 1) canReplace = true;
                else if (Character.isDigit(c) && counts[2] > 1) canReplace = true;
            } else { // Missing Digit ('1')
                // Priority: Lower (if count > 1), then Upper (if count > 1)
                if (Character.isLowerCase(c) && counts[1] > 1) canReplace = true;
                else if (Character.isUpperCase(c) && counts[0] > 1) canReplace = true;
            }

            if (canReplace) {
                return i;
            }
        }
        return -1;
    }

    /**
     * FastScanner utility for efficient input reading.
     */
    static class FastScanner implements AutoCloseable {
        BufferedReader br;
        StringTokenizer st;

        public FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            String token = next();
            return (token == null) ? 0 : Integer.parseInt(token);
        }

        boolean hasMoreTokens() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return false;
                    if (line.trim().isEmpty()) continue;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return true;
        }

        @Override
        public void close() throws IOException {
            br.close();
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.nio.charset.StandardCharsets;

public class VasyaAndPassword {

    public static void main(String[] args) throws IOException {
        // Use try-with-resources to guarantee proper resource cleanup
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(System.in, StandardCharsets.UTF_8));
             PrintWriter writer = new PrintWriter(System.out)) {

            String line = reader.readLine();
            if (line == null) return;

            int testCases = Integer.parseInt(line.trim());

            while (testCases-- > 0) {
                String input = reader.readLine();
                if (input == null) break;

                char[] characters = input.toCharArray();
                int lowerCount = 0;
                int upperCount = 0;
                int digitCount = 0;

                // Count character categories
                for (char c : characters) {
                    if (Character.isLowerCase(c)) lowerCount++;
                    else if (Character.isUpperCase(c)) upperCount++;
                    else if (Character.isDigit(c)) digitCount++;
                }

                // Ensure each category is represented by replacing the first available character
                if (lowerCount == 0) {
                    replaceFirst(characters, upperCount > 1, digitCount > 1, 'a');
                }
                if (upperCount == 0) {
                    replaceFirst(characters, lowerCount > 1, digitCount > 1, 'A');
                }
                if (digitCount == 0) {
                    replaceFirst(characters, upperCount > 1, lowerCount > 1, '0');
                }

                writer.println(new String(characters));
            }
        }
    }

    /**
     * Replaces the first character of a target category if that category has more than one occurrence.
     *
     * @param chars             The character array to modify in-place
     * @param canReplaceUpper   True if we are allowed to replace an uppercase letter (requires count > 1)
     * @param canReplaceDigit   True if we are allowed to replace a digit (requires count > 1)
     * @param replacement       The character to insert as the replacement
     */
    private static void replaceFirst(char[] chars, boolean canReplaceUpper, boolean canReplaceDigit, char replacement) {
        for (int i = 0; i < chars.length; i++) {
            char c = chars[i];
            if ((Character.isUpperCase(c) && canReplaceUpper) || (Character.isDigit(c) && canReplaceDigit)) {
                chars[i] = replacement;
                break;
            }
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.ArrayList;
import java.util.List;
import java.util.StringTokenizer;

public class PasswordStrengthModifier {

    public static void main(String[] args) {
        FastReader reader = new FastReader();
        PrintWriter out = new PrintWriter(System.out);

        try {
            int testCases = reader.nextInt();
            while (testCases-- > 0) {
                String input = reader.next();
                if (input == null) break;

                char[] chars = input.toCharArray();

                List<Integer> lowercaseIndices = new ArrayList<>();
                List<Integer> uppercaseIndices = new ArrayList<>();
                List<Integer> digitIndices = new ArrayList<>();

                for (int i = 0; i < chars.length; i++) {
                    char c = chars[i];
                    if (c >= 'a' && c <= 'z') {
                        lowercaseIndices.add(i);
                    } else if (c >= 'A' && c <= 'Z') {
                        uppercaseIndices.add(i);
                    } else if (c >= '0' && c <= '9') {
                        digitIndices.add(i);
                    }
                }

                ensureAllCategoriesPresent(chars, lowercaseIndices, uppercaseIndices, digitIndices);
                out.println(new String(chars));
            }
        } finally {
            out.flush();
        }
    }

    /**
     * Modifies the character array to ensure it contains at least one lowercase letter,
     * one uppercase letter, and one digit. Preserves the original replacement strategy.
     */
    private static void ensureAllCategoriesPresent(char[] chars, List<Integer> lower, List<Integer> upper, List<Integer> digits) {
        // Safety guard for edge cases where string length is insufficient
        if (chars.length < 2) {
            return;
        }

        boolean missingLower = lower.isEmpty();
        boolean missingUpper = upper.isEmpty();
        boolean missingDigit = digits.isEmpty();

        if (missingLower) {
            if (missingUpper) {
                // Missing both uppercase and digit
                chars[0] = 'a';
                chars[1] = 'A';
            } else if (missingDigit) {
                // Missing both uppercase and digit
                chars[0] = 'a';
                chars[1] = '1';
            } else {
                // Has uppercase and digit, need lowercase
                if (upper.size() == 1) {
                    chars[digits.get(0)] = 'a';
                } else {
                    chars[upper.get(0)] = 'a';
                }
            }
        } else if (missingUpper) {
            if (missingDigit) {
                // Missing both lowercase and digit
                chars[0] = 'A';
                chars[1] = '1';
            } else {
                // Has lowercase and digit, need uppercase
                if (lower.size() == 1) {
                    chars[digits.get(0)] = 'A';
                } else {
                    chars[lower.get(0)] = 'A';
                }
            }
        } else if (missingDigit) {
            // Has lowercase and uppercase, need digit
            if (upper.size() == 1) {
                chars[lower.get(0)] = '1';
            } else {
                chars[upper.get(0)] = '1';
            }
        }
    }

    /**
     * A clean, standard-compliant Fast I/O helper. Replaces the original 
     * byte-level custom reader to improve readability and maintainability.
     */
    static class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            String token = next();
            return token == null ? 0 : Integer.parseInt(token);
        }
    }
}

import java.util.Scanner;
import java.util.function.Predicate;

/**
 * Ensures that input strings contain at least one lowercase letter, 
 * one uppercase letter, and one digit.
 */
public class PasswordStrengthEnsurer {

    public static void main(String[] args) {
        // Use try-with-resources for automatic resource management
        try (Scanner scanner = new Scanner(System.in)) {
            if (scanner.hasNextInt()) {
                int testCases = scanner.nextInt();
                for (int i = 0; i < testCases; i++) {
                    String input = scanner.next();
                    System.out.println(processInput(input));
                }
            }
        }
    }

    /**
     * Processes the input string to guarantee it contains at least one 
     * lowercase letter, one uppercase letter, and one digit.
     */
    private static String processInput(String input) {
        int lowerCount = 0;
        int upperCount = 0;
        int digitCount = 0;

        // Count character categories
        for (char c : input.toCharArray()) {
            if (Character.isLowerCase(c)) lowerCount++;
            else if (Character.isUpperCase(c)) upperCount++;
            else if (Character.isDigit(c)) digitCount++;
        }

        // If all categories are already present, return as-is
        if (lowerCount > 0 && upperCount > 0 && digitCount > 0) {
            return input;
        }

        StringBuilder sb = new StringBuilder(input);

        // Handle cases where two or more categories are missing
        if (lowerCount == 0 && upperCount == 0 && digitCount == 0) {
            sb.insert(0, "aA0");
        } else if (lowerCount == 0 && upperCount == 0) {
            sb.insert(0, "aA");
        } else if (lowerCount == 0 && digitCount == 0) {
            sb.insert(0, "a0");
        } else if (upperCount == 0 && digitCount == 0) {
            sb.insert(0, "A0");
        } else {
            // Exactly one category is missing
            char missingChar;
            Predicate<Character> searchPredicate;

            if (lowerCount == 0) {
                missingChar = 'a';
                searchPredicate = Character::isUpperCase;
            } else if (upperCount == 0) {
                missingChar = 'A';
                searchPredicate = Character::isLowerCase;
            } else {
                missingChar = '0';
                searchPredicate = Character::isDigit;
            }

            // Find the index of the single character of the target type
            int insertIndex = -1;
            int foundCount = 0;
            for (int i = 0; i < input.length(); i++) {
                if (searchPredicate.test(input.charAt(i))) {
                    foundCount++;
                    if (foundCount == 1) {
                        insertIndex = i;
                    }
                }
            }

            // Insert at the found index if exactly one exists, otherwise at the beginning
            if (foundCount == 1) {
                sb.insert(insertIndex, missingChar);
            } else {
                sb.insert(0, missingChar);
            }
        }

        return sb.toString();
    }
}

import java.util.Scanner;

/**
 * Processes passwords to ensure they contain at least one lowercase letter,
 * one uppercase letter, and one digit. If a type is missing, replaces the
 * first suitable character to satisfy the requirement.
 */
public class PasswordModifier {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (scanner.hasNextInt()) {
            int testCases = scanner.nextInt();
            while (testCases-- > 0 && scanner.hasNext()) {
                String password = scanner.next();
                System.out.println(modifyPassword(password));
            }
        }
        scanner.close();
    }

    /**
     * Validates and modifies a password to contain lowercase, uppercase, and digit characters.
     *
     * @param password the input string to process
     * @return the validated or modified password
     */
    private static String modifyPassword(String password) {
        char[] chars = password.toCharArray();
        boolean hasLower = false, hasUpper = false, hasDigit = false;
        int lowerCount = 0, upperCount = 0, digitCount = 0;

        // Count character types and check presence
        for (char c : chars) {
            if (isLowercase(c)) {
                hasLower = true;
                lowerCount++;
            } else if (isUppercase(c)) {
                hasUpper = true;
                upperCount++;
            } else if (isDigit(c)) {
                hasDigit = true;
                digitCount++;
            }
        }

        // Already satisfies all requirements
        if (hasLower && hasUpper && hasDigit) {
            return password;
        }

        // Handle missing exactly one character type
        if (!hasDigit) {
            if (lowerCount > 1) replaceFirst(chars, 'a', 'z', '1');
            else replaceFirst(chars, 'A', 'Z', '1');
        } else if (!hasLower) {
            if (upperCount > 1) replaceFirst(chars, 'A', 'Z', 'a');
            else replaceFirst(chars, '0', '9', 'a');
        } else if (!hasUpper) {
            if (lowerCount > 1) replaceFirst(chars, 'a', 'z', 'A');
            else replaceFirst(chars, '0', '9', 'A');
        }
        // Handle missing exactly two character types
        else if (!hasLower && !hasUpper) {
            chars[0] = 'a';
            chars[1] = 'A';
        } else if (!hasLower && !hasDigit) {
            chars[0] = '1';
            chars[1] = 'a';
        } else if (!hasUpper && !hasDigit) {
            chars[0] = '1';
            chars[1] = 'A';
        }

        return new String(chars);
    }

    /**
     * Finds and replaces the first occurrence of a character within the specified range.
     */
    private static void replaceFirst(char[] chars, char min, char max, char replacement) {
        for (int i = 0; i < chars.length; i++) {
            if (chars[i] >= min && chars[i] <= max) {
                chars[i] = replacement;
                break;
            }
        }
    }

    private static boolean isLowercase(char c) { return c >= 'a' && c <= 'z'; }
    private static boolean isUppercase(char c) { return c >= 'A' && c <= 'Z'; }
    private static boolean isDigit(char c) { return c >= '0' && c <= '9'; }
}

import java.io.*;
import java.util.StringTokenizer;

public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        OutputWriter out = new OutputWriter(outputStream);
        Task1 solver = new Task1();
        solver.solve(in, out);
        out.close();
    }

    static class Task1 {
        public void solve(InputReader in, OutputWriter out) {
            int t = in.nextInt();
            while (t-- > 0) {
                String s = in.next();
                int countUpper = 0;
                int countLower = 0;
                int countDigits = 0;

                // Count character categories
                for (int i = 0; i < s.length(); i++) {
                    char c = s.charAt(i);
                    if (Character.isUpperCase(c)) countUpper++;
                    else if (Character.isLowerCase(c)) countLower++;
                    else if (Character.isDigit(c)) countDigits++;
                }

                boolean hasUpper = countUpper > 0;
                boolean hasLower = countLower > 0;
                boolean hasDigit = countDigits > 0;

                // Case 1: Already satisfies all conditions
                if (hasUpper && hasLower && hasDigit) {
                    out.println(s);
                    continue;
                }

                char[] chars = s.toCharArray();
                boolean missingUpper = !hasUpper;
                boolean missingLower = !hasLower;
                boolean missingDigit = !hasDigit;

                // Case 2: Two categories are missing
                if (missingUpper && missingLower) {
                    chars[0] = '1'; // digit
                    chars[1] = 'A'; // upper
                } else if (missingUpper && missingDigit) {
                    chars[0] = 'a'; // lower
                    chars[1] = 'A'; // upper
                } else if (missingLower && missingDigit) {
                    chars[0] = '1'; // digit
                    chars[1] = 'a'; // lower
                } else {
                    // Case 3: Exactly one category is missing
                    char missingChar;
                    if (missingUpper) missingChar = 'A';
                    else if (missingLower) missingChar = 'a';
                    else missingChar = '0'; // digit

                    // Determine which existing category to replace (the one with the highest count)
                    int maxCount = Math.max(countUpper, Math.max(countLower, countDigits));
                    char typeToReplace;
                    if (countUpper == maxCount) typeToReplace = 'A';
                    else if (countLower == maxCount) typeToReplace = 'a';
                    else typeToReplace = '0'; // digit

                    // Replace the first occurrence of the majority type
                    for (int i = 0; i < chars.length; i++) {
                        if (chars[i] == typeToReplace) {
                            chars[i] = missingChar;
                            break;
                        }
                    }
                }
                out.println(new String(chars));
            }
        }
    }

    static class InputReader {
        private final BufferedReader br;
        private StringTokenizer st;

        public InputReader(InputStream inputStream) {
            br = new BufferedReader(new InputStreamReader(inputStream));
        }

        public String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }

    static class OutputWriter {
        private final PrintWriter writer;

        public OutputWriter(OutputStream outputStream) {
            writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(outputStream)));
        }

        public void print(Object... objects) {
            for (int i = 0; i < objects.length; i++) {
                if (i != 0) writer.print(' ');
                writer.print(objects[i]);
            }
        }

        public void println(Object... objects) {
            print(objects);
            writer.println();
        }

        public void close() {
            writer.close();
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

/**
 * Refactored Main class for improved maintainability and code quality.
 * 
 * Improvements made:
 * 1. Removed Magic Numbers: Replaced ASCII values with Character class methods.
 * 2. DRY Principle: Consolidated repetitive replacement logic into a generic loop.
 * 3. Separation of Concerns: Extracted validation logic into a separate method.
 * 4. Cleaned I/O: Simplified FastScanner and removed unused methods.
 * 5. Readability: Used meaningful variable names and structured control flow.
 */
public class Main {

    public static void main(String[] args) {
        FastScanner fs = new FastScanner();

        // Read number of test cases
        String tStr = fs.next();
        if (tStr != null) {
            int T = Integer.parseInt(tStr);
            for (int i = 0; i < T; i++) {
                String s = fs.next();
                if (s != null) {
                    solve(s);
                }
            }
        }
    }

    /**
     * Solves the problem for a single string input.
     * Checks validity and attempts to fix the string by replacing characters
     * to satisfy the requirement of having at least one digit, one uppercase, and one lowercase letter.
     */
    private static void solve(String s) {
        // If the string already satisfies the condition, print it
        if (isValid(s)) {
            System.out.println(s);
            return;
        }

        // Analyze current character types
        boolean hasDigit = false;
        boolean hasUpper = false;
        boolean hasLower = false;

        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (Character.isDigit(c)) hasDigit = true;
            else if (Character.isUpperCase(c)) hasUpper = true;
            else if (Character.isLowerCase(c)) hasLower = true;
        }

        // Construct the string of missing characters needed to satisfy the condition
        // Order: Digit ('1'), Upper ('A'), Lower ('a')
        StringBuilder needed = new StringBuilder();
        if (!hasDigit) needed.append("1");
        if (!hasUpper) needed.append("A");
        if (!hasLower) needed.append("a");

        int missingCount = needed.length();
        int len = s.length();

        // If 2 types are missing (e.g., only digits present), we need to replace 2 characters
        if (missingCount == 2) {
            String replacement = needed.toString();
            // Iterate through the string to find a valid 2-char replacement
            for (int i = 0; i <= len - 2; i++) {
                StringBuilder sb = new StringBuilder(s);
                sb.replace(i, i + 2, replacement);
                if (isValid(sb.toString())) {
                    System.out.println(sb.toString());
                    return;
                }
            }
        } 
        // If 1 type is missing, we need to replace 1 character
        else if (missingCount == 1) {
            String replacement = needed.toString();
            // Iterate through the string to find a valid 1-char replacement
            for (int i = 0; i < len; i++) {
                StringBuilder sb = new StringBuilder(s);
                sb.replace(i, i + 1, replacement);
                if (isValid(sb.toString())) {
                    System.out.println(sb.toString());
                    return;
                }
            }
        }
        // If missingCount > 2 (e.g., empty string), no single replacement can fix it.
    }

    /**
     * Checks if the string contains at least one digit, one uppercase letter, and one lowercase letter.
     */
    private static boolean isValid(String s) {
        boolean hasDigit = false;
        boolean hasUpper = false;
        boolean hasLower = false;

        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (Character.isDigit(c)) hasDigit = true;
            else if (Character.isUpperCase(c)) hasUpper = true;
            else if (Character.isLowerCase(c)) hasLower = true;
        }

        return hasDigit && hasUpper && hasLower;
    }

    /**
     * FastScanner helper class for efficient input reading.
     */
    static class FastScanner {
        BufferedReader br;
        StringTokenizer st;

        public FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    e.printStackTrace();
                    return null;
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            String s = next();
            return s == null ? 0 : Integer.parseInt(s);
        }
    }
}

import java.util.Scanner;

public class CF1051A {
    // Constants for readability and maintainability
    private static final char LOWER_CHAR = 'a';
    private static final char UPPER_CHAR = 'A';
    private static final char DIGIT_CHAR = '8';

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        // Check if input exists to prevent exceptions on empty input streams
        if (scanner.hasNextInt()) {
            int t = scanner.nextInt();
            while (t-- > 0) {
                String str = scanner.next();
                System.out.println(processPassword(str));
            }
        }
        scanner.close();
    }

    /**
     * Processes the input string to ensure it meets password requirements:
     * at least one lowercase, one uppercase, and one digit.
     * Modifies the string in place if necessary.
     *
     * @param str The input string to process
     * @return The modified string or the original if valid
     */
    private static String processPassword(String str) {
        int countL = 0;
        int countU = 0;
        int countD = 0;

        // Count occurrences of each character type
        for (int i = 0; i < str.length(); i++) {
            char c = str.charAt(i);
            if (Character.isLowerCase(c)) {
                countL++;
            } else if (Character.isUpperCase(c)) {
                countU++;
            } else if (Character.isDigit(c)) {
                countD++;
            }
        }

        // Case 1: Password is already strong (contains all types)
        if (countL > 0 && countU > 0 && countD > 0) {
            return str;
        }

        char[] arr = str.toCharArray();

        // Case 2: Exactly one type is present (Two types missing)
        // Logic: Overwrite the first two characters to introduce the missing types.
        // Note: This assumes string length >= 2. If length < 2, this may throw IndexOutOfBoundsException,
        // preserving the behavior of the original code.
        if (countU > 0 && countL == 0 && countD == 0) {
            // Only Uppercase present. Need Lower ('a') and Digit ('8').
            arr[0] = LOWER_CHAR;
            arr[1] = DIGIT_CHAR;
        } else if (countD > 0 && countL == 0 && countU == 0) {
            // Only Digit present. Need Lower ('a') and Upper ('A').
            arr[0] = LOWER_CHAR;
            arr[1] = UPPER_CHAR;
        } else if (countL > 0 && countU == 0 && countD == 0) {
            // Only Lowercase present. Need Digit ('8') and Upper ('A').
            arr[0] = DIGIT_CHAR;
            arr[1] = UPPER_CHAR;
        }

        // Case 3: Exactly two types are present (One type missing)
        else if (countL == 0) {
            // Missing Lowercase. Need to replace a character with 'a'.
            int replaceIndex = findReplacementIndex(arr, countL, countU, countD, LOWER_CHAR);
            arr[replaceIndex] = LOWER_CHAR;
        } else if (countU == 0) {
            // Missing Uppercase. Need to replace a character with 'A'.
            int replaceIndex = findReplacementIndex(arr, countL, countU, countD, UPPER_CHAR);
            arr[replaceIndex] = UPPER_CHAR;
        } else if (countD == 0) {
            // Missing Digit. Need to replace a character with '8'.
            int replaceIndex = findReplacementIndex(arr, countL, countU, countD, DIGIT_CHAR);
            arr[replaceIndex] = DIGIT_CHAR;
        }

        return new String(arr);
    }

    /**
     * Finds the index of a character to replace in order to satisfy the password requirements
     * without reducing the count of any existing type to zero (if count is 1).
     *
     * @param arr The character array of the string
     * @param countL Current count of lowercase characters
     * @param countU Current count of uppercase characters
     * @param countD Current count of digit characters
     * @param targetChar The character type we are trying to add
     * @return The index of the character to replace
     */
    private static int findReplacementIndex(char[] arr, int countL, int countU, int countD, char targetChar) {
        int replaceIndex = -1;

        // Determine which types are critical (count == 1) to avoid destroying them.
        // The logic prioritizes preserving specific types based on the original code's structure.

        if (targetChar == LOWER_CHAR) {
            // We are adding a Lowercase.
            // Priority 1: If Digit count is 1, we must preserve it. Find first non-digit.
            if (countD == 1) {
                replaceIndex = findFirstNonDigit(arr);
            } 
            // Priority 2: If Uppercase count is 1, we must preserve it. Find first non-uppercase.
            else if (countU == 1) {
                replaceIndex = findFirstNonUpper(arr);
            }
        } 
        else if (targetChar == UPPER_CHAR) {
            // We are adding an Uppercase.
            // Priority 1: If Digit count is 1, preserve it. Find first non-digit.
            if (countD == 1) {
                replaceIndex = findFirstNonDigit(arr);
            } 
            // Priority 2: If Lowercase count is 1, preserve it. Find first non-lowercase.
            else if (countL == 1) {
                replaceIndex = findFirstNonLower(arr);
            }
        } 
        else if (targetChar == DIGIT_CHAR) {
            // We are adding a Digit.
            // Priority 1: If Uppercase count is 1, preserve it. Find first non-uppercase.
            if (countU == 1) {
                replaceIndex = findFirstNonUpper(arr);
            } 
            // Priority 2: If Lowercase count is 1, preserve it. Find first non-lowercase.
            else if (countL == 1) {
                replaceIndex = findFirstNonLower(arr);
            }
        }

        // Fallback to index 0 if no specific safe index was found (e.g., all counts > 1 or loop finished)
        if (replaceIndex == -1) {
            replaceIndex = 0;
        }

        return replaceIndex;
    }

    private static int findFirstNonDigit(char[] arr) {
        for (int i = 0; i < arr.length; i++) {
            if (!Character.isDigit(arr[i])) {
                return i;
            }
        }
        return -1;
    }

    private static int findFirstNonUpper(char[] arr) {
        for (int i = 0; i < arr.length; i++) {
            if (!Character.isUpperCase(arr[i])) {
                return i;
            }
        }
        return -1;
    }

    private static int findFirstNonLower(char[] arr) {
        for (int i = 0; i < arr.length; i++) {
            if (!Character.isLowerCase(arr[i])) {
                return i;
            }
        }
        return -1;
    }
}

import java.util.Scanner;

public class VasyaPassword {

    public static void main(String[] args) {
        // Use try-with-resources to ensure the Scanner is closed properly
        try (Scanner scanner = new Scanner(System.in)) {
            if (scanner.hasNextInt()) {
                int testCases = scanner.nextInt();
                scanner.nextLine(); // Consume the newline character after the integer

                for (int i = 0; i < testCases; i++) {
                    String password = scanner.nextLine();
                    System.out.println(fixPassword(password));
                }
            }
        }
    }

    /**
     * Analyzes the password string and ensures it contains at least one lowercase letter,
     * one uppercase letter, and one digit. If a required character type is missing,
     * it attempts to replace an existing character to satisfy the condition.
     *
     * @param s The input password string.
     * @return The modified password string.
     */
    private static String fixPassword(String s) {
        if (s == null || s.isEmpty()) {
            return s;
        }

        char[] chars = s.toCharArray();
        int length = chars.length;

        // Flags to track the presence of character types
        boolean hasLower = false;
        boolean hasUpper = false;
        boolean hasDigit = false;

        // Indices of the last occurrence of each character type found in the first pass
        int lastLowerIndex = -1;
        int lastUpperIndex = -1;
        int lastDigitIndex = -1;

        // First pass: Identify character types and record the index of their last occurrence
        for (int i = 0; i < length; i++) {
            char c = chars[i];
            if (Character.isLowerCase(c)) {
                hasLower = true;
                lastLowerIndex = i;
            } else if (Character.isUpperCase(c)) {
                hasUpper = true;
                lastUpperIndex = i;
            } else if (Character.isDigit(c)) {
                hasDigit = true;
                lastDigitIndex = i;
            }
        }

        // Indices to be replaced (initialized to -1)
        int replaceLowerIndex = -1;
        int replaceUpperIndex = -1;
        int replaceDigitIndex = -1;

        // Second pass: Find suitable indices to replace if types are missing.
        // The logic attempts to find an index that is not the specific 'last' index 
        // of the other required types, preserving the instances found in the first pass.
        for (int i = 0; i < length; i++) {
            // If we need a lowercase letter and haven't found a replacement index yet
            if (!hasLower && replaceLowerIndex == -1) {
                // Avoid overwriting the specific Upper or Digit instances found in pass 1
                if (i != lastUpperIndex && i != lastDigitIndex) {
                    replaceLowerIndex = i;
                }
            }
            // If we need an uppercase letter
            else if (!hasUpper && replaceUpperIndex == -1) {
                // Avoid overwriting the specific Lower or Digit instances
                if (i != lastLowerIndex && i != lastDigitIndex) {
                    replaceUpperIndex = i;
                }
            }
            // If we need a digit
            else if (!hasDigit && replaceDigitIndex == -1) {
                // Avoid overwriting the specific Lower or Upper instances
                if (i != lastLowerIndex && i != lastUpperIndex) {
                    replaceDigitIndex = i;
                }
            }
        }

        // Apply replacements
        // We check if the replacement index is valid (not -1) to prevent ArrayIndexOutOfBoundsException
        if (!hasLower && replaceLowerIndex != -1) {
            chars[replaceLowerIndex] = 'a'; // Character.toLowerCase('a')
        }
        if (!hasUpper && replaceUpperIndex != -1) {
            chars[replaceUpperIndex] = 'A'; // Character.toUpperCase('a')
        }
        if (!hasDigit && replaceDigitIndex != -1) {
            chars[replaceDigitIndex] = '1';
        }

        return new String(chars);
    }
}

import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        // Using try-with-resources ensures the Scanner is properly closed
        try (Scanner scanner = new Scanner(System.in)) {
            if (scanner.hasNextInt()) {
                int testCases = scanner.nextInt();
                while (testCases-- > 0 && scanner.hasNext()) {
                    String input = scanner.next();
                    System.out.println(findValidPassword(input));
                }
            }
        }
    }

    /**
     * Attempts to modify the input string to satisfy the password requirements:
     * - At least one uppercase letter
     * - At least one lowercase letter
     * - At least one digit
     * 
     * Priority:
     * 1. Return original string if already valid.
     * 2. Try changing exactly one character.
     * 3. Try changing exactly two adjacent characters.
     */
    private static String findValidPassword(String s) {
        char[] chars = s.toCharArray();

        // Check if the string already meets all requirements
        if (hasRequiredTypes(chars)) {
            return s;
        }

        int n = chars.length;

        // Strategy 1: Try changing exactly one character
        for (int i = 0; i < n; i++) {
            char original = chars[i];
            char[] replacements = {'1', 'a', 'A'};
            for (char rep : replacements) {
                chars[i] = rep;
                if (hasRequiredTypes(chars)) {
                    return new String(chars);
                }
            }
            chars[i] = original; // Backtrack to restore original character
        }

        // Strategy 2: Try changing exactly two adjacent characters
        for (int i = 0; i < n - 1; i++) {
            char orig1 = chars[i];
            char orig2 = chars[i + 1];
            char[][] pairs = {
                {'5', 'a'},
                {'1', 'A'},
                {'A', 'a'}
            };
            for (char[] pair : pairs) {
                chars[i] = pair[0];
                chars[i + 1] = pair[1];
                if (hasRequiredTypes(chars)) {
                    return new String(chars);
                }
            }
            chars[i] = orig1;
            chars[i + 1] = orig2; // Backtrack to restore original characters
        }

        // Fallback: Return original if no valid modification is found
        // (Problem constraints typically guarantee a solution exists)
        return s;
    }

    /**
     * Checks if the character array contains at least one uppercase, 
     * one lowercase, and one digit.
     */
    private static boolean hasRequiredTypes(char[] arr) {
        boolean hasUpper = false, hasLower = false, hasDigit = false;
        for (char c : arr) {
            if (Character.isUpperCase(c)) hasUpper = true;
            else if (Character.isLowerCase(c)) hasLower = true;
            else if (Character.isDigit(c)) hasDigit = true;

            // Early exit if all conditions are met
            if (hasUpper && hasLower && hasDigit) {
                return true;
            }
        }
        return false;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

public class PasswordStrengthModifier {

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner();
        int testCases = scanner.nextInt();

        for (int i = 0; i < testCases; i++) {
            String input = scanner.next();
            System.out.println(modifyStringForStrength(input));
        }
    }

    /**
     * Modifies the input string to ensure it contains at least one lowercase letter,
     * one uppercase letter, and one digit, following specific replacement rules.
     */
    private static String modifyStringForStrength(String s) {
        char[] chars = s.toCharArray();
        boolean hasLower = false, hasUpper = false, hasDigit = false;
        int lowerCount = 0, upperCount = 0, digitCount = 0;
        int firstLower = -1, firstUpper = -1, firstDigit = -1;

        // Single pass to gather counts and first occurrence indices
        for (int i = 0; i < chars.length; i++) {
            char c = chars[i];
            if (Character.isLowerCase(c)) {
                hasLower = true;
                lowerCount++;
                if (firstLower == -1) firstLower = i;
            } else if (Character.isUpperCase(c)) {
                hasUpper = true;
                upperCount++;
                if (firstUpper == -1) firstUpper = i;
            } else if (Character.isDigit(c)) {
                hasDigit = true;
                digitCount++;
                if (firstDigit == -1) firstDigit = i;
            }
        }

        // If already contains all three types, return original string
        if (hasLower && hasUpper && hasDigit) {
            return s;
        }

        // Apply modifications based on missing character types
        if (!hasLower && hasUpper && hasDigit) {
            if (digitCount >= upperCount && firstDigit != -1) {
                chars[firstDigit] = 'a';
            } else if (firstUpper != -1) {
                chars[firstUpper] = 'a';
            }
        } else if (hasLower && !hasUpper && hasDigit) {
            if (digitCount >= lowerCount && firstDigit != -1) {
                chars[firstDigit] = 'A';
            } else if (firstLower != -1) {
                chars[firstLower] = 'A';
            }
        } else if (hasLower && hasUpper && !hasDigit) {
            if (lowerCount >= upperCount && firstLower != -1) {
                chars[firstLower] = '1';
            } else if (firstUpper != -1) {
                chars[firstUpper] = '1';
            }
        } else if (!hasLower && !hasUpper && hasDigit) {
            chars[0] = 'a';
            chars[1] = 'A';
        } else if (!hasLower && hasUpper && !hasDigit) {
            chars[0] = '1';
            chars[1] = 'a';
        } else if (hasLower && !hasUpper && !hasDigit) {
            chars[0] = 'A';
            chars[1] = '1';
        }

        return new String(chars);
    }

    /**
     * Lightweight, maintainable I/O helper using BufferedReader and StringTokenizer.
     * Replaces the original bloated and buggy InputReader.
     */
    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.BufferedReader; 
import java.io.IOException; 
import java.io.InputStreamReader; 
import java.util.StringTokenizer; 

/**
 * PasswordFixer refactors the original logic to ensure robustness and maintainability.
 * It fixes potential IndexOutOfBoundsException errors and simplifies the replacement strategy
 * to a deterministic "safe replacement" logic (preserving character type counts > 1).
 */
public class PasswordFixer 
{ 
    public static void main(String[] args) throws IOException 
    {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in)); 

        // Read the number of test cases, handling potential empty lines or null input
        String line = br.readLine();
        while (line != null && line.trim().isEmpty()) {
            line = br.readLine();
        }

        if (line == null) return;

        StringTokenizer st = new StringTokenizer(line); 
        if (!st.hasMoreTokens()) return;

        int n = Integer.parseInt(st.nextToken()); 

        for (int i = 0; i < n; i++) 
        { 
            String pwdStr = br.readLine();
            // Handle end of input or empty lines gracefully
            if (pwdStr == null) break;

            char[] password = pwdStr.toCharArray(); 
            fixPassword(password); 
            System.out.println(new String(password)); 
        } 
    } 

    /**
     * Analyzes the password and modifies it in-place to satisfy requirements:
     * 1. Contains at least one lowercase letter.
     * 2. Contains at least one uppercase letter.
     * 3. Contains at least one digit.
     * 
     * The strategy minimizes changes by replacing characters that belong to 
     * character classes with a count > 1, ensuring no other required class is lost.
     */
    private static void fixPassword(char[] password) 
    {
        if (password == null || password.length == 0) return;

        int lowerCount = 0;
        int upperCount = 0;
        int digitCount = 0;

        // Count occurrences of each character type
        for (char c : password) 
        {
            if (Character.isLowerCase(c)) lowerCount++;
            else if (Character.isUpperCase(c)) upperCount++;
            else if (Character.isDigit(c)) digitCount++;
        }

        boolean missingLower = (lowerCount == 0);
        boolean missingUpper = (upperCount == 0);
        boolean missingDigit = (digitCount == 0);

        int missingCount = 0;
        if (missingLower) missingCount++;
        if (missingUpper) missingCount++;
        if (missingDigit) missingCount++;

        // If all types are present, no fix needed
        if (missingCount == 0) return;

        if (missingCount == 1) 
        {
            // Only one type is missing. We need to change exactly one character.
            char replacementChar = missingLower ? 'a' : (missingUpper ? 'A' : '1');
            int replaceIndex = -1;

            // Find a "safe" character to replace.
            // A character is safe to replace if its current type count is > 1.
            // This ensures that changing it won't result in a new missing type.
            for (int i = 0; i < password.length; i++) 
            {
                char c = password[i];
                boolean isLower = Character.isLowerCase(c);
                boolean isUpper = Character.isUpperCase(c);
                boolean isDigit = Character.isDigit(c);

                boolean isSafe = false;
                if (isLower && lowerCount > 1) isSafe = true;
                if (isUpper && upperCount > 1) isSafe = true;
                if (isDigit && digitCount > 1) isSafe = true;

                if (isSafe) 
                {
                    replaceIndex = i;
                    break;
                }
            }

            // Fallback: If no safe character exists (e.g., string is "A1", missing Lower),
            // we must change a character even if it risks dropping a count to 0.
            // We pick the first character.
            if (replaceIndex == -1 && password.length > 0) 
            {
                replaceIndex = 0;
            }

            if (replaceIndex != -1) 
            {
                password[replaceIndex] = replacementChar;
            }
        } 
        else if (missingCount == 2) 
        {
            // Two types are missing. We have only one type present.
            // We need to change two characters to introduce the missing types.
            // We prioritize changing characters of the present type.

            char[] charsToInsert = new char[2];
            int idx = 0;
            if (missingLower) charsToInsert[idx++] = 'a';
            if (missingUpper) charsToInsert[idx++] = 'A';
            if (missingDigit) charsToInsert[idx++] = '1';

            // Replace the first two characters if they exist.
            // This mirrors the aggressive replacement strategy of the original code
            // but adds necessary bounds checking.
            if (password.length > 0) password[0] = charsToInsert[0];
            if (password.length > 1) password[1] = charsToInsert[1];
        } 
        else if (missingCount == 3) 
        {
            // All three types are missing (e.g., string of symbols/spaces).
            // We attempt to introduce all three if length permits.
            if (password.length >= 3) 
            {
                password[0] = 'a';
                password[1] = 'A';
                password[2] = '1';
            } 
            else if (password.length == 2) 
            {
                password[0] = 'a';
                password[1] = 'A';
            } 
            else if (password.length == 1) 
            {
                password[0] = 'a';
            }
        }
    } 
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;

public class Solution {
    public static void main(String[] args) throws IOException {
        // Use standard, maintainable I/O instead of custom fast I/O boilerplate
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter out = new PrintWriter(System.out);

        String line = reader.readLine();
        if (line != null && !line.trim().isEmpty()) {
            int t = Integer.parseInt(line.trim());
            while (t-- > 0) {
                String input = reader.readLine();
                if (input != null) {
                    out.println(processPassword(input.trim()));
                }
            }
        }

        out.flush();
        out.close();
    }

    /**
     * Processes the input string to ensure it contains at least one lowercase letter,
     * one uppercase letter, and one digit. Applies specific replacement rules if types are missing.
     */
    private static String processPassword(String str) {
        int lowerCount = 0;
        int upperCount = 0;
        int digitCount = 0;

        // Count character types using standard library methods
        for (char c : str.toCharArray()) {
            if (Character.isLowerCase(c)) {
                lowerCount++;
            } else if (Character.isUpperCase(c)) {
                upperCount++;
            } else if (Character.isDigit(c)) {
                digitCount++;
            }
        }

        // If all character types are already present, return unchanged
        if (lowerCount > 0 && upperCount > 0 && digitCount > 0) {
            return str;
        }

        char[] chars = str.toCharArray();
        int n = chars.length;

        boolean missingLower = lowerCount == 0;
        boolean missingUpper = upperCount == 0;
        boolean missingDigit = digitCount == 0;

        // Case 1: Two types missing -> replace the first two characters
        if (missingLower && missingUpper) {
            chars[0] = 'a';
            chars[1] = '0';
        } else if (missingLower && missingDigit) {
            chars[0] = 'a';
            chars[1] = 'A';
        } else if (missingUpper && missingDigit) {
            chars[0] = 'A';
            chars[1] = '0';
        }
        // Case 2: One type missing -> replace the first occurrence of the most frequent type
        else if (missingDigit) {
            if (lowerCount > 1) replaceFirstOfType(chars, n, Character::isLowerCase, '0');
            else if (upperCount > 1) replaceFirstOfType(chars, n, Character::isUpperCase, '0');
        } else if (missingUpper) {
            if (lowerCount > 1) replaceFirstOfType(chars, n, Character::isLowerCase, 'A');
            else if (digitCount > 1) replaceFirstOfType(chars, n, Character::isDigit, 'A');
        } else if (missingLower) {
            if (upperCount > 1) replaceFirstOfType(chars, n, Character::isUpperCase, 'a');
            else if (digitCount > 1) replaceFirstOfType(chars, n, Character::isDigit, 'a');
        }

        return new String(chars);
    }

    /**
     * Replaces the first character matching the given type checker with the replacement character.
     */
    private static void replaceFirstOfType(char[] chars, int n, java.util.function.Predicate<Character> checker, char replacement) {
        for (int i = 0; i < n; i++) {
            if (checker.test(chars[i])) {
                chars[i] = replacement;
                break;
            }
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Refactored Strong Password Solver.
 * 
 * Improvements made:
 * 1. Naming: Renamed classes and variables to be descriptive (e.g., StrongPasswordSolver, input, digitCount).
 * 2. Structure: Moved InputReader and MathUtils to static nested classes for better encapsulation.
 * 3. Logic Extraction: Extracted the complex loop logic for inserting missing characters into a generic method.
 * 4. Robustness: Added bounds checking for substring operations to prevent IndexOutOfBoundsException.
 * 5. Efficiency: Used StringBuilder for string construction in loops instead of repeated print calls.
 * 6. Maintainability: Removed dead code and simplified the flow of control.
 */
public class StrongPasswordSolver {

    private static final long MOD = 1_000_000_007L;

    public static void main(String[] args) {
        StrongPasswordSolver solver = new StrongPasswordSolver();
        solver.run();
    }

    public void run() {
        InputReader in = new InputReader();
        PrintWriter out = new PrintWriter(System.out);

        try {
            // Read number of test cases
            String tStr = in.next();
            if (tStr != null) {
                int t = Integer.parseInt(tStr);
                while (t-- > 0) {
                    solve(in, out);
                }
            }
        } catch (Exception e) {
            e.printStackTrace();
        } finally {
            out.flush();
            out.close();
        }
    }

    private void solve(InputReader in, PrintWriter out) {
        String input = in.next();
        if (input == null) return;

        String result = processPassword(input);
        out.println(result);
    }

    private String processPassword(String input) {
        int n = input.length();
        int digitCount = 0;
        int lowerCount = 0;
        int upperCount = 0;

        // Count character types
        for (int i = 0; i < n; i++) {
            char c = input.charAt(i);
            if (Character.isDigit(c)) {
                digitCount++;
            } else if (Character.isLowerCase(c)) {
                lowerCount++;
            } else if (Character.isUpperCase(c)) {
                upperCount++;
            }
        }

        // Case 1: All types present
        if (digitCount > 0 && lowerCount > 0 && upperCount > 0) {
            return input;
        }

        // Helper for substring logic to handle short strings safely
        // Original code used st.substring(2) which throws if length < 2.
        String suffix = (n > 2) ? input.substring(2) : "";

        // Case 2: Two types missing
        // Logic preserved from original code
        if (digitCount == 0 && lowerCount == 0) {
            return "1a" + suffix;
        }
        if (digitCount == 0 && upperCount == 0) {
            return "1A" + suffix;
        }
        if (lowerCount == 0 && upperCount == 0) {
            return "aA" + suffix;
        }

        // Case 3: One type missing
        // Logic extracted to a generic method for maintainability
        if (lowerCount == 0) {
            // Missing lowercase. Insert 'a'.
            // Priority: Check Digit, then Upper.
            return insertMissingChar(input, 'a', CharType.DIGIT, CharType.UPPER);
        }
        if (digitCount == 0) {
            // Missing digit. Insert '1'.
            // Priority: Check Lower, then Upper.
            return insertMissingChar(input, '1', CharType.LOWER, CharType.UPPER);
        }
        if (upperCount == 0) {
            // Missing upper. Insert 'A'.
            // Priority: Check Digit, then Lower.
            return insertMissingChar(input, 'A', CharType.DIGIT, CharType.LOWER);
        }

        return input;
    }

    private enum CharType {
        DIGIT, LOWER, UPPER
    }

    /**
     * Inserts a missing character type into the string based on priority logic.
     * This method replicates the complex loop logic found in the original solve() method.
     * 
     * Logic:
     * 1. If char matches priorityType1 and not found yet -> print char, mark found.
     * 2. Else if char matches priorityType2 and not found yet -> print char, mark found.
     * 3. Else if missing char not inserted yet -> insert missing char, mark inserted.
     * 4. Else -> print char.
     */
    private String insertMissingChar(String input, char missingChar, CharType priority1, CharType priority2) {
        boolean foundP1 = false;
        boolean foundP2 = false;
        boolean foundMissing = false;
        StringBuilder sb = new StringBuilder();

        for (int i = 0; i < input.length(); i++) {
            char c = input.charAt(i);
            CharType type = getType(c);

            // Priority 1 check
            if (type == priority1 && !foundP1) {
                sb.append(c);
                foundP1 = true;
            } 
            // Priority 2 check
            else if (type == priority2 && !foundP2) {
                sb.append(c);
                foundP2 = true;
            } 
            // Insert missing char if not yet inserted
            else if (!foundMissing) {
                sb.append(missingChar);
                foundMissing = true;
            } 
            // Otherwise print original character
            else {
                sb.append(c);
            }
        }
        return sb.toString();
    }

    private CharType getType(char c) {
        if (Character.isDigit(c)) return CharType.DIGIT;
        if (Character.isLowerCase(c)) return CharType.LOWER;
        if (Character.isUpperCase(c)) return CharType.UPPER;
        return CharType.LOWER; // Default fallback
    }

    // --- Static Nested Classes ---

    /**
     * Utility class for mathematical operations used in competitive programming.
     */
    static class MathUtils {
        long gcd(long a, long b) { return (b == 0) ? a : gcd(b, a % b); }
        int gcd(int a, int b) { return (b == 0) ? a : gcd(b, a % b); }

        int bitcount(long n) { return (n == 0) ? 0 : (1 + bitcount(n & (n - 1))); }

        long mul(long a, long b) {
            if (a >= MOD) a %= MOD;
            if (b >= MOD) b %= MOD;
            a *= b;
            if (a >= MOD) a %= MOD;
            return a;
        }

        long modPow(long a, long p) {
            long o = 1;
            while (p > 0) {
                if ((p & 1) == 1) o = mul(o, a);
                a = mul(a, a);
                p >>= 1;
            }
            return o;
        }

        long add(long a, long b) {
            if (a >= MOD) a %= MOD;
            if (b >= MOD) b %= MOD;
            if (b < 0) b += MOD;
            a += b;
            if (a >= MOD) a -= MOD;
            return a;
        }
    }

    /**
     * Fast Input Reader for competitive programming.
     */
    static class InputReader {
        BufferedReader br;
        StringTokenizer st;

        public InputReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        public InputReader(String s) throws Exception {
            br = new BufferedReader(new FileReader(s));
        }

        String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    e.printStackTrace();
                    return null;
                }
            }
            return st.nextToken();
        }

        String nextLine() {
            String str = "";
            try {
                str = br.readLine();
            } catch (IOException e) {
                e.printStackTrace();
            }
            return str;
        }

        int nextInt() {
            String s = next();
            return (s == null) ? 0 : Integer.parseInt(s);
        }

        long nextLong() {
            String s = next();
            return (s == null) ? 0L : Long.parseLong(s);
        }

        double nextDouble() {
            String s = next();
            return (s == null) ? 0.0 : Double.parseDouble(s);
        }
    }
}

import java.util.Scanner;

/**
 * Refactored version of the cff class.
 * This program reads a number of test cases and for each case, processes a string
 * to ensure it contains at least one lowercase letter, one uppercase letter,
 * and one digit.
 */
public class Main {

    public static void main(String[] args) {
        // Use try-with-resources for automatic resource management of the Scanner
        try (Scanner scanner = new Scanner(System.in)) {
            if (scanner.hasNextInt()) {
                int testCases = scanner.nextInt();

                // Loop through all test cases
                while (testCases > 0) {
                    if (scanner.hasNext()) {
                        String data = scanner.next();
                        System.out.println(processString(data));
                    }
                    testCases--;
                }
            }
        }
    }

    /**
     * Processes the input string to ensure it meets the criteria:
     * 1. Contains at least one lowercase letter.
     * 2. Contains at least one uppercase letter.
     * 3. Contains at least one digit.
     *
     * The algorithm converts redundant characters (where count > 1) to missing types
     * based on specific priority rules derived from the original logic.
     *
     * @param data The input string to process
     * @return The modified string satisfying the criteria
     */
    private static String processString(String data) {
        if (data == null || data.isEmpty()) {
            return data;
        }

        // Counters for character frequencies
        int lowerCount = 0;
        int upperCount = 0;
        int digitCount = 0;

        // Flags to track presence of character types
        boolean hasLower = false;
        boolean hasUpper = false;
        boolean hasDigit = false;

        // First pass: Count characters and set flags
        for (int i = 0; i < data.length(); i++) {
            char c = data.charAt(i);
            if (Character.isLowerCase(c)) {
                lowerCount++;
                hasLower = true;
            } else if (Character.isUpperCase(c)) {
                upperCount++;
                hasUpper = true;
            } else if (Character.isDigit(c)) {
                digitCount++;
                hasDigit = true;
            }
        }

        // Convert to char array for in-place modification
        char[] chars = data.toCharArray();

        // Second pass: Modify characters to satisfy missing requirements
        for (int i = 0; i < chars.length; i++) {
            // Optimization: If all requirements are met, stop processing
            // This mirrors the original loop condition: set_flag[0]+set_flag[1]+set_flag[2] != 3
            if (hasLower && hasUpper && hasDigit) {
                break;
            }

            char currentChar = chars[i];

            // Logic mirrors the original code's priority rules.
            // Original magic numbers: -3 (Lower), -1 (Upper), -2 (Digit)

            if (Character.isUpperCase(currentChar) && upperCount > 1) {
                // If we have extra uppercase letters
                // Priority 1: Convert to Digit if missing
                if (!hasDigit) {
                    chars[i] = '0';
                    upperCount--;
                    digitCount++;
                    hasDigit = true;
                } 
                // Priority 2: Convert to Lowercase if missing
                else if (!hasLower) {
                    chars[i] = 'a';
                    upperCount--;
                    lowerCount++;
                    hasLower = true;
                }
            } 
            else if (Character.isDigit(currentChar) && digitCount > 1) {
                // If we have extra digits
                // Priority 1: Convert to Lowercase if missing
                if (!hasLower) {
                    chars[i] = 'a';
                    digitCount--;
                    lowerCount++;
                    hasLower = true;
                } 
                // Priority 2: Convert to Uppercase if missing
                else if (!hasUpper) {
                    chars[i] = 'A';
                    digitCount--;
                    upperCount++;
                    hasUpper = true;
                }
            } 
            else if (Character.isLowerCase(currentChar) && lowerCount > 1) {
                // If we have extra lowercase letters
                // Priority 1: Convert to Uppercase if missing
                if (!hasUpper) {
                    chars[i] = 'A';
                    lowerCount--;
                    upperCount++;
                    hasUpper = true;
                } 
                // Priority 2: Convert to Digit if missing
                else if (!hasDigit) {
                    chars[i] = '0';
                    lowerCount--;
                    digitCount++;
                    hasDigit = true;
                }
            }
        }

        return new String(chars);
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;

public class VAP {

    public static void main(String[] args) throws IOException {
        // Use try-with-resources to ensure the BufferedReader is closed automatically
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(System.in))) {
            String line = reader.readLine();
            if (line == null || line.trim().isEmpty()) {
                return;
            }

            int testCases;
            try {
                testCases = Integer.parseInt(line.trim());
            } catch (NumberFormatException e) {
                System.err.println("Invalid number of test cases: " + line);
                return;
            }

            // StringBuilder is preferred over StringBuffer for single-threaded scenarios
            StringBuilder output = new StringBuilder();
            while (testCases-- > 0) {
                String input = reader.readLine();
                if (input == null) {
                    break;
                }
                output.append(processAndFixString(input)).append('\n');
            }
            System.out.print(output);
        }
    }

    /**
     * Analyzes the input string for character types and returns the string 
     * if it already contains at least one lowercase letter, one uppercase letter, and one digit.
     * Otherwise, it fixes the missing character types and returns the modified string.
     */
    private static String processAndFixString(String input) {
        int lowercaseCount = 0;
        int uppercaseCount = 0;
        int digitCount = 0;

        for (char c : input.toCharArray()) {
            if (Character.isLowerCase(c)) {
                lowercaseCount++;
            } else if (Character.isUpperCase(c)) {
                uppercaseCount++;
            } else if (Character.isDigit(c)) {
                digitCount++;
            }
        }

        // If all three character types are present, return the original string
        if (lowercaseCount > 0 && uppercaseCount > 0 && digitCount > 0) {
            return input;
        }

        return fixMissingCharacterTypes(input, lowercaseCount, uppercaseCount, digitCount);
    }

    /**
     * Modifies the string to ensure it contains lowercase, uppercase, and digit characters.
     * Preserves the original length by replacing existing characters when possible.
     */
    private static String fixMissingCharacterTypes(String s, int lowerCount, int upperCount, int digitCount) {
        char[] chars = s.toCharArray();
        boolean missingLower = lowerCount == 0;
        boolean missingUpper = upperCount == 0;
        boolean missingDigit = digitCount == 0;

        // Case 1: Two character types are missing
        if (missingLower && missingUpper) {
            if (chars.length > 0) chars[0] = 'D';
            if (chars.length > 1) chars[1] = '1';
        } else if (missingLower && missingDigit) {
            if (chars.length > 0) chars[0] = 'D';
            if (chars.length > 1) chars[1] = 'a';
        } else if (missingUpper && missingDigit) {
            if (chars.length > 0) chars[0] = 'a';
            if (chars.length > 1) chars[1] = '1';
        }
        // Case 2: Only one character type is missing
        else {
            char replacement = missingLower ? 'a' : (missingUpper ? 'A' : '1');

            for (int i = 0; i < chars.length; i++) {
                char c = chars[i];
                boolean isLower = Character.isLowerCase(c);
                boolean isUpper = Character.isUpperCase(c);
                boolean isDigit = Character.isDigit(c);

                boolean shouldReplace = false;
                if (isLower && lowerCount > 1 && (missingUpper || missingDigit)) {
                    shouldReplace = true;
                } else if (isUpper && upperCount > 1 && (missingLower || missingDigit)) {
                    shouldReplace = true;
                } else if (isDigit && digitCount > 1 && (missingLower || missingUpper)) {
                    shouldReplace = true;
                }

                if (shouldReplace) {
                    chars[i] = replacement;
                    break;
                }
            }
        }

        return new String(chars);
    }
}

import java.io.ByteArrayInputStream;
