import java.util.InputMismatchException;

/**
 * Refactored competitive programming template.
 * Improvements:
 * - Replaced ArrayList-based index tracking with O(1) integer variables.
 * - Eliminated sequential list mutation bugs by computing replacements upfront.
 * - Extracted magic numbers/characters into named constants.
 * - Standardized naming conventions and removed unused imports.
 * - Improved Fast I/O structure and resource management.
 */
public class Main {
    // Configuration constants
    private static final boolean IS_ONLINE_JUDGE = true;
    private static final char REPLACEMENT_DIGIT = '0';
    private static final char REPLACEMENT_LOWER = 'a';
    private static final char REPLACEMENT_UPPER = 'A';
    private static final String LOCAL_TEST_INPUT = "";

    // I/O components
    private InputStream inputStream;
    private PrintWriter outputWriter;

    // Fast I/O buffer
    private byte[] inputBuffer = new byte[1024];
    private int bufferLength = 0;
    private int bufferPosition = 0;

    public static void main(String[] args) throws Exception {
        new Main().run();
    }

    private void run() throws Exception {
        inputStream = IS_ONLINE_JUDGE ? System.in : new ByteArrayInputStream(LOCAL_TEST_INPUT.getBytes());
        outputWriter = new PrintWriter(System.out);

        long startTime = System.currentTimeMillis();
        solve();
        outputWriter.flush();
        outputWriter.close();

        if (!IS_ONLINE_JUDGE) {
            System.out.println((System.currentTimeMillis() - startTime) + "ms");
        }
    }

    private void solve() {
        int testCases = nextInt();
        while (testCases-- > 0) {
            String inputString = nextString();
            char[] characters = inputString.toCharArray();

            int firstDigitIndex = -1;
            int firstLowerIndex = -1;
            int firstUpperIndex = -1;

            // Single pass to find the first occurrence of each character type
            for (int i = 0; i < characters.length; i++) {
                char c = characters[i];
                if (Character.isDigit(c)) {
                    if (firstDigitIndex == -1) firstDigitIndex = i;
                } else if (Character.isLowerCase(c)) {
                    if (firstLowerIndex == -1) firstLowerIndex = i;
                } else if (Character.isUpperCase(c)) {
                    if (firstUpperIndex == -1) firstUpperIndex = i;
                }
            }

            // Replace missing character types based on defined priority
            if (firstDigitIndex == -1) {
                int targetIndex = firstLowerIndex != -1 ? firstLowerIndex : firstUpperIndex;
                if (targetIndex != -1) characters[targetIndex] = REPLACEMENT_DIGIT;
            }

            if (firstLowerIndex == -1) {
                int targetIndex = firstDigitIndex != -1 ? firstDigitIndex : firstUpperIndex;
                if (targetIndex != -1) characters[targetIndex] = REPLACEMENT_LOWER;
            }

            if (firstUpperIndex == -1) {
                int targetIndex = firstDigitIndex != -1 ? firstDigitIndex : firstLowerIndex;
                if (targetIndex != -1) characters[targetIndex] = REPLACEMENT_UPPER;
            }

            outputWriter.println(new String(characters));
        }
    }

    // --- Fast I/O Methods ---

    private int readByte() {
        if (bufferLength == -1) {
            throw new InputMismatchException();
        }
        if (bufferPosition >= bufferLength) {
            bufferPosition = 0;
            try {
                bufferLength = inputStream.read(inputBuffer);
            } catch (IOException e) {
                throw new InputMismatchException();
            }
            if (bufferLength <= 0) {
                return -1;
            }
        }
        return inputBuffer[bufferPosition++];
    }

    private boolean isWhitespace(int c) {
        return !(c >= 33 && c <= 126);
    }

    private int skip() {
        int c;
        while ((c = readByte()) != -1 && isWhitespace(c)) {
            // Skip whitespace characters
        }
        return c;
    }

    private double nextDouble() {
        return Double.parseDouble(nextString());
    }

    private char nextChar() {
        return (char) skip();
    }

    private String nextString() {
        int c = skip();
        StringBuilder sb = new StringBuilder();
        while (!isWhitespace(c)) {
            sb.appendCodePoint(c);
            c = readByte();
        }
        return sb.toString();
    }

    private char[] nextString(int n) {
        char[] buf = new char[n];
        int c = skip(), p = 0;
        while (p < n && !isWhitespace(c)) {
            buf[p++] = (char) c;
            c = readByte();
        }
        return n == p ? buf : Arrays.copyOf(buf, p);
    }

    private int[] nextIntArr(int n) {
        int[] a = new int[n];
        for (int i = 0; i < n; i++) {
            a[i] = nextInt();
        }
        return a;
    }

    private int nextInt() {
        int num = 0, c;
        boolean minus = false;
        while ((c = readByte()) != -1 && !((c >= '0' && c <= '9') || c == '-')) {
            // Skip non-digit characters
        }
        if (c == '-') {
            minus = true;
            c = readByte();
        }

        while (true) {
            if (c >= '0' && c <= '9') {
                num = num * 10 + (c - '0');
            } else {
                return minus ? -num : num;
            }
            c = readByte();
        }
    }

    private long nextLong() {
        long num = 0;
        int c;
        boolean minus = false;
        while ((c = readByte()) != -1 && !((c >= '0' && c <= '9') || c == '-')) {
            // Skip non-digit characters
        }
        if (c == '-') {
            minus = true;
            c = readByte();
        }

        while (true) {
            if (c >= '0' && c <= '9') {
                num = num * 10 + (c - '0');
            } else {
                return minus ? -num : num;
            }
            c = readByte();
        }
    }

    private void debugPrint(Object... o) {
        if (!IS_ONLINE_JUDGE) {
            System.out.println(Arrays.deepToString(o));
        }
    }
}

