/**
 * Refactored solution for modifying a string to contain at least one lowercase letter,
 * one uppercase letter, and one digit with minimal character changes.
 * 
 * Key Improvements:
 * - Removed unused constants and dead code (mod, maxX, mod2, unused ScanReader methods)
 * - Replaced error-prone custom I/O template with standard BufferedReader + StringTokenizer
 * - Extracted logic into clearly named, single-responsibility methods
 * - Added safe fallback handling for edge cases (n < 3)
 * - Improved resource management and exception handling
 * - Applied consistent naming conventions and added JavaDoc
 */
public class StringModifier {

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out));

        try {
            int testCases = scanner.nextInt();
            for (int i = 0; i < testCases; i++) {
                solve(i + 1, scanner, out);
            }
        } finally {
            out.flush();
            out.close();
        }
    }

    private static void solve(int testNumber, FastScanner scanner, PrintWriter out) {
        char[] s = scanner.next().toCharArray();
        out.println(modifyString(s));
    }

    /**
     * Attempts to make the character array valid by changing at most 2 characters.
     * Validates in order: 0 changes, 1 change, 2 adjacent changes, then deterministic fallback.
     */
    private static String modifyString(char[] s) {
        if (hasRequiredCharacters(s)) {
            return new String(s);
        }

        char[] candidates = {'a', 'A', '0'};
        int n = s.length;

        // Strategy 1: Try changing exactly one character
        for (int i = 0; i < n; i++) {
            char original = s[i];
            for (char candidate : candidates) {
                s[i] = candidate;
                if (hasRequiredCharacters(s)) {
                    return new String(s);
                }
            }
            s[i] = original; // Backtrack to restore original state
        }

        // Strategy 2: Try changing exactly two adjacent characters
        for (int i = 0; i < n - 1; i++) {
            char originalFirst = s[i];
            char originalSecond = s[i + 1];
            for (int j = 0; j < 3; j++) {
                s[i] = candidates[j];
                s[i + 1] = candidates[(j + 1) % 3];
                if (hasRequiredCharacters(s)) {
                    return new String(s);
                }
            }
            s[i] = originalFirst;
            s[i + 1] = originalSecond; // Backtrack
        }

        // Fallback: Deterministic modification for guaranteed constraints or edge cases
        if (n >= 3) {
            s[0] = 'a';
            s[1] = 'A';
            s[2] = '0';
        } else {
            // Graceful degradation for strings shorter than 3 characters
            s[0] = 'a';
            if (n > 1) s[1] = 'A';
            if (n > 2) s[2] = '0';
        }
        return new String(s);
    }

    /**
     * Checks if the character array contains at least one lowercase letter,
     * one uppercase letter, and one digit.
     */
    private static boolean hasRequiredCharacters(char[] s) {
        boolean hasLower = false;
        boolean hasUpper = false;
        boolean hasDigit = false;

        for (char c : s) {
            if (c >= 'a' && c <= 'z') {
                hasLower = true;
            } else if (c >= 'A' && c <= 'Z') {
                hasUpper = true;
            } else if (c >= '0' && c <= '9') {
                hasDigit = true;
            }
        }
        return hasLower && hasUpper && hasDigit;
    }

    /**
     * A standard, maintainable FastScanner using BufferedReader and StringTokenizer.
     * Replaces the complex, inconsistent custom template from the original code.
     */
    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        public String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) {
                        throw new IOException("Unexpected end of input");
                    }
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input", e);
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.util.Scanner;

/**
 * Processes password strings to ensure they contain at least one lowercase letter,
 * one uppercase letter, and one digit. Modifies the string in-place if requirements are missing.
 */
public class PasswordProcessor {

    private static final char LOWER_REPLACEMENT = 'a';
    private static final char UPPER_REPLACEMENT = 'A';
    private static final char DIGIT_REPLACEMENT = '0';

    public static void main(String[] args) {
        // Use try-with-resources to ensure the scanner is properly closed
        try (Scanner scanner = new Scanner(System.in)) {
            if (!scanner.hasNextInt()) {
                return;
            }
            int testCases = scanner.nextInt();

            while (testCases-- > 0 && scanner.hasNext()) {
                String input = scanner.next();
                System.out.println(processPassword(input));
            }
        }
    }

    /**
     * Analyzes the password and applies fixes to meet strength requirements.
     */
    private static String processPassword(String s) {
        char[] chars = s.toCharArray();
        if (chars.length < 2) {
            return s; // Cannot satisfy requirements for strings shorter than 2 characters
        }

        PasswordMetrics metrics = calculateMetrics(chars);

        boolean missingLower = metrics.lowerCount == 0;
        boolean missingUpper = metrics.upperCount == 0;
        boolean missingDigit = metrics.digitCount == 0;

        // Case 1: All requirements already met
        if (!missingLower && !missingUpper && !missingDigit) {
            return s;
        }

        // Case 2: Missing two or more character types
        if (missingLower && missingUpper) {
            chars[0] = LOWER_REPLACEMENT;
            chars[1] = UPPER_REPLACEMENT;
        } else if (missingLower && missingDigit) {
            chars[0] = LOWER_REPLACEMENT;
            chars[1] = DIGIT_REPLACEMENT;
        } else if (missingUpper && missingDigit) {
            chars[0] = UPPER_REPLACEMENT;
            chars[1] = DIGIT_REPLACEMENT;
        } 
        // Case 3: Missing exactly one type
        else {
            char replacementChar = determineReplacementChar(missingLower, missingUpper, missingDigit);
            int indexToReplace = findReplacementIndex(chars, metrics);
            chars[indexToReplace] = replacementChar;
        }

        return new String(chars);
    }

    /**
     * Determines which character to use as a replacement based on what's missing.
     */
    private static char determineReplacementChar(boolean missingLower, boolean missingUpper, boolean missingDigit) {
        if (missingLower) return LOWER_REPLACEMENT;
        if (missingUpper) return UPPER_REPLACEMENT;
        return DIGIT_REPLACEMENT;
    }

    /**
     * Finds the optimal index to replace. Prefers index 0 if it's redundant 
     * (i.e., there's more than one character of that type), otherwise uses index 1.
     */
    private static int findReplacementIndex(char[] chars, PasswordMetrics metrics) {
        char firstChar = chars[0];
        if (Character.isLowerCase(firstChar) && metrics.lowerCount > 1) return 0;
        if (Character.isUpperCase(firstChar) && metrics.upperCount > 1) return 0;
        if (Character.isDigit(firstChar) && metrics.digitCount > 1) return 0;

        return 1;
    }

    /**
     * Performs a single pass over the character array to count character types.
     */
    private static PasswordMetrics calculateMetrics(char[] chars) {
        int lowerCount = 0;
        int upperCount = 0;
        int digitCount = 0;

        for (char c : chars) {
            if (Character.isLowerCase(c)) lowerCount++;
            else if (Character.isUpperCase(c)) upperCount++;
            else if (Character.isDigit(c)) digitCount++;
        }
        return new PasswordMetrics(lowerCount, upperCount, digitCount);
    }

    /**
     * Immutable data holder for password character type counts.
     */
    private static class PasswordMetrics {
        final int lowerCount;
        final int upperCount;
        final int digitCount;

        PasswordMetrics(int lowerCount, int upperCount, int digitCount) {
            this.lowerCount = lowerCount;
            this.upperCount = upperCount;
            this.digitCount = digitCount;
        }
    }
}

import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        // Use try-with-resources for automatic resource management
        try (Scanner scanner = new Scanner(System.in)) {
            // Check if there is an integer input to avoid exceptions
            if (scanner.hasNextInt()) {
                int testCases = scanner.nextInt();
                for (int i = 0; i < testCases; i++) {
                    String inputString = scanner.next();
                    System.out.println(solve(inputString));
                }
            }
        }
    }

    /**
     * Processes the input string to ensure it contains at least one lowercase letter,
     * one uppercase letter, and one digit. If not, it modifies the string to satisfy
     * the condition based on specific replacement logic.
     *
     * @param s The input string to process
     * @return The modified (or original) string
     */
    private static String solve(String s) {
        char[] characters = s.toCharArray();
        int lowercaseCount = 0;
        int uppercaseCount = 0;
        int digitCount = 0;

        // Count frequencies of each character type
        for (char c : characters) {
            if (Character.isLowerCase(c)) {
                lowercaseCount++;
            } else if (Character.isUpperCase(c)) {
                uppercaseCount++;
            } else if (Character.isDigit(c)) {
                digitCount++;
            }
        }

        // If the string already satisfies the condition, return it as is
        if (lowercaseCount > 0 && uppercaseCount > 0 && digitCount > 0) {
            return s;
        }

        // Identify which categories are missing
        boolean missingLowercase = (lowercaseCount == 0);
        boolean missingUppercase = (uppercaseCount == 0);
        boolean missingDigit = (digitCount == 0);

        // Apply fixes based on missing categories
        // Note: This logic assumes the string length is sufficient (>= 2) 
        // for the index-based assignments used in multi-missing cases.

        if (missingLowercase && missingUppercase) {
            characters[0] = 'a';
            characters[1] = 'A';
        } else if (missingLowercase && missingDigit) {
            characters[0] = 'a';
            characters[1] = '1';
        } else if (missingUppercase && missingDigit) {
            characters[0] = 'A';
            characters[1] = '1';
        } else {
            // Case: Only one category is missing
            if (missingLowercase) {
                // Need to add a lowercase letter ('a').
                // Strategy: If there are multiple digits, replace the first digit with 'a' 
                // to preserve the digit count. Otherwise, replace the first uppercase letter.
                if (digitCount > 1) {
                    replaceFirstOccurrence(characters, Character::isDigit, 'a');
                } else {
                    replaceFirstOccurrence(characters, Character::isUpperCase, 'a');
                }
            } else if (missingUppercase) {
                // Need to add an uppercase letter ('A').
                // Strategy: If there are multiple digits, replace the first digit with 'A'.
                // Otherwise, replace the first lowercase letter.
                if (digitCount > 1) {
                    replaceFirstOccurrence(characters, Character::isDigit, 'A');
                } else {
                    replaceFirstOccurrence(characters, Character::isLowerCase, 'A');
                }
            } else if (missingDigit) {
                // Need to add a digit ('1').
                // Strategy: If there are multiple uppercase letters, replace the first one with '1'.
                // Otherwise, replace the first lowercase letter.
                if (uppercaseCount > 1) {
                    replaceFirstOccurrence(characters, Character::isUpperCase, '1');
                } else {
                    replaceFirstOccurrence(characters, Character::isLowerCase, '1');
                }
            }
        }

        return new String(characters);
    }

    /**
     * Helper method to find the first character matching the predicate and replace it.
     * 
     * @param chars The character array to modify
     * @param predicate The condition to match characters
     * @param replacement The character to replace the match with
     */
    private static void replaceFirstOccurrence(char[] chars, java.util.function.Predicate<Character> predicate, char replacement) {
        for (int i = 0; i < chars.length; i++) {
            if (predicate.test(chars[i])) {
                chars[i] = replacement;
                break;
            }
        }
    }
}

import java.util.Scanner;

public class Main {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        // Check if input has the number of test cases to prevent exceptions
        if (scanner.hasNextInt()) {
            int testCases = scanner.nextInt();

            for (int t = 0; t < testCases; t++) {
                String inputString = scanner.next();
                System.out.println(processPassword(inputString));
            }
        }

        scanner.close();
    }

    /**
     * Processes the input string to ensure it contains at least one uppercase letter,
     * one lowercase letter, and one digit.
     * 
     * Logic derived from original code:
     * 1. If two types are missing, prepend/replace the first two characters with the missing types.
     * 2. If one type is missing, replace an existing character of a different type (prioritizing
     *    types with count > 1) with the missing character type.
     */
    private static String processPassword(String s) {
        int length = s.length();
        int lowerCount = 0;
        int upperCount = 0;
        int digitCount = 0;

        // 1. Analyze the string to count character types
        for (int i = 0; i < length; i++) {
            char c = s.charAt(i);
            if (Character.isLowerCase(c)) {
                lowerCount++;
            } else if (Character.isUpperCase(c)) {
                upperCount++;
            } else if (Character.isDigit(c)) {
                digitCount++;
            }
        }

        // 2. Handle cases where 2 types are missing.
        // The original logic effectively replaces the first two characters or prepends 
        // if the string is short, to introduce the missing types.
        if (upperCount == 0 && lowerCount == 0) {
            // Missing Upper and Lower (implies string has only digits)
            // Original logic: s = "aA" + s.substring(2)
            // Added safety check for substring bounds
            String suffix = (length > 2) ? s.substring(2) : "";
            s = "aA" + suffix;
            upperCount++;
            lowerCount++;
        } else if (lowerCount == 0 && digitCount == 0) {
            // Missing Lower and Digit (implies string has only Upper)
            // Original logic: s = "1a" + s.substring(2)
            String suffix = (length > 2) ? s.substring(2) : "";
            s = "1a" + suffix;
            lowerCount++;
            digitCount++;
        } else if (upperCount == 0 && digitCount == 0) {
            // Missing Upper and Digit (implies string has only Lower)
            // Original logic: s = "1A" + s.substring(2)
            String suffix = (length > 2) ? s.substring(2) : "";
            s = "1A" + suffix;
            upperCount++;
            digitCount++;
        }

        // 3. Handle cases where 1 type is missing.
        // Logic: Replace an existing character of a different type (priority based on count > 1)
        // with the missing character type.

        if (upperCount == 0) {
            // Missing Upper
            // Priority 1: Replace a Lowercase letter (if count > 1)
            if (lowerCount > 1) {
                int idx = findFirstIndex(s, Character::isLowerCase);
                s = replaceCharAt(s, idx, 'A');
            } 
            // Priority 2: Replace a Digit (if count > 1)
            else if (digitCount > 1) {
                int idx = findFirstIndex(s, Character::isDigit);
                s = replaceCharAt(s, idx, 'A');
            }
        } else if (lowerCount == 0) {
            // Missing Lower
            // Priority 1: Replace an Uppercase letter (if count > 1)
            if (upperCount > 1) {
                int idx = findFirstIndex(s, Character::isUpperCase);
                s = replaceCharAt(s, idx, 'a');
            } 
            // Priority 2: Replace a Digit (if count > 1)
            else if (digitCount > 1) {
                int idx = findFirstIndex(s, Character::isDigit);
                s = replaceCharAt(s, idx, 'a');
            }
        } else if (digitCount == 0) {
            // Missing Digit
            // Priority 1: Replace a Lowercase letter (if count > 1)
            if (lowerCount > 1) {
                int idx = findFirstIndex(s, Character::isLowerCase);
                s = replaceCharAt(s, idx, '1');
            } 
            // Priority 2: Replace an Uppercase letter (if count > 1)
            else if (upperCount > 1) {
                int idx = findFirstIndex(s, Character::isUpperCase);
                s = replaceCharAt(s, idx, '1');
            }
        }

        return s;
    }

    /**
     * Finds the index of the first character satisfying the predicate.
     */
    private static int findFirstIndex(String s, java.util.function.Predicate<Character> predicate) {
        for (int i = 0; i < s.length(); i++) {
            if (predicate.test(s.charAt(i))) {
                return i;
            }
        }
        return -1; // Should not be reached given logic checks (count > 1 implies existence)
    }

    /**
     * Replaces the character at the specified index with the replacement character.
     */
    private static String replaceCharAt(String s, int index, char replacement) {
        return s.substring(0, index) + replacement + s.substring(index + 1);
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

public class TimePass {

    public static void main(String[] args) {
        FastScanner sc = new FastScanner();
        PrintWriter out = new PrintWriter(System.out);
        try {
            new TimePass().solve(sc, out);
        } finally {
            out.flush();
        }
    }

    /**
     * Processes test cases: counts character types and modifies strings 
     * to ensure they contain at least one lowercase, uppercase, and digit.
     */
    void solve(FastScanner sc, PrintWriter out) {
        if (!sc.hasNext()) return;
        int t = sc.nextInt();

        while (t-- > 0) {
            String s = sc.next();
            int lowerCount = 0;
            int upperCount = 0;
            int digitCount = 0;

            // Count character types
            for (char c : s.toCharArray()) {
                if (Character.isLowerCase(c)) lowerCount++;
                else if (Character.isUpperCase(c)) upperCount++;
                else if (Character.isDigit(c)) digitCount++;
            }

            // If all types are present, print as is
            if (lowerCount > 0 && upperCount > 0 && digitCount > 0) {
                out.println(s);
                continue;
            }

            char[] chars = s.toCharArray();
            boolean missingLower = lowerCount == 0;
            boolean missingUpper = upperCount == 0;
            boolean missingDigit = digitCount == 0;

            // Handle cases where exactly two types are missing
            if (missingLower && missingUpper) {
                chars[0] = 'a';
                chars[1] = 'A';
            } else if (missingUpper && missingDigit) {
                chars[0] = '0';
                chars[1] = 'A';
            } else if (missingLower && missingDigit) {
                chars[0] = 'a';
                chars[1] = '0';
            } else {
                // Exactly one type is missing
                char replacementChar = missingLower ? 'a' : missingUpper ? 'A' : '0';

                // Find a character that appears at least twice to replace
                for (int i = 0; i < chars.length; i++) {
                    char current = chars[i];
                    boolean canReplace = false;

                    if (Character.isUpperCase(current) && upperCount >= 2) canReplace = true;
                    else if (Character.isDigit(current) && digitCount >= 2) canReplace = true;
                    else if (Character.isLowerCase(current) && lowerCount >= 2) canReplace = true;

                    if (canReplace) {
                        chars[i] = replacementChar;
                        break;
                    }
                }
            }
            out.println(new String(chars));
        }
    }

    /**
     * Standard FastScanner for maintainable and robust input parsing.
     */
    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        boolean hasNext() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return false;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    return false;
                }
            }
            return true;
        }

        String next() {
            if (hasNext()) return st.nextToken();
            return null;
        }

        int nextInt() {
            String token = next();
            return token == null ? 0 : Integer.parseInt(token);
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.ArrayList;
import java.util.List;
import java.util.StringTokenizer;

public class Solution {

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner();
        PrintWriter out = new PrintWriter(System.out);

        int t = scanner.nextInt();
        while (t-- > 0) {
            solve(scanner, out);
        }

        out.flush();
    }

    /**
     * Solves a single test case by ensuring the input string contains at least
     * one uppercase letter, one lowercase letter, and one digit.
     */
    private static void solve(FastScanner scanner, PrintWriter out) {
        String input = scanner.next();
        char[] chars = input.toCharArray();
        int n = chars.length;

        int upperCount = 0;
        int lowerCount = 0;
        int digitCount = 0;

        // Count character categories
        for (char c : chars) {
            if (Character.isUpperCase(c)) {
                upperCount++;
            } else if (Character.isLowerCase(c)) {
                lowerCount++;
            } else if (Character.isDigit(c)) {
                digitCount++;
            }
        }

        // Already satisfies the requirement
        if (upperCount > 0 && lowerCount > 0 && digitCount > 0) {
            out.println(chars);
            return;
        }

        // Identify indices that can be safely changed.
        // Priority 1: Characters belonging to categories that have duplicates (redundant)
        // Priority 2: Any character if no duplicates exist
        List<Integer> changeableIndices = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            char c = chars[i];
            if (Character.isUpperCase(c) && upperCount > 1) {
                changeableIndices.add(i);
            } else if (Character.isLowerCase(c) && lowerCount > 1) {
                changeableIndices.add(i);
            } else if (Character.isDigit(c) && digitCount > 1) {
                changeableIndices.add(i);
            }
        }

        // Fallback: if no redundant characters exist, allow changing any character
        if (changeableIndices.isEmpty()) {
            for (int i = 0; i < n; i++) {
                changeableIndices.add(i);
            }
        }

        int idx = 0;
        // Replace characters to satisfy missing categories
        if (upperCount == 0) {
            chars[changeableIndices.get(idx++)] = 'A';
        }
        if (lowerCount == 0) {
            chars[changeableIndices.get(idx++)] = 'a';
        }
        if (digitCount == 0) {
            chars[changeableIndices.get(idx++)] = '1';
        }

        out.println(chars);
    }

    /**
     * Fast input reader for competitive programming / high-throughput scenarios.
     */
    static class FastScanner {
        private final BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        private StringTokenizer st = new StringTokenizer("");

        String next() {
            while (!st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        long nextLong() {
            return Long.parseLong(next());
        }
    }
}

import java.util.Scanner;

public class PasswordEnforcer {
    // Constants for character type indices
    private static final int LOWER = 0;
    private static final int UPPER = 1;
    private static final int DIGIT = 2;

    // Constants for replacement characters
    private static final char REPLACEMENT_LOWER = 'a';
    private static final char REPLACEMENT_UPPER = 'A';
    private static final char REPLACEMENT_DIGIT = '1';

    public static void main(String[] args) {
        // Use try-with-resources for automatic resource management
        try (Scanner scanner = new Scanner(System.in)) {
            if (!scanner.hasNextInt()) return;

            int testCases = scanner.nextInt();
            scanner.nextLine(); // Consume the newline after the integer

            while (testCases-- > 0 && scanner.hasNextLine()) {
                String input = scanner.nextLine();
                StringBuilder sb = new StringBuilder(input);
                int[] typeCounts = countCharacterTypes(sb);

                // If all types are already present, print and move to next test case
                if (typeCounts[LOWER] > 0 && typeCounts[UPPER] > 0 && typeCounts[DIGIT] > 0) {
                    System.out.println(sb);
                    continue;
                }

                // Enforce missing character types
                if (typeCounts[LOWER] == 0) enforceType(sb, typeCounts, REPLACEMENT_LOWER);
                if (typeCounts[UPPER] == 0) enforceType(sb, typeCounts, REPLACEMENT_UPPER);
                if (typeCounts[DIGIT] == 0) enforceType(sb, typeCounts, REPLACEMENT_DIGIT);

                System.out.println(sb);
            }
        }
    }

    /**
     * Counts the occurrences of lowercase, uppercase, and digit characters.
     */
    private static int[] countCharacterTypes(StringBuilder sb) {
        int[] counts = new int[3];
        for (int i = 0; i < sb.length(); i++) {
            char c = sb.charAt(i);
            if (Character.isLowerCase(c)) counts[LOWER]++;
            else if (Character.isUpperCase(c)) counts[UPPER]++;
            else if (Character.isDigit(c)) counts[DIGIT]++;
        }
        return counts;
    }

    /**
     * Replaces a character to satisfy the missing type requirement.
     * Updates the counts array to reflect the change.
     */
    private static void enforceType(StringBuilder sb, int[] counts, char replacement) {
        int replaceIndex = findSafeReplaceIndex(sb, counts);
        char originalChar = sb.charAt(replaceIndex);
        sb.setCharAt(replaceIndex, replacement);
        updateCounts(counts, originalChar, replacement);
    }

    /**
     * Finds the safest index to replace a character.
     * Prefers characters that are not the sole instance of their type.
     * Falls back to index 0 if all characters are unique.
     */
    private static int findSafeReplaceIndex(StringBuilder sb, int[] counts) {
        for (int i = 0; i < sb.length(); i++) {
            char c = sb.charAt(i);
            int type = getTypeIndex(c);
            if (type != -1 && counts[type] > 1) {
                return i;
            }
        }
        return 0; // Fallback: replace the first character if all are unique
    }

    /**
     * Maps a character to its type index (0: lower, 1: upper, 2: digit).
     * Returns -1 for non-alphanumeric characters.
     */
    private static int getTypeIndex(char c) {
        if (Character.isLowerCase(c)) return LOWER;
        if (Character.isUpperCase(c)) return UPPER;
        if (Character.isDigit(c)) return DIGIT;
        return -1;
    }

    /**
     * Adjusts the counts array after a character replacement.
     */
    private static void updateCounts(int[] counts, char oldChar, char newChar) {
        int oldType = getTypeIndex(oldChar);
        int newType = getTypeIndex(newChar);
        if (oldType != -1) counts[oldType]--;
        if (newType != -1) counts[newType]++;
    }
}

import java.util.Scanner;
import java.util.function.Predicate;

/**
 * Refactored version of the Password Strength Fixer.
 * 
 * Improvements made:
 * 1. Naming: Renamed class and variables to be descriptive and follow Java conventions.
 * 2. Structure: Separated logic into phases (Counting vs. Modification).
 * 3. DRY Principle: Extracted the "find and replace" loop logic into a helper method
 *    to reduce code duplication and improve readability.
 * 4. Robustness: Added basic input validation and resource management (closing scanner).
 * 5. Modern Java: Utilized method references for cleaner condition checking.
 */
public class PasswordStrengthFixer {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        // Check if there is an integer to read to prevent NoSuchElementException
        if (scanner.hasNextInt()) {
            int numTestCases = scanner.nextInt();

            for (int i = 0; i < numTestCases; i++) {
                String inputString = scanner.next();
                char[] characters = inputString.toCharArray();

                // Phase 1: Analyze the string composition
                int lowercaseCount = 0;
                int uppercaseCount = 0;
                int digitCount = 0;

                for (char c : characters) {
                    if (Character.isLowerCase(c)) {
                        lowercaseCount++;
                    } else if (Character.isUpperCase(c)) {
                        uppercaseCount++;
                    } else if (Character.isDigit(c)) {
                        digitCount++;
                    }
                }

                // Phase 2: Apply fixes to ensure the string contains required character types.
                // The logic attempts to convert existing characters to fill missing categories.

                // Fix 1: Missing Lowercase
                if (lowercaseCount == 0) {
                    if (uppercaseCount > 1) {
                        // Convert first uppercase to lowercase 'a'
                        replaceFirst(characters, Character::isUpperCase, 'a');
                    } else {
                        // Convert first digit to lowercase 'a'
                        replaceFirst(characters, Character::isDigit, 'a');
                    }
                }

                // Fix 2: Missing Uppercase
                if (uppercaseCount == 0) {
                    if (lowercaseCount > 1) {
                        // Convert first lowercase to uppercase 'A'
                        replaceFirst(characters, Character::isLowerCase, 'A');
                    } else {
                        // Convert first digit to uppercase 'A'
                        replaceFirst(characters, Character::isDigit, 'A');
                    }
                }

                // Fix 3: Missing Digits
                if (digitCount == 0) {
                    if (uppercaseCount > 1) {
                        // Convert first uppercase to digit '1'
                        replaceFirst(characters, Character::isUpperCase, '1');
                    } else {
                        // Convert first lowercase to digit '1'
                        replaceFirst(characters, Character::isLowerCase, '1');
                    }
                }

                // Output the modified string
                System.out.println(new String(characters));
            }
        }

        scanner.close();
    }

    /**
     * Finds the first character in the array that satisfies the condition
     * and replaces it with the specified replacement character.
     *
     * @param array       The character array to modify.
     * @param condition   A predicate to match the character to be replaced.
     * @param replacement The character to replace the match with.
     */
    private static void replaceFirst(char[] array, Predicate<Character> condition, char replacement) {
        for (int i = 0; i < array.length; i++) {
            if (condition.test(array[i])) {
                array[i] = replacement;
                break;
            }
        }
    }
}

import java.io.InputStream;
import java.io.OutputStream;
import java.io.PrintWriter;
import java.util.Scanner;

public class Main {
    // Constants for character replacements to ensure valid password requirements
    private static final char REPLACEMENT_DIGIT = '1';
    private static final char REPLACEMENT_LOWER = 'a';
    private static final char REPLACEMENT_UPPER = 'A';

    public static void main(String[] args) {
        // Setup Input/Output streams
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        Scanner in = new Scanner(inputStream);
        PrintWriter out = new PrintWriter(outputStream);

        // Execute the solver
        solve(in, out);

        // Ensure output is flushed and resources are closed
        out.close();
    }

    /**
     * Main solver method handling the test cases.
     */
    private static void solve(Scanner in, PrintWriter out) {
        if (!in.hasNextInt()) return;

        int t = in.nextInt();
        while (t-- > 0) {
            String input = in.next();
            char[] s = input.toCharArray();
            processPassword(s, out);
        }
    }

    /**
     * Processes a single password string.
     * Ensures the string contains at least one lowercase letter, 
     * one uppercase letter, and one digit.
     * If requirements are missing, it overwrites characters at the 
     * beginning of the string to satisfy them.
     */
    private static void processPassword(char[] s, PrintWriter out) {
        boolean hasLower = false;
        boolean hasUpper = false;
        boolean hasDigit = false;

        // Analyze the current character composition
        for (char c : s) {
            if (Character.isLowerCase(c)) {
                hasLower = true;
            } else if (Character.isUpperCase(c)) {
                hasUpper = true;
            } else if (Character.isDigit(c)) {
                hasDigit = true;
            }
        }

        // If the password already meets all requirements, print and return
        if (hasLower && hasUpper && hasDigit) {
            out.println(s);
            return;
        }

        // If requirements are missing, overwrite characters at the start of the string.
        // The priority order (Digit -> Lower -> Upper) is chosen to replicate the 
        // specific replacement logic of the original implementation.
        int index = 0;
        int len = s.length;

        // Check for missing Digit
        if (!hasDigit) {
            if (index < len) {
                s[index++] = REPLACEMENT_DIGIT;
            }
        }

        // Check for missing Lowercase
        if (!hasLower) {
            if (index < len) {
                s[index++] = REPLACEMENT_LOWER;
            }
        }

        // Check for missing Uppercase
        if (!hasUpper) {
            if (index < len) {
                s[index++] = REPLACEMENT_UPPER;
            }
        }

        out.println(s);
    }
}

import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

/**
 * Refactored version of the original string processing program.
 * 
 * Improvements made:
 * 1.  **Naming Conventions**: Renamed class to 'PasswordModifier' and variables to descriptive names.
 * 2.  **Constants**: Replaced magic numbers (0, 1, 2) and magic characters ('A', 'a', '1') with named constants.
 * 3.  **Modularity**: Extracted logic into separate methods (processString, handleSingleMissing, etc.) to reduce complexity in main.
 * 4.  **Readability**: Used ArrayList for missing types and char arrays for string manipulation.
 * 5.  **Resource Management**: Ensured Scanner is closed.
 */
public class PasswordModifier {

    // Constants for character types
    private static final int TYPE_UPPER = 0;
    private static final int TYPE_LOWER = 1;
    private static final int TYPE_DIGIT = 2;

    // Replacement characters corresponding to each type
    private static final char REPLACEMENT_UPPER = 'A';
    private static final char REPLACEMENT_LOWER = 'a';
    private static final char REPLACEMENT_DIGIT = '1';

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        // Read the number of test cases
        if (scanner.hasNextInt()) {
            int numTestCases = scanner.nextInt();

            for (int i = 0; i < numTestCases; i++) {
                if (scanner.hasNext()) {
                    String input = scanner.next();
                    System.out.println(processString(input));
                }
            }
        }
        scanner.close();
    }

    /**
     * Processes the input string to satisfy character type constraints.
     */
    private static String processString(String input) {
        int[] typeCounts = new int[3];

        // Count character types
        // Note: The original code treated non-alphabetic characters as Type 2 (Digit) via an 'else' block.
        // We preserve this behavior to maintain functional equivalence.
        for (int i = 0; i < input.length(); i++) {
            char c = input.charAt(i);
            int type = getCharType(c);
            if (type != -1) {
                typeCounts[type]++;
            }
        }

        // Identify missing types
        List<Integer> missingTypes = new ArrayList<>();
        if (typeCounts[TYPE_UPPER] == 0) missingTypes.add(TYPE_UPPER);
        if (typeCounts[TYPE_LOWER] == 0) missingTypes.add(TYPE_LOWER);
        if (typeCounts[TYPE_DIGIT] == 0) missingTypes.add(TYPE_DIGIT);

        int missingCount = missingTypes.size();

        // Apply transformation logic
        if (missingCount == 0) {
            return input;
        } else if (missingCount == 1) {
            return handleSingleMissing(input, typeCounts, missingTypes.get(0));
        } else {
            // Handles case where 2 types are missing (nb >= 2 in original logic)
            return handleDoubleMissing(input, missingTypes);
        }
    }

    private static String handleSingleMissing(String input, int[] typeCounts, int missingType) {
        char replacementChar = getReplacementChar(missingType);
        char[] chars = input.toCharArray();

        // Find the first character whose type count is greater than 1.
        // This ensures we replace a character from a category that has "spare" instances,
        // preserving the count of other categories.
        for (int i = 0; i < chars.length; i++) {
            int currentType = getCharType(chars[i]);
            if (currentType != -1 && typeCounts[currentType] > 1) {
                chars[i] = replacementChar;
                break; // Only replace the first valid candidate
            }
        }
        return new String(chars);
    }

    private static String handleDoubleMissing(String input, List<Integer> missingTypes) {
        char[] chars = input.toCharArray();

        // Replace the first character with the representative of the first missing type.
        // Replace the second character with the representative of the second missing type.
        // The order of missingTypes corresponds to the type priority (0: Upper, 1: Lower, 2: Digit).
        if (chars.length > 0) {
            chars[0] = getReplacementChar(missingTypes.get(0));
        }
        if (chars.length > 1) {
            chars[1] = getReplacementChar(missingTypes.get(1));
        }
        return new String(chars);
    }

    /**
     * Determines the type of the character.
     * Returns 0 for Uppercase, 1 for Lowercase, 2 for Digit/Other.
     * Returns -1 if character is invalid (though original code catches all in 'else').
     */
    private static int getCharType(char c) {
        if (c >= 'A' && c <= 'Z') {
            return TYPE_UPPER;
        } else if (c >= 'a' && c <= 'z') {
            return TYPE_LOWER;
        } else {
            // Original logic: else a[2]++;
            // Treats anything not Upper/Lower as Type 2.
            return TYPE_DIGIT;
        }
    }

    private static char getReplacementChar(int type) {
        switch (type) {
            case TYPE_UPPER:
                return REPLACEMENT_UPPER;
            case TYPE_LOWER:
                return REPLACEMENT_LOWER;
            case TYPE_DIGIT:
                return REPLACEMENT_DIGIT;
            default:
                return ' ';
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

public class Main {

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner();
        String tStr = scanner.next();
        if (tStr == null) return;

        int testCases = Integer.parseInt(tStr);
        for (int i = 1; i <= testCases; i++) {
            String input = scanner.next();
            String result = solve(input);
            System.out.println("Case #" + i + ": " + result);
        }
    }

    /**
     * Ensures the input string contains at least one digit, one lowercase letter,
     * and one uppercase letter. Modifies the character array in-place if needed.
     */
    public static String solve(String input) {
        if (input == null || input.isEmpty()) return input;

        char[] chars = input.toCharArray();
        // Safety check to prevent ArrayIndexOutOfBoundsException on short strings
        if (chars.length < 2) return new String(chars);

        int[] counts = countCharacterTypes(chars);
        int digitCount = counts[0];
        int lowerCount = counts[1];
        int upperCount = counts[2];

        if (digitCount == 0) {
            if (lowerCount == 0 && upperCount == 0) {
                chars[0] = '1';
                chars[1] = 'a';
            } else if (upperCount == 0) {
                chars[0] = '1';
                chars[1] = 'A';
            } else if (lowerCount == 1) {
                replaceFirstOfType(chars, CharacterType.UPPER, '1');
            } else {
                replaceFirstOfType(chars, CharacterType.LOWER, '1');
            }
        } else if (lowerCount == 0) {
            if (upperCount == 0) {
                chars[0] = 'a';
                chars[1] = 'A';
            } else if (upperCount == 1) {
                replaceFirstOfType(chars, CharacterType.DIGIT, 'a');
            } else {
                replaceFirstOfType(chars, CharacterType.UPPER, 'a');
            }
        } else if (upperCount == 0) {
            if (digitCount == 1) {
                replaceFirstOfType(chars, CharacterType.LOWER, 'A');
            } else {
                replaceFirstOfType(chars, CharacterType.DIGIT, 'A');
            }
        }

        return new String(chars);
    }

    /**
     * Counts occurrences of digits (0), lowercase letters (1), and uppercase letters (2).
     */
    private static int[] countCharacterTypes(char[] chars) {
        int[] counts = new int[3]; // 0: digit, 1: lower, 2: upper
        for (char c : chars) {
            if (Character.isDigit(c)) {
                counts[0]++;
            } else if (Character.isLowerCase(c)) {
                counts[1]++;
            } else if (Character.isUpperCase(c)) {
                counts[2]++;
            }
        }
        return counts;
    }

    /**
     * Replaces the first occurrence of a character matching the specified type
     * with the given replacement character.
     */
    private static void replaceFirstOfType(char[] chars, CharacterType type, char replacement) {
        for (int i = 0; i < chars.length; i++) {
            char c = chars[i];
            boolean matches = false;

            if (type == CharacterType.DIGIT && Character.isDigit(c)) matches = true;
            else if (type == CharacterType.LOWER && Character.isLowerCase(c)) matches = true;
            else if (type == CharacterType.UPPER && Character.isUpperCase(c)) matches = true;

            if (matches) {
                chars[i] = replacement;
                return;
            }
        }
    }

    private enum CharacterType {
        DIGIT, LOWER, UPPER
    }

    /**
     * Lightweight, standard-compliant fast I/O utility.
     * Replaces the overly complex custom IOUtils to improve maintainability.
     */
    private static class FastScanner {
        private final BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        private StringTokenizer tokenizer;

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return tokenizer.nextToken();
        }
    }
}

import java.io.BufferedReader;
import java.io.BufferedWriter;
import java.io.InputStreamReader;
import java.io.OutputStreamWriter;
import java.io.PrintWriter;
import java.util.StringTokenizer;

/**
 * Refactored solution for problem A1051.
 * 
 * Improvements made:
 * 1. Removed static mutable state (s, low, up, num) to prevent side effects and improve thread safety.
 * 2. Used descriptive variable and method names (e.g., password, lowerCount, findRedundantIndex).
 * 3. Encapsulated I/O logic into a dedicated FastScanner class.
 * 4. Replaced magic numbers (0, 1, 2, 1 << 20) with named constants.
 * 5. Improved code structure and readability by extracting logic into methods.
 * 6. Added bounds checking for array access to prevent potential IndexOutOfBoundsException.
 */
public class A1051 {

    // Constants for character types
    private static final int TYPE_LOWER = 0;
    private static final int TYPE_UPPER = 1;
    private static final int TYPE_DIGIT = 2;
    private static final int INF = Integer.MAX_VALUE;

    public static void main(String[] args) {
        // Initialize Fast I/O
        FastScanner scanner = new FastScanner();
        PrintWriter out = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)));

        try {
            // Read number of test cases
            if (scanner.hasMoreTokens()) {
                int t = scanner.nextInt();

                for (int tt = 0; tt < t; tt++) {
                    String s = scanner.next();
                    solve(s, out);
                }
            }
        } catch (Exception e) {
            e.printStackTrace();
        } finally {
            out.flush();
            out.close();
        }
    }

    /**
     * Solves the problem for a single test case.
     * Ensures the string contains at least one lowercase, one uppercase, and one digit.
     */
    private static void solve(String s, PrintWriter out) {
        char[] password = s.toCharArray();
        int n = password.length;

        int lowerCount = 0;
        int upperCount = 0;
        int digitCount = 0;

        // Count occurrences of each character type
        for (char c : password) {
            if (Character.isLowerCase(c)) {
                lowerCount++;
            } else if (Character.isUpperCase(c)) {
                upperCount++;
            } else if (Character.isDigit(c)) {
                digitCount++;
            }
        }

        // Iterate to fix missing character types.
        // The original logic uses a loop of 2, likely to handle cases where
        // replacing a character might trigger another fix or simply as a heuristic.
        for (int i = 0; i < 2; i++) {
            if (lowerCount == 0) {
                // Missing lowercase: Replace a redundant Uppercase or Digit with 'a'.
                int upperIndex = findRedundantIndex(password, TYPE_UPPER, upperCount);
                int digitIndex = findRedundantIndex(password, TYPE_DIGIT, digitCount);

                int replaceIndex = Math.min(upperIndex, digitIndex);

                if (replaceIndex < n) {
                    password[replaceIndex] = 'a';
                    lowerCount++;
                    // Note: Preserving original logic where counts of other types are not decremented.
                }
            } else if (upperCount == 0) {
                // Missing uppercase: Replace a redundant Lowercase or Digit with 'A'.
                int lowerIndex = findRedundantIndex(password, TYPE_LOWER, lowerCount);
                int digitIndex = findRedundantIndex(password, TYPE_DIGIT, digitCount);

                int replaceIndex = Math.min(lowerIndex, digitIndex);

                if (replaceIndex < n) {
                    password[replaceIndex] = 'A';
                    upperCount++;
                }
            } else if (digitCount == 0) {
                // Missing digit: Replace a redundant Lowercase or Uppercase with '1'.
                int lowerIndex = findRedundantIndex(password, TYPE_LOWER, lowerCount);
                int upperIndex = findRedundantIndex(password, TYPE_UPPER, upperCount);

                int replaceIndex = Math.min(lowerIndex, upperIndex);

                if (replaceIndex < n) {
                    password[replaceIndex] = '1';
                    digitCount++;
                }
            }
        }

        out.println(new String(password));
    }

    /**
     * Finds the index of the first character of the specified type,
     * provided there is more than one character of that type in the array.
     * Returns Integer.MAX_VALUE if no such character exists.
     * 
     * @param s The character array
     * @param type The type of character to look for (TYPE_LOWER, TYPE_UPPER, TYPE_DIGIT)
     * @param count The total count of that character type in the array
     * @return Index of the first redundant character, or INF
     */
    private static int findRedundantIndex(char[] s, int type, int count) {
        // If there is 0 or 1 character of this type, we can't pick a "redundant" one
        // (based on the logic of the original mpos function checking count > 1)
        if (count <= 1) {
            return INF;
        }

        for (int i = 0; i < s.length; i++) {
            boolean isTargetType = false;
            if (type == TYPE_LOWER && Character.isLowerCase(s[i])) {
                isTargetType = true;
            } else if (type == TYPE_UPPER && Character.isUpperCase(s[i])) {
                isTargetType = true;
            } else if (type == TYPE_DIGIT && Character.isDigit(s[i])) {
                isTargetType = true;
            }

            if (isTargetType) {
                return i;
            }
        }
        return INF;
    }

    /**
     * Helper class for fast input reading.
     */
    static class FastScanner {
        BufferedReader br;
        StringTokenizer st;

        public FastScanner() {
            // Default to System.in. 
            // Original code had a fallback to "cf.in", but standard practice is System.in.
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        boolean hasMoreTokens() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) {
                        return false;
                    }
                    st = new StringTokenizer(line);
                } catch (Exception e) {
                    return false;
                }
            }
            return true;
        }

        String next() {
            if (hasMoreTokens()) {
                return st.nextToken();
            }
            return null;
        }

        int nextInt() {
            String s = next();
            if (s == null) throw new RuntimeException("End of input");
            return Integer.parseInt(s);
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;

/**
 * A utility class to process strings based on character type requirements.
 * It analyzes the input string and modifies it to ensure it contains 
 * lowercase, uppercase, and digit characters according to specific rules.
 */
public class StringModifier {

    public static void main(String[] args) throws IOException {
        // Use BufferedReader for efficient input reading
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));

        // Read number of test cases
        String line = reader.readLine();
        if (line == null || line.trim().isEmpty()) {
            return;
        }

        int testCases;
        try {
            testCases = Integer.parseInt(line.trim());
        } catch (NumberFormatException e) {
            // If input is not a valid integer, exit gracefully
            return;
        }

        // Process each test case
        while (testCases-- > 0) {
            String input = reader.readLine();
            if (input == null) {
                break;
            }
            System.out.println(modifyString(input));
        }
    }

    /**
     * Modifies the input string to satisfy character type requirements.
     * 
     * Logic derived from original implementation:
     * 1. If string already has lower, upper, and digit -> return as is.
     * 2. If missing two types -> specific hardcoded replacement logic.
     * 3. If missing one type -> find dominant char type, replace first occurrence 
     *    with the missing character type.
     */
    private static String modifyString(String s) {
        int len = s.length();
        int lowerCount = 0;
        int upperCount = 0;
        int digitCount = 0;

        // Analyze string content using Character class methods (avoids magic numbers)
        for (int i = 0; i < len; i++) {
            char c = s.charAt(i);
            if (Character.isLowerCase(c)) {
                lowerCount++;
            } else if (Character.isUpperCase(c)) {
                upperCount++;
            } else if (Character.isDigit(c)) {
                digitCount++;
            }
        }

        boolean hasLower = lowerCount > 0;
        boolean hasUpper = upperCount > 0;
        boolean hasDigit = digitCount > 0;

        // Case 1: String already contains all required character types
        if (hasLower && hasUpper && hasDigit) {
            return s;
        }

        // Case 2: Missing two character types (Hardcoded logic from original)
        // Original: if missing Upper & Lower -> "Aa" + substring(2)
        if (!hasUpper && !hasLower) {
            return "Aa" + (len > 2 ? s.substring(2) : "");
        }
        // Original: if missing Digit & Lower -> "a0" + substring(2)
        if (!hasDigit && !hasLower) {
            return "a0" + (len > 2 ? s.substring(2) : "");
        }
        // Original: if missing Digit & Upper -> "A0" + substring(2)
        if (!hasDigit && !hasUpper) {
            return "A0" + (len > 2 ? s.substring(2) : "");
        }

        // Case 3: Missing exactly one character type
        // Determine the dominant character type to find the insertion point
        int dominantType = getDominantType(lowerCount, upperCount, digitCount);
        char charToInsert = getMissingChar(hasLower, hasUpper, hasDigit);

        // Find the index of the first occurrence of the dominant type
        int index = findFirstIndexOfType(s, dominantType);

        if (index != -1) {
            // Insert the missing character before the dominant character found.
            // Note: Original logic effectively replaced the character at 'index' 
            // by using s.substring(0, index) + put + s.substring(index + 1).
            return s.substring(0, index) + charToInsert + s.substring(index + 1);
        } else {
            // Fallback if dominant type not found (e.g., empty string)
            return s;
        }
    }

    /**
     * Determines the dominant character type based on counts.
     * Priority (based on original Math.max logic):
     * 1 = Lowercase
     * 2 = Uppercase
     * 3 = Digit
     */
    private static int getDominantType(int lower, int upper, int digit) {
        // Lower wins ties against Upper and Digit
        if (lower >= upper && lower >= digit) {
            return 1;
        }
        // Upper wins ties against Digit
        if (upper >= digit) {
            return 2;
        }
        return 3;
    }

    /**
     * Returns the character required to satisfy the missing type.
     */
    private static char getMissingChar(boolean hasLower, boolean hasUpper, boolean hasDigit) {
        if (!hasLower) return 'a';
        if (!hasUpper) return 'A';
        return '0';
    }

    /**
     * Finds the index of the first character matching the specified type.
     * Type: 1=Lower, 2=Upper, 3=Digit
     */
    private static int findFirstIndexOfType(String s, int type) {
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (type == 1 && Character.isLowerCase(c)) return i;
            if (type == 2 && Character.isUpperCase(c)) return i;
            if (type == 3 && Character.isDigit(c)) return i;
        }
        return -1;
    }
}

import java.util.Scanner;

public class Codechef {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        // Read the number of test cases
        if (scanner.hasNextInt()) {
            int numTestCases = scanner.nextInt();

            while (numTestCases-- > 0) {
                String inputString = scanner.next();
                processString(inputString);
            }
        }
        scanner.close();
    }

    /**
     * Processes the input string to ensure it contains at least one lowercase letter,
     * one uppercase letter, and one digit. If not, it modifies the string to satisfy
     * these requirements while preserving existing valid characters.
     */
    private static void processString(String s) {
        int length = s.length();
        int lowerCaseIndex = -1;
        int upperCaseIndex = -1;
        int digitIndex = -1;

        // Pass 1: Identify the indices of character types.
        // The original logic updates the index unconditionally, meaning it stores 
        // the index of the *last* occurrence of each character type found during iteration.
        for (int i = 0; i < length; i++) {
            char currentChar = s.charAt(i);

            // Replaced magic numbers (ASCII values) with standard Character methods
            if (Character.isLowerCase(currentChar)) {
                lowerCaseIndex = i;
            } else if (Character.isUpperCase(currentChar)) {
                upperCaseIndex = i;
            } else if (Character.isDigit(currentChar)) {
                digitIndex = i;
            }
        }

        // If all character types (lowercase, uppercase, digit) are present,
        // the string is valid. Print it and return.
        if (lowerCaseIndex >= 0 && upperCaseIndex >= 0 && digitIndex >= 0) {
            System.out.println(s);
        } else {
            // Pass 2: Modify the string to satisfy missing requirements.
            // We convert to char array to modify characters in place.
            char[] charArray = s.toCharArray();

            for (int i = 0; i < length; i++) {
                // If we are missing a lowercase letter:
                // Replace character at index i with 'a', provided i is not the index
                // of an already identified Uppercase or Digit character (to preserve them).
                if (lowerCaseIndex == -1 && i != upperCaseIndex && i != digitIndex) {
                    charArray[i] = 'a';
                    lowerCaseIndex = i; // Mark requirement as satisfied
                } 
                // If we are missing an uppercase letter:
                // Replace character at index i with 'A', provided i is not the index
                // of an already identified Lowercase or Digit character.
                else if (upperCaseIndex == -1 && i != lowerCaseIndex && i != digitIndex) {
                    charArray[i] = 'A';
                    upperCaseIndex = i;
                } 
                // If we are missing a digit:
                // Replace character at index i with '1', provided i is not the index
                // of an already identified Lowercase or Uppercase character.
                else if (digitIndex == -1 && i != lowerCaseIndex && i != upperCaseIndex) {
                    charArray[i] = '1';
                    digitIndex = i;
                }
                // Else: Keep the original character (already present in charArray)
            }

            System.out.println(new String(charArray));
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;

/**
 * A utility class to process strings (likely passwords) to ensure they contain
 * lowercase, uppercase, and digit characters.
 * 
 * Refactoring Notes:
 * 1. Naming: Renamed class and variables to be descriptive (e.g., 'A' -> 'PasswordEnforcer', 'c1' -> 'lowerCount').
 * 2. Structure: Extracted core logic into a separate method 'processInputString' for better readability and testing.
 * 3. Robustness: Added safety checks for array bounds and null inputs to prevent runtime exceptions.
 * 4. Resource Management: Used try-with-resources for automatic handling of the BufferedReader.
 * 5. Constants: Replaced magic characters ('a', 'A', '1') with named constants.
 */
public class PasswordEnforcer {

    // Constants for required character types
    private static final char LOWER_CASE = 'a';
    private static final char UPPER_CASE = 'A';
    private static final char DIGIT = '1';

    public static void main(String[] args) throws IOException {
        // Use try-with-resources to ensure the reader is closed automatically
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {

            String line = br.readLine();
            if (line == null) {
                return;
            }

            int testCases;
            try {
                testCases = Integer.parseInt(line.trim());
            } catch (NumberFormatException e) {
                System.err.println("Invalid input: Number of test cases must be an integer.");
                return;
            }

            StringBuilder resultBuilder = new StringBuilder();

            for (int t = 0; t < testCases; t++) {
                String input = br.readLine();
                if (input != null) {
                    String processed = processInputString(input.trim());
                    resultBuilder.append(processed).append("\n");
                }
            }

            // Print the accumulated results
            System.out.print(resultBuilder);
        }
    }

    /**
     * Analyzes the input string and modifies it to include at least one lowercase,
     * one uppercase, and one digit character.
     * 
     * @param input The raw string input
     * @return The modified string
     */
    private static String processInputString(String input) {
        char[] chars = input.toCharArray();
        int length = chars.length;

        // Counters for character types found
        int lowerCount = 0;
        int upperCount = 0;
        int digitCount = 0;

        // Indices of the *last* occurrence of each type
        int lastLowerIndex = -1;
        int lastUpperIndex = -1;
        int lastDigitIndex = -1;

        // Scan the string to count types and find last indices
        for (int i = 0; i < length; i++) {
            char c = chars[i];
            if (Character.isLowerCase(c)) {
                lowerCount++;
                lastLowerIndex = i;
            } else if (Character.isUpperCase(c)) {
                upperCount++;
                lastUpperIndex = i;
            } else if (Character.isDigit(c)) {
                digitCount++;
                lastDigitIndex = i;
            }
        }

        // Calculate how many distinct character types are present
        int presentTypes = 0;
        if (lowerCount > 0) presentTypes++;
        if (upperCount > 0) presentTypes++;
        if (digitCount > 0) presentTypes++;

        // Apply modification logic based on missing types
        if (presentTypes == 2) {
            // Exactly one type is missing.
            // We replace an existing character to introduce the missing type.
            if (lowerCount == 0) {
                // Missing lowercase ('a'). Replace last Upper or Digit.
                // Logic: Replace the type with higher count, or Digit if equal.
                if (upperCount > digitCount) {
                    chars[lastUpperIndex] = LOWER_CASE;
                } else {
                    chars[lastDigitIndex] = LOWER_CASE;
                }
            } else if (upperCount == 0) {
                // Missing uppercase ('A'). Replace last Lower or Digit.
                // Logic: Replace the type with higher count, or Digit if equal.
                if (lowerCount > digitCount) {
                    chars[lastLowerIndex] = UPPER_CASE;
                } else {
                    chars[lastDigitIndex] = UPPER_CASE;
                }
            } else {
                // Missing digit ('1'). Replace last Lower or Upper.
                // Logic: Replace the type with higher count, or Upper if equal.
                if (lowerCount > upperCount) {
                    chars[lastLowerIndex] = DIGIT;
                } else {
                    chars[lastUpperIndex] = DIGIT;
                }
            }
        } else if (presentTypes == 1) {
            // Only one type is present. Two are missing.
            // Original logic modifies indices 0 and 1 directly.
            // Added safety check to prevent IndexOutOfBoundsException on short strings.
            if (length >= 2) {
                if (lowerCount > 0) {
                    // Only lowercase present -> replace index 0 with Upper, 1 with Digit
                    chars[0] = UPPER_CASE;
                    chars[1] = DIGIT;
                } else if (upperCount > 0) {
                    // Only uppercase present -> replace index 0 with Lower, 1 with Digit
                    chars[0] = LOWER_CASE;
                    chars[1] = DIGIT;
                } else {
                    // Only digit present -> replace index 0 with Lower, 1 with Upper
                    chars[0] = LOWER_CASE;
                    chars[1] = UPPER_CASE;
                }
            }
        }

        return new String(chars);
    }
}

import java.io.*;
