public class Codeforces1059B {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        // Read grid dimensions
        if (!scanner.hasNextInt()) {
            return;
        }
        int numRows = scanner.nextInt();
        int numCols = scanner.nextInt();

        // Read the input grid
        char[][] originalGrid = new char[numRows][numCols];
        for (int i = 0; i < numRows; i++) {
            String line = scanner.next();
            // Convert the input string directly to a char array.
            // This assumes the input string length matches numCols.
            originalGrid[i] = line.toCharArray();
        }

        // Initialize the target grid with '.'
        char[][] generatedGrid = new char[numRows][numCols];
        for (int i = 0; i < numRows; i++) {
            Arrays.fill(generatedGrid[i], '.');
        }

        // Iterate through inner cells to check neighbors safely.
        // We start at index 1 and end at n-2 to ensure that accessing 
        // neighbors (r-1, r+1) does not go out of bounds.
        for (int r = 1; r < numRows - 1; r++) {
            for (int c = 1; c < numCols - 1; c++) {
                // Check if the current cell in the original grid allows signing.
                // Based on original logic: returns true if all 8 neighbors are NOT '.'.
                if (isSurroundedByNonDots(originalGrid, r, c)) {
                    // Mark the 8 neighbors in the generated grid as '#'
                    markNeighborsAsHash(generatedGrid, r, c);
                }
            }
        }

        // Compare the original grid with the generated grid
        if (Arrays.deepEquals(originalGrid, generatedGrid)) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }

        scanner.close();
    }

    /**
     * Checks if all 8 neighbors of the cell at (r, c) are not '.'.
     * This preserves the logic from the original 'canSign' method.
     * 
     * @param grid The grid to check
     * @param r    The row index of the center cell
     * @param c    The column index of the center cell
     * @return true if all neighbors are not '.', false otherwise
     */
    private static boolean isSurroundedByNonDots(char[][] grid, int r, int c) {
        for (int dr = -1; dr <= 1; dr++) {
            for (int dc = -1; dc <= 1; dc++) {
                // Skip the center cell itself
                if (dr == 0 && dc == 0) continue;

                // Check neighbor. Bounds are safe due to loop constraints in main.
                if (grid[r + dr][c + dc] == '.') {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Marks all 8 neighbors of the cell at (r, c) as '#' in the grid.
     * This preserves the logic from the original 'sign' method.
     * 
     * @param grid The grid to modify
     * @param r    The row index of the center cell
     * @param c    The column index of the center cell
     */
    private static void markNeighborsAsHash(char[][] grid, int r, int c) {
        for (int dr = -1; dr <= 1; dr++) {
            for (int dc = -1; dc <= 1; dc++) {
                // Skip the center cell itself
                if (dr == 0 && dc == 0) continue;

                grid[r + dr][c + dc] = '#';
            }
        }
    }
}

import java.util.Scanner;

/**
 * Solves a grid-based neighbor-checking problem.
 * Refactored to follow SOLID principles, improve readability, and reduce side effects.
 */
public class GridSolver {

    private boolean[][] grid;
    private boolean[][] checkGrid;
    private int rows;
    private int cols;

    public static void main(String[] args) {
        GridSolver solver = new GridSolver();
        solver.run();
    }

    /**
     * Orchestrates the solution flow: input -> processing -> output.
     */
    public void run() {
        readInput();
        processGrid();
        printResult();
    }

    /**
     * Reads grid dimensions and populates the input grid.
     */
    private void readInput() {
        try (Scanner scanner = new Scanner(System.in)) {
            if (!scanner.hasNextInt()) {
                return;
            }
            this.rows = scanner.nextInt();
            this.cols = scanner.nextInt();

            grid = new boolean[rows][cols];
            checkGrid = new boolean[rows][cols];

            for (int i = 0; i < rows; i++) {
                String line = scanner.next();
                for (int j = 0; j < cols; j++) {
                    grid[i][j] = line.charAt(j) == '#';
                }
            }
        }
    }

    /**
     * Applies the neighbor-marking logic to all non-border cells.
     */
    private void processGrid() {
        // Skip border cells to avoid out-of-bounds checks during neighbor traversal
        for (int i = 1; i < rows - 1; i++) {
            for (int j = 1; j < cols - 1; j++) {
                markSurroundedNeighbors(i, j);
            }
        }
    }

    /**
     * If all 8 surrounding cells in 'grid' are true, marks them true in 'checkGrid'.
     */
    private void markSurroundedNeighbors(int x, int y) {
        boolean allNeighborsPresent = true;

        // Phase 1: Validate condition
        for (int dx = -1; dx <= 1; dx++) {
            for (int dy = -1; dy <= 1; dy++) {
                if (dx == 0 && dy == 0) continue;
                if (!grid[x + dx][y + dy]) {
                    allNeighborsPresent = false;
                    break;
                }
            }
            if (!allNeighborsPresent) break;
        }

        // Phase 2: Apply transformation only if condition is met
        if (allNeighborsPresent) {
            for (int dx = -1; dx <= 1; dx++) {
                for (int dy = -1; dy <= 1; dy++) {
                    if (dx == 0 && dy == 0) continue;
                    checkGrid[x + dx][y + dy] = true;
                }
            }
        }
    }

    /**
     * Compares the original and processed grids, then prints the result.
     */
    private void printResult() {
        boolean identical = true;
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] != checkGrid[i][j]) {
                    identical = false;
                    break;
                }
            }
            if (!identical) break;
        }
        System.out.println(identical ? "YES" : "NO");
    }
}

