/**
 * Validates a grid to ensure every '#' character is completely surrounded
 * by '#' characters in all 8 neighboring cells (including diagonals).
 */
public class GridValidator {

    // Direction offsets for the 8 neighboring cells (row, col)
    private static final int[] DR = {-1, -1, -1, 0, 0, 1, 1, 1};
    private static final int[] DC = {-1, 0, 1, -1, 1, -1, 0, 1};

    public static void main(String[] args) {
        // try-with-resources ensures streams are properly closed regardless of exceptions
        try (FastScanner scanner = new FastScanner(System.in);
             PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out))) {

            int rows = scanner.nextInt();
            int cols = scanner.nextInt();

            char[][] grid = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                String line = scanner.next();
                grid[i] = line.toCharArray();
            }

            if (isGridValid(grid, rows, cols)) {
                out.println("YES");
            } else {
                out.println("NO");
            }

        } catch (IOException e) {
            System.err.println("I/O Error: " + e.getMessage());
        }
    }

    /**
     * Checks if every '#' in the grid satisfies the neighbor condition.
     */
    private static boolean isGridValid(char[][] grid, int rows, int cols) {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '#') {
                    if (!hasAllValidNeighbors(grid, r, c, rows, cols)) {
                        return false;
                    }
                }
            }
        }
        return true;
    }

    /**
     * Verifies that all 8 neighbors of (r, c) are within bounds and contain '#'.
     */
    private static boolean hasAllValidNeighbors(char[][] grid, int r, int c, int rows, int cols) {
        for (int i = 0; i < 8; i++) {
            int nr = r + DR[i];
            int nc = c + DC[i];

            // Check boundary conditions
            if (nr < 0 || nr >= rows || nc < 0 || nc >= cols) {
                return false;
            }
            // Check if neighbor is not '#'
            if (grid[nr][nc] != '#') {
                return false;
            }
        }
        return true;
    }

    /**
     * Fast input reader optimized for performance-critical tasks.
     * Replaces the original custom parser with a robust, standard implementation.
     */
    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner(InputStream input) {
            br = new BufferedReader(new InputStreamReader(input));
        }

        public String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) {
                        return null;
                    }
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input", e);
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            String token = next();
            if (token == null) {
                throw new RuntimeException("Unexpected end of input");
            }
            return Integer.parseInt(token);
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

/**
 * Refactored solution for the grid covering problem.
 * 
 * Improvements:
 * 1. Readability: Meaningful variable names (rows, cols, grid) instead of n, m, s.
 * 2. Modularity: Extracted loop logic into helper methods (hasDonutPattern, markDonut).
 * 3. Constants: Replaced magic numbers (3) with named constants.
 * 4. Separation of Concerns: Logic is separated from I/O.
 * 5. I/O: Simplified the InputReader to a standard FastScanner pattern.
 */
public class Main {

    // Constants to replace magic numbers
    private static final int GRID_SIZE = 3;
    private static final int CENTER_OFFSET = 1;

    public static void main(String[] args) {
        // Initialize Fast I/O
        FastScanner scanner = new FastScanner();
        PrintWriter out = new PrintWriter(System.out);

        try {
            // Read grid dimensions
            // Note: We assume valid input as per standard competitive programming constraints.
            if (!scanner.hasMoreTokens()) {
                return;
            }

            int rows = scanner.nextInt();
            int cols = scanner.nextInt();

            // Read the grid
            char[][] grid = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                String line = scanner.next();
                grid[i] = line.toCharArray();
            }

            // Solve the problem
            boolean isCovered = solve(rows, cols, grid);

            // Output result
            out.println(isCovered ? "YES" : "NO");

        } catch (Exception e) {
            e.printStackTrace();
        } finally {
            out.flush();
            out.close();
        }
    }

    /**
     * Solves the problem by checking for valid "donut" patterns and marking covered cells.
     * 
     * @param rows Number of rows in the grid
     * @param cols Number of columns in the grid
     * @param grid The character grid representing the map
     * @return true if all '#' characters are covered, false otherwise
     */
    private static boolean solve(int rows, int cols, char[][] grid) {
        // Array to track which cells are covered by a donut pattern
        boolean[][] covered = new boolean[rows][cols];

        // Iterate through every possible top-left corner of a 3x3 area.
        // A 3x3 area starting at (r, c) spans rows r to r+2 and cols c to c+2.
        // We stop at rows - 3 because the area needs 3 rows to fit.
        for (int r = 0; r <= rows - GRID_SIZE; r++) {
            for (int c = 0; c <= cols - GRID_SIZE; c++) {
                // Check if the current 3x3 area forms a valid donut (ring of '#')
                if (hasDonutPattern(grid, r, c)) {
                    // Mark the surrounding cells as covered
                    markDonut(covered, r, c);
                }
            }
        }

        // Verify that every '#' in the original grid is marked as covered
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '#' && !covered[r][c]) {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Checks if the 3x3 area starting at (startRow, startCol) contains '#' 
     * in all positions except the center.
     */
    private static boolean hasDonutPattern(char[][] grid, int startRow, int startCol) {
        for (int dr = 0; dr < GRID_SIZE; dr++) {
            for (int dc = 0; dc < GRID_SIZE; dc++) {
                // Skip the center cell of the 3x3 square
                if (dr == CENTER_OFFSET && dc == CENTER_OFFSET) {
                    continue;
                }

                // Check if the cell is a '#'
                // Bounds are guaranteed safe by the loop conditions in solve()
                if (grid[startRow + dr][startCol + dc] != '#') {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Marks the 8 surrounding cells of the 3x3 area starting at (startRow, startCol)
     * as covered in the boolean array.
     */
    private static void markDonut(boolean[][] covered, int startRow, int startCol) {
        for (int dr = 0; dr < GRID_SIZE; dr++) {
            for (int dc = 0; dc < GRID_SIZE; dc++) {
                if (dr == CENTER_OFFSET && dc == CENTER_OFFSET) {
                    continue;
                }
                covered[startRow + dr][startCol + dc] = true;
            }
        }
    }

    /**
     * A simplified FastScanner class for efficient input reading.
     */
    static class FastScanner {
        private BufferedReader br;
        private StringTokenizer st;

        public FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in), 1 << 15);
        }

        boolean hasMoreTokens() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) {
                        return false;
                    }
                    // Skip empty lines
                    if (line.trim().isEmpty()) {
                        continue;
                    }
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return true;
        }

        String next() {
            if (hasMoreTokens()) {
                return st.nextToken();
            }
            return null;
        }

        int nextInt() {
            String s = next();
            if (s == null) throw new RuntimeException("End of input");
            return Integer.parseInt(s);
        }
    }
}

import java.util.Scanner;

/**
 * Validates whether a grid of cells remains stable after two transformation steps.
 * Step 1: Marks cells that have exactly 8 marked neighbors.
 * Step 2: Marks all neighbors of the cells marked in Step 1.
 * The grid is valid if the final state matches the original grid.
 */
public class GridStabilityChecker {

    private static final int MARKED = 1;
    private static final int EMPTY = 0;
    private static final int TOTAL_NEIGHBORS = 8;

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            if (!scanner.hasNextInt()) {
                return;
            }

            int rows = scanner.nextInt();
            int cols = scanner.nextInt();

            int[][] originalGrid = readGrid(scanner, rows, cols);
            int[][] intermediateGrid = computeStepOne(originalGrid, rows, cols);
            int[][] finalGrid = computeStepTwo(intermediateGrid, rows, cols);

            if (areGridsIdentical(originalGrid, finalGrid)) {
                System.out.println("YES");
            } else {
                System.out.println("NO");
            }
        }
    }

    /**
     * Reads the grid from standard input.
     */
    private static int[][] readGrid(Scanner scanner, int rows, int cols) {
        int[][] grid = new int[rows][cols];
        scanner.nextLine(); // Consume the newline character after reading cols

        for (int i = 0; i < rows; i++) {
            String line = scanner.nextLine().trim();
            for (int j = 0; j < cols; j++) {
                grid[i][j] = (line.charAt(j) == '.') ? EMPTY : MARKED;
            }
        }
        return grid;
    }

    /**
     * Step 1: Marks cells that have exactly 8 marked neighbors.
     */
    private static int[][] computeStepOne(int[][] grid, int rows, int cols) {
        int[][] result = new int[rows][cols];
        for (int i = 1; i < rows - 1; i++) {
            for (int j = 1; j < cols - 1; j++) {
                if (countMarkedNeighbors(grid, i, j) == TOTAL_NEIGHBORS) {
                    result[i][j] = MARKED;
                }
            }
        }
        return result;
    }

    /**
     * Step 2: Marks all neighbors of cells marked in Step 1.
     */
    private static int[][] computeStepTwo(int[][] stepOneGrid, int rows, int cols) {
        int[][] result = new int[rows][cols];
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (stepOneGrid[i][j] == MARKED) {
                    markNeighbors(result, i, j);
                }
            }
        }
        return result;
    }

    /**
     * Marks all valid 8-connected neighbors of a cell in the target grid.
     */
    private static void markNeighbors(int[][] targetGrid, int row, int col) {
        for (int dr = -1; dr <= 1; dr++) {
            for (int dc = -1; dc <= 1; dc++) {
                if (dr == 0 && dc == 0) {
                    continue;
                }
                int newRow = row + dr;
                int newCol = col + dc;
                if (isValidCell(targetGrid, newRow, newCol)) {
                    targetGrid[newRow][newCol] = MARKED;
                }
            }
        }
    }

    /**
     * Counts the number of marked neighbors for a given cell.
     */
    private static int countMarkedNeighbors(int[][] grid, int row, int col) {
        int count = 0;
        for (int dr = -1; dr <= 1; dr++) {
            for (int dc = -1; dc <= 1; dc++) {
                if (dr == 0 && dc == 0) {
                    continue;
                }
                int newRow = row + dr;
                int newCol = col + dc;
                if (isValidCell(grid, newRow, newCol) && grid[newRow][newCol] == MARKED) {
                    count++;
                }
            }
        }
        return count;
    }

    /**
     * Checks if the given coordinates are within grid bounds.
     */
    private static boolean isValidCell(int[][] grid, int row, int col) {
        return row >= 0 && row < grid.length && col >= 0 && col < grid[0].length;
    }

    /**
     * Compares two grids for exact equality.
     */
    private static boolean areGridsIdentical(int[][] grid1, int[][] grid2) {
        for (int i = 0; i < grid1.length; i++) {
            for (int j = 0; j < grid1[0].length; j++) {
                if (grid1[i][j] != grid2[i][j]) {
                    return false;
                }
            }
        }
        return true;
    }
}

