public class CF1059B {
    // Direction vectors for the 8 adjacent neighbors (horizontal, vertical, diagonal)
    private static final int[] DX = {-1, -1, -1, 0, 0, 1, 1, 1};
    private static final int[] DY = {-1, 0, 1, -1, 1, -1, 0, 1};

    public static void main(String[] args) {
        FastReader reader = new FastReader();
        int rows = reader.nextInt();
        int cols = reader.nextInt();

        // Read the grid. Using next() is safer than nextLine() for competitive programming
        // as it automatically handles whitespace and newline variations.
        char[][] grid = new char[rows][];
        for (int i = 0; i < rows; i++) {
            grid[i] = reader.next().toCharArray();
        }

        // Boolean grid to mark valid centers. Default initialization is false.
        boolean[][] isCenter = new boolean[rows][cols];

        // Identify all valid centers
        // A center must not be on the boundary and all 8 neighbors must be '#'
        for (int i = 1; i < rows - 1; i++) {
            for (int j = 1; j < cols - 1; j++) {
                if (areAllNeighborsHash(grid, i, j, rows, cols)) {
                    isCenter[i][j] = true;
                }
            }
        }

        // Verify that every '#' is adjacent to at least one center
        boolean allHashCovered = true;
        outerLoop:
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == '#') {
                    if (!hasCenterNeighbor(isCenter, i, j, rows, cols)) {
                        allHashCovered = false;
                        break outerLoop;
                    }
                }
            }
        }

        System.out.println(allHashCovered ? "YES" : "NO");
    }

    /**
     * Checks if all 8 neighbors of (r, c) are '#'.
     * Assumes (r, c) is strictly internal (not on the boundary).
     */
    private static boolean areAllNeighborsHash(char[][] grid, int r, int c, int rows, int cols) {
        for (int k = 0; k < 8; k++) {
            int nr = r + DX[k];
            int nc = c + DY[k];
            if (grid[nr][nc] != '#') {
                return false;
            }
        }
        return true;
    }

    /**
     * Checks if any of the 8 neighbors of (r, c) is a marked center.
     */
    private static boolean hasCenterNeighbor(boolean[][] isCenter, int r, int c, int rows, int cols) {
        for (int k = 0; k < 8; k++) {
            int nr = r + DX[k];
            int nc = c + DY[k];
            if (isValid(nr, nc, rows, cols) && isCenter[nr][nc]) {
                return true;
            }
        }
        return false;
    }

    /**
     * Checks if coordinates are within grid boundaries.
     */
    private static boolean isValid(int r, int c, int rows, int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /**
     * Fast I/O helper class optimized for competitive programming.
     */
    static class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

