import java.util.Scanner;

public class GridValidator {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            return;
        }

        int rows = scanner.nextInt();
        int cols = scanner.nextInt();
        scanner.nextLine(); // Consume the newline after the column count

        char[][] grid = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            String line = scanner.nextLine();
            for (int j = 0; j < cols; j++) {
                grid[i][j] = line.charAt(j);
            }
        }

        if (isValidGrid(grid)) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }

        scanner.close();
    }

    /**
     * Validates that every '#' cell in the grid has at least one valid neighbor.
     * A valid neighbor is one whose surrounding 3x3 area (excluding its center)
     * is completely filled with '#' characters and within bounds.
     */
    private static boolean isValidGrid(char[][] grid) {
        int rows = grid.length;
        int cols = grid[0].length;

        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == '#') {
                    if (!hasValidNeighbor(grid, i, j)) {
                        return false;
                    }
                }
            }
        }
        return true;
    }

    /**
     * Checks if a '#' cell at (row, col) has at least one neighbor that satisfies
     * the 3x3 surrounding condition.
     */
    private static boolean hasValidNeighbor(char[][] grid, int row, int col) {
        int[] dr = {-1, -1, -1, 0, 0, 1, 1, 1};
        int[] dc = {-1, 0, 1, -1, 1, -1, 0, 1};

        for (int k = 0; k < 8; k++) {
            int nr = row + dr[k];
            int nc = col + dc[k];

            if (isValidPosition(grid, nr, nc) && isSurroundingFullOfHashes(grid, nr, nc)) {
                return true;
            }
        }
        return false;
    }

    /**
     * Verifies that all 8 cells surrounding (centerRow, centerCol) are within bounds
     * and contain the '#' character. The center cell itself is intentionally excluded
     * to match the original logic.
     */
    private static boolean isSurroundingFullOfHashes(char[][] grid, int centerRow, int centerCol) {
        int[] dr = {-1, -1, -1, 0, 0, 1, 1, 1};
        int[] dc = {-1, 0, 1, -1, 1, -1, 0, 1};

        for (int k = 0; k < 8; k++) {
            int r = centerRow + dr[k];
            int c = centerCol + dc[k];

            if (!isValidPosition(grid, r, c) || grid[r][c] != '#') {
                return false;
            }
        }
        return true;
    }

    /**
     * Checks if the given coordinates are within the grid boundaries.
     */
    private static boolean isValidPosition(char[][] grid, int row, int col) {
        return row >= 0 && row < grid.length && col >= 0 && col < grid[0].length;
    }
}

import java.io.*;
