public class TaskB {
    private static final char HASH_CHAR = '#';
    private static final String RESULT_YES = "YES";
    private static final String RESULT_NO = "NO";

    // Offsets for the 8 surrounding cells (row_delta, col_delta)
    private static final int[] DR = {-1, -1, -1, 0, 0, 1, 1, 1};
    private static final int[] DC = {-1, 0, 1, -1, 1, -1, 0, 1};

    public static void main(String[] args) {
        // Use try-with-resources to guarantee streams are closed properly
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
             PrintWriter out = new PrintWriter(System.out)) {

            FastScanner scanner = new FastScanner(br);
            int rows = scanner.nextInt();
            int cols = scanner.nextInt();

            char[][] grid = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                String line = br.readLine();
                if (line == null) break;
                grid[i] = line.toCharArray();
            }

            // Only inner cells can be centers. Java boolean arrays default to false.
            boolean[][] isCenterGrid = new boolean[rows][cols];
            for (int i = 1; i < rows - 1; i++) {
                for (int j = 1; j < cols - 1; j++) {
                    isCenterGrid[i][j] = isCenter(grid, i, j);
                }
            }

            boolean allHashNearCenter = true;
            outerLoop:
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j] == HASH_CHAR) {
                        if (!isNearCenter(isCenterGrid, i, j)) {
                            allHashNearCenter = false;
                            break outerLoop; // Early exit for performance
                        }
                    }
                }
            }

            out.println(allHashNearCenter ? RESULT_YES : RESULT_NO);
        } catch (IOException e) {
            throw new RuntimeException("Input/Output error", e);
        }
    }

    /**
     * Checks if the cell at (r, c) is the center of a 3x3 block of HASH_CHAR.
     * Assumes (r, c) is strictly inside the grid boundaries.
     */
    private static boolean isCenter(char[][] grid, int r, int c) {
        for (int k = 0; k < 8; k++) {
            if (grid[r + DR[k]][c + DC[k]] != HASH_CHAR) {
                return false;
            }
        }
        return true;
    }

    /**
     * Checks if the cell at (r, c) is a valid center.
     * A valid center must be strictly inside the grid and marked as a center.
     */
    private static boolean isValidCenter(boolean[][] isCenterGrid, int r, int c) {
        int rows = isCenterGrid.length;
        int cols = isCenterGrid[0].length;
        return r > 0 && r < rows - 1 &&
               c > 0 && c < cols - 1 &&
               isCenterGrid[r][c];
    }

    /**
     * Checks if any of the 8 neighboring cells is a valid center.
     */
    private static boolean isNearCenter(boolean[][] isCenterGrid, int r, int c) {
        for (int k = 0; k < 8; k++) {
            if (isValidCenter(isCenterGrid, r + DR[k], c + DC[k])) {
                return true;
            }
        }
        return false;
    }

    /**
     * Fast I/O helper class for competitive programming style input.
     */
    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner(BufferedReader br) {
            this.br = br;
        }

        public String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public double nextDouble() {
            return Double.parseDouble(next());
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

public class Main {
    public static void main(String[] args) {
        FastScanner in = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out);
        new GridPatternSolver().solve(in, out);
        out.flush();
    }

    /**
     * Solves the grid pattern coverage problem.
     * Checks if all '#' characters can be covered by 3x3 squares 
     * (specifically, the 8 perimeter cells of each square must be '#').
     */
    static class GridPatternSolver {
        public void solve(FastScanner in, PrintWriter out) {
            int rows = in.nextInt();
            int cols = in.nextInt();

            char[][] grid = new char[rows][cols];
            boolean[][] covered = new boolean[rows][cols];

            // Read the grid
            for (int i = 0; i < rows; i++) {
                String line = in.next();
                grid[i] = line.toCharArray();
            }

            // Verify each '#' is covered by at least one valid 3x3 square
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] == '#' && !covered[r][c]) {
                        boolean isCovered = false;

                        // A '#' at (r, c) can be part of a 3x3 square starting at:
                        // (r-2, c-2), (r, c), (r, c-2), or (r-2, c)
                        int[] topRows = {r - 2, r, r, r - 2};
                        int[] leftCols = {c - 2, c, c - 2, c};

                        for (int k = 0; k < 4; k++) {
                            if (canPlaceSquare(grid, covered, rows, cols, topRows[k], leftCols[k])) {
                                isCovered = true;
                                break; // Early exit: one valid square is enough
                            }
                        }

                        if (!isCovered) {
                            out.println("NO");
                            return;
                        }
                    }
                }
            }
            out.println("YES");
        }

        /**
         * Checks if a 3x3 square with the given top-left corner can be placed.
         * All 8 perimeter cells must be '#'. The center cell is ignored.
         * If valid, marks the perimeter cells as covered.
         */
        private boolean canPlaceSquare(char[][] grid, boolean[][] covered, int rows, int cols, int topRow, int leftCol) {
            // Boundary check for a 3x3 square
            if (topRow < 0 || topRow + 2 >= rows || leftCol < 0 || leftCol + 2 >= cols) {
                return false;
            }

            boolean canPlace = true;
            // Verify all 8 perimeter cells are '#'
            for (int dr = 0; dr < 3; dr++) {
                for (int dc = 0; dc < 3; dc++) {
                    if (dr == 1 && dc == 1) continue; // Skip center cell
                    if (grid[topRow + dr][leftCol + dc] != '#') {
                        canPlace = false;
                        break;
                    }
                }
                if (!canPlace) break;
            }

            if (canPlace) {
                // Mark perimeter cells as covered
                for (int dr = 0; dr < 3; dr++) {
                    for (int dc = 0; dc < 3; dc++) {
                        if (dr == 1 && dc == 1) continue;
                        covered[topRow + dr][leftCol + dc] = true;
                    }
                }
            }
            return canPlace;
        }
    }

    /**
     * Fast and maintainable input reader using BufferedReader and StringTokenizer.
     * Replaces the custom, overly complex InputReader from the original code.
     */
    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        public String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input", e);
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            String token = next();
            return token == null ? 0 : Integer.parseInt(token);
        }
    }
}

