            for (int row = 0; row < n; row++) {
                for (int col = 0; col < m; col++) {
                    if (isWithinBounds(row, col, n, m) &&
                        inputGrid[row][col] == '#' &&
                        containsDot(resultGrid, row, col) &&
                        !containsDot(inputGrid, row, col)) {

                        markPattern(resultGrid, row, col);
                    }
                }
            }

            // Compare input and result grids
            if (gridsMatch(inputGrid, resultGrid)) {
                System.out.println("YES");
            } else {
                System.out.println("NO");
            }
        }
    }

    /**
     * Checks if a 3x3 pattern starting at (r, c) fits within the grid boundaries.
     */
    private static boolean isWithinBounds(int r, int c, int n, int m) {
        return r >= 0 && r + PATTERN_SIZE - 1 < n &&
               c >= 0 && c + PATTERN_SIZE - 1 < m;
    }

    /**
     * Checks if any of the 8 surrounding cells in the 3x3 block contains a '.'.
     */
    private static boolean containsDot(char[][] grid, int r, int c) {
        for (int[] offset : PATTERN_OFFSETS) {
            if (grid[r + offset[0]][c + offset[1]] == '.') {
                return true;
            }
        }
        return false;
    }

    /**
     * Marks the 8 surrounding cells of the 3x3 block with '#' in the result grid.
     */
    private static void markPattern(char[][] grid, int r, int c) {
        for (int[] offset : PATTERN_OFFSETS) {
            grid[r + offset[0]][c + offset[1]] = '#';
        }
    }

    /**
     * Compares two 2D character grids for equality.
     */
    private static boolean gridsMatch(char[][] grid1, char[][] grid2) {
        for (int i = 0; i < grid1.length; i++) {
            if (!Arrays.equals(grid1[i], grid2[i])) {
                return false;
            }
        }
        return true;
    }
}

