import java.io.*;
import java.util.*;

public class Main {
    private static final int BLOCK_SIZE = 3;

    public static void main(String[] args) {
        InputReader in = new InputReader(System.in);
        OutputWriter out = new OutputWriter(System.out);
        try {
            int n = in.nextInt();
            int m = in.nextInt();
            char[][] grid = readGrid(in, n, m);

            boolean result = solve(grid, n, m);
            out.printLine(result ? "YES" : "NO");
        } finally {
            out.flush();
        }
    }

    /**
     * Reads the grid dimensions and populates the 2D character array.
     */
    private static char[][] readGrid(InputReader in, int n, int m) {
        char[][] grid = new char[n][m];
        for (int i = 0; i < n; i++) {
            grid[i] = in.readString().toCharArray();
        }
        return grid;
    }

    /**
     * Validates whether all '#' characters in the grid are covered by at least one 
     * complete 3x3 block of '#' characters.
     */
    private static boolean solve(char[][] grid, int n, int m) {
        boolean[][] visited = new boolean[n][m];
        int halfSize = BLOCK_SIZE / 2; // Equals 1

        // Iterate over all valid 3x3 block centers
        for (int i = halfSize; i < n - halfSize; i++) {
            for (int j = halfSize; j < m - halfSize; j++) {
                if (grid[i][j] == '#') {
                    boolean isFullBlock = true;

                    // Check if the 3x3 block centered at (i, j) consists entirely of '#'
                    for (int di = -1; di <= 1; di++) {
                        for (int dj = -1; dj <= 1; dj++) {
                            if (grid[i + di][j + dj] != '#') {
                                isFullBlock = false;
                                break;
                            }
                        }
                        if (!isFullBlock) break;
                    }

                    // If valid, mark all 9 cells in the block as visited
                    if (isFullBlock) {
                        for (int di = -1; di <= 1; di++) {
                            for (int dj = -1; dj <= 1; dj++) {
                                visited[i + di][j + dj] = true;
                            }
                        }
                    }
                }
            }
        }

        // Verify that every '#' in the grid has been covered
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == '#' && !visited[i][j]) {
                    return false;
                }
            }
        }
        return true;
    }

    // -----------------------------------------------------------------------
    // Standard Competitive Programming I/O Utilities
    // -----------------------------------------------------------------------
    static class InputReader {
        private final InputStream stream;
        private final byte[] buf = new byte[8192];
        private int curChar, snumChars;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        public int read() {
            if (snumChars == -1) {
                throw new InputMismatchException();
            }
            if (curChar >= snumChars) {
                curChar = 0;
                try {
                    snumChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (snumChars <= 0) {
                    return -1;
                }
            }
            return buf[curChar++];
        }

        public int nextInt() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            int res = 0;
            do {
                res *= 10;
                res += c - '0';
                c = read();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public long nextLong() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            long res = 0;
            do {
                res *= 10;
                res += c - '0';
                c = read();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public int[] nextIntArray(int n) {
            int[] a = new int[n];
            for (int i = 0; i < n; i++) {
                a[i] = nextInt();
            }
            return a;
        }

        public String readString() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            StringBuilder res = new StringBuilder();
            do {
                res.appendCodePoint(c);
                c = read();
            } while (!isSpaceChar(c));
            return res.toString();
        }

        public String nextLine() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            StringBuilder res = new StringBuilder();
            do {
                res.appendCodePoint(c);
                c = read();
            } while (!isEndOfLine(c));
            return res.toString();
        }

        public boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        private boolean isEndOfLine(int c) {
            return c == '\n' || c == '\r' || c == -1;
        }
    }

    static class OutputWriter {
        private final PrintWriter writer;

        public OutputWriter(OutputStream outputStream) {
            writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(outputStream)));
        }

        public OutputWriter(Writer writer) {
            this.writer = new PrintWriter(writer);
        }

        public void print(Object... objects) {
            for (int i = 0; i < objects.length; i++) {
                if (i != 0) {
                    writer.print(' ');
                }
                writer.print(objects[i]);
            }
        }

        public void printLine(Object... objects) {
            print(objects);
            writer.println();
        }

        public void close() {
            writer.close();
        }

        public void flush() {
            writer.flush();
        }
    }
}

