    private static final int[] DX = {-1, -1, -1, 0, 1, 1, 1, 0};
    private static final int[] DY = {-1, 0, 1, 1, 1, 0, -1, -1};

    public static void main(String[] args) {
        // Try-with-resources ensures proper cleanup of I/O streams
        try (FastScanner scanner = new FastScanner(System.in);
             PrintWriter out = new PrintWriter(System.out)) {
            solve(scanner, out);
        } catch (IOException e) {
            throw new RuntimeException("Failed to read input", e);
        }
    }

    private static void solve(FastScanner scanner, PrintWriter out) {
        String nStr = scanner.next();
        if (nStr == null) return;
        int n = Integer.parseInt(nStr);
        int m = scanner.nextInt();

        char[][] grid = new char[n][m];
        for (int i = 0; i < n; i++) {
            grid[i] = scanner.next().toCharArray();
        }

        boolean[][] covered = new boolean[n][m];

        // Identify all 3x3 blocks of '#' and mark their neighbors as covered
        for (int i = 1; i < n - 1; i++) {
            for (int j = 1; j < m - 1; j++) {
                if (isFullBlock(grid, i, j)) {
                    markNeighbors(covered, i, j);
                }
            }
        }

        // Verify that every '#' is covered by at least one valid 3x3 block
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == '#' && !covered[i][j]) {
                    out.println("NO");
                    return;
                }
            }
        }
        out.println("YES");
    }

    /**
     * Checks if all 8 neighbors of (r, c) are '#'.
     */
    private static boolean isFullBlock(char[][] grid, int r, int c) {
        for (int k = 0; k < 8; k++) {
            if (grid[r + DX[k]][c + DY[k]] != '#') {
                return false;
            }
        }
        return true;
    }

    /**
     * Marks all 8 neighbors of (r, c) as covered.
     */
    private static void markNeighbors(boolean[][] covered, int r, int c) {
        for (int k = 0; k < 8; k++) {
            covered[r + DX[k]][c + DY[k]] = true;
        }
    }

