/**
 * Validates a grid pattern based on neighbor coverage rules.
 * A '#' character is valid only if it is part of at least one 3x3 block
 * where all 8 surrounding neighbors are also '#'.
 */
public class ForgeryChecker {

    // Direction vectors for the 8 neighbors (row offset, col offset)
    private static final int[] DR = {-1, -1, -1, 0, 0, 1, 1, 1};
    private static final int[] DC = {-1, 0, 1, -1, 1, -1, 0, 1};

    public static void main(String[] args) {
        new ForgeryChecker().run();
    }

    public void run() {
        FastScanner scanner = new FastScanner();
        int n = scanner.nextInt();
        int m = scanner.nextInt();

        char[][] grid = new char[n][];
        for (int i = 0; i < n; i++) {
            grid[i] = scanner.next().toCharArray();
        }

        // Tracks which '#' cells are covered by a valid 3x3 pattern
        boolean[][] isCovered = new boolean[n][m];

        // Check every non-border cell as a potential center of a 3x3 pattern
        for (int i = 1; i < n - 1; i++) {
            for (int j = 1; j < m - 1; j++) {
                if (areAllNeighborsHash(grid, i, j)) {
                    markNeighborsAsCovered(isCovered, i, j);
                }
            }
        }

        // Verify that every '#' in the grid is covered
        boolean allHashesCovered = true;
        outer:
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == '#' && !isCovered[i][j]) {
                    allHashesCovered = false;
                    break outer;
                }
            }
        }

        System.out.println(allHashesCovered ? "YES" : "NO");
    }

    /**
     * Checks if all 8 neighbors of a given cell are '#'.
     */
    private static boolean areAllNeighborsHash(char[][] grid, int row, int col) {
        for (int k = 0; k < 8; k++) {
            if (grid[row + DR[k]][col + DC[k]] != '#') {
                return false;
            }
        }
        return true;
    }

    /**
     * Marks all 8 neighbors of a given cell as covered.
     */
    private static void markNeighborsAsCovered(boolean[][] isCovered, int row, int col) {
        for (int k = 0; k < 8; k++) {
            isCovered[row + DR[k]][col + DC[k]] = true;
        }
    }

    /**
     * High-performance input reader for competitive programming / large inputs.
     */
    private static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) {
                        throw new IOException("Unexpected end of input");
                    }
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.util.Scanner;

public class Main {
    // Define the block size as a constant for clarity and easy modification
    private static final int BLOCK_SIZE = 3;

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        // Read grid dimensions
        if (!scanner.hasNextInt()) {
            return;
        }
        int rows = scanner.nextInt();
        int cols = scanner.nextInt();

        // Use char[][] for efficient 2D access
        char[][] grid = new char[rows][cols];

        // Read the grid input
        for (int r = 0; r < rows; r++) {
            String line = scanner.next();
            // Fill the row with characters from the input string
            for (int c = 0; c < cols && c < line.length(); c++) {
                grid[r][c] = line.charAt(c);
            }
        }

        // Array to keep track of which '#' cells are covered by a valid block
        boolean[][] isCovered = new boolean[rows][cols];

        // Iterate through all possible top-left corners of 3x3 blocks.
        // A block starting at (r, c) occupies rows [r, r+2] and cols [c, c+2].
        for (int r = 0; r <= rows - BLOCK_SIZE; r++) {
            for (int c = 0; c <= cols - BLOCK_SIZE; c++) {
                // Check if the current 3x3 block is valid (all cells are '#')
                if (isBlockValid(grid, r, c)) {
                    // Mark all cells in this valid block as covered
                    markBlockCovered(isCovered, r, c);
                }
            }
        }

        // Verify that every '#' in the grid is covered by at least one block
        boolean allCovered = true;
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '#' && !isCovered[r][c]) {
                    allCovered = false;
                    break;
                }
            }
            if (!allCovered) {
                break;
            }
        }

        // Output the result
        System.out.println(allCovered ? "YES" : "NO");

        scanner.close();
    }

    /**
     * Checks if a 3x3 block starting at (r, c) consists entirely of '#' characters.
     *
     * @param grid The 2D character array representing the grid.
     * @param r    The starting row index of the block.
     * @param c    The starting column index of the block.
     * @return true if all 9 cells in the block are '#', false otherwise.
     */
    private static boolean isBlockValid(char[][] grid, int r, int c) {
        for (int i = 0; i < BLOCK_SIZE; i++) {
            for (int j = 0; j < BLOCK_SIZE; j++) {
                if (grid[r + i][c + j] != '#') {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Marks all cells in the 3x3 block starting at (r, c) as covered.
     *
     * @param covered The 2D boolean array tracking coverage.
     * @param r       The starting row index of the block.
     * @param c       The starting column index of the block.
     */
    private static void markBlockCovered(boolean[][] covered, int r, int c) {
        for (int i = 0; i < BLOCK_SIZE; i++) {
            for (int j = 0; j < BLOCK_SIZE; j++) {
                covered[r + i][c + j] = true;
            }
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.OutputStream;
import java.io.PrintWriter;
import java.util.StringTokenizer;

/**
 * Main class for the solution.
 * Refactored to improve maintainability, code quality, and performance.
 * 
 * Key Improvements:
 * 1. Separated logic into a dedicated GridSolver class.
 * 2. Optimized the core algorithm from O(N*M*9) to O(N*M).
 * 3. Replaced String manipulation with char[][] for faster access.
 * 4. Improved InputReader robustness and readability.
 * 5. Added comprehensive documentation and comments.
 */
public class Main {

    public static void main(String[] args) {
        // Initialize I/O streams
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;

        // Use fast I/O helper
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);

        // Execute the solver logic
        GridSolver solver = new GridSolver();
        solver.solve(in, out);

        // Ensure output is flushed and closed
        out.close();
    }

    /**
     * Encapsulates the logic for solving the grid problem.
     */
    static class GridSolver {
        private static final int PATTERN_SIZE = 3;

        /**
         * Solves the problem for a single test case.
         */
        public void solve(InputReader in, PrintWriter out) {
            // Read dimensions n and m
            String nStr = in.next();
            if (nStr == null) return; // Handle empty input gracefully
            int n = Integer.parseInt(nStr);
            int m = in.nextInt();

            // Read the grid into a char array for faster access
            char[][] grid = new char[n][];
            for (int i = 0; i < n; i++) {
                String row = in.next();
                grid[i] = row.toCharArray();
            }

            // Array to track which '#' cells are covered by at least one pattern placement
            boolean[][] covered = new boolean[n][m];

            // Iterate through all valid top-left positions (r, c) for the 3x3 pattern.
            // A 3x3 pattern starting at (r, c) occupies rows r to r+2 and columns c to c+2.
            // Thus, valid r ranges from 0 to n-3, and valid c ranges from 0 to m-3.
            for (int r = 0; r <= n - PATTERN_SIZE; r++) {
                for (int c = 0; c <= m - PATTERN_SIZE; c++) {
                    // Check if the pattern fits at this position
                    if (matchesPattern(grid, r, c)) {
                        // If it fits, mark the covered cells in the boolean array
                        markCovered(covered, r, c);
                    }
                }
            }

            // Verification step: Check if every '#' in the original grid is covered
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    // If a cell is '#' in the grid but not marked as covered, the answer is NO
                    if (grid[i][j] == '#' && !covered[i][j]) {
                        out.println("NO");
                        return;
                    }
                }
            }

            // If all '#' cells are covered, the answer is YES
            out.println("YES");
        }

        /**
         * Checks if the 3x3 pattern fits at grid[r][c].
         * 
         * The pattern is:
         * ###
         * #.#
         * ###
         * 
         * This means the 8 surrounding cells of the center (r+1, c+1) must contain '#'.
         * The center cell (r+1, c+1) corresponds to the '.' in the pattern and is ignored
         * during the check (it can be anything).
         */
        private boolean matchesPattern(char[][] grid, int r, int c) {
            // Check Top Row
            if (grid[r][c] != '#') return false;
            if (grid[r][c + 1] != '#') return false;
            if (grid[r][c + 2] != '#') return false;

            // Check Middle Row (skip center at c+1)
            if (grid[r + 1][c] != '#') return false;
            // Hole at grid[r + 1][c + 1] is ignored
            if (grid[r + 1][c + 2] != '#') return false;

            // Check Bottom Row
            if (grid[r + 2][c] != '#') return false;
            if (grid[r + 2][c + 1] != '#') return false;
            if (grid[r + 2][c + 2] != '#') return false;

            return true;
        }

        /**
         * Marks the cells covered by the pattern at grid[r][c] as true in the covered array.
         * The center cell (r+1, c+1) is a hole in the pattern and is NOT marked.
         */
        private void markCovered(boolean[][] covered, int r, int c) {
            // Top Row
            covered[r][c] = true;
            covered[r][c + 1] = true;
            covered[r][c + 2] = true;

            // Middle Row (skip center)
            covered[r + 1][c] = true;
            // Hole at covered[r + 1][c + 1] remains false
            covered[r + 1][c + 2] = true;

            // Bottom Row
            covered[r + 2][c] = true;
            covered[r + 2][c + 1] = true;
            covered[r + 2][c + 2] = true;
        }
    }

    /**
     * Helper class for fast input reading.
     */
    static class InputReader {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        /**
         * Reads the next token from the input.
         * @return The next token string, or null if end of stream.
         */
        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return tokenizer.nextToken();
        }

        /**
         * Reads the next integer token.
         * @return The next integer.
         */
        public int nextInt() {
            String s = next();
            if (s == null) throw new RuntimeException("Unexpected end of input");
            return Integer.parseInt(s);
        }
    }
}

