import java.util.ArrayDeque;
import java.util.Map;
import java.util.StringTokenizer;
import java.util.TreeMap;

public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        PalindromeMatrixSolver solver = new PalindromeMatrixSolver();
        solver.solve(in, out);
        out.close();
    }

    /**
     * Solves the palindrome matrix construction problem.
     * Organizes input reading, validation, matrix filling, and output.
     */
    static class PalindromeMatrixSolver {
        public void solve(InputReader in, PrintWriter out) {
            int n = in.nextInt();
            if (n == 1) {
                out.println("YES");
                out.println(in.nextInt());
                return;
            }

            int[] freq = new int[2000];
            int totalElements = n * n;
            for (int i = 0; i < totalElements; i++) {
                freq[in.nextInt()]++;
            }

            // Group values by their frequency for efficient retrieval
            TreeMap<Integer, ArrayDeque<CountedValue>> counts = new TreeMap<>();
            for (int val = 0; val < freq.length; val++) {
                if (freq[val] > 0) {
                    counts.computeIfAbsent(freq[val], k -> new ArrayDeque<>())
                          .offer(new CountedValue(val, freq[val]));
                }
            }

            int[][] matrix = new int[n][n];

            if (!fillQuadrants(n, matrix, counts)) {
                out.println("NO");
                return;
            }

            if (n % 2 == 1) {
                if (!fillEdges(n, matrix, counts)) {
                    out.println("NO");
                    return;
                }
                if (!fillCenter(n, matrix, counts)) {
                    out.println("NO");
                    return;
                }
            }

            out.println("YES");
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < n; j++) {
                    out.print(matrix[i][j] + (j == n - 1 ? "" : " "));
                }
                out.println();
            }
        }

        private boolean fillQuadrants(int n, int[][] matrix, TreeMap<Integer, ArrayDeque<CountedValue>> counts) {
            ValueProvider provider = new ValueProvider(counts, 4);
            for (int i = 0; i < n / 2; i++) {
                for (int j = 0; j < n / 2; j++) {
                    CountedValue val = provider.next();
                    if (val == null) return false;
                    matrix[i][j] = matrix[n - 1 - i][j] = matrix[i][n - 1 - j] = matrix[n - 1 - i][n - 1 - j] = val.value;
                    provider.use(val);
                }
            }
            return true;
        }

        private boolean fillEdges(int n, int[][] matrix, TreeMap<Integer, ArrayDeque<CountedValue>> counts) {
            ValueProvider provider = new ValueProvider(counts, 2);
            int mid = n / 2;

            // Fill vertical middle column
            for (int i = 0; i < n / 2; i++) {
                CountedValue val = provider.next();
                if (val == null) return false;
                matrix[i][mid] = matrix[n - 1 - i][mid] = val.value;
                provider.use(val);
            }

            // Fill horizontal middle row
            for (int i = 0; i < n / 2; i++) {
                CountedValue val = provider.next();
                if (val == null) return false;
                matrix[mid][i] = matrix[mid][n - 1 - i] = val.value;
                provider.use(val);
            }
            return true;
        }

        private boolean fillCenter(int n, int[][] matrix, TreeMap<Integer, ArrayDeque<CountedValue>> counts) {
            ValueProvider provider = new ValueProvider(counts, 1);
            int mid = n / 2;
            CountedValue val = provider.next();
            if (val == null) return false;
            matrix[mid][mid] = val.value;
            provider.use(val);
            return true;
        }

        /**
         * Manages fetching and decrementing values from the frequency TreeMap.
         * Optimizes performance by reusing the same value across iterations 
         * until its remaining count no longer satisfies the requirement.
         */
        private static class ValueProvider {
            private final TreeMap<Integer, ArrayDeque<CountedValue>> tree;
            private final int required;
            private ArrayDeque<CountedValue> currentQueue;
            private CountedValue currentValue;

            public ValueProvider(TreeMap<Integer, ArrayDeque<CountedValue>> tree, int required) {
                this.tree = tree;
                this.required = required;
            }

            public CountedValue next() {
                if (currentValue == null || currentValue.count == 0) {
                    Map.Entry<Integer, ArrayDeque<CountedValue>> entry = tree.ceilingEntry(required);
                    if (entry == null) return null;

                    currentQueue = entry.getValue();
                    currentValue = currentQueue.poll();
                    if (currentQueue.isEmpty()) {
                        tree.remove(entry.getKey());
                    }
                }
                return currentValue;
            }

            public void use(CountedValue val) {
                if (val == null) return;

                val.count -= required;
                if (val.count > 0 && val.count < required) {
                    tree.computeIfAbsent(val.count, k -> new ArrayDeque<>()).offer(val);
                    currentValue = null;
                } else if (val.count == 0) {
                    currentValue = null;
                }
            }
        }

        private static class CountedValue {
            final int value;
            int count;

            CountedValue(int value, int count) {
                this.value = value;
                this.count = count;
            }
        }
    }

    static class InputReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public InputReader(InputStream in) {
            reader = new BufferedReader(new InputStreamReader(in));
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                tokenizer = new StringTokenizer(readLine());
            }
            return tokenizer.nextToken();
        }

        public String readLine() {
            String line;
            try {
                line = reader.readLine();
            } catch (IOException e) {
                throw new RuntimeException(e);
            }
            return line;
        }
    }
}

import java.util.Scanner;

public class C_PalindromicMatrix {

    private static final int MAX_VALUE = 1001;

    public static void main(String[] args) {
        // Use try-with-resources for automatic Scanner cleanup
        try (Scanner sc = new Scanner(System.in)) {
            if (!sc.hasNextInt()) return;

            int n = sc.nextInt();
            int[] counts = new int[MAX_VALUE];

            // Read input and populate frequency array
            for (int i = 0; i < n * n; i++) {
                if (sc.hasNextInt()) {
                    counts[sc.nextInt()]++;
                }
            }

            // Validate, construct, and output
            if (isValid(counts, n)) {
                System.out.println("YES");
                int[][] matrix = buildMatrix(counts, n);
                printMatrix(matrix);
            } else {
                System.out.println("NO");
            }
        }
    }

    /**
     * Validates if the given frequency counts can form a palindromic matrix of size n x n.
     * A palindromic matrix requires 4-way symmetry for quadrants, 2-way symmetry for 
     * middle rows/columns (if n is odd), and exactly one center element (if n is odd).
     */
    private static boolean isValid(int[] counts, int n) {
        int m = n / 2;
        int[] temp = counts.clone();

        int qNeeded = m * m;
        int rNeeded = (n % 2 == 0) ? 0 : m;
        int cNeeded = (n % 2 == 0) ? 0 : m;
        int centerNeeded = (n % 2 == 0) ? 0 : 1;

        int qGot = 0, rGot = 0, cGot = 0, centerGot = 0;

        // Greedily drain counts into required slots
        for (int val = 1; val < temp.length; val++) {
            while (temp[val] >= 4 && qGot < qNeeded) {
                temp[val] -= 4;
                qGot++;
            }
            while (temp[val] >= 2 && rGot < rNeeded) {
                temp[val] -= 2;
                rGot++;
            }
            while (temp[val] >= 2 && cGot < cNeeded) {
                temp[val] -= 2;
                cGot++;
            }
            if (temp[val] == 1 && centerGot < centerNeeded) {
                temp[val] = 0;
                centerGot++;
            }
        }

        // If any counts remain, the distribution is invalid
        for (int c : temp) {
            if (c > 0) return false;
        }

        return qGot == qNeeded && rGot == rNeeded && cGot == cNeeded && centerGot == centerNeeded;
    }

    /**
     * Constructs the palindromic matrix based on validated frequency counts.
     */
    private static int[][] buildMatrix(int[] counts, int n) {
        int m = n / 2;
        int[] tempCounts = counts.clone();
        int[][] quadrant = new int[m][m];
        int[] rowVals = new int[m];
        int[] colVals = new int[m];
        int center = 0;

        int qIdx = 0, rIdx = 0, cIdx = 0;

        // Distribute values into quadrant, middle row, middle column, and center
        for (int val = 1; val < tempCounts.length; val++) {
            while (tempCounts[val] >= 4 && qIdx < m * m) {
                quadrant[qIdx / m][qIdx % m] = val;
                tempCounts[val] -= 4;
                qIdx++;
            }
            while (tempCounts[val] >= 2 && rIdx < m) {
                rowVals[rIdx] = val;
                tempCounts[val] -= 2;
                rIdx++;
            }
            while (tempCounts[val] >= 2 && cIdx < m) {
                colVals[cIdx] = val;
                tempCounts[val] -= 2;
                cIdx++;
            }
            if (tempCounts[val] == 1) {
                center = val;
                tempCounts[val] = 0;
            }
        }

        int[][] result = new int[n][n];

        // Fill matrix using 4-way symmetry for the top-left quadrant
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < m; j++) {
                int val = quadrant[i][j];
                result[i][j] = val;
                result[i][n - 1 - j] = val;
                result[n - 1 - i][j] = val;
                result[n - 1 - i][n - 1 - j] = val;
            }
        }

        // Fill middle row and column for odd-sized matrices
        if (n % 2 != 0) {
            for (int i = 0; i < m; i++) {
                result[m][i] = rowVals[i];
                result[m][n - 1 - i] = rowVals[i];
                result[i][m] = colVals[i];
                result[n - 1 - i][m] = colVals[i];
            }
            result[m][m] = center;
        }

        return result;
    }

    /**
     * Prints the matrix to standard output.
     */
    private static void printMatrix(int[][] matrix) {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < matrix.length; i++) {
            for (int j = 0; j < matrix[i].length; j++) {
                sb.append(matrix[i][j]).append(j == matrix[i].length - 1 ? "" : " ");
            }
            sb.append("\n");
        }
        System.out.print(sb);
    }
}

import java.io.*;
import java.util.*;

/**
 * Refactored Palindromic Matrix Builder.
 * 
 * Key Improvements:
 * 1. Removed global static state: Instance variables ensure thread-safety and testability.
 * 2. Separated concerns: Validation, construction, and I/O are handled in distinct methods.
 * 3. Improved performance: Used StringBuilder for output and HashMap.merge for counting.
 * 4. Enhanced readability: Extracted symmetry-filling logic, used descriptive names, and added comments.
 * 5. Robust I/O: InputReader handles edge cases gracefully; output is buffered.
 */
public class PalindromicMatrix {

    private final int n;
    private final int[][] matrix;
    private final Map<Integer, Integer> frequencyMap;

    public PalindromicMatrix(int n) {
        this.n = n;
        this.matrix = new int[n][n];
        this.frequencyMap = new HashMap<>();
    }

    /**
     * Orchestrates reading input, validating feasibility, constructing the matrix,
     * and printing the result.
     */
    public void solve(InputReader in) throws IOException {
        // 1. Read input and count frequencies
        for (int i = 0; i < n * n; i++) {
            int val = in.nextInt();
            frequencyMap.merge(val, 1, Integer::sum);
        }

        // 2. Validate if a palindromic arrangement is possible
        if (!isValidConfiguration()) {
            System.out.println("NO");
            return;
        }

        // 3. Construct the symmetric matrix
        constructMatrix();

        // 4. Output result
        System.out.println("YES");
        printMatrix();
    }

    /**
     * Checks if the frequency counts satisfy the mathematical requirements
     * for a 4-way symmetric (palindromic) matrix.
     */
    private boolean isValidConfiguration() {
        if (n % 2 == 0) {
            // Even n: Every number must appear in multiples of 4
            for (int count : frequencyMap.values()) {
                if (count % 4 != 0) {
                    return false;
                }
            }
        } else {
            // Odd n: Exactly one number can have an odd count (for the center)
            // All others must be multiples of 4 or 1 (1 for center, rest multiples of 4)
            int oddCount = 0;
            for (int count : frequencyMap.values()) {
                if (count % 2 != 0) {
                    oddCount++;
                }
                if (count % 4 != 0 && count % 4 != 1) {
                    return false;
                }
            }
            if (oddCount != 1) {
                return false;
            }
        }
        return true;
    }

    /**
     * Fills the matrix symmetrically based on validated frequencies.
     * Fills corner quadrants first, then middle row/column pairs.
     */
    private void constructMatrix() {
        // Place the center element for odd n
        if (n % 2 == 1) {
            int centerVal = -1;
            for (Map.Entry<Integer, Integer> entry : frequencyMap.entrySet()) {
                if (entry.getValue() % 2 != 0) {
                    centerVal = entry.getKey();
                    break;
                }
            }
            matrix[n / 2][n / 2] = centerVal;
        }

        int cornerRow = 0;
        int cornerCol = 0;
        int middlePairIdx = 0;
        int maxMiddlePairs = 2 * (n / 2); // Total pairs available in middle row/col

        for (Map.Entry<Integer, Integer> entry : frequencyMap.entrySet()) {
            int val = entry.getKey();
            int count = entry.getValue();

            // Reserve 1 for the center if applicable
            if (n % 2 == 1 && count % 2 != 0) {
                count--;
            }

            // Place groups of 4 in corner quadrants
            int cornerQuads = count / 4;
            count %= 4;

            for (int k = 0; k < cornerQuads; k++) {
                fillCornerQuadrant(cornerRow, cornerCol, val);
                advanceCornerPosition();
            }

            // Place remaining groups of 2 in the middle row/column
            if (count > 0) {
                int pairs = count / 2;
                for (int k = 0; k < pairs; k++) {
                    fillMiddlePair(middlePairIdx, val);
                    middlePairIdx++;
                }
            }
        }
    }

    private void fillCornerQuadrant(int r, int c, int val) {
        matrix[r][c] = val;
        matrix[r][n - 1 - c] = val;
        matrix[n - 1 - r][c] = val;
        matrix[n - 1 - r][n - 1 - c] = val;
    }

    private void advanceCornerPosition() {
        cornerRow++;
        if (cornerRow == n / 2) {
            cornerRow = 0;
            cornerCol++;
        }
    }

    private void fillMiddlePair(int idx, int val) {
        if (idx < n / 2) {
            // Middle row pairs
            matrix[n / 2][idx] = val;
            matrix[n / 2][n - 1 - idx] = val;
        } else {
            // Middle column pairs
            int colIdx = idx - n / 2;
            matrix[colIdx][n / 2] = val;
            matrix[n - 1 - colIdx][n / 2] = val;
        }
    }

    /**
     * Prints the constructed matrix using StringBuilder for performance.
     */
    private void printMatrix() {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                sb.append(matrix[i][j]).append(j == n - 1 ? "" : " ");
            }
            sb.append('\n');
        }
        System.out.print(sb);
    }

    /**
     * Fast I/O helper class.
     */
    private static class InputReader {
        private final BufferedReader br;
        private StringTokenizer st;

        public InputReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        public String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input", e);
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            String token = next();
            return token == null ? 0 : Integer.parseInt(token);
        }
    }

    public static void main(String[] args) {
        InputReader in = new InputReader();
        int n = in.nextInt();
        PalindromicMatrix solver = new PalindromicMatrix(n);
        try {
            solver.solve(in);
        } catch (IOException e) {
            System.err.println("I/O Error: " + e.getMessage());
        }
    }
}

import java.util.*;

public class MatrixBuilder {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        if (!sc.hasNextInt()) {
            sc.close();
            return;
        }

        int n = sc.nextInt();
        int[][] matrix = new int[n][n];

        // Step 1: Count frequency of each input number
        Map<Integer, Integer> freqMap = new HashMap<>();
        for (int i = 0; i < n * n; i++) {
            int val = sc.nextInt();
            freqMap.merge(val, 1, Integer::sum);
        }
        sc.close();

        // Step 2: Categorize frequencies into groups of 4, 2, and 1
        Map<Integer, Integer> groupsOf4 = new HashMap<>();
        Map<Integer, Integer> groupsOf2 = new HashMap<>();
        Map<Integer, Integer> groupsOf1 = new HashMap<>();

        for (Map.Entry<Integer, Integer> entry : freqMap.entrySet()) {
            int count = entry.getValue();
            int fours = count / 4;
            int remainder = count % 4;
            int twos = remainder / 2;
            int ones = remainder % 2;

            if (fours > 0) groupsOf4.put(entry.getKey(), fours);
            if (twos > 0) groupsOf2.put(entry.getKey(), twos);
            if (ones > 0) groupsOf1.put(entry.getKey(), ones);
        }

        // Step 3: Determine feasibility and fill matrix based on parity of n
        boolean possible;
        if (n % 2 == 0) {
            possible = solveEven(n, matrix, groupsOf4);
        } else {
            possible = solveOdd(n, matrix, groupsOf4, groupsOf2, groupsOf1);
        }

        // Step 4: Output result
        if (possible) {
            System.out.println("YES");
            printMatrix(matrix);
        } else {
            System.out.println("NO");
        }
    }

    /**
     * Solves the matrix construction for even n.
     * Requires exactly (n/2 * n/2) groups of 4.
     */
    private static boolean solveEven(int n, int[][] matrix, Map<Integer, Integer> groupsOf4) {
        int quadrantSize = n / 2;
        int needed = quadrantSize * quadrantSize;
        int available = groupsOf4.values().stream().mapToInt(Integer::intValue).sum();

        if (available < needed) {
            return false;
        }

        List<Integer> quadrantCandidates = buildCandidateList(groupsOf4);
        int idx = 0;

        for (int i = 0; i < quadrantSize; i++) {
            for (int j = 0; j < quadrantSize; j++) {
                int val = quadrantCandidates.get(idx++);
                // Fill symmetric positions across both axes
                matrix[i][j] = val;
                matrix[i][n - 1 - j] = val;
                matrix[n - 1 - i][j] = val;
                matrix[n - 1 - i][n - 1 - j] = val;
            }
        }
        return true;
    }

    /**
     * Solves the matrix construction for odd n.
     * Requires:
     * - (n/2 * n/2) groups of 4 for quadrants
     * - (n - 1) groups of 2 for middle row/column
     * - Exactly 1 group of 1 for the center
     */
    private static boolean solveOdd(int n, int[][] matrix, Map<Integer, Integer> groupsOf4,
                                    Map<Integer, Integer> groupsOf2, Map<Integer, Integer> groupsOf1) {
        int quadrantSize = n / 2;
        int neededQuadrants = quadrantSize * quadrantSize;
        int neededMiddle = n - 1;
        int neededCenter = 1;

        // Validate center requirement: exactly one number with remainder 1
        int totalOnes = groupsOf1.values().stream().mapToInt(Integer::intValue).sum();
        if (totalOnes != neededCenter) {
            return false;
        }

        // Validate quadrant requirement
        int availableQuadrants = groupsOf4.values().stream().mapToInt(Integer::intValue).sum();
        if (availableQuadrants < neededQuadrants) {
            return false;
        }

        // Prepare candidates for quadrants
        List<Integer> quadrantCandidates = buildCandidateList(groupsOf4);

        // Prepare candidates for middle row/column
        // Per original logic, all groups of 4 are also converted to pairs for the middle sections
        List<Integer> middleCandidates = buildCandidateList(groupsOf2);
        for (Map.Entry<Integer, Integer> entry : groupsOf4.entrySet()) {
            for (int k = 0; k < entry.getValue() * 2; k++) {
                middleCandidates.add(entry.getKey());
            }
        }

        if (middleCandidates.size() < neededMiddle) {
            return false;
        }

        // Fill quadrants
        int quadIdx = 0;
        for (int i = 0; i < quadrantSize; i++) {
            for (int j = 0; j < quadrantSize; j++) {
                int val = quadrantCandidates.get(quadIdx++);
                matrix[i][j] = val;
                matrix[i][n - 1 - j] = val;
                matrix[n - 1 - i][j] = val;
                matrix[n - 1 - i][n - 1 - j] = val;
            }
        }

        // Fill middle row (left and right of center)
        int midIdx = 0;
        for (int i = 0; i < quadrantSize; i++) {
            int val = middleCandidates.get(midIdx++);
            matrix[n / 2][i] = val;
            matrix[n / 2][n - 1 - i] = val;
        }

        // Fill middle column (above and below center)
        for (int i = 0; i < quadrantSize; i++) {
            int val = middleCandidates.get(midIdx++);
            matrix[i][n / 2] = val;
            matrix[n - 1 - i][n / 2] = val;
        }

        // Fill center
        for (Map.Entry<Integer, Integer> entry : groupsOf1.entrySet()) {
            matrix[n / 2][n / 2] = entry.getKey();
            break;
        }

        return true;
    }

    /**
     * Helper method to flatten a frequency map into a candidate list.
     */
    private static List<Integer> buildCandidateList(Map<Integer, Integer> groupMap) {
        List<Integer> candidates = new ArrayList<>();
        for (Map.Entry<Integer, Integer> entry : groupMap.entrySet()) {
            for (int k = 0; k < entry.getValue(); k++) {
                candidates.add(entry.getKey());
            }
        }
        return candidates;
    }

    /**
     * Efficiently prints the constructed matrix.
     */
    private static void printMatrix(int[][] matrix) {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < matrix.length; i++) {
            for (int j = 0; j < matrix[i].length; j++) {
                sb.append(matrix[i][j]).append(j == matrix[i].length - 1 ? "" : " ");
            }
            sb.append("\n");
        }
        System.out.print(sb);
    }
}

import java.io.BufferedReader;
import java.io.File;
import java.io.FileReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

/**
 * Main entry point for the grid symmetry solver.
 * Handles I/O configuration and delegates problem-solving to the Solver class.
 */
public class Main {

    private static final int MAX_VALUE = 1000;
    private static final int BUFFER_SIZE = 32768;

    public static void main(String[] args) {
        // Determine I/O mode: console (default) or file-based
        boolean useFileIO = args.length > 0 && "file".equalsIgnoreCase(args[0]);
        if (System.getProperty("useFileIO") != null) {
            useFileIO = true;
        }

        if (useFileIO) {
            runFileIO();
        } else {
            runConsoleIO();
        }
    }

    private static void runConsoleIO() {
        try (BufferedReader in = new BufferedReader(new InputStreamReader(System.in), BUFFER_SIZE);
             PrintWriter out = new PrintWriter(System.out)) {
            new Solver().solve(in, out);
        } catch (IOException e) {
            System.err.println("Console I/O Error: " + e.getMessage());
        }
    }

    private static void runFileIO() {
        String home = System.getProperty("user.home", ".");
        String inPath = home + "/Downloads/ip.in";
        String outPath = home + "/Downloads/op.out";

        try (BufferedReader in = new BufferedReader(new FileReader(inPath), BUFFER_SIZE);
             PrintWriter out = new PrintWriter(new File(outPath))) {
            new Solver().solve(in, out);
        } catch (IOException e) {
            System.err.println("File I/O Error: " + e.getMessage());
        }
    }

    /**
     * Encapsulates the core algorithm for solving the grid symmetry problem.
     */
    static class Solver {
        void solve(BufferedReader in, PrintWriter out) {
            try {
                FastScanner scanner = new FastScanner(in);
                int n = scanner.nextInt();
                int[] counts = new int[MAX_VALUE + 1];

                // Count frequency of each number in the input
                for (int i = 0; i < n * n; i++) {
                    counts[scanner.nextInt()]++;
                }

                int[][] grid = new int[n][n];
                boolean possible = true;

                // 1. Fill 4-fold symmetric positions (corners/quadrants)
                for (int i = 0; i < n / 2 && possible; i++) {
                    for (int j = 0; j < n / 2 && possible; j++) {
                        int val = findAndAssign(counts, 4);
                        if (val == -1) {
                            possible = false;
                        } else {
                            grid[i][j] = grid[i][n - 1 - j] = grid[n - 1 - i][j] = grid[n - 1 - i][n - 1 - j] = val;
                        }
                    }
                }

                // 2. Handle odd n center row, column, and cell
                if (possible && n % 2 == 1) {
                    int mid = n / 2;

                    // Center row (2-fold symmetry)
                    for (int j = 0; j < mid && possible; j++) {
                        int val = findAndAssign(counts, 2);
                        if (val == -1) {
                            possible = false;
                        } else {
                            grid[mid][j] = grid[mid][n - 1 - j] = val;
                        }
                    }

                    // Center column (2-fold symmetry)
                    for (int i = 0; i < mid && possible; i++) {
                        int val = findAndAssign(counts, 2);
                        if (val == -1) {
                            possible = false;
                        } else {
                            grid[i][mid] = grid[n - 1 - i][mid] = val;
                        }
                    }

                    // Center cell (1-fold symmetry)
                    if (possible) {
                        int val = findAndAssign(counts, 1);
                        if (val == -1) {
                            possible = false;
                        } else {
                            grid[mid][mid] = val;
                        }
                    }
                }

                // 3. Verify all numbers were successfully placed
                if (possible) {
                    for (int count : counts) {
                        if (count != 0) {
                            possible = false;
                            break;
                        }
                    }
                }

                // Output results
                if (!possible) {
                    out.println("NO");
                } else {
                    out.println("YES");
                    for (int i = 0; i < n; i++) {
                        for (int j = 0; j < n; j++) {
                            out.print(grid[i][j]);
                            out.print(j == n - 1 ? "" : " ");
                        }
                        out.println();
                    }
                }
            } catch (IOException e) {
                out.println("ERROR: " + e.getMessage());
            }
        }

        /**
         * Finds a number with at least the required count, decrements it, and returns the number.
         * Returns -1 if no suitable number exists.
         */
        private static int findAndAssign(int[] counts, int required) {
            for (int k = 0; k < counts.length; k++) {
                if (counts[k] >= required) {
                    counts[k] -= required;
                    return k;
                }
            }
            return -1;
        }
    }

    /**
     * Lightweight fast I/O scanner using BufferedReader and StringTokenizer.
     */
    static class FastScanner {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        FastScanner(BufferedReader reader) {
            this.reader = reader;
            this.tokenizer = null;
        }

        String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                String line = reader.readLine();
                if (line == null) {
                    throw new IOException("Unexpected end of input");
                }
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}

import java.util.Scanner;

public class MatrixBuilder {
    // Maximum possible value for an element as per problem constraints
    private static final int MAX_VALUE = 1005;

    public static void main(String[] args) {
        // Use try-with-resources for automatic resource management
        try (Scanner scanner = new Scanner(System.in)) {
            if (!scanner.hasNextInt()) return;
            int n = scanner.nextInt();
            int[] freq = readFrequencies(scanner, n);

            if (!isValid(n, freq)) {
                System.out.println("NO");
                return;
            }

            int[][] matrix = buildMatrix(n, freq);
            if (matrix == null) {
                System.out.println("NO");
                return;
            }

            System.out.println("YES");
            printMatrix(matrix);
        }
    }

    /**
     * Reads n*n integers and populates their frequency array.
     */
    private static int[] readFrequencies(Scanner scanner, int n) {
        int[] freq = new int[MAX_VALUE];
        for (int i = 0; i < n * n; i++) {
            freq[scanner.nextInt()]++;
        }
        return freq;
    }

    /**
     * Validates if the frequency distribution allows constructing a 
     * 4-fold symmetric matrix (with optional center element for odd n).
     */
    private static boolean isValid(int n, int[] freq) {
        int singleUsed = -1;
        for (int i = 0; i < freq.length; i++) {
            int rem = freq[i] % 4;
            // Remainder 0 or 2 are acceptable for symmetric groups
            if (rem == 0 || rem == 2) continue;

            // Odd remainders must appear exactly once (for the center element)
            if (freq[i] % 2 == 1) {
                if (singleUsed == -1) singleUsed = i;
                else return false; // Multiple odd remainders make construction impossible
            }
        }
        // Even n cannot have a center element, odd n must have exactly one
        if (n % 2 == 0 && singleUsed != -1) return false;
        if (n % 2 == 1 && singleUsed == -1) return false;
        return true;
    }

    /**
     * Constructs the symmetric matrix using the available frequencies.
     * Returns null if construction fails (should not happen if isValid passed).
     */
    private static int[][] buildMatrix(int n, int[] freq) {
        int[][] matrix = new int[n][n];
        int singleUsed = -1;
        for (int i = 0; i < freq.length; i++) {
            if (freq[i] % 2 == 1) {
                singleUsed = i;
                break;
            }
        }

        // Place the center element for odd-sized matrices
        if (singleUsed != -1) {
            matrix[n / 2][n / 2] = singleUsed;
            freq[singleUsed]--;
        }

        // Fill remaining cells in symmetry groups
        // Process remainder 2 groups first, then remainder 0 groups
        fillGroups(matrix, freq, n, 2);
        fillGroups(matrix, freq, n, 0);

        // Verify that every cell was successfully filled
        for (int[] row : matrix) {
            for (int val : row) {
                if (val == 0) return null;
            }
        }
        return matrix;
    }

    /**
     * Fills symmetry groups for numbers with a specific frequency remainder.
     * A symmetry group consists of 4 positions: (r,c), (r, n-1-c), (n-1-r, c), (n-1-r, n-1-c).
     */
    private static void fillGroups(int[][] matrix, int[] freq, int n, int targetRem) {
        for (int i = 0; i < freq.length; i++) {
            // Continue processing this number while it matches the target remainder
            while (freq[i] > 0 && freq[i] % 4 == targetRem) {
                boolean assigned = false;
                for (int r = 0; r < n; r++) {
                    for (int c = 0; c < n; c++) {
                        if (matrix[r][c] != 0) continue;

                        int r2 = n - 1 - r;
                        int c2 = n - 1 - c;
                        int count = 0;
                        if (matrix[r][c] == 0) count++;
                        if (matrix[r][c2] == 0) count++;
                        if (matrix[r2][c] == 0) count++;
                        if (matrix[r2][c2] == 0) count++;

                        if (count > 0) {
                            if (matrix[r][c] == 0) matrix[r][c] = i;
                            if (matrix[r][c2] == 0) matrix[r][c2] = i;
                            if (matrix[r2][c] == 0) matrix[r2][c] = i;
                            if (matrix[r2][c2] == 0) matrix[r2][c2] = i;

                            freq[i] -= count;
                            assigned = true;
                            break; // Move to the next empty group
                        }
                    }
                    if (assigned) break; // Move to the next number
                }
                if (!assigned) break; // No more empty groups available
            }
        }
    }

    /**
     * Prints the constructed matrix to standard output.
     */
    private static void printMatrix(int[][] matrix) {
        for (int[] row : matrix) {
            for (int val : row) {
                System.out.print(val + " ");
            }
            System.out.println();
        }
    }
}

import java.io.*;
import java.util.*;

public class Main {
    private static final int MAX_VALUE = 1000;

    private final BufferedReader reader;
    private final BufferedWriter writer;
    private StringTokenizer tokenizer;

    private List<NumberPair> availablePairs;
    private int currentPairIndex;

    public Main() {
        this.reader = new BufferedReader(new InputStreamReader(System.in));
        this.writer = new BufferedWriter(new OutputStreamWriter(System.out));
    }

    public void solve() {
        int n = readInt();
        if (n == 1) {
            int val = readInt();
            write("YES\n" + val + "\n");
            return;
        }

        int[] frequencies = new int[MAX_VALUE + 1];
        for (int i = 0; i < n * n; i++) {
            frequencies[readInt()]++;
        }

        availablePairs = new ArrayList<>();
        for (int i = 1; i <= MAX_VALUE; i++) {
            int count = frequencies[i];
            if (count == 0) continue;

            if (count % 2 != 0) {
                availablePairs.add(new NumberPair(i, 1));
                count--;
            }
            if (count % 4 != 0) {
                availablePairs.add(new NumberPair(i, count % 4));
                count -= count % 4;
            }
            availablePairs.add(new NumberPair(i, count));
        }

        Collections.sort(availablePairs);

        int oneCount = 0;
        int twoCount = 0;
        for (NumberPair pair : availablePairs) {
            int cur = pair.remaining;
            if (cur % 2 != 0) {
                oneCount++;
                cur--;
            }
            if (cur % 4 != 0) {
                twoCount += cur % 4;
            }
        }

        if (!isValidConfiguration(n, oneCount, twoCount)) {
            write("NO\n");
            return;
        }

        int[][] grid = generateGrid(n);
        write("YES\n");
        printGrid(grid, n);
    }

    private boolean isValidConfiguration(int n, int oneCount, int twoCount) {
        boolean isEvenN = n % 2 == 0;
        if (isEvenN && oneCount > 0) return false;
        if (!isEvenN && oneCount != 1) return false;
        if (isEvenN && twoCount != 0) return false;
        if (!isEvenN && twoCount > (n - 1) * 2) return false;
        return true;
    }

    private int[][] generateGrid(int n) {
        int half = n / 2;
        int isOdd = n % 2;
        int quadrantSize = half + isOdd;
        int[][] quadrant = new int[quadrantSize][quadrantSize];

        if (isOdd == 1) {
            quadrant[quadrantSize - 1][quadrantSize - 1] = next(1);
            for (int i = 0; i < half; i++) {
                quadrant[quadrantSize - 1][i] = next(2);
                quadrant[i][quadrantSize - 1] = next(2);
            }
        }

        for (int i = 0; i < half; i++) {
            for (int j = 0; j < half; j++) {
                quadrant[i][j] = next(4);
            }
        }

        // Mirror the quadrant to fill the full n x n grid
        int[][] fullGrid = new int[n][n];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                int x = i >= quadrantSize ? n - i - 1 : i;
                int y = j >= quadrantSize ? n - j - 1 : j;
                fullGrid[i][j] = quadrant[x][y];
            }
        }
        return fullGrid;
    }

    private int next(int count) {
        while (currentPairIndex < availablePairs.size()) {
            NumberPair current = availablePairs.get(currentPairIndex);
            if (current.remaining >= count) {
                current.remaining -= count;
                return current.value;
            }
            currentPairIndex++;
        }
        throw new IllegalStateException("Insufficient numbers to fill the grid.");
    }

    private void printGrid(int[][] grid, int n) {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                sb.append(grid[i][j]).append(j == n - 1 ? "" : " ");
            }
            sb.append('\n');
        }
        write(sb.toString());
    }

    // I/O Helpers
    private String nextToken() {
        while (tokenizer == null || !tokenizer.hasMoreTokens()) {
            try {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            } catch (IOException e) {
                throw new RuntimeException("Failed to read input", e);
            }
        }
        return tokenizer.nextToken();
    }

    private int readInt() {
        return Integer.parseInt(nextToken());
    }

    private void write(String s) {
        try {
            writer.write(s);
        } catch (IOException e) {
            throw new RuntimeException("Failed to write output", e);
        }
    }

    public static void main(String[] args) {
        try (Main solver = new Main()) {
            solver.solve();
        } catch (IOException e) {
            throw new RuntimeException(e);
        }
    }

    private static class NumberPair implements Comparable<NumberPair> {
        final int value;
        int remaining;
        final int priority;

        NumberPair(int value, int remaining) {
            this.value = value;
            this.remaining = remaining;
            this.priority = (remaining % 4 == 0) ? 2 : ((remaining % 2 == 0) ? 1 : 0);
        }

        @Override
        public int compareTo(NumberPair other) {
            return Integer.compare(this.priority, other.priority);
        }
    }
}

import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.NoSuchElementException;

public class Main {
    private static final int MAX_VALUE = 1000;

    public static void main(String[] args) {
        FastScanner sc = new FastScanner();
        PrintWriter out = new PrintWriter(System.out);
        try {
            solve(sc, out);
        } finally {
            out.flush();
        }
    }

    private static void solve(FastScanner sc, PrintWriter out) {
        int n = sc.nextInt();
        int[] counts = new int[MAX_VALUE + 1];
        int totalElements = n * n;

        for (int i = 0; i < totalElements; i++) {
            counts[sc.nextInt()]++;
        }

        int[][] grid = new int[n][n];

        if (n % 2 == 0) {
            if (!fillEvenGrid(grid, n, counts)) {
                out.println("NO");
                return;
            }
        } else {
            if (!fillOddGrid(grid, n, counts)) {
                out.println("NO");
                return;
            }
        }

        out.println("YES");
        printGrid(out, grid, n);
    }

    private static boolean fillEvenGrid(int[][] grid, int n, int[] counts) {
        int x = 0;
        int y = 0;

        for (int val = 1; val <= MAX_VALUE; val++) {
            if (counts[val] % 4 != 0) {
                return false;
            }
            while (counts[val] >= 4) {
                fillQuadrant(grid, n, val, x, y);
                counts[val] -= 4;
                x++;
                if (x == n / 2) {
                    x = 0;
                    y++;
                }
            }
        }
        return true;
    }

    private static boolean fillOddGrid(int[][] grid, int n, int[] counts) {
        int mid = n / 2;

        // Handle the center cell for the number with an odd count
        for (int val = 1; val <= MAX_VALUE; val++) {
            if (counts[val] % 2 != 0) {
                if (grid[mid][mid] != 0) {
                    return false;
                }
                grid[mid][mid] = val;
                counts[val]--;
                break; // Only one number can have an odd count
            }
        }

        int x = 0;
        int y = 0;

        for (int val = 1; val <= MAX_VALUE; val++) {
            // Process groups of 4 symmetric positions
            while (counts[val] >= 4) {
                if (y == mid) {
                    // Cannot place 4 symmetric values in the middle column
                    if (!fillMiddlePair(grid, n, val)) {
                        return false;
                    }
                    counts[val] -= 2;
                } else {
                    fillQuadrant(grid, n, val, x, y);
                    counts[val] -= 4;
                    x++;
                    if (x == mid) {
                        x = 0;
                        y++;
                    }
                }
            }

            // Process remaining pairs in the middle row/column
            while (counts[val] >= 2) {
                if (!fillMiddlePair(grid, n, val)) {
                    return false;
                }
                counts[val] -= 2;
            }
        }
        return true;
    }

    private static void fillQuadrant(int[][] grid, int n, int val, int x, int y) {
        grid[x][y] = val;
        grid[n - 1 - x][y] = val;
        grid[x][n - 1 - y] = val;
        grid[n - 1 - x][n - 1 - y] = val;
    }

    private static boolean fillMiddlePair(int[][] grid, int n, int val) {
        int mid = n / 2;
        for (int j = 0; j < mid; j++) {
            if (grid[j][mid] == 0) {
                grid[j][mid] = val;
                grid[n - 1 - j][mid] = val;
                return true;
            } else if (grid[mid][j] == 0) {
                grid[mid][j] = val;
                grid[mid][n - 1 - j] = val;
                return true;
            }
        }
        return false;
    }

    private static void printGrid(PrintWriter out, int[][] grid, int n) {
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (j > 0) {
                    out.print(" ");
                }
                out.print(grid[i][j]);
            }
            out.println();
        }
    }

    /**
     * FastScanner for efficient competitive programming input parsing.
     */
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1024];
        private int ptr = 0;
        private int buflen = 0;

        private boolean hasNextByte() {
            if (ptr < buflen) {
                return true;
            }
            ptr = 0;
            try {
                buflen = in.read(buffer);
            } catch (IOException e) {
                e.printStackTrace();
            }
            return buflen > 0;
        }

        private int readByte() {
            return hasNextByte() ? buffer[ptr++] : -1;
        }

        private static boolean isPrintableChar(int c) {
            return 33 <= c && c <= 126;
        }

        private void skipUnprintable() {
            while (hasNextByte() && !isPrintableChar(buffer[ptr])) {
                ptr++;
            }
        }

        public boolean hasNext() {
            skipUnprintable();
            return hasNextByte();
        }

        public String next() {
            if (!hasNext()) throw new NoSuchElementException();
            StringBuilder sb = new StringBuilder();
            int b = readByte();
            while (isPrintableChar(b)) {
                sb.appendCodePoint(b);
                b = readByte();
            }
            return sb.toString();
        }

        public long nextLong() {
            return Long.parseLong(next());
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public double nextDouble() {
            return Double.parseDouble(next());
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.ArrayList;
import java.util.List;
import java.util.StringTokenizer;

public class Main {
    public static void main(String[] args) {
        InputReader in = new InputReader(System.in);
        PrintWriter out = new PrintWriter(System.out);
        new Task().solve(in, out);
        out.flush();
    }

    static class Task {
        private static final int MAX_VALUE = 1000;

        public void solve(InputReader in, PrintWriter out) {
            int n = in.nextInt();
            int[] counts = new int[MAX_VALUE + 1];

            // Read grid and count frequencies
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < n; j++) {
                    counts[in.nextInt()]++;
                }
            }

            // Distribute numbers into groups based on frequency modulo 4
            List<Integer> fours = new ArrayList<>();
            List<Integer> edges = new ArrayList<>();
            List<Integer> centers = new ArrayList<>();

            for (int val = 0; val <= MAX_VALUE; val++) {
                int count = counts[val];
                if (count == 0) continue;

                int groupsOf4 = count / 4;
                int remainder = count % 4;

                for (int k = 0; k < groupsOf4; k++) {
                    fours.add(val);
                }

                if (remainder == 1) {
                    centers.add(val);
                } else if (remainder == 2) {
                    edges.add(val);
                    edges.add(val);
                } else if (remainder == 3) {
                    edges.add(val);
                    centers.add(val);
                }
            }

            // Calculate required group counts
            int cornerGroups = (n / 2) * (n / 2);
            int edgeGroups = (n * n - 4 * cornerGroups - (n % 2 == 1 ? 1 : 0)) / 2;

            // Convert excess corner groups into edge groups (1 group of 4 -> 2 groups of 2)
            while (fours.size() > cornerGroups) {
                int val = fours.remove(fours.size() - 1);
                edges.add(val);
                edges.add(val);
            }

            // Validate if we have exactly the required number of groups
            if (fours.size() != cornerGroups || edges.size() != edgeGroups || 
                centers.size() != (n % 2 == 1 ? 1 : 0)) {
                out.println("NO");
                return;
            }

            out.println("YES");
            int[][] grid = constructGrid(n, fours, edges, centers.get(0));

            // Output the constructed grid
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < n; j++) {
                    out.print(grid[i][j] + (j == n - 1 ? "" : " "));
                }
                out.println();
            }
        }

        /**
         * Constructs the n x n grid by filling concentric layers.
         * Uses indices passed as local variables to avoid shared mutable state.
         */
        private int[][] constructGrid(int n, List<Integer> fours, List<Integer> edges, int center) {
            int[][] grid = new int[n][n];
            int fIdx = 0;
            int eIdx = 0;

            for (int c1 = 0, c2 = n - 1; c1 <= c2; c1++, c2--) {
                for (int r1 = 0, r2 = n - 1; r1 <= r2; r1++, r2--) {
                    if (r1 != r2 && c1 != c2) {
                        // Four corners of the current concentric square
                        int val = fours.get(fIdx++);
                        grid[r1][c1] = val;
                        grid[r1][c2] = val;
                        grid[r2][c1] = val;
                        grid[r2][c2] = val;
                    } else if (r1 == r2 && c1 == c2) {
                        // Center element (only for odd n)
                        grid[r1][c2] = center;
                    } else if (r1 == r2) {
                        // Top/Bottom edge
                        int val = edges.get(eIdx++);
                        grid[r1][c1] = val;
                        grid[r1][c2] = val;
                    } else {
                        // Left/Right edge
                        int val = edges.get(eIdx++);
                        grid[r1][c2] = val;
                        grid[r2][c1] = val;
                    }
                }
            }
            return grid;
        }
    }

    static class InputReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            String s = next();
            if (s == null) throw new RuntimeException("Unexpected end of input");
            return Integer.parseInt(s);
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.StringTokenizer;

public class CodeforcesFun {

    public static void main(String[] args) throws IOException {
        // Use try-with-resources for automatic resource management
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
             PrintWriter out = new PrintWriter(System.out)) {

            FastScanner scanner = new FastScanner(br);
            int n = scanner.nextInt();
            int totalElements = n * n;
            int[] values = new int[totalElements];

            for (int i = 0; i < totalElements; i++) {
                values[i] = scanner.nextInt();
            }
            Arrays.sort(values);

            // Buckets for distribution
            List<Integer> quads = new ArrayList<>();
            List<Integer> pairs = new ArrayList<>();
            List<Integer> singles = new ArrayList<>();

            // Count frequencies and distribute into buckets
            int i = 0;
            while (i < totalElements) {
                int currentValue = values[i];
                int count = 0;
                while (i < totalElements && values[i] == currentValue) {
                    count++;
                    i++;
                }
                distributeCounts(count, currentValue, quads, pairs, singles);
            }

            // Process based on matrix parity
            if (n % 2 == 0) {
                if (!pairs.isEmpty() || !singles.isEmpty()) {
                    out.println("NO");
                } else {
                    int half = n / 2;
                    int[][] quarterMatrix = new int[half][half];
                    for (int r = 0; r < half; r++) {
                        for (int c = 0; c < half; c++) {
                            quarterMatrix[r][c] = quads.remove(quads.size() - 1);
                        }
                    }
                    out.println("YES");
                    buildAndPrintMatrix(quarterMatrix, half, n, out);
                }
            } else {
                if (singles.size() != 1) {
                    out.println("NO");
                } else {
                    int midLength = n / 2;
                    int neededPairs = midLength * 2;

                    // Convert quads to pairs if we don't have enough pairs
                    while (pairs.size() < neededPairs) {
                        int value = quads.remove(quads.size() - 1);
                        pairs.add(value);
                        pairs.add(value);
                    }

                    if (pairs.size() != neededPairs) {
                        out.println("NO");
                    } else {
                        int half = n / 2 + 1;
                        int[][] quarterMatrix = new int[half][half];

                        // Fill the top-left quadrant
                        for (int r = 0; r < half - 1; r++) {
                            for (int c = 0; c < half - 1; c++) {
                                quarterMatrix[r][c] = quads.remove(quads.size() - 1);
                            }
                        }
                        // Fill the center element
                        quarterMatrix[half - 1][half - 1] = singles.remove(singles.size() - 1);

                        // Fill the middle row and column
                        for (int r = 0; r < half - 1; r++) {
                            quarterMatrix[half - 1][r] = pairs.remove(pairs.size() - 1);
                            quarterMatrix[r][half - 1] = pairs.remove(pairs.size() - 1);
                        }

                        out.println("YES");
                        buildAndPrintMatrix(quarterMatrix, half, n, out);
                    }
                }
            }
            out.flush();
        }
    }

    /**
     * Distributes a count into groups of 4, 2, and 1.
     */
    private static void distributeCounts(int count, int value, List<Integer> quads, 
                                         List<Integer> pairs, List<Integer> singles) {
        int groupsOf4 = count / 4;
        for (int k = 0; k < groupsOf4; k++) {
            quads.add(value);
        }
        count %= 4;

        int groupsOf2 = count / 2;
        for (int k = 0; k < groupsOf2; k++) {
            pairs.add(value);
        }
        count %= 2;

        if (count > 0) {
            singles.add(value);
        }
    }

    /**
     * Expands a base matrix into a fully symmetric matrix and prints it.
     * Handles both even and odd n cases uniformly.
     */
    private static void buildAndPrintMatrix(int[][] base, int baseSize, int n, PrintWriter out) {
        int[][] matrix = new int[n][n];
        for (int i = 0; i < baseSize; i++) {
            for (int j = 0; j < baseSize; j++) {
                int val = base[i][j];
                matrix[i][j] = val;
                matrix[n - 1 - i][j] = val;
                matrix[i][n - 1 - j] = val;
                matrix[n - 1 - i][n - 1 - j] = val;
            }
        }

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                out.print(matrix[i][j] + (j == n - 1 ? "" : " "));
            }
            out.println();
        }
    }

    /**
     * Lightweight, non-blocking fast I/O scanner.
     */
    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner(BufferedReader br) {
            this.br = br;
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input", e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Scanner;

public class PalindromicMatrixBuilder {

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            if (!scanner.hasNextInt()) {
                return;
            }
            int n = scanner.nextInt();
            int[] elements = new int[n * n];
            for (int i = 0; i < n * n; i++) {
                elements[i] = scanner.nextInt();
            }

            PalindromicMatrixBuilder solver = new PalindromicMatrixBuilder();
            System.out.println(solver.constructMatrix(n, elements));
        }
    }

    /**
     * Constructs a palindromic matrix from the given elements.
     * A palindromic matrix is symmetric horizontally and vertically.
     *
     * @param n      The dimension of the square matrix.
     * @param elements The n*n input integers.
     * @return "YES" followed by the matrix if possible, otherwise "NO".
     */
    public String constructMatrix(int n, int[] elements) {
        // 1. Count frequency of each number
        Map<Integer, Integer> frequencyMap = new HashMap<>();
        for (int num : elements) {
            frequencyMap.put(num, frequencyMap.getOrDefault(num, 0) + 1);
        }

        // 2. Group numbers into buckets based on symmetric position requirements
        // Quadrants require 4 identical values. Middle row/col require 2. Center requires 1.
        List<Integer> fours = new ArrayList<>();
        List<Integer> twos = new ArrayList<>();
        List<Integer> ones = new ArrayList<>();

        for (Map.Entry<Integer, Integer> entry : frequencyMap.entrySet()) {
            int num = entry.getKey();
            int count = entry.getValue();

            while (count >= 4) {
                fours.add(num);
                count -= 4;
            }
            while (count >= 2) {
                twos.add(num);
                count -= 2;
            }
            if (count == 1) {
                ones.add(num);
            }
        }

        // 3. Calculate required counts
        int quadrantCount = (n / 2) * (n / 2);
        int midLinePairs = (n % 2 == 1) ? n / 2 : 0;
        int centerCount = (n % 2 == 1) ? 1 : 0;

        // 4. Validate feasibility
        if (fours.size() < quadrantCount ||
            twos.size() < 2 * midLinePairs ||
            ones.size() < centerCount) {
            return "NO";
        }

        // 5. Fill the matrix
        int[][] matrix = new int[n][n];
        int foursIdx = 0;
        int twosIdx = 0;
        int onesIdx = 0;

        // Fill top-left quadrant and mirror to other three quadrants
        for (int i = 0; i < n / 2; i++) {
            for (int j = 0; j < n / 2; j++) {
                int val = fours.get(foursIdx++);
                matrix[i][j] = val;
                matrix[i][n - 1 - j] = val;
                matrix[n - 1 - i][j] = val;
                matrix[n - 1 - i][n - 1 - j] = val;
            }
        }

        // Fill middle row and column if n is odd
        if (n % 2 == 1) {
            int mid = n / 2;
            // Middle row pairs
            for (int j = 0; j < mid; j++) {
                int val = twos.get(twosIdx++);
                matrix[mid][j] = val;
                matrix[mid][n - 1 - j] = val;
            }
            // Middle column pairs
            for (int i = 0; i < mid; i++) {
                int val = twos.get(twosIdx++);
                matrix[i][mid] = val;
                matrix[n - 1 - i][mid] = val;
            }
            // Center element
            matrix[mid][mid] = ones.get(onesIdx);
        }

        // 6. Format output
        StringBuilder output = new StringBuilder();
        output.append("YES\n");
        for (int[] row : matrix) {
            for (int val : row) {
                output.append(val).append(' ');
            }
            output.append('\n');
        }
        return output.toString().trim();
    }
}

import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.List;
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            if (!scanner.hasNextInt()) {
                return;
            }
            int n = scanner.nextInt();
            int[] counts = new int[1000];

            for (int i = 0; i < n * n; i++) {
                int val = scanner.nextInt();
                counts[val - 1]++;
            }

            List<Data> dataList = new ArrayList<>();
            for (int i = 0; i < 1000; i++) {
                if (counts[i] > 0) {
                    dataList.add(new Data(i + 1, counts[i]));
                }
            }

            Collections.sort(dataList, new PriorityComparator());

            int[][] grid = new int[n][n];
            GridBuilder builder = new GridBuilder(dataList, grid, n);

            if (builder.build()) {
                System.out.println("YES");
                printGrid(grid);
            } else {
                System.out.println("NO");
            }
        }
    }

    private static void printGrid(int[][] grid) {
        for (int[] row : grid) {
            for (int val : row) {
                System.out.print(val + " ");
            }
            System.out.println();
        }
    }
}

/**
 * Represents a number value along with its frequency and calculated priority.
 */
class Data {
    final int value;
    int count;
    final int priority;

    Data(int value, int count) {
        this.value = value;
        this.count = count;
        this.priority = calculatePriority(count);
    }

    private static int calculatePriority(int count) {
        if (count % 2 != 0) {
            return 0;
        } else if (count % 4 == 0) {
            return 400 * count;
        } else {
            return count;
        }
    }

    void decrementCount() {
        count--;
    }
}

/**
 * Comparator that orders Data objects by their priority.
 * Uses Integer.compare to prevent integer overflow.
 */
class PriorityComparator implements Comparator<Data> {
    @Override
    public int compare(Data d1, Data d2) {
        return Integer.compare(d1.priority, d2.priority);
    }
}

/**
 * Encapsulates the logic for constructing the symmetric grid.
 * Replaces global state (judge flag) with explicit boolean return values.
 */
class GridBuilder {
    private final List<Data> dataList;
    private final int[][] grid;
    private final int n;
    private final int middle;

    GridBuilder(List<Data> dataList, int[][] grid, int n) {
        this.dataList = dataList;
        this.grid = grid;
        this.n = n;
        this.middle = n / 2;
    }

    boolean build() {
        if (n % 2 != 0) {
            if (!fillCenter()) return false;
            if (!fillQuadrants()) return false;
            if (!fillMiddleAxes()) return false;
        } else {
            if (!fillQuadrants()) return false;
        }
        return true;
    }

    private boolean fillCenter() {
        if (dataList.isEmpty()) return false;
        Data data = dataList.get(0);
        grid[middle][middle] = data.value;
        data.decrementCount();
        return true;
    }

    private boolean fillQuadrants() {
        for (int i = 0; i < middle; i++) {
            for (int j = 0; j < middle; j++) {
                if (!fillSymmetricQuad(i, j)) return false;
            }
        }
        return true;
    }

    private boolean fillMiddleAxes() {
        // Fill top and bottom middle columns
        for (int i = 0; i < middle; i++) {
            if (!fillPair(i, middle, n - 1 - i, middle)) return false;
        }
        // Fill left and right middle rows
        for (int i = 0; i < middle; i++) {
            if (!fillPair(middle, i, middle, n - 1 - i)) return false;
        }
        return true;
    }

    private boolean fillPair(int r1, int c1, int r2, int c2) {
        int idx = findIncreasingIndex();
        if (idx == -1) return false;
        Data data = dataList.get(idx);
        if (grid[r1][c1] == 0) {
            grid[r1][c1] = data.value;
            data.decrementCount();
        }
        if (grid[r2][c2] == 0) {
            grid[r2][c2] = data.value;
            data.decrementCount();
        }
        return true;
    }

    private boolean fillSymmetricQuad(int r1, int c1) {
        int idx = findDecreasingIndex();
        if (idx == -1) return false;
        Data data = dataList.get(idx);
        int[][] positions = {
            {r1, c1}, {r1, n - 1 - c1},
            {n - 1 - r1, c1}, {n - 1 - r1, n - 1 - c1}
        };
        for (int[] pos : positions) {
            if (grid[pos[0]][pos[1]] == 0) {
                grid[pos[0]][pos[1]] = data.value;
                data.decrementCount();
            }
        }
        return true;
    }

    private int findIncreasingIndex() {
        for (int i = 0; i < dataList.size(); i++) {
            if (dataList.get(i).count >= 2) {
                return i;
            }
        }
        return -1;
    }

    private int findDecreasingIndex() {
        for (int i = dataList.size() - 1; i >= 0; i--) {
            if (dataList.get(i).count >= 4) {
                return i;
            }
        }
        return -1;
    }
}

import java.io.*;
import java.util.*;

/**
 * Constructs a symmetric matrix from a given set of values.
 * Supports both even and odd dimensions with 4-way rotational symmetry.
 */
public class Main {

    private static final FastScanner scanner = new FastScanner();
    private static final PrintWriter out = new PrintWriter(System.out);

    public static void main(String[] args) {
        try {
            new Main().solve();
        } catch (Exception e) {
            e.printStackTrace();
            System.exit(1);
        } finally {
            out.flush();
        }
    }

    void solve() throws IOException {
        int n = scanner.nextInt();
        int totalElements = n * n;
        int[] values = new int[totalElements];
        for (int i = 0; i < totalElements; i++) {
            values[i] = scanner.nextInt();
        }

        // Arrays.sort is preferred for maintainability. 
        // It uses Dual-Pivot Quicksort which is highly optimized for typical inputs.
        Arrays.sort(values);

        Map<Integer, Integer> counts = new HashMap<>();
        for (int v : values) {
            counts.merge(v, 1, Integer::sum);
        }

        int[][] matrix = new int[n][n];

        if (n % 2 == 0) {
            if (!validateEvenCase(counts)) {
                out.println("NO");
                return;
            }
            fillEvenCase(n, matrix, counts);
        } else {
            if (!validateOddCase(counts)) {
                out.println("NO");
                return;
            }
            fillOddCase(n, matrix, counts);
        }

        out.println("YES");
        printMatrix(n, matrix);
    }

    /**
     * Validates that all element frequencies are multiples of 4 for even-sized matrices.
     */
    private boolean validateEvenCase(Map<Integer, Integer> counts) {
        for (int count : counts.values()) {
            if (count % 4 != 0) {
                return false;
            }
        }
        return true;
    }

    /**
     * Validates that exactly one element has an odd frequency (required for the center cell).
     */
    private boolean validateOddCase(Map<Integer, Integer> counts) {
        int oddFrequencyCount = 0;
        for (int count : counts.values()) {
            if (count % 2 != 0) {
                oddFrequencyCount++;
            }
        }
        return oddFrequencyCount == 1;
    }

    /**
     * Fills the matrix for even dimensions using 4-way symmetric placement.
     */
    private void fillEvenCase(int n, int[][] matrix, Map<Integer, Integer> counts) {
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (matrix[i][j] != 0) continue;

                for (Map.Entry<Integer, Integer> entry : counts.entrySet()) {
                    if (entry.getValue() >= 4) {
                        int value = entry.getKey();
                        entry.setValue(entry.getValue() - 4);
                        placeSymmetricGroup(matrix, i, j, n, value);
                        break;
                    }
                }
            }
        }
    }

    /**
     * Fills the matrix for odd dimensions, handling center, 4-way groups, 
     * and middle row/column pairs.
     */
    private void fillOddCase(int n, int[][] matrix, Map<Integer, Integer> counts) {
        // 1. Place center element (requires exactly one number with odd count)
        for (Map.Entry<Integer, Integer> entry : counts.entrySet()) {
            if (entry.getValue() % 2 != 0) {
                int value = entry.getKey();
                matrix[n / 2][n / 2] = value;
                entry.setValue(entry.getValue() - 1);
                break;
            }
        }

        // 2. Fill 4-way symmetric positions (excluding center and middle axes)
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (matrix[i][j] == 0 && i != n / 2 && j != n / 2) {
                    for (Map.Entry<Integer, Integer> entry : counts.entrySet()) {
                        if (entry.getValue() >= 4) {
                            int value = entry.getKey();
                            entry.setValue(entry.getValue() - 4);
                            placeSymmetricGroup(matrix, i, j, n, value);
                            break;
                        }
                    }
                }
            }
        }

        // 3. Fill middle row pairs
        for (int j = 0; j <= n / 2 - 1; j++) {
            if (matrix[n / 2][j] == 0) {
                for (Map.Entry<Integer, Integer> entry : counts.entrySet()) {
                    if (entry.getValue() >= 2) {
                        int value = entry.getKey();
                        entry.setValue(entry.getValue() - 2);
                        matrix[n / 2][j] = value;
                        matrix[n / 2][n - j - 1] = value;
                        break;
                    }
                }
            }
        }

        // 4. Fill middle column pairs
        for (int i = 0; i <= n / 2 - 1; i++) {
            if (matrix[i][n / 2] == 0) {
                for (Map.Entry<Integer, Integer> entry : counts.entrySet()) {
                    if (entry.getValue() >= 2) {
                        int value = entry.getKey();
                        entry.setValue(entry.getValue() - 2);
                        matrix[i][n / 2] = value;
                        matrix[n - i - 1][n / 2] = value;
                        break;
                    }
                }
            }
        }

        // 5. Final validation check
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (matrix[i][j] == 0) {
                    out.println("NO");
                    return;
                }
            }
        }
    }

    /**
     * Places a value into four symmetric positions in the matrix.
     */
    private void placeSymmetricGroup(int[][] matrix, int i, int j, int n, int value) {
        matrix[i][j] = value;
        matrix[i][n - j - 1] = value;
        matrix[n - i - 1][j] = value;
        matrix[n - i - 1][n - j - 1] = value;
    }

    /**
     * Prints the constructed matrix to standard output.
     */
    private void printMatrix(int n, int[][] matrix) {
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                out.print(matrix[i][j] + (j == n - 1 ? "" : " "));
            }
            out.println();
        }
    }

    /**
     * Fast I/O helper to encapsulate BufferedReader and StringTokenizer usage.
     * Replaces scattered static fields and improves testability.
     */
    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        long nextLong() {
            return Long.parseLong(next());
        }

        double nextDouble() {
            return Double.parseDouble(next());
        }
    }
}

import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) {
        FastReader in = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        PalindromicMatrixSolver solver = new PalindromicMatrixSolver();
        solver.solve(in, out);

        out.flush();
        out.close();
    }

    /**
     * Solves the Palindromic Matrix problem by constructing a matrix that is symmetric
     * across both vertical and horizontal midlines.
     */
    static class PalindromicMatrixSolver {
        private static final int QUADRANT_GROUP_SIZE = 4;
        private static final int MIDDLE_GROUP_SIZE = 2;

        public void solve(FastReader in, PrintWriter out) {
            int n = in.nextInt();
            int totalCells = n * n;
            int[] a = in.nextIntArray(totalCells);
            Arrays.sort(a);

            // Base case: 1x1 matrix is always valid
            if (n == 1) {
                out.println("YES");
                out.println(a[0]);
                return;
            }

            // Pre-allocate arrays to avoid ArrayList boxing overhead
            int[] quadrantValues = new int[totalCells];
            int[] middleValues = new int[totalCells];
            int qIdx = 0, mIdx = 0;
            int centerValue = 0;
            boolean hasCenter = false;

            // Group identical numbers and distribute them to symmetry groups
            int i = 0;
            while (i < totalCells) {
                int j = i;
                while (j < totalCells && a[j] == a[i]) {
                    j++;
                }
                int count = j - i;
                int fullQuadrants = count / QUADRANT_GROUP_SIZE;
                int remainder = count % QUADRANT_GROUP_SIZE;

                // Fill quadrant positions (4 identical cells per group)
                for (int k = 0; k < fullQuadrants; k++) {
                    quadrantValues[qIdx++] = a[i];
                }

                // Fill middle row/column positions (2 identical cells per group)
                for (int k = 0; k < remainder / MIDDLE_GROUP_SIZE; k++) {
                    middleValues[mIdx++] = a[i];
                }

                // Handle leftover single cell (only allowed for center in odd n)
                if (remainder % MIDDLE_GROUP_SIZE == 1) {
                    if (n % 2 == 1) {
                        centerValue = a[i];
                        hasCenter = true;
                    } else {
                        // Even n cannot have a center cell
                        out.println("NO");
                        return;
                    }
                }
                i = j;
            }

            int[][] matrix = new int[n][n];

            // Validate expected counts before construction
            int expectedQuadrants = (n / 2) * (n / 2);
            int expectedMiddles = (n % 2 == 1) ? n : 0;

            if (qIdx != expectedQuadrants || mIdx != expectedMiddles || (n % 2 == 1 && !hasCenter)) {
                out.println("NO");
                return;
            }

            // Fill quadrants
            int ptr = 0;
            for (int r = 0; r < n / 2; r++) {
                for (int c = 0; c < n / 2; c++) {
                    int val = quadrantValues[ptr++];
                    matrix[r][c] = matrix[n - 1 - r][c] = 
                                   matrix[r][n - 1 - c] = matrix[n - 1 - r][n - 1 - c] = val;
                }
            }

            // Fill middle row and column for odd n
            if (n % 2 == 1) {
                int mid = n / 2;
                matrix[mid][mid] = centerValue;

                ptr = 0;
                // Middle row
                for (int c = 0; c < mid; c++) {
                    int val = middleValues[ptr++];
                    matrix[mid][c] = matrix[mid][n - 1 - c] = val;
                }
                // Middle column
                for (int r = 0; r < mid; r++) {
                    int val = middleValues[ptr++];
                    matrix[r][mid] = matrix[n - 1 - r][mid] = val;
                }
            }

            // Final validation to ensure symmetry constraints are met
            if (!isValid(matrix, n)) {
                out.println("NO");
                return;
            }

            out.println("YES");
            ArrayUtils.printMatrix(out, matrix);
        }

        /**
         * Validates that the matrix satisfies 4-fold symmetry.
         */
        private boolean isValid(int[][] matrix, int n) {
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < n; j++) {
                    if (matrix[i][j] != matrix[n - 1 - i][j] ||
                        matrix[i][j] != matrix[i][n - 1 - j] ||
                        matrix[i][j] != matrix[n - 1 - i][n - 1 - j]) {
                        return false;
                    }
                }
            }
            return true;
        }
    }

    /**
     * Utility class for common array operations.
     */
    static class ArrayUtils {
        public static void printMatrix(PrintWriter out, int[][] matrix) {
            for (int[] row : matrix) {
                for (int j = 0; j < row.length; j++) {
                    if (j > 0) out.print(' ');
                    out.print(row[j]);
                }
                out.println();
            }
        }
    }

    /**
     * Fast I/O reader optimized for competitive programming environments.
     */
    static class FastReader {
        private final InputStream stream;
        private final byte[] buf = new byte[8192];
        private int curChar;
        private int numChars;

        public FastReader(InputStream stream) {
            this.stream = stream;
        }

        private int read() {
            if (numChars == -1) {
                throw new InputMismatchException();
            }
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0) {
                    return -1;
                }
            }
            return buf[curChar++];
        }

        public int nextInt() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                res *= 10;
                res += c - '0';
                c = read();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public int[] nextIntArray(int n) {
            int[] arr = new int[n];
            for (int i = 0; i < n; i++) {
                arr[i] = nextInt();
            }
            return arr;
        }

        private boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }
    }
}

import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Scanner;

/**
 * Refactored version of the Boss class.
 * 
 * Improvements made:
 * 1. Class name changed to SymmetricGrid for clarity.
 * 2. Logic separated into methods (solveEven, solveOdd, fillQuadrants, etc.) for modularity.
 * 3. Replaced fixed-size array (size 1005) with a Map<Integer, Integer> to handle any integer range.
 * 4. Fixed potential ArrayIndexOutOfBoundsException in the original code where available groups 
 *    exceeded the required amount (using Math.min).
 * 5. Used List<Integer> instead of fixed arrays for storing groups, allowing dynamic sizing.
 * 6. Improved variable naming (e.g., n -> gridSize, c -> counts, r -> groups4).
 * 7. Used StringBuilder for efficient grid printing.
 * 8. Added input validation checks.
 */
public class SymmetricGrid {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        // Read grid size n
        if (!scanner.hasNextInt()) {
            scanner.close();
            return;
        }
        int n = scanner.nextInt();

        int totalElements = n * n;
        // Frequency map to count occurrences of each number.
        // Using a Map avoids the fixed size limitation (1005) of the original array.
        Map<Integer, Integer> counts = new HashMap<>();

        for (int i = 0; i < totalElements; i++) {
            if (scanner.hasNextInt()) {
                int val = scanner.nextInt();
                counts.put(val, counts.getOrDefault(val, 0) + 1);
            }
        }
        scanner.close();

        // Solve based on parity of n
        if (n % 2 == 0) {
            solveEven(n, counts);
        } else {
            solveOdd(n, counts);
        }
    }

    /**
     * Solves for even n.
     * The grid is divided into 4 quadrants. Each quadrant needs (n/2 * n/2) cells.
     * The logic requires filling the grid with groups of 4 identical numbers 
     * to maintain 4-way symmetry.
     */
    private static void solveEven(int n, Map<Integer, Integer> counts) {
        int neededGroups4 = (n * n) / 4;
        List<Integer> groups4 = new ArrayList<>();

        // Sort keys to process numbers in ascending order (mimicking original array scan 0..1004)
        List<Integer> sortedKeys = new ArrayList<>(counts.keySet());
        Collections.sort(sortedKeys);

        for (int val : sortedKeys) {
            int count = counts.get(val);
            if (count >= 4) {
                int availableGroups = count / 4;
                // Safety check: do not take more groups than needed to prevent overflow logic errors
                int groupsToTake = Math.min(availableGroups, neededGroups4);

                for (int i = 0; i < groupsToTake; i++) {
                    groups4.add(val);
                }
                neededGroups4 -= groupsToTake;
            }
            if (neededGroups4 == 0) break;
        }

        if (neededGroups4 != 0) {
            System.out.println("NO");
        } else {
            System.out.println("YES");
            int[][] grid = new int[n][n];
            fillQuadrants(grid, groups4, n);
            printGrid(grid);
        }
    }

    /**
     * Solves for odd n.
     * The center cell is handled separately.
     * The remaining (n-1)x(n-1) block requires groups of 4.
     * The center row and column (excluding center) require groups of 2.
     */
    private static void solveOdd(int n, Map<Integer, Integer> counts) {
        int evenSide = n - 1;
        int neededGroups4 = (evenSide * evenSide) / 4;
        int neededGroups2 = evenSide; // (n-1) pairs needed for the cross

        List<Integer> groups4 = new ArrayList<>();
        List<Integer> groups2 = new ArrayList<>();
        Integer centerValue = null;

        List<Integer> sortedKeys = new ArrayList<>(counts.keySet());
        Collections.sort(sortedKeys);

        // Pass 1: Collect groups of 4 for the quadrants
        for (int val : sortedKeys) {
            int count = counts.get(val);
            if (count >= 4 && neededGroups4 > 0) {
                int availableGroups = count / 4;
                int groupsToTake = Math.min(availableGroups, neededGroups4);

                for (int i = 0; i < groupsToTake; i++) {
                    groups4.add(val);
                }
                neededGroups4 -= groupsToTake;
                // Update count to reflect usage
                counts.put(val, count - (groupsToTake * 4));
            }
        }

        // Pass 2: Collect groups of 2 for the cross (row and column)
        for (int val : sortedKeys) {
            int count = counts.get(val);
            if (count >= 2 && neededGroups2 > 0) {
                int availablePairs = count / 2;
                int pairsToTake = Math.min(availablePairs, neededGroups2);

                for (int i = 0; i < pairsToTake; i++) {
                    groups2.add(val);
                }
                neededGroups2 -= pairsToTake;
                // Update count to reflect usage
                counts.put(val, count - (pairsToTake * 2));
            }
        }

        // Pass 3: Find a single number for the center
        if (centerValue == null) {
            for (int val : sortedKeys) {
                if (counts.get(val) > 0) {
                    centerValue = val;
                    break;
                }
            }
        }

        if (neededGroups4 != 0 || neededGroups2 != 0 || centerValue == null) {
            System.out.println("NO");
        } else {
            System.out.println("YES");
            int[][] grid = new int[n][n];
            fillQuadrants(grid, groups4, n);
            fillCross(grid, groups2, n);
            fillCenter(grid, centerValue, n);
            printGrid(grid);
        }
    }

    /**
     * Fills the four quadrants of the grid with groups of 4 identical numbers.
     */
    private static void fillQuadrants(int[][] grid, List<Integer> groups4, int n) {
        int idx = 0;
        int halfN = n / 2;
        for (int r = 0; r < halfN; r++) {
            for (int c = 0; c < halfN; c++) {
                int val = groups4.get(idx++);
                // Assign to symmetric positions
                grid[r][c] = val;
                grid[r][n - 1 - c] = val;
                grid[n - 1 - r][c] = val;
                grid[n - 1 - r][n - 1 - c] = val;
            }
        }
    }

    /**
     * Fills the center row and column (cross) with pairs of identical numbers.
     */
    private static void fillCross(int[][] grid, List<Integer> groups2, int n) {
        int mid = n / 2;
        int idx = 0;

        // Fill center row (excluding center)
        for (int k = 0; k < mid; k++) {
            int val = groups2.get(idx++);
            grid[mid][k] = val;
            grid[mid][n - 1 - k] = val;
        }

        // Fill center column (excluding center)
        for (int k = 0; k < mid; k++) {
            int val = groups2.get(idx++);
            grid[k][mid] = val;
            grid[n - 1 - k][mid] = val;
        }
    }

    /**
     * Fills the center cell.
     */
    private static void fillCenter(int[][] grid, int val, int n) {
        grid[n / 2][n / 2] = val;
    }

    /**
     * Prints the grid to stdout.
     */
    private static void printGrid(int[][] grid) {
        StringBuilder sb = new StringBuilder();
        for (int[] row : grid) {
            for (int val : row) {
                sb.append(val).append(" ");
            }
            sb.append("\n");
        }
        System.out.print(sb.toString());
    }
}

import java.io.*;
import java.util.*;

public class SymmetricMatrixFiller {

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner(System.in);
        if (!scanner.hasMoreTokens()) return;

        int n = scanner.nextInt();
        int totalElements = n * n;

        // Count frequencies of each input number
        Map<Integer, Integer> frequencyMap = new HashMap<>();
        for (int i = 0; i < totalElements; i++) {
            int value = scanner.nextInt();
            frequencyMap.merge(value, 1, Integer::sum);
        }

        // PriorityQueue sorted by frequency in descending order
        PriorityQueue<FrequencyPair> pq = new PriorityQueue<>(
                Comparator.comparingInt(FrequencyPair::count).reversed()
        );
        for (Map.Entry<Integer, Integer> entry : frequencyMap.entrySet()) {
            pq.add(new FrequencyPair(entry.getKey(), entry.getValue()));
        }

        // Initialize matrix with -1
        int[][] matrix = new int[n][n];
        for (int[] row : matrix) {
            Arrays.fill(row, -1);
        }

        boolean success = fillMatrix(matrix, pq, n);

        if (success) {
            System.out.println("YES");
            printMatrix(matrix);
        } else {
            System.out.println("NO");
        }
    }

    /**
     * Fills the matrix with symmetric patterns using the priority queue.
     */
    private static boolean fillMatrix(int[][] matrix, PriorityQueue<FrequencyPair> pq, int n) {
        // Fill top-left quadrant and its 4-way symmetric counterparts
        for (int i = 0; i < n / 2; i++) {
            for (int j = 0; j < n / 2; j++) {
                if (!fillSymmetricPositions(matrix, pq, i, j, n)) {
                    return false;
                }
            }
        }

        // Handle middle row and column for odd n
        if (n % 2 == 1) {
            int mid = n / 2;
            // Middle column (excluding center)
            for (int i = 0; i < mid; i++) {
                if (!fillSymmetricPositions(matrix, pq, i, mid, n)) {
                    return false;
                }
            }
            // Middle row (including center)
            for (int i = 0; i <= mid; i++) {
                if (!fillSymmetricPositions(matrix, pq, mid, i, n)) {
                    return false;
                }
            }
        }

        // All positions filled successfully if queue is empty
        return pq.isEmpty();
    }

    /**
     * Distributes a single frequency pair across up to 4 symmetric positions.
     */
    private static boolean fillSymmetricPositions(int[][] matrix, PriorityQueue<FrequencyPair> pq, 
                                                  int i, int j, int n) {
        if (pq.isEmpty()) return false;

        FrequencyPair pair = pq.poll();
        if (pair.count() <= 0) return false;

        int[] rowIndices = {i, n - 1 - i};
        int[] colIndices = {j, n - 1 - j};

        // Fill empty symmetric positions with the current number
        for (int r : rowIndices) {
            for (int c : colIndices) {
                if (matrix[r][c] == -1) {
                    matrix[r][c] = pair.value();
                    pair = new FrequencyPair(pair.value(), pair.count() - 1);
                }
            }
        }

        // If count remains, push back to queue
        if (pair.count() > 0) {
            pq.add(pair);
        }
        return true;
    }

    /**
     * Prints the matrix to stdout efficiently.
     */
    private static void printMatrix(int[][] matrix) {
        StringBuilder sb = new StringBuilder();
        for (int[] row : matrix) {
            for (int val : row) {
                sb.append(val).append(' ');
            }
            sb.append('\n');
        }
        System.out.print(sb);
    }

    /**
     * Immutable record to store a number and its remaining frequency.
     */
    public record FrequencyPair(int value, int count) {}

    /**
     * Fast I/O helper class to replace java.util.Scanner for better performance.
     */
    public static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        public boolean hasMoreTokens() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return false;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input", e);
                }
            }
            return true;
        }

        public String next() {
            if (hasMoreTokens()) return st.nextToken();
            throw new NoSuchElementException();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.util.ArrayDeque;
import java.util.HashMap;
import java.util.Map;
import java.util.Queue;
import java.util.Scanner;

public class Main {

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            if (!scanner.hasNextInt()) {
                return;
            }

            int n = scanner.nextInt();
            int totalElements = n * n;
            Map<Integer, Integer> freqMap = new HashMap<>();

            // Read input and build frequency map
            for (int k = 0; k < totalElements; k++) {
                int value = scanner.nextInt();
                freqMap.put(value, freqMap.getOrDefault(value, 0) + 1);
            }

            int[][] grid = new int[n][n];
            boolean possible;

            // Route to appropriate solver based on grid parity
            if (n % 2 == 0) {
                possible = solveEven(n, freqMap, grid);
            } else {
                possible = solveOdd(n, freqMap, grid);
            }

            // Output result
            if (possible) {
                System.out.println("YES");
                printGrid(grid);
            } else {
                System.out.println("NO");
            }
        }
    }

    /**
     * Solves for even-sized grids. Every number must appear in multiples of 4
     * to maintain 4-way symmetry across both axes.
     */
    private static boolean solveEven(int n, Map<Integer, Integer> freqMap, int[][] grid) {
        Queue<Integer> quadrantQueue = new ArrayDeque<>();

        for (Map.Entry<Integer, Integer> entry : freqMap.entrySet()) {
            int count = entry.getValue();
            if (count % 4 != 0) {
                return false;
            }
            // Each group of 4 will fill one symmetric set of 4 cells
            for (int k = 0; k < count / 4; k++) {
                quadrantQueue.add(entry.getKey());
            }
        }

        int half = n / 2;
        for (int i = 0; i < half; i++) {
            for (int j = 0; j < half; j++) {
                if (quadrantQueue.isEmpty()) {
                    return false; // Should not occur if input validation passes
                }
                int value = quadrantQueue.poll();
                // Fill the 4 symmetric positions
                grid[i][j] = grid[n - 1 - i][j] = grid[i][n - 1 - j] = grid[n - 1 - i][n - 1 - j] = value;
            }
        }
        return true;
    }

    /**
     * Solves for odd-sized grids. Handles center placement and axis symmetry.
     * Numbers with remainder 1 go to center, remainder 2/3 go to axis pairs,
     * remainder 0 fill quadrants.
     */
    private static boolean solveOdd(int n, Map<Integer, Integer> freqMap, int[][] grid) {
        Queue<Integer> quadrantQueue = new ArrayDeque<>();
        Queue<Integer> axisQueue = new ArrayDeque<>();
        Integer centerValue = null;

        for (Map.Entry<Integer, Integer> entry : freqMap.entrySet()) {
            int count = entry.getValue();
            int remainder = count % 4;

            if (remainder == 1) {
                if (centerValue != null) return false; // Only one center allowed
                centerValue = entry.getKey();
            } else if (remainder == 2) {
                axisQueue.add(entry.getKey());
            } else if (remainder == 3) {
                axisQueue.add(entry.getKey()); // Contributes to a pair
                if (centerValue != null) return false;
                centerValue = entry.getKey();  // Remaining 1 goes to center
            }

            // Multiples of 4 go to quadrants
            for (int k = 0; k < count / 4; k++) {
                quadrantQueue.add(entry.getKey());
            }
        }

        int half = n / 2;

        // 1. Fill the four symmetric quadrants
        for (int i = 0; i < half; i++) {
            for (int j = 0; j < half; j++) {
                if (quadrantQueue.isEmpty()) return false;
                int value = quadrantQueue.poll();
                grid[i][j] = grid[n - 1 - i][j] = grid[i][n - 1 - j] = grid[n - 1 - i][n - 1 - j] = value;
            }
        }

        // 2. Fill the middle row (left and right of center)
        for (int j = 0; j < half; j++) {
            if (axisQueue.isEmpty()) {
                if (quadrantQueue.isEmpty()) return false;
                // Convert a quadrant set into two axis pairs
                int value = quadrantQueue.poll();
                axisQueue.add(value);
                axisQueue.add(value);
            }
            if (axisQueue.isEmpty()) return false;
            int value = axisQueue.poll();
            grid[half][j] = grid[half][n - 1 - j] = value;
        }

        // 3. Fill the middle column (top and bottom of center)
        for (int i = 0; i < half; i++) {
            if (axisQueue.isEmpty()) {
                if (quadrantQueue.isEmpty()) return false;
                int value = quadrantQueue.poll();
                axisQueue.add(value);
                axisQueue.add(value);
            }
            if (axisQueue.isEmpty()) return false;
            int value = axisQueue.poll();
            grid[i][half] = grid[n - 1 - i][half] = value;
        }

        // 4. Place center value
        grid[half][half] = centerValue;
        return true;
    }

    /**
     * Prints the grid to standard output with space-separated values.
     */
    private static void printGrid(int[][] grid) {
        for (int[] row : grid) {
            StringBuilder line = new StringBuilder();
            for (int i = 0; i < row.length; i++) {
                line.append(row[i]);
                if (i < row.length - 1) {
                    line.append(' ');
                }
            }
            System.out.println(line);
        }
    }
}

import java.io.PrintWriter;
import java.util.Arrays;
import java.util.Scanner;

/**
 * Refactored Palindromic Matrix solution.
 * 
 * This program determines if a given set of n*n integers can form a 
 * Palindromic Matrix (a matrix that reads the same forwards and backwards 
 * in rows, columns, and diagonals).
 * 
 * Refactoring Improvements:
 * 1. Separation of Concerns: Logic is split into specific methods (solveEven, solveOdd, buildMatrix).
 * 2. Readability: Variable names are descriptive (e.g., quadrantMatrix, cornerValues).
 * 3. Maintainability: Magic numbers are replaced or encapsulated; logic is easier to follow.
 * 4. Robustness: Added checks for array bounds and validity conditions.
 */
public class PalindromicMatrix {

    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            if (in.hasNextInt()) {
                int n = in.nextInt();
                int totalElements = n * n;
                int[] arr = new int[totalElements];
                for (int i = 0; i < totalElements; i++) {
                    arr[i] = in.nextInt();
                }

                // Sorting is required to easily group identical numbers
                Arrays.sort(arr);

                int[][] resultMatrix = solve(n, arr);

                if (resultMatrix != null) {
                    out.println("YES");
                    printMatrix(resultMatrix, out);
                } else {
                    out.println("NO");
                }
            }
        } finally {
            in.close();
            out.flush();
            out.close();
        }
    }

    /**
     * Main solver method that dispatches to specific logic based on matrix dimension parity.
     */
    private static int[][] solve(int n, int[] arr) {
        if (n % 2 == 0) {
            return solveEven(n, arr);
        } else {
            return solveOdd(n, arr);
        }
    }

    /**
     * Handles the case where n is even.
     * In an even matrix, every number must appear in multiples of 4 
     * to satisfy the 4-fold symmetry of the corners.
     */
    private static int[][] solveEven(int n, int[] arr) {
        int half = n / 2;
        int totalElements = n * n;
        // Quadrant matrix represents the top-left (n/2 x n/2) section
        int[][] quadrantMatrix = new int[half][half];

        // Iterate through the sorted array in blocks of 4
        for (int k = 0; k < totalElements; k += 4) {
            int val = arr[k];

            // Check if the group of 4 elements are identical
            // Since array is sorted, we just check against the first element of the block
            if (arr[k] != val || arr[k + 1] != val || arr[k + 2] != val || arr[k + 3] != val) {
                return null; // Invalid configuration
            }

            // Map the block index to the quadrant matrix coordinates
            // Block 0 (indices 0-3) -> quadrantMatrix[0][0]
            // Block 1 (indices 4-7) -> quadrantMatrix[0][1]
            int blockIndex = k / 4;
            int r = blockIndex / half;
            int c = blockIndex % half;

            quadrantMatrix[r][c] = val;
        }

        return buildMatrix(n, quadrantMatrix);
    }

    /**
     * Handles the case where n is odd.
     * Requires exactly one number for the center (odd count), 
     * and remaining numbers distributed into corners (multiples of 4) 
     * and edges (multiples of 2).
     */
    private static int[][] solveOdd(int n, int[] arr) {
        int half = n / 2; // Integer division, e.g., 3/2 = 1
        int totalElements = n * n;
        int quadrantSize = half + 1; // (n + 1) / 2
        int[][] quadrantMatrix = new int[quadrantSize][quadrantSize];

        // Arrays to hold values for corners (groups of 4) and edges (groups of 2)
        // Corner values fill the top-left (half x half) block of the quadrant matrix.
        // Edge values fill the middle row and middle column of the quadrant matrix.
        int[] cornerValues = new int[half * half];
        int[] edgeValues = new int[2 * half];
        int centerValue = -1;

        int cornerIdx = 0;
        int edgeIdx = 0;

        int i = 0;
        while (i < totalElements) {
            int j = i;
            // Count frequency of the current number
            while (j < totalElements && arr[j] == arr[i]) {
                j++;
            }
            int count = j - i;
            int val = arr[i];

            // If count is odd, one instance must be the center
            if (count % 2 != 0) {
                if (centerValue != -1) {
                    return null; // More than one potential center found
                }
                centerValue = val;
                count--; // Reserve 1 for center
            }

            // Distribute the remaining even count
            if (count > 0) {
                // Prioritize filling corners (groups of 4)
                while (count >= 4 && cornerIdx < cornerValues.length) {
                    cornerValues[cornerIdx++] = val;
                    count -= 4;
                }
                // Then fill edges (groups of 2)
                while (count >= 2 && edgeIdx < edgeValues.length) {
                    edgeValues[edgeIdx++] = val;
                    count -= 2;
                }

                // If there are leftover elements that don't fit in 4s or 2s, it's invalid
                if (count > 0) {
                    return null;
                }
            }

            i = j;
        }

        // Validation checks
        if (centerValue == -1) return null; // No center found
        if (cornerIdx != cornerValues.length) return null; // Not enough corner values
        if (edgeIdx != edgeValues.length) return null; // Not enough edge values

        // Fill the quadrant matrix
        // 1. Top-Left block (Corners)
        for (int r = 0; r < half; r++) {
            for (int c = 0; c < half; c++) {
                quadrantMatrix[r][c] = cornerValues[r * half + c];
            }
        }

        // 2. Middle Column (top part)
        for (int r = 0; r < half; r++) {
            quadrantMatrix[r][half] = edgeValues[r];
        }

        // 3. Middle Row (left part)
        for (int c = 0; c < half; c++) {
            quadrantMatrix[half][c] = edgeValues[half + c];
        }

        // 4. Center
        quadrantMatrix[half][half] = centerValue;

        return buildMatrix(n, quadrantMatrix);
    }

    /**
     * Mirrors the top-left quadrant matrix to form the full palindromic matrix.
     * The quadrant matrix contains the top-left (n+1)/2 x (n+1)/2 section.
     */
    private static int[][] buildMatrix(int n, int[][] quadrantMatrix) {
        int[][] matrix = new int[n][n];
        int halfQuadrant = quadrantMatrix.length;

        for (int r = 0; r < halfQuadrant; r++) {
            for (int c = 0; c < halfQuadrant; c++) {
                int val = quadrantMatrix[r][c];
                // Assign to all 4 symmetric positions
                matrix[r][c] = val;
                matrix[n - 1 - r][c] = val;
                matrix[r][n - 1 - c] = val;
                matrix[n - 1 - r][n - 1 - c] = val;
            }
        }
        return matrix;
    }

    /**
     * Prints the matrix to the PrintWriter.
     */
    private static void printMatrix(int[][] matrix, PrintWriter out) {
        int n = matrix.length;
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < n - 1; c++) {
                out.print(matrix[r][c] + " ");
            }
            out.println(matrix[r][n - 1]);
        }
    }
}

import java.util.Scanner;

public class CodeForces540C {
    // Maximum possible value for elements as per problem constraints (1 to 1000)
    private static final int MAX_VAL = 1000;

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        if (!scanner.hasNextInt()) return;

        int n = scanner.nextInt();
        int[] counts = new int[MAX_VAL + 1];

        // Read n*n integers and populate frequency map
        int limit = n * n;
        for (int i = 0; i < limit; i++) {
            if (scanner.hasNextInt()) {
                int val = scanner.nextInt();
                if (val >= 1 && val <= MAX_VAL) {
                    counts[val]++;
                }
            }
        }

        System.out.println(solve(counts, n));
    }

    /**
     * Solves the problem by constructing the matrix or determining if it's impossible.
     * 
     * @param counts Frequency array of available numbers.
     * @param n Dimension of the matrix.
     * @return "YES" and the matrix, or "NO".
     */
    public static String solve(int[] counts, int n) {
        int[][] matrix = new int[n][n];

        // 1. Handle Center (if n is odd)
        // The center element must be unique and consume 1 count.
        // Thus, there must be exactly one number with an odd count.
        if (n % 2 == 1) {
            int centerVal = -1;
            for (int i = 1; i <= MAX_VAL; i++) {
                if (counts[i] % 2 != 0) {
                    if (centerVal != -1) return "NO"; // More than one odd count
                    centerVal = i;
                }
            }

            if (centerVal != -1) {
                matrix[n / 2][n / 2] = centerVal;
                counts[centerVal]--;
            } else {
                // Odd n requires a center element. If no odd count, impossible.
                return "NO";
            }
        }

        // 2. Fill Middle Column (indices 0 to n/2 - 1)
        // We need to fill pairs: matrix[i][n/2] and matrix[n-1-i][n/2].
        // Priority: Numbers with count % 4 != 0 (remainder 2) must go here,
        // as they cannot form groups of 4 for the quadrants.
        for (int i = 0; i < n / 2; i++) {
            int val = findNumberForCross(counts, n, true);
            if (val != -1) {
                matrix[i][n / 2] = val;
                matrix[n - 1 - i][n / 2] = val;
                counts[val] -= 2;
            }
            // If val is -1, spot remains 0, to be filled in gap-filling phase
        }

        // 3. Fill Middle Row (indices 0 to n/2 - 1)
        // We need to fill pairs: matrix[n/2][i] and matrix[n/2][n-1-i].
        // Same priority logic as Middle Column.
        for (int i = 0; i < n / 2; i++) {
            int val = findNumberForCross(counts, n, true);
            if (val != -1) {
                matrix[n / 2][i] = val;
                matrix[n / 2][n - 1 - i] = val;
                counts[val] -= 2;
            }
        }

        // 4. Fill gaps in Middle Column and Middle Row with ANY number
        // If the previous steps didn't fill a spot, we try to fill it with any available number.
        for (int i = 0; i < n / 2; i++) {
            // Check Middle Column
            if (matrix[i][n / 2] == 0) {
                int val = findNumberForCross(counts, n, false);
                if (val == -1) return "NO";
                matrix[i][n / 2] = val;
                matrix[n - 1 - i][n / 2] = val;
                counts[val] -= 2;
            }
            // Check Middle Row
            if (matrix[n / 2][i] == 0) {
                int val = findNumberForCross(counts, n, false);
                if (val == -1) return "NO";
                matrix[n / 2][i] = val;
                matrix[n / 2][n - 1 - i] = val;
                counts[val] -= 2;
            }
        }

        // 5. Fill Quadrants
        // The remaining cells must be filled in groups of 4 symmetric cells.
        // Any number used here must have a count divisible by 4.
        int x = 0;
        int y = 0;
        for (int val = 1; val <= MAX_VAL; val++) {
            if (counts[val] % 4 != 0) return "NO";

            while (counts[val] > 0) {
                if (x >= n / 2 || y >= n / 2) return "NO";

                matrix[x][y] = val;
                matrix[x][n - 1 - y] = val;
                matrix[n - 1 - x][y] = val;
                matrix[n - 1 - x][n - 1 - y] = val;

                counts[val] -= 4;

                x++;
                if (x == n / 2) {
                    x = 0;
                    y++;
                }
            }
        }

        // 6. Final Validation
        // Check if matrix is fully filled (no 0s remaining)
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (matrix[i][j] == 0) return "NO";
            }
        }

        // Check if all counts are exhausted
        for (int c : counts) {
            if (c != 0) return "NO";
        }

        // Output
        StringBuilder sb = new StringBuilder("YES\n");
        for (int[] row : matrix) {
            for (int val : row) {
                sb.append(val).append(" ");
            }
            sb.append("\n");
        }
        return sb.toString();
    }

    /**
     * Helper method to find a suitable number for the cross (Middle Row/Col).
     * 
     * @param counts Frequency array.
     * @param n Matrix dimension (unused here but kept for signature consistency).
     * @param preferRemainder2 If true, prioritizes numbers with count % 4 != 0.
     * @return The number value, or -1 if none found.
     */
    private static int findNumberForCross(int[] counts, int n, boolean preferRemainder2) {
        // Pass 1: Look for remainder 2 (count % 4 != 0)
        // These numbers are critical for the cross because they can't fill quadrants (needs 4).
        if (preferRemainder2) {
            for (int i = 1; i <= MAX_VAL; i++) {
                if (counts[i] > 0 && counts[i] % 4 != 0) {
                    return i;
                }
            }
        }

        // Pass 2: Look for any available number
        for (int i = 1; i <= MAX_VAL; i++) {
            if (counts[i] > 0) {
                return i;
            }
        }

        return -1;
    }
}

import java.util.HashMap;
import java.util.Map;
import java.util.Scanner;

public class PalindromicMatrix {

    public static void main(String[] args) {
        // Use try-with-resources to ensure Scanner is closed automatically
        try (Scanner scanner = new Scanner(System.in)) {
            if (!scanner.hasNextInt()) {
                return;
            }
            int n = scanner.nextInt();
            int totalElements = n * n;

            // Count frequencies of each number using modern Map API
            Map<Integer, Integer> frequencyMap = new HashMap<>();
            for (int i = 0; i < totalElements; i++) {
                int value = scanner.nextInt();
                frequencyMap.merge(value, 1, Integer::sum);
            }

            // Validate if a palindromic matrix can be formed
            if (canFormPalindromicMatrix(n, frequencyMap)) {
                System.out.println("YES");
                int[][] matrix = constructPalindromicMatrix(n, frequencyMap);
                printMatrix(matrix);
            } else {
                System.out.println("NO");
            }
        }
    }

    /**
     * Checks if the given frequencies can form a palindromic matrix.
     * For even n, all frequencies must be even.
     * For odd n, exactly one frequency must be odd (reserved for the center element).
     */
    private static boolean canFormPalindromicMatrix(int n, Map<Integer, Integer> freq) {
        int oddFrequencyCount = 0;
        for (int count : freq.values()) {
            if (count % 2 != 0) {
                oddFrequencyCount++;
            }
        }
        if (n % 2 == 0) {
            return oddFrequencyCount == 0;
        }
        return oddFrequencyCount == 1;
    }

    /**
     * Constructs the palindromic matrix by filling symmetric positions layer by layer.
     */
    private static int[][] constructPalindromicMatrix(int n, Map<Integer, Integer> freq) {
        int[][] matrix = new int[n][n];

        // Iterate through each concentric layer of the matrix
        for (int i = 0; i < (n + 1) / 2; i++) {
            for (int j = i; j < n - i; j++) {
                // Skip right-half duplicates to avoid overwriting and double-decrementing frequency
                if (j > n - 1 - j) {
                    break;
                }

                int requiredCount = getRequiredCount(i, j, n);
                int value = pickAndDecrementFrequency(freq, requiredCount);

                if (value == -1) {
                    throw new IllegalStateException("Insufficient elements to complete the matrix.");
                }

                fillSymmetricPositions(matrix, i, j, value, n);
            }
        }
        return matrix;
    }

    /**
     * Determines how many unique cells are covered by the symmetric positions of (row, col).
     * A palindromic matrix requires symmetry across both axes:
     * (r, c) == (r, n-1-c) == (n-1-r, c) == (n-1-r, n-1-c)
     */
    private static int getRequiredCount(int row, int col, int n) {
        boolean isCenter = (n % 2 != 0 && row == n / 2 && col == n / 2);
        boolean isEdge = (n % 2 != 0 && (row == n / 2 || col == n / 2));

        if (isCenter) return 1;
        if (isEdge) return 2;
        return 4;
    }

    /**
     * Finds a number with sufficient remaining frequency and decrements it.
     * Greedily picks the first available candidate.
     */
    private static int pickAndDecrementFrequency(Map<Integer, Integer> freq, int requiredCount) {
        for (Map.Entry<Integer, Integer> entry : freq.entrySet()) {
            if (entry.getValue() >= requiredCount) {
                int value = entry.getKey();
                int remaining = entry.getValue() - requiredCount;
                if (remaining == 0) {
                    freq.remove(value);
                } else {
                    freq.put(value, remaining);
                }
                return value;
            }
        }
        return -1;
    }

    /**
     * Fills all symmetric positions for a given cell with the specified value.
     */
    private static void fillSymmetricPositions(int[][] matrix, int row, int col, int value, int n) {
        matrix[row][col] = value;
        matrix[row][n - 1 - col] = value;
        matrix[n - 1 - row][col] = value;
        matrix[n - 1 - row][n - 1 - col] = value;
    }

    /**
     * Prints the matrix to standard output with space-separated values.
     */
    private static void printMatrix(int[][] matrix) {
        for (int[] row : matrix) {
            for (int i = 0; i < row.length; i++) {
                System.out.print(row[i] + (i < row.length - 1 ? " " : ""));
            }
            System.out.println();
        }
    }
}

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Scanner;

public class SymmetricMatrixGenerator {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        // Ensure there is input to read
        if (!scanner.hasNextInt()) {
            scanner.close();
            return;
        }

        int n = scanner.nextInt();
        Map<Integer, Integer> counts = new HashMap<>();

        // Read matrix elements and count frequencies
        // The original code reads n*n integers, counts them, and then resets the matrix to 0.
        int totalElements = n * n;
        for (int i = 0; i < totalElements; i++) {
            if (scanner.hasNextInt()) {
                int val = scanner.nextInt();
                counts.put(val, counts.getOrDefault(val, 0) + 1);
            }
        }
        scanner.close();

        int[][] matrix = new int[n][n];
        // Extract keys to a list to maintain iteration order (similar to original array behavior)
        List<Integer> keys = new ArrayList<>(counts.keySet());
        int numKeys = keys.size();
        int keyIdx = 0;
        int halfN = n / 2;

        // Phase 1: Fill Quadrants (requires 4 of a number)
        // Fills top-left quadrant, which determines the other 3 quadrants symmetrically
        for (int r = 0; r < halfN; r++) {
            for (int c = 0; c < halfN; c++) {
                // Find a number with at least 4 occurrences
                while (keyIdx < numKeys && counts.get(keys.get(keyIdx)) < 4) {
                    keyIdx++;
                }

                if (keyIdx >= numKeys) {
                    // Not enough numbers to fill this spot
                    break;
                }

                int val = keys.get(keyIdx);

                // Place value in symmetric positions
                matrix[r][c] = val;
                matrix[r][n - 1 - c] = val;
                matrix[n - 1 - r][c] = val;
                matrix[n - 1 - r][n - 1 - c] = val;

                counts.put(val, counts.get(val) - 4);

                // If this number is now insufficient for the next 4-cell block, move to next key
                if (counts.get(val) < 4) {
                    keyIdx++;
                }
            }
        }

        // Phase 2: Handle Odd Dimensions
        if (n % 2 != 0) {
            int mid = n / 2;

            // Phase 2a: Fill Middle Column (requires 2 of a number)
            // Original code resets keyIdx to 0 here to re-scan from the beginning
            keyIdx = 0; 
            for (int r = 0; r < halfN; r++) {
                while (keyIdx < numKeys && counts.get(keys.get(keyIdx)) < 2) {
                    keyIdx++;
                }
                if (keyIdx >= numKeys) break;

                int val = keys.get(keyIdx);
                matrix[r][mid] = val;
                matrix[n - 1 - r][mid] = val;

                counts.put(val, counts.get(val) - 2);

                if (counts.get(val) < 2) {
                    keyIdx++;
                }
            }

            // Phase 2b: Fill Middle Row (requires 2 of a number)
            // Original code resets keyIdx to 0 here
            keyIdx = 0;
            for (int c = 0; c < halfN; c++) {
                while (keyIdx < numKeys && counts.get(keys.get(keyIdx)) < 2) {
                    keyIdx++;
                }
                if (keyIdx >= numKeys) break;

                int val = keys.get(keyIdx);
                matrix[mid][c] = val;
                matrix[mid][n - 1 - c] = val;

                counts.put(val, counts.get(val) - 2);

                if (counts.get(val) < 2) {
                    keyIdx++;
                }
            }

            // Phase 2c: Fill Center Cell (requires 1 of a number)
            // Original code scans keys linearly to find first available
            for (int k = 0; k < numKeys; k++) {
                if (counts.get(keys.get(k)) >= 1) {
                    matrix[mid][mid] = keys.get(k);
                    counts.put(keys.get(k), counts.get(keys.get(k)) - 1);
                    break;
                }
            }
        }

        // Validation: Check if any counts remain
        boolean possible = true;
        for (int count : counts.values()) {
            if (count > 0) {
                possible = false;
                break;
            }
        }

        if (!possible) {
            System.out.println("NO");
        } else {
            System.out.println("YES");
            for (int[] row : matrix) {
                for (int val : row) {
                    System.out.print(val + " ");
                }
                System.out.println();
            }
        }
    }
}

import java.io.*;
import java.util.*;

public class Solution {
    private static final int MAX_VALUE = 1000;

    public static void main(String[] args) throws IOException {
        try (FastReader sc = new FastReader();
             PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out))) {

            int n = sc.nextInt();
            int[] frequencyCounts = new int[MAX_VALUE + 1];
            int totalElements = n * n;

            // Count frequencies of each number
            for (int i = 0; i < totalElements; i++) {
                frequencyCounts[sc.nextInt()]++;
            }

            // Decompose counts into singles, pairs, and quadruplets
            int[] singles = new int[totalElements];
            int[] pairs = new int[totalElements];
            int[] quadrants = new int[totalElements];
            int sSize = 0, pSize = 0, qSize = 0;

            for (int val = 0; val <= MAX_VALUE; val++) {
                int count = frequencyCounts[val];
                int quads = count / 4;
                int rem = count % 4;
                int pairsCount = rem / 2;
                int singlesCount = rem % 2;

                for (int k = 0; k < quads; k++) quadrants[qSize++] = val;
                for (int k = 0; k < pairsCount; k++) pairs[pSize++] = val;
                for (int k = 0; k < singlesCount; k++) singles[sSize++] = val;
            }

            // Validate if a valid grid configuration is possible
            if (isValidConfiguration(n, sSize, pSize)) {
                out.println("YES");
                int[][] grid = buildGrid(n, singles, pairs, quadrants, sSize, pSize, qSize);
                printGrid(out, grid);
            } else {
                out.println("NO");
            }
        }
    }

    /**
     * Checks if the collected counts satisfy the symmetry constraints for an n x n grid.
     */
    private static boolean isValidConfiguration(int n, int sSize, int pSize) {
        if (n % 2 == 0) {
            // Even grids require perfect 4-fold symmetry (no singles or pairs)
            return sSize == 0 && pSize == 0;
        }
        // Odd grids require exactly one center element (single) and at most n-1 pairs
        return sSize == 1 && pSize <= n - 1;
    }

    /**
     * Constructs the n x n grid using 4-fold, 2-fold, and 1-fold symmetry.
     */
    private static int[][] buildGrid(int n, int[] singles, int[] pairs, int[] quadrants, 
                                     int sSize, int pSize, int qSize) {
        int[][] grid = new int[n][n];
        int half = (n + 1) / 2;
        int pIdx = 0;
        int qIdx = 0;

        for (int i = 0; i < half; i++) {
            for (int j = 0; j < half; j++) {
                if (i == n / 2 && j == n / 2) {
                    // Center element (1-fold symmetry)
                    grid[i][j] = singles[0];
                } else if (i != n / 2 && j != n / 2) {
                    // Corner quadrants (4-fold symmetry)
                    int val = quadrants[qIdx++];
                    grid[i][j] = grid[n - 1 - i][j] = grid[n - 1 - i][n - 1 - j] = grid[i][n - 1 - j] = val;
                } else if (i == n / 2) {
                    // Middle row (2-fold symmetry)
                    if (pIdx >= pSize) {
                        // Split a quadrant into two pairs when initial pairs are exhausted
                        int val = quadrants[--qIdx];
                        pairs[pIdx++] = val;
                        pairs[pIdx++] = val;
                    }
                    int val = pairs[pIdx++];
                    grid[i][j] = grid[i][n - 1 - j] = val;
                } else if (j == n / 2) {
                    // Middle column (2-fold symmetry)
                    if (pIdx >= pSize) {
                        int val = quadrants[--qIdx];
                        pairs[pIdx++] = val;
                        pairs[pIdx++] = val;
                    }
                    int val = pairs[pIdx++];
                    grid[i][j] = grid[n - 1 - i][j] = val;
                }
            }
        }
        return grid;
    }

    /**
     * Prints the grid to the output stream.
     */
    private static void printGrid(PrintWriter out, int[][] grid) {
        for (int[] row : grid) {
            for (int i = 0; i < row.length; i++) {
                out.print(row[i]);
                out.print(i == row.length - 1 ? "" : " ");
            }
            out.println();
        }
    }

    /**
     * Lightweight fast I/O helper for competitive programming and large inputs.
     */
    private static class FastReader {
        BufferedReader br;
        StringTokenizer st;

        public FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    e.printStackTrace();
                    return null;
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            String s = next();
            return s == null ? 0 : Integer.parseInt(s);
        }
    }
}

import java.io.*;
import java.util.StringTokenizer;

public class ProblemC {

    private static final int MAX_VALUE = 1000;

    public static void main(String[] args) {
        // Use try-with-resources for automatic and safe resource management
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
             PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out))) {

            FastScanner scanner = new FastScanner(br);
            int n = scanner.nextInt();

            // Frequency array for numbers 1 to 1000
            int[] counts = new int[MAX_VALUE + 1];
            for (int i = 0; i < n * n; i++) {
                counts[scanner.nextInt()]++;
            }

            int[][] grid = new int[n][n];
            boolean possible = true;

            // Phase 1: Fill 2x2 quadrants (each number appears 4 times symmetrically)
            if (possible) {
                possible = fillQuadrants(grid, counts, n);
            }

            // Phase 2: Handle odd dimensions
            if (possible && n % 2 == 1) {
                int mid = n / 2;
                // Fill top and bottom halves of the middle column
                possible = fillVerticalMiddle(grid, counts, n, mid);
                // Fill left and right halves of the middle row
                possible = fillHorizontalMiddle(grid, counts, n, mid);
                // Fill the center cell
                possible = fillCenter(grid, counts, mid);
            }

            // Output results
            if (possible) {
                out.println("YES");
                for (int i = 0; i < n; i++) {
                    for (int j = 0; j < n; j++) {
                        out.print(grid[i][j] + " ");
                    }
                    out.println();
                }
            } else {
                out.println("NO");
            }

        } catch (Exception e) {
            // Fallback in case of unexpected errors during execution
            System.err.println("Execution error: " + e.getMessage());
        } finally {
            out.flush();
        }
    }

    /**
     * Fills the 2x2 quadrants of the grid.
     * Each selected number is placed at four symmetric positions and its count is reduced by 4.
     */
    private static boolean fillQuadrants(int[][] grid, int[] counts, int n) {
        int currentVal = 0;
        for (int i = 0; i < n / 2; i++) {
            for (int j = 0; j < n / 2; j++) {
                currentVal = findNextAvailable(counts, 4, currentVal);
                if (currentVal == -1) return false;

                grid[i][j] = currentVal;
                grid[i][n - 1 - j] = currentVal;
                grid[n - 1 - i][j] = currentVal;
                grid[n - 1 - i][n - 1 - j] = currentVal;
                counts[currentVal] -= 4;
            }
        }
        return true;
    }

    /**
     * Fills the top and bottom halves of the middle column.
     * Each selected number is placed at two symmetric positions and its count is reduced by 2.
     */
    private static boolean fillVerticalMiddle(int[][] grid, int[] counts, int n, int mid) {
        int currentVal = 0;
        for (int i = 0; i < n / 2; i++) {
            currentVal = findNextAvailable(counts, 2, currentVal);
            if (currentVal == -1) return false;

            grid[i][mid] = currentVal;
            grid[n - 1 - i][mid] = currentVal;
            counts[currentVal] -= 2;
        }
        return true;
    }

    /**
     * Fills the left and right halves of the middle row.
     * Each selected number is placed at two symmetric positions and its count is reduced by 2.
     */
    private static boolean fillHorizontalMiddle(int[][] grid, int[] counts, int n, int mid) {
        int currentVal = 0;
        for (int i = 0; i < n / 2; i++) {
            currentVal = findNextAvailable(counts, 2, currentVal);
            if (currentVal == -1) return false;

            grid[mid][i] = currentVal;
            grid[mid][n - 1 - i] = currentVal;
            counts[currentVal] -= 2;
        }
        return true;
    }

    /**
     * Finds the center cell.
     * Requires a number that appears exactly once.
     */
    private static boolean fillCenter(int[][] grid, int[] counts, int mid) {
        for (int i = 1; i <= MAX_VALUE; i++) {
            if (counts[i] == 1) {
                grid[mid][mid] = i;
                return true;
            }
        }
        return false;
    }

    /**
     * Finds the next available number in the counts array that has at least the required frequency.
     * Scans linearly from the given start index to maintain the original greedy assignment order.
     *
     * @param counts   Frequency array of numbers
     * @param required Minimum frequency needed
     * @param startFrom Index to begin scanning from
     * @return The number index if found, otherwise -1
     */
    private static int findNextAvailable(int[] counts, int required, int startFrom) {
        for (int i = startFrom; i <= MAX_VALUE; i++) {
            if (counts[i] >= required) {
                return i;
            }
        }
        return -1;
    }

    /**
     * Efficient scanner for reading whitespace-delimited tokens from input.
     */
    private static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner(BufferedReader br) {
            this.br = br;
        }

        public String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input", e);
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            String token = next();
            if (token == null) throw new RuntimeException("Unexpected end of input");
            return Integer.parseInt(token);
        }
    }
}

import java.io.*;
import java.util.*;

public class Main {
    private static final int MAX_VALUE = 1000;

    public static void main(String[] args) throws IOException {
        FastReader reader = new FastReader();
        PrintWriter out = new PrintWriter(System.out);

        int n = reader.nextInt();

        // Edge case: 1x1 matrix
        if (n == 1) {
            out.println("YES");
            out.println(reader.nextInt());
            out.flush();
            return;
        }

        int[] counts = new int[MAX_VALUE + 1];
        int totalElements = n * n;
        for (int i = 0; i < totalElements; i++) {
            counts[reader.nextInt()]++;
        }

        int[][] matrix = new int[n][n];
        Queue<Integer> fourQueue = new ArrayDeque<>();
        int oddCount = 0;
        int evenNotDivBy4Count = 0;

        // Categorize numbers based on their frequencies
        for (int val = 1; val <= MAX_VALUE; val++) {
            int count = counts[val];
            if (count == 0) continue;

            if (count % 4 != 0) {
                if (count % 2 == 0) {
                    evenNotDivBy4Count++;
                } else {
                    oddCount++;
                }
            }
            if (count >= 4) {
                fourQueue.offer(val);
            }
        }

        // Validate if a valid symmetric matrix can be constructed
        if (!isValid(n, oddCount, evenNotDivBy4Count)) {
            out.println("NO");
            out.flush();
            return;
        }

        // Fill the four symmetric quadrants
        fillQuadrants(matrix, n, counts, fourQueue);

        // Fill middle row, middle column, and center if n is odd
        if (n % 2 == 1) {
            Queue<Integer> twoQueue = new ArrayDeque<>();
            for (int val = 1; val <= MAX_VALUE; val++) {
                if (counts[val] > 0) {
                    twoQueue.offer(val);
                }
            }
            fillMiddleCross(matrix, n, counts, twoQueue);
            fillCenter(matrix, n, counts);
        }

        out.println("YES");
        printMatrix(out, matrix);
        out.flush();
    }

    /**
     * Validates whether the input frequencies can form a valid symmetric matrix.
     * - Even n: All numbers must appear a multiple of 4 times.
     * - Odd n: Exactly one number can have an odd count (center), 
     *          and at most n-1 numbers can have even counts not divisible by 4 (middle cross).
     */
    private static boolean isValid(int n, int oddCount, int evenNotDivBy4Count) {
        if (n % 2 == 0) {
            return oddCount == 0 && evenNotDivBy4Count == 0;
        } else {
            return oddCount == 1 && evenNotDivBy4Count <= n - 1;
        }
    }

    private static void fillQuadrants(int[][] matrix, int n, int[] counts, Queue<Integer> fourQueue) {
        for (int i = 0; i < n / 2; i++) {
            for (int j = 0; j < n / 2; j++) {
                int val = getNextValue(fourQueue, counts, 4);
                matrix[i][j] = val;
                matrix[i][n - 1 - j] = val;
                matrix[n - 1 - i][j] = val;
                matrix[n - 1 - i][n - 1 - j] = val;
                counts[val] -= 4;
            }
        }
    }

    private static void fillMiddleCross(int[][] matrix, int n, int[] counts, Queue<Integer> twoQueue) {
        // Fill middle row
        for (int j = 0; j < n / 2; j++) {
            int val = getNextValue(twoQueue, counts, 2);
            matrix[n / 2][j] = val;
            matrix[n / 2][n - 1 - j] = val;
            counts[val] -= 2;
        }
        // Fill middle column
        for (int i = 0; i < n / 2; i++) {
            int val = getNextValue(twoQueue, counts, 2);
            matrix[i][n / 2] = val;
            matrix[n - 1 - i][n / 2] = val;
            counts[val] -= 2;
        }
    }

    private static void fillCenter(int[][] matrix, int n, int[] counts) {
        for (int val = 1; val <= MAX_VALUE; val++) {
            if (counts[val] > 0) {
                matrix[n / 2][n / 2] = val;
                break;
            }
        }
    }

    /**
     * Retrieves the next valid value from the queue that has at least 'needed' occurrences left.
     */
    private static int getNextValue(Queue<Integer> queue, int[] counts, int needed) {
        while (!queue.isEmpty() && counts[queue.peek()] < needed) {
            queue.poll();
        }
        if (queue.isEmpty()) {
            throw new IllegalStateException("Invalid state: not enough elements to fill required positions.");
        }
        return queue.poll();
    }

    private static void printMatrix(PrintWriter out, int[][] matrix) {
        for (int[] row : matrix) {
            for (int val : row) {
                out.print(val).print(' ');
            }
            out.println();
        }
    }

    /**
     * Fast I/O helper class for competitive programming.
     */
    static class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        public String next() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) return null;
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

        public int nextInt() throws IOException {
            String s = next();
            return s == null ? 0 : Integer.parseInt(s);
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.HashMap;
import java.util.Map;
import java.util.StringTokenizer;

public class PalindromicMatrix {

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner();
        // Check if input is available
        String nStr = scanner.next();
        if (nStr == null) return;

        int n;
        try {
            n = Integer.parseInt(nStr);
        } catch (NumberFormatException e) {
            return;
        }

        int totalElements = n * n;
        Map<Integer, Integer> counts = new HashMap<>();

        for (int i = 0; i < totalElements; i++) {
            String token = scanner.next();
            if (token != null) {
                int val = Integer.parseInt(token);
                counts.merge(val, 1, Integer::sum);
            }
        }

        solve(n, counts);
    }

    private static void solve(int n, Map<Integer, Integer> counts) {
        int[][] matrix = new int[n][n];
        int mid = n / 2;

        if (n % 2 == 0) {
            solveEven(n, matrix, counts);
        } else {
            solveOdd(n, matrix, counts, mid);
        }
    }

    private static void solveEven(int n, int[][] matrix, Map<Integer, Integer> counts) {
        // Validation: All counts must be divisible by 4 for even n
        for (int count : counts.values()) {
            if (count % 4 != 0) {
                System.out.println("NO");
                return;
            }
        }

        int quadsNeeded = (n / 2) * (n / 2);
        int quadsFilled = 0;
        int r = 0, c = 0;
        int limit = n / 2;

        // Fill Quadrants
        // We iterate through the map. Since we modify counts, we need to handle leftovers.
        // We process each entry, filling as many 4-symmetric blocks as possible.
        for (Map.Entry<Integer, Integer> entry : counts.entrySet()) {
            int val = entry.getKey();
            int count = entry.getValue();

            while (count >= 4 && quadsFilled < quadsNeeded) {
                // Fill 4 symmetric positions
                matrix[r][c] = val;
                matrix[r][n - 1 - c] = val;
                matrix[n - 1 - r][c] = val;
                matrix[n - 1 - r][n - 1 - c] = val;

                count -= 4;
                quadsFilled++;

                // Advance coordinates
                c++;
                if (c == limit) {
                    c = 0;
                    r++;
                }
            }
            entry.setValue(count);
        }

        if (quadsFilled == quadsNeeded) {
            System.out.println("YES");
            printMatrix(matrix);
        } else {
            System.out.println("NO");
        }
    }

    private static void solveOdd(int n, int[][] matrix, Map<Integer, Integer> counts, int mid) {
        // 1. Find Center Element (must have odd count)
        int centerVal = -1;
        int oddCountNumbers = 0;

        for (Map.Entry<Integer, Integer> entry : counts.entrySet()) {
            if (entry.getValue() % 2 != 0) {
                oddCountNumbers++;
                centerVal = entry.getKey();
            }
        }

        if (oddCountNumbers != 1) {
            System.out.println("NO");
            return;
        }

        // Place Center
        matrix[mid][mid] = centerVal;
        counts.put(centerVal, counts.get(centerVal) - 1);

        // 2. Fill Quadrants
        int quadsNeeded = mid * mid;
        int quadsFilled = 0;
        int r = 0, c = 0;
        int limit = mid;

        for (Map.Entry<Integer, Integer> entry : counts.entrySet()) {
            int val = entry.getKey();
            int count = entry.getValue();

            while (count >= 4 && quadsFilled < quadsNeeded) {
                matrix[r][c] = val;
                matrix[r][n - 1 - c] = val;
                matrix[n - 1 - r][c] = val;
                matrix[n - 1 - r][n - 1 - c] = val;

                count -= 4;
                quadsFilled++;

                c++;
                if (c == limit) {
                    c = 0;
                    r++;
                }
            }
            entry.setValue(count);
        }

        if (quadsFilled != quadsNeeded) {
            System.out.println("NO");
            return;
        }

        // 3. Fill Axes (Middle Row and Middle Column)
        // Middle Row: indices (mid, 0) to (mid, mid-1) -> mid slots
        // Middle Col: indices (0, mid) to (mid-1, mid) -> mid slots
        // Total 2 * mid slots. Each slot consumes 2 numbers.
        int axisPairsNeeded = 2 * mid;
        int axisPairsFilled = 0;

        // Coordinates for Row mid
        int rAxis = mid;
        int cAxis = 0;

        // We iterate map again to fill axes with remaining counts
        for (Map.Entry<Integer, Integer> entry : counts.entrySet()) {
            int val = entry.getKey();
            int count = entry.getValue();

            // Fill Middle Row slots
            while (count >= 2 && axisPairsFilled < mid) {
                matrix[rAxis][cAxis] = val;
                matrix[rAxis][n - 1 - cAxis] = val;

                count -= 2;
                axisPairsFilled++;
                cAxis++;
            }
            entry.setValue(count);

            // Fill Middle Column slots
            while (count >= 2 && axisPairsFilled < axisPairsNeeded) {
                // Calculate row index for column filling
                // We have filled 'mid' pairs in the row.
                // Current pair index is 'axisPairsFilled'.
                // Offset for column filling is 'axisPairsFilled - mid'.
                int rCol = axisPairsFilled - mid;

                matrix[rCol][mid] = val;
                matrix[n - 1 - rCol][mid] = val;

                count -= 2;
                axisPairsFilled++;
            }
            entry.setValue(count);
        }

        if (axisPairsFilled != axisPairsNeeded) {
            System.out.println("NO");
            return;
        }

        // 4. Final Validation
        // Check if all counts are consumed
        boolean allConsumed = true;
        for (int count : counts.values()) {
            if (count != 0) {
                allConsumed = false;
                break;
            }
        }

        if (allConsumed) {
            System.out.println("YES");
            printMatrix(matrix);
        } else {
            System.out.println("NO");
        }
    }

    private static void printMatrix(int[][] matrix) {
        StringBuilder sb = new StringBuilder();
        int n = matrix.length;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                sb.append(matrix[i][j]);
                if (j < n - 1) {
                    sb.append(" ");
                }
            }
            sb.append("\n");
        }
        System.out.print(sb);
    }

    static class FastScanner {
        BufferedReader br;
        StringTokenizer st;

        public FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    e.printStackTrace();
                    return null;
                }
            }
            return st.nextToken();
        }
    }
}

import java.io.*;
import java.util.StringTokenizer;

public class CF1118C {
    // Constants to eliminate magic numbers
    private static final int MAX_VALUE = 1000;
    private static final int MAX_N = 25;

    public static void main(String[] args) {
        // Fast I/O using BufferedReader and StringTokenizer
        FastReader reader = new FastReader();
        PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out));

        try {
            int n = reader.nextInt();
            int[] frequencyCounts = new int[MAX_VALUE + 1];

            // Read input and populate frequency map
            for (int i = 0; i < n * n; i++) {
                int value = reader.nextInt();
                if (value >= 1 && value <= MAX_VALUE) {
                    frequencyCounts[value]++;
                }
            }

            int[][] grid = new int[n][n];
            boolean possible = fillGrid(grid, frequencyCounts, n);

            if (!possible) {
                out.println("NO");
            } else {
                out.println("YES");
                printGrid(out, grid, n);
            }
        } finally {
            out.flush();
            reader.close();
        }
    }

    /**
     * Fills the grid with symmetric patterns based on available frequencies.
     * Returns false if the grid cannot be completely filled.
     */
    private static boolean fillGrid(int[][] grid, int[] frequencyCounts, int n) {
        // 1. Fill the 2x2 quadrants
        for (int i = 0; i < n / 2; i++) {
            for (int j = 0; j < n / 2; j++) {
                if (!placeSymmetric(grid, frequencyCounts, n, 4,
                        i * n + j,
                        i * n + (n - 1 - j),
                        (n - 1 - i) * n + j,
                        (n - 1 - i) * n + (n - 1 - j))) {
                    return false;
                }
            }
        }

        // 2. Handle odd dimension center cross and middle point
        if (n % 2 != 0) {
            int mid = n / 2;

            // Middle row (left half)
            for (int j = 0; j < mid; j++) {
                if (!placeSymmetric(grid, frequencyCounts, n, 2,
                        mid * n + j,
                        mid * n + (n - 1 - j))) {
                    return false;
                }
            }

            // Middle column (upper half)
            for (int i = 0; i < mid; i++) {
                if (!placeSymmetric(grid, frequencyCounts, n, 2,
                        i * n + mid,
                        (n - 1 - i) * n + mid)) {
                    return false;
                }
            }

            // Center element
            if (!placeSymmetric(grid, frequencyCounts, n, 1, mid * n + mid)) {
                return false;
            }
        }

        // 3. Validation: ensure no empty cells remain
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 0) {
                    return false;
                }
            }
        }

        return true;
    }

    /**
     * Finds a number with sufficient frequency and places it at the specified symmetric positions.
     * Uses flattened indices for cleaner coordinate handling.
     */
    private static boolean placeSymmetric(int[][] grid, int[] frequencyCounts, int n, int count, int... flatIndices) {
        for (int value = 1; value <= MAX_VALUE; value++) {
            if (frequencyCounts[value] >= count) {
                for (int idx : flatIndices) {
                    grid[idx / n][idx % n] = value;
                }
                frequencyCounts[value] -= count;
                return true;
            }
        }
        return false;
    }

    /**
     * Prints the completed grid to the output stream.
     */
    private static void printGrid(PrintWriter out, int[][] grid, int n) {
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                out.print(grid[i][j]);
                out.print(j == n - 1 ? "" : " ");
            }
            out.println();
        }
    }

    /**
     * Fast I/O helper class for competitive programming.
     */
    static class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            String s = next();
            return s == null ? 0 : Integer.parseInt(s);
        }

        void close() {
            try {
                br.close();
            } catch (IOException e) {
                throw new RuntimeException(e);
            }
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

/**
 * Solves the concentric symmetric matrix construction problem.
 * Reads an integer n and an array of n integers, then attempts to fill
 * an n x n matrix such that numbers appear in symmetric quadrants.
 */
public class ConcentricMatrixSolver {

    public static void main(String[] args) {
        // Try-with-resources ensures proper cleanup of I/O streams
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
             PrintWriter pw = new PrintWriter(System.out)) {
            new ConcentricMatrixSolver().solve(br, pw);
        } catch (IOException e) {
            throw new RuntimeException("Failed to read input", e);
        }
    }

    void solve(BufferedReader br, PrintWriter pw) {
        FastScanner scanner = new FastScanner(br);
        int n = scanner.nextInt();
        int[] arr = scanner.nextIntArray(n);

        // Dynamically size frequency array based on actual input range
        int maxVal = 0;
        for (int val : arr) {
            maxVal = Math.max(maxVal, val);
        }
        int[] counts = new int[maxVal + 1];
        for (int val : arr) {
            counts[val]++;
        }

        int[][] matrix = new int[n][n];

        // Build outer concentric rings
        if (!buildQuadrants(n, matrix, counts, pw)) {
            return;
        }

        // Handle odd dimensions: middle cross and center
        if (n % 2 == 1) {
            if (!buildMiddleCross(n, matrix, counts, pw)) {
                return;
            }
            if (!placeCenter(n, matrix, counts, pw)) {
                return;
            }
        }

        // All positions filled successfully
        pw.println("YES");
        printMatrix(pw, matrix);
    }

    private boolean buildQuadrants(int n, int[][] matrix, int[] counts, PrintWriter pw) {
        for (int i = 0; i < n / 2; i++) {
            for (int k = 0; k < n / 2; k++) {
                if (!assignQuad(i, k, n, matrix, counts)) {
                    pw.println("NO");
                    return false;
                }
            }
        }
        return true;
    }

    private boolean assignQuad(int i, int k, int n, int[][] matrix, int[] counts) {
        for (int val = 0; val < counts.length; val++) {
            if (counts[val] >= 4) {
                counts[val] -= 4;
                matrix[i][k] = val;
                matrix[n - i - 1][k] = val;
                matrix[i][n - k - 1] = val;
                matrix[n - i - 1][n - k - 1] = val;
                return true;
            }
        }
        return false;
    }

    private boolean buildMiddleCross(int n, int[][] matrix, int[] counts, PrintWriter pw) {
        int mid = n / 2;

        // Assign pairs to the middle column
        for (int i = 0; i < n / 2; i++) {
            if (!assignPair(i, mid, n - i - 1, mid, matrix, counts)) {
                pw.println("NO");
                return false;
            }
        }

        // Assign pairs to the middle row
        for (int i = 0; i < n / 2; i++) {
            if (!assignPair(mid, i, mid, n - i - 1, matrix, counts)) {
                pw.println("NO");
                return false;
            }
        }
        return true;
    }

    private boolean assignPair(int r1, int c1, int r2, int c2, int[][] matrix, int[] counts) {
        for (int val = 0; val < counts.length; val++) {
            if (counts[val] >= 2) {
                counts[val] -= 2;
                matrix[r1][c1] = val;
                matrix[r2][c2] = val;
                return true;
            }
        }
        return false;
    }

    private boolean placeCenter(int n, int[][] matrix, int[] counts, PrintWriter pw) {
        int mid = n / 2;
        for (int val = 0; val < counts.length; val++) {
            if (counts[val] > 0) {
                matrix[mid][mid] = val;
                return true;
            }
        }
        pw.println("NO");
        return false;
    }

    private void printMatrix(PrintWriter pw, int[][] matrix) {
        for (int[] row : matrix) {
            for (int val : row) {
                pw.print(val).append(' ');
            }
            pw.println();
        }
    }

    /**
     * Lightweight scanner for fast and robust whitespace-delimited input reading.
     */
    private static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner(BufferedReader br) {
            this.br = br;
        }

        String next() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) return null;
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

        int nextInt() throws IOException {
            String token = next();
            if (token == null) throw new IOException("Unexpected end of input");
            return Integer.parseInt(token);
        }

        int[] nextIntArray(int n) throws IOException {
            int[] arr = new int[n];
            for (int i = 0; i < n; i++) {
                arr[i] = nextInt();
            }
            return arr;
        }
    }
}

import java.io.InputStream;
import java.io.IOException;
import java.io.PrintWriter;
import java.util.InputMismatchException;

public class Main {
    public static void main(String[] args) {
        InputReader in = new InputReader(System.in);
        PrintWriter out = new PrintWriter(System.out);
        new CPalindromicMatrix().solve(in, out);
        out.flush();
        out.close();
    }

    static class CPalindromicMatrix {
        public void solve(InputReader in, PrintWriter out) {
            int n = in.nextInt();
            int[] a = in.nextIntArray(n * n);
            solve(n, a, out);
        }

        private void solve(int n, int[] a, PrintWriter out) {
            int[] counts = new int[1001];
            for (int val : a) {
                counts[val]++;
            }

            if (!isValid(n, counts)) {
                out.println("NO");
                return;
            }

            out.println("YES");
            buildAndPrintMatrix(n, counts, out);
        }

        /**
         * Validates if the given frequency counts can form a palindromic matrix.
         * - Even n: All counts must be divisible by 4.
         * - Odd n: Exactly one count can have remainder 1 (center), 
         *          others can be 0 or 2 (pairs), and we must have enough groups of 4 for quadrants.
         */
        private boolean isValid(int n, int[] counts) {
            if (n % 2 == 0) {
                for (int c : counts) {
                    if (c % 4 != 0) return false;
                }
            } else {
                int oddRemainders = 0;
                int maxQuads = 0;
                for (int c : counts) {
                    int rem = c % 4;
                    if (rem == 1) {
                        oddRemainders++;
                    } else if (rem != 0 && rem != 2) {
                        return false; // Remainder 3 is invalid
                    }
                    maxQuads += c / 4;
                }
                if (oddRemainders != 1 || maxQuads < (n * n) / 4) {
                    return false;
                }
            }
            return true;
        }

        private void buildAndPrintMatrix(int n, int[] counts, PrintWriter out) {
            int mid = n / 2;
            int[] quads = new int[mid * mid];
            int[] pairs = new int[2 * mid];
            int qIdx = 0, pIdx = 0;
            int center = -1;

            // Extract elements into structured buckets
            for (int k = 1; k <= 1000; k++) {
                while (counts[k] >= 4) {
                    quads[qIdx++] = k;
                    counts[k] -= 4;
                }
                while (counts[k] >= 2) {
                    pairs[pIdx++] = k;
                    counts[k] -= 2;
                }
                if (counts[k] == 1) {
                    center = k;
                }
            }

            // Fill the top-left quadrant
            int[][] quadrant = new int[mid][mid];
            int qPtr = 0;
            for (int i = 0; i < mid; i++) {
                for (int j = 0; j < mid; j++) {
                    quadrant[i][j] = quads[qPtr++];
                }
            }

            // Fill middle row left half and middle column top half
            int[] midRowLeft = new int[mid];
            int[] midColTop = new int[mid];
            int pPtr = 0;
            for (int i = 0; i < mid; i++) midRowLeft[i] = pairs[pPtr++];
            for (int i = 0; i < mid; i++) midColTop[i] = pairs[pPtr++];

            // Print the fully symmetric matrix
            for (int i = 0; i < n; i++) {
                if (i < mid) {
                    // Top half
                    for (int j = 0; j < mid; j++) out.print(quadrant[i][j] + " ");
                    out.print(midColTop[i] + " ");
                    for (int j = mid - 1; j >= 0; j--) out.print(quadrant[i][j] + " ");
                } else if (i == mid) {
                    // Middle row
                    for (int j = 0; j < mid; j++) out.print(midRowLeft[j] + " ");
                    out.print(center + " ");
                    for (int j = mid - 1; j >= 0; j--) out.print(midRowLeft[j] + " ");
                } else {
                    // Bottom half (mirror of top half)
                    int row = n - 1 - i;
                    for (int j = 0; j < mid; j++) out.print(quadrant[row][j] + " ");
                    out.print(midColTop[row] + " ");
                    for (int j = mid - 1; j >= 0; j--) out.print(quadrant[row][j] + " ");
                }
                out.println();
            }
        }
    }

    /**
     * Fast input reader for competitive programming.
     * Wraps an InputStream instead of incorrectly extending it.
     */
    static class InputReader {
        private final InputStream stream;
        private final byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        public int read() {
            if (numChars == -1) {
                throw new InputMismatchException();
            }
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0) {
                    return -1;
                }
            }
            return buf[curChar++];
        }

        public int nextInt() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                res *= 10;
                res += c - '0';
                c = read();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public int[] nextIntArray(int length) {
            int[] arr = new int[length];
            for (int i = 0; i < length; i++) {
                arr[i] = nextInt();
            }
            return arr;
        }

        private static boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Generates a symmetric matrix where each number appears in symmetric positions.
 * For an n x n matrix, values are assigned in groups of 4 (quadrants), 
 * 2 (middle row/column pairs), or 1 (center element) if n is odd.
 */
public class SymmetricMatrixGenerator {

    private static final int MAX_VALUE = 1000;
    private static final int COUNT_ARRAY_SIZE = MAX_VALUE + 1;

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out));
        try {
            solve(scanner, out);
        } finally {
            out.flush();
            out.close();
        }
    }

    /**
     * Orchestrates input reading, frequency counting, matrix construction, and output.
     */
    private static void solve(FastScanner scanner, PrintWriter out) {
        String nToken = scanner.next();
        if (nToken == null) return;

        int n = Integer.parseInt(nToken);
        int totalCells = n * n;

        // Count frequencies of all input numbers
        int[] frequency = new int[COUNT_ARRAY_SIZE];
        for (int i = 0; i < totalCells; i++) {
            String token = scanner.next();
            if (token == null) break;
            int val = Integer.parseInt(token);
            if (val >= 0 && val <= MAX_VALUE) {
                frequency[val]++;
            } else {
                out.println("NO");
                return;
            }
        }

        int[][] matrix = new int[n][n];
        int[] currentK = {0}; // Wrapper to allow mutation inside helper method

        // 1. Fill the four quadrants (each position requires 4 identical values)
        for (int i = 0; i < n / 2; i++) {
            int iBottom = n - 1 - i;
            for (int j = 0; j < n / 2; j++) {
                int jRight = n - 1 - j;
                int val = findAndDecrement(frequency, currentK, 4);
                if (val == -1) {
                    out.println("NO");
                    return;
                }
                matrix[i][j] = matrix[i][jRight] = matrix[iBottom][j] = matrix[iBottom][jRight] = val;
            }
        }

        // 2. Handle odd dimension: middle row, middle column, and center
        if (n % 2 == 1) {
            int mid = n / 2;

            // Middle row pairs (requires 2 identical values per pair)
            currentK[0] = 0; // Reset search pointer as in original logic
            for (int j = 0; j < mid; j++) {
                int jRight = n - 1 - j;
                int val = findAndDecrement(frequency, currentK, 2);
                if (val == -1) {
                    out.println("NO");
                    return;
                }
                matrix[mid][j] = matrix[mid][jRight] = val;
            }

            // Middle column pairs (requires 2 identical values per pair)
            currentK[0] = 0; // Reset search pointer as in original logic
            for (int i = 0; i < mid; i++) {
                int iBottom = n - 1 - i;
                int val = findAndDecrement(frequency, currentK, 2);
                if (val == -1) {
                    out.println("NO");
                    return;
                }
                matrix[i][mid] = matrix[iBottom][mid] = val;
            }

            // Center element (requires 1 value)
            while (currentK[0] <= MAX_VALUE && frequency[currentK[0]] < 1) {
                currentK[0]++;
            }
            if (currentK[0] > MAX_VALUE) {
                out.println("NO");
                return;
            }
            matrix[mid][mid] = currentK[0];
        }

        // Output success and the constructed matrix
        out.println("YES");
        printMatrix(out, matrix);
    }

    /**
     * Finds the smallest number >= currentK that has at least minCount remaining.
     * Decrements its frequency by minCount and returns the number.
     * Returns -1 if no such number exists.
     */
    private static int findAndDecrement(int[] frequency, int[] currentK, int minCount) {
        while (currentK[0] <= MAX_VALUE && frequency[currentK[0]] < minCount) {
            currentK[0]++;
        }
        if (currentK[0] > MAX_VALUE) {
            return -1;
        }
        frequency[currentK[0]] -= minCount;
        return currentK[0];
    }

    /**
     * Prints the matrix rows to the provided PrintWriter.
     */
    private static void printMatrix(PrintWriter out, int[][] matrix) {
        for (int[] row : matrix) {
            for (int val : row) {
                out.print(val).append(' ');
            }
            out.println();
        }
    }

    /**
     * Lightweight fast I/O utility for competitive programming contexts.
     * Replaces custom byte-buffer readers with standard, maintainable Java I/O.
     */
    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        public String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input", e);
                }
            }
            return st.nextToken();
        }
    }
}

import java.io.*;
import java.util.*;

public class CF1118C {
    private static final int MAX_VALUE = 1000;

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter out = new PrintWriter(System.out);
        StringTokenizer st = new StringTokenizer("");

        // Helper to safely read tokens across multiple lines
        if (!readToken(br, st)) {
            out.flush();
            return;
        }
        int n = Integer.parseInt(st.nextToken());

        int[] freqCounts = new int[MAX_VALUE + 1];
        for (int i = 0; i < n * n; i++) {
            readToken(br, st);
            int val = Integer.parseInt(st.nextToken());
            freqCounts[val]++;
        }

        // Validate parity constraints and find center value if needed
        int centerValue = findCenterValue(freqCounts);
        boolean isOddN = (n % 2 != 0);

        if ((isOddN && centerValue == -1) || (!isOddN && centerValue != -1)) {
            out.println("NO");
            out.flush();
            return;
        }

        int[][] grid = new int[n][n];
        int half = n / 2;
        int searchIdx = 1; // Optimized pointer to avoid rescanning from 1

        // Place center value for odd-sized grids
        if (isOddN) {
            grid[half][half] = centerValue;
            freqCounts[centerValue]--;
        }

        // Fill middle column (excluding center) for odd n
        if (isOddN) {
            for (int i = 0; i < half; i++) {
                int val = findNextValue(freqCounts, 2, searchIdx, true);
                if (val == -1) { out.println("NO"); out.flush(); return; }
                grid[i][half] = grid[n - 1 - i][half] = val;
                freqCounts[val] -= 2;
                searchIdx = val + 1;
            }
            // Fill middle row (excluding center) for odd n
            for (int j = 0; j < half; j++) {
                int val = findNextValue(freqCounts, 2, searchIdx, true);
                if (val == -1) { out.println("NO"); out.flush(); return; }
                grid[half][j] = grid[half][n - 1 - j] = val;
                freqCounts[val] -= 2;
                searchIdx = val + 1;
            }
        }

        // Fill the four quadrants (4 symmetric cells at a time)
        for (int i = 0; i < half; i++) {
            for (int j = 0; j < half; j++) {
                int val = findNextValue(freqCounts, 4, searchIdx, false);
                if (val == -1) { out.println("NO"); out.flush(); return; }
                grid[i][j] = grid[n - 1 - i][j] = grid[i][n - 1 - j] = grid[n - 1 - i][n - 1 - j] = val;
                freqCounts[val] -= 4;
                searchIdx = val + 1;
            }
        }

        // Output results
        out.println("YES");
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                out.print(grid[i][j] + (j == n - 1 ? "" : " "));
            }
            out.println();
        }
        out.flush();
    }

    /**
     * Finds the unique value with an odd frequency.
     * Returns -1 if none or more than one exists.
     */
    private static int findCenterValue(int[] freqCounts) {
        int center = -1;
        for (int val = 1; val <= MAX_VALUE; val++) {
            if (freqCounts[val] % 2 != 0) {
                if (center != -1) return -1; // More than one odd frequency
                center = val;
            }
        }
        return center;
    }

    /**
     * Finds the next available number with at least `required` occurrences.
     * If prioritizeMod4Equals2 is true, prefers numbers where freq % 4 == 2
     * to prevent leftover remainders that can't form groups of 4.
     */
    private static int findNextValue(int[] freqCounts, int required, int startIdx, boolean prioritizeMod4Equals2) {
        // First pass: respect priority if requested
        for (int i = startIdx; i < freqCounts.length; i++) {
            if (freqCounts[i] >= required) {
                if (!prioritizeMod4Equals2 || freqCounts[i] % 4 == 2) {
                    return i;
                }
            }
        }
        // Fallback: if prioritization yielded nothing, accept any valid number
        if (prioritizeMod4Equals2) {
            for (int i = startIdx; i < freqCounts.length; i++) {
                if (freqCounts[i] >= required) {
                    return i;
                }
            }
        }
        return -1;
    }

    /**
     * Robust token reader that handles line breaks gracefully.
     */
    private static boolean readToken(BufferedReader br, StringTokenizer st) throws IOException {
        while (!st.hasMoreTokens()) {
            String line = br.readLine();
            if (line == null) return false;
            st = new StringTokenizer(line);
        }
        return true;
    }
}

import java.io.*;
import java.util.*;
import java.util.stream.IntStream;

public class SymmetricMatrixFiller {

    private static final int MAX_VALUE = 1000;

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner(System.in);
        try (PrintWriter out = new PrintWriter(System.out)) {
            new Solver().solve(scanner, out);
        }
        scanner.close();
    }

    static class Solver {
        private int gridSize;
        private int[][] grid;
        private int[] valueFrequencies;
        private Queue<int[][]> groupsOfFour;
        private Queue<int[][]> groupsOfTwo;
        private Queue<int[][]> groupsOfOne;

        void solve(FastScanner s, PrintWriter out) {
            gridSize = s.nextInt();
            int totalCells = gridSize * gridSize;
            int[] values = s.nextIntArray(totalCells);

            valueFrequencies = new int[MAX_VALUE + 1];
            for (int val : values) {
                if (val >= 1 && val <= MAX_VALUE) {
                    valueFrequencies[val]++;
                }
            }

            PriorityQueue<Integer> valueQueue = new PriorityQueue<>(
                (a, b) -> Integer.compare(valueFrequencies[b], valueFrequencies[a])
            );
            IntStream.range(1, MAX_VALUE + 1).forEach(valueQueue::add);

            initializeGroupQueues(gridSize);

            if (fillGrid(valueQueue)) {
                out.println("YES");
                printGrid(out);
            } else {
                out.println("NO");
            }
        }

        private void initializeGroupQueues(int n) {
            groupsOfFour = new ArrayDeque<>();
            groupsOfTwo = new ArrayDeque<>();
            groupsOfOne = new ArrayDeque<>();

            int half = n / 2;
            for (int i = 0, ii = n - 1; i < half; i++, ii--) {
                for (int j = 0, jj = n - 1; j < half; j++, jj--) {
                    groupsOfFour.add(new int[][]{{i, j}, {ii, j}, {i, jj}, {ii, jj}});
                }
            }

            if (n % 2 == 1) {
                int mid = n / 2;
                for (int i = 0, ii = n - 1; i < mid; i++, ii--) {
                    groupsOfTwo.add(new int[][]{{i, mid}, {ii, mid}});
                    groupsOfTwo.add(new int[][]{{mid, i}, {mid, ii}});
                }
                groupsOfOne.add(new int[][]{{mid, mid}});
            }
        }

        private boolean fillGrid(PriorityQueue<Integer> valueQueue) {
            grid = new int[gridSize][gridSize];

            while (!valueQueue.isEmpty()) {
                int currentValue = valueQueue.poll();
                int currentFreq = valueFrequencies[currentValue];

                if (currentFreq == 0) {
                    break;
                }

                boolean placed = false;
                if (currentFreq >= 4 && !groupsOfFour.isEmpty()) {
                    placeValue(groupsOfFour.poll(), currentValue);
                    valueFrequencies[currentValue] -= 4;
                    placed = true;
                } else if (currentFreq >= 2 && !groupsOfTwo.isEmpty()) {
                    placeValue(groupsOfTwo.poll(), currentValue);
                    valueFrequencies[currentValue] -= 2;
                    placed = true;
                } else if (currentFreq >= 1 && !groupsOfOne.isEmpty()) {
                    placeValue(groupsOfOne.poll(), currentValue);
                    valueFrequencies[currentValue] -= 1;
                    placed = true;
                }

                if (placed) {
                    valueQueue.add(currentValue);
                } else {
                    return false;
                }
            }
            return true;
        }

        private void placeValue(int[][] coordinates, int value) {
            for (int[] coord : coordinates) {
                grid[coord[0]][coord[1]] = value;
            }
        }

        private void printGrid(PrintWriter out) {
            for (int[] row : grid) {
                for (int val : row) {
                    out.print(val + " ");
                }
                out.println();
            }
        }
    }

    static class FastScanner {
        private final InputStream stream;
        private final byte[] buf = new byte[1 << 22];
        private int curChar;
        private int numChars;

        public FastScanner(InputStream stream) {
            this.stream = stream;
        }

        public FastScanner(File f) throws FileNotFoundException {
            this(new FileInputStream(f));
        }

        public FastScanner(String s) {
            this.stream = new ByteArrayInputStream(s.getBytes(StandardCharsets.UTF_8));
        }

        public void close() {
            try {
                stream.close();
            } catch (IOException e) {
                // Ignore on close
            }
        }

        int read() {
            if (numChars == -1) {
                throw new InputMismatchException();
            }
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0) {
                    return -1;
                }
            }
            return buf[curChar++];
        }

        boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        boolean isEndline(int c) {
            return c == '\n' || c == '\r' || c == -1;
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }

        public double nextDouble() {
            return Double.parseDouble(next());
        }

        public String next() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            StringBuilder res = new StringBuilder();
            do {
                res.appendCodePoint(c);
                c = read();
            } while (!isSpaceChar(c));
            return res.toString();
        }

        public String nextLine() {
            int c = read();
            while (isEndline(c)) {
                c = read();
            }
            StringBuilder res = new StringBuilder();
            do {
                res.appendCodePoint(c);
                c = read();
            } while (!isEndline(c));
            return res.toString();
        }

        public int[] nextIntArray(int N) {
            int[] ret = new int[N];
            for (int i = 0; i < N; i++) {
                ret[i] = this.nextInt();
            }
            return ret;
        }

        public int[][] next2DIntArray(int N, int M) {
            int[][] ret = new int[N][];
            for (int i = 0; i < N; i++) {
                ret[i] = this.nextIntArray(M);
            }
            return ret;
        }

        public long[] nextLongArray(int N) {
            long[] ret = new long[N];
            for (int i = 0; i < N; i++) {
                ret[i] = this.nextLong();
            }
            return ret;
        }

        public long[][] next2DLongArray(int N, int M) {
            long[][] ret = new long[N][];
            for (int i = 0; i < N; i++) {
                ret[i] = nextLongArray(M);
            }
            return ret;
        }

        public double[] nextDoubleArray(int N) {
            double[] ret = new double[N];
            for (int i = 0; i < N; i++) {
                ret[i] = this.nextDouble();
            }
            return ret;
        }

        public double[][] next2DDoubleArray(int N, int M) {
            double[][] ret = new double[N][];
            for (int i = 0; i < N; i++) {
                ret[i] = this.nextDoubleArray(M);
            }
            return ret;
        }
    }
}

import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        OutputWriter out = new OutputWriter(outputStream);
        PalindromicMatrixSolver solver = new PalindromicMatrixSolver();
        solver.solve(in, out);
        out.close();
    }

    /**
     * Solves the palindromic matrix construction problem.
     * Groups cells by their symmetry requirements and greedily assigns values.
     */
    static class PalindromicMatrixSolver {
        private static final int MAX_VALUE = 1000;

        public void solve(InputReader in, OutputWriter out) {
            int n = in.readInt();
            int totalElements = n * n;
            int[] a = in.readIntArray(totalElements);

            int[] cnt = new int[MAX_VALUE + 1];
            for (int val : a) {
                if (val < 0 || val > MAX_VALUE) {
                    throw new IllegalArgumentException("Value out of bounds: " + val);
                }
                cnt[val]++;
            }

            List<Set<IntIntPair>> groups = generateSymmetryGroups(n);
            // Sort groups by size descending to ensure larger groups get values first
            groups.sort(Comparator.comparingInt(Set::size).reversed());

            int[][] ans = new int[n][n];
            for (Set<IntIntPair> group : groups) {
                boolean assigned = false;
                for (int val = 0; val <= MAX_VALUE; val++) {
                    if (cnt[val] >= group.size()) {
                        for (IntIntPair p : group) {
                            ans[p.first][p.second] = val;
                            cnt[val]--;
                        }
                        assigned = true;
                        break;
                    }
                }
                if (!assigned) {
                    out.println("NO");
                    return;
                }
            }

            out.println("YES");
            for (int[] row : ans) {
                out.printLine(row);
            }
        }

        /**
         * Generates sets of coordinates that must share the same value due to 
         * horizontal, vertical, and 180-degree rotational symmetry.
         */
        private List<Set<IntIntPair>> generateSymmetryGroups(int n) {
            boolean[][] visited = new boolean[n][n];
            List<Set<IntIntPair>> groups = new ArrayList<>();
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < n; j++) {
                    if (!visited[i][j]) {
                        Set<IntIntPair> group = new HashSet<>();
                        int i1 = n - 1 - i;
                        int j1 = n - 1 - j;

                        group.add(new IntIntPair(i, j));
                        group.add(new IntIntPair(i, j1));
                        group.add(new IntIntPair(i1, j));
                        group.add(new IntIntPair(i1, j1));

                        groups.add(group);
                        visited[i][j] = visited[i][j1] = visited[i1][j] = visited[i1][j1] = true;
                    }
                }
            }
            return groups;
        }
    }

    /**
     * Fast input reader for competitive programming environments.
     */
    static class InputReader {
        private final InputStream stream;
        private final byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        public int[] readIntArray(int size) {
            int[] array = new int[size];
            for (int i = 0; i < size; i++) {
                array[i] = readInt();
            }
            return array;
        }

        public int read() {
            if (numChars == -1) {
                throw new InputMismatchException("End of stream reached unexpectedly");
            }
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException("IO Error: " + e.getMessage());
                }
                if (numChars <= 0) {
                    return -1;
                }
            }
            return buf[curChar++];
        }

        public int readInt() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9') {
                    throw new InputMismatchException("Invalid integer character");
                }
                res *= 10;
                res += c - '0';
                c = read();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }
    }

    /**
     * Fast output writer with buffered printing capabilities.
     */
    static class OutputWriter {
        private final PrintWriter writer;

        public OutputWriter(OutputStream outputStream) {
            writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(outputStream)));
        }

        public OutputWriter(Writer writer) {
            this.writer = new PrintWriter(writer);
        }

        public void print(Object... objects) {
            for (int i = 0; i < objects.length; i++) {
                if (i != 0) {
                    writer.print(' ');
                }
                writer.print(objects[i]);
            }
        }

        public void print(int[] array) {
            for (int i = 0; i < array.length; i++) {
                if (i != 0) {
                    writer.print(' ');
                }
                writer.print(array[i]);
            }
        }

        public void printLine(int[] array) {
            print(array);
            writer.println();
        }

        public void printLine(Object... objects) {
            print(objects);
            writer.println();
        }

        public void println(String s) {
            writer.println(s);
        }

        public void close() {
            writer.close();
        }
    }

    /**
     * Immutable pair of integers used for coordinate tracking.
     */
    static final class IntIntPair {
        public final int first;
        public final int second;

        public IntIntPair(int first, int second) {
            this.first = first;
            this.second = second;
        }

        @Override
        public boolean equals(Object o) {
            if (this == o) return true;
            if (!(o instanceof IntIntPair)) return false;
            IntIntPair pair = (IntIntPair) o;
            return first == pair.first && second == pair.second;
        }

        @Override
        public int hashCode() {
            int result = first;
            result = 31 * result + second;
            return result;
        }

        @Override
        public String toString() {
            return "(" + first + "," + second + ")";
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.OutputStream;
import java.io.PrintWriter;
import java.util.StringTokenizer;

public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        ReaderFastIO in = new ReaderFastIO(inputStream);
        PrintWriter out = new PrintWriter(outputStream);

        PalindromicMatrixSolver solver = new PalindromicMatrixSolver();
        solver.solve(in.nextInt(), in, out);

        out.flush(); // Ensure all buffered output is written to the console
        out.close();
    }
}

/**
 * Solves the palindromic matrix construction problem.
 * Separated from I/O to improve testability and separation of concerns.
 */
class PalindromicMatrixSolver {

    public void solve(int n, ReaderFastIO in, PrintWriter out) {
        int totalElements = n * n;
        int[] inputArray = new int[totalElements];
        int maxVal = 0;

        // Read input and determine the maximum value dynamically
        for (int i = 0; i < totalElements; i++) {
            inputArray[i] = in.nextInt();
            if (inputArray[i] > maxVal) {
                maxVal = inputArray[i];
            }
        }

        // Frequency array to track available counts for each number
        int[] frequency = new int[maxVal + 1];
        for (int value : inputArray) {
            frequency[value]++;
        }

        int[][] matrix = new int[n][n];
        int topRow = 0;
        int bottomRow = n - 1;
        int leftCol = 0;
        int rightCol = n - 1;
        int currentValue = 1;

        // Fill outer layers from the boundary inward
        while (topRow < bottomRow) {
            while (currentValue <= maxVal && frequency[currentValue] < 4) {
                currentValue++;
            }
            if (currentValue > maxVal) {
                out.println("NO");
                return;
            }

            matrix[topRow][leftCol] = currentValue;
            matrix[topRow][rightCol] = currentValue;
            matrix[bottomRow][leftCol] = currentValue;
            matrix[bottomRow][rightCol] = currentValue;
            frequency[currentValue] -= 4;

            leftCol++;
            rightCol--;
            if (leftCol > rightCol) {
                leftCol = 0;
                rightCol = n - 1;
                topRow++;
                bottomRow--;
            }
        }

        if (n % 2 == 0) {
            out.println("YES");
            printMatrix(matrix, out);
        } else {
            solveOddCase(n, matrix, frequency, maxVal, out);
        }
    }

    private void solveOddCase(int n, int[][] matrix, int[] frequency, int maxVal, PrintWriter out) {
        int mid = n / 2;
        int currentValue = 1;

        // Fill middle row pairs
        int leftCol = 0;
        int rightCol = n - 1;
        while (leftCol < rightCol) {
            while (currentValue <= maxVal && frequency[currentValue] < 2) {
                currentValue++;
            }
            if (currentValue > maxVal) {
                out.println("NO");
                return;
            }
            matrix[mid][leftCol] = currentValue;
            matrix[mid][rightCol] = currentValue;
            frequency[currentValue] -= 2;
            leftCol++;
            rightCol--;
        }

        // Fill middle column pairs
        int topRow = 0;
        int bottomRow = n - 1;
        currentValue = 1;
        while (topRow < bottomRow) {
            while (currentValue <= maxVal && frequency[currentValue] < 2) {
                currentValue++;
            }
            if (currentValue > maxVal) {
                out.println("NO");
                return;
            }
            matrix[topRow][mid] = currentValue;
            matrix[bottomRow][mid] = currentValue;
            frequency[currentValue] -= 2;
            topRow++;
            bottomRow--;
        }

        // Fill center element
        while (currentValue <= maxVal && frequency[currentValue] < 1) {
            currentValue++;
        }
        if (currentValue <= maxVal) {
            matrix[mid][mid] = currentValue;
            frequency[currentValue]--;
        } else {
            out.println("NO");
            return;
        }

        out.println("YES");
        printMatrix(matrix, out);
    }

    private void printMatrix(int[][] matrix, PrintWriter out) {
        for (int[] row : matrix) {
            for (int value : row) {
                out.print(value + " ");
            }
            out.println();
        }
    }
}

/**
 * Fast I/O utility for competitive programming and high-throughput input parsing.
 */
class ReaderFastIO {
    private final BufferedReader br;
    private StringTokenizer st;

    public ReaderFastIO() {
        this(System.in);
    }

    public ReaderFastIO(InputStream input) {
        br = new BufferedReader(new InputStreamReader(input));
    }

    public String next() {
        while (st == null || !st.hasMoreTokens()) {
            try {
                String line = br.readLine();
                if (line == null) {
                    return null;
                }
                st = new StringTokenizer(line);
            } catch (IOException e) {
                throw new RuntimeException("Error reading input stream", e);
            }
        }
        return st.nextToken();
    }

    public int nextInt() {
        String token = next();
        if (token == null) {
            throw new RuntimeException("Unexpected end of input");
        }
        return Integer.parseInt(token);
    }
}

import java.util.Scanner;

public class Main {
    // Constants extracted for clarity, testability, and maintainability
    private static final int MAX_VALUE = 1000;
    private static final int QUADRANT_SIZE = 4;
    private static final int AXIS_SIZE = 2;

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        if (!scanner.hasNextInt()) {
            return;
        }

        int n = scanner.nextInt();
        int[] values = new int[n * n];
        for (int i = 0; i < values.length; i++) {
            values[i] = scanner.nextInt();
        }

        int[][] grid;
        try {
            if (n == 1) {
                grid = new int[1][1];
                grid[0][0] = values[0];
            } else if (n % 2 != 0) {
                grid = buildOddGrid(n, values);
            } else {
                grid = buildEvenGrid(n, values);
            }
            printGrid(grid);
        } catch (IllegalArgumentException e) {
            System.out.println("NO");
        }
    }

    /**
     * Constructs the grid for odd-sized n.
     * Handles center placement, quadrant filling, and axis filling.
     */
    private static int[][] buildOddGrid(int n, int[] values) {
        int[][] grid = new int[n][n];
        int[] counts = new int[MAX_VALUE + 1];
        for (int val : values) {
            if (val < 0 || val > MAX_VALUE) {
                throw new IllegalArgumentException("Value out of bounds");
            }
            counts[val]++;
        }

        // 1. Place center element (must have an odd count)
        int oddCountValues = 0;
        for (int i = 1; i <= MAX_VALUE; i++) {
            if (counts[i] % 2 != 0) {
                grid[n / 2][n / 2] = i;
                counts[i]--;
                oddCountValues++;
            }
        }
        if (oddCountValues != 1) {
            throw new IllegalArgumentException("Invalid center configuration");
        }

        // 2. Fill quadrants symmetrically
        int[] pos = {0, 0}; // [row, col]
        for (int i = 1; i <= MAX_VALUE; i++) {
            while (counts[i] >= QUADRANT_SIZE && pos[0] < n / 2) {
                fillQuadrant(grid, n, i, pos);
                counts[i] -= QUADRANT_SIZE;
            }
            if (pos[0] == n / 2) {
                break;
            }
        }

        if (pos[0] != n / 2 || pos[1] != 0) {
            throw new IllegalArgumentException("Quadrants not fully filled");
        }

        // 3. Fill middle row and column
        int[] axisPos = {0, 0}; // [hori, vert]
        for (int i = 1; i <= MAX_VALUE; i++) {
            while (counts[i] > 0) {
                counts[i] -= AXIS_SIZE;
                if (axisPos[0] < n / 2) {
                    fillAxisRow(grid, n, i, axisPos[0]);
                    axisPos[0]++;
                } else {
                    fillAxisCol(grid, n, i, axisPos[1]);
                    axisPos[1]++;
                }
            }
        }

        return grid;
    }

    /**
     * Constructs the grid for even-sized n.
     * All values must appear in multiples of 4.
     */
    private static int[][] buildEvenGrid(int n, int[] values) {
        int[][] grid = new int[n][n];
        int[] counts = new int[MAX_VALUE + 1];
        for (int val : values) {
            if (val < 0 || val > MAX_VALUE) {
                throw new IllegalArgumentException("Value out of bounds");
            }
            counts[val]++;
        }

        int[] pos = {0, 0}; // [row, col]
        for (int i = 1; i <= MAX_VALUE; i++) {
            if (counts[i] % QUADRANT_SIZE != 0) {
                throw new IllegalArgumentException("Invalid count for even grid");
            }
            while (counts[i] > 0) {
                fillQuadrant(grid, n, i, pos);
                counts[i] -= QUADRANT_SIZE;
            }
        }

        return grid;
    }

    /**
     * Fills a 4-way symmetric quadrant position and updates the position tracker.
     */
    private static void fillQuadrant(int[][] grid, int n, int value, int[] pos) {
        int r = pos[0];
        int c = pos[1];
        grid[r][c] = value;
        grid[r][n - 1 - c] = value;
        grid[n - 1 - r][c] = value;
        grid[n - 1 - r][n - 1 - c] = value;

        pos[1]++;
        if (pos[1] == n / 2) {
            pos[0]++;
            pos[1] = 0;
        }
    }

    /**
     * Fills a symmetric pair in the middle row.
     */
    private static void fillAxisRow(int[][] grid, int n, int value, int index) {
        grid[n / 2][index] = value;
        grid[n / 2][n - 1 - index] = value;
    }

    /**
     * Fills a symmetric pair in the middle column.
     */
    private static void fillAxisCol(int[][] grid, int n, int value, int index) {
        grid[index][n / 2] = value;
        grid[n - 1 - index][n / 2] = value;
    }

    /**
     * Prints the resulting grid in the required format.
     */
    private static void printGrid(int[][] grid) {
        System.out.println("YES");
        for (int[] row : grid) {
            StringBuilder sb = new StringBuilder();
            for (int val : row) {
                sb.append(val).append(' ');
            }
            System.out.println(sb);
        }
    }
}

import java.io.*;
import java.util.*;

public class Codeforces {
    private static final int MAX_VALUE = 1000;

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out));
        try {
            solve(scanner, out);
        } finally {
            out.flush();
            out.close();
        }
    }

    private static void solve(FastScanner sc, PrintWriter out) {
        int n = sc.nextInt();
        int[] counts = new int[MAX_VALUE + 1];

        // Count frequencies of all input numbers
        for (int i = 0; i < n * n; i++) {
            counts[sc.nextInt()]++;
        }

        // Requirement 1: 2x2 blocks need numbers appearing at least 4 times
        int quadCount = (n / 2) * (n / 2);
        List<Integer> quadValues = collectValues(counts, 4, quadCount);
        if (quadValues == null) {
            out.println("NO");
            return;
        }

        List<Integer> lineValues = null;
        int centerValue = -1;

        // Requirement 2 & 3: Odd n needs middle row/col (2 times each) and center (1 time)
        if (n % 2 == 1) {
            int lineCount = (n / 2) * 2;
            lineValues = collectValues(counts, 2, lineCount);
            if (lineValues == null) {
                out.println("NO");
                return;
            }
            centerValue = collectSingleValue(counts);
            if (centerValue == -1) {
                out.println("NO");
                return;
            }
        }

        // Construct the grid
        int[][] grid = new int[n][n];
        int quadIdx = 0;
        for (int i = 0; i < n / 2; i++) {
            for (int j = 0; j < n / 2; j++) {
                int val = quadValues.get(quadIdx++);
                grid[i][j] = grid[n - 1 - i][j] = grid[i][n - 1 - j] = grid[n - 1 - i][n - 1 - j] = val;
            }
        }

        if (n % 2 == 1) {
            int lineIdx = 0;
            // Fill middle column (excluding center)
            for (int i = 0; i < n / 2; i++) {
                int val = lineValues.get(lineIdx++);
                grid[i][n / 2] = grid[n - 1 - i][n / 2] = val;
            }
            // Fill middle row (excluding center)
            for (int j = 0; j < n / 2; j++) {
                int val = lineValues.get(lineIdx++);
                grid[n / 2][j] = grid[n / 2][n - 1 - j] = val;
            }
            // Fill center
            grid[n / 2][n / 2] = centerValue;
        }

        // Output result
        out.println("YES");
        for (int[] row : grid) {
            for (int i = 0; i < n; i++) {
                out.print(row[i]);
                out.print(i == n - 1 ? "" : " ");
            }
            out.println();
        }
    }

    /**
     * Collects values that appear at least 'requiredPerValue' times.
     * Modifies the counts array to reflect consumed values.
     * Returns null if not enough values are available.
     */
    private static List<Integer> collectValues(int[] counts, int requiredPerValue, int needed) {
        List<Integer> result = new ArrayList<>(needed);
        for (int val = 1; val <= MAX_VALUE; val++) {
            while (counts[val] >= requiredPerValue && needed > 0) {
                result.add(val);
                counts[val] -= requiredPerValue;
                needed--;
            }
        }
        return needed == 0 ? result : null;
    }

    /**
     * Finds the first value with at least 1 remaining count.
     */
    private static int collectSingleValue(int[] counts) {
        for (int val = 1; val <= MAX_VALUE; val++) {
            if (counts[val] >= 1) {
                return val;
            }
        }
        return -1;
    }

    /**
     * Fast I/O helper class optimized for competitive programming.
     */
    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input", e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.util.*;

public class ProblemC {

    public static void main(String[] args) {
        new ProblemC().run();
    }

    private void run() {
        Scanner scanner = new Scanner(System.in);
        if (!scanner.hasNextInt()) {
            return;
        }
        int n = scanner.nextInt();

        // Handle edge case n=1 separately
        if (n == 1) {
            System.out.println("YES");
            if (scanner.hasNextInt()) {
                System.out.println(scanner.nextInt());
            }
            return;
        }

        // Read and count frequencies
        Map<Integer, Integer> frequencyMap = countFrequencies(scanner, n * n);

        // Solve and print result
        solve(n, frequencyMap);
    }

    /**
     * Reads n*n integers and returns their frequency map.
     */
    private Map<Integer, Integer> countFrequencies(Scanner scanner, int count) {
        Map<Integer, Integer> freq = new HashMap<>();
        for (int i = 0; i < count; i++) {
            if (scanner.hasNextInt()) {
                int num = scanner.nextInt();
                freq.merge(num, 1, Integer::sum);
            }
        }
        return freq;
    }

    /**
     * Distributes numbers into groups of 4, 2, and 1 based on matrix requirements,
     * then constructs and prints the matrix.
     */
    private void solve(int n, Map<Integer, Integer> frequencyMap) {
        int halfN = n / 2;
        int fourCapacity = halfN * halfN;
        int twoCapacity = (n % 2 == 1) ? (n - 1) : 0;
        int oneCapacity = (n % 2 == 1) ? 1 : 0;

        int[] fourElements = new int[fourCapacity];
        int[] twoElements = new int[twoCapacity];
        int oneElement = 0;

        int fourIdx = 0;
        int twoIdx = 0;
        int onesLeft = oneCapacity;

        // Sort entries by frequency ascending as per original logic
        List<Map.Entry<Integer, Integer>> sortedEntries = new ArrayList<>(frequencyMap.entrySet());
        sortedEntries.sort(Map.Entry.comparingByValue());

        for (Map.Entry<Integer, Integer> entry : sortedEntries) {
            int key = entry.getKey();
            int count = entry.getValue();

            int groupsOf4 = count / 4;
            int remainder = count % 4;

            // 1. Place as many groups of 4 as possible
            int foursToPlace = Math.min(groupsOf4, fourCapacity);
            fourCapacity -= foursToPlace;
            groupsOf4 -= foursToPlace;

            // 2. Convert excess groups of 4 into pairs
            if (groupsOf4 > 0) {
                int pairsFromQuads = groupsOf4 * 2;
                int pairsToPlace = Math.min(pairsFromQuads, twoCapacity);
                twoCapacity -= pairsToPlace;
            }

            // 3. Place the fours
            for (int i = 0; i < foursToPlace; i++) {
                fourElements[fourIdx++] = key;
            }

            // 4. Handle remainder: 2s
            if (remainder >= 2) {
                twoCapacity--;
                twoElements[twoIdx++] = key;
                remainder -= 2;
            }

            // 5. Handle remainder: 1
            if (remainder == 1) {
                onesLeft--;
                oneElement = key;
            }
        }

        // Check if distribution was feasible
        if (onesLeft < 0 || twoCapacity < 0 || fourCapacity < 0) {
            System.out.println("NO");
            return;
        }

        System.out.println("YES");
        printMatrix(n, fourElements, twoElements, oneElement, fourIdx, twoIdx);
    }

    /**
     * Constructs and prints the matrix rows. Each row is a palindrome.
     */
    private void printMatrix(int n, int[] fourElements, int[] twoElements, 
                             int oneElement, int fourIdx, int twoIdx) {
        Deque<Integer> stack = new ArrayDeque<>();
        int halfN = n / 2;

        // Print top half rows
        for (int i = 0; i < halfN; i++) {
            StringBuilder row = new StringBuilder();
            for (int j = 0; j < halfN; j++) {
                int val = fourElements[fourIdx++];
                row.append(val).append(' ');
                stack.push(val);
            }
            if (n % 2 == 1) {
                row.append(twoElements[twoIdx++]).append(' ');
            }
            // Append mirrored left half
            while (!stack.isEmpty()) {
                row.append(stack.pop()).append(' ');
            }
            System.out.println(row);
        }

        // Print middle row if n is odd
        if (n % 2 == 1) {
            StringBuilder sb = new StringBuilder();
            stack.clear();
            for (int i = 0; i < halfN; i++) {
                int val = twoElements[twoIdx];
                sb.append(val).append(' ');
                stack.push(val);
                twoIdx++;
            }
            sb.append(oneElement).append(' ');
            while (!stack.isEmpty()) {
                sb.append(stack.pop()).append(' ');
            }
            System.out.println(sb);
        }
    }
}

import java.util.Scanner;

/**
 * Solves the symmetric grid filling problem.
 * Constructs an n x n grid with 4-way rotational symmetry using the provided values.
 * For even n, fills the entire grid. For odd n, fills the four quadrants and the
 * middle cross, reserving the exact center for a single remaining value.
 */
public class GridSymmetrizer {
    private static final int MAX_VALUE = 1000;

    private final int size;
    private final int[][] grid;
    private int currentRow;
    private int currentCol;

    /**
     * Creates a GridSymmetrizer for an n x n board.
     *
     * @param size the dimension of the square grid
     */
    public GridSymmetrizer(int size) {
        if (size <= 0) {
            throw new IllegalArgumentException("Grid size must be a positive integer");
        }
        this.size = size;
        this.grid = new int[size][size];
        this.currentRow = 0;
        this.currentCol = 0;
    }

    /**
     * Attempts to fill the grid according to the symmetry rules.
     *
     * @param inputValues the n*n input numbers to place
     * @return true if a valid configuration exists, false otherwise
     */
    public boolean solve(int[] inputValues) {
        int[] valueCounts = new int[MAX_VALUE + 1];
        for (int val : inputValues) {
            if (val < 0 || val > MAX_VALUE) {
                throw new IllegalArgumentException("Input values must be between 0 and " + MAX_VALUE);
            }
            valueCounts[val]++;
        }

        int filledCount = 0;

        // Phase 1: Fill the four quadrants using groups of 4
        for (int val = 0; val <= MAX_VALUE; val++) {
            while (valueCounts[val] >= 4) {
                fillQuadrant(val);
                valueCounts[val] -= 4;
                filledCount += 4;
            }
        }

        if (size % 2 == 0) {
            return filledCount == size * size;
        } else {
            // Phase 2: Fill the middle row and column using groups of 2
            resetForMiddleCross();
            int centerValue = -1;
            boolean possible = true;

            for (int val = 0; val <= MAX_VALUE; val++) {
                while (valueCounts[val] >= 2 && filledCount < size * size) {
                    fillMiddleCross(val);
                    valueCounts[val] -= 2;
                    filledCount += 2;
                }
                if (valueCounts[val] == 1) {
                    if (centerValue == -1) {
                        centerValue = val;
                    } else {
                        possible = false;
                    }
                }
            }

            if (possible && centerValue != -1) {
                grid[size / 2][size / 2] = centerValue;
                return true;
            }
            return false;
        }
    }

    /**
     * Places a value in the four symmetric positions of the current quadrant cell.
     * Advances the cursor to the next cell in the top-left quadrant.
     */
    private void fillQuadrant(int value) {
        grid[currentRow][currentCol] = value;
        grid[currentRow][size - 1 - currentCol] = value;
        grid[size - 1 - currentRow][currentCol] = value;
        grid[size - 1 - currentRow][size - 1 - currentCol] = value;

        currentCol++;
        if (currentCol == size / 2) {
            currentCol = 0;
            currentRow++;
        }
    }

    /**
     * Resets the cursor to the start of the middle cross (middle row, first column).
     */
    private void resetForMiddleCross() {
        currentRow = size / 2;
        currentCol = 0;
    }

    /**
     * Places a value in the four symmetric positions for the middle cross.
     * Advances the cursor along the middle row and column.
     */
    private void fillMiddleCross(int value) {
        grid[currentRow][currentCol] = value;
        grid[currentRow][size - 1 - currentCol] = value;
        grid[size - 1 - currentRow][currentCol] = value;
        grid[size - 1 - currentRow][size - 1 - currentCol] = value;

        if (currentRow == size / 2) {
            currentCol++;
            if (currentCol == size / 2) {
                currentRow = 0;
                currentCol = size / 2;
            }
        } else {
            currentRow++;
        }
    }

    /**
     * Prints the resulting grid to standard output.
     */
    public void print() {
        System.out.println("YES");
        for (int[] rowArray : grid) {
            for (int value : rowArray) {
                System.out.print(value + " ");
            }
            System.out.println();
        }
    }

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            if (!scanner.hasNextInt()) {
                return;
            }
            int n = scanner.nextInt();
            if (n <= 0) {
                System.out.println("NO");
                return;
            }

            int totalCells = n * n;
            int[] inputValues = new int[totalCells];
            for (int i = 0; i < totalCells; i++) {
                inputValues[i] = scanner.nextInt();
            }

            GridSymmetrizer solver = new GridSymmetrizer(n);
            if (solver.solve(inputValues)) {
                solver.print();
            } else {
                System.out.println("NO");
            }
        }
    }
}

import java.io.*;
import java.util.*;

public class PalindromicMatrix {
    private static final int MAX_VALUE = 1000;
    private static final int CORNERS = 4;
    private static final int MID_LINE = 2;
    private static final int CENTER = 1;

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner();
        // BufferedOutputStream improves performance for large outputs
        PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out));
        try {
            solve(scanner, out);
        } finally {
            out.flush();
        }
    }

    private static void solve(FastScanner scanner, PrintWriter out) {
        int n = scanner.nextInt();
        int[] counts = new int[MAX_VALUE + 1];

        // Count frequencies directly without storing unused array
        for (int i = 0; i < n * n; i++) {
            counts[scanner.nextInt()]++;
        }

        // Max-heap ordered by frequency (descending)
        PriorityQueue<Element> pq = new PriorityQueue<>();
        for (int i = 0; i <= MAX_VALUE; i++) {
            if (counts[i] > 0) {
                pq.offer(new Element(i, counts[i]));
            }
        }

        int[][] matrix = new int[n][n];
        int half = n / 2;

        // 1. Fill 4-fold symmetric corners
        for (int r = 0; r < half; r++) {
            for (int c = 0; c < half; c++) {
                Element el = takeFromQueue(pq, CORNERS);
                if (el == null) {
                    out.println("NO");
                    return;
                }
                matrix[r][c] = matrix[n - 1 - r][c] = 
                               matrix[n - 1 - r][n - 1 - c] = matrix[r][n - 1 - c] = el.value;
            }
        }

        // 2. Handle odd dimensions: middle row, middle column, and center
        if (n % 2 == 1) {
            // Middle row (2-fold symmetry)
            for (int c = 0; c < half; c++) {
                Element el = takeFromQueue(pq, MID_LINE);
                if (el == null) {
                    out.println("NO");
                    return;
                }
                matrix[half][c] = matrix[half][n - 1 - c] = el.value;
            }

            // Middle column (2-fold symmetry)
            for (int r = 0; r < half; r++) {
                Element el = takeFromQueue(pq, MID_LINE);
                if (el == null) {
                    out.println("NO");
                    return;
                }
                matrix[r][half] = matrix[n - 1 - r][half] = el.value;
            }

            // Center element (requires exactly 1)
            Element el = takeFromQueue(pq, CENTER);
            if (el == null) {
                out.println("NO");
                return;
            }
            matrix[half][half] = el.value;
        }

        // 3. Output result
        out.println("YES");
        printMatrix(out, matrix);
    }

    /**
     * Retrieves an element from the priority queue that satisfies the required count.
     * If insufficient count remains, returns null. Otherwise, polls the element,
     * pushes back the remainder if any, and returns the original element.
     */
    private static Element takeFromQueue(PriorityQueue<Element> pq, int required) {
        if (pq.isEmpty() || pq.peek().count < required) {
            return null;
        }
        Element current = pq.poll();
        if (current.count > required) {
            pq.offer(new Element(current.value, current.count - required));
        }
        return current;
    }

    private static void printMatrix(PrintWriter out, int[][] matrix) {
        for (int[] row : matrix) {
            for (int val : row) {
                out.print(val + " ");
            }
            out.println();
        }
    }

    /** Represents a value and its remaining frequency count. */
    private static class Element implements Comparable<Element> {
        final int value;
        final int count;

        Element(int value, int count) {
            this.value = value;
            this.count = count;
        }

        @Override
        public int compareTo(Element other) {
            // Descending order by count
            return Integer.compare(other.count, this.count);
        }
    }

    /** Lightweight fast I/O scanner for competitive programming. */
    private static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner() {
            this.br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            String s = next();
            if (s == null) throw new NoSuchElementException("Unexpected end of input");
            return Integer.parseInt(s);
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Solves a grid reconstruction problem by distributing input values
 * into an n x n grid following specific symmetry rules.
 * 
 * Refactoring highlights:
 * - Separated I/O, logic, and output into distinct, single-responsibility methods.
 * - Replaced raw generic types with properly typed collections.
 * - Eliminated magic '0' empty-cell check by using a dedicated boolean matrix.
 * - Improved naming, added JavaDoc, and standardized formatting.
 * - Handled resources safely with try-finally.
 */
public class Main {

    public static void main(String[] args) {
        FastScanner sc = new FastScanner();
        PrintWriter out = new PrintWriter(System.out);
        try {
            solve(sc, out);
        } finally {
            out.flush();
            out.close();
        }
    }

    private static void solve(FastScanner sc, PrintWriter out) {
        int n = sc.nextInt();
        int[] frequencies = new int[1001];
        int totalElements = n * n;

        for (int i = 0; i < totalElements; i++) {
            frequencies[sc.nextInt()]++;
        }

        List<Queue<Integer>> valueQueues = buildValueQueues(frequencies);
        int[][] grid = new int[n][n];
        boolean[][] filled = new boolean[n][n];

        if (!fillGrid(n, grid, filled, valueQueues, out)) {
            return;
        }

        out.println("YES");
        printGrid(out, grid);
    }

    /**
     * Distributes value frequencies into queues based on divisibility rules:
     * - Groups of 4 go to queue index 4
     * - Groups of 2 go to queue index 2
     * - Remainder (1) goes to queue index 1
     */
    private static List<Queue<Integer>> buildValueQueues(int[] frequencies) {
        List<Queue<Integer>> queues = new ArrayList<>(5);
        for (int i = 0; i < 5; i++) {
            queues.add(new ArrayDeque<>());
        }

        for (int val = 0; val <= 1000; val++) {
            int count = frequencies[val];
            while (count >= 4) {
                queues.get(4).add(val);
                count -= 4;
            }
            if (count >= 2) {
                queues.get(2).add(val);
                count -= 2;
            }
            if (count > 0) {
                queues.get(1).add(val);
            }
        }
        return queues;
    }

    /**
     * Fills the grid according to the problem's symmetry constraints.
     * Returns false and prints "NO" if the configuration is impossible.
     */
    private static boolean fillGrid(int n, int[][] grid, boolean[][] filled, 
                                    List<Queue<Integer>> queues, PrintWriter out) {

        // Handle center and cross for odd-sized grids
        if (n % 2 != 0) {
            if (queues.get(1).isEmpty()) {
                out.println("NO");
                return false;
            }

            int center = n / 2;
            grid[center][center] = queues.get(1).poll();
            filled[center][center] = true;

            for (int j = 0; j < center; j++) {
                if (queues.get(2).size() >= 2) {
                    int val1 = queues.get(2).poll();
                    int val2 = queues.get(2).poll();

                    grid[center][j] = val1; filled[center][j] = true;
                    grid[center][n - 1 - j] = val1; filled[center][n - 1 - j] = true;
                    grid[j][center] = val2; filled[j][center] = true;
                    grid[n - 1 - j][center] = val2; filled[n - 1 - j][center] = true;
                } else if (!queues.get(4).isEmpty()) {
                    int val = queues.get(4).poll();

                    grid[center][j] = val; filled[center][j] = true;
                    grid[center][n - 1 - j] = val; filled[center][n - 1 - j] = true;
                    grid[j][center] = val; filled[j][center] = true;
                    grid[n - 1 - j][center] = val; filled[n - 1 - j][center] = true;
                } else {
                    out.println("NO");
                    return false;
                }
            }
        }

        // Fill remaining cells using groups of 4
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (filled[i][j]) continue;

                if (queues.get(4).isEmpty()) {
                    out.println("NO");
                    return false;
                }

                int val = queues.get(4).poll();
                grid[i][j] = val; filled[i][j] = true;
                grid[n - 1 - i][n - 1 - j] = val; filled[n - 1 - i][n - 1 - j] = true;
                grid[i][n - 1 - j] = val; filled[i][n - 1 - j] = true;
                grid[n - 1 - i][j] = val; filled[n - 1 - i][j] = true;
            }
        }
        return true;
    }

    private static void printGrid(PrintWriter out, int[][] grid) {
        for (int[] row : grid) {
            for (int val : row) {
                out.print(val + " ");
            }
            out.println();
        }
    }

    /**
     * Fast input reader optimized for competitive programming environments.
     */
    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) throw new EOFException();
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.HashMap;
import java.util.Map;
import java.util.PriorityQueue;
import java.util.StringTokenizer;

public class C1118 {

    /**
     * Represents a number and its frequency count.
     * Elements are ordered in the priority queue by count (ascending), then by value (ascending).
     */
    private static class Element implements Comparable<Element> {
        final int value;
        final int count;

        Element(int value, int count) {
            this.value = value;
            this.count = count;
        }

        @Override
        public int compareTo(Element other) {
            // Primary sort: frequency ascending
            if (this.count != other.count) {
                return Integer.compare(this.count, other.count);
            }
            // Secondary sort: numeric value ascending
            return Integer.compare(this.value, other.value);
        }
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line = br.readLine();
        if (line == null || line.trim().isEmpty()) {
            return;
        }

        int n = Integer.parseInt(line.trim());
        int totalElements = n * n;
        int[] nums = new int[totalElements];
        int idx = 0;

        // Robustly read n*n integers, handling multi-line input and varying whitespace
        StringTokenizer st = new StringTokenizer("");
        while (idx < totalElements) {
            while (!st.hasMoreTokens()) {
                String s = br.readLine();
                if (s == null) break;
                st = new StringTokenizer(s);
            }
            if (st.hasMoreTokens()) {
                nums[idx++] = Integer.parseInt(st.nextToken());
            } else {
                break;
            }
        }

        PriorityQueue<Element> pq = buildPriorityQueue(nums);
        int[][] grid = new int[n][n];

        if (!fillGrid(grid, pq)) {
            System.out.println("NO");
            return;
        }

        StringBuilder sb = new StringBuilder("YES\n");
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                sb.append(grid[i][j]).append(' ');
            }
            sb.append('\n');
        }
        System.out.println(sb);
    }

    /**
     * Counts frequencies of each number and populates a priority queue.
     * Time Complexity: O(N) where N is the number of input integers.
     */
    private static PriorityQueue<Element> buildPriorityQueue(int[] nums) {
        Map<Integer, Integer> frequencyMap = new HashMap<>();
        for (int num : nums) {
            frequencyMap.merge(num, 1, Integer::sum);
        }

        PriorityQueue<Element> pq = new PriorityQueue<>();
        for (Map.Entry<Integer, Integer> entry : frequencyMap.entrySet()) {
            pq.add(new Element(entry.getKey(), entry.getValue()));
        }
        return pq;
    }

    /**
     * Fills the grid with symmetric patterns using the available elements.
     * Processes concentric layers from outside in:
     * 1. 4-corner symmetric positions
     * 2. Middle row and column (if n is odd)
     * 3. Center element (if n is odd)
     *
     * @return true if a valid configuration is formed, false otherwise
     */
    private static boolean fillGrid(int[][] grid, PriorityQueue<Element> pq) {
        int n = grid.length;
        int half = n / 2;

        // 1. Fill the 4-corner symmetric positions for each concentric layer
        for (int i = 0; i < half; i++) {
            for (int j = 0; j < half; j++) {
                Element el = pq.poll();
                if (el == null || el.count < 4) {
                    return false;
                }
                grid[i][j] = grid[n - 1 - i][j] = grid[i][n - 1 - j] = grid[n - 1 - i][n - 1 - j] = el.value;
                if (el.count > 4) {
                    pq.add(new Element(el.value, el.count - 4));
                }
            }
        }

        // 2. Fill the middle row and column (only if n is odd)
        if (n % 2 == 1) {
            // Middle row
            for (int i = 0; i < half; i++) {
                Element el = pq.poll();
                if (el == null || el.count < 2) {
                    return false;
                }
                grid[half][i] = grid[half][n - 1 - i] = el.value;
                if (el.count > 2) {
                    pq.add(new Element(el.value, el.count - 2));
                }
            }
            // Middle column
            for (int i = 0; i < half; i++) {
                Element el = pq.poll();
                if (el == null || el.count < 2) {
                    return false;
                }
                grid[i][half] = grid[n - 1 - i][half] = el.value;
                if (el.count > 2) {
                    pq.add(new Element(el.value, el.count - 2));
                }
            }
            // Center element
            Element centerEl = pq.poll();
            if (centerEl == null || centerEl.count < 1) {
                return false;
            }
            grid[half][half] = centerEl.value;
        }

        return true;
    }
}

import java.util.ArrayList;
import java.util.Comparator;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Scanner;

public class ProblemC {

    /**
     * Represents a number and its frequency in the input.
     */
    private static class Number {
        final int value;
        int frequency;

        Number(int value) {
            this.value = value;
            this.frequency = 1;
        }
    }

    public static void main(String[] args) {
        // Use try-with-resources to automatically close the scanner
        try (Scanner scanner = new Scanner(System.in)) {
            if (!scanner.hasNextInt()) return;
            int n = scanner.nextInt();
            int totalElements = n * n;

            // Count frequencies of each number
            Map<Integer, Number> frequencyMap = new HashMap<>();
            for (int i = 0; i < totalElements; i++) {
                int x = scanner.nextInt();
                frequencyMap.computeIfAbsent(x, Number::new);
                frequencyMap.get(x).frequency++;
            }

            int[][] matrix = new int[n][n];
            // Extract values to a list and sort by frequency (ascending)
            List<Number> numberList = new ArrayList<>(frequencyMap.values());
            numberList.sort(Comparator.comparingInt(num -> num.frequency));

            // Attempt to fill the matrix layer by layer
            boolean possible = fillLayer(matrix, 0, n, numberList);

            if (possible) {
                System.out.println("YES");
                printMatrix(matrix);
            } else {
                System.out.println("NO");
            }
        }
    }

    /**
     * Recursively fills concentric layers of the matrix.
     * Handles both even and odd dimensions uniformly.
     */
    private static boolean fillLayer(int[][] matrix, int layer, int size, List<Number> numberList) {
        // Base cases for recursion
        if (size == 0) {
            return true;
        }
        if (size == 1) {
            int index = findAndDecrement(numberList, 1);
            if (index == -1) return false;
            matrix[layer][layer] = numberList.get(index).value;
            return true;
        }

        // Fill four corners of the current layer
        for (int i = layer; i < size / 2; i++) {
            int index = findAndDecrement(numberList, 4);
            if (index == -1) return false;
            int val = numberList.get(index).value;
            matrix[layer][i] = val;
            matrix[layer][size - 1 - i] = val;
            matrix[size - 1 - layer][i] = val;
            matrix[size - 1 - layer][size - 1 - i] = val;
        }

        // Fill four edges (excluding corners and center if odd)
        for (int i = layer + 1; i < size / 2; i++) {
            int index = findAndDecrement(numberList, 4);
            if (index == -1) return false;
            int val = numberList.get(index).value;
            matrix[i][layer] = val;
            matrix[i][size - 1 - layer] = val;
            matrix[size - 1 - i][layer] = val;
            matrix[size - 1 - i][size - 1 - layer] = val;
        }

        // Handle middle elements for odd-sized matrices
        if (size % 2 != 0) {
            int mid = size / 2;

            // Top and bottom middle positions
            int index = findAndDecrement(numberList, 2);
            if (index == -1) return false;
            int val = numberList.get(index).value;
            matrix[layer][mid] = val;
            matrix[size - 1 - layer][mid] = val;

            // Left and right middle positions
            index = findAndDecrement(numberList, 2);
            if (index == -1) {
                index = findAndDecrement(numberList, 3);
            }
            if (index == -1) return false;
            val = numberList.get(index).value;
            matrix[mid][layer] = val;
            matrix[mid][size - 1 - layer] = val;
        }

        // Recurse to the next inner layer
        return fillLayer(matrix, layer + 1, size - 2, numberList);
    }

    /**
     * Finds the first number in the list with at least minFreq remaining,
     * decrements its frequency, and returns its index.
     */
    private static int findAndDecrement(List<Number> list, int minFreq) {
        for (int i = 0; i < list.size(); i++) {
            if (list.get(i).frequency >= minFreq) {
                list.get(i).frequency -= minFreq;
                return i;
            }
        }
        return -1;
    }

    /**
     * Prints the matrix row by row without trailing spaces.
     */
    private static void printMatrix(int[][] matrix) {
        for (int[] row : matrix) {
            for (int j = 0; j < row.length; j++) {
                System.out.print(row[j] + (j == row.length - 1 ? "" : " "));
            }
            System.out.println();
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.PriorityQueue;
import java.util.StringTokenizer;

/**
 * Solves the concentric grid arrangement problem.
 * Reads an integer n and n*n integers, counts frequencies, and attempts to fill 
 * an n x n grid such that each concentric layer uses 4 identical values, 
 * the middle row/column (if n is odd) uses 2, and the center uses 1.
 */
public class CFG {

    /**
     * FastScanner for efficient token-based input reading.
     */
    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        public String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) {
                        throw new IOException("End of input reached unexpectedly");
                    }
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input", e);
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }

    /**
     * Represents a value and its remaining frequency for priority-based selection.
     */
    static class ElementCount implements Comparable<ElementCount> {
        final int value;
        int count;

        public ElementCount(int value, int count) {
            this.value = value;
            this.count = count;
        }

        @Override
        public int compareTo(ElementCount other) {
            // Descending order by frequency
            return Integer.compare(other.count, this.count);
        }
    }

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            int n = scanner.nextInt();
            solve(n, scanner, out);
        } catch (Exception e) {
            System.err.println("Input error: " + e.getMessage());
        } finally {
            out.flush();
        }
    }

    /**
     * Orchestrates the grid arrangement process.
     */
    private static void solve(int n, FastScanner scanner, PrintWriter out) {
        int[] frequency = new int[1001];
        int totalElements = n * n;

        // Count frequencies of all input values
        for (int i = 0; i < totalElements; i++) {
            frequency[scanner.nextInt()]++;
        }

        // Build max-heap based on frequency
        PriorityQueue<ElementCount> priorityQueue = new PriorityQueue<>();
        for (int val = 0; val <= 1000; val++) {
            if (frequency[val] > 0) {
                priorityQueue.add(new ElementCount(val, frequency[val]));
            }
        }

        int[][] grid = new int[n][n];

        if (tryFillGrid(n, priorityQueue, grid)) {
            out.println("YES");
            printGrid(grid, out);
        } else {
            out.println("NO");
        }
    }

    /**
     * Attempts to fill the grid layer by layer using the most frequent available elements.
     * Returns true if a valid arrangement is found, false otherwise.
     */
    private static boolean tryFillGrid(int n, PriorityQueue<ElementCount> pq, int[][] grid) {
        // Fill concentric square layers
        for (int i = 0; i < n / 2; i++) {
            for (int j = 0; j < n / 2; j++) {
                if (pq.isEmpty() || pq.peek().count < 4) {
                    return false;
                }
                ElementCount top = pq.poll();

                // Assign to 4 symmetric positions
                grid[i][j] = top.value;
                grid[i][n - 1 - j] = top.value;
                grid[n - 1 - i][n - 1 - j] = top.value;
                grid[n - 1 - i][j] = top.value;

                top.count -= 4;
                if (top.count > 0) {
                    pq.add(top);
                }
            }
        }

        // Handle odd dimension center cross
        if (n % 2 != 0) {
            int mid = n / 2;

            // Fill middle row (excluding center)
            for (int i = 0; i < mid; i++) {
                if (pq.isEmpty() || pq.peek().count < 2) {
                    return false;
                }
                ElementCount top = pq.poll();
                grid[mid][i] = top.value;
                grid[mid][n - 1 - i] = top.value;
                top.count -= 2;
                if (top.count > 0) {
                    pq.add(top);
                }
            }

            // Fill middle column (excluding center)
            for (int i = 0; i < mid; i++) {
                if (pq.isEmpty() || pq.peek().count < 2) {
                    return false;
                }
                ElementCount top = pq.poll();
                grid[i][mid] = top.value;
                grid[n - 1 - i][mid] = top.value;
                top.count -= 2;
                if (top.count > 0) {
                    pq.add(top);
                }
            }

            // Fill center element
            if (!pq.isEmpty() && pq.peek().count > 0) {
                grid[mid][mid] = pq.poll().value;
            }
        }

        // Verify all elements were successfully placed
        return pq.isEmpty();
    }

    /**
     * Formats and prints the resulting grid.
     */
    private static void printGrid(int[][] grid, PrintWriter out) {
        for (int[] row : grid) {
            StringBuilder rowBuilder = new StringBuilder();
            for (int value : row) {
                rowBuilder.append(value).append(' ');
            }
            out.println(rowBuilder);
        }
    }
}

