            }
        } catch (Exception e) {
            out.println("NO");
        } finally {
            out.flush();
        }
    }

    /**
     * Calculates the required number of elements for each symmetry position.
     * 4-way: corners (n/2 * n/2)
     * 2-way: middle edges (n-1 if odd, else 0)
     * 1-way: center (1 if odd, else 0)
     */
    private static int[] calculateRequirements(int n) {
        int reqFours = (n / 2) * (n / 2);
        int reqTwos = (n % 2 == 1) ? (n - 1) : 0;
        int reqOnes = (n % 2 == 1) ? 1 : 0;
        return new int[]{reqFours, reqTwos, reqOnes};
    }

    /**
     * Distributes numbers into lists based on how many times they appear.
     */
    private static void categorizeNumbers(int[] freq, List<Integer> fours, List<Integer> twos, List<Integer> ones) {
        for (int i = 1; i <= MAX_VALUE; i++) {
            int count = freq[i];

            // Extract groups of 4
            int f = count / QUARTER;
            count %= QUARTER;
            while (f-- > 0) fours.add(i);

            // Extract groups of 2
            int t = count / HALF;
            while (t-- > 0) twos.add(i);
            count %= HALF;

            // Remaining is group of 1
            int o = count;
            while (o-- > 0) ones.add(i);
        }
    }

    /**
     * Converts pairs from groupsOfFour to groupsOfTwo to meet requirements.
     */
    private static void balanceLists(int reqTwos, List<Integer> fours, List<Integer> twos) {
        int diff = reqTwos - twos.size();

        // Cannot balance if we need fewer twos or if the difference is odd
        if (diff < 0 || diff % 2 != 0) {
            return;
        }

        int pairsToConvert = diff / 2;
        for (int i = 0; i < pairsToConvert; i++) {
            if (!fours.isEmpty()) {
                int val = fours.remove(fours.size() - 1);
                twos.add(val);
                twos.add(val);
            } else {
                break; // Not enough fours to convert
            }
        }
    }

    /**
     * Validates that all lists match the exact required sizes.
     */
    private static boolean validateCounts(int reqFours, int reqTwos, int reqOnes,
                                          List<Integer> fours, List<Integer> twos, List<Integer> ones) {
        return fours.size() == reqFours &&
               twos.size() == reqTwos &&
               ones.size() == reqOnes;
    }

    /**
     * Constructs the grid using 4-way rotational symmetry.
     */
    private static int[][] buildGrid(int n, List<Integer> fours, List<Integer> twos, List<Integer> ones) {
        int[][] grid = new int[n][n];
        int mid = n / 2;

        // Fill corners (4-way symmetry)
        for (int i = 0; i < mid; i++) {
            for (int j = 0; j < mid; j++) {
                int val = fours.remove(fours.size() - 1);
                grid[i][j] = val;
                grid[n - 1 - i][j] = val;
                grid[n - 1 - i][n - 1 - j] = val;
                grid[i][n - 1 - j] = val;
            }
        }

        // Fill center (1-way symmetry)
        if (n % 2 == 1) {
            grid[mid][mid] = ones.remove(ones.size() - 1);
        }

        // Fill middle edges (2-way symmetry)
        if (!twos.isEmpty()) {
            // Vertical middle edges
            for (int i = 0; i < mid; i++) {
                int val = twos.remove(twos.size() - 1);
                grid[i][mid] = val;
                grid[n - 1 - i][mid] = val;
            }
            // Horizontal middle edges
            for (int i = 0; i < mid; i++) {
                int val = twos.remove(twos.size() - 1);
                grid[mid][i] = val;
                grid[mid][n - 1 - i] = val;
            }
        }
        return grid;
    }

    /**
     * Prints the grid to the provided PrintWriter.
     */
    private static void printGrid(PrintWriter out, int[][] grid) {
        int n = grid.length;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                out.print(grid[i][j] + " ");
            }
            out.println();
        }
    }

    /**
     * Fast I/O helper class for competitive programming / high-throughput input.
     */
    static class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) return null;
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

        int nextInt() throws IOException {
            String token = next();
            return token == null ? 0 : Integer.parseInt(token);
        }

        long nextLong() throws IOException {
            String token = next();
            return token == null ? 0L : Long.parseLong(token);
        }

        double nextDouble() throws IOException {
            String token = next();
            return token == null ? 0.0 : Double.parseDouble(token);
        }
    }
}

import java.util.Scanner;
import java.io.PrintWriter;
import java.io.BufferedOutputStream;

public class Main {
    // Constant defining the maximum value for input numbers.
    // Based on the original code's MAXN = 1001.
    private static final int MAX_VALUE_LIMIT = 1001;

    public static void main(String[] args) {
        // Initialize Scanner for input and PrintWriter for buffered output
        Scanner scanner = new Scanner(System.in);
        PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out));

        try {
            // Read the size of the grid
            if (scanner.hasNextInt()) {
                int n = scanner.nextInt();
                solve(n, scanner, out);
            }
        } finally {
            // Ensure resources are closed and output is flushed
            scanner.close();
            out.flush();
            out.close();
        }
    }

    /**
     * Solves the grid filling problem.
     * 
     * @param n The dimension of the grid (n x n).
     * @param scanner The input scanner.
     * @param out The output printer.
     */
    private static void solve(int n, Scanner scanner, PrintWriter out) {
        // Array to store the frequency of each number available.
        // Index represents the number, value represents the count.
        int[] counts = new int[MAX_VALUE_LIMIT];
        int totalCells = n * n;

        // Read n*n integers and populate the frequency array
        for (int k = 0; k < totalCells; k++) {
            if (scanner.hasNextInt()) {
                int val = scanner.nextInt();
                // Only count numbers within the supported range to prevent IndexOutOfBounds
                if (val < MAX_VALUE_LIMIT) {
                    counts[val]++;
                }
            }
        }

        int[][] grid = new int[n][n];
        boolean isPossible = true;

        // Weights represent the number of symmetric positions a cell covers.
        // Order 4, 2, 1 prioritizes filling cells that require more copies of a number.
        int[] weightsToFill = {4, 2, 1};

        for (int targetWeight : weightsToFill) {
            // Optimization: Start searching for numbers from 1 for each weight type
            // to find the smallest valid number available.
            int currentSearchVal = 1;

            // Iterate over the top-left quadrant of the grid.
            // This range covers all unique symmetric positions.
            int limit = (n + 1) / 2;

            for (int i = 0; i < limit; i++) {
                for (int j = 0; j < limit; j++) {
                    // Determine the weight (number of symmetric cells) for position (i, j).
                    // A cell is on the middle row if n is odd and i == n/2.
                    // A cell is on the middle col if n is odd and j == n/2.
                    boolean isOnMiddleRow = (n % 2 != 0) && (i == n / 2);
                    boolean isOnMiddleCol = (n % 2 != 0) && (j == n / 2);

                    int currentWeight = 1;
                    if (!isOnMiddleRow) currentWeight *= 2;
                    if (!isOnMiddleCol) currentWeight *= 2;

                    // If this cell's weight doesn't match the current target, skip it.
                    if (currentWeight != targetWeight) {
                        continue;
                    }

                    // Find the smallest number 'val' that has enough count to fill 'targetWeight'.
                    // We continue searching from 'currentSearchVal' because counts only decrease,
                    // so numbers smaller than currentSearchVal are no longer valid or were skipped.
                    while (currentSearchVal < MAX_VALUE_LIMIT && counts[currentSearchVal] < targetWeight) {
                        currentSearchVal++;
                    }

                    if (currentSearchVal >= MAX_VALUE_LIMIT) {
                        // No valid number found to fill this cell
                        isPossible = false;
                        break;
                    }

                    // Assign the found number to all symmetric positions in the grid
                    int val = currentSearchVal;
                    grid[i][j] = val;
                    grid[n - 1 - i][j] = val;
                    grid[i][n - 1 - j] = val;
                    grid[n - 1 - i][n - 1 - j] = val;

                    // Decrement the count of the used number
                    counts[val] -= targetWeight;
                }
                if (!isPossible) break;
            }
            if (!isPossible) break;
        }

        if (isPossible) {
            out.println("YES");
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < n; j++) {
                    out.print(grid[i][j]);
                    // Print space between numbers, but not after the last number in a row
                    if (j < n - 1) {
                        out.print(" ");
                    }
                }
                out.println();
            }
        } else {
            out.println("NO");
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.Arrays;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.NoSuchElementException;
import java.util.PriorityQueue;
import java.util.StringTokenizer;

public class PalindromicMatrix {

    /**
     * Represents a number and its available frequency count.
     * Used to efficiently track how many times each value can be placed.
     */
    static class NumberFrequency {
        int count;
        int value;

        NumberFrequency(int count, int value) {
            this.count = count;
            this.value = value;
        }
    }

    public static void main(String[] args) {
        FastScanner sc = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            int n = sc.nextInt();
            int[][] matrix = new int[n][n];
            Map<Integer, Integer> freqMap = new HashMap<>();

            // Read input and count frequencies using Map.merge for cleaner logic
            for (int i = 0; i < n * n; i++) {
                freqMap.merge(sc.nextInt(), 1, Integer::sum);
            }

            // Max-heap ordered by frequency descending, then value descending
            PriorityQueue<NumberFrequency> pq = new PriorityQueue<>((a, b) -> {
                if (a.count != b.count) {
                    return b.count - a.count;
                }
                return b.value - a.value;
            });

            for (Map.Entry<Integer, Integer> entry : freqMap.entrySet()) {
                pq.add(new NumberFrequency(entry.getValue(), entry.getKey()));
            }

            if (!solve(n, matrix, pq, out)) {
                out.println("NO");
            } else {
                out.println("YES");
                printMatrix(matrix, out);
            }
        } finally {
            out.flush();
        }
    }

    /**
     * Attempts to fill the matrix with palindromic symmetry.
     * Returns false if a valid configuration is impossible.
     */
    private static boolean solve(int n, int[][] matrix, PriorityQueue<NumberFrequency> pq, PrintWriter out) {
        int half = n / 2;

        // Fill the four symmetric quadrants
        for (int i = 0; i < half; i++) {
            for (int j = 0; j < half; j++) {
                List<int[]> positions = Arrays.asList(
                    new int[]{i, j},
                    new int[]{i, n - 1 - j},
                    new int[]{n - 1 - i, j},
                    new int[]{n - 1 - i, n - 1 - j}
                );
                if (!fillPositions(pq, matrix, positions)) {
                    return false;
                }
            }
        }

        // Handle middle row and column if n is odd
        if (n % 2 != 0) {
            int mid = half;

            // Middle column (excluding center)
            for (int i = 0; i < half; i++) {
                List<int[]> positions = Arrays.asList(
                    new int[]{i, mid},
                    new int[]{n - 1 - i, mid}
                );
                if (!fillPositions(pq, matrix, positions)) {
                    return false;
                }
            }

            // Middle row (excluding center)
            for (int i = 0; i < half; i++) {
                List<int[]> positions = Arrays.asList(
                    new int[]{mid, i},
                    new int[]{mid, n - 1 - i}
                );
                if (!fillPositions(pq, matrix, positions)) {
                    return false;
                }
            }

            // Center element
            List<int[]> positions = Arrays.asList(new int[]{mid, mid});
            if (!fillPositions(pq, matrix, positions)) {
                return false;
            }
        }

        return true;
    }

    /**
     * Greedily assigns the highest frequency number to the given symmetric positions.
     * Returns false if the available count is insufficient.
     */
    private static boolean fillPositions(PriorityQueue<NumberFrequency> pq, int[][] matrix, List<int[]> positions) {
        if (pq.isEmpty()) {
            return false;
        }

        NumberFrequency top = pq.peek();
        if (top.count < positions.size()) {
            return false;
        }

        NumberFrequency freq = pq.poll();
        for (int[] pos : positions) {
            matrix[pos[0]][pos[1]] = freq.value;
        }

        freq.count -= positions.size();
        pq.add(freq);
        return true;
    }

    /**
     * Prints the completed matrix to the output stream.
     */
    private static void printMatrix(int[][] matrix, PrintWriter out) {
        int n = matrix.length;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                out.print(matrix[i][j]);
                if (j < n - 1) {
                    out.print(' ');
                }
            }
            out.println();
        }
    }

    /**
     * Optimized FastScanner for efficient console input reading.
     */
    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) {
                        return null;
                    }
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            String s = next();
            if (s == null) {
                throw new NoSuchElementException("End of input");
            }
            return Integer.parseInt(s);
        }
    }
}

import java.io.*;
import java.util.*;

public class Solution {
    public static void main(String[] args) throws IOException {
        // Use BufferedReader and PrintWriter for efficient I/O handling
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out));
        StringTokenizer st = null;

        // Read n
        String line = br.readLine();
        while (line != null && line.trim().isEmpty()) {
            line = br.readLine();
        }
        if (line == null) return;
        st = new StringTokenizer(line);
        int n = Integer.parseInt(st.nextToken());

        // Frequency array for colors. 100001 safely covers typical competitive programming constraints.
        int[] colorCounts = new int[100001];
        int maxColor = 0;
        int totalElements = n * n;

        // Read n*n integers
        for (int i = 0; i < totalElements; i++) {
            while (st == null || !st.hasMoreTokens()) {
                String nextLine = br.readLine();
                if (nextLine == null) break;
                st = new StringTokenizer(nextLine);
            }
            int color = Integer.parseInt(st.nextToken());
            colorCounts[color]++;
            if (color > maxColor) maxColor = color;
        }

        int[][] grid = new int[n][n];

        // Validate configuration possibility
        if (canConstruct(n, colorCounts, maxColor)) {
            out.println("YES");
            constructGrid(n, colorCounts, maxColor, grid);
        } else {
            out.println("NO");
        }

        // Output grid if valid
        if (canConstruct(n, colorCounts, maxColor)) {
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < n; j++) {
                    out.print(grid[i][j]);
                    out.print(j == n - 1 ? "" : " ");
                }
                out.println();
            }
        }

        out.flush();
        out.close();
        br.close();
    }

    /**
     * Validates if a valid grid configuration is possible based on n and color frequencies.
     */
    private static boolean canConstruct(int n, int[] counts, int maxColor) {
        if (n % 2 == 0) {
            // For even n, every color count must be divisible by 4
            for (int i = 1; i <= maxColor; i++) {
                if (counts[i] > 0 && counts[i] % 4 != 0) {
                    return false;
                }
            }
            return true;
        } else {
            // For odd n, we need exactly one center (odd count)
            // and at most n-1 pairs for the cross structure
            int singleCounts = 0;
            int pairCounts = 0;
            for (int i = 0; i <= maxColor; i++) {
                if (counts[i] == 0) continue;
                if (counts[i] % 4 == 0) {
                    // Contributes only to quadruplets
                } else if (counts[i] % 2 == 0) {
                    pairCounts++;
                } else {
                    if (counts[i] % 4 == 3) {
                        pairCounts++;
                    }
                    singleCounts++;
                }
            }
            return singleCounts <= 1 && pairCounts <= n - 1;
        }
    }

    /**
     * Fills the grid with colors following the concentric square and cross pattern.
     */
    private static void constructGrid(int n, int[] counts, int maxColor, int[][] grid) {
        int row = 0;
        int col = 0;

        if (n % 2 != 0) {
            // 1. Fill the center cell
            for (int i = 0; i <= maxColor; i++) {
                if (counts[i] % 2 != 0) {
                    grid[n / 2][n / 2] = i;
                    counts[i]--;
                    break;
                }
            }

            // 2. Fill the horizontal cross through the center
            col = 0;
            for (int i = 1; i <= maxColor; i++) {
                if (counts[i] % 4 == 2) {
                    grid[n / 2][col] = i;
                    grid[n / 2][n - col - 1] = i;
                    col++;
                    counts[i] -= 2;
                    if (col == n / 2) break;
                }
            }
            if (col != n / 2) {
                for (int i = 1; i <= maxColor; i++) {
                    while (counts[i] > 0) {
                        grid[n / 2][col] = i;
                        grid[n / 2][n - col - 1] = i;
                        col++;
                        counts[i] -= 2;
                        if (col == n / 2) break;
                    }
                    if (col == n / 2) break;
                }
            }

            // 3. Fill the vertical cross through the center
            row = 0;
            for (int i = 1; i <= maxColor; i++) {
                if (counts[i] % 4 == 2) {
                    grid[row][n / 2] = i;
                    grid[n - row - 1][n / 2] = i;
                    row++;
                    counts[i] -= 2;
                    if (row == n / 2) break;
                }
            }
            if (row != n / 2) {
                for (int i = 1; i <= maxColor; i++) {
                    while (counts[i] > 0) {
                        grid[row][n / 2] = i;
                        grid[n - row - 1][n / 2] = i;
                        row++;
                        counts[i] -= 2;
                        if (row == n / 2) break;
                    }
                    if (row == n / 2) break;
                }
            }

            // 4. Fill remaining concentric squares
            row = 0;
            col = 0;
            for (int i = 1; i <= maxColor; i++) {
                while (counts[i] > 0) {
                    grid[row][col] = i;
                    grid[n - row - 1][col] = i;
                    grid[row][n - col - 1] = i;
                    grid[n - row - 1][n - col - 1] = i;
                    row++;
                    counts[i] -= 4;
                    if (row == n / 2) {
                        row = 0;
                        col++;
                    }
                }
            }
        } else {
            // Even case: fill concentric squares from outside in
            for (int i = 1; i <= maxColor; i++) {
                while (counts[i] > 0) {
                    grid[row][col] = i;
                    grid[n - row - 1][col] = i;
                    grid[row][n - col - 1] = i;
                    grid[n - row - 1][n - col - 1] = i;
                    row++;
                    counts[i] -= 4;
                    if (row == n / 2) {
                        row = 0;
                        col++;
                    }
                }
            }
        }
    }
}

import java.io.*;
import java.util.*;

public class Solution {
    public static void main(String[] args) {
        FastReader reader = new FastReader();
        int n = reader.nextInt();

        // Count frequencies of each number
        Map<Integer, Integer> frequencyMap = new HashMap<>();
        int totalElements = n * n;
        for (int i = 0; i < totalElements; i++) {
            int num = reader.nextInt();
            frequencyMap.merge(num, 1, Integer::sum);
        }

        // Priority queue to process numbers with highest frequencies first
        PriorityQueue<ElementFrequency> pq = new PriorityQueue<>(
            Comparator.comparingInt(ElementFrequency::getFreq).reversed()
        );
        for (Map.Entry<Integer, Integer> entry : frequencyMap.entrySet()) {
            pq.add(new ElementFrequency(entry.getKey(), entry.getValue()));
        }

        int[][] matrix = new int[n][n];
        if (solve(n, pq, matrix)) {
            printMatrix(matrix);
        } else {
            System.out.println("NO");
        }
    }

    /**
     * Fills the matrix according to symmetric position requirements.
     * Returns false if there aren't enough elements to satisfy the constraints.
     */
    private static boolean solve(int n, PriorityQueue<ElementFrequency> pq, int[][] matrix) {
        // Fill four symmetric positions for each concentric square layer
        for (int j = 0; j < n / 2; j++) {
            for (int k = 0; k < n / 2; k++) {
                ElementFrequency elem = pollAndDecrement(pq, 4);
                if (elem == null) return false;

                matrix[j][k] = elem.num;
                matrix[n - 1 - j][k] = elem.num;
                matrix[n - 1 - j][n - 1 - k] = elem.num;
                matrix[j][n - 1 - k] = elem.num;
            }
        }

        if (n % 2 == 0) return true;

        // Fill two symmetric positions for the middle column
        for (int i = 0; i < n / 2; i++) {
            ElementFrequency elem = pollAndDecrement(pq, 2);
            if (elem == null) return false;

            matrix[i][n / 2] = elem.num;
            matrix[n - 1 - i][n / 2] = elem.num;
        }

        // Fill two symmetric positions for the middle row
        for (int i = 0; i < n / 2; i++) {
            ElementFrequency elem = pollAndDecrement(pq, 2);
            if (elem == null) return false;

            matrix[n / 2][i] = elem.num;
            matrix[n / 2][n - 1 - i] = elem.num;
        }

        // Fill the center position
        ElementFrequency elem = pollAndDecrement(pq, 1);
        if (elem == null) return false;

        matrix[n / 2][n / 2] = elem.num;
        return true;
    }

    /**
     * Safely extracts an element from the priority queue, checks if it has enough frequency,
     * decrements it, and re-inserts if remaining frequency is positive.
     */
    private static ElementFrequency pollAndDecrement(PriorityQueue<ElementFrequency> pq, int count) {
        ElementFrequency elem = pq.poll();
        if (elem == null || elem.getFreq() < count) {
            return null;
        }
        int remainingFreq = elem.getFreq() - count;
        if (remainingFreq > 0) {
            pq.add(new ElementFrequency(elem.num, remainingFreq));
        }
        return elem;
    }

    private static void printMatrix(int[][] matrix) {
        System.out.println("YES");
        for (int[] row : matrix) {
            for (int val : row) {
                System.out.print(val + " ");
            }
            System.out.println();
        }
    }

    /**
     * Represents a number and its remaining frequency count.
     */
    private static class ElementFrequency {
        private final int num;
        private int freq;

        ElementFrequency(int num, int freq) {
            this.num = num;
            this.freq = freq;
        }

        int getNum() { return num; }
        int getFreq() { return freq; }
        void setFreq(int freq) { this.freq = freq; }
    }

    /**
     * Fast I/O helper for competitive programming scenarios.
     */
    static class FastReader {
        BufferedReader br;
        StringTokenizer st;

        public FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        long nextLong() {
            return Long.parseLong(next());
        }

        double nextDouble() {
            return Double.parseDouble(next());
        }

        String nextLine() {
            String str = "";
            try {
