import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.OutputStream;
import java.io.PrintWriter;
import java.util.HashMap;
import java.util.Map;
import java.util.PriorityQueue;
import java.util.StringTokenizer;

public class Main {
    public static void main(String[] args) {
        solve(System.in, System.out);
    }

    private static void solve(InputStream input, OutputStream output) {
        ReaderFastIO in = new ReaderFastIO(input);
        PrintWriter out = new PrintWriter(output);
        PalindromicMatrixSolver solver = new PalindromicMatrixSolver();
        solver.solve(in, out);
        out.flush();
        out.close();
    }

    static class PalindromicMatrixSolver {
        private int[][] matrix;
        private PriorityQueue<FrequencyEntry> queue;

        public void solve(ReaderFastIO in, PrintWriter out) {
            int n = in.nextInt();
            matrix = new int[n][n];
            Map<Integer, Integer> frequencyMap = new HashMap<>();

            for (int i = 0; i < n * n; i++) {
                int val = in.nextInt();
                frequencyMap.put(val, frequencyMap.getOrDefault(val, 0) + 1);
            }

            // Sort by frequency descending
            queue = new PriorityQueue<>((a, b) -> Integer.compare(b.count, a.count));
            for (Map.Entry<Integer, Integer> entry : frequencyMap.entrySet()) {
                queue.offer(new FrequencyEntry(entry.getValue(), entry.getKey()));
            }

            boolean possible = true;

            // Fill symmetric 2x2 blocks
            for (int i = 0; i < n / 2; i++) {
                for (int j = 0; j < n / 2; j++) {
                    if (!fill(new int[][]{
                            {i, j}, {i, n - 1 - j}, {n - 1 - i, j}, {n - 1 - i, n - 1 - j}
                    })) {
                        possible = false;
                        break;
                    }
                }
                if (!possible) break;
            }

            if (possible && n % 2 == 1) {
                int mid = n / 2;

                // Fill vertical middle column (excluding center)
                for (int i = 0; i < mid; i++) {
                    if (!fill(new int[][]{{i, mid}, {n - 1 - i, mid}})) {
                        possible = false;
                        break;
                    }
                }

                // Fill horizontal middle row (excluding center)
                if (possible) {
                    for (int i = 0; i < mid; i++) {
                        if (!fill(new int[][]{{mid, i}, {mid, n - 1 - i}})) {
                            possible = false;
                            break;
                        }
                    }
                }

                // Fill center element
                if (possible) {
                    if (!fill(new int[][]{{mid, mid}})) {
                        possible = false;
                    }
                }
            }

            if (!possible) {
                out.println("NO");
            } else {
                out.println("YES");
                print(matrix, out);
            }
        }

        private boolean fill(int[][] coords) {
            if (queue.isEmpty()) return false;
            FrequencyEntry entry = queue.poll();
            int required = coords.length;

            if (entry.count < required) {
                return false;
            }

            for (int[] coord : coords) {
                matrix[coord[0]][coord[1]] = entry.value;
            }

            int remaining = entry.count - required;
            if (remaining > 0) {
                queue.offer(new FrequencyEntry(remaining, entry.value));
            }

            return true;
        }

        private void print(int[][] matrix, PrintWriter out) {
            for (int i = 0; i < matrix.length; i++) {
                for (int j = 0; j < matrix[i].length; j++) {
                    out.print(matrix[i][j] + (j == matrix[i].length - 1 ? "" : " "));
                }
                out.println();
            }
        }

        private static class FrequencyEntry implements Comparable<FrequencyEntry> {
            final int count;
            final int value;

            FrequencyEntry(int count, int value) {
                this.count = count;
                this.value = value;
            }

            @Override
            public int compareTo(FrequencyEntry other) {
                return Integer.compare(other.count, this.count);
            }
        }
    }

    static class ReaderFastIO {
        private final BufferedReader br;
        private StringTokenizer st;

        public ReaderFastIO(InputStream input) {
            br = new BufferedReader(new InputStreamReader(input));
        }

        public String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            String s = next();
            if (s == null) throw new RuntimeException("Unexpected end of input");
            return Integer.parseInt(s);
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

/**
 * Constructs an n x n matrix where numbers appear in symmetric patterns:
 * - 4 times for corner/edge positions
 * - 2 times for middle row/column positions (if n is odd)
 * - 1 time for the center (if n is odd)
 * 
 * Refactored for maintainability, performance, and readability.
 */
public class MatrixFiller {

    /** Maximum expected value based on original constraint. */
    private static final int MAX_VALUE = 1010;

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out);

        String nStr = scanner.next();
        if (nStr == null) {
            out.flush();
            return;
        }
        int n = Integer.parseInt(nStr);

        // Frequency array to track available counts for each number
        int[] valueCounts = new int[MAX_VALUE];
        int firstValue = 0;
        int totalElements = n * n;

        // Read input and populate frequency map
        for (int i = 0; i < totalElements; i++) {
            int val = scanner.nextInt();
            if (i == 0) firstValue = val;
            if (val >= 0 && val < MAX_VALUE) {
                valueCounts[val]++;
            }
        }

        // Handle trivial case
        if (n == 1) {
            out.println("YES");
            out.println(firstValue);
            out.flush();
            return;
        }

        int[][] matrix = new int[n][n];

        // 1. Fill the 4 symmetric positions for each layer
        int bottomOffset = n - 1;
        for (int i = 0; i < n / 2; i++, bottomOffset -= 2) {
            int rightOffset = n - 1;
            for (int j = 0; j < n / 2; j++, rightOffset -= 2) {
                int selectedValue = findValueWithMinimumCount(valueCounts, 4);
                if (selectedValue == -1) {
                    out.println("NO");
                    out.flush();
                    return;
                }
                matrix[i][j] = selectedValue;
                matrix[i][j + rightOffset] = selectedValue;
                matrix[i + bottomOffset][j] = selectedValue;
                matrix[i + bottomOffset][j + rightOffset] = selectedValue;
                valueCounts[selectedValue] -= 4;
            }
        }

        // 2. Handle middle row and column if n is odd
        if (n % 2 != 0) {
            int mid = n / 2;

            // Fill middle row symmetrically
            int rowOffset = n - 1;
            for (int i = 0; i < n / 2; i++, rowOffset -= 2) {
                int selectedValue = findValueWithMinimumCount(valueCounts, 2);
                if (selectedValue == -1) {
                    out.println("NO");
                    out.flush();
                    return;
                }
                matrix[mid][i] = selectedValue;
                matrix[mid][i + rowOffset] = selectedValue;
                valueCounts[selectedValue] -= 2;
            }

            // Fill middle column symmetrically
            int colOffset = n - 1;
            for (int i = 0; i < n / 2; i++, colOffset -= 2) {
                int selectedValue = findValueWithMinimumCount(valueCounts, 2);
                if (selectedValue == -1) {
                    out.println("NO");
                    out.flush();
                    return;
                }
                matrix[i][mid] = selectedValue;
                matrix[i + colOffset][mid] = selectedValue;
                valueCounts[selectedValue] -= 2;
            }

            // Fill center element
            int centerValue = findValueWithMinimumCount(valueCounts, 1);
            if (centerValue == -1) {
                out.println("NO");
                out.flush();
                return;
            }
            matrix[mid][mid] = centerValue;
        }

        // Output result
        out.println("YES");
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                out.print(matrix[i][j]);
                out.print(j == n - 1 ? "" : " ");
            }
            out.println();
        }
        out.flush();
    }

    /**
     * Finds the smallest number that has at least 'required' occurrences remaining.
     *
     * @param counts   Array tracking remaining counts of each number
     * @param required Minimum occurrences needed
     * @return The number satisfying the condition, or -1 if none exists
     */
    private static int findValueWithMinimumCount(int[] counts, int required) {
        for (int i = 1; i < counts.length; i++) {
            if (counts[i] >= required) {
                return i;
            }
        }
        return -1;
    }

    /**
     * Fast input reader for competitive programming / large I/O scenarios.
     */
    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner(InputStream stream) {
            br = new BufferedReader(new InputStreamReader(stream));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Input stream error", e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            String s = next();
            return s == null ? 0 : Integer.parseInt(s);
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.StringTokenizer;

public class CR540 {

    /**
     * Fast I/O helper class optimized for competitive programming.
     */
    static class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) {
                        throw new RuntimeException("Unexpected End of Input");
                    }
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("I/O Error", e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        long nextLong() {
            return Long.parseLong(next());
        }

        double nextDouble() {
            return Double.parseDouble(next());
        }

        String nextLine() {
            String str = "";
            try {
                str = br.readLine();
            } catch (IOException e) {
                throw new RuntimeException("I/O Error", e);
            }
            return str;
        }
    }

    public static void main(String[] args) {
        FastReader sc = new FastReader();
        int n;
        try {
            n = sc.nextInt();
        } catch (Exception e) {
            return; // Graceful exit on empty/invalid input
        }

        // Handle trivial case n = 1
        if (n == 1) {
            int t = sc.nextInt();
            System.out.println("YES");
            System.out.println(t);
            return;
        }

        // Read input and compute frequencies
        Map<Integer, Integer> frequencyMap = new HashMap<>();
        int totalElements = n * n;
        for (int i = 0; i < totalElements; i++) {
            int value = sc.nextInt();
            frequencyMap.merge(value, 1, Integer::sum);
        }

        int[][] grid = new int[n][n];

        // Solve and print result
        if (solve(n, frequencyMap, grid)) {
            System.out.println("YES");
            printGrid(grid);
        } else {
            System.out.println("NO");
        }
    }

    /**
     * Dispatches to the appropriate solver based on grid parity.
     */
    private static boolean solve(int n, Map<Integer, Integer> frequencyMap, int[][] grid) {
        return n % 2 == 0 ? solveEven(n, frequencyMap, grid) : solveOdd(n, frequencyMap, grid);
    }

    /**
     * Solves for even-sized grids. Every number's frequency must be divisible by 4.
     */
    private static boolean solveEven(int n, Map<Integer, Integer> frequencyMap, int[][] grid) {
        // Validate frequencies
        for (int count : frequencyMap.values()) {
            if (count % 4 != 0) {
                return false;
            }
        }

        // Build a flat list of values to assign (each value appears count/4 times)
        List<Integer> values = new ArrayList<>();
        for (Map.Entry<Integer, Integer> entry : frequencyMap.entrySet()) {
            int count = entry.getValue() / 4;
            for (int i = 0; i < count; i++) {
                values.add(entry.getKey());
            }
        }

        // Fill quadrants symmetrically
        int idx = 0;
        int half = n / 2;
        for (int i = 0; i < half; i++) {
            for (int j = 0; j < half; j++) {
                int val = values.get(idx++);
                setSymmetric(grid, i, j, n, val);
            }
        }
        return true;
    }

    /**
     * Solves for odd-sized grids. Greedily assigns groups of 4, then 2, then 1.
     */
    private static boolean solveOdd(int n, Map<Integer, Integer> frequencyMap, int[][] grid) {
        int half = n / 2;
        // Use a mutable list of entries to safely decrement counts during iteration
        List<Map.Entry<Integer, Integer>> entries = new ArrayList<>(frequencyMap.entrySet());

        // Phase 1: Fill 4-symmetric corner quadrants
        for (int i = 0; i < half; i++) {
            for (int j = 0; j < half; j++) {
                if (!assignGroup(entries, 4, (val) -> setSymmetric(grid, i, j, n, val))) {
                    return false;
                }
            }
        }

        // Phase 2: Fill middle row pairs (excluding center)
        for (int i = 0; i < half; i++) {
            if (!assignGroup(entries, 2, (val) -> {
                grid[i][half] = val;
                grid[n - 1 - i][half] = val;
            })) {
                return false;
            }
        }

        // Phase 3: Fill middle column pairs (excluding center)
        for (int j = 0; j < half; j++) {
            if (!assignGroup(entries, 2, (val) -> {
                grid[half][j] = val;
                grid[half][n - 1 - j] = val;
            })) {
                return false;
            }
        }

        // Phase 4: Fill center element
        return assignGroup(entries, 1, (val) -> grid[half][half] = val);
    }

    /**
     * Helper lambda interface for grid assignment actions.
     */
    @FunctionalInterface
    private interface GridAssignAction {
        void apply(int value);
    }

    /**
     * Finds a value with at least 'requiredCount' remaining, assigns it, and decrements its count.
     */
    private static boolean assignGroup(List<Map.Entry<Integer, Integer>> entries, int requiredCount, GridAssignAction action) {
        for (Map.Entry<Integer, Integer> entry : entries) {
            if (entry.getValue() >= requiredCount) {
                action.apply(entry.getKey());
                entry.setValue(entry.getValue() - requiredCount);
                return true;
            }
        }
        return false;
    }

    /**
     * Sets all four symmetric positions in the grid to the given value.
     */
    private static void setSymmetric(int[][] grid, int i, int j, int n, int value) {
        grid[i][j] = value;
        grid[i][n - 1 - j] = value;
        grid[n - 1 - i][j] = value;
        grid[n - 1 - i][n - 1 - j] = value;
    }

    /**
     * Prints the grid efficiently using StringBuilder.
     */
    private static void printGrid(int[][] grid) {
        StringBuilder sb = new StringBuilder();
        for (int[] row : grid) {
            for (int val : row) {
                sb.append(val).append(' ');
            }
            sb.append('\n');
        }
        System.out.print(sb);
    }
}

import java.io.*;
import java.util.*;

/**
 * Refactored version of the original Task class.
 * Improves maintainability by:
 * - Removing unused fields and inner classes
 * - Extracting constants and magic numbers
 * - Improving resource management with try-with-resources
 * - Extracting repetitive logic into helper methods
 * - Fixing a logical bug where the center cell was overwritten for even-sized grids
 * - Using descriptive naming and consistent formatting
 */
public class SymmetricGridBuilder implements AutoCloseable {

    private static final int MAX_VALUE_LIMIT = 1010;

    private PrintWriter out;
    private FastScanner in;

    public SymmetricGridBuilder() {
        try {
            in = new FastScanner("input.txt");
            out = new PrintWriter(new BufferedWriter(new FileWriter("output.txt")));
        } catch (IOException e) {
            // Fallback to standard I/O if file I/O fails
            in = new FastScanner(System.in);
            out = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)));
        }
    }

    public static void main(String[] args) {
        try (SymmetricGridBuilder builder = new SymmetricGridBuilder()) {
            builder.run();
        } catch (IOException e) {
            System.err.println("I/O Error: " + e.getMessage());
        }
    }

    private void run() throws IOException {
        int testCases = 1; // Original hardcoded to 1; easily extensible
        while (testCases-- > 0) {
            solve();
        }
        out.flush();
    }

    private void solve() throws IOException {
        int n = in.nextInt();
        int[] counts = new int[MAX_VALUE_LIMIT];
        int totalElements = n * n;

        for (int i = 0; i < totalElements; i++) {
            counts[in.nextInt()]++;
        }

        int[][] grid = new int[n][n];
        int currentVal = 1;

        // 1. Fill 4-way symmetric quadrants
        for (int i = 0; i < n / 2; i++) {
            for (int j = 0; j < n / 2; j++) {
                if (grid[i][j] == 0) {
                    currentVal = findNextAvailable(counts, currentVal, 4);
                    if (currentVal == -1) {
                        out.println("NO");
                        return;
                    }
                    counts[currentVal] -= 4;
                    grid[i][j] = currentVal;
                    grid[n - i - 1][j] = currentVal;
                    grid[i][n - j - 1] = currentVal;
                    grid[n - i - 1][n - j - 1] = currentVal;
                }
            }
        }

        // 2. Fill 2-way symmetric middle row/col if n is odd
        if (n % 2 == 1) {
            currentVal = 1; // Reset search pointer as per original logic
            int mid = n / 2;

            // Middle column (excluding center)
            for (int i = 0; i < n / 2; i++) {
                currentVal = findNextAvailable(counts, currentVal, 2);
                if (currentVal == -1) {
                    out.println("NO");
                    return;
                }
                counts[currentVal] -= 2;
                grid[i][mid] = currentVal;
                grid[n - i - 1][mid] = currentVal;
            }

            // Middle row (excluding center)
            for (int i = 0; i < n / 2; i++) {
                currentVal = findNextAvailable(counts, currentVal, 2);
                if (currentVal == -1) {
                    out.println("NO");
                    return;
                }
                counts[currentVal] -= 2;
                grid[mid][i] = currentVal;
                grid[mid][n - i - 1] = currentVal;
            }

            // Center element (must have exactly 1 remaining count)
            int centerVal = -1;
            for (int i = 1; i < counts.length; i++) {
                if (counts[i] == 1) {
                    centerVal = i;
                    break;
                }
            }
            if (centerVal == -1) {
                out.println("NO");
                return;
            }
            grid[mid][mid] = centerVal;
        }

        out.println("Yes");
        for (int[] row : grid) {
            for (int val : row) {
                out.print(val + " ");
            }
            out.println();
        }
    }

    /**
     * Finds the next available number in the counts array that has at least the required frequency.
     *
     * @param counts    Array of frequencies
     * @param start     Index to start searching from
     * @param required  Minimum frequency needed
     * @return          The number (index) if found, -1 otherwise
     */
    private int findNextAvailable(int[] counts, int start, int required) {
        for (int i = start; i < counts.length; i++) {
            if (counts[i] >= required) {
                return i;
            }
        }
        return -1;
    }

    @Override
    public void close() throws IOException {
        if (out != null) {
            out.flush();
            out.close();
        }
    }

    /**
     * Fast I/O helper class optimized for competitive programming style inputs.
     */
    private static class FastScanner {
        private BufferedReader br;
        private StringTokenizer st;

        public FastScanner(String filePath) throws IOException {
            br = new BufferedReader(new FileReader(filePath));
        }

        public FastScanner(InputStream inputStream) {
            br = new BufferedReader(new InputStreamReader(inputStream));
        }

        public String next() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) {
                    throw new EOFException("End of input reached unexpectedly.");
                }
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Constructs a symmetric n x n matrix where elements are placed in 
 * 4-way symmetric quadrants, 2-way symmetric cross segments, or a single center cell.
 */
public class GridBuilder {
    private static final int MAX_VALUE = 1000;
    private static final PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out));

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner();
        // Read number of test cases
        int t = scanner.nextInt();
        while (t-- > 0) {
            solve(scanner);
        }
        out.flush();
        out.close();
    }

    private static void solve(FastScanner scanner) {
        int n = scanner.nextInt();
        int[] counts = new int[MAX_VALUE + 1];
        int totalElements = n * n;

        // Count frequencies directly while reading input
        for (int i = 0; i < totalElements; i++) {
            counts[scanner.nextInt()]++;
        }

        Queue<Integer> singles = new ArrayDeque<>();
        Queue<Integer> pairs = new ArrayDeque<>();
        Queue<Integer> quads = new ArrayDeque<>();
        distributeCounts(counts, singles, pairs, quads);

        if (!validateConstraints(n, singles, pairs, quads)) {
            out.println("NO");
            return;
        }

        int[][] matrix = constructMatrix(n, singles, pairs, quads);
        out.println("YES");
        printMatrix(matrix, n);
    }

    /**
     * Distributes counted values into singles, pairs, and quads based on frequency.
     */
    private static void distributeCounts(int[] counts, Queue<Integer> singles, Queue<Integer> pairs, Queue<Integer> quads) {
        for (int val = 1; val <= MAX_VALUE; val++) {
            int count = counts[val];
            while (count >= 4) {
                quads.offer(val);
                count -= 4;
            }
            if (count >= 2) {
                pairs.offer(val);
                count -= 2;
            }
            if (count == 1) {
                singles.offer(val);
            }
        }
    }

    /**
     * Validates if the available counts can form a valid symmetric matrix for size n.
     */
    private static boolean validateConstraints(int n, Queue<Integer> singles, Queue<Integer> pairs, Queue<Integer> quads) {
        if (n % 2 == 0) {
            // Even n: all cells must be fillable by quads. No singles or pairs allowed.
            return singles.isEmpty() && pairs.isEmpty();
        } else {
            // Odd n: exactly one single for the center, and at most n-1 pairs for the cross arms.
            return singles.size() == 1 && pairs.size() <= n - 1;
        }
    }

    /**
     * Constructs the symmetric matrix using the distributed queues.
     */
    private static int[][] constructMatrix(int n, Queue<Integer> singles, Queue<Integer> pairs, Queue<Integer> quads) {
        int[][] mat = new int[n][n];

        if (n % 2 == 0) {
            // Even case: fill all quadrants with quads
            for (int i = 0; i < n / 2; i++) {
                for (int j = 0; j < n / 2; j++) {
                    fillQuadrant(mat, n, i, j, quads.poll());
                }
            }
        } else {
            // Odd case: place single at center
            mat[n / 2][n / 2] = singles.poll();

            // Convert quads to pairs if we lack enough pairs for the cross edges
            while (pairs.size() < n - 1) {
                int val = quads.poll();
                pairs.offer(val);
                pairs.offer(val);
            }

            // Fill top and bottom middle columns
            for (int i = 0; i < n / 2; i++) {
                int val = pairs.poll();
                mat[i][n / 2] = mat[n - i - 1][n / 2] = val;
            }

            // Fill left and right middle rows
            for (int i = 0; i < n / 2; i++) {
                int val = pairs.poll();
                mat[n / 2][i] = mat[n / 2][n - i - 1] = val;
            }

            // Fill the four quadrants
            for (int i = 0; i < n / 2; i++) {
                for (int j = 0; j < n / 2; j++) {
                    fillQuadrant(mat, n, i, j, quads.poll());
                }
            }
        }
        return mat;
    }

    /**
     * Places a value in all four symmetric positions of a quadrant.
     */
    private static void fillQuadrant(int[][] mat, int n, int i, int j, int val) {
        mat[i][j] = mat[n - i - 1][j] = mat[i][n - j - 1] = mat[n - i - 1][n - j - 1] = val;
    }

    /**
     * Prints the constructed matrix row by row.
     */
    private static void printMatrix(int[][] mat, int n) {
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                out.print(mat[i][j]).print(' ');
            }
            out.println();
        }
    }

    /**
     * High-performance input scanner for competitive programming.
     */
    private static class FastScanner {
        private final BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        private StringTokenizer st = new StringTokenizer("");

        String next() {
            while (!st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            String s = next();
            if (s == null) throw new NoSuchElementException();
            return Integer.parseInt(s);
        }
    }
}

import java.util.Scanner;

/**
 * A program to construct a specific n x n matrix based on input frequencies.
 * The matrix is filled symmetrically:
 * - Groups of 4 elements fill the four corners of sub-squares.
 * - Groups of 2 elements fill the middle row and column.
 * - Single elements fill the center (if n is odd).
 */
public class MatrixGenerator {

    // Maximum value for input numbers based on original array size
    private static final int MAX_VALUE = 1001;

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        // Read n
        if (!scanner.hasNextInt()) {
            scanner.close();
            return;
        }
        int n = scanner.nextInt();

        // Frequency array to count occurrences of each number
        int[] frequencyCounts = new int[MAX_VALUE];

        // Read n*n integers and update frequencies
        for (int i = 0; i < n * n; i++) {
            if (scanner.hasNextInt()) {
                int val = scanner.nextInt();
                // Ensure we don't go out of bounds, though problem constraints likely guarantee val < 1001
                if (val >= 0 && val < MAX_VALUE) {
                    frequencyCounts[val]++;
                }
            }
        }

        // Analyze counts to determine how many groups of 4, 2, and 1 we have
        int quadCount = 0; // Groups of 4
        int pairCount = 0; // Groups of 2
        int singleCount = 0; // Groups of 1 (singles)

        for (int count : frequencyCounts) {
            quadCount += count / 4;
            pairCount += (count % 4) / 2;
            singleCount += count % 2;
        }

        // Validate if the matrix can be constructed according to the rules
        if (isValid(n, quadCount, pairCount, singleCount)) {
            System.out.println("YES");
            int[][] matrix = buildMatrix(n, frequencyCounts);
            printMatrix(matrix);
        } else {
            System.out.println("NO");
        }

        scanner.close();
    }

    /**
     * Checks if the counts allow for a valid matrix construction.
     */
    private static boolean isValid(int n, int quadCount, int pairCount, int singleCount) {
        if (n % 2 != 0) {
            // Odd dimension: Center cell exists.
            // We can have at most 1 single (for the center).
            // The number of pairs is limited by the available slots in the cross arms.
            // Original logic: pairCount > (n - 1) is invalid.
            if (singleCount > 1 || pairCount > (n - 1)) {
                return false;
            }
        } else {
            // Even dimension: No center cell.
            // No singles allowed.
            // No pairs allowed (based on original logic check).
            if (singleCount != 0 || pairCount != 0) {
                return false;
            }
        }
        return true;
    }

    /**
     * Constructs the n x n matrix based on the frequency counts.
     */
    private static int[][] buildMatrix(int n, int[] frequencyCounts) {
        int[][] matrix = new int[n][n];
        int halfN = n / 2;

        // Cursors for filling the matrix
        // 4s fill the 4 symmetric corners of the top-left quadrant
        int quadR = 0;
        int quadC = 0;

        // 2s fill the middle row and middle column (the cross)
        // We track progress in the column first, then the row
        int crossColOffset = 0;
        int crossRowOffset = 0;
        boolean fillingColumn = true;

        // Iterate through all possible numbers
        for (int val = 0; val < MAX_VALUE; val++) {
            int count = frequencyCounts[val];

            // Fill groups of 4
            while (count >= 4) {
                if (quadR < halfN && quadC < halfN) {
                    // Fill 4 symmetric positions
                    matrix[quadR][quadC] = val;
                    matrix[n - 1 - quadR][quadC] = val;
                    matrix[quadR][n - 1 - quadC] = val;
                    matrix[n - 1 - quadR][n - 1 - quadC] = val;

                    // Advance cursor (row-major order in top-left quadrant)
                    quadC++;
                    if (quadC == halfN) {
                        quadC = 0;
                        quadR++;
                    }
                } else {
                    break; // No more space for 4s
                }
                count -= 4;
            }

            // Fill groups of 2
            while (count >= 2) {
                if (fillingColumn) {
                    if (crossColOffset < halfN) {
                        int r = crossColOffset;
                        int c = halfN; // Middle column index
                        matrix[r][c] = val;
                        matrix[n - 1 - r][c] = val;
                        crossColOffset++;
                    } else {
                        // Switch to filling the row
                        fillingColumn = false;
                        crossRowOffset = 0;
                    }
                } else {
                    if (crossRowOffset < halfN) {
                        int r = halfN; // Middle row index
                        int c = crossRowOffset;
                        matrix[r][c] = val;
                        matrix[r][n - 1 - c] = val;
                        crossRowOffset++;
                    } else {
                        break; // No more space for 2s
                    }
                }
                count -= 2;
            }

            // Fill single element (center)
            if (count > 0) {
                matrix[halfN][halfN] = val;
                count = 0; // Consumed
            }
        }
        return matrix;
    }

    /**
     * Prints the matrix to the console.
     */
    private static void printMatrix(int[][] matrix) {
        StringBuilder sb = new StringBuilder();
        for (int[] row : matrix) {
            for (int val : row) {
                sb.append(val).append(" ");
            }
            sb.append("\n");
        }
        System.out.print(sb);
    }
}

import java.util.*;

public class Test {

    private static final int MAX_VALUE = 1005;

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        if (!scanner.hasNextInt()) {
            return;
        }
        int n = scanner.nextInt();

        int[] frequencies = readAndCountFrequencies(n, scanner);
        scanner.close();

        int[][] grid = new int[n][n];
        boolean isValid = true;

        if (n % 2 == 0) {
            List<Integer> quadrantValues = distributeForEvenCase(n, frequencies);
            isValid = quadrantValues != null;
            if (isValid) {
                fillQuadrants(grid, n, quadrantValues);
            }
        } else {
            OddCaseDistribution result = distributeForOddCase(n, frequencies);
            isValid = result != null;
            if (isValid) {
                grid[n / 2][n / 2] = result.centerValue();
                fillEdges(grid, n, result.edgeValues());
                fillQuadrants(grid, n, result.quadrantValues());
            }
        }

        if (isValid) {
            System.out.println("YES");
            printGrid(grid);
        } else {
            System.out.println("NO");
        }
    }

    /**
     * Reads n*n integers and counts their frequencies.
     */
    private static int[] readAndCountFrequencies(int n, Scanner scanner) {
        int[] freq = new int[MAX_VALUE];
        for (int i = 0; i < n * n; i++) {
            if (!scanner.hasNextInt()) break;
            int val = scanner.nextInt();
            if (val < 0 || val >= freq.length) {
                throw new IllegalArgumentException("Value out of expected range [0, " + (MAX_VALUE - 1) + "]");
            }
            freq[val]++;
        }
        return freq;
    }

    /**
     * Validates and extracts values for the even-sized grid case.
     * Every number must appear a multiple of 4 times.
     */
    private static List<Integer> distributeForEvenCase(int n, int[] frequencies) {
        List<Integer> quadrantValues = new ArrayList<>();
        for (int val = 0; val < frequencies.length; val++) {
            if (frequencies[val] % 4 != 0) {
                return null; // Invalid configuration
            }
            int count = frequencies[val] / 4;
            for (int k = 0; k < count; k++) {
                quadrantValues.add(val);
            }
        }
        return quadrantValues;
    }

    /**
     * Validates and extracts values for the odd-sized grid case.
     * Requires: (n-1)^2/4 groups of 4, (n-1) groups of 2, and exactly 1 single.
     */
    private static OddCaseDistribution distributeForOddCase(int n, int[] frequencies) {
        List<Integer> quadrantValues = new ArrayList<>();
        List<Integer> edgeValues = new ArrayList<>();
        int centerValue = -1;

        int neededQuadrants = (n * n - 2 * n + 1) / 4;
        int neededEdges = n - 1;
        int neededCenter = 1;

        // Work on a copy to avoid side effects
        int[] remaining = Arrays.copyOf(frequencies, frequencies.length);

        // 1. Fill quadrants (need multiples of 4)
        for (int val = 0; val < remaining.length && neededQuadrants > 0; val++) {
            int count = remaining[val];
            int groups = count / 4;
            for (int k = 0; k < groups && neededQuadrants > 0; k++) {
                quadrantValues.add(val);
                neededQuadrants--;
                remaining[val] -= 4;
            }
        }
        if (neededQuadrants != 0) return null;

        // 2. Fill middle edges (need multiples of 2)
        for (int val = 0; val < remaining.length && neededEdges > 0; val++) {
            int count = remaining[val];
            int groups = count / 2;
            for (int k = 0; k < groups && neededEdges > 0; k++) {
                edgeValues.add(val);
                neededEdges--;
                remaining[val] -= 2;
            }
        }
        if (neededEdges != 0) return null;

        // 3. Fill center (need exactly 1)
        for (int val = 0; val < remaining.length && neededCenter > 0; val++) {
            if (remaining[val] == 1) {
                centerValue = val;
                neededCenter--;
            }
        }
        if (neededCenter != 0) return null;

        return new OddCaseDistribution(quadrantValues, edgeValues, centerValue);
    }

    /**
     * Fills the four symmetric quadrants of the grid.
     */
    private static void fillQuadrants(int[][] grid, int n, List<Integer> values) {
        int idx = 0;
        int half = n / 2;
        for (int i = 0; i < half; i++) {
            for (int j = 0; j < half; j++) {
                int val = values.get(idx++);
                grid[i][j] = val;
                grid[n - 1 - i][j] = val;
                grid[i][n - 1 - j] = val;
                grid[n - 1 - i][n - 1 - j] = val;
            }
        }
    }

    /**
     * Fills the middle row and column arms for odd-sized grids.
     */
    private static void fillEdges(int[][] grid, int n, List<Integer> edgeValues) {
        int mid = n / 2;
        for (int i = 0; i < edgeValues.size(); i++) {
            int val = edgeValues.get(i);
            if (i < mid) {
                // Top and bottom middle cells
                grid[i][mid] = val;
                grid[n - 1 - i][mid] = val;
            } else {
                // Left and right middle cells
                int offset = i - mid;
                grid[mid][offset] = val;
                grid[mid][n - 1 - offset] = val;
            }
        }
    }

    /**
     * Prints the grid to standard output efficiently.
     */
    private static void printGrid(int[][] grid) {
        StringBuilder sb = new StringBuilder();
        for (int[] row : grid) {
            for (int val : row) {
                sb.append(val).append(' ');
            }
            sb.append('\n');
        }
        System.out.print(sb);
    }

    /**
     * Helper class to encapsulate odd-case distribution results.
     */
    private static class OddCaseDistribution {
        private final List<Integer> quadrantValues;
        private final List<Integer> edgeValues;
        private final int centerValue;

        OddCaseDistribution(List<Integer> quadrantValues, List<Integer> edgeValues, int centerValue) {
            this.quadrantValues = quadrantValues;
            this.edgeValues = edgeValues;
            this.centerValue = centerValue;
        }

        public List<Integer> quadrantValues() { return quadrantValues; }
        public List<Integer> edgeValues() { return edgeValues; }
        public int centerValue() { return centerValue; }
    }
}

import java.io.*;
import java.util.*;

public class Exam {

    private static final char STAR = '*';
    private static final char DOT = '.';
    private static final String YES = "YES";
    private static final String NO = "NO";

    public static void main(String[] args) {
        InputReader sc = new InputReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            int n = sc.nextInt();
            int m = sc.nextInt();

            char[][] grid = new char[n][];
            for (int i = 0; i < n; i++) {
                grid[i] = sc.nextLine().toCharArray();
            }

            List<int[]> plusCenters = findPlusCenters(grid);

            if (plusCenters.size() == 1) {
                int[] center = plusCenters.get(0);
                if (hasOnlyPlusAndDots(grid, center[0], center[1])) {
                    out.println(YES);
                } else {
                    out.println(NO);
                }
            } else {
                out.println(NO);
            }
        } catch (Exception e) {
            // Gracefully handle unexpected input errors
            out.println(NO);
        } finally {
            out.flush();
            out.close();
        }
    }

    /**
     * Scans the grid and returns a list of coordinates that form the center of a '+' shape.
     */
    private static List<int[]> findPlusCenters(char[][] grid) {
        List<int[]> centers = new ArrayList<>();
        if (grid == null || grid.length == 0) {
            return centers;
        }

        int n = grid.length;
        int m = grid[0].length;

        for (int i = 1; i < n - 1; i++) {
            for (int j = 1; j < m - 1; j++) {
                if (isPlusCenter(grid, i, j)) {
                    centers.add(new int[]{i, j});
                }
            }
        }
        return centers;
    }

    /**
     * Checks if the cell at (r, c) and its immediate neighbors form a '+' shape.
     */
    private static boolean isPlusCenter(char[][] grid, int r, int c) {
        return grid[r][c] == STAR &&
               grid[r - 1][c] == STAR &&
               grid[r + 1][c] == STAR &&
               grid[r][c - 1] == STAR &&
               grid[r][c + 1] == STAR;
    }

    /**
     * Verifies that the grid contains only the '+' shape at (centerR, centerC) and dots elsewhere.
     */
    private static boolean hasOnlyPlusAndDots(char[][] grid, int centerR, int centerC) {
        int n = grid.length;
        int m = grid[0].length;

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                // Skip the 5 cells that constitute the '+' shape
                if ((i == centerR && j == centerC) ||
                    (i == centerR - 1 && j == centerC) ||
                    (i == centerR + 1 && j == centerC) ||
                    (i == centerR && j == centerC - 1) ||
                    (i == centerR && j == centerC + 1)) {
                    continue;
                }
                if (grid[i][j] == STAR) {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Fast I/O utility commonly used in competitive programming.
     */
    static class InputReader {
        private final InputStream stream;
        private final byte[] buf = new byte[8192];
        private int curChar, snumChars;
        private SpaceCharFilter filter;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        public int snext() {
            if (snumChars == -1) {
                throw new InputMismatchException();
            }
            if (curChar >= snumChars) {
                curChar = 0;
                try {
                    snumChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (snumChars <= 0) {
                    return -1;
                }
            }
            return buf[curChar++];
        }

        public int nextInt() {
            int c = snext();
            while (isSpaceChar(c)) {
                c = snext();
            }
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = snext();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                res *= 10;
                res += c - '0';
                c = snext();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public long nextLong() {
            int c = snext();
            while (isSpaceChar(c)) {
                c = snext();
            }
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = snext();
            }
            long res = 0;
            do {
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                res *= 10;
                res += c - '0';
                c = snext();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public int[] nextIntArray(int n) {
            int[] a = new int[n];
            for (int i = 0; i < n; i++) {
                a[i] = nextInt();
            }
            return a;
        }

        public String readString() {
            int c = snext();
            while (isSpaceChar(c)) {
                c = snext();
            }
            StringBuilder res = new StringBuilder();
            do {
                res.appendCodePoint(c);
                c = snext();
            } while (!isSpaceChar(c));
            return res.toString();
        }

        public String nextLine() {
            int c = snext();
            while (isSpaceChar(c)) {
                c = snext();
            }
            StringBuilder res = new StringBuilder();
            do {
                res.appendCodePoint(c);
                c = snext();
            } while (!isEndOfLine(c));
            return res.toString();
        }

        public boolean isSpaceChar(int c) {
            if (filter != null) {
                return filter.isSpaceChar(c);
            }
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        private boolean isEndOfLine(int c) {
            return c == '\n' || c == '\r' || c == -1;
        }

        public interface SpaceCharFilter {
            boolean isSpaceChar(int ch);
        }
    }
}

import java.io.*;
import java.util.StringTokenizer;

/**
 * Solves Codeforces Problem 1182B: Nastya Studies Informatics.
 * Determines if every '*' in the grid belongs to at least one cross.
 * A cross is defined as a center '*' with at least one '*' extending 
 * in all four cardinal directions (up, down, left, right).
 */
public class Codeforces1182B {

    public static void main(String[] args) {
        try (InputStream inputStream = System.in;
             PrintWriter outputStream = new PrintWriter(System.out)) {
            FastScanner in = new FastScanner(inputStream);
            solve(in, outputStream);
            outputStream.flush();
        } catch (IOException e) {
            throw new RuntimeException("Failed to read input or write output.", e);
        }
    }

    private static void solve(FastScanner in, PrintWriter out) {
        int rows = in.nextInt();
        int cols = in.nextInt();

        // A cross requires at least a 3x3 area. Early exit for small grids.
        if (rows < 3 || cols < 3) {
            out.println("NO");
            return;
        }

        char[][] grid = readGrid(in, rows);

        // Precompute consecutive '*' counts in all four directions
        int[][] up = computeConsecutive(grid, rows, cols, Direction.UP);
        int[][] down = computeConsecutive(grid, rows, cols, Direction.DOWN);
        int[][] left = computeConsecutive(grid, rows, cols, Direction.LEFT);
        int[][] right = computeConsecutive(grid, rows, cols, Direction.RIGHT);

        // Mark all cells that belong to at least one valid cross
        boolean[][] covered = markCrosses(grid, rows, cols, up, down, left, right);

        // Verify every '*' is covered
        if (allStarsCovered(grid, covered)) {
            out.println("YES");
        } else {
            out.println("NO");
        }
    }

    private static char[][] readGrid(FastScanner in, int rows) {
        char[][] grid = new char[rows][];
        for (int r = 0; r < rows; r++) {
            grid[r] = in.next().toCharArray();
        }
        return grid;
    }

    private static int[][] computeConsecutive(char[][] grid, int rows, int cols, Direction dir) {
        int[][] counts = new int[rows][cols];
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] != '*') continue;

                switch (dir) {
                    case UP:
                        counts[r][c] = (r > 0 ? counts[r - 1][c] : 0) + 1;
                        break;
                    case DOWN:
                        counts[r][c] = (r < rows - 1 ? counts[r + 1][c] : 0) + 1;
                        break;
                    case LEFT:
                        counts[r][c] = (c > 0 ? counts[r][c - 1] : 0) + 1;
                        break;
                    case RIGHT:
                        counts[r][c] = (c < cols - 1 ? counts[r][c + 1] : 0) + 1;
                        break;
                }
            }
        }
        return counts;
    }

    private static boolean[][] markCrosses(char[][] grid, int rows, int cols,
                                           int[][] up, int[][] down,
                                           int[][] left, int[][] right) {
        boolean[][] covered = new boolean[rows][cols];

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                // Check if current cell is a valid cross center
                if (grid[r][c] == '*' && up[r][c] > 1 && down[r][c] > 1 &&
                    left[r][c] > 1 && right[r][c] > 1) {

                    // Mark center
                    covered[r][c] = true;

                    // Mark arms
                    for (int k = 1; k < up[r][c]; k++) covered[r - k][c] = true;
                    for (int k = 1; k < down[r][c]; k++) covered[r + k][c] = true;
                    for (int k = 1; k < left[r][c]; k++) covered[r][c - k] = true;
                    for (int k = 1; k < right[r][c]; k++) covered[r][c + k] = true;
                }
            }
        }
        return covered;
    }

    private static boolean allStarsCovered(char[][] grid, boolean[][] covered) {
        for (int r = 0; r < grid.length; r++) {
            for (int c = 0; c < grid[r].length; c++) {
                if (grid[r][c] == '*' && !covered[r][c]) {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Standard fast I/O helper for competitive programming and large inputs.
     */
    private static class FastScanner {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastScanner(InputStream stream) {
            this.reader = new BufferedReader(new InputStreamReader(stream));
            this.tokenizer = new StringTokenizer("");
        }

        public String next() {
            while (!tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input.", e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            String token = next();
            return token == null ? 0 : Integer.parseInt(token);
        }
    }

    /**
     * Enum representing cardinal directions for preprocessing.
     */
    private enum Direction {
        UP, DOWN, LEFT, RIGHT
    }
}

import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        // Read grid dimensions
        if (!scanner.hasNextInt()) {
            return;
        }
        int rows = scanner.nextInt();
        int cols = scanner.nextInt();

        // Read the grid content
        // Using boolean array for clarity: true represents '*', false represents other
        boolean[][] grid = new boolean[rows][cols];
        for (int i = 0; i < rows; i++) {
            String line = scanner.next();
            for (int j = 0; j < cols; j++) {
                grid[i][j] = (line.charAt(j) == '*');
            }
        }

        // Find the center of a valid cross
        // A valid center (r, c) must be a '*' and have '*' neighbors in all 4 directions
        int centerRow = -1;
        int centerCol = -1;

        // Search for a '*' that has '*' neighbors in all 4 cardinal directions.
        // We search from index 1 to n-2 to ensure neighbors exist.
        for (int i = 1; i < rows - 1; i++) {
            for (int j = 1; j < cols - 1; j++) {
                if (grid[i][j] && grid[i][j - 1] && grid[i][j + 1] && 
                    grid[i - 1][j] && grid[i + 1][j]) {
                    centerRow = i;
                    centerCol = j;
                    // Found a valid center. 
                    // The original code continued searching to find the last valid center.
                    // However, for the purpose of the algorithm (clearing and checking emptiness),
                    // finding the first valid center is sufficient and more efficient.
                    break;
                }
            }
            if (centerRow != -1) {
                break;
            }
        }

        // If no center was found, it's impossible to clear the grid as required.
        // (Original code checked x*y == 0, which effectively checked if coordinates were initialized)
        if (centerRow == -1) {
            System.out.println("NO");
            return;
        }

        // Clear the row and column corresponding to the found center
        clearCross(grid, centerRow, centerCol);

        // Check if any '*' remains in the grid
        if (hasRemainingStars(grid)) {
            System.out.println("NO");
        } else {
            System.out.println("YES");
        }

        scanner.close();
    }

    /**
     * Clears the row and column starting from the center outwards as long as '*' are present.
     * This mimics the logic of the four loops in the original code.
     */
    private static void clearCross(boolean[][] grid, int r, int c) {
        // Clear Right
        for (int j = c + 1; j < grid[0].length && grid[r][j]; j++) {
            grid[r][j] = false;
        }
        // Clear Left
        for (int j = c - 1; j >= 0 && grid[r][j]; j--) {
            grid[r][j] = false;
        }
        // Clear Down
        for (int i = r + 1; i < grid.length && grid[i][c]; i++) {
            grid[i][c] = false;
        }
        // Clear Up
        for (int i = r - 1; i >= 0 && grid[i][c]; i--) {
            grid[i][c] = false;
        }
        // Clear Center
        grid[r][c] = false;
    }

    /**
     * Checks if the grid still contains any '*' characters.
     */
    private static boolean hasRemainingStars(boolean[][] grid) {
        for (boolean[] row : grid) {
            for (boolean cell : row) {
                if (cell) {
                    return true;
                }
            }
        }
        return false;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

public class Contest {

    public static void main(String[] args) throws IOException {
        FastScanner in = new FastScanner();
        PrintWriter out = new PrintWriter(System.out);

        try {
            solve(in, out);
        } finally {
            // Flush ensures all buffered output is written to System.out.
            // Closing System.out is generally discouraged in Java applications.
            out.flush();
        }
    }

    static void solve(FastScanner in, PrintWriter out) throws IOException {
        int rows = in.nextInt();
        int cols = in.nextInt();

        // A cross pattern requires at least a 3x3 grid
        if (rows < 3 || cols < 3) {
            out.println("NO");
            return;
        }

        char[][] grid = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            grid[i] = in.next().toCharArray();
        }

        boolean found = false;
        outerLoop:
        for (int i = 1; i < rows - 1; i++) {
            for (int j = 1; j < cols - 1; j++) {
                if (grid[i][j] == '*') {
                    // Check all four orthogonal neighbors
                    boolean up = grid[i - 1][j] == '*';
                    boolean down = grid[i + 1][j] == '*';
                    boolean left = grid[i][j - 1] == '*';
                    boolean right = grid[i][j + 1] == '*';

                    if (up && down && left && right) {
                        clearCross(grid, i, j, rows, cols);
                        found = true;
                        break outerLoop;
                    }
                }
            }
        }

        if (found) {
            // If a cross was found, verify that no '*' remains in the grid
            for (char[] row : grid) {
                for (char cell : row) {
                    if (cell == '*') {
                        out.println("NO");
                        return;
                    }
                }
            }
            out.println("YES");
        } else {
            out.println("NO");
        }
    }

    /**
     * Clears the '*' characters in a cross shape centered at (r, c).
     * Stops clearing in each direction when a non-'*' character is encountered.
     */
    private static void clearCross(char[][] grid, int r, int c, int rows, int cols) {
        // Clear left
        for (int k = c - 1; k >= 0; k--) {
            if (grid[r][k] == '*') grid[r][k] = '-';
            else break;
        }
        // Clear right
        for (int k = c + 1; k < cols; k++) {
            if (grid[r][k] == '*') grid[r][k] = '-';
            else break;
        }
        // Clear up
        for (int k = r - 1; k >= 0; k--) {
            if (grid[k][c] == '*') grid[k][c] = '-';
            else break;
        }
        // Clear down
        for (int k = r + 1; k < rows; k++) {
            if (grid[k][c] == '*') grid[k][c] = '-';
            else break;
        }
        // Clear center
        grid[r][c] = '-';
    }

    /**
     * Encapsulates fast I/O utilities to avoid static state pollution
     * and improve testability/reusability.
     */
    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            String s = next();
            return s == null ? 0 : Integer.parseInt(s);
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

/**
 * Solves the star-grid expansion problem.
 * Finds a '*' surrounded by '*' in all four cardinal directions,
 * expands in those directions replacing '*' with '-', and checks
 * if the grid is completely cleared.
 */
public class StarGridSolver {

    private static final int[][] DIRECTIONS = {
        {-1, 0}, {0, -1}, {0, 1}, {1, 0}
    };

    public static void main(String[] args) throws IOException {
        FastScanner scanner = new FastScanner();
        int h = scanner.nextInt();
        int w = scanner.nextInt();

        char[][] grid = new char[h][];
        for (int i = 0; i < h; i++) {
            grid[i] = scanner.next().toCharArray();
        }

        boolean allCleared = solve(grid, h, w);
        System.out.println(allCleared ? "YES" : "NO");
    }

    /**
     * Attempts to find a valid starting '*' and expand it.
     * Returns true if the grid is completely cleared, false otherwise.
     */
    private static boolean solve(char[][] grid, int h, int w) {
        for (int i = 1; i < h - 1; i++) {
            for (int j = 1; j < w - 1; j++) {
                if (isSurroundedByStars(grid, i, j)) {
                    grid[i][j] = '-';
                    expandInAllDirections(grid, h, w, i, j);
                    return !hasRemainingStars(grid);
                }
            }
        }
        // No valid starting point found
        return false;
    }

    private static boolean isSurroundedByStars(char[][] grid, int i, int j) {
        return grid[i][j] == '*'
            && grid[i - 1][j] == '*'
            && grid[i + 1][j] == '*'
            && grid[i][j - 1] == '*'
            && grid[i][j + 1] == '*';
    }

    private static void expandInAllDirections(char[][] grid, int h, int w, int startI, int startJ) {
        for (int[] dir : DIRECTIONS) {
            expandInDirection(grid, h, w, startI, startJ, dir[0], dir[1]);
        }
    }

    private static void expandInDirection(char[][] grid, int h, int w, int startI, int startJ, int dRow, int dCol) {
        for (int i = startI + dRow, j = startJ + dCol;
             i >= 0 && i < h && j >= 0 && j < w;
             i += dRow, j += dCol) {
            if (grid[i][j] != '*') {
                break;
            }
            grid[i][j] = '-';
        }
    }

    private static boolean hasRemainingStars(char[][] grid) {
        for (char[] row : grid) {
            for (char cell : row) {
                if (cell == '*') {
                    return true;
                }
            }
        }
        return false;
    }

    /**
     * Standard fast I/O utility for competitive programming and large inputs.
     * Replaces error-prone byte-level reading with a clean, maintainable approach.
     */
    private static class FastScanner {
        private final BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        private StringTokenizer tokenizer;

        public String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                String line = reader.readLine();
                if (line == null) {
                    throw new IOException("Unexpected end of input");
                }
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

/**
 * A utility class to determine if a given grid of characters represents a valid "Plus" shape.
 * A valid Plus shape is defined as a set of '*' characters forming a cross (center with arms
 * extending up, down, left, and right) that accounts for all '*' characters in the grid.
 */
public class PlusShapeChecker {

    public static void main(String[] args) throws IOException {
        // Use BufferedReader for efficient input reading
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));

        // Read dimensions (rows and columns)
        String line = reader.readLine();
        if (line == null) {
            return;
        }

        StringTokenizer tokenizer = new StringTokenizer(line);
        int rows = Integer.parseInt(tokenizer.nextToken());
        int cols = Integer.parseInt(tokenizer.nextToken());

        // Read the grid and count the total number of stars
        char[][] grid = new char[rows][cols];
        int totalStars = 0;

        for (int i = 0; i < rows; i++) {
            String rowStr = reader.readLine();
            if (rowStr != null) {
                for (int j = 0; j < cols; j++) {
                    // Safe access to character, defaulting to non-star if index out of bounds
                    char currentChar = (j < rowStr.length()) ? rowStr.charAt(j) : ' ';
                    grid[i][j] = currentChar;
                    if (currentChar == '*') {
                        totalStars++;
                    }
                }
            }
        }

        // Determine if the grid contains a valid plus shape
        boolean isValidPlus = checkForPlusShape(grid, rows, cols, totalStars);

        // Output the result
        System.out.println(isValidPlus ? "YES" : "NO");
    }

    /**
     * Checks if the grid contains a valid plus shape that covers all stars.
     *
     * @param grid The 2D character array representing the grid.
     * @param rows The number of rows in the grid.
     * @param cols The number of columns in the grid.
     * @param totalStars The total count of '*' characters in the grid.
     * @return true if a valid plus shape exists covering all stars, false otherwise.
     */
    private static boolean checkForPlusShape(char[][] grid, int rows, int cols, int totalStars) {
        // Iterate through the grid to find a potential center of a plus.
        // A center cannot be on the border (index 0 or max index).
        for (int i = 1; i < rows - 1; i++) {
            for (int j = 1; j < cols - 1; j++) {

                // A plus center must be a star
                if (grid[i][j] == '*') {

                    // Check immediate neighbors (Up, Down, Left, Right)
                    // We check bounds implicitly by the loop range (1 to size-2)
                    if (grid[i - 1][j] == '*' &&
                        grid[i + 1][j] == '*' &&
                        grid[i][j - 1] == '*' &&
                        grid[i][j + 1] == '*') {

                        // Calculate the size of the plus shape centered at (i, j)
                        int plusSize = 1; // Start with the center star

                        // Count vertical arm (Down)
                        for (int k = i + 1; k < rows && grid[k][j] == '*'; k++) {
                            plusSize++;
                        }
                        // Count vertical arm (Up)
                        for (int k = i - 1; k >= 0 && grid[k][j] == '*'; k--) {
                            plusSize++;
                        }
                        // Count horizontal arm (Right)
                        for (int k = j + 1; k < cols && grid[i][k] == '*'; k++) {
                            plusSize++;
                        }
                        // Count horizontal arm (Left)
                        for (int k = j - 1; k >= 0 && grid[i][k] == '*'; k--) {
                            plusSize++;
                        }

                        // If the size of this plus equals the total number of stars in the grid,
                        // it implies the entire grid consists of this single plus shape.
                        if (plusSize == totalStars) {
                            return true;
                        }
                    }
                }
            }
        }
        return false;
    }
}

import java.util.Scanner;

public class PlusFromPicture {

    public static void main(String[] args) {
        // Use try-with-resources to ensure Scanner is properly closed
        try (Scanner scanner = new Scanner(System.in)) {
            if (!scanner.hasNextInt()) {
                return;
            }

            int numRows = scanner.nextInt();
            int numCols = scanner.nextInt();

            if (numRows <= 0 || numCols <= 0) {
                System.out.println("NO");
                return;
            }

            char[][] grid = readGrid(scanner, numRows, numCols);
            if (grid == null) {
                System.out.println("NO");
                return;
            }

            int[] plusPosition = findPlus(grid, numRows, numCols);
            if (plusPosition != null) {
                removePlus(grid, plusPosition[0], plusPosition[1], numRows, numCols);
                if (hasRemainingStars(grid, numRows, numCols)) {
                    System.out.println("NO");
                } else {
                    System.out.println("YES");
                }
            } else {
                System.out.println("NO");
            }
        }
    }

    /**
     * Reads the grid from the scanner input.
     * @return the character grid, or null if input is malformed
     */
    private static char[][] readGrid(Scanner scanner, int numRows, int numCols) {
        char[][] grid = new char[numRows][numCols];
        for (int i = 0; i < numRows; i++) {
            if (!scanner.hasNext()) {
                return null;
            }
            String row = scanner.next();
            if (row.length() != numCols) {
                return null;
            }
            grid[i] = row.toCharArray();
        }
        return grid;
    }

    /**
     * Locates exactly one plus sign in the grid.
     * A plus is defined as a center '*' with '*' immediately above, below, left, and right.
     * @return int array {row, col} if exactly one plus exists, otherwise null
     */
    private static int[] findPlus(char[][] grid, int numRows, int numCols) {
        int plusCount = 0;
        int plusRow = -1;
        int plusCol = -1;

        // Pluses cannot touch the border
        for (int i = 1; i < numRows - 1; i++) {
            for (int j = 1; j < numCols - 1; j++) {
                if (grid[i][j] == '*' &&
                    grid[i][j - 1] == '*' && grid[i][j + 1] == '*' &&
                    grid[i - 1][j] == '*' && grid[i + 1][j] == '*') {
                    plusCount++;
                    plusRow = i;
                    plusCol = j;
                }
            }
        }

        return plusCount == 1 ? new int[]{plusRow, plusCol} : null;
    }

    /**
     * Removes the plus sign centered at (row, col) from the grid.
     * Replaces all connected '*' characters forming the plus with '.'
     */
    private static void removePlus(char[][] grid, int row, int col, int numRows, int numCols) {
        // Remove vertical segment
        for (int i = row - 1; i >= 0 && grid[i][col] == '*'; i--) {
            grid[i][col] = '.';
        }
        for (int i = row + 1; i < numRows && grid[i][col] == '*'; i++) {
            grid[i][col] = '.';
        }

        // Remove horizontal segment
        for (int j = col - 1; j >= 0 && grid[row][j] == '*'; j--) {
            grid[row][j] = '.';
        }
        for (int j = col + 1; j < numCols && grid[row][j] == '*'; j++) {
            grid[row][j] = '.';
        }

        // Remove center
        grid[row][col] = '.';
    }

    /**
     * Checks if any '*' characters remain in the grid.
     */
    private static boolean hasRemainingStars(char[][] grid, int numRows, int numCols) {
        for (int i = 0; i < numRows; i++) {
            for (int j = 0; j < numCols; j++) {
                if (grid[i][j] == '*') {
                    return true;
                }
            }
        }
        return false;
    }
}

import java.util.Scanner;

/**
 * A program to detect and remove a specific cross pattern from a character grid.
 * The program checks if the grid contains exactly one cross shape (a center '*' 
 * with '*' in all four cardinal directions) such that removing it leaves the grid empty.
 */
public class GridPatternSolver {

    public static void main(String[] args) {
        // Use try-with-resources for automatic resource management
        try (Scanner scanner = new Scanner(System.in)) {
            if (!scanner.hasNextInt()) {
                return;
            }

            int n = scanner.nextInt();
            int m = scanner.nextInt();

            char[][] grid = new char[n][];
            for (int i = 0; i < n; i++) {
                // Read the next token and convert to char array
                // This matches the original logic: sc.next().toCharArray()
                grid[i] = scanner.next().toCharArray();
            }

            boolean result = solve(grid);

            if (result) {
                System.out.println("YES");
            } else {
                System.out.println("NO");
            }
        }
    }

    /**
     * Core logic to solve the grid problem.
     * 
     * @param grid The 2D character array representing the grid.
     * @return true if the grid can be cleared by removing exactly one cross, false otherwise.
     */
    private static boolean solve(char[][] grid) {
        int n = grid.length;
        int m = grid[0].length;
        boolean crossFound = false;

        // Iterate through the grid to find the first valid cross.
        // We start from 1 and end at length-2 because a cross requires neighbors in all 4 directions.
        outerLoop:
        for (int i = 1; i < n - 1; i++) {
            for (int j = 1; j < m - 1; j++) {
                if (isCross(grid, i, j)) {
                    removeCross(grid, i, j);
                    crossFound = true;
                    // Once the first valid cross is found and removed, 
                    // we stop searching for others.
                    break outerLoop;
                }
            }
        }

        // If no cross was found, the condition fails.
        if (!crossFound) {
            return false;
        }

        // After removing the cross, verify that the grid is completely empty of '*' characters.
        return isGridEmpty(grid);
    }

    /**
     * Checks if the cell at (r, c) is the center of a cross.
     * A cross center must have '*' in the current cell and all 4 cardinal neighbors.
     */
    private static boolean isCross(char[][] grid, int r, int c) {
        return grid[r][c] == '*' &&
               grid[r - 1][c] == '*' && // Up
               grid[r][c - 1] == '*' && // Left
               grid[r + 1][c] == '*' && // Down
               grid[r][c + 1] == '*';   // Right
    }

    /**
     * Removes the cross centered at (r, c) from the grid.
     * It turns the center and all contiguous '*' characters in the 4 cardinal directions into '.'.
     */
    private static void removeCross(char[][] grid, int r, int c) {
        // Remove the center
        grid[r][c] = '.';

        // Remove vertical segment (Up)
        for (int i = r - 1; i >= 0; i--) {
            if (grid[i][c] != '*') break;
            grid[i][c] = '.';
        }

        // Remove vertical segment (Down)
        for (int i = r + 1; i < grid.length; i++) {
            if (grid[i][c] != '*') break;
            grid[i][c] = '.';
        }

        // Remove horizontal segment (Left)
        for (int j = c - 1; j >= 0; j--) {
            if (grid[r][j] != '*') break;
            grid[r][j] = '.';
        }

        // Remove horizontal segment (Right)
        for (int j = c + 1; j < grid[0].length; j++) {
            if (grid[r][j] != '*') break;
            grid[r][j] = '.';
        }
    }

    /**
     * Checks if the grid contains any '*' characters.
     * 
     * @return true if no '*' characters are found, false otherwise.
     */
    private static boolean isGridEmpty(char[][] grid) {
        for (char[] row : grid) {
            for (char cell : row) {
                if (cell == '*') {
                    return false;
                }
            }
        }
        return true;
    }
}

import java.util.Scanner;
import java.io.PrintWriter;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        PrintWriter out = new PrintWriter(System.out);

        // Read dimensions
        if (!sc.hasNextInt()) {
            out.flush();
            return;
        }
        int numRows = sc.nextInt();
        int numCols = sc.nextInt();
        sc.nextLine(); // Consume the newline character after the integers

        char[][] grid = new char[numRows][numCols];
        int startRow = -1;
        int startCol = -1;

        // Read the grid and identify the starting point (first '*')
        for (int i = 0; i < numRows; i++) {
            String line = sc.nextLine();
            for (int j = 0; j < numCols && j < line.length(); j++) {
                grid[i][j] = line.charAt(j);
                // Find the first occurrence of '*'
                if (grid[i][j] == '*' && startRow == -1) {
                    startRow = i;
                    startCol = j;
                }
            }
        }

        // Validation 1: Check boundary and immediate neighbors of the start point
        // Conditions:
        // 1. Start column cannot be on the edge (0 or numCols - 1)
        // 2. Start point must exist (startRow != -1)
        // 3. Immediate horizontal neighbors must not be '*'
        if (startCol == 0 || startCol == numCols - 1 || startRow == -1 ||
            grid[startRow][startCol - 1] == '*' || grid[startRow][startCol + 1] == '*') {
            out.println("NO");
            out.flush();
            sc.close();
            out.close();
            return;
        }

        boolean[][] visited = new boolean[numRows][numCols];
        int currentRow = startRow;
        int currentCol = startCol;
        int branchRow = -1; // Tracks the row where the path widens horizontally

        // Traverse down the column of '*'
        while (currentRow < numRows && grid[currentRow][currentCol] == '*') {
            // Check if this '*' has '*' neighbors on both left and right
            // This identifies a "branch" or horizontal segment
            if (currentRow > 0 && currentRow < numRows - 1 &&
                grid[currentRow][currentCol - 1] == '*' &&
                grid[currentRow][currentCol + 1] == '*') {
                branchRow = currentRow;
            }
            visited[currentRow][currentCol] = true;
            currentRow++;
        }

        // Validation 2:
        // 1. We must have found a branch point (branchRow != -1)
        // 2. The vertical path must continue below the branch point
        //    (checked by seeing if the cell below branchRow was visited)
        if (branchRow == -1 || !visited[branchRow + 1][currentCol]) {
            out.println("NO");
            out.flush();
            sc.close();
            out.close();
            return;
        }

        // Horizontal Sweep:
        // From the branchRow, sweep left and right to mark all connected '*'
        int sweepCol = currentCol; // Start from the vertical line's column

        // Sweep Left
        while (sweepCol >= 0 && grid[branchRow][sweepCol] == '*') {
            visited[branchRow][sweepCol] = true;
            sweepCol--;
        }

        // Sweep Right
        sweepCol = currentCol; // Reset to start column
        while (sweepCol < numCols && grid[branchRow][sweepCol] == '*') {
            visited[branchRow][sweepCol] = true;
            sweepCol++;
        }

        // Final Validation: Ensure every '*' in the grid has been visited
        for (int i = 0; i < numRows; i++) {
            for (int j = 0; j < numCols; j++) {
                if (!visited[i][j] && grid[i][j] == '*') {
                    out.println("NO");
                    out.flush();
                    sc.close();
                    out.close();
                    return;
                }
            }
        }

        out.println("YES");
        out.flush();

        sc.close();
        out.close();
    }
}

import java.util.Scanner;

/**
 * Solves the grid problem:
 * 1. Finds a central asterisk surrounded by 4 others (a cross pattern).
 * 2. Clears all asterisks in the horizontal and vertical lines passing through the center.
 * 3. Checks if any asterisks remain in the grid.
 */
public class GridCrossSolver {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        // Reading dimensions
        if (!scanner.hasNextInt()) {
            return;
        }
        int rows = scanner.nextInt();
        int cols = scanner.nextInt();

        // Reading grid
        char[][] grid = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            String rowString = scanner.next();
            // Fill the row, ensuring we don't exceed string length if input is malformed
            for (int j = 0; j < cols && j < rowString.length(); j++) {
                grid[i][j] = rowString.charAt(j);
            }
        }

        // Execute logic
        solve(grid);

        scanner.close();
    }

    /**
     * Orchestrates the solving process.
     */
    private static void solve(char[][] grid) {
        // Step 1: Find the center of the cross
        int[] center = findCenter(grid);

        if (center == null) {
            System.out.println("NO");
            return;
        }

        int centerRow = center[0];
        int centerCol = center[1];

        // Step 2: Clear the arms of the cross
        clearArms(grid, centerRow, centerCol);

        // Step 3: Verify if the grid is empty of stars
        if (hasRemainingStars(grid)) {
            System.out.println("NO");
        } else {
            System.out.println("YES");
        }
    }

    /**
     * Scans the grid to find a 'center' asterisk surrounded by 4 others.
     * Returns an int array {row, col} or null if not found.
     */
    private static int[] findCenter(char[][] grid) {
        int rows = grid.length;
        int cols = grid[0].length;

        // We start from 1 and go to length-2 because we need neighbors on all sides
        for (int i = 1; i < rows - 1; i++) {
            for (int j = 1; j < cols - 1; j++) {
                if (isCrossCenter(grid, i, j)) {
                    return new int[]{i, j};
                }
            }
        }
        return null;
    }

    /**
     * Checks if the cell at (r, c) is the center of a cross.
     */
    private static boolean isCrossCenter(char[][] grid, int r, int c) {
        return grid[r][c] == '*' &&
                grid[r][c - 1] == '*' && // Left
                grid[r][c + 1] == '*' && // Right
                grid[r - 1][c] == '*' && // Up
                grid[r + 1][c] == '*';   // Down
    }

    /**
     * Clears asterisks in all 4 cardinal directions from the center.
     * Logic matches original code: Right starts at center, others start at neighbor.
     */
    private static void clearArms(char[][] grid, int centerRow, int centerCol) {
        // Right: starts at center
        clearLine(grid, centerRow, centerCol, 0, 1);
        // Left: starts left of center
        clearLine(grid, centerRow, centerCol - 1, 0, -1);
        // Down: starts below center
        clearLine(grid, centerRow + 1, centerCol, 1, 0);
        // Up: starts above center
        clearLine(grid, centerRow - 1, centerCol, -1, 0);
    }

    /**
     * Clears a line starting from (startRow, startCol) in a specific direction.
     * Stops when a '.' is encountered or boundaries are reached.
     */
    private static void clearLine(char[][] grid, int startRow, int startCol, int deltaRow, int deltaCol) {
        int r = startRow;
        int c = startCol;

        while (r >= 0 && r < grid.length && c >= 0 && c < grid[0].length) {
            if (grid[r][c] == '.') {
                break;
            }
            grid[r][c] = '.';
            r += deltaRow;
            c += deltaCol;
        }
    }

    /**
     * Checks if any asterisks remain in the grid.
     */
    private static boolean hasRemainingStars(char[][] grid) {
        for (char[] row : grid) {
            for (char cell : row) {
                if (cell == '*') {
                    return true;
                }
            }
        }
        return false;
    }
}

import java.util.Scanner;

/**
 * A solver for the grid problem.
 * Refactored for maintainability, readability, and adherence to Java conventions.
 */
public class GridSolver {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        // Read dimensions
        if (!scanner.hasNextInt()) return;
        int rows = scanner.nextInt();
        int cols = scanner.nextInt();

        // Constraint check: Grid must be large enough to have an internal pivot
        if (rows <= 2 || cols <= 2) {
            System.out.println("NO");
            return;
        }

        // Read grid
        char[][] grid = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            // Using next() to skip whitespace and read the row string
            String line = scanner.next();
            grid[i] = line.toCharArray();
        }

        // Attempt to find a valid pivot point and clear the cross shape centered at that point.
        // The original logic stops searching after the first successful mark.
        boolean pivotFound = findAndClearPivot(grid, rows, cols);

        if (!pivotFound) {
            System.out.println("NO");
            return;
        }

        // Verify if the grid is completely cleared of '*' characters
        if (isGridCleared(grid)) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }

        scanner.close();
    }

    /**
     * Searches for a valid pivot point and clears the cross shape centered at that point.
     * Returns true if a pivot was found and cleared, false otherwise.
     */
    private static boolean findAndClearPivot(char[][] grid, int rows, int cols) {
        // Iterate through the grid, excluding the border rows and columns.
        // In 0-based indexing, valid pivot rows are 1 to rows-2.
        // Valid pivot columns are 1 to cols-2.
        for (int r = 1; r < rows - 1; r++) {
            for (int c = 1; c < cols - 1; c++) {
                if (isValidPivot(grid, r, c)) {
                    clearCross(grid, r, c);
                    return true; // Found one, executed move, and stopped searching.
                }
            }
        }
        return false;
    }

    /**
     * Checks if the cell at (r, c) and its 4 orthogonal neighbors are all '*' (not '.').
     * This corresponds to the original 'check' method logic.
     */
    private static boolean isValidPivot(char[][] grid, int r, int c) {
        // Check center
        if (grid[r][c] == '.') return false;
        // Check neighbors (Up, Down, Left, Right)
        // Bounds are guaranteed safe because loops in findAndClearPivot exclude borders
        if (grid[r - 1][c] == '.') return false; // Up
        if (grid[r + 1][c] == '.') return false; // Down
        if (grid[r][c - 1] == '.') return false; // Left
        if (grid[r][c + 1] == '.') return false; // Right

        return true;
    }

    /**
     * Marks the center cell and clears the cross shape (Up, Down, Left, Right)
     * until a '.' is encountered or the grid boundary is reached.
     * This corresponds to the original 'mark' method logic.
     */
    private static void clearCross(char[][] grid, int r, int c) {
        // Mark center
        grid[r][c] = '.';

        // Clear Up
        for (int i = r - 1; i >= 0; i--) {
            if (grid[i][c] == '.') break;
            grid[i][c] = '.';
        }

        // Clear Down
        for (int i = r + 1; i < grid.length; i++) {
            if (grid[i][c] == '.') break;
            grid[i][c] = '.';
        }

        // Clear Left
        for (int i = c - 1; i >= 0; i--) {
            if (grid[r][i] == '.') break;
            grid[r][i] = '.';
        }

        // Clear Right
        for (int i = c + 1; i < grid[r].length; i++) {
            if (grid[r][i] == '.') break;
            grid[r][i] = '.';
        }
    }

    /**
     * Checks if there are any '*' characters remaining in the grid.
     */
    private static boolean isGridCleared(char[][] grid) {
        for (char[] row : grid) {
            for (char cell : row) {
                if (cell == '*') {
                    return false;
                }
            }
        }
        return true;
    }
}

import java.util.Scanner;

/**
 * Determines if a grid contains exactly one isolated cross shape formed by '*' characters.
 */
public class CrossChecker {

    private static final char STAR = '*';

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        if (!scanner.hasNextInt()) {
            return;
        }

        int height = scanner.nextInt();
        int width = scanner.nextInt();

        // A cross requires at least a 3x3 area to have a center and 4 valid neighbors
        if (height < 3 || width < 3) {
            System.out.println("NO");
            return;
        }

        String[] grid = new String[height];
        for (int i = 0; i < height; i++) {
            grid[i] = scanner.next();
        }

        if (isValidCross(grid, height, width)) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }
    }

    /**
     * Validates if the grid contains exactly one isolated cross.
     */
    private static boolean isValidCross(String[] grid, int height, int width) {
        int centerX = -1;
        int centerY = -1;

        // 1. Find the center of the cross
        for (int i = 1; i < height - 1; i++) {
            for (int j = 1; j < width - 1; j++) {
                if (isCrossCenter(grid, i, j)) {
                    centerX = i;
                    centerY = j;
                    break;
                }
            }
            if (centerX != -1) {
                break;
            }
        }

        if (centerX == -1) {
            return false;
        }

        // 2. Verify that the cross arms do not extend further
        if (!isCrossIsolated(grid, centerX, centerY, height, width)) {
            return false;
        }

        // 3. Ensure no other '*' characters exist in the grid
        return !hasOtherStars(grid, centerX, centerY, height, width);
    }

    /**
     * Checks if the given coordinates form the center of a cross.
     */
    private static boolean isCrossCenter(String[] grid, int row, int col) {
        return grid[row].charAt(col) == STAR &&
               grid[row - 1].charAt(col) == STAR &&
               grid[row + 1].charAt(col) == STAR &&
               grid[row].charAt(col - 1) == STAR &&
               grid[row].charAt(col + 1) == STAR;
    }

    /**
     * Verifies that the cross arms are bounded and do not continue further in any direction.
     */
    private static boolean isCrossIsolated(String[] grid, int centerX, int centerY, int height, int width) {
        // Check horizontal boundaries
        int left = centerY;
        while (left > 0 && grid[centerX].charAt(left - 1) == STAR) {
            left--;
        }
        if (left > 0 && grid[centerX].charAt(left - 1) == STAR) {
            return false;
        }

        int right = centerY;
        while (right < width - 1 && grid[centerX].charAt(right + 1) == STAR) {
            right++;
        }
        if (right < width - 1 && grid[centerX].charAt(right + 1) == STAR) {
            return false;
        }

        // Check vertical boundaries
        int top = centerX;
        while (top > 0 && grid[top - 1].charAt(centerY) == STAR) {
            top--;
        }
        if (top > 0 && grid[top - 1].charAt(centerY) == STAR) {
            return false;
        }

        int bottom = centerX;
        while (bottom < height - 1 && grid[bottom + 1].charAt(centerY) == STAR) {
            bottom++;
        }
        if (bottom < height - 1 && grid[bottom + 1].charAt(centerY) == STAR) {
            return false;
        }

        return true;
    }

    /**
     * Checks if there are any '*' characters outside the identified cross.
     */
    private static boolean hasOtherStars(String[] grid, int centerX, int centerY, int height, int width) {
        for (int i = 0; i < height; i++) {
            for (int j = 0; j < width; j++) {
                if ((i != centerX || j != centerY) && grid[i].charAt(j) == STAR) {
                    return true;
                }
            }
        }
        return false;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

public class CrossPatternChecker {

    public static void main(String[] args) throws IOException {
        // Use try-with-resources for automatic stream closure
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            String line = br.readLine();
            if (line == null) return;

            StringTokenizer st = new StringTokenizer(line);
            int height = Integer.parseInt(st.nextToken());
            int width = Integer.parseInt(st.nextToken());

            char[][] grid = new char[height][width];
            for (int i = 0; i < height; i++) {
                String rowLine = br.readLine();
                if (rowLine != null) {
                    grid[i] = rowLine.toCharArray();
                }
            }

            // Identify the single valid row and column segments
            Segment rowSegment = findSingleRowSegment(grid, height, width);
            Segment colSegment = findSingleColumnSegment(grid, height, width);

            // If either segment is invalid or missing, output NO
            if (rowSegment == null || colSegment == null) {
                System.out.println("NO");
                return;
            }

            // Check intersection and clear if valid
            if (areSegmentsIntersecting(rowSegment, colSegment)) {
                clearSegments(grid, rowSegment, colSegment);
                if (isGridClean(grid, height, width)) {
                    System.out.println("YES");
                } else {
                    System.out.println("NO");
                }
            } else {
                System.out.println("NO");
            }
        }
    }

    /**
     * Scans all rows to find exactly one contiguous segment of '*'.
     * Returns null if any row contains multiple segments or if multiple rows have segments.
     */
    private static Segment findSingleRowSegment(char[][] grid, int height, int width) {
        Segment found = null;
        for (int row = 0; row < height; row++) {
            Segment segment = findSegmentInLine(grid[row]);
            if (segment == null) {
                return null; // Invalid row structure (multiple segments)
            }
            if (!segment.isEmpty()) {
                if (found != null) {
                    return null; // More than one row contains a segment
                }
                found = new Segment(segment.start, segment.end, row);
            }
        }
        return found;
    }

    /**
     * Scans all columns to find exactly one contiguous segment of '*'.
     * Returns null if any column contains multiple segments or if multiple columns have segments.
     */
    private static Segment findSingleColumnSegment(char[][] grid, int height, int width) {
        Segment found = null;
        for (int col = 0; col < width; col++) {
            // Extract column data into a 1D array for uniform processing
            char[] column = new char[height];
            for (int row = 0; row < height; row++) {
                column[row] = grid[row][col];
            }
            Segment segment = findSegmentInLine(column);
            if (segment == null) {
                return null; // Invalid column structure
            }
            if (!segment.isEmpty()) {
                if (found != null) {
                    return null; // More than one column contains a segment
                }
                found = new Segment(segment.start, segment.end, col);
            }
        }
        return found;
    }

    /**
     * Identifies a contiguous segment of '*' in a 1D array.
     * Returns null if there are multiple disconnected segments.
     * Returns a Segment with start/end = -1 if no '*' is found.
     */
    private static Segment findSegmentInLine(char[] line) {
        int first = -1;
        int last = -1;

        // Locate first and last occurrence of '*'
        for (int i = 0; i < line.length; i++) {
            if (line[i] == '*') {
                if (first == -1) first = i;
                last = i;
            }
        }

        // No '*' present
        if (first == -1) {
            return new Segment(-1, -1, -1);
        }

        // Verify all characters between first and last are '*'
        for (int i = first; i <= last; i++) {
            if (line[i] != '*') {
                return null; // Disconnected segments detected
            }
        }

        return new Segment(first, last, -1);
    }

    /**
     * Checks if the identified row and column segments intersect.
     * Preserves the original strict inequality condition (intersection cannot touch segment endpoints).
     */
    private static boolean areSegmentsIntersecting(Segment rowSeg, Segment colSeg) {
        // rowSeg.index = row coordinate, colSeg.index = column coordinate
        // Original logic: xa < y && y < xb && ya < x && x < yb
        return rowSeg.start < colSeg.index && colSeg.index < rowSeg.end &&
               colSeg.start < rowSeg.index && rowSeg.index < colSeg.end;
    }

    /**
     * Clears all '*' characters along the identified row and column segments.
     */
    private static void clearSegments(char[][] grid, Segment rowSeg, Segment colSeg) {
        for (int col = rowSeg.start; col <= rowSeg.end; col++) {
            grid[rowSeg.index][col] = '.';
        }
        for (int row = colSeg.start; row <= colSeg.end; row++) {
            grid[row][colSeg.index] = '.';
        }
    }

    /**
     * Verifies that the grid contains no remaining '*' characters.
     */
    private static boolean isGridClean(char[][] grid, int height, int width) {
        for (int i = 0; i < height; i++) {
            for (int j = 0; j < width; j++) {
                if (grid[i][j] == '*') {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Represents a contiguous segment of '*' in a 1D line.
     */
    private static class Segment {
        final int start;
        final int end;
        final int index; // Row index for row segments, column index for column segments

        Segment(int start, int end, int index) {
            this.start = start;
            this.end = end;
            this.index = index;
        }

        boolean isEmpty() {
            return start == -1;
        }
    }
}

import java.util.Scanner;

/**
 * Analyzes a grid of characters to determine if all star ('*') characters
 * are connected to a central star via horizontal or vertical lines.
 * 
 * Original logic:
 * 1. Reads a grid of size h x w.
 * 2. Finds the first star that is strictly surrounded by stars in all 4 cardinal directions.
 * 3. From that star, marks all connected stars in straight horizontal and vertical lines.
 * 4. Checks if every star in the grid was marked.
 */
public class Chessboard {

    // Instance variables to replace static fields for better encapsulation
    private char[][] grid;
    private boolean[][] visited;
    private int rows;
    private int cols;

    /**
     * Entry point for the analysis logic.
     */
    public void solve() {
        Scanner scanner = new Scanner(System.in);

        // Read dimensions
        if (!scanner.hasNextInt()) {
            return;
        }
        this.rows = scanner.nextInt();
        this.cols = scanner.nextInt();
        scanner.nextLine(); // Consume the newline character after integers

        // Initialize grid structures
        this.grid = new char[rows][cols];
        this.visited = new boolean[rows][cols];
        boolean hasStars = false;

        // Read grid content
        for (int r = 0; r < rows; r++) {
            String line = scanner.nextLine();
            // Ensure we don't go out of bounds if the input line is shorter than expected
            int length = Math.min(line.length(), cols);
            for (int c = 0; c < length; c++) {
                grid[r][c] = line.charAt(c);
                if (grid[r][c] == '*') {
                    hasStars = true;
                    // visited[r][c] remains false by default, indicating an unvisited star
                } else {
                    // Mark non-stars as visited to simplify the final verification logic
                    visited[r][c] = true;
                }
            }
        }

        // If no stars exist, the condition cannot be met based on original logic
        if (!hasStars) {
            System.out.println("NO");
            return;
        }

        // Find the first star that is surrounded by stars in all 4 directions
        boolean foundCenter = false;
        outerLoop:
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (isStarSurrounded(r, c)) {
                    markLines(r, c);
                    foundCenter = true;
                    break outerLoop;
                }
            }
        }

        // Verify if all stars have been visited
        boolean allStarsVisited = true;
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                // If we find a star that hasn't been visited, the condition fails
                if (grid[r][c] == '*' && !visited[r][c]) {
                    allStarsVisited = false;
                    break;
                }
            }
        }

        if (allStarsVisited) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }
    }

    /**
     * Checks if a star at (r, c) is strictly surrounded by stars 
     * in the Up, Down, Left, and Right directions.
     * 
     * @param r The row index
     * @param c The column index
     * @return true if the star is surrounded, false otherwise
     */
    private boolean isStarSurrounded(int r, int c) {
        // Must be strictly inside the grid (not on the border)
        if (r <= 0 || r >= rows - 1 || c <= 0 || c >= cols - 1) {
            return false;
        }

        return grid[r - 1][c] == '*' &&   // Up
               grid[r + 1][c] == '*' &&   // Down
               grid[r][c - 1] == '*' &&   // Left
               grid[r][c + 1] == '*';     // Right
    }

    /**
     * Marks all reachable stars in the horizontal and vertical lines
     * passing through (r, c) as visited.
     * 
     * @param r The row index of the center star
     * @param c The column index of the center star
     */
    private void markLines(int r, int c) {
        // Mark Vertical (Up)
        for (int i = r - 1; i >= 0; i--) {
            if (grid[i][c] == '*') {
                visited[i][c] = true;
            } else {
                break; // Stop at the first non-star
            }
        }

        // Mark Vertical (Down)
        for (int i = r + 1; i < rows; i++) {
            if (grid[i][c] == '*') {
                visited[i][c] = true;
            } else {
                break;
            }
        }

        // Mark Horizontal (Left)
        for (int j = c - 1; j >= 0; j--) {
            if (grid[r][j] == '*') {
                visited[r][j] = true;
            } else {
                break;
            }
        }

        // Mark Horizontal (Right)
        for (int j = c + 1; j < cols; j++) {
            if (grid[r][j] == '*') {
                visited[r][j] = true;
            } else {
                break;
            }
        }
    }

    public static void main(String[] args) {
        new Chessboard().solve();
    }
}

import java.io.*;
import java.util.StringTokenizer;

/**
 * Checks if all star characters ('*') in a grid form a valid cross/plus shape.
 * A valid shape requires a central horizontal segment with vertical arms extending
 * above and below it, covering all stars in the grid.
 */
public class Main {

    private static final char STAR = '*';
    private static final char EMPTY = '.';

    public static void main(String[] args) throws IOException {
        // try-with-resources ensures proper cleanup of I/O streams
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
             PrintWriter out = new PrintWriter(System.out)) {

            FastScanner scanner = new FastScanner(reader);
            out.print(solve(scanner));
        }
    }

    /**
     * Solves the cross-pattern validation problem.
     * @param scanner FastScanner instance reading from standard input
     * @return "YES" if the grid contains a valid cross pattern, otherwise "NO"
     * @throws IOException if an I/O error occurs
     */
    private static String solve(FastScanner scanner) throws IOException {
        int rows = scanner.nextInt();
        int cols = scanner.nextInt();

        char[][] grid = new char[rows][cols];
        int totalStars = 0;
        int[] starsPerRow = new int[rows];

        // Read grid and precompute star counts
        for (int i = 0; i < rows; i++) {
            String line = scanner.next();
            for (int j = 0; j < cols; j++) {
                grid[i][j] = line.charAt(j);
                if (grid[i][j] == STAR) {
                    totalStars++;
                    starsPerRow[i]++;
                }
            }
        }

        // A cross requires at least 3 rows and 3 columns
        if (rows <= 2 || cols <= 2) {
            return "NO";
        }

        // Find a candidate center row with at least 3 stars
        int centerRow = -1;
        for (int i = 1; i < rows - 1; i++) {
            if (starsPerRow[i] >= 3) {
                centerRow = i;
                break;
            }
        }

        if (centerRow == -1) {
            return "NO";
        }

        // Find the contiguous horizontal segment of stars in the center row
        int startCol = 0;
        while (startCol < cols && grid[centerRow][startCol] == EMPTY) {
            startCol++;
        }

        int endCol = startCol + 1;
        while (endCol < cols && grid[centerRow][endCol] == STAR) {
            endCol++;
        }
        endCol--; // Adjust to point to the last star in the segment

        // A horizontal arm must span at least 2 columns to form a cross
        if (startCol == endCol) {
            return "NO";
        }

        int horizontalStars = endCol - startCol + 1;

        // Preserve original logic: check if a star exists immediately to the left
        // If so, extend the horizontal count; otherwise, skip the leftmost column
        // for vertical checks to avoid double-counting or boundary issues
        if (startCol > 0 && grid[centerRow][startCol - 1] == STAR) {
            horizontalStars++;
        } else {
            startCol++;
        }
        endCol--;

        // After adjustment, the valid range for vertical checks must be valid
        if (endCol < startCol) {
            return "NO";
        }

        // Verify vertical arms for each column in the adjusted horizontal segment
        for (int col = startCol; col <= endCol; col++) {
            int starsAbove = 0;
            int row = centerRow - 1;
            while (row >= 0 && grid[row][col] == STAR) {
                starsAbove++;
                row--;
            }

            // Columns with no stars above are skipped (not part of the vertical arm)
            if (starsAbove == 0) {
                continue;
            }

            int starsBelow = 0;
            row = centerRow + 1;
            while (row < rows && grid[row][col] == STAR) {
                starsBelow++;
                row++;
            }

            // Every column with an upper arm must also have a lower arm
            if (starsBelow == 0) {
                return "NO";
            }

            // If the counted stars match the total, we found a valid cross
            if (starsAbove + starsBelow + horizontalStars == totalStars) {
                return "YES";
            }
        }

        return "NO";
    }

    /**
     * Fast I/O helper class for competitive programming and performance-critical applications.
     */
    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer tokenizer;

        FastScanner(InputStream inputStream) {
            this.br = new BufferedReader(new InputStreamReader(inputStream));
        }

        FastScanner(BufferedReader bufferedReader) {
            this.br = bufferedReader;
        }

        String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) {
                    return null;
                }
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        long nextLong() throws IOException {
            return Long.parseLong(next());
        }

        double nextDouble() throws IOException {
            return Double.parseDouble(next());
        }

        char nextChar() throws IOException {
            return (char) br.read();
        }

        String nextLine() throws IOException {
            return br.readLine();
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

public class Main {
    // Direction vectors for Right, Down, Left, Up
    private static final int[] DH = {0, 1, 0, -1};
    private static final int[] DW = {1, 0, -1, 0};

    public static void main(String[] args) {
        FastScanner sc = new FastScanner(System.in);
        int H = sc.nextInt();
        int W = sc.nextInt();
        char[][] grid = new char[H][W];

        for (int i = 0; i < H; i++) {
            grid[i] = sc.next().toCharArray();
        }

        System.out.println(solve(grid, H, W) ? "YES" : "NO");
    }

    /**
     * Determines if the grid contains exactly one valid plus-shaped pattern.
     * A valid pattern has exactly one center cell surrounded by '*' in all 4 directions,
     * with equal arm lengths extending from the center, and no other '*' characters.
     */
    private static boolean solve(char[][] grid, int H, int W) {
        int totalStars = 0;
        int centerH = -1;
        int centerW = -1;

        // First pass: count total stars and locate the unique center
        for (int h = 0; h < H; h++) {
            for (int w = 0; w < W; w++) {
                if (grid[h][w] == '*') {
                    totalStars++;
                }
                if (isCenter(grid, h, w)) {
                    if (centerH != -1) {
                        return false; // Multiple centers detected
                    }
                    centerH = h;
                    centerW = w;
                }
            }
        }

        if (centerH == -1) {
            return false; // No valid center found
        }

        // Second pass: verify arm lengths and total star count
        int expectedStars = 1; // Start with the center itself
        for (int d = 0; d < 4; d++) {
            int count = countInDirection(grid, centerH, centerW, d);
            if (count == 0) {
                return false; // Each direction must have at least one star
            }
            expectedStars += count;
        }

        return totalStars == expectedStars;
    }

    /**
     * Checks if the cell at (h, w) is a valid center (surrounded by '*' in all 4 directions).
     */
    private static boolean isCenter(char[][] grid, int h, int w) {
        if (grid[h][w] != '*') {
            return false;
        }
        for (int i = 0; i < 4; i++) {
            int nh = h + DH[i];
            int nw = w + DW[i];
            if (nh < 0 || nh >= grid.length || nw < 0 || nw >= grid[0].length || grid[nh][nw] != '*') {
                return false;
            }
        }
        return true;
    }

    /**
     * Counts consecutive '*' characters in a specific direction starting from (h, w).
     */
    private static int countInDirection(char[][] grid, int h, int w, int d) {
        int count = 0;
        int curH = h;
        int curW = w;
        while (true) {
            int nextH = curH + DH[d];
            int nextW = curW + DW[d];
            if (nextH >= 0 && nextH < grid.length && nextW >= 0 && nextW < grid[0].length && grid[nextH][nextW] == '*') {
                count++;
                curH = nextH;
                curW = nextW;
            } else {
                break;
            }
        }
        return count;
    }

    /**
     * Optimized FastScanner for efficient input reading.
     * Removed unused methods and fixed the buggy nextLine() implementation.
     */
    static class FastScanner {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        FastScanner(InputStream in) {
            reader = new BufferedReader(new InputStreamReader(in));
            tokenizer = null;
        }

        String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) {
                        return null;
                    }
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return tokenizer.nextToken();
        }

        int nextInt() {
            String s = next();
            if (s == null) {
                throw new RuntimeException("Unexpected end of input");
            }
            return Integer.parseInt(s);
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

/**
 * Solves Codeforces Problem 1182B: Neko Performs Cat Furrier Transform.
 * Finds a '*' with '*' in all four cardinal directions, removes it and 
 * all connected '*' in those directions, and verifies if any '*' remain.
 */
public class P1182B {

    public static void main(String[] args) throws IOException {
        // Use try-with-resources to guarantee proper cleanup of I/O streams
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
             PrintWriter out = new PrintWriter(System.out)) {
            new P1182B().run(br, out);
        }
    }

    /**
     * Orchestrates reading input, executing the algorithm, and writing output.
     */
    void run(BufferedReader br, PrintWriter out) throws IOException {
        StringTokenizer st = new StringTokenizer("");

        // Read grid dimensions
        while (!st.hasMoreTokens()) {
            String line = br.readLine();
            if (line == null) return;
            st = new StringTokenizer(line);
        }
        int rows = Integer.parseInt(st.nextToken());
        int cols = Integer.parseInt(st.nextToken());

        // Read grid rows
        char[][] grid = new char[rows][];
        for (int i = 0; i < rows; i++) {
            while (!st.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) break;
                st = new StringTokenizer(line);
            }
            grid[i] = st.nextToken().toCharArray();
        }

        // Execute core logic
        int[] target = findCrossCenter(grid, rows, cols);
        if (target == null) {
            out.println("NO");
            return;
        }

        clearConnectedStars(grid, target[0], target[1], rows, cols);

        if (hasRemainingStars(grid)) {
            out.println("NO");
        } else {
            out.println("YES");
        }
    }

    /**
     * Searches for a '*' that has '*' in all four cardinal directions.
     * Returns coordinates as [row, col] or null if not found.
     */
    private int[] findCrossCenter(char[][] grid, int rows, int cols) {
        for (int r = rows - 2; r >= 1; r--) {
            for (int c = cols - 2; c >= 1; c--) {
                if (isCross(grid, r, c)) {
                    return new int[]{r, c};
                }
            }
        }
        return null;
    }

    /**
     * Checks if the cell at (r, c) and its four neighbors are all '*'.
     */
    private boolean isCross(char[][] grid, int r, int c) {
        return grid[r][c] == '*' &&
               grid[r - 1][c] == '*' &&
               grid[r + 1][c] == '*' &&
               grid[r][c - 1] == '*' &&
               grid[r][c + 1] == '*';
    }

    /**
     * Clears the target cell and all connected '*' in the four cardinal directions.
     */
    private void clearConnectedStars(char[][] grid, int r, int c, int rows, int cols) {
        grid[r][c] = '.';
        clearDirection(grid, r, c, -1, 0, rows, cols); // Up
        clearDirection(grid, r, c, 1, 0, rows, cols);  // Down
        clearDirection(grid, r, c, 0, -1, rows, cols); // Left
        clearDirection(grid, r, c, 0, 1, rows, cols);  // Right
    }

    /**
     * Traverses a single direction from (r, c) and clears consecutive '*'.
     */
    private void clearDirection(char[][] grid, int r, int c, int dr, int dc, int rows, int cols) {
        int nr = r + dr;
        int nc = c + dc;
        while (nr >= 0 && nr < rows && nc >= 0 && nc < cols && grid[nr][nc] == '*') {
            grid[nr][nc] = '.';
            nr += dr;
            nc += dc;
        }
    }

    /**
     * Checks if any '*' remain in the grid.
     */
    private boolean hasRemainingStars(char[][] grid) {
        for (char[] row : grid) {
            for (char cell : row) {
                if (cell == '*') {
                    return true;
                }
            }
        }
        return false;
    }
}

import java.util.Scanner;

public class Plus {

    // Constants for grid characters to improve readability
    private static final char STAR = '*';
    private static final char EMPTY = '.';

    public static void main(String[] args) {
        // Use try-with-resources to ensure the Scanner is properly closed
        try (Scanner sc = new Scanner(System.in)) {
            if (!sc.hasNextInt()) {
                return;
            }

            int rows = sc.nextInt();
            int cols = sc.nextInt();

            char[][] grid = new char[rows][cols];

            // Read the grid from input
            for (int i = 0; i < rows; i++) {
                if (sc.hasNext()) {
                    grid[i] = sc.next().toCharArray();
                }
            }

            // Iterate through the grid to find the center of a potential plus sign.
            // A valid plus sign of size 3x3 requires the center to be at least 1 unit 
            // away from the grid boundaries to accommodate its 4 neighbors.
            // Row index 'r' ranges from 1 to rows-2.
            // Column index 'c' ranges from 1 to cols-2.
            for (int r = 1; r < rows - 1; r++) {
                for (int c = 1; c < cols - 1; c++) {

                    // Check if the 5-star pattern (center + 4 immediate neighbors) exists
                    if (hasPlusPattern(grid, r, c)) {
                        // If a pattern is found, verify global constraints:
                        // 1. The arms must be valid according to specific rules.
                        // 2. There must be no other stars outside this cross shape.
                        if (isPlusArmValid(grid, r, c, rows, cols) && 
                            hasStarsOutsideCross(grid, r, c, rows, cols)) {
                            System.out.println("YES");
                        } else {
                            System.out.println("NO");
                        }
                        // The original logic terminates immediately upon finding the first pattern.
                        return;
                    }
                }
            }

            // If no valid plus pattern is found after scanning the entire grid
            System.out.println("NO");
        }
    }

    /**
     * Checks if the specific 5-star pattern exists at the given center coordinates.
     */
    private static boolean hasPlusPattern(char[][] grid, int r, int c) {
        return grid[r][c] == STAR &&
               grid[r][c - 1] == STAR &&
               grid[r][c + 1] == STAR &&
               grid[r - 1][c] == STAR &&
               grid[r + 1][c] == STAR;
    }

    /**
     * Checks if the arms of the plus sign extending from the center are valid.
     * 
     * Logic preserved from original 'isplus' method:
     * Scans outwards from center. 
     * - If a dot ('.') is encountered, it marks the arm state as -1.
     * - If a star ('*') is encountered AFTER a dot (state -1), it marks the arm as invalid (0).
     * - An arm is considered valid if it does not end in state 0.
     * Essentially, this logic forbids the pattern where a star appears after a gap (dot) 
     * in the outward direction from the center.
     */
    private static boolean isPlusArmValid(char[][] grid, int centerR, int centerC, int rows, int cols) {
        // Check all 4 directions: Up, Down, Left, Right
        if (!checkDirection(grid, centerR, centerC, -1, 0, rows, cols)) return false; // Up
        if (!checkDirection(grid, centerR, centerC, 1, 0, rows, cols))  return false; // Down
        if (!checkDirection(grid, centerR, centerC, 0, -1, rows, cols)) return false; // Left
        if (!checkDirection(grid, centerR, centerC, 0, 1, rows, cols))  return false; // Right

        return true;
    }

    /**
     * Helper method to check validity of a single arm direction.
     */
    private static boolean checkDirection(char[][] grid, int r, int c, int dr, int dc, int rows, int cols) {
        int flag = 1; // 1: Valid (all stars or stars then dots), -1: Saw dot, 0: Saw dot then star (Invalid)

        int currR = r + dr;
        int currC = c + dc;

        while (currR >= 0 && currR < rows && currC >= 0 && currC < cols) {
            char cell = grid[currR][currC];

            if (cell == EMPTY) {
                flag = -1;
            } else if (cell == STAR && flag == -1) {
                // Saw a dot previously, now seeing a star. This is the invalid pattern.
                flag = 0;
                break; // Original logic breaks here upon finding invalid pattern
            }

            currR += dr;
            currC += dc;
        }

        // Valid if flag is not 0. 
        // 1 means we never saw a dot (all stars).
        // -1 means we saw a dot but never a star after it (stars then dots, or just dots).
        return flag != 0;
    }

    /**
     * Checks if there are any stars in the grid outside the cross shape defined by
     * the center row and center column.
     */
    private static boolean hasStarsOutsideCross(char[][] grid, int centerR, int centerC, int rows, int cols) {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                // Skip cells that are part of the cross (same row or same column as center)
                // This corresponds to the logic (r != i && c != j) in the original code
                if (r == centerR || c == centerC) {
                    continue;
                }

                if (grid[r][c] == STAR) {
                    return false; // Found a star outside the cross
                }
            }
        }
        return true; // No stars found outside
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

public class PlusFromPicture {
    // Direction vectors for checking immediate neighbors (Up, Down, Left, Right)
    private static final int[] NEIGHBOR_DR = {-1, 1, 0, 0};
    private static final int[] NEIGHBOR_DC = {0, 0, -1, 1};

    // Direction vectors for scanning arms (Down, Up, Right, Left)
    private static final int[] SCAN_DR = {1, -1, 0, 0};
    private static final int[] SCAN_DC = {0, 0, 1, -1};

    private final int rows;
    private final int cols;
    private final char[][] grid;
    private final int totalStars;

    public PlusFromPicture() throws IOException {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));

        // Read dimensions
        String line = reader.readLine();
        if (line == null) return;

        StringTokenizer tokenizer = new StringTokenizer(line);
        if (!tokenizer.hasMoreTokens()) return;

        this.rows = Integer.parseInt(tokenizer.nextToken());
        this.cols = Integer.parseInt(tokenizer.nextToken());

        // Initialize grid with padding (1-based indexing for data)
        // Padding at index 0 and index (size+1) acts as boundaries.
        // Default char is '\0', which is not '*', ensuring safe boundary checks.
        this.grid = new char[rows + 2][cols + 2];
        this.totalStars = 0;

        // Read grid data
        for (int i = 1; i <= rows; i++) {
            String rowLine = reader.readLine();
            if (rowLine != null) {
                for (int j = 1; j <= cols; j++) {
                    // Handle potential short lines gracefully
                    char c = (j - 1 < rowLine.length()) ? rowLine.charAt(j - 1) : ' ';
                    this.grid[i][j] = c;
                    if (c == '*') {
                        this.totalStars++;
                    }
                }
            }
        }
    }

    public void solve() {
        for (int r = 1; r <= rows; r++) {
            for (int c = 1; c <= cols; c++) {
                if (grid[r][c] == '*') {
                    // Check if this star has '*' in all 4 orthogonal directions
                    boolean isCenter = true;
                    for (int k = 0; k < 4; k++) {
                        // Accessing padding indices (0 or rows+1) is safe due to array size
                        if (grid[r + NEIGHBOR_DR[k]][c + NEIGHBOR_DC[k]] != '*') {
                            isCenter = false;
                            break;
                        }
                    }

                    if (isCenter) {
                        int crossSize = calculateCrossSize(r, c);
                        if (crossSize == totalStars) {
                            System.out.println("YES");
                            return;
                        }
                    }
                }
            }
        }
        System.out.println("NO");
    }

    private int calculateCrossSize(int r, int c) {
        int count = 0;

        for (int k = 0; k < 4; k++) {
            int currR = r + SCAN_DR[k];
            int currC = c + SCAN_DC[k];

            // Traverse in the current direction as long as we encounter stars.
            // Explicit bounds check ensures we stay within the valid data area (1 to rows/cols).
            while (currR >= 1 && currR <= rows && currC >= 1 && currC <= cols && 
                   grid[currR][currC] == '*') {
                count++;
                currR += SCAN_DR[k];
                currC += SCAN_DC[k];
            }
        }
        return count + 1; // Add 1 for the center star itself
    }

    public static void main(String[] args) throws IOException {
        new PlusFromPicture().solve();
    }
}

import java.util.Scanner;

/**
 * Refactored version of PlusfromPicture.
 * This class analyzes a grid to determine if it contains exactly one plus sign
 * composed entirely of asterisks ('*').
 */
public class PlusSignChecker {

    // Encapsulated state instead of static fields for better maintainability
    private final char[][] grid;
    private final int height;
    private final int width;

    /**
     * Constructor that initializes the grid by reading input from the Scanner.
     *
     * @param scanner The scanner to read input from.
     */
    public PlusSignChecker(Scanner scanner) {
        if (!scanner.hasNextInt()) {
            return;
        }
        this.height = scanner.nextInt();
        this.width = scanner.nextInt();
        this.grid = new char[height][width];

        // Read the grid rows
        for (int i = 0; i < height; i++) {
            String row = scanner.next();
            this.grid[i] = row.toCharArray();
        }
    }

    /**
     * Main logic to solve the problem.
     */
    public void solve() {
        int totalStars = countTotalStars();

        // A valid plus sign requires at least 5 stars (1 center + 4 arms of length 1)
        if (totalStars < 5) {
            System.out.println("NO");
            return;
        }

        boolean found = false;

        // Iterate through the grid to find a potential center.
        // The center cannot be on the border (index 0 or max-1) because it needs neighbors in all 4 directions.
        for (int r = 1; r < height - 1; r++) {
            for (int c = 1; c < width - 1; c++) {
                if (grid[r][c] == '*') {
                    // Check if this cell is the center of a plus sign
                    if (isCenter(r, c)) {
                        int plusSize = calculatePlusSize(r, c);
                        // If the size of the plus sign equals the total number of stars in the grid,
                        // then the grid consists of exactly one plus sign.
                        if (plusSize == totalStars) {
                            found = true;
                            break;
                        }
                    }
                }
            }
            if (found) {
                break;
            }
        }

        System.out.println(found ? "YES" : "NO");
    }

    /**
     * Counts the total number of asterisks in the grid.
     *
     * @return The count of '*' characters.
     */
    private int countTotalStars() {
        int count = 0;
        for (char[] row : grid) {
            for (char cell : row) {
                if (cell == '*') {
                    count++;
                }
            }
        }
        return count;
    }

    /**
     * Checks if the cell at (r, c) is the center of a plus sign.
     * A center must have asterisks in all four cardinal directions (Up, Down, Left, Right).
     *
     * @param r The row index.
     * @param c The column index.
     * @return true if valid center, false otherwise.
     */
    private boolean isCenter(int r, int c) {
        return grid[r - 1][c] == '*' &&
               grid[r + 1][c] == '*' &&
               grid[r][c - 1] == '*' &&
               grid[r][c + 1] == '*';
    }

    /**
     * Calculates the total number of stars in the plus sign centered at (r, c).
     *
     * @param r The row index of the center.
     * @param c The column index of the center.
     * @return The count of stars forming the plus sign.
     */
    private int calculatePlusSize(int r, int c) {
        int size = 1; // Start with the center star

        // Count stars extending to the Right
        int curr = c + 1;
        while (curr < width && grid[r][curr] == '*') {
            size++;
            curr++;
        }

        // Count stars extending to the Left
        curr = c - 1;
        while (curr >= 0 && grid[r][curr] == '*') {
            size++;
            curr--;
        }

        // Count stars extending Down
        curr = r + 1;
        while (curr < height && grid[curr][c] == '*') {
            size++;
            curr++;
        }

        // Count stars extending Up
        curr = r - 1;
        while (curr >= 0 && grid[curr][c] == '*') {
            size++;
            curr--;
        }

        return size;
    }

    public static void main(String[] args) {
        // Use try-with-resources to ensure Scanner is closed properly
        try (Scanner sc = new Scanner(System.in)) {
            PlusSignChecker checker = new PlusSignChecker(sc);
            checker.solve();
        }
    }
}

import java.util.Scanner;

public class Main {
    // Direction vectors: Up, Right, Down, Left
    // Using parallel arrays or a 2D array is cleaner than magic numbers.
    private static final int[] DR = {-1, 0, 1, 0};
    private static final int[] DC = {0, 1, 0, -1};

    public static void main(String[] args) {
        // Use try-with-resources to ensure the Scanner is closed automatically.
        // This prevents resource leaks and is a best practice.
        try (Scanner sc = new Scanner(System.in)) {
            // Check if input exists to prevent exceptions on empty input
            if (!sc.hasNextInt()) {
                return;
            }

            int rows = sc.nextInt();
            int cols = sc.nextInt();

            char[][] grid = new char[rows][cols];
            for (int r = 0; r < rows; r++) {
                String line = sc.next();
                for (int c = 0; c < cols; c++) {
                    grid[r][c] = line.charAt(c);
                }
            }

            System.out.println(solve(grid) ? "YES" : "NO");
        }
    }

    /**
     * Determines if the grid contains a 'cross' pattern that covers all stars.
     * A valid cross requires a center star with arms extending in all 4 directions.
     */
    private static boolean solve(char[][] grid) {
        int totalStars = countTotalStars(grid);
        int rows = grid.length;
        int cols = grid[0].length;

        // A cross center must have neighbors in all 4 directions, 
        // so it cannot be on the border (indices 0 or max).
        for (int r = 1; r < rows - 1; r++) {
            for (int c = 1; c < cols - 1; c++) {
                if (grid[r][c] == '*') {
                    // Check if immediate neighbors form the arms of the cross.
                    // This ensures the cross has a minimum size (length >= 1 in all directions).
                    if (hasCrossArms(grid, r, c)) {
                        int crossLength = computeCrossLength(grid, r, c);
                        if (crossLength == totalStars) {
                            return true;
                        }
                    }
                }
            }
        }
        return false;
    }

    /**
     * Checks if the cell at (r, c) has star neighbors in all 4 cardinal directions.
     */
    private static boolean hasCrossArms(char[][] grid, int r, int c) {
        return grid[r - 1][c] == '*' && grid[r][c + 1] == '*' &&
               grid[r + 1][c] == '*' && grid[r][c - 1] == '*';
    }

    /**
     * Counts the total number of stars in the grid.
     */
    private static int countTotalStars(char[][] grid) {
        int count = 0;
        for (char[] row : grid) {
            for (char cell : row) {
                if (cell == '*') {
                    count++;
                }
            }
        }
        return count;
    }

    /**
     * Computes the total number of stars covered by a cross centered at (centerR, centerC).
     * This includes the center star plus all connected stars in the 4 directions.
     */
    private static int computeCrossLength(char[][] grid, int centerR, int centerC) {
        int length = 1; // Count the center star
        for (int i = 0; i < DR.length; i++) {
            length += countRayLength(grid, centerR, centerC, DR[i], DC[i]);
        }
        return length;
    }

    /**
     * Counts the number of consecutive stars in a specific direction from the center.
     */
    private static int countRayLength(char[][] grid, int startR, int startC, int deltaR, int deltaC) {
        int count = 0;
        int r = startR + deltaR;
        int c = startC + deltaC;
        int rows = grid.length;
        int cols = grid[0].length;

        // Traverse in the direction until boundary or non-star cell is reached
        while (r >= 0 && r < rows && c >= 0 && c < cols && grid[r][c] == '*') {
            count++;
            r += deltaR;
            c += deltaC;
        }
        return count;
    }
}

import java.util.Scanner;

/**
 * Refactored Star Pattern Validator.
 * 
 * Refactoring Notes:
 * 1. Encapsulation: Moved static fields to instance variables to prevent state leakage.
 * 2. Naming: Renamed variables for clarity (e.g., 'r' -> 'centerRow', 'array' -> 'grid').
 * 3. Dead Code Removal: Removed unused 'TreeSet' imports and variables.
 * 4. Modularity: Split logic into distinct methods (Input, Search, Validation).
 * 5. Safety: Added basic input validation.
 */
public class Main {
    // Instance variables to hold state
    private int rows;
    private int cols;
    private char[][] grid;
    private int centerRow;
    private int centerCol;

    public static void main(String[] args) {
        Main validator = new Main();
        // Execute logic and print result
        if (validator.run()) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }
    }

    /**
     * Main execution flow: Reads input, finds cross, validates grid.
     */
    private boolean run() {
        Scanner scanner = new Scanner(System.in);

        // Ensure input exists
        if (!scanner.hasNextInt()) {
            return false;
        }

        this.rows = scanner.nextInt();
        this.cols = scanner.nextInt();
        this.grid = new char[this.rows][this.cols];

        // Read the grid content
        for (int i = 0; i < this.rows; i++) {
            String line = scanner.next();
            for (int j = 0; j < this.cols; j++) {
                this.grid[i][j] = line.charAt(j);
            }
        }

        // Step 1: Locate the center of the cross
        if (!findCrossCenter()) {
            return false;
        }

        // Step 2: Validate the grid configuration against the found center
        return validateGrid();
    }

    /**
     * Searches for a 'cross' center (a '*' surrounded by '*' in all 4 directions).
     */
    private boolean findCrossCenter() {
        // Iterate through the interior of the grid
        for (int i = 1; i < this.rows - 1; i++) {
            for (int j = 1; j < this.cols - 1; j++) {
                if (isStar(i, j) && isStar(i + 1, j) && isStar(i - 1, j) &&
                    isStar(i, j + 1) && isStar(i, j - 1)) {

                    this.centerRow = i;
                    this.centerCol = j;
                    return true;
                }
            }
        }
        return false;
    }

    /**
     * Validates the grid based on the found cross center.
     * Checks constraints regarding star placement and boundaries.
     */
    private boolean validateGrid() {
        // Constraint 1: No stars allowed outside the cross's row or column.
        // (Stars must be in the same row OR same column as the center)
        for (int i = 0; i < this.rows; i++) {
            for (int j = 0; j < this.cols; j++) {
                if (grid[i][j] == '*' && (this.centerRow != i && this.centerCol != j)) {
                    return false;
                }
            }
        }

        // Constraint 2: Boundary checks (Preserving original logic structure)

        // Check horizontal line to the left of center
        for (int i = this.centerCol; i >= 0; i--) {
            if (grid[this.centerRow][i] == '*' && grid[this.centerRow][i + 1] == '.') {
                return false;
            }
        }

        // Check horizontal line to the right of center
        for (int i = this.centerCol; i < this.cols; i++) {
            if (grid[this.centerRow][i] == '*' && grid[this.centerRow][i - 1] == '.') {
                return false;
            }
        }

        // Check vertical line above center
        for (int i = this.centerRow; i >= 0; i--) {
            if (grid[i][this.centerCol] == '*' && grid[i + 1][this.centerCol] == '.') {
                return false;
            }
        }

        // Check vertical line below center
        for (int i = this.centerRow; i < this.rows; i++) {
            if (grid[i][this.centerCol] == '*' && grid[i - 1][this.centerCol] == '.') {
                return false;
            }
        }

        return true;
    }

    /**
     * Helper method to check if a cell contains a star.
     */
    private boolean isStar(int r, int c) {
        return grid[r][c] == '*';
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;

/**
 * Solution to determine if all stars in a grid form a valid cross pattern.
 * A valid cross pattern consists of a center star with contiguous stars extending
 * in all four cardinal directions (up, down, left, right), covering exactly all stars in the grid.
 */
public class Solution {

    public static void main(String[] args) {
        // Use try-with-resources to ensure BufferedReader is properly closed
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(System.in))) {
            String line = reader.readLine();
            if (line == null) return;

            String[] dimensions = line.trim().split("\\s+");
            int rows = Integer.parseInt(dimensions[0]);
            int cols = Integer.parseInt(dimensions[1]);

            // Edge case: A single cell cannot form a cross
            if (rows == 1 && cols == 1) {
                System.out.println("NO");
                return;
            }

            char[][] grid = new char[rows][cols];
            int totalStars = 0;

            // Read grid and count total stars
            for (int i = 0; i < rows; i++) {
                String rowLine = reader.readLine();
                if (rowLine == null) break;
                grid[i] = rowLine.trim().toCharArray();
                for (char c : grid[i]) {
                    if (c == '*') {
                        totalStars++;
                    }
                }
            }

            // Evaluate pattern and print result
            System.out.println(isCrossPattern(grid, rows, cols, totalStars) ? "YES" : "NO");

        } catch (IOException e) {
            System.err.println("Error reading input: " + e.getMessage());
        } catch (NumberFormatException e) {
            System.err.println("Invalid input format: " + e.getMessage());
        }
    }

    /**
     * Checks if the grid contains a valid cross pattern covering all stars.
     *
     * @param grid       2D character array representing the grid
     * @param rows       Number of rows
     * @param cols       Number of columns
     * @param totalStars Total number of '*' characters in the grid
     * @return true if a valid cross pattern exists, false otherwise
     */
    private static boolean isCrossPattern(char[][] grid, int rows, int cols, int totalStars) {
        // Direction vectors: Up, Down, Left, Right
        int[] dRow = {-1, 1, 0, 0};
        int[] dCol = {0, 0, -1, 1};

        // Only interior cells can be the center of a cross
        for (int r = 1; r < rows - 1; r++) {
            for (int c = 1; c < cols - 1; c++) {
                if (grid[r][c] == '*') {
                    int countedCells = 1; // Start with the center star
                    boolean[] directionVisited = new boolean[4];

                    // Traverse in all 4 cardinal directions
                    for (int d = 0; d < 4; d++) {
                        int nr = r + dRow[d];
                        int nc = c + dCol[d];

                        while (nr >= 0 && nr < rows && nc >= 0 && nc < cols && grid[nr][nc] == '*') {
                            countedCells++;
                            directionVisited[d] = true;
                            nr += dRow[d];
                            nc += dCol[d];
                        }
                    }

                    // Valid cross must:
                    // 1. Cover exactly all stars in the grid
                    // 2. Have stars extending in all 4 directions
                    if (countedCells == totalStars &&
                        directionVisited[0] && directionVisited[1] &&
                        directionVisited[2] && directionVisited[3]) {
                        return true;
                    }
                }
            }
        }
        return false;
    }
}

import java.util.Scanner;

public class Main {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        // Read grid dimensions
        if (!scanner.hasNextInt()) {
            return;
        }
        int rows = scanner.nextInt();
        int cols = scanner.nextInt();

        char[][] grid = new char[rows][];
        int totalStars = 0;

        // Read grid data and count the total number of stars
        for (int i = 0; i < rows; i++) {
            if (scanner.hasNext()) {
                String line = scanner.next();
                grid[i] = line.toCharArray();
                for (char c : grid[i]) {
                    if (c == '*') {
                        totalStars++;
                    }
                }
            }
        }

        boolean foundPlusShape = false;

        // Iterate through each cell to check if it can be the center of a valid plus shape
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                // The center of the plus shape must be a star
                if (grid[r][c] != '*') {
                    continue;
                }

                // A valid plus shape requires arms extending in all 4 directions.
                // We check immediate neighbors first to ensure arms exist (length >= 1).
                // If a neighbor is out of bounds or not a star, this center is invalid.
                if (r == 0 || grid[r - 1][c] != '*') continue; // Up
                if (r == rows - 1 || grid[r + 1][c] != '*') continue; // Down
                if (c == 0 || grid[r][c - 1] != '*') continue; // Left
                if (c == cols - 1 || grid[r][c + 1] != '*') continue; // Right

                // Count consecutive stars extending from the center in each direction
                int upCount = countConsecutiveStars(grid, r - 1, c, -1, 0);
                int downCount = countConsecutiveStars(grid, r + 1, c, 1, 0);
                int leftCount = countConsecutiveStars(grid, r, c - 1, 0, -1);
                int rightCount = countConsecutiveStars(grid, r, c + 1, 0, 1);

                // The sum of stars in the cross shape (including the center) must equal 
                // the total number of stars in the entire grid.
                if (upCount + downCount + leftCount + rightCount + 1 == totalStars) {
                    foundPlusShape = true;
                    break;
                }
            }
            if (foundPlusShape) {
                break;
            }
        }

        System.out.println(foundPlusShape ? "YES" : "NO");
        scanner.close();
    }

    /**
     * Counts consecutive stars starting from a specific position in a specific direction.
     *
     * @param grid The character grid
     * @param startRow Starting row index
     * @param startCol Starting column index
     * @param dRow Direction row increment (-1, 0, or 1)
     * @param dCol Direction column increment (-1, 0, or 1)
     * @return Number of consecutive stars found
     */
    private static int countConsecutiveStars(char[][] grid, int startRow, int startCol, int dRow, int dCol) {
        int count = 0;
        int r = startRow;
        int c = startCol;

        // Traverse in the given direction as long as we are within bounds and find stars
        while (r >= 0 && r < grid.length && c >= 0 && c < grid[0].length && grid[r][c] == '*') {
            count++;
            r += dRow;
            c += dCol;
        }

        return count;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.OutputStream;
import java.io.PrintWriter;
import java.util.StringTokenizer;

public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        FastReader in = new FastReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        CrossPatternValidator solver = new CrossPatternValidator();
        solver.solve(in, out);
        out.close();
    }

    /**
     * Validates whether all '*' characters in the grid form a single contiguous cross.
     * A valid cross requires a center point with '*' in all four cardinal directions,
     * and every '*' in the grid must lie on the contiguous arms extending from that center.
     */
    static class CrossPatternValidator {
        private static final String RESULT_YES = "YES";
        private static final String RESULT_NO = "NO";

        public void solve(FastReader in, PrintWriter out) {
            int n = in.nextInt();
            int m = in.nextInt();

            boolean[][] grid = new boolean[n][m];
            int totalStars = 0;

            // Read grid and count total '*' characters
            for (int i = 0; i < n; i++) {
                String row = in.next();
                for (int j = 0; j < m; j++) {
                    if (row.charAt(j) == '*') {
                        grid[i][j] = true;
                        totalStars++;
                    }
                }
            }

            // Locate a valid center point
            int centerRow = -1;
            int centerCol = -1;
            for (int i = 1; i < n - 1; i++) {
                for (int j = 1; j < m - 1; j++) {
                    if (grid[i][j] && grid[i - 1][j] && grid[i + 1][j] &&
                        grid[i][j - 1] && grid[i][j + 1]) {
                        centerRow = i;
                        centerCol = j;
                        break;
                    }
                }
                if (centerRow != -1) break;
            }

            if (centerRow == -1) {
                out.println(RESULT_NO);
                return;
            }

            // Mark all contiguous '*' forming the cross from the center
            boolean[][] onCross = new boolean[n][m];
            markContiguousArms(grid, centerRow, centerCol, onCross);

            // Verify that every '*' in the grid belongs to the cross
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    if (grid[i][j] && !onCross[i][j]) {
                        out.println(RESULT_NO);
                        return;
                    }
                }
            }

            out.println(RESULT_YES);
        }

        /**
         * Marks all contiguous '*' cells in the four cardinal directions from the center.
         */
        private void markContiguousArms(boolean[][] grid, int cr, int cc, boolean[][] onCross) {
            int[] dr = {-1, 1, 0, 0};
            int[] dc = {0, 0, -1, 1};

            for (int d = 0; d < 4; d++) {
                int r = cr;
                int c = cc;
                while (r >= 0 && r < grid.length && c >= 0 && c < grid[0].length && grid[r][c]) {
                    onCross[r][c] = true;
                    r += dr[d];
                    c += dc[d];
                }
            }
        }
    }

    /**
     * Optimized input reader for handling large volumes of whitespace-delimited tokens.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input", e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            String s = next();
            return s == null ? 0 : Integer.parseInt(s);
        }
    }
}

import java.util.Scanner;

/**
 * Checks if all '*' characters in a grid form a single connected plus shape.
 * A valid plus shape requires a center cell with '*' in all four cardinal directions,
 * and all '*' cells in the grid must lie on the same row or column intersecting at that center.
 */
public class Main {
    private static final char PLUS_CHAR = '*';
    private static final String RESULT_YES = "YES";
    private static final String RESULT_NO = "NO";
    private static final int[][] DIRECTIONS = {{-1, 0}, {0, 1}, {1, 0}, {0, -1}};

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        if (!scanner.hasNextInt()) {
            scanner.close();
            return;
        }

        int rows = scanner.nextInt();
        int cols = scanner.nextInt();

        char[][] grid = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            grid[i] = scanner.next().toCharArray();
        }
        scanner.close();

        System.out.println(solve(grid, rows, cols));
    }

    /**
     * Determines if all plus characters form a single valid plus shape.
     */
    private static String solve(char[][] grid, int rows, int cols) {
        // A plus shape requires at least a 3x3 area
        if (rows <= 2 || cols <= 2) {
            return RESULT_NO;
        }

        int centerRow = -1;
        int centerCol = -1;

        // Find the center of the plus shape
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == PLUS_CHAR && isPlusCenter(i, j, grid, rows, cols)) {
                    centerRow = i;
                    centerCol = j;
                    break;
                }
            }
            if (centerRow != -1) {
                break;
            }
        }

        // If no valid center is found, it cannot be a plus shape
        if (centerRow == -1) {
            return RESULT_NO;
        }

        // Mark all cells that are part of the plus shape extending from the center
        boolean[][] visited = new boolean[rows][cols];
        markCrossCells(centerRow, centerCol, grid, visited, rows, cols);

        // Verify that every plus character in the grid was visited
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == PLUS_CHAR && !visited[i][j]) {
                    return RESULT_NO;
                }
            }
        }

        return RESULT_YES;
    }

    /**
     * Checks if the given cell is a valid center for a plus shape.
     * A valid center must have '*' in all four adjacent cells.
     */
    private static boolean isPlusCenter(int row, int col, char[][] grid, int rows, int cols) {
        for (int[] dir : DIRECTIONS) {
            int nextRow = row + dir[0];
            int nextCol = col + dir[1];
            if (!isInBounds(nextRow, nextCol, rows, cols) || grid[nextRow][nextCol] != PLUS_CHAR) {
                return false;
            }
        }
        return true;
    }

    /**
     * Marks all cells connected to the center in the four cardinal directions.
     * Traces straight lines until a non-plus character or grid boundary is reached.
     */
    private static void markCrossCells(int row, int col, char[][] grid, boolean[][] visited, int rows, int cols) {
        visited[row][col] = true;

        for (int[] dir : DIRECTIONS) {
            int r = row + dir[0];
            int c = col + dir[1];
            while (isInBounds(r, c, rows, cols) && grid[r][c] == PLUS_CHAR) {
                visited[r][c] = true;
                r += dir[0];
                c += dir[1];
            }
        }
    }

    /**
     * Checks if the given coordinates are within the grid boundaries.
     */
    private static boolean isInBounds(int row, int col, int rows, int cols) {
        return row >= 0 && row < rows && col >= 0 && col < cols;
    }
}

import java.util.Scanner;

public class StarShapeValidator {
    // Cell state constants
    private static final int EMPTY = 0;
    private static final int FILLED = 1;

    // Direction vectors: UP, RIGHT, DOWN, LEFT
    private static final int[] DIR_X = {-1, 0, 1, 0};
    private static final int[] DIR_Y = {0, 1, 0, -1};

    public static void main(String[] args) {
        // Use try-with-resources to automatically close the Scanner
        try (Scanner scanner = new Scanner(System.in)) {
            if (!scanner.hasNextInt()) return;

            int rows = scanner.nextInt();
            int cols = scanner.nextInt();
            scanner.nextLine(); // Consume the newline after the last integer

            if (rows <= 0 || cols <= 0) {
                System.out.println("NO");
                return;
            }

            int[][] grid = readGrid(scanner, rows, cols);
            if (!hasAnyFilledCell(grid)) {
                System.out.println("NO");
                return;
            }

            int[] center = findCenter(grid);
            if (center == null) {
                System.out.println("NO");
                return;
            }

            boolean[][] visited = new boolean[rows][cols];
            traverseArms(grid, center[0], center[1], visited);

            System.out.println(allFilledCellsVisited(grid, visited) ? "YES" : "NO");
        }
    }

    /**
     * Reads the grid from input and converts it to a 2D integer array.
     * '.' becomes EMPTY (0), any other character becomes FILLED (1).
     */
    private static int[][] readGrid(Scanner scanner, int rows, int cols) {
        int[][] grid = new int[rows][cols];
        for (int i = 0; i < rows; i++) {
            String line = scanner.nextLine().trim();
            for (int j = 0; j < cols; j++) {
                // Safely handle lines that might be shorter than expected
                boolean isDot = j < line.length() && line.charAt(j) == '.';
                grid[i][j] = isDot ? EMPTY : FILLED;
            }
        }
        return grid;
    }

    /**
     * Checks if the grid contains at least one filled cell.
     */
    private static boolean hasAnyFilledCell(int[][] grid) {
        for (int[] row : grid) {
            for (int cell : row) {
                if (cell == FILLED) {
                    return true;
                }
            }
        }
        return false;
    }

    /**
     * Finds the center of the star shape.
     * The center must be a filled cell surrounded by filled cells in all 4 directions.
     * Returns null if no valid center is found.
     */
    private static int[] findCenter(int[][] grid) {
        int rows = grid.length;
        int cols = grid[0].length;

        for (int i = 1; i < rows - 1; i++) {
            for (int j = 1; j < cols - 1; j++) {
                if (grid[i][j] == FILLED &&
                    grid[i - 1][j] == FILLED && grid[i + 1][j] == FILLED &&
                    grid[i][j - 1] == FILLED && grid[i][j + 1] == FILLED) {
                    return new int[]{i, j};
                }
            }
        }
        return null;
    }

    /**
     * Initiates traversal of all four arms from the center.
     */
    private static void traverseArms(int[][] grid, int r, int c, boolean[][] visited) {
        for (int dir = 0; dir < 4; dir++) {
            traverseArm(grid, r, c, dir, visited);
        }
    }

    /**
     * Recursively traverses a single arm in the specified direction.
     * Marks visited cells to ensure they are part of the star structure.
     */
    private static void traverseArm(int[][] grid, int r, int c, int dir, boolean[][] visited) {
        // Base case: out of bounds or hit an empty cell
        if (r < 0 || r >= grid.length || c < 0 || c >= grid[0].length || grid[r][c] == EMPTY) {
            return;
        }

        visited[r][c] = true;

        // Move to the next cell in the current direction
        int nextR = r + DIR_X[dir];
        int nextC = c + DIR_Y[dir];
        traverseArm(grid, nextR, nextC, dir, visited);
    }

    /**
     * Verifies that every filled cell in the grid has been visited.
     */
    private static boolean allFilledCellsVisited(int[][] grid, boolean[][] visited) {
        for (int i = 0; i < grid.length; i++) {
            for (int j = 0; j < grid[0].length; j++) {
                if (grid[i][j] == FILLED && !visited[i][j]) {
                    return false;
                }
            }
        }
        return true;
    }
}

import java.util.Scanner;

public class Main {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        if (!scanner.hasNextInt()) {
            return;
        }

        int n = scanner.nextInt();
        int m = scanner.nextInt();

        char[][] grid = new char[n][m];
        int totalStars = 0;

        // Read grid and count total stars in a single pass
        for (int i = 0; i < n; i++) {
            String row = scanner.next();
            grid[i] = row.toCharArray();
            for (char c : grid[i]) {
                if (c == '*') {
                    totalStars++;
                }
            }
        }

        boolean isValid = findValidDot(grid, n, m, totalStars);
        System.out.println(isValid ? "YES" : "NO");
    }

    /**
     * Checks if there exists a '.' cell that has stars in all four cardinal directions
     * and the total count of those stars plus the cell itself equals the total stars in the grid.
     */
    private static boolean findValidDot(char[][] grid, int n, int m, int totalStars) {
        // A valid dot requires at least one cell in each direction
        if (n < 3 || m < 3) {
            return false;
        }

        for (int i = 1; i < n - 1; i++) {
            for (int j = 1; j < m - 1; j++) {
                if (grid[i][j] == '*') {
                    continue;
                }

                int left = countStarsInDirection(grid, i, j - 1, 0, -1);
                int right = countStarsInDirection(grid, i, j + 1, 0, 1);
                int up = countStarsInDirection(grid, i - 1, j, -1, 0);
                int down = countStarsInDirection(grid, i + 1, j, 1, 0);

                // Condition: all directions must have stars, and total matches grid star count
                if (left > 0 && right > 0 && up > 0 && down > 0 &&
                    (1 + left + right + up + down) == totalStars) {
                    return true;
                }
            }
        }
        return false;
    }

    /**
     * Counts consecutive stars starting from (startRow, startCol) moving in the given direction.
     */
    private static int countStarsInDirection(char[][] grid, int startRow, int startCol, 
                                             int rowStep, int colStep) {
        int count = 0;
        int r = startRow;
        int c = startCol;

        while (r >= 0 && r < grid.length && c >= 0 && c < grid[0].length && grid[r][c] == '*') {
            count++;
            r += rowStep;
            c += colStep;
        }
        return count;
    }
}

import java.util.Scanner;

/**
 * Analyzes a grid of characters to determine if it contains a specific 
 * "cross" pattern of stars ('*') that, when removed, clears the entire grid.
 * 
 * Logic:
 * 1. Identify a unique star that has stars in all 4 cardinal directions (Up, Down, Left, Right).
 * 2. If such a star exists exactly once, remove it and all contiguous stars extending 
 *    horizontally and vertically from it.
 * 3. If the grid is completely empty of stars after this operation, output "YES".
 */
public class StarGridSolver {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        // 1. Read grid dimensions
        if (!scanner.hasNextLine()) {
            return;
        }
        // Use regex \\s+ to handle multiple spaces between numbers robustly
        String[] dimensions = scanner.nextLine().trim().split("\\s+");
        int rows = Integer.parseInt(dimensions[0]);
        int cols = Integer.parseInt(dimensions[1]);

        // 2. Read the grid content
        char[][] grid = new char[rows][];
        for (int i = 0; i < rows; i++) {
            if (scanner.hasNextLine()) {
                grid[i] = scanner.nextLine().toCharArray();
            }
        }

        // 3. Find the unique crossing star
        int targetRow = -1;
        int targetCol = -1;
        int crossingCount = 0;

        // Iterate through inner cells. 
        // A crossing star cannot be on the border because it needs neighbors in all 4 directions.
        for (int i = 1; i < rows - 1; i++) {
            for (int j = 1; j < cols - 1; j++) {
                if (isCrossingStar(grid, i, j)) {
                    crossingCount++;
                    targetRow = i;
                    targetCol = j;
                }
            }
        }

        // 4. Validate that exactly one crossing star exists
        // Original logic: if count == 0 || count >= 2 -> NO
        if (crossingCount != 1) {
            System.out.println("NO");
            return;
        }

        // 5. Clear the cross shape centered at the target
        clearCrossShape(grid, targetRow, targetCol, rows, cols);

        // 6. Verify that no stars remain in the grid
        if (gridContainsStars(grid)) {
            System.out.println("NO");
        } else {
            System.out.println("YES");
        }

        scanner.close();
    }

    /**
     * Checks if the cell at (row, col) and its 4 immediate neighbors are all stars ('*').
     */
    private static boolean isCrossingStar(char[][] grid, int row, int col) {
        // Check center
        if (grid[row][col] != '*') return false;

        // Check neighbors (Up, Down, Left, Right)
        // Note: Boundary checks are handled by the loop bounds in main method
        return grid[row - 1][col] == '*' &&
               grid[row + 1][col] == '*' &&
               grid[row][col - 1] == '*' &&
               grid[row][col + 1] == '*';
    }

    /**
     * Removes the center star and extends horizontally and vertically 
     * removing contiguous stars until a non-star character or boundary is reached.
     */
    private static void clearCrossShape(char[][] grid, int r, int c, int rows, int cols) {
        // Clear the center star
        grid[r][c] = '.';

        // Clear to the Left
        for (int col = c - 1; col >= 0; col--) {
            if (grid[r][col] != '*') {
                break;
            }
            grid[r][col] = '.';
        }

        // Clear to the Right
        for (int col = c + 1; col < cols; col++) {
            if (grid[r][col] != '*') {
                break;
            }
            grid[r][col] = '.';
        }

        // Clear Upwards
        for (int row = r - 1; row >= 0; row--) {
            if (grid[row][c] != '*') {
                break;
            }
            grid[row][c] = '.';
        }

        // Clear Downwards
        for (int row = r + 1; row < rows; row++) {
            if (grid[row][c] != '*') {
                break;
            }
            grid[row][c] = '.';
        }
    }

    /**
     * Checks if the grid still contains any star characters.
     */
    private static boolean gridContainsStars(char[][] grid) {
        for (char[] row : grid) {
            for (char cell : row) {
                if (cell == '*') {
                    return true;
                }
            }
        }
        return false;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

/**
 * Checks if all '*' characters in the grid form a valid connected cross pattern.
 * A valid pattern requires a central '*' cell with '*' neighbors in all 4 cardinal directions,
 * and all '*' cells in the grid must be reachable from this center by moving straight in one direction.
 */
public class GridStarChecker {

    // Direction vectors: Down, Up, Left, Right
    private static final int[] DX = {1, -1, 0, 0};
    private static final int[] DY = {0, 0, -1, 1};

    public static void main(String[] args) {
        FastReader reader = new FastReader();
        int n = reader.nextInt();
        int m = reader.nextInt();

        char[][] grid = new char[n][m];
        for (int i = 0; i < n; i++) {
            grid[i] = reader.next().toCharArray();
        }

        boolean[][] visited = new boolean[n][m];
        boolean foundCenter = false;

        // Find the first valid center cell
        outerLoop:
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (isStarCenter(grid, i, j)) {
                    foundCenter = true;
                    // Mark all cells in the 4 straight lines from the center
                    for (int k = 0; k < 4; k++) {
                        traverseInDirection(grid, visited, i, j, k);
                    }
                    break outerLoop;
                }
            }
        }

        // Verify all '*' cells in the grid have been visited
        boolean allStarsCovered = true;
        searchLoop:
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (isStar(grid, i, j) && !visited[i][j]) {
                    allStarsCovered = false;
                    break searchLoop;
                }
            }
        }

        System.out.println(foundCenter && allStarsCovered ? "YES" : "NO");
    }

    /**
     * Checks if a cell and all its 4 adjacent neighbors are '*' characters.
     */
    private static boolean isStarCenter(char[][] grid, int r, int c) {
        return isStar(grid, r, c) &&
               isStar(grid, r + DX[0], c + DY[0]) &&
               isStar(grid, r + DX[1], c + DY[1]) &&
               isStar(grid, r + DX[2], c + DY[2]) &&
               isStar(grid, r + DX[3], c + DY[3]);
    }

    /**
     * Checks if a cell is within bounds and contains a '*' character.
     */
    private static boolean isStar(char[][] grid, int r, int c) {
        return r >= 0 && c >= 0 && r < grid.length && c < grid[0].length && grid[r][c] == '*';
    }

    /**
     * Recursively marks cells in a specific direction starting from (r, c).
     */
    private static void traverseInDirection(char[][] grid, boolean[][] visited, int r, int c, int dirIndex) {
        visited[r][c] = true;
        int nextR = r + DX[dirIndex];
        int nextC = c + DY[dirIndex];
        if (isStar(grid, nextR, nextC) && !visited[nextR][nextC]) {
            traverseInDirection(grid, visited, nextR, nextC, dirIndex);
        }
    }

    /**
     * Fast I/O helper class optimized for competitive programming.
     */
    static class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        long nextLong() {
            return Long.parseLong(next());
        }

        double nextDouble() {
            return Double.parseDouble(next());
        }

        String nextLine() {
            String str = "";
            try {
                str = br.readLine();
            } catch (IOException e) {
                throw new RuntimeException(e);
            }
            return str;
        }
    }
}

import java.io.PrintWriter;
import java.util.Optional;
import java.util.Scanner;

/**
 * Solves the plus shape detection problem.
 * Checks if all '*' characters in the grid form exactly one contiguous plus shape.
 */
public class Solution {

    private static final char STAR = '*';
    private static final char EMPTY = '.';

    private final int height;
    private final int width;
    private final char[][] grid;

    public Solution(Scanner scanner) {
        this.height = scanner.nextInt();
        this.width = scanner.nextInt();
        this.grid = new char[this.height][];
        for (int row = 0; row < this.height; row++) {
            this.grid[row] = scanner.next().toCharArray();
        }
    }

    /**
     * Checks if the given coordinates are within bounds and contain a star.
     */
    private boolean isStar(int row, int col) {
        return row >= 0 && row < this.height
            && col >= 0 && col < this.width
            && this.grid[row][col] == STAR;
    }

    /**
     * Extracts a plus shape mask centered at (centerRow, centerCol).
     * Returns an empty Optional if the center does not form a valid plus shape.
     */
    private Optional<boolean[][]> extractPlusShape(int centerRow, int centerCol) {
        // A valid plus requires the center and its 4 immediate neighbors to be stars
        if (!isStar(centerRow, centerCol)
            || !isStar(centerRow, centerCol + 1)
            || !isStar(centerRow, centerCol - 1)
            || !isStar(centerRow - 1, centerCol)
            || !isStar(centerRow + 1, centerCol)) {
            return Optional.empty();
        }

        boolean[][] shapeMask = new boolean[this.height][this.width];

        // Fill horizontal arm extending right from center
        for (int col = centerCol; col < this.width && isStar(centerRow, col); col++) {
            shapeMask[centerRow][col] = true;
        }
        // Fill horizontal arm extending left from center
        for (int col = centerCol - 1; col >= 0 && isStar(centerRow, col); col--) {
            shapeMask[centerRow][col] = true;
        }

        // Fill vertical arm extending down from center
        for (int row = centerRow; row < this.height && isStar(row, centerCol); row++) {
            shapeMask[row][centerCol] = true;
        }
        // Fill vertical arm extending up from center
        for (int row = centerRow - 1; row >= 0 && isStar(row, centerCol); row--) {
            shapeMask[row][centerCol] = true;
        }

        return Optional.of(shapeMask);
    }

    /**
     * Scans the grid to find the first valid plus shape.
     */
    private Optional<boolean[][]> findFirstPlusShape() {
        // Iterate through potential centers, excluding borders
        for (int row = 1; row < this.height - 1; row++) {
            for (int col = 1; col < this.width - 1; col++) {
                Optional<boolean[][]> shape = extractPlusShape(row, col);
                if (shape.isPresent()) {
                    return shape;
                }
            }
        }
        return Optional.empty();
    }

    /**
     * Determines if all stars in the grid form exactly one plus shape.
     */
    public String solve() {
        Optional<boolean[][]> plusShapeOpt = findFirstPlusShape();
        if (plusShapeOpt.isEmpty()) {
            return "NO";
        }

        boolean[][] plusShape = plusShapeOpt.get();
        for (int row = 0; row < this.height; row++) {
            for (int col = 0; col < this.width; col++) {
                if (this.grid[row][col] == STAR && !plusShape[row][col]) {
                    return "NO";
                }
            }
        }

        return "YES";
    }

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in);
             PrintWriter writer = new PrintWriter(System.out)) {
            Solution solver = new Solution(scanner);
            writer.println(solver.solve());
        }
        // JVM exits naturally; System.exit(0) is unnecessary and discouraged in modern Java
    }
}

import java.util.Scanner;

public class Div2_566B {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        // Read dimensions
        if (!scanner.hasNextInt()) {
            scanner.close();
            return;
        }
        int rows = scanner.nextInt();
        int cols = scanner.nextInt();

        char[][] grid = new char[rows][cols];
        int totalStars = 0;

        // Read grid and count total stars
        for (int i = 0; i < rows; i++) {
            String line = scanner.next();
            for (int j = 0; j < cols; j++) {
                grid[i][j] = line.charAt(j);
                if (grid[i][j] == '*') {
                    totalStars++;
                }
            }
        }

        // Optimization: A cross shape cannot have more stars than the max possible cross in the grid.
        // The maximum number of stars in a single cross fitting in an N x M grid is N + M - 1.
        if (totalStars > rows + cols - 1) {
            System.out.println("NO");
            scanner.close();
            return;
        }

        boolean isValid = false;

        // Iterate through the grid to find a potential center of the cross
        searchLoop:
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == '*') {
                    // Count consecutive stars in all 4 directions starting from neighbors
                    int right = countConsecutive(grid, i, j, 0, 1);
                    int left = countConsecutive(grid, i, j, 0, -1);
                    int down = countConsecutive(grid, i, j, 1, 0);
                    int up = countConsecutive(grid, i, j, -1, 0);

                    // The center star itself counts as 1
                    int crossSize = right + left + down + up + 1;

                    // Check if this cross contains all stars and has arms in all 4 directions
                    if (crossSize == totalStars && right > 0 && left > 0 && down > 0 && up > 0) {
                        isValid = true;
                        break searchLoop;
                    }
                }
            }
        }

        System.out.println(isValid ? "YES" : "NO");
        scanner.close();
    }

    /**
     * Counts consecutive stars in a specific direction starting from a neighbor cell.
     *
     * @param grid The 2D character array representing the grid.
     * @param startRow The row index of the center star.
     * @param startCol The column index of the center star.
     * @param deltaRow The change in row for each step (e.g., 1 for down, -1 for up).
     * @param deltaCol The change in column for each step (e.g., 1 for right, -1 for left).
     * @return The number of consecutive stars found in that direction.
     */
    private static int countConsecutive(char[][] grid, int startRow, int startCol, int deltaRow, int deltaCol) {
        int count = 0;
        int currentRow = startRow + deltaRow;
        int currentCol = startCol + deltaCol;
        int rows = grid.length;
        int cols = grid[0].length;

        while (currentRow >= 0 && currentRow < rows && currentCol >= 0 && currentCol < cols) {
            if (grid[currentRow][currentCol] == '*') {
                count++;
                currentRow += deltaRow;
                currentCol += deltaCol;
            } else {
                break;
            }
        }
        return count;
    }
}

import java.util.Scanner;

public class Main {

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        if (!sc.hasNextInt()) return;

        int rows = sc.nextInt();
        int cols = sc.nextInt();

        boolean[][] grid = new boolean[rows][cols];
        for (int i = 0; i < rows; i++) {
            String line = sc.next();
            for (int j = 0; j < cols; j++) {
                grid[i][j] = line.charAt(j) == '*';
            }
        }

        int centerRow = -1;
        int centerCol = -1;
        boolean crossFound = false;

        // Step 1: Locate the center of the cross
        for (int i = 2; i < rows; i++) {
            for (int j = 1; j < cols - 1; j++) {
                if (detectCrossCenter(grid, i, j)) {
                    if (crossFound) {
                        // Multiple potential centers indicate an invalid shape
                        System.out.println("NO");
                        return;
                    }
                    crossFound = true;
                    centerRow = i - 1;
                    centerCol = j;
                }
            }
        }

        if (!crossFound) {
            System.out.println("NO");
            return;
        }

        // Step 2: Validate the entire grid against the cross shape
        System.out.println(validateCrossShape(grid, centerRow, centerCol, rows, cols) ? "YES" : "NO");
    }

    /**
     * Detects if a cross center exists at (i-1, j) based on the required pattern:
     * - (i, j)       : bottom tip of vertical arm
     * - (i-1, j)     : center of the cross
     * - (i-2, j)     : top tip of vertical arm
     * - (i-1, j-1)   : left arm
     * - (i-1, j+1)   : right arm
     */
    private static boolean detectCrossCenter(boolean[][] grid, int i, int j) {
        int centerRow = i - 1;
        int centerCol = j;
        return grid[i][j] && grid[centerRow][centerCol] && grid[centerRow - 1][centerCol] &&
               grid[centerRow][centerCol - 1] && grid[centerRow][centerCol + 1];
    }

    /**
     * Validates that the grid contains exactly one continuous cross centered at (centerRow, centerCol).
     * Ensures no extra stars exist and that all arms are contiguous (no gaps).
     */
    private static boolean validateCrossShape(boolean[][] grid, int centerRow, int centerCol, int rows, int cols) {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (!grid[i][j]) continue;

                // Any star must lie on the same row or column as the center
                if (i != centerRow && j != centerCol) {
                    return false;
                }

                // Check for vertical gaps above the center
                if (j == centerCol && i < centerRow) {
                    if (!grid[i + 1][j]) return false;
                }
                // Check for vertical gaps below the center
                if (j == centerCol && i > centerRow) {
                    if (!grid[i - 1][j]) return false;
                }
                // Check for horizontal gaps to the right of the center
                if (i == centerRow && j > centerCol) {
                    if (!grid[i][j - 1]) return false;
                }
                // Check for horizontal gaps to the left of the center
                if (i == centerRow && j < centerCol) {
                    if (!grid[i][j + 1]) return false;
                }
            }
        }
        return true;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

/**
 * Solves the grid cross problem.
 * Determines if there exists a '*' that forms a complete cross (up, down, left, right)
 * such that the total number of '*' in the grid exactly matches the cross size.
 */
public class GridCrossSolver {

    public static void main(String[] args) throws IOException {
        FastScanner scanner = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            // Read number of test cases
            int T = scanner.nextInt();
            for (int t = 1; t <= T; t++) {
                solve(t, scanner, out);
            }
        } finally {
            out.flush();
            out.close();
            scanner.close();
        }
    }

    /**
     * Processes a single test case.
     */
    private static void solve(int testCase, FastScanner scanner, PrintWriter out) throws IOException {
        int height = scanner.nextInt();
        int width = scanner.nextInt();

        boolean[][] grid = new boolean[height][width];
        int starCount = 0;

        // Read grid rows and count total stars
        for (int i = 0; i < height; i++) {
            String row = scanner.next();
            for (int j = 0; j < width; j++) {
                grid[i][j] = row.charAt(j) == '*';
                if (grid[i][j]) {
                    starCount++;
                }
            }
        }

        // Check each star to see if it forms a valid cross
        boolean found = false;
        for (int i = 0; i < height; i++) {
            for (int j = 0; j < width; j++) {
                if (!grid[i][j]) continue;

                int up = countStarsInDirection(grid, i, j, -1, 0, height, width);
                int down = countStarsInDirection(grid, i, j, 1, 0, height, width);
                int left = countStarsInDirection(grid, i, j, 0, -1, height, width);
                int right = countStarsInDirection(grid, i, j, 0, 1, height, width);

                // A valid cross must have at least one star in each direction
                if (up >= 1 && down >= 1 && left >= 1 && right >= 1) {
                    int crossSize = up + down + left + right + 1;
                    if (crossSize == starCount) {
                        found = true;
                        break;
                    }
                }
            }
            if (found) break;
        }

        out.println(found ? "YES" : "NO");
    }

    /**
     * Counts consecutive stars in a specific direction from a starting cell.
     * Stops when hitting a non-star cell or the grid boundary.
     */
    private static int countStarsInDirection(boolean[][] grid, int startRow, int startCol,
                                             int dRow, int dCol, int height, int width) {
        int count = 0;
        int r = startRow + dRow;
        int c = startCol + dCol;

        while (r >= 0 && r < height && c >= 0 && c < width && grid[r][c]) {
            count++;
            r += dRow;
            c += dCol;
        }
        return count;
    }

    /**
     * High-performance I/O helper for competitive programming environments.
     */
    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        public String next() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) {
                    return null;
                }
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

        public int nextInt() throws IOException {
            String token = next();
            if (token == null) {
                throw new IOException("Unexpected end of input");
            }
            return Integer.parseInt(token);
        }

        public void close() throws IOException {
            br.close();
        }
    }
}

