        char[][] grid = new char[rows][cols];

        // Read grid data
        for (int i = 0; i < rows; i++) {
            String line = scanner.next();
            grid[i] = line.toCharArray();
        }

        boolean centerFound = false;

        // Iterate through the grid to find a star surrounded by stars in all 4 directions.
        // We skip the boundaries (index 0 and index n-1) to avoid out-of-bounds checks for neighbors.
        for (int i = 1; i < rows - 1; i++) {
            for (int j = 1; j < cols - 1; j++) {
                if (isStarCenter(i, j, grid)) {
                    centerFound = true;

                    // Remove the center star
                    grid[i][j] = '.';

                    // Clear connected stars in straight lines (Up, Down, Left, Right)
                    clearConnectedLines(i, j, grid);

                    // Check if any stars remain in the grid
                    if (!hasRemainingStars(grid)) {
                        System.out.println("YES");
                    } else {
                        System.out.println("NO");
                    }

                    // The original logic stops searching after finding the first center
                    // because the 'bo' flag breaks the loops.
                    return;
                }
            }
        }

        // If no center was found, print NO
        System.out.println("NO");

        scanner.close();
    }

    /**
     * Checks if the star at (x, y) is surrounded by stars in all 4 cardinal directions.
     */
    private static boolean isStarCenter(int x, int y, char[][] grid) {
        return grid[x][y] == '*'
                && grid[x - 1][y] == '*' // Up
                && grid[x + 1][y] == '*' // Down
                && grid[x][y - 1] == '*' // Left
                && grid[x][y + 1] == '*'; // Right
    }

    /**
     * Clears stars in a straight line from (x, y) in all 4 directions until a non-star is hit.
     * Note: The original method name was 'dfs', but it performs iterative line clearing.
     */
    private static void clearConnectedLines(int x, int y, char[][] grid) {
        // Clear Up
        for (int i = x - 1; i >= 0; i--) {
            if (grid[i][y] == '*') {
                grid[i][y] = '.';
            } else {
                break;
            }
        }
        // Clear Down
        for (int i = x + 1; i < grid.length; i++) {
            if (grid[i][y] == '*') {
                grid[i][y] = '.';
            } else {
                break;
            }
        }
        // Clear Left
        for (int i = y - 1; i >= 0; i--) {
            if (grid[x][i] == '*') {
                grid[x][i] = '.';
            } else {
                break;
            }
        }
        // Clear Right
        for (int i = y + 1; i < grid[0].length; i++) {
            if (grid[x][i] == '*') {
                grid[x][i] = '.';
            } else {
                break;
            }
        }
    }

    /**
     * Checks if there are any stars left in the grid.
     */
    private static boolean hasRemainingStars(char[][] grid) {
        for (char[] row : grid) {
            for (char cell : row) {
                if (cell == '*') {
                    return true;
                }
            }
        }
        return false;
    }
}

