class Picture {
    private static final char STAR = '*';
    private static final char EMPTY = '.';
    private static final int[] DELTA_ROW = {0, -1, 0, 1, 0};
    private static final int[] DELTA_COL = {0, 0, 1, 0, -1};

    private final char[][] grid;

    public Picture(int rows, int cols) {
        grid = new char[rows][cols];
    }

    public void setRow(int row, String line) {
        grid[row] = line.toCharArray();
    }

    /**
     * Scans the grid, counts valid plus shapes, removes them, and verifies
     * that exactly one plus existed and no stars remain.
     */
    public boolean hasExactlyOnePlus() {
        int plusCount = 0;
        for (int r = 0; r < grid.length; r++) {
            for (int c = 0; c < grid[r].length; c++) {
                if (isPlus(r, c)) {
                    plusCount++;
                    removePlus(r, c);
                }
            }
        }
        return plusCount == 1 && countStars() == 0;
    }

    /**
     * Checks if the center at (row, col) and its 4 immediate orthogonal 
     * neighbors are all stars.
     */
    private boolean isPlus(int row, int col) {
        for (int i = 0; i < DELTA_ROW.length; i++) {
            int r = row + DELTA_ROW[i];
            int c = col + DELTA_COL[i];
            if (!isStar(r, c)) {
                return false;
            }
        }
        return true;
    }

    /**
     * Removes the 5 stars that form a plus shape centered at (row, col).
     * Note: Original code had a logical inconsistency where isPlus() checked 
     * 5 stars but removePlus() cleared extended arms. This method now 
     * consistently removes exactly the 5 stars checked by isPlus().
     */
    private void removePlus(int row, int col) {
        for (int i = 0; i < DELTA_ROW.length; i++) {
            int r = row + DELTA_ROW[i];
            int c = col + DELTA_COL[i];
            if (isStar(r, c)) {
                grid[r][c] = EMPTY;
            }
        }
    }

    public int countStars() {
        int stars = 0;
        for (char[] row : grid) {
            for (char cell : row) {
                if (cell == STAR) {
                    stars++;
                }
            }
        }
        return stars;
    }

    private boolean isStar(int row, int col) {
        return inBounds(row, col) && grid[row][col] == STAR;
    }

    private boolean inBounds(int row, int col) {
        return row >= 0 && row < grid.length && col >= 0 && col < grid[row].length;
    }
}

import java.io.BufferedWriter;
