/**
 * Main entry point for the competitive programming solution.
 * Refactored for improved structure, readability, and maintainability.
 */
public class Main {
    public static void main(String[] args) {
        InputReader in = new InputReader(System.in);
        OutputWriter out = new OutputWriter(System.out);

        new Task566B().solve(1, in, out);

        out.close();
    }

    /**
     * Solves Task 566B: Validates if all '*' characters in a grid form 
     * a connected cross/line structure originating from a valid center.
     */
    static class Task566B {
        private static final int[][] DIRECTIONS = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};

        public void solve(int testNumber, InputReader in, OutputWriter out) {
            int rows = in.nextInt();
            int cols = in.nextInt();

            boolean[][] grid = readGrid(in, rows, cols);
            int starCount = countStars(grid);

            // If there are no stars, the condition cannot be satisfied
            if (starCount == 0) {
                out.println("NO");
                return;
            }

            int[] center = findFirstValidCenter(grid, rows, cols);
            boolean[][] visited = new boolean[rows][cols];

            // If a valid center exists, mark all connected stars in straight lines
            if (center != null) {
                markStarsInAllDirections(grid, visited, center[0], center[1], rows, cols);
            }

            // Verify that every star has been visited
            if (allStarsCovered(grid, visited)) {
                out.println("YES");
            } else {
                out.println("NO");
            }
        }

        /**
         * Reads the grid from input and converts '*' to true, others to false.
         */
        private boolean[][] readGrid(InputReader in, int rows, int cols) {
            boolean[][] grid = new boolean[rows][cols];
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    char ch = in.nextCharacter();
                    grid[r][c] = (ch == '*');
                }
            }
            return grid;
        }

        /**
         * Counts the total number of '*' characters in the grid.
         */
        private int countStars(boolean[][] grid) {
            int count = 0;
            for (boolean[] row : grid) {
                for (boolean isStar : row) {
                    if (isStar) count++;
                }
            }
            return count;
        }

        /**
         * Finds the first '*' that has all 4 adjacent neighbors as '*'.
         * Returns coordinates as [row, col], or null if none exists.
         */
        private int[] findFirstValidCenter(boolean[][] grid, int rows, int cols) {
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (!grid[r][c]) continue;

                    boolean hasAllNeighbors = true;
                    for (int[] dir : DIRECTIONS) {
                        int nr = r + dir[0];
                        int nc = c + dir[1];

                        if (nr < 0 || nr >= rows || nc < 0 || nc >= cols || !grid[nr][nc]) {
                            hasAllNeighbors = false;
                            break;
                        }
                    }

                    if (hasAllNeighbors) {
                        return new int[]{r, c};
                    }
                }
            }
            return null;
        }

        /**
         * Marks the center and all consecutive '*' characters in all 4 cardinal directions.
         */
        private void markStarsInAllDirections(boolean[][] grid, boolean[][] visited, 
                                              int r, int c, int rows, int cols) {
            visited[r][c] = true;
            for (int[] dir : DIRECTIONS) {
                int nr = r + dir[0];
                int nc = c + dir[1];

                while (nr >= 0 && nr < rows && nc >= 0 && nc < cols && grid[nr][nc]) {
                    visited[nr][nc] = true;
                    nr += dir[0];
                    nc += dir[1];
                }
            }
        }

        /**
         * Checks if every '*' in the grid has been marked as visited.
         */
        private boolean allStarsCovered(boolean[][] grid, boolean[][] visited) {
            for (int r = 0; r < grid.length; r++) {
                for (int c = 0; c < grid[r].length; c++) {
                    if (grid[r][c] && !visited[r][c]) {
                        return false;
                    }
                }
            }
            return true;
        }
    }

    /**
     * Fast input reader for competitive programming.
     */
    static class InputReader {
        private final InputStream stream;
        private final byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;
        private SpaceCharFilter filter;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        public int read() {
            if (numChars == -1) {
                throw new InputMismatchException();
            }
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0) {
                    return -1;
                }
            }
            return buf[curChar++];
        }

        public int nextInt() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                res *= 10;
                res += c - '0';
                c = read();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public boolean isSpaceChar(int c) {
            return (filter != null && filter.isSpaceChar(c)) || isWhitespace(c);
        }

        public static boolean isWhitespace(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        public char nextCharacter() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            return (char) c;
        }

        @FunctionalInterface
        public interface SpaceCharFilter {
            boolean isSpaceChar(int ch);
        }
    }

    /**
     * Fast output writer for competitive programming.
     */
    static class OutputWriter {
        private final PrintWriter writer;

        public OutputWriter(OutputStream outputStream) {
            this.writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(outputStream)));
        }

        public OutputWriter(Writer writer) {
            this.writer = new PrintWriter(writer);
        }

        public void print(Object... objects) {
            for (int i = 0; i < objects.length; i++) {
                if (i > 0) {
                    writer.print(' ');
                }
                writer.print(objects[i]);
            }
        }

        public void println(Object... objects) {
            print(objects);
            writer.println();
        }

        public void flush() {
            writer.flush();
        }

        public void close() {
            writer.close();
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

/**
 * Validates whether a grid of '*' characters forms a valid cross shape.
 * A valid cross must have a center that is not on the border, and all '*' 
 * characters must lie on the same row and column as the center.
 */
public class CrossShapeChecker {

    public static void main(String[] args) {
        new CrossShapeChecker().solve();
    }

    public void solve() {
        FastReader sc = new FastReader();
        int rows = sc.nextInt();
        int cols = sc.nextInt();

        boolean[][] grid = new boolean[rows][cols];
        int totalStars = 0;

        for (int i = 0; i < rows; i++) {
            String line = sc.next();
            for (int j = 0; j < cols; j++) {
                if (line.charAt(j) == '*') {
                    grid[i][j] = true;
                    totalStars++;
                }
            }
        }

        int centerRow = -1;
        int centerCol = -1;

        // Find the potential cross center (must not be on the border)
        for (int i = 1; i < rows - 1; i++) {
            for (int j = 1; j < cols - 1; j++) {
                if (grid[i][j] && grid[i - 1][j] && grid[i + 1][j] &&
                    grid[i][j - 1] && grid[i][j + 1]) {
                    centerRow = i;
                    centerCol = j;
                    break;
                }
            }
            if (centerRow != -1) {
                break;
            }
        }

        if (centerRow == -1) {
            System.out.println("NO");
            return;
        }

        // Count all '*' in the four cardinal directions from the center
        int crossCount = 1; // Start with the center itself
        crossCount += countConsecutive(grid, centerRow, centerCol, 1, 0);   // Down
        crossCount += countConsecutive(grid, centerRow, centerCol, -1, 0);  // Up
        crossCount += countConsecutive(grid, centerRow, centerCol, 0, 1);   // Right
        crossCount += countConsecutive(grid, centerRow, centerCol, 0, -1);  // Left

        if (crossCount == totalStars) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }
    }

    /**
     * Counts consecutive true values in a specific direction from a starting point.
     */
    private int countConsecutive(boolean[][] grid, int startRow, int startCol, int dRow, int dCol) {
        int count = 0;
        int r = startRow + dRow;
        int c = startCol + dCol;
        while (r >= 0 && r < grid.length && c >= 0 && c < grid[0].length && grid[r][c]) {
            count++;
            r += dRow;
            c += dCol;
        }
        return count;
    }

    /**
     * Fast input reader for competitive programming and large inputs.
     */
    static class FastReader {
        BufferedReader br;
        StringTokenizer st;

        public FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        long nextLong() {
            return Long.parseLong(next());
        }

        double nextDouble() {
            return Double.parseDouble(next());
        }

        String nextLine() {
            String str = "";
            try {
                str = br.readLine();
            } catch (IOException e) {
                e.printStackTrace();
            }
            return str;
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

public class Main {

    public static void main(String[] args) throws IOException {
        FastReader reader = new FastReader(System.in);

        // Read grid dimensions
        int rows = reader.nextInt();
        int cols = reader.nextInt();

        // Read grid data
        char[][] grid = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            String line = reader.next();
            grid[i] = line.toCharArray();
        }

        // Validate and print result
        System.out.println(validateGrid(grid, rows, cols));
    }

    /**
     * Validates the grid according to the specified pattern rules.
     * Returns "YES" if the pattern is valid and contains an extra star below the center,
     * otherwise returns "NO".
     */
    private static String validateGrid(char[][] grid, int rows, int cols) {
        int firstStarRow = -1, firstStarCol = -1;
        boolean foundFirstStar = false;

        // Step 1: Locate the first '*' in the grid
        outerLoop:
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '*') {
                    firstStarRow = r;
                    firstStarCol = c;
                    foundFirstStar = true;
                    break outerLoop;
                }
            }
        }

        if (!foundFirstStar) {
            return "NO";
        }

        // Step 2: Boundary validation
        if (firstStarCol == cols - 1 || firstStarRow == rows - 1 ||
            firstStarCol == 0 || firstStarRow == rows - 2) {
            return "NO";
        }

        // Mark the first star as visited to track remaining stars later
        grid[firstStarRow][firstStarCol] = '.';

        // Step 3: Verify no '*' exists to the right of the first star
        for (int c = firstStarCol + 1; c < cols; c++) {
            if (grid[firstStarRow][c] == '*') {
                return "NO";
            }
        }

        // Step 4: Verify the cell directly below the first star is '*'
        if (grid[firstStarRow + 1][firstStarCol] != '*') {
            return "NO";
        }

        int centerRow = -1;
        boolean centerFound = false;
        boolean hasExtraStarBelowCenter = false;
        boolean verticalGapFound = false;

        // Step 5: Scan downward from the first star's column
        for (int r = firstStarRow + 1; r < rows; r++) {
            if (grid[r][firstStarCol] == '*') {
                if (centerFound) {
                    hasExtraStarBelowCenter = true;
                }
                grid[r][firstStarCol] = '.'; // Mark as visited

                if (verticalGapFound) {
                    return "NO";
                }

                boolean leftStar = firstStarCol > 0 && grid[r][firstStarCol - 1] == '*';
                boolean rightStar = firstStarCol < cols - 1 && grid[r][firstStarCol + 1] == '*';

                if (leftStar && rightStar) {
                    if (centerFound) {
                        return "NO"; // Multiple centers detected
                    }
                    centerRow = r;
                    centerFound = true;
                } else if (leftStar || rightStar) {
                    return "NO"; // Asymmetric neighbor configuration
                }
            } else {
                verticalGapFound = true;
            }
        }

        if (!centerFound) {
            return "NO";
        }

        // Step 6: Scan left from the center row
        boolean horizontalGapFound = false;
        for (int c = firstStarCol - 1; c >= 0; c--) {
            if (grid[centerRow][c] == '*') {
                if (horizontalGapFound) {
                    return "NO";
                }
                grid[centerRow][c] = '.'; // Mark as visited
            } else {
                horizontalGapFound = true;
            }
        }

        // Step 7: Scan right from the center row
        horizontalGapFound = false;
        for (int c = firstStarCol + 1; c < cols; c++) {
            if (grid[centerRow][c] == '*') {
                if (horizontalGapFound) {
                    return "NO";
                }
                grid[centerRow][c] = '.'; // Mark as visited
            } else {
                horizontalGapFound = true;
            }
        }

        // Step 8: Ensure no '*' characters remain unprocessed
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '*') {
                    return "NO";
                }
            }
        }

        return hasExtraStarBelowCenter ? "YES" : "NO";
    }

    /**
     * Fast I/O utility class for competitive programming and performance-critical inputs.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
            tokenizer = new StringTokenizer("");
        }

        public String next() throws IOException {
            while (!tokenizer.hasMoreTokens()) {
                String line = reader.readLine();
                if (line == null) {
                    return null;
                }
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            String token = next();
            return token == null ? 0 : Integer.parseInt(token);
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

public class Main {
    // Constants for grid characters to improve readability and maintainability
    private static final char STAR = '*';
    private static final char BLOCK = '#';
    private static final char EMPTY = '.';

    public static void main(String[] args) {
        FastReader scanner = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);
        try {
            new Main().solve(scanner, out);
        } finally {
            out.flush();
        }
    }

    /**
     * Main solving logic. Reads input, processes the grid, and outputs the result.
     */
    void solve(FastReader scanner, PrintWriter out) {
        int rows = scanner.nextInt();
        int cols = scanner.nextInt();
        char[][] grid = readGrid(scanner, rows, cols);

        // Iterate over inner cells (excluding borders)
        for (int i = 1; i < rows - 1; i++) {
            for (int j = 1; j < cols - 1; j++) {
                if (grid[i][j] == STAR && isSurrounded(grid, i, j)) {
                    expandCross(grid, i, j);
                    out.println(isGridValid(grid) ? "YES" : "NO");
                    return;
                }
            }
        }
        out.println("NO");
    }

    /**
     * Checks if the cell at (row, col) is surrounded by non-empty characters in all 4 directions.
     */
    private boolean isSurrounded(char[][] grid, int row, int col) {
        return grid[row - 1][col] != EMPTY &&
               grid[row + 1][col] != EMPTY &&
               grid[row][col - 1] != EMPTY &&
               grid[row][col + 1] != EMPTY;
    }

    /**
     * Expands the cross pattern from the given cell, converting adjacent '*' to '#'
     * while skipping over '#' characters.
     */
    private void expandCross(char[][] grid, int row, int col) {
        expandDirection(grid, row, col, -1, 0); // Up
        expandDirection(grid, row, col, 1, 0);  // Down
        expandDirection(grid, row, col, 0, -1); // Left
        expandDirection(grid, row, col, 0, 1);  // Right
    }

    /**
     * Expands in a specific direction until a non-'*' and non-'#' character is encountered.
     */
    private void expandDirection(char[][] grid, int row, int col, int dRow, int dCol) {
        for (int r = row, c = col; ; r += dRow, c += dCol) {
            if (r < 0 || c < 0 || r >= grid.length || c >= grid[0].length) break;
            if (grid[r][c] == BLOCK) continue; // Skip blocks, keep searching
            if (grid[r][c] == STAR) grid[r][c] = BLOCK;
            else break; // Stop at any other character (e.g., '.')
        }
    }

    /**
     * Verifies that the grid only contains EMPTY ('.') and BLOCK ('#') characters.
     */
    private boolean isGridValid(char[][] grid) {
        for (char[] row : grid) {
            for (char cell : row) {
                if (cell != EMPTY && cell != BLOCK) {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Reads the grid from the input scanner.
     */
    private char[][] readGrid(FastReader scanner, int rows, int cols) {
        char[][] grid = new char[rows][];
        for (int i = 0; i < rows; i++) {
            grid[i] = scanner.next().toCharArray();
        }
        return grid;
    }

    /**
     * Lightweight, standard-compliant FastReader for efficient console input.
     * Replaces the original custom byte-buffer I/O for better maintainability.
     */
    static class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        FastReader(java.io.InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Checks if a grid contains a cross pattern that exactly covers all '*' characters.
 * A valid cross center must have at least one '*' in each of the four cardinal directions,
 * and the total number of '*' in the cross must equal the total '*' count in the grid.
 */
public class CrossPatternChecker {

    // Cardinal directions: up, down, left, right
    private static final int[][] DIRECTIONS = {
        {-1, 0}, {1, 0}, {0, -1}, {0, 1}
    };

    public static void main(String[] args) {
        FastIO io = new FastIO();
        solve(io);
        io.close();
    }

    /**
     * Reads the grid, validates dimensions and star count, then searches for a valid cross center.
     */
    private static void solve(FastIO io) {
        int h = io.nextInt();
        int w = io.nextInt();

        char[][] grid = new char[h][w];
        int totalStars = 0;

        // Read grid and count total '*' characters
        for (int i = 0; i < h; i++) {
            String line = io.next();
            grid[i] = line.toCharArray();
            for (int j = 0; j < w; j++) {
                if (grid[i][j] == '*') {
                    totalStars++;
                }
            }
        }

        // Early exit: A cross requires at least 5 stars (center + 1 per direction)
        // and a grid of at least 3x3 to physically fit.
        if (totalStars <= 4 || h <= 2 || w <= 2) {
            io.println("NO");
            return;
        }

        boolean foundCross = false;
        for (int r = 0; r < h && !foundCross; r++) {
            for (int c = 0; c < w && !foundCross; c++) {
                if (grid[r][c] != '*') {
                    continue;
                }

                int crossSize = 1; // Count the center itself
                boolean validCenter = true;

                // Check all four directions from the current cell
                for (int[] dir : DIRECTIONS) {
                    int count = 0;
                    int nr = r + dir[0];
                    int nc = c + dir[1];

                    // Count consecutive '*' in this direction
                    while (nr >= 0 && nr < h && nc >= 0 && nc < w && grid[nr][nc] == '*') {
                        count++;
                        nr += dir[0];
                        nc += dir[1];
                    }

                    // A valid cross center must have at least one '*' in every direction
                    if (count == 0) {
                        validCenter = false;
                        break;
                    }
                    crossSize += count;
                }

                // If all directions contributed and the cross covers exactly all stars, we found it
                if (validCenter && crossSize == totalStars) {
                    foundCross = true;
                }
            }
        }

        io.println(foundCross ? "YES" : "NO");
    }

    /**
     * High-performance input/output helper for competitive programming.
     * Uses composition over inheritance for better encapsulation.
     */
    static class FastIO {
        private final BufferedReader reader;
        private final PrintWriter writer;
        private StringTokenizer tokenizer;

        public FastIO() {
            this.reader = new BufferedReader(new InputStreamReader(System.in));
            this.writer = new PrintWriter(System.out);
            this.tokenizer = new StringTokenizer("");
        }

        public String next() {
            while (!tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) {
                        throw new EOFException("Unexpected end of input");
                    }
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input stream", e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }

        public double nextDouble() {
            return Double.parseDouble(next());
        }

        public void println(Object obj) {
            writer.println(obj);
        }

        public void close() {
            writer.flush();
            writer.close();
        }
    }
}

