public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line = br.readLine();
        if (line == null) return;

        StringTokenizer st = new StringTokenizer(line);
        int n = Integer.parseInt(st.nextToken());
        int m = Integer.parseInt(st.nextToken());

        int[][] grid = readGrid(br, n, m);

        System.out.println(determineResult(grid) ? "YES" : "NO");
    }

    private static int[][] readGrid(BufferedReader br, int n, int m) throws IOException {
        int[][] grid = new int[n][m];
        for (int i = 0; i < n; i++) {
            String rowLine = br.readLine();
            for (int j = 0; j < m; j++) {
                grid[i][j] = (rowLine.charAt(j) == '.') ? 0 : 1;
            }
        }
        return grid;
    }

    private static boolean determineResult(int[][] grid) {
        int n = grid.length;
        int m = grid[0].length;
        int onesCount = 0;

        // Count total '1's to quickly rule out invalid configurations
        for (int[] row : grid) {
            for (int val : row) {
                if (val == 1) onesCount++;
            }
        }

        // A valid cross consists of exactly 5 cells: center + 4 immediate neighbors
        if (onesCount != 5) {
            return false;
        }

        // Check if the 5 cells form a cross shape
        for (int i = 1; i < n - 1; i++) {
            for (int j = 1; j < m - 1; j++) {
                if (grid[i][j] == 1 &&
                    grid[i - 1][j] == 1 &&
                    grid[i + 1][j] == 1 &&
                    grid[i][j - 1] == 1 &&
                    grid[i][j + 1] == 1) {
                    return true;
                }
            }
        }
        return false;
    }
}

import java.util.Scanner;

/**
 * Validates grid configurations to detect exactly one valid cross pattern.
 * A valid cross pattern consists of a center cell and its four orthogonal neighbors
 * being '*', with all '*' in the grid confined to the center's row and column,
 * and forming contiguous blocks.
 */
public class CrossPatternValidator {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        // Basic input validation
        if (!scanner.hasNextInt()) {
            scanner.close();
            return;
        }

        int n = scanner.nextInt();
        int m = scanner.nextInt();

        char[][] grid = new char[n][m];
        for (int i = 0; i < n; i++) {
            grid[i] = scanner.next().toCharArray();
        }
        scanner.close();

        int validCrossCount = 0;
        // Iterate over inner cells to safely check 4 neighbors without boundary checks
        for (int i = 1; i < n - 1; i++) {
            for (int j = 1; j < m - 1; j++) {
                if (isCrossCenter(grid, i, j) && isValidCrossConfiguration(grid, i, j)) {
                    validCrossCount++;
                }
            }
        }

        System.out.println(validCrossCount == 1 ? "YES" : "NO");
    }

    /**
     * Checks if the cell at (row, col) forms the center of a cross pattern.
     */
    private static boolean isCrossCenter(char[][] grid, int row, int col) {
        return grid[row][col] == '*' &&
               grid[row - 1][col] == '*' &&
               grid[row + 1][col] == '*' &&
               grid[row][col - 1] == '*' &&
               grid[row][col + 1] == '*';
    }

    /**
     * Validates the entire cross configuration:
     * 1. All '*' characters must lie within the center's row or column.
     * 2. The '*' characters in the center's row must be contiguous.
     * 3. The '*' characters in the center's column must be contiguous.
     */
    private static boolean isValidCrossConfiguration(char[][] grid, int centerRow, int centerCol) {
        // Verify all '*' are confined to the cross arms
        for (int r = 0; r < grid.length; r++) {
            for (int c = 0; c < grid[0].length; c++) {
                if (grid[r][c] == '*' && r != centerRow && c != centerCol) {
                    return false;
                }
            }
        }

        // Check contiguity in the center row
        if (!isContiguous(grid[centerRow])) {
            return false;
        }

        // Check contiguity in the center column
        if (!isContiguousColumn(grid, centerCol)) {
            return false;
        }

        return true;
    }

    /**
     * Checks if a 1D array contains a single contiguous block of '*' characters.
     */
    private static boolean isContiguous(char[] sequence) {
        boolean foundStar = false;
        boolean foundGap = false;

        for (char c : sequence) {
            if (c == '*') {
                if (foundGap) return false; // Gap detected before a star
                foundStar = true;
            } else {
                if (foundStar) {
                    foundGap = true; // Gap detected after a star
                }
            }
        }
        return true;
    }

    /**
     * Checks if a column in the grid contains a single contiguous block of '*' characters.
     */
    private static boolean isContiguousColumn(char[][] grid, int col) {
        boolean foundStar = false;
        boolean foundGap = false;

        for (char[] row : grid) {
            char c = row[col];
            if (c == '*') {
                if (foundGap) return false;
                foundStar = true;
            } else {
                if (foundStar) {
                    foundGap = true;
                }
            }
        }
        return true;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

public class Main {
    public static void main(String[] args) {
        solve();
    }

    private static void solve() {
        // Use try-with-resources for automatic and safe resource management
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
             PrintWriter out = new PrintWriter(System.out)) {

            FastScanner scanner = new FastScanner(br);

            int rows = scanner.nextInt();
            int cols = scanner.nextInt();
            char[][] grid = new char[rows][cols];
            int totalStars = 0;

            // Read grid and count total stars
            for (int i = 0; i < rows; i++) {
                String line = scanner.next();
                char[] rowChars = line.toCharArray();
                grid[i] = rowChars;
                for (char cell : rowChars) {
                    if (cell == '*') {
                        totalStars++;
                    }
                }
            }

            int patternCount = -5; // Initialized to a value that cannot match totalStars

            // Search for the specific cross pattern
            outerLoop:
            for (int i = 1; i < rows - 1; i++) {
                for (int j = 1; j < cols - 1; j++) {
                    if (grid[i][j] == '*') {
                        // Check if current '*' is the center of a cross
                        if (grid[i - 1][j] == '*' && grid[i][j - 1] == '*' &&
                            grid[i + 1][j] == '*' && grid[i][j + 1] == '*') {

                            patternCount = 5; // Center + 4 immediate neighbors

                            // Extend upwards (skipping immediate neighbor)
                            for (int r = i - 2; r >= 0 && grid[r][j] == '*'; r--) {
                                patternCount++;
                            }
                            // Extend leftwards (skipping immediate neighbor)
                            for (int c = j - 2; c >= 0 && grid[i][c] == '*'; c--) {
                                patternCount++;
                            }
                            // Extend rightwards (skipping immediate neighbor)
                            for (int c = j + 2; c < cols && grid[i][c] == '*'; c++) {
                                patternCount++;
                            }
                            // Extend downwards (skipping immediate neighbor)
                            for (int r = i + 2; r < rows && grid[r][j] == '*'; r++) {
                                patternCount++;
                            }

                            break outerLoop;
                        }
                    }
                }
            }

            out.println(patternCount == totalStars ? "YES" : "NO");

        } catch (IOException e) {
            System.err.println("Error reading input: " + e.getMessage());
        }
    }

    /**
     * A clean, maintainable fast scanner using BufferedReader and StringTokenizer.
     * Replaces the error-prone custom byte-based InputReader from the original code.
     */
    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner(BufferedReader br) {
            this.br = br;
        }

        public String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            String s = next();
            if (s == null) throw new RuntimeException("Unexpected end of input");
            return Integer.parseInt(s);
        }
    }
}

import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) {
        FastScanner scanner = new FastScanner();
        PrintWriter out = new PrintWriter(System.out);

        try {
            int H = scanner.nextInt();
            int W = scanner.nextInt();
            char[][] grid = readGrid(scanner, H, W);

            int[] rowCounts = new int[H];
            int[] colCounts = new int[W];
            int totalStars = 0;

            // Single pass to compute row/column counts and total stars
            for (int r = 0; r < H; r++) {
                for (int c = 0; c < W; c++) {
                    if (grid[r][c] == '*') {
                        rowCounts[r]++;
                        colCounts[c]++;
                        totalStars++;
                    }
                }
            }

            boolean isValid = validate(grid, H, W, rowCounts, colCounts, totalStars);
            out.println(isValid ? "YES" : "NO");
        } catch (Exception e) {
            // Graceful fallback for unexpected input/format errors
            out.println("NO");
        }
        out.flush();
    }

    /**
     * Orchestrates all validation checks for the star pattern.
     */
    private static boolean validate(char[][] grid, int H, int W, 
                                    int[] rowCounts, int[] colCounts, int totalStars) {
        if (totalStars < 4) return false;
        if (H <= 1 || W <= 1) return false;
        if (!isConnected(grid, H, W, totalStars)) return false;
        if (!isValidUnimodalSequence(rowCounts)) return false;
        if (!isValidUnimodalSequence(colCounts)) return false;
        return true;
    }

    /**
     * Reads the grid from the scanner.
     */
    private static char[][] readGrid(FastScanner scanner, int H, int W) {
        char[][] grid = new char[H][W];
        for (int i = 0; i < H; i++) {
            String line = scanner.next();
            grid[i] = line.toCharArray();
        }
        return grid;
    }

    /**
     * Verifies that all '*' characters form a single connected component using BFS.
     */
    private static boolean isConnected(char[][] grid, int H, int W, int totalStars) {
        boolean[][] visited = new boolean[H][W];
        int startR = -1, startC = -1;

        // Locate the first star to begin traversal
        outer:
        for (int r = 0; r < H; r++) {
            for (int c = 0; c < W; c++) {
                if (grid[r][c] == '*') {
                    startR = r;
                    startC = c;
                    break outer;
                }
            }
        }

        // If no stars exist, connectivity is trivially satisfied (though totalStars >= 4 prevents this)
        if (startR == -1) return totalStars == 0;

        int visitedCount = bfs(grid, H, W, startR, startC, visited);
        return visitedCount == totalStars;
    }

    /**
     * Performs BFS to count reachable '*' cells from the starting position.
     */
    private static int bfs(char[][] grid, int H, int W, int startR, int startC, boolean[][] visited) {
        int count = 0;
        Queue<int[]> queue = new ArrayDeque<>();
        queue.offer(new int[]{startR, startC});
        visited[startR][startC] = true;

        int[] dr = {1, 0, -1, 0};
        int[] dc = {0, 1, 0, -1};

        while (!queue.isEmpty()) {
            int[] cur = queue.poll();
            count++;
            for (int k = 0; k < 4; k++) {
                int nr = cur[0] + dr[k];
                int nc = cur[1] + dc[k];
                if (nr >= 0 && nr < H && nc >= 0 && nc < W &&
                    !visited[nr][nc] && grid[nr][nc] == '*') {
                    visited[nr][nc] = true;
                    queue.offer(new int[]{nr, nc});
                }
            }
        }
        return count;
    }

    /**
     * Validates that the sequence of counts follows the required unimodal pattern.
     * Preserves the exact conditional branching logic of the original implementation.
     */
    private static boolean isValidUnimodalSequence(int[] counts) {
        boolean increasing = true;
        for (int i = 1; i < counts.length; i++) {
            if (increasing && counts[i] < counts[i - 1]) return false;
            else if (counts[i - 1] > 1 && counts[i] != 1) return false;
            else if (increasing && counts[i] > 1) increasing = false;
            else if (!increasing && counts[i] > 1) return false;
            else if (!increasing && counts[i] > counts[i - 1]) return false;
        }
        return !increasing; // Must have reached a peak
    }

    /**
     * Optimized input reader for competitive programming scenarios.
     * Removed unused methods to reduce cognitive load and bloat.
     */
    public static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner() {
            this(new InputStreamReader(System.in));
        }

        public FastScanner(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        public String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            String s = next();
            return s == null ? 0 : Integer.parseInt(s);
        }
    }
}

import java.util.Scanner;

public class Main {

    public static void main(String[] args) {
        // Use try-with-resources to ensure the Scanner is properly closed
        try (Scanner scanner = new Scanner(System.in)) {
            if (!scanner.hasNextInt()) {
                return;
            }

            int n = scanner.nextInt();
            int m = scanner.nextInt();

            // Early validation as per original logic
            if (n < 3 || m < 3) {
                System.out.println("NO");
                return;
            }

            // Efficiently read and store the grid
            char[][] grid = new char[n][m];
            for (int i = 0; i < n; i++) {
                String row = scanner.next();
                grid[i] = row.toCharArray();
            }

            // Delegate validation logic to a dedicated method
            System.out.println(solve(n, m, grid));
        }
    }

    /**
     * Validates the grid against the problem's pattern rules.
     * Returns "YES" if valid, "NO" otherwise.
     */
    private static String solve(int n, int m, char[][] grid) {
        int starRow = -1;
        int starCol = -1;

        // Find the first '*' in row-major order
        outerLoop:
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == '*') {
                    starRow = i;
                    starCol = j;
                    break outerLoop;
                }
            }
        }

        // Handle edge case where no star exists (original code assumed valid input)
        if (starRow == -1 || starCol == -1) {
            return "NO";
        }

        // Rule 1: Star cannot be in the first column
        if (starCol == 0) {
            return "NO";
        }

        // Rule 2: Move down while the cell to the left is not '*'
        while (starRow < n && grid[starRow][starCol - 1] != '*') {
            starRow++;
        }

        // Rule 3: Must stop within bounds and find a '*' to the left
        if (starRow == n || grid[starRow][starCol - 1] != '*') {
            return "NO";
        }

        // Rule 4: Star cannot be on the border or adjacent to '.'
        if (starRow == 0 || starRow == n - 1 || starCol == 0 || starCol == m - 1) {
            return "NO";
        }
        if (grid[starRow - 1][starCol] == '.' || grid[starRow + 1][starCol] == '.' ||
            grid[starRow][starCol - 1] == '.' || grid[starRow][starCol + 1] == '.') {
            return "NO";
        }

        int interruptedCount = 0;

        // Rule 5 & 6: Validate each row
        for (int r = 0; r < n; r++) {
            if (r == starRow) {
                // The star's row must contain exactly one contiguous block of '*'
                int c = 0;
                while (c < m && grid[r][c] == '.') c++;
                while (c < m && grid[r][c] == '*') c++;
                while (c < m && grid[r][c] == '.') c++;

                if (c != m) {
                    return "NO";
                }
            } else {
                // Other rows must not contain '*' except possibly at starCol
                for (int c = 0; c < m; c++) {
                    if (c != starCol && grid[r][c] == '*') {
                        return "NO";
                    }

                    if (c == starCol && grid[r][c] == '.') {
                        // Clamp indices to valid bounds safely
                        int prevRow = Math.max(0, r - 1);
                        int nextRow = Math.min(n - 1, r + 1);

                        if (grid[prevRow][c] == '*' && grid[nextRow][c] == '*') {
                            interruptedCount++;
                        }
                    }
                }
            }
        }

        // Final condition: no interrupted columns allowed
        return interruptedCount == 0 ? "YES" : "NO";
    }
}

import java.io.*;
import java.util.StringTokenizer;

/**
 * Checks if a grid of 0s and 1s contains exactly one cross shape.
 * A cross shape is defined as a horizontal line and a vertical line
 * intersecting at a center point, with all 1s lying on these lines.
 */
public class GridCrossChecker {

    private static final int BUFFER_SIZE = 32768;

    public static void main(String[] args) throws IOException {
        // Use try-with-resources for automatic and safe resource management
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(System.in), BUFFER_SIZE);
             PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out))) {

            FastScanner sc = new FastScanner(reader);

            // Read dimensions
            String hStr = sc.next();
            String wStr = sc.next();
            if (hStr == null || wStr == null) return; // Graceful handling of empty input

            int h = Integer.parseInt(hStr);
            int w = Integer.parseInt(wStr);

            // Read grid
            int[][] grid = new int[h][w];
            for (int r = 0; r < h; r++) {
                String row = sc.next();
                if (row == null) break;
                for (int c = 0; c < w; c++) {
                    grid[r][c] = (row.charAt(c) == '.') ? 0 : 1;
                }
            }

            // Solve and output result
            boolean result = solve(h, w, grid);
            out.println(result ? "YES" : "NO");
            out.flush();
        }
    }

    /**
     * Determines if all '1's in the grid form exactly one cross.
     * 
     * @param h Grid height
     * @param w Grid width
     * @param grid 2D array representing the grid (0 for '.', 1 for other chars)
     * @return true if all 1s form a single cross, false otherwise
     */
    private static boolean solve(int h, int w, int[][] grid) {
        int centerR = -1;
        int centerC = -1;

        // 1. Find the first valid cross center (must be strictly inside the grid)
        for (int r = 1; r < h - 1; r++) {
            for (int c = 1; c < w - 1; c++) {
                if (grid[r][c] == 1 &&
                    grid[r - 1][c] == 1 && grid[r + 1][c] == 1 &&
                    grid[r][c - 1] == 1 && grid[r][c + 1] == 1) {
                    centerR = r;
                    centerC = c;
                    break;
                }
            }
            if (centerR != -1) break;
        }

        // If no valid center exists, it cannot be a cross
        if (centerR == -1) {
            return false;
        }

        // 2. Expand horizontally to find the full extent of the cross arm
        int left = centerC;
        while (left > 0 && grid[centerR][left - 1] == 1) {
            left--;
        }
        int right = centerC;
        while (right < w - 1 && grid[centerR][right + 1] == 1) {
            right++;
        }

        // 3. Expand vertically to find the full extent of the cross arm
        int top = centerR;
        while (top > 0 && grid[top - 1][centerC] == 1) {
            top--;
        }
        int bottom = centerR;
        while (bottom < h - 1 && grid[bottom + 1][centerC] == 1) {
            bottom++;
        }

        // 4. Verify that ALL 1s in the grid lie within the defined cross boundaries
        for (int r = 0; r < h; r++) {
            for (int c = 0; c < w; c++) {
                if (grid[r][c] == 1) {
                    boolean inHorizontalArm = (r == centerR && c >= left && c <= right);
                    boolean inVerticalArm = (c == centerC && r >= top && r <= bottom);

                    // If a '1' is found outside the cross, the condition fails
                    if (!inHorizontalArm && !inVerticalArm) {
                        return false;
                    }
                }
            }
        }

        return true;
    }

    /**
     * High-performance input scanner for competitive programming and I/O-heavy tasks.
     */
    private static class FastScanner {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        FastScanner(BufferedReader reader) {
            this.reader = reader;
        }

        String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                String line = reader.readLine();
                if (line == null) {
                    return null;
                }
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }
    }
}

import java.io.IOException;
