public class Main {

    public static void main(String[] args) {
        // Local I/O instances improve testability and avoid static state pollution
        InputReader in = new InputReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        new CrossGridSolver(in, out).solve();
        out.flush();
    }

    /**
     * Encapsulates the business logic for cross-grid analysis.
     * Follows Single Responsibility Principle by separating concerns:
     * finding a cross, removing it, and counting remaining stars.
     */
    private static class CrossGridSolver {
        private final InputReader in;
        private final PrintWriter out;

        CrossGridSolver(InputReader in, PrintWriter out) {
            this.in = in;
            this.out = out;
        }

        void solve() {
            int height = in.nextInt();
            int width = in.nextInt();
            char[][] grid = in.nextCharMap(height, width);

            // A cross requires at least a 3x3 area. Early exit improves performance.
            if (height < 3 || width < 3) {
                out.println("NO");
                return;
            }

            int[] crossPos = findCross(grid);
            if (crossPos[0] == -1) {
                out.println("NO");
                return;
            }

            removeCross(grid, crossPos[0], crossPos[1]);
            int remainingStars = countRemainingStars(grid);

            out.println(remainingStars == 1 ? "YES" : "NO");
        }

        /**
         * Scans the grid to find exactly one cross pattern.
         * Returns {-1, -1} if zero or multiple crosses are found.
         */
        private int[] findCross(char[][] grid) {
            int crossCount = 0;
            int crossRow = -1;
            int crossCol = -1;

            for (int i = 1; i < grid.length - 1; i++) {
                for (int j = 1; j < grid[i].length - 1; j++) {
                    if (isCross(grid, i, j)) {
                        crossCount++;
                        crossRow = i;
                        crossCol = j;
                    }
                }
            }

            return crossCount == 1 ? new int[]{crossRow, crossCol} : new int[]{-1, -1};
        }

        /**
         * Checks if the cell at (r, c) forms the center of a cross.
         */
        private boolean isCross(char[][] grid, int r, int c) {
            return grid[r][c] == '*'
                    && grid[r - 1][c] == '*'
                    && grid[r + 1][c] == '*'
                    && grid[r][c - 1] == '*'
                    && grid[r][c + 1] == '*';
        }

        /**
         * Removes the cross pattern by clearing contiguous '*' arms in all four directions.
         */
        private void removeCross(char[][] grid, int r, int c) {
            removeArm(grid, r - 1, c, -1, 0);
            removeArm(grid, r + 1, c, 1, 0);
            removeArm(grid, r, c - 1, 0, -1);
            removeArm(grid, r, c + 1, 0, 1);
        }

        /**
         * Clears '*' characters in a specific direction until a non-'*' character is encountered.
         */
        private void removeArm(char[][] grid, int startR, int startC, int dRow, int dCol) {
            for (int i = startR, j = startC;
                 i >= 0 && i < grid.length && j >= 0 && j < grid[i].length;
                 i += dRow, j += dCol) {
                if (grid[i][j] == '*') {
                    grid[i][j] = '.';
                } else {
                    break;
                }
            }
        }

        /**
         * Counts the remaining '*' characters in the grid.
         */
        private int countRemainingStars(char[][] grid) {
            int count = 0;
            for (char[] row : grid) {
                for (char cell : row) {
                    if (cell == '*') count++;
                }
            }
            return count;
        }
    }

    /**
     * Fast I/O reader for competitive programming.
     * Kept largely unchanged to preserve performance characteristics.
     */
    static class InputReader {
        private InputStream in;
        private byte[] buffer = new byte[1024];
        private int curbuf;
        private int lenbuf;

        public InputReader(InputStream in) {
            this.in = in;
            this.curbuf = this.lenbuf = 0;
        }

        public boolean hasNextByte() {
            if (curbuf >= lenbuf) {
                curbuf = 0;
                try {
                    lenbuf = in.read(buffer);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (lenbuf <= 0)
                    return false;
            }
            return true;
        }

        private int readByte() {
            if (hasNextByte())
                return buffer[curbuf++];
            else
                return -1;
        }

        private boolean isSpaceChar(int c) {
            return !(c >= 33 && c <= 126);
        }

        private void skip() {
            while (hasNextByte() && isSpaceChar(buffer[curbuf]))
                curbuf++;
        }

        public boolean hasNext() {
            skip();
            return hasNextByte();
        }

        public String next() {
            if (!hasNext())
                throw new NoSuchElementException();
            StringBuilder sb = new StringBuilder();
            int b = readByte();
            while (!isSpaceChar(b)) {
                sb.appendCodePoint(b);
                b = readByte();
            }
            return sb.toString();
        }

        public int nextInt() {
            if (!hasNext())
                throw new NoSuchElementException();
            int c = readByte();
            while (isSpaceChar(c))
                c = readByte();
            boolean minus = false;
            if (c == '-') {
                minus = true;
                c = readByte();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9')
                    throw new InputMismatchException();
                res = res * 10 + c - '0';
                c = readByte();
            } while (!isSpaceChar(c));
            return (minus) ? -res : res;
        }

        public long nextLong() {
            if (!hasNext())
                throw new NoSuchElementException();
            int c = readByte();
            while (isSpaceChar(c))
                c = readByte();
            boolean minus = false;
            if (c == '-') {
                minus = true;
                c = readByte();
            }
            long res = 0;
            do {
                if (c < '0' || c > '9')
                    throw new InputMismatchException();
                res = res * 10 + c - '0';
                c = readByte();
            } while (!isSpaceChar(c));
            return (minus) ? -res : res;
        }

        public double nextDouble() {
            return Double.parseDouble(next());
        }

        public int[] nextIntArray(int n) {
            int[] a = new int[n];
            for (int i = 0; i < n; i++)
                a[i] = nextInt();
            return a;
        }

        public long[] nextLongArray(int n) {
            long[] a = new long[n];
            for (int i = 0; i < n; i++)
                a[i] = nextLong();
            return a;
        }

        public char[][] nextCharMap(int n, int m) {
            char[][] map = new char[n][m];
            for (int i = 0; i < n; i++)
                map[i] = next().toCharArray();
            return map;
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

/**
 * Refactored for maintainability, readability, and performance.
 * - Extracted logic into focused, single-responsibility methods.
 * - Replaced String[] with char[][] for O(1) access and better semantics.
 * - Removed magic numbers and hardcoded class name.
 * - Standardized I/O handling and added robust FastScanner.
 */
public class Main {

    private static final char STAR = '*';
    private static final char EMPTY = '.';

    public static void main(String[] args) {
        FastScanner in = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out);
        new Main().solve(in, out);
        out.flush();
    }

    public void solve(FastScanner in, PrintWriter out) {
        int rows = in.nextInt();
        int cols = in.nextInt();
        char[][] grid = new char[rows][cols];

        // Read grid into a 2D char array for efficient access
        for (int i = 0; i < rows; i++) {
            grid[i] = in.next().toCharArray();
        }

        int centerRow = -1;
        int centerCol = -1;

        // 1. Locate the potential cross center
        for (int r = 1; r < rows - 1; r++) {
            for (int c = 1; c < cols - 1; c++) {
                if (isCrossCenter(grid, r, c)) {
                    centerRow = r;
                    centerCol = c;
                    break;
                }
            }
            if (centerRow != -1) {
                break;
            }
        }

        if (centerRow == -1) {
            out.println("NO");
            return;
        }

        // 2. Verify that '*' characters are contiguous from the center in all 4 directions
        if (!checkContiguity(grid, centerRow, centerCol, 0, -1) || // Left
            !checkContiguity(grid, centerRow, centerCol, 0, 1)  || // Right
            !checkContiguity(grid, centerRow, centerCol, -1, 0) || // Up
            !checkContiguity(grid, centerRow, centerCol, 1, 0)) {  // Down
            out.println("NO");
            return;
        }

        // 3. Ensure every '*' in the grid lies on the cross (same row or column as center)
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == STAR && r != centerRow && c != centerCol) {
                    out.println("NO");
                    return;
                }
            }
        }

        out.println("YES");
    }

    /**
     * Checks if the given position forms the center of a cross.
     * Requires '*' at the position and in all four immediate neighbors.
     */
    private boolean isCrossCenter(char[][] grid, int r, int c) {
        return grid[r][c] == STAR &&
               grid[r - 1][c] == STAR && grid[r + 1][c] == STAR &&
               grid[r][c - 1] == STAR && grid[r][c + 1] == STAR;
    }

    /**
     * Checks contiguity of '*' characters from the center outwards in a specific direction.
     * Returns false if a '*' appears after an EMPTY cell in that direction.
     */
    private boolean checkContiguity(char[][] grid, int startRow, int startCol, int dRow, int dCol) {
        boolean foundEmpty = false;
        int r = startRow + dRow;
        int c = startCol + dCol;

        while (r >= 0 && r < grid.length && c >= 0 && c < grid[0].length) {
            if (grid[r][c] == EMPTY) {
                foundEmpty = true;
            } else if (grid[r][c] == STAR && foundEmpty) {
                return false;
            }
            r += dRow;
            c += dCol;
        }
        return true;
    }

    /**
     * High-performance input reader for competitive programming environments.
     */
    static class FastScanner {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastScanner(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            String s = next();
            return s == null ? 0 : Integer.parseInt(s);
        }

        public long nextLong() {
            String s = next();
            return s == null ? 0L : Long.parseLong(s);
        }

        public double nextDouble() {
            String s = next();
            return s == null ? 0.0 : Double.parseDouble(s);
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

public class Solution {
    public static void main(String[] args) {
        FastReader reader = new FastReader();

        // Read dimensions
        String hStr = reader.next();
        if (hStr == null) return;
        int rows = Integer.parseInt(hStr);

        String wStr = reader.next();
        if (wStr == null) return;
        int cols = Integer.parseInt(wStr);

        // Initialize grid
        char[][] grid = new char[rows][cols];

        // Read grid rows
        // Using next() assumes grid rows are tokens (no internal spaces), 
        // which is standard for this type of problem and handles whitespace/newlines robustly.
        for (int i = 0; i < rows; i++) {
            String row = reader.next();
            if (row != null) {
                // Fill the row in the grid, handling potential length mismatches safely
                int len = Math.min(row.length(), cols);
                for (int j = 0; j < len; j++) {
                    grid[i][j] = row.charAt(j);
                }
            }
        }

        // Logic to find and clear the cross pattern
        boolean foundPattern = false;

        // Iterate through valid center positions (excluding borders)
        // A center (r, c) is valid if it has neighbors in all 4 directions
        for (int r = 1; r < rows - 1; r++) {
            for (int c = 1; c < cols - 1; c++) {
                if (isCrossPattern(grid, r, c)) {
                    foundPattern = true;
                    clearCrossPattern(grid, r, c);
                    break; // Stop after finding the first pattern
                }
            }
            if (foundPattern) break;
        }

        if (!foundPattern) {
            System.out.println("NO");
        } else {
            // Check if any '*' remains in the grid after clearing
            boolean allCleared = true;
            outerLoop:
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] == '*') {
                        allCleared = false;
                        break outerLoop;
                    }
                }
            }
            System.out.println(allCleared ? "YES" : "NO");
        }
    }

    /**
     * Checks if a cross pattern exists centered at (r, c).
     * A cross pattern is a '*' with '*' neighbors in all 4 cardinal directions.
     */
    private static boolean isCrossPattern(char[][] grid, int r, int c) {
        return grid[r][c] == '*' &&
               grid[r - 1][c] == '*' &&
               grid[r + 1][c] == '*' &&
               grid[r][c - 1] == '*' &&
               grid[r][c + 1] == '*';
    }

    /**
     * Clears the cross pattern centered at (r, c).
     * Changes the center and contiguous '*' segments in all 4 directions to '#'.
     */
    private static void clearCrossPattern(char[][] grid, int r, int c) {
        // Clear center
        grid[r][c] = '#';

        // Clear Vertical Up
        for (int i = r - 1; i >= 0; i--) {
            if (grid[i][c] == '*') {
                grid[i][c] = '#';
            } else {
                break;
            }
        }

        // Clear Vertical Down
        for (int i = r + 1; i < grid.length; i++) {
            if (grid[i][c] == '*') {
                grid[i][c] = '#';
            } else {
                break;
            }
        }

        // Clear Horizontal Left
        for (int j = c - 1; j >= 0; j--) {
            if (grid[r][j] == '*') {
                grid[r][j] = '#';
            } else {
                break;
            }
        }

        // Clear Horizontal Right
        for (int j = c + 1; j < grid[0].length; j++) {
            if (grid[r][j] == '*') {
                grid[r][j] = '#';
            } else {
                break;
            }
        }
    }

    /**
     * Helper class for fast input reading.
     */
    static class FastReader {
        BufferedReader br;
        StringTokenizer st;

        public FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    e.printStackTrace();
                    return null;
                }
            }
            return st.nextToken();
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

/**
 * Refactored Main class.
 * 
 * Improvements made:
 * 1. Removed static mutable state (graph, was) to improve thread safety and testability.
 * 2. Replaced explicit ArrayList graph with direct 2D array traversal (implicit graph) for better memory usage and cleaner code.
 * 3. Improved variable naming (e.g., 'n' -> 'numRows', 'a' -> 'grid', 'was' -> 'visited').
 * 4. Encapsulated Fast I/O logic into a dedicated inner class.
 * 5. Separated logic into distinct steps (Read, Validate Connectivity, Find Center, Validate Shape).
 * 6. Ensured proper resource management for PrintWriter.
 */
public class Main {

    // Fast I/O helper class to handle input parsing efficiently
    static class FastScanner {
        BufferedReader br;
        StringTokenizer st;

        public FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            String s = next();
            if (s == null) throw new RuntimeException("End of input");
            return Integer.parseInt(s);
        }
    }

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner();
        PrintWriter out = new PrintWriter(System.out);

        // Run the logic in a new instance to avoid static state pollution
        new Main().run(scanner, out);

        out.flush();
    }

    void run(FastScanner scanner, PrintWriter out) {
        // 1. Read dimensions
        String nStr = scanner.next();
        if (nStr == null) return; // Handle empty input
        int numRows = scanner.nextInt();
        int numCols = scanner.nextInt();

        // 2. Read Grid
        // Using a boolean grid simplifies logic compared to char[][]
        boolean[][] isStar = new boolean[numRows][numCols];
        for (int i = 0; i < numRows; i++) {
            String rowStr = scanner.next();
            for (int j = 0; j < numCols; j++) {
                isStar[i][j] = (rowStr.charAt(j) == '*');
            }
        }

        // 3. Check Connectivity (Count Connected Components)
        boolean[][] visited = new boolean[numRows][numCols];
        int componentCount = 0;

        for (int i = 0; i < numRows; i++) {
            for (int j = 0; j < numCols; j++) {
                // If we find an unvisited star, it's a new component
                if (isStar[i][j] && !visited[i][j]) {
                    dfs(i, j, numRows, numCols, isStar, visited);
                    componentCount++;
                }
            }
        }

        // Condition 1: All stars must form a single connected component
        if (componentCount > 1) {
            out.println("NO");
            return;
        }

        // 4. Find the "Center" (a star surrounded by stars on all 4 sides)
        int centerRow = -1;
        int centerCol = -1;
        boolean centerFound = false;

        // Optimization: Center cannot be on the border
        for (int i = 1; i < numRows - 1; i++) {
            for (int j = 1; j < numCols - 1; j++) {
                if (isStar[i][j]) {
                    // Check 4 neighbors
                    if (isStar[i - 1][j] && isStar[i + 1][j] &&
                        isStar[i][j - 1] && isStar[i][j + 1]) {
                        centerRow = i;
                        centerCol = j;
                        centerFound = true;
                        break;
                    }
                }
            }
            if (centerFound) break;
        }

        // Condition 2: A valid configuration must have a center
        if (!centerFound) {
            out.println("NO");
            return;
        }

        // 5. Validate Shape (All stars must lie on the center's row or column)
        for (int i = 0; i < numRows; i++) {
            for (int j = 0; j < numCols; j++) {
                if (isStar[i][j]) {
                    // A star is valid if it is on the center's row OR center's column
                    if (i != centerRow && j != centerCol) {
                        out.println("NO");
                        return;
                    }
                }
            }
        }

        // If all checks pass
        out.println("YES");
    }

    // Depth First Search to traverse connected components of stars
    void dfs(int r, int c, int rows, int cols, boolean[][] grid, boolean[][] visited) {
        visited[r][c] = true;

        // Directions: Up, Down, Left, Right
        int[] dr = {-1, 1, 0, 0};
        int[] dc = {0, 0, -1, 1};

        for (int k = 0; k < 4; k++) {
            int nr = r + dr[k];
            int nc = c + dc[k];

            // Check bounds
            if (nr >= 0 && nr < rows && nc >= 0 && nc < cols) {
                // Recurse if neighbor is a star and not visited
                if (grid[nr][nc] && !visited[nr][nc]) {
                    dfs(nr, nc, rows, cols, grid, visited);
                }
            }
        }
    }
}

import java.util.Scanner;

/**
 * Refactored version of the CodeForces grid validator.
 * 
 * Improvements made:
 * 1. Naming: Used descriptive variable names (e.g., 'rows', 'cols', 'grid', 'centerRow')
 *    instead of single letters or vague names ('h', 'w', 'array', 'posI').
 * 2. Structure: Extracted logic into helper methods ('getArmLength') to reduce duplication
 *    and improve readability.
 * 3. Data Structure: Changed from 'boolean[][]' to 'char[][]' to store the grid directly
 *    from input, reducing parsing overhead.
 * 4. Bug Fixes:
 *    - Fixed the neighbor check logic which was checking the bottom neighbor twice and 
 *      missing the top neighbor.
 *    - Fixed the final validation logic which incorrectly rejected valid plus signs 
 *      (original code rejected any star that wasn't the center, invalidating the arms).
 * 5. Efficiency: Used a total star count comparison to validate the grid, which is cleaner
 *    than iterating the grid multiple times with complex flags.
 */
public class PlusSignValidator {

    public static void main(String[] args) {
        // Use standard Scanner for input
        Scanner scanner = new Scanner(System.in);

        // Read dimensions
        if (!scanner.hasNextInt()) {
            return;
        }
        int rows = scanner.nextInt();
        int cols = scanner.nextInt();

        // Read grid
        char[][] grid = new char[rows][cols];
        int totalStars = 0;

        for (int i = 0; i < rows; i++) {
            String line = scanner.next();
            grid[i] = line.toCharArray();
            // Count total stars in the grid for final validation
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == '*') {
                    totalStars++;
                }
            }
        }

        // 1. Find a valid center (i, j)
        // A valid center must have '*' at (i, j) and its 4 immediate neighbors.
        int centerRow = -1;
        int centerCol = -1;
        boolean foundCenter = false;

        // Iterate excluding borders since center needs neighbors
        for (int i = 1; i < rows - 1; i++) {
            for (int j = 1; j < cols - 1; j++) {
                if (grid[i][j] == '*' &&
                    grid[i - 1][j] == '*' && // Top neighbor (Fixed bug: was missing)
                    grid[i + 1][j] == '*' && // Bottom neighbor
                    grid[i][j - 1] == '*' && // Left neighbor
                    grid[i][j + 1] == '*') {  // Right neighbor
                    centerRow = i;
                    centerCol = j;
                    foundCenter = true;
                    break;
                }
            }
            if (foundCenter) {
                break;
            }
        }

        if (!foundCenter) {
            System.out.println("NO");
            scanner.close();
            return;
        }

        // 2. Validate arms and calculate the size of the plus sign
        // We check each of the 4 directions. If an arm is invalid (star after gap), return NO.
        // We also count the stars in valid arms to verify against totalStars.

        int plusSize = 1; // Start with the center star

        // Left Arm (direction: 0, -1)
        int leftLen = getArmLength(grid, centerRow, centerCol, 0, -1, rows, cols);
        if (leftLen == -1) {
            System.out.println("NO");
            scanner.close();
            return;
        }
        plusSize += leftLen;

        // Right Arm (direction: 0, 1)
        int rightLen = getArmLength(grid, centerRow, centerCol, 0, 1, rows, cols);
        if (rightLen == -1) {
            System.out.println("NO");
            scanner.close();
            return;
        }
        plusSize += rightLen;

        // Top Arm (direction: -1, 0)
        int topLen = getArmLength(grid, centerRow, centerCol, -1, 0, rows, cols);
        if (topLen == -1) {
            System.out.println("NO");
            scanner.close();
            return;
        }
        plusSize += topLen;

        // Bottom Arm (direction: 1, 0)
        int bottomLen = getArmLength(grid, centerRow, centerCol, 1, 0, rows, cols);
        if (bottomLen == -1) {
            System.out.println("NO");
            scanner.close();
            return;
        }
        plusSize += bottomLen;

        // 3. Final Validation
        // The total number of stars in the grid must exactly match the size of the plus sign.
        // This ensures there are no stray stars outside the plus shape.
        // (Original code had a logic error here that rejected valid plus signs)
        if (totalStars == plusSize) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }

        scanner.close();
    }

    /**
     * Scans a direction from the center to find the length of the contiguous star arm.
     * Returns -1 if the arm is invalid (i.e., a star appears after a gap).
     * 
     * @param grid The grid
     * @param startR Starting row (center)
     * @param startC Starting col (center)
     * @param dr Row direction increment
     * @param dc Col direction increment
     * @param rows Total rows
     * @param cols Total cols
     * @return Length of the arm (number of stars), or -1 if invalid.
     */
    private static int getArmLength(char[][] grid, int startR, int startC, int dr, int dc, int rows, int cols) {
        int length = 0;
        boolean seenGap = false;

        int currR = startR + dr;
        int currC = startC + dc;

        // Scan until boundary
        while (currR >= 0 && currR < rows && currC >= 0 && currC < cols) {
            if (grid[currR][currC] == '*') {
                if (seenGap) {
                    // Found a star after a gap -> Invalid arm
                    return -1;
                }
                length++;
            } else {
                // Found a non-star (gap)
                seenGap = true;
            }

            currR += dr;
            currC += dc;
        }

        return length;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

public class GridCrossChecker {

    private static final char STAR = '*';
    private static final char MARKED = 'X';

    public static void main(String[] args) {
        // Use try-with-resources to ensure proper cleanup of I/O streams
        try (FastScanner in = new FastScanner(System.in);
             PrintWriter out = new PrintWriter(System.out)) {
            solve(in, out);
        } catch (IOException e) {
            System.err.println("I/O error occurred: " + e.getMessage());
        }
    }

    /**
     * Orchestrates the grid processing logic.
     */
    static void solve(FastScanner in, PrintWriter out) {
        int n = in.nextInt();
        int m = in.nextInt();

        char[][] grid = new char[n][m];
        for (int i = 0; i < n; i++) {
            grid[i] = in.next().toCharArray();
        }

        int[] center = findCenter(grid, n, m);
        if (center == null) {
            out.println("NO");
            return;
        }

        // Mark the center star as processed
        grid[center[0]][center[1]] = MARKED;

        // Traverse all 4 directions from the center, marking stars and tracking progress
        boolean[] directions = traverseAndMark(grid, center[0], center[1], n, m);
        boolean allDirections = directions[0] && directions[1] && directions[2] && directions[3];

        // Verify that no unmarked stars remain in the grid
        boolean allStarsMarked = !hasUnmarkedStar(grid, n, m);

        out.println(allDirections && allStarsMarked ? "YES" : "NO");
    }

    /**
     * Locates the central star that has stars in all four cardinal directions.
     */
    private static int[] findCenter(char[][] grid, int n, int m) {
        for (int i = 1; i < n - 1; i++) {
            for (int j = 1; j < m - 1; j++) {
                if (grid[i][j] == STAR &&
                    grid[i - 1][j] == STAR && grid[i + 1][j] == STAR &&
                    grid[i][j - 1] == STAR && grid[i][j + 1] == STAR) {
                    return new int[]{i, j};
                }
            }
        }
        return null;
    }

    /**
     * Traverses outward from the center in all four directions.
     * Marks encountered stars and records whether each direction was extended.
     */
    private static boolean[] traverseAndMark(char[][] grid, int startI, int startJ, int n, int m) {
        boolean[] directions = new boolean[4]; // up, down, left, right
        int[][] dirs = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};

        for (int d = 0; d < 4; d++) {
            int di = dirs[d][0];
            int dj = dirs[d][1];
            int r = startI + di;
            int c = startJ + dj;

            while (r >= 0 && r < n && c >= 0 && c < m && grid[r][c] == STAR) {
                grid[r][c] = MARKED;
                directions[d] = true;
                r += di;
                c += dj;
            }
        }
        return directions;
    }

    /**
     * Checks if any unmarked stars remain in the grid.
     */
    private static boolean hasUnmarkedStar(char[][] grid, int n, int m) {
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == STAR) {
                    return true;
                }
            }
        }
        return false;
    }

    /**
     * Fast input scanner for performance-critical I/O.
     * Implements AutoCloseable for proper resource management.
     */
    static class FastScanner implements AutoCloseable {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner(InputStream in) {
            this.br = new BufferedReader(new InputStreamReader(in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input", e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            String s = next();
            if (s == null) throw new RuntimeException("Unexpected end of input");
            return Integer.parseInt(s);
        }

        @Override
        public void close() throws IOException {
            br.close();
        }
    }
}

import java.util.Scanner;

public class B_PlusFromPicture {

    // Constants for better readability and maintainability
    private static final char STAR = '*';
    private static final String RESULT_YES = "YES";
    private static final String RESULT_NO = "NO";

    public static void main(String[] args) {
        // Using Scanner for cleaner input handling compared to the custom FastReader.
        // Note: For extremely large inputs in competitive programming, BufferedReader is preferred,
        // but Scanner is standard for general Java code quality and maintainability.
        Scanner scanner = new Scanner(System.in);

        // Check if input exists
        if (!scanner.hasNextInt()) {
            return;
        }

        int rows = scanner.nextInt();
        int cols = scanner.nextInt();

        // Use a 2D char array for easier grid manipulation
        char[][] grid = new char[rows][cols];
        int totalStarCount = 0;

        // Read the grid content and count total stars
        for (int i = 0; i < rows; i++) {
            if (scanner.hasNext()) {
                String line = scanner.next();
                grid[i] = line.toCharArray();
                // Count stars during input reading for efficiency
                for (char c : line.toCharArray()) {
                    if (c == STAR) {
                        totalStarCount++;
                    }
                }
            }
        }

        // Determine if the grid forms a valid plus shape
        if (isValidPlusShape(grid, rows, cols, totalStarCount)) {
            System.out.println(RESULT_YES);
        } else {
            System.out.println(RESULT_NO);
        }

        scanner.close();
    }

    /**
     * Checks if the grid contains a valid plus sign shape that accounts for all stars.
     *
     * @param grid The 2D character array representing the picture
     * @param rows Number of rows
     * @param cols Number of columns
     * @param totalStarCount Total number of stars in the grid
     * @return true if a valid plus shape exists covering all stars, false otherwise
     */
    private static boolean isValidPlusShape(char[][] grid, int rows, int cols, int totalStarCount) {
        // A valid plus sign must have at least 5 stars (center + 4 arms of length 1)
        if (totalStarCount < 5) {
            return false;
        }

        // Iterate through the grid to find a potential center of the plus sign.
        // A center cannot be on the border (index 0 or max) because it requires neighbors in all 4 directions.
        // Optimization: Start from 1 and end at rows/cols - 2.
        for (int r = 1; r < rows - 1; r++) {
            for (int c = 1; c < cols - 1; c++) {
                // Check if current cell is a star
                if (grid[r][c] == STAR) {
                    // Check if it has star neighbors in all 4 cardinal directions
                    if (hasStarNeighbors(grid, r, c)) {
                        // Calculate the total number of stars in the plus shape centered here
                        int plusShapeStarCount = calculatePlusLength(grid, r, c, rows, cols);

                        // If the count matches the total stars in the grid, we found our shape
                        if (plusShapeStarCount == totalStarCount) {
                            return true;
                        }
                    }
                }
            }
        }

        return false;
    }

    /**
     * Checks if the cell at (r, c) has stars in all 4 adjacent directions (up, down, left, right).
     */
    private static boolean hasStarNeighbors(char[][] grid, int r, int c) {
        return grid[r - 1][c] == STAR && // Up
               grid[r + 1][c] == STAR && // Down
               grid[r][c - 1] == STAR && // Left
               grid[r][c + 1] == STAR;    // Right
    }

    /**
     * Calculates the number of stars in the plus shape centered at (r, c).
     * This includes the center and extends in all 4 directions until a non-star is found.
     */
    private static int calculatePlusLength(char[][] grid, int r, int c, int rows, int cols) {
        int count = 1; // Start with the center star

        // Count stars to the Left
        for (int k = c - 1; k >= 0; k--) {
            if (grid[r][k] == STAR) {
                count++;
            } else {
                break;
            }
        }

        // Count stars to the Right
        for (int k = c + 1; k < cols; k++) {
            if (grid[r][k] == STAR) {
                count++;
            } else {
                break;
            }
        }

        // Count stars Up
        for (int k = r - 1; k >= 0; k--) {
            if (grid[k][c] == STAR) {
                count++;
            } else {
                break;
            }
        }

        // Count stars Down
        for (int k = r + 1; k < rows; k++) {
            if (grid[k][c] == STAR) {
                count++;
            } else {
                break;
            }
        }

        return count;
    }
}

