/**
 * Solves the cross pattern detection problem.
 * Checks if all '*' characters in the grid form a single cross shape.
 */
class CrossPatternSolver {
    public void solve(InputReader in, PrintWriter out) {
        int rows = in.nextInt();
        int cols = in.nextInt();
        char[][] grid = new char[rows][cols];
        int totalStars = 0;

        // Read grid and count total stars
        for (int i = 0; i < rows; i++) {
            String line = in.next();
            for (int j = 0; j < cols; j++) {
                grid[i][j] = line.charAt(j);
                if (grid[i][j] == '*') {
                    totalStars++;
                }
            }
        }

        // A cross requires at least a 3x3 area
        if (rows < 3 || cols < 3) {
            out.println("NO");
            return;
        }

        // Find the center of the potential cross
        int centerRow = -1;
        int centerCol = -1;

        for (int i = 1; i < rows - 1; i++) {
            for (int j = 1; j < cols - 1; j++) {
                if (isCrossCenter(grid, i, j)) {
                    centerRow = i;
                    centerCol = j;
                    break;
                }
            }
            if (centerRow != -1) break;
        }

        if (centerRow == -1) {
            out.println("NO");
            return;
        }

        // Verify if the cross encompasses all stars in the grid
        int crossSize = calculateCrossSize(grid, centerRow, centerCol);
        if (crossSize == totalStars) {
            out.println("YES");
        } else {
            out.println("NO");
        }
    }

    /**
     * Checks if a given cell is the center of a cross.
     * A center must have '*' in all four cardinal directions.
     */
    private boolean isCrossCenter(char[][] grid, int r, int c) {
        return grid[r][c] == '*'
                && grid[r - 1][c] == '*'
                && grid[r + 1][c] == '*'
                && grid[r][c - 1] == '*'
                && grid[r][c + 1] == '*';
    }

    /**
     * Calculates the total number of '*' in the cross centered at (centerRow, centerCol).
     */
    private int calculateCrossSize(char[][] grid, int centerRow, int centerCol) {
        int size = 1; // Count the center itself
        size += countStarsInDirection(grid, centerRow, centerCol, -1, 0); // Up
        size += countStarsInDirection(grid, centerRow, centerCol, 1, 0);  // Down
        size += countStarsInDirection(grid, centerRow, centerCol, 0, -1); // Left
        size += countStarsInDirection(grid, centerRow, centerCol, 0, 1);  // Right
        return size;
    }

    /**
     * Counts consecutive '*' characters starting from (startRow, startCol)
     * moving in the direction specified by (dRow, dCol).
     */
    private int countStarsInDirection(char[][] grid, int startRow, int startCol, int dRow, int dCol) {
        int count = 0;
        int r = startRow + dRow;
        int c = startCol + dCol;

        while (r >= 0 && r < grid.length && c >= 0 && c < grid[0].length && grid[r][c] == '*') {
            count++;
            r += dRow;
            c += dCol;
        }
        return count;
    }
}

/**
 * Fast input reader for competitive programming.
 */
class InputReader {
    private final BufferedReader br;
    private StringTokenizer st;

    public InputReader(InputStream in) {
        this.br = new BufferedReader(new InputStreamReader(in));
    }

    public String next() {
        while (st == null || !st.hasMoreTokens()) {
            try {
                String line = br.readLine();
                if (line == null) {
                    throw new IOException("End of input");
                }
                st = new StringTokenizer(line);
            } catch (IOException e) {
                throw new RuntimeException(e);
            }
        }
        return st.nextToken();
    }

    public int nextInt() {
        return Integer.parseInt(next());
    }

    public long nextLong() {
        return Long.parseLong(next());
    }

    public double nextDouble() {
        return Double.parseDouble(next());
    }
}

import java.util.Scanner;

/**
 * Validates whether a given character grid contains a valid cross pattern.
 * A valid cross consists of '*' characters forming a cross shape, with all other 
 * cells being '.'. The center must have '*' in all four cardinal directions,
 * and the arms must extend to the grid boundaries.
 */
public class CrossPatternValidator {

    private static final char STAR = '*';
    private static final char EMPTY = '.';

    public static void main(String[] args) {
        // Use try-with-resources to ensure the scanner is properly closed
        try (Scanner scanner = new Scanner(System.in)) {
            if (!scanner.hasNextInt()) {
                return;
            }

            int rows = scanner.nextInt();
            int cols = scanner.nextInt();

            char[][] grid = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                String rowStr = scanner.next();
                if (rowStr.length() != cols) {
                    throw new IllegalArgumentException(
                        "Invalid input: row " + i + " has length " + rowStr.length() + 
                        ", expected " + cols
                    );
                }
                grid[i] = rowStr.toCharArray();
            }

            boolean isValid = validateCrossPattern(grid);
            System.out.println(isValid ? "YES" : "NO");
        }
    }

    /**
     * Orchestrates the validation of the cross pattern.
     */
    private static boolean validateCrossPattern(char[][] grid) {
        if (grid == null || grid.length == 0 || grid[0].length == 0) {
            return false;
        }

        int centerRow = -1;
        int centerCol = -1;

        // 1. Locate the center '*' that has '*' in all four adjacent directions
        for (int i = 1; i < grid.length - 1; i++) {
            for (int j = 1; j < grid[i].length - 1; j++) {
                if (grid[i][j] == STAR &&
                    grid[i - 1][j] == STAR &&
                    grid[i + 1][j] == STAR &&
                    grid[i][j - 1] == STAR &&
                    grid[i][j + 1] == STAR) {
                    centerRow = i;
                    centerCol = j;
                    break;
                }
            }
            if (centerRow != -1) {
                break;
            }
        }

        // If no valid center is found, the pattern cannot be a cross
        if (centerRow == -1) {
            return false;
        }

        // 2. Ensure all other cells in the grid contain only valid characters (STAR or EMPTY)
        for (int i = 0; i < grid.length; i++) {
            for (int j = 0; j < grid[i].length; j++) {
                if (i == centerRow && j == centerCol) {
                    continue;
                }
                if (grid[i][j] != EMPTY && grid[i][j] != STAR) {
                    return false;
                }
            }
        }

        // 3. Verify that all four directions from the center to the boundary are filled with STAR
        return isLineFilled(grid, centerRow, centerCol, -1, 0) &&
               isLineFilled(grid, centerRow, centerCol, 1, 0) &&
               isLineFilled(grid, centerRow, centerCol, 0, -1) &&
               isLineFilled(grid, centerRow, centerCol, 0, 1);
    }

    /**
     * Checks if a line starting adjacent to (startRow, startCol) in a given direction
     * is completely filled with STAR characters until the grid boundary.
     */
    private static boolean isLineFilled(char[][] grid, int startRow, int startCol, int deltaRow, int deltaCol) {
        int r = startRow + deltaRow;
        int c = startCol + deltaCol;

        while (r >= 0 && r < grid.length && c >= 0 && c < grid[0].length) {
            if (grid[r][c] != STAR) {
                return false;
            }
            r += deltaRow;
            c += deltaCol;
        }
        return true;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

public class R566B {

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner();
        int n = scanner.nextInt();
        int m = scanner.nextInt();

        char[][] board = new char[n][m];
        for (int i = 0; i < n; i++) {
            board[i] = scanner.next().toCharArray();
        }

        boolean hasStar = false;

        // Locate the first '*' and apply the problem's transformation rules
        outerLoop:
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (board[i][j] == '*') {
                    hasStar = true;

                    // Rule 1: Stars on the boundary are skipped for processing
                    if (isOnBoundary(i, j, n, m)) {
                        continue;
                    }

                    // Rule 2: Stars adjacent to '.' are skipped for processing
                    if (hasDotNeighbor(i, j, board)) {
                        continue;
                    }

                    // Rule 3: Clear connected '*'s in a cross pattern
                    clearCrossComponent(i, j, board, n, m);
                    break outerLoop; // Only the first valid star triggers the clear operation
                }
            }
        }

        // If no star was present initially, the condition fails
        if (!hasStar) {
            System.out.println("NO");
            return;
        }

        // After processing, check if any '*' remains
        if (containsStar(board)) {
            System.out.println("NO");
        } else {
            System.out.println("YES");
        }
    }

    /**
     * Checks if the given coordinates are on the grid boundary.
     */
    private static boolean isOnBoundary(int row, int col, int rows, int cols) {
        return row == 0 || col == 0 || row == rows - 1 || col == cols - 1;
    }

    /**
     * Checks if any of the four orthogonal neighbors contain '.'.
     * Pre-condition: (row, col) is strictly inside the grid.
     */
    private static boolean hasDotNeighbor(int row, int col, char[][] board) {
        int[] dr = {-1, 1, 0, 0};
        int[] dc = {0, 0, -1, 1};

        for (int k = 0; k < 4; k++) {
            int nr = row + dr[k];
            int nc = col + dc[k];
            if (board[nr][nc] == '.') {
                return true;
            }
        }
        return false;
    }

    /**
     * Clears '*' characters in a cross pattern starting from (row, col)
     * until a '.' or the grid boundary is encountered.
     */
    private static void clearCrossComponent(int row, int col, char[][] board, int rows, int cols) {
        int[] dr = {-1, 1, 0, 0};
        int[] dc = {0, 0, -1, 1};

        for (int k = 0; k < 4; k++) {
            int nr = row + dr[k];
            int nc = col + dc[k];
            while (nr >= 0 && nr < rows && nc >= 0 && nc < cols && board[nr][nc] == '*') {
                board[nr][nc] = '.';
                nr += dr[k];
                nc += dc[k];
            }
        }
        board[row][col] = '.';
    }

    /**
     * Checks if the grid contains any '*' character.
     */
    private static boolean containsStar(char[][] board) {
        for (char[] row : board) {
            for (char cell : row) {
                if (cell == '*') {
                    return true;
                }
            }
        }
        return false;
    }

    /**
     * Efficient input reader for competitive programming.
     * Replaces the original complex JS class with a standard, maintainable implementation.
     */
    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            String s = next();
            return (s == null) ? 0 : Integer.parseInt(s);
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

/**
 * Refactored solution for the Plus Picture problem.
 * 
 * Improvements made:
 * 1. Replaced StringBuilder array with char[][] for better performance and readability.
 * 2. Encapsulated input reading logic into a cleaner FastScanner helper.
 * 3. Improved variable naming (h/w -> rows/cols, arr -> grid).
 * 4. Structured the logic to separate finding the pattern, modifying it, and verification.
 * 5. Used try-with-resources for resource management.
 */
public class PlusPicture {

    public static void main(String[] args) {
        // Use try-with-resources to ensure streams are closed properly
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
             PrintWriter out = new PrintWriter(System.out)) {

            FastScanner sc = new FastScanner(br);

            // Read dimensions
            String hStr = sc.next();
            if (hStr == null) return; // End of input
            int rows = Integer.parseInt(hStr);

            String wStr = sc.next();
            if (wStr == null) return;
            int cols = Integer.parseInt(wStr);

            // Read the grid into a 2D char array
            char[][] grid = new char[rows][];
            for (int i = 0; i < rows; i++) {
                String rowStr = sc.next();
                if (rowStr != null) {
                    grid[i] = rowStr.toCharArray();
                }
            }

            // Variables to store the position of the plus sign center
            int centerRow = -1;
            int centerCol = -1;
            boolean found = false;

            // 1. Search for the center of the plus sign
            // The center cannot be on the border (indices 0 or rows-1, cols-1)
            for (int i = 1; i < rows - 1; i++) {
                for (int j = 1; j < cols - 1; j++) {
                    // Check if current cell is '*' and all 4 neighbors are '*'
                    if (grid[i][j] == '*' &&
                        grid[i - 1][j] == '*' &&
                        grid[i + 1][j] == '*' &&
                        grid[i][j - 1] == '*' &&
                        grid[i][j + 1] == '*') {

                        found = true;
                        centerRow = i;
                        centerCol = j;
                        break; // Found the center, exit inner loop
                    }
                }
                if (found) break; // Exit outer loop
            }

            // 2. If a plus sign is found, fill it with '#'
            if (found) {
                // Fill center
                grid[centerRow][centerCol] = '#';

                // Fill Up
                for (int r = centerRow - 1; r >= 0; r--) {
                    if (grid[r][centerCol] == '*') {
                        grid[r][centerCol] = '#';
                    } else {
                        break; // Stop if we hit a non-'*' character
                    }
                }

                // Fill Down
                for (int r = centerRow + 1; r < rows; r++) {
                    if (grid[r][centerCol] == '*') {
                        grid[r][centerCol] = '#';
                    } else {
                        break;
                    }
                }

                // Fill Left
                for (int c = centerCol - 1; c >= 0; c--) {
                    if (grid[centerRow][c] == '*') {
                        grid[centerRow][c] = '#';
                    } else {
                        break;
                    }
                }

                // Fill Right
                for (int c = centerCol + 1; c < cols; c++) {
                    if (grid[centerRow][c] == '*') {
                        grid[centerRow][c] = '#';
                    } else {
                        break;
                    }
                }

                // 3. Verify if any '*' remains in the grid
                boolean allCleared = true;
                searchLoop:
                for (int i = 0; i < rows; i++) {
                    for (int j = 0; j < cols; j++) {
                        if (grid[i][j] == '*') {
                            allCleared = false;
                            break searchLoop;
                        }
                    }
                }

                if (allCleared) {
                    out.println("YES");
                } else {
                    out.println("NO");
                }
            } else {
                // No valid plus sign found
                out.println("NO");
            }

        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    /**
     * Helper class for fast input reading.
     */
    static class FastScanner {
        BufferedReader br;
        StringTokenizer st;

        public FastScanner(BufferedReader br) {
            this.br = br;
        }

        public String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    e.printStackTrace();
                    return null;
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            String s = next();
            if (s == null) throw new RuntimeException("End of input");
            return Integer.parseInt(s);
        }
    }
}

import java.util.Scanner;

public class Main {
    // Direction vectors for orthogonal movement: Up, Left, Right, Down
    private static final int[] DR = {-1, 0, 0, 1};
    private static final int[] DC = {0, -1, 1, 0};

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        if (!scanner.hasNextInt()) {
            scanner.close();
            return;
        }

        int rows = scanner.nextInt();
        int cols = scanner.nextInt();

        char[][] grid = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            grid[i] = scanner.next().toCharArray();
        }

        boolean isValid = isValidConfiguration(grid, rows, cols);
        System.out.println(isValid ? "YES" : "NO");
        scanner.close();
    }

    /**
     * Validates the grid configuration according to the problem rules:
     * 1. Exactly one connected component of '*'
     * 2. Exactly one center '*' with all 4 orthogonal neighbors as '*'
     * 3. All other '*' cells must be adjacent to the center
     */
    private static boolean isValidConfiguration(char[][] grid, int rows, int cols) {
        // A center with 4 orthogonal neighbors requires at least a 3x3 area
        if (rows < 3 || cols < 3) {
            return false;
        }

        // 1. Check for exactly one connected component of '*'
        boolean[][] visited = new boolean[rows][cols];
        int componentCount = 0;
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == '*' && !visited[i][j]) {
                    componentCount++;
                    if (componentCount > 1) {
                        return false;
                    }
                    dfs(grid, visited, i, j);
                }
            }
        }
        if (componentCount == 0) {
            return false;
        }

        // 2. Find the unique center '*' with all 4 orthogonal neighbors as '*'
        int centerRow = -1;
        int centerCol = -1;
        int centerCount = 0;

        for (int i = 1; i < rows - 1; i++) {
            for (int j = 1; j < cols - 1; j++) {
                if (isCrossCenter(grid, i, j)) {
                    centerRow = i;
                    centerCol = j;
                    centerCount++;
                }
            }
        }
        if (centerCount != 1) {
            return false;
        }

        // 3. Validate that all '*' cells are either the center or adjacent to it
        // Note: Original code had a logical bug here (checked center_x != i && center_y != j)
        // which would always fail for valid inputs. Fixed to properly check adjacency.
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == '*' 
                        && !(i == centerRow && j == centerCol) 
                        && !isAdjacent(i, j, centerRow, centerCol)) {
                    return false;
                }
            }
        }

        return true;
    }

    /**
     * Checks if a cell is a valid cross-center (has '*' in all 4 orthogonal directions)
     */
    private static boolean isCrossCenter(char[][] grid, int r, int c) {
        return grid[r][c] == '*'
                && grid[r - 1][c] == '*'
                && grid[r][c - 1] == '*'
                && grid[r][c + 1] == '*'
                && grid[r + 1][c] == '*';
    }

    /**
     * Checks if two cells are orthogonally adjacent using Manhattan distance
     */
    private static boolean isAdjacent(int r1, int c1, int r2, int c2) {
        return Math.abs(r1 - r2) + Math.abs(c1 - c2) == 1;
    }

    /**
     * Performs Depth-First Search to mark all cells in the connected component
     */
    private static void dfs(char[][] grid, boolean[][] visited, int r, int c) {
        visited[r][c] = true;
        for (int k = 0; k < DR.length; k++) {
            int nr = r + DR[k];
            int nc = c + DC[k];
            if (isInside(nr, nc, grid.length, grid[0].length) 
                    && !visited[nr][nc] 
                    && grid[nr][nc] == '*') {
                dfs(grid, visited, nr, nc);
            }
        }
    }

    /**
     * Checks if coordinates are within grid boundaries
     */
    private static boolean isInside(int r, int c, int rows, int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }
}

import java.io.*;
import java.util.*;

public class Main {

    public static void main(String[] args) {
        FastReader reader = new FastReader();

        // Read grid dimensions
        int h = reader.nextInt();
        int w = reader.nextInt();

        // Consume the remaining newline after the second integer
        reader.nextLine();

        String[] grid = new String[h];
        for (int i = 0; i < h; i++) {
            grid[i] = reader.nextLine();
        }

        boolean isPatternValid = solve(grid);
        System.out.println(isPatternValid ? "YES" : "NO");
    }

    /**
     * Solves the grid pattern matching problem.
     * Expects a vertical sequence of exactly three row types:
     * 1. A row with exactly one '*'
     * 2. A "bridge" row with >= 3 consecutive '*'s, where the column of the first '*' 
     *    is strictly inside this row's star range
     * 3. A row with exactly one '*' at the same column, immediately following the bridge
     * Any other '*' characters in any row result in an invalid pattern.
     */
    private static boolean solve(String[] grid) {
        boolean foundFirstSingle = false;
        int firstSingleCol = -1;
        int firstSingleRow = -1;

        boolean foundBridge = false;
        boolean foundSecondSingle = false;

        for (int i = 0; i < grid.length; i++) {
            RowAnalysis analysis = analyzeRow(grid[i]);

            // Empty rows are safely ignored
            if (analysis.count == 0) {
                continue;
            }

            if (analysis.count == 1) {
                if (!foundFirstSingle) {
                    // First single '*' row
                    foundFirstSingle = true;
                    firstSingleCol = analysis.minCol;
                    firstSingleRow = i;
                } else if (foundBridge && i == firstSingleRow + 1 && analysis.minCol == firstSingleCol) {
                    // Second single '*' row immediately after the bridge, at the same column
                    foundSecondSingle = true;
                } else {
                    // Unexpected single '*' row breaks the pattern
                    return false;
                }
            } else if (analysis.count >= 3 && analysis.isConsecutive && foundFirstSingle && !foundBridge) {
                // Bridge row: consecutive stars, count >= 3, and first single star's column is strictly inside
                if (firstSingleCol > analysis.minCol && firstSingleCol < analysis.maxCol) {
                    foundBridge = true;
                } else {
                    // Bridge doesn't cover the required column
                    return false;
                }
            } else {
                // Invalid row pattern (e.g., multiple disjoint stars, or wrong sequence)
                return false;
            }
        }

        return foundFirstSingle && foundBridge && foundSecondSingle;
    }

    /**
     * Analyzes a single row to extract star positions and properties.
     */
    private static RowAnalysis analyzeRow(String row) {
        int count = 0;
        int minCol = Integer.MAX_VALUE;
        int maxCol = Integer.MIN_VALUE;
        int maxGap = 0;
        int lastPos = -1;

        for (int j = 0; j < row.length(); j++) {
            if (row.charAt(j) == '*') {
                count++;
                if (j < minCol) minCol = j;
                if (j > maxCol) maxCol = j;

                if (lastPos != -1) {
                    int gap = j - lastPos;
                    if (gap > maxGap) maxGap = gap;
                }
                lastPos = j;
            }
        }

        // Consecutive means all gaps between stars are exactly 1
        boolean isConsecutive = count > 1 && maxGap == 1;

        return new RowAnalysis(count, minCol, maxCol, isConsecutive);
    }

    /**
     * Immutable data class to hold row analysis results.
     */
    private static class RowAnalysis {
        final int count;
        final int minCol;
        final int maxCol;
        final boolean isConsecutive;

        RowAnalysis(int count, int minCol, int maxCol, boolean isConsecutive) {
            this.count = count;
            this.minCol = minCol;
            this.maxCol = maxCol;
            this.isConsecutive = isConsecutive;
        }
    }

    /**
     * Fast I/O helper class.
     */
    static class FastReader {
        BufferedReader br;
        StringTokenizer st;

        public FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input", e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        String nextLine() {
            try {
                return br.readLine();
            } catch (IOException e) {
                throw new RuntimeException("Failed to read line", e);
            }
        }
    }
}

import java.io.*;
import java.util.*;

public class TaskE implements Runnable {
    private FastScanner inputReader;
    private PrintWriter outputWriter;

    public static void main(String[] args) {
        // Standard competitive programming trick to increase thread stack size to 64MB
        new Thread(null, new TaskE(), "TaskE", 1 << 26).start();
    }

    @Override
    public void run() {
        inputReader = new FastScanner(System.in);
        // Try-with-resources ensures PrintWriter is properly flushed and closed
        try (outputWriter = new PrintWriter(System.out)) {
            solve();
        }
    }

    private void solve() {
        int n = inputReader.nextInt();
        int m = inputReader.nextInt();
        char[][] grid = new char[n][];
        for (int i = 0; i < n; i++) {
            grid[i] = inputReader.next().toCharArray();
        }

        int totalStars = countTotalStars(grid, n, m);
        if (findAndVerifyCross(grid, n, m, totalStars)) {
            outputWriter.println("YES");
        } else {
            outputWriter.println("NO");
        }
    }

    /**
     * Counts the total number of '*' characters in the grid.
     */
    private int countTotalStars(char[][] grid, int n, int m) {
        int count = 0;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == '*') {
                    count++;
                }
            }
        }
        return count;
    }

    /**
     * Checks if there exists a cross pattern that covers all stars in the grid.
     * A valid cross must have its center and 4 immediate neighbors as '*',
     * and the total stars in the cross must equal the total stars in the grid.
     */
    private boolean findAndVerifyCross(char[][] grid, int n, int m, int totalStars) {
        // Iterate over all possible center positions (excluding grid borders)
        for (int i = 1; i < n - 1; i++) {
            for (int j = 1; j < m - 1; j++) {
                // Verify center and 4 neighbors are stars
                if (grid[i][j] != '*' ||
                    grid[i - 1][j] != '*' ||
                    grid[i][j - 1] != '*' ||
                    grid[i][j + 1] != '*' ||
                    grid[i + 1][j] != '*') {
                    continue;
                }

                int crossStars = 1; // Start with the center star

                // Count vertical arm upwards
                int x = i - 1;
                while (x >= 0 && grid[x][j] == '*') {
                    crossStars++;
                    x--;
                }
                // Count vertical arm downwards
                x = i + 1;
                while (x < n && grid[x][j] == '*') {
                    crossStars++;
                    x++;
                }
                // Count horizontal arm leftwards
                int y = j - 1;
                while (y >= 0 && grid[i][y] == '*') {
                    crossStars++;
                    y--;
                }
                // Count horizontal arm rightwards
                y = j + 1;
                while (y < m && grid[i][y] == '*') {
                    crossStars++;
                    y++;
                }

                // If the cross covers exactly all stars in the grid, we found a valid configuration
                if (crossStars == totalStars) {
                    return true;
                }
            }
        }
        return false;
    }

    /**
     * Optimized fast input reader for competitive programming.
     * Removed unused methods and simplified for better maintainability.
     */
    static class FastScanner {
        private final InputStream stream;
        private final byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;

        public FastScanner(InputStream stream) {
            this.stream = stream;
        }

        private int read() {
            if (numChars == -1) {
                throw new InputMismatchException();
            }
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0) {
                    return -1;
                }
            }
            return buf[curChar++];
        }

        public int nextInt() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                res *= 10;
                res += c - '0';
                c = read();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public String next() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            StringBuilder res = new StringBuilder();
            do {
                res.appendCodePoint(c);
                c = read();
            } while (!isSpaceChar(c));
            return res.toString();
        }

        private boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;

public class Codechef {
    public static void main(String[] args) throws IOException {
        // Use try-with-resources to ensure streams are properly closed
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
             PrintWriter out = new PrintWriter(System.out)) {
            solve(br, out);
        }
    }

    private static void solve(BufferedReader br, PrintWriter out) throws IOException {
        // Read dimensions
        String line = br.readLine();
        if (line == null) return;

        String[] dimensions = line.trim().split("\\s+");
        int n = Integer.parseInt(dimensions[0]);
        int m = Integer.parseInt(dimensions[1]);

        // Parse grid and count total stars
        int[][] grid = new int[n][m];
        int totalStars = 0;

        for (int i = 0; i < n; i++) {
            String row = br.readLine();
            for (int j = 0; j < m; j++) {
                // Safely handle potentially malformed input lines
                if (row != null && j < row.length() && row.charAt(j) == '*') {
                    grid[i][j] = 1;
                    totalStars++;
                } else {
                    grid[i][j] = 0;
                }
            }
        }

        // Determine if all stars form a single cross pattern
        boolean isCrossPattern = checkCrossPattern(grid, n, m, totalStars);
        out.println(isCrossPattern ? "YES" : "NO");
    }

    /**
     * Checks if all '*' in the grid form exactly one cross shape.
     * A cross is defined by a center point with '*' extending in all 4 cardinal directions.
     */
    private static boolean checkCrossPattern(int[][] grid, int n, int m, int totalStars) {
        // A valid cross requires an interior center and at least one star
        if (n < 3 || m < 3 || totalStars == 0) {
            return false;
        }

        // Iterate over all possible center points (must have 4 neighbors)
        for (int i = 1; i < n - 1; i++) {
            for (int j = 1; j < m - 1; j++) {
                // Quick check: center and immediate neighbors must be '*'
                if (grid[i][j] == 1 &&
                    grid[i - 1][j] == 1 &&
                    grid[i + 1][j] == 1 &&
                    grid[i][j - 1] == 1 &&
                    grid[i][j + 1] == 1) {

                    // Count consecutive stars in each direction
                    int up = countConsecutive(grid, i, j, -1, 0);
                    int down = countConsecutive(grid, i, j, 1, 0);
                    int left = countConsecutive(grid, i, j, 0, -1);
                    int right = countConsecutive(grid, i, j, 0, 1);

                    // Total stars in the cross = arms + center
                    int crossSize = up + down + left + right + 1;

                    // If the cross contains exactly all stars in the grid, we found our pattern
                    if (crossSize == totalStars) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Counts consecutive '*' cells starting from (r, c) moving in direction (dr, dc).
     * Does not include the starting cell itself.
     */
    private static int countConsecutive(int[][] grid, int r, int c, int dr, int dc) {
        int count = 0;
        int nr = r + dr;
        int nc = c + dc;

        while (nr >= 0 && nr < grid.length && 
               nc >= 0 && nc < grid[0].length && 
               grid[nr][nc] == 1) {
            count++;
            nr += dr;
            nc += dc;
        }
        return count;
    }
}

import java.io.InputStream;
import java.io.IOException;
import java.io.OutputStream;
import java.io.PrintWriter;
import java.util.InputMismatchException;

public class Main {
    public static void main(String[] args) {
        FastScanner scanner = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out);
        BPlusFromPicture solver = new BPlusFromPicture();
        solver.solve(scanner, out);
        out.close();
    }

    static class BPlusFromPicture {
        private static final char SHAPE_CHAR = '*';
        // Direction vectors: Right, Left, Down, Up
        private static final int[] DX = {0, 0, 1, -1};
        private static final int[] DY = {1, -1, 0, 0};

        /**
         * Solves the B+ shape detection problem.
         * Identifies crosses of '*' characters, marks all cells belonging to them,
         * and verifies if exactly one such shape covers all '*' in the grid.
         */
        public void solve(FastScanner scanner, PrintWriter out) {
            int width = scanner.nextInt();
            int height = scanner.nextInt();

            // Standard grid layout: grid[row][col]
            char[][] grid = new char[height][width];
            for (int r = 0; r < height; r++) {
                for (int c = 0; c < width; c++) {
                    grid[r][c] = scanner.nextCharacter();
                }
            }

            boolean[][] used = new boolean[height][width];
            int shapeCount = 0;

            // Iterate over potential centers (excluding borders)
            for (int r = 1; r < height - 1; r++) {
                for (int c = 1; c < width - 1; c++) {
                    if (grid[r][c] == SHAPE_CHAR && isCrossCenter(grid, r, c)) {
                        shapeCount++;
                        markCross(grid, used, r, c);
                    }
                }
            }

            // Verify if all '*' characters are covered by exactly one shape
            boolean allCovered = true;
            outerLoop:
            for (int r = 0; r < height; r++) {
                for (int c = 0; c < width; c++) {
                    if (grid[r][c] == SHAPE_CHAR && !used[r][c]) {
                        allCovered = false;
                        break outerLoop;
                    }
                }
            }

            if (shapeCount == 1 && allCovered) {
                out.println("YES");
            } else {
                out.println("NO");
            }
        }

        /**
         * Checks if the given cell is the center of a cross (B+ shape).
         * A cross center must have '*' in all four cardinal directions.
         */
        private boolean isCrossCenter(char[][] grid, int r, int c) {
            return grid[r - 1][c] == SHAPE_CHAR &&
                   grid[r + 1][c] == SHAPE_CHAR &&
                   grid[r][c - 1] == SHAPE_CHAR &&
                   grid[r][c + 1] == SHAPE_CHAR;
        }

        /**
         * Marks the center and all contiguous '*' cells in all four directions.
         */
        private void markCross(char[][] grid, boolean[][] used, int r, int c) {
            used[r][c] = true;

            for (int d = 0; d < 4; d++) {
                int dr = DX[d];
                int dc = DY[d];
                int nr = r + dr;
                int nc = c + dc;

                while (isValid(grid, nr, nc) && grid[nr][nc] == SHAPE_CHAR) {
                    used[nr][nc] = true;
                    nr += dr;
                    nc += dc;
                }
            }
        }

        /**
         * Checks if coordinates are within grid bounds.
         */
        private boolean isValid(char[][] grid, int r, int c) {
            return r >= 0 && r < grid.length && c >= 0 && c < grid[0].length;
        }
    }

    /**
     * FastScanner for efficient input reading in competitive programming contexts.
     */
    static class FastScanner {
        private final InputStream stream;
        private final byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;

        public FastScanner(InputStream stream) {
            this.stream = stream;
        }

        public int read() {
            if (numChars == -1) {
                throw new InputMismatchException();
            }
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0) {
                    return -1;
                }
            }
            return buf[curChar++];
        }

        public int nextInt() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                res *= 10;
                res += c - '0';
                c = read();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public boolean isSpaceChar(int c) {
            return isWhitespace(c);
        }

        public static boolean isWhitespace(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        public char nextCharacter() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            return (char) c;
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

/**
 * Validates whether a given grid contains exactly one valid cross shape.
 * A valid cross consists of a center cell surrounded by '*' in all 4 directions,
 * with horizontal and vertical arms that are contiguous segments of '*'s.
 */
public class CrossPatternValidator {

    public static void main(String[] args) {
        // Resource management handled via try-with-resources for automatic cleanup
        try (FastScanner sc = new FastScanner(System.in);
             PrintWriter out = new PrintWriter(System.out)) {

            int h = sc.nextInt();
            int w = sc.nextInt();
            boolean[][] grid = new boolean[h][w];

            // Parse the input grid
            for (int i = 0; i < h; i++) {
                String row = sc.next();
                for (int j = 0; j < w; j++) {
                    grid[i][j] = row.charAt(j) == '*';
                }
            }

            int centerR = -1;
            int centerC = -1;

            // 1. Locate the potential center of the cross
            for (int i = 1; i < h - 1; i++) {
                for (int j = 1; j < w - 1; j++) {
                    if (grid[i][j] &&
                        grid[i - 1][j] && grid[i + 1][j] &&
                        grid[i][j - 1] && grid[i][j + 1]) {
                        centerR = i;
                        centerC = j;
                        break;
                    }
                }
                if (centerR != -1) break;
            }

            if (centerR == -1) {
                out.println("NO");
            } else {
                // 2. Validate the complete cross structure
                boolean isValid = validateCross(grid, centerR, centerC, h, w);
                out.println(isValid ? "YES" : "NO");
            }
        } catch (IOException e) {
            throw new RuntimeException("Input/Output error occurred", e);
        }
    }

    /**
     * Validates that the grid contains exactly one valid cross shape centered at (r, c).
     * Conditions:
     * 1. All '*' cells must lie exactly on the center row or center column.
     * 2. The horizontal arm must form a single contiguous segment.
     * 3. The vertical arm must form a single contiguous segment.
     */
    private static boolean validateCross(boolean[][] grid, int r, int c, int h, int w) {
        // Condition 1: Ensure no stray '*' exists off the cross axes
        for (int i = 0; i < h; i++) {
            for (int j = 0; j < w; j++) {
                if (grid[i][j] && i != r && j != c) {
                    return false;
                }
            }
        }

        // Condition 2 & 3: Verify contiguity of horizontal and vertical arms
        if (!isContiguous(grid, r, 0, w, true)) {
            return false;
        }
        if (!isContiguous(grid, c, 0, h, false)) {
            return false;
        }

        return true;
    }

    /**
     * Checks if the specified row or column contains exactly one contiguous segment of '*'s.
     *
     * @param grid       The grid to check
     * @param fixedIndex The fixed row index (for horizontal) or column index (for vertical)
     * @param start      Start index of the segment check
     * @param end        End index of the segment check
     * @param isRow      true if checking a row, false if checking a column
     * @return true if the segment is contiguous, false otherwise
     */
    private static boolean isContiguous(boolean[][] grid, int fixedIndex, int start, int end, boolean isRow) {
        boolean started = false;
        for (int idx = start; idx < end; idx++) {
            boolean isPresent = isRow ? grid[fixedIndex][idx] : grid[idx][fixedIndex];
            if (isPresent) {
                if (started) {
                    continue; // Continuation of the segment
                }
                started = true; // First '*' found
            } else if (started) {
                return false; // Gap detected after the segment started
            }
        }
        return true;
    }

    /**
     * Lightweight, efficient input reader optimized for competitive programming.
     * Replaces the original verbose Scanner with a focused, memory-efficient implementation.
     */
    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        public String next() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) return null;
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

/**
 * Analyzes a 2D grid of characters to determine if it satisfies specific
 * connectivity and neighbor-counting criteria.
 * 
 * Refactoring highlights:
 * - Removed global mutable state by encapsulating data in instance fields.
 * - Renamed variables/methods to be descriptive and follow Java conventions.
 * - Fixed a logical bug in the original neighbor-counting logic (isCenter).
 * - Improved input handling and error resilience.
 * - Added JavaDoc and clear separation of concerns.
 */
public class StarGridAnalyzer {

    private static final int[] DX = {1, 0, -1, 0};
    private static final int[] DY = {0, 1, 0, -1};
    private static final char STAR = '*';
    private static final char EMPTY = '.';

    private char[][] grid;
    private boolean[][] visited;
    private int componentCount = 0;
    private int fourNeighborCount = 0;
    private int highNeighborCount = 0;

    public static void main(String[] args) {
        StarGridAnalyzer analyzer = new StarGridAnalyzer();
        FastReader reader = new FastReader();
        try {
            analyzer.solve(reader);
        } catch (IOException e) {
            System.err.println("Error reading input: " + e.getMessage());
        }
    }

    public void solve(FastReader reader) throws IOException {
        int n = reader.nextInt();
        int m = reader.nextInt();

        grid = new char[n][m];
        visited = new boolean[n][m];

        for (int i = 0; i < n; i++) {
            String line = reader.next();
            if (line != null && line.length() >= m) {
                for (int j = 0; j < m; j++) {
                    grid[i][j] = line.charAt(j);
                }
            }
        }

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (!visited[i][j] && grid[i][j] == STAR) {
                    dfs(i, j, n, m);
                    componentCount++;
                }
            }
        }

        if (componentCount == 1 && fourNeighborCount == 1 && highNeighborCount == 1) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }
    }

    private void dfs(int x, int y, int n, int m) {
        visited[x][y] = true;
        int adjCount = countAdjacentStars(x, y, n, m);

        if (adjCount == 4) {
            fourNeighborCount++;
        }
        if (adjCount > 1) {
            highNeighborCount++;
        }

        for (int i = 0; i < 4; i++) {
            int nx = x + DX[i];
            int ny = y + DY[i];
            if (isValid(nx, ny, n, m)) {
                dfs(nx, ny, n, m);
            }
        }
    }

    private boolean isValid(int x, int y, int n, int m) {
        return x >= 0 && x < n && y >= 0 && y < m
                && grid[x][y] == STAR
                && !visited[x][y];
    }

    /**
     * Counts the number of adjacent '*' cells in the four cardinal directions.
     * Replaces the original isCenter method which contained flawed conditional
     * guards (u==0, l==0) that incorrectly skipped neighbor checks.
     */
    private int countAdjacentStars(int x, int y, int n, int m) {
        int count = 0;
        for (int i = 0; i < 4; i++) {
            int nx = x + DX[i];
            int ny = y + DY[i];
            if (nx >= 0 && nx < n && ny >= 0 && ny < m && grid[nx][ny] == STAR) {
                count++;
            }
        }
        return count;
    }

    /**
     * Utility class for fast input reading, commonly used in competitive programming.
     */
    static class FastReader {
        private BufferedReader br;
        private StringTokenizer st;

        public FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input line", e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            String s = next();
            return s == null ? 0 : Integer.parseInt(s);
        }

        long nextLong() {
            String s = next();
            return s == null ? 0L : Long.parseLong(s);
        }

        double nextDouble() {
            String s = next();
            return s == null ? 0.0 : Double.parseDouble(s);
        }

        String nextLine() {
            String str = "";
            try {
                str = br.readLine();
            } catch (IOException e) {
                throw new RuntimeException("Failed to read input line", e);
            }
            return str;
        }
    }
}

import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        // Read dimensions
        if (!scanner.hasNextInt()) {
            return;
        }
        int rows = scanner.nextInt();
        int cols = scanner.nextInt();
        scanner.nextLine(); // Consume the newline character after the width

        // Read the grid
        char[][] grid = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            String line = scanner.nextLine();
            for (int j = 0; j < cols; j++) {
                // Ensure we don't access out of bounds if line is shorter than expected
                if (j < line.length()) {
                    grid[i][j] = line.charAt(j);
                } else {
                    grid[i][j] = '.'; // Default fill if line is short
                }
            }
        }

        // Process the grid and determine the result
        boolean result = solve(grid, rows, cols);

        // Output the result
        System.out.println(result ? "YES" : "NO");
    }

    /**
     * Solves the problem based on the logic derived from the original code.
     * It looks for a "cross center" (a star with 4 star neighbors).
     * If found, it clears the cross shape and checks if the grid is empty.
     * Note: The original code stops checking after the first valid cross is found 
     * due to the 'ran' flag logic.
     */
    private static boolean solve(char[][] grid, int rows, int cols) {
        boolean foundValidCross = false;

        // Iterate through the inner grid (excluding borders)
        // The original code used bounds 1 to h-2 and 1 to w-2 to safely access neighbors.
        searchLoop:
        for (int i = 1; i < rows - 1; i++) {
            for (int j = 1; j < cols - 1; j++) {

                // Original logic: 'ran' flag prevents re-checking logic after first success
                if (!foundValidCross) {
                    if (isCrossCenter(grid, i, j)) {
                        foundValidCross = true;
                        clearCross(grid, i, j, rows, cols);

                        // Break out of loops as subsequent iterations do nothing 
                        // due to the 'ran' flag logic in the original code.
                        break searchLoop;
                    }
                }
            }
        }

        // If no cross was found, the answer remains false (based on original initialization)
        boolean answer = foundValidCross;

        // If a cross was found and cleared, verify if any stars remain in the grid
        if (answer) {
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j] == '*') {
                        answer = false;
                        break;
                    }
                }
                if (!answer) {
                    break;
                }
            }
        }

        return answer;
    }

    /**
     * Checks if the cell at (r, c) is a center of a cross.
     * A center is defined as a '*' with '*' neighbors in all 4 cardinal directions.
     */
    private static boolean isCrossCenter(char[][] grid, int r, int c) {
        // Bounds are guaranteed by the caller (solve method) to be within 1..rows-2
        return grid[r][c] == '*' &&
               grid[r - 1][c] == '*' && // Up
               grid[r + 1][c] == '*' && // Down
               grid[r][c - 1] == '*' && // Left
               grid[r][c + 1] == '*';    // Right
    }

    /**
     * Clears the cross shape centered at (r, c).
     * It removes the center and extends outwards in all 4 directions until a non-'*' is found.
     */
    private static void clearCross(char[][] grid, int r, int c, int rows, int cols) {
        // Clear the center
        grid[r][c] = '.';

        // Clear Downwards
        for (int i = r + 1; i < rows; i++) {
            if (grid[i][c] == '*') {
                grid[i][c] = '.';
            } else {
                break;
            }
        }

        // Clear Upwards
        for (int i = r - 1; i >= 0; i--) {
            if (grid[i][c] == '*') {
                grid[i][c] = '.';
            } else {
                break;
            }
        }

        // Clear Rightwards
        for (int j = c + 1; j < cols; j++) {
            if (grid[r][j] == '*') {
                grid[r][j] = '.';
            } else {
                break;
            }
        }

        // Clear Leftwards
        for (int j = c - 1; j >= 0; j--) {
            if (grid[r][j] == '*') {
                grid[r][j] = '.';
            } else {
                break;
            }
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.util.HashSet;
import java.util.StringTokenizer;

public class StarCrossValidator {

    /**
     * FastScanner for efficient token-based input parsing.
     */
    private static class FastScanner {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastScanner(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input", e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            String token = next();
            return token == null ? 0 : Integer.parseInt(token);
        }
    }

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner(System.in);

        int n = scanner.nextInt();
        int m = scanner.nextInt();

        char[][] grid = new char[n][];
        for (int i = 0; i < n; i++) {
            String row = scanner.next();
            grid[i] = row != null ? row.toCharArray() : new char[0];
        }

        System.out.println(solve(grid, n, m) ? "YES" : "NO");
    }

    /**
     * Validates whether all '*' characters form a single contiguous cross shape.
     */
    private static boolean solve(char[][] grid, int n, int m) {
        int centerRow = -1;
        int centerCol = -1;

        // 1. Locate the intersection point of the cross
        for (int i = 1; i < n - 1; i++) {
            for (int j = 1; j < m - 1; j++) {
                if (grid[i][j] == '*' &&
                    grid[i - 1][j] == '*' &&
                    grid[i + 1][j] == '*' &&
                    grid[i][j - 1] == '*' &&
                    grid[i][j + 1] == '*') {
                    centerRow = i;
                    centerCol = j;
                    break;
                }
            }
            if (centerRow != -1) break;
        }

        if (centerRow == -1) {
            return false;
        }

        HashSet<Long> crossPoints = new HashSet<>();

        // 2. Validate and collect horizontal segment
        if (!isContiguousSegment(grid, centerRow, true, m)) {
            return false;
        }
        for (int j = 0; j < m; j++) {
            if (grid[centerRow][j] == '*') {
                crossPoints.add(encode(centerRow, j));
            }
        }

        // 3. Validate and collect vertical segment
        if (!isContiguousSegment(grid, centerCol, false, n)) {
            return false;
        }
        for (int i = 0; i < n; i++) {
            if (grid[i][centerCol] == '*') {
                crossPoints.add(encode(i, centerCol));
            }
        }

        // 4. Ensure all stars in the grid belong to the cross
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == '*') {
                    if (!crossPoints.contains(encode(i, j))) {
                        return false;
                    }
                }
            }
        }

        return true;
    }

    /**
     * Checks if a row or column contains exactly one contiguous block of '*'.
     */
    private static boolean isContiguousSegment(char[][] grid, int fixedIdx, boolean isRow, int length) {
        boolean foundStar = false;
        boolean seenGap = false;

        for (int i = 0; i < length; i++) {
            char c = isRow ? grid[fixedIdx][i] : grid[i][fixedIdx];
            if (c == '*') {
                if (seenGap) return false; // Star after a gap indicates multiple segments
                foundStar = true;
            } else {
                if (foundStar) seenGap = true;
            }
        }
        return foundStar; // Must contain at least one star
    }

    /**
     * Encodes two coordinates into a single long for efficient HashSet storage.
     */
    private static long encode(int row, int col) {
        return ((long) row << 32) | (col & 0xFFFFFFFFL);
    }
}

import java.util.Scanner;

public class StarCrossFinder {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            return;
        }

        int rows = scanner.nextInt();
        int cols = scanner.nextInt();

        String[] grid = new String[rows];
        for (int i = 0; i < rows; i++) {
            grid[i] = scanner.next();
        }

        int totalStars = countTotalStars(grid);
        if (hasValidCross(grid, totalStars)) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }
    }

    /**
     * Counts the total number of '*' characters in the grid.
     */
    private static int countTotalStars(String[] grid) {
        int count = 0;
        for (String row : grid) {
            for (int i = 0; i < row.length(); i++) {
                if (row.charAt(i) == '*') {
                    count++;
                }
            }
        }
        return count;
    }

    /**
     * Checks if there exists a center '*' that forms a complete cross
     * covering all '*' characters in the grid.
     */
    private static boolean hasValidCross(String[] grid, int totalStars) {
        int rows = grid.length;
        if (rows == 0) {
            return false;
        }
        int cols = grid[0].length();

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r].charAt(c) != '*') {
                    continue;
                }

                int left = countConsecutiveStars(grid, r, c, 0, -1);
                int right = countConsecutiveStars(grid, r, c, 0, 1);
                int up = countConsecutiveStars(grid, r, c, -1, 0);
                int down = countConsecutiveStars(grid, r, c, 1, 0);

                // A valid cross must have arms in all 4 directions and 
                // the total stars in the cross must equal all stars in the grid.
                if (left > 0 && right > 0 && up > 0 && down > 0 &&
                    (1 + left + right + up + down) == totalStars) {
                    return true;
                }
            }
        }
        return false;
    }

    /**
     * Counts consecutive '*' characters starting from (startRow, startCol)
     * in the direction specified by (dRow, dCol).
     */
    private static int countConsecutiveStars(String[] grid, int startRow, int startCol, int dRow, int dCol) {
        int count = 0;
        int r = startRow + dRow;
        int c = startCol + dCol;

        while (r >= 0 && r < grid.length && c >= 0 && c < grid[0].length() && grid[r].charAt(c) == '*') {
            count++;
            r += dRow;
            c += dCol;
        }
        return count;
    }
}

import java.io.IOException;
import java.io.InputStream;
import java.io.OutputStream;
import java.io.PrintWriter;
import java.util.InputMismatchException;

/**
 * Main entry point for the grid cross-checking problem.
 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        FastScanner in = new FastScanner(inputStream);
        PrintWriter out = new PrintWriter(outputStream);

        GridCrossChecker solver = new GridCrossChecker();
        solver.solve(in, out);

        out.close();
    }

    /**
     * Solves the problem: determines if all '*' characters in the grid form a valid cross.
     * A valid cross exists if there is a center '*' such that the contiguous '*' arms
     * in all four cardinal directions (up, down, left, right) plus the center itself
     * account for every '*' in the grid.
     */
    static class GridCrossChecker {
        public void solve(FastScanner in, PrintWriter out) {
            int height = in.nextInt();
            int width = in.nextInt();
            String[] grid = in.nextStringArray(height);

            int totalStars = countStars(grid);
            boolean foundCross = false;

            for (int r = 0; r < height; r++) {
                for (int c = 0; c < width; c++) {
                    if (grid[r].charAt(c) != '*') {
                        continue;
                    }

                    int up = countContiguous(grid, r, c, -1, 0);
                    int down = countContiguous(grid, r, c, 1, 0);
                    int left = countContiguous(grid, r, c, 0, -1);
                    int right = countContiguous(grid, r, c, 0, 1);

                    if (up + down + left + right + 1 == totalStars) {
                        foundCross = true;
                        break;
                    }
                }
                if (foundCross) {
                    break;
                }
            }

            out.println(foundCross ? "YES" : "NO");
        }

        /**
         * Counts the total number of '*' characters in the grid.
         */
        private int countStars(String[] grid) {
            int count = 0;
            for (String row : grid) {
                for (int i = 0; i < row.length(); i++) {
                    if (row.charAt(i) == '*') {
                        count++;
                    }
                }
            }
            return count;
        }

        /**
         * Counts contiguous '*' characters starting from (r, c) in a given direction.
         *
         * @param dr Row direction (-1 for up, 1 for down, 0 for horizontal)
         * @param dc Column direction (-1 for left, 1 for right, 0 for vertical)
         */
        private int countContiguous(String[] grid, int r, int c, int dr, int dc) {
            int count = 0;
            int currR = r + dr;
            int currC = c + dc;
            int rows = grid.length;
            int cols = grid.length > 0 ? grid[0].length() : 0;

            while (currR >= 0 && currR < rows && currC >= 0 && currC < cols 
                   && grid[currR].charAt(currC) == '*') {
                count++;
                currR += dr;
                currC += dc;
            }
            return count;
        }
    }

    /**
     * Fast input reader for competitive programming environments.
     * Optimized for reading integers and strings from an InputStream.
     */
    static class FastScanner {
        private final InputStream stream;
        private final byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;

        public FastScanner(InputStream stream) {
            this.stream = stream;
        }

        private int read() {
            if (numChars == -1) {
                throw new InputMismatchException();
            }
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0) {
                    return -1;
                }
            }
            return buf[curChar++];
        }

        private boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        public int nextInt() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                res *= 10;
                res += c - '0';
                c = read();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public String next() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            StringBuilder res = new StringBuilder();
            do {
                res.appendCodePoint(c);
                c = read();
            } while (!isSpaceChar(c));
            return res.toString();
        }

        public String[] nextStringArray(int size) {
            String[] array = new String[size];
            for (int i = 0; i < size; i++) {
                array[i] = next();
            }
            return array;
        }
    }
}

import java.util.Scanner;

public class Solution {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        // Read grid dimensions
        if (!scanner.hasNextInt()) {
            return;
        }
        int rows = scanner.nextInt();
        int cols = scanner.nextInt();

        char[][] grid = new char[rows][cols];
        int totalAsterisks = 0;

        // Read grid input and count total asterisks
        for (int i = 0; i < rows; i++) {
            String line = scanner.next();
            for (int j = 0; j < cols; j++) {
                // Safety check to prevent IndexOutOfBounds if input line is short
                if (j < line.length()) {
                    grid[i][j] = line.charAt(j);
                    if (grid[i][j] == '*') {
                        totalAsterisks++;
                    }
                }
            }
        }

        // Variables to store the position of the valid center
        int centerRow = -1;
        int centerCol = -1;
        boolean multipleCentersFound = false;

        // Iterate through the inner cells (excluding borders) to find a center
        // A valid center must have asterisks in all 4 cardinal directions (Up, Down, Left, Right)
        for (int i = 1; i < rows - 1; i++) {
            for (int j = 1; j < cols - 1; j++) {
                if (isAsterisk(grid, i - 1, j) && // Up
                    isAsterisk(grid, i + 1, j) && // Down
                    isAsterisk(grid, i, j - 1) && // Left
                    isAsterisk(grid, i, j + 1)) { // Right

                    if (centerRow == -1) {
                        // Found the first valid center
                        centerRow = i;
                        centerCol = j;
                    } else {
                        // Found a second valid center, which invalidates the configuration
                        multipleCentersFound = true;
                        break;
                    }
                }
            }
            if (multipleCentersFound) {
                break;
            }
        }

        // Validation and Output Logic
        if (multipleCentersFound || centerRow == -1) {
            System.out.println("NO");
        } else {
            // Calculate the number of asterisks connected to the center in a cross shape
            int connectedAsterisks = 0;

            // Check Up (including the center cell itself)
            connectedAsterisks += countContiguousAsterisks(grid, centerRow, centerCol, -1, 0);

            // Check Down (starting from the cell below the center)
            connectedAsterisks += countContiguousAsterisks(grid, centerRow + 1, centerCol, 1, 0);

            // Check Left (starting from the cell to the left of the center)
            connectedAsterisks += countContiguousAsterisks(grid, centerRow, centerCol - 1, 0, -1);

            // Check Right (starting from the cell to the right of the center)
            connectedAsterisks += countContiguousAsterisks(grid, centerRow, centerCol + 1, 0, 1);

            // If the total number of asterisks in the grid equals the number of asterisks 
            // in the cross shape, then all asterisks are part of the valid configuration.
            if (totalAsterisks == connectedAsterisks) {
                System.out.println("YES");
            } else {
                System.out.println("NO");
            }
        }

        scanner.close();
    }

    /**
     * Helper method to safely check if a cell contains an asterisk.
     * Returns false if the coordinates are out of bounds.
     */
    private static boolean isAsterisk(char[][] grid, int r, int c) {
        if (r < 0 || r >= grid.length || c < 0 || c >= grid[0].length) {
            return false;
        }
        return grid[r][c] == '*';
    }

    /**
     * Helper method to count contiguous asterisks starting from (r, c)
     * in a specific direction defined by (dr, dc).
     * Stops counting at the first non-asterisk cell or boundary.
     */
    private static int countContiguousAsterisks(char[][] grid, int r, int c, int dr, int dc) {
        int count = 0;
        while (r >= 0 && r < grid.length && c >= 0 && c < grid[0].length && grid[r][c] == '*') {
            count++;
            r += dr;
            c += dc;
        }
        return count;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

/**
 * Validates whether a given grid contains exactly one cross pattern and no other '*' characters.
 * A valid cross center is a '*' not on the border that has '*' in all four adjacent directions.
 * The cross arms are removed, and the grid is checked for any remaining '*' characters.
 */
public class GridCrossChecker {

    private static final FastReader reader = new FastReader();

    public static void main(String[] args) {
        int n = reader.nextInt();
        int m = reader.nextInt();

        char[][] grid = new char[n][m];
        for (int i = 0; i < n; i++) {
            grid[i] = reader.next().toCharArray();
        }

        int centerRow = -1;
        int centerCol = -1;

        // Locate the cross center
        for (int i = 1; i < n - 1; i++) {
            for (int j = 1; j < m - 1; j++) {
                if (isCrossCenter(grid, i, j)) {
                    centerRow = i;
                    centerCol = j;
                }
            }
        }

        if (centerRow == -1) {
            System.out.println("NO");
            return;
        }

        // Remove the identified cross
        removeCross(grid, centerRow, centerCol, n, m);

        // Count remaining '*' characters
        int remainingStars = countRemainingStars(grid, n, m);

        System.out.println(remainingStars <= 1 ? "YES" : "NO");
    }

    /**
     * Checks if the cell at (row, col) is a valid cross center.
     */
    private static boolean isCrossCenter(char[][] grid, int row, int col) {
        return grid[row][col] == '*' &&
               grid[row - 1][col] == '*' && grid[row + 1][col] == '*' &&
               grid[row][col - 1] == '*' && grid[row][col + 1] == '*';
    }

    /**
     * Removes the vertical and horizontal arms of the cross centered at (centerRow, centerCol).
     */
    private static void removeCross(char[][] grid, int centerRow, int centerCol, int rows, int cols) {
        // Clear vertical arm upwards
        for (int i = centerRow - 1; i >= 0; i--) {
            if (grid[i][centerCol] != '*') break;
            grid[i][centerCol] = '.';
        }
        // Clear vertical arm downwards
        for (int i = centerRow + 1; i < rows; i++) {
            if (grid[i][centerCol] != '*') break;
            grid[i][centerCol] = '.';
        }

        // Clear horizontal arm leftwards
        for (int j = centerCol - 1; j >= 0; j--) {
            if (grid[centerRow][j] != '*') break;
            grid[centerRow][j] = '.';
        }
        // Clear horizontal arm rightwards
        for (int j = centerCol + 1; j < cols; j++) {
            if (grid[centerRow][j] != '*') break;
            grid[centerRow][j] = '.';
        }
    }

    /**
     * Counts the number of '*' characters remaining in the grid.
     */
    private static int countRemainingStars(char[][] grid, int rows, int cols) {
        int count = 0;
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == '*') {
                    count++;
                }
            }
        }
        return count;
    }

    /**
     * Fast I/O helper class for competitive programming.
     */
    static class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        long nextLong() {
            return Long.parseLong(next());
        }

        double nextDouble() {
            return Double.parseDouble(next());
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

public class Main {
    public static void main(String[] args) {
        FastReader reader = new FastReader();
        int height = reader.nextInt();
        int width = reader.nextInt();

        boolean[][] grid = readGrid(reader, height, width);

        // A cross requires at least a 3x3 area
        if (height < 3 || width < 3) {
            System.out.println("NO");
            return;
        }

        int[] cross = findCross(grid, height, width);
        if (cross == null) {
            System.out.println("NO");
            return;
        }

        // Remove the identified cross
        removeCross(grid, cross[0], cross[1]);

        // If any stars remain after removal, output NO; otherwise YES
        System.out.println(hasStars(grid) ? "NO" : "YES");
    }

    /**
     * Reads the grid from input and converts '*' characters to true, others to false.
     */
    private static boolean[][] readGrid(FastReader reader, int height, int width) {
        boolean[][] grid = new boolean[height][width];
        for (int i = 0; i < height; i++) {
            String row = reader.next();
            for (int j = 0; j < width; j++) {
                grid[i][j] = row.charAt(j) == '*';
            }
        }
        return grid;
    }

    /**
     * Searches for a cross pattern (center + 4 orthogonal neighbors).
     * Returns coordinates {row, col} if found, otherwise null.
     */
    private static int[] findCross(boolean[][] grid, int height, int width) {
        for (int i = 1; i < height - 1; i++) {
            for (int j = 1; j < width - 1; j++) {
                if (grid[i][j] && grid[i - 1][j] && grid[i + 1][j] &&
                    grid[i][j - 1] && grid[i][j + 1]) {
                    return new int[]{i, j};
                }
            }
        }
        return null;
    }

    /**
     * Clears all cells belonging to a cross at the given center coordinates.
     */
    private static void removeCross(boolean[][] grid, int row, int col) {
        grid[row][col] = false;
        grid[row - 1][col] = false;
        grid[row + 1][col] = false;
        grid[row][col - 1] = false;
        grid[row][col + 1] = false;
    }

    /**
     * Checks if any star remains in the grid.
     */
    private static boolean hasStars(boolean[][] grid) {
        for (boolean[] row : grid) {
            for (boolean cell : row) {
                if (cell) return true;
            }
        }
        return false;
    }

    /**
     * Optimized fast I/O reader for competitive programming environments.
     */
    static class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        public String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input", e);
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            String token = next();
            return token == null ? 0 : Integer.parseInt(token);
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

public class GridCrossValidator {

    public static void main(String[] args) {
        FastScanner sc = new FastScanner(System.in);
        int rows = sc.nextInt();
        int cols = sc.nextInt();

        char[][] grid = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            grid[i] = sc.next().toCharArray();
        }

        int centerR = -1;
        int centerC = -1;
        int validCentersCount = 0;

        // 1. Find exactly one valid cross center
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '*' && isValidCenter(grid, r, c, rows, cols)) {
                    validCentersCount++;
                    centerR = r;
                    centerC = c;
                }
            }
        }

        if (validCentersCount != 1) {
            System.out.println("NO");
            return;
        }

        // 2. Mark all cells belonging to the cross shape
        boolean[][] marked = new boolean[rows][cols];
        markCross(grid, marked, centerR, centerC, rows, cols);

        // 3. Verify that every '*' in the grid is part of the marked cross
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '*' && !marked[r][c]) {
                    System.out.println("NO");
                    return;
                }
            }
        }

        System.out.println("YES");
    }

    /**
     * Checks if coordinates are within grid boundaries.
     */
    private static boolean isValid(int r, int c, int rows, int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /**
     * Validates if a cell can be the center of a cross:
     * - All 4 orthogonal neighbors must be '*'
     * - All 4 diagonal neighbors must NOT be '*'
     */
    private static boolean isValidCenter(char[][] grid, int r, int c, int rows, int cols) {
        // Check orthogonal neighbors
        int[] dr = {-1, 1, 0, 0};
        int[] dc = {0, 0, -1, 1};
        for (int k = 0; k < 4; k++) {
            int nr = r + dr[k];
            int nc = c + dc[k];
            if (!isValid(nr, nc, rows, cols) || grid[nr][nc] != '*') {
                return false;
            }
        }

        // Check diagonal neighbors (must NOT be '*')
        int[] ddr = {-1, -1, 1, 1};
        int[] ddc = {-1, 1, -1, 1};
        for (int k = 0; k < 4; k++) {
            int nr = r + ddr[k];
            int nc = c + ddc[k];
            if (isValid(nr, nc, rows, cols) && grid[nr][nc] == '*') {
                return false;
            }
        }

        return true;
    }

    /**
     * Marks the center and all connected '*' cells in the 4 cardinal directions.
     * Stops marking when a non-'*' cell or boundary is encountered.
     */
    private static void markCross(char[][] grid, boolean[][] marked, int centerR, int centerC, int rows, int cols) {
        // Mark the center itself
        marked[centerR][centerC] = true;

        // Extend in all 4 directions
        int[] dr = {-1, 1, 0, 0};
        int[] dc = {0, 0, -1, 1};
        for (int k = 0; k < 4; k++) {
            int r = centerR + dr[k];
            int c = centerC + dc[k];
            while (isValid(r, c, rows, cols) && grid[r][c] == '*') {
                marked[r][c] = true;
                r += dr[k];
                c += dc[k];
            }
        }
    }

    /**
     * Lightweight fast I/O helper to replace verbose boilerplate.
     */
    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner(java.io.InputStream stream) {
            br = new BufferedReader(new InputStreamReader(stream), 32768);
        }

        public String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.util.Scanner;

/**
 * A program to determine if a grid contains a "cross" pattern of stars (*)
 * that accounts for all stars in the grid.
 * 
 * A valid cross is defined as a center star with continuous arms of stars
 * extending in all four cardinal directions (up, down, left, right).
 * The cross must have a minimum size of 5 stars (center + 1 in each direction).
 */
public class CrossPatternChecker {

    // Minimum dimension required to form a valid cross center
    private static final int MIN_DIMENSION = 3;

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        // Read grid dimensions
        if (!scanner.hasNextInt()) {
            return;
        }
        int rows = scanner.nextInt();
        int cols = scanner.nextInt();

        // Read the grid content
        String[] grid = new String[rows];
        for (int i = 0; i < rows; i++) {
            grid[i] = scanner.next();
        }

        // Close scanner as it is no longer needed
        scanner.close();

        // Validate grid dimensions
        if (rows < MIN_DIMENSION || cols < MIN_DIMENSION) {
            System.out.println("NO");
            return;
        }

        // Check if a valid cross pattern exists
        if (hasValidCrossPattern(grid, rows, cols)) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }
    }

    /**
     * Determines if the grid contains a cross pattern that includes all stars.
     *
     * @param grid   The 2D grid represented as an array of strings.
     * @param rows   Number of rows.
     * @param cols   Number of columns.
     * @return true if a valid cross covering all stars exists, false otherwise.
     */
    private static boolean hasValidCrossPattern(String[] grid, int rows, int cols) {
        int totalStars = countTotalStars(grid, rows, cols);

        // If there are no stars, a cross cannot exist (based on logical requirement of stars)
        if (totalStars == 0) {
            return false;
        }

        // Iterate through all possible center positions.
        // A center cannot be on the border (indices 1 to rows-2).
        for (int i = 1; i < rows - 1; i++) {
            for (int j = 1; j < cols - 1; j++) {

                // Check if current cell is a valid center (star + 4 neighbors)
                if (isCenter(grid, i, j)) {
                    int crossSize = calculateCrossSize(grid, i, j, rows, cols);

                    // If the cross size matches the total number of stars in the grid,
                    // it means all stars belong to this cross.
                    if (crossSize == totalStars) {
                        return true;
                    }
                }
            }
        }

        return false;
    }

    /**
     * Counts the total number of '*' characters in the grid.
     */
    private static int countTotalStars(String[] grid, int rows, int cols) {
        int count = 0;
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i].charAt(j) == '*') {
                    count++;
                }
            }
        }
        return count;
    }

    /**
     * Checks if the cell at (r, c) and its 4 immediate neighbors are all stars.
     */
    private static boolean isCenter(String[] grid, int r, int c) {
        return grid[r].charAt(c) == '*' &&
               grid[r - 1].charAt(c) == '*' && // Up
               grid[r + 1].charAt(c) == '*' && // Down
               grid[r].charAt(c - 1) == '*' && // Left
               grid[r].charAt(c + 1) == '*';   // Right
    }

    /**
     * Calculates the total number of stars in the cross shape centered at (r, c).
     * This includes the center and continuous arms extending in all directions.
     */
    private static int calculateCrossSize(String[] grid, int r, int c, int rows, int cols) {
        int crossStars = 0;

        // Count Vertical Arm (Up and Down)
        // Start from center (r) and go Up
        for (int i = r; i >= 0; i--) {
            if (grid[i].charAt(c) == '*') {
                crossStars++;
            } else {
                break;
            }
        }
        // Continue from center + 1 and go Down
        for (int i = r + 1; i < rows; i++) {
            if (grid[i].charAt(c) == '*') {
                crossStars++;
            } else {
                break;
            }
        }

        // Count Horizontal Arm (Left and Right)
        // Note: Center (r,c) is already counted in the vertical pass.
        // We only count neighbors to the left.
        for (int j = c - 1; j >= 0; j--) {
            if (grid[r].charAt(j) == '*') {
                crossStars++;
            } else {
                break;
            }
        }
        // Count neighbors to the right.
        for (int j = c + 1; j < cols; j++) {
            if (grid[r].charAt(j) == '*') {
                crossStars++;
            } else {
                break;
            }
        }

        return crossStars;
    }
}

import java.util.Scanner;

/**
 * Refactored version of B_Plus_from_Picture.
 * 
 * Improvements made:
 * 1. Class Naming: Renamed to PlusShapeChecker for better descriptiveness.
 * 2. Input Handling: Replaced custom FastScanner with standard java.util.Scanner 
 *    for improved readability and maintainability (assuming standard input sizes).
 * 3. Variable Naming: Renamed variables to be more descriptive (e.g., mat -> grid, cnt -> totalStars).
 * 4. Code Structure: Flattened deeply nested if-statements into a single compound condition.
 * 5. Modularity: Extracted the cross-size calculation logic into a helper method.
 * 6. Dead Code Removal: Removed the unused 'sort' method.
 * 7. Comments: Added documentation to explain the algorithm.
 */
public class PlusShapeChecker {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        // Check if input exists to prevent exceptions on empty input
        if (!scanner.hasNextInt()) {
            scanner.close();
            return;
        }

        int n = scanner.nextInt();
        int m = scanner.nextInt();

        boolean[][] grid = new boolean[n][m];
        int totalStars = 0;

        // Read the grid and count total stars
        for (int i = 0; i < n; i++) {
            String row = scanner.next();
            for (int j = 0; j < m; j++) {
                if (row.charAt(j) == '*') {
                    grid[i][j] = true;
                    totalStars++;
                }
            }
        }

        // Optimization: A plus sign requires a center and 4 arms.
        // Minimum size is 5 stars (1 center + 4 arms of length 1).
        // Dimensions must be at least 3x3 to fit this shape.
        if (n < 3 || m < 3 || totalStars < 5) {
            System.out.println("NO");
            scanner.close();
            return;
        }

        // Check if the stars form a valid plus sign
        if (isPlusShape(grid, n, m, totalStars)) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }

        scanner.close();
    }

    /**
     * Determines if the grid contains a valid plus sign shape that includes all stars.
     * 
     * @param grid The boolean matrix representing the picture.
     * @param n    Number of rows.
     * @param m    Number of columns.
     * @param totalStars Total number of '*' characters in the grid.
     * @return true if a valid plus sign exists covering all stars, false otherwise.
     */
    private static boolean isPlusShape(boolean[][] grid, int n, int m, int totalStars) {
        // A plus sign must have a center point where all 4 orthogonal neighbors are stars.
        // We iterate through inner cells (excluding borders) to find a potential center.
        for (int i = 1; i < n - 1; i++) {
            for (int j = 1; j < m - 1; j++) {

                // Check if current cell is a star
                if (grid[i][j]) {
                    // Check if all 4 neighbors are stars.
                    // Flattened the nested if-statements for better readability.
                    if (grid[i - 1][j] && grid[i + 1][j] &&
                        grid[i][j - 1] && grid[i][j + 1]) {

                        // Calculate the size of the cross centered at (i, j)
                        int crossSize = calculateCrossSize(grid, i, j, n, m);

                        // If the calculated cross size equals the total number of stars,
                        // it implies all stars in the grid form this single plus sign.
                        if (crossSize == totalStars) {
                            return true;
                        }
                    }
                }
            }
        }
        return false;
    }

    /**
     * Calculates the number of stars in the cross shape centered at (centerRow, centerCol).
     * Includes the center star itself.
     * 
     * @param grid The boolean matrix.
     * @param centerRow The row index of the center.
     * @param centerCol The column index of the center.
     * @param n Number of rows.
     * @param m Number of columns.
     * @return The total count of stars in the cross.
     */
    private static int calculateCrossSize(boolean[][] grid, int centerRow, int centerCol, int n, int m) {
        int size = 1; // Start with the center star

        // Expand Up
        int r = centerRow - 1;
        while (r >= 0 && grid[r][centerCol]) {
            size++;
            r--;
        }

        // Expand Down
        r = centerRow + 1;
        while (r < n && grid[r][centerCol]) {
            size++;
            r++;
        }

        // Expand Left
        int c = centerCol - 1;
        while (c >= 0 && grid[centerRow][c]) {
            size++;
            c--;
        }

        // Expand Right
        c = centerCol + 1;
        while (c < m && grid[centerRow][c]) {
            size++;
            c++;
        }

        return size;
    }
}

import java.util.Scanner;

/**
 * A program to validate if a grid contains a specific cross pattern of stars.
 * A valid cross consists of a center point with arms of stars extending 
 * horizontally and vertically, with no other stars present in the grid.
 * 
 * Refactored for:
 * - Encapsulation (removed static state)
 * - Readability (descriptive variable and method names)
 * - Efficiency (removed regex and string manipulation overhead)
 * - Robustness (boundary checks and input validation)
 */
public class CrossPatternChecker {

    private static final char STAR_CHAR = '*';

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        // Read grid dimensions
        if (!scanner.hasNextInt()) {
            return;
        }
        int numRows = scanner.nextInt();
        int numCols = scanner.nextInt();

        // Initialize grid
        char[][] grid = new char[numRows][numCols];

        // Read grid data
        for (int i = 0; i < numRows; i++) {
            if (scanner.hasNext()) {
                String rowString = scanner.next();
                // Fill the row, handling cases where input string might be shorter than expected
                for (int j = 0; j < numCols && j < rowString.length(); j++) {
                    grid[i][j] = rowString.charAt(j);
                }
            }
        }

        // Process and print result
        solve(grid);

        scanner.close();
    }

    /**
     * Orchestrates the validation logic for the grid.
     */
    private static void solve(char[][] grid) {
        int rows = grid.length;
        if (rows == 0) {
            System.out.println("NO");
            return;
        }
        int cols = grid[0].length;

        // Step 1: Locate the center of the potential cross
        int centerRow = -1;
        int centerCol = -1;
        int centerCount = 0;

        // A center must have neighbors in all 4 directions, so it cannot be on the border.
        // Valid range is [1, rows-2] and [1, cols-2].
        for (int i = 1; i < rows - 1; i++) {
            for (int j = 1; j < cols - 1; j++) {
                if (isCenter(grid, i, j)) {
                    centerCount++;
                    centerRow = i;
                    centerCol = j;
                }
            }
        }

        // There must be exactly one center
        if (centerCount != 1) {
            System.out.println("NO");
            return;
        }

        // Step 2: Validate the cross pattern
        if (isValidCross(grid, centerRow, centerCol)) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }
    }

    /**
     * Checks if the cell at (row, col) is a valid center point.
     * A valid center has stars in all 4 cardinal directions (up, down, left, right).
     */
    private static boolean isCenter(char[][] grid, int row, int col) {
        return grid[row][col + 1] == STAR_CHAR &&
               grid[row][col - 1] == STAR_CHAR &&
               grid[row - 1][col] == STAR_CHAR &&
               grid[row + 1][col] == STAR_CHAR;
    }

    /**
     * Validates that the grid forms a perfect cross shape centered at (centerRow, centerCol).
     * Conditions:
     * 1. The center cell must be a star.
     * 2. The entire row containing the center must consist of stars.
     * 3. The entire column containing the center must consist of stars.
     * 4. No stars should exist outside of this cross shape.
     */
    private static boolean isValidCross(char[][] grid, int centerRow, int centerCol) {
        int rows = grid.length;
        int cols = grid[0].length;

        // Condition 1: Center must be a star
        if (grid[centerRow][centerCol] != STAR_CHAR) {
            return false;
        }

        // Condition 2: Horizontal arm must be all stars
        for (int j = 0; j < cols; j++) {
            if (grid[centerRow][j] != STAR_CHAR) {
                return false;
            }
        }

        // Condition 3: Vertical arm must be all stars
        for (int i = 0; i < rows; i++) {
            if (grid[i][centerCol] != STAR_CHAR) {
                return false;
            }
        }

        // Condition 4: No stray stars outside the cross
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                // Check if the current cell is outside the cross arms
                // A cell is part of the cross if it is in the center row OR center column
                if (i != centerRow && j != centerCol) {
                    if (grid[i][j] == STAR_CHAR) {
                        return false;
                    }
                }
            }
        }

        return true;
    }
}

import java.io.BufferedReader;
import java.io.BufferedOutputStream;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

public class Round566Div2B {

    public static void main(String[] args) {
        FastReader reader = new FastReader();
        PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out));

        try {
            int h = reader.nextInt();
            int w = reader.nextInt();

            // A valid cross requires at least a 3x3 grid
            if (h < 3 || w < 3) {
                out.println("NO");
                out.flush();
                return;
            }

            char[][] grid = new char[h][];
            int totalStars = 0;

            // Read grid and count total stars in a single pass
            for (int i = 0; i < h; i++) {
                String line = reader.next();
                grid[i] = line.toCharArray();
                for (char c : grid[i]) {
                    if (c == '*') {
                        totalStars++;
                    }
                }
            }

            int crossRow = -1;
            int crossCol = -1;

            // Find the center star that has all 4 orthogonal neighbors as '*'
            for (int i = 1; i < h - 1; i++) {
                for (int j = 1; j < w - 1; j++) {
                    if (grid[i][j] == '*' &&
                        grid[i - 1][j] == '*' && grid[i + 1][j] == '*' &&
                        grid[i][j - 1] == '*' && grid[i][j + 1] == '*') {
                        crossRow = i;
                        crossCol = j;
                        break;
                    }
                }
                if (crossRow != -1) {
                    break;
                }
            }

            if (crossRow == -1) {
                out.println("NO");
            } else {
                int rowStars = countStarsInRow(grid, crossRow, w);
                int colStars = countStarsInCol(grid, crossCol, h);

                // The center star is counted in both rowStars and colStars.
                // If all stars lie on this cross, then: rowStars + colStars == totalStars + 1
                if (rowStars + colStars == totalStars + 1) {
                    out.println("YES");
                } else {
                    out.println("NO");
                }
            }
        } catch (Exception e) {
            e.printStackTrace();
        } finally {
            out.flush();
        }
    }

    private static int countStarsInRow(char[][] grid, int row, int width) {
        int count = 0;
        for (int j = 0; j < width; j++) {
            if (grid[row][j] == '*') {
                count++;
            }
        }
        return count;
    }

    private static int countStarsInCol(char[][] grid, int col, int height) {
        int count = 0;
        for (int i = 0; i < height; i++) {
            if (grid[i][col] == '*') {
                count++;
            }
        }
        return count;
    }

    /**
     * Fast input reader for competitive programming / high-throughput scenarios.
     */
    public static class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) {
                        return null;
                    }
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            String s = next();
            return (s == null) ? 0 : Integer.parseInt(s);
        }

        double nextDouble() {
            return Double.parseDouble(next());
        }

        long nextLong() {
            return Long.parseLong(next());
        }

        String nextLine() {
            String str = "";
            try {
                str = br.readLine();
            } catch (IOException e) {
                throw new RuntimeException("Error reading line", e);
            }
            return str;
        }
    }
}

import java.util.Scanner;

/**
 * Refactored version of the Star Grid Solver.
 * 
 * Changes made to improve maintainability and code quality:
 * 1. Class Naming: Renamed 'ProbB' to 'StarGridSolver' for semantic clarity.
 * 2. Data Structure: Changed from String[][] to char[][] for better memory efficiency 
 *    and performance.
 * 3. Input Handling: Cleaned up Scanner usage to properly consume the newline character 
 *    after reading integers.
 * 4. Method Extraction: Broken down the monolithic main method into smaller, 
 *    single-responsibility helper methods (solve, copyGrid, clearContiguousStars, isEmpty).
 * 5. Variable Naming: Replaced single-letter variables (h, w, a, b, x, y, q) with 
 *    descriptive names (height, width, rowIndex, colIndex, etc.).
 * 6. Logic Clarity: Extracted the "clearing" logic into a generic directional function.
 */
public class StarGridSolver {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        // Read grid dimensions
        if (!scanner.hasNextInt()) {
            return;
        }
        int height = scanner.nextInt();
        int width = scanner.nextInt();

        // Consume the newline character left by nextInt()
        scanner.nextLine();

        char[][] grid = new char[height][width];

        // Read the grid content
        for (int i = 0; i < height; i++) {
            String line = scanner.nextLine();
            // Fill the grid row. We assume valid input where line length >= width.
            for (int j = 0; j < width && j < line.length(); j++) {
                grid[i][j] = line.charAt(j);
            }
        }

        // Execute logic and print result
        System.out.println(solve(height, width, grid));

        scanner.close();
    }

    /**
     * Main logic to determine if the grid can be cleared.
     */
    private static String solve(int h, int w, char[][] grid) {
        // Iterate through the inner cells (excluding the border)
        // We look for a '*' that has '*' neighbors in all 4 cardinal directions.
        // Original loop: for(int i = 1; i < h-1; i++)
        for (int i = 1; i < h - 1; i++) {
            // Original loop: for(int j = 1; j < w-1; j++)
            for (int j = 1; j < w - 1; j++) {

                // Check if current cell and neighbors are stars
                if (isStar(grid, i, j) &&
                    isStar(grid, i - 1, j) &&
                    isStar(grid, i + 1, j) &&
                    isStar(grid, i, j - 1) &&
                    isStar(grid, i, j + 1)) {

                    // Create a copy of the grid to simulate the operation
                    char[][] tempGrid = copyGrid(grid);

                    // Remove the center star
                    tempGrid[i][j] = '.';

                    // Clear contiguous stars in all 4 directions from the center
                    // Down
                    clearContiguousStars(tempGrid, i, j, 1, 0);
                    // Up
                    clearContiguousStars(tempGrid, i, j, -1, 0);
                    // Right
                    clearContiguousStars(tempGrid, i, j, 0, 1);
                    // Left
                    clearContiguousStars(tempGrid, i, j, 0, -1);

                    // If the grid is empty of stars, we found a solution
                    if (isEmpty(tempGrid)) {
                        return "YES";
                    }
                }
            }
        }
        return "NO";
    }

    /**
     * Checks if the cell at (r, c) contains a star.
     */
    private static boolean isStar(char[][] grid, int r, int c) {
        return grid[r][c] == '*';
    }

    /**
     * Creates a deep copy of the grid.
     */
    private static char[][] copyGrid(char[][] source) {
        char[][] copy = new char[source.length][source[0].length];
        for (int i = 0; i < source.length; i++) {
            System.arraycopy(source[i], 0, copy[i], 0, source[i].length);
        }
        return copy;
    }

    /**
     * Clears '*' characters in a specific direction until a '.' is encountered.
     * 
     * @param grid The grid to modify
     * @param r Current row
     * @param c Current column
     * @param dr Row direction increment (1, -1, or 0)
     * @param dc Column direction increment (1, -1, or 0)
     */
    private static void clearContiguousStars(char[][] grid, int r, int c, int dr, int dc) {
        int nr = r + dr;
        int nc = c + dc;

        while (nr >= 0 && nr < grid.length && nc >= 0 && nc < grid[0].length) {
            if (grid[nr][nc] == '.') {
                break; // Stop clearing at empty space
            }
            grid[nr][nc] = '.';
            nr += dr;
            nc += dc;
        }
    }

    /**
     * Checks if the grid contains any remaining stars.
     */
    private static boolean isEmpty(char[][] grid) {
        for (char[] row : grid) {
            for (char cell : row) {
                if (cell == '*') {
                    return false;
                }
            }
        }
        return true;
    }
}

import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) {
        InputReader scanner = new InputReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        int rows = scanner.nextInt();
        int cols = scanner.nextInt();
        int[][] grid = parseGrid(rows, cols, scanner);

        boolean crossFoundAndRemoved = findAndRemoveCross(grid);
        boolean isGridCleared = !hasRemainingCells(grid);

        if (crossFoundAndRemoved && isGridCleared) {
            out.println("YES");
        } else {
            out.println("NO");
        }

        out.flush();
        out.close();
    }

    /**
     * Parses the input grid into a 2D integer array.
     * '.' is mapped to 0, and '#' is mapped to 1.
     */
    private static int[][] parseGrid(int rows, int cols, InputReader scanner) {
        int[][] grid = new int[rows][cols];
        for (int i = 0; i < rows; i++) {
            String rowString = scanner.next();
            for (int j = 0; j < cols; j++) {
                grid[i][j] = rowString.charAt(j) == '.' ? 0 : 1;
            }
        }
        return grid;
    }

    /**
     * Searches for a cross pattern (center with 1s in all 4 cardinal directions).
     * If found, removes the cross and returns true. Otherwise, returns false.
     */
    private static boolean findAndRemoveCross(int[][] grid) {
        int rows = grid.length;
        int cols = grid[0].length;

        for (int i = 1; i < rows - 1; i++) {
            for (int j = 1; j < cols - 1; j++) {
                if (grid[i][j] == 1 &&
                    grid[i - 1][j] == 1 &&
                    grid[i + 1][j] == 1 &&
                    grid[i][j - 1] == 1 &&
                    grid[i][j + 1] == 1) {
                    removeCross(grid, i, j);
                    return true;
                }
            }
        }
        return false;
    }

    /**
     * Removes the cross centered at (centerRow, centerCol).
     * Clears contiguous 1s in all four directions until a 0 is encountered.
     */
    private static void removeCross(int[][] grid, int centerRow, int centerCol) {
        // Clear the center
        grid[centerRow][centerCol] = 0;

        // Clear upwards
        for (int i = centerRow - 1; i >= 0; i--) {
            if (grid[i][centerCol] == 1) grid[i][centerCol] = 0;
            else break;
        }
        // Clear downwards
        for (int i = centerRow + 1; i < grid.length; i++) {
            if (grid[i][centerCol] == 1) grid[i][centerCol] = 0;
            else break;
        }
        // Clear leftwards
        for (int j = centerCol - 1; j >= 0; j--) {
            if (grid[centerRow][j] == 1) grid[centerRow][j] = 0;
            else break;
        }
        // Clear rightwards
        for (int j = centerCol + 1; j < grid[0].length; j++) {
            if (grid[centerRow][j] == 1) grid[centerRow][j] = 0;
            else break;
        }
    }

    /**
     * Checks if there are any remaining '#' cells (represented as 1) in the grid.
     */
    private static boolean hasRemainingCells(int[][] grid) {
        for (int[] row : grid) {
            for (int cell : row) {
                if (cell == 1) return true;
            }
        }
        return false;
    }

    /**
     * Fast input reader optimized for competitive programming.
     */
    static class InputReader {
        public BufferedReader reader;
        public StringTokenizer tokenizer;

        public InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }
    }
}

import java.util.Scanner;

/**
 * Refactored version of p1182b.
 * This program checks if a grid contains a valid "plus" or "cross" pattern
 * formed by asterisks ('*').
 */
public class GridPatternValidator {

    /**
     * Helper class to store 2D coordinates.
     */
    private static class Point {
        int row, col;

        Point(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        // Check for valid input
        if (!scanner.hasNextInt()) {
            return;
        }

        int rows = scanner.nextInt();
        int cols = scanner.nextInt();

        char[][] grid = new char[rows][cols];
        Point star1 = null;
        Point star2 = null;

        // Read the grid and identify the first two relevant stars
        for (int i = 0; i < rows; i++) {
            String line = scanner.next();
            grid[i] = line.toCharArray();
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == '*') {
                    if (star1 == null) {
                        star1 = new Point(i, j);
                    } else if (star2 == null) {
                        // Find a second star that is not in the same row or column as the first star.
                        // This heuristic helps identify the defining points of the cross.
                        if (i != star1.row && j != star1.col) {
                            star2 = new Point(i, j);
                        }
                    }
                }
            }
        }

        // If we cannot find two stars that define the cross structure, it's invalid.
        if (star2 == null) {
            System.out.println("NO");
            return;
        }

        // Determine the potential center of the cross.
        // The center is likely the intersection of the row of one star and the column of the other.
        Point center = new Point(star1.row, star2.col);

        // If the calculated intersection is not a star, try the alternative intersection.
        if (grid[center.row][center.col] != '*') {
            center = new Point(star2.row, star1.col);
        }

        // Validate the center point:
        // 1. It must be a star ('*').
        // 2. It must be strictly inside the grid (not on the border) to allow for cross arms.
        if (grid[center.row][center.col] != '*' || 
            center.row <= 0 || center.row >= rows - 1 || 
            center.col <= 0 || center.col >= cols - 1) {
            System.out.println("NO");
            return;
        }

        // Validate the entire grid pattern against the determined center.
        if (isValidCross(grid, center, rows, cols)) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }

        scanner.close();
    }

    /**
     * Validates if the grid forms a valid cross centered at 'center'.
     * A valid cross requires:
     * 1. All stars must lie on the horizontal or vertical axis passing through the center.
     * 2. The path from any star to the center must be continuous (no gaps/dots).
     * 3. The center star must have neighbors in all 4 cardinal directions (implied by connectivity checks).
     */
    private static boolean isValidCross(char[][] grid, Point center, int rows, int cols) {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == '*') {
                    // Constraint 1: Stars must be on the cross axes
                    if (i != center.row && j != center.col) {
                        return false;
                    }

                    // Constraint 2: Connectivity checks
                    // We check neighbors to ensure stars are connected towards the center.

                    // Horizontal Arm Checks
                    if (i == center.row) {
                        // If star is to the left of or at the center, check the right neighbor.
                        if (j <= center.col) {
                            // Bounds check is safe because center is not on the edge, 
                            // but included for defensive programming.
                            if (j + 1 < cols && grid[i][j + 1] == '.') {
                                return false;
                            }
                        }
                        // If star is to the right of or at the center, check the left neighbor.
                        if (j >= center.col) {
                            if (j - 1 >= 0 && grid[i][j - 1] == '.') {
                                return false;
                            }
                        }
                    }

                    // Vertical Arm Checks
                    if (j == center.col) {
                        // If star is above or at the center, check the down neighbor.
                        if (i <= center.row) {
                            if (i + 1 < rows && grid[i + 1][j] == '.') {
                                return false;
                            }
                        }
                        // If star is below or at the center, check the up neighbor.
                        if (i >= center.row) {
                            if (i - 1 >= 0 && grid[i - 1][j] == '.') {
                                return false;
                            }
                        }
                    }
                }
            }
        }
        return true;
    }
}

import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        // Read grid dimensions
        if (!scanner.hasNextInt()) {
            scanner.close();
            return;
        }
        int height = scanner.nextInt();
        int width = scanner.nextInt();

        // Read the grid content
        // We store the grid as a 2D char array for direct access
        char[][] grid = new char[height][width];
        for (int i = 0; i < height; i++) {
            String row = scanner.next();
            grid[i] = row.toCharArray();
        }

        // Variables to store the coordinates of the center '*'
        int centerRow = -1;
        int centerCol = -1;

        // Iterate through the grid to find a '*' that is surrounded by '*' in all 4 directions.
        // We skip the borders (index 0 and height-1/width-1) as they cannot have 4 neighbors.
        boolean foundCenter = false;
        for (int i = 1; i < height - 1; i++) {
            for (int j = 1; j < width - 1; j++) {
                if (grid[i][j] == '*') {
                    // Check neighbors: Up, Down, Left, Right
                    if (grid[i - 1][j] == '*' &&
                        grid[i + 1][j] == '*' &&
                        grid[i][j - 1] == '*' &&
                        grid[i][j + 1] == '*') {

                        centerRow = i;
                        centerCol = j;
                        foundCenter = true;
                        break; // Found the center, exit inner loop
                    }
                }
            }
            if (foundCenter) {
                break; // Exit outer loop
            }
        }

        // If no valid center is found, it's impossible to satisfy the condition
        if (!foundCenter) {
            System.out.println("NO");
            scanner.close();
            return;
        }

        // Create a boolean matrix to keep track of marked '*' characters
        // This replaces the int array 'c' used in the original code
        boolean[][] marked = new boolean[height][width];

        // Mark the cross shape starting from the center
        markCross(grid, marked, centerRow, centerCol);

        // Verify if every '*' in the grid has been marked
        boolean allMarked = true;
        for (int i = 0; i < height; i++) {
            for (int j = 0; j < width; j++) {
                if (grid[i][j] == '*' && !marked[i][j]) {
                    allMarked = false;
                    break;
                }
            }
            if (!allMarked) {
                break;
            }
        }

        // Output the result
        System.out.println(allMarked ? "YES" : "NO");

        scanner.close();
    }

    /**
     * Marks the '*' characters in a cross pattern (Up, Down, Left, Right)
     * starting from the given center coordinates until a '.' is encountered.
     * 
     * @param grid The character grid representing the map
     * @param marked A boolean matrix to track which '*'s have been processed
     * @param r The row index of the center
     * @param c The column index of the center
     */
    private static void markCross(char[][] grid, boolean[][] marked, int r, int c) {
        // Mark the center itself
        marked[r][c] = true;

        // Directions: Up, Down, Left, Right
        // dr corresponds to row changes, dc to column changes
        int[] dr = {-1, 1, 0, 0};
        int[] dc = {0, 0, -1, 1};

        // Iterate through all 4 directions
        for (int d = 0; d < 4; d++) {
            int currR = r + dr[d];
            int currC = c + dc[d];

            // Traverse in the current direction
            while (currR >= 0 && currR < grid.length &&
                   currC >= 0 && currC < grid[0].length) {

                if (grid[currR][currC] == '*') {
                    marked[currR][currC] = true;
                    // Move to the next cell in the direction
                    currR += dr[d];
                    currC += dc[d];
                } else {
                    // If the cell is not '*', it must be '.' (based on problem constraints)
                    // Stop traversing in this direction
                    break;
                }
            }
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

public class Contest {

    /**
     * Entry point for the program. Handles input parsing, grid construction,
     * pattern validation, and output formatting.
     */
    public static void main(String[] args) throws IOException {
        // Use try-with-resources to ensure the stream is properly closed
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(System.in))) {
            String line = reader.readLine();
            if (line == null || line.trim().isEmpty()) {
                return;
            }

            StringTokenizer tokenizer = new StringTokenizer(line);
            int height = Integer.parseInt(tokenizer.nextToken());
            int width = Integer.parseInt(tokenizer.nextToken());

            int[][] grid = new int[height][width];
            for (int i = 0; i < height; i++) {
                String rowLine = reader.readLine();
                if (rowLine != null) {
                    // Fixed bug: split("") creates empty strings at boundaries.
                    // Using charAt() is safer and more efficient.
                    for (int j = 0; j < width && j < rowLine.length(); j++) {
                        grid[i][j] = (rowLine.charAt(j) == '*') ? 1 : 0;
                    }
                }
            }

            boolean isValid = validateGridPattern(grid, height, width);
            System.out.println(isValid ? "YES" : "NO");
        }
    }

    /**
     * Validates if the grid contains a specific pattern:
     * A contiguous horizontal line of '*' with exactly one '*' directly above it,
     * and no '*' elsewhere in the grid.
     */
    private static boolean validateGridPattern(int[][] grid, int height, int width) {
        int baseRow = findBaseRow(grid, height, width);

        // The base row must contain >1 star and cannot be on the top or bottom edge
        if (baseRow == -1 || baseRow == 0 || baseRow == height - 1) {
            return false;
        }

        return processBaseRow(grid, height, width, baseRow);
    }

    /**
     * Identifies the row that contains more than one star.
     * Returns -1 if no such row exists.
     */
    private static int findBaseRow(int[][] grid, int height, int width) {
        int baseRow = -1;
        for (int i = 0; i < height; i++) {
            int starCount = 0;
            for (int j = 0; j < width; j++) {
                if (grid[i][j] == 1) {
                    starCount++;
                }
            }
            if (starCount > 1) {
                baseRow = i;
            }
        }
        return baseRow;
    }

    /**
     * Validates the horizontal contiguity, vertical extension, and ensures
     * all stars in the grid are accounted for.
     * Note: This method modifies the grid to mark processed stars.
     */
    private static boolean processBaseRow(int[][] grid, int height, int width, int baseRow) {
        boolean verticalExtensionFound = false;
        int extensionCol = -1;
        boolean previousWasStar = false;

        for (int j = 0; j < width; j++) {
            if (grid[baseRow][j] == 1) {
                previousWasStar = true;

                if (!verticalExtensionFound) {
                    boolean foundAbove = false;
                    for (int k = 0; k < height; k++) {
                        if (grid[k][j] == 1 && k != baseRow) {
                            if (k > baseRow) {
                                return false; // Stars are not allowed below the base row
                            }
                            foundAbove = true;
                            extensionCol = j;
                            grid[k][j] = 0; // Mark as processed
                        } else if (grid[k][j] == 0 && foundAbove) {
                            if (k <= baseRow + 1) {
                                return false;
                            }
                            break;
                        }
                    }
                    if (!foundAbove) {
                        return false; // Must have exactly one star directly above
                    }
                    verticalExtensionFound = true;
                }
                grid[baseRow][j] = 0; // Mark base star as processed
            } else if (previousWasStar) {
                // Gap detected after a contiguous block of stars
                if (j == extensionCol + 1) {
                    return false; // Extension column cannot be immediately followed by a gap
                }
                break; // End of the horizontal line
            }
        }

        if (!verticalExtensionFound) {
            return false;
        }

        // Verify that all stars have been processed (grid is empty)
        for (int i = 0; i < height; i++) {
            for (int j = 0; j < width; j++) {
                if (grid[i][j] == 1) {
                    return false;
                }
            }
        }
        return true;
    }
}

import java.util.Scanner;

public class HelloWorld15 {
    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            int rows = scanner.nextInt();
            int cols = scanner.nextInt();
            char[][] grid = readGrid(scanner, rows, cols);

            boolean centerFound = findAndClearCenter(grid, rows, cols);
            boolean hasRemainingStars = hasRemainingStars(grid);

            boolean success = centerFound && !hasRemainingStars;
            System.out.println(success ? "YES" : "NO");
        }
    }

    private static char[][] readGrid(Scanner scanner, int rows, int cols) {
        char[][] grid = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            grid[i] = scanner.next().toCharArray();
        }
        return grid;
    }

    private static boolean findAndClearCenter(char[][] grid, int rows, int cols) {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == '*' && isCenterOfCross(grid, i, j)) {
                    clearCross(grid, i, j);
                    return true;
                }
            }
        }
        return false;
    }

    private static boolean isCenterOfCross(char[][] grid, int row, int col) {
        if (row <= 0 || row >= grid.length - 1 ||
            col <= 0 || col >= grid[0].length - 1) {
            return false;
        }
        return grid[row - 1][col] == '*' &&
               grid[row + 1][col] == '*' &&
               grid[row][col - 1] == '*' &&
               grid[row][col + 1] == '*';
    }

    private static void clearCross(char[][] grid, int row, int col) {
        clearDirection(grid, row, col, 0, 1);  // right
        clearDirection(grid, row, col, 0, -1); // left
        clearDirection(grid, row, col, -1, 0); // up
        clearDirection(grid, row, col, 1, 0);  // down
    }

    private static void clearDirection(char[][] grid, int row, int col, int dRow, int dCol) {
        int r = row + dRow;
        int c = col + dCol;
        while (r >= 0 && r < grid.length && c >= 0 && c < grid[0].length && grid[r][c] == '*') {
            grid[r][c] = '.';
            r += dRow;
            c += dCol;
        }
    }

    private static boolean hasRemainingStars(char[][] grid) {
        for (char[] row : grid) {
            for (char cell : row) {
                if (cell == '*') {
                    return true;
                }
            }
        }
        return false;
    }
}

import java.util.Scanner;

/**
 * Validates if a grid contains a specific cross pattern of asterisks.
 * The pattern requires a central asterisk with asterisks in all 4 cardinal directions,
 * and all other asterisks in the grid must lie on the same row or column as the center,
 * forming a contiguous cross shape.
 */
public class GridCrossValidator {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        // Read dimensions
        if (!scanner.hasNextInt()) {
            return;
        }
        int rows = scanner.nextInt();
        int cols = scanner.nextInt();
        scanner.nextLine(); // Consume the newline character after integers

        // Read grid into a 2D char array for easier access
        char[][] grid = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            String line = scanner.nextLine();
            // Store the line as a char array. 
            // Note: In a production environment, we might validate line length here.
            grid[i] = line.toCharArray();
        }

        // Find the center of the cross
        int[] center = findCrossCenter(grid);

        if (center == null) {
            System.out.println("NO");
            return;
        }

        int centerRow = center[0];
        int centerCol = center[1];

        // Determine the boundaries of the cross arms
        // topLimit: index of the first non-star above the center (or -1 if none)
        int topLimit = -1;
        for (int i = centerRow; i >= 0; i--) {
            if (grid[i][centerCol] != '*') {
                topLimit = i;
                break;
            }
        }

        // bottomLimit: index of the first non-star below the center (or rows if none)
        int bottomLimit = rows;
        for (int i = centerRow; i < rows; i++) {
            if (grid[i][centerCol] != '*') {
                bottomLimit = i;
                break;
            }
        }

        // leftLimit: index of the first non-star to the left of the center (or -1 if none)
        int leftLimit = -1;
        for (int j = centerCol; j >= 0; j--) {
            if (grid[centerRow][j] != '*') {
                leftLimit = j;
                break;
            }
        }

        // rightLimit: index of the first non-star to the right of the center (or cols if none)
        int rightLimit = cols;
        for (int j = centerCol; j < cols; j++) {
            if (grid[centerRow][j] != '*') {
                rightLimit = j;
                break;
            }
        }

        // Validate that all asterisks in the grid conform to the cross pattern
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == '*') {
                    boolean onHorizontalAxis = (i == centerRow);
                    boolean onVerticalAxis = (j == centerCol);

                    // An asterisk must be on at least one axis of the cross
                    if (!onHorizontalAxis && !onVerticalAxis) {
                        System.out.println("NO");
                        return;
                    }

                    // If on horizontal axis, it must be within the horizontal bounds
                    if (onHorizontalAxis) {
                        if (j <= leftLimit || j >= rightLimit) {
                            System.out.println("NO");
                            return;
                        }
                    }

                    // If on vertical axis, it must be within the vertical bounds
                    if (onVerticalAxis) {
                        if (i <= topLimit || i >= bottomLimit) {
                            System.out.println("NO");
                            return;
                        }
                    }
                }
            }
        }

        System.out.println("YES");
    }

    /**
     * Finds the coordinates of a '*' that has '*' neighbors in all 4 cardinal directions.
     *
     * @param grid The character grid to search.
     * @return An int array {row, col} of the center, or null if not found.
     */
    private static int[] findCrossCenter(char[][] grid) {
        int rows = grid.length;
        if (rows == 0) return null;
        int cols = grid[0].length;

        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == '*') {
                    // Check 4 neighbors safely within grid bounds
                    boolean hasUp = (i > 0) && (grid[i - 1][j] == '*');
                    boolean hasDown = (i < rows - 1) && (grid[i + 1][j] == '*');
                    boolean hasLeft = (j > 0) && (grid[i][j - 1] == '*');
                    boolean hasRight = (j < cols - 1) && (grid[i][j + 1] == '*');

                    if (hasUp && hasDown && hasLeft && hasRight) {
                        return new int[]{i, j};
                    }
                }
            }
        }
        return null;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.OutputStream;
import java.io.PrintWriter;
import java.util.StringTokenizer;

/**
 * Refactored solution for the Star Cross problem.
 * 
 * Improvements made:
 * 1. Modularization: Logic extracted into separate methods (solve, findCenter, countCrossStars).
 * 2. Readability: Descriptive variable names (rows, cols, centerRow, etc.).
 * 3. Efficiency: Optimized the check from O(H*W) space/complexity to O(1) space by counting stars
 *    instead of using a boolean matrix, while maintaining O(H*W) time complexity.
 * 4. Robustness: Improved InputReader to handle potential EOF issues gracefully.
 * 5. Cleanup: Removed unused imports and redundant code.
 */
public class Codeforces {

    public static void main(String[] args) {
        // Initialize input and output streams
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);

        // Execute the solution logic
        solve(in, out);

        // Ensure output is flushed and closed
        out.close();
    }

    /**
     * Main logic to solve the problem.
     */
    private static void solve(InputReader in, PrintWriter out) {
        int rows = in.nextInt();
        int cols = in.nextInt();

        char[][] grid = new char[rows][cols];
        int totalStars = 0;

        // Read the grid and count total stars in a single pass
        for (int i = 0; i < rows; i++) {
            String line = in.next();
            grid[i] = line.toCharArray();
            for (char c : grid[i]) {
                if (c == '*') {
                    totalStars++;
                }
            }
        }

        // Find a valid center for the cross
        int[] center = findCenter(grid);

        if (center == null) {
            // No valid center found, output NO
            out.println("NO");
        } else {
            // Calculate the number of stars forming the cross centered at 'center'
            int crossStars = countCrossStars(grid, center[0], center[1]);

            // If the number of stars in the identified cross equals the total stars in the grid,
            // then the grid consists of exactly one cross.
            if (crossStars == totalStars) {
                out.println("YES");
            } else {
                out.println("NO");
            }
        }
    }

    /**
     * Finds a cell (r, c) such that it and its 4 immediate neighbors are '*'.
     * Returns an array {r, c} if found, otherwise null.
     */
    private static int[] findCenter(char[][] grid) {
        int rows = grid.length;
        int cols = grid[0].length;

        // Iterate through the grid, excluding borders as they cannot be centers
        // of a cross (neighbors would be out of bounds).
        for (int r = 1; r < rows - 1; r++) {
            for (int c = 1; c < cols - 1; c++) {
                if (grid[r][c] == '*'
                        && grid[r + 1][c] == '*'
                        && grid[r - 1][c] == '*'
                        && grid[r][c + 1] == '*'
                        && grid[r][c - 1] == '*') {
                    return new int[]{r, c};
                }
            }
        }
        return null;
    }

    /**
     * Counts the number of '*' stars in the cross shape centered at (centerRow, centerCol).
     * The cross extends in all 4 cardinal directions until a non-star cell is hit.
     */
    private static int countCrossStars(char[][] grid, int centerRow, int centerCol) {
        int count = 0;
        int rows = grid.length;
        int cols = grid[0].length;

        // Count the center itself
        if (grid[centerRow][centerCol] == '*') {
            count++;
        } else {
            return 0; // Should not happen if findCenter worked correctly
        }

        // Expand Up
        for (int r = centerRow - 1; r >= 0; r--) {
            if (grid[r][centerCol] == '*') {
                count++;
            } else {
                break;
            }
        }

        // Expand Down
        for (int r = centerRow + 1; r < rows; r++) {
            if (grid[r][centerCol] == '*') {
                count++;
            } else {
                break;
            }
        }

        // Expand Left
        for (int c = centerCol - 1; c >= 0; c--) {
            if (grid[centerRow][c] == '*') {
                count++;
            } else {
                break;
            }
        }

        // Expand Right
        for (int c = centerCol + 1; c < cols; c++) {
            if (grid[centerRow][c] == '*') {
                count++;
            } else {
                break;
            }
        }

        return count;
    }

    /**
     * Helper class for fast input reading.
     */
    public static class InputReader {
        public BufferedReader reader;
        public StringTokenizer tokenizer;

        public InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) {
                        return null;
                    }
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public String nextLine() {
            try {
                return reader.readLine();
            } catch (IOException e) {
                throw new RuntimeException(e);
            }
        }

        public int nextInt() {
            String s = next();
            if (s == null) throw new RuntimeException("End of input");
            return Integer.parseInt(s);
        }

        public long nextLong() {
            String s = next();
            if (s == null) throw new RuntimeException("End of input");
            return Long.parseLong(s);
        }
    }
}

import java.util.Scanner;

/**
 * Validates a grid pattern based on specific star placement rules.
 * Refactored for improved readability, maintainability, and structural clarity.
 */
public class PatternValidator {

    public static void main(String[] args) {
        // Use try-with-resources to ensure Scanner is properly managed
        try (Scanner scanner = new Scanner(System.in)) {
            if (!scanner.hasNextInt()) {
                return;
            }

            int height = scanner.nextInt();
            int width = scanner.nextInt();
            scanner.nextLine(); // Consume the newline character after width

            String[] grid = new String[height];
            for (int i = 0; i < height; i++) {
                grid[i] = scanner.nextLine();
            }

            System.out.println(validatePattern(grid, height, width));
        }
    }

    /**
     * Core validation logic for the grid pattern.
     * Returns "YES" if the pattern meets all criteria, otherwise "NO".
     */
    private static String validatePattern(String[] grid, int height, int width) {
        int centerCol = 0;
        int centerRow = 0;
        boolean foundFirstStar = false;
        boolean foundSecondStar = false;
        boolean centerLineIntact = true;

        for (int row = 0; row < height; row++) {
            String line = grid[row];
            for (int col = 0; col < width; col++) {
                char ch = line.charAt(col);

                if (!foundFirstStar) {
                    // Phase 1: Locate the first star and establish the center column
                    if (ch == '*') {
                        centerCol = col;
                        if (col == 0 || col == width - 1) {
                            return "NO";
                        }
                        foundFirstStar = true;
                    }
                } else {
                    // Phase 2: Validate the vertical center line continuity
                    if (col == centerCol && centerLineIntact) {
                        if (ch != '*') {
                            if (row <= centerRow + 1) {
                                return "NO";
                            }
                            centerLineIntact = false;
                        }
                    }

                    // Phase 3: Locate the second star on the current row
                    if (ch == '*' && !foundSecondStar) {
                        foundSecondStar = true;
                        centerRow = row;

                        // Validate positional constraints for the second star
                        // Note: Preserved original logic. col > centerCol will always be true here.
                        if (row == height - 1 || col > centerCol) {
                            return "NO";
                        }

                        // Validate the remainder of the row pattern
                        if (!validateRowPattern(line, col, centerCol, width)) {
                            return "NO";
                        }
                        break; // Row validation complete, move to next row
                    }

                    // Phase 4: Reject any additional stars after the second one
                    if (ch == '*') {
                        return "NO";
                    }
                }
            }
        }

        // Final boundary checks
        if (centerCol == 0 || centerRow == 0) {
            return "NO";
        }

        return "YES";
    }

    /**
     * Validates the pattern of stars and empty spaces for the remainder of a row.
     * Ensures that once a gap (non-star) appears, no more stars can follow.
     */
    private static boolean validateRowPattern(String line, int startCol, int centerCol, int width) {
        boolean lineBroken = false;
        for (int scanCol = startCol; scanCol < width; scanCol++) {
            char ch = line.charAt(scanCol);
            if (ch == '*') {
                if (lineBroken) {
                    return false;
                }
            } else {
                if (scanCol <= centerCol + 1) {
                    return false;
                }
                lineBroken = true;
            }
        }
        return true;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.HashSet;
import java.util.Objects;
import java.util.Set;

/**
 * Refactored solution for problem B1182.
 * 
 * This program reads a grid of characters and checks if all '*' characters
 * can be covered by a specific pattern centered at a valid coordinate.
 * The pattern consists of a center '*', its 4 immediate neighbors (Up, Down, Left, Right),
 * and lines extending from the center in 4 directions (skipping the immediate neighbors).
 */
public class GridPatternChecker {

    /**
     * Represents a coordinate (row, column) in the grid.
     */
    static class Coordinate {
        final int row;
        final int col;

        Coordinate(int row, int col) {
            this.row = row;
            this.col = col;
        }

        @Override
        public boolean equals(Object o) {
            if (this == o) return true;
            if (!(o instanceof Coordinate)) return false;
            Coordinate that = (Coordinate) o;
            return row == that.row && col == that.col;
        }

        @Override
        public int hashCode() {
            return Objects.hash(row, col);
        }
    }

    public static void main(String[] args) throws IOException {
        // Use try-with-resources for automatic resource management
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            String line = br.readLine();
            if (line == null || line.trim().isEmpty()) {
                return;
            }

            // Split by whitespace to handle multiple spaces robustly
            String[] parts = line.trim().split("\\s+");
            int rows = Integer.parseInt(parts[0]);
            int cols = Integer.parseInt(parts[1]);

            char[][] grid = new char[rows][cols];
            int starCount = 0;

            // Read grid and count stars
            for (int i = 0; i < rows; i++) {
                String rowStr = br.readLine();
                if (rowStr == null) break;

                // Fill the row, handling potential short lines gracefully
                int len = Math.min(rowStr.length(), cols);
                for (int j = 0; j < len; j++) {
                    grid[i][j] = rowStr.charAt(j);
                    if (grid[i][j] == '*') {
                        starCount++;
                    }
                }
                // Fill remaining cells with '.' if the line was short
                for (int j = len; j < cols; j++) {
                    grid[i][j] = '.';
                }
            }

            // If no stars exist, the condition fails (based on original logic)
            if (starCount == 0) {
                System.out.println("NO");
                return;
            }

            // Set to store coordinates that are part of the valid shape
            // Using HashSet is semantically correct here instead of HashMap<Integer>
            Set<Coordinate> coveredCells = new HashSet<>();
            boolean validCenterFound = false;

            // Iterate through the grid to find a valid center.
            // A valid center must not be on the border (indices 1 to n-2).
            searchLoop:
            for (int i = 1; i < rows - 1; i++) {
                for (int j = 1; j < cols - 1; j++) {
                    if (grid[i][j] == '*') {
                        // Check if the immediate neighbors (Up, Down, Left, Right) are also '*'
                        if (grid[i - 1][j] == '*' && 
                            grid[i + 1][j] == '*' && 
                            grid[i][j - 1] == '*' && 
                            grid[i][j + 1] == '*') {

                            // Found a valid center at (i, j)
                            Coordinate center = new Coordinate(i, j);
                            coveredCells.add(center);

                            // Add the immediate neighbors
                            coveredCells.add(new Coordinate(i - 1, j));
                            coveredCells.add(new Coordinate(i + 1, j));
                            coveredCells.add(new Coordinate(i, j - 1));
                            coveredCells.add(new Coordinate(i, j + 1));

                            // Extend lines from the center in 4 directions.
                            // Note: Original logic starts extending from offset 2 (skipping immediate neighbor).

                            // Down
                            for (int k = i + 2; k < rows; k++) {
                                if (grid[k][j] == '.') break;
                                coveredCells.add(new Coordinate(k, j));
                            }
                            // Up
                            for (int k = i - 2; k >= 0; k--) {
                                if (grid[k][j] == '.') break;
                                coveredCells.add(new Coordinate(k, j));
                            }
                            // Right
                            for (int k = j + 2; k < cols; k++) {
                                if (grid[i][k] == '.') break;
                                coveredCells.add(new Coordinate(i, k));
                            }
                            // Left
                            for (int k = j - 2; k >= 0; k--) {
                                if (grid[i][k] == '.') break;
                                coveredCells.add(new Coordinate(i, k));
                            }

                            validCenterFound = true;
                            // Exit loops early as per original logic (break out of both loops)
                            break searchLoop;
                        }
                    }
                }
            }

            // Verify that every '*' in the grid is covered by the shape found
            boolean allStarsCovered = true;
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j] == '*') {
                        if (!coveredCells.contains(new Coordinate(i, j))) {
                            allStarsCovered = false;
                            break;
                        }
                    }
                }
                if (!allStarsCovered) break;
            }

            if (allStarsCovered) {
                System.out.println("YES");
            } else {
                System.out.println("NO");
            }
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

/**
 * Validates whether a 2D character grid contains a specific cross-like pattern.
 * The algorithm uses a row-by-row state machine to track the expected structure:
 * 1. INITIAL: Locate the first '*' to define the vertical axis column.
 * 2. MIDDLE_ROW: Expect the horizontal bar crossing the vertical axis.
 * 3. BOTTOM_ROWS: Expect '*' only on the vertical axis.
 */
public class GridPatternChecker {

    private static final int MIN_DIMENSION = 3;

    /** Represents the current phase of pattern validation. */
    private enum PatternState {
        INITIAL,
        MIDDLE_ROW,
        BOTTOM_ROWS
    }

    public static void main(String[] args) throws IOException {
        // Use try-with-resources for automatic resource management
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(System.in))) {
            String inputLine = reader.readLine();
            if (inputLine == null || inputLine.trim().isEmpty()) {
                return;
            }

            StringTokenizer tokenizer = new StringTokenizer(inputLine);
            int rowCount = Integer.parseInt(tokenizer.nextToken());
            int colCount = Integer.parseInt(tokenizer.nextToken());

            char[][] grid = new char[rowCount][colCount];
            for (int i = 0; i < rowCount; i++) {
                String rowLine = reader.readLine();
                grid[i] = (rowLine != null) ? rowLine.toCharArray() : new char[colCount];
            }

            boolean isValid = isValidCrossPattern(grid, rowCount, colCount);
            System.out.println(isValid ? "YES" : "NO");
        }
    }

    /**
     * Checks if the grid matches the expected cross pattern.
     *
     * @param grid     The 2D character grid to validate
     * @param rowCount Number of rows in the grid
     * @param colCount Number of columns in the grid
     * @return true if the pattern is valid, false otherwise
     */
    private static boolean isValidCrossPattern(char[][] grid, int rowCount, int colCount) {
        if (rowCount < MIN_DIMENSION || colCount < MIN_DIMENSION) {
            return false;
        }

        PatternState currentState = PatternState.INITIAL;
        boolean foundAnyStar = false;
        int verticalAxisCol = -1;
        int middleRowIndex = -1;
        int horizontalBarEndCol = -1;

        for (int i = 0; i < rowCount; i++) {
            // Transition from middle row to bottom rows at the start of a new row
            if (currentState == PatternState.MIDDLE_ROW) {
                currentState = PatternState.BOTTOM_ROWS;
            }

            for (int j = 0; j < colCount; j++) {
                char ch = grid[i][j];
                if (!foundAnyStar && ch == '*') {
                    foundAnyStar = true;
                }

                switch (currentState) {
                    case INITIAL:
                        if (verticalAxisCol == -1 && ch == '*') {
                            verticalAxisCol = j;
                            continue;
                        }
                        if (verticalAxisCol != -1) {
                            if (verticalAxisCol < j && ch == '*') {
                                return false;
                            }
                            if (verticalAxisCol > j && ch == '*') {
                                currentState = PatternState.MIDDLE_ROW;
                            }
                            if (j == verticalAxisCol && ch != '*') {
                                return false;
                            }
                        }
                        break;

                    case MIDDLE_ROW:
                        middleRowIndex = i;
                        if (ch != '*') {
                            if (j <= verticalAxisCol + 1) {
                                return false;
                            } else if (horizontalBarEndCol == -1) {
                                horizontalBarEndCol = j;
                            }
                        } else if (horizontalBarEndCol != -1) {
                            return false;
                        }
                        break;

                    case BOTTOM_ROWS:
                        if (ch == '*' && verticalAxisCol != -1 && j != verticalAxisCol) {
                            return false;
                        }
                        if (ch == '.' && verticalAxisCol != -1 && j == verticalAxisCol) {
                            if (middleRowIndex + 1 == i) {
                                return false;
                            } else {
                                verticalAxisCol = -1;
                            }
                        }
                        if (verticalAxisCol == -1 && ch == '*') {
                            return false;
                        }
                        break;
                }
            }
        }

        return foundAnyStar && currentState == PatternState.BOTTOM_ROWS;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

public class Plus {

    public static void main(String[] args) throws IOException {
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
             PrintWriter out = new PrintWriter(System.out)) {

            String line = br.readLine();
            if (line == null) return;

            StringTokenizer st = new StringTokenizer(line);
            int rows = Integer.parseInt(st.nextToken());
            int cols = Integer.parseInt(st.nextToken());

            char[][] grid = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                String rowLine = br.readLine();
                if (rowLine != null) {
                    rowLine = rowLine.trim();
                    for (int j = 0; j < cols && j < rowLine.length(); j++) {
                        grid[i][j] = rowLine.charAt(j);
                    }
                }
            }

            int[] center = findCenter(grid);
            if (center[0] == -1) {
                out.println("NO");
            } else {
                int[] bounds = findBounds(grid, center[0], center[1]);
                boolean isValid = isCrossShape(grid, center[0], center[1], bounds);
                out.println(isValid ? "YES" : "NO");
            }
        }
    }

    /**
     * Locates the center '*' that has '*' neighbors in all four cardinal directions.
     * Returns {row, col} or {-1, -1} if no valid center exists.
     */
    private static int[] findCenter(char[][] grid) {
        int rows = grid.length;
        int cols = grid[0].length;

        for (int i = 1; i < rows - 1; i++) {
            for (int j = 1; j < cols - 1; j++) {
                if (grid[i][j] == '*' &&
                    grid[i - 1][j] == '*' && grid[i + 1][j] == '*' &&
                    grid[i][j - 1] == '*' && grid[i][j + 1] == '*') {
                    return new int[]{i, j};
                }
            }
        }
        return new int[]{-1, -1};
    }

    /**
     * Determines the boundaries of the cross shape centered at (centerRow, centerCol).
     * Returns an array: {top, bottom, left, right}.
     */
    private static int[] findBounds(char[][] grid, int centerRow, int centerCol) {
        int rows = grid.length;
        int cols = grid[0].length;
        int top = centerRow, bottom = centerRow;
        int left = centerCol, right = centerCol;

        // Expand vertically to find top and bottom bounds
        while (top > 0 && grid[top - 1][centerCol] == '*') top--;
        while (bottom < rows - 1 && grid[bottom + 1][centerCol] == '*') bottom++;

        // Expand horizontally to find left and right bounds
        while (left > 0 && grid[centerRow][left - 1] == '*') left--;
        while (right < cols - 1 && grid[centerRow][right + 1] == '*') right++;

        return new int[]{top, bottom, left, right};
    }

    /**
     * Validates that all '*' characters in the grid form exactly the cross shape
     * defined by the center coordinates and calculated bounds.
     */
    private static boolean isCrossShape(char[][] grid, int centerRow, int centerCol, int[] bounds) {
        int top = bounds[0], bottom = bounds[1];
        int left = bounds[2], right = bounds[3];

        for (int i = 0; i < grid.length; i++) {
            for (int j = 0; j < grid[0].length; j++) {
                if (grid[i][j] == '*') {
                    boolean onVertical = (j == centerCol && i >= top && i <= bottom);
                    boolean onHorizontal = (i == centerRow && j >= left && j <= right);
                    if (!onVertical && !onHorizontal) {
                        return false;
                    }
                }
            }
        }
        return true;
    }
}

import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.InputMismatchException;

public class Main {
    public static void main(String[] args) throws IOException {
        FastScanner in = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            int n = in.nextInt();
            int m = in.nextInt();
            char[][] grid = in.nextCharTable(n, m);

            BPlusFromPicture solver = new BPlusFromPicture();
            solver.solve(n, m, grid, out);
        } finally {
            out.flush();
            out.close();
        }
    }

    static class BPlusFromPicture {
        /**
         * Solves the problem by identifying a cross pattern in the grid.
         * 
         * @param n    Number of rows
         * @param m    Number of columns
         * @param grid The input character grid
         * @param out  Output writer
         */
        public void solve(int n, int m, char[][] grid, PrintWriter out) {
            int centerRow = -1;
            int centerCol = -1;

            // Find the intersection point of the cross
            // Valid center must have neighbors in all 4 cardinal directions
            for (int i = 1; i < n - 1; i++) {
                for (int j = 1; j < m - 1; j++) {
                    if (grid[i][j] == '*' &&
                        grid[i - 1][j] == '*' && grid[i + 1][j] == '*' &&
                        grid[i][j - 1] == '*' && grid[i][j + 1] == '*') {
                        centerRow = i;
                        centerCol = j;
                        break;
                    }
                }
                if (centerRow != -1) break;
            }

            if (centerRow == -1) {
                out.println("NO");
                return;
            }

            // Mark all cells that belong to the cross
            boolean[][] isCross = new boolean[n][m];
            markCrossVertical(grid, isCross, centerRow, centerCol, n);
            markCrossHorizontal(grid, isCross, centerRow, centerCol, m);

            // Verify that every '*' in the grid is part of the cross
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    if (grid[i][j] == '*' && !isCross[i][j]) {
                        out.println("NO");
                        return;
                    }
                }
            }
            out.println("YES");
        }

        private void markCrossVertical(char[][] grid, boolean[][] isCross, int centerRow, int centerCol, int n) {
            for (int i = centerRow; i < n && grid[i][centerCol] == '*'; i++) {
                isCross[i][centerCol] = true;
            }
            for (int i = centerRow - 1; i >= 0 && grid[i][centerCol] == '*'; i--) {
                isCross[i][centerCol] = true;
            }
        }

        private void markCrossHorizontal(char[][] grid, boolean[][] isCross, int centerRow, int centerCol, int m) {
            for (int j = centerCol; j < m && grid[centerRow][j] == '*'; j++) {
                isCross[centerRow][j] = true;
            }
            for (int j = centerCol - 1; j >= 0 && grid[centerRow][j] == '*'; j--) {
                isCross[centerRow][j] = true;
            }
        }
    }

    /**
     * Fast input scanner for competitive programming / high-throughput I/O.
     * Uses composition instead of inheritance to properly wrap an InputStream.
     */
    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1024];
        private int ptr = 0;
        private int buflen = 0;

        public FastScanner(InputStream in) {
            this.in = in;
        }

        private int readByte() throws IOException {
            if (ptr >= buflen) {
                ptr = 0;
                buflen = in.read(buffer);
                if (buflen <= 0) return -1;
            }
            return buffer[ptr++];
        }

        public int nextInt() throws IOException {
            int c = readByte();
            while (c <= ' ') {
                if (c == -1) throw new InputMismatchException();
                c = readByte();
            }
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = readByte();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9') {
                    if (c == -1) break;
                    throw new InputMismatchException();
                }
                res = res * 10 + (c - '0');
                c = readByte();
            } while (c > ' ' && c != -1);
            return res * sgn;
        }

        public char[][] nextCharTable(int rows, int cols) throws IOException {
            char[][] grid = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    grid[i][j] = nextChar();
                }
            }
            return grid;
        }

        public char nextChar() throws IOException {
            int c = readByte();
            while (c <= ' ') {
                if (c == -1) throw new InputMismatchException();
                c = readByte();
            }
            return (char) c;
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

public class Main {

    public static void main(String[] args) {
        // Encapsulate logic in an instance to avoid static state and improve maintainability
        new Main().solve();
    }

    private void solve() {
        FastReader reader = new FastReader();

        // Read grid dimensions
        // Added null checks for robustness against empty input
        String hStr = reader.next();
        if (hStr == null) return;
        int rows = Integer.parseInt(hStr);

        String wStr = reader.next();
        if (wStr == null) return;
        int cols = Integer.parseInt(wStr);

        // Read the grid
        char[][] grid = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            String line = reader.next();
            if (line != null) {
                grid[i] = line.toCharArray();
            }
        }

        boolean patternFound = false;

        // Iterate through the grid to find the target pattern.
        // The pattern is a '*' cell surrounded by '*' in all 4 cardinal directions.
        // We iterate from index 1 to rows-2 (and cols-2) because neighbors must exist.
        for (int r = 1; r < rows - 1; r++) {
            for (int c = 1; c < cols - 1; c++) {
                if (grid[r][c] == '*' &&
                    grid[r - 1][c] == '*' &&
                    grid[r + 1][c] == '*' &&
                    grid[r][c - 1] == '*' &&
                    grid[r][c + 1] == '*') {

                    // Pattern found: clear the cross shape centered at (r, c)
                    clearCross(grid, r, c, rows, cols);
                    patternFound = true;
                    break; // Original logic stops searching after the first match
                }
            }
            if (patternFound) {
                break;
            }
        }

        // Determine the output based on the result
        if (patternFound) {
            // If pattern was found, check if the grid is completely empty of stars
            if (hasRemainingStars(grid)) {
                System.out.println("NO");
            } else {
                System.out.println("YES");
            }
        } else {
            // If no pattern was found, the condition is not met
            System.out.println("NO");
        }
    }

    /**
     * Clears the cross shape centered at (r, c).
     * It clears the center cell and extends in all 4 cardinal directions (Up, Down, Left, Right)
     * clearing '*' cells until it encounters a '.' (empty space) or the grid boundary.
     */
    private void clearCross(char[][] grid, int r, int c, int rows, int cols) {
        grid[r][c] = '.'; // Clear the center

        // Directions: Up, Down, Left, Right
        int[] dr = {-1, 1, 0, 0};
        int[] dc = {0, 0, -1, 1};

        for (int i = 0; i < 4; i++) {
            int currR = r;
            int currC = c;

            // Traverse in the current direction
            while (true) {
                int nextR = currR + dr[i];
                int nextC = currC + dc[i];

                // Check grid boundaries
                if (nextR < 0 || nextR >= rows || nextC < 0 || nextC >= cols) {
                    break;
                }

                // Stop if we encounter an empty space '.'
                if (grid[nextR][nextC] == '.') {
                    break;
                }

                // Clear the star and move to the next cell
                grid[nextR][nextC] = '.';
                currR = nextR;
                currC = nextC;
            }
        }
    }

    /**
     * Checks if there are any '*' characters remaining in the grid.
     */
    private boolean hasRemainingStars(char[][] grid) {
        for (char[] row : grid) {
            for (char cell : row) {
                if (cell == '*') {
                    return true;
                }
            }
        }
        return false;
    }

    /**
     * Helper class for fast input reading.
     */
    static class FastReader {
        BufferedReader br;
        StringTokenizer st;

        public FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            String s = next();
            return (s == null) ? 0 : Integer.parseInt(s);
        }

        long nextLong() {
            String s = next();
            return (s == null) ? 0L : Long.parseLong(s);
        }

        double nextDouble() {
            String s = next();
            return (s == null) ? 0.0 : Double.parseDouble(s);
        }

        String nextLine() {
            String str = "";
            try {
                str = br.readLine();
            } catch (IOException e) {
                throw new RuntimeException(e);
            }
            return str;
        }
    }
}

import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) {
        // Use try-with-resources to guarantee proper resource cleanup and flushing
        try (InputReader in = new InputReader(System.in);
             PrintWriter out = new PrintWriter(System.out)) {

            PlusGridAnalyzer analyzer = new PlusGridAnalyzer(in, out);
            analyzer.solve();
        }
    }

    /**
     * Encapsulates all grid analysis logic.
     * Replaces global static state with instance fields, making the code
     * thread-safe, testable, and easier to maintain.
     */
    static class PlusGridAnalyzer {
        private final int rows;
        private final int cols;
        private final String[] grid;
        private final boolean[][] marked;
        private int plusRow = -1;
        private int plusCol = -1;
        private final PrintWriter out;

        public PlusGridAnalyzer(InputReader in, PrintWriter out) {
            this.out = out;
            this.rows = in.nextInt();
            this.cols = in.nextInt();
            this.grid = new String[rows];
            this.marked = new boolean[rows][cols];

            for (int i = 0; i < rows; i++) {
                grid[i] = in.next();
            }
        }

        public void solve() {
            int plusCount = findPlusCenter();
            if (plusCount != 1) {
                out.println("NO");
                return;
            }

            markPlusCells();
            if (verifyAllStarsMarked()) {
                out.println("YES");
            } else {
                out.println("NO");
            }
        }

        /**
         * Checks if a cell at (r, c) is within bounds and contains a star.
         */
        private boolean isStar(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols && grid[r].charAt(c) == '*';
        }

        /**
         * Scans the grid to find the center of the plus sign.
         * Returns the total number of valid plus centers found.
         */
        private int findPlusCenter() {
            int count = 0;
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (isPlusCenter(r, c)) {
                        count++;
                        plusRow = r;
                        plusCol = c;
                    }
                }
            }
            return count;
        }

        /**
         * Determines if the cell at (r, c) and its 4 immediate neighbors form a plus sign.
         */
        private boolean isPlusCenter(int r, int c) {
            return isStar(r, c) &&
                   isStar(r - 1, c) &&
                   isStar(r + 1, c) &&
                   isStar(r, c - 1) &&
                   isStar(r, c + 1);
        }

        /**
         * Marks all cells that are part of the identified plus sign.
         * Uses explicit boundary checks and star validation for safety.
         */
        private void markPlusCells() {
            // Mark vertical line (upwards)
            for (int r = plusRow; r >= 0 && grid[r].charAt(plusCol) == '*'; r--) {
                marked[r][plusCol] = true;
            }
            // Mark vertical line (downwards)
            for (int r = plusRow + 1; r < rows && grid[r].charAt(plusCol) == '*'; r++) {
                marked[r][plusCol] = true;
            }

            // Mark horizontal line (leftwards)
            for (int c = plusCol; c >= 0 && grid[plusRow].charAt(c) == '*'; c--) {
                marked[plusRow][c] = true;
            }
            // Mark horizontal line (rightwards)
            for (int c = plusCol + 1; c < cols && grid[plusRow].charAt(c) == '*'; c++) {
                marked[plusRow][c] = true;
            }
        }

        /**
         * Verifies that every '*' in the grid has been covered by the plus sign.
         */
        private boolean verifyAllStarsMarked() {
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r].charAt(c) == '*' && !marked[r][c]) {
                        return false;
                    }
                }
            }
            return true;
        }
    }

    /**
     * Fast input reader for handling large volumes of input data efficiently.
     */
    static class InputReader {
        public BufferedReader reader;
        public StringTokenizer tokenizer;

        public InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) {
                        throw new EOFException("Unexpected end of input");
                    }
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

/**
 * Validates whether a given grid of characters forms a valid cross pattern.
 * A valid cross consists of a contiguous horizontal line and a contiguous vertical line
 * that intersect at exactly one cell, with at least one '*' extending in all four
 * cardinal directions from the intersection.
 */
public class Main {

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner();

        // Read grid dimensions
        String hStr = scanner.next();
        String wStr = scanner.next();
        if (hStr == null || wStr == null) {
            return;
        }

        int h = Integer.parseInt(hStr);
        int w = Integer.parseInt(wStr);

        // Read grid data
        char[][] grid = new char[h][w];
        for (int i = 0; i < h; i++) {
            String row = scanner.next();
            if (row != null) {
                grid[i] = row.toCharArray();
            }
        }

        // Validate and output result
        System.out.println(validateCrossPattern(grid, h, w) ? "YES" : "NO");
    }

    /**
     * Checks if the grid contains exactly one valid cross pattern formed by '*' characters.
     *
     * @param grid The 2D character array representing the grid
     * @param h    Number of rows
     * @param w    Number of columns
     * @return true if a valid cross exists, false otherwise
     */
    private static boolean validateCrossPattern(char[][] grid, int h, int w) {
        int starCount = 0;
        int[] rowCount = new int[h];
        int[] colCount = new int[w];

        // Count '*' occurrences per row and column
        for (int r = 0; r < h; r++) {
            for (int c = 0; c < w; c++) {
                if (grid[r][c] == '*') {
                    starCount++;
                    rowCount[r]++;
                    colCount[c]++;
                }
            }
        }

        // A valid cross requires at least 5 stars (center + 4 arms)
        if (starCount < 5) {
            return false;
        }

        // Identify candidate row and column (those with the most '*'s)
        int candidateRow = -1, maxRow = 0;
        for (int r = 0; r < h; r++) {
            if (rowCount[r] > maxRow) {
                maxRow = rowCount[r];
                candidateRow = r;
            }
        }

        int candidateCol = -1, maxCol = 0;
        for (int c = 0; c < w; c++) {
            if (colCount[c] > maxCol) {
                maxCol = colCount[c];
                candidateCol = c;
            }
        }

        // Must have valid candidates and both lines must contain multiple stars
        if (candidateRow == -1 || candidateCol == -1 || maxRow <= 1 || maxCol <= 1) {
            return false;
        }

        // Verify that ALL '*' characters lie exactly on the candidate row or column
        for (int r = 0; r < h; r++) {
            for (int c = 0; c < w; c++) {
                if (grid[r][c] == '*') {
                    if (r != candidateRow && c != candidateCol) {
                        return false; // Stray '*' not on the cross lines
                    }
                }
            }
        }

        // Verify horizontal line continuity and arm extension
        boolean hLeft = false, hRight = false;
        for (int c = 0; c < w; c++) {
            if (grid[candidateRow][c] == '*') {
                if (c < candidateCol) hLeft = true;
                if (c > candidateCol) hRight = true;
            } else if (c != candidateCol) {
                return false; // Gap detected in horizontal line
            }
        }

        // Verify vertical line continuity and arm extension
        boolean vUp = false, vDown = false;
        for (int r = 0; r < h; r++) {
            if (grid[r][candidateCol] == '*') {
                if (r < candidateRow) vUp = true;
                if (r > candidateRow) vDown = true;
            } else if (r != candidateRow) {
                return false; // Gap detected in vertical line
            }
        }

        // Valid cross requires arms extending in all four directions from the intersection
        return hLeft && hRight && vUp && vDown;
    }

    /**
     * Lightweight, standard-compliant fast I/O utility for competitive programming.
     * Replaces the original custom InputReader with a cleaner, well-documented implementation.
     */
    private static class FastScanner {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastScanner() {
            reader = new BufferedReader(new InputStreamReader(System.in));
        }

        /**
         * Reads the next token from input.
         *
         * @return The next token as a String, or null if end-of-stream is reached
         */
        String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) {
                        return null;
                    }
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input", e);
                }
            }
            return tokenizer.nextToken();
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

public class GridCrossValidator {

    public static void main(String[] args) {
        FastReader reader = new FastReader();

        // Read grid dimensions
        int height = reader.nextInt();
        int width = reader.nextInt();

        char[][] grid = new char[height][width];
        int totalStarCount = 0;

        // Read grid rows and count total stars in a single pass
        for (int i = 0; i < height; i++) {
            String line = reader.next();
            for (int j = 0; j < width; j++) {
                grid[i][j] = line.charAt(j);
                if (grid[i][j] == '*') {
                    totalStarCount++;
                }
            }
        }

        // Check if any star forms a complete cross covering all stars
        boolean isValidCrossFound = false;
        for (int i = 0; i < height; i++) {
            for (int j = 0; j < width; j++) {
                if (grid[i][j] == '*') {
                    if (isCompleteCross(grid, i, j, height, width, totalStarCount)) {
                        isValidCrossFound = true;
                        break; // Early exit: valid cross found
                    }
                }
            }
            if (isValidCrossFound) {
                break; // Early exit: outer loop
            }
        }

        System.out.println(isValidCrossFound ? "YES" : "NO");
    }

    /**
     * Determines if the star at (centerRow, centerCol) forms a complete cross
     * such that the total number of stars in the cross equals the total stars in the grid.
     */
    private static boolean isCompleteCross(char[][] grid, int centerRow, int centerCol,
                                           int height, int width, int totalStars) {
        int up = countConsecutiveStars(grid, centerRow, centerCol, -1, 0, height, width);
        int down = countConsecutiveStars(grid, centerRow, centerCol, 1, 0, height, width);
        int left = countConsecutiveStars(grid, centerRow, centerCol, 0, -1, height, width);
        int right = countConsecutiveStars(grid, centerRow, centerCol, 0, 1, height, width);

        // A valid cross must extend at least one step in all four cardinal directions
        if (up > 0 && down > 0 && left > 0 && right > 0) {
            // Total stars in the cross = 4 arms + center cell
            return (up + down + left + right + 1) == totalStars;
        }
        return false;
    }

    /**
     * Counts consecutive stars moving in a specific direction from the starting position.
     */
    private static int countConsecutiveStars(char[][] grid, int startRow, int startCol,
                                             int rowStep, int colStep, int height, int width) {
        int count = 0;
        int r = startRow + rowStep;
        int c = startCol + colStep;

        while (r >= 0 && r < height && c >= 0 && c < width && grid[r][c] == '*') {
            count++;
            r += rowStep;
            c += colStep;
        }
        return count;
    }

    /**
     * Fast I/O helper class optimized for competitive programming scenarios.
     */
    private static class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null; // Handle EOF gracefully
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input stream", e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.OutputStream;
import java.io.PrintWriter;
import java.util.StringTokenizer;

public class Main {

    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);

        GridCrossSolver solver = new GridCrossSolver();
        solver.solve(in, out);

        out.flush();
        out.close();
    }

    static class GridCrossSolver {
        private static final int EMPTY = 0;
        private static final int FILLED = 1;

        void solve(InputReader in, PrintWriter out) {
            int h = in.nextInt();
            int w = in.nextInt();
            int[][] grid = readGrid(in, h, w);

            boolean changed = true;
            // Repeat passes until no more crosses can be removed
            while (changed) {
                changed = false;
                // Only need to check inner cells since borders cannot be centers
                for (int i = 1; i < h - 1; i++) {
                    for (int j = 1; j < w - 1; j++) {
                        if (canRemoveCross(grid, i, j)) {
                            removeCross(grid, i, j, h, w);
                            changed = true;
                        }
                    }
                }
            }

            if (hasRemainingFilledCells(grid, h, w)) {
                out.println("NO");
            } else {
                out.println("YES");
            }
        }

        private int[][] readGrid(InputReader in, int h, int w) {
            int[][] grid = new int[h][w];
            for (int i = 0; i < h; i++) {
                String row = in.next();
                for (int j = 0; j < w; j++) {
                    grid[i][j] = (row.charAt(j) == '.') ? EMPTY : FILLED;
                }
            }
            return grid;
        }

        private boolean canRemoveCross(int[][] grid, int i, int j) {
            return grid[i][j] == FILLED &&
                   grid[i - 1][j] == FILLED &&
                   grid[i + 1][j] == FILLED &&
                   grid[i][j - 1] == FILLED &&
                   grid[i][j + 1] == FILLED;
        }

        private void removeCross(int[][] grid, int i, int j, int h, int w) {
            grid[i][j] = EMPTY;
            for (int t = i - 1; t >= 0 && grid[t][j] == FILLED; t--) grid[t][j] = EMPTY;
            for (int t = i + 1; t < h && grid[t][j] == FILLED; t++) grid[t][j] = EMPTY;
            for (int t = j - 1; t >= 0 && grid[i][t] == FILLED; t--) grid[i][t] = EMPTY;
            for (int t = j + 1; t < w && grid[i][t] == FILLED; t++) grid[i][t] = EMPTY;
        }

        private boolean hasRemainingFilledCells(int[][] grid, int h, int w) {
            for (int[] row : grid) {
                for (int cell : row) {
                    if (cell == FILLED) {
                        return true;
                    }
                }
            }
            return false;
        }
    }

    static class InputReader {
        public BufferedReader reader;
        public StringTokenizer tokenizer;

        public InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            String s = next();
            if (s == null) throw new RuntimeException("Unexpected end of input");
            return Integer.parseInt(s);
        }
    }
}

import java.io.*;
import java.util.StringTokenizer;

public class Main {
    public static void main(String[] args) {
        FastScanner in = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out);

        GridCrossSolver solver = new GridCrossSolver();
        solver.solve(in, out);

        out.flush(); // Ensure all output is written before termination
    }

    /**
     * Encapsulates the business logic for detecting and removing a cross pattern from a grid.
     */
    static class GridCrossSolver {
        public void solve(FastScanner sc, PrintWriter out) {
            int h = sc.nextInt();
            int w = sc.nextInt();
            char[][] grid = new char[h][w];

            for (int i = 0; i < h; i++) {
                grid[i] = sc.nextLine().toCharArray();
            }

            int centerX = -1, centerY = -1;

            // Find the center of the cross
            for (int i = 1; i < h - 1; i++) {
                for (int j = 1; j < w - 1; j++) {
                    if (isCrossCenter(grid, i, j)) {
                        if (centerX != -1) {
                            // Multiple cross centers found
                            out.println("NO");
                            return;
                        }
                        centerX = i;
                        centerY = j;
                    }
                }
            }

            if (centerX == -1) {
                out.println("NO");
                return;
            }

            // Remove the cross pattern
            grid[centerX][centerY] = '.';
            clearVerticalArm(grid, centerX, centerY, -1);
            clearVerticalArm(grid, centerX, centerY, 1);
            clearHorizontalArm(grid, centerX, centerY, -1);
            clearHorizontalArm(grid, centerX, centerY, 1);

            // Verify no '*' characters remain
            if (!isGridEmpty(grid)) {
                out.println("NO");
            } else {
                out.println("YES");
            }
        }

        /**
         * Checks if the cell at (r, c) forms the center of a cross.
         */
        private boolean isCrossCenter(char[][] grid, int r, int c) {
            return grid[r][c] == '*' &&
                   grid[r + 1][c] == '*' &&
                   grid[r - 1][c] == '*' &&
                   grid[r][c + 1] == '*' &&
                   grid[r][c - 1] == '*';
        }

        /**
         * Clears a vertical arm of the cross starting from the center and moving in the given direction.
         */
        private void clearVerticalArm(char[][] grid, int r, int c, int direction) {
            for (int i = r + direction; i >= 0 && i < grid.length; i += direction) {
                if (grid[i][c] == '.') break;
                grid[i][c] = '.';
            }
        }

        /**
         * Clears a horizontal arm of the cross starting from the center and moving in the given direction.
         */
        private void clearHorizontalArm(char[][] grid, int r, int c, int direction) {
            for (int i = c + direction; i >= 0 && i < grid[0].length; i += direction) {
                if (grid[r][i] == '.') break;
                grid[r][i] = '.';
            }
        }

        /**
         * Checks if the grid contains any remaining '*' characters.
         */
        private boolean isGridEmpty(char[][] grid) {
            for (char[] row : grid) {
                for (char cell : row) {
                    if (cell == '*') return false;
                }
            }
            return true;
        }
    }

    /**
     * Fast I/O helper class for competitive programming and performance-sensitive applications.
     */
    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner(InputStream in) {
            this.br = new BufferedReader(new InputStreamReader(in));
        }

        public String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input", e);
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public String nextLine() {
            try {
                return br.readLine();
            } catch (IOException e) {
                throw new RuntimeException("Failed to read line", e);
            }
        }
    }
}

import java.io.IOException;
import java.io.InputStream;
import java.util.NoSuchElementException;

public class Main {
    public static void main(String[] args) {
        FastScanner sc = new FastScanner();
        int height = sc.nextInt();
        int width = sc.nextInt();

        boolean[][] grid = new boolean[height][width];
        int[] rowCount = new int[height];
        int[] colCount = new int[width];

        // 1. Parse input and count stars per row/column
        for (int i = 0; i < height; i++) {
            String line = sc.next();
            for (int j = 0; j < width; j++) {
                if (line.charAt(j) == '*') {
                    grid[i][j] = true;
                    rowCount[i]++;
                    colCount[j]++;
                }
            }
        }

        // 2. Find the unique row and column that contain more than one star
        int crossRow = findUniqueIndex(rowCount, height);
        int crossCol = findUniqueIndex(colCount, width);

        if (crossRow == -1 || crossCol == -1) {
            System.out.println("NO");
            return;
        }

        // 3. Intersection must be a star
        if (!grid[crossRow][crossCol]) {
            System.out.println("NO");
            return;
        }

        // 4. Validate the pattern: exactly two crossing lines with no stray stars
        if (!validatePattern(grid, crossRow, crossCol, height, width)) {
            System.out.println("NO");
            return;
        }

        System.out.println("YES");
    }

    /**
     * Finds the index of an array where the value is > 1.
     * Returns -1 if none or more than one such index exists.
     */
    private static int findUniqueIndex(int[] counts, int length) {
        int uniqueIndex = -1;
        for (int i = 0; i < length; i++) {
            if (counts[i] > 1) {
                if (uniqueIndex != -1) {
                    return -1; // Multiple rows/cols have > 1 star
                }
                uniqueIndex = i;
            }
        }
        return uniqueIndex;
    }

    /**
     * Validates that the grid consists of exactly one full row and one full column
     * crossing at (crossRow, crossCol), with stars extending in all 4 directions
     * and no stray stars remaining.
     */
    private static boolean validatePattern(boolean[][] grid, int crossRow, int crossCol, int h, int w) {
        // Check all 4 directions from the intersection
        if (!clearAndCheckDirection(grid, crossRow, crossCol, -1, 0, h, w)) return false; // Up
        if (!clearAndCheckDirection(grid, crossRow, crossCol, 1, 0, h, w)) return false;  // Down
        if (!clearAndCheckDirection(grid, crossRow, crossCol, 0, -1, h, w)) return false; // Left
        if (!clearAndCheckDirection(grid, crossRow, crossCol, 0, 1, h, w)) return false;  // Right

        // Ensure no stars remain outside the cleared lines
        for (int i = 0; i < h; i++) {
            for (int j = 0; j < w; j++) {
                if (grid[i][j]) {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Traverses in a given direction from the starting cell, clearing stars.
     * Returns true if at least one star was found and cleared in that direction.
     */
    private static boolean clearAndCheckDirection(boolean[][] grid, int r, int c, int dr, int dc, int h, int w) {
        int nr = r + dr;
        int nc = c + dc;
        boolean found = false;
        while (nr >= 0 && nr < h && nc >= 0 && nc < w) {
            if (grid[nr][nc]) {
                grid[nr][nc] = false;
                found = true;
            } else {
                break;
            }
            nr += dr;
            nc += dc;
        }
        return found;
    }

    /**
     * High-performance scanner for competitive programming.
     */
    private static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1024];
        private int ptr = 0;
        private int buflen = 0;

        private boolean hasNextByte() {
            if (ptr < buflen) {
                return true;
            }
            ptr = 0;
            try {
                buflen = in.read(buffer);
            } catch (IOException e) {
                e.printStackTrace();
            }
            return buflen > 0;
        }

        private int readByte() {
            return hasNextByte() ? buffer[ptr++] : -1;
        }

        private static boolean isPrintableChar(int c) {
            return c >= 33 && c <= 126;
        }

        private void skipUnprintable() {
            while (hasNextByte() && !isPrintableChar(buffer[ptr])) {
                ptr++;
            }
        }

        public boolean hasNext() {
            skipUnprintable();
            return hasNextByte();
        }

        public String next() {
            if (!hasNext()) throw new NoSuchElementException();
            StringBuilder sb = new StringBuilder();
            int b = readByte();
            while (isPrintableChar(b)) {
                sb.appendCodePoint(b);
                b = readByte();
            }
            return sb.toString();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        // Read dimensions
        if (!scanner.hasNextInt()) {
            scanner.close();
            return;
        }
        int height = scanner.nextInt();
        int width = scanner.nextInt();
        scanner.nextLine(); // Consume the newline character after the integers

        // Grid to store the map: true for '*', false otherwise
        boolean[][] grid = new boolean[height][width];
        int totalStars = 0;

        // Read the grid content
        for (int i = 0; i < height; i++) {
            String line = scanner.nextLine();
            for (int j = 0; j < width; j++) {
                // Ensure we don't go out of bounds if line is shorter than width
                if (j < line.length() && line.charAt(j) == '*') {
                    grid[i][j] = true;
                    totalStars++;
                }
            }
        }

        // Find the center of the cross
        // A valid center must have '*' and its immediate neighbors (up, down, left, right) must be '*'
        int centerRow = -1;
        int centerCol = -1;

        // Iterate from 1 to height-2 and 1 to width-2 to ensure neighbors exist
        searchCenter:
        for (int r = 1; r < height - 1; r++) {
            for (int c = 1; c < width - 1; c++) {
                if (grid[r][c] &&
                    grid[r - 1][c] && grid[r + 1][c] &&
                    grid[r][c - 1] && grid[r][c + 1]) {
                    centerRow = r;
                    centerCol = c;
                    break searchCenter;
                }
            }
        }

        // If no center is found, the shape cannot be a valid cross
        if (centerRow == -1) {
            System.out.println("NO");
            scanner.close();
            return;
        }

        // Validate the shape
        // 1. Check if the row containing the center has contiguous stars
        if (!isContiguousLine(grid, centerRow, 0, width, true)) {
            System.out.println("NO");
            scanner.close();
            return;
        }

        // 2. Check if the column containing the center has contiguous stars
        if (!isContiguousLine(grid, centerCol, 0, height, false)) {
            System.out.println("NO");
            scanner.close();
            return;
        }

        // 3. Check if the total number of stars matches the cross shape count
        // The cross consists of stars in the center row and center column.
        // We count stars in the row, then add stars in the column (excluding the center overlap).
        int crossStarCount = 0;

        // Count stars in the center row
        for (int c = 0; c < width; c++) {
            if (grid[centerRow][c]) {
                crossStarCount++;
            }
        }

        // Count stars in the center column (excluding the center cell to avoid double counting)
        for (int r = 0; r < height; r++) {
            if (r != centerRow && grid[r][centerCol]) {
                crossStarCount++;
            }
        }

        if (crossStarCount == totalStars) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }

        scanner.close();
    }

    /**
     * Checks if all '*' characters in a specific row or column are contiguous.
     * 
     * @param grid The 2D boolean array
     * @param lineIdx The index of the row (if isRow is true) or column (if isRow is false)
     * @param rangeStart Start index of the range to check
     * @param rangeEnd End index of the range to check
     * @param isRow True if checking a row (iterates columns), False if checking a column (iterates rows)
     * @return true if stars are contiguous, false otherwise
     */
    private static boolean isContiguousLine(boolean[][] grid, int lineIdx, int rangeStart, int rangeEnd, boolean isRow) {
        int firstStar = -1;
        int lastStar = -1;

        // Find the first and last star in the line
        for (int i = rangeStart; i < rangeEnd; i++) {
            boolean isStar = isRow ? grid[lineIdx][i] : grid[i][lineIdx];
            if (isStar) {
                if (firstStar == -1) {
                    firstStar = i;
                }
                lastStar = i;
            }
        }

        // If no stars found, it's technically contiguous (vacuously true).
        // In the context of this problem, a center implies stars must exist.
        if (firstStar == -1) {
            return true;
        }

        // Check if there are any gaps (false values) between the first and last star
        for (int i = firstStar; i <= lastStar; i++) {
            boolean isStar = isRow ? grid[lineIdx][i] : grid[i][lineIdx];
            if (!isStar) {
                return false;
            }
        }

        return true;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.OutputStream;
import java.io.PrintWriter;
import java.util.StringTokenizer;
import java.util.TreeSet;

public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);

        BPlusFromPicture solver = new BPlusFromPicture();
        solver.solve(in, out);

        out.close();
    }

    static class BPlusFromPicture {
        private static final String YES = "YES";
        private static final String NO = "NO";

        /**
         * Entry point for solving a single test case.
         */
        public void solve(InputReader in, PrintWriter out) {
            boolean isValid = validateGrid(in);
            out.println(isValid ? YES : NO);
        }

        /**
         * Reads the grid dimensions and content, then validates the pattern.
         */
        private boolean validateGrid(InputReader in) {
            int h = in.nextInt();
            int w = in.nextInt();

            boolean[][] grid = new boolean[h][w];
            int totalStars = 0;

            for (int i = 0; i < h; i++) {
                String line = in.next();
                for (int j = 0; j < w; j++) {
                    boolean isStar = line.charAt(j) == '*';
                    grid[i][j] = isStar;
                    if (isStar) {
                        totalStars++;
                    }
                }
            }

            return verifyPattern(grid, h, w, totalStars);
        }

        /**
         * Core validation logic: checks row/col constraints, contiguity, intersection, and total count.
         */
        private boolean verifyPattern(boolean[][] grid, int h, int w, int totalStars) {
            int[] starsPerRow = countStarsPerDimension(grid, h, w, false);
            int[] starsPerCol = countStarsPerDimension(grid, h, w, true);

            int crossRow = findUniqueDimensionWithMultipleStars(starsPerRow);
            int crossCol = findUniqueDimensionWithMultipleStars(starsPerCol);

            if (crossRow == -1 || crossCol == -1) {
                return false;
            }

            if (!verifyContiguity(grid, crossRow, crossCol, h, w)) {
                return false;
            }

            if (!verifyIntersection(grid, crossRow, crossCol, h, w)) {
                return false;
            }

            return verifyTotalStarCount(totalStars, starsPerRow[crossRow], starsPerCol[crossCol]);
        }

        /**
         * Counts stars per row or per column.
         */
        private int[] countStarsPerDimension(boolean[][] grid, int h, int w, boolean byColumn) {
            int[] counts = new int[byColumn ? w : h];
            for (int i = 0; i < h; i++) {
                for (int j = 0; j < w; j++) {
                    if (grid[i][j]) {
                        counts[byColumn ? j : i]++;
                    }
                }
            }
            return counts;
        }

        /**
         * Finds the index of the single dimension (row or column) containing more than one star.
         * Returns -1 if none or multiple exist.
         */
        private int findUniqueDimensionWithMultipleStars(int[] counts) {
            int uniqueIndex = -1;
            for (int i = 0; i < counts.length; i++) {
                if (counts[i] > 1) {
                    if (uniqueIndex != -1) {
                        return -1; // More than one line with multiple stars violates the pattern
                    }
                    uniqueIndex = i;
                }
            }
            return uniqueIndex;
        }

        /**
         * Verifies that the stars in the cross row and cross column form contiguous blocks.
         */
        private boolean verifyContiguity(boolean[][] grid, int crossRow, int crossCol, int h, int w) {
            TreeSet<Integer> rowIndices = collectIndices(grid, crossRow, w, true);
            TreeSet<Integer> colIndices = collectIndices(grid, crossCol, h, false);

            return isContiguous(rowIndices) && isContiguous(colIndices);
        }

        /**
         * Collects indices of stars along a specific row or column.
         */
        private TreeSet<Integer> collectIndices(boolean[][] grid, int fixedIndex, int length, boolean isRow) {
            TreeSet<Integer> indices = new TreeSet<>();
            for (int i = 0; i < length; i++) {
                if (isRow ? grid[fixedIndex][i] : grid[i][fixedIndex]) {
                    indices.add(i);
                }
            }
            return indices;
        }

        /**
         * Checks if a set of integer indices forms a contiguous sequence.
         */
        private boolean isContiguous(TreeSet<Integer> indices) {
            if (indices.isEmpty()) {
                return false;
            }
            return (indices.last() - indices.first() + 1) == indices.size();
        }

        /**
         * Verifies that the horizontal and vertical lines intersect properly (cross internally, not at endpoints).
         */
        private boolean verifyIntersection(boolean[][] grid, int crossRow, int crossCol, int h, int w) {
            TreeSet<Integer> rowIndices = collectIndices(grid, crossRow, w, true);
            TreeSet<Integer> colIndices = collectIndices(grid, crossCol, h, false);

            // Ensure the lines cross internally, not at their endpoints
            if (rowIndices.first() == crossCol || rowIndices.last() == crossCol) {
                return false;
            }
            if (colIndices.first() == crossRow || colIndices.last() == crossRow) {
                return false;
            }

            // Verify that they actually intersect at the calculated cross point
            return grid[crossRow][crossCol];
        }

        /**
         * Validates that the total number of stars matches the expected count for a valid cross pattern.
         */
        private boolean verifyTotalStarCount(int totalStars, int rowStars, int colStars) {
            // Total stars should equal the sum of stars in the cross row and column, minus 1 for the intersection
            return totalStars == rowStars + colStars - 1;
        }
    }

    /**
     * Fast input reader for competitive programming / large I/O scenarios.
     */
    static class InputReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) {
                        return null;
                    }
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input", e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            String token = next();
            if (token == null) {
                throw new RuntimeException("Unexpected end of input");
            }
            return Integer.parseInt(token);
        }
    }
}

import java.io.BufferedReader;
import java.io.BufferedWriter;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.OutputStreamWriter;

public class CF_p2 {
    public static void main(String[] args) throws IOException {
        // Use try-with-resources for automatic and safe resource management
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
             BufferedWriter wr = new BufferedWriter(new OutputStreamWriter(System.out))) {

            String[] dimensions = br.readLine().trim().split("\\s+");
            int height = Integer.parseInt(dimensions[0]);
            int width = Integer.parseInt(dimensions[1]);

            char[][] grid = new char[height][width];
            for (int i = 0; i < height; i++) {
                String line = br.readLine();
                if (line != null) {
                    grid[i] = line.toCharArray();
                }
            }

            String result = solve(grid);
            wr.write(result);
        }
    }

    /**
     * Determines if the grid consists of exactly one cross.
     * Returns "YES" if the total number of '*' equals the size of the largest cross,
     * and at least one valid cross exists. Otherwise returns "NO".
     */
    private static String solve(char[][] grid) {
        int totalStars = countStars(grid);
        int maxCrossSize = findMaxCrossSize(grid);
        return (totalStars == maxCrossSize && maxCrossSize > 0) ? "YES" : "NO";
    }

    /**
     * Counts the total number of '*' characters in the grid.
     */
    private static int countStars(char[][] grid) {
        int count = 0;
        for (char[] row : grid) {
            for (char cell : row) {
                if (cell == '*') {
                    count++;
                }
            }
        }
        return count;
    }

    /**
     * Finds the size of the largest cross in the grid.
     * A cross is defined as a center '*' with at least one '*' in each of the four 
     * cardinal directions (up, down, left, right).
     */
    private static int findMaxCrossSize(char[][] grid) {
        int max = 0;
        int rows = grid.length;
        int cols = grid[0].length;

        // Only inner cells can be valid cross centers
        for (int i = 1; i < rows - 1; i++) {
            for (int j = 1; j < cols - 1; j++) {
                if (grid[i][j] == '*') {
                    int currentSize = calculateCrossSize(grid, i, j);
                    if (currentSize > max) {
                        max = currentSize;
                    }
                }
            }
        }
        return max;
    }

    /**
     * Calculates the total number of '*' forming a cross centered at (r, c).
     * Returns 0 if the center does not have '*' in all four immediate neighbors.
     */
    private static int calculateCrossSize(char[][] grid, int r, int c) {
        // A valid cross requires '*' in all 4 immediate directions from the center
        if (grid[r - 1][c] == '*' && grid[r + 1][c] == '*' &&
            grid[r][c - 1] == '*' && grid[r][c + 1] == '*') {

            int size = 1; // Center
            size += countConsecutiveStars(grid, r - 1, c, -1, 0); // Up
            size += countConsecutiveStars(grid, r + 1, c, 1, 0);  // Down
            size += countConsecutiveStars(grid, r, c - 1, 0, -1); // Left
            size += countConsecutiveStars(grid, r, c + 1, 0, 1);  // Right
            return size;
        }
        return 0;
    }

    /**
     * Counts consecutive '*' characters starting from (r, c) moving in direction (dr, dc).
     */
    private static int countConsecutiveStars(char[][] grid, int r, int c, int dr, int dc) {
        int count = 0;
        while (r >= 0 && r < grid.length && c >= 0 && c < grid[0].length && grid[r][c] == '*') {
            count++;
            r += dr;
            c += dc;
        }
        return count;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

public class GridPlusValidator {
    private final int height;
    private final int width;
    private final char[][] grid;

    public GridPlusValidator(int height, int width, char[][] grid) {
        this.height = height;
        this.width = width;
        this.grid = grid;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line = br.readLine();
        if (line == null) return;

        StringTokenizer st = new StringTokenizer(line);
        int h = Integer.parseInt(st.nextToken());
        int w = Integer.parseInt(st.nextToken());

        char[][] grid = new char[h][w];
        for (int i = 0; i < h; i++) {
            String row = br.readLine();
            if (row != null) {
                for (int j = 0; j < w && j < row.length(); j++) {
                    grid[i][j] = row.charAt(j);
                }
            }
        }

        GridPlusValidator validator = new GridPlusValidator(h, w, grid);
        System.out.println(validator.isValidPlusShape() ? "YES" : "NO");
    }

    /**
     * Determines if all stars in the grid form a valid plus shape.
     * A valid plus shape requires a center star with 4 orthogonal star neighbors,
     * and the total number of stars along all 4 axes must equal the grid's total star count.
     */
    public boolean isValidPlusShape() {
        if (height < 3 || width < 3) {
            return false;
        }

        int totalStars = countTotalStars();
        if (totalStars == 0) {
            return false;
        }

        int[] rowDeltas = {1, -1, 0, 0}; // Down, Up, Right, Left
        int[] colDeltas = {0, 0, 1, -1};

        for (int i = 1; i < height - 1; i++) {
            for (int j = 1; j < width - 1; j++) {
                if (isPotentialCenter(i, j)) {
                    int foundStars = 1; // Count the center star
                    for (int d = 0; d < 4; d++) {
                        foundStars += countStarsInDirection(i, j, rowDeltas[d], colDeltas[d]);
                    }
                    if (foundStars == totalStars) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    private boolean isPotentialCenter(int r, int c) {
        return grid[r][c] == '*' &&
               grid[r][c + 1] == '*' &&
               grid[r][c - 1] == '*' &&
               grid[r + 1][c] == '*' &&
               grid[r - 1][c] == '*';
    }

    private int countTotalStars() {
        int count = 0;
        for (char[] row : grid) {
            for (char cell : row) {
                if (cell == '*') {
                    count++;
                }
            }
        }
        return count;
    }

    /**
     * Iteratively counts consecutive stars in a specific direction starting from the neighbor.
     */
    private int countStarsInDirection(int startY, int startX, int rowDelta, int colDelta) {
        int count = 0;
        int y = startY + rowDelta;
        int x = startX + colDelta;

        while (y >= 0 && y < height && x >= 0 && x < width && grid[y][x] == '*') {
            count++;
            y += rowDelta;
            x += colDelta;
        }
        return count;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

/**
 * Refactored program to detect if a grid contains a cross pattern
 * that encompasses all star characters ('*').
 */
public class CrossPatternChecker {

    public static void main(String[] args) throws IOException {
        FastScanner scanner = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            // Read dimensions
            // Note: In a production environment, input validation should be more robust.
            String rowStr = scanner.next();
            if (rowStr == null) return;
            int rows = Integer.parseInt(rowStr);

            String colStr = scanner.next();
            if (colStr == null) return;
            int cols = Integer.parseInt(colStr);

            char[][] grid = new char[rows][cols];
            int totalStars = 0;

            // Read grid content and count total stars
            for (int i = 0; i < rows; i++) {
                String line = scanner.next();
                if (line != null) {
                    grid[i] = line.toCharArray();
                    for (char c : line.toCharArray()) {
                        if (c == '*') {
                            totalStars++;
                        }
                    }
                }
            }

            // Solve and output result
            boolean foundCross = solve(grid, rows, cols, totalStars);
            out.println(foundCross ? "YES" : "NO");

        } finally {
            out.flush();
        }
    }

    /**
     * Determines if a valid cross pattern exists that contains all stars in the grid.
     *
     * @param grid The 2D character array representing the map.
     * @param rows Number of rows in the grid.
     * @param cols Number of columns in the grid.
     * @param totalStars Total count of '*' characters in the grid.
     * @return true if a valid cross is found, false otherwise.
     */
    private static boolean solve(char[][] grid, int rows, int cols, int totalStars) {
        // A cross center cannot be on the border (index 0 or max-1) 
        // because it requires neighbors in all 4 directions.
        for (int i = 1; i < rows - 1; i++) {
            for (int j = 1; j < cols - 1; j++) {

                // The center of the cross must be a star
                if (grid[i][j] == '*') {

                    // Calculate arm lengths in all 4 directions
                    int verticalUp = countConsecutiveStars(grid, i - 1, j, -1, 0);
                    int verticalDown = countConsecutiveStars(grid, i + 1, j, 1, 0);
                    int horizontalLeft = countConsecutiveStars(grid, i, j - 1, 0, -1);
                    int horizontalRight = countConsecutiveStars(grid, i, j + 1, 0, 1);

                    // A valid cross must have at least one star in each direction
                    if (verticalUp > 0 && verticalDown > 0 && 
                        horizontalLeft > 0 && horizontalRight > 0) {

                        // Calculate total stars in this specific cross configuration
                        int crossStarCount = 1 + verticalUp + verticalDown + 
                                             horizontalLeft + horizontalRight;

                        // If the cross contains exactly all the stars in the grid, the condition is met.
                        if (crossStarCount == totalStars) {
                            return true;
                        }
                    }
                }
            }
        }
        return false;
    }

    /**
     * Counts consecutive stars starting from a position in a specific direction.
     *
     * @param grid The grid.
     * @param r Starting row index.
     * @param c Starting column index.
     * @param dr Row direction increment (-1, 0, 1).
     * @param dc Column direction increment (-1, 0, 1).
     * @return Number of consecutive stars found.
     */
    private static int countConsecutiveStars(char[][] grid, int r, int c, int dr, int dc) {
        int count = 0;
        int currR = r;
        int currC = c;

        // Check bounds and if the current cell is a star
        while (currR >= 0 && currR < grid.length && 
               currC >= 0 && currC < grid[0].length && 
               grid[currR][currC] == '*') {
            count++;
            currR += dr;
            currC += dc;
        }
        return count;
    }

    /**
     * Helper class for fast input reading.
     */
    private static class FastScanner {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastScanner(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
            tokenizer = new StringTokenizer("");
        }

        public String next() throws IOException {
            while (!tokenizer.hasMoreTokens()) {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            String s = next();
            if (s == null) throw new IOException("Unexpected end of input");
            return Integer.parseInt(s);
        }
    }
}

import java.util.Scanner;

/**
 * A class to validate if a given grid of characters contains a specific star cross pattern.
 * The pattern consists of a central star surrounded by stars in all 4 cardinal directions,
 * extending to form a solid cross shape with no other stars present.
 */
public class StarCrossChecker {

    private final char[][] grid;
    private final int height;
    private final int width;

    /**
     * Constructs a StarCrossChecker with the given grid dimensions and data.
     *
     * @param height The number of rows in the grid.
     * @param width  The number of columns in the grid.
     * @param grid   The 2D character array representing the grid.
     */
    public StarCrossChecker(int height, int width, char[][] grid) {
        this.height = height;
        this.width = width;
        this.grid = grid;
    }

    /**
     * Determines if the grid contains a valid star cross pattern.
     *
     * @return true if a valid star cross is found, false otherwise.
     */
    public boolean isValidStarCross() {
        // 1. Locate the center of the cross
        // The center must be a star surrounded by stars in all 4 directions.
        int[] center = findCenterStar();
        if (center == null) {
            return false;
        }

        int centerRow = center[0];
        int centerCol = center[1];

        // 2. Determine the boundaries of the star cluster along the axes
        // Find the extent of stars on the horizontal axis (row)
        int leftmostCol = findLeftmostStarIndex(centerRow);
        int rightmostCol = findRightmostStarIndex(centerRow);

        // Find the extent of stars on the vertical axis (column)
        int topmostRow = findTopmostStarIndex(centerCol);
        int bottommostRow = findBottommostStarIndex(centerCol);

        // 3. Verify that the horizontal arm is solid (no gaps)
        // Check if all cells strictly between leftmost and rightmost on the center row are stars.
        if (!isSolidHorizontal(centerRow, leftmostCol + 1, rightmostCol)) {
            return false;
        }

        // 4. Verify that the vertical arm is solid (no gaps)
        // Check if all cells strictly between topmost and bottommost on the center column are stars.
        if (!isSolidVertical(centerCol, topmostRow + 1, bottommostRow)) {
            return false;
        }

        // 5. Verify that there are no stars outside the cross shape
        // Stars are only allowed on the center row or center column.
        if (hasStarsOutsideCross(centerRow, centerCol)) {
            return false;
        }

        return true;
    }

    /**
     * Scans the grid to find a star that is surrounded by stars in all 4 cardinal directions.
     *
     * @return An integer array {row, col} representing the center coordinates, or null if not found.
     */
    private int[] findCenterStar() {
        // A center requires neighbors, so grid must be at least 3x3
        if (height < 3 || width < 3) {
            return null;
        }

        for (int i = 1; i < height - 1; i++) {
            for (int j = 1; j < width - 1; j++) {
                if (grid[i][j] == '*'
                        && grid[i - 1][j] == '*'
                        && grid[i + 1][j] == '*'
                        && grid[i][j - 1] == '*'
                        && grid[i][j + 1] == '*') {
                    return new int[]{i, j};
                }
            }
        }
        return null;
    }

    /**
     * Finds the column index of the first star encountered from the left on a specific row.
     *
     * @param row The row index to search.
     * @return The column index of the leftmost star, or -1 if none found.
     */
    private int findLeftmostStarIndex(int row) {
        for (int j = 0; j < width; j++) {
            if (grid[row][j] == '*') {
                return j;
            }
        }
        return -1;
    }

    /**
     * Finds the column index of the first star encountered from the right on a specific row.
     *
     * @param row The row index to search.
     * @return The column index of the rightmost star, or -1 if none found.
     */
    private int findRightmostStarIndex(int row) {
        for (int j = width - 1; j >= 0; j--) {
            if (grid[row][j] == '*') {
                return j;
            }
        }
        return -1;
    }

    /**
     * Finds the row index of the first star encountered from the top on a specific column.
     *
     * @param col The column index to search.
     * @return The row index of the topmost star, or -1 if none found.
     */
    private int findTopmostStarIndex(int col) {
        for (int i = 0; i < height; i++) {
            if (grid[i][col] == '*') {
                return i;
            }
        }
        return -1;
    }

    /**
     * Finds the row index of the first star encountered from the bottom on a specific column.
     *
     * @param col The column index to search.
     * @return The row index of the bottommost star, or -1 if none found.
     */
    private int findBottommostStarIndex(int col) {
        for (int i = height - 1; i >= 0; i--) {
            if (grid[i][col] == '*') {
                return i;
            }
        }
        return -1;
    }

    /**
     * Checks if a horizontal segment of the grid is filled with stars.
     *
     * @param row       The row index.
     * @param startCol  The starting column index (inclusive).
     * @param endCol    The ending column index (exclusive).
     * @return true if all cells between startCol and endCol are stars, false otherwise.
     */
    private boolean isSolidHorizontal(int row, int startCol, int endCol) {
        if (startCol >= endCol) {
            return true;
        }
        for (int j = startCol; j < endCol; j++) {
            if (grid[row][j] == '.') {
                return false;
            }
        }
        return true;
    }

    /**
     * Checks if a vertical segment of the grid is filled with stars.
     *
     * @param col        The column index.
     * @param startRow   The starting row index (inclusive).
     * @param endRow     The ending row index (exclusive).
     * @return true if all cells between startRow and endRow are stars, false otherwise.
     */
    private boolean isSolidVertical(int col, int startRow, int endRow) {
        if (startRow >= endRow) {
            return true;
        }
        for (int i = startRow; i < endRow; i++) {
            if (grid[i][col] == '.') {
                return false;
            }
        }
        return true;
    }

    /**
     * Checks if there are any stars in the grid that do not belong to the cross shape.
     * Stars are only allowed on the center row or center column.
     *
     * @param centerRow The row index of the center.
     * @param centerCol The column index of the center.
     * @return true if invalid stars are found, false if the grid is clean.
     */
    private boolean hasStarsOutsideCross(int centerRow, int centerCol) {
        for (int i = 0; i < height; i++) {
            for (int j = 0; j < width; j++) {
                if (grid[i][j] == '*') {
                    // A star is valid only if it lies on the central row or central column
                    if (i != centerRow && j != centerCol) {
                        return true; // Found an invalid star
                    }
                }
            }
        }
        return false;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        // Reading dimensions
        if (sc.hasNextInt()) {
            int h = sc.nextInt();
            int w = sc.nextInt();

            char[][] matrix = new char[h][w];

            // Reading the grid
            for (int i = 0; i < h; i++) {
                String line = sc.next();
                for (int j = 0; j < w; j++) {
                    matrix[i][j] = line.charAt(j);
                }
            }

            // Performing validation
            StarCrossChecker checker = new StarCrossChecker(h, w, matrix);
            if (checker.isValidStarCross()) {
                System.out.println("YES");
            } else {
                System.out.println("NO");
            }
        }

        sc.close();
    }
}

import java.util.Scanner;

/**
 * Refactored version of PlusFromPicture.
 * 
 * Improvements made:
 * 1. Separation of Concerns: Logic is divided into distinct methods (reading input, 
 *    checking for a plus sign, removing it, and verifying emptiness).
 * 2. Readability: Variable names are descriptive (e.g., 'height', 'width', 'grid', 'row', 'col').
 * 3. Maintainability: Magic numbers are replaced with logic or constants where appropriate.
 * 4. Resource Management: Uses try-with-resources for the Scanner to ensure it is closed properly.
 * 5. Robustness: Added checks for input validity and array boundaries.
 */
public class PlusFromPicture {

    private static final char EMPTY_CELL = '.';

    public static void main(String[] args) {
        // Use try-with-resources to ensure the Scanner is closed automatically
        try (Scanner scanner = new Scanner(System.in)) {

            // 1. Read Dimensions
            if (!scanner.hasNextInt()) return;
            int height = scanner.nextInt();
            int width = scanner.nextInt();
            scanner.nextLine(); // Consume the newline character after the integers

            // 2. Read Grid
            char[][] grid = new char[height][width];
            boolean hasBlocks = false;

            for (int i = 0; i < height; i++) {
                if (scanner.hasNextLine()) {
                    String line = scanner.nextLine();
                    // Safety check to prevent IndexOutOfBounds if line is shorter than width
                    for (int j = 0; j < width && j < line.length(); j++) {
                        grid[i][j] = line.charAt(j);
                        if (grid[i][j] != EMPTY_CELL) {
                            hasBlocks = true;
                        }
                    }
                }
            }

            // 3. Process Logic
            // If the grid is completely empty, it cannot contain a plus sign.
            if (!hasBlocks) {
                System.out.println("NO");
                return;
            }

            boolean plusFound = false;

            // 4. Search for the center of the plus sign
            // A plus center cannot be on the border (indices 0 or max-1)
            for (int r = 1; r < height - 1; r++) {
                for (int c = 1; c < width - 1; c++) {
                    if (isPlusCenter(grid, r, c)) {
                        // Found a valid center, erase the plus sign
                        removePlusSign(grid, r, c);
                        plusFound = true;
                        break; // We assume there is only one plus sign to remove
                    }
                }
                if (plusFound) break;
            }

            // 5. Verify Result
            // If we found a plus and the grid is now empty, the answer is YES.
            // Otherwise (no plus found, or residue remains), the answer is NO.
            if (plusFound && isGridEmpty(grid)) {
                System.out.println("YES");
            } else {
                System.out.println("NO");
            }

        } catch (Exception e) {
            // In a production environment, log the exception.
            e.printStackTrace();
        }
    }

    /**
     * Checks if the cell at (row, col) is the center of a plus sign.
     * A center must be filled and have filled neighbors in all 4 cardinal directions.
     */
    private static boolean isPlusCenter(char[][] grid, int row, int col) {
        // Check if current cell is filled
        if (grid[row][col] == EMPTY_CELL) {
            return false;
        }
        // Check neighbors (Up, Down, Left, Right)
        // Note: Bounds are implicitly safe because the caller iterates 1 to height-2
        if (grid[row - 1][col] == EMPTY_CELL) return false; // Up
        if (grid[row + 1][col] == EMPTY_CELL) return false; // Down
        if (grid[row][col - 1] == EMPTY_CELL) return false; // Left
        if (grid[row][col + 1] == EMPTY_CELL) return false; // Right

        return true;
    }

    /**
     * Removes the plus sign centered at (row, col) from the grid.
     * It clears the center and extends outwards in all 4 directions until 
     * it hits an empty cell or the grid boundary.
     */
    private static void removePlusSign(char[][] grid, int row, int col) {
        // Clear the center
        grid[row][col] = EMPTY_CELL;

        // Clear Vertical Arm (Up)
        int r = row;
        while (r > 0 && grid[r - 1][col] != EMPTY_CELL) {
            grid[r - 1][col] = EMPTY_CELL;
            r--;
        }

        // Clear Vertical Arm (Down)
        r = row;
        while (r < grid.length - 1 && grid[r + 1][col] != EMPTY_CELL) {
            grid[r + 1][col] = EMPTY_CELL;
            r++;
        }

        // Clear Horizontal Arm (Left)
        int c = col;
        while (c > 0 && grid[row][c - 1] != EMPTY_CELL) {
            grid[row][c - 1] = EMPTY_CELL;
            c--;
        }

        // Clear Horizontal Arm (Right)
        c = col;
        while (c < grid[0].length - 1 && grid[row][c + 1] != EMPTY_CELL) {
            grid[row][c + 1] = EMPTY_CELL;
            c++;
        }
    }

    /**
     * Checks if the entire grid is empty (contains only '.').
     */
    private static boolean isGridEmpty(char[][] grid) {
        for (char[] row : grid) {
            for (char cell : row) {
                if (cell != EMPTY_CELL) {
                    return false;
                }
            }
        }
        return true;
    }
}

