/**
 * Solves a grid pattern problem by detecting a specific cross configuration.
 * If a cross of '*' characters is found, it clears the contiguous '*' lines
 * extending from the center. If no '*' characters remain afterward, outputs "YES",
 * otherwise outputs "NO".
 */
public class Main {

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner();
        int rows = scanner.nextInt();
        int cols = scanner.nextInt();

        char[][] grid = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            grid[i] = scanner.next().toCharArray();
        }

        boolean crossFound = false;
        // Iterate through inner cells only, as a cross requires neighbors in all 4 directions
        for (int i = 1; i < rows - 1 && !crossFound; i++) {
            for (int j = 1; j < cols - 1 && !crossFound; j++) {
                if (isCrossCenter(grid, i, j)) {
                    clearCrossLines(grid, i, j, rows, cols);
                    crossFound = true;
                }
            }
        }

        if (crossFound && !gridContainsStars(grid, rows, cols)) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }
    }

    /**
     * Checks if the cell at (row, col) is the center of a cross.
     * A valid cross center requires '*' at the center and all four immediate neighbors.
     */
    private static boolean isCrossCenter(char[][] grid, int row, int col) {
        return grid[row][col] == '*'
            && grid[row - 1][col] == '*'
            && grid[row + 1][col] == '*'
            && grid[row][col - 1] == '*'
            && grid[row][col + 1] == '*';
    }

    /**
     * Clears contiguous '*' characters extending from the center in all four directions.
     * Stops clearing when a non-'*' character or grid boundary is encountered.
     */
    private static void clearCrossLines(char[][] grid, int centerRow, int centerCol, int rows, int cols) {
        // Clear upwards
        for (int i = centerRow - 1; i >= 0 && grid[i][centerCol] == '*'; i--) {
            grid[i][centerCol] = '.';
        }
        // Clear downwards
        for (int i = centerRow + 1; i < rows && grid[i][centerCol] == '*'; i++) {
            grid[i][centerCol] = '.';
        }
        // Clear leftwards
        for (int j = centerCol - 1; j >= 0 && grid[centerRow][j] == '*'; j--) {
            grid[centerRow][j] = '.';
        }
        // Clear rightwards
        for (int j = centerCol + 1; j < cols && grid[centerRow][j] == '*'; j++) {
            grid[centerRow][j] = '.';
        }
    }

    /**
     * Checks if any '*' characters remain in the grid.
     */
    private static boolean gridContainsStars(char[][] grid, int rows, int cols) {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == '*') {
                    return true;
                }
            }
        }
        return false;
    }

    /**
     * Efficient input scanner optimized for competitive programming environments.
     */
    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) {
                        return null;
                    }
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input", e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            String token = next();
            if (token == null) {
                throw new RuntimeException("Unexpected end of input");
            }
            return Integer.parseInt(token);
        }
    }
}

import java.util.Scanner;

/**
 * Validates a grid pattern based on specific traversal and connectivity rules.
 * Refactored for maintainability, readability, and code quality.
 */
public class GridPatternValidator {

    private static final String RESULT_YES = "YES";
    private static final String RESULT_NO = "NO";

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        // Safety check to prevent NoSuchElementException on empty input
        if (!scanner.hasNextInt()) {
            return;
        }

        int rows = scanner.nextInt();
        int cols = scanner.nextInt();
        scanner.nextLine(); // Consume the newline character left by nextInt()

        char[][] grid = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            String line = scanner.nextLine();
            grid[i] = line.toCharArray();
        }

        if (validateGrid(grid, rows, cols)) {
            System.out.println(RESULT_YES);
        } else {
            System.out.println(RESULT_NO);
        }
    }

    /**
     * Validates the grid pattern according to the original algorithm's logic.
     *
     * @param grid   The 2D character array representing the grid
     * @param rows   Number of rows
     * @param cols   Number of columns
     * @return true if the pattern is valid, false otherwise
     */
    private static boolean validateGrid(char[][] grid, int rows, int cols) {
        int firstStarRow = -1;
        int firstStarCol = -1;
        boolean foundFirstStar = false;

        // 1. Locate the first '*' (top-most, then left-most)
        outerLoop:
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '*') {
                    firstStarRow = r;
                    firstStarCol = c;
                    foundFirstStar = true;
                    break outerLoop;
                }
            }
        }

        // If no stars are found, the pattern is invalid
        if (!foundFirstStar) {
            return false;
        }

        // 2. Validate initial position constraints
        // Original logic checks immediate neighbors and boundaries

        // Cannot have a star to the left
        if (firstStarCol - 1 >= 0 && grid[firstStarRow][firstStarCol - 1] == '*') {
            return false;
        }
        // Cannot have a star to the right
        if (firstStarCol + 1 < cols && grid[firstStarRow][firstStarCol + 1] == '*') {
            return false;
        }
        // Cannot be in the last row (needs space below to continue pattern)
        if (firstStarRow + 1 == rows) {
            return false;
        }
        // Cannot be in the first or last column
        if (firstStarCol - 1 < 0 || firstStarCol + 1 == cols) {
            return false;
        }

        // 3. Traverse the vertical line of stars downwards
        boolean[][] visited = new boolean[rows][cols];
        visited[firstStarRow][firstStarCol] = true;

        int currentRow = firstStarRow + 1;
        int currentCol = firstStarCol;
        int verticalLength = 1; // Count includes the starting star
        boolean branchFound = false;
        int branchRowIndex = -1;

        // Move downwards as long as we encounter '*'
        while (currentRow < rows && grid[currentRow][currentCol] == '*') {
            // Check for horizontal neighbors to detect a branch point
            // We only care about the first branch point encountered (matching original 'f' flag logic)
            if (!branchFound && (grid[currentRow][currentCol - 1] == '*' || grid[currentRow][currentCol + 1] == '*')) {
                branchFound = true;
                branchRowIndex = currentRow;
            }

            visited[currentRow][currentCol] = true;
            currentRow++;
            verticalLength++;
        }

        // 4. Post-traversal validation
        // Original condition: length > 2 AND branch exists AND cell below branch is '*'
        if (verticalLength > 2 && branchFound && branchRowIndex + 1 < rows && grid[branchRowIndex + 1][currentCol] == '*') {

            // Scan the branch row horizontally to count and mark neighbors
            int leftCount = 0;
            int rightCount = 0;

            // Scan Left from the branch column
            int t = currentCol - 1;
            while (t >= 0 && grid[branchRowIndex][t] == '*') {
                leftCount++;
                visited[branchRowIndex][t] = true;
                t--;
            }

            // Scan Right from the branch column
            t = currentCol + 1;
            while (t < cols && grid[branchRowIndex][t] == '*') {
                rightCount++;
                visited[branchRowIndex][t] = true;
                t++;
            }

            // Must have stars on both sides of the branch point
            if (leftCount == 0 || rightCount == 0) {
                return false;
            }

            // 5. Final check: Ensure all '*' in the grid have been visited
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] == '*' && !visited[r][c]) {
                        return false;
                    }
                }
            }
            return true;

        } else {
            return false;
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

public class StarGridSolver {

    public static void main(String[] args) {
        FastReader reader = new FastReader();

        String nStr = reader.next();
        String mStr = reader.next();
        if (nStr == null || mStr == null) return;

        int n = Integer.parseInt(nStr);
        int m = Integer.parseInt(mStr);

        char[][] grid = new char[n][m];
        for (int i = 0; i < n; i++) {
            grid[i] = reader.next().toCharArray();
        }

        boolean foundCross = false;
        // Search for a '*' that has '*' neighbors in all 4 cardinal directions
        for (int i = 1; i < n - 1; i++) {
            for (int j = 1; j < m - 1; j++) {
                if (grid[i][j] == '*' &&
                    grid[i - 1][j] == '*' && grid[i + 1][j] == '*' &&
                    grid[i][j - 1] == '*' && grid[i][j + 1] == '*') {
                    clearCross(grid, i, j, n, m);
                    foundCross = true;
                    break;
                }
            }
            if (foundCross) break;
        }

        int remainingStars = countStars(grid, n, m);
        if (foundCross && remainingStars == 1) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }
    }

    /**
     * Clears the cross shape centered at (row, col) by replacing '*' with '.'
     * in all four cardinal directions until boundaries or non-'*' characters are reached.
     */
    private static void clearCross(char[][] grid, int row, int col, int n, int m) {
        // Clear upward
        for (int i = row - 1; i >= 0 && grid[i][col] == '*'; i--) {
            grid[i][col] = '.';
        }
        // Clear downward
        for (int i = row + 1; i < n && grid[i][col] == '*'; i++) {
            grid[i][col] = '.';
        }
        // Clear leftward
        for (int j = col - 1; j >= 0 && grid[row][j] == '*'; j--) {
            grid[row][j] = '.';
        }
        // Clear rightward
        for (int j = col + 1; j < m && grid[row][j] == '*'; j++) {
            grid[row][j] = '.';
        }
    }

    /**
     * Counts the total number of '*' characters remaining in the grid.
     */
    private static int countStars(char[][] grid, int n, int m) {
        int count = 0;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == '*') {
                    count++;
                }
            }
        }
        return count;
    }

    /**
     * Fast I/O helper class optimized for competitive programming.
     */
    private static class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        public String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input", e);
                }
            }
            return st.nextToken();
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

public class CrossPatternChecker {

    public static void main(String[] args) throws IOException {
        // Use try-with-resources to ensure streams are properly closed and flushed
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
             PrintWriter writer = new PrintWriter(System.out)) {

            String line = reader.readLine();
            if (line == null) return;

            StringTokenizer st = new StringTokenizer(line);
            if (!st.hasMoreTokens()) return;

            int rows = Integer.parseInt(st.nextToken());
            int cols = Integer.parseInt(st.nextToken());

            char[][] grid = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                String rowLine = reader.readLine();
                if (rowLine != null) {
                    // Safely copy characters, handling potential line length mismatches
                    int len = Math.min(rowLine.length(), cols);
                    for (int j = 0; j < len; j++) {
                        grid[i][j] = rowLine.charAt(j);
                    }
                }
            }

            int centerRow = -1;
            int centerCol = -1;
            boolean crossFound = false;

            // Scan the grid to find the center of the cross.
            // A valid center must be strictly inside the grid boundaries (not on the edge).
            outerLoop:
            for (int r = 1; r < rows - 1; r++) {
                for (int c = 1; c < cols - 1; c++) {
                    if (grid[r][c] == '*') {
                        // Check if all 4 immediate neighbors are '*'
                        // The original code validated neighbors in the scan (Top, Left) 
                        // and in the expansion loops (Bottom, Right). 
                        // We perform the full check here for clarity and efficiency.
                        if (grid[r - 1][c] == '*' && grid[r + 1][c] == '*' &&
                            grid[r][c - 1] == '*' && grid[r][c + 1] == '*') {

                            if (crossFound) {
                                // Original logic: If a second valid cross center is found, output NO
                                writer.println("NO");
                                return;
                            }

                            crossFound = true;
                            centerRow = r;
                            centerCol = c;
                        }
                    }
                }
            }

            if (!crossFound) {
                writer.println("NO");
                return;
            }

            boolean[][] isCovered = new boolean[rows][cols];

            // Directions: Up, Down, Left, Right
            int[] dRow = {-1, 1, 0, 0};
            int[] dCol = {0, 0, -1, 1};

            // Mark the cross centered at (centerRow, centerCol)
            // We traverse in all 4 directions from the center
            for (int k = 0; k < 4; k++) {
                int currR = centerRow;
                int currC = centerCol;

                // Mark the center cell
                isCovered[currR][currC] = true;

                // Move in the current direction
                int nextR = currR + dRow[k];
                int nextC = currC + dCol[k];

                // Traverse as long as we are within bounds and the cell is '*'
                while (nextR >= 0 && nextR < rows && nextC >= 0 && nextC < cols &&
                       grid[nextR][nextC] == '*') {
                    isCovered[nextR][nextC] = true;
                    nextR += dRow[k];
                    nextC += dCol[k];
                }
            }

            // Verify that every '*' in the grid is part of the marked cross
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] != '.' && !isCovered[r][c]) {
                        writer.println("NO");
                        return;
                    }
                }
            }

            writer.println("YES");
        }
    }
}

import java.io.InputStream;
import java.io.OutputStream;
import java.io.PrintWriter;
import java.util.Scanner;

public class Main {

    // Constant defining the minimum size for a valid cross shape
    private static final int MIN_CROSS_SIZE = 5;

    public static void main(String[] args) {
        // Setup standard I/O
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        Scanner in = new Scanner(inputStream);
        PrintWriter out = new PrintWriter(outputStream);

        // Run the solver
        solve(in, out);

        // Cleanup resources
        out.flush();
        out.close();
        in.close();
    }

    /**
     * Main logic to solve the problem.
     * Reads grid dimensions and content, then determines if the stars form a valid cross.
     */
    private static void solve(Scanner in, PrintWriter out) {
        // Read grid dimensions
        if (!in.hasNextInt()) return;
        int height = in.nextInt();
        int width = in.nextInt();

        char[][] grid = new char[height][width];
        int totalStars = 0;

        // Read the grid data
        for (int i = 0; i < height; i++) {
            if (in.hasNext()) {
                String row = in.next();
                for (int j = 0; j < width; j++) {
                    // Safe character access to prevent IndexOutOfBoundsException
                    // if the input string is shorter than the specified width
                    char cell = (j < row.length()) ? row.charAt(j) : ' ';
                    grid[i][j] = cell;
                    if (cell == '*') {
                        totalStars++;
                    }
                }
            }
        }

        boolean isCrossShape = false;

        // Iterate through potential centers of the cross.
        // A center cannot be on the boundary (index 0 or max) because it needs neighbors in all 4 directions.
        for (int i = 1; i < height - 1; i++) {
            for (int j = 1; j < width - 1; j++) {
                if (grid[i][j] == '*') {
                    // Check if this star is the center of a valid cross
                    int crossSize = calculateCrossSize(grid, i, j, height, width);

                    if (crossSize > 0) {
                        // A valid cross must have size >= 5 and contain ALL stars in the grid
                        if (crossSize >= MIN_CROSS_SIZE && crossSize == totalStars) {
                            isCrossShape = true;
                            break;
                        }
                    }
                }
            }
            if (isCrossShape) break;
        }

        if (isCrossShape) {
            out.println("YES");
        } else {
            out.println("NO");
        }
    }

    /**
     * Calculates the size of a cross centered at (r, c).
     * A valid cross requires contiguous stars in all 4 cardinal directions (Up, Down, Left, Right).
     *
     * @param grid The 2D grid
     * @param r    Row index of the center
     * @param c    Column index of the center
     * @param h    Grid height
     * @param w    Grid width
     * @return     The total number of stars in the cross shape, or 0 if invalid.
     */
    private static int calculateCrossSize(char[][] grid, int r, int c, int h, int w) {
        int size = 1; // Start with the center star

        // Check Right direction
        int countRight = 0;
        for (int k = c + 1; k < w; k++) {
            if (grid[r][k] == '*') {
                countRight++;
            } else {
                break;
            }
        }
        if (countRight == 0) return 0; // Invalid center: no right arm
        size += countRight;

        // Check Left direction
        int countLeft = 0;
        for (int k = c - 1; k >= 0; k--) {
            if (grid[r][k] == '*') {
                countLeft++;
            } else {
                break;
            }
        }
        if (countLeft == 0) return 0; // Invalid center: no left arm
        size += countLeft;

        // Check Down direction
        int countDown = 0;
        for (int k = r + 1; k < h; k++) {
            if (grid[k][c] == '*') {
                countDown++;
            } else {
                break;
            }
        }
        if (countDown == 0) return 0; // Invalid center: no down arm
        size += countDown;

        // Check Up direction
        int countUp = 0;
        for (int k = r - 1; k >= 0; k--) {
            if (grid[k][c] == '*') {
                countUp++;
            } else {
                break;
            }
        }
        if (countUp == 0) return 0; // Invalid center: no up arm
        size += countUp;

        return size;
    }
}

import java.io.*;
import java.util.*;

public class Main {
    // Direction vectors: Down, Right, Up, Left
    private static final int[] DR = {1, 0, -1, 0};
    private static final int[] DC = {0, 1, 0, -1};

    public static void main(String[] args) {
        FastReader reader = new FastReader();
        PrintWriter out = new PrintWriter(System.out);

        try {
            // Read number of test cases. Falls back to 1 if input is empty.
            String tStr = reader.next();
            int t = (tStr != null) ? Integer.parseInt(tStr) : 1;

            while (t-- > 0) {
                int n = reader.nextInt();
                int m = reader.nextInt();
                char[][] grid = new char[n][m];
                for (int i = 0; i < n; i++) {
                    grid[i] = reader.next().toCharArray();
                }

                out.println(solve(grid, n, m) ? "YES" : "NO");
            }
        } catch (Exception e) {
            out.println("Error: " + e.getMessage());
        } finally {
            out.flush();
        }
    }

    /**
     * Validates the grid according to the problem rules.
     */
    private static boolean solve(char[][] grid, int n, int m) {
        int starRow = findRowWithMaxStars(grid, n, m);
        int starCol = findColWithMaxStars(grid, n, m);

        // If no stars exist in the grid
        if (starRow == -1 || starCol == -1) {
            return false;
        }

        // The intersection of the max row and max col must be a star
        if (grid[starRow][starCol] != '*') {
            return false;
        }

        // All four cardinal directions must contain at least one star
        for (int k = 0; k < 4; k++) {
            if (!hasStarInDirection(grid, n, m, starRow, starCol, DR[k], DC[k])) {
                return false;
            }
        }

        // After satisfying directional constraints, no stars should remain
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == '*') {
                    return false;
                }
            }
        }

        return true;
    }

    /**
     * Finds the index of the row with the maximum number of stars.
     */
    private static int findRowWithMaxStars(char[][] grid, int n, int m) {
        int maxCount = -1;
        int maxIndex = -1;
        for (int i = 0; i < n; i++) {
            int count = 0;
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == '*') count++;
            }
            if (count > maxCount) {
                maxCount = count;
                maxIndex = i;
            }
        }
        return maxIndex;
    }

    /**
     * Finds the index of the column with the maximum number of stars.
     */
    private static int findColWithMaxStars(char[][] grid, int n, int m) {
        int maxCount = -1;
        int maxIndex = -1;
        for (int j = 0; j < m; j++) {
            int count = 0;
            for (int i = 0; i < n; i++) {
                if (grid[i][j] == '*') count++;
            }
            if (count > maxCount) {
                maxCount = count;
                maxIndex = j;
            }
        }
        return maxIndex;
    }

    /**
     * Checks if there is at least one star in the given direction from (r, c).
     * Stops scanning when a non-star character or grid boundary is encountered.
     */
    private static boolean hasStarInDirection(char[][] grid, int n, int m, int r, int c, int dr, int dc) {
        for (int nr = r + dr, nc = c + dc; nr >= 0 && nr < n && nc >= 0 && nc < m; nr += dr, nc += dc) {
            if (grid[nr][nc] == '*') {
                return true;
            }
            if (grid[nr][nc] != '*') {
                break;
            }
        }
        return false;
    }

    // ==================== Utility Methods ====================

    static int gcd(int a, int b) {
        while (b != 0) {
            int temp = b;
            b = a % b;
            a = temp;
        }
        return a;
    }

    static boolean isPrime(int n) {
        if (n <= 1) return false;
        if (n == 2) return true;
        if (n % 2 == 0) return false;
        for (int i = 3; i <= Math.sqrt(n); i += 2) {
            if (n % i == 0) return false;
        }
        return true;
    }

    // ==================== Fast I/O ====================

    static class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input", e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            String s = next();
            if (s == null) throw new RuntimeException("Unexpected end of input");
            return Integer.parseInt(s);
        }

        long nextLong() {
            String s = next();
            if (s == null) throw new RuntimeException("Unexpected end of input");
            return Long.parseLong(s);
        }

        double nextDouble() {
            String s = next();
            if (s == null) throw new RuntimeException("Unexpected end of input");
            return Double.parseDouble(s);
        }
    }
}

import java.io.IOException;
import java.io.InputStream;

public class Solution {

    public static void main(String[] args) throws IOException {
        FastReader reader = new FastReader(System.in);
        int rows = reader.nextInt();
        int cols = reader.nextInt();

        char[][] grid = readGrid(reader, rows, cols);

        boolean hasStars = hasAnyStar(grid);
        if (!hasStars) {
            System.out.println("NO");
            return;
        }

        boolean isCompleteCross = isCompleteCross(grid);
        System.out.println(isCompleteCross ? "YES" : "NO");
    }

    /**
     * Reads the character grid from the input stream.
     */
    private static char[][] readGrid(FastReader reader, int rows, int cols) {
        char[][] grid = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                grid[i][j] = reader.nextChar();
            }
        }
        return grid;
    }

    /**
     * Checks if the grid contains at least one '*' character.
     */
    private static boolean hasAnyStar(char[][] grid) {
        for (char[] row : grid) {
            for (char cell : row) {
                if (cell == '*') {
                    return true;
                }
            }
        }
        return false;
    }

    /**
     * Determines if all '*' characters form a single contiguous cross shape.
     */
    private static boolean isCompleteCross(char[][] grid) {
        int rows = grid.length;
        int cols = grid[0].length;
        boolean[][] marked = new boolean[rows][cols];
        boolean foundCenter = false;

        // Find the first valid cross center
        outerLoop:
        for (int i = 1; i < rows - 1; i++) {
            for (int j = 1; j < cols - 1; j++) {
                if (isCrossCenter(grid, i, j)) {
                    markCrossSegments(grid, marked, i, j);
                    foundCenter = true;
                    break outerLoop;
                }
            }
        }

        // If no center was found, or all stars are not part of the marked cross
        return foundCenter && allStarsAreMarked(grid, marked);
    }

    /**
     * Checks if a cell is the center of a cross (has '*' in all 4 cardinal directions).
     */
    private static boolean isCrossCenter(char[][] grid, int r, int c) {
        return grid[r][c] == '*'
                && grid[r - 1][c] == '*'
                && grid[r + 1][c] == '*'
                && grid[r][c - 1] == '*'
                && grid[r][c + 1] == '*';
    }

    /**
     * Marks contiguous '*' segments vertically and horizontally from the center.
     */
    private static void markCrossSegments(char[][] grid, boolean[][] marked, int centerR, int centerC) {
        // Mark vertical segment
        for (int i = centerR; i < grid.length; i++) {
            if (grid[i][centerC] != '*') break;
            marked[i][centerC] = true;
        }
        for (int i = centerR - 1; i >= 0; i--) {
            if (grid[i][centerC] != '*') break;
            marked[i][centerC] = true;
        }

        // Mark horizontal segment
        for (int j = centerC; j < grid[0].length; j++) {
            if (grid[centerR][j] != '*') break;
            marked[centerR][j] = true;
        }
        for (int j = centerC - 1; j >= 0; j--) {
            if (grid[centerR][j] != '*') break;
            marked[centerR][j] = true;
        }
    }

    /**
     * Verifies that every '*' in the grid has been marked.
     */
    private static boolean allStarsAreMarked(char[][] grid, boolean[][] marked) {
        for (int i = 0; i < grid.length; i++) {
            for (int j = 0; j < grid[0].length; j++) {
                if (grid[i][j] == '*' && !marked[i][j]) {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * High-performance input reader for competitive programming scenarios.
     */
    static class FastReader {
        private final byte[] buffer = new byte[2048];
        private int bufferIndex, bytesRead;
        private final InputStream inputStream;

        FastReader(InputStream inputStream) {
            this.inputStream = inputStream;
        }

        private int readByte() throws IOException {
            if (bufferIndex >= bytesRead) {
                bufferIndex = 0;
                bytesRead = inputStream.read(buffer);
                if (bytesRead <= 0) {
                    return -1;
                }
            }
            return buffer[bufferIndex++];
        }

        private boolean isWhitespace(int c) {
            return c <= 32;
        }

        public String next() throws IOException {
            int c = readByte();
            while (isWhitespace(c) && c != -1) {
                c = readByte();
            }
            StringBuilder sb = new StringBuilder();
            while (!isWhitespace(c) && c != -1) {
                sb.append((char) c);
                c = readByte();
            }
            return sb.toString();
        }

        public String nextLine() throws IOException {
            int c = readByte();
            while (isWhitespace(c) && c != -1) {
                c = readByte();
            }
            StringBuilder sb = new StringBuilder();
            while (c != '\n' && c != '\r' && c != -1) {
                sb.append((char) c);
                c = readByte();
            }
            return sb.toString();
        }

        public char nextChar() throws IOException {
            int c = readByte();
            while (isWhitespace(c) && c != -1) {
                c = readByte();
            }
            return (char) c;
        }

        public int nextInt() throws IOException {
            int c = readByte();
            while (isWhitespace(c) && c != -1) {
                c = readByte();
            }
            boolean isNegative = c == '-';
            if (isNegative || c == '+') {
                c = readByte();
            }
            int result = 0;
            while (c >= '0' && c <= '9') {
                result = (result << 3) + (result << 1) + (c & 15);
                c = readByte();
            }
            return isNegative ? -result : result;
        }

        public long nextLong() throws IOException {
            int c = readByte();
            while (isWhitespace(c) && c != -1) {
                c = readByte();
            }
            boolean isNegative = c == '-';
            if (isNegative || c == '+') {
                c = readByte();
            }
            long result = 0;
            while (c >= '0' && c <= '9') {
                result = (result << 3) + (result << 1) + (c & 15);
                c = readByte();
            }
            return isNegative ? -result : result;
        }
    }
}

import java.util.Scanner;

/**
 * A program to analyze a grid of characters to determine if they form a specific
 * cross pattern. The grid must contain exactly one "plus" shape formed by '*' characters,
 * and all '*' characters in the grid must be part of this single cross.
 */
public class StarPatternChecker {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        // Read grid dimensions
        if (!scanner.hasNextInt()) return;
        int rows = scanner.nextInt();
        int cols = scanner.nextInt();

        char[][] grid = new char[rows][cols];

        // Read grid data
        for (int i = 0; i < rows; i++) {
            if (scanner.hasNext()) {
                String line = scanner.next();
                // Ensure we don't go out of bounds if input line is shorter than expected
                for (int j = 0; j < cols && j < line.length(); j++) {
                    grid[i][j] = line.charAt(j);
                }
            }
        }

        // Solve and print result
        boolean isValid = solve(grid, rows, cols);
        System.out.println(isValid ? "YES" : "NO");

        scanner.close();
    }

    /**
     * Main logic to validate the star pattern.
     */
    private static boolean solve(char[][] grid, int rows, int cols) {
        boolean[][] marked = new boolean[rows][cols];
        boolean centerFound = false;

        // Iterate through potential centers. 
        // A center cannot be on the border (index 0 or rows-1) as it needs 4 neighbors.
        for (int r = 1; r < rows - 1; r++) {
            for (int c = 1; c < cols - 1; c++) {
                if (grid[r][c] == '*') {
                    if (isCrossCenter(grid, r, c)) {
                        if (centerFound) {
                            // If we find a second valid center, the pattern is invalid 
                            // (implies disjoint shapes or complex structures).
                            return false;
                        }
                        centerFound = true;
                        markCrossPattern(grid, r, c, marked);
                    }
                }
            }
        }

        // If no center was found, the grid does not contain the required pattern.
        if (!centerFound) {
            return false;
        }

        // Verify that every '*' in the grid has been marked by the cross pattern.
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '*' && !marked[r][c]) {
                    return false;
                }
            }
        }

        return true;
    }

    /**
     * Checks if the cell at (r, c) is the center of a cross.
     * A center must have '*' neighbors in all 4 cardinal directions.
     */
    private static boolean isCrossCenter(char[][] grid, int r, int c) {
        return grid[r - 1][c] == '*' &&
               grid[r + 1][c] == '*' &&
               grid[r][c - 1] == '*' &&
               grid[r][c + 1] == '*';
    }

    /**
     * Marks the center and the arms of the cross in the marked array.
     * It traces lines Up, Down, Left, and Right from the center as long as '*' is found.
     */
    private static void markCrossPattern(char[][] grid, int r, int c, boolean[][] marked) {
        // Mark the center
        marked[r][c] = true;

        // Directions: Up, Down, Left, Right
        int[] dr = {-1, 1, 0, 0};
        int[] dc = {0, 0, -1, 1};

        for (int k = 0; k < 4; k++) {
            int nr = r + dr[k];
            int nc = c + dc[k];

            // Traverse in the current direction as long as we are within bounds and see '*'
            while (isValid(nr, nc, grid.length, grid[0].length) && grid[nr][nc] == '*') {
                marked[nr][nc] = true;
                nr += dr[k];
                nc += dc[k];
            }
        }
    }

    /**
     * Checks if coordinates are within grid bounds.
     */
    private static boolean isValid(int r, int c, int rows, int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }
}

import java.util.Scanner;

public class TaskB {

    public static void main(String[] args) {
        // Use try-with-resources to ensure the Scanner is closed automatically
        try (Scanner scanner = new Scanner(System.in)) {
            if (!scanner.hasNextInt()) {
                return;
            }

            int rows = scanner.nextInt();
            int cols = scanner.nextInt();

            char[][] grid = new char[rows][cols];
            int firstStarRow = -1;
            int firstStarCol = -1;

            // 1. Read the grid and locate the first '*'
            for (int i = 0; i < rows; i++) {
                String rowString = scanner.next();
                for (int j = 0; j < cols; j++) {
                    grid[i][j] = rowString.charAt(j);
                    if (firstStarRow == -1 && grid[i][j] == '*') {
                        firstStarRow = i;
                        firstStarCol = j;
                    }
                }
            }

            int verticalSteps = 0;
            int horizontalStartRow = -1;
            int horizontalStartCol = -1;

            // 2. Traverse downwards from the first '*'
            int currentRow = firstStarRow;
            while (currentRow >= 0 && currentRow < rows && grid[currentRow][firstStarCol] == '*') {
                verticalSteps++;
                grid[currentRow][firstStarCol] = 'O'; // Mark as visited

                // Check for horizontal path eligibility
                if (horizontalStartRow == -1 && firstStarCol > 0 && firstStarCol + 1 < cols
                        && grid[currentRow][firstStarCol - 1] == '*' && grid[currentRow][firstStarCol + 1] == '*') {
                    if (!hasAdjacentDotVertically(grid, rows, currentRow, firstStarCol)) {
                        horizontalStartRow = currentRow;
                        horizontalStartCol = 0; // Start horizontal scan from column 0
                    }
                }
                currentRow++;
            }

            int horizontalSteps = 0;
            // 3. Traverse horizontally from the determined start point
            // Added defensive check to prevent ArrayIndexOutOfBoundsException if no valid start was found
            if (horizontalStartRow != -1 && horizontalStartCol >= 0 && horizontalStartCol < cols) {
                int currentCol = horizontalStartCol;
                while (currentCol >= 0 && currentCol < cols) {
                    char cell = grid[horizontalStartRow][currentCol];
                    if (cell == '*' || cell == 'O') {
                        grid[horizontalStartRow][currentCol] = 'O';
                        horizontalSteps++;
                    }
                    // Stop if we hit a '.' after marking at least one cell
                    if (horizontalSteps > 0 && cell == '.') {
                        break;
                    }
                    currentCol++;
                }
            }

            // 4. Evaluate and print result
            if (!hasStars(grid, rows, cols) && hasVisited(grid, rows, cols)
                    && verticalSteps > 0 && horizontalSteps > 0) {
                System.out.println("YES");
            } else {
                System.out.println("NO");
            }
        }
    }

    /**
     * Checks if the grid still contains any unvisited '*' characters.
     */
    private static boolean hasStars(char[][] grid, int rows, int cols) {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == '*') {
                    return true;
                }
            }
        }
        return false;
    }

    /**
     * Checks if the grid contains any visited 'O' characters.
     */
    private static boolean hasVisited(char[][] grid, int rows, int cols) {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == 'O') {
                    return true;
                }
            }
        }
        return false;
    }

    /**
     * Checks if there is a '.' directly above or below the specified cell.
     */
    private static boolean hasAdjacentDotVertically(char[][] grid, int rows, int row, int col) {
        return (row + 1 < rows && grid[row + 1][col] == '.')
                || (row - 1 >= 0 && grid[row - 1][col] == '.');
    }
}

import java.util.Scanner;

/**
 * Refactored version of the BEAUTGAR program.
 * 
 * Original Logic:
 * 1. Reads a grid of characters. '.' represents empty space (0), others represent blocks (1).
 * 2. Searches for a specific pattern: a block surrounded by blocks in all 4 cardinal directions.
 * 3. If found, it clears the block and the contiguous line of blocks extending from it in all 4 directions until a gap is hit.
 * 4. If the pattern was found and the entire grid is cleared (no blocks left), output "YES", else "NO".
 * 5. If the pattern was never found, output "NO".
 */
public class BeautifulGarden {

    // Constants to represent grid states
    private static final int EMPTY = 0;
    private static final int FILLED = 1;

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        // Read dimensions
        if (!scanner.hasNextInt()) {
            return;
        }
        int height = scanner.nextInt();
        int width = scanner.nextInt();

        // Initialize grid with padding.
        // Padding (size + 2) allows us to check boundaries without explicit index checks,
        // as the default int value (0) acts as a boundary wall.
        int[][] grid = new int[height + 2][width + 2];

        // Read input and populate grid
        // We iterate from 1 to height/width to utilize the padding at index 0 and height+1/width+1
        for (int i = 1; i <= height; i++) {
            if (scanner.hasNext()) {
                String row = scanner.next();
                for (int j = 1; j <= width; j++) {
                    // Map '.' to 0 (Empty) and any other character to 1 (Filled)
                    // Added bounds check for safety, though valid input is assumed
                    if (j - 1 < row.length()) {
                        grid[i][j] = (row.charAt(j - 1) == '.') ? EMPTY : FILLED;
                    }
                }
            }
        }

        boolean crossFound = false;

        // Search for the specific "Cross" pattern
        // A block (1) that has blocks (1) in all 4 neighbors (Up, Down, Left, Right)
        for (int i = 1; i <= height; i++) {
            for (int j = 1; j <= width; j++) {
                if (grid[i][j] == FILLED) {
                    // Check neighbors. Padding ensures we don't go out of bounds.
                    if (grid[i - 1][j] == FILLED && // Up
                        grid[i + 1][j] == FILLED && // Down
                        grid[i][j - 1] == FILLED && // Left
                        grid[i][j + 1] == FILLED) { // Right

                        crossFound = true;
                        clearCross(grid, i, j);
                        break; // Stop after finding the first valid cross
                    }
                }
            }
            if (crossFound) {
                break;
            }
        }

        // Determine result based on findings
        if (crossFound) {
            // If a cross was found, check if the grid is now completely empty
            if (isGridEmpty(grid, height, width)) {
                System.out.println("YES");
            } else {
                System.out.println("NO");
            }
        } else {
            // If no cross pattern was found, the answer is NO
            System.out.println("NO");
        }

        scanner.close();
    }

    /**
     * Clears the current cell and the contiguous line of blocks extending 
     * from it in all 4 cardinal directions until an empty cell (0) is reached.
     */
    private static void clearCross(int[][] grid, int r, int c) {
        // Clear the center block
        grid[r][c] = EMPTY;

        // Clear Right
        int col = c + 1;
        while (grid[r][col] == FILLED) {
            grid[r][col] = EMPTY;
            col++;
        }

        // Clear Left
        col = c - 1;
        while (grid[r][col] == FILLED) {
            grid[r][col] = EMPTY;
            col--;
        }

        // Clear Down
        int row = r + 1;
        while (grid[row][c] == FILLED) {
            grid[row][c] = EMPTY;
            row++;
        }

        // Clear Up
        row = r - 1;
        while (grid[row][c] == FILLED) {
            grid[row][c] = EMPTY;
            row--;
        }
    }

    /**
     * Checks if there are any filled blocks (1) remaining in the valid grid area.
     */
    private static boolean isGridEmpty(int[][] grid, int height, int width) {
        for (int i = 1; i <= height; i++) {
            for (int j = 1; j <= width; j++) {
                if (grid[i][j] == FILLED) {
                    return false;
                }
            }
        }
        return true;
    }
}

import java.util.Scanner;
import java.util.Arrays;

/**
 * A class to validate if a given grid represents a cross pattern.
 * 
 * The validation logic determines if the grid contains exactly one cross shape
 * that covers the entire grid. A cross is defined as a center cell with star ('*')
 * neighbors in all four cardinal directions (Up, Down, Left, Right), extending
 * contiguously from the center.
 */
public class CrossPatternChecker {

    private boolean[][] grid;
    private boolean[][] marked;
    private int rows;
    private int cols;

    /**
     * Constructor to initialize grid dimensions.
     *
     * @param rows The number of rows in the grid.
     * @param cols The number of columns in the grid.
     */
    public CrossPatternChecker(int rows, int cols) {
        this.rows = rows;
        this.cols = cols;
        this.grid = new boolean[rows][cols];
        this.marked = new boolean[rows][cols];
    }

    public static void main(String[] args) {
        // Use try-with-resources for automatic resource management of the Scanner
        try (Scanner scanner = new Scanner(System.in)) {
            if (!scanner.hasNextInt()) {
                return;
            }
            int h = scanner.nextInt();
            int w = scanner.nextInt();

            CrossPatternChecker checker = new CrossPatternChecker(h, w);
            checker.readGrid(scanner);

            boolean isValid = checker.validate();
            System.out.println(isValid ? "YES" : "NO");
        }
    }

    /**
     * Reads the grid configuration from the scanner input.
     *
     * @param scanner The Scanner instance reading input.
     */
    private void readGrid(Scanner scanner) {
        for (int i = 0; i < rows; i++) {
            if (scanner.hasNext()) {
                String rowStr = scanner.next();
                // Safely handle cases where input string might be shorter than expected width
                int len = Math.min(rowStr.length(), cols);
                for (int j = 0; j < len; j++) {
                    grid[i][j] = (rowStr.charAt(j) == '*');
                }
            }
        }
    }

    /**
     * Validates if the grid represents a valid cross pattern.
     * 
     * Algorithm:
     * 1. Find the first valid cross center in the grid.
     * 2. If a center is found, mark the corresponding cross shape in the 'marked' array.
     * 3. Check if the 'marked' array is identical to the 'grid' array.
     *    (This implies the grid must be exactly one cross and nothing else).
     *
     * @return true if the grid is a valid single cross, false otherwise.
     */
    private boolean validate() {
        int[] crossPos = findFirstCross();

        boolean crossFound = (crossPos != null);

        if (crossFound) {
            markCross(crossPos[0], crossPos[1]);
        }

        // The grid is valid if a cross was found AND the marked cross covers the entire grid
        return crossFound && Arrays.deepEquals(grid, marked);
    }

    /**
     * Scans the grid to find the first valid cross center.
     * 
     * @return An array {row, col} of the first valid center, or null if none found.
     */
    private int[] findFirstCross() {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (isCrossCenter(i, j)) {
                    return new int[]{i, j};
                }
            }
        }
        return null;
    }

    /**
     * Checks if the cell at (r, c) is a valid center of a cross.
     * A valid center requires the cell itself and its immediate neighbors 
     * in all 4 cardinal directions to be stars ('*').
     *
     * @param r Row index.
     * @param c Column index.
     * @return true if (r, c) is a valid cross center.
     */
    private boolean isCrossCenter(int r, int c) {
        // Check center
        if (!grid[r][c]) return false;

        // Check neighbors
        // Note: The original code had confusing naming where 'rightNonEmpty' checked 
        // the bottom neighbor (row index + 1) and 'bottomNonEmpty' checked the right neighbor.
        // This method uses semantically correct names to improve maintainability.
        return hasNeighborUp(r, c) &&
               hasNeighborDown(r, c) &&
               hasNeighborLeft(r, c) &&
               hasNeighborRight(r, c);
    }

    private boolean hasNeighborUp(int r, int c) {
        return r > 0 && grid[r - 1][c];
    }

    private boolean hasNeighborDown(int r, int c) {
        // Checks the cell below (increasing row index)
        return r < rows - 1 && grid[r + 1][c];
    }

    private boolean hasNeighborLeft(int r, int c) {
        return c > 0 && grid[r][c - 1];
    }

    private boolean hasNeighborRight(int r, int c) {
        // Checks the cell to the right (increasing column index)
        return c < cols - 1 && grid[r][c + 1];
    }

    /**
     * Marks the cross shape centered at (r, c) in the 'marked' array.
     * It marks contiguous stars extending from the center in all 4 directions.
     *
     * @param r Row index of the center.
     * @param c Column index of the center.
     */
    private void markCross(int r, int c) {
        // Mark vertical line (Up and Down)
        // Upwards
        for (int i = r; i >= 0 && grid[i][c]; i--) {
            marked[i][c] = true;
        }
        // Downwards (start from r + 1 to avoid redundant write to center)
        for (int i = r + 1; i < rows && grid[i][c]; i++) {
            marked[i][c] = true;
        }

        // Mark horizontal line (Left and Right)
        // Leftwards
        for (int j = c; j >= 0 && grid[r][j]; j--) {
            marked[r][j] = true;
        }
        // Rightwards (start from c + 1)
        for (int j = c + 1; j < cols && grid[r][j]; j++) {
            marked[r][j] = true;
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

/**
 * Validates if a grid of characters forms a specific cross pattern.
 * The pattern requires a central '*' with '*' neighbors in all 4 cardinal directions,
 * and all other '*'s in the grid must be connected to this center horizontally or vertically.
 */
public class StarCrossValidator {

    public static void main(String[] args) {
        FastReader scanner = new FastReader();

        // The original code supported multiple test cases but defaulted to false.
        // For maintainability, we run the validation once. 
        // If multiple test cases are required, this structure allows easy modification.
        solve(scanner);
    }

    /**
     * Handles input reading and triggers the validation logic.
     */
    private static void solve(FastReader in) {
        // Read dimensions
        String nStr = in.next();
        if (nStr == null) return; // Handle empty input gracefully
        int n = Integer.parseInt(nStr);
        int m = in.nextInt();

        // Read grid
        char[][] grid = new char[n][m];
        for (int i = 0; i < n; i++) {
            String rowStr = in.next();
            // Optimization: Convert string to char array directly
            if (rowStr != null) {
                grid[i] = rowStr.toCharArray();
            }
        }

        // Validate and print result
        if (validateGrid(grid)) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }
    }

    /**
     * Checks if the grid satisfies the star cross pattern requirements.
     * 
     * @param grid The character grid to validate.
     * @return true if the pattern is valid, false otherwise.
     */
    private static boolean validateGrid(char[][] grid) {
        int n = grid.length;
        if (n == 0) return false;
        int m = grid[0].length;

        int centerRow = -1;
        int centerCol = -1;
        boolean foundCenter = false;

        // 1. Find the intersection point (center)
        // The center must be strictly inside the grid (not on the border)
        // and must have '*' neighbors in all 4 directions.
        outerLoop:
        for (int i = 1; i < n - 1; i++) {
            for (int j = 1; j < m - 1; j++) {
                if (grid[i][j] == '*' &&
                    grid[i - 1][j] == '*' &&
                    grid[i + 1][j] == '*' &&
                    grid[i][j - 1] == '*' &&
                    grid[i][j + 1] == '*') {

                    centerRow = i;
                    centerCol = j;
                    foundCenter = true;
                    break outerLoop; // Found the first valid center
                }
            }
        }

        // If no valid center is found, the pattern cannot exist
        if (!foundCenter) {
            return false;
        }

        // 2. Mark all valid stars connected to the center
        // A star is valid if it lies on the same row or column as the center
        // and is connected contiguously to the center.
        boolean[][] isCovered = new boolean[n][m];

        // Mark Vertical Segment (Column centerCol)
        // Upwards from center
        for (int r = centerRow; r >= 0; r--) {
            if (grid[r][centerCol] == '*') {
                isCovered[r][centerCol] = true;
            } else {
                break; // Contiguous segment ends
            }
        }
        // Downwards from center
        for (int r = centerRow + 1; r < n; r++) {
            if (grid[r][centerCol] == '*') {
                isCovered[r][centerCol] = true;
            } else {
                break;
            }
        }

        // Mark Horizontal Segment (Row centerRow)
        // Leftwards from center
        for (int c = centerCol; c >= 0; c--) {
            if (grid[centerRow][c] == '*') {
                isCovered[centerRow][c] = true;
            } else {
                break;
            }
        }
        // Rightwards from center
        for (int c = centerCol + 1; c < m; c++) {
            if (grid[centerRow][c] == '*') {
                isCovered[centerRow][c] = true;
            } else {
                break;
            }
        }

        // 3. Verify that every '*' in the grid is covered
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == '*' && !isCovered[i][j]) {
                    return false;
                }
            }
        }

        return true;
    }

    /**
     * Fast I/O helper class for competitive programming or performance-critical input.
     */
    static class FastReader {
        BufferedReader br;
        StringTokenizer st;

        public FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    e.printStackTrace();
                    return null;
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            String s = next();
            return s == null ? 0 : Integer.parseInt(s);
        }

        long nextLong() {
            String s = next();
            return s == null ? 0L : Long.parseLong(s);
        }

        double nextDouble() {
            String s = next();
            return s == null ? 0.0 : Double.parseDouble(s);
        }

        char nextChar() {
            String s = next();
            return s == null ? 0 : s.charAt(0);
        }

        String nextLine() {
            String str = "";
            try {
                str = br.readLine();
            } catch (IOException e) {
                e.printStackTrace();
            }
            return str;
        }

        int[] nextIntArray(int n) {
            int[] arr = new int[n];
            for (int i = 0; i < n; i++) {
                arr[i] = nextInt();
            }
            return arr;
        }
    }
}

import java.util.Scanner;
import java.io.PrintWriter;
import java.io.BufferedOutputStream;

/**
 * Refactored version of PlusFromPicture.
 * 
 * Improvements made:
 * 1. Separation of Concerns: Logic is divided into methods (readGrid, solve, isCenter, markPlusShape).
 * 2. Naming Conventions: Variables and methods use descriptive names (e.g., 'height', 'width', 'isPartOfPlus').
 * 3. Readability: Loop bounds and logic are clearer. Magic numbers are minimized.
 * 4. Robustness: Resource management (flush/close) is handled explicitly.
 * 5. Algorithmic Clarity: The logic to find a center, expand it, and verify coverage is distinct.
 */
public class PlusShapeChecker {

    public static void main(String[] args) {
        // Initialize input and output streams
        Scanner scanner = new Scanner(System.in);
        // Using BufferedOutputStream for performance with PrintWriter
        PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out));

        // Read dimensions if input exists
        if (scanner.hasNextInt()) {
            int height = scanner.nextInt();
            int width = scanner.nextInt();

            // Read the grid data
            char[][] grid = readGrid(scanner, height, width);

            // Solve the problem and print result
            boolean isPlus = solve(height, width, grid);
            out.println(isPlus ? "YES" : "NO");
        }

        // Ensure output is written and resources are cleaned up
        out.flush();
        out.close();
        scanner.close();
    }

    /**
     * Reads the grid from the scanner.
     */
    private static char[][] readGrid(Scanner scanner, int height, int width) {
        char[][] grid = new char[height][width];
        for (int i = 0; i < height; i++) {
            String row = scanner.next();
            // Convert string to char array for easier access
            // Note: Assumes input string length matches width
            grid[i] = row.toCharArray();
        }
        return grid;
    }

    /**
     * Determines if the grid contains exactly one valid plus sign (+).
     */
    private static boolean solve(int height, int width, char[][] grid) {
        int centerRow = -1;
        int centerCol = -1;

        // 1. Locate the center of the plus.
        // A valid center must be surrounded by '*' in all 4 cardinal directions.
        // We skip the borders (1 to height-2) because a center cannot be on the edge.
        for (int i = 1; i < height - 1; i++) {
            for (int j = 1; j < width - 1; j++) {
                if (isCenter(grid, i, j)) {
                    centerRow = i;
                    centerCol = j;
                    break;
                }
            }
            // Optimization: If center found, stop searching
            if (centerRow != -1) {
                break;
            }
        }

        // If no center is found, it cannot be a plus.
        if (centerRow == -1) {
            return false;
        }

        // 2. Mark all cells that are part of the plus centered at (centerRow, centerCol).
        boolean[][] isPartOfPlus = new boolean[height][width];
        markPlusShape(grid, height, width, centerRow, centerCol, isPartOfPlus);

        // 3. Verify that every '*' in the grid is covered by the plus.
        // If there is any '*' that is not part of the marked plus, the shape is invalid.
        for (int i = 0; i < height; i++) {
            for (int j = 0; j < width; j++) {
                if (grid[i][j] == '*' && !isPartOfPlus[i][j]) {
                    return false;
                }
            }
        }

        return true;
    }

    /**
     * Checks if the cell at (r, c) is a valid center of a plus.
     */
    private static boolean isCenter(char[][] grid, int r, int c) {
        return grid[r][c] == '*' &&
               grid[r - 1][c] == '*' &&
               grid[r + 1][c] == '*' &&
               grid[r][c - 1] == '*' &&
               grid[r][c + 1] == '*';
    }

    /**
     * Marks the vertical and horizontal arms of the plus in the boolean matrix.
     */
    private static void markPlusShape(char[][] grid, int height, int width, int r, int c, boolean[][] isPartOfPlus) {
        // Mark vertical arm (upwards)
        for (int i = r; i >= 0 && grid[i][c] == '*'; i--) {
            isPartOfPlus[i][c] = true;
        }
        // Mark vertical arm (downwards)
        for (int i = r; i < height && grid[i][c] == '*'; i++) {
            isPartOfPlus[i][c] = true;
        }

        // Mark horizontal arm (leftwards)
        for (int j = c; j >= 0 && grid[r][j] == '*'; j--) {
            isPartOfPlus[r][j] = true;
        }
        // Mark horizontal arm (rightwards)
        for (int j = c; j < width && grid[r][j] == '*'; j++) {
            isPartOfPlus[r][j] = true;
        }
    }
}

import java.util.Scanner;

/**
 * Analyzes a grid to determine if it matches a specific cross-pattern criteria.
 * 
 * Logic preserved from original implementation:
 * 1. Identifies cells that are centers of a cross (filled cell with 4 filled neighbors).
 * 2. Calculates the size of the cross (center + length of 4 arms).
 * 3. Checks if the size of the *last found* cross equals the total number of filled cells.
 *    (Note: The original code reset the accumulator 'abs' for every center found, 
 *     effectively checking if the grid consists of exactly one cross shape).
 */
public class GridPatternAnalyzer {

    private static final int FILLED = 1;
    private static final int EMPTY = 0;

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        // Reading dimensions
        if (!scanner.hasNextInt()) {
            scanner.close();
            return;
        }
        int height = scanner.nextInt();
        int width = scanner.nextInt();

        // Consume the newline character left after nextInt()
        scanner.nextLine();

        int[][] grid = new int[height][width];
        int totalOnes = 0;

        // Reading the grid
        for (int i = 0; i < height; i++) {
            if (scanner.hasNextLine()) {
                String line = scanner.nextLine();
                char[] chars = line.toCharArray();

                for (int j = 0; j < width; j++) {
                    // Safe access to character array
                    char ch = (j < chars.length) ? chars[j] : EMPTY;

                    if (ch == '.') {
                        grid[i][j] = EMPTY;
                    } else {
                        grid[i][j] = FILLED;
                        totalOnes++;
                    }
                }
            }
        }

        // Original logic: if num == 0 return false
        if (totalOnes == 0) {
            System.out.println("NO");
        } else if (validateGrid(grid, width, height, totalOnes)) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }

        scanner.close();
    }

    /**
     * Validates if the grid satisfies the pattern logic.
     */
    public static boolean validateGrid(int[][] grid, int width, int height, int totalOnes) {
        int lastFoundCrossSize = 0;

        // Iterate through the inner grid (excluding borders)
        // Original bounds: i from 1 to h-2, j from 1 to w-2
        for (int i = 1; i < height - 1; i++) {
            for (int j = 1; j < width - 1; j++) {

                // Check if current cell is filled
                if (grid[i][j] == FILLED) {

                    // Check if all 4 immediate neighbors are filled
                    if (hasValidNeighbors(grid, i, j)) {
                        // If valid center, calculate size of this cross
                        // Original code: abs = 1; then adds arm lengths
                        int currentCrossSize = 1; // Count the center

                        // Add lengths of arms in all 4 directions
                        currentCrossSize += countArmLength(grid, i, j, -1, 0); // Up
                        currentCrossSize += countArmLength(grid, i, j, 1, 0);  // Down
                        currentCrossSize += countArmLength(grid, i, j, 0, -1); // Left
                        currentCrossSize += countArmLength(grid, i, j, 0, 1);  // Right

                        // Original logic: 'abs' variable was overwritten in each iteration
                        lastFoundCrossSize = currentCrossSize;
                    }
                }
            }
        }

        // Original check: if(abs==num)return true;
        return lastFoundCrossSize == totalOnes;
    }

    /**
     * Checks if the immediate neighbors (Up, Down, Left, Right) of a cell are filled.
     */
    private static boolean hasValidNeighbors(int[][] grid, int row, int col) {
        // Up
        if (grid[row - 1][col] != FILLED) return false;
        // Down
        if (grid[row + 1][col] != FILLED) return false;
        // Left
        if (grid[row][col - 1] != FILLED) return false;
        // Right
        if (grid[row][col + 1] != FILLED) return false;

        return true;
    }

    /**
     * Counts the length of a continuous line of filled cells starting from
     * (startRow, startCol) moving in direction (dr, dc).
     * 
     * Matches original logic: Move 1 step away from center, then count while cell is filled.
     */
    private static int countArmLength(int[][] grid, int startRow, int startCol, int dr, int dc) {
        int length = 0;
        int r = startRow + dr;
        int c = startCol + dc;

        // Boundary checks and value check
        while (r >= 0 && r < grid.length && c >= 0 && c < grid[0].length) {
            if (grid[r][c] == FILLED) {
                length++;
                r += dr;
                c += dc;
            } else {
                break;
            }
        }
        return length;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

/**
 * Refactored version of the original program.
 * 
 * Refactoring Improvements:
 * 1.  **Naming Conventions**: Renamed class to 'StarGridSolver' and variables to descriptive names (e.g., 'grid', 'height', 'width').
 * 2.  **Modularity**: Decomposed the monolithic 'main' method into smaller, single-responsibility methods:
 *     - 'solve': Orchestrates the logic.
 *     - 'isCrossCenter': Checks for the specific pattern.
 *     - 'removeCross': Handles the removal logic.
 *     - 'isGridEmpty': Validates the final state.
 * 3.  **Readability**: Removed nested variable swapping ('k', 'l') and replaced it with clear, linear loops.
 * 4.  **Constants**: Defined 'STAR' and 'EMPTY' characters to avoid magic characters.
 * 5.  **Resource Management**: Used try-with-resources for the BufferedReader to ensure proper closure.
 * 6.  **Safety**: Added basic null checks and length validations for input parsing.
 */
public class StarGridSolver {

    private static final char STAR = '*';
    private static final char EMPTY = '.';

    public static void main(String[] args) throws IOException {
        // Use try-with-resources for automatic resource management
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {

            // Read dimensions
            String line = br.readLine();
            if (line == null) return;

            StringTokenizer tokenizer = new StringTokenizer(line);
            if (!tokenizer.hasMoreTokens()) return;

            int height = Integer.parseInt(tokenizer.nextToken());
            int width = Integer.parseInt(tokenizer.nextToken());

            // Initialize grid
            char[][] grid = new char[height][width];

            // Read grid content
            for (int i = 0; i < height; i++) {
                String rowStr = br.readLine();
                // Safe parsing: handle potential short lines or null input
                if (rowStr != null) {
                    int len = Math.min(rowStr.length(), width);
                    for (int j = 0; j < len; j++) {
                        grid[i][j] = rowStr.charAt(j);
                    }
                }
            }

            // Execute logic
            boolean success = solve(grid, height, width);
            System.out.println(success ? "YES" : "NO");
        }
    }

    /**
     * Core logic: Finds a cross pattern, removes it, and checks if the grid is empty.
     */
    private static boolean solve(char[][] grid, int height, int width) {
        // Iterate through the inner cells. 
        // A cross center cannot be on the border (index 0 or max).
        for (int row = 1; row < height - 1; row++) {
            for (int col = 1; col < width - 1; col++) {

                // Check if current cell is the center of a cross
                if (isCrossCenter(grid, row, col)) {
                    // Remove the cross pattern
                    removeCross(grid, row, col);

                    // Check if any stars remain in the grid
                    return isGridEmpty(grid);
                }
            }
        }
        return false;
    }

    /**
     * Checks if the cell at (row, col) and its 4 immediate neighbors (Up, Down, Left, Right) are stars.
     */
    private static boolean isCrossCenter(char[][] grid, int row, int col) {
        return grid[row][col] == STAR &&
               grid[row - 1][col] == STAR && // Up
               grid[row + 1][col] == STAR && // Down
               grid[row][col - 1] == STAR && // Left
               grid[row][col + 1] == STAR;   // Right
    }

    /**
     * Removes the cross pattern centered at (row, col).
     * It clears the center and extends outwards in all 4 directions
     * as long as stars are encountered.
     */
    private static void removeCross(char[][] grid, int row, int col) {
        // Clear the center
        grid[row][col] = EMPTY;

        // Clear Horizontal Line (Right)
        int c = col + 1;
        while (c < grid[0].length && grid[row][c] == STAR) {
            grid[row][c] = EMPTY;
            c++;
        }

        // Clear Horizontal Line (Left)
        c = col - 1;
        while (c >= 0 && grid[row][c] == STAR) {
            grid[row][c] = EMPTY;
            c--;
        }

        // Clear Vertical Line (Down)
        int r = row + 1;
        while (r < grid.length && grid[r][col] == STAR) {
            grid[r][col] = EMPTY;
            r++;
        }

        // Clear Vertical Line (Up)
        r = row - 1;
        while (r >= 0 && grid[r][col] == STAR) {
            grid[r][col] = EMPTY;
            r--;
        }
    }

    /**
     * Checks if the grid contains any remaining stars.
     */
    private static boolean isGridEmpty(char[][] grid) {
        for (char[] row : grid) {
            for (char cell : row) {
                if (cell == STAR) {
                    return false;
                }
            }
        }
        return true;
    }
}

import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        if (!scanner.hasNextInt()) {
            return;
        }

        int h = scanner.nextInt();
        int w = scanner.nextInt();

        if (h < 3 || w < 3) {
            System.out.println("NO");
            return;
        }

        char[][] grid = new char[h][w];
        for (int i = 0; i < h; i++) {
            grid[i] = scanner.next().toCharArray();
        }

        System.out.println(canClearAll(grid, h, w) ? "YES" : "NO");
    }

    /**
     * Determines if all '*' characters in the grid can be cleared
     * by removing exactly one valid cross pattern.
     */
    private static boolean canClearAll(char[][] grid, int h, int w) {
        int crossR = -1;
        int crossC = -1;

        // Find the first valid cross center
        outerLoop:
        for (int i = 1; i < h - 1; i++) {
            for (int j = 1; j < w - 1; j++) {
                if (grid[i][j] == '*' &&
                    grid[i - 1][j] == '*' && grid[i + 1][j] == '*' &&
                    grid[i][j - 1] == '*' && grid[i][j + 1] == '*') {
                    crossR = i;
                    crossC = j;
                    break outerLoop;
                }
            }
        }

        // If no cross is found, we cannot clear the grid
        if (crossR == -1) {
            return false;
        }

        // Clear the center of the cross
        grid[crossR][crossC] = '.';

        // Clear contiguous '*' segments in all four cardinal directions
        clearOutward(grid, crossR, crossC, 1, 0, h, w); // Down
        clearOutward(grid, crossR, crossC, -1, 0, h, w); // Up
        clearOutward(grid, crossR, crossC, 0, 1, h, w);  // Right
        clearOutward(grid, crossR, crossC, 0, -1, h, w); // Left

        // Check if any '*' remains in the grid
        for (int i = 0; i < h; i++) {
            for (int j = 0; j < w; j++) {
                if (grid[i][j] == '*') {
                    return false;
                }
            }
        }

        return true;
    }

    /**
     * Clears contiguous '*' characters moving outward from (r, c)
     * in the direction specified by (dr, dc).
     */
    private static void clearOutward(char[][] grid, int r, int c, int dr, int dc, int h, int w) {
        int currR = r + dr;
        int currC = c + dc;
        while (currR >= 0 && currR < h && currC >= 0 && currC < w && grid[currR][currC] == '*') {
            grid[currR][currC] = '.';
            currR += dr;
            currC += dc;
        }
    }
}

import java.io.IOException;
import java.io.InputStream;

public class Solution {
    public static void main(String[] args) throws IOException {
        FastReader reader = new FastReader(System.in);

        int gridSize = reader.nextInt();
        int windowSize = reader.nextInt();

        // Handle invalid dimensions gracefully
        if (gridSize <= 0 || windowSize <= 0) {
            System.out.println(0);
            return;
        }

        boolean[][] grid = readGrid(reader, gridSize);
        int[][] rowBounds = computeRowBounds(grid, gridSize);
        int[][] colBounds = computeColBounds(grid, gridSize);

        int emptyCount = countEmptyRowsOrCols(rowBounds, colBounds, gridSize);

        // If the window is larger than the grid, no sliding window overlap is possible
        if (windowSize > gridSize) {
            System.out.println(emptyCount);
            return;
        }

        int maxOverlap = computeMaxWindowOverlap(rowBounds, colBounds, gridSize, windowSize);
        System.out.println(emptyCount + maxOverlap);
    }

    /**
     * Reads the n x n grid from input.
     */
    private static boolean[][] readGrid(FastReader reader, int n) {
        boolean[][] grid = new boolean[n][n];
        for (int i = 0; i < n; i++) {
            String line = reader.nextLine();
            for (int j = 0; j < line.length() && j < n; j++) {
                if (line.charAt(j) == 'B') {
                    grid[i][j] = true;
                }
            }
        }
        return grid;
    }

    /**
     * Computes the minimum and maximum column indices for each row containing 'B'.
     * Uses -1 to indicate rows with no 'B's.
     */
    private static int[][] computeRowBounds(boolean[][] grid, int n) {
        int[][] bounds = new int[n][2]; // [minCol, maxCol]
        for (int i = 0; i < n; i++) {
            int min = -1, max = -1;
            for (int j = 0; j < n; j++) {
                if (grid[i][j]) {
                    if (min == -1 || j < min) min = j;
                    if (max == -1 || j > max) max = j;
                }
            }
            bounds[i][0] = min;
            bounds[i][1] = max;
        }
        return bounds;
    }

    /**
     * Computes the minimum and maximum row indices for each column containing 'B'.
     * Uses -1 to indicate columns with no 'B's.
     */
    private static int[][] computeColBounds(boolean[][] grid, int n) {
        int[][] bounds = new int[n][2]; // [minRow, maxRow]
        for (int j = 0; j < n; j++) {
            int min = -1, max = -1;
            for (int i = 0; i < n; i++) {
                if (grid[i][j]) {
                    if (min == -1 || i < min) min = i;
                    if (max == -1 || i > max) max = i;
                }
            }
            bounds[j][0] = min;
            bounds[j][1] = max;
        }
        return bounds;
    }

    /**
     * Counts the number of rows and columns that contain no 'B's.
     */
    private static int countEmptyRowsOrCols(int[][] rowBounds, int[][] colBounds, int n) {
        int count = 0;
        for (int i = 0; i < n; i++) {
            if (rowBounds[i][0] == -1) count++;
            if (colBounds[i][0] == -1) count++;
        }
        return count;
    }

    /**
     * Computes the maximum sum of active rows and active columns 
     * within any k x k sliding window.
     */
    private static int computeMaxWindowOverlap(int[][] rowBounds, int[][] colBounds, int n, int k) {
        int[][] rowActiveCounts = computeWindowCounts(rowBounds, n, k);
        int[][] colActiveCounts = computeWindowCounts(colBounds, n, k);

        int maxOverlap = 0;
        for (int i = 0; i <= n - k; i++) {
            for (int j = 0; j <= n - k; j++) {
                int currentOverlap = rowActiveCounts[i][j] + colActiveCounts[i][j];
                if (currentOverlap > maxOverlap) {
                    maxOverlap = currentOverlap;
                }
            }
        }
        return maxOverlap;
    }

    /**
     * Uses a sliding window approach to count how many rows/columns 
     * are fully contained within each window of size k.
     */
    private static int[][] computeWindowCounts(int[][] bounds, int n, int k) {
        int[][] counts = new int[n - k + 1][n - k + 1];

        for (int windowStart = 0; windowStart <= n - k; windowStart++) {
            int count = 0;

            // Initialize count for the first window of size k
            for (int i = 0; i < k; i++) {
                if (bounds[i][0] != -1 && bounds[i][0] >= windowStart && bounds[i][1] <= windowStart + k - 1) {
                    count++;
                }
            }
            counts[0][windowStart] = count;

            // Slide the window
            for (int i = 1; i <= n - k; i++) {
                // Remove the element leaving the window
                if (bounds[i - 1][0] != -1 && bounds[i - 1][0] >= windowStart && bounds[i - 1][1] <= windowStart + k - 1) {
                    count--;
                }
                // Add the element entering the window
                if (bounds[i + k - 1][0] != -1 && bounds[i + k - 1][0] >= windowStart && bounds[i + k - 1][1] <= windowStart + k - 1) {
                    count++;
                }
                counts[i][windowStart] = count;
            }
        }
        return counts;
    }

    /**
     * High-performance input reader commonly used in competitive programming.
     */
    private static class FastReader {
        private final byte[] buf = new byte[2048];
        private int index, total;
        private final InputStream in;

        FastReader(InputStream is) {
            this.in = is;
        }

        private int scan() throws IOException {
            if (index >= total) {
                index = 0;
                total = in.read(buf);
                if (total <= 0) {
                    return -1;
                }
            }
            return buf[index++];
        }

        String next() throws IOException {
            int c = scan();
            while (c <= 32 && c != -1) c = scan();
            StringBuilder sb = new StringBuilder();
            while (c > 32 && c != -1) {
                sb.append((char) c);
                c = scan();
            }
            return sb.toString();
        }

        String nextLine() throws IOException {
            int c = scan();
            while (c <= 32 && c != -1) c = scan();
            StringBuilder sb = new StringBuilder();
            while (c != 10 && c != 13 && c != -1) {
                sb.append((char) c);
                c = scan();
            }
            return sb.toString();
        }

        char nextChar() throws IOException {
            int c = scan();
            while (c <= 32 && c != -1) c = scan();
            return (char) c;
        }

        int nextInt() throws IOException {
            int c = scan();
            while (c <= 32 && c != -1) c = scan();
            boolean neg = c == '-';
            if (c == '-' || c == '+') c = scan();
            int val = 0;
            while (c >= '0' && c <= '9' && c != -1) {
                val = (val << 3) + (val << 1) + (c & 15);
                c = scan();
            }
            return neg ? -val : val;
        }

        long nextLong() throws IOException {
            int c = scan();
            while (c <= 32 && c != -1) c = scan();
            boolean neg = c == '-';
            if (c == '-' || c == '+') c = scan();
            long val = 0;
            while (c >= '0' && c <= '9' && c != -1) {
                val = (val << 3) + (val << 1) + (c & 15);
                c = scan();
            }
            return neg ? -val : val;
        }
    }
}

import java.io.InputStream;
import java.io.OutputStream;
import java.io.PrintWriter;
import java.io.IOException;
import java.util.InputMismatchException;
import java.util.ArrayList;

public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        TaskD solver = new TaskD();
        solver.solve(1, in, out);
        out.close();
    }

    static class TaskD {
        public void solve(int testNumber, InputReader in, PrintWriter out) {
            int n = in.nextInt();
            int k = in.nextInt();
            char[][] grid = new char[n + 1][n + 1];
            for (int i = 1; i <= n; i++) {
                String line = in.nextLine();
                for (int j = 1; j <= n; j++) {
                    grid[i][j] = line.charAt(j - 1);
                }
            }

            // Compute prefix sums once and reuse
            int[][] prefixSums = computePrefixSums(n, grid);
            int oldLines = countFullyWhiteLines(n, prefixSums);
            int newLines = calculateMaxAdditionalLines(n, k, prefixSums, grid);

            out.print(oldLines + newLines);
        }

        /**
         * Computes the 2D prefix sum array for black cells ('B').
         * Uses 1-based indexing to align with competitive programming conventions.
         */
        private int[][] computePrefixSums(int n, char[][] grid) {
            int[][] prefixSums = new int[n + 1][n + 1];
            for (int i = 1; i <= n; i++) {
                for (int j = 1; j <= n; j++) {
                    prefixSums[i][j] = prefixSums[i - 1][j] + prefixSums[i][j - 1] - prefixSums[i - 1][j - 1];
                    prefixSums[i][j] += (grid[i][j] == 'B' ? 1 : 0);
                }
            }
            return prefixSums;
        }

        /**
         * Counts rows and columns that contain zero black cells.
         */
        private int countFullyWhiteLines(int n, int[][] prefixSums) {
            int count = 0;
            for (int i = 1; i <= n; i++) {
                if (queryPrefixSum(prefixSums, i, 1, i, n) == 0) count++;
            }
            for (int j = 1; j <= n; j++) {
                if (queryPrefixSum(prefixSums, 1, j, n, j) == 0) count++;
            }
            return count;
        }

        /**
         * Standard 2D prefix sum range query.
         */
        private int queryPrefixSum(int[][] prefixSums, int x1, int y1, int x2, int y2) {
            return prefixSums[x2][y2] - prefixSums[x1 - 1][y2] - prefixSums[x2][y1 - 1] + prefixSums[x1 - 1][y1 - 1];
        }

        /**
         * Calculates the maximum number of additional white lines that can be formed
         * by selecting a k x k subgrid that covers all black cells in those lines.
         */
        private int calculateMaxAdditionalLines(int n, int k, int[][] prefixSums, char[][] grid) {
            int[] leftmostBlackCol = new int[n + 1];
            int[] rightmostBlackCol = new int[n + 1];

            // Precompute the leftmost and rightmost black cell column index for each row
            for (int row = 1; row <= n; row++) {
                leftmostBlackCol[row] = n + 1;
                rightmostBlackCol[row] = -1;
                for (int col = 1; col <= n; col++) {
                    if (grid[row][col] == 'B') {
                        leftmostBlackCol[row] = Math.min(col, leftmostBlackCol[row]);
                        rightmostBlackCol[row] = Math.max(col, rightmostBlackCol[row]);
                    }
                }
            }

            int maxAdditionalLines = 0;

            // Slide a k-height window vertically
            for (int topRow = 1; topRow <= n - k + 1; topRow++) {
                ArrayList<IntervalEvent> events = new ArrayList<>();
                for (int r = topRow; r < topRow + k; r++) {
                    // Only consider rows that fit within the k-width constraint
                    if (rightmostBlackCol[r] >= leftmostBlackCol[r] && 
                        rightmostBlackCol[r] - leftmostBlackCol[r] <= k) {
                        events.add(new IntervalEvent(rightmostBlackCol[r], r));
                        events.add(new IntervalEvent(leftmostBlackCol[r], -r));
                    }
                }

                // Sort events by column index, then by event type
                events.sort((a, b) -> {
                    if (a.col != b.col) return Integer.compare(a.col, b.col);
                    return Integer.compare(a.rowType, b.rowType);
                });

                ArrayList<IntervalEvent> activeEvents = new ArrayList<>();
                int eventIdx = 0;
                int activeEventIdx = 0;
                int coveredColumnsCount = 0;

                // Slide a k-width window horizontally
                for (int col = 1; col <= n; col++) {
                    if (col > k) {
                        // Remove events that exit the left side of the window
                        while (activeEventIdx < activeEvents.size() && activeEvents.get(activeEventIdx).col == col - k) {
                            if (activeEvents.get(activeEventIdx).rowType < 0) {
                                coveredColumnsCount--;
                            }
                            activeEventIdx++;
                        }
                        // Check if the leaving column is still fully covered by the window
                        if (!isColumnFullyWhite(prefixSums, col, n) &&
                            queryPrefixSum(prefixSums, topRow, col, topRow + k - 1, col) == 
                            queryPrefixSum(prefixSums, 1, col, n, col)) {
                            coveredColumnsCount--;
                        }
                    }

                    // Check if the entering column is now fully covered
                    if (!isColumnFullyWhite(prefixSums, col, n) &&
                        queryPrefixSum(prefixSums, topRow, col, topRow + k - 1, col) == 
                        queryPrefixSum(prefixSums, 1, col, n, col)) {
                        coveredColumnsCount++;
                    }

                    // Process events starting at the current column
                    while (eventIdx < events.size() && events.get(eventIdx).col == col) {
                        if (events.get(eventIdx).rowType > 0) {
                            coveredColumnsCount++;
                        }
                        activeEvents.add(events.get(eventIdx));
                        eventIdx++;
                    }

                    maxAdditionalLines = Math.max(maxAdditionalLines, coveredColumnsCount);
                }
            }
            return maxAdditionalLines;
        }

        /**
         * Checks if an entire column contains no black cells.
         */
        private boolean isColumnFullyWhite(int[][] prefixSums, int col, int n) {
            return queryPrefixSum(prefixSums, 1, col, n, col) == 0;
        }

        /**
         * Represents a boundary event for the sliding window algorithm.
         */
        private static class IntervalEvent {
            final int col;
            final int rowType; // Positive for rightmost boundary, Negative for leftmost

            IntervalEvent(int col, int rowType) {
                this.col = col;
                this.rowType = rowType;
            }
        }
    }

    /**
     * Fast input reader for competitive programming environments.
     */
    static class InputReader {
        private final byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;
        private final InputStream stream;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        private boolean isWhitespace(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        private boolean isEndOfLine(int c) {
            return c == '\n' || c == '\r' || c == -1;
        }

        private int read() {
            if (numChars == -1) {
                throw new InputMismatchException();
            }
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0) {
                    return -1;
                }
            }
            return buf[curChar++];
        }

        public int nextInt() {
            int c = read();
            while (isWhitespace(c)) {
                c = read();
            }
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                res *= 10;
                res += c - '0';
                c = read();
            } while (!isWhitespace(c));
            return res * sgn;
        }

        public String nextLine() {
            int c = read();
            while (isWhitespace(c)) {
                c = read();
            }
            StringBuilder res = new StringBuilder();
            do {
                res.appendCodePoint(c);
                c = read();
            } while (!isEndOfLine(c));
            return res.toString();
        }
    }
}

import java.util.Arrays;
import java.util.Scanner;

/**
 * Calculates the maximum number of rows and columns that can be "covered" 
 * by a k x k square placed on an n x n grid. A row/column is covered if 
 * all 'B' characters within it fall inside the square's bounds.
 */
public class GridCovering {

    public static void main(String[] args) {
        // Use try-with-resources to automatically close the Scanner
        try (Scanner sc = new Scanner(System.in)) {
            if (!sc.hasNextInt()) {
                return;
            }

            int n = sc.nextInt();
            int k = sc.nextInt();
            sc.nextLine(); // Consume the newline character after the integers

            String[] grid = new String[n];
            for (int i = 0; i < n; i++) {
                grid[i] = sc.nextLine();
            }

            System.out.println(calculateMaxCovered(grid, k));
        }
    }

    /**
     * Computes the maximum number of rows and columns covered by a k x k window.
     */
    private static int calculateMaxCovered(String[] grid, int k) {
        int n = grid.length;
        if (k <= 0 || k > n) {
            return 0;
        }

        // Arrays to store the first and last occurrence index of 'B' for each row/column
        int[] firstRow = new int[n];
        int[] lastRow = new int[n];
        int[] firstCol = new int[n];
        int[] lastCol = new int[n];

        Arrays.fill(firstRow, -1);
        Arrays.fill(firstCol, -1);

        int emptyCols = 0;
        int emptyRows = 0;

        // 1. Determine vertical bounds for each column
        for (int j = 0; j < n; j++) {
            for (int i = 0; i < n; i++) {
                if (grid[i].charAt(j) == 'B') {
                    if (firstRow[j] == -1) {
                        firstRow[j] = i;
                        lastRow[j] = i;
                    } else {
                        lastRow[j] = i;
                    }
                }
            }
            if (firstRow[j] == -1) {
                emptyCols++;
            }
        }

        // 2. Determine horizontal bounds for each row
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i].charAt(j) == 'B') {
                    if (firstCol[i] == -1) {
                        firstCol[i] = j;
                        lastCol[i] = j;
                    } else {
                        lastCol[i] = j;
                    }
                }
            }
            if (firstCol[i] == -1) {
                emptyRows++;
            }
        }

        // 3. Precompute sliding window counts
        // numr[i][j] = count of columns in window [j, j+k-1] whose vertical span fits in row window [i, i+k-1]
        int[][] numr = new int[n][n];
        // numc[i][j] = count of rows in window [i, i+k-1] whose horizontal span fits in column window [j, j+k-1]
        int[][] numc = new int[n][n];

        computeSlidingWindowCounts(numr, grid, k, firstRow, lastRow, true);
        computeSlidingWindowCounts(numc, grid, k, firstCol, lastCol, false);

        // 4. Find the maximum combined count over all valid k x k positions
        int maxCovered = 0;
        for (int i = 0; i <= n - k; i++) {
            for (int j = 0; j <= n - k; j++) {
                maxCovered = Math.max(maxCovered, numr[i][j] + numc[i][j]);
            }
        }

        // Columns/rows with no 'B's trivially fit in any window
        return maxCovered + emptyCols + emptyRows;
    }

    /**
     * Computes sliding window counts for either rows or columns.
     * @param result The 2D array to populate
     * @param k The window size
     * @param first Array of first occurrence indices
     * @param last Array of last occurrence indices
     * @param isVertical If true, computes vertical fits (numr). If false, horizontal fits (numc).
     */
    private static void computeSlidingWindowCounts(int[][] result, int k, 
                                                   int[] first, int[] last, 
                                                   boolean isVertical) {
        int n = result.length;

        // Iterate over the fixed axis (rows for numr, columns for numc)
        int fixedAxisLimit = isVertical ? n : n;

        for (int fixedIdx = 0; fixedIdx < fixedAxisLimit; fixedIdx++) {
            int count = 0;
            int start = isVertical ? fixedIdx : fixedIdx; // Window start on the sliding axis

            // Initialize first window
            int windowStart = 0;
            for (int slidingIdx = 0; slidingIdx < k; slidingIdx++) {
                if (isSpanContained(slidingIdx, start, k, first, last)) {
                    count++;
                }
            }
            result[fixedIdx][0] = count;

            // Slide the window across the other axis
            for (int slidingIdx = 1; slidingIdx < n; slidingIdx++) {
                // Remove element leaving the window
                if (isSpanContained(slidingIdx - 1, start, k, first, last)) {
                    count--;
                }
                // Add element entering the window
                if (slidingIdx + k - 1 < n && isSpanContained(slidingIdx + k - 1, start, k, first, last)) {
                    count++;
                }
                result[fixedIdx][slidingIdx] = count;
            }
        }
    }

    /**
     * Checks if the span of 'B's at index `idx` is fully contained within 
     * the window [start, start + k - 1].
     */
    private static boolean isSpanContained(int idx, int start, int k, int[] first, int[] last) {
        int firstIdx = first[idx];
        if (firstIdx == -1) {
            return false; // No 'B's at this index, handled separately by empty counts
        }
        return firstIdx >= start && last[idx] <= start + k - 1;
    }
}

import java.io.*;
import java.util.*;

/**
 * Solves a grid-based problem by analyzing sliding windows of size k x k.
 * Counts empty rows/columns and maximizes the combined count of 
 * row/column windows that fit within a k-length range.
 */
public class GridSolver {

    public static void main(String[] args) {
        FastScanner in = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out);

        // Original template used a fixed test case count of 1
        int t = 1;
        for (int i = 0; i < t; i++) {
            new Solver().solve(i + 1, in, out);
        }

        out.flush();
        out.close();
    }

    /**
     * Encapsulates the core solving logic for a single test case.
     */
    static class Solver {
        public void solve(int testNumber, FastScanner in, PrintWriter out) {
            int n = in.nextInt();
            int k = in.nextInt();

            char[][] grid = new char[n][];
            for (int i = 0; i < n; i++) {
                grid[i] = in.next().toCharArray();
            }

            // Compute min/max bounds for 'B' characters in each row and column
            int[][] rowBounds = computeBounds(grid, true, n);
            int[][] colBounds = computeBounds(grid, false, n);

            // Count completely empty rows and columns
            int emptyCount = 0;
            for (int[] bounds : rowBounds) {
                if (bounds[0] == n) emptyCount++;
            }
            for (int[] bounds : colBounds) {
                if (bounds[0] == n) emptyCount++;
            }

            // Compute sliding window sums for rows and columns
            // Indexing: [verticalStart][horizontalStart]
            int[][] rowWindowSums = computeWindowSums(rowBounds, n, k, true);
            int[][] colWindowSums = computeWindowSums(colBounds, n, k, false);

            // Find the maximum combined window sum across all possible k x k positions
            int maxSum = 0;
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < n; j++) {
                    maxSum = Math.max(maxSum, rowWindowSums[i][j] + colWindowSums[i][j]);
                }
            }

            out.println(maxSum + emptyCount);
        }

        /**
         * Computes the minimum and maximum indices of 'B' for each row or column.
         * If a row/column contains no 'B', bounds[0] remains n.
         */
        private int[][] computeBounds(char[][] grid, boolean isRow, int n) {
            int[][] bounds = new int[n][2];
            for (int i = 0; i < n; i++) {
                int min = n;
                int max = -1;
                for (int j = 0; j < n; j++) {
                    char cell = isRow ? grid[i][j] : grid[j][i];
                    if (cell == 'B') {
                        min = Math.min(min, j);
                        max = j;
                    }
                }
                bounds[i][0] = min;
                bounds[i][1] = max;
            }
            return bounds;
        }

        /**
         * Computes sliding window sums for a 2D grid of bounds.
         * Uses a vertical sliding window approach over precomputed bounds.
         */
        private int[][] computeWindowSums(int[][] bounds, int n, int k, boolean isRow) {
            int[][] windowSums = new int[n][n];

            // Initialize the first vertical window for each horizontal start position
            for (int hStart = 0; hStart + k - 1 < n; hStart++) {
                int count = 0;
                for (int i = 0; i < k; i++) {
                    if (checkCondition(bounds, i, hStart, k, isRow)) {
                        count++;
                    }
                }
                windowSums[0][hStart] = count;

                // Slide the window vertically
                for (int vStart = 1; vStart + k - 1 < n; vStart++) {
                    int removed = checkCondition(bounds, vStart - 1, hStart, k, isRow) ? 1 : 0;
                    int added = checkCondition(bounds, vStart + k - 1, hStart, k, isRow) ? 1 : 0;
                    windowSums[vStart][hStart] = windowSums[vStart - 1][hStart] - removed + added;
                }
            }
            return windowSums;
        }

        /**
         * Checks if a row/column's 'B' range fits entirely within a sliding window.
         */
        private boolean checkCondition(int[][] bounds, int index, int windowStart, int k, boolean isRow) {
            int min = bounds[index][0];
            if (min == n) return false; // Empty row/column
            int max = bounds[index][1];
            return min >= windowStart && max < windowStart + k;
        }
    }

    /**
     * Efficient input reader using BufferedReader and StringTokenizer.
     * Replaces the original buggy custom reader for better maintainability.
     */
    static class FastScanner {
        private BufferedReader br;
        private StringTokenizer st;

        public FastScanner(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        public String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input", e);
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            String token = next();
            return token == null ? 0 : Integer.parseInt(token);
        }
    }
}

import java.util.Scanner;

/**
 * Analyzes an n x n grid to find the optimal k x k window that maximizes
 * the count of occupied rows and columns within the window, plus the total
 * number of completely empty rows and columns in the grid.
 */
public class Main {
    private static final int NO_BOUND = -1;

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            if (!scanner.hasNextInt()) {
                return;
            }

            int gridSize = scanner.nextInt();
            int windowSize = scanner.nextInt();

            // Validate input to prevent negative array dimensions
            if (windowSize > gridSize) {
                System.out.println(0);
                return;
            }

            int[][] rowBounds = new int[gridSize][2];
            int[][] colBounds = new int[gridSize][2];
            initializeBounds(rowBounds, colBounds, gridSize);

            readGridAndComputeBounds(scanner, gridSize, rowBounds, colBounds);

            int emptyLinesCount = countEmptyLines(gridSize, rowBounds, colBounds);
            int[][][] dpTable = computeDpTable(gridSize, windowSize, rowBounds, colBounds);
            int maxScore = findMaxScore(dpTable);

            System.out.println(maxScore + emptyLinesCount);
        }
    }

    /**
     * Initializes the min/max bounds for each row and column.
     * Bounds are set to gridSize (min) and NO_BOUND (max) initially.
     */
    private static void initializeBounds(int[][] rowBounds, int[][] colBounds, int gridSize) {
        for (int i = 0; i < gridSize; i++) {
            rowBounds[i][0] = gridSize;
            rowBounds[i][1] = NO_BOUND;
            colBounds[i][0] = gridSize;
            colBounds[i][1] = NO_BOUND;
        }
    }

    /**
     * Reads the grid row by row and updates the bounding indices for 'B' characters.
     */
    private static void readGridAndComputeBounds(Scanner scanner, int gridSize, int[][] rowBounds, int[][] colBounds) {
        for (int i = 0; i < gridSize; i++) {
            String row = scanner.next();
            for (int j = 0; j < gridSize; j++) {
                if (row.charAt(j) == 'B') {
                    updateBounds(rowBounds, colBounds, i, j);
                }
            }
        }
    }

    /**
     * Updates the min/max column index for a specific row,
     * and the min/max row index for a specific column.
     */
    private static void updateBounds(int[][] rowBounds, int[][] colBounds, int row, int col) {
        rowBounds[row][0] = Math.min(col, rowBounds[row][0]);
        rowBounds[row][1] = Math.max(col, rowBounds[row][1]);
        colBounds[col][0] = Math.min(row, colBounds[col][0]);
        colBounds[col][1] = Math.max(row, colBounds[col][1]);
    }

    /**
     * Counts the number of rows and columns that contain no 'B' characters at all.
     */
    private static int countEmptyLines(int gridSize, int[][] rowBounds, int[][] colBounds) {
        int count = 0;
        for (int i = 0; i < gridSize; i++) {
            if (rowBounds[i][1] == NO_BOUND) count++;
            if (colBounds[i][1] == NO_BOUND) count++;
        }
        return count;
    }

    /**
     * Computes the DP table using a 2D sliding window approach.
     * dpTable[i][j][0] tracks occupied rows in the k x k window starting at (i, j).
     * dpTable[i][j][1] tracks occupied columns in the k x k window starting at (i, j).
     */
    private static int[][][] computeDpTable(int gridSize, int windowSize, int[][] rowBounds, int[][] colBounds) {
        int dpSize = gridSize - windowSize + 1;
        int[][][] dpTable = new int[dpSize][dpSize][2];

        // Initialize the top-left window dp[0][0]
        for (int i = 0; i < windowSize; i++) {
            if (rowBounds[i][1] < windowSize && rowBounds[i][1] >= 0) {
                dpTable[0][0][0]++;
            }
            if (colBounds[i][1] < windowSize && colBounds[i][1] >= 0) {
                dpTable[0][0][1]++;
            }
        }

        // Cache for tracking row changes during horizontal shifts
        int[] columnCache = new int[dpSize];

        for (int i = 0; i < dpSize; i++) {
            // --- Vertical Window Shift (sliding down) ---
            if (i > 0) {
                dpTable[i][0][0] = dpTable[i - 1][0][0];
                if (rowBounds[i - 1][1] < windowSize && rowBounds[i - 1][1] >= 0) {
                    dpTable[i][0][0]--;
                }
                if (rowBounds[i + windowSize - 1][1] < windowSize && rowBounds[i + windowSize - 1][1] >= 0) {
                    dpTable[i][0][0]++;
                }

                int tempChange = 0;
                for (int m = 0; m < windowSize; m++) {
                    if (colBounds[m][1] == NO_BOUND) continue;
                    if (i - 1 <= colBounds[m][0] && i + windowSize - 2 >= colBounds[m][1]) {
                        if (i > colBounds[m][0]) {
                            tempChange--;
                        }
                    } else {
                        if (i <= colBounds[m][0] && i + windowSize - 1 >= colBounds[m][1]) {
                            tempChange++;
                        }
                    }
                }
                dpTable[i][0][1] = dpTable[i - 1][0][1] + tempChange;
            }

            // --- Horizontal Window Shift (sliding right) ---
            for (int j = 1; j < dpSize; j++) {
                dpTable[i][j][0] = dpTable[i][j - 1][0];
                dpTable[i][j][1] = dpTable[i][j - 1][1];

                // Update column occupancy for horizontal shift
                if (colBounds[j - 1][1] >= 0 && i <= colBounds[j - 1][0] && i + windowSize - 1 >= colBounds[j - 1][1]) {
                    dpTable[i][j][1]--;
                }
                if (colBounds[j + windowSize - 1][1] >= 0 && i <= colBounds[j + windowSize - 1][0] && i + windowSize - 1 >= colBounds[j + windowSize - 1][1]) {
                    dpTable[i][j][1]++;
                }

                // Update row occupancy for horizontal shift
                if (i == 0) {
                    int curChange = 0;
                    for (int q = i; q <= i + windowSize - 1; q++) {
                        if (rowBounds[q][1] == NO_BOUND) continue;
                        if (j - 1 <= rowBounds[q][0] && j + windowSize - 2 >= rowBounds[q][1]) {
                            if (j > rowBounds[q][0]) {
                                curChange--;
                            }
                        } else {
                            if (j <= rowBounds[q][0] && j + windowSize - 1 >= rowBounds[q][1]) {
                                curChange++;
                            }
                        }
                    }
                    columnCache[j] = curChange;
                    dpTable[i][j][0] = dpTable[i][j - 1][0] + curChange;
                } else {
                    int nowChange = 0;
                    // Remove effect of the row leaving the window
                    if (j - 1 <= rowBounds[i - 1][0] && j + windowSize - 2 >= rowBounds[i - 1][1]) {
                        if (j > rowBounds[i - 1][0]) {
                            nowChange++;
                        }
                    } else {
                        if (j <= rowBounds[i - 1][0] && j + windowSize - 1 >= rowBounds[i - 1][1]) {
                            nowChange--;
                        }
                    }
                    // Add effect of the row entering the window
                    if (j - 1 <= rowBounds[i + windowSize - 1][0] && j + windowSize - 2 >= rowBounds[i + windowSize - 1][1]) {
                        if (j > rowBounds[i + windowSize - 1][0]) {
                            nowChange--;
                        }
                    } else {
                        if (j <= rowBounds[i + windowSize - 1][0] && j + windowSize - 1 >= rowBounds[i + windowSize - 1][1]) {
                            nowChange++;
                        }
                    }
                    columnCache[j] += nowChange;
                    dpTable[i][j][0] = dpTable[i][j - 1][0] + columnCache[j];
                }
            }
        }
        return dpTable;
    }

    /**
     * Finds the maximum score across all possible k x k window positions.
     */
    private static int findMaxScore(int[][][] dpTable) {
        int maxScore = 0;
        for (int i = 0; i < dpTable.length; i++) {
            for (int j = 0; j < dpTable[i].length; j++) {
                int currentScore = dpTable[i][j][0] + dpTable[i][j][1];
                if (currentScore > maxScore) {
                    maxScore = currentScore;
                }
            }
        }
        return maxScore;
    }
}

import java.io.*;
import java.util.Arrays;
import java.util.InputMismatchException;

public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;

        InputReader in = new InputReader(inputStream);
        OutputWriter out = new OutputWriter(outputStream);

        TaskD solver = new TaskD();
        solver.solve(in, out);

        out.close();
    }

    static class TaskD {
        public void solve(InputReader in, OutputWriter out) {
            int n = in.nextInt();
            int k = in.nextInt();

            // Track the minimum and maximum indices of 'B' characters per row/column
            int[] rowMin = new int[n];
            int[] rowMax = new int[n];
            int[] colMin = new int[n];
            int[] colMax = new int[n];

            // Initialize min arrays to MAX_VALUE to easily detect empty rows/cols
            Arrays.fill(rowMin, Integer.MAX_VALUE);
            Arrays.fill(colMin, Integer.MAX_VALUE);

            // Read grid and populate boundary arrays
            for (int i = 0; i < n; i++) {
                char[] row = in.readCharArray(n);
                for (int j = 0; j < n; j++) {
                    if (row[j] == 'B') {
                        rowMax[i] = Math.max(rowMax[i], j);
                        rowMin[i] = Math.min(rowMin[i], j);
                        colMax[j] = Math.max(colMax[j], i);
                        colMin[j] = Math.min(colMin[j], i);
                    }
                }
            }

            // Count rows and columns that contain no 'B' characters
            int emptyCount = 0;
            for (int i = 0; i < n; i++) {
                if (rowMin[i] == Integer.MAX_VALUE) emptyCount++;
                if (colMin[i] == Integer.MAX_VALUE) emptyCount++;
            }

            int maxVal = emptyCount;
            int windowCount = n - k + 1;

            // Precompute which rows are fully contained within each column window
            boolean[][] rowInColWindow = new boolean[n][windowCount];
            for (int i = 0; i < n; i++) {
                if (rowMin[i] == Integer.MAX_VALUE) continue;
                int rMin = rowMin[i];
                int rMax = rowMax[i];
                for (int j = 0; j < windowCount; j++) {
                    // Check if row i's 'B's fall entirely within columns [j, j+k-1]
                    rowInColWindow[i][j] = (rMax < j + k && rMin >= j);
                }
            }

            // Precompute which columns are fully contained within each row window
            boolean[][] colInRowWindow = new boolean[n][windowCount];
            for (int j = 0; j < n; j++) {
                if (colMin[j] == Integer.MAX_VALUE) continue;
                int cMin = colMin[j];
                int cMax = colMax[j];
                for (int i = 0; i < windowCount; i++) {
                    // Check if col j's 'B's fall entirely within rows [i, i+k-1]
                    colInRowWindow[j][i] = (cMax < i + k && cMin >= i);
                }
            }

            // Compute sliding window sums for rows across column windows
            int[][] rowWindowSums = new int[windowCount][windowCount];
            for (int j = 0; j < windowCount; j++) {
                int currentSum = 0;
                for (int i = 0; i < n; i++) {
                    if (i >= k) {
                        currentSum -= rowInColWindow[i - k][j] ? 1 : 0;
                    }
                    currentSum += rowInColWindow[i][j] ? 1 : 0;
                    if (i >= k - 1) {
                        rowWindowSums[i - k + 1][j] = currentSum;
                    }
                }
            }

            // Compute sliding window sums for columns and combine with row sums
            for (int i = 0; i < windowCount; i++) {
                int currentSum = 0;
                for (int j = 0; j < n; j++) {
                    if (j >= k) {
                        currentSum -= colInRowWindow[j - k][i] ? 1 : 0;
                    }
                    currentSum += colInRowWindow[j][i] ? 1 : 0;
                    if (j >= k - 1) {
                        // Total valid lines = empty lines + contained rows + contained columns
                        int total = emptyCount + rowWindowSums[i][j - k + 1] + currentSum;
                        if (total > maxVal) {
                            maxVal = total;
                        }
                    }
                }
            }

            out.println(maxVal);
        }
    }

    /**
     * Fast input reader for competitive programming environments.
     */
    static class InputReader {
        private final InputStream stream;
        private final byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        public char readCharacter() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            return (char) c;
        }

        public char[] readCharArray(int size) {
            char[] array = new char[size];
            for (int i = 0; i < size; i++) {
                array[i] = readCharacter();
            }
            return array;
        }

        public int read() {
            if (numChars == -1) {
                throw new InputMismatchException();
            }
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0) {
                    return -1;
                }
            }
            return buf[curChar++];
        }

        public int nextInt() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                res *= 10;
                res += c - '0';
                c = read();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public boolean isSpaceChar(int c) {
            return isWhitespace(c);
        }

        public static boolean isWhitespace(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }
    }

    /**
     * Fast output writer with buffered printing.
     */
    static class OutputWriter {
        private final PrintWriter writer;

        public OutputWriter(OutputStream outputStream) {
            writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(outputStream)));
        }

        public OutputWriter(Writer writer) {
            this.writer = new PrintWriter(writer);
        }

        public void println(Object... objects) {
            for (int i = 0; i < objects.length; i++) {
                if (i != 0) {
                    writer.print(' ');
                }
                writer.print(objects[i]);
            }
            writer.print('\n');
        }

        public void close() {
            writer.close();
        }
    }
}

import java.io.*;
import java.util.*;

public class CodingLegacy {

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner();
        PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out));

        int t = 1; // Default number of test cases. Can be extended to read from input if needed.

        PalindromeSolver solver = new PalindromeSolver();
        for (int i = 0; i < t; i++) {
            solver.solve(i + 1, scanner, out);
        }

        out.flush();
        out.close();
    }

    /**
     * Encapsulates the core algorithm for solving palindrome-related grid problems.
     */
    static class PalindromeSolver {

        /**
         * Solves a single test case.
         *
         * @param testNumber Current test case identifier
         * @param in         FastScanner instance for input
         * @param out        PrintWriter instance for output
         */
        void solve(int testNumber, FastScanner in, PrintWriter out) {
            int n = in.nextInt();
            int k = in.nextInt();

            char[][] grid = new char[n][];
            for (int i = 0; i < n; i++) {
                grid[i] = in.next().toCharArray();
            }

            // 2D prefix sum array to count 'B's in any rectangular region.
            // prefixSum[i][j] stores the count of 'B's in grid[0..i-1][0..j-1]
            int[][] prefixSum = new int[n + 1][n + 1];
            for (int i = 1; i <= n; i++) {
                for (int j = 1; j <= n; j++) {
                    prefixSum[i][j] = prefixSum[i - 1][j] + prefixSum[i][j - 1]
                                    - prefixSum[i - 1][j - 1]
                                    + (grid[i - 1][j - 1] == 'B' ? 1 : 0);
                }
            }

            // Count rows and columns that contain zero 'B's
            int zeroCount = 0;
            for (int i = 1; i <= n; i++) {
                if (queryCount(prefixSum, i, 1, i, n) == 0) zeroCount++;
                if (queryCount(prefixSum, 1, i, n, i) == 0) zeroCount++;
            }

            // rowValid[i][j] = 1 if a horizontal segment of length k starting at (i,j)
            // has the same number of 'B's as the entire row i.
            int[][] rowValid = new int[n + 1][n + 1];
            for (int i = 1; i <= n; i++) {
                int fullRowBCount = queryCount(prefixSum, i, 1, i, n);
                for (int j = 1; j <= n; j++) {
                    int segmentEndCol = Math.min(n, j + k - 1);
                    if (fullRowBCount > 0 && queryCount(prefixSum, i, j, i, segmentEndCol) == fullRowBCount) {
                        rowValid[i][j] = 1;
                    }
                }
            }

            // colValid[i][j] = 1 if a vertical segment of length k starting at (i,j)
            // has the same number of 'B's as the entire column j.
            int[][] colValid = new int[n + 1][n + 1];
            for (int j = 1; j <= n; j++) {
                int fullColBCount = queryCount(prefixSum, 1, j, n, j);
                for (int i = 1; i <= n; i++) {
                    int segmentEndRow = Math.min(n, i + k - 1);
                    if (fullColBCount > 0 && queryCount(prefixSum, i, j, segmentEndRow, j) == fullColColBCount) {
                        colValid[i][j] = 1;
                    }
                }
            }

            // Convert rowValid to vertical prefix sums and colValid to horizontal prefix sums
            for (int i = 1; i <= n; i++) {
                for (int j = 1; j <= n; j++) {
                    rowValid[i][j] += rowValid[i - 1][j];
                }
            }
            for (int i = 1; i <= n; i++) {
                for (int j = 1; j <= n; j++) {
                    colValid[i][j] += colValid[i][j - 1];
                }
            }

            // Find the maximum sum of valid row segments and valid column segments
            // within any k x k window
            int maxOverlap = 0;
            for (int i = 1; i <= n; i++) {
                for (int j = 1; j <= n; j++) {
                    int rEnd = Math.min(n, i + k - 1);
                    int cEnd = Math.min(n, j + k - 1);
                    int currentRowSum = rowValid[rEnd][j] - rowValid[i - 1][j];
                    int currentColSum = colValid[i][cEnd] - colValid[i][j - 1];
                    maxOverlap = Math.max(maxOverlap, currentRowSum + currentColSum);
                }
            }

            out.println(zeroCount + maxOverlap);
        }

        /**
         * Queries the 2D prefix sum array to get the count of 'B's in the rectangle
         * defined by top-left (l1, r1) and bottom-right (l2, r2) using 1-based indexing.
         */
        private int queryCount(int[][] prefixSum, int l1, int r1, int l2, int r2) {
            l2 = Math.min(l2, prefixSum.length - 1);
            r2 = Math.min(r2, prefixSum[0].length - 1);
            return prefixSum[l2][r2] - prefixSum[l1 - 1][r2] - prefixSum[l2][r1 - 1] + prefixSum[l1 - 1][r1 - 1];
        }
    }

    /**
     * FastScanner for efficient input reading.
     * Replaces the inconsistent custom byte-buffer reader with a standard, robust BufferedReader/StringTokenizer approach.
     */
    static class FastScanner {
        private BufferedReader br;
        private StringTokenizer st;

        public FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        long nextLong() {
            return Long.parseLong(next());
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.StringTokenizer;

public class CF_578_D {

    /**
     * Immutable value class representing a closed integer range [start, end].
     */
    private static class IntRange {
        final int start;
        final int end;

        IntRange(int start, int end) {
            this.start = start;
            this.end = end;
        }
    }

    /**
     * Entry point for the program.
     */
    public static void main(String[] args) {
        FastScanner scanner = new FastScanner();
        int testCases = 1;
        while (testCases-- > 0) {
            new CF_578_D().solve(scanner.nextInt(), scanner.nextInt());
        }
    }

    /**
     * Core logic to process the grid and compute the answer.
     *
     * @param n Grid dimension (n x n)
     * @param k Window size for the sliding window
     */
    private void solve(int n, int k) {
        int[] firstRowInCol = new int[n];
        int[] lastRowInCol = new int[n];
        Arrays.fill(firstRowInCol, -1);

        int emptyRowsCount = 0;
        List<IntRange> validRowStartRanges = new ArrayList<>(n);

        // 1. Read grid and precompute column boundaries & valid row coverage ranges
        for (int i = 0; i < n; i++) {
            String rowStr = scanner.next();
            int firstB = -1;
            int lastB = -1;

            for (int j = 0; j < n; j++) {
                boolean isBlack = rowStr.charAt(j) == 'B';
                if (isBlack) {
                    if (firstRowInCol[j] == -1) {
                        firstRowInCol[j] = i;
                    }
                    lastRowInCol[j] = i;
                    if (firstB == -1) firstB = j;
                    lastB = j;
                }
            }

            if (firstB == -1) {
                emptyRowsCount++;
                validRowStartRanges.add(null);
            } else if (lastB - firstB + 1 <= k) {
                // A window of size k can cover this row's 'B's if it starts between
                // [lastB - k + 1, firstB]. Clamp start to 0.
                int validStart = Math.max(0, lastB - k + 1);
                validRowStartRanges.add(new IntRange(validStart, firstB));
            } else {
                validRowStartRanges.add(null);
            }
        }

        // 2. Sliding window over rows and columns
        int maxCoveredMetric = 0;
        int[] columnCoverageCount = new int[n]; // Tracks how many rows in current window cover each column

        for (int currentRowEnd = 0; currentRowEnd < n; currentRowEnd++) {
            int currentRowStart = currentRowEnd - k + 1;

            // Add new row entering the vertical window
            IntRange rowRange = validRowStartRanges.get(currentRowEnd);
            if (rowRange != null) {
                for (int col = rowRange.start; col <= rowRange.end; col++) {
                    columnCoverageCount[col]++;
                }
            }

            // Remove row leaving the vertical window
            if (currentRowStart > 0) {
                IntRange oldRange = validRowStartRanges.get(currentRowStart - 1);
                if (oldRange != null) {
                    for (int col = oldRange.start; col <= oldRange.end; col++) {
                        columnCoverageCount[col]--;
                    }
                }
            }

            // 3. Sliding window over columns within the current row window
            int fullyContainedColumns = 0;
            for (int currentColEnd = 0; currentColEnd < n; currentColEnd++) {
                int currentColStart = currentColEnd - k + 1;

                // Check if current column is fully contained within the current row window
                if (firstRowInCol[currentColEnd] >= currentRowStart &&
                    lastRowInCol[currentColEnd] <= currentRowEnd) {
                    fullyContainedColumns++;
                }

                // Remove column leaving the horizontal window
                if (currentColStart > 0) {
                    if (firstRowInCol[currentColStart - 1] >= currentRowStart &&
                        lastRowInCol[currentColStart - 1] <= currentRowEnd) {
                        fullyContainedColumns--;
                    }
                }

                // Update maximum metric for valid kxk windows
                if (currentColStart >= 0) {
                    int currentMetric = columnCoverageCount[currentColStart] + fullyContainedColumns;
                    maxCoveredMetric = Math.max(maxCoveredMetric, currentMetric);
                }
            }
        }

        // 4. Count empty columns
        int emptyColsCount = 0;
        for (int j = 0; j < n; j++) {
            if (firstRowInCol[j] == -1) {
                emptyColsCount++;
            }
        }

        System.out.println(maxCoveredMetric + emptyRowsCount + emptyColsCount);
    }

    /**
     * Fast I/O helper class for competitive programming environments.
     */
    static class FastScanner {
        private final BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        private StringTokenizer st;

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) throw new IOException("End of input");
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        long nextLong() {
            return Long.parseLong(next());
        }

        double nextDouble() {
            return Double.parseDouble(next());
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.OutputStream;
import java.io.PrintWriter;
import java.util.Arrays;
import java.util.StringTokenizer;

public class Main {
    public static void main(String[] args) {
        FastScanner in = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out);
        TaskD solver = new TaskD();
        solver.solve(in, out);
        out.flush();
        out.close();
    }

    static class TaskD {
        public void solve(FastScanner in, PrintWriter out) {
            int n = in.nextInt();
            int k = in.nextInt();
            char[][] grid = new char[n][];
            for (int i = 0; i < n; i++) {
                grid[i] = in.next().toCharArray();
            }

            int[] rMin = new int[n];
            int[] rMax = new int[n];
            Arrays.fill(rMin, -1);
            Arrays.fill(rMax, -1);

            int[] cMin = new int[n];
            int[] cMax = new int[n];
            Arrays.fill(cMin, -1);
            Arrays.fill(cMax, -1);

            // Compute bounding indices for 'B' characters
            computeBounds(grid, rMin, rMax, true);
            computeBounds(grid, cMin, cMax, false);

            // Difference array for range updates. Size n+1 avoids boundary checks.
            int[][] diff = new int[n][n + 1];
            int base = 0;

            // Process rows
            for (int i = 0; i < n; i++) {
                if (rMin[i] == -1 && rMax[i] == -1) {
                    base++;
                } else if (rMax[i] - rMin[i] < k) {
                    int tMin = Math.max(rMax[i] - k + 1, 0);
                    int tMax = rMin[i] + 1;
                    for (int j = Math.max(i - k + 1, 0); j <= i; j++) {
                        diff[j][tMin]++;
                        diff[j][tMax]--;
                    }
                }
            }

            // Process columns
            for (int i = 0; i < n; i++) {
                if (cMin[i] == -1 && cMax[i] == -1) {
                    base++;
                } else if (cMax[i] - cMin[i] < k) {
                    int tMin = Math.max(i - k + 1, 0);
                    int tMax = i + 1;
                    for (int j = Math.max(cMax[i] - k + 1, 0); j <= cMin[i]; j++) {
                        diff[j][tMin]++;
                        diff[j][tMax]--;
                    }
                }
            }

            // Compute prefix sums and find the maximum overlap
            int ans = 0;
            for (int i = 0; i < n; i++) {
                int current = 0;
                for (int j = 0; j < n; j++) {
                    current += diff[i][j];
                    if (current > ans) {
                        ans = current;
                    }
                }
            }

            out.println(base + ans);
        }

        /**
         * Computes the minimum and maximum indices of 'B' characters for each row or column.
         *
         * @param grid  The character grid
         * @param min   Array to store minimum indices
         * @param max   Array to store maximum indices
         * @param isRow True to process rows, false to process columns
         */
        private void computeBounds(char[][] grid, int[] min, int[] max, boolean isRow) {
            int size = grid.length;
            for (int i = 0; i < size; i++) {
                for (int j = 0; j < size; j++) {
                    char cell = isRow ? grid[i][j] : grid[j][i];
                    if (cell == 'B') {
                        if (min[i] == -1 || j < min[i]) {
                            min[i] = j;
                        }
                        if (max[i] == -1 || j > max[i]) {
                            max[i] = j;
                        }
                    }
                }
            }
        }
    }

    /**
     * Fast input reader using BufferedReader and StringTokenizer.
     * Replaces the original line-based tokenizer for better robustness and standard practices.
     */
    static class FastScanner {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastScanner(InputStream inputStream) {
            reader = new BufferedReader(new InputStreamReader(inputStream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            String token = next();
            if (token == null) throw new RuntimeException("Unexpected end of input");
            return Integer.parseInt(token);
        }
    }
}

import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) {
        FastScanner sc = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out);
        new WhiteLinesSolver().solve(sc, out);
        out.flush();
    }

    /**
     * Solves the WhiteLines problem using O(n^2) sliding window technique.
     */
    static class WhiteLinesSolver {
        public void solve(FastScanner sc, PrintWriter out) {
            int n = sc.nextInt();
            int k = sc.nextInt();
            char[][] grid = new char[n][n];
            for (int i = 0; i < n; i++) {
                grid[i] = sc.next().toCharArray();
            }

            // 1. Count black cells per row and column
            int[] blackCountRow = new int[n];
            int[] blackCountCol = new int[n];
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < n; j++) {
                    if (grid[i][j] == 'B') {
                        blackCountRow[i]++;
                        blackCountCol[j]++;
                    }
                }
            }

            // 2. Count rows and columns with zero black cells (these always contribute)
            int zeroCount = 0;
            for (int count : blackCountRow) if (count == 0) zeroCount++;
            for (int count : blackCountCol) if (count == 0) zeroCount++;

            // 3. Mark valid horizontal windows of length k
            // isValidHoriz[r][c] = 1 if the horizontal window starting at column c in row r
            // contains exactly all black cells of row r.
            int[][] isValidHoriz = new int[n][n];
            for (int r = 0; r < n; r++) {
                if (blackCountRow[r] == 0) continue; // Cannot be valid if row has no blacks

                int currentBlacks = 0;
                for (int c = 0; c < k; c++) {
                    if (grid[r][c] == 'B') currentBlacks++;
                }
                if (currentBlacks == blackCountRow[r]) {
                    isValidHoriz[r][0] = 1;
                }
                for (int c = 1; c <= n - k; c++) {
                    if (grid[r][c - 1] == 'B') currentBlacks--;
                    if (grid[r][c + k - 1] == 'B') currentBlacks++;
                    if (currentBlacks == blackCountRow[r]) {
                        isValidHoriz[r][c] = 1;
                    }
                }
            }

            // 4. Mark valid vertical windows of length k
            // isValidVert[r][c] = 1 if the vertical window starting at row r in column c
            // contains exactly all black cells of column c.
            int[][] isValidVert = new int[n][n];
            for (int c = 0; c < n; c++) {
                if (blackCountCol[c] == 0) continue;

                int currentBlacks = 0;
                for (int r = 0; r < k; r++) {
                    if (grid[r][c] == 'B') currentBlacks++;
                }
                if (currentBlacks == blackCountCol[c]) {
                    isValidVert[0][c] = 1;
                }
                for (int r = 1; r <= n - k; r++) {
                    if (grid[r - 1][c] == 'B') currentBlacks--;
                    if (grid[r + k - 1][c] == 'B') currentBlacks++;
                    if (currentBlacks == blackCountCol[c]) {
                        isValidVert[r][c] = 1;
                    }
                }
            }

            // 5. Count how many valid horizontal windows intersect each k x k square
            // horizIntersectCount[r][c] = sum of isValidHoriz[x][c] for x in [r, r+k-1]
            int[][] horizIntersectCount = new int[n][n];
            for (int c = 0; c <= n - k; c++) {
                int sum = 0;
                for (int r = 0; r < k; r++) sum += isValidHoriz[r][c];
                horizIntersectCount[0][c] = sum;
                for (int r = 1; r <= n - k; r++) {
                    sum -= isValidHoriz[r - 1][c];
                    sum += isValidHoriz[r + k - 1][c];
                    horizIntersectCount[r][c] = sum;
                }
            }

            // 6. Count how many valid vertical windows intersect each k x k square
            // vertIntersectCount[r][c] = sum of isValidVert[r][x] for x in [c, c+k-1]
            int[][] vertIntersectCount = new int[n][n];
            for (int r = 0; r <= n - k; r++) {
                int sum = 0;
                for (int c = 0; c < k; c++) sum += isValidVert[r][c];
                vertIntersectCount[r][0] = sum;
                for (int c = 1; c <= n - k; c++) {
                    sum -= isValidVert[r][c - 1];
                    sum += isValidVert[r][c + k - 1];
                    vertIntersectCount[r][c] = sum;
                }
            }

            // 7. Find the maximum combined intersections across all possible k x k positions
            long maxCrossings = 0;
            for (int r = 0; r <= n - k; r++) {
                for (int c = 0; c <= n - k; c++) {
                    maxCrossings = Math.max(maxCrossings, horizIntersectCount[r][c] + vertIntersectCount[r][c]);
                }
            }

            out.println(maxCrossings + zeroCount);
        }
    }

    /**
     * Fast I/O helper class for competitive programming.
     */
    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        public String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

/**
 * Solves a grid coverage problem by finding a k x k subgrid that maximizes
 * the number of fully covered empty rows, empty columns, and rows/columns
 * whose 'B' markers fall entirely within the subgrid boundaries.
 */
public class GridLineCoverageSolver {

    private final FastScanner sc;
    private final PrintWriter out;

    public GridLineCoverageSolver(FastScanner sc, PrintWriter out) {
        this.sc = sc;
        this.out = out;
    }

    /**
     * Entry point for the solution.
     */
    public static void main(String[] args) {
        FastScanner sc = new FastScanner();
        PrintWriter out = new PrintWriter(System.out);
        try {
            new GridLineCoverageSolver(sc, out).solve();
        } finally {
            out.flush();
        }
    }

    /**
     * Core logic for reading input, computing bounds, and finding the optimal window.
     */
    void solve() {
        int n = sc.nextInt();
        int k = sc.nextInt();

        // rowBounds[i] stores {minCol, maxCol} of 'B' characters in row i
        int[][] rowBounds = new int[n][2];
        // colBounds[j] stores {minRow, maxRow} of 'B' characters in column j
        int[][] colBounds = new int[n][2];

        // Initialize bounds with sentinel values indicating "empty"
        for (int i = 0; i < n; i++) {
            rowBounds[i][0] = Integer.MAX_VALUE;
            rowBounds[i][1] = -1;
            colBounds[i][0] = Integer.MAX_VALUE;
            colBounds[i][1] = -1;
        }

        // Read grid and populate bounds
        for (int i = 0; i < n; i++) {
            String line = sc.next();
            for (int j = 0; j < n; j++) {
                if (line.charAt(j) == 'B') {
                    rowBounds[i][0] = Math.min(rowBounds[i][0], j);
                    rowBounds[i][1] = Math.max(rowBounds[i][1], j);
                    colBounds[j][0] = Math.min(colBounds[j][0], i);
                    colBounds[j][1] = Math.max(colBounds[j][1], i);
                }
            }
        }

        // Count completely empty rows and columns in the entire grid
        int emptyRowCount = 0;
        int emptyColCount = 0;
        for (int i = 0; i < n; i++) {
            if (rowBounds[i][0] == Integer.MAX_VALUE) emptyRowCount++;
            if (colBounds[i][0] == Integer.MAX_VALUE) emptyColCount++;
        }

        // Special case: window covers the entire grid
        // In this case, every row/col is either fully empty or fully contained,
        // so the maximum coverage is always n (empty rows) + n (empty cols) = 2n.
        if (n == k) {
            out.println(2 * n);
            return;
        }

        int windowEnd = n - k;
        // rowCountInWindow[startRow][startCol] counts how many rows in the vertical
        // window [startRow, startRow+k-1] are fully contained within columns [startCol, startCol+k-1]
        int[][] rowCountInWindow = new int[windowEnd + 1][windowEnd + 1];

        // colCountInWindow[startRow][startCol] counts how many columns in the horizontal
        // window [startCol, startCol+k-1] are fully contained within rows [startRow, startRow+k-1]
        int[][] colCountInWindow = new int[windowEnd + 1][windowEnd + 1];

        // Compute row containment counts using a sliding window
        for (int startCol = 0; startCol <= windowEnd; startCol++) {
            int currentCount = 0;
            for (int r = 0; r < k; r++) {
                if (isRowContained(rowBounds[r], startCol, k)) {
                    currentCount++;
                }
            }
            rowCountInWindow[0][startCol] = currentCount;

            for (int startRow = 1; startRow <= windowEnd; startRow++) {
                currentCount = rowCountInWindow[startRow - 1][startCol];
                if (isRowContained(rowBounds[startRow - 1], startCol, k)) {
                    currentCount--;
                }
                if (isRowContained(rowBounds[startRow + k - 1], startCol, k)) {
                    currentCount++;
                }
                rowCountInWindow[startRow][startCol] = currentCount;
            }
        }

        // Compute column containment counts using a sliding window
        for (int startRow = 0; startRow <= windowEnd; startRow++) {
            int currentCount = 0;
            for (int c = 0; c < k; c++) {
                if (isColContained(colBounds[c], startRow, k)) {
                    currentCount++;
                }
            }
            colCountInWindow[startRow][0] = currentCount;

            for (int startCol = 1; startCol <= windowEnd; startCol++) {
                currentCount = colCountInWindow[startRow][startCol - 1];
                if (isColContained(colBounds[startCol - 1], startRow, k)) {
                    currentCount--;
                }
                if (isColContained(colBounds[startCol + k - 1], startRow, k)) {
                    currentCount++;
                }
                colCountInWindow[startRow][startCol] = currentCount;
            }
        }

        // Find the maximum combined coverage across all valid k x k windows
        int maxCoverage = 0;
        for (int i = 0; i <= windowEnd; i++) {
            for (int j = 0; j <= windowEnd; j++) {
                int currentCoverage = emptyRowCount + emptyColCount +
                                      rowCountInWindow[i][j] + colCountInWindow[i][j];
                if (currentCoverage > maxCoverage) {
                    maxCoverage = currentCoverage;
                }
            }
        }

        out.println(maxCoverage);
    }

    /**
     * Checks if a row's 'B' markers are fully contained within a column window.
     */
    private boolean isRowContained(int[] rowBounds, int startCol, int k) {
        return rowBounds[0] != Integer.MAX_VALUE &&
               rowBounds[0] >= startCol &&
               rowBounds[1] <= startCol + k - 1;
    }

    /**
     * Checks if a column's 'B' markers are fully contained within a row window.
     */
    private boolean isColContained(int[] colBounds, int startRow, int k) {
        return colBounds[0] != Integer.MAX_VALUE &&
               colBounds[0] >= startRow &&
               colBounds[1] <= startRow + k - 1;
    }

    /**
     * Fast input scanner using BufferedReader and StringTokenizer.
     * Replaces custom byte-buffer implementations for better maintainability
     * while retaining competitive programming performance.
     */
    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input", e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            String token = next();
            return token == null ? 0 : Integer.parseInt(token);
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

public class GridBlockCounter {

    public static void main(String[] args) {
        FastReader reader = new FastReader();
        PrintWriter out = new PrintWriter(System.out);

        try {
            int gridSize = reader.nextInt();
            int windowSize = reader.nextInt();

            char[][] grid = new char[gridSize][gridSize];
            for (int i = 0; i < gridSize; i++) {
                grid[i] = reader.next().toCharArray();
            }

            int[][] verticalDP = computeVerticalDP(grid, gridSize);
            int[][] horizontalDP = computeHorizontalDP(grid, gridSize);

            int initialCount = computeInitialCount(verticalDP, horizontalDP, gridSize);

            int[][] verticalPrefixSum = computeVerticalPrefixSum(verticalDP, windowSize, gridSize);
            int[][] horizontalPrefixSum = computeHorizontalPrefixSum(horizontalDP, windowSize, gridSize);

            long maxCount = findMaxCount(verticalPrefixSum, horizontalPrefixSum, initialCount, windowSize, gridSize);

            out.println(maxCount);
        } catch (Exception e) {
            out.println("Error processing input: " + e.getMessage());
        } finally {
            out.flush();
        }
    }

    /**
     * Computes vertical consecutive 'B' counts propagating from top to bottom.
     */
    private static int[][] computeVerticalDP(char[][] grid, int n) {
        int[][] dpv = new int[n][n];
        for (int j = 0; j < n; j++) {
            for (int i = 0; i < n; i++) {
                if (grid[i][j] == 'B') {
                    dpv[i][j] = (i > 0 ? dpv[i - 1][j] : 0) + 1;
                } else {
                    dpv[i][j] = (i > 0 ? dpv[i - 1][j] : 0);
                }
            }
        }
        return dpv;
    }

    /**
     * Computes horizontal consecutive 'B' counts propagating from left to right.
     */
    private static int[][] computeHorizontalDP(char[][] grid, int n) {
        int[][] dph = new int[n][n];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 'B') {
                    dph[i][j] = (j > 0 ? dph[i][j - 1] : 0) + 1;
                } else {
                    dph[i][j] = (j > 0 ? dph[i][j - 1] : 0);
                }
            }
        }
        return dph;
    }

    /**
     * Counts baseline segments where the trailing cell in a row/column is 0.
     */
    private static int computeInitialCount(int[][] verticalDP, int[][] horizontalDP, int n) {
        int count = 0;
        for (int j = 0; j < n; j++) {
            if (verticalDP[n - 1][j] == 0) {
                count++;
            }
        }
        for (int i = 0; i < n; i++) {
            if (horizontalDP[i][n - 1] == 0) {
                count++;
            }
        }
        return count;
    }

    /**
     * Computes prefix sums for valid vertical segments of length k.
     */
    private static int[][] computeVerticalPrefixSum(int[][] verticalDP, int k, int n) {
        int[][] spv = new int[n][n];
        for (int i = k - 1; i < n; i++) {
            int inc = 0;
            for (int j = 0; j < n; j++) {
                boolean isValidSegment = (i - k >= 0)
                        ? (verticalDP[i][j] - verticalDP[i - k][j] == verticalDP[n - 1][j] && verticalDP[n - 1][j] > 0)
                        : (verticalDP[i][j] == verticalDP[n - 1][j] && verticalDP[n - 1][j] > 0);

                if (isValidSegment) {
                    inc++;
                }
                spv[i][j] = (j > 0) ? spv[i][j - 1] + inc : inc;
            }
        }
        return spv;
    }

    /**
     * Computes prefix sums for valid horizontal segments of length k.
     */
    private static int[][] computeHorizontalPrefixSum(int[][] horizontalDP, int k, int n) {
        int[][] sph = new int[n][n];
        for (int i = 0; i < n; i++) {
            int inc = 0;
            for (int j = k - 1; j < n; j++) {
                boolean isValidSegment = (j - k >= 0)
                        ? (horizontalDP[i][j] - horizontalDP[i][j - k] == horizontalDP[i][n - 1] && horizontalDP[i][n - 1] > 0)
                        : (horizontalDP[i][j] == horizontalDP[i][n - 1] && horizontalDP[i][n - 1] > 0);

                if (isValidSegment) {
                    inc++;
                }
                sph[i][j] = (i > 0) ? sph[i - 1][j] + inc : inc;
            }
        }
        return sph;
    }

    /**
     * Finds the maximum count across all k x k subgrids.
     */
    private static long findMaxCount(int[][] verticalPrefixSum, int[][] horizontalPrefixSum, 
                                     int initialCount, int k, int n) {
        long maxCount = initialCount;
        for (int i = k - 1; i < n; i++) {
            for (int j = k - 1; j < n; j++) {
                long count = initialCount;
                count += (j >= k) ? verticalPrefixSum[i][j] - verticalPrefixSum[i][j - k] : verticalPrefixSum[i][j];
                count += (i >= k) ? horizontalPrefixSum[i][j] - horizontalPrefixSum[i - k][j] : horizontalPrefixSum[i][j];
                maxCount = Math.max(maxCount, count);
            }
        }
        return maxCount;
    }

    /**
     * Optimized fast input reader for competitive programming.
     */
    static class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input", e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            String s = next();
            return s == null ? 0 : Integer.parseInt(s);
        }

        long nextLong() {
            String s = next();
            return s == null ? 0L : Long.parseLong(s);
        }

        double nextDouble() {
            String s = next();
            return s == null ? 0.0 : Double.parseDouble(s);
        }
    }
}

import java.io.*;
import java.nio.file.Files;
import java.nio.file.Paths;
import java.util.StringTokenizer;

/**
 * Solves the grid coverage problem:
 * Finds a k x k square that maximizes the number of fully covered rows and columns,
 * then adds the count of already empty rows and columns.
 */
public class GridCoverageSolver {

    private static BufferedReader br;
    private static PrintWriter out;
    private static StringTokenizer st;

    public static void main(String[] args) {
        try {
            initIO();
            solve();
            out.flush();
        } catch (IOException e) {
            System.err.println("I/O Error: " + e.getMessage());
            e.printStackTrace();
        }
    }

    /**
     * Initializes input/output streams. Attempts to read from TEMPLATE.in 
     * and write to TEMPLATE.out. Falls back to stdin/stdout if files are unavailable.
     */
    private static void initIO() throws IOException {
        try {
            br = Files.newBufferedReader(Paths.get("TEMPLATE.in"));
            out = new PrintWriter(new BufferedWriter(new FileWriter("TEMPLATE.out")));
        } catch (IOException e) {
            br = new BufferedReader(new InputStreamReader(System.in));
            out = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)));
        }
        st = new StringTokenizer("");
    }

    private static String next() throws IOException {
        while (!st.hasMoreTokens()) {
            String line = br.readLine();
            if (line == null) return null;
            st = new StringTokenizer(line);
        }
        return st.nextToken();
    }

    private static int nextInt() throws IOException {
        String token = next();
        return token == null ? 0 : Integer.parseInt(token);
    }

    private static void solve() throws IOException {
        int n = nextInt();
        int k = nextInt();

        // Read grid
        boolean[][] grid = new boolean[n][n];
        for (int i = 0; i < n; i++) {
            String line = next();
            for (int j = 0; j < n; j++) {
                grid[i][j] = line.charAt(j) == 'B';
            }
        }

        // If k exceeds grid size, no k x k square can fit.
        if (k > n) {
            out.println(countEmptyLines(grid, n));
            return;
        }

        // rowCover[i][j] = 1 if horizontal window of length k starting at column j
        // completely covers all 'B's in row i
        int[][] rowCover = new int[n][n - k + 1];
        for (int i = 0; i < n; i++) {
            int firstB = -1, lastB = -1;
            for (int j = 0; j < n; j++) {
                if (grid[i][j]) {
                    if (firstB == -1) firstB = j;
                    lastB = j;
                }
            }
            if (firstB != -1) {
                for (int j = 0; j <= n - k; j++) {
                    if (j <= firstB && j + k - 1 >= lastB) {
                        rowCover[i][j] = 1;
                    }
                }
            }
        }

        // colCover[i][j] = 1 if vertical window of length k starting at row i
        // completely covers all 'B's in column j
        int[][] colCover = new int[n - k + 1][n];
        for (int j = 0; j < n; j++) {
            int firstB = -1, lastB = -1;
            for (int i = 0; i < n; i++) {
                if (grid[i][j]) {
                    if (firstB == -1) firstB = i;
                    lastB = i;
                }
            }
            if (firstB != -1) {
                for (int i = 0; i <= n - k; i++) {
                    if (i <= firstB && i + k - 1 >= lastB) {
                        colCover[i][j] = 1;
                    }
                }
            }
        }

        // Compute sliding window sums for rowCover (vertical direction)
        int[][] windowRowSums = new int[n - k + 1][n - k + 1];
        for (int j = 0; j < n - k + 1; j++) {
            int currentSum = 0;
            for (int i = 0; i < k; i++) {
                currentSum += rowCover[i][j];
            }
            windowRowSums[0][j] = currentSum;
            for (int i = 1; i < n - k + 1; i++) {
                currentSum += rowCover[i + k - 1][j] - rowCover[i - 1][j];
                windowRowSums[i][j] = currentSum;
            }
        }

        // Compute sliding window sums for colCover (horizontal direction)
        int[][] windowColSums = new int[n - k + 1][n - k + 1];
        for (int i = 0; i < n - k + 1; i++) {
            int currentSum = 0;
            for (int j = 0; j < k; j++) {
                currentSum += colCover[i][j];
            }
            windowColSums[i][0] = currentSum;
            for (int j = 1; j < n - k + 1; j++) {
                currentSum += colCover[i][j + k - 1] - colCover[i][j - 1];
                windowColSums[i][j] = currentSum;
            }
        }

        // Count completely empty rows and columns
        int emptyLines = countEmptyLines(grid, n);

        // Find the maximum number of fully covered lines in any k x k square
        int maxCovered = 0;
        int limit = n - k + 1;
        for (int i = 0; i < limit; i++) {
            for (int j = 0; j < limit; j++) {
                int total = windowRowSums[i][j] + windowColSums[i][j];
                if (total > maxCovered) {
                    maxCovered = total;
                }
            }
        }

        out.println(maxCovered + emptyLines);
    }

    /**
     * Counts the number of rows and columns that contain no 'B's.
     */
    private static int countEmptyLines(boolean[][] grid, int n) {
        int emptyLines = 0;
        for (int i = 0; i < n; i++) {
            boolean empty = true;
            for (int j = 0; j < n; j++) {
                if (grid[i][j]) {
                    empty = false;
                    break;
                }
            }
            if (empty) emptyLines++;
        }
        for (int j = 0; j < n; j++) {
            boolean empty = true;
            for (int i = 0; i < n; i++) {
                if (grid[i][j]) {
                    empty = false;
                    break;
                }
            }
            if (empty) emptyLines++;
        }
        return emptyLines;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

public class Main {
    public static void main(String[] args) {
        new Main().run();
    }

    private FastReader in = new FastReader();
    private PrintWriter out = new PrintWriter(System.out);

    public void run() {
        try {
            solve();
        } catch (Exception e) {
            e.printStackTrace();
        } finally {
            out.flush();
        }
    }

    private void solve() {
        // Read grid dimensions and window size
        int n = in.nextInt();
        int k = in.nextInt();

        // Grid storage: 1 for 'W' (occupied), 0 for others (empty)
        // We use an integer array to match the original logic's 0/1 distinction.
        int[][] grid = new int[n][n];
        for (int i = 0; i < n; i++) {
            String rowStr = in.next();
            for (int j = 0; j < n; j++) {
                grid[i][j] = (rowStr.charAt(j) == 'W') ? 1 : 0;
            }
        }

        // Arrays to store the boundaries of empty space (0s) for each row and column.
        // If a row/col has no 0s, the bounds will indicate an invalid range (e.g., Left > Right).

        // Row Bounds:
        // rowLeftBound[i]: Index of the first 0 in row i.
        // rowRightBound[i]: Index of the last 0 in row i.
        int[] rowLeftBound = new int[n];
        int[] rowRightBound = new int[n];

        // Column Bounds:
        // colTopBound[j]: Index of the first 0 in column j.
        // colBottomBound[j]: Index of the last 0 in column j.
        int[] colTopBound = new int[n];
        int[] colBottomBound = new int[n];

        // Compute Row Bounds
        for (int i = 0; i < n; i++) {
            rowLeftBound[i] = n; // Default to 'not found'
            rowRightBound[i] = -1; // Default to 'not found'
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 0) {
                    // If this is the first 0 found, set the left bound
                    if (rowLeftBound[i] == n) {
                        rowLeftBound[i] = j;
                    }
                    // Update right bound (will end up being the last 0)
                    rowRightBound[i] = j;
                }
            }
        }

        // Compute Column Bounds
        for (int j = 0; j < n; j++) {
            colTopBound[j] = n; // Default to 'not found'
            colBottomBound[j] = -1; // Default to 'not found'
            for (int i = 0; i < n; i++) {
                if (grid[i][j] == 0) {
                    // If this is the first 0 found, set the top bound
                    if (colTopBound[j] == n) {
                        colTopBound[j] = i;
                    }
                    // Update bottom bound (will end up being the last 0)
                    colBottomBound[j] = i;
                }
            }
        }

        // Prefix sums for "Full Rows" (Rows containing no 0s, i.e., entirely 'W')
        // A row is considered full if rowLeftBound[i] == n.
        int[] fullRowPrefixCount = new int[n];
        int count = 0;
        for (int i = 0; i < n; i++) {
            if (rowLeftBound[i] == n) {
                count++;
            }
            fullRowPrefixCount[i] = count;
        }

        // Prefix sums for "Full Cols"
        // A col is considered full if colTopBound[j] == n.
        int[] fullColPrefixCount = new int[n];
        count = 0;
        for (int j = 0; j < n; j++) {
            if (colTopBound[j] == n) {
                count++;
            }
            fullColPrefixCount[j] = count;
        }

        // DP Arrays
        // windowFullRowCount[i][j]: Number of rows in the vertical window [i, i+k-1] 
        //                          that are fully covered horizontally by the window columns [j, j+k-1].
        int[][] windowFullRowCount = new int[n][n];

        // windowFullColCount[i][j]: Number of cols in the horizontal window [j, j+k-1]
        //                          that are fully covered vertically by the window rows [i, i+k-1].
        int[][] windowFullColCount = new int[n][n];

        int maxScore = 0;

        // Iterate through all possible top-left corners (i, j) of the k x k window
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                int windowTop = i;
                int windowBottom = i + k - 1;
                int windowLeft = j;
                int windowRight = j + k - 1;

                // Check if the window fits within the grid boundaries
                if (windowBottom >= n || windowRight >= n) {
                    continue;
                }

                // --- Calculate windowFullRowCount (dp1 equivalent) ---
                if (windowTop == 0) {
                    // Base case: Initialize for the first row of windows (i=0)
                    // Count how many rows in [0, k-1] are fully covered by columns [j, j+k-1]
                    for (int p = 0; p < k; p++) {
                        int r = p; // Row index
                        // A row is covered if the window columns span the entire range of 0s in that row
                        if (windowLeft <= rowLeftBound[r] && windowRight >= rowRightBound[r]) {
                            windowFullRowCount[windowTop][windowLeft]++;
                        }
                    }
                } else {
                    // Sliding window update: Shift window down by 1 row
                    // Take count from the window directly above
                    int prevCount = windowFullRowCount[windowTop - 1][windowLeft];

                    // Remove the row leaving the window (top row of previous window)
                    int leavingRow = windowTop - 1;
                    if (windowLeft <= rowLeftBound[leavingRow] && windowRight >= rowRightBound[leavingRow]) {
                        prevCount--;
                    }

                    // Add the row entering the window (new bottom row)
                    int enteringRow = windowBottom;
                    if (windowLeft <= rowLeftBound[enteringRow] && windowRight >= rowRightBound[enteringRow]) {
                        prevCount++;
                    }

                    windowFullRowCount[windowTop][windowLeft] = prevCount;
                }

                // --- Calculate windowFullColCount (dp2 equivalent) ---
                if (windowLeft == 0) {
                    // Base case: Initialize for the first column of windows (j=0)
                    // Count how many cols in [0, k-1] are fully covered by rows [i, i+k-1]
                    for (int p = 0; p < k; p++) {
                        int c = p; // Col index
                        // A col is covered if the window rows span the entire range of 0s in that col
                        if (windowTop <= colTopBound[c] && windowBottom >= colBottomBound[c]) {
                            windowFullColCount[windowTop][windowLeft]++;
                        }
                    }
                } else {
                    // Sliding window update: Shift window right by 1 col
                    // Take count from the window directly to the left
                    int prevCount = windowFullColCount[windowTop][windowLeft - 1];

                    // Remove the col leaving the window (left col of previous window)
                    int leavingCol = windowLeft - 1;
                    if (windowTop <= colTopBound[leavingCol] && windowBottom >= colBottomBound[leavingCol]) {
                        prevCount--;
                    }

                    // Add the col entering the window (new right col)
                    int enteringCol = windowRight;
                    if (windowTop <= colTopBound[enteringCol] && windowBottom >= colBottomBound[enteringCol]) {
                        prevCount++;
                    }

                    windowFullColCount[windowTop][windowLeft] = prevCount;
                }

                // --- Calculate Score ---
                // The score is the sum of:
                // 1. Full rows inside the window (covered horizontally)
                // 2. Full cols inside the window (covered vertically)
                // 3. Full rows outside the window (above and below)
                // 4. Full cols outside the window (left and right)

                int currentScore = windowFullRowCount[windowTop][windowLeft] 
                                 + windowFullColCount[windowTop][windowLeft];

                // Full rows strictly above the window
                if (windowTop > 0) {
                    currentScore += fullRowPrefixCount[windowTop - 1];
                }
                // Full rows strictly below the window
                currentScore += fullRowPrefixCount[n - 1] - fullRowPrefixCount[windowBottom];

                // Full cols strictly to the left of the window
                if (windowLeft > 0) {
                    currentScore += fullColPrefixCount[windowLeft - 1];
                }
                // Full cols strictly to the right of the window
                currentScore += fullColPrefixCount[n - 1] - fullColPrefixCount[windowRight];

                if (currentScore > maxScore) {
                    maxScore = currentScore;
                }
            }
        }

        out.println(maxScore);
    }

    /**
     * FastReader utility class for efficient input reading.
     */
    static class FastReader {
        BufferedReader br;
        StringTokenizer st;

        public FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) {
                        return null;
                    }
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    e.printStackTrace();
                    return null;
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            String s = next();
            return s == null ? 0 : Integer.parseInt(s);
        }

        long nextLong() {
            String s = next();
            return s == null ? 0L : Long.parseLong(s);
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

/**
 * Solves the WhiteLines problem by calculating the maximum number of empty rows 
 * and columns achievable by removing a k x k window from an n x n grid.
 * 
 * Refactoring improvements:
 * - Extracted logic into well-named, single-responsibility methods
 * - Replaced magic numbers (e.g., 2*n) with explicit boolean flags
 * - Standardized sliding window implementations to reduce duplication
 * - Added comprehensive JavaDoc and inline comments
 * - Improved input/output handling and error resilience
 * - Used precise imports instead of wildcard imports
 */
public class WhiteLines {

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner();
        PrintWriter out = new PrintWriter(System.out);
        solve(scanner, out);
        out.flush();
    }

    private static void solve(FastScanner scanner, PrintWriter out) {
        int n = scanner.nextInt();
        int k = scanner.nextInt();
        boolean[][] grid = readGrid(n, scanner);

        int[] nonWhiteCountsPerRow = new int[n];
        int[] nonWhiteCountsPerCol = new int[n];
        boolean[] isRowAlreadyEmpty = new boolean[n];
        boolean[] isColAlreadyEmpty = new boolean[n];

        calculateEmptyLinesAndCounts(n, grid, nonWhiteCountsPerRow, nonWhiteCountsPerCol, 
                                     isRowAlreadyEmpty, isColAlreadyEmpty);
        int baseEmptyLines = countAlreadyEmpty(isRowAlreadyEmpty, isColAlreadyEmpty);

        boolean[][] colBecomesEmpty = computeWindowStatus(n, k, grid, nonWhiteCountsPerCol, true);
        boolean[][] rowBecomesEmpty = computeWindowStatus(n, k, grid, nonWhiteCountsPerRow, false);

        int[][] emptyLinesAddedByWindow = computeTotalEmptyLines(n, k, colBecomesEmpty, rowBecomesEmpty);
        int maxAdditionalEmptyLines = findMaxInMatrix(emptyLinesAddedByWindow);

        out.println(baseEmptyLines + maxAdditionalEmptyLines);
    }

    /**
     * Reads the n x n grid from input.
     * 'W' maps to true, any other character maps to false.
     */
    private static boolean[][] readGrid(int n, FastScanner scanner) {
        boolean[][] grid = new boolean[n][n];
        for (int i = 0; i < n; i++) {
            String line = scanner.next();
            for (int j = 0; j < n; j++) {
                grid[i][j] = line.charAt(j) == 'W';
            }
        }
        return grid;
    }

    /**
     * Counts non-white cells per row/column and identifies already empty lines.
     */
    private static void calculateEmptyLinesAndCounts(int n, boolean[][] grid, 
                                                     int[] nonWhiteRows, int[] nonWhiteCols,
                                                     boolean[] rowEmpty, boolean[] colEmpty) {
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (!grid[i][j]) {
                    nonWhiteRows[i]++;
                    nonWhiteCols[j]++;
                }
            }
        }
        for (int i = 0; i < n; i++) {
            if (nonWhiteRows[i] == 0) rowEmpty[i] = true;
            if (nonWhiteCols[i] == 0) colEmpty[i] = true;
        }
    }

    /**
     * Returns the total number of rows and columns that are already empty.
     */
    private static int countAlreadyEmpty(boolean[] rowEmpty, boolean[] colEmpty) {
        int count = 0;
        for (boolean b : rowEmpty) if (b) count++;
        for (boolean b : colEmpty) if (b) count++;
        return count;
    }

    /**
     * Computes a boolean matrix indicating whether a line becomes empty when a 
     * sliding window of size k is removed.
     *
     * @param slideOverRows If true, computes for columns (slides over row indices).
     *                      If false, computes for rows (slides over column indices).
     */
    private static boolean[][] computeWindowStatus(int n, int k, boolean[][] grid, 
                                                   int[] totalCounts, boolean slideOverRows) {
        boolean[][] status = new boolean[n][n - k + 1];

        for (int i = 0; i < n; i++) {
            int windowCount = 0;

            // Initialize first window
            for (int j = 0; j < k; j++) {
                if (!grid[slideOverRows ? j : i][slideOverRows ? i : j]) {
                    windowCount++;
                }
            }
            if (windowCount == totalCounts[i]) {
                status[i][0] = true;
            }

            // Slide window across the grid
            for (int j = k; j < n; j++) {
                if (!grid[slideOverRows ? j : i][slideOverRows ? i : j]) windowCount++;
                if (!grid[slideOverRows ? j - k : i][slideOverRows ? i : j - k]) windowCount--;

                if (windowCount == totalCounts[i]) {
                    status[i][j - k + 1] = true;
                }
            }
        }
        return status;
    }

    /**
     * Computes a 2D sliding window sum over the 'colBecomesEmpty' and 'rowBecomesEmpty' matrices.
     * amt[r][c] represents the total number of empty lines gained by removing a k x k window 
     * starting at row r and column c.
     */
    private static int[][] computeTotalEmptyLines(int n, int k, boolean[][] colBecomesEmpty, 
                                                  boolean[][] rowBecomesEmpty) {
        int[][] amt = new int[n - k + 1][n - k + 1];

        // Accumulate column contributions (slide over rows)
        for (int c = 0; c <= n - k; c++) {
            int count = 0;
            for (int r = 0; r < k; r++) {
                if (colBecomesEmpty[r][c]) count++;
            }
            amt[0][c] += count;
            for (int r = k; r < n; r++) {
                if (colBecomesEmpty[r][c]) count++;
                if (colBecomesEmpty[r - k][c]) count--;
                amt[r - k + 1][c] += count;
            }
        }

        // Accumulate row contributions (slide over columns)
        for (int r = 0; r <= n - k; r++) {
            int count = 0;
            for (int c = 0; c < k; c++) {
                if (rowBecomesEmpty[r][c]) count++;
            }
            amt[r][0] += count;
            for (int c = k; c < n; c++) {
                if (rowBecomesEmpty[r][c]) count++;
                if (rowBecomesEmpty[r][c - k]) count--;
                amt[r][c - k + 1] += count;
            }
        }
        return amt;
    }

    /**
     * Finds the maximum value in a 2D integer matrix.
     */
    private static int findMaxInMatrix(int[][] matrix) {
        int max = 0;
        for (int[] row : matrix) {
            for (int val : row) {
                if (val > max) max = val;
            }
        }
        return max;
    }

    /**
     * High-performance input scanner for competitive programming.
     */
    public static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input", e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        long nextLong() {
            return Long.parseLong(next());
        }

        double nextDouble() {
            return Double.parseDouble(next());
        }
    }
}

import java.util.Scanner;
import java.util.Arrays;

public class Solution {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        // Basic validation to prevent exceptions on empty input
        if (!sc.hasNextInt()) {
            sc.close();
            return;
        }

        int n = sc.nextInt();
        int k = sc.nextInt();

        // Bounds arrays to store the first and last index of the target character (non-'W').
        // rowBounds[i][0] stores the first index, rowBounds[i][1] stores the last index.
        int[][] rowBounds = new int[n][2];
        int[][] colBounds = new int[n][2];

        // Initialize with -1 to indicate no target character found yet
        for (int[] row : rowBounds) Arrays.fill(row, -1);
        for (int[] row : colBounds) Arrays.fill(row, -1);

        // Read grid and populate bounds
        // We process the grid row by row.
        for (int i = 0; i < n; i++) {
            String rowStr = sc.next();
            for (int j = 0; j < n; j++) {
                char ch = rowStr.charAt(j);
                // The original logic treats non-'W' characters as '0' (target).
                if (ch != 'W') { 
                    // Update row bounds
                    if (rowBounds[i][0] == -1) {
                        rowBounds[i][0] = j;
                    }
                    rowBounds[i][1] = j;

                    // Update col bounds
                    if (colBounds[j][0] == -1) {
                        colBounds[j][0] = i;
                    }
                    colBounds[j][1] = i;
                }
            }
        }

        // Count rows and columns that have no target characters.
        // These are always "satisfied" by any window, so we add their count to the final score.
        int emptyRowCount = 0;
        int emptyColCount = 0;
        for (int i = 0; i < n; i++) {
            if (rowBounds[i][0] == -1) emptyRowCount++;
            if (colBounds[i][0] == -1) emptyColCount++;
        }

        // The window size is K. The top-left corner of the window can range from (0,0) to (n-k, n-k).
        // The number of possible positions is (n - k + 1).
        int windowSize = n - k + 1;

        // rowSatisfaction[r][c] is 1 if row r is fully contained within the window starting at column c.
        // Dimensions: [n][windowSize]
        int[][] rowSatisfaction = new int[n][windowSize];
        for (int r = 0; r < n; r++) {
            if (rowBounds[r][0] == -1) continue; // Skip empty rows
            int start = rowBounds[r][0];
            int end = rowBounds[r][1];
            for (int c = 0; c < windowSize; c++) {
                // Check if the window [c, c + k - 1] covers the range [start, end]
                if (start >= c && end <= c + k - 1) {
                    rowSatisfaction[r][c] = 1;
                }
            }
        }

        // colSatisfaction[c][r] is 1 if col c is fully contained within the window starting at row r.
        // Dimensions: [n][windowSize]
        // Note: We store this as [colIndex][windowStartRow] to align with the summation logic.
        int[][] colSatisfaction = new int[n][windowSize];
        for (int c = 0; c < n; c++) {
            if (colBounds[c][0] == -1) continue; // Skip empty cols
            int start = colBounds[c][0];
            int end = colBounds[c][1];
            for (int r = 0; r < windowSize; r++) {
                // Check if the window [r, r + k - 1] covers the range [start, end]
                if (start >= r && end <= r + k - 1) {
                    colSatisfaction[c][r] = 1;
                }
            }
        }

        // Calculate sliding window sums for rows.
        // We need to sum rowSatisfaction vertically (along rows) for a window of size k.
        // rowSatisfaction is [n][windowSize]. Summing dim 0 gives [windowSize][windowSize].
        // result[r][c] will store the number of satisfied rows in the vertical strip of height k starting at row r, for a window starting at col c.
        int[][] rowWindowSum = computeSlidingWindowSum(rowSatisfaction, k);

        // Calculate sliding window sums for columns.
        // We need to sum colSatisfaction horizontally (along columns of the grid, which is dim 0 of colSatisfaction) for a window of size k.
        // colSatisfaction is [n][windowSize] (indexed [colIndex][windowStartRow]).
        // Summing dim 0 gives [windowSize][windowSize].
        // result[c][r] will store the number of satisfied columns in the horizontal strip of width k starting at col c, for a window starting at row r.
        int[][] colWindowSum = computeSlidingWindowSum(colSatisfaction, k);

        // Find the maximum score
        int maxScore = 0;
        for (int r = 0; r < windowSize; r++) {
            for (int c = 0; c < windowSize; c++) {
                // rowWindowSum[r][c] is sum of satisfied rows for window at (r, c)
                // colWindowSum[c][r] is sum of satisfied cols for window at (r, c)
                // Note the index swap for colWindowSum because of how we stored it.
                int currentScore = rowWindowSum[r][c] + colWindowSum[c][r];
                if (currentScore > maxScore) {
                    maxScore = currentScore;
                }
            }
        }

        // Add bonuses for rows/cols that have no target characters (always satisfied)
        maxScore += emptyRowCount + emptyColCount;

        System.out.println(maxScore);

        sc.close();
    }

    /**
     * Computes the sliding window sum along the first dimension (rows) of the matrix.
     * 
     * @param matrix The input matrix [M][P]
     * @param k The window size
     * @return A matrix [M - k + 1][P] where result[i][j] is the sum of matrix[i...i+k-1][j]
     */
    private static int[][] computeSlidingWindowSum(int[][] matrix, int k) {
        int m = matrix.length;
        int p = matrix[0].length;

        // Handle edge case where window is larger than matrix dimension
        if (k > m) {
            return new int[0][p];
        }

        int[][] result = new int[m - k + 1][p];

        for (int j = 0; j < p; j++) {
            int currentSum = 0;
            // Initialize the first window
            for (int i = 0; i < k; i++) {
                currentSum += matrix[i][j];
            }
            result[0][j] = currentSum;

            // Slide the window
            for (int i = 1; i < m - k + 1; i++) {
                currentSum += matrix[i + k - 1][j] - matrix[i - 1][j];
                result[i][j] = currentSum;
            }
        }
        return result;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

public class Main {

    /**
     * Fast I/O helper for competitive programming scenarios.
     */
    static class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    e.printStackTrace();
                    return null;
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            String s = next();
            return s == null ? 0 : Integer.parseInt(s);
        }

        long nextLong() {
            String s = next();
            return s == null ? 0L : Long.parseLong(s);
        }

        double nextDouble() {
            String s = next();
            return s == null ? 0.0 : Double.parseDouble(s);
        }

        String nextLine() {
            String str = "";
            try {
                str = br.readLine();
            } catch (IOException e) {
                e.printStackTrace();
            }
            return str;
        }
    }

    /**
     * Represents the first and last index of a contiguous segment in a row or column.
     */
    static class Segment {
        final int start;
        final int end;

        Segment(int start, int end) {
            this.start = start;
            this.end = end;
        }
    }

    public static void main(String[] args) {
        FastReader reader = new FastReader();
        int gridSize = reader.nextInt();
        int windowSize = reader.nextInt();

        // Guard against invalid window size
        if (windowSize > gridSize) {
            System.out.println(0);
            return;
        }

        char[][] grid = new char[gridSize][gridSize];
        for (int i = 0; i < gridSize; i++) {
            String line = reader.next();
            grid[i] = line.toCharArray();
        }

        Segment[] rowSegments = new Segment[gridSize];
        Segment[] colSegments = new Segment[gridSize];
        int emptyCount = 0;

        // Identify start and end indices of 'B' segments for each row
        for (int i = 0; i < gridSize; i++) {
            int first = -1, last = -1;
            for (int j = 0; j < gridSize; j++) {
                if (grid[i][j] == 'B') {
                    if (first == -1) first = j;
                    last = j;
                }
            }
            if (first == -1) emptyCount++;
            rowSegments[i] = new Segment(first, last);
        }

        // Identify start and end indices of 'B' segments for each column
        for (int i = 0; i < gridSize; i++) {
            int first = -1, last = -1;
            for (int j = 0; j < gridSize; j++) {
                if (grid[j][i] == 'B') {
                    if (first == -1) first = j;
                    last = j;
                }
            }
            if (first == -1) emptyCount++;
            colSegments[i] = new Segment(first, last);
        }

        // DP table to store the number of valid segments for each k x k window
        int windowLimit = gridSize - windowSize + 1;
        int[][] coverageGrid = new int[windowLimit][windowLimit];

        // Slide window horizontally across columns for each row window
        for (int r = 0; r < windowLimit; r++) {
            int count = 0;
            // Initialize with the first window
            for (int c = 0; c < windowSize; c++) {
                if (isInsideWindow(colSegments[c], r, windowSize)) {
                    count++;
                }
            }
            coverageGrid[r][0] = count;

            // Slide the window one step to the right
            for (int c = 1; c < windowLimit; c++) {
                if (isInsideWindow(colSegments[c - 1], r, windowSize)) count--;
                if (isInsideWindow(colSegments[c + windowSize - 1], r, windowSize)) count++;
                coverageGrid[r][c] = count;
            }
        }

        // Slide window vertically across rows for each column window
        for (int c = 0; c < windowLimit; c++) {
            int count = 0;
            // Initialize with the first window
            for (int r = 0; r < windowSize; r++) {
                if (isInsideWindow(rowSegments[r], c, windowSize)) {
                    count++;
                }
            }
            coverageGrid[0][c] += count;

            // Slide the window one step down
            for (int r = 1; r < windowLimit; r++) {
                if (isInsideWindow(rowSegments[r - 1], c, windowSize)) count--;
                if (isInsideWindow(rowSegments[r + windowSize - 1], c, windowSize)) count++;
                coverageGrid[r][c] += count;
            }
        }

        // Find the maximum coverage across all possible k x k windows
        int maxCoverage = 0;
        for (int r = 0; r < windowLimit; r++) {
            for (int c = 0; c < windowLimit; c++) {
                if (coverageGrid[r][c] > maxCoverage) {
                    maxCoverage = coverageGrid[r][c];
                }
            }
        }

        System.out.println(maxCoverage + emptyCount);
    }

    /**
     * Checks if a segment is fully contained within a sliding window.
     *
     * @param seg          The segment to check
     * @param windowStart  The starting index of the window
     * @param windowSize   The size of the window
     * @return true if the segment is completely inside the window, false otherwise
     */
    private static boolean isInsideWindow(Segment seg, int windowStart, int windowSize) {
        // An empty segment (-1, -1) cannot be inside any window
        if (seg.start == -1 || seg.end == -1) {
            return false;
        }
        return seg.start >= windowStart && seg.end < windowStart + windowSize;
    }
}

import java.io.*;
import java.util.StringTokenizer;

public class P578D {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);

        Task solver = new Task();
        solver.solve(in, out);

        out.close();
    }

    /**
     * Solves the grid coverage problem.
     * For each cell, calculates how many valid horizontal and vertical windows of size k
     * can cover it, then finds the maximum cross-shaped coverage plus empty rows/cols.
     */
    static class Task {
        public void solve(InputReader in, PrintWriter out) {
            int n = in.nextInt();
            int k = in.nextInt();

            char[][] grid = new char[n][n];
            for (int i = 0; i < n; i++) {
                String line = in.nextLine();
                for (int j = 0; j < n; j++) {
                    grid[i][j] = line.charAt(j);
                }
            }

            // --- Process Rows ---
            boolean[][] horizontalValid = new boolean[n][n];
            int emptyRows = 0;

            for (int i = 0; i < n; i++) {
                int minB = -1, maxB = -1;
                // Find the leftmost and rightmost 'B' in the row
                for (int j = 0; j < n; j++) {
                    if (grid[i][j] == 'B') {
                        maxB = j;
                        if (minB == -1) minB = j;
                    }
                }

                if (minB == -1) {
                    // No 'B' in this row
                    emptyRows++;
                } else if (maxB - minB + 1 <= k) {
                    // All 'B's fit within a window of size k.
                    // Mark all valid starting positions for such a window.
                    int start = Math.max(0, maxB - k + 1);
                    int end = Math.min(n - 1, minB);
                    for (int j = start; j <= end; j++) {
                        horizontalValid[i][j] = true;
                    }
                }
            }

            // --- Process Columns ---
            boolean[][] verticalValid = new boolean[n][n];
            int emptyCols = 0;

            for (int j = 0; j < n; j++) {
                int minB = -1, maxB = -1;
                // Find the topmost and bottommost 'B' in the column
                for (int i = 0; i < n; i++) {
                    if (grid[i][j] == 'B') {
                        maxB = i;
                        if (minB == -1) minB = i;
                    }
                }

                if (minB == -1) {
                    // No 'B' in this column
                    emptyCols++;
                } else if (maxB - minB + 1 <= k) {
                    // All 'B's fit within a window of size k.
                    int start = Math.max(0, maxB - k + 1);
                    int end = Math.min(n - 1, minB);
                    for (int i = start; i <= end; i++) {
                        verticalValid[i][j] = true;
                    }
                }
            }

            // --- Compute Sliding Window Coverage ---
            // horizontalCoverage[row][col] stores how many valid horizontal windows cover (row, col)
            int[][] horizontalCoverage = new int[n][n];
            for (int col = 0; col < n; col++) {
                int count = 0;
                for (int row = 0; row < n; row++) {
                    count += horizontalValid[row][col] ? 1 : 0;
                    if (row >= k) {
                        count -= horizontalValid[row - k][col] ? 1 : 0;
                    }
                    horizontalCoverage[row][col] = count;
                }
            }

            // verticalCoverage[row][col] stores how many valid vertical windows cover (row, col)
            int[][] verticalCoverage = new int[n][n];
            for (int row = 0; row < n; row++) {
                int count = 0;
                for (int col = 0; col < n; col++) {
                    count += verticalValid[row][col] ? 1 : 0;
                    if (col >= k) {
                        count -= verticalValid[row][col - k] ? 1 : 0;
                    }
                    verticalCoverage[row][col] = count;
                }
            }

            // --- Find Maximum Cross Coverage ---
            int maxCross = 0;
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < n; j++) {
                    maxCross = Math.max(maxCross, horizontalCoverage[i][j] + verticalCoverage[i][j]);
                }
            }

            out.println(maxCross + emptyRows + emptyCols);
        }
    }

    /**
     * Fast I/O helper for competitive programming.
     */
    static class InputReader {
        public BufferedReader reader;
        public StringTokenizer tokenizer;

        public InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }

        public String nextLine() {
            try {
                return reader.readLine();
            } catch (IOException e) {
                throw new RuntimeException(e);
            }
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

/**
 * Solves the empty grid coverage problem by calculating the maximum number of
 * empty rows and columns that can be covered by a k x k window.
 */
public class EmptyGridSolver {

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line = br.readLine();
        if (line == null || line.trim().isEmpty()) {
            return;
        }

        StringTokenizer st = new StringTokenizer(line);
        int gridSize = Integer.parseInt(st.nextToken());
        int windowSize = Integer.parseInt(st.nextToken());

        char[][] grid = new char[gridSize][];
        for (int i = 0; i < gridSize; i++) {
            String rowLine = br.readLine();
            grid[i] = (rowLine != null) ? rowLine.toCharArray() : new char[0];
        }

        int result = solve(grid, gridSize, windowSize);
        System.out.println(result);
    }

    /**
     * Orchestrates the calculation pipeline.
     */
    private static int solve(char[][] grid, int n, int k) {
        // 1. Identify completely empty rows and columns
        int[] isEmptyRow = new int[n];
        int[] isEmptyCol = new int[n];
        computeEmptiness(grid, n, isEmptyRow, isEmptyCol);

        // 2. Compute prefix and suffix sums for empty rows/cols
        int[] emptyColPrefix = computePrefixSuffixSums(isEmptyCol, true);
        int[] emptyColSuffix = computePrefixSuffixSums(isEmptyCol, false);
        int[] emptyRowPrefix = computePrefixSuffixSums(isEmptyRow, true);
        int[] emptyRowSuffix = computePrefixSuffixSums(isEmptyRow, false);

        // 3. Compute directional 'B' counts (prefix/suffix sums of obstacles)
        int[][] leftCounts  = computeDirectionalCounts(grid, n, true, true);
        int[][] rightCounts = computeDirectionalCounts(grid, n, true, false);
        int[][] upCounts    = computeDirectionalCounts(grid, n, false, true);
        int[][] downCounts  = computeDirectionalCounts(grid, n, false, false);

        // 4. Determine if k-length windows are empty of 'B's
        int[][] horizontalWindowEmpty = computeWindowEmptiness(leftCounts, rightCounts, n, k, true);
        int[][] verticalWindowEmpty   = computeWindowEmptiness(upCounts, downCounts, n, k, false);

        // 5. Compute sliding window sums of empty windows
        int[][] horizontalEmptyCounts = computeSlidingWindowSums(horizontalWindowEmpty, n, k, true);
        int[][] verticalEmptyCounts   = computeSlidingWindowSums(verticalWindowEmpty, n, k, false);

        // 6. Calculate and return the maximum coverage
        return calculateMaxCoverage(horizontalEmptyCounts, verticalEmptyCounts,
                emptyRowPrefix, emptyRowSuffix, emptyColPrefix, emptyColSuffix, n, k);
    }

    /**
     * Marks rows and columns that contain no 'B' characters.
     */
    private static void computeEmptiness(char[][] grid, int n, int[] isEmptyRow, int[] isEmptyCol) {
        for (int i = 0; i < n; i++) {
            boolean rowHasB = false;
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 'B') {
                    rowHasB = true;
                    break;
                }
            }
            if (!rowHasB) {
                isEmptyRow[i] = 1;
            }
        }

        for (int j = 0; j < n; j++) {
            boolean colHasB = false;
            for (int i = 0; i < n; i++) {
                if (grid[i][j] == 'B') {
                    colHasB = true;
                    break;
                }
            }
            if (!colHasB) {
                isEmptyCol[j] = 1;
            }
        }
    }

    /**
     * Computes prefix (forward=true) or suffix (forward=false) cumulative sums.
     */
    private static int[] computePrefixSuffixSums(int[] isEmpty, boolean forward) {
        int[] sums = new int[isEmpty.length];
        int acc = 0;
        int start = forward ? 0 : isEmpty.length - 1;
        int end = forward ? isEmpty.length : -1;
        int step = forward ? 1 : -1;

        for (int i = start; i != end; i += step) {
            acc += isEmpty[i];
            sums[i] = acc;
        }
        return sums;
    }

    /**
     * Computes directional obstacle counts (prefix/suffix sums of 'B' occurrences).
     */
    private static int[][] computeDirectionalCounts(char[][] grid, int n, boolean isHorizontal, boolean forward) {
        int[][] counts = new int[n][n];
        if (isHorizontal) {
            for (int i = 0; i < n; i++) {
                if (forward) {
                    for (int j = 0; j < n; j++) {
                        if (j > 0) counts[i][j] = counts[i][j - 1];
                        if (grid[i][j] == 'B') counts[i][j]++;
                    }
                } else {
                    for (int j = n - 1; j >= 0; j--) {
                        if (j < n - 1) counts[i][j] = counts[i][j + 1];
                        if (grid[i][j] == 'B') counts[i][j]++;
                    }
                }
            }
        } else {
            for (int j = 0; j < n; j++) {
                if (forward) {
                    for (int i = 0; i < n; i++) {
                        if (i > 0) counts[i][j] = counts[i - 1][j];
                        if (grid[i][j] == 'B') counts[i][j]++;
                    }
                } else {
                    for (int i = n - 1; i >= 0; i--) {
                        if (i < n - 1) counts[i][j] = counts[i + 1][j];
                        if (grid[i][j] == 'B') counts[i][j]++;
                    }
                }
            }
        }
        return counts;
    }

    /**
     * Determines if a k-length window starting at (r, c) contains no 'B's.
     */
    private static int[][] computeWindowEmptiness(int[][] forwardCounts, int[][] backwardCounts,
                                                  int n, int k, boolean isHorizontal) {
        int[][] isEmpty = new int[n][n];
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < n; c++) {
                boolean forwardOk, backwardOk;
                if (isHorizontal) {
                    forwardOk = (c + k >= n) || (forwardCounts[r][c + k] == 0);
                    backwardOk = (c == 0) || (backwardCounts[r][c - 1] == 0);
                } else {
                    forwardOk = (r + k >= n) || (forwardCounts[r + k][c] == 0);
                    backwardOk = (r == 0) || (backwardCounts[r - 1][c] == 0);
                }
                if (forwardOk && backwardOk) {
                    isEmpty[r][c] = 1;
                }
            }
        }
        return isEmpty;
    }

    /**
     * Computes sliding window sums of empty windows over strips of length k.
     */
    private static int[][] computeSlidingWindowSums(int[][] isEmpty, int n, int k, boolean isHorizontal) {
        int[][] sums = new int[n][n];
        for (int r = 0; r < n; r++) {
            int acc = 0;
            if (isHorizontal) {
                for (int c = n - 1; c >= 0; c--) {
                    acc += isEmpty[r][c];
                    if (c + k < n) acc -= isEmpty[r][c + k];
                    sums[r][c] = acc;
                }
            } else {
                for (int c = n - 1; c >= 0; c--) {
                    acc += isEmpty[c][r];
                    if (c + k < n) acc -= isEmpty[c + k][r];
                    sums[c][r] = acc;
                }
            }
        }
        return sums;
    }

    /**
     * Calculates the maximum number of empty rows and columns covered by a k x k window.
     */
    private static int calculateMaxCoverage(int[][] horizontalEmptyCounts, int[][] verticalEmptyCounts,
                                            int[] emptyRowPrefix, int[] emptyRowSuffix,
                                            int[] emptyColPrefix, int[] emptyColSuffix,
                                            int n, int k) {
        int maxCovered = 0;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                int currentCovered = horizontalEmptyCounts[i][j] + verticalEmptyCounts[i][j];

                // Add empty rows/cols outside the window boundaries
                if (i > 0) currentCovered += emptyRowPrefix[i - 1];
                if (i + k < n) currentCovered += emptyRowSuffix[i + k];
                if (j > 0) currentCovered += emptyColPrefix[j - 1];
                if (j + k < n) currentCovered += emptyColSuffix[j + k];

                maxCovered = Math.max(maxCovered, currentCovered);
            }
        }
        return maxCovered;
    }
}

import java.io.*;
import java.util.StringTokenizer;

public class Main {
    public static void main(String[] args) {
        FastReader in = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);
        new GridSolver().solve(in, out);
        out.flush();
    }

    /**
     * Solves the grid problem by computing row/column metrics, sliding window counts,
     * and determining the maximum possible score based on the given constraints.
     */
    static class GridSolver {
        public void solve(FastReader in, PrintWriter out) {
            int n = in.nextInt();
            int k = in.nextInt();

            // Read grid (1-based indexing for direct compatibility with original logic)
            char[][] grid = new char[n + 1][n + 1];
            for (int i = 1; i <= n; i++) {
                String line = in.next();
                for (int j = 1; j <= n; j++) {
                    grid[i][j] = line.charAt(j - 1);
                }
            }

            // Phase 1: Identify rows and columns that contain only 'W'
            int[] rowAllWhitePrefix = new int[n + 1];
            for (int i = 1; i <= n; i++) {
                boolean isAllWhite = true;
                for (int j = 1; j <= n; j++) {
                    if (grid[i][j] == 'B') {
                        isAllWhite = false;
                        break;
                    }
                }
                rowAllWhitePrefix[i] = isAllWhite ? 1 : 0;
            }
            for (int i = 1; i <= n; i++) rowAllWhitePrefix[i] += rowAllWhitePrefix[i - 1];

            int[] colAllWhitePrefix = new int[n + 1];
            for (int j = 1; j <= n; j++) {
                boolean isAllWhite = true;
                for (int i = 1; i <= n; i++) {
                    if (grid[i][j] == 'B') {
                        isAllWhite = false;
                        break;
                    }
                }
                colAllWhitePrefix[j] = isAllWhite ? 1 : 0;
            }
            for (int i = 1; i <= n; i++) colAllWhitePrefix[i] += colAllWhitePrefix[i - 1];

            // Phase 2: Row-wise prefix sums for 'W' counts
            int[][] rowPrefixSum = new int[n + 1][n + 1];
            for (int i = 1; i <= n; i++) {
                for (int j = 1; j <= n; j++) {
                    rowPrefixSum[i][j] = (grid[i][j] == 'W' ? 1 : 0) + rowPrefixSum[i][j - 1];
                }
            }

            // Phase 3: Compute row-window metrics and vertical all-white window match counts
            long[][] rowWindowMetric = new long[n + 1][n + 1];
            long[][] verticalWindowMatchCount = new long[n + 1][n + 1];

            for (int j = 1; j <= n; j++) {
                if (j + k - 1 > n) break;
                for (int i = 1; i <= n; i++) {
                    // Original formula preserved exactly for algorithmic fidelity
                    long metric = rowPrefixSum[i][n] - rowPrefixSum[i][j + k - 1] + k;
                    if (j > 1) {
                        metric += rowPrefixSum[i][j - 1];
                    }
                    rowWindowMetric[i][j] = metric;
                }

                // Sliding window over rows to count matches in column j
                int matchCount = 0;
                for (int i = 1; i <= k; i++) {
                    if (rowWindowMetric[i][j] == n) matchCount++;
                }
                verticalWindowMatchCount[1][j] = matchCount;

                int rightRow = k + 1;
                for (int i = 2; i <= n; i++) {
                    if (i + k - 1 > n) break;
                    if (rowWindowMetric[i - 1][j] == n) matchCount--;
                    if (rowWindowMetric[rightRow++][j] == n) matchCount++;
                    verticalWindowMatchCount[i][j] = matchCount;
                }
            }

            // Phase 4: Column-wise prefix sums for 'W' counts
            int[][] colPrefixSum = new int[n + 1][n + 1];
            for (int j = 1; j <= n; j++) {
                for (int i = 1; i <= n; i++) {
                    colPrefixSum[i][j] = (grid[i][j] == 'W' ? 1 : 0) + colPrefixSum[i - 1][j];
                }
            }

            // Phase 5: Compute column-window metrics and horizontal all-white window match counts
            long[][] colWindowMetric = new long[n + 1][n + 1];
            long[][] horizontalWindowMatchCount = new long[n + 1][n + 1];

            for (int i = 1; i <= n; i++) {
                if (i + k - 1 > n) break;
                for (int j = 1; j <= n; j++) {
                    long metric = colPrefixSum[n][j] - colPrefixSum[i + k - 1][j] + k;
                    if (i > 1) {
                        metric += colPrefixSum[i - 1][j];
                    }
                    colWindowMetric[i][j] = metric;
                }

                int matchCount = 0;
                for (int j = 1; j <= k; j++) {
                    if (colWindowMetric[i][j] == n) matchCount++;
                }
                horizontalWindowMatchCount[i][1] = matchCount;

                int rightCol = k + 1;
                for (int j = 2; j <= n; j++) {
                    if (j + k - 1 > n) break;
                    if (colWindowMetric[i][j - 1] == n) matchCount--;
                    if (colWindowMetric[i][rightCol++] == n) matchCount++;
                    horizontalWindowMatchCount[i][j] = matchCount;
                }
            }

            // Phase 6: Calculate maximum score across all valid window positions
            long maxScore = 0;
            for (int i = 1; i <= n; i++) {
                for (int j = 1; j <= n; j++) {
                    if (i + k - 1 <= n && j + k - 1 <= n) {
                        long currentScore = 0;
                        currentScore += countAllWhite(rowAllWhitePrefix, 1, i - 1);
                        currentScore += countAllWhite(rowAllWhitePrefix, i + k, n);
                        currentScore += verticalWindowMatchCount[i][j];

                        currentScore += countAllWhite(colAllWhitePrefix, 1, j - 1);
                        currentScore += countAllWhite(colAllWhitePrefix, j + k, n);
                        currentScore += horizontalWindowMatchCount[i][j];

                        if (currentScore > maxScore) {
                            maxScore = currentScore;
                        }
                    }
                }
            }

            out.println(maxScore);
        }

        /**
         * Returns the sum of all-white flags in the given range using prefix sums.
         */
        private long countAllWhite(int[] prefix, int left, int right) {
            if (left > right) return 0;
            return prefix[right] - prefix[left - 1];
        }
    }

    /**
     * Fast input reader using BufferedReader and StringTokenizer.
     * Replaces the custom byte-buffer reader for better maintainability and standard compliance.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input", e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            String token = next();
            return token == null ? 0 : Integer.parseInt(token);
        }
    }
}

import java.util.Scanner;

public class WhiteLines {

    /**
     * Solves the problem to find the maximum score based on white lines in the grid.
     *
     * @param n The size of the grid (n x n).
     * @param k The length of the segments to check.
     * @param grid The 2D grid containing 0s and 1s (0 for non-white, 1 for white).
     * @return The calculated maximum score.
     */
    public static int solve(int n, int k, int[][] grid) {
        // Counters for full rows and columns
        int fullRowCount = 0;
        int fullColCount = 0;

        // Arrays to store cumulative counts of full rows/cols from the current index to the end (Suffix Sums)
        // in_dp_r[i] stores the number of full rows in the range [i, n-1]
        int[] fullRowCountSuffix = new int[n + 1];
        // in_dp_c[j] stores the number of full columns in the range [j, n-1]
        int[] fullColCountSuffix = new int[n + 1];

        // 2D arrays to mark if a specific segment of length k is "valid" (value 1)
        // rowSegmentValid[i][j] indicates if the segment in row i starting at j is valid
        int[][] rowSegmentValid = new int[n][n];
        // colSegmentValid[i][j] indicates if the segment in column j starting at i is valid
        int[][] colSegmentValid = new int[n][n];

        // 1. Process Rows
        // Iterate backwards to build suffix sums
        for (int i = n - 1; i >= 0; i--) {
            int[] suffixWhiteCount = new int[n + 1];

            // Calculate suffix sum of white cells for the current row
            if (grid[i][n - 1] == 1) {
                suffixWhiteCount[n - 1] = 1;
            }
            for (int j = n - 2; j >= 0; j--) {
                suffixWhiteCount[j] = suffixWhiteCount[j + 1];
                if (grid[i][j] == 1) {
                    suffixWhiteCount[j]++;
                }
            }

            // Check if the entire row is white
            if (suffixWhiteCount[0] == n) {
                fullRowCount++;
            }
            fullRowCountSuffix[i] = fullRowCount;

            // Check validity of segments of length k
            // We only need to check start positions j where a segment of length k fits: 0 <= j <= n-k
            for (int j = n - k; j >= 0; j--) {
                boolean isValid = false;

                if (j == 0) {
                    // Special case for the start of the row
                    if (k + suffixWhiteCount[j + k] == n) {
                        isValid = true;
                    }
                } else if (j + k == n) {
                    // Special case for the end of the row
                    if (k + suffixWhiteCount[0] - suffixWhiteCount[j] == n) {
                        isValid = true;
                    }
                } else {
                    // General case
                    if (k + suffixWhiteCount[j + k] - suffixWhiteCount[j] + suffixWhiteCount[0] == n) {
                        isValid = true;
                    }
                }

                if (isValid) {
                    rowSegmentValid[i][j] = 1;
                }
            }
        }

        // 2. Process Columns
        // Iterate backwards on column index j
        for (int j = n - 1; j >= 0; j--) {
            int[] suffixWhiteCount = new int[n + 1];

            // Calculate suffix sum of white cells for the current column
            if (grid[n - 1][j] == 1) {
                suffixWhiteCount[n - 1] = 1;
            }
            for (int i = n - 2; i >= 0; i--) {
                suffixWhiteCount[i] = suffixWhiteCount[i + 1];
                if (grid[i][j] == 1) {
                    suffixWhiteCount[i]++;
                }
            }

            // Check if the entire column is white
            if (suffixWhiteCount[0] == n) {
                fullColCount++;
            }
            fullColCountSuffix[j] = fullColCount;

            // Check validity of segments of length k in this column
            // Iterate through row indices i
            for (int i = 0; i < n; i++) {
                boolean isValid = false;

                if (i == 0) {
                    // Special case for the start of the column
                    if (k + suffixWhiteCount[i + k] == n) {
                        isValid = true;
                    }
                } else if (i + k == n) {
                    // Special case for the end of the column
                    if (k + suffixWhiteCount[0] - suffixWhiteCount[i] == n) {
                        isValid = true;
                    }
                } else if (i + k < n) {
                    // General case
                    if (k + suffixWhiteCount[0] - suffixWhiteCount[i] + suffixWhiteCount[i + k] == n) {
                        isValid = true;
                    }
                }

                if (isValid) {
                    colSegmentValid[i][j] = 1;
                }
            }
        }

        // 3. Final Calculation
        // Accumulators for sliding window sums
        int[][] rowSegmentAccumulator = new int[n][n];
        int[][] colSegmentAccumulator = new int[n][n];

        int maxAns = 0;

        // Logic Block 1: Initialize column accumulators for the last valid window column
        for (int i = n - k; i >= 0; i--) {
            for (int j = n - k; j < n; j++) {
                colSegmentAccumulator[i][n - k] += colSegmentValid[i][j];
            }
            maxAns = Math.max(maxAns, colSegmentAccumulator[i][n - k] + fullColCountSuffix[0] - fullColCountSuffix[n - k]);
        }

        // Logic Block 2: Slide column accumulators to the left
        for (int j = n - k - 1; j >= 0; j--) {
            for (int i = n - k; i >= 0; i--) {
                // Sliding window sum update: add new entry, remove old entry
                colSegmentAccumulator[i][j] += colSegmentAccumulator[i][j + 1] + colSegmentValid[i][j] - colSegmentValid[i][j + k];
                maxAns = Math.max(maxAns, colSegmentAccumulator[i][j] + fullColCountSuffix[0] - fullColCountSuffix[j] + fullColCountSuffix[j + k]);
            }
        }

        // Logic Block 3: Initialize row accumulators for the last valid window row
        for (int j = n - k; j >= 0; j--) {
            for (int i = n - k; i < n; i++) {
                rowSegmentAccumulator[n - k][j] += rowSegmentValid[i][j];
            }
            // Combine with column accumulator from previous steps
            maxAns = Math.max(maxAns, rowSegmentAccumulator[n - k][j] + fullRowCountSuffix[0] - fullRowCountSuffix[n - k] 
                            + colSegmentAccumulator[n - k][j] + fullColCountSuffix[0] - fullColCountSuffix[j] + fullColCountSuffix[j + k]);
        }

        // Logic Block 4: Slide row accumulators upwards
        for (int i = n - k - 1; i >= 0; i--) {
            for (int j = n - k; j >= 0; j--) {
                // Sliding window sum update: add new entry, remove old entry
                rowSegmentAccumulator[i][j] += rowSegmentAccumulator[i + 1][j] - rowSegmentValid[i + k][j] + rowSegmentValid[i][j];

                maxAns = Math.max(maxAns, rowSegmentAccumulator[i][j] + colSegmentAccumulator[i][j] 
                                + fullColCountSuffix[0] - fullColCountSuffix[j] + fullColCountSuffix[j + k] 
                                + fullRowCountSuffix[0] - fullRowCountSuffix[i] + fullRowCountSuffix[i + k]);
            }
        }

        return maxAns;
    }

    public static void main(String[] args) {
        // Use try-with-resources to ensure Scanner is closed
        try (Scanner s = new Scanner(System.in)) {
            if (!s.hasNextInt()) return;

            int n = s.nextInt();
            int k = s.nextInt();

            int[][] grid = new int[n][n];
            for (int i = 0; i < n; i++) {
                String input = s.next();
                for (int j = 0; j < n; j++) {
                    grid[i][j] = (input.charAt(j) == 'W') ? 1 : 0;
                }
            }

            System.out.println(solve(n, k, grid));
        }
    }
}

import java.io.*;
import java.util.*;

public class TaskD {

    public static void main(String[] args) {
        FastReader in = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            int n = in.nextInt();
            int k = in.nextInt();

            // 1. Read input and center the grid within a larger matrix
            boolean[][] grid = readAndCenterGrid(in, n, k);

            // 2. Compute the first and last occurrence of 'B' for each row and column
            int[][] rowBounds = new int[k + n][2];
            int[][] colBounds = new int[k + n][2];
            computeBounds(grid, rowBounds, colBounds);

            // 3. Calculate the maximum score using dynamic programming / difference arrays
            int maxScore = calculateMaxScore(n, k, rowBounds, colBounds);

            out.println(maxScore);
        } finally {
            out.flush();
            out.close();
        }
    }

    /**
     * Reads the n x n grid from input and places it in the center of a (k+n) x (k+n) matrix.
     */
    private static boolean[][] readAndCenterGrid(FastReader in, int n, int k) {
        int size = k + n;
        boolean[][] grid = new boolean[size][size];
        for (int i = 0; i < n; i++) {
            String row = in.next();
            for (int j = 0; j < n; j++) {
                grid[k + i][k + j] = (row.charAt(j) == 'B');
            }
        }
        return grid;
    }

    /**
     * Computes the start and end indices of 'B' characters for every row and column.
     * Returns -1 for both indices if the row/column contains no 'B's.
     */
    private static void computeBounds(boolean[][] grid, int[][] rowBounds, int[][] colBounds) {
        int size = grid.length;
        for (int i = 0; i < size; i++) {
            rowBounds[i] = findRange(grid[i]);
            colBounds[i] = findColumnRange(grid, i);
        }
    }

    /**
     * Finds the first and last index of a true value in a 1D boolean array.
     */
    private static int[] findRange(boolean[] line) {
        int start = -1;
        int end = -1;
        for (int i = 0; i < line.length; i++) {
            if (line[i]) {
                if (start == -1) start = i;
                end = i;
            }
        }
        return new int[]{start, end};
    }

    /**
     * Finds the first and last index of a true value in a specific column.
     */
    private static int[] findColumnRange(boolean[][] grid, int colIndex) {
        int start = -1;
        int end = -1;
        for (int i = 0; i < grid.length; i++) {
            if (grid[i][colIndex]) {
                if (start == -1) start = i;
                end = i;
            }
        }
        return new int[]{start, end};
    }

    /**
     * Calculates the maximum combined score using sliding window logic and prefix sums.
     */
    private static int calculateMaxScore(int n, int k, int[][] rowBounds, int[][] colBounds) {
        int size = k + n;
        int[][] rowDp = new int[size][size];
        int[][] colDp = new int[size][size];
        int maxScore = 0;

        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= n; j++) {
                // Update row contribution DP
                rowDp[i][j] = rowDp[i - 1][j];
                if (j <= rowBounds[i - 1][0] && rowBounds[i - 1][1] < j + k) {
                    rowDp[i][j]--;
                }
                if (j <= rowBounds[k + i - 1][0] && rowBounds[k + i - 1][1] < j + k) {
                    rowDp[i][j]++;
                }

                // Update column contribution DP
                colDp[i][j] = colDp[i][j - 1];
                if (i <= colBounds[j - 1][0] && colBounds[j - 1][1] < i + k) {
                    colDp[i][j]--;
                }
                if (i <= colBounds[k + j - 1][0] && colBounds[k + j - 1][1] < i + k) {
                    colDp[i][j]++;
                }

                maxScore = Math.max(maxScore, rowDp[i][j] + colDp[i][j]);
            }
        }

        // Adjust score for completely empty rows and columns in the target region
        for (int i = k; i < k + n; i++) {
            if (rowBounds[i][0] == -1) maxScore++;
            if (colBounds[i][0] == -1) maxScore++;
        }

        return maxScore;
    }

    /**
     * High-performance input reader for competitive programming environments.
     */
    private static class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastReader(InputStream is) {
            br = new BufferedReader(new InputStreamReader(is));
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }

        public double nextDouble() {
            return Double.parseDouble(next());
        }

        public String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = nextLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input stream", e);
                }
            }
            return st.nextToken();
        }

        private String nextLine() throws IOException {
            return br.readLine();
        }
    }
}

import java.util.Scanner;
import java.util.Arrays;

public class DWhiteLines {

    // Constant for infinity to represent non-existent boundaries
    private static final int INF = Integer.MAX_VALUE;

    public static void main(String[] args) {
        // Use try-with-resources for automatic resource management
        try (Scanner scanner = new Scanner(System.in)) {

            if (!scanner.hasNextInt()) {
                return;
            }

            int n = scanner.nextInt();
            int k = scanner.nextInt();

            // Consume the rest of the line including the newline character
            scanner.nextLine();

            char[][] board = new char[n][n];
            for (int i = 0; i < n; i++) {
                String line = scanner.nextLine();
                board[i] = line.toCharArray();
            }

            // Arrays to store the boundaries of black pixels in each row and column
            // rowMinCol[i] stores the minimum column index of a black pixel in row i
            int[] rowMinCol = new int[n];
            // rowMaxCol[i] stores the maximum column index of a black pixel in row i
            int[] rowMaxCol = new int[n];
            // colMinRow[i] stores the minimum row index of a black pixel in column i
            int[] colMinRow = new int[n];
            // colMaxRow[i] stores the maximum row index of a black pixel in column i
            int[] colMaxRow = new int[n];

            // Initialize boundaries
            Arrays.fill(rowMinCol, INF);
            Arrays.fill(rowMaxCol, -1);
            Arrays.fill(colMinRow, INF);
            Arrays.fill(colMaxRow, -1);

            int whiteRowCount = 0;
            int whiteColCount = 0;

            // Analyze the grid to find boundaries and count white lines
            for (int i = 0; i < n; i++) {
                boolean isWhiteRow = true;
                boolean isWhiteCol = true;

                for (int j = 0; j < n; j++) {
                    // Check row i
                    if (board[i][j] == 'B') {
                        rowMinCol[i] = Math.min(rowMinCol[i], j);
                        rowMaxCol[i] = Math.max(rowMaxCol[i], j);
                        isWhiteRow = false;
                    }

                    // Check column i (accessing board[j][i])
                    if (board[j][i] == 'B') {
                        colMinRow[i] = Math.min(colMinRow[i], j);
                        colMaxRow[i] = Math.max(colMaxRow[i], j);
                        isWhiteCol = false;
                    }
                }

                if (isWhiteRow) whiteRowCount++;
                if (isWhiteCol) whiteColCount++;
            }

            // Edge case: if window size k is larger than grid size n
            if (k > n) {
                // No k x k square can fit. The score from covered lines is 0.
                System.out.println(whiteRowCount + whiteColCount);
                return;
            }

            // DP Arrays
            // rowsCovered[r][c] stores the number of rows in the vertical window [r, r+k-1]
            // that are fully contained within the horizontal window [c, c+k-1].
            int[][] rowsCovered = new int[n - k + 1][n - k + 1];

            // colsCovered[r][c] stores the number of columns in the horizontal window [c, c+k-1]
            // that are fully contained within the vertical window [r, r+k-1].
            int[][] colsCovered = new int[n - k + 1][n - k + 1];

            // Initialize base cases for rowsCovered (vertical window starts at 0)
            for (int colStart = 0; colStart < n - k + 1; colStart++) {
                int count = 0;
                for (int r = 0; r < k; r++) {
                    // Check if row r is fully inside the column window [colStart, colStart + k - 1]
                    if (rowMinCol[r] != INF && 
                        rowMinCol[r] >= colStart && 
                        rowMaxCol[r] <= colStart + k - 1) {
                        count++;
                    }
                }
                rowsCovered[0][colStart] = count;
            }

            // Initialize base cases for colsCovered (horizontal window starts at 0)
            for (int rowStart = 0; rowStart < n - k + 1; rowStart++) {
                int count = 0;
                for (int c = 0; c < k; c++) {
                    // Check if column c is fully inside the row window [rowStart, rowStart + k - 1]
                    if (colMinRow[c] != INF && 
                        colMinRow[c] >= rowStart && 
                        colMaxRow[c] <= rowStart + k - 1) {
                        count++;
                    }
                }
                colsCovered[rowStart][0] = count;
            }

            // Sliding Window for rowsCovered
            // We slide the vertical window down from rowStart-1 to rowStart
            for (int rowStart = 1; rowStart < n - k + 1; rowStart++) {
                for (int colStart = 0; colStart < n - k + 1; colStart++) {
                    // Start with the count from the previous vertical window position
                    rowsCovered[rowStart][colStart] = rowsCovered[rowStart - 1][colStart];

                    // Remove the row that is sliding out of the window (rowStart - 1)
                    int removedRow = rowStart - 1;
                    if (rowMinCol[removedRow] != INF && 
                        rowMinCol[removedRow] >= colStart && 
                        rowMaxCol[removedRow] <= colStart + k - 1) {
                        rowsCovered[rowStart][colStart]--;
                    }

                    // Add the row that is sliding into the window (rowStart + k - 1)
                    int addedRow = rowStart + k - 1;
                    if (rowMinCol[addedRow] != INF && 
                        rowMinCol[addedRow] >= colStart && 
                        rowMaxCol[addedRow] <= colStart + k - 1) {
                        rowsCovered[rowStart][colStart]++;
                    }
                }
            }

            // Sliding Window for colsCovered
            // We slide the horizontal window right from colStart-1 to colStart
            for (int colStart = 1; colStart < n - k + 1; colStart++) {
                for (int rowStart = 0; rowStart < n - k + 1; rowStart++) {
                    // Start with the count from the previous horizontal window position
                    colsCovered[rowStart][colStart] = colsCovered[rowStart][colStart - 1];

                    // Remove the column that is sliding out of the window (colStart - 1)
                    int removedCol = colStart - 1;
                    if (colMinRow[removedCol] != INF && 
                        colMinRow[removedCol] >= rowStart && 
                        colMaxRow[removedCol] <= rowStart + k - 1) {
                        colsCovered[rowStart][colStart]--;
                    }

                    // Add the column that is sliding into the window (colStart + k - 1)
                    int addedCol = colStart + k - 1;
                    if (colMinRow[addedCol] != INF && 
                        colMinRow[addedCol] >= rowStart && 
                        colMaxRow[addedCol] <= rowStart + k - 1) {
                        colsCovered[rowStart][colStart]++;
                    }
                }
            }

            // Find the maximum sum of covered rows and columns for any k x k square
            int maxCovered = 0;
            int size = n - k + 1;
            for (int i = 0; i < size; i++) {
                for (int j = 0; j < size; j++) {
                    maxCovered = Math.max(maxCovered, rowsCovered[i][j] + colsCovered[i][j]);
                }
            }

            // Output result: max covered lines + pure white lines
            System.out.println(maxCovered + whiteRowCount + whiteColCount);

        } catch (Exception e) {
            e.printStackTrace();
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

/**
 * Refactored solution for calculating maximum White Lines (WL) in a grid.
 * 
 * Refactoring improvements:
 * 1. Separation of Concerns: Logic is split into distinct methods (input reading, 
 *    grid processing, window counting, transposition).
 * 2. Readability: Variable names are descriptive (e.g., 'whiteLines' instead of 'WL').
 * 3. Maintainability: The algorithm for rows and columns is unified using a transpose 
 *    operation to reduce code duplication.
 * 4. Robustness: Better exception handling in FastScanner and input validation.
 * 5. Complexity: Maintains O(N^2) time and space complexity.
 */
public class Main {

    // FastScanner class for efficient input reading
    static class FastScanner {
        BufferedReader br;
        StringTokenizer st;

        public FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) {
                        return null;
                    }
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            String s = next();
            if (s == null) {
                throw new RuntimeException("Unexpected end of input");
            }
            return Integer.parseInt(s);
        }
    }

    public static void main(String[] args) {
        FastScanner sc = new FastScanner();

        // Read N and K
        String nStr = sc.next();
        if (nStr == null) return;
        int n = Integer.parseInt(nStr);
        int k = sc.nextInt();

        // Read Grid
        // Using int[][] for easier summation logic (1 for 'B', 0 otherwise)
        int[][] grid = new int[n][n];
        for (int i = 0; i < n; i++) {
            String rowStr = sc.next();
            for (int j = 0; j < n; j++) {
                grid[i][j] = (rowStr.charAt(j) == 'B') ? 1 : 0;
            }
        }

        // 1. Calculate base White Lines (empty rows and columns)
        // These contribute to the count regardless of the window size K.
        int whiteLines = 0;

        // Count empty rows
        for (int i = 0; i < n; i++) {
            int sum = 0;
            for (int val : grid[i]) sum += val;
            if (sum == 0) whiteLines++;
        }

        // Count empty columns
        for (int j = 0; j < n; j++) {
            int sum = 0;
            for (int i = 0; i < n; i++) sum += grid[i][j];
            if (sum == 0) whiteLines++;
        }

        // If K > N, no KxK subgrid exists, so the result is just the base white lines.
        if (k > n) {
            System.out.println(whiteLines);
            return;
        }

        // 2. Calculate Row Window Counts
        // rowCounts[i][j] stores the number of rows in the vertical strip [i, i+K-1]
        // that have a maximum density horizontal window starting at column j.
        int[][] rowCounts = calculateWindowCounts(grid, n, k);

        // 3. Calculate Column Window Counts
        // We reuse the row logic by transposing the grid.
        // colCounts[i][j] corresponds to rowCounts[j][i] on the transposed grid.
        int[][] gridT = transpose(grid, n);
        int[][] colCountsT = calculateWindowCounts(gridT, n, k);

        // 4. Find Maximum WL
        int maxWL = 0;
        int limit = n - k + 1;

        for (int i = 0; i < limit; i++) {
            for (int j = 0; j < limit; j++) {
                // rowCounts[i][j]: Count of valid horizontal lines in the square
                // colCountsT[j][i]: Count of valid vertical lines in the square
                int currentWL = rowCounts[i][j] + colCountsT[j][i];
                if (currentWL > maxWL) {
                    maxWL = currentWL;
                }
            }
        }

        System.out.println(maxWL + whiteLines);
    }

    /**
     * Calculates the counts of maximum density windows for a grid.
     * 
     * @param grid The input grid (N x N)
     * @param n    Size of the grid
     * @param k    Window size
     * @return A 2D array of size (N-K+1) x (N-K+1) where result[i][j] is the count
     *         of rows in the vertical strip starting at row i (height K) that have
     *         a maximum density window of length K starting at column j.
     */
    private static int[][] calculateWindowCounts(int[][] grid, int n, int k) {
        // 1. Compute Row Prefix Sums
        // prefixSum[i][j] stores sum of grid[i][0...j-1]
        int[][] prefixSum = new int[n][n + 1];
        int[] rowMax = new int[n]; // Stores max sum for each row

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                prefixSum[i][j + 1] = prefixSum[i][j] + grid[i][j];
            }
            rowMax[i] = prefixSum[i][n];
        }

        // 2. Identify "Max Density Windows"
        // isMaxWindow[r][c] is true if the window of length k starting at c in row r
        // has the maximum possible sum for that row (and sum > 0).
        int windowWidth = n - k + 1;
        boolean[][] isMaxWindow = new boolean[n][windowWidth];

        for (int i = 0; i < n; i++) {
            int max = rowMax[i];
            if (max > 0) { // Only care if row is not empty
                for (int j = 0; j < windowWidth; j++) {
                    int windowSum = prefixSum[i][j + k] - prefixSum[i][j];
                    if (windowSum == max) {
                        isMaxWindow[i][j] = true;
                    }
                }
            }
        }

        // 3. Compute Vertical Accumulation (Sliding Window Sum over Rows)
        // verticalAcc[r][c] stores sum of isMaxWindow[0...r-1][c]
        // This allows O(1) calculation of sum in range [i, i+K-1]
        int[][] verticalAcc = new int[n + 1][windowWidth];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < windowWidth; j++) {
                verticalAcc[i + 1][j] = verticalAcc[i][j] + (isMaxWindow[i][j] ? 1 : 0);
            }
        }

        // 4. Compute Final Counts
        int[][] result = new int[windowWidth][windowWidth];
        for (int i = 0; i < windowWidth; i++) {
            for (int j = 0; j < windowWidth; j++) {
                // Count in rows i to i+K-1 at column start j
                result[i][j] = verticalAcc[i + k][j] - verticalAcc[i][j];
            }
        }

        return result;
    }

    /**
     * Transposes the grid.
     */
    private static int[][] transpose(int[][] grid, int n) {
        int[][] transposed = new int[n][n];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                transposed[j][i] = grid[i][j];
            }
        }
        return transposed;
    }
}

import java.util.Arrays;
import java.util.Scanner;

public class Main {

    public static void main(String[] args) {
        // Use try-with-resources to ensure the Scanner is properly closed
        try (Scanner scanner = new Scanner(System.in)) {
            if (!scanner.hasNextInt()) return;

            int n = scanner.nextInt();
            int k = scanner.nextInt();

            String[] grid = new String[n];
            for (int i = 0; i < n; i++) {
                grid[i] = scanner.next();
            }

            // Compute contributions for rows and columns separately
            int[][] rowContributions = computeWindowContributions(grid, n, k, true);
            int[][] colContributions = computeWindowContributions(grid, n, k, false);

            // Find the maximum combined contribution across all valid k x k windows
            int maxCount = 0;
            int validSize = n - k + 1;
            for (int i = 0; i < validSize; i++) {
                for (int j = 0; j < validSize; j++) {
                    int total = rowContributions[i][j] + colContributions[i][j];
                    if (total > maxCount) {
                        maxCount = total;
                    }
                }
            }

            System.out.println(maxCount);
        }
    }

    /**
     * Computes the contribution of rows or columns to each k x k sliding window.
     * A row/column contributes to a window if it contains at least one 'B' and all 
     * its 'B's fall within the window's bounds along the perpendicular axis.
     *
     * @param grid  The input grid of strings
     * @param n     Grid dimension
     * @param k     Window size
     * @param isRow If true, computes row contributions (slides window vertically)
     *              If false, computes column contributions (slides window horizontally)
     * @return 2D array where result[i][j] is the contribution count for a window 
     *         starting at row i, column j
     */
    private static int[][] computeWindowContributions(String[] grid, int n, int k, boolean isRow) {
        int[][] contributions = new int[n][n];
        int[] first = new int[n];
        int[] last = new int[n];
        boolean[] isEmpty = new boolean[n];
        Arrays.fill(first, -1);
        Arrays.fill(last, -1);

        // Determine the first and last occurrence of 'B' for each row or column
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                // Access character based on whether we're analyzing rows or columns
                char c = isRow ? grid[i].charAt(j) : grid[j].charAt(i);
                if (c == 'B') {
                    if (first[i] == -1) {
                        first[i] = j;
                    }
                    last[i] = j;
                }
            }
            if (first[i] == -1) {
                isEmpty[i] = true;
            }
        }

        // Count initially empty rows/columns (they always contribute to the baseline)
        int emptyCount = 0;
        for (boolean e : isEmpty) {
            if (e) emptyCount++;
        }

        int windowLimit = n - k + 1;
        // Slide the window along the perpendicular axis
        for (int start = 0; start < windowLimit; start++) {
            int currentCount = emptyCount;
            int end = start + k - 1;

            // Initialize count for the first window position
            for (int i = 0; i < k; i++) {
                if (!isEmpty[i] && first[i] >= start && last[i] <= end) {
                    currentCount++;
                }
            }

            // Map to correct [rowStart][colStart] indices
            if (isRow) {
                contributions[0][start] = currentCount;
            } else {
                contributions[start][0] = currentCount;
            }

            // Slide the window down (or right) using O(1) updates
            for (int i = k; i < n; i++) {
                // Add the newly included row/column
                if (!isEmpty[i] && first[i] >= start && last[i] <= end) {
                    currentCount++;
                }
                // Remove the row/column that just left the window
                if (!isEmpty[i - k] && first[i - k] >= start && last[i - k] <= end) {
                    currentCount--;
                }

                int rowStart = isRow ? (i - k + 1) : start;
                int colStart = isRow ? start : (i - k + 1);
                contributions[rowStart][colStart] = currentCount;
            }
        }
        return contributions;
    }
}

import java.util.Scanner;

/**
 * Analyzes a grid to find a window of size k x k that maximizes a specific score.
 * The score is based on filled rows/cols and rows/cols that can be completed 
 * by filling the window.
 */
public class Generator {
    private int gridSize;
    private int windowSize;
    private int[][] grid;

    // Prefix sums for grid values
    private int[][] rowPrefixSums;
    private int[][] colPrefixSums;

    // Prefix sums of filled status (rows/cols that are fully filled with 1s)
    private int[] filledRowsPrefix;
    private int[] filledColsPrefix;

    // Status arrays indicating if a row/col can be completed to all 1s by a window
    // canCompleteRow[colWindowStart][row]
    private int[][] canCompleteRow;
    // canCompleteCol[rowWindowStart][col]
    private int[][] canCompleteCol;

    // Prefix sums of the status arrays
    private int[][] prefCanCompleteRow;
    private int[][] prefCanCompleteCol;

    public static void main(String[] args) {
        Generator analyzer = new Generator();
        analyzer.run();
    }

    private void run() {
        Scanner scanner = new Scanner(System.in);
        if (!scanner.hasNextInt()) {
            return;
        }

        gridSize = scanner.nextInt();
        windowSize = scanner.nextInt();

        grid = new int[gridSize][gridSize];
        for (int i = 0; i < gridSize; i++) {
            String line = scanner.next();
            for (int j = 0; j < gridSize; j++) {
                grid[i][j] = (line.charAt(j) == 'W') ? 1 : 0;
            }
        }

        computePrefixSums();
        computeFilledStatus();
        computeCompletionStatus();
        computeCompletionPrefixSums();

        System.out.println(calculateMaxScore());

        scanner.close();
    }

    private void computePrefixSums() {
        rowPrefixSums = new int[gridSize][gridSize];
        colPrefixSums = new int[gridSize][gridSize];

        // Row prefix sums: rowPrefixSums[i][j] stores sum of grid[i][0...j]
        for (int i = 0; i < gridSize; i++) {
            int sum = 0;
            for (int j = 0; j < gridSize; j++) {
                sum += grid[i][j];
                rowPrefixSums[i][j] = sum;
            }
        }

        // Col prefix sums: colPrefixSums[j][i] stores sum of grid[0...i][j]
        // Note: Using [colIndex][rowIndex] to match original logic structure
        for (int j = 0; j < gridSize; j++) {
            int sum = 0;
            for (int i = 0; i < gridSize; i++) {
                sum += grid[i][j];
                colPrefixSums[j][i] = sum;
            }
        }
    }

    private void computeFilledStatus() {
        filledRowsPrefix = new int[gridSize];
        filledColsPrefix = new int[gridSize];

        // Check if rows are fully filled
        filledRowsPrefix[0] = (rowPrefixSums[0][gridSize - 1] == gridSize) ? 1 : 0;
        for (int i = 1; i < gridSize; i++) {
            filledRowsPrefix[i] = filledRowsPrefix[i - 1] + 
                ((rowPrefixSums[i][gridSize - 1] == gridSize) ? 1 : 0);
        }

        // Check if cols are fully filled
        filledColsPrefix[0] = (colPrefixSums[0][gridSize - 1] == gridSize) ? 1 : 0;
        for (int i = 1; i < gridSize; i++) {
            filledColsPrefix[i] = filledColsPrefix[i - 1] + 
                ((colPrefixSums[i][gridSize - 1] == gridSize) ? 1 : 0);
        }
    }

    private void computeCompletionStatus() {
        // canCompleteRow[colStart][row]
        // Dimensions: [gridSize - windowSize + 1][gridSize]
        int maxColStart = gridSize - windowSize;
        canCompleteRow = new int[maxColStart + 1][gridSize];

        for (int colStart = 0; colStart <= maxColStart; colStart++) {
            for (int row = 0; row < gridSize; row++) {
                // Sum of 1s in this row outside the window [colStart, colStart + windowSize - 1]
                int outsideSum = getRangeSum(rowPrefixSums[row], 0, colStart - 1) + 
                                 getRangeSum(rowPrefixSums[row], colStart + windowSize, gridSize - 1);

                if (outsideSum + windowSize == gridSize) {
                    canCompleteRow[colStart][row] = 1;
                }
            }
        }

        // canCompleteCol[rowStart][col]
        // Dimensions: [gridSize - windowSize + 1][gridSize]
        int maxRowStart = gridSize - windowSize;
        canCompleteCol = new int[maxRowStart + 1][gridSize];

        for (int rowStart = 0; rowStart <= maxRowStart; rowStart++) {
            for (int col = 0; col < gridSize; col++) {
                // Sum of 1s in this col outside the window [rowStart, rowStart + windowSize - 1]
                int outsideSum = getRangeSum(colPrefixSums[col], 0, rowStart - 1) + 
                                 getRangeSum(colPrefixSums[col], rowStart + windowSize, gridSize - 1);

                if (outsideSum + windowSize == gridSize) {
                    canCompleteCol[rowStart][col] = 1;
                }
            }
        }
    }

    private void computeCompletionPrefixSums() {
        // Prefix sums for canCompleteRow over the row index (2nd dimension)
        prefCanCompleteRow = new int[canCompleteRow.length][gridSize];
        for (int colStart = 0; colStart < canCompleteRow.length; colStart++) {
            prefCanCompleteRow[colStart][0] = canCompleteRow[colStart][0];
            for (int row = 1; row < gridSize; row++) {
                prefCanCompleteRow[colStart][row] = prefCanCompleteRow[colStart][row - 1] + canCompleteRow[colStart][row];
            }
        }

        // Prefix sums for canCompleteCol over the col index (2nd dimension)
        prefCanCompleteCol = new int[canCompleteCol.length][gridSize];
        for (int rowStart = 0; rowStart < canCompleteCol.length; rowStart++) {
            prefCanCompleteCol[rowStart][0] = canCompleteCol[rowStart][0];
            for (int col = 1; col < gridSize; col++) {
                prefCanCompleteCol[rowStart][col] = prefCanCompleteCol[rowStart][col - 1] + canCompleteCol[rowStart][col];
            }
        }
    }

    private int calculateMaxScore() {
        int maxScore = 0;
        int maxWindowStart = gridSize - windowSize;

        for (int rowStart = 0; rowStart <= maxWindowStart; rowStart++) {
            for (int colStart = 0; colStart <= maxWindowStart; colStart++) {
                int currentScore = 0;

                // Count completed rows within the vertical span of the window
                // Rows from rowStart to rowStart + windowSize - 1
                currentScore += getRangeSum2D(prefCanCompleteRow, colStart, rowStart, rowStart + windowSize - 1);

                // Count completed cols within the horizontal span of the window
                // Cols from colStart to colStart + windowSize - 1
                currentScore += getRangeSum2D(prefCanCompleteCol, rowStart, colStart, colStart + windowSize - 1);

                // Count fully filled rows outside the window vertically
                currentScore += getRangeSum(filledRowsPrefix, 0, rowStart - 1);
                currentScore += getRangeSum(filledRowsPrefix, rowStart + windowSize, gridSize - 1);

                // Count fully filled cols outside the window horizontally
                currentScore += getRangeSum(filledColsPrefix, 0, colStart - 1);
                currentScore += getRangeSum(filledColsPrefix, colStart + windowSize, gridSize - 1);

                if (currentScore > maxScore) {
                    maxScore = currentScore;
                }
            }
        }
        return maxScore;
    }

    // Helper to get sum in range [l, r] of a 1D prefix sum array
    private int getRangeSum(int[] prefixArray, int l, int r) {
        if (l > r) {
            return 0;
        }
        if (l == 0) {
            return prefixArray[r];
        }
        return prefixArray[r] - prefixArray[l - 1];
    }

    // Helper to get sum in range [l, r] of a 2D prefix sum array (fixed index in 1st dim)
    private int getRangeSum2D(int[][] prefixArray, int fixedIndex, int l, int r) {
        if (l > r) {
            return 0;
        }
        if (l == 0) {
            return prefixArray[fixedIndex][r];
        }
        return prefixArray[fixedIndex][r] - prefixArray[fixedIndex][l - 1];
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.Arrays;
import java.util.StringTokenizer;

public class Solution {
    public static void main(String[] args) throws IOException {
        // Use BufferedReader and PrintWriter for fast I/O
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter out = new PrintWriter(System.out);

        // Read grid size (N) and window size (K)
        String line = br.readLine();
        if (line != null) {
            StringTokenizer st = new StringTokenizer(line);
            int gridSize = Integer.parseInt(st.nextToken());
            int windowSize = Integer.parseInt(st.nextToken());

            // Arrays to store the column index of the first and last 'B' for each row
            int[] rowMinCol = new int[gridSize];
            int[] rowMaxCol = new int[gridSize];

            // Arrays to store the row index of the first and last 'B' for each column
            int[] colMinRow = new int[gridSize];
            int[] colMaxRow = new int[gridSize];

            // Initialize boundary arrays with -1 (indicating no 'B' found yet)
            Arrays.fill(rowMinCol, -1);
            Arrays.fill(rowMaxCol, -1);
            Arrays.fill(colMinRow, -1);
            Arrays.fill(colMaxRow, -1);

            // Read the grid and populate boundary arrays
            for (int r = 0; r < gridSize; r++) {
                st = new StringTokenizer(br.readLine());
                String rowStr = st.nextToken();
                for (int c = 0; c < gridSize; c++) {
                    if (rowStr.charAt(c) == 'B') {
                        // Update row boundaries
                        if (rowMinCol[r] == -1) rowMinCol[r] = c;
                        rowMaxCol[r] = c;

                        // Update column boundaries
                        if (colMinRow[c] == -1) colMinRow[c] = r;
                        colMaxRow[c] = r;
                    }
                }
            }

            // Filter rows and columns that exceed the window size K
            // If a row/col span is too large, it's considered invalid
            int invalidBoundariesCount = 0;
            for (int i = 0; i < gridSize; i++) {
                // Check Row i
                if (rowMinCol[i] == -1) {
                    invalidBoundariesCount++;
                } else if (rowMaxCol[i] - rowMinCol[i] + 1 > windowSize) {
                    rowMaxCol[i] = -1;
                    rowMinCol[i] = -1;
                }

                // Check Column i
                if (colMinRow[i] == -1) {
                    invalidBoundariesCount++;
                } else if (colMaxRow[i] - colMinRow[i] + 1 > windowSize) {
                    colMaxRow[i] = -1;
                    colMinRow[i] = -1;
                }
            }

            // Indicator arrays for prefix sums
            // rowStartIndicator[r][c] = 1 if row r starts at col c
            int[][] rowStartIndicator = new int[gridSize][gridSize];
            // rowEndIndicator[r][c] = 1 if row r ends at col c
            int[][] rowEndIndicator = new int[gridSize][gridSize];
            // colStartIndicator[r][c] = 1 if col c starts at row r
            int[][] colStartIndicator = new int[gridSize][gridSize];
            // colEndIndicator[r][c] = 1 if col c ends at row r
            int[][] colEndIndicator = new int[gridSize][gridSize];

            for (int r = 0; r < gridSize; r++) {
                if (rowMinCol[r] != -1) rowStartIndicator[r][rowMinCol[r]] = 1;
                if (rowMaxCol[r] != -1) rowEndIndicator[r][rowMaxCol[r]] = 1;
                if (colMinRow[r] != -1) colStartIndicator[colMinRow[r]][r] = 1;
                if (colMaxRow[r] != -1) colEndIndicator[colMaxRow[r]][r] = 1;
            }

            // Compute Prefix Sums
            // Vertical prefix sums for row indicators (summing down columns)
            // This allows O(1) counting of rows starting/ending at a specific column within a row range
            for (int c = 0; c < gridSize; c++) {
                for (int r = 1; r < gridSize; r++) {
                    rowStartIndicator[r][c] += rowStartIndicator[r - 1][c];
                    rowEndIndicator[r][c] += rowEndIndicator[r - 1][c];
                }
            }

            // Horizontal prefix sums for col indicators (summing across rows)
            // This allows O(1) counting of cols starting/ending at a specific row within a col range
            for (int r = 0; r < gridSize; r++) {
                for (int c = 1; c < gridSize; c++) {
                    colStartIndicator[r][c] += colStartIndicator[r][c - 1];
                    colEndIndicator[r][c] += colEndIndicator[r][c - 1];
                }
            }

            // DP Array to store scores for each possible window position
            // windowScores[r][c] corresponds to the score of a window with top-left at (r, c)
            int windowRows = gridSize - windowSize + 1;
            int windowCols = gridSize - windowSize + 1;
            int[][] windowScores = new int[windowRows][windowCols];

            // Initialize dp[0][0] (Top-left window)
            // Sum of boundaries at the edges of the first window
            for (int i = 0; i < windowSize; i++) {
                windowScores[0][0] += rowEndIndicator[windowSize - 1][i];
                windowScores[0][0] += colEndIndicator[i][windowSize - 1];
            }

            // Fill DP table using a sliding window approach
            for (int r = 0; r < windowRows; r++) {
                for (int c = 0; c < windowCols; c++) {
                    if (r == 0 && c == 0) continue;

                    if (c == 0) {
                        // Moving down (changing row index of window top)
                        // Copy score from window directly above
                        windowScores[r][c] = windowScores[r - 1][c];

                        // Add boundaries entering from the bottom of the new window
                        windowScores[r][c] += colEndIndicator[r + windowSize - 1][c + windowSize - 1];
                        // Remove boundaries leaving from the top (row above the new window)
                        windowScores[r][c] -= colStartIndicator[r - 1][c + windowSize - 1];

                        // Adjust for horizontal boundaries (rows) entering/leaving the window horizontally
                        // Row leaving top (r-1)
                        if (rowMinCol[r - 1] >= c && rowMaxCol[r - 1] < c + windowSize) {
                            windowScores[r][c]--;
                        }
                        // Row entering bottom (r + windowSize - 1)
                        if (rowMinCol[r + windowSize - 1] >= c && rowMaxCol[r + windowSize - 1] < c + windowSize) {
                            windowScores[r][c]++;
                        }
                    } else {
                        // Moving right (changing col index of window left)
                        // Copy score from window directly to the left
                        windowScores[r][c] = windowScores[r][c - 1];

                        // Add boundaries entering from the right
                        windowScores[r][c] += rowEndIndicator[r + windowSize - 1][c + windowSize - 1];

                        // Remove boundaries leaving from the left (col c-1)
                        // Note: Logic preserves original complex boundary adjustments
                        if (r > 0) {
                            windowScores[r][c] -= rowEndIndicator[r - 1][c + windowSize - 1];
                        }
                        windowScores[r][c] -= rowStartIndicator[r + windowSize - 1][c - 1];
                        if (r > 0) {
                            windowScores[r][c] += rowStartIndicator[r - 1][c - 1];
                        }

                        // Adjust for vertical boundaries (cols) entering/leaving the window vertically
                        // Col leaving left (c-1)
                        if (colMinRow[c - 1] >= r && colMaxRow[c - 1] < r + windowSize) {
                            windowScores[r][c]--;
                        }
                        // Col entering right (c + windowSize - 1)
                        if (colMinRow[c + windowSize - 1] >= r && colMaxRow[c + windowSize - 1] < r + windowSize) {
                            windowScores[r][c]++;
                        }
                    }
                }
            }

            // Find maximum score in the DP table
            int maxScore = 0;
            for (int r = 0; r < windowRows; r++) {
                for (int c = 0; c < windowCols; c++) {
                    if (windowScores[r][c] > maxScore) {
                        maxScore = windowScores[r][c];
                    }
                }
            }

            // Final result is the count of invalid boundaries plus the max window score
            out.println(invalidBoundariesCount + maxScore);
            out.flush();
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.OutputStream;
import java.io.PrintWriter;
import java.util.StringTokenizer;

public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);

        TaskD solver = new TaskD();
        solver.solve(in, out);

        out.close();
    }

    static class TaskD {
        public void solve(InputReader in, PrintWriter out) {
            int n = in.nextInt();
            int k = in.nextInt();

            // Read grid into char array for efficient access
            char[][] grid = new char[n][];
            for (int i = 0; i < n; ++i) {
                grid[i] = in.next().toCharArray();
            }

            // 1. Process Rows: Find first and last occurrence of 'B' in each row
            int[] rowFirst = new int[n];
            int[] rowLast = new int[n];
            int emptyRows = 0;

            for (int i = 0; i < n; ++i) {
                rowFirst[i] = -1;
                rowLast[i] = -1;
                for (int j = 0; j < n; ++j) {
                    if (grid[i][j] == 'B') {
                        if (rowFirst[i] == -1) {
                            rowFirst[i] = j;
                        }
                        rowLast[i] = j;
                    }
                }
                if (rowFirst[i] == -1) {
                    emptyRows++;
                }
            }

            // 2. Process Columns: Find first and last occurrence of 'B' in each column
            int[] colFirst = new int[n];
            int[] colLast = new int[n];
            int emptyCols = 0;

            for (int j = 0; j < n; ++j) {
                colFirst[j] = -1;
                colLast[j] = -1;
                for (int i = 0; i < n; ++i) {
                    if (grid[i][j] == 'B') {
                        if (colFirst[j] == -1) {
                            colFirst[j] = i;
                        }
                        colLast[j] = i;
                    }
                }
                if (colFirst[j] == -1) {
                    emptyCols++;
                }
            }

            // 3. Compute VR Matrix
            // vr[i][j] stores the number of rows in the vertical window [i, i+k-1]
            // that are fully contained within the horizontal window [j, j+k-1].
            int[][] vr = computeVR(n, k, rowFirst, rowLast);

            // 4. Compute VC Matrix
            // vc[i][j] stores the number of columns in the horizontal window [j, j+k-1]
            // that are fully contained within the vertical window [i, i+k-1].
            int[][] vc = computeVC(n, k, colFirst, colLast);

            // 5. Find Maximum Sum
            int maxVal = 0;
            int limit = n - k;

            // If k > n, limit is negative, loops won't run, maxVal remains 0.
            if (limit >= 0) {
                for (int i = 0; i <= limit; ++i) {
                    for (int j = 0; j <= limit; ++j) {
                        int currentSum = vr[i][j] + vc[i][j];
                        if (currentSum > maxVal) {
                            maxVal = currentSum;
                        }
                    }
                }
            }

            out.println(maxVal + emptyRows + emptyCols);
        }

        /**
         * Computes the VR matrix.
         * vr[i][j] is the count of rows in vertical range [i, i+k-1] 
         * whose 'B's are horizontally contained in range [j, j+k-1].
         */
        private int[][] computeVR(int n, int k, int[] rowFirst, int[] rowLast) {
            int[][] vr = new int[n][n];
            // Reusable buffer for row validity to avoid allocation in loop
            boolean[] rowValid = new boolean[n];

            // Iterate over horizontal window start position j
            for (int j = 0; j <= n - k; ++j) {
                // Determine which rows are valid for this horizontal window
                for (int i = 0; i < n; ++i) {
                    // A row is valid if its first and last 'B' are within [j, j+k-1]
                    // If rowFirst[i] is -1 (empty row), condition fails naturally
                    rowValid[i] = (rowFirst[i] >= j && rowLast[i] <= j + k - 1);
                }

                // Compute sliding window sum over rows for this j
                int sum = 0;
                // Initial window [0, k-1]
                for (int i = 0; i < k; ++i) {
                    if (rowValid[i]) sum++;
                }
                vr[0][j] = sum;

                // Slide window down
                for (int i = 1; i <= n - k; ++i) {
                    if (rowValid[i - 1]) sum--;
                    if (rowValid[i + k - 1]) sum++;
                    vr[i][j] = sum;
                }
            }
            return vr;
        }

        /**
         * Computes the VC matrix.
         * vc[i][j] is the count of columns in horizontal range [j, j+k-1]
         * whose 'B's are vertically contained in range [i, i+k-1].
         */
        private int[][] computeVC(int n, int k, int[] colFirst, int[] colLast) {
            int[][] vc = new int[n][n];
            // Reusable buffer for column validity to avoid allocation in loop
            boolean[] colValid = new boolean[n];

            // Iterate over vertical window start position i
            for (int i = 0; i <= n - k; ++i) {
                // Determine which columns are valid for this vertical window
                for (int j = 0; j < n; ++j) {
                    // A column is valid if its first and last 'B' are within [i, i+k-1]
                    colValid[j] = (colFirst[j] >= i && colLast[j] <= i + k - 1);
                }

                // Compute sliding window sum over columns for this i
                int sum = 0;
                // Initial window [0, k-1]
                for (int j = 0; j < k; ++j) {
                    if (colValid[j]) sum++;
                }
                vc[i][0] = sum;

                // Slide window right
                for (int j = 1; j <= n - k; ++j) {
                    if (colValid[j - 1]) sum--;
                    if (colValid[j + k - 1]) sum++;
                    vc[i][j] = sum;
                }
            }
            return vc;
        }
    }

    static class InputReader {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            String s = next();
            if (s == null) return 0;
            return Integer.parseInt(s);
        }
    }
}

import java.io.*;
import java.util.*;

public class Round578D {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out));

        int n = reader.nextInt();
        int k = reader.nextInt();
        char[][] grid = new char[n][n];
        for (int i = 0; i < n; i++) {
            grid[i] = reader.next().toCharArray();
        }

        int[][] ans = new int[n][n];

        // --- Process Columns ---
        // colPrefix[i][j] stores the cumulative count of 'B's in column j up to row i-1
        int[][] colPrefix = new int[n + 1][n];
        for (int i = 1; i <= n; i++) {
            for (int j = 0; j < n; j++) {
                colPrefix[i][j] = colPrefix[i - 1][j] + (grid[i - 1][j] == 'B' ? 1 : 0);
            }
        }

        int emptyColCount = 0;
        for (int j = 0; j < n; j++) {
            if (colPrefix[n][j] == 0) {
                emptyColCount++;
            }
        }

        for (int i = 0; i <= n - k; i++) { // Window start row
            int fullColsInWindow = 0;

            // Initialize window with the first k columns
            for (int j = 0; j < k; j++) {
                if (isLineFullyContained(colPrefix[n][j], colPrefix[i + k][j] - colPrefix[i][j])) {
                    fullColsInWindow++;
                }
            }
            ans[i][0] = fullColsInWindow + emptyColCount;

            // Slide the window across columns
            for (int j = 1; j <= n - k; j++) {
                int leavingCol = j - 1;
                int enteringCol = j + k - 1;

                if (isLineFullyContained(colPrefix[n][leavingCol], colPrefix[i + k][leavingCol] - colPrefix[i][leavingCol])) {
                    fullColsInWindow--;
                }
                if (isLineFullyContained(colPrefix[n][enteringCol], colPrefix[i + k][enteringCol] - colPrefix[i][enteringCol])) {
                    fullColsInWindow++;
                }
                ans[i][j] = fullColsInWindow + emptyColCount;
            }
        }

        // --- Process Rows ---
        // rowPrefix[j][i] stores the cumulative count of 'B's in row j up to column i-1
        int[][] rowPrefix = new int[n][n + 1];
        for (int j = 0; j < n; j++) {
            for (int i = 1; i <= n; i++) {
                rowPrefix[j][i] = rowPrefix[j][i - 1] + (grid[j][i - 1] == 'B' ? 1 : 0);
            }
        }

        int emptyRowCount = 0;
        for (int j = 0; j < n; j++) {
            if (rowPrefix[j][n] == 0) {
                emptyRowCount++;
            }
        }

        for (int i = 0; i <= n - k; i++) { // Window start column
            int fullRowsInWindow = 0;

            // Initialize window with the first k rows
            for (int j = 0; j < k; j++) {
                if (isLineFullyContained(rowPrefix[j][n], rowPrefix[j][i + k] - rowPrefix[j][i])) {
                    fullRowsInWindow++;
                }
            }
            ans[0][i] += fullRowsInWindow + emptyRowCount;

            // Slide the window across rows
            for (int j = 1; j <= n - k; j++) {
                int leavingRow = j - 1;
                int enteringRow = j + k - 1;

                if (isLineFullyContained(rowPrefix[leavingRow][n], rowPrefix[leavingRow][i + k] - rowPrefix[leavingRow][i])) {
                    fullRowsInWindow--;
                }
                if (isLineFullyContained(rowPrefix[enteringRow][n], rowPrefix[enteringRow][i + k] - rowPrefix[enteringRow][i])) {
                    fullRowsInWindow++;
                }
                ans[j][i] += fullRowsInWindow + emptyRowCount;
            }
        }

        // Find the maximum value in the result matrix
        int maxVal = 0;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                maxVal = Math.max(maxVal, ans[i][j]);
            }
        }

        out.println(maxVal);
        out.flush();
    }

    /**
     * Checks if a line (row or column) is fully contained within the sliding window.
     * A line is considered fully contained if it has at least one 'B' and all of its 'B's
     * fall within the current window boundaries.
     */
    private static boolean isLineFullyContained(int totalOnes, int onesInWindow) {
        return totalOnes > 0 && totalOnes == onesInWindow;
    }

    /**
     * Fast I/O helper class optimized for competitive programming environments.
     */
    public static class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastReader(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) {
                        return null;
                    }
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input", e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            String s = next();
            return s == null ? 0 : Integer.parseInt(s);
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

/**
 * Calculates the maximum coverage for any k x k subgrid within an n x n grid.
 * The grid consists of 'W' (walls/occupied) and other characters (empty).
 * The algorithm computes bounds of empty cells per row/column, counts fully 
 * occupied lines, and uses suffix sums with inclusion-exclusion to find 
 * the optimal subgrid configuration.
 */
public class GridCoverageCalculator {

    public static void main(String[] args) throws IOException {
        // Use try-with-resources for automatic stream management
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(System.in))) {
            String line = reader.readLine();
            if (line == null) {
                return;
            }

            StringTokenizer tokenizer = new StringTokenizer(line);
            int n = Integer.parseInt(tokenizer.nextToken());
            int k = Integer.parseInt(tokenizer.nextToken());

            boolean[][] grid = readGrid(reader, n);
            int[][] rowBounds = computeLineBounds(grid, n);
            int[][] colBounds = computeLineBounds(grid, n);

            int emptyLinesCount = countFullyOccupiedLines(rowBounds, colBounds, n);
            int maxCoverage = calculateMaxSubgridCoverage(grid, rowBounds, colBounds, n, k);

            System.out.println(maxCoverage + emptyLinesCount);
        }
    }

    /**
     * Reads the n x n grid from the input stream.
     * true represents 'W', false represents other characters.
     */
    private static boolean[][] readGrid(BufferedReader reader, int n) throws IOException {
        boolean[][] grid = new boolean[n][n];
        for (int i = 0; i < n; i++) {
            String line = reader.readLine();
            for (int j = 0; j < n; j++) {
                grid[i][j] = line.charAt(j) == 'W';
            }
        }
        return grid;
    }

    /**
     * Computes the first and last occurrence indices of non-'W' cells
     * for each row and column. Initialized to -1 if no such cell exists.
     */
    private static int[][] computeLineBounds(boolean[][] grid, int n) {
        int[][] bounds = new int[n][2];
        for (int i = 0; i < n; i++) {
            bounds[i][0] = -1;
            bounds[i][1] = -1;
        }

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (!grid[i][j]) {
                    bounds[i][1] = j;
                    if (bounds[i][0] == -1) {
                        bounds[i][0] = j;
                    }
                }
            }
        }
        return bounds;
    }

    /**
     * Counts rows and columns that contain no non-'W' cells (completely filled).
     */
    private static int countFullyOccupiedLines(int[][] rowBounds, int[][] colBounds, int n) {
        int count = 0;
        for (int i = n - 1; i >= 0; i--) {
            if (rowBounds[i][0] == -1) {
                count++;
            }
            if (colBounds[i][0] == -1) {
                count++;
            }
        }
        return count;
    }

    /**
     * Calculates the maximum coverage value for any k x k subgrid using
     * suffix sums and inclusion-exclusion principles.
     */
    private static int calculateMaxSubgridCoverage(boolean[][] grid, int[][] rowBounds, 
                                                   int[][] colBounds, int n, int k) {
        int[][] colCoverage = new int[n][n];
        int[][] rowCoverage = new int[n][n];

        // Mark coverage cells where all non-'W' cells in a line fall within the k-window
        for (int i = n - 1; i >= 0; i--) {
            for (int j = n - 1; j >= 0; j--) {
                if (i <= n - k) {
                    if (colBounds[j][0] >= i && colBounds[j][1] < i + k) {
                        colCoverage[i][j] = 1;
                    }
                }
                if (j <= n - k) {
                    if (rowBounds[i][0] >= j && rowBounds[i][1] < j + k) {
                        rowCoverage[i][j] = 1;
                    }
                }
            }
        }

        // Compute suffix sums for columns
        for (int i = n - 1; i >= 0; i--) {
            for (int j = n - 2; j >= 0; j--) {
                colCoverage[i][j] += colCoverage[i][j + 1];
            }
        }

        // Compute suffix sums for rows
        for (int i = n - 2; i >= 0; i--) {
            for (int j = n - 1; j >= 0; j--) {
                rowCoverage[i][j] += rowCoverage[i + 1][j];
            }
        }

        // Apply inclusion-exclusion to find the maximum value in any k x k window
        int maxCoverage = 0;
        for (int i = n - k; i >= 0; i--) {
            for (int j = n - k; j >= 0; j--) {
                int current = colCoverage[i][j] + rowCoverage[i][j];
                if (i + k < n) {
                    current -= rowCoverage[i + k][j];
                }
                if (j + k < n) {
                    current -= colCoverage[i][j + k];
                }
                maxCoverage = Math.max(maxCoverage, current);
            }
        }

        return maxCoverage;
    }
}

import java.io.IOException;
import java.io.InputStream;
import java.io.OutputStream;
import java.io.PrintWriter;
import java.util.InputMismatchException;

/**
 * Main entry point for the White Lines solver.
 * Refactored to improve readability, remove code duplication, and follow 
 * standard Java naming conventions and structural patterns.
 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;

        FastReader in = new FastReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);

        WhiteLinesSolver solver = new WhiteLinesSolver();
        solver.solve(in, out);

        out.close();
    }

    /**
     * Solves the White Lines problem using prefix sums and sliding window DP.
     */
    static class WhiteLinesSolver {
        public void solve(FastReader in, PrintWriter out) {
            int n = in.nextInt();
            int k = in.nextInt();

            // Read grid using idiomatic 0-based indexing
            char[][] grid = new char[n][];
            for (int i = 0; i < n; i++) {
                grid[i] = in.next().toCharArray();
            }

            // 1. Compute prefix sums for rows and columns
            int[][] rowPrefix = computePrefixSums(grid, n, true);
            int[][] colPrefix = computePrefixSums(grid, n, false);

            // 2. Count how many rows/cols contain at least one black cell up to each index
            int[] rowsWithBlack = computeAccumulatedLineCounts(rowPrefix, n, true);
            int[] colsWithBlack = computeAccumulatedLineCounts(colPrefix, n, false);

            // 3. Compute DP tables: number of "incomplete" lines in sliding k-window
            int[][] rowBadCounts = computeWindowBadCounts(n, k, rowPrefix, true);
            int[][] colBadCounts = computeWindowBadCounts(n, k, colPrefix, false);

            // 4. Find maximum score across all valid k x k subgrids
            long maxScore = 0;
            for (int i = k - 1; i < n; i++) {
                for (int j = k - 1; j < n; j++) {
                    long score = calculateScore(n, k, i, j, rowBadCounts, colBadCounts, rowsWithBlack, colsWithBlack);
                    if (score > maxScore) {
                        maxScore = score;
                    }
                }
            }
            out.println(maxScore);
        }

        /**
         * Computes 2D prefix sums for either rows or columns.
         */
        private int[][] computePrefixSums(char[][] grid, int n, boolean isRow) {
            int[][] prefix = new int[n][n];
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < n; j++) {
                    int prev = isRow ? (j > 0 ? prefix[i][j - 1] : 0) : (i > 0 ? prefix[i - 1][j] : 0);
                    prefix[i][j] = prev + (grid[i][j] == 'B' ? 1 : 0);
                }
            }
            return prefix;
        }

        /**
         * Computes an array where each index i holds the count of lines 
         * (rows or columns) containing at least one black cell from index 0 to i.
         */
        private int[] computeAccumulatedLineCounts(int[][] prefix, int n, boolean isRow) {
            int[] counts = new int[n];
            int lastCount = 0;
            for (int i = 0; i < n; i++) {
                int totalInLine = isRow ? prefix[i][n - 1] : prefix[n - 1][i];
                if (totalInLine > 0) {
                    lastCount++;
                }
                counts[i] = lastCount;
            }
            return counts;
        }

        /**
         * Computes the number of "bad" lines (lines that don't have all their 
         * black cells within the sliding window) for each window position.
         */
        private int[][] computeWindowBadCounts(int n, int k, int[][] prefix, boolean isRow) {
            int[][] badCounts = new int[n][n];

            // Slide the window end from k-1 to n-1
            for (int winEnd = k - 1; winEnd < n; winEnd++) {
                int winStart = winEnd - k + 1;
                int currentBad = 0;

                // Initialize for the first window
                for (int line = 0; line < k; line++) {
                    if (!isLineComplete(prefix, line, winStart, winEnd, isRow, n)) {
                        currentBad++;
                    }
                }
                badCounts[k - 1][winEnd] = currentBad;

                // Slide the window vertically/horizontally
                for (int line = k; line < n; line++) {
                    int enteringLine = line;
                    int leavingLine = line - k;

                    boolean enteringBad = !isLineComplete(prefix, enteringLine, winStart, winEnd, isRow, n);
                    boolean leavingBad = !isLineComplete(prefix, leavingLine, winStart, winEnd, isRow, n);

                    currentBad += (enteringBad ? 1 : 0) - (leavingBad ? 1 : 0);
                    badCounts[line][winEnd] = currentBad;
                }
            }
            return badCounts;
        }

        /**
         * Checks if all black cells in a specific line fall within the given window.
         */
        private boolean isLineComplete(int[][] prefix, int lineIdx, int winStart, int winEnd, boolean isRow, int n) {
            int countInWindow = isRow
                ? prefix[lineIdx][winEnd] - (winStart > 0 ? prefix[lineIdx][winStart - 1] : 0)
                : prefix[winEnd][lineIdx] - (winStart > 0 ? prefix[winStart - 1][lineIdx] : 0);

            int totalInLine = isRow ? prefix[lineIdx][n - 1] : prefix[n - 1][lineIdx];
            return countInWindow == totalInLine;
        }

        /**
         * Calculates the score for a k x k subgrid defined by its bottom-right corner (i, j).
         */
        private long calculateScore(int n, int k, int i, int j, int[][] rowBadCounts, int[][] colBadCounts, 
                                    int[] rowsWithBlack, int[] colsWithBlack) {
            // Lines outside the current window that contain black cells
            int rowsOutsideWindow = rowsWithBlack[n - 1] - rowsWithBlack[i] + (i >= k ? rowsWithBlack[i - k] : 0);
            int colsOutsideWindow = colsWithBlack[n - 1] - colsWithBlack[j] + (j >= k ? colsWithBlack[j - k] : 0);

            // Formula derivation:
            // Total possible lines = n (rows) + n (cols)
            // Subtract incomplete lines inside window (badCounts)
            // Subtract lines outside window that still contain black cells (they prevent full white lines)
            return (long) n - rowBadCounts[i][j] - rowsOutsideWindow
                 + (long) n - colBadCounts[i][j] - colsOutsideWindow;
        }
    }

    /**
     * Optimized fast input reader for competitive programming style I/O.
     * Refactored to remove unused interfaces, simplify whitespace handling,
     * and improve readability.
     */
    static class FastReader {
        private final InputStream stream;
        private final byte[] buffer = new byte[1024];
        private int bufferPtr = 0;
        private int bytesRead = 0;

        public FastReader(InputStream stream) {
            this.stream = stream;
        }

        private int read() throws IOException {
            if (bufferPtr == bytesRead) {
                bufferPtr = 0;
                bytesRead = stream.read(buffer);
                if (bytesRead <= 0) {
                    return -1;
                }
            }
            return buffer[bufferPtr++];
        }

        public int nextInt() {
            try {
                int c = read();
                while (c <= ' ') {
                    if (c == -1) throw new InputMismatchException();
                    c = read();
                }
                int sign = 1;
                if (c == '-') {
                    sign = -1;
                    c = read();
                }
                int res = 0;
                do {
                    if (c < '0' || c > '9') throw new InputMismatchException();
                    res = res * 10 + c - '0';
                    c = read();
                } while (c > ' ');
                return res * sign;
            } catch (IOException e) {
                throw new InputMismatchException();
            }
        }

        public String next() {
            try {
                int c = read();
                while (c <= ' ') {
                    if (c == -1) throw new InputMismatchException();
                    c = read();
                }
                StringBuilder sb = new StringBuilder();
                do {
                    sb.append((char) c);
                    c = read();
                } while (c > ' ');
                return sb.toString();
            } catch (IOException e) {
                throw new InputMismatchException();
            }
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

public class Codeforces1200D {

    public static void main(String[] args) throws IOException {
        // Use try-with-resources for automatic resource management
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            String line = br.readLine();
            if (line == null) return;

            StringTokenizer st = new StringTokenizer(line);
            int n = Integer.parseInt(st.nextToken());
            int k = Integer.parseInt(st.nextToken());

            // Read the grid
            // grid[i][j] is true if the cell is 'W' (White), false otherwise (Black)
            boolean[][] grid = new boolean[n][n];
            for (int i = 0; i < n; i++) {
                String rowStr = br.readLine();
                if (rowStr != null) {
                    StringTokenizer rowSt = new StringTokenizer(rowStr);
                    if (rowSt.hasMoreTokens()) {
                        String s = rowSt.nextToken();
                        // Assuming the input string represents the row characters contiguously
                        for (int j = 0; j < n && j < s.length(); j++) {
                            grid[i][j] = (s.charAt(j) == 'W');
                        }
                    }
                }
            }

            // 1. Calculate the count of rows and columns that contain NO black pixels.
            // This corresponds to the variable 'ctr' in the original code.
            int emptyLinesCount = countEmptyLines(grid, n);

            // 2. Calculate horizontal coverage.
            // rowSpanCoverage[i][j] = 1 if a horizontal window of size k starting at column j in row i
            // covers the span of black pixels in that row.
            int[][] rowSpanCoverage = calculateRowSpanCoverage(grid, n, k);

            // 3. Calculate vertical coverage.
            // colSpanCoverage[r][c] = 1 if a vertical window of size k starting at row r in column c
            // covers the span of black pixels in that column.
            int[][] colSpanCoverage = calculateColSpanCoverage(grid, n, k);

            // 4. Calculate 2D sliding window sums.
            // rowOccupancyCounts[y][x] stores the number of rows in the vertical window [y, y+k-1]
            // that have horizontal coverage at column x.
            int[][] rowOccupancyCounts = calculateVerticalSlidingSum(rowSpanCoverage, k);

            // colOccupancyCounts[y][x] stores the number of columns in the horizontal window [x, x+k-1]
            // that have vertical coverage at row y.
            int[][] colOccupancyCounts = calculateHorizontalSlidingSum(colSpanCoverage, k);

            // 5. Find the maximum occupancy.
            int maxOccupancy = 0;
            int limit = n - k + 1;
            for (int i = 0; i < limit; i++) {
                for (int j = 0; j < limit; j++) {
                    int currentOccupancy = rowOccupancyCounts[i][j] + colOccupancyCounts[i][j];
                    if (currentOccupancy > maxOccupancy) {
                        maxOccupancy = currentOccupancy;
                    }
                }
            }

            // Output result
            System.out.println(maxOccupancy + emptyLinesCount);
        }
    }

    /**
     * Counts the number of rows and columns that contain no black pixels.
     * A cell is black if grid[i][j] is false (since grid[i][j] is true for 'W').
     */
    private static int countEmptyLines(boolean[][] grid, int n) {
        int count = 0;

        // Check rows
        for (int i = 0; i < n; i++) {
            boolean hasBlack = false;
            for (int j = 0; j < n; j++) {
                if (!grid[i][j]) {
                    hasBlack = true;
                    break;
                }
            }
            if (!hasBlack) {
                count++;
            }
        }

        // Check columns
        for (int j = 0; j < n; j++) {
            boolean hasBlack = false;
            for (int i = 0; i < n; i++) {
                if (!grid[i][j]) {
                    hasBlack = true;
                    break;
                }
            }
            if (!hasBlack) {
                count++;
            }
        }

        return count;
    }

    /**
     * Calculates a 2D array where coverage[i][j] is 1 if a horizontal window of size k
     * starting at column j in row i intersects the range of black pixels in row i.
     */
    private static int[][] calculateRowSpanCoverage(boolean[][] grid, int n, int k) {
        int[][] coverage = new int[n][n - k + 1];

        for (int i = 0; i < n; i++) {
            int firstBlack = -1;
            int lastBlack = -1;

            // Find the range of black pixels in the row
            for (int j = 0; j < n; j++) {
                if (!grid[i][j]) { // If not 'W', it's black
                    lastBlack = j;
                    if (firstBlack == -1) {
                        firstBlack = j;
                    }
                }
            }

            // If no black pixels, coverage remains 0
            if (firstBlack == -1) {
                continue;
            }

            // Determine the valid range of window start positions [start, end)
            // A window starting at j covers indices [j, j + k - 1].
            // The logic preserves the original algorithm's constraints:
            // Lower bound depends on lastBlack, Upper bound depends on firstBlack.
            int start = Math.max(0, lastBlack - k + 1);
            int end = Math.min(n - k + 1, firstBlack + 1); // Exclusive upper bound

            for (int j = start; j < end; j++) {
                coverage[i][j] = 1;
            }
        }

        return coverage;
    }

    /**
     * Calculates a 2D array where coverage[r][c] is 1 if a vertical window of size k
     * starting at row r in column c intersects the range of black pixels in column c.
     */
    private static int[][] calculateColSpanCoverage(boolean[][] grid, int n, int k) {
        // Dimensions: (n - k + 1) rows, n columns
        int[][] coverage = new int[n - k + 1][n];

        for (int c = 0; c < n; c++) {
            int firstBlack = -1;
            int lastBlack = -1;

            // Find the range of black pixels in the column
            for (int r = 0; r < n; r++) {
                if (!grid[r][c]) { // If not 'W', it's black
                    lastBlack = r;
                    if (firstBlack == -1) {
                        firstBlack = r;
                    }
                }
            }

            // If no black pixels, coverage remains 0
            if (firstBlack == -1) {
                continue;
            }

            int start = Math.max(0, lastBlack - k + 1);
            int end = Math.min(n - k + 1, firstBlack + 1); // Exclusive upper bound

            for (int r = start; r < end; r++) {
                coverage[r][c] = 1;
            }
        }

        return coverage;
    }

    /**
     * Computes the vertical sliding window sum of size k.
     * Input matrix size: R x C. Output size: (R - k + 1) x C.
     */
    private static int[][] calculateVerticalSlidingSum(int[][] matrix, int k) {
        int rows = matrix.length;
        int cols = matrix[0].length;
        int[][] result = new int[rows - k + 1][cols];

        // Initialize the first window for each column
        for (int c = 0; c < cols; c++) {
            int sum = 0;
            for (int r = 0; r < k; r++) {
                sum += matrix[r][c];
            }
            result[0][c] = sum;
        }

        // Slide the window down
        for (int r = 1; r < rows - k + 1; r++) {
            for (int c = 0; c < cols; c++) {
                result[r][c] = result[r - 1][c] - matrix[r - 1][c] + matrix[r + k - 1][c];
            }
        }

        return result;
    }

    /**
     * Computes the horizontal sliding window sum of size k.
     * Input matrix size: R x C. Output size: R x (C - k + 1).
     */
    private static int[][] calculateHorizontalSlidingSum(int[][] matrix, int k) {
        int rows = matrix.length;
        int cols = matrix[0].length;
        int[][] result = new int[rows][cols - k + 1];

        // Initialize the first window for each row
        for (int r = 0; r < rows; r++) {
            int sum = 0;
            for (int c = 0; c < k; c++) {
                sum += matrix[r][c];
            }
            result[r][0] = sum;
        }

        // Slide the window right
        for (int c = 1; c < cols - k + 1; c++) {
            for (int r = 0; r < rows; r++) {
                result[r][c] = result[r][c - 1] - matrix[r][c - 1] + matrix[r][c + k - 1];
            }
        }

        return result;
    }
}

import java.io.*;
import java.util.*;

public class EdA {

    public static void main(String[] args) throws IOException {
        // Use try-with-resources for automatic and safe resource cleanup
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
             PrintWriter out = new PrintWriter(System.out)) {

            StringTokenizer st = new StringTokenizer(br.readLine());
            int n = Integer.parseInt(st.nextToken());
            int m = Integer.parseInt(st.nextToken());

            char[][] grid = new char[n][n];
            for (int i = 0; i < n; i++) {
                grid[i] = br.readLine().trim().toCharArray();
            }

            int emptyCount = 0;
            int[][] rowDiff = new int[n][n];
            int[][] colDiff = new int[n][n];

            // Process each row to find valid anchor positions
            for (int j = 0; j < n; j++) {
                int[] span = findBSpan(grid[j]);
                int start = span[0];
                int end = span[1];

                if (start == Integer.MAX_VALUE) {
                    // No 'B' found in this row
                    emptyCount++;
                } else if (end - start < m) {
                    // 'B' span fits within an m x m window; update difference array
                    updateDifferenceArray(rowDiff, n, m, j, start, end);
                }
            }
            computePrefixSums(rowDiff, n);

            // Process each column to find valid anchor positions
            for (int j = 0; j < n; j++) {
                int[] span = new int[]{Integer.MAX_VALUE, -1};
                for (int k = 0; k < n; k++) {
                    if (grid[k][j] == 'B') {
                        span[0] = Math.min(span[0], k);
                        span[1] = Math.max(span[1], k);
                    }
                }
                int start = span[0];
                int end = span[1];

                if (start == Integer.MAX_VALUE) {
                    emptyCount++;
                } else if (end - start < m) {
                    updateDifferenceArray(colDiff, n, m, j, start, end);
                }
            }
            computePrefixSums(colDiff, n);

            // Find the maximum combined overlap of rows and columns
            int maxOverlap = 0;
            for (int r = 0; r <= n - m; r++) {
                for (int c = 0; c <= n - m; c++) {
                    maxOverlap = Math.max(maxOverlap, rowDiff[r][c] + colDiff[c][r]);
                }
            }

            out.println(maxOverlap + emptyCount);
        }
    }

    /**
     * Finds the minimum and maximum indices of 'B' in a 1D character array.
     * @return int[]{minIndex, maxIndex}. Returns {Integer.MAX_VALUE, -1} if 'B' is absent.
     */
    private static int[] findBSpan(char[] line) {
        int min = Integer.MAX_VALUE;
        int max = -1;
        for (int i = 0; i < line.length; i++) {
            if (line[i] == 'B') {
                min = Math.min(min, i);
                max = Math.max(max, i);
            }
        }
        return new int[]{min, max};
    }

    /**
     * Applies a 1D difference array update for a valid range [L, R] across 
     * all anchor positions that would cover the current row/column.
     * 
     * @param diff The 2D difference array to update
     * @param n    Grid dimension
     * @param m    Window size
     * @param anchorIdx The index of the row/column being processed
     * @param start Minimum index of 'B'
     * @param end   Maximum index of 'B'
     */
    private static void updateDifferenceArray(int[][] diff, int n, int m, int anchorIdx, int start, int end) {
        // Calculate the valid range of anchor positions for this row/column
        int L = Math.max(0, end - m + 1);
        int R = Math.min(n - m, start);

        // If the range is invalid, no update is needed
        if (L > R) {
            return;
        }

        // Determine which anchor indices (k) are affected
        int rowStart = Math.max(0, anchorIdx - m + 1);
        int rowEnd = anchorIdx;

        for (int k = rowStart; k <= rowEnd; k++) {
            diff[k][L]++;
            if (R + 1 < n) {
                diff[k][R + 1]--;
            }
        }
    }

    /**
     * Computes prefix sums for each row in a 2D difference array to resolve actual counts.
     */
    private static void computePrefixSums(int[][] arr, int n) {
        for (int i = 0; i < n; i++) {
            for (int j = 1; j < n; j++) {
                arr[i][j] += arr[i][j - 1];
            }
        }
    }
}

import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        OutputWriter out = new OutputWriter(outputStream);

        WhiteLinesSolver solver = new WhiteLinesSolver();
        solver.solve(in, out);

        out.close();
    }

    /**
     * Solves the White Lines problem using prefix sums and a sliding window approach.
     * Computes the maximum number of complete white lines remaining after removing a k x k square.
     */
    static class WhiteLinesSolver {
        public void solve(InputReader in, OutputWriter out) {
            int n = in.nextInt();
            int k = in.nextInt();
            char[][] grid = new char[n][n];
            for (int i = 0; i < n; i++) {
                grid[i] = in.next().toCharArray();
            }

            // 1. Count fully white rows and columns
            int[] fullRows = new int[n + 1];
            int[] fullCols = new int[n + 1];
            int totalFullLines = 0;

            for (int i = 0; i < n; i++) {
                if (isFullRow(grid, i)) {
                    totalFullLines++;
                    fullRows[i + 1] = 1;
                }
            }
            for (int j = 0; j < n; j++) {
                if (isFullColumn(grid, j)) {
                    totalFullLines++;
                    fullCols[j + 1] = 1;
                }
            }

            // Prefix sums for full lines to allow O(1) range queries
            for (int i = 1; i <= n; i++) {
                fullRows[i] += fullRows[i - 1];
                fullCols[i] += fullCols[i - 1];
            }

            // 2. Compute continuous white segments in 4 directions
            // Padding with +2 simplifies boundary checks by acting as sentinels
            int size = n + 2;
            boolean[][][] continuous = new boolean[4][size][size];

            // Initialize boundaries to true (sentinels for propagation)
            for (int d = 0; d < 4; d++) {
                for (int i = 0; i < size; i++) {
                    Arrays.fill(continuous[d][i], true);
                }
            }

            // Overwrite interior with actual grid data (shifted by 1)
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < n; j++) {
                    continuous[0][i + 1][j + 1] = (grid[i][j] == 'W'); // Left-to-Right
                    continuous[1][i + 1][j + 1] = (grid[i][j] == 'W'); // Right-to-Left
                    continuous[2][i + 1][j + 1] = (grid[i][j] == 'W'); // Top-to-Bottom
                    continuous[3][i + 1][j + 1] = (grid[i][j] == 'W'); // Bottom-to-Top
                }
            }

            // Propagate continuity: Horizontal directions
            for (int i = 1; i <= n; i++) {
                for (int j = 2; j <= n + 1; j++) {
                    continuous[0][i][j] &= continuous[0][i][j - 1];
                }
                for (int j = n; j >= 1; j--) {
                    continuous[1][i][j] &= continuous[1][i][j + 1];
                }
            }

            // Propagate continuity: Vertical directions
            for (int j = 1; j <= n; j++) {
                for (int i = 2; i <= n + 1; i++) {
                    continuous[2][i][j] &= continuous[2][i - 1][j];
                }
                for (int i = n; i >= 1; i--) {
                    continuous[3][i][j] &= continuous[3][i + 1][j];
                }
            }

            // 3. Count valid k-length segments
            int[][] horizontalSegments = new int[size][size];
            int[][] verticalSegments = new int[size][size];

            for (int i = 1; i <= n; i++) {
                for (int j = 1; j <= n - k + 1; j++) {
                    // Horizontal segment of length k starting at (i, j)
                    if (continuous[0][i][j - 1] && continuous[1][i][j + k]) {
                        horizontalSegments[i][j] = 1;
                    }
                    // Vertical segment of length k starting at (j, i)
                    if (continuous[2][j - 1][i] && continuous[3][j + k][i]) {
                        verticalSegments[j][i] = 1;
                    }
                }
            }

            // Prefix sums for segment counts
            for (int i = 1; i < size; i++) {
                for (int j = 1; j < size; j++) {
                    horizontalSegments[i][j] += horizontalSegments[i - 1][j];
                    verticalSegments[i][j] += verticalSegments[i][j - 1];
                }
            }

            // 4. Sliding window to find maximum remaining lines
            int maxLines = 0;
            for (int i = 1; i <= n - k + 1; i++) {
                for (int j = 1; j <= n - k + 1; j++) {
                    // Lines completely removed by the k x k window
                    int removedRows = fullRows[i + k - 1] - fullRows[i - 1];
                    int removedCols = fullCols[j + k - 1] - fullCols[j - 1];

                    // Lines that become complete inside the window boundaries
                    int addedHorizontal = horizontalSegments[i + k - 1][j] - horizontalSegments[i - 1][j];
                    int addedVertical = verticalSegments[i][j + k - 1] - verticalSegments[i][j - 1];

                    int currentLines = totalFullLines - removedRows - removedCols + addedHorizontal + addedVertical;
                    maxLines = Math.max(maxLines, currentLines);
                }
            }

            out.println(maxLines);
        }

        private boolean isFullRow(char[][] grid, int row) {
            for (char c : grid[row]) {
                if (c != 'W') return false;
            }
            return true;
        }

        private boolean isFullColumn(char[][] grid, int col) {
            for (char[] row : grid) {
                if (row[col] != 'W') return false;
            }
            return true;
        }
    }

    /**
     * Fast output writer for competitive programming environments.
     */
    static class OutputWriter {
        private final PrintWriter writer;

        public OutputWriter(OutputStream outputStream) {
            writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(outputStream)));
        }

        public OutputWriter(Writer writer) {
            this.writer = new PrintWriter(writer);
        }

        public void close() {
            writer.close();
        }

        public void println(int i) {
            writer.println(i);
        }
    }

    /**
     * Fast input reader for competitive programming environments.
     */
    static class InputReader {
        private final InputStream stream;
        private final byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;
        private SpaceCharFilter filter;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        public int read() {
            if (numChars == -1) {
                throw new InputMismatchException();
            }
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0) {
                    return -1;
                }
            }
            return buf[curChar++];
        }

        public int nextInt() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                res *= 10;
                res += c - '0';
                c = read();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public String next() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            StringBuilder res = new StringBuilder();
            do {
                if (Character.isValidCodePoint(c)) {
                    res.appendCodePoint(c);
                }
                c = read();
            } while (!isSpaceChar(c));
            return res.toString();
        }

        public boolean isSpaceChar(int c) {
            return filter != null ? filter.isSpaceChar(c) : isWhitespace(c);
        }

        public static boolean isWhitespace(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        @FunctionalInterface
        public interface SpaceCharFilter {
            boolean isSpaceChar(int ch);
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

/**
 * Refactored solution for grid analysis problem.
 * 
 * This program reads an n x n grid containing 'B' characters and calculates a metric
 * based on sliding windows of size k x k. It uses a 2D difference array (prefix sum technique)
 * to efficiently mark valid regions where 'B' characters are contained within a window of size k.
 */
public class GridAnalyzer {

    public static void main(String[] args) throws IOException {
        // Initialize fast I/O
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter writer = new PrintWriter(System.out);

        // Read dimensions n and k
        String line = reader.readLine();
        if (line == null) {
            writer.flush();
            return;
        }
        StringTokenizer st = new StringTokenizer(line);
        int n = Integer.parseInt(st.nextToken());
        int k = Integer.parseInt(st.nextToken());

        // Read the grid
        // We map 'B' to 0 and any other character to 1 for easier processing
        int[][] grid = new int[n][n];
        for (int i = 0; i < n; i++) {
            String rowStr = reader.readLine();
            // Safety check for line length, though competitive programming inputs are usually well-formed
            int len = (rowStr != null) ? Math.min(rowStr.length(), n) : 0;
            for (int j = 0; j < len; j++) {
                grid[i][j] = (rowStr.charAt(j) == 'B') ? 0 : 1;
            }
        }

        // Difference array to store updates. Size is (n+1)x(n+1) to handle boundary conditions
        // comfortably (0 to n indices).
        int[][] differenceArray = new int[n + 1][n + 1];

        // 1. Process Rows
        // For each row, we identify the span of 'B's (0s). If the span fits within a window of size k,
        // we mark the valid window start positions in the difference array.
        for (int i = 0; i < n; i++) {
            int minJ = n;
            int maxJ = -1;

            // Find the first (minJ) and last (maxJ) occurrence of 'B' in the current row
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 0) {
                    maxJ = j;
                    if (minJ == n) {
                        minJ = j;
                    }
                }
            }

            if (minJ == n) {
                // No 'B's found in this row.
                // This implies that for this row, any k x k window is valid regarding 'B' containment.
                // We add 1 to the entire grid area in the difference array.
                updateDifferenceArray(differenceArray, 0, 0, n, n, 1);
            } else {
                // 'B's found. Check if they fit within a window of size k.
                // Condition: The distance between the first and last 'B' must be less than k.
                if (maxJ - minJ < k) {
                    // Determine the valid range of window start positions.
                    // A window starting at column 'c' covers columns [c, c + k - 1].
                    // To cover the 'B's in [minJ, maxJ], we need:
                    // c <= minJ  AND  c + k - 1 >= maxJ  =>  c >= maxJ - k + 1.
                    // Valid start columns: [maxJ - k + 1, minJ].

                    // Similarly for rows, the window must cover row i.
                    // Valid start rows: [i - k + 1, i].

                    // We update the difference array for the rectangle of valid window top-left corners.
                    // Note: differenceArray indices correspond to window top-left coordinates.

                    int r1 = Math.max(0, i - k + 1);
                    int r2 = i + 1; // Exclusive upper bound for row start
                    int c1 = Math.max(0, maxJ - k + 1);
                    int c2 = minJ + 1; // Exclusive upper bound for col start

                    updateDifferenceArray(differenceArray, r1, c1, r2, c2, 1);
                }
            }
        }

        // 2. Process Columns
        // Symmetric logic to rows: find vertical spans of 'B's and mark valid window positions.
        for (int j = 0; j < n; j++) {
            int minI = n;
            int maxI = -1;

            // Find the first (minI) and last (maxI) occurrence of 'B' in the current column
            for (int i = 0; i < n; i++) {
                if (grid[i][j] == 0) {
                    maxI = i;
                    if (minI == n) {
                        minI = i;
                    }
                }
            }

            if (minI == n) {
                // No 'B's found in this column.
                updateDifferenceArray(differenceArray, 0, 0, n, n, 1);
            } else {
                if (maxI - minI < k) {
                    // Valid start rows: [maxI - k + 1, minI]
                    int r1 = Math.max(0, maxI - k + 1);
                    int r2 = minI + 1; // Exclusive upper bound

                    // Valid start columns: [j - k + 1, j]
                    int c1 = Math.max(0, j - k + 1);
                    int c2 = j + 1; // Exclusive upper bound

                    updateDifferenceArray(differenceArray, r1, c1, r2, c2, 1);
                }
            }
        }

        // 3. Compute 2D Prefix Sums
        // Resolve the difference array to get the actual counts for each window position.

        // Horizontal accumulation (prefix sum along rows)
        for (int i = 1; i < n; i++) {
            differenceArray[i][0] += differenceArray[i - 1][0];
        }

        // Vertical accumulation (prefix sum along columns)
        for (int j = 1; j < n; j++) {
            differenceArray[0][j] += differenceArray[0][j - 1];
        }

        // 2D accumulation
        for (int i = 1; i < n; i++) {
            for (int j = 1; j < n; j++) {
                differenceArray[i][j] += differenceArray[i - 1][j] + differenceArray[i][j - 1] - differenceArray[i - 1][j - 1];
            }
        }

        // 4. Find the maximum value in the valid grid area
        int max = 0;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (differenceArray[i][j] > max) {
                    max = differenceArray[i][j];
                }
            }
        }

        writer.println(max);
        writer.flush();
    }

    /**
     * Updates the 2D difference array to add 'val' to the rectangle defined by
     * top-left (r1, c1) and bottom-right (r2, c2) coordinates.
     * The rectangle includes r1, c1 but excludes r2, c2 (standard half-open interval [r1, r2) x [c1, c2)).
     *
     * @param arr The difference array
     * @param r1  Top row index (inclusive)
     * @param c1  Left column index (inclusive)
     * @param r2  Bottom row index (exclusive)
     * @param c2  Right column index (exclusive)
     * @param val Value to add
     */
    private static void updateDifferenceArray(int[][] arr, int r1, int c1, int r2, int c2, int val) {
        arr[r1][c1] += val;
        arr[r2][c2] += val;
        arr[r2][c1] -= val;
        arr[r1][c2] -= val;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.Arrays;
import java.util.Map;
import java.util.Set;
import java.util.StringTokenizer;
import java.util.TreeMap;
import java.util.TreeSet;

/**
 * A solver for grid coverage problems.
 * Analyzes a grid to find optimal coverage based on bounding boxes of specific characters.
 */
public class GridCoverageSolver {

    public static void main(String[] args) throws IOException {
        // Initialize fast I/O
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));

        // Read dimensions n and k
        String line = reader.readLine();
        if (line == null) return;

        StringTokenizer st = new StringTokenizer(line);
        int n = Integer.parseInt(st.nextToken());
        int k = Integer.parseInt(st.nextToken());

        // Arrays to store bounding box coordinates of 'B' characters
        // rowMinCol[i] stores the minimum column index containing 'B' in row i
        int[] rowMinCol = new int[n];
        // rowMaxCol[i] stores the maximum column index containing 'B' in row i
        int[] rowMaxCol = new int[n];
        // colMinRow[j] stores the minimum row index containing 'B' in column j
        int[] colMinRow = new int[n];
        // colMaxRow[j] stores the maximum row index containing 'B' in column j
        int[] colMaxRow = new int[n];

        // Initialize arrays with -1 (indicating no 'B' found yet)
        Arrays.fill(rowMinCol, -1);
        Arrays.fill(rowMaxCol, -1);
        Arrays.fill(colMinRow, -1);
        Arrays.fill(colMaxRow, -1);

        // Read the grid and populate bounding boxes
        for (int i = 0; i < n; i++) {
            String gridRow = reader.readLine();
            if (gridRow == null) break;

            for (int j = 0; j < n; j++) {
                if (gridRow.charAt(j) == 'B') {
                    // Update row bounds
                    if (rowMinCol[i] == -1 || j < rowMinCol[i]) {
                        rowMinCol[i] = j;
                    }
                    if (j > rowMaxCol[i]) {
                        rowMaxCol[i] = j;
                    }

                    // Update column bounds
                    if (colMinRow[j] == -1 || i < colMinRow[j]) {
                        colMinRow[j] = i;
                    }
                    if (i > colMaxRow[j]) {
                        colMaxRow[j] = i;
                    }
                }
            }
        }

        // Count rows and columns that are completely empty (contain no 'B')
        int emptyRowsAndColsCount = 0;
        for (int i = 0; i < n; i++) {
            if (rowMinCol[i] == -1) emptyRowsAndColsCount++;
            if (colMinRow[i] == -1) emptyRowsAndColsCount++;
        }

        int globalMaxScore = 0;

        // Iterate through all possible starting rows for the k-height window
        for (int windowStartRow = 0; windowStartRow <= n - k; windowStartRow++) {
            int windowEndRow = windowStartRow + k; // Exclusive end bound

            // Maps to track the distribution of row spans within the current row window
            // Key: Column Index, Value: Count of rows in the window starting/ending at that column
            Map<Integer, Integer> rowCountStarts = new TreeMap<>();
            Map<Integer, Integer> rowCountEnds = new TreeMap<>();

            int rowsFittingMetric = 0; // Tracks a specific count of rows fitting the window criteria

            // Set of column indices that intersect with the current vertical row window
            Set<Integer> activeColumns = new TreeSet<>();

            // 1. Initialize data structures for the current row window
            for (int row = windowStartRow; row < windowEndRow; row++) {
                // Only consider rows that contain 'B's and have a width less than k
                if (rowMinCol[row] != -1 && (rowMaxCol[row] - rowMinCol[row]) < k) {
                    int startCol = rowMinCol[row];
                    int endCol = rowMaxCol[row];

                    rowCountStarts.put(startCol, rowCountStarts.getOrDefault(startCol, 0) + 1);
                    rowCountEnds.put(endCol, rowCountEnds.getOrDefault(endCol, 0) + 1);

                    // Original logic: count rows ending within the first k columns (0 to k-1)
                    if (endCol <= k - 1) {
                        rowsFittingMetric++;
                    }
                }
            }

            // 2. Initialize the set of active columns for the first column window (0 to k-1)
            // A column is active if its 'B's are vertically contained within the current row window
            for (int col = 0; col < k; col++) {
                if (colMaxRow[col] < windowEndRow && colMinRow[col] >= windowStartRow) {
                    activeColumns.add(col);
                }
            }

            // Update global maximum with the initial column window state
            globalMaxScore = Math.max(globalMaxScore, activeColumns.size() + rowsFittingMetric + emptyRowsAndColsCount);

            // 3. Slide the column window from left to right
            // The window shifts by one column to the right at each step
            for (int colSlideIndex = k; colSlideIndex < n; colSlideIndex++) {
                // Remove the column leaving the window (leftmost column of previous window)
                int leavingCol = colSlideIndex - k;
                activeColumns.remove(leavingCol);

                // Update the rows fitting metric:
                // Remove counts of rows that started at the leaving column
                rowsFittingMetric -= rowCountStarts.getOrDefault(leavingCol, 0);
                // Add counts of rows that end at the entering column
                rowsFittingMetric += rowCountEnds.getOrDefault(colSlideIndex, 0);

                // Check if the new entering column intersects the vertical row window
                if (colMaxRow[colSlideIndex] < windowEndRow && colMinRow[colSlideIndex] >= windowStartRow) {
                    activeColumns.add(colSlideIndex);
                }

                // Update global maximum with the new window state
                globalMaxScore = Math.max(globalMaxScore, activeColumns.size() + rowsFittingMetric + emptyRowsAndColsCount);
            }
        }

        System.out.println(globalMaxScore);
    }
}

import java.util.Scanner;
import java.util.Arrays;

public class WhiteLines2 {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        // Read grid dimensions n and k
        if (!scanner.hasNextInt()) return;
        int n = scanner.nextInt();
        int k = scanner.nextInt();
        scanner.nextLine(); // Consume the newline character after integers

        // Data structures to store the valid range of start positions for each row/column
        // to cover all black pixels in that line.
        // For a row r, the square's top-left column 'c' must be in [rowMinStartCol[r], rowMaxStartCol[r]]
        // to cover all black pixels in row r.
        int[] rowMinStartCol = new int[n];
        int[] rowMaxStartCol = new int[n];

        // For a column c, the square's top-left row 'r' must be in [colMinStartRow[c], colMaxStartRow[c]]
        // to cover all black pixels in column c.
        int[] colMinStartRow = new int[n];
        int[] colMaxStartRow = new int[n];

        boolean[] rowHasBlack = new boolean[n];
        boolean[] colHasBlack = new boolean[n];

        // Initialize ranges to full possible span [0, n-1]
        Arrays.fill(rowMinStartCol, 0);
        Arrays.fill(rowMaxStartCol, n - 1);
        Arrays.fill(colMinStartRow, 0);
        Arrays.fill(colMaxStartRow, n - 1);

        // Parse the grid
        for (int r = 0; r < n; r++) {
            String line = scanner.nextLine();
            for (int c = 0; c < n; c++) {
                if (line.charAt(c) == 'B') {
                    rowHasBlack[r] = true;
                    colHasBlack[c] = true;

                    // Update row constraints:
                    // To cover black pixel at (r, c), the square's horizontal start 'c_start'
                    // must satisfy: c_start <= c AND c_start + k - 1 >= c
                    // => c - k + 1 <= c_start <= c
                    rowMinStartCol[r] = Math.max(rowMinStartCol[r], c - k + 1);
                    rowMaxStartCol[r] = Math.min(rowMaxStartCol[r], c);

                    // Update column constraints:
                    // To cover black pixel at (r, c), the square's vertical start 'r_start'
                    // must satisfy: r_start <= r AND r_start + k - 1 >= r
                    // => r - k + 1 <= r_start <= r
                    colMinStartRow[c] = Math.max(colMinStartRow[c], r - k + 1);
                    colMaxStartRow[c] = Math.min(colMaxStartRow[c], r);
                }
            }
        }
        scanner.close();

        // Calculate base score: count lines that are already white (no black pixels)
        int baseScore = 0;
        for (int i = 0; i < n; i++) {
            if (!rowHasBlack[i]) baseScore++;
            if (!colHasBlack[i]) baseScore++;
        }

        int maxWhiteLines = baseScore;

        // Difference array to count how many rows in the current vertical strip
        // are covered by the square's horizontal span.
        // rowCoverageDiff[c] helps calculate the number of covered rows 
        // for a square starting at column c.
        int[] rowCoverageDiff = new int[n + 1];

        // Iterate over all possible top rows (y) of the k x k square
        for (int y = 0; y <= n - k; y++) {

            int currentScore = baseScore;

            // 1. Calculate contribution from columns for the square at column 0
            // The square covers columns [0, k-1].
            for (int c = 0; c < k; c++) {
                if (colHasBlack[c]) {
                    // Check if the square's vertical position y covers the black pixels in column c
                    if (colMinStartRow[c] <= y && y <= colMaxStartRow[c]) {
                        currentScore++;
                    }
                }
            }

            // 2. Build the difference array for row coverage
            // We consider rows inside the square's vertical strip: [y, y + k - 1]
            Arrays.fill(rowCoverageDiff, 0);
            for (int r = y; r < y + k; r++) {
                if (rowHasBlack[r]) {
                    int minStart = rowMinStartCol[r];
                    int maxStart = rowMaxStartCol[r];

                    // If the valid range is valid (min <= max), the row can be covered.
                    // We increment the count for all start columns in [minStart, maxStart].
                    if (minStart <= maxStart) {
                        rowCoverageDiff[minStart]++;
                        if (maxStart + 1 < rowCoverageDiff.length) {
                            rowCoverageDiff[maxStart + 1]--;
                        }
                    }
                }
            }

            // 3. Add row contribution for square at column 0
            // The number of covered rows is the prefix sum of the difference array at index 0.
            // Since minStart >= 0, rowCoverageDiff[0] is the correct count.
            currentScore += rowCoverageDiff[0];

            maxWhiteLines = Math.max(maxWhiteLines, currentScore);

            // 4. Slide the square horizontally
            // x is the current left column index of the square
            for (int x = 1; x <= n - k; x++) {

                // Update row contribution: add the change in covered rows count
                // rowCoverageDiff[x] is the difference in count between column x and x-1
                currentScore += rowCoverageDiff[x];

                // Update column contribution:
                // The square moves from [x-1, x+k-2] to [x, x+k-1]

                // Remove contribution of the column leaving the window (x-1)
                int leavingCol = x - 1;
                if (colHasBlack[leavingCol]) {
                    if (colMinStartRow[leavingCol] <= y && y <= colMaxStartRow[leavingCol]) {
                        currentScore--;
                    }
                }

                // Add contribution of the column entering the window (x + k - 1)
                int enteringCol = x + k - 1;
                if (colHasBlack[enteringCol]) {
                    if (colMinStartRow[enteringCol] <= y && y <= colMaxStartRow[enteringCol]) {
                        currentScore++;
                    }
                }

                maxWhiteLines = Math.max(maxWhiteLines, currentScore);
            }
        }

        System.out.println(maxWhiteLines);
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.HashSet;
import java.util.StringTokenizer;

/**
 * Solves a grid coverage problem using sliding window techniques.
 * Computes the maximum combined coverage of rows and columns within a k x k window.
 */
public class GridCoverageSolver {

    public static void main(String[] args) {
        FastReader scanner = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            int n = scanner.nextInt();
            int k = scanner.nextInt();
            char[][] grid = readGrid(scanner, n);

            int result = solve(n, k, grid);
            out.println(result);
        } catch (Exception e) {
            // In competitive programming environments, we typically assume well-formed input.
            // This block ensures graceful termination if unexpected issues occur.
        } finally {
            out.flush();
            out.close();
        }
    }

    /**
     * Reads the n x n character grid from input.
     */
    private static char[][] readGrid(FastReader scanner, int n) {
        char[][] grid = new char[n][n];
        for (int i = 0; i < n; i++) {
            grid[i] = scanner.next().toCharArray();
        }
        return grid;
    }

    /**
     * Orchestrates the coverage calculation and finds the maximum combined value.
     */
    private static int solve(int n, int k, char[][] grid) {
        if (k > n) {
            return 0;
        }

        // colCoverage[i][j] = number of columns in range [j, j+k-1] that contain 'B's 
        // within the row range [i, i+k-1].
        int[][] colCoverage = computeCoverage(grid, n, k, true);

        // rowCoverage[i][j] = number of rows in range [i, i+k-1] that contain 'B's 
        // within the column range [j, j+k-1].
        int[][] rowCoverage = computeCoverage(grid, n, k, false);

        int maxTotalCoverage = 0;
        for (int i = 0; i <= n - k; i++) {
            for (int j = 0; j <= n - k; j++) {
                maxTotalCoverage = Math.max(maxTotalCoverage, colCoverage[i][j] + rowCoverage[i][j]);
            }
        }
        return maxTotalCoverage;
    }

    /**
     * Computes a 2D coverage array using a sliding window approach.
     *
     * @param grid          The input character grid
     * @param n             Grid dimension
     * @param k             Window size
     * @param computeForColumns If true, computes coverage per column index; otherwise per row index
     * @return              2D array where coverage[start][windowStart] holds the count
     */
    private static int[][] computeCoverage(char[][] grid, int n, int k, boolean computeForColumns) {
        int[] firstPos = new int[n];
        int[] lastPos = new int[n];
        HashSet<Integer> emptyIndices = new HashSet<>();

        // Determine the first and last occurrence of 'B' for each line (column or row)
        for (int idx = 0; idx < n; idx++) {
            firstPos[idx] = Integer.MAX_VALUE;
            lastPos[idx] = Integer.MIN_VALUE;

            for (int pos = 0; pos < n; pos++) {
                char cell = computeForColumns ? grid[pos][idx] : grid[idx][pos];
                if (cell == 'B') {
                    firstPos[idx] = Math.min(firstPos[idx], pos);
                    lastPos[idx] = Math.max(lastPos[idx], pos);
                }
            }

            // Track lines that contain no 'B's at all
            if (firstPos[idx] == Integer.MAX_VALUE) {
                emptyIndices.add(idx);
            }
        }

        int[][] coverage = new int[n][n];

        // Sliding window over the second dimension
        for (int start = 0; start <= n - k; start++) {
            int end = start + k - 1;
            int count = emptyIndices.size();

            // Initialize count for the first window position
            for (int idx = 0; idx < k; idx++) {
                if (!emptyIndices.contains(idx) && start <= firstPos[idx] && lastPos[idx] <= end) {
                    count++;
                }
            }
            coverage[start][0] = count;

            // Slide the window across the remaining indices
            for (int idx = k; idx < n; idx++) {
                int prevIdx = idx - k;
                int newStartIdx = idx - k + 1;
                coverage[start][newStartIdx] = coverage[start][prevIdx];

                // Remove contribution of the element leaving the window
                if (!emptyIndices.contains(prevIdx) && start <= firstPos[prevIdx] && lastPos[prevIdx] <= end) {
                    coverage[start][newStartIdx]--;
                }

                // Add contribution of the element entering the window
                if (!emptyIndices.contains(idx) && start <= firstPos[idx] && lastPos[idx] <= end) {
                    coverage[start][newStartIdx]++;
                }
            }
        }

        return coverage;
    }

    /**
     * Fast I/O helper class. Replaces the custom byte-buffered reader with a 
     * standard, maintainable BufferedReader/StringTokenizer approach.
     */
    static class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastReader(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        public String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) {
                        return null;
                    }
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Input stream error", e);
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            String s = next();
            if (s == null) {
                throw new RuntimeException("Unexpected end of input");
            }
            return Integer.parseInt(s);
        }
    }
}

import java.io.*;
import java.util.Arrays;
import java.util.StringTokenizer;

public class Main {

    public static void main(String[] args) throws IOException {
        FastScanner scanner = new FastScanner(System.in);

        // Use try-with-resources to ensure proper flushing and closing of output
        try (PrintWriter out = new PrintWriter(System.out)) {
            int n = scanner.nextInt();
            int k = scanner.nextInt();

            // Dynamically size arrays based on input n instead of fixed 2000
            int[] topRow = new int[n];
            int[] bottomRow = new int[n];
            int[] leftCol = new int[n];
            int[] rightCol = new int[n];

            Arrays.fill(topRow, -1);
            Arrays.fill(bottomRow, -1);
            Arrays.fill(leftCol, -1);
            Arrays.fill(rightCol, -1);

            // Parse grid and record boundary coordinates for 'B' characters
            for (int i = 0; i < n; i++) {
                String row = scanner.next();
                for (int j = 0; j < row.length(); j++) {
                    if (row.charAt(j) == 'B') {
                        if (topRow[j] == -1) topRow[j] = i;
                        if (leftCol[i] == -1) leftCol[i] = j;
                        rightCol[i] = j;
                        bottomRow[j] = i;
                    }
                }
            }

            // Difference array to calculate coverage counts efficiently
            int[][] diffGrid = new int[n + 1][n + 1];

            // Apply difference array updates for vertical and horizontal constraints
            updateDifferenceGridForVertical(n, k, topRow, bottomRow, diffGrid);
            updateDifferenceGridForHorizontal(n, k, leftCol, rightCol, diffGrid);

            // Convert difference array to actual coverage counts using prefix sums
            computePrefixSums(diffGrid);

            // Find and print the maximum coverage
            int maxCoverage = findMaxValue(diffGrid);
            out.println(maxCoverage);
        }
    }

    /**
     * Applies difference array updates based on vertical boundaries (topRow, bottomRow).
     * Uses 2D difference array technique to mark valid placement regions.
     */
    private static void updateDifferenceGridForVertical(int n, int k, int[] topRow, int[] bottomRow, int[][] diffGrid) {
        for (int i = 0; i < n; i++) {
            if (topRow[i] == -1) {
                markGridCorners(diffGrid);
                continue;
            }
            if (bottomRow[i] - topRow[i] + 1 > k) continue;

            int r1 = Math.max(i - k + 1, 0);
            int c1 = Math.max(bottomRow[i] - k + 1, 0);
            int r2 = i + 1;
            int c2 = topRow[i] + 1;

            applyDiff(diffGrid, r1, c1, 1);
            applyDiff(diffGrid, r2, c1, -1);
            applyDiff(diffGrid, r1, c2, -1);
            applyDiff(diffGrid, r2, c2, 1);
        }
    }

    /**
     * Applies difference array updates based on horizontal boundaries (leftCol, rightCol).
     */
    private static void updateDifferenceGridForHorizontal(int n, int k, int[] leftCol, int[] rightCol, int[][] diffGrid) {
        for (int i = 0; i < n; i++) {
            if (leftCol[i] == -1) {
                markGridCorners(diffGrid);
                continue;
            }
            if (rightCol[i] - leftCol[i] + 1 > k) continue;

            int c1 = Math.max(rightCol[i] - k + 1, 0);
            int r1 = Math.max(i - k + 1, 0);
            int c2 = leftCol[i] + 1;
            int r2 = i + 1;

            applyDiff(diffGrid, r1, c1, 1);
            applyDiff(diffGrid, r2, c1, -1);
            applyDiff(diffGrid, r1, c2, -1);
            applyDiff(diffGrid, r2, c2, 1);
        }
    }

    /**
     * Increments/decrements the four corners of the difference grid.
     * Used when a row/column has no 'B' characters.
     */
    private static void markGridCorners(int[][] grid) {
        grid[0][0]++;
        grid[0][grid.length - 1]--;
        grid[grid.length - 1][0]--;
        grid[grid.length - 1][grid.length - 1]++;
    }

    /**
     * Applies a value to a single cell in the difference array.
     */
    private static void applyDiff(int[][] grid, int r, int c, int val) {
        grid[r][c] += val;
    }

    /**
     * Computes 2D prefix sums to convert the difference array into actual coverage counts.
     */
    private static void computePrefixSums(int[][] grid) {
        int n = grid.length - 1;

        // Row-wise prefix sums
        for (int i = 0; i <= n; i++) {
            for (int j = 1; j <= n; j++) {
                grid[i][j] += grid[i][j - 1];
            }
        }

        // Column-wise prefix sums
        for (int i = 1; i <= n; i++) {
            for (int j = 0; j <= n; j++) {
                grid[i][j] += grid[i - 1][j];
            }
        }
    }

    /**
     * Finds the maximum value in the computed coverage grid.
     */
    private static int findMaxValue(int[][] grid) {
        int max = 0;
        int n = grid.length - 1;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] > max) {
                    max = grid[i][j];
                }
            }
        }
        return max;
    }

    /**
     * Fast I/O helper class for competitive programming contexts.
     */
    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner(InputStream input) {
            br = new BufferedReader(new InputStreamReader(input));
        }

        String next() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) return null;
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

        int nextInt() throws IOException {
            String s = next();
            return s == null ? 0 : Integer.parseInt(s);
        }

        long nextLong() throws IOException {
            String s = next();
            return s == null ? 0L : Long.parseLong(s);
        }

        double nextDouble() throws IOException {
            String s = next();
            return s == null ? 0.0 : Double.parseDouble(s);
        }
    }
}

import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) {
        FastScanner in = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out);
        try {
            new Main().solve(in, out);
        } finally {
            out.flush();
        }
    }

    /**
     * Core logic to process the grid and compute the maximum window score.
     */
    private void solve(FastScanner in, PrintWriter out) {
        int n = in.nextInt();
        int k = in.nextInt();
        char[][] grid = new char[n][];
        for (int i = 0; i < n; i++) {
            grid[i] = in.next().toCharArray();
        }

        // Phase 1: Precompute row boundaries and edge prefix sums
        int[] rowRightBlockStart = new int[n];
        int[] rowLeftBlockEnd = new int[n];
        int[] rowEdgePrefixSum = new int[n + 1];

        for (int i = 0; i < n; i++) {
            // Find the leftmost index of the contiguous 'W' block touching the right edge
            rowRightBlockStart[i] = n;
            for (int j = n - 1; j >= 0 && grid[i][j] == 'W'; j--) {
                rowRightBlockStart[i] = j;
            }

            // Find the rightmost index of the contiguous 'W' block touching the left edge
            rowLeftBlockEnd[i] = -1;
            for (int j = 0; j < n && grid[i][j] == 'W'; j++) {
                rowLeftBlockEnd[i] = j;
            }

            rowEdgePrefixSum[i + 1] = rowEdgePrefixSum[i];
            if (rowRightBlockStart[i] == 0) {
                rowEdgePrefixSum[i + 1]++;
            }
        }

        // Phase 2: Precompute column boundaries and edge prefix sums
        int[] colBottomBlockStart = new int[n];
        int[] colTopBlockEnd = new int[n];
        int[] colEdgePrefixSum = new int[n + 1];

        for (int j = 0; j < n; j++) {
            // Find the topmost index of the contiguous 'W' block touching the bottom edge
            colBottomBlockStart[j] = n;
            for (int i = n - 1; i >= 0 && grid[i][j] == 'W'; i--) {
                colBottomBlockStart[j] = i;
            }

            // Find the bottommost index of the contiguous 'W' block touching the top edge
            colTopBlockEnd[j] = -1;
            for (int i = 0; i < n && grid[i][j] == 'W'; i++) {
                colTopBlockEnd[j] = i;
            }

            colEdgePrefixSum[j + 1] = colEdgePrefixSum[j];
            if (colBottomBlockStart[j] == 0) {
                colEdgePrefixSum[j + 1]++;
            }
        }

        // Phase 3: Calculate scores for each K x K window
        // windowScore[i][j] stores the metric for the K x K window with top-left at (i, j)
        int[][] windowScore = new int[n][n];

        // Row-based sliding window contribution
        for (int j = 0; j + k - 1 < n; j++) {
            int overlappingRowsCount = 0;
            // Initialize count for the first K-1 rows
            for (int i = 0; i < k - 1; i++) {
                if (rowRightBlockStart[i] <= j + k && rowLeftBlockEnd[i] >= j - 1) {
                    overlappingRowsCount++;
                }
            }

            // Slide the window down across rows
            for (int i = 0; i + k - 1 < n; i++) {
                int nextRow = i + k - 1;
                if (rowRightBlockStart[nextRow] <= j + k && rowLeftBlockEnd[nextRow] >= j - 1) {
                    overlappingRowsCount++;
                }
                if (i > 0 && rowRightBlockStart[i - 1] <= j + k && rowLeftBlockEnd[i - 1] >= j - 1) {
                    overlappingRowsCount--;
                }

                windowScore[i][j] = overlappingRowsCount
                    + rowEdgePrefixSum[i]
                    + rowEdgePrefixSum[n] - rowEdgePrefixSum[i + k];
            }
        }

        // Column-based sliding window contribution (adds to existing scores)
        for (int i = 0; i + k - 1 < n; i++) {
            int overlappingColsCount = 0;
            // Initialize count for the first K-1 columns
            for (int j = 0; j < k - 1; j++) {
                if (colBottomBlockStart[j] <= i + k && colTopBlockEnd[j] >= i - 1) {
                    overlappingColsCount++;
                }
            }

            // Slide the window right across columns
            for (int j = 0; j + k - 1 < n; j++) {
                int nextCol = j + k - 1;
                if (colBottomBlockStart[nextCol] <= i + k && colTopBlockEnd[nextCol] >= i - 1) {
                    overlappingColsCount++;
                }
                if (j > 0 && colBottomBlockStart[j - 1] <= i + k && colTopBlockEnd[j - 1] >= i - 1) {
                    overlappingColsCount--;
                }

                windowScore[i][j] += overlappingColsCount
                    + colEdgePrefixSum[j]
                    + colEdgePrefixSum[n] - colEdgePrefixSum[j + k];
            }
        }

        // Phase 4: Find and output the maximum score
        int maxScore = 0;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                maxScore = Math.max(maxScore, windowScore[i][j]);
            }
        }
        out.println(maxScore);
    }

    /**
     * High-performance scanner for competitive programming / fast I/O.
     */
    private static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner(InputStream in) {
            this.br = new BufferedReader(new InputStreamReader(in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) {
                        throw new NoSuchElementException("End of input reached");
                    }
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input stream", e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        long nextLong() {
            return Long.parseLong(next());
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

public class Main {

    public static void main(String[] args) throws IOException {
        // Initialize fast I/O
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter out = new PrintWriter(System.out);

        // Read dimensions n and k
        String line = br.readLine();
        if (line == null) {
            out.flush();
            return;
        }
        StringTokenizer st = new StringTokenizer(line);
        int n = Integer.parseInt(st.nextToken());
        int k = Integer.parseInt(st.nextToken());

        // Read the n x n grid
        int[][] grid = new int[n][n];
        for (int i = 0; i < n; i++) {
            String rowStr = br.readLine();
            while (rowStr != null && rowStr.trim().isEmpty()) {
                rowStr = br.readLine(); // Skip empty lines if any
            }
            if (rowStr == null) break;
            rowStr = rowStr.trim();
            for (int j = 0; j < n && j < rowStr.length(); j++) {
                grid[i][j] = (rowStr.charAt(j) == 'B') ? 1 : 0;
            }
        }

        // Compute 2D prefix sums (1-based indexing for convenience)
        int[][] prefixSum = new int[n + 1][n + 1];
        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= n; j++) {
                prefixSum[i][j] = prefixSum[i - 1][j] + prefixSum[i][j - 1] -
                                  prefixSum[i - 1][j - 1] + grid[i - 1][j - 1];
            }
        }

        // Count full rows and columns that contain no 'B's (sum == 0)
        int fullLinesCount = 0;
        for (int i = 1; i <= n; i++) {
            if (query(prefixSum, 1, i, n, i) == 0) fullLinesCount++;
            if (query(prefixSum, i, 1, i, n) == 0) fullLinesCount++;
        }

        // Identify valid k-length segments that match full row/column sums
        int[][] rowCount = new int[n + 1][n + 1];
        int[][] colCount = new int[n + 1][n + 1];

        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= n; j++) {
                int fullColSum = query(prefixSum, 1, j, n, j);
                if (fullColSum != 0 && query(prefixSum, i, j, Math.min(i + k - 1, n), j) == fullColSum) {
                    colCount[i][j] = 1;
                }

                int fullRowSum = query(prefixSum, i, 1, i, n);
                if (fullRowSum != 0 && query(prefixSum, i, j, i, Math.min(j + k - 1, n)) == fullRowSum) {
                    rowCount[i][j] = 1;
                }
            }
        }

        // Compute prefix sums for rowCount and colCount arrays
        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= n; j++) {
                rowCount[i][j] += rowCount[i - 1][j];
                colCount[i][j] += colCount[i][j - 1];
            }
        }

        // Calculate maximum intersection of valid row and column segments within any k x k window
        int maxWindowIntersection = 0;
        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= n; j++) {
                int r2 = Math.min(i + k - 1, n);
                int c2 = Math.min(j + k - 1, n);
                int currentIntersection = (rowCount[r2][j] - rowCount[i - 1][j]) +
                                          (colCount[i][c2] - colCount[i][j - 1]);
                if (currentIntersection > maxWindowIntersection) {
                    maxWindowIntersection = currentIntersection;
                }
            }
        }

        out.println(fullLinesCount + maxWindowIntersection);
        out.flush();
    }

    /**
     * Returns the sum of elements in the submatrix from (r1, c1) to (r2, c2) inclusive.
     * Uses 1-based indexing consistent with the prefixSum array.
     */
    private static int query(int[][] prefixSum, int r1, int c1, int r2, int c2) {
        return prefixSum[r2][c2] - prefixSum[r1 - 1][c2] - prefixSum[r2][c1 - 1] + prefixSum[r1 - 1][c1 - 1];
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

/**
 * Refactored solution for cf1200d.
 * 
 * Algorithm Overview:
 * 1. Reads an n x n grid and tracks the first/last occurrence of 'B' for each row and column.
 * 2. Adjusts these bounds: if a segment is shorter than k, it shifts to the rightmost valid position;
 *    if empty, it increments a counter; if long enough, it marks the start as invalid (n).
 * 3. Uses a 2D sliding window of size k x k to count intersections with row/column bounds.
 * 4. Outputs the maximum intersections plus the count of empty/uncovered segments.
 */
public class cf1200d {

    public static void main(String[] args) throws IOException {
        FastScanner scanner = new FastScanner();
        int n = scanner.nextInt();
        int k = scanner.nextInt();

        int[][] rowBounds = new int[n][2];
        int[][] colBounds = new int[n][2];

        // Phase 1: Initialize bounds with a sentinel value
        initializeBounds(rowBounds, colBounds, n);

        // Phase 2: Parse grid and compute first/last 'B' positions
        readGridAndComputeBounds(scanner, rowBounds, colBounds, n);

        // Phase 3: Adjust bounds and count empty segments
        int emptySegmentsCount = adjustAndCountEmptySegments(rowBounds, colBounds, n, k);

        // Phase 4: Calculate maximum intersections using sliding window
        int maxIntersections = calculateMaxIntersections(rowBounds, colBounds, n, k);

        // Output result
        System.out.println(maxIntersections + emptySegmentsCount);
    }

    private static void initializeBounds(int[][] rowBounds, int[][] colBounds, int n) {
        for (int i = 0; i < n; i++) {
            rowBounds[i][0] = rowBounds[i][1] = colBounds[i][0] = colBounds[i][1] = -n;
        }
    }

    private static void readGridAndComputeBounds(FastScanner scanner, int[][] rowBounds, int[][] colBounds, int n) throws IOException {
        for (int i = 0; i < n; i++) {
            String line = scanner.next();
            for (int j = 0; j < n; j++) {
                if (line.charAt(j) == 'B') {
                    if (rowBounds[i][0] == -n) {
                        rowBounds[i][0] = j;
                    }
                    rowBounds[i][1] = j;

                    if (colBounds[j][0] == -n) {
                        colBounds[j][0] = i;
                    }
                    colBounds[j][1] = i;
                }
            }
        }
    }

    private static int adjustAndCountEmptySegments(int[][] rowBounds, int[][] colBounds, int n, int k) {
        int count = 0;
        for (int i = 0; i < n; i++) {
            count += processSegmentBounds(rowBounds[i], n, k);
            count += processSegmentBounds(colBounds[i], n, k);
        }
        return count;
    }

    /**
     * Adjusts segment bounds according to problem rules and returns 1 if the segment was empty.
     */
    private static int processSegmentBounds(int[] bounds, int n, int k) {
        if (bounds[0] == -n) {
            return 1; // Empty segment
        } else if (bounds[1] - bounds[0] < k) {
            // Segment too short: shift window to the rightmost valid position
            int originalStart = bounds[0];
            bounds[0] = Math.max(0, bounds[1] - k + 1);
            bounds[1] = originalStart;
        } else {
            bounds[0] = n; // Mark as invalid for intersection counting
        }
        return 0;
    }

    private static boolean isInRange(int index, int[] range) {
        return range[0] <= index && index <= range[1];
    }

    private static int calculateMaxIntersections(int[][] rowBounds, int[][] colBounds, int n, int k) {
        int size = n - k + 1;
        int[][] intersectionCounts = new int[size][size];

        for (int i = 0; i < size; i++) {
            int currentRowIntersections = 0;
            int currentColIntersections = 0;

            // Initialize first window column
            for (int j = 0; j < k; j++) {
                currentRowIntersections += isInRange(i, colBounds[j]) ? 1 : 0;
                currentColIntersections += isInRange(i, rowBounds[j]) ? 1 : 0;
            }

            intersectionCounts[i][0] += currentRowIntersections;
            intersectionCounts[0][i] += currentColIntersections;

            // Slide window across columns
            for (int j = 0; j < size - 1; j++) {
                currentRowIntersections += isInRange(i, colBounds[j + k]) ? 1 : 0;
                currentRowIntersections -= isInRange(i, colBounds[j]) ? 1 : 0;

                currentColIntersections += isInRange(i, rowBounds[j + k]) ? 1 : 0;
                currentColIntersections -= isInRange(i, rowBounds[j]) ? 1 : 0;

                intersectionCounts[i][j + 1] += currentRowIntersections;
                intersectionCounts[j + 1][i] += currentColIntersections;
            }
        }

        int max = 0;
        for (int i = 0; i < size; i++) {
            for (int j = 0; j < size; j++) {
                if (intersectionCounts[i][j] > max) {
                    max = intersectionCounts[i][j];
                }
            }
        }
        return max;
    }

    /**
     * Lightweight, production-ready FastScanner for competitive programming / fast I/O.
     */
    private static class FastScanner {
        private final BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        private StringTokenizer tokenizer;

        public String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                String line = reader.readLine();
                if (line == null) throw new IOException("End of input");
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}

import java.util.Scanner;

public class WhiteLines {

    public static void main(String[] args) {
        // Use try-with-resources to ensure the Scanner is properly closed
        try (Scanner scan = new Scanner(System.in)) {
            if (!scan.hasNextInt()) return;

            int n = scan.nextInt();
            // The input k represents the size of the square window.
            // The logic uses k-1 as an index offset for the window size (k+1).
            int kInput = scan.nextInt();
            int kOffset = kInput - 1;

            int[][] grid = new int[n][n];
            for (int i = 0; i < n; i++) {
                String row = scan.next();
                for (int j = 0; j < n; j++) {
                    // Store 1 for Black ('B'), 0 for White ('.')
                    if (row.charAt(j) == 'B') {
                        grid[i][j] = 1;
                    }
                }
            }

            // Compute 2D prefix sums for the grid to allow O(1) sum queries
            computePrefixSums(grid, n);

            // Matrices to store if a segment of length (k+1) covers all black pixels in that line
            int[][] rowSegments = new int[n][n];
            int[][] colSegments = new int[n][n];

            // Count of lines (rows/cols) that are completely white (0 black pixels)
            int fullyWhiteLinesCount = 0;

            // Process Rows
            for (int i = 0; i < n; i++) {
                // Calculate total black pixels in the entire row
                int rowTotal = getSubgridSum(grid, i, 0, i, n - 1);

                // If the row has no black pixels, it's a "perfect" white line
                if (rowTotal == 0) {
                    fullyWhiteLinesCount++;
                } else {
                    // Check segments of length (k+1) starting at each column j
                    // We only check segments if the row actually has black pixels
                    for (int j = 0; j < n; j++) {
                        if (j + kOffset < n) {
                            // Check if the segment [j, j+kOffset] contains all black pixels of the row
                            int segmentSum = getSubgridSum(grid, i, j, i, j + kOffset);
                            if (segmentSum == rowTotal) {
                                rowSegments[i][j] = 1;
                            }
                        }
                    }
                }
            }

            // Process Columns
            for (int j = 0; j < n; j++) {
                // Calculate total black pixels in the entire column
                int colTotal = getSubgridSum(grid, 0, j, n - 1, j);

                // If the column has no black pixels, it's a "perfect" white line
                if (colTotal == 0) {
                    fullyWhiteLinesCount++;
                } else {
                    // Check segments of length (k+1) starting at each row i
                    for (int i = 0; i < n; i++) {
                        if (i + kOffset < n) {
                            // Check if the segment [i, i+kOffset] contains all black pixels of the column
                            int segmentSum = getSubgridSum(grid, i, j, i + kOffset, j);
                            if (segmentSum == colTotal) {
                                colSegments[i][j] = 1;
                            }
                        }
                    }
                }
            }

            // Compute prefix sums for the segment matrices to quickly count valid segments in a window
            computePrefixSums(rowSegments, n);
            computePrefixSums(colSegments, n);

            int maxLines = 0;
            // Iterate over all possible top-left corners (i, j) of the (k+1)x(k+1) window
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < n; j++) {
                    // Check if the window fits within the grid
                    if (i + kOffset < n && j + kOffset < n) {
                        // Count horizontal segments in the window.
                        // The logic sums rowSegments in a vertical strip at column j 
                        // spanning the window height [i, i+kOffset].
                        int hSegments = getSubgridSum(rowSegments, i, j, i + kOffset, j);

                        // Count vertical segments in the window.
                        // The logic sums colSegments in a horizontal strip at row i 
                        // spanning the window width [j, j+kOffset].
                        int vSegments = getSubgridSum(colSegments, i, j, i, j + kOffset);

                        int currentLines = hSegments + vSegments + fullyWhiteLinesCount;
                        if (currentLines > maxLines) {
                            maxLines = currentLines;
                        }
                    }
                }
            }

            System.out.println(maxLines);
        }
    }

    /**
     * Computes the 2D prefix sum of the matrix in-place.
     * After this, matrix[r][c] contains the sum of the rectangle from (0,0) to (r,c).
     */
    public static void computePrefixSums(int[][] matrix, int n) {
        // Accumulate horizontally
        for (int i = 0; i < n; i++) {
            for (int j = 1; j < n; j++) {
                matrix[i][j] += matrix[i][j - 1];
            }
        }
        // Accumulate vertically
        for (int j = 0; j < n; j++) {
            for (int i = 1; i < n; i++) {
                matrix[i][j] += matrix[i - 1][j];
            }
        }
    }

    /**
     * Retrieves the sum of a subgrid defined by top-left (r1, c1) and bottom-right (r2, c2).
     * Assumes the matrix has been processed by computePrefixSums.
     */
    public static int getSubgridSum(int[][] matrix, int r1, int c1, int r2, int c2) {
        int res = matrix[r2][c2];
        if (r1 > 0) res -= matrix[r1 - 1][c2];
        if (c1 > 0) res -= matrix[r2][c1 - 1];
        if (r1 > 0 && c1 > 0) res += matrix[r1 - 1][c1 - 1];
        return res;
    }
}

import java.io.IOException;
import java.io.InputStream;
import java.io.OutputStream;
import java.io.PrintWriter;
import java.util.InputMismatchException;

public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);

        TaskD solver = new TaskD();
        solver.solve(in, out);

        out.close();
    }

    /**
     * Solves the repainting problem.
     * Counts initial white lines, then evaluates all possible k x k repaint positions
     * to find the maximum achievable white lines.
     */
    static class TaskD {
        public void solve(InputReader in, PrintWriter out) {
            int n = in.readInt();
            int k = in.readInt();
            char[][] grid = in.readTable(n, n);

            // Convert grid: 'W' -> 0, anything else -> 1
            int[][] matrix = new int[n][n];
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < n; j++) {
                    matrix[i][j] = grid[i][j] == 'W' ? 0 : 1;
                }
            }

            // Count rows and columns that are already completely white
            int initialWhiteLines = countInitialWhiteLines(matrix, n);

            // Precompute how many lines become white when repainting a k x k square
            Repainter rowRepainter = new Repainter(k, matrix, false);
            Repainter colRepainter = new Repainter(k, matrix, true);

            int maxWhiteLines = initialWhiteLines;
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < n; j++) {
                    int gainRows = rowRepainter.getGainIfRepaintFrom(i, j);
                    int gainCols = colRepainter.getGainIfRepaintFrom(i, j);
                    maxWhiteLines = Math.max(maxWhiteLines, initialWhiteLines + gainRows + gainCols);
                }
            }
            out.println(maxWhiteLines);
        }

        /**
         * Counts how many rows and columns consist entirely of white cells (0).
         */
        private int countInitialWhiteLines(int[][] matrix, int n) {
            int count = 0;

            // Check rows
            for (int i = 0; i < n; i++) {
                boolean allWhite = true;
                for (int val : matrix[i]) {
                    if (val != 0) {
                        allWhite = false;
                        break;
                    }
                }
                if (allWhite) count++;
            }

            // Check columns
            for (int j = 0; j < n; j++) {
                boolean allWhite = true;
                for (int i = 0; i < n; i++) {
                    if (matrix[i][j] != 0) {
                        allWhite = false;
                        break;
                    }
                }
                if (allWhite) count++;
            }

            return count;
        }
    }

    /**
     * Precomputes the gain in white lines for each possible top-left position
     * of a k x k repaint square. Uses prefix/suffix sums and sliding windows
     * to achieve O(n^2) precomputation.
     */
    static class Repainter {
        private final int[][] gainTable;

        public Repainter(int k, int[][] matrix, boolean isColumns) {
            int n = matrix.length;
            // Transpose if processing columns so we can reuse row-wise logic
            int[][] workingMatrix = isColumns ? transpose(matrix) : matrix;
            int[][] rowGains = computeRowRepaintGains(k, workingMatrix);
            // Transpose back to restore original orientation
            this.gainTable = isColumns ? transpose(rowGains) : rowGains;
        }

        private int[][] transpose(int[][] matrix) {
            int n = matrix.length;
            int[][] transposed = new int[n][n];
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < n; j++) {
                    transposed[i][j] = matrix[j][i];
                }
            }
            return transposed;
        }

        private int[][] computeRowRepaintGains(int k, int[][] matrix) {
            int n = matrix.length;
            int[][] gainTable = new int[n][n];

            // Phase 1: Determine if repainting a segment of length k makes each row all-white
            int[][] rowMakesWhite = new int[n][n];
            for (int i = 0; i < n; i++) {
                int[] row = matrix[i];
                int[] pref = new int[n + 1];
                int[] suf = new int[n + 1];

                for (int j = 0; j < n; j++) {
                    pref[j + 1] = pref[j] + row[j];
                    suf[n - 1 - j] = suf[n - j] + row[n - 1 - j];
                }

                for (int j = 0; j <= n - k; j++) {
                    // Repainting [j, j+k) makes the row all white if the rest is already white
                    if (pref[j] == 0 && suf[j + k] == 0) {
                        rowMakesWhite[i][j] = 1;
                    }
                }
            }

            // Phase 2: For each column index j, compute sliding window sum over rowMakesWhite
            // gainTable[i][j] = number of rows that become all-white if the repaint square's
            // top-left row is i. This is equivalent to summing rowMakesWhite[r][j] for r in [i, i+k).
            for (int j = 0; j < n; j++) {
                int currentSum = 0;
                for (int i = 0; i < n; i++) {
                    currentSum += rowMakesWhite[i][j];
                    if (i >= k) {
                        currentSum -= rowMakesWhite[i - k][j];
                    }
                    if (i >= k - 1) {
                        gainTable[i - k + 1][j] = currentSum;
                    }
                }
            }

            return gainTable;
        }

        /**
         * Returns the number of additional white lines gained by repainting a k x k square
         * with its top-left corner at (row, col).
         */
        public int getGainIfRepaintFrom(int row, int col) {
            return gainTable[row][col];
        }
    }

    /**
     * Fast input reader for competitive programming environments.
     */
    static class InputReader {
        private final InputStream stream;
        private final byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;
        private SpaceCharFilter filter;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        public char[] readCharArray(int size) {
            char[] array = new char[size];
            for (int i = 0; i < size; i++) {
                array[i] = readCharacter();
            }
            return array;
        }

        public char[][] readTable(int rowCount, int columnCount) {
            char[][] table = new char[rowCount][];
            for (int i = 0; i < rowCount; i++) {
                table[i] = this.readCharArray(columnCount);
            }
            return table;
        }

        public int read() {
            if (numChars == -1) {
                throw new InputMismatchException();
            }
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0) {
                    return -1;
                }
            }
            return buf[curChar++];
        }

        public int readInt() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                res *= 10;
                res += c - '0';
                c = read();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public boolean isSpaceChar(int c) {
            return filter != null ? filter.isSpaceChar(c) : isWhitespace(c);
        }

        public static boolean isWhitespace(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        public char readCharacter() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            return (char) c;
        }

        @FunctionalInterface
        public interface SpaceCharFilter {
            boolean isSpaceChar(int ch);
        }
    }
}

import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) {
        FastScanner scanner = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out);
        try {
            GridSolver solver = new GridSolver(scanner, out);
            solver.run();
        } catch (IOException e) {
            e.printStackTrace();
        } finally {
            out.flush();
            out.close();
        }
    }

    /**
     * Encapsulates the core problem logic, removing static globals and improving maintainability.
     */
    private static class GridSolver {
        private static final int INF = 1_000_000_000;
        private final int n;
        private final int k;
        private final int[][] grid;
        private final int[] rowFirst;
        private final int[] rowLast;
        private final int[] colFirst;
        private final int[] colLast;
        private final int minPenalty;
        private final PrintWriter out;

        public GridSolver(FastScanner scanner, PrintWriter out) throws IOException {
            this.out = out;
            this.n = scanner.nextInt();
            this.k = scanner.nextInt();
            this.grid = new int[n][n];
            this.rowFirst = new int[n];
            this.rowLast = new int[n];
            this.colFirst = new int[n];
            this.colLast = new int[n];
            Arrays.fill(rowFirst, INF);
            Arrays.fill(rowLast, INF);
            Arrays.fill(colFirst, INF);
            Arrays.fill(colLast, INF);

            readAndProcessGrid(scanner);
            this.minPenalty = computeMinPenalty();
        }

        private void readAndProcessGrid(FastScanner scanner) throws IOException {
            for (int i = 0; i < n; i++) {
                String line = scanner.next();
                for (int j = 0; j < n; j++) {
                    if (line.charAt(j) != 'W') {
                        grid[i][j] = 1;
                        // Track first and last occurrence of '1' in each row and column
                        rowFirst[i] = Math.min(rowFirst[i], j);
                        rowLast[i] = Math.max(rowLast[i], j);
                        colFirst[j] = Math.min(colFirst[j], i);
                        colLast[j] = Math.max(colLast[j], i);
                    }
                }
            }
        }

        private int computeMinPenalty() {
            int penalty = 0;
            for (int i = 0; i < n; i++) {
                if (rowFirst[i] == INF) penalty++;
                if (colFirst[i] == INF) penalty++;
            }
            return penalty;
        }

        public void run() throws IOException {
            out.println(findMaxAnswer());
        }

        private int findMaxAnswer() {
            int maxResult = 0;
            // Slide a window of height k over the grid
            for (int windowRowStart = 0; windowRowStart + k <= n; windowRowStart++) {
                SegmentTree tree = new SegmentTree(n);
                int[] colPenalty = new int[n];
                int currentWindowSum = 0;

                // Identify columns that have NO '1's within the current row window
                for (int j = 0; j < n; j++) {
                    if (colFirst[j] >= windowRowStart && colLast[j] < windowRowStart + k) {
                        colPenalty[j] = 1;
                    }
                }

                // Compute sliding window sums of column penalties
                for (int j = 0; j < k; j++) {
                    currentWindowSum += colPenalty[j];
                }
                tree.update(0, 0, currentWindowSum);

                for (int j = k; j < n; j++) {
                    currentWindowSum += colPenalty[j] - colPenalty[j - k];
                    tree.update(j - k + 1, j - k + 1, currentWindowSum);
                }

                // Apply row constraints: if a row's span fits within k, add 1 to valid column ranges
                for (int j = windowRowStart; j < windowRowStart + k; j++) {
                    if (rowLast[j] - rowFirst[j] <= k) {
                        tree.update(rowLast[j] - k + 1, rowFirst[j], 1);
                    }
                }

                maxResult = Math.max(maxResult, minPenalty + tree.getMax());
            }
            return maxResult;
        }
    }

    /**
     * Standard Lazy Propagation Segment Tree supporting range updates and max queries.
     */
    private static class SegmentTree {
        private final int n;
        private final int[] max;
        private final int[] lazy;

        public SegmentTree(int n) {
            this.n = n;
            this.max = new int[4 * n];
            this.lazy = new int[4 * n];
        }

        private void push(int node) {
            if (lazy[node] != 0) {
                int left = 2 * node + 1;
                int right = 2 * node + 2;
                lazy[left] += lazy[node];
                max[left] += lazy[node];
                lazy[right] += lazy[node];
                max[right] += lazy[node];
                lazy[node] = 0;
            }
        }

        public void update(int l, int r, int val) {
            update(0, 0, n - 1, l, r, val);
        }

        private void update(int node, int start, int end, int l, int r, int val) {
            if (l > end || r < start) return;
            if (l <= start && end <= r) {
                max[node] += val;
                lazy[node] += val;
                return;
            }
            push(node);
            int mid = (start + end) / 2;
            update(2 * node + 1, start, mid, l, r, val);
            update(2 * node + 2, mid + 1, end, l, r, val);
            max[node] = Math.max(max[2 * node + 1], max[2 * node + 2]);
        }

        public int getMax() {
            return max[0];
        }
    }

    /**
     * Fast I/O helper for competitive programming style inputs.
     */
    private static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
            st = new StringTokenizer("");
        }

        public String next() throws IOException {
            while (!st.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) return null;
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        public long nextLong() throws IOException {
            return Long.parseLong(next());
        }
    }
}

