    }

    /**
     * Solves the problem by finding two k x k squares that maximize the number of 'B's covered.
     * Uses row/column bounds and sliding window DP to efficiently compute coverage.
     */
    static class Task {
        public void solve(InputReader in, PrintWriter out) {
            int n = in.nextInt();
            int k = in.nextInt();

            // Bounds for 'B' characters in each row and column
            int[] rowMin = new int[n];
            int[] rowMax = new int[n];
            int[] colMin = new int[n];
            int[] colMax = new int[n];

            // Initialize bounds: rows/cols with no 'B' will remain at these sentinel values
            Arrays.fill(rowMin, Integer.MAX_VALUE);
            Arrays.fill(rowMax, -1);
            Arrays.fill(colMin, Integer.MAX_VALUE);
            Arrays.fill(colMax, -1);

            // Read grid and populate bounds
            char[][] grid = new char[n][n];
            for (int i = 0; i < n; i++) {
                String line = in.next();
                grid[i] = line.toCharArray();
                for (int j = 0; j < n; j++) {
                    if (grid[i][j] == 'B') {
                        rowMin[i] = Math.min(rowMin[i], j);
                        rowMax[i] = Math.max(rowMax[i], j);
                        colMin[j] = Math.min(colMin[j], i);
                        colMax[j] = Math.max(colMax[j], i);
                    }
                }
            }

            // Count completely empty rows and columns
            int emptyCount = 0;
            for (int i = 0; i < n; i++) {
                if (rowMin[i] == Integer.MAX_VALUE) {
                    emptyCount++;
                    rowMin[i] = -1;
                    rowMax[i] = n; // Ensure they don't match the DP condition
                }
                if (colMin[i] == Integer.MAX_VALUE) {
                    emptyCount++;
                    colMin[i] = -1;
                    colMax[i] = n;
                }
            }

            int limit = n - k + 1;
            int[][] rowCoverage = new int[n + 1][n + 1];
            int[][] colCoverage = new int[n + 1][n + 1];

            // DP1: Compute how many rows in a vertical window [i, i+k-1] 
            // are fully contained within a horizontal window [j, j+k-1]
            for (int j = 0; j < limit; j++) {
                int count = 0;
                for (int i = 0; i < k; i++) {
                    if (rowMin[i] >= j && rowMax[i] <= j + k - 1) {
                        count++;
                    }
                }
                rowCoverage[0][j] = count;
            }

            // Slide the vertical window down
            for (int i = 1; i < limit; i++) {
                for (int j = 0; j < limit; j++) {
                    int diff = 0;
                    if (rowMin[i - 1] >= j && rowMax[i - 1] <= j + k - 1) diff--;
                    if (rowMin[i + k - 1] >= j && rowMax[i + k - 1] <= j + k - 1) diff++;
                    rowCoverage[i][j] = rowCoverage[i - 1][j] + diff;
                }
            }

            // DP2: Compute how many columns in a horizontal window [j, j+k-1]
            // are fully contained within a vertical window [i, i+k-1]
            for (int i = 0; i < limit; i++) {
                int count = 0;
                for (int j = 0; j < k; j++) {
                    if (colMin[j] >= i && colMax[j] <= i + k - 1) {
                        count++;
                    }
                }
                colCoverage[i][0] = count;
            }

            // Slide the horizontal window right
            for (int i = 0; i < limit; i++) {
                for (int j = 1; j < limit; j++) {
                    int diff = 0;
                    if (colMin[j - 1] >= i && colMax[j - 1] <= i + k - 1) diff--;
                    if (colMin[j + k - 1] >= i && colMax[j + k - 1] <= i + k - 1) diff++;
                    colCoverage[i][j] = colCoverage[i][j - 1] + diff;
                }
            }

            // Find the maximum combined coverage
            int maxCoverage = 0;
            for (int i = 0; i < limit; i++) {
                for (int j = 0; j < limit; j++) {
                    maxCoverage = Math.max(maxCoverage, rowCoverage[i][j] + colCoverage[i][j]);
                }
            }

            out.println(maxCoverage + emptyCount);
        }
    }

    /**
     * Fast input reader optimized for competitive programming.
     */
    static class InputReader {
        public BufferedReader reader;
        public StringTokenizer tokenizer;

        public InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }
    }
}

import java.io.*;
import java.util.StringTokenizer;

public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);

        WhiteLinesSolver solver = new WhiteLinesSolver();
        solver.solve(in, out);

        out.close();
    }

    /**
     * Encapsulates the solution logic for the White Lines problem.
     * Breaks down the problem into focused, testable, and maintainable methods.
     */
    static class WhiteLinesSolver {
        public void solve(InputReader in, PrintWriter out) {
            int n = in.nextInt();
            int k = in.nextInt();
            boolean[][] grid = readGrid(in, n);

            int validStarts = n - k + 1;

            // Compute vertical window scores for the original grid
            int[][] verticalScores = computeSlidingWindowScores(grid, k, validStarts);

            // Compute horizontal window scores by transposing the grid and reusing logic
            boolean[][] transposedGrid = transpose(grid);
            int[][] horizontalScores = computeSlidingWindowScores(transposedGrid, k, validStarts);

            // Find the maximum combined score across all valid k x k positions
            int maxScore = calculateMaxCombinedScore(verticalScores, horizontalScores, validStarts);

            // Add counts for completely empty rows and columns
            int emptyLines = countEmptyLines(grid, n);

            out.println(maxScore + emptyLines);
        }

        /** Reads the n x n grid from input. */
        private boolean[][] readGrid(InputReader in, int n) {
            boolean[][] grid = new boolean[n][n];
            for (int i = 0; i < n; i++) {
                String row = in.next();
                for (int j = 0; j < n; j++) {
                    grid[i][j] = row.charAt(j) == 'B';
                }
            }
            return grid;
        }

        /** Transposes a square boolean grid in-place logic. */
        private boolean[][] transpose(boolean[][] grid) {
            int n = grid.length;
            boolean[][] transposed = new boolean[n][n];
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < n; j++) {
                    transposed[i][j] = grid[j][i];
                }
            }
            return transposed;
        }

        /**
         * Computes a 2D score matrix where score[i][j] represents the number of rows 
         * in the vertical window [i, i+k-1] that contain at least one 'B' in the 
         * horizontal window [j, j+k-1].
         */
        private int[][] computeSlidingWindowScores(boolean[][] grid, int k, int validStarts) {
            boolean[][] rowCovered = new boolean[grid.length][validStarts];

            // Determine which horizontal windows cover each row's black cells
            for (int i = 0; i < grid.length; i++) {
                int minCol = Integer.MAX_VALUE;
                int maxCol = Integer.MIN_VALUE;
                for (int j = 0; j < grid.length; j++) {
                    if (grid[i][j]) {
                        minCol = Math.min(minCol, j);
                        maxCol = Math.max(maxCol, j);
                    }
                }

                for (int j = 0; j < validStarts; j++) {
                    if (minCol != Integer.MAX_VALUE && j <= minCol && maxCol <= j + k - 1) {
                        rowCovered[i][j] = true;
                    }
                }
            }

            // Use prefix sums to count covered rows in each vertical window
            int[][] score = new int[validStarts][validStarts];
            for (int j = 0; j < validStarts; j++) {
                int[] prefixSum = new int[grid.length + 1];
                for (int i = 0; i < grid.length; i++) {
                    prefixSum[i + 1] = prefixSum[i] + (rowCovered[i][j] ? 1 : 0);
                }
                for (int i = 0; i < validStarts; i++) {
                    score[i][j] = prefixSum[i + k] - prefixSum[i];
                }
            }
            return score;
        }

        /** Calculates the maximum sum of vertical and horizontal scores for aligned windows. */
        private int calculateMaxCombinedScore(int[][] verticalScores, int[][] horizontalScores, int validStarts) {
            int maxScore = 0;
            for (int i = 0; i < validStarts; i++) {
                for (int j = 0; j < validStarts; j++) {
                    int combined = verticalScores[i][j] + horizontalScores[j][i];
                    if (combined > maxScore) {
                        maxScore = combined;
                    }
                }
            }
            return maxScore;
        }

        /** Counts the number of rows and columns that contain zero 'B' cells. */
        private int countEmptyLines(boolean[][] grid, int n) {
            boolean[] hasBlackRow = new boolean[n];
            boolean[] hasBlackCol = new boolean[n];

            for (int i = 0; i < n; i++) {
                for (int j = 0; j < n; j++) {
                    if (grid[i][j]) {
                        hasBlackRow[i] = true;
                        hasBlackCol[j] = true;
                    }
                }
            }

            int emptyLines = 0;
            for (boolean hasBlack : hasBlackRow) {
                if (!hasBlack) emptyLines++;
            }
            for (boolean hasBlack : hasBlackCol) {
                if (!hasBlack) emptyLines++;
            }
            return emptyLines;
        }
    }

    /**
     * Efficient input reader for competitive programming environments.
     */
    static class InputReader {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Input reading failed", e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            String token = next();
            return token == null ? 0 : Integer.parseInt(token);
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.util.Arrays;
import java.util.StringTokenizer;

/**
 * Analyzes a grid of characters to find the maximum overlap of k-length 
 * windows covering 'B' characters across rows and columns.
 */
public class GridBCharacterAnalyzer {

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner(System.in);

        // Read dimensions and window size
        int n = scanner.nextInt();
        int k = scanner.nextInt();

        // Read grid
        char[][] grid = new char[n][];
        for (int i = 0; i < n; i++) {
            grid[i] = scanner.next().toCharArray();
        }

        // Initialize bounds for 'B' characters
        int[] minRowForCol = new int[n];
        int[] maxRowForCol = new int[n];
        int[] minColForRow = new int[n];
        int[] maxColForRow = new int[n];

        Arrays.fill(minRowForCol, Integer.MAX_VALUE);
        Arrays.fill(maxRowForCol, -1);
        Arrays.fill(minColForRow, Integer.MAX_VALUE);
        Arrays.fill(maxColForRow, -1);

        // Determine bounding box of 'B's for each row and column
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < n; c++) {
                if (grid[r][c] == 'B') {
                    minRowForCol[c] = Math.min(minRowForCol[c], r);
                    maxRowForCol[c] = Math.max(maxRowForCol[c], r);
                    minColForRow[r] = Math.min(minColForRow[r], c);
                    maxColForRow[r] = Math.max(maxColForRow[r], c);
                }
            }
        }

        int emptyCount = 0;
        int[][] rowWindows = new int[n][n + 2];
        int[][] colWindows = new int[n][n + 2];

        // Process each row and column
        for (int i = 0; i < n; i++) {
            // Count completely empty rows and columns
            if (maxRowForCol[i] == -1) emptyCount++;
            if (maxColForRow[i] == -1) emptyCount++;

            // If column i contains 'B's and fits within window size k
            if (maxRowForCol[i] != -1 && (maxRowForCol[i] - minRowForCol[i] + 1) <= k) {
                int span = maxRowForCol[i] - minRowForCol[i] + 1;
                int slack = k - span;
                int minStart = Math.max(0, minRowForCol[i] - slack);
                int maxStart = minRowForCol[i];

                // Apply difference array for valid vertical start positions
                // Only consider rows j that can vertically align with column i within distance k
                for (int j = i; j >= 0 && j > i - k; j--) {
                    colWindows[j][minStart]++;
                    colWindows[j][maxStart + 1]--;
                }
            }

            // If row i contains 'B's and fits within window size k
            if (maxColForRow[i] != -1 && (maxColForRow[i] - minColForRow[i] + 1) <= k) {
                int span = maxColForRow[i] - minColForRow[i] + 1;
                int slack = k - span;
                int minStart = Math.max(0, minColForRow[i] - slack);
                int maxStart = minColForRow[i];

                // Apply difference array for valid horizontal start positions
                for (int j = i; j >= 0 && j > i - k; j--) {
                    rowWindows[j][minStart]++;
                    rowWindows[j][maxStart + 1]--;
                }
            }
        }

        // Compute prefix sums to get actual window counts
        for (int i = 0; i < n; i++) {
            for (int j = 1; j < n + 2; j++) {
                rowWindows[i][j] += rowWindows[i][j - 1];
                colWindows[i][j] += colWindows[i][j - 1];
            }
        }

        // Find maximum combined overlap across all possible top-left positions
        long maxOverlap = 0;
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < n; c++) {
                long currentOverlap = rowWindows[r][c] + colWindows[c][r];
                if (currentOverlap > maxOverlap) {
                    maxOverlap = currentOverlap;
                }
            }
        }

        // Output result: max overlap + count of empty rows/columns
        System.out.println(maxOverlap + emptyCount);
    }

    /**
     * Fast input reader for competitive programming and performance-critical applications.
     */
    static class FastScanner {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastScanner(InputStream stream) {
            this.reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input stream", e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            String token = next();
            return token == null ? 0 : Integer.parseInt(token);
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

/**
 * Refactored version of the original competitive programming solution.
 * 
 * Refactoring Improvements:
 * 1. Descriptive Naming: Replaced single-letter variables and cryptic abbreviations 
 *    (e.g., prefr, sufC, cntr) with meaningful names (rowPrefix, colSuffix, rowCount).
 * 2. Separation of Concerns: Isolated I/O handling from business logic.
 * 3. Standard I/O: Replaced custom byte-based fast I/O with standard BufferedReader/StringTokenizer 
 *    for better maintainability and readability without significant performance trade-offs.
 * 4. Clear Indexing Strategy: Maintained 1-based indexing for prefix/suffix arrays to simplify 
 *    boundary handling, but added explicit comments explaining the mapping to 0-based grid coordinates.
 * 5. Modular Structure: Broke down the monolithic solve() method into logical sections with comments.
 * 6. Removed Dead Code: Eliminated unused variables (M, oj, tr, INPUT) and unnecessary imports.
 * 
 * Note: The core algorithmic logic has been preserved exactly as in the original to ensure 
 * compatibility with the target problem judge.
 */
public class Main {
    // I/O Streams
    private BufferedReader br;
    private StringTokenizer st;
    private PrintWriter out;

    public static void main(String[] args) {
        new Main().run();
    }

    /**
     * Entry point for execution. Initializes I/O and triggers the solver.
     */
    public void run() {
        br = new BufferedReader(new InputStreamReader(System.in));
        out = new PrintWriter(System.out);
        try {
            solve();
        } catch (IOException e) {
            throw new RuntimeException("I/O Error during execution", e);
        } finally {
            out.flush();
            out.close();
        }
    }

    /**
     * Core logic for solving the problem.
     * Uses prefix and suffix sum arrays to efficiently count valid configurations.
     */
    private void solve() throws IOException {
        int n = nextInt();
        int k = nextInt();

        char[][] grid = new char[n][];
        for (int i = 0; i < n; i++) {
            grid[i] = next().toCharArray();
        }

        // --- Prefix & Suffix Sum Arrays ---
        // Dimensions: (n+1) x (n+1) for prefix, (n+2) x (n+2) for suffix to safely handle boundary indices.
        // Indexing is 1-based for the DP arrays to align with standard prefix sum conventions.
        int[][] colPrefix = new int[n + 1][n + 1];
        int[][] colSuffix = new int[n + 2][n + 2];
        int[][] rowPrefix = new int[n + 1][n + 1];
        int[][] rowSuffix = new int[n + 2][n + 2];

        // Compute column prefix and suffix sums
        for (int j = 1; j <= n; j++) {
            for (int i = 1; i <= n; i++) {
                colPrefix[i][j] = colPrefix[i - 1][j];
                if (grid[i - 1][j - 1] == 'W') {
                    colPrefix[i][j]++;
                }
            }
            for (int i = n; i >= 1; i--) {
                colSuffix[i][j] = colSuffix[i + 1][j];
                if (grid[i - 1][j - 1] == 'W') {
                    colSuffix[i][j]++;
                }
            }
        }

        // Compute row prefix and suffix sums
        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= n; j++) {
                rowPrefix[i][j] = rowPrefix[i][j - 1];
                if (grid[i - 1][j - 1] == 'W') {
                    rowPrefix[i][j]++;
                }
            }
            for (int j = n; j >= 1; j--) {
                rowSuffix[i][j] = rowSuffix[i][j + 1];
                if (grid[i - 1][j - 1] == 'W') {
                    rowSuffix[i][j]++;
                }
            }
        }

        // --- Segment Validation Arrays ---
        // colCount[i][j] marks valid vertical segments ending at row i in column j
        // rowCount[i][j] marks valid horizontal segments ending at col j in row i
        int[][] colCount = new int[n + 1][n + 1];
        int[][] rowCount = new int[n + 1][n + 1];

        for (int j = 1; j <= n; j++) {
            for (int i = k; i <= n; i++) {
                // Preserved original logic: checks if the entire column is 'W'
                if (colPrefix[i - k][j] == i - k && colSuffix[i + 1][j] == n - i) {
                    colCount[i][j] = 1;
                }
            }
        }

        for (int i = 1; i <= n; i++) {
            for (int j = k; j <= n; j++) {
                // Preserved original logic: checks if the entire row is 'W'
                if (rowPrefix[i][j - k] == j - k && rowSuffix[i][j + 1] == n - j) {
                    rowCount[i][j] = 1;
                }
            }
        }

        // --- Prefix Sum Optimization for Count Arrays ---
        // Transform count arrays into prefix sums for O(1) range queries
        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= n; j++) {
                colCount[i][j] += colCount[i][j - 1];
            }
        }
        for (int j = 1; j <= n; j++) {
            for (int i = 1; i <= n; i++) {
                rowCount[i][j] += rowCount[i - 1][j];
            }
        }

        // --- Full Row/Column Tracking Arrays ---
        int[] fullRowPrefix = new int[n + 1];
        int[] fullRowSuffix = new int[n + 2];
        int[] fullColPrefix = new int[n + 1];
        int[] fullColSuffix = new int[n + 2];

        for (int i = 1; i <= n; i++) {
            fullRowPrefix[i] = fullRowPrefix[i - 1];
            if (rowPrefix[i][n] == n) fullRowPrefix[i]++;
        }
        for (int i = n; i >= 1; i--) {
            fullRowSuffix[i] = fullRowSuffix[i + 1];
            if (rowPrefix[i][n] == n) fullRowSuffix[i]++;
        }
        for (int j = 1; j <= n; j++) {
            fullColPrefix[j] = fullColPrefix[j - 1];
            if (colPrefix[n][j] == n) fullColPrefix[j]++;
        }
        for (int j = n; j >= 1; j--) {
            fullColSuffix[j] = fullColSuffix[j + 1];
            if (colPrefix[n][j] == n) fullColSuffix[j]++;
        }

        // --- Final Calculation ---
        int maxAnswer = fullRowPrefix[n] + fullColPrefix[n];

        // Iterate over all possible top-left corners of k x k windows
        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= n; j++) {
                int topRow = i - k + 1;
                int leftCol = j - k + 1;

                if (topRow <= 0 || leftCol <= 0) continue;

                int currentAnswer = fullRowPrefix[topRow - 1] + fullRowSuffix[i + 1]
                                  + fullColPrefix[leftCol - 1] + fullColSuffix[j + 1]
                                  + rowCount[i][j] - rowCount[topRow - 1][j]
                                  + colCount[i][j] - colCount[i][leftCol - 1];

                maxAnswer = Math.max(maxAnswer, currentAnswer);
            }
        }

        out.println(maxAnswer);
    }

    // --- Standard Fast I/O Helpers ---
    private String next() throws IOException {
        while (st == null || !st.hasMoreTokens()) {
            String line = br.readLine();
            if (line == null) return null;
            st = new StringTokenizer(line);
        }
        return st.nextToken();
    }

    private int nextInt() throws IOException {
        String token = next();
        return token == null ? 0 : Integer.parseInt(token);
    }
}

import java.io.BufferedInputStream;
import java.io.IOException;
import java.util.Scanner;

/**
 * Calculates the maximum alignment bonus for a sliding window on a grid,
 * considering vertical and horizontal full-line coverage bonuses.
 */
public class GridBonusCalculator {

    private static final int DEFAULT_BUFFER_SIZE = 1 << 19;

    public static void main(String[] args) throws IOException {
        Scanner scanner = new Scanner(new BufferedInputStream(System.in, DEFAULT_BUFFER_SIZE));

        if (!scanner.hasNextInt()) {
            return;
        }

        int n = scanner.nextInt();
        int windowSize = scanner.nextInt();
        int k = windowSize - 1;

        // Prefix sum arrays for vertical and horizontal 'B' counts
        int[][] verticalPrefixSums = new int[n][n];
        int[][] horizontalPrefixSums = new int[n][n];

        readGridAndComputePrefixSums(scanner, n, verticalPrefixSums, horizontalPrefixSums);

        // Bonus arrays: 1 if a full column/row segment matches the total, 0 otherwise
        int[][] upBonuses = new int[n][n];
        int[][] leftBonuses = new int[n][n];
        computeBonuses(n, k, verticalPrefixSums, horizontalPrefixSums, upBonuses, leftBonuses);

        // Prefix sums of bonus arrays to allow O(1) window sum queries
        int[][] upBonusPrefixSums = new int[n][n];
        int[][] leftBonusPrefixSums = new int[n][n];
        computeBonusPrefixSums(n, upBonuses, leftBonuses, upBonusPrefixSums, leftBonusPrefixSums);

        // Find the maximum bonus achievable by any (k+1)x(k+1) window
        int maxWindowBonus = findMaxWindowBonus(n, k, upBonusPrefixSums, leftBonusPrefixSums);

        // Count completely empty rows and columns
        int emptyLinesCount = countEmptyLines(n, verticalPrefixSums, horizontalPrefixSums);

        System.out.println(maxWindowBonus + emptyLinesCount);
    }

    /**
     * Reads the grid from input and computes prefix sums for vertical and horizontal 'B' counts.
     */
    private static void readGridAndComputePrefixSums(Scanner scanner, int n, int[][] v, int[][] h) {
        for (int i = 0; i < n; i++) {
            char[] row = scanner.next().toCharArray();
            for (int j = 0; j < n; j++) {
                int isBlack = (row[j] == 'B') ? 1 : 0;
                v[i][j] = (i > 0 ? v[i - 1][j] : 0) + isBlack;
                h[i][j] = (j > 0 ? h[i][j - 1] : 0) + isBlack;
            }
        }
    }

    /**
     * Computes bonus values indicating whether a segment fully covers all 'B's in its respective line.
     */
    private static void computeBonuses(int n, int k, int[][] v, int[][] h, int[][] up, int[][] left) {
        // Compute vertical bonuses
        for (int i = 0; i < n - k; i++) {
            for (int j = 0; j < n; j++) {
                int segmentSum = v[i + k][j] - (i > 0 ? v[i - 1][j] : 0);
                int totalSum = v[n - 1][j];
                // Bonus is 1 if the segment contains all 'B's of the column, 0 otherwise
                up[i][j] = (totalSum > 0 && segmentSum == totalSum) ? 1 : 0;
            }
        }

        // Compute horizontal bonuses
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n - k; j++) {
                int segmentSum = h[i][j + k] - (j > 0 ? h[i][j - 1] : 0);
                int totalSum = h[i][n - 1];
                // Bonus is 1 if the segment contains all 'B's of the row, 0 otherwise
                left[i][j] = (totalSum > 0 && segmentSum == totalSum) ? 1 : 0;
            }
        }
    }

    /**
     * Computes prefix sums over the bonus arrays to enable O(1) range sum queries.
     */
    private static void computeBonusPrefixSums(int n, int[][] up, int[][] left, int[][] upAcc, int[][] leftAcc) {
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                upAcc[i][j] = (j > 0 ? upAcc[i][j - 1] : 0) + up[i][j];
                leftAcc[i][j] = (i > 0 ? leftAcc[i - 1][j] : 0) + left[i][j];
            }
        }
    }

    /**
     * Slides a (k+1)x(k+1) window across the grid and finds the maximum combined bonus.
     */
    private static int findMaxWindowBonus(int n, int k, int[][] upAcc, int[][] leftAcc) {
        int maxBonus = 0;
        for (int i = 0; i < n - k; i++) {
            for (int j = 0; j < n - k; j++) {
                // Sum of up bonuses in the current window's columns
                int currentUpBonus = upAcc[i][j + k] - (j > 0 ? upAcc[i][j - 1] : 0);
                // Sum of left bonuses in the current window's rows
                int currentLeftBonus = leftAcc[i + k][j] - (i > 0 ? leftAcc[i - 1][j] : 0);

                maxBonus = Math.max(maxBonus, currentUpBonus + currentLeftBonus);
            }
        }
        return maxBonus;
    }

    /**
     * Counts the number of completely empty rows and columns.
     */
    private static int countEmptyLines(int n, int[][] v, int[][] h) {
        int count = 0;
        for (int i = 0; i < n; i++) {
            if (v[n - 1][i] == 0) count++; // Empty column
            if (h[i][n - 1] == 0) count++; // Empty row
        }
        return count;
    }
}

import java.io.InputStream;
import java.io.OutputStream;
import java.io.IOException;
import java.io.UncheckedIOException;
import java.io.Writer;
import java.io.OutputStreamWriter;
import java.nio.charset.StandardCharsets;

public class Main {
    private static final int BUFFER_SIZE = 1 << 20;
    private static final int OUTPUT_BUFFER_SIZE = 10 << 20;
    private static final int MAX_WHITESPACE = 32;
    private static final int DEFAULT_STACK_SIZE = 1 << 27;

    public static void main(String[] args) {
        Thread thread = new Thread(null, new TaskAdapter(), "Solver-Thread", DEFAULT_STACK_SIZE);
        thread.start();
        try {
            thread.join();
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
    }

    static class TaskAdapter implements Runnable {
        @Override
        public void run() {
            try (FastInput in = new FastInput(System.in);
                 FastOutput out = new FastOutput(System.out)) {
                new DWhiteLines().solve(in, out);
            } catch (Exception e) {
                throw new RuntimeException("Error during execution", e);
            }
        }
    }

    static class DWhiteLines {
        public void solve(FastInput in, FastOutput out) {
            int n = in.readInt();
            int k = in.readInt();
            int[][] mat = new int[n + 1][n + 1];

            for (int i = 1; i <= n; i++) {
                for (int j = 1; j <= n; j++) {
                    mat[i][j] = in.readChar() == 'B' ? 1 : 0;
                }
            }

            int[][] tags = new int[n + 1][n + 1];

            // Process each row
            for (int i = 1; i <= n; i++) {
                int minCol = n + 1;
                int maxCol = 0;
                for (int j = 1; j <= n; j++) {
                    if (mat[i][j] == 1) {
                        minCol = Math.min(minCol, j);
                        maxCol = Math.max(maxCol, j);
                    }
                }
                if (minCol > maxCol) {
                    tags[1][1]++;
                } else {
                    updateTags(tags, n, maxCol - k + 1, minCol, i - k + 1, i);
                }
            }

            // Process each column
            for (int i = 1; i <= n; i++) {
                int minRow = n + 1;
                int maxRow = 0;
                for (int j = 1; j <= n; j++) {
                    if (mat[j][i] == 1) {
                        minRow = Math.min(minRow, j);
                        maxRow = Math.max(maxRow, j);
                    }
                }
                if (minRow > maxRow) {
                    tags[1][1]++;
                } else {
                    updateTags(tags, n, i - k + 1, i, maxRow - k + 1, minRow);
                }
            }

            // Reconstruct 2D prefix sums from difference array
            for (int i = 1; i <= n; i++) {
                for (int j = 1; j <= n; j++) {
                    tags[i][j] += tags[i - 1][j] + tags[i][j - 1] - tags[i - 1][j - 1];
                }
            }

            // Find maximum value
            int ans = 0;
            for (int i = 1; i <= n; i++) {
                for (int j = 1; j <= n; j++) {
                    ans = Math.max(ans, tags[i][j]);
                }
            }

            out.println(ans);
        }

        private void updateTags(int[][] tags, int n, int l, int r, int t, int b) {
            l = Math.max(l, 1);
            r = Math.min(r, n);
            t = Math.max(t, 1);
            b = Math.min(b, n);

            if (l > r || t > b) {
                return;
            }

            tags[t][l]++;
            if (b < n) tags[b + 1][l]--;
            if (r < n) tags[t][r + 1]--;
            if (b < n && r < n) tags[b + 1][r + 1]++;
        }
    }

    static class FastInput {
        private final InputStream is;
        private final byte[] buf = new byte[BUFFER_SIZE];
        private int bufLen;
        private int bufOffset;
        private int next;

        public FastInput(InputStream is) {
            this.is = is;
        }

        private int read() {
            while (bufLen == bufOffset) {
                bufOffset = 0;
                try {
                    bufLen = is.read(buf);
                } catch (IOException e) {
                    bufLen = -1;
                }
                if (bufLen == -1) {
                    return -1;
                }
            }
            return buf[bufOffset++];
        }

        private void skipWhitespace() {
            while (next >= 0 && next <= MAX_WHITESPACE) {
                next = read();
            }
        }

        public int readInt() {
            skipWhitespace();
            int sign = 1;
            if (next == '+' || next == '-') {
                sign = next == '+' ? 1 : -1;
                next = read();
            }

            int val = 0;
            if (sign == 1) {
                while (next >= '0' && next <= '9') {
                    val = val * 10 + next - '0';
                    next = read();
                }
            } else {
                while (next >= '0' && next <= '9') {
                    val = val * 10 - next + '0';
                    next = read();
                }
            }
            return val;
        }

        public char readChar() {
            skipWhitespace();
            char c = (char) next;
            next = read();
            return c;
        }
    }

    static class FastOutput implements AutoCloseable, Appendable {
        private final StringBuilder cache = new StringBuilder(OUTPUT_BUFFER_SIZE);
        private final Writer os;

        public FastOutput(Writer os) {
            this.os = os;
        }

        public FastOutput(OutputStream os) {
            this(new OutputStreamWriter(os, StandardCharsets.UTF_8));
        }

        @Override
        public FastOutput append(CharSequence csq) {
            cache.append(csq);
            return this;
        }

        @Override
        public FastOutput append(CharSequence csq, int start, int end) {
            cache.append(csq, start, end);
            return this;
        }

        @Override
        public FastOutput append(char c) {
            cache.append(c);
            return this;
        }

        public FastOutput println(int val) {
            cache.append(val);
            println();
            return this;
        }

        public FastOutput println() {
            cache.append(System.lineSeparator());
            return this;
        }

        private void flush() {
            if (cache.length() > 0) {
                try {
                    os.append(cache);
                    os.flush();
                    cache.setLength(0);
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
        }

        @Override
        public void close() {
            flush();
            try {
                os.close();
            } catch (IOException e) {
                throw new UncheckedIOException(e);
            }
        }

        @Override
        public String toString() {
            return cache.toString();
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

public class CP {
    public static void main(String[] args) {
        FastScanner scanner = new FastScanner();
        PrintWriter out = new PrintWriter(System.out);
        try {
            new Solver().solve(scanner, out);
        } catch (IOException e) {
            e.printStackTrace();
        } finally {
            out.flush();
        }
    }

    /**
     * Standard FastScanner for efficient input parsing.
     * Replaces custom byte-buffer I/O with standard Java I/O for better maintainability.
     */
    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        public String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }

    /**
     * Encapsulates the core algorithm for grid processing and overlap calculation.
     */
    static class Solver {
        private int n;
        private int k;
        private boolean[][] grid;
        private int[][] diffArray; // 2D Difference Array

        void solve(FastScanner scanner, PrintWriter out) throws IOException {
            n = scanner.nextInt();
            k = scanner.nextInt();
            grid = new boolean[n][n];

            // Read grid input
            for (int i = 0; i < n; i++) {
                String row = scanner.next();
                for (int j = 0; j < n; j++) {
                    grid[i][j] = row.charAt(j) == 'B';
                }
            }

            diffArray = new int[n][n];

            // Process each row
            for (int i = 0; i < n; i++) {
                int minCol = n + 1;
                int maxCol = -1;
                for (int j = 0; j < n; j++) {
                    if (grid[i][j]) {
                        minCol = Math.min(minCol, j);
                        maxCol = Math.max(maxCol, j);
                    }
                }

                if (minCol > maxCol) {
                    // No 'B' in this row: mark the entire grid
                    update(0, 0, n - 1, n - 1);
                } else if (maxCol - minCol < k) {
                    // Width of bounding box is less than K: mark rectangle
                    update(i - k + 1, maxCol - k + 1, i, minCol);
                }
            }

            // Process each column
            for (int j = 0; j < n; j++) {
                int minRow = n + 1;
                int maxRow = -1;
                for (int i = 0; i < n; i++) {
                    if (grid[i][j]) {
                        minRow = Math.min(minRow, i);
                        maxRow = Math.max(maxRow, i);
                    }
                }

                if (minRow > maxRow) {
                    // No 'B' in this column: mark the entire grid
                    update(0, 0, n - 1, n - 1);
                } else if (maxRow - minRow < k) {
                    // Height of bounding box is less than K: mark rectangle
                    update(maxRow - k + 1, j - k + 1, minRow, j);
                }
            }

            // Compute 2D prefix sums from the difference array
            for (int i = 0; i < n; i++) {
                for (int j = 1; j < n; j++) {
                    diffArray[i][j] += diffArray[i][j - 1];
                }
            }
            for (int i = 1; i < n; i++) {
                for (int j = 0; j < n; j++) {
                    diffArray[i][j] += diffArray[i - 1][j];
                }
            }

            // Find the maximum overlap value
            long maxOverlap = 0;
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < n; j++) {
                    if (diffArray[i][j] > maxOverlap) {
                        maxOverlap = diffArray[i][j];
                    }
                }
            }

            out.println(maxOverlap);
        }

        /**
         * Applies a +1 update to a rectangular region using the 2D difference array technique.
         * Coordinates are clamped to valid grid bounds before applying updates.
         */
        private void update(int r1, int c1, int r2, int c2) {
            // Clamp coordinates to the grid boundaries
            r1 = Math.max(r1, 0);
            r2 = Math.min(r2, n - 1);
            c1 = Math.max(c1, 0);
            c2 = Math.min(c2, n - 1);

            // If the region is invalid after clamping, skip
            if (r1 > r2 || c1 > c2) {
                return;
            }

            // Standard 2D Difference Array updates
            diffArray[r1][c1]++;
            if (r2 + 1 < n && c2 + 1 < n) diffArray[r2 + 1][c2 + 1]++;
            if (r2 + 1 < n) diffArray[r2 + 1][c1]--;
            if (c2 + 1 < n) diffArray[r1][c2 + 1]--;
        }
    }
}

import java.util.Arrays;
import java.util.Scanner;

/**
 * Refactored solution for calculating the maximum number of empty rows and columns
 * within any k x k sliding window on an n x n grid.
 * 
 * Improvements:
 * - Removed all static state; class is now instantiable and thread-safe.
 * - Replaced cryptic/Hindi variable names with descriptive English equivalents.
 * - Extracted complex logic into well-named, single-responsibility methods.
 * - Used try-with-resources for proper Scanner management.
 * - Eliminated unnecessary static imports and magic numbers.
 * - Preserved original algorithmic behavior and time complexity.
 */
public class GridWindowCounter {

    private int n;
    private int k;
    private char[][] grid;
    private boolean[] rowEmpty;
    private boolean[] colEmpty;
    private int[] firstBInRow;
    private int[] lastBInRow;
    private int[] firstBInCol;
    private int[] lastBInCol;

    public static void main(String[] args) {
        try (Scanner sc = new Scanner(System.in)) {
            GridWindowCounter solver = new GridWindowCounter();
            solver.readInput(sc);
            solver.preprocessGrid();
            System.out.println(solver.calculateMaxEmptyCount());
        }
    }

    private void readInput(Scanner sc) {
        if (!sc.hasNextInt()) return;
        n = sc.nextInt();
        k = sc.nextInt();
        grid = new char[n][];
        for (int i = 0; i < n; i++) {
            grid[i] = sc.next().toCharArray();
        }
    }

    private void preprocessGrid() {
        rowEmpty = new boolean[n];
        colEmpty = new boolean[n];
        firstBInRow = new int[n];
        lastBInRow = new int[n];
        firstBInCol = new int[n];
        lastBInCol = new int[n];
        Arrays.fill(firstBInRow, -1);
        Arrays.fill(lastBInRow, -1);
        Arrays.fill(firstBInCol, -1);
        Arrays.fill(lastBInCol, -1);

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 'B') {
                    rowEmpty[i] = false;
                    if (firstBInRow[i] == -1) {
                        firstBInRow[i] = j;
                        lastBInRow[i] = j;
                    } else {
                        lastBInRow[i] = j;
                    }
                }
                if (grid[j][i] == 'B') {
                    colEmpty[i] = false;
                    if (firstBInCol[i] == -1) {
                        firstBInCol[i] = j;
                        lastBInCol[i] = j;
                    } else {
                        lastBInCol[i] = j;
                    }
                }
            }
        }
    }

    private int calculateMaxEmptyCount() {
        if (k >= n) {
            return 2 * n;
        }

        int[][] colCounts = new int[n - k + 1][n - k + 1];
        int[][] rowCountCounts = new int[n - k + 1][n - k + 1];

        // Calculate column counts for each window position
        int currentColCount = initializeColCount();
        colCounts[0][0] = currentColCount;
        for (int i = 0; i < n - k + 1; i++) {
            int originalCount = currentColCount;
            for (int j = 0; j < n - k; j++) {
                currentColCount = updateColCountWhenShiftingRight(i, j, currentColCount);
                colCounts[i][j + 1] = currentColCount;
            }
            if (i < n - k) {
                currentColCount = updateColCountWhenShiftingDown(i, 0, originalCount);
            }
        }

        // Calculate row counts for each window position
        int currentRowCount = initializeRowCount();
        rowCountCounts[0][0] = currentRowCount;
        for (int j = 0; j < n - k + 1; j++) {
            int originalCount = currentRowCount;
            for (int i = 0; i < n - k; i++) {
                currentRowCount = updateRowCountWhenShiftingDown(i, j, currentRowCount);
                rowCountCounts[i + 1][j] = currentRowCount;
            }
            if (j < n - k) {
                currentRowCount = updateRowCountWhenShiftingRight(0, j, originalCount);
            }
        }

        // Find the maximum sum of empty rows and columns in any k x k window
        int maxSum = 0;
        for (int i = 0; i < n - k + 1; i++) {
            for (int j = 0; j < n - k + 1; j++) {
                int sum = colCounts[i][j] + rowCountCounts[i][j];
                maxSum = Math.max(maxSum, sum);
            }
        }
        return maxSum;
    }

    private int initializeColCount() {
        int cnt = 0;
        for (int p = 0; p < k; p++) {
            if (colEmpty[p] || lastBInCol[p] < k) {
                cnt++;
            }
        }
        for (int p = k; p < n; p++) {
            if (colEmpty[p]) {
                cnt++;
            }
        }
        return cnt;
    }

    private int initializeRowCount() {
        int cnt = 0;
        for (int p = 0; p < k; p++) {
            if (rowEmpty[p] || lastBInRow[p] < k) {
                cnt++;
            }
        }
        for (int p = k; p < n; p++) {
            if (rowEmpty[p]) {
                cnt++;
            }
        }
        return cnt;
    }

    private int updateColCountWhenShiftingRight(int i, int j, int cnt) {
        if (!colEmpty[j] && firstBInCol[j] >= i && lastBInCol[j] < i + k) {
            cnt--;
        }
        if (!colEmpty[j + k] && firstBInCol[j + k] >= i && lastBInCol[j + k] < i + k) {
            cnt++;
        }
        return cnt;
    }

    private int updateColCountWhenShiftingDown(int i, int j, int cnt) {
        for (int p = j; p < j + k; p++) {
            if (!colEmpty[p] && firstBInCol[p] >= i && lastBInCol[p] < i + k) {
                cnt--;
            }
            if (!colEmpty[p] && firstBInCol[p] > i && lastBInCol[p] <= i + k) {
                cnt++;
            }
        }
        return cnt;
    }

    private int updateRowCountWhenShiftingDown(int i, int j, int cnt) {
        if (!rowEmpty[i] && firstBInRow[i] >= j && lastBInRow[i] < j + k) {
            cnt--;
        }
        if (!rowEmpty[i + k] && firstBInRow[i + k] >= j && lastBInRow[i + k] < j + k) {
            cnt++;
        }
        return cnt;
    }

    private int updateRowCountWhenShiftingRight(int i, int j, int cnt) {
        for (int p = i; p < i + k; p++) {
            if (!rowEmpty[p] && firstBInRow[p] >= j && lastBInRow[p] < j + k) {
                cnt--;
            }
            if (!rowEmpty[p] && firstBInRow[p] > j && lastBInRow[p] <= j + k) {
                cnt++;
            }
        }
        return cnt;
    }
}

import java.io.*;
import java.util.*;

public class CF_1200D {

    public static void main(String[] args) throws Exception {
        FastScanner in = new FastScanner(System.in);
        FastPrinter out = new FastPrinter(System.out);
        solve(in, out);
        out.close();
    }

    /**
     * Solves the problem using a 2D difference array to find the maximum overlap
     * of valid k x k square top-left corners, plus the count of empty rows/cols.
     */
    static void solve(FastScanner in, FastPrinter out) {
        int n = in.nextInt();
        int k = in.nextInt();

        boolean[][] grid = new boolean[n][n];
        for (int i = 0; i < n; i++) {
            String row = in.next();
            for (int j = 0; j < n; j++) {
                grid[i][j] = row.charAt(j) == 'B';
            }
        }

        int emptyLines = 0;
        int[][] diff = new int[n + 1][n + 1];

        // Process rows
        for (int i = 0; i < n; i++) {
            int first = -1, last = -1;
            for (int j = 0; j < n; j++) {
                if (grid[i][j]) {
                    if (first == -1) first = j;
                    last = j;
                }
            }

            if (first == -1) {
                emptyLines++;
                continue;
            }

            // Valid top-left column range for a k x k square to cover all 'B's in row i
            int cStart = Math.max(0, last - k + 1);
            int cEnd = first;
            // Valid top-left row range to include row i
            int rStart = Math.max(0, i - k + 1);
            int rEnd = i;

            if (cEnd < cStart) continue;

            updateDiff(diff, rStart, cStart, rEnd + 1, cEnd + 1);
        }

        // Process columns
        for (int j = 0; j < n; j++) {
            int first = -1, last = -1;
            for (int i = 0; i < n; i++) {
                if (grid[i][j]) {
                    if (first == -1) first = i;
                    last = i;
                }
            }

            if (first == -1) {
                emptyLines++;
                continue;
            }

            // Valid top-left row range for a k x k square to cover all 'B's in column j
            int rStart = Math.max(0, last - k + 1);
            int rEnd = first;
            // Valid top-left column range to include column j
            int cStart = Math.max(0, j - k + 1);
            int cEnd = j;

            if (rEnd < rStart) continue;

            updateDiff(diff, rStart, cStart, rEnd + 1, cEnd + 1);
        }

        // Compute 2D prefix sums from the difference array
        int[][] sums = new int[n + 1][n + 1];
        for (int i = 0; i <= n; i++) {
            for (int j = 0; j <= n; j++) {
                if (i > 0) sums[i][j] += sums[i - 1][j];
                if (j > 0) sums[i][j] += sums[i][j - 1];
                if (i > 0 && j > 0) sums[i][j] -= sums[i - 1][j - 1];
                sums[i][j] += diff[i][j];
            }
        }

        // Find maximum overlap
        int maxOverlap = 0;
        for (int i = 0; i <= n; i++) {
            for (int j = 0; j <= n; j++) {
                if (sums[i][j] > maxOverlap) {
                    maxOverlap = sums[i][j];
                }
            }
        }

        out.println(maxOverlap + emptyLines);
    }

    /**
     * Applies a standard 2D difference array update for rectangle [r1, r2) x [c1, c2).
     */
    private static void updateDiff(int[][] diff, int r1, int c1, int r2, int c2) {
        diff[r1][c1]++;
        diff[r1][c2]--;
        diff[r2][c1]--;
        diff[r2][c2]++;
    }

    // ==================== Utility Methods ====================

    static void readGraph(FastScanner in, ArrayList<ArrayList<Integer>> adj, int n) {
        for (int i = 0; i < n; i++) {
            int u = in.nextInt() - 1;
            int v = in.nextInt() - 1;
            adj.get(u).add(v);
            adj.get(v).add(u);
        }
    }

    static <T> ArrayList<ArrayList<T>> get2D(int n) {
        ArrayList<ArrayList<T>> ret = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            ret.add(new ArrayList<>());
        }
        return ret;
    }

    static void force(boolean condition) {
        if (!condition) {
            throw new IllegalStateException("Assertion failed");
        }
    }

    static void debug(Object obj) {
        if (obj instanceof long[][]) {
            for (long[] a : (long[][]) obj) System.out.println(Arrays.toString(a));
        } else if (obj instanceof int[][]) {
