        } else if (obj instanceof boolean[]) {
            System.out.println(Arrays.toString((boolean[]) obj));
        } else {
            System.out.println(obj);
        }
    }

    // ==================== Fast I/O ====================

    static class FastPrinter {
        private final PrintWriter out;

        FastPrinter(OutputStream os) {
            this(new OutputStreamWriter(os));
        }

        FastPrinter(Writer writer) {
            this.out = new PrintWriter(new BufferedWriter(writer));
        }

        void print(Object... objects) {
            for (int i = 0; i < objects.length; i++) {
                if (i != 0) out.print(' ');
                out.print(objects[i]);
            }
        }

        void println(Object... objects) {
            print(objects);
            out.println();
        }

        void flush() {
            out.flush();
        }

        void close() {
            out.close();
        }
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 13];
        private int pos, count;

        FastScanner(InputStream in) throws IOException {
            this.in = in;
        }

        private int read() throws IOException {
            try {
                if (pos >= count) {
                    pos = 0;
                    count = in.read(buffer);
                    if (count <= 0) {
                        return -1;
                    }
                }
            } catch (IOException e) {
                throw new InputMismatchException();
            }
            return buffer[pos++];
        }

        private static boolean isSpace(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        private int readSkipSpace() throws IOException {
            int c;
            do {
                c = read();
            } while (isSpace(c));
            return c;
        }

        int nextInt() throws IOException {
            int sign = 1;
            int c = readSkipSpace();
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                res = res * 10 + c - '0';
                c = read();
            } while (!isSpace(c));
            return res * sign;
        }

        String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c = readSkipSpace();
            do {
                sb.append((char) c);
                c = read();
            } while (!isSpace(c));
            return sb.toString();
        }

        long nextLong() throws IOException {
            return Long.parseLong(next());
        }

        int[] nextN(int n) throws IOException {
            int[] ret = new int[n];
            for (int i = 0; i < n; i++) {
                ret[i] = nextInt();
            }
            return ret;
        }

        long[] nextNL(int n) throws IOException {
            long[] ret = new long[n];
            for (int i = 0; i < n; i++) {
                ret[i] = nextLong();
            }
            return ret;
        }

        void close() throws IOException {
            in.close();
        }
    }
}

import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

/**
 * Refactored solution for grid analysis problem.
 * The original class name D578 has been changed to Main for standard execution.
 * Static state has been removed, logic is encapsulated in methods, and variable
 * naming has been improved for readability.
 */
public class Main {

    /**
     * Represents a rectangular region defined by top-left (x1, y1) and bottom-right (x2, y2) coordinates.
     */
    static class Rectangle {
        int x1, x2, y1, y2;

        public Rectangle(int x1, int x2, int y1, int y2) {
            this.x1 = x1;
            this.x2 = x2;
            this.y1 = y1;
            this.y2 = y2;
        }
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        // Read input dimensions n and parameter k
        if (!scanner.hasNextInt()) {
            scanner.close();
            return;
        }
        int n = scanner.nextInt();
        int k = scanner.nextInt();

        // Read the grid
        int[][] grid = readGrid(scanner, n);

        List<Rectangle> rectangles = new ArrayList<>();
        int emptyCount = 0;

        // Analyze rows to find valid regions and count empty rows
        emptyCount += analyzeRows(grid, n, k, rectangles);

        // Analyze columns to find valid regions and count empty columns
        emptyCount += analyzeCols(grid, n, k, rectangles);

        // Calculate the maximum overlap of rectangles using a 2D difference array
        int maxOverlap = calculateMaxOverlap(rectangles, n, k);

        // Output the result: max overlap count + number of empty rows/cols
        System.out.println(maxOverlap + emptyCount);

        scanner.close();
    }

    /**
     * Reads the grid from the scanner.
     */
    private static int[][] readGrid(Scanner scanner, int n) {
        int[][] grid = new int[n][n];
        for (int i = 0; i < n; i++) {
            String rowStr = scanner.next();
            for (int j = 0; j < n; j++) {
                if (rowStr.charAt(j) == 'B') {
                    grid[i][j] = 1;
                } else {
                    grid[i][j] = 0;
                }
            }
        }
        return grid;
    }

    /**
     * Analyzes each row to identify regions and count empty rows.
     */
    private static int analyzeRows(int[][] grid, int n, int k, List<Rectangle> rectangles) {
        int emptyRows = 0;

        for (int i = 0; i < n; i++) {
            int firstIndex = -1;
            int lastIndex = n;

            // Find the first occurrence of 'B' (1) in the row
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 1) {
                    firstIndex = j;
                    break;
                }
            }

            // Find the last occurrence of 'B' (1) in the row
            for (int j = n - 1; j >= 0; j--) {
                if (grid[i][j] == 1) {
                    lastIndex = j;
                    break;
                }
            }

            // If the row contains no 'B's, it is empty
            if (firstIndex == -1) {
                emptyRows++;
                continue;
            }

            // If the span of 'B's is too large (>= k), skip adding a rectangle
            // Note: Original logic: if (l - f >= k) continue;
            if (lastIndex - firstIndex >= k) {
                continue;
            }

            // Add the calculated rectangle
            // Original logic: new rect(i - k + 1, i, l - k + 1, f)
            // x range: [i - k + 1, i]
            // y range: [lastIndex - k + 1, firstIndex]
            int x1 = i - k + 1;
            int x2 = i;
            int y1 = lastIndex - k + 1;
            int y2 = firstIndex;

            rectangles.add(new Rectangle(x1, x2, y1, y2));
        }
        return emptyRows;
    }

    /**
     * Analyzes each column to identify regions and count empty columns.
     */
    private static int analyzeCols(int[][] grid, int n, int k, List<Rectangle> rectangles) {
        int emptyCols = 0;

        for (int j = 0; j < n; j++) {
            int firstIndex = -1; // Topmost 'B'
            int lastIndex = n;   // Bottommost 'B'

            // Find the first occurrence of 'B' (1) in the column (top to bottom)
            for (int i = 0; i < n; i++) {
                if (grid[i][j] == 1) {
                    firstIndex = i;
                    break;
                }
            }

            // Find the last occurrence of 'B' (1) in the column (bottom to top)
            for (int i = n - 1; i >= 0; i--) {
                if (grid[i][j] == 1) {
                    lastIndex = i;
                    break;
                }
            }

            // If the column contains no 'B's, it is empty
            if (firstIndex == -1) {
                emptyCols++;
                continue;
            }

            // If the span of 'B's is too large (>= k), skip adding a rectangle
            if (lastIndex - firstIndex >= k) {
                continue;
            }

            // Add the calculated rectangle
            // Original logic: new rect(l - k + 1, f, j - k + 1, j)
            // x range (rows): [lastIndex - k + 1, firstIndex]
            // y range (cols): [j - k + 1, j]
            int x1 = lastIndex - k + 1;
            int x2 = firstIndex;
            int y1 = j - k + 1;
            int y2 = j;

            rectangles.add(new Rectangle(x1, x2, y1, y2));
        }
        return emptyCols;
    }

    /**
     * Calculates the maximum overlap of rectangles using a 2D difference array.
     */
    private static int calculateMaxOverlap(List<Rectangle> rectangles, int n, int k) {
        // Difference array to mark rectangle boundaries
        // Size is (n+1)x(n+1) to handle 1-based indexing or boundary increments safely
        int[][] diffArray = new int[n + 1][n + 1];

        for (Rectangle rect : rectangles) {
            // Apply the clamping logic present in the original 'rect' constructor
            // x1, y1 clamped to min 0
            // x2, y2 clamped to max (n - k)
            int rX1 = Math.max(0, rect.x1);
            int rX2 = Math.min(n - k, rect.x2);
            int rY1 = Math.max(0, rect.y1);
            int rY2 = Math.min(n - k, rect.y2);

            // Ensure the rectangle is valid (start <= end)
            if (rX1 > rX2 || rY1 > rY2) {
                continue;
            }

            // Update the difference array (2D prefix sum technique)
            diffArray[rX1][rY1]++;
            diffArray[rX1][rY2 + 1]--;
            diffArray[rX2 + 1][rY1]--;
            diffArray[rX2 + 1][rY2 + 1]++;
        }

        // Compute the prefix sums to get the actual overlap counts
        int[][] prefixSum = new int[n + 1][n + 1];
        int maxVal = 0;

        // Iterate through the grid to compute prefix sums
        // The original code iterates i, j from 0 to n-1 and accesses s[i+1][j+1]
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                // 2D Prefix Sum formula:
                // current_cell = current_row_prefix + current_col_prefix - overlap + current_diff
                prefixSum[i + 1][j + 1] = prefixSum[i + 1][j] + prefixSum[i][j + 1] - prefixSum[i][j] + diffArray[i][j];

                if (prefixSum[i + 1][j + 1] > maxVal) {
                    maxVal = prefixSum[i + 1][j + 1];
                }
            }
        }

        return maxVal;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

public class Main {
    public static void main(String[] args) {
        FastReader reader = new FastReader();
        PrintWriter out = new PrintWriter(System.out);

        // Read dimensions and sliding window size
        int n = reader.nextInt();
        int m = n; // Original logic forces a square grid (m = n)
        int k = reader.nextInt();

        // Read grid input ('B' for black, all other characters treated as white)
        int[][] grid = new int[n + 1][m + 1];
        for (int i = 1; i <= n; i++) {
            String rowStr = reader.next();
            for (int j = 1; j <= m; j++) {
                grid[i][j] = (rowStr.charAt(j - 1) == 'B') ? 1 : 0;
            }
        }

        // Prefix sum arrays and counters for entirely white rows/columns
        int[][] rowPrefixSum = new int[n + 1][m + 1];
        int[][] colPrefixSum = new int[n + 1][m + 1];
        int[] whiteRowCount = new int[n + 1];
        int[] whiteColCount = new int[m + 1];

        // Compute row prefix sums and cumulative count of entirely white rows
        for (int i = 1; i <= n; i++) {
            rowPrefixSum[i][0] = 0;
            for (int j = 1; j <= m; j++) {
                rowPrefixSum[i][j] = grid[i][j] + rowPrefixSum[i][j - 1];
            }
            whiteRowCount[i] = whiteRowCount[i - 1] + (rowPrefixSum[i][m] == 0 ? 1 : 0);
        }

        // Compute column prefix sums and cumulative count of entirely white columns
        for (int j = 1; j <= m; j++) {
            colPrefixSum[0][j] = 0;
            for (int i = 1; i <= n; i++) {
                colPrefixSum[i][j] = grid[i][j] + colPrefixSum[i - 1][j];
            }
            whiteColCount[j] = whiteColCount[j - 1] + (colPrefixSum[n][j] == 0 ? 1 : 0);
        }

        // Arrays for sliding window calculations
        int[][] colWhitPrefix = new int[n + 1][n + 1];
        int[][] rowWhitPrefix = new int[n + 1][n + 1];
        int[][] ans = new int[n + 1][m + 1];

        // Process vertical sliding windows
        for (int j = 1; j <= n - k + 1; j++) {
            colWhitPrefix[0][j] = 0;
            for (int i = 1; i <= n; i++) {
                int blackCellsOutsideWindow = (rowPrefixSum[i][n] - rowPrefixSum[i][j + k - 1]) +
                                              (rowPrefixSum[i][j - 1] - rowPrefixSum[i][0]);
                colWhitPrefix[i][j] = (blackCellsOutsideWindow == 0) ? 1 : 0;
                colWhitPrefix[i][j] += colWhitPrefix[i - 1][j];
            }
            for (int i = 1; i <= n - k + 1; i++) {
                ans[i][j] = colWhitPrefix[i + k - 1][j] - colWhitPrefix[i - 1][j] +
                            whiteRowCount[n] - whiteRowCount[i + k - 1] + whiteRowCount[i - 1] - whiteRowCount[0];
            }
        }

        // Process horizontal sliding windows
        for (int i = 1; i <= n - k + 1; i++) {
            rowWhitPrefix[i][0] = 0;
            for (int j = 1; j <= n; j++) {
                int blackCellsOutsideWindow = (colPrefixSum[n][j] - colPrefixSum[i + k - 1][j]) +
                                              (colPrefixSum[i - 1][j] - colPrefixSum[0][j]);
                rowWhitPrefix[i][j] = (blackCellsOutsideWindow == 0) ? 1 : 0;
                rowWhitPrefix[i][j] += rowWhitPrefix[i][j - 1];
            }
            for (int j = 1; j <= n - k + 1; j++) {
                ans[i][j] += rowWhitPrefix[i][j + k - 1] - rowWhitPrefix[i][j - 1] +
                             whiteColCount[n] - whiteColCount[j + k - 1] + whiteColCount[j - 1] - whiteColCount[0];
            }
        }

        // Find the maximum score across all valid window positions
        int maxVal = 0;
        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= m; j++) {
                maxVal = Math.max(maxVal, ans[i][j]);
            }
        }

        out.println(maxVal);
        out.flush();
        out.close();
    }

    /**
     * Fast I/O helper class optimized for competitive programming style inputs.
     */
    static class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return st.nextToken();
        }

        String nextLine() {
            try {
                return br.readLine();
            } catch (IOException e) {
                throw new RuntimeException("Error reading line", e);
            }
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        long nextLong() {
            return Long.parseLong(next());
        }
    }
}

import java.io.*;
import java.util.StringTokenizer;

public class TwoDPrefixSolver {

    public static void main(String[] args) {
        FastReader reader = new FastReader();
        PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out));
        try {
            long result = solve(reader);
            out.print(result);
        } finally {
            out.flush();
            out.close();
        }
    }

    /**
     * Core logic for the 2D prefix sum problem.
     */
    private static long solve(FastReader sc) {
        int n = sc.nextInt();
        int k = sc.nextInt();

        // 1-based prefix sum array for counting 'B' characters
        long[][] prefixSum = new long[n + 1][n + 1];

        for (int i = 1; i <= n; i++) {
            String line = sc.next();
            for (int j = 1; j <= n; j++) {
                int isB = (line.charAt(j - 1) == 'B') ? 1 : 0;
                prefixSum[i][j] = isB + prefixSum[i - 1][j] + prefixSum[i][j - 1] - prefixSum[i - 1][j - 1];
            }
        }

        // Count rows and columns with zero 'B's
        int emptyLinesCount = 0;
        for (int i = 1; i <= n; i++) {
            if (query(prefixSum, i, 1, i, n) == 0) emptyLinesCount++;
            if (query(prefixSum, 1, i, n, i) == 0) emptyLinesCount++;
        }

        // Mark 1 if a segment of length k has the same count as the full row/column
        long[][] rowMark = new long[n + 1][n + 1];
        long[][] colMark = new long[n + 1][n + 1];

        for (int i = 1; i <= n; i++) {
            long fullRowCount = query(prefixSum, i, 1, i, n);
            for (int j = 1; j <= n; j++) {
                if (fullRowCount != 0) {
                    long segCount = query(prefixSum, i, j, i, Math.min(n, j + k - 1));
                    if (segCount == fullRowCount) {
                        rowMark[i][j] = 1;
                    }
                }
            }
        }

        for (int j = 1; j <= n; j++) {
            long fullColCount = query(prefixSum, 1, j, n, j);
            for (int i = 1; i <= n; i++) {
                if (fullColCount != 0) {
                    long segCount = query(prefixSum, i, j, Math.min(n, i + k - 1), j);
                    if (segCount == fullColCount) {
                        colMark[i][j] = 1;
                    }
                }
            }
        }

        // Compute prefix sums for rowMark and colMark
        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= n; j++) {
                rowMark[i][j] += rowMark[i - 1][j];
                colMark[i][j] += colMark[i][j - 1];
            }
        }

        // Find maximum score for any k x k window
        long maxWindowScore = 0;
        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= n; j++) {
                int iEnd = Math.min(n, i + k - 1);
                int jEnd = Math.min(n, j + k - 1);
                long currentScore = (rowMark[iEnd][j] - rowMark[i - 1][j]) +
                                    (colMark[i][jEnd] - colMark[i][j - 1]);
                if (currentScore > maxWindowScore) {
                    maxWindowScore = currentScore;
                }
            }
        }

        return emptyLinesCount + maxWindowScore;
    }

    /**
     * Queries the 2D prefix sum for a rectangle defined by (r1, c1) to (r2, c2).
     * Automatically clamps r2 and c2 to the grid boundaries.
     */
    private static long query(long[][] prefixSum, int r1, int c1, int r2, int c2) {
        r2 = Math.min(r2, prefixSum.length - 1);
        c2 = Math.min(c2, prefixSum[0].length - 1);
        return prefixSum[r2][c2] - prefixSum[r1 - 1][c2] - prefixSum[r2][c1 - 1] + prefixSum[r1 - 1][c1 - 1];
    }

    /**
     * Fast I/O reader commonly used in competitive programming.
     */
    static class FastReader {
        private final BufferedReader br;
        private StringTokenizer tokenizer;

        public FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return tokenizer.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        long nextLong() {
            return Long.parseLong(next());
        }

        double nextDouble() {
            return Double.parseDouble(next());
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

public class Task1200D {

    public static void main(String[] args) {
        InputReader in = new InputReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        // The original code hardcoded t=1 and did not read a test case count.
        // We execute the solution logic once.
        solve(in, out);

        out.flush();
        out.close();
    }

    private static void solve(InputReader in, PrintWriter out) {
        // Read dimensions and rectangle size
        int n = in.nextInt();
        int k = in.nextInt();

        // Read the grid
        char[][] grid = new char[n][n];
        for (int i = 0; i < n; i++) {
            grid[i] = in.next().toCharArray();
        }

        // Difference array to count overlaps. 
        // Size (n+1)x(n+1) to handle boundary conditions (1-based indexing logic or padding).
        // Java initializes int arrays to 0, so explicit filling is not required.
        int[][] differenceGrid = new int[n + 1][n + 1];

        // Process each row to find horizontal segments of 'W's
        for (int i = 0; i < n; i++) {
            int segmentStart = 0;
            while (segmentStart < n && grid[i][segmentStart] == 'W') {
                segmentStart++;
            }

            int segmentEnd = n - 1;
            while (segmentEnd >= 0 && grid[i][segmentEnd] == 'W') {
                segmentEnd--;
            }

            // If the entire row consists of 'W's
            if (segmentStart == n) {
                differenceGrid[0][0]++;
                continue;
            }

            // If the contiguous segment of 'W's is longer than k
            if (segmentEnd - segmentStart + 1 > k) {
                continue;
            }

            // Calculate bounds for the difference array update
            // These bounds define the rectangle of valid top-left corners for a 1xk rectangle
            // that covers the segment [segmentStart, segmentEnd] in row i.
            int rowStart = Math.max(i - k + 1, 0);
            int rowEnd = i + 1;
            int colStart = Math.max(segmentEnd - k + 1, 0);
            int colEnd = segmentStart + 1;

            // Apply 2D Difference Array Update
            differenceGrid[rowStart][colStart]++;
            differenceGrid[rowEnd][colEnd]++;
            differenceGrid[rowStart][colEnd]--;
            differenceGrid[rowEnd][colStart]--;
        }

        // Process each column to find vertical segments of 'W's
        for (int i = 0; i < n; i++) {
            int segmentStart = 0;
            while (segmentStart < n && grid[segmentStart][i] == 'W') {
                segmentStart++;
            }

            int segmentEnd = n - 1;
            while (segmentEnd >= 0 && grid[segmentEnd][i] == 'W') {
                segmentEnd--;
            }

            // If the entire column consists of 'W's
            if (segmentStart == n) {
                differenceGrid[0][0]++;
                continue;
            }

            // If the contiguous segment of 'W's is longer than k
            if (segmentEnd - segmentStart + 1 > k) {
                continue;
            }

            // Calculate bounds for the difference array update
            // These bounds define the rectangle of valid top-left corners for a kx1 rectangle
            // that covers the segment [segmentStart, segmentEnd] in column i.
            int rowStart = Math.max(segmentEnd - k + 1, 0);
            int rowEnd = segmentStart + 1;
            int colStart = Math.max(i - k + 1, 0);
            int colEnd = i + 1;

            // Apply 2D Difference Array Update
            differenceGrid[rowStart][colStart]++;
            differenceGrid[rowEnd][colEnd]++;
            differenceGrid[rowStart][colEnd]--;
            differenceGrid[rowEnd][colStart]--;
        }

        // Compute 2D Prefix Sums to transform difference array into actual counts
        // First, accumulate along rows
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                differenceGrid[i][j + 1] += differenceGrid[i][j];
            }
        }
        // Then, accumulate along columns
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                differenceGrid[i + 1][j] += differenceGrid[i][j];
            }
        }

        // Find the maximum value in the grid
        int maxVal = 0;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (differenceGrid[i][j] > maxVal) {
                    maxVal = differenceGrid[i][j];
                }
            }
        }

        out.println(maxVal);
    }

    /**
     * Fast Input Reader for competitive programming or large I/O operations.
     */
    static class InputReader {
        public BufferedReader reader;
        public StringTokenizer tokenizer;

        public InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) {
                        return null;
                    }
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            String s = next();
            if (s == null) throw new RuntimeException("End of input");
            return Integer.parseInt(s);
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Main entry point for the competitive programming solution.
 * Uses a dedicated thread with increased stack size to prevent StackOverflowError
 * during deep recursion or large local array allocations.
 */
public class Main {
    public static void main(String[] args) {
        // Increase stack size to 64MB (1 << 26 bytes) to accommodate large local variables
        new Thread(null, () -> new Main().solve(), "solver-thread", 1 << 26).start();
    }

    private void solve() {
        FastScanner in = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out));

        try {
            new Solver().solve(in, out);
        } finally {
            out.flush();
            out.close();
        }
    }

    /**
     * Core solver class encapsulating the grid processing and optimization logic.
     */
    static class Solver {
        // 2D prefix sum arrays
        private int[][] gridPrefixSum;
        private int[][] rowCompletionPrefix;
        private int[][] colCompletionPrefix;

        private int n;
        private int k;

        /**
         * Solves the problem for a single test case.
         * 
         * @param in  FastScanner for efficient input reading
         * @param out PrintWriter for efficient output writing
         */
        public void solve(FastScanner in, PrintWriter out) {
            n = in.nextInt();
            k = in.nextInt();

            int[][] grid = new int[n + 1][n + 1];
            int[] fullRowCount = new int[n + 1];
            int[] fullColCount = new int[n + 1];

            // Read grid and count white cells per row/column
            for (int i = 1; i <= n; i++) {
                for (int j = 1; j <= n; j++) {
                    grid[i][j] = in.nextChar() == 'B' ? 1 : 0;
                    if (grid[i][j] == 0) {
                        fullRowCount[i]++;
                        fullColCount[j]++;
                    }
                }
            }

            // Mark rows/columns that are already completely white
            for (int i = 1; i <= n; i++) {
                fullRowCount[i] = (fullRowCount[i] == n) ? 1 : 0;
                fullColCount[i] = (fullColCount[i] == n) ? 1 : 0;
            }

            // Compute 1D prefix sums for fully white rows/columns
            for (int i = 1; i <= n; i++) {
                fullRowCount[i] += fullRowCount[i - 1];
                fullColCount[i] += fullColCount[i - 1];
            }

            // Compute 2D prefix sum for the grid to enable O(1) range queries
            gridPrefixSum = new int[n + 1][n + 1];
            for (int i = 1; i <= n; i++) {
                for (int j = 1; j <= n; j++) {
                    gridPrefixSum[i][j] = gridPrefixSum[i - 1][j]
                                        + gridPrefixSum[i][j - 1]
                                        - gridPrefixSum[i - 1][j - 1]
                                        + grid[i][j];
                }
            }

            // Determine which rows become completely white if a k x k square is placed
            rowCompletionPrefix = new int[n + 2][n + 2];
            for (int i = 1; i <= n + 1; i++) {
                for (int j = 1; j <= n + 1; j++) {
                    boolean isRowCompleted = true;
                    if (j - k - 1 >= 0) {
                        // Check if column j is entirely white outside the window [i, i+k-1]
                        int topSum = query(gridPrefixSum, 0, j, i - k - 1, j);
                        int botSum = query(gridPrefixSum, i, j, n, j);
                        isRowCompleted = (topSum + botSum) == 0;
                    }
                    rowCompletionPrefix[i][j] = isRowCompleted ? 1 : 0;
                    rowCompletionPrefix[i][j] += rowCompletionPrefix[i - 1][j]
                                             + rowCompletionPrefix[i][j - 1]
                                             - rowCompletionPrefix[i - 1][j - 1];
                }
            }

            // Determine which columns become completely white if a k x k square is placed
            colCompletionPrefix = new int[n + 2][n + 2];
            for (int i = 1; i <= n + 1; i++) {
                for (int j = 1; j <= n + 1; j++) {
                    boolean isColCompleted = true;
                    if (i - k - 1 >= 0) {
                        // Check if row i is entirely white outside the window [j, j+k-1]
                        int leftSum = query(gridPrefixSum, i, 0, i, j - k - 1);
                        int rightSum = query(gridPrefixSum, i, j, i, n);
                        isColCompleted = (leftSum + rightSum) == 0;
                    }
                    colCompletionPrefix[i][j] = isColCompleted ? 1 : 0;
                    colCompletionPrefix[i][j] += colCompletionPrefix[i - 1][j]
                                             + colCompletionPrefix[i][j - 1]
                                             - colCompletionPrefix[i - 1][j - 1];
                }
            }

            // Slide the k x k window and calculate the maximum number of complete white lines
            int maxWhiteLines = 0;
            for (int i = 1; i <= n; i++) {
                for (int j = 1; j <= n; j++) {
                    if (i + k - 1 <= n && j + k - 1 <= n) {
                        int currentWhiteLines = fullRowCount[n] + fullColCount[n];

                        // Subtract rows/columns that were originally full but now contain black cells
                        currentWhiteLines -= (fullRowCount[i + k - 1] - fullRowCount[i - 1]);
                        currentWhiteLines -= (fullColCount[j + k - 1] - fullColCount[j - 1]);

                        // Add rows/columns that become full due to the k x k fill
                        currentWhiteLines += query(rowCompletionPrefix, i + k, j, i + k, j + k - 1);
                        currentWhiteLines += query(colCompletionPrefix, i, j + k, i + k - 1, j + k);

                        maxWhiteLines = Math.max(maxWhiteLines, currentWhiteLines);
                    }
                }
            }

            out.println(maxWhiteLines);
        }

        /**
         * Queries a 2D prefix sum array in O(1) time.
         * Clamps coordinates to valid bounds [1, max] to prevent IndexOutOfBoundsException.
         */
        private int query(int[][] prefixSum, int r1, int c1, int r2, int c2) {
            int maxR = prefixSum.length - 1;
            int maxC = prefixSum[0].length - 1;

            // Clamp indices to valid 1-based range
            r2 = Math.min(r2, maxR);
            c2 = Math.min(c2, maxC);
            r1 = Math.max(r1, 1);
            c1 = Math.max(c1, 1);

            if (r2 < r1 || c2 < c1) {
                return 0;
            }

            return prefixSum[r2][c2]
                 - prefixSum[r2][c1 - 1]
                 - prefixSum[r1 - 1][c2]
                 + prefixSum[r1 - 1][c1 - 1];
        }
    }

    /**
     * Fast I/O utility class for competitive programming.
     * Replaces Scanner with a byte-buffered reader for significant performance gains.
     */
    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 14];
        private int ptr = 0;
        private int buflen = 0;

        public FastScanner(InputStream in) {
            this.in = in;
        }

        private int readByte() {
            if (ptr >= buflen) {
                ptr = 0;
                try {
                    buflen = in.read(buffer);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input", e);
                }
                if (buflen <= 0) {
                    return -1;
                }
            }
            return buffer[ptr++];
        }

        private static boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        public int nextInt() {
            int c = readByte();
            while (isSpaceChar(c)) {
                c = readByte();
            }
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = readByte();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9') {
                    throw new InputMismatchException("Invalid integer format");
                }
                res *= 10;
                res += c - '0';
                c = readByte();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public char nextChar() {
            int c = readByte();
            while (isSpaceChar(c)) {
                c = readByte();
            }
            return (char) c;
        }
    }
}

import java.io.*;
import java.util.*;

public class GridCoverageAnalyzer {

    /**
     * Transposes a square grid of strings.
     * Assumes the input grid is n x n.
     */
    private static String[] transpose(String[] grid) {
        int n = grid.length;
        String[] transposed = new String[n];
        for (int i = 0; i < n; i++) {
            char[] rowChars = new char[n];
            for (int j = 0; j < n; j++) {
                rowChars[j] = grid[j].charAt(i);
            }
            transposed[i] = new String(rowChars);
        }
        return transposed;
    }

    /**
     * Calculates a coverage grid where each cell (r, c) contains the number of
     * valid k-length segments covering that cell.
     */
    private static int[][] calculateCoverage(String[] grid, int k) {
        int n = grid.length;
        int[][] coverage = new int[n][n];
        int[][] validStarts = new int[n][n];

        // Mark valid starting positions for k-length segments in each row
        for (int row = 0; row < n; row++) {
            int firstB = -1;
            int lastB = -1;
            for (int col = 0; col < n; col++) {
                if (grid[row].charAt(col) == 'B') {
                    if (firstB == -1) firstB = col;
                    lastB = col;
                }
            }
            if (firstB != -1) {
                int startCol = Math.max(0, lastB - k + 1);
                for (int col = startCol; col <= firstB; col++) {
                    validStarts[row][col] = 1;
                }
            }
        }

        // Compute sliding window sums vertically for each column
        for (int col = 0; col < n; col++) {
            int windowSum = 0;
            for (int i = 0; i < k; i++) {
                windowSum += validStarts[i][col];
            }
            for (int row = 0; row < n; row++) {
                coverage[row][col] = windowSum;
                if (row < n - k) {
                    windowSum += validStarts[row + k][col];
                    windowSum -= validStarts[row][col];
                }
            }
        }
        return coverage;
    }

    /**
     * Counts the number of completely empty rows and columns (containing no 'B').
     */
    private static int countEmptyRowsAndColumns(String[] grid) {
        int n = grid.length;
        int emptyCount = 0;
        for (int i = 0; i < n; i++) {
            boolean rowEmpty = true;
            boolean colEmpty = true;
            for (int j = 0; j < n; j++) {
                if (grid[i].charAt(j) == 'B') rowEmpty = false;
                if (grid[j].charAt(i) == 'B') colEmpty = false;
            }
            if (rowEmpty) emptyCount++;
            if (colEmpty) emptyCount++;
        }
        return emptyCount;
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        PrintWriter out = new PrintWriter(System.out);

        if (scanner.hasNextInt()) {
            int n = scanner.nextInt();
            int k = scanner.nextInt();
            scanner.nextLine(); // Consume the remaining newline character

            String[] grid = new String[n];
            for (int i = 0; i < n; i++) {
                grid[i] = scanner.nextLine();
            }

            String[] transposedGrid = transpose(grid);
            int[][] horizontalCoverage = calculateCoverage(grid, k);
            int[][] verticalCoverage = calculateCoverage(transposedGrid, k);

            int maxCoverage = 0;
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < n; j++) {
                    int currentCoverage = horizontalCoverage[i][j] + verticalCoverage[i][j];
                    if (currentCoverage > maxCoverage) {
                        maxCoverage = currentCoverage;
                    }
                }
            }

            out.println(maxCoverage + countEmptyRowsAndColumns(grid));
        }

        out.flush();
        scanner.close();
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

/**
 * Analyzes a grid to find the maximum number of white cells within any KxK subgrid.
 * A cell is considered "white" if it's not a black cell ('B').
 * The solution uses prefix sums and a sliding window approach for O(N^2) performance.
 */
public class GridAnalyzer {

    public static void main(String[] args) throws IOException {
        // 1. Input Parsing
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(reader.readLine());
        int n = Integer.parseInt(st.nextToken());
        int k = Integer.parseInt(st.nextToken());

        char[][] grid = new char[n][];
        for (int i = 0; i < n; i++) {
            grid[i] = reader.readLine().toCharArray();
        }

        // 2. Precompute counts and prefix sums
        int[] blackCountsPerRow = new int[n];
        int[] blackCountsPerCol = new int[n];
        int[][] prefixRowSums = new int[n][n];
        int[][] prefixColSums = new int[n][n];

        computePrefixSumsAndCounts(grid, n, blackCountsPerRow, blackCountsPerCol, prefixRowSums, prefixColSums);

        // 3. Count rows/columns that are completely white
        int alreadyWhiteLines = countFullyWhiteLines(n, blackCountsPerRow, blackCountsPerCol);

        // 4. Compute white cell counts for all KxK windows
        int[][] windowWhiteCounts = computeWindowWhiteCounts(n, k, blackCountsPerCol, prefixColSums,
                                                             blackCountsPerRow, prefixRowSums, alreadyWhiteLines);

        // 5. Output the maximum count found
        System.out.println(findMaxValue(windowWhiteCounts));
    }

    /**
     * Calculates the number of black cells per row/column and builds 2D prefix sum arrays.
     */
    private static void computePrefixSumsAndCounts(char[][] grid, int n,
                                                   int[] blackCountsPerRow, int[] blackCountsPerCol,
                                                   int[][] prefixRowSums, int[][] prefixColSums) {
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < n; c++) {
                boolean isBlack = grid[r][c] == 'B';
                blackCountsPerRow[r] += isBlack ? 1 : 0;
                blackCountsPerCol[c] += isBlack ? 1 : 0;

                prefixRowSums[r][c] = (c > 0 ? prefixRowSums[r][c - 1] : 0) + (isBlack ? 1 : 0);
                prefixColSums[r][c] = (r > 0 ? prefixColSums[r - 1][c] : 0) + (isBlack ? 1 : 0);
            }
        }
    }

    /**
     * Counts how many rows and columns contain zero black cells.
     */
    private static int countFullyWhiteLines(int n, int[] blackCountsPerRow, int[] blackCountsPerCol) {
        int count = 0;
        for (int i = 0; i < n; i++) {
            if (blackCountsPerRow[i] == 0) count++;
            if (blackCountsPerCol[i] == 0) count++;
        }
        return count;
    }

    /**
     * Checks if all black cells in a specific column are contained within a vertical window of height K.
     */
    private static boolean isColumnFullyContained(int rowStart, int col, int k, int[] prefixColSums, int colBlackCount) {
        int blackCellsInWindow = prefixColSums[rowStart + k - 1][col];
        if (rowStart > 0) {
            blackCellsInWindow -= prefixColSums[rowStart - 1][col];
        }
        return blackCellsInWindow == colBlackCount;
    }

    /**
     * Checks if all black cells in a specific row are contained within a horizontal window of width K.
     */
    private static boolean isRowFullyContained(int row, int colStart, int k, int[] prefixRowSums, int rowBlackCount) {
        int blackCellsInWindow = prefixRowSums[row][colStart + k - 1];
        if (colStart > 0) {
            blackCellsInWindow -= prefixRowSums[row][colStart - 1];
        }
        return blackCellsInWindow == rowBlackCount;
    }

    /**
     * Uses a sliding window approach to calculate how many fully-contained rows/columns 
     * exist for every possible KxK window top-left position.
     */
    private static int[][] computeWindowWhiteCounts(int n, int k, int[] blackCountsPerCol, int[][] prefixColSums,
                                                    int[] blackCountsPerRow, int[][] prefixRowSums,
                                                    int alreadyWhiteLines) {
        int[][] whiteCounts = new int[n - k + 1][n - k + 1];

        // Slide window vertically over columns
        for (int r = 0; r < n - k + 1; r++) {
            int temp = 0;
            for (int c = 0; c < k; c++) {
                if (isColumnFullyContained(r, c, k, prefixColSums, blackCountsPerCol[c])) {
                    temp++;
                }
            }
            whiteCounts[r][0] = temp;

            for (int c = k; c < n; c++) {
                if (isColumnFullyContained(r, c - k, k, prefixColSums, blackCountsPerCol[c - k])) {
                    temp--;
                }
                if (isColumnFullyContained(r, c, k, prefixColSums, blackCountsPerCol[c])) {
                    temp++;
                }
                whiteCounts[r][c - k + 1] = temp;
            }
        }

        // Slide window horizontally over rows
        for (int c = 0; c < n - k + 1; c++) {
            int temp = 0;
            for (int r = 0; r < k; r++) {
                if (isRowFullyContained(r, c, k, prefixRowSums, blackCountsPerRow[r])) {
                    temp++;
                }
            }
            whiteCounts[0][c] += temp;

            for (int r = k; r < n; r++) {
                if (isRowFullyContained(r - k, c, k, prefixRowSums, blackCountsPerRow[r - k])) {
                    temp--;
                }
                if (isRowFullyContained(r, c, k, prefixRowSums, blackCountsPerRow[r])) {
                    temp++;
                }
                whiteCounts[r - k + 1][c] += temp;
            }
        }

        return whiteCounts;
    }

    /**
     * Finds the maximum value in a 2D integer array.
     */
    private static int findMaxValue(int[][] matrix) {
        int max = 0;
        for (int[] row : matrix) {
            for (int val : row) {
                if (val > max) {
                    max = val;
                }
            }
        }
        return max;
    }
}

import java.util.Scanner;
import java.io.PrintWriter;

public class Main {

    public static void main(String[] args) {
        new Main().run();
    }

    /**
     * Entry point that handles resource management and delegates to the solver.
     */
    void run() {
        try (Scanner in = new Scanner(System.in);
             PrintWriter out = new PrintWriter(System.out)) {
            solve(in, out);
        }
    }

    /**
     * Core logic: reads the grid, computes coverage possibilities,
     * applies a sliding window to find the optimal k x k square,
     * and prints the maximum number of cleared rows and columns.
     */
    void solve(Scanner in, PrintWriter out) {
        int n = in.nextInt();
        int k = in.nextInt();
        char[][] grid = readGrid(in, n);

        int emptyRows = 0;
        int emptyCols = 0;
        boolean[][] rowCovered = new boolean[n][n];
        boolean[][] colCovered = new boolean[n][n];

        // Process rows: identify empty rows and valid horizontal segment starts
        for (int i = 0; i < n; i++) {
            int[] bIndices = findFirstAndLastB(grid[i]);
            if (bIndices[0] == -1) {
                emptyRows++;
                continue;
            }
            markCoverageRange(rowCovered[i], bIndices[0], bIndices[1], k);
        }

        // Process columns: identify empty columns and valid vertical segment starts
        for (int j = 0; j < n; j++) {
            int[] bIndices = findFirstAndLastBInColumn(grid, j);
            if (bIndices[0] == -1) {
                emptyCols++;
                continue;
            }
            markCoverageRange(colCovered, bIndices[0], bIndices[1], k, j);
        }

        // Calculate sliding window sums for k x k squares
        int[][] horizontalCounts = computeSlidingWindowSums(rowCovered, k, n);
        int[][] verticalCounts = computeSlidingWindowSumsTranspose(colCovered, k, n);

        // Find the maximum coverage achievable by placing a k x k square
        int maxCoverage = emptyRows + emptyCols;
        int limit = n - k + 1;
        for (int r = 0; r < limit; r++) {
            for (int c = 0; c < limit; c++) {
                int currentCoverage = emptyRows + emptyCols
                    + horizontalCounts[r][c]
                    + verticalCounts[r][c];
                if (currentCoverage > maxCoverage) {
                    maxCoverage = currentCoverage;
                }
            }
        }

        out.println(maxCoverage);
    }

    private char[][] readGrid(Scanner in, int n) {
        char[][] grid = new char[n][n];
        for (int i = 0; i < n; i++) {
            grid[i] = in.next().toCharArray();
        }
        return grid;
    }

    private int[] findFirstAndLastB(char[] row) {
        int first = -1;
        int last = -1;
        for (int j = 0; j < row.length; j++) {
            if (row[j] == 'B') {
                if (first == -1) first = j;
                last = j;
            }
        }
        return new int[]{first, last};
    }

    private int[] findFirstAndLastBInColumn(char[][] grid, int col) {
        int first = -1;
        int last = -1;
        for (int i = 0; i < grid.length; i++) {
            if (grid[i][col] == 'B') {
                if (first == -1) first = i;
                last = i;
            }
        }
        return new int[]{first, last};
    }

    /**
     * Marks valid start indices for a segment of length k that covers
     * all 'B's between firstB and lastB (inclusive).
     */
    private void markCoverageRange(boolean[] range, int firstB, int lastB, int k) {
        int minStart = Math.max(0, lastB - k + 1);
        int maxStart = firstB;
        for (int j = minStart; j <= maxStart; j++) {
            range[j] = true;
        }
    }

    /**
     * Marks valid start indices for a segment of length k that covers
     * all 'B's between firstB and lastB (inclusive) in a specific column.
     */
    private void markCoverageRange(boolean[][] matrix, int firstB, int lastB, int k, int col) {
        int minStart = Math.max(0, lastB - k + 1);
        int maxStart = firstB;
        for (int i = minStart; i <= maxStart; i++) {
            matrix[i][col] = true;
        }
    }

    /**
     * Computes a sliding window sum over rows for each column.
     * horizontalCounts[r][c] = number of rows in [r, r+k-1] covered by a horizontal segment starting at c.
     */
    private int[][] computeSlidingWindowSums(boolean[][] matrix, int k, int n) {
        int limit = n - k + 1;
        int[][] sums = new int[limit][limit];

        for (int c = 0; c < limit; c++) {
            int count = 0;
            for (int r = 0; r < k; r++) {
                if (matrix[r][c]) count++;
            }
            sums[0][c] = count;

            for (int r = 1; r < limit; r++) {
                if (matrix[r - 1][c]) count--;
                if (matrix[r + k - 1][c]) count++;
                sums[r][c] = count;
            }
        }
        return sums;
    }

    /**
     * Computes a sliding window sum over columns for each row.
     * verticalCounts[r][c] = number of columns in [c, c+k-1] covered by a vertical segment starting at r.
     */
    private int[][] computeSlidingWindowSumsTranspose(boolean[][] matrix, int k, int n) {
        int limit = n - k + 1;
        int[][] sums = new int[limit][limit];

        for (int r = 0; r < limit; r++) {
            int count = 0;
            for (int c = 0; c < k; c++) {
                if (matrix[r][c]) count++;
            }
            sums[r][0] = count;

            for (int c = 1; c < limit; c++) {
                if (matrix[r][c - 1]) count--;
                if (matrix[r][c + k - 1]) count++;
                sums[r][c] = count;
            }
        }
        return sums;
    }
}

import java.io.*;
import java.util.Arrays;
import java.util.NoSuchElementException;
import java.util.StringTokenizer;

public class P1200D_2 {

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        // Read input dimensions
        int n = scanner.nextInt();
        int k = scanner.nextInt();

        // Guard against invalid window size
        if (k > n) {
            writer.println(0);
            writer.flush();
            return;
        }

        // Read grid
        char[][] grid = new char[n][];
        for (int i = 0; i < n; i++) {
            grid[i] = scanner.next().toCharArray();
        }

        // Initialize bounding box arrays
        int[] colTop = new int[n];
        int[] colBottom = new int[n];
        int[] rowLeft = new int[n];
        int[] rowRight = new int[n];

        Arrays.fill(colTop, n);
        Arrays.fill(rowLeft, n);
        Arrays.fill(colBottom, -1);
        Arrays.fill(rowRight, -1);

        // Compute bounding boxes for each row and column
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 'B') {
                    colTop[j] = Math.min(colTop[j], i);
                    colBottom[j] = Math.max(colBottom[j], i);
                    rowLeft[i] = Math.min(rowLeft[i], j);
                    rowRight[i] = Math.max(rowRight[i], j);
                }
            }
        }

        // Count rows and columns that are already empty (cleared)
        int alreadyCleared = 0;
        for (int i = 0; i < n; i++) {
            if (rowRight[i] < rowLeft[i]) alreadyCleared++;
            if (colBottom[i] < colTop[i]) alreadyCleared++;
        }

        // Calculate additional cleared rows/cols using sliding window technique
        int[][] colContrib = computeSlidingWindowCounts(colTop, colBottom, n, k);
        int[][] rowContrib = computeSlidingWindowCounts(rowLeft, rowRight, n, k);

        // Find the maximum additional cleared rows + columns for any k x k subgrid
        int maxAdditional = 0;
        for (int i = 0; i <= n - k; i++) {
            for (int j = 0; j <= n - k; j++) {
                maxAdditional = Math.max(maxAdditional, colContrib[i][j] + rowContrib[i][j]);
            }
        }

        writer.println(alreadyCleared + maxAdditional);
        writer.flush();
    }

    /**
     * Computes a 2D array where each cell [i][j] represents the number of axes 
     * (rows or columns) in a k-length window starting at j that are activated 
     * by a perpendicular window of size k starting at i.
     */
    private static int[][] computeSlidingWindowCounts(int[] minBounds, int[] maxBounds, int n, int k) {
        int[][] counts = new int[n - k + 1][n - k + 1];

        for (int i = 0; i <= n - k; i++) {
            int currentCount = 0;

            // Initialize count for the first window position
            for (int j = 0; j < k; j++) {
                if (isAxisActive(minBounds[j], maxBounds[j], i, i + k)) {
                    currentCount++;
                }
            }
            counts[i][0] = currentCount;

            // Slide the window horizontally using a running sum
            for (int j = 1; j <= n - k; j++) {
                counts[i][j] = counts[i][j - 1];

                // Remove the axis leaving the window
                if (isAxisActive(minBounds[j - 1], maxBounds[j - 1], i, i + k)) {
                    counts[i][j]--;
                }

                // Add the axis entering the window
                if (isAxisActive(minBounds[j + k - 1], maxBounds[j + k - 1], i, i + k)) {
                    counts[i][j]++;
                }
            }
        }
        return counts;
    }

    /**
     * Checks if an axis's bounding box intersects with the vertical window [start, end).
     * An axis is considered "active" if it contains at least one 'B'.
     */
    private static boolean isAxisActive(int min, int max, int windowStart, int windowEnd) {
        return max >= min && max < windowEnd && min >= windowStart;
    }

    /**
     * Fast I/O helper using BufferedReader and StringTokenizer.
     * Replaces the original CharBuffer-based scanner with a standard, 
     * maintainable, and widely-accepted competitive programming pattern.
     */
    private static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) throw new NoSuchElementException();
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.*;
import java.util.*;

public class Solution {

    public static void main(String[] args) {
        // Use fast, standard I/O for competitive programming context
        FastScanner scanner = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out));
        try {
            solve(scanner, out);
        } finally {
            out.flush();
        }
    }

    private static void solve(FastScanner sc, PrintWriter out) {
        int n = sc.nextInt();
        int k = sc.nextInt();

        // Edge case: if window size exceeds grid dimensions, no 'B's can be fully covered
        if (k > n) {
            out.println(0);
            return;
        }

        char[][] grid = new char[n][n];
        for (int i = 0; i < n; i++) {
            grid[i] = sc.next().toCharArray();
        }

        // Compute prefix sums for horizontal k-length windows
        int[][] rowPrefix = computeHorizontalPrefixSums(grid, n, k);
        // Compute prefix sums for vertical k-length windows
        int[][] colPrefix = computeVerticalPrefixSums(grid, n, k);

        // Count completely empty rows and columns (they are always "covered")
        int emptyRows = countEmptyLines(grid, n, true);
        int emptyCols = countEmptyLines(grid, n, false);

        int maxCovered = emptyRows + emptyCols;

        // Slide the k x k window over the grid
        for (int r = 0; r <= n - k; r++) {
            for (int c = 0; c <= n - k; c++) {
                // Number of rows in [r, r+k-1] where horizontal window at c covers all 'B's
                int rowsCovered = rowPrefix[r + k - 1][c] - (r > 0 ? rowPrefix[r - 1][c] : 0);
                // Number of columns in [c, c+k-1] where vertical window at r covers all 'B's
                int colsCovered = colPrefix[c + k - 1][r] - (c > 0 ? colPrefix[c - 1][r] : 0);

                int currentCovered = rowsCovered + colsCovered + emptyRows + emptyCols;
                if (currentCovered > maxCovered) {
                    maxCovered = currentCovered;
                }
            }
        }

        out.println(maxCovered);
    }

    /**
     * Computes a 2D prefix sum array where prefix[i][j] represents the number of rows
     * from 0 to i where a horizontal window of length k starting at column j
     * completely covers all 'B' characters in that row.
     */
    private static int[][] computeHorizontalPrefixSums(char[][] grid, int n, int k) {
        int[][] prefix = new int[n][n - k + 1];
        int[] rowBCounts = new int[n];

        // Count total 'B's per row
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 'B') {
                    rowBCounts[i]++;
                }
            }
        }

        // Sliding window & prefix sum calculation
        for (int i = 0; i < n; i++) {
            int bInWindow = 0;
            // Initialize window for the first k columns
            for (int j = 0; j < k; j++) {
                if (grid[i][j] == 'B') {
                    bInWindow++;
                }
            }

            for (int j = 0; j < n - k + 1; j++) {
                // A window is "full" if it contains all 'B's in the row (and row isn't empty)
                boolean isFull = (rowBCounts[i] > 0 && bInWindow == rowBCounts[i]);
                prefix[i][j] = (i > 0 ? prefix[i - 1][j] : 0) + (isFull ? 1 : 0);

                // Slide window to the right
                if (j + k < n) {
                    if (grid[i][j] == 'B') bInWindow--;
                    if (grid[i][j + k] == 'B') bInWindow++;
                }
            }
        }
        return prefix;
    }

    /**
     * Computes a 2D prefix sum array where prefix[j][i] represents the number of columns
     * from 0 to j where a vertical window of length k starting at row i
     * completely covers all 'B' characters in that column.
     */
    private static int[][] computeVerticalPrefixSums(char[][] grid, int n, int k) {
        int[][] prefix = new int[n][n - k + 1];
        int[] colBCounts = new int[n];

        // Count total 'B's per column
        for (int j = 0; j < n; j++) {
            for (int i = 0; i < n; i++) {
                if (grid[i][j] == 'B') {
                    colBCounts[j]++;
                }
            }
        }

        // Sliding window & prefix sum calculation
        for (int j = 0; j < n; j++) {
            int bInWindow = 0;
            // Initialize window for the first k rows
            for (int i = 0; i < k; i++) {
                if (grid[i][j] == 'B') {
                    bInWindow++;
                }
            }

            for (int i = 0; i < n - k + 1; i++) {
                boolean isFull = (colBCounts[j] > 0 && bInWindow == colBCounts[j]);
                prefix[j][i] = (j > 0 ? prefix[j - 1][i] : 0) + (isFull ? 1 : 0);

                // Slide window downwards
                if (i + k < n) {
                    if (grid[i][j] == 'B') bInWindow--;
                    if (grid[i + k][j] == 'B') bInWindow++;
                }
            }
        }
        return prefix;
    }

    /**
     * Counts the number of completely empty rows or columns.
     */
    private static int countEmptyLines(char[][] grid, int n, boolean countRows) {
        int count = 0;
        for (int i = 0; i < n; i++) {
            boolean isEmpty = true;
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 'B') {
                    isEmpty = false;
                    break;
                }
            }
            if (isEmpty) count++;
        }
        return count;
    }

    /**
     * Fast I/O helper class using BufferedReader and StringTokenizer.
     * Replaces the error-prone custom InputReader from the original code.
     */
    static class FastScanner {
        private BufferedReader br;
        private StringTokenizer st;

        public FastScanner(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        public String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            String s = next();
            if (s == null) throw new NoSuchElementException();
            return Integer.parseInt(s);
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayList;
import java.util.Collections;
import java.util.StringTokenizer;

/**
 * Refactored solution for the Garland problem.
 * Improvements:
 * - Replaced custom I/O with standard BufferedReader/StringTokenizer for maintainability.
 * - Removed unused variables (mod, pos) and helper methods.
 * - Extracted logical steps into clearly named variables and blocks.
 * - Eliminated list mutation during iteration (using match counters instead of -1 markers).
 * - Added comprehensive comments explaining the algorithm.
 * - Followed Java naming conventions and best practices.
 */
public class Garland {

    public static void main(String[] args) throws IOException {
        FastScanner scanner = new FastScanner();
        int n = scanner.nextInt();
        int[] values = new int[n];
        boolean[] isPresent = new boolean[n + 1];

        // Read input and track present numbers
        for (int i = 0; i < n; i++) {
            values[i] = scanner.nextInt();
            if (values[i] != 0) {
                isPresent[values[i]] = true;
            }
        }

        // Edge case: single element
        if (n == 1) {
            System.out.println(0);
            return;
        }

        // Edge case: all zeros
        boolean allZeros = true;
        for (int v : values) {
            if (v != 0) {
                allZeros = false;
                break;
            }
        }
        if (allZeros) {
            System.out.println(1);
            return;
        }

        // Count missing even and odd numbers in range [1, n]
        int missingEvenCount = 0;
        int missingOddCount = 0;
        for (int i = 1; i <= n; i++) {
            if (!isPresent[i]) {
                if (i % 2 == 0) missingEvenCount++;
                else missingOddCount++;
            }
        }

        ArrayList<Integer> oddRequiredSegments = new ArrayList<>();
        ArrayList<Integer> evenRequiredSegments = new ArrayList<>();
        int totalZeroSegments = 0;

        // Identify zero segments and determine parity requirements
        for (int i = 0; i < n; ) {
            if (values[i] == 0) {
                totalZeroSegments++;
                int start = i;
                while (i < n && values[i] == 0) i++;
                int length = i - start;

                int leftVal = (start > 0) ? values[start - 1] : -1;
                int rightVal = (i < n) ? values[i] : -1;

                boolean leftOdd = (leftVal != -1 && leftVal % 2 != 0);
                boolean leftEven = (leftVal != -1 && leftVal % 2 == 0);
                boolean rightOdd = (rightVal != -1 && rightVal % 2 != 0);
                boolean rightEven = (rightVal != -1 && rightVal % 2 == 0);

                // Only middle segments (bounded by non-zeros on both sides) have fixed parity requirements
                if (leftVal != -1 && rightVal != -1) {
                    if (leftOdd && rightOdd) {
                        oddRequiredSegments.add(length);
                    } else if (leftEven && rightEven) {
                        evenRequiredSegments.add(length);
                    }
                }
                // Leading and trailing segments are flexible and handled separately
            } else {
                i++;
            }
        }

        // Sort lengths for greedy matching
        Collections.sort(oddRequiredSegments);
        Collections.sort(evenRequiredSegments);

        // Greedily match odd-required segments with available odd numbers
        int matchedOddSegments = 0;
        for (int len : oddRequiredSegments) {
            if (missingOddCount == 0) break;
            if (len <= missingOddCount) {
                missingOddCount -= len;
                totalZeroSegments--;
                matchedOddSegments++;
            }
        }

        // Greedily match even-required segments with available even numbers
        int matchedEvenSegments = 0;
        for (int len : evenRequiredSegments) {
            if (missingEvenCount == 0) break;
            if (len <= missingEvenCount) {
                missingEvenCount -= len;
                totalZeroSegments--;
                matchedEvenSegments++;
            }
        }

        // Handle leading zero segment
        if (values[0] == 0) {
            int i = 0;
            while (i < n && values[i] == 0) i++;
            int length = i;
            int rightVal = values[i];

            if (rightVal % 2 == 0) {
                if (missingEvenCount >= length) {
                    missingEvenCount -= length;
                } else {
                    missingOddCount -= (length - missingEvenCount);
                }
                totalZeroSegments--;
            } else {
                if (missingOddCount >= length) {
                    missingOddCount -= length;
                } else {
                    missingEvenCount -= (length - missingOddCount);
                }
                totalZeroSegments--;
            }
        }

        // Handle trailing zero segment
        if (values[n - 1] == 0) {
            int i = n - 1;
            while (i >= 0 && values[i] == 0) i--;
            int length = n - 1 - i;
            int leftVal = values[i];

            if (leftVal % 2 == 0) {
                if (missingEvenCount >= length) {
                    missingEvenCount -= length;
                } else {
                    missingOddCount -= (length - missingEvenCount);
                }
                totalZeroSegments--;
            } else {
                if (missingOddCount >= length) {
                    missingOddCount -= length;
                } else {
                    missingEvenCount -= (length - missingOddCount);
                }
                totalZeroSegments--;
            }
        }

        // Count parity mismatches between adjacent non-zero elements
        int parityFlips = 0;
        for (int i = 0; i < n - 1; i++) {
            if (values[i] != 0 && values[i + 1] != 0 && (values[i] % 2 != values[i + 1] % 2)) {
                parityFlips++;
            }
        }

        // Calculate final answer:
        // parityFlips: existing mismatches
        // (unmatchedOddSegments + unmatchedEvenSegments) * 2: each unassigned required segment costs 2
        // totalZeroSegments: remaining flexible segments cost 1 each
        int unmatchedOddSegments = oddRequiredSegments.size() - matchedOddSegments;
        int unmatchedEvenSegments = evenRequiredSegments.size() - matchedEvenSegments;
        int result = parityFlips + (unmatchedOddSegments + unmatchedEvenSegments) * 2 + totalZeroSegments;

        System.out.println(result);
    }

    /**
     * Fast I/O helper class using BufferedReader and StringTokenizer.
     * Replaces the custom Reader class for better maintainability and standard compliance.
     */
    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Solves the garland coloring problem using dynamic programming with memoization.
 * 
 * Problem Logic:
 * - We need to color a sequence of length n with 0s and 1s.
 * - The input pattern uses -1 for flexible positions, 0 for fixed evens, and 1 for fixed odds.
 * - Constraints: Total 0s <= n/2, Total 1s <= n/2 + (n % 2).
 * - Objective: Minimize adjacent color changes.
 */
public class GarlandColoringSolver {

    private static final int INF = Integer.MAX_VALUE / 2;

    // Memoization table: [current index][odds count][evens count][previous color]
    private int[][][][] memo;
    // Pattern array: -1 = flexible, 0 = must be 0, 1 = must be 1
    private int[] pattern;
    private int n;

    /**
     * Solves a single test case.
     * @param testCaseNumber Unused identifier for logging/debugging
     * @return Minimum number of adjacent color changes, or INF if impossible
     */
    public int solveTestCase(int testCaseNumber) {
        FastReader sc = new FastReader();
        n = sc.nextInt();

        if (n <= 0) {
            return 0;
        }

        pattern = new int[n + 1];
        int maxOdds = (n / 2) + (n % 2);
        int maxEvens = n / 2;

        // Initialize memoization table with -1
        memo = new int[n + 1][maxOdds + 1][maxEvens + 1][2];
        for (int[][][] layer1 : memo) {
            for (int[][] layer2 : layer1) {
                for (int[] layer3 : layer2) {
                    Arrays.fill(layer3, -1);
                }
            }
        }

        // Read input pattern
        for (int i = 1; i <= n; i++) {
            int x = sc.nextInt();
            // Map input: 0 -> flexible (-1), non-zero -> parity (0 or 1)
            pattern[i] = (x == 0) ? -1 : (x % 2);
        }

        int result;
        if (n == 1) {
            result = 0;
        } else {
            // Try starting with 1 (odd) or 0 (even) based on fixed constraints
            if (pattern[1] == -1) {
                result = Math.min(solveDP(2, 1, 0, 1), solveDP(2, 0, 1, 0));
            } else if (pattern[1] == 1) {
                result = solveDP(2, 1, 0, 1);
            } else {
                result = solveDP(2, 0, 1, 0);
            }
        }

        return result;
    }

    /**
     * Recursive DP with memoization to compute minimum changes.
     * @param currentIndex Current position in the garland (1-based)
     * @param oddsCount Number of 1s placed so far
     * @param evensCount Number of 0s placed so far
     * @param prevColor Color of the previous position (0 or 1)
     * @return Minimum changes from currentIndex to n
     */
    private int solveDP(int currentIndex, int oddsCount, int evensCount, int prevColor) {
        if (currentIndex > n) {
            return 0;
        }

        if (memo[currentIndex][oddsCount][evensCount][prevColor] != -1) {
            return memo[currentIndex][oddsCount][evensCount][prevColor];
        }

        int minChanges = INF;
        int maxOdds = (n / 2) + (n % 2);
        int maxEvens = n / 2;
        int currentConstraint = pattern[currentIndex];

        if (currentConstraint == -1) {
            // Flexible position: try placing 1
            if (oddsCount < maxOdds) {
                int cost = (prevColor != 1 ? 1 : 0);
                minChanges = Math.min(minChanges, cost + solveDP(currentIndex + 1, oddsCount + 1, evensCount, 1));
            }
            // Try placing 0
            if (evensCount < maxEvens) {
                int cost = (prevColor != 0 ? 1 : 0);
                minChanges = Math.min(minChanges, cost + solveDP(currentIndex + 1, oddsCount, evensCount + 1, 0));
            }
        } else if (currentConstraint == 0) {
            // Must be 0 (even)
            if (evensCount < maxEvens) {
                int cost = (prevColor != 0 ? 1 : 0);
                minChanges = Math.min(minChanges, cost + solveDP(currentIndex + 1, oddsCount, evensCount + 1, 0));
            }
        } else {
            // currentConstraint == 1: Must be 1 (odd)
            if (oddsCount < maxOdds) {
                int cost = (prevColor != 1 ? 1 : 0);
                minChanges = Math.min(minChanges, cost + solveDP(currentIndex + 1, oddsCount + 1, evensCount, 1));
            }
        }

        memo[currentIndex][oddsCount][evensCount][prevColor] = minChanges;
        return minChanges;
    }

    public static void main(String[] args) {
        GarlandColoringSolver solver = new GarlandColoringSolver();
        FastReader sc = new FastReader();
        PrintWriter out = new PrintWriter(System.out);

        int t = 1; // Hardcoded as per original implementation
        long startTime = System.currentTimeMillis();

        for (int i = 1; i <= t; i++) {
            out.println(solver.solveTestCase(i));
        }

        out.flush();
        System.err.println((System.currentTimeMillis() - startTime) + "ms");
    }

    /**
     * Fast I/O utility for competitive programming scenarios.
     */
    static class FastReader {
        private BufferedReader br;
        private StringTokenizer st;

        public FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            String s = next();
            return s == null ? 0 : Integer.parseInt(s);
        }

        long nextLong() {
            String s = next();
            return s == null ? 0L : Long.parseLong(s);
        }

        double nextDouble() {
            String s = next();
            return s == null ? 0.0 : Double.parseDouble(s);
        }

        String nextLine() {
            String str = "";
            try {
                str = br.readLine();
            } catch (IOException e) {
                throw new RuntimeException(e);
            }
            return str;
        }
    }
}

import java.util.Arrays;
import java.util.Scanner;

/**
 * Solves a dynamic programming problem to minimize parity changes
 * while ensuring a specific distribution of even and odd numbers.
 */
public class Solution {

    // Constants for the 'last' state parameter to replace magic numbers
    private static final int STATE_INITIAL = 2;
    private static final int PARITY_EVEN = 0;
    private static final int PARITY_ODD = 1;

    // Memoization table: dp[remainingOdds][remainingEvens][position][lastParity]
    private static int[][][][] dp;

    public static void main(String[] args) {
        // Use try-with-resources to automatically close the Scanner
        try (Scanner scanner = new Scanner(System.in)) {
            if (!scanner.hasNextInt()) {
                return;
            }

            int n = scanner.nextInt();
            int[] arr = new int[n];
            int currentOdds = 0;
            int currentEvens = 0;

            // Read input and count existing non-zero odds/evens
            for (int i = 0; i < n; i++) {
                arr[i] = scanner.nextInt();
                if (arr[i] != 0) {
                    if (Math.abs(arr[i]) % 2 != 0) {
                        currentOdds++;
                    } else {
                        currentEvens++;
                    }
                }
            }

            // Calculate how many more odds/evens are needed to balance the array
            int remainingOdds, remainingEvens;
            if (n % 2 == 0) {
                remainingOdds = (n / 2) - currentOdds;
                remainingEvens = (n / 2) - currentEvens;
            } else {
                // Odd length: requires one more odd than even
                remainingOdds = ((n / 2) + 1) - currentOdds;
                remainingEvens = (n / 2) - currentEvens;
            }

            // Initialize DP table with -1 (uncomputed state)
            initializeDpTable(remainingOdds, remainingEvens, n);

            // Compute and print the result
            int result = solve(remainingOdds, remainingEvens, 0, STATE_INITIAL, arr);
            System.out.println(result);
        }
    }

    /**
     * Fills the 4D DP array with -1 to indicate uncomputed states.
     */
    private static void initializeDpTable(int o, int e, int n) {
        dp = new int[o + 1][e + 1][n][3];
        for (int i = 0; i <= o; i++) {
            for (int j = 0; j <= e; j++) {
                for (int k = 0; k < n; k++) {
                    Arrays.fill(dp[i][j][k], -1);
                }
            }
        }
    }

    /**
     * Recursive DP function with memoization to find the minimum cost.
     *
     * @param o   Remaining odd numbers to place
     * @param e   Remaining even numbers to place
     * @param pos Current index in the array
     * @param last Parity of the previously placed number (0=even, 1=odd, 2=initial)
     * @param arr The input array
     * @return Minimum cost to complete the array
     */
    private static int solve(int o, int e, int pos, int last, int[] arr) {
        // Base case: reached end of array
        if (pos == arr.length) {
            return 0;
        }

        // Return memoized result if available
        if (dp[o][e][pos][last] != -1) {
            return dp[o][e][pos][last];
        }

        int minCost = Integer.MAX_VALUE;

        // Determine which parities can be placed at the current position.
        // If arr[pos] is 0, we can choose either even or odd.
        // Otherwise, the parity is fixed by the existing number.
        int[] possibleParities = (arr[pos] == 0) 
                ? new int[]{PARITY_EVEN, PARITY_ODD} 
                : new int[]{Math.abs(arr[pos]) % 2};

        for (int parity : possibleParities) {
            if (parity == PARITY_EVEN && e > 0) {
                int cost = (last != STATE_INITIAL && last != PARITY_EVEN) ? 1 : 0;
                minCost = Math.min(minCost, cost + solve(o, e - 1, pos + 1, PARITY_EVEN, arr));
            } else if (parity == PARITY_ODD && o > 0) {
                int cost = (last != STATE_INITIAL && last != PARITY_ODD) ? 1 : 0;
                minCost = Math.min(minCost, cost + solve(o - 1, e, pos + 1, PARITY_ODD, arr));
            }
        }

        // Store and return the result
        return dp[o][e][pos][last] = minCost;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.StringTokenizer;

/**
 * A refactored version of the Gap Calculator program.
 * Improvements include:
 * - Descriptive class and variable names.
 * - Use of Try-with-resources for safe resource management.
 * - Extraction of logic into clear blocks for readability.
 * - Removal of magic numbers (using NO_NEIGHBOR constant).
 * - Use of ArrayList for dynamic gap storage.
 */
public class GapCalculator {

    /**
     * Represents a sequence of zeros (a gap) in the array.
     */
    private static class Gap implements Comparable<Gap> {
        final int size;
        final int leftNeighbor;
        final int rightNeighbor;
        boolean filled;

        public Gap(int size, int leftNeighbor, int rightNeighbor) {
            this.size = size;
            this.leftNeighbor = leftNeighbor;
            this.rightNeighbor = rightNeighbor;
            this.filled = false;
        }

        @Override
        public int compareTo(Gap other) {
            return Integer.compare(this.size, other.size);
        }
    }

    private static final int NO_NEIGHBOR = -1;

    public static void main(String[] args) throws IOException {
        // Use try-with-resources for automatic resource management
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            String line = br.readLine();
            if (line == null) return;

            int n = Integer.parseInt(line.trim());
            int[] array = new int[n];

            String numbersLine = br.readLine();
            if (numbersLine != null) {
                StringTokenizer st = new StringTokenizer(numbersLine);
                for (int i = 0; i < n; i++) {
                    if (st.hasMoreTokens()) {
                        array[i] = Integer.parseInt(st.nextToken());
                    }
                }
            }

            // Identify present numbers and count missing odds/evens
            boolean[] present = new boolean[n + 1];
            int missingOddCount = 0;
            int missingEvenCount = 0;

            for (int val : array) {
                if (val != 0) {
                    present[val] = true;
                }
            }

            for (int i = 1; i <= n; i++) {
                if (!present[i]) {
                    if (i % 2 == 0) {
                        missingEvenCount++;
                    } else {
                        missingOddCount++;
                    }
                }
            }

            // Identify gaps (sequences of zeros)
            List<Gap> gaps = new ArrayList<>();
            int i = 0;
            while (i < n) {
                if (array[i] == 0) {
                    int start = i;
                    // Count consecutive zeros
                    while (i < n && array[i] == 0) {
                        i++;
                    }
                    int gapSize = i - start;

                    // Determine neighbors
                    int left = (start > 0) ? array[start - 1] : NO_NEIGHBOR;
                    int right = (i < n) ? array[i] : NO_NEIGHBOR;

                    gaps.add(new Gap(gapSize, left, right));
                } else {
                    i++;
                }
            }

            // Sort gaps by size (ascending)
            Collections.sort(gaps);

            // Phase 1: Try to fill gaps with missing numbers
            for (Gap gap : gaps) {
                if (gap.filled) {
                    continue;
                }

                boolean needsEven = false;
                boolean needsOdd = false;

                if (gap.leftNeighbor != NO_NEIGHBOR && gap.rightNeighbor != NO_NEIGHBOR) {
                    // Internal Gap
                    if (gap.leftNeighbor % 2 == 0 && gap.rightNeighbor % 2 == 0) {
                        needsEven = true;
                    } else if (gap.leftNeighbor % 2 != 0 && gap.rightNeighbor % 2 != 0) {
                        needsOdd = true;
                    }
                    // If parities differ, the gap cannot be filled with a single parity number
                    // based on the original logic constraints.
                } else if (gap.leftNeighbor == NO_NEIGHBOR) {
                    // Start of Array
                    if (gap.rightNeighbor % 2 == 0) {
                        needsEven = true;
                    } else {
                        needsOdd = true;
                    }
                } else if (gap.rightNeighbor == NO_NEIGHBOR) {
                    // End of Array
                    if (gap.leftNeighbor % 2 != 0) {
                        needsOdd = true;
                    } else {
                        needsEven = true;
                    }
                }

                // Attempt to fill
                if (needsEven && missingEvenCount >= gap.size) {
                    missingEvenCount -= gap.size;
                    gap.filled = true;
                } else if (needsOdd && missingOddCount >= gap.size) {
                    missingOddCount -= gap.size;
                    gap.filled = true;
                }
            }

            // Phase 2: Calculate answer based on unfilled gaps
            int ans = 0;
            for (Gap gap : gaps) {
                if (!gap.filled) {
                    if (gap.leftNeighbor != NO_NEIGHBOR && gap.rightNeighbor != NO_NEIGHBOR) {
                        // Internal Gap
                        if (gap.leftNeighbor % 2 != gap.rightNeighbor % 2) {
                            ans++; // Different parity neighbors
                        } else {
                            ans += 2; // Same parity neighbors
                        }
                    } else {
                        // Boundary Gap
                        ans++;
                    }
                }
            }

            // Phase 3: Count parity mismatches in the original array
            for (int k = 0; k < n - 1; k++) {
                if (array[k] != 0 && array[k + 1] != 0) {
                    if (array[k] % 2 != array[k + 1] % 2) {
                        ans++;
                    }
                }
            }

            System.out.println(ans);
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.Arrays;
import java.util.HashSet;
import java.util.Set;
import java.util.StringTokenizer;

/**
 * Solves the minimum parity transition problem by filling zero placeholders
 * with missing numbers from 1 to n to minimize adjacent parity changes.
 */
public class AlternatingParitySolver {

    private final int[] arr;
    private final int n;
    // DP state: [currentIndex][remainingOddCount][lastWasOdd]
    // lastWasOdd is stored as 0 (false) or 1 (true) for array indexing
    private final int[][][] memo;

    /**
     * Initializes the solver with the input array.
     *
     * @param arr the array containing fixed numbers and 0s to be filled
     */
    public AlternatingParitySolver(int[] arr) {
        this.arr = arr;
        this.n = arr.length;
        this.memo = new int[n + 1][n + 1][2];
        initializeMemo();
    }

    /**
     * Fills the memoization table with -1 to indicate uncomputed states.
     */
    private void initializeMemo() {
        for (int[][] layer : memo) {
            for (int[] row : layer) {
                Arrays.fill(row, -1);
            }
        }
    }

    /**
     * Computes and returns the minimum number of parity transitions required.
     *
     * @return minimum transitions count
     */
    public int solve() {
        Set<Integer> usedNumbers = new HashSet<>();
        for (int val : arr) {
            if (val != 0) {
                usedNumbers.add(val);
            }
        }

        int oddCount = 0;
        // evenCount is implicitly derived: (n - currentIndex) - oddCount
        for (int i = 1; i <= n; i++) {
            if (!usedNumbers.contains(i) && (i & 1) == 1) {
                oddCount++;
            }
        }

        // lastWasOdd is initially true. The first element (index 0) skips the 
        // transition check, so the initial value doesn't affect the result.
        return computeMinTransitions(0, oddCount, true);
    }

    /**
     * Recursive DP function with memoization to find the minimum transitions.
     *
     * @param currentIndex      current position in the array being filled
     * @param remainingOddCount number of odd values still available to place
     * @param lastWasOdd        parity of the element at currentIndex - 1
     * @return minimum transitions from this state to the end
     */
    private int computeMinTransitions(int currentIndex, int remainingOddCount, boolean lastWasOdd) {
        if (currentIndex == n) {
            return 0;
        }

        // Base case: no numbers left to place. All remaining positions are fixed.
        if (remainingOddCount == 0) {
            int transitions = 0;
            for (int i = currentIndex; i < n - 1; i++) {
                if (isOdd(arr[i]) != isOdd(arr[i + 1])) {
                    transitions++;
                }
            }
            if (currentIndex > 0 && isOdd(arr[currentIndex]) != lastWasOdd) {
                transitions++;
            }
            memo[currentIndex][remainingOddCount][lastWasOdd ? 1 : 0] = transitions;
            return transitions;
        }

        if (memo[currentIndex][remainingOddCount][lastWasOdd ? 1 : 0] != -1) {
            return memo[currentIndex][remainingOddCount][lastWasOdd ? 1 : 0];
        }

        int result;
        if (arr[currentIndex] != 0) {
            // Position is already fixed
            boolean curIsOdd = isOdd(arr[currentIndex]);
            result = computeMinTransitions(currentIndex + 1, remainingOddCount, curIsOdd);
            if (currentIndex > 0 && isOdd(arr[currentIndex]) != lastWasOdd) {
                result++;
            }
        } else {
            // Position is empty (0). Try placing an odd or even number.
            int minResult = Integer.MAX_VALUE;

            // Option 1: Place an odd number
            if (remainingOddCount > 0) {
                int res = computeMinTransitions(currentIndex + 1, remainingOddCount - 1, true);
                if (currentIndex > 0 && !lastWasOdd) {
                    res++;
                }
                minResult = Math.min(minResult, res);
            }

            // Option 2: Place an even number
            // Remaining even count = total remaining slots - remaining odd count
            int remainingEvenCount = (n - currentIndex) - remainingOddCount;
            if (remainingEvenCount > 0) {
                int res = computeMinTransitions(currentIndex + 1, remainingOddCount, false);
                if (currentIndex > 0 && lastWasOdd) {
                    res++;
                }
                minResult = Math.min(minResult, res);
            }

            result = minResult;
        }

        memo[currentIndex][remainingOddCount][lastWasOdd ? 1 : 0] = result;
        return result;
    }

    /**
     * Checks if a number is odd using bitwise operation.
     */
    private boolean isOdd(int num) {
        return (num & 1) == 1;
    }

    /**
     * Fast I/O helper to handle large inputs efficiently.
     */
    private static class FastReader {
        private final BufferedReader br;
        private StringTokenizer tokenizer;

        public FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) {
                    throw new IOException("Unexpected end of input");
                }
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }

    public static void main(String[] args) throws IOException {
        FastReader reader = new FastReader();
        int n = reader.nextInt();
        int[] arr = new int[n];
        for (int i = 0; i < n; i++) {
            arr[i] = reader.nextInt();
        }
        System.out.println(new AlternatingParitySolver(arr).solve());
    }
}

import java.util.Scanner;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.List;
import java.io.PrintWriter;
import java.io.IOException;

/**
 * Refactored solution for array parity problem.
 * 
 * This version improves maintainability by:
 * 1. Replacing the custom fast I/O with standard Scanner (for readability).
 * 2. Removing unused imports and variables (e.g., mod).
 * 3. Renaming variables and classes to be descriptive (e.g., GapSegment, evenBudget).
 * 4. Structuring the logic into clear, readable blocks.
 * 5. Adding comments to explain the algorithm steps.
 */
public class ArrayAlternator {

    /**
     * Represents a gap of zeros between two numbers of the same parity.
     */
    private static class GapSegment {
        final int gapLength;
        final int startIndex;
        final int endIndex;

        public GapSegment(int gapLength, int startIndex, int endIndex) {
            this.gapLength = gapLength;
            this.startIndex = startIndex;
            this.endIndex = endIndex;
        }
    }

    public static void main(String[] args) throws IOException {
        // Using Scanner for readability. 
        // For competitive programming with very large inputs, 
        // BufferedReader/StringTokenizer is preferred for performance.
        Scanner scanner = new Scanner(System.in);
        PrintWriter out = new PrintWriter(System.out);

        if (scanner.hasNextInt()) {
            int n = scanner.nextInt();

            // Array size n+2 to handle 1-based indexing and boundary padding (indices 0 and n+1)
            int[] arr = new int[n + 2];

            // Budgets for converting zeros to evens or odds.
            // Initialized to theoretical maximum counts, decremented as actual numbers are found.
            // This logic tracks how many zeros can be converted to match a specific parity.
            int evenBudget = n / 2;
            int oddBudget = (n + 1) / 2;

            // Read input array
            for (int i = 1; i <= n; i++) {
                if (scanner.hasNextInt()) {
                    arr[i] = scanner.nextInt();
                    if (arr[i] != 0) {
                        if (arr[i] % 2 == 0) {
                            evenBudget--;
                        } else {
                            oddBudget--;
                        }
                    }
                }
            }

            // Find the first and last non-zero indices
            int firstNonZeroIdx = 0;
            int lastNonZeroIdx = 0;

            for (int i = 1; i <= n; i++) {
                if (arr[i] != 0) {
                    firstNonZeroIdx = i;
                    break;
                }
            }
            for (int i = n; i >= 1; i--) {
                if (arr[i] != 0) {
                    lastNonZeroIdx = i;
                    break;
                }
            }

            // Edge case: Array contains only zeros
            if (firstNonZeroIdx == 0 && lastNonZeroIdx == 0) {
                out.println(n > 1 ? 1 : 0);
            } else {
                int operations = 0;
                int lastProcessedIdx = firstNonZeroIdx;
                List<GapSegment> gaps = new ArrayList<>();

                // Iterate through the array from the first non-zero to the last non-zero
                for (int i = firstNonZeroIdx + 1; i <= lastNonZeroIdx; i++) {
                    if (arr[i] == 0) continue;

                    boolean isAdjacent = (lastProcessedIdx == i - 1);

                    if (isAdjacent) {
                        // If adjacent, check if parity changes
                        if (arr[i] % 2 != arr[lastProcessedIdx] % 2) {
                            operations++;
                        }
                        lastProcessedIdx = i;
                    } else {
                        // Not adjacent (separated by zeros)
                        boolean sameParity = (arr[i] % 2 == arr[lastProcessedIdx] % 2);

                        if (sameParity) {
                            // Record the gap of zeros between them
                            int gapSize = i - lastProcessedIdx - 1;
                            gaps.add(new GapSegment(gapSize, lastProcessedIdx, i));
                            lastProcessedIdx = i;
                        } else {
                            // Different parity across a gap
                            operations++;
                            lastProcessedIdx = i;
                        }
                    }
                }

                // Sort gaps by size (greedy strategy: handle smaller gaps first)
                Collections.sort(gaps, Comparator.comparingInt(g -> g.gapLength));

                // Process gaps
                for (GapSegment gap : gaps) {
                    int start = gap.startIndex;
                    int end = gap.endIndex;
                    int size = gap.gapLength;

                    // Determine which budget to use based on the parity of the numbers surrounding the gap
                    // Both numbers at start and end have the same parity.
                    boolean isEven = (arr[start] % 2 == 0);

                    if (isEven) {
                        if (evenBudget >= size) {
                            evenBudget -= size;
                        } else {
                            // Insufficient budget
                            // Cost logic: 2 for internal gaps, 1 for boundary gaps
                            // Note: In this logic flow, gaps are strictly internal (indices 1..n),
                            // so the condition (start != 0 && end != n + 1) is always true.
                            if (start != 0 && end != n + 1) {
                                operations += 2;
                            } else {
                                operations++;
                            }
                        }
                    } else {
                        if (oddBudget >= size) {
                            oddBudget -= size;
                        } else {
                            if (start != 0 && end != n + 1) {
                                operations += 2;
                            } else {
                                operations++;
                            }
                        }
                    }
                }

                // Handle Prefix (zeros before the first non-zero number)
                if (firstNonZeroIdx != 1) {
                    int prefixLength = firstNonZeroIdx - 1;
                    boolean firstNumIsEven = (arr[firstNonZeroIdx] % 2 == 0);

                    if (firstNumIsEven) {
                        if (evenBudget < prefixLength) {
                            operations++;
                        } else {
                            evenBudget -= prefixLength;
                        }
                    } else {
                        if (oddBudget < prefixLength) {
                            operations++;
                        } else {
                            oddBudget -= prefixLength;
                        }
                    }
                }

                // Handle Suffix (zeros after the last non-zero number)
                if (lastNonZeroIdx != n) {
                    int suffixLength = n - lastNonZeroIdx;
                    boolean lastNumIsEven = (arr[lastNonZeroIdx] % 2 == 0);

                    if (lastNumIsEven) {
                        if (evenBudget < suffixLength) {
                            operations++;
                        } else {
                            evenBudget -= suffixLength;
                        }
                    } else {
                        if (oddBudget < suffixLength) {
                            operations++;
                        } else {
                            oddBudget -= suffixLength;
                        }
                    }
                }

                out.println(operations);
            }
        }

        out.flush();
        scanner.close();
    }
}

import java.io.*;
import java.util.*;

/**
 * Refactored solution for Day9.
 * 
 * Key Improvements:
 * 1. Fixed compilation error: TreeSet does not have pollFirst(). Replaced with PriorityQueue.
 * 2. Extracted complex logic into single-responsibility methods.
 * 3. Renamed cryptic identifiers (nech/chet -> availableOdds/availableEvens).
 * 4. Replaced generic 'pair' class with semantically named 'IndexRange'.
 * 5. Added JavaDoc, consistent formatting, and robust resource management.
 * 6. Simplified nested conditionals while preserving original algorithmic behavior.
 */
public class Day9 {

    /**
     * Represents a contiguous range of indices [start, end) in the array.
     * Used to identify segments of zeros bounded by non-zero numbers.
     */
    private static class IndexRange implements Comparable<IndexRange> {
        final int start;
        final int end;

        public IndexRange(int start, int end) {
            this.start = start;
            this.end = end;
        }

        public int length() {
            return end - start - 1;
        }

        @Override
        public int compareTo(IndexRange other) {
            // Sort by segment length in ascending order to match original behavior
            return Integer.compare(this.length(), other.length());
        }
    }

    public static void main(String[] args) throws IOException {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter writer = new PrintWriter(System.out);

        try {
            String line = reader.readLine();
            if (line == null || line.trim().isEmpty()) return;

            int n = Integer.parseInt(line.trim());
            int[] array = new int[n];

            PriorityQueue<Integer> availableOdds = new PriorityQueue<>();
            PriorityQueue<Integer> availableEvens = new PriorityQueue<>();

            initializeAvailableNumbers(n, availableOdds, availableEvens);
            readArrayAndRemoveUsedNumbers(reader, array, availableOdds, availableEvens);

            // Fill segments bounded by even numbers
            fillBoundedSegments(array, availableEvens, true);

            // Fill segments bounded by odd numbers
            fillBoundedSegments(array, availableOdds, false);

            // Handle leading and trailing zeros
            fillPrefixZeros(array, availableEvens, availableOdds);
            fillSuffixZeros(array, availableEvens, availableOdds);

            // Fill any remaining zeros based on neighbor parity
            fillRemainingZeros(array, availableEvens, availableOdds);

            // Count and output parity changes
            int parityChanges = countParityChanges(array);
            writer.println(parityChanges);
        } finally {
            writer.flush();
            reader.close();
        }
    }

    private static void initializeAvailableNumbers(int n, PriorityQueue<Integer> odds, PriorityQueue<Integer> evens) {
        for (int i = 1; i <= n; i++) {
            if (i % 2 != 0) {
                odds.add(i);
            } else {
                evens.add(i);
            }
        }
    }

    private static void readArrayAndRemoveUsedNumbers(BufferedReader reader, int[] array,
                                                      PriorityQueue<Integer> odds, PriorityQueue<Integer> evens) throws IOException {
        StringTokenizer st = new StringTokenizer(reader.readLine());
        for (int i = 0; i < array.length; i++) {
            array[i] = Integer.parseInt(st.nextToken());
            odds.remove(array[i]);
            evens.remove(array[i]);
        }
    }

    /**
     * Fills zero-segments bounded by numbers of a specific parity.
     * Segments are processed from smallest to largest to maintain original behavior.
     */
    private static void fillBoundedSegments(int[] array, PriorityQueue<Integer> availableNumbers, boolean isEven) {
        List<IndexRange> segments = new ArrayList<>();
        int lastFilledIndex = -1;

        for (int i = 0; i < array.length; i++) {
            int val = array[i];
            boolean isCurrentEven = (val != 0 && val % 2 == 0);
            boolean isCurrentOdd = (val % 2 == 1); // 0 % 2 == 0, so safely skips empty slots

            if (isCurrentEven) {
                if (lastFilledIndex != -1) {
                    segments.add(new IndexRange(lastFilledIndex, i));
                }
                lastFilledIndex = i;
            } else if (isCurrentOdd) {
                lastFilledIndex = -1;
            }
        }

        Collections.sort(segments);
        for (IndexRange seg : segments) {
            if (availableNumbers.size() < seg.length()) {
                break;
            }
            for (int j = seg.start + 1; j < seg.end; j++) {
                array[j] = availableNumbers.poll();
            }
        }
    }

    private static void fillPrefixZeros(int[] array, PriorityQueue<Integer> evens, PriorityQueue<Integer> odds) {
        int firstNonZeroIndex = -1;
        for (int i = 0; i < array.length; i++) {
            if (array[i] != 0) {
                firstNonZeroIndex = i;
                break;
            }
        }

        if (firstNonZeroIndex == -1) return; // Array contains only zeros

        int prefixLength = firstNonZeroIndex;
        int firstNonZeroVal = array[firstNonZeroIndex];

        if (firstNonZeroVal % 2 == 0) {
            if (evens.size() >= prefixLength) {
                for (int i = 0; i < prefixLength; i++) {
                    array[i] = evens.poll();
                }
            }
        } else {
            if (odds.size() >= prefixLength) {
                for (int i = 0; i < prefixLength; i++) {
                    array[i] = odds.poll();
                }
            }
        }
    }

    private static void fillSuffixZeros(int[] array, PriorityQueue<Integer> evens, PriorityQueue<Integer> odds) {
        int lastNonZeroIndex = -1;
        for (int i = array.length - 1; i >= 0; i--) {
            if (array[i] != 0) {
                lastNonZeroIndex = i;
                break;
            }
        }

        if (lastNonZeroIndex == -1) return; // Array contains only zeros

        int suffixLength = array.length - 1 - lastNonZeroIndex;
        int lastNonZeroVal = array[lastNonZeroIndex];

        if (lastNonZeroVal % 2 == 0) {
            if (evens.size() >= suffixLength) {
                for (int i = array.length - 1; i > lastNonZeroIndex; i--) {
                    array[i] = evens.poll();
                }
            }
        } else {
            if (odds.size() >= suffixLength) {
                for (int i = array.length - 1; i > lastNonZeroIndex; i--) {
                    array[i] = odds.poll();
                }
            }
        }
    }

    /**
     * Fills remaining zeros by checking left and right neighbors.
     * Prefers matching parity with neighbors, falls back to the other set if needed.
     */
    private static void fillRemainingZeros(int[] array, PriorityQueue<Integer> evens, PriorityQueue<Integer> odds) {
        while (!evens.isEmpty() || !odds.isEmpty()) {
            for (int i = 0; i < array.length; i++) {
                if (array[i] == 0) {
                    // Try filling from left neighbor
                    if (i > 0 && array[i - 1] != 0) {
                        int left = array[i - 1];
                        if (left % 2 == 1) {
                            if (!odds.isEmpty()) array[i] = odds.poll();
                            else if (!evens.isEmpty()) array[i] = evens.poll();
                        } else {
                            if (!evens.isEmpty()) array[i] = evens.poll();
                            else if (!odds.isEmpty()) array[i] = odds.poll();
                        }
                    }

                    // Try filling from right neighbor if still empty
                    if (array[i] == 0 && i < array.length - 1 && array[i + 1] != 0) {
                        int right = array[i + 1];
                        if (right % 2 == 1) {
                            if (!odds.isEmpty()) array[i] = odds.poll();
                            else if (!evens.isEmpty()) array[i] = evens.poll();
                        } else {
                            if (!evens.isEmpty()) array[i] = evens.poll();
                            else if (!odds.isEmpty()) array[i] = odds.poll();
                        }
                    }
                }
            }
        }
    }

    private static int countParityChanges(int[] array) {
        int changes = 0;
        for (int i = 0; i < array.length - 1; i++) {
            if (array[i] % 2 != array[i + 1] % 2) {
                changes++;
            }
        }
        return changes;
    }
}

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Scanner;

public class Main {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        if (!scanner.hasNextInt()) {
            return;
        }

        int n = scanner.nextInt();
        int[] numbers = new int[n];
        for (int i = 0; i < n; i++) {
            numbers[i] = scanner.nextInt();
        }

        int result = calculateMinimumOperations(numbers);
        System.out.println(result);
        scanner.close();
    }

    /**
     * Calculates the minimum number of operations required to satisfy the alternating 
     * even/odd parity constraint across the array, treating 0 as a wildcard.
     *
     * @param numbers the input array
     * @return the minimum number of operations
     */
    private static int calculateMinimumOperations(int[] numbers) {
        int n = numbers.length;
        int evenSlots = n / 2;
        int oddSlots = n - evenSlots;

        // Count how many even/odd slots are still available after placing non-zero numbers
        for (int num : numbers) {
            if (num != 0) {
                if (num % 2 == 0) {
                    evenSlots--;
                } else {
                    oddSlots--;
                }
            }
        }

        List<Integer> evenSegmentLengths = new ArrayList<>();
        List<Integer> oddSegmentLengths = new ArrayList<>();
        List<Integer> prefixEvenLengths = new ArrayList<>();
        List<Integer> prefixOddLengths = new ArrayList<>();

        int operations = 0;
        boolean inZeroSegment = false;
        int lastNonZeroIndex = -1;

        for (int i = 0; i < n; i++) {
            if (numbers[i] == 0 && !inZeroSegment) {
                inZeroSegment = true;
                lastNonZeroIndex = i - 1;
            } else if (numbers[i] == 0 && inZeroSegment) {
                continue;
            } else if (inZeroSegment) {
                inZeroSegment = false;
                if (lastNonZeroIndex == -1) {
                    // Segment at the beginning of the array
                    if (numbers[i] % 2 == 0) {
                        prefixEvenLengths.add(i);
                    } else {
                        prefixOddLengths.add(i);
                    }
                    continue;
                }

                int segmentLength = i - lastNonZeroIndex - 1;
                int currentParity = numbers[i] % 2;
                int previousParity = numbers[lastNonZeroIndex] % 2;

                if (currentParity == 0 && previousParity == 0) {
                    evenSegmentLengths.add(segmentLength);
                } else if (currentParity != 0 && previousParity != 0) {
                    oddSegmentLengths.add(segmentLength);
                } else {
                    // Mixed parity segment requires an operation
                    operations++;
                }
            } else {
                // Check adjacent parity mismatch
                if (i > 0 && (numbers[i] % 2 != numbers[i - 1] % 2)) {
                    operations++;
                }
            }
        }

        // Handle trailing zero segment
        if (inZeroSegment) {
            if (lastNonZeroIndex < 0) {
                // Entire array consists of zeros
                return n > 1 ? 1 : 0;
            } else {
                int suffixLength = n - lastNonZeroIndex - 1;
                if (numbers[lastNonZeroIndex] % 2 == 0) {
                    prefixEvenLengths.add(suffixLength);
                } else {
                    prefixOddLengths.add(suffixLength);
                }
            }
        }

        // Sort segments to apply greedy strategy
        Collections.sort(evenSegmentLengths);
        Collections.sort(oddSegmentLengths);
        Collections.sort(prefixEvenLengths);
        Collections.sort(prefixOddLengths);

        int prefixEvenIndex = 0;
        int prefixOddIndex = 0;

        // Process even segments
        for (int len : evenSegmentLengths) {
            if (len <= evenSlots) {
                evenSlots -= len;
            } else {
                operations += 2;
            }
        }
        // Process up to two prefix/suffix even segments
        if (prefixEvenIndex < prefixEvenLengths.size()) {
            if (prefixEvenLengths.get(prefixEvenIndex) <= evenSlots) {
                evenSlots -= prefixEvenLengths.get(prefixEvenIndex);
            } else {
                operations += 1;
            }
            prefixEvenIndex++;
        }
        if (prefixEvenIndex < prefixEvenLengths.size()) {
            if (prefixEvenLengths.get(prefixEvenIndex) <= evenSlots) {
                evenSlots -= prefixEvenLengths.get(prefixEvenIndex);
            } else {
                operations += 1;
            }
            prefixEvenIndex++;
        }

        // Process odd segments
        for (int len : oddSegmentLengths) {
            if (len <= oddSlots) {
                oddSlots -= len;
            } else {
                operations += 2;
            }
        }
        // Process up to two prefix/suffix odd segments
        if (prefixOddIndex < prefixOddLengths.size()) {
            if (prefixOddLengths.get(prefixOddIndex) <= oddSlots) {
                oddSlots -= prefixOddLengths.get(prefixOddIndex);
            } else {
                operations += 1;
            }
            prefixOddIndex++;
        }
        if (prefixOddIndex < prefixOddLengths.size()) {
            if (prefixOddLengths.get(prefixOddIndex) <= oddSlots) {
                oddSlots -= prefixOddLengths.get(prefixOddIndex);
            } else {
                operations += 1;
            }
            prefixOddIndex++;
        }

        return operations;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

/**
 * Optimizes parity transitions in an array by strategically filling zero placeholders.
 * Uses dynamic programming to minimize additional transitions while respecting
 * global constraints on the total number of even and odd values.
 */
public class ParityTransitionOptimizer {

    public static void main(String[] args) throws IOException {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        String line = reader.readLine();
        if (line == null || line.trim().isEmpty()) {
            return;
        }

        int n = Integer.parseInt(line.trim());
        int[] arr = new int[n];

        String arrayLine = reader.readLine();
        if (arrayLine != null) {
            StringTokenizer st = new StringTokenizer(arrayLine);
            for (int i = 0; i < n; i++) {
                if (st.hasMoreTokens()) {
                    arr[i] = Integer.parseInt(st.nextToken());
                }
            }
        }

        int initialTransitions = calculateInitialTransitions(arr, n);
        int[] availableSlots = calculateAvailableSlots(arr, n);
        int maxEven = availableSlots[0];
        int maxOdd = availableSlots[1];

        int firstNonZeroIndex = findFirstNonZero(arr, n);
        if (firstNonZeroIndex == -1) {
            System.out.println(n == 1 ? 0 : 1);
            return;
        }

        int[][] dp = initializeDpTable(maxEven, maxOdd);
        dp[0][0] = 0;

        // Process prefix zeros (before the first non-zero element)
        processSegment(dp, maxEven, maxOdd, firstNonZeroIndex,
                getParity(arr[firstNonZeroIndex]), -1);

        // Process middle segments of zeros (between two non-zero elements)
        int start = firstNonZeroIndex;
        for (int end = start + 1; end < n; end++) {
            if (arr[end] != 0) {
                int zeroCount = end - start - 1;
                if (zeroCount > 0) {
                    processSegment(dp, maxEven, maxOdd, zeroCount,
                            getParity(arr[start]), getParity(arr[end]));
                }
                start = end;
            }
        }

        // Process suffix zeros (after the last non-zero element)
        if (start < n - 1) {
            int zeroCount = n - start - 1;
            processSegment(dp, maxEven, maxOdd, zeroCount,
                    getParity(arr[start]), -1);
        }

        System.out.println(initialTransitions + dp[maxEven][maxOdd]);
    }

    /** Returns 0 for even, 1 for odd. */
    private static int getParity(int value) {
        return value % 2 == 0 ? 0 : 1;
    }

    /** Counts parity transitions between adjacent non-zero elements. */
    private static int calculateInitialTransitions(int[] arr, int n) {
        int transitions = 0;
        for (int i = 1; i < n; i++) {
            if (arr[i] == 0 || arr[i - 1] == 0) continue;
            if (getParity(arr[i - 1]) != getParity(arr[i])) {
                transitions++;
            }
        }
        return transitions;
    }

    /** Calculates how many even/odd slots remain to be filled by zeros. */
    private static int[] calculateAvailableSlots(int[] arr, int n) {
        int evenSlots = n / 2;
        int oddSlots = n / 2 + n % 2;
        for (int val : arr) {
            if (val == 0) continue;
            if (val % 2 == 0) evenSlots--;
            else oddSlots--;
        }
        return new int[]{evenSlots, oddSlots};
    }

    /** Finds the index of the first non-zero element. */
    private static int findFirstNonZero(int[] arr, int n) {
        for (int i = 0; i < n; i++) {
            if (arr[i] != 0) return i;
        }
        return -1;
    }

    /** Initializes the DP table with -1 to represent unreachable states. */
    private static int[][] initializeDpTable(int maxEven, int maxOdd) {
        int[][] dp = new int[maxEven + 1][maxOdd + 1];
        for (int i = 0; i <= maxEven; i++) {
            for (int j = 0; j <= maxOdd; j++) {
                dp[i][j] = -1;
            }
        }
        return dp;
    }

    /**
     * Updates the DP table for a contiguous segment of zeros.
     *
     * @param dp          The DP state table
     * @param maxEven     Maximum even values allowed
     * @param maxOdd      Maximum odd values allowed
     * @param zeroCount   Number of zeros in the current segment
     * @param leftParity  Parity of the left boundary (0=even, 1=odd, -1=none)
     * @param rightParity Parity of the right boundary (0=even, 1=odd, -1=none)
     */
    private static void processSegment(int[][] dp, int maxEven, int maxOdd,
                                       int zeroCount, int leftParity, int rightParity) {
        for (int i = maxEven; i >= 0; i--) {
            for (int j = maxOdd; j >= 0; j--) {
                for (int k = 0; k <= zeroCount; k++) {
                    if (k > i || zeroCount - k > j) continue;

                    int prevI = i - k;
                    int prevJ = j - (zeroCount - k);
                    if (dp[prevI][prevJ] == -1) continue;

                    int cost;
                    if (leftParity == -1 && rightParity == -1) {
                        cost = 1; // Fallback (should not be reached in valid inputs)
                    } else if (leftParity == -1) {
                        // Right boundary only (suffix)
                        cost = 1;
                        if (k == zeroCount && rightParity == 0) cost = 0;
                        if (k == 0 && rightParity == 1) cost = 0;
                    } else if (rightParity == -1) {
                        // Left boundary only (prefix)
                        cost = 1;
                        if (k == zeroCount && leftParity == 0) cost = 0;
                        if (k == 0 && leftParity == 1) cost = 0;
                    } else {
                        // Both boundaries (middle segment)
                        cost = 2;
                        if (leftParity != rightParity) cost = 1;
                        else if (leftParity == 0 && k == zeroCount) cost = 0;
                        else if (leftParity == 1 && k == 0) cost = 0;
                    }

                    int newCost = dp[prevI][prevJ] + cost;
                    if (dp[i][j] == -1 || newCost < dp[i][j]) {
                        dp[i][j] = newCost;
                    }
                }
            }
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Solves a parity gap-filling optimization problem.
 * 
 * Refactoring Notes:
 * - Removed unused constants (INF, MOD, N) and fields (rand, static in/out).
 * - Replaced magic variable names with descriptive identifiers.
 * - Extracted I/O into a dedicated, robust FastScanner class.
 * - Removed static state from solve() by passing dependencies explicitly.
 * - Grouped repetitive boundary-slot logic for clarity.
 * - Added JavaDoc and inline comments explaining algorithmic steps.
 * - Fixed FastScanner edge-case handling (EOF and IOException propagation).
 */
public class Main {

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out));

        // Original implementation hardcoded 1 test case. Kept for behavioral parity.
        int testCases = 1;
        while (testCases-- > 0) {
            solve(scanner, out);
        }

        out.flush();
        out.close();
    }

    /**
     * Core algorithm: calculates minimum cost to resolve parity mismatches
     * by strategically filling zero-gaps with available even/odd slots.
     */
    private static void solve(FastScanner in, PrintWriter out) {
        int n = in.nextInt();
        int[] values = new int[n];
        for (int i = 0; i < n; i++) {
            values[i] = in.nextInt();
        }

        // Calculate available slots based on parity (index 0 = even, index 1 = odd)
        int[] availableSlots = {n / 2, n / 2 + n % 2};
        for (int val : values) {
            if (val != 0) {
                availableSlots[val % 2]--;
            }
        }

        // Base case: if all positions are zero, cost is trivial
        if (availableSlots[0] + availableSlots[1] == n) {
            out.println(n == 1 ? 0 : 1);
            return;
        }

        // PriorityQueues store gap lengths, ordered smallest to largest (greedy optimal)
        PriorityQueue<Integer> gapsEvenEven = new PriorityQueue<>();
        PriorityQueue<Integer> gapsEvenOdd = new PriorityQueue<>();
        PriorityQueue<Integer> gapsOddEven = new PriorityQueue<>();
        PriorityQueue<Integer> gapsOddOdd = new PriorityQueue<>();

        int prefixEven = 0, prefixOdd = 0;
        int suffixEven = 0, suffixOdd = 0;
        int cost = 0;

        int i = 0;
        while (i < n) {
            if (values[i] == 0) {
                // Find the end of the current zero-gap
                int j = i;
                while (j < n && values[j] == 0) {
                    j++;
                }
                int gapLength = j - i;

                if (i == 0) {
                    // Prefix gap: classify by the parity of the first non-zero element after it
                    if (j < n && values[j] % 2 == 0) {
                        prefixEven = gapLength;
                    } else {
                        prefixOdd = gapLength;
                    }
                } else if (j == n) {
                    // Suffix gap: classify by the parity of the last non-zero element before it
                    if (values[i - 1] % 2 == 0) {
                        suffixEven = gapLength;
                    } else {
                        suffixOdd = gapLength;
                    }
                } else {
                    // Middle gap: classify by boundary parities
                    int leftParity = values[i - 1] % 2;
                    int rightParity = values[j] % 2;
                    if (leftParity == 0 && rightParity == 0) {
                        gapsEvenEven.add(gapLength);
                    } else if (leftParity == 0 && rightParity == 1) {
                        gapsEvenOdd.add(gapLength);
                    } else if (leftParity == 1 && rightParity == 0) {
                        gapsOddEven.add(gapLength);
                    } else {
                        gapsOddOdd.add(gapLength);
                    }
                }
                i = j; // Advance past the processed gap
            } else {
                // Count parity mismatches between consecutive non-zero elements
                if (i > 0 && values[i - 1] != 0) {
                    if ((values[i - 1] % 2 + values[i] % 2) % 2 == 1) {
                        cost++;
                    }
                }
                i++;
            }
        }

        // Mixed-parity gaps inherently cost 1 each
        cost += gapsEvenOdd.size();
        cost += gapsOddEven.size();

        // Greedily fill homogeneous gaps with matching slots
        cost += applySlots(gapsEvenEven, availableSlots[0]);
        cost += applySlots(gapsOddOdd, availableSlots[1]);

        // Handle boundary gaps explicitly for clarity and correctness
        if (prefixEven != 0) {
            if (availableSlots[0] >= prefixEven) {
                availableSlots[0] -= prefixEven;
            } else {
                cost++;
            }
        }
        if (prefixOdd != 0) {
            if (availableSlots[1] >= prefixOdd) {
                availableSlots[1] -= prefixOdd;
            } else {
                cost++;
            }
        }
        if (suffixEven != 0) {
            if (availableSlots[0] >= suffixEven) {
                availableSlots[0] -= suffixEven;
            } else {
                cost++;
            }
        }
        if (suffixOdd != 0) {
            if (availableSlots[1] >= suffixOdd) {
                availableSlots[1] -= suffixOdd;
            } else {
                cost++;
            }
        }

        out.println(cost);
    }

    /**
     * Applies available slots to a collection of gaps.
     * Fills gaps greedily from smallest to largest. If a gap cannot be fully filled,
     * it adds a cost of 2.
     */
    private static int applySlots(PriorityQueue<Integer> gaps, int available) {
        int additionalCost = 0;
        while (!gaps.isEmpty()) {
            int length = gaps.poll();
            if (available >= length) {
                available -= length;
            } else {
                additionalCost += 2;
            }
        }
        return additionalCost;
    }

    /**
     * Fast, robust input reader optimized for competitive programming.
     */
    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner(InputStream is) {
            br = new BufferedReader(new InputStreamReader(is));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input stream", e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            String s = next();
            if (s == null) throw new NoSuchElementException("Unexpected end of input");
            return Integer.parseInt(s);
        }
    }
}

import java.io.*;
import java.util.*;

public class Codeforces {

    /** Represents the parity of a number */
    enum Parity {
        ODD, EVEN
    }

    /** Represents a contiguous segment of zeros bounded by non-zero values */
    static class Interval implements Comparable<Interval> {
        final Parity parity;
        final int count;

        Interval(Parity parity, int count) {
            this.parity = parity;
            this.count = count;
        }

        @Override
        public int compareTo(Interval other) {
            return Integer.compare(this.count, other.count);
        }
    }

    public static void main(String[] args) {
        InputReader in = new InputReader(System.in);
        PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out));
        try {
            int n = in.nextInt();
            int[] p = in.nextIntArr(n);
            out.println(solve(n, p));
        } finally {
            out.flush();
        }
    }

    /**
     * Core algorithm to calculate the minimum operations.
     *
     * @param n size of the permutation
     * @param p array containing numbers 1..n and zeros
     * @return calculated result
     */
    private static int solve(int n, int[] p) {
        if (n == 0) return 0;

        // Identify which numbers from 1 to n are missing
        Set<Integer> presentValues = new HashSet<>();
        for (int val : p) {
            if (val != 0) presentValues.add(val);
        }

        int missingEvenCount = 0;
        int missingOddCount = 0;
        for (int i = 1; i <= n; i++) {
            if (!presentValues.contains(i)) {
                if (i % 2 == 0) missingEvenCount++;
                else missingOddCount++;
            }
        }

        // Edge case: all positions are zero (only possible if p contains no non-zeros)
        if (missingEvenCount + missingOddCount == n) {
            return n == 1 ? 0 : 1;
        }

        List<Interval> closedIntervals = new ArrayList<>();
        List<Interval> openIntervals = new ArrayList<>();
        int result = 0;

        int zeroRunLength = 0;
        Integer previousNonZero = null;

        for (int i = 0; i < n; i++) {
            if (p[i] != 0) {
                if (previousNonZero == null && zeroRunLength > 0) {
                    // Leading zeros segment
                    openIntervals.add(new Interval(getParity(p[i]), zeroRunLength));
                } else if (previousNonZero != null && zeroRunLength > 0) {
                    // Zero segment between two non-zero values
                    if (p[i] % 2 == previousNonZero % 2) {
                        closedIntervals.add(new Interval(getParity(p[i]), zeroRunLength));
                    } else {
                        result++;
                    }
                } else if (previousNonZero != null && zeroRunLength == 0) {
                    // Adjacent non-zero values with different parity
                    if (p[i] % 2 != previousNonZero % 2) {
                        result++;
                    }
                }

                zeroRunLength = 0;
                previousNonZero = p[i];
            } else {
                zeroRunLength++;
                if (i == n - 1) {
                    // Trailing zeros segment
                    if (previousNonZero != null) {
                        openIntervals.add(new Interval(getParity(previousNonZero), zeroRunLength));
                    }
                }
            }
        }

        // Greedy strategy: fill larger zero segments first
        Collections.sort(closedIntervals);

        for (Interval interval : closedIntervals) {
            if (interval.parity == Parity.EVEN) {
                if (missingEvenCount >= interval.count) {
                    missingEvenCount -= interval.count;
                } else {
                    result += 2;
                }
            } else {
                if (missingOddCount >= interval.count) {
                    missingOddCount -= interval.count;
                } else {
                    result += 2;
                }
            }
        }

        for (Interval openInterval : openIntervals) {
            if (openInterval.parity == Parity.EVEN) {
                if (missingEvenCount < openInterval.count) {
                    result++;
                }
            } else {
                if (missingOddCount < openInterval.count) {
                    result++;
                }
            }
        }

        return result;
    }

    private static Parity getParity(int value) {
        return (value % 2 == 0) ? Parity.EVEN : Parity.ODD;
    }

    /** Fast I/O helper for competitive programming */
    public static class InputReader {
        public BufferedReader reader;
        public StringTokenizer tokenizer;

        public InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public String nextLine() {
            try {
                return reader.readLine();
            } catch (IOException e) {
                throw new RuntimeException(e);
            }
        }

        public int nextInt() {
            String s = next();
            return s == null ? 0 : Integer.parseInt(s);
        }

        public long nextLong() {
            String s = next();
            return s == null ? 0L : Long.parseLong(s);
        }

        public int[] nextIntArr(int n) {
            int[] arr = new int[n];
            for (int i = 0; i < n; i++) {
                arr[i] = nextInt();
            }
            return arr;
        }

        public long[] nextLongArr(int n) {
            long[] arr = new long[n];
            for (int i = 0; i < n; i++) {
                arr[i] = nextLong();
            }
            return arr;
        }
    }
}

import java.util.Scanner;

public class Garland {

    public static void main(String[] args) {
        // Use try-with-resources to ensure Scanner is properly closed
        try (Scanner scanner = new Scanner(System.in)) {
            if (!scanner.hasNextInt()) return;
            int n = scanner.nextInt();
            int[] arr = new int[n];
            int oddCount = 0;
            int evenCount = 0;

            // Phase 1: Read input and count initial parities
            for (int i = 0; i < n; i++) {
                arr[i] = scanner.nextInt();
                if (arr[i] == 1) oddCount++;
                else if (arr[i] == 2) evenCount++;
            }

            // Edge case: All lamps are off
            if (oddCount == 0 && evenCount == 0) {
                System.out.println(n == 1 ? 0 : 1);
                return;
            }

            int firstIndex = -1;
            int lastIndex = -1;
            int lastNonZeroValue = -1;
            int gapLength = 0;
            int[] sameParityGaps = new int[n];

            // Phase 2: Identify gaps between same-parity numbers
            for (int i = 0; i < n; i++) {
                if (arr[i] != 0) {
                    lastIndex = i;
                    if (firstIndex == -1) firstIndex = i;

                    if (lastNonZeroValue == -1) {
                        lastNonZeroValue = arr[i];
                        gapLength = 0;
                    } else {
                        if (isSameParity(lastNonZeroValue, arr[i])) {
                            sameParityGaps[gapLength] = 1;
                        }
                        lastNonZeroValue = arr[i];
                        gapLength = 0;
                    }
                    continue;
                }
                gapLength++;
            }

            // Phase 3: Fill gaps between same-parity numbers
            for (int i = 1; i < n; i++) {
                if (sameParityGaps[i] != 0) {
                    int distance = i;
                    for (int j = 0; j < n - distance - 1; j++) {
                        if (arr[j] != 0 && arr[j + distance + 1] != 0 &&
                                isSameParity(arr[j], arr[j + distance + 1])) {
                            boolean allZeros = true;
                            for (int k = j + 1; k <= j + distance; k++) {
                                if (arr[k] != 0) {
                                    allZeros = false;
                                    break;
                                }
                            }
                            if (allZeros) {
                                fillGap(arr, j + 1, j + distance, arr[j]);
                                if (arr[j] % 2 == 0) evenCount -= distance;
                                else oddCount -= distance;
                            }
                        }
                    }
                }
            }

            // Phase 4: Fill trailing zeros
            if (lastIndex != n - 1) {
                int remaining = n - lastIndex - 1;
                int fillValue = -1;
                if (arr[lastIndex] % 2 == 0 && evenCount >= remaining) {
                    fillValue = 2;
                    evenCount -= remaining;
                } else if (arr[lastIndex] % 2 != 0 && oddCount >= remaining) {
                    fillValue = 1;
                    oddCount -= remaining;
                }
                if (fillValue != -1) {
                    for (int i = lastIndex + 1; i < n; i++) {
                        arr[i] = fillValue;
                    }
                }
            }

            // Phase 5: Fill leading zeros
            for (int i = firstIndex - 1; i >= 0; i--) {
                int nextValue = arr[i + 1];
                if (nextValue % 2 == 0) {
                    if (evenCount > 0) {
                        evenCount--;
                        arr[i] = 2;
                    } else {
                        oddCount--;
                        arr[i] = 1;
                    }
                } else {
                    if (oddCount > 0) {
                        oddCount--;
                        arr[i] = 1;
                    } else {
                        evenCount--;
                        arr[i] = 2;
                    }
                }
            }

            // Phase 6: Fill any remaining zeros
            for (int i = firstIndex + 1; i < n; i++) {
                if (arr[i] == 0) {
                    arr[i] = 1;
                }
            }

            // Phase 7: Calculate and output result
            System.out.println(countParityChanges(arr));
        }
    }

    /** Checks if two numbers have the same parity (both even or both odd) */
    private static boolean isSameParity(int a, int b) {
        return (a % 2) == (b % 2);
    }

    /** Fills a contiguous range in the array with a specific value */
    private static void fillGap(int[] arr, int start, int end, int value) {
        for (int i = start; i <= end; i++) {
            arr[i] = value;
        }
    }

    /** Counts the number of adjacent pairs with different parity */
    private static int countParityChanges(int[] arr) {
        int changes = 0;
        for (int i = 0; i < arr.length - 1; i++) {
            if ((arr[i] % 2) != (arr[i + 1] % 2)) {
                changes++;
            }
        }
        return changes;
    }
}

import java.io.*;
import java.util.*;

public class Main {
    // Semantic constants to replace magic numbers
    private static final int EVEN = 0;
    private static final int ODD = 1;
    private static final int NO_PREVIOUS = 2;

    public static void main(String[] args) throws IOException {
        FastScanner scanner = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));

        try {
            // Original code runs exactly once (t=1)
            int n = scanner.nextInt();

            // Calculate initial capacity for odds and evens we can still place
            int remainingOdds = (n + 1) / 2;
            int remainingEvens = n / 2;

            int[] fixedValues = new int[n];
            for (int i = 0; i < n; i++) {
                int num = scanner.nextInt();
                if (num == 0) {
                    fixedValues[i] = -1; // -1 represents an unknown value to be determined
                } else if (num % 2 == 0) {
                    remainingEvens--;
                    fixedValues[i] = EVEN;
                } else {
                    remainingOdds--;
                    fixedValues[i] = ODD;
                }
            }

            // Initialize DP table with -1 to indicate uncomputed states
            int[][][][] dp = new int[n][remainingOdds + 1][remainingEvens + 1][3];
            for (int i = 0; i < n; i++) {
                for (int j = 0; j <= remainingOdds; j++) {
                    for (int k = 0; k <= remainingEvens; k++) {
                        Arrays.fill(dp[i][j][k], -1);
                    }
                }
            }

            // Compute and print result
            out.println(solve(0, fixedValues, remainingOdds, remainingEvens, NO_PREVIOUS, dp));
        } finally {
            out.flush();
            out.close();
        }
    }

    /**
     * Recursive DP function to find the minimum number of transitions
     * between even and odd numbers, respecting fixed values and counts.
     *
     * @param index          Current position in the array
     * @param arr            Fixed values array (-1 for unknowns)
     * @param remainingOdds  Number of odd values we can still place
     * @param remainingEvens Number of even values we can still place
     * @param previous       Type of the previous element (EVEN, ODD, or NO_PREVIOUS)
     * @param dp             Memoization table
     * @return Minimum transitions from current state to the end
     */
    private static int solve(int index, int[] arr, int remainingOdds, int remainingEvens,
                             int previous, int[][][][] dp) {
        if (index == arr.length) {
            return 0;
        }

        if (dp[index][remainingOdds][remainingEvens][previous] != -1) {
            return dp[index][remainingOdds][remainingEvens][previous];
        }

        int ans = 0;
        int current = arr[index];

        if (current != -1) {
            // If the current value is fixed, count a transition if it differs from previous
            if (previous != NO_PREVIOUS && current != previous) {
                ans++;
            }
            ans += solve(index + 1, arr, remainingOdds, remainingEvens, current, dp);
        } else {
            // Current value is unknown (-1), try placing ODD or EVEN
            int minCost = Integer.MAX_VALUE;

            // Option 1: Place ODD (1)
            if (remainingOdds > 0) {
                int cost = 0;
                if (previous == EVEN) {
                    cost++; // Transition from 0 to 1
                }
                cost += solve(index + 1, arr, remainingOdds - 1, remainingEvens, ODD, dp);
                minCost = Math.min(minCost, cost);
            }

            // Option 2: Place EVEN (0)
            if (remainingEvens > 0) {
                int cost = 0;
                if (previous == ODD) {
                    cost++; // Transition from 1 to 0
                }
                cost += solve(index + 1, arr, remainingOdds, remainingEvens - 1, EVEN, dp);
                minCost = Math.min(minCost, cost);
            }

            ans = minCost;
        }

        dp[index][remainingOdds][remainingEvens][previous] = ans;
        return ans;
    }

    /**
     * Standard fast I/O helper for competitive programming.
     * Replaces custom byte-buffer reader with BufferedReader for better maintainability.
     */
    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
            st = new StringTokenizer("");
        }

        String next() throws IOException {
            while (!st.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) return null;
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

        int nextInt() throws IOException {
            String s = next();
            if (s == null) throw new EOFException();
            return Integer.parseInt(s);
        }
    }
}

import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) {
        FastScanner sc = new FastScanner();
        PrintWriter out = new PrintWriter(System.out);
        solve(sc, out);
        out.flush();
        out.close();
    }

    private static void solve(FastScanner sc, PrintWriter out) {
        int n = sc.ni();
        int[] nums = new int[n];
        int positiveEvens = 0;
        int positiveOdds = 0;

        // Indices of positive numbers, with sentinels at boundaries (-1 and n)
        List<Integer> positiveIndices = new ArrayList<>();
        positiveIndices.add(-1);

        for (int i = 0; i < n; i++) {
            nums[i] = sc.ni();
            if (nums[i] > 0) {
                positiveIndices.add(i);
                if (nums[i] % 2 == 0) positiveEvens++;
                else positiveOdds++;
            }
        }
        positiveIndices.add(n);

        // Calculate how many even/odd numbers from 1..N are missing
        int missingEvens = (n / 2) - positiveEvens;
        int missingOdds = ((n + 1) / 2) - positiveOdds;

        if (n == 1) {
            out.println(0);
            return;
        }

        if (positiveIndices.size() == 2) {
            out.println(1);
            return;
        }

        int cost = 0;

        // Count adjacent positive pairs with different parity
        for (int i = 1; i < n; i++) {
            if (nums[i] > 0 && nums[i - 1] > 0 && (nums[i] % 2) != (nums[i - 1] % 2)) {
                cost++;
            }
        }

        // Categorize zero-segments based on parity of adjacent positive numbers
        List<Integer> edgeEven = new ArrayList<>();
        List<Integer> edgeOdd = new ArrayList<>();
        List<Integer> mainEven = new ArrayList<>();
        List<Integer> mainOdd = new ArrayList<>();

        for (int i = 1; i < positiveIndices.size(); i++) {
            int gap = positiveIndices.get(i) - positiveIndices.get(i - 1) - 1;
            if (gap == 0) continue;

            int leftIdx = positiveIndices.get(i - 1);
            int rightIdx = positiveIndices.get(i);

            if (i == 1) {
                // Leftmost gap (before first positive)
                if (nums[rightIdx] % 2 == 0) edgeEven.add(gap);
                else edgeOdd.add(gap);
            } else if (i == positiveIndices.size() - 1) {
                // Rightmost gap (after last positive)
                if (nums[leftIdx] % 2 == 0) edgeEven.add(gap);
                else edgeOdd.add(gap);
            } else {
                // Internal gaps
                if (nums[leftIdx] % 2 == 0 && nums[rightIdx] % 2 == 0) {
                    mainEven.add(gap);
                } else if (nums[leftIdx] % 2 == 1 && nums[rightIdx] % 2 == 1) {
                    mainOdd.add(gap);
                } else {
                    cost++;
                }
            }
        }

        // Sort gaps to greedily fill smaller ones first
        Collections.sort(mainEven);
        Collections.sort(mainOdd);
        Collections.sort(edgeEven);
        Collections.sort(edgeOdd);

        // Process main even gaps
        for (int gap : mainEven) {
            if (missingEvens >= gap) missingEvens -= gap;
            else cost += 2;
        }

        // Process edge even gaps
        for (int gap : edgeEven) {
            if (missingEvens >= gap) missingEvens -= gap;
            else cost += 1;
        }

        // Process main odd gaps
        for (int gap : mainOdd) {
            if (missingOdds >= gap) missingOdds -= gap;
            else cost += 2;
        }

        // Process edge odd gaps
        for (int gap : edgeOdd) {
            if (missingOdds >= gap) missingOdds -= gap;
            else cost += 1;
        }

        out.println(cost);
    }

    /**
     * Optimized FastScanner for competitive programming input.
     * Replaces HashSet lookups with direct counting to avoid autoboxing and O(N log N) overhead.
     */
    static class FastScanner {
        BufferedReader br;
        StringTokenizer st;

        public FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        int ni() { return Integer.parseInt(next()); }
        long nl() { return Long.parseLong(next()); }
        double nd() { return Double.parseDouble(next()); }

        String nextLine() {
            String str = "";
            try { str = br.readLine(); } catch (IOException e) { e.printStackTrace(); }
            return str;
        }
    }
}

import java.io.IOException;
import java.io.InputStream;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

public class Garland {

    public static void main(String[] args) throws IOException {
        // Use try-with-resources to guarantee stream closure
        try (FastIO in = new FastIO(System.in)) {
            int n = in.nextInt();
            int[] values = new int[n];

            // Initial capacity based on parity distribution
            int evenCapacity = n / 2;
            int oddCapacity = (n + 1) / 2;
            int mismatchCount = 0;

            // Read input and adjust available capacity for non-zero values
            for (int i = 0; i < n; i++) {
                values[i] = in.nextInt();
                if (values[i] % 2 == 0) {
                    evenCapacity--;
                } else {
                    oddCapacity--;
                }
            }

            // Separate zero-segments by their boundary conditions
            List<Integer> sameParityEvenSegments = new ArrayList<>();
            List<Integer> sameParityOddSegments = new ArrayList<>();
            List<Integer> boundaryEvenSegments = new ArrayList<>();
            List<Integer> boundaryOddSegments = new ArrayList<>();

            int i = 0;
            while (i < n) {
                if (values[i] != 0) {
                    i++;
                    continue;
                }

                int segmentStart = i;
                while (i < n && values[i] == 0) {
                    i++;
                }
                int segmentLength = i - segmentStart;

                int leftNeighbor = (segmentStart > 0) ? values[segmentStart - 1] : -1;
                int rightNeighbor = (i < n) ? values[i] : -1;

                if (leftNeighbor != -1 && rightNeighbor != -1) {
                    if (leftNeighbor % 2 == rightNeighbor % 2) {
                        if (leftNeighbor % 2 == 0) {
                            sameParityEvenSegments.add(segmentLength);
                        } else {
                            sameParityOddSegments.add(segmentLength);
                        }
                    } else {
                        mismatchCount++; // Different parity neighbors cause a mismatch
                    }
                } else if (leftNeighbor == -1) {
                    // Boundary at the start of the array
                    if (rightNeighbor % 2 == 0) {
                        boundaryEvenSegments.add(segmentLength);
                    } else {
                        boundaryOddSegments.add(segmentLength);
                    }
                } else {
                    // Boundary at the end of the array
                    if (leftNeighbor % 2 == 0) {
                        boundaryEvenSegments.add(segmentLength);
                    } else {
                        boundaryOddSegments.add(segmentLength);
                    }
                }
            }

            // Process segments: fit them into available capacity and count mismatches
            int[] evenCap = {evenCapacity};
            int[] oddCap = {oddCapacity};

            mismatchCount += processSegments(sameParityEvenSegments, evenCap, 2);
            mismatchCount += processSegments(sameParityOddSegments, oddCap, 2);
            mismatchCount += processSegments(boundaryEvenSegments, evenCap, 1);
            mismatchCount += processSegments(boundaryOddSegments, oddCap, 1);

            // Count adjacent non-zero elements with different parity
            for (int k = 0; k < n - 1; k++) {
                if (values[k] != 0 && values[k + 1] != 0) {
                    if (values[k] % 2 != values[k + 1] % 2) {
                        mismatchCount++;
                    }
                }
            }

            System.out.println(mismatchCount);
        }
    }

    /**
     * Sorts segments, fits as many as possible into the given capacity,
     * updates the capacity holder, and returns the weighted count of unfit segments.
     *
     * @param segments   List of segment lengths to process
     * @param capacityHolder Mutable container for the remaining capacity
     * @param multiplier Multiplier for unfit segments (2 for same-parity, 1 for boundary)
     * @return Number of added mismatches
     */
    private static int processSegments(List<Integer> segments, int[] capacityHolder, int multiplier) {
        Collections.sort(segments);
        int capacity = capacityHolder[0];
        int sum = 0;
        int fittedCount = 0;

        for (int length : segments) {
            if (sum + length > capacity) {
                break;
            }
            sum += length;
            fittedCount++;
        }

        capacityHolder[0] = capacity - sum;
        return multiplier * (segments.size() - fittedCount);
    }

    /**
     * Fast Input/Output utility for competitive programming scenarios.
     */
    public static class FastIO implements AutoCloseable {
        private final InputStream dis;
        private final byte[] buffer = new byte[1 << 17];
        private int pointer = 0;

        public FastIO(InputStream is) throws IOException {
            this.dis = is;
        }

        public int nextInt() throws IOException {
            int ret = 0;
            byte b;

            do {
                b = nextByte();
            } while (b <= ' ');

            boolean negative = false;
            if (b == '-') {
                negative = true;
                b = nextByte();
            }

            while (b >= '0' && b <= '9') {
                ret = 10 * ret + b - '0';
                b = nextByte();
            }

            return negative ? -ret : ret;
        }

        public byte nextByte() throws IOException {
            if (pointer == buffer.length) {
                dis.read(buffer, 0, buffer.length);
                pointer = 0;
            }
            return buffer[pointer++];
        }

        @Override
        public void close() throws IOException {
            dis.close();
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Refactored solution for counting parity transitions in an array.
 * Computes the minimum number of changes needed to satisfy parity constraints.
 */
public class ParityGapCounter {

    public static void main(String[] args) throws IOException {
        // Use try-with-resources for automatic and safe resource management
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
             PrintWriter writer = new PrintWriter(new BufferedOutputStream(System.out))) {

            String line = reader.readLine();
            if (line == null) return;
            int n = Integer.parseInt(line.trim());

            int[] array = new int[n];
            StringTokenizer st = new StringTokenizer(reader.readLine());
            for (int i = 0; i < n; i++) {
                array[i] = Integer.parseInt(st.nextToken());
            }

            int result = computeParityTransitions(n, array);
            writer.println(result);
        }
    }

    /**
     * Core algorithm to compute the number of parity transitions required.
     */
    private static int computeParityTransitions(int n, int[] array) {
        int availableZeros = n / 2;
        int availableOnes = n - n / 2;
        int transitionsNeeded = 0;

        List<Integer> oneGaps = new ArrayList<>();
        List<Integer> zeroGaps = new ArrayList<>();

        int lastNonZeroIndex = -1;
        boolean firstNonZeroFound = false;

        // First pass: identify gaps between same-parity non-zero elements
        for (int i = 0; i < n; i++) {
            if (array[i] != 0) {
                if (firstNonZeroFound) {
                    int gap = i - lastNonZeroIndex - 1;

                    if (array[i] % 2 == 1 && array[lastNonZeroIndex] % 2 == 1) {
                        oneGaps.add(gap);
                    } else if (array[i] % 2 == 0 && array[lastNonZeroIndex] % 2 == 0) {
                        zeroGaps.add(gap);
                    } else {
                        transitionsNeeded++;
                    }
                } else {
                    firstNonZeroFound = true;
                }

                // Decrement available counts for the current non-zero element
                if (array[i] % 2 == 1) {
                    availableOnes--;
                } else {
                    availableZeros--;
                }

                lastNonZeroIndex = i;
            }
        }

        // Greedily fill same-parity gaps with available counts
        Collections.sort(oneGaps);
        Collections.sort(zeroGaps);

        int i = 0;
        for (; i < oneGaps.size(); i++) {
            if (availableOnes - oneGaps.get(i) >= 0) {
                availableOnes -= oneGaps.get(i);
            } else {
                break;
            }
        }
        transitionsNeeded += 2 * (oneGaps.size() - i);

        int j = 0;
        for (; j < zeroGaps.size(); j++) {
            if (availableZeros - zeroGaps.get(j) >= 0) {
                availableZeros -= zeroGaps.get(j);
            } else {
                break;
            }
        }
        transitionsNeeded += 2 * (zeroGaps.size() - j);

        // Handle leading zeros
        int firstNonZeroIdx = findFirstNonZero(array, n);
        if (firstNonZeroIdx == -1) {
            return n > 1 ? 1 : 0;
        }

        int leadingZeros = firstNonZeroIdx;
        if (array[firstNonZeroIdx] % 2 == 0) {
            if (leadingZeros <= availableZeros) {
                availableZeros -= leadingZeros;
            } else {
                transitionsNeeded++;
            }
        } else {
            if (leadingZeros <= availableOnes) {
                availableOnes -= leadingZeros;
            } else {
                transitionsNeeded++;
            }
        }

        // Handle trailing zeros
        int lastNonZeroIdx = findLastNonZero(array, n);
        int trailingZeros = n - 1 - lastNonZeroIdx;
        if (array[lastNonZeroIdx] % 2 == 0) {
            if (trailingZeros <= availableZeros) {
                availableZeros -= trailingZeros;
            } else {
                transitionsNeeded++;
            }
        } else {
            if (trailingZeros <= availableOnes) {
                availableOnes -= trailingZeros;
            } else {
                transitionsNeeded++;
            }
        }

        return transitionsNeeded;
    }

    /**
     * Finds the index of the first non-zero element.
     */
    private static int findFirstNonZero(int[] array, int n) {
        for (int idx = 0; idx < n; idx++) {
            if (array[idx] != 0) {
                return idx;
            }
        }
        return -1;
    }

    /**
     * Finds the index of the last non-zero element.
     */
    private static int findLastNonZero(int[] array, int n) {
        for (int idx = n - 1; idx >= 0; idx--) {
            if (array[idx] != 0) {
                return idx;
            }
        }
        return -1;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.OutputStream;
import java.io.PrintWriter;
import java.util.StringTokenizer;

public class Main {
    // Use a large enough constant to prevent overflow when adding 1 during transitions
    private static final int INF = Integer.MAX_VALUE / 2;

    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        TaskC solver = new TaskC();
        solver.solve(1, in, out);
        out.close();
    }

    static class TaskC {
        /**
         * Solves the problem using dynamic programming.
         * 
         * DP State: dp[i][parity][remainingOdd][remainingEven]
         * - i: current index in the array
         * - parity: parity of the element at index i (0 for even, 1 for odd)
         * - remainingOdd: number of odd values still needed to fill zero positions
         * - remainingEven: number of even values still needed to fill zero positions
         * Value: Minimum cost (mismatches) to fill the prefix up to i satisfying constraints
         */
        public void solve(int testNumber, InputReader in, PrintWriter out) {
            int n = in.nextInt();
            int[] arr = new int[n];
            int neededOdd = (n + 1) / 2;
            int neededEven = n / 2;

            // Read input and calculate how many odd/even numbers are still required for zeros
            for (int i = 0; i < n; i++) {
                arr[i] = in.nextInt();
                if (arr[i] != 0) {
                    if (arr[i] % 2 != 0) {
                        neededOdd--;
                    } else {
                        neededEven--;
                    }
                }
            }

            // Initialize DP table
            int[][][][] dp = new int[n][2][neededOdd + 1][neededEven + 1];

            // Fill DP table with INF
            for (int i = 0; i < n; i++) {
                for (int p = 0; p < 2; p++) {
                    for (int ro = 0; ro <= neededOdd; ro++) {
                        for (int re = 0; re <= neededEven; re++) {
                            dp[i][p][ro][re] = INF;
                        }
                    }
                }
            }

            // Base case: i = 0
            if (arr[0] != 0) {
                int p = arr[0] % 2;
                for (int ro = 0; ro <= neededOdd; ro++) {
                    for (int re = 0; re <= neededEven; re++) {
                        dp[0][p][ro][re] = 0;
                    }
                }
            } else {
                for (int p = 0; p < 2; p++) {
                    for (int ro = 0; ro <= neededOdd; ro++) {
                        for (int re = 0; re <= neededEven; re++) {
                            // Cannot place a parity if we've exhausted its required count
                            if ((p == 0 && re == 0) || (p == 1 && ro == 0)) {
                                continue;
                            }
                            dp[0][p][ro][re] = 0;
                            // Look-ahead cost: mismatch with next fixed element
                            if (n > 1 && arr[1] != 0 && arr[1] % 2 != p) {
                                dp[0][p][ro][re]++;
                            }
                        }
                    }
                }
            }

            // Count existing mismatches between fixed adjacent elements
            int existingMismatches = 0;
            for (int i = 1; i < n; i++) {
                if (arr[i] != 0 && arr[i - 1] != 0 && arr[i] % 2 != arr[i - 1] % 2) {
                    existingMismatches++;
                }
            }

            // DP transitions
            for (int i = 1; i < n; i++) {
                for (int p = 0; p < 2; p++) {
                    for (int ro = 0; ro <= neededOdd; ro++) {
                        for (int re = 0; re <= neededEven; re++) {
                            if (arr[i] != 0) {
                                // Current element is fixed
                                if (p == arr[i] % 2) {
                                    dp[i][p][ro][re] = Math.min(dp[i - 1][0][ro][re], dp[i - 1][1][ro][re]);
                                }
                            } else {
                                // Current element is 0, we choose parity p
                                // Check if we have enough numbers of parity p remaining
                                if ((p == 0 && re == 0) || (p == 1 && ro == 0)) {
                                    continue;
                                }

                                int prevRo = (p == 1) ? ro - 1 : ro;
                                int prevRe = (p == 0) ? re - 1 : re;

                                // Transition cost: add 1 if previous parity differs from current p
                                int costFromPrev0 = dp[i - 1][0][prevRo][prevRe];
                                int costFromPrev1 = dp[i - 1][1][prevRo][prevRe] + 1;

                                dp[i][p][ro][re] = Math.min(costFromPrev0, costFromPrev1);

                                // Look-ahead cost: mismatch with next fixed element
                                if (i < n - 1 && arr[i + 1] != 0 && arr[i + 1] % 2 != p) {
                                    dp[i][p][ro][re]++;
                                }
                            }
                        }
                    }
                }
            }

            out.println(existingMismatches + Math.min(dp[n - 1][0][neededOdd][neededEven], dp[n - 1][1][neededOdd][neededEven]));
        }
    }

    static class InputReader {
        public BufferedReader reader;
        public StringTokenizer tokenizer;

        public InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.Arrays;
import java.util.StringTokenizer;

public class TaskC {
    // Constants for parity and unknown state to improve readability
    private static final int ODD = 1;
    private static final int EVEN = 0;
    private static final int UNKNOWN = -1;
    private static final int INF = Integer.MAX_VALUE;

    public static void main(String[] args) throws IOException {
        // Use BufferedReader for efficient input reading
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));

        // Read n
        String line = br.readLine();
        if (line == null) return;
        int n = Integer.parseInt(line.trim());

        // Read the array elements
        // Using StringTokenizer to robustly handle whitespace
        String inputLine = br.readLine();
        if (inputLine == null) return;
        StringTokenizer st = new StringTokenizer(inputLine);

        int[] parities = new int[n];

        // Calculate initial capacities (ceil(n/2) and floor(n/2))
        // These represent the maximum allowed counts of odd and even numbers
        int capacityOdds = n - n / 2;
        int capacityEvens = n - n / 2 - (n % 2);

        // Parse input and update capacities based on actual numbers present
        for (int i = 0; i < n; i++) {
            if (st.hasMoreTokens()) {
                int v = Integer.parseInt(st.nextToken());
                if (v > 0) {
                    parities[i] = v % 2;
                    if (v % 2 == 0) {
                        capacityEvens--;
                    } else {
                        capacityOdds--;
                    }
                } else {
                    // Non-positive numbers are treated as wildcards (UNKNOWN)
                    parities[i] = UNKNOWN;
                }
            }
        }

        // DP Table initialization
        // dp[i][j][k][parity]
        // i: current index in array (0 to n-1)
        // j: remaining odd capacity
        // k: remaining even capacity
        // parity: 0 for Even, 1 for Odd (parity of the last placed number)
        // Using int array with INF instead of Integer array for better performance and cleaner null checks
        int[][][][] dp = new int[n][capacityOdds + 1][capacityEvens + 1][2];

        // Fill DP table with INF (representing unreachable states)
        for (int i = 0; i < n; i++) {
            for (int j = 0; j <= capacityOdds; j++) {
                for (int k = 0; k <= capacityEvens; k++) {
                    Arrays.fill(dp[i][j][k], INF);
                }
            }
        }

        // Base case: Index 0
        if (parities[0] == UNKNOWN) {
            // If unknown, we can place an Odd or an Even
            if (capacityOdds > 0) {
                dp[0][capacityOdds - 1][capacityEvens][ODD] = 0;
            }
            if (capacityEvens > 0) {
                dp[0][capacityOdds][capacityEvens - 1][EVEN] = 0;
            }
        } else {
            // If fixed parity
            dp[0][capacityOdds][capacityEvens][parities[0]] = 0;
        }

        // DP Transitions
        for (int i = 1; i < n; i++) {
            for (int j = 0; j <= capacityOdds; j++) {
                for (int k = 0; k <= capacityEvens; k++) {

                    // We look at previous state dp[i-1][j][k]
                    // Note: The logic for fixed numbers in the original code 
                    // does not decrement j or k, while wildcards do.

                    if (parities[i] == UNKNOWN) {
                        // Wildcard: Can transition to ODD or EVEN

                        // Transitioning to ODD consumes 1 Odd capacity (j -> j-1)
                        if (j > 0) {
                            // From previous ODD (cost 0 change)
                            if (dp[i - 1][j][k][ODD] != INF) {
                                dp[i][j - 1][k][ODD] = Math.min(dp[i][j - 1][k][ODD], dp[i - 1][j][k][ODD]);
                            }
                            // From previous EVEN (cost 1 change)
                            if (dp[i - 1][j][k][EVEN] != INF) {
                                dp[i][j - 1][k][ODD] = Math.min(dp[i][j - 1][k][ODD], 1 + dp[i - 1][j][k][EVEN]);
                            }
                        }

                        // Transitioning to EVEN consumes 1 Even capacity (k -> k-1)
                        if (k > 0) {
                            // From previous EVEN (cost 0 change)
                            if (dp[i - 1][j][k][EVEN] != INF) {
                                dp[i][j][k - 1][EVEN] = Math.min(dp[i][j][k - 1][EVEN], dp[i - 1][j][k][EVEN]);
                            }
                            // From previous ODD (cost 1 change)
                            if (dp[i - 1][j][k][ODD] != INF) {
                                dp[i][j][k - 1][EVEN] = Math.min(dp[i][j][k - 1][EVEN], 1 + dp[i - 1][j][k][ODD]);
                            }
                        }

                    } else {
                        // Fixed Parity
                        int p = parities[i]; // 0 or 1

                        // Original logic: indices j, k remain the same for fixed numbers
                        // Option 1: Previous was same parity (cost 0)
                        if (dp[i - 1][j][k][p] != INF) {
                            dp[i][j][k][p] = Math.min(dp[i][j][k][p], dp[i - 1][j][k][p]);
                        }
                        // Option 2: Previous was different parity (cost 1)
                        int prevP = 1 - p;
                        if (dp[i - 1][j][k][prevP] != INF) {
                            dp[i][j][k][p] = Math.min(dp[i][j][k][p], 1 + dp[i - 1][j][k][prevP]);
                        }
                    }
                }
            }
        }

        // Extract result
        // We check both ending parities (Even and Odd) to find the minimum cost
        int ans = dp[n - 1][0][0][EVEN];
        if (dp[n - 1][0][0][ODD] != INF && (ans == INF || dp[n - 1][0][0][ODD] < ans)) {
            ans = dp[n - 1][0][0][ODD];
        }

        // Output result
        // If ans is INF, it implies no valid sequence was found.
        System.out.println(ans);
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

/**
 * Solves a dynamic programming problem to find the minimum number of changes
 * required to make an array alternate between 0 and 1, respecting given counts.
 */
public class Main {

    /**
     * FastScanner for efficient and maintainable input reading.
     */
    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    e.printStackTrace();
                    return null;
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            String s = next();
            return s == null ? 0 : Integer.parseInt(s);
        }
    }

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner();
        int n = scanner.nextInt();

        if (n == 0) {
            System.out.println(0);
            return;
        }

        int[] a = new int[n];
        int zerosNeeded = n / 2;
        int onesNeeded = (n + 1) / 2;

        // Read input and preprocess: 0 -> -1 (wildcard), others -> 0 or 1
        for (int i = 0; i < n; i++) {
            int val = scanner.nextInt();
            if (val == 0) {
                a[i] = -1; // Represents a wildcard that can be 0 or 1
            } else {
                a[i] = val % 2; // 0 or 1
                if (a[i] == 0) {
                    zerosNeeded--;
                } else {
                    onesNeeded--;
                }
            }
        }

        /**
         * dp[i][j][k][last] stores the minimum operations to fill the first i elements
         * with j zeros and k ones remaining to be placed, ending with 'last' (0 or 1).
         */
        int[][][][] dp = new int[n + 1][n + 1][n + 1][2];

        // Initialize DP table with a sentinel value representing infinity
        for (int i = 0; i <= n; i++) {
            for (int j = 0; j <= n; j++) {
                for (int k = 0; k <= n; k++) {
                    dp[i][j][k][0] = Integer.MAX_VALUE;
                    dp[i][j][k][1] = Integer.MAX_VALUE;
                }
            }
        }

        // Base case: First element
        if (a[0] == -1) {
            if (zerosNeeded > 0) dp[1][zerosNeeded - 1][onesNeeded][0] = 0;
            if (onesNeeded > 0) dp[1][zerosNeeded][onesNeeded - 1][1] = 0;
        } else {
            dp[1][zerosNeeded][onesNeeded][a[0]] = 0;
        }

        // DP Transitions
        for (int i = 2; i <= n; i++) {
            int currentVal = a[i - 1];
            for (int j = 0; j <= zerosNeeded; j++) {
                for (int k = 0; k <= onesNeeded; k++) {
                    for (int last = 0; last < 2; last++) {
                        int prevCost = dp[i - 1][j][k][last];
                        if (prevCost == Integer.MAX_VALUE) continue;

                        if (currentVal != -1) {
                            // Current position is fixed to 0 or 1
                            int cost = prevCost + (last != currentVal ? 1 : 0);
                            if (cost < dp[i][j][k][currentVal]) {
                                dp[i][j][k][currentVal] = cost;
                            }
                        } else {
                            // Current position is wildcard (-1): try placing 0 or 1
                            if (j > 0) {
                                int cost = prevCost + (last != 0 ? 1 : 0);
                                if (cost < dp[i][j - 1][k][0]) {
                                    dp[i][j - 1][k][0] = cost;
                                }
                            }
                            if (k > 0) {
                                int cost = prevCost + (last != 1 ? 1 : 0);
                                if (cost < dp[i][j][k - 1][1]) {
                                    dp[i][j][k - 1][1] = cost;
                                }
                            }
                        }
                    }
                }
            }
        }

        // The answer is the minimum cost to fill all n positions with 0 zeros and 0 ones remaining
        int result = Math.min(dp[n][0][0][0], dp[n][0][0][1]);
        System.out.println(result);
    }
}

import java.io.*;
import java.util.*;

public class Main {

    public static void main(String[] args) {
        FastScanner in = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out);
        try {
            int result = solve(in);
            out.println(result);
        } catch (Exception e) {
            e.printStackTrace();
        } finally {
            out.flush();
            out.close();
        }
    }

    /**
     * Core logic to calculate the minimum operations required.
     */
    private static int solve(FastScanner in) throws Exception {
        int n = in.nextInt();
        int[] values = new int[n];
        int existingOdds = 0;
        int existingEvens = 0;

        // Read input and count existing parities
        for (int i = 0; i < n; i++) {
            values[i] = in.nextInt();
            if (values[i] % 2 != 0) {
                existingOdds++;
            } else if (values[i] != 0) {
                existingEvens++;
            }
        }

        // Calculate how many zero slots can be filled with odd/even numbers
        int oddSlots = n / 2 - existingOdds + (n % 2);
        int evenSlots = n / 2 - existingEvens;

        // Find the first non-zero element to handle leading zeros
        int firstNonZero = 0;
        while (firstNonZero < n && values[firstNonZero] == 0) {
            firstNonZero++;
        }

        // Edge case: all elements are zero
        if (firstNonZero == n) {
            return Math.min(n - 1, 1);
        }

        // Extract contiguous zero segments
        List<ZeroSegment> gaps = new ArrayList<>();
        if (firstNonZero > 0) {
            gaps.add(new ZeroSegment(0, firstNonZero - 1));
        }

        int cur = firstNonZero;
        while (cur < n) {
            while (cur < n && values[cur] != 0) {
                cur++;
            }
            int start = cur;
            while (cur < n && values[cur] == 0) {
                cur++;
            }
            if (start < cur) {
                gaps.add(new ZeroSegment(start, cur - 1));
            }
        }

        // Classify gaps based on surrounding parities
        List<ZeroSegment> oddGaps = new ArrayList<>();
        List<ZeroSegment> evenGaps = new ArrayList<>();
        int mixedGapsCount = 0;

        for (ZeroSegment gap : gaps) {
            gap.size = gap.end - gap.start + 1;
            if (gap.start == 0 || gap.end == n - 1) {
                continue; // Handled separately as boundary gaps
            }

            int prevVal = values[(gap.start + n - 1) % n];
            int nextVal = values[gap.end + 1];

            if (prevVal % 2 == 0 && nextVal % 2 == 0) {
                gap.type = 0;
                evenGaps.add(gap);
            } else if (prevVal % 2 != 0 && nextVal % 2 != 0) {
                gap.type = 1;
                oddGaps.add(gap);
            } else {
                gap.type = 2;
                mixedGapsCount++;
            }
        }

        // Process gaps by size to maximize slot utilization
        oddGaps.sort(Comparator.comparingInt(g -> g.size));
        evenGaps.sort(Comparator.comparingInt(g -> g.size));

        for (ZeroSegment gap : oddGaps) {
            if (gap.size <= oddSlots) {
                oddSlots -= gap.size;
            } else {
                mixedGapsCount += 2;
            }
        }

        for (ZeroSegment gap : evenGaps) {
            if (gap.size <= evenSlots) {
                evenSlots -= gap.size;
            } else {
                mixedGapsCount += 2;
            }
        }

        // Handle boundary gaps (first and last in the list)
        if (!gaps.isEmpty()) {
            ZeroSegment firstGap = gaps.get(0);
            if (firstGap.start == 0) {
                int nextVal = values[firstGap.end + 1];
                if (nextVal % 2 != 0) {
                    if (oddSlots < firstGap.size) {
                        mixedGapsCount++;
                    } else {
                        oddSlots -= firstGap.size;
                    }
                } else {
                    if (evenSlots < firstGap.size) {
                        mixedGapsCount++;
                    } else {
                        evenSlots -= firstGap.size;
                    }
                }
            }

            ZeroSegment lastGap = gaps.get(gaps.size() - 1);
            if (lastGap.end == n - 1) {
                int prevVal = values[lastGap.start - 1];
                if (prevVal % 2 != 0) {
                    if (oddSlots < lastGap.size) {
                        mixedGapsCount++;
                    } else {
                        oddSlots -= lastGap.size;
                    }
                } else {
                    if (evenSlots < lastGap.size) {
                        mixedGapsCount++;
                    } else {
                        evenSlots -= lastGap.size;
                    }
                }
            }
        }

        // Count adjacent parity mismatches in non-zero regions
        for (int i = 0; i < n - 1; i++) {
            if (values[i] == 0 || values[i + 1] == 0) continue;
            if (values[i] % 2 != values[i + 1] % 2) {
                mixedGapsCount++;
            }
        }

        return mixedGapsCount;
    }

    /**
     * Represents a contiguous segment of zeros in the array.
     */
    private static class ZeroSegment {
        int start, end, size, type;

        ZeroSegment(int start, int end) {
            this.start = start;
            this.end = end;
        }

        @Override
        public String toString() {
            return "(" + start + ", " + end + ")";
        }
    }

    /**
     * Fast input reader for competitive programming / performance-critical I/O.
     */
    private static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

/**
 * Refactored solution optimized for maintainability and code quality.
 * 
 * Key Improvements:
 * - Replaced global static state with instance fields for better testability.
 * - Applied meaningful variable and method names.
 * - Replaced magic numbers (e.g., n+5, -1) with named constants.
 * - Streamlined FastReader with proper exception handling.
 * - Preserved original algorithmic logic and performance characteristics.
 */
public class Main {

    // Instance fields to avoid global mutable state
    private int numElements;
    private int[] elementParity; // 0: zero, 1: odd, 2: even
    private int[] zeroPrefixCount;
    private int evenCount;
    private int oddCount;
    private int[][][] memo;
    private static final int INF_COST = Integer.MAX_VALUE / 2;

    public static void main(String[] args) {
        // Increase stack size to prevent StackOverflowError for deep recursion
        new Thread(null, () -> new Main().solve(), "solver", 1 << 26).start();
    }

    private void solve() {
        FastReader reader = new FastReader();
        PrintWriter writer = new PrintWriter(System.out);

        try {
            numElements = reader.nextInt();
            elementParity = new int[numElements + 1];
            zeroPrefixCount = new int[numElements + 1];
            evenCount = numElements / 2;
            oddCount = (int) Math.ceil(numElements / 2.0);

            if (numElements == 1) {
                writer.println(0);
            } else {
                // Read input and classify parities
                for (int i = 1; i <= numElements; i++) {
                    int value = reader.nextInt();
                    if (value == 0) {
                        elementParity[i] = 0;
                        zeroPrefixCount[i] = 1;
                    } else if ((value & 1) == 0) {
                        elementParity[i] = 2;
                        evenCount--;
                    } else {
                        elementParity[i] = 1;
                        oddCount--;
                    }
                }

                // Build prefix sum array for zero counts
                for (int i = 1; i <= numElements; i++) {
                    zeroPrefixCount[i] += zeroPrefixCount[i - 1];
                }

                // Initialize memoization table with -1 (uncomputed state)
                for (int i = 0; i <= numElements; i++) {
                    for (int j = 0; j <= numElements / 2; j++) {
                        memo[i][j][0] = memo[i][j][1] = memo[i][j][2] = -1;
                    }
                }

                writer.println(calculate(1, evenCount, -1));
            }
        } catch (Exception e) {
            // Fallback for unexpected input errors
            e.printStackTrace();
        } finally {
            writer.flush();
            writer.close();
        }
    }

    /**
     * Recursive DP function with memoization.
     * 
     * @param currentIndex     Current position in the sequence (1-based)
     * @param evensRemaining   Number of even numbers still available to place
     * @param previousParity   Parity of the previously placed number (0, 1, 2, or -1)
     * @return Minimum cost to complete the sequence from this state
     */
    private int calculate(int currentIndex, int evensRemaining, int previousParity) {
        // Calculate remaining odds based on original formula
        int oddsRemaining = oddCount - (zeroPrefixCount[currentIndex - 1] - (evenCount - evensRemaining));

        // Base case: first position
        if (currentIndex == 1) {
            if (elementParity[currentIndex] == 0) {
                int minCost = INF_COST;
                if (oddsRemaining > 0) {
                    minCost = Math.min(minCost, calculate(currentIndex + 1, evensRemaining, 1));
                }
                if (evensRemaining > 0) {
                    minCost = Math.min(minCost, calculate(currentIndex + 1, evensRemaining - 1, 2));
                }
                return minCost;
            } else {
                return calculate(currentIndex + 1, evensRemaining, elementParity[currentIndex]);
            }
        } else {
            // Return memoized result if available
            if (memo[currentIndex][evensRemaining][previousParity] != -1) {
                return memo[currentIndex][evensRemaining][previousParity];
            }

            int result;
            if (elementParity[currentIndex] == 0) {
                int minCost = INF_COST;
                int cost;

                // Option 1: Place an odd number
                if (oddsRemaining > 0) {
                    cost = (previousParity == 2) ? 1 : 0;
                    if (currentIndex < numElements) {
                        minCost = Math.min(minCost, calculate(currentIndex + 1, evensRemaining, 1) + cost);
                    } else {
                        minCost = Math.min(minCost, cost);
                    }
                }

                // Option 2: Place an even number
                if (evensRemaining > 0) {
                    cost = (previousParity == 1) ? 1 : 0;
                    if (currentIndex < numElements) {
                        minCost = Math.min(minCost, calculate(currentIndex + 1, evensRemaining - 1, 2) + cost);
                    } else {
                        minCost = Math.min(minCost, cost);
                    }
                }
                result = minCost;
            } else {
                // Fixed parity: must match input
                int cost = (previousParity != elementParity[currentIndex]) ? 1 : 0;
                if (currentIndex < numElements) {
                    result = cost + calculate(currentIndex + 1, evensRemaining, elementParity[currentIndex]);
                } else {
                    result = cost;
                }
            }

            // Store and return result
            memo[currentIndex][evensRemaining][previousParity] = result;
            return result;
        }
    }

    /**
     * High-performance I/O helper for competitive programming environments.
     */
    private static class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input", e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.StringTokenizer;

public class Solution {

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner();
        PrintWriter out = new PrintWriter(System.out);

        int testCases = 1;
        while (testCases-- > 0) {
            int n = scanner.nextInt();
            int[] p = new int[n];
            for (int i = 0; i < n; i++) {
                p[i] = scanner.nextInt();
            }

            out.println(solve(n, p));
        }

        out.flush();
        out.close();
    }

    /**
     * Calculates the minimum operations/cost based on parity constraints and zero segments.
     * 
     * @param n  Size of the array
     * @param p  Input array containing numbers and zeros
     * @return   Calculated cost/count
     */
    private static int solve(int n, int[] p) {
        // Target remaining capacity for even (index 0) and odd (index 1) numbers
        int[] remainingCapacity = new int[2];
        remainingCapacity[0] = n / 2;
        remainingCapacity[1] = (n + 1) / 2;

        // Decrement capacity for existing non-zero numbers
        for (int val : p) {
            if (val != 0) {
                remainingCapacity[val % 2]--;
            }
        }

        // Segments of consecutive zeros bounded by same-parity neighbors
        List<Integer> boundedEvenSegments = new ArrayList<>();
        List<Integer> boundedOddSegments = new ArrayList<>();

        // Prefix/Suffix segments of zeros (only one neighbor exists)
        List<Integer> boundaryEvenSegments = new ArrayList<>();
        List<Integer> boundaryOddSegments = new ArrayList<>();

        int cost = 0;

        // Identify and categorize zero segments
        for (int i = 0; i < n; i++) {
            if (p[i] == 0) {
                int start = i;
                while (i < n - 1 && p[i + 1] == 0) {
                    i++;
                }
                int length = i - start + 1;

                int leftNeighbor = (start > 0) ? p[start - 1] : -1;
                int rightNeighbor = (i < n - 1) ? p[i + 1] : -1;

                if (leftNeighbor != -1 && rightNeighbor != -1) {
                    if (leftNeighbor % 2 == rightNeighbor % 2) {
                        if (leftNeighbor % 2 == 0) {
                            boundedEvenSegments.add(length);
                        } else {
                            boundedOddSegments.add(length);
                        }
                    } else {
                        // Mismatched neighbors incur a base cost
                        cost++;
                    }
                } else if (leftNeighbor == -1) {
                    // Prefix segment
                    if (rightNeighbor % 2 == 0) {
                        boundaryEvenSegments.add(length);
                    } else {
                        boundaryOddSegments.add(length);
                    }
                } else {
                    // Suffix segment
                    if (leftNeighbor % 2 == 0) {
                        boundaryEvenSegments.add(length);
                    } else {
                        boundaryOddSegments.add(length);
                    }
                }
            }
        }

        // Sort segments to apply greedy strategy (fill smaller segments first)
        Collections.sort(boundedEvenSegments);
        Collections.sort(boundedOddSegments);

        // Greedily fill bounded segments (cost 2 per unfilled segment)
        cost += fillSegments(boundedEvenSegments, remainingCapacity, 0, 2);
        cost += fillSegments(boundedOddSegments, remainingCapacity, 1, 2);

        Collections.sort(boundaryEvenSegments);
        Collections.sort(boundaryOddSegments);

        // Greedily fill boundary/prefix/suffix segments (cost 1 per unfilled segment)
        cost += fillSegments(boundaryEvenSegments, remainingCapacity, 0, 1);
        cost += fillSegments(boundaryOddSegments, remainingCapacity, 1, 1);

        // Count parity mismatches between adjacent non-zero elements
        for (int i = 0; i < n - 1; i++) {
            if (p[i] != 0 && p[i + 1] != 0) {
                if (p[i] % 2 != p[i + 1] % 2) {
                    cost++;
                }
            }
        }

        return cost;
    }

    /**
     * Greedily fills segments up to the available capacity.
     * Updates the capacity array and returns the cost of unfilled segments.
     */
    private static int fillSegments(List<Integer> segments, int[] capacity, int parity, int costPerUnfilled) {
        int cost = 0;
        int usedCapacity = 0;
        int segmentsFilled = 0;

        for (int length : segments) {
            if (usedCapacity + length > capacity[parity]) {
                break;
            }
            usedCapacity += length;
            segmentsFilled++;
        }

        capacity[parity] -= usedCapacity;
        cost = costPerUnfilled * (segments.size() - segmentsFilled);
        return cost;
    }

    /**
     * Fast I/O helper class for competitive programming.
     */
    static class FastScanner {
        private final BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        private StringTokenizer st = new StringTokenizer("");

        public String next() {
            while (!st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Solves the mod interval complement counting problem.
 * Reads an array of integers, identifies streaks of zeros,
 * and calculates the minimum number of adjacent value transitions
 * after optimally filling the zero streaks.
 */
public class ModIntervalSolver {

    public static void main(String[] args) throws IOException {
        // Use try-with-resources for automatic and safe resource management
        try (FastScanner scanner = new FastScanner(System.in);
             PrintWriter writer = new PrintWriter(new BufferedOutputStream(System.out))) {

            ModIntervalSolver solver = new ModIntervalSolver();
            int result = solver.calculateResult(scanner);
            writer.println(result);
        }
        // PrintWriter.close() automatically flushes the buffer
    }

    /**
     * Reads input and calculates the complement count based on mod intervals.
     */
    int calculateResult(FastScanner scanner) throws IOException {
        int n = scanner.nextInt();

        // Edge case: A single element has zero adjacent transitions
        if (n == 1) {
            return 0;
        }

        int[] parityArray = new int[n];
        List<StreakInterval> streakIntervals = new ArrayList<>();
        int[] availableCounts = {n / 2, (n + 1) / 2};
        int complementCount = 0;
        int consecutiveZerosLength = 0;

        for (int i = 0; i < n; i++) {
            int input = scanner.nextInt();
            if (input == 0) {
                parityArray[i] = -1; // Represents a zero/streak to be filled
                consecutiveZerosLength++;
            } else {
                parityArray[i] = input % 2;
                availableCounts[parityArray[i]]--;

                if (consecutiveZerosLength > 0) {
                    streakIntervals.add(new StreakInterval(i - consecutiveZerosLength, i));
                    consecutiveZerosLength = 0;
                }

                if (i > 0 && parityArray[i - 1] != -1 && parityArray[i] != parityArray[i - 1]) {
                    complementCount++;
                }
            }
        }

        // Handle trailing streak of zeros
        if (consecutiveZerosLength > 0) {
            streakIntervals.add(new StreakInterval(n - consecutiveZerosLength, n));
        }

        // Sort intervals by length (ascending) for greedy filling strategy
        Collections.sort(streakIntervals);

        // Process non-edge intervals first, then edge intervals
        applyParityIntervals(streakIntervals, availableCounts, parityArray, false);
        applyParityIntervals(streakIntervals, availableCounts, parityArray, true);

        // Calculate final complement count
        for (StreakInterval interval : streakIntervals) {
            int requiredParity = getRequiredParity(interval, parityArray);
            if (requiredParity != -1 && interval.start != 0 && interval.end != n) {
                // Internal interval with matching boundaries adds 2 transitions
                complementCount += 2;
            } else {
                // Edge interval or mismatched boundaries adds 1 transition
                complementCount++;
            }
        }

        return complementCount;
    }

    /**
     * Fills streak intervals with available parity counts if they match boundaries.
     * @param allowEdges If true, processes intervals at the start or end of the array.
     */
    private void applyParityIntervals(List<StreakInterval> intervals, int[] availableCounts,
                                      int[] parityArray, boolean allowEdges) {
        for (Iterator<StreakInterval> it = intervals.iterator(); it.hasNext(); ) {
            StreakInterval interval = it.next();
            int requiredParity = getRequiredParity(interval, parityArray);
            boolean isEdge = (interval.start == 0 || interval.end == parityArray.length);

            if (requiredParity != -1 && (!allowEdges || isEdge) && interval.length() <= availableCounts[requiredParity]) {
                availableCounts[requiredParity] -= interval.length();
                it.remove();
            }
        }
    }

    /**
     * Determines the required parity (0 or 1) for an interval based on its neighbors.
     * Returns -1 if the interval spans the entire array or neighbors have mismatched parities.
     */
    private int getRequiredParity(StreakInterval interval, int[] parityArray) {
        int n = parityArray.length;
        if (interval.start == 0 && interval.end == n) {
            return -1;
        } else if (interval.start == 0) {
            return parityArray[interval.end];
        } else if (interval.end == n) {
            return parityArray[interval.start - 1];
        } else {
            if (parityArray[interval.start - 1] == parityArray[interval.end]) {
                return parityArray[interval.start - 1];
            } else {
                return -1;
            }
        }
    }

    /**
     * Represents a contiguous streak of zeros in the input array.
     */
    static class StreakInterval implements Comparable<StreakInterval> {
        final int start;
        final int end;

        StreakInterval(int start, int end) {
            this.start = start;
            this.end = end;
        }

        int length() {
            return end - start;
        }

        @Override
        public int compareTo(StreakInterval other) {
            return Integer.compare(this.length(), other.length());
        }
    }

    /**
     * Fast input scanner optimized for competitive programming.
     */
    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer tokenizer;

        FastScanner(InputStream is) {
            this.br = new BufferedReader(new InputStreamReader(is));
        }

        FastScanner(File file) throws FileNotFoundException {
            this(new FileInputStream(file));
        }

        String nextLine() throws IOException {
            return br.readLine();
        }

        String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        int nextInt() throws IOException {
            String s = next();
            if (s == null) throw new IOException("Unexpected end of input");
            return Integer.parseInt(s);
        }
    }
}

import java.io.*;
import java.util.*;

public class Main {
    // Constants for parity states
    private static final int NO_PREV = 0;
    private static final int EVEN = 1;
    private static final int ODD = 2;

    private static int n;
    private static int[] parities;
    private static int[][][][] memo;

    /**
     * Recursive DP function with memoization.
     *
     * @param index      Current position in the array (0 to n)
     * @param prevParity Parity of the previous element (0=none, 1=even, 2=odd)
     * @param evensLeft  Number of missing even values remaining to place
     * @param oddsLeft   Number of missing odd values remaining to place
     * @return Minimum cost to fill the remaining positions, or Integer.MAX_VALUE if invalid
     */
    private static int solve(int index, int prevParity, int evensLeft, int oddsLeft) {
        // Base case: all positions filled
        if (index == n) {
            return (evensLeft == 0 && oddsLeft == 0) ? 0 : Integer.MAX_VALUE;
        }

        // Return memoized result if available
        if (memo[index][prevParity][evensLeft][oddsLeft] != -1) {
            return memo[index][prevParity][evensLeft][oddsLeft];
        }

        int result = Integer.MAX_VALUE;

        if (parities[index] == 0) {
            // Current position is missing; we must place a number
            if (evensLeft == 0 && oddsLeft == 0) {
                return memo[index][prevParity][evensLeft][oddsLeft] = Integer.MAX_VALUE;
            }

            int costEven = Integer.MAX_VALUE;
            int costOdd = Integer.MAX_VALUE;

            // Try placing an even number
            if (evensLeft > 0) {
                costEven = solve(index + 1, EVEN, evensLeft - 1, oddsLeft);
                if (costEven != Integer.MAX_VALUE && prevParity != NO_PREV && prevParity != EVEN) {
                    costEven++;
                }
            }

            // Try placing an odd number
            if (oddsLeft > 0) {
                costOdd = solve(index + 1, ODD, evensLeft, oddsLeft - 1);
                if (costOdd != Integer.MAX_VALUE && prevParity != NO_PREV && prevParity != ODD) {
                    costOdd++;
                }
            }

            result = Math.min(costEven, costOdd);
        } else {
            // Current position has a fixed parity (from input)
            int cost = solve(index + 1, parities[index], evensLeft, oddsLeft);
            if (cost != Integer.MAX_VALUE && prevParity != NO_PREV && prevParity != parities[index]) {
                cost++;
            }
            result = cost;
        }

        return memo[index][prevParity][evensLeft][oddsLeft] = result;
    }

    public static void main(String[] args) throws IOException {
        FastScanner sc = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            n = sc.nextInt();
            parities = new int[n];
            boolean[] present = new boolean[n + 1];

            // Read input and determine parities of fixed numbers
            for (int i = 0; i < n; i++) {
                int val = sc.nextInt();
                if (val != 0) {
                    parities[i] = (val % 2 == 0) ? EVEN : ODD;
                    present[val] = true;
                }
            }

            // Count missing even and odd numbers from 1 to n
            int evensLeft = 0;
            int oddsLeft = 0;
            for (int i = 1; i <= n; i++) {
                if (!present[i]) {
                    if (i % 2 == 0) evensLeft++;
                    else oddsLeft++;
                }
            }

            // Initialize DP table with -1
            memo = new int[n + 1][3][n + 1][n + 1];
            for (int i = 0; i <= n; i++) {
                for (int j = 0; j < 3; j++) {
                    for (int k = 0; k <= n; k++) {
                        Arrays.fill(memo[i][j][k], -1);
                    }
                }
            }

            out.println(solve(0, NO_PREV, evensLeft, oddsLeft));
        } finally {
            out.flush();
            out.close();
        }
    }

    /**
     * Fast I/O helper class for competitive programming.
     */
    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            String s = next();
            if (s == null) throw new NoSuchElementException();
            return Integer.parseInt(s);
        }
    }
}

import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) {
        // Increase stack size to prevent StackOverflowError during deep recursion
        new Thread(null, new Main(), "Solver", 1L << 28).start();
    }

    public void run() {
        FastScanner scanner = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out);

        int n = scanner.nextInt();
        int[] sequence = new int[n];
        for (int i = 0; i < n; i++) {
            sequence[i] = scanner.nextInt();
        }

        // Determine available odd and even numbers that are not already in the sequence
        boolean[] isUsed = new boolean[n + 1];
        for (int val : sequence) {
            if (val != 0) {
                isUsed[val] = true;
            }
        }

        int availableOdds = 0;
        int availableEvens = 0;
        for (int i = 1; i <= n; i++) {
            if (!isUsed[i]) {
                if (i % 2 == 0) {
                    availableEvens++;
                } else {
                    availableOdds++;
                }
            }
        }

        // Initialize memoization table with -1 to indicate uncomputed states
        int[][][][] memo = new int[n][n + 1][n + 1][2];
        for (int[][][] layer : memo) {
            for (int[][] subLayer : layer) {
                Arrays.fill(subLayer, -1);
            }
        }

        int result;
        int firstValue = sequence[0];
        if (firstValue != 0) {
            int firstParity = firstValue % 2;
            result = solve(1, availableOdds, availableEvens, firstParity, sequence, memo);
        } else {
            result = Integer.MAX_VALUE;
            if (availableOdds > 0) {
                result = Math.min(result, solve(1, availableOdds - 1, availableEvens, 1, sequence, memo));
            }
            if (availableEvens > 0) {
                result = Math.min(result, solve(1, availableOdds, availableEvens - 1, 0, sequence, memo));
            }
        }

        out.println(result);
        out.flush();
    }

    /**
     * Recursive function with memoization to find the minimum parity switches.
     *
     * @param index          Current position in the sequence
     * @param oddCount       Number of available odd numbers to place
     * @param evenCount      Number of available even numbers to place
     * @param previousParity Parity of the previous element (0 for even, 1 for odd)
     * @param sequence       The input array
     * @param memo           Memoization table
     * @return Minimum cost from this state onwards
     */
    private int solve(int index, int oddCount, int evenCount, int previousParity, int[] sequence, int[][][][] memo) {
        if (index == sequence.length) {
            return 0;
        }
        if (memo[index][oddCount][evenCount][previousParity] != -1) {
            return memo[index][oddCount][evenCount][previousParity];
        }

        int minCost = Integer.MAX_VALUE;
        int currentValue = sequence[index];

        if (currentValue == 0) {
            // Option 1: Place an available odd number
            if (oddCount > 0) {
                int cost = previousParity == 1 ? 0 : 1;
                minCost = Math.min(minCost, solve(index + 1, oddCount - 1, evenCount, 1, sequence, memo) + cost);
            }
            // Option 2: Place an available even number
            if (evenCount > 0) {
                int cost = previousParity == 0 ? 0 : 1;
                minCost = Math.min(minCost, solve(index + 1, oddCount, evenCount - 1, 0, sequence, memo) + cost);
            }
        } else {
            // Current value is fixed in the input
            int currentParity = currentValue % 2;
            int cost = previousParity == currentParity ? 0 : 1;
            minCost = solve(index + 1, oddCount, evenCount, currentParity, sequence, memo) + cost;
        }

        return memo[index][oddCount][evenCount][previousParity] = minCost;
    }

    /**
     * Fast Scanner for efficient input reading. Replaces the original buggy custom reader
     * with a standard, maintainable, and robust implementation.
     */
    static class FastScanner {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastScanner(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) {
                        return null;
                    }
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.DataInputStream;
import java.io.IOException;

/**
 * Main class containing the solution logic and a FastScanner utility.
 * Refactored for improved maintainability, readability, and robustness.
 */
public class Main {

    /**
     * FastScanner class for efficient input reading.
     * Replaces the original Reader class with a cleaner, standard implementation.
     */
    static class FastScanner {
        private final DataInputStream din;
        private final byte[] buffer;
        private int bufferPointer, bytesRead;

        private static final int BUFFER_SIZE = 1 << 16;

        public FastScanner() {
            din = new DataInputStream(System.in);
            buffer = new byte[BUFFER_SIZE];
            bufferPointer = bytesRead = 0;
        }

        /**
         * Reads a single byte from the input buffer.
         */
        private byte read() throws IOException {
            if (bufferPointer == bytesRead) {
                fillBuffer();
            }
            return buffer[bufferPointer++];
        }

        private void fillBuffer() throws IOException {
            bytesRead = din.read(buffer, bufferPointer = 0, BUFFER_SIZE);
            if (bytesRead == -1) {
                buffer[0] = -1;
            }
        }

        /**
         * Reads the next integer from input.
         */
        public int nextInt() throws IOException {
            int ret = 0;
            byte c = read();
            while (c <= ' ') {
                c = read();
            }
            boolean neg = (c == '-');
            if (neg) {
                c = read();
            }
            do {
                ret = ret * 10 + c - '0';
            } while ((c = read()) >= '0' && c <= '9');

            if (neg) {
                return -ret;
            }
            return ret;
        }

        /**
         * Reads the next long from input.
         */
        public long nextLong() throws IOException {
            long ret = 0;
            byte c = read();
            while (c <= ' ') {
                c = read();
            }
            boolean neg = (c == '-');
            if (neg) {
                c = read();
            }
            do {
                ret = ret * 10 + c - '0';
            } while ((c = read()) >= '0' && c <= '9');

            if (neg) {
                return -ret;
            }
            return ret;
        }

        /**
         * Reads the next double from input.
         */
        public double nextDouble() throws IOException {
            double ret = 0, div = 1;
            byte c = read();
            while (c <= ' ') {
                c = read();
            }
            boolean neg = (c == '-');
            if (neg) {
                c = read();
            }

            do {
                ret = ret * 10 + c - '0';
            } while ((c = read()) >= '0' && c <= '9');

            if (c == '.') {
                while ((c = read()) >= '0' && c <= '9') {
                    ret += (c - '0') / (div *= 10);
                }
            }

            if (neg) {
                return -ret;
            }
            return ret;
        }

        public void close() throws IOException {
            if (din != null) {
                din.close();
            }
        }
    }

    public static void main(String[] args) throws IOException {
        FastScanner scanner = new FastScanner();

        // Read array size
        int n = scanner.nextInt();

        // Read array elements
        int[] numbers = new int[n];
        for (int i = 0; i < n; i++) {
            numbers[i] = scanner.nextInt();
        }

        // Target number of even elements required
        int targetEvenCount = n / 2;
        long mod = 1_000_000_007L;

        // DP Table initialization
        // dp[i][j][k]
        // i: number of elements processed
        // j: number of even elements placed so far
        // k: parity of the last placed element (0 for even, 1 for odd)
        // Dimensions: [n+1][n+1][2] to handle dynamic n safely (replaces hardcoded 1000)
        long[][][] dp = new long[n + 1][n + 1][2];

        // Initialize DP table with modulo value (representing infinity/unreachable)
        for (int i = 0; i <= n; i++) {
            for (int j = 0; j <= n; j++) {
                dp[i][j][0] = mod;
                dp[i][j][1] = mod;
            }
        }

        // Base case: 0 elements processed, 0 evens, cost is 0
        dp[0][0][0] = 0;
        dp[0][0][1] = 0;

        // Fill DP table
        for (int i = 1; i <= n; i++) {
            // Optimization: j (count of evens) cannot exceed i-1 before processing current element
            for (int j = 0; j < i; j++) { 
                for (int k = 0; k < 2; k++) {
                    long prev = dp[i - 1][j][k];

                    // If previous state is unreachable, skip
                    if (prev == mod) continue;

                    int currentVal = numbers[i - 1];

                    if (currentVal != 0) {
                        if (currentVal % 2 == 0) {
                            // Current number is Even
                            // Transition to state with parity 0 (Even)
                            // Cost increases by k (if previous was Odd (1), cost +1)
                            dp[i][j + 1][0] = Math.min(dp[i][j + 1][0], prev + k);
                        } else {
                            // Current number is Odd
                            // Transition to state with parity 1 (Odd)
                            // Cost increases by 1-k (if previous was Even (0), cost +1)
                            dp[i][j][1] = Math.min(dp[i][j][1], prev + (1 - k));
                        }
                    } else {
                        // Current number is 0 (Wildcard)
                        // Can be treated as Even or Odd

                        // Option 1: Treat as Even (parity 0)
                        // Cost logic: 1 if prev was odd, 0 if even
                        int costEven = (k == 1) ? 1 : 0;
                        dp[i][j + 1][0] = Math.min(dp[i][j + 1][0], prev + costEven);

                        // Option 2: Treat as Odd (parity 1)
                        // Cost logic: 1 if prev was even, 0 if odd
                        int costOdd = (k == 0) ? 1 : 0;
                        dp[i][j][1] = Math.min(dp[i][j][1], prev + costOdd);
                    }
                }
            }
        }

        // Result is the minimum cost to have exactly n/2 even numbers
        // considering the last element could be even (0) or odd (1)
        System.out.println(Math.min(dp[n][targetEvenCount][0], dp[n][targetEvenCount][1]));

        scanner.close();
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

public class Main {

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner();
        int n = scanner.nextInt();
        int[] arr = new int[n];
        int fixedOdds = 0;
        int fixedEvens = 0;

        // Read input and count numbers with fixed parity
        for (int i = 0; i < n; i++) {
            arr[i] = scanner.nextInt();
            if (arr[i] != 0) {
                if (Math.abs(arr[i]) % 2 != 0) {
                    fixedOdds++;
                } else {
                    fixedEvens++;
                }
            }
        }

        // Calculate target counts to balance odd/even positions
        int targetOdd = n / 2;
        int targetEven = n / 2;
        if (n % 2 == 1) {
            targetOdd++;
        }

        int additionalOddsNeeded = targetOdd - fixedOdds;
        int additionalEvensNeeded = targetEven - fixedEvens;

        // DP state: dp[index][usedOdds][usedEvens][currentParity]
        // currentParity: 0 for even, 1 for odd
        // Value: minimum cost to reach this state
        int INF = Integer.MAX_VALUE / 2; // Safe infinity to prevent overflow on addition
        int[][][][] dp = new int[n][additionalOddsNeeded + 1][additionalEvensNeeded + 1][2];

        // Initialize DP table with infinity
        for (int i = 0; i < n; i++) {
            for (int j = 0; j <= additionalOddsNeeded; j++) {
                for (int k = 0; k <= additionalEvensNeeded; k++) {
                    dp[i][j][k][0] = INF;
                    dp[i][j][k][1] = INF;
                }
            }
        }

        // Base case: first element
        if (arr[0] == 0) {
            if (additionalOddsNeeded > 0) {
                dp[0][1][0][1] = 0;
            }
            if (additionalEvensNeeded > 0) {
                dp[0][0][1][0] = 0;
            }
        } else {
            int parity = Math.abs(arr[0]) % 2;
            dp[0][0][0][parity] = 0;
        }

        // Fill DP table
        for (int i = 1; i < n; i++) {
            for (int j = 0; j <= additionalOddsNeeded; j++) {
                for (int k = 0; k <= additionalEvensNeeded; k++) {
                    if (arr[i] != 0) {
                        // Fixed parity element
                        int currentParity = Math.abs(arr[i]) % 2;
                        int prevEvenCost = dp[i - 1][j][k][0];
                        int prevOddCost = dp[i - 1][j][k][1];

                        // Transition from previous even
                        if (prevEvenCost != INF) {
                            dp[i][j][k][currentParity] = Math.min(
                                dp[i][j][k][currentParity],
                                prevEvenCost + Math.abs(currentParity - 0)
                            );
                        }
                        // Transition from previous odd
                        if (prevOddCost != INF) {
                            dp[i][j][k][currentParity] = Math.min(
                                dp[i][j][k][currentParity],
                                prevOddCost + Math.abs(currentParity - 1)
                            );
                        }
                    } else {
                        // Wildcard (0): can be placed as even or odd
                        // Option 1: Place an even number (parity 0)
                        if (k < additionalEvensNeeded) {
                            int prevEvenCost = dp[i - 1][j][k][0];
                            int prevOddCost = dp[i - 1][j][k][1];

                            if (prevEvenCost != INF) {
                                dp[i][j][k + 1][0] = Math.min(
                                    dp[i][j][k + 1][0],
                                    prevEvenCost // cost 0: even -> even
                                );
                            }
                            if (prevOddCost != INF) {
                                dp[i][j][k + 1][0] = Math.min(
                                    dp[i][j][k + 1][0],
                                    prevOddCost + 1 // cost 1: odd -> even
                                );
                            }
                        }

                        // Option 2: Place an odd number (parity 1)
                        if (j < additionalOddsNeeded) {
                            int prevEvenCost = dp[i - 1][j][k][0];
                            int prevOddCost = dp[i - 1][j][k][1];

                            if (prevEvenCost != INF) {
                                dp[i][j + 1][k][1] = Math.min(
                                    dp[i][j + 1][k][1],
                                    prevEvenCost + 1 // cost 1: even -> odd
                                );
                            }
                            if (prevOddCost != INF) {
                                dp[i][j + 1][k][1] = Math.min(
                                    dp[i][j + 1][k][1],
                                    prevOddCost // cost 0: odd -> odd
                                );
                            }
                        }
                    }
                }
            }
        }

        // Result is the minimum cost to reach the end with exact target counts
        int result = Math.min(
            dp[n - 1][additionalOddsNeeded][additionalEvensNeeded][0],
            dp[n - 1][additionalOddsNeeded][additionalEvensNeeded][1]
        );
        System.out.println(result);
    }

    /**
     * Efficient input reader for competitive programming.
     */
    static class FastScanner {
        private final BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        private StringTokenizer st = new StringTokenizer("");

        String next() {
            while (!st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            String token = next();
            return token == null ? 0 : Integer.parseInt(token);
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.StringTokenizer;

/**
 * Refactored solution for Codeforces 1286A.
 * Focuses on maintainability, clear variable naming, and safe loop structures.
 */
public class CF1286A {

    public static void main(String[] args) throws IOException {
        // Use try-with-resources to ensure the reader is closed automatically
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            String line = br.readLine();
            if (line == null) return;

            int arraySize = Integer.parseInt(line.trim());

            // Edge case: single element requires 0 operations
            if (arraySize == 1) {
                System.out.println(0);
                return;
            }

            StringTokenizer st = new StringTokenizer(br.readLine().trim());
            int[] parityArray = new int[arraySize];

            int evenSlots = arraySize / 2;
            int oddSlots = (arraySize + 1) / 2;
            int minOperations = 0;

            // PHASE 1: Parse input, track slot usage, and count initial parity mismatches
            for (int i = 0; i < arraySize; i++) {
                int value = Integer.parseInt(st.nextToken());

                if (value > 0) {
                    int parity = value % 2; // 1 for odd, 0 for even
                    parityArray[i] = parity;

                    if (parity == 1) {
                        oddSlots--;
                    } else {
                        evenSlots--;
                    }

                    // Check adjacent parity mismatch
                    if (i > 0 && parityArray[i - 1] != -1) {
                        int prevParity = parityArray[i - 1];
                        if (prevParity != parity) {
                            minOperations++;
                        }
                    }
                } else {
                    parityArray[i] = -1; // -1 represents an unknown/gap value
                }
            }

            // PHASE 2: Identify gaps and classify them by boundary parity and position
            List<Integer> evenInternalLens = new ArrayList<>();
            List<Integer> evenEdgeLens = new ArrayList<>();
            List<Integer> oddInternalLens = new ArrayList<>();
            List<Integer> oddEdgeLens = new ArrayList<>();

            int i = 0;
            while (i < arraySize) {
                if (parityArray[i] == -1) {
                    // Find the end of the current gap
                    int j = i;
                    while (j < arraySize && parityArray[j] == -1) {
                        j++;
                    }
                    int gapLength = j - i;

                    // Determine boundary values (-1 indicates array edge)
                    int prevBoundary = (i == 0) ? -1 : parityArray[i - 1];
                    int nextBoundary = (j == arraySize) ? -1 : parityArray[j];

                    // Classify gap: valid if at edge, or boundaries match
                    if (j == arraySize || prevBoundary == nextBoundary || prevBoundary == -1) {
                        int boundaryParity = (prevBoundary != -1) ? prevBoundary : nextBoundary;

                        if (boundaryParity == 1) {
                            if (prevBoundary == -1 || j == arraySize) {
                                oddEdgeLens.add(gapLength);
                            } else {
                                oddInternalLens.add(gapLength);
                            }
                        } else {
                            if (prevBoundary == -1 || j == arraySize) {
                                evenEdgeLens.add(gapLength);
                            } else {
                                evenInternalLens.add(gapLength);
                            }
                        }
                    } else {
                        // Boundaries differ and gap is internal -> requires 1 operation to fix
                        minOperations++;
                    }

                    // Skip past the processed gap
                    i = j;
                } else {
                    i++;
                }
            }

            // PHASE 3: Adjust operations based on available even/odd slots
            if (evenInternalLens.size() + evenEdgeLens.size() > evenSlots) {
                Collections.sort(evenInternalLens);
                Collections.sort(evenEdgeLens);
                minOperations += 2 * evenInternalLens.size() + evenEdgeLens.size();

                int available = evenSlots;
                int idx = 0;
                while (idx < evenInternalLens.size() && available >= evenInternalLens.get(idx)) {
                    minOperations -= 2;
                    available -= evenInternalLens.get(idx);
                    idx++;
                }
                idx = 0;
                while (idx < evenEdgeLens.size() && available >= evenEdgeLens.get(idx)) {
                    minOperations -= 1;
                    available -= evenEdgeLens.get(idx);
                    idx++;
                }
            } else if (oddInternalLens.size() + oddEdgeLens.size() > oddSlots) {
                Collections.sort(oddInternalLens);
                Collections.sort(oddEdgeLens);
                minOperations += 2 * oddInternalLens.size() + oddEdgeLens.size();

                int available = oddSlots;
                int idx = 0;
                while (idx < oddInternalLens.size() && available >= oddInternalLens.get(idx)) {
                    minOperations -= 2;
                    available -= oddInternalLens.get(idx);
                    idx++;
                }
                idx = 0;
                while (idx < oddEdgeLens.size() && available >= oddEdgeLens.get(idx)) {
                    minOperations -= 1;
                    available -= oddEdgeLens.get(idx);
                    idx++;
                }
            }

            System.out.println(minOperations);
        }
    }
}

