/**
 * Solves TaskC by analyzing parity distributions and zero-run lengths
 * to compute the minimum operations required.
 */
class TaskC {
    private final FastScanner sc;
    private final PrintWriter out;

    public TaskC(FastScanner sc, PrintWriter out) {
        this.sc = sc;
        this.out = out;
    }

    public void solve() {
        int n = sc.nextInt();
        int[] set = new int[n + 1];
        for (int i = 1; i <= n; i++) {
            int val = sc.nextInt();
            if (val > 0) {
                set[i] = val;
            }
        }

        int startZeros = 0;
        int endZeros = 0;
        int leadingEvenZeros = 0;
        int leadingOddZeros = 0;
        int trailingEvenZeros = 0;
        int trailingOddZeros = 0;

        // Handle leading zeros and all-zeros edge case
        if (set[1] == 0) {
            for (int i = 1; i <= n; i++) {
                if (set[i] == 0) {
                    startZeros++;
                } else {
                    if (set[i] % 2 == 0) leadingEvenZeros = startZeros;
                    else leadingOddZeros = startZeros;
                    break;
                }
            }
            if (startZeros == n) {
                out.println(n == 1 ? 0 : 1);
                return;
            }
        }

        // Handle trailing zeros
        if (set[n] == 0) {
            for (int i = n; i >= 1; i--) {
                if (set[i] == 0) {
                    endZeros++;
                } else {
                    if (set[i] % 2 == 0) trailingEvenZeros = endZeros;
                    else trailingOddZeros = endZeros;
                    break;
                }
            }
        }

        int ans = 0;
        int totalOdd = (n + 1) / 2;
        int totalEven = n - totalOdd;

        IntList evenGroupLengths = new IntList();
        IntList oddGroupLengths = new IntList();

        // Initialize with the first non-zero element to match original loop semantics
        int i = 1 + startZeros;
        int val = set[i];
        int prevParity = val % 2;
        if (prevParity == 0) totalEven--;
        else totalOdd--;

        int currentZeroRun = 0;

        // Process the middle segment between leading and trailing zeros
        for (; i <= n - endZeros; i++) {
            val = set[i];
            if (val == 0) {
                currentZeroRun++;
                continue;
            }

            int parity = val % 2;
            if (parity == 0) totalEven--;
            else totalOdd--;

            if (parity == prevParity) {
                if (currentZeroRun > 0) {
                    if (parity == 0) evenGroupLengths.add(currentZeroRun);
                    else oddGroupLengths.add(currentZeroRun);
                }
            } else {
                ans++;
            }
            prevParity = parity;
            currentZeroRun = 0;
        }

        evenGroupLengths.sort();
        oddGroupLengths.sort();

        // Apply leading/trailing zero costs for even parity
        for (int idx = 0; idx < evenGroupLengths.size(); idx++) {
            if (totalEven >= evenGroupLengths.get(idx)) {
                totalEven -= evenGroupLengths.get(idx);
            } else {
                ans += 2;
            }
        }
        if (leadingEvenZeros > 0) {
            if (totalEven >= leadingEvenZeros) totalEven -= leadingEvenZeros;
            else ans++;
        }
        if (trailingEvenZeros > 0) {
            if (totalEven >= trailingEvenZeros) totalEven -= trailingEvenZeros;
            else ans++;
        }

        // Apply leading/trailing zero costs for odd parity
        for (int idx = 0; idx < oddGroupLengths.size(); idx++) {
            if (totalOdd >= oddGroupLengths.get(idx)) {
                totalOdd -= oddGroupLengths.get(idx);
            } else {
                ans += 2;
            }
        }
        if (leadingOddZeros > 0) {
            if (totalOdd >= leadingOddZeros) totalOdd -= leadingOddZeros;
            else ans++;
        }
        if (trailingOddZeros > 0) {
            if (totalOdd >= trailingOddZeros) totalOdd -= trailingOddZeros;
            else ans++;
        }

        out.println(ans);
    }
}

/**
 * A lightweight dynamic array for primitive ints.
 * Replaces the original IntArray with a cleaner API and standard library usage.
 */
class IntList {
    private int[] data;
    private int size;

    public IntList(int capacity) {
        data = new int[Math.max(capacity, 10)];
    }

    public IntList() {
        this(20);
    }

    public void add(int value) {
        if (size == data.length) {
            data = Arrays.copyOf(data, data.length * 2);
        }
        data[size++] = value;
    }

    public void sort() {
        Arrays.sort(data, 0, size);
    }

    public int get(int index) {
        if (index < 0 || index >= size) {
            throw new IndexOutOfBoundsException("Index: " + index + ", Size: " + size);
        }
        return data[index];
    }

    public int size() {
        return size;
    }
}

/**
 * Fast input scanner optimized for competitive programming environments.
 */
class FastScanner {
    private final InputStream stream;
    private final byte[] buf = new byte[1024];
    private int curChar;
    private int numChars;

    public FastScanner(InputStream stream) {
        this.stream = stream;
    }

    int read() {
        if (numChars == -1) {
            throw new InputMismatchException();
        }
        if (curChar >= numChars) {
            curChar = 0;
            try {
                numChars = stream.read(buf);
            } catch (IOException e) {
                throw new InputMismatchException();
            }
            if (numChars <= 0) {
                return -1;
            }
        }
        return buf[curChar++];
    }

    boolean isSpaceChar(int c) {
        return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
    }

    public int nextInt() {
        return Integer.parseInt(next());
    }

    public String next() {
        int c = read();
        while (isSpaceChar(c)) {
            c = read();
        }
        StringBuilder res = new StringBuilder();
        do {
            res.appendCodePoint(c);
            c = read();
        } while (!isSpaceChar(c));
        return res.toString();
    }
}

import java.io.*;
import java.util.*;

public class Main {
    private int n;
    private int[] arr;
    private int[][][][] dp;

    public static void main(String[] args) throws IOException {
        FastScanner sc = new FastScanner(System.in);
        Main solver = new Main();
        solver.run(sc);
    }

    private void run(FastScanner sc) throws IOException {
        n = sc.nextInt();
        arr = new int[n];
        boolean[] present = new boolean[n + 1];
        int evenCount = 0, oddCount = 0;

        // Read input and track which numbers are already placed
        for (int i = 0; i < n; i++) {
            arr[i] = sc.nextInt();
            if (arr[i] != 0) {
                present[arr[i]] = true;
            }
        }

        // Count missing even and odd numbers efficiently O(N)
        for (int i = 1; i <= n; i++) {
            if (!present[i]) {
                if (i % 2 == 0) {
                    evenCount++;
                } else {
                    oddCount++;
                }
            }
        }

        // Count initial parity mismatches between fixed adjacent elements
        int initialChanges = 0;
        for (int i = 0; i < n - 1; i++) {
            if (arr[i] != 0 && arr[i + 1] != 0) {
                if (arr[i] % 2 != arr[i + 1] % 2) {
                    initialChanges++;
                }
            }
        }

        // Initialize DP table with dynamic sizing based on actual counts
        // dp[idx][even][odd][prevParity]
        // prevParity: 0 = none, 1 = odd, 2 = even
        dp = new int[n + 1][evenCount + 1][oddCount + 1][3];
        for (int[][][] layer : dp) {
            for (int[][] subLayer : layer) {
                for (int[] subSubLayer : subLayer) {
                    Arrays.fill(subSubLayer, -1);
                }
            }
        }

        // Solve and print result
        int result = initialChanges + solve(0, evenCount, oddCount, 0);
        System.out.println(result);
    }

    private int solve(int idx, int even, int odd, int prevParity) {
        // Base cases: reached end or no numbers left to place
        if (idx == n || (even == 0 && odd == 0)) {
            return 0;
        }

        // Skip fixed (non-zero) elements and update previous parity
        while (idx < n && arr[idx] != 0) {
            prevParity = (arr[idx] % 2 == 0) ? 2 : 1;
            idx++;
        }

        // Re-check base cases after skipping
        if (idx == n || (even == 0 && odd == 0)) {
            return 0;
        }

        // Return memoized result if available
        if (dp[idx][even][odd][prevParity] != -1) {
            return dp[idx][even][odd][prevParity];
        }

        int minCost = Integer.MAX_VALUE;

        // Option 1: Place an even number
        if (even > 0) {
            arr[idx] = 2; // Use 2 as a parity marker for even
            int cost = solve(idx + 1, even - 1, odd, 2);
            arr[idx] = 0; // Backtrack

            // Check parity mismatch with left neighbor
            if (idx > 0 && arr[idx - 1] != 0 && arr[idx - 1] % 2 != 0) {
                cost++;
            }
            // Check parity mismatch with right neighbor (only if already fixed)
            if (idx < n - 1 && arr[idx + 1] != 0 && arr[idx + 1] % 2 != 0) {
                cost++;
            }
            minCost = Math.min(minCost, cost);
        }

        // Option 2: Place an odd number
        if (odd > 0) {
            arr[idx] = 1; // Use 1 as a parity marker for odd
            int cost = solve(idx + 1, even, odd - 1, 1);
            arr[idx] = 0; // Backtrack

            // Check parity mismatch with left neighbor
            if (idx > 0 && arr[idx - 1] != 0 && arr[idx - 1] % 2 == 0) {
                cost++;
            }
            // Check parity mismatch with right neighbor (only if already fixed)
            if (idx < n - 1 && arr[idx + 1] != 0 && arr[idx + 1] % 2 == 0) {
                cost++;
            }
            minCost = Math.min(minCost, cost);
        }

        // Memoize and return
        dp[idx][even][odd][prevParity] = minCost;
        return minCost;
    }

    /**
     * Fast, standard-compliant input scanner for competitive programming.
     */
    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) {
                        return null;
                    }
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input", e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            String token = next();
            if (token == null) {
                throw new NoSuchElementException("End of input reached");
            }
            return Integer.parseInt(token);
        }
    }
}

import java.io.*;
