/**
 * Refactored solution for Codeforces 1287C.
 * 
 * Key Improvements:
 * 1. Removed inheritance from PrintWriter; uses composition instead.
 * 2. Replaced cryptic variable names with descriptive, domain-specific names.
 * 3. Extracted unused code (reverse method) and redundant logic.
 * 4. Split monolithic main() into focused, single-responsibility methods.
 * 5. Added FastScanner for efficient I/O handling.
 * 6. Documented complex algorithmic branches with inline comments.
 */
public class Codeforces1287C {

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out);
        new Codeforces1287C().solve(scanner, out);
        out.flush();
    }

    /**
     * Main solver entry point. Orchestrates input reading, processing, and output.
     */
    void solve(FastScanner scanner, PrintWriter out) {
        int n = scanner.nextInt();
        int[] parities = new int[n];
        int evenCount = 0;
        int oddCount = 0;

        // Parse input and track parities. 0 is marked as -1 (special case).
        for (int i = 0; i < n; i++) {
            int p = scanner.nextInt();
            if (p == 0) {
                parities[i] = -1;
            } else {
                parities[i] = p % 2;
                if (parities[i] == 0) evenCount++;
                else oddCount++;
            }
        }

        // k0/k1 track how many additional even/odd positions are required
        // to satisfy the alternating parity constraint.
        int k0 = n / 2 - evenCount;
        int k1 = (n + 1) / 2 - oddCount;

        // Edge case: if we need to adjust exactly n positions, answer is trivial.
        if (k0 + k1 == n) {
            out.println(n == 1 ? 0 : 1);
            return;
        }

        // Group consecutive segments by parity type
        int[] evenEvenGroups = new int[n]; int cntEvenEven = 0;
        int[] oddOddGroups = new int[n]; int cntOddOdd = 0;
        int[] mixedGroups = new int[n]; int cntMixed = 0;
        int[] evenGroups = new int[2]; int cntEven = 0;
        int[] oddGroups = new int[2]; int cntOdd = 0;

        int operations = 0;
        int lastValidIndex = -1;

        for (int i = 0; i < n; i++) {
            if (parities[i] == -1) continue;

            int gap = i - lastValidIndex - 1;
            if (gap > 0) {
                if (parities[i] == 0) {
                    if (lastValidIndex == -1) {
                        evenGroups[cntEven++] = gap;
                    } else if (parities[lastValidIndex] == parities[i]) {
                        evenEvenGroups[cntEvenEven++] = gap;
                    } else {
                        mixedGroups[cntMixed++] = gap;
                    }
                } else {
                    if (lastValidIndex == -1) {
                        oddGroups[cntOdd++] = gap;
                    } else if (parities[lastValidIndex] == parities[i]) {
                        oddOddGroups[cntOddOdd++] = gap;
                    } else {
                        mixedGroups[cntMixed++] = gap;
                    }
                }
            }

            // Count transitions between different parities
            if (lastValidIndex != -1 && parities[lastValidIndex] != parities[i]) {
                operations++;
            }
            lastValidIndex = i;
        }

        // Handle trailing gap after the last valid element
        int trailingGap = n - lastValidIndex - 1;
        if (trailingGap > 0 && lastValidIndex != -1) {
            if (parities[lastValidIndex] == 0) {
                evenGroups[cntEven++] = trailingGap;
            } else {
                oddGroups[cntOdd++] = trailingGap;
            }
        }

        // If no adjustments are needed, return base operations count
        if (k0 + k1 == 0) {
            out.println(operations);
            return;
        }

        // Determine which adjustment path is feasible and calculate additional operations
        int remainingK0 = k0 - sum(evenEvenGroups, cntEvenEven) - sum(evenGroups, cntEven);
        if (remainingK0 >= 0) {
            int remainingMixedK0 = remainingK0 - sum(mixedGroups, cntMixed);
            if (remainingMixedK0 > 0) {
                operations += calculateMinimumOperations(
                    remainingMixedK0, oddGroups, cntOdd, oddOddGroups, cntOddOdd
                );
            }
        } else {
            int remainingK1 = k1 - sum(oddOddGroups, cntOddOdd) - sum(oddGroups, cntOdd);
            if (remainingK1 >= 0) {
                int remainingMixedK1 = remainingK1 - sum(mixedGroups, cntMixed);
                if (remainingMixedK1 > 0) {
                    operations += calculateMinimumOperations(
                        remainingMixedK1, evenGroups, cntEven, evenEvenGroups, cntEvenEven
                    );
                }
            }
        }

        out.println(operations);
    }

    /**
     * Calculates the sum of the first 'count' elements in an array.
     */
    private int sum(int[] arr, int count) {
        int total = 0;
        for (int i = 0; i < count; i++) {
            total += arr[i];
        }
        return total;
    }

    /**
     * Counts how many largest elements from 'values' are needed to cover 'k'.
     * Assumes 'values' is sorted in ascending order.
     */
    private int countOperationsToCover(int k, int[] values, int count) {
        int ops = 0;
        int idx = count - 1;
        while (k > 0 && idx >= 0) {
            ops++;
            if (k >= values[idx]) {
                k -= values[idx];
            } else {
                k = 0;
            }
            idx--;
        }
        return ops;
    }

    /**
     * Calculates the minimum operations required to satisfy a deficit 'k'
     * using combinations of groupA and groupB elements.
     */
    private int calculateMinimumOperations(int k, int[] groupA, int countA, int[] groupB, int countB) {
        Arrays.sort(groupA, 0, countA);
        Arrays.sort(groupB, 0, countB);

        int minOps;

        // Base cases for small deficits
        if (countA >= 1 && k <= groupA[countA - 1]) {
            minOps = 1;
        } else if (countA == 2 && k <= groupA[0] + groupA[1]) {
            minOps = 2;
        } else {
            // General case: worst case is 2 operations per unit
            minOps = k * 2;
            int sumB = sum(groupB, countB);

            // Option 1: Cover entirely with groupB
            if (k <= sumB) {
                minOps = Math.min(minOps, countOperationsToCover(k, groupB, countB) * 2);
            }
            // Option 2: Use 1 element from groupA + rest from groupB
            if (countA >= 1 && k - groupA[0] <= sumB) {
                minOps = Math.min(minOps, 1 + countOperationsToCover(k - groupA[0], groupB, countB) * 2);
            }
            // Option 3: Use 2 elements from groupA (specifically the largest) + rest from groupB
            if (countA == 2 && k - groupA[1] <= sumB) {
                minOps = Math.min(minOps, 1 + countOperationsToCover(k - groupA[1], groupB, countB) * 2);
            }
            // Option 4: Use both elements from groupA + rest from groupB
            if (countA == 2 && k - groupA[0] - groupA[1] <= sumB) {
                minOps = Math.min(minOps, 2 + countOperationsToCover(k - groupA[0] - groupA[1], groupB, countB) * 2);
            }
        }
        return minOps;
    }

    /**
     * Fast I/O helper class for competitive programming.
     */
    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.util.Scanner;

public class Solution {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        // The original code hardcoded tests = 1. 
        // We process a single test case as per the original logic.
        solve(scanner);
    }

    private static void solve(Scanner scanner) {
        if (!scanner.hasNextInt()) {
            return;
        }

        int n = scanner.nextInt();
        int[] numbers = new int[n];

        int positiveOddCount = 0;
        int positiveEvenCount = 0;

        // Read array elements and count existing positive odds/evens
        for (int i = 0; i < n; i++) {
            numbers[i] = scanner.nextInt();
            if (numbers[i] > 0) {
                if (numbers[i] % 2 == 0) {
                    positiveEvenCount++;
                } else {
                    positiveOddCount++;
                }
            }
        }

        // Calculate expected counts for a complete set 1..n
        int expectedEvenCount = n / 2;
        int expectedOddCount = n - expectedEvenCount;

        // Calculate how many odds/evens are missing
        int missingOddCount = expectedOddCount - positiveOddCount;
        int missingEvenCount = expectedEvenCount - positiveEvenCount;

        // Arrays to store the frequency of gaps between non-zero elements
        // gapOddCounts[k] stores the number of gaps of size k between two odd numbers
        // gapEvenCounts[k] stores the number of gaps of size k between two even numbers
        int[] gapOddCounts = new int[n];
        int[] gapEvenCounts = new int[n];

        int operations = 0;

        // Iterate through the array to find gaps between non-zero elements
        for (int i = 0; i < n - 1; i++) {
            if (numbers[i] == 0) {
                continue;
            }

            int j = i + 1;
            while (j < n && numbers[j] == 0) {
                j++;
            }

            if (j == n) {
                break; // Reached the end of the array
            }

            int gapSize = j - i - 1;
            boolean currentIsEven = (numbers[i] % 2 == 0);
            boolean nextIsEven = (numbers[j] % 2 == 0);

            if (currentIsEven) {
                if (nextIsEven) {
                    gapEvenCounts[gapSize]++;
                } else {
                    operations++;
                }
            } else {
                if (!nextIsEven) {
                    gapOddCounts[gapSize]++;
                } else {
                    operations++;
                }
            }
        }

        // Process gaps to update operations count and remaining missing counts
        for (int gap = 1; gap < n; gap++) {
            // Process Odd gaps
            int requiredOdd = gap * gapOddCounts[gap];
            if (requiredOdd <= missingOddCount) {
                missingOddCount -= requiredOdd;
            } else {
                int filledGaps = missingOddCount / gap;
                gapOddCounts[gap] -= filledGaps;
                operations += (gapOddCounts[gap] * 2);

                int itemsConsumed = filledGaps * gap;
                missingOddCount -= itemsConsumed;
            }

            // Process Even gaps
            int requiredEven = gap * gapEvenCounts[gap];
            if (requiredEven <= missingEvenCount) {
                missingEvenCount -= requiredEven;
            } else {
                int filledGaps = missingEvenCount / gap;
                gapEvenCounts[gap] -= filledGaps;
                operations += (gapEvenCounts[gap] * 2);

                int itemsConsumed = filledGaps * gap;
                missingEvenCount -= itemsConsumed;
            }
        }

        // Handle Leading Zeros
        int leadingZeroCount = 0;
        while (leadingZeroCount < n && numbers[leadingZeroCount] == 0) {
            leadingZeroCount++;
        }

        if (leadingZeroCount == n) {
            // Array contains only zeros
            System.out.println(n == 1 ? 0 : 1);
            return;
        }

        // Check parity of the first non-zero element
        if (numbers[leadingZeroCount] % 2 == 0) {
            if (leadingZeroCount <= missingEvenCount) {
                missingEvenCount -= leadingZeroCount;
            } else {
                operations++;
            }
        } else {
            if (leadingZeroCount <= missingOddCount) {
                missingOddCount -= leadingZeroCount;
            } else {
                operations++;
            }
        }

        // Handle Trailing Zeros
        int lastNonZeroIndex = n - 1;
        while (lastNonZeroIndex >= 0 && numbers[lastNonZeroIndex] == 0) {
            lastNonZeroIndex--;
        }

        // Calculate the number of trailing zeros explicitly
        // Note: The original code subtracted 'index' (position) instead of the count of zeros.
        // This has been corrected to subtract the actual count of zeros for logical consistency.
        int trailingZeroCount = n - 1 - lastNonZeroIndex;

        if (numbers[lastNonZeroIndex] % 2 == 0) {
            if (trailingZeroCount <= missingEvenCount) {
                missingEvenCount -= trailingZeroCount;
            } else {
                operations++;
            }
        } else {
            if (trailingZeroCount <= missingOddCount) {
                missingOddCount -= trailingZeroCount;
            } else {
                operations++;
            }
        }

        System.out.println(operations);
    }
}

import java.util.Scanner;

public class Garland {
    private static final int ODD_VALUE = 1;
    private static final int EVEN_VALUE = 2;

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            if (!scanner.hasNextInt()) return;
            int n = scanner.nextInt();

            // counts[0] tracks remaining odd numbers (1s), counts[1] tracks remaining even numbers (2s)
            int[] counts = new int[2];
            counts[0] = (n % 2 == 0) ? n / 2 : n / 2 + 1;
            counts[1] = n / 2;

            int[] arr = new int[n];
            int firstIndex = -1;
            int lastIndex = -1;

            // Flags to mark gap sizes between consecutive non-zero elements of the same parity
            int[] sameParityGapFlags = new int[n];
            int frontNum = -1;
            int currentDistance = 0;

            // Parse input and initialize state
            for (int i = 0; i < n; i++) {
                arr[i] = scanner.nextInt();
                if (arr[i] != 0) {
                    lastIndex = i;
                    if (firstIndex == -1) {
                        firstIndex = i;
                    }
                    if (arr[i] % 2 == 0) {
                        counts[1]--;
                    } else {
                        counts[0]--;
                    }
                    if (frontNum == -1) {
                        frontNum = arr[i];
                        currentDistance = 0;
                    } else {
                        if (isSameParity(frontNum, arr[i])) {
                            sameParityGapFlags[currentDistance] = 1;
                        }
                        frontNum = arr[i];
                        currentDistance = 0;
                    }
                    continue;
                }
                currentDistance++;
            }

            int answer = 0;
            if (firstIndex == -1) {
                // No non-zero elements initially
                answer = (n == 1) ? 0 : 1;
            } else {
                // 1. Fill gaps between same-parity non-zero elements
                fillSameParityGaps(arr, sameParityGapFlags, counts);

                // 2. Fill the suffix after the last non-zero element
                fillSuffix(arr, lastIndex, n, counts);

                // 3. Fill the prefix before the first non-zero element
                fillPrefix(arr, firstIndex, counts);

                // 4. Fill remaining zeros between non-zero elements
                fillRemainingInternalZeros(arr, firstIndex, n, counts);

                // 5. Fill any remaining zeros with an odd number
                fillRemainingZeros(arr, firstIndex, n);

                // 6. Count the number of adjacent pairs with different parity
                answer = countAlternations(arr);
            }

            System.out.println(answer);
        }
    }

    /**
     * Fills gaps of a specific size between non-zero elements that share the same parity.
     * Processes gaps in ascending order of size to maintain original greedy behavior.
     */
    private static void fillSameParityGaps(int[] arr, int[] gapFlags, int[] counts) {
        for (int gapSize = 1; gapSize < arr.length; gapSize++) {
            if (gapFlags[gapSize] == 0) continue;

            for (int start = 0; start < arr.length - gapSize - 1; start++) {
                int end = start + gapSize + 1;
                if (arr[start] == 0 || arr[end] == 0) continue;
                if (!isSameParity(arr[start], arr[end])) continue;

                // Verify the gap contains only zeros
                boolean isAllZeros = true;
                for (int k = start + 1; k < end; k++) {
                    if (arr[k] != 0) {
                        isAllZeros = false;
                        break;
                    }
                }
                if (!isAllZeros) continue;

                int parity = arr[start] % 2;
                if (parity == 0 && counts[1] >= gapSize) {
                    fillRange(arr, start + 1, gapSize, EVEN_VALUE);
                    counts[1] -= gapSize;
                } else if (parity != 0 && counts[0] >= gapSize) {
                    fillRange(arr, start + 1, gapSize, ODD_VALUE);
                    counts[0] -= gapSize;
                }
            }
        }
    }

    /**
     * Fills the array segment after the last known non-zero element.
     */
    private static void fillSuffix(int[] arr, int lastIndex, int n, int[] counts) {
        int suffixLength = n - lastIndex - 1;
        if (suffixLength <= 0) return;

        int lastVal = arr[lastIndex];
        int parity = lastVal % 2;

        if (parity == 0 && counts[1] >= suffixLength) {
            fillRange(arr, lastIndex + 1, suffixLength, EVEN_VALUE);
            counts[1] -= suffixLength;
        } else if (parity != 0 && counts[0] >= suffixLength) {
            fillRange(arr, lastIndex + 1, suffixLength, ODD_VALUE);
            counts[0] -= suffixLength;
        }
    }

    /**
     * Fills the array segment before the first known non-zero element.
     * Tries to match the parity of the next element, falling back to even if odd count is exhausted.
     */
    private static void fillPrefix(int[] arr, int firstIndex, int[] counts) {
        for (int i = firstIndex - 1; i >= 0; i--) {
            int nextVal = arr[i + 1];
            boolean nextIsEven = nextVal % 2 == 0;

            // Replicates original insert logic: prefer even if next is even and we have evens,
            // or if next is odd and we have no odds left. Otherwise place odd.
            if ((nextIsEven && counts[1] > 0) || (!nextIsEven && counts[0] <= 0)) {
                arr[i] = EVEN_VALUE;
                counts[1]--;
            } else {
                arr[i] = ODD_VALUE;
                counts[0]--;
            }
        }
    }

    /**
     * Fills remaining zeros between non-zero elements, skipping those bounded by different parities.
     */
    private static void fillRemainingInternalZeros(int[] arr, int firstIndex, int n, int[] counts) {
        for (int i = firstIndex + 1; i < n; i++) {
            if (arr[i] != 0) continue;

            // Skip if surrounded by different parities
            if (i < n - 1 && arr[i - 1] != 0 && arr[i + 1] != 0 && isDifferentParity(arr[i - 1], arr[i + 1])) {
                continue;
            }

            // Fill based on the previous element's parity
            int prevVal = arr[i - 1];
            boolean prevIsEven = prevVal % 2 == 0;

            if ((prevIsEven && counts[1] > 0) || (!prevIsEven && counts[0] <= 0)) {
                arr[i] = EVEN_VALUE;
                counts[1]--;
            } else {
                arr[i] = ODD_VALUE;
                counts[0]--;
            }
        }
    }

    /**
     * Fills any remaining unfilled positions with an odd number.
     */
    private static void fillRemainingZeros(int[] arr, int firstIndex, int n) {
        for (int i = firstIndex + 1; i < n; i++) {
            if (arr[i] == 0) {
                arr[i] = ODD_VALUE;
            }
        }
    }

    /**
     * Counts adjacent pairs with different parity.
     */
    private static int countAlternations(int[] arr) {
        int count = 0;
        for (int i = 0; i < arr.length - 1; i++) {
            if (isDifferentParity(arr[i], arr[i + 1])) {
                count++;
            }
        }
        return count;
    }

    private static boolean isSameParity(int a, int b) {
        return (a % 2 == 0 && b % 2 == 0) || (a % 2 != 0 && b % 2 != 0);
    }

    private static boolean isDifferentParity(int a, int b) {
        return (a % 2 == 0 && b % 2 != 0) || (a % 2 != 0 && b % 2 == 0);
    }

    private static void fillRange(int[] arr, int start, int length, int value) {
        for (int i = 0; i < length; i++) {
            arr[start + i] = value;
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Solves a parity-based assignment problem using dynamic programming.
 * 
 * DP State: dp[index][missingEvens][missingOdds][lastParity]
 * - index: current position in the input array (1-based)
 * - missingEvens: number of even values from 1..n still unused
 * - missingOdds: number of odd values from 1..n still unused
 * - lastParity: 0 for even, 1 for odd
 * 
 * Transitions allow keeping the same parity (cost 0) or flipping parity (cost 1).
 * Values of 0 in the input act as wildcards that can consume either parity.
 */
public class Main {
    private static final int INF = Integer.MAX_VALUE;

    public static void main(String[] args) {
        new Main().run();
    }

    /**
     * Orchestrates I/O setup, execution, and cleanup.
     */
    private void run() {
        FastScanner sc = new FastScanner();
        PrintWriter out = new PrintWriter(System.out);
        try {
            out.println(solve(sc));
        } finally {
            out.flush();
        }
    }

    /**
     * Core problem-solving logic.
     * @param sc FastScanner instance for reading input
     * @return minimum operations/value as computed by the DP table
     */
    private int solve(FastScanner sc) {
        int n = sc.nextInt();
        int[] a = new int[n + 1];
        for (int i = 1; i <= n; i++) {
            a[i] = sc.nextInt();
        }

        // Identify which numbers from 1..n are missing and count by parity
        boolean[] present = new boolean[n + 1];
        for (int i = 1; i <= n; i++) {
            present[a[i]] = true;
        }

        int missingEven = 0;
        int missingOdd = 0;
        for (int i = 1; i <= n; i++) {
            if (!present[i]) {
                if (i % 2 == 0) missingEven++;
                else missingOdd++;
            }
        }

        // Initialize DP table with infinity
        int[][][][] dp = new int[n + 1][missingEven + 1][missingOdd + 1][2];
        for (int i = 0; i <= n; i++) {
            for (int e = 0; e <= missingEven; e++) {
                for (int o = 0; o <= missingOdd; o++) {
                    dp[i][e][o][0] = INF;
                    dp[i][e][o][1] = INF;
                }
            }
        }

        // Base case: first element
        if (a[1] == 0) {
            // Can be assigned as even (consumes one missing even)
            if (missingEven > 0) {
                dp[1][missingEven - 1][missingOdd][0] = 0;
            }
            // Can be assigned as odd (consumes one missing odd)
            if (missingOdd > 0) {
                dp[1][missingEven][missingOdd - 1][1] = 0;
            }
        } else {
            int parity = a[1] % 2;
            dp[1][missingEven][missingOdd][parity] = 0;
        }

        // Fill DP table
        for (int i = 2; i <= n; i++) {
            for (int e = 0; e <= missingEven; e++) {
                for (int o = 0; o <= missingOdd; o++) {
                    int currentVal = a[i];
                    // -1 indicates wildcard (can be even or odd)
                    int allowedParity = (currentVal == 0) ? -1 : currentVal % 2;

                    // Try assigning even parity (0)
                    if (allowedParity == -1 || allowedParity == 0) {
                        if (e + 1 <= missingEven) {
                            int prevE = e + 1;
                            int prevO = o;
                            if (dp[i - 1][prevE][prevO][0] != INF) {
                                dp[i][e][o][0] = Math.min(dp[i][e][o][0], dp[i - 1][prevE][prevO][0]);
                            }
                            if (dp[i - 1][prevE][prevO][1] != INF) {
                                dp[i][e][o][0] = Math.min(dp[i][e][o][0], 1 + dp[i - 1][prevE][prevO][1]);
                            }
                        }
                    }

                    // Try assigning odd parity (1)
                    if (allowedParity == -1 || allowedParity == 1) {
                        if (o + 1 <= missingOdd) {
                            int prevE = e;
                            int prevO = o + 1;
                            if (dp[i - 1][prevE][prevO][0] != INF) {
                                dp[i][e][o][1] = Math.min(dp[i][e][o][1], dp[i - 1][prevE][prevO][0]);
                            }
                            if (dp[i - 1][prevE][prevO][1] != INF) {
                                dp[i][e][o][1] = Math.min(dp[i][e][o][1], 1 + dp[i - 1][prevE][prevO][1]);
                            }
                        }
                    }
                }
            }
        }

        // Result is the minimum cost to reach the end with zero missing numbers
        return Math.min(dp[n][0][0][0], dp[n][0][0][1]);
    }

    /**
     * High-performance scanner for competitive programming style inputs.
     */
    private static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input", e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            String s = next();
            if (s == null) throw new NoSuchElementException("Unexpected end of input");
            return Integer.parseInt(s);
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.OutputStream;
import java.io.PrintWriter;
import java.util.Arrays;
import java.util.StringTokenizer;

public class Main {

    // Constants
    private static final int INF = 100_000;
    // DP state constants for the last dimension (index 3)
    private static final int STATE_PREV_EVEN = 0;
    private static final int STATE_PREV_ODD = 1;
    private static final int STATE_PREV_FIXED = 2;

    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;

        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);

        new Task().solve(in, out);

        out.flush();
        out.close();
    }

    static class Task {
        /**
         * Solves the problem using dynamic programming.
         * dp[i][oddsUsed][evensUsed][state] represents the minimum cost to fill the first i positions,
         * having used 'oddsUsed' zeros as odd numbers and 'evensUsed' zeros as even numbers.
         * 'state' indicates the parity of the (i-1)-th element: 0=even, 1=odd, 2=fixed (original non-zero).
         */
        public void solve(InputReader in, PrintWriter out) {
            int n = in.nextInt();
            int[] values = new int[n + 1];

            int fixedEvenCount = 0;
            int fixedOddCount = 0;

            // Read input and count fixed parities
            for (int i = 1; i <= n; i++) {
                values[i] = in.nextInt();
                if (values[i] != 0) {
                    if ((values[i] % 2) == 0) {
                        fixedEvenCount++;
                    } else {
                        fixedOddCount++;
                    }
                }
            }

            // Calculate how many zeros must be filled with even/odd numbers to balance the sequence
            int zerosToFillEven = (n / 2) - fixedEvenCount;
            int zerosToFillOdd = ((n + 1) / 2) - fixedOddCount;

            // Initialize DP table
            int[][][][] dp = new int[n + 1][zerosToFillOdd + 1][zerosToFillEven + 1][3];
            initializeDP(dp);

            // Fill DP table
            for (int i = 1; i <= n; i++) {
                int currentValue = values[i];
                int prevValue = values[i - 1];
                boolean isCurrentFixed = (currentValue != 0);
                boolean isPrevFixed = (prevValue != 0);

                if (isCurrentFixed) {
                    // Current position is fixed (non-zero)
                    if (i == 1) {
                        dp[i][0][0][STATE_PREV_FIXED] = 0;
                        continue;
                    }

                    int currentParity = currentValue % 2; // 0 for even, 1 for odd

                    if (!isPrevFixed) {
                        // Previous position was zero, so we transition from STATE_PREV_EVEN or STATE_PREV_ODD
                        int costIfPrevEven = currentParity;      // Cost 1 if current is odd
                        int costIfPrevOdd = 1 - currentParity;    // Cost 1 if current is even
                        dp[i][0][0][STATE_PREV_FIXED] = Math.min(
                            dp[i - 1][0][0][STATE_PREV_EVEN] + costIfPrevEven,
                            dp[i - 1][0][0][STATE_PREV_ODD] + costIfPrevOdd
                        );
                    } else {
                        // Previous position was also fixed
                        int prevParity = prevValue % 2;
                        // Cost is 1 if parities differ (alternating violation)
                        int cost = (currentParity ^ prevParity);
                        dp[i][0][0][STATE_PREV_FIXED] = dp[i - 1][0][0][STATE_PREV_FIXED] + cost;
                    }
                } else {
                    // Current position is zero, we must decide its parity
                    if (i == 1) {
                        if (zerosToFillOdd > 0) dp[i][1][0][STATE_PREV_ODD] = 0;
                        if (zerosToFillEven > 0) dp[i][0][1][STATE_PREV_EVEN] = 0;
                        continue;
                    }

                    if (isPrevFixed) {
                        int prevParity = prevValue % 2;

                        // Option 1: Place Odd at current position
                        int costPlaceOdd = (prevParity == 0 ? 1 : 0); // Cost 1 if previous was even
                        for (int o = 0; o <= zerosToFillOdd - 1; o++) {
                            for (int e = 0; e <= zerosToFillEven; e++) {
                                dp[i][o + 1][e][STATE_PREV_ODD] = Math.min(
                                    dp[i][o + 1][e][STATE_PREV_ODD],
                                    dp[i - 1][o][e][STATE_PREV_FIXED] + costPlaceOdd
                                );
                            }
                        }

                        // Option 2: Place Even at current position
                        int costPlaceEven = (prevParity == 1 ? 1 : 0); // Cost 1 if previous was odd
                        for (int o = 0; o <= zerosToFillOdd; o++) {
                            for (int e = 0; e <= zerosToFillEven - 1; e++) {
                                dp[i][o][e + 1][STATE_PREV_EVEN] = Math.min(
                                    dp[i][o][e + 1][STATE_PREV_EVEN],
                                    dp[i - 1][o][e][STATE_PREV_FIXED] + costPlaceEven
                                );
                            }
                        }
                    } else {
                        // Previous position was also zero
                        // Option 1: Place Odd at current position
                        for (int o = 0; o <= zerosToFillOdd - 1; o++) {
                            for (int e = 0; e <= zerosToFillEven; e++) {
                                dp[i][o + 1][e][STATE_PREV_ODD] = Math.min(
                                    dp[i][o + 1][e][STATE_PREV_ODD],
                                    Math.min(dp[i - 1][o][e][STATE_PREV_EVEN] + 1, dp[i - 1][o][e][STATE_PREV_ODD])
                                );
                            }
                        }

                        // Option 2: Place Even at current position
                        for (int o = 0; o <= zerosToFillOdd; o++) {
                            for (int e = 0; e <= zerosToFillEven - 1; e++) {
                                dp[i][o][e + 1][STATE_PREV_EVEN] = Math.min(
                                    dp[i][o][e + 1][STATE_PREV_EVEN],
                                    Math.min(dp[i - 1][o][e][STATE_PREV_EVEN], dp[i - 1][o][e][STATE_PREV_ODD] + 1)
                                );
                            }
                        }
                    }
                }
            }

            // Extract result from valid terminal states
            int result = Math.min(dp[n][zerosToFillOdd][zerosToFillEven][STATE_PREV_EVEN],
                    Math.min(dp[n][zerosToFillOdd][zerosToFillEven][STATE_PREV_ODD],
                            dp[n][zerosToFillOdd][zerosToFillEven][STATE_PREV_FIXED]));
            out.println(result);
        }

        /**
         * Initializes the DP table with infinity.
         */
        private void initializeDP(int[][][][] dp) {
            int d1 = dp.length;
            int d2 = dp[0].length;
            int d3 = dp[0][0].length;
            int d4 = dp[0][0][0].length;

            for (int i = 0; i < d1; i++) {
                for (int j = 0; j < d2; j++) {
                    for (int k = 0; k < d3; k++) {
                        Arrays.fill(dp[i][j][k], INF);
                    }
                }
            }
        }
    }

    /**
     * Fast input reader for competitive programming style problems.
     */
    static class InputReader {
        public BufferedReader reader;
        public StringTokenizer tokenizer;

        public InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            String s = next();
            if (s == null) throw new RuntimeException("Unexpected end of input");
            return Integer.parseInt(s);
        }

        public long nextLong() {
            String s = next();
            if (s == null) throw new RuntimeException("Unexpected end of input");
            return Long.parseLong(s);
        }
    }
}

import java.io.BufferedWriter;
import java.io.IOException;
import java.io.InputStream;
import java.io.OutputStream;
import java.io.OutputStreamWriter;
import java.io.PrintWriter;
import java.io.Writer;
import java.util.Arrays;
import java.util.InputMismatchException;

/**
 * Main entry point for the competitive programming solver.
 * Sets up fast I/O and delegates the problem logic to TaskA.
 */
public class Main {

    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;

        InputReader in = new InputReader(inputStream);
        OutputWriter out = new OutputWriter(outputStream);

        TaskA solver = new TaskA();
        solver.solve(1, in, out);

        out.close();
    }

    /**
     * Solves TaskA: Minimizes parity changes in a sequence while respecting
     * fixed counts of zeros and ones. Uses dynamic programming.
     */
    static class TaskA {
        private static final int INF = 1_000_000_000;

        public void solve(int testNumber, InputReader in, OutputWriter out) {
            int n = in.nextInt();
            int expectedZeros = n / 2;
            int expectedOnes = n - expectedZeros;

            // Normalize input: 0 becomes -1 (wildcard), others become parity (0 or 1)
            int[] a = new int[n];
            for (int i = 0; i < n; i++) {
                a[i] = in.nextInt();
                a[i] = (a[i] == 0) ? -1 : (a[i] % 2);
            }

            // dp[parity][remainingZeros][remainingOnes]
            // parity: 0 or 1, representing the value assigned to the previous position
            int[][][] currentDp = new int[2][expectedZeros + 1][expectedOnes + 1];
            int[][][] nextDp = new int[2][expectedZeros + 1][expectedOnes + 1];

            // Initialize DP table with infinity
            for (int p = 0; p < 2; p++) {
                for (int z = 0; z <= expectedZeros; z++) {
                    Arrays.fill(currentDp[p][z], INF);
                }
            }

            // Base case: Before processing any elements, all counts are remaining.
            // Both starting parities are valid with 0 cost.
            currentDp[0][expectedZeros][expectedOnes] = 0;
            currentDp[1][expectedZeros][expectedOnes] = 0;

            // Process each element in the input sequence
            for (int it = 0; it < n; it++) {
                int x = a[it]; // -1 (any), 0, or 1

                // Reset next DP table for the current iteration
                for (int p = 0; p < 2; p++) {
                    for (int z = 0; z <= expectedZeros; z++) {
                        Arrays.fill(nextDp[p][z], INF);
                    }
                }

                // Transition: iterate over all valid states from the previous step
                for (int currentParity = 0; currentParity < 2; currentParity++) {
                    for (int remainingZeros = 0; remainingZeros <= expectedZeros; remainingZeros++) {
                        for (int remainingOnes = 0; remainingOnes <= expectedOnes; remainingOnes++) {
                            int currentCost = currentDp[currentParity][remainingZeros][remainingOnes];
                            if (currentCost == INF) {
                                continue;
                            }

                            // Try assigning 0 or 1 to the current position
                            for (int assignedValue = 0; assignedValue < 2; assignedValue++) {
                                // If the input has a constraint, it must match our assignment
                                if (x != -1 && x != assignedValue) {
                                    continue;
                                }

                                int nextCost = currentCost;
                                // Increment cost if parity changes from the previous position
                                if (assignedValue != currentParity) {
                                    nextCost++;
                                }

                                int nextRemainingZeros = remainingZeros;
                                int nextRemainingOnes = remainingOnes;

                                if (assignedValue == 0) {
                                    nextRemainingZeros--;
                                } else {
                                    nextRemainingOnes--;
                                }

                                // Validate bounds
                                if (nextRemainingZeros < 0 || nextRemainingOnes < 0) {
                                    continue;
                                }

                                // Update DP state if we found a cheaper path
                                if (nextDp[assignedValue][nextRemainingZeros][nextRemainingOnes] > nextCost) {
                                    nextDp[assignedValue][nextRemainingZeros][nextRemainingOnes] = nextCost;
                                }
                            }
                        }
                    }
                }

                // Swap references to advance DP state (more efficient than copying arrays)
                int[][][] temp = currentDp;
                currentDp = nextDp;
                nextDp = temp;
            }

            // Result is the minimum cost to reach 0 remaining zeros and 0 remaining ones
            int result = Math.min(currentDp[0][0][0], currentDp[1][0][0]);
            out.printLine(result);
        }
    }

    /**
     * Fast input reader for competitive programming environments.
     * Handles buffered reading and integer parsing efficiently.
     */
    static class InputReader {
        private final InputStream stream;
        private final byte[] buffer = new byte[10000];
        private int cur;
        private int count;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        public static boolean isSpace(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        public int read() {
            if (count == -1) {
                throw new InputMismatchException();
            }
            try {
                if (cur >= count) {
                    cur = 0;
                    count = stream.read(buffer);
                    if (count <= 0) {
                        return -1;
                    }
                }
            } catch (IOException e) {
                throw new InputMismatchException();
            }
            return buffer[cur++];
        }

        public int readSkipSpace() {
            int c;
            do {
                c = read();
            } while (isSpace(c));
            return c;
        }

        public int nextInt() {
            int sgn = 1;
            int c = readSkipSpace();
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                res = res * 10 + c - '0';
                c = read();
            } while (!isSpace(c));
            res *= sgn;
            return res;
        }
    }

    /**
     * Fast output writer for competitive programming environments.
     * Wraps BufferedWriter and PrintWriter for efficient formatted output.
     */
    static class OutputWriter {
        private final PrintWriter writer;

        public OutputWriter(OutputStream outputStream) {
            writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(outputStream)));
        }

        public OutputWriter(Writer writer) {
            this.writer = new PrintWriter(writer);
        }

        public void print(Object... objects) {
            for (int i = 0; i < objects.length; i++) {
                if (i != 0) {
                    writer.print(' ');
                }
                writer.print(objects[i]);
            }
        }

        public void printLine(Object... objects) {
            print(objects);
            writer.println();
        }

        public void close() {
            writer.flush();
            writer.close();
        }
    }
}

import java.util.Scanner;
import java.io.PrintWriter;
import java.io.IOException;
import java.util.Arrays;

/**
 * Solves a dynamic programming problem involving parity transitions.
 * Calculates the minimum cost to arrange an array where 0s can be replaced
 * by even or odd numbers, minimizing parity changes between adjacent elements.
 */
public class SequenceParitySolver {

    private static final int MAX_SIZE = 105;
    private static long[][][][] memo;

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        PrintWriter pw = new PrintWriter(System.out);

        if (!sc.hasNextInt()) {
            pw.flush();
            return;
        }

        int n = sc.nextInt();
        int[] arr = new int[n];
        int evenCount = n / 2;
        int oddCount = (n + 1) / 2;

        for (int i = 0; i < n; i++) {
            arr[i] = sc.nextInt();
            if (arr[i] != 0) {
                if (arr[i] % 2 == 0) {
                    evenCount--;
                } else {
                    oddCount--;
                }
            }
        }

        // Initialize memoization table
        memo = new long[MAX_SIZE][MAX_SIZE][MAX_SIZE][2];
        initializeMemo(n, evenCount, oddCount);

        // Compute minimum cost starting with either even or odd previous element
        long result = Math.min(
            solve(arr, 0, evenCount, oddCount, false),
            solve(arr, 0, evenCount, oddCount, true)
        );

        pw.println(result);
        pw.flush();
        pw.close();
        sc.close();
    }

    /**
     * Recursive function with memoization to find the minimum parity transition cost.
     *
     * @param arr The input array
     * @param index Current position in the array
     * @param remainingEven Number of even numbers left to place (for 0s)
     * @param remainingOdd Number of odd numbers left to place (for 0s)
     * @param lastWasEven Boolean indicating if the previous element was even
     * @return Minimum cost from current state to the end
     */
    private static long solve(int[] arr, int index, int remainingEven, int remainingOdd, boolean lastWasEven) {
        // Base case: reached the end of the array
        if (index == arr.length) {
            return 0;
        }

        // Return memoized result if available
        int lastState = lastWasEven ? 1 : 0;
        if (memo[index][remainingEven][remainingOdd][lastState] != -1) {
            return memo[index][remainingEven][remainingOdd][lastState];
        }

        long minCost = Long.MAX_VALUE;

        if (arr[index] == 0) {
            // Option 1: Place an even number
            if (remainingEven > 0) {
                long cost = lastWasEven ? 0 : 1;
                minCost = Math.min(minCost, cost + solve(arr, index + 1, remainingEven - 1, remainingOdd, true));
            }
            // Option 2: Place an odd number
            if (remainingOdd > 0) {
                long cost = lastWasEven ? 1 : 0;
                minCost = Math.min(minCost, cost + solve(arr, index + 1, remainingEven, remainingOdd - 1, false));
            }
        } else {
            // Fixed parity based on the array value
            boolean isEven = arr[index] % 2 == 0;
            long cost = lastWasEven == isEven ? 0 : 1;
            minCost = cost + solve(arr, index + 1, remainingEven, remainingOdd, isEven);
        }

        // Store and return the result
        return memo[index][remainingEven][remainingOdd][lastState] = minCost;
    }

    /**
     * Initializes the memoization table with -1.
     * Only fills the relevant subset of the 4D array for performance.
     */
    private static void initializeMemo(int n, int evenCount, int oddCount) {
        for (int i = 0; i <= n; i++) {
            for (int j = 0; j <= evenCount; j++) {
                for (int k = 0; k <= oddCount; k++) {
                    Arrays.fill(memo[i][j][k], -1);
                }
            }
        }
    }
}

import java.io.*;
import java.util.*;

public class Main {

    public static void main(String[] args) {
        FastScanner sc = new FastScanner(System.in);
        Output out = new Output(System.out);
        new Solver(sc, out).solve();
        out.flush();
    }

    /**
     * Encapsulates the problem-solving logic.
     */
    static class Solver {
        private final FastScanner sc;
        private final Output out;
        private static final long INF = Long.MAX_VALUE / 2;

        public Solver(FastScanner sc, Output out) {
            this.sc = sc;
            this.out = out;
        }

        public void solve() {
            int n = sc.nextInt();
            int[] a = new int[n];
            int targetOddCount = (n + 1) / 2;

            for (int i = 0; i < n; i++) {
                int val = sc.nextInt();
                // -1 indicates the value can be freely chosen (0 or 1)
                // Otherwise, store the parity (0 for even, 1 for odd)
                a[i] = (val == 0) ? -1 : (val % 2);
            }

            // dp[i][j][k] = minimum cost to fill the first i elements
            // such that exactly j of them are odd, and the i-th element has parity k.
            long[][][] dp = new long[n + 1][targetOddCount + 1][2];
            initializeDp(dp);

            // Base case: 0 elements processed, 0 odds, parity doesn't matter
            dp[0][0][0] = 0;
            dp[0][0][1] = 0;

            for (int i = 1; i <= n; i++) {
                for (int j = 0; j <= Math.min(i, targetOddCount); j++) {
                    if (a[i - 1] == -1) {
                        // Current element is free to choose: 0 (even) or 1 (odd)
                        dp[i][j][0] = Math.min(dp[i - 1][j][0], dp[i - 1][j][1] + 1);
                        if (j > 0) {
                            dp[i][j][1] = Math.min(dp[i - 1][j - 1][0] + 1, dp[i - 1][j - 1][1]);
                        }
                    } else {
                        // Current element parity is fixed
                        int parity = a[i - 1];
                        dp[i][j][parity] = Math.min(dp[i - 1][j][0] + parity, dp[i - 1][j][1] + (1 - parity));
                        // The opposite parity state remains at INF as it's unreachable
                    }
                }
            }

            out.println(Math.min(dp[n][targetOddCount][0], dp[n][targetOddCount][1]));
        }

        private void initializeDp(long[][][] dp) {
            for (int i = 0; i < dp.length; i++) {
                for (int j = 0; j < dp[i].length; j++) {
                    Arrays.fill(dp[i][j], INF);
                }
            }
        }
    }

    /**
     * Fast I/O scanner optimized for competitive programming.
     */
    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1024];
        private int ptr = 0;
        private int buflen = 0;

        public FastScanner(InputStream in) {
            this.in = in;
        }

        private boolean hasNextByte() {
            if (ptr < buflen) {
                return true;
            }
            ptr = 0;
            try {
                buflen = in.read(buffer);
            } catch (IOException e) {
                e.printStackTrace();
            }
            return buflen > 0;
        }

        private int readByte() {
            return hasNextByte() ? buffer[ptr++] : -1;
        }

        private static boolean isPrintableChar(int c) {
            return c >= 33 && c <= 126;
        }

        private void skipUnprintable() {
            while (hasNextByte() && !isPrintableChar(buffer[ptr])) {
                ptr++;
            }
        }

        public boolean hasNext() {
            skipUnprintable();
            return hasNextByte();
        }

        public String next() {
            if (!hasNext()) throw new NoSuchElementException();
            StringBuilder sb = new StringBuilder();
            int b = readByte();
            while (isPrintableChar(b)) {
                sb.appendCodePoint(b);
                b = readByte();
            }
            return sb.toString();
        }

        public long nextLong() {
            if (!hasNext()) throw new NoSuchElementException();
            long n = 0;
            boolean minus = false;
            int b = readByte();
            if (b == '-') {
                minus = true;
                b = readByte();
            }
            if (b < '0' || b > '9') {
                throw new NumberFormatException();
            }
            while (true) {
                if (b >= '0' && b <= '9') {
                    n *= 10;
                    n += b - '0';
                } else if (b == -1 || !isPrintableChar(b)) {
                    return minus ? -n : n;
                } else {
                    throw new NumberFormatException();
                }
                b = readByte();
            }
        }

        public int nextInt() {
            return (int) nextLong();
        }

        public int[] nextIntArray(int n, boolean oneBased) {
            int[] arr = oneBased ? new int[n + 1] : new int[n];
            int start = oneBased ? 1 : 0;
            for (int i = start; i < arr.length; i++) {
                arr[i] = nextInt();
            }
            return arr;
        }

        public long[] nextLongArray(int n, boolean oneBased) {
            long[] arr = oneBased ? new long[n + 1] : new long[n];
            int start = oneBased ? 1 : 0;
            for (int i = start; i < arr.length; i++) {
                arr[i] = nextLong();
            }
            return arr;
        }
    }

    /**
     * Wrapper around PrintWriter with convenient array printing utilities.
     */
    static class Output extends PrintWriter {

        public Output(PrintStream ps) {
            super(ps);
        }

        public void print(int[] a, String separator) {
            for (int i = 0; i < a.length; i++) {
                if (i > 0) print(separator);
                print(a[i]);
            }
            println();
        }

        public void print(long[] a, String separator) {
            for (int i = 0; i < a.length; i++) {
                if (i > 0) print(separator);
                print(a[i]);
            }
            println();
        }

        public void print(String[] a, String separator) {
            for (int i = 0; i < a.length; i++) {
                if (i > 0) print(separator);
                print(a[i]);
            }
            println();
        }

        public void print(ArrayList<?> a, String separator) {
            for (int i = 0; i < a.size(); i++) {
                if (i > 0) print(separator);
                print(a.get(i));
            }
            println();
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

/**
 * Entry point for the competitive programming solution.
 * Handles input/output setup and delegates solving logic to TaskC.
 */
public class Main {
    public static void main(String[] args) {
        InputReader in = new InputReader();
        PrintWriter out = new PrintWriter(System.out);

        // Instantiate and run the solver
        new TaskC().solve(in, out);

        // Ensure all output is flushed and resources are closed
        out.flush();
        out.close();
    }

    /**
     * Contains the core algorithm for solving the problem.
     * Uses dynamic programming to find the minimum cost to balance array parities.
     */
    static class TaskC {
        public void solve(InputReader in, PrintWriter out) {
            int n = in.nextInt();
            int[] a = new int[n];
            int existingEvenCount = 0;
            int existingOddCount = 0;

            // Read input and count existing even/odd numbers
            for (int i = 0; i < n; i++) {
                a[i] = in.nextInt();
                if (a[i] != 0) {
                    if (a[i] % 2 == 0) {
                        existingEvenCount++;
                    } else {
                        existingOddCount++;
                    }
                }
            }

            // Calculate how many zeros must be replaced with even/odd numbers
            // to satisfy the required parity distribution for the array
            int zerosForEven = n / 2 - existingEvenCount;
            int zerosForOdd = (n + 1) / 2 - existingOddCount;

            // dp[i][j][k][l]
            // i: index in the original array (1-based)
            // j: number of zeros filled with even numbers so far
            // k: number of zeros filled with odd numbers so far
            // l: parity of the current element (0 for even, 1 for odd)
            int[][][][] dp = new int[n + 1][n + 1][n + 1][2];

            // Initialize DP table to a safe large value to prevent incorrect minimums
            for (int i = 0; i <= n; i++) {
                for (int j = 0; j <= n; j++) {
                    for (int k = 0; k <= n; k++) {
                        dp[i][j][k][0] = Integer.MAX_VALUE;
                        dp[i][j][k][1] = Integer.MAX_VALUE;
                    }
                }
            }

            // Base case: zero cost before processing any elements
            dp[0][0][0][0] = 0;
            dp[0][0][0][1] = 0;

            for (int i = 1; i <= n; i++) {
                for (int j = 0; j <= zerosForEven; j++) {
                    for (int k = 0; k <= zerosForOdd; k++) {
                        // Calculate minimum cost if current element is even (l = 0)
                        int minCostEven = Integer.MAX_VALUE;
                        if (a[i - 1] == 0) {
                            if (j > 0 && dp[i - 1][j - 1][k][0] != Integer.MAX_VALUE) {
                                minCostEven = Math.min(minCostEven, dp[i - 1][j - 1][k][0]);
                            }
                            if (k > 0 && dp[i - 1][j][k - 1][1] != Integer.MAX_VALUE) {
                                minCostEven = Math.min(minCostEven, dp[i - 1][j][k - 1][1] + 1);
                            }
                        } else {
                            int originalParity = a[i - 1] % 2;
                            if (dp[i - 1][j][k][originalParity] != Integer.MAX_VALUE) {
                                minCostEven = dp[i - 1][j][k][originalParity] + Math.abs(originalParity);
                            }
                        }
                        dp[i][j][k][0] = minCostEven;

                        // Calculate minimum cost if current element is odd (l = 1)
                        int minCostOdd = Integer.MAX_VALUE;
                        if (a[i - 1] == 0) {
                            if (j > 0 && dp[i - 1][j - 1][k][0] != Integer.MAX_VALUE) {
                                minCostOdd = Math.min(minCostOdd, dp[i - 1][j - 1][k][0] + 1);
                            }
                            if (k > 0 && dp[i - 1][j][k - 1][1] != Integer.MAX_VALUE) {
                                minCostOdd = Math.min(minCostOdd, dp[i - 1][j][k - 1][1]);
                            }
                        } else {
                            int originalParity = a[i - 1] % 2;
                            if (dp[i - 1][j][k][originalParity] != Integer.MAX_VALUE) {
                                minCostOdd = dp[i - 1][j][k][originalParity] + Math.abs(originalParity - 1);
                            }
                        }
                        dp[i][j][k][1] = minCostOdd;
                    }
                }
            }

            // Output the minimum cost to satisfy parity constraints
            out.println(Math.min(dp[n][zerosForEven][zerosForOdd][0], dp[n][zerosForEven][zerosForOdd][1]));
        }
    }

    /**
     * Fast input reader for competitive programming environments.
     * Wraps BufferedReader and StringTokenizer for efficient token parsing.
     */
    static class InputReader {
        private final BufferedReader br;
        private StringTokenizer st;

        public InputReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input", e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            String token = next();
            if (token == null) throw new RuntimeException("Unexpected end of input");
            return Integer.parseInt(token);
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Refactored solution for an alternating parity sequence problem.
 * 
 * Key Improvements:
 * 1. Clear Naming: Replaced cryptic variables with descriptive names (e.g., parities, remainingEvens, dp).
 * 2. Separation of Concerns: Extracted core logic into a dedicated `solve()` method.
 * 3. Performance: Replaced `ArrayList.contains()` (O(N)) with a boolean array `isUnknown` (O(1)).
 * 4. Safety: Fixed a potential `ArrayIndexOutOfBoundsException` when accessing `dp[i-1][j-1]` by adding bounds checks.
 * 5. Resource Management: Used try-with-resources patterns and explicit flushing for I/O.
 * 6. Documentation: Added JavaDoc and inline comments explaining the DP state and transitions.
 */
public class AlternatingParity {

    public static void main(String[] args) {
        FastScanner sc = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out));
        try {
            int n = sc.nextInt();
            solve(n, sc, out);
        } catch (Exception e) {
            e.printStackTrace();
        } finally {
            out.flush();
        }
    }

    /**
     * Solves the alternating parity sequence problem using dynamic programming.
     *
     * @param n    Length of the sequence
     * @param sc   Fast input scanner
     * @param out  Buffered output writer
     */
    private static void solve(int n, FastScanner sc, PrintWriter out) {
        // parities[i] stores the parity of the i-th element (1-based indexing)
        // 0 = even, 1 = odd, -1 = unknown
        int[] parities = new int[n + 1];
        boolean[] isUnknown = new boolean[n + 1];

        // Calculate required counts for even and odd numbers
        int maxEvens = (n % 2 == 0) ? n / 2 : (n - 1) / 2;
        int maxOdds = (n % 2 == 0) ? n / 2 : (n + 1) / 2;

        for (int i = 1; i <= n; i++) {
            int val = sc.nextInt();
            if (val == 0) {
                parities[i] = -1;
                isUnknown[i] = true;
            } else if (val % 2 == 0) {
                parities[i] = 0;
            } else {
                parities[i] = 1;
            }
        }

        final int INF = n + 1;
        // dp[i][remainingEvens][remainingOdds][currentParity]
        // i: current position (1 to n)
        // remainingEvens: number of even slots left to fill
        // remainingOdds: number of odd slots left to fill
        // currentParity: parity of the element at position i (0 or 1)
        int[][][][] dp = new int[n + 1][maxEvens + 2][maxOdds + 2][2];

        // Initialize DP table with infinity
        for (int i = 1; i <= n; i++) {
            for (int j = 0; j <= maxEvens + 1; j++) {
                for (int k = 0; k <= maxOdds + 1; k++) {
                    Arrays.fill(dp[i][j][k], INF);
                }
            }
        }

        // Base case: first element
        for (int j = 1; j <= maxEvens + 1; j++) {
            for (int k = 1; k <= maxOdds + 1; k++) {
                for (int m = 0; m < 2; m++) {
                    if (parities[1] != -1 && parities[1] != m) {
                        dp[1][j][k][m] = INF; // Mismatch with fixed input
                    } else {
                        dp[1][j][k][m] = 0; // No changes needed for the first element
                    }
                }
            }
        }

        // DP Transitions
        for (int i = 2; i <= n; i++) {
            for (int j = 0; j <= maxEvens + 1; j++) {
                for (int k = 0; k <= maxOdds + 1; k++) {
                    for (int m = 0; m < 2; m++) {
                        // Skip unreachable previous states
                        if (dp[i - 1][j][k][m] >= INF) continue;

                        if (isUnknown[i]) {
                            // Current element can be chosen freely
                            if (m == 0) {
                                // Choose even (0)
                                int costSame = (j > 0) ? dp[i - 1][j - 1][k][0] : INF;
                                int costChange = (k > 0) ? (1 + dp[i - 1][j][k - 1][1]) : INF;
                                dp[i][j][k][m] = Math.min(costSame, costChange);
                            } else {
                                // Choose odd (1)
                                int costSame = (k > 0) ? dp[i - 1][j][k - 1][1] : INF;
                                int costChange = (j > 0) ? (1 + dp[i - 1][j - 1][k][0]) : INF;
                                dp[i][j][k][m] = Math.min(costSame, costChange);
                            }
                        } else {
                            // Current element is fixed by input
                            if (parities[i] == m) {
                                dp[i][j][k][m] = dp[i - 1][j][k][m];
                            } else {
                                dp[i][j][k][m] = 1 + dp[i - 1][j][k][1 - m];
                            }
                        }
                    }
                }
            }
        }

        // Extract the minimum cost for the full sequence
        if (isUnknown[n]) {
            int ans1 = dp[n][maxEvens][maxOdds + 1][0];
            int ans2 = dp[n][maxEvens + 1][maxOdds][1];
            out.println(Math.min(ans1, ans2));
        } else {
            out.println(dp[n][maxEvens + 1][maxOdds + 1][parities[n]]);
        }
    }

    /**
     * Fast input scanner for competitive programming / large I/O.
     */
    public static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    e.printStackTrace();
                    return null;
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            String s = next();
            return s == null ? 0 : Integer.parseInt(s);
        }

        long nextLong() {
            String s = next();
            return s == null ? 0L : Long.parseLong(s);
        }

        double nextDouble() {
            String s = next();
            return s == null ? 0.0 : Double.parseDouble(s);
        }

        String nextLine() {
            String str = "";
            try {
                str = br.readLine();
            } catch (IOException e) {
                e.printStackTrace();
            }
            return str;
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.LinkedList;
import java.util.List;
import java.util.Queue;

/**
 * Main application class containing the core DP logic for parity-based sequence optimization.
 */
public class Main {
    private static final int MOD = 998244353;
    private static int n;
    private static long[] a;
    private static int[][][][] dp;

    public static void main(String[] args) throws IOException {
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(System.in))) {
            String line = reader.readLine();
            if (line == null || line.trim().isEmpty()) return;

            n = Integer.parseInt(line.trim());
            String[] parts = reader.readLine().trim().split("\\s+");
            a = new long[n];

            // Calculate available even and odd numbers to fill placeholder zeros
            int evensAvailable = n / 2;
            int oddsAvailable = n / 2;
            if (n % 2 != 0) oddsAvailable++;

            for (int i = 0; i < n; i++) {
                a[i] = Long.parseLong(parts[i]);
                if (a[i] != 0) {
                    if (a[i] % 2 == 0) evensAvailable--;
                    else oddsAvailable--;
                }
            }

            // Initialize DP table with -1 (uncomputed state)
            dp = new int[n][n][n][2];
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < n; j++) {
                    for (int k = 0; k < n; k++) {
                        Arrays.fill(dp[i][j][k], -1);
                    }
                }
            }

            // Compute and print result based on the first element's value/parity
            int result;
            if (a[0] == 0) {
                if (evensAvailable > 0 && oddsAvailable > 0) {
                    result = n - 1 - Math.max(solve(1, 0, evensAvailable - 1, oddsAvailable),
                                              solve(1, 1, evensAvailable, oddsAvailable - 1));
                } else if (evensAvailable > 0) {
                    result = n - 1 - solve(1, 0, evensAvailable - 1, oddsAvailable);
                } else {
                    result = n - 1 - solve(1, 1, evensAvailable, oddsAvailable - 1);
                }
            } else {
                if (a[0] % 2 == 0) {
                    result = n - 1 - solve(1, 0, evensAvailable, oddsAvailable);
                } else {
                    result = n - 1 - solve(1, 1, evensAvailable, oddsAvailable);
                }
            }
            System.out.println(result);
        } catch (IOException | NumberFormatException e) {
            System.err.println("Error processing input: " + e.getMessage());
        }
    }

    /**
     * Recursive function with memoization to compute the optimal value.
     *
     * @param idx         Current index in array a
     * @param prevParity  Parity of the previous element (0 for even, 1 for odd)
     * @param evensLeft   Number of even values available to fill zeros
     * @param oddsLeft    Number of odd values available to fill zeros
     * @return Computed value for the subproblem
     */
    private static int solve(int idx, int prevParity, int evensLeft, int oddsLeft) {
        if (idx == n) {
            return 0;
        }

        if (dp[idx][evensLeft][oddsLeft][prevParity] != -1) {
            return dp[idx][evensLeft][oddsLeft][prevParity];
        }

        int result;
        if (a[idx] == 0) {
            if (prevParity == 0) { // Previous was even
                if (evensLeft > 0 && oddsLeft > 0) {
                    result = Math.max(1 + solve(idx + 1, 0, evensLeft - 1, oddsLeft),
                                      solve(idx + 1, 1, evensLeft, oddsLeft - 1));
                } else if (evensLeft > 0) {
                    result = 1 + solve(idx + 1, 0, evensLeft - 1, oddsLeft);
                } else {
                    result = solve(idx + 1, 1, evensLeft, oddsLeft - 1);
                }
            } else { // Previous was odd
                if (evensLeft > 0 && oddsLeft > 0) {
                    result = Math.max(solve(idx + 1, 0, evensLeft - 1, oddsLeft),
                                      1 + solve(idx + 1, 1, evensLeft, oddsLeft - 1));
                } else if (evensLeft > 0) {
                    result = solve(idx + 1, 0, evensLeft - 1, oddsLeft);
                } else {
                    result = 1 + solve(idx + 1, 1, evensLeft, oddsLeft - 1);
                }
            }
        } else {
            boolean isEven = a[idx] % 2 == 0;
            if (prevParity == 0 && isEven) {
                result = 1 + solve(idx + 1, 0, evensLeft, oddsLeft);
            } else if (prevParity == 0) {
                result = solve(idx + 1, 1, evensLeft, oddsLeft);
            } else if (prevParity == 1 && isEven) {
                result = solve(idx + 1, 0, evensLeft, oddsLeft);
            } else {
                result = 1 + solve(idx + 1, 1, evensLeft, oddsLeft);
            }
        }

        dp[idx][evensLeft][oddsLeft][prevParity] = result;
        return result;
    }
}

/**
 * Utility class containing common algorithmic helper methods.
 * Dead code and unused classes from the original have been removed for maintainability.
 */
class AlgorithmUtils {
    // Bit manipulation
    private static final int[] BITS_SET_TABLE_256 = new int[256];
    static {
        for (int i = 0; i < 256; i++) {
            BITS_SET_TABLE_256[i] = (i & 1) + BITS_SET_TABLE_256[i / 2];
        }
    }

    public static int countSetBits(int n) {
        return BITS_SET_TABLE_256[n & 0xff]
             + BITS_SET_TABLE_256[(n >> 8) & 0xff]
             + BITS_SET_TABLE_256[(n >> 16) & 0xff]
             + BITS_SET_TABLE_256[(n >> 24) & 0xff];
    }

    // String algorithms
    public static String lexicographicallySmallest(String s) {
        if (s.length() % 2 == 1) return s;
        String s1 = lexicographicallySmallest(s.substring(0, s.length() / 2));
        String s2 = lexicographicallySmallest(s.substring(s.length() / 2));
        return s1.compareTo(s2) < 0 ? s1 + s2 : s2 + s1;
    }

    public static void computeLPSArray(String pat, int[] lps) {
        int len = 0;
        int i = 1;
        int m = pat.length();
        lps[0] = 0;
        while (i < m) {
            if (pat.charAt(i) == pat.charAt(len)) {
                len++;
                lps[i] = len;
                i++;
            } else {
                if (len != 0) {
                    len = lps[len - 1];
                } else {
                    lps[i] = 0;
                    i++;
                }
            }
        }
    }

    // Number theory
    public static boolean isPrime(int n) {
        if (n <= 1) return false;
        if (n <= 3) return true;
        if (n % 2 == 0 || n % 3 == 0) return false;
        for (int i = 5; i * i <= n; i += 6) {
            if (n % i == 0 || n % (i + 2) == 0) return false;
        }
        return true;
    }

    public static long powerWithMod(long base, long exp, int mod) {
        long res = 1;
        base %= mod;
        while (exp > 0) {
            if ((exp & 1) == 1) res = (res * base) % mod;
            exp >>= 1;
            base = (base * base) % mod;
        }
        return res;
    }

    public static long powerWithoutMod(long base, int exp) {
        if (exp == 0) return 1;
        long temp = powerWithoutMod(base, exp / 2);
        if (exp % 2 == 0) return temp * temp;
        return base * temp * temp;
    }

    public static long gcd(long a, long b) {
        return b == 0 ? a : gcd(b, a % b);
    }

    public static long modInverse(long a, int m) {
        return powerWithMod(a, m - 2, m);
    }

    // Fraction handling
    public static void fraction(double x) {
        String parts = String.valueOf(x);
        if (!parts.contains(".")) return;
        String[] split = parts.split("\\.");
        int decimals = split[1].length();
        int denominator = (int) Math.pow(10, decimals);
        int numerator = (int) (x * denominator);
        long commonDivisor = gcd(numerator, denominator);
        numerator /= commonDivisor;
        denominator /= commonDivisor;

        long inv = modInverse(denominator, 998244353);
        System.out.println(((numerator % 998244353) * (inv % 998244353)) % 998244353);
    }

    // Graph
    public static int bfs(int start, List<List<Integer>> adj, int target, boolean[] visited) {
        Queue<Integer> q = new LinkedList<>();
        Queue<Integer> distQ = new LinkedList<>();
        q.add(start);
        distQ.add(0);
        visited[start] = true;

        while (!q.isEmpty()) {
            int u = q.poll();
            int d = distQ.poll();
            if (u == target) return d;

            for (int v : adj.get(u)) {
                if (!visited[v]) {
                    visited[v] = true;
                    q.add(v);
                    distQ.add(d + 1);
                }
            }
        }
        return -1;
    }

    // Sieve & Combinatorics
    private static final int MAX_N = 100000;
    private static final int[] SPF = new int[MAX_N];
    private static final long[] FAC = new long[MAX_N];

    static {
        sieve();
        calculateFac(998244353);
    }

    private static void sieve() {
        for (int i = 0; i < MAX_N; i++) SPF[i] = i;
        for (int i = 4; i < MAX_N; i += 2) SPF[i] = 2;
        for (int i = 3; i * i < MAX_N; i++) {
            if (SPF[i] == i) {
                for (int j = i * i; j < MAX_N; j += i) {
                    if (SPF[j] == j) SPF[j] = i;
                }
            }
        }
    }

    private static void calculateFac(int mod) {
        FAC[0] = 1;
        for (int i = 1; i < MAX_N; i++) {
            FAC[i] = (FAC[i - 1] * i) % mod;
        }
    }

    public static List<Integer> getFactorization(int x) {
        List<Integer> factors = new ArrayList<>();
        while (x > 1) {
            factors.add(SPF[x]);
            x /= SPF[x];
        }
        return factors;
    }

    public static long nCrModP(int n, int r, int mod) {
        if (r < 0 || r > n) return 0;
        return (FAC[n] * modInverse(FAC[r], mod) % mod * modInverse(FAC[n - r], mod)) % mod;
    }
}

import java.io.IOException;
import java.io.InputStream;
import java.io.OutputStream;
import java.io.PrintWriter;

public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        FastScanner in = new FastScanner(inputStream);
        PrintWriter out = new PrintWriter(outputStream);

        GarlandSolver solver = new GarlandSolver();
        solver.solve(in, out);

        out.close();
    }

    /**
     * Solves the Garland problem using dynamic programming with memoization.
     * Refactored for readability, state encapsulation, and memory efficiency.
     */
    static class GarlandSolver {
        private int[] arr;
        private int n;
        private Long[][][][] dp;
        private static final long INF = Long.MAX_VALUE / 2;

        public void solve(FastScanner in, PrintWriter out) {
            n = in.nextInt();
            arr = new int[n];
            for (int i = 0; i < n; i++) {
                arr[i] = in.nextInt();
            }

            // Count available even and odd numbers to fill the zeros
            int evenCount = 0;
            int oddCount = 0;
            boolean[] used = new boolean[n + 1];

            for (int val : arr) {
                if (val != 0) {
                    used[val] = true;
                    if (val % 2 == 0) evenCount++;
                    else oddCount++;
                }
            }

            // Identify missing numbers and update counts
            for (int i = 1; i <= n; i++) {
                if (!used[i]) {
                    if (i % 2 == 0) evenCount++;
                    else oddCount++;
                }
            }

            // Initialize DP table: dp[index][odd][even][parity]
            // Using tighter bounds improves memory usage and cache locality
            dp = new Long[n][oddCount + 1][evenCount + 1][2];

            long ans;
            if (arr[0] == 0) {
                // First position is empty: try placing an even (0) or odd (1) number
                ans = Math.min(solveDP(1, oddCount, evenCount - 1, 0),
                               solveDP(1, oddCount - 1, evenCount, 1));
            } else {
                // First position is fixed
                ans = solveDP(1, oddCount, evenCount, arr[0] % 2);
            }

            out.println(ans);
        }

        /**
         * Recursive DP with memoization to find the minimum cost.
         *
         * @param index   Current position in the array
         * @param odd     Remaining odd numbers available to place
         * @param even    Remaining even numbers available to place
         * @param parity  Expected parity of the previous element (0 for even, 1 for odd)
         * @return        Minimum cost from this state to the end
         */
        private long solveDP(int index, int odd, int even, int parity) {
            // Invalid state: requested more numbers than available
            if (odd < 0 || even < 0) return INF;
            // Base case: successfully filled all positions
            if (index == n) return 0;

            // Return memoized result if available
            if (dp[index][odd][even][parity] != null) {
                return dp[index][odd][even][parity];
            }

            long result = INF;
            if (arr[index] != 0) {
                // Fixed value: check parity match and recurse
                int currentParity = arr[index] % 2;
                int cost = (currentParity == parity) ? 0 : 1;
                result = cost + solveDP(index + 1, odd, even, currentParity);
            } else {
                // Empty slot: try placing an even number (0)
                int costEven = (0 == parity) ? 0 : 1;
                result = Math.min(result, costEven + solveDP(index + 1, odd, even - 1, 0));

                // Try placing an odd number (1)
                int costOdd = (1 == parity) ? 0 : 1;
                result = Math.min(result, costOdd + solveDP(index + 1, odd - 1, even, 1));
            }

            // Store and return result
            return dp[index][odd][even][parity] = result;
        }
    }

    /**
     * High-performance input scanner for competitive programming style I/O.
     * Replaces standard Scanner to avoid TLE on large inputs.
     */
    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0;
        private int buflen = 0;

        public FastScanner(InputStream in) {
            this.in = in;
        }

        private int readByte() {
            if (ptr >= buflen) {
                ptr = 0;
                try {
                    buflen = in.read(buffer);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input", e);
                }
                if (buflen <= 0) return -1;
            }
            return buffer[ptr++];
        }

        public int nextInt() {
            int c = readByte();
            while (c <= ' ') {
                if (c == -1) throw new RuntimeException("Unexpected end of input");
                c = readByte();
            }
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = readByte();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9') throw new RuntimeException("Invalid number format");
                res = res * 10 + (c - '0');
                c = readByte();
            } while (c > ' ');
            return res * sgn;
        }
    }
}

import java.io.*;
import java.util.*;

public class Main {

    /**
     * Represents a contiguous segment of gaps (zeros) in the array.
     * Used to determine the cost of filling these gaps based on neighbor parities.
     */
    static class GapSegment implements Comparable<GapSegment> {
        int start;
        int end;
        int cost;
        int length;

        public GapSegment(int start, int end, int cost) {
            this.start = start;
            this.end = end;
            this.cost = cost;
            this.length = end - start + 1;
        }

        @Override
        public int compareTo(GapSegment other) {
            // Sort by cost descending (higher cost segments processed first)
            int costDiff = Integer.compare(other.cost, this.cost);
            if (costDiff != 0) {
                return costDiff;
            }
            // If costs are equal, sort by length ascending (shorter segments processed first)
            return Integer.compare(this.length, other.length);
        }
    }

    public static void main(String[] args) {
        FastReader in = new FastReader();

        int n;
        try {
            n = in.nextInt();
        } catch (Exception e) {
            return;
        }

        // Edge case: Single element array requires 0 transitions
        if (n == 1) {
            System.out.println(0);
            return;
        }

        int[] values = new int[n];
        int[] remainingSlots = new int[2];
        // Target counts for parity 0 and 1 to balance the array
        remainingSlots[0] = n / 2;
        remainingSlots[1] = n / 2 + n % 2;

        int transitionCost = 0;

        // Read input and preprocess
        for (int i = 0; i < n; i++) {
            int val = in.nextInt();
            if (val == 0) {
                values[i] = -1; // -1 represents a gap (originally 0)
            } else {
                values[i] = val % 2; // Normalize to parity 0 or 1
                remainingSlots[values[i]]--;

                // Count transitions between adjacent fixed values
                if (i > 0 && values[i - 1] != -1 && values[i] != values[i - 1]) {
                    transitionCost++;
                }
            }
        }

        // If the array contains no fixed values (all gaps), the cost is 1.
        // remainingSlots sum equals N if no values were processed (all were 0/gaps).
        if (remainingSlots[0] + remainingSlots[1] == n) {
            System.out.println(1);
            return;
        }

        // List of segments for parity 0 and parity 1
        // Using List of Lists to avoid unchecked cast warnings from array of generics
        List<List<GapSegment>> segments = new ArrayList<>(2);
        segments.add(new ArrayList<>());
        segments.add(new ArrayList<>());

        // Identify contiguous segments of gaps
        for (int i = 0; i < n; i++) {
            if (values[i] != -1) {
                continue;
            }

            int start = i;
            int end = i;
            // Find the end of the current contiguous gap segment
            while (end + 1 < n && values[end + 1] == -1) {
                end++;
            }

            // Determine the preferred parity to fill this gap
            // and calculate the cost if we are forced to fill it with the wrong parity.

            int leftParity = (start > 0) ? values[start - 1] : -1;
            int rightParity = (end < n - 1) ? values[end + 1] : -1;

            if (start > 0 && end < n - 1) {
                // Gap is bounded by values on both sides
                if (leftParity == rightParity) {
                    // Neighbors have same parity.
                    // If we fill with this parity, cost is 0 (relative to neighbors).
                    // If forced to fill with other parity, cost is 2 (transitions on both sides).
                    segments.get(leftParity).add(new GapSegment(start, end, 2));
                } else {
                    // Neighbors have different parity.
                    // A transition is unavoidable between neighbors.
                    // Cost contribution is 1.
                    transitionCost++;
                    // Add to the list of the left neighbor's parity.
                    // Original logic: list[start > 0 ? p[start - 1] : p[end + 1]]
                    segments.get(leftParity).add(new GapSegment(start, end, 1));
                }
            } else {
                // Gap touches one or both boundaries.
                // Since "all gaps" case is handled, exactly one boundary neighbor must exist.
                int preferredParity;
                if (start > 0) {
                    preferredParity = values[start - 1];
                } else {
                    preferredParity = values[end + 1];
                }
                segments.get(preferredParity).add(new GapSegment(start, end, 1));
            }

            // Skip the processed gap segment
            i = end + 1;
        }

        // Process segments to calculate final cost
        // We try to fill gaps with the preferred parity if slots are available.
        // If not, we pay the penalty cost.
        for (int parity = 0; parity < 2; parity++) {
            List<GapSegment> list = segments.get(parity);
            Collections.sort(list);

            for (GapSegment seg : list) {
                if (remainingSlots[parity] >= seg.length) {
                    remainingSlots[parity] -= seg.length;
                } else {
                    transitionCost += seg.cost;
                }
            }
        }

        System.out.println(transitionCost);
    }

    /**
     * Fast Input Reader for competitive programming.
     */
    static class FastReader {
        BufferedReader reader;
        StringTokenizer st;

        public FastReader() {
            reader = new BufferedReader(new InputStreamReader(System.in));
        }

        public String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    e.printStackTrace();
                    return null;
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            String s = next();
            if (s == null) throw new RuntimeException("End of input");
            return Integer.parseInt(s);
        }
    }
}

import java.io.*;
import java.util.*;

public class Garland {
    // Constants to replace magic numbers
    private static final int INF = 1000;
    private static final int MAX_COUNT = 50;

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line = br.readLine();
        if (line == null || line.trim().isEmpty()) return;

        int n = Integer.parseInt(line.trim());
        StringTokenizer st = new StringTokenizer(br.readLine());
        int[] arr = new int[n];
        for (int i = 0; i < n; i++) {
            arr[i] = Integer.parseInt(st.nextToken());
        }

        // Calculate maximum allowed counts for evens and odds
        int maxEvens = n / 2;
        int maxOdds = (n % 2 == 0) ? n / 2 : n / 2 + 1;

        // dp[i][evens][odds][currentParity]
        // currentParity: 0 for even, 1 for odd
        int[][][][] dp = new int[n][MAX_COUNT + 1][MAX_COUNT + 1][2];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j <= MAX_COUNT; j++) {
                for (int k = 0; k <= MAX_COUNT; k++) {
                    dp[i][j][k][0] = INF;
                    dp[i][j][k][1] = INF;
                }
            }
        }

        // Try starting with an even number (parity 0) or an odd number (parity 1)
        int result = Math.min(minCost(0, 1, 0, 0, n, maxEvens, maxOdds, dp, arr),
                              minCost(0, 0, 1, 1, n, maxEvens, maxOdds, dp, arr));
        System.out.println(result);
    }

    /**
     * Recursive DP function with memoization to find the minimum cost.
     *
     * @param i            Current index in the array
     * @param evens        Count of even numbers placed so far
     * @param odds         Count of odd numbers placed so far
     * @param currentParity Target parity for the current position (0=even, 1=odd)
     * @param n            Total array length
     * @param maxEvens     Maximum allowed even numbers
     * @param maxOdds      Maximum allowed odd numbers
     * @param dp           Memoization table
     * @param arr          Input array
     * @return Minimum cost to complete the garland from index i, or INF if invalid
     */
    private static int minCost(int i, int evens, int odds, int currentParity, int n, int maxEvens, int maxOdds,
                               int[][][][] dp, int[] arr) {
        // 1. Validate parity counts against limits
        if (evens > maxEvens || odds > maxOdds || evens > MAX_COUNT || odds > MAX_COUNT) {
            return INF;
        }

        // 2. Return memoized result if available
        if (dp[i][evens][odds][currentParity] != INF) {
            return dp[i][evens][odds][currentParity];
        }

        // 3. If element is fixed, check parity compatibility
        if (arr[i] != 0 && (currentParity + arr[i]) % 2 != 0) {
            return dp[i][evens][odds][currentParity] = INF;
        }

        // 4. Base case: reached the last element
        if (i == n - 1) {
            return dp[i][evens][odds][currentParity] = 0;
        }

        int nextIdx = i + 1;
        int result;

        // 5. Recursive transitions based on current element value
        if (arr[i] == 0) {
            if (arr[nextIdx] == 0) {
                // Both current and next are placeholders
                if (currentParity == 0) {
                    result = Math.min(minCost(nextIdx, evens + 1, odds, 0, n, maxEvens, maxOdds, dp, arr),
                                      1 + minCost(nextIdx, evens, odds + 1, 1, n, maxEvens, maxOdds, dp, arr));
                } else {
                    result = Math.min(1 + minCost(nextIdx, evens + 1, odds, 0, n, maxEvens, maxOdds, dp, arr),
                                      minCost(nextIdx, evens, odds + 1, 1, n, maxEvens, maxOdds, dp, arr));
                }
            } else {
                // Next element is fixed
                if (arr[nextIdx] % 2 == 0) {
                    if (currentParity == 0) {
                        result = minCost(nextIdx, evens + 1, odds, 0, n, maxEvens, maxOdds, dp, arr);
                    } else {
                        result = 1 + minCost(nextIdx, evens + 1, odds, 0, n, maxEvens, maxOdds, dp, arr);
                    }
                } else {
                    if (currentParity == 0) {
                        result = 1 + minCost(nextIdx, evens, odds + 1, 1, n, maxEvens, maxOdds, dp, arr);
                    } else {
                        result = minCost(nextIdx, evens, odds + 1, 1, n, maxEvens, maxOdds, dp, arr);
                    }
                }
            }
        } else {
            // Current element is fixed
            if (arr[i] % 2 == 0) {
                result = Math.min(minCost(nextIdx, evens + 1, odds, 0, n, maxEvens, maxOdds, dp, arr),
                                  1 + minCost(nextIdx, evens, odds + 1, 1, n, maxEvens, maxOdds, dp, arr));
            } else {
                result = Math.min(1 + minCost(nextIdx, evens + 1, odds, 0, n, maxEvens, maxOdds, dp, arr),
                                  minCost(nextIdx, evens, odds + 1, 1, n, maxEvens, maxOdds, dp, arr));
            }
        }

        return dp[i][evens][odds][currentParity] = result;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.Arrays;

/**
 * Solves a variation of the "Line" problem (Codeforces 7C).
 * Given an array with some missing values (0), fills them to maximize the number
 * of adjacent pairs with different parity (even/odd), while maintaining a balanced
 * count of even and odd numbers overall.
 */
public class LineParityOptimizer {

    // Parity state constants for DP memoization
    private static final int PARITY_NONE = 0;
    private static final int PARITY_ODD = 1;
    private static final int PARITY_EVEN = 2;

    public static void main(String[] args) throws IOException {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        String line1 = reader.readLine();
        if (line1 == null) return;

        int n = Integer.parseInt(line1.trim());
        String line2 = reader.readLine();
        if (line2 == null) return;

        // Parse input array, robustly handling multiple spaces
        int[] numbers = Arrays.stream(line2.trim().split("\\s+"))
                              .mapToInt(Integer::parseInt)
                              .toArray();

        int existingGoodPairs = 0;
        int evensCount = 0;
        int oddsCount = 0;

        // Count existing parities and pre-existing "good" adjacent pairs
        for (int num : numbers) {
            if (num != 0) {
                if (num % 2 == 0) evensCount++;
                else oddsCount++;
            }
        }

        for (int i = 0; i < n - 1; i++) {
            if (numbers[i] != 0 && numbers[i + 1] != 0) {
                if ((numbers[i] % 2) != (numbers[i + 1] % 2)) {
                    existingGoodPairs++;
                }
            }
        }

        // Calculate how many even/odd numbers we still need to place
        int evensNeeded = (n / 2) - evensCount;
        int oddsNeeded = ((n + 1) / 2) - oddsCount;
        int missingCount = evensNeeded + oddsNeeded;

        // DP table: dp[index][oddsNeeded][lastParity]
        // lastParity: 0 = none, 1 = odd, 2 = even
        int[][][] dp = new int[n][missingCount + 1][3];
        for (int[][] row : dp) {
            for (int[] col : row) {
                Arrays.fill(col, -1);
            }
        }

        // Solve and print result
        int maxAdditionalGoodPairs = solve(numbers, 0, oddsNeeded, evensNeeded, PARITY_NONE, dp);
        System.out.println(existingGoodPairs + maxAdditionalGoodPairs);
    }

    /**
     * Recursive DP with memoization to maximize adjacent pairs with different parity.
     *
     * @param index      Current position in the array
     * @param oddsNeeded Remaining odd numbers to place
     * @param evensNeeded Remaining even numbers to place
     * @param lastParity Parity of the previous element (0, 1, or 2)
     * @param dp         Memoization table
     * @return Maximum number of "good" (different parity) pairs achievable from this state
     */
    private static int solve(int[] numbers, int index, int oddsNeeded, int evensNeeded, int lastParity, int[][][] dp) {
        // Base case: reached the end of the array
        if (index == numbers.length) {
            return 0;
        }

        // Return memoized result if available
        if (dp[index][oddsNeeded][lastParity] != -1) {
            return dp[index][oddsNeeded][lastParity];
        }

        // If current position is fixed, move to next and check parity with previous
        if (numbers[index] != 0) {
            int currentParity = (numbers[index] % 2 == 0) ? PARITY_EVEN : PARITY_ODD;
            int result = solve(numbers, index + 1, oddsNeeded, evensNeeded, currentParity, dp);
            if (lastParity != PARITY_NONE && lastParity != currentParity) {
                result++;
            }
            dp[index][oddsNeeded][lastParity] = result;
            return result;
        }

        // Current position is 0 (missing). Try placing an odd or even number.
        int maxGain = -1;

        // Option 1: Place an odd number
        if (oddsNeeded > 0) {
            int gain = 0;
            // Check left neighbor
            if (lastParity != PARITY_NONE && lastParity != PARITY_ODD) gain++;
            // Check right neighbor
            if (index + 1 < numbers.length && numbers[index + 1] != 0 && numbers[index + 1] % 2 == 0) gain++;

            maxGain = Math.max(maxGain, gain + solve(numbers, index + 1, oddsNeeded - 1, evensNeeded, PARITY_ODD, dp));
        }

        // Option 2: Place an even number
        if (evensNeeded > 0) {
            int gain = 0;
            // Check left neighbor
            if (lastParity != PARITY_NONE && lastParity != PARITY_EVEN) gain++;
            // Check right neighbor
            if (index + 1 < numbers.length && numbers[index + 1] != 0 && numbers[index + 1] % 2 != 0) gain++;

            maxGain = Math.max(maxGain, gain + solve(numbers, index + 1, oddsNeeded, evensNeeded - 1, PARITY_EVEN, dp));
        }

        dp[index][oddsNeeded][lastParity] = maxGain;
        return maxGain;
    }
}

import java.util.Arrays;
import java.util.Scanner;

/**
 * Refactored solution for the sequence parity problem.
 * 
 * Improvements made:
 * 1. Readability: Descriptive variable names (e.g., 'sequence', 'dp', 'availableEvens') 
 *    and clear comments explaining the logic.
 * 2. Maintainability: Separated logic into a 'solve' method, used standard libraries 
 *    (Scanner) for I/O to reduce boilerplate, and added bounds checking for safety.
 * 3. Performance: Tightened loop bounds based on actual constraints (zeros count) 
 *    rather than loose upper bounds.
 * 4. Structure: Used 1-based indexing for arrays to match the algorithmic logic cleanly.
 */
public class Main {

    // Constant for infinity. 
    // Max possible cost is N (switching parity at every step), so 10^9 is safe.
    private static final int INF = 1000000000;

    public static void main(String[] args) {
        // Using Scanner for readability and simplicity. 
        // For N=200, performance overhead is negligible compared to the algorithmic complexity.
        try (Scanner scanner = new Scanner(System.in)) {
            if (scanner.hasNextInt()) {
                int n = scanner.nextInt();
                solve(n, scanner);
            }
        }
    }

    private static void solve(int n, Scanner scanner) {
        // Arrays are allocated with size n + 1 to support 1-based indexing
        // which aligns with the original algorithm's logic.
        int[] sequence = new int[n + 1];

        // Tracks which numbers from 1 to n are present in the input sequence
        boolean[] valuePresence = new boolean[n + 1];

        // Prefix sum array to count zeros encountered up to index i
        int[] zeroPrefixCount = new int[n + 1];

        // DP Table: dp[index][evensPlaced][lastParity]
        // index: Current position in sequence (1 to n)
        // evensPlaced: Number of wildcards (0s) assigned an even number so far
        // lastParity: Parity of the number placed at the current index (0 for even, 1 for odd)
        int[][][] dp = new int[n + 1][n + 1][2];

        // Initialize DP table with INF
        for (int i = 0; i <= n; i++) {
            for (int j = 0; j <= n; j++) {
                Arrays.fill(dp[i][j], INF);
            }
        }

        // 1. Read Input and Pre-processing
        for (int i = 1; i <= n; i++) {
            sequence[i] = scanner.nextInt();

            // Update prefix count of zeros
            zeroPrefixCount[i] = zeroPrefixCount[i - 1];
            if (sequence[i] == 0) {
                zeroPrefixCount[i]++;
                continue;
            }

            // Mark presence of non-zero numbers
            // Added bounds check for safety, though problem constraints likely ensure validity
            if (sequence[i] >= 1 && sequence[i] <= n) {
                valuePresence[sequence[i]] = true;
            }
        }

        // 2. Calculate Available Numbers (Missing from sequence)
        // s0: count of missing even numbers in range 1..n
        // s1: count of missing odd numbers in range 1..n
        int availableEvens = 0;
        int availableOdds = 0;

        for (int val = 1; val <= n; val++) {
            if (!valuePresence[val]) {
                if (val % 2 == 0) {
                    availableEvens++;
                } else {
                    availableOdds++;
                }
            }
        }

        // 3. Base Case Initialization (Index 1)
        // We are initializing the state after processing the first element.
        if (sequence[1] == 0) {
            // If current is wildcard (0), we can assign an Even or Odd number

            // Option A: Assign an Even number (Parity 0)
            // Requires at least one available even number.
            // EvensPlaced count becomes 1 (since we used one wildcard for an even).
            if (availableEvens > 0) {
                dp[1][1][0] = 0; 
            }

            // Option B: Assign an Odd number (Parity 1)
            // Requires at least one available odd number.
            // EvensPlaced count remains 0 (wildcard used for odd).
            if (availableOdds > 0) {
                dp[1][0][1] = 0;
            }
        } else {
            // Fixed value. Parity is determined by the value itself.
            // EvensPlaced remains 0 (since it's not a wildcard).
            dp[1][0][sequence[1] % 2] = 0;
        }

        // 4. DP Transitions
        for (int i = 1; i < n; i++) {
            // Optimization: j (evensPlaced) cannot exceed total zeros seen so far (zeroPrefixCount[i])
            // Also j cannot exceed availableEvens.
            int maxJ = Math.min(zeroPrefixCount[i], availableEvens);

            for (int j = 0; j <= maxJ; j++) {
                for (int lastParity = 0; lastParity < 2; lastParity++) {
                    if (dp[i][j][lastParity] == INF) continue;

                    int currentCost = dp[i][j][lastParity];
                    int nextVal = sequence[i + 1];

                    if (nextVal == 0) {
                        // Wildcard case: Can place Even or Odd

                        // Option 1: Place Even number (Parity 0)
                        // Requires: We have unused even numbers available.
                        // Current evens placed = j. Next would be j + 1.
                        if (j + 1 <= availableEvens) {
                            // Cost transition: (lastParity ^ 0) -> just lastParity
                            // If lastParity was 1 (odd), cost increases by 1.
                            int transitionCost = currentCost + lastParity;
                            if (transitionCost < dp[i + 1][j + 1][0]) {
                                dp[i + 1][j + 1][0] = transitionCost;
                            }
                        }

                        // Option 2: Place Odd number (Parity 1)
                        // Requires: We have unused odd numbers available.
                        // Total zeros processed so far = zeroPrefixCount[i].
                        // Zeros assigned to even = j.
                        // Zeros assigned to odd = zeroPrefixCount[i] - j.
                        // We are about to assign one more odd.
                        // Check: (zeroPrefixCount[i] - j) + 1 <= availableOdds
                        if (zeroPrefixCount[i] - j + 1 <= availableOdds) {
                            // Cost transition: (lastParity ^ 1)
                            // If lastParity was 0 (even), cost increases by 1.
                            int transitionCost = currentCost + (lastParity ^ 1);
                            if (transitionCost < dp[i + 1][j][1]) {
                                dp[i + 1][j][1] = transitionCost;
                            }
                        }
                    } else {
                        // Fixed value case
                        int parity = nextVal % 2;
                        // Cost transition: (lastParity ^ parity)
                        // Cost increases if parities differ.
                        int transitionCost = currentCost + (lastParity ^ parity);

                        if (transitionCost < dp[i + 1][j][parity]) {
                            dp[i + 1][j][parity] = transitionCost;
                        }
                    }
                }
            }
        }

        // 5. Result Extraction
        int ans = n + 1; // Initialize with a value larger than any possible cost

        // Check all valid states at index n
        // j ranges from 0 to availableEvens
        for (int j = 0; j <= availableEvens; j++) {
            ans = Math.min(ans, dp[n][j][0]);
            ans = Math.min(ans, dp[n][j][1]);
        }

        System.out.println(ans);
    }
}

import java.io.IOException;
import java.io.InputStream;
import java.io.OutputStream;
import java.io.PrintWriter;
import java.util.InputMismatchException;

public class Main {

    public static void main(String[] args) {
        // Setup fast I/O streams
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);

        // Instantiate and run the solver
        GarlandSolver solver = new GarlandSolver();
        solver.solve(in, out);

        // Ensure all output is flushed and resources are closed
        out.flush();
        out.close();
    }

    /**
     * Solves the Garland problem using dynamic programming.
     * 
     * DP State: dp[i][j][k][last]
     * - i: Number of positions processed so far
     * - j: Number of 0s remaining to be placed
     * - k: Number of 1s remaining to be placed
     * - last: The value (0 or 1) placed at position i
     * - Value: Minimum cost (flips) to achieve this state
     */
    static class GarlandSolver {
        private static final int INF = Integer.MAX_VALUE / 2; // Safe infinity to prevent overflow on addition
        private static final int EMPTY_SLOT = -1;

        public void solve(InputReader in, PrintWriter out) {
            int n = in.nextInt();
            int[] sequence = new int[n + 1];
            int[] remainingCounts = new int[2];

            // In a perfect alternating sequence of length n:
            // Count of 0s = n / 2
            // Count of 1s = (n + 1) / 2
            remainingCounts[0] = n / 2;
            remainingCounts[1] = (n + 1) / 2;

            // Read input and preprocess values
            for (int i = 1; i <= n; i++) {
                int val = in.nextInt();
                // 0 represents an empty slot, 1 or 2 represent fixed values (normalized to 0 or 1)
                sequence[i] = (val == 0) ? EMPTY_SLOT : (val % 2);

                if (sequence[i] != EMPTY_SLOT) {
                    remainingCounts[sequence[i]]--;
                }
            }

            // Initialize and compute DP table
            int[][][][] dp = initializeDP(n, remainingCounts);
            computeDP(sequence, remainingCounts, dp);

            // Extract result from the final state
            int result = Math.min(dp[n][remainingCounts[0]][remainingCounts[1]][0],
                                  dp[n][remainingCounts[0]][remainingCounts[1]][1]);
            out.println(result);
        }

        /**
         * Initializes the 4D DP table with infinity, except for the base case.
         */
        private int[][][][] initializeDP(int n, int[] remainingCounts) {
            int[][][][] dp = new int[n + 1][remainingCounts[0] + 1][remainingCounts[1] + 1][2];

            for (int i = 0; i <= n; i++) {
                for (int j = 0; j <= remainingCounts[0]; j++) {
                    for (int k = 0; k <= remainingCounts[1]; k++) {
                        dp[i][j][k][0] = INF;
                        dp[i][j][k][1] = INF;
                    }
                }
            }

            // Base case: 0 positions processed, 0 cost
            dp[0][0][0][0] = 0;
            dp[0][0][0][1] = 0;
            return dp;
        }

        /**
         * Fills the DP table using transitions based on whether the current position is fixed or empty.
         */
        private void computeDP(int[] sequence, int[] remainingCounts, int[][][][] dp) {
            int n = sequence.length - 1;

            for (int i = 1; i <= n; i++) {
                for (int j = 0; j <= remainingCounts[0]; j++) {
                    for (int k = 0; k <= remainingCounts[1]; k++) {
                        if (sequence[i] == EMPTY_SLOT) {
                            // Current position is empty. We can place either 0 or 1.

                            // Option 1: Place a 0 (requires at least one 0 remaining)
                            if (j > 0) {
                                dp[i][j][k][0] = Math.min(dp[i - 1][j - 1][k][0],
                                                          dp[i - 1][j - 1][k][1] + 1);
                            }

                            // Option 2: Place a 1 (requires at least one 1 remaining)
                            if (k > 0) {
                                dp[i][j][k][1] = Math.min(dp[i - 1][j][k - 1][1],
                                                          dp[i - 1][j][k - 1][0] + 1);
                            }
                        } else {
                            // Current position is fixed. The last value must match the fixed value.
                            int fixedVal = sequence[i];

                            // We can either keep the fixed value (cost 0) or flip it (cost 1)
                            dp[i][j][k][fixedVal] = Math.min(dp[i - 1][j][k][fixedVal],
                                                             1 + dp[i - 1][j][k][1 ^ fixedVal]);
                        }
                    }
                }
            }
        }
    }

    /**
     * Fast input reader for competitive programming and performance-critical applications.
     * Handles whitespace skipping and integer parsing efficiently.
     */
    static class InputReader {
        private final InputStream stream;
        private final byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;
        private SpaceCharFilter filter;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        public int read() {
            if (numChars == -1) {
                throw new InputMismatchException();
            }
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0) {
                    return -1;
                }
            }
            return buf[curChar++];
        }

        public int nextInt() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }

            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }

            int res = 0;
            do {
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                res *= 10;
                res += c - '0';
                c = read();
            } while (!isSpaceChar(c));

            return res * sgn;
        }

        public boolean isSpaceChar(int c) {
            return filter != null ? filter.isSpaceChar(c) : isWhitespace(c);
        }

        public static boolean isWhitespace(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        @FunctionalInterface
        public interface SpaceCharFilter {
            boolean isSpaceChar(int ch);
        }
    }
}

import java.util.ArrayList;
import java.util.Collections;
import java.util.HashSet;
import java.util.List;
import java.util.Scanner;
import java.util.Set;

public class Solution {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        // Read the size of the array
        if (!scanner.hasNextInt()) {
            scanner.close();
            return;
        }
        int arrayLength = scanner.nextInt();

        int[] inputArray = new int[arrayLength];
        for (int i = 0; i < arrayLength; i++) {
            inputArray[i] = scanner.nextInt();
        }

        // Identify existing numbers and store indices of non-zero numbers
        Set<Integer> existingNumbers = new HashSet<>();
        List<Integer> nonZeroIndices = new ArrayList<>();

        for (int i = 0; i < arrayLength; i++) {
            if (inputArray[i] != 0) {
                existingNumbers.add(inputArray[i]);
                nonZeroIndices.add(i);
            }
        }

        // Edge case: If the array contains only zeros
        if (nonZeroIndices.isEmpty()) {
            System.out.println(arrayLength == 1 ? 0 : 1);
            scanner.close();
            return;
        }

        // Count missing numbers in range [1, n] based on parity
        int missingOddCount = 0;
        int missingEvenCount = 0;
        for (int i = 1; i <= arrayLength; i++) {
            if (!existingNumbers.contains(i)) {
                if (i % 2 == 0) {
                    missingEvenCount++;
                } else {
                    missingOddCount++;
                }
            }
        }

        int totalOperations = 0;
        List<Integer> evenGaps = new ArrayList<>();
        List<Integer> oddGaps = new ArrayList<>();

        // Calculate gaps between consecutive non-zero numbers
        for (int i = 1; i < nonZeroIndices.size(); i++) {
            int currentIndex = nonZeroIndices.get(i);
            int previousIndex = nonZeroIndices.get(i - 1);

            // Check parity of the numbers surrounding the gap
            if (inputArray[currentIndex] % 2 == inputArray[previousIndex] % 2) {
                int gapLength = currentIndex - previousIndex - 1;
                if (inputArray[currentIndex] % 2 == 0) {
                    evenGaps.add(gapLength);
                } else {
                    oddGaps.add(gapLength);
                }
            } else {
                // Mismatch in parity requires an operation
                totalOperations++;
            }
        }

        // Sort gaps to process smallest first (Greedy strategy)
        Collections.sort(evenGaps);
        Collections.sort(oddGaps);

        // Process internal gaps
        // If gap size > available missing numbers, cost increases by 2.
        // Otherwise, we use the missing numbers to fill the gap.
        for (int gap : evenGaps) {
            if (missingEvenCount >= gap) {
                missingEvenCount -= gap;
            } else {
                totalOperations += 2;
            }
        }

        for (int gap : oddGaps) {
            if (missingOddCount >= gap) {
                missingOddCount -= gap;
            } else {
                totalOperations += 2;
            }
        }

        // Process the gap before the first non-zero number (Prefix)
        int firstIndex = nonZeroIndices.get(0);
        int prefixGap = firstIndex; // Distance from start (index 0)

        if (inputArray[firstIndex] % 2 == 0) {
            if (missingEvenCount >= prefixGap) {
                missingEvenCount -= prefixGap;
            } else {
                totalOperations += 1;
            }
        } else {
            if (missingOddCount >= prefixGap) {
                missingOddCount -= prefixGap;
            } else {
                totalOperations += 1;
            }
        }

        // Process the gap after the last non-zero number (Suffix)
        int lastIndex = nonZeroIndices.get(nonZeroIndices.size() - 1);
        int suffixGap = (arrayLength - 1) - lastIndex; // Distance to end

        if (inputArray[lastIndex] % 2 == 0) {
            if (missingEvenCount >= suffixGap) {
                missingEvenCount -= suffixGap;
            } else {
                totalOperations += 1;
            }
        } else {
            if (missingOddCount >= suffixGap) {
                missingOddCount -= suffixGap;
            } else {
                totalOperations += 1;
            }
        }

        System.out.println(totalOperations);
        scanner.close();
    }
}

import java.io.IOException;
import java.io.InputStream;
import java.io.OutputStream;
import java.io.PrintWriter;
import java.util.Arrays;
import java.util.InputMismatchException;

public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);

        ParityPlacementSolver solver = new ParityPlacementSolver();
        solver.solve(in, out);

        out.close();
    }

    /**
     * Solves the parity placement optimization problem using memoized recursion.
     * The goal is to fill empty positions (0s) with missing even/odd numbers
     * to minimize parity transitions.
     */
    static class ParityPlacementSolver {
        private static final int PARITY_EVEN = 0;
        private static final int PARITY_ODD = 1;
        private static final int INF = 100000;
        private static final int UNCOMPUTED = -1;

        public void solve(InputReader in, PrintWriter out) {
            int n = in.readInt();
            int[] givenValues = in.readIntArray(n);

            // Efficiently count missing even and odd numbers in O(n)
            int[] missingCounts = countMissingParities(n, givenValues);
            int missingEven = missingCounts[0];
            int missingOdd = missingCounts[1];

            // Initialize memoization table with dimensions tailored to actual missing counts
            int[][][][] memoizationTable = new int[n][missingEven + 1][missingOdd + 1][2];
            fillMemoizationTable(memoizationTable, UNCOMPUTED);

            // Try starting with both even and odd parity, take the minimum
            int ans = computeMinCost(givenValues, 0, missingEven, missingOdd, PARITY_EVEN, memoizationTable);
            ans = Math.min(computeMinCost(givenValues, 0, missingEven, missingOdd, PARITY_ODD, memoizationTable), ans);

            out.println(ans);
        }

        /**
         * Counts how many even and odd numbers from 1 to n are missing in the given array.
         */
        private int[] countMissingParities(int n, int[] givenValues) {
            boolean[] present = new boolean[n + 1];
            for (int val : givenValues) {
                if (val > 0 && val <= n) {
                    present[val] = true;
                }
            }

            int missingEven = 0;
            int missingOdd = 0;
            for (int i = 1; i <= n; i++) {
                if (!present[i]) {
                    if (i % 2 == 0) missingEven++;
                    else missingOdd++;
                }
            }
            return new int[]{missingEven, missingOdd};
        }

        /**
         * Fills the multi-dimensional memoization table with a specified value.
         */
        private void fillMemoizationTable(int[][][][] table, int value) {
            for (int i = 0; i < table.length; i++) {
                for (int j = 0; j < table[i].length; j++) {
                    for (int k = 0; k < table[i][j].length; k++) {
                        Arrays.fill(table[i][j][k], value);
                    }
                }
            }
        }

        /**
         * Recursively computes the minimum cost to fill the remaining positions,
         * considering parity constraints and the parity of the previously placed number.
         */
        private int computeMinCost(int[] givenValues, int currentIndex, int remainingEven,
                                   int remainingOdd, int lastParity, int[][][][] memo) {
            // Base case: all positions processed
            if (currentIndex == givenValues.length) {
                return 0;
            }

            // Return cached result if available
            if (memo[currentIndex][remainingEven][remainingOdd][lastParity] != UNCOMPUTED) {
                return memo[currentIndex][remainingEven][remainingOdd][lastParity];
            }

            // If the position is pre-filled, just check parity transition
            if (givenValues[currentIndex] != 0) {
                int currentParity = givenValues[currentIndex] % 2;
                int cost = computeMinCost(givenValues, currentIndex + 1, remainingEven, remainingOdd, currentParity, memo);
                if (lastParity != currentParity) {
                    cost++;
                }
                return memo[currentIndex][remainingEven][remainingOdd][lastParity] = cost;
            }

            // Position is empty: try placing an even number
            int minCost = INF;
            if (remainingEven > 0) {
                int cost = computeMinCost(givenValues, currentIndex + 1, remainingEven - 1, remainingOdd, PARITY_EVEN, memo);
                if (lastParity == PARITY_ODD) {
                    cost++;
                }
                minCost = Math.min(minCost, cost);
            }

            // Try placing an odd number
            if (remainingOdd > 0) {
                int cost = computeMinCost(givenValues, currentIndex + 1, remainingEven, remainingOdd - 1, PARITY_ODD, memo);
                if (lastParity == PARITY_EVEN) {
                    cost++;
                }
                minCost = Math.min(minCost, cost);
            }

            return memo[currentIndex][remainingEven][remainingOdd][lastParity] = minCost;
        }
    }

    /**
     * Fast input reader for competitive programming environments.
     */
    static class InputReader {
        private final InputStream stream;
        private final byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;
        private SpaceCharFilter filter;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        public int read() {
            if (numChars == -1) {
                throw new InputMismatchException();
            }
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0) {
                    return -1;
                }
            }
            return buf[curChar++];
        }

        public int readInt() {
            int c = read();
            if (c == -1) {
                throw new InputMismatchException();
            }
            while (isSpaceChar(c)) {
                c = read();
            }

            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }

            int res = 0;
            do {
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                res *= 10;
                res += c - '0';
                c = read();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public boolean isSpaceChar(int c) {
            return filter != null ? filter.isSpaceChar(c) : isWhitespace(c);
        }

        public static boolean isWhitespace(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        public int[] readIntArray(int size) {
            int[] ans = new int[size];
            for (int i = 0; i < size; i++) {
                ans[i] = readInt();
            }
            return ans;
        }

        public interface SpaceCharFilter {
            boolean isSpaceChar(int ch);
        }
    }
}

import java.io.DataInputStream;
import java.io.IOException;
import java.io.PrintWriter;

/**
 * Solves the alternating parity minimization problem using memoized DP.
 * Reads an array with zeros, counts required even/odd placements,
 * and computes the minimum changes needed to achieve alternating parity.
 */
public class AlternatingParity {

    private int n;
    private int[] arr;
    private int[][][][] dp;
    private FastReader scanner;
    private PrintWriter out;

    public static void main(String[] args) {
        // Instantiating the solver keeps state encapsulated and avoids static pollution.
        new AlternatingParity().run();
    }

    private void run() {
        scanner = new FastReader();
        out = new PrintWriter(System.out);
        try {
            solve();
        } catch (IOException e) {
            e.printStackTrace();
        } finally {
            out.flush();
            out.close();
        }
    }

    private void solve() throws IOException {
        n = scanner.nextInt();
        arr = new int[n];

        // Calculate how many even/odd numbers are still needed to complete an alternating sequence.
        // Assuming the sequence starts with an even number at index 0.
        int remainingEven = n / 2;
        int remainingOdd = (n + 1) / 2;

        for (int i = 0; i < n; i++) {
            arr[i] = scanner.nextInt();
            if (arr[i] != 0) {
                if (arr[i] % 2 == 0) {
                    remainingEven--;
                } else {
                    remainingOdd--;
                }
            }
        }

        // Initialize DP table with -1 (uncomputed state)
        dp = new int[n + 1][n + 1][n + 1][2];
        for (int i = 0; i <= n; i++) {
            for (int j = 0; j <= n; j++) {
                for (int k = 0; k <= n; k++) {
                    dp[i][j][k][0] = dp[i][j][k][1] = -1;
                }
            }
        }

        // Compute and output the result
        int result = computeMinChanges(0, remainingEven, remainingOdd, 0);
        out.println(result);
    }

    /**
     * Recursive memoized function to find minimum changes.
     *
     * @param idx         Current index in the array
     * @param evenRem     Remaining even numbers available to place
     * @param oddRem      Remaining odd numbers available to place
     * @param prevParity  Parity of the previous element (0 for even, 1 for odd)
     * @return            Minimum changes needed from idx to n
     */
    private int computeMinChanges(int idx, int evenRem, int oddRem, int prevParity) {
        if (idx == n) {
            return 0;
        }
        if (dp[idx][evenRem][oddRem][prevParity] != -1) {
            return dp[idx][evenRem][oddRem][prevParity];
        }

        int currentVal = arr[idx];
        if (currentVal != 0) {
            int currentParity = currentVal % 2;
            // Cost is 1 if current parity matches previous parity (violation of alternation)
            int cost = (idx > 0 && currentParity == prevParity) ? 1 : 0;
            return dp[idx][evenRem][oddRem][prevParity] =
                    computeMinChanges(idx + 1, evenRem, oddRem, currentParity) + cost;
        }

        int minChanges = Integer.MAX_VALUE;

        // Try placing an even number (parity 0)
        if (evenRem > 0) {
            int cost = (idx > 0) ? prevParity : 0;
            minChanges = Math.min(minChanges, computeMinChanges(idx + 1, evenRem - 1, oddRem, 0) + cost);
        }

        // Try placing an odd number (parity 1)
        if (oddRem > 0) {
            int cost = (idx > 0) ? (1 - prevParity) : 0;
            minChanges = Math.min(minChanges, computeMinChanges(idx + 1, evenRem, oddRem - 1, 1) + cost);
        }

        return dp[idx][evenRem][oddRem][prevParity] = minChanges;
    }

    /**
     * Fast I/O helper class for competitive programming.
     */
    private static class FastReader {
        private static final int BUFFER_SIZE = 1 << 16;
        private final DataInputStream din;
        private final byte[] buffer;
        private int bufferPointer, bytesRead;

        public FastReader() {
            din = new DataInputStream(System.in);
            buffer = new byte[BUFFER_SIZE];
            bufferPointer = bytesRead = 0;
        }

        public FastReader(String file_name) throws IOException {
            din = new DataInputStream(new java.io.FileInputStream(file_name));
            buffer = new byte[BUFFER_SIZE];
            bufferPointer = bytesRead = 0;
        }

        public String readLine() throws IOException {
            byte[] buf = new byte[1000000];
            int cnt = 0, c;
            while ((c = read()) != -1) {
                if (c == '\n') break;
                buf[cnt++] = (byte) c;
            }
            return new String(buf, 0, cnt);
        }

        public int nextInt() throws IOException {
            int ret = 0;
            byte c = read();
            while (c <= ' ') c = read();
            boolean neg = (c == '-');
            if (neg) c = read();
            do {
                ret = ret * 10 + c - '0';
            } while ((c = read()) >= '0' && c <= '9');
            if (neg) return -ret;
            return ret;
        }

        public long nextLong() throws IOException {
            long ret = 0;
            byte c = read();
            while (c <= ' ') c = read();
            boolean neg = (c == '-');
            if (neg) c = read();
            do {
                ret = ret * 10 + c - '0';
            } while ((c = read()) >= '0' && c <= '9');
            if (neg) return -ret;
            return ret;
        }

        public double nextDouble() throws IOException {
            double ret = 0, div = 1;
            byte c = read();
            while (c <= ' ') c = read();
            boolean neg = (c == '-');
            if (neg) c = read();
            do {
                ret = ret * 10 + c - '0';
            } while ((c = read()) >= '0' && c <= '9');
            if (c == '.') {
                while ((c = read()) >= '0' && c <= '9') {
                    ret += (c - '0') / (div *= 10);
                }
            }
            if (neg) return -ret;
            return ret;
        }

        private void fillBuffer() throws IOException {
            bytesRead = din.read(buffer, bufferPointer = 0, BUFFER_SIZE);
            if (bytesRead == -1) buffer[0] = -1;
        }

        private byte read() throws IOException {
            if (bufferPointer == bytesRead) fillBuffer();
            return buffer[bufferPointer++];
        }

        public void close() throws IOException {
            if (din != null) {
                din.close();
            }
        }
    }
}

import java.util.Arrays;
import java.util.Scanner;

public class Main {
    // Maximum size for N. The original code used 102, suggesting N <= 100.
    private static final int MAX_N = 102;

    // DP table: [previousValue][remainingOdds][remainingEvens][currentIndex]
    // previousValue: 0 (None/Start), 1 (Odd), 2 (Even)
    // remainingOdds: Number of 1s allowed to be placed in remaining 0-slots
    // remainingEvens: Number of 2s allowed to be placed in remaining 0-slots
    // currentIndex: Current index in the input array being processed
    private static int[][][][] dp;

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        // Read n
        if (!sc.hasNextInt()) {
            sc.close();
            return;
        }
        int n = sc.nextInt();

        int[] constraints = new int[n];
        int oddsUsedByFixed = 0;
        int evensUsedByFixed = 0;

        // Read input and normalize to 0 (wildcard), 1 (odd), 2 (even)
        // Also count how many odds/evens are fixed by the input to adjust available counts later.
        for (int i = 0; i < n; i++) {
            if (sc.hasNextInt()) {
                int val = sc.nextInt();
                if (val == 0) {
                    constraints[i] = 0;
                } else if (val % 2 != 0) {
                    constraints[i] = 1; // Treat any odd as 1
                    oddsUsedByFixed++;
                } else {
                    constraints[i] = 2; // Treat any even as 2
                    evensUsedByFixed++;
                }
            }
        }

        // Calculate available counts for 1s and 2s that can be placed in wildcard (0) positions.
        // The problem implies a global constraint on the total count of odds and evens in the sequence.
        // Specifically, for a sequence of length n, we typically need (n+1)/2 odds and n/2 evens.
        int totalOddsAllowed = (n + 1) / 2;
        int totalEvensAllowed = n / 2;

        int oddsAvailable = totalOddsAllowed - oddsUsedByFixed;
        int evensAvailable = totalEvensAllowed - evensUsedByFixed;

        // Initialize DP table with -1 (unvisited)
        dp = new int[3][MAX_N][MAX_N][MAX_N];
        for (int[][][] layer1 : dp) {
            for (int[][] layer2 : layer1) {
                for (int[] layer3 : layer2) {
                    Arrays.fill(layer3, -1);
                }
            }
        }

        // Start recursion from index 0, with no previous value (state 0)
        int result = solve(0, oddsAvailable, evensAvailable, 0, constraints);

        System.out.println(result);
        sc.close();
    }

    /**
     * Recursive function with memoization to find the minimum cost.
     *
     * @param index          Current index in the constraints array.
     * @param oddsRemaining  Number of 1s (odds) we are still allowed to place in 0-slots.
     * @param evensRemaining Number of 2s (evens) we are still allowed to place in 0-slots.
     * @param previousValue  The value placed at index - 1 (0, 1, or 2). 0 indicates start.
     * @param constraints    The input array of constraints.
     * @return Minimum cost to complete the array, or Integer.MAX_VALUE if impossible.
     */
    private static int solve(int index, int oddsRemaining, int evensRemaining, int previousValue, int[] constraints) {
        // Base case: If we have processed all elements, the cost is 0.
        if (index == constraints.length) {
            return 0;
        }

        // Check memoization table
        // previousValue maps to index 0, 1, 2
        if (dp[previousValue][oddsRemaining][evensRemaining][index] != -1) {
            return dp[previousValue][oddsRemaining][evensRemaining][index];
        }

        int currentConstraint = constraints[index];
        int minCost = Integer.MAX_VALUE;
        boolean possible = false;

        // Determine possible moves based on the constraint at current index
        // A constraint of 0 means we can place either 1 or 2 (if counts allow).
        // A constraint of 1 means we must place 1.
        // A constraint of 2 means we must place 2.

        // Option 1: Place 1 (Odd)
        if (currentConstraint == 0 || currentConstraint == 1) {
            // If the constraint is 1 (fixed), we don't consume oddsRemaining because 
            // it was already decremented in main() based on fixed inputs.
            // If the constraint is 0 (wildcard), we consume one from oddsRemaining.
            int oddsToConsume = (currentConstraint == 0) ? 1 : 0;

            if (oddsRemaining >= oddsToConsume) {
                // Calculate transition cost. 
                // If previousValue is 0 (start), cost is 0. Otherwise abs difference.
                int transitionCost = (previousValue == 0) ? 0 : Math.abs(previousValue - 1);

                int subProblemCost = solve(index + 1, oddsRemaining - oddsToConsume, evensRemaining, 1, constraints);

                if (subProblemCost != Integer.MAX_VALUE) {
                    minCost = Math.min(minCost, transitionCost + subProblemCost);
                    possible = true;
                }
            }
        }

        // Option 2: Place 2 (Even)
        if (currentConstraint == 0 || currentConstraint == 2) {
            int evensToConsume = (currentConstraint == 0) ? 1 : 0;

            if (evensRemaining >= evensToConsume) {
                int transitionCost = (previousValue == 0) ? 0 : Math.abs(previousValue - 2);

                int subProblemCost = solve(index + 1, oddsRemaining, evensRemaining - evensToConsume, 2, constraints);

                if (subProblemCost != Integer.MAX_VALUE) {
                    minCost = Math.min(minCost, transitionCost + subProblemCost);
                    possible = true;
                }
            }
        }

        // If no valid moves were found, mark as impossible (MAX_VALUE)
        if (!possible) {
            minCost = Integer.MAX_VALUE;
        }

        // Store result in DP table
        dp[previousValue][oddsRemaining][evensRemaining][index] = minCost;
        return minCost;
    }
}

import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) {
        FastScanner scanner = new FastScanner();
        PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out));
        try {
            // Read number of test cases
            String tStr = scanner.next();
            if (tStr == null) return;
            int t = Integer.parseInt(tStr);

            while (t-- > 0) {
                out.println(new ProblemSolver().solve(scanner));
            }
        } finally {
            out.flush();
            out.close();
        }
    }

    /**
     * Encapsulates the core algorithm and state for a single test case.
     * Uses memoized recursion to find the minimum parity transitions.
     */
    static class ProblemSolver {
        private int n;
        private int[] arr;
        private int[][][][] dp;

        /**
         * Solves the problem for a single test case.
         * @param sc FastScanner instance to read input
         * @return Minimum cost/changes required
         */
        public int solve(FastScanner sc) {
            n = sc.nextInt();
            arr = new int[n];

            // Initial counts based on problem constraints
            int oddCount = (n + 1) / 2;
            int evenCount = n / 2;

            for (int i = 0; i < n; i++) {
                int val = sc.nextInt();
                if (val == 0) {
                    arr[i] = -1; // Represents an unknown/unfixed position
                } else {
                    arr[i] = val & 1; // Keep only parity (0 for even, 1 for odd)
                    if (arr[i] == 1) {
                        oddCount--;
                    } else {
                        evenCount--;
                    }
                }
            }

            // Base case: single element requires 0 changes
            if (n == 1) {
                return 0;
            }

            initializeDP();

            // Try starting with both parity 0 and 1, take the minimum
            return Math.min(solve(0, evenCount, oddCount, 0),
                            solve(0, evenCount, oddCount, 1));
        }

        /**
         * Initializes the 4D DP table with -1 to indicate uncomputed states.
         * Dimensions: [current_index][remaining_evens][remaining_odds][last_parity]
         */
        private void initializeDP() {
            dp = new int[n][n][n][2];
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < n; j++) {
                    for (int k = 0; k < n; k++) {
                        dp[i][j][k][0] = -1;
                        dp[i][j][k][1] = -1;
                    }
                }
            }
        }

        /**
         * Recursive function with memoization to compute minimum changes.
         * @param idx Current position in the array
         * @param evenRemaining Number of even values we can still place
         * @param oddRemaining Number of odd values we can still place
         * @param lastParity Parity of the previous element (0 or 1)
         * @return Minimum cost from this state to the end
         */
        private int solve(int idx, int evenRemaining, int oddRemaining, int lastParity) {
            // Base case: reached the end of the array
            if (idx == n) {
                return 0;
            }

            // Return memoized result if available
            if (dp[idx][evenRemaining][oddRemaining][lastParity] != -1) {
                return dp[idx][evenRemaining][oddRemaining][lastParity];
            }

            // If the current position is fixed, we must use its parity
            if (arr[idx] != -1) {
                int cost = (arr[idx] != lastParity) ? 1 : 0;
                return dp[idx][evenRemaining][oddRemaining][lastParity] =
                        cost + solve(idx + 1, evenRemaining, oddRemaining, arr[idx]);
            }

            // If the current position is flexible (-1), try placing even or odd
            int minCost = Integer.MAX_VALUE;

            if (evenRemaining > 0) {
                int cost = (0 != lastParity) ? 1 : 0;
                minCost = Math.min(minCost, cost + solve(idx + 1, evenRemaining - 1, oddRemaining, 0));
            }

            if (oddRemaining > 0) {
                int cost = (1 != lastParity) ? 1 : 0;
                minCost = Math.min(minCost, cost + solve(idx + 1, evenRemaining, oddRemaining - 1, 1));
            }

            return dp[idx][evenRemaining][oddRemaining][lastParity] = minCost;
        }
    }

    /**
     * Optimized Fast I/O helper for competitive programming.
     */
    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) {
                        throw new EOFException("Unexpected end of input");
                    }
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input", e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            String s = next();
            return (s == null) ? 0 : Integer.parseInt(s);
        }
    }
}

import java.io.IOException;
import java.io.InputStream;
import java.io.OutputStream;
import java.io.OutputStreamWriter;
import java.io.UncheckedIOException;
import java.io.Writer;
import java.util.Arrays;

public class Main {
    public static void main(String[] args) {
        FastInput in = new FastInput(System.in);
        // try-with-resources ensures FastOutput is properly flushed and closed
        try (FastOutput out = new FastOutput(System.out)) {
            new GarlandSolver().solve(in, out);
        }
    }

    /**
     * Solves the Garland parity constraint problem using dynamic programming.
     */
    static class GarlandSolver {
        private static final int INF = 100_000_000;

        void solve(FastInput in, FastOutput out) {
            int n = in.readInt();
            int[] parity = new int[n + 1];

            // unknownCounts[0] tracks required even numbers, [1] tracks required odd numbers
            int[] unknownCounts = new int[2];
            unknownCounts[0] = n / 2;
            unknownCounts[1] = n - n / 2;

            for (int i = 1; i <= n; i++) {
                int p = in.readInt();
                parity[i] = p;
                if (p != 0) {
                    unknownCounts[p % 2]--;
                }
            }

            // dp[i][j][k] = min changes for first i positions, j evens placed, current parity k
            int[][][] dp = new int[n + 1][n + 1][2];
            fillDp(dp, INF);
            dp[0][0][0] = dp[0][0][1] = 0;

            for (int i = 1; i <= n; i++) {
                int p = parity[i];
                for (int j = 0; j <= n; j++) {
                    for (int k = 0; k < 2; k++) {
                        if (p == 0) {
                            // Option 1: Place even number (parity 0)
                            if (j > 0 && k == 0) {
                                dp[i][j][k] = Math.min(dp[i][j][k], dp[i - 1][j - 1][k]);
                                dp[i][j][k] = Math.min(dp[i][j][k], dp[i - 1][j - 1][1 - k] + 1);
                            }
                            // Option 2: Place odd number (parity 1)
                            if (k == 1) {
                                dp[i][j][k] = Math.min(dp[i][j][k], dp[i - 1][j][k]);
                                dp[i][j][k] = Math.min(dp[i][j][k], dp[i - 1][j][1 - k] + 1);
                            }
                        } else {
                            // Fixed parity constraint
                            if (p % 2 != k) {
                                continue;
                            }
                            dp[i][j][k] = Math.min(dp[i - 1][j][k], dp[i][j][k]);
                            dp[i][j][k] = Math.min(dp[i - 1][j][1 - k] + 1, dp[i][j][k]);
                        }
                    }
                }
            }

            out.println(Math.min(dp[n][unknownCounts[0]][0], dp[n][unknownCounts[0]][1]));
        }

        /**
         * Iteratively fills a 3D array with a specific value.
         * Replaces the original recursive deepFill to avoid stack overhead.
         */
        private static void fillDp(int[][][] dp, int value) {
            for (int[][] slice : dp) {
                for (int[] row : slice) {
                    Arrays.fill(row, value);
                }
            }
        }
    }

    /**
     * High-performance input reader for competitive programming scenarios.
     */
    static class FastInput {
        private final InputStream is;
        private final byte[] buf = new byte[1 << 13];
        private int bufLen = 0;
        private int bufOffset = 0;
        private int next = -1;

        public FastInput(InputStream is) {
            this.is = is;
        }

        private int read() {
            while (bufLen == bufOffset) {
                bufOffset = 0;
                try {
                    bufLen = is.read(buf);
                } catch (IOException e) {
                    bufLen = -1;
                }
                if (bufLen == -1) {
                    return -1;
                }
            }
            return buf[bufOffset++];
        }

        public void skipBlank() {
            while (next >= 0 && next <= 32) {
                next = read();
            }
        }

        public int readInt() {
            skipBlank();
            int sign = 1;
            if (next == '+' || next == '-') {
                sign = next == '+' ? 1 : -1;
                next = read();
            }

            int val = 0;
            while (next >= '0' && next <= '9') {
                val = val * 10 + (next - '0') * sign;
                next = read();
            }
            return val;
        }
    }

    /**
     * High-performance buffered output writer.
     */
    static class FastOutput implements AutoCloseable {
        private final StringBuilder cache = new StringBuilder(1 << 20);
        private final Writer writer;

        public FastOutput(OutputStream os) {
            this.writer = new OutputStreamWriter(os);
        }

        public FastOutput println(int val) {
            cache.append(val).append('\n');
            return this;
        }

        private void flush() {
            try {
                writer.write(cache);
                writer.flush();
                cache.setLength(0);
            } catch (IOException e) {
                throw new UncheckedIOException(e);
            }
        }

        @Override
        public void close() {
            flush();
            try {
                writer.close();
            } catch (IOException e) {
                throw new UncheckedIOException(e);
            }
        }
    }
}

import java.io.BufferedReader;
import java.io.BufferedOutputStream;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.OutputStream;
import java.io.OutputStreamWriter;
import java.io.UncheckedIOException;
import java.io.Writer;
import java.nio.charset.Charset;
import java.util.Arrays;
import java.util.NoSuchElementException;
import java.util.StringTokenizer;

public class Main {
    public static void main(String[] args) {
        LightScanner in = new LightScanner(System.in);
        LightWriter out = new LightWriter(System.out);
        new AGarland().solve(in, out);
        out.close();
    }

    /**
     * Solves the A Garland problem using dynamic programming.
     * 
     * DP State: dp[p][i][even][odd]
     *   p    : parity of the last placed number (0 = even, 1 = odd)
     *   i    : current position being filled (0 to n)
     *   even : number of even values placed so far
     *   odd  : number of odd values placed so far
     * Value  : minimum operations to reach this state
     */
    static class AGarland {
        public void solve(LightScanner in, LightWriter out) {
            int n = in.ints();
            int[] a = in.ints(n);

            // Track which numbers are already present in the input array
            boolean[] present = new boolean[n + 1];
            for (int val : a) {
                if (val != 0) {
                    present[val] = true;
                }
            }

            // Count how many even and odd positions are missing
            int missingEvens = 0;
            int missingOdds = 0;
            for (int i = 1; i <= n; i++) {
                if (!present[i]) {
                    if (i % 2 == 0) {
                        missingEvens++;
                    } else {
                        missingOdds++;
                    }
                }
            }

            // Initialize DP table with a large value
            int[][][][] dp = new int[2][n + 1][missingEvens + 1][missingOdds + 1];
            for (int p = 0; p < 2; p++) {
                for (int i = 0; i <= n; i++) {
                    for (int e = 0; e <= missingEvens; e++) {
                        Arrays.fill(dp[p][i][e], Integer.MAX_VALUE);
                    }
                }
            }
            dp[0][0][0][0] = 0;
            dp[1][0][0][0] = 0;

            for (int i = 0; i < n; i++) {
                if (a[i] == 0) {
                    // Position is empty. Try placing an even number.
                    for (int odd = 0; odd <= missingOdds; odd++) {
                        for (int even = 0; even < missingEvens; even++) {
                            dp[0][i + 1][even + 1][odd] = Math.min(
                                dp[0][i + 1][even + 1][odd],
                                Math.min(dp[0][i][even][odd], dp[1][i][even][odd] + 1)
                            );
                        }
                    }
                    // Try placing an odd number.
                    for (int odd = 0; odd < missingOdds; odd++) {
                        for (int even = 0; even <= missingEvens; even++) {
                            dp[1][i + 1][even][odd + 1] = Math.min(
                                dp[1][i + 1][even][odd + 1],
                                Math.min(dp[0][i][even][odd] + 1, dp[1][i][even][odd])
                            );
                        }
                    }
                } else {
                    // Position is fixed. Update DP state based on the fixed value's parity.
                    int parity = a[i] % 2; // 0 for even, 1 for odd
                    for (int odd = 0; odd <= missingOdds; odd++) {
                        for (int even = 0; even <= missingEvens; even++) {
                            dp[parity][i + 1][even][odd] = Math.min(
                                dp[parity][i][even][odd],
                                dp[1 - parity][i][even][odd] + 1
                            );
                        }
                    }
                }
            }

            // The answer is the minimum operations to fill all n positions
            // having placed exactly the required number of even and odd values.
            out.ans(Math.min(dp[0][n][missingEvens][missingOdds], dp[1][n][missingEvens][missingOdds])).ln();
        }
    }

    /**
     * Fast input scanner for competitive programming.
     */
    static class LightScanner {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public LightScanner(InputStream in) {
            reader = new BufferedReader(new InputStreamReader(in));
        }

        public String string() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) {
                        throw new NoSuchElementException();
                    }
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int ints() {
            return Integer.parseInt(string());
        }

        public int[] ints(int length) {
            int[] result = new int[length];
            for (int i = 0; i < length; i++) {
                result[i] = ints();
            }
            return result;
        }
    }

    /**
     * Fast output writer for competitive programming.
     */
    static class LightWriter implements AutoCloseable {
        private final Writer out;
        private boolean newlineStart = true;

        public LightWriter(OutputStream out) {
            this.out = new OutputStreamWriter(new BufferedOutputStream(out), Charset.defaultCharset());
        }

        public LightWriter print(char c) {
            try {
                out.write(c);
                newlineStart = false;
            } catch (IOException e) {
                throw new UncheckedIOException(e);
            }
            return this;
        }

        public LightWriter print(String s) {
            try {
                out.write(s, 0, s.length());
                newlineStart = false;
            } catch (IOException e) {
                throw new UncheckedIOException(e);
            }
            return this;
        }

        public LightWriter ans(String s) {
            if (!newlineStart) {
                print(' ');
            }
            return print(s);
        }

        public LightWriter ans(int i) {
            return ans(Integer.toString(i));
        }

        public LightWriter ln() {
            print(System.lineSeparator());
            newlineStart = true;
            return this;
        }

        @Override
        public void close() {
            try {
                out.close();
            } catch (IOException e) {
                throw new UncheckedIOException(e);
            }
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

public class Garland {
    // Use a safe infinity value to prevent integer overflow during DP transitions
    private static final int INFINITY = Integer.MAX_VALUE / 2;

    public static void main(String[] args) throws IOException {
        // Use try-with-resources for automatic resource cleanup
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(System.in))) {
            String line = reader.readLine();
            if (line == null || line.trim().isEmpty()) {
                return;
            }
            int n = Integer.parseInt(line.trim());

            int[] sequence = new int[n + 1];
            boolean[] isPresent = new boolean[n + 1];
            StringTokenizer tokenizer = new StringTokenizer(reader.readLine().trim());

            // Parse input sequence
            for (int i = 1; i <= n; i++) {
                sequence[i] = Integer.parseInt(tokenizer.nextToken());
                if (sequence[i] != 0) {
                    isPresent[sequence[i]] = true;
                }
            }

            // Count missing odd and even numbers
            int missingOdd = 0;
            int missingEven = 0;
            for (int i = 1; i <= n; i++) {
                if (!isPresent[i]) {
                    if (i % 2 == 0) {
                        missingEven++;
                    } else {
                        missingOdd++;
                    }
                }
            }

            // Compute and print the result
            int result = solveGarland(n, sequence, missingOdd, missingEven);
            System.out.println(result);
        }
    }

    /**
     * Solves the Garland problem using dynamic programming.
     * 
     * @param n           Total number of positions
     * @param sequence    Input array where 0 represents a missing number
     * @param missingOdd  Count of available odd numbers to place
     * @param missingEven Count of available even numbers to place
     * @return Minimum cost to fill the sequence according to the problem rules
     */
    private static int solveGarland(int n, int[] sequence, int missingOdd, int missingEven) {
        /**
         * DP State: dp[i][j][k][l]
         * i: Current position being filled (1 to n)
         * j: Number of odd values used from the missing set
         * k: Number of even values used from the missing set
         * l: Parity of the value at position i (0 = even, 1 = odd)
         * Value: Minimum accumulated cost up to position i
         */
        int[][][][] dp = new int[n + 1][missingOdd + 1][missingEven + 1][2];

        // Initialize DP table with infinity
        for (int i = 0; i <= n; i++) {
            for (int j = 0; j <= missingOdd; j++) {
                for (int k = 0; k <= missingEven; k++) {
                    for (int l = 0; l < 2; l++) {
                        dp[i][j][k][l] = INFINITY;
                    }
                }
            }
        }

        // Base case: 0 positions filled, 0 cost regardless of imaginary previous parity
        dp[0][0][0][0] = 0;
        dp[0][0][0][1] = 0;

        // Fill DP table
        for (int i = 1; i <= n; i++) {
            for (int j = 0; j <= missingOdd; j++) {
                for (int k = 0; k <= missingEven; k++) {
                    if (sequence[i] == 0) {
                        // Position is empty: try placing an odd number
                        if (j > 0) {
                            dp[i][j][k][1] = Math.min(dp[i - 1][j - 1][k][0] + 1, dp[i - 1][j - 1][k][1]);
                        }
                        // Position is empty: try placing an even number
                        if (k > 0) {
                            dp[i][j][k][0] = Math.min(dp[i - 1][j][k - 1][0], dp[i - 1][j][k - 1][1] + 1);
                        }
                    } else {
                        // Position is fixed to a specific value
                        if (sequence[i] % 2 == 0) {
                            dp[i][j][k][0] = Math.min(dp[i - 1][j][k][0], dp[i - 1][j][k][1] + 1);
                        } else {
                            dp[i][j][k][1] = Math.min(dp[i - 1][j][k][1], dp[i - 1][j][k][0] + 1);
                        }
                    }
                }
            }
        }

        // The answer is the minimum cost to fill all n positions
        return Math.min(dp[n][missingOdd][missingEven][0], dp[n][missingOdd][missingEven][1]);
    }
}

import java.io.InputStream;
import java.io.OutputStream;
import java.io.IOException;
import java.io.PrintWriter;
import java.util.InputMismatchException;

/**
 * Main entry point for the Garland solver.
 * Reads input, processes it, and outputs the minimum number of changes required.
 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        FastReader in = new FastReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);

        GarlandSolver solver = new GarlandSolver();
        solver.solve(in, out);

        out.close();
    }

    /**
     * Solves the Garland problem using dynamic programming with memoization.
     */
    static class GarlandSolver {
        // DP State Constants
        private static final int STATE_EVEN = 0;
        private static final int STATE_ODD = 1;
        private static final int STATE_FLEXIBLE = 2;

        /**
         * Entry point for solving the problem.
         */
        public void solve(FastReader reader, PrintWriter out) {
            int n = reader.nextInt();
            int[] arr = reader.nextIntArray(n);

            // Determine required counts for odd and even positions based on problem constraints
            int remainingOdd = (n % 2 == 0) ? n / 2 : n / 2 + 1;
            int remainingEven = (n % 2 == 0) ? n / 2 : n / 2;

            // Normalize array: 0 -> -1 (placeholder), even -> 0, odd -> 1
            // Decrement required counts as we encounter fixed values
            for (int i = 0; i < n; i++) {
                if (arr[i] == 0) {
                    arr[i] = -1; // Unknown, needs assignment
                } else if (arr[i] % 2 == 0) {
                    arr[i] = STATE_EVEN;
                    remainingEven--;
                } else {
                    arr[i] = STATE_ODD;
                    remainingOdd--;
                }
            }

            // DP memoization table: memo[remainingOdd][remainingEven][index]
            DPState[][][] memo = new DPState[remainingOdd + 1][remainingEven + 1][n];

            DPState result = computeMinChanges(remainingOdd, remainingEven, 0, arr, memo);
            out.println(result.cost);
        }

        /**
         * Recursive DP function with memoization.
         * Returns the minimum changes needed and the state of the current position.
         */
        private DPState computeMinChanges(int oddLeft, int evenLeft, int pos, int[] arr, DPState[][][] memo) {
            // Base case: last element
            if (pos == arr.length - 1) {
                if (arr[pos] != -1) {
                    return new DPState(0, arr[pos]);
                }
                return evenLeft > 0 ? new DPState(0, STATE_EVEN) : new DPState(0, STATE_ODD);
            }

            // Return memoized result if available
            if (memo[oddLeft][evenLeft][pos] != null) {
                return memo[oddLeft][evenLeft][pos];
            }

            DPState nextState;
            int currentCost;
            int currentState;

            if (oddLeft == 0 && evenLeft == 0) {
                // No more numbers to place, just check compatibility with next position
                nextState = computeMinChanges(oddLeft, evenLeft, pos + 1, arr, memo);
                currentState = arr[pos];
                currentCost = (nextState.value != currentState && nextState.value != STATE_FLEXIBLE)
                        ? nextState.cost + 1 : nextState.cost;
            } else if (arr[pos] != -1) {
                // Current position is fixed by input
                nextState = computeMinChanges(oddLeft, evenLeft, pos + 1, arr, memo);
                currentState = arr[pos];
                currentCost = (nextState.value == currentState || nextState.value == STATE_FLEXIBLE)
                        ? nextState.cost : nextState.cost + 1;
            } else {
                // Current position is unknown (-1), try assigning ODD or EVEN
                if (oddLeft == 0) {
                    nextState = computeMinChanges(oddLeft, evenLeft - 1, pos + 1, arr, memo);
                    currentState = STATE_EVEN;
                    currentCost = (nextState.value == STATE_EVEN || nextState.value == STATE_FLEXIBLE)
                            ? nextState.cost : nextState.cost + 1;
                } else if (evenLeft == 0) {
                    nextState = computeMinChanges(oddLeft - 1, evenLeft, pos + 1, arr, memo);
                    currentState = STATE_ODD;
                    currentCost = (nextState.value == STATE_ODD || nextState.value == STATE_FLEXIBLE)
                            ? nextState.cost : nextState.cost + 1;
                } else {
                    // Try both options and pick the best
                    DPState optionOdd = computeMinChanges(oddLeft - 1, evenLeft, pos + 1, arr, memo);
                    DPState optionEven = computeMinChanges(oddLeft, evenLeft - 1, pos + 1, arr, memo);

                    // Calculate cost if we assign ODD (1) at current position
                    int costOdd = optionOdd.cost + (optionOdd.value == STATE_EVEN ? 1 : 0);
                    // Calculate cost if we assign EVEN (0) at current position
                    int costEven = optionEven.cost + (optionEven.value == STATE_ODD ? 1 : 0);

                    if (costOdd < costEven) {
                        currentState = STATE_ODD;
                        currentCost = costOdd;
                    } else if (costEven < costOdd) {
                        currentState = STATE_EVEN;
                        currentCost = costEven;
                    } else {
                        // Equal costs: prefer flexible state to reduce future constraints
                        currentState = STATE_FLEXIBLE;
                        currentCost = costOdd;
                    }
                }
            }

            DPState result = new DPState(currentCost, currentState);
            memo[oddLeft][evenLeft][pos] = result;
            return result;
        }

        /**
         * Represents the result of a DP state computation.
         */
        private static class DPState {
            final int cost;
            final int value; // STATE_EVEN, STATE_ODD, or STATE_FLEXIBLE

            DPState(int cost, int value) {
                this.cost = cost;
                this.value = value;
            }
        }
    }

    /**
     * Fast I/O utility for competitive programming.
     */
    static class FastReader {
        private final InputStream stream;
        private final byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;
        private SpaceCharFilter filter;

        public FastReader(InputStream stream) {
            this.stream = stream;
        }

        public int read() {
            if (numChars == -1) {
                throw new InputMismatchException();
            }
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0) {
                    return -1;
                }
            }
            return buf[curChar++];
        }

        public int nextInt() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                res *= 10;
                res += c - '0';
                c = read();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public boolean isSpaceChar(int c) {
            return filter != null ? filter.isSpaceChar(c) : isWhitespace(c);
        }

        public static boolean isWhitespace(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        public int[] nextIntArray(int n) {
            int[] array = new int[n];
            for (int i = 0; i < n; i++) {
                array[i] = nextInt();
            }
            return array;
        }

        public interface SpaceCharFilter {
            boolean isSpaceChar(int ch);
        }
    }
}

import java.util.Scanner;

/**
 * Refactored version of the parity balancing problem solver.
 * 
 * Improvements made:
 * 1.  **Class Naming**: Renamed from "Illegal" to "ParityBalancer" for clarity.
 * 2.  **Variable Naming**: Replaced cryptic variables (p, m, k, cnt) with descriptive names.
 * 3.  **Indexing**: Switched from 1-based to 0-based indexing for arrays to align with Java conventions.
 * 4.  **Dynamic Sizing**: The DP array is now sized based on the input 'n' rather than a hardcoded constant.
 * 5.  **Constants**: Removed unused constants (MXN, mod) and defined a safe INF value.
 * 6.  **Resource Management**: Used try-with-resources for the Scanner to prevent resource leaks.
 * 7.  **Safety**: Added bounds checking and safe modulo operations to prevent exceptions.
 */
public class ParityBalancer {

    // A safe infinity value that won't overflow when adding 1
    private static final int INF = Integer.MAX_VALUE / 2;

    public static void main(String[] args) {
        // Use try-with-resources to automatically close the scanner
        try (Scanner scanner = new Scanner(System.in)) {
            if (!scanner.hasNextInt()) {
                return;
            }

            int n = scanner.nextInt();

            // Array to store the input sequence. 
            // Using 0-based indexing to align with Java standards.
            int[] numbers = new int[n];

            // m and k represent constraints/counts derived from n.
            // m is related to even numbers capacity.
            // k is related to odd numbers capacity.
            int m = n / 2;
            int k = (n + 1) / 2;

            // Counter for zeros encountered so far
            int zeroCount = 0;

            // Read input and update constraints
            for (int i = 0; i < n; i++) {
                numbers[i] = scanner.nextInt();

                // If a positive even number is found, decrement m
                if (numbers[i] > 0 && numbers[i] % 2 == 0) {
                    m--;
                }
                // If an odd number is found, decrement k
                if (numbers[i] % 2 != 0) {
                    k--;
                }
            }

            // DP State: dp[index][j][parity]
            // index: Current position in the array (0 to n-1)
            // j: A state variable (bounded by m, but allocated safely)
            // parity: 0 for even, 1 for odd
            // We allocate width as m + 2 to safely handle base case indexing 
            // and potential edge cases where m might be small.
            int dpWidth = Math.max(m + 1, 2);
            int[][][] dp = new int[n][dpWidth][2];

            // Initialize DP table with INF
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < dpWidth; j++) {
                    dp[i][j][0] = INF;
                    dp[i][j][1] = INF;
                }
            }

            // Base Case: Handling the first element (index 0)
            if (numbers[0] == 0) {
                zeroCount = 1;
                // Original logic: dp[1][1][0] = 0; dp[1][0][1] = 0;
                // Mapping to 0-based: dp[0][1][0] = 0; dp[0][0][1] = 0;
                dp[0][1][0] = 0;
                dp[0][0][1] = 0;
            } else {
                // Original logic: dp[1][0][p[1]%2] = 0;
                // Mapping to 0-based: dp[0][0][parity] = 0;
                // Use Math.abs to handle potential negative modulo results safely
                int parity = Math.abs(numbers[0] % 2);
                dp[0][0][parity] = 0;
            }

            // DP Transitions
            for (int i = 1; i < n; i++) {
                if (numbers[i] != 0) {
                    // Case: Current number is non-zero
                    // Iterate j up to m. Ensure we don't exceed array bounds.
                    int limit = Math.min(m, dpWidth - 1);
                    for (int j = 0; j <= limit; j++) {
                        dp[i][j][0] = INF;
                        dp[i][j][1] = INF;

                        int parity = Math.abs(numbers[i] % 2);
                        int prevParity = parity;
                        int otherParity = 1 - parity;

                        // Transition: 
                        // If current parity matches, cost is min of same parity prev or flipped prev + 1
                        int val1 = dp[i - 1][j][prevParity];
                        int val2 = dp[i - 1][j][otherParity] + 1;

                        dp[i][j][parity] = Math.min(val1, val2);
                    }
                } else {
                    // Case: Current number is zero (wildcard)
                    zeroCount++;

                    // Reset base states for j=0
                    dp[i][0][0] = INF;
                    dp[i][0][1] = INF;

                    // Condition: if(zeroCount <= k)
                    if (zeroCount <= k) {
                        int val1 = dp[i - 1][0][1];
                        int val2 = dp[i - 1][0][0] + 1;
                        dp[i][0][1] = Math.min(val1, val2);
                    }

                    // Loop for j from 1 to m
                    int limit = Math.min(m, dpWidth - 1);
                    for (int j = 1; j <= limit; j++) {
                        dp[i][j][0] = INF;
                        dp[i][j][1] = INF;

                        // Logic for dp[i][j][0]
                        // if(j <= zeroCount)
                        if (j <= zeroCount) {
                            int val1 = dp[i - 1][j - 1][0];
                            int val2 = dp[i - 1][j - 1][1] + 1;
                            dp[i][j][0] = Math.min(val1, val2);
                        }

                        // Logic for dp[i][j][1]
                        // if(j <= zeroCount && zeroCount - j <= k)
                        if (j <= zeroCount && (zeroCount - j) <= k) {
                            int val1 = dp[i - 1][j][0] + 1;
                            int val2 = dp[i - 1][j][1];
                            dp[i][j][1] = Math.min(val1, val2);
                        }
                    }
                }
            }

            // Result is min of dp[n-1][m][0] and dp[n-1][m][1]
            // Check bounds before accessing
            int result = INF;
            if (m >= 0 && m < dpWidth) {
                result = Math.min(dp[n - 1][m][0], dp[n - 1][m][1]);
            }

            System.out.println(result);

        } catch (Exception e) {
            // In a production environment, log the exception.
            // For this algorithmic context, we assume valid input.
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.util.Arrays;
import java.util.StringTokenizer;

/**
 * Refactored solution for the alternating parity problem.
 * 
 * Original Logic Analysis:
 * 1. Reads N and an array of integers.
 * 2. Input 0 is treated as a wildcard (can be 0 or 1).
 * 3. Non-zero inputs are fixed to their parity (0 for even, 1 for odd).
 * 4. The goal is to assign values to wildcards such that the array becomes alternating (0,1,0,1... or 1,0,1,0...)
 *    and satisfies specific count constraints for 0s and 1s.
 * 5. Specifically, it targets floor(N/2) zeros and ceil(N/2) ones.
 * 6. Minimizes the number of "flips" (changes in parity between adjacent elements).
 */
public class Main {
    // Use a sufficiently large value for infinity. 
    // The maximum possible answer is N (flipping every element).
    private static final int INF = 1_000_000_000;

    public static void main(String[] args) {
        FastScanner in = new FastScanner(System.in);

        // Read N
        String nStr = in.next();
        if (nStr == null) return;
        int N = Integer.parseInt(nStr);

        // Special case: If N is 1, the array is already alternating (length 1).
        // Cost is 0.
        if (N == 1) {
            System.out.println(0);
            return;
        }

        // Array to store processed values.
        // 1-based indexing for convenience to match DP logic.
        // Values: -1 (Wildcard/Input 0), 0 (Fixed Even), 1 (Fixed Odd).
        int[] values = new int[N + 1];

        // Calculate target counts for wildcards.
        // The problem requires the final array to have:
        // floor(N/2) zeros and ceil(N/2) ones.
        // 'remainingZeros' and 'remainingOnes' track the *remaining capacity* for wildcards
        // to fill these counts, after accounting for fixed values in the input.
        int remainingZeros = N / 2;
        int remainingOnes = N / 2 + N % 2;

        for (int i = 1; i <= N; i++) {
            int val = in.nextInt();
            if (val == 0) {
                values[i] = -1; // Wildcard
            } else {
                values[i] = val % 2; // 0 or 1
                if (values[i] == 0) {
                    remainingZeros--;
                } else {
                    remainingOnes--;
                }
            }
        }

        // Check if all inputs were wildcards (0s).
        // In the original logic, if remainingZeros + remainingOnes == N, 
        // it implies no fixed values were encountered (since each fixed value decrements the sum).
        if (remainingZeros + remainingOnes == N) {
            System.out.println(1);
            return;
        }

        // DP Dimensions
        // j: number of wildcards converted to 0
        // k: number of wildcards converted to 1
        // state: 0 or 1 (parity of the current element)
        // We use rolling arrays to save space: dp[j][k][state]
        // Note: Using Math.max(0, ...) prevents NegativeArraySizeException if constraints are impossible.
        int dimZ = Math.max(0, remainingZeros + 1);
        int dimO = Math.max(0, remainingOnes + 1);

        // dp[j][k][state] stores the min cost
        int[][][] dp = new int[dimZ][dimO][2];
        int[][][] nextDp = new int[dimZ][dimO][2];

        // Initialize DP table with INF
        for (int j = 0; j < dimZ; j++) {
            for (int k = 0; k < dimO; k++) {
                Arrays.fill(dp[j][k], INF);
                Arrays.fill(nextDp[j][k], INF);
            }
        }

        // Base case: 0 elements processed, 0 wildcards used, cost 0.
        // We can consider the "previous" element as having any parity for cost calculation purposes.
        if (dimZ > 0 && dimO > 0) {
            dp[0][0][0] = 0;
            dp[0][0][1] = 0;
        }

        // Iterate through each element of the array
        for (int i = 1; i <= N; i++) {
            // Reset nextDp for the current step
            for (int j = 0; j < dimZ; j++) {
                for (int k = 0; k < dimO; k++) {
                    Arrays.fill(nextDp[j][k], INF);
                }
            }

            int val = values[i];

            // Iterate through all valid states (j, k)
            for (int j = 0; j < dimZ; j++) {
                for (int k = 0; k < dimO; k++) {

                    // If the current element is fixed (0 or 1)
                    if (val != -1) {
                        // We must place 'val'.
                        // We don't consume a wildcard slot, so j and k remain same.
                        // Cost depends on the previous element's parity.

                        int costFromPrev0 = dp[j][k][0]; // Prev was 0
                        int costFromPrev1 = dp[j][k][1]; // Prev was 1

                        if (val == 0) {
                            // Placing 0.
                            // If prev was 0, no flip (cost 0).
                            // If prev was 1, flip needed (cost 1).
                            int currentCost = Math.min(costFromPrev0, costFromPrev1 + 1);
                            nextDp[j][k][0] = currentCost;
                        } else { // val == 1
                            // Placing 1.
                            // If prev was 1, no flip (cost 0).
                            // If prev was 0, flip needed (cost 1).
                            int currentCost = Math.min(costFromPrev1, costFromPrev0 + 1);
                            nextDp[j][k][1] = currentCost;
                        }
                    } 
                    // If the current element is a wildcard (-1)
                    else {
                        // Option 1: Convert wildcard to 0
                        // Requires j > 0 (we must have capacity for a 0)
                        // Comes from state (j-1, k)
                        if (j > 0) {
                            int prevCost0 = dp[j - 1][k][0];
                            int prevCost1 = dp[j - 1][k][1];
                            // Transition to state 0
                            int cost = Math.min(prevCost0, prevCost1 + 1);
                            if (cost < nextDp[j][k][0]) {
                                nextDp[j][k][0] = cost;
                            }
                        }

                        // Option 2: Convert wildcard to 1
                        // Requires k > 0
                        // Comes from state (j, k-1)
                        if (k > 0) {
                            int prevCost0 = dp[j][k - 1][0];
                            int prevCost1 = dp[j][k - 1][1];
                            // Transition to state 1
                            int cost = Math.min(prevCost1, prevCost0 + 1);
                            if (cost < nextDp[j][k][1]) {
                                nextDp[j][k][1] = cost;
                            }
                        }
                    }
                }
            }

            // Swap arrays for next iteration (Rolling Array Optimization)
            int[][][] temp = dp;
            dp = nextDp;
            nextDp = temp;
        }

        // The answer is the minimum cost to reach the state where we have used
        // exactly 'remainingZeros' wildcards as 0s and 'remainingOnes' as 1s.
        int result = INF;
        if (remainingZeros >= 0 && remainingOnes >= 0 && 
            remainingZeros < dimZ && remainingOnes < dimO) {
            result = Math.min(dp[remainingZeros][remainingOnes][0], 
                              dp[remainingZeros][remainingOnes][1]);
        }

        System.out.println(result);
    }

    // Helper class for fast input reading
    static class FastScanner {
        BufferedReader reader;
        StringTokenizer st;

        public FastScanner(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            String s = next();
            if (s == null) return 0;
            return Integer.parseInt(s);
        }
    }
}

import java.util.Scanner;

public class Main {
    // Constant for infinity. 
    // 1,000,000 is chosen to be larger than any possible path cost (N) 
    // but small enough to avoid integer overflow when adding 1.
    private static final int INF = 1_000_000;

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        // Check if input exists to prevent exceptions
        if (!scanner.hasNextInt()) {
            scanner.close();
            return;
        }

        int n = scanner.nextInt();
        int[] numbers = new int[n];
        for (int i = 0; i < n; i++) {
            numbers[i] = scanner.nextInt();
        }

        // Determine the target counts for the two partitions.
        // Based on original logic: evenCount = n/2, oddCount = n - evenCount
        int evenCount = n / 2;
        int oddCount = n - evenCount;

        // DP Table: dp[i][j][k][state]
        // i: Number of elements processed (1 to n)
        // j: Number of elements assigned to the "Even" partition (0 to evenCount)
        // k: Number of elements assigned to the "Odd" partition (0 to oddCount)
        // state: 0 if the last placed element was Even (or compatible), 1 if Odd
        int[][][] dp = new int[n + 1][evenCount + 1][oddCount + 1][2];

        // Initialize DP table with INF
        for (int i = 0; i <= n; i++) {
            for (int j = 0; j <= evenCount; j++) {
                for (int k = 0; k <= oddCount; k++) {
                    dp[i][j][k][0] = INF;
                    dp[i][j][k][1] = INF;
                }
            }
        }

        // Base case: Before processing any elements, cost is 0
        dp[0][0][0][0] = 0;
        dp[0][0][0][1] = 0;

        // Iterate through each number in the input
        // We use 1-based indexing for 'i' to align with the DP state "processed i items"
        for (int i = 1; i <= n; i++) {
            int currentVal = numbers[i - 1]; // Access 0-based array
            boolean isEven = (currentVal % 2 == 0);

            for (int j = 0; j <= evenCount; j++) {
                for (int k = 0; k <= oddCount; k++) {

                    // Logic derived from original code:
                    // If the number is Even (or 0), it contributes to the 'even' count (j).
                    // It transitions to State 0.
                    if (isEven) {
                        if (j > 0) {
                            // Cost to be in State 0 (Even end)
                            // Option 1: Previous was State 0 (Even end). Cost += 0.
                            // Option 2: Previous was State 1 (Odd end). Cost += 1 (Switch).
                            int costFromState0 = dp[i - 1][j - 1][k][0];
                            int costFromState1 = dp[i - 1][j - 1][k][1] + 1;

                            dp[i][j][k][0] = Math.min(costFromState0, costFromState1);
                        }
                    } 
                    // If the number is Odd, it contributes to the 'odd' count (k).
                    // It transitions to State 1.
                    else {
                        if (k > 0) {
                            // Cost to be in State 1 (Odd end)
                            // Option 1: Previous was State 0 (Even end). Cost += 1 (Switch).
                            // Option 2: Previous was State 1 (Odd end). Cost += 0.
                            int costFromState0 = dp[i - 1][j][k - 1][0] + 1;
                            int costFromState1 = dp[i - 1][j][k - 1][1];

                            dp[i][j][k][1] = Math.min(costFromState0, costFromState1);
                        }
                    }
                }
            }
        }

        // The result is the minimum cost to process all n items, 
        // filling exactly evenCount even-slots and oddCount odd-slots.
        int result = Math.min(dp[n][evenCount][oddCount][0], dp[n][evenCount][oddCount][1]);

        System.out.println(result);
        scanner.close();
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

/**
 * Refactored Main class for competitive programming or algorithmic tasks.
 * Improvements:
 * 1. Removed unused fields (sz, id, edges) and imports.
 * 2. Improved variable naming for clarity (e.g., dpTable, values, targetEvenCount).
 * 3. Separated IO handling into dedicated methods.
 * 4. Added comments explaining the DP state transitions.
 * 5. Removed unnecessary interface implementation (Runnable).
 */
public class Main {

    // Constant for infinity, using a specific integer value
    private static final int INFINITY = 1_000_000_000;

    // IO Components
    private BufferedReader br;
    private PrintWriter pw;
    private StringTokenizer st;

    public static void main(String[] args) {
        // Encapsulate execution in a new instance
        new Main().run();
    }

    public void run() {
        try {
            initializeIO();
            solve();
            flushOutput();
        } catch (IOException e) {
            handleError(e);
        }
    }

    private void initializeIO() {
        br = new BufferedReader(new InputStreamReader(System.in));
        pw = new PrintWriter(System.out);
    }

    private void flushOutput() {
        pw.flush();
        pw.close();
        try {
            br.close();
        } catch (IOException e) {
            // Ignore close exception
        }
    }

    private void handleError(Exception e) {
        e.printStackTrace();
        System.exit(1);
    }

    private void solve() throws IOException {
        // Read number of elements
        int n = nextInt();

        // Array to store input values
        int[] values = new int[n];

        // Counter for elements that must be even (based on 1-based index parity)
        int targetEvenCount = 0;

        for (int i = 0; i < n; i++) {
            values[i] = nextInt();
            // Check if the 1-based index (i + 1) is even
            if (((i + 1) % 2) == 0) {
                targetEvenCount++;
            }
        }

        // DP Table Initialization
        // dpTable[i][j][k]
        // i: Number of elements processed (from 0 to n)
        // j: Number of even values placed so far (from 0 to n)
        // k: Parity of the last placed value (0 for Even, 1 for Odd)
        int[][][] dpTable = new int[n + 1][n + 1][2];

        // Fill DP table with infinity
        for (int i = 0; i <= n; i++) {
            for (int j = 0; j <= n; j++) {
                dpTable[i][j][0] = INFINITY;
                dpTable[i][j][1] = INFINITY;
            }
        }

        // Base Case: 0 elements processed, 0 evens placed, cost 0
        dpTable[0][0][0] = 0;
        dpTable[0][0][1] = 0;

        // DP Transitions
        for (int i = 1; i <= n; i++) {
            // Iterate through possible counts of even numbers placed in the previous step
            // Max even numbers placed after i-1 steps is i-1.
            for (int j = 0; j < i; j++) {

                // Iterate through the parity of the last placed number (0 or 1)
                for (int prevParity = 0; prevParity < 2; prevParity++) {

                    int currentCost = dpTable[i - 1][j][prevParity];

                    // If the previous state is unreachable (infinity), skip it
                    if (currentCost >= INFINITY) continue;

                    int currentValue = values[i - 1];

                    if (currentValue != 0) {
                        // Case 1: The value is fixed (not 0)
                        if (currentValue % 2 == 0) {
                            // Value is Even -> Must place as Even (state 0)
                            int nextParity = 0;
                            int costChange = (prevParity != nextParity) ? 1 : 0;
                            int nextJ = j + 1; // Increment even count

                            if (currentCost + costChange < dpTable[i][nextJ][nextParity]) {
                                dpTable[i][nextJ][nextParity] = currentCost + costChange;
                            }
                        } else {
                            // Value is Odd -> Must place as Odd (state 1)
                            int nextParity = 1;
                            int costChange = (prevParity != nextParity) ? 1 : 0;
                            int nextJ = j; // Even count remains same

                            if (currentCost + costChange < dpTable[i][nextJ][nextParity]) {
                                dpTable[i][nextJ][nextParity] = currentCost + costChange;
                            }
                        }
                    } else {
                        // Case 2: The value is 0 (Wildcard) -> Can be Even or Odd
                        for (int nextParity = 0; nextParity < 2; nextParity++) {
                            int costChange = (prevParity != nextParity) ? 1 : 0;
                            // If nextParity is 0 (Even), increment count
                            int nextJ = j + (nextParity == 0 ? 1 : 0);

                            if (currentCost + costChange < dpTable[i][nextJ][nextParity]) {
                                dpTable[i][nextJ][nextParity] = currentCost + costChange;
                            }
                        }
                    }
                }
            }
        }

        // The result is the minimum cost to process all n items, 
        // having placed exactly targetEvenCount even numbers.
        // We take the min of ending in state 0 (Even) or state 1 (Odd).
        int result = Math.min(dpTable[n][targetEvenCount][0], dpTable[n][targetEvenCount][1]);
        pw.println(result);
    }

    // --- Input/Output Helper Methods ---

    private int nextInt() throws IOException {
        return Integer.parseInt(next());
    }

    private long nextLong() throws IOException {
        return Long.parseLong(next());
    }

    private double nextDouble() throws IOException {
        return Double.parseDouble(next());
    }

    private String next() throws IOException {
        while (st == null || !st.hasMoreTokens()) {
            String line = br.readLine();
            if (line == null) {
                return null; // End of input
            }
            st = new StringTokenizer(line);
        }
        return st.nextToken();
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

/**
 * Main class for the palindrome/parity dynamic programming solution.
 * Refactored for better maintainability, readability, and code quality.
 */
public class Main {

    /**
     * FastReader class for efficient input reading.
     * Adapted from common competitive programming templates.
     */
    static class FastReader {
        BufferedReader br;
        StringTokenizer st;

        public FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    e.printStackTrace();
                    return null;
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            String s = next();
            return (s == null) ? 0 : Integer.parseInt(s);
        }

        long nextLong() {
            String s = next();
            return (s == null) ? 0L : Long.parseLong(s);
        }

        double nextDouble() {
            String s = next();
            return (s == null) ? 0.0 : Double.parseDouble(s);
        }

        String nextLine() {
            String str = "";
            try {
                str = br.readLine();
            } catch (IOException e) {
                e.printStackTrace();
            }
            return str;
        }
    }

    public static void main(String[] args) {
        FastReader scanner = new FastReader();

        // Read the size of the array
        String nStr = scanner.next();
        if (nStr == null) return;
        int n = Integer.parseInt(nStr);

        // Read the input array elements
        // Using 1-based indexing to match the original logic
        int[] inputValues = new int[n + 1];
        for (int i = 1; i <= n; i++) {
            inputValues[i] = scanner.nextInt();
        }

        /**
         * Dynamic Programming Table
         * dpTable[i][j][k][state]
         * i: Number of elements processed (1 to n)
         * j: Count of even numbers (or zeros treated as even)
         * k: Count of odd numbers (or zeros treated as odd)
         * state: 0 or 1 (likely representing the parity of the current sum or a specific condition)
         * 
         * Dimensions: [n+1][n+1][n+1][2]
         */
        int[][][][] dpTable = new int[n + 1][n + 1][n + 1][2];

        // Initialize DP table with a large value (n acts as infinity here)
        // This is O(N^3) iterations
        for (int i = 0; i <= n; i++) {
            for (int j = 0; j <= n; j++) {
                for (int k = 0; k <= n; k++) {
                    dpTable[i][j][k][0] = n;
                    dpTable[i][j][k][1] = n;
                }
            }
        }

        // Base case: 0 elements processed, 0 even/odd counts, cost 0
        dpTable[0][0][0][0] = 0;
        dpTable[0][0][0][1] = 0;

        // Fill the DP table
        for (int i = 1; i <= n; i++) {
            // j represents the count of even numbers so far
            // k represents the count of odd numbers so far
            // Since i elements are processed, j + k = i - 1 (before processing current element)
            for (int j = 0; j < i; j++) {
                int k = i - 1 - j; // Derived odd count

                int val = inputValues[i];
                boolean isZero = (val == 0);
                boolean isEven = (val % 2 == 0); // 0 is even, but logic handles 0 separately

                // Logic derived from original code:
                // If val is 0, it can contribute to either even count (state 0) or odd count (state 1).
                // If val is non-zero:
                //   - If even, contributes to even count (state 0).
                //   - If odd, contributes to odd count (state 1).

                // Transition for State 0 (Incrementing Even Count 'j')
                // Valid if val is 0 OR val is even
                if (isZero || isEven) {
                    // dpTable[i][j + 1][k][0]
                    // Cost is min of:
                    // 1. Previous state 0 cost (no switch)
                    // 2. Previous state 1 cost + 1 (switch)
                    int costFromState0 = dpTable[i - 1][j][k][0];
                    int costFromState1 = dpTable[i - 1][j][k][1] + 1;
                    dpTable[i][j + 1][k][0] = Math.min(costFromState0, costFromState1);
                }

                // Transition for State 1 (Incrementing Odd Count 'k')
                // Valid if val is 0 OR val is odd
                if (isZero || !isEven) {
                    // dpTable[i][j][k + 1][1]
                    // Cost is min of:
                    // 1. Previous state 1 cost (no switch)
                    // 2. Previous state 0 cost + 1 (switch)
                    int costFromState1 = dpTable[i - 1][j][k][1];
                    int costFromState0 = dpTable[i - 1][j][k][0] + 1;
                    dpTable[i][j][k + 1][1] = Math.min(costFromState1, costFromState0);
                }
            }
        }

        // Calculate final result
        // We need to split n elements into even and odd counts.
        // Original logic: e = n >> 1 (floor(n/2)), o = n - e
        int targetEvenCount = n / 2;
        int targetOddCount = n - targetEvenCount;

        // The answer is the minimum cost to reach the target counts in either state
        int result = Math.min(
            dpTable[n][targetEvenCount][targetOddCount][0],
            dpTable[n][targetEvenCount][targetOddCount][1]
        );

        System.out.println(result);
    }
}

import java.io.*;
import java.util.*;

/**
 * Main solution class for the parity assignment problem.
 * Uses dynamic programming with memoization to compute the minimum toggle cost
 * while satisfying odd/even count constraints.
 */
public class Main {
    // Safely represents infinity without risking integer overflow during addition
    private static final int INF = Integer.MAX_VALUE / 2;

    public static void main(String[] args) {
        FastScanner sc = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            int n = sc.nextInt();
            int[] arr = new int[n];
            for (int i = 0; i < n; i++) {
                arr[i] = sc.nextInt();
            }

            // Split n into required odd and even counts
            int oddCount = (n + 1) / 2;
            int evenCount = n / 2;

            // memo[idx][remainingOdd][remainingEven][lastParity]
            // lastParity: 0 for even, 1 for odd
            int[][][][] memo = new int[n][oddCount + 1][evenCount + 1][2];
            initializeMemo(memo);

            // Evaluate both possible starting parities and take the minimum
            int result = Math.min(solveDP(n - 1, oddCount, evenCount, 0, memo, arr),
                                  solveDP(n - 1, oddCount, evenCount, 1, memo, arr));
            out.println(result);
        } catch (Exception e) {
            e.printStackTrace();
        } finally {
            out.flush();
            out.close();
        }
    }

    /**
     * Initializes the 4D memoization table with -1 to indicate uncomputed states.
     */
    private static void initializeMemo(int[][][][] memo) {
        for (int[][][] layer : memo) {
            for (int[][] subLayer : layer) {
                for (int[] subSubLayer : subLayer) {
                    Arrays.fill(subSubLayer, -1);
                }
            }
        }
    }

    /**
     * Recursive DP with memoization.
     *
     * @param idx         Current index in the array being processed
     * @param oddLeft     Number of odd parities still required
     * @param evenLeft    Number of even parities still required
     * @param lastParity  Parity chosen at the previous index (0 for even, 1 for odd)
     * @param memo        Memoization table
     * @param arr         Input array
     * @return            Minimum cost to satisfy constraints from idx down to 0
     */
    private static int solveDP(int idx, int oddLeft, int evenLeft, int lastParity, int[][][][] memo, int[] arr) {
        // Invalid state: requested more parities than available
        if (oddLeft < 0 || evenLeft < 0) {
            return INF;
        }
        // Base case: successfully processed all elements
        if (idx < 0) {
            return 0;
        }
        // Return memoized result if available
        if (memo[idx][oddLeft][evenLeft][lastParity] != -1) {
            return memo[idx][oddLeft][evenLeft][lastParity];
        }

        int currentVal = arr[idx];
        int result;

        if (currentVal > 0) {
            // Element is fixed to a specific parity
            int chosenParity = (currentVal % 2 == 0) ? 0 : 1;
            int toggleCost = (chosenParity ^ lastParity);

            if (chosenParity == 0) {
                result = solveDP(idx - 1, oddLeft, evenLeft - 1, chosenParity, memo, arr) + toggleCost;
            } else {
                result = solveDP(idx - 1, oddLeft - 1, evenLeft, chosenParity, memo, arr) + toggleCost;
            }
        } else {
            // Element is a wildcard (0): can choose either parity
            int costChoose0 = (0 ^ lastParity);
            int res0 = solveDP(idx - 1, oddLeft, evenLeft - 1, 0, memo, arr) + costChoose0;

            int costChoose1 = (1 ^ lastParity);
            int res1 = solveDP(idx - 1, oddLeft - 1, evenLeft, 1, memo, arr) + costChoose1;

            result = Math.min(res0, res1);
        }

        // Store and return the computed result
        return memo[idx][oddLeft][evenLeft][lastParity] = result;
    }

    /**
     * Fast I/O helper class using BufferedReader and StringTokenizer.
     * Replaces custom byte-stream parsers for better readability and standard compliance.
     */
    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        public String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        FastScanner in = new FastScanner(inputStream);
        FastPrinter out = new FastPrinter(outputStream);
        Solver solver = new Solver();
        solver.solve(1, in, out);
        out.close();
    }

    /**
     * Solves the problem using dynamic programming with memoization.
     * DP State: dp[index][evenRemaining][oddRemaining][lastParity]
     * - index: current position in the array being processed
     * - evenRemaining: count of unused even numbers available to place
     * - oddRemaining: count of unused odd numbers available to place
     * - lastParity: parity (0 for even, 1 for odd) of the previously placed number
     */
    static class Solver {
        public void solve(int testNumber, FastScanner in, FastPrinter out) {
            int n = in.nextInt();
            int[] a = new int[n];
            for (int i = 0; i < n; i++) {
                a[i] = in.nextInt();
            }

            // Base case: single element requires zero transitions
            if (n == 1) {
                out.println(0);
                return;
            }

            // Identify missing numbers from 1 to n and count evens/odds
            boolean[] present = new boolean[n + 1];
            int missingEven = 0, missingOdd = 0;
            for (int val : a) {
                if (val >= 1 && val <= n) {
                    present[val] = true;
                }
            }
            for (int i = 1; i <= n; i++) {
                if (!present[i]) {
                    if (i % 2 == 0) missingEven++;
                    else missingOdd++;
                }
            }

            // Initialize DP table with MAX_VALUE
            int[][][][] dp = new int[n][missingEven + 1][missingOdd + 1][2];
            for (int[][][] slice : dp) {
                for (int[][] slice2 : slice) {
                    for (int[] slice3 : slice2) {
                        Arrays.fill(slice3, Integer.MAX_VALUE);
                    }
                }
            }

            // Try starting with even or odd parity and take the minimum cost
            int result = Math.min(
                solveDP(0, missingEven, missingOdd, 0, dp, a),
                solveDP(0, missingEven, missingOdd, 1, dp, a)
            );

            out.println(result);
        }

        private int solveDP(int index, int evenRemaining, int oddRemaining, int lastParity,
                            int[][][][] dp, int[] a) {
            if (index >= a.length) {
                return 0;
            }

            if (dp[index][evenRemaining][oddRemaining][lastParity] != Integer.MAX_VALUE) {
                return dp[index][evenRemaining][oddRemaining][lastParity];
            }

            int minCost = Integer.MAX_VALUE;

            if (a[index] == 0) {
                // Option 1: Place an even number
                if (evenRemaining > 0) {
                    int cost = solveDP(index + 1, evenRemaining - 1, oddRemaining, 0, dp, a);
                    if (cost != Integer.MAX_VALUE && lastParity != 0) {
                        cost++;
                    }
                    minCost = Math.min(minCost, cost);
                }
                // Option 2: Place an odd number
                if (oddRemaining > 0) {
                    int cost = solveDP(index + 1, evenRemaining, oddRemaining - 1, 1, dp, a);
                    if (cost != Integer.MAX_VALUE && lastParity != 1) {
                        cost++;
                    }
                    minCost = Math.min(minCost, cost);
                }
            } else {
                // Parity is fixed by the input array
                int parity = a[index] % 2;
                int cost = solveDP(index + 1, evenRemaining, oddRemaining, parity, dp, a);
                if (cost != Integer.MAX_VALUE && lastParity != parity) {
                    cost++;
                }
                minCost = Math.min(minCost, cost);
            }

            return dp[index][evenRemaining][oddRemaining][lastParity] = minCost;
        }
    }

    /**
     * Fast I/O helper for reading input efficiently.
     */
    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        public String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }

    /**
     * Fast I/O helper for writing output efficiently.
     */
    static class FastPrinter {
        private final PrintWriter out;

        public FastPrinter(OutputStream out) {
            this.out = new PrintWriter(new BufferedWriter(new OutputStreamWriter(out)));
        }

        public void print(Object... objects) {
            for (int i = 0; i < objects.length; i++) {
                if (i != 0) out.print(' ');
                out.print(objects[i]);
            }
        }

        public void println(Object... objects) {
            print(objects);
            out.println();
        }

        public void close() {
            out.flush();
            out.close();
        }
    }
}

import java.util.Scanner;

public class AlternatingParitySolver {

    private static final int INFINITY = Integer.MAX_VALUE / 2;
    private static final int STATE_PADDING = 10;

    public static void main(String[] args) {
        // Use try-with-resources to ensure the scanner is properly closed
        try (Scanner scanner = new Scanner(System.in)) {
            solve(scanner);
        }
    }

    /**
     * Entry point for the problem solver.
     * Reads input, initializes DP tables, and computes the minimum parity transitions.
     */
    public static void solve(Scanner scanner) {
        if (!scanner.hasNextInt()) {
            return;
        }
        int n = scanner.nextInt();
        int[] sequence = new int[n];

        boolean[] isPresent = new boolean[n + 1];
        int missingOddCount = 0;
        int missingEvenCount = 0;

        // Read sequence and track which numbers in [1, n] are already present
        for (int i = 0; i < n; i++) {
            sequence[i] = scanner.nextInt();
            if (sequence[i] >= 1 && sequence[i] <= n) {
                isPresent[sequence[i]] = true;
            }
        }

        // Count missing odd and even numbers in the range [1, n]
        for (int i = 1; i <= n; i++) {
            if (!isPresent[i]) {
                if (i % 2 == 0) {
                    missingEvenCount++;
                } else {
                    missingOddCount++;
                }
            }
        }

        // DP dimensions: [currentIndex][remainingOdd][remainingEven]
        int maxMissing = Math.max(missingOddCount, missingEvenCount) + STATE_PADDING;
        int[][][] memoOdd = new int[n + 1][maxMissing][maxMissing];
        int[][][] memoEven = new int[n + 1][maxMissing][maxMissing];

        initializeMemoizationTables(memoOdd, memoEven);

        // Compute minimum transitions starting with either an odd or even placeholder
        int resultStartingWithOdd = computeMinTransitions(true, 0, sequence, missingOddCount, missingEvenCount, memoOdd, memoEven);
        int resultStartingWithEven = computeMinTransitions(false, 0, sequence, missingOddCount, missingEvenCount, memoOdd, memoEven);

        System.out.println(Math.min(resultStartingWithOdd, resultStartingWithEven));
    }

    /**
     * Initializes the memoization tables with -1 to indicate uncomputed states.
     */
    private static void initializeMemoizationTables(int[][][] memoOdd, int[][][] memoEven) {
        for (int i = 0; i < memoOdd.length; i++) {
            for (int j = 0; j < memoOdd[i].length; j++) {
                for (int k = 0; k < memoOdd[i][j].length; k++) {
                    memoOdd[i][j][k] = -1;
                    memoEven[i][j][k] = -1;
                }
            }
        }
    }

    /**
     * Recursively computes the minimum number of parity transitions required to complete the sequence.
     * Uses memoization to avoid recomputing overlapping subproblems.
     *
     * @param previousWasOdd    true if the previously placed number was odd, false otherwise
     * @param currentIndex      current index in the sequence being processed
     * @param sequence          the input array with placeholders (0s)
     * @param oddRemaining      number of unused odd numbers available for placeholders
     * @param evenRemaining     number of unused even numbers available for placeholders
     * @param memoOdd           memoization table when the previous number was odd
     * @param memoEven          memoization table when the previous number was even
     * @return minimum transitions from the current state to the end of the sequence
     */
    private static int computeMinTransitions(boolean previousWasOdd, int currentIndex, int[] sequence,
                                             int oddRemaining, int evenRemaining,
                                             int[][][] memoOdd, int[][][] memoEven) {
        if (currentIndex == sequence.length) {
            return 0;
        }

        // Return cached result if available
        if (previousWasOdd) {
            if (memoOdd[currentIndex][oddRemaining][evenRemaining] != -1) {
                return memoOdd[currentIndex][oddRemaining][evenRemaining];
            }
        } else {
            if (memoEven[currentIndex][oddRemaining][evenRemaining] != -1) {
                return memoEven[currentIndex][oddRemaining][evenRemaining];
            }
        }

        int minCost = INFINITY;

        if (sequence[currentIndex] == 0) {
            // Placeholder: try placing an odd or even number if available
            if (oddRemaining > 0) {
                int transitionCost = previousWasOdd ? 0 : 1;
                minCost = Math.min(minCost, transitionCost +
                        computeMinTransitions(true, currentIndex + 1, sequence, oddRemaining - 1, evenRemaining, memoOdd, memoEven));
            }
            if (evenRemaining > 0) {
                int transitionCost = previousWasOdd ? 1 : 0;
                minCost = Math.min(minCost, transitionCost +
                        computeMinTransitions(false, currentIndex + 1, sequence, oddRemaining, evenRemaining - 1, memoOdd, memoEven));
            }
        } else {
            // Fixed number: check parity against the previous number
            boolean currentIsOdd = sequence[currentIndex] % 2 != 0;
            int transitionCost = (previousWasOdd == currentIsOdd) ? 0 : 1;
            minCost = transitionCost +
                    computeMinTransitions(currentIsOdd, currentIndex + 1, sequence, oddRemaining, evenRemaining, memoOdd, memoEven);
        }

        // Cache the result before returning
        if (previousWasOdd) {
            memoOdd[currentIndex][oddRemaining][evenRemaining] = minCost;
        } else {
            memoEven[currentIndex][oddRemaining][evenRemaining] = minCost;
        }

        return minCost;
    }
}

import java.io.*;
import java.util.*;

public class Codechef {
    // Constants
    private static final int MAX_SIZE = 110;

    // State variables
    private static int[] arr;
    private static int n;
    private static int[][][][] memo;

    public static void main(String[] args) throws IOException {
        FastScanner scanner = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            n = scanner.nextInt();
            arr = new int[n];
            for (int i = 0; i < n; i++) {
                arr[i] = scanner.nextInt();
            }

            // Identify which numbers from 1 to n are already present in the array
            Set<Integer> presentNumbers = new HashSet<>();
            for (int num : arr) {
                if (num != 0) {
                    presentNumbers.add(num);
                }
            }

            // Count available even and odd numbers not present in the array
            int availableEven = 0;
            int availableOdd = 0;
            for (int i = 1; i <= n; i++) {
                if (!presentNumbers.contains(i)) {
                    if (i % 2 == 0) {
                        availableEven++;
                    } else {
                        availableOdd++;
                    }
                }
            }

            // Preprocess array: map non-zero values to their parity (1 for odd, 2 for even)
            for (int i = 0; i < n; i++) {
                if (arr[i] != 0) {
                    arr[i] = (arr[i] % 2 == 0) ? 2 : 1;
                }
            }

            // Initialize memoization table with -1
            memo = new int[MAX_SIZE][MAX_SIZE][MAX_SIZE][2];
            for (int i = 0; i < MAX_SIZE; i++) {
                for (int j = 0; j < MAX_SIZE; j++) {
                    for (int k = 0; k < MAX_SIZE; k++) {
                        Arrays.fill(memo[i][j][k], -1);
                    }
                }
            }

            // Compute and print the result
            int result = solve(0, availableEven, availableOdd, 0);
            out.println(result);

        } finally {
            out.flush();
            out.close();
        }
    }

    /**
     * Recursive DP function with memoization.
     *
     * @param idx             Current index in the array
     * @param remainingEven   Number of even values available to place
     * @param remainingOdd    Number of odd values available to place
     * @param lastParity      Parity of the previously placed number (0 for even, 1 for odd)
     * @return                Minimum cost to fill the remaining positions
     */
    private static int solve(int idx, int remainingEven, int remainingOdd, int lastParity) {
        // Base case: all positions filled
        if (idx == n) {
            return 0;
        }

        // Return memoized result if available
        if (memo[idx][remainingEven][remainingOdd][lastParity] != -1) {
            return memo[idx][remainingEven][remainingOdd][lastParity];
        }

        int currentVal = arr[idx];
        int minCost = Integer.MAX_VALUE;

        if (currentVal == 0) {
            // Option 1: Place an even number (parity 0)
            if (remainingEven > 0) {
                int cost = (lastParity + 0) % 2;
                minCost = Math.min(minCost, solve(idx + 1, remainingEven - 1, remainingOdd, 0) + cost);
            }
            // Option 2: Place an odd number (parity 1)
            if (remainingOdd > 0) {
                int cost = (lastParity + 1) % 2;
                minCost = Math.min(minCost, solve(idx + 1, remainingEven, remainingOdd - 1, 1) + cost);
            }
        } else {
            // Fixed parity: 1 for odd, 2 for even
            int parity = (currentVal == 1) ? 1 : 0;
            int cost = (lastParity + currentVal) % 2;
            minCost = solve(idx + 1, remainingEven, remainingOdd, parity) + cost;
        }

        // Memoize and return
        memo[idx][remainingEven][remainingOdd][lastParity] = minCost;
        return minCost;
    }

    /**
     * Fast I/O helper class for competitive programming.
     */
    static class FastScanner {
        private BufferedReader br;
        private StringTokenizer st;

        public FastScanner(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        long nextLong() {
            return Long.parseLong(next());
        }

        double nextDouble() {
            return Double.parseDouble(next());
        }
    }
}

import java.util.Arrays;
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        // Using try-with-resources ensures the Scanner is properly closed
        try (Scanner sc = new Scanner(System.in)) {
            // Original code hardcodes t=1. Adjust if multiple test cases are expected.
            int t = 1;
            for (int i = 0; i < t; i++) {
                if (!sc.hasNextInt()) break;

                int n = sc.nextInt();
                int[] nums = new int[n];
                int remainingEvens = n / 2;
                int remainingOdds = n - n / 2;

                for (int j = 0; j < n; j++) {
                    nums[j] = sc.nextInt();
                    if (nums[j] != 0) {
                        if (nums[j] % 2 == 0) {
                            remainingEvens--;
                        } else {
                            remainingOdds--;
                        }
                    }
                }

                ParitySolver solver = new ParitySolver(nums);
                int resultStartEven = solver.solve(0, remainingEvens, remainingOdds, 0);
                int resultStartOdd = solver.solve(0, remainingEvens, remainingOdds, 1);

                System.out.println(Math.min(resultStartEven, resultStartOdd));
            }
        }
    }

    /**
     * Encapsulates the dynamic programming logic for parity balancing.
     * Eliminates global state and improves reusability.
     */
    private static class ParitySolver {
        private final int[][][][] memo;
        private final int[] nums;
        private final int n;

        public ParitySolver(int[] nums) {
            this.nums = nums;
            this.n = nums.length;
            // Last dimension size is 2 since parity is always 0 or 1
            this.memo = new int[n + 1][n + 1][n + 1][2];
            initializeMemo();
        }

        private void initializeMemo() {
            // Correctly initialize all valid states up to n
            for (int i = 0; i <= n; i++) {
                for (int j = 0; j <= n; j++) {
                    for (int k = 0; k <= n; k++) {
                        Arrays.fill(memo[i][j][k], -1);
                    }
                }
            }
        }

        /**
         * Recursive DP function with memoization.
         *
         * @param index         Current position in the array
         * @param remainingEvens Count of even numbers we still need to pick
         * @param remainingOdds Count of odd numbers we still need to pick
         * @param lastParity    Parity (0 or 1) of the previously picked element
         * @return Minimum cost to satisfy constraints from this state
         */
        public int solve(int index, int remainingEvens, int remainingOdds, int lastParity) {
            if (index >= n) {
                return 0;
            }
            if (memo[index][remainingEvens][remainingOdds][lastParity] != -1) {
                return memo[index][remainingEvens][remainingOdds][lastParity];
            }

            int currentVal = nums[index];
            int currentParity = currentVal % 2;
            int transitionCost = (lastParity + currentParity) % 2;

            // Base condition: if current element is positive or no more counts are needed, we must take it
            if (currentVal > 0 || (remainingEvens <= 0 && remainingOdds <= 0)) {
                return memo[index][remainingEvens][remainingOdds][lastParity] =
                    transitionCost + solve(index + 1, remainingEvens, remainingOdds, currentParity);
            }

            // If we cannot pick even numbers anymore
            if (remainingEvens <= 0) {
                return memo[index][remainingEvens][remainingOdds][lastParity] =
                    solve(index + 1, remainingEvens, remainingOdds - 1, 1) + (lastParity + 1) % 2;
            }

            // If we cannot pick odd numbers anymore
            if (remainingOdds <= 0) {
                return memo[index][remainingEvens][remainingOdds][lastParity] =
                    solve(index + 1, remainingEvens - 1, remainingOdds, 0) + lastParity % 2;
            }

            // Otherwise, choose the minimum cost path
            int costPickEven = solve(index + 1, remainingEvens - 1, remainingOdds, 0);
            int costPickOdd = solve(index + 1, remainingEvens, remainingOdds - 1, 1);

            // Adjust costs based on parity transition
            if (lastParity == 0) {
                costPickEven += 0;
                costPickOdd += 1;
            } else {
                costPickEven += 1;
                costPickOdd += 0;
            }

            return memo[index][remainingEvens][remainingOdds][lastParity] = Math.min(costPickEven, costPickOdd);
        }
    }
}

