            numbers[i] = scanner.nextInt();
            if (numbers[i] != 0) {
                if (numbers[i] % 2 == 0) {
                    evensRemaining--;
                } else {
                    oddsRemaining--;
                }
            }
        }

        // DP table: dp[index][evensRemaining][prevParity]
        // prevParity: 0 = even, 1 = odd
        int[][][] dp = new int[n + 1][n + 1][2];
        for (int i = 0; i <= n; i++) {
            for (int j = 0; j <= n; j++) {
                Arrays.fill(dp[i][j], -1);
            }
        }

        // Compute results for both possible starting parities
        int resultWithPrevEven = recurse(numbers, 0, evensRemaining, oddsRemaining, 0, dp);
        resetDp(dp);
        int resultWithPrevOdd = recurse(numbers, 0, evensRemaining, oddsRemaining, 1, dp);

        System.out.println(Math.min(resultWithPrevEven, resultWithPrevOdd));
    }

    /**
     * Resets the DP table to -1 to allow reuse in subsequent test cases.
     */
    private static void resetDp(int[][][] dp) {
        for (int[][] row : dp) {
            for (int[] col : row) {
                Arrays.fill(col, -1);
            }
        }
    }

    /**
     * Recursive function with memoization to find the minimum cost.
     *
     * @param numbers          The input array
     * @param index            Current position in the array
     * @param evensRemaining   Number of even numbers allowed to be picked
     * @param oddsRemaining    Number of odd numbers allowed to be picked
     * @param prevParity       Parity of the previously picked number (0 for even, 1 for odd)
     * @param dp               Memoization table
     * @return                 Minimum cost from the current state
     */
    private static int recurse(int[] numbers, int index, int evensRemaining, int oddsRemaining, int prevParity, int[][][] dp) {
        // Base case: reached the end of the array
        if (index >= numbers.length) {
            return 0;
        }

        // Return memoized result if already computed
        if (dp[index][evensRemaining][prevParity] != -1) {
            return dp[index][evensRemaining][prevParity];
        }

        int currentNumber = numbers[index];
        int result;

        // If the current number is positive or both parity counts are exhausted,
        // we must pick it. Cost increases based on parity alternation.
        if (currentNumber > 0 || (evensRemaining <= 0 && oddsRemaining <= 0)) {
            result = (prevParity + currentNumber) % 2 +
                     recurse(numbers, index + 1, evensRemaining, oddsRemaining, currentNumber % 2, dp);
        }
        // No evens remaining: forced to pick an odd number
        else if (evensRemaining <= 0) {
            result = recurse(numbers, index + 1, evensRemaining, oddsRemaining - 1, 1, dp) + (prevParity + 1) % 2;
        }
        // No odds remaining: forced to pick an even number
        else if (oddsRemaining <= 0) {
            result = recurse(numbers, index + 1, evensRemaining - 1, oddsRemaining, 0, dp) + prevParity;
        }
        // Free choice: pick the option that minimizes total cost
        else if (prevParity % 2 == 0) {
            result = Math.min(
                recurse(numbers, index + 1, evensRemaining - 1, oddsRemaining, 0, dp),
                recurse(numbers, index + 1, evensRemaining, oddsRemaining - 1, 1, dp) + 1
            );
        } else {
            result = Math.min(
                recurse(numbers, index + 1, evensRemaining - 1, oddsRemaining, 0, dp) + 1,
                recurse(numbers, index + 1, evensRemaining, oddsRemaining - 1, 1, dp)
            );
        }

        // Store and return the computed result
        dp[index][evensRemaining][prevParity] = result;
        return result;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.Reader;
import java.util.ArrayList;
import java.util.List;
import java.util.PriorityQueue;
import java.util.Queue;
import java.util.StringTokenizer;

/**
 * Refactored version of TaskC.
 * 
 * Improvements:
 * - Separated concerns: I/O handling, parsing, and core algorithm logic.
 * - Replaced cryptic variable names with descriptive identifiers.
 * - Eliminated generic array creation warning by using List<Queue<Integer>>.
 * - Changed return type from String to int for better type safety.
 * - Removed unused methods from the I/O helper to reduce dead code.
 * - Added JavaDoc and inline comments to clarify algorithmic steps.
 * - Used try-with-resources for proper resource management.
 */
public class TaskC {

    public static void main(String[] args) throws IOException {
        try (Reader reader = new InputStreamReader(System.in)) {
            FastReader fastReader = new FastReader(reader);
            int result = solve(fastReader);
            System.out.println(result);
        }
    }

    /**
     * Core algorithm to solve the problem.
     * 
     * @param reader Fast I/O reader
     * @return Calculated result based on segment parity and free slot distribution
     */
    public static int solve(FastReader reader) throws IOException {
        int n = reader.nextInt();
        int[] nums = reader.readIntArray(n);

        if (n == 1) {
            return 0;
        }

        // 1. Identify free slots (indices not targeted by non-zero values)
        boolean[] isTargeted = new boolean[n];
        for (int num : nums) {
            if (num != 0) {
                isTargeted[num - 1] = true;
            }
        }

        int[] freeSlotsByParity = new int[2];
        for (int i = 0; i < n; i++) {
            if (!isTargeted[i]) {
                freeSlotsByParity[(i + 1) % 2]++;
            }
        }

        // 2. Locate the first non-zero element
        int firstNonZeroIdx = findFirstNonZero(nums);
        if (firstNonZeroIdx == n) {
            // All elements are zero
            return 1;
        }

        // 3. Classify zero segments into internal and edge segments
        List<Queue<Integer>> internalSegments = new ArrayList<>(2);
        internalSegments.add(new PriorityQueue<>());
        internalSegments.add(new PriorityQueue<>());

        List<Queue<Integer>> edgeSegments = new ArrayList<>(2);
        edgeSegments.add(new PriorityQueue<>());
        edgeSegments.add(new PriorityQueue<>());

        // Leading segment (length equals index of first non-zero)
        edgeSegments.get(nums[firstNonZeroIdx] % 2).add(firstNonZeroIdx);

        int parityTransitions = 0;
        int currentIdx = firstNonZeroIdx;

        while (currentIdx < n) {
            int nextNonZeroIdx = findNextNonZero(nums, currentIdx + 1);
            if (nextNonZeroIdx == n) {
                break;
            }

            if (nums[currentIdx] % 2 != nums[nextNonZeroIdx] % 2) {
                parityTransitions++;
            } else if (nextNonZeroIdx > currentIdx + 1) {
                internalSegments.get(nums[nextNonZeroIdx] % 2).add(nextNonZeroIdx - currentIdx - 1);
            }
            currentIdx = nextNonZeroIdx;
        }

        // Trailing segment
        if (currentIdx + 1 < n) {
            edgeSegments.get(nums[currentIdx] % 2).add(n - currentIdx - 1);
        }

        // 4. Greedily assign segments to free slots
        for (int parity = 0; parity < 2; parity++) {
            while (!internalSegments.get(parity).isEmpty() &&
                   internalSegments.get(parity).peek() <= freeSlotsByParity[parity]) {
                freeSlotsByParity[parity] -= internalSegments.get(parity).poll();
            }
            while (!edgeSegments.get(parity).isEmpty() &&
                   edgeSegments.get(parity).peek() <= freeSlotsByParity[parity]) {
                freeSlotsByParity[parity] -= edgeSegments.get(parity).poll();
            }
            parityTransitions += internalSegments.get(parity).size() * 2 + edgeSegments.get(parity).size();
        }

        return parityTransitions;
    }

    /**
     * Finds the index of the first non-zero element.
     */
    private static int findFirstNonZero(int[] nums) {
        for (int i = 0; i < nums.length; i++) {
            if (nums[i] != 0) return i;
        }
        return nums.length;
    }

    /**
     * Finds the index of the next non-zero element starting from a given position.
     */
    private static int findNextNonZero(int[] nums, int start) {
        for (int i = start; i < nums.length; i++) {
            if (nums[i] != 0) return i;
        }
        return nums.length;
    }

    /**
     * Fast I/O helper class optimized for competitive programming.
     * Replaces the original MyReader with a cleaner, focused implementation.
     */
    static class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastReader(Reader reader) throws IOException {
            this.br = new BufferedReader(reader);
            readNextLine();
        }

        private void readNextLine() throws IOException {
            String line = br.readLine();
            st = new StringTokenizer(line == null ? "" : line);
        }

        public String nextToken() throws IOException {
            while (!st.hasMoreTokens()) {
                readNextLine();
            }
            return st.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(nextToken());
        }

        public int[] readIntArray(int n) throws IOException {
            int[] arr = new int[n];
            for (int i = 0; i < n; i++) {
                arr[i] = nextInt();
            }
            return arr;
        }
    }
}

import java.io.*;
import java.util.*;

public class AlternatingParityMinChanges {
    private int n;
    private int[] a;
    private static final int INF = 1_000_000_000;
    private int[][][][] memo;

    /**
     * Computes the minimum number of parity changes required from the current index onwards.
     *
     * @param even  Count of available even numbers to place in remaining zero positions
     * @param odd   Count of available odd numbers to place in remaining zero positions
     * @param idx   Current index in the array being processed
     * @param prev  Parity of the previous element (0: even, 1: odd, 2: start/no previous)
     * @return Minimum parity changes from idx to n
     */
    private int dp(int even, int odd, int idx, int prev) {
        if (idx == n) {
            return 0;
        }
        if (memo[prev][even][odd][idx] != -1) {
            return memo[prev][even][odd][idx];
        }

        int ans = INF;
        if (a[idx] != 0) {
            int currentParity = a[idx] % 2;
            int cost = (prev != 2 && currentParity != prev) ? 1 : 0;
            ans = dp(even, odd, idx + 1, currentParity) + cost;
        } else {
            if (even > 0) {
                int cost = (prev == 1) ? 1 : 0;
                ans = Math.min(ans, dp(even - 1, odd, idx + 1, 0) + cost);
            }
            if (odd > 0) {
                int cost = (prev == 0) ? 1 : 0;
                ans = Math.min(ans, dp(even, odd - 1, idx + 1, 1) + cost);
            }
        }
        return memo[prev][even][odd][idx] = ans;
    }

    public static void main(String[] args) {
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
             PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out))) {

            FastScanner sc = new FastScanner(br);

            String nStr = sc.next();
            if (nStr == null) {
                out.flush();
                return;
            }
            int n = Integer.parseInt(nStr);

            int[] a = new int[n];
            boolean[] present = new boolean[n + 1];

            for (int i = 0; i < n; i++) {
                String token = sc.next();
                if (token != null) {
                    a[i] = Integer.parseInt(token);
                    if (a[i] != 0) {
                        present[a[i]] = true;
                    }
                }
            }

            int evenCount = 0;
            int oddCount = 0;
            for (int i = 1; i <= n; i++) {
                if (!present[i]) {
                    if (i % 2 == 0) evenCount++;
                    else oddCount++;
                }
            }

            AlternatingParityMinChanges solver = new AlternatingParityMinChanges();
            solver.n = n;
            solver.a = a;
            solver.memo = new int[3][n + 1][n + 1][n + 1];

            // Initialize memoization table with -1
            for (int i = 0; i < 3; i++) {
                for (int j = 0; j <= n; j++) {
                    for (int k = 0; k <= n; k++) {
                        Arrays.fill(solver.memo[i][j][k], -1);
                    }
                }
            }

            out.println(solver.dp(evenCount, oddCount, 0, 2));
            out.flush();

        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    /**
     * Lightweight fast scanner for efficient and robust input reading.
     */
    private static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner(BufferedReader br) {
            this.br = br;
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input", e);
                }
            }
            return st.nextToken();
        }
    }
}

import java.io.*;
import java.util.StringTokenizer;

/**
 * Solves a parity-based minimum cost problem using memoized dynamic programming.
 * Refactored for maintainability by encapsulating state, removing unused utilities,
 * and applying standard Java naming and resource management conventions.
 */
public class ParityDP {

    // Core problem state
    private int n;
    private int[] values;
    private int[][][][] memo;
    private boolean[][][][] visited;
    private int availableEvenSlots;
    private int availableOddSlots;

    // I/O handling
    private BufferedReader reader;
    private PrintWriter writer;
    private StringTokenizer tokenizer;

    public ParityDP() {
        this.reader = new BufferedReader(new InputStreamReader(System.in));
        this.writer = new PrintWriter(new BufferedOutputStream(System.out));
        this.tokenizer = null;
    }

    /** Reads the next token from standard input. */
    private String nextToken() throws IOException {
        while (tokenizer == null || !tokenizer.hasMoreTokens()) {
            String line = reader.readLine();
            if (line == null) return null;
            tokenizer = new StringTokenizer(line);
        }
        return tokenizer.nextToken();
    }

    /** Parses the next token as an integer. */
    private int nextInt() throws IOException {
        String token = nextToken();
        if (token == null) throw new EOFException("Unexpected end of input");
        return Integer.parseInt(token);
    }

    /** Entry point for the problem logic. */
    public void solve() throws IOException {
        n = nextInt();
        values = new int[n + 1];
        int actualEvenCount = 0;
        int actualOddCount = 0;

        for (int i = 1; i <= n; i++) {
            values[i] = nextInt();
            if (values[i] == 0) continue;
            if (values[i] % 2 == 0) actualEvenCount++;
            else actualOddCount++;
        }

        // Calculate remaining slots for even/odd numbers based on position parity
        availableEvenSlots = n / 2 - actualEvenCount;
        availableOddSlots = (n + 1) / 2 - actualOddCount;

        // Initialize memoization structures
        memo = new int[n + 1][2][n + 1][n + 1];
        visited = new boolean[n + 1][2][n + 1][n + 1];

        int result;
        if (values[n] != 0) {
            result = calculateMinCost(n - 1, values[n] % 2, availableEvenSlots, availableOddSlots);
        } else if (availableEvenSlots == 0) {
            result = calculateMinCost(n - 1, 1, 0, availableOddSlots - 1);
        } else if (availableOddSlots == 0) {
            result = calculateMinCost(n - 1, 0, availableEvenSlots - 1, 0);
        } else {
            result = Math.min(
                calculateMinCost(n - 1, 0, availableEvenSlots - 1, availableOddSlots),
                calculateMinCost(n - 1, 1, availableEvenSlots, availableOddSlots - 1)
            );
        }

        writer.println(result);
    }

    /**
     * Recursive DP with memoization to find the minimum cost.
     *
     * @param index          Current position being evaluated
     * @param currentParity  Parity required at the current position
     * @param remainingEven  Available even numbers to place
     * @param remainingOdd   Available odd numbers to place
     * @return Minimum cost to satisfy parity constraints from index down to 1
     */
    private int calculateMinCost(int index, int currentParity, int remainingEven, int remainingOdd) {
        if (index == 0) return 0;

        if (visited[index][currentParity][remainingEven][remainingOdd]) {
            return memo[index][currentParity][remainingEven][remainingOdd];
        }

        int cost;
        if (values[index] != 0) {
            int mismatch = (currentParity == values[index] % 2) ? 0 : 1;
            cost = mismatch + calculateMinCost(index - 1, values[index] % 2, remainingEven, remainingOdd);
        } else if (remainingEven == 0) {
            int mismatch = (currentParity == 0) ? 1 : 0;
            cost = mismatch + calculateMinCost(index - 1, 1, remainingEven, remainingOdd - 1);
        } else if (remainingOdd == 0) {
            int mismatch = (currentParity == 1) ? 1 : 0;
            cost = mismatch + calculateMinCost(index - 1, 0, remainingEven - 1, remainingOdd);
        } else {
            int costEven = (currentParity == 1) ? 1 : 0;
            int costOdd = (currentParity == 0) ? 1 : 0;
            cost = Math.min(
                costEven + calculateMinCost(index - 1, 0, remainingEven - 1, remainingOdd),
                costOdd + calculateMinCost(index - 1, 1, remainingEven, remainingOdd - 1)
            );
        }

        visited[index][currentParity][remainingEven][remainingOdd] = true;
        memo[index][currentParity][remainingEven][remainingOdd] = cost;
        return cost;
    }

    public static void main(String[] args) {
        ParityDP solver = new ParityDP();
        try {
            solver.solve();
        } catch (IOException e) {
            System.err.println("I/O Error: " + e.getMessage());
        } finally {
            solver.writer.flush();
            solver.writer.close();
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.Arrays;
import java.util.StringTokenizer;

/**
 * Solves a dynamic programming problem where we need to fill an array with
 * numbers from 1 to n, minimizing the cost of adjacent elements having different parities.
 * Some positions are pre-filled, others are zeros to be filled.
 */
public class ParityCostOptimizer {

    private final int n;
    private final int[] arr;
    private int[][][][] memo;

    public ParityCostOptimizer(int n, int[] arr) {
        this.n = n;
        this.arr = arr;
    }

    /**
     * Recursive DP with memoization.
     *
     * @param idx          Current index in the array being processed
     * @param eRemaining   Count of even numbers left to place
     * @param oRemaining   Count of odd numbers left to place
     * @param prevParity   Parity of the previous element (0 for even, 1 for odd)
     * @return Minimum cost from idx to the end of the array
     */
    private int solve(int idx, int eRemaining, int oRemaining, int prevParity) {
        if (idx == n) {
            return 0;
        }
        if (memo[idx][eRemaining][oRemaining][prevParity] != -1) {
            return memo[idx][eRemaining][oRemaining][prevParity];
        }

        // If the current position is pre-filled, we must use that value
        if (arr[idx] != 0) {
            int currentParity = arr[idx] % 2;
            int cost = (prevParity == currentParity) ? 0 : 1;
            return memo[idx][eRemaining][oRemaining][prevParity] =
                    solve(idx + 1, eRemaining, oRemaining, currentParity) + cost;
        }

        // If the position is empty, try placing an even or odd number
        int minCost = Integer.MAX_VALUE;

        if (eRemaining > 0) {
            // Cost increases by prevParity (0 if prev was even, 1 if prev was odd)
            int costEven = solve(idx + 1, eRemaining - 1, oRemaining, 0) + prevParity;
            minCost = Math.min(minCost, costEven);
        }

        if (oRemaining > 0) {
            // Cost increases by (1 - prevParity) (1 if prev was even, 0 if prev was odd)
            int costOdd = solve(idx + 1, eRemaining, oRemaining - 1, 1) + (1 - prevParity);
            minCost = Math.min(minCost, costOdd);
        }

        return memo[idx][eRemaining][oRemaining][prevParity] = minCost;
    }

    /**
     * Computes the minimum parity mismatch cost for the given array configuration.
     */
    public int computeMinimumCost() {
        // Count available even and odd numbers from 1 to n
        int eCount = n / 2;
        int oCount = n - eCount;

        // Subtract numbers already placed in the array
        for (int num : arr) {
            if (num != 0) {
                if (num % 2 == 0) {
                    eCount--;
                } else {
                    oCount--;
                }
            }
        }

        // Single element arrays have no adjacent pairs, so cost is 0
        if (n == 1) {
            return 0;
        }

        // Initialize memoization table with -1
        memo = new int[n][eCount + 1][oCount + 1][2];
        for (int[][][] layer : memo) {
            for (int[][] row : layer) {
                for (int[] col : row) {
                    Arrays.fill(col, -1);
                }
            }
        }

        // Handle the first element separately to establish the initial parity context
        if (arr[0] == 0) {
            int ans = Integer.MAX_VALUE;
            if (oCount > 0) {
                ans = Math.min(ans, solve(1, eCount, oCount - 1, 1));
            }
            if (eCount > 0) {
                ans = Math.min(ans, solve(1, eCount - 1, oCount, 0));
            }
            return ans;
        } else {
            return solve(1, eCount, oCount, arr[0] % 2);
        }
    }

    public static void main(String[] args) throws IOException {
        FastReader reader = new FastReader();
        PrintWriter out = new PrintWriter(System.out);

        String nStr = reader.next();
        if (nStr != null) {
            int n = Integer.parseInt(nStr);
            int[] arr = new int[n];
            for (int i = 0; i < n; i++) {
                arr[i] = reader.nextInt();
            }

            ParityCostOptimizer solver = new ParityCostOptimizer(n, arr);
            out.println(solver.computeMinimumCost());
        }

        out.flush();
        out.close();
    }

    /**
     * Fast I/O helper to handle whitespace-separated tokens efficiently.
     */
    static class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        public String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) {
                        return null;
                    }
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            String s = next();
            return s == null ? 0 : Integer.parseInt(s);
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.Arrays;
import java.util.StringTokenizer;

/**
 * Refactored Parity Game Solver.
 * 
 * Improvements made:
 * 1. Encapsulation: Moved global static variables into instance fields.
 * 2. Naming: Renamed class and variables for better readability (e.g., C -> ParityGameSolver).
 * 3. I/O: Replaced slow Scanner with BufferedReader/StringTokenizer for performance.
 * 4. Constants: Defined INF as a named constant.
 * 5. Structure: Organized code into logical methods and removed unused debug code.
 * 6. Threading: Preserved the thread stack size hack but used modern lambda syntax.
 */
public class ParityGameSolver {

    // Instance variables to encapsulate state
    private int n;
    private int[] arr;
    private int[][][] dp;
    private int missingEvens;
    private int missingOdds;

    // Constant for infinity
    private static final int INF = 100_000_000;

    public static void main(String[] args) {
        // Run in a thread with increased stack size to prevent StackOverflowError
        // on deep recursion, which is common in competitive programming solutions.
        // Stack size 1 << 28 is approximately 256MB.
        new Thread(null, () -> {
            try {
                new ParityGameSolver().run();
            } catch (Exception e) {
                e.printStackTrace();
                System.exit(1);
            }
        }, "Main", 1 << 28).start();
    }

    public void run() throws IOException {
        FastScanner scanner = new FastScanner();
        PrintWriter out = new PrintWriter(System.out);

        try {
            if (!scanner.hasNext()) {
                out.flush();
                return;
            }

            n = scanner.nextInt();
            arr = new int[n];
            int[] frequency = new int[n + 1];

            // Read array elements
            for (int i = 0; i < n; i++) {
                arr[i] = scanner.nextInt();
                // Count frequency of numbers present in the array
                // Assuming valid input range [0, n] based on original logic
                if (arr[i] >= 0 && arr[i] <= n) {
                    frequency[arr[i]]++;
                }
            }

            // Count missing numbers based on parity
            // We look for numbers 1 to n that are not present in the array
            for (int i = 1; i <= n; i++) {
                if (frequency[i] == 0) {
                    if (i % 2 == 0) {
                        missingEvens++;
                    } else {
                        missingOdds++;
                    }
                }
            }

            // Initialize DP table with -1
            // Dimensions: [lastParity][currentIndex][filledOdds]
            // lastParity: 0 for Even, 1 for Odd
            dp = new int[2][n + 1][n + 1];
            for (int[][] layer : dp) {
                for (int[] row : layer) {
                    Arrays.fill(row, -1);
                }
            }

            // Solve starting at index 0, last parity 0 (Even), 0 odds filled, 0 evens filled
            // Note: The initial lastParity doesn't affect cost calculation because pos > 0 check handles it.
            int result = solve(0, 0, 0, 0);

            out.println(result);
        } finally {
            out.flush();
        }
    }

    /**
     * Recursive function with memoization to find the minimum cost.
     *
     * @param lastParity  Parity of the number placed at the previous position (0 for Even, 1 for Odd)
     * @param currentIndex Current index in the array being processed
     * @param filledOdds   Number of odd numbers placed so far
     * @param filledEvens  Number of even numbers placed so far
     * @return Minimum cost to complete the array
     */
    private int solve(int lastParity, int currentIndex, int filledOdds, int filledEvens) {
        // Base case: All positions processed
        if (currentIndex >= n) {
            return 0;
        }

        // Check memoization table
        // Note: filledEvens is implicitly determined by currentIndex, filledOdds, 
        // and the array structure, so it is not needed as a key in the DP table.
        if (dp[lastParity][currentIndex][filledOdds] != -1) {
            return dp[lastParity][currentIndex][filledOdds];
        }

        int minCost = INF;
        int currentValue = arr[currentIndex];

        if (currentValue == 0) {
            // Case: Current position is empty (0), we can place an Odd or Even number

            // Option 1: Place an Odd number
            if (filledOdds < missingOdds) {
                // Cost increases by 1 if parity changes from previous position
                // 0 represents Even, 1 represents Odd. 
                // If last was Even (0) and we pick Odd (1), cost is 1.
                int cost = (currentIndex > 0 && lastParity == 0) ? 1 : 0;
                // Recurse: new lastParity is 1 (Odd)
                minCost = Math.min(minCost, cost + solve(1, currentIndex + 1, filledOdds + 1, filledEvens));
            }

            // Option 2: Place an Even number
            if (filledEvens < missingEvens) {
                // Cost increases by 1 if parity changes from previous position
                // If last was Odd (1) and we pick Even (0), cost is 1.
                int cost = (currentIndex > 0 && lastParity == 1) ? 1 : 0;
                // Recurse: new lastParity is 0 (Even)
                minCost = Math.min(minCost, cost + solve(0, currentIndex + 1, filledOdds, filledEvens + 1));
            }
        } else {
            // Case: Current position has a fixed value
            int currentParity = currentValue & 1; // 0 for Even, 1 for Odd
            int cost = (currentIndex > 0 && lastParity != currentParity) ? 1 : 0;
            minCost = Math.min(minCost, cost + solve(currentParity, currentIndex + 1, filledOdds, filledEvens));
        }

        // Memoize and return
        return dp[lastParity][currentIndex][filledOdds] = minCost;
    }

    /**
     * Helper class for fast input reading.
     */
    static class FastScanner {
        BufferedReader br;
        StringTokenizer st;

        public FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        boolean hasNext() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return false;
                    if (line.trim().isEmpty()) continue;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    return false;
                }
            }
            return true;
        }

        String next() {
            if (hasNext()) return st.nextToken();
            return null;
        }

        int nextInt() {
            String s = next();
            if (s == null) return 0; // Or throw exception
            return Integer.parseInt(s);
        }
    }
}

import java.util.Arrays;
import java.util.Scanner;

public class Garland {
    private final int n;
    private final int[] arr;
    private final int remainingEven;
    private final int remainingOdd;
    private final int[][][] dp;

    /**
     * Constructs the Garland solver with the given array of numbers.
     * Positions with values <= 0 are considered empty and can be filled.
     */
    public Garland(int n, int[] arr) {
        this.n = n;
        this.arr = arr;

        int totalEven = n / 2;
        int totalOdd = n - totalEven;
        int remEven = totalEven;
        int remOdd = totalOdd;

        // Calculate how many even/odd numbers are still available to place
        for (int val : arr) {
            if (val > 0) {
                if (val % 2 == 0) {
                    remEven--;
                } else {
                    remOdd--;
                }
            }
        }

        this.remainingEven = remEven;
        this.remainingOdd = remOdd;
        this.dp = new int[n][remainingEven + 1][2];
        initializeDP();
    }

    /**
     * Initializes the memoization table with -1 to indicate uncomputed states.
     */
    private void initializeDP() {
        for (int[][] row2d : dp) {
            for (int[] row1d : row2d) {
                Arrays.fill(row1d, -1);
            }
        }
    }

    /**
     * Public entry point to solve the garland arrangement problem.
     */
    public int solve() {
        // prev = 0 initially; the cost calculation correctly handles idx == 0
        return solve(0, remainingEven, 0);
    }

    /**
     * Recursive DP with memoization.
     *
     * @param idx     Current position in the array
     * @param remEven Remaining even numbers available to place
     * @param prev    Parity of the previously placed number (0 = even, 1 = odd)
     * @return Minimum cost to complete the arrangement from idx to n
     */
    private int solve(int idx, int remEven, int prev) {
        if (idx == n) {
            return 0;
        }

        if (dp[idx][remEven][prev] != -1) {
            return dp[idx][remEven][prev];
        }

        // Use half of MAX_VALUE to prevent overflow when adding costs
        int result = Integer.MAX_VALUE / 2;

        if (arr[idx] > 0) {
            // Position is pre-filled; must use its parity
            int curParity = arr[idx] % 2;
            int cost = (idx > 0 && curParity != prev) ? 1 : 0;
            result = cost + solve(idx + 1, remEven, curParity);
        } else {
            // Option 1: Place an even number
            if (remEven > 0) {
                int cost = (idx > 0 && 0 != prev) ? 1 : 0;
                result = Math.min(result, cost + solve(idx + 1, remEven - 1, 0));
            }

            // Option 2: Place an odd number
            // Derive remaining odd count from placed counts
            int placedEven = remainingEven - remEven;
            int placedOdd = idx - placedEven;
            int remOdd = remainingOdd - placedOdd;

            if (remOdd > 0) {
                int cost = (idx > 0 && 1 != prev) ? 1 : 0;
                result = Math.min(result, cost + solve(idx + 1, remEven, 1));
            }
        }

        dp[idx][remEven][prev] = result;
        return result;
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        if (scanner.hasNextInt()) {
            int n = scanner.nextInt();
            int[] arr = new int[n];
            for (int i = 0; i < n; i++) {
                arr[i] = scanner.nextInt();
            }

            Garland garland = new Garland(n, arr);
            System.out.println(garland.solve());
        }
        scanner.close();
    }
}

