/**
 * Refactored solver for the parity problem.
 * 
 * Key Improvements:
 * 1. Removed static state: The solver class is now instance-based, preventing state leakage 
 *    between test cases or concurrent executions.
 * 2. Improved Naming: Variables like 'res', 'u', 'a', 'b', 'c' have been replaced with 
 *    descriptive names (e.g., 'inputArray', 'present', 'missingEvens', 'missingOdds', 'lastParity').
 * 3. Code Cleanup: Removed unused utility methods (shuffle) and redundant imports.
 * 4. Magic Numbers: Replaced magic numbers (like 100000) with Integer.MAX_VALUE and explicit logic checks.
 * 5. Structure: Logic is encapsulated in clear methods (solve, computeDP).
 * 6. I/O: Used BufferedOutputStream for slightly better output performance.
 */
public class ParityGameSolver {

    public static void main(String[] args) {
        FastReader scan = new FastReader();
        // Buffered output is generally faster for large outputs
        PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out));

        ParityGameSolver solver = new ParityGameSolver();

        // Original code had a loop for test cases, initialized to 1.
        int t = 1;
        while (t-- > 0) {
            solver.solve(1, scan, out);
        }

        out.flush();
        out.close();
    }

    /**
     * Solves a single test case.
     */
    public void solve(int testNumber, FastReader scan, PrintWriter out) {
        int n = scan.nextInt();
        int[] inputArray = new int[n];
        // Tracks numbers 1..n present in input. Size n+1 for 1-based indexing.
        boolean[] present = new boolean[n + 1]; 

        for (int i = 0; i < n; i++) {
            inputArray[i] = scan.nextInt();
            // Mark present numbers. 0 is a placeholder, not a value 1..n.
            if (inputArray[i] != 0) {
                present[inputArray[i]] = true;
            }
        }

        // Count missing numbers by parity (Even/Odd)
        int missingEvens = 0;
        int missingOdds = 0;
        for (int i = 1; i <= n; i++) {
            if (!present[i]) {
                if (i % 2 == 0) {
                    missingEvens++;
                } else {
                    missingOdds++;
                }
            }
        }

        // DP Table: dp[index][missingEvens][missingOdds][lastParity]
        // lastParity: 0 = Even, 1 = Odd, 2 = None (Start)
        int[][][][] dp = new int[n][missingEvens + 1][missingOdds + 1][3];

        // Initialize DP table with -1
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < dp[0].length; j++) {
                for (int k = 0; k < dp[0][0].length; k++) {
                    Arrays.fill(dp[i][j][k], -1);
                }
            }
        }

        // Start recursion from index 0, with all missing numbers available, 
        // and no previous parity (2 represents None)
        int result = computeDP(0, inputArray, missingEvens, missingOdds, 2, dp);
        out.println(result);
    }

    /**
     * Recursive function with memoization to calculate minimum cost.
     * 
     * @param index Current position in the input array
     * @param a     Number of missing even numbers available to fill
     * @param b     Number of missing odd numbers available to fill
     * @param lastParity Parity of the number at index-1 (0: Even, 1: Odd, 2: None)
     * @param dp    Memoization table
     * @return Minimum cost (number of parity switches)
     */
    private int computeDP(int index, int[] inputArray, int a, int b, int lastParity, int[][][][] dp) {
        // Base case: processed all elements
        if (index >= inputArray.length) {
            return 0;
        }

        // Return memoized result if available
        if (dp[index][a][b][lastParity] != -1) {
            return dp[index][a][b][lastParity];
        }

        int currentVal = inputArray[index];
        int result;

        if (currentVal != 0) {
            // The slot is fixed with a specific number
            int currentParity = currentVal % 2;
            int cost = 0;

            // If not the start, check if parity changes from previous.
            // Cost increases if parities are different (switch).
            if (lastParity != 2 && lastParity != currentParity) {
                cost = 1;
            }

            result = cost + computeDP(index + 1, inputArray, a, b, currentParity, dp);
        } else {
            // The slot is empty (0), try filling with an even or odd number
            int minCost = Integer.MAX_VALUE;

            // Option 1: Fill with an Even number (parity 0)
            if (a > 0) {
                int cost = 0;
                if (lastParity != 2 && lastParity != 0) {
                    cost = 1;
                }
                int res = cost + computeDP(index + 1, inputArray, a - 1, b, 0, dp);
                if (res < minCost) {
                    minCost = res;
                }
            }

            // Option 2: Fill with an Odd number (parity 1)
            if (b > 0) {
                int cost = 0;
                if (lastParity != 2 && lastParity != 1) {
                    cost = 1;
                }
                int res = cost + computeDP(index + 1, inputArray, a, b - 1, 1, dp);
                if (res < minCost) {
                    minCost = res;
                }
            }

            result = minCost;
        }

        // Memoize and return
        return dp[index][a][b][lastParity] = result;
    }

    /**
     * Fast I/O Helper Class
     */
    static class FastReader {
        BufferedReader br;
        StringTokenizer st;

        public FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        public FastReader(String s) throws FileNotFoundException {
            br = new BufferedReader(new FileReader(new File(s)));
        }

        String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    e.printStackTrace();
                    return null;
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            String s = next();
            if (s == null) return 0;
            return Integer.parseInt(s);
        }

        long nextLong() {
            String s = next();
            if (s == null) return 0L;
            return Long.parseLong(s);
        }

        double nextDouble() {
            String s = next();
            if (s == null) return 0.0;
            return Double.parseDouble(s);
        }

        String nextLine() {
            String str = "";
            try {
                str = br.readLine();
            } catch (IOException e) {
                e.printStackTrace();
            }
            return str;
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.ArrayList;
import java.util.Collections;
import java.util.StringTokenizer;

/**
 * Refactored solution for Task 1287C.
 * 
 * Key Improvements:
 * 1. Replaced custom I/O classes with standard Java I/O (BufferedReader/StringTokenizer) 
 *    for better readability and maintainability.
 * 2. Eliminated instance state mutation by passing data as method parameters, making the 
 *    core logic pure and thread-safe.
 * 3. Replaced duplicated boundary condition assignments with a clean nested loop.
 * 4. Removed unnecessary helper classes (MaxMin, Task1287C wrapper) and redundant imports.
 * 5. Improved variable naming, added JavaDoc, and used modern Java practices where appropriate.
 */
public class Main {

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner();
        PrintWriter out = new PrintWriter(System.out);

        int n = scanner.nextInt();
        // Array size is n + 2 to handle 1-based indexing and boundary elements at indices 0 and n+1
        int[] a = new int[n + 2];

        // Calculate initial available odd/even counts based on problem constraints
        int availableOdds = (n + 1) / 2;
        int availableEvens = n - availableOdds;

        for (int i = 1; i <= n; i++) {
            a[i] = scanner.nextInt();
            if (a[i] != 0) {
                if (a[i] % 2 != 0) {
                    availableOdds--;
                } else {
                    availableEvens--;
                }
            }
        }

        int minAns = Integer.MAX_VALUE;
        int[] boundaryOptions = {1, 2};

        // Test all four combinations for the boundary elements
        for (int left : boundaryOptions) {
            for (int right : boundaryOptions) {
                a[0] = left;
                a[n + 1] = right;
                int currentAns = calculateAnswer(a, n, availableOdds, availableEvens);
                if (currentAns < minAns) {
                    minAns = currentAns;
                }
            }
        }

        out.println(minAns);
        out.flush();
    }

    /**
     * Calculates the minimum operations required for a given array configuration.
     *
     * @param a             The input array with boundary values set
     * @param n             The original array length
     * @param availableOdds Remaining odd numbers that can be placed in zero positions
     * @param availableEvens Remaining even numbers that can be placed in zero positions
     * @return Minimum operations needed
     */
    private static int calculateAnswer(int[] a, int n, int availableOdds, int availableEvens) {
        int result = 0;
        int transitions = 0;
        ArrayList<GapInfo> gaps = new ArrayList<>();

        int left = 0;
        for (int right = 1; right <= n + 1; right++) {
            // Find the next non-zero element
            while (right <= n + 1 && a[right] == 0) {
                right++;
            }

            // Check parity transition between boundaries
            if ((a[left] + a[right]) % 2 != 0) {
                transitions++;
            } else {
                // Store gap length and boundary parity
                gaps.add(new GapInfo(right - left - 1, Math.abs(a[left] % 2)));
            }
            left = right;
        }

        // Sort gaps by length, then by parity to process smaller gaps first
        Collections.sort(gaps);

        // Process gaps to determine additional operations needed
        for (GapInfo gap : gaps) {
            if (gap.parity == 1) {
                if (gap.length <= availableOdds) {
                    availableOdds -= gap.length;
                } else {
                    result += 2;
                }
            } else {
                if (gap.length <= availableEvens) {
                    availableEvens -= gap.length;
                } else {
                    result += 2;
                }
            }
        }

        return result + transitions;
    }

    /**
     * Helper class to represent a contiguous gap of zeros between non-zero elements.
     */
    private static class GapInfo implements Comparable<GapInfo> {
        final int length;
        final int parity;

        GapInfo(int length, int parity) {
            this.length = length;
            this.parity = parity;
        }

        @Override
        public int compareTo(GapInfo other) {
            int cmp = Integer.compare(this.length, other.length);
            if (cmp != 0) return cmp;
            return Integer.compare(this.parity, other.parity);
        }
    }

    /**
     * Fast I/O helper using BufferedReader and StringTokenizer.
     * Provides efficient parsing while maintaining standard Java practices.
     */
    private static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input", e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.Arrays;
import java.util.StringTokenizer;

/**
 * Refactored version of the original program.
 * 
 * This program solves a dynamic programming problem involving filling gaps (0s)
 * in a sequence of numbers to minimize parity changes, while respecting
 * constraints on available missing even and odd numbers.
 * 
 * Key Improvements:
 * 1. Encapsulation: Moved static fields to instance fields to avoid global state.
 * 2. Naming: Used descriptive names for variables, methods, and classes.
 * 3. Constants: Replaced magic numbers (like 2 for start state) with named constants.
 * 4. Readability: Added comments and structured the logic for better flow.
 * 5. Safety: Improved input handling and added bounds checks.
 */
public class ParityGapOptimizer {

    // Constants for Parity States
    private static final int PARITY_EVEN = 0;
    private static final int PARITY_ODD = 1;
    private static final int PARITY_NONE = 2; // Represents the state before the first element

    // Instance variables to replace static globals
    private int size;
    private int[] sequence;
    private boolean[] isPresent; // Tracks numbers 1 to n present in input
    private int[][][][] memo;

    public static void main(String[] args) {
        ParityGapOptimizer solver = new ParityGapOptimizer();
        solver.run();
    }

    public void run() {
        FastScanner sc = new FastScanner();
        try {
            // Read size of the sequence
            this.size = sc.nextInt();
            this.sequence = new int[this.size];
            // 1-based indexing for values 1..n, plus index 0 for potential 0 inputs
            this.isPresent = new boolean[this.size + 1];

            // Read sequence and mark present numbers
            for (int i = 0; i < this.size; i++) {
                this.sequence[i] = sc.nextInt();
                // Ensure index is within bounds before marking
                if (this.sequence[i] >= 0 && this.sequence[i] <= this.size) {
                    this.isPresent[this.sequence[i]] = true;
                }
            }

            int missingEvens = 0;
            int missingOdds = 0;

            // Count missing numbers based on parity from 1 to n
            for (int i = 1; i <= this.size; i++) {
                if (!this.isPresent[i]) {
                    if (i % 2 == 0) {
                        missingEvens++;
                    } else {
                        missingOdds++;
                    }
                }
            }

            // Initialize DP table (Memoization)
            // Dimensions: [index][missingEvens][missingOdds][previousParity]
            // previousParity can be 0 (Even), 1 (Odd), or 2 (None)
            this.memo = new int[this.size + 1][missingEvens + 1][missingOdds + 1][3];

            // Fill memoization table with -1 to indicate uncomputed states
            for (int[][][] layer : this.memo) {
                for (int[][] plane : layer) {
                    for (int[] row : plane) {
                        Arrays.fill(row, -1);
                    }
                }
            }

            // Start recursion from index 0, with all missing numbers available, and PARITY_NONE
            int result = solve(0, missingEvens, missingOdds, PARITY_NONE);
            System.out.println(result);

        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    /**
     * Recursive function with memoization to find the minimum cost.
     *
     * @param index Current position in the sequence
     * @param missingEvens Remaining count of missing even numbers available to fill
     * @param missingOdds Remaining count of missing odd numbers available to fill
     * @param previousParity Parity of the element at index - 1 (0=Even, 1=Odd, 2=None)
     * @return Minimum cost to complete the sequence
     */
    private int solve(int index, int missingEvens, int missingOdds, int previousParity) {
        // Check memoization table
        if (this.memo[index][missingEvens][missingOdds][previousParity] != -1) {
            return this.memo[index][missingEvens][missingOdds][previousParity];
        }

        // Base case: End of sequence
        if (index == this.size) {
            return this.memo[index][missingEvens][missingOdds][previousParity] = 0;
        }

        int currentCost = -1;

        // If the current position is pre-filled (not 0)
        if (this.sequence[index] != 0) {
            int currentParity = this.sequence[index] % 2;
            // Cost is 0 if parities match, 1 if they differ
            int transitionCost = (currentParity == previousParity) ? 0 : 1;
            currentCost = transitionCost + solve(index + 1, missingEvens, missingOdds, currentParity);
        }
        // If the current position is empty (0), we must fill it with a missing number
        else {
            int minCost = Integer.MAX_VALUE / 2; // Safe infinity to prevent overflow

            // Option 1: Fill with an Even number
            if (missingEvens > 0) {
                int costIfEven = (PARITY_EVEN == previousParity) ? 0 : 1;
                int cost = costIfEven + solve(index + 1, missingEvens - 1, missingOdds, PARITY_EVEN);
                if (cost < minCost) {
                    minCost = cost;
                }
            }

            // Option 2: Fill with an Odd number
            if (missingOdds > 0) {
                int costIfOdd = (PARITY_ODD == previousParity) ? 0 : 1;
                int cost = costIfOdd + solve(index + 1, missingEvens, missingOdds - 1, PARITY_ODD);
                if (cost < minCost) {
                    minCost = cost;
                }
            }

            currentCost = minCost;
        }

        // Special handling for the first element (where previousParity was PARITY_NONE)
        // The logic implies the first element doesn't count as a "change" against a void predecessor
        if (previousParity == PARITY_NONE) {
            currentCost--;
        }

        return this.memo[index][missingEvens][missingOdds][previousParity] = currentCost;
    }

    // Fast Scanner Class for efficient input reading
    static class FastScanner {
        BufferedReader br;
        StringTokenizer st;

        public FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    e.printStackTrace();
                    return null;
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            String s = next();
            return s == null ? 0 : Integer.parseInt(s);
        }

        long nextLong() {
            String s = next();
            return s == null ? 0L : Long.parseLong(s);
        }
    }
}

import java.util.Scanner;
