        // Read n
        if (!scanner.hasNextInt()) {
            return;
        }
        int n = scanner.nextInt();

        int[] inputArray = new int[n];

        // Initial counts based on n/2 rule
        // z represents remaining zeros allowed to be placed
        // o represents remaining ones allowed to be placed
        int zerosRemaining = n / 2;
        int onesRemaining = n - n / 2;

        // Read input array and adjust counts based on fixed values
        for (int i = 0; i < n; i++) {
            inputArray[i] = scanner.nextInt();

            // If the input value is not 0, it is a fixed constraint.
            // Even numbers consume a 'zero' slot, Odd numbers consume a 'one' slot.
            if (inputArray[i] != 0) {
                if (inputArray[i] % 2 == 0) {
                    zerosRemaining--;
                } else {
                    onesRemaining--;
                }
            }
        }

        // Initialize DP table (Memoization)
        // Dimensions: [index][zeros_left][ones_left][last_parity]
        // Using n + 1 as a safe upper bound for all dimensions.
        int[][][][] memoizationTable = new int[n + 1][n + 1][n + 1][2];

        // Fill with -1 to represent uncomputed states
        for (int[][][] layer : memoizationTable) {
            for (int[][] subLayer : layer) {
                for (int[] subSubLayer : subLayer) {
                    Arrays.fill(subSubLayer, -1);
                }
            }
        }

        // Solve starting with lastParity 0 and 1, take minimum result
        // We try both possibilities for the "virtual" previous element to handle the start of the array
        int resultWithLast0 = solve(inputArray, 0, zerosRemaining, onesRemaining, 0, memoizationTable);
        int resultWithLast1 = solve(inputArray, 0, zerosRemaining, onesRemaining, 1, memoizationTable);

        System.out.println(Math.min(resultWithLast0, resultWithLast1));

        scanner.close();
    }

    /**
     * Recursive solver with memoization.
     * 
     * @param inputArray The array containing fixed constraints and 0s to fill.
     * @param currentIndex The current index in the array being processed.
     * @param zerosRemaining Count of zeros we are still allowed to place.
     * @param onesRemaining Count of ones we are still allowed to place.
     * @param lastParity The parity (0 or 1) of the element at currentIndex - 1.
     * @param memoizationTable The DP table to store results.
     * @return The minimum cost to fill the rest of the array, or Integer.MAX_VALUE if impossible.
     */
    private static int solve(int[] inputArray, int currentIndex, int zerosRemaining, int onesRemaining, int lastParity, int[][][][] memoizationTable) {
        // Base Case: Invalid state (negative counts mean we tried to place more than allowed)
        if (zerosRemaining < 0 || onesRemaining < 0) {
            return Integer.MAX_VALUE;
        }

        // Base Case: Successfully processed all elements
        if (currentIndex == inputArray.length) {
            return 0;
        }

        // Check Memoization
        if (memoizationTable[currentIndex][zerosRemaining][onesRemaining][lastParity] != -1) {
            return memoizationTable[currentIndex][zerosRemaining][onesRemaining][lastParity];
        }

        int result = Integer.MAX_VALUE;

        if (inputArray[currentIndex] != 0) {
            // Case 1: Fixed value in input array
            int currentParity = inputArray[currentIndex] % 2;

            // Recurse to next index with the current value's parity as the new lastParity
            int nextResult = solve(inputArray, currentIndex + 1, zerosRemaining, onesRemaining, currentParity, memoizationTable);

            // Avoid integer overflow if nextResult is MAX_VALUE
            if (nextResult != Integer.MAX_VALUE) {
                // Cost is 1 if parity changes from previous element, 0 otherwise
                int cost = (currentParity == lastParity) ? 0 : 1;
                result = nextResult + cost;
            }
        } else {
            // Case 2: Empty slot (value is 0), we can place 0 or 1

            // Option A: Place 0 (Even parity)
            // Consumes a zero slot
            int resPlace0 = solve(inputArray, currentIndex + 1, zerosRemaining - 1, onesRemaining, 0, memoizationTable);
            if (resPlace0 != Integer.MAX_VALUE) {
                // Cost calculation: if last element was 0, cost is 0. If last was 1, cost is 1.
                int cost0 = (lastParity == 0) ? 0 : 1;
                resPlace0 += cost0;
            }

            // Option B: Place 1 (Odd parity)
            // Consumes a one slot
            int resPlace1 = solve(inputArray, currentIndex + 1, zerosRemaining, onesRemaining - 1, 1, memoizationTable);
            if (resPlace1 != Integer.MAX_VALUE) {
                // Cost calculation: if last element was 0, cost is 1. If last was 1, cost is 0.
                int cost1 = (lastParity == 0) ? 1 : 0;
                resPlace1 += cost1;
            }

            // Take the minimum of placing 0 or 1
            if (resPlace0 != Integer.MAX_VALUE && resPlace1 != Integer.MAX_VALUE) {
                result = Math.min(resPlace0, resPlace1);
            } else if (resPlace0 != Integer.MAX_VALUE) {
                result = resPlace0;
            } else if (resPlace1 != Integer.MAX_VALUE) {
                result = resPlace1;
            }
        }

        // Store result in memoization table
        memoizationTable[currentIndex][zerosRemaining][onesRemaining][lastParity] = result;
        return result;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

/**
 * Solves the Garland problem by finding the minimum parity mismatches
 * when filling in missing numbers (represented as 0) in a sequence.
 * Uses memoized recursion (top-down DP) over index, last parity, and 
 * remaining counts of odd/even numbers.
 */
public class Garland implements AutoCloseable {

    private static final int INF = Integer.MAX_VALUE / 2;

    private final InputReader in;
    private final PrintWriter out;

    private int n;
    private int[] sequence;
    private Integer[][][][] memo;

    public Garland() {
        this.in = new InputReader(System.in);
        this.out = new PrintWriter(System.out);
    }

    public void solve() {
        n = in.nextInt();
        sequence = new int[n];
        boolean[] present = new boolean[n + 1];

        for (int i = 0; i < n; i++) {
            sequence[i] = in.nextInt();
            if (sequence[i] != 0) {
                present[sequence[i]] = true;
            }
        }

        int remainingOdd = 0;
        int remainingEven = 0;
        for (int i = 1; i <= n; i++) {
            if (!present[i]) {
                if (i % 2 == 0) {
                    remainingEven++;
                } else {
                    remainingOdd++;
                }
            }
        }

        // DP state: [index][lastParity][remainingOdd][remainingEven]
        memo = new Integer[n][2][remainingOdd + 1][remainingEven + 1];
        int result = INF;

        if (sequence[0] == 0) {
            if (remainingOdd > 0) {
                result = Math.min(result, solveRecursive(1, 1, remainingOdd - 1, remainingEven));
            }
            if (remainingEven > 0) {
                result = Math.min(result, solveRecursive(1, 0, remainingOdd, remainingEven - 1));
            }
        } else {
            result = solveRecursive(1, sequence[0] % 2, remainingOdd, remainingEven);
        }

        out.println(result);
    }

    /**
     * Recursive function with memoization to compute minimum parity mismatches.
     *
     * @param idx            Current index in the sequence being processed
     * @param lastParity     Parity (0 for even, 1 for odd) of the previous element
     * @param remainingOdd   Count of unused odd numbers available to fill zeros
     * @param remainingEven  Count of unused even numbers available to fill zeros
     * @return Minimum cost (mismatches) from the current index to the end
     */
    private int solveRecursive(int idx, int lastParity, int remainingOdd, int remainingEven) {
        if (idx == n) {
            return 0;
        }

        if (memo[idx][lastParity][remainingOdd][remainingEven] != null) {
            return memo[idx][lastParity][remainingOdd][remainingEven];
        }

        int currentVal = sequence[idx];
        int minCost = INF;

        if (currentVal != 0) {
            // Cost is 1 if parities differ, 0 otherwise
            int cost = (lastParity + (currentVal % 2)) % 2;
            minCost = cost + solveRecursive(idx + 1, currentVal % 2, remainingOdd, remainingEven);
        } else {
            // Try placing an odd number (parity 1)
            if (remainingOdd > 0) {
                int cost = (lastParity + 1) % 2;
                minCost = Math.min(minCost, cost + solveRecursive(idx + 1, 1, remainingOdd - 1, remainingEven));
            }
            // Try placing an even number (parity 0)
            if (remainingEven > 0) {
                int cost = lastParity; // (lastParity + 0) % 2
                minCost = Math.min(minCost, cost + solveRecursive(idx + 1, 0, remainingOdd, remainingEven - 1));
            }
        }

        return memo[idx][lastParity][remainingOdd][remainingEven] = minCost;
    }

    @Override
    public void close() throws IOException {
        in.close();
        out.flush();
        out.close();
    }

    /**
     * Fast input reader optimized for competitive programming style problems.
     */
    private static class InputReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) {
                        return null;
                    }
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            String s = next();
            if (s == null) {
                throw new RuntimeException("Unexpected end of input");
            }
            return Integer.parseInt(s);
        }

        public void close() throws IOException {
            reader.close();
        }
    }

    public static void main(String[] args) {
        try (Garland garland = new Garland()) {
            garland.solve();
        } catch (IOException e) {
            throw new RuntimeException("Failed to close resources", e);
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Solves a grid-based pathfinding problem.
 * 
 * Refactoring Highlights:
 * 1. Fixed critical off-by-one bounds bug in BFS that would cause ArrayIndexOutOfBoundsException.
 * 2. Replaced java.awt.Point with lightweight int[] arrays to avoid UI library dependency and casting overhead.
 * 3. Extracted logic into single-responsibility methods: readGrid(), solve(), bfs().
 * 4. Removed redundant boolean[][] allocation and unused check() method.
 * 5. Improved FastReader with proper null/EOF handling and removed static state pollution.
 * 6. Applied Java naming conventions, constants for magic values, and clear variable names.
 * 7. Used ArrayDeque for O(1) queue operations instead of LinkedList.
 */
public class GridPathSolver {

    // Direction vectors for 4-directional movement (Down, Up, Right, Left)
    private static final int[][] DIRECTIONS = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};
    private static final char EMPTY = '.';
    private static final char GOAL = 'G';
    private static final char BLOCKER = 'B';

    public static void main(String[] args) {
        FastReader reader = new FastReader();
        // BufferedOutputStream improves PrintWriter performance for large outputs
        PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out));

        try {
            String tcStr = reader.next();
            if (tcStr == null) return;
            int testCases = Integer.parseInt(tcStr);

            while (testCases-- > 0) {
                int rows = reader.nextInt();
                int cols = reader.nextInt();
                int[][] grid = readGrid(reader, rows, cols);

                boolean result = solve(grid, rows, cols);
                out.println(result ? "Yes" : "No");
            }
        } catch (Exception e) {
            // In competitive programming, malformed input is rare. 
            // This catch prevents runtime crashes on unexpected EOF.
        } finally {
            out.flush();
        }
    }

    /**
     * Parses the input grid into an integer matrix:
     * 0 = Empty, 1 = Blocker, 2 = Goal, -1 = Obstacle
     */
    private static int[][] readGrid(FastReader reader, int rows, int cols) {
        int[][] grid = new int[rows][cols];
        for (int i = 0; i < rows; i++) {
            String line = reader.next();
            for (int j = 0; j < cols; j++) {
                char ch = line.charAt(j);
                if (ch == EMPTY) {
                    grid[i][j] = 0;
                } else if (ch == GOAL) {
                    grid[i][j] = 2;
                } else if (ch == BLOCKER) {
                    grid[i][j] = 1;
                } else {
                    grid[i][j] = -1; // Unknown/Obstacle character
                }
            }
        }
        return grid;
    }

    /**
     * Core logic to determine if all goals are reachable from the destination
     * without touching blockers or their adjacent cells.
     */
    private static boolean solve(int[][] grid, int rows, int cols) {
        // Count total goals
        int goalCount = 0;
        for (int[] row : grid) {
            for (int val : row) {
                if (val == 2) goalCount++;
            }
        }

        // Trivial case: No goals exist, and destination is not a blocker
        if (goalCount == 0 && grid[rows - 1][cols - 1] != 1) {
            return true;
        }

        // Mark cells adjacent to blockers as blocked (-1)
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == 1) {
                    for (int[] dir : DIRECTIONS) {
                        int ni = i + dir[0];
                        int nj = j + dir[1];
                        if (ni >= 0 && ni < rows && nj >= 0 && nj < cols && grid[ni][nj] == 0) {
                            grid[ni][nj] = -1;
                        }
                    }
                }
            }
        }

        // If destination is blocked, path is impossible
        if (grid[rows - 1][cols - 1] == -1 || grid[rows - 1][cols - 1] == 1) {
            return false;
        }

        // Find all cells reachable from the destination
        boolean[][] reachable = bfs(grid, rows, cols, rows - 1, cols - 1);

        // Verify all goals are within the reachable area
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == 2 && !reachable[i][j]) {
                    return false;
                }
            }
        }

        // Verify no blocker is adjacent to any reachable cell
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == 1) {
                    for (int[] dir : DIRECTIONS) {
                        int ni = i + dir[0];
                        int nj = j + dir[1];
                        if (ni >= 0 && ni < rows && nj >= 0 && nj < cols && reachable[ni][nj]) {
                            return false;
                        }
                    }
                }
            }
        }

        return true;
    }

    /**
     * Performs BFS from the start coordinate to find all reachable cells.
     * Returns a 2D boolean array indicating reachability.
     */
    private static boolean[][] bfs(int[][] grid, int rows, int cols, int startRow, int startCol) {
        boolean[][] reachable = new boolean[rows][cols];
        Queue<int[]> queue = new ArrayDeque<>();

        queue.add(new int[]{startRow, startCol});
        reachable[startRow][startCol] = true;

        while (!queue.isEmpty()) {
            int[] curr = queue.poll();
            int r = curr[0];
            int c = curr[1];

            for (int[] dir : DIRECTIONS) {
                int nr = r + dir[0];
                int nc = c + dir[1];

                // Correct bounds checking: < rows and < cols (0-indexed)
                if (nr >= 0 && nr < rows && nc >= 0 && nc < cols
                        && grid[nr][nc] != -1 && !reachable[nr][nc]) {
                    reachable[nr][nc] = true;
                    queue.add(new int[]{nr, nc});
                }
            }
        }
        return reachable;
    }

    /**
     * High-performance input reader for competitive programming.
     */
    static class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input", e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            String token = next();
            return token == null ? 0 : Integer.parseInt(token);
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

public class Main {
    // Direction vectors for up, left, down, right
    private static final int[] DR = {-1, 0, 1, 0};
    private static final int[] DC = {0, -1, 0, 1};

    public static void main(String[] args) {
        FastScanner sc = new FastScanner();
        PrintWriter out = new PrintWriter(System.out);

        int testCases = sc.nextInt();
        while (testCases-- > 0) {
            int rows = sc.nextInt();
            int cols = sc.nextInt();
            char[][] grid = readGrid(sc, rows, cols);

            if (solve(grid, rows, cols)) {
                out.println("Yes");
            } else {
                out.println("No");
            }
        }
        out.flush();
    }

    private static char[][] readGrid(FastScanner sc, int rows, int cols) {
        char[][] grid = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            String line = sc.next();
            for (int j = 0; j < cols; j++) {
                grid[i][j] = line.charAt(j);
            }
        }
        return grid;
    }

    private static boolean solve(char[][] grid, int rows, int cols) {
        // Check if goal cell exists
        boolean hasGoal = false;
        for (char[] row : grid) {
            for (char cell : row) {
                if (cell == 'G') {
                    hasGoal = true;
                    break;
                }
            }
            if (hasGoal) break;
        }

        // Process 'B' cells: block adjacent '.' and fail if adjacent to 'G'
        boolean isBlocked = false;
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == 'B') {
                    if (!checkAndBlockNeighbors(grid, r, c, rows, cols)) {
                        isBlocked = true;
                        break;
                    }
                }
            }
            if (isBlocked) break;
        }

        // Additional blocking condition from original logic
        if (grid[rows - 1][cols - 1] == '#' && hasGoal) {
            isBlocked = true;
        }

        if (isBlocked) {
            return false;
        }

        // Find all reachable cells from bottom-right
        boolean[][] visited = new boolean[rows][cols];
        dfs(visited, rows - 1, cols - 1, grid, rows, cols);

        // Verify all 'G' cells are reachable
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == 'G' && !visited[r][c]) {
                    return false;
                }
            }
        }

        return true;
    }

    private static boolean checkAndBlockNeighbors(char[][] grid, int r, int c, int rows, int cols) {
        for (int i = 0; i < 4; i++) {
            int nr = r + DR[i];
            int nc = c + DC[i];
            if (isValid(nr, nc, rows, cols)) {
                if (grid[nr][nc] == 'G') {
                    return false;
                }
                if (grid[nr][nc] == '.') {
                    grid[nr][nc] = '#';
                }
            }
        }
        return true;
    }

    private static boolean isValid(int r, int c, int rows, int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    private static void dfs(boolean[][] visited, int r, int c, char[][] grid, int rows, int cols) {
        if (!isValid(r, c, rows, cols) || grid[r][c] == '#' || visited[r][c]) {
            return;
        }
        visited[r][c] = true;
        for (int i = 0; i < 4; i++) {
            dfs(visited, r + DR[i], c + DC[i], grid, rows, cols);
        }
    }

    /**
     * Efficient input reader for competitive programming.
     * Handles whitespace tokenization and EOF gracefully.
     */
    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.*;
import java.util.*;

public class GridPathSolver {
    // Constants representing grid cell types for better readability
    private static final int EMPTY = 0;
    private static final int WALL = 1;
    private static final int GOAL = 2;
    private static final int START = 3;

    private int rows, cols;
    private int[][] grid;
    private boolean[][] visited;

    public static void main(String[] args) {
        InputReader in = new InputReader(System.in);
        // BufferedOutputStream improves PrintWriter performance
        PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out));

        int testCases = in.nextInt();
        for (int t = 0; t < testCases; t++) {
            // Instantiate solver per test case to avoid static state pollution
            GridPathSolver solver = new GridPathSolver();
            solver.readInput(in);
            out.println(solver.solve() ? "Yes" : "No");
        }
        out.flush();
    }

    /**
     * Reads grid dimensions and cell contents from input.
     */
    private void readInput(InputReader in) {
        rows = in.nextInt();
        cols = in.nextInt();
        grid = new int[rows][cols];

        for (int i = 0; i < rows; i++) {
            String line = in.next();
            for (int j = 0; j < cols; j++) {
                char c = line.charAt(j);
                if (c == '.') grid[i][j] = EMPTY;
                else if (c == '#') grid[i][j] = WALL;
                else if (c == 'G') grid[i][j] = GOAL;
                else grid[i][j] = START; // Handles 'S' or any other character
            }
        }
    }

    /**
     * Core logic to determine if all goals are reachable from the start.
     */
    private boolean solve() {
        // Original constraint: if bottom-right is the start, it's invalid
        if (grid[rows - 1][cols - 1] == START) {
            return false;
        }

        boolean possible = true;
        int[] dRow = {-1, 1, 0, 0};
        int[] dCol = {0, 0, -1, 1};

        // Process start positions: block adjacent empty cells and check adjacency to goal
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == START) {
                    for (int k = 0; k < 4; k++) {
                        int ni = i + dRow[k];
                        int nj = j + dCol[k];
                        if (isValid(ni, nj)) {
                            if (grid[ni][nj] == GOAL) {
                                possible = false;
                            } else if (grid[ni][nj] == EMPTY) {
                                grid[ni][nj] = WALL; // Block empty neighbors
                            }
                        }
                    }
                }
            }
        }

        if (!possible) {
            return false;
        }

        // Initialize visited array and perform DFS from bottom-right
        visited = new boolean[rows][cols];
        dfs(rows - 1, cols - 1);

        // Verify that all goal cells are reachable
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == GOAL && !visited[i][j]) {
                    return false;
                }
            }
        }

        return true;
    }

    /**
     * Checks if coordinates are within bounds and not a wall.
     */
    private boolean isValid(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols && grid[r][c] != WALL;
    }

    /**
     * Iterative DFS to mark all reachable cells from the starting point.
     * Using an explicit stack prevents StackOverflowError on large grids.
     */
    private void dfs(int startR, int startC) {
        Deque<int[]> stack = new ArrayDeque<>();
        stack.push(new int[]{startR, startC});
        visited[startR][startC] = true;

        int[] dRow = {-1, 1, 0, 0};
        int[] dCol = {0, 0, -1, 1};

        while (!stack.isEmpty()) {
            int[] curr = stack.pop();
            int r = curr[0];
            int c = curr[1];

            for (int k = 0; k < 4; k++) {
                int nr = r + dRow[k];
                int nc = c + dCol[k];
                if (isValid(nr, nc) && !visited[nr][nc]) {
                    visited[nr][nc] = true;
                    stack.push(new int[]{nr, nc});
                }
            }
        }
    }

    /**
     * Fast I/O helper class for competitive programming.
     */
    static class InputReader {
        public BufferedReader reader;
        public StringTokenizer tokenizer;

        public InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
