import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.ArrayDeque;
import java.util.StringTokenizer;

public final class CF_648_D2_D {

    private static final int[][] DIRECTIONS = {{-1, 0}, {0, 1}, {1, 0}, {0, -1}};
    private static final char BOMB = 'B';
    private static final char GOAL = 'G';
    private static final char WALL = '#';

    public static void main(String[] args) throws IOException {
        FastScanner scanner = new FastScanner();
        PrintWriter out = new PrintWriter(System.out);

        int testCases = scanner.nextInt();
        while (testCases-- > 0) {
            int n = scanner.nextInt();
            int m = scanner.nextInt();
            char[][] grid = new char[n][];
            for (int i = 0; i < n; i++) {
                grid[i] = scanner.next().toCharArray();
            }

            boolean result = solve(n, m, grid);
            out.println(result ? "Yes" : "No");
        }
        out.flush();
    }

    private static boolean solve(int n, int m, char[][] grid) {
        int reachableGoals = 0;
        boolean isAdjacentBombGoal = false;

        // First pass: count goals, detect invalid adjacency, and place walls
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                char cell = grid[i][j];
                if (cell == GOAL) {
                    reachableGoals++;
                } else if (cell == BOMB) {
                    for (int[] dir : DIRECTIONS) {
                        int ni = i + dir[0];
                        int nj = j + dir[1];
                        if (isValid(ni, nj, n, m)) {
                            char neighbor = grid[ni][nj];
                            if (neighbor == GOAL) {
                                isAdjacentBombGoal = true;
                            } else if (neighbor == '.') {
                                grid[ni][nj] = WALL;
                            }
                        }
                    }
                }
            }
        }

        if (isAdjacentBombGoal) {
            return false;
        }

        // Second pass: DFS from bottom-right to count reachable goals
        if (grid[n - 1][m - 1] == '.') {
            boolean[][] visited = new boolean[n][m];
            ArrayDeque<Integer> stack = new ArrayDeque<>();
            // Encode 2D coordinates into a single integer for efficiency
            stack.push((n - 1) * m + (m - 1));
            visited[n - 1][m - 1] = true;

            while (!stack.isEmpty()) {
                int curr = stack.pop();
                int r = curr / m;
                int c = curr % m;

                if (grid[r][c] == GOAL) {
                    reachableGoals--;
                }

                for (int[] dir : DIRECTIONS) {
                    int nr = r + dir[0];
                    int nc = c + dir[1];
                    if (isValid(nr, nc, n, m) && !visited[nr][nc] && grid[nr][nc] != WALL) {
                        visited[nr][nc] = true;
                        stack.push(nr * m + nc);
                    }
                }
            }
        }

        return reachableGoals == 0;
    }

    private static boolean isValid(int r, int c, int n, int m) {
        return r >= 0 && r < n && c >= 0 && c < m;
    }

    /**
     * Lightweight fast I/O utility to replace custom byte-buffer readers.
     * Uses BufferedReader and StringTokenizer for clean, standard, and sufficiently fast parsing.
     */
    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input", e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Solves a grid reachability problem where:
 * - 'B' blocks all adjacent non-'B' cells.
 * - 'G' represents goals that must be reachable from the bottom-right corner.
 * - '#' represents blocked/wall cells.
 * 
 * Refactored for maintainability, readability, and performance.
 */
public class GridReachabilitySolver {

    // Direction vectors: Up, Down, Left, Right
    private static final int[] DR = {-1, 1, 0, 0};
    private static final int[] DC = {0, 0, -1, 1};

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out));

        try {
            int t = scanner.nextInt();
            while (t-- > 0) {
                int n = scanner.nextInt();
                int m = scanner.nextInt();
                char[][] grid = new char[n][m];

                for (int i = 0; i < n; i++) {
                    grid[i] = scanner.next().toCharArray();
                }

                boolean canReachAllGoals = solve(grid, n, m);
                out.println(canReachAllGoals ? "Yes" : "No");
            }
        } catch (Exception e) {
            // In competitive programming, input is guaranteed to be well-formed.
            // This catch block is for safety during local testing.
            out.println("Error: " + e.getMessage());
        } finally {
            out.flush();
        }
    }

    /**
     * Processes a single test case: applies barriers, validates constraints,
     * and checks reachability using BFS.
     */
    private static boolean solve(char[][] grid, int n, int m) {
        // Count total goals before modifying the grid
        int totalGoals = 0;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == 'G') {
                    totalGoals++;
                }
            }
        }

        // Apply barriers around 'B' cells. Returns true if immediate failure occurs.
        if (applyBarriers(grid, n, m)) {
            return false;
        }

        // If there are no goals, the condition is trivially satisfied
        if (totalGoals == 0) {
            return true;
        }

        // Start position must not be blocked
        if (grid[n - 1][m - 1] == '#') {
            return false;
        }

        // Count reachable goals via BFS from bottom-right corner
        int reachableGoals = countReachableGoals(grid, n - 1, m - 1, n, m);

        return reachableGoals == totalGoals;
    }

    /**
     * Modifies the grid in-place to block cells adjacent to 'B'.
     * Returns true if any 'G' is directly adjacent to a 'B', which is an immediate failure.
     */
    private static boolean applyBarriers(char[][] grid, int n, int m) {
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == 'B') {
                    for (int d = 0; d < 4; d++) {
                        int ni = i + DR[d];
                        int nj = j + DC[d];

                        if (ni >= 0 && ni < n && nj >= 0 && nj < m) {
                            if (grid[ni][nj] == 'G') {
                                return true; // 'G' is adjacent to 'B' -> unreachable
                            }
                            if (grid[ni][nj] != 'B') {
                                grid[ni][nj] = '#'; // Block non-'B' cells adjacent to 'B'
                            }
                        }
                    }
                }
            }
        }
        return false;
    }

    /**
     * Performs BFS from the starting position and counts how many 'G' cells are reachable.
     */
    private static int countReachableGoals(char[][] grid, int startR, int startC, int n, int m) {
        boolean[][] visited = new boolean[n][m];
        Queue<Point> queue = new ArrayDeque<>();

        queue.add(new Point(startR, startC));
        visited[startR][startC] = true;

        int count = (grid[startR][startC] == 'G') ? 1 : 0;

        while (!queue.isEmpty()) {
            Point curr = queue.poll();

            for (int d = 0; d < 4; d++) {
                int nr = curr.r + DR[d];
                int nc = curr.c + DC[d];

                if (nr >= 0 && nr < n && nc >= 0 && nc < m &&
                    !visited[nr][nc] && grid[nr][nc] != '#') {

                    visited[nr][nc] = true;
                    if (grid[nr][nc] == 'G') {
                        count++;
                    }
                    queue.add(new Point(nr, nc));
                }
            }
        }
        return count;
    }

    /**
     * Simple immutable value class for 2D grid coordinates.
     */
    private static class Point {
        final int r;
        final int c;

        Point(int r, int c) {
            this.r = r;
            this.c = c;
        }
    }

    /**
     * Fast I/O helper class optimized for competitive programming environments.
     */
    private static class FastScanner {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastScanner(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
            tokenizer = new StringTokenizer("");
        }

        public String next() throws IOException {
            while (!tokenizer.hasMoreTokens()) {
                String line = reader.readLine();
                if (line == null) {
                    throw new EOFException();
                }
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        public long nextLong() throws IOException {
            return Long.parseLong(next());
        }

        public double nextDouble() throws IOException {
            return Double.parseDouble(next());
        }
    }
}

import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.InputMismatchException;
import java.util.LinkedList;
import java.util.Queue;

public class Main {
    public static void main(String[] args) {
        try (PrintWriter out = new PrintWriter(System.out)) {
            FastReader in = new FastReader(System.in);
            DSolveTheMaze solver = new DSolveTheMaze();
            solver.solve(in, out);
        } catch (IOException e) {
            throw new RuntimeException("Failed to process input/output", e);
        }
    }

    static class DSolveTheMaze {
        private static final char GOOD = 'G';
        private static final char BAD = 'B';
        private static final char EMPTY = '.';
        private static final char WALL = '#';

        private static final int[][] DIRECTIONS = {
                {0, -1}, {-1, 0}, {1, 0}, {0, 1}
        };

        public void solve(FastReader in, PrintWriter out) {
            try {
                int testCases = in.nextInt();
                while (testCases-- > 0) {
                    int rows = in.nextInt();
                    int cols = in.nextInt();
                    char[][] grid = readGrid(in, rows, cols);

                    expandBadCells(grid, rows, cols);
                    boolean[][] reachable = bfs(grid, rows, cols, rows - 1, cols - 1);
                    boolean isValid = validateConditions(grid, reachable, rows, cols);

                    out.println(isValid ? "Yes" : "No");
                }
            } catch (IOException e) {
                throw new RuntimeException("Error reading test case input", e);
            }
        }

        private char[][] readGrid(FastReader in, int rows, int cols) throws IOException {
            char[][] grid = new char[rows][];
            for (int i = 0; i < rows; i++) {
                grid[i] = in.next().toCharArray();
            }
            return grid;
        }

        private void expandBadCells(char[][] grid, int rows, int cols) {
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] == BAD) {
                        for (int[] dir : DIRECTIONS) {
                            int nr = r + dir[0];
                            int nc = c + dir[1];
                            if (isValidCell(nr, nc, rows, cols) && grid[nr][nc] == EMPTY) {
                                grid[nr][nc] = WALL;
                            }
                        }
                    }
                }
            }
        }

        private boolean[][] bfs(char[][] grid, int rows, int cols, int startR, int startC) {
            boolean[][] reachable = new boolean[rows][cols];
            Queue<Cell> queue = new LinkedList<>();

            if (grid[startR][startC] != WALL) {
                queue.offer(new Cell(startR, startC));
                reachable[startR][startC] = true;
            }

            while (!queue.isEmpty()) {
                Cell current = queue.poll();
                for (int[] dir : DIRECTIONS) {
                    int nr = current.r + dir[0];
                    int nc = current.c + dir[1];
                    if (isValidCell(nr, nc, rows, cols) && grid[nr][nc] != WALL && !reachable[nr][nc]) {
                        reachable[nr][nc] = true;
                        queue.offer(new Cell(nr, nc));
                    }
                }
            }
            return reachable;
        }

        private boolean validateConditions(char[][] grid, boolean[][] reachable, int rows, int cols) {
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    char cell = grid[r][c];
                    if (cell == BAD && reachable[r][c]) {
                        return false;
                    }
                    if (cell == GOOD && !reachable[r][c]) {
                        return false;
                    }
                }
            }
            return true;
        }

        private boolean isValidCell(int r, int c, int rows, int cols) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }

        // Helper class to replace int[] for better readability and type safety
        static class Cell {
            final int r, c;

            Cell(int r, int c) {
                this.r = r;
                this.c = c;
            }
        }
    }

    static class FastReader {
        private final byte[] buf = new byte[1024];
        private int index;
        private final InputStream in;
        private int total;

        public FastReader(InputStream in) {
            this.in = in;
        }

        public int scan() throws IOException {
            if (total < 0) {
                throw new InputMismatchException();
            }
            if (index >= total) {
                index = 0;
                total = in.read(buf);
                if (total <= 0) {
                    return -1;
                }
            }
            return buf[index++];
        }

        public int nextInt() throws IOException {
            int integer = 0;
            int n = scan();
            while (isWhiteSpace(n)) {
                n = scan();
            }
            int neg = 1;
            if (n == '-') {
                neg = -1;
                n = scan();
            }
            while (!isWhiteSpace(n)) {
                if (n >= '0' && n <= '9') {
                    integer *= 10;
                    integer += n - '0';
                    n = scan();
                } else {
                    throw new InputMismatchException();
                }
            }
            return neg * integer;
        }

        public String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int n = scan();
            while (isWhiteSpace(n)) {
                n = scan();
            }
            while (!isWhiteSpace(n)) {
                sb.append((char) n);
                n = scan();
            }
            return sb.toString();
        }

        private boolean isWhiteSpace(int n) {
            return n == ' ' || n == '\n' || n == '\r' || n == '\t' || n == -1;
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.ArrayDeque;
import java.util.HashSet;
import java.util.Objects;
import java.util.Set;
import java.util.StringTokenizer;

public class Main {

    // Direction vectors for right, left, down, up
    private static final int[] DX = {1, -1, 0, 0};
    private static final int[] DY = {0, 0, 1, -1};

    /**
     * Immutable coordinate class to replace the original mutable Pair.
     * Provides proper equals/hashCode for use in Collections.
     */
    private static final class Point {
        final int x, y;

        Point(int x, int y) {
            this.x = x;
            this.y = y;
        }

        @Override
        public boolean equals(Object o) {
            if (this == o) return true;
            if (!(o instanceof Point)) return false;
            Point p = (Point) o;
            return x == p.x && y == p.y;
        }

        @Override
        public int hashCode() {
            return Objects.hash(x, y);
        }
    }

    public static void main(String[] args) {
        InputReader in = new InputReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        int t = in.nextInt();
        while (t-- > 0) {
            solve(in, out);
        }
        out.flush();
    }

    /**
     * Processes a single test case.
     */
    private static void solve(InputReader in, PrintWriter out) {
        int n = in.nextInt();
        int m = in.nextInt();
        char[][] grid = new char[n][m];
        Set<Point> greens = new HashSet<>();

        // Read grid and collect coordinates of all 'G' cells
        for (int i = 0; i < n; i++) {
            String row = in.next();
            for (int j = 0; j < m; j++) {
                grid[i][j] = row.charAt(j);
                if (grid[i][j] == 'G') {
                    greens.add(new Point(j, i));
                }
            }
        }

        // Validate constraints and mark blocked cells
        if (!validateAndMark(grid, n, m)) {
            out.println("No");
            return;
        }

        // Check if all 'G' cells can reach the bottom-right corner
        if (allGreensCanReachTarget(grid, n, m, greens)) {
            out.println("Yes");
        } else {
            out.println("No");
        }
    }

    /**
     * Checks if any 'B' is adjacent to 'G' (invalid).
     * Marks all non-'B' neighbors of 'B' as blocked ('#').
     */
    private static boolean validateAndMark(char[][] grid, int n, int m) {
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == 'B') {
                    for (int d = 0; d < 4; d++) {
                        int ni = i + DY[d];
                        int nj = j + DX[d];

                        if (ni < 0 || ni >= n || nj < 0 || nj >= m) continue;
                        if (grid[ni][nj] == 'G') return false; // 'B' adjacent to 'G' is invalid
                        if (grid[ni][nj] != 'B') grid[ni][nj] = '#'; // Mark non-'B' neighbors as blocked
                    }
                }
            }
        }
        return true;
    }

    /**
     * Verifies that every 'G' cell can reach the target (n-1, m-1).
     * Uses a visitId counter to avoid reallocating/clearing the visited array per BFS.
     */
    private static boolean allGreensCanReachTarget(char[][] grid, int n, int m, Set<Point> greens) {
        int[][] visited = new int[n][m];
        int visitId = 0;
        int targetR = n - 1;
        int targetC = m - 1;

        for (Point p : greens) {
            visitId++;
            if (!bfs(p.y, p.x, grid, n, m, visited, visitId, targetR, targetC)) {
                return false;
            }
        }
        return visited[targetR][targetC] != 0;
    }

    /**
     * Standard BFS to check reachability from start to target.
     */
    private static boolean bfs(int startR, int startC, char[][] grid, int n, int m,
                               int[][] visited, int visitId, int targetR, int targetC) {
        ArrayDeque<Point> queue = new ArrayDeque<>();
        queue.add(new Point(startC, startR));
        visited[startR][startC] = visitId;

        while (!queue.isEmpty()) {
            Point curr = queue.poll();
            if (curr.y == targetR && curr.x == targetC) return true;

            for (int d = 0; d < 4; d++) {
                int ni = curr.y + DY[d];
                int nj = curr.x + DX[d];

                if (ni < 0 || ni >= n || nj < 0 || nj >= m) continue;
                if (grid[ni][nj] == '#') continue;
                if (visited[ni][nj] == visitId) continue;

                visited[ni][nj] = visitId;
                queue.add(new Point(nj, ni));
            }
        }
        return false;
    }

    /**
     * Fast I/O helper for competitive programming environments.
     */
    static class InputReader {
        public BufferedReader reader;
        public StringTokenizer tokenizer;

        public InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            String s = next();
            return s == null ? 0 : Integer.parseInt(s);
        }

        public long nextLong() {
            String s = next();
            return s == null ? 0L : Long.parseLong(s);
        }
    }
}

import java.io.*;
import java.util.*;

public class Main {
    // Constants for grid cell types to eliminate magic characters
    private static final char WALL = '#';
    private static final char BAD  = 'B';
    private static final char GOOD = 'G';

    // Movement directions: right, left, down, up
    private static final int[][] DIRECTIONS = {{0, 1}, {0, -1}, {1, 0}, {-1, 0}};

    public static void main(String[] args) {
        InputReader in = new InputReader(System.in);
        PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out));
        new MazeSolver().solve(in, out);
        out.flush();
    }

    /**
     * Encapsulates the game logic and validation rules.
     */
    static class MazeSolver {
        public void solve(InputReader in, PrintWriter out) {
            int t = in.nextInt();
            while (t-- > 0) {
                int n = in.nextInt();
                int m = in.nextInt();
                char[][] grid = new char[n][m];
                List<Point> bads = new ArrayList<>();
                List<Point> goods = new ArrayList<>();

                // Parse grid and collect coordinates
                for (int i = 0; i < n; i++) {
                    String row = in.nextToken();
                    grid[i] = row.toCharArray();
                    for (int j = 0; j < m; j++) {
                        char cell = grid[i][j];
                        if (cell == BAD) bads.add(new Point(i, j));
                        else if (cell == GOOD) goods.add(new Point(i, j));
                    }
                }

                out.println(isValidConfiguration(grid, bads, goods, n, m) ? "Yes" : "No");
            }
        }

        /**
         * Validates the maze according to the problem rules:
         * 1. No 'B' cell can reach any 'G' cell.
         * 2. All 'G' cells must be reachable from the bottom-right corner.
         */
        private boolean isValidConfiguration(char[][] grid, List<Point> bads, List<Point> goods, int n, int m) {
            // Phase 1: Ensure no Bad cell can reach a Good cell
            for (Point bad : bads) {
                boolean[][] visited = new boolean[n][m];
                if (canReachGood(bad.r, bad.c, grid, visited)) {
                    return false;
                }
            }

            // Phase 2: Ensure all Good cells are reachable from (n-1, m-1)
            // Special rule: If the starting cell is a wall, the configuration is valid 
            // only if there are no Good cells at all.
            if (grid[n - 1][m - 1] == WALL) {
                return goods.isEmpty();
            }

            boolean[][] visited = new boolean[n][m];
            traverseFrom(grid, n - 1, m - 1, visited);

            for (Point good : goods) {
                if (!visited[good.r][good.c]) {
                    return false;
                }
            }
            return true;
        }

        /**
         * Iterative DFS to check if any Good cell is reachable from a Bad cell.
         */
        private boolean canReachGood(int startR, int startC, char[][] grid, boolean[][] visited) {
            Deque<Point> stack = new ArrayDeque<>();
            stack.push(new Point(startR, startC));
            visited[startR][startC] = true;

            while (!stack.isEmpty()) {
                Point curr = stack.pop();
                if (grid[curr.r][curr.c] == GOOD) {
                    return true;
                }

                for (int[] dir : DIRECTIONS) {
                    int nr = curr.r + dir[0];
                    int nc = curr.c + dir[1];
                    if (isValidCell(nr, nc, grid) && !visited[nr][nc]) {
                        visited[nr][nc] = true;
                        stack.push(new Point(nr, nc));
                    }
                }
            }
            return false;
        }

        /**
         * Iterative DFS to mark all reachable cells from a starting point.
         */
        private void traverseFrom(char[][] grid, int startR, int startC, boolean[][] visited) {
            Deque<Point> stack = new ArrayDeque<>();
            stack.push(new Point(startR, startC));
            visited[startR][startC] = true;

            while (!stack.isEmpty()) {
                Point curr = stack.pop();
                for (int[] dir : DIRECTIONS) {
                    int nr = curr.r + dir[0];
                    int nc = curr.c + dir[1];
                    if (isValidCell(nr, nc, grid) && !visited[nr][nc]) {
                        visited[nr][nc] = true;
                        stack.push(new Point(nr, nc));
                    }
                }
            }
        }

        /**
         * Checks bounds and wall conditions for a cell.
         */
        private boolean isValidCell(int r, int c, char[][] grid) {
            return r >= 0 && r < grid.length && c >= 0 && c < grid[0].length && grid[r][c] != WALL;
        }

        /**
         * Immutable coordinate holder.
         */
        private static class Point {
            final int r, c;
            Point(int r, int c) {
                this.r = r;
                this.c = c;
            }
        }
    }

    /**
     * Fast I/O helper for competitive programming environments.
     */
    static class InputReader {
        BufferedReader br;
        StringTokenizer st;

        public InputReader(InputStream stream) {
            br = new BufferedReader(new InputStreamReader(stream));
        }

        public String nextToken() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(nextToken());
        }

        public long nextLong() {
            return Long.parseLong(nextToken());
        }
    }
}

import java.io.BufferedWriter;
import java.io.IOException;
import java.io.InputStream;
import java.io.OutputStream;
import java.io.OutputStreamWriter;
import java.io.PrintWriter;
import java.io.Writer;
import java.util.InputMismatchException;

/**
 * Solves a maze pathfinding problem with blocker propagation logic.
 * Refactored for maintainability, readability, and robustness.
 */
public class MazeSolver {

    // Constants for maze characters
    private static final char BLOCKER = 'B';
    private static final char GOAL = 'G';
    private static final char WALL = '#';
    private static final char EMPTY = '.';

    public static void main(String[] args) {
        // Use try-with-resources to ensure proper I/O cleanup and flushing
        try (InputReader in = new InputReader(System.in);
             OutputWriter out = new OutputWriter(System.out)) {
            solve(in, out);
        } catch (Exception e) {
            System.err.println("An error occurred: " + e.getMessage());
        }
    }

    /**
     * Orchestrates the solving process for multiple test cases.
     */
    private static void solve(InputReader in, OutputWriter out) {
        int t = in.nextInt();
        while (t-- > 0) {
            int n = in.nextInt();
            int m = in.nextInt();
            char[][] maze = new char[n][m];

            // Read maze grid
            for (int i = 0; i < n; i++) {
                maze[i] = in.next().toCharArray();
            }

            // Quick check: if the exit is blocked, the answer is immediately No
            if (maze[n - 1][m - 1] == BLOCKER || maze[n - 1][m - 1] == WALL) {
                out.println("No");
                continue;
            }

            // Track visited cells during block propagation
            boolean[][] visited = new boolean[n][m];

            // Mark empty cells reachable from blockers as walls
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    if (maze[i][j] == BLOCKER) {
                        propagateBlock(i, j, n, m, maze, visited);
                    }
                }
            }

            boolean possible = true;
            // Verify if all goals can reach the exit
            for (int i = 0; i < n && possible; i++) {
                for (int j = 0; j < m; j++) {
                    if (maze[i][j] == GOAL) {
                        // Reset visited array for each independent goal check
                        visited = new boolean[n][m];
                        if (!canReachExit(i, j, n, m, maze, visited)) {
                            possible = false;
                        }
                    }
                }
            }

            out.println(possible ? "Yes" : "No");
        }
    }

    /**
     * Checks if a path exists from (r, c) to the bottom-right corner.
     * Uses depth-first search with backtracking.
     */
    private static boolean canReachExit(int r, int c, int n, int m, char[][] maze, boolean[][] visited) {
        // Boundary check
        if (r < 0 || r >= n || c < 0 || c >= m) {
            return false;
        }
        // Already visited or wall
        if (visited[r][c] || maze[r][c] == WALL) {
            return false;
        }

        // Reached the exit
        if (r == n - 1 && c == m - 1 && (maze[r][c] == GOAL || maze[r][c] == EMPTY)) {
            return true;
        }

        visited[r][c] = true;
        boolean canGo = canReachExit(r + 1, c, n, m, maze, visited);
        if (!canGo) canGo = canReachExit(r, c + 1, n, m, maze, visited);
        if (!canGo) canGo = canReachExit(r - 1, c, n, m, maze, visited);
        if (!canGo) canGo = canReachExit(r, c - 1, n, m, maze, visited);
        return canGo;
    }

    /**
     * Propagates blockage from a blocker cell.
     * Note: Mutates the maze array by turning reachable '.' cells into walls.
     * Recursion stops at '.' cells but continues through 'B' cells.
     */
    private static void propagateBlock(int r, int c, int n, int m, char[][] maze, boolean[][] visited) {
        if (r < 0 || r >= n || c < 0 || c >= m) {
            return;
        }
        if (visited[r][c] || maze[r][c] == WALL) {
            return;
        }

        visited[r][c] = true;
        if (maze[r][c] == EMPTY) {
            maze[r][c] = WALL; // Block empty cells but do not recurse further
        } else {
            // Continue traversal from blocker cells
            propagateBlock(r - 1, c, n, m, maze, visited);
            propagateBlock(r, c - 1, n, m, maze, visited);
            propagateBlock(r + 1, c, n, m, maze, visited);
            propagateBlock(r, c + 1, n, m, maze, visited);
        }
    }

    // ========================================================================
    // I/O Utility Classes (Standard Competitive Programming Templates)
    // ========================================================================

    static class InputReader {
        private final InputStream stream;
        private final byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;
        private SpaceCharFilter filter;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        public int read() {
            if (numChars == -1) {
                throw new InputMismatchException();
            }
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0) {
                    return -1;
                }
            }
            return buf[curChar++];
        }

        public int nextInt() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                res *= 10;
                res += c - '0';
                c = read();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public long nextLong() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            long res = 0;
            do {
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                res *= 10;
                res += c - '0';
                c = read();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public String next() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            StringBuilder res = new StringBuilder();
            do {
                res.appendCodePoint(c);
                c = read();
            } while (!isSpaceChar(c));
            return res.toString();
        }

        public boolean isSpaceChar(int c) {
            return filter != null ? filter.isSpaceChar(c) : (c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1);
        }

        public interface SpaceCharFilter {
            boolean isSpaceChar(int ch);
        }
    }

    static class OutputWriter {
        private final PrintWriter writer;

        public OutputWriter(OutputStream outputStream) {
            writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(outputStream)));
        }

        public OutputWriter(Writer writer) {
            this.writer = new PrintWriter(writer);
        }

        public void print(Object... objects) {
            for (int i = 0; i < objects.length; i++) {
                if (i != 0) {
                    writer.print(' ');
                }
                writer.print(objects[i]);
            }
        }

        public void println(Object... objects) {
            print(objects);
            writer.println();
        }

        // Alias for compatibility with original naming convention
        public void printLine(Object... objects) {
            println(objects);
        }

        public void flush() {
            writer.flush();
        }

        public void close() {
            writer.close();
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayDeque;
import java.util.StringTokenizer;

/**
 * Solves the grid path problem:
 * 1. Blockers ('B') convert adjacent empty cells ('.') to walls ('#').
 * 2. All Goal cells ('G') must be able to reach the bottom-right corner.
 * 3. No Blocker ('B') cell must be able to reach the bottom-right corner.
 */
public class GridPathSolver {

    // Direction vectors for Up, Down, Left, Right
    private static final int[] DX = {-1, 1, 0, 0};
    private static final int[] DY = {0, 0, -1, 1};

    // Grid cell types
    private static final char WALL = '#';
    private static final char BLANK = '.';
    private static final char GOAL = 'G';
    private static final char BLOCKER = 'B';

    public static void main(String[] args) {
        GridPathSolver solver = new GridPathSolver();
        solver.run();
    }

    /**
     * Orchestrates reading input and processing each test case.
     */
    public void run() {
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(System.in))) {
            StringTokenizer tokenizer = new StringTokenizer("");

            // Read number of test cases
            String token = nextToken(reader, tokenizer);
            if (token == null) return;
            int T = Integer.parseInt(token);

            for (int t = 0; t < T; t++) {
                // Read n and m
                token = nextToken(reader, tokenizer);
                int n = Integer.parseInt(token);
                token = nextToken(reader, tokenizer);
                int m = Integer.parseInt(token);

                // Read grid
                char[][] grid = new char[n][m];
                for (int i = 0; i < n; i++) {
                    String line = reader.readLine();
                    while (line != null && line.trim().isEmpty()) { // Skip empty lines if any
                        line = reader.readLine();
                    }
                    if (line != null) {
                        for (int j = 0; j < m; j++) {
                            grid[i][j] = line.charAt(j);
                        }
                    }
                }

                processTestCase(grid, n, m);
            }
        } catch (IOException e) {
            System.err.println("Error reading input: " + e.getMessage());
        }
    }

    /**
     * Helper to safely retrieve the next token from the reader.
     */
    private String nextToken(BufferedReader reader, StringTokenizer tokenizer) throws IOException {
        while (!tokenizer.hasMoreTokens()) {
            String line = reader.readLine();
            if (line == null) return null;
            tokenizer = new StringTokenizer(line);
        }
        return tokenizer.nextToken();
    }

    /**
     * Processes a single test case: applies blocker effects and validates paths.
     */
    private void processTestCase(char[][] grid, int n, int m) {
        applyBlockerEffects(grid, n, m);

        boolean allGoalsReachEnd = true;
        boolean noBlockersReachEnd = true;

        boolean[][] visitedGoals = new boolean[n][m];
        boolean[][] visitedBlockers = new boolean[n][m];

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == GOAL && !visitedGoals[i][j]) {
                    if (!canReach(grid, n, m, i, j, n - 1, m - 1, visitedGoals)) {
                        allGoalsReachEnd = false;
                    }
                }
                if (grid[i][j] == BLOCKER && !visitedBlockers[i][j]) {
                    if (canReach(grid, n, m, i, j, n - 1, m - 1, visitedBlockers)) {
                        noBlockersReachEnd = false;
                    }
                }
            }
        }

        System.out.println(allGoalsReachEnd && noBlockersReachEnd ? "Yes" : "No");
    }

    /**
     * Modifies the grid in-place: adjacent '.' cells to any 'B' become '#'.
     */
    private void applyBlockerEffects(char[][] grid, int n, int m) {
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == BLOCKER) {
                    for (int d = 0; d < 4; d++) {
                        int ni = i + DX[d];
                        int nj = j + DY[d];
                        if (ni >= 0 && ni < n && nj >= 0 && nj < m && grid[ni][nj] == BLANK) {
                            grid[ni][nj] = WALL;
                        }
                    }
                }
            }
        }
    }

    /**
     * Performs BFS to check if a path exists from (startX, startY) to (targetX, targetY)
     * avoiding walls. Marks visited cells in the provided array to prevent redundant BFS runs.
     */
    private boolean canReach(char[][] grid, int n, int m, int startX, int startY, 
                             int targetX, int targetY, boolean[][] visited) {
        ArrayDeque<int[]> queue = new ArrayDeque<>();
        queue.add(new int[]{startX, startY});
        visited[startX][startY] = true;

        while (!queue.isEmpty()) {
            int[] current = queue.poll();
            int x = current[0];
            int y = current[1];

            if (x == targetX && y == targetY) {
                return true;
            }

            for (int d = 0; d < 4; d++) {
                int nx = x + DX[d];
                int ny = y + DY[d];

                if (nx >= 0 && nx < n && ny >= 0 && ny < m && 
                    !visited[nx][ny] && grid[nx][ny] != WALL) {
                    visited[nx][ny] = true;
                    queue.add(new int[]{nx, ny});
                }
            }
        }
        return false;
    }
}

import java.io.*;
import java.util.ArrayDeque;
import java.util.Deque;
import java.util.StringTokenizer;

/**
 * Solves a grid-based pathfinding problem where balls block adjacent empty cells,
 * and determines if all goals are reachable from the bottom-right corner.
 */
public class MazeSolver {

    // Grid cell constants
    private static final char EMPTY = '.';
    private static final char BLOCKED = '#';
    private static final char BALL = 'B';
    private static final char GOAL = 'G';

    // Direction vectors: Up, Down, Left, Right
    private static final int[] DR = {-1, 1, 0, 0};
    private static final int[] DC = {0, 0, -1, 1};

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner();
        PrintWriter out = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)));

        try {
            int t = scanner.nextInt();
            while (t-- > 0) {
                solve(scanner, out);
            }
        } finally {
            out.flush();
            out.close();
        }
    }

    /**
     * Processes a single test case.
     */
    private static void solve(FastScanner scanner, PrintWriter out) {
        int n = scanner.nextInt();
        int m = scanner.nextInt();

        char[][] maze = new char[n][m];
        for (int i = 0; i < n; i++) {
            maze[i] = scanner.next().toCharArray();
        }

        // 1. Process balls: block adjacent empty cells and check for adjacent goals
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (maze[i][j] == BALL) {
                    for (int k = 0; k < 4; k++) {
                        int ni = i + DR[k];
                        int nj = j + DC[k];

                        if (ni >= 0 && ni < n && nj >= 0 && nj < m) {
                            if (maze[ni][nj] == GOAL) {
                                out.println("No");
                                return;
                            }
                            if (maze[ni][nj] == EMPTY) {
                                maze[ni][nj] = BLOCKED;
                            }
                        }
                    }
                }
            }
        }

        // 2. Count total goals in the grid
        int totalGoals = 0;
        for (char[] row : maze) {
            for (char cell : row) {
                if (cell == GOAL) {
                    totalGoals++;
                }
            }
        }

        // 3. BFS from bottom-right corner to find reachable goals
        int reachableGoals = bfs(maze, n, m, n - 1, m - 1);

        out.println(reachableGoals == totalGoals ? "Yes" : "No");
    }

    /**
     * Performs Breadth-First Search from (startR, startC) to count reachable goals.
     * Coordinates are encoded as (row * m + col) to avoid object allocation.
     */
    private static int bfs(char[][] maze, int n, int m, int startR, int startC) {
        if (maze[startR][startC] == BLOCKED) {
            return 0;
        }

        boolean[][] visited = new boolean[n][m];
        Deque<Integer> queue = new ArrayDeque<>();

        queue.add(startR * m + startC);
        visited[startR][startC] = true;

        int reachableCount = 0;

        while (!queue.isEmpty()) {
            int pos = queue.poll();
            int r = pos / m;
            int c = pos % m;

            if (maze[r][c] == GOAL) {
                reachableCount++;
            }

            for (int k = 0; k < 4; k++) {
                int nr = r + DR[k];
                int nc = c + DC[k];

                if (nr >= 0 && nr < n && nc >= 0 && nc < m &&
                    maze[nr][nc] != BLOCKED && !visited[nr][nc]) {
                    visited[nr][nc] = true;
                    queue.add(nr * m + nc);
                }
            }
        }
        return reachableCount;
    }

    /**
     * Fast I/O helper class for competitive programming style inputs.
     */
    private static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input", e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            String s = next();
            if (s == null) throw new RuntimeException("Unexpected end of input");
            return Integer.parseInt(s);
        }
    }
}

import java.util.ArrayDeque;
import java.util.Queue;
import java.util.Scanner;

/**
 * Solves a grid reachability problem where:
 * 1. 'B' (Black) cells cannot be adjacent to 'G' (Green) cells.
 * 2. All '.' (Empty) cells adjacent to 'B' become walls '#'.
 * 3. Determines if all 'G' cells are reachable from the bottom-right corner (n-1, m-1).
 */
public class GridReachabilitySolver {

    // Constants for grid characters to eliminate magic values
    private static final char BLACK = 'B';
    private static final char GREEN = 'G';
    private static final char EMPTY = '.';
    private static final char WALL = '#';

    // Direction vectors for up, down, left, right movement
    private static final int[][] DIRECTIONS = {
        {-1, 0}, {1, 0}, {0, -1}, {0, 1}
    };

    public static void main(String[] args) {
        // Use try-with-resources for automatic resource cleanup
        try (Scanner scanner = new Scanner(System.in)) {
            if (scanner.hasNextInt()) {
                int testCases = scanner.nextInt();
                while (testCases-- > 0) {
                    solveTestCase(scanner);
                }
            }
        }
    }

    /**
     * Processes a single test case: reads input, applies rules, and prints the result.
     */
    private static void solveTestCase(Scanner scanner) {
        int rows = scanner.nextInt();
        int cols = scanner.nextInt();
        char[][] grid = new char[rows][cols];

        // Read the grid row by row
        for (int r = 0; r < rows; r++) {
            grid[r] = scanner.next().toCharArray();
        }

        // Rule 1: Check if any Black cell is directly adjacent to a Green cell
        if (hasAdjacentBlackAndGreen(grid)) {
            System.out.println("No");
            return;
        }

        // Rule 2: Block all empty cells adjacent to Black cells
        blockEmptyNeighbors(grid);

        // Rule 3: Check if all Green cells are reachable from the bottom-right corner
        if (canReachAllGreen(grid)) {
            System.out.println("Yes");
        } else {
            System.out.println("No");
        }
    }

    /**
     * Returns true if any 'B' cell is adjacent to a 'G' cell.
     */
    private static boolean hasAdjacentBlackAndGreen(char[][] grid) {
        int rows = grid.length;
        int cols = grid[0].length;

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == BLACK) {
                    for (int[] dir : DIRECTIONS) {
                        int nr = r + dir[0];
                        int nc = c + dir[1];
                        if (isValidCell(nr, nc, rows, cols) && grid[nr][nc] == GREEN) {
                            return true;
                        }
                    }
                }
            }
        }
        return false;
    }

    /**
     * Modifies the grid in-place: changes '.' to '#' if adjacent to 'B'.
     */
    private static void blockEmptyNeighbors(char[][] grid) {
        int rows = grid.length;
        int cols = grid[0].length;

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == BLACK) {
                    for (int[] dir : DIRECTIONS) {
                        int nr = r + dir[0];
                        int nc = c + dir[1];
                        if (isValidCell(nr, nc, rows, cols) && grid[nr][nc] == EMPTY) {
                            grid[nr][nc] = WALL;
                        }
                    }
                }
            }
        }
    }

    /**
     * Uses iterative BFS from (n-1, m-1) to verify all 'G' cells are reachable.
     */
    private static boolean canReachAllGreen(char[][] grid) {
        int rows = grid.length;
        int cols = grid[0].length;
        boolean[][] visited = new boolean[rows][cols];

        int targetR = rows - 1;
        int targetC = cols - 1;

        // Count total Green cells in the grid
        int totalGreenCount = 0;
        for (char[] row : grid) {
            for (char cell : row) {
                if (cell == GREEN) {
                    totalGreenCount++;
                }
            }
        }

        // Trivially satisfied if there are no Green cells
        if (totalGreenCount == 0) {
            return true;
        }

        // Starting point is blocked, so nothing is reachable
        if (grid[targetR][targetC] == WALL) {
            return false;
        }

        // Iterative BFS to prevent StackOverflowError on large grids
        Queue<int[]> queue = new ArrayDeque<>();
        queue.offer(new int[]{targetR, targetC});
        visited[targetR][targetC] = true;

        int visitedGreenCount = 0;

        while (!queue.isEmpty()) {
            int[] current = queue.poll();
            int r = current[0];
            int c = current[1];

            if (grid[r][c] == GREEN) {
                visitedGreenCount++;
            }

            for (int[] dir : DIRECTIONS) {
                int nr = r + dir[0];
                int nc = c + dir[1];
                if (isValidCell(nr, nc, rows, cols) && !visited[nr][nc] && grid[nr][nc] != WALL) {
                    visited[nr][nc] = true;
                    queue.offer(new int[]{nr, nc});
                }
            }
        }

        return visitedGreenCount == totalGreenCount;
    }

    /**
     * Helper method to check grid boundaries.
     */
    private static boolean isValidCell(int r, int c, int rows, int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }
}

