            }
        } catch (Exception e) {
            // In competitive programming, we assume valid input format.
            // This block prevents unexpected crashes from malformed input.
        } finally {
            out.flush();
        }
    }

    /**
     * Orchestrates the logic for a single test case.
     */
    private static void solve(FastScanner scanner, PrintWriter out) {
        int rows = scanner.nextInt();
        int cols = scanner.nextInt();
        char[][] grid = new char[rows][];

        for (int i = 0; i < rows; i++) {
            grid[i] = scanner.next().toCharArray();
        }

        // Step 1: Validate that no Goal is adjacent to a Block
        if (hasAdjacentGoalAndBlock(grid, rows, cols)) {
            out.println("No");
            return;
        }

        // Step 2: If no Goals exist, the condition is trivially satisfied
        if (!gridContainsGoal(grid, rows, cols)) {
            out.println("Yes");
            return;
        }

        // Step 3: Transform the grid: mark cells adjacent to Blocks as Walls
        markAdjacentCellsAsWalls(grid, rows, cols);

        // Step 4: If the destination is blocked, it's unreachable
        if (grid[rows - 1][cols - 1] == WALL) {
            out.println("No");
            return;
        }

        // Step 5: Check if all Goals are reachable from the destination
        if (areAllGoalsReachable(grid, rows, cols)) {
            out.println("Yes");
        } else {
            out.println("No");
        }
    }

    /**
     * Checks if any Goal cell has an adjacent Block cell.
     */
    private static boolean hasAdjacentGoalAndBlock(char[][] grid, int rows, int cols) {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == GOAL) {
                    for (int[] dir : DIRECTIONS) {
                        int nr = r + dir[0];
                        int nc = c + dir[1];
                        if (isWithinBounds(nr, nc, rows, cols) && grid[nr][nc] == BLOCK) {
                            return true; // Invalid configuration detected
                        }
                    }
                }
            }
        }
        return false;
    }

    /**
     * Checks if the grid contains at least one Goal cell.
     */
    private static boolean gridContainsGoal(char[][] grid, int rows, int cols) {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == GOAL) {
                    return true;
                }
            }
        }
        return false;
    }

    /**
     * Modifies the grid in-place: marks EMPTY cells adjacent to BLOCKs as WALLs.
     */
    private static void markAdjacentCellsAsWalls(char[][] grid, int rows, int cols) {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == BLOCK) {
                    for (int[] dir : DIRECTIONS) {
                        int nr = r + dir[0];
                        int nc = c + dir[1];
                        if (isWithinBounds(nr, nc, rows, cols) && grid[nr][nc] == EMPTY) {
                            grid[nr][nc] = WALL;
                        }
                    }
                }
            }
        }
    }

    /**
     * Performs BFS from the bottom-right corner and verifies all Goals are reachable.
     */
    private static boolean areAllGoalsReachable(char[][] grid, int rows, int cols) {
        boolean[][] visited = new boolean[rows][cols];
        Queue<int[]> queue = new ArrayDeque<>();

        int startRow = rows - 1;
        int startCol = cols - 1;
        queue.offer(new int[]{startRow, startCol});
        visited[startRow][startCol] = true;

        while (!queue.isEmpty()) {
            int[] current = queue.poll();
            int r = current[0];
            int c = current[1];

            for (int[] dir : DIRECTIONS) {
                int nr = r + dir[0];
                int nc = c + dir[1];

                if (isWithinBounds(nr, nc, rows, cols)
                        && !visited[nr][nc]
                        && grid[nr][nc] != WALL) {
                    visited[nr][nc] = true;
                    queue.offer(new int[]{nr, nc});
                }
            }
        }

        // Verify all Goals are visited
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == GOAL && !visited[r][c]) {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Utility method to check grid boundaries.
     */
    private static boolean isWithinBounds(int r, int c, int rows, int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /**
     * Optimized Fast I/O scanner for competitive programming.
     * Removed unused methods to reduce cognitive load and dead code.
     */
    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        public String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input", e);
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.ArrayDeque;
import java.util.Queue;
import java.util.StringTokenizer;

/**
 * Refactored Maze Solver.
 * 
 * Improvements made:
 * 1. Class Naming: Renamed to 'MazeSolver' for better convention.
 * 2. Code Structure: Separated logic into distinct methods (solveTestCase, solveMaze, bfsCheckReachability).
 * 3. Variable Naming: Used descriptive names (rows, cols, grid, dx, dy, visited).
 * 4. Constants: Replaced magic numbers and arrays with named constants or clear logic.
 * 5. FastReader: Improved robustness (handles EOF, throws RuntimeException on IO error instead of silent loops).
 * 6. Dead Code: Removed unused 'shuffle' and 'swap' methods.
 * 7. BFS Optimization: Used ArrayDeque instead of LinkedList for better performance.
 * 8. Readability: Added comments and clearer control flow.
 */
public class MazeSolver {

    public static void main(String[] args) {
        FastReader sc = new FastReader();
        PrintWriter out = new PrintWriter(System.out);

        // Read number of test cases safely
        String tStr = sc.next();
        if (tStr != null) {
            int testCases = Integer.parseInt(tStr);
            while (testCases-- > 0) {
                solveTestCase(sc, out);
            }
        }

        out.flush();
        out.close();
    }

    private static void solveTestCase(FastReader sc, PrintWriter out) {
        int rows = sc.nextInt();
        int cols = sc.nextInt();
        char[][] grid = new char[rows][cols];

        // Read grid rows
        for (int i = 0; i < rows; i++) {
            String line = sc.next();
            if (line != null) {
                grid[i] = line.toCharArray();
            }
        }

        if (solveMaze(rows, cols, grid)) {
            out.println("Yes");
        } else {
            out.println("No");
        }
    }

    /**
     * Solves the maze logic for a single test case.
     * 1. Processes 'B' (Blocker) constraints.
     * 2. Checks reachability of all 'G' (Goal) cells from the bottom-right corner.
     */
    private static boolean solveMaze(int rows, int cols, char[][] grid) {
        // Direction vectors: Right, Left, Down, Up
        int[] dx = {1, -1, 0, 0};
        int[] dy = {0, 0, 1, -1};

        // 1. Process 'B' (Blocker) constraints
        // If 'B' is adjacent to '.', it blocks the path (turns into '#').
        // If 'B' is adjacent to 'G', it's an immediate failure.
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == 'B') {
                    for (int k = 0; k < 4; k++) {
                        int nr = r + dx[k];
                        int nc = c + dy[k];

                        if (isValid(nr, nc, rows, cols)) {
                            if (grid[nr][nc] == '.') {
                                grid[nr][nc] = '#'; // Turn path into wall
                            } else if (grid[nr][nc] == 'G') {
                                return false; // 'G' is blocked by 'B'
                            }
                        }
                    }
                }
            }
        }

        // 2. BFS to check if all 'G' cells are reachable from bottom-right (rows-1, cols-1)
        return bfsCheckReachability(rows, cols, grid);
    }

    /**
     * Performs BFS starting from the bottom-right corner to determine reachability.
     * Returns true if all 'G' cells in the grid are reachable.
     */
    private static boolean bfsCheckReachability(int rows, int cols, char[][] grid) {
        int[] dx = {1, -1, 0, 0};
        int[] dy = {0, 0, 1, -1};

        // Queue for BFS: stores int arrays {row, col}
        Queue<int[]> queue = new ArrayDeque<>();
        boolean[][] visited = new boolean[rows][cols];

        // Check if the starting position is valid
        // Valid cells are '.' (path) or 'G' (goal)
        if (grid[rows - 1][cols - 1] == '.' || grid[rows - 1][cols - 1] == 'G') {
            queue.add(new int[]{rows - 1, cols - 1});
            visited[rows - 1][cols - 1] = true;
        }

        while (!queue.isEmpty()) {
            int[] current = queue.poll();
            int r = current[0];
            int c = current[1];

            for (int k = 0; k < 4; k++) {
                int nr = r + dx[k];
                int nc = c + dy[k];

                if (isValid(nr, nc, rows, cols)) {
                    char cell = grid[nr][nc];
                    // Can move to path or goal, and not visited yet
                    if ((cell == '.' || cell == 'G') && !visited[nr][nc]) {
                        visited[nr][nc] = true;
                        queue.add(new int[]{nr, nc});
                    }
                }
            }
        }

        // Verify that every 'G' in the grid has been visited
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == 'G' && !visited[r][c]) {
                    return false;
                }
            }
        }

        return true;
    }

    private static boolean isValid(int r, int c, int rows, int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /**
     * Fast I/O helper class.
     */
    static class FastReader {
        BufferedReader br;
        StringTokenizer st;

        public FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            String s = next();
            return s == null ? 0 : Integer.parseInt(s);
        }

        long nextLong() {
            String s = next();
            return s == null ? 0L : Long.parseLong(s);
        }

        double nextDouble() {
            String s = next();
            return s == null ? 0.0 : Double.parseDouble(s);
        }
    }
}

import java.io.*;
import java.util.*;

public class Main {
    // Directions: Right, Down, Left, Up
    private static final int[] DR = {0, 1, 0, -1};
    private static final int[] DC = {1, 0, -1, 0};

    public static void main(String[] args) {
        FastScanner in = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out));
        try {
            solve(in, out);
        } finally {
            out.flush();
            out.close();
        }
    }

    private static void solve(FastScanner in, PrintWriter out) {
        if (!in.hasNext()) return;
        int t = in.nextInt();
        for (int testCase = 1; testCase <= t; testCase++) {
            int n = in.nextInt();
            int m = in.nextInt();
            String[] grid = new String[n];
            for (int i = 0; i < n; i++) {
                grid[i] = in.next();
            }

            boolean isSolvable = processTestCase(n, m, grid);
            out.println(isSolvable ? "Yes" : "No");
        }
    }

    private static boolean processTestCase(int n, int m, String[] grid) {
        boolean[][] isBlocked = new boolean[n][m];
        List<int[]> goalPositions = new ArrayList<>();
        boolean isInvalid = false;

        // 1. Parse grid, mark blocked cells, and collect goal positions
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < m; c++) {
                char cell = grid[r].charAt(c);
                if (cell == '#') {
                    isBlocked[r][c] = true;
                } else if (cell == 'B') {
                    markBlockedNeighbors(r, c, n, m, grid, isBlocked);
                } else if (cell == 'G') {
                    goalPositions.add(new int[]{r, c});
                }
            }
        }

        // 2. Check for invalid adjacency: 'B' directly next to 'G'
        for (int[] goal : goalPositions) {
            int r = goal[0];
            int c = goal[1];
            for (int k = 0; k < 4; k++) {
                int nr = r + DR[k];
                int nc = c + DC[k];
                if (isValid(nr, nc, n, m) && grid[nr].charAt(nc) == 'B') {
                    isInvalid = true;
                    break;
                }
            }
            if (isInvalid) break;
        }

        if (isInvalid) return false;

        // 3. Perform DFS from the bottom-right cell to find reachable cells
        boolean[][] visited = new boolean[n][m];
        dfs(n - 1, m - 1, n, m, grid, isBlocked, visited);

        // 4. Verify all goal positions are reachable from the starting point
        for (int[] goal : goalPositions) {
            if (!visited[goal[0]][goal[1]]) {
                return false;
            }
        }

        return true;
    }

    private static void markBlockedNeighbors(int r, int c, int n, int m, String[] grid, boolean[][] isBlocked) {
        for (int k = 0; k < 4; k++) {
            int nr = r + DR[k];
            int nc = c + DC[k];
            if (isValid(nr, nc, n, m)) {
                char neighbor = grid[nr].charAt(nc);
                // Replicating original logic: mark as blocked unless neighbor is 'G' or 'B' 
                // and is located in the top or left direction relative to the 'B'
                if (nr >= r || nc >= c || (neighbor != 'G' && neighbor != 'B')) {
                    isBlocked[nr][nc] = true;
                }
            }
        }
    }

    private static void dfs(int r, int c, int n, int m, String[] grid, boolean[][] isBlocked, boolean[][] visited) {
        if (!isValid(r, c, n, m) || visited[r][c] || isBlocked[r][c]) {
            return;
        }

        visited[r][c] = true;
        for (int k = 0; k < 4; k++) {
            dfs(r + DR[k], c + DC[k], n, m, grid, isBlocked, visited);
        }
    }

    private static boolean isValid(int r, int c, int n, int m) {
        return r >= 0 && c >= 0 && r < n && c < m;
    }

    // FastScanner for efficient input reading in competitive programming contexts
    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        public boolean hasNext() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) {
                        return false;
                    }
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input", e);
                }
            }
            return true;
        }

        public String next() {
            if (hasNext()) {
                return st.nextToken();
            }
            return null;
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.OutputStreamWriter;
import java.io.PrintWriter;
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.List;
import java.util.Queue;
import java.util.StringTokenizer;

/**
 * Validates grid path constraints using Breadth-First Search (BFS).
 * Checks if 'B' cells can block the destination and if all 'G' cells remain reachable.
 */
public class PathValidator {

    // Magic constants replaced with named constants for clarity
    private static final char GOOD = 'G';
    private static final char BAD = 'B';
    private static final char EMPTY = '.';
    private static final char BLOCKED = '#';

    // Direction vectors for Up, Down, Left, Right
    private static final int[][] DIRECTIONS = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};

    public static void main(String[] args) throws IOException {
        // Efficient buffered I/O
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter writer = new PrintWriter(new OutputStreamWriter(System.out));

        String line = reader.readLine();
        if (line == null) return;
        int testCases = Integer.parseInt(line.trim());

        while (testCases-- > 0) {
            StringTokenizer st = new StringTokenizer(reader.readLine());
            int rows = Integer.parseInt(st.nextToken());
            int cols = Integer.parseInt(st.nextToken());

            char[][] grid = new char[rows][cols];
            List<Point> goodPoints = new ArrayList<>();
            List<Point> badPoints = new ArrayList<>();

            // Parse grid and collect target positions
            for (int i = 0; i < rows; i++) {
                String rowStr = reader.readLine();
                for (int j = 0; j < cols; j++) {
                    grid[i][j] = rowStr.charAt(j);
                    if (grid[i][j] == GOOD) {
                        goodPoints.add(new Point(i, j));
                    } else if (grid[i][j] == BAD) {
                        badPoints.add(new Point(i, j));
                    }
                }
            }

            // First BFS: Check if any 'B' can reach the bottom-right corner
            boolean isBadReachable = canBadReachEnd(grid, rows, cols, badPoints);

            if (!isBadReachable) {
                writer.println("No");
                continue;
            }

            // Second BFS: Check if all 'G' points are reachable from the bottom-right corner
            boolean isAllGoodReachable = canReachAllGood(grid, rows, cols, goodPoints);
            writer.println(isAllGoodReachable ? "Yes" : "No");
        }

        writer.flush();
        writer.close();
    }

    /**
     * Performs a BFS starting from all 'B' positions.
     * Returns false if a 'B' reaches (rows-1, cols-1), otherwise true.
     * Marks adjacent '.' cells as '#' but does not traverse through them.
     */
    private static boolean canBadReachEnd(char[][] grid, int rows, int cols, List<Point> badPoints) {
        Queue<Point> queue = new ArrayDeque<>(badPoints);
        boolean[][] visited = new boolean[rows][cols];

        while (!queue.isEmpty()) {
            Point current = queue.poll();
            if (visited[current.row][current.col]) continue;
            visited[current.row][current.col] = true;

            if (current.row == rows - 1 && current.col == cols - 1) {
                return false; // 'B' reached the target
            }

            for (int[] dir : DIRECTIONS) {
                int nr = current.row + dir[0];
                int nc = current.col + dir[1];

                if (isValid(nr, nc, rows, cols) && !visited[nr][nc]) {
                    char cell = grid[nr][nc];
                    if (cell == GOOD || cell == BAD) {
                        queue.add(new Point(nr, nc));
                    } else if (cell == EMPTY) {
                        grid[nr][nc] = BLOCKED;
                    }
                }
            }
        }
        return true; // 'B' did not reach the target
    }

    /**
     * Performs a BFS starting from the bottom-right corner.
     * Returns true if all 'G' points are reachable, otherwise false.
     */
    private static boolean canReachAllGood(char[][] grid, int rows, int cols, List<Point> goodPoints) {
        Queue<Point> queue = new ArrayDeque<>();
        queue.add(new Point(rows - 1, cols - 1));
        boolean[][] visited = new boolean[rows][cols];

        while (!queue.isEmpty()) {
            Point current = queue.poll();
            if (grid[current.row][current.col] == BLOCKED || visited[current.row][current.col]) continue;
            visited[current.row][current.col] = true;

            for (int[] dir : DIRECTIONS) {
                int nr = current.row + dir[0];
                int nc = current.col + dir[1];

                if (isValid(nr, nc, rows, cols) &&
                    grid[nr][nc] != BLOCKED && !visited[nr][nc]) {
                    queue.add(new Point(nr, nc));
                }
            }
        }

        for (Point p : goodPoints) {
            if (!visited[p.row][p.col]) {
                return false;
            }
        }
        return true;
    }

    private static boolean isValid(int r, int c, int rows, int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /**
     * Immutable coordinate holder for grid positions.
     */
    private static class Point {
        final int row;
        final int col;

        Point(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }
}

import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) {
        InputReader in = new InputReader(System.in);
        OutputWriter out = new OutputWriter(System.out);
        MazeSolver solver = new MazeSolver();
        solver.run(in, out);
        out.close();
    }

    static class MazeSolver {
        private static final char EMPTY = '.';
        private static final char BLOCKER = 'B';
        private static final char WALL = '#';
        private static final char GOAL = 'G';
        private static final int[][] DIRECTIONS = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};

        public void run(InputReader in, OutputWriter out) {
            int testCases = in.nextInt();
            for (int t = 0; t < testCases; t++) {
                out.println(solveTestCase(in));
            }
        }

        private String solveTestCase(InputReader in) {
            int rows = in.nextInt();
            int cols = in.nextInt();
            char[][] grid = readGrid(in, rows, cols);

            applyBlockers(grid, rows, cols);
            List<List<Integer>> adjacencyList = buildAdjacencyList(grid, rows, cols);
            int[] distances = computeBFS(adjacencyList, rows * cols);

            return validate(grid, rows, cols, distances);
        }

        private char[][] readGrid(InputReader in, int rows, int cols) {
            char[][] grid = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                grid[i] = in.next().toCharArray();
            }
            return grid;
        }

        private void applyBlockers(char[][] grid, int rows, int cols) {
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j] == BLOCKER) {
                        for (int[] dir : DIRECTIONS) {
                            int ni = i + dir[0];
                            int nj = j + dir[1];
                            if (isValid(ni, nj, rows, cols) && grid[ni][nj] == EMPTY) {
                                grid[ni][nj] = WALL;
                            }
                        }
                    }
                }
            }
        }

        private List<List<Integer>> buildAdjacencyList(char[][] grid, int rows, int cols) {
            int totalCells = rows * cols;
            List<List<Integer>> adj = new ArrayList<>(totalCells);
            for (int i = 0; i < totalCells; i++) {
                adj.add(new ArrayList<>());
            }

            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j] != WALL) {
                        for (int[] dir : DIRECTIONS) {
                            int ni = i + dir[0];
                            int nj = j + dir[1];
                            if (isValid(ni, nj, rows, cols) && grid[ni][nj] != WALL) {
                                int u = i * cols + j;
                                int v = ni * cols + nj;
                                // Add each undirected edge exactly once
                                if (v > u) {
                                    adj.get(u).add(v);
                                    adj.get(v).add(u);
                                }
                            }
                        }
                    }
                }
            }
            return adj;
        }

        private int[] computeBFS(List<List<Integer>> adj, int totalCells) {
            int[] distances = new int[totalCells];
            Arrays.fill(distances, -1);

            int startNode = totalCells - 1;
            distances[startNode] = 0;

            Deque<Integer> queue = new ArrayDeque<>();
            queue.add(startNode);

            while (!queue.isEmpty()) {
                int u = queue.poll();
                for (int v : adj.get(u)) {
                    if (distances[v] == -1) {
                        distances[v] = distances[u] + 1;
                        queue.add(v);
                    }
                }
            }
            return distances;
        }

        private String validate(char[][] grid, int rows, int cols, int[] distances) {
            int totalCells = rows * cols;
            for (int i = 0; i < totalCells; i++) {
                int r = i / cols;
                int c = i % cols;
                char cell = grid[r][c];

                if (cell == BLOCKER && distances[i] != -1) {
                    return "No";
                }
                if (cell == GOAL && distances[i] == -1) {
                    return "No";
                }
            }
            return "Yes";
        }

        private boolean isValid(int r, int c, int rows, int cols) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }
    }

    static class InputReader {
        private final InputStream stream;
        private final byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        public int read() {
            if (numChars == -1) {
                throw new InputMismatchException();
            }

            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0) {
                    return -1;
                }
            }

            return buf[curChar++];
        }

        public int nextInt() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }

            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }

            int res = 0;
            do {
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                res *= 10;
                res += c & 15;
                c = read();
            } while (!isSpaceChar(c));

            return res * sgn;
        }

        public String next() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }

            StringBuilder res = new StringBuilder();
            do {
                res.appendCodePoint(c);
                c = read();
            } while (!isSpaceChar(c));

            return res.toString();
        }

        public boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }
    }

    static class OutputWriter {
        private final PrintWriter writer;

        public OutputWriter(OutputStream outputStream) {
            writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(outputStream)));
        }

        public OutputWriter(Writer writer) {
            this.writer = new PrintWriter(writer);
        }

        public void print(Object... objects) {
            for (int i = 0; i < objects.length; i++) {
                if (i != 0) {
                    writer.print(' ');
                }
                writer.print(objects[i]);
            }
        }

        public void println(Object... objects) {
            print(objects);
            writer.println();
        }

        public void close() {
            writer.close();
        }
    }
}

import java.io.*;
import java.util.*;

public class Solution {

    // Direction vectors for moving right, left, down, up
    private static final int[] DR = {0, 0, 1, -1};
    private static final int[] DC = {1, -1, 0, 0};

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner();
        PrintWriter out = new PrintWriter(System.out);
        try {
            int t = scanner.nextInt();
            while (t-- > 0) {
                int n = scanner.nextInt();
                int m = scanner.nextInt();
                char[][] grid = new char[n][];
                for (int i = 0; i < n; i++) {
                    grid[i] = scanner.next().toCharArray();
                }
                boolean result = solve(n, m, grid);
                out.println(result ? "Yes" : "No");
            }
        } finally {
            out.flush();
            out.close();
        }
    }

    /**
     * Solves a single test case.
     * 1. Blocks '.' cells adjacent to each 'B' by turning them into '#'.
     * 2. Performs BFS from the bottom-right corner to find all reachable cells.
     * 3. Validates that all 'G' cells are reachable and all 'B' cells are unreachable.
     */
    private static boolean solve(int n, int m, char[][] grid) {
        // Phase 1: Block adjacent '.' cells around each 'B'
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < m; c++) {
                if (grid[r][c] == 'B') {
                    block(grid, r, c, n, m);
                }
            }
        }

        // Phase 2: BFS from the bottom-right corner
        Queue<int[]> queue = new LinkedList<>();
        boolean[][] visited = new boolean[n][m];

        if (grid[n - 1][m - 1] == '.') {
            queue.add(new int[]{n - 1, m - 1});
            visited[n - 1][m - 1] = true;
        }

        while (!queue.isEmpty()) {
            int[] current = queue.poll();
            for (int dir = 0; dir < 4; dir++) {
                int nr = current[0] + DR[dir];
                int nc = current[1] + DC[dir];
                if (isValid(nr, nc, n, m) && !visited[nr][nc] && grid[nr][nc] != '#') {
                    visited[nr][nc] = true;
                    queue.add(new int[]{nr, nc});
                }
            }
        }

        // Phase 3: Verify conditions
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < m; c++) {
                char cell = grid[r][c];
                if ((cell == 'G' && !visited[r][c]) || (cell == 'B' && visited[r][c])) {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Marks adjacent '.' cells as '#' (blocked) around the given position.
     */
    private static void block(char[][] grid, int r, int c, int n, int m) {
        for (int dir = 0; dir < 4; dir++) {
            int nr = r + DR[dir];
            int nc = c + DC[dir];
            if (isValid(nr, nc, n, m) && grid[nr][nc] == '.') {
                grid[nr][nc] = '#';
            }
        }
    }

    /**
     * Checks if the given coordinates are within grid bounds.
     */
    private static boolean isValid(int r, int c, int n, int m) {
        return r >= 0 && r < n && c >= 0 && c < m;
    }

    /**
     * Fast I/O helper class for competitive programming.
     */
    static class FastScanner {
        private final BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        private StringTokenizer st = new StringTokenizer("");

        public String next() {
            while (!st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            String token = next();
            if (token == null) throw new NoSuchElementException("Unexpected end of input");
            return Integer.parseInt(token);
        }
    }
}

