/**
 * Solves the grid-based reachability problem.
 */
class GridSolver {
    private static final int[] ROW_DIRS = {1, 0, -1, 0};
    private static final int[] COL_DIRS = {0, 1, 0, -1};

    private static final char EMPTY = '.';
    private static final char BLACK = 'B';
    private static final char GOAL = 'G';
    private static final char BLOCKED = '#';

    private int n, m;
    private char[][] grid;

    /**
     * Orchestrates reading input and running test cases.
     */
    public void run(FastScanner sc, PrintWriter out) {
        boolean runMultipleTestCases = true;
        int t = runMultipleTestCases ? sc.nextInt() : 1;

        for (int tc = 1; tc <= t; tc++) {
            solve(tc, sc, out);
        }
    }

    private void solve(int tc, FastScanner sc, PrintWriter out) {
        n = sc.nextInt();
        m = sc.nextInt();
        grid = new char[n][m];

        for (int i = 0; i < n; i++) {
            grid[i] = sc.next().toCharArray();
        }

        // Pre-process grid: expand black cells and check adjacency constraints
        if (!processGrid()) {
            out.println("No");
            return;
        }

        // Destination must not be blocked
        if (grid[n - 1][m - 1] == BLOCKED) {
            out.println("No");
            return;
        }

        // Check reachability via BFS
        out.println(bfs() ? "Yes" : "No");
    }

    /**
     * Processes the grid according to problem rules:
     * - Adjacent cells to 'B' become '#'
     * - If 'G' is adjacent to 'B', the configuration is invalid
     * - If no 'G' exists, it's automatically valid
     */
    private boolean processGrid() {
        int goalCount = 0;
        boolean adjacentToGoalValid = true;

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == BLACK) {
                    for (int k = 0; k < 4; k++) {
                        int r = i + ROW_DIRS[k];
                        int c = j + COL_DIRS[k];
                        if (isValid(r, c)) {
                            if (grid[r][c] == EMPTY) {
                                grid[r][c] = BLOCKED;
                            } else if (grid[r][c] == GOAL) {
                                adjacentToGoalValid = false;
                            }
                        }
                    }
                } else if (grid[i][j] == GOAL) {
                    goalCount++;
                }
            }
        }

        if (goalCount == 0) return true;
        return adjacentToGoalValid;
    }

    /**
     * Performs BFS from the bottom-right corner to verify all goals are reachable
     * without stepping on black cells.
     */
    private boolean bfs() {
        boolean[][] visited = new boolean[n][m];
        Queue<Point> queue = new ArrayDeque<>();

        queue.add(new Point(n - 1, m - 1));
        visited[n - 1][m - 1] = true;

        while (!queue.isEmpty()) {
            Point curr = queue.poll();

            for (int k = 0; k < 4; k++) {
                int r = curr.row + ROW_DIRS[k];
                int c = curr.col + COL_DIRS[k];

                if (isValid(r, c) && !visited[r][c]) {
                    char cell = grid[r][c];
                    if (cell == GOAL || cell == EMPTY) {
                        visited[r][c] = true;
                        queue.add(new Point(r, c));
                    } else if (cell == BLACK) {
                        return false;
                    }
                    // BLOCKED cells are implicitly ignored (act as walls)
                }
            }
        }

        // Ensure every goal cell was reached
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == GOAL && !visited[i][j]) {
                    return false;
                }
            }
        }
        return true;
    }

    private boolean isValid(int r, int c) {
        return r >= 0 && c >= 0 && r < n && c < m;
    }

    /** Simple immutable coordinate container */
    private static class Point {
        final int row, col;
        Point(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }
}

/**
 * High-performance input scanner for competitive programming.
 */
class FastScanner {
    private final InputStream in;
    private final byte[] buffer = new byte[1024 * 8];
    private int ptr = 0;
    private int buflen = 0;

    public FastScanner(InputStream in) {
        this.in = in;
    }

    private boolean hasNextByte() {
        if (ptr < buflen) return true;
        ptr = 0;
        try { buflen = in.read(buffer); } 
        catch (IOException e) { throw new RuntimeException(e); }
        return buflen > 0;
    }

    private int readByte() {
        if (hasNextByte()) return buffer[ptr++];
        return -1;
    }

    private static boolean isPrintableChar(int c) {
        return c >= 33 && c <= 126;
    }

    public String next() {
        if (!hasNextByte()) throw new NoSuchElementException();
        StringBuilder sb = new StringBuilder();
        int b = readByte();
        while (isPrintableChar(b)) {
            sb.appendCodePoint(b);
            b = readByte();
        }
        return sb.toString();
    }

    public int nextInt() {
        long nl = nextLong();
        if (nl < Integer.MIN_VALUE || nl > Integer.MAX_VALUE) throw new NumberFormatException();
        return (int) nl;
    }

    public long nextLong() {
        long n = 0;
        boolean minus = false;
        int b = readByte();
        if (b == '-') { minus = true; b = readByte(); }
        if (b < '0' || '9' < b) throw new NumberFormatException();

        while (true) {
            if ('0' <= b && b <= '9') {
                n *= 10;
                n += b - '0';
            } else if (b == -1 || !isPrintableChar(b)) {
                return minus ? -n : n;
            } else {
                throw new NumberFormatException();
            }
            b = readByte();
        }
    }
}

/**
 * Mathematical utilities commonly used in algorithmic problems.
 */
class MathUtils {
    private static final int MOD = 1_000_000_007;

    public static long pow(long a, long b) {
        if (b == 0 || a == 1) return 1;
        long res = 1;
        for (long p = b; p > 0; p >>= 1) {
            if ((p & 1) == 1) res = (res * a) % MOD;
            a = (a * a) % MOD;
        }
        return res;
    }

    public static long inv(long x) {
        long res = 1;
        for (long p = MOD - 2; p > 0; p >>= 1) {
            if ((p & 1) == 1) res = (res * x) % MOD;
            x = (x * x) % MOD;
        }
        return res;
    }

    public static long gcd(long a, long b) { return b == 0 ? a : gcd(b, a % b); }
    public static int gcd(int a, int b) { return b == 0 ? a : gcd(b, a % b); }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.OutputStream;
import java.io.PrintWriter;
import java.util.ArrayDeque;
import java.util.Arrays;
import java.util.Deque;
import java.util.StringTokenizer;

public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        FastScanner in = new FastScanner(inputStream);
        PrintWriter out = new PrintWriter(outputStream);

        TaskD solver = new TaskD();
        solver.solve(in, out);

        out.close();
    }

    static class TaskD {
        // Named constants for maintainability and readability
        private static final int INF = 1 << 30;
        private static final char WALL = '#';
        private static final char EMPTY = '.';
        private static final char BLACK = 'B';
        private static final char GREEN = 'G';

        public void solve(FastScanner in, PrintWriter out) {
            int testCases = in.nextInt();
            while (testCases-- > 0) {
                int rows = in.nextInt();
                int cols = in.nextInt();
                char[][] grid = readGrid(in, rows);

                applyBlackWallEffect(grid, rows, cols);
                int[][] distances = runBFS(grid, rows, cols);
                boolean result = validateResult(grid, distances, rows, cols);

                out.println(result ? "Yes" : "No");
            }
        }

        private char[][] readGrid(FastScanner in, int rows) {
            char[][] grid = new char[rows][];
            for (int i = 0; i < rows; i++) {
                grid[i] = in.next().toCharArray();
            }
            return grid;
        }

        private void applyBlackWallEffect(char[][] grid, int rows, int cols) {
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j] == BLACK) {
                        setWallIfEmpty(i - 1, j, grid, rows, cols);
                        setWallIfEmpty(i, j - 1, grid, rows, cols);
                        setWallIfEmpty(i + 1, j, grid, rows, cols);
                        setWallIfEmpty(i, j + 1, grid, rows, cols);
                    }
                }
            }
        }

        private void setWallIfEmpty(int x, int y, char[][] grid, int rows, int cols) {
            if (isInside(x, y, rows, cols) && grid[x][y] == EMPTY) {
                grid[x][y] = WALL;
            }
        }

        private int[][] runBFS(char[][] grid, int rows, int cols) {
            int[][] distances = new int[rows][cols];
            for (int[] row : distances) {
                Arrays.fill(row, INF);
            }

            int startRow = rows - 1;
            int startCol = cols - 1;

            // If the starting position is blocked, all distances remain INF
            if (grid[startRow][startCol] != WALL) {
                distances[startRow][startCol] = 0;
            } else {
                return distances;
            }

            Deque<int[]> queue = new ArrayDeque<>();
            queue.addLast(new int[]{startRow, startCol});

            int[] dr = {-1, 0, 1, 0};
            int[] dc = {0, 1, 0, -1};

            while (!queue.isEmpty()) {
                int[] curr = queue.removeFirst();
                int r = curr[0];
                int c = curr[1];

                for (int i = 0; i < 4; i++) {
                    int nr = r + dr[i];
                    int nc = c + dc[i];

                    if (isInside(nr, nc, rows, cols)
                            && distances[nr][nc] == INF
                            && grid[nr][nc] != WALL) {
                        distances[nr][nc] = distances[r][c] + 1;
                        queue.addLast(new int[]{nr, nc});
                    }
                }
            }
            return distances;
        }

        private boolean validateResult(char[][] grid, int[][] distances, int rows, int cols) {
            boolean allGoalReachable = true;
            boolean noBlackReachable = true;

            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j] == GREEN && distances[i][j] == INF) {
                        allGoalReachable = false;
                    }
                    if (grid[i][j] == BLACK && distances[i][j] != INF) {
                        noBlackReachable = false;
                    }
                }
            }
            return allGoalReachable && noBlackReachable;
        }

        private boolean isInside(int x, int y, int rows, int cols) {
            return x >= 0 && y >= 0 && x < rows && y < cols;
        }
    }

    static class FastScanner {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastScanner(InputStream inputStream) {
            this.reader = new BufferedReader(new InputStreamReader(inputStream));
            this.tokenizer = new StringTokenizer("");
        }

        public String next() {
            while (!tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) {
                        return null;
                    }
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            String s = next();
            if (s == null) {
                throw new RuntimeException("Unexpected end of input");
            }
            return Integer.parseInt(s);
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayDeque;
import java.util.Queue;

/**
 * Refactored version of the Grid Path Solver.
 * 
 * Key Improvements:
 * 1. Class Naming: Renamed 'D' to 'GridPathSolver' for clarity.
 * 2. Input Parsing: Fixed a critical bug in the original 'split("")' logic which caused 
 *    IndexOutOfBoundsException. Used 'toCharArray()' or 'charAt()' for robust character reading.
 * 3. Algorithm: Replaced the recursive Depth-First Search (DFS) in 'fillPath' with an 
 *    iterative Breadth-First Search (BFS) using a Queue. This prevents StackOverflowError 
 *    on large grids.
 * 4. Structure: Separated concerns into distinct methods ('processTestCase', 'applyBaddieRules', 'bfs')
 *    to improve readability and maintainability.
 * 5. Cleanup: Removed unused imports (Arrays, HashSet, HashMap) and the unused 'combos' variable.
 * 6. Robustness: Added input validation (trimming, empty line handling) and bounds checking.
 */
public class GridPathSolver {

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));

        String line = br.readLine();
        if (line == null) return;

        int t;
        try {
            t = Integer.parseInt(line.trim());
        } catch (NumberFormatException e) {
            return;
        }

        for (int i = 0; i < t; i++) {
            line = br.readLine();
            // Skip empty lines that might occur between test cases
            while (line != null && line.trim().isEmpty()) {
                line = br.readLine();
            }
            if (line == null) break;

            String[] dims = line.trim().split("\\s+");
            if (dims.length < 2) continue;

            int rows = Integer.parseInt(dims[0]);
            int cols = Integer.parseInt(dims[1]);

            char[][] grid = new char[rows][cols];
            for (int r = 0; r < rows; r++) {
                String rowStr = br.readLine();
                if (rowStr != null) {
                    // Robustly fill the row, handling potential short lines
                    int length = Math.min(rowStr.length(), cols);
                    for (int c = 0; c < length; c++) {
                        grid[r][c] = rowStr.charAt(c);
                    }
                }
            }

            // Process the grid and print result
            if (processTestCase(grid, rows, cols)) {
                System.out.println("Yes");
            } else {
                System.out.println("No");
            }
        }
        System.out.flush();
    }

    /**
     * Orchestrates the logic for a single test case.
     * @return true if a valid path exists to all 'G's, false otherwise.
     */
    private static boolean processTestCase(char[][] grid, int rows, int cols) {
        // Step 1: Apply Baddie rules. 
        // If a Baddie is adjacent to a Goal ('G'), it's an immediate failure.
        // Also, Baddies block adjacent non-Baddie cells (turning them into walls '#').
        if (applyBaddieRules(grid, rows, cols)) {
            return false;
        }

        // Step 2: Find all reachable cells from the bottom-right corner (rows-1, cols-1).
        // Using BFS to avoid recursion depth issues.
        boolean[][] visited = new boolean[rows][cols];
        bfs(grid, rows, cols, rows - 1, cols - 1, visited);

        // Step 3: Verify that every 'G' in the grid has been visited.
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == 'G' && !visited[r][c]) {
                    return false;
                }
            }
        }

        return true;
    }

    /**
     * Scans the grid for Baddies ('B') and applies game rules:
     * 1. If a 'B' is adjacent to 'G', return true (conflict).
     * 2. If a 'B' is adjacent to a non-'B' cell, turn that cell into a wall ('#').
     */
    private static boolean applyBaddieRules(char[][] grid, int rows, int cols) {
        int[] dRow = {-1, 1, 0, 0};
        int[] dCol = {0, 0, -1, 1};

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == 'B') {
                    for (int k = 0; k < 4; k++) {
                        int nr = r + dRow[k];
                        int nc = c + dCol[k];

                        // Check bounds
                        if (nr >= 0 && nr < rows && nc >= 0 && nc < cols) {
                            if (grid[nr][nc] == 'G') {
                                return true; // Conflict detected
                            }
                            // Block the cell if it's not a Baddie itself
                            // (Original logic: if != 'B' set to '#')
                            if (grid[nr][nc] != 'B') {
                                grid[nr][nc] = '#';
                            }
                        }
                    }
                }
            }
        }
        return false;
    }

    /**
     * Iterative Breadth-First Search (BFS) to mark reachable cells.
     * Starts from (startRow, startCol).
     */
    private static void bfs(char[][] grid, int rows, int cols, int startRow, int startCol, boolean[][] visited) {
        // Basic validation for start position
        if (startRow < 0 || startRow >= rows || startCol < 0 || startCol >= cols) return;
        if (grid[startRow][startCol] == '#') return;

        Queue<int[]> queue = new ArrayDeque<>();
        queue.offer(new int[]{startRow, startCol});
        visited[startRow][startCol] = true;

        int[] dRow = {-1, 1, 0, 0};
        int[] dCol = {0, 0, -1, 1};

        while (!queue.isEmpty()) {
            int[] current = queue.poll();
            int r = current[0];
            int c = current[1];

            for (int k = 0; k < 4; k++) {
                int nr = r + dRow[k];
                int nc = c + dCol[k];

                if (nr >= 0 && nr < rows && nc >= 0 && nc < cols) {
                    if (!visited[nr][nc] && grid[nr][nc] != '#') {
                        visited[nr][nc] = true;
                        queue.offer(new int[]{nr, nc});
                    }
                }
            }
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Refactored solution for grid traversal problem.
 * 
 * Improvements made:
 * 1. Naming: Descriptive variable and method names (e.g., 'rows', 'cols', 'solveTestCase').
 * 2. Structure: Separated logic into distinct methods (solve, mark, traverse, validate).
 * 3. State: Removed global mutable state (mat, vis) in favor of local variables passed as arguments.
 * 4. Algorithm: Replaced recursive DFS with iterative BFS to prevent StackOverflowError on large grids.
 * 5. Constants: Used constants for magic characters ('B', 'G', '.', '#') to improve readability.
 * 6. Robustness: Better exception handling and resource management (try-with-resources pattern logic).
 */
public class Main {

    // Constants for grid characters to improve readability
    private static final char CHAR_BLUE = 'B';
    private static final char CHAR_GREEN = 'G';
    private static final char CHAR_EMPTY = '.';
    private static final char CHAR_BLOCKED = '#';

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner();
        PrintWriter out = new PrintWriter(System.out);

        try {
            Main solver = new Main();
            solver.run(scanner, out);
        } catch (Exception e) {
            // In a production environment, log the error. 
            // For competitive programming style, we might just ignore or print stack trace.
            e.printStackTrace();
        } finally {
            out.flush();
        }
    }

    public void run(FastScanner scanner, PrintWriter out) {
        // Read number of test cases safely
        String token = scanner.next();
        if (token == null) return;
        int numTestCases = Integer.parseInt(token);

        while (numTestCases-- > 0) {
            int rows = scanner.nextInt();
            int cols = scanner.nextInt();

            // Process the current test case
            boolean result = solveTestCase(rows, cols, scanner);
            out.println(result ? "Yes" : "No");
        }
    }

    private boolean solveTestCase(int rows, int cols, FastScanner scanner) {
        // 1. Read the grid
        char[][] grid = new char[rows][];
        for (int i = 0; i < rows; i++) {
            String rowStr = scanner.next();
            if (rowStr != null) {
                grid[i] = rowStr.toCharArray();
            } else {
                grid[i] = new char[0]; // Handle unexpected EOF gracefully
            }
        }

        // 2. Mark neighbors of 'B' cells as blocked ('#')
        markBlockedNeighbors(grid, rows, cols);

        // 3. Perform traversal (BFS) starting from bottom-right (rows-1, cols-1)
        // Using BFS instead of recursion to prevent StackOverflowError on large grids
        boolean[][] visited = new boolean[rows][cols];
        bfsTraversal(grid, rows, cols, visited);

        // 4. Validate the result
        return validate(grid, visited, rows, cols);
    }

    private void markBlockedNeighbors(char[][] grid, int rows, int cols) {
        for (int r = 0; r < rows; r++) {
            // Safety check for ragged arrays
            if (grid[r] == null) continue;

            for (int c = 0; c < cols; c++) {
                if (c >= grid[r].length) break;

                if (grid[r][c] == CHAR_BLUE) {
                    // Mark all 4 adjacent cells as blocked if they are within bounds and empty
                    if (r > 0 && grid[r - 1][c] == CHAR_EMPTY) grid[r - 1][c] = CHAR_BLOCKED;
                    if (r < rows - 1 && grid[r + 1][c] == CHAR_EMPTY) grid[r + 1][c] = CHAR_BLOCKED;
                    if (c > 0 && grid[r][c - 1] == CHAR_EMPTY) grid[r][c - 1] = CHAR_BLOCKED;
                    if (c < cols - 1 && grid[r][c + 1] == CHAR_EMPTY) grid[r][c + 1] = CHAR_BLOCKED;
                }
            }
        }
    }

    private void bfsTraversal(char[][] grid, int rows, int cols, boolean[][] visited) {
        // Queue for BFS: stores coordinates as int[]{row, col}
        Queue<int[]> queue = new ArrayDeque<>();

        // Starting position: bottom-right corner
        int startR = rows - 1;
        int startC = cols - 1;

        // Check if start position is valid and not blocked
        if (isValid(startR, startC, rows, cols) && grid[startR][startC] != CHAR_BLOCKED) {
            visited[startR][startC] = true;
            queue.add(new int[]{startR, startC});
        }

        int[] dr = {-1, 1, 0, 0}; // Direction vectors for Up, Down, Left, Right
        int[] dc = {0, 0, -1, 1};

        while (!queue.isEmpty()) {
            int[] current = queue.poll();
            int r = current[0];
            int c = current[1];

            // Explore neighbors
            for (int i = 0; i < 4; i++) {
                int nr = r + dr[i];
                int nc = c + dc[i];

                if (isValid(nr, nc, rows, cols) 
                    && !visited[nr][nc] 
                    && grid[nr][nc] != CHAR_BLOCKED) {

                    visited[nr][nc] = true;
                    queue.add(new int[]{nr, nc});
                }
            }
        }
    }

    private boolean validate(char[][] grid, boolean[][] visited, int rows, int cols) {
        for (int r = 0; r < rows; r++) {
            if (grid[r] == null) continue;
            for (int c = 0; c < cols; c++) {
                if (c >= grid[r].length) break;

                char cell = grid[r][c];
                boolean isVisited = visited[r][c];

                // If a Blue cell is visited, it's a failure (we stepped on a Blue cell)
                if (cell == CHAR_BLUE && isVisited) {
                    return false;
                }
                // If a Green cell is NOT visited, it's a failure (we couldn't reach it)
                else if (cell == CHAR_GREEN && !isVisited) {
                    return false;
                }
            }
        }
        return true;
    }

    private boolean isValid(int r, int c, int rows, int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /**
     * FastScanner class for efficient input reading.
     */
    static class FastScanner {
        BufferedReader reader;
        StringTokenizer tokenizer;

        public FastScanner() {
            reader = new BufferedReader(new InputStreamReader(System.in), 32768);
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            String s = next();
            if (s == null) throw new RuntimeException("End of input");
            return Integer.parseInt(s);
        }
    }
}

import java.util.Scanner;
import java.util.Queue;
import java.util.LinkedList;

/**
 * Refactored Maze Solver.
 * 
 * This version improves maintainability and code quality by:
 * 1. Using descriptive variable and method names.
 * 2. Separating concerns (input reading, logic processing, traversal).
 * 3. Replacing recursive DFS with iterative BFS to prevent StackOverflowError on large grids.
 * 4. Using a boolean array to track blocked cells instead of mutating the grid directly.
 * 5. Using constants for grid characters to improve readability.
 */
public class MazeSolver {

    // Constants representing grid elements
    private static final char EMPTY_CELL = '.';
    private static final char BLOCKED_CELL = '#';
    private static final char GOAL = 'G';
    private static final char BALL = 'B';

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        // Read number of test cases
        if (scanner.hasNextInt()) {
            int t = scanner.nextInt();
            while (t-- > 0) {
                solveTestCase(scanner);
            }
        }
        scanner.close();
    }

    private static void solveTestCase(Scanner scanner) {
        int n = scanner.nextInt();
        int m = scanner.nextInt();

        char[][] grid = new char[n][m];

        // Read the maze grid
        // Using charAt loop ensures rectangular array even if input string length varies
        for (int i = 0; i < n; i++) {
            String row = scanner.next();
            for (int j = 0; j < m; j++) {
                grid[i][j] = row.charAt(j);
            }
        }

        // Track blocked cells (walls) and ball constraints
        // Using a separate boolean array avoids mutating the original grid
        boolean[][] isBlocked = new boolean[n][m];
        boolean goalAdjacentToBall = false;
        int totalGoals = 0;

        // 1. Initialize blocked cells (existing walls) and count total goals
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                char cell = grid[i][j];
                if (cell == BLOCKED_CELL) {
                    isBlocked[i][j] = true;
                } else if (cell == GOAL) {
                    totalGoals++;
                }
            }
        }

        // 2. Process Ball constraints
        // A Ball blocks adjacent empty cells.
        // If a Ball is adjacent to a Goal, the condition fails.
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == BALL) {
                    if (hasAdjacentGoal(i, j, n, m, grid)) {
                        goalAdjacentToBall = true;
                    }
                    blockAdjacentEmptyCells(i, j, n, m, grid, isBlocked);
                }
            }
        }

        // 3. Traverse to find reachable goals from bottom-right (n-1, m-1)
        int reachableGoals = 0;
        // If a goal is adjacent to a ball, the condition fails immediately.
        // We can skip traversal or just run it (result will be No anyway).
        if (!goalAdjacentToBall) {
            reachableGoals = countReachableGoals(grid, isBlocked, n - 1, m - 1, n, m);
        }

        // 4. Output result
        // Condition: All goals must be reachable AND no goal adjacent to a ball
        if (totalGoals == reachableGoals && !goalAdjacentToBall) {
            System.out.println("Yes");
        } else {
            System.out.println("No");
        }
    }

    /**
     * Checks if a Ball at (r, c) has any adjacent Goal cells.
     */
    private static boolean hasAdjacentGoal(int r, int c, int n, int m, char[][] grid) {
        int[] dRow = {-1, 1, 0, 0};
        int[] dCol = {0, 0, -1, 1};

        for (int k = 0; k < 4; k++) {
            int nr = r + dRow[k];
            int nc = c + dCol[k];
            if (isValid(nr, nc, n, m) && grid[nr][nc] == GOAL) {
                return true;
            }
        }
        return false;
    }

    /**
     * Marks adjacent empty cells as blocked if they are neighbors of a Ball at (r, c).
     */
    private static void blockAdjacentEmptyCells(int r, int c, int n, int m, char[][] grid, boolean[][] isBlocked) {
        int[] dRow = {-1, 1, 0, 0};
        int[] dCol = {0, 0, -1, 1};

        for (int k = 0; k < 4; k++) {
            int nr = r + dRow[k];
            int nc = c + dCol[k];
            if (isValid(nr, nc, n, m) && grid[nr][nc] == EMPTY_CELL) {
                isBlocked[nr][nc] = true;
            }
        }
    }

    /**
     * Checks if coordinates are within grid bounds.
     */
    private static boolean isValid(int r, int c, int n, int m) {
        return r >= 0 && r < n && c >= 0 && c < m;
    }

    /**
     * Uses BFS to count reachable Goal cells starting from (startR, startC).
     */
    private static int countReachableGoals(char[][] grid, boolean[][] isBlocked, int startR, int startC, int n, int m) {
        // If start position is blocked, no goals are reachable
        if (isBlocked[startR][startC]) {
            return 0;
        }

        int count = 0;
        boolean[][] visited = new boolean[n][m];
        Queue<int[]> queue = new LinkedList<>();

        queue.offer(new int[]{startR, startC});
        visited[startR][startC] = true;

        int[] dRow = {-1, 1, 0, 0};
        int[] dCol = {0, 0, -1, 1};

        while (!queue.isEmpty()) {
            int[] current = queue.poll();
            int r = current[0];
            int c = current[1];

            if (grid[r][c] == GOAL) {
                count++;
            }

            for (int k = 0; k < 4; k++) {
                int nr = r + dRow[k];
                int nc = c + dCol[k];

                if (isValid(nr, nc, n, m) && !isBlocked[nr][nc] && !visited[nr][nc]) {
                    visited[nr][nc] = true;
                    queue.offer(new int[]{nr, nc});
                }
            }
        }
        return count;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayDeque;
import java.util.Deque;
import java.util.StringTokenizer;

/**
 * Solves grid path problems where 'B' cells block adjacent '.' cells,
 * and we must verify reachability from the bottom-right corner to all 'G' cells.
 */
public class GridPathSolver {

    private static final int[] DX = {-1, 1, 0, 0};
    private static final int[] DY = {0, 0, -1, 1};

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner();
        int testCases = scanner.nextInt();

        for (int t = 0; t < testCases; t++) {
            int n = scanner.nextInt();
            int m = scanner.nextInt();
            char[][] grid = new char[n][m];

            for (int i = 0; i < n; i++) {
                grid[i] = scanner.next().toCharArray();
            }

            solve(n, m, grid);
        }
    }

    /**
     * Orchestrates the solution for a single test case.
     */
    private static void solve(int n, int m, char[][] grid) {
        markBlockedCells(grid, n, m);
        boolean[][] reachable = findReachableCells(grid, n, m);
        System.out.println(isValidConfiguration(grid, reachable, n, m) ? "Yes" : "No");
    }

    /**
     * Marks '.' cells adjacent to 'B' cells as blocked ('#').
     */
    private static void markBlockedCells(char[][] grid, int n, int m) {
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == 'B') {
                    for (int dir = 0; dir < 4; dir++) {
                        int ni = i + DX[dir];
                        int nj = j + DY[dir];
                        if (isValidCell(ni, nj, n, m) && grid[ni][nj] == '.') {
                            grid[ni][nj] = '#';
                        }
                    }
                }
            }
        }
    }

    /**
     * Performs DFS from the bottom-right corner to find all reachable cells.
     */
    private static boolean[][] findReachableCells(char[][] grid, int n, int m) {
        boolean[][] visited = new boolean[n][m];

        if (grid[n - 1][m - 1] == '#') {
            return visited;
        }

        Deque<Position> stack = new ArrayDeque<>();
        stack.push(new Position(n - 1, m - 1));
        visited[n - 1][m - 1] = true;

        while (!stack.isEmpty()) {
            Position current = stack.pop();
            for (int dir = 0; dir < 4; dir++) {
                int ni = current.x + DX[dir];
                int nj = current.y + DY[dir];

                if (isValidCell(ni, nj, n, m) && grid[ni][nj] != '#' && !visited[ni][nj]) {
                    visited[ni][nj] = true;
                    stack.push(new Position(ni, nj));
                }
            }
        }
        return visited;
    }

    /**
     * Validates the configuration: all 'G' cells must be reachable,
     * and no 'B' cells should be reachable.
     */
    private static boolean isValidConfiguration(char[][] grid, boolean[][] visited, int n, int m) {
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                char cell = grid[i][j];
                if ((cell == 'G' && !visited[i][j]) || (cell == 'B' && visited[i][j])) {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Checks if coordinates are within grid boundaries.
     */
    private static boolean isValidCell(int x, int y, int n, int m) {
        return x >= 0 && x < n && y >= 0 && y < m;
    }

    /**
     * Fast input reader for competitive programming scenarios.
     */
    private static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) {
                        throw new IOException("Unexpected end of input");
                    }
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input", e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }
    }

    /**
     * Represents a 2D grid coordinate.
     */
    private static class Position {
        final int x, y;

        Position(int x, int y) {
            this.x = x;
            this.y = y;
        }
    }
}

import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

public class Main {
    // Constants for grid characters to avoid magic strings
    private static final char GOAL = 'G';
    private static final char BAD = 'B';
    private static final char BLOCKED = '#';

    // Instance variables to replace static fields, improving testability and state management
    private char[][] grid;
    private int rows;
    private int cols;
    private int goalsRemaining;

    public static void main(String[] args) {
        Main solver = new Main();
        Scanner scanner = new Scanner(System.in);

        // Read number of test cases
        if (scanner.hasNextInt()) {
            int testCases = scanner.nextInt();
            while (testCases-- > 0) {
                solver.solveTestCase(scanner);
            }
        }
        scanner.close();
    }

    /**
     * Processes a single test case.
     */
    private void solveTestCase(Scanner scanner) {
        // 1. Read dimensions
        if (!scanner.hasNextInt()) return;
        this.rows = scanner.nextInt();
        this.cols = scanner.nextInt();

        // Initialize grid
        this.grid = new char[this.rows][this.cols];
        this.goalsRemaining = 0;

        // List to store coordinates of 'B' (Bad) characters
        List<int[]> badPositions = new ArrayList<>();

        // 2. Read grid data
        for (int r = 0; r < rows; r++) {
            String line = scanner.next();
            for (int c = 0; c < cols; c++) {
                char ch = line.charAt(c);
                grid[r][c] = ch;

                if (ch == GOAL) {
                    goalsRemaining++;
                } else if (ch == BAD) {
                    badPositions.add(new int[]{r, c});
                }
            }
        }

        // 3. Check if the destination (bottom-right) is blocked by 'B'
        // Note: Added bounds check for safety, though inputs usually guarantee n, m >= 1
        if (rows > 0 && cols > 0 && grid[rows - 1][cols - 1] == BAD) {
            System.out.println("No");
            return;
        }

        // 4. Process 'B' zones: mark neighbors as blocked and check for conflicts
        if (hasConflictWithBadZones(badPositions)) {
            System.out.println("No");
            return;
        }

        // 5. Traverse grid starting from bottom-right to collect goals
        traverseAndCollect(rows - 1, cols - 1);

        // 6. Output result
        if (goalsRemaining == 0) {
            System.out.println("Yes");
        } else {
            System.out.println("No");
        }
    }

    /**
     * Checks neighbors of all 'B' positions.
     * Returns true if a 'G' is adjacent to a 'B' (conflict).
     * Marks non-'B' neighbors as blocked ('#').
     */
    private boolean hasConflictWithBadZones(List<int[]> badPositions) {
        // Direction vectors: Up, Left, Down, Right
        int[] dRow = {-1, 0, 1, 0};
        int[] dCol = {0, -1, 0, 1};

        for (int[] pos : badPositions) {
            int r = pos[0];
            int c = pos[1];

            for (int i = 0; i < 4; i++) {
                int nr = r + dRow[i];
                int nc = c + dCol[i];

                // Check bounds
                if (nr >= 0 && nr < rows && nc >= 0 && nc < cols) {
                    if (grid[nr][nc] == GOAL) {
                        return true; // Conflict detected: Goal adjacent to Bad
                    }
                    if (grid[nr][nc] != BAD) {
                        grid[nr][nc] = BLOCKED; // Mark as blocked
                    }
                }
            }
        }
        return false;
    }

    /**
     * Recursive DFS to traverse the grid and collect 'G' characters.
     * Marks visited cells as blocked to prevent cycles and re-processing.
     */
    private void traverseAndCollect(int r, int c) {
        // Base cases
        if (goalsRemaining == 0) return; // Optimization: all goals collected
        if (r < 0 || r >= rows || c < 0 || c >= cols) return; // Out of bounds
        if (grid[r][c] == BLOCKED) return; // Already visited or blocked

        // Collect goal if present
        if (grid[r][c] == GOAL) {
            goalsRemaining--;
        }

        // Mark current cell as visited/blocked
        grid[r][c] = BLOCKED;

        // Recurse in all 4 directions
        traverseAndCollect(r - 1, c);
        traverseAndCollect(r + 1, c);
        traverseAndCollect(r, c - 1);
        traverseAndCollect(r, c + 1);
    }
}

import java.io.BufferedReader;
