/**
 * Refactored Maze Solver.
 * 
 * Improvements:
 * 1. Object-Oriented Design: Encapsulates state and logic within a class (MazeSolver).
 * 2. Readability: Uses descriptive variable and method names (e.g., 'grid' instead of 'maze', 'floodFill' instead of 'ff').
 * 3. Performance: Replaced recursive DFS with iterative DFS using a Stack to prevent StackOverflowError on large grids.
 * 4. Input/Output: Uses BufferedReader and StringTokenizer for faster input parsing compared to Scanner.
 * 5. Maintainability: Separated concerns into distinct methods (parsing, logic, checks) and removed static mutable state.
 */
public class MazeSolver {

    // Directions: Up, Right, Down, Left
    private static final int[] DR = {-1, 0, 1, 0};
    private static final int[] DC = {0, 1, 0, -1};

    private char[][] grid;
    private int rows;
    private int cols;

    public static void main(String[] args) {
        MazeSolver solver = new MazeSolver();
        solver.run();
    }

    public void run() {
        FastScanner scanner = new FastScanner();
        try {
            // Read number of test cases
            if (!scanner.hasMoreTokens()) return;
            int t = scanner.nextInt();

            while (t-- > 0) {
                solveTestCase(scanner);
            }
        } catch (Exception e) {
            // In a production environment, handle exceptions appropriately.
            // For competitive programming style problems, we usually ignore or crash.
        }
    }

    private void solveTestCase(FastScanner scanner) {
        try {
            int n = scanner.nextInt();
            int m = scanner.nextInt();
            rows = n;
            cols = m;
            grid = new char[n][m];

            for (int i = 0; i < n; i++) {
                String line = scanner.next();
                grid[i] = line.toCharArray();
            }

            // The original code starts the flood fill from (n-1, m-1).
            // We preserve this behavior as it appears to be specific to the problem logic.
            int startR = n - 1;
            int startC = m - 1;

            // 1. Initial Reachability Check
            // Check if Goal ('G') is reachable from Start on the original grid.
            boolean[][] initialReachability = floodFill(startR, startC);
            if (!isGoalReachable(initialReachability)) {
                System.out.println("No");
                return;
            }

            // 2. Check 'B' constraints
            // Iterate through the grid to find 'B's.
            // We must process them in the order they appear (row-major) because
            // the grid state (modifications) persists between checks.
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    // Check if current cell is 'B' and was reachable from Start initially.
                    // Note: 'B' is not '.', so it won't be turned into a wall by previous steps.
                    if (grid[i][j] == 'B' && initialReachability[i][j]) {

                        // Simulate 'B' blocking the area
                        markBlockedArea(i, j);

                        // Recompute reachability on the modified grid
                        boolean[][] currentReachability = floodFill(startR, startC);

                        // Check conditions:
                        // 1. Is the 'B' cell itself still reachable? (corresponds to ffd[i][j])
                        // 2. Is the Goal still reachable? (corresponds to !checkgp())
                        if (currentReachability[i][j] || !isGoalReachable(currentReachability)) {
                            System.out.println("No");
                            return;
                        }
                    }
                }
            }

            System.out.println("Yes");

        } catch (Exception e) {
            // Handle input errors if necessary
        }
    }

    /**
     * Performs a flood fill (DFS) from the start position to determine reachable cells.
     * Respects walls ('#') in the grid.
     * 
     * @param startR Starting row
     * @param startC Starting column
     * @return A boolean matrix where true indicates the cell is reachable.
     */
    private boolean[][] floodFill(int startR, int startC) {
        boolean[][] visited = new boolean[rows][cols];
        Deque<int[]> stack = new ArrayDeque<>();

        // Validate start position
        if (isValid(startR, startC) && grid[startR][startC] != '#') {
            visited[startR][startC] = true;
            stack.push(new int[]{startR, startC});
        }

        while (!stack.isEmpty()) {
            int[] current = stack.pop();
            int r = current[0];
            int c = current[1];

            // Explore neighbors
            for (int d = 0; d < 4; d++) {
                int nr = r + DR[d];
                int nc = c + DC[d];

                if (isValid(nr, nc) && !visited[nr][nc] && grid[nr][nc] != '#') {
                    visited[nr][nc] = true;
                    stack.push(new int[]{nr, nc});
                }
            }
        }
        return visited;
    }

    /**
     * Simulates the 'B' cell consuming the maze.
     * It traverses from the 'B' position.
     * - If it encounters a '.', it turns it into a wall ('#').
     * - If it encounters another non-wall, non-'.' cell, it continues traversal.
     * This logic matches the recursive `bpff` function in the original code.
     * 
     * @param startR Row of 'B'
     * @param startC Column of 'B'
     */
    private void markBlockedArea(int startR, int startC) {
        boolean[][] visited = new boolean[rows][cols];
        Deque<int[]> stack = new ArrayDeque<>();

        // Start traversal from 'B'
        // Note: 'B' is not '.', so it won't be turned into '#'.
        visited[startR][startC] = true;
        stack.push(new int[]{startR, startC});

        while (!stack.isEmpty()) {
            int[] current = stack.pop();
            int r = current[0];
            int c = current[1];

            for (int d = 0; d < 4; d++) {
                int nr = r + DR[d];
                int nc = c + DC[d];

                if (isValid(nr, nc) && grid[nr][nc] != '#') {
                    if (grid[nr][nc] == '.') {
                        // Turn '.' into wall
                        grid[nr][nc] = '#';
                        // Do NOT recurse into '.' cells based on original logic
                    } else {
                        // If not '.', continue traversal if not visited
                        if (!visited[nr][nc]) {
                            visited[nr][nc] = true;
                            stack.push(new int[]{nr, nc});
                        }
                    }
                }
            }
        }
    }

    /**
     * Checks if the Goal ('G') is reachable based on the provided reachability matrix.
     * Returns false if any 'G' cell is not marked as reachable.
     * 
     * @param reachability Matrix from floodFill
     * @return true if all 'G' cells are reachable, false otherwise.
     */
    private boolean isGoalReachable(boolean[][] reachability) {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == 'G' && !reachability[i][j]) {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Checks if coordinates are within grid bounds.
     */
    private boolean isValid(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /**
     * Helper class for fast input reading.
     */
    private static class FastScanner {
        BufferedReader br;
        StringTokenizer st;

        public FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    e.printStackTrace();
                    return null;
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            String s = next();
            if (s == null) throw new RuntimeException("End of input");
            return Integer.parseInt(s);
        }

        boolean hasMoreTokens() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return false;
                    if (line.trim().isEmpty()) continue; // Skip empty lines
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    return false;
                }
            }
            return true;
        }
    }
}

import java.io.*;
import java.util.*;

public class Codechef {
    // Magic characters replaced with named constants for clarity
    private static final char BLOCKED = '#';
    private static final char BOMB = 'B';
    private static final char GOAL = 'G';
    private static final char EMPTY = '.';
    private static final int[][] DIRECTIONS = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};

    public static void main(String[] args) {
        // Local I/O resources instead of static fields to improve testability and safety
        FastReader sc = new FastReader(System.in);
        PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out));
        try {
            int testCases = sc.nextInt();
            for (int t = 0; t < testCases; t++) {
                int n = sc.nextInt();
                int m = sc.nextInt();
                char[][] grid = new char[n][m];
                for (int i = 0; i < n; i++) {
                    grid[i] = sc.next().toCharArray();
                }
                boolean result = solve(grid, n, m);
                out.println(result ? "Yes" : "No");
            }
        } finally {
            out.flush();
            out.close();
        }
    }

    /**
     * Orchestrates the core logic: marking blocked cells, finding reachable cells,
     * and validating the final conditions.
     */
    private static boolean solve(char[][] grid, int n, int m) {
        boolean[][] blocked = markBlockedCells(grid, n, m);
        boolean[][] visited = findReachableCells(grid, blocked, n, m);
        return validateConditions(grid, visited, n, m);
    }

    /**
     * Identifies cells that become blocked ('#') due to adjacent bombs.
     * Uses a separate boolean array instead of mutating the input grid.
     */
    private static boolean[][] markBlockedCells(char[][] grid, int n, int m) {
        boolean[][] blocked = new boolean[n][m];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == BOMB) {
                    for (int[] dir : DIRECTIONS) {
                        int ni = i + dir[0];
                        int nj = j + dir[1];
                        if (isValid(ni, nj, n, m) && grid[ni][nj] == EMPTY) {
                            blocked[ni][nj] = true;
                        }
                    }
                }
            }
        }
        return blocked;
    }

    /**
     * Performs BFS from the bottom-right corner to find all reachable cells.
     * Uses ArrayDeque for better performance than LinkedList.
     */
    private static boolean[][] findReachableCells(char[][] grid, boolean[][] blocked, int n, int m) {
        boolean[][] visited = new boolean[n][m];
        Queue<Point> queue = new ArrayDeque<>();
        int startR = n - 1;
        int startC = m - 1;

        // Only start BFS if the destination is accessible
        if (grid[startR][startC] == EMPTY && !blocked[startR][startC]) {
            queue.add(new Point(startR, startC));
            visited[startR][startC] = true;
        }

        while (!queue.isEmpty()) {
            Point curr = queue.poll();
            for (int[] dir : DIRECTIONS) {
                int ni = curr.x + dir[0];
                int nj = curr.y + dir[1];
                if (isValid(ni, nj, n, m) && !visited[ni][nj] && !blocked[ni][nj] && grid[ni][nj] != BLOCKED) {
                    queue.add(new Point(ni, nj));
                    visited[ni][nj] = true;
                }
            }
        }
        return visited;
    }

    /**
     * Validates that all goal cells are reachable and no bomb cells are reachable.
     */
    private static boolean validateConditions(char[][] grid, boolean[][] visited, int n, int m) {
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == GOAL && !visited[i][j]) return false;
                if (grid[i][j] == BOMB && visited[i][j]) return false;
            }
        }
        return true;
    }

    /**
     * Checks array bounds efficiently.
     */
    private static boolean isValid(int x, int y, int n, int m) {
        return x >= 0 && x < n && y >= 0 && y < m;
    }

    /**
     * Immutable coordinate class for BFS traversal.
     */
    private static class Point {
        final int x, y;
        Point(int x, int y) {
            this.x = x;
            this.y = y;
        }
    }

    /**
     * Optimized fast input reader for competitive programming.
     */
    public static class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastReader(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input", e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            String token = next();
            if (token == null) throw new NoSuchElementException("End of input");
            return Integer.parseInt(token);
        }
    }
}

import java.io.*;
import java.util.*;

public class Main {

    public static void main(String[] args) {
        // Try-with-resources ensures streams are properly closed and flushed
        try (FastReader in = new FastReader(System.in);
             PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out))) {
            new Main().solve(in, out);
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    public void solve(FastReader in, PrintWriter out) throws IOException {
        int testCount = in.nextInt();
        while (testCount-- > 0) {
            int rows = in.nextInt();
            int cols = in.nextInt();
            in.nextLine(); // Consume the newline after the dimensions

            char[][] grid = new char[rows][cols];
            List<int[]> goodPositions = new ArrayList<>();
            List<int[]> badPositions = new ArrayList<>();

            // Read grid and collect target positions
            for (int r = 0; r < rows; r++) {
                String line = in.nextLine();
                for (int c = 0; c < cols; c++) {
                    char ch = line.charAt(c);
                    grid[r][c] = ch;
                    if (ch == 'G') goodPositions.add(new int[]{r, c});
                    else if (ch == 'B') badPositions.add(new int[]{r, c});
                }
            }

            // Set destination cell
            grid[rows - 1][cols - 1] = 'D';

            // If there are no good positions, the condition is trivially satisfied
            if (goodPositions.isEmpty()) {
                out.println("Yes");
                continue;
            }

            // Work on a copy to prevent mutation during validation
            char[][] blockedGrid = new char[rows][cols];
            for (int r = 0; r < rows; r++) {
                System.arraycopy(grid[r], 0, blockedGrid[r], 0, cols);
            }

            // Validate if all 'B' positions can be safely blocked
            boolean canBlockAll = true;
            for (int[] pos : badPositions) {
                if (!tryBlock(blockedGrid, pos[0], pos[1])) {
                    canBlockAll = false;
                    break;
                }
            }

            if (!canBlockAll) {
                out.println("No");
            } else {
                // Find all reachable cells from 'D' using iterative BFS
                boolean[][] visited = new boolean[rows][cols];
                bfs(blockedGrid, rows - 1, cols - 1, visited);

                // Verify all 'G' positions are reachable
                boolean allGoodReachable = true;
                for (int[] pos : goodPositions) {
                    if (!visited[pos[0]][pos[1]]) {
                        allGoodReachable = false;
                        break;
                    }
                }
                out.println(allGoodReachable ? "Yes" : "No");
            }
        }
        out.flush();
    }

    /**
     * Attempts to block the cross-shaped area around (r, c).
     * Returns false if blocking would overlap with 'G' or 'D'.
     * Modifies the grid in-place to mark blocked cells with '#'.
     */
    private static boolean tryBlock(char[][] grid, int r, int c) {
        // Check vertical cross
        for (int i = Math.max(0, r - 1); i <= Math.min(r + 1, grid.length - 1); i++) {
            if (grid[i][c] == 'G' || grid[i][c] == 'D') return false;
            grid[i][c] = '#';
        }
        // Check horizontal cross
        for (int j = Math.max(0, c - 1); j <= Math.min(c + 1, grid[0].length - 1); j++) {
            if (grid[r][j] == 'G' || grid[r][j] == 'D') return false;
            grid[r][j] = '#';
        }
        return true;
    }

    /**
     * Iterative BFS to mark all reachable cells from the start position.
     * Avoids '#' cells. Uses a visited array to prevent cycles and redundant processing.
     */
    private static void bfs(char[][] grid, int startR, int startC, boolean[][] visited) {
        int rows = grid.length;
        int cols = grid[0].length;
        Queue<int[]> queue = new ArrayDeque<>();
        queue.offer(new int[]{startR, startC});
        visited[startR][startC] = true;

        int[] dr = {-1, 1, 0, 0};
        int[] dc = {0, 0, -1, 1};

        while (!queue.isEmpty()) {
            int[] curr = queue.poll();
            int r = curr[0], c = curr[1];

            for (int k = 0; k < 4; k++) {
                int nr = r + dr[k];
                int nc = c + dc[k];
                if (nr >= 0 && nr < rows && nc >= 0 && nc < cols &&
                    !visited[nr][nc] && grid[nr][nc] != '#') {
                    visited[nr][nc] = true;
                    queue.offer(new int[]{nr, nc});
                }
            }
        }
    }

    /**
     * Fast I/O helper class optimized for competitive programming scenarios.
     */
    static class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastReader(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        String nextLine() {
            String str = "";
            try {
                str = br.readLine();
            } catch (IOException e) {
                e.printStackTrace();
            }
            return str;
        }
    }
}

import java.util.ArrayDeque;
import java.util.Queue;
import java.util.Scanner;

public class Main {

    // Direction vectors for moving up, down, left, right
    private static final int[] DR = {-1, 1, 0, 0};
    private static final int[] DC = {0, 0, -1, 1};

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        if (!scanner.hasNextInt()) {
            return;
        }

        int numTestCases = scanner.nextInt();
        scanner.nextLine(); // Consume the newline character after the integer

        for (int i = 0; i < numTestCases; i++) {
            System.out.println(solveTestCase(scanner));
        }
        scanner.close();
    }

    /**
     * Processes a single test case: reads dimensions and grid, 
     * resolves 'B' blockages, and determines if all 'G' persons are reachable.
     */
    private static String solveTestCase(Scanner scanner) {
        String[] dimensions = scanner.nextLine().trim().split("\\s+");
        int rows = Integer.parseInt(dimensions[0]);
        int cols = Integer.parseInt(dimensions[1]);

        char[][] grid = new char[rows][cols];
        boolean[][] isGood = new boolean[rows][cols];
        int goodPersonCount = 0;

        // Parse and process the grid row by row
        for (int r = 0; r < rows; r++) {
            String line = scanner.nextLine();
            for (int c = 0; c < cols; c++) {
                char cell = line.charAt(c);
                if (cell == 'G') {
                    // Good person: mark as traversable and record position
                    if (grid[r][c] != '#') {
                        grid[r][c] = '.';
                    }
                    isGood[r][c] = true;
                    goodPersonCount++;
                } else if (cell == 'B') {
                    // Bad person: mark adjacent cells as blocked
                    markAdjacentBlocked(grid, r, c, rows, cols);
                } else {
                    // Other characters: copy to grid if not already blocked
                    if (grid[r][c] != '#') {
                        grid[r][c] = cell;
                    }
                }
            }
        }

        // If the destination is blocked, we can only succeed if there are no good persons to save
        if (grid[rows - 1][cols - 1] == '#') {
            return goodPersonCount == 0 ? "Yes" : "No";
        }

        // Perform BFS from the destination to count reachable good persons
        int reachableGoodCount = bfsCountGoodPersons(grid, rows, cols, isGood);

        return reachableGoodCount == goodPersonCount ? "Yes" : "No";
    }

    /**
     * Marks the four adjacent cells of (r, c) as blocked ('#').
     */
    private static void markAdjacentBlocked(char[][] grid, int r, int c, int rows, int cols) {
        for (int d = 0; d < 4; d++) {
            int nr = r + DR[d];
            int nc = c + DC[d];
            if (isValid(nr, nc, rows, cols)) {
                grid[nr][nc] = '#';
            }
        }
    }

    /**
     * Performs a Breadth-First Search starting from the bottom-right corner.
     * Returns the number of 'G' persons reachable via '.' cells.
     */
    private static int bfsCountGoodPersons(char[][] grid, int rows, int cols, boolean[][] isGood) {
        boolean[][] visited = new boolean[rows][cols];
        Queue<int[]> queue = new ArrayDeque<>();

        int startR = rows - 1;
        int startC = cols - 1;
        queue.offer(new int[]{startR, startC});
        visited[startR][startC] = true;

        int count = 0;

        while (!queue.isEmpty()) {
            int[] current = queue.poll();
            int r = current[0];
            int c = current[1];

            // Check if current position contains a good person
            if (isGood[r][c]) {
                count++;
            }

            // Explore valid, unvisited, traversable neighbors
            for (int d = 0; d < 4; d++) {
                int nr = r + DR[d];
                int nc = c + DC[d];

                if (isValid(nr, nc, rows, cols) && !visited[nr][nc] && grid[nr][nc] == '.') {
                    visited[nr][nc] = true;
                    queue.offer(new int[]{nr, nc});
                }
            }
        }
        return count;
    }

    /**
     * Checks if a coordinate is within the grid boundaries.
     */
    private static boolean isValid(int r, int c, int rows, int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }
}

import java.util.LinkedList;
import java.util.Queue;
import java.util.Scanner;

/**
 * Refactored Grid Solver.
 * 
 * Key Improvements:
 * 1. Naming Conventions: Renamed class, methods, and variables to be descriptive (e.g., 'e' -> 'GridSolver', 'ch' -> 'grid').
 * 2. Modularity: Separated logic into distinct methods (processBlackCells, bfs, validateSolution).
 * 3. Readability: Used constants for direction vectors and improved variable names.
 * 4. Maintainability: Encapsulated grid validation and BFS logic, making it easier to test and modify.
 * 5. Code Structure: Removed unused imports and consolidated repetitive logic.
 */
public class GridSolver {

    // Direction vectors: Up, Right, Down, Left
    private static final int[] ROW_DIRS = {-1, 0, 1, 0};
    private static final int[] COL_DIRS = {0, 1, 0, -1};

    /**
     * Represents a coordinate and distance in the grid.
     */
    private static class Point {
        int r, c, dist;

        Point(int r, int c, int dist) {
            this.r = r;
            this.c = c;
            this.dist = dist;
        }
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        // Check if input exists to prevent exceptions on empty input
        if (scanner.hasNextInt()) {
            int t = scanner.nextInt();
            while (t-- > 0) {
                solveTestCase(scanner);
            }
        }
        scanner.close();
    }

    /**
     * Solves a single test case.
     */
    private static void solveTestCase(Scanner scanner) {
        int n = scanner.nextInt();
        int m = scanner.nextInt();
        char[][] grid = new char[n][m];

        // Read the grid
        for (int i = 0; i < n; i++) {
            grid[i] = scanner.next().toCharArray();
        }

        // 1. Process Black Cells: Expand obstacles to adjacent empty cells
        processBlackCells(grid, n, m);

        // 2. Count Green Cells
        int greenCount = countGreenCells(grid, n, m);

        // 3. Determine Result
        if (greenCount == 0) {
            // If no Green cells, condition is trivially satisfied
            System.out.println("Yes");
        } else if (grid[n - 1][m - 1] == '#') {
            // If the destination (bottom-right) is blocked
            System.out.println("No");
        } else {
            // 4. Perform BFS to find reachable cells from bottom-right
            boolean[][] visited = bfs(grid, n, m, n - 1, m - 1);

            // 5. Validate Solution
            // Conditions:
            // - No Black cell should be reachable.
            // - All Green cells must be reachable.
            boolean isSolutionValid = validateSolution(grid, visited, n, m);

            if (isSolutionValid) {
                System.out.println("Yes");
            } else {
                System.out.println("No");
            }
        }
    }

    /**
     * Iterates through the grid. If a 'B' cell is found, marks adjacent '.' cells as '#'.
     */
    private static void processBlackCells(char[][] grid, int n, int m) {
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < m; c++) {
                if (grid[r][c] == 'B') {
                    expandNeighbors(grid, r, c, n, m);
                }
            }
        }
    }

    /**
     * Marks valid adjacent neighbors of a cell as obstacles ('#').
     */
    private static void expandNeighbors(char[][] grid, int r, int c, int n, int m) {
        for (int i = 0; i < 4; i++) {
            int nr = r + ROW_DIRS[i];
            int nc = c + COL_DIRS[i];
            if (isValid(nr, nc, n, m) && grid[nr][nc] == '.') {
                grid[nr][nc] = '#';
            }
        }
    }

    /**
     * Checks if coordinates are within grid bounds.
     */
    private static boolean isValid(int r, int c, int n, int m) {
        return r >= 0 && c >= 0 && r < n && c < m;
    }

    /**
     * Counts the number of Green ('G') cells in the grid.
     */
    private static int countGreenCells(char[][] grid, int n, int m) {
        int count = 0;
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < m; c++) {
                if (grid[r][c] == 'G') {
                    count++;
                }
            }
        }
        return count;
    }

    /**
     * Performs Breadth-First Search (BFS) starting from (startR, startC).
     * Returns a 2D boolean array indicating visited cells.
     */
    private static boolean[][] bfs(char[][] grid, int n, int m, int startR, int startC) {
        boolean[][] visited = new boolean[n][m];
        Queue<Point> queue = new LinkedList<>();

        // If start position is blocked, nothing is reachable
        if (grid[startR][startC] == '#') {
            return visited;
        }

        queue.add(new Point(startR, startC, 0));
        visited[startR][startC] = true;

        while (!queue.isEmpty()) {
            Point current = queue.poll();

            for (int i = 0; i < 4; i++) {
                int nr = current.r + ROW_DIRS[i];
                int nc = current.c + COL_DIRS[i];

                if (isValid(nr, nc, n, m) && !visited[nr][nc] && grid[nr][nc] != '#') {
                    queue.add(new Point(nr, nc, current.dist + 1));
                    visited[nr][nc] = true;
                }
            }
        }
        return visited;
    }

    /**
     * Validates the solution based on grid state and BFS reachability.
     * - No 'B' cell should be reachable.
     * - All 'G' cells must be reachable.
     */
    private static boolean validateSolution(char[][] grid, boolean[][] visited, int n, int m) {
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < m; c++) {
                // If a Black cell is reachable, the solution is invalid
                if (grid[r][c] == 'B' && visited[r][c]) {
                    return false;
                }
                // If a Green cell is not reachable, the solution is invalid
                if (grid[r][c] == 'G' && !visited[r][c]) {
                    return false;
                }
            }
        }
        return true;
    }
}

import java.io.*;
import java.util.ArrayDeque;
import java.util.InputMismatchException;
import java.util.Queue;

public class Main {
    public static void main(String[] args) {
        InputReader in = new InputReader(System.in);
        OutputWriter out = new OutputWriter(System.out);
        new MazeSolver().solve(in.nextInt(), in, out);
        out.close();
    }

    /**
     * Solves the maze problem for multiple test cases.
     * Uses BFS to determine reachability and validates grid conditions.
     */
    static class MazeSolver {
        private static final int[] DR = {-1, 0, 1, 0};
        private static final int[] DC = {0, 1, 0, -1};

        public void solve(int testCount, InputReader in, OutputWriter out) {
            while (testCount-- > 0) {
                int rows = in.nextInt();
                int cols = in.nextInt();
                char[][] grid = new char[rows][cols];
                boolean[][] visited = new boolean[rows][cols];
                int greenCount = 0;
                int blackCount = 0;

                // Read grid and count special cells
                for (int i = 0; i < rows; i++) {
                    for (int j = 0; j < cols; j++) {
                        char ch = in.nextCharacter();
                        grid[i][j] = ch;
                        if (ch == 'G') {
                            greenCount++;
                        } else if (ch == 'B') {
                            blackCount++;
                        }
                    }
                }

                // If no green cells, condition is trivially satisfied
                if (greenCount == 0) {
                    out.println("Yes");
                    continue;
                }

                // Determine blocked cells (adjacent to 'B' or bottom-right corner)
                boolean[][] blocked = new boolean[rows][cols];
                for (int i = 0; i < rows; i++) {
                    for (int j = 0; j < cols; j++) {
                        if (grid[i][j] == 'B') {
                            for (int k = 0; k < 4; k++) {
                                int nr = i + DR[k];
                                int nc = j + DC[k];
                                if (isValid(nr, nc, rows, cols) && grid[nr][nc] == '.') {
                                    blocked[nr][nc] = true;
                                }
                            }
                        }
                    }
                }

                // Mark bottom-right as blocked if it's empty
                if (grid[rows - 1][cols - 1] == '.') {
                    blocked[rows - 1][cols - 1] = true;
                }

                // Run BFS from bottom-right to find reachable cells
                bfs(rows - 1, cols - 1, rows, cols, grid, blocked, visited);

                // Validate conditions:
                // 1. All 'G' cells must be visited
                // 2. No 'B' cells should be visited
                boolean valid = true;
                outerLoop:
                for (int i = 0; i < rows; i++) {
                    for (int j = 0; j < cols; j++) {
                        char cell = grid[i][j];
                        if (cell == 'G' && !visited[i][j]) {
                            valid = false;
                            break outerLoop;
                        }
                        if (cell == 'B' && visited[i][j]) {
                            valid = false;
                            break outerLoop;
                        }
                    }
                }

                out.println(valid ? "Yes" : "No");
            }
        }

        private boolean isValid(int r, int c, int rows, int cols) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }

        private void bfs(int startR, int startC, int rows, int cols,
                         char[][] grid, boolean[][] blocked, boolean[][] visited) {
            Queue<Point> queue = new ArrayDeque<>();
            queue.add(new Point(startR, startC));
            visited[startR][startC] = true;

            while (!queue.isEmpty()) {
                Point curr = queue.poll();
                for (int k = 0; k < 4; k++) {
                    int nr = curr.r + DR[k];
                    int nc = curr.c + DC[k];
                    if (isValid(nr, nc, rows, cols)
                            && grid[nr][nc] != '#'
                            && !blocked[nr][nc]
                            && !visited[nr][nc]) {
                        visited[nr][nc] = true;
                        queue.add(new Point(nr, nc));
                    }
                }
            }
        }

        /**
         * Simple immutable coordinate class for BFS queue.
         */
        private static class Point {
            final int r, c;
            Point(int r, int c) {
                this.r = r;
                this.c = c;
            }
        }
    }

    /**
     * Fast output writer using PrintWriter and BufferedWriter.
     */
    static class OutputWriter {
        private final PrintWriter writer;

        public OutputWriter(OutputStream outputStream) {
            this.writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(outputStream)));
        }

        public void print(Object... objects) {
            for (int i = 0; i < objects.length; i++) {
                if (i > 0) {
                    writer.print(' ');
                }
                writer.print(objects[i]);
            }
        }

        public void println(Object... objects) {
            print(objects);
            writer.println();
        }

        public void close() {
            writer.flush();
            writer.close();
        }
    }

    /**
     * Fast input reader for competitive programming.
     */
    static class InputReader {
        private final InputStream stream;
        private final byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;
        private SpaceCharFilter filter;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        public int read() {
            if (numChars == -1) {
                throw new InputMismatchException();
            }
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0) {
                    return -1;
                }
            }
            return buf[curChar++];
        }

        public int nextInt() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                res *= 10;
                res += c - '0';
                c = read();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public char nextCharacter() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            return (char) c;
        }

        public boolean isSpaceChar(int c) {
            return filter != null ? filter.isSpaceChar(c) : isWhitespace(c);
        }

        public static boolean isWhitespace(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        public interface SpaceCharFilter {
            boolean isSpaceChar(int ch);
        }
    }
}

import java.io.*;
import java.util.*;

public class Main {

    public static void main(String[] args) {
        // Use buffered I/O for performance
        FastScanner sc = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out));

        try {
            int t = sc.nextInt();
            while (t-- > 0) {
                solve(sc, out);
            }
        } catch (Exception e) {
            e.printStackTrace();
        } finally {
            out.flush();
            out.close();
        }
    }

    /**
     * Solves a single test case.
     * Encapsulates all state locally to avoid global variable pollution.
     */
    private static void solve(FastScanner sc, PrintWriter out) {
        int n = sc.nextInt();
        int m = sc.nextInt();
        char[][] grid = new char[n][m];

        for (int i = 0; i < n; i++) {
            grid[i] = sc.next().toCharArray();
        }

        // Direction vectors for 4-directional movement
        int[] dRow = {-1, 1, 0, 0};
        int[] dCol = {0, 0, -1, 1};

        // 1. Mark cells adjacent to 'B' as blocked ('#')
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == 'B') {
                    for (int k = 0; k < 4; k++) {
                        int ni = i + dRow[k];
                        int nj = j + dCol[k];
                        // Only mark if within bounds and not already blocked or 'B'
                        if (ni >= 0 && ni < n && nj >= 0 && nj < m && 
                            grid[ni][nj] != '#' && grid[ni][nj] != 'B') {
                            grid[ni][nj] = '#';
                        }
                    }
                }
            }
        }

        // 2. Iterative BFS from the bottom-right corner (n-1, m-1)
        boolean[][] visited = new boolean[n][m];
        Queue<int[]> queue = new ArrayDeque<>();

        // If the starting cell is blocked, BFS won't explore anything, which is correct
        if (grid[n - 1][m - 1] != '#') {
            queue.offer(new int[]{n - 1, m - 1});
            visited[n - 1][m - 1] = true;
        }

        while (!queue.isEmpty()) {
            int[] curr = queue.poll();
            int r = curr[0];
            int c = curr[1];

            for (int k = 0; k < 4; k++) {
                int nr = r + dRow[k];
                int nc = c + dCol[k];

                // Check bounds, visited status, and obstacles ('#' and 'B')
                if (nr >= 0 && nr < n && nc >= 0 && nc < m &&
                    !visited[nr][nc] && grid[nr][nc] != '#' && grid[nr][nc] != 'B') {
                    visited[nr][nc] = true;
                    queue.offer(new int[]{nr, nc});
                }
            }
        }

        // 3. Verify all 'G' cells are reachable
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == 'G' && !visited[i][j]) {
                    out.println("No");
                    return;
                }
            }
        }
        out.println("Yes");
    }

    /**
     * Fast, robust input scanner for competitive programming / large I/O.
     */
    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        public String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input", e);
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            String s = next();
            return s == null ? 0 : Integer.parseInt(s);
        }

        public long nextLong() {
            String s = next();
            return s == null ? 0L : Long.parseLong(s);
        }

        public double nextDouble() {
            String s = next();
            return s == null ? 0.0 : Double.parseDouble(s);
        }
    }
}

import java.io.OutputStream;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.Scanner;

public class Main {
    // Magic values extracted to constants for readability and maintainability
    private static final char BLACK = 'B';
    private static final char GREEN = 'G';
    private static final char BLOCKED = '#';
    private static final String OUTPUT_YES = "Yes";
    private static final String OUTPUT_NO = "No";

    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        Scanner in = new Scanner(inputStream);
        PrintWriter out = new PrintWriter(outputStream);

        int testCount = in.hasNextInt() ? in.nextInt() : 0;
        for (int i = 1; i <= testCount; i++) {
            // Instantiate solver per test case to isolate state
            GridSolver solver = new GridSolver(in, out);
            solver.solve();
        }
        out.close();
    }

    /**
     * Encapsulates grid processing logic for a single test case.
     * Replaces static fields with instance fields to prevent state leakage
     * between test cases and improve thread-safety/reusability.
     */
    static class GridSolver {
        private final int rows;
        private final int cols;
        private final char[][] grid;
        private final int[][] memo;      // 0: uncomputed, 1: true, 2: false
        private final int[][] visitedToken; // Tracks visited cells per DFS traversal
        private int currentToken = 0;    // Increments per traversal to avoid O(N*M) reset

        private final Scanner in;
        private final PrintWriter out;

        public GridSolver(Scanner in, PrintWriter out) {
            this.in = in;
            this.out = out;
            this.rows = in.nextInt();
            this.cols = in.nextInt();
            this.grid = new char[rows][cols];
            this.memo = new int[rows][cols];
            this.visitedToken = new int[rows][cols];

            for (int i = 0; i < rows; i++) {
                grid[i] = in.next().toCharArray();
            }
        }

        public void solve() {
            // Pass 1: Validate and process all 'B' cells
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j] == BLACK) {
                        currentToken++;
                        if (!convert(i, j)) {
                            out.println(OUTPUT_NO);
                            return;
                        }
                    }
                }
            }

            // Pass 2: Validate reachability for all 'G' cells
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j] == GREEN) {
                        currentToken++;
                        if (!canReachDestination(i, j)) {
                            out.println(OUTPUT_NO);
                            return;
                        }
                    }
                }
            }
            out.println(OUTPUT_YES);
        }

        /**
         * Recursively processes 'B' cells, converting them to '#'.
         * Fails immediately if a 'B' cell is adjacent to 'G'.
         */
        private boolean convert(int r, int c) {
            // Out of bounds or already processed/blocked
            if (r < 0 || r >= rows || c < 0 || c >= cols || grid[r][c] == BLOCKED) {
                return true;
            }
            // 'B' cells are marked as blocked once processed to prevent re-entry
            grid[r][c] = BLOCKED;

            int[] dr = {-1, 1, 0, 0};
            int[] dc = {0, 0, -1, 1};

            for (int k = 0; k < 4; k++) {
                int nr = r + dr[k];
                int nc = c + dc[k];

                if (nr < 0 || nr >= rows || nc < 0 || nc >= cols) {
                    continue;
                }

                char neighbor = grid[nr][nc];
                if (neighbor == GREEN) {
                    return false; // Invalid configuration
                }
                if (neighbor == BLACK) {
                    if (!convert(nr, nc)) {
                        return false; // Chain validation failed
                    }
                }
                // '#' neighbors are safely skipped
            }
            return true;
        }

        /**
         * Checks if a 'G' cell can reach the bottom-right corner (rows-1, cols-1).
         * Uses DFS with memoization and a token-based visited array to avoid
         * O(N*M) array reallocations per traversal.
         */
        private boolean canReachDestination(int r, int c) {
            if (r < 0 || r >= rows || c < 0 || c >= cols) {
                return false;
            }
            if (grid[r][c] == BLOCKED) {
                return false;
            }
            if (r == rows - 1 && c == cols - 1) {
                return true;
            }
            if (memo[r][c] != 0) {
                return memo[r][c] == 1;
            }
            if (visitedToken[r][c] == currentToken) {
                return false; // Cycle detected
            }

            visitedToken[r][c] = currentToken;
            boolean result = canReachDestination(r + 1, c) ||
                             canReachDestination(r - 1, c) ||
                             canReachDestination(r, c + 1) ||
                             canReachDestination(r, c - 1);

            memo[r][c] = result ? 1 : 2;
            return result;
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.ArrayDeque;
import java.util.StringTokenizer;

public class Task4 {

    // Constants for grid characters and output strings
    private static final char CH_B = 'B';
    private static final char CH_G = 'G';
    private static final char CH_DOT = '.';
    private static final char CH_BLOCK = '#';
    private static final String OUT_YES = "Yes";
    private static final String OUT_NO = "No";

    // Direction vectors for Up, Down, Left, Right
    private static final int[] DR = {-1, 1, 0, 0};
    private static final int[] DC = {0, 0, -1, 1};

    public static void main(String[] args) throws IOException {
        // Use try-with-resources for automatic resource management
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
             PrintWriter out = new PrintWriter(System.out)) {
            new Task4().solve(br, out);
        }
    }

    public void solve(BufferedReader br, PrintWriter out) throws IOException {
        String line = br.readLine();
        if (line == null) return;

        int t = Integer.parseInt(line.trim());
        for (int caseNum = 0; caseNum < t; caseNum++) {
            String rowLine = br.readLine();
            while (rowLine != null && rowLine.trim().isEmpty()) {
                rowLine = br.readLine(); // Skip potential empty lines
            }
            if (rowLine == null) break;

            StringTokenizer st = new StringTokenizer(rowLine);
            int n = Integer.parseInt(st.nextToken());
            int m = Integer.parseInt(st.nextToken());

            char[][] grid = new char[n][m];
            for (int i = 0; i < n; i++) {
                grid[i] = br.readLine().toCharArray();
            }

            boolean possible = processGrid(grid, n, m);
            out.println(possible ? OUT_YES : OUT_NO);
        }
    }

    /**
     * Processes a single test case grid.
     * 1. Validates B-G adjacency and marks '.' cells adjacent to 'B' as blocked.
     * 2. Performs iterative DFS from the exit to find all reachable cells.
     * 3. Verifies that all 'G' cells are reachable from the exit.
     */
    private boolean processGrid(char[][] grid, int n, int m) {
        // Step 1: Initialize blocked cells and validate B-G adjacency
        boolean[][] blocked = new boolean[n][m];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == CH_BLOCK) {
                    blocked[i][j] = true;
                }
            }
        }

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == CH_B) {
                    for (int d = 0; d < 4; d++) {
                        int ni = i + DR[d];
                        int nj = j + DC[d];
                        if (isValid(ni, nj, n, m)) {
                            if (grid[ni][nj] == CH_G) {
                                return false; // Invalid: B is directly adjacent to G
                            }
                            if (grid[ni][nj] == CH_DOT) {
                                blocked[ni][nj] = true; // '.' adjacent to 'B' becomes an obstacle
                            }
                        }
                    }
                }
            }
        }

        // Step 2: Find all cells reachable from the bottom-right exit
        boolean[][] canExit = new boolean[n][m];
        if (!blocked[n - 1][m - 1]) {
            dfsIterative(n - 1, m - 1, blocked, canExit, n, m);
        }

        // Step 3: Verify all 'G' cells can reach the exit
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == CH_G && !canExit[i][j]) {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Iterative DFS to mark all reachable cells from the start position.
     * Uses an explicit stack to avoid potential StackOverflowError on large grids.
     */
    private void dfsIterative(int startR, int startC, boolean[][] blocked, boolean[][] canExit, int n, int m) {
        ArrayDeque<Point> stack = new ArrayDeque<>();
        stack.push(new Point(startR, startC));
        canExit[startR][startC] = true;

        while (!stack.isEmpty()) {
            Point curr = stack.pop();
            for (int d = 0; d < 4; d++) {
                int nr = curr.r + DR[d];
                int nc = curr.c + DC[d];
                if (isValid(nr, nc, n, m) && !blocked[nr][nc] && !canExit[nr][nc]) {
                    canExit[nr][nc] = true;
                    stack.push(new Point(nr, nc));
                }
            }
        }
    }

    private boolean isValid(int r, int c, int n, int m) {
        return r >= 0 && r < n && c >= 0 && c < m;
    }

    /**
     * Immutable coordinate class to replace int[] arrays for better type safety and readability.
     */
    private static class Point {
        final int r, c;
        Point(int r, int c) {
            this.r = r;
            this.c = c;
        }
    }
}

import java.util.ArrayDeque;
import java.util.Queue;
import java.util.Scanner;

public class Main {
    // Direction vectors for moving up, down, left, right
    private static final int[][] DIRECTIONS = {
        {0, 1}, {0, -1}, {1, 0}, {-1, 0}
    };

    /**
     * Helper class to represent coordinates in the grid.
     * Replaces the original Node class with a more descriptive name.
     */
    static class Point {
        int x, y;

        Point(int x, int y) {
            this.x = x;
            this.y = y;
        }
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        // Check if input exists to prevent exceptions on empty input
        if (scanner.hasNextInt()) {
            int testCases = scanner.nextInt();
            while (testCases-- > 0) {
                solve(scanner);
            }
        }
        scanner.close();
    }

    /**
     * Solves a single test case.
     * 
     * @param scanner The input scanner
     */
    private static void solve(Scanner scanner) {
        int rows = scanner.nextInt();
        int cols = scanner.nextInt();
        char[][] grid = new char[rows][cols];
        int totalGrapes = 0;

        // Read the grid and count initial grapes
        for (int i = 0; i < rows; i++) {
            String line = scanner.next();
            for (int j = 0; j < cols; j++) {
                grid[i][j] = line.charAt(j);
                if (grid[i][j] == 'G') {
                    totalGrapes++;
                }
            }
        }

        // Phase 1: Process Bombs
        // Bombs destroy adjacent empty spaces ('.') turning them into walls ('#').
        // If a bomb is adjacent to a grape ('G'), the mission is unsafe.
        boolean isBombSafe = true;

        // Using a labeled break to exit nested loops immediately upon failure
        bombCheck:
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == 'B') {
                    for (int[] d : DIRECTIONS) {
                        int nx = i + d[0];
                        int ny = j + d[1];

                        if (isValid(nx, ny, rows, cols)) {
                            if (grid[nx][ny] == 'G') {
                                isBombSafe = false;
                                break bombCheck; // Found a grape next to a bomb, stop checking
                            } else if (grid[nx][ny] == '.') {
                                grid[nx][ny] = '#'; // Turn empty space into wall
                            }
                        }
                    }
                }
            }
        }

        // Phase 2: Determine Outcome
        // If the mission is unsafe (bomb next to grape) OR the goal (bottom-right) is blocked,
        // we cannot perform the pathfinding search.
        if (!isBombSafe || grid[rows - 1][cols - 1] == '#') {
            // If unsafe or blocked, we check if there are any grapes left.
            // Logic preserved from original: if totalGrapes == 0 Yes else No.
            System.out.println(totalGrapes == 0 ? "Yes" : "No");
        } else {
            // Phase 3: BFS to collect remaining grapes
            // Start from bottom-right corner (rows-1, cols-1)

            // Mark starting position as visited (wall) - matches original logic
            grid[rows - 1][cols - 1] = '#';
            Queue<Point> queue = new ArrayDeque<>();
            queue.add(new Point(rows - 1, cols - 1));

            while (!queue.isEmpty()) {
                Point current = queue.poll();

                for (int[] d : DIRECTIONS) {
                    int nx = current.x + d[0];
                    int ny = current.y + d[1];

                    if (isValid(nx, ny, rows, cols) && grid[nx][ny] != '#') {
                        if (grid[nx][ny] == 'G') {
                            totalGrapes--; // Collected a grape
                        }
                        grid[nx][ny] = '#'; // Mark as visited
                        queue.add(new Point(nx, ny));
                    }
                }
            }

            // If all grapes are collected (count is 0), output Yes
            System.out.println(totalGrapes == 0 ? "Yes" : "No");
        }
    }

    /**
     * Checks if coordinates are within grid bounds.
     * 
     * @param x X coordinate
     * @param y Y coordinate
     * @param rows Number of rows
     * @param cols Number of columns
     * @return true if valid, false otherwise
     */
    private static boolean isValid(int x, int y, int rows, int cols) {
        return x >= 0 && x < rows && y >= 0 && y < cols;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

/**
 * Refactored solution for grid pathfinding.
 * 
 * Improvements made:
 * 1. Removed global state (static 'found' variable) to improve thread safety and logic clarity.
 * 2. Encapsulated logic into distinct methods: Input handling, Grid processing, and Pathfinding.
 * 3. Used descriptive variable names and constants for grid characters.
 * 4. Implemented proper memoization to avoid redundant calculations in the DFS.
 * 5. Fixed the pathfinding logic to correctly return boolean results instead of relying on side-effects.
 * 6. Used try-with-resources for robust resource management.
 * 7. Added input validation and robustness checks.
 */
public class PathFinder {

    // Constants for grid characters
    private static final char WALL = '#';
    private static final char BOMB = 'B';
    private static final char GOAL = 'G';

    public static void main(String[] args) throws IOException {
        // Use try-with-resources to ensure BufferedReader is closed automatically
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(System.in))) {
            String line = reader.readLine();
            if (line == null) return;

            // Parse number of test cases
            int testCases;
            try {
                testCases = Integer.parseInt(line.trim());
            } catch (NumberFormatException e) {
                return;
            }

            while (testCases-- > 0) {
                // Read dimensions
                line = reader.readLine();
                // Skip potential empty lines between test cases
                while (line != null && line.trim().isEmpty()) {
                    line = reader.readLine();
                }
                if (line == null) break;

                StringTokenizer st = new StringTokenizer(line);
                int rows = Integer.parseInt(st.nextToken());
                int cols = Integer.parseInt(st.nextToken());

                // Read grid
                char[][] grid = new char[rows][];
                for (int r = 0; r < rows; r++) {
                    String rowStr = reader.readLine();
                    while (rowStr != null && rowStr.trim().isEmpty()) {
                        rowStr = reader.readLine();
                    }
                    if (rowStr == null) break;
                    grid[r] = rowStr.trim().toCharArray();
                }

                // Process blocked cells (Walls and Bomb effects)
                boolean[][] isBlocked = processBlockedCells(grid, rows, cols);

                // Check if all 'G' positions can reach the bottom-right corner
                boolean allGoalsReachable = true;
                // Memoization array: null = unknown, true = reachable, false = unreachable
                Boolean[][] memo = new Boolean[rows][cols];

                outerLoop:
                for (int r = 0; r < rows; r++) {
                    for (int c = 0; c < cols; c++) {
                        if (grid[r][c] == GOAL) {
                            // Create a fresh visited array for the current path search to detect cycles
                            boolean[][] visited = new boolean[rows][cols];

                            if (!canReach(r, c, rows, cols, isBlocked, memo, visited)) {
                                allGoalsReachable = false;
                                break outerLoop;
                            }
                        }
                    }
                }

                System.out.println(allGoalsReachable ? "Yes" : "No");
            }
        }
    }

    /**
     * Processes the grid to identify all blocked cells.
     * Walls ('#') are blocked. Bombs ('B') block themselves and their 4 adjacent neighbors.
     */
    private static boolean[][] processBlockedCells(char[][] grid, int rows, int cols) {
        boolean[][] blocked = new boolean[rows][cols];

        for (int r = 0; r < rows; r++) {
            if (grid[r] == null || grid[r].length < cols) continue;

            for (int c = 0; c < cols; c++) {
                char cell = grid[r][c];
                if (cell == WALL) {
                    blocked[r][c] = true;
                } else if (cell == BOMB) {
                    blocked[r][c] = true;
                    // Mark adjacent cells as blocked
                    markNeighborsBlocked(blocked, r - 1, c, rows, cols);
                    markNeighborsBlocked(blocked, r + 1, c, rows, cols);
                    markNeighborsBlocked(blocked, r, c - 1, rows, cols);
                    markNeighborsBlocked(blocked, r, c + 1, rows, cols);
                }
            }
        }
        return blocked;
    }

    private static void markNeighborsBlocked(boolean[][] blocked, int r, int c, int rows, int cols) {
        if (r >= 0 && r < rows && c >= 0 && c < cols) {
            blocked[r][c] = true;
        }
    }

    /**
     * Determines if a path exists from (r, c) to the bottom-right corner (rows-1, cols-1).
     * Uses Depth First Search (DFS) with memoization.
     *
     * @param r Current row
     * @param c Current column
     * @param rows Total number of rows
     * @param cols Total number of columns
     * @param isBlocked 2D array indicating blocked cells
     * @param memo Memoization array to store results of subproblems
     * @param visited 2D array to track the current recursion path (cycle detection)
     * @return true if a path exists, false otherwise
     */
    private static boolean canReach(int r, int c, int rows, int cols, 
                                    boolean[][] isBlocked, Boolean[][] memo, boolean[][] visited) {

        // 1. Boundary Check
        if (r < 0 || r >= rows || c < 0 || c >= cols) {
            return false;
        }

        // 2. Check if cell is blocked
        if (isBlocked[r][c]) {
            return false;
        }

        // 3. Check Memoization
        // If we have already determined the result for this cell, return it.
        if (memo[r][c] != null) {
            return memo[r][c];
        }

        // 4. Cycle Detection
        // If we are revisiting a cell in the current path, we have a cycle.
        if (visited[r][c]) {
            return false;
        }

        // 5. Goal Check
        // If we reached the bottom-right corner, we found a path.
        if (r == rows - 1 && c == cols - 1) {
            visited[r][c] = true; 
            memo[r][c] = true;
            return true;
        }

        // 6. Mark current cell as visited for the current path
        visited[r][c] = true;

        // 7. Recursive Step: Check all 4 directions
        boolean canReachDown = canReach(r + 1, c, rows, cols, isBlocked, memo, visited);
        boolean canReachUp = canReach(r - 1, c, rows, cols, isBlocked, memo, visited);
        boolean canReachRight = canReach(r, c + 1, rows, cols, isBlocked, memo, visited);
        boolean canReachLeft = canReach(r, c - 1, rows, cols, isBlocked, memo, visited);

        boolean result = canReachDown || canReachUp || canReachRight || canReachLeft;

        // 8. Memoize the result
        memo[r][c] = result;

        // Note: We do not reset visited[r][c] = false here. 
        // Since we memoize the result, subsequent calls will hit the memo check (step 3) 
        // and return immediately. The visited state is only critical for preventing infinite 
        // loops during the computation of a specific cell's status.

        return result;
    }
}

import java.util.LinkedList;
import java.util.Queue;
import java.util.Scanner;

public class D1365 {

    // Grid cell type constants
    private static final int EMPTY = 0;
    private static final int WALL = 1;
    private static final int GOAL = 2;
    private static final int TRAP = 3;

    // Direction vectors: Down, Up, Right, Left
    private static final int[] DX = {1, -1, 0, 0};
    private static final int[] DY = {0, 0, 1, -1};

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        if (!scanner.hasNextInt()) {
            return;
        }

        int testCases = scanner.nextInt();
        while (testCases-- > 0) {
            int rows = scanner.nextInt();
            int cols = scanner.nextInt();

            int[][] grid = readGrid(scanner, rows, cols);
            int totalGoals = countGoals(grid, rows, cols);

            // Traps convert adjacent empty cells into walls
            propagateTraps(grid, rows, cols);

            // If the destination is blocked, check if any goals existed
            if (grid[rows - 1][cols - 1] == WALL) {
                System.out.println(totalGoals == 0 ? "Yes" : "No");
            } else {
                BFSResult bfsResult = performBFS(grid, rows, cols, rows - 1, cols - 1);
                if (bfsResult.isBad) {
                    System.out.println("No");
                } else {
                    System.out.println(totalGoals == bfsResult.reachableGoals ? "Yes" : "No");
                }
            }
        }
        scanner.close();
    }

    /**
     * Parses the input grid into an integer matrix.
     */
    private static int[][] readGrid(Scanner scanner, int rows, int cols) {
        int[][] grid = new int[rows][cols];
        for (int i = 0; i < rows; i++) {
            String rowStr = scanner.next();
            for (int j = 0; j < cols; j++) {
                char c = rowStr.charAt(j);
                if (c == '.') grid[i][j] = EMPTY;
                else if (c == '#') grid[i][j] = WALL;
                else if (c == 'G') grid[i][j] = GOAL;
                else grid[i][j] = TRAP;
            }
        }
        return grid;
    }

    /**
     * Counts the total number of goal cells in the grid.
     */
    private static int countGoals(int[][] grid, int rows, int cols) {
        int count = 0;
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == GOAL) count++;
            }
        }
        return count;
    }

    /**
     * Propagates trap effects: adjacent empty cells become walls.
     */
    private static void propagateTraps(int[][] grid, int rows, int cols) {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == TRAP) {
                    for (int k = 0; k < 4; k++) {
                        int ni = i + DX[k];
                        int nj = j + DY[k];
                        if (isValid(ni, nj, rows, cols) && grid[ni][nj] == EMPTY) {
                            grid[ni][nj] = WALL;
                        }
                    }
                }
            }
        }
    }

    /**
     * Checks if coordinates are within grid boundaries.
     */
    private static boolean isValid(int x, int y, int rows, int cols) {
        return x >= 0 && x < rows && y >= 0 && y < cols;
    }

    /**
     * Performs BFS from the starting position to count reachable goals
     * and detect if any traps are encountered.
     */
    private static BFSResult performBFS(int[][] grid, int rows, int cols, int startX, int startY) {
        boolean[][] visited = new boolean[rows][cols];
        Queue<Point> queue = new LinkedList<>();
        queue.add(new Point(startX, startY));
        visited[startX][startY] = true;

        int reachableGoals = 0;
        boolean isBad = false;

        while (!queue.isEmpty()) {
            Point current = queue.poll();

            for (int k = 0; k < 4; k++) {
                int ni = current.x + DX[k];
                int nj = current.y + DY[k];

                if (!isValid(ni, nj, rows, cols)) continue;
                if (visited[ni][nj]) continue;
                if (grid[ni][nj] == WALL) continue;

                visited[ni][nj] = true;

                if (grid[ni][nj] == TRAP) {
                    isBad = true;
                    break;
                } else if (grid[ni][nj] == GOAL) {
                    reachableGoals++;
                }

                queue.add(new Point(ni, nj));
            }
            if (isBad) break;
        }

        return new BFSResult(isBad, reachableGoals);
    }

    /**
     * Immutable data structure to hold BFS traversal results.
     */
    private static class BFSResult {
        final boolean isBad;
        final int reachableGoals;

        BFSResult(boolean isBad, int reachableGoals) {
            this.isBad = isBad;
            this.reachableGoals = reachableGoals;
        }
    }

    /**
     * Immutable coordinate point for grid traversal.
     */
    private static class Point {
        final int x, y;

        Point(int x, int y) {
            this.x = x;
            this.y = y;
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Refactored solution for grid traversal problem.
 * 
 * Improvements over original:
 * - Eliminated global static state for better encapsulation and testability.
 * - Replaced recursive DFS with iterative BFS to prevent StackOverflowError.
 * - Fixed logical bugs in visited tracking and obstacle handling.
 * - Replaced custom InputReader with a standard, correct FastScanner.
 * - Removed unused code (mod, Pair, Debugger).
 * - Applied proper resource management with try-with-resources.
 */
public class Main {

    public static void main(String[] args) {
        // try-with-resources ensures automatic closing and flushing of streams
        try (FastScanner scanner = new FastScanner(System.in);
             PrintWriter out = new PrintWriter(System.out)) {

            int t = scanner.nextInt();
            while (t-- > 0) {
                solve(scanner, out);
            }
        }
        out.flush();
    }

    /**
     * Processes a single test case: reads the grid, counts total 'G's,
     * performs BFS from the bottom-right corner, and prints the result.
     */
    private static void solve(FastScanner scanner, PrintWriter out) {
        int n = scanner.nextInt();
        int m = scanner.nextInt();
        char[][] grid = new char[n][m];
        int totalGs = 0;

        for (int i = 0; i < n; i++) {
            String line = scanner.next();
            grid[i] = line.toCharArray();
            for (char c : line.toCharArray()) {
                if (c == 'G') {
                    totalGs++;
                }
            }
        }

        // Edge case: no 'G' cells exist
        if (totalGs == 0) {
            out.println("Yes");
            return;
        }

        int reachableGs = countReachableGs(grid, n, m);
        out.println(reachableGs == totalGs ? "Yes" : "No");
    }

    /**
     * Performs iterative BFS from (n-1, m-1) to count reachable 'G' cells.
     * Avoids traversing through 'B' (blocked) or '#' (wall) cells.
     */
    private static int countReachableGs(char[][] grid, int n, int m) {
        boolean[][] visited = new boolean[n][m];
        int reachableGs = 0;

        // Array-based queue for O(1) enqueue/dequeue without object overhead
        int[] queue = new int[n * m];
        int head = 0, tail = 0;

        int startR = n - 1;
        int startC = m - 1;

        // Starting position is blocked
        if (grid[startR][startC] == 'B' || grid[startR][startC] == '#') {
            return 0;
        }

        queue[tail++] = startR * m + startC;
        visited[startR][startC] = true;

        int[] dr = {-1, 1, 0, 0};
        int[] dc = {0, 0, -1, 1};

        while (head < tail) {
            int pos = queue[head++];
            int r = pos / m;
            int c = pos % m;

            if (grid[r][c] == 'G') {
                reachableGs++;
            }

            for (int i = 0; i < 4; i++) {
                int nr = r + dr[i];
                int nc = c + dc[i];

                // Check bounds, visited status, and obstacles
                if (nr >= 0 && nr < n && nc >= 0 && nc < m &&
                    !visited[nr][nc] &&
                    grid[nr][nc] != 'B' && grid[nr][nc] != '#') {

                    visited[nr][nc] = true;
                    queue[tail++] = nr * m + nc;
                }
            }
        }

        return reachableGs;
    }

    /**
     * FastScanner for efficient input reading in competitive programming.
     * Uses BufferedReader and StringTokenizer to handle whitespace correctly.
     */
    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        public String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            String s = next();
            return s == null ? 0 : Integer.parseInt(s);
        }
    }
}

import java.util.Scanner;

public class CF1365D {

    /**
     * Direction vectors for traversing the grid (Up, Down, Left, Right).
     * Using arrays simplifies neighbor iteration and reduces code duplication.
     */
    private static final int[] DR = {-1, 1, 0, 0};
    private static final int[] DC = {0, 0, -1, 1};

    public static void main(String[] args) {
        // Use try-with-resources to ensure the Scanner is properly closed.
        // This prevents resource leaks.
        try (Scanner sc = new Scanner(System.in)) {
            if (sc.hasNextInt()) {
                int testCases = sc.nextInt();
                for (int t = 1; t <= testCases; t++) {
                    solveTestCase(sc);
                }
            }
        }
    }

    /**
     * Solves a single test case by reading input, processing the grid,
     * and printing the result.
     */
    private static void solveTestCase(Scanner sc) {
        int rows = sc.nextInt();
        int cols = sc.nextInt();

        // Safety check for empty grid dimensions, though problem constraints usually ensure >= 1.
        if (rows == 0 || cols == 0) {
            return;
        }

        char[][] grid = new char[rows][cols];

        // Read the grid rows
        for (int r = 0; r < rows; r++) {
            grid[r] = sc.next().toCharArray();
        }

        // Step 1: Block all cells adjacent to 'B' (Ball) by turning them into walls '#'.
        // This prevents movement through or adjacent to the ball.
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == 'B') {
                    blockNeighbors(r, c, rows, cols, grid);
                }
            }
        }

        // Step 2: Determine if the Goal 'G' is reachable from the bottom-right corner.
        // The logic implies that if 'G' is reachable (and thus marked by DFS),
        // the outcome is "yes". If 'G' remains unvisited, it is "No".

        boolean possible = true;
        int startRow = rows - 1;
        int startCol = cols - 1;

        // Only start traversal if the starting cell is walkable ('.')
        if (grid[startRow][startCol] == '.') {
            dfs(startRow, startCol, rows, cols, grid);
        }

        // Check if 'G' is still present in the grid.
        // If 'G' was reachable, the DFS would have marked it with '$'.
        // If 'G' is still 'G', it was not reachable.
        searchForGoal:
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == 'G') {
                    possible = false;
                    break searchForGoal;
                }
            }
        }

        // Output result (preserving original casing: "yes" / "No")
        if (possible) {
            System.out.println("yes");
        } else {
            System.out.println("No");
        }
    }

    /**
     * Marks all valid neighbors of a cell as walls ('#').
     */
    private static void blockNeighbors(int r, int c, int rows, int cols, char[][] grid) {
        for (int i = 0; i < 4; i++) {
            int nr = r + DR[i];
            int nc = c + DC[i];
            if (isValid(nr, nc, rows, cols) && grid[nr][nc] == '.') {
                grid[nr][nc] = '#';
            }
        }
    }

    /**
     * Checks if coordinates are within grid bounds.
     */
    private static boolean isValid(int r, int c, int rows, int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /**
     * Performs Depth First Search (DFS) to mark reachable cells.
     * Replaces visited walkable cells ('.') with '$'.
     */
    private static void dfs(int r, int c, int rows, int cols, char[][] grid) {
        // Boundary check
        if (!isValid(r, c, rows, cols)) {
            return;
        }

        char currentCell = grid[r][c];

        // Traverse only if the cell is walkable ('.'), not a wall ('#'), 
        // not already visited ('$'), and not a 'B' (Ball).
        // Note: 'B' cells are surrounded by walls due to pre-processing, 
        // so this check effectively prevents entering 'B' cells.
        if (currentCell != '#' && currentCell != '$' && currentCell != 'B') {
            grid[r][c] = '$'; // Mark as visited

            // Recursively visit neighbors
            dfs(r - 1, c, rows, cols, grid);
            dfs(r + 1, c, rows, cols, grid);
            dfs(r, c - 1, rows, cols, grid);
            dfs(r, c + 1, rows, cols, grid);
        }

        // Note: The original code contained a check `if (currentCell == 'B') possible=false;`
        // inside the DFS. This block was unreachable because the entry condition 
        // `currentCell != 'B'` prevents execution of the block containing the recursive calls,
        // and the logic flow places this check after the block. 
        // Furthermore, pre-processing ensures 'B' cells are isolated from '.' cells.
        // Therefore, this dead code has been removed to improve code quality.
    }
}

import java.io.*;
import java.util.*;

public class GridPathSolver {

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner();
        PrintWriter out = new PrintWriter(System.out);

        int testCases = scanner.nextInt();
        while (testCases-- > 0) {
            if (solve(scanner, out)) {
                out.println("Yes");
            } else {
                out.println("No");
            }
        }
        out.flush();
    }

    /**
     * Orchestrates the solution for a single test case.
     * Returns true if the grid configuration is valid and all 'G' cells can reach the bottom-right corner.
     */
    private static boolean solve(FastScanner scanner, PrintWriter out) {
        int rows = scanner.nextInt();
        int cols = scanner.nextInt();
        char[][] grid = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            grid[i] = scanner.next().toCharArray();
        }

        // Step 1: Validate adjacency rules and apply wall transformations
        if (!validateAndApplyWalls(grid, rows, cols)) {
            return false;
        }

        // Step 2: Ensure every 'G' cell can reach the target (rows-1, cols-1)
        boolean[][] visitedG = new boolean[rows][cols];
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == 'G' && !visitedG[r][c]) {
                    if (!canReachTarget(grid, rows, cols, r, c, visitedG)) {
                        return false;
                    }
                }
            }
        }
        return true;
    }

    /**
     * Checks if any 'B' is adjacent to 'G' (invalid).
     * Marks non-'B' neighbors of 'B' as walls '#'.
     */
    private static boolean validateAndApplyWalls(char[][] grid, int rows, int cols) {
        int[] dr = {-1, 1, 0, 0};
        int[] dc = {0, 0, -1, 1};

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == 'B') {
                    for (int i = 0; i < 4; i++) {
                        int nr = r + dr[i];
                        int nc = c + dc[i];
                        if (isWithinBounds(nr, nc, rows, cols)) {
                            if (grid[nr][nc] == 'G') {
                                return false; // Invalid: 'B' cannot be adjacent to 'G'
                            }
                            if (grid[nr][nc] != 'B') {
                                grid[nr][nc] = '#'; // Apply wall rule
                            }
                        }
                    }
                }
            }
        }
        return true;
    }

    /**
     * Performs BFS from a starting 'G' cell to check if the bottom-right corner is reachable.
     * Marks discovered 'G' cells in visitedG to avoid redundant BFS traversals.
     */
    private static boolean canReachTarget(char[][] grid, int rows, int cols, int startR, int startC, boolean[][] visitedG) {
        int[] dr = {-1, 1, 0, 0};
        int[] dc = {0, 0, -1, 1};

        Queue<int[]> queue = new ArrayDeque<>();
        queue.offer(new int[]{startR, startC});

        boolean[][] visited = new boolean[rows][cols];
        visited[startR][startC] = true;

        int targetR = rows - 1;
        int targetC = cols - 1;

        while (!queue.isEmpty()) {
            int[] curr = queue.poll();
            int r = curr[0];
            int c = curr[1];

            // Check if target reached
            if (r == targetR && c == targetC) {
                return true;
            }

            for (int i = 0; i < 4; i++) {
                int nr = r + dr[i];
                int nc = c + dc[i];

                if (isWithinBounds(nr, nc, rows, cols) && !visited[nr][nc] && grid[nr][nc] != '#') {
                    visited[nr][nc] = true;
                    if (grid[nr][nc] == 'G') {
                        visitedG[nr][nc] = true; // Mark connected 'G' components as visited
                    }
                    queue.offer(new int[]{nr, nc});
                }
            }
        }
        return false;
    }

    private static boolean isWithinBounds(int r, int c, int rows, int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /**
     * Optimized fast input reader for competitive programming scenarios.
     */
    static class FastScanner {
        private final BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        private StringTokenizer st = new StringTokenizer("");

        String next() {
            while (!st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Input reading failed", e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.*;
import java.util.*;

public class SolveTheMaze {

    // Grid traversal directions (Right, Down, Left, Up)
    private static final int[] ROW_DIRS = {0, 1, 0, -1};
    private static final int[] COL_DIRS = {1, 0, -1, 0};

    // Grid characters
    private static final char WALL = '#';
    private static final char BLOCK = 'B';
    private static final char GOAL = 'G';
    private static final char EMPTY = '.';

    /**
     * Encapsulates maze solving logic to avoid static state and improve maintainability.
     */
    static class MazeSolver {
        private final int rows;
        private final int cols;
        private final char[][] grid;
        private final boolean[][] visited;

        public MazeSolver(int rows, int cols, char[][] grid) {
            this.rows = rows;
            this.cols = cols;
            this.grid = grid;
            this.visited = new boolean[rows][cols];
        }

        public String solve() {
            if (isGoalAdjacentToBlock()) {
                return "No";
            }

            applyBlockExpansions();

            if (grid[rows - 1][cols - 1] == WALL) {
                return "No";
            }

            bfsFromBottomRight();

            return isGoalReachable() ? "Yes" : "No";
        }

        private boolean isGoalAdjacentToBlock() {
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] == BLOCK) {
                        for (int i = 0; i < 4; i++) {
                            int nr = r + ROW_DIRS[i];
                            int nc = c + COL_DIRS[i];
                            if (isValid(nr, nc) && grid[nr][nc] == GOAL) {
                                return true;
                            }
                        }
                    }
                }
            }
            return false;
        }

        private void applyBlockExpansions() {
            // Mark adjacent empty cells as walls. 
            // Safe to modify in-place as changing '.' to '#' doesn't affect 
            // the condition checks for other cells in this pass.
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] == BLOCK) {
                        for (int i = 0; i < 4; i++) {
                            int nr = r + ROW_DIRS[i];
                            int nc = c + COL_DIRS[i];
                            if (isValid(nr, nc) && grid[nr][nc] == EMPTY) {
                                grid[nr][nc] = WALL;
                            }
                        }
                    }
                }
            }
        }

        private void bfsFromBottomRight() {
            Queue<int[]> queue = new ArrayDeque<>();
            queue.offer(new int[]{rows - 1, cols - 1});
            visited[rows - 1][cols - 1] = true;

            while (!queue.isEmpty()) {
                int[] current = queue.poll();
                int r = current[0];
                int c = current[1];

                for (int i = 0; i < 4; i++) {
                    int nr = r + ROW_DIRS[i];
                    int nc = c + COL_DIRS[i];

                    if (isValid(nr, nc) && !visited[nr][nc] && grid[nr][nc] != WALL) {
                        visited[nr][nc] = true;
                        queue.offer(new int[]{nr, nc});
                    }
                }
            }
        }

        private boolean isGoalReachable() {
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] == GOAL && !visited[r][c]) {
                        return false;
                    }
                }
            }
            return true;
        }

        private boolean isValid(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }
    }

    /**
     * Fast I/O helper to handle large input efficiently without swallowing exceptions.
     */
    static class FastIO {
        private final BufferedReader br;
        private final PrintWriter out;
        private StringTokenizer st;

        public FastIO(InputStream in, OutputStream out) {
            this.br = new BufferedReader(new InputStreamReader(in));
            this.out = new PrintWriter(out);
        }

        public String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            String token = next();
            if (token == null) throw new NoSuchElementException("End of input");
            return Integer.parseInt(token);
        }

        public void println(String s) {
            out.println(s);
        }

        public void close() {
            out.flush();
            out.close();
        }
    }

    public static void main(String[] args) {
        FastIO io = new FastIO(System.in, System.out);
        int numTestCases = io.nextInt();

        for (int x = 0; x < numTestCases; x++) {
            int rows = io.nextInt();
            int cols = io.nextInt();
            char[][] grid = new char[rows][cols];

            for (int r = 0; r < rows; r++) {
                grid[r] = io.next().toCharArray();
            }

            MazeSolver solver = new MazeSolver(rows, cols, grid);
            io.println(solver.solve());
        }
        io.close();
    }
}

import java.io.*;
import java.math.BigInteger;
import java.util.*;

/**
 * Solves the maze problem by checking if all 'G' cells are reachable
 * from the bottom-right corner without passing through 'B' or blocked cells.
 */
public class Solve {

    // Direction vectors for moving up, down, left, right
    private static final int[] DR = {-1, 1, 0, 0};
    private static final int[] DC = {0, 0, -1, 1};

    public static void main(String[] args) {
        // Use try-with-resources to ensure proper closure of I/O streams
        try (FastScanner in = new FastScanner(System.in);
             PrintWriter out = new PrintWriter(System.out)) {
            new Solve(in, out).run();
        }
    }

    private final FastScanner in;
    private final PrintWriter out;

    public Solve(FastScanner in, PrintWriter out) {
        this.in = in;
        this.out = out;
    }

    public void run() {
        int t = in.nextInt();
        while (t-- > 0) {
            solve();
        }
        out.flush();
    }

    private void solve() {
        int rows = in.nextInt();
        int cols = in.nextInt();
        char[][] grid = new char[rows][cols];
        int totalGoals = 0;

        // Read grid and count total 'G' cells
        for (int r = 0; r < rows; r++) {
            String line = in.next();
            grid[r] = line.toCharArray();
            for (char c : line.toCharArray()) {
                if (c == 'G') {
                    totalGoals++;
                }
            }
        }

        // Mark cells adjacent to 'B' as blocked
        applyBlockers(grid, rows, cols);

        // Check if all goals are reachable from the bottom-right corner
        boolean result = bfs(grid, rows, cols, totalGoals);
        out.println(result ? "Yes" : "No");
    }

    /**
     * Marks all '.' cells adjacent to 'B' as '#' (blocked).
     */
    private void applyBlockers(char[][] grid, int rows, int cols) {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == 'B') {
                    for (int d = 0; d < 4; d++) {
                        int nr = r + DR[d];
                        int nc = c + DC[d];
                        if (isValid(nr, nc, rows, cols) && grid[nr][nc] == '.') {
                            grid[nr][nc] = '#';
                        }
                    }
                }
            }
        }
    }

    /**
     * Performs BFS from the bottom-right corner to check reachability.
     * Returns true if all 'G' cells are reachable and no 'B' cells are encountered.
     */
    private boolean bfs(char[][] grid, int rows, int cols, int totalGoals) {
        boolean[][] visited = new boolean[rows][cols];
        int goalsFound = 0;
        int blockersFound = 0;

        Queue<Point> queue = new ArrayDeque<>();
        int startR = rows - 1;
        int startC = cols - 1;

        // Start BFS only from '.' cells (preserving original logic)
        if (grid[startR][startC] == '.') {
            queue.add(new Point(startR, startC));
            visited[startR][startC] = true;
        }

        while (!queue.isEmpty()) {
            Point curr = queue.poll();
            char cell = grid[curr.r][curr.c];

            if (cell == 'G') {
                goalsFound++;
            } else if (cell == 'B') {
                blockersFound++;
            }

            for (int d = 0; d < 4; d++) {
                int nr = curr.r + DR[d];
                int nc = curr.c + DC[d];
                if (isValid(nr, nc, rows, cols) && !visited[nr][nc] && grid[nr][nc] != '#') {
                    queue.add(new Point(nr, nc));
                    visited[nr][nc] = true;
                }
            }
        }

        return goalsFound == totalGoals && blockersFound == 0;
    }

    private boolean isValid(int r, int c, int rows, int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /**
     * Represents a coordinate in the grid.
     */
    private static class Point {
        final int r, c;

        Point(int r, int c) {
            this.r = r;
            this.c = c;
        }
    }

    /**
     * Fast I/O scanner for competitive programming.
     */
    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner(File f) {
            try {
                this.br = new BufferedReader(new FileReader(f));
            } catch (FileNotFoundException e) {
                throw new RuntimeException("File not found: " + f.getAbsolutePath(), e);
            }
        }

        public FastScanner(InputStream in) {
            this.br = new BufferedReader(new InputStreamReader(in));
        }

        private void ensureTokens() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) {
                    st = null;
                    return;
                }
                st = new StringTokenizer(line);
            }
        }

        public String next() {
            try {
                ensureTokens();
                if (st == null) throw new EOFException("End of input stream");
                return st.nextToken();
            } catch (IOException e) {
                throw new RuntimeException("Error reading from input stream", e);
            }
        }

        public boolean hasMoreTokens() {
            try {
                ensureTokens();
                return st != null && st.hasMoreTokens();
            } catch (IOException e) {
                throw new RuntimeException("Error reading from input stream", e);
            }
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }

        public double nextDouble() {
            return Double.parseDouble(next());
        }

        public BigInteger nextBigInteger() {
            return new BigInteger(next());
        }
    }
}

import java.util.*;
import java.io.*;

public class Main {
    // Grid character constants for better readability and maintainability
    private static final char WALL = '#';
    private static final char GOAL = 'G';
    private static final char BLOCKER = 'B';
    private static final char EMPTY = '.';

    // Direction vectors: right, left, down, up
    private static final int[][] DIRECTIONS = {{0, 1}, {0, -1}, {1, 0}, {-1, 0}};

    public static void main(String[] args) {
        Scanner scanner = new Scanner(new BufferedReader(new InputStreamReader(System.in)));
        int testCases = scanner.nextInt();

        for (int t = 1; t <= testCases; t++) {
            solve(scanner);
        }
        scanner.close();
    }

    private static void solve(Scanner scanner) {
        int rows = scanner.nextInt();
        int cols = scanner.nextInt();
        char[][] grid = new char[rows][cols];

        for (int i = 0; i < rows; i++) {
            grid[i] = scanner.next().toCharArray();
        }

        List<int[]> goalCells = new ArrayList<>();

        // Process grid: handle blockers and collect goal positions
        if (!processGrid(grid, rows, cols, goalCells)) {
            System.out.println("No");
            return;
        }

        // If the destination is blocked, all goals must be unreachable for "Yes"
        if (grid[rows - 1][cols - 1] == WALL) {
            System.out.println(goalCells.isEmpty() ? "Yes" : "No");
            return;
        }

        // BFS to determine reachable cells from the destination
        boolean[][] visited = new boolean[rows][cols];
        bfs(grid, rows, cols, goalCells, visited);
    }

    private static boolean processGrid(char[][] grid, int rows, int cols, List<int[]> goalCells) {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == BLOCKER) {
                    for (int[] dir : DIRECTIONS) {
                        int nr = i + dir[0];
                        int nc = j + dir[1];
                        if (isValid(nr, nc, rows, cols)) {
                            if (grid[nr][nc] == GOAL) {
                                return false; // Invalid configuration: blocker adjacent to goal
                            } else if (grid[nr][nc] == EMPTY) {
                                grid[nr][nc] = WALL; // Block adjacent empty cells
                            }
                        }
                    }
                } else if (grid[i][j] == GOAL) {
                    goalCells.add(new int[]{i, j});
                }
            }
        }
        return true;
    }

    private static void bfs(char[][] grid, int rows, int cols, List<int[]> goalCells, boolean[][] visited) {
        Queue<int[]> queue = new ArrayDeque<>();
        int startRow = rows - 1;
        int startCol = cols - 1;

        queue.add(new int[]{startRow, startCol});
        visited[startRow][startCol] = true;

        while (!queue.isEmpty()) {
            int[] current = queue.poll();
            for (int[] dir : DIRECTIONS) {
                int nextRow = current[0] + dir[0];
                int nextCol = current[1] + dir[1];

                if (isValid(nextRow, nextCol, rows, cols)
                        && grid[nextRow][nextCol] != WALL
                        && !visited[nextRow][nextCol]) {
                    visited[nextRow][nextCol] = true;
                    queue.add(new int[]{nextRow, nextCol});
                }
            }
        }

        // Check if all goal cells are reachable
        for (int[] goal : goalCells) {
            if (!visited[goal[0]][goal[1]]) {
                System.out.println("No");
                return;
            }
        }
        System.out.println("Yes");
    }

    private static boolean isValid(int r, int c, int rows, int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }
}

import java.io.*;
import java.util.*;

public class ProblemD {

    // Direction vectors for moving up, down, left, right
    private static final int[] DX = {1, -1, 0, 0};
    private static final int[] DY = {0, 0, 1, -1};

    public static void main(String[] args) {
        FastScanner in = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out);

        int T = in.nextInt();
        while (T-- > 0) {
            int N = in.nextInt();
            int M = in.nextInt();
            char[][] maze = new char[N][M];
            for (int i = 0; i < N; i++) {
                String line = in.next();
                maze[i] = line.toCharArray();
            }

            Solver solver = new Solver(N, M, maze);
            out.println(solver.solve() ? "Yes" : "No");
        }
        out.flush();
    }

    /**
     * Encapsulates all game logic and state to avoid static coupling and improve testability.
     */
    static class Solver {
        private final int N, M;
        private final char[][] maze;
        private boolean[][] visited;

        public Solver(int N, int M, char[][] maze) {
            this.N = N;
            this.M = M;
            this.maze = maze;
            this.visited = new boolean[N][M];
        }

        public boolean solve() {
            // Step 1: Verify that no 'B' can reach any 'G'.
            // During this pass, reachable '.' cells are permanently blocked ('#') to prevent path reuse.
            for (int i = 0; i < N; i++) {
                for (int j = 0; j < M; j++) {
                    if (maze[i][j] == 'B') {
                        if (!bfsFromB(i, j)) {
                            return false;
                        }
                    }
                }
            }

            // Step 2: Verify that the goal (bottom-right) can reach all 'G's 
            // without passing through any 'B'.
            return bfsFromGoal(N - 1, M - 1);
        }

        /**
         * BFS starting from a 'B' position.
         * Returns true if no 'G' is reachable. Permanently marks reachable '.' as '#' to block paths.
         */
        private boolean bfsFromB(int startX, int startY) {
            Queue<Point> queue = new ArrayDeque<>();
            visited[startX][startY] = true;
            queue.add(new Point(startX, startY));

            while (!queue.isEmpty()) {
                Point curr = queue.poll();
                for (int d = 0; d < 4; d++) {
                    int nx = curr.x + DX[d];
                    int ny = curr.y + DY[d];

                    if (!isValid(nx, ny) || visited[nx][ny]) {
                        continue;
                    }

                    char cell = maze[nx][ny];
                    if (cell == '.') {
                        maze[nx][ny] = '#'; // Block reachable empty space
                    } else if (cell == 'G') {
                        return false; // 'G' is reachable from this 'B'
                    } else if (cell == 'B') {
                        visited[nx][ny] = true;
                        queue.add(new Point(nx, ny));
                    }
                    // '#' cells are ignored
                }
            }
            return true; // No 'G' reachable from this 'B'
        }

        /**
         * BFS starting from the goal position.
         * Returns true if all 'G's are reachable without passing through any 'B'.
         */
        private boolean bfsFromGoal(int startX, int startY) {
            if (maze[startX][startY] == '#') {
                return checkAllGsVisited();
            }

            // Reset visited array for this independent traversal
            visited = new boolean[N][M];
            Queue<Point> queue = new ArrayDeque<>();
            visited[startX][startY] = true;
            queue.add(new Point(startX, startY));

            while (!queue.isEmpty()) {
                Point curr = queue.poll();
                for (int d = 0; d < 4; d++) {
                    int nx = curr.x + DX[d];
                    int ny = curr.y + DY[d];

                    if (!isValid(nx, ny) || visited[nx][ny]) {
                        continue;
                    }

                    char cell = maze[nx][ny];
                    if (cell == '.' || cell == 'G') {
                        visited[nx][ny] = true;
                        queue.add(new Point(nx, ny));
                    } else if (cell == '#') {
                        continue;
                    } else if (cell == 'B') {
                        return false; // 'B' is reachable from goal
                    }
                }
            }
            return checkAllGsVisited();
        }

        /**
         * Checks if every 'G' in the grid has been marked as visited.
         */
        private boolean checkAllGsVisited() {
            for (int i = 0; i < N; i++) {
                for (int j = 0; j < M; j++) {
                    if (maze[i][j] == 'G' && !visited[i][j]) {
                        return false;
                    }
                }
            }
            return true;
        }

        /**
         * Validates grid boundaries.
         */
        private boolean isValid(int x, int y) {
            return x >= 0 && x < N && y >= 0 && y < M;
        }
    }

    /**
     * Immutable coordinate class replacing the original Pair.
     */
    static class Point {
        final int x, y;

        Point(int x, int y) {
            this.x = x;
            this.y = y;
        }
    }

    /**
     * Robust fast I/O helper replacing the original InputReader.
     * Handles whitespace/newlines correctly and avoids NullPointerExceptions.
     */
    static class FastScanner {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastScanner(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) throw new EOFException("Unexpected end of input");
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("I/O error", e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Solves grid traversal problems with goals, walls, and blocked cells.
 * Refactored for maintainability, safety, and readability.
 */
public class MazeSolver {

    // Grid cell type constants for clarity and maintainability
    private static final int WALL = 0;
    private static final int EMPTY = 1;
    private static final int GOAL = 2;
    private static final int BLOCKED = 3;

    private int rows;
    private int cols;
    private int[][] grid;
    private boolean[][] visited;
    private int goalCount;

    /**
     * Entry point for solving all test cases.
     */
    public void solve() throws IOException {
        FastScanner scanner = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out));

        int t = scanner.nextInt();
        while (t-- > 0) {
            rows = scanner.nextInt();
            cols = scanner.nextInt();

            grid = new int[rows][cols];
            visited = new boolean[rows][cols];
            goalCount = 0;

            // Parse the grid
            for (int i = 0; i < rows; i++) {
                String line = scanner.next();
                for (int j = 0; j < cols; j++) {
                    char c = line.charAt(j);
                    if (c == '#') {
                        grid[i][j] = WALL;
                    } else if (c == '.') {
                        grid[i][j] = EMPTY;
                    } else if (c == 'G') {
                        grid[i][j] = GOAL;
                        goalCount++;
                    } else {
                        // Represents the original -1 type cell
                        grid[i][j] = BLOCKED;
                    }
                }
            }

            // Propagate blocked cells: neighbors of blocked cells become walls
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j] == BLOCKED) {
                        markNeighborsAsWalls(i, j);
                    }
                }
            }

            // Start DFS from bottom-right cell if it's not a wall
            if (grid[rows - 1][cols - 1] != WALL) {
                dfsIterative(rows - 1, cols - 1);
            }

            // Validate traversal results
            boolean allGoalsReachable = true;
            boolean noBlockedVisited = true;

            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j] == GOAL && !visited[i][j]) {
                        allGoalsReachable = false;
                    }
                    if (grid[i][j] == BLOCKED && visited[i][j]) {
                        noBlockedVisited = false;
                    }
                }
            }

            out.println(allGoalsReachable && noBlockedVisited ? "Yes" : "No");
        }
        out.flush();
    }

    /**
     * Checks if a cell is within bounds, unvisited, and not a wall.
     */
    private boolean isValid(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols
                && grid[r][c] != WALL && !visited[r][c];
    }

    /**
     * Iterative DFS to mark all reachable cells from the start position.
     * Uses an explicit stack to prevent StackOverflowError on large grids.
     */
    private void dfsIterative(int startR, int startC) {
        Deque<int[]> stack = new ArrayDeque<>();
        stack.push(new int[]{startR, startC});
        visited[startR][startC] = true;

        int[] dr = {-1, 1, 0, 0};
        int[] dc = {0, 0, -1, 1};

        while (!stack.isEmpty()) {
            int[] curr = stack.pop();
            int r = curr[0];
            int c = curr[1];

            for (int i = 0; i < 4; i++) {
                int nr = r + dr[i];
                int nc = c + dc[i];
                if (isValid(nr, nc)) {
                    visited[nr][nc] = true;
                    stack.push(new int[]{nr, nc});
                }
            }
        }
    }

    /**
     * Marks valid neighbors of a blocked cell as walls.
     * Preserves goals and other blocked cells as per original logic.
     */
    private void markNeighborsAsWalls(int r, int c) {
        int[] dr = {-1, 1, 0, 0};
        int[] dc = {0, 0, -1, 1};
        for (int i = 0; i < 4; i++) {
            int nr = r + dr[i];
            int nc = c + dc[i];
            if (nr >= 0 && nr < rows && nc >= 0 && nc < cols
                    && grid[nr][nc] != BLOCKED && grid[nr][nc] != GOAL) {
                grid[nr][nc] = WALL;
            }
        }
    }

    /**
     * Fast I/O helper class for competitive programming style inputs.
     */
    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }
    }

    public static void main(String[] args) throws IOException {
        new MazeSolver().solve();
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

/**
 * Solves the dungeon exploration problem.
 * Determines if all 'Good' items ('G') are reachable from the bottom-right corner,
 * avoiding obstacles ('#') and bomb zones ('B').
 */
public class DungeonSolver {

    // Constants for grid characters to improve readability and maintainability
    private static final char OBSTACLE = '#';
    private static final char BOMB = 'B';
    private static final char GOOD_ITEM = 'G';

    public static void main(String[] args) throws IOException {
        // Use try-with-resources to ensure the BufferedReader is closed automatically
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(System.in))) {
            String line = reader.readLine();
            if (line == null || line.trim().isEmpty()) {
                return;
            }

            int numTestCases;
            try {
                numTestCases = Integer.parseInt(line.trim());
            } catch (NumberFormatException e) {
                // Gracefully handle malformed input
                return;
            }

            for (int i = 0; i < numTestCases; i++) {
                solveTestCase(reader);
            }
        }
    }

    /**
     * Processes a single test case from the input.
     */
    private static void solveTestCase(BufferedReader reader) throws IOException {
        // Read dimensions, skipping potential empty lines
        String line = reader.readLine();
        while (line != null && line.trim().isEmpty()) {
            line = reader.readLine();
        }

        if (line == null) return;

        StringTokenizer st = new StringTokenizer(line);
        if (!st.hasMoreTokens()) return;

        int rows = Integer.parseInt(st.nextToken());
        int cols = Integer.parseInt(st.nextToken());

        // Initialize arrays
        char[][] grid = new char[rows][];
        boolean[][] isBlocked = new boolean[rows][];
        boolean[][] visited = new boolean[rows][];

        // Read grid data and initialize boolean arrays
        for (int r = 0; r < rows; r++) {
            isBlocked[r] = new boolean[cols];
            visited[r] = new boolean[cols];

            String rowStr = reader.readLine();
            if (rowStr != null) {
                grid[r] = rowStr.toCharArray();
            } else {
                grid[r] = new char[0]; // Handle unexpected EOF safely
            }
        }

        // Process grid to identify blocked cells and count total good items
        int totalGoodItems = 0;
        for (int r = 0; r < rows; r++) {
            int currentRowLen = (grid[r] != null) ? grid[r].length : 0;

            for (int c = 0; c < cols; c++) {
                // Safety check for malformed rows (shorter than cols)
                if (c >= currentRowLen) break;

                char cell = grid[r][c];
                if (cell == OBSTACLE) {
                    isBlocked[r][c] = true;
                } else if (cell == BOMB) {
                    isBlocked[r][c] = true;
                    markBombImpact(r, c, rows, cols, isBlocked);
                } else if (cell == GOOD_ITEM) {
                    totalGoodItems++;
                }
            }
        }

        // Start search from bottom-right corner (rows-1, cols-1)
        // The search method handles bounds checking internally
        int reachableGoodItems = countReachableGoods(rows - 1, cols - 1, isBlocked, visited, grid);

        System.out.println(reachableGoodItems == totalGoodItems ? "Yes" : "No");
    }

    /**
     * Marks the cells adjacent to a bomb as blocked.
     */
    private static void markBombImpact(int r, int c, int rows, int cols, boolean[][] isBlocked) {
        int[] dr = {-1, 1, 0, 0};
        int[] dc = {0, 0, -1, 1};

        for (int i = 0; i < 4; i++) {
            int nr = r + dr[i];
            int nc = c + dc[i];

            if (nr >= 0 && nr < rows && nc >= 0 && nc < cols) {
                isBlocked[nr][nc] = true;
            }
        }
    }

    /**
     * Recursively counts reachable 'Good' items using DFS.
     * Returns the count of found items.
     * 
     * @param r Current row index
     * @param c Current column index
     * @param isBlocked 2D array marking blocked cells
     * @param visited 2D array tracking visited cells to prevent cycles
     * @param grid The character grid
     * @return Number of reachable 'G' items from this position
     */
    private static int countReachableGoods(int r, int c, boolean[][] isBlocked, boolean[][] visited, char[][] grid) {
        // Boundary checks
        if (r < 0 || c < 0 || r >= grid.length || c >= grid[r].length) {
            return 0;
        }

        // Check if already visited or blocked
        if (visited[r][c] || isBlocked[r][c]) {
            return 0;
        }

        visited[r][c] = true;
        int count = (grid[r][c] == GOOD_ITEM) ? 1 : 0;

        // Explore neighbors (Up, Down, Left, Right)
        count += countReachableGoods(r - 1, c, isBlocked, visited, grid);
        count += countReachableGoods(r + 1, c, isBlocked, visited, grid);
        count += countReachableGoods(r, c - 1, isBlocked, visited, grid);
        count += countReachableGoods(r, c + 1, isBlocked, visited, grid);

        return count;
    }
}

import java.io.*;
import java.util.*;

public class GridEscapeSolver {
    // Direction vectors for Up, Right, Down, Left
    private static final int[] DR = {-1, 0, 1, 0};
    private static final int[] DC = {0, 1, 0, -1};

    public static void main(String[] args) throws IOException {
        FastScanner scanner = new FastScanner(System.in);
        // Buffered output improves performance for large volumes of data
        PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out));

        try {
            int t = scanner.nextInt();
            for (int i = 0; i < t; i++) {
                int n = scanner.nextInt();
                int m = scanner.nextInt();

                char[][] maze = new char[n][m];
                for (int r = 0; r < n; r++) {
                    maze[r] = scanner.next().toCharArray();
                }

                out.println(solve(n, m, maze) ? "Yes" : "No");
            }
        } finally {
            out.flush();
            out.close();
        }
    }

    /**
     * Evaluates whether all 'G' cells are reachable from the bottom-right corner
     * after applying 'B' cell blocking rules.
     */
    private static boolean solve(int n, int m, char[][] maze) {
        // Phase 1: Process 'B' cells
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < m; c++) {
                if (maze[r][c] == 'B') {
                    for (int d = 0; d < 4; d++) {
                        int nr = r + DR[d];
                        int nc = c + DC[d];

                        if (isValid(nr, nc, n, m)) {
                            if (maze[nr][nc] == 'G') {
                                return false; // 'G' is directly adjacent to 'B'
                            } else if (maze[nr][nc] == '.') {
                                maze[nr][nc] = '#'; // Block adjacent empty cells
                            }
                        }
                    }
                }
            }
        }

        // Phase 2: BFS from bottom-right corner to find reachable cells
        boolean[][] reachable = new boolean[n][m];
        Queue<int[]> queue = new ArrayDeque<>();

        // Start BFS if the destination is not blocked
        if (isValid(n - 1, m - 1, n, m) && maze[n - 1][m - 1] != '#') {
            reachable[n - 1][m - 1] = true;
            queue.offer(new int[]{n - 1, m - 1});
        }

        while (!queue.isEmpty()) {
            int[] curr = queue.poll();
            int r = curr[0];
            int c = curr[1];

            for (int d = 0; d < 4; d++) {
                int nr = r + DR[d];
                int nc = c + DC[d];

                if (isValid(nr, nc, n, m) && !reachable[nr][nc]) {
                    char cell = maze[nr][nc];
                    if (cell == '.' || cell == 'G') {
                        reachable[nr][nc] = true;
                        queue.offer(new int[]{nr, nc});
                    }
                }
            }
        }

        // Phase 3: Verify all 'G' cells are reachable
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < m; c++) {
                if (maze[r][c] == 'G' && !reachable[r][c]) {
                    return false;
                }
            }
        }

        return true;
    }

    private static boolean isValid(int r, int c, int n, int m) {
        return r >= 0 && r < n && c >= 0 && c < m;
    }

    /**
     * Fast input reader for competitive programming / large I/O scenarios.
     */
    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        public String next() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) throw new EOFException("End of input stream");
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}

import java.io.*;
import java.util.*;

public class Main {
    // Direction vectors: Up, Left, Down, Right
    private static final int[] DX = {-1, 0, 1, 0};
    private static final int[] DY = {0, -1, 0, 1};

    public static void main(String[] args) {
        FastScanner sc = new FastScanner();
        PrintWriter out = new PrintWriter(System.out);

        try {
            int t = sc.nextInt();
            while (t-- > 0) {
                solve(sc, out);
            }
        } catch (Exception e) {
            e.printStackTrace();
        } finally {
            out.flush();
        }
    }

    /**
     * Processes a single test case.
     */
    private static void solve(FastScanner sc, PrintWriter out) {
        int n = sc.nextInt();
        int m = sc.nextInt();
        char[][] grid = new char[n][m];
        int totalG = 0;

        // Read grid and count total 'G' cells
        for (int i = 0; i < n; i++) {
            String row = sc.next();
            grid[i] = row.toCharArray();
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == 'G') {
                    totalG++;
                }
            }
        }

        // If no 'G' exists, the condition is trivially satisfied
        if (totalG == 0) {
            out.println("Yes");
            return;
        }

        // Step 1: Find all 'B' cells reachable from the bottom-right corner
        List<int[]> reachableB = bfsFindReachableB(n, m, grid);

        // Step 2: Block the found 'B' cells and their valid neighbors
        blockCells(grid, reachableB);

        // Step 3: Check if the starting position (bottom-right) is blocked
        boolean startUnblocked = grid[n - 1][m - 1] != '#';

        // Step 4: Check if all 'G' cells are still reachable from the bottom-right
        int reachableGCount = bfsCountReachableG(n, m, grid);
        boolean allGReachable = (reachableGCount == totalG);

        out.println((startUnblocked && allGReachable) ? "Yes" : "No");
    }

    /**
     * Performs BFS from the bottom-right corner to find all reachable 'B' cells.
     */
    private static List<int[]> bfsFindReachableB(int n, int m, char[][] grid) {
        boolean[][] visited = new boolean[n][m];
        // Array-based queue for performance (avoids autoboxing overhead)
        int[] queue = new int[n * m * 2];
        int head = 0, tail = 0;

        queue[tail++] = n - 1;
        queue[tail++] = m - 1;
        visited[n - 1][m - 1] = true;

        List<int[]> reachableB = new ArrayList<>();

        while (head < tail) {
            int x = queue[head++];
            int y = queue[head++];

            if (grid[x][y] == 'B') {
                reachableB.add(new int[]{x, y});
            }

            for (int k = 0; k < 4; k++) {
                int nx = x + DX[k];
                int ny = y + DY[k];
                if (isValid(nx, ny, n, m) && !visited[nx][ny] && grid[nx][ny] != '#') {
                    visited[nx][ny] = true;
                    queue[tail++] = nx;
                    queue[tail++] = ny;
                }
            }
        }
        return reachableB;
    }

    /**
     * Performs BFS from the bottom-right corner to count reachable 'G' cells.
     */
    private static int bfsCountReachableG(int n, int m, char[][] grid) {
        boolean[][] visited = new boolean[n][m];
        int[] queue = new int[n * m * 2];
        int head = 0, tail = 0;

        queue[tail++] = n - 1;
        queue[tail++] = m - 1;
        visited[n - 1][m - 1] = true;

        int reachableGCount = 0;

        while (head < tail) {
            int x = queue[head++];
            int y = queue[head++];

            if (grid[x][y] == 'G') {
                reachableGCount++;
            }

            for (int k = 0; k < 4; k++) {
                int nx = x + DX[k];
                int ny = y + DY[k];
                if (isValid(nx, ny, n, m) && !visited[nx][ny] && grid[nx][ny] != '#') {
                    visited[nx][ny] = true;
                    queue[tail++] = nx;
                    queue[tail++] = ny;
                }
            }
        }
        return reachableGCount;
    }

    /**
     * Marks the given 'B' cells and their valid neighbors as obstacles ('#').
     */
    private static void blockCells(char[][] grid, List<int[]> reachableB) {
        int n = grid.length;
        int m = grid[0].length;

        for (int[] pos : reachableB) {
            int x = pos[0];
            int y = pos[1];

            // Block valid neighbors
            for (int k = 0; k < 4; k++) {
                int nx = x + DX[k];
                int ny = y + DY[k];
                if (isValid(nx, ny, n, m) && grid[nx][ny] != '#') {
                    grid[nx][ny] = '#';
                }
            }

            // Block the 'B' cell itself
            grid[x][y] = '#';
        }
    }

    /**
     * Checks if coordinates are within grid bounds.
     */
    private static boolean isValid(int x, int y, int n, int m) {
        return x >= 0 && x < n && y >= 0 && y < m;
    }

    /**
     * Fast I/O helper class for competitive programming.
     */
    static class FastScanner {
        BufferedReader br;
        StringTokenizer st;

        public FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    e.printStackTrace();
                    return null;
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            String s = next();
            return s == null ? 0 : Integer.parseInt(s);
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.LinkedList;
import java.util.Queue;
import java.util.StringTokenizer;

/**
 * Refactored Solution class for improved maintainability and code quality.
 * 
 * Improvements made:
 * 1. Extracted magic numbers/characters into named constants.
 * 2. Separated concerns: I/O handling in main, logic in solve().
 * 3. Removed unused code (printMat).
 * 4. Replaced int[] arrays in Queue with a dedicated Point class for readability.
 * 5. Improved input parsing robustness.
 * 6. Added JavaDoc and comments.
 */
public class Solution {

    // Constants for grid characters
    private static final char BLOCK_CHAR = 'B';
    private static final char GREEN_CHAR = 'G';
    private static final char OBSTACLE_CHAR = '#';
    private static final char EMPTY_CHAR = '.';

    // Constants for output strings
    private static final String RESULT_YES = "Yes";
    private static final String RESULT_NO = "No";

    // Direction vectors: Right, Left, Down, Up
    private static final int[][] DIRECTIONS = {
        {0, 1}, {0, -1}, {1, 0}, {-1, 0}
    };

    public static void main(String[] args) throws IOException {
        // Use try-with-resources for automatic resource management
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            String line = br.readLine();
            if (line == null || line.trim().isEmpty()) {
                return;
            }

            int T;
            try {
                T = Integer.parseInt(line.trim());
            } catch (NumberFormatException e) {
                return;
            }

            StringBuilder output = new StringBuilder();

            for (int t = 0; t < T; t++) {
                // Read n and m
                // Use StringTokenizer to handle potential whitespace issues
                String lineNM = br.readLine();
                while (lineNM != null && lineNM.trim().isEmpty()) {
                    lineNM = br.readLine();
                }

                if (lineNM == null) break;

                StringTokenizer st = new StringTokenizer(lineNM);
                if (!st.hasMoreTokens()) break;
                int n = Integer.parseInt(st.nextToken());

                if (!st.hasMoreTokens()) {
                     // In case m is on the next line or missing, though standard input usually guarantees format
                     // For robustness in a general context, we might need to read again, 
                     // but sticking to original assumption for CP problems.
                     // If this throws, input is malformed.
                }
                int m = Integer.parseInt(st.nextToken());

                char[][] grid = new char[n][m];
                for (int i = 0; i < n; i++) {
                    String row = br.readLine();
                    if (row != null) {
                        // Fill the row, handling potential length mismatch safely
                        for (int j = 0; j < m && j < row.length(); j++) {
                            grid[i][j] = row.charAt(j);
                        }
                    }
                }

                boolean isPossible = solve(grid, n, m);
                output.append(isPossible ? RESULT_YES : RESULT_NO).append("\n");
            }
            System.out.println(output);
        }
    }

    /**
     * Solves the problem for a single test case.
     * 
     * Logic:
     * 1. Process the grid to apply blocking rules from 'B' cells.
     *    - 'B' cells block adjacent non-'B' cells (turning them into obstacles '#').
     *    - If a 'B' cell is adjacent to a 'G' cell, the configuration is invalid (return false).
     * 2. Perform BFS starting from the bottom-right corner (n-1, m-1) if it is an empty cell ('.').
     * 3. Check if all 'G' cells in the grid were visited during BFS.
     */
    private static boolean solve(char[][] grid, int rows, int cols) {
        // Step 1: Apply blocking logic
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == BLOCK_CHAR) {
                    for (int[] d : DIRECTIONS) {
                        int nr = r + d[0];
                        int nc = c + d[1];

                        if (isValid(nr, nc, rows, cols)) {
                            if (grid[nr][nc] == GREEN_CHAR) {
                                return false; // Green cell is blocked by Black
                            }
                            // If not Black, it becomes an obstacle
                            if (grid[nr][nc] != BLOCK_CHAR) {
                                grid[nr][nc] = OBSTACLE_CHAR;
                            }
                        }
                    }
                }
            }
        }

        // Step 2: BFS Initialization
        // Original logic restricts start to empty cell '.'
        if (grid[rows - 1][cols - 1] != EMPTY_CHAR) {
            // If start is not empty, BFS queue remains empty.
            // We must check if there are any Greens. If so, we can't reach them.
            if (countGreens(grid, rows, cols) > 0) {
                return false;
            }
            return true;
        }

        boolean[][] visited = new boolean[rows][cols];
        Queue<Point> queue = new LinkedList<>();

        // Add start point
        Point start = new Point(rows - 1, cols - 1);
        queue.add(start);
        visited[rows - 1][cols - 1] = true;

        // Count total greens to verify reachability later
        int greenCount = countGreens(grid, rows, cols);
        if (greenCount == 0) return true;

        int visitedGreenCount = 0;

        // Step 3: BFS Execution
        while (!queue.isEmpty()) {
            Point current = queue.poll();

            // If current cell is Green, increment counter
            if (grid[current.r][current.c] == GREEN_CHAR) {
                visitedGreenCount++;
            }

            // Explore neighbors
            for (int[] d : DIRECTIONS) {
                int nr = current.r + d[0];
                int nc = current.c + d[1];

                if (isValid(nr, nc, rows, cols) && !visited[nr][nc] && grid[nr][nc] != OBSTACLE_CHAR) {
                    visited[nr][nc] = true;
                    queue.add(new Point(nr, nc));
                }
            }
        }

        // Step 4: Validation
        // Check if all Greens were visited
        return visitedGreenCount == greenCount;
    }

    private static boolean isValid(int r, int c, int rows, int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    private static int countGreens(char[][] grid, int rows, int cols) {
        int count = 0;
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == GREEN_CHAR) {
                    count++;
                }
            }
        }
        return count;
    }

    /**
     * Helper class to represent a coordinate in the grid.
     */
    private static class Point {
        int r, c;

        Point(int r, int c) {
            this.r = r;
            this.c = c;
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;

public class D1365 {
    // Constants for grid cells and movement directions
    private static final int[][] DIRECTIONS = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};
    private static final char CELL_BLACK = 'B';
    private static final char CELL_GREEN = 'G';
    private static final char CELL_WALL = '#';

    public static void main(String[] args) {
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            String line = br.readLine();
            if (line == null) return;

            int testCases = Integer.parseInt(line.trim());
            while (testCases-- > 0) {
                String[] dims = br.readLine().trim().split("\\s+");
                int rows = Integer.parseInt(dims[0]);
                int cols = Integer.parseInt(dims[1]);

                char[][] grid = new char[rows][cols];
                for (int i = 0; i < rows; i++) {
                    String rowStr = br.readLine();
                    if (rowStr != null) {
                        for (int j = 0; j < cols; j++) {
                            grid[i][j] = rowStr.charAt(j);
                        }
                    }
                }

                boolean result = solve(grid, rows, cols);
                System.out.println(result ? "Yes" : "No");
            }
        } catch (IOException e) {
            System.err.println("I/O error: " + e.getMessage());
        } catch (NumberFormatException e) {
            System.err.println("Invalid number format: " + e.getMessage());
        } catch (Exception e) {
            System.err.println("Unexpected error: " + e.getMessage());
        }
    }

    /**
     * Solves the grid problem by processing 'B' cells, performing reachability analysis,
     * and verifying if all 'G' cells are accessible from the bottom-right corner.
     */
    private static boolean solve(char[][] grid, int rows, int cols) {
        if (rows == 0 || cols == 0) return false;

        // Step 1: Process 'B' cells to identify invalid configurations and create walls
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == CELL_BLACK) {
                    for (int[] dir : DIRECTIONS) {
                        int ni = i + dir[0];
                        int nj = j + dir[1];
                        if (isValid(ni, nj, rows, cols)) {
                            if (grid[ni][nj] == CELL_GREEN) {
                                return false; // 'B' adjacent to 'G' makes the configuration invalid
                            } else if (grid[ni][nj] != CELL_BLACK) {
                                grid[ni][nj] = CELL_WALL; // Convert non-'B' neighbors to walls
                            }
                        }
                    }
                }
            }
        }

        // Step 2: Perform DFS from the bottom-right corner to find all reachable cells
        boolean[][] visited = new boolean[rows][cols];
        dfs(rows - 1, cols - 1, grid, visited);

        // Step 3: Verify that all 'G' cells are reachable from the bottom-right corner
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == CELL_GREEN && !visited[i][j]) {
                    return false;
                }
            }
        }
        return true;
    }

    private static boolean isValid(int r, int c, int rows, int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /**
     * Standard recursive DFS to mark all reachable non-wall cells.
     */
    private static void dfs(int r, int c, char[][] grid, boolean[][] visited) {
        // Base case: out of bounds, already visited, or blocked by a wall
        if (!isValid(r, c, grid.length, grid[0].length) || visited[r][c] || grid[r][c] == CELL_WALL) {
            return;
        }
        visited[r][c] = true;
        for (int[] dir : DIRECTIONS) {
            dfs(r + dir[0], c + dir[1], grid, visited);
        }
    }
}

import java.io.BufferedReader;
import java.io.BufferedWriter;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.OutputStreamWriter;
import java.util.Arrays;

/**
 * Refactored solution for the maze pathfinding problem.
 * 
 * Improvements made:
 * 1. Encapsulation: Logic moved out of main into a dedicated method.
 * 2. State Management: Removed static global grid; grid is allocated dynamically per test case.
 * 3. Constants: Used named constants for cell states and direction vectors.
 * 4. Readability: Renamed variables (e.g., rowCnt -> rows, j -> r) and removed debug code.
 * 5. Robustness: Improved input parsing and boundary handling.
 */
public class MazeSolver {

    // Direction vectors: Down, Right, Up, Left
    private static final int[] DR = {1, 0, -1, 0};
    private static final int[] DC = {0, 1, 0, -1};

    // Cell states
    private static final int STATE_EMPTY = 0;
    private static final int STATE_WALL = 1;
    private static final int STATE_GOAL = 2;

    public static void main(String[] args) throws IOException {
        // Use try-with-resources for automatic resource management
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
             BufferedWriter bw = new BufferedWriter(new OutputStreamWriter(System.out))) {

            String line = br.readLine();
            if (line != null && !line.trim().isEmpty()) {
                int testCases = Integer.parseInt(line.trim());

                for (int i = 0; i < testCases; i++) {
                    solveTestCase(br, bw);
                }
            }
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    private static void solveTestCase(BufferedReader br, BufferedWriter bw) throws IOException {
        // Read dimensions
        String line = br.readLine();
        while (line != null && line.trim().isEmpty()) { // Skip empty lines if any
            line = br.readLine();
        }
        if (line == null) return;

        String[] dims = line.trim().split("\\s+");
        int rows = Integer.parseInt(dims[0]);
        int cols = Integer.parseInt(dims[1]);

        // Grid with padding (1 layer of walls) to simplify boundary checks.
        // Dimensions: (rows + 2) x (cols + 2)
        // Indices 0 and rows+1 are top/bottom walls.
        // Indices 0 and cols+1 are left/right walls.
        int[][] grid = new int[rows + 2][cols + 2];

        // 1. Initialize boundaries as walls
        Arrays.fill(grid[0], STATE_WALL);
        Arrays.fill(grid[rows + 1], STATE_WALL);

        int goalCount = 0;

        // 2. Parse grid content
        for (int r = 1; r <= rows; r++) {
            // Initialize left and right boundaries for this row
            grid[r][0] = STATE_WALL;
            grid[r][cols + 1] = STATE_WALL;

            String rowStr = br.readLine();
            if (rowStr == null) break;

            for (int c = 1; c <= cols; c++) {
                // Safe character access
                char ch = (c - 1 < rowStr.length()) ? rowStr.charAt(c - 1) : ' ';

                if (ch == '#') {
                    grid[r][c] = STATE_WALL;
                } else if (ch == 'G') {
                    // Mark as goal only if currently empty (preserves wall status if logic overlaps)
                    if (grid[r][c] == STATE_EMPTY) {
                        grid[r][c] = STATE_GOAL;
                        goalCount++;
                    }
                } else if (ch == 'B') {
                    // Bomb: Destroys adjacent cells (sets them to walls).
                    // The bomb cell itself remains empty (STATE_EMPTY) based on original logic.
                    for (int dir = 0; dir < 4; dir++) {
                        int nr = r + DR[dir];
                        int nc = c + DC[dir];
                        // Bounds check (redundant with padding but safe)
                        if (nr >= 0 && nr <= rows + 1 && nc >= 0 && nc <= cols + 1) {
                            grid[nr][nc] = STATE_WALL;
                        }
                    }
                }
            }
        }

        // 3. Edge Case: No goals present
        if (goalCount == 0) {
            bw.write("Yes\n");
            return;
        }

        // BFS Initialization
        // Start position: Bottom-Right of the playable area (rows, cols)
        int startR = rows;
        int startC = cols;

        // If start position is a wall, we cannot move
        if (grid[startR][startC] == STATE_WALL) {
            bw.write("No\n");
            return;
        }

        // Queue for BFS: stores {row, col}
        // Max size needed is total cells in the padded grid
        int[][] queue = new int[(rows + 2) * (cols + 2)][2];
        boolean[][] visited = new boolean[rows + 2][cols + 2];

        int head = 0;
        int tail = 0;

        // Enqueue start position
        queue[tail][0] = startR;
        queue[tail][1] = startC;
        tail++;
        visited[startR][startC] = true;

        int goalsReached = 0;

        // BFS Loop
        while (head < tail) {
            int[] current = queue[head++];
            int r = current[0];
            int c = current[1];

            // Check if current cell is a goal
            if (grid[r][c] == STATE_GOAL) {
                goalsReached++;
            }

            // Explore neighbors
            for (int dir = 0; dir < 4; dir++) {
                int nr = r + DR[dir];
                int nc = c + DC[dir];

                if (nr >= 0 && nr <= rows + 1 && nc >= 0 && nc <= cols + 1) {
                    if (!visited[nr][nc] && grid[nr][nc] != STATE_WALL) {
                        visited[nr][nc] = true;
                        queue[tail][0] = nr;
                        queue[tail][1] = nc;
                        tail++;
                    }
                }
            }
        }

        // Output result
        bw.write((goalsReached == goalCount) ? "Yes\n" : "No\n");
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.ArrayDeque;
import java.util.Queue;
import java.util.StringTokenizer;

public class Solution {

    // Constants for grid characters to improve readability and maintainability
    private static final char BLOCK = 'B';
    private static final char GOAL = 'G';
    private static final char EMPTY = '.';

    // Direction vectors for moving in the grid (Up, Down, Left, Right)
    private static final int[] DR = {-1, 1, 0, 0};
    private static final int[] DC = {0, 0, -1, 1};

    public static void main(String[] args) {
        FastReader sc = new FastReader();
        PrintWriter out = new PrintWriter(System.out);

        // Read number of test cases
        // Using FastReader to handle potential whitespace issues robustly
        String tStr = sc.next();
        if (tStr != null) {
            int numTestCases = Integer.parseInt(tStr);

            while (numTestCases-- > 0) {
                // Read N and M
                String nStr = sc.next();
                String mStr = sc.next();

                if (nStr == null || mStr == null) break;

                int n = Integer.parseInt(nStr);
                int m = Integer.parseInt(mStr);

                char[][] grid = new char[n][m];
                for (int i = 0; i < n; i++) {
                    // Read grid row
                    // The input might be space-separated chars ("B G B") or a string ("BGB").
                    // We handle both by consuming tokens until the row is filled.
                    int col = 0;
                    String token = sc.next();

                    while (col < m && token != null) {
                        for (int k = 0; k < token.length() && col < m; k++) {
                            grid[i][col] = token.charAt(k);
                            col++;
                        }
                        if (col < m) {
                            token = sc.next();
                        }
                    }
                }

                out.println(isPossible(grid));
            }
        }

        out.flush();
        out.close();
    }

    /**
     * Determines if it is possible to reach all 'G' (Goal) cells 
     * starting from the bottom-right cell (n-1, m-1).
     * 
     * Rules:
     * 1. 'B' (Block) cannot be adjacent to 'G' (Goal).
     * 2. '.' (Empty) adjacent to 'B' becomes an obstacle '#'.
     * 3. Path cannot pass through 'B' or '#'.
     */
    public static String isPossible(char[][] grid) {
        if (grid == null || grid.length == 0 || grid[0].length == 0) {
            return "Yes";
        }

        int n = grid.length;
        int m = grid[0].length;

        // Matrix to track blocked cells.
        // We use a separate boolean matrix instead of mutating the input grid.
        // This preserves the original input and makes the method stateless/pure regarding the grid.
        boolean[][] blocked = new boolean[n][m];
        int totalGoals = 0;

        // First pass: Validate rules and mark obstacles
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < m; c++) {
                char cell = grid[r][c];

                if (cell == GOAL) {
                    totalGoals++;
                } else if (cell == BLOCK) {
                    // Check all 4 neighbors
                    for (int k = 0; k < 4; k++) {
                        int nr = r + DR[k];
                        int nc = c + DC[k];

                        if (isValid(nr, nc, n, m)) {
                            if (grid[nr][nc] == GOAL) {
                                // Rule 1: Block cannot be adjacent to Goal
                                return "No";
                            }
                            if (grid[nr][nc] == EMPTY) {
                                // Rule 2: Empty cell adjacent to Block becomes obstacle
                                blocked[nr][nc] = true;
                            }
                        }
                    }
                }
            }
        }

        // Optimization: If no goals, condition is vacuously true.
        // Preserving original logic order.
        if (totalGoals == 0) {
            return "Yes";
        }

        // Check if the starting position (bottom-right) is blocked.
        // The original code checks if arr[n-1][m-1] == '#'.
        // In our logic, this corresponds to blocked[n-1][m-1] being true,
        // or the cell itself being a BLOCK.
        if (blocked[n - 1][m - 1] || grid[n - 1][m - 1] == BLOCK) {
            return "No";
        }

        // BFS to find reachable goals
        // BFS is preferred over DFS to avoid StackOverflowError on large grids.
        int reachableGoals = bfs(grid, blocked, n, m);

        return reachableGoals == totalGoals ? "Yes" : "No";
    }

    private static boolean isValid(int r, int c, int n, int m) {
        return r >= 0 && c >= 0 && r < n && c < m;
    }

    private static int bfs(char[][] grid, boolean[][] blocked, int n, int m) {
        int count = 0;
        Queue<int[]> queue = new ArrayDeque<>();
        boolean[][] visited = new boolean[n][m];

        // Start from bottom-right
        int startR = n - 1;
        int startC = m - 1;

        queue.offer(new int[]{startR, startC});
        visited[startR][startC] = true;

        while (!queue.isEmpty()) {
            int[] curr = queue.poll();
            int r = curr[0];
            int c = curr[1];

            // If current cell is a goal, count it
            if (grid[r][c] == GOAL) {
                count++;
            }

            // Explore neighbors
            for (int k = 0; k < 4; k++) {
                int nr = r + DR[k];
                int nc = c + DC[k];

                // Check bounds, visited status, blocked status, and if it's not a Block
                if (isValid(nr, nc, n, m) && !visited[nr][nc] && !blocked[nr][nc] && grid[nr][nc] != BLOCK) {
                    visited[nr][nc] = true;
                    queue.offer(new int[]{nr, nc});
                }
            }
        }
        return count;
    }

    /**
     * Helper class for fast input reading.
     */
    static class FastReader {
        BufferedReader br;
        StringTokenizer st;

        public FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    e.printStackTrace();
                    return null;
                }
            }
            return st.nextToken();
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Refactored solution for grid traversal and blocking problem.
 * 
 * Key Improvements:
 * 1. Separated Concerns: I/O handling, grid processing, and DFS logic are clearly isolated.
 * 2. State Encapsulation: Replaced scattered instance variables with a dedicated DfsContext class.
 * 3. 0-Based Indexing: Eliminated fragile 1-based indexing and off-by-one errors.
 * 4. Resource Management: Used try-with-resources to guarantee stream closure.
 * 5. Descriptive Naming: Replaced ambiguous names (flag, reds, list, dx/dy) with semantic ones.
 * 6. Robust I/O: Implemented a FastScanner with proper EOF handling and tokenization.
 * 7. Documentation: Added JavaDoc and inline comments for maintainability.
 */
public class Main {

    // Direction vectors for moving up, down, left, right
    private static final int[] DR = {-1, 1, 0, 0};
    private static final int[] DC = {0, 0, -1, 1};

    public static void main(String[] args) {
        // try-with-resources ensures streams are closed even if an exception occurs
        try (FastScanner scanner = new FastScanner(System.in);
             PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out))) {

            int testCases = scanner.nextInt();
            while (testCases-- > 0) {
                solve(scanner, out);
            }
            out.flush();
        } catch (IOException e) {
            System.err.println("I/O error occurred: " + e.getMessage());
        }
    }

    private static void solve(FastScanner scanner, PrintWriter out) throws IOException {
        int rows = scanner.nextInt();
        int cols = scanner.nextInt();
        char[][] grid = new char[rows][cols];
        int totalGreen = 0;

        // Read grid and count total 'G' cells
        for (int i = 0; i < rows; i++) {
            String line = scanner.next();
            for (int j = 0; j < cols; j++) {
                grid[i][j] = line.charAt(j);
                if (grid[i][j] == 'G') {
                    totalGreen++;
                }
            }
        }

        // Initial DFS from bottom-right corner to check connectivity and locate 'B' cells
        DfsContext context = new DfsContext();
        boolean[][] visited = new boolean[rows][cols];

        if (grid[rows - 1][cols - 1] != '#') {
            dfs(grid, visited, rows, cols, rows - 1, cols - 1, context);
        }

        // If not all 'G' cells are reachable, the answer is immediately "No"
        if (context.reachableGreen != totalGreen) {
            out.println("No");
            return;
        }

        // Block adjacent '.' cells around each 'B' cell to prevent them from touching 'G's
        for (Point blue : context.bluePositions) {
            for (int k = 0; k < 4; k++) {
                int r = blue.r + DR[k];
                int c = blue.c + DC[k];

                if (isValid(r, c, rows, cols) && grid[r][c] == '.') {
                    grid[r][c] = '#';
                }
            }
        }

        // Second DFS to verify all 'G' cells remain reachable and no 'B' cells are left unblocked
        visited = new boolean[rows][cols];
        context = new DfsContext();
        if (grid[rows - 1][cols - 1] != '#') {
            dfs(grid, visited, rows, cols, rows - 1, cols - 1, context);
        }

        if (context.reachableGreen == totalGreen && context.bluePositions.isEmpty()) {
            out.println("Yes");
        } else {
            out.println("No");
        }
    }

    /**
     * Depth-First Search to traverse the grid.
     * Counts reachable 'G' cells and collects coordinates of 'B' cells.
     */
    private static void dfs(char[][] grid, boolean[][] visited, int rows, int cols,
                            int r, int c, DfsContext context) {
        visited[r][c] = true;

        if (grid[r][c] == 'G') {
            context.reachableGreen++;
        } else if (grid[r][c] == 'B') {
            context.bluePositions.add(new Point(r, c));
        }

        for (int k = 0; k < 4; k++) {
            int nr = r + DR[k];
            int nc = c + DC[k];

            if (isValid(nr, nc, rows, cols) && !visited[nr][nc] && grid[nr][nc] != '#') {
                dfs(grid, visited, rows, cols, nr, nc, context);
            }
        }
    }

    private static boolean isValid(int r, int c, int rows, int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /**
     * Encapsulates state mutated during DFS traversal.
     * Replaces the original scattered instance variables (reds, list, visited, flag).
     */
    private static class DfsContext {
        int reachableGreen = 0;
        final List<Point> bluePositions = new ArrayList<>();
    }

    /**
     * Immutable coordinate holder.
     */
    private static class Point {
        final int r;
        final int c;

        Point(int r, int c) {
            this.r = r;
            this.c = c;
        }
    }

    /**
     * Fast I/O helper class for competitive programming style inputs.
     */
    private static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        public String next() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) throw new EOFException("Unexpected end of input");
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}

