/**
 * Encapsulates all logic and state for processing grid test cases.
 * Replaces global static variables with instance state for thread-safety and testability.
 */
class GridSolver {

    // Descriptive constants replacing magic numbers
    private static final int EMPTY = 0;
    private static final int WALL = 1;
    private static final int BLOCKER = 2;
    private static final int GOAL = 3;

    // Instance state for a single test case
    private int[][] grid;
    private int[][] visited;
    private int goalCount;
    private boolean reachedEnd;

    /**
     * Processes a single test case: parsing, validation, and pathfinding.
     */
    void processTestCase(int n, int m, Scanner scanner) {
        grid = new int[n][m];
        parseGrid(n, m, scanner);

        int initialGoalCount = countGoals();
        int startRow = -1;
        int startCol = -1;

        // Locate the first goal to start traversal
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == GOAL) {
                    if (startRow == -1) {
                        startRow = i;
                        startCol = j;
                    }
                }
            }
        }

        // Validate all blockers against their neighbors
        boolean isValidConfiguration = true;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == BLOCKER) {
                    if (!validateBlockerNeighbors(i, j, n, m)) {
                        isValidConfiguration = false;
                        break;
                    }
                }
            }
            if (!isValidConfiguration) break;
        }

        if (!isValidConfiguration) {
            System.out.println("No");
            return;
        }

        // If no goals exist, the condition is trivially satisfied
        if (initialGoalCount == 0) {
            System.out.println("Yes");
            return;
        }

        // Initialize traversal state and run DFS
        visited = new int[n][m];
        goalCount = 0;
        reachedEnd = false;

        if (isValidMove(startRow, startCol, n, m)) {
            traverse(startRow, startCol, n, m);

            if (reachedEnd && goalCount == initialGoalCount) {
                System.out.println("Yes");
            } else {
                System.out.println("No");
            }
        } else {
            System.out.println("No");
        }
    }

    /**
     * Reads the grid characters from input and maps them to integer constants.
     */
    private void parseGrid(int n, int m, Scanner scanner) {
        for (int i = 0; i < n; i++) {
            String row = scanner.next();
            for (int j = 0; j < m; j++) {
                char c = row.charAt(j);
                if (c == '.') grid[i][j] = EMPTY;
                else if (c == '#') grid[i][j] = WALL;
                else if (c == 'B') grid[i][j] = BLOCKER;
                else if (c == 'G') grid[i][j] = GOAL;
            }
        }
    }

    /**
     * Counts the total number of GOAL cells in the grid.
     */
    private int countGoals() {
        int count = 0;
        for (int[] row : grid) {
            for (int cell : row) {
                if (cell == GOAL) count++;
            }
        }
        return count;
    }

    /**
     * Validates the four neighbors of a BLOCKER.
     * Preserves original behavior: marks EMPTY neighbors as WALL, returns false if a GOAL is adjacent.
     */
    private boolean validateBlockerNeighbors(int r, int c, int n, int m) {
        int[][] directions = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};

        for (int[] dir : directions) {
            int nr = r + dir[0];
            int nc = c + dir[1];

            if (nr >= 0 && nr < n && nc >= 0 && nc < m) {
                if (grid[nr][nc] == EMPTY) {
                    grid[nr][nc] = WALL; // Side effect preserved from original logic
                }
                if (grid[nr][nc] == GOAL) {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Checks if a cell is within bounds, unvisited, and not a WALL or BLOCKER.
     */
    private boolean isValidMove(int r, int c, int n, int m) {
        return r >= 0 && r < n && c >= 0 && c < m &&
               visited[r][c] == 0 &&
               grid[r][c] != WALL &&
               grid[r][c] != BLOCKER;
    }

    /**
     * Performs a Depth-First Search to count reachable GOALs and check if the bottom-right cell is reachable.
     */
    private void traverse(int r, int c, int n, int m) {
        visited[r][c] = 1;

        if (grid[r][c] == GOAL) {
            goalCount++;
        }

        if (r == n - 1 && c == m - 1) {
            reachedEnd = true;
        }

        int[][] directions = {{0, 1}, {0, -1}, {1, 0}, {-1, 0}};
        for (int[] dir : directions) {
            int nr = r + dir[0];
            int nc = c + dir[1];

            if (isValidMove(nr, nc, n, m)) {
                traverse(nr, nc, n, m);
            }
        }
    }
}

import java.io.*;
import java.util.*;

public class Solution {

    /** Represents the type of each cell in the grid */
    enum CellType {
        EMPTY('.'), OBSTACLE('#'), GOAL('G'), UNKNOWN('?');

        private final char symbol;
        CellType(char symbol) { this.symbol = symbol; }
        char getSymbol() { return symbol; }

        static CellType fromChar(char c) {
            for (CellType type : values()) {
                if (type.symbol == c) return type;
            }
            return UNKNOWN;
        }
    }

    /** Immutable coordinate pair */
    record Position(int row, int col) {}

    /** Direction vectors for 4-way movement (up, left, down, right) */
    private static final int[][] DIRECTIONS = { {-1, 0}, {0, -1}, {1, 0}, {0, 1} };

    /** Fast input reader for competitive programming / CLI usage */
    static class InputReader {
        private final BufferedReader br;
        private StringTokenizer st;

        public InputReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) throw new EOFException("Unexpected end of input");
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }
    }

    public static void main(String[] args) {
        InputReader reader = new InputReader();
        int testCases = reader.nextInt();

        for (int i = 0; i < testCases; i++) {
            boolean result = solve(reader);
            System.out.println(result ? "Yes" : "No");
        }
    }

    /**
     * Solves a single test case:
     * 1. Parses the grid
     * 2. Propagates obstacles around UNKNOWN cells
     * 3. Performs BFS from bottom-right to count reachable GOAL cells
     */
    private static boolean solve(InputReader reader) {
        int n = reader.nextInt();
        int m = reader.nextInt();

        CellType[][] grid = new CellType[n][m];
        List<Position> goals = new ArrayList<>();

        // 1. Parse Grid
        for (int i = 0; i < n; i++) {
            String row = reader.next();
            for (int j = 0; j < m; j++) {
                CellType type = CellType.fromChar(row.charAt(j));
                grid[i][j] = type;
                if (type == CellType.GOAL) {
                    goals.add(new Position(i, j));
                }
            }
        }

        // 2. Propagate Obstacles: Mark neighbors of UNKNOWN cells as OBSTACLE (unless they are GOAL)
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < m; c++) {
                if (grid[r][c] == CellType.UNKNOWN) {
                    for (int[] dir : DIRECTIONS) {
                        int nr = r + dir[0];
                        int nc = c + dir[1];
                        if (nr >= 0 && nr < n && nc >= 0 && nc < m) {
                            if (grid[nr][nc] != CellType.GOAL) {
                                grid[nr][nc] = CellType.OBSTACLE;
                            }
                        }
                    }
                }
            }
        }

        // 3. BFS from bottom-right corner (n-1, m-1)
        boolean possible = true;
        boolean[][] visited = new boolean[n][m];
        Deque<Position> queue = new ArrayDeque<>();

        queue.add(new Position(n - 1, m - 1));
        visited[n - 1][m - 1] = true;

        int reachableGoalsCount = 0;

        while (!queue.isEmpty() && possible) {
            Position curr = queue.poll();
            CellType type = grid[curr.row()][curr.col()];

            if (type == CellType.GOAL) {
                reachableGoalsCount++;
            } else if (type == CellType.UNKNOWN) {
                // Encountering an UNKNOWN cell during traversal invalidates the path
                possible = false;
                break;
            }

            // Explore neighbors
            for (int[] dir : DIRECTIONS) {
                int nr = curr.row() + dir[0];
                int nc = curr.col() + dir[1];

                if (nr >= 0 && nr < n && nc >= 0 && nc < m 
                        && !visited[nr][nc] 
                        && grid[nr][nc] != CellType.OBSTACLE) {
                    visited[nr][nc] = true;
                    queue.add(new Position(nr, nc));
                }
            }
        }

        // All GOAL cells must be reachable and the path must not contain UNKNOWN cells
        return possible && reachableGoalsCount == goals.size();
    }
}

import java.io.*;
import java.util.*;

public class MazeSolver {
    // Direction vectors for moving up, down, left, right
    private static final int[][] DIRECTIONS = {{0, 1}, {0, -1}, {1, 0}, {-1, 0}};

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out));

        try {
            int t = scanner.nextInt();
            while (t-- > 0) {
                solve(scanner, out);
            }
        } catch (Exception e) {
            // In competitive programming, unexpected errors are typically fatal.
            // We log them but allow the program to terminate cleanly.
            e.printStackTrace();
        } finally {
            out.flush();
            out.close();
        }
    }

    /**
     * Orchestrates the solution for a single test case.
     */
    private static void solve(FastScanner scanner, PrintWriter out) {
        int n = scanner.nextInt();
        int m = scanner.nextInt();
        char[][] grid = new char[n][m];
        int totalGoals = 0;

        // Read grid and count total 'G' cells
        for (int i = 0; i < n; i++) {
            String line = scanner.next();
            grid[i] = line.toCharArray();
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == 'G') {
                    totalGoals++;
                }
            }
        }

        // Process 'B' cells: block adjacent '.' and fail if adjacent to 'G'
        if (!processBombs(grid, n, m)) {
            out.println("No");
            return;
        }

        // Find all reachable 'G' cells from the bottom-right corner
        boolean[][] visited = new boolean[n][m];
        int reachableGoals = dfs(grid, n, m, n - 1, m - 1, visited);

        out.println(reachableGoals == totalGoals ? "Yes" : "No");
    }

    /**
     * Handles bomb ('B') logic. Returns false if a bomb is adjacent to a goal.
     * Converts adjacent '.' cells to walls ('#').
     */
    private static boolean processBombs(char[][] grid, int n, int m) {
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == 'B') {
                    for (int[] dir : DIRECTIONS) {
                        int ni = i + dir[0];
                        int nj = j + dir[1];
                        if (isValid(ni, nj, n, m)) {
                            if (grid[ni][nj] == 'G') {
                                return false; // Bomb adjacent to goal = immediate failure
                            }
                            if (grid[ni][nj] == '.') {
                                grid[ni][nj] = '#'; // Block adjacent empty space
                            }
                        }
                    }
                }
            }
        }
        return true;
    }

    /**
     * Depth-First Search to count reachable 'G' cells.
     * Note: Correctly counts the starting cell if it is 'G'.
     */
    private static int dfs(char[][] grid, int n, int m, int r, int c, boolean[][] visited) {
        if (!isValid(r, c, n, m) || visited[r][c] || grid[r][c] == '#' || grid[r][c] == 'B') {
            return 0;
        }

        visited[r][c] = true;
        int count = (grid[r][c] == 'G') ? 1 : 0;

        for (int[] dir : DIRECTIONS) {
            count += dfs(grid, n, m, r + dir[0], c + dir[1], visited);
        }
        return count;
    }

    /**
     * Checks if coordinates are within grid bounds.
     */
    private static boolean isValid(int r, int c, int n, int m) {
        return r >= 0 && r < n && c >= 0 && c < m;
    }

    /**
     * Fast input reader optimized for competitive programming.
     */
    static class FastScanner {
        private BufferedReader br;
        private StringTokenizer st;

        public FastScanner(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        public String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            String s = next();
            if (s == null) throw new RuntimeException("Unexpected end of input");
            return Integer.parseInt(s);
        }
    }
}

import java.util.LinkedList;
import java.util.Queue;
import java.util.Scanner;

public class SolveTheMaze {

    /**
     * Immutable coordinate class representing a cell in the grid.
     */
    private static final class Point {
        final int x;
        final int y;

        Point(int x, int y) {
            this.x = x;
            this.y = y;
        }
    }

    // Direction vectors for Up, Down, Left, Right
    private static final int[] DX = {-1, 1, 0, 0};
    private static final int[] DY = {0, 0, -1, 1};

    public static void main(String[] args) {
        // Use try-with-resources to ensure proper resource cleanup
        try (Scanner scanner = new Scanner(System.in)) {
            if (scanner.hasNextInt()) {
                int testCases = scanner.nextInt();
                while (testCases-- > 0) {
                    int rows = scanner.nextInt();
                    int cols = scanner.nextInt();
                    char[][] grid = new char[rows][cols];
                    int totalGoals = 0;

                    // Read grid input and count total goals
                    for (int i = 0; i < rows; i++) {
                        String rowStr = scanner.next();
                        for (int j = 0; j < cols; j++) {
                            grid[i][j] = rowStr.charAt(j);
                            if (grid[i][j] == 'G') {
                                totalGoals++;
                            }
                        }
                    }

                    // Apply preprocessing rules for 'B' (blocker) cells
                    boolean isPossible = preprocessGrid(grid, rows, cols);
                    if (!isPossible) {
                        System.out.println("No");
                        continue;
                    }

                    // If no goals exist, the condition is trivially satisfied
                    if (totalGoals == 0) {
                        System.out.println("Yes");
                        continue;
                    }

                    // Starting position cannot be a wall
                    if (grid[rows - 1][cols - 1] == '#') {
                        System.out.println("No");
                        continue;
                    }

                    // BFS to count how many goals are reachable from the start
                    int reachableGoals = bfsCountGoals(grid, rows, cols);

                    // Output result based on whether all goals were collected
                    System.out.println(reachableGoals == totalGoals ? "Yes" : "No");
                }
            }
        }
    }

    /**
     * Applies preprocessing rules for 'B' cells:
     * - If 'B' is adjacent to 'G', the configuration is invalid.
     * - If 'B' is adjacent to '.', that cell becomes a wall '#'.
     */
    private static boolean preprocessGrid(char[][] grid, int rows, int cols) {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == 'B') {
                    for (int d = 0; d < 4; d++) {
                        int ni = i + DX[d];
                        int nj = j + DY[d];

                        if (ni >= 0 && ni < rows && nj >= 0 && nj < cols) {
                            if (grid[ni][nj] == 'G') {
                                return false; // Invalid configuration: B adjacent to G
                            } else if (grid[ni][nj] == '.') {
                                grid[ni][nj] = '#'; // Block adjacent empty space
                            }
                        }
                    }
                }
            }
        }
        return true;
    }

    /**
     * Performs BFS from the bottom-right corner to count reachable 'G' cells.
     * Returns -1 if a 'B' cell is encountered (should be prevented by preprocessing).
     */
    private static int bfsCountGoals(char[][] grid, int rows, int cols) {
        Queue<Point> queue = new LinkedList<>();
        boolean[][] visited = new boolean[rows][cols];

        int startX = rows - 1;
        int startY = cols - 1;
        queue.add(new Point(startX, startY));
        visited[startX][startY] = true;

        int goalsCollected = 0;

        while (!queue.isEmpty()) {
            Point current = queue.poll();

            // Safety check: if start position is 'B', return failure
            if (grid[current.x][current.y] == 'B') {
                return -1;
            }
            if (grid[current.x][current.y] == 'G') {
                goalsCollected++;
            }

            // Explore valid neighbors
            for (int d = 0; d < 4; d++) {
                int nx = current.x + DX[d];
                int ny = current.y + DY[d];

                if (nx >= 0 && nx < rows && ny >= 0 && ny < cols &&
                    !visited[nx][ny] &&
                    grid[nx][ny] != '#' &&
                    grid[nx][ny] != 'B') {
                    visited[nx][ny] = true;
                    queue.add(new Point(nx, ny));
                }
            }
        }
        return goalsCollected;
    }
}

import java.util.Scanner;
import java.util.ArrayDeque;
import java.util.Arrays;

public class Main {
    // Constants for grid characters
    private static final char WALL = '#';
    private static final char EMPTY = '.';
    private static final char BLUE = 'B';
    private static final char GREEN = 'G';

    // Constants for BFS
    private static final int UNREACHABLE = -1;
    // Direction vectors: Up, Down, Left, Right
    private static final int[] ROW_OFFSETS = {-1, 1, 0, 0};
    private static final int[] COL_OFFSETS = {0, 0, -1, 1};

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        StringBuilder output = new StringBuilder();

        // Read number of test cases
        if (scanner.hasNextInt()) {
            int testCases = scanner.nextInt();

            for (int t = 0; t < testCases; t++) {
                int rows = scanner.nextInt();
                int cols = scanner.nextInt();

                // 1. Read and Pad the Maze
                char[][] grid = readAndPadMaze(scanner, rows, cols);

                // 2. Apply Blue Wall Expansion Logic
                applyBlueExpansion(grid, rows, cols);

                // 3. Calculate Distances via BFS
                int[][] distances = calculateDistances(grid, rows, cols);

                // 4. Validate Conditions
                boolean isSolutionValid = validateConditions(grid, distances, rows, cols);

                output.append(isSolutionValid ? "Yes" : "No")
                      .append(System.lineSeparator());
            }
        }

        System.out.print(output);
        scanner.close();
    }

    /**
     * Reads the maze from input and adds a wall border around it.
     * This simplifies boundary checks during BFS and neighbor iteration.
     */
    private static char[][] readAndPadMaze(Scanner scanner, int rows, int cols) {
        // Grid size includes +2 for the border (top/bottom)
        char[][] grid = new char[rows + 2][cols + 2];

        // Fill top and bottom borders with walls
        Arrays.fill(grid[0], WALL);
        Arrays.fill(grid[rows + 1], WALL);

        // Read each row and pad with walls on left and right
        for (int r = 1; r <= rows; r++) {
            String line = scanner.next();
            // Construct the row: Wall + Content + Wall
            char[] paddedRow = new char[cols + 2];
            paddedRow[0] = WALL;
            paddedRow[cols + 1] = WALL;
            // Copy content from input string to the middle of the array
            line.getChars(0, line.length(), paddedRow, 1);
            grid[r] = paddedRow;
        }
        return grid;
    }

    /**
     * Iterates through the grid and converts neighbors of 'B' cells into walls.
     * This simulates the specific rule where Blue blocks adjacent empty spaces.
     */
    private static void applyBlueExpansion(char[][] grid, int rows, int cols) {
        for (int r = 1; r <= rows; r++) {
            for (int c = 1; c <= cols; c++) {
                if (grid[r][c] == BLUE) {
                    // Check all 4 cardinal directions
                    for (int i = 0; i < 4; i++) {
                        int nextR = r + ROW_OFFSETS[i];
                        int nextC = c + COL_OFFSETS[i];

                        // If the neighbor is empty space, turn it into a wall
                        if (grid[nextR][nextC] == EMPTY) {
                            grid[nextR][nextC] = WALL;
                        }
                    }
                }
            }
        }
    }

    /**
     * Performs Breadth-First Search (BFS) starting from the bottom-right corner (rows, cols).
     * Returns a 2D array of distances from the start point.
     */
    private static int[][] calculateDistances(char[][] grid, int rows, int cols) {
        int[][] distances = new int[rows + 2][cols + 2];

        // Initialize distances to -1 (unreachable)
        for (int r = 0; r < distances.length; r++) {
            Arrays.fill(distances[r], UNREACHABLE);
        }

        ArrayDeque<Coordinate> queue = new ArrayDeque<>();
        int startR = rows;
        int startC = cols;

        // Start BFS if the starting position is not a wall
        if (grid[startR][startC] != WALL) {
            distances[startR][startC] = 0;
            queue.add(new Coordinate(startR, startC));
        }

        while (!queue.isEmpty()) {
            Coordinate current = queue.poll();
            int currR = current.r;
            int currC = current.c;

            // Explore neighbors
            for (int i = 0; i < 4; i++) {
                int nextR = currR + ROW_OFFSETS[i];
                int nextC = currC + COL_OFFSETS[i];

                // Check if the neighbor is within valid distance bounds and not a wall
                if (distances[nextR][nextC] == UNREACHABLE && grid[nextR][nextC] != WALL) {
                    distances[nextR][nextC] = distances[currR][currC] + 1;
                    queue.add(new Coordinate(nextR, nextC));
                }
            }
        }
        return distances;
    }

    /**
     * Validates the solution conditions:
     * 1. All 'G' (Green) cells must be reachable.
     * 2. All 'B' (Blue) cells must be unreachable.
     */
    private static boolean validateConditions(char[][] grid, int[][] distances, int rows, int cols) {
        for (int r = 1; r <= rows; r++) {
            for (int c = 1; c <= cols; c++) {
                char cell = grid[r][c];
                int dist = distances[r][c];

                // Condition: Green must be reachable
                if (cell == GREEN && dist == UNREACHABLE) {
                    return false;
                }

                // Condition: Blue must be unreachable
                if (cell == BLUE && dist != UNREACHABLE) {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Simple data structure to hold grid coordinates.
     */
    private static class Coordinate {
        int r, c;

        public Coordinate(int r, int c) {
            this.r = r;
            this.c = c;
        }
    }
}

import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Deque;
import java.util.List;
import java.util.Scanner;

public class Main {
    // Cell type constants for better readability and maintainability
    private static final int EMPTY = 0;
    private static final int OBSTACLE = 1;
    private static final int GOAL = 2;
    private static final int INVALID = 3;
    private static final int VISITED = -1;

    public static void main(String[] args) {
        // Use try-with-resources for proper resource management
        try (Scanner scanner = new Scanner(System.in)) {
            if (!scanner.hasNextInt()) return;
            int testCases = scanner.nextInt();

            while (testCases-- > 0) {
                int rows = scanner.nextInt();
                int cols = scanner.nextInt();

                int[][] grid = parseGrid(scanner, rows, cols);
                int initialGoalCount = countGoals(grid);
                propagateInvalidCells(grid, rows, cols);

                boolean isPossible = findPath(grid, rows, cols, initialGoalCount);
                System.out.println(isPossible ? "Yes" : "No");
            }
        }
    }

    /**
     * Parses the input grid into an integer matrix based on character mapping.
     */
    private static int[][] parseGrid(Scanner scanner, int rows, int cols) {
        int[][] grid = new int[rows][cols];
        for (int i = 0; i < rows; i++) {
            String line = scanner.next();
            for (int j = 0; j < cols; j++) {
                char c = line.charAt(j);
                if (c == '.') grid[i][j] = EMPTY;
                else if (c == '#') grid[i][j] = OBSTACLE;
                else if (c == 'G') grid[i][j] = GOAL;
                else grid[i][j] = INVALID;
            }
        }
        return grid;
    }

    /**
     * Counts the total number of goal cells in the grid.
     */
    private static int countGoals(int[][] grid) {
        int count = 0;
        for (int[] row : grid) {
            for (int cell : row) {
                if (cell == GOAL) count++;
            }
        }
        return count;
    }

    /**
     * Identifies invalid cells and marks their adjacent empty cells as obstacles.
     */
    private static void propagateInvalidCells(int[][] grid, int rows, int cols) {
        List<Point> invalidCells = new ArrayList<>();
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == INVALID) {
                    invalidCells.add(new Point(i, j));
                }
            }
        }

        for (Point p : invalidCells) {
            markAdjacentEmptyAsObstacles(grid, p.row, p.col, rows, cols);
        }
    }

    /**
     * Marks adjacent empty cells around a given coordinate as obstacles.
     */
    private static void markAdjacentEmptyAsObstacles(int[][] grid, int r, int c, int rows, int cols) {
        int[] dr = {-1, 1, 0, 0};
        int[] dc = {0, 0, -1, 1};
        for (int k = 0; k < 4; k++) {
            int nr = r + dr[k];
            int nc = c + dc[k];
            if (nr >= 0 && nr < rows && nc >= 0 && nc < cols && grid[nr][nc] == EMPTY) {
                grid[nr][nc] = OBSTACLE;
            }
        }
    }

    /**
     * Performs DFS to determine if all goals are reachable without traversing invalid cells.
     */
    private static boolean findPath(int[][] grid, int rows, int cols, int initialGoalCount) {
        // Start position is blocked
        if (grid[rows - 1][cols - 1] == OBSTACLE) {
            return false;
        }

        // ArrayDeque is preferred over Stack for LIFO operations
        Deque<Point> stack = new ArrayDeque<>();
        stack.push(new Point(rows - 1, cols - 1));

        int goalsVisited = 0;
        boolean validPath = true;

        while (!stack.isEmpty()) {
            Point current = stack.pop();
            int r = current.row;
            int c = current.col;

            if (grid[r][c] == INVALID) {
                validPath = false;
            } else if (grid[r][c] == GOAL) {
                goalsVisited++;
            }

            // Mark cell as visited
            grid[r][c] = VISITED;

            // Explore neighbors
            int[] dr = {-1, 1, 0, 0};
            int[] dc = {0, 0, -1, 1};
            for (int k = 0; k < 4; k++) {
                int nr = r + dr[k];
                int nc = c + dc[k];
                if (isValidMove(grid, nr, nc, rows, cols)) {
                    stack.push(new Point(nr, nc));
                }
            }
        }

        return validPath && goalsVisited == initialGoalCount;
    }

    /**
     * Checks if a given coordinate is within bounds and not an obstacle or visited.
     */
    private static boolean isValidMove(int[][] grid, int r, int c, int rows, int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols
                && grid[r][c] != OBSTACLE
                && grid[r][c] != VISITED;
    }

    /**
     * Immutable coordinate class to replace the original Node class.
     */
    private static class Point {
        private final int row;
        private final int col;

        public Point(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Main entry point for the maze solver application.
 * Handles test case iteration and I/O setup.
 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;

        InputReader in = new InputReader(inputStream);
        OutputWriter out = new OutputWriter(outputStream);

        MazeSolver solver = new MazeSolver();
        int testCount = Integer.parseInt(in.next());

        for (int i = 1; i <= testCount; i++) {
            solver.solve(i, in, out);
        }

        out.close();
    }

    /**
     * Core solver logic for the maze problem.
     */
    static class MazeSolver {
        private static final char BLOCKED = '#';
        private static final char EMPTY = '.';
        private static final char GOAL = 'G';
        private static final char OBSTACLE = 'B';

        public void solve(int testNumber, InputReader in, OutputWriter out) {
            int n = in.nextInt();
            int m = in.nextInt();
            char[][] maze = in.readCharMatrix(n, m);

            GridBounds gridBounds = new GridBounds(n, m);
            Point exit = new Point(n - 1, m - 1);

            // Step 1: Process obstacles ('B')
            // If an obstacle touches a goal, it's impossible.
            // Otherwise, block adjacent empty cells to prevent bypassing.
            for (int r = 0; r < n; r++) {
                for (int c = 0; c < m; c++) {
                    if (maze[r][c] == OBSTACLE) {
                        List<Point> accessibleNeighbors = gridBounds.getNeighbors(
                            new Point(r, c),
                            (row, col) -> maze[row][col] == EMPTY || maze[row][col] == GOAL
                        );

                        for (Point neighbor : accessibleNeighbors) {
                            if (maze[neighbor.row][neighbor.col] == GOAL) {
                                out.println("No");
                                return;
                            }
                            maze[neighbor.row][neighbor.col] = BLOCKED;
                        }
                    }
                }
            }

            // Step 2: DFS from the exit to mark all reachable cells
            boolean[][] visited = new boolean[n][m];
            if (maze[n - 1][m - 1] != BLOCKED) {
                dfs(exit, visited, gridBounds, 
                    (row, col) -> !visited[row][col] && maze[row][col] != BLOCKED);
            }

            // Step 3: Verify all goals are reachable from the exit
            List<Point> goals = findCells(n, m, maze, GOAL);
            for (Point goal : goals) {
                if (!visited[goal.row][goal.col]) {
                    out.println("No");
                    return;
                }
            }

            out.println("Yes");
        }

        private void dfs(Point node, boolean[][] visited, GridBounds gridBounds, 
                         BiPredicate<Integer, Integer> isAvailable) {
            visited[node.row][node.col] = true;
            for (Point neighbor : gridBounds.getNeighbors(node, isAvailable)) {
                dfs(neighbor, visited, gridBounds, isAvailable);
            }
        }

        private List<Point> findCells(int n, int m, char[][] maze, char type) {
            List<Point> result = new ArrayList<>();
            for (int r = 0; r < n; r++) {
                for (int c = 0; c < m; c++) {
                    if (maze[r][c] == type) {
                        result.add(new Point(r, c));
                    }
                }
            }
            return result;
        }
    }

    /**
     * Utility class for grid boundary checks and neighbor retrieval.
     */
    static class GridBounds {
        private static final int[][] DIRECTIONS = {{-1, 0}, {0, 1}, {1, 0}, {0, -1}};
        private final int rows;
        private final int cols;

        public GridBounds(int rows, int cols) {
            this.rows = rows;
            this.cols = cols;
        }

        public boolean isWithinBounds(int row, int col) {
            return row >= 0 && row < rows && col >= 0 && col < cols;
        }

        public List<Point> getNeighbors(Point cell, BiPredicate<Integer, Integer> predicate) {
            List<Point> neighbors = new ArrayList<>();
            for (int[] dir : DIRECTIONS) {
                int r = cell.row + dir[0];
                int c = cell.col + dir[1];
                if (isWithinBounds(r, c) && predicate.test(r, c)) {
                    neighbors.add(new Point(r, c));
                }
            }
            return neighbors;
        }
    }

    /**
     * Immutable coordinate pair representing a grid cell.
     */
    static class Point implements Comparable<Point> {
        public final int row;
        public final int col;

        public Point(int row, int col) {
            this.row = row;
            this.col = col;
        }

        @Override
        public int compareTo(Point other) {
            if (this.row != other.row) return Integer.compare(this.row, other.row);
            return Integer.compare(this.col, other.col);
        }

        @Override
        public boolean equals(Object o) {
            if (this == o) return true;
            if (!(o instanceof Point)) return false;
            Point point = (Point) o;
            return row == point.row && col == point.col;
        }

        @Override
        public int hashCode() {
            return Objects.hash(row, col);
        }

        @Override
        public String toString() {
            return row + " " + col;
        }
    }

    /**
     * Optimized output writer wrapping PrintWriter.
     */
    static class OutputWriter extends PrintWriter {
        public OutputWriter(OutputStream outputStream) {
            super(outputStream);
        }

        public OutputWriter(Writer writer) {
            super(writer);
        }

        public void yes() {
            println("Yes");
        }

        public void no() {
            println("No");
        }

        @Override
        public void close() {
            super.close();
        }
    }

    /**
     * Fast input reader for competitive programming style I/O.
     */
    static class InputReader extends BufferedReader {
        private StringTokenizer tokenizer;

        public InputReader(InputStream inputStream) {
            super(new InputStreamReader(inputStream), 32768);
        }

        public InputReader(String filename) {
            super(new InputStreamReader(
                Objects.requireNonNull(Thread.currentThread()
                    .getContextClassLoader().getResourceAsStream(filename)),
                StandardCharsets.UTF_8));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input", e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public char[][] readCharMatrix(int n, int m) {
            char[][] result = new char[n][];
            for (int i = 0; i < n; i++) {
                result[i] = next().toCharArray();
            }
            return result;
        }
    }
}

import java.util.LinkedList;
import java.util.Queue;
import java.util.Scanner;

/**
 * Solves the maze validation and reachability problem.
 * Refactored for maintainability, readability, and separation of concerns.
 */
public class MazeSolver {

    // Direction vectors for up, down, left, right
    private static final int[] DX = {-1, 1, 0, 0};
    private static final int[] DY = {0, 0, -1, 1};

    public static void main(String[] args) {
        solve();
    }

    /**
     * Orchestrates the reading, validation, and processing of all test cases.
     */
    public static void solve() {
        Scanner scanner = new Scanner(System.in);
        StringBuilder output = new StringBuilder();

        if (!scanner.hasNextInt()) {
            System.out.print(output);
            return;
        }

        int testCases = scanner.nextInt();
        for (int caseNum = 0; caseNum < testCases; caseNum++) {
            int n = scanner.nextInt();
            int m = scanner.nextInt();

            char[][] maze = initializeMaze(n, m);
            int goodCount = loadMazeGrid(scanner, maze, n, m);

            boolean isValid = true;

            // 1. Validate all 'B' cells
            for (int i = 1; i <= n; i++) {
                for (int j = 1; j <= m; j++) {
                    if (maze[i][j] == 'B' && !isBlocked(maze, i, j)) {
                        isValid = false;
                        break;
                    }
                }
                if (!isValid) {
                    break;
                }
            }

            // 2. Check additional condition from original logic
            if (isValid && maze[n][m] == '#' && goodCount != 0) {
                isValid = false;
            }

            // 3. Flood-fill reachable cells and verify if all 'G' are removed
            if (isValid) {
                isValid = floodFillAndCheckReachable(maze, n, m, goodCount);
            }

            output.append(isValid ? "Yes" : "No").append('\n');
        }

        System.out.print(output);
        scanner.close();
    }

    /**
     * Creates the maze grid with padded boundaries.
     */
    private static char[][] initializeMaze(int n, int m) {
        char[][] maze = new char[n + 2][m + 2];
        for (int j = 0; j < m + 2; j++) {
            maze[0][j] = '#';
            maze[n + 1][j] = '#';
        }
        for (int i = 0; i < n + 2; i++) {
            maze[i][0] = '#';
            maze[i][m + 1] = '#';
        }
        return maze;
    }

    /**
     * Reads the maze rows from input and counts 'G' cells.
     */
    private static int loadMazeGrid(Scanner scanner, char[][] maze, int n, int m) {
        int goodCount = 0;
        for (int i = 1; i <= n; i++) {
            String row = scanner.next();
            for (int j = 1; j <= m; j++) {
                char cell = row.charAt(j - 1);
                maze[i][j] = cell;
                if (cell == 'G') {
                    goodCount++;
                }
            }
        }
        return goodCount;
    }

    /**
     * Checks if a 'B' cell is blocked. Returns false if any adjacent cell is 'G'.
     * Note: Side-effect modification of '.' cells was removed for purity.
     * If required, this should be handled in a dedicated state-modification method.
     */
    private static boolean isBlocked(char[][] maze, int i, int j) {
        for (int k = 0; k < 4; k++) {
            int ni = i + DX[k];
            int nj = j + DY[k];
            if (maze[ni][nj] == 'G') {
                return false;
            }
        }
        return true;
    }

    /**
     * Performs BFS from (n, m) to remove reachable 'G' and '.' cells.
     * Returns true if all 'G' cells were successfully removed.
     */
    private static boolean floodFillAndCheckReachable(char[][] maze, int n, int m, int initialGoodCount) {
        Queue<Point> queue = new LinkedList<>();
        queue.add(new Point(n, m));

        int remainingGood = initialGoodCount;

        while (!queue.isEmpty()) {
            Point current = queue.poll();
            int i = current.x;
            int j = current.y;

            for (int k = 0; k < 4; k++) {
                int ni = i + DX[k];
                int nj = j + DY[k];

                if (maze[ni][nj] == 'G') {
                    maze[ni][nj] = '#';
                    remainingGood--;
                    queue.add(new Point(ni, nj));
                } else if (maze[ni][nj] == '.') {
                    maze[ni][nj] = '#';
                    queue.add(new Point(ni, nj));
                }
            }
        }
        return remainingGood == 0;
    }

    /**
     * Immutable coordinate class for BFS queue storage.
     * (Use 'record Point(int x, int y)' in Java 14+)
     */
    private static class Point {
        final int x;
        final int y;

        Point(int x, int y) {
            this.x = x;
            this.y = y;
        }
    }
}

import java.io.*;
import java.util.*;

public class Main {
    // Directions for movement: Down, Up, Right, Left
    private static final int[][] DIRECTIONS = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};

    public static void main(String[] args) throws IOException {
        // try-with-resources ensures streams are properly closed and flushed
        try (FastScanner sc = new FastScanner(System.in);
             PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out))) {

            int t = sc.nextInt();
            while (t-- > 0) {
                int n = sc.nextInt();
                int m = sc.nextInt();
                char[][] grid = new char[n][m];
                for (int i = 0; i < n; i++) {
                    grid[i] = sc.next().toCharArray();
                }

                // Step 1: Block adjacent empty cells to 'B' (Bad persons)
                if (!blockBadPersons(grid, n, m)) {
                    out.println("No");
                    continue;
                }

                // Step 2: Verify every 'G' (Good person) can reach the bottom-right corner
                boolean[][] processedG = new boolean[n][m];
                boolean allEscaped = true;

                outerLoop:
                for (int i = 0; i < n; i++) {
                    for (int j = 0; j < m; j++) {
                        if (grid[i][j] == 'G' && !processedG[i][j]) {
                            if (!canEscape(grid, i, j, n, m, processedG)) {
                                allEscaped = false;
                                break outerLoop;
                            }
                        }
                    }
                }
                out.println(allEscaped ? "Yes" : "No");
            }
        }
    }

    /**
     * Blocks adjacent empty cells to 'B' with '#'.
     * Returns false if a 'B' is directly adjacent to a 'G', making escape impossible.
     */
    private static boolean blockBadPersons(char[][] grid, int n, int m) {
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == 'B') {
                    for (int[] dir : DIRECTIONS) {
                        int x = i + dir[0];
                        int y = j + dir[1];
                        if (x >= 0 && x < n && y >= 0 && y < m) {
                            if (grid[x][y] == 'G') {
                                return false; // Bad person adjacent to Good person
                            } else if (grid[x][y] == '.') {
                                grid[x][y] = '#'; // Block empty cell
                            }
                        }
                    }
                }
            }
        }
        return true;
    }

    /**
     * Performs BFS to check if a 'G' can reach the bottom-right corner.
     * Marks all reachable 'G' cells as processed to avoid redundant BFS calls.
     */
    private static boolean canEscape(char[][] grid, int startRow, int startCol, int n, int m, boolean[][] processedG) {
        Deque<int[]> queue = new ArrayDeque<>();
        boolean[][] visited = new boolean[n][m];

        queue.add(new int[]{startRow, startCol});
        visited[startRow][startCol] = true;

        while (!queue.isEmpty()) {
            int[] curr = queue.poll();
            if (curr[0] == n - 1 && curr[1] == m - 1) {
                return true; // Reached destination
            }

            for (int[] dir : DIRECTIONS) {
                int nr = curr[0] + dir[0];
                int nc = curr[1] + dir[1];

                if (nr >= 0 && nr < n && nc >= 0 && nc < m && !visited[nr][nc]) {
                    char cell = grid[nr][nc];
                    if (cell == '#') {
                        continue; // Blocked cell
                    }
                    if (cell == 'G') {
                        processedG[nr][nc] = true; // Mark as processed
                    }
                    visited[nr][nc] = true;
                    queue.add(new int[]{nr, nc});
                }
            }
        }
        return false; // Path not found
    }

    /**
     * Fast I/O helper class for competitive programming.
     */
    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        String next() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) {
                    throw new EOFException("Unexpected end of input");
                }
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        long nextLong() throws IOException {
            return Long.parseLong(next());
        }
    }
}

import java.util.Scanner;
import java.util.Queue;
import java.util.LinkedList;

public class Main {
    // Directions for moving up, down, left, right
    private static final int[][] DIRECTIONS = {
        {-1, 0}, {1, 0}, {0, -1}, {0, 1}
    };

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        // Check if input exists to prevent exceptions
        if (scanner.hasNextInt()) {
            int t = scanner.nextInt();
            while (t-- > 0) {
                solveTestCase(scanner);
            }
        }
        scanner.close();
    }

    /**
     * Solves a single test case for the maze problem.
     */
    private static void solveTestCase(Scanner scanner) {
        int n = scanner.nextInt();
        int m = scanner.nextInt();

        char[][] maze = new char[n][];
        int totalGoals = 0;

        // 1. Read the maze and count total goals
        for (int i = 0; i < n; i++) {
            String row = scanner.next();
            maze[i] = row.toCharArray();
            for (char cell : maze[i]) {
                if (cell == 'G') {
                    totalGoals++;
                }
            }
        }

        // 2. Process Bombs
        // Bombs block adjacent empty spaces ('.') and kill adjacent goals ('G')
        boolean isPossible = true;

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (maze[i][j] == 'B') {
                    // Check all 4 neighbors
                    for (int[] dir : DIRECTIONS) {
                        int r = i + dir[0];
                        int c = j + dir[1];

                        if (isValidCoordinate(r, c, n, m)) {
                            if (maze[r][c] == 'G') {
                                // Bomb is adjacent to a Goal -> Impossible
                                isPossible = false;
                                break; 
                            }
                            if (maze[r][c] == '.') {
                                // Bomb blocks adjacent empty space
                                maze[r][c] = '#';
                            }
                        }
                    }
                    if (!isPossible) break;
                }
            }
            if (!isPossible) break;
        }

        // If logic failed during bomb processing
        if (!isPossible) {
            System.out.println("No");
            return;
        }

        // 3. Check Reachability from bottom-right corner (n-1, m-1)
        int reachableGoals = countReachableGoals(maze, n, m);

        // 4. Output result
        if (reachableGoals == totalGoals) {
            System.out.println("Yes");
        } else {
            System.out.println("No");
        }
    }

    /**
     * Counts how many 'G' cells are reachable from the bottom-right corner (n-1, m-1)
     * using Breadth-First Search (BFS).
     */
    private static int countReachableGoals(char[][] maze, int n, int m) {
        // If grid is empty, no goals reachable
        if (n == 0 || m == 0) return 0;

        int startRow = n - 1;
        int startCol = m - 1;

        // If starting position is a wall, nothing is reachable
        if (maze[startRow][startCol] == '#') {
            return 0;
        }

        boolean[][] visited = new boolean[n][m];
        Queue<int[]> queue = new LinkedList<>();

        queue.offer(new int[]{startRow, startCol});
        visited[startRow][startCol] = true;

        int reachableCount = 0;
        // Check if the starting cell itself is a goal
        if (maze[startRow][startCol] == 'G') {
            reachableCount++;
        }

        while (!queue.isEmpty()) {
            int[] current = queue.poll();
            int r = current[0];
            int c = current[1];

            for (int[] dir : DIRECTIONS) {
                int nr = r + dir[0];
                int nc = c + dir[1];

                if (isValidCoordinate(nr, nc, n, m) && !visited[nr][nc] && maze[nr][nc] != '#') {
                    visited[nr][nc] = true;
                    if (maze[nr][nc] == 'G') {
                        reachableCount++;
                    }
                    queue.offer(new int[]{nr, nc});
                }
            }
        }

        return reachableCount;
    }

    /**
     * Checks if the given coordinates are within the grid boundaries.
     */
    private static boolean isValidCoordinate(int r, int c, int n, int m) {
        return r >= 0 && r < n && c >= 0 && c < m;
    }
}

import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.ArrayDeque;
import java.util.Queue;

public class MazeSolver {
    // Direction vectors for moving up, right, down, left
    private static final int[] DR = {-1, 0, 1, 0};
    private static final int[] DC = {0, 1, 0, -1};

    public static void main(String[] args) throws Exception {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter out = new PrintWriter(System.out);

        String line = reader.readLine();
        if (line == null || line.trim().isEmpty()) {
            out.flush();
            return;
        }
        int testCases = Integer.parseInt(line.trim());

        while (testCases-- > 0) {
            String[] dims = reader.readLine().trim().split("\\s+");
            int rows = Integer.parseInt(dims[0]);
            int cols = Integer.parseInt(dims[1]);

            char[][] grid = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                grid[i] = reader.readLine().trim().toCharArray();
            }

            out.println(solve(grid, rows, cols) ? "Yes" : "No");
        }

        out.flush();
        out.close();
    }

    /**
     * Orchestrates the maze solving logic.
     */
    private static boolean solve(char[][] grid, int rows, int cols) {
        // Step 1: Process 'B' (Bomb) adjacency rules
        if (!processBombAdjacentCells(grid, rows, cols)) {
            return false;
        }
        // Step 2: Verify all 'G' (Goal) cells are reachable from bottom-right
        return isAllGoalsReachable(grid, rows, cols);
    }

    /**
     * Applies bomb rules: blocks adjacent empty cells and fails if a bomb touches a goal.
     */
    private static boolean processBombAdjacentCells(char[][] grid, int rows, int cols) {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == 'B') {
                    for (int d = 0; d < 4; d++) {
                        int nr = r + DR[d];
                        int nc = c + DC[d];
                        if (isValid(nr, nc, rows, cols)) {
                            if (grid[nr][nc] == 'G') {
                                return false; // Bomb adjacent to Goal -> Impossible
                            }
                            if (grid[nr][nc] == '.') {
                                grid[nr][nc] = '#'; // Block adjacent empty cells
                            }
                        }
                    }
                }
            }
        }
        return true;
    }

    /**
     * Uses BFS to check if all 'G' cells are reachable from (rows-1, cols-1).
     */
    private static boolean isAllGoalsReachable(char[][] grid, int rows, int cols) {
        if (grid[rows - 1][cols - 1] == '#') {
            return false; // Starting position is blocked
        }

        boolean[][] visited = new boolean[rows][cols];
        Queue<Point> queue = new ArrayDeque<>();

        queue.add(new Point(rows - 1, cols - 1));
        visited[rows - 1][cols - 1] = true;

        while (!queue.isEmpty()) {
            Point curr = queue.poll();
            for (int d = 0; d < 4; d++) {
                int nr = curr.r + DR[d];
                int nc = curr.c + DC[d];
                if (isValid(nr, nc, rows, cols) && !visited[nr][nc] && grid[nr][nc] != '#') {
                    visited[nr][nc] = true;
                    queue.add(new Point(nr, nc));
                }
            }
        }

        // Verify every 'G' cell was visited during BFS
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == 'G' && !visited[r][c]) {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Checks if coordinates are within grid bounds.
     */
    private static boolean isValid(int r, int c, int rows, int cols) {
        return r >= 0 && c >= 0 && r < rows && c < cols;
    }

    /**
     * Simple immutable record-like class to hold grid coordinates.
     */
    private static class Point {
        final int r, c;
        Point(int r, int c) { this.r = r; this.c = c; }
    }
}

import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        if (!scanner.hasNextInt()) {
            return;
        }

        int testCases = scanner.nextInt();
        while (testCases-- > 0) {
            int n = scanner.nextInt();
            int m = scanner.nextInt();

            char[][] grid = new char[n][m];
            int totalG = 0;

            // Read grid rows. Using next() avoids common nextInt/nextLine newline issues.
            for (int i = 0; i < n; i++) {
                String row = scanner.next();
                grid[i] = row.toCharArray();
                for (int j = 0; j < m; j++) {
                    if (grid[i][j] == 'G') {
                        totalG++;
                    }
                }
            }

            GridSolver solver = new GridSolver(grid, n, m, totalG);
            // Standardized output casing for consistency
            System.out.println(solver.solve() ? "YES" : "NO");
        }
        scanner.close();
    }

    /**
     * Encapsulates all grid traversal and validation logic.
     * Removes static global state, making the code testable and reusable.
     */
    private static class GridSolver {
        private static final int[][] DIRECTIONS = {{0, 1}, {0, -1}, {1, 0}, {-1, 0}};

        private final char[][] grid;
        private final int rows, cols, totalG;
        private boolean[][] visited;
        private int reachableG;
        private boolean possible;

        public GridSolver(char[][] grid, int rows, int cols, int totalG) {
            this.grid = grid;
            this.rows = rows;
            this.cols = cols;
            this.totalG = totalG;
            this.visited = new boolean[rows][cols];
            this.reachableG = 0;
            this.possible = true;
        }

        public boolean solve() {
            preprocess();
            dfs(rows - 1, cols - 1);
            return possible && reachableG == totalG;
        }

        /**
         * Marks cells adjacent to 'B' as blocked ('#') to prevent traversal.
         */
        private void preprocess() {
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j] == 'B') {
                        for (int[] dir : DIRECTIONS) {
                            int ni = i + dir[0];
                            int nj = j + dir[1];
                            if (isValid(ni, nj) && grid[ni][nj] == '.') {
                                grid[ni][nj] = '#';
                            }
                        }
                    }
                }
            }
        }

        /**
         * Validates boundaries and blocked cells.
         */
        private boolean isValid(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols && grid[r][c] != '#';
        }

        /**
         * Depth-First Search to count reachable 'G's and check adjacency constraints.
         */
        private void dfs(int r, int c) {
            if (!possible) {
                return;
            }
            if (!isValid(r, c) || visited[r][c]) {
                return;
            }

            visited[r][c] = true;

            if (grid[r][c] == 'G') {
                reachableG++;
                // Check if this 'G' is adjacent to any 'B'
                for (int[] dir : DIRECTIONS) {
                    int ni = r + dir[0];
                    int nj = c + dir[1];
                    if (isValid(ni, nj) && grid[ni][nj] == 'B') {
                        possible = false;
                        return;
                    }
                }
            }

            for (int[] dir : DIRECTIONS) {
                dfs(r + dir[0], c + dir[1]);
                if (!possible) {
                    return;
                }
            }
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

/**
 * Refactored solution for grid traversal problem.
 * 
 * Improvements made:
 * 1. Removed global static state (count, direction arrays) to make the code thread-safe and testable.
 * 2. Replaced String array with char[][] for better performance and easier character access.
 * 3. Used meaningful variable names (grid, rows, cols, visited) instead of single letters.
 * 4. Extracted logic into helper methods (dfs, isValid) for better readability and separation of concerns.
 * 5. Used constants for direction offsets.
 * 6. Improved input reading robustness (handling potential empty lines).
 */
public class Main {

    // Direction vectors: Right, Down, Left, Up
    private static final int[] ROW_OFFSETS = {0, 1, 0, -1};
    private static final int[] COL_OFFSETS = {1, 0, -1, 0};

    public static void main(String[] args) throws IOException {
        // Use try-with-resources for automatic resource management
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            String line = br.readLine();
            if (line == null || line.trim().isEmpty()) {
                return;
            }

            int t = Integer.parseInt(line.trim());

            while (t-- > 0) {
                // Read dimensions n and m
                String lineNM = br.readLine();
                // Skip empty lines if any occur between test cases
                while (lineNM != null && lineNM.trim().isEmpty()) {
                    lineNM = br.readLine();
                }
                if (lineNM == null) break;

                StringTokenizer st = new StringTokenizer(lineNM);
                int n = Integer.parseInt(st.nextToken());
                int m = Integer.parseInt(st.nextToken());

                char[][] grid = new char[n][m];
                int totalGs = 0;

                // Read grid and count total 'G's
                for (int i = 0; i < n; i++) {
                    String row = br.readLine();
                    if (row != null) {
                        // Ensure we don't go out of bounds if the input row is short
                        int len = Math.min(row.length(), m);
                        for (int j = 0; j < len; j++) {
                            grid[i][j] = row.charAt(j);
                            if (grid[i][j] == 'G') {
                                totalGs++;
                            }
                        }
                    }
                }

                boolean[][] visited = new boolean[n][m];
                // Use an array to hold the count reference so it can be modified in DFS
                int[] reachableGs = new int[1];

                // Start DFS from the bottom-right corner (n-1, m-1)
                dfs(grid, visited, n - 1, m - 1, n, m, reachableGs);

                // Compare reachable 'G's with total 'G's
                if (totalGs == reachableGs[0]) {
                    System.out.println("Yes");
                } else {
                    System.out.println("No");
                }
            }
        }
    }

    /**
     * Performs Depth First Search to find reachable 'G' cells.
     * 
     * Logic preserved from original:
     * - Traversal stops immediately if any adjacent neighbor is 'B'.
     * - Current cell is counted as 'G' only if traversal hasn't been stopped by a neighbor.
     */
    private static void dfs(char[][] grid, boolean[][] visited, int r, int c, int rows, int cols, int[] countRef) {
        if (!isValid(grid, visited, r, c, rows, cols)) {
            return;
        }

        visited[r][c] = true;

        // Check neighbors for the 'B' condition.
        // Original Logic: If any neighbor is 'B', terminate this DFS branch immediately.
        for (int i = 0; i < 4; i++) {
            int nr = r + ROW_OFFSETS[i];
            int nc = c + COL_OFFSETS[i];

            // Check bounds
            if (nr < 0 || nr >= rows || nc < 0 || nc >= cols) {
                continue;
            }

            // Check for 'B' (Block/Bomb)
            if (grid[nr][nc] == 'B') {
                return; 
            }
        }

        // Count current cell if it is a Goal ('G')
        if (grid[r][c] == 'G') {
            countRef[0]++;
        }

        // Recurse to neighbors
        for (int i = 0; i < 4; i++) {
            dfs(grid, visited, r + ROW_OFFSETS[i], c + COL_OFFSETS[i], rows, cols, countRef);
        }
    }

    /**
     * Validates if the cell (r, c) is within bounds, not visited, and not a wall ('#').
     */
    private static boolean isValid(char[][] grid, boolean[][] visited, int r, int c, int rows, int cols) {
        if (r < 0 || r >= rows || c < 0 || c >= cols) {
            return false;
        }
        if (visited[r][c]) {
            return false;
        }
        if (grid[r][c] == '#') {
            return false;
        }
        return true;
    }
}

import java.util.Scanner;
import java.util.Queue;
import java.util.ArrayDeque;

public class UndergroundSystem {

    // Direction vectors for moving up, down, left, right
    private static final int[] DR = {-1, 1, 0, 0};
    private static final int[] DC = {0, 0, -1, 1};

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        if (!scanner.hasNextInt()) {
            return;
        }
        int testCases = scanner.nextInt();

        for (int t = 1; t <= testCases; t++) {
            int rows = scanner.nextInt();
            int cols = scanner.nextInt();
            char[][] grid = readGrid(scanner, rows, cols);

            boolean isValid = processAndValidate(grid, rows, cols);
            System.out.println(isValid ? "Yes" : "No");
        }
        scanner.close();
    }

    /**
     * Reads the grid layout from standard input.
     */
    private static char[][] readGrid(Scanner scanner, int rows, int cols) {
        char[][] grid = new char[rows][cols];
        for (int r = 0; r < rows; r++) {
            String line = scanner.next();
            for (int c = 0; c < cols; c++) {
                grid[r][c] = line.charAt(c);
            }
        }
        return grid;
    }

    /**
     * Orchestrates the grid processing and validation pipeline.
     */
    private static boolean processAndValidate(char[][] grid, int rows, int cols) {
        if (rows == 0 || cols == 0) {
            return true;
        }

        // Step 1: Apply bomb rules (convert adjacent '.' to '#' and detect invalid 'B'-'G' adjacency)
        if (!applyBombRules(grid, rows, cols)) {
            return false;
        }

        // Step 2: Find all cells reachable from the bottom-right corner
        boolean[][] reachable = findReachableCells(grid, rows, cols);

        // Step 3: Validate reachability conditions
        return validateConditions(grid, reachable, rows, cols);
    }

    /**
     * Applies rules for 'B' (Bomb) cells:
     * - Converts adjacent '.' cells to '#' (blocked).
     * - Returns false if a 'B' is adjacent to a 'G' (Goal), indicating an invalid configuration.
     */
    private static boolean applyBombRules(char[][] grid, int rows, int cols) {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == 'B') {
                    for (int d = 0; d < 4; d++) {
                        int nr = r + DR[d];
                        int nc = c + DC[d];
                        if (isValidCell(nr, nc, rows, cols)) {
                            if (grid[nr][nc] == 'G') {
                                return false; // Invalid: Bomb next to Goal
                            }
                            if (grid[nr][nc] == '.') {
                                grid[nr][nc] = '#'; // Block empty space next to Bomb
                            }
                        }
                    }
                }
            }
        }
        return true;
    }

    /**
     * Checks if coordinates are within grid boundaries.
     */
    private static boolean isValidCell(int r, int c, int rows, int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /**
     * Uses BFS to find all reachable cells from the bottom-right corner.
     * '#' cells are treated as obstacles.
     */
    private static boolean[][] findReachableCells(char[][] grid, int rows, int cols) {
        boolean[][] reachable = new boolean[rows][cols];
        int startR = rows - 1;
        int startC = cols - 1;

        // If the starting position is blocked, nothing is reachable
        if (grid[startR][startC] == '#') {
            return reachable;
        }

        Queue<int[]> queue = new ArrayDeque<>();
        queue.offer(new int[]{startR, startC});
        reachable[startR][startC] = true;

        while (!queue.isEmpty()) {
            int[] current = queue.poll();
            int r = current[0];
            int c = current[1];

            for (int d = 0; d < 4; d++) {
                int nr = r + DR[d];
                int nc = c + DC[d];

                if (isValidCell(nr, nc, rows, cols) && !reachable[nr][nc] && grid[nr][nc] != '#') {
                    reachable[nr][nc] = true;
                    queue.offer(new int[]{nr, nc});
                }
            }
        }
        return reachable;
    }

    /**
     * Validates the final grid state:
     * - All 'G' (Goal) cells must be reachable.
     * - No 'B' (Bomb) cells must be reachable.
     */
    private static boolean validateConditions(char[][] grid, boolean[][] reachable, int rows, int cols) {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                char cell = grid[r][c];
                if (cell == 'G' && !reachable[r][c]) {
                    return false; // Goal unreachable
                }
                if (cell == 'B' && reachable[r][c]) {
                    return false; // Bomb reachable
                }
            }
        }
        return true;
    }
}

import java.util.Scanner;
import java.util.Queue;
import java.util.ArrayDeque;

/**
 * Refactored Grid Solver.
 * 
 * Improvements made:
 * 1. Encapsulation: Logic moved from main into distinct methods (propagation, BFS, validation).
 * 2. Naming: Descriptive variable names (grid, numRows, visited, etc.) replace single-letter variables.
 * 3. Constants: Direction vectors are defined as static final constants.
 * 4. Data Structures: Used ArrayDeque for better performance and Point class for readability.
 * 5. Readability: Removed magic numbers and simplified control flow.
 * 6. Resource Management: Scanner is properly closed.
 */
public class GridSolver {

    // Direction vectors for moving Down, Right, Left, Up (matching original x, y order: 1,0; 0,1; 0,-1; -1,0)
    // x corresponds to row index change, y to column index change.
    private static final int[] ROW_OFFSETS = {1, 0, 0, -1};
    private static final int[] COL_OFFSETS = {0, 1, -1, 0};

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        // Using try-with-resources is good practice, but closing System.in is sometimes discouraged in competitive programming.
        // However, for maintainability, we close it.
        if (scanner.hasNextInt()) {
            int testCases = scanner.nextInt();

            while (testCases-- > 0) {
                int numRows = scanner.nextInt();
                int numCols = scanner.nextInt();

                char[][] grid = new char[numRows][numCols];

                // Read grid input
                for (int r = 0; r < numRows; r++) {
                    String rowString = scanner.next();
                    grid[r] = rowString.toCharArray();
                }

                boolean result = solve(numRows, numCols, grid);
                System.out.println(result ? "Yes" : "No");
            }
        }
        scanner.close();
    }

    /**
     * Orchestrates the solving process.
     */
    private static boolean solve(int numRows, int numCols, char[][] grid) {
        // Step 1: Propagate 'B' influence (mark neighbors as blocked)
        propagateBlockedCells(grid, numRows, numCols);

        // Step 2: Perform BFS to find reachable cells from bottom-right
        boolean[][] visited = performBFS(grid, numRows, numCols);

        // Step 3: Validate the configuration
        return validateConfiguration(grid, visited, numRows, numCols);
    }

    /**
     * Marks immediate neighbors of 'B' cells as blocked ('#').
     */
    private static void propagateBlockedCells(char[][] grid, int rows, int cols) {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == 'B') {
                    for (int k = 0; k < 4; k++) {
                        int nextR = r + ROW_OFFSETS[k];
                        int nextC = c + COL_OFFSETS[k];

                        if (isValidCoordinate(nextR, nextC, rows, cols) && grid[nextR][nextC] == '.') {
                            grid[nextR][nextC] = '#';
                        }
                    }
                }
            }
        }
    }

    /**
     * Performs Breadth-First Search starting from the bottom-right corner.
     */
    private static boolean[][] performBFS(char[][] grid, int rows, int cols) {
        boolean[][] visited = new boolean[rows][cols];
        Queue<Point> queue = new ArrayDeque<>();

        int startR = rows - 1;
        int startC = cols - 1;

        // BFS starts only if the starting cell is accessible (matches original logic: a[n-1][m-1]=='.')
        if (isValidCoordinate(startR, startC, rows, cols) && grid[startR][startC] == '.') {
            queue.offer(new Point(startR, startC));
            visited[startR][startC] = true;
        }

        while (!queue.isEmpty()) {
            Point current = queue.poll();
            int r = current.row;
            int c = current.col;

            for (int k = 0; k < 4; k++) {
                int nextR = r + ROW_OFFSETS[k];
                int nextC = c + COL_OFFSETS[k];

                if (isValidCoordinate(nextR, nextC, rows, cols) 
                        && !visited[nextR][nextC] 
                        && grid[nextR][nextC] != '#') {

                    queue.offer(new Point(nextR, nextC));
                    visited[nextR][nextC] = true;
                }
            }
        }

        return visited;
    }

    /**
     * Checks if the grid satisfies the reachability conditions.
     * Conditions:
     * 1. 'B' cells must NOT be reachable.
     * 2. 'G' cells MUST be reachable.
     */
    private static boolean validateConfiguration(char[][] grid, boolean[][] visited, int rows, int cols) {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                char cell = grid[r][c];

                // If 'B' is visited, the condition fails
                if (cell == 'B' && visited[r][c]) {
                    return false;
                }

                // If 'G' is not visited, the condition fails
                if (cell == 'G' && !visited[r][c]) {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Utility method to check boundary conditions.
     */
    private static boolean isValidCoordinate(int r, int c, int rows, int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /**
     * Helper class to store coordinate points.
     */
    private static class Point {
        int row;
        int col;

        public Point(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

public class NeighborGrid {

    // Constants defining the maximum allowed values for different cell positions
    private static final int CORNER_LIMIT = 2;
    private static final int EDGE_LIMIT = 3;
    private static final int INTERIOR_LIMIT = 4;

    public static void main(String[] args) {
        FastReader scanner = new FastReader();

        // Read number of test cases safely
        String tStr = scanner.next();
        if (tStr == null) return;
        int t = Integer.parseInt(tStr);

        // Use StringBuilder for efficient output handling
        StringBuilder output = new StringBuilder();

        for (int i = 0; i < t; i++) {
            int n = scanner.nextInt(); // Number of rows
            int m = scanner.nextInt(); // Number of columns

            int[][] grid = new int[n][m];
            boolean isPossible = true;

            // Read grid and validate constraints
            for (int row = 0; row < n; row++) {
                for (int col = 0; col < m; col++) {
                    grid[row][col] = scanner.nextInt();

                    // If we already found a violation, we just consume the input
                    // to advance the stream for the next test case
                    if (isPossible) {
                        int limit = getCellLimit(row, col, n, m);
                        if (grid[row][col] > limit) {
                            isPossible = false;
                        }
                    }
                }
            }

            // Generate output based on validation result
            if (!isPossible) {
                output.append("NO\n");
            } else {
                output.append("YES\n");
                // Print the pattern grid (max allowed values)
                for (int row = 0; row < n; row++) {
                    for (int col = 0; col < m; col++) {
                        output.append(getCellLimit(row, col, n, m)).append(" ");
                    }
                    output.append("\n");
                }
            }
        }
        System.out.print(output);
    }

    /**
     * Calculates the maximum allowed value for a cell based on its position.
     * Corners: 2
     * Edges (non-corner): 3
     * Interior: 4
     */
    private static int getCellLimit(int row, int col, int rows, int cols) {
        boolean isRowEdge = (row == 0 || row == rows - 1);
        boolean isColEdge = (col == 0 || col == cols - 1);

        // Corners are on both row and column edges
        if (isRowEdge && isColEdge) {
            return CORNER_LIMIT;
        }
        // Edges are on one of the boundaries
        if (isRowEdge || isColEdge) {
            return EDGE_LIMIT;
        }
        // Interior cells
        return INTERIOR_LIMIT;
    }

    // FastReader class for efficient input reading
    static class FastReader {
        BufferedReader br;
        StringTokenizer st;

        public FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    e.printStackTrace();
                    return null;
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            String s = next();
            return (s == null) ? 0 : Integer.parseInt(s);
        }

        long nextLong() {
            String s = next();
            return (s == null) ? 0L : Long.parseLong(s);
        }

        double nextDouble() {
            String s = next();
            return (s == null) ? 0.0 : Double.parseDouble(s);
        }

        String nextLine() {
            String str = "";
            try {
                str = br.readLine();
            } catch (IOException e) {
                e.printStackTrace();
            }
            return str;
        }
    }
}

import java.io.*;
import java.util.StringTokenizer;

/**
 * Refactored solution for a grid pattern problem.
 * 
 * Key improvements:
 * 1. Removed all static mutable state to prevent side-effects and improve testability.
 * 2. Eliminated dead code (unused utilities like gcd, prime sieve, lowerBound, etc.).
 * 3. Replaced slow Scanner with a robust BufferedReader-based FastScanner.
 * 4. Used PrintWriter and StringBuilder for efficient output handling.
 * 5. Extracted magic numbers and complex conditions into well-named helper methods.
 * 6. Improved error handling for I/O operations.
 */
public class Main {

    public static void main(String[] args) {
        FastScanner sc = new FastScanner();
        PrintWriter out = new PrintWriter(System.out);

        try {
            if (sc.hasNext()) {
                int t = sc.nextInt();
                while (t-- > 0) {
                    solve(sc, out);
                }
            }
        } finally {
            out.flush();
        }
    }

    private static void solve(FastScanner sc, PrintWriter out) {
        int n = sc.nextInt();
        int m = sc.nextInt();
        int[][] grid = new int[n][m];

        // Read input grid
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                grid[i][j] = sc.nextInt();
            }
        }

        // Validate constraints against problem rules
        if (!isValid(grid, n, m)) {
            out.println("NO");
            return;
        }

        // Output valid result
        out.println("YES");
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                int value;
                if (isCorner(i, j, n, m)) {
                    value = 2;
                } else if (isEdge(i, j, n, m)) {
                    value = 3;
                } else {
                    value = 4;
                }
                sb.append(value).append(j == m - 1 ? "" : " ");
            }
            sb.append('\n');
        }
        out.print(sb);
    }

    /**
     * Checks if all grid values satisfy the problem constraints.
     */
    private static boolean isValid(int[][] grid, int n, int m) {
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                int val = grid[i][j];
                if (val > 4) return false;
                if (val > 2 && isCorner(i, j, n, m)) return false;
                if (val == 4 && isEdge(i, j, n, m)) return false;
            }
        }
        return true;
    }

    private static boolean isCorner(int i, int j, int n, int m) {
        return (i == 0 && j == 0) || (i == n - 1 && j == 0) ||
               (i == 0 && j == m - 1) || (i == n - 1 && j == m - 1);
    }

    private static boolean isEdge(int i, int j, int n, int m) {
        return i == 0 || i == n - 1 || j == 0 || j == m - 1;
    }

    /**
     * High-performance input reader for competitive programming.
     */
    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        boolean hasNext() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return false;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input", e);
                }
            }
            return true;
        }

        String next() {
            if (hasNext()) return st.nextToken();
            throw new RuntimeException("Unexpected end of input");
        }

        int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        // Check if input is available to prevent exceptions on empty input
        if (scanner.hasNextInt()) {
            int t = scanner.nextInt();
            while (t-- > 0) {
                processTestCase(scanner);
            }
        }
        scanner.close();
    }

    /**
     * Processes a single test case.
     * Reads the matrix dimensions and values, validates constraints,
     * updates values according to rules, and prints the result.
     */
    private static void processTestCase(Scanner scanner) {
        int rows = scanner.nextInt();
        int cols = scanner.nextInt();
        int[][] matrix = new int[rows][cols];

        // 1. Read Input
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                matrix[i][j] = scanner.nextInt();
            }
        }

        boolean isValid = true;

        // 2. Validate and Transform
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                int maxAllowed = calculateLimit(i, j, rows, cols);

                // Check constraint
                if (matrix[i][j] > maxAllowed) {
                    isValid = false;
                    break; // Break inner loop
                }

                // Update value to the maximum allowed limit as per original logic
                matrix[i][j] = maxAllowed;
            }
            if (!isValid) break; // Break outer loop
        }

        // 3. Output Result
        if (isValid) {
            System.out.println("YES");
            printMatrix(matrix);
        } else {
            System.out.println("NO");
        }
    }

    /**
     * Determines the maximum allowed value for a cell based on its position.
     * 
     * Corners:    Max value 2
     * Edges:      Max value 3
     * Interior:   Max value 4
     */
    private static int calculateLimit(int row, int col, int rows, int cols) {
        // Check if the cell is a corner
        // Corners are at (0,0), (0, cols-1), (rows-1, 0), (rows-1, cols-1)
        boolean isCorner = (row == 0 || row == rows - 1) && (col == 0 || col == cols - 1);
        if (isCorner) {
            return 2;
        }

        // Check if the cell is on an edge (boundary but not a corner)
        // Edges are where row is 0 or rows-1, OR col is 0 or cols-1
        boolean isEdge = (row == 0 || row == rows - 1 || col == 0 || col == cols - 1);
        if (isEdge) {
            return 3;
        }

        // Interior cell
        return 4;
    }

    /**
     * Prints the matrix to standard output.
     * Uses StringBuilder for better performance compared to multiple print calls.
     */
    private static void printMatrix(int[][] matrix) {
        StringBuilder sb = new StringBuilder();
        for (int[] row : matrix) {
            for (int val : row) {
                sb.append(val).append(" ");
            }
            sb.append("\n");
        }
        System.out.print(sb);
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

/**
 * Validates a matrix against a specific corner/edge/interior value pattern.
 * Refactored for readability, maintainability, and performance.
 */
public class MatrixPatternValidator {

    // Magic numbers replaced with named constants for clarity
    private static final int CORNER_VALUE = 2;
    private static final int EDGE_VALUE = 3;
    private static final int INTERIOR_VALUE = 4;

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner();
        PrintWriter out = new PrintWriter(System.out);

        int testCases = scanner.nextInt();
        while (testCases-- > 0) {
            solve(scanner, out);
        }

        out.flush();
    }

    /**
     * Processes a single test case: reads input, validates against pattern,
     * and writes the result.
     */
    private static void solve(FastScanner scanner, PrintWriter out) {
        int n = scanner.nextInt();
        int m = scanner.nextInt();
        int[][] inputGrid = new int[n][m];

        // Read the input matrix
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                inputGrid[i][j] = scanner.nextInt();
            }
        }

        int[][] requiredPattern = new int[n][m];
        boolean isValid = true;

        // Generate the required pattern and validate in a single pass
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                requiredPattern[i][j] = getRequiredValue(i, j, n, m);
                if (inputGrid[i][j] > requiredPattern[i][j]) {
                    isValid = false;
                }
            }
        }

        if (!isValid) {
            out.println("NO");
        } else {
            out.println("YES");
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    out.print(requiredPattern[i][j]);
                    if (j < m - 1) {
                        out.print(' ');
                    }
                }
                out.println();
            }
        }
    }

    /**
     * Determines the required value based on the cell's position.
     * Corners: 2, Edges (excluding corners): 3, Interior: 4
     */
    private static int getRequiredValue(int row, int col, int n, int m) {
        boolean isCorner = (row == 0 || row == n - 1) && (col == 0 || col == m - 1);
        boolean isEdge = row == 0 || row == n - 1 || col == 0 || col == m - 1;

        if (isCorner) return CORNER_VALUE;
        if (isEdge) return EDGE_VALUE;
        return INTERIOR_VALUE;
    }

    /**
     * Fast I/O helper optimized for competitive programming and large inputs.
     */
    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) {
                        throw new IOException("Unexpected end of input");
                    }
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.BufferedReader;
