import java.util.StringTokenizer;

/**
 * Refactored grid neighbor checker.
 * 
 * Improvements applied:
 * 1. Descriptive naming: Class, variables, and methods follow Java conventions.
 * 2. Removed dead code: Unused `mod` constant and unnecessary 2D array allocation.
 * 3. DRY principle: Extracted adjacent cell calculation into a dedicated method.
 * 4. Single Responsibility: `solve()` handles one test case cleanly.
 * 5. Robust I/O: Buffered output stream, proper EOF handling in FastScanner.
 * 6. Memory efficiency: Processes input stream directly without storing the grid.
 */
public class GridNeighborChecker {

    private static final BufferedReader IN = new BufferedReader(new InputStreamReader(System.in));
    private static final PrintWriter OUT = new PrintWriter(new java.io.BufferedOutputStream(System.out));
    private static FastScanner scanner;

    public static void main(String[] args) throws IOException {
        scanner = new FastScanner(IN);
        int t = scanner.nextInt();

        while (t-- > 0) {
            solve();
        }

        OUT.flush();
    }

    /**
     * Processes a single test case.
     * Reads the grid dimensions and values, validates constraints,
     * and outputs the result.
     */
    private static void solve() throws IOException {
        int n = scanner.nextInt();
        int m = scanner.nextInt();
        boolean isPossible = true;

        // First pass: read values and validate against adjacent cell limits
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                int value = scanner.nextInt();
                int maxAdjacent = calculateAdjacentCount(i, j, n, m);
                if (value > maxAdjacent) {
                    isPossible = false;
                }
            }
        }

        if (!isPossible) {
            OUT.println("NO");
            return;
        }

        OUT.println("YES");

        // Second pass: output the grid of valid adjacent cell counts
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                OUT.print(calculateAdjacentCount(i, j, n, m) + (j == m - 1 ? "" : " "));
            }
            OUT.println();
        }
    }

    /**
     * Calculates the number of adjacent cells for a given position in an n x m grid.
     * Returns 4 for inner cells, 3 for edge cells, and 2 for corner cells.
     */
    private static int calculateAdjacentCount(int row, int col, int n, int m) {
        int count = 4;
        if (row == 0 || row == n - 1) {
            count--;
        }
        if (col == 0 || col == m - 1) {
            count--;
        }
        return count;
    }

    /**
     * High-performance scanner for competitive programming / fast I/O.
     */
    private static class FastScanner {
        private final BufferedReader in;
        private StringTokenizer st;

        public FastScanner(BufferedReader in) {
            this.in = in;
        }

        public String nextToken() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                String line = in.readLine();
                if (line == null) {
                    throw new IOException("Unexpected end of input");
                }
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(nextToken());
        }

        public long nextLong() throws IOException {
            return Long.parseLong(nextToken());
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

/**
 * Refactored Matrix Grid Solver.
 * 
 * This program reads a grid of integers, validates a specific condition 
 * regarding neighbor counts, and outputs the result.
 */
public class MatrixGridSolver {

    public static void main(String[] args) {
        FastReader sc = new FastReader();
        PrintWriter out = new PrintWriter(System.out);

        try {
            // Read the number of test cases
            String tStr = sc.next();
            if (tStr != null) {
                int t = Integer.parseInt(tStr);
                while (t-- > 0) {
                    solve(sc, out);
                }
            }
        } catch (Exception e) {
            e.printStackTrace();
        } finally {
            out.flush();
        }
    }

    /**
     * Solves a single test case.
     */
    private static void solve(FastReader sc, PrintWriter out) {
        int rows = sc.nextInt();
        int cols = sc.nextInt();
        int[][] grid = new int[rows][cols];

        // Read the grid input
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                grid[i][j] = sc.nextInt();
            }
        }

        boolean isValid = true;

        // Iterate through the grid to validate and transform
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                // Calculate number of valid orthogonal neighbors
                int neighborCount = countValidNeighbors(i, j, rows, cols);

                // Check condition: if cell value exceeds neighbor count, it's invalid
                if (grid[i][j] > neighborCount) {
                    isValid = false;
                    break;
                }

                // Update cell value to the neighbor count (as per original logic)
                grid[i][j] = neighborCount;
            }
            if (!isValid) {
                break;
            }
        }

        // Output the result
        if (isValid) {
            out.println("YES");
            printGrid(out, grid);
        } else {
            out.println("NO");
        }
    }

    /**
     * Counts the number of valid orthogonal neighbors (up, down, left, right)
     * for a cell at (row, col) within a grid of size (rows, cols).
     */
    private static int countValidNeighbors(int row, int col, int rows, int cols) {
        int count = 0;
        if (row > 0) count++;           // Top neighbor exists
        if (row < rows - 1) count++;    // Bottom neighbor exists
        if (col > 0) count++;           // Left neighbor exists
        if (col < cols - 1) count++;    // Right neighbor exists
        return count;
    }

    /**
     * Prints the 2D integer array to the PrintWriter.
     */
    private static void printGrid(PrintWriter out, int[][] grid) {
        for (int[] row : grid) {
            for (int val : row) {
                out.print(val + " ");
            }
            out.println();
        }
    }

    /**
     * Fast I/O Helper Class
     */
    static class FastReader {
        BufferedReader br;
        StringTokenizer st;

        public FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    e.printStackTrace();
                    return null;
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            String s = next();
            if (s == null) return 0;
            return Integer.parseInt(s);
        }

        long nextLong() {
            String s = next();
            if (s == null) return 0L;
            return Long.parseLong(s);
        }

        double nextDouble() {
            String s = next();
            if (s == null) return 0.0;
            return Double.parseDouble(s);
        }
    }
}

import java.util.Scanner;

public class Solution {

    /**
     * Main entry point for the application.
     * Handles the reading of test cases and delegates processing.
     */
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        // Check if there is input available to prevent NoSuchElementException
        if (scanner.hasNextInt()) {
            int numberOfTestCases = scanner.nextInt();

            for (int t = 0; t < numberOfTestCases; t++) {
                processTestCase(scanner);
            }
        }

        scanner.close();
    }

    /**
     * Processes a single test case: reads dimensions and matrix, validates the configuration,
     * and prints the result.
     *
     * @param scanner The scanner to read input from.
     */
    private static void processTestCase(Scanner scanner) {
        int rows = scanner.nextInt();
        int cols = scanner.nextInt();

        int[][] inputMatrix = new int[rows][cols];

        // Read the input matrix
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                inputMatrix[i][j] = scanner.nextInt();
            }
        }

        // Array to store the calculated edge counts (degrees) for output
        int[][] resultMatrix = new int[rows][cols];
        boolean isValidConfiguration = true;

        // Validate input and calculate edge counts
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                int edgeCount = calculateEdgeCount(i, j, rows, cols);

                // If the input value exceeds the possible number of edges, the configuration is invalid
                if (inputMatrix[i][j] > edgeCount) {
                    isValidConfiguration = false;
                    break;
                }

                // Store the calculated edge count for output
                resultMatrix[i][j] = edgeCount;
            }

            // If invalid, stop processing this test case early
            if (!isValidConfiguration) {
                break;
            }
        }

        // Output results
        if (isValidConfiguration) {
            System.out.println("YES");
            printMatrix(resultMatrix);
        } else {
            System.out.println("NO");
        }
    }

    /**
     * Calculates the number of valid edges (neighbors) for a cell at (row, col)
     * in a grid of size totalRows x totalCols.
     *
     * @param row The current row index.
     * @param col The current column index.
     * @param totalRows Total number of rows in the grid.
     * @param totalCols Total number of columns in the grid.
     * @return The number of valid neighbors (edges).
     */
    private static int calculateEdgeCount(int row, int col, int totalRows, int totalCols) {
        int count = 0;

        // Check Top neighbor
        if (row > 0) {
            count++;
        }
        // Check Bottom neighbor
        if (row < totalRows - 1) {
            count++;
        }
        // Check Left neighbor
        if (col > 0) {
            count++;
        }
        // Check Right neighbor
        if (col < totalCols - 1) {
            count++;
        }

        return count;
    }

    /**
     * Prints the matrix to the console in the specified format.
     *
     * @param matrix The 2D array to print.
     */
    private static void printMatrix(int[][] matrix) {
        for (int i = 0; i < matrix.length; i++) {
            for (int j = 0; j < matrix[i].length; j++) {
                System.out.print(matrix[i][j] + " ");
            }
            System.out.println();
        }
    }
}

import java.io.PrintWriter;
import java.util.Scanner;

/**
 * Validates if a given grid meets a specific boundary pattern requirement.
 * Pattern rules:
 * - Corners must be <= 2
 * - Non-corner borders must be <= 3
 * - Interior cells must be <= 4
 */
public class GridValidator {

    private static final int CORNER_VALUE = 2;
    private static final int BORDER_VALUE = 3;
    private static final int INTERIOR_VALUE = 4;

    public static void main(String[] args) {
        // Use try-with-resources to ensure proper closure of I/O streams
        try (Scanner scanner = new Scanner(System.in);
             PrintWriter out = new PrintWriter(System.out)) {

            int testCases = scanner.nextInt();
            for (int t = 0; t < testCases; t++) {
                int rows = scanner.nextInt();
                int cols = scanner.nextInt();
                int[][] grid = new int[rows][cols];

                // Read the input grid
                for (int i = 0; i < rows; i++) {
                    for (int j = 0; j < cols; j++) {
                        grid[i][j] = scanner.nextInt();
                    }
                }

                // Validate and output result
                validateAndPrint(grid, rows, cols, out);
            }
        }
        // PrintWriter is automatically flushed and closed here
    }

    /**
     * Validates the grid against the pattern and prints the result.
     */
    private static void validateAndPrint(int[][] grid, int n, int m, PrintWriter out) {
        int[][] pattern = createPatternMatrix(n, m);
        if (isValid(grid, pattern)) {
            out.println("YES");
            printMatrix(pattern, out);
        } else {
            out.println("NO");
        }
    }

    /**
     * Constructs the expected pattern matrix based on grid dimensions.
     */
    private static int[][] createPatternMatrix(int n, int m) {
        int[][] pattern = new int[n][m];

        // 1. Set interior cells
        for (int i = 1; i < n - 1; i++) {
            for (int j = 1; j < m - 1; j++) {
                pattern[i][j] = INTERIOR_VALUE;
            }
        }

        // 2. Set border cells
        for (int i = 0; i < n; i++) {
            pattern[i][0] = BORDER_VALUE;
            pattern[i][m - 1] = BORDER_VALUE;
        }
        for (int j = 0; j < m; j++) {
            pattern[0][j] = BORDER_VALUE;
            pattern[n - 1][j] = BORDER_VALUE;
        }

        // 3. Override corners with corner value
        pattern[0][0] = CORNER_VALUE;
        pattern[0][m - 1] = CORNER_VALUE;
        pattern[n - 1][0] = CORNER_VALUE;
        pattern[n - 1][m - 1] = CORNER_VALUE;

        return pattern;
    }

    /**
     * Checks if all cells in the grid are less than or equal to the corresponding pattern cells.
     */
    private static boolean isValid(int[][] grid, int[][] pattern) {
        for (int i = 0; i < grid.length; i++) {
            for (int j = 0; j < grid[0].length; j++) {
                if (grid[i][j] > pattern[i][j]) {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Prints a 2D integer matrix to the provided PrintWriter.
     */
    private static void printMatrix(int[][] matrix, PrintWriter out) {
        for (int[] row : matrix) {
            for (int value : row) {
                out.print(value + " ");
            }
            out.println();
        }
    }
}

import java.io.BufferedReader;
