public class TaskB {

    public static void main(String[] args) {
        // Initialize input and output handlers
        // Using try-with-resources ensures PrintWriter is flushed and closed properly
        try (FastScanner sc = new FastScanner(System.in);
             PrintWriter out = new PrintWriter(System.out)) {

            // Read the number of test cases
            String tStr = sc.next();
            if (tStr != null) {
                int t = Integer.parseInt(tStr);
                while (t-- > 0) {
                    solve(sc, out);
                }
            }
        } catch (Exception e) {
            // In a production environment, log the exception.
            // For competitive programming, we typically allow the program to terminate.
        }
    }

    /**
     * Solves a single test case.
     */
    private static void solve(FastScanner sc, PrintWriter out) {
        // Read dimensions n and m
        String nStr = sc.next();
        String mStr = sc.next();

        // Safety check for end of input
        if (nStr == null || mStr == null) return;

        int n = Integer.parseInt(nStr);
        int m = Integer.parseInt(mStr);

        int[][] matrix = new int[n][m];

        // Read matrix elements
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                String val = sc.next();
                if (val != null) {
                    matrix[i][j] = Integer.parseInt(val);
                }
            }
        }

        // Process the matrix
        boolean isValid = true;

        // Define directions for neighbors: Up, Down, Left, Right
        int[] dr = {-1, 1, 0, 0};
        int[] dc = {0, 0, -1, 1};

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                int neighborCount = 0;

                // Count valid neighbors
                for (int k = 0; k < 4; k++) {
                    int ni = i + dr[k];
                    int nj = j + dc[k];

                    // Check boundaries
                    if (ni >= 0 && ni < n && nj >= 0 && nj < m) {
                        neighborCount++;
                    }
                }

                // Validation check: value must not exceed neighbor count
                if (matrix[i][j] > neighborCount) {
                    isValid = false;
                    break; // Optimization: Stop processing if condition fails
                }

                // Update cell value to the count of valid neighbors
                matrix[i][j] = neighborCount;
            }
            if (!isValid) break;
        }

        // Output results
        if (isValid) {
            out.println("YES");
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    out.print(matrix[i][j]);
                    // Print space separator, but avoid trailing space at end of line
                    if (j < m - 1) {
                        out.print(" ");
                    }
                }
                out.println();
            }
        } else {
            out.println("NO");
        }
    }

    /**
     * Helper class for fast input reading.
     * Handles whitespace and newlines robustly.
     */
    static class FastScanner {
        BufferedReader br;
        StringTokenizer st;

        public FastScanner(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return st.nextToken();
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

/**
 * Determines if a given grid can be satisfied by the maximum number of neighbors
 * each cell can have in a 2D grid. If valid, prints the neighbor configuration.
 */
public class NeighborGrid {

    public static void main(String[] args) throws IOException {
        // Use try-with-resources for automatic and safe resource management
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(System.in))) {
            String line = reader.readLine();
            if (line == null || line.trim().isEmpty()) {
                return;
            }

            int numTestCases = Integer.parseInt(line.trim());

            for (int t = 0; t < numTestCases; t++) {
                StringTokenizer st = new StringTokenizer(reader.readLine());
                int rows = Integer.parseInt(st.nextToken());
                int cols = Integer.parseInt(st.nextToken());

                int[][] targetGrid = readGrid(reader, rows, cols);
                int[][] neighborGrid = computeNeighborGrid(rows, cols);

                if (isValidConfiguration(targetGrid, neighborGrid)) {
                    System.out.println("YES");
                    printGrid(neighborGrid);
                } else {
                    System.out.println("NO");
                }
            }
        }
    }

    /**
     * Reads an n x m grid of integers from the input stream.
     */
    private static int[][] readGrid(BufferedReader reader, int rows, int cols) throws IOException {
        int[][] grid = new int[rows][cols];
        for (int i = 0; i < rows; i++) {
            StringTokenizer st = new StringTokenizer(reader.readLine());
            for (int j = 0; j < cols; j++) {
                grid[i][j] = Integer.parseInt(st.nextToken());
            }
        }
        return grid;
    }

    /**
     * Computes the maximum possible neighbor count for each cell in a grid.
     * Interior cells have 4 neighbors, edge cells have 3, and corner cells have 2.
     */
    private static int[][] computeNeighborGrid(int rows, int cols) {
        int[][] grid = new int[rows][cols];
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                grid[i][j] = countNeighbors(i, j, rows, cols);
            }
        }
        return grid;
    }

    /**
     * Calculates the number of valid adjacent neighbors for a cell at (row, col).
     */
    private static int countNeighbors(int row, int col, int rows, int cols) {
        int count = 0;
        if (row > 0) count++;
        if (row < rows - 1) count++;
        if (col > 0) count++;
        if (col < cols - 1) count++;
        return count;
    }

    /**
     * Validates if the computed neighbor grid satisfies the target grid.
     * A configuration is valid if every cell's neighbor count is >= the target value.
     */
    private static boolean isValidConfiguration(int[][] target, int[][] computed) {
        int rows = target.length;
        int cols = target[0].length;
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (computed[i][j] < target[i][j]) {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Prints the grid to standard output.
     */
    private static void printGrid(int[][] grid) {
        StringBuilder output = new StringBuilder();
        for (int[] row : grid) {
            for (int value : row) {
                output.append(value).append(' ');
            }
            output.append('\n');
        }
        System.out.print(output);
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

public class Main {

    // Magic numbers extracted to named constants for clarity
    private static final int CORNER_VALUE = 2;
    private static final int EDGE_VALUE = 3;
    private static final int INNER_VALUE = 4;

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner();
        String tStr = scanner.next();
        if (tStr == null) return;

        int testCases = Integer.parseInt(tStr);
        for (int t = 1; t <= testCases; t++) {
            int n = scanner.nextInt();
            int m = scanner.nextInt();
            solve(n, m, scanner);
        }
    }

    /**
     * Processes a single test case by reading the grid, validating against
     * a predefined pattern, and printing the result.
     */
    private static void solve(int n, int m, FastScanner scanner) {
        StringBuilder output = new StringBuilder();
        boolean possible = true;

        // Single pass: read input, validate, and build output simultaneously
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                int actual = scanner.nextInt();

                // Determine expected value based on cell position
                int expected;
                boolean isCorner = (i == 0 || i == n - 1) && (j == 0 || j == m - 1);
                boolean isEdge = i == 0 || i == n - 1 || j == 0 || j == m - 1;

                if (isCorner) {
                    expected = CORNER_VALUE;
                } else if (isEdge) {
                    expected = EDGE_VALUE;
                } else {
                    expected = INNER_VALUE;
                }

                // Condition: actual value must not exceed the expected pattern value
                if (actual > expected) {
                    possible = false;
                }

                // Append to output buffer (avoids trailing spaces)
                output.append(expected).append(j == m - 1 ? "" : " ");
            }
