     * Interior cells: max 4
     * Edge cells (non-corner): max 3
     * Corner cells: max 2
     */
    static class GridValidator {
        private static final int MAX_INTERIOR = 4;
        private static final int MAX_EDGE = 3;
        private static final int MAX_CORNER = 2;

        public void solve(FastScanner in, PrintWriter out) {
            int t = in.nextInt();
            while (t-- > 0) {
                int n = in.nextInt();
                int m = in.nextInt();
                boolean isValid = true;

                // Read input and validate constraints
                for (int i = 0; i < n; i++) {
                    for (int j = 0; j < m; j++) {
                        int val = in.nextInt();
                        int maxAllowed = getMaxAllowedValue(i, j, n, m);
                        if (val > maxAllowed) {
                            isValid = false;
                        }
                    }
                }

                if (isValid) {
                    out.println("YES");
                    // Output the grid of maximum allowed values
                    for (int i = 0; i < n; i++) {
                        for (int j = 0; j < m; j++) {
                            out.print(getMaxAllowedValue(i, j, n, m) + (j == m - 1 ? "" : " "));
