                } else {
                    out.println("NO");
                }
            }
        }

        /**
         * Calculates the maximum allowed value based on cell position.
         * Interior: 4, Edge: 3, Corner: 2
         */
        private int getMaxAllowedValue(int i, int j, int n, int m) {
            int max = MAX_INTERIOR;
            if (i == 0 || i == n - 1) max--;
            if (j == 0 || j == m - 1) max--;
