                // If the cell value exceeds the number of valid neighbors, the condition fails
                if (grid[i][j] > neighborCount) {
                    isPossible = false;
                    break;
                }
                // Update the grid value to the calculated neighbor count
                grid[i][j] = neighborCount;
            }
            if (!isPossible) {
                break;
