    private static int countNeighbors(int rows, int cols, int r, int c) {
        int count = 0;
        if (r > 0) count++;          // Up
        if (r < rows - 1) count++;   // Down
        if (c > 0) count++;          // Left
        if (c < cols - 1) count++;   // Right
