public class GridNeighborChecker {

    // Direction vectors for moving Right, Up, Left, Down
    // dr: change in row index, dc: change in column index
    private static final int[] DR = {0, -1, 0, 1};
    private static final int[] DC = {1, 0, -1, 0};

    public static void main(String[] args) {
        // Initialize I/O resources
        FastScanner scanner = new FastScanner(System.in);
        PrintWriter printWriter = new PrintWriter(System.out);

        try {
            // Read number of test cases
            // We check for null to handle potential empty input gracefully
            String tStr = scanner.next();
            if (tStr != null) {
                int t = Integer.parseInt(tStr);
                for (int tt = 1; tt <= t; ++tt) {
                    solve(scanner, printWriter);
                }
            }
        } catch (Exception e) {
            // In a production environment, log the exception.
            // For this script, we ensure output is flushed.
            e.printStackTrace();
        } finally {
            // Ensure all output is written
            printWriter.flush();
            printWriter.close();
        }
    }

    /**
     * Solves a single test case.
     *
     * @param sc  The scanner to read input from.
     * @param out The writer to output results to.
     */
    private static void solve(FastScanner sc, PrintWriter out) {
        int rows = sc.nextInt();
        int cols = sc.nextInt();

        int[][] grid = new int[rows][cols];

        // Read the grid values
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                grid[r][c] = sc.nextInt();
            }
        }

        int[][] neighborCounts = new int[rows][cols];
        boolean allCellsValid = true;

        // Iterate over each cell to calculate neighbor counts and validate
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                int count = 0;

                // Check all 4 adjacent neighbors
                for (int d = 0; d < 4; d++) {
                    int nr = r + DR[d];
                    int nc = c + DC[d];

                    // Check if neighbor is within grid bounds
                    if (nr >= 0 && nr < rows && nc >= 0 && nc < cols) {
                        count++;
                    }
                }

                neighborCounts[r][c] = count;

                // Validation logic: cell value must not exceed its neighbor count
                if (grid[r][c] > count) {
                    allCellsValid = false;
                }
            }
        }

        // Output the result for the current test case
        if (!allCellsValid) {
            out.println("NO");
        } else {
            out.println("YES");
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    out.print(neighborCounts[r][c] + " ");
                }
                out.println();
            }
        }
    }

    /**
     * A helper class for fast input reading.
     */
    static class FastScanner {
        BufferedReader br;
        StringTokenizer st;

        public FastScanner(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        /**
         * Reads the next token from the input.
         *
         * @return The next token string, or null if end of stream.
         */
        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) {
                        return null;
                    }
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return st.nextToken();
        }

        /**
         * Reads the next integer token.
         *
         * @return The parsed integer.
         */
        int nextInt() {
            String s = next();
            if (s == null) {
                throw new RuntimeException("Unexpected end of input");
            }
            return Integer.parseInt(s);
        }

        /**
         * Reads the next long token.
         *
