/**
 * Refactored solution for CF1375B.
 * 
 * Improvements made:
 * 1. Naming Conventions: Replaced generic names (asdf, r, c, orig, copy) with descriptive ones.
 * 2. Magic Numbers: Extracted constants (4, 3, buffer size) for better readability and maintenance.
 * 3. Separation of Concerns: Extracted test case logic into a dedicated method (solveTestCase).
 * 4. Memory Optimization: Removed the redundant 'orig' array. We only need to store the 
 *    generated grid ('generatedGrid') for output, as the input values are consumed immediately.
 * 5. Helper Methods: Extracted grid printing and value calculation logic to reduce nesting.
 * 6. Imports: Removed unused imports (java.text, java.math).
 * 7. Error Handling: Improved FastScanner robustness.
 */
public class CF1375B {

    // Constants for grid logic
    private static final int INTERIOR_VALUE = 4;
    private static final int BOUNDARY_DECREMENT = 1;
    private static final int BUFFER_SIZE = 32768;

    public static void main(String[] args) {
        new CF1375B().run();
    }

    public void run() {
        FastScanner scanner = new FastScanner();
        PrintWriter out = new PrintWriter(System.out);

        try {
            // Read number of test cases
            int testCases = scanner.nextInt();

            while (testCases-- > 0) {
                solveTestCase(scanner, out);
            }
        } catch (Exception e) {
            // In a competitive programming context, exceptions usually indicate runtime errors.
            // In a production environment, proper logging would be required.
            e.printStackTrace();
        } finally {
            out.flush();
            try {
                scanner.close();
            } catch (IOException e) {
                e.printStackTrace();
            }
        }
    }

    /**
     * Processes a single test case.
     */
    private void solveTestCase(FastScanner scanner, PrintWriter out) {
        int rows = scanner.nextInt();
        int cols = scanner.nextInt();

        // We only need to store the generated grid to print it later.
        // We do not need to store the input grid ('orig') as we compare values on the fly.
        int[][] generatedGrid = new int[rows][cols];
        boolean isValid = true;

        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                int inputVal = scanner.nextInt();

                // Calculate the maximum allowed value for this cell based on position
                int maxAllowed = calculateMaxValue(i, j, rows, cols);

                // Check if input violates the constraint (input > maxAllowed)
                if (inputVal > maxAllowed) {
                    isValid = false;
                }

                // Store the generated value for output
                generatedGrid[i][j] = maxAllowed;
            }
        }

        if (isValid) {
            out.println("YES");
            printGrid(out, generatedGrid);
        } else {
            out.println("NO");
        }
    }

    /**
     * Calculates the maximum allowed value for a cell at (row, col).
     * 
     * Logic preserved from original code:
     * - Interior cells: 4
     * - Boundary cells (non-corner): 3 (decremented once)
     * - Corner cells: 2 (decremented twice due to row and column boundary checks)
     */
    private int calculateMaxValue(int row, int col, int rows, int cols) {
        int value = INTERIOR_VALUE;

        // Check row boundaries
        if (row == 0 || row == rows - 1) {
            value -= BOUNDARY_DECREMENT;
        }

        // Check column boundaries
        if (col == 0 || col == cols - 1) {
            value -= BOUNDARY_DECREMENT;
        }

        return value;
    }

    /**
     * Prints the 2D integer grid to the output stream.
     */
    private void printGrid(PrintWriter out, int[][] grid) {
        for (int i = 0; i < grid.length; i++) {
            for (int j = 0; j < grid[i].length; j++) {
                out.print(grid[i][j] + " ");
            }
            out.println();
        }
    }

    /**
     * FastScanner utility class for efficient input reading.
     */
    static class FastScanner {
        BufferedReader reader;
        StringTokenizer tokenizer;

        public FastScanner() {
            reader = new BufferedReader(new InputStreamReader(System.in), BUFFER_SIZE);
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            String s = next();
            if (s == null) throw new RuntimeException("End of input");
            return Integer.parseInt(s);
        }

        public long nextLong() {
            return Long.parseLong(next());
        }

        public double nextDouble() {
            return Double.parseDouble(next());
        }

        public void close() throws IOException {
            reader.close();
        }
    }
}

import java.util.Scanner;

/**
 * A program to analyze a matrix based on neighbor counts.
 * For each cell, if the value is less than or equal to the number of 
 * orthogonal neighbors, the value is updated to the neighbor count.
 * If any cell fails this condition, the result is "NO".
 */
public class NeighborChecker {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        // Check if input exists to prevent exceptions on empty input
        if (scanner.hasNextInt()) {
            int testCases = scanner.nextInt();

            // Process each test case
            for (int t = 0; t < testCases; t++) {
                processTestCase(scanner);
            }
        }

        scanner.close();
    }

    /**
     * Reads a test case, processes the matrix, and prints the result.
     */
    private static void processTestCase(Scanner scanner) {
        // Read dimensions
        int rows = scanner.nextInt();
        int cols = scanner.nextInt();

        int[][] matrix = new int[rows][cols];

        // Read matrix data
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                matrix[i][j] = scanner.nextInt();
            }
        }

        boolean isValid = true;

        // Process logic: Check condition and update matrix
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                int currentValue = matrix[i][j];
                int neighborCount = calculateNeighborCount(i, j, rows, cols);

                // If the value is <= neighbor count, update it.
                // If not, the entire test case is invalid.
                if (currentValue <= neighborCount) {
                    matrix[i][j] = neighborCount;
                } else {
                    isValid = false;
                }
            }
        }

        // Output results
        if (isValid) {
            System.out.println("YES");
            printMatrix(matrix);
        } else {
            System.out.println("NO");
        }
    }

    /**
     * Calculates the number of orthogonal neighbors (Up, Down, Left, Right) 
     * for a cell at (row, col) within a grid of size (rows, cols).
     */
    private static int calculateNeighborCount(int row, int col, int rows, int cols) {
        int count = 0;

        // Check Up
        if (row > 0) {
            count++;
        }
        // Check Down
        if (row < rows - 1) {
            count++;
        }
        // Check Left
        if (col > 0) {
            count++;
        }
        // Check Right
        if (col < cols - 1) {
            count++;
        }

        return count;
    }

    /**
     * Prints the matrix to standard output.
     */
    private static void printMatrix(int[][] matrix) {
        for (int i = 0; i < matrix.length; i++) {
            for (int j = 0; j < matrix[i].length; j++) {
                System.out.print(matrix[i][j] + " ");
            }
            System.out.println();
        }
    }
}

