        }
    }

    /**
     * Processes a single test case: reads the grid, validates cell values against
     * their valid neighbor count, updates the grid, and prints the result.
     */
    private static void solve(FastScanner scanner, PrintWriter out) {
        int n = scanner.nextInt();
        int m = scanner.nextInt();
        int[][] grid = new int[n][m];

        // Read the grid dimensions and values
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                grid[i][j] = scanner.nextInt();
            }
        }

        // Validate and transform each cell
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                int validNeighbors = countValidNeighbors(grid, i, j);
                if (grid[i][j] > validNeighbors) {
                    out.println("NO");
                    return; // Skip remaining cells and proceed to next test case
                }
                grid[i][j] = validNeighbors;
            }
        }

        // All cells satisfy the condition
        out.println("YES");
        printGrid(out, grid);
