    /**
     * Counts the number of valid adjacent cells (up, down, left, right)
     * that lie within the grid boundaries.
     */
    private static int countValidNeighbors(int[][] grid, int row, int col) {
        int count = 0;
        if (row > 0) count++;
        if (row < grid.length - 1) count++;
        if (col > 0) count++;
        if (col < grid[0].length - 1) count++;
        return count;
    }

    /**
     * Formats and prints the 2D grid to the output stream.
     */
    private static void printGrid(PrintWriter out, int[][] grid) {
        for (int[] row : grid) {
            for (int value : row) {
                out.print(value).append(' ');
            }
            out.println();
        }
    }
}

