     * @param n   Total number of rows
     * @param m   Total number of columns
     * @return Classification value: 2 for corners, 3 for edges, 4 for interior
     */
    private static int getClassification(int row, int col, int n, int m) {
        boolean isEdge = (row == 0 || row == n - 1 || col == 0 || col == m - 1);
        if (!isEdge) {
            return 4; // Interior cell
        }
        boolean isCorner = (row == 0 || row == n - 1) && (col == 0 || col == m - 1);
        return isCorner ? 2 : 3; // Corner or edge
    }

    /**
     * Prints a 2D integer array to the output stream.
     * Elements are space-separated, and rows are newline-separated.
     *
     * @param grid The grid to print
     * @param out  Output stream
     */
    private static void printGrid(int[][] grid, PrintWriter out) {
        for (int i = 0; i < grid.length; i++) {
            for (int j = 0; j < grid[i].length; j++) {
                if (j > 0) {
                    out.print(" ");
                }
                out.print(grid[i][j]);
            }
            out.println();
        }
    }
}

import java.util.Scanner;

public class NeighborGrid {

    /**
     * Calculates the number of valid orthogonal neighbors for a cell at (row, col).
     * Neighbors are defined as cells directly above, below, left, or right.
     *
     * @param grid The 2D grid array.
     * @param row  The current row index.
     * @param col  The current column index.
     * @return The count of valid neighbors.
     */
    private static int countNeighbors(int[][] grid, int row, int col) {
        int count = 0;
        int rows = grid.length;
        int cols = grid[0].length; // Assuming rectangular grid

        // Check Upper neighbor
        if (row > 0) {
            count++;
        }
        // Check Lower neighbor
        if (row < rows - 1) {
            count++;
        }
        // Check Left neighbor
        if (col > 0) {
            count++;
        }
        // Check Right neighbor
        if (col < cols - 1) {
            count++;
        }

        return count;
    }

    /**
     * Validates the grid and updates cell values based on neighbor counts.
     * A cell is valid if its value is less than or equal to the number of its neighbors.
     * If valid, the cell's value is replaced by the neighbor count.
     *
     * @param grid The 2D grid to validate and update.
     * @return true if all cells are valid, false otherwise.
     */
    private static boolean validateAndUpdateGrid(int[][] grid) {
        int rows = grid.length;
        int cols = grid[0].length;

        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                int neighborCount = countNeighbors(grid, i, j);

                // Condition: Cell value must not exceed neighbor count
                if (grid[i][j] > neighborCount) {
                    return false;
                }

                // Update cell value to match neighbor count
                grid[i][j] = neighborCount;
            }
        }
        return true;
    }

    public static void main(String[] args) {
        // Use try-with-resources for automatic resource management
        try (Scanner scanner = new Scanner(System.in)) {
            if (scanner.hasNextInt()) {
                int testCases = scanner.nextInt();

                // Loop through each test case
                for (int t = 0; t < testCases; t++) {
                    int rows = scanner.nextInt();
                    int cols = scanner.nextInt();
                    int[][] grid = new int[rows][cols];

                    // Read the grid values
                    for (int i = 0; i < rows; i++) {
                        for (int j = 0; j < cols; j++) {
                            grid[i][j] = scanner.nextInt();
                        }
                    }

                    // Process the grid
                    if (!validateAndUpdateGrid(grid)) {
                        System.out.println("NO");
                    } else {
                        System.out.println("YES");
                        StringBuilder output = new StringBuilder();
                        for (int i = 0; i < rows; i++) {
                            for (int j = 0; j < cols; j++) {
                                output.append(grid[i][j]).append(" ");
                            }
                            // Append newline character between rows
                            if (i < rows - 1) {
                                output.append("\n");
                            }
                        }
                        System.out.println(output.toString());
                    }
                }
            }
        }
    }
}

