    /**
     * Processes a single test case: reads the grid, validates constraints,
     * replaces values with valid direction counts, and prints the result.
     */
    private static void solve(FastScanner sc, PrintWriter out) throws IOException {
        int n = sc.nextInt();
        int m = sc.nextInt();
        int[][] grid = new int[n][m];

        // Read the grid
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                grid[i][j] = sc.nextInt();
            }
        }

        // Process the grid
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                int validDirections = countValidDirections(grid, i, j);
                if (grid[i][j] > validDirections) {
                    out.println("NO");
                    return;
                }
                grid[i][j] = validDirections;
            }
        }

        // Output result
        out.println("YES");
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                out.print(grid[i][j]);
                out.print(j == m - 1 ? "" : " ");
            }
            out.println();
        }
    }

    /**
     * Counts the number of valid adjacent directions (up, left, down, right)
     * within the grid boundaries.
     */
    private static int countValidDirections(int[][] grid, int row, int col) {
        int count = 0;
        if (row > 0) count++;
        if (col > 0) count++;
        if (row < grid.length - 1) count++;
        if (col < grid[0].length - 1) count++;
        return count;
    }

