import java.util.Scanner;

public class Main {
    // Constants for the thresholds defined in the problem logic
    // Using constants improves maintainability by centralizing magic numbers
    private static final int CORNER_THRESHOLD = 2;
    private static final int EDGE_THRESHOLD = 3;
    private static final int INTERIOR_THRESHOLD = 4;

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        // Check if input exists to prevent NoSuchElementException
        if (scanner.hasNextInt()) {
            int numTestCases = scanner.nextInt();

            // Process each test case
            for (int t = 0; t < numTestCases; t++) {
                solve(scanner);
            }
        }

        scanner.close();
    }

    /**
     * Solves a single test case by reading input, validating, and printing output.
     */
    private static void solve(Scanner scanner) {
        int rows = scanner.nextInt();
        int cols = scanner.nextInt();

        int[][] matrix = new int[rows][cols];

        // Read the matrix elements
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                matrix[i][j] = scanner.nextInt();
            }
        }

        // Validate the matrix against the rules
        if (isValid(matrix)) {
            System.out.println("YES");
            printPattern(rows, cols);
        } else {
            System.out.println("NO");
        }
    }

    /**
     * Checks if the matrix satisfies the conditions:
     * - Corners must be <= 2
     * - Edges must be <= 3
     * - Interior cells must be <= 4
     * 
     * @param matrix The 2D array to check
     * @return true if valid, false otherwise
     */
    private static boolean isValid(int[][] matrix) {
        int rows = matrix.length;
        if (rows == 0) return true;
        int cols = matrix[0].length;

        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                int limit = getCellLimit(i, j, rows, cols);
                if (matrix[i][j] > limit) {
                    return false; // Early exit on first violation
                }
            }
        }
        return true;
    }

    /**
     * Determines the maximum allowed value for a cell based on its position.
     * This logic encapsulates the complex boundary checks found in the original code.
     */
    private static int getCellLimit(int row, int col, int rows, int cols) {
        // A cell is a corner if it is in the first/last row AND first/last column
        boolean isCorner = (row == 0 || row == rows - 1) && (col == 0 || col == cols - 1);

        // A cell is an edge if it is in the first/last row OR first/last column
        boolean isEdge = (row == 0 || row == rows - 1 || col == 0 || col == cols - 1);

        if (isCorner) {
            return CORNER_THRESHOLD;
        } else if (isEdge) {
            return EDGE_THRESHOLD;
        } else {
            return INTERIOR_THRESHOLD;
        }
    }

    /**
     * Prints the required pattern of limits for a valid matrix.
     * Uses StringBuilder for better I/O performance compared to repeated System.out.print.
     */
    private static void printPattern(int rows, int cols) {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                int limit = getCellLimit(i, j, rows, cols);
                sb.append(limit).append(" ");
            }
            sb.append("\n");
        }
        System.out.print(sb.toString());
    }
}

