                    matrix[i][j] = neighborCount;
                }
            }

            out.println(isValid ? "YES" : "NO");
            if (isValid) {
                printMatrix(out, matrix);
            }
        }

        /**
         * Counts the number of orthogonal (up, down, left, right) 
         * neighbors within the grid boundaries.
         */
        private int countValidNeighbors(int row, int col, int totalRows, int totalCols) {
            int count = 0;
            if (row > 0) count++;
            if (row < totalRows - 1) count++;
            if (col > 0) count++;
            if (col < totalCols - 1) count++;
            return count;
