/**
 * A solver for grid neighbor problems.
 * It reads a grid of integers, checks if each cell's value is less than or equal to
 * the count of its valid neighbors, and updates the grid accordingly.
 */
public class GridNeighborSolver {

    // Direction vectors for Up, Down, Left, Right
    private static final int[] DX = {0, 0, -1, 1};
    private static final int[] DY = {-1, 1, 0, 0};

    private FastScanner scanner;
    private PrintWriter out;

    public static void main(String[] args) {
        new GridNeighborSolver().run();
    }

    public void run() {
        scanner = new FastScanner();
        out = new PrintWriter(System.out);

        try {
            // Read number of test cases
            String tStr = scanner.next();
            if (tStr != null) {
                int testCases = Integer.parseInt(tStr);
                while (testCases-- > 0) {
                    solve();
                }
            }
        } catch (Exception e) {
            // In a production environment, proper logging should be used.
            // For competitive programming contexts, this often results in a Runtime Error.
            e.printStackTrace();
        } finally {
            out.flush();
            out.close();
        }
    }

    private void solve() {
        // Read dimensions
        int rows = scanner.nextInt();
        int cols = scanner.nextInt();

        int[][] grid = new int[rows][cols];

        // Read grid data
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                grid[i][j] = scanner.nextInt();
            }
        }

        // Process grid
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                // Calculate neighbor count once to avoid redundant calculations
                int neighborCount = countValidNeighbors(i, j, rows, cols);

                if (neighborCount >= grid[i][j]) {
                    grid[i][j] = neighborCount;
                } else {
                    out.println("NO");
                    return; // Exit solve method to proceed to next test case
                }
            }
        }

        // Output result
        out.println("YES");
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                out.print(grid[i][j] + " ");
            }
            out.println();
        }
    }

    /**
     * Counts the number of valid neighbors (within grid bounds) for a given cell.
     * Note: This logic only checks coordinate validity, not the values of neighbors.
     */
    private int countValidNeighbors(int x, int y, int rows, int cols) {
        int count = 0;
        for (int k = 0; k < 4; k++) {
            int nx = x + DX[k];
            int ny = y + DY[k];
            if (isValidCoordinate(nx, ny, rows, cols)) {
                count++;
            }
        }
        return count;
    }

    /**
     * Checks if the given coordinates are within the grid boundaries.
     */
    private boolean isValidCoordinate(int x, int y, int rows, int cols) {
        return x >= 0 && x < rows && y >= 0 && y < cols;
    }

    /**
     * Helper class for fast input reading.
     */
    static class FastScanner {
        BufferedReader br;
        StringTokenizer st;

        public FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    e.printStackTrace();
                    return null;
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            String s = next();
            if (s == null) throw new RuntimeException("Unexpected end of input");
            return Integer.parseInt(s);
        }
    }
}

import java.io.*;
import java.util.StringTokenizer;

public class MatrixProcessor {

    // Configuration constants for matrix validation rules
    private static final int INTERIOR_MAX_VALUE = 4;
    private static final int CORNER_MAX_VALUE = 2;
    private static final int EDGE_MAX_VALUE = 3;

    public static void main(String[] args) throws IOException {
        FastScanner scanner = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            int t = scanner.nextInt();
            while (t-- > 0) {
                int n = scanner.nextInt();
                int m = scanner.nextInt();
                int[][] matrix = new int[n][m];

                for (int i = 0; i < n; i++) {
                    matrix[i] = scanner.nextIntArray(m);
                }

                processMatrix(matrix, out);
            }
        } finally {
            out.flush();
        }
    }

    /**
     * Validates and modifies the matrix according to region-specific constraints.
     * Interior cells: max 4, Corners: max 2, Edges: max 3.
     * Assumes n >= 3 and m >= 3 based on original logic.
     */
    private static void processMatrix(int[][] matrix, PrintWriter out) {
        int n = matrix.length;
        int m = matrix[0].length;

        // 1. Process interior cells
        for (int i = 1; i < n - 1; i++) {
            for (int j = 1; j < m - 1; j++) {
                if (matrix[i][j] > INTERIOR_MAX_VALUE) {
                    out.println("NO");
                    return;
                }
                matrix[i][j] = INTERIOR_MAX_VALUE;
            }
        }

        // 2. Process corner cells
        int[][] corners = {{0, 0}, {0, m - 1}, {n - 1, 0}, {n - 1, m - 1}};
        for (int[] corner : corners) {
            if (matrix[corner[0]][corner[1]] > CORNER_MAX_VALUE) {
                out.println("NO");
                return;
            }
            matrix[corner[0]][corner[1]] = CORNER_MAX_VALUE;
        }

        // 3. Process top and bottom edges (excluding corners)
        for (int j = 1; j < m - 1; j++) {
            if (matrix[0][j] > EDGE_MAX_VALUE || matrix[n - 1][j] > EDGE_MAX_VALUE) {
                out.println("NO");
                return;
            }
            matrix[0][j] = EDGE_MAX_VALUE;
            matrix[n - 1][j] = EDGE_MAX_VALUE;
        }

        // 4. Process left and right edges (excluding corners)
        for (int i = 1; i < n - 1; i++) {
            if (matrix[i][0] > EDGE_MAX_VALUE || matrix[i][m - 1] > EDGE_MAX_VALUE) {
                out.println("NO");
                return;
            }
            matrix[i][0] = EDGE_MAX_VALUE;
            matrix[i][m - 1] = EDGE_MAX_VALUE;
        }

        // Output success and the modified matrix
        out.println("YES");
        printMatrix(matrix, out);
    }

    private static void printMatrix(int[][] matrix, PrintWriter out) {
        for (int[] row : matrix) {
            for (int value : row) {
                out.print(value);
                out.print(' ');
            }
            out.println();
        }
    }

    /**
     * Fast I/O utility class for high-throughput input reading.
     */
    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        public FastScanner(String filePath) throws IOException {
            br = new BufferedReader(new FileReader(filePath));
        }

        public String next() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) throw new IOException("Unexpected end of input");
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        public long nextLong() throws IOException {
            return Long.parseLong(next());
        }

        public double nextDouble() throws IOException {
            return Double.parseDouble(next());
        }

        public char nextChar() throws IOException {
            return next().charAt(0);
        }

        public int[] nextIntArray(int n) throws IOException {
            int[] arr = new int[n];
            for (int i = 0; i < n; i++) arr[i] = nextInt();
            return arr;
        }

        public long[] nextLongArray(int n) throws IOException {
            long[] arr = new long[n];
            for (int i = 0; i < n; i++) arr[i] = nextLong();
            return arr;
        }

        public String nextLine() throws IOException {
            return br.readLine();
        }

        public boolean ready() throws IOException {
            return br.ready();
        }
    }

    /**
     * Mathematical utility methods.
     */
    private static final long MOD = 1_000_000_007L;

    private static long computePower(long base, long exp) {
        long result = 1;
        while (exp > 0) {
            if ((exp & 1) == 1) result = (result * base) % MOD;
            exp >>= 1;
            base = (base * base) % MOD;
        }
        return result;
    }

    private static long computeGcd(long a, long b) {
        return b == 0 ? a : computeGcd(b, a % b);
    }
}

import java.io.InputStream;
import java.io.OutputStream;
import java.io.PrintWriter;
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        Scanner in = new Scanner(inputStream);
        PrintWriter out = new PrintWriter(outputStream);

        TaskB solver = new TaskB();
        solver.solve(in, out);

        out.close();
    }

    static class TaskB {
        public void solve(Scanner in, PrintWriter out) {
            if (!in.hasNextInt()) return;
            int testCases = in.nextInt();
            while (testCases-- > 0) {
                int rows = in.nextInt();
                int cols = in.nextInt();
                int[][] matrix = new int[rows][cols];

                for (int i = 0; i < rows; i++) {
                    for (int j = 0; j < cols; j++) {
                        matrix[i][j] = in.nextInt();
                    }
                }

                if (processAndValidate(matrix, rows, cols)) {
                    out.println("YES");
                    printMatrix(matrix, out);
                } else {
                    out.println("NO");
                }
            }
        }

        /**
         * Validates that the matrix can be transformed into the required pattern
         * and applies the transformation in-place.
         * Returns true if valid, false otherwise.
         */
        private boolean processAndValidate(int[][] matrix, int rows, int cols) {
            for (int row = 0; row < rows; row++) {
                int cornerValue = (row == 0 || row == rows - 1) ? 2 : 3;
                int midValue = cornerValue + 1;

                // Validate and set corners
                if (matrix[row][0] > cornerValue || matrix[row][cols - 1] > cornerValue) {
                    return false;
                }
                matrix[row][0] = cornerValue;
                matrix[row][cols - 1] = cornerValue;

                // Validate and set middle elements
                for (int col = 1; col < cols - 1; col++) {
                    if (matrix[row][col] > midValue) {
                        return false;
                    }
                    matrix[row][col] = midValue;
                }
            }
            return true;
        }

        /**
         * Prints the matrix with proper spacing.
         */
        private void printMatrix(int[][] matrix, PrintWriter out) {
            for (int i = 0; i < matrix.length; i++) {
                for (int j = 0; j < matrix[i].length; j++) {
                    out.print(matrix[i][j]);
                    if (j < matrix[i].length - 1) {
                        out.print(' ');
                    }
                }
                out.println();
            }
        }
    }
}

