    private static void solve(FastScanner sc, PrintWriter out) {
        int numRows = sc.nextInt();
        int numCols = sc.nextInt();

        int[][] resultGrid = new int[numRows][numCols];
        boolean isValid = true;

        // Read input, compute adjacent counts, and validate in a single pass
        for (int i = 0; i < numRows; i++) {
            for (int j = 0; j < numCols; j++) {
                int value = sc.nextInt();
                int adjacentCount = getAdjacentCellCount(i, j, numRows, numCols);
                resultGrid[i][j] = adjacentCount;

                if (value > adjacentCount) {
                    isValid = false;
                }
            }
        }

        if (!isValid) {
            out.println("NO");
        } else {
            out.println("YES");
            for (int[] row : resultGrid) {
                for (int val : row) {
                    out.print(val + " ");
                }
                out.println();
            }
        }
    }

    /**
     * Calculates the number of valid orthogonal neighbors (up, down, left, right)
     * for a cell at (row, col) in a grid of size (numRows x numCols).
     */
    private static int getAdjacentCellCount(int row, int col, int numRows, int numCols) {
        int count = 0;
        if (row > 0) count++;           // Up
        if (col > 0) count++;           // Left
        if (row < numRows - 1) count++; // Down
        if (col < numCols - 1) count++; // Right
        return count;
    }

    /**
     * Efficient scanner for competitive programming / fast I/O.
     */
    private static class FastScanner {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastScanner() {
            reader = new BufferedReader(new InputStreamReader(System.in), 32768);
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }

        public double nextDouble() {
            return Double.parseDouble(next());
        }

        public String nextLine() {
            try {
                return reader.readLine();
            } catch (IOException e) {
                throw new RuntimeException(e);
            }
        }
    }
}

