import java.io.PrintWriter;
import java.util.StringTokenizer;

/**
 * Refactored Grid Validator.
 * 
 * Key Improvements:
 * 1. Meaningful naming: Class and variables follow Java conventions.
 * 2. Eliminated magic numbers: Limits (2, 3, 4) are defined as constants.
 * 3. Simplified boundary logic: Extracted position checking into a dedicated method.
 * 4. Removed dead code: Deleted unused `sa()`, `pair<U,V>`, and the complex custom `InputReader`.
 * 5. Standard I/O: Replaced the custom byte-level reader with `BufferedReader` + `StringTokenizer` 
 *    for better readability, maintainability, and standard compliance.
 * 6. Resource management: Ensured `PrintWriter` is properly flushed and closed.
 * 7. Cleaner control flow: Removed nested ternary-like conditions and unused thread wrapper.
 */
public class GridValidator {

    private static final int CORNER_LIMIT = 2;
    private static final int EDGE_LIMIT = 3;
    private static final int INTERIOR_LIMIT = 4;

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            int testCases = scanner.nextInt();
            while (testCases-- > 0) {
                int n = scanner.nextInt();
                int m = scanner.nextInt();
                int[][] grid = new int[n][m];
                boolean isValid = true;

                for (int i = 0; i < n; i++) {
                    for (int j = 0; j < m; j++) {
                        grid[i][j] = scanner.nextInt();
                        int limit = getCellLimit(i, j, n, m);
                        if (grid[i][j] > limit) {
                            isValid = false;
                        }
                        grid[i][j] = limit;
                    }
                }

                if (!isValid) {
                    out.println("NO");
                } else {
                    out.println("YES");
                    for (int i = 0; i < n; i++) {
                        for (int j = 0; j < m; j++) {
                            out.print(grid[i][j] + " ");
                        }
                        out.println();
                    }
                }
            }
        } catch (Exception e) {
            e.printStackTrace();
        } finally {
            out.flush();
            out.close();
        }
    }

    /**
     * Determines the maximum allowed value for a cell based on its grid position.
     * Corners: <= 2, Edges: <= 3, Interior: <= 4
     */
    private static int getCellLimit(int row, int col, int rows, int cols) {
        boolean isCorner = (row == 0 || row == rows - 1) && (col == 0 || col == cols - 1);
        boolean isEdge = row == 0 || row == rows - 1 || col == 0 || col == cols - 1;

        if (isCorner) return CORNER_LIMIT;
        if (isEdge) return EDGE_LIMIT;
        return INTERIOR_LIMIT;
    }

    /**
     * Fast I/O helper class using BufferedReader and StringTokenizer.
     * Replaces the original custom InputReader for better readability and standard compliance.
     */
    static class FastScanner {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastScanner(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        int nextInt() {
            String s = next();
            if (s == null) throw new RuntimeException("Unexpected end of input");
            return Integer.parseInt(s);
        }
    }
}

import java.io.BufferedReader;
