public class Main {
    public static void main(String[] args) {
        FastScanner in = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out);

        NeighborGridSolver solver = new NeighborGridSolver();
        solver.solve(in, out);

        out.flush();
        out.close();
    }

    static class NeighborGridSolver {
        // Direction vectors for up, down, left, right
        private static final int[] DIR_ROWS = {-1, 1, 0, 0};
        private static final int[] DIR_COLS = {0, 0, -1, 1};

        public void solve(FastScanner in, PrintWriter out) {
            int testCases = in.nextInt();
            for (int t = 0; t < testCases; t++) {
                int rows = in.nextInt();
                int cols = in.nextInt();
                int[][] grid = new int[rows][cols];

                // Read grid input
                for (int i = 0; i < rows; i++) {
                    for (int j = 0; j < cols; j++) {
                        grid[i][j] = in.nextInt();
                    }
                }

                // Process and output result for the current test case
                if (!processTestCase(grid, rows, cols, out)) {
                    continue; // Skip to the next test case
                }
            }
        }

        private boolean processTestCase(int[][] grid, int rows, int cols, PrintWriter out) {
            int[][] result = new int[rows][cols];

            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    int neighborCount = countValidNeighbors(i, j, rows, cols);

                    if (grid[i][j] > neighborCount) {
                        out.println("NO");
                        return false; // Invalid configuration found
                    }

                    result[i][j] = neighborCount;
                }
            }

            out.println("YES");
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    out.print(result[i][j] + (j == cols - 1 ? "" : " "));
                }
                out.println();
            }
            return true;
        }

        private int countValidNeighbors(int row, int col, int rows, int cols) {
            int count = 0;
            for (int k = 0; k < DIR_ROWS.length; k++) {
                int newRow = row + DIR_ROWS[k];
                int newCol = col + DIR_COLS[k];

                if (newRow >= 0 && newRow < rows && newCol >= 0 && newCol < cols) {
                    count++;
                }
            }
            return count;
        }
    }

    /**
     * Standard fast I/O helper using BufferedReader and StringTokenizer.
     * Replaces custom byte-buffer readers for better maintainability.
     */
    static class FastScanner {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastScanner(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) {
                        throw new IOException("Unexpected end of input");
                    }
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input", e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            try {
                return Integer.parseInt(next());
            } catch (NumberFormatException e) {
                throw new IllegalArgumentException("Invalid integer format", e);
            }
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

/**
 * Determines if a grid satisfies the neighbor constraint and outputs the 
 * modified grid or a failure message.
 */
public class NeighborGrid {

    private static final int[][] DIRECTIONS = {
        {0, 1},   // Right
        {-1, 0},  // Up
        {0, -1},  // Left
        {1, 0}    // Down
    };

    public static void main(String[] args) {
        FastReader reader = new FastReader();
        StringBuilder output = new StringBuilder();

        int t = reader.nextInt();
        for (int i = 0; i < t; i++) {
            output.append(solveTestCase(reader));
        }
        System.out.print(output);
    }

    /**
     * Processes a single test case: reads the grid, validates constraints,
     * and formats the result.
     */
    private static String solveTestCase(FastReader reader) {
        int n = reader.nextInt();
        int m = reader.nextInt();

        int[][] grid = readGrid(reader, n, m);

        boolean isValid = true;
        for (int i = 0; i < n && isValid; i++) {
            for (int j = 0; j < m; j++) {
                int neighborCount = countValidNeighbors(i, j, n, m);
                if (grid[i][j] > neighborCount) {
                    isValid = false;
                    break;
                }
                grid[i][j] = neighborCount;
            }
        }

        if (!isValid) {
            return "NO\n";
        }

        StringBuilder result = new StringBuilder("YES\n");
        for (int[] row : grid) {
            for (int value : row) {
                result.append(value).append(' ');
            }
            result.append('\n');
        }
        return result.toString();
    }

    /**
     * Reads the n x m grid from the input stream.
     */
    private static int[][] readGrid(FastReader reader, int n, int m) {
        int[][] grid = new int[n][m];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                grid[i][j] = reader.nextInt();
            }
        }
        return grid;
    }

    /**
     * Counts the number of valid (in-bounds) orthogonal neighbors for a cell.
     */
    private static int countValidNeighbors(int x, int y, int n, int m) {
        int count = 0;
        for (int[] dir : DIRECTIONS) {
            int nx = x + dir[0];
            int ny = y + dir[1];
            if (nx >= 0 && nx < n && ny >= 0 && ny < m) {
                count++;
            }
        }
        return count;
    }

    /**
     * High-performance input reader for competitive programming scenarios.
     */
    public static class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) {
                        return null;
                    }
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input", e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            String s = next();
            if (s == null) throw new RuntimeException("Unexpected end of input");
            return Integer.parseInt(s);
        }

        long nextLong() {
            return Long.parseLong(next());
        }

        double nextDouble() {
            return Double.parseDouble(next());
        }

        float nextFloat() {
            return Float.parseFloat(next());
        }
    }
}

import java.util.Scanner;
import java.io.PrintWriter;
import java.io.BufferedOutputStream;

public class NeighborGrid {

    public static void main(String[] args) {
        // Use try-with-resources to ensure proper cleanup of I/O resources
        try (Scanner scanner = new Scanner(System.in);
             PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out))) {

            if (scanner.hasNextInt()) {
                int testCases = scanner.nextInt();
                for (int t = 0; t < testCases; t++) {
                    int rows = scanner.nextInt();
                    int cols = scanner.nextInt();
                    int[][] grid = new int[rows][cols];

                    // Read grid input
                    for (int i = 0; i < rows; i++) {
                        for (int j = 0; j < cols; j++) {
                            grid[i][j] = scanner.nextInt();
                        }
                    }

                    // Validate and transform the grid in a single pass
                    boolean isValid = validateAndTransformGrid(grid, rows, cols);

                    if (isValid) {
                        out.println("YES");
                        printGrid(out, grid);
                    } else {
                        out.println("NO");
                    }
                }
            }
            out.flush();
        }
    }

    /**
     * Validates the grid condition and transforms each cell to its valid neighbor count.
     * Returns false immediately if any cell fails the condition.
     */
    private static boolean validateAndTransformGrid(int[][] grid, int rows, int cols) {
        for (int row = 0; row < rows; row++) {
            for (int col = 0; col < cols; col++) {
                int validNeighborCount = countValidNeighbors(row, col, rows, cols);
                if (validNeighborCount < grid[row][col]) {
                    return false;
                }
                grid[row][col] = validNeighborCount;
            }
        }
        return true;
    }

    /**
     * Counts the number of valid adjacent cells (up, down, left, right) within grid bounds.
     */
    private static int countValidNeighbors(int row, int col, int rows, int cols) {
        int count = 0;
        if (row > 0) count++;
        if (row < rows - 1) count++;
        if (col > 0) count++;
        if (col < cols - 1) count++;
        return count;
    }

    /**
     * Prints the grid to the provided PrintWriter with space-separated values.
     */
    private static void printGrid(PrintWriter out, int[][] grid) {
        for (int row = 0; row < grid.length; row++) {
            for (int col = 0; col < grid[row].length; col++) {
                out.print(grid[row][col]);
                if (col < grid[row].length - 1) {
                    out.print(" ");
                }
            }
            out.println();
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

public class Practice {

    private static final int CORNER_LIMIT = 2;
    private static final int EDGE_LIMIT = 3;
    private static final int INTERIOR_LIMIT = 4;

    public static void main(String[] args) {
        FastReader reader = new FastReader();
        int t = reader.nextInt();
        while (t-- > 0) {
            int n = reader.nextInt();
            int m = reader.nextInt();
            solve(n, m, reader);
        }
    }

    private static void solve(int n, int m, FastReader reader) {
        boolean isValid = true;

        // Read matrix values and validate constraints
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                int value = reader.nextInt();
                if (!isValidConstraint(i, j, n, m, value)) {
                    isValid = false;
                }
            }
        }

        if (!isValid) {
            System.out.println("NO");
        } else {
            System.out.println("YES");
            printConstructedMatrix(n, m);
        }
    }

    private static boolean isValidConstraint(int i, int j, int n, int m, int value) {
        if (isCorner(i, j, n, m)) {
            return value <= CORNER_LIMIT;
        } else if (isEdge(i, j, n, m)) {
            return value <= EDGE_LIMIT;
        } else {
            return value <= INTERIOR_LIMIT;
        }
    }

    private static boolean isCorner(int i, int j, int n, int m) {
        return (i == 0 && j == 0) || (i == 0 && j == m - 1) ||
               (i == n - 1 && j == 0) || (i == n - 1 && j == m - 1);
    }

    private static boolean isEdge(int i, int j, int n, int m) {
        return i == 0 || i == n - 1 || j == 0 || j == m - 1;
    }

    private static void printConstructedMatrix(int n, int m) {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (isCorner(i, j, n, m)) {
                    sb.append(CORNER_LIMIT);
                } else if (isEdge(i, j, n, m)) {
                    sb.append(EDGE_LIMIT);
                } else {
                    sb.append(INTERIOR_LIMIT);
                }
                sb.append(j == m - 1 ? "" : " ");
            }
            sb.append("\n");
        }
        System.out.print(sb);
    }

    /**
     * Fast I/O reader commonly used in competitive programming.
     */
    static class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    e.printStackTrace();
                    return null;
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            String s = next();
            return s == null ? 0 : Integer.parseInt(s);
        }

        long nextLong() {
            String s = next();
            return s == null ? 0L : Long.parseLong(s);
        }
    }
}

