            // Handle potential end of stream gracefully
            return (s == null) ? 0 : Integer.parseInt(s);
        }
    }

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner();
        // Using BufferedOutputStream for faster output operations
        PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out));

        try {
            // Read number of test cases
            String tStr = scanner.next();
            if (tStr != null) {
                int t = Integer.parseInt(tStr);
                while (t-- > 0) {
                    int rows = scanner.nextInt();
                    int cols = scanner.nextInt();

                    // Read the grid
                    int[][] grid = new int[rows][cols];
                    for (int i = 0; i < rows; i++) {
                        for (int j = 0; j < cols; j++) {
                            grid[i][j] = scanner.nextInt();
                        }
                    }

                    // Process the test case
                    if (isValid(grid, rows, cols)) {
                        out.println("YES");
                        printSolution(rows, cols, out);
                    } else {
                        out.println("NO");
                    }
                }
            }
        } catch (Exception e) {
            // Logging exceptions is better than swallowing them silently
            e.printStackTrace();
        } finally {
            out.flush();
        }
    }

    /**
     * Validates the grid based on the problem constraints:
     * - Corners must be <= 2
     * - Edges (non-corners) must be <= 3
     * - Interior cells must be <= 4
     */
    private static boolean isValid(int[][] grid, int rows, int cols) {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                int limit = getCellLimit(i, j, rows, cols);
                if (grid[i][j] > limit) {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Returns the maximum allowed value for a cell at (r, c) based on its position.
     * 2 for corners, 3 for edges, 4 for interior.
     */
    private static int getCellLimit(int r, int c, int rows, int cols) {
        // Check if the cell is a corner
        boolean isCorner = (r == 0 && c == 0) ||
                           (r == 0 && c == cols - 1) ||
                           (r == rows - 1 && c == 0) ||
                           (r == rows - 1 && c == cols - 1);

        if (isCorner) {
            return 2;
        }

        // Check if the cell is on an edge (but not a corner)
        // Note: Corners are already handled above, so this strictly checks non-corner edges
        boolean isEdge = (r == 0 || r == rows - 1 || c == 0 || c == cols - 1);

        if (isEdge) {
            return 3;
        }

        // Interior cell
        return 4;
    }

    /**
     * Prints the solution grid.
     * The output grid follows the pattern: 2 at corners, 3 at edges, 4 at interior.
     */
    private static void printSolution(int rows, int cols, PrintWriter out) {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                out.print(getCellLimit(i, j, rows, cols));
                out.print(' ');
            }
            out.println();
        }
    }
}

import java.util.Scanner;

/**
 * Processes grid test cases to validate cell values based on their position.
 * Corners must be <= 2, edges <= 3, and interior cells <= 4.
 * If valid, outputs a standardized grid with these maximum values.
 */
public class NeighborGrid {

    private static final int MAX_VALUE = 4;
    private static final int EDGE_MAX = 3;
    private static final int CORNER_MAX = 2;

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            if (scanner.hasNextInt()) {
                int numTestCases = scanner.nextInt();
                for (int t = 0; t < numTestCases; t++) {
                    processTestCase(scanner);
                }
            }
        }
    }

    /**
     * Reads a single test case, validates the grid, and prints the result.
     */
    private static void processTestCase(Scanner scanner) {
        int rows = scanner.nextInt();
        int cols = scanner.nextInt();
        boolean isValid = true;

        // Read and validate the grid row by row
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                int value = scanner.nextInt();
                // Continue reading to keep scanner in sync, but skip redundant checks
                if (isValid && !validateCell(value, r, c, rows, cols)) {
                    isValid = false;
                }
            }
        }

        if (isValid) {
            System.out.println("YES");
            printResultGrid(rows, cols);
        } else {
            System.out.println("NO");
        }
    }

    /**
     * Determines if a cell's value meets the requirements for its position.
     */
    private static boolean validateCell(int value, int row, int col, int rows, int cols) {
        if (isCorner(row, col, rows, cols)) {
            return value <= CORNER_MAX;
        } else if (isEdge(row, col, rows, cols)) {
            return value <= EDGE_MAX;
        } else {
            return value <= MAX_VALUE;
        }
    }

    /**
     * Checks if the given coordinates represent a corner cell.
     */
    private static boolean isCorner(int row, int col, int rows, int cols) {
        return (row == 0 || row == rows - 1) && (col == 0 || col == cols - 1);
    }

    /**
     * Checks if the given coordinates represent an edge cell (including corners).
     */
    private static boolean isEdge(int row, int col, int rows, int cols) {
