    private static final int MAX_EDGE_VALUE = 3;
    private static final int MAX_INNER_VALUE = 4;

    public static void main(String[] args) {
        FastReader reader = new FastReader();
        // Try-with-resources ensures PrintWriter is properly flushed and closed
        try (PrintWriter writer = new PrintWriter(new OutputStreamWriter(System.out))) {
            int t = reader.nextInt();
            while (t-- > 0) {
                processTestCase(reader, writer);
            }
            writer.flush();
        } catch (IOException e) {
            System.err.println("I/O Error: " + e.getMessage());
        }
    }

    /**
     * Processes a single test case: reads the grid, validates constraints,
     * and outputs the result.
     */
    private static void processTestCase(FastReader reader, PrintWriter writer) {
        int n = reader.nextInt();
        int m = reader.nextInt();

        boolean isValid = true;

        // Read input and validate against position-based constraints
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                int value = reader.nextInt();
                if (value > getMaxAllowedValue(i, j, n, m)) {
                    isValid = false;
                }
            }
        }

        if (!isValid) {
            writer.println("NO");
        } else {
            writer.println("YES");
            // Output the transformed grid based on position rules
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    writer.print(getMaxAllowedValue(i, j, n, m));
                    writer.print(" ");
                }
                writer.println();
            }
        }
    }

    /**
     * Determines the maximum allowed value for a cell based on its grid position.
     * Corners: 2, Edges: 3, Interior: 4
     */
    private static int getMaxAllowedValue(int row, int col, int n, int m) {
        boolean isCorner = (row == 0 || row == n - 1) && (col == 0 || col == m - 1);
        boolean isEdge = row == 0 || row == n - 1 || col == 0 || col == m - 1;

        if (isCorner) {
            return MAX_CORNER_VALUE;
        } else if (isEdge) {
            return MAX_EDGE_VALUE;
        } else {
            return MAX_INNER_VALUE;
        }
    }

    /**
     * High-performance input reader commonly used in competitive programming.
     * Encapsulates BufferedReader and StringTokenizer for token-based parsing.
     */
    static class FastReader {
