public class NeighborGrid {

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner();
        // Guard against empty input
        String tStr = scanner.next();
        if (tStr == null) return;
        int t = Integer.parseInt(tStr);

        StringBuilder output = new StringBuilder();

        while (t-- > 0) {
            int n = scanner.nextInt();
            int m = scanner.nextInt();
            int[][] grid = new int[n][m];
            boolean isValid = true;

            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    int inputValue = scanner.nextInt();
                    int requiredValue = calculateRequiredValue(i, j, n, m);

                    grid[i][j] = requiredValue;

                    if (inputValue < requiredValue) {
                        isValid = false;
                    }
                }
            }

            if (isValid) {
                output.append("YES\n");
                for (int i = 0; i < n; i++) {
                    for (int j = 0; j < m; j++) {
                        output.append(grid[i][j]).append(j == m - 1 ? "" : " ");
                    }
                    output.append("\n");
                }
            } else {
                output.append("NO\n");
            }
        }
        System.out.print(output);
    }

    /**
     * Calculates the minimum required value for a cell based on its position.
     * - Corners: 2
     * - Edges (non-corner): 3
     * - Interior: 4
     */
    private static int calculateRequiredValue(int row, int col, int n, int m) {
        boolean isRowEdge = (row == 0 || row == n - 1);
        boolean isColEdge = (col == 0 || col == m - 1);

        if (isRowEdge && isColEdge) {
            return 2;
        } else if (isRowEdge || isColEdge) {
            return 3;
        } else {
            return 4;
        }
    }

    /**
     * Optimized input reader for competitive programming and fast I/O.
     */
    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        public String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            String s = next();
            return s == null ? 0 : Integer.parseInt(s);
        }
    }
}

import java.util.Scanner;

public class Solution {

    // Constants defining the maximum allowed values for each cell type
    private static final int MAX_CORNER_VALUE = 2;
    private static final int MAX_EDGE_VALUE = 3;
    private static final int MAX_INNER_VALUE = 4;

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        // Check if input exists to avoid exceptions on empty input
        if (scanner.hasNextInt()) {
            int numTestCases = scanner.nextInt();

            for (int t = 0; t < numTestCases; t++) {
                solveTestCase(scanner);
            }
        }

        scanner.close();
    }

    /**
     * Handles the logic for a single test case.
     */
    private static void solveTestCase(Scanner scanner) {
        int rows = scanner.nextInt();
        int cols = scanner.nextInt();

        int[][] grid = new int[rows][cols];

        // Read the grid input
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                grid[i][j] = scanner.nextInt();
            }
        }

        // Validate and transform the grid
        boolean isValid = validateAndTransform(grid, rows, cols);

        // Output results
        if (isValid) {
            System.out.println("YES");
            printGrid(grid);
        } else {
            System.out.println("NO");
        }
    }

    /**
     * Validates the grid constraints and transforms values based on position.
     * Returns true if valid, false otherwise.
     */
    private static boolean validateAndTransform(int[][] grid, int rows, int cols) {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                int value = grid[i][j];

                boolean isCorner = isCorner(i, j, rows, cols);
                boolean isEdge = isEdge(i, j, rows, cols);

                int maxAllowed;

                // Determine the maximum allowed value based on position
                if (isCorner) {
                    maxAllowed = MAX_CORNER_VALUE;
                } else if (isEdge) {
                    maxAllowed = MAX_EDGE_VALUE;
                } else {
                    maxAllowed = MAX_INNER_VALUE;
                }

                // Check validity
                if (value > maxAllowed) {
                    return false;
                }

                // Transform the value based on position
                if (isCorner) {
                    grid[i][j] = MAX_CORNER_VALUE;
                } else if (isEdge) {
                    grid[i][j] = MAX_EDGE_VALUE;
                } else {
                    grid[i][j] = MAX_INNER_VALUE;
                }
            }
        }
        return true;
    }

    /**
     * Checks if a cell is a corner of the grid.
     */
    private static boolean isCorner(int row, int col, int rows, int cols) {
        return (row == 0 || row == rows - 1) && (col == 0 || col == cols - 1);
    }

    /**
     * Checks if a cell is on the edge of the grid.
     * Note: This includes corners, but validateAndTransform checks corners first.
     */
    private static boolean isEdge(int row, int col, int rows, int cols) {
        return (row == 0 || row == rows - 1 || col == 0 || col == cols - 1);
    }

    /**
     * Prints the grid to standard output.
     */
    private static void printGrid(int[][] grid) {
        for (int[] row : grid) {
            for (int val : row) {
                System.out.print(val + " ");
            }
            System.out.println();
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

public class Main {

    // Constants defining the constraints for each cell type
    private static final int CORNER_LIMIT = 2;
    private static final int EDGE_LIMIT = 3;
    private static final int INTERIOR_LIMIT = 4;

    public static void main(String[] args) {
        FastReader sc = new FastReader();

        try {
            // Read the number of test cases
            String tStr = sc.next();
            if (tStr == null) return;
            int t = Integer.parseInt(tStr);

            while (t-- > 0) {
                // Read dimensions
                String nStr = sc.next();
                if (nStr == null) break;
                int n = Integer.parseInt(nStr);
                int m = sc.nextInt();

                boolean isValid = true;

                // Read the grid and validate constraints
                // We iterate through all elements to consume the input stream correctly,
                // even if a validation failure occurs early.
                for (int i = 0; i < n; i++) {
                    for (int j = 0; j < m; j++) {
                        int val = sc.nextInt();

                        // Optimization: Only validate if we haven't already found an invalid cell
                        if (isValid) {
                            if (!isCellValid(i, j, n, m, val)) {
                                isValid = false;
                            }
                        }
                    }
                }

                if (isValid) {
                    System.out.println("YES");
                    printPatternGrid(n, m);
                } else {
                    System.out.println("NO");
                }
            }
        } catch (Exception e) {
            // In a production environment, proper logging should be used.
            // For competitive programming, printing stack trace helps debugging.
            e.printStackTrace();
        }
    }

    /**
     * Checks if the value at the specified grid position satisfies the problem constraints.
     * 
     * @param row Current row index (0-based)
     * @param col Current column index (0-based)
     * @param rows Total number of rows
     * @param cols Total number of columns
     * @param value The value in the grid cell
     * @return true if valid, false otherwise
     */
    private static boolean isCellValid(int row, int col, int rows, int cols, int value) {
        // Determine if the cell is a corner
        // Corners are at (0,0), (0, m-1), (n-1, 0), (n-1, m-1)
        boolean isCorner = (row == 0 || row == rows - 1) && (col == 0 || col == cols - 1);

        // Determine if the cell is on the edge (but not a corner, checked in if-else)
        // Edges are top row, bottom row, left col, right col
        boolean isEdge = row == 0 || row == rows - 1 || col == 0 || col == cols - 1;

        if (isCorner) {
            return value <= CORNER_LIMIT;
        } else if (isEdge) {
            return value <= EDGE_LIMIT;
        } else {
            // Interior cells
            return value <= INTERIOR_LIMIT;
        }
    }

    /**
     * Generates and prints the required pattern grid (2s, 3s, 4s) based on dimensions.
     * 
     * @param rows Number of rows
     * @param cols Number of columns
     */
    private static void printPatternGrid(int rows, int cols) {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                boolean isCorner = (i == 0 || i == rows - 1) && (j == 0 || j == cols - 1);
                boolean isEdge = i == 0 || i == rows - 1 || j == 0 || j == cols - 1;

                if (isCorner) {
                    sb.append("2 ");
                } else if (isEdge) {
                    sb.append("3 ");
                } else {
                    sb.append("4 ");
                }
            }
            sb.append("\n");
        }
        // Using println to match the original output format which adds a newline at the end
        System.out.println(sb);
    }

    /**
     * Helper class for fast input reading.
     */
    static class FastReader {
        BufferedReader br;
        StringTokenizer st;

        public FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            String s = next();
            if (s == null) throw new RuntimeException("End of input");
            return Integer.parseInt(s);
        }
    }
}

