/**
 * Solves a grid validation problem where cells have position-based value limits.
 * Refactored for maintainability, readability, and adherence to software engineering principles.
 */
public class GridProblemSolver {

    // Constants for grid values and constraints
    private static final int CORNER_VALUE = 2;
    private static final int EDGE_VALUE = 3;
    private static final int INTERIOR_VALUE = 4;

    private static final int MAX_CORNER_VALUE = 2;
    private static final int MAX_EDGE_VALUE = 3;
    private static final int MAX_INTERIOR_VALUE = 4;

    private final FastReader scanner = new FastReader();
    private final PrintWriter out = new PrintWriter(System.out);

    public static void main(String[] args) {
        GridProblemSolver solver = new GridProblemSolver();
        solver.run();
        solver.out.close();
    }

    /**
     * Orchestrates the execution flow for all test cases.
     */
    public void run() {
        int testCases = scanner.nextInt();
        while (testCases-- > 0) {
            solveTestCase();
        }
    }

    /**
     * Reads a single test case, validates constraints, and outputs the result.
     */
    private void solveTestCase() {
        int n = scanner.nextInt();
        int m = scanner.nextInt();
        long[][] grid = new long[n][m];

        // Read grid input
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                grid[i][j] = scanner.nextLong();
            }
        }

        if (isValid(grid, n, m)) {
            out.println("YES");
            printConstructedGrid(n, m);
        } else {
            out.println("NO");
        }
    }

    /**
     * Validates that all cells respect their position-based maximum value limits.
     */
    private boolean isValid(long[][] grid, int n, int m) {
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                int maxAllowed = getMaxAllowedValue(i, j, n, m);
                if (grid[i][j] > maxAllowed) {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Determines the maximum allowed value based on cell position.
     */
    private int getMaxAllowedValue(int i, int j, int n, int m) {
        if (isCorner(i, j, n, m)) {
            return MAX_CORNER_VALUE;
        } else if (isEdge(i, j, n, m)) {
            return MAX_EDGE_VALUE;
        }
        return MAX_INTERIOR_VALUE;
    }

    /**
     * Checks if a cell is a corner of the grid.
     */
    private boolean isCorner(int i, int j, int n, int m) {
        return (i == 0 || i == n - 1) && (j == 0 || j == m - 1);
    }

    /**
     * Checks if a cell is on the boundary (edge) of the grid.
     */
    private boolean isEdge(int i, int j, int n, int m) {
        return i == 0 || i == n - 1 || j == 0 || j == m - 1;
    }

    /**
     * Prints the constructed grid pattern based on position rules.
     */
    private void printConstructedGrid(int n, int m) {
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                int value;
                if (isCorner(i, j, n, m)) {
                    value = CORNER_VALUE;
                } else if (isEdge(i, j, n, m)) {
                    value = EDGE_VALUE;
                } else {
                    value = INTERIOR_VALUE;
                }
                out.print(value).print(' ');
            }
            out.println();
        }
    }

    /**
     * Fast I/O helper class for competitive programming environments.
     */
    static class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
            return st.nextToken();
