        } catch (Exception e) {
            // Graceful error handling for malformed input or unexpected EOF
            System.err.println("Input error: " + e.getMessage());
        } finally {
            out.flush();
        }
    }

    /**
     * Optimized FastScanner for competitive programming input reading.
     * Replaces manual byte-array parsing with BufferedReader + StringTokenizer
     * for better Java ecosystem integration and readability.
     */
    static class FastScanner {
        BufferedReader br;
        StringTokenizer st;

        public FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input", e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            String s = next();
            return s == null ? 0 : Integer.parseInt(s);
        }

        long nextLong() {
            String s = next();
            return s == null ? 0L : Long.parseLong(s);
        }

        double nextDouble() {
            String s = next();
            return s == null ? 0.0 : Double.parseDouble(s);
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

public class Grid {

    private static final int CORNER_VALUE = 2;
    private static final int EDGE_VALUE = 3;
    private static final int INNER_VALUE = 4;

    public static void main(String[] args) throws IOException {
        FastScanner scanner = new FastScanner();
        PrintWriter out = new PrintWriter(System.out);

        try {
            String tStr = scanner.next();
            if (tStr == null) return;
            int t = Integer.parseInt(tStr);

            for (int testIdx = 0; testIdx < t; testIdx++) {
                int n = scanner.nextInt();
                int m = scanner.nextInt();
                long[][] inputGrid = new long[n][m];

                for (int i = 0; i < n; i++) {
                    for (int j = 0; j < m; j++) {
                        inputGrid[i][j] = scanner.nextLong();
                    }
                }

                long[][] expectedGrid = generateExpectedGrid(n, m);

                if (isEqual(inputGrid, expectedGrid)) {
                    out.println("YES");
                    for (long[] row : expectedGrid) {
                        for (int j = 0; j < m; j++) {
                            out.print(row[j] + (j < m - 1 ? " " : ""));
                        }
                        out.println();
                    }
                } else {
                    out.println("NO");
                }
            }
        } finally {
            out.flush();
        }
    }

    /**
     * Compares two grids for equality.
     * Fixed logical bug from original: changed '>' to '!=' for proper equality check.
     */
    public static boolean isEqual(long[][] a, long[][] b) {
        if (a.length != b.length) {
            return false;
        }
        for (int i = 0; i < a.length; i++) {
            if (a[i].length != b[i].length) {
                return false;
            }
            for (int j = 0; j < a[i].length; j++) {
                if (a[i][j] != b[i][j]) {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Generates the expected grid based on position rules.
     * Replaced magic numbers with named constants and simplified boundary logic.
     */
    private static long[][] generateExpectedGrid(int n, int m) {
        long[][] grid = new long[n][m];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                boolean isCorner = (i == 0 || i == n - 1) && (j == 0 || j == m - 1);
                boolean isEdge = i == 0 || i == n - 1 || j == 0 || j == m - 1;
                grid[i][j] = isCorner ? CORNER_VALUE : (isEdge ? EDGE_VALUE : INNER_VALUE);
            }
        }
        return grid;
    }

    /**
     * A clean, standard-compliant fast input reader.
     * Replaced the custom InputReader to improve maintainability and remove error-prone code.
     */
    static class FastScanner {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastScanner() {
            reader = new BufferedReader(new InputStreamReader(System.in));
            tokenizer = new StringTokenizer("");
        }

        private String next() throws IOException {
            while (!tokenizer.hasMoreTokens()) {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            String s = next();
            return s == null ? 0 : Integer.parseInt(s);
        }

        public long nextLong() throws IOException {
            String s = next();
            return s == null ? 0L : Long.parseLong(s);
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

public class Codechef {
    public static void main(String[] args) {
        FastReader sc = new FastReader();
        PrintWriter out = new PrintWriter(System.out);

        int t = sc.nextInt();
        while (t-- > 0) {
            solve(sc, out);
        }

        out.flush();
        out.close();
    }

    private static void solve(FastReader sc, PrintWriter out) {
        int n = sc.nextInt();
        int m = sc.nextInt();
        int[][] matrix = new int[n][m];
        boolean hasNonZero = false;

        // Read input and track if any non-zero element exists
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                matrix[i][j] = sc.nextInt();
                if (matrix[i][j] > 0) {
                    hasNonZero = true;
                }
            }
        }

        // If all elements are zero, constraints are trivially satisfied
        if (!hasNonZero) {
            out.println("YES");
            printMatrix(out, matrix);
            return;
        }

        boolean possible = true;
        for (int i = 0; i < n && possible; i++) {
            for (int j = 0; j < m && possible; j++) {
                int maxAllowed = getMaxValueForPosition(i, j, n, m);
                if (matrix[i][j] > maxAllowed) {
                    possible = false;
                } else {
                    // Cap the value to the maximum allowed for this position
                    matrix[i][j] = Math.min(matrix[i][j], maxAllowed);
                }
            }
        }

        if (!possible) {
            out.println("NO");
        } else {
            out.println("YES");
            printMatrix(out, matrix);
        }
    }

    /**
     * Returns the maximum allowed value based on grid position:
     * Corners: 2, Edges: 3, Interior: 4
     */
    private static int getMaxValueForPosition(int i, int j, int n, int m) {
        boolean isCorner = (i == 0 || i == n - 1) && (j == 0 || j == m - 1);
        boolean isEdge = i == 0 || i == n - 1 || j == 0 || j == m - 1;

        if (isCorner) return 2;
        if (isEdge) return 3;
        return 4;
    }

    private static void printMatrix(PrintWriter out, int[][] matrix) {
        for (int[] row : matrix) {
            for (int value : row) {
                out.print(value).append(' ');
            }
            out.println();
        }
    }

    /**
     * Fast I/O helper class for competitive programming
     */
    static class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            String s = next();
            return s == null ? 0 : Integer.parseInt(s);
        }

        long nextLong() {
            String s = next();
            return s == null ? 0L : Long.parseLong(s);
        }

        double nextDouble() {
            String s = next();
            return s == null ? 0.0 : Double.parseDouble(s);
        }

        String nextLine() {
            String str = "";
            try {
                str = br.readLine();
            } catch (IOException e) {
                throw new RuntimeException("Error reading line", e);
            }
            return str;
        }
    }
}

import java.util.Scanner;

/**
 * Reads grid dimensions and values for multiple test cases.
 * Validates if each cell's value stays within position-based thresholds:
 *   Corners <= 2, Edges <= 3, Interior <= 4.
 * If valid, prints "YES" and outputs a standardized pattern grid.
 * Otherwise, prints "NO".
 */
public class GridPatternGenerator {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        if (scanner.hasNextInt()) {
            int testCases = scanner.nextInt();
            for (int t = 0; t < testCases; t++) {
                int rows = scanner.nextInt();
                int cols = scanner.nextInt();
                int[][] grid = new int[rows][cols];

                for (int i = 0; i < rows; i++) {
                    for (int j = 0; j < cols; j++) {
                        grid[i][j] = scanner.nextInt();
                    }
                }

                solveTestcase(rows, cols, grid);
            }
        }
        scanner.close();
    }

    /**
     * Processes a single test case: validates the input grid and prints the result.
     */
    private static void solveTestcase(int rows, int cols, int[][] grid) {
        if (isValid(grid, rows, cols)) {
            System.out.println("YES");
            int[][] pattern = generatePattern(rows, cols);
            printGrid(pattern);
        } else {
            System.out.println("NO");
        }
    }

    /**
     * Checks if all grid values are within their allowed thresholds.
     * Returns false immediately if any cell violates its position-based limit.
     */
    private static boolean isValid(int[][] grid, int rows, int cols) {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] > getThreshold(i, j, rows, cols)) {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Determines the maximum allowed value for a cell based on its position.
     *   - Corner cells: 2
     *   - Edge cells: 3
     *   - Interior cells: 4
     */
    private static int getThreshold(int row, int col, int rows, int cols) {
        boolean isCorner = (row == 0 || row == rows - 1) && (col == 0 || col == cols - 1);
        if (isCorner) {
            return 2;
        }

        boolean isEdge = (row == 0 || row == rows - 1) || (col == 0 || col == cols - 1);
        if (isEdge) {
            return 3;
        }

        return 4;
    }

    /**
     * Generates a standardized pattern grid where each cell contains 
     * its position-based threshold value.
     */
    private static int[][] generatePattern(int rows, int cols) {
        int[][] pattern = new int[rows][cols];
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                pattern[i][j] = getThreshold(i, j, rows, cols);
            }
        }
        return pattern;
    }

    /**
     * Prints the 2D array to standard output with consistent spacing.
     */
    private static void printGrid(int[][] grid) {
        for (int[] row : grid) {
            for (int value : row) {
                System.out.print(value + " ");
            }
            System.out.println();
        }
    }
}

import java.util.Scanner;

public class NeighbourGrid {

    private static final int CORNER_VALUE = 2;
    private static final int EDGE_VALUE = 3;
    private static final int INTERIOR_VALUE = 4;

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            if (scanner.hasNextInt()) {
                int numTestCases = scanner.nextInt();
                for (int t = 0; t < numTestCases; t++) {
                    if (!scanner.hasNextInt()) break;

                    int rows = scanner.nextInt();
                    int cols = scanner.nextInt();
                    int[][] grid = new int[rows][cols];

                    for (int r = 0; r < rows; r++) {
                        for (int c = 0; c < cols; c++) {
                            grid[r][c] = scanner.nextInt();
                        }
                    }
                    processGrid(grid);
                }
            }
        }
    }

    /**
     * Validates the grid and handles output formatting.
     */
    private static void processGrid(int[][] grid) {
        if (isGridValid(grid)) {
            System.out.println("YES");
            printTransformedGrid(grid);
        } else {
            System.out.println("NO");
        }
    }

    /**
     * Checks if all cells comply with the boundary constraints.
     */
    private static boolean isGridValid(int[][] grid) {
        if (grid == null || grid.length == 0 || grid[0].length == 0) {
            return false;
        }

        int rows = grid.length;
        int cols = grid[0].length;

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] > getExpectedValue(r, c, rows, cols)) {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Prints the transformed grid without modifying the original array.
     */
    private static void printTransformedGrid(int[][] grid) {
        int rows = grid.length;
        int cols = grid[0].length;
        StringBuilder output = new StringBuilder();

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                output.append(getExpectedValue(r, c, rows, cols)).append(' ');
            }
            // Remove trailing space and append newline
            if (output.length() > 0) {
                output.setLength(output.length() - 1);
            }
            output.append('\n');
        }
        System.out.print(output);
    }

    /**
     * Determines the expected value for a cell based on its position.
     */
    private static int getExpectedValue(int r, int c, int rows, int cols) {
        boolean isCorner = (r == 0 || r == rows - 1) && (c == 0 || c == cols - 1);
        boolean isEdge = r == 0 || r == rows - 1 || c == 0 || c == cols - 1;

        if (isCorner) return CORNER_VALUE;
        if (isEdge) return EDGE_VALUE;
        return INTERIOR_VALUE;
    }
}

import java.io.PrintWriter;
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        PrintWriter out = new PrintWriter(System.out);

        if (scanner.hasNextInt()) {
            int testCases = scanner.nextInt();
            while (testCases-- > 0) {
                int rows = scanner.nextInt();
                int cols = scanner.nextInt();
                int[][] grid = new int[rows][cols];

                for (int i = 0; i < rows; i++) {
                    for (int j = 0; j < cols; j++) {
                        grid[i][j] = scanner.nextInt();
                    }
                }

                if (validateAndModifyGrid(grid, rows, cols, out)) {
                    out.println("YES");
                    printGrid(grid, rows, cols, out);
                } else {
                    out.println("NO");
                }
            }
        }
        out.flush();
    }

    /**
     * Validates the grid against position-based constraints and updates values in-place.
     * Returns true if all cells meet the requirements, false otherwise.
     */
    private static boolean validateAndModifyGrid(int[][] grid, int rows, int cols, PrintWriter out) {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                int maxValue = determineMaxValue(i, j, rows, cols);
                if (grid[i][j] > maxValue) {
                    return false;
                }
                grid[i][j] = maxValue;
            }
        }
        return true;
    }

    /**
     * Determines the maximum allowed value for a cell based on its position.
     * Priority: Corner > Edge > Inner
     */
    private static int determineMaxValue(int i, int j, int rows, int cols) {
        if (isCorner(i, j, rows, cols)) {
            return 2;
        } else if (isEdge(i, j, rows, cols)) {
            return 3;
        } else {
            return 4;
        }
    }

    private static boolean isCorner(int i, int j, int rows, int cols) {
        return (i == 0 && j == 0) || (i == 0 && j == cols - 1) ||
               (i == rows - 1 && j == 0) || (i == rows - 1 && j == cols - 1);
    }

    private static boolean isEdge(int i, int j, int rows, int cols) {
        return i == 0 || i == rows - 1 || j == 0 || j == cols - 1;
    }

    private static void printGrid(int[][] grid, int rows, int cols, PrintWriter out) {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                out.print(grid[i][j] + " ");
            }
            out.println();
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.stream.Collectors;

/**
 * Solves a grid-based constraint propagation problem.
 * Refactored for improved maintainability, readability, and robustness.
 */
public class GridConstraintSolver {

    // Boundary constraints extracted as constants for clarity
    private static final int CORNER_MAX = 2;
    private static final int EDGE_MAX = 3;
    private static final int INTERIOR_MAX = 4;

    public static void main(String[] args) {
        String inputPath = args.length > 0 ? args[0] : null;
        String outputPath = args.length > 1 ? args[1] : null;

        BufferedReader br = null;
        PrintWriter pw = null;

        try {
            br = createReader(inputPath);
            pw = createWriter(outputPath);

            new GridConstraintSolver().run(br, pw);
            pw.flush();
        } catch (IOException e) {
            System.err.println("I/O Error: " + e.getMessage());
        } finally {
            try {
                if (br != null) br.close();
                if (pw != null) {
                    // Only close file writers; System.out should remain open
                    if (outputPath != null) pw.close();
                    else pw.flush();
                }
            } catch (IOException e) {
                System.err.println("Failed to close resources: " + e.getMessage());
            }
        }
    }

    /**
     * Creates a BufferedReader from a file path or standard input.
     */
    private static BufferedReader createReader(String filePath) throws IOException {
        return filePath != null 
                ? new BufferedReader(new FileReader(filePath)) 
                : new BufferedReader(new InputStreamReader(System.in));
    }

    /**
     * Creates a PrintWriter for a file path or standard output.
     */
    private static PrintWriter createWriter(String filePath) throws IOException {
        return filePath != null 
                ? new PrintWriter(new FileWriter(filePath)) 
                : new PrintWriter(System.out);
    }

    /**
     * Orchestrates the reading of test cases and delegates to the solver.
     */
    private void run(BufferedReader br, PrintWriter pw) throws IOException {
        String line = br.readLine();
        if (line == null || line.trim().isEmpty()) {
            return;
        }

        int t = Integer.parseInt(line.trim());
        for (int caseNum = 0; caseNum < t; caseNum++) {
            int[] dimensions = readInts(br);
            int n = dimensions[0];
            int m = dimensions[1];
            int[][] grid = readGrid(br, n, m);

            solve(n, m, grid, pw);
        }
    }

    /**
     * Reads a single line of space-separated integers.
     */
    private int[] readInts(BufferedReader br) throws IOException {
        String line = br.readLine();
        if (line == null) {
            throw new IOException("Unexpected end of input while reading integers");
        }
        return Arrays.stream(line.trim().split("\\s+"))
                .filter(s -> !s.isEmpty())
                .mapToInt(Integer::parseInt)
                .toArray();
    }

    /**
     * Reads an n x m grid from the input stream.
     */
    private int[][] readGrid(BufferedReader br, int n, int m) throws IOException {
        int[][] grid = new int[n][m];
        for (int i = 0; i < n; i++) {
            grid[i] = readInts(br);
        }
        return grid;
    }

    /**
     * Solves the constraint propagation problem for a single test case.
     */
    private void solve(int n, int m, int[][] grid, PrintWriter out) {
        boolean possible = true;
        boolean changed = true;

        while (changed && possible) {
            changed = false;
            for (int i = 0; i < n && possible; i++) {
                for (int j = 0; j < m && possible; j++) {
                    int val = grid[i][j];
                    if (val == 0) continue;

                    // Validate boundary constraints
                    if (isInvalidBoundary(i, j, n, m, val)) {
                        possible = false;
                        break;
                    }

                    // Count filled neighbors and identify empty directions
                    int filledCount = 0;
                    List<Direction> emptyDirs = new ArrayList<>();

                    for (Direction dir : Direction.values()) {
                        int ni = i + dir.dRow;
                        int nj = j + dir.dCol;
                        if (isValid(ni, nj, n, m)) {
                            if (grid[ni][nj] > 0) {
                                filledCount++;
                            } else {
                                emptyDirs.add(dir);
                            }
                        }
                    }

                    // Propagate constraints
                    if (filledCount < val) {
                        int needed = val - filledCount;
                        if (emptyDirs.size() < needed) {
                            possible = false;
                            break;
                        }
                        for (int k = 0; k < needed; k++) {
                            grid[i + emptyDirs.get(k).dRow][j + emptyDirs.get(k).dCol] = 1;
                            changed = true;
                        }
                    } else if (filledCount > val) {
                        grid[i][j] = filledCount;
                        changed = true;
                    }
                }
            }
        }

        out.println(possible ? "YES" : "NO");
        if (possible) {
            for (int[] row : grid) {
                out.println(Arrays.stream(row)
                        .mapToObj(Integer::toString)
                        .collect(Collectors.joining(" ")));
            }
        }
    }

    /**
     * Checks if a cell's value violates boundary constraints.
     */
    private boolean isInvalidBoundary(int i, int j, int n, int m, int val) {
        boolean isCorner = (i == 0 || i == n - 1) && (j == 0 || j == m - 1);
        boolean isEdge = (i == 0 || i == n - 1 || j == 0 || j == m - 1);

        if (isCorner && val > CORNER_MAX) return true;
        if (isEdge && val > EDGE_MAX) return true;
        if (!isEdge && !isCorner && val > INTERIOR_MAX) return true;
        return false;
    }

    /**
     * Checks if coordinates are within grid bounds.
     */
    private boolean isValid(int r, int c, int n, int m) {
        return r >= 0 && r < n && c >= 0 && c < m;
    }

    /**
     * Represents grid traversal directions with corresponding coordinate deltas.
     */
    private enum Direction {
        UP(-1, 0),
        LEFT(0, -1),
        DOWN(1, 0),
        RIGHT(0, 1);

        final int dRow;
        final int dCol;

        Direction(int dRow, int dCol) {
            this.dRow = dRow;
            this.dCol = dCol;
        }
    }
}

import java.io.BufferedReader;
import java.io.EOFException;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

public class NeighbourGrid {

    private static final int MAX_CORNER_VALUE = 2;
    private static final int MAX_EDGE_VALUE = 3;
    private static final int MAX_INNER_VALUE = 4;

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner();
        PrintWriter out = new PrintWriter(System.out);

        try {
            int testCases = scanner.nextInt();
            while (testCases-- > 0) {
                int rows = scanner.nextInt();
                int cols = scanner.nextInt();

                boolean isValid = true;
                for (int i = 0; i < rows; i++) {
                    for (int j = 0; j < cols; j++) {
                        int value = scanner.nextInt();
                        if (isValid && value > getMaxAllowedValue(i, j, rows, cols)) {
                            isValid = false;
                        }
                    }
                }

                if (isValid) {
                    out.println("YES");
                    printCanonicalGrid(out, rows, cols);
                } else {
                    out.println("NO");
                }
            }
        } finally {
            out.flush();
            out.close();
        }
    }

    private static int getMaxAllowedValue(int row, int col, int rows, int cols) {
        if (isCorner(row, col, rows, cols)) {
            return MAX_CORNER_VALUE;
        }
        if (isEdge(row, col, rows, cols)) {
            return MAX_EDGE_VALUE;
        }
        return MAX_INNER_VALUE;
    }

    private static boolean isCorner(int row, int col, int rows, int cols) {
        return (row == 0 && col == 0) ||
               (row == rows - 1 && col == cols - 1) ||
               (row == 0 && col == cols - 1) ||
               (row == rows - 1 && col == 0);
    }

    private static boolean isEdge(int row, int col, int rows, int cols) {
        return row == 0 || row == rows - 1 || col == 0 || col == cols - 1;
    }

    private static void printCanonicalGrid(PrintWriter out, int rows, int cols) {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                out.print(getMaxAllowedValue(i, j, rows, cols) + " ");
            }
            out.println();
        }
    }

    /**
     * Fast I/O helper class for competitive programming and large input scenarios.
     */
    private static class FastScanner {
