import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayList;
import java.util.List;
import java.util.StringTokenizer;

/**
 * Solves grid-based neighbor counting puzzles.
 * Validates cell values against neighbor constraints, fills adjacent zeros,
 * and normalizes the grid before output.
 */
public class GridSolver {

    private static final int[][] DIRECTIONS = {{0, 1}, {0, -1}, {1, 0}, {-1, 0}};

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner();
        StringBuilder output = new StringBuilder();

        // Read number of test cases
        String tStr = scanner.next();
        if (tStr == null) return;
        int t = Integer.parseInt(tStr);

        while (t-- > 0) {
            int rows = scanner.nextInt();
            int cols = scanner.nextInt();
            int[][] grid = new int[rows][cols];

            // Read grid data
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    grid[i][j] = scanner.nextInt();
                }
            }

            // Process and append result
            if (solve(rows, cols, grid)) {
                output.append("YES\n");
                for (int i = 0; i < rows; i++) {
                    for (int j = 0; j < cols; j++) {
                        output.append(grid[i][j]).append(' ');
                    }
                    output.append('\n');
                }
            } else {
                output.append("NO\n");
            }
        }
        System.out.print(output);
    }

    /**
     * Core logic: validates, transforms, and normalizes the grid.
     * @return true if the grid is valid and processed, false otherwise.
     */
    private static boolean solve(int rows, int cols, int[][] grid) {
        List<Cell> problematicCells = new ArrayList<>();
        boolean invalid = false;

        // Phase 1: Validation & Collection
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == 0) continue;

                int validNeighbors = countValidNeighbors(i, j, rows, cols);
                if (grid[i][j] > validNeighbors) {
                    invalid = true;
                    break;
                }

                int positiveNeighbors = countPositiveNeighbors(i, j, grid);
                if (grid[i][j] != positiveNeighbors) {
                    problematicCells.add(new Cell(i, j, positiveNeighbors));
                }
            }
            if (invalid) break;
        }

        if (invalid) return false;

        // Phase 2: Transformation
        for (Cell cell : problematicCells) {
            if (grid[cell.r][cell.c] < cell.fillValue) {
                grid[cell.r][cell.c] = cell.fillValue;
                continue;
            }

            int remaining = grid[cell.r][cell.c] - countPositiveNeighbors(cell.r, cell.c, grid);
            if (remaining == 0) continue;

            for (int[] dir : DIRECTIONS) {
                int nr = cell.r + dir[0];
                int nc = cell.c + dir[1];
                if (isValid(nr, nc, rows, cols) && grid[nr][nc] == 0) {
                    int neighborCount = countPositiveNeighbors(nr, nc, grid);
                    grid[nr][nc] = neighborCount;
                    remaining--;
                    if (remaining == 0) break;
                }
            }
        }

        // Phase 3: Final Normalization
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] != 0) {
                    grid[i][j] = countPositiveNeighbors(i, j, grid);
                }
            }
        }

        return true;
    }

    /** Checks if coordinates are within grid bounds. */
    private static boolean isValid(int r, int c, int rows, int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /** Counts how many adjacent cells are within grid bounds. */
    private static int countValidNeighbors(int r, int c, int rows, int cols) {
        int count = 0;
        for (int[] dir : DIRECTIONS) {
            if (isValid(r + dir[0], c + dir[1], rows, cols)) {
                count++;
            }
        }
        return count;
    }

    /** Counts how many adjacent cells have a value > 0. */
    private static int countPositiveNeighbors(int r, int c, int[][] grid) {
        int count = 0;
        for (int[] dir : DIRECTIONS) {
            int nr = r + dir[0];
            int nc = c + dir[1];
            if (isValid(nr, nc, grid.length, grid[0].length) && grid[nr][nc] > 0) {
                count++;
            }
        }
        return count;
    }

    /** Immutable data class to track problematic cells and their target fill values. */
    private static class Cell {
        final int r, c, fillValue;

        Cell(int r, int c, int fillValue) {
            this.r = r;
            this.c = c;
            this.fillValue = fillValue;
        }
    }

    /**
     * Standard fast I/O using BufferedReader and StringTokenizer.
     * Replaces the original custom Reader to fix a critical 4GB buffer bug
     * and improve maintainability.
     */
    private static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            String token = next();
            return token == null ? 0 : Integer.parseInt(token);
        }
    }
}

import java.io.BufferedReader;
