/**
 * Refactored solution for grid boundary validation and output generation.
 * Improvements:
 * - Removed unused imports, methods, and variables (isPalindrome, gcd, fact, run, etc.)
 * - Extracted magic numbers into named constants
 * - Separated concerns: input reading, validation, and output generation
 * - Eliminated unnecessary grid storage by validating on-the-fly
 * - Simplified boundary condition logic
 * - Standardized Fast I/O implementation
 * - Improved naming consistency and code readability
 */
public class Solve {
    private static final PrintWriter OUT = new PrintWriter(System.out);
    private static final int CORNER_LIMIT = 2;
    private static final int EDGE_LIMIT = 3;
    private static final int INTERIOR_LIMIT = 4;

    public static void main(String[] args) {
        FastReader sc = new FastReader();
        String tStr = sc.next();
        if (tStr == null) return;
        int t = Integer.parseInt(tStr);

        while (t-- > 0) {
            int n = sc.nextInt();
            int m = sc.nextInt();
            boolean isValid = true;

            // Validate input values on-the-fly without storing the grid
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    int value = sc.nextInt();
                    if (!isWithinLimits(i, j, n, m, value)) {
                        isValid = false;
                    }
                }
            }

            if (isValid) {
                OUT.println("YES");
                printSolutionGrid(n, m);
            } else {
                OUT.println("NO");
            }
        }
        OUT.flush();
    }

    /**
     * Checks if a value at position (i, j) satisfies the boundary constraints.
     */
    private static boolean isWithinLimits(int i, int j, int n, int m, int value) {
        boolean isCorner = (i == 0 || i == n - 1) && (j == 0 || j == m - 1);

        if (isCorner) {
            return value <= CORNER_LIMIT;
        } else if (i == 0 || i == n - 1 || j == 0 || j == m - 1) {
            return value <= EDGE_LIMIT;
        } else {
            return value <= INTERIOR_LIMIT;
        }
    }

    /**
     * Prints the required output grid based on position rules.
     */
    private static void printSolutionGrid(int n, int m) {
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                OUT.print(getValueForPosition(i, j, n, m));
                if (j < m - 1) {
                    OUT.print(' ');
                }
            }
            OUT.println();
        }
    }

    /**
     * Determines the correct output value for a given grid position.
     */
    private static int getValueForPosition(int i, int j, int n, int m) {
        boolean isCorner = (i == 0 || i == n - 1) && (j == 0 || j == m - 1);

        if (isCorner) return CORNER_LIMIT;
        if (i == 0 || i == n - 1 || j == 0 || j == m - 1) return EDGE_LIMIT;
        return INTERIOR_LIMIT;
    }

    /**
     * Optimized Fast I/O reader for competitive programming scenarios.
     */
    static class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    e.printStackTrace();
                    return null;
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            String s = next();
            return s == null ? 0 : Integer.parseInt(s);
        }
    }
}

import java.io.BufferedWriter;
import java.io.IOException;
import java.io.InputStream;
import java.io.OutputStream;
import java.io.OutputStreamWriter;
import java.io.PrintWriter;
import java.util.InputMismatchException;

/**
 * Entry point for the competitive programming solution.
 * Handles initialization of fast I/O and delegates problem-solving logic.
 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        OutputWriter out = new OutputWriter(outputStream);

        NeighborGridSolver solver = new NeighborGridSolver();
        solver.solve(in, out);

        out.close();
    }

    /**
     * Solves the Neighbor Grid problem.
     * Validates and normalizes grid values based on cell position (corner, edge, inner).
     */
    static class NeighborGridSolver {
        private static final int MAX_CORNER_VALUE = 2;
        private static final int MAX_EDGE_VALUE = 3;
        private static final int MAX_INNER_VALUE = 4;

        /**
         * Processes all test cases.
         *
         * @param in  Fast input reader
         * @param out Fast output writer
         */
        public void solve(InputReader in, OutputWriter out) {
            int numTestCases = in.nextInt();
            while (numTestCases-- > 0) {
                int n = in.nextInt();
                int m = in.nextInt();
                int[][] grid = new int[n][m];

                // Read grid input
                for (int i = 0; i < n; i++) {
                    for (int j = 0; j < m; j++) {
                        grid[i][j] = in.nextInt();
                    }
                }

                // Validate and normalize grid values
                boolean isPossible = true;
                for (int i = 0; i < n; i++) {
                    for (int j = 0; j < m; j++) {
                        int maxAllowed = getMaxAllowedForCell(i, j, n, m);
                        if (grid[i][j] > maxAllowed) {
                            isPossible = false;
                        } else {
                            grid[i][j] = maxAllowed;
                        }
                    }
                }

                // Output result
                if (!isPossible) {
                    out.println("NO");
                } else {
                    out.println("YES");
                    for (int i = 0; i < n; i++) {
                        for (int j = 0; j < m; j++) {
                            out.print(grid[i][j]);
                            if (j < m - 1) {
                                out.print(' ');
                            }
                        }
                        out.println();
                    }
                }
            }
        }

        /**
         * Determines the maximum allowed value for a cell based on its position.
         * Corners: 2, Edges: 3, Inner cells: 4
         *
         * @param i Row index
         * @param j Column index
         * @param n Number of rows
         * @param m Number of columns
         * @return Maximum allowed value for the cell
         */
        private int getMaxAllowedForCell(int i, int j, int n, int m) {
            boolean isTopOrBottom = (i == 0 || i == n - 1);
            boolean isLeftOrRight = (j == 0 || j == m - 1);

            if (isTopOrBottom && isLeftOrRight) {
                return MAX_CORNER_VALUE;
            }
            if (isTopOrBottom || isLeftOrRight) {
                return MAX_EDGE_VALUE;
            }
            return MAX_INNER_VALUE;
        }
    }

    /**
     * Fast input reader for competitive programming.
     * Parses integers efficiently from an InputStream.
     */
    static class InputReader {
        private final InputStream stream;
        private final byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        public int read() {
            if (numChars == -1) {
                throw new InputMismatchException();
            }
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0) {
                    return -1;
                }
            }
            return buf[curChar++];
        }

        public int nextInt() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                res *= 10;
                res += c - '0';
                c = read();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public boolean isSpaceChar(int c) {
            return isWhitespace(c);
        }

        public static boolean isWhitespace(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }
    }

    /**
     * Fast output writer for competitive programming.
     * Wraps BufferedWriter and PrintWriter for efficient console output.
     */
    static class OutputWriter {
        private final PrintWriter writer;

        public OutputWriter(OutputStream outputStream) {
            writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(outputStream)));
        }

        public OutputWriter(java.io.Writer writer) {
            this.writer = new PrintWriter(writer);
        }

        public void println() {
            writer.println();
        }

        public void print(Object... objects) {
            for (int i = 0; i < objects.length; i++) {
                if (i != 0) {
                    writer.print(' ');
                }
                writer.print(objects[i]);
            }
        }

        public void println(Object... objects) {
            print(objects);
            writer.println();
        }

        public void close() {
            writer.close();
        }
    }
}

import java.util.Scanner;

/**
 * A program to validate and transform a matrix based on specific boundary rules.
 * 
 * Refactoring improvements:
 * 1. Class renamed from 'BGR9' to 'MatrixProcessor' for better context.
 * 2. Variable names updated to be descriptive (e.g., 'arr' -> 'matrix', 'n' -> 'rows').
 * 3. Removed unused variable 'arr2'.
 * 4. Extracted magic numbers (2, 3, 4) into named constants for clarity.
 * 5. Separated concerns: Input reading, Validation/Transformation, and Output printing.
 * 6. Replaced nested loops with 'break' flags with cleaner return statements.
 * 7. Used try-with-resources for Scanner to prevent resource leaks.
 */
public class MatrixProcessor {

    // Constants defining the maximum allowed values for different matrix regions
    private static final int CORNER_LIMIT = 2;
    private static final int EDGE_LIMIT = 3;
    private static final int INNER_LIMIT = 4;

    public static void main(String[] args) {
        // Use try-with-resources to ensure the Scanner is closed automatically
        try (Scanner scanner = new Scanner(System.in)) {

            // Check if input exists to prevent NoSuchElementException
            if (scanner.hasNextInt()) {
                int numTestCases = scanner.nextInt();

                for (int t = 0; t < numTestCases; t++) {
                    int rows = scanner.nextInt();
                    int cols = scanner.nextInt();

                    long[][] matrix = new long[rows][cols];

                    // Read the matrix data
                    for (int i = 0; i < rows; i++) {
                        for (int j = 0; j < cols; j++) {
                            if (scanner.hasNextLong()) {
                                matrix[i][j] = scanner.nextLong();
                            }
                        }
                    }

                    // Process the matrix: Validate constraints and apply limits
                    boolean isValid = processMatrix(matrix, rows, cols);

                    if (isValid) {
                        System.out.println("YES");
                        printMatrix(matrix);
                    } else {
                        System.out.println("NO");
                    }
                }
            }
        }
    }

    /**
     * Validates the matrix against boundary rules and updates values to the limits.
     * 
     * @param matrix The 2D array to process
     * @param rows Number of rows
     * @param cols Number of columns
     * @return true if the matrix is valid, false otherwise
     */
    private static boolean processMatrix(long[][] matrix, int rows, int cols) {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                int limit = getLimitForPosition(i, j, rows, cols);

                // If the current value exceeds the limit for its position, the matrix is invalid
                if (matrix[i][j] > limit) {
                    return false;
                }

                // Update the value to the maximum allowed limit
                matrix[i][j] = limit;
            }
        }
        return true;
    }

    /**
     * Determines the maximum allowed value based on the cell's position.
     * 
     * @param row Current row index
     * @param col Current column index
     * @param rows Total number of rows
     * @param cols Total number of columns
     * @return The limit integer (2 for corners, 3 for edges, 4 for interior)
     */
    private static int getLimitForPosition(int row, int col, int rows, int cols) {
        // Check if the cell is a corner
        boolean isCorner = (row == 0 && col == 0) || 
                           (row == rows - 1 && col == cols - 1) || 
                           (row == rows - 1 && col == 0) || 
                           (row == 0 && col == cols - 1);

        if (isCorner) {
            return CORNER_LIMIT;
        }

        // Check if the cell is on an edge (but not a corner)
        boolean isEdge = (row == 0 || row == rows - 1 || col == 0 || col == cols - 1);
        if (isEdge) {
            return EDGE_LIMIT;
        }

        // Otherwise, it is an interior cell
        return INNER_LIMIT;
    }

    /**
     * Prints the matrix to the console.
     * 
     * @param matrix The 2D array to print
     */
    private static void printMatrix(long[][] matrix) {
        StringBuilder sb = new StringBuilder();
        for (long[] row : matrix) {
            for (long val : row) {
                sb.append(val).append(" ");
            }
            sb.append("\n");
        }
        System.out.print(sb.toString());
    }
}

import java.io.BufferedReader;
