import java.util.StringTokenizer;

/**
 * A refactored solution for validating and normalizing a matrix based on position constraints.
 * 
 * Refactoring improvements:
 * 1. Naming: Replaced generic variable names (a, t, n, m) with descriptive names (matrix, testCases, rows, cols).
 * 2. Constants: Extracted magic numbers (2, 3, 4) into named constants for clarity.
 * 3. Modularity: Separated I/O logic, parsing, and business logic into distinct methods.
 * 4. Robustness: Used StringTokenizer for safer whitespace handling during input parsing.
 * 5. Readability: Improved indentation, spacing, and added JavaDoc comments.
 */
public class MatrixValidator {

    // Constants representing the maximum allowed values for cell positions
    private static final int MAX_CORNER_VALUE = 2;
    private static final int MAX_EDGE_VALUE = 3;
    private static final int MAX_INNER_VALUE = 4;

    public static void main(String[] args) throws IOException {
        // Initialize efficient I/O streams
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        BufferedWriter bw = new BufferedWriter(new OutputStreamWriter(System.out));

        try {
            String line = br.readLine();
            // Check for null or empty input to prevent crashes
            if (line != null && !line.trim().isEmpty()) {
                int testCases = Integer.parseInt(line.trim());

                while (testCases-- > 0) {
                    processTestCase(br, bw);
                }
            }
        } finally {
            // Ensure output is flushed and resources are managed
            bw.flush();
            bw.close();
        }
    }

    /**
     * Processes a single test case: reads dimensions and matrix, validates, and writes output.
     */
    private static void processTestCase(BufferedReader br, BufferedWriter bw) throws IOException {
        // Read dimensions (rows and columns)
        String dimensionLine = br.readLine();
        if (dimensionLine == null) return;

        StringTokenizer st = new StringTokenizer(dimensionLine);
        int rows = Integer.parseInt(st.nextToken());
        int cols = Integer.parseInt(st.nextToken());

        int[][] matrix = new int[rows][cols];

        // Read matrix data
        for (int i = 0; i < rows; i++) {
            String rowData = br.readLine();
            if (rowData != null) {
                st = new StringTokenizer(rowData);
                for (int j = 0; j < cols; j++) {
                    if (st.hasMoreTokens()) {
                        matrix[i][j] = Integer.parseInt(st.nextToken());
                    }
                }
            }
        }

        // Validate and normalize the matrix
        boolean isValid = true;
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                int limit = getCellLimit(i, j, rows, cols);

                // Check if value exceeds the limit for this position
                if (matrix[i][j] > limit) {
                    isValid = false;
                }

                // Cap the value to the limit (consistent with original behavior)
                matrix[i][j] = Math.min(matrix[i][j], limit);
            }
        }

        // Output results
        if (isValid) {
            bw.write("YES\n");
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    bw.write(matrix[i][j] + " ");
                }
                bw.newLine();
            }
        } else {
            bw.write("NO\n");
        }
    }

    /**
     * Determines the maximum allowed value for a cell based on its coordinates.
     * 
     * @param row Current row index
     * @param col Current column index
     * @param rows Total number of rows
     * @param cols Total number of columns
     * @return The maximum allowed integer value for the cell
     */
    private static int getCellLimit(int row, int col, int rows, int cols) {
        // Check for corners: (0,0), (0, cols-1), (rows-1, 0), (rows-1, cols-1)
        boolean isTopLeft = (row == 0 && col == 0);
        boolean isTopRight = (row == 0 && col == cols - 1);
        boolean isBottomLeft = (row == rows - 1 && col == 0);
        boolean isBottomRight = (row == rows - 1 && col == cols - 1);

        if (isTopLeft || isTopRight || isBottomLeft || isBottomRight) {
            return MAX_CORNER_VALUE;
        }

        // Check for edges: first/last row or first/last column
        if (row == 0 || row == rows - 1 || col == 0 || col == cols - 1) {
            return MAX_EDGE_VALUE;
        }

        // Inner cells
        return MAX_INNER_VALUE;
    }
}

