/**
 * A program to process a grid based on specific boundary constraints.
 * Corners must be <= 2, edges <= 3, and interior <= 4.
 */
public class GridProcessor {

    // Constants defining the maximum allowed values for different grid positions
    private static final int CORNER_LIMIT = 2;
    private static final int EDGE_LIMIT = 3;
    private static final int INNER_LIMIT = 4;

    // I/O Resources
    private static final PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out));
    private static final FastScanner sc = new FastScanner();

