    /**
     * Solves a single test case.
     */
    private static void solve() {
        int rows = sc.nextInt();
        int cols = sc.nextInt();
        int[][] grid = new int[rows][cols];
        boolean possible = true;

        // Read grid and validate constraints in a single pass
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                int value = sc.nextInt();
                int limit = getLimitForPosition(i, j, rows, cols);

                if (value > limit) {
                    possible = false;
                }

                // Store the transformed value (clamped to the limit)
                // This matches the original logic where valid cells are set to the limit
                grid[i][j] = limit;
            }
        }

        if (!possible) {
            out.println("NO");
        } else {
            out.println("YES");
            printGrid(grid);
        }
    }

    /**
     * Determines the maximum allowed value for a cell based on its coordinates.
     */
    private static int getLimitForPosition(int row, int col, int totalRows, int totalCols) {
        // Check if the cell is a corner
        boolean isCorner = (row == 0 || row == totalRows - 1) && 
                           (col == 0 || col == totalCols - 1);

        // Check if the cell is on an edge (but not a corner)
        boolean isEdge = row == 0 || row == totalRows - 1 || 
                         col == 0 || col == totalCols - 1;

        if (isCorner) return CORNER_LIMIT;
        if (isEdge) return EDGE_LIMIT;
        return INNER_LIMIT;
    }

    /**
     * Prints the grid to the output stream.
     */
    private static void printGrid(int[][] grid) {
        StringBuilder sb = new StringBuilder();
        for (int[] row : grid) {
            for (int val : row) {
                sb.append(val).append(" ");
            }
            sb.append("\n");
        }
        out.print(sb);
    }

    /**
     * FastScanner for efficient input reading.
     */
    static class FastScanner {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer("");

        String next() {
            while (!st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    e.printStackTrace();
                    return null;
                }
            }
            return st.nextToken();
        }

        boolean hasNext() {
            while (!st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return false;
                    if (line.trim().isEmpty()) continue; // Skip empty lines
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    e.printStackTrace();
                    return false;
                }
            }
            return true;
        }

        int nextInt() {
            String s = next();
            if (s == null) throw new NoSuchElementException();
            return Integer.parseInt(s);
        }

        long nextLong() {
            String s = next();
            if (s == null) throw new NoSuchElementException();
            return Long.parseLong(s);
        }

        int[] readArray(int n) {
            int[] a = new int[n];
            for (int i = 0; i < n; i++) a[i] = nextInt();
            return a;
        }
    }
}

