/**
 * Solves the grid constraint problem.
 * Validates if a grid can be modified such that:
 * - Corners have values <= 2
 * - Edges (non-corners) have values <= 3
 * - Inner cells have values <= 4
 */
public class GridConstraintSolver {

    // Constants defining the maximum allowed values for specific grid positions
    private static final int CORNER_LIMIT = 2;
    private static final int EDGE_LIMIT = 3;
    private static final int INNER_LIMIT = 4;

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        // Read the number of test cases
        if (scanner.hasNextInt()) {
            int numTestCases = scanner.nextInt();

            while (numTestCases-- > 0) {
                solveTestCase(scanner);
            }
        }

        scanner.close();
    }

    /**
     * Processes a single test case.
     * 
     * @param scanner The Scanner object to read input from
     */
    private static void solveTestCase(Scanner scanner) {
        int rows = scanner.nextInt();
        int cols = scanner.nextInt();

        int[][] grid = new int[rows][cols];

        // Read the grid data
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                grid[i][j] = scanner.nextInt();
            }
        }

        boolean isValid = true;

        // Validate and modify the grid in-place
        outerLoop:
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                int limit = getMaxAllowedValue(i, j, rows, cols);

                if (grid[i][j] > limit) {
                    isValid = false;
                    break outerLoop;
                }

                // Cap the value at the limit
                grid[i][j] = limit;
            }
        }

        // Output results
        if (isValid) {
            System.out.println("YES");
            StringBuilder rowBuilder = new StringBuilder();
            for (int i = 0; i < rows; i++) {
                rowBuilder.setLength(0); // Clear buffer for new row
                for (int j = 0; j < cols; j++) {
                    rowBuilder.append(grid[i][j]).append(" ");
                }
                System.out.println(rowBuilder);
            }
        } else {
            System.out.println("NO");
        }
    }

    /**
     * Determines the maximum allowed value for a cell based on its position.
     * 
     * @param row Current row index
     * @param col Current column index
     * @param totalRows Total number of rows
     * @param totalCols Total number of columns
     * @return The maximum allowed integer value for this position
     */
    private static int getMaxAllowedValue(int row, int col, int totalRows, int totalCols) {
        // Check if the cell is a corner
        boolean isCorner = (row == 0 || row == totalRows - 1) && (col == 0 || col == totalCols - 1);

        // Check if the cell is on an edge (but not a corner, as corners take precedence)
        boolean isEdge = (row == 0 || row == totalRows - 1 || col == 0 || col == totalCols - 1);

        if (isCorner) {
            return CORNER_LIMIT;
        } else if (isEdge) {
            return EDGE_LIMIT;
        } else {
            return INNER_LIMIT;
        }
    }
}

