/**
 * Validates and transforms a matrix based on positional constraints.
 * Corners must be <= 2, edges <= 3, and interior cells <= 4.
 */
public class MatrixValidator {

    private static final int CORNER_LIMIT = 2;
    private static final int EDGE_LIMIT = 3;
    private static final int INTERIOR_LIMIT = 4;

    public static void main(String[] args) throws IOException {
        // Use try-with-resources to ensure proper cleanup of I/O streams
        try (InputReader in = new InputReader(System.in);
             PrintWriter out = new PrintWriter(System.out)) {

            int testCases = in.nextInt();
            for (int t = 0; t < testCases; t++) {
                processTestCase(in, out);
            }
        }
    }

    /**
     * Processes a single test case: reads dimensions and matrix values,
     * validates constraints, and outputs the result.
     */
    private static void processTestCase(InputReader in, PrintWriter out) throws IOException {
        int rows = in.nextInt();
        int cols = in.nextInt();
        int[][] matrix = new int[rows][cols];
        boolean isValid = true;

        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                int inputValue = in.nextInt();
                int limit = getMaxAllowedValue(i, j, rows, cols);

                if (inputValue > limit) {
                    isValid = false;
                }
                // Store the validated/transformed value
                matrix[i][j] = limit;
            }
        }

        if (isValid) {
            out.println("YES");
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    out.print(matrix[i][j]);
                    // Avoid trailing spaces for cleaner output
                    out.print(j < cols - 1 ? " " : "");
                }
                out.println();
            }
        } else {
            out.println("NO");
        }
    }

    /**
     * Determines the maximum allowed value based on the cell's position.
     * Corners: 2, Edges: 3, Interior: 4
     */
    private static int getMaxAllowedValue(int row, int col, int rows, int cols) {
        boolean isOnBoundary = row == 0 || row == rows - 1 || col == 0 || col == cols - 1;
        if (!isOnBoundary) {
            return INTERIOR_LIMIT;
        }
        boolean isCorner = (row == 0 || row == rows - 1) && (col == 0 || col == cols - 1);
        return isCorner ? CORNER_LIMIT : EDGE_LIMIT;
    }

    /**
     * Lightweight, fast input reader using BufferedReader and StringTokenizer.
     * Replaces the original custom Scanner to improve reliability and maintainability.
     */
    private static class InputReader {
        private final BufferedReader br;
        private StringTokenizer st;

        public InputReader(InputStream stream) {
            br = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) {
                    return null;
                }
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

        public int nextInt() throws IOException {
            String token = next();
            if (token == null) {
                throw new IOException("Unexpected end of input");
            }
            return Integer.parseInt(token);
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

/**
 * Processes a 2D grid of integers, validating and normalizing values based on 
 * their position (corner, edge, or interior).
 */
public class GridProcessor {

    /**
     * Fast I/O helper for performance-critical input reading.
     */
    static class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input", e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            String s = next();
            return s == null ? 0 : Integer.parseInt(s);
        }

        long nextLong() {
            String s = next();
            return s == null ? 0L : Long.parseLong(s);
        }

        double nextDouble() {
            String s = next();
            return s == null ? 0.0 : Double.parseDouble(s);
        }

        String nextLine() {
            String str = "";
            try {
                str = br.readLine();
            } catch (IOException e) {
                throw new RuntimeException("Failed to read line", e);
            }
            return str;
        }
    }

    public static void main(String[] args) {
        FastReader reader = new FastReader();
        PrintWriter out = new PrintWriter(System.out);

        try {
            String tStr = reader.next();
            if (tStr != null) {
                int t = Integer.parseInt(tStr);
                while (t-- > 0) {
                    solve(reader, out);
                }
            }
        } finally {
            out.flush();
        }
    }

    /**
     * Solves a single test case: reads dimensions and matrix, validates values,
     * normalizes them, and prints the result.
     */
    private static void solve(FastReader reader, PrintWriter out) {
        int rows = reader.nextInt();
        int cols = reader.nextInt();
        int[][] matrix = new int[rows][cols];
        boolean isValid = true;

        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                int value = reader.nextInt();
                int threshold = getThreshold(i, j, rows, cols);

                if (value > threshold) {
                    isValid = false;
                }
                matrix[i][j] = Math.min(value, threshold);
            }
        }

        if (!isValid) {
            out.println("NO");
        } else {
            out.println("YES");
            printMatrix(out, matrix);
        }
    }

    /**
     * Prints the normalized matrix to the output writer.
     */
    private static void printMatrix(PrintWriter out, int[][] matrix) {
        for (int[] row : matrix) {
            for (int i = 0; i < row.length; i++) {
                out.print(row[i]);
                out.print(i == row.length - 1 ? "" : " ");
            }
            out.println();
        }
    }

    /**
     * Returns the maximum allowed value for a cell based on its position.
     * Corners: 2 | Edges: 3 | Interior: 4
     */
    private static int getThreshold(int row, int col, int rows, int cols) {
        boolean isCorner = (row == 0 || row == rows - 1) && (col == 0 || col == cols - 1);
        if (isCorner) return 2;

        boolean isEdge = row == 0 || row == rows - 1 || col == 0 || col == cols - 1;
        if (isEdge) return 3;

        return 4;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
