import java.util.StringTokenizer;

public class Main {

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner();
        PrintWriter out = new PrintWriter(System.out);
        try {
            int testCases = scanner.nextInt();
            while (testCases-- > 0) {
                processTestCase(scanner, out);
            }
        } finally {
            out.flush();
            out.close();
        }
    }

    /**
     * Processes a single test case: reads the grid, validates it against boundary rules,
     * and prints the result.
     */
    private static void processTestCase(FastScanner scanner, PrintWriter out) {
        int rows = scanner.nextInt();
        int cols = scanner.nextInt();

        int[][] grid = new int[rows][cols];
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                grid[r][c] = scanner.nextInt();
            }
        }

        int[][] expectedNeighbors = new int[rows][cols];
        boolean isValid = true;

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                expectedNeighbors[r][c] = calculateNeighborCount(r, c, rows, cols);
                if (expectedNeighbors[r][c] < grid[r][c]) {
                    isValid = false;
                }
            }
        }

        if (isValid) {
            out.println("YES");
            printGrid(out, expectedNeighbors);
        } else {
            out.println("NO");
        }
    }

    /**
     * Calculates the number of boundary-adjacent neighbors for a cell.
     * A cell in a grid has up to 4 neighbors. Each boundary condition reduces the count by 1.
     */
    private static int calculateNeighborCount(int row, int col, int totalRows, int totalCols) {
        int count = 4;
        if (row == 0) count--;
        if (row == totalRows - 1) count--;
        if (col == 0) count--;
        if (col == totalCols - 1) count--;
        return count;
    }

    /**
     * Formats and prints a 2D integer grid to the provided PrintWriter.
     */
    private static void printGrid(PrintWriter out, int[][] grid) {
        for (int r = 0; r < grid.length; r++) {
            for (int c = 0; c < grid[r].length; c++) {
                if (c > 0) out.print(" ");
                out.print(grid[r][c]);
            }
            out.println();
        }
    }

    /**
     * A robust, standard Java FastScanner using BufferedReader and StringTokenizer.
     * Replaces the original byte-based scanner for better readability, safety, and maintainability.
     */
    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        public boolean hasNext() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) {
                        return false;
                    }
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input", e);
                }
            }
            return true;
        }

        public String next() {
            if (!hasNext()) {
                throw new RuntimeException("Unexpected end of input");
            }
            return st.nextToken();
        }

        public int nextInt() {
            String token = next();
            return Integer.parseInt(token);
        }
    }
}

import java.io.*;
import java.util.StringTokenizer;

/**
 * Solves the grid validation problem.
 * Reads a grid, checks if cell values respect position-based constraints,
 * and outputs a standardized grid if valid.
 * 
 * Constraints:
 * - Corners: <= 2
 * - Edges (excluding corners): <= 3
 * - Interior cells: <= 4
 */
public class GridProblemSolver {

    public static void main(String[] args) {
        FastScanner sc = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out));

        try {
            String tStr = sc.next();
            if (tStr == null) return;
            int T = Integer.parseInt(tStr);

            for (int t = 0; t < T; t++) {
                int n = sc.nextInt();
                int m = sc.nextInt();
                int[][] grid = new int[n][m];

                // Read the input grid
                for (int i = 0; i < n; i++) {
                    for (int j = 0; j < m; j++) {
                        grid[i][j] = sc.nextInt();
                    }
                }

                // Validate and produce output
                if (isValidGrid(grid, n, m)) {
                    out.println("YES");
                    printStandardGrid(n, m, out);
                } else {
                    out.println("NO");
                }
            }
        } catch (Exception e) {
            // Gracefully handle unexpected input errors
            e.printStackTrace();
        } finally {
            out.flush();
            out.close();
        }
    }

    /**
     * Checks if the grid satisfies the position-based value constraints.
     */
    private static boolean isValidGrid(int[][] grid, int n, int m) {
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] > getMaxAllowed(i, j, n, m)) {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Returns the maximum allowed value for a cell at (row, col) in an n x m grid.
     */
    private static int getMaxAllowed(int row, int col, int n, int m) {
        boolean isCorner = (row == 0 || row == n - 1) && (col == 0 || col == m - 1);
        boolean isEdge = row == 0 || row == n - 1 || col == 0 || col == m - 1;

        if (isCorner) return 2;
        if (isEdge) return 3;
        return 4;
    }

    /**
     * Prints the standardized grid to the output stream.
     * Corners are 2, edges are 3, and interior cells are 4.
     */
    private static void printStandardGrid(int n, int m, PrintWriter out) {
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                out.print(getMaxAllowed(i, j, n, m));
                out.print(j == m - 1 ? "" : " ");
            }
            out.println();
        }
    }

    /**
     * Fast input reader for competitive programming and high-throughput scenarios.
     */
    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        public String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input", e);
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            String token = next();
            if (token == null) throw new RuntimeException("Unexpected end of input");
            return Integer.parseInt(token);
        }
    }
}

import java.util.Scanner;

public class Main {
    private static final int MAX_VALUE = 4;

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            if (scanner.hasNextInt()) {
                int testCases = scanner.nextInt();
                for (int t = 0; t < testCases; t++) {
                    solve(scanner);
                }
            }
        }
    }

    private static void solve(Scanner scanner) {
        int rows = scanner.nextInt();
        int cols = scanner.nextInt();
        int[][] grid = new int[rows][cols];

        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                grid[i][j] = scanner.nextInt();
            }
        }

        if (processGrid(grid, rows, cols)) {
            printResult(grid);
        } else {
            System.out.println("NO");
        }
    }

    private static boolean processGrid(int[][] grid, int rows, int cols) {
        boolean changed = true;
        while (changed) {
            changed = false;
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    AdjustmentResult result = adjustCell(grid, i, j, rows, cols);
                    if (result == AdjustmentResult.INVALID) {
                        return false;
                    }
                    if (result == AdjustmentResult.VALID_CHANGED) {
                        changed = true;
                    }
                }
            }
        }
        return true;
    }

    private static AdjustmentResult adjustCell(int[][] grid, int i, int j, int rows, int cols) {
        int current = grid[i][j];
        int edgeBonus = ((i == 0 || i == rows - 1) ? 1 : 0) + ((j == 0 || j == cols - 1) ? 1 : 0);

        if (current + edgeBonus > MAX_VALUE) {
            return AdjustmentResult.INVALID;
        }

        int nonZeroNeighbors = countNonZeroNeighbors(grid, i, j, rows, cols);
        int excess = current - nonZeroNeighbors;

        if (excess < 0) {
            if (excess != -1 || current != 0) {
                grid[i][j] -= excess;
                return AdjustmentResult.VALID_CHANGED;
            }
        } else if (excess > 0) {
            int[] di = {-1, 1, 0, 0};
            int[] dj = {0, 0, -1, 1};
            for (int k = 0; k < 4; k++) {
                if (excess <= 0) break;
                int ni = i + di[k];
                int nj = j + dj[k];
                if (ni >= 0 && ni < rows && nj >= 0 && nj < cols && grid[ni][nj] == 0) {
                    grid[ni][nj]++;
                    excess--;
                    return AdjustmentResult.VALID_CHANGED;
                }
            }
        }
        return AdjustmentResult.VALID_NO_CHANGE;
    }

    private static int countNonZeroNeighbors(int[][] grid, int i, int j, int rows, int cols) {
        int count = 0;
        if (i > 0 && grid[i - 1][j] > 0) count++;
        if (i < rows - 1 && grid[i + 1][j] > 0) count++;
        if (j > 0 && grid[i][j - 1] > 0) count++;
        if (j < cols - 1 && grid[i][j + 1] > 0) count++;
        return count;
    }

    private static void printResult(int[][] grid) {
        StringBuilder sb = new StringBuilder();
        sb.append("YES\n");
        for (int i = 0; i < grid.length; i++) {
            for (int j = 0; j < grid[i].length; j++) {
                sb.append(grid[i][j]);
                if (j < grid[i].length - 1) sb.append(' ');
            }
            sb.append('\n');
        }
        System.out.print(sb);
    }

    private enum AdjustmentResult {
        VALID_NO_CHANGE,
        VALID_CHANGED,
        INVALID
    }
}

