 * Improvements made:
 * 1. Class renamed to 'GridSolution' for better semantic meaning.
 * 2. Magic numbers (2, 3, 4) extracted into named constants.
 * 3. Grid dimensions standardized to [rows][cols] (y, x) instead of [w][h] (x, y)
 *    to align with standard 2D array conventions.
 * 4. Logic extracted into a 'solve' method to reduce nesting and improve readability.
 * 5. Control flow improved by removing 'continue outer' in favor of boolean flags/returns.
 * 6. Input reading robustness improved (null checks).
 * 7. FastReader encapsulated as a static inner utility class.
 */
public class GridSolution {

    // Constants defining the constraints for grid values
    private static final int MAX_INNER_VALUE = 4;
    private static final int MAX_EDGE_VALUE = 3;
    private static final int MAX_CORNER_VALUE = 2;

    public static void main(String[] args) {
        FastReader sc = new FastReader();
        PrintWriter out = new PrintWriter(System.out);

        try {
            String tStr = sc.next();
            if (tStr != null) {
