                while (t-- > 0) {
                    solve(sc, out);
                }
            }
        } catch (Exception e) {
            e.printStackTrace();
        } finally {
            out.flush();
            out.close();
        }
    }

    private static void solve(FastReader sc, PrintWriter out) {
        int rows = sc.nextInt();
        int cols = sc.nextInt();

        // Standard 2D array convention: grid[row][col]
        int[][] grid = new int[rows][cols];

        // Read the entire grid first. This ensures the input stream is consumed
        // correctly even if validation fails early.
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                grid[r][c] = sc.nextInt();
            }
        }

        boolean isValid = true;

        // 1. Check Corners
        // Corners must not exceed MAX_CORNER_VALUE
        if (grid[0][0] > MAX_CORNER_VALUE ||
            grid[0][cols - 1] > MAX_CORNER_VALUE ||
            grid[rows - 1][0] > MAX_CORNER_VALUE ||
            grid[rows - 1][cols - 1] > MAX_CORNER_VALUE) {
            isValid = false;
        }

        // 2. Check Edges and Inner values
        if (isValid) {
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    int val = grid[r][c];

                    // Any value greater than MAX_INNER_VALUE is invalid
                    if (val > MAX_INNER_VALUE) {
                        isValid = false;
                        break;
                    }

                    // Edge cells (border) must not exceed MAX_EDGE_VALUE
                    boolean isEdge = (r == 0 || r == rows - 1 || c == 0 || c == cols - 1);
                    if (isEdge && val > MAX_EDGE_VALUE) {
                        isValid = false;
                        break;
                    }
                }
                if (!isValid) break;
            }
        }

        // Output Result
        if (!isValid) {
            out.println("NO");
        } else {
            out.println("YES");
            // Generate the required output pattern
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    int val = MAX_INNER_VALUE;

                    // Decrease value for horizontal edges (columns 0 and cols-1)
                    if (c == 0 || c == cols - 1) {
                        val--;
                    }
                    // Decrease value for vertical edges (rows 0 and rows-1)
                    if (r == 0 || r == rows - 1) {
                        val--;
                    }
                    out.print(val + " ");
                }
                out.println();
            }
        }
    }

    /**
     * Utility class for fast input reading.
     */
    static class FastReader {
        BufferedReader br;
        StringTokenizer st;

        public FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    e.printStackTrace();
                    return null;
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            String s = next();
            return (s == null) ? 0 : Integer.parseInt(s);
        }

        long nextLong() {
            String s = next();
            return (s == null) ? 0L : Long.parseLong(s);
        }

        double nextDouble() {
            String s = next();
            return (s == null) ? 0.0 : Double.parseDouble(s);
        }

        String nextLine() {
            String str = "";
            try {
                str = br.readLine();
            } catch (IOException e) {
                e.printStackTrace();
            }
            return str;
        }
    }
}

import java.io.BufferedOutputStream;
import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.InputMismatchException;

/**
 * Processes grid-based test cases.
 * Validates each cell against its neighbor count, transforms the grid,
 * and fills remaining zeros based on non-zero neighbors.
 */
public class GridProcessor {

    private final PrintWriter out;
    private final FastReader reader;

    public GridProcessor(InputStream in, PrintWriter out) {
        this.reader = new FastReader(in);
        this.out = out;
    }

    /**
     * Solves all test cases sequentially.
     */
    public void solve() {
        int testCases = reader.nextInt();
        while (testCases-- > 0) {
            int rows = reader.nextInt();
            int cols = reader.nextInt();
            int[][] grid = readGrid(rows, cols);

            if (validateAndTransform(grid, rows, cols)) {
                out.println("YES");
                printGrid(grid, rows, cols);
            } else {
                out.println("NO");
            }
        }
    }

    private int[][] readGrid(int rows, int cols) {
        int[][] grid = new int[rows][cols];
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                grid[i][j] = reader.nextInt();
            }
        }
        return grid;
    }

    /**
     * Validates the grid and applies the required transformations in-place.
     * Returns false if any cell violates the neighbor count constraint.
     */
    private boolean validateAndTransform(int[][] grid, int rows, int cols) {
        // Pass 1: Validate original values and replace with valid direction count
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                int neighborCount = countValidDirections(i, j, rows, cols);
                if (grid[i][j] > neighborCount) {
                    return false;
                }
                grid[i][j] = neighborCount;
            }
        }

        // Pass 2: Fill zeros with count of non-zero neighbors
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == 0) {
                    grid[i][j] = countNonZeroNeighbors(grid, i, j, rows, cols);
                }
            }
        }
        return true;
    }

    private int countValidDirections(int row, int col, int rows, int cols) {
        int count = 0;
        if (row > 0) count++;
        if (row < rows - 1) count++;
        if (col > 0) count++;
        if (col < cols - 1) count++;
        return count;
    }

    private int countNonZeroNeighbors(int[][] grid, int row, int col, int rows, int cols) {
        int count = 0;
        if (row > 0 && grid[row - 1][col] != 0) count++;
        if (row < rows - 1 && grid[row + 1][col] != 0) count++;
        if (col > 0 && grid[row][col - 1] != 0) count++;
        if (col < cols - 1 && grid[row][col + 1] != 0) count++;
        return count;
    }

    private void printGrid(int[][] grid, int rows, int cols) {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                sb.append(grid[i][j]).append(' ');
            }
            sb.append('\n');
        }
        out.print(sb);
    }

    public static void main(String[] args) {
        // Competitive programming hack: increase thread stack size to prevent
        // StackOverflowError on large inputs or deeply nested operations.
        new Thread(null, new Runnable() {
            @Override
            public void run() {
                PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out));
                try {
                    GridProcessor processor = new GridProcessor(System.in, out);
                    processor.solve();
                } catch (Exception e) {
                    e.printStackTrace();
                    System.exit(1);
                } finally {
                    out.close();
                }
            }
        }, "Thread", 1 << 27).start();
    }

    /**
     * Fast input reader optimized for competitive programming environments.
     */
    public static class FastReader {
        private final InputStream stream;
        private final byte[] buf = new byte[4096];
        private int curChar, snumChars;

        public FastReader(InputStream stream) {
            this.stream = stream;
        }

        private int read() {
            if (snumChars == -1) {
                throw new InputMismatchException();
            }
            if (curChar >= snumChars) {
                curChar = 0;
                try {
                    snumChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
            }
            if (snumChars <= 0) {
                return -1;
            }
            return buf[curChar++];
        }

        public int nextInt() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            int number = 0;
            do {
                number *= 10;
                number += c - '0';
                c = read();
            } while (!isSpaceChar(c));
            return number * sgn;
        }

        public long nextLong() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            long sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            long number = 0;
            do {
                number *= 10L;
                number += (long) (c - '0');
                c = read();
            } while (!isSpaceChar(c));
            return number * sgn;
        }

        public int[] nextIntArray(int n) {
            int[] arr = new int[n];
            for (int i = 0; i < n; i++) {
                arr[i] = nextInt();
            }
            return arr;
        }

        public long[] nextLongArray(int n) {
            long[] arr = new long[n];
            for (int i = 0; i < n; i++) {
                arr[i] = nextLong();
            }
            return arr;
        }

        public String next() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            StringBuilder res = new StringBuilder();
            do {
                res.appendCodePoint(c);
                c = read();
            } while (!isSpaceChar(c));
            return res.toString();
        }

        public String nextLine() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            StringBuilder res = new StringBuilder();
            do {
                res.appendCodePoint(c);
                c = read();
            } while (!isEndofLine(c));
            return res.toString();
        }

        public boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        public boolean isEndofLine(int c) {
            return c == '\n' || c == '\r' || c == -1;
        }
    }
}

import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.InputMismatchException;

/**
 * Validates a grid where each cell's value must not exceed the number of its 
 * valid adjacent neighbors (up, down, left, right). If valid, outputs the 
 * grid of neighbor counts. Otherwise, outputs NO.
 */
public class GridNeighborValidator {

    public static void main(String[] args) throws IOException {
        FastScanner scanner = new FastScanner();
        PrintWriter out = new PrintWriter(System.out);

        int t = scanner.nextInt();
        while (t-- > 0) {
            int n = scanner.nextInt();
            int m = scanner.nextInt();

            int[][] grid = new int[n][m];
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    grid[i][j] = scanner.nextInt();
                }
            }

            ValidationResult result = processTestCase(n, m, grid);
            if (result.isValid) {
                out.println("YES");
                for (int i = 0; i < n; i++) {
                    for (int j = 0; j < m; j++) {
                        out.print(result.neighborCounts[i][j] + " ");
                    }
                    out.println();
                }
            } else {
                out.println("NO");
            }
        }
        out.flush();
    }

    /**
     * Processes a single test case.
     * Checks if every cell's value is <= the number of its valid adjacent cells.
     * Returns the validation result and the grid of neighbor counts.
     */
    private static ValidationResult processTestCase(int n, int m, int[][] grid) {
        int[][] neighborCounts = new int[n][m];
        boolean isValid = true;

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                int count = calculateNeighborCount(i, j, n, m);
                if (grid[i][j] > count) {
                    isValid = false;
                    break;
                }
                neighborCounts[i][j] = count;
            }
            if (!isValid) break;
        }

        return new ValidationResult(isValid, neighborCounts);
    }

    /**
     * Calculates the number of valid adjacent cells (up, down, left, right) 
     * for a given cell in an n x m grid.
     */
    private static int calculateNeighborCount(int row, int col, int n, int m) {
        int count = 0;
        if (row > 0) count++;
        if (row < n - 1) count++;
        if (col > 0) count++;
        if (col < m - 1) count++;
        return count;
    }

    /**
     * Holds the result of a test case validation.
     */
    private static class ValidationResult {
        final boolean isValid;
        final int[][] neighborCounts;

        ValidationResult(boolean isValid, int[][] neighborCounts) {
            this.isValid = isValid;
            this.neighborCounts = neighborCounts;
        }
    }

    /**
     * High-performance I/O scanner for competitive programming.
     */
    private static class FastScanner {
        private final InputStream inputStream;
        private final byte[] buffer = new byte[1024];
        private int bufferPointer = 0;
        private int bytesRead = 0;

        public FastScanner() {
            this(System.in);
        }

        public FastScanner(InputStream inputStream) {
            this.inputStream = inputStream;
        }

        private int read() throws IOException {
            if (bufferPointer == bytesRead) {
                bufferPointer = 0;
                try {
                    bytesRead = inputStream.read(buffer);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (bytesRead <= 0) {
                    throw new InputMismatchException();
                }
            }
            return buffer[bufferPointer++];
        }

        public String next() {
            StringBuilder res = new StringBuilder();
            int c = read();
            while (isSpaceChar(c)) c = read();
            do {
                res.appendCodePoint(c);
                c = read();
            } while (!isSpaceChar(c));
            return res.toString();
        }

        public int nextInt() {
            int c = read();
            while (isSpaceChar(c)) c = read();
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9') throw new InputMismatchException();
                res *= 10;
                res += c - '0';
                c = read();
            } while (!isSpaceChar(c));
            return res * sign;
        }

        public long nextLong() {
            int c = read();
            while (isSpaceChar(c)) c = read();
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            long res = 0;
            do {
                if (c < '0' || c > '9') throw new InputMismatchException();
                res *= 10;
                res += c - '0';
                c = read();
            } while (!isSpaceChar(c));
            return res * sign;
        }

        public double nextDouble() {
            return Double.parseDouble(next());
        }

        public String nextLine() {
            int c = read();
            while (isSpaceChar(c)) c = read();
            StringBuilder res = new StringBuilder();
            do {
                res.appendCodePoint(c);
                c = read();
            } while (!isEndOfLine(c));
            return res.toString();
        }

        public int[] nextIntArray(int n) {
            int[] arr = new int[n];
            for (int i = 0; i < n; i++) {
                arr[i] = nextInt();
            }
            return arr;
        }

        public long[] nextLongArray(int n) {
            long[] arr = new long[n];
            for (int i = 0; i < n; i++) {
                arr[i] = nextLong();
            }
            return arr;
        }

        private boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        private boolean isEndOfLine(int c) {
            return c == '\n' || c == '\r' || c == -1;
        }
    }
}

import java.io.*;
import java.util.*;

public class Main {
    // Constants defining maximum allowed values for different grid regions
    private static final int CORNER_THRESHOLD = 2;
    private static final int EDGE_THRESHOLD = 3;
    private static final int INNER_THRESHOLD = 4;

    public static void main(String[] args) {
        FastReader reader = new FastReader();
        PrintWriter out = new PrintWriter(System.out);

        String tStr = reader.next();
        if (tStr != null) {
            int t = Integer.parseInt(tStr);
            while (t-- > 0) {
                solve(reader, out);
            }
        }
        out.flush();
    }

    /**
     * Reads grid dimensions and values, then validates and prints the result.
     */
    private static void solve(FastReader reader, PrintWriter out) {
        int n = reader.nextInt();
        int m = reader.nextInt();
        int[][] grid = new int[n][m];

        // Read the input grid
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                grid[i][j] = reader.nextInt();
            }
        }

        // Validate constraints and produce output
        processGrid(grid, n, m, out);
    }

    /**
     * Validates the grid against region-specific thresholds and prints the result.
     */
    private static void processGrid(int[][] grid, int n, int m, PrintWriter out) {
        // First pass: Validate all cells
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                int threshold = getThreshold(i, j, n, m);
                if (grid[i][j] > threshold) {
                    out.println("NO");
                    return;
                }
            }
        }

        // Second pass: Print success message and transformed grid
        out.println("YES");
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                out.print(getThreshold(i, j, n, m));
                out.print(j == m - 1 ? "" : " ");
            }
            out.println();
        }
    }

    /**
     * Determines the threshold value based on the cell's position.
     * Corners must be <= 2, edges <= 3, and inner cells <= 4.
     */
    private static int getThreshold(int i, int j, int n, int m) {
        boolean isCorner = (i == 0 || i == n - 1) && (j == 0 || j == m - 1);
        boolean isEdge = (i == 0 || i == n - 1) || (j == 0 || j == m - 1);

        if (isCorner) return CORNER_THRESHOLD;
        if (isEdge) return EDGE_THRESHOLD;
        return INNER_THRESHOLD;
    }

    /**
     * Optimized Fast I/O helper for competitive programming.
     */
    static class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input", e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            String s = next();
            return s == null ? 0 : Integer.parseInt(s);
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

/**
 * Validates and modifies a 2D grid based on positional constraints.
 * Corners must be <= 2, edges <= 3, and interior cells <= 4.
 */
public class GridValidator {

    // Magic numbers extracted to named constants for clarity and maintainability
    private static final int CORNER_MAX = 2;
    private static final int EDGE_MAX = 3;
    private static final int INTERIOR_MAX = 4;

    // Encapsulated I/O resources
    private static final FastReader input = new FastReader();
    private static final PrintWriter output = new PrintWriter(System.out);

    public static void main(String[] args) {
        int t = input.nextInt();
        while (t-- > 0) {
            int n = input.nextInt();
            int m = input.nextInt();
            int[][] grid = readIntMatrix(n, m);

            if (validateAndModifyGrid(grid, n, m)) {
                output.println("YES");
                printGrid(grid, n, m);
            } else {
                output.println("NO");
            }
        }
        output.flush();
    }

    /**
     * Validates grid constraints and modifies values in-place.
     * Returns false immediately if any cell violates its positional limit.
     */
    private static boolean validateAndModifyGrid(int[][] grid, int n, int m) {
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                int maxAllowed = getMaxAllowedValue(i, j, n, m);
                if (grid[i][j] > maxAllowed) {
                    return false;
                }
                grid[i][j] = maxAllowed;
            }
        }
        return true;
    }

    /**
     * Determines the maximum allowed value for a cell based on its position.
     * Priority: Corners > Edges > Interior
     */
    private static int getMaxAllowedValue(int row, int col, int n, int m) {
        boolean isCorner = (row == 0 || row == n - 1) && (col == 0 || col == m - 1);
        boolean isEdge = row == 0 || row == n - 1 || col == 0 || col == m - 1;

        if (isCorner) return CORNER_MAX;
        if (isEdge) return EDGE_MAX;
        return INTERIOR_MAX;
    }

    /**
     * Prints the modified grid to standard output.
     */
    private static void printGrid(int[][] grid, int n, int m) {
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                output.print(grid[i][j]);
                output.print(j == m - 1 ? "" : " ");
            }
            output.println();
        }
    }

    // ========================
    // Input Reading Helpers
    // ========================
    private static int[][] readIntMatrix(int n, int m) {
        int[][] matrix = new int[n][m];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                matrix[i][j] = input.nextInt();
            }
        }
        return matrix;
    }

    private static long[][] readLongMatrix(int n, int m) {
        long[][] matrix = new long[n][m];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                matrix[i][j] = input.nextLong();
            }
        }
        return matrix;
    }

    // ========================
    // Fast I/O Implementation
    // ========================
    static class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            String s = next();
            return s == null ? 0 : Integer.parseInt(s);
        }

        long nextLong() {
            String s = next();
            return s == null ? 0L : Long.parseLong(s);
        }
    }
}

