    /**
     * Validates the grid state and applies updates.
     * Returns null if the grid configuration violates neighbor constraints.
     */
    private static int[][] updateGrid(int[][] grid, int n, int m) {
        // First pass: validate neighbors and attempt to distribute increments
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] > 0) {
                    if (!validateAndDistribute(grid, n, m, i, j)) {
                        return null;
                    }
                }
            }
        }

        // Second pass: apply calculated decrements
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] > 0) {
                    grid[i][j] -= calculateDecrement(grid, n, m, i, j);
                }
            }
        }
        return grid;
    }

    /**
     * Calculates how many decrements are needed based on active neighbors.
     */
    private static int calculateDecrement(int[][] grid, int n, int m, int r, int c) {
        int decrement = grid[r][c];
        for (int k = 0; k < 4; k++) {
            int nr = r + DR[k];
            int nc = c + DC[k];
            if (isValid(nr, nc, n, m) && grid[nr][nc] > 0) {
                decrement--;
            }
        }
        return decrement;
    }

    /**
     * Validates if excess increments can be distributed to neighbors.
     */
    private static boolean validateAndDistribute(int[][] grid, int n, int m, int r, int c) {
        int excess = calculateDecrement(grid, n, m, r, c);

        if (excess > 4) {
            return false;
        }

        if (excess < 0) {
            grid[r][c] -= excess; // Add back the negative excess
            return true;
        }

        // Attempt to increment neighbors in a fixed order
        for (int k = 0; k < 4; k++) {
            int nr = r + DIST_DR[k];
            int nc = c + DIST_DC[k];
            if (isValid(nr, nc, n, m) && excess > 0) {
                if (incrementCell(grid, nr, nc)) {
                    excess--;
                }
            }
        }
        return excess == 0;
    }

    /**
     * Increments a cell if it is currently 0.
     */
    private static boolean incrementCell(int[][] grid, int r, int c) {
        if (grid[r][c] == 0) {
            grid[r][c]++;
            return true;
        }
        return false;
    }

    /**
     * Checks if coordinates are within grid bounds.
     */
    private static boolean isValid(int r, int c, int n, int m) {
        return r >= 0 && r < n && c >= 0 && c < m;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
