import java.util.StringTokenizer;

public class MatrixConstraintSolver {

    public static void main(String[] args) {
        MatrixConstraintSolver solver = new MatrixConstraintSolver();
        solver.run();
    }

    public void run() {
        FastScanner scanner = new FastScanner();
        PrintWriter out = new PrintWriter(System.out);

        try {
            int testCases = scanner.nextInt();
            while (testCases-- > 0) {
                int rows = scanner.nextInt();
                int cols = scanner.nextInt();
                processTestCase(rows, cols, scanner, out);
            }
        } catch (Exception e) {
            // In competitive programming contexts, we typically assume well-formed input.
            // For production systems, replace with proper logging/framework error handling.
            e.printStackTrace();
        } finally {
            out.flush();
        }
    }

    private void processTestCase(int rows, int cols, FastScanner scanner, PrintWriter out) {
        boolean isValid = true;

        // Read the entire grid to consume input, even if validation fails early.
        // This prevents subsequent test cases from reading stale tokens.
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                int value = scanner.nextInt();
                if (!isValid) continue;

                if (isCorner(i, j, rows, cols)) {
                    if (value > 2) isValid = false;
                } else if (isEdge(i, j, rows, cols)) {
                    if (value > 3) isValid = false;
                } else {
                    if (value > 4) isValid = false;
                }
            }
        }

        if (!isValid) {
            out.println("NO");
        } else {
            out.println("YES");
            printConstructedGrid(rows, cols, out);
        }
    }

    private boolean isCorner(int r, int c, int rows, int cols) {
        return (r == 0 && c == 0) || (r == 0 && c == cols - 1) ||
               (r == rows - 1 && c == 0) || (r == rows - 1 && c == cols - 1);
    }

    private boolean isEdge(int r, int c, int rows, int cols) {
        return r == 0 || c == 0 || r == rows - 1 || c == cols - 1;
    }

    private void printConstructedGrid(int rows, int cols, PrintWriter out) {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (isCorner(i, j, rows, cols)) {
                    out.print(2);
                } else if (isEdge(i, j, rows, cols)) {
                    out.print(3);
                } else {
                    out.print(4);
                }
                out.print(j == cols - 1 ? "" : " ");
            }
            out.println();
        }
    }

    /**
     * Efficient input reader using BufferedReader and StringTokenizer.
     * Provides competitive programming performance with standard Java APIs
     * for better readability and maintainability.
     */
    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input", e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            String s = next();
            if (s == null) throw new RuntimeException("Unexpected end of input");
            return Integer.parseInt(s);
        }
    }
}

