                int[][] resultGrid = new int[r][c];
                boolean isValid = true;

                for (int i = 0; i < r; i++) {
                    for (int j = 0; j < c; j++) {
                        int inputVal = scanner.nextInt();
                        int expectedVal = getExpectedValue(i, j, r, c);
                        resultGrid[i][j] = expectedVal;

