    private static int getExpectedValue(int i, int j, int r, int c) {
        if ((i == 0 && j == 0) || (i == 0 && j == c - 1) ||
            (i == r - 1 && j == 0) || (i == r - 1 && j == c - 1)) {
            return CORNER_VALUE;
        } else if (i == 0 || j == 0 || j == c - 1 || i == r - 1) {
            return EDGE_VALUE;
        } else {
