public class GridValidator {

    private static final String YES = "YES";
    private static final String NO = "NO";

    private static final int CORNER_LIMIT = 2;
    private static final int EDGE_LIMIT = 3;
    private static final int INTERIOR_LIMIT = 4;

    public static void main(String[] args) throws IOException {
        // Use try-with-resources to ensure streams are properly closed and flushed
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
             PrintWriter out = new PrintWriter(System.out)) {

            FastScanner scanner = new FastScanner(br);
            int testCases = scanner.nextInt();

            for (int t = 0; t < testCases; t++) {
                int rows = scanner.nextInt();
                int cols = scanner.nextInt();

                int[][] limits = new int[rows][cols];
                boolean isValid = true;

                // Read grid values, compute limits, and validate in a single pass
                for (int i = 0; i < rows; i++) {
                    for (int j = 0; j < cols; j++) {
                        int value = scanner.nextInt();
                        limits[i][j] = calculateLimit(i, j, rows, cols);
                        if (value > limits[i][j]) {
                            isValid = false;
                        }
                    }
                }

                if (!isValid) {
                    out.println(NO);
                } else {
                    out.println(YES);
                    printGrid(limits, out);
                }
            }
        }
    }

    /**
     * Calculates the maximum allowed value for a cell based on its position.
     * Corners: 2, Edges: 3, Interior: 4
     */
    private static int calculateLimit(int row, int col, int numRows, int numCols) {
        boolean isTopOrBottom = (row == 0 || row == numRows - 1);
        boolean isLeftOrRight = (col == 0 || col == numCols - 1);

        if (isTopOrBottom && isLeftOrRight) {
            return CORNER_LIMIT;
        } else if (isTopOrBottom || isLeftOrRight) {
            return EDGE_LIMIT;
        } else {
            return INTERIOR_LIMIT;
        }
    }

    /**
     * Prints a 2D integer grid to the provided PrintWriter with space separation.
     */
    private static void printGrid(int[][] grid, PrintWriter out) {
        for (int i = 0; i < grid.length; i++) {
            for (int j = 0; j < grid[i].length; j++) {
                out.print(grid[i][j]);
                if (j < grid[i].length - 1) {
                    out.print(' ');
                }
            }
            out.println();
        }
    }

    /**
     * Lightweight scanner for fast input reading.
     */
    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner(BufferedReader br) {
            this.br = br;
        }

        String next() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) {
                    throw new IOException("Unexpected end of input");
                }
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}

import java.util.Scanner;

/**
 * NeighborGrid solves a grid transformation problem.
 * It validates if a grid meets specific boundary constraints and, if so,
 * outputs the transformed grid where cells are replaced by their maximum allowed values.
 */
public class NeighborGrid {

    // Constants defining the maximum allowed values for different cell positions
    private static final int CORNER_LIMIT = 2;
    private static final int EDGE_LIMIT = 3;
    private static final int INNER_LIMIT = 4;

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        // Read number of test cases safely
        if (scanner.hasNextInt()) {
            int t = scanner.nextInt();
            for (int i = 0; i < t; i++) {
                solveTestCase(scanner);
            }
        }

        scanner.close();
    }

    /**
     * Processes a single test case.
     * Reads dimensions and grid, validates constraints, and prints the result.
     */
    private static void solveTestCase(Scanner scanner) {
        // Read dimensions
        int rows = scanner.nextInt();
        int cols = scanner.nextInt();

        // Read the grid data
        int[][] grid = new int[rows][cols];
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                grid[i][j] = scanner.nextInt();
            }
        }

        // Validate and process
        if (isValidGrid(grid, rows, cols)) {
            System.out.println("YES");
            printTransformedGrid(rows, cols);
        } else {
            System.out.println("NO");
        }
    }

    /**
     * Checks if the grid satisfies the constraints for all cells.
     * Corners must be <= 2, Edges <= 3, Inner cells <= 4.
     */
    private static boolean isValidGrid(int[][] grid, int rows, int cols) {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                int limit = getCellLimit(i, j, rows, cols);
                if (grid[i][j] > limit) {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Determines the maximum allowed value for a cell at (r, c).
     * This encapsulates the logic previously scattered across the original loop.
     */
    private static int getCellLimit(int r, int c, int rows, int cols) {
        boolean isBoundaryRow = (r == 0 || r == rows - 1);
        boolean isBoundaryCol = (c == 0 || c == cols - 1);

        if (isBoundaryRow && isBoundaryCol) {
            return CORNER_LIMIT;
        } else if (isBoundaryRow || isBoundaryCol) {
            return EDGE_LIMIT;
        } else {
            return INNER_LIMIT;
        }
    }

    /**
     * Prints the transformed grid based on the calculated limits.
     */
    private static void printTransformedGrid(int rows, int cols) {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                System.out.print(getCellLimit(i, j, rows, cols) + " ");
            }
            System.out.println();
        }
    }
}

import java.io.*;
import java.util.*;

public class Solution {
    // Named constants replace magic numbers for clarity and easy maintenance
    private static final int CORNER_MAX = 2;
    private static final int EDGE_MAX = 3;
    private static final int INTERIOR_MAX = 4;

    public static void main(String[] args) throws Exception {
        FastReader reader = new FastReader();
        PrintWriter out = new PrintWriter(System.out);

        int t = reader.nextInt();
        while (t-- > 0) {
            solve(reader, out);
        }

        out.flush();
    }

    /**
     * Processes a single test case: reads dimensions and matrix,
     * validates constraints, and prints the result.
     */
    private static void solve(FastReader reader, PrintWriter out) {
        int n = reader.nextInt();
        int m = reader.nextInt();
        int[][] matrix = new int[n][m];
        boolean possible = true;

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                int value = reader.nextInt();
                int maxAllowed = getMaxAllowedValue(i, j, n, m);

                if (value > maxAllowed) {
                    possible = false;
                } else {
                    matrix[i][j] = maxAllowed;
                }
            }
        }

        if (possible) {
            out.println("YES");
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    out.print(matrix[i][j] + " ");
                }
                out.println();
            }
        } else {
            out.println("NO");
        }
    }

    /**
     * Determines the maximum allowed value based on grid position.
     * Priority: Corners -> Edges -> Interior
     */
    private static int getMaxAllowedValue(int i, int j, int n, int m) {
        boolean isCorner = (i == 0 || i == n - 1) && (j == 0 || j == m - 1);
        boolean isEdge = i == 0 || i == n - 1 || j == 0 || j == m - 1;

        if (isCorner) return CORNER_MAX;
        if (isEdge) return EDGE_MAX;
        return INTERIOR_MAX;
    }
}

