/**
 * Validates a grid against specific boundary conditions and prints a reference grid.
 */
public class GridValidator {

    private static final int CORNER_THRESHOLD = 2;
    private static final int EDGE_THRESHOLD = 3;
    private static final int INTERIOR_THRESHOLD = 4;

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        if (scanner.hasNextInt()) {
            int testCases = scanner.nextInt();

            for (int t = 0; t < testCases; t++) {
                int rows = scanner.nextInt();
                int cols = scanner.nextInt();
                int[][] grid = new int[rows][cols];

                for (int i = 0; i < rows; i++) {
                    for (int j = 0; j < cols; j++) {
                        grid[i][j] = scanner.nextInt();
                    }
                }

                boolean isValid = validateGrid(grid, rows, cols);
                if (isValid) {
                    System.out.println("YES");
                    printReferenceGrid(rows, cols);
                } else {
                    System.out.println("NO");
                }
            }
        }
        scanner.close();
    }

    /**
     * Validates that each cell in the grid does not exceed its positional threshold.
     */
    private static boolean validateGrid(int[][] grid, int rows, int cols) {
        for (int row = 0; row < rows; row++) {
            for (int col = 0; col < cols; col++) {
                if (grid[row][col] > getThreshold(row, col, rows, cols)) {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Determines the maximum allowed value based on the cell's position.
     */
    private static int getThreshold(int row, int col, int rows, int cols) {
        boolean isCorner = (row == 0 || row == rows - 1) && (col == 0 || col == cols - 1);
        boolean isEdge = row == 0 || row == rows - 1 || col == 0 || col == cols - 1;

        if (isCorner) return CORNER_THRESHOLD;
        if (isEdge) return EDGE_THRESHOLD;
        return INTERIOR_THRESHOLD;
    }

    /**
     * Prints the reference grid based on positional thresholds.
     */
    private static void printReferenceGrid(int rows, int cols) {
        for (int row = 0; row < rows; row++) {
            for (int col = 0; col < cols; col++) {
                System.out.print(getThreshold(row, col, rows, cols) + " ");
            }
            System.out.println();
        }
    }
}

