/**
 * Refactored version of the Neighborhood Grid program.
 * 
 * Improvements made:
 * 1. Naming Conventions: Class and variable names follow Java standards (PascalCase for classes, camelCase for variables).
 * 2. Readability: Magic numbers (2, 3, 4) are replaced with named constants.
 * 3. Structure: Logic is separated into methods (Input, Validation, Output) for better maintainability.
 * 4. Resource Management: Scanner is handled with try-with-resources to prevent leaks.
 * 5. Output Formatting: Fixed the grid printing logic to display rows correctly (space-separated values) 
 *    instead of printing every number on a new line.
 */
public class NeighborhoodGrid {

    // Constants defining the maximum allowed values for grid cells based on position.
    // Corners have fewer neighbors, thus stricter limits.
    private static final int CORNER_LIMIT = 2;
    private static final int EDGE_LIMIT = 3;
    private static final int INNER_LIMIT = 4;

    public static void main(String[] args) {
        // Use try-with-resources to ensure the Scanner is closed automatically
        try (Scanner scanner = new Scanner(System.in)) {
            if (scanner.hasNextInt()) {
                int numTestCases = scanner.nextInt();

                for (int i = 0; i < numTestCases; i++) {
                    processTestCase(scanner);
                }
            }
        }
    }

    /**
     * Processes a single test case: reads dimensions, grid data, validates constraints,
     * and prints the result.
     */
    private static void processTestCase(Scanner scanner) {
        int rows = scanner.nextInt();
        int cols = scanner.nextInt();

        long[][] grid = new long[rows][cols];

        // Read the grid values
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                grid[r][c] = scanner.nextLong();
            }
        }

        boolean isValid = true;

        // Validate and transform the grid
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                int limit = getLimitForPosition(r, c, rows, cols);

                if (grid[r][c] > limit) {
                    isValid = false;
                    // No need to check further for this grid
                    break; 
                } else {
                    // Update value to the limit (as per original logic)
                    grid[r][c] = limit;
                }
            }
            if (!isValid) {
                break;
            }
        }

        if (!isValid) {
            System.out.println("NO");
        } else {
            System.out.println("YES");
            printGrid(grid);
        }
    }

    /**
     * Determines the maximum allowed value for a cell based on its coordinates.
     * - Corners (intersections of boundaries) have limit 2.
     * - Edges (on boundary but not corner) have limit 3.
     * - Inner cells have limit 4.
     */
    private static int getLimitForPosition(int row, int col, int totalRows, int totalCols) {
        boolean isTopOrBottom = (row == 0 || row == totalRows - 1);
        boolean isLeftOrRight = (col == 0 || col == totalCols - 1);

        if (isTopOrBottom && isLeftOrRight) {
            return CORNER_LIMIT;
        } else if (isTopOrBottom || isLeftOrRight) {
            return EDGE_LIMIT;
        } else {
            return INNER_LIMIT;
        }
    }

    /**
     * Prints the grid to standard output.
     * Outputs rows on separate lines with space-separated values.
     */
    private static void printGrid(long[][] grid) {
        StringBuilder sb = new StringBuilder();
        for (long[] row : grid) {
            for (long value : row) {
                sb.append(value).append(" ");
            }
            sb.append("\n");
        }
        System.out.print(sb.toString());
    }
}

