    private static final int CORNER_LIMIT = 2;
    private static final int EDGE_LIMIT = 3;
    private static final int INNER_LIMIT = 4;

    private static final Scanner scanner = new Scanner(System.in);

    public static void main(String[] args) {
        // Check if input exists to handle potential empty input gracefully
        if (scanner.hasNextInt()) {
            int testCases = scanner.nextInt();
            for (int t = 0; t < testCases; t++) {
                solveTestCase();
            }
        }
        scanner.close();
    }

    /**
     * Solves a single test case.
     * Reads the grid dimensions and values, validates constraints,
     * modifies the grid, and prints the result.
     */
    private static void solveTestCase() {
        int rows = scanner.nextInt();
        int cols = scanner.nextInt();
        int[][] grid = new int[rows][cols];

        // 1. Read the entire grid first.
        // This ensures we consume all input for the current test case 
        // even if validation fails later.
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                grid[i][j] = scanner.nextInt();
            }
        }

        boolean isValid = true;

        // 2. Process and Validate the grid
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                int limit = getLimitForPosition(i, j, rows, cols);

                if (grid[i][j] > limit) {
                    isValid = false;
                } else {
                    // Update the cell to the maximum allowed value for its position
                    grid[i][j] = limit;
                }
            }
        }

        // 3. Output results
        if (isValid) {
            System.out.println("YES");
            printGrid(grid);
        } else {
            System.out.println("NO");
        }
    }

    /**
     * Determines the maximum allowed value for a cell based on its position.
     * - Corners (0,0), (0,m-1), (n-1,0), (n-1,m-1): Limit is 2
     * - Edges (excluding corners): Limit is 3
     * - Interior: Limit is 4
     */
    private static int getLimitForPosition(int row, int col, int totalRows, int totalCols) {
        boolean isTopOrBottom = (row == 0 || row == totalRows - 1);
        boolean isLeftOrRight = (col == 0 || col == totalCols - 1);

        if (isTopOrBottom && isLeftOrRight) {
            return CORNER_LIMIT;
        }
        if (isTopOrBottom || isLeftOrRight) {
            return EDGE_LIMIT;
        }
        return INNER_LIMIT;
    }

    /**
     * Prints the 2D array to standard output.
     */
    private static void printGrid(int[][] grid) {
        for (int[] row : grid) {
            for (int val : row) {
                System.out.print(val + " ");
            }
            System.out.println();
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

/**
 * Validates and caps grid values based on their position (interior, edge, corner).
 * Refactored for maintainability, readability, and removal of dead code.
 */
public class GridValidator {
    // Constants for position-based value limits
    private static final int INTERIOR_LIMIT = 4;
    private static final int EDGE_LIMIT = 3;
    private static final int CORNER_LIMIT = 2;

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner();
        PrintWriter out = new PrintWriter(System.out);

        try {
            // Read number of test cases
            String tStr = scanner.next();
            if (tStr == null) return;
            int t = Integer.parseInt(tStr);

            while (t-- > 0) {
                int n = scanner.nextInt();
                int m = scanner.nextInt();
                int[][] grid = new int[n][m];

                // Read grid values
                for (int i = 0; i < n; i++) {
                    for (int j = 0; j < m; j++) {
                        grid[i][j] = scanner.nextInt();
                    }
                }

                // Process and output result
                processGrid(grid, n, m, out);
            }
        } finally {
            out.flush();
            out.close();
        }
    }

    /**
     * Validates grid constraints and applies value caps based on cell position.
     * Modifies the grid in-place.
     */
    private static void processGrid(int[][] grid, int n, int m, PrintWriter out) {
        boolean possible = true;

        // 1. Check and cap interior cells (not on any border)
        for (int i = 1; i < n - 1; i++) {
            for (int j = 1; j < m - 1; j++) {
                if (grid[i][j] > INTERIOR_LIMIT) {
                    possible = false;
                }
                grid[i][j] = Math.min(grid[i][j], INTERIOR_LIMIT);
            }
        }

        // 2. Check and cap left/right edges (excluding corners)
        for (int i = 1; i < n - 1; i++) {
            if (grid[i][0] > EDGE_LIMIT) possible = false;
            if (grid[i][m - 1] > EDGE_LIMIT) possible = false;
            grid[i][0] = Math.min(grid[i][0], EDGE_LIMIT);
            grid[i][m - 1] = Math.min(grid[i][m - 1], EDGE_LIMIT);
        }

        // 3. Check and cap top/bottom edges (excluding corners)
        for (int j = 1; j < m - 1; j++) {
            if (grid[0][j] > EDGE_LIMIT) possible = false;
            if (grid[n - 1][j] > EDGE_LIMIT) possible = false;
            grid[0][j] = Math.min(grid[0][j], EDGE_LIMIT);
            grid[n - 1][j] = Math.min(grid[n - 1][j], EDGE_LIMIT);
        }

        // 4. Check and cap corners
        if (grid[0][0] > CORNER_LIMIT) possible = false;
        if (grid[0][m - 1] > CORNER_LIMIT) possible = false;
        if (grid[n - 1][0] > CORNER_LIMIT) possible = false;
        if (grid[n - 1][m - 1] > CORNER_LIMIT) possible = false;
        grid[0][0] = Math.min(grid[0][0], CORNER_LIMIT);
        grid[0][m - 1] = Math.min(grid[0][m - 1], CORNER_LIMIT);
        grid[n - 1][0] = Math.min(grid[n - 1][0], CORNER_LIMIT);
        grid[n - 1][m - 1] = Math.min(grid[n - 1][m - 1], CORNER_LIMIT);

        // Output result
        if (possible) {
            out.println("YES");
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    out.print(grid[i][j]);
                    out.print(j == m - 1 ? "" : " ");
                }
                out.println();
            }
        } else {
            out.println("NO");
        }
    }

    /**
     * Fast I/O helper class for competitive programming style input reading.
     */
    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            String s = next();
            return s == null ? 0 : Integer.parseInt(s);
        }

        long nextLong() {
            String s = next();
            return s == null ? 0L : Long.parseLong(s);
        }

        double nextDouble() {
            String s = next();
            return s == null ? 0.0 : Double.parseDouble(s);
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

/**
 * Validates and transforms a 2D grid based on positional constraints.
 * <p>
 * Constraints:
 * <ul>
 *   <li>Corners must be &le; 2</li>
 *   <li>Edges must be &le; 3</li>
 *   <li>Interior cells must be &le; 4</li>
 * </ul>
 * Outputs "YES" and the maximum valid grid if constraints are met, otherwise "NO".
 */
public class GridConstraintValidator {

    private static final int CORNER_LIMIT = 2;
    private static final int EDGE_LIMIT = 3;
    private static final int INTERIOR_LIMIT = 4;

    public static void main(String[] args) {
        FastReader reader = new FastReader();
        PrintWriter out = new PrintWriter(System.out);

        try {
            String tStr = reader.next();
            if (tStr == null) return;
            int t = Integer.parseInt(tStr);

            while (t-- > 0) {
                int n = reader.nextInt();
                int m = reader.nextInt();

                boolean isValid = true;
                int[][] resultGrid = new int[n][m];

                // Read input, validate constraints, and prepare output grid in a single pass
                for (int i = 0; i < n; i++) {
                    for (int j = 0; j < m; j++) {
                        long inputValue = reader.nextLong();
                        int limit = getLimit(i, j, n, m);
                        resultGrid[i][j] = limit;

                        if (inputValue > limit) {
                            isValid = false;
                        }
                    }
                }

                if (!isValid) {
                    out.println("NO");
                } else {
                    out.println("YES");
                    printGrid(out, resultGrid);
                }
            }
        } finally {
            out.flush();
        }
    }

    /**
     * Determines the maximum allowed value for a cell based on its position.
     *
     * @param row    Current row index
     * @param col    Current column index
     * @param rows   Total number of rows
     * @param cols   Total number of columns
     * @return       Limit value (2 for corners, 3 for edges, 4 for interior)
     */
    private static int getLimit(int row, int col, int rows, int cols) {
        boolean isCorner = (row == 0 && col == 0) || (row == 0 && col == cols - 1) ||
                           (row == rows - 1 && col == 0) || (row == rows - 1 && col == cols - 1);
        boolean isEdge = row == 0 || col == 0 || row == rows - 1 || col == cols - 1;

        if (isCorner) return CORNER_LIMIT;
        if (isEdge) return EDGE_LIMIT;
        return INTERIOR_LIMIT;
    }

    /**
     * Prints the 2D integer grid to the provided PrintWriter.
     *
     * @param out   PrintWriter for formatted output
     * @param grid  2D array representing the grid
     */
    private static void printGrid(PrintWriter out, int[][] grid) {
        for (int[] row : grid) {
            for (int value : row) {
                out.print(value + " ");
            }
            out.println();
        }
    }

    /**
     * Fast I/O helper class for efficient input reading.
     */
    static class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            String s = next();
            if (s == null) throw new RuntimeException("Unexpected end of input");
            return Integer.parseInt(s);
        }

        long nextLong() {
            String s = next();
            if (s == null) throw new RuntimeException("Unexpected end of input");
            return Long.parseLong(s);
        }

        double nextDouble() {
            String s = next();
            if (s == null) throw new RuntimeException("Unexpected end of input");
            return Double.parseDouble(s);
        }

        String nextLine() {
            String str = "";
            try {
                str = br.readLine();
            } catch (IOException e) {
                throw new RuntimeException("Error reading line", e);
            }
            return str;
        }
    }
}

