/**
 * Validates and transforms a matrix based on orthogonal neighbor counts.
 * For each cell, if the input value exceeds the number of valid neighbors,
 * the matrix is marked invalid. Otherwise, the cell value is replaced with
 * the calculated neighbor count.
 */
public class MatrixNeighborValidator {

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            String tToken = scanner.next();
            if (tToken != null) {
                int t = Integer.parseInt(tToken);
                while (t-- > 0) {
                    solve(scanner, out);
                }
            }
        } catch (Exception e) {
            // In production environments, replace with a proper logging framework
            System.err.println("An error occurred during execution: " + e.getMessage());
        } finally {
            out.flush();
        }
    }

    /**
     * Processes a single test case: reads dimensions and matrix values,
     * validates the condition, and prints the result.
     */
    private static void solve(FastScanner scanner, PrintWriter out) {
        int n = scanner.nextInt();
        int m = scanner.nextInt();

        boolean isValid = true;
        int[][] resultMatrix = new int[n][m];

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                int currentValue = scanner.nextInt();
                int neighborCount = calculateNeighborCount(i, j, n, m);

                if (neighborCount < currentValue) {
                    isValid = false;
                    resultMatrix[i][j] = currentValue;
                } else {
                    resultMatrix[i][j] = neighborCount;
                }
            }
        }

        if (isValid) {
            out.println("YES");
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    out.print(resultMatrix[i][j]);
                    if (j < m - 1) {
                        out.print(' ');
                    }
                }
                out.println();
            }
        } else {
            out.println("NO");
        }
    }

    /**
     * Calculates the number of valid orthogonal neighbors for a cell at (i, j)
     * in an n x m matrix. Neighbors are defined as cells directly above, below,
     * left, or right within bounds.
     */
    private static int calculateNeighborCount(int i, int j, int n, int m) {
        int count = 0;
        if (i > 0) count++;
        if (i < n - 1) count++;
        if (j > 0) count++;
        if (j < m - 1) count++;
        return count;
    }

    /**
     * A robust, maintainable fast input scanner.
     * Replaces the original byte-array based reader with standard Java I/O
     * to improve readability, safety, and maintainability while retaining
     * competitive programming performance characteristics.
     */
    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        public String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) {
                        return null;
                    }
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input stream", e);
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            String token = next();
            if (token == null) {
                throw new RuntimeException("Unexpected end of input");
            }
            return Integer.parseInt(token);
        }

        public long nextLong() {
            String token = next();
            if (token == null) {
                throw new RuntimeException("Unexpected end of input");
            }
            return Long.parseLong(token);
        }
    }
}

import java.util.Scanner;

/**
 * A solver for the matrix validation problem.
 * It reads a matrix, validates it against specific boundary constraints,
 * and prints a constructed matrix if valid.
 */
public class MatrixSolver {

    // Constants defining the constraints for different parts of the matrix
    private static final int MAX_VALUE = 4;
    private static final int CORNER_LIMIT = 2;
    private static final int EDGE_LIMIT = 3;

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        // Check if input exists to prevent exceptions
        if (scanner.hasNextInt()) {
            int testCases = scanner.nextInt();

            while (testCases-- > 0) {
                int rows = scanner.nextInt();
                int cols = scanner.nextInt();
                int[][] matrix = new int[rows][cols];

                // 1. Read Input
                // We must read the entire matrix to advance the scanner correctly
                // for the next test case, regardless of validation results.
                for (int i = 0; i < rows; i++) {
                    for (int j = 0; j < cols; j++) {
                        matrix[i][j] = scanner.nextInt();
                    }
                }

                // 2. Validate and Output
                if (isValidMatrix(matrix, rows, cols)) {
                    System.out.println("YES");
                    printConstructedMatrix(rows, cols);
                } else {
                    System.out.println("NO");
                }
            }
        }
        scanner.close();
    }

    /**
     * Validates the matrix based on the problem constraints:
     * - Interior elements must be <= 4
     * - Edge elements (non-corner) must be <= 3
     * - Corner elements must be <= 2
     */
    private static boolean isValidMatrix(int[][] matrix, int rows, int cols) {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                int limit = MAX_VALUE; // Default limit for interior cells

                // Determine if the cell is a corner or an edge
                boolean isCorner = (i == 0 || i == rows - 1) && (j == 0 || j == cols - 1);
                boolean isEdge = (i == 0 || i == rows - 1 || j == 0 || j == cols - 1);

                if (isCorner) {
                    limit = CORNER_LIMIT;
                } else if (isEdge) {
                    limit = EDGE_LIMIT;
                }

                if (matrix[i][j] > limit) {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Prints the constructed matrix based on the dimensions.
     * Logic:
     * - Corners: 2
     * - Edges: 3
     * - Interior: 4
     */
    private static void printConstructedMatrix(int rows, int cols) {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                int val = MAX_VALUE;

                // Decrement value if on top/bottom edge
                if (i == 0 || i == rows - 1) {
                    val--;
                }
                // Decrement value if on left/right edge
                if (j == 0 || j == cols - 1) {
                    val--;
                }

                System.out.print(val + " ");
            }
            System.out.println();
        }
    }
}

import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.InputMismatchException;

public class Main {
    private static final String OUTPUT_YES = "YES";
    private static final String OUTPUT_NO = "NO";
    private static final String TIMER_SUFFIX = "ms";
    private static final String TEST_INPUT = ""; // Set this to test with custom input

    public static void main(String[] args) throws Exception {
        new Main().run();
    }

    private void run() throws Exception {
        InputStream inputStream = TEST_INPUT.isEmpty() ? System.in : new ByteArrayInputStream(TEST_INPUT.getBytes());
        FastScanner scanner = new FastScanner(inputStream);
        PrintWriter out = new PrintWriter(System.out);

        long startTime = System.currentTimeMillis();
        try {
            solve(scanner, out);
        } finally {
            out.flush();
        }

        if (!TEST_INPUT.isEmpty()) {
            System.out.println((System.currentTimeMillis() - startTime) + TIMER_SUFFIX);
        }
    }

    private void solve(FastScanner scanner, PrintWriter out) {
        int testCases = scanner.nextInt();
        for (int t = 0; t < testCases; t++) {
            int n = scanner.nextInt();
            int m = scanner.nextInt();
            int[][] grid = readGrid(scanner, n, m);
            int[][] ideal = computeIdealMatrix(n, m);
            boolean possible = checkFeasibility(grid, ideal);

            if (possible) {
                out.println(OUTPUT_YES);
                printMatrix(out, ideal);
            } else {
                out.println(OUTPUT_NO);
            }
        }
    }

    private int[][] readGrid(FastScanner scanner, int n, int m) {
        int[][] grid = new int[n][m];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                grid[i][j] = scanner.nextInt();
            }
        }
        return grid;
    }

    private int[][] computeIdealMatrix(int n, int m) {
        int[][] ideal = new int[n][m];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                ideal[i][j] = countValidNeighbors(i, j, n, m);
            }
        }
        return ideal;
    }

    private int countValidNeighbors(int row, int col, int n, int m) {
        int count = 0;
        if (row > 0) count++;
        if (col > 0) count++;
        if (row < n - 1) count++;
        if (col < m - 1) count++;
        return count;
    }

    private boolean checkFeasibility(int[][] grid, int[][] ideal) {
        int n = grid.length;
        int m = grid[0].length;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (ideal[i][j] < grid[i][j]) {
                    return false;
                }
            }
        }
        return true;
    }

    private void printMatrix(PrintWriter out, int[][] matrix) {
        for (int[] row : matrix) {
            for (int value : row) {
                out.print(value + " ");
            }
            out.println();
        }
    }

    /**
     * FastScanner for efficient competitive programming style input reading.
     */
    private static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1024];
        private int ptr = 0;
        private int buflen = 0;

        public FastScanner(InputStream in) {
            this.in = in;
        }

        private byte readByte() {
            if (ptr >= buflen) {
                ptr = 0;
                try {
                    buflen = in.read(buffer);
                } catch (IOException e) {
                    throw new InputMismatchException(e);
                }
                if (buflen <= 0) {
                    return -1;
                }
            }
            return buffer[ptr++];
        }

        private boolean isSpaceChar(int c) {
            return c <= 32 || c > 126;
        }

        private int skip() {
            int b = readByte();
            while (b != -1 && !((b >= '0' && b <= '9') || b == '-')) {
                b = readByte();
            }
            return b;
        }

        public int nextInt() {
            int b = skip();
            if (b == -1) {
                throw new InputMismatchException();
            }
            boolean isNegative = (b == '-');
            if (isNegative) {
                b = readByte();
            }
            int num = 0;
            while (b != -1 && b >= '0' && b <= '9') {
                num = num * 10 + (b - '0');
                b = readByte();
            }
            return isNegative ? -num : num;
        }

        public long nextLong() {
            int b = skip();
            if (b == -1) {
                throw new InputMismatchException();
            }
            boolean isNegative = (b == '-');
            if (isNegative) {
                b = readByte();
            }
            long num = 0;
            while (b != -1 && b >= '0' && b <= '9') {
                num = num * 10 + (b - '0');
                b = readByte();
            }
            return isNegative ? -num : num;
        }
    }
}

