    }

    /**
     * Validates the matrix constraints and modifies values in-place.
     * Returns true if all constraints are met, false otherwise.
     */
    private static boolean validateAndTransformMatrix(int[][] matrix, int rows, int cols) {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                int value = matrix[r][c];

                if (isCorner(r, c, rows, cols)) {
                    if (value < CORNER_THRESHOLD) {
                        matrix[r][c] = CORNER_VALUE;
                    } else {
                        return false;
                    }
                } else if (isEdge(r, c, rows, cols)) {
                    if (value < EDGE_THRESHOLD) {
                        matrix[r][c] = EDGE_VALUE;
                    } else {
                        return false;
                    }
                } else {
                    // Inner cell
                    if (value < INNER_THRESHOLD) {
                        matrix[r][c] = INNER_VALUE;
                    } else {
                        return false;
                    }
                }
            }
        }
        return true;
    }

    /**
     * Checks if a cell is a corner of the matrix.
     */
    private static boolean isCorner(int r, int c, int rows, int cols) {
        return (r == 0 || r == rows - 1) && (c == 0 || c == cols - 1);
    }

    /**
     * Checks if a cell is on the edge of the matrix (excluding corners).
     */
    private static boolean isEdge(int r, int c, int rows, int cols) {
        return r == 0 || r == rows - 1 || c == 0 || c == cols - 1;
    }

    /**
     * Prints the matrix to standard output.
     */
    private static void printMatrix(int[][] matrix) {
        StringBuilder sb = new StringBuilder();
        for (int[] row : matrix) {
            for (int val : row) {
                sb.append(val).append(" ");
            }
            sb.append("\n");
        }
        System.out.print(sb.toString());
    }
}

import java.io.BufferedReader;
import java.io.IOException;
