import java.util.StringTokenizer;

/**
 * Refactored solution for grid validation and transformation.
 * 
 * Improvements made:
 * - Removed unused imports, static fields, and local variables.
 * - Replaced magic numbers with clearly named constants.
 * - Extracted per-test-case logic into a dedicated 'solve' method.
 * - Improved FastScanner with proper null/exception handling and removed unused methods.
 * - Applied try-with-resources for automatic and safe resource cleanup.
 * - Enhanced variable naming, indentation, and added JavaDoc comments.
 */
public class Main {

    // Constants representing the required grid values
    private static final int CORNER_VALUE = 2;
    private static final int EDGE_VALUE = 3;
    private static final int INTERIOR_VALUE = 4;
    private static final int MAX_ALLOWED_VALUE = 4;

    public static void main(String[] args) {
        FastScanner sc = new FastScanner();
        // PrintWriter is closed automatically via try-with-resources, which also flushes the buffer
        try (PrintWriter out = new PrintWriter(System.out)) {
            int testCases = sc.nextInt();
            while (testCases-- > 0) {
                solve(sc, out);
            }
        }
    }

    /**
     * Processes a single test case: reads the grid, validates constraints,
     * constructs the required pattern, and prints the result.
     */
    private static void solve(FastScanner sc, PrintWriter out) {
        int n = sc.nextInt();
        int m = sc.nextInt();
        int[][] grid = new int[n][m];
        int maxVal = 0;

        // Read the grid and track the maximum value encountered
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                grid[i][j] = sc.nextInt();
                if (grid[i][j] > maxVal) {
                    maxVal = grid[i][j];
                }
            }
        }

        // Initial validation: global max constraint and corner constraints
        if (maxVal > MAX_ALLOWED_VALUE ||
            grid[0][0] > CORNER_VALUE || grid[0][m - 1] > CORNER_VALUE ||
            grid[n - 1][0] > CORNER_VALUE || grid[n - 1][m - 1] > CORNER_VALUE) {
            out.println("NO");
            return;
        }

        // Set corners to the required value
        grid[0][0] = CORNER_VALUE;
        grid[0][m - 1] = CORNER_VALUE;
        grid[n - 1][0] = CORNER_VALUE;
        grid[n - 1][m - 1] = CORNER_VALUE;

        // Validate and set top and bottom edges
        for (int j = 1; j < m - 1; j++) {
            if (grid[0][j] > EDGE_VALUE || grid[n - 1][j] > EDGE_VALUE) {
                out.println("NO");
                return;
            }
            grid[0][j] = EDGE_VALUE;
            grid[n - 1][j] = EDGE_VALUE;
        }

        // Validate and set left and right edges
        for (int i = 1; i < n - 1; i++) {
            if (grid[i][0] > EDGE_VALUE || grid[i][m - 1] > EDGE_VALUE) {
                out.println("NO");
                return;
            }
            grid[i][0] = EDGE_VALUE;
            grid[i][m - 1] = EDGE_VALUE;
        }

        // Fill interior with the required value
        for (int i = 1; i < n - 1; i++) {
            for (int j = 1; j < m - 1; j++) {
                grid[i][j] = INTERIOR_VALUE;
            }
        }

        // Output result
        out.println("YES");
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                out.print(grid[i][j]);
                out.print(j == m - 1 ? "" : " ");
            }
            out.println();
        }
    }

    /**
     * Fast input reader optimized for competitive programming style problems.
     * Handles tokenization and buffering efficiently.
     */
    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) {
                        return null;
                    }
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input", e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            String s = next();
            if (s == null) {
                throw new RuntimeException("Unexpected end of input");
            }
            return Integer.parseInt(s);
        }
    }
}

import java.io.BufferedReader;
