public class Main {
    public static void main(String[] args) {
        InputReader in = new InputReader(System.in);
        PrintWriter out = new PrintWriter(System.out);
        try {
            NeighborGrid solver = new NeighborGrid();
            solver.solve(in, out);
        } finally {
            out.close();
        }
    }

    /**
     * Handles grid validation, transformation, and output for each test case.
     */
    static class NeighborGrid {
        // Named constants replace magic numbers for clarity
        private static final int MAX_CORNER_VALUE = 2;
        private static final int MAX_EDGE_VALUE = 3;
        private static final int MAX_INNER_VALUE = 4;

        public void solve(InputReader in, PrintWriter out) {
            int testCases = in.nextInt();
            for (int t = 0; t < testCases; t++) {
                int n = in.nextInt();
                int m = in.nextInt();
                int[][] grid = readGrid(in, n, m);

                // Validation and transformation are encapsulated.
                // Returns false if constraints are violated, printing "NO".
                if (!validateAndTransformGrid(grid, n, m, out)) {
                    continue;
                }
                printGrid(grid, n, m, out);
            }
        }

        private int[][] readGrid(InputReader in, int n, int m) {
            int[][] grid = new int[n][m];
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    grid[i][j] = in.nextInt();
                }
            }
            return grid;
        }

        private boolean validateAndTransformGrid(int[][] grid, int n, int m, PrintWriter out) {
            // 1. Validate and set corners
            if (grid[0][0] > MAX_CORNER_VALUE || grid[n - 1][m - 1] > MAX_CORNER_VALUE ||
                grid[0][m - 1] > MAX_CORNER_VALUE || grid[n - 1][0] > MAX_CORNER_VALUE) {
                out.println("NO");
                return false;
            }
            grid[0][0] = MAX_CORNER_VALUE;
            grid[n - 1][m - 1] = MAX_CORNER_VALUE;
            grid[0][m - 1] = MAX_CORNER_VALUE;
            grid[n - 1][0] = MAX_CORNER_VALUE;

            // 2. Validate and set left/right edges
            for (int i = 1; i < n - 1; i++) {
                if (grid[i][0] > MAX_EDGE_VALUE || grid[i][m - 1] > MAX_EDGE_VALUE) {
                    out.println("NO");
                    return false;
                }
                grid[i][0] = MAX_EDGE_VALUE;
                grid[i][m - 1] = MAX_EDGE_VALUE;
            }

            // 3. Validate and set top/bottom edges
            for (int j = 1; j < m - 1; j++) {
                if (grid[0][j] > MAX_EDGE_VALUE || grid[n - 1][j] > MAX_EDGE_VALUE) {
                    out.println("NO");
                    return false;
                }
                grid[0][j] = MAX_EDGE_VALUE;
                grid[n - 1][j] = MAX_EDGE_VALUE;
            }

            // 4. Validate and set inner cells
            for (int i = 1; i < n - 1; i++) {
                for (int j = 1; j < m - 1; j++) {
                    if (grid[i][j] > MAX_INNER_VALUE) {
                        out.println("NO");
                        return false;
                    }
                    grid[i][j] = MAX_INNER_VALUE;
                }
            }

            out.println("YES");
            return true;
        }

        private void printGrid(int[][] grid, int n, int m, PrintWriter out) {
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    out.println(grid[i][j]);
                }
            }
        }
    }

    /**
     * Fast input reader for competitive programming style inputs.
     */
    static class InputReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public InputReader(InputStream stream) {
            this.reader = new BufferedReader(new InputStreamReader(stream), 32768);
            this.tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) {
                        return null;
                    }
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            String s = next();
            if (s == null) {
                throw new RuntimeException("Unexpected end of input");
            }
            return Integer.parseInt(s);
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

public class Codeforces {

    // Constants representing the maximum allowed values for each position type
    // This replaces the magic numbers 2, 3, and 4 found in the original logic
    private static final int CORNER_LIMIT = 2;
    private static final int SIDE_LIMIT = 3;
    private static final int MIDDLE_LIMIT = 4;

    public static void main(String[] args) throws IOException {
        // Use BufferedReader for efficient input reading
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        StringBuilder output = new StringBuilder();

        // Read number of test cases
        String line = reader.readLine();
        if (line == null) return;
        int t = Integer.parseInt(line.trim());

        while (t-- > 0) {
            // Read n (rows) and m (columns)
            // Using StringTokenizer is safer and more robust than split(" ") 
            // as it handles multiple whitespace characters gracefully.
            StringTokenizer st = new StringTokenizer(reader.readLine());
            int rows = Integer.parseInt(st.nextToken());
            int cols = Integer.parseInt(st.nextToken());

            int[][] matrix = new int[rows][cols];
            boolean isValid = true;

            // Process each row
            for (int r = 0; r < rows; r++) {
                String rowLine = reader.readLine();
                // Basic safety check for end of input
                if (rowLine == null) break;

                st = new StringTokenizer(rowLine);

                for (int c = 0; c < cols; c++) {
                    if (st.hasMoreTokens()) {
                        matrix[r][c] = Integer.parseInt(st.nextToken());
                    } else {
                        // Fallback if input is malformed, though CP inputs are usually valid
                        matrix[r][c] = 0;
                    }

                    // Determine the limit based on position
                    int maxAllowed = getLimitForPosition(r, c, rows, cols);

                    // Check validity: if original value exceeds limit, mark as invalid
                    if (matrix[r][c] > maxAllowed) {
                        isValid = false;
                    }

                    // Apply the limit (overwrite the value), matching original behavior
                    matrix[r][c] = maxAllowed;
                }
            }

            // Output results
            if (!isValid) {
                output.append("NO\n");
            } else {
                output.append("YES\n");
                for (int r = 0; r < rows; r++) {
                    for (int c = 0; c < cols; c++) {
                        output.append(matrix[r][c]).append(" ");
                    }
                    output.append("\n");
                }
            }
        }

        System.out.print(output);
    }

    /**
     * Determines the maximum allowed value for a cell based on its position.
     * 
     * Logic consolidation of original 'corner', 'side', and 'middle' methods:
     * - Corners (0,0), (0,m-1), (n-1,0), (n-1,m-1) allow max 2.
     * - Sides (edges but not corners) allow max 3.
     * - Middle (interior) cells allow max 4.
     */
    private static int getLimitForPosition(int r, int c, int rows, int cols) {
        boolean isTopOrBottom = (r == 0 || r == rows - 1);
        boolean isLeftOrRight = (c == 0 || c == cols - 1);

        // Check for corners (intersection of boundaries)
        if (isTopOrBottom && isLeftOrRight) {
            return CORNER_LIMIT;
        }

        // Check for sides (on a boundary but not a corner)
        if (isTopOrBottom || isLeftOrRight) {
            return SIDE_LIMIT;
        }

        // Default to middle (interior)
        return MIDDLE_LIMIT;
    }
}

import java.util.Scanner;

/**
 * Processes a 2D grid according to specific validation and transformation rules.
 * Validates that corner values do not exceed 2, edge values do not exceed 3,
 * and interior values do not exceed 4. If valid, transforms the grid and prints it.
 */
public class GridProcessor {

    // Named constants replace magic numbers for clarity and maintainability
    private static final int CORNER_VALUE = 2;
    private static final int EDGE_VALUE = 3;
    private static final int INTERIOR_VALUE = 4;

    public static void main(String[] args) {
        // Use try-with-resources to ensure the Scanner is properly closed
        try (Scanner scanner = new Scanner(System.in)) {
            if (scanner.hasNextInt()) {
                int testCases = scanner.nextInt();
                for (int i = 0; i < testCases; i++) {
                    processTestCase(scanner);
                }
            }
        }
    }

    /**
     * Reads grid dimensions and values, validates constraints, and outputs the result.
     */
    private static void processTestCase(Scanner scanner) {
        int rows = scanner.nextInt();
        int cols = scanner.nextInt();
        int[][] grid = new int[rows][cols];

        // Read the grid data
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                grid[i][j] = scanner.nextInt();
            }
        }

        // Validate and transform the grid
        if (validateAndModifyGrid(grid)) {
            System.out.println("YES");
            printGrid(grid);
        } else {
            System.out.println("NO");
        }
    }

    /**
     * Validates grid constraints and modifies values in-place.
     * Returns true if all constraints are met, false otherwise.
     */
    private static boolean validateAndModifyGrid(int[][] grid) {
        int rows = grid.length;
        int cols = grid[0].length;

        // Validate and set corners
        if (grid[0][0] > CORNER_VALUE || grid[0][cols - 1] > CORNER_VALUE ||
            grid[rows - 1][0] > CORNER_VALUE || grid[rows - 1][cols - 1] > CORNER_VALUE) {
            return false;
        }
        grid[0][0] = CORNER_VALUE;
        grid[0][cols - 1] = CORNER_VALUE;
        grid[rows - 1][0] = CORNER_VALUE;
        grid[rows - 1][cols - 1] = CORNER_VALUE;

        // Validate and set top/bottom edges
        for (int j = 1; j < cols - 1; j++) {
            if (grid[0][j] > EDGE_VALUE || grid[rows - 1][j] > EDGE_VALUE) {
                return false;
            }
            grid[0][j] = EDGE_VALUE;
            grid[rows - 1][j] = EDGE_VALUE;
        }

        // Validate and set left/right edges
        for (int i = 1; i < rows - 1; i++) {
            if (grid[i][0] > EDGE_VALUE || grid[i][cols - 1] > EDGE_VALUE) {
                return false;
            }
            grid[i][0] = EDGE_VALUE;
            grid[i][cols - 1] = EDGE_VALUE;
        }

        // Validate and set interior cells
        for (int i = 1; i < rows - 1; i++) {
            for (int j = 1; j < cols - 1; j++) {
                if (grid[i][j] > INTERIOR_VALUE) {
                    return false;
                }
                grid[i][j] = INTERIOR_VALUE;
            }
        }

        return true;
    }

    /**
     * Prints the transformed grid to standard output.
     */
    private static void printGrid(int[][] grid) {
        for (int[] row : grid) {
            for (int value : row) {
                System.out.print(value + " ");
            }
            System.out.println();
        }
    }
}

import java.io.BufferedReader;
import java.io.FileReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

public class Solution {
    // Grid constraint limits
    private static final int CORNER_LIMIT = 2;
    private static final int EDGE_LIMIT = 3;
    private static final int INTERIOR_LIMIT = 4;

    public static void main(String[] args) throws IOException {
        try (FastScanner sc = new FastScanner()) {
            String tStr = sc.next();
            if (tStr == null) return;
            int t = Integer.parseInt(tStr);
            StringBuilder output = new StringBuilder();

            while (t-- > 0) {
                int n = sc.nextInt();
                int m = sc.nextInt();
                int[][] grid = new int[n][m];
                boolean hasPositive = false;

                // Read grid and track if any positive value exists
                for (int i = 0; i < n; i++) {
                    for (int j = 0; j < m; j++) {
                        grid[i][j] = sc.nextInt();
                        if (grid[i][j] > 0) {
                            hasPositive = true;
                        }
                    }
                }

                if (!hasPositive) {
                    output.append("YES\n");
                    appendGrid(output, grid);
                } else {
                    if (validateAndModifyGrid(grid, n, m)) {
                        output.append("YES\n");
                        appendGrid(output, grid);
                    } else {
                        output.append("NO\n");
                    }
                }
            }
            System.out.print(output);
        }
    }

    /**
     * Formats and appends the grid to the provided StringBuilder.
     */
    private static void appendGrid(StringBuilder sb, int[][] grid) {
        for (int[] row : grid) {
            for (int val : row) {
                sb.append(val).append(" ");
            }
            sb.append("\n");
        }
    }

    /**
     * Validates grid constraints and modifies values in-place if valid.
     * Returns false if any constraint is violated.
     */
    private static boolean validateAndModifyGrid(int[][] grid, int n, int m) {
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                int limit;
                if (isCorner(i, j, n, m)) {
                    limit = CORNER_LIMIT;
                } else if (isEdge(i, j, n, m)) {
                    limit = EDGE_LIMIT;
                } else {
                    limit = INTERIOR_LIMIT;
                }

                if (grid[i][j] > limit) {
                    return false;
                }
                grid[i][j] = limit;
            }
        }
        return true;
    }

    private static boolean isCorner(int i, int j, int n, int m) {
        return (i == 0 || i == n - 1) && (j == 0 || j == m - 1);
    }

    private static boolean isEdge(int i, int j, int n, int m) {
        return i == 0 || i == n - 1 || j == 0 || j == m - 1;
    }

    /**
     * Modern, maintainable fast I/O scanner.
     */
    static class FastScanner implements AutoCloseable {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner() {
            this.br = new BufferedReader(new InputStreamReader(System.in));
        }

        public FastScanner(String fileName) throws IOException {
            this.br = new BufferedReader(new FileReader(fileName));
        }

        public String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }

        public double nextDouble() {
            return Double.parseDouble(next());
        }

        @Override
        public void close() throws IOException {
            br.close();
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

public class Main {
    // Named constants replace magic numbers for better readability and maintainability
    private static final int CORNER_LIMIT = 2;
    private static final int CORNER_VALUE = 2;
    private static final int EDGE_LIMIT = 3;
    private static final int EDGE_VALUE = 3;
    private static final int INTERIOR_LIMIT = 4;
    private static final int INTERIOR_VALUE = 4;

    private static FastScanner scn;
    private static StringBuilder ans;

    public static void main(String[] args) {
        scn = new FastScanner();
        ans = new StringBuilder();

        int t = scn.nextInt();
        for (int i = 1; i <= t; i++) {
            solve();
        }
        System.out.print(ans);
    }

    /**
     * Solves a single test case.
     * Reads a matrix, validates constraints based on cell position,
     * transforms values, and outputs the result.
     */
    private static void solve() {
        int n = scn.nextInt();
        int m = scn.nextInt();

        int[][] matrix = new int[n][m];
        for (int i = 0; i < n; i++) {
            matrix[i] = scn.nextIntArray(m);
        }

        boolean possible = true;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                int limit;
                int value;

                // Determine position category and corresponding limits/values
                if (isCorner(i, j, n, m)) {
                    limit = CORNER_LIMIT;
                    value = CORNER_VALUE;
                } else if (isEdge(i, j, n, m)) {
                    limit = EDGE_LIMIT;
                    value = EDGE_VALUE;
                } else {
                    limit = INTERIOR_LIMIT;
                    value = INTERIOR_VALUE;
                }

                // Validate constraint
                if (matrix[i][j] > limit) {
                    possible = false;
                    break;
                }

                // Apply transformation
                matrix[i][j] = value;
            }
            if (!possible) {
                break;
            }
        }

        if (possible) {
            print("YES\n");
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    // Avoid trailing spaces for cleaner output
                    print(matrix[i][j] + (j < m - 1 ? " " : ""));
                }
                print("\n");
            }
        } else {
            print("NO\n");
        }
    }

    /**
     * Checks if a cell is a corner of the matrix.
     */
    private static boolean isCorner(int i, int j, int n, int m) {
        return (i == 0 || i == n - 1) && (j == 0 || j == m - 1);
    }

    /**
     * Checks if a cell is on the edge (but not a corner) of the matrix.
     */
    private static boolean isEdge(int i, int j, int n, int m) {
        return i == 0 || i == n - 1 || j == 0 || j == m - 1;
    }

    /**
     * Appends an object's string representation to the output buffer.
     */
    private static void print(Object obj) {
        ans.append(obj.toString());
    }

    /**
     * Fast I/O helper class to replace java.util.Scanner for performance.
     */
    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Input stream error", e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        long nextLong() {
            return Long.parseLong(next());
        }

        double nextDouble() {
            return Double.parseDouble(next());
        }

        int[] nextIntArray(int n) {
            int[] arr = new int[n];
            for (int i = 0; i < n; i++) {
                arr[i] = nextInt();
            }
            return arr;
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

public class Question2 {

    // Named constants replace magic numbers for better readability and maintainability
    private static final int INNER_VALUE = 4;
    private static final int EDGE_VALUE = 3;
    private static final int CORNER_VALUE = 2;

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner();
        PrintWriter out = new PrintWriter(System.out);

        try {
            if (scanner.hasNext()) {
                int testCases = scanner.nextInt();
                while (testCases-- > 0) {
                    solve(scanner, out);
                }
            }
        } catch (Exception e) {
            e.printStackTrace();
        } finally {
            out.flush();
        }
    }

    /**
     * Processes a single test case.
     * Reads dimensions, constructs the target matrix, validates input against it,
     * and prints the result.
     */
    private static void solve(FastScanner scanner, PrintWriter out) {
        int n = scanner.nextInt();
        int m = scanner.nextInt();

        int[][] matrix = buildMatrix(n, m);
        boolean isPossible = true;

        // Read input values and validate against the constructed matrix
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                int inputVal = scanner.nextInt();
                if (inputVal > matrix[i][j]) {
                    isPossible = false;
                }
            }
        }

        if (!isPossible) {
            out.println("NO");
        } else {
            out.println("YES");
            printMatrix(matrix, out);
        }
    }

    /**
     * Constructs the n x m matrix according to the problem rules:
     * - Corners: 2
     * - Edges: 3
     * - Inner cells: 4
     */
    private static int[][] buildMatrix(int n, int m) {
        int[][] matrix = new int[n][m];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                boolean isCorner = (i == 0 || i == n - 1) && (j == 0 || j == m - 1);
                boolean isEdge = i == 0 || i == n - 1 || j == 0 || j == m - 1;

                if (isCorner) {
                    matrix[i][j] = CORNER_VALUE;
                } else if (isEdge) {
                    matrix[i][j] = EDGE_VALUE;
                } else {
                    matrix[i][j] = INNER_VALUE;
                }
            }
        }
        return matrix;
    }

    /**
     * Prints the matrix to the output stream.
     */
    private static void printMatrix(int[][] matrix, PrintWriter out) {
        for (int[] row : matrix) {
            for (int val : row) {
                out.print(val + " ");
            }
            out.println();
        }
    }

    /**
     * A maintainable and standard fast I/O scanner using BufferedReader and StringTokenizer.
     * Replaces the low-level byte-buffer Reader for better readability, safety, and Java idiomatic usage.
     */
    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        boolean hasNext() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) {
                        return false;
                    }
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    return false;
                }
            }
            return true;
        }

        String next() {
            if (hasNext()) return st.nextToken();
            return null;
        }

        int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.util.Scanner;

public class Main {
    // Constants defining the validation limits for each cell type
    private static final int CORNER_LIMIT = 2;
    private static final int EDGE_LIMIT = 3;
    private static final int INNER_LIMIT = 4;

    // Constants defining the values to overwrite the grid with if valid
    private static final int CORNER_VALUE = 2;
    private static final int EDGE_VALUE = 3;
    private static final int INNER_VALUE = 4;

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        // Check if input exists to prevent exceptions on empty input
        if (scanner.hasNextInt()) {
            int testCases = scanner.nextInt();

            // Process each test case
            for (int t = 0; t < testCases; t++) {
                solveTestCase(scanner);
            }
        }
        scanner.close();
    }

    private static void solveTestCase(Scanner scanner) {
        int rows = scanner.nextInt();
        int cols = scanner.nextInt();
        int[][] grid = new int[rows][cols];

        // Read grid data
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                grid[i][j] = scanner.nextInt();
            }
        }

        // Validate the grid based on constraints
        if (isValid(grid, rows, cols)) {
            // Transform the grid if valid
            transformGrid(grid, rows, cols);

            System.out.println("YES");
            printGrid(grid, rows, cols);
        } else {
            System.out.println("NO");
        }
    }

    /**
     * Validates the grid against the problem constraints.
     * Corners must be <= 2.
     * Edges (non-corner) must be <= 3.
     * Inner cells must be <= 4.
     */
    private static boolean isValid(int[][] grid, int rows, int cols) {
        // Check Corners
        // Note: Assumes rows >= 1 and cols >= 1 based on typical problem constraints.
        if (grid[0][0] > CORNER_LIMIT) return false;
        if (grid[0][cols - 1] > CORNER_LIMIT) return false;
        if (grid[rows - 1][0] > CORNER_LIMIT) return false;
        if (grid[rows - 1][cols - 1] > CORNER_LIMIT) return false;

        // Check Vertical Edges (excluding corners)
        for (int i = 1; i < rows - 1; i++) {
            if (grid[i][0] > EDGE_LIMIT) return false;
            if (grid[i][cols - 1] > EDGE_LIMIT) return false;
        }

        // Check Horizontal Edges (excluding corners)
        for (int j = 1; j < cols - 1; j++) {
            if (grid[0][j] > EDGE_LIMIT) return false;
            if (grid[rows - 1][j] > EDGE_LIMIT) return false;
        }

        // Check Inner Cells
        for (int i = 1; i < rows - 1; i++) {
            for (int j = 1; j < cols - 1; j++) {
                if (grid[i][j] > INNER_LIMIT) return false;
            }
        }

        return true;
    }

    /**
     * Transforms the grid cells to their required values if the grid is valid.
     * Corners -> 2
     * Edges -> 3
     * Inner -> 4
     */
    private static void transformGrid(int[][] grid, int rows, int cols) {
        // Update Corners
        grid[0][0] = CORNER_VALUE;
        grid[0][cols - 1] = CORNER_VALUE;
        grid[rows - 1][0] = CORNER_VALUE;
        grid[rows - 1][cols - 1] = CORNER_VALUE;

        // Update Vertical Edges
        for (int i = 1; i < rows - 1; i++) {
            grid[i][0] = EDGE_VALUE;
            grid[i][cols - 1] = EDGE_VALUE;
        }

        // Update Horizontal Edges
        for (int j = 1; j < cols - 1; j++) {
            grid[0][j] = EDGE_VALUE;
            grid[rows - 1][j] = EDGE_VALUE;
        }

        // Update Inner Cells
        for (int i = 1; i < rows - 1; i++) {
            for (int j = 1; j < cols - 1; j++) {
                grid[i][j] = INNER_VALUE;
            }
        }
    }

    /**
     * Prints the grid to stdout in the specified format.
     */
    private static void printGrid(int[][] grid, int rows, int cols) {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                sb.append(grid[i][j]).append(" ");
            }
            sb.append("\n");
        }
        System.out.print(sb);
    }
}

