/**
 * Refactored version of the grid validation program.
 * 
 * Improvements made:
 * 1. Readability: Replaced magic numbers with named constants.
 * 2. Structure: Extracted logic into methods (Single Responsibility Principle).
 * 3. Control Flow: Removed the labeled 'continue' statement in favor of method returns.
 * 4. Naming: Used descriptive variable and method names.
 * 5. Logic: Simplified boundary checks using boolean flags.
 */
public class GridValidator {

    // Constants defining the maximum allowed values for different cell positions
    private static final int CORNER_LIMIT = 2;
    private static final int EDGE_LIMIT = 3;
    private static final int INTERIOR_LIMIT = 4;

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        StringBuilder output = new StringBuilder();

        // Read number of test cases
        if (scanner.hasNextInt()) {
            int testCases = scanner.nextInt();
            for (int t = 0; t < testCases; t++) {
                processTestCase(scanner, output);
            }
        }

        // Print all accumulated output at once
        System.out.print(output);
        scanner.close();
    }

    /**
     * Processes a single test case: reads the grid, validates constraints,
     * modifies values, and appends the result to the output buffer.
     */
    private static void processTestCase(Scanner scanner, StringBuilder output) {
        int rows = scanner.nextInt();
        int cols = scanner.nextInt();
        int[][] matrix = new int[rows][cols];

        // Read the matrix input
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                matrix[i][j] = scanner.nextInt();
            }
        }

        // Validate and normalize the matrix
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                int limit = getLimitForPosition(i, j, rows, cols);

                // If the current value exceeds the limit for its position, the case is invalid
                if (matrix[i][j] > limit) {
                    output.append("NO\n");
                    return; // Exit method to proceed to the next test case
                }

                // Update the value to the limit (as per original logic)
                matrix[i][j] = limit;
            }
        }

        // If the loop completes, the matrix is valid
        output.append("YES\n");
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                output.append(matrix[i][j]).append(" ");
            }
            output.append("\n");
        }
    }

    /**
     * Determines the maximum allowed value based on the cell's position in the grid.
     * 
     * @param row The current row index
     * @param col The current column index
     * @param totalRows Total number of rows
     * @param totalCols Total number of columns
     * @return The maximum allowed value (2 for corners, 3 for edges, 4 for interior)
     */
    private static int getLimitForPosition(int row, int col, int totalRows, int totalCols) {
        boolean isTopOrBottom = (row == 0 || row == totalRows - 1);
        boolean isLeftOrRight = (col == 0 || col == totalCols - 1);

        // Corners are intersection of top/bottom and left/right boundaries
        if (isTopOrBottom && isLeftOrRight) {
            return CORNER_LIMIT;
        }

        // Edges are on the boundary but not corners
        if (isTopOrBottom || isLeftOrRight) {
            return EDGE_LIMIT;
        }

        // Interior cells
        return INTERIOR_LIMIT;
    }
}

import java.io.*;
import java.util.*;

public class Main {
    // Direction vectors for moving up, down, left, right
    private static final int[] DX = {0, 0, -1, 1};
    private static final int[] DY = {1, -1, 0, 0};

    // Values for the transformed grid
    private static final int CORNER_VALUE = 2;
    private static final int EDGE_VALUE = 3;
    private static final int INTERIOR_VALUE = 4;

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner();
        PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out));

        int testCases = scanner.nextInt();
        while (testCases-- > 0) {
            solve(scanner, out);
        }

        out.flush();
        out.close();
    }

    private static void solve(FastScanner scanner, PrintWriter out) {
        int n = scanner.nextInt();
        int m = scanner.nextInt();
        long[][] matrix = new long[n][m];

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                matrix[i][j] = scanner.nextLong();
            }
        }

        if (!isValidGrid(matrix, n, m)) {
            out.println("NO");
            return;
        }

        out.println("YES");
        transformAndPrintGrid(matrix, n, m, out);
    }

    /**
     * Validates that every positive cell has at least as many safe neighbors 
     * as its value.
     */
    private static boolean isValidGrid(long[][] matrix, int n, int m) {
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (matrix[i][j] > 0) {
                    int safeNeighborCount = countSafeNeighbors(i, j, n, m);
                    if (matrix[i][j] > safeNeighborCount) {
                        return false;
                    }
                }
            }
        }
        return true;
    }

    private static int countSafeNeighbors(int row, int col, int n, int m) {
        int count = 0;
        for (int k = 0; k < 4; k++) {
            int newRow = row + DX[k];
            int newCol = col + DY[k];
            if (isWithinBounds(newRow, newCol, n, m)) {
                count++;
            }
        }
        return count;
    }

    private static boolean isWithinBounds(int row, int col, int n, int m) {
        return row >= 0 && row < n && col >= 0 && col < m;
    }

    /**
     * Transforms the grid based on position (corners, edges, interior)
     * and prints it row by row.
     */
    private static void transformAndPrintGrid(long[][] matrix, int n, int m, PrintWriter out) {
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (i == 0 || i == n - 1) {
                    if (j == 0 || j == m - 1) {
                        matrix[i][j] = CORNER_VALUE;
                    } else {
                        matrix[i][j] = EDGE_VALUE;
                    }
                } else if (j == 0 || j == m - 1) {
                    matrix[i][j] = EDGE_VALUE;
                } else {
                    matrix[i][j] = INTERIOR_VALUE;
                }
                out.print(matrix[i][j] + (j == m - 1 ? "" : " "));
            }
            out.println();
        }
    }

    /**
     * Fast I/O helper class for competitive programming.
     */
    static class FastScanner {
        BufferedReader br;
        StringTokenizer st;

        public FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) {
                        throw new EOFException();
                    }
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        long nextLong() {
            return Long.parseLong(next());
        }
    }
}

