public class Main {
    // Constants defining the maximum allowed values for different matrix regions
    private static final int INNER_LIMIT = 4;
    private static final int EDGE_LIMIT = 3;
    private static final int CORNER_LIMIT = 2;

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        // Check if input exists to prevent NoSuchElementException
        if (scanner.hasNextInt()) {
            int numTestCases = scanner.nextInt();

            while (numTestCases-- > 0) {
                int rows = scanner.nextInt();
                int cols = scanner.nextInt();

                int[][] matrix = new int[rows][cols];

                // Read matrix data
                for (int i = 0; i < rows; i++) {
                    for (int j = 0; j < cols; j++) {
                        if (scanner.hasNextInt()) {
                            matrix[i][j] = scanner.nextInt();
                        }
                    }
                }

                // Process and validate the matrix
                boolean isValid = validateAndModifyMatrix(matrix);

                // Output results
                if (isValid) {
                    System.out.println("YES");
                    printMatrix(matrix);
                } else {
                    System.out.println("NO");
                }
            }
        }
        scanner.close();
    }

    /**
     * Validates the matrix against position-based constraints and modifies valid cells.
     * Returns true if all cells meet the constraints, false otherwise.
     */
    private static boolean validateAndModifyMatrix(int[][] matrix) {
        int rows = matrix.length;
        if (rows == 0) return true;
        int cols = matrix[0].length;

        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                int limit = getLimitForPosition(i, j, rows, cols);

                // If the current value exceeds the limit for this position, the case is invalid
                if (matrix[i][j] > limit) {
                    return false;
                }

                // Modify the cell to the maximum allowed value if valid
                matrix[i][j] = limit;
            }
        }
        return true;
    }

    /**
     * Determines the maximum allowed value based on the cell's position (corner, edge, or inner).
     */
    private static int getLimitForPosition(int row, int col, int totalRows, int totalCols) {
        // Check if the cell is a corner
        boolean isCorner = (row == 0 || row == totalRows - 1) && 
                           (col == 0 || col == totalCols - 1);

        if (isCorner) {
            return CORNER_LIMIT;
        }

        // Check if the cell is on an edge (excluding corners)
        boolean isEdge = (row == 0 || row == totalRows - 1 || 
                          col == 0 || col == totalCols - 1);

        if (isEdge) {
            return EDGE_LIMIT;
        }

        // Otherwise, it is an inner cell
        return INNER_LIMIT;
    }

    /**
     * Prints the matrix to standard output efficiently.
     */
    private static void printMatrix(int[][] matrix) {
        StringBuilder sb = new StringBuilder();
        for (int[] row : matrix) {
            for (int value : row) {
                sb.append(value).append(" ");
            }
            sb.append("\n");
        }
        System.out.print(sb);
    }
}

