     * Updates matrix values to their respective limits.
     *
     * @param matrix The 2D array to process
     * @param rows   Number of rows
     * @param cols   Number of columns
     * @return true if all original values were within limits, false otherwise
     */
    private static boolean processMatrix(int[][] matrix, int rows, int cols) {
        boolean isValid = true;

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                int limit = getLimitForPosition(r, c, rows, cols);

                // Check if the current value exceeds the allowed limit
                if (matrix[r][c] > limit) {
                    isValid = false;
                }

                // Update the matrix value to the limit
                matrix[r][c] = limit;
            }
        }
        return isValid;
    }

    /**
     * Determines the maximum allowed value based on the cell's position.
     * Corners (0,0), (0, cols-1), (rows-1, 0), (rows-1, cols-1) -> 2
     * Edges (top/bottom rows or left/right cols, excluding corners) -> 3
     * Interior (everything else) -> 4
     */
    private static int getLimitForPosition(int row, int col, int rows, int cols) {
        boolean isTopOrBottom = (row == 0 || row == rows - 1);
        boolean isLeftOrRight = (col == 0 || col == cols - 1);

        if (isTopOrBottom && isLeftOrRight) {
            return CORNER_LIMIT;
        } else if (isTopOrBottom || isLeftOrRight) {
            return EDGE_LIMIT;
        } else {
            return INTERIOR_LIMIT;
        }
    }

