import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;

public class Task2 {

    // Constants defining the maximum allowed values for grid positions
    private static final int CORNER_LIMIT = 2;
    private static final int EDGE_LIMIT = 3;
    private static final int INTERIOR_LIMIT = 4;

    public static void main(String[] args) throws IOException {
        // Use try-with-resources for automatic and safe resource management
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            String line = br.readLine();
            if (line == null || line.trim().isEmpty()) {
                return;
            }

            int t = Integer.parseInt(line.trim());

            for (int test = 0; test < t; test++) {
                String rcLine = br.readLine();
                if (rcLine == null) break;

                String[] rc = rcLine.trim().split("\\s+");
                int rows = Integer.parseInt(rc[0]);
                int cols = Integer.parseInt(rc[1]);

                // Read the entire grid into memory first. 
                // This completely eliminates the error-prone "skip remaining lines" logic.
                int[][] grid = new int[rows][cols];
                for (int i = 0; i < rows; i++) {
                    String rowLine = br.readLine();
                    if (rowLine == null) break;
                    String[] row = rowLine.trim().split("\\s+");
                    for (int j = 0; j < cols; j++) {
                        grid[i][j] = Integer.parseInt(row[j]);
                    }
                }

                // Validate constraints and generate output
                if (validateGrid(grid)) {
                    System.out.println("YES");
                    System.out.println(buildOutputPattern(rows, cols));
                } else {
                    System.out.println("NO");
                }
            }
        }
    }

    /**
     * Validates the grid according to boundary constraints.
     * Corners must be <= CORNER_LIMIT, edges <= EDGE_LIMIT, interior <= INTERIOR_LIMIT.
     */
    private static boolean validateGrid(int[][] grid) {
        int rows = grid.length;
        int cols = grid[0].length;

        // Handle single-row case explicitly to avoid redundant checks
        if (rows == 1) {
            return validateBoundaryRow(grid[0], cols);
        }

        // Validate first row
        if (!validateBoundaryRow(grid[0], cols)) {
            return false;
        }

        // Validate middle rows
        for (int i = 1; i < rows - 1; i++) {
            if (!validateInteriorRow(grid[i], cols)) {
                return false;
            }
        }

        // Validate last row
        return validateBoundaryRow(grid[rows - 1], cols);
    }

    private static boolean validateBoundaryRow(int[] row, int cols) {
        // Check corners
        if (row[0] > CORNER_LIMIT || row[cols - 1] > CORNER_LIMIT) {
            return false;
        }
        // Check edges
        for (int j = 1; j < cols - 1; j++) {
            if (row[j] > EDGE_LIMIT) {
                return false;
            }
        }
        return true;
    }

    private static boolean validateInteriorRow(int[] row, int cols) {
        // Check edges
        if (row[0] > EDGE_LIMIT || row[cols - 1] > EDGE_LIMIT) {
            return false;
        }
        // Check interior
        for (int j = 1; j < cols - 1; j++) {
            if (row[j] > INTERIOR_LIMIT) {
                return false;
            }
        }
        return true;
    }

    /**
     * Constructs the expected output pattern based on grid dimensions.
     * The pattern is deterministic and independent of input values (as long as validation passes).
     */
    private static String buildOutputPattern(int rows, int cols) {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < rows; i++) {
            if (i == 0 || i == rows - 1) {
                sb.append("2 ");
                for (int j = 1; j < cols - 1; j++) {
