/**
 * Refactored solution for problem p1375B.
 * This class validates and modifies a 2D grid based on boundary constraints.
 * 
 * Improvements made:
 * 1. Readability: Descriptive variable names (e.g., 'rows', 'cols', 'isValid').
 * 2. Maintainability: Extracted magic numbers (2, 3, 4) into named constants.
 * 3. Structure: Separated logic into helper methods (processTestCase, getRegionLimit, printGrid).
 * 4. Performance: Used StringBuilder for output to reduce I/O overhead.
 * 5. DRY: Unified the validation and modification logic into a single pass over the grid.
 */
public class Main {

    // Constants defining the maximum allowed values for different grid regions
    private static final int CORNER_LIMIT = 2;
    private static final int EDGE_LIMIT = 3;
    private static final int INTERIOR_LIMIT = 4;

    public static void main(String[] args) {
        // Use Scanner for input reading. 
        // Note: For extremely large inputs, BufferedReader/StringTokenizer is preferred,
        // but Scanner is used here for readability consistent with standard practices.
        Scanner scanner = new Scanner(System.in);

        // Check if input exists to prevent NoSuchElementException
        if (scanner.hasNextInt()) {
            int t = scanner.nextInt(); // Number of test cases

            for (int i = 0; i < t; i++) {
                processTestCase(scanner);
            }
        }
        scanner.close();
    }

    /**
     * Reads and processes a single test case.
     */
    private static void processTestCase(Scanner scanner) {
        int rows = scanner.nextInt();
        int cols = scanner.nextInt();

        int[][] grid = new int[rows][cols];

        // Read the grid values
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                grid[r][c] = scanner.nextInt();
            }
        }

        boolean isValid = true;

        // Iterate through the grid to validate constraints and apply modifications
        // This replaces the multiple scattered loops in the original code
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                int limit = getRegionLimit(r, c, rows, cols);

                if (grid[r][c] > limit) {
                    isValid = false;
                    // Optimization: We could break here, but continuing ensures
                    // we don't leave the scanner in a weird state if we were reading on the fly.
                    // Since we read all input first, we can safely break, 
                    // but iterating is clean enough and safe.
                } else {
                    grid[r][c] = limit;
                }
            }
        }

        if (!isValid) {
            System.out.println("NO");
        } else {
            System.out.println("YES");
            printGrid(grid);
        }
    }

    /**
     * Determines the maximum allowed value for a cell based on its position.
     * 
     * @param r Current row index
     * @param c Current column index
     * @param rows Total number of rows
     * @param cols Total number of columns
     * @return The limit value for the specific region (Corner, Edge, or Interior)
     */
    private static int getRegionLimit(int r, int c, int rows, int cols) {
        // Check if cell is a corner
        boolean isCorner = (r == 0 || r == rows - 1) && (c == 0 || c == cols - 1);
        // Check if cell is on the edge (but not a corner)
        boolean isEdge = (r == 0 || r == rows - 1) || (c == 0 || c == cols - 1);

        if (isCorner) {
            return CORNER_LIMIT;
        } else if (isEdge) {
            return EDGE_LIMIT;
        } else {
            return INTERIOR_LIMIT;
        }
    }

    /**
     * Prints the 2D grid to standard output.
     * Uses StringBuilder for better performance than repeated System.out.print calls.
     */
    private static void printGrid(int[][] grid) {
        StringBuilder sb = new StringBuilder();
        for (int[] row : grid) {
            for (int val : row) {
                sb.append(val).append(" ");
            }
            sb.append("\n");
        }
        System.out.print(sb);
    }
}

