import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

public class Main {

    // Constants defining the maximum allowed values for different cell positions
    // Replacing magic numbers 2, 3, 4 with descriptive constants
    private static final int CORNER_LIMIT = 2;
    private static final int EDGE_LIMIT = 3;
    private static final int INTERIOR_LIMIT = 4;

    public static void main(String[] args) {
        // Encapsulate I/O logic for cleaner main method
        FastScanner scanner = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            // Read number of test cases
            String tStr = scanner.next();
            if (tStr != null) {
                int t = Integer.parseInt(tStr);
                while (t-- > 0) {
                    solve(scanner, out);
                }
            }
        } catch (Exception e) {
            // Handle potential parsing or IO errors gracefully
        } finally {
            out.flush();
        }
    }

    private static void solve(FastScanner scanner, PrintWriter out) {
        int n = scanner.nextInt();
        int m = scanner.nextInt();

        int[][] matrix = new int[n][m];
        boolean isValid = true;

        // Process the matrix in a single pass (O(N*M))
        // Original code read the matrix first, then iterated multiple times to check/modify.
        // This refactored version combines reading, validation, and modification.
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                int value = scanner.nextInt();

                // Determine the constraint limit for the current cell position
                int limit = getLimitForPosition(i, j, n, m);

                // Check validity: if input value exceeds the limit for this position
                if (value > limit) {
                    isValid = false;
                }

                // Store the value capped at the limit.
                // Note: The original code explicitly assigned the limit value 
                // (e.g., A[1][1]=2) regardless of whether the input was smaller.
                // We preserve this behavior.
                matrix[i][j] = limit; 
            }
        }

        if (isValid) {
            out.println("YES");
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    out.print(matrix[i][j]);
                    // Print space separator, avoiding trailing space at end of line for better formatting
                    if (j < m - 1) {
                        out.print(" ");
                    }
                }
                out.println();
            }
        } else {
            out.println("NO");
        }
    }

    /**
     * Determines the maximum allowed value for a cell at (row, col) in an n x m grid.
     * Uses 0-based indexing for standard Java array access.
     */
    private static int getLimitForPosition(int row, int col, int n, int m) {
        // Check if the cell is a corner
        // Corners are at (0,0), (0, m-1), (n-1, 0), (n-1, m-1)
        boolean isCorner = (row == 0 || row == n - 1) && (col == 0 || col == m - 1);

        // Check if the cell is on the edge (but not a corner)
        // Edges are the first/last row or first/last column
        boolean isEdge = (row == 0 || row == n - 1 || col == 0 || col == m - 1);

        if (isCorner) {
            return CORNER_LIMIT;
        } else if (isEdge) {
            return EDGE_LIMIT;
        } else {
            return INTERIOR_LIMIT;
        }
    }

    // Helper class for fast input reading
    static class FastScanner {
        BufferedReader br;
        StringTokenizer st;

        public FastScanner(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) {
                        return null;
                    }
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            String s = next();
            if (s == null) throw new RuntimeException("End of input");
            return Integer.parseInt(s);
        }
    }
}

