/**
 * Refactored version of the original grid validation and generation program.
 * 
 * Improvements made:
 * - Removed unnecessary 2D array allocation; processes input on-the-fly to reduce memory usage.
 * - Extracted magic numbers (2, 3, 4) into named constants for clarity.
 * - Encapsulated boundary detection logic into reusable, well-named helper methods.
 * - Simplified condition evaluation using a threshold-based approach.
 * - Improved variable naming, indentation, and overall structure for readability.
 * - Applied try-with-resources for proper Scanner management.
 */
public class Main {
    private static final int CORNER_THRESHOLD = 2;
    private static final int EDGE_THRESHOLD = 3;
    private static final int INNER_THRESHOLD = 4;

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            if (!scanner.hasNextInt()) {
                return;
            }

            int testCases = scanner.nextInt();
            for (int t = 0; t < testCases; t++) {
                int rows = scanner.nextInt();
                int cols = scanner.nextInt();

                if (isValidConfiguration(rows, cols, scanner)) {
                    System.out.println("YES");
                    printGeneratedGrid(rows, cols);
                } else {
                    System.out.println("NO");
                }
            }
        }
    }

    /**
     * Reads the grid values and validates them against position-specific thresholds.
     * Returns false if any value exceeds its allowed maximum, otherwise true.
     */
    private static boolean isValidConfiguration(int rows, int cols, Scanner scanner) {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                int value = scanner.nextInt();
                if (value > getMaxAllowed(rows, cols, i, j)) {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Determines the maximum allowed value for a cell based on its position.
     * Corners: <= 2, Edges: <= 3, Inner: <= 4
     */
    private static int getMaxAllowed(int rows, int cols, int row, int col) {
        if (row == 0 || row == rows - 1 || col == 0 || col == cols - 1) {
            // Check if the current cell is a corner
            if ((row == 0 || row == rows - 1) && (col == 0 || col == cols - 1)) {
                return CORNER_THRESHOLD;
            }
            return EDGE_THRESHOLD;
        }
        return INNER_THRESHOLD;
    }

    /**
     * Prints the generated grid according to the rules.
     * Corners: 2, Edges: 3, Inner: 4
     */
    private static void printGeneratedGrid(int rows, int cols) {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                System.out.print(getMaxAllowed(rows, cols, i, j) + " ");
            }
            System.out.println();
        }
    }
}

import java.io.*;
import java.util.*;

public class MatrixSolver {

    private static final int CORNER_VALUE = 2;
    private static final int EDGE_VALUE = 3;
    private static final int INTERIOR_VALUE = 4;

    public static void main(String[] args) throws IOException {
        // Use try-with-resources to ensure streams are properly closed
        try (FastReader in = new FastReader();
             PrintWriter out = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)))) {

            String numCasesStr = in.next();
            if (numCasesStr == null) {
                return;
            }
            int numCases = Integer.parseInt(numCasesStr);

            for (int caseNum = 0; caseNum < numCases; caseNum++) {
                int rows = in.nextInt();
                int cols = in.nextInt();

                int[][] matrix = new int[rows][cols];
                for (int i = 0; i < rows; i++) {
                    for (int j = 0; j < cols; j++) {
                        matrix[i][j] = in.nextInt();
                    }
                }

                if (isValidMatrix(matrix)) {
                    out.println("YES");
                    applySolutionPattern(matrix);
                    printMatrix(out, matrix);
                } else {
                    out.println("NO");
                }
            }
        }
    }

    /**
     * Validates that the matrix meets the problem constraints:
     * - Corner cells must be <= 2
     * - Edge cells (excluding corners) must be <= 3
     * - Interior cells must be <= 4
     */
    private static boolean isValidMatrix(int[][] matrix) {
        int rows = matrix.length;
        if (rows == 0) return false;
        int cols = matrix[0].length;
        if (cols == 0) return false;

        // Validate corners
        if (matrix[0][0] > CORNER_VALUE || matrix[rows - 1][0] > CORNER_VALUE ||
            matrix[0][cols - 1] > CORNER_VALUE || matrix[rows - 1][cols - 1] > CORNER_VALUE) {
            return false;
        }

        // Validate top and bottom edges (excluding corners)
        for (int j = 1; j < cols - 1; j++) {
            if (matrix[0][j] > EDGE_VALUE || matrix[rows - 1][j] > EDGE_VALUE) {
                return false;
            }
        }

        // Validate left and right edges (excluding corners)
        for (int i = 1; i < rows - 1; i++) {
            if (matrix[i][0] > EDGE_VALUE || matrix[i][cols - 1] > EDGE_VALUE) {
                return false;
            }
        }

        // Validate interior cells
        for (int i = 1; i < rows - 1; i++) {
            for (int j = 1; j < cols - 1; j++) {
                if (matrix[i][j] > INTERIOR_VALUE) {
                    return false;
                }
            }
        }

        return true;
    }

    /**
     * Overwrites the matrix with the canonical solution pattern.
     * Note: This method mutates the input matrix in-place.
     */
    private static void applySolutionPattern(int[][] matrix) {
        int rows = matrix.length;
        int cols = matrix[0].length;

        // Set corners
        matrix[0][0] = CORNER_VALUE;
        matrix[rows - 1][0] = CORNER_VALUE;
        matrix[0][cols - 1] = CORNER_VALUE;
        matrix[rows - 1][cols - 1] = CORNER_VALUE;

        // Set left and right edges
        for (int i = 1; i < rows - 1; i++) {
            matrix[i][0] = EDGE_VALUE;
            matrix[i][cols - 1] = EDGE_VALUE;
        }

        // Set top and bottom edges
        for (int j = 1; j < cols - 1; j++) {
            matrix[0][j] = EDGE_VALUE;
            matrix[rows - 1][j] = EDGE_VALUE;
        }

        // Set interior using optimized array fill
        for (int i = 1; i < rows - 1; i++) {
            Arrays.fill(matrix[i], 1, cols - 1, INTERIOR_VALUE);
        }
    }

    /**
     * Formats and prints the matrix rows to the output writer.
     */
    private static void printMatrix(PrintWriter out, int[][] matrix) {
        for (int[] row : matrix) {
            StringBuilder sb = new StringBuilder();
            for (int i = 0; i < row.length; i++) {
                sb.append(row[i]);
                if (i < row.length - 1) {
                    sb.append(' ');
                }
            }
            out.println(sb);
        }
    }

    /**
     * Helper class for fast and robust input reading.
     */
    private static class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input", e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            String s = next();
            if (s == null) throw new NoSuchElementException("Unexpected end of input");
            return Integer.parseInt(s);
        }
    }
}

import java.util.Scanner;

/**
 * Refactored version of the CodeChef problem solver.
 * 
 * Improvements made:
 * 1. Removed global state (static n, m) to improve encapsulation.
 * 2. Extracted logic into distinct helper methods for readability (readGrid, processGrid, etc.).
 * 3. Renamed variables to be more descriptive (e.g., 'arr' -> 'grid', 'test' -> 'numTestCases').
 * 4. Used StringBuilder for output to improve performance.
 * 5. Removed redundant logic in the printing loop.
 * 6. Added comments to explain the logic.
 */
public class Codechef {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        // Check if input exists to prevent NoSuchElementException
        if (scanner.hasNextInt()) {
            int numTestCases = scanner.nextInt();
            while (numTestCases-- > 0) {
                int n = scanner.nextInt();
                int m = scanner.nextInt();

                int[][] grid = readGrid(scanner, n, m);

                if (processGrid(grid, n, m)) {
                    System.out.println("YES");
                    printGrid(grid);
                } else {
                    System.out.println("NO");
                }
            }
        }
        scanner.close();
    }

    /**
     * Reads the matrix dimensions and values from the scanner.
     */
    private static int[][] readGrid(Scanner scanner, int n, int m) {
        int[][] grid = new int[n][m];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                grid[i][j] = scanner.nextInt();
            }
        }
        return grid;
    }

    /**
     * Processes the grid to validate and adjust values according to the problem rules.
     * 
     * Logic:
     * 1. Iterate through each cell.
     * 2. If cell is 0, skip.
     * 3. Calculate sum of non-zero neighbors.
     * 4. If cell value < neighbor sum, update cell value to match sum.
     * 5. If cell value > neighbor sum, try to increment neighbors to reduce the excess.
     *    If neighbors cannot absorb the excess, the grid is invalid.
     */
    private static boolean processGrid(int[][] grid, int n, int m) {
        boolean isValid = true;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == 0) continue;

                int neighborSum = countNonZeroNeighbors(grid, i, j, n, m);
                int diff = grid[i][j] - neighborSum;

                if (diff == 0) {
                    continue;
                }

                if (diff < 0) {
                    // If value is less than neighbor count, increase value to match count
                    grid[i][j] = neighborSum;
                } else {
                    // If value is greater, try to increment neighbors to reduce the excess
                    // Note: This modifies the grid in place, potentially affecting subsequent checks
                    if (!distributeExcess(grid, diff, i, j, n, m)) {
                        isValid = false;
                        break;
                    }
                }
            }
            if (!isValid) break;
        }
        return isValid;
    }

    /**
     * Counts non-zero neighbors of a cell at (r, c).
     * Checks Up, Left, Down, Right.
     */
    private static int countNonZeroNeighbors(int[][] grid, int r, int c, int n, int m) {
        int count = 0;
        // Up
        if (r > 0 && grid[r - 1][c] != 0) count++;
        // Left
        if (c > 0 && grid[r][c - 1] != 0) count++;
        // Down
        if (r < n - 1 && grid[r + 1][c] != 0) count++;
        // Right
        if (c < m - 1 && grid[r][c + 1] != 0) count++;
        return count;
    }

    /**
     * Attempts to distribute excess value by incrementing neighboring zero cells.
     * Order of checking neighbors: Up, Left, Down, Right (matching original logic).
     * 
     * @return true if excess is fully distributed (becomes 0), false otherwise.
     */
    private static boolean distributeExcess(int[][] grid, int excess, int r, int c, int n, int m) {
        // Directions: Up, Left, Down, Right
        int[] dr = {-1, 0, 1, 0};
        int[] dc = {0, -1, 0, 1};

        for (int k = 0; k < 4 && excess > 0; k++) {
            int nr = r + dr[k];
            int nc = c + dc[k];

            // Check bounds and if cell is empty (0)
            if (nr >= 0 && nr < n && nc >= 0 && nc < m && grid[nr][nc] == 0) {
                grid[nr][nc]++;
                excess--;
            }
        }
        return excess == 0;
    }

    /**
     * Prints the grid to standard output.
     */
    private static void printGrid(int[][] grid) {
        StringBuilder sb = new StringBuilder();
        for (int[] row : grid) {
            for (int val : row) {
                sb.append(val).append(" ");
            }
            sb.append("\n");
        }
        System.out.print(sb);
    }
}

