import java.util.Scanner;

/**
 * Validates grid input against positional constraints and outputs a standardized pattern.
 * Refactored for maintainability, readability, and resource safety.
 */
public class GridPatternValidator {

    // Named constants replace magic numbers for clarity and easy maintenance
    private static final int MAX_ALLOWED_VALUE = 4;
    private static final int CORNER_VALUE = 2;
    private static final int EDGE_VALUE = 3;
    private static final int INTERIOR_VALUE = 4;

    public static void main(String[] args) {
        // try-with-resources ensures the Scanner is properly closed
        try (Scanner scanner = new Scanner(System.in)) {
            if (scanner.hasNextInt()) {
                int testCases = scanner.nextInt();
                for (int i = 0; i < testCases; i++) {
                    processTestCase(scanner);
                }
            }
        }
    }

    /**
     * Handles a single test case: reads dimensions, validates input, and prints result.
     */
    private static void processTestCase(Scanner scanner) {
        int rows = scanner.nextInt();
        int cols = scanner.nextInt();

        // Validate all cells while guaranteeing every input token is consumed
        boolean isValid = validateGridValues(rows, cols, scanner);

        if (isValid) {
            System.out.println("YES");
            printConstructedPattern(rows, cols);
        } else {
            System.out.println("NO");
        }
    }

    /**
     * Reads the entire grid and validates each cell against positional rules.
     * Continues reading even after a failure to prevent desynchronization with subsequent test cases.
     */
    private static boolean validateGridValues(int rows, int cols, Scanner scanner) {
        boolean isValid = true;
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                int value = scanner.nextInt();
                if (!isCellValid(i, j, rows, cols, value)) {
                    isValid = false;
                }
            }
        }
        return isValid;
    }

    /**
     * Checks if a cell's value respects the constraints for its position.
     * Corners <= 2, Edges <= 3, Interior <= 4.
     */
    private static boolean isCellValid(int row, int col, int rows, int cols, int value) {
        if (value > MAX_ALLOWED_VALUE) {
            return false;
        }

        boolean isCorner = (row == 0 || row == rows - 1) && (col == 0 || col == cols - 1);
        if (isCorner) {
            return value <= CORNER_VALUE;
        }

        boolean isEdge = row == 0 || row == rows - 1 || col == 0 || col == cols - 1;
        if (isEdge) {
            return value <= EDGE_VALUE;
        }

        // Interior cells only need to satisfy the global maximum check above
        return true;
    }

    /**
     * Prints the standardized output pattern using efficient string concatenation.
     */
    private static void printConstructedPattern(int rows, int cols) {
        StringBuilder output = new StringBuilder();
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                output.append(getPatternValue(i, j, rows, cols));
                if (j < cols - 1) {
                    output.append(' ');
                }
            }
            output.append('\n');
        }
        System.out.print(output);
    }

    /**
     * Determines the output value based on cell position for the standardized pattern.
     */
    private static int getPatternValue(int row, int col, int rows, int cols) {
        boolean isCorner = (row == 0 || row == rows - 1) && (col == 0 || col == cols - 1);
        if (isCorner) {
            return CORNER_VALUE;
        }

        boolean isEdge = row == 0 || row == rows - 1 || col == 0 || col == cols - 1;
        if (isEdge) {
            return EDGE_VALUE;
        }

        return INTERIOR_VALUE;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

/**
 * Processes grid matrices according to specific transformation and validation rules.
 * Interior cells must be <= 4, border cells <= 3, and corner cells <= 2.
 */
public class MatrixProcessor {

    // Transformation thresholds
    private static final int MAX_CORNER_VALUE = 2;
    private static final int MAX_BORDER_VALUE = 3;
    private static final int MAX_INTERIOR_VALUE = 4;

    public static void main(String[] args) throws Exception {
        new MatrixProcessor().run();
    }

    /**
     * Orchestrates the reading of test cases and delegates processing.
     */
    public void run() throws IOException {
        FastReader reader = new FastReader();
        String token = reader.next();
        if (token == null) return;

        int testCases = Integer.parseInt(token);
        for (int t = 0; t < testCases; t++) {
            processTestCase(reader);
        }
    }

    /**
     * Reads a single test case, validates/transforms the grid, and prints the result.
     */
    private void processTestCase(FastReader reader) throws IOException {
        int rows = reader.nextInt();
        int cols = reader.nextInt();
        int[][] grid = readGrid(reader, rows, cols);

        boolean isValid = transformAndValidateGrid(grid, rows, cols);

        if (isValid) {
            System.out.println("YES");
            printGrid(grid);
        } else {
            System.out.println("NO");
        }
    }

    /**
     * Reads the grid dimensions and populates the 2D array.
     */
    private int[][] readGrid(FastReader reader, int rows, int cols) {
        int[][] grid = new int[rows][cols];
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                grid[i][j] = reader.nextInt();
            }
        }
        return grid;
    }

    /**
     * Validates and transforms the grid according to position-based rules.
     * Returns true if all constraints are satisfied.
     */
    private boolean transformAndValidateGrid(int[][] grid, int rows, int cols) {
        boolean[][] visited = new boolean[rows][cols];
        boolean isValid = true;

        // 1. Interior cells (not on any border)
        for (int i = 1; i < rows - 1; i++) {
            for (int j = 1; j < cols - 1; j++) {
                if (grid[i][j] > MAX_INTERIOR_VALUE) {
                    isValid = false;
                }
                grid[i][j] = MAX_INTERIOR_VALUE;
                visited[i][j] = true;
            }
        }

        // 2. Corner cells
        int[][] corners = {{0, 0}, {0, cols - 1}, {rows - 1, cols - 1}, {rows - 1, 0}};
        for (int[] corner : corners) {
            int r = corner[0];
            int c = corner[1];
            if (grid[r][c] > MAX_CORNER_VALUE) {
                isValid = false;
            }
            grid[r][c] = MAX_CORNER_VALUE;
            visited[r][c] = true;
        }

        // 3. Remaining border cells
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (!visited[i][j]) {
                    if (grid[i][j] > MAX_BORDER_VALUE) {
                        isValid = false;
                    }
                    grid[i][j] = MAX_BORDER_VALUE;
                    visited[i][j] = true;
                }
            }
        }

        return isValid;
    }

    /**
     * Prints the transformed grid to standard output.
     */
    private void printGrid(int[][] grid) {
        StringBuilder sb = new StringBuilder();
        for (int[] row : grid) {
            for (int value : row) {
                sb.append(value).append(' ');
            }
            sb.append('\n');
        }
        System.out.print(sb);
    }

    /**
     * Optimized input reader for fast I/O operations.
     */
    static class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input", e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            String s = next();
            if (s == null) throw new RuntimeException("Unexpected end of input");
            return Integer.parseInt(s);
        }
    }
}

import java.util.Scanner;

/**
 * Validates a grid based on neighbor count constraints and outputs the neighbor configuration.
 * Refactored for improved maintainability, memory efficiency, and code clarity.
 */
public class NeighborGrid {
    private static final int INTERIOR_NEIGHBORS = 4;
    private static final int EDGE_NEIGHBORS = 3;
    private static final int CORNER_NEIGHBORS = 2;

    public static void main(String[] args) {
        // Use try-with-resources to automatically close the scanner
        try (Scanner scanner = new Scanner(System.in)) {
            if (scanner.hasNextInt()) {
                int numTestCases = scanner.nextInt();
                // Process each test case on-the-fly to save memory
                for (int i = 0; i < numTestCases; i++) {
                    int rows = scanner.nextInt();
                    int cols = scanner.nextInt();
                    int[][] grid = readGrid(scanner, rows, cols);
                    processTestCase(grid);
                }
            }
        }
    }

    /**
     * Reads the grid dimensions and values from the scanner.
     */
    private static int[][] readGrid(Scanner scanner, int rows, int cols) {
        int[][] grid = new int[rows][cols];
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                grid[r][c] = scanner.nextInt();
            }
        }
        return grid;
    }

    /**
     * Orchestrates validation and output for a single test case.
     */
    private static void processTestCase(int[][] grid) {
        boolean isValid = isGridValid(grid);
        System.out.println(isValid ? "YES" : "NO");
        if (isValid) {
            int[][] neighborGrid = calculateNeighborGrid(grid.length, grid[0].length);
            printGrid(neighborGrid);
        }
    }

    /**
     * Checks if every cell's value is less than or equal to its neighbor count.
     */
    private static boolean isGridValid(int[][] grid) {
        int rows = grid.length;
        int cols = grid[0].length;
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] > getNeighborCount(r, c, rows, cols)) {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Determines the number of neighbors for a cell at (row, col) based on grid boundaries.
     */
    private static int getNeighborCount(int row, int col, int rows, int cols) {
        // Interior cells have 4 neighbors
        if (row > 0 && row < rows - 1 && col > 0 && col < cols - 1) {
            return INTERIOR_NEIGHBORS;
        }
        // Corner cells have 2 neighbors
        if ((row == 0 && col == 0) || (row == rows - 1 && col == 0) ||
            (row == 0 && col == cols - 1) || (row == rows - 1 && col == cols - 1)) {
            return CORNER_NEIGHBORS;
        }
        // Edge cells have 3 neighbors
        return EDGE_NEIGHBORS;
    }

    /**
     * Generates a grid where each cell contains its neighbor count.
     */
    private static int[][] calculateNeighborGrid(int rows, int cols) {
        int[][] neighborGrid = new int[rows][cols];
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                neighborGrid[r][c] = getNeighborCount(r, c, rows, cols);
            }
        }
        return neighborGrid;
    }

    /**
     * Prints the neighbor grid with space-separated values and proper line breaks.
     */
    private static void printGrid(int[][] grid) {
        StringBuilder output = new StringBuilder();
        for (int[] row : grid) {
            for (int i = 0; i < row.length; i++) {
                output.append(row[i]).append(i == row.length - 1 ? "" : " ");
            }
            output.append("\n");
        }
        System.out.print(output);
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

public class Main {

    /**
     * FastScanner class for efficient input reading.
     * Encapsulates BufferedReader and StringTokenizer logic to handle whitespace and newlines.
     */
    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        /**
         * Reads the next token from the input.
         * @return The next token as a String.
         */
        public String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) {
                        return null; // End of Input
                    }
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return st.nextToken();
        }

        /**
         * Reads the next integer token.
         * @return The next integer.
         */
        public int nextInt() {
            String s = next();
            if (s == null) {
                throw new RuntimeException("Unexpected end of input");
            }
            return Integer.parseInt(s);
        }
    }

    public static void main(String[] args) {
        // Initialize scanner and printer
        FastScanner scanner = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            // Read number of test cases
            String tStr = scanner.next();
            if (tStr != null) {
                int t = Integer.parseInt(tStr);
                while (t-- > 0) {
                    solve(scanner, out);
                }
            }
        } finally {
            // Ensure output is flushed and closed
            out.flush();
            out.close();
        }
    }

    /**
     * Solves a single test case.
     */
    private static void solve(FastScanner sc, PrintWriter out) {
        int rows = sc.nextInt();
        int cols = sc.nextInt();

        // Read the grid
        int[][] grid = new int[rows][cols];
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                grid[i][j] = sc.nextInt();
            }
        }

        // Matrix to store neighbor counts
        int[][] neighborCounts = new int[rows][cols];

        // Direction vectors for neighbors (Down, Up, Right, Left)
        // rowDeltas correspond to changes in 'i' (row index)
        // colDeltas correspond to changes in 'j' (col index)
        int[] rowDeltas = {1, -1, 0, 0};
        int[] colDeltas = {0, 0, 1, -1};

        boolean isPossible = true;

        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                int count = 0;

                // Check all 4 neighbors
                for (int k = 0; k < 4; k++) {
                    int ni = i + rowDeltas[k];
                    int nj = j + colDeltas[k];

                    if (isValidCell(ni, nj, rows, cols)) {
                        count++;
                    }
                }

                neighborCounts[i][j] = count;

                // Check condition: grid value must not exceed neighbor count
                if (grid[i][j] > count) {
                    isPossible = false;
                    break; // Optimization: stop processing this test case early
                }
            }
            if (!isPossible) {
                break;
            }
        }

        if (!isPossible) {
            out.println("NO");
        } else {
            out.println("YES");
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    out.print(neighborCounts[i][j] + " ");
                }
                out.println();
            }
        }
    }

    /**
     * Checks if the given coordinates are within the grid boundaries.
     */
    private static boolean isValidCell(int x, int y, int rows, int cols) {
        return x >= 0 && x < rows && y >= 0 && y < cols;
    }
}

import java.io.BufferedReader;
