/**
 * Refactored version of the original program.
 * 
 * Improvements made:
 * 1.  **Naming Conventions**: Renamed class to `GridValidator` and variables to descriptive names (e.g., `rows`, `cols`, `grid`).
 * 2.  **Constants**: Replaced magic numbers (2, 3, 4) with named constants to improve readability and maintainability.
 * 3.  **Encapsulation**: Separated input reading, validation logic, and output generation into distinct methods.
 * 4.  **Efficiency**: Used `PrintWriter` and `StringBuilder` for output to handle large grids efficiently, replacing slow `System.out.print` calls.
 * 5.  **FastScanner**: Improved the `FastScanner` utility to be more robust and standard, handling exceptions appropriately.
 * 6.  **Code Structure**: Removed redundant variable assignments and streamlined loops.
 */
public class GridValidator {

    // Constants defining the maximum allowed values for grid cells based on position
    private static final int MAX_CORNER_VALUE = 2;
    private static final int MAX_EDGE_VALUE = 3;
    private static final int MAX_INTERIOR_VALUE = 4;

    public static void main(String[] args) {
        // Initialize FastScanner for efficient input reading
        FastScanner scanner = new FastScanner(System.in);
        // Initialize PrintWriter for buffered output
        PrintWriter out = new PrintWriter(System.out);

        try {
            // Read the number of test cases
            String tStr = scanner.next();
            if (tStr != null) {
                int t = Integer.parseInt(tStr);
                for (int tt = 0; tt < t; tt++) {
                    solve(scanner, out);
                }
            }
        } catch (Exception e) {
            e.printStackTrace();
        } finally {
            out.flush();
        }
    }

    /**
     * Solves a single test case by reading input, validating, and printing output.
     */
    private static void solve(FastScanner scanner, PrintWriter out) {
        int rows = scanner.nextInt();
        int cols = scanner.nextInt();

        // Read the grid data
        int[][] grid = new int[rows][];
        for (int i = 0; i < rows; i++) {
            grid[i] = scanner.readArray(cols);
        }

        // Validate the grid
        if (isValidGrid(grid, rows, cols)) {
            out.println("YES");
            printResultGrid(out, rows, cols);
        } else {
            out.println("NO");
        }
    }

    /**
     * Validates the grid according to the problem constraints.
     * - Corners must be <= 2
     * - Edges must be <= 3
     * - Interior cells must be <= 4
     */
    private static boolean isValidGrid(int[][] grid, int rows, int cols) {
        // Check 4 corners
        // Note: Assumes rows >= 1 and cols >= 1 based on typical problem constraints.
        if (grid[0][0] > MAX_CORNER_VALUE ||
            grid[rows - 1][0] > MAX_CORNER_VALUE ||
            grid[0][cols - 1] > MAX_CORNER_VALUE ||
            grid[rows - 1][cols - 1] > MAX_CORNER_VALUE) {
            return false;
        }

        // Check vertical edges (excluding corners)
        for (int i = 1; i < rows - 1; i++) {
            if (grid[i][0] > MAX_EDGE_VALUE || grid[i][cols - 1] > MAX_EDGE_VALUE) {
                return false;
            }
        }

        // Check horizontal edges (excluding corners)
        for (int i = 1; i < cols - 1; i++) {
            if (grid[0][i] > MAX_EDGE_VALUE || grid[rows - 1][i] > MAX_EDGE_VALUE) {
                return false;
            }
        }

        // Check interior cells
        for (int i = 1; i < rows - 1; i++) {
            for (int j = 1; j < cols - 1; j++) {
                if (grid[i][j] > MAX_INTERIOR_VALUE) {
                    return false;
                }
            }
        }

        return true;
    }

    /**
     * Prints the calculated grid based on position logic.
     * Logic: Base value 4. Subtract 1 for each boundary crossed.
     * - Interior: 4
     * - Edge: 3
     * - Corner: 2
     */
    private static void printResultGrid(PrintWriter out, int rows, int cols) {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < rows; i++) {
            boolean isRowEdge = (i == 0 || i == rows - 1);
            for (int j = 0; j < cols; j++) {
                boolean isColEdge = (j == 0 || j == cols - 1);

                int value = MAX_INTERIOR_VALUE;
                if (isRowEdge) value--;
                if (isColEdge) value--;

                sb.append(value).append(' ');
            }
            sb.append('\n');
        }
        out.print(sb);
    }

    /**
     * Utility class for fast input reading.
     */
    static class FastScanner {
        private BufferedReader br;
        private StringTokenizer st;

        public FastScanner(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) {
                        return null;
                    }
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            String s = next();
            if (s == null) throw new RuntimeException("End of input");
            return Integer.parseInt(s);
        }

        long nextLong() {
            String s = next();
            if (s == null) throw new RuntimeException("End of input");
            return Long.parseLong(s);
        }

        int[] readArray(int n) {
            int[] arr = new int[n];
            for (int i = 0; i < n; i++) {
                arr[i] = nextInt();
            }
            return arr;
        }
    }
}

import java.io.BufferedReader;
