/**
 * Validates a 2D grid against positional value constraints and outputs the result.
 * Constraints:
 * - Corners: max value 2
 * - Edges (non-corners): max value 3
 * - Interior cells: max value 4
 */
public class GridConstraintChecker {

    public static void main(String[] args) throws IOException {
        FastScanner scanner = new FastScanner();
        PrintWriter out = new PrintWriter(System.out);

        // Read number of test cases
        int t = scanner.nextInt();
        while (t-- > 0) {
            int n = scanner.nextInt();
            int m = scanner.nextInt();
            int[][] grid = new int[n][m];

            // Read grid values
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    grid[i][j] = scanner.nextInt();
                }
            }

            // Validate and print result
            if (isValid(grid, n, m)) {
                out.println("YES");
                for (int i = 0; i < n; i++) {
                    for (int j = 0; j < m; j++) {
                        out.print(getCellValue(i, j, n, m));
                        // Avoid trailing space at the end of each row
                        out.print(j == m - 1 ? "" : " ");
                    }
                    out.println();
                }
            } else {
                out.println("NO");
            }
        }
        out.flush();
    }

    /**
     * Checks if every cell in the grid satisfies its positional constraint.
     */
    private static boolean isValid(int[][] grid, int n, int m) {
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                int maxAllowed = getCellValue(i, j, n, m);
                if (grid[i][j] > maxAllowed) {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Returns the required value based on the cell's position.
     * Corners -> 2, Edges -> 3, Interior -> 4
     */
    private static int getCellValue(int i, int j, int n, int m) {
        if (isCorner(i, j, n, m)) {
            return 2;
        } else if (isEdge(i, j, n, m)) {
            return 3;
        } else {
            return 4;
        }
    }

    private static boolean isCorner(int i, int j, int n, int m) {
        return (i == 0 && j == 0) || (i == n - 1 && j == 0) ||
               (i == 0 && j == m - 1) || (i == n - 1 && j == m - 1);
    }

    private static boolean isEdge(int i, int j, int n, int m) {
        return i == 0 || j == 0 || i == n - 1 || j == m - 1;
    }

    /**
     * Fast input reader to handle whitespace-separated integers efficiently.
     * Replaces fragile String.split() with StringTokenizer.
     */
    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Input parsing failed", e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            String s = next();
            return s == null ? 0 : Integer.parseInt(s);
        }
    }
}

import java.util.Scanner;

/**
 * Refactored solution for the Edit Grid problem.
 * Improvements:
 * - Clear, descriptive naming for classes, methods, and variables.
 * - Extracted common neighbor-counting logic to follow DRY principles.
 * - Replaced magic arrays with a 2D constant for directions.
 * - Added resource management for Scanner (try-with-resources).
 * - Used StringBuilder for efficient output formatting.
 * - Added JavaDoc comments for method responsibilities.
 */
public class EditGridSolver {

    private static final int[][] DIRECTIONS = {
        {0, 1}, {0, -1}, {1, 0}, {-1, 0}
    };

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            if (scanner.hasNextInt()) {
                int t = scanner.nextInt();
                for (int i = 0; i < t; i++) {
                    solve(scanner);
                }
            }
        }
    }

    /**
     * Orchestrates the grid solving process for a single test case.
     */
    private static void solve(Scanner scanner) {
        int rows = scanner.nextInt();
        int cols = scanner.nextInt();
        int[][] grid = new int[rows][cols];
        boolean isAllZeros = true;

        // Read grid and check if already valid
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                grid[r][c] = scanner.nextInt();
                if (grid[r][c] != 0) {
                    isAllZeros = false;
                }
            }
        }

        if (isAllZeros) {
            System.out.println("YES");
            printGrid(grid);
            return;
        }

        // Phase 1: Attempt to repair each non-zero cell
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] != 0) {
                    if (!attemptRepair(r, c, grid[r][c], grid)) {
                        System.out.println("NO");
                        return;
                    }
                }
            }
        }

        // Phase 2: Balance remaining non-zero cells
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] != 0) {
                    balanceCell(r, c, grid[r][c], grid);
                }
            }
        }

        System.out.println("YES");
        printGrid(grid);
    }

    /**
     * Attempts to fix a cell by adjusting its value or filling neighboring zeros.
     * @return true if the cell can be successfully repaired, false otherwise.
     */
    private static boolean attemptRepair(int row, int col, int cellValue, int[][] grid) {
        int neighborCount = countNonZeroNeighbors(row, col, grid);

        if (neighborCount > cellValue) {
            grid[row][col] = neighborCount;
            return true;
        }

        if (neighborCount == cellValue) {
            return true;
        }

        // neighborCount < cellValue: try to fill empty neighbors with 1
        for (int[] dir : DIRECTIONS) {
            int nr = row + dir[0];
            int nc = col + dir[1];
            if (isValid(nr, nc, grid.length, grid[0].length) && grid[nr][nc] == 0) {
                grid[nr][nc] = 1;
                neighborCount++;
                if (neighborCount == cellValue) {
                    return true;
                }
            }
        }

        return false;
    }

    /**
     * Adjusts a cell's value if it has more non-zero neighbors than its current value.
     */
    private static void balanceCell(int row, int col, int cellValue, int[][] grid) {
        int neighborCount = countNonZeroNeighbors(row, col, grid);
        if (neighborCount > cellValue) {
            grid[row][col] = neighborCount;
        }
    }

    /**
     * Counts the number of non-zero neighbors for a given cell.
     */
    private static int countNonZeroNeighbors(int row, int col, int[][] grid) {
        int count = 0;
        for (int[] dir : DIRECTIONS) {
            int nr = row + dir[0];
            int nc = col + dir[1];
            if (isValid(nr, nc, grid.length, grid[0].length) && grid[nr][nc] != 0) {
                count++;
            }
        }
        return count;
    }

    /**
     * Checks if the given coordinates are within grid boundaries.
     */
    private static boolean isValid(int row, int col, int maxRows, int maxCols) {
        return row >= 0 && col >= 0 && row < maxRows && col < maxCols;
    }

    /**
     * Prints the grid to standard output in the required format.
     */
    private static void printGrid(int[][] grid) {
        StringBuilder sb = new StringBuilder();
        for (int[] row : grid) {
            for (int val : row) {
                sb.append(val).append(' ');
            }
            sb.append('\n');
        }
        System.out.print(sb);
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

/**
 * Refactored version of the LongInteger program.
 * 
 * Refactoring Improvements:
 * 1. Class Renaming: Renamed 'LongInteger' to 'MatrixProcessor' to accurately reflect the program's logic.
 * 2. Separation of Concerns: Separated Input/Output handling from the core business logic.
 * 3. Robust Input Parsing: Implemented a 'FastScanner' helper class to handle whitespace and newlines reliably,
 *    replacing the brittle 'split(" ")' method.
 * 4. Code Modularity: Extracted the neighbor counting logic into a dedicated helper method 'countNonZeroNeighbors'.
 * 5. Readability: Used descriptive variable names (e.g., 'matrix', 'rows', 'cols') instead of single letters.
 * 6. Side-Effect Management: The 'processMatrix' method now returns a boolean status instead of printing "NO" directly,
 *    allowing the main method to handle output formatting consistently.
 * 7. Cleanup: Removed unused imports (HashMap, Map).
 */
public class MatrixProcessor {

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner();

        // Read number of test cases
        String tStr = scanner.next();
        if (tStr == null) return;

        int t = Integer.parseInt(tStr);

        while (t-- > 0) {
            String nStr = scanner.next();
            String mStr = scanner.next();

            if (nStr == null || mStr == null) break;

            int n = Integer.parseInt(nStr);
            int m = Integer.parseInt(mStr);

            int[][] matrix = new int[n][m];
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    String valStr = scanner.next();
                    if (valStr != null) {
                        matrix[i][j] = Integer.parseInt(valStr);
                    }
                }
            }

            boolean isValid = processMatrix(matrix);

            if (isValid) {
                System.out.println("YES");
                printMatrix(matrix);
            } else {
                System.out.println("NO");
            }
        }
    }

    /**
     * Processes the matrix according to the specific rules:
     * 1. If a cell is 0, replace it with the count of its non-zero neighbors.
     * 2. If a cell is > 0, verify that the count of its non-zero neighbors 
     *    is not less than its current value. If valid, update cell to neighbor count.
     *
     * @param matrix The 2D integer array to process.
     * @return true if the matrix satisfies all conditions, false otherwise.
     */
    private static boolean processMatrix(int[][] matrix) {
        if (matrix == null || matrix.length == 0) {
            return true;
        }

        int rows = matrix.length;
        int cols = matrix[0].length;

        // Pass 1: Fill zeros with neighbor counts
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (matrix[r][c] == 0) {
                    matrix[r][c] = countNonZeroNeighbors(matrix, r, c);
                }
            }
        }

        // Pass 2: Validate and update non-zero cells
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (matrix[r][c] > 0) {
                    int currentVal = matrix[r][c];
                    int neighborCount = countNonZeroNeighbors(matrix, r, c);

                    if (neighborCount < currentVal) {
                        return false;
                    }
                    matrix[r][c] = neighborCount;
                }
            }
        }

        return true;
    }

    /**
     * Counts the number of non-zero neighbors for a cell at (r, c).
     * Neighbors are defined as Up, Down, Left, Right.
     */
    private static int countNonZeroNeighbors(int[][] matrix, int r, int c) {
        int count = 0;
        int rows = matrix.length;
        int cols = matrix[0].length;

        // Check Up
        if (r > 0 && matrix[r - 1][c] > 0) count++;
        // Check Down
        if (r < rows - 1 && matrix[r + 1][c] > 0) count++;
        // Check Left
        if (c > 0 && matrix[r][c - 1] > 0) count++;
        // Check Right
        if (c < cols - 1 && matrix[r][c + 1] > 0) count++;

        return count;
    }

    /**
     * Prints the matrix to standard output.
     */
    private static void printMatrix(int[][] matrix) {
        StringBuilder sb = new StringBuilder();
        for (int[] row : matrix) {
            for (int val : row) {
                sb.append(val).append(" ");
            }
            sb.append("\n");
        }
        System.out.print(sb);
    }

    /**
     * Helper class for efficient and robust input reading.
     */
    static class FastScanner {
        BufferedReader br;
        StringTokenizer st;

        public FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return st.nextToken();
        }
    }
}

import java.io.*;
import java.util.StringTokenizer;

public class B_1375 {
    // Direction vectors for moving right, left, up, down
    private static final int[] DX = {0, 0, -1, 1};
    private static final int[] DY = {1, -1, 0, 0};

    public static void main(String[] args) {
        FastScanner sc = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out);
        try {
            solve(sc, out);
        } finally {
            out.flush();
        }
    }

    /**
     * Orchestrates reading, processing, and output for all test cases.
     */
    private static void solve(FastScanner sc, PrintWriter out) {
        if (!sc.hasMoreTokens()) return;
        int t = sc.nextInt();

        while (t-- > 0) {
            int n = sc.nextInt();
            int m = sc.nextInt();

            // Read the input grid
            int[][] grid = new int[n][m];
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    grid[i][j] = sc.nextInt();
                }
            }

            // Compute valid neighbor counts for each cell
            int[][] neighborCounts = computeNeighborCounts(n, m);

            // Validate if the input grid satisfies the condition
            boolean isValid = true;
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    if (grid[i][j] > neighborCounts[i][j]) {
                        isValid = false;
                        break;
                    }
                }
                if (!isValid) break; // Early exit on failure
            }

            // Output result
            out.println(isValid ? "YES" : "NO");
            if (isValid) {
                for (int i = 0; i < n; i++) {
                    for (int j = 0; j < m; j++) {
                        out.print(neighborCounts[i][j] + (j == m - 1 ? "" : " "));
                    }
                    out.println();
                }
            }
        }
    }

    /**
     * Computes the number of valid adjacent neighbors for each cell in an n x m grid.
     */
    private static int[][] computeNeighborCounts(int n, int m) {
        int[][] counts = new int[n][m];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                int c = 0;
                for (int d = 0; d < 4; d++) {
                    int nx = i + DX[d];
                    int ny = j + DY[d];
                    if (isValid(nx, ny, n, m)) {
                        c++;
                    }
                }
                counts[i][j] = c;
            }
        }
        return counts;
    }

    /**
     * Checks if coordinates are within grid boundaries.
     */
    private static boolean isValid(int x, int y, int n, int m) {
        return x >= 0 && x < n && y >= 0 && y < m;
    }

    /**
     * Fast I/O helper class to replace java.util.Scanner for competitive programming performance.
     */
    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        boolean hasMoreTokens() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return false;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return true;
        }

        String next() {
            if (hasMoreTokens()) return st.nextToken();
            throw new RuntimeException("Unexpected end of input");
        }

        int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.*;
import java.util.*;

public class Main {
    // Constants for grid configuration to improve readability and maintainability
    private static final int CORNER_VALUE = 2;
    private static final int EDGE_VALUE = 3;
    private static final int DEFAULT_VALUE = 4;

    public static void main(String[] args) {
        FastReader reader = new FastReader();
        // Use PrintWriter with buffered output for significantly faster I/O
        PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out));

        try {
            String testCasesInput = reader.next();
            if (testCasesInput == null) {
                out.flush();
                return;
            }
            int testCases = Integer.parseInt(testCasesInput);

            while (testCases-- > 0) {
                int n = reader.nextInt();
                int m = reader.nextInt();

                int[][] expectedGrid = buildExpectedGrid(n, m);
                int[][] actualGrid = new int[n][m];
                boolean isInvalid = false;

                // Read input grid and validate against expected grid
                for (int i = 0; i < n; i++) {
                    for (int j = 0; j < m; j++) {
                        actualGrid[i][j] = reader.nextInt();
                        if (actualGrid[i][j] > expectedGrid[i][j]) {
                            isInvalid = true;
                        }
                    }
                }

                if (isInvalid) {
                    out.println("NO");
                } else {
                    out.println("YES");
                    printGrid(out, expectedGrid);
                }
            }
        } catch (Exception e) {
            e.printStackTrace();
        } finally {
            out.flush();
        }
    }

    /**
     * Constructs the expected grid pattern based on the problem's rules.
     * - Default cells are 4
     * - Corners are 2
     * - Edges (excluding corners) are 3
     */
    private static int[][] buildExpectedGrid(int n, int m) {
        int[][] grid = new int[n][m];
        // Initialize all cells with the default value
        for (int[] row : grid) {
            Arrays.fill(row, DEFAULT_VALUE);
        }

        // Set corner values
        grid[0][0] = CORNER_VALUE;
        grid[0][m - 1] = CORNER_VALUE;
        grid[n - 1][0] = CORNER_VALUE;
        grid[n - 1][m - 1] = CORNER_VALUE;

        // Set top and bottom edges (excluding corners)
        for (int j = 1; j < m - 1; j++) {
            grid[0][j] = EDGE_VALUE;
            grid[n - 1][j] = EDGE_VALUE;
        }

        // Set left and right edges (excluding corners)
        for (int i = 1; i < n - 1; i++) {
            grid[i][0] = EDGE_VALUE;
            grid[i][m - 1] = EDGE_VALUE;
        }

        return grid;
    }

    /**
     * Prints the grid to the provided PrintWriter.
     */
    private static void printGrid(PrintWriter out, int[][] grid) {
        for (int[] row : grid) {
            for (int val : row) {
                out.print(val).print(' ');
            }
            out.println();
        }
    }

    /**
     * Fast I/O helper class for competitive programming.
     * Replaces Scanner with BufferedReader and StringTokenizer for performance.
     */
    static class FastReader {
        BufferedReader br;
        StringTokenizer st;

        public FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.*;
import java.util.*;

public class Main {
    // Configuration Constants
    private static final String INPUT_FILE = "input.txt";
    private static final String OUTPUT_FILE = "output.txt";
    private static final boolean READ_TEST_CASE_COUNT_FROM_INPUT = true;

    // Logic Constants
    private static final int CORNER_VALUE = 2;
    private static final int EDGE_VALUE = 3;
    private static final int INNER_VALUE = 4;

    public static void main(String[] args) {
        PrintWriter out = null;
        FastReader sc = null;
        long startTime = 0;
        long endTime = 0;
        boolean timingEnabled = false;

        try {
            // Initialize Input Reader
            sc = new FastReader();

            // Initialize Output Writer
            File outputFile = new File(OUTPUT_FILE);
            if (outputFile.exists()) {
                out = new PrintWriter(new FileOutputStream(OUTPUT_FILE));
                timingEnabled = true;
                startTime = System.nanoTime();
            } else {
                out = new PrintWriter(System.out);
            }

            // Determine number of test cases
            int testCases = 1;
            if (READ_TEST_CASE_COUNT_FROM_INPUT) {
                testCases = sc.nextInt();
            }

            // Process each test case
            while (testCases-- > 0) {
                solve(sc, out);
            }

            // Finalize Output
            out.flush();
            if (timingEnabled) {
                endTime = System.nanoTime();
                out.println("Execution time: " + (endTime - startTime) / 1_000_000 + " ms");
            }

        } catch (Exception e) {
            if (out != null) {
                out.println("Exception: " + e.getMessage());
                out.flush();
            }
        } finally {
            if (out != null) {
                out.close();
            }
        }
    }

    /**
     * Solves a single test case.
     */
    private static void solve(FastReader sc, PrintWriter out) throws IOException {
        int rows = sc.nextInt();
        int cols = sc.nextInt();

        int[][] grid = new int[rows][cols];
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                grid[i][j] = sc.nextInt();
            }
        }

        boolean isValid = true;
        int[][] requiredGrid = new int[rows][cols];

        // Calculate required values and validate against input grid
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                requiredGrid[i][j] = getRequiredValue(i, j, rows, cols);
                // Original logic: if (ans[i][j] < a[i][j]) -> NO
                // This implies input value (grid) must be <= required value (ans)
                if (requiredGrid[i][j] < grid[i][j]) {
                    isValid = false;
                }
            }
        }

        if (!isValid) {
            out.println("NO");
        } else {
            out.println("YES");
            StringBuilder sb = new StringBuilder();
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    sb.append(requiredGrid[i][j]);
                    if (j < cols - 1) {
                        sb.append(' ');
                    }
                }
                sb.append('\n');
            }
            out.print(sb);
        }
    }

    /**
     * Determines the minimum required value for a cell based on its position.
     * Corners: 2, Edges: 3, Inner: 4
     */
    private static int getRequiredValue(int row, int col, int rows, int cols) {
        boolean isBorderRow = (row == 0 || row == rows - 1);
        boolean isBorderCol = (col == 0 || col == cols - 1);

        if (isBorderRow && isBorderCol) {
            return CORNER_VALUE;
        } else if (isBorderRow || isBorderCol) {
            return EDGE_VALUE;
        } else {
            return INNER_VALUE;
        }
    }

    /**
     * Fast I/O Reader
     */
    static class FastReader {
        BufferedReader br;
        StringTokenizer st;

        public FastReader() throws FileNotFoundException {
            File in = new File(INPUT_FILE);
            if (in.exists()) {
                br = new BufferedReader(new InputStreamReader(new FileInputStream(in)));
            } else {
                br = new BufferedReader(new InputStreamReader(System.in));
            }
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) {
                        return null;
                    }
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            String s = next();
            if (s == null) throw new RuntimeException("Unexpected end of input");
            return Integer.parseInt(s);
        }

        long nextLong() {
            String s = next();
            if (s == null) throw new RuntimeException("Unexpected end of input");
            return Long.parseLong(s);
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.OutputStreamWriter;
import java.io.PrintWriter;
import java.util.StringTokenizer;

public class B_ {
    // Constants defining the maximum allowed values for different grid positions
    private static final int CORNER_LIMIT = 2;
    private static final int EDGE_LIMIT = 3;
    private static final int INTERIOR_LIMIT = 4;

    // Fast I/O components
    private static final BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
    private static final PrintWriter pw = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)));
    private static StringTokenizer st;

    public static void main(String[] args) throws IOException {
        // Read number of test cases
        int t = readInt();
        while (t-- > 0) {
            solve();
        }
        pw.flush();
        pw.close();
    }

    private static void solve() throws IOException {
        int n = readInt();
        int m = readInt();

        boolean isPossible = true;

        // Read the grid and validate constraints on the fly.
        // We consume the input regardless of validity to maintain stream synchronization.
        // This also avoids allocating O(N*M) memory for the grid array.
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                int val = readInt();
                if (isPossible) {
                    if (!isValidCell(i, j, n, m, val)) {
                        isPossible = false;
                    }
                }
            }
        }

        if (!isPossible) {
            pw.println("NO");
        } else {
            pw.println("YES");
            generateOutput(n, m);
        }
    }

    /**
     * Checks if a cell value is within the allowed limit based on its position.
     * Corners must be <= 2.
     * Edges (non-corner) must be <= 3.
     * Interior cells must be <= 4.
     */
    private static boolean isValidCell(int row, int col, int n, int m, int val) {
        boolean isCorner = (row == 0 || row == n - 1) && (col == 0 || col == m - 1);
        boolean isEdge = row == 0 || row == n - 1 || col == 0 || col == m - 1;

        if (isCorner) {
            return val <= CORNER_LIMIT;
        } else if (isEdge) {
            return val <= EDGE_LIMIT;
        } else {
            return val <= INTERIOR_LIMIT;
        }
    }

    /**
     * Generates and prints the required output grid pattern.
     * Top/Bottom rows: 2, 3, ..., 3, 2
     * Middle rows: 3, 4, ..., 4, 3
     */
    private static void generateOutput(int n, int m) {
        StringBuilder sb = new StringBuilder();

        for (int i = 0; i < n; i++) {
            boolean isBoundaryRow = (i == 0 || i == n - 1);

            // First element of the row
            int firstVal = isBoundaryRow ? 2 : 3;
            sb.append(firstVal);

            // Middle elements (if any)
            if (m > 1) {
                for (int j = 1; j < m - 1; j++) {
                    int midVal = isBoundaryRow ? 3 : 4;
                    sb.append(" ").append(midVal);
                }
                // Last element of the row
                int lastVal = isBoundaryRow ? 2 : 3;
                sb.append(" ").append(lastVal);
            }
            sb.append("\n");
        }
        pw.print(sb);
    }

    // Helper method to read next integer token
    private static int readInt() throws IOException {
        while (st == null || !st.hasMoreTokens()) {
            String line = br.readLine();
            if (line == null) {
                throw new IOException("Unexpected end of input");
            }
            st = new StringTokenizer(line);
        }
        return Integer.parseInt(st.nextToken());
    }
}

import java.util.Scanner;

public class GridValidator {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        // The original code contained a dangling input.nextInt() at the start which likely 
        // consumed the first dimension of the first grid or a test case count incorrectly.
        // We assume the input stream consists of a sequence of grid definitions (rows cols grid_data).

        while (scanner.hasNextInt()) {
            int rows = scanner.nextInt();
            int cols = scanner.nextInt();

            int[][] grid = new int[rows][cols];

            // Read grid data
            // Standard Row-Major order is used for maintainability: Row 0, then Row 1, etc.
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (scanner.hasNextInt()) {
                        grid[r][c] = scanner.nextInt();
                    }
                }
            }

            if (isValid(grid, rows, cols)) {
                System.out.println("YES");
                int[][] neighborCounts = calculateNeighborCounts(grid, rows, cols);
                printGrid(neighborCounts, rows, cols);
            } else {
                System.out.println("NO");
            }
        }
        scanner.close();
    }

    /**
     * Validates the grid based on the rule:
     * For any cell with a value other than 1, the value must not exceed
     * the number of its orthogonal neighbors (Up, Down, Left, Right).
     */
    private static boolean isValid(int[][] grid, int rows, int cols) {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] != 1) {
                    int neighborCount = countNeighbors(r, c, rows, cols);
                    if (grid[r][c] > neighborCount) {
                        return false;
                    }
                }
            }
        }
        return true;
    }

    /**
     * Counts the number of valid orthogonal neighbors for a cell at coordinates (r, c).
     */
    private static int countNeighbors(int r, int c, int rows, int cols) {
        int count = 0;
        if (r > 0) count++;           // Up
        if (r < rows - 1) count++;    // Down
        if (c > 0) count++;           // Left
        if (c < cols - 1) count++;    // Right
        return count;
    }

    /**
     * Calculates the neighbor count for every cell in the grid.
     * Returns a new grid containing these counts.
     */
    private static int[][] calculateNeighborCounts(int[][] grid, int rows, int cols) {
        int[][] counts = new int[rows][cols];
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                counts[r][c] = countNeighbors(r, c, rows, cols);
            }
        }
        return counts;
    }

    /**
     * Prints the grid to standard output.
     * Values are space-separated, rows are newline-separated.
     */
    private static void printGrid(int[][] grid, int rows, int cols) {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                System.out.print(grid[r][c]);
                if (c < cols - 1) {
                    System.out.print(" ");
                }
            }
            System.out.println();
        }
    }
}

import java.io.*;
import java.util.*;

public class GridSolver {
    // Magic numbers extracted to named constants for readability and maintainability
    private static final int MAX_ALLOWED_VALUE = 4;
    private static final int CORNER_MAX_VALUE = 2;
    private static final int EDGE_MAX_VALUE = 3;
    private static final int CORNER_SET_VALUE = 2;
    private static final int EDGE_SET_VALUE = 3;
    private static final int INTERIOR_SET_VALUE = 4;

    public static void main(String[] args) {
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
             PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out))) {

            FastScanner sc = new FastScanner(br);
            if (sc.hasNext()) {
                int t = sc.nextInt();
                while (t-- > 0) {
                    int n = sc.nextInt();
                    int m = sc.nextInt();
                    int[][] grid = new int[n][m];
                    for (int i = 0; i < n; i++) {
                        for (int j = 0; j < m; j++) {
                            grid[i][j] = sc.nextInt();
                        }
                    }
                    solve(grid, n, m, out);
                }
            }
        } catch (IOException e) {
            System.err.println("I/O Error: " + e.getMessage());
        }
    }

    /**
     * Validates the grid according to problem constraints and modifies it if valid.
     * Prints "YES" with the modified grid or "NO" if constraints are violated.
     */
    private static void solve(int[][] grid, int n, int m, PrintWriter out) {
        boolean valid = true;

        // 1. Validate all cells are within the maximum allowed value
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] > MAX_ALLOWED_VALUE) {
                    valid = false;
                }
            }
        }

        // 2. Validate corners do not exceed corner max value
        if (n > 0 && m > 0) {
            if (grid[0][0] > CORNER_MAX_VALUE || grid[0][m - 1] > CORNER_MAX_VALUE ||
                grid[n - 1][m - 1] > CORNER_MAX_VALUE || grid[n - 1][0] > CORNER_MAX_VALUE) {
                valid = false;
            }
        }

        // 3. Validate and set top/bottom edges (excluding corners)
        for (int j = 1; j < m - 1; j++) {
            if (grid[0][j] > EDGE_MAX_VALUE) valid = false;
            grid[0][j] = EDGE_SET_VALUE;
            if (grid[n - 1][j] > EDGE_MAX_VALUE) valid = false;
            grid[n - 1][j] = EDGE_SET_VALUE;
        }

        // 4. Validate and set left/right edges (excluding corners)
        for (int i = 1; i < n - 1; i++) {
            if (grid[i][0] > EDGE_MAX_VALUE) valid = false;
            grid[i][0] = EDGE_SET_VALUE;
            if (grid[i][m - 1] > EDGE_MAX_VALUE) valid = false;
            grid[i][m - 1] = EDGE_SET_VALUE;
        }

        // If any validation failed, output NO and return early
        if (!valid) {
            out.println("NO");
            return;
        }

        // 5. Set final values for the valid configuration
        grid[0][0] = CORNER_SET_VALUE;
        grid[0][m - 1] = CORNER_SET_VALUE;
        grid[n - 1][m - 1] = CORNER_SET_VALUE;
        grid[n - 1][0] = CORNER_SET_VALUE;

        for (int i = 1; i < n - 1; i++) {
            for (int j = 1; j < m - 1; j++) {
                grid[i][j] = INTERIOR_SET_VALUE;
            }
        }

        // Output YES and the modified grid
        out.println("YES");
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                out.print(grid[i][j]);
                out.print(j == m - 1 ? "" : " ");
            }
            out.println();
        }
    }

    /**
     * Helper class for fast and robust input parsing.
     * Handles whitespace, empty lines, and newlines automatically.
     */
    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner(BufferedReader br) {
            this.br = br;
        }

        public boolean hasNext() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return false;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    return false;
                }
            }
            return true;
        }

        public String next() {
            if (hasNext()) return st.nextToken();
            throw new NoSuchElementException("No more tokens available");
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

