/**
 * Refactored solution for constructing a palindrome string with a given count of zeros and ones.
 * Handles multiple test cases efficiently using fast I/O.
 */
public class Solution {

    /**
     * Fast input scanner for competitive programming style problems.
     */
    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            String s = next();
            return s == null ? 0 : Integer.parseInt(s);
        }
    }

    /**
     * Fast output writer extending PrintWriter for buffered output.
     */
    static class FastWriter extends PrintWriter {
        FastWriter() {
            super(System.out);
        }
    }

    public static void main(String[] args) {
        FastScanner in = new FastScanner();
        FastWriter out = new FastWriter();

        int testCases = in.nextInt();
        while (testCases-- > 0) {
            solve(in, out);
        }

        out.close();
    }

    /**
     * Solves a single test case.
     */
    private static void solve(FastScanner in, FastWriter out) {
        int targetZeros = in.nextInt();
        int targetOnes = in.nextInt();
        char[] pattern = in.next().toCharArray();
        int length = pattern.length;

        // Step 1: Enforce palindrome symmetry
        if (!enforcePalindrome(pattern)) {
            out.println("-1");
            return;
        }

        // Step 2: Count existing characters after symmetry enforcement
        int currentZeros = 0;
        int currentOnes = 0;
        for (char c : pattern) {
            if (c == '0') currentZeros++;
            else if (c == '1') currentOnes++;
        }

        // Step 3: Basic feasibility check
        if (targetZeros < currentZeros || targetOnes < currentOnes) {
            out.println("-1");
            return;
        }

        int remainingZeros = targetZeros - currentZeros;
        int remainingOnes = targetOnes - currentOnes;

        // Step 4: Handle middle element for odd-length strings
        if (length % 2 != 0) {
            int mid = length / 2;
            if (pattern[mid] == '?') {
                // Exactly one of remainingZeros or remainingOnes must be odd
                if (remainingZeros % 2 != 0) {
                    pattern[mid] = '0';
                    remainingZeros--;
                } else if (remainingOnes % 2 != 0) {
                    pattern[mid] = '1';
                    remainingOnes--;
                } else {
                    // Both even or both odd -> impossible for odd length
                    out.println("-1");
                    return;
                }
            } else {
                // Middle character is fixed, adjust remaining counts
                if (pattern[mid] == '0') remainingZeros--;
                else remainingOnes--;
            }
        } else {
            // Even length: both remaining counts must be even
            if (remainingZeros % 2 != 0 || remainingOnes % 2 != 0) {
                out.println("-1");
                return;
            }
        }

        // Step 5: Fill remaining '?' characters in symmetric pairs
        for (int i = 0; i < length / 2; i++) {
            if (pattern[i] == '?') {
                if (remainingZeros >= 2) {
                    pattern[i] = '0';
                    pattern[length - 1 - i] = '0';
                    remainingZeros -= 2;
                } else if (remainingOnes >= 2) {
                    pattern[i] = '1';
                    pattern[length - 1 - i] = '1';
                    remainingOnes -= 2;
                } else {
                    // Should not be reached if parity checks passed
                    out.println("-1");
                    return;
                }
            }
        }

        // Step 6: Final validation
        if (remainingZeros != 0 || remainingOnes != 0) {
            out.println("-1");
            return;
        }

        out.println(new String(pattern));
    }

    /**
     * Enforces palindrome property on the character array.
     * Returns false if a contradiction is found, true otherwise.
     * Modifies the array in-place to reflect symmetry.
     */
    private static boolean enforcePalindrome(char[] arr) {
        int n = arr.length;
        for (int i = 0; i < n / 2; i++) {
            char left = arr[i];
            char right = arr[n - 1 - i];

            if (left != '?' && right != '?') {
                if (left != right) return false;
            } else if (left != '?') {
                arr[n - 1 - i] = left;
            } else if (right != '?') {
                arr[i] = right;
            }
            // If both are '?', leave them for later filling
        }
        return true;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

public final class Solution {

    public static void main(String[] args) {
        FastReader reader = new FastReader();
        PrintWriter writer = new PrintWriter(System.out);

        int testCases = reader.nextInt();
        while (testCases-- > 0) {
            int numZeros = reader.nextInt();
            int numOnes = reader.nextInt();
            String pattern = reader.next();

            writer.println(solvePalindrome(numZeros, numOnes, pattern));
        }

        writer.flush();
        writer.close();
    }

    /**
     * Constructs a palindrome from the given pattern by replacing '?' characters
     * with '0's and '1's, respecting the available counts.
     *
     * @param numZeros Total available '0's to place
     * @param numOnes  Total available '1's to place
     * @param pattern  Input string containing '0', '1', and '?'
     * @return The constructed palindrome, or "-1" if impossible
     */
    private static String solvePalindrome(int numZeros, int numOnes, String pattern) {
        int n = pattern.length();
        // Precondition: total characters must match the sum of available zeros and ones
        if (numZeros + numOnes != n) {
            return "-1";
        }

        char[] chars = pattern.toCharArray();

        // Decrement counters based on already present characters
        for (char c : chars) {
            if (c == '0') numZeros--;
            else if (c == '1') numOnes--;
        }

        int left = 0;
        int right = n - 1;

        while (left < right) {
            char leftChar = chars[left];
            char rightChar = chars[right];

            if (leftChar == '?' && rightChar == '?') {
                // Both are unknown: greedily assign pairs
                if (numZeros >= 2) {
                    chars[left] = '0';
                    chars[right] = '0';
                    numZeros -= 2;
                } else if (numOnes >= 2) {
                    chars[left] = '1';
                    chars[right] = '1';
                    numOnes -= 2;
                } else {
                    return "-1";
                }
            } else if (leftChar == '?') {
                // Left is unknown, match right
                chars[left] = rightChar;
                if (rightChar == '0') numZeros--;
                else numOnes--;
            } else if (rightChar == '?') {
                // Right is unknown, match left
                chars[right] = leftChar;
                if (leftChar == '0') numZeros--;
                else numOnes--;
            } else if (leftChar != rightChar) {
                // Both known but mismatched -> not a palindrome
                return "-1";
            }

            left++;
            right--;
        }

        // Handle middle character for odd-length strings
        if (n % 2 != 0) {
            int mid = left;
            if (chars[mid] == '?') {
                if (numZeros > 0) {
                    chars[mid] = '0';
                    numZeros--;
                } else if (numOnes > 0) {
                    chars[mid] = '1';
                    numOnes--;
                } else {
                    return "-1";
                }
            }
        }

        // Verify all characters were used
        if (numZeros != 0 || numOnes != 0) {
            return "-1";
        }

        return new String(chars);
    }

    /**
     * Efficient input reader for competitive programming.
     */
    static class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        long nextLong() {
            return Long.parseLong(next());
        }

        double nextDouble() {
            return Double.parseDouble(next());
        }

        String nextLine() {
            String str = "";
            try {
                str = br.readLine();
            } catch (IOException e) {
                throw new RuntimeException("Error reading line", e);
            }
            return str;
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Solves the problem of balancing '0's and '1's in a string while ensuring it forms a palindrome.
 * Replaces '?' characters to meet exact counts of '0's and '1's.
 */
public class StringPalindromeBalancer {
    private final FastScanner in;
    private final PrintWriter out;

    public StringPalindromeBalancer(InputStream in, OutputStream out) {
        this.in = new FastScanner(in);
        this.out = new PrintWriter(out);
    }

    /**
     * Solves a single test case.
     * Reads required counts for '0' and '1', then a character array.
     * Modifies the array in-place to satisfy palindrome and count constraints.
     */
    public void solve() {
        int zeroCount = in.nextInt(); // Remaining '0's allowed
        int oneCount = in.nextInt();  // Remaining '1's allowed
        char[] chars = in.next().toCharArray();
        int length = chars.length;

        // Pass 1: Resolve symmetric pairs with at least one known character
        for (int i = 0; i < length / 2; i++) {
            int j = length - 1 - i;
            char left = chars[i];
            char right = chars[j];

            if (left == right) {
                if (left == '0') zeroCount -= 2;
                else if (left == '1') oneCount -= 2;
            } else if (left == '?' && right == '?') {
                // Both unknown, defer to Pass 2
            } else if (left == '?' || right == '?') {
                // Exactly one unknown: force it to match the known character
                char fixed = (left != '?') ? left : right;
                int unknownIdx = (left == '?') ? j : i;
                chars[unknownIdx] = fixed;
                if (fixed == '0') zeroCount--;
                else oneCount--;
            } else {
                // Both known but different: impossible to form a palindrome
                out.println(-1);
                return;
            }
        }

        // Pass 2: Resolve remaining '?' pairs based on remaining quotas
        for (int i = 0; i < length / 2; i++) {
            int j = length - 1 - i;
            if (chars[i] == '?') { // Both chars[i] and chars[j] are '?'
                if (zeroCount >= oneCount) {
                    chars[i] = chars[j] = '0';
                    zeroCount -= 2;
                } else {
                    chars[i] = chars[j] = '1';
                    oneCount -= 2;
                }
            }
        }

        // Handle middle element for odd-length strings
        if (length % 2 == 1) {
            int mid = length / 2;
            if (chars[mid] == '?') {
                if (zeroCount > 0) {
                    chars[mid] = '0';
                    zeroCount--;
                } else if (oneCount > 0) {
                    chars[mid] = '1';
                    oneCount--;
                }
            }
        }

        // Final validation: ensure all quotas are exactly met
        if (zeroCount != 0 || oneCount != 0) {
            out.println(-1);
        } else {
            out.println(new String(chars));
        }
    }

    /**
     * Orchestrates reading test cases and invoking the solver.
     */
    public void run() {
        try {
            int testCases = in.nextInt();
            while (testCases-- > 0) {
                solve();
            }
        } finally {
            out.flush();
            out.close();
        }
    }

    public static void main(String[] args) {
        // Standard competitive programming I/O setup.
        // To use file I/O, replace System.in/System.out with FileInputStream/FileOutputStream.
        new StringPalindromeBalancer(System.in, System.out).run();
    }

    /**
     * Fast I/O helper class for competitive programming.
     * Optimized for reading integers, longs, floats, doubles, and strings.
     */
    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1024];
        private int ptr = 0;
        private int buflen = 0;

        public FastScanner(InputStream in) {
            this.in = in;
        }

        private int readByte() {
            if (ptr >= buflen) {
                ptr = 0;
                try {
                    buflen = in.read(buffer);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
                if (buflen <= 0) return -1;
            }
            return buffer[ptr++];
        }

        private static boolean isSpaceChar(int c) {
            return !(c >= 33 && c <= 126);
        }

        private int skip() {
            int b;
            while ((b = readByte()) != -1 && isSpaceChar(b));
            return b;
        }

        public String next() {
            int b = skip();
            StringBuilder sb = new StringBuilder();
            while (b != -1 && !isSpaceChar(b)) {
                sb.appendCodePoint(b);
                b = readByte();
            }
            return sb.toString();
        }

        public int nextInt() {
            int b = skip();
            int num = 0;
            boolean negative = false;
            if (b == '-') {
                negative = true;
                b = readByte();
            }
            while (b >= '0' && b <= '9') {
                num = num * 10 + (b - '0');
                b = readByte();
            }
            return negative ? -num : num;
        }

        public long nextLong() {
            int b = skip();
            long num = 0;
            boolean negative = false;
            if (b == '-') {
                negative = true;
                b = readByte();
            }
            while (b >= '0' && b <= '9') {
                num = num * 10L + (b - '0');
                b = readByte();
            }
            return negative ? -num : num;
        }

        public float nextFloat() {
            return Float.parseFloat(next());
        }

        public double nextDouble() {
            return Double.parseDouble(next());
        }
    }
}

import java.util.Scanner;

public class Solution {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        if (scanner.hasNextInt()) {
            int numTestCases = scanner.nextInt();
            scanner.nextLine(); // Consume the newline after the integer count

            for (int i = 0; i < numTestCases; i++) {
                System.out.println(solve(scanner));
            }
        }
    }

    /**
     * Solves a single test case: fills '?' characters in a string to form a palindrome
     * with exactly 'targetZeros' zeros and 'targetOnes' ones.
     */
    private static String solve(Scanner scanner) {
        String[] parts = scanner.nextLine().trim().split("\\s+");
        int targetZeros = Integer.parseInt(parts[0]);
        int targetOnes = Integer.parseInt(parts[1]);
        char[] arr = scanner.nextLine().toCharArray();

        int left = 0;
        int right = arr.length - 1;

        // Pass 1: Resolve symmetric '?'s to satisfy palindrome property
        while (left < right) {
            if (arr[left] == '?' || arr[right] == '?') {
                if (arr[left] == '?' && arr[right] == '?') {
                    // Leave for later filling
                } else if (arr[left] == '?') {
                    arr[left] = arr[right];
                } else {
                    arr[right] = arr[left];
                }
                left++;
                right--;
            } else if (arr[left] != arr[right]) {
                return "-1";
            } else {
                left++;
                right--;
            }
        }

        // Count existing zeros and ones
        int currentZeros = 0;
        int currentOnes = 0;
        for (char c : arr) {
            if (c == '0') currentZeros++;
            else if (c == '1') currentOnes++;
        }

        if (currentZeros > targetZeros || currentOnes > targetOnes) {
            return "-1";
        }

        int remainingZeros = targetZeros - currentZeros;
        int remainingOnes = targetOnes - currentOnes;

        // Pass 2: Fill remaining '?'s from outside in
        left = 0;
        right = arr.length - 1;
        while (left < right) {
            if (arr[left] != '?' && arr[right] != '?') {
                left++;
                right--;
                continue;
            }

            // Fill a symmetric pair. Prefer '0' if we have enough quota, else '1'
            if (remainingZeros >= 2) {
                remainingZeros -= 2;
                arr[left] = '0';
                arr[right] = '0';
            } else {
                remainingOnes -= 2;
                arr[left] = '1';
                arr[right] = '1';
            }
            left++;
            right--;
        }

        // Handle middle element for odd-length strings
        if (left == right && arr[left] == '?') {
            if (remainingZeros == 1) {
                remainingZeros--;
                arr[left] = '0';
            } else {
                remainingOnes--;
                arr[left] = '1';
            }
        }

        // Final validation: ensure exact counts are met
        if (remainingZeros != 0 || remainingOnes != 0) {
            return "-1";
        }

        return new String(arr);
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

/**
 * A solution to balance a string into a palindrome with constraints on character counts.
 * Refactored for maintainability, readability, and separation of concerns.
 */
public class StringBalancer {

    public static void main(String[] args) {
        // Initialize FastScanner and PrintWriter
        FastScanner scanner = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            // Check if input exists
            if (scanner.hasNext()) {
                // The first integer represents the number of test cases
                int testCnt = scanner.nextInt();
                solve(testCnt, scanner, out);
            }
        } catch (Exception e) {
            // In a production environment, use a proper logger
            e.printStackTrace();
        } finally {
            // Ensure output is flushed and resources closed
            out.flush();
            out.close();
        }
    }

    /**
     * Processes multiple test cases.
     *
     * @param testCnt Number of test cases to process
     * @param in      FastScanner instance for input
     * @param out     PrintWriter instance for output
     */
    private static void solve(int testCnt, FastScanner in, PrintWriter out) {
        for (int t = 0; t < testCnt; t++) {
            int maxZeros = in.nextInt();
            int maxOnes = in.nextInt();
            String s = in.next();

            // Process the string and print the result
            out.println(processString(maxZeros, maxOnes, s));
        }
    }

    /**
     * Attempts to form a palindrome from the input string 's' using at most
     * 'maxZeros' and 'maxOnes'.
     *
     * @param maxZeros Maximum allowed count of '0's
     * @param maxOnes  Maximum allowed count of '1's
     * @param s        The input string containing '0', '1', and '?'
     * @return         The resulting palindrome string, or "-1" if impossible
     */
    private static String processString(int maxZeros, int maxOnes, String s) {
        char[] chars = s.toCharArray();
        int n = chars.length;
        int currentZeros = 0;
        int currentOnes = 0;

        // Pass 1: Validate existing characters and propagate fixed digits to '?'
        // We iterate from the outside in.
        for (int i = 0; i < n / 2; i++) {
            int j = n - 1 - i;
            char left = chars[i];
            char right = chars[j];

            if (left != '?' && right != '?') {
                // Both characters are fixed digits
                if (left != right) {
                    return "-1"; // Mismatch prevents palindrome
                }
                // Count the occurrences
                currentZeros += (left == '0' ? 2 : 0);
                currentOnes += (left == '1' ? 2 : 0);
            } else if (left != '?' && right == '?') {
                // Left is fixed, fill the right '?' with the left character
                chars[j] = left;
                currentZeros += (left == '0' ? 2 : 0);
                currentOnes += (left == '1' ? 2 : 0);
            } else if (left == '?' && right != '?') {
                // Right is fixed, fill the left '?' with the right character
                chars[i] = right;
                currentZeros += (right == '0' ? 2 : 0);
                currentOnes += (right == '1' ? 2 : 0);
            }
            // If both are '?', we leave them for Pass 2

            // Check constraints immediately
            if (currentZeros > maxZeros || currentOnes > maxOnes) {
                return "-1";
            }
        }

        // Handle the middle character for odd length strings
        if (n % 2 != 0) {
            int mid = n / 2;
            if (chars[mid] != '?') {
                currentZeros += (chars[mid] == '0' ? 1 : 0);
                currentOnes += (chars[mid] == '1' ? 1 : 0);
                if (currentZeros > maxZeros || currentOnes > maxOnes) {
                    return "-1";
                }
            }
        }

        // Pass 2: Fill remaining '?' pairs greedily
        // We prefer '0' if capacity allows, otherwise '1'
        for (int i = 0; i < n / 2; i++) {
            int j = n - 1 - i;
            if (chars[i] == '?') { 
                // Since it's a palindrome check, if chars[i] is '?', chars[j] must also be '?'

                // Try to fill with '0'
                if (currentZeros + 2 <= maxZeros) {
                    chars[i] = '0';
                    chars[j] = '0';
                    currentZeros += 2;
                } 
                // Try to fill with '1'
                else if (currentOnes + 2 <= maxOnes) {
                    chars[i] = '1';
                    chars[j] = '1';
                    currentOnes += 2;
                } 
                // Cannot fill with either
                else {
                    return "-1";
                }
            }
        }

        // Pass 3: Fill remaining middle '?' if it exists
        if (n % 2 != 0) {
            int mid = n / 2;
            if (chars[mid] == '?') {
                // Try '0'
                if (currentZeros + 1 <= maxZeros) {
                    chars[mid] = '0';
                    currentZeros++;
                } 
                // Try '1'
                else if (currentOnes + 1 <= maxOnes) {
                    chars[mid] = '1';
                    currentOnes++;
                } 
                // Cannot fill
                else {
                    return "-1";
                }
            }
        }

        return new String(chars);
    }

    /**
     * A fast scanner class for efficient input reading.
     */
    static class FastScanner {
        BufferedReader br;
        StringTokenizer st;

        public FastScanner(InputStream stream) {
            br = new BufferedReader(new InputStreamReader(stream), 32768);
        }

        boolean hasNext() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) {
                        return false;
                    }
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return true;
        }

        String next() {
            if (hasNext()) {
                return st.nextToken();
            }
            return null;
        }

        int nextInt() {
            String s = next();
            if (s == null) throw new RuntimeException("End of input");
            return Integer.parseInt(s);
        }

        long nextLong() {
            String s = next();
            if (s == null) throw new RuntimeException("End of input");
            return Long.parseLong(s);
        }
    }
