    static class PalindromeSolver {
        void solve(InputReader in, PrintWriter out) {
            int n = in.nextInt();
            int targetZeros = in.nextInt();
            int targetOnes = in.nextInt();
            char[] arr = in.next().toCharArray();

            // First pass: resolve conflicts and forced assignments
            for (int i = 0, j = n - 1; i < j; i++, j--) {
                char left = arr[i];
                char right = arr[j];

                if (left == '?' && right == '?') {
                    continue; // Leave for later filling
                } else if (left == '?') {
                    arr[i] = right;
                    if (right == '1') targetOnes -= 2; else targetZeros -= 2;
                } else if (right == '?') {
                    arr[j] = left;
                    if (left == '1') targetOnes -= 2; else targetZeros -= 2;
                } else if (left != right) {
                    out.println(-1);
                    return;
                } else {
                    if (left == '1') targetOnes -= 2; else targetZeros -= 2;
                }
            }

            // Early exit if counts went negative
            if (targetZeros < 0 || targetOnes < 0) {
                out.println(-1);
                return;
            }

            // Handle middle element for odd-length strings
            if (n % 2 == 1) {
                int mid = n / 2;
                if (arr[mid] == '?') {
                    if (targetZeros > 0) {
                        arr[mid] = '0';
                        targetZeros--;
                    } else if (targetOnes > 0) {
                        arr[mid] = '1';
