import java.util.Scanner;

/**
 * A solution class to construct a palindrome string based on given constraints.
 * This refactored version improves maintainability by:
 * 1. Using descriptive variable and method names.
 * 2. Separating logic into distinct passes (Validation, Forced Fills, Free Fills).
 * 3. Using early returns to reduce nesting and complexity.
 * 4. Encapsulating the logic in a method that returns the result string.
 */
public class Solution {

    private static final Scanner scanner = new Scanner(System.in);

    public static void main(String[] args) {
        // Read the number of test cases
        if (scanner.hasNextInt()) {
            int cases = scanner.nextInt();
            for (int i = 0; i < cases; i++) {
                System.out.println(solve());
            }
        }
        scanner.close();
    }

    /**
     * Solves a single test case.
     * 
     * @return The constructed palindrome string or "-1" if impossible.
     */
    private static String solve() {
        // Read inputs
        if (!scanner.hasNextInt()) return "-1";
        int zeros = scanner.nextInt();
        int ones = scanner.nextInt();

        if (!scanner.hasNext()) return "-1";
        String input = scanner.next();
        char[] digits = input.toCharArray();
        int len = digits.length;

        // 1. Validate initial counts against existing characters in the string
        // Decrement available counts based on fixed characters ('0' or '1')
        for (char c : digits) {
            if (c == '0') {
                zeros--;
            } else if (c == '1') {
                ones--;
            }
        }

        // If the string already requires more digits than provided, it's impossible
        if (zeros < 0 || ones < 0) {
            return "-1";
        }

        // 2. Pass 1: Resolve '?' characters that have a determined partner
        // Iterate from outside in up to the middle
        for (int i = 0; i < len / 2; i++) {
            int j = len - 1 - i; // Mirror index

            // If both sides are '?', we handle them in Pass 2
            if (digits[i] == '?' && digits[j] == '?') {
                continue;
            }

            // Identify the required digit based on the non-'?' character
            char requiredDigit = (digits[i] != '?') ? digits[i] : digits[j];

            // Fill the '?' side if necessary
            if (digits[i] == '?') {
                if (requiredDigit == '0') {
                    if (zeros > 0) {
                        digits[i] = '0';
                        zeros--;
                    } else {
                        return "-1"; // Not enough zeros
                    }
                } else { // requiredDigit == '1'
                    if (ones > 0) {
                        digits[i] = '1';
                        ones--;
                    } else {
                        return "-1"; // Not enough ones
                    }
                }
            } else if (digits[j] == '?') {
                if (requiredDigit == '0') {
                    if (zeros > 0) {
                        digits[j] = '0';
                        zeros--;
                    } else {
                        return "-1";
                    }
                } else { // requiredDigit == '1'
                    if (ones > 0) {
                        digits[j] = '1';
                        ones--;
                    } else {
                        return "-1";
                    }
                }
            } else {
                // Both are digits, check for consistency
                if (digits[i] != digits[j]) {
                    return "-1";
                }
            }
        }

        // 3. Pass 2: Fill remaining '?' pairs (which must be ??)
        // These pairs were skipped in Pass 1 because both were '?'
        for (int i = 0; i < len / 2; i++) {
            if (digits[i] == '?') {
                // digits[len - 1 - i] is also '?' here
                // Prefer filling with 0s if available, else 1s
                if (zeros >= 2) {
                    digits[i] = digits[len - 1 - i] = '0';
                    zeros -= 2;
                } else if (ones >= 2) {
                    digits[i] = digits[len - 1 - i] = '1';
                    ones -= 2;
                } else {
                    return "-1"; // Cannot form a pair
                }
            }
        }

        // 4. Handle the middle element if the length is odd
        if (len % 2 != 0) {
            int mid = len / 2;
            if (digits[mid] == '?') {
                if (zeros == 1) {
                    digits[mid] = '0';
                    zeros--;
                } else if (ones == 1) {
                    digits[mid] = '1';
                    ones--;
                } else {
                    return "-1"; // Cannot fill middle
                }
            }
        }

        // 5. Final Validation
        // All counts must be exactly exhausted (0 remaining)
        if (zeros == 0 && ones == 0) {
            return new String(digits);
        } else {
            return "-1";
        }
    }
}

