    /**
     * Solves the palindrome construction problem for a given number of test cases.
     * The algorithm validates symmetry, checks resource availability, fills known pairs,
     * greedily fills unknown pairs, handles the middle character (if odd length),
     * and outputs the result or -1 if impossible.
     */
    static void solve(InputReader in, OutputWriter out) {
        int t = in.nextInt();
        while (t-- > 0) {
            int zerosAvailable = in.nextInt();
            int onesAvailable = in.nextInt();
            String pattern = in.next();
            int n = pattern.length();
            char[] result = pattern.toCharArray();

            // Step 1: Validate existing characters and count required pairs
            int zerosRequired = 0;
            int onesRequired = 0;
            boolean possible = true;

            for (int i = 0; i < n / 2; i++) {
                char left = result[i];
                char right = result[n - 1 - i];

                if (left != '?' && right != '?') {
                    if (left != right) {
                        possible = false;
                        break;
                    }
                    if (left == '0') zerosRequired += 2;
                    else onesRequired += 2;
                } else if (left != '?' || right != '?') {
                    if (left == '0' || right == '0') zerosRequired++;
                    else onesRequired++;
                }
            }

            // Step 2: Check middle character if length is odd
            char middleChar = (n % 2 == 1) ? result[n / 2] : '?';

            // Step 3: Validate if available counts meet requirements
            if (zerosAvailable < zerosRequired || onesAvailable < onesRequired) {
                possible = false;
            }

            // Step 4: Fill symmetric pairs where one side is known
            if (possible) {
                for (int i = 0; i < n / 2; i++) {
                    if (result[i] == '?' && result[n - 1 - i] != '?') {
                        result[i] = result[n - 1 - i];
                    } else if (result[i] != '?' && result[n - 1 - i] == '?') {
                        result[n - 1 - i] = result[i];
                    }
                }
            }

            // Step 5: Fill remaining '?' pairs greedily
            if (possible) {
                for (int i = 0; i < n / 2; i++) {
                    if (result[i] == '?') {
                        if (zerosAvailable >= 2) {
                            result[i] = result[n - 1 - i] = '0';
                            zerosAvailable -= 2;
                        } else if (onesAvailable >= 2) {
                            result[i] = result[n - 1 - i] = '1';
                            onesAvailable -= 2;
                        } else {
                            possible = false;
                            break;
                        }
                    }
                }
            }

            // Step 6: Handle middle character if odd length and still '?'
            if (possible && n % 2 == 1 && result[n / 2] == '?') {
                if (zerosAvailable >= 1) {
                    result[n / 2] = '0';
                    zerosAvailable--;
                } else if (onesAvailable >= 1) {
                    result[n / 2] = '1';
                    onesAvailable--;
                } else {
                    possible = false;
                }
            }

            // Step 7: Output result
            if (possible) {
                out.println(new String(result));
