import java.util.*;

public class PalindromeSolver {

    public static void main(String[] args) {
        FastReader reader = new FastReader();
        StringBuilder output = new StringBuilder();

        try {
            int testCases = reader.nextInt();
            while (testCases-- > 0) {
                int totalZeros = reader.nextInt();
                int totalOnes = reader.nextInt();
                String pattern = reader.next();
                output.append(solve(totalZeros, totalOnes, pattern)).append('\n');
            }
        } catch (Exception e) {
            // Gracefully handle unexpected input errors without crashing
        }

        System.out.print(output);
    }

    /**
     * Attempts to construct a palindrome from the given pattern by replacing '?' characters.
     * The resulting string must contain exactly totalZeros '0's and totalOnes '1's.
     *
     * @param totalZeros  Required count of '0' characters
     * @param totalOnes   Required count of '1' characters
     * @param pattern     Input string containing '0', '1', and '?'
     * @return            The valid palindrome string, or "-1" if impossible
     */
    private static String solve(int totalZeros, int totalOnes, String pattern) {
        int n = pattern.length();
        if (n != totalZeros + totalOnes) {
            return "-1";
        }
        // A palindrome can have at most one character type with an odd count.
        if ((totalZeros % 2 != 0) && (totalOnes % 2 != 0)) {
            return "-1";
        }

        char[] chars = pattern.toCharArray();
        int remZeros = totalZeros;
        int remOnes = totalOnes;

        // Account for characters already fixed in the pattern
        for (char c : chars) {
            if (c == '0') remZeros--;
            else if (c == '1') remOnes--;
        }

        int left = 0;
        int right = n - 1;

        // Pass 1: Resolve fixed characters against '?' and detect immediate mismatches
        while (left < right) {
            char l = chars[left];
            char r = chars[right];

            if (l != '?' && r != '?' && l != r) {
                return "-1";
            } else if (l != '?' && r == '?') {
                chars[right] = l;
                if (l == '0') remZeros--;
                else remOnes--;
            } else if (l == '?' && r != '?') {
                chars[left] = r;
                if (r == '0') remZeros--;
                else remOnes--;
            }

            if (remZeros < 0 || remOnes < 0) {
                return "-1";
            }

            left++;
            right--;
        }

        // Pass 2: Resolve remaining '?' pairs
        left = 0;
        right = n - 1;
        while (left < right) {
            if (chars[left] == '?' && chars[right] == '?') {
                if (remZeros >= 2) {
                    chars[left] = chars[right] = '0';
                    remZeros -= 2;
                } else if (remOnes >= 2) {
                    chars[left] = chars[right] = '1';
                    remOnes -= 2;
                } else {
                    return "-1";
                }
            }
            left++;
            right--;
        }

        // Handle middle element for odd-length strings
        if (n % 2 == 1) {
            int mid = n / 2;
            if (chars[mid] == '?') {
                if (remZeros >= 1) {
                    chars[mid] = '0';
                    remZeros--;
                } else if (remOnes >= 1) {
                    chars[mid] = '1';
                    remOnes--;
                } else {
                    return "-1";
                }
            }
        }

        // Final validation: all required counts must be exactly met
        if (remZeros != 0 || remOnes != 0) {
            return "-1";
        }

        return new String(chars);
    }

    /**
     * Fast I/O helper class optimized for competitive programming.
     */
    static class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    e.printStackTrace();
                    return null;
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            String s = next();
            return s == null ? 0 : Integer.parseInt(s);
        }

        long nextLong() {
            String s = next();
            return s == null ? 0L : Long.parseLong(s);
        }

        double nextDouble() {
            String s = next();
            return s == null ? 0.0 : Double.parseDouble(s);
        }

        String nextLine() {
            String str = "";
            try {
                str = br.readLine();
            } catch (IOException e) {
                e.printStackTrace();
            }
            return str;
        }
    }
}

import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.InputMismatchException;
import java.util.Random;

/**
 * Competitive programming solution for constructing a palindrome from a string
 * containing '0', '1', and '?' characters with exact counts for '0's and '1's.
 */
public class Solution implements Runnable {

    private static final PrintWriter out = new PrintWriter(System.out);
    private static final FastScanner in = new FastScanner(System.in);

    public static void main(String[] args) {
        // Thread trick to avoid StackOverflowError on deep recursion (if any)
        new Thread(null, new Solution(), "1").start();
    }

    @Override
    public void run() {
        try {
            solve();
        } catch (IOException e) {
            throw new RuntimeException("I/O error during execution", e);
        } finally {
            out.close();
        }
    }

    private void solve() throws IOException {
        int t = in.nextInt();
        while (t-- > 0) {
            int zeroCount = in.nextInt();
            int oneCount = in.nextInt();
            char[] arr = in.next().toCharArray();
            int questionMarks = 0;

            // 1. Count existing characters and adjust required counts
            for (char c : arr) {
                if (c == '0') {
                    zeroCount--;
                } else if (c == '1') {
                    oneCount--;
                } else {
                    questionMarks++;
                }
            }

            // Early exit if not enough zeros/ones to fill question marks
            if (questionMarks > zeroCount + oneCount) {
                println(-1);
                continue;
            }

            // 2. Mirror known characters to their symmetric positions
            int len = arr.length;
            for (int i = 0; i < len; i++) {
                int opposite = len - i - 1;
                if (arr[i] != '?' && arr[opposite] == '?') {
                    arr[opposite] = arr[i];
                    if (arr[i] == '0') zeroCount--;
                    else oneCount--;
                    questionMarks--;
                }
            }

            // Check again after mirroring
            if (questionMarks > zeroCount + oneCount) {
                println(-1);
                continue;
            }

            // 3. Fill remaining question marks
            for (int i = 0; i < len; i++) {
                if (arr[i] == '?') {
                    int opposite = len - i - 1;
                    int pairsToFill = (opposite == i) ? 1 : 2;
                    questionMarks -= pairsToFill;

                    if (zeroCount > oneCount) {
                        arr[i] = '0';
                        arr[opposite] = '0';
                        zeroCount -= pairsToFill;
                    } else {
                        arr[i] = '1';
                        arr[opposite] = '1';
                        oneCount -= pairsToFill;
                    }
                }
            }

            // 4. Validate final state
            if (questionMarks != 0 || zeroCount != 0 || oneCount != 0 || !isPalindrome(arr)) {
                println(-1);
            } else {
                println(new String(arr));
            }
        }
    }

    /**
     * Checks if the given character array represents a palindrome.
     */
    private boolean isPalindrome(char[] arr) {
        int left = 0, right = arr.length - 1;
        while (left < right) {
            if (arr[left++] != arr[right--]) {
                return false;
            }
        }
        return true;
    }

    // --- Output Utilities ---
    private static void print(Object object) {
        out.print(object);
    }

    private static void println(Object object) {
        out.println(object);
    }

    // --- Fast I/O Scanner ---
    private static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1024];
        private int ptr = 0;
        private int buflen = 0;

        public FastScanner(InputStream in) {
            this.in = in;
        }

        private int read() throws IOException {
            if (ptr >= buflen) {
                ptr = 0;
                buflen = in.read(buffer);
                if (buflen <= 0) return -1;
            }
            return buffer[ptr++];
        }

        public int nextInt() throws IOException {
            int c = read();
            while (isSpaceChar(c)) c = read();
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9') throw new InputMismatchException();
                res *= 10;
                res += c - '0';
                c = read();
            } while (!isSpaceChar(c));
            return res * sign;
        }

        public String next() throws IOException {
            int c = read();
            while (isSpaceChar(c)) c = read();
            StringBuilder sb = new StringBuilder();
            do {
                sb.append((char) c);
                c = read();
            } while (!isSpaceChar(c));
            return sb.toString();
        }

        public double nextDouble() throws IOException {
            int c = read();
            while (isSpaceChar(c)) c = read();
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            double res = 0;
            do {
                if (c < '0' || c > '9') throw new InputMismatchException();
                res *= 10;
                res += c - '0';
                c = read();
            } while (!isSpaceChar(c) && c != '.');
            if (c == '.') {
                c = read();
                double factor = 0.1;
                while (!isSpaceChar(c)) {
                    if (c < '0' || c > '9') throw new InputMismatchException();
                    res += (c - '0') * factor;
                    factor /= 10;
                    c = read();
                }
            }
            return res * sign;
        }

        private boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }
    }

    // --- Array Utilities (Optional but kept for template compatibility) ---
    private static void shuffle(int[] arr) {
        Random rand = new Random();
        for (int i = arr.length - 1; i > 0; i--) {
            int j = rand.nextInt(i + 1);
            int temp = arr[i];
            arr[i] = arr[j];
            arr[j] = temp;
        }
    }

    private static void shuffle(int[][] arr) {
        Random rand = new Random();
        for (int i = arr.length - 1; i > 0; i--) {
            int j = rand.nextInt(i + 1);
            int[] temp = arr[i];
            arr[i] = arr[j];
            arr[j] = temp;
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

/**
 * Solves a palindrome construction problem.
 * Given counts of '0's and '1's to place, and a template string containing '0', '1', and '?',
 * determines if a valid palindrome can be formed and outputs it, or -1 if impossible.
 */
public class Main {

    public static void main(String[] args) {
        FastReader scanner = new FastReader();
        PrintWriter out = new PrintWriter(System.out);

        try {
            // Read number of test cases
            String tStr = scanner.next();
            if (tStr == null) return;
            int t = Integer.parseInt(tStr);

            while (t-- > 0) {
                int a = scanner.nextInt(); // required count of '0'
                int b = scanner.nextInt(); // required count of '1'
                String s = scanner.next(); // template string

                out.println(solvePalindrome(a, b, s));
            }
        } catch (Exception e) {
            // In competitive programming, unexpected input failures can be silently ignored
            // or logged. Here we ensure clean termination.
        } finally {
            out.flush();
        }
    }

    /**
     * Attempts to fill '?' characters in the string to form a palindrome
     * with exactly `zeroCount` zeros and `oneCount` ones.
     *
     * @param zeroCount  Required number of '0's
     * @param oneCount   Required number of '1's
     * @param template   Input string containing '0', '1', and '?'
     * @return           The filled palindrome string, or "-1" if impossible
     */
    private static String solvePalindrome(int zeroCount, int oneCount, String template) {
        int n = template.length();
        if (zeroCount + oneCount != n) {
            return "-1";
        }

        char[] chars = template.toCharArray();
        int zerosRemaining = zeroCount;
        int onesRemaining = oneCount;

        // Step 1: Validate existing characters don't exceed required counts
        for (char c : chars) {
            if (c == '0') zerosRemaining--;
            else if (c == '1') onesRemaining--;
        }
        if (zerosRemaining < 0 || onesRemaining < 0) {
            return "-1";
        }

        // Step 2: Fill '?' symmetrically from outside in
        for (int i = 0; i <= n / 2; i++) {
            int j = n - 1 - i;
            char left = chars[i];
            char right = chars[j];

            if (left == '?' && right == '?') {
                if (i == j) {
                    // Middle character of odd-length string
                    if (zerosRemaining > 0) {
                        chars[i] = '0';
                        zerosRemaining--;
                    } else if (onesRemaining > 0) {
                        chars[i] = '1';
                        onesRemaining--;
                    } else {
                        return "-1";
                    }
                } else {
                    // Symmetric pair
                    if (zerosRemaining >= 2) {
                        chars[i] = '0';
                        chars[j] = '0';
                        zerosRemaining -= 2;
                    } else if (onesRemaining >= 2) {
                        chars[i] = '1';
                        chars[j] = '1';
                        onesRemaining -= 2;
                    } else {
                        return "-1";
                    }
                }
            } else if (left == '?') {
                // Left is unknown, right is known
                chars[i] = right;
                if (right == '0') zerosRemaining--;
                else onesRemaining--;
            } else if (right == '?') {
                // Right is unknown, left is known
                chars[j] = left;
                if (left == '0') zerosRemaining--;
                else onesRemaining--;
            } else if (left != right) {
                // Both known but mismatched -> cannot be palindrome
                return "-1";
            }
        }

        // Step 3: Ensure all required characters were used
        if (zerosRemaining != 0 || onesRemaining != 0) {
            return "-1";
        }

        return new String(chars);
    }

    /**
     * Lightweight fast I/O helper to handle whitespace-separated tokens efficiently.
     */
    static class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input", e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            String token = next();
            return token == null ? 0 : Integer.parseInt(token);
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

/**
 * Refactored solution for generating a palindrome with specific counts of '0's and '1's.
 * 
 * Refactoring improvements:
 * 1. Class Renaming: Renamed 'a' to 'PalindromeSolver' for descriptive naming.
 * 2. Code Organization: Extracted the core logic into a 'solve()' method to reduce 
 *    nesting and improve readability.
 * 3. Variable Naming: Replaced cryptic variables (zcnt, ocnt, arr) with descriptive names 
 *    (zerosCount, onesCount, chars).
 * 4. Input Handling: Fixed a potential bug where mixing nextInt() and nextLine() could 
 *    cause issues with newline consumption. Used sc.next() for the string token.
 * 5. Logic Optimization: Optimized loop bounds to iterate only up to n/2 where appropriate.
 * 6. Safety: Added null checks and improved error handling in the FastReader.
 * 7. Cleanup: Removed unused constants (mod) and redundant imports.
 */
public class PalindromeSolver {

    private static final FastReader sc = new FastReader();
    private static final PrintWriter out = new PrintWriter(System.out);

    public static void main(String[] args) {
        try {
            // Check if input exists before attempting to read
            if (sc.hasNext()) {
                int t = sc.nextInt();
                while (t-- > 0) {
                    solve();
                }
            }
        } catch (Exception e) {
            e.printStackTrace();
        } finally {
            out.flush();
        }
    }

    private static void solve() {
        int zerosCount = sc.nextInt();
        int onesCount = sc.nextInt();

        // Use next() to read the pattern string. 
        // This consumes the string token and handles preceding whitespace/newlines automatically,
        // avoiding issues with nextInt() leaving a newline character in the buffer.
        String pattern = sc.next();
        char[] chars = pattern.toCharArray();
        int n = chars.length;

        // 1. Propagate known characters to symmetric positions to satisfy palindrome property
        // We only need to iterate up to the middle of the array
        for (int i = 0; i < n / 2; i++) {
            char left = chars[i];
            char right = chars[n - 1 - i];

            if (left != '?' && right == '?') {
                chars[n - 1 - i] = left;
            } else if (right != '?' && left == '?') {
                chars[i] = right;
            }
        }

        // 2. Update counts based on characters filled so far
        for (char c : chars) {
            if (c == '0') {
                zerosCount--;
            } else if (c == '1') {
                onesCount--;
            }
        }

        // 3. Check if the palindrome constraint is already violated
        boolean isPalindrome = true;
        for (int i = 0; i < n / 2; i++) {
            if (chars[i] != chars[n - 1 - i]) {
                isPalindrome = false;
                break;
            }
        }

        // If counts are negative or palindrome structure is broken, output -1
        if (zerosCount < 0 || onesCount < 0 || !isPalindrome) {
            out.println(-1);
            return;
        }

        // 4. Fill remaining '?' pairs
        for (int i = 0; i < n / 2; i++) {
            if (chars[i] == '?') {
                // To fill a pair (i, n-1-i), we need at least 2 of the same character
                if (Math.max(zerosCount, onesCount) < 2) {
                    isPalindrome = false;
                    break;
                }

                // Greedily fill with the character that has more remaining count
                if (zerosCount > onesCount) {
                    chars[i] = '0';
                    chars[n - 1 - i] = '0';
                    zerosCount -= 2;
                } else {
                    chars[i] = '1';
                    chars[n - 1 - i] = '1';
                    onesCount -= 2;
                }
            }
        }

        // 5. Handle the middle character for odd-length strings
        if (n % 2 != 0 && chars[n / 2] == '?') {
            if (zerosCount > 0) {
                chars[n / 2] = '0';
                zerosCount--;
            } else if (onesCount > 0) {
                chars[n / 2] = '1';
                onesCount--;
            } else {
                // No characters left to fill the middle
                isPalindrome = false;
            }
        }

        // 6. Final validation and output
        if (zerosCount < 0 || onesCount < 0 || !isPalindrome) {
            out.println(-1);
        } else {
            out.println(new String(chars));
        }
    }

    /**
     * FastReader utility class for faster input reading.
     */
    static class FastReader {
        BufferedReader br;
        StringTokenizer st;

        public FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    e.printStackTrace();
                    return null;
                }
            }
            return st.nextToken();
        }

        boolean hasNext() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return false;
                    if (line.trim().isEmpty()) continue; // Skip empty lines
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    return false;
                }
            }
            return true;
        }

        int nextInt() {
            String s = next();
            if (s == null) return 0;
            return Integer.parseInt(s);
        }

        long nextLong() {
            String s = next();
            if (s == null) return 0L;
            return Long.parseLong(s);
        }

        double nextDouble() {
            String s = next();
            if (s == null) return 0.0;
            return Double.parseDouble(s);
        }

        String nextLine() {
            String str = "";
            try {
                str = br.readLine();
            } catch (IOException e) {
                e.printStackTrace();
            }
            return str;
        }
    }
}

import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter out = new PrintWriter(System.out);

        String line = br.readLine();
        if (line != null) {
            int t = Integer.parseInt(line.trim());
            while (t-- > 0) {
                String[] parts = br.readLine().trim().split("\\s+");
                int zeros = Integer.parseInt(parts[0]);
                int ones = Integer.parseInt(parts[1]);
                String pattern = br.readLine().trim();

                out.println(solve(zeros, ones, pattern));
            }
        }
        out.flush();
    }

    /**
     * Attempts to fill '?' characters in the pattern to form a valid palindrome
     * with exactly the specified number of '0's and '1's.
     *
     * @param zeros Required count of '0' characters
     * @param ones  Required count of '1' characters
     * @param pattern Input string containing '0', '1', and '?'
     * @return Valid palindrome string, or "-1" if impossible
     */
    private static String solve(int zeros, int ones, String pattern) {
        int n = pattern.length();

        // Parity check: In a palindrome, characters must be placed symmetrically.
        // If length is even, both counts must be even. If odd, exactly one count must be odd.
        if ((n % 2 == 0) && (zeros % 2 != 0 || ones % 2 != 0)) {
            return "-1";
        }

        char[] s = pattern.toCharArray();
        int rem0 = zeros;
        int rem1 = ones;

        // Update remaining counts based on already placed characters
        for (char c : s) {
            if (c == '0') rem0--;
            else if (c == '1') rem1--;
        }

        // If the pattern already contains more characters than allowed, it's invalid
        if (rem0 < 0 || rem1 < 0) {
            return "-1";
        }

        // First pass: resolve positions where exactly one side of the pair is '?'
        for (int i = 0; i < n / 2; i++) {
            char left = s[i];
            char right = s[n - 1 - i];

            if (left == '?' && right == '?') {
                continue; // Defer to second pass
            } else if (left == '?') {
                s[i] = right;
                if (right == '0') rem0--;
                else rem1--;
            } else if (right == '?') {
                s[n - 1 - i] = left;
                if (left == '0') rem0--;
                else rem1--;
            } else if (left != right) {
                return "-1"; // Fixed characters mismatch breaks palindrome property
            }
        }

        // Second pass: fill remaining symmetric '?' pairs
        for (int i = 0; i < n / 2; i++) {
            if (s[i] == '?') {
                if (rem0 >= 2) {
                    s[i] = s[n - 1 - i] = '0';
                    rem0 -= 2;
                } else if (rem1 >= 2) {
                    s[i] = s[n - 1 - i] = '1';
                    rem1 -= 2;
                } else {
                    return "-1"; // Not enough characters to complete the pair
                }
            }
        }

        // Handle the middle character for odd-length strings
        if (n % 2 == 1) {
            if (s[n / 2] == '?') {
                if (rem0 > 0) {
                    s[n / 2] = '0';
                    rem0--;
                } else if (rem1 > 0) {
                    s[n / 2] = '1';
                    rem1--;
                } else {
                    return "-1"; // Cannot fill the center character
                }
            }
        }

        // Final validation: all required counts must be exactly exhausted
        if (rem0 != 0 || rem1 != 0) {
            return "-1";
        }

        return new String(s);
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
