import java.util.StringTokenizer;

/**
 * Main entry point for solving palindrome construction problems with character count constraints.
 */
public class Main {

    public static void main(String[] args) {
        FastScanner sc = new FastScanner();
        PrintWriter out = new PrintWriter(System.out);

        int testCases = sc.nextInt();
        while (testCases-- > 0) {
            solve(sc, out);
        }

        out.flush();
        out.close();
    }

    /**
     * Solves a single test case: constructs a palindrome from a string containing '0', '1', and '?',
     * matching exact target counts for '0's and '1's.
     */
    private static void solve(FastScanner sc, PrintWriter out) {
        int targetZeroCount = sc.nextInt();
        int targetOneCount = sc.nextInt();
        String s = sc.next();
        int n = s.length();

        // Basic validation: total characters must match target counts
        if (targetZeroCount + targetOneCount != n) {
            out.println("-1");
            return;
        }

        char[] chars = s.toCharArray();
        int currentZeroCount = 0;
        int currentOneCount = 0;

        // Count existing fixed characters
        for (char c : chars) {
            if (c == '0') currentZeroCount++;
            else if (c == '1') currentOneCount++;
        }

        int remainingZeros = targetZeroCount - currentZeroCount;
        int remainingOnes = targetOneCount - currentOneCount;

        // If we already exceed the allowed counts, it's impossible
        if (remainingZeros < 0 || remainingOnes < 0) {
            out.println("-1");
            return;
        }

        // Two-pointer approach to fill '?' and validate palindrome structure
        for (int i = 0, j = n - 1; i <= j; i++, j--) {
            if (i == j) {
                // Middle character for odd-length strings
                if (chars[i] == '?') {
                    if (remainingZeros == 1) {
                        chars[i] = '0';
                        remainingZeros = 0;
                    } else if (remainingOnes == 1) {
                        chars[i] = '1';
                        remainingOnes = 0;
                    } else {
                        out.println("-1");
                        return;
                    }
                }
            } else {
                char left = chars[i];
                char right = chars[j];

                if (left != '?' && right != '?') {
                    // Both sides are fixed; must match for palindrome property
                    if (left != right) {
                        out.println("-1");
                        return;
                    }
                } else if (left == '?' && right == '?') {
                    // Both sides are unknown; assign based on remaining counts
                    if (remainingZeros >= 2) {
                        chars[i] = '0';
                        chars[j] = '0';
                        remainingZeros -= 2;
                    } else if (remainingOnes >= 2) {
                        chars[i] = '1';
                        chars[j] = '1';
                        remainingOnes -= 2;
                    } else {
                        out.println("-1");
                        return;
                    }
                } else {
                    // One side is known, the other is unknown; mirror the known character
                    char known = (left == '?') ? right : left;
                    chars[i] = known;
                    chars[j] = known;
                    if (known == '0') remainingZeros--;
                    else remainingOnes--;
                }
            }
        }

        // Final validation: all target counts must be met exactly
        if (remainingZeros == 0 && remainingOnes == 0) {
            out.println(new String(chars));
        } else {
            out.println("-1");
        }
    }

    /**
     * Fast input reader for competitive programming and performance-critical applications.
     */
    static class FastScanner {
        private final BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        private StringTokenizer st = new StringTokenizer("");

        public String next() {
            while (!st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input", e);
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }

        public double nextDouble() {
            return Double.parseDouble(next());
        }

        public String nextLine() {
            try {
                return br.readLine();
            } catch (IOException e) {
                throw new RuntimeException("Failed to read line", e);
            }
        }

        public int[] readArray(int n) {
            int[] a = new int[n];
            for (int i = 0; i < n; i++) {
                a[i] = nextInt();
            }
            return a;
        }

        public long[] readArrayLong(int n) {
