import java.io.IOException;
import java.io.InputStream;
import java.util.InputMismatchException;

public class Solution {

    public static void main(String[] args) {
        InputReader reader = new InputReader(System.in);
        StringBuilder output = new StringBuilder();

        int testCases = reader.readInt();
        for (int t = 1; t <= testCases; t++) {
            int targetEven = reader.readInt();
            int targetOdd = reader.readInt();
            String input = reader.readString();
            output.append(new Solution().solve(targetEven, targetOdd, input)).append('\n');
        }
        System.out.print(output);
    }

    /**
     * Solves the problem by enforcing palindrome symmetry and greedily filling 
     * remaining '?' characters to meet the target even/odd digit counts.
     */
    public String solve(int targetEven, int targetOdd, String input) {
        char[] chars = input.toCharArray();
        int n = chars.length;

        // Step 1: Enforce palindrome symmetry on '?' pairs
        for (int i = 0; i < (n + 1) / 2; i++) {
            char left = chars[i];
            char right = chars[n - i - 1];

            if (left == '?' && right == '?') {
                continue;
            } else if (left == '?') {
                chars[i] = right;
            } else if (right == '?') {
                chars[n - i - 1] = left;
            } else if (left != right) {
                return "-1"; // Symmetry constraint violated
            }
        }

        // Step 2: Count current even/odd digits and identify remaining '?'
        int currentEven = 0;
        int currentOdd = 0;

        for (char c : chars) {
            if (c == '?') {
                continue;
            }
            if ((c - '0') % 2 == 0) {
                currentEven++;
            } else {
                currentOdd++;
            }
        }

        int remainingEven = targetEven - currentEven;
        int remainingOdd = targetOdd - currentOdd;

        // Step 3: Fill remaining '?' pairs greedily
        for (int i = 0; i < (n + 1) / 2; i++) {
            if (chars[i] == '?') {
                boolean isMiddle = (i == n - i - 1);
                int pairSize = isMiddle ? 1 : 2;

                // Prefer filling with '0' (even) if we need more or equal evens
                if (remainingEven >= remainingOdd) {
                    chars[i] = chars[n - i - 1] = '0';
                    remainingEven -= pairSize;
                } else {
                    chars[i] = chars[n - i - 1] = '1';
                    remainingOdd -= pairSize;
                }
            }

            // Check feasibility after each assignment
            if (remainingEven < 0 || remainingOdd < 0) {
                return "-1";
            }
        }

        return new String(chars);
    }
}

/**
 * Fast I/O helper class for competitive programming environments.
 */
class InputReader {
    private final InputStream stream;
    private final byte[] buffer = new byte[1024];
    private int currentChar;
    private int numberOfChars;

    public InputReader(InputStream stream) {
        this.stream = stream;
    }

    public int read() {
        if (numberOfChars == -1) {
            throw new InputMismatchException();
        }
        if (currentChar >= numberOfChars) {
            currentChar = 0;
            try {
                numberOfChars = stream.read(buffer);
            } catch (IOException e) {
                throw new InputMismatchException();
            }
            if (numberOfChars <= 0) {
                return -1;
            }
        }
        return buffer[currentChar++];
    }

    private boolean isSpace(int c) {
        return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
    }

    public int readInt() {
        int c = read();
        while (isSpace(c)) {
            c = read();
        }

        int sign = 1;
        if (c == '-') {
            sign = -1;
            c = read();
        }

        int result = 0;
        do {
            if (c < '0' || c > '9') {
                throw new InputMismatchException();
            }
            result *= 10;
            result += (c - '0');
            c = read();
        } while (!isSpace(c));
        return sign * result;
    }

    public long readLong() {
        int c = read();
        while (isSpace(c)) {
            c = read();
        }

        int sign = 1;
        if (c == '-') {
            sign = -1;
            c = read();
        }

        long result = 0;
        do {
            if (c < '0' || c > '9') {
                throw new InputMismatchException();
            }
            result *= 10;
            result += (c - '0');
            c = read();
        } while (!isSpace(c));
        return sign * result;
    }

    public double readDouble() {
        int c = read();
        while (isSpace(c)) {
            c = read();
        }

        int sign = 1;
        if (c == '-') {
            sign = -1;
            c = read();
        }

        double result = 0.0;
        while (!isSpace(c) && c != '.') {
            if (c == 'e' || c == 'E') {
                return result * Math.pow(10, readInt());
            }
            if (c < '0' || c > '9') {
                throw new InputMismatchException();
            }
            result *= 10;
            result += (c - '0');
            c = read();
        }
        if (c == '.') {
            c = read();
            double multiplier = 1.0;
            while (!isSpace(c)) {
                if (c == 'e' || c == 'E') {
                    return result * Math.pow(10, readInt());
                }
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                multiplier /= 10.0;
                result += (c - '0') * multiplier;
                c = read();
            }
        }
        return result * sign;
    }

    public String readString() {
        int c = read();
        while (isSpace(c)) {
            c = read();
        }
        StringBuilder result = new StringBuilder();
        do {
            result.appendCodePoint(c);
            c = read();
        } while (!isSpace(c));
        return result.toString();
    }
}

import java.util.Scanner;

/**
 * Solves palindrome construction problems by replacing '?' characters with '0' or '1'
 * while respecting budget constraints for each digit.
 */
public class PalindromeBuilder {

    public static void main(String[] args) {
        // try-with-resources ensures the Scanner is properly closed
        try (Scanner scanner = new Scanner(System.in)) {
            if (scanner.hasNextInt()) {
                int testCases = scanner.nextInt();
                while (testCases-- > 0) {
                    int maxZeros = scanner.nextInt();
                    int maxOnes = scanner.nextInt();
                    String sequence = scanner.next();

                    System.out.println(solvePalindrome(maxZeros, maxOnes, sequence));
                }
            }
        }
    }

    /**
     * Attempts to convert the input sequence into a valid palindrome.
     *
     * @param maxZeros Maximum allowed '0' characters
     * @param maxOnes  Maximum allowed '1' characters
     * @param sequence Input string containing '0', '1', and '?'
     * @return The resulting palindrome string, or "-1" if impossible
     */
    public static String solvePalindrome(int maxZeros, int maxOnes, String sequence) {
        char[] chars = sequence.toCharArray();
        int n = chars.length;

        // Calculate remaining budget after accounting for fixed characters
        int remainingZeros = maxZeros;
        int remainingOnes = maxOnes;

        for (char c : chars) {
            if (c == '0') remainingZeros--;
            else if (c == '1') remainingOnes--;
        }

        // Budget already violated by fixed characters
        if (remainingZeros < 0 || remainingOnes < 0) {
            return "-1";
        }

        // First pass: Resolve pairs where exactly one side is known
        for (int i = 0; i < n / 2; i++) {
            char left = chars[i];
            char right = chars[n - 1 - i];

            if (left == '?' && right == '?') {
                continue;
            } else if (left == '?') {
                if (right == '0') {
                    if (remainingZeros > 0) { chars[i] = '0'; remainingZeros--; }
                    else return "-1";
                } else {
                    if (remainingOnes > 0) { chars[i] = '1'; remainingOnes--; }
                    else return "-1";
                }
            } else if (right == '?') {
                if (left == '0') {
                    if (remainingZeros > 0) { chars[n - 1 - i] = '0'; remainingZeros--; }
                    else return "-1";
                } else {
                    if (remainingOnes > 0) { chars[n - 1 - i] = '1'; remainingOnes--; }
                    else return "-1";
                }
            } else if (left != right) {
                // Both sides are known but don't match
                return "-1";
            }
        }

        // Count remaining completely unknown pairs
        int unknownPairs = 0;
        for (int i = 0; i < n / 2; i++) {
            if (chars[i] == '?') {
                unknownPairs++;
            }
        }

        // Fill unknown pairs if any exist
        if (unknownPairs > 0) {
            if (remainingZeros / 2 >= unknownPairs) {
                fillRemainingPairs(chars, '0', unknownPairs);
                remainingZeros -= unknownPairs * 2;
            } else if (remainingOnes / 2 >= unknownPairs) {
                fillRemainingPairs(chars, '1', unknownPairs);
                remainingOnes -= unknownPairs * 2;
            } else {
                return "-1";
            }
        }

        // Handle the middle character for odd-length strings
        if (n % 2 == 1 && chars[n / 2] == '?') {
            if (remainingZeros > 0) {
                chars[n / 2] = '0';
                remainingZeros--;
            } else if (remainingOnes > 0) {
                chars[n / 2] = '1';
                remainingOnes--;
            } else {
                return "-1";
            }
        }

        return new String(chars);
    }

    /**
     * Fills the first 'count' unknown symmetric pairs in the character array.
     */
    private static void fillRemainingPairs(char[] chars, char value, int count) {
        for (int i = 0; i < chars.length / 2; i++) {
            if (chars[i] == '?') {
                chars[i] = value;
                chars[chars.length - 1 - i] = value;
                count--;
                if (count == 0) break;
            }
        }
    }
}

