/**
 * Builds a palindrome string from a pattern containing '0', '1', and '?'.
 * Ensures the result contains exactly the specified number of zeros and ones.
 */
public class PalindromeBuilder {

    public static void main(String[] args) {
        FastReader reader = new FastReader();
        int testCases = reader.nextInt();

        while (testCases-- > 0) {
            int zeros = reader.nextInt();
            int ones = reader.nextInt();
            String pattern = reader.next();

            System.out.println(solve(zeros, ones, pattern));
        }
    }

    /**
     * Attempts to fill '?' characters to form a valid palindrome with the exact
     * counts of '0's and '1's. Returns the result or "-1" if impossible.
     */
    private static String solve(int zeros, int ones, String pattern) {
        int len = pattern.length();
        char[] chars = pattern.toCharArray();

        // 1. Adjust available counts based on characters already present in the pattern
        for (char c : chars) {
            if (c == '0') zeros--;
            else if (c == '1') ones--;
        }

        // 2. First pass: Resolve forced pairs (one side fixed, other is '?')
        for (int i = 0; i < len / 2; i++) {
            char left = chars[i];
            char right = chars[len - 1 - i];

            if (left == '?' && right == '?') {
                continue; // Both unknown, handled in pass 3
            } else if (left == '?') {
                chars[i] = right;
                if (right == '0') zeros--;
                else ones--;
            } else if (right == '?') {
                chars[len - 1 - i] = left;
                if (left == '0') zeros--;
                else ones--;
            } else if (left != right) {
                return "-1"; // Mismatched fixed characters
            }
        }

        // 3. Second pass: Fill remaining '?' pairs symmetrically
        for (int i = 0; i < len / 2; i++) {
            if (chars[i] == '?') {
                if (zeros >= 2) {
                    chars[i] = '0';
                    chars[len - 1 - i] = '0';
                    zeros -= 2;
                } else if (ones >= 2) {
                    chars[i] = '1';
                    chars[len - 1 - i] = '1';
                    ones -= 2;
                } else {
                    return "-1"; // Cannot form symmetric pairs
                }
            }
        }

        // 4. Handle middle character for odd-length strings
        if (len % 2 == 1 && chars[len / 2] == '?') {
            if (zeros > 0) {
                chars[len / 2] = '0';
                zeros--;
            } else if (ones > 0) {
                chars[len / 2] = '1';
                ones--;
            } else {
                return "-1"; // No characters left for the middle
            }
        }

        // 5. Final validation: All required characters must be used
        if (zeros == 0 && ones == 0) {
            return new String(chars);
        }
        return "-1";
    }

    /**
     * Fast input reader for competitive programming and performance-critical tasks.
     */
    static class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Input reading failed", e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            String token = next();
            return token == null ? 0 : Integer.parseInt(token);
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

/**
 * Refactored Palindrome Generator.
 * This program solves the problem of constructing a palindrome string
 * given the required counts of '0's and '1's and a template string.
 * 
 * Refactoring improvements:
 * - Renamed class to descriptive name.
 * - Extracted logic into a dedicated 'solve' method.
 * - Improved variable naming (zeroCount, oneCount, chars).
 * - Simplified palindrome logic and validation.
 * - Used StringBuilder for efficient output buffering.
 * - Added comments for clarity.
 */
public class PalindromeGenerator {

    public static void main(String[] args) throws IOException {
        // Use BufferedReader for efficient input reading
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));

        // Read number of test cases
        String line = reader.readLine();
        if (line == null || line.trim().isEmpty()) {
            return;
        }

        int t;
        try {
            t = Integer.parseInt(line.trim());
        } catch (NumberFormatException e) {
            return;
        }

        StringBuilder output = new StringBuilder();

        while (t-- > 0) {
            // Read a (count of '0') and b (count of '1')
            String countsLine = reader.readLine();
            if (countsLine == null) break;

            StringTokenizer st = new StringTokenizer(countsLine);
            if (!st.hasMoreTokens()) break;
            int zeroCount = Integer.parseInt(st.nextToken());

            if (!st.hasMoreTokens()) break;
            int oneCount = Integer.parseInt(st.nextToken());

            // Read the pattern string s
            String s = reader.readLine();
            if (s == null) break;
            s = s.trim();

            String result = solve(zeroCount, oneCount, s);
            output.append(result).append("\n");
        }
        System.out.print(output);
    }

    /**
     * Attempts to construct a palindrome based on the given character counts and pattern.
     *
     * @param zeroCount The required number of '0' characters.
     * @param oneCount  The required number of '1' characters.
     * @param s         The input string containing '0', '1', and '?'.
     * @return          The constructed palindrome string, or "-1" if impossible.
     */
    private static String solve(int zeroCount, int oneCount, String s) {
        char[] chars = s.toCharArray();
        int n = chars.length;

        // 1. Pre-validation: Check if existing characters exceed the allowed counts
        int currentZeros = 0;
        int currentOnes = 0;
        for (char c : chars) {
            if (c == '0') currentZeros++;
            else if (c == '1') currentOnes++;
        }

        if (currentZeros > zeroCount || currentOnes > oneCount) {
            return "-1";
        }

        // Deduct existing characters from the required counts
        zeroCount -= currentZeros;
        oneCount -= currentOnes;

        // 2. Enforce Palindrome Symmetry
        // Iterate through the first half of the string
        for (int i = 0; i < n / 2; i++) {
            char left = chars[i];
            char right = chars[n - 1 - i];

            // If both are fixed characters and they differ, it's impossible
            if (left != '?' && right != '?' && left != right) {
                return "-1";
            }

            // If one is '?' and the other is fixed, fill the '?'
            if (left == '?' && right != '?') {
                chars[i] = right;
                if (right == '0') zeroCount--;
                else oneCount--;
            } else if (left != '?' && right == '?') {
                chars[n - 1 - i] = left;
                if (left == '0') zeroCount--;
                else oneCount--;
            }
        }

        // 3. Fill remaining '?' pairs
        // Iterate through the first half again to fill pairs of '?'
        for (int i = 0; i < n / 2; i++) {
            if (chars[i] == '?') {
                // We need to fill a pair (chars[i] and chars[n-1-i])
                if (zeroCount >= 2) {
                    chars[i] = '0';
                    chars[n - 1 - i] = '0';
                    zeroCount -= 2;
                } else if (oneCount >= 2) {
                    chars[i] = '1';
                    chars[n - 1 - i] = '1';
                    oneCount -= 2;
                } else {
                    // Cannot fill the pair with available counts
                    return "-1";
                }
            }
        }

        // 4. Handle the center element (if the string length is odd)
        if (n % 2 == 1) {
            int mid = n / 2;
            if (chars[mid] == '?') {
                if (zeroCount >= 1) {
                    chars[mid] = '0';
                    zeroCount--;
                } else if (oneCount >= 1) {
                    chars[mid] = '1';
                    oneCount--;
                } else {
                    // Cannot fill the center element
                    return "-1";
                }
            }
        }

        // 5. Final Validation
        // Counts must be exactly zero. 
        if (zeroCount == 0 && oneCount == 0) {
            return new String(chars);
        } else {
            return "-1";
        }
    }
}

import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        // Reading the number of test cases
        if (scanner.hasNextInt()) {
            int t = scanner.nextInt();
            while (t-- > 0) {
                solve(scanner);
            }
        }
        scanner.close();
    }

    /**
     * Reads input for a single test case and processes it.
     */
    private static void solve(Scanner scanner) {
        // Reading a (count of 0s) and b (count of 1s)
        if (!scanner.hasNextInt()) return;
        int countZeros = scanner.nextInt();
        int countOnes = scanner.nextInt();

        // Consume the newline character after reading integers
        scanner.nextLine();

        // Reading the string
        if (!scanner.hasNextLine()) return;
        String inputString = scanner.nextLine();

        // Process the test case and print result
        String result = buildPalindrome(countZeros, countOnes, inputString);
        System.out.println(result);
    }

    /**
     * Constructs a palindrome string with exactly 'a' zeros and 'b' ones
     * based on the input string which may contain '?' placeholders.
     * 
     * @param a Number of 0s required
     * @param b Number of 1s required
     * @param s Input string containing '0', '1', and '?'
     * @return The constructed palindrome string or "-1" if impossible
     */
    private static String buildPalindrome(int a, int b, String s) {
        int n = s.length();

        // Constraint: Total characters required must match string length
        if (a + b != n) {
            return "-1";
        }

        char[] chars = s.toCharArray();

        // Count existing characters to determine what needs to be filled
        int currentZeros = 0;
        int currentOnes = 0;

        for (char c : chars) {
            if (c == '0') currentZeros++;
            else if (c == '1') currentOnes++;
        }

        // If we already have more characters than allowed, it's impossible
        if (currentZeros > a || currentOnes > b) {
            return "-1";
        }

        // Calculate remaining characters needed
        int remZeros = a - currentZeros;
        int remOnes = b - currentOnes;

        // Step 1: Fill '?' based on symmetry (Outer to Inner)
        // Iterate through the first half of the array to enforce palindrome property
        for (int i = 0; i < n / 2; i++) {
            int left = i;
            int right = n - 1 - i;

            if (chars[left] == '?' && chars[right] != '?') {
                chars[left] = chars[right];
            } else if (chars[left] != '?' && chars[right] == '?') {
                chars[right] = chars[left];
            }
        }

        // Step 2: Handle Middle Element (if length is odd)
        if (n % 2 != 0) {
            int mid = n / 2;
            if (chars[mid] == '?') {
                // The middle element must take the character with the odd remaining count.
                // Since a + b = n (odd), exactly one of remZeros or remOnes must be odd.
                if (remZeros % 2 != 0) {
                    chars[mid] = '0';
                    remZeros--;
                } else if (remOnes % 2 != 0) {
                    chars[mid] = '1';
                    remOnes--;
                } else {
                    // If both are even, we can't fill the middle '?' with a single character
                    return "-1";
                }
            }
        }

        // Step 3: Fill remaining '?' pairs
        // Any remaining '?' must be in symmetric pairs (i, n-1-i).
        // Also, remZeros and remOnes must be even because we handled the odd middle element.
        if (remZeros % 2 != 0 || remOnes % 2 != 0) {
            return "-1";
        }

        // Fill pairs with 0s
        int pairsOfZeros = remZeros / 2;
        for (int i = 0; i < n / 2 && pairsOfZeros > 0; i++) {
            if (chars[i] == '?') {
                chars[i] = '0';
                chars[n - 1 - i] = '0';
                pairsOfZeros--;
            }
        }

        // Fill pairs with 1s
        int pairsOfOnes = remOnes / 2;
        for (int i = 0; i < n / 2 && pairsOfOnes > 0; i++) {
            if (chars[i] == '?') {
                chars[i] = '1';
                chars[n - 1 - i] = '1';
                pairsOfOnes--;
            }
        }

        // Step 4: Final Validation
        // Check if any '?' remain unfilled
        for (char c : chars) {
            if (c == '?') return "-1";
        }

        // Check if palindrome (redundant but safe)
        for (int i = 0; i < n / 2; i++) {
            if (chars[i] != chars[n - 1 - i]) return "-1";
        }

        return new String(chars);
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

public class Main {
    public static void main(String[] args) {
        FastScanner scanner = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out);

        int testCases = scanner.nextInt();
        CABPalindromeSolver solver = new CABPalindromeSolver();
        for (int i = 1; i <= testCases; i++) {
            solver.solve(i, scanner, out);
        }

        out.flush();
        out.close();
    }

    /**
     * Solves the CABPalindrome problem for a single test case.
     */
    static class CABPalindromeSolver {
        public void solve(int testNumber, FastScanner in, PrintWriter out) {
            int targetZeros = in.nextInt();
            int targetOnes = in.nextInt();
            String s = in.next();
            char[] arr = s.toCharArray();
            int n = arr.length;

            // Step 1: Propagate known digits to their mirror positions
            for (int i = 0; i < n; i++) {
                if (arr[i] != '?' && arr[n - 1 - i] == '?') {
                    arr[n - 1 - i] = arr[i];
                }
            }

            // Step 2: Count current digits and question marks
            int currentZeros = 0;
            int currentOnes = 0;
            int questionMarks = 0;
            for (char c : arr) {
                if (c == '0') currentZeros++;
                else if (c == '1') currentOnes++;
                else if (c == '?') questionMarks++;
            }

            // Step 3: Calculate remaining required digits
            int remainingZeros = targetZeros - currentZeros;
            int remainingOnes = targetOnes - currentOnes;

            // Step 4: Validate feasibility
            if (remainingZeros < 0 || remainingOnes < 0 || remainingZeros + remainingOnes != questionMarks) {
                out.println("-1");
                return;
            }

            // If no question marks remain, the string is already determined
            if (questionMarks == 0) {
                out.println(arr);
                return;
            }

            // A palindrome can have at most one character type with an odd count
            if (remainingZeros % 2 != 0 && remainingOnes % 2 != 0) {
                out.println("-1");
                return;
            }

            // Step 5: Place the odd-count character in the middle (if applicable)
            int mid = n / 2;
            if (remainingZeros % 2 != 0) {
                arr[mid] = '0';
                remainingZeros--;
            } else if (remainingOnes % 2 != 0) {
                arr[mid] = '1';
                remainingOnes--;
            }

            // Step 6: Fill remaining question marks in symmetric pairs
            for (int i = 0; i < n; i++) {
                if (arr[i] == '?') {
                    if (remainingZeros > 0) {
                        arr[i] = '0';
                        arr[n - 1 - i] = '0';
                        remainingZeros -= 2;
                    } else {
                        arr[i] = '1';
                        arr[n - 1 - i] = '1';
                        remainingOnes -= 2;
                    }
                }
            }

            out.println(arr);
        }
    }

    /**
     * Fast I/O helper class for competitive programming / performance-critical tasks.
     */
    static class FastScanner {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastScanner(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input", e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            String token = next();
            return token == null ? 0 : Integer.parseInt(token);
        }
    }
}

import java.io.InputStream;
import java.io.IOException;
import java.io.OutputStream;
import java.io.PrintWriter;
import java.util.InputMismatchException;

public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        TaskC solver = new TaskC();
        int testCount = Integer.parseInt(in.next());
        for (int i = 1; i <= testCount; i++) {
            solver.solve(i, in, out);
        }
        out.close();
    }

    static class TaskC {
        public void solve(int testNumber, InputReader in, PrintWriter out) {
            int zeros = in.readInt();
            int ones = in.readInt();
            int n = zeros + ones;
            char[] chars = in.readCharArray(n);

            int l = 0;
            int r = n - 1;

            // First pass: Resolve fixed pairs, handle '?' mirroring, and process the middle element
            while (l <= r) {
                if (l == r) {
                    // Middle element of an odd-length string
                    if (chars[l] == '0') {
                        if (zeros <= 0) { out.println(-1); return; }
                        zeros--;
                    } else if (chars[l] == '1') {
                        if (ones <= 0) { out.println(-1); return; }
                        ones--;
                    } else { // chars[l] == '?'
                        if (zeros + ones <= 0) { out.println(-1); return; }
                        // Greedy strategy: assign '0' if zeros count is odd, otherwise '1'
                        if (zeros % 2 == 1) {
                            zeros--;
                            chars[l] = '0';
                        } else {
                            ones--;
                            chars[l] = '1';
                        }
                    }
                } else {
                    char left = chars[l];
                    char right = chars[r];

                    // Invalid case: mismatched fixed characters cannot form a palindrome
                    if ((left == '0' && right == '1') || (left == '1' && right == '0')) {
                        out.println(-1);
                        return;
                    }

                    if (left == '?' && right == '?') {
                        // Defer filling to the second pass
                        l++;
                        r--;
                        continue;
                    }

                    if (left == right) {
                        if (left == '0') {
                            if (zeros < 2) { out.println(-1); return; }
                            zeros -= 2;
                        } else { // left == '1'
                            if (ones < 2) { out.println(-1); return; }
                            ones -= 2;
                        }
                    } else {
                        // One side is '?', the other is fixed. Mirror the fixed character.
                        char fixed = (left == '?') ? right : left;
                        if (fixed == '0') {
                            if (zeros < 2) { out.println(-1); return; }
                            zeros -= 2;
                            chars[l] = chars[r] = '0';
                        } else { // fixed == '1'
                            if (ones < 2) { out.println(-1); return; }
                            ones -= 2;
                            chars[l] = chars[r] = '1';
                        }
                    }
                }
                l++;
                r--;
            }

            // Second pass: Fill remaining '?' pairs with available counts
            l = 0;
            r = n - 1;
            while (l < r) {
                if (chars[l] == '?' && chars[r] == '?') {
                    if (ones >= 2) {
                        chars[l] = chars[r] = '1';
                        ones -= 2;
                    } else if (zeros >= 2) {
                        chars[l] = chars[r] = '0';
                        zeros -= 2;
                    } else {
                        out.println(-1);
                        return;
                    }
                }
                l++;
                r--;
            }

            // Final validation: ensure all character counts are exactly exhausted
            if (zeros != 0 || ones != 0) {
                out.println(-1);
                return;
            }

            out.println(chars);
        }
    }

    static class InputReader {
        private InputStream stream;
        private byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;
        private SpaceCharFilter filter;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        public char[] readCharArray(int size) {
            char[] array = new char[size];
            for (int i = 0; i < size; i++) {
                array[i] = readCharacter();
            }
            return array;
        }

        public int read() {
            if (numChars == -1) {
                throw new InputMismatchException();
            }
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0) {
                    return -1;
                }
            }
            return buf[curChar++];
        }

        public int readInt() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                res *= 10;
                res += c - '0';
                c = read();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public String readString() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            StringBuilder res = new StringBuilder();
            do {
                if (Character.isValidCodePoint(c)) {
                    res.appendCodePoint(c);
                }
                c = read();
            } while (!isSpaceChar(c));
            return res.toString();
        }

        public boolean isSpaceChar(int c) {
            if (filter != null) {
                return filter.isSpaceChar(c);
            }
            return isWhitespace(c);
        }

        public static boolean isWhitespace(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        public char readCharacter() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            return (char) c;
        }

        public String next() {
            return readString();
        }

        public interface SpaceCharFilter {
            boolean isSpaceChar(int ch);
        }
    }
}

import java.io.*;

/**
 * Refactored solution for constructing a valid palindrome under character count constraints.
 * 
 * Improvements over the original:
 * - Descriptive class, method, and variable names
 * - Early returns eliminate deep nesting and boolean flag toggling
 * - Clear separation of algorithmic phases (parsing, validation, symmetric filling, parity handling, final fill)
 * - Robust input splitting and null-safety
 * - Comprehensive inline documentation
 */
public class PalindromeConstructor {

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out));

        try {
            String line = br.readLine();
            if (line != null && !line.trim().isEmpty()) {
                int t = Integer.parseInt(line.trim());
                while (t-- > 0) {
                    solve(br, out);
                }
            }
        } finally {
            out.flush();
        }
    }

    private static void solve(BufferedReader br, PrintWriter out) throws IOException {
        // Phase 1: Parse input
        String[] parts = br.readLine().trim().split("\\s+");
        int maxZeros = Integer.parseInt(parts[0]);
        int maxOnes = Integer.parseInt(parts[1]);
        String input = br.readLine();
        char[] chars = input.toCharArray();

        // Phase 2: Validate initial counts and count unresolved question marks
        int remainingZeros = maxZeros;
        int remainingOnes = maxOnes;
        int questionMarks = 0;

        for (char c : chars) {
            if (c == '0') remainingZeros--;
            else if (c == '1') remainingOnes--;
            else if (c == '?') questionMarks++;
        }

        if (remainingZeros < 0 || remainingOnes < 0) {
            out.println(-1);
            return;
        }

        // Phase 3: Two-pointer pass to resolve symmetric question marks
        int left = 0;
        int right = chars.length - 1;
        while (left <= right) {
            // Both sides are fixed characters
            if (chars[left] != '?' && chars[right] != '?') {
                if (chars[left] != chars[right]) {
                    out.println(-1);
                    return;
                }
                left++;
                right--;
                continue;
            }

            // Both sides are question marks; defer to later phases
            if (chars[left] == '?' && chars[right] == '?') {
                left++;
                right--;
                continue;
            }

            // Exactly one side is '?'; mirror the known character
            if (chars[left] == '?') {
                if (chars[right] == '0') {
                    remainingZeros--;
                    chars[left] = '0';
                } else {
                    remainingOnes--;
                    chars[left] = '1';
                }
            } else { // chars[right] == '?'
                if (chars[left] == '0') {
                    remainingZeros--;
                    chars[right] = '0';
                } else {
                    remainingOnes--;
                    chars[right] = '1';
                }
            }

            questionMarks--;
            if (remainingZeros < 0 || remainingOnes < 0) {
                out.println(-1);
                return;
            }
            left++;
            right--;
        }

        // If all question marks are resolved, we're done
        if (questionMarks == 0) {
            out.println(new String(chars));
            return;
        }

        // Phase 4: Handle parity for the center character
        // A palindrome can have at most one character with an odd count.
        boolean hasOddZeros = (remainingZeros & 1) == 1;
        boolean hasOddOnes = (remainingOnes & 1) == 1;
        boolean hasOddQuestionMarks = (questionMarks & 1) == 1;

        if (hasOddZeros) remainingZeros--;
        if (hasOddOnes) remainingOnes--;
        if (hasOddQuestionMarks) questionMarks--;

        if (hasOddQuestionMarks) {
            int mid = chars.length / 2;
            if (hasOddZeros) {
                chars[mid] = '0';
            } else if (hasOddOnes) {
                chars[mid] = '1';
            } else {
                out.println(-1);
                return;
            }
        }

        // Phase 5: Fill remaining symmetric pairs from the outside in
        if (remainingZeros + remainingOnes < questionMarks) {
            out.println(-1);
            return;
        }

        left = 0;
        right = chars.length - 1;
        while (left < right) {
            if (chars[left] == '?') {
                if (remainingZeros > 0) {
                    chars[left] = chars[right] = '0';
                    remainingZeros -= 2;
                } else if (remainingOnes > 0) {
                    chars[left] = chars[right] = '1';
                    remainingOnes -= 2;
                }
            }
            left++;
            right--;
        }

        out.println(new String(chars));
    }
}

import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        // Use try-with-resources to ensure Scanner is closed properly
        try (Scanner scanner = new Scanner(System.in)) {
            if (scanner.hasNextInt()) {
                int t = scanner.nextInt();
                while (t-- > 0) {
                    int maxZeros = scanner.nextInt();
                    int maxOnes = scanner.nextInt();
                    String inputString = scanner.next();
                    System.out.println(solve(maxZeros, maxOnes, inputString));
                }
            }
        }
    }

    /**
     * Attempts to construct a palindrome from the input string using the available counts of '0's and '1's.
     * 
     * @param maxZeros The maximum number of '0's available to use.
     * @param maxOnes  The maximum number of '1's available to use.
     * @param inputString The string containing '0', '1', and '?'.
     * @return The constructed palindrome string, or "-1" if it's impossible.
     */
    private static String solve(int maxZeros, int maxOnes, String inputString) {
        char[] charArray = inputString.toCharArray();
        int n = charArray.length;

        // Phase 1: Validate palindrome structure and propagate known characters.
        // We iterate through the first half of the string.
        for (int i = 0; i < (n + 1) / 2; i++) {
            int left = i;
            int right = n - 1 - i;

            if (charArray[left] != '?' && charArray[right] != '?') {
                // Both characters are fixed. They must match for a valid palindrome.
                if (charArray[left] != charArray[right]) {
                    return "-1";
                }
            } else if (charArray[left] == '?' && charArray[right] != '?') {
                // Left is unknown, right is known. Propagate right to left.
                charArray[left] = charArray[right];
            } else if (charArray[left] != '?' && charArray[right] == '?') {
                // Left is known, right is unknown. Propagate left to right.
                charArray[right] = charArray[left];
            }
            // If both are '?', we leave them for the filling phase.
        }

        // Phase 2: Count current usage and check feasibility against budget.
        int currentZeros = 0;
        int currentOnes = 0;
        int questionMarks = 0;

        for (char c : charArray) {
            if (c == '0') {
                currentZeros++;
            } else if (c == '1') {
                currentOnes++;
            } else if (c == '?') {
                questionMarks++;
            }
        }

        // Check if the fixed characters already exceed the available budget
        if (currentZeros > maxZeros || currentOnes > maxOnes) {
            return "-1";
        }

        int remainingZeros = maxZeros - currentZeros;
        int remainingOnes = maxOnes - currentOnes;

        // The sum of remaining available characters must exactly match the number of '?' slots
        if (remainingZeros + remainingOnes != questionMarks) {
            return "-1";
        }

        // Phase 3: Fill remaining '?' slots.
        // We must fill pairs symmetrically to maintain the palindrome property.
        int left = 0;
        int right = n - 1;

        while (left < right) {
            if (charArray[left] == '?') {
                // Both charArray[left] and charArray[right] are '?' here.
                // We must fill them with the same character.
                if (remainingZeros >= 2) {
                    charArray[left] = '0';
                    charArray[right] = '0';
                    remainingZeros -= 2;
                } else if (remainingOnes >= 2) {
                    charArray[left] = '1';
                    charArray[right] = '1';
                    remainingOnes -= 2;
                } else {
                    // Not enough characters to fill the pair
                    return "-1";
                }
            }
            left++;
            right--;
        }

        // Handle the middle element if the string length is odd
        if (n % 2 != 0) {
            int mid = n / 2;
            if (charArray[mid] == '?') {
                if (remainingZeros >= 1) {
                    charArray[mid] = '0';
                    remainingZeros--;
                } else if (remainingOnes >= 1) {
                    charArray[mid] = '1';
                    remainingOnes--;
                } else {
                    // Not enough characters to fill the middle
                    return "-1";
                }
            }
        }

        return new String(charArray);
    }
}

