        try {
            testCases = Integer.parseInt(line.trim());
        } catch (NumberFormatException e) {
            return;
        }

        StringBuilder output = new StringBuilder();

        for (int t = 1; t <= testCases; t++) {
            // Read a (count of '0's) and b (count of '1's)
            String inputLine = reader.readLine();
            if (inputLine == null) break;

            StringTokenizer st = new StringTokenizer(inputLine);
            int a = Integer.parseInt(st.nextToken()); 
            int b = Integer.parseInt(st.nextToken()); 

            // Read the string s
            String s = reader.readLine();
            if (s == null) break;

            // Solve the test case
            String result = solve(a, b, s);
            output.append(result).append("\n");
        }
        System.out.print(output);
    }

    /**
     * Solves the palindrome construction problem.
     * 
     * @param a The number of '0's available.
     * @param b The number of '1's available.
     * @param s The input string containing '0', '1', and '?'.
     * @return The constructed palindrome string, or "-1" if impossible.
     */
    private static String solve(int a, int b, String s) {
        char[] chars = s.toCharArray();
        int n = chars.length;

        int count0 = a;
        int count1 = b;

        // 1. Process pairs from the outside in
        for (int i = 0; i < n / 2; i++) {
            int left = i;
            int right = n - 1 - i;
            char leftChar = chars[left];
            char rightChar = chars[right];

            if (leftChar != '?' && rightChar != '?') {
                // Both characters are known
                if (leftChar != rightChar) {
                    return "-1"; // Mismatch found
                }
                // Decrement the count for the matching digit
                if (leftChar == '0') count0 -= 2;
                else count1 -= 2;
            } else if (leftChar == '?' && rightChar != '?') {
                // Left is unknown, fill it with the right character
                chars[left] = rightChar;
                if (rightChar == '0') count0 -= 2;
                else count1 -= 2;
            } else if (leftChar != '?' && rightChar == '?') {
                // Right is unknown, fill it with the left character
                chars[right] = leftChar;
                if (leftChar == '0') count0 -= 2;
                else count1 -= 2;
            } else {
                // Both are '?', they will be filled later
            }

            // Check if we have exceeded the available counts
            if (count0 < 0 || count1 < 0) {
                return "-1";
            }
        }

        // 2. Handle the middle character if the length is odd
        if (n % 2 != 0) {
            int mid = n / 2;
            if (chars[mid] == '?') {
                // Middle is unknown. It must consume a single '0' or '1'.
                // This implies the remaining count for that digit must be odd.
                if (count0 % 2 != 0) {
                    chars[mid] = '0';
                    count0--;
                } else if (count1 % 2 != 0) {
                    chars[mid] = '1';
                    count1--;
                } else {
                    // Neither count is odd, impossible to fill the middle
                    return "-1";
                }
            } else {
                // Middle is known, just decrement the count
                if (chars[mid] == '0') count0--;
                else count1--;
            }

            if (count0 < 0 || count1 < 0) {
                return "-1";
            }
        }

        // 3. Validate remaining counts and fill remaining '?' pairs
        // Remaining counts must be non-negative and even (since they fill pairs)
        if (count0 < 0 || count1 < 0 || count0 % 2 != 0 || count1 % 2 != 0) {
            return "-1";
        }

        // Count how many pairs of '?' are left to be filled
        int unknownPairs = 0;
        for (int i = 0; i < n / 2; i++) {
            if (chars[i] == '?') {
                unknownPairs++;
            }
        }

        // Calculate required pairs based on remaining counts
        int requiredPairs = (count0 / 2) + (count1 / 2);

        // If the number of available '?' pairs doesn't match the required pairs, it's impossible
        if (unknownPairs != requiredPairs) {
            return "-1";
        }

        // 4. Fill the remaining '?' pairs
        for (int i = 0; i < n / 2; i++) {
            if (chars[i] == '?') {
                // Fill the pair (i, n-1-i)
                if (count0 > 0) {
                    chars[i] = '0';
                    chars[n - 1 - i] = '0';
                    count0 -= 2;
                } else {
                    chars[i] = '1';
                    chars[n - 1 - i] = '1';
                    count1 -= 2;
                }
            }
        }

        return new String(chars);
    }
}

