/**
 * Solves palindrome construction problems with character constraints.
 * Reads test cases, each containing available counts of '0's and '1's,
 * and a template string containing '0', '1', and '?'.
 * Constructs a valid palindrome using exactly the available characters,
 * or returns -1 if impossible.
 */
public class PalindromeBuilder {

    public static void main(String[] args) throws IOException {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer tokenizer = new StringTokenizer(reader.readLine());

        int testCases = Integer.parseInt(tokenizer.nextToken());
        StringBuilder output = new StringBuilder();

        for (int t = 0; t < testCases; t++) {
            // Read counts for '0' and '1'
            String line1 = reader.readLine();
            while (line1 != null && line1.trim().isEmpty()) {
                line1 = reader.readLine();
            }
            if (line1 == null) break;
            tokenizer = new StringTokenizer(line1);

            int countZeros = Integer.parseInt(tokenizer.nextToken());
            int countOnes = Integer.parseInt(tokenizer.nextToken());

            // Read template string
            String template = reader.readLine().trim();

            // Process and append result
            output.append(solve(countZeros, countOnes, template)).append('\n');
        }
        System.out.print(output);
    }

    /**
     * Attempts to construct a palindrome from the given pattern using exactly
     * the specified counts of '0's and '1's.
     *
     * @param countZeros Number of available '0' characters
     * @param countOnes  Number of available '1' characters
     * @param pattern    Template string containing '0', '1', and '?'
     * @return The constructed palindrome, or "-1" if impossible
     */
    private static String solve(int countZeros, int countOnes, String pattern) {
        int n = pattern.length();

        // Validation: total characters must exactly match available counts
        if (countZeros + countOnes != n) {
            return "-1";
        }

        char[] result = new char[n];
        int left = 0;
        int right = n - 1;

        // Phase 1: Propagate known constraints and detect conflicts
        while (left <= right) {
            char leftChar = pattern.charAt(left);
            char rightChar = pattern.charAt(right);

            if (leftChar == '?' && rightChar == '?') {
                // Both unknown, mark as pending for Phase 2
                result[left] = '?';
                result[right] = '?';
            } else if (leftChar == '?' || rightChar == '?') {
                // One known, one unknown: propagate the known character
                char knownChar = (leftChar != '?') ? leftChar : rightChar;
                result[left] = knownChar;
                result[right] = knownChar;
                if (knownChar == '0') countZeros--;
                else countOnes--;
            } else {
                // Both known: verify they match
                if (leftChar != rightChar) {
                    return "-1"; // Conflict prevents palindrome formation
                }
                result[left] = leftChar;
                result[right] = rightChar;
                if (leftChar == '0') countZeros--;
                else countOnes--;
            }

            // Move inward; break if we've reached the middle element
            if (left == right) break;
            left++;
            right--;
        }

        // Fail if propagation consumed more characters than available
        if (countZeros < 0 || countOnes < 0) {
            return "-1";
        }

        // Phase 2: Fill remaining '?' placeholders
        left = 0;
        right = n - 1;
        while (left <= right) {
            if (result[left] == '?') {
                if (left == right) {
                    // Middle element (odd-length string)
                    if (countZeros >= 1) {
                        result[left] = '0';
                        countZeros--;
                    } else if (countOnes >= 1) {
                        result[left] = '1';
                        countOnes--;
                    } else {
                        return "-1";
                    }
                } else {
                    // Symmetric pair (even-length requirement)
                    if (countZeros >= 2) {
                        result[left] = '0';
                        result[right] = '0';
                        countZeros -= 2;
                    } else if (countOnes >= 2) {
                        result[left] = '1';
                        result[right] = '1';
                        countOnes -= 2;
                    } else {
                        return "-1";
                    }
                }
            }

            if (left == right) break;
            left++;
            right--;
        }

        // Final validation: exactly zero counts must remain
        if (countZeros != 0 || countOnes != 0) {
            return "-1";
        }

        return new String(result);
    }
}

import java.util.Scanner;

public class Main {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        if (scanner.hasNextInt()) {
            int testCases = scanner.nextInt();
            while (testCases-- > 0) {
                int requiredZeros = scanner.nextInt();
                int requiredOnes = scanner.nextInt();
                String inputString = scanner.next();
                System.out.println(buildPalindrome(requiredZeros, requiredOnes, inputString));
            }
        }
        scanner.close();
    }

    /**
     * Constructs a palindrome containing exactly {@code a} zeros and {@code b} ones.
     * Returns "-1" if no valid palindrome can be formed.
     */
    private static String buildPalindrome(int a, int b, String s) {
        int n = s.length();
        // Total characters must match the sum of required zeros and ones
        if (a + b != n) {
            return "-1";
        }

        char[] chars = s.toCharArray();
        int currentZeros = 0;
        int currentOnes = 0;
        boolean middleEmpty = false;

        // First pass: resolve forced '?' characters based on palindrome symmetry
        for (int i = 0; i < n / 2; i++) {
            int j = n - 1 - i;
            if (chars[i] != '?' && chars[j] != '?') {
                if (chars[i] != chars[j]) {
                    return "-1"; // Non-matching fixed characters break palindrome property
                }
            } else if (chars[i] == '?' && chars[j] != '?') {
                chars[i] = chars[j];
            } else if (chars[i] != '?' && chars[j] == '?') {
                chars[j] = chars[i];
            }
        }

        // Handle middle character for odd-length strings
        if (n % 2 == 1) {
            if (chars[n / 2] == '?') {
                middleEmpty = true;
            } else if (chars[n / 2] == '0') {
                currentZeros++;
            } else {
                currentOnes++;
            }
        }

        // Count existing zeros and ones after forced resolution
        for (char c : chars) {
            if (c == '0') currentZeros++;
            else if (c == '1') currentOnes++;
        }

        // Early exit if we already exceed the required counts
        if (currentZeros > a || currentOnes > b) {
            return "-1";
        }

        int remainingZeros = a - currentZeros;
        int remainingOnes = b - currentOnes;

        // Count unresolved '?' pairs in the first half
        int unresolvedPairs = 0;
        for (int i = 0; i < n / 2; i++) {
            if (chars[i] == '?') {
                unresolvedPairs++;
            }
        }

        // Validation: remaining counts must exactly match available slots
        if (remainingZeros + remainingOnes != 2 * unresolvedPairs + (middleEmpty ? 1 : 0)) {
            return "-1";
        }
        // Parity constraint: if no middle slot exists, remainingZeros must be even
        // because each pair contributes 0 or 2 zeros.
        if (!middleEmpty && remainingZeros % 2 != 0) {
            return "-1";
        }

        // Second pass: fill remaining '?' characters optimally
        int pairsForZero = remainingZeros / 2;
        for (int i = 0; i < n / 2; i++) {
            int j = n - 1 - i;
            if (chars[i] == '?') {
                if (pairsForZero > 0) {
                    chars[i] = chars[j] = '0';
                    pairsForZero--;
                } else {
                    chars[i] = chars[j] = '1';
                }
            }
        }

        // Assign the middle character if it was unresolved
        if (middleEmpty) {
            chars[n / 2] = (remainingZeros % 2 == 1) ? '0' : '1';
        }

        return new String(chars);
    }
}

import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        // Read the number of test cases
        if (scanner.hasNextInt()) {
            int testCases = scanner.nextInt();

            // Process each test case
            while (testCases-- > 0) {
                solve(scanner);
            }
        }

        scanner.close();
    }

    /**
     * Processes a single test case to construct a palindrome.
     * 
     * @param scanner The Scanner object to read input from.
     */
    private static void solve(Scanner scanner) {
        // Read the maximum allowed counts for '0' and '1'
        int remainingZeros = scanner.nextInt();
        int remainingOnes = scanner.nextInt();

        // Consume the newline character after reading integers
        scanner.nextLine();

        // Read the pattern string containing '?' placeholders
        String pattern = scanner.nextLine();
        char[] chars = pattern.toCharArray();
        int n = chars.length;

        // Pass 1: Propagate known characters to ensure symmetry.
        // If one side of the palindrome is known ('0' or '1') and the other is '?',
        // fill the '?' with the known character.
        for (int i = 0; i < (n + 1) / 2; i++) {
            int j = n - 1 - i;
            if (chars[i] == '?' && chars[j] != '?') {
                chars[i] = chars[j];
            } else if (chars[i] != '?' && chars[j] == '?') {
                chars[j] = chars[i];
            }
        }

        // Count existing '0's and '1's to determine how many more are needed
        int currentZeros = 0;
        int currentOnes = 0;
        for (char c : chars) {
            if (c == '0') {
                currentZeros++;
            } else if (c == '1') {
                currentOnes++;
            }
        }

        // Update remaining counts by subtracting existing characters
        remainingZeros -= currentZeros;
        remainingOnes -= currentOnes;

        // Pass 2: Fill remaining '?' characters.
        // Priority is given to '0' then '1' to satisfy the counts.
        for (int i = 0; i < (n + 1) / 2; i++) {
            int j = n - 1 - i;

            // If the current position is still '?', we need to fill it.
            // Due to Pass 1, if chars[i] is '?', chars[j] is also '?' (unless i==j).
            if (chars[i] == '?') {
                if (i == j) {
                    // Case: Center element of an odd-length string (needs 1 char)
                    if (remainingZeros > 0) {
                        chars[i] = '0';
                        remainingZeros--;
                    } else if (remainingOnes > 0) {
                        chars[i] = '1';
                        remainingOnes--;
                    }
                } else {
                    // Case: Symmetric pair (needs 2 identical chars)
                    // We must fill with 2 '0's or 2 '1's to maintain palindrome property.
                    if (remainingZeros >= 2) {
                        chars[i] = chars[j] = '0';
                        remainingZeros -= 2;
                    } else if (remainingOnes >= 2) {
                        chars[i] = chars[j] = '1';
                        remainingOnes -= 2;
                    }
                }
            }
        }

        // Validation: Verify the string is a valid palindrome
        boolean isPalindrome = true;
        for (int i = 0; i < n / 2; i++) {
            if (chars[i] != chars[n - 1 - i]) {
                isPalindrome = false;
                break;
            }
        }

        // Output the result
        // Valid if all character counts are exactly met and the string is a palindrome
        if (remainingZeros == 0 && remainingOnes == 0 && isPalindrome) {
            System.out.println(new String(chars));
        } else {
            System.out.println(-1);
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

/**
 * Refactored solution for generating a palindrome string with specific counts of '0's and '1's.
 * Reads multiple test cases, each specifying required counts of '0' (a) and '1' (b),
 * and a template string containing '0', '1', and '?'. Attempts to replace '?'s to satisfy
 * the counts while maintaining palindrome symmetry. Outputs -1 if impossible.
 */
public class Main {
    private static final char CHAR_ZERO = '0';
    private static final char CHAR_ONE = '1';
    private static final char CHAR_QUESTION = '?';

    public static void main(String[] args) throws IOException {
        FastReader sc = new FastReader(System.in);
        PrintWriter pw = new PrintWriter(System.out);

        try {
            String tStr = sc.next();
            if (tStr != null) {
                int t = Integer.parseInt(tStr);
                while (t-- > 0) {
                    solve(sc, pw);
                }
            }
        } finally {
            pw.flush();
        }
    }

    private static void solve(FastReader sc, PrintWriter pw) throws IOException {
        int a = sc.nextInt();
        int b = sc.nextInt();
        String sStr = sc.next();
        int n = sStr.length();

        if (a + b != n) {
            pw.println(-1);
            return;
        }

        char[] s = sStr.toCharArray();
        int count0 = 0;
        int count1 = 0;
        int countQ = 0;

        // Phase 1: Process symmetric pairs and resolve forced '?'s
        for (int i = 0; i < n / 2; i++) {
            char left = s[i];
            char right = s[n - 1 - i];

            if (left != CHAR_QUESTION && right != CHAR_QUESTION) {
                if (left != right) {
                    pw.println(-1);
                    return;
                }
                if (left == CHAR_ZERO) count0 += 2;
                else count1 += 2;
            } else if (left == CHAR_QUESTION && right == CHAR_QUESTION) {
                countQ += 2;
            } else {
                // One side is known, propagate to the other to maintain palindrome
                char known = (left == CHAR_QUESTION) ? right : left;
                s[i] = s[n - 1 - i] = known;
                if (known == CHAR_ZERO) count0 += 2;
                else count1 += 2;
            }
        }

        // Phase 2: Handle middle element if string length is odd
        if (n % 2 == 1) {
            char mid = s[n / 2];
            if (mid == CHAR_ZERO) count0++;
            else if (mid == CHAR_ONE) count1++;
            else countQ++;
        }

        // Phase 3: Validate basic feasibility
        if (count0 > a || count1 > b || count0 + count1 + countQ != a + b) {
            pw.println(-1);
            return;
        }

        // Phase 4: Fill remaining '?'s to meet exact counts
        int needed0 = a - count0;
        int needed1 = b - count1;

        // Fill symmetric pairs first
        for (int i = 0; i < n / 2; i++) {
            if (s[i] == CHAR_QUESTION) {
                if (needed0 >= 2) {
                    s[i] = s[n - 1 - i] = CHAR_ZERO;
                    needed0 -= 2;
                } else if (needed1 >= 2) {
                    s[i] = s[n - 1 - i] = CHAR_ONE;
                    needed1 -= 2;
                } else {
                    pw.println(-1);
                    return;
                }
            }
        }

        // Fill middle element if it's still '?'
        if (n % 2 == 1 && s[n / 2] == CHAR_QUESTION) {
            if (needed0 > 0) {
                s[n / 2] = CHAR_ZERO;
                needed0--;
            } else if (needed1 > 0) {
                s[n / 2] = CHAR_ONE;
                needed1--;
            } else {
                pw.println(-1);
                return;
            }
        }

        // Final validation
        if (needed0 == 0 && needed1 == 0) {
            pw.println(s);
        } else {
            pw.println(-1);
        }
    }

    /**
     * Fast I/O helper class optimized for competitive programming.
     */
    static class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastReader(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        String next() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) return null;
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

        int nextInt() throws IOException {
            String s = next();
            return s == null ? 0 : Integer.parseInt(s);
        }

        long nextLong() throws IOException {
            String s = next();
            return s == null ? 0L : Long.parseLong(s);
        }
    }
}

import java.io.BufferedWriter;
import java.io.IOException;
import java.io.OutputStreamWriter;
import java.util.Scanner;

public class Main {

    public static void main(String[] args) throws IOException {
        // Use try-with-resources to ensure resources are closed properly.
        // Scanner wraps System.in, and BufferedWriter wraps System.out.
        try (Scanner sc = new Scanner(System.in);
             BufferedWriter output = new BufferedWriter(new OutputStreamWriter(System.out))) {

            // Check if input exists before reading
            if (sc.hasNextInt()) {
                int t = sc.nextInt();
                for (int i = 0; i < t; i++) {
                    solveTestCase(sc, output);
                }
            }
        }
    }

    /**
     * Solves a single test case: constructs a palindrome string with specific counts of '0' and '1'.
     * 
     * @param sc   The Scanner to read input from
     * @param output The BufferedWriter to write output to
     * @throws IOException If an I/O error occurs
     */
    private static void solveTestCase(Scanner sc, BufferedWriter output) throws IOException {
        // Read target counts
        int targetZeroCount = sc.nextInt();
        int targetOneCount = sc.nextInt();

        // Read the pattern string
        String inputString = sc.next();
        char[] chars = inputString.toCharArray();
        int length = chars.length;

        int currentZeroCount = 0;
        int currentOneCount = 0;

        // 1. Count existing characters in the string
        for (char c : chars) {
            if (c == '0') {
                currentZeroCount++;
            } else if (c == '1') {
                currentOneCount++;
            }
        }

        // 2. First Pass: Sync '?' characters with their symmetric counterparts.
        // If one side of the pair is known, copy it to the '?' side.
        for (int i = 0; i < length / 2; i++) {
            char left = chars[i];
            char right = chars[length - 1 - i];

            if (left == '?' && right != '?') {
                chars[i] = right;
                if (right == '0') currentZeroCount++;
                else currentOneCount++;
            } else if (right == '?' && left != '?') {
                chars[length - 1 - i] = left;
                if (left == '0') currentZeroCount++;
                else currentOneCount++;
            }
        }

        // 3. Second Pass: Fill remaining '?' pairs (where both are '?').
        // Greedily fill with '0' if we need more zeros than ones, otherwise '1'.
        for (int i = 0; i < length / 2; i++) {
            if (chars[i] == '?' && chars[length - 1 - i] == '?') {
                int remainingZeros = targetZeroCount - currentZeroCount;
                int remainingOnes = targetOneCount - currentOneCount;

                if (remainingZeros > remainingOnes) {
                    chars[i] = '0';
                    chars[length - 1 - i] = '0';
                    currentZeroCount += 2;
                } else {
                    chars[i] = '1';
                    chars[length - 1 - i] = '1';
                    currentOneCount += 2;
                }
            }
        }

        // 4. Handle the middle element if the string length is odd
        if (length % 2 == 1) {
            int midIndex = length / 2;
            if (chars[midIndex] == '?') {
                if (currentZeroCount < targetZeroCount) {
                    chars[midIndex] = '0';
                    currentZeroCount++;
                } else {
                    chars[midIndex] = '1';
                    currentOneCount++;
                }
            }
        }

        // 5. Validation
        // Check if the string is a palindrome
        boolean isPalindrome = true;
        for (int i = 0; i < length / 2; i++) {
            if (chars[i] != chars[length - 1 - i]) {
                isPalindrome = false;
                break;
            }
        }
        // A single character string is always a palindrome
        if (length == 1) {
            isPalindrome = true;
        }

        // Check if the final counts match the targets
        boolean countsMatch = (currentZeroCount == targetZeroCount) && (currentOneCount == targetOneCount);

        // Output result
        if (countsMatch && isPalindrome) {
            output.write(new String(chars));
        } else {
            output.write("-1");
        }
        output.write("\n");
    }
}

import java.util.Scanner;

public class Main {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        // Safely read the number of test cases
        if (scanner.hasNextInt()) {
            int numTestCases = scanner.nextInt();

            for (int t = 0; t < numTestCases; t++) {
                int countOnes = scanner.nextInt();
                int countZeros = scanner.nextInt();
                String pattern = scanner.next();

                // Delegate business logic to a dedicated method
                System.out.println(solve(countOnes, countZeros, pattern));
            }
        }

        scanner.close();
    }

    /**
     * Validates and constructs a palindrome given counts of '0's and '1's.
     * Returns "-1" if no valid palindrome can be formed.
     */
    private static String solve(int countOnes, int countZeros, String pattern) {
        int length = pattern.length();

        // Basic validation: total characters must match the pattern length
        if (countOnes + countZeros != length) {
            return "-1";
        }

        char[] chars = pattern.toCharArray();

        // Handle the middle character for odd-length strings
        if (length % 2 != 0) {
            int mid = length / 2;
            if (chars[mid] == '?') {
                // Exactly one count must be odd for the middle position
                if (countOnes % 2 != 0) {
                    countOnes--;
                    chars[mid] = '1';
                } else {
                    countZeros--;
                    chars[mid] = '0';
                }
            } else if (chars[mid] == '1') {
                countOnes--;
            } else {
                countZeros--;
            }

            // Early exit if counts go negative
            if (countOnes < 0 || countZeros < 0) {
                return "-1";
            }
        } else {
            // Even-length strings require even counts for both characters
            if (countOnes % 2 != 0 || countZeros % 2 != 0) {
                return "-1";
            }
        }

        // First pass: Validate symmetry and resolve fixed '?' pairs
        for (int i = 0, j = length - 1; i < j; i++, j--) {
            char left = chars[i];
            char right = chars[j];

            if (left == '?' && right != '?') {
                chars[i] = right;
                if (right == '1') countOnes -= 2;
                else countZeros -= 2;
            } else if (left != '?' && right == '?') {
                chars[j] = left;
                if (left == '1') countOnes -= 2;
                else countZeros -= 2;
            } else if (left != '?' && right != '?' && left != right) {
                return "-1"; // Conflicting fixed characters break palindrome property
            } else if (left == '1') {
                countOnes -= 2;
            } else if (left == '0') {
                countZeros -= 2;
            }
        }

        // Second pass: Fill remaining '?' pairs with available counts
        for (int i = 0, j = length - 1; i < j; i++, j--) {
            if (chars[i] == '?') {
                if (countOnes > 0) {
                    countOnes -= 2;
                    chars[i] = chars[j] = '1';
                } else {
                    countZeros -= 2;
                    chars[i] = chars[j] = '0';
                }
            }
        }

        // Final validation: All counts must be exactly exhausted
        if (countOnes != 0 || countZeros != 0) {
            return "-1";
        }

        return new String(chars);
    }
}

import java.util.Scanner;

public class Solution {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        if (scanner.hasNextInt()) {
            int testCases = scanner.nextInt();
            while (testCases-- > 0) {
                solveTestCase(scanner);
            }
        }
        scanner.close();
    }

    /**
     * Processes a single test case: reads inputs, constructs a valid palindrome,
     * and prints the result or -1 if impossible.
     */
    private static void solveTestCase(Scanner scanner) {
        int availableZeros = scanner.nextInt();
        int availableOnes = scanner.nextInt();
        String input = scanner.next();
        int length = input.length();
        char[] result = new char[length];
        boolean isPossible = true;

        // First pass: resolve fixed characters and mixed pairs
        for (int i = 0; i < length / 2; i++) {
            char left = input.charAt(i);
            char right = input.charAt(length - 1 - i);

            if (left == right) {
                if (left == '0') {
                    availableZeros -= 2;
                    result[i] = '0';
                    result[length - 1 - i] = '0';
                } else if (left == '1') {
                    availableOnes -= 2;
                    result[i] = '1';
                    result[length - 1 - i] = '1';
                }
                // If both are '?', defer to the second pass
            } else if ((left == '0' && right == '1') || (left == '1' && right == '0')) {
                // Mismatched fixed characters make a palindrome impossible
                isPossible = false;
                break;
            } else {
                // One side is '?', the other is '0' or '1'
                if (left == '1' || right == '1') {
                    availableOnes -= 2;
                    result[i] = '1';
                    result[length - 1 - i] = '1';
                } else {
                    availableZeros -= 2;
                    result[i] = '0';
                    result[length - 1 - i] = '0';
                }
            }
        }

        if (!isPossible) {
            System.out.println(-1);
            return;
        }

        // Second pass: resolve remaining '?' pairs
        for (int i = 0; i < length / 2; i++) {
            if (input.charAt(i) == '?' && input.charAt(length - 1 - i) == '?') {
                if (availableZeros == 0 || availableZeros == 1) {
                    availableOnes -= 2;
                    result[i] = '1';
                    result[length - 1 - i] = '1';
                } else {
                    availableZeros -= 2;
                    result[i] = '0';
                    result[length - 1 - i] = '0';
                }
            }
        }

        // Handle middle character for odd-length strings
        if (length % 2 == 1) {
            int mid = length / 2;
            if (input.charAt(mid) == '?') {
                if (availableZeros == 1) {
                    availableZeros--;
                    result[mid] = '0';
                } else if (availableOnes == 1) {
                    availableOnes--;
                    result[mid] = '1';
                } else {
                    isPossible = false;
                }
            } else {
                result[mid] = input.charAt(mid);
                if (result[mid] == '1') {
                    availableOnes--;
                } else {
                    availableZeros--;
                }
            }
        }

        // Final validation: all counts must be exactly zero and no contradictions occurred
        if (availableZeros != 0 || availableOnes != 0 || !isPossible) {
            System.out.println(-1);
        } else {
            System.out.println(new String(result));
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

/**
 * Solves palindrome construction problems with fixed character counts.
 * Reads test cases, enforces palindrome symmetry, and fills '?' characters
 * to satisfy exact counts of '0's and '1's.
 */
public class PalindromeSolver {

    private static final FastReader sc = new FastReader();
    private static final PrintWriter out = new PrintWriter(System.out);

    public static void main(String[] args) {
        int t = sc.nextInt();
        while (t-- > 0) {
            solve();
        }
        out.flush();
    }

    /**
     * Processes a single test case.
     * Attempts to construct a palindrome with exactly 'a' zeros and 'b' ones.
     */
    private static void solve() {
        int a = sc.nextInt();
        int b = sc.nextInt();
        String s = sc.next();
        int n = s.length();

        // Total characters must exactly match required counts
        if (a + b != n) {
            out.println("-1");
            return;
        }

        char[] arr = s.toCharArray();

        // Step 1: Enforce palindrome symmetry
        // Mirror '?' to their symmetric counterparts. If fixed characters conflict, it's impossible.
        for (int i = 0; i < n / 2; i++) {
            char left = arr[i];
            char right = arr[n - 1 - i];

            if (left != '?' && right != '?') {
                if (left != right) {
                    out.println("-1");
                    return;
                }
            } else if (left == '?') {
                arr[i] = right;
            } else {
                arr[n - 1 - i] = left;
            }
        }

        // Step 2: Count fixed zeros and ones
        int fixedZeros = 0;
        int fixedOnes = 0;
        for (char c : arr) {
            if (c == '0') fixedZeros++;
            else if (c == '1') fixedOnes++;
        }

        // If fixed characters already exceed required counts, impossible
        if (fixedZeros > a || fixedOnes > b) {
            out.println("-1");
            return;
        }

        int remainingA = a - fixedZeros;
        int remainingB = b - fixedOnes;

        // Step 3: Fill remaining '?' pairs from outside in
        for (int i = 0; i < n / 2; i++) {
            if (arr[i] == '?') {
                if (remainingA >= 2) {
                    arr[i] = '0';
                    arr[n - 1 - i] = '0';
                    remainingA -= 2;
                } else if (remainingB >= 2) {
                    arr[i] = '1';
                    arr[n - 1 - i] = '1';
                    remainingB -= 2;
                } else {
                    out.println("-1");
                    return;
                }
            }
        }

        // Step 4: Handle middle element if length is odd
        if (n % 2 == 1 && arr[n / 2] == '?') {
            if (remainingA >= 1) {
                arr[n / 2] = '0';
                remainingA--;
            } else if (remainingB >= 1) {
                arr[n / 2] = '1';
                remainingB--;
            } else {
                out.println("-1");
                return;
            }
        }

        // Step 5: Verify all counts are exactly satisfied
        if (remainingA != 0 || remainingB != 0) {
            out.println("-1");
            return;
        }

        out.println(new String(arr));
    }

    /**
     * Fast I/O helper class for competitive programming and large inputs.
     */
    static class FastReader {
        private final BufferedReader br;
