import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

/**
 * Refactored solution for constructing a palindrome with exactly 'maxZeros' zeros
 * and 'maxOnes' ones, based on a given template string containing '0', '1', and '?'.
 * 
 * Original algorithm preserved but structured for clarity, testability, and maintainability.
 */
public class PalindromeBuilder {

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner();
        PrintWriter out = new PrintWriter(System.out);
        try {
            int t = scanner.nextInt();
            for (int i = 0; i < t; i++) {
                solve(scanner, out);
            }
        } finally {
            out.flush();
            out.close();
        }
    }

    private static void solve(FastScanner scanner, PrintWriter out) {
        int maxZeros = scanner.nextInt();
        int maxOnes = scanner.nextInt();
        String template = scanner.next();
        char[] result = template.toCharArray();
        int length = result.length;

        // A palindrome can have at most one character type with an odd count.
        if (maxZeros % 2 == 1 && maxOnes % 2 == 1) {
            out.println(-1);
            return;
        }

        int zerosCount = 0;
        int onesCount = 0;
        boolean isValid = true;

        // 1. Handle the middle element if the length is odd
        if (length % 2 == 1) {
            int mid = length / 2;
            boolean mustBeZero = (maxZeros % 2 == 1);

            if (result[mid] == '?') {
                result[mid] = mustBeZero ? '0' : '1';
            } else if (mustBeZero && result[mid] == '1') {
                isValid = false;
            } else if (!mustBeZero && result[mid] == '0') {
                isValid = false;
            }

            if (isValid) {
                if (result[mid] == '0') zerosCount++;
                else onesCount++;
            }
        }

        // 2. Process symmetric pairs from outside in
        for (int i = 0; i < length / 2; i++) {
            int left = i;
            int right = length - 1 - i;
            char leftChar = result[left];
            char rightChar = result[right];

            if (leftChar != '?' && rightChar != '?') {
                // Both are fixed: they must match to maintain palindrome property
                if (leftChar != rightChar) {
                    isValid = false;
                    break;
                }
                if (leftChar == '1') onesCount += 2;
                else zerosCount += 2;
            } else if (leftChar != '?' || rightChar != '?') {
                // One is fixed, the other is '?': propagate the fixed character
                char fixedChar = (leftChar != '?') ? leftChar : rightChar;
                result[left] = fixedChar;
                result[right] = fixedChar;
                if (fixedChar == '1') onesCount += 2;
                else zerosCount += 2;
            }
            // If both are '?', leave them for the final filling phase
        }

        // 3. Validate counts against allowed limits
        if (isValid && (zerosCount > maxZeros || onesCount > maxOnes)) {
            isValid = false;
        }

        // 4. Fill remaining '?' pairs with available zeros or ones
        if (isValid) {
            int zerosRemaining = maxZeros - zerosCount;
            int onesRemaining = maxOnes - onesCount;

            for (int i = 0; i < length / 2; i++) {
                if (result[i] == '?' && result[length - 1 - i] == '?') {
                    if (zerosRemaining > 0) {
                        result[i] = '0';
                        result[length - 1 - i] = '0';
                        zerosRemaining -= 2;
                    } else {
                        result[i] = '1';
                        result[length - 1 - i] = '1';
                        onesRemaining -= 2;
                    }
                }
            }
        }

        // 5. Output result
        if (isValid) {
            out.println(new String(result));
        } else {
            out.println(-1);
        }
    }

    /**
     * Fast I/O helper class optimized for competitive programming scenarios.
     */
    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input stream", e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            String s = next();
            return s == null ? 0 : Integer.parseInt(s);
        }

        long nextLong() {
            String s = next();
            return s == null ? 0L : Long.parseLong(s);
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

public class ABPalindrome {

    public static void main(String[] args) throws IOException {
        // Use BufferedReader for efficient input reading
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));

        // Read the number of test cases
        String line = reader.readLine();
        if (line == null || line.trim().isEmpty()) {
            return;
        }

        int testCases = Integer.parseInt(line.trim());

        while (testCases-- > 0) {
            // Read a (count of 0s) and b (count of 1s)
            StringTokenizer tokenizer = new StringTokenizer(reader.readLine());
            int countZeros = Integer.parseInt(tokenizer.nextToken());
            int countOnes = Integer.parseInt(tokenizer.nextToken());

            // Read the pattern string
            // Using trim() to handle potential trailing whitespace
            char[] chars = reader.readLine().trim().toCharArray();

            // Solve the problem for the current test case
            if (solve(chars, countZeros, countOnes)) {
                System.out.println(new String(chars));
            } else {
                System.out.println(-1);
            }
        }
    }

    /**
     * Attempts to fill '?' characters in the pattern to form a palindrome
     * using exactly the specified counts of '0's and '1's.
     *
     * @param chars       The char array to modify in place
     * @param countZeros  Available count of '0's to use
     * @param countOnes   Available count of '1's to use
     * @return true if a valid palindrome can be formed, false otherwise
     */
    private static boolean solve(char[] chars, int countZeros, int countOnes) {
        int n = chars.length;

        // 1. Validate existing characters against available counts
        // If the input string already contains more '0's or '1's than allowed, it's impossible.
        int currentZeros = 0;
        int currentOnes = 0;
        for (char c : chars) {
            if (c == '0') currentZeros++;
            else if (c == '1') currentOnes++;
        }

        if (currentZeros > countZeros || currentOnes > countOnes) {
            return false;
        }

        // 2. Fill '?' characters to satisfy palindrome property
        // We iterate from the start up to the middle of the array.
        // If n is odd, the center element is at index n/2.
        for (int i = 0; i <= n / 2; i++) {
            int j = n - 1 - i; // Mirror index

            char left = chars[i];
            char right = chars[j];

            if (left == '?' && right == '?') {
                // Case: Both positions are unknown
                if (i == j) {
                    // Center element (occurs only when n is odd)
                    // Needs exactly 1 character
                    if (countZeros > 0) {
                        chars[i] = '0';
                        countZeros--;
                    } else if (countOnes > 0) {
                        chars[i] = '1';
                        countOnes--;
                    } else {
                        return false; // Cannot fill the center
                    }
                } else {
                    // Pair of positions
                    // Needs 2 identical characters
                    // Greedy approach: prioritize filling with '0's if possible, then '1's
                    if (countZeros >= 2) {
                        chars[i] = '0';
                        chars[j] = '0';
                        countZeros -= 2;
                    } else if (countOnes >= 2) {
                        chars[i] = '1';
                        chars[j] = '1';
                        countOnes -= 2;
                    } else {
                        return false; // Cannot fill this pair
                    }
                }
            } else if (left != '?' && right != '?') {
                // Case: Both positions are fixed
                if (left != right) {
                    return false; // Mismatch between fixed characters
                }
            } else {
                // Case: One is '?' and the other is fixed
                // The '?' must take the value of the fixed character to maintain palindrome property
                char fixedChar = (left != '?') ? left : right;

                if (fixedChar == '0') {
                    if (countZeros > 0) {
                        countZeros--;
                        if (left == '?') chars[i] = '0';
                        else chars[j] = '0';
                    } else {
                        return false; // Not enough '0's available
                    }
                } else { // fixedChar == '1'
                    if (countOnes > 0) {
                        countOnes--;
                        if (left == '?') chars[i] = '1';
                        else chars[j] = '1';
                    } else {
                        return false; // Not enough '1's available
                    }
                }
            }
        }

        // 3. Ensure all required characters were used exactly
        // The problem requires using exactly 'a' zeros and 'b' ones.
        return countZeros == 0 && countOnes == 0;
    }
}

import java.util.Scanner;

/**
 * Main class to solve palindrome construction problems.
 * Refactored for better maintainability, readability, and resource management.
 */
public class Main {

    public static void main(String[] args) {
        // Use try-with-resources to ensure the Scanner is closed properly
        try (Scanner scanner = new Scanner(System.in)) {
            if (scanner.hasNextInt()) {
                int numTestCases = scanner.nextInt();

                for (int i = 0; i < numTestCases; i++) {
                    int availableZeros = scanner.nextInt();
                    int availableOnes = scanner.nextInt();
                    String template = scanner.next();

                    String result = solvePalindrome(template, availableZeros, availableOnes);
                    System.out.println(result);
                }
            }
        }
    }

    /**
     * Attempts to form a palindrome from the template string using the available counts of '0's and '1's.
     *
     * @param template The string containing '0', '1', and '?'.
     * @param availableZeros The count of '0's available to fill '?' characters.
     * @param availableOnes The count of '1's available to fill '?' characters.
     * @return The completed palindrome string, or "-1" if impossible.
     */
    private static String solvePalindrome(String template, int availableZeros, int availableOnes) {
        char[] chars = template.toCharArray();
        int n = chars.length;

        // Step 1: Consume fixed characters ('0' and '1') and validate availability.
        // If a fixed character exceeds the available count, it's impossible.
        for (char c : chars) {
            if (c == '0') {
                if (availableZeros == 0) {
                    return "-1";
                }
                availableZeros--;
            } else if (c == '1') {
                if (availableOnes == 0) {
                    return "-1";
                }
                availableOnes--;
            }
        }

        // Step 2: Fill '?' characters to satisfy the palindrome property.
        // We use two pointers, one from the start and one from the end.
        int left = 0;
        int right = n - 1;

        while (left < right) {
            char leftChar = chars[left];
            char rightChar = chars[right];

            if (leftChar == '?' && rightChar == '?') {
                // Case: Both positions are wildcards.
                // We must fill them with the same character to maintain symmetry.
                // Prefer '0' if available in pairs, otherwise '1'.
                if (availableZeros >= 2) {
                    chars[left] = '0';
                    chars[right] = '0';
                    availableZeros -= 2;
                } else if (availableOnes >= 2) {
                    chars[left] = '1';
                    chars[right] = '1';
                    availableOnes -= 2;
                } else {
                    // Cannot form a pair
                    return "-1";
                }
            } else if (leftChar == '?') {
                // Case: Left is wildcard, Right is fixed.
                // Left must match Right.
                chars[left] = rightChar;
                if (rightChar == '0') {
                    availableZeros--;
                    if (availableZeros < 0) return "-1";
                } else {
                    availableOnes--;
                    if (availableOnes < 0) return "-1";
                }
            } else if (rightChar == '?') {
                // Case: Right is wildcard, Left is fixed.
                // Right must match Left.
                chars[right] = leftChar;
                if (leftChar == '0') {
                    availableZeros--;
                    if (availableZeros < 0) return "-1";
                } else {
                    availableOnes--;
                    if (availableOnes < 0) return "-1";
                }
            } else {
                // Case: Both are fixed characters.
                // They must match for the string to be a palindrome.
                if (leftChar != rightChar) {
                    return "-1";
                }
            }

            left++;
            right--;
        }

        // Step 3: Handle the middle character if the string length is odd.
        if (n % 2 != 0) {
            int mid = left; // At this point, left == right
            if (chars[mid] == '?') {
                // Fill the middle with remaining available character
                if (availableZeros >= 1) {
                    chars[mid] = '0';
                    availableZeros--;
                } else if (availableOnes >= 1) {
                    chars[mid] = '1';
                    availableOnes--;
                } else {
                    // No characters left to fill the middle
                    return "-1";
                }
            }
        }

        return new String(chars);
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

/**
 * Refactored Palindrome Solver.
 * 
 * This program determines if a string containing '0', '1', and '?' characters
 * can be transformed into a palindrome that satisfies specific counts of '0's 
 * and '1's.
 * 
 * Improvements made:
 * 1. Encapsulated logic into a separate method for better readability and testing.
 * 2. Used meaningful variable names (e.g., targetZeros, remZeros).
 * 3. Optimized input/output handling using BufferedReader and PrintWriter.
 * 4. Structured logic into distinct phases: Consistency Check, Counting, Filling, Validation.
 * 5. Improved error handling logic during the filling phase.
 */
public class PalindromeSolver {

    public static void main(String[] args) throws IOException {
        // Use BufferedReader for fast input reading
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        // Use PrintWriter for buffered output, which is more efficient for large outputs
        PrintWriter out = new PrintWriter(System.out);

        String line = br.readLine();
        if (line != null && !line.trim().isEmpty()) {
            int t = Integer.parseInt(line.trim());

            while (t-- > 0) {
                // Read target counts for '0' and '1'
                String tokenizerLine = br.readLine();
                if (tokenizerLine == null) break;
                StringTokenizer st = new StringTokenizer(tokenizerLine);
                int targetZeros = Integer.parseInt(st.nextToken());
                int targetOnes = Integer.parseInt(st.nextToken());

                // Read the input string
                String s = br.readLine();
                if (s == null) break;

                // Solve and print result
                out.println(solvePalindrome(targetZeros, targetOnes, s));
            }
        }
        out.flush();
    }

    /**
     * Attempts to convert the input string into a valid palindrome
     * with the specified counts of '0's and '1's.
     *
     * @param targetZeros Required number of '0's
     * @param targetOnes  Required number of '1's
     * @param s           Input string containing '0', '1', and '?'
     * @return            The valid string or "-1" if impossible
     */
    private static String solvePalindrome(int targetZeros, int targetOnes, String s) {
        char[] chars = s.toCharArray();
        int n = chars.length;

        // --- Phase 1: Enforce Palindrome Consistency ---
        // Iterate through the first half of the string to ensure s[i] == s[n-1-i]
        for (int i = 0; i < n / 2; i++) {
            int j = n - 1 - i; // Mirror index

            char left = chars[i];
            char right = chars[j];

            if (left != '?' && right != '?') {
                // Both characters are fixed; they must match
                if (left != right) {
                    return "-1";
                }
            } else if (left == '?') {
                // Left is unknown, propagate right to left
                chars[i] = right;
            } else {
                // Right is unknown, propagate left to right
                chars[j] = left;
            }
        }

        // --- Phase 2: Count existing characters ---
        int currentZeros = 0;
        int currentOnes = 0;
        for (char c : chars) {
            if (c == '0') currentZeros++;
            else if (c == '1') currentOnes++;
        }

        int remZeros = targetZeros - currentZeros;
        int remOnes = targetOnes - currentOnes;

        // --- Phase 3: Fill remaining '?' characters ---

        // Handle pairs (left and right halves)
        for (int i = 0; i < n / 2; i++) {
            if (chars[i] == '?') {
                // Due to Phase 1, if chars[i] is '?', then chars[n-1-i] is also '?'
                // We need to fill a pair, so we consume 2 from the remaining count.

                if (remZeros >= 2) {
                    chars[i] = '0';
                    chars[n - 1 - i] = '0';
                    remZeros -= 2;
                } else if (remOnes >= 2) {
                    chars[i] = '1';
                    chars[n - 1 - i] = '1';
                    remOnes -= 2;
                } else {
                    // Cannot fill this pair with either character
                    return "-1";
                }
            }
        }

        // Handle the middle element for odd-length strings
        if (n % 2 == 1) {
            int mid = n / 2;
            if (chars[mid] == '?') {
                // Can only consume 1 unit for the middle element
                if (remZeros >= 1) {
                    chars[mid] = '0';
                    remZeros--;
                } else if (remOnes >= 1) {
                    chars[mid] = '1';
                    remOnes--;
                } else {
                    return "-1";
                }
            }
        }

        // --- Phase 4: Final Validation ---
        // If we have used exactly the required number of characters
        if (remZeros == 0 && remOnes == 0) {
            return new String(chars);
        } else {
            return "-1";
        }
    }
}

import java.io.BufferedReader;
