public class CodeForces {

    public static void main(String[] args) {
        FastReader sc = new FastReader();
        int t = sc.nextInt();
        while (t-- > 0) {
            solve(sc);
        }
    }

    private static void solve(FastReader sc) {
        int zerosLeft = sc.nextInt();
        int onesLeft = sc.nextInt();
        String s = sc.next();
        int n = s.length();

        // Initial validation: total characters must match required counts
        if (zerosLeft + onesLeft != n) {
            System.out.println(-1);
            return;
        }

        char[] ch = s.toCharArray();

        // Step 1: Mirror known characters to '?' positions
        int l = 0, r = n - 1;
        while (l < r) {
            if (ch[l] != '?' && ch[r] == '?') {
                ch[r] = ch[l];
            } else if (ch[l] == '?' && ch[r] != '?') {
                ch[l] = ch[r];
            }
            l++;
            r--;
        }

        // Step 2: Count remaining '?' and adjust available counts
        int questionMarks = 0;
        for (char c : ch) {
            if (c == '?') {
                questionMarks++;
            } else if (c == '0') {
                zerosLeft--;
            } else if (c == '1') {
                onesLeft--;
            }
        }

        // Validate if we have enough characters to fill the '?' spots
        if (zerosLeft < 0 || onesLeft < 0 || zerosLeft + onesLeft != questionMarks) {
            System.out.println(-1);
            return;
        }

        // Step 3: Fill remaining '?' pairs
        l = 0;
        r = n - 1;
        while (l < r) {
            if (ch[l] == '?') {
                if (zerosLeft >= 2) {
                    ch[l] = ch[r] = '0';
                    zerosLeft -= 2;
                } else if (onesLeft >= 2) {
                    ch[l] = ch[r] = '1';
                    onesLeft -= 2;
                } else {
                    System.out.println(-1);
                    return;
                }
            }
            l++;
            r--;
        }

        // Step 4: Handle middle element for odd-length strings
        if (n % 2 == 1 && ch[n / 2] == '?') {
            if (zerosLeft == 1) {
                ch[n / 2] = '0';
                zerosLeft = 0;
            } else if (onesLeft == 1) {
                ch[n / 2] = '1';
                onesLeft = 0;
            } else {
                System.out.println(-1);
                return;
            }
        }

        // Final validation and output
        if (zerosLeft == 0 && onesLeft == 0) {
            System.out.println(new String(ch));
        } else {
            System.out.println(-1);
        }
    }

    /**
     * Fast I/O helper class to replace java.util.Scanner for competitive programming.
     */
