/**
 * Utility class for common competitive programming helpers.
 * Instantiation is prevented to enforce static usage and prevent inheritance misuse.
 */
public final class Functions {
    public static final int MOD = 1_000_000_007;
    public static final int INT_MAX = Integer.MAX_VALUE;
    public static final int INT_MIN = Integer.MIN_VALUE;
    public static final long LONG_MAX = Long.MAX_VALUE;
    public static final long LONG_MIN = Long.MIN_VALUE;
    public static final double DOUBLE_MAX = Double.MAX_VALUE;
    public static final double DOUBLE_MIN = Double.MIN_VALUE;

    private Functions() {
        // Prevent instantiation
    }

    public static void sort(int[] a, boolean isAscending) {
        Arrays.sort(a);
        if (!isAscending) {
            reverseArray(a);
        }
    }

    public static <T extends Comparable<T>> void sort(List<T> list, boolean isAscending) {
        if (isAscending) {
            Collections.sort(list);
        } else {
            Collections.sort(list, Collections.reverseOrder());
        }
    }

    public static long factorial(int n) {
        long fact = 1L;
        for (int i = 2; i <= n; i++) {
            fact = (fact * i) % MOD;
        }
        return fact;
    }

    public static int ncr(int n, int r) {
        if (r > n || r < 0) return 0;
        if (r == 0 || r == n) return 1;
        if (r > n / 2) r = n - r;

        long[] inv = new long[r + 1];
        inv[1] = 1;
        for (int i = 2; i <= r; i++) {
            inv[i] = MOD - (MOD / i) * inv[(int) (MOD % i)] % MOD;
        }

        long ans = 1;
        for (int i = 2; i <= r; i++) {
            ans = (ans * inv[i]) % MOD;
        }
        for (int i = n; i >= n - r + 1; i--) {
            ans = (ans * i) % MOD;
        }
        return (int) ans;
    }

    public static void reverseArray(int[] a) {
        int left = 0, right = a.length - 1;
        while (left < right) {
            int temp = a[left];
            a[left] = a[right];
            a[right] = temp;
            left++;
            right--;
        }
    }

    /**
     * Returns the smallest divisor of n if n is composite, otherwise returns -1.
     */
    public static int isPrime(int n) {
        if (n <= 1) return -1;
        for (int i = 2; i * i <= n; i++) {
            if (n % i == 0) return i;
        }
        return -1;
    }
}

