    public static void main(String[] args) throws IOException {
        // Use try-with-resources for automatic and safe resource management
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            String line = br.readLine();
            if (line == null) return;

            StringTokenizer tokenizer = new StringTokenizer(line);
            int testCases = Integer.parseInt(tokenizer.nextToken());

            StringBuilder output = new StringBuilder();

            while (testCases-- > 0) {
                line = br.readLine();
                while (line != null && line.trim().isEmpty()) {
                    line = br.readLine();
                }
                if (line == null) break;

                tokenizer = new StringTokenizer(line);
                int targetZeros = Integer.parseInt(tokenizer.nextToken());
                int targetOnes = Integer.parseInt(tokenizer.nextToken());

                String inputStr = br.readLine().trim();
                String result = solveTestCase(inputStr, targetZeros, targetOnes);
                output.append(result).append('\n');
            }
            System.out.print(output);
        }
    }

    /**
     * Fills '?' characters in the string to form a palindrome with exactly
     * targetZeros '0's and targetOnes '1's. Returns "-1" if impossible.
     */
    private static String solveTestCase(String s, int targetZeros, int targetOnes) {
        int n = s.length();
        char[] chars = s.toCharArray();
        int currentZeros = 0;
        int currentOnes = 0;

        // Count initially known characters
        for (char c : chars) {
            if (c == '0') currentZeros++;
            else if (c == '1') currentOnes++;
        }

        int left = 0;
        int right = n - 1;

        // Process pairs from outside in
        while (left < right) {
            char leftChar = chars[left];
            char rightChar = chars[right];

            if (leftChar != '?' && rightChar != '?') {
                // Both known: must match for palindrome property
                if (leftChar != rightChar) {
                    return "-1";
                }
            } else if (leftChar == '?' && rightChar != '?') {
                // Left unknown, right known: mirror right to left
                chars[left] = rightChar;
                if (rightChar == '0') currentZeros++;
                else currentOnes++;
            } else if (leftChar != '?' && rightChar == '?') {
                // Left known, right unknown: mirror left to right
                chars[right] = leftChar;
                if (leftChar == '0') currentZeros++;
                else currentOnes++;
            } else {
                // Both unknown: decide based on remaining count requirements
                int zerosNeeded = targetZeros - currentZeros;
                int onesNeeded = targetOnes - currentOnes;

                if (zerosNeeded >= 2 && onesNeeded >= 2) {
                    // Both options valid; greedily fill the one we need more of
                    if (zerosNeeded > onesNeeded) {
                        chars[left] = '0';
                        chars[right] = '0';
                        currentZeros += 2;
                    } else {
                        chars[left] = '1';
                        chars[right] = '1';
                        currentOnes += 2;
                    }
                } else if (zerosNeeded >= 2) {
                    chars[left] = '0';
                    chars[right] = '0';
                    currentZeros += 2;
                } else if (onesNeeded >= 2) {
                    chars[left] = '1';
                    chars[right] = '1';
                    currentOnes += 2;
                } else {
                    // Cannot satisfy both palindrome and count constraints
                    return "-1";
                }
            }
            left++;
            right--;
        }

        // Handle the center character for odd-length strings
        if (left == right) {
            if (chars[left] == '?') {
                if (currentZeros < targetZeros) {
                    chars[left] = '0';
                    currentZeros++;
                } else if (currentOnes < targetOnes) {
                    chars[left] = '1';
                    currentOnes++;
                } else {
                    return "-1";
                }
            }
        }

        // Final validation to ensure exact target counts were met
        if (currentZeros != targetZeros || currentOnes != targetOnes) {
            return "-1";
        }

        return new String(chars);
    }
}

import java.util.Scanner;

public class Main {
    // Use a static scanner for efficient input reading
    private static final Scanner scanner = new Scanner(System.in);

    public static void main(String[] args) {
        // Read the number of test cases
        if (scanner.hasNextInt()) {
            int numTestCases = scanner.nextInt();

            // Process each test case
            while (numTestCases-- > 0) {
                solve();
            }
        }
    }

    /**
     * Handles the logic for a single test case.
     */
    private static void solve() {
        int countZeros = scanner.nextInt();
        int countOnes = scanner.nextInt();
        String pattern = scanner.next();

        // Convert pattern to char array for mutability
        char[] chars = pattern.toCharArray();
        int length = chars.length;

        // Attempt to construct the valid palindrome
        if (buildPalindrome(chars, countZeros, countOnes, length)) {
            System.out.println(new String(chars));
        } else {
            System.out.println(-1);
        }
    }

    /**
     * Attempts to fill the char array to form a valid palindrome using the given counts.
     * 
     * @param chars The character array to modify in place
     * @param countZeros Available count of '0's
     * @param countOnes Available count of '1's
     * @param length Length of the string
     * @return true if a valid palindrome can be formed, false otherwise
     */
    private static boolean buildPalindrome(char[] chars, int countZeros, int countOnes, int length) {
        // Pass 1: Validate existing characters and consume budget for fixed pairs
        for (int i = 0; i < length / 2; i++) {
            int left = i;
            int right = length - 1 - i;

            if (chars[left] != chars[right]) {
                // Mismatch found: try to resolve using '?'
                if (chars[left] == '?') {
                    chars[left] = chars[right];
                } else if (chars[right] == '?') {
                    chars[right] = chars[left];
                } else {
                    // Mismatch between two fixed characters (e.g., '0' and '1')
                    return false; 
                }
            }

            // Update budget based on the resolved character at this symmetric position.
            // We decrement by 2 because we are accounting for the pair (left, right).
            char currentChar = chars[left]; // left and right are now equal
            if (currentChar == '1') {
                countOnes -= 2;
            } else if (currentChar == '0') {
                countZeros -= 2;
            }
            // If currentChar is '?', it means both were '?' and we haven't decided yet.
            // This is handled in Pass 2.
        }

        // Handle the middle element if the length is odd
        if (length % 2 == 1) {
            int mid = length / 2;
            if (chars[mid] != '?') {
                // Fixed middle element
                if (chars[mid] == '1') {
                    countOnes--;
                } else {
                    countZeros--;
                }
            } else {
                // Middle element is '?'. 
                // It must take the value that has an odd remaining count (parity argument).
                // If countOnes is odd, we must place '1' in the middle to leave an even count for pairs.
                if (countOnes % 2 == 1) {
                    chars[mid] = '1';
                    countOnes--;
                } else {
                    chars[mid] = '0';
                    countZeros--;
                }
            }
        }

        // Parity Check:
        // After handling the middle element (if any), all remaining '?'s must be filled in pairs.
        // Therefore, the remaining counts of '0's and '1's must be even.
        if (countZeros % 2 != 0 || countOnes % 2 != 0) {
            return false;
        }

        // Pass 2: Fill remaining '?'s using available budget
        for (int i = 0; i < length / 2; i++) {
            int left = i;
            int right = length - 1 - i;

            if (chars[left] == '?') {
                // Greedily fill with '0' if available, else '1'
                if (countZeros > 0) {
                    chars[left] = '0';
                    chars[right] = '0';
                    countZeros -= 2;
                } else if (countOnes > 0) {
                    chars[left] = '1';
                    chars[right] = '1';
                    countOnes -= 2;
                }
            }
        }

        // Final Validation
        // Ensure we didn't go negative (should be covered by logic, but good for safety)
        if (countZeros < 0 || countOnes < 0) {
            return false;
        }

        return true;
    }
}

