/**
 * Refactored SolutionC.
 * 
 * Improvements made:
 * 1. Removed unnecessary Thread extension and stack size manipulation. The logic is iterative
 *    and does not require a separate thread or increased stack size.
 * 2. Improved FastReader:
 *    - Added proper exception handling (throws RuntimeException instead of printStackTrace).
 *    - Removed unused methods (nextLine).
 *    - Added null checks for input streams.
 * 3. Variable Naming: Renamed generic variables (a, b, s, n) to descriptive names 
 *    (countZeros, countOnes, inputString, length) for better readability.
 * 4. Logic Consolidation: Merged the synchronization and filling loops into a single 
 *    pass using two pointers (left, right) to reduce code duplication and complexity.
 * 5. Output: Used PrintWriter efficiently and ensured proper flushing/closing.
 */
public class SolutionC {

    /**
     * Helper class for fast input reading.
     */
    static class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) {
                        return null;
                    }
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            String s = next();
            if (s == null) throw new RuntimeException("Unexpected end of input");
            return Integer.parseInt(s);
        }

        long nextLong() {
            String s = next();
            if (s == null) throw new RuntimeException("Unexpected end of input");
            return Long.parseLong(s);
        }

        double nextDouble() {
            String s = next();
            if (s == null) throw new RuntimeException("Unexpected end of input");
            return Double.parseDouble(s);
        }
    }

    private static final FastReader scanner = new FastReader();
    private static final PrintWriter out = new PrintWriter(System.out);

    public static void main(String[] args) {
        try {
            // Read number of test cases
            String tStr = scanner.next();
            if (tStr != null) {
                int t = Integer.parseInt(tStr);
                for (int i = 0; i < t; i++) {
                    solve();
                }
            }
        } catch (Exception e) {
            e.printStackTrace();
        } finally {
            out.flush();
            out.close();
        }
    }

    private static void solve() {
        int countZeros = scanner.nextInt();
        int countOnes = scanner.nextInt();
        String inputString = scanner.next();

        if (inputString == null) return;

        char[] chars = inputString.toCharArray();
        int length = chars.length;

        int left = 0;
        int right = length - 1;

        while (left <= right) {
            // Handle middle element for odd length strings
            if (left == right) {
                if (chars[left] != '?') {
                    // Character is already determined
                    if (chars[left] == '0') {
                        countZeros--;
                    } else {
                        countOnes--;
                    }
                } else {
                    // Character is '?', fill it based on available counts
                    if (countZeros > 0) {
                        chars[left] = '0';
                        countZeros--;
                    } else if (countOnes > 0) {
                        chars[left] = '1';
                        countOnes--;
                    } else {
                        out.println("-1");
                        return;
                    }
                }
                left++; // Move past middle
                break;
            }

            char leftChar = chars[left];
            char rightChar = chars[right];

            if (leftChar != '?' && rightChar != '?') {
                // Both characters are known
                if (leftChar != rightChar) {
                    out.println("-1");
                    return;
                }
                // Both match, consume counts for the pair
                if (leftChar == '0') {
                    countZeros -= 2;
                } else {
                    countOnes -= 2;
                }
            } else if (leftChar == '?' && rightChar == '?') {
                // Both are unknown, fill them with available counts
                // Priority given to '0' if counts allow, matching original logic
                if (countZeros >= 2) {
                    chars[left] = '0';
                    chars[right] = '0';
                    countZeros -= 2;
                } else if (countOnes >= 2) {
                    chars[left] = '1';
                    chars[right] = '1';
                    countOnes -= 2;
                } else {
                    out.println("-1");
                    return;
                }
            } else {
                // One is known, one is unknown
                // Copy the known character to the '?' position
                char knownChar = (leftChar != '?') ? leftChar : rightChar;
                chars[left] = knownChar;
                chars[right] = knownChar;

                // Consume counts
                if (knownChar == '0') {
                    countZeros -= 2;
                } else {
                    countOnes -= 2;
                }
            }

            left++;
            right--;
        }

        // After processing, check if we have used exactly the required counts.
        // If counts are not zero, it means we have leftover characters that couldn't be placed
        // or we didn't use enough.
        if (countZeros == 0 && countOnes == 0) {
            out.println(chars);
        } else {
            out.println("-1");
        }
    }
}

import java.util.Scanner;

/**
 * Solves the palindrome construction problem.
 * Given a target count of '0's and '1's, and a string containing '0', '1', and '?',
 * constructs a palindrome using exactly the specified counts, or returns "-1" if impossible.
 */
public class PalindromeConstructor {

    // Constants for improved readability and maintainability
    private static final char ZERO = '0';
    private static final char ONE = '1';
    private static final char QUESTION_MARK = '?';
    private static final String IMPOSSIBLE_RESULT = "-1";

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        if (!scanner.hasNextInt()) {
            return;
        }

        int testCases = scanner.nextInt();
        while (testCases-- > 0) {
            int targetZeroCount = scanner.nextInt();
            int targetOneCount = scanner.nextInt();
            String inputString = scanner.next();

            System.out.println(solvePalindrome(inputString, targetZeroCount, targetOneCount));
        }
        scanner.close();
    }

    /**
     * Attempts to construct a valid palindrome from the input string.
     * Uses a two-pointer approach to resolve mismatches and fill placeholders.
     */
    private static String solvePalindrome(String input, int targetZeros, int targetOnes) {
        char[] chars = input.toCharArray();
        int currentZeros = 0;
        int currentOnes = 0;

        // 1. Count existing characters
        for (char c : chars) {
            if (c == ZERO) currentZeros++;
            else if (c == ONE) currentOnes++;
        }

        // 2. Quick validation checks
        if (currentZeros > targetZeros || currentOnes > targetOnes) {
            return IMPOSSIBLE_RESULT;
        }
        // A palindrome cannot have both '0' and '1' counts as odd numbers
        if (targetZeros == targetOnes && targetOnes % 2 != 0) {
            return IMPOSSIBLE_RESULT;
        }

        // 3. First pass: Resolve asymmetric pairs (one side is '?', the other is fixed)
        int left = 0;
        int right = chars.length - 1;
        while (left <= right) {
            if (chars[left] == chars[right]) {
                // Already matches or both are '?', proceed
            } else if (chars[left] != QUESTION_MARK && chars[right] != QUESTION_MARK) {
                // Mismatch between two fixed characters
                return IMPOSSIBLE_RESULT;
            } else {
                // One side is '?', assign the fixed character to both
                char fixedChar = (chars[left] != QUESTION_MARK) ? chars[left] : chars[right];
                if (fixedChar == ZERO) {
                    if (currentZeros >= targetZeros) return IMPOSSIBLE_RESULT;
                    currentZeros++;
                } else {
                    if (currentOnes >= targetOnes) return IMPOSSIBLE_RESULT;
                    currentOnes++;
                }
                chars[left] = fixedChar;
                chars[right] = fixedChar;
            }
            left++;
            right--;
        }

        // 4. Second pass: Fill remaining '?' pairs symmetrically
        left = 0;
        right = chars.length - 1;
        while (left < right) {
            if (chars[left] == QUESTION_MARK && chars[right] == QUESTION_MARK) {
                if (currentZeros + 2 <= targetZeros) {
                    chars[left] = chars[right] = ZERO;
                    currentZeros += 2;
                } else if (currentOnes + 2 <= targetOnes) {
                    chars[left] = chars[right] = ONE;
                    currentOnes += 2;
                } else {
                    return IMPOSSIBLE_RESULT;
                }
            }
            left++;
            right--;
        }

        // 5. Handle the middle character for odd-length strings
        if (chars.length % 2 != 0 && chars[chars.length / 2] == QUESTION_MARK) {
            if (currentZeros < targetZeros) {
                chars[chars.length / 2] = ZERO;
                currentZeros++;
            } else if (currentOnes < targetOnes) {
                chars[chars.length / 2] = ONE;
                currentOnes++;
            } else {
                return IMPOSSIBLE_RESULT;
            }
        }

        // 6. Final validation
        if (currentZeros == targetZeros && currentOnes == targetOnes && isPalindrome(chars)) {
            return new String(chars);
        }

        return IMPOSSIBLE_RESULT;
    }

    /**
     * Checks if a character array represents a palindrome.
     */
    private static boolean isPalindrome(char[] chars) {
        int left = 0;
        int right = chars.length - 1;
        while (left < right) {
            if (chars[left++] != chars[right--]) {
                return false;
            }
        }
        return true;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

public class Codeforces {

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner();

        // Check if input is available to prevent exceptions on empty input
        if (!scanner.hasMoreTokens()) {
            return;
        }

        int t = scanner.nextInt();
        while (t-- > 0) {
            int zeros = scanner.nextInt();
            int ones = scanner.nextInt();
            String pattern = scanner.next();

            // Output the result of the solve method
            System.out.println(solve(zeros, ones, pattern));
        }
    }

    /**
     * Solves the palindrome construction problem.
     * 
     * @param zeros Required count of '0's
     * @param ones  Required count of '1's
     * @param pattern The input pattern containing '0', '1', and '?'
     * @return The constructed palindrome string, or "-1" if impossible
     */
    private static String solve(int zeros, int ones, String pattern) {
        char[] chars = pattern.toCharArray();
        int n = chars.length;

        // Basic validation: Length must match sum of required characters
        if (n != zeros + ones) {
            return "-1";
        }

        // 1. Count existing characters and validate constraints
        for (char c : chars) {
            if (c == '0') zeros--;
            else if (c == '1') ones--;
        }

        // If we already have more characters than allowed
        if (zeros < 0 || ones < 0) {
            return "-1";
        }

        // 2. Enforce Palindrome Property (Sync '?' with known mirror)
        // Iterate only up to half the array to check pairs
        for (int i = 0; i < n / 2; i++) {
            int j = n - 1 - i;

            // If left is '?' and right is known, copy right to left
            if (chars[i] == '?' && chars[j] != '?') {
                chars[i] = chars[j];
                if (chars[j] == '0') zeros--;
                else ones--;
            } 
            // If right is '?' and left is known, copy left to right
            else if (chars[j] == '?' && chars[i] != '?') {
                chars[j] = chars[i];
                if (chars[i] == '0') zeros--;
                else ones--;
            }

            // Check validity after modification
            if (zeros < 0 || ones < 0) return "-1";
        }

        // 3. Fill remaining '?'
        // Iterate up to middle (inclusive) to handle pairs and the center element
        for (int i = 0; i < (n + 1) / 2; i++) {
            int j = n - 1 - i;

            if (chars[i] == '?') {
                // If chars[i] is '?', chars[j] must also be '?' due to Step 2 logic
                // (unless i == j, which is the middle element)

                if (i == j) {
                    // Middle element (only exists if n is odd)
                    // Priority: 0 then 1 (matching original logic preference)
                    if (zeros > 0) {
                        chars[i] = '0';
                        zeros--;
                    } else if (ones > 0) {
                        chars[i] = '1';
                        ones--;
                    } else {
                        return "-1"; // No characters left for the middle
                    }
                } else {
                    // Pair element
                    // Priority: 0s then 1s (matching original logic preference)
                    if (zeros >= 2) {
                        chars[i] = chars[j] = '0';
                        zeros -= 2;
                    } else if (ones >= 2) {
                        chars[i] = chars[j] = '1';
                        ones -= 2;
                    } else {
                        return "-1"; // Cannot fill a pair with single characters
                    }
                }
            }
        }

        // 4. Final Verification
        // Ensure all required characters were used exactly
        if (zeros == 0 && ones == 0) {
            return new String(chars);
        }
        return "-1";
    }

    // FastScanner for efficient input reading
    static class FastScanner {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer("");

        boolean hasMoreTokens() {
            while (!st.hasMoreTokens()) {
                String line = null;
                try {
                    line = br.readLine();
                } catch (IOException e) {
                    e.printStackTrace();
                }
                if (line == null) return false;
                st = new StringTokenizer(line);
            }
            return true;
        }

        String next() {
            if (hasMoreTokens()) return st.nextToken();
            return null;
        }

        int nextInt() {
            String s = next();
            return s == null ? 0 : Integer.parseInt(s);
        }
    }
}

