    /**
     * Solves the palindrome construction problem for a single test case.
     * 
     * @param s The input string containing '0', '1', and '?'.
     * @param countZeros The required number of '0's in the final string.
     * @param countOnes The required number of '1's in the final string.
     * @return The constructed palindrome string, or "-1" if impossible.
     */
    private static String solve(String s, int countZeros, int countOnes) {
        char[] chars = s.toCharArray();
        int n = chars.length;

        // Step 1: Decrement counts for characters already present in the string.
        // This establishes the remaining budget of '0's and '1's we can place.
        for (char c : chars) {
            if (c == '0') countZeros--;
            else if (c == '1') countOnes--;
        }

        // Step 2: Propagate known characters to '?' positions.
        // If one side of the pair is known, the other must match to form a palindrome.
        for (int i = 0, j = n - 1; i < j; i++, j--) {
            if (chars[i] == '?' && chars[j] != '?') {
                chars[i] = chars[j];
                if (chars[j] == '0') countZeros--;
                else countOnes--;
            } else if (chars[j] == '?' && chars[i] != '?') {
                chars[j] = chars[i];
                if (chars[i] == '0') countZeros--;
                else countOnes--;
            }
        }

        // Step 3: Fill remaining '?' positions.
        // If both sides are unknown, choose the character with the higher remaining budget.
        for (int i = 0, j = n - 1; i < j; i++, j--) {
            if (chars[i] == '?' && chars[j] == '?') {
                if (countZeros > countOnes) {
                    chars[i] = chars[j] = '0';
                    countZeros -= 2;
                } else {
                    chars[i] = chars[j] = '1';
                    countOnes -= 2;
                }
            }
        }

        // Step 4: Handle the center element for odd-length strings.
        if (n % 2 != 0) {
            int mid = n / 2;
            if (chars[mid] == '?') {
                if (countZeros > countOnes) {
                    chars[mid] = '0';
                    countZeros--;
                } else {
                    chars[mid] = '1';
                    countOnes--;
                }
            }
        }

        // Step 5: Validation.
        // Check if we used exactly the required counts and if the result is a palindrome.
        if (countZeros == 0 && countOnes == 0 && isPalindrome(chars)) {
            return new String(chars);
        } else {
            return "-1";
        }
    }

    /**
     * Checks if a character array is a palindrome.
     */
    private static boolean isPalindrome(char[] arr) {
        int n = arr.length;
        for (int i = 0, j = n - 1; i < j; i++, j--) {
            if (arr[i] != arr[j]) return false;
        }
        return true;
    }
}

import java.io.*;
import java.util.StringTokenizer;

public class Main {

    public static void main(String[] args) {
        InputReader in = new InputReader(System.in);
        PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out));

        int testCases = in.nextInt();
        while (testCases-- > 0) {
            solve(in, out);
        }

        out.flush();
    }

    /**
     * Solves a single test case: constructs a palindrome using exactly 
     * zeroCount zeros and oneCount ones, or outputs -1 if impossible.
     */
    private static void solve(InputReader in, PrintWriter out) {
        int zeroCount = in.nextInt();
        int oneCount = in.nextInt();
        char[] chars = in.next().toCharArray();
        int n = chars.length;
        boolean isImpossible = false;

        // Phase 1: Resolve forced pairs and validate existing characters
        for (int i = 0; i < n / 2; i++) {
            char left = chars[i];
            char right = chars[n - 1 - i];

            if (left == '?' && right == '?') {
                continue; // Defer to Phase 3
            } else if (left == '?' || right == '?') {
                // Exactly one side is '?'; force it to match the known character
                char known = (left == '?') ? right : left;
                chars[i] = chars[n - 1 - i] = known;
                if (known == '0') zeroCount -= 2;
                else oneCount -= 2;
            } else if (left != right) {
                // Both sides are known but mismatched -> impossible to form palindrome
                isImpossible = true;
                break;
            } else {
                // Both sides are known and identical
                if (left == '0') zeroCount -= 2;
                else oneCount -= 2;
            }
        }

        if (isImpossible) {
            out.println(-1);
            return;
        }

        // Phase 2: Handle middle element for odd-length strings
        if (n % 2 == 1) {
            int mid = n / 2;
            if (chars[mid] == '?') {
                if (zeroCount % 2 == 1) {
                    chars[mid] = '0';
                    zeroCount--;
                } else if (oneCount % 2 == 1) {
                    chars[mid] = '1';
                    oneCount--;
                } else {
                    out.println(-1);
                    return;
                }
            } else {
                if (chars[mid] == '0') zeroCount--;
                else oneCount--;
            }
        }

        // Phase 3: Fill remaining '?' pairs
        for (int i = 0; i < n / 2; i++) {
            if (chars[i] == '?') {
                if (zeroCount > 0) {
                    zeroCount -= 2;
                    chars[i] = chars[n - 1 - i] = '0';
                } else {
                    oneCount -= 2;
                    chars[i] = chars[n - 1 - i] = '1';
                }
            }
        }

        // Phase 4: Final validation
        if (zeroCount == 0 && oneCount == 0) {
            out.println(chars);
        } else {
            out.println(-1);
        }
    }

    /**
     * Fast input reader for competitive programming style problems.
     */
    private static class InputReader {
        public BufferedReader reader;
        public StringTokenizer tokenizer;

        public InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }

        public double nextDouble() {
            return Double.parseDouble(next());
        }

        public String nextLine() {
            String str = "";
            try {
                str = reader.readLine();
            } catch (IOException e) {
                e.printStackTrace();
            }
            return str;
        }
    }
}

import java.util.Scanner;

/**
 * Refactored Palindrome Generator.
 * 
 * This program reads test cases involving a template string with placeholders ('?')
 * and attempts to fill them with '0's and '1's to form a palindrome with specific
 * counts of each character.
 * 
 * Refactoring improvements:
 * 1. Separation of concerns: Logic moved from main() to a dedicated solve() method.
 * 2. Readability: Descriptive variable names (zerosNeeded, onesNeeded, template).
 * 3. Maintainability: Clear algorithmic steps with comments.
 * 4. Correctness: Fixed logic errors present in the original code (e.g., middle element handling).
 * 5. Efficiency: Reduced redundant loops and calculations.
 */
public class Main {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        // Check if input exists to prevent exceptions on empty input
        if (scanner.hasNextInt()) {
            int numTestCases = scanner.nextInt();

            for (int t = 0; t < numTestCases; t++) {
                // Read inputs with descriptive variable names
                int zerosNeeded = scanner.nextInt();
                int onesNeeded = scanner.nextInt();
                String template = scanner.next();

                // Process the test case and print the result
                String result = solve(zerosNeeded, onesNeeded, template);
                System.out.println(result);
            }
        }

        scanner.close();
    }

    /**
     * Attempts to construct a palindrome from the template string using the specified counts.
     * 
     * @param zerosNeeded The required number of '0's.
     * @param onesNeeded The required number of '1's.
     * @param template The input string containing '0', '1', and '?'.
     * @return The valid palindrome string, or "-1" if impossible.
     */
    private static String solve(int zerosNeeded, int onesNeeded, String template) {
        // Constraint Check:
        // A palindrome can have at most one character type with an odd count 
        // (the character in the exact middle of an odd-length string).
        // If both counts are odd, it is impossible to form a palindrome.
        if (zerosNeeded % 2 != 0 && onesNeeded % 2 != 0) {
            return "-1";
        }

        char[] chars = template.toCharArray();
        int n = chars.length;

        // Pass 1: Resolve '?' characters that have a known mirror character.
        // Also validates that existing characters match symmetrically.
        for (int i = 0, j = n - 1; i < j; i++, j--) {
            char left = chars[i];
            char right = chars[j];

            if (left == '?' && right != '?') {
                // Mirror the known character to the '?'
                chars[i] = right;
            } else if (left != '?' && right == '?') {
                // Mirror the known character to the '?'
                chars[j] = left;
            } else if (left != '?' && right != '?' && left != right) {
                // Mismatch between two fixed characters -> Impossible
                return "-1";
            }
        }

        // Count current occurrences of '0' and '1' after resolving mirrors
        int currentZeros = 0;
        int currentOnes = 0;
        for (char c : chars) {
            if (c == '0') currentZeros++;
            else if (c == '1') currentOnes++;
        }

        // Calculate remaining counts needed
        int remainingZeros = zerosNeeded - currentZeros;
        int remainingOnes = onesNeeded - currentOnes;

        // If we already exceeded the required count, it's impossible
        if (remainingZeros < 0 || remainingOnes < 0) {
            return "-1";
        }

        // Pass 2: Fill remaining '?' characters.
        // We iterate from outside in. Since Pass 1 handled cases where one side was known,
        // any remaining '?' at index i implies '?' at index j (mirror).
        for (int i = 0, j = n - 1; i < j; i++, j--) {
            if (chars[i] == '?') {
                // We have a pair of '?'s. We must fill them with the same character.
                // Check if we have enough characters to fill a pair (count of 2).

                if (remainingZeros >= 2) {
                    chars[i] = '0';
                    chars[j] = '0';
                    remainingZeros -= 2;
                } else if (remainingOnes >= 2) {
                    chars[i] = '1';
                    chars[j] = '1';
                    remainingOnes -= 2;
                } else {
                    // Cannot fill this pair with available characters
                    return "-1";
                }
            }
        }

        // Pass 3: Handle the middle element if the string length is odd.
        if (n % 2 != 0) {
            int mid = n / 2;
            if (chars[mid] == '?') {
                // Middle element consumes 1 count
                if (remainingZeros >= 1) {
                    chars[mid] = '0';
                    remainingZeros--;
                } else if (remainingOnes >= 1) {
                    chars[mid] = '1';
                    remainingOnes--;
                } else {
                    // Cannot fill the middle element
                    return "-1";
                }
            }
        }

        // Final Validation:
        // Ensure that we have used exactly the required number of characters.
        // If remainingZeros or remainingOnes is not 0, the counts didn't match.
        if (remainingZeros == 0 && remainingOnes == 0) {
            return new String(chars);
        } else {
            return "-1";
        }
    }
}

import java.util.Scanner;

/**
 * A solver for constructing palindrome strings based on character counts.
 * Refactored for improved maintainability, readability, and separation of concerns.
 */
public class PalindromeSolver {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        // Check if input exists to handle potential empty input gracefully
        if (scanner.hasNextInt()) {
            int testCases = scanner.nextInt();
            StringBuilder output = new StringBuilder();

            for (int t = 0; t < testCases; t++) {
                int totalZeros = scanner.nextInt();
                int totalOnes = scanner.nextInt();
                String inputString = scanner.next();

                output.append(solve(totalZeros, totalOnes, inputString)).append('\n');
            }
            System.out.print(output);
        }

        scanner.close();
    }

    /**
     * Solves the palindrome construction problem for a single test case.
     * 
     * @param totalZeros The total allowed count of '0's in the final string.
     * @param totalOnes The total allowed count of '1's in the final string.
     * @param s The input string containing '0', '1', and '?'.
     * @return The constructed palindrome string, or "-1" if it's impossible to satisfy constraints.
     */
    private static String solve(int totalZeros, int totalOnes, String s) {
        char[] chars = s.toCharArray();
        int n = chars.length;

        // 1. Count existing characters and validate against limits
        int currentZeros = 0;
        int currentOnes = 0;
        for (char c : chars) {
            if (c == '0') currentZeros++;
            else if (c == '1') currentOnes++;
        }

        // If the string already contains more characters than allowed, it's impossible.
        if (currentZeros > totalZeros || currentOnes > totalOnes) {
            return "-1";
        }

        int remainingZeros = totalZeros - currentZeros;
        int remainingOnes = totalOnes - currentOnes;

        // 2. Enforce Palindrome Property (First Half)
        // Iterate up to the middle. If a character is known, its mirror must match.
        // If one is '?', we fill it with the known character and update the budget.
        for (int i = 0; i < n / 2; i++) {
            int j = n - 1 - i;
            char left = chars[i];
            char right = chars[j];

            if (left != '?' && right != '?') {
                if (left != right) return "-1"; // Mismatch found
            } else if (left == '?' && right != '?') {
                chars[i] = right;
                if (right == '0') remainingZeros--;
                else remainingOnes--;
            } else if (left != '?' && right == '?') {
                chars[j] = left;
                if (left == '0') remainingZeros--;
                else remainingOnes--;
            }
            // If both are '?', we leave them for the final filling step.
        }

        // 3. Handle Center Element (Odd Length)
        if (n % 2 == 1) {
            int mid = n / 2;
            if (chars[mid] == '?') {
                // The center element must be filled.
                // It consumes 1 zero or 1 one.
                // We check parity because we need to be able to fill pairs later,
                // or simply because the budget must allow it.
                if (remainingZeros % 2 == 1) {
                    chars[mid] = '0';
                    remainingZeros--;
                } else if (remainingOnes % 2 == 1) {
                    chars[mid] = '1';
                    remainingOnes--;
                } else {
                    return "-1"; // Cannot fill center with available budget
                }
            }
            // If chars[mid] is not '?', it was already counted in step 1,
            // so remaining counts don't change.
        }

        // 4. Validate Remaining Counts
        // Counts must be non-negative.
        if (remainingZeros < 0 || remainingOnes < 0) {
            return "-1";
        }
        // Counts must be even because remaining '?'s come in symmetric pairs.
        // If we have an odd number of remaining zeros/ones, we cannot fill the pairs perfectly.
        if (remainingZeros % 2 != 0 || remainingOnes % 2 != 0) {
            return "-1";
        }

        // 5. Fill Remaining '?'s
        // Iterate through the first half again to fill any remaining '?'s.
        for (int i = 0; i < n / 2; i++) {
            if (chars[i] == '?') {
                // If chars[i] is '?', chars[n-1-i] must also be '?'
                // due to the logic in step 2.

                // Prefer filling with '0' if available, otherwise '1'
                if (remainingZeros > 0) {
                    chars[i] = '0';
                    chars[n - 1 - i] = '0';
                    remainingZeros -= 2;
                } else {
                    chars[i] = '1';
                    chars[n - 1 - i] = '1';
                    remainingOnes -= 2; // Decrement budget for correctness
                }
            }
        }

        return new String(chars);
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

/**
 * A utility class to balance strings containing '0', '1', and '?' characters
 * to form valid palindromes given specific counts of '0's and '1's.
 */
public class StringBalancer {

    public static void main(String[] args) throws IOException {
        // Use BufferedReader for efficient input reading
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringBuilder output = new StringBuilder();

        String line = br.readLine();
        if (line == null) return;

        // Parse number of test cases
        int testCases = Integer.parseInt(line.trim());

        while (testCases-- > 0) {
            line = br.readLine();
            if (line == null) break;

            // Use StringTokenizer for robust whitespace handling
            StringTokenizer st = new StringTokenizer(line);
            if (!st.hasMoreTokens()) break;

            int countZero = Integer.parseInt(st.nextToken());
            int countOne = Integer.parseInt(st.nextToken());

            String inputStr = br.readLine();
            if (inputStr == null) break;

            char[] charArray = inputStr.trim().toCharArray();

            String result = solve(countZero, countOne, charArray);
            output.append(result).append("\n");
        }
        System.out.println(output);
    }

    /**
     * Solves the string balancing problem.
     * 
     * @param countZero The number of '0's available to place.
     * @param countOne  The number of '1's available to place.
     * @param charArray The character array representing the string with '?' placeholders.
     * @return The balanced palindrome string, or "-1" if impossible.
     */
    private static String solve(int countZero, int countOne, char[] charArray) {
        int length = charArray.length;

        // Pass 1: Propagate known characters and check for immediate conflicts.
        // We iterate from the outside in to the middle.
        // This mirrors the logic of filling '?'s based on their symmetric counterparts.
        for (int i = 0; i <= length / 2; i++) {
            int left = i;
            int right = length - 1 - i;

            char leftChar = charArray[left];
            char rightChar = charArray[right];

            if (leftChar == '?' && rightChar == '?') {
                // Both unknown, defer filling to Pass 2
                continue;
            } else if (leftChar == '?') {
                // Left is unknown, mirror the known right character
                charArray[left] = rightChar;
            } else if (rightChar == '?') {
                // Right is unknown, mirror the known left character
                charArray[right] = leftChar;
            } else {
                // Both are known characters
                if (leftChar != rightChar) {
                    // Conflict detected (e.g., '0' at start, '1' at end)
                    // This makes a palindrome impossible
                    return "-1";
                }
            }
        }

        // Pass 2: Fill remaining '?' characters based on available counts.
        // The original logic prefers '0' if countZero > countOne, otherwise '1'.
        for (int i = 0; i <= length / 2; i++) {
            int left = i;
            int right = length - 1 - i;

            if (charArray[left] == '?') {
                // If left is '?', right must also be '?' due to Pass 1 logic,
                // unless left == right (middle element of an odd-length string).

                // Determine character to fill based on counts
                boolean fillZero = countZero > countOne;
                char fillChar = fillZero ? '0' : '1';

                charArray[left] = fillChar;
                if (left != right) {
                    charArray[right] = fillChar;
                }

                // Update counts
                if (fillZero) {
                    if (left == right) {
                        countZero--;
                    } else {
                        countZero -= 2;
                    }
                } else {
                    if (left == right) {
                        countOne--;
                    } else {
                        countOne -= 2;
                    }
                }
            }
        }

        // Final validation: Ensure all available characters were used exactly
        if (countZero != 0 || countOne != 0) {
            return "-1";
        }

        return new String(charArray);
    }
}

