/**
 * Solves palindrome construction problems with character constraints.
 * For each test case, it determines if a string with '?' wildcards can be
 * transformed into a palindrome containing exactly 'a' zeros and 'b' ones.
 */
public class PalindromeStringBalancer {

    public static void main(String[] args) {
        PalindromeStringBalancer balancer = new PalindromeStringBalancer();
        balancer.run();
    }

    /**
     * Orchestrates the reading of input and execution of test cases.
     */
    public void run() {
        Scanner scanner = new Scanner(System.in);
        if (!scanner.hasNextInt()) {
            return;
        }
        int numTestCases = scanner.nextInt();

        for (int t = 0; t < numTestCases; t++) {
            int targetCount0 = scanner.nextInt();
            int targetCount1 = scanner.nextInt();
            String inputString = scanner.next();

            String result = processTestCase(targetCount0, targetCount1, inputString);
            System.out.println(result);
        }
        scanner.close();
    }

    /**
     * Processes a single test case to determine if a valid palindrome can be formed.
     *
     * @param targetCount0 The required number of '0' characters
     * @param targetCount1 The required number of '1' characters
     * @param s            The input string containing digits and '?' wildcards
     * @return The valid palindrome string, or "-1" if impossible
     */
    private String processTestCase(int targetCount0, int targetCount1, String s) {
        char[] chars = s.toCharArray();
        int len = chars.length;
        int left = 0;
        int right = len - 1;
        int currentCount0 = 0;
        int currentCount1 = 0;
        boolean possible = true;

        // First pass: Resolve conflicts and count known characters
        while (left < right) {
            char leftChar = chars[left];
            char rightChar = chars[right];

            if (leftChar != rightChar) {
                if (leftChar == '?') {
                    chars[left] = rightChar;
                } else if (rightChar == '?') {
                    chars[right] = leftChar;
                } else {
                    // Mismatch between two non-wildcard characters
                    possible = false;
                    break;
                }
                // Update counts based on the resolved character
                if (chars[left] == '0') currentCount0 += 2;
                else currentCount1 += 2;
            } else {
                // Characters match
                if (leftChar != '?') {
                    if (leftChar == '0') currentCount0 += 2;
                    else currentCount1 += 2;
                }
            }
            left++;
            right--;
        }

        if (possible) {
            // Handle the middle character if the length is odd
            if (left == right && chars[left] != '?') {
                if (chars[left] == '0') currentCount0++;
                else currentCount1++;
            }

            // Second pass: Fill remaining '?' characters
            left = 0;
            right = len - 1;
            while (left < right) {
                if (chars[left] == '?') {
                    // Prefer '0' if we have capacity for a pair, otherwise use '1'
                    if (currentCount0 + 2 <= targetCount0) {
                        currentCount0 += 2;
                        chars[left] = chars[right] = '0';
                    } else {
                        currentCount1 += 2;
                        chars[left] = chars[right] = '1';
                    }
                }
                left++;
                right--;
            }

            // Fill the middle '?' if it exists
            if (left == right && chars[left] == '?') {
                if (currentCount0 < targetCount0) {
                    chars[left] = '0';
                    currentCount0++;
                } else {
                    chars[left] = '1';
                    currentCount1++;
                }
            }

            // Final validation: Ensure exact counts are met
            if (currentCount0 != targetCount0 || currentCount1 != targetCount1) {
                possible = false;
            }
        }

        return possible ? new String(chars) : "-1";
    }
}

import java.util.Scanner;

/**
 * Constructs a valid palindrome from a character array containing '0', '1', and '?'.
 * Replaces '?' characters using exactly the specified counts of '0's and '1's.
 */
public class PalindromeBuilder {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int testCases = scanner.nextInt();

        for (int t = 0; t < testCases; t++) {
            int count0 = scanner.nextInt();
            int count1 = scanner.nextInt();
            String input = scanner.next();

            String result = solveTestCase(input.toCharArray(), count0, count1);
            System.out.println(result);
        }
        scanner.close();
    }

    /**
     * Processes a single test case to build a palindrome or determine impossibility.
     *
     * @param chars   The character array containing '0', '1', and '?'
     * @param count0  Available number of '0's to place
     * @param count1  Available number of '1's to place
     * @return        The resulting palindrome string, or "-1" if impossible
     */
    private static String solveTestCase(char[] chars, int count0, int count1) {
        int n = chars.length;

        // Pass 1: Mirror known characters to '?' positions to enforce symmetry
        for (int i = 0, j = n - 1; i <= j; i++, j--) {
            if (chars[i] != '?' && chars[j] == '?') {
                chars[j] = chars[i];
            } else if (chars[i] == '?' && chars[j] != '?') {
                chars[i] = chars[j];
            }
        }

        // Pass 2: Account for already placed characters and decrement available counts
        for (char c : chars) {
            if (c == '0') count0--;
            else if (c == '1') count1--;
        }

        // Pass 3: Fill remaining '?' from outside to inside
        for (int i = 0, j = n - 1; i <= j; i++, j--) {
            if (chars[i] != chars[j]) {
                return "-1"; // Symmetry violation detected
            }

            if (chars[i] != '?') continue;

            if (i == j) {
                // Center character (only for odd-length strings)
                if (count0 > 0) {
                    count0--;
                    chars[i] = '0';
                } else if (count1 > 0) {
                    count1--;
                    chars[i] = '1';
                }
            } else {
                // Symmetric pair
                if (count0 >= 2) {
                    count0 -= 2;
                    chars[i] = '0';
                    chars[j] = '0';
                } else if (count1 >= 2) {
                    count1 -= 2;
                    chars[i] = '1';
                    chars[j] = '1';
                }
            }
        }

        // Pass 4: Verify that exactly the required number of '0's and '1's were used
        if (count0 != 0 || count1 != 0) {
            return "-1";
        }

        return new String(chars);
    }
}

