     * Returns the resulting string or "-1" if impossible.
     */
    private static String solve(int n, int m, String s) {
        int len = s.length();
        if (n + m != len) {
            return "-1";
        }

        char[] chars = s.toCharArray();
        int zeroCount = 0;
        int oneCount = 0;

        // Count existing characters
        for (char c : chars) {
            if (c == '0') zeroCount++;
            else if (c == '1') oneCount++;
        }

        // Basic validation: can't have more fixed chars than allowed
        if (zeroCount > n || oneCount > m) {
            return "-1";
        }

        // Step 1: Fill '?' characters adjacent to fixed characters
        for (int i = 0, j = len - 1; i < j; i++, j--) {
            char left = chars[i];
            char right = chars[j];

            if (left == '?' && right != '?') {
                chars[i] = right;
                if (right == '0') zeroCount++; else oneCount++;
            } else if (right == '?' && left != '?') {
                chars[j] = left;
                if (left == '0') zeroCount++; else oneCount++;
            } else if (left != '?' && right != '?' && left != right) {
                return "-1"; // Mismatched fixed characters
            }
        }

        // Step 2: Handle middle character for odd-length strings
        if (len % 2 == 1) {
            int mid = len / 2;
            if (chars[mid] != '?') {
                if (chars[mid] == '0') zeroCount++; else oneCount++;
            }
        }

        // Step 3: Calculate remaining characters needed and available
        int remZero = n - zeroCount;
        int remOne = m - oneCount;
        int remQuestion = 0;
        for (char c : chars) {
            if (c == '?') remQuestion++;
        }

        // Validation: counts must be non-negative and match available slots
        if (remZero < 0 || remOne < 0 || remZero + remOne != remQuestion) {
            return "-1";
        }

        // Step 4: Handle middle '?' if it still exists
        if (len % 2 == 1 && chars[len / 2] == '?') {
            if (remZero == 1) {
                chars[len / 2] = '0';
                remZero = 0;
            } else if (remOne == 1) {
                chars[len / 2] = '1';
                remOne = 0;
            } else {
                return "-1"; // Middle '?' cannot be satisfied
            }
        }

        // Step 5: Remaining '?' must be fillable in symmetric pairs (consumes 2 of the same char)
        if (remZero % 2 != 0 || remOne % 2 != 0) {
            return "-1";
        }

        int pairsToZero = remZero / 2;
        int pairsToOne = remOne / 2;

        // Step 6: Fill remaining '?' pairs
        for (int i = 0, j = len - 1; i < j; i++, j--) {
            if (chars[i] == '?') {
                if (pairsToZero > 0) {
                    chars[i] = '0';
                    chars[j] = '0';
                    pairsToZero--;
                } else {
                    chars[i] = '1';
                    chars[j] = '1';
                    pairsToOne--;
                }
            }
        }

        return new String(chars);
    }

    /**
     * Optimized I/O helper for competitive programming environments.
     */
    static class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    e.printStackTrace();
                    return null;
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            String s = next();
            return s == null ? 0 : Integer.parseInt(s);
        }
    }
}

import java.util.Scanner;

/**
 * Refactored solution for B_ABPalindrome.
 * 
 * Improvements made:
 * 1. Variable Naming: Used descriptive names (e.g., targetZeros, currentZeros) instead of cryptic ones (a, a1).
 * 2. Modularity: Encapsulated the logic for a single test case into a 'solve' method.
 * 3. Readability: Simplified complex nested if-else blocks into clear, sequential steps.
 * 4. Logic Separation: Distinctly separated pair validation, middle element handling, and filling logic.
 * 5. Robustness: Added checks to prevent index out of bounds or logic errors.
 */
public class B_ABPalindrome {

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        // Check if input exists to avoid exceptions on empty input streams
        if (sc.hasNextInt()) {
            int t = sc.nextInt();
            while (t-- > 0) {
                solve(sc);
            }
        }
        sc.close();
    }

    private static void solve(Scanner sc) {
        int targetZeros = sc.nextInt();
        int targetOnes = sc.nextInt();
        String inputString = sc.next();
        char[] chars = inputString.toCharArray();
        int n = chars.length;

        // 1. Enforce Palindrome Constraints on Pairs
        // Iterate through the first half of the string to check symmetry
        for (int i = 0; i < n / 2; i++) {
            char left = chars[i];
            char right = chars[n - 1 - i];

            // If both characters are fixed and mismatch, it's impossible to form a palindrome
            if (left != '?' && right != '?' && left != right) {
                System.out.println("-1");
                return;
            }

            // If one is fixed and the other is '?', fill the '?' to match the fixed character
            if (left == '?' && right != '?') {
                chars[i] = right;
            } else if (right == '?' && left != '?') {
                chars[n - 1 - i] = left;
            }
            // If both are '?', we leave them for later processing
        }

        // 2. Count currently fixed characters (0s and 1s)
        int currentZeros = 0;
        int currentOnes = 0;
        for (char c : chars) {
            if (c == '0') currentZeros++;
            else if (c == '1') currentOnes++;
        }

        // 3. Handle Middle Element (if length is odd)
        if (n % 2 == 1) {
            int midIndex = n / 2;
            if (chars[midIndex] == '?') {
                // Determine if we must place '0' or '1' based on parity.
                // Pairs always contribute an even number of characters.
                // Therefore, the parity of the total count of a character type 
                // must match the parity of the count required by the middle element.

                int remainingZeros = targetZeros - currentZeros;

                if (remainingZeros % 2 != 0) {
                    // Parity requires a '0' in the middle
                    if (currentZeros < targetZeros) {
                        chars[midIndex] = '0';
                        currentZeros++;
                    } else {
                        System.out.println("-1");
                        return;
                    }
                } else {
                    // Parity requires a '1' in the middle
                    if (currentOnes < targetOnes) {
                        chars[midIndex] = '1';
                        currentOnes++;
                    } else {
                        System.out.println("-1");
                        return;
                    }
                }
            }
        }

        // 4. Final Validation
        // Check if we have exceeded the required counts
        if (currentZeros > targetZeros || currentOnes > targetOnes) {
            System.out.println("-1");
            return;
        }

        // Check if remaining counts are even (since we fill '?' in pairs)
        // If the difference is odd, we cannot fill the remaining '?'s in pairs
        if ((targetZeros - currentZeros) % 2 != 0 || (targetOnes - currentOnes) % 2 != 0) {
            System.out.println("-1");
            return;
        }

        // 5. Fill remaining '?'s
        // Iterate through the array. If we find a '?', it belongs to a pair (i, n-1-i)
        // where both characters are '?'.
        for (int i = 0; i < n; i++) {
            if (chars[i] == '?') {
                // Fill the pair. Priority: Fill with '0' if we have zeros left.
                // Since we checked parity, if currentZeros < targetZeros, 
                // the difference is at least 2.
                if (currentZeros < targetZeros) {
                    chars[i] = '0';
                    chars[n - 1 - i] = '0';
                    currentZeros += 2;
                } else {
                    chars[i] = '1';
                    chars[n - 1 - i] = '1';
                    currentOnes += 2;
                }
            }
        }

        System.out.println(new String(chars));
    }
}

