public class ABPalindrome {

    public static void main(String[] args) {
        FastScanner sc = new FastScanner();
        PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out));

        try {
            int testCases = sc.nextInt();
            while (testCases-- > 0) {
                int zeros = sc.nextInt();
                int ones = sc.nextInt();
                String line = sc.next();
                out.println(solve(zeros, ones, line));
            }
        } finally {
            out.flush();
            out.close();
        }
    }

    /**
     * Attempts to construct a palindrome from the given string by replacing '?' 
     * characters with '0's and '1's according to the provided counts.
     *
     * @param zeros Required number of '0's
     * @param ones  Required number of '1's
     * @param line  Input string containing '0', '1', and '?'
     * @return The constructed palindrome, or "-1" if impossible
     */
    private static String solve(int zeros, int ones, String line) {
        int n = line.length();
        char[] chars = line.toCharArray();
        int questionMarks = 0;

        // Count existing question marks
        for (char c : chars) {
            if (c == '?') questionMarks++;
        }

        // If the required counts don't match the number of '?', it's impossible
        if (zeros + ones != questionMarks) {
            return "-1";
        }

        // If no '?' exists, just verify if it's already a palindrome
        if (questionMarks == 0) {
            return isPalindrome(chars) ? line : "-1";
        }

        // Pass 1: Resolve '?' when paired with a known character
        for (int i = 0; i <= (n - 1) / 2; i++) {
            int j = n - 1 - i;
            char left = chars[i];
            char right = chars[j];

            if (left == '?' && right != '?') {
                chars[i] = right;
                if (right == '0') zeros--; else ones--;
            } else if (right == '?' && left != '?') {
                chars[j] = left;
                if (left == '0') zeros--; else ones--;
            }
        }

        // Pass 2: Resolve '?' when both sides are unknown
        for (int i = 0; i <= (n - 1) / 2; i++) {
            int j = n - 1 - i;
            if (chars[i] == '?' && chars[j] == '?') {
                if (i == j) { // Middle character (odd length)
                    if (zeros > 0) {
                        chars[i] = '0';
                        zeros--;
                    } else if (ones > 0) {
                        chars[i] = '1';
                        ones--;
                    } else {
                        return "-1";
                    }
                } else {
                    if (zeros >= 2) {
                        chars[i] = chars[j] = '0';
                        zeros -= 2;
                    } else if (ones >= 2) {
                        chars[i] = chars[j] = '1';
                        ones -= 2;
                    } else {
                        return "-1";
                    }
                }
            }
        }

        // If we still have unused counts, the configuration was invalid
        if (zeros != 0 || ones != 0) {
            return "-1";
        }

        return new String(chars);
    }

    /**
     * Checks if a character array represents a palindrome.
     */
    private static boolean isPalindrome(char[] chars) {
        int n = chars.length;
        for (int i = 0; i < n / 2; i++) {
            if (chars[i] != chars[n - 1 - i]) {
                return false;
            }
        }
        return true;
    }

    /**
     * Fast I/O scanner for competitive programming.
     */
    private static class FastScanner {
        BufferedReader br;
        StringTokenizer st;

        public FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input", e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        long nextLong() {
            return Long.parseLong(next());
        }

        double nextDouble() {
            return Double.parseDouble(next());
        }
    }
}

