                }
            }
        }
    }

    /**
     * Attempts to construct a palindrome from the template string using the available counts of '0's and '1's.
     * 
     * @param template The input string containing '0', '1', and '?' characters.
     * @param countZeros The total number of '0's available to place.
     * @param countOnes The total number of '1's available to place.
     * @return The constructed palindrome string, or "-1" if impossible.
     */
    public static String buildPalindrome(String template, int countZeros, int countOnes) {
        int n = template.length();

        // Validation: The template length must match the total count of characters available
        if (n != countZeros + countOnes) {
            return "-1";
        }

        char[] chars = template.toCharArray();

        // Step 1: Resolve '?' pairs based on existing characters
        // If one side is known, fill the other. If both are '?' or mismatched, handle later or fail.
        for (int i = 0; i < n / 2; i++) {
            char left = chars[i];
            char right = chars[n - 1 - i];

            if (left != '?' && right != '?' && left != right) {
                return "-1"; // Mismatch of fixed characters
            }

            if (left == '?') {
                chars[i] = right; // Fill left with right
            } else if (right == '?') {
                chars[n - 1 - i] = left; // Fill right with left
            }
        }

        // Step 2: Consume resources for characters already present in the first half
        for (int i = 0; i < n / 2; i++) {
            if (chars[i] == '0') {
                countZeros -= 2;
            } else if (chars[i] == '1') {
                countOnes -= 2;
            }
        }

        // Step 3: Fill remaining '?' pairs
        for (int i = 0; i < n / 2; i++) {
            if (chars[i] == '?') {
                // Priority: Place '0' if possible, then '1'
                if (countZeros >= 2) {
                    chars[i] = '0';
                    chars[n - 1 - i] = '0';
                    countZeros -= 2;
                } else if (countOnes >= 2) {
                    chars[i] = '1';
                    chars[n - 1 - i] = '1';
                    countOnes -= 2;
                } else {
                    return "-1"; // Cannot fill this pair
                }
            }
        }

        // Step 4: Handle the middle element for odd-length strings
        if (n % 2 != 0) {
            int mid = n / 2;
            if (chars[mid] == '?') {
                // If we have an odd number of zeros left, we must place a '0' in the center.
                // (Since pairs consume 2, an odd count implies 1 remaining).
                if (countZeros % 2 != 0) {
                    chars[mid] = '0';
                    countZeros--;
                } else {
                    // Otherwise, place '1'
                    chars[mid] = '1';
                    countOnes--;
                }
            } else {
                // Middle element was already fixed, consume the resource
                if (chars[mid] == '0') {
                    countZeros--;
                } else if (chars[mid] == '1') {
                    countOnes--;
                }
            }
        }

        // Step 5: Final validation
        // All resources must be exactly used up
        if (countZeros != 0 || countOnes != 0) {
            return "-1";
        }

        return new String(chars);
    }
}

