            if (chars[left] == '?' && chars[right] != '?') {
                chars[left] = chars[right];
            } else if (chars[right] == '?' && chars[left] != '?') {
                chars[right] = chars[left];
            }
        }

        // 2. Count existing characters and deduct from available counts
        for (char c : chars) {
            if (c == '0') {
                zerosAvailable--;
            } else if (c == '1') {
                onesAvailable--;
            }
        }

        // 3. Fill remaining '?' characters
        // Iterate through the first half to handle pairs efficiently
        for (int i = 0; i < n / 2; i++) {
            int left = i;
            int right = n - 1 - i;
            if (chars[left] == '?') {
                // Greedy choice: fill with the digit that has a higher remaining count
                // This matches the original logic: if (a > b) fill '0' else fill '1'
                if (zerosAvailable > onesAvailable) {
