/**
 * Refactored version of ABPalindrome.
 * 
 * Improvements made:
 * 1. Separation of Concerns: Logic is split into 'solveTestCase' and 'isPalindrome'.
 * 2. Readability: Variable names are descriptive (e.g., 'countZero' instead of 'a').
 * 3. Robust Input Handling: Uses 'StringTokenizer' to handle whitespace safely.
 * 4. Efficient I/O: Uses 'BufferedReader' and 'PrintWriter' for performance.
 * 5. Algorithm Optimization: Reduced redundant loops and clarified the logic flow.
 */
public class ABPalindrome {

    public static void main(String[] args) throws IOException {
        // Use BufferedReader for fast input reading
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        // Use PrintWriter for buffered output (better than System.out.println in loops)
        PrintWriter out = new PrintWriter(System.out);

        String line = br.readLine();
        if (line != null && !line.trim().isEmpty()) {
            int t = Integer.parseInt(line.trim());

            while (t-- > 0) {
                // Read 'a' (count of 0s) and 'b' (count of 1s)
                // Using StringTokenizer to handle potential irregular spacing
                String lineAB = br.readLine();
                while (lineAB != null && lineAB.trim().isEmpty()) {
                    lineAB = br.readLine();
                }
                if (lineAB == null) break;

                StringTokenizer st = new StringTokenizer(lineAB);
                int countZero = Integer.parseInt(st.nextToken());
                int countOne = Integer.parseInt(st.nextToken());

                // Read the string 's'
                String s = br.readLine();
                while (s != null && s.trim().isEmpty()) {
                    s = br.readLine();
                }
                if (s == null) break;
                s = s.trim();

                String result = solveTestCase(countZero, countOne, s);
                out.println(result);
            }
        }
        out.flush();
    }

    /**
     * Solves a single test case for the AB Palindrome problem.
     * 
     * @param countZero The number of '0's available to use.
     * @param countOne  The number of '1's available to use.
     * @param s         The input string containing '0', '1', and '?'.
     * @return          The resulting palindrome string, or "-1" if impossible.
     */
    private static String solveTestCase(int countZero, int countOne, String s) {
        char[] chars = s.toCharArray();
        int n = chars.length;

        // Step 1: Propagate known characters to their mirror positions.
        // If one side is known and the other is '?', fill the '?'.
        // We only need to iterate up to n/2 because pairs are symmetric.
        for (int i = 0; i < n / 2; i++) {
            int j = n - 1 - i;
            if (chars[i] == '?' && chars[j] != '?') {
                chars[i] = chars[j];
            } else if (chars[j] == '?' && chars[i] != '?') {
                chars[j] = chars[i];
            }
        }

        // Step 2: Count current usage of '0's and '1's and count remaining '?'s.
        int usedZero = 0;
        int usedOne = 0;
        int remainingQuestionMarks = 0;

        for (char c : chars) {
            if (c == '0') {
                usedZero++;
            } else if (c == '1') {
                usedOne++;
            } else {
                remainingQuestionMarks++;
            }
        }

        // Check if the already placed characters exceed the available counts
        if (usedZero > countZero || usedOne > countOne) {
            return "-1";
        }

        int remZero = countZero - usedZero;
        int remOne = countOne - usedOne;

        // Check if the number of remaining '?'s matches the sum of remaining characters
        if (remainingQuestionMarks != remZero + remOne) {
            return "-1";
        }

        // Step 3: Fill the remaining '?'s.
        // We iterate up to n/2 to handle pairs. If n is odd, the middle element is included.
        for (int i = 0; i <= n / 2; i++) {
            int j = n - 1 - i;

            // If the character at i is still '?', it means the mirror logic didn't fill it.
            // This implies both chars[i] and chars[j] were '?' (or it's the middle element).
            if (chars[i] == '?') {
                // Greedy strategy: If we have more '0's left than '1's, prioritize '0'.
                // This matches the logic in the original code: if (a > b) fill '0'.
                if (remZero > remOne) {
                    chars[i] = '0';
                    chars[j] = '0';
                    // Decrement count: 1 if middle element, 2 if pair
                    remZero -= (i == j) ? 1 : 2;
                } else {
                    chars[i] = '1';
                    chars[j] = '1';
                    remOne -= (i == j) ? 1 : 2;
                }
            }
        }

        // Step 4: Final Validation.
        // We must have used exactly all available characters.
        if (remZero == 0 && remOne == 0) {
            // Verify it is a palindrome (though construction logic guarantees it, 
            // this is a safety check consistent with original code).
            if (isPalindrome(chars)) {
                return new String(chars);
            }
        }

        return "-1";
    }

    /**
     * Checks if a character array is a palindrome.
     */
    private static boolean isPalindrome(char[] arr) {
        int left = 0;
        int right = arr.length - 1;
        while (left < right) {
            if (arr[left] != arr[right]) {
                return false;
            }
            left++;
            right--;
        }
        return true;
    }
}

