     */
    public static String solve(int a, int b, String s) {
        char[] chars = s.toCharArray();
        int n = chars.length;

        // 1. Validate existing characters consume the budget.
        // We decrement 'a' and 'b' to track the remaining budget for '?'s.
        for (char c : chars) {
            if (c == '0') {
                a--;
            } else if (c == '1') {
                b--;
            }
        }

        // If existing characters exceed the allowed counts, it's impossible.
        if (a < 0 || b < 0) {
            return "-1";
        }

        // 2. Iterate through the first half of the string to fill '?'s.
        // We work from outside in to ensure palindrome symmetry.
        for (int i = 0; i < n / 2; i++) {
            int leftIndex = i;
            int rightIndex = n - 1 - i;
            char leftChar = chars[leftIndex];
            char rightChar = chars[rightIndex];

            if (leftChar == '?' && rightChar == '?') {
                // Both positions are '?'. We need to place a pair.
                // Greedy approach: prefer '0' if budget allows, else '1'.
                if (a >= 2) {
                    chars[leftIndex] = '0';
                    chars[rightIndex] = '0';
                    a -= 2;
                } else if (b >= 2) {
                    chars[leftIndex] = '1';
                    chars[rightIndex] = '1';
                    b -= 2;
                } else {
                    // Not enough characters to form a valid pair.
                    return "-1";
                }
            } else if (leftChar == '?') {
                // Left is '?', Right is a fixed digit.
                // Must match the Right digit.
                if (rightChar == '0' && a > 0) {
                    chars[leftIndex] = '0';
                    a--;
                } else if (rightChar == '1' && b > 0) {
                    chars[leftIndex] = '1';
                    b--;
                } else {
                    // Mismatch or insufficient budget.
                    return "-1";
                }
            } else if (rightChar == '?') {
                // Right is '?', Left is a fixed digit.
                // Must match the Left digit.
                if (leftChar == '0' && a > 0) {
                    chars[rightIndex] = '0';
                    a--;
                } else if (leftChar == '1' && b > 0) {
                    chars[rightIndex] = '1';
                    b--;
                } else {
                    // Mismatch or insufficient budget.
                    return "-1";
                }
            } else {
                // Both are fixed digits.
                // They must match for the string to be a palindrome.
                if (leftChar != rightChar) {
                    return "-1";
                }
            }
        }

        // 3. Handle the middle character if the string length is odd.
        if (n % 2 != 0 && chars[n / 2] == '?') {
            if (a > 0) {
                chars[n / 2] = '0';
                a--;
            } else if (b > 0) {
                chars[n / 2] = '1';
                b--;
            } else {
                // No characters left to fill the middle spot.
                return "-1";
            }
        }

        // 4. Final Validation:
        // We must have used exactly 'a' zeros and 'b' ones.
        // Since we decremented for existing chars and filled '?', 
        // a and b should be exactly 0.
        if (a != 0 || b != 0) {
            return "-1";
        }

        return new String(chars);
    }
}

