/**
 * Refactored Main class for palindrome construction.
 * 
 * Refactoring improvements:
 * 1. Removed dead code (unused utility methods like gcd, isPrime, ruffle_sort, and array helpers).
 * 2. Extracted problem-solving logic into a separate 'solve' method for better readability and testability.
 * 3. Improved variable naming (e.g., 'zero' -> 'targetZeros').
 * 4. Simplified the logic inside the main loop by reducing nested conditionals.
 * 5. Enhanced FastReader to handle EOF gracefully.
 * 6. Standardized imports and formatting.
 */
public class Main {
    static PrintWriter out;
    static FastReader scan;

    public static void main(String[] args) {
        out = new PrintWriter(System.out);
        scan = new FastReader();

        try {
            // Read number of test cases
            String tStr = scan.next();
            if (tStr != null) {
                int t = Integer.parseInt(tStr);
                while (t-- > 0) {
                    int zero = scan.nextInt();
                    int one = scan.nextInt();
                    String s = scan.next();
                    out.println(solve(zero, one, s));
                }
            }
        } catch (Exception e) {
            // In a production environment, log this. In CP, usually ignored.
        } finally {
            out.flush();
            out.close();
        }
    }

    /**
     * Solves the palindrome construction problem.
     * 
     * @param targetZeros The required number of '0' characters.
     * @param targetOnes  The required number of '1' characters.
     * @param s           The input string containing '0', '1', and '?'.
     * @return            The constructed palindrome string, or "-1" if impossible.
     */
    private static String solve(int targetZeros, int targetOnes, String s) {
        char[] chars = s.toCharArray();
        int n = chars.length;

        // 1. Count existing characters and decrement targets
        for (char c : chars) {
            if (c == '0') {
                targetZeros--;
            } else if (c == '1') {
                targetOnes--;
            }
        }

        // If we already exceeded the required counts, it's impossible
        if (targetZeros < 0 || targetOnes < 0) {
            return "-1";
        }

        // 2. First pass: Resolve '?' characters based on their symmetric counterpart
        for (int i = 0; i < n / 2; i++) {
            char left = chars[i];
            char right = chars[n - 1 - i];

            if (left != '?' && right != '?') {
                // Both are known, check for conflict
                if (left != right) {
                    return "-1";
                }
            } else if (left != '?') {
                // Left is known, fill right
                chars[n - 1 - i] = left;
                if (left == '0') targetZeros--;
                else targetOnes--;
            } else if (right != '?') {
                // Right is known, fill left
                chars[i] = right;
                if (right == '0') targetZeros--;
                else targetOnes--;
            }
        }

        // Check counts again after filling forced '?'
        if (targetZeros < 0 || targetOnes < 0) {
            return "-1";
        }

        // 3. Second pass: Fill remaining '?' pairs (where both sides are '?')
        for (int i = 0; i < n / 2; i++) {
            if (chars[i] == '?' && chars[n - 1 - i] == '?') {
                if (targetZeros >= 2) {
                    chars[i] = chars[n - 1 - i] = '0';
                    targetZeros -= 2;
                } else if (targetOnes >= 2) {
                    chars[i] = chars[n - 1 - i] = '1';
                    targetOnes -= 2;
                } else {
                    // Cannot fill this pair
                    return "-1";
                }
            }
        }

        // 4. Handle the middle element if the string length is odd
        if (n % 2 != 0) {
            int mid = n / 2;
            if (chars[mid] == '?') {
                if (targetZeros >= 1) {
                    chars[mid] = '0';
                    targetZeros--;
                } else if (targetOnes >= 1) {
                    chars[mid] = '1';
                    targetOnes--;
                } else {
                    // Cannot fill the middle element
                    return "-1";
                }
            }
        }

        // 5. Final validation: All targets must be exactly met
        if (targetZeros == 0 && targetOnes == 0) {
            return new String(chars);
        } else {
            return "-1";
        }
    }

    /**
     * Fast I/O Helper Class
     */
    static class FastReader {
        BufferedReader br;
        StringTokenizer st;

        public FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    e.printStackTrace();
                    return null;
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            String s = next();
            if (s == null) throw new RuntimeException("End of input");
            return Integer.parseInt(s);
        }

        long nextLong() {
            String s = next();
            if (s == null) throw new RuntimeException("End of input");
            return Long.parseLong(s);
        }

        double nextDouble() {
            String s = next();
            if (s == null) throw new RuntimeException("End of input");
            return Double.parseDouble(s);
        }

        String nextLine() {
            String str = "";
            try {
                str = br.readLine();
            } catch (IOException e) {
                e.printStackTrace();
            }
            return str;
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayList;
import java.util.List;
import java.util.StringTokenizer;

public class Main {

    /**
     * Fast I/O helper class optimized for competitive programming.
     * Handles tokenization and stream reading safely.
     */
    static class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) {
                        return null;
                    }
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input stream", e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            String token = next();
            return token == null ? 0 : Integer.parseInt(token);
        }

        long nextLong() {
            String token = next();
            return token == null ? 0L : Long.parseLong(token);
        }

        double nextDouble() {
            String token = next();
            return token == null ? 0.0 : Double.parseDouble(token);
        }

        String nextLine() {
            String str = "";
            try {
                str = br.readLine();
            } catch (IOException e) {
                throw new RuntimeException("Error reading line", e);
            }
            return str;
        }
    }

    public static void main(String[] args) {
        FastReader reader = new FastReader();
        String tStr = reader.next();
        if (tStr == null) {
            return;
        }
        int testCases = Integer.parseInt(tStr);

        while (testCases-- > 0) {
            processTestCase(reader);
        }
    }

    /**
     * Processes a single test case: replaces '?' characters with '0' and '1'
     * to match the target counts of zeros and ones. Prints the result or -1.
     */
    private static void processTestCase(FastReader reader) {
        int targetZeros = reader.nextInt();
        int targetOnes = reader.nextInt();
        String input = reader.next();
        char[] chars = input.toCharArray();
        int len = chars.length;
        int left = 0;
        int right = len - 1;

        List<Integer> unknownPairIndices = new ArrayList<>();

        while (left < right) {
            char leftChar = chars[left];
            char rightChar = chars[right];

            if (leftChar == '0' && rightChar == '1') {
                System.out.println("-1");
                return;
            } else if (leftChar == '0' && rightChar == '0') {
                targetZeros -= 2;
            } else if (leftChar == '1' && rightChar == '1') {
                targetOnes -= 2;
            } else if (leftChar == '0' && rightChar == '?') {
                chars[right] = '0';
                targetZeros -= 2;
            } else if (leftChar == '?' && rightChar == '0') {
                chars[left] = '0';
                targetZeros -= 2;
            } else if (leftChar == '1' && rightChar == '?') {
                chars[right] = '1';
                targetOnes -= 2;
            } else if (leftChar == '?' && rightChar == '1') {
                chars[left] = '1';
                targetOnes -= 2;
            } else if (leftChar == '?' && rightChar == '?') {
                unknownPairIndices.add(left);
            }
            left++;
            right--;
        }

        // Resolve remaining '?' pairs
        for (int idx : unknownPairIndices) {
            if (targetZeros >= 2) {
                chars[idx] = '0';
                chars[len - idx - 1] = '0';
                targetZeros -= 2;
            } else if (targetOnes >= 2) {
                chars[idx] = '1';
                chars[len - idx - 1] = '1';
                targetOnes -= 2;
            } else {
                System.out.println("-1");
                return;
            }
        }

        // Handle middle character for odd-length strings
        if (len % 2 != 0) {
            int mid = len / 2;
            if (chars[mid] == '?') {
                if (targetZeros > 0) {
                    chars[mid] = '0';
                    targetZeros--;
                } else if (targetOnes > 0) {
                    chars[mid] = '1';
                    targetOnes--;
                } else {
                    System.out.println("-1");
                    return;
                }
            } else {
                if (chars[mid] == '0') {
                    targetZeros--;
                } else if (chars[mid] == '1') {
                    targetOnes--;
                }
            }
        }

        // Final validation: both counters must be exactly zero
        if (targetZeros == 0 && targetOnes == 0) {
            System.out.println(new String(chars));
        } else {
            System.out.println("-1");
        }
    }
}

import java.io.BufferedOutputStream;
import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.OutputStream;
import java.io.PrintWriter;
import java.util.StringTokenizer;

public class Solution {
    private static final String ERROR_RESULT = "-1";

    public static void main(String[] args) {
        new Solution().solve(System.in, System.out);
    }

    public void solve(InputStream in, OutputStream out) {
        InputReader reader = new InputReader(in);
        PrintWriter writer = new PrintWriter(new BufferedOutputStream(out));

        int numTestCases = reader.nextInt();
        for (int i = 0; i < numTestCases; i++) {
            int maxZeros = reader.nextInt();
            int maxOnes = reader.nextInt();
            String pattern = reader.next();
            writer.println(solve(maxZeros, maxOnes, pattern));
        }

        writer.flush();
        writer.close();
    }

    private String solve(int maxZeros, int maxOnes, String pattern) {
        char[] chars = pattern.toCharArray();
        int len = chars.length;

        // Step 1: Enforce palindrome symmetry constraints
        for (int i = 0; i < len / 2; i++) {
            int j = len - 1 - i;
            if (chars[i] == '?' && chars[j] != '?') {
                chars[i] = chars[j];
            } else if (chars[i] != '?' && chars[j] == '?') {
                chars[j] = chars[i];
            } else if (chars[i] != '?' && chars[j] != '?' && chars[i] != chars[j]) {
                return ERROR_RESULT;
            }
        }

        // Step 2: Count existing characters
        int zeroCount = 0;
        int oneCount = 0;
        for (char c : chars) {
            if (c == '0') zeroCount++;
            else if (c == '1') oneCount++;
        }

        // Step 3: Validate against capacity limits
        if (zeroCount > maxZeros || oneCount > maxOnes) {
            return ERROR_RESULT;
        }

        // Step 4: Fill remaining '?' pairs
        for (int i = 0; i < len / 2; i++) {
            int j = len - 1 - i;
            if (chars[i] == '?') {
                if (zeroCount + 2 <= maxZeros) {
                    chars[i] = chars[j] = '0';
                    zeroCount += 2;
                } else if (oneCount + 2 <= maxOnes) {
                    chars[i] = chars[j] = '1';
                    oneCount += 2;
                } else {
                    return ERROR_RESULT;
                }
            }
        }

        // Step 5: Handle middle character for odd-length strings
        if (len % 2 == 1) {
            int mid = len / 2;
            if (chars[mid] == '?') {
                if (oneCount < maxOnes) {
                    chars[mid] = '1';
                    oneCount++;
                } else if (zeroCount < maxZeros) {
                    chars[mid] = '0';
                    zeroCount++;
                } else {
                    return ERROR_RESULT;
                }
            }
        }

        // Step 6: Final exact count validation
        if (zeroCount != maxZeros || oneCount != maxOnes) {
            return ERROR_RESULT;
        }

        return new String(chars);
    }

    private static class InputReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input", e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }
    }
}

import java.util.Scanner;

public class PalindromeConstructor {

    private static final char CHAR_ZERO = '0';
    private static final char CHAR_ONE = '1';
    private static final char CHAR_QUESTION = '?';
    private static final String RESULT_IMPOSSIBLE = "-1";

    public static void main(String[] args) {
        // Try-with-resources ensures the Scanner is properly closed
        try (Scanner scanner = new Scanner(System.in)) {
            if (scanner.hasNextInt()) {
                int testCases = scanner.nextInt();
                for (int i = 0; i < testCases; i++) {
                    int availableZeros = scanner.nextInt();
                    int availableOnes = scanner.nextInt();
                    String inputWord = scanner.next();
                    System.out.println(solve(availableZeros, availableOnes, inputWord));
                }
            }
        }
    }

    /**
     * Attempts to construct a palindrome from the given word by replacing '?'
     * characters with exactly 'availableZeros' zeros and 'availableOnes' ones.
     *
     * @param availableZeros Number of '0's available to fill '?'
     * @param availableOnes  Number of '1's available to fill '?'
     * @param inputWord      The string containing '0', '1', and '?'
     * @return The constructed palindrome, or "-1" if impossible
     */
    private static String solve(int availableZeros, int availableOnes, String inputWord) {
        char[] chars = inputWord.toCharArray();
        int n = chars.length;
        int questionMarkCount = 0;

        // Validate that available characters exactly match the number of '?'
        for (char c : chars) {
            if (c == CHAR_QUESTION) {
                questionMarkCount++;
            }
        }

        if (availableZeros + availableOnes != questionMarkCount) {
            return RESULT_IMPOSSIBLE;
        }

        int left = 0;
        int right = n - 1;

        // Pass 1: Resolve forced assignments and detect fixed character mismatches
        while (left < right) {
            char leftChar = chars[left];
            char rightChar = chars[right];

            if (leftChar == CHAR_QUESTION && rightChar == CHAR_QUESTION) {
                // Both are unknown, defer to Pass 2
            } else if (leftChar == CHAR_QUESTION) {
                chars[left] = rightChar;
                if (rightChar == CHAR_ZERO) {
                    if (--availableZeros < 0) return RESULT_IMPOSSIBLE;
                } else {
                    if (--availableOnes < 0) return RESULT_IMPOSSIBLE;
                }
            } else if (rightChar == CHAR_QUESTION) {
                chars[right] = leftChar;
                if (leftChar == CHAR_ZERO) {
                    if (--availableZeros < 0) return RESULT_IMPOSSIBLE;
                } else {
                    if (--availableOnes < 0) return RESULT_IMPOSSIBLE;
                }
            } else if (leftChar != rightChar) {
                // Fixed characters don't match, impossible to form a palindrome
                return RESULT_IMPOSSIBLE;
            }
            left++;
            right--;
        }

        // Pass 2: Fill remaining '?' pairs and the middle character (if any)
        left = 0;
        right = n - 1;
        while (left <= right) {
            if (chars[left] == CHAR_QUESTION && chars[right] == CHAR_QUESTION) {
                if (left == right) {
                    // Middle character for odd-length strings
                    chars[left] = (availableZeros > 0) ? CHAR_ZERO : CHAR_ONE;
                } else {
                    // Pair of '?' characters
                    if (availableZeros >= 2) {
                        chars[left] = CHAR_ZERO;
                        chars[right] = CHAR_ZERO;
                        availableZeros -= 2;
                    } else if (availableOnes >= 2) {
                        chars[left] = CHAR_ONE;
                        chars[right] = CHAR_ONE;
                        availableOnes -= 2;
                    } else {
                        // Neither count is sufficient to form a pair
                        return RESULT_IMPOSSIBLE;
                    }
                }
            }
            left++;
            right--;
        }

        // Final validation: ensure all available characters were exactly consumed
        if (availableZeros == 0 && availableOnes == 0) {
            return new String(chars);
        }
        return RESULT_IMPOSSIBLE;
    }
}

import java.io.*;
import java.util.*;

public class PalindromeConstructor {

    public static void main(String[] args) throws IOException {
        // Use try-with-resources to guarantee proper resource cleanup
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
             PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out))) {

            String line = br.readLine();
            if (line == null) return;

            StringTokenizer st = new StringTokenizer(line);
            int t = Integer.parseInt(st.nextToken());

            while (t-- > 0) {
                line = br.readLine();
                while (line != null && line.trim().isEmpty()) {
                    line = br.readLine();
                }
                if (line == null) break;

                st = new StringTokenizer(line);
                int totalZeros = Integer.parseInt(st.nextToken());
                int totalOnes = Integer.parseInt(st.nextToken());

                String template = br.readLine();
                if (template == null) break;

                String result = constructPalindrome(totalZeros, totalOnes, template);
                out.println(result != null ? result : "-1");
            }
        }
        // PrintWriter is automatically flushed and closed by try-with-resources
    }

    /**
     * Constructs a palindrome from a template string containing '0', '1', and '?',
     * ensuring the total count of '0's is exactly totalZeros and '1's is exactly totalOnes.
     *
     * @param totalZeros Required total number of '0's in the result
     * @param totalOnes  Required total number of '1's in the result
     * @param template   Input string with fixed characters and placeholders ('?')
     * @return The constructed palindrome, or null if impossible
     */
    private static String constructPalindrome(int totalZeros, int totalOnes, String template) {
        char[] result = template.toCharArray();
        int n = result.length;
        int zerosNeeded = totalZeros;
        int onesNeeded = totalOnes;

        // Step 1: Count existing characters and update required counts
        for (char c : result) {
            if (c == '0') zerosNeeded--;
            else if (c == '1') onesNeeded--;
        }

        // Step 2: Process symmetric pairs from the outside in
        for (int i = 0; i < n / 2; i++) {
            int j = n - 1 - i;
            char left = result[i];
            char right = result[j];

            if (left != '?' && right != '?') {
                // Both sides are fixed; they must match for a valid palindrome
                if (left != right) {
                    return null;
                }
            } else if (left != '?') {
                // Left is fixed, mirror to right
                result[j] = left;
                if (left == '0') zerosNeeded--;
                else onesNeeded--;
            } else if (right != '?') {
                // Right is fixed, mirror to left
                result[i] = right;
                if (right == '0') zerosNeeded--;
                else onesNeeded--;
            }
            // If both are '?', we handle them in the next step
        }

        // Step 3: Fill remaining '?' pairs
        for (int i = 0; i < n / 2; i++) {
            int j = n - 1 - i;
            if (result[i] == '?') {
                if (zerosNeeded >= 2) {
                    result[i] = result[j] = '0';
                    zerosNeeded -= 2;
                } else if (onesNeeded >= 2) {
                    result[i] = result[j] = '1';
                    onesNeeded -= 2;
                } else {
                    return null; // Not enough characters to fill the pair
                }
            }
        }

        // Step 4: Handle the middle character if the length is odd
        if (n % 2 == 1) {
            int mid = n / 2;
            if (result[mid] == '?') {
                if (zerosNeeded >= 1) {
                    result[mid] = '0';
                    zerosNeeded--;
                } else if (onesNeeded >= 1) {
                    result[mid] = '1';
                    onesNeeded--;
                } else {
                    return null; // Not enough characters for the middle
                }
            }
        }

        // Step 5: Verify exact counts were met
        if (zerosNeeded == 0 && onesNeeded == 0) {
            return new String(result);
        }

        return null;
    }
}

