    /**
     * FastScanner class for efficient input reading.
     * Handles tokenization and whitespace skipping automatically.
     */
    static class FastScanner {
        BufferedReader br;
        StringTokenizer st;

        public FastScanner(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            String s = next();
            if (s == null) throw new RuntimeException("Unexpected end of input");
            return Integer.parseInt(s);
        }
    }

    public static void main(String[] args) {
        // Use BufferedOutputStream for performance
        PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out));
        FastScanner in = new FastScanner(System.in);

        try {
            // Read number of test cases
            String tStr = in.next();
            if (tStr != null) {
                int T = Integer.parseInt(tStr);
                PalindromeSolver solver = new PalindromeSolver();

                while (T-- > 0) {
                    solver.solve(in, out);
                }
            }
        } catch (Exception e) {
            // In a real application, proper logging should be used here.
            e.printStackTrace();
        } finally {
            out.flush();
        }
    }

    /**
     * Logic handler for the palindrome problem.
     */
    static class PalindromeSolver {

        public void solve(FastScanner in, PrintWriter out) {
            try {
                // Read target counts for '0' and '1'
                // We use next() and parse to ensure we skip any whitespace/newlines cleanly
                String aStr = in.next();
                String bStr = in.next();

                if (aStr == null || bStr == null) return;

                int targetZeros = Integer.parseInt(aStr);
                int targetOnes = Integer.parseInt(bStr);
                int n = targetZeros + targetOnes;

                // Read the input string
                // If n is 0, the string is empty, so we don't consume a token.
                char[] s = new char[0];
                if (n > 0) {
                    String sStr = in.next();
                    if (sStr == null) {
                        out.println("-1");
                        return;
                    }
                    s = sStr.toCharArray();
                }

                // Validation: The string length must match the sum of required counts
                if (s.length != n) {
                    out.println("-1");
                    return;
                }

                // Count existing characters in the string
                int currentZeros = 0;
                int currentOnes = 0;
                for (char c : s) {
                    if (c == '0') currentZeros++;
                    else if (c == '1') currentOnes++;
                }

                // Calculate how many more '0's and '1's we need to fill in the '?'s
                int remZeros = targetZeros - currentZeros;
                int remOnes = targetOnes - currentOnes;

                // If the input string already has too many characters, it's impossible
                if (remZeros < 0 || remOnes < 0) {
                    out.println("-1");
                    return;
                }

                // Fill '?' characters to satisfy palindrome and count constraints
                // Iterate from both ends towards the center
                int left = 0;
                int right = n - 1;

                while (left < right) {
                    char leftChar = s[left];
                    char rightChar = s[right];

                    if (leftChar == '?' && rightChar == '?') {
                        // Both positions are unknown.
                        // They must be the same character to maintain palindrome property.
                        // We greedily assign '0' if we have enough count, otherwise '1'.
                        if (remZeros >= 2) {
                            s[left] = s[right] = '0';
                            remZeros -= 2;
                        } else if (remOnes >= 2) {
                            s[left] = s[right] = '1';
                            remOnes -= 2;
                        } else {
                            // Cannot fill this pair with available counts
                            out.println("-1");
                            return;
                        }
                    } else if (leftChar == '?' && rightChar != '?') {
                        // Left is unknown, Right is fixed.
                        // Left must match Right.
                        if (rightChar == '0') {
                            if (remZeros > 0) {
                                s[left] = '0';
                                remZeros--;
                            } else {
                                out.println("-1");
                                return;
                            }
                        } else { // '1'
                            if (remOnes > 0) {
                                s[left] = '1';
                                remOnes--;
                            } else {
                                out.println("-1");
                                return;
                            }
                        }
                    } else if (leftChar != '?' && rightChar == '?') {
                        // Left is fixed, Right is unknown.
                        // Right must match Left.
                        if (leftChar == '0') {
                            if (remZeros > 0) {
                                s[right] = '0';
                                remZeros--;
                            } else {
                                out.println("-1");
                                return;
                            }
                        } else { // '1'
                            if (remOnes > 0) {
                                s[right] = '1';
                                remOnes--;
                            } else {
                                out.println("-1");
                                return;
                            }
                        }
                    } else {
                        // Both are fixed. Check for consistency.
                        if (leftChar != rightChar) {
                            out.println("-1");
                            return;
                        }
                    }

                    left++;
                    right--;
                }

                // Handle the middle element if the length is odd
                if (left == right) {
                    if (s[left] == '?') {
                        if (remZeros >= 1) {
                            s[left] = '0';
                            remZeros--;
                        } else if (remOnes >= 1) {
                            s[left] = '1';
                            remOnes--;
                        } else {
                            out.println("-1");
                            return;
                        }
                    }
                }

                // Final verification: all counts must be exactly 0
                if (remZeros == 0 && remOnes == 0) {
                    out.println(new String(s));
                } else {
                    out.println("-1");
                }

            } catch (Exception e) {
                // Catch any unexpected exceptions during processing
                out.println("-1");
            }
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

public class Main {
    // Constants for improved readability and maintainability
    private static final char QUESTION = '?';
    private static final char ZERO = '0';
    private static final char ONE = '1';

    public static void main(String[] args) throws IOException {
        // Try-with-resources ensures proper cleanup of I/O streams
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
             PrintWriter writer = new PrintWriter(System.out)) {

            FastScanner scanner = new FastScanner(reader);
            int numTestCases = scanner.nextInt();

            for (int t = 0; t < numTestCases; t++) {
                int targetZeros = scanner.nextInt();
                int targetOnes = scanner.nextInt();
                String inputString = scanner.next();

                String result = solve(targetZeros, targetOnes, inputString);
                writer.println(result);
            }
            // Single flush at the end is significantly more efficient than flushing per character
            writer.flush();
        }
    }

    /**
     * Solves a single test case by filling '?' characters to form a palindrome
     * with exactly targetZeros '0's and targetOnes '1's.
     *
     * @param targetZeros Expected number of '0' characters
     * @param targetOnes  Expected number of '1' characters
     * @param input       Original string containing '?'
     * @return            Filled string if valid, otherwise "-1"
     */
    private static String solve(int targetZeros, int targetOnes, String input) {
        char[] chars = input.toCharArray();
        int n = chars.length;

        // Pass 1: Synchronize symmetric positions with known characters
        for (int i = 0; i <= n / 2; i++) {
            int mirror = n - i - 1;
            if (chars[i] != QUESTION && chars[mirror] == QUESTION) {
                chars[mirror] = chars[i];
            } else if (chars[i] == QUESTION && chars[mirror] != QUESTION) {
                chars[i] = chars[mirror];
            }
        }

        // Pass 2: Count existing '0's and '1's
        int[] charCounts = new int[2]; // Index 0 -> '0', Index 1 -> '1'
        for (char c : chars) {
            if (c != QUESTION) {
                charCounts[c - ZERO]++;
            }
        }

        // Pass 3: Fill remaining '?' pairs
        for (int i = 0; i <= n / 2; i++) {
            int mirror = n - i - 1;
            if (chars[i] == QUESTION && chars[mirror] == QUESTION) {
                int charsToFill = (i == mirror) ? 1 : 2;

                // Greedy assignment: prioritize '0' if it fits within the target count
                if (charCounts[0] + charsToFill <= targetZeros) {
                    chars[i] = ZERO;
                    chars[mirror] = ZERO;
                    charCounts[0] += charsToFill;
                } else {
                    chars[i] = ONE;
                    chars[mirror] = ONE;
                    charCounts[1] += charsToFill;
                }
            }
        }

        // Validation: Ensure exact count match
        // Note: isPalindrome() is intentionally omitted because symmetric filling
        // mathematically guarantees the result is always a palindrome.
        if (charCounts[0] == targetZeros && charCounts[1] == targetOnes) {
            return new String(chars);
        }
        return "-1";
    }

    /**
     * Fast I/O helper class optimized for competitive programming and large inputs.
     */
    private static class FastScanner {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastScanner(BufferedReader reader) {
            this.reader = reader;
        }

        public String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                String line = reader.readLine();
                if (line == null) {
                    throw new IOException("Unexpected end of input");
                }
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        public long nextLong() throws IOException {
            return Long.parseLong(next());
        }
    }
}

import java.io.*;
import java.util.*;

public class PalindromePatternSolver {
    // Represents the wildcard/unassigned value in the input pattern.
    // Kept as a constant for easy configuration and readability.
    private static final int WILDCARD = 15;

    public static void main(String[] args) {
        FastScanner sc = new FastScanner();
        PrintWriter out = new PrintWriter(System.out);

        int t = sc.nextInt();
        while (t-- > 0) {
            solve(sc, out);
        }
        out.flush();
    }

    private static void solve(FastScanner sc, PrintWriter out) {
        int count0 = sc.nextInt();
        int count1 = sc.nextInt();
        String pattern = sc.next();
        int n = count0 + count1;
        int[] arr = toIntArray(pattern);

        // Pass 1: Resolve wildcards based on their mirror partners and check for conflicts
        for (int i = 0; i < n / 2; i++) {
            int mirror = n - i - 1;
            if (hasConflict(arr[i], arr[mirror])) {
                out.println(-1);
                return;
            }
            resolveWildcardPair(arr, i, mirror);
        }

        // Count remaining fixed values to update available counts
        for (int val : arr) {
            if (val == 0) count0--;
            else if (val == 1) count1--;
        }

        // Pass 2: Assign remaining wildcards to available slots
        for (int i = 0; i < n / 2; i++) {
            int mirror = n - i - 1;
            if (arr[i] == WILDCARD) {
                if (count0 >= 2) {
                    arr[i] = arr[mirror] = 0;
                    count0 -= 2;
                } else {
                    arr[i] = arr[mirror] = 1;
                    count1 -= 2;
                }
            }
        }

        // Handle middle element for odd-length strings
        if (n % 2 == 1) {
            int mid = n / 2;
            if (arr[mid] == WILDCARD) {
                if (count0 >= 1) {
                    arr[mid] = 0;
                    count0--;
                } else {
                    arr[mid] = 1;
                    count1--;
                }
            }
        }

        // Final validation: ensure we didn't over-assign
        if (count0 < 0 || count1 < 0) {
            out.println(-1);
        } else {
            for (int val : arr) {
                out.print(val);
            }
            out.println();
        }
    }

    /**
     * Checks if two characters form an invalid pair (0 and 1).
     */
    private static boolean hasConflict(int a, int b) {
        return (a == 0 && b == 1) || (a == 1 && b == 0);
    }

    /**
     * Resolves wildcard values in a symmetric pair based on the non-wildcard partner.
     * If both are wildcards, defaults to 0 to maintain deterministic behavior.
     */
    private static void resolveWildcardPair(int[] arr, int i, int mirror) {
        if (arr[i] == 0 || arr[mirror] == 0) {
            if (arr[i] == WILDCARD || arr[mirror] == WILDCARD) {
                arr[i] = arr[mirror] = 0;
            }
        } else if (arr[i] == 1 || arr[mirror] == 1) {
            if (arr[i] == WILDCARD || arr[mirror] == WILDCARD) {
                arr[i] = arr[mirror] = 1;
            }
        }
    }

    /**
     * Converts a string of digits or letters into an integer array.
     * Automatically detects the base character ('0', 'a', or 'A') from the first character.
     */
    private static int[] toIntArray(String s) {
        if (s.isEmpty()) return new int[0];

        int len = s.length();
        int[] result = new int[len];
        char base = '0';
        char first = s.charAt(0);

        if (first >= 'a' && first <= 'z') {
            base = 'a';
        } else if (first >= 'A' && first <= 'Z') {
            base = 'A';
        }

        for (int i = 0; i < len; i++) {
            result[i] = s.charAt(i) - base;
        }
        return result;
    }

    /**
     * Fast I/O helper class for competitive programming and performance-critical applications.
     */
    static class FastScanner {
        BufferedReader br;
        StringTokenizer st;

        public FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) throw new IOException("End of input");
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.BufferedReader;
