/**
 * Competitive Programming solution for constructing a valid palindrome
 * with limited counts of '0' and '1' characters.
 */
public class CodeForces {

    public static void main(String[] args) {
        FastScanner sc = new FastScanner(System.in);
        StringBuilder output = new StringBuilder();
        int testCases = sc.nextInt();

        while (testCases-- > 0) {
            solve(sc, output);
        }
        System.out.print(output);
    }

    /**
     * Processes a single test case: validates constraints, resolves conflicts,
     * fills wildcards, and appends the result to the output buffer.
     */
    private static void solve(FastScanner sc, StringBuilder output) {
        int count0 = sc.nextInt();
        int count1 = sc.nextInt();
        char[] chars = sc.next().toCharArray();
        int left = 0;
        int right = chars.length - 1;

        // First pass: resolve conflicts and consume already-fixed characters
        while (left < right) {
            char leftChar = chars[left];
            char rightChar = chars[right];

            if (leftChar == rightChar) {
                if (leftChar == '0') {
                    count0 -= 2;
                } else if (leftChar == '1') {
                    count1 -= 2;
                }
            } else {
                // Characters differ; one must be a wildcard '?'
                if (leftChar == '?') {
                    chars[left] = rightChar;
                } else if (rightChar == '?') {
                    chars[right] = leftChar;
                } else {
                    output.append("-1\n");
                    return;
                }
                // Consume counts after resolution
                if (chars[left] == '0') {
                    count0 -= 2;
                } else {
                    count1 -= 2;
                }
            }
            left++;
            right--;
        }

        // Handle the middle character for odd-length strings
        if (left == right) {
            if (chars[left] == '0') {
                count0--;
            } else if (chars[left] == '1') {
                count1--;
            }
        }

        // Validate remaining counts: must be non-negative and not both odd
        if (count0 < 0 || count1 < 0 || (count0 % 2 != 0 && count1 % 2 != 0)) {
            output.append("-1\n");
            return;
        }

        // Second pass: fill remaining '?' characters greedily
        left = 0;
        right = chars.length - 1;
        while (left < right) {
            if (chars[left] == '?') {
                if (count0 >= 2) {
                    chars[left] = chars[right] = '0';
                    count0 -= 2;
                } else {
                    chars[left] = chars[right] = '1';
                    count1 -= 2;
                }
            }
            left++;
            right--;
        }

        // Fill the middle '?' if it exists
        if (left == right && chars[left] == '?') {
            if (count0 > 0) {
                chars[left] = '0';
            } else {
                chars[left] = '1';
            }
        }

        output.append(chars).append('\n');
    }

    /**
     * High-performance input reader for competitive programming.
     */
    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) {
                        return null;
                    }
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input", e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        long nextLong() {
            return Long.parseLong(next());
        }

        double nextDouble() {
            return Double.parseDouble(next());
        }

        String nextLine() {
            String str = "";
            try {
                str = br.readLine();
            } catch (IOException e) {
                throw new RuntimeException("Failed to read line", e);
            }
            return str;
        }
    }
}

import java.util.Scanner;

/**
 * A utility class to reconstruct a string pattern based on character counts.
 * It ensures the resulting string is a palindrome and respects the required
 * counts of '0's and '1's.
 */
public class StringPatternReconstructor {

    public static void main(String[] args) {
        // Use try-with-resources to ensure the Scanner is closed properly
        try (Scanner scanner = new Scanner(System.in)) {
            if (scanner.hasNextInt()) {
                int testCaseCount = scanner.nextInt();

                for (int i = 0; i < testCaseCount; i++) {
                    int requiredZeroCount = scanner.nextInt();
                    int requiredOneCount = scanner.nextInt();
                    String pattern = scanner.next();

                    System.out.println(reconstructPattern(pattern, requiredZeroCount, requiredOneCount));
                }
            }
        }
    }

    /**
     * Attempts to reconstruct a palindrome string from a pattern containing '0', '1', and '?'.
     * The result must satisfy the exact counts of '0's and '1's provided.
     *
     * @param pattern The input string containing '0', '1', and '?'
     * @param requiredZeroCount The exact number of '0's required in the result
     * @param requiredOneCount The exact number of '1's required in the result
     * @return The reconstructed palindrome string, or "-1" if impossible
     */
    public static String reconstructPattern(String pattern, int requiredZeroCount, int requiredOneCount) {
        char[] chars = pattern.toCharArray();
        int length = chars.length;

        // Track remaining counts. Using separate variables is more readable than an array.
        int zerosRemaining = requiredZeroCount;
        int onesRemaining = requiredOneCount;

        // Pass 1: Validate symmetry and resolve forced '?' placements
        int leftIndex = 0;
        int rightIndex = length - 1;

        while (leftIndex < rightIndex) {
            char leftChar = chars[leftIndex];
            char rightChar = chars[rightIndex];

            if (leftChar != '?' && rightChar != '?') {
                // Both are digits: they must match for a palindrome
                if (leftChar != rightChar) {
                    return "-1";
                }
                // Consume 2 of the matching digit
                if (leftChar == '0') {
                    zerosRemaining -= 2;
                } else {
                    onesRemaining -= 2;
                }
            } else if (leftChar == '?') {
                // Left is '?', Right is digit: Fill Left with Right's value
                chars[leftIndex] = rightChar;
                if (rightChar == '0') {
                    zerosRemaining -= 2;
                } else {
                    onesRemaining -= 2;
                }
            } else if (rightChar == '?') {
                // Right is '?', Left is digit: Fill Right with Left's value
                chars[rightIndex] = leftChar;
                if (leftChar == '0') {
                    zerosRemaining -= 2;
                } else {
                    onesRemaining -= 2;
                }
            }
            // If both are '?', we defer filling them to Pass 2

            leftIndex++;
            rightIndex--;
        }

        // Pass 2: Fill remaining '?' pairs
        leftIndex = 0;
        rightIndex = length - 1;

        while (leftIndex < rightIndex) {
            if (chars[leftIndex] == '?') {
                // We have a pair of '?' that needs filling
                // Priority: Fill with '0' if possible, otherwise '1'
                if (zerosRemaining >= 2) {
                    chars[leftIndex] = '0';
                    chars[rightIndex] = '0';
                    zerosRemaining -= 2;
                } else {
                    chars[leftIndex] = '1';
                    chars[rightIndex] = '1';
                    onesRemaining -= 2;
                }
            }
            leftIndex++;
            rightIndex--;
        }

        // Handle the middle element if the string length is odd
        if (length % 2 != 0) {
            int midIndex = length / 2;
            if (chars[midIndex] == '?') {
                // Fill middle with remaining count (needs 1)
                if (zerosRemaining >= 1) {
                    chars[midIndex] = '0';
                    zerosRemaining--;
                } else if (onesRemaining >= 1) {
                    chars[midIndex] = '1';
                    onesRemaining--;
                }
            } else {
                // Middle is a digit, consume 1 of that digit
                if (chars[midIndex] == '0') {
                    zerosRemaining--;
                } else {
                    onesRemaining--;
                }
            }
        }

        // Final Validation: Check if all required counts were exactly met
        if (zerosRemaining == 0 && onesRemaining == 0) {
            return new String(chars);
        }

        return "-1";
    }
}

