/**
 * Solves palindrome construction problems with character count constraints.
 * Refactored for maintainability, readability, and separation of concerns.
 */
public class CP {

    /**
     * Fast input reader for competitive programming environments.
     */
    static class FastReader {
        BufferedReader br;
        StringTokenizer st;

        public FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    e.printStackTrace();
                    return null;
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            String token = next();
            return token == null ? 0 : Integer.parseInt(token);
        }

        long nextLong() {
            String token = next();
            return token == null ? 0L : Long.parseLong(token);
        }

        double nextDouble() {
            String token = next();
            return token == null ? 0.0 : Double.parseDouble(token);
        }

        String nextLine() {
            String str = "";
            try {
                str = br.readLine();
            } catch (IOException e) {
                e.printStackTrace();
            }
            return str;
        }
    }

    public static void main(String[] args) {
        FastReader sc = new FastReader();
        String tcStr = sc.next();
        if (tcStr == null) return;

        int testCases = Integer.parseInt(tcStr);
        StringBuilder output = new StringBuilder();

        while (testCases-- > 0) {
            int zerosCount = sc.nextInt();
            int onesCount = sc.nextInt();
            String inputStr = sc.next();
            char[] arr = inputStr.toCharArray();
            int n = arr.length - 1;

            // Constraint 1: Total characters must match required counts
            if (zerosCount + onesCount != arr.length) {
                output.append("-1\n");
                continue;
            }

            // Constraint 2: Initial palindrome compatibility check
            if (!isPalindromeCompatible(arr)) {
                output.append("-1\n");
                continue;
            }

            boolean[] visited = new boolean[arr.length];

            // Pass 1: Resolve fixed '0's and '1's and mirror them
            for (int i = 0; i <= n; i++) {
                if (arr[i] == '0') {
                    if (arr[n - i] == '?') {
                        arr[n - i] = '0';
                    }
                    if (!visited[i]) {
                        zerosCount--;
                        visited[i] = true;
                    }
                    if (!visited[n - i]) {
                        zerosCount--;
                        visited[n - i] = true;
                    }
                } else if (arr[i] == '1') {
                    if (arr[n - i] == '?') {
                        arr[n - i] = '1';
                    }
                    if (!visited[i]) {
                        onesCount--;
                        visited[i] = true;
                    }
                    if (!visited[n - i]) {
                        onesCount--;
                        visited[n - i] = true;
                    }
                }
            }

            // Handle middle element for odd-length strings
            if (arr.length % 2 == 1) {
                int midIndex = arr.length / 2;
                if (zerosCount % 2 == 1) {
                    zerosCount--;
                    arr[midIndex] = '0';
                }
                if (onesCount % 2 == 1) {
                    onesCount--;
                    arr[midIndex] = '1'; // Preserves original overwrite behavior
                }
            }

            // Pass 2: Fill remaining '?' with symmetric pairs
            for (int i = 0; i <= n; i++) {
                if (arr[i] == '?') {
                    if (zerosCount > 0) {
                        arr[i] = '0';
                        arr[n - i] = '0';
                        zerosCount -= 2;
                    } else {
                        arr[i] = '1';
                        arr[n - i] = '1';
                        onesCount -= 2;
                    }
                }
            }

            String result = new String(arr);
            if (zerosCount == 0 && onesCount == 0 && isValidPalindrome(result)) {
                output.append(result).append("\n");
            } else {
                output.append("-1\n");
            }
        }
        System.out.print(output);
    }

    /**
     * Checks if the character array can form a palindrome, ignoring '?' placeholders.
     */
    private static boolean isPalindromeCompatible(char[] arr) {
        int left = 0;
        int right = arr.length - 1;
        while (left <= right) {
            if (arr[left] != arr[right] && arr[left] != '?' && arr[right] != '?') {
                return false;
            }
            left++;
            right--;
        }
        return true;
    }

    /**
     * Validates that the final string is a complete palindrome.
     * Side-effect free: removed original System.out.println debugging calls.
     */
    private static boolean isValidPalindrome(String str) {
        int left = 0;
        int right = str.length() - 1;
        while (left <= right) {
            if (str.charAt(left) != str.charAt(right)) {
                return false;
            }
            left++;
            right--;
        }
        return true;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;

public class Solution {

    /**
     * Constructs a valid palindrome from a template string containing '0', '1', and '?'.
     * '?' placeholders are replaced using the provided counts of '0's and '1's.
     *
     * @param template  The input string with '0', '1', and '?' characters
     * @param zeroCount Number of '0's available to replace '?'
     * @param oneCount  Number of '1's available to replace '?'
     * @return The constructed palindrome, or "-1" if no valid palindrome can be formed
     */
    public static String constructPalindrome(String template, int zeroCount, int oneCount) {
        if (template == null || template.isEmpty()) {
            return "-1";
        }

        char[] chars = template.toCharArray();
        int n = chars.length;

        // Count existing '0's and '1's to validate against available counts
        int existingZeros = 0;
        int existingOnes = 0;
        for (char c : chars) {
            if (c == '0') existingZeros++;
            else if (c == '1') existingOnes++;
        }

        if (existingZeros > zeroCount || existingOnes > oneCount) {
            return "-1";
        }

        // Deduct existing characters from the available counts
        zeroCount -= existingZeros;
        oneCount -= existingOnes;

        // If no placeholders remain, verify if the string is already a palindrome
        if (zeroCount == 0 && oneCount == 0) {
            return isPalindrome(chars) ? template : "-1";
        }

        // Two-pointer approach to fill '?' and enforce palindrome symmetry
        int left = 0;
        int right = n - 1;

        while (left < right) {
            char leftChar = chars[left];
            char rightChar = chars[right];

            if (leftChar == '?' && rightChar == '?') {
                // Both are placeholders: prefer '0's if available, else '1's
                if (zeroCount >= 2) {
                    chars[left] = '0';
                    chars[right] = '0';
                    zeroCount -= 2;
                } else if (oneCount >= 2) {
                    chars[left] = '1';
                    chars[right] = '1';
                    oneCount -= 2;
                } else {
                    return "-1"; // Not enough characters to fill the pair
                }
            } else if (leftChar == '?') {
                // Left is placeholder, right is fixed: mirror the right character
                chars[left] = rightChar;
                if (rightChar == '0') zeroCount--;
                else oneCount--;
            } else if (rightChar == '?') {
                // Right is placeholder, left is fixed: mirror the left character
                chars[right] = leftChar;
                if (leftChar == '0') zeroCount--;
                else oneCount--;
            } else {
                // Neither is a placeholder: they must match for a valid palindrome
                if (leftChar != rightChar) {
                    return "-1";
                }
            }
            left++;
            right--;
        }

        // Handle the middle character for odd-length strings
        if (left == right && chars[left] == '?') {
            if (zeroCount > 0) {
                chars[left] = '0';
                zeroCount--;
            } else if (oneCount > 0) {
                chars[left] = '1';
                oneCount--;
            } else {
                return "-1"; // Middle placeholder cannot be filled
            }
        }

        // Final safety check: ensure no '?' remain
        for (char c : chars) {
            if (c == '?') {
                return "-1";
            }
        }

        return new String(chars);
    }

    /**
     * Checks if a character array represents a palindrome.
     */
    private static boolean isPalindrome(char[] chars) {
        int left = 0;
        int right = chars.length - 1;
        while (left < right) {
            if (chars[left++] != chars[right--]) {
                return false;
            }
        }
        return true;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line = br.readLine();
        if (line == null) return;

        int t = Integer.parseInt(line.trim());
        while (t-- > 0) {
            String[] parts = br.readLine().trim().split("\\s+");
            int a = Integer.parseInt(parts[0]);
            int b = Integer.parseInt(parts[1]);
            String r = br.readLine().trim();
            System.out.println(constructPalindrome(r, a, b));
        }
    }
}

import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) {
        // Standard competitive programming setup: run solve() in a separate thread
        // with increased stack size to prevent StackOverflowError on deep recursion/large I/O.
        new Thread(null, new Runnable() {
            public void run() {
                try {
                    solve();
                } catch (Exception e) {
                    e.printStackTrace();
                }
            }
        }, "solve", 1 << 26).start();
    }

    private static void solve() {
        FastReader in = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);
        StringBuilder output = new StringBuilder();

        int t = in.nextInt();
        while (t-- > 0) {
            int maxZeros = in.nextInt();
            int maxOnes = in.nextInt();
            String pattern = in.next();
            output.append(solveTestCase(maxZeros, maxOnes, pattern)).append('\n');
        }

        out.print(output);
        out.flush();
        out.close();
    }

    /**
     * Solves a single test case: replaces '?' with '0' or '1' to form a valid palindrome
     * using at most maxZeros and maxOnes characters.
     */
    private static String solveTestCase(int maxZeros, int maxOnes, String pattern) {
        int n = pattern.length();
        char[] chars = pattern.toCharArray();

        // Preserve original parity constraint logic
        if (maxZeros % 2 != 0 && maxOnes % 2 != 0) {
            return "-1";
        }

        // Count existing characters
        int currentZeros = 0;
        int currentOnes = 0;
        for (char c : chars) {
            if (c == '0') currentZeros++;
            else if (c == '1') currentOnes++;
        }

        // Immediate failure if existing counts exceed limits
        if (currentZeros > maxZeros || currentOnes > maxOnes) {
            return "-1";
        }

        int remZeros = maxZeros - currentZeros;
        int remOnes = maxOnes - currentOnes;

        // Pass 1: Enforce palindrome symmetry and consume forced characters
        for (int i = 0; i < n / 2; i++) {
            int j = n - 1 - i;
            char left = chars[i];
            char right = chars[j];

            if (left == '?' && right == '?') {
                continue; // Both unknown, will be filled in Pass 2
            } else if (left == '?') {
                // Left must match right
                if (right == '0') remZeros--;
                else remOnes--;
                chars[i] = right;
            } else if (right == '?') {
                // Right must match left
                if (left == '0') remZeros--;
                else remOnes--;
                chars[j] = left;
            } else if (left != right) {
                return "-1"; // Hard conflict: cannot form palindrome
            }

            if (remZeros < 0 || remOnes < 0) {
                return "-1"; // Overused character type
            }
        }

        // Pass 2: Fill remaining '?' pairs
        for (int i = 0; i < n / 2; i++) {
            if (chars[i] == '?') { // chars[n-1-i] is also '?'
                if (remZeros >= 2) {
                    chars[i] = chars[n - 1 - i] = '0';
                    remZeros -= 2;
                } else if (remOnes >= 2) {
                    chars[i] = chars[n - 1 - i] = '1';
                    remOnes -= 2;
                } else {
                    return "-1"; // Not enough characters to fill pair
                }
            }
        }

        // Handle middle character for odd-length strings
        if (n % 2 == 1) {
            int mid = n / 2;
            if (chars[mid] == '?') {
                if (remZeros >= 1) {
                    chars[mid] = '0';
                    remZeros--;
                } else if (remOnes >= 1) {
                    chars[mid] = '1';
                    remOnes--;
                } else {
                    return "-1"; // Cannot fill middle character
                }
            }
        }

        return new String(chars);
    }

    /**
     * High-performance input reader for competitive programming.
     */
    static class FastReader {
        private final InputStream stream;
        private final byte[] buf = new byte[8192];
        private int curChar, numChars;

        public FastReader(InputStream stream) {
            this.stream = stream;
        }

        private int read() {
            if (numChars == -1) throw new InputMismatchException();
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0) return -1;
            }
            return buf[curChar++];
        }

        public int nextInt() {
            int c = read();
            while (isSpaceChar(c)) c = read();
            int sgn = 1;
            if (c == '-') { sgn = -1; c = read(); }
            int res = 0;
            do {
                if (c < '0' || c > '9') throw new InputMismatchException();
                res = res * 10 + (c - '0');
                c = read();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public String next() {
            int c = read();
            while (isSpaceChar(c)) c = read();
            StringBuilder res = new StringBuilder();
            do {
                res.appendCodePoint(c);
                c = read();
            } while (!isSpaceChar(c));
            return res.toString();
        }

        private boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayDeque;
import java.util.Queue;
import java.util.StringTokenizer;

public class B329 {
    // Direction vectors for Up, Down, Left, Right
    private static final int[] DX = {-1, 1, 0, 0};
    private static final int[] DY = {0, 0, -1, 1};

    private static final char WALL = 'T';
    private static final char START = 'S';
    private static final char END = 'E';

    public static void main(String[] args) throws IOException {
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(System.in))) {
            String line = reader.readLine();
            if (line == null) return;

            StringTokenizer st = new StringTokenizer(line);
            int n = Integer.parseInt(st.nextToken());
            int m = Integer.parseInt(st.nextToken());

            char[][] board = new char[n][m];
            int startX = -1, startY = -1;
            int endX = -1, endY = -1;

            for (int i = 0; i < n; i++) {
                String row = reader.readLine();
                for (int j = 0; j < m; j++) {
                    board[i][j] = row.charAt(j);
                    if (board[i][j] == START) {
                        startX = i;
                        startY = j;
                    } else if (board[i][j] == END) {
                        endX = i;
                        endY = j;
                    }
                }
            }

            int minDistance = bfsShortestPath(board, n, m, startX, startY, endX, endY);
            int totalValue = bfsCollectValues(board, n, m, endX, endY, minDistance);

            System.out.println(totalValue);
        }
    }

    /**
     * Finds the shortest path distance from START to END avoiding WALLs.
     */
    private static int bfsShortestPath(char[][] board, int n, int m,
                                       int startX, int startY, int endX, int endY) {
        boolean[][] visited = new boolean[n][m];
        Queue<State> queue = new ArrayDeque<>();

        queue.add(new State(startX, startY, 0));
        visited[startX][startY] = true;

        while (!queue.isEmpty()) {
            State current = queue.poll();

            if (current.x == endX && current.y == endY) {
                return current.level;
            }

            for (int i = 0; i < 4; i++) {
                int nx = current.x + DX[i];
                int ny = current.y + DY[i];

                if (isValidCell(nx, ny, n, m, board) && !visited[nx][ny]) {
                    visited[nx][ny] = true;
                    queue.add(new State(nx, ny, current.level + 1));
                }
            }
        }
        return -1; // No path found
    }

    /**
     * Calculates the sum of numeric values from END backwards within minDistance.
     * Avoids START, END, and WALL cells.
     */
    private static int bfsCollectValues(char[][] board, int n, int m,
                                        int startX, int startY, int maxDistance) {
        boolean[][] visited = new boolean[n][m];
        Queue<State> queue = new ArrayDeque<>();

        queue.add(new State(startX, startY, 0));
        visited[startX][startY] = true;

        int totalValue = 0;

        while (!queue.isEmpty()) {
            State current = queue.poll();

            // Add value if not the END cell
            if (board[current.x][current.y] != END) {
                totalValue += Character.getNumericValue(board[current.x][current.y]);
            }

            // Only expand if we haven't reached the max distance yet
            if (current.level < maxDistance) {
                for (int i = 0; i < 4; i++) {
                    int nx = current.x + DX[i];
                    int ny = current.y + DY[i];

                    if (isValidCollectionCell(nx, ny, n, m, board) && !visited[nx][ny]) {
                        visited[nx][ny] = true;
                        queue.add(new State(nx, ny, current.level + 1));
                    }
                }
            }
        }
        return totalValue;
    }

    private static boolean isValidCell(int x, int y, int n, int m, char[][] board) {
        return x >= 0 && x < n && y >= 0 && y < m && board[x][y] != WALL;
    }

    private static boolean isValidCollectionCell(int x, int y, int n, int m, char[][] board) {
        return x >= 0 && x < n && y >= 0 && y < m &&
               board[x][y] != WALL && board[x][y] != END && board[x][y] != START;
    }

    /**
     * Represents a coordinate and its distance from the starting point.
     */
    private static class State {
        final int x, y, level;

        State(int x, int y, int level) {
            this.x = x;
            this.y = y;
            this.level = level;
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.Queue;
import java.util.StringTokenizer;

/**
 * Solves the problem by performing a Breadth-First Search (BFS) from the exit ('E')
 * to compute the shortest distance to all reachable cells. It then determines
 * how many items ('0'-'9') are within the same or shorter distance than the start ('S').
 */
public class Round_192_D {

    /**
     * Utility class for fast input reading.
     */
    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner(InputStream in) {
            this.br = new BufferedReader(new InputStreamReader(in));
        }

        public String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input", e);
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            String s = next();
            if (s == null) throw new IllegalStateException("Unexpected end of input");
            return Integer.parseInt(s);
        }

        public long nextLong() {
            String s = next();
            if (s == null) throw new IllegalStateException("Unexpected end of input");
            return Long.parseLong(s);
        }

        public double nextDouble() {
            String s = next();
            if (s == null) throw new IllegalStateException("Unexpected end of input");
            return Double.parseDouble(s);
        }
    }

    /**
     * Represents a breeder/item found on the grid.
     */
    static class Breeder {
        final int distanceFromExit;
        final int quantity;

        Breeder(int distanceFromExit, int quantity) {
            this.distanceFromExit = distanceFromExit;
            this.quantity = quantity;
        }
    }

    public static void main(String[] args) {
        FastScanner sc = new FastScanner(System.in);
        int R = sc.nextInt();
        int C = sc.nextInt();

        char[][] grid = new char[R][C];
        int exitR = -1;
        int exitC = -1;

        // Read grid and locate the exit
        for (int r = 0; r < R; r++) {
            String line = sc.next();
            grid[r] = line.toCharArray();
            for (int c = 0; c < C; c++) {
                if (grid[r][c] == 'E') {
                    exitR = r;
                    exitC = c;
                }
            }
        }

        // Initialize distance matrix with -1 (unvisited)
        int[][] dist = new int[R][C];
        for (int[] row : dist) {
            Arrays.fill(row, -1);
        }
        dist[exitR][exitC] = 0;

        // BFS initialization
        Queue<int[]> queue = new ArrayDeque<>();
        queue.add(new int[]{exitR, exitC});

        int startDist = -1;
        List<Breeder> breeders = new ArrayList<>();

        // Direction vectors: Up, Down, Left, Right
        int[] dr = {-1, 1, 0, 0};
        int[] dc = {0, 0, -1, 1};

        while (!queue.isEmpty()) {
            int[] curr = queue.poll();
            int r = curr[0];
            int c = curr[1];
            int d = dist[r][c];
            char cell = grid[r][c];

            // Identify start position and collect breeders
            if (cell == 'S') {
                startDist = d;
            } else if (cell >= '0' && cell <= '9') {
                breeders.add(new Breeder(d, cell - '0'));
            }

            // Explore adjacent cells
            for (int i = 0; i < 4; i++) {
                int nr = r + dr[i];
                int nc = c + dc[i];

                // Check bounds, visited status, and obstacle
                if (nr >= 0 && nr < R && nc >= 0 && nc < C &&
                    dist[nr][nc] == -1 && grid[nr][nc] != 'T') {
                    dist[nr][nc] = d + 1;
                    queue.add(new int[]{nr, nc});
                }
            }
        }

        // Calculate the answer based on distances
        long ans = 0;
        for (Breeder b : breeders) {
            if (startDist != -1 && b.distanceFromExit <= startDist) {
                ans += b.quantity;
            }
        }

        System.out.println(ans);
    }
}

import java.util.ArrayDeque;
import java.util.Queue;
import java.util.Scanner;

public class Main {

    // Simple Point class to avoid dependency on java.awt.Point and improve encapsulation
    static class Point {
        int x, y;

        Point(int x, int y) {
            this.x = x;
            this.y = y;
        }
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        // Read grid dimensions
        if (!scanner.hasNextInt()) {
            return;
        }
        int rows = scanner.nextInt();
        int cols = scanner.nextInt();

        char[][] grid = new char[rows][cols];
        int[][] distances = new int[rows][cols];
        Point startPoint = null;

        // Read the grid and locate the starting point 'E'
        for (int i = 0; i < rows; i++) {
            String line = scanner.next();
            for (int j = 0; j < cols; j++) {
                grid[i][j] = line.charAt(j);
                if (grid[i][j] == 'E') {
                    startPoint = new Point(i, j);
                }
            }
        }

        // If no start point 'E' is found, output 0 and exit
        if (startPoint == null) {
            System.out.println(0);
            return;
        }

        // Use ArrayDeque as a Queue for BFS traversal.
        // The original code used LinkedList with mixed push/add/pop methods which effectively 
        // acted as a Queue (FIFO), but using standard Queue interface is clearer.
        Queue<Point> queue = new ArrayDeque<>();
        queue.add(startPoint);

        int trainers = 0;

        while (!queue.isEmpty()) {
            Point current = queue.poll();
            int r = current.x;
            int c = current.y;
            int currentDistance = distances[r][c];

            // Check if the current node is the target 'S'
            if (grid[r][c] == 'S') {
                // Process remaining nodes in the queue.
                // Logic: Sum trainers of nodes that are at a distance <= current distance.
                // This preserves the original behavior where the queue is drained 
                // based on distance criteria upon finding 'S'.
                while (!queue.isEmpty()) {
                    Point p = queue.poll();
                    if (distances[p.x][p.y] <= currentDistance) {
                        char cell = grid[p.x][p.y];
                        // Ensure we only process digits to avoid garbage values
                        if (Character.isDigit(cell)) {
                            trainers += cell - '0';
                        }
                    }
                }
                break;
            }

            // Count trainer at current node (if it's a digit and not 'E')
            // Original: if (grid[x][y] != 'E') trainers += grid[x][y]-'0';
            if (grid[r][c] != 'E') {
                char cell = grid[r][c];
                if (Character.isDigit(cell)) {
                    trainers += cell - '0';
                }
            }

            // Explore neighbors (Up, Down, Left, Right)
            int[] dr = {-1, 1, 0, 0};
            int[] dc = {0, 0, -1, 1};

            for (int k = 0; k < 4; k++) {
                int nr = r + dr[k];
                int nc = c + dc[k];

                // Check bounds
                if (nr >= 0 && nr < rows && nc >= 0 && nc < cols) {
                    char neighborChar = grid[nr][nc];

                    // Validation:
                    // 1. Not an obstacle 'T'
                    // 2. Not the start point 'E' (prevents cycles/backtracking)
                    // 3. Not visited yet (distance is 0)
                    if (neighborChar != 'T' && neighborChar != 'E' && distances[nr][nc] == 0) {
                        queue.add(new Point(nr, nc));
                        distances[nr][nc] = currentDistance + 1;
                    }
                }
            }
        }

        System.out.println(trainers);
        scanner.close();
    }
}

