class TaskB {
    // Constants to replace magic numbers
    private static final int WALL = -1;
    private static final int INFINITY = Integer.MAX_VALUE;

    // Direction vectors for BFS (Up, Down, Left, Right)
    private static final int[] DR = {-1, 1, 0, 0};
    private static final int[] DC = {0, 0, -1, 1};

    public void solve(FastReader in, PrintWriter out) {
        int rows = in.nextInt();
        int cols = in.nextInt();

        // Allocate grid with 1-based indexing and padded borders
        int[][] grid = new int[rows + 2][cols + 2];
        for (int[] row : grid) {
            Arrays.fill(row, WALL);
        }

        int startR = 0, startC = 0;
        int exitR = 0, exitC = 0;

        // Parse the grid and locate start/exit points
        for (int i = 1; i <= rows; i++) {
            String line = in.next();
            for (int j = 1; j <= cols; j++) {
                char ch = line.charAt(j - 1);
                if (ch == 'T') {
                    grid[i][j] = WALL;
                } else if (ch == 'S') {
                    startR = i;
                    startC = j;
                } else if (ch == 'E') {
                    exitR = i;
                    exitC = j;
                } else {
                    grid[i][j] = ch - '0';
                }
            }
        }

        // Find shortest distances from Exit to all reachable cells
        int[][] distances = bfs(grid, exitR, exitC);
        int shortestPathToStart = distances[startR][startC];

        // Calculate result based on cells within the shortest path distance
        long result = 0;
        for (int i = 1; i <= rows; i++) {
            for (int j = 1; j <= cols; j++) {
                if (grid[i][j] > 0 && distances[i][j] <= shortestPathToStart) {
                    result += grid[i][j];
                }
            }
        }

        out.println(result);
    }

    /**
     * Performs Breadth-First Search from the starting position to compute
     * the shortest distance to every reachable cell in the grid.
     */
    private int[][] bfs(int[][] grid, int startR, int startC) {
        int rows = grid.length;
        int cols = grid[0].length;
        int[][] dist = new int[rows][cols];

        // Initialize distances to infinity
        for (int[] row : dist) {
            Arrays.fill(row, INFINITY);
        }

        dist[startR][startC] = 0;
        Queue<Point> queue = new ArrayDeque<>();
        queue.add(new Point(startR, startC));

        while (!queue.isEmpty()) {
            Point curr = queue.poll();

            // Explore all 4 adjacent cells
            for (int k = 0; k < 4; k++) {
                int nextR = curr.r + DR[k];
                int nextC = curr.c + DC[k];

                // Check bounds, wall status, and if cell is unvisited
                if (grid[nextR][nextC] != WALL && dist[nextR][nextC] == INFINITY) {
                    dist[nextR][nextC] = dist[curr.r][curr.c] + 1;
                    queue.add(new Point(nextR, nextC));
                }
            }
        }
        return dist;
    }

    /**
     * Immutable record-like class to represent grid coordinates.
     * Made static to avoid implicit reference to outer class.
     */
    private static class Point {
        final int r;
        final int c;

        Point(int r, int c) {
            this.r = r;
            this.c = c;
        }
    }

    /**
     * Fast I/O helper to handle large input efficiently.
     */
    private static class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        public String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Input stream closed unexpectedly", e);
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            String token = next();
            return token == null ? 0 : Integer.parseInt(token);
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.Arrays;
import java.util.LinkedList;
import java.util.Queue;
import java.util.StringTokenizer;

public class Problem329B {
    private static final int INF = 1_000_000_007;
    private static final int[][] DIRECTIONS = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};

    public static void main(String[] args) throws IOException {
        FastScanner scanner = new FastScanner();
        PrintWriter out = new PrintWriter(System.out);

        int rows = scanner.nextInt();
        int cols = scanner.nextInt();

        char[][] grid = new char[rows][cols];
        int startX = -1, startY = -1;
        int endX = -1, endY = -1;

        for (int i = 0; i < rows; i++) {
            String line = scanner.next();
            for (int j = 0; j < cols; j++) {
                grid[i][j] = line.charAt(j);
                if (grid[i][j] == 'S') {
                    startX = i;
                    startY = j;
                } else if (grid[i][j] == 'E') {
                    endX = i;
                    endY = j;
                }
            }
        }

        int[][] dist = computeShortestPaths(grid, rows, cols, startX, startY);
        int endDist = dist[endX][endY];

        int totalValue = 0;
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] >= '0' && grid[i][j] <= '9' && dist[i][j] <= endDist) {
                    totalValue += grid[i][j] - '0';
                }
            }
        }

        out.println(totalValue);
        out.flush();
    }

    /**
     * Performs BFS to compute shortest distances from start to all reachable cells.
     */
    private static int[][] computeShortestPaths(char[][] grid, int rows, int cols, int startX, int startY) {
        int[][] dist = new int[rows][cols];
        for (int[] row : dist) {
            Arrays.fill(row, INF);
        }

        dist[startX][startY] = 0;
        Queue<Point> queue = new LinkedList<>();
        queue.offer(new Point(startX, startY));

        while (!queue.isEmpty()) {
            Point current = queue.poll();
            int r = current.r;
            int c = current.c;
            int d = dist[r][c];

            for (int[] dir : DIRECTIONS) {
                int nr = r + dir[0];
                int nc = c + dir[1];

                if (nr >= 0 && nr < rows && nc >= 0 && nc < cols &&
                    grid[nr][nc] != 'T' && dist[nr][nc] == INF) {
                    dist[nr][nc] = d + 1;
                    queue.offer(new Point(nr, nc));
                }
            }
        }
        return dist;
    }

    /**
     * Lightweight coordinate class for BFS traversal.
     */
    private static class Point {
        final int r, c;
        Point(int r, int c) {
            this.r = r;
            this.c = c;
        }
    }

    /**
     * Standard fast I/O helper for competitive programming.
     */
    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) throw new IOException("End of input");
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.OutputStream;
import java.io.PrintWriter;
import java.util.Arrays;
import java.util.Comparator;
import java.util.PriorityQueue;
import java.util.StringTokenizer;

public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        BiridianForest solver = new BiridianForest();
        solver.solve(in, out);
        out.close();
    }

    static class BiridianForest {
        private static final int[] DR = {-1, 1, 0, 0};
        private static final int[] DC = {0, 0, -1, 1};

        public void solve(InputReader in, PrintWriter out) {
            int rows = in.nextInt();
            int cols = in.nextInt();
            int[][] grid = new int[rows][cols];
            int startRow = -1, startCol = -1, endRow = -1, endCol = -1;

            for (int i = 0; i < rows; i++) {
                String line = in.next();
                for (int j = 0; j < cols; j++) {
                    char c = line.charAt(j);
                    if (c == 'T') {
                        grid[i][j] = -1; // Obstacle
                    } else if (c == 'S') {
                        startRow = i;
                        startCol = j;
                    } else if (c == 'E') {
                        endRow = i;
                        endCol = j;
                    } else {
                        grid[i][j] = Character.getNumericValue(c);
                    }
                }
            }

            int[][] minDist = new int[rows][cols];
            for (int[] row : minDist) {
                Arrays.fill(row, Integer.MAX_VALUE);
            }
            minDist[endRow][endCol] = 0;

            PriorityQueue<Path> pq = new PriorityQueue<>(Comparator.comparingInt(p -> p.dist));
            pq.offer(new Path(endRow, endCol, 0));

            while (!pq.isEmpty()) {
                Path current = pq.poll();

                for (int d = 0; d < 4; d++) {
                    int r = current.r + DR[d];
                    int c = current.c + DC[d];

                    if (isValid(r, c, rows, cols) && grid[r][c] != -1 && current.dist + 1 < minDist[r][c]) {
                        minDist[r][c] = current.dist + 1;
                        pq.offer(new Path(r, c, minDist[r][c]));
                    }
                }
            }

            int shortestDistToStart = minDist[startRow][startCol];
            int totalCost = 0;

            // Guard against unreachable start position
            if (shortestDistToStart == Integer.MAX_VALUE) {
                out.println(0);
                return;
            }

            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j] != -1 && minDist[i][j] <= shortestDistToStart) {
                        totalCost += grid[i][j];
                    }
                }
            }

            out.println(totalCost);
        }

        private boolean isValid(int r, int c, int rows, int cols) {
            return r >= 0 && c >= 0 && r < rows && c < cols;
        }

        static class Path {
            final int r, c, dist;

            Path(int r, int c, int dist) {
                this.r = r;
                this.c = c;
                this.dist = dist;
            }
        }
    }

    static class InputReader {
        public BufferedReader reader;
        public StringTokenizer tokenizer;

        public InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            String s = next();
            if (s == null) throw new RuntimeException("Unexpected end of input");
            return Integer.parseInt(s);
        }
    }
}

import java.io.*;
import java.util.*;

public class GridPathSolver {
    public static void main(String[] args) throws IOException {
        // Use buffered output for improved performance
        PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out));
        FastScanner scanner = new FastScanner(System.in);

        int n = scanner.nextInt();
        int m = scanner.nextInt();

        char[][] grid = new char[n][m];
        int startRow = 0, startCol = 0;
        int endRow = 0, endCol = 0;

        // Read grid and locate start/end positions
        for (int i = 0; i < n; i++) {
            String row = scanner.next();
            for (int j = 0; j < m; j++) {
                grid[i][j] = row.charAt(j);
                if (grid[i][j] == 'S') {
                    startRow = i;
                    startCol = j;
                } else if (grid[i][j] == 'E') {
                    endRow = i;
                    endCol = j;
                }
            }
        }

        // Initialize distances with -1 (unvisited)
        int[][] distances = new int[n][m];
        for (int[] row : distances) {
            Arrays.fill(row, -1);
        }

        // BFS initialization from 'E'
        distances[endRow][endCol] = 0;
        Queue<Point> queue = new ArrayDeque<>();
        queue.add(new Point(endRow, endCol));

        // Direction vectors: Up, Down, Left, Right
        int[] dr = {-1, 1, 0, 0};
        int[] dc = {0, 0, -1, 1};

        // Standard BFS to compute shortest path distances from 'E'
        while (!queue.isEmpty()) {
            Point current = queue.poll();
            for (int k = 0; k < 4; k++) {
                int nr = current.r + dr[k];
                int nc = current.c + dc[k];

                // Boundary check
                if (nr < 0 || nr >= n || nc < 0 || nc >= m) continue;
                // Skip visited cells and obstacles
                if (distances[nr][nc] != -1 || grid[nr][nc] == 'T') continue;

                distances[nr][nc] = distances[current.r][current.c] + 1;
                queue.add(new Point(nr, nc));
            }
        }

        // Calculate total sum of digits within the distance threshold
        int movesToStart = distances[startRow][startCol];
        long totalDigitSum = 0;

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (distances[i][j] != -1 && 
                    distances[i][j] <= movesToStart && 
                    grid[i][j] >= '0' && grid[i][j] <= '9') {
                    totalDigitSum += grid[i][j] - '0';
                }
            }
        }

        out.println(totalDigitSum);
        out.flush();
    }

    // Simple immutable class to hold 2D coordinates
    private static class Point {
        final int r, c;
        Point(int r, int c) { this.r = r; this.c = c; }
    }

    // Fast I/O helper class
    private static class FastScanner {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastScanner(InputStream stream) {
            this.reader = new BufferedReader(new InputStreamReader(stream));
            this.tokenizer = new StringTokenizer("");
        }

        String next() throws IOException {
            while (!tokenizer.hasMoreTokens()) {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        int nextInt() throws IOException {
            String s = next();
            return s == null ? 0 : Integer.parseInt(s);
        }
    }
}

import java.io.*;
import java.util.*;

public class ProblemA {

    /**
     * Lightweight, immutable coordinate class for grid traversal.
     * Replaces java.awt.Point to reduce dependencies and improve performance.
     */
    private static class Coord {
        final int r, c;
        Coord(int r, int c) {
            this.r = r;
            this.c = c;
        }
    }

    /**
     * Solves the problem for a single test case.
     * Performs BFS from the Exit ('E') to compute shortest distances to all reachable cells.
     * Then sums battle points ('0'-'9') on cells within the path distance from Start ('S').
     */
    public static void solve(InputReader in, PrintWriter out, DebugWriter debug) throws IOException {
        int rows = in.nextInt();
        int cols = in.nextInt();

        char[][] grid = new char[rows][cols];
        int[][] distances = new int[rows][cols];
        for (int[] row : distances) {
            Arrays.fill(row, -1);
        }

        Coord start = null;
        Coord end = null;

        // Parse grid and locate start/end points
        for (int i = 0; i < rows; i++) {
            String line = in.next();
            for (int j = 0; j < cols; j++) {
                char cell = line.charAt(j);
                grid[i][j] = cell;

                if (cell == 'T') {
                    distances[i][j] = -2; // Obstacle/Wall
                } else if (cell == 'E') {
                    end = new Coord(i, j);
                } else if (cell == 'S') {
                    start = new Coord(i, j);
                }
            }
        }

        // Safety check for missing start or exit
        if (start == null || end == null) {
            out.println(0);
            return;
        }

        // BFS from Exit to calculate distances to all reachable cells
        distances[end.r][end.c] = 0;
        Queue<Coord> queue = new ArrayDeque<>();
        queue.add(end);

        int[] dr = {-1, 1, 0, 0};
        int[] dc = {0, 0, -1, 1};

        while (!queue.isEmpty()) {
            Coord curr = queue.poll();
            int currentDist = distances[curr.r][curr.c];

            for (int d = 0; d < 4; d++) {
                int nr = curr.r + dr[d];
                int nc = curr.c + dc[d];

                if (nr >= 0 && nr < rows && nc >= 0 && nc < cols && distances[nr][nc] == -1) {
                    distances[nr][nc] = currentDist + 1;
                    queue.add(new Coord(nr, nc));
                }
            }
        }

        // Debug: Print distance matrix
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                debug.print(distances[i][j] >= 0 ? distances[i][j] : "* ");
            }
            debug.println();
        }

        int distanceToExit = distances[start.r][start.c];
        debug.println("Distance to Exit: " + distanceToExit);

        // Count battle points within the path distance
        int battleCount = 0;
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                int dist = distances[i][j];
                if (dist >= 0 && dist <= distanceToExit) {
                    char cell = grid[i][j];
                    if (cell >= '0' && cell <= '9') {
                        battleCount += cell - '0';
                    }
                }
            }
        }

        out.println(battleCount);
    }

    public static void main(String[] args) throws IOException {
        InputReader in;
        PrintWriter out;
        DebugWriter debug;

        if (args.length > 0 && args[0].equals("file")) {
            in = new InputReader(new BufferedReader(new FileReader("input.txt")));
            out = new PrintWriter(new FileWriter("output.txt"));
            debug = new DebugWriter(true);

            int sampleNumber = 1;
            while (true) {
                String nextSample = "Sample #" + sampleNumber++ + ": ";
                out.println(nextSample);
                debug.println(nextSample);

                try {
                    solve(in, out, debug);
                } catch (IOException e) {
                    break; // End of input or parsing error
                }

                out.println();
                debug.println();
            }
        } else {
            in = new InputReader(new BufferedReader(new InputStreamReader(System.in)));
            out = new PrintWriter(new OutputStreamWriter(System.out));
            debug = new DebugWriter(false);
            solve(in, out, debug);
        }

        in.close();
        out.close();
    }

    /**
     * Fast I/O helper for competitive programming style inputs.
     */
    public static class InputReader {
        public BufferedReader reader;
        public StringTokenizer tokenizer;

        public InputReader(BufferedReader reader) {
            this.reader = reader;
            tokenizer = null;
        }

        public String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            String s = next();
            if (s == null) throw new EOFException("Unexpected end of input");
            return Integer.parseInt(s);
        }

        public int[] nextIntArray(int n) throws IOException {
            int[] array = new int[n];
            for (int i = 0; i < n; i++) {
                array[i] = nextInt();
            }
            return array;
        }

        public void close() throws IOException {
            reader.close();
        }
    }

    /**
     * Conditional debug output writer.
     */
    public static class DebugWriter {
        public boolean enable;

        public DebugWriter(boolean enable) {
            this.enable = enable;
        }

        public void print(Object o) {
            if (enable) System.out.print(o);
        }

        public void println(Object o) {
            if (enable) System.out.println(o);
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.ArrayDeque;
import java.util.Arrays;
import java.util.Queue;
import java.util.StringTokenizer;

/**
 * Solves a grid path problem by computing shortest distances from the endpoint
 * and summing digits at reachable cells within the shortest path length.
 * 
 * Refactoring highlights:
 * - Separated concerns: input parsing, BFS traversal, and result calculation are isolated methods.
 * - Replaced flattened coordinates with a dedicated Point class for readability.
 * - Converted String[] map to char[][] grid for O(1) character access and better performance.
 * - Replaced LinkedList with ArrayDeque (recommended for queue implementations in Java).
 * - Removed unused code (mod constant, endLine method, unnecessary exception declarations).
 * - Extracted magic numbers and direction vectors into named constants.
 * - Added comprehensive JavaDoc, comments, and input validation.
 * - Improved I/O handling with a robust FastScanner and proper resource flushing.
 */
public class GridPathSolver {

    // Direction vectors for moving right, down, left, up
    private static final int[] DR = {0, 1, 0, -1};
    private static final int[] DC = {1, 0, -1, 0};

    private static final char START_CHAR = 'S';
    private static final char END_CHAR = 'E';
    private static final char OBSTACLE_CHAR = 'T';
    private static final char DIGIT_START = '0';
    private static final char DIGIT_END = '9';

    /** Represents a coordinate in the grid */
    private static class Point {
        final int row, col;
        Point(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner();
        PrintWriter out = new PrintWriter(System.out);

        try {
            int rows = scanner.nextInt();
            int cols = scanner.nextInt();

            char[][] grid = new char[rows][cols];
            Point startPoint = null;
            Point endPoint = null;

            // Parse the grid and locate start/end points
            for (int i = 0; i < rows; i++) {
                String line = scanner.next();
                grid[i] = line.toCharArray();
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j] == START_CHAR) {
                        startPoint = new Point(i, j);
                    } else if (grid[i][j] == END_CHAR) {
                        endPoint = new Point(i, j);
                    }
                }
            }

            // Validate that required points exist
            if (startPoint == null || endPoint == null) {
                out.println(0);
                out.flush();
                return;
            }

            // Compute shortest distances from the endpoint to all reachable cells
            int[][] distances = computeShortestDistances(grid, rows, cols, endPoint);

            // Calculate the result based on distances and grid values
            int result = calculateResult(grid, rows, cols, startPoint, endPoint, distances);
            out.println(result);

        } catch (Exception e) {
            // In production, log this exception. For algorithmic problems, output 0 gracefully.
            out.println(0);
        } finally {
            out.flush();
        }
    }

    /**
     * Performs BFS from the given start point to compute shortest distances
     * to all reachable cells, avoiding obstacles.
     */
    private static int[][] computeShortestDistances(char[][] grid, int rows, int cols, Point start) {
        int[][] distances = new int[rows][cols];
        for (int[] row : distances) {
            Arrays.fill(row, -1);
        }

        Queue<Point> queue = new ArrayDeque<>();
        queue.add(start);
        distances[start.row][start.col] = 0;

        while (!queue.isEmpty()) {
            Point current = queue.poll();
            int currentDist = distances[current.row][current.col];

            for (int i = 0; i < 4; i++) {
                int nextRow = current.row + DR[i];
                int nextCol = current.col + DC[i];

                if (isValidCell(nextRow, nextCol, rows, cols) &&
                    grid[nextRow][nextCol] != OBSTACLE_CHAR &&
                    distances[nextRow][nextCol] == -1) {

                    distances[nextRow][nextCol] = currentDist + 1;
                    queue.add(new Point(nextRow, nextCol));
                }
            }
        }
        return distances;
    }

    /**
     * Calculates the sum of digits at valid cells that are reachable
     * and within the shortest path distance from start to end.
     */
    private static int calculateResult(char[][] grid, int rows, int cols, Point start, Point end, int[][] distances) {
        int shortestPathLength = distances[start.row][start.col];

        // If start is unreachable from end, no valid cells can satisfy the condition
        if (shortestPathLength == -1) {
            return 0;
        }

        int result = 0;
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                // Skip start and end positions as per original logic
                if ((r == start.row && c == start.col) || (r == end.row && c == end.col)) {
                    continue;
                }

                int dist = distances[r][c];
                char cell = grid[r][c];

                // Check if reachable, within distance limit, and contains a digit
                if (dist != -1 && dist <= shortestPathLength && cell >= DIGIT_START && cell <= DIGIT_END) {
                    result += cell - DIGIT_START;
                }
            }
        }
        return result;
    }

    private static boolean isValidCell(int row, int col, int rows, int cols) {
        return row >= 0 && row < rows && col >= 0 && col < cols;
    }

    /**
     * Fast I/O helper class optimized for competitive programming and large inputs.
     */
    private static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            String token = next();
            if (token == null) throw new RuntimeException("Unexpected end of input");
            return Integer.parseInt(token);
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.Arrays;
import java.util.LinkedList;
import java.util.Queue;
import java.util.StringTokenizer;

/**
 * Refactored solution for the grid pathfinding problem.
 * 
 * Improvements made:
 * 1. Removed unnecessary 'Runnable' interface implementation.
 * 2. Replaced 'Queue<Integer>' with 'Queue<int[]>' for cleaner coordinate handling.
 * 3. Extracted direction vectors to constants for readability.
 * 4. Improved variable naming (e.g., 'R' -> 'rows', 'd' -> 'distances').
 * 5. Consolidated grid reading and coordinate finding into a single pass.
 * 6. Fixed potential NullPointerException in input reading (EOF handling).
 * 7. Used 'ArrayDeque' instead of 'LinkedList' for better performance.
 * 8. Removed excessive whitespace and organized code structure.
 */
public class Main {

    // Directions: Down, Up, Right, Left
    private static final int[] DR = {1, -1, 0, 0};
    private static final int[] DC = {0, 0, 1, -1};

    private BufferedReader in;
    private StringTokenizer tok;

    public static void main(String[] args) {
        new Main().solve();
    }

    public void solve() {
        try {
            in = new BufferedReader(new InputStreamReader(System.in));
            tok = null;

            int rows = nextInt();
            int cols = nextInt();

            char[][] grid = new char[rows][cols];
            int startR = -1, startC = -1;
            int exitR = -1, exitC = -1;

            // Read grid and locate Start ('S') and Exit ('E')
            for (int i = 0; i < rows; i++) {
                String line = nextToken();
                grid[i] = line.toCharArray();
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j] == 'S') {
                        startR = i;
                        startC = j;
                    } else if (grid[i][j] == 'E' && exitR == -1) {
                        // Find the first Exit encountered (mimicking original break logic)
                        exitR = i;
                        exitC = j;
                    }
                }
            }

            // Initialize distances with -1 (unreachable)
            int[][] distances = new int[rows][cols];
            for (int[] row : distances) {
                Arrays.fill(row, -1);
            }

            Queue<int[]> queue = new LinkedList<>();

            // Start BFS from Exit
            if (exitR != -1) {
                distances[exitR][exitC] = 0;
                queue.add(new int[]{exitR, exitC});
            }

            while (!queue.isEmpty()) {
                int[] current = queue.poll();
                int r = current[0];
                int c = current[1];

                for (int k = 0; k < 4; k++) {
                    int nr = r + DR[k];
                    int nc = c + DC[k];

                    if (isValid(nr, nc, rows, cols) && grid[nr][nc] != 'T' && distances[nr][nc] == -1) {
                        distances[nr][nc] = distances[r][c] + 1;
                        queue.add(new int[]{nr, nc});
                    }
                }
            }

            // Determine distance from Exit to Start
            int ourDistance = (startR != -1) ? distances[startR][startC] : -1;
            int ans = 0;

            // Calculate answer based on enemy positions
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    char cell = grid[i][j];
                    // Check if cell is an enemy (digit) and not a special tile
                    if (cell != 'T' && cell != 'E' && cell != 'S' && Character.isDigit(cell)) {
                        int enemyValue = cell - '0';

                        // If enemy is reachable and closer/equal to start relative to exit
                        if (distances[i][j] != -1 && distances[i][j] <= ourDistance) {
                            ans += enemyValue;
                        }
                    }
                }
            }

            System.out.println(ans);

        } catch (IOException e) {
            // In a real application, log the error. 
            // For CP, we can just exit or ignore.
            e.printStackTrace();
        } finally {
            if (in != null) {
                try {
                    in.close();
                } catch (IOException e) {
                    // Ignore close exception
                }
            }
        }
    }

    private boolean isValid(int r, int c, int rows, int cols) {
        return r >= 0 && c >= 0 && r < rows && c < cols;
    }

    /**
     * Fast input reader helper
     */
    public String nextToken() throws IOException {
        while (tok == null || !tok.hasMoreTokens()) {
            String line = in.readLine();
            if (line == null) return null;
            tok = new StringTokenizer(line);
        }
        return tok.nextToken();
    }

    public int nextInt() throws IOException {
        String token = nextToken();
        if (token == null) throw new IOException("Unexpected end of input");
        return Integer.parseInt(token);
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.ArrayDeque;
import java.util.Arrays;
import java.util.Queue;
import java.util.StringTokenizer;

public class GridPathSolver {
    private static final int[][] DIRECTIONS = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};
    private static final int INFINITY = Integer.MAX_VALUE;

    public static void main(String[] args) {
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
             PrintWriter out = new PrintWriter(System.out)) {
            new GridPathSolver().solve(reader, out);
        } catch (IOException e) {
            throw new RuntimeException("Failed to process input/output", e);
        }
    }

    void solve(BufferedReader reader, PrintWriter out) throws IOException {
        FastScanner sc = new FastScanner(reader);
        int n = sc.nextInt();
        int m = sc.nextInt();

        int[][] grid = new int[n][m];
        int endX = 0, endY = 0;
        int startX = 0, startY = 0;

        for (int i = 0; i < n; i++) {
            String line = sc.next();
            for (int j = 0; j < m; j++) {
                char c = line.charAt(j);
                switch (c) {
                    case 'T':
                        grid[i][j] = -1; // Obstacle
                        break;
                    case 'S':
                        grid[i][j] = 11; // Start marker (problem-specific encoding)
                        startX = i;
                        startY = j;
                        break;
                    case 'E':
                        grid[i][j] = 0;  // End marker
                        endX = i;
                        endY = j;
                        break;
                    default:
                        grid[i][j] = c - '0'; // Numeric cell value
                        break;
                }
            }
        }

        // Compute shortest distances from the 'E' (Exit) point to all reachable cells
        int[][] distances = bfs(endX, endY, grid, n, m);
        int distanceToStart = distances[startX][startY];

        int totalValue = 0;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                int cellValue = grid[i][j];
                // Sum values of numeric cells that are reachable and on or before the path to 'S'
                if (cellValue > 0 && cellValue < 10 &&
                    distances[i][j] != INFINITY &&
                    distances[i][j] <= distanceToStart) {
                    totalValue += cellValue;
                }
            }
        }

        out.println(totalValue);
    }

    /**
     * Performs BFS from the start point to calculate shortest distances to all other cells.
     * Returns a 2D array where each cell contains the minimum steps from the start point,
     * or INFINITY if unreachable.
     */
    private int[][] bfs(int startX, int startY, int[][] grid, int n, int m) {
        int[][] dist = new int[n][m];
        for (int[] row : dist) {
            Arrays.fill(row, INFINITY);
        }

        Queue<Integer> queue = new ArrayDeque<>();
        dist[startX][startY] = 0;
        queue.add(encode(startX, startY, m));

        while (!queue.isEmpty()) {
            int pos = queue.poll();
            int x = pos / m;
            int y = pos % m;
            int currentDist = dist[x][y];

            for (int[] dir : DIRECTIONS) {
                int nx = x + dir[0];
                int ny = y + dir[1];

                if (isValid(nx, ny, n, m) && grid[nx][ny] != -1 && dist[nx][ny] == INFINITY) {
                    dist[nx][ny] = currentDist + 1;
                    queue.add(encode(nx, ny, m));
                }
            }
        }
        return dist;
    }

    private boolean isValid(int x, int y, int n, int m) {
        return x >= 0 && x < n && y >= 0 && y < m;
    }

    /**
     * Encodes 2D coordinates into a single integer to store in a 1D queue.
     * Assumes n * m fits within Integer.MAX_VALUE.
     */
    private int encode(int x, int y, int m) {
        return x * m + y;
    }

    /**
     * Helper class for fast token-based input reading.
     */
    private static class FastScanner {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        FastScanner(BufferedReader reader) {
            this.reader = reader;
        }

        String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        int nextInt() throws IOException {
            String token = next();
            if (token == null) throw new IOException("Unexpected end of input");
            return Integer.parseInt(token);
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayDeque;
import java.util.Queue;
import java.util.StringTokenizer;

/**
 * Solves a grid-based pathfinding problem.
 * 1. Finds the shortest path from 'S' to 'E' using BFS.
 * 2. Calculates the sum of all digits reachable within that shortest distance from 'E'.
 */
public class GridPathSolver {

    private static final int[][] DIRECTIONS = {{0, 1}, {0, -1}, {1, 0}, {-1, 0}};

    /**
     * Represents a cell in the grid along with the distance from the starting point.
     */
    private static class CellState implements Comparable<CellState> {
        final int row, col, dist;

        CellState(int row, int col, int dist) {
            this.row = row;
            this.col = col;
            this.dist = dist;
        }

        @Override
        public int compareTo(CellState other) {
            return Integer.compare(this.dist, other.dist);
        }
    }

    /**
     * Fast I/O helper for competitive programming style inputs.
     */
    private static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input", e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            String token = next();
            return token == null ? 0 : Integer.parseInt(token);
        }
    }

    /**
     * Checks if a cell is within bounds, not a wall ('T'), and unvisited.
     */
    private boolean isValid(int r, int c, int rows, int cols, char[][] grid, boolean[][] visited) {
        return r >= 0 && r < rows && c >= 0 && c < cols &&
               grid[r][c] != 'T' && !visited[r][c];
    }

    /**
     * Finds the shortest distance from start to end using BFS.
     * (BFS is preferred over Dijkstra here since all edge weights are uniformly 1,
     * reducing time complexity from O(E log V) to O(V + E))
     */
    private int findShortestPath(int rows, int cols, char[][] grid, int startRow, int startCol, int endRow, int endCol) {
        boolean[][] visited = new boolean[rows][cols];
        Queue<CellState> queue = new ArrayDeque<>();

        queue.offer(new CellState(startRow, startCol, 0));
        visited[startRow][startCol] = true;

        while (!queue.isEmpty()) {
            CellState current = queue.poll();

            if (current.row == endRow && current.col == endCol) {
                return current.dist;
            }

            for (int[] dir : DIRECTIONS) {
                int newRow = current.row + dir[0];
                int newCol = current.col + dir[1];

                if (isValid(newRow, newCol, rows, cols, grid, visited)) {
                    visited[newRow][newCol] = true;
                    queue.offer(new CellState(newRow, newCol, current.dist + 1));
                }
            }
        }
        return -1; // End is unreachable
    }

    /**
     * Performs BFS from the endpoint to sum all digits reachable within maxDist steps.
     */
    private int sumDigitsInRange(int rows, int cols, char[][] grid, int endRow, int endCol, int maxDist) {
        boolean[][] visited = new boolean[rows][cols];
        Queue<CellState> queue = new ArrayDeque<>();

        queue.offer(new CellState(endRow, endCol, 0));
        visited[endRow][endCol] = true;
        int sum = 0;

        while (!queue.isEmpty()) {
            CellState current = queue.poll();

            // Sum digit if the cell contains one
            if (Character.isDigit(grid[current.row][current.col])) {
                sum += grid[current.row][current.col] - '0';
            }

            // Stop expanding if we've reached the maximum allowed distance
            if (current.dist == maxDist) {
                continue;
            }

            for (int[] dir : DIRECTIONS) {
                int newRow = current.row + dir[0];
                int newCol = current.col + dir[1];

                if (isValid(newRow, newCol, rows, cols, grid, visited)) {
                    visited[newRow][newCol] = true;
                    queue.offer(new CellState(newRow, newCol, current.dist + 1));
                }
            }
        }
        return sum;
    }

    /**
     * Main solver method. Reads input, computes path, and prints result.
     */
    public int solve() {
        FastScanner scanner = new FastScanner();

        String rStr = scanner.next();
        if (rStr == null) return 0;

        int rows = Integer.parseInt(rStr);
        int cols = scanner.nextInt();

        char[][] grid = new char[rows][cols];
        int startRow = -1, startCol = -1;
        int endRow = -1, endCol = -1;

        for (int i = 0; i < rows; i++) {
            String line = scanner.next();
            if (line != null) {
                grid[i] = line.toCharArray();
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j] == 'S') {
                        startRow = i;
                        startCol = j;
                    } else if (grid[i][j] == 'E') {
                        endRow = i;
                        endCol = j;
                    }
                }
            }
        }

        // Step 1: Find shortest path from S to E
        int shortestDist = findShortestPath(rows, cols, grid, startRow, startCol, endRow, endCol);

        // If destination is unreachable, output 0
        if (shortestDist == -1) {
            System.out.println(0);
            return 0;
        }

        // Step 2: Sum digits reachable from E within the shortest distance
        int result = sumDigitsInRange(rows, cols, grid, endRow, endCol, shortestDist);
        System.out.println(result);
        return result;
    }

    public static void main(String[] args) {
        new GridPathSolver().solve();
    }
}

import java.io.*;
import java.util.*;

public class ProblemB {

    /**
     * FastScanner provides efficient token-based input reading.
     * Replaces inefficient String.split() with StringTokenizer for competitive programming scenarios.
     */
    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        public String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input", e);
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            String s = next();
            return s == null ? 0 : Integer.parseInt(s);
        }

        public long nextLong() {
            String s = next();
            return s == null ? 0L : Long.parseLong(s);
        }
    }

    /**
     * Immutable value class representing grid coordinates.
     */
    static class Pair {
        final int r, c;

        Pair(int r, int c) {
            this.r = r;
            this.c = c;
        }
    }

    public static void main(String[] args) {
        FastScanner sc = new FastScanner(System.in);
        // BufferedOutputStream improves PrintWriter performance
        PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out));
        try {
            new ProblemB().run(sc, out);
        } finally {
            out.flush();
        }
    }

    /**
     * Orchestrates reading the number of test cases and dispatching to solve().
     */
    void run(FastScanner sc, PrintWriter out) {
        String tStr = sc.next();
        if (tStr == null) return;
        int t = Integer.parseInt(tStr);
        for (int i = 0; i < t; i++) {
            if (i > 0) out.println();
            solve(sc, out);
        }
    }

    /**
     * Solves a single test case using multi-source BFS.
     */
    void solve(FastScanner sc, PrintWriter out) {
        int m = sc.nextInt();
        int n = sc.nextInt();
        char[][] grid = new char[m][];
        int[][] dist = new int[m][n];
        int startR = 0, startC = 0;
        Queue<Pair> queue = new ArrayDeque<>();
        final int INF = Integer.MAX_VALUE;

        // Read grid and initialize BFS sources
        for (int i = 0; i < m; i++) {
            String row = sc.next();
            grid[i] = row.toCharArray();
            Arrays.fill(dist[i], INF);
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 'E') {
                    queue.add(new Pair(i, j));
                    dist[i][j] = 0;
                } else if (grid[i][j] == 'S') {
                    startR = i;
                    startC = j;
                }
            }
        }

        // Direction vectors: up, down, left, right
        int[] dr = {-1, 1, 0, 0};
        int[] dc = {0, 0, -1, 1};

        // Multi-source BFS from all 'E' positions
        while (!queue.isEmpty()) {
            Pair curr = queue.poll();
            for (int k = 0; k < 4; k++) {
                int r = curr.r + dr[k];
                int c = curr.c + dc[k];

                // Boundary check, obstacle check, and unvisited check
                if (r >= 0 && r < m && c >= 0 && c < n && grid[r][c] != 'T' && dist[r][c] == INF) {
                    dist[r][c] = dist[curr.r][curr.c] + 1;
                    queue.add(new Pair(r, c));
                }
            }
        }

        int sDist = dist[startR][startC];
        int ans = 0;
        for (int r = 0; r < m; r++) {
            for (int c = 0; c < n; c++) {
                char ch = grid[r][c];
                // Sum digits that are reachable within the distance from 'S' to 'E'
                if (ch > '0' && ch <= '9' && dist[r][c] <= sDist) {
                    ans += ch - '0';
                }
            }
        }
        out.println(ans);
    }
}

import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.ArrayDeque;
import java.util.Arrays;
import java.util.InputMismatchException;
import java.util.Queue;

public class MazeSolver {

    private static final int OBSTACLE = -1;
    private static final int EMPTY = 0;
    private static final int UNVISITED = Integer.MAX_VALUE;

    public static void main(String[] args) {
        // Use try-with-resources for automatic resource management
        try (InputReader in = new InputReader(System.in);
             PrintWriter out = new PrintWriter(System.out)) {
            new MazeSolver().solve(in, out);
        }
        out.flush();
    }

    void solve(InputReader in, PrintWriter out) {
        int rows = in.nextInt();
        int cols = in.nextInt();
        int[][] grid = new int[rows][cols];

        GridData gridData = parseGrid(in, rows, cols, grid);
        if (gridData.start == null || gridData.end == null) {
            out.println(0);
            return;
        }

        // BFS from the end point to compute distances to all reachable cells
        int[][] distances = computeDistances(grid, rows, cols, gridData.end);

        // Calculate score based on reachability from start
        int score = calculateScore(grid, rows, cols, distances, gridData.start);

        out.println(score);
    }

    /**
     * Parses the input grid and identifies start, end, obstacles, and numeric values.
     */
    private static GridData parseGrid(InputReader in, int rows, int cols, int[][] grid) {
        Coordinates start = null;
        Coordinates end = null;

        for (int r = 0; r < rows; r++) {
            String line = in.nextToken();
            for (int c = 0; c < cols; c++) {
                char ch = line.charAt(c);
                if (Character.isDigit(ch)) {
                    grid[r][c] = ch - '0';
                } else if (ch == 'T') {
                    grid[r][c] = OBSTACLE;
                } else if (ch == 'E') {
                    end = new Coordinates(r, c);
                    grid[r][c] = EMPTY;
                } else {
                    start = new Coordinates(r, c);
                    grid[r][c] = EMPTY;
                }
            }
        }
        return new GridData(start, end);
    }

    /**
     * Performs BFS from a source coordinate to compute shortest distances to all reachable cells.
     */
    private static int[][] computeDistances(int[][] grid, int rows, int cols, Coordinates source) {
        int[][] distances = new int[rows][cols];
        for (int[] row : distances) {
            Arrays.fill(row, UNVISITED);
        }
        distances[source.row][source.col] = 0;

        Queue<Coordinates> queue = new ArrayDeque<>();
        queue.add(source);

        int[][] directions = {{0, 1}, {0, -1}, {1, 0}, {-1, 0}};

        while (!queue.isEmpty()) {
            Coordinates curr = queue.poll();
            for (int[] dir : directions) {
                int nr = curr.row + dir[0];
                int nc = curr.col + dir[1];

                // Replaced redundant 'visit' array with distance check
                if (isValid(nr, nc, rows, cols) && distances[nr][nc] == UNVISITED && grid[nr][nc] != OBSTACLE) {
                    distances[nr][nc] = distances[curr.row][curr.col] + 1;
                    queue.add(new Coordinates(nr, nc));
                }
            }
        }
        return distances;
    }

    /**
     * Sums numeric values on cells that are reachable from start and within the max reachable distance.
     */
    private static int calculateScore(int[][] grid, int rows, int cols, int[][] distances, Coordinates start) {
        int maxReachableDist = distances[start.row][start.col];
        int score = 0;

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] > 0 && distances[r][c] != UNVISITED && maxReachableDist >= distances[r][c]) {
                    score += grid[r][c];
                }
            }
        }
        return score;
    }

    private static boolean isValid(int r, int c, int rows, int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /** Immutable coordinate class */
    private static class Coordinates {
        final int row, col;
        Coordinates(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    /** Holds parsed grid metadata */
    private static class GridData {
        final Coordinates start, end;
        GridData(Coordinates start, Coordinates end) {
            this.start = start;
            this.end = end;
        }
    }

    /** Fast I/O helper (kept as-is from original, formatted for readability) */
    public static class InputReader {
        private InputStream stream;
        private byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;
        private SpaceCharFilter filter;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        public int read() {
            if (numChars == -1)
                throw new InputMismatchException();
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0)
                    return -1;
            }
            return buf[curChar++];
        }

        public int nextInt() {
            int c = read();
            while (isSpaceChar(c))
                c = read();
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9')
                    throw new InputMismatchException();
                res *= 10;
                res += c - '0';
                c = read();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public long nextLong() {
            int c = read();
            while (isSpaceChar(c))
                c = read();
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            long res = 0;
            do {
                if (c < '0' || c > '9')
                    throw new InputMismatchException();
                res *= 10;
                res += c - '0';
                c = read();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public String nextToken() {
            int c = read();
            while (isSpaceChar(c))
                c = read();
            StringBuilder res = new StringBuilder();
            do {
                res.appendCodePoint(c);
                c = read();
            } while (!isSpaceChar(c));
            return res.toString();
        }

        public boolean isSpaceChar(int c) {
            if (filter != null)
                return filter.isSpaceChar(c);
            return isWhitespace(c);
        }

        public static boolean isWhitespace(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        public interface SpaceCharFilter {
            boolean isSpaceChar(int ch);
        }
    }
}

