/**
 * Core solver for the grid path problem.
 * Uses BFS from the endpoint 'E' to compute shortest distances to all reachable cells,
 * then calculates the sum of digits within the shortest distance to 'S'.
 */
class GridPathSolver {
    private static final int[] DX = {1, 0, -1, 0};
    private static final int[] DY = {0, 1, 0, -1};
    private static final int UNREACHABLE = Integer.MAX_VALUE;

    public void solve(FastScanner in, PrintWriter out) {
        int n = in.nextInt();
        int m = in.nextInt();
        char[][] grid = in.readCharacterField(n, m);

        int startRow = -1, startCol = -1;
        int endRow = -1, endCol = -1;

        // Locate start ('S') and end ('E') positions
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == 'S') {
                    startRow = i;
                    startCol = j;
                } else if (grid[i][j] == 'E') {
                    endRow = i;
                    endCol = j;
                }
            }
        }

        if (startRow == -1 || endRow == -1) {
            throw new IllegalArgumentException("Grid must contain both 'S' and 'E' markers.");
        }

        // Compute shortest distances from 'E' to all other cells
        int[][] distances = computeDistances(grid, n, m, endRow, endCol);
        int distanceToStart = distances[startRow][startCol];

        // If 'S' is unreachable, output -1
        if (distanceToStart == UNREACHABLE) {
            out.println(-1);
            return;
        }

        // Sum digits that are reachable within the shortest path distance to 'S'
        int reachableDigitSum = 0;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (Character.isDigit(grid[i][j]) && distances[i][j] <= distanceToStart) {
                    reachableDigitSum += grid[i][j] - '0';
                }
            }
        }
        out.println(reachableDigitSum);
    }

    /**
     * Performs BFS from the given start position to compute shortest distances.
     * Avoids cells marked 'T' (obstacles).
     */
    private int[][] computeDistances(char[][] grid, int n, int m, int startRow, int startCol) {
        int[][] distances = new int[n][m];
        for (int[] row : distances) {
            Arrays.fill(row, UNREACHABLE);
        }

        Queue<Integer> queue = new ArrayDeque<>();
        queue.offer(startRow * m + startCol);
        distances[startRow][startCol] = 0;

        while (!queue.isEmpty()) {
            int v = queue.poll();
            int r = v / m;
            int c = v % m;

            for (int dir = 0; dir < 4; dir++) {
                int nr = r + DX[dir];
                int nc = c + DY[dir];

                if (isValid(nr, nc, n, m) && distances[nr][nc] == UNREACHABLE && grid[nr][nc] != 'T') {
                    distances[nr][nc] = distances[r][c] + 1;
                    queue.offer(nr * m + nc);
                }
            }
        }
        return distances;
    }

    private boolean isValid(int r, int c, int n, int m) {
        return r >= 0 && r < n && c >= 0 && c < m;
    }
}

/**
 * Fast input scanner using BufferedReader and StringTokenizer.
 * Replaces the flawed BufferedReader extension pattern with a robust, standard approach.
 */
class FastScanner {
    private final BufferedReader br;
    private StringTokenizer st;

    public FastScanner(InputStream is) {
        this.br = new BufferedReader(new InputStreamReader(is));
    }

    public String next() {
        while (st == null || !st.hasMoreTokens()) {
            try {
                String line = br.readLine();
                if (line == null) {
                    return null;
                }
                st = new StringTokenizer(line);
            } catch (IOException e) {
                throw new RuntimeException("Failed to read input", e);
            }
        }
        return st.nextToken();
    }

    public int nextInt() {
        String token = next();
        if (token == null) {
            throw new RuntimeException("Unexpected end of input");
        }
        try {
            return Integer.parseInt(token);
        } catch (NumberFormatException e) {
            throw new RuntimeException("Invalid integer format: " + token, e);
        }
    }

    public char[][] readCharacterField(int n, int m) {
        char[][] grid = new char[n][m];
        for (int i = 0; i < n; i++) {
            String row = next();
            if (row == null || row.length() != m) {
                throw new IllegalArgumentException(
                    "Invalid grid row at index " + i + ". Expected length " + m + 
                    ", got " + (row == null ? 0 : row.length())
                );
            }
            grid[i] = row.toCharArray();
        }
        return grid;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayDeque;
import java.util.Arrays;
import java.util.Queue;

public class Biridian {

    // Constants
    private static final int INF = 100_000_000;
    // Directions: Right, Left, Down, Up
    private static final int[][] DIRECTIONS = {{0, 1}, {0, -1}, {1, 0}, {-1, 0}};

    // State variables
    private static int rows;
    private static int cols;
    private static char[][] grid;
    private static int[][] distances;

    public static void main(String[] args) {
        try {
            parseInput();
            bfs();
            System.out.println(calculateResult());
        } catch (IOException e) {
            System.err.println("Error reading input: " + e.getMessage());
        }
    }

    /**
     * Parses the input from System.in.
     * Handles whitespace splitting and basic validation.
     */
    private static void parseInput() throws IOException {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        String line = reader.readLine();

        if (line == null || line.trim().isEmpty()) {
            throw new IOException("Empty input");
        }

        // Split by whitespace to handle multiple spaces between numbers
        String[] tokens = line.trim().split("\\s+");
        rows = Integer.parseInt(tokens[0]);
        cols = Integer.parseInt(tokens[1]);

        grid = new char[rows][];
        for (int i = 0; i < rows; i++) {
            String rowStr = reader.readLine();
            if (rowStr != null) {
                grid[i] = rowStr.toCharArray();
            } else {
                grid[i] = new char[0];
            }
        }
    }

    /**
     * Performs a Multi-Source BFS starting from all 'E' (End) positions.
     * Calculates the shortest distance to every reachable cell.
     */
    private static void bfs() {
        distances = new int[rows][];
        for (int i = 0; i < rows; i++) {
            distances[i] = new int[grid[i].length];
            Arrays.fill(distances[i], INF);
        }

        Queue<int[]> queue = new ArrayDeque<>();

        // Initialize BFS from all 'E' (End) positions
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < grid[r].length; c++) {
                if (grid[r][c] == 'E') {
                    distances[r][c] = 0;
                    queue.offer(new int[]{r, c});
                }
            }
        }

        // Perform BFS
        while (!queue.isEmpty()) {
            int[] current = queue.poll();
            int r = current[0];
            int c = current[1];
            int currentDist = distances[r][c];

            for (int[] dir : DIRECTIONS) {
                int nr = r + dir[0];
                int nc = c + dir[1];

                if (isValid(nr, nc) && grid[nr][nc] != 'T' && distances[nr][nc] == INF) {
                    distances[nr][nc] = currentDist + 1;
                    queue.offer(new int[]{nr, nc});
                }
            }
        }
    }

    /**
     * Checks if coordinates are within grid bounds.
     */
    private static boolean isValid(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < grid[r].length;
    }

    /**
     * Calculates the final result based on BFS distances.
     * Finds the distance to 'S' (Start) and sums digits reachable within that distance.
     */
    private static int calculateResult() {
        int playerMoves = -1;

        // Find the distance from 'E' to 'S' (Start)
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < grid[r].length; c++) {
                if (grid[r][c] == 'S') {
                    playerMoves = distances[r][c];
                }
            }
        }

        int totalValue = 0;
        // Sum digits reachable within the player's move limit
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < grid[r].length; c++) {
                char cell = grid[r][c];
                if (cell >= '0' && cell <= '9') {
                    // Check if reachable and within distance.
                    // Note: distances are >= 0. If playerMoves is -1 (S not found), 
                    // the condition distances <= -1 will be false, preventing addition.
                    if (distances[r][c] <= playerMoves) {
                        totalValue += (cell - '0');
                    }
                }
            }
        }
        return totalValue;
    }
}

import java.io.*;
import java.util.*;

public class BiridianForest {
    /**
     * Represents a coordinate in the 2D grid.
     */
    private static final class Point {
        final int x, y;
        Point(int x, int y) {
            this.x = x;
            this.y = y;
        }
    }

    public static void main(String[] args) throws IOException {
        solve();
    }

    private static void solve() throws IOException {
        // Use try-with-resources for automatic and safe resource management
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
             PrintWriter pw = new PrintWriter(new BufferedOutputStream(System.out))) {

            String line = br.readLine();
            if (line == null) return;

            String[] dims = line.trim().split("\\s+");
            int n = Integer.parseInt(dims[0]);
            int m = Integer.parseInt(dims[1]);

            char[][] grid = new char[n][m];
            Point start = null;
            Point end = null;

            // Parse grid and locate start/end positions
            for (int i = 0; i < n; i++) {
                String row = br.readLine();
                if (row == null) break;
                grid[i] = row.trim().toCharArray();
                for (int j = 0; j < m; j++) {
                    if (j < grid[i].length) {
                        if (grid[i][j] == 'S') {
                            start = new Point(j, i);
                        } else if (grid[i][j] == 'E') {
                            end = new Point(j, i);
                        }
                    }
                }
            }

            // Guard against malformed input
            if (start == null || end == null) {
                pw.println(0);
                return;
            }

            // Initialize distances array
            int[][] distances = new int[n][m];
            for (int[] row : distances) {
                Arrays.fill(row, Integer.MAX_VALUE);
            }

            // BFS setup: Since all edge weights are 1, a standard Queue is 
            // more efficient than a PriorityQueue (O(V+E) vs O(E log V))
            boolean[][] visited = new boolean[n][m];
            Queue<Point> queue = new ArrayDeque<>();

            distances[end.y][end.x] = 0;
            visited[end.y][end.x] = true;
            queue.add(end);

            int[] dx = {-1, 1, 0, 0};
            int[] dy = {0, 0, -1, 1};

            int visitedCount = 1;
            while (!queue.isEmpty() && visitedCount < n * m) {
                Point current = queue.poll();

                for (int i = 0; i < 4; i++) {
                    int nx = current.x + dx[i];
                    int ny = current.y + dy[i];

                    // Check boundaries, visited status, and obstacles
                    if (nx >= 0 && nx < m && ny >= 0 && ny < n && 
                        !visited[ny][nx] && grid[ny][nx] != 'T') {

                        visited[ny][nx] = true;
                        distances[ny][nx] = distances[current.y][current.x] + 1;
                        queue.add(new Point(nx, ny));
                        visitedCount++;
                    }
                }
            }

            // Calculate the sum of digits for reachable cells
            int answer = 0;
            int startDist = distances[start.y][start.x];

            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    if (j < grid[i].length && distances[i][j] <= startDist && 
                        grid[i][j] != 'S' && grid[i][j] != 'E' && Character.isDigit(grid[i][j])) {
                        answer += grid[i][j] - '0';
                    }
                }
            }

            pw.println(answer);
        }
    }
}

import java.util.ArrayDeque;
import java.util.Arrays;
import java.util.Queue;
import java.util.Scanner;

/**
 * Finds the shortest path distance from a starting point 'E' to a target 'S'
 * in a grid, then sums the numeric values of all reachable cells within that distance.
 */
public class ForestPathfinder {
    // Direction vectors: Down, Right, Up, Left
    private static final int[] DR = {1, 0, -1, 0};
    private static final int[] DC = {0, 1, 0, -1};

    public static void main(String[] args) {
        // Use try-with-resources to ensure the Scanner is properly closed
        try (Scanner scanner = new Scanner(System.in)) {
            if (!scanner.hasNextInt()) {
                return;
            }

            int rows = scanner.nextInt();
            int cols = scanner.nextInt();

            char[][] grid = new char[rows][cols];
            int startRow = -1;
            int startCol = -1;

            // Read grid and locate starting position
            for (int i = 0; i < rows; i++) {
                String line = scanner.next();
                grid[i] = line.toCharArray();
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j] == 'E') {
                        startRow = i;
                        startCol = j;
                    }
                }
            }

            if (startRow == -1 || startCol == -1) {
                System.out.println(0);
                return;
            }

            // Initialize BFS structures
            int[][] distances = new int[rows][cols];
            for (int[] row : distances) {
                Arrays.fill(row, -1);
            }

            boolean[][] visited = new boolean[rows][cols];
            Queue<int[]> queue = new ArrayDeque<>();

            queue.offer(new int[]{startRow, startCol});
            visited[startRow][startCol] = true;
            distances[startRow][startCol] = 0;

            int targetDistance = -1;
            int currentDistance = 0;

            // Perform BFS level-by-level to find shortest path to 'S'
            while (!queue.isEmpty()) {
                int levelSize = queue.size();
                for (int i = 0; i < levelSize; i++) {
                    int[] current = queue.poll();
                    int r = current[0];
                    int c = current[1];

                    if (grid[r][c] == 'S') {
                        targetDistance = currentDistance;
                    }

                    // Explore valid neighbors
                    for (int d = 0; d < DR.length; d++) {
                        int nr = r + DR[d];
                        int nc = c + DC[d];

                        if (isValidPosition(nr, nc, rows, cols) &&
                            grid[nr][nc] != 'T' &&
                            !visited[nr][nc]) {

                            visited[nr][nc] = true;
                            distances[nr][nc] = currentDistance + 1;
                            queue.offer(new int[]{nr, nc});
                        }
                    }
                }
                currentDistance++;
            }

            // If 'S' was unreachable, output 0
            if (targetDistance == -1) {
                System.out.println(0);
                return;
            }

            // Sum values of reachable cells within the shortest path distance to 'S'
            long result = 0;
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    char cell = grid[i][j];
                    if (cell != 'E' && cell != 'S' && cell != 'T' &&
                        distances[i][j] != -1 && distances[i][j] <= targetDistance) {
                        result += (cell - '0');
                    }
                }
            }

            System.out.println(result);
        }
    }

    /**
     * Checks if a given row and column are within grid boundaries.
     */
    private static boolean isValidPosition(int r, int c, int rows, int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }
}

