class TaskB {
    private static final char START = 'S';
    private static final char END = 'E';
    private static final char TREE = 'T';
    private static final int UNREACHABLE = -1;

    public void solve(InputReader in, OutputWriter out) {
        int rows = in.nextInt();
        int cols = in.nextInt();
        char[][] grid = in.next2DCharArray(rows, cols);

        Point start = null;
        Point end = null;

        // Locate start and end positions
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                char cell = grid[r][c];
                if (cell == START) {
                    start = new Point(r, c);
                } else if (cell == END) {
                    end = new Point(r, c);
                }
            }
        }

        if (start == null || end == null) {
            out.println(0);
            return;
        }

        // Initialize distances with -1 (unreachable)
        int[][] distances = new int[rows][cols];
        for (int[] row : distances) {
            Arrays.fill(row, UNREACHABLE);
        }

        distances[end.r][end.c] = 0;
        Queue<Point> queue = new ArrayDeque<>();
        queue.add(end);

        // Orthogonal movement directions (Up, Down, Left, Right)
        int[] dr = {-1, 1, 0, 0};
        int[] dc = {0, 0, -1, 1};

        // BFS from End to all reachable cells
        while (!queue.isEmpty()) {
            Point current = queue.poll();
            for (int i = 0; i < 4; i++) {
                int nr = current.r + dr[i];
                int nc = current.c + dc[i];

                if (isValid(nr, nc, rows, cols) &&
                    grid[nr][nc] != TREE &&
                    distances[nr][nc] == UNREACHABLE) {

                    distances[nr][nc] = distances[current.r][current.c] + 1;
                    queue.add(new Point(nr, nc));
                }
            }
        }

        int distanceToStart = distances[start.r][start.c];
        int totalDigits = 0;

        // Sum digits on cells reachable within the start-to-end distance
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                int d = distances[r][c];
                if (d != UNREACHABLE && d <= distanceToStart && isDigit(grid[r][c])) {
                    totalDigits += grid[r][c] - '0';
                }
            }
        }

        out.println(totalDigits);
    }

    private boolean isValid(int r, int c, int rows, int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    private boolean isDigit(char c) {
        return c >= '0' && c <= '9';
    }
}

