import java.io.*;
import java.util.*;

/**
 * Solves a grid-based shortest path problem.
 * Computes the sum of digits located on any shortest path from 'S' to 'E'.
 * Uses BFS from 'E' to determine shortest distances to all reachable cells.
 */
public class ShortestPathDigitSum {

    private int rows;
    private int cols;
    private char[][] grid;
    private int[][] distances;
    private int startX, startY, endX, endY;

    // Direction vectors for moving up, down, left, right
    private static final int[] DX = {1, -1, 0, 0};
    private static final int[] DY = {0, 0, 1, -1};

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner(System.in);
        FastPrinter printer = new FastPrinter(System.out);

        try {
            ShortestPathDigitSum solver = new ShortestPathDigitSum();
            solver.readInput(scanner);
            solver.performBfs();
            long result = solver.calculateDigitSum();
            printer.println(result);
        } catch (Exception e) {
            System.err.println("An error occurred: " + e.getMessage());
        } finally {
            printer.close();
        }
    }

    /** Reads grid dimensions and layout from input */
    private void readInput(FastScanner scanner) {
        this.rows = scanner.nextInt();
        this.cols = scanner.nextInt();
        this.grid = new char[rows][cols];

        for (int i = 0; i < rows; i++) {
            String line = scanner.next();
            for (int j = 0; j < cols; j++) {
                grid[i][j] = line.charAt(j);
                if (grid[i][j] == 'S') {
                    startX = i;
                    startY = j;
                } else if (grid[i][j] == 'E') {
                    endX = i;
                    endY = j;
                }
            }
        }
    }

    /** Performs BFS backwards from 'E' to compute shortest distances to all cells */
    private void performBfs() {
        distances = new int[rows][cols];
        Queue<Position> queue = new ArrayDeque<>();
        queue.add(new Position(endX, endY));

        while (!queue.isEmpty()) {
            Position current = queue.poll();
            for (int i = 0; i < 4; i++) {
                int nx = current.x + DX[i];
                int ny = current.y + DY[i];

                if (isValidCell(nx, ny)) {
                    distances[nx][ny] = distances[current.x][current.y] + 1;
                    queue.add(new Position(nx, ny));
                }
            }
        }
    }

    /** Validates if a cell is within bounds, traversable, and unvisited */
    private boolean isValidCell(int x, int y) {
        if (x < 0 || x >= rows || y < 0 || y >= cols) {
            return false;
        }
        if (grid[x][y] == 'T' || grid[x][y] == 'E') {
            return false;
        }
        if (distances[x][y] != 0) {
            return false; // Already visited
        }
        return true;
    }

    /** Calculates the sum of digits on all shortest paths from 'S' to 'E' */
    private long calculateDigitSum() {
        int shortestPathLength = distances[startX][startY];
        long sum = 0;

        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                // Check if cell is reachable, lies on a shortest path, and contains a digit
                if (distances[i][j] > 0 && distances[i][j] <= shortestPathLength && Character.isDigit(grid[i][j])) {
                    sum += Character.getNumericValue(grid[i][j]);
                }
            }
        }
        return sum;
    }

    /** Represents a coordinate in the grid */
    private static class Position {
        final int x;
        final int y;

        Position(int x, int y) {
            this.x = x;
            this.y = y;
        }
    }

    /** High-performance scanner for competitive programming */
    private static class FastScanner {
        private final InputStream stream;
        private final byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;
        private SpaceCharFilter filter;

        public FastScanner(InputStream stream) {
            this.stream = stream;
        }

        public int read() {
            if (numChars == -1) {
                throw new InputMismatchException();
            }
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0) {
                    return -1;
                }
            }
            return buf[curChar++];
        }

        public int nextInt() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                res *= 10;
                res += c - '0';
                c = read();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public String next() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            StringBuilder res = new StringBuilder();
            do {
                res.appendCodePoint(c);
                c = read();
            } while (!isSpaceChar(c));
            return res.toString();
        }

        public boolean isSpaceChar(int c) {
            return filter != null ? filter.isSpaceChar(c) : (c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1);
        }

        public interface SpaceCharFilter {
            boolean isSpaceChar(int ch);
        }
    }

    /** High-performance printer for competitive programming */
    private static class FastPrinter {
        private final PrintWriter writer;

        public FastPrinter(OutputStream outputStream) {
            writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(outputStream)));
        }

        public FastPrinter(Writer writer) {
            this.writer = new PrintWriter(writer);
        }

        public void print(Object... objects) {
            for (int i = 0; i < objects.length; i++) {
                if (i != 0) {
                    writer.print(' ');
                }
                writer.print(objects[i]);
            }
        }

        public void println(Object... objects) {
            print(objects);
            writer.println();
        }

        public void close() {
            writer.close();
        }

        public void flush() {
            writer.flush();
        }
    }
}

import java.io.*;
import java.util.*;

public class BirrdianForest {
    // Constants for grid characters
    private static final char TREE = 'T';
    private static final char START = 'E';
    private static final char TARGET = 'S';

    // Direction vectors for up, down, left, right
    private static final int[] DR = {-1, 1, 0, 0};
    private static final int[] DC = {0, 0, -1, 1};

    /**
     * Immutable representation of a grid cell.
     */
    private static final class Cell {
        final int row;
        final int col;

        Cell(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    public static void main(String[] args) throws IOException {
        // Use try-with-resources for automatic and safe resource management
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
             PrintWriter writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)))) {

            // 1. Parse dimensions safely
            String line = reader.readLine();
            if (line == null || line.trim().isEmpty()) {
                writer.println(0);
                return;
            }
            String[] dims = line.trim().split("\\s+");
            int rows = Integer.parseInt(dims[0]);
            int cols = Integer.parseInt(dims[1]);

            // 2. Read grid and locate start position
            char[][] grid = new char[rows][cols];
            Cell start = null;

            for (int i = 0; i < rows; i++) {
                String gridLine = reader.readLine();
                if (gridLine == null) break;
                grid[i] = gridLine.toCharArray();
                for (int j = 0; j < cols && j < grid[i].length; j++) {
                    if (grid[i][j] == START) {
                        start = new Cell(i, j);
                    }
                }
            }

            // Handle missing start position gracefully
            if (start == null) {
                writer.println(0);
                return;
            }

            // 3. Execute BFS and output result
            int result = bfs(grid, start, rows, cols);
            writer.println(result);
        }
        // PrintWriter is automatically flushed and closed by try-with-resources
    }

    /**
     * Performs BFS from the start position to find the target.
     * Sums numeric values ('1'-'9') encountered on reachable nodes before finding the target.
     */
    private static int bfs(char[][] grid, Cell start, int rows, int cols) {
        boolean[][] visited = new boolean[rows][cols];
        Queue<Cell> queue = new ArrayDeque<>();
        queue.offer(start);
        visited[start.row][start.col] = true;
        int sum = 0;

        while (!queue.isEmpty()) {
            Cell current = queue.poll();

            // Check if target is reached
            if (grid[current.row][current.col] == TARGET) {
                return sum;
            }

            // Accumulate numeric values from current cell
            char cell = grid[current.row][current.col];
            if (cell >= '1' && cell <= '9') {
                sum += cell - '0';
            }

            // Explore valid neighbors
            for (int i = 0; i < 4; i++) {
                int nr = current.row + DR[i];
                int nc = current.col + DC[i];

                if (isValidMove(grid, nr, nc, rows, cols) && !visited[nr][nc]) {
                    visited[nr][nc] = true;
                    queue.offer(new Cell(nr, nc));
                }
            }
        }
        return sum;
    }

    /**
     * Checks if a move to (row, col) is within bounds and not blocked by a tree.
     */
    private static boolean isValidMove(char[][] grid, int row, int col, int rows, int cols) {
        return row >= 0 && row < rows && col >= 0 && col < cols && grid[row][col] != TREE;
    }
}

import java.io.*;
import java.util.*;

public class Main {
    // Direction vectors for moving up, down, left, right
    private static final int[] DX = {-1, 1, 0, 0};
    private static final int[] DY = {0, 0, -1, 1};
    // Use Integer.MAX_VALUE / 2 to prevent overflow when adding 1 during BFS
    private static final int INF = Integer.MAX_VALUE / 2;

    public static void main(String[] args) throws IOException {
        // Try-with-resources ensures proper cleanup of I/O streams
        try (FastScanner scanner = new FastScanner(System.in);
             PrintWriter out = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)))) {

            // Process test cases until EOF
            while (scanner.hasNext()) {
                int rows = scanner.nextInt();
                int cols = scanner.nextInt();

                char[][] grid = new char[rows][cols];
                for (int i = 0; i < rows; i++) {
                    grid[i] = scanner.next().toCharArray();
                }

                BfsResult result = performBfs(grid, rows, cols);
                int shortestDist = result.shortestDistToS;

                int digitSum = 0;
                // Only sum digits if a valid path to 'S' was actually found
                if (shortestDist != INF) {
                    for (int i = 0; i < rows; i++) {
                        for (int j = 0; j < cols; j++) {
                            if (Character.isDigit(grid[i][j]) && result.dist[i][j] <= shortestDist) {
                                digitSum += grid[i][j] - '0';
                            }
                        }
                    }
                }
                out.println(digitSum);
            }
        }
    }

    /**
     * Performs a multi-source BFS from all 'E' cells to find the shortest distance to any 'S' cell.
     * Returns both the shortest distance to 'S' and the complete distance matrix.
     */
    private static BfsResult performBfs(char[][] grid, int rows, int cols) {
        int[][] dist = new int[rows][cols];
        for (int[] row : dist) {
            Arrays.fill(row, INF);
        }

        Queue<State> queue = new ArrayDeque<>();
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == 'E') {
                    dist[i][j] = 0;
                    queue.add(new State(i, j));
                }
            }
        }

        int shortestDistToS = INF;
        while (!queue.isEmpty()) {
            State current = queue.poll();

            if (grid[current.x][current.y] == 'S') {
                shortestDistToS = dist[current.x][current.y];
                break; // BFS guarantees this is the shortest path to any 'S'
            }

            for (int k = 0; k < 4; k++) {
                int nx = current.x + DX[k];
                int ny = current.y + DY[k];

                if (isValid(nx, ny, rows, cols) &&
                    dist[nx][ny] > dist[current.x][current.y] + 1 &&
                    grid[nx][ny] != 'T') {
                    dist[nx][ny] = dist[current.x][current.y] + 1;
                    queue.add(new State(nx, ny));
                }
            }
        }

        return new BfsResult(shortestDistToS, dist);
    }

    private static boolean isValid(int x, int y, int rows, int cols) {
        return x >= 0 && x < rows && y >= 0 && y < cols;
    }

    /**
     * Encapsulates the result of the BFS traversal.
     */
    private static class BfsResult {
        final int shortestDistToS;
        final int[][] dist;

        BfsResult(int shortestDistToS, int[][] dist) {
            this.shortestDistToS = shortestDistToS;
            this.dist = dist;
        }
    }

    /**
     * Represents a coordinate in the grid.
     */
    private static class State {
        final int x;
        final int y;

        State(int x, int y) {
            this.x = x;
            this.y = y;
        }
    }

    /**
     * Fast input scanner optimized for competitive programming.
     * Handles tokenization, EOF detection, and resource cleanup.
     */
    private static class FastScanner implements AutoCloseable {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        @Override
        public void close() throws IOException {
            br.close();
        }

        boolean hasNext() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) {
                        return false;
                    }
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    return false;
                }
            }
            return true;
        }

        String next() {
            if (hasNext()) {
                return st.nextToken();
            }
            throw new NoSuchElementException("No more tokens available");
        }

        int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Solves a grid-based pathfinding problem using multi-source BFS.
 * Computes distances from all 'E' (Exit) cells, determines the shortest distance to 'S' (Start),
 * and sums the numeric values of all cells reachable within that distance.
 */
public class GridBfsSolver {

    // Direction vectors for moving right, left, down, up
    private static final int[] DELTA_X = {1, -1, 0, 0};
    private static final int[] DELTA_Y = {0, 0, -1, 1};

    // Grid cell constants
    private static final char EXIT = 'E';
    private static final char START = 'S';
    private static final char OBSTACLE = 'T';
    private static final char MIN_DIGIT = '0';
    private static final char MAX_DIGIT = '9';

    private BufferedReader br;
    private PrintWriter out;
    private StringTokenizer tokenizer;

    public static void main(String[] args) {
        new GridBfsSolver().run();
    }

    /**
     * Initializes I/O streams, executes the solution, and ensures resources are closed properly.
     */
    public void run() {
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
             PrintWriter writer = new PrintWriter(new BufferedOutputStream(System.out))) {
            br = reader;
            out = writer;
            tokenizer = new StringTokenizer("");
            solve();
        } catch (IOException e) {
            throw new RuntimeException("I/O error occurred", e);
        } finally {
            out.flush();
        }
    }

    /**
     * Orchestrates input reading, BFS computation, and result output.
     */
    private void solve() throws IOException {
        int n = nextInt();
        int m = nextInt();
        char[][] grid = new char[n][m];
        for (int i = 0; i < n; i++) {
            grid[i] = next().toCharArray();
        }

        int[][] distances = new int[n][m];
        int startDist = bfs(grid, distances, n, m);
        int result = calculateDigitSum(grid, distances, startDist, n, m);

        out.println(result);
    }

    /**
     * Performs a multi-source BFS starting from all 'E' cells.
     * Returns the shortest distance to 'S', or 0 if 'S' is unreachable.
     */
    private int bfs(char[][] grid, int[][] distances, int n, int m) {
        Queue<Point> queue = new ArrayDeque<>();

        // Initialize BFS with all exit positions
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == EXIT) {
                    distances[i][j] = 1; // Distance 1 represents the starting cells
                    queue.offer(new Point(i, j));
                }
            }
        }

        while (!queue.isEmpty()) {
            Point current = queue.poll();

            for (int dir = 0; dir < 4; dir++) {
                int newX = current.x + DELTA_X[dir];
                int newY = current.y + DELTA_Y[dir];

                if (isValid(newX, newY, n, m) && distances[newX][newY] == 0 && grid[newX][newY] != OBSTACLE) {
                    distances[newX][newY] = distances[current.x][current.y] + 1;
                    queue.offer(new Point(newX, newY));
                }
            }
        }

        // Locate the start position and return its distance
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == START) {
                    return distances[i][j];
                }
            }
        }
        return 0; // Should not occur given valid problem constraints
    }

    /**
     * Validates grid boundaries.
     */
    private boolean isValid(int x, int y, int n, int m) {
        return x >= 0 && x < n && y >= 0 && y < m;
    }

    /**
     * Calculates the sum of digit characters in cells that are reachable 
     * and have a distance less than or equal to the distance to 'S'.
     */
    private int calculateDigitSum(char[][] grid, int[][] distances, int startDist, int n, int m) {
        int sum = 0;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (distances[i][j] > 0 && distances[i][j] <= startDist &&
                    grid[i][j] >= MIN_DIGIT && grid[i][j] <= MAX_DIGIT) {
                    sum += grid[i][j] - MIN_DIGIT;
                }
            }
        }
        return sum;
    }

    /**
     * Reads the next token from input.
     */
    private String next() throws IOException {
        while (!tokenizer.hasMoreTokens()) {
            String line = br.readLine();
            if (line == null) return null;
            tokenizer = new StringTokenizer(line);
        }
        return tokenizer.nextToken();
    }

    private int nextInt() throws IOException {
        String s = next();
        return s == null ? 0 : Integer.parseInt(s);
    }

    private long nextLong() throws IOException {
        String s = next();
        return s == null ? 0L : Long.parseLong(s);
    }

    /**
     * Immutable value class representing 2D grid coordinates.
     */
    private static class Point {
        final int x, y;
        Point(int x, int y) {
            this.x = x;
            this.y = y;
        }
    }
}

