class TaskA {
    private static final int INFINITY = 1_000_000_009;
    private static final int OBSTACLE = -3;

    private int[][] grid;
    private int[][] distance;
    private int rows, cols;

    private static class Point {
        final int r, c;
        Point(int r, int c) { this.r = r; this.c = c; }
    }

    public void solve(InputReader in, PrintWriter out) {
        rows = in.nextInt();
        cols = in.nextInt();

        grid = new int[rows][cols];
        distance = new int[rows][cols];
        for (int[] row : distance) {
            Arrays.fill(row, INFINITY);
        }

        int startR = -1, startC = -1;
        int endR = -1, endC = -1;

        for (int i = 0; i < rows; i++) {
            String line = in.next();
            for (int j = 0; j < cols; j++) {
                char ch = line.charAt(j);
                if (Character.isDigit(ch)) {
                    grid[i][j] = ch - '0';
                } else if (ch == 'E') {
                    grid[i][j] = -1;
                    startR = i;
                    startC = j;
                } else if (ch == 'S') {
                    grid[i][j] = -2;
                    endR = i;
                    endC = j;
                } else if (ch == 'T') {
                    grid[i][j] = OBSTACLE;
                }
            }
        }

        // BFS Initialization
        ArrayDeque<Point> queue = new ArrayDeque<>();
        queue.add(new Point(startR, startC));
        distance[startR][startC] = 0;

        int[] dr = {-1, 1, 0, 0};
        int[] dc = {0, 0, -1, 1};

        while (!queue.isEmpty()) {
            Point curr = queue.poll();

            for (int dir = 0; dir < 4; dir++) {
                int nr = curr.r + dr[dir];
                int nc = curr.c + dc[dir];

                if (isValid(nr, nc) && distance[nr][nc] == INFINITY) {
                    distance[nr][nc] = distance[curr.r][curr.c] + 1;
                    queue.add(new Point(nr, nc));
                }
            }
        }

        // Calculate result
        int ans = 0;
        int endDist = distance[endR][endC];
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] > 0 && distance[i][j] <= endDist && (i != endR || j != endC)) {
                    ans += grid[i][j];
                }
            }
        }
        out.println(ans);
    }

    private boolean isValid(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols && grid[r][c] != OBSTACLE;
    }
}

