class GridPathSolver {
    private static final int INF = 1_000_000_000;
    private static final int[][] DIRECTIONS = {
        {0, 1}, {1, 0}, {0, -1}, {-1, 0}
    };

    void solve(FastScanner scanner, PrintWriter out) {
        int rows = scanner.nextInt();
        int cols = scanner.nextInt();
        char[][] grid = new char[rows][cols];
        Point start = null;
        Point end = null;

        for (int r = 0; r < rows; r++) {
            String line = scanner.next();
            grid[r] = line.toCharArray();
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == 'S') {
                    start = new Point(r, c);
                } else if (grid[r][c] == 'E') {
                    end = new Point(r, c);
                }
            }
        }

        if (start == null || end == null) {
            out.println(0);
            return;
        }

        // BFS from 'E' to compute shortest distances to all reachable cells
        int[][] distances = bfs(grid, rows, cols, end);
        int shortestPath = distances[start.row][start.col];
        int result = calculateDigitSum(grid, distances, rows, cols, shortestPath);
        out.println(result);
    }

    private int[][] bfs(char[][] grid, int rows, int cols, Point source) {
        int[][] dist = new int[rows][cols];
        for (int[] row : dist) {
            Arrays.fill(row, INF);
        }

        Queue<Point> queue = new ArrayDeque<>();
        queue.add(source);
        dist[source.row][source.col] = 0;

        while (!queue.isEmpty()) {
            Point curr = queue.poll();

            for (int[] dir : DIRECTIONS) {
                int nextRow = curr.row + dir[0];
                int nextCol = curr.col + dir[1];

                if (isValid(nextRow, nextCol, rows, cols) &&
                    grid[nextRow][nextCol] != 'T' &&
                    dist[nextRow][nextCol] == INF) {
                        dist[nextRow][nextCol] = dist[curr.row][curr.col] + 1;
                        queue.add(new Point(nextRow, nextCol));
                    }
            }
        }
        return dist;
    }

    private boolean isValid(int r, int c, int rows, int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    private int calculateDigitSum(char[][] grid, int[][] dist, int rows, int cols, int shortestPath) {
        int sum = 0;
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                char cell = grid[r][c];
                if (Character.isDigit(cell) && dist[r][c] <= shortestPath) {
                    sum += cell - '0';
                }
            }
        }
        return sum;
    }

    private static class Point {
        final int row;
        final int col;

        Point(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }
}

