import java.util.LinkedList;
import java.util.Queue;
import java.util.Scanner;

/**
 * Solves a grid-based pathfinding problem using Breadth-First Search (BFS).
 * Traverses from 'E' (start) to 'S' (end), avoiding 'T' (walls),
 * and accumulates numeric values from grid cells based on traversal depth.
 */
public class GridPathSolver {

    // Magic number extracted to a named constant for clarity
    private static final int OUTPUT_ADJUSTMENT = 21;

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        if (!scanner.hasNextInt()) {
            return;
        }

        int rows = scanner.nextInt();
        int cols = scanner.nextInt();

        char[][] grid = new char[rows][cols];
        int startRow = 0;
        int startCol = 0;

        // Read grid and locate the starting position
        for (int i = 0; i < rows; i++) {
            String line = scanner.next();
            for (int j = 0; j < cols; j++) {
                grid[i][j] = line.charAt(j);
                if (grid[i][j] == 'E') {
                    startRow = i;
                    startCol = j;
                }
            }
        }

        int accumulatedValue = bfs(grid, rows, cols, startRow, startCol);
        System.out.println(accumulatedValue - OUTPUT_ADJUSTMENT);
    }

    /**
     * Performs BFS to traverse the grid and calculate the accumulated value.
     * Marks nodes as visited upon enqueueing to prevent duplicate processing
     * and improve performance compared to marking on dequeue.
     */
    private static int bfs(char[][] grid, int rows, int cols, int startRow, int startCol) {
        Queue<Position> queue = new LinkedList<>();
        queue.offer(new Position(startRow, startCol, 0));

        boolean[][] visited = new boolean[rows][cols];
        visited[startRow][startCol] = true;

        int accumulatedValue = 0;
        boolean foundEnd = false;
        int maxDepthAtEnd = 0;

        // Direction arrays for cleaner neighbor iteration (Down, Up, Right, Left)
        int[] dr = {1, -1, 0, 0};
        int[] dc = {0, 0, 1, -1};

        while (!queue.isEmpty()) {
            Position current = queue.poll();
            char cell = grid[current.row][current.col];

            if (cell == 'S') {
                foundEnd = true;
                maxDepthAtEnd = current.depth;
            } else if (!foundEnd) {
                accumulatedValue += cell - '0';
                maxDepthAtEnd = Math.max(maxDepthAtEnd, current.depth);
            } else if (foundEnd && current.depth <= maxDepthAtEnd) {
                accumulatedValue += cell - '0';
            }

            // Explore valid neighbors
            for (int i = 0; i < 4; i++) {
                int nextRow = current.row + dr[i];
                int nextCol = current.col + dc[i];

                if (isValid(nextRow, nextCol, rows, cols) &&
                    !visited[nextRow][nextCol] &&
                    grid[nextRow][nextCol] != 'T') {

                    visited[nextRow][nextCol] = true;
                    queue.offer(new Position(nextRow, nextCol, current.depth + 1));
                }
            }
        }
        return accumulatedValue;
    }

    private static boolean isValid(int row, int col, int rows, int cols) {
        return row >= 0 && row < rows && col >= 0 && col < cols;
    }

    /**
     * Immutable record-like class representing a grid position and its BFS depth.
     */
    private static class Position {
        final int row;
        final int col;
        final int depth;

        Position(int row, int col, int depth) {
            this.row = row;
            this.col = col;
            this.depth = depth;
        }
    }
}

import java.util.ArrayDeque;
import java.util.Arrays;
import java.util.Queue;
import java.util.Scanner;

/**
 * Refactored version of problem4.
 * 
 * This program reads a grid of characters and performs a Breadth-First Search (BFS)
 * starting from 'E' (Exit) to find the shortest path to 'S' (Start).
 * It then calculates the sum of all digits on the grid that are reachable 
 * within the shortest distance found between 'E' and 'S'.
 * 
 * Improvements made:
 * 1. Class and variable naming conventions (camelCase, descriptive names).
 * 2. Replaced magic numbers (1000000) with Integer.MAX_VALUE.
 * 3. Replaced three separate LinkedLists for BFS with a single Queue of a custom Node class.
 * 4. Used ArrayDeque instead of LinkedList for better performance.
 * 5. Used direction arrays to reduce code duplication in boundary checks.
 * 6. Separated concerns (Input reading, BFS logic, Calculation).
 * 7. Added comments and JavaDoc for clarity.
 */
public class MazePathSolver {

    /**
     * Helper class to store coordinates and distance for BFS traversal.
     */
    private static class Node {
        int row;
        int col;
        int distance;

        public Node(int row, int col, int distance) {
            this.row = row;
            this.col = col;
            this.distance = distance;
        }
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        // Read grid dimensions
        if (!scanner.hasNextInt()) {
            return;
        }
        int numRows = scanner.nextInt();
        int numCols = scanner.nextInt();
        scanner.nextLine(); // Consume the newline character left by nextInt()

        char[][] grid = new char[numRows][numCols];
        int startRow = -1;
        int startCol = -1;

        // Read the grid and locate the starting point 'E'
        for (int i = 0; i < numRows; i++) {
            String line = scanner.nextLine();
            for (int j = 0; j < numCols; j++) {
                // Handle cases where input line might be shorter than expected
                if (j < line.length()) {
                    grid[i][j] = line.charAt(j);
                } else {
                    grid[i][j] = ' '; // Treat missing characters as empty space
                }

                if (grid[i][j] == 'E') {
                    startRow = i;
                    startCol = j;
                }
            }
        }

        // If 'E' is not found, we cannot proceed.
        if (startRow == -1) {
            System.out.println(0);
            return;
        }

        // Distance matrix initialized to maximum value (representing unvisited/unreachable)
        int[][] distances = new int[numRows][numCols];
        for (int[] row : distances) {
            Arrays.fill(row, Integer.MAX_VALUE);
        }

        // BFS Initialization
        Queue<Node> queue = new ArrayDeque<>();
        queue.add(new Node(startRow, startCol, 0));
        distances[startRow][startCol] = 0;

        int minDistanceToS = Integer.MAX_VALUE;

        // Direction vectors for moving Up, Down, Left, Right
        int[] dr = {-1, 1, 0, 0};
        int[] dc = {0, 0, -1, 1};

        // BFS Loop
        while (!queue.isEmpty()) {
            Node current = queue.poll();

            // Check if we reached the target 'S'
            if (grid[current.row][current.col] == 'S') {
                minDistanceToS = current.distance;
                // Optimization: Since BFS guarantees the first time we encounter 
                // 'S' is via the shortest path, we can stop here.
                break;
            }

            // Explore neighbors
            for (int i = 0; i < 4; i++) {
                int nextRow = current.row + dr[i];
                int nextCol = current.col + dc[i];

                // Check boundaries
                if (nextRow >= 0 && nextRow < numRows && nextCol >= 0 && nextCol < numCols) {
                    char cell = grid[nextRow][nextCol];

                    // Check if not an obstacle ('T') and not visited (distance is MAX)
                    if (cell != 'T' && distances[nextRow][nextCol] == Integer.MAX_VALUE) {
                        distances[nextRow][nextCol] = current.distance + 1;
                        queue.add(new Node(nextRow, nextCol, current.distance + 1));
                    }
                }
            }
        }

        // If 'S' was never reached, minDistanceToS remains MAX_VALUE.
        // To match original behavior (where min=0 if S not found, resulting in sum=0),
        // we set it to -1 so no distance satisfies <= -1.
        if (minDistanceToS == Integer.MAX_VALUE) {
            minDistanceToS = -1;
        }

        // Calculate the sum of digits within the minimum distance found
        int totalSum = 0;
        for (int i = 0; i < numRows; i++) {
            for (int j = 0; j < numCols; j++) {
                char cell = grid[i][j];
                // Original logic: digit must be > '0' and <= '9'
                if (cell > '0' && cell <= '9') {
                    // Check if reachable and within the threshold distance
                    if (distances[i][j] != Integer.MAX_VALUE && distances[i][j] <= minDistanceToS) {
                        totalSum += (cell - '0');
                    }
                }
            }
        }

        System.out.println(totalSum);

        scanner.close();
    }
}

