/**
 * Solves a grid-based pathfinding problem using Breadth-First Search (BFS).
 * Calculates the sum of digit characters ('0'-'9') that are reachable from 
 * the 'E' (End) position and within the shortest path distance to the 'S' (Start) position.
 */
public class GridBfsSolver implements Runnable {

    private static final char WALL = 'T';
    private static final char END = 'E';
    private static final char START = 'S';

    public static void main(String[] args) {
        // Use a dedicated thread with increased stack size to prevent stack overflow 
        // and optimize I/O performance for large inputs.
        new Thread(null, new GridBfsSolver(), "BfsSolver", 1 << 26).start();
    }

    @Override
    public void run() {
        FastScanner scanner = new FastScanner();
        PrintWriter out = new PrintWriter(System.out);

        try {
            int n = scanner.nextInt();
            int m = scanner.nextInt();

            char[][] grid = new char[n][];
            Point endPos = null;
            Point startPos = null;

            // Read the grid and locate start/end positions in a single pass
            for (int i = 0; i < n; i++) {
                String rowStr = scanner.next();
                grid[i] = rowStr.toCharArray();
                for (int j = 0; j < m; j++) {
                    char c = grid[i][j];
                    if (c == END) {
                        endPos = new Point(i, j);
                    } else if (c == START) {
                        startPos = new Point(i, j);
                    }
                }
            }

            // Validate that both critical positions were found
            if (endPos == null || startPos == null) {
                out.println(0);
                return;
            }

            // Perform BFS from the END position to compute shortest distances to all reachable cells
            int[][] distances = bfs(grid, endPos, n, m);
            int startDistance = distances[startPos.row][startPos.col];

            // Sum digits that are reachable from END and within the distance of START
            long totalSum = 0;
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    char c = grid[i][j];
                    if (c >= '0' && c <= '9' && distances[i][j] != -1 && distances[i][j] <= startDistance) {
                        totalSum += c - '0';
                    }
                }
            }

            out.println(totalSum);
        } catch (Exception e) {
            // In production, use proper logging. For competitive programming, 
            // this ensures graceful handling of malformed input.
            e.printStackTrace();
        } finally {
            out.close();
        }
    }

    /**
     * Executes a Breadth-First Search to find the shortest path distances 
     * from a starting point to all other reachable cells in the grid.
     */
    private static int[][] bfs(char[][] grid, Point start, int n, int m) {
        int[][] distances = new int[n][m];
        for (int[] row : distances) {
            Arrays.fill(row, -1);
        }

        Queue<Point> queue = new ArrayDeque<>();
        queue.add(start);
        distances[start.row][start.col] = 0;

        // Direction vectors for moving up, down, left, and right
        int[] dr = {-1, 1, 0, 0};
        int[] dc = {0, 0, -1, 1};

        while (!queue.isEmpty()) {
            Point current = queue.poll();

            for (int k = 0; k < 4; k++) {
                int r = current.row + dr[k];
                int c = current.col + dc[k];

                // Check bounds, visited status, and wall constraints
                if (r >= 0 && r < n && c >= 0 && c < m &&
                    distances[r][c] == -1 && grid[r][c] != WALL) {
                    distances[r][c] = distances[current.row][current.col] + 1;
                    queue.add(new Point(r, c));
                }
            }
        }
        return distances;
    }

    /**
     * Immutable coordinate class to represent grid positions.
     */
    private static class Point {
        final int row;
        final int col;

        Point(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    /**
     * Fast I/O helper class using BufferedReader and StringTokenizer 
     * for efficient input parsing. Replaces the fragile custom byte-reader.
     */
    private static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        public String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Input reading failed", e);
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            String token = next();
            if (token == null) throw new RuntimeException("Unexpected end of input");
            return Integer.parseInt(token);
        }
    }
}

