        Solver.solve(in.nextInt(), in.nextInt(), in, out);
        out.close();
    }

    /**
     * Encapsulates the core algorithm logic. Kept stateless to improve testability
     * and prevent side-effects from shared instance variables.
     */
    static class Solver {
        private static final int[][] DIRECTIONS = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};
        private static final char WALL = 'T';
        private static final char START = 'S';
        private static final char END = 'E';
        private static final int INF = Integer.MAX_VALUE;

        public static void solve(int r, int c, FastScanner in, PrintWriter out) {
            char[][] grid = new char[r][c];
            int startR = 0, startC = 0, endR = 0, endC = 0;

            // Parse grid and locate start/end points
            for (int i = 0; i < r; i++) {
                String line = in.next();
                for (int j = 0; j < c; j++) {
                    grid[i][j] = line.charAt(j);
                    if (grid[i][j] == START) {
                        startR = i;
                        startC = j;
                    } else if (grid[i][j] == END) {
                        endR = i;
                        endC = j;
                    }
                }
            }

            // Calculate shortest distances from the endpoint to all reachable cells
            int[][] distances = bfsDistances(grid, endR, endC);
            int shortestPath = distances[startR][startC];

            // Sum values of digits within the shortest path distance
            int totalValue = 0;
            for (int i = 0; i < r; i++) {
                for (int j = 0; j < c; j++) {
                    if (distances[i][j] <= shortestPath && grid[i][j] >= '1' && grid[i][j] <= '9') {
                        totalValue += grid[i][j] - '0';
                    }
                }
            }

            out.println(totalValue);
        }

        /**
         * Performs a Breadth-First Search to compute shortest path distances
         * from a starting cell to all other reachable cells.
         */
        private static int[][] bfsDistances(char[][] grid, int startR, int startC) {
            int r = grid.length;
            int c = grid[0].length;
            int[][] distances = new int[r][c];
            for (int[] row : distances) {
                Arrays.fill(row, INF);
            }
            distances[startR][startC] = 0;

            Queue<int[]> queue = new ArrayDeque<>();
            queue.offer(new int[]{startR, startC});

            while (!queue.isEmpty()) {
                int[] current = queue.poll();
                int curR = current[0];
                int curC = current[1];
                int currentDist = distances[curR][curC];

                for (int[] dir : DIRECTIONS) {
                    int nextR = curR + dir[0];
                    int nextC = curC + dir[1];

                    if (nextR >= 0 && nextR < r && nextC >= 0 && nextC < c
                            && distances[nextR][nextC] == INF
                            && grid[nextR][nextC] != WALL) {
                        distances[nextR][nextC] = currentDist + 1;
                        queue.offer(new int[]{nextR, nextC});
                    }
                }
            }
            return distances;
        }
    }

    /**
     * Fast input reader using BufferedReader and StringTokenizer.
     * Replaces the legacy StreamTokenizer-based reader with a modern, 
     * robust, and standard competitive programming scanner.
     */
