        out = new PrintWriter(System.out);
        solve();
        out.flush(); // Ensure all buffered output is written to stdout
    }

    public static void main(String[] args) throws IOException {
        new CFA();
    }

    private void solve() throws IOException {
        int n = nextInt();
        int m = nextInt();
        char[][] grid = new char[n][m];

        // Read grid rows, safely skipping potential empty lines
        for (int i = 0; i < n; i++) {
            String line = br.readLine();
            while (line != null && line.trim().isEmpty()) {
                line = br.readLine();
            }
            if (line != null) {
                grid[i] = line.trim().toCharArray();
            }
        }

        int ex = -1, ey = -1, sx = -1, sy = -1;
        // Locate Start ('S') and End ('E') positions
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == 'E') {
                    ex = i;
                    ey = j;
                } else if (grid[i][j] == 'S') {
                    sx = i;
                    sy = j;
                }
            }
        }

        // Initialize distance array with -1 to represent unreachable cells
        int[][] dist = new int[n][m];
        for (int[] row : dist) {
            Arrays.fill(row, -1);
        }

        // BFS Initialization
        Queue<int[]> queue = new ArrayDeque<>();
        queue.offer(new int[]{ex, ey});
        dist[ex][ey] = 0;

        // BFS Execution
        while (!queue.isEmpty()) {
            int[] current = queue.poll();
            int cx = current[0];
            int cy = current[1];
            int cd = dist[cx][cy];

            for (int d = 0; d < 4; d++) {
                int nx = cx + DX[d];
                int ny = cy + DY[d];

                if (isValid(nx, ny, n, m) && grid[nx][ny] != 'T' && dist[nx][ny] == -1) {
                    dist[nx][ny] = cd + 1;
                    queue.offer(new int[]{nx, ny});
                }
            }
        }

        // Sum digits within the shortest path distance of 'S'
        int totalSum = 0;
        int sDistance = dist[sx][sy];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (dist[i][j] != -1 && dist[i][j] <= sDistance && grid[i][j] >= '1' && grid[i][j] <= '9') {
                    totalSum += grid[i][j] - '0';
                }
            }
        }

        out.println(totalSum);
    }

    /** Checks if coordinates are within grid boundaries */
    private boolean isValid(int x, int y, int n, int m) {
        return x >= 0 && x < n && y >= 0 && y < m;
    }

