        String token = nextToken();
        return token == null ? 0L : Long.parseLong(token);
    }

    private double nextDouble() {
        String token = nextToken();
        return token == null ? 0.0 : Double.parseDouble(token);
    }

    private String nextLine() {
        try {
            return br.readLine();
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }
}

