            if (rowStr != null) {
                grid[i] = rowStr.toCharArray();
                for (int j = 0; j < m; j++) {
                    char c = grid[i][j];
                    if (c == 'S') {
                        startPoint = new Point(i, j);
                    } else if (c == 'E') {
                        endPoint = new Point(i, j);
                    }
                }
            }
        }

        // Basic validation to prevent null pointer exceptions
        if (startPoint == null || endPoint == null) {
            out.println(0);
            return;
        }

        // Perform BFS starting from the End point to calculate distances to all cells.
        // The distance array stores the distance FROM the End point.
        int[][] dist = bfs(grid, n, m, endPoint);

        // The target threshold is the distance from End to Start
        int distanceToStart = dist[startPoint.r][startPoint.c];

        int totalValue = 0;

        // Iterate through the grid to sum values of valid cells.
        // Logic: Cell must not be obstacle ('T'), Start, or End.
        // Cell must be reachable from End within distance 'distanceToStart'.
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                char c = grid[i][j];

                // Skip obstacles and special markers
                if (c == 'T' || c == 'S' || c == 'E') {
                    continue;
                }

                // Check reachability and distance constraint.
                // dist[i][j] is Integer.MAX_VALUE if unreachable.
                if (dist[i][j] != Integer.MAX_VALUE && dist[i][j] <= distanceToStart) {
                    // Accumulate digit value.
                    // Assuming valid grid contains digits '0'-'9' for countable cells.
                    if (Character.isDigit(c)) {
                        totalValue += (c - '0');
                    }
                }
            }
        }

        out.println(totalValue);
    }

    /**
     * Performs Breadth-First Search (BFS) from a starting point.
     * 
     * @param grid  The 2D character grid.
     * @param rows  Number of rows.
     * @param cols  Number of columns.
     * @param start The starting Point for BFS.
     * @return A 2D integer array representing distances from the start point.
     */
    private static int[][] bfs(char[][] grid, int rows, int cols, Point start) {
        int[][] dist = new int[rows][cols];
        // Initialize distances to MAX_VALUE (unreachable)
        for (int[] row : dist) {
            Arrays.fill(row, Integer.MAX_VALUE);
        }

        dist[start.r][start.c] = 0;
        Queue<Point> queue = new ArrayDeque<>();
        queue.add(start);

        while (!queue.isEmpty()) {
            Point current = queue.poll();

            // Explore neighbors
            for (int k = 0; k < 4; k++) {
                int nr = current.r + DR[k];
                int nc = current.c + DC[k];

                if (isValidMove(grid, rows, cols, nr, nc)) {
                    // If not visited yet
                    if (dist[nr][nc] == Integer.MAX_VALUE) {
                        dist[nr][nc] = dist[current.r][current.c] + 1;
                        queue.add(new Point(nr, nc));
                    }
                }
            }
        }
        return dist;
    }

    /**
     * Checks if a move to (r, c) is valid.
     */
    private static boolean isValidMove(char[][] grid, int rows, int cols, int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols && grid[r][c] != 'T';
    }

    // --- Helper Classes ---

    /**
     * Simple immutable class to represent a coordinate point.
     */
    private static class Point {
        final int r;
        final int c;

        Point(int r, int c) {
            this.r = r;
            this.c = c;
        }
    }

    // --- Fast I/O Helpers ---

    private static boolean hasNextToken() throws IOException {
        while (st == null || !st.hasMoreTokens()) {
            String line = br.readLine();
            if (line == null) {
                return false;
            }
            st = new StringTokenizer(line);
        }
        return true;
    }

    private static String nextToken() throws IOException {
        return hasNextToken() ? st.nextToken() : null;
    }

    private static int nextInt() throws IOException {
        String token = nextToken();
        // Handle potential null if input ends unexpectedly
        return (token == null) ? 0 : Integer.parseInt(token);
    }
}

import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) {
        // Standard Java I/O setup for better maintainability and resource management
        FastScanner scanner = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out));
        new BiridianForestSolver().solve(scanner, out);
        out.flush();
        out.close();
    }

    /**
     * Encapsulates the core logic for solving the Biridian Forest problem.
     * Uses Dijkstra's algorithm to compute shortest paths from the 'E' position.
     */
    static class BiridianForestSolver {
        private static final int[] DR = {-1, 1, 0, 0};
        private static final int[] DC = {0, 0, -1, 1};
        private static final int INF = Integer.MAX_VALUE;

        public void solve(FastScanner in, PrintWriter out) {
            int rows = in.nextInt();
            int cols = in.nextInt();
            char[][] grid = new char[rows][];
            int[][] distances = new int[rows][cols];

            // Read the grid
            for (int i = 0; i < rows; i++) {
                grid[i] = in.next().toCharArray();
            }

            // Locate Start ('S') and End ('E') positions
            int startRow = -1, startCol = -1;
            int endRow = -1, endCol = -1;

            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j] == 'S') {
                        startRow = i;
                        startCol = j;
                    } else if (grid[i][j] == 'E') {
                        endRow = i;
                        endCol = j;
                    }
                }
            }

            // Compute shortest distances from 'E' to all reachable cells
            dijkstra(grid, distances, endRow, endCol, rows, cols);

            // Calculate the answer: sum of digits on cells reachable within the distance to 'S'
            long answer = 0;
            int distanceToStart = distances[startRow][startCol];

            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (Character.isDigit(grid[i][j]) && distances[i][j] <= distanceToStart) {
                        answer += grid[i][j] - '0';
                    }
                }
            }

            out.println(answer);
        }

        /**
         * Checks if a cell is within bounds and not an obstacle ('T').
         */
        private boolean isWalkable(char[][] grid, int r, int c, int rows, int cols) {
            return r >= 0 && r < rows && c >= 0 && c < cols && grid[r][c] != 'T';
        }

        /**
         * Runs Dijkstra's algorithm from a starting position.
         */
        private void dijkstra(char[][] grid, int[][] distances, int startR, int startC, int rows, int cols) {
            // Initialize all distances to infinity
            for (int[] row : distances) {
                Arrays.fill(row, INF);
            }
            distances[startR][startC] = 0;

            PriorityQueue<Node> pq = new PriorityQueue<>();
            pq.add(new Node(startR, startC, 0));

            boolean[][] visited = new boolean[rows][cols];

            while (!pq.isEmpty()) {
                Node current = pq.poll();
                if (visited[current.r][current.c]) {
                    continue;
                }
                visited[current.r][current.c] = true;

                // Explore all 4 cardinal directions
                for (int d = 0; d < 4; d++) {
                    int nr = current.r + DR[d];
                    int nc = current.c + DC[d];

                    if (isWalkable(grid, nr, nc, rows, cols) && 
                        !visited[nr][nc] && 
                        distances[nr][nc] > current.dist + 1) {

                        distances[nr][nc] = current.dist + 1;
                        pq.add(new Node(nr, nc, distances[nr][nc]));
                    }
                }
            }
        }

        /**
         * Represents a node in the priority queue for Dijkstra's algorithm.
         */
        private static class Node implements Comparable<Node> {
            int r, c, dist;

            Node(int r, int c, int dist) {
                this.r = r;
                this.c = c;
                this.dist = dist;
            }

            @Override
            public int compareTo(Node other) {
                return Integer.compare(this.dist, other.dist);
            }
        }
    }

    /**
     * Fast I/O helper class using BufferedReader and StringTokenizer.
     * Replaces custom byte-parsing for better maintainability and standard compliance.
     */
    static class FastScanner {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastScanner(InputStream inputStream) {
            reader = new BufferedReader(new InputStreamReader(inputStream));
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) {
                        return null;
                    }
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input stream", e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            String s = next();
            if (s == null) {
                throw new NoSuchElementException("End of input reached");
            }
            return Integer.parseInt(s);
        }
    }
}

import java.io.*;
import java.util.*;

public class Main {
    private static final char PLAYER = 'S';
    private static final char DOOR = 'E';
    private static final char OBSTACLE = 'T';

    // Direction vectors: Up, Down, Left, Right
    private static final int[] DR = {-1, 1, 0, 0};
    private static final int[] DC = {0, 0, -1, 1};

    public static void main(String[] args) {
        InputReader in = new InputReader(System.in);
        PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out));

        try {
            int n = in.nextInt();
            int m = in.nextInt();

            GridInfo gridInfo = readGrid(in, n, m);
            char[][] grid = gridInfo.grid;
            int playerRow = gridInfo.playerRow;
            int playerCol = gridInfo.playerCol;
            int doorRow = gridInfo.doorRow;
            int doorCol = gridInfo.doorCol;

            int[][] distances = bfs(grid, n, m, doorRow, doorCol);

            int result = 0;
            int playerDistance = distances[playerRow][playerCol];

            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    // Skip start and end positions
                    if (i == playerRow && j == playerCol) continue;
                    if (i == doorRow && j == doorCol) continue;

                    int dist = distances[i][j];
                    // Only count reachable cells within the player's distance threshold
                    if (dist != -1 && playerDistance != -1 && dist <= playerDistance) {
                        result += grid[i][j] - '0';
                    }
                }
            }

            out.println(result);
        } finally {
            out.flush();
        }
    }

    /**
     * Reads the grid and locates the player and door positions.
     */
    private static GridInfo readGrid(InputReader in, int n, int m) {
        char[][] grid = new char[n][m];
        int playerRow = -1, playerCol = -1;
        int doorRow = -1, doorCol = -1;

        for (int i = 0; i < n; i++) {
            String line = in.next();
            grid[i] = line.toCharArray();
            for (int j = 0; j < m; j++) {
                char c = grid[i][j];
                if (c == PLAYER) {
                    playerRow = i;
                    playerCol = j;
                } else if (c == DOOR) {
                    doorRow = i;
                    doorCol = j;
                }
            }
        }
        return new GridInfo(grid, playerRow, playerCol, doorRow, doorCol);
    }

    /**
     * Performs BFS from the door to calculate shortest distances to all reachable cells.
     */
    private static int[][] bfs(char[][] grid, int n, int m, int startR, int startC) {
        int[][] dist = new int[n][m];
        for (int[] row : dist) {
            Arrays.fill(row, -1);
        }

        // Queue stores encoded coordinates: row * m + col
        Queue<Integer> queue = new ArrayDeque<>();
        queue.add(startR * m + startC);
        dist[startR][startC] = 0;

        while (!queue.isEmpty()) {
            int curr = queue.poll();
            int r = curr / m;
            int c = curr % m;

            for (int k = 0; k < 4; k++) {
                int nr = r + DR[k];
                int nc = c + DC[k];

                if (nr >= 0 && nr < n && nc >= 0 && nc < m &&
                    grid[nr][nc] != OBSTACLE && dist[nr][nc] == -1) {
                    dist[nr][nc] = dist[r][c] + 1;
                    queue.add(nr * m + nc);
                }
            }
        }
        return dist;
    }

    /**
     * Simple data class to bundle grid and coordinate information.
     */
    private static class GridInfo {
        final char[][] grid;
        final int playerRow, playerCol;
        final int doorRow, doorCol;

        GridInfo(char[][] grid, int playerRow, int playerCol, int doorRow, int doorCol) {
            this.grid = grid;
            this.playerRow = playerRow;
            this.playerCol = playerCol;
            this.doorRow = doorRow;
            this.doorCol = doorCol;
        }
    }

    /**
     * Fast input reader for competitive programming environments.
     */
    private static class InputReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }
    }
}

