public class Test {

    /**
     * Dedicated FastScanner for efficient token-based input reading.
     * Encapsulated to avoid static state pollution in the main class.
     */
    private static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input", e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }
    }

    /**
     * Performs a Breadth-First Search from a starting coordinate.
     * Populates the distance matrix with 1-based distances.
     *
     * @param startRow Row index of the starting position
     * @param startCol Column index of the starting position
     * @param n        Number of rows in the grid
     * @param m        Number of columns in the grid
     * @param grid     The character grid representing the map
     * @param dist     Distance matrix to be populated (initialized to 0)
     */
    private static void bfs(int startRow, int startCol, int n, int m, char[][] grid, int[][] dist) {
        Queue<Integer> queue = new ArrayDeque<>();
        dist[startRow][startCol] = 1; // 1-based distance to match original logic
        queue.add(startRow * m + startCol);

        // Direction vectors: Up, Down, Left, Right
        int[] dr = {-1, 1, 0, 0};
        int[] dc = {0, 0, -1, 1};

        while (!queue.isEmpty()) {
            int curr = queue.poll();
            int r = curr / m;
            int c = curr % m;

            for (int i = 0; i < 4; i++) {
                int nr = r + dr[i];
                int nc = c + dc[i];

                // Boundary check, obstacle check, and unvisited check
                if (nr >= 0 && nr < n && nc >= 0 && nc < m &&
                    grid[nr][nc] != 'T' && dist[nr][nc] == 0) {
                    dist[nr][nc] = dist[r][c] + 1;
                    queue.add(nr * m + nc);
                }
            }
        }
    }

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner();
        PrintWriter out = new PrintWriter(System.out);

        int n = scanner.nextInt();
        int m = scanner.nextInt();

        char[][] grid = new char[n][m];
        int startRow = 0, startCol = 0, endRow = 0, endCol = 0;

        // Read grid and locate start ('S') and end ('E') positions
        for (int i = 0; i < n; i++) {
            String row = scanner.next();
            grid[i] = row.toCharArray();
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == 'S') {
                    startRow = i;
                    startCol = j;
                } else if (grid[i][j] == 'E') {
                    endRow = i;
                    endCol = j;
                }
            }
        }

        // First BFS: Compute distances from Start
        int[][] distFromStart = new int[n][m];
        bfs(startRow, startCol, n, m, grid, distFromStart);

        int shortestPathLen = distFromStart[endRow][endCol];

        // Second BFS: Compute distances from End
        // Allocating a fresh array is cleaner and safer than manually zeroing out a reused array
        int[][] distFromEnd = new int[n][m];
        bfs(endRow, endCol, n, m, grid, distFromEnd);

        // Calculate answer based on original logic
        int ans = 0;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (Character.isDigit(grid[i][j]) && distFromEnd[i][j] > 0 && distFromEnd[i][j] <= shortestPathLen) {
                    ans += grid[i][j] - '0';
                }
            }
        }

        out.println(ans);
        out.flush();
        out.close();
    }
}

