class TaskB {
    private static final int[] DR = {1, -1, 0, 0};
    private static final int[] DC = {0, 0, 1, -1};

    public void solve(FastScanner in, PrintWriter out) {
        int n = in.nextInt();
        int m = in.nextInt();

        char[][] grid = new char[n][m];
        int exitR = -1, exitC = -1;
        int startR = -1, startC = -1;

        for (int i = 0; i < n; i++) {
            String line = in.next();
            grid[i] = line.toCharArray();
            for (int j = 0; j < m; j++) {
                char cell = grid[i][j];
                if (cell == 'E') {
                    exitR = i;
                    exitC = j;
                } else if (cell == 'S') {
                    startR = i;
                    startC = j;
                }
            }
        }

        int[][] distances = bfs(grid, n, m, exitR, exitC);
        int distanceToStart = distances[startR][startC];

        int totalDigits = 0;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (isDigit(grid[i][j]) && distances[i][j] != -1 && distances[i][j] <= distanceToStart) {
                    totalDigits += grid[i][j] - '0';
                }
            }
        }

        out.println(totalDigits);
    }

    private boolean isDigit(char c) {
        return c >= '0' && c <= '9';
    }

    private int[][] bfs(char[][] grid, int n, int m, int startR, int startC) {
        int[][] dist = new int[n][m];
        for (int[] row : dist) {
            Arrays.fill(row, -1);
        }

        Queue<Point> queue = new ArrayDeque<>();
        queue.add(new Point(startR, startC));
        dist[startR][startC] = 0;

        while (!queue.isEmpty()) {
            Point current = queue.poll();
            for (int k = 0; k < 4; k++) {
                int nextR = current.r + DR[k];
                int nextC = current.c + DC[k];

                if (isValid(nextR, nextC, n, m) && grid[nextR][nextC] != 'T' && dist[nextR][nextC] == -1) {
                    dist[nextR][nextC] = dist[current.r][current.c] + 1;
                    queue.add(new Point(nextR, nextC));
                }
            }
        }
        return dist;
    }

    private boolean isValid(int r, int c, int n, int m) {
        return r >= 0 && r < n && c >= 0 && c < m;
    }

    private static class Point {
        final int r, c;

        Point(int r, int c) {
            this.r = r;
            this.c = c;
        }

        @Override
        public boolean equals(Object o) {
            if (this == o) return true;
            if (!(o instanceof Point)) return false;
            Point point = (Point) o;
            return r == point.r && c == point.c;
        }

        @Override
        public int hashCode() {
            return Objects.hash(r, c);
        }
    }
}

