/**
 * Solves a grid-based multi-source BFS problem.
 * <p>
 * Reads a grid, performs BFS from all 'E' cells, determines the distance to 'S',
 * and calculates the sum of all numeric characters within that distance threshold.
 */
public class BfsGridSolver {

    // Grid cell constants
    private static final char START_CHAR = 'S';
    private static final char END_CHAR = 'E';
    private static final char OBSTACLE_CHAR = 'T';
    private static final char MIN_DIGIT = '0';
    private static final char MAX_DIGIT = '9';

    // Movement directions: right, left, down, up
    private static final int[][] DIRECTIONS = {
        {0, 1}, {0, -1}, {1, 0}, {-1, 0}
    };

    public static void main(String[] args) {
        // Setup input stream (fallback to b.in if available, otherwise System.in)
        InputStream input = System.in;
        File inputFile = new File("b.in");
        if (inputFile.exists() && inputFile.canRead()) {
            try {
                input = new FileInputStream(inputFile);
            } catch (FileNotFoundException e) {
                // Silently fallback to standard input
            }
        }

        FastScanner scanner = new FastScanner(input);
        PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out));

        try {
            solve(scanner, out);
        } catch (IOException e) {
            out.println("Error processing input: " + e.getMessage());
        } finally {
            out.flush();
            out.close();
        }
    }

    /**
     * Core logic: BFS distance calculation and result aggregation.
     */
    private static void solve(FastScanner scanner, PrintWriter out) throws IOException {
        int rows = scanner.nextInt();
        int cols = scanner.nextInt();

        char[][] grid = new char[rows][];
        for (int r = 0; r < rows; r++) {
            String line = scanner.next();
            if (line == null) throw new IOException("Unexpected end of input while reading grid rows.");
            grid[r] = line.toCharArray();
        }

        // Initialize distances with -1 (unvisited)
        int[][] distances = new int[rows][cols];
        for (int[] row : distances) {
            Arrays.fill(row, -1);
        }

        // Multi-source BFS initialization from all 'E' cells
        Queue<Cell> bfsQueue = new ArrayDeque<>();
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == END_CHAR) {
                    bfsQueue.add(new Cell(r, c));
                    distances[r][c] = 0;
                }
            }
        }

        // BFS Execution
        while (!bfsQueue.isEmpty()) {
            Cell current = bfsQueue.poll();
            for (int[] dir : DIRECTIONS) {
                int nextR = current.row + dir[0];
                int nextC = current.col + dir[1];

                if (isValid(nextR, nextC, rows, cols) && grid[nextR][nextC] != OBSTACLE_CHAR) {
                    if (distances[nextR][nextC] == -1) {
                        distances[nextR][nextC] = distances[current.row][current.col] + 1;
                        bfsQueue.add(new Cell(nextR, nextC));
                    }
                }
            }
        }

        // Find distance to 'S'
        int startDistance = -1;
        outerLoop:
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == START_CHAR) {
                    startDistance = distances[r][c];
                    break outerLoop;
                }
            }
        }

        // Sum numeric values within the reachable distance from 'S'
        int totalFightValue = 0;
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (distances[r][c] != -1 && distances[r][c] <= startDistance) {
                    char cell = grid[r][c];
                    if (cell >= MIN_DIGIT && cell <= MAX_DIGIT) {
                        totalFightValue += cell - MIN_DIGIT;
                    }
                }
            }
        }

        out.println(totalFightValue);
    }

    /**
     * Checks if coordinates are within grid bounds.
     */
    private static boolean isValid(int row, int col, int maxRow, int maxCol) {
        return row >= 0 && col >= 0 && row < maxRow && col < maxCol;
    }

    /**
     * Lightweight immutable record to represent grid coordinates.
     * Replaces cryptic bit-packing with explicit, self-documenting code.
     */
    private static record Cell(int row, int col) {}

    /**
     * Fast, memory-efficient scanner for competitive programming style inputs.
     */
    private static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner(InputStream input) {
            this.br = new BufferedReader(new InputStreamReader(input));
        }

        String next() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) return null;
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

        int nextInt() throws IOException {
            String token = next();
            if (token == null) throw new IOException("Unexpected end of input");
            return Integer.parseInt(token);
        }
    }
}

