            // Hardcoded test cases count as in original, easily adjustable
            int t = 1;
            for (int i = 0; i < t; i++) {
                solver.solve(in, out);
            }
        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    /**
     * Encapsulates the problem-solving logic for grid traversal and scoring.
     */
    static class GridSolver {
        // Magic characters replaced with named constants for readability
        private static final char START = 'S';
        private static final char END = 'E';
        private static final char TRAP = 'T';
        private static final char DIGIT_START = '0';
        private static final char DIGIT_END = '9';

        public void solve(FastReader in, PrintWriter out) {
            int rows = in.nextInt();
            int cols = in.nextInt();

            char[][] grid = new char[rows][cols];
            int startRow = -1, startCol = -1;
            Queue<State> queue = new ArrayDeque<>();

            // Parse grid and initialize BFS queue with all 'E' positions
            for (int i = 0; i < rows; i++) {
                // Using next() instead of nextLine() avoids common CP newline-handling bugs
                String line = in.next();
                grid[i] = line.toCharArray();
                for (int j = 0; j < cols; j++) {
                    char c = grid[i][j];
                    if (c == END) {
                        queue.add(new State(i, j, 0));
                    } else if (c == START) {
                        startRow = i;
                        startCol = j;
                    }
                }
            }

            boolean[][] visited = new boolean[rows][cols];
            int score = 0;
            boolean reachedStart = false;
            int minDistanceToStart = Integer.MAX_VALUE;

            // Direction vectors for Up, Down, Left, Right
            int[] dr = {-1, 1, 0, 0};
            int[] dc = {0, 0, -1, 1};

            while (!queue.isEmpty()) {
                State current = queue.poll();
                int r = current.r;
                int c = current.c;
                int dist = current.dist;

                if (visited[r][c]) continue;
                visited[r][c] = true;

                if (grid[r][c] == START) {
                    reachedStart = true;
                    if (dist < minDistanceToStart) {
                        minDistanceToStart = dist;
                    }
                }

                // Original break condition: stop exploring once we've passed the shortest path to 'S'
                if (reachedStart && dist > minDistanceToStart) {
                    break;
                }

                // Accumulate score from digits
                if (grid[r][c] >= DIGIT_START && grid[r][c] <= DIGIT_END) {
                    score += grid[r][c] - DIGIT_START;
                }

                // Explore neighbors using direction arrays to eliminate repetitive if-statements
                for (int k = 0; k < 4; k++) {
                    int nr = r + dr[k];
                    int nc = c + dc[k];

                    if (nr >= 0 && nr < rows && nc >= 0 && nc < cols &&
                        !visited[nr][nc] && grid[nr][nc] != TRAP && grid[nr][nc] != END) {
                        queue.add(new State(nr, nc, dist + 1));
                    }
                }
            }

            out.println(score);
        }

        /**
         * Immutable state holder for BFS traversal.
         */
        private static class State {
            final int r, c, dist;

            State(int r, int c, int dist) {
                this.r = r;
                this.c = c;
                this.dist = dist;
            }
        }
    }

    /**
     * Optimized fast I/O reader for competitive programming.
     */
    static class FastReader {
        private BufferedReader br;
        private StringTokenizer st;

        public FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        long nextLong() {
