/**
 * Solves the grid traversal problem using Breadth-First Search (BFS).
 * Calculates shortest distances from all 'E' cells, finds the distance to 'S',
 * and sums digits in reachable cells within that distance.
 */
class GridSolver {
    // Extracted constants for readability and maintainability
    private static final char START_CHAR = 'S';
    private static final char END_CHAR = 'E';
    private static final char TRAP_CHAR = 'T';
    private static final char DIGIT_START = '0';
    private static final char DIGIT_END = '9';

    /**
     * @param testNumber Test case identifier (unused in this implementation)
     * @param in         Input reader for grid data
     * @param out        Output writer for results
     */
    public void solve(int testNumber, InputReader in, PrintWriter out) {
        int rows = in.nextInt();
        int cols = in.nextInt();
        char[][] grid = new char[rows][cols];

        // Read grid into a 2D char array for efficient character access
        for (int r = 0; r < rows; r++) {
            String line = in.next();
            grid[r] = line.toCharArray();
        }

        // Initialize distance matrix with -1 to represent unvisited cells
        int[][] distances = new int[rows][cols];
        for (int[] row : distances) {
            Arrays.fill(row, -1);
        }

        // Use standard Queue API for better readability and maintainability
        Queue<int[]> queue = new ArrayDeque<>();
        int startRow = -1;
        int startCol = -1;

        // Initialize BFS from all 'E' cells and locate the 'S' cell
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                char cell = grid[r][c];
                if (cell == END_CHAR) {
                    distances[r][c] = 0;
                    queue.offer(new int[]{r, c});
                } else if (cell == START_CHAR) {
                    startRow = r;
                    startCol = c;
                }
            }
        }

        // Direction vectors for Up, Down, Left, Right movement
        int[] dr = {-1, 1, 0, 0};
        int[] dc = {0, 0, -1, 1};

        // Standard BFS traversal
        while (!queue.isEmpty()) {
            int[] current = queue.poll();
            int r = current[0];
            int c = current[1];

            for (int i = 0; i < 4; i++) {
                int nr = r + dr[i];
                int nc = c + dc[i];

                // Validate bounds, avoid traps, and check if unvisited
                if (nr >= 0 && nr < rows && nc >= 0 && nc < cols &&
                    grid[nr][nc] != TRAP_CHAR && distances[nr][nc] == -1) {
                    distances[nr][nc] = distances[r][c] + 1;
                    queue.offer(new int[]{nr, nc});
                }
            }
        }

        // Safely retrieve distance to start cell
        int startDistance = (startRow != -1 && startCol != -1) ? distances[startRow][startCol] : -1;

        // Sum digits in cells that are reachable and within the start distance
        int result = 0;
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                char cell = grid[r][c];
                if (cell >= DIGIT_START && cell <= DIGIT_END &&
                    distances[r][c] >= 0 && distances[r][c] <= startDistance) {
                    result += cell - DIGIT_START;
                }
            }
        }

        out.println(result);
    }
}

