import java.util.ArrayDeque;
import java.util.Arrays;
import java.util.Queue;
import java.util.Scanner;

public class BiridianForest {
    // Constants for grid characters to avoid magic numbers
    private static final char START_CHAR = 'S';
    private static final char EXIT_CHAR = 'E';
    private static final char OBSTACLE_CHAR = 'T';
    private static final int UNREACHABLE = -1;

    // Direction vectors: Up, Left, Down, Right
    private static final int[] DR = {-1, 0, 1, 0};
    private static final int[] DC = {0, -1, 0, 1};

    /**
     * Represents a coordinate in the grid.
     * Using a dedicated class improves code readability compared to passing
     * separate x and y integers or packing them into a single integer.
     */
    private static class Point {
        final int r;
        final int c;

        Point(int r, int c) {
            this.r = r;
            this.c = c;
        }
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        // Read dimensions
        if (!scanner.hasNextInt()) {
            scanner.close();
            return;
        }
        int rows = scanner.nextInt();
        int columns = scanner.nextInt();
        scanner.nextLine(); // Consume the newline character after integers

        char[][] grid = new char[rows][columns];
        Point start = null;
        Point exit = null;

        // Read grid and locate Start/Exit points
        for (int r = 0; r < rows; r++) {
            String line = scanner.nextLine();
            // Assign the row. Note: Input is assumed to be well-formed (rectangular grid).
            grid[r] = line.toCharArray();

            for (int c = 0; c < grid[r].length; c++) {
                char cell = grid[r][c];
                if (cell == START_CHAR) {
                    start = new Point(r, c);
                } else if (cell == EXIT_CHAR) {
                    exit = new Point(r, c);
                }
            }
        }

        // Safety check for missing start or exit
        if (start == null || exit == null) {
            System.out.println(0);
            scanner.close();
            return;
        }

        // 1. Calculate distances from Start to all cells
        // We pass the intended grid dimensions (rows, columns) to the BFS method
        int[][] distancesFromStart = bfs(grid, start, rows, columns);

        // Distance from Start to Exit
        int exitDistance = (exit.r < rows && exit.c < columns) ? distancesFromStart[exit.r][exit.c] : -1;

        // 2. Calculate distances from Exit to all cells
        int[][] distancesFromExit = bfs(grid, exit, rows, columns);

        // 3. Calculate minimum battles
        int minBattles = 0;
        for (int r = 0; r < rows; r++) {
            // Iterate through the actual length of the row to handle potential jagged input safely
            int rowLen = (r < rows) ? grid[r].length : 0;
            for (int c = 0; c < rowLen; c++) {
                char cell = grid[r][c];
                // Retrieve distance. Check bounds against the BFS result array size (rows x columns)
                int distFromExit = (r < rows && c < columns) ? distancesFromExit[r][c] : UNREACHABLE;

                // Logic preserved from original:
                // - Not Start or Exit
                // - Reachable from Exit (dist >= 0)
                // - Distance from Exit is within the total path length (dist <= exitDistance)
                if (cell != START_CHAR && cell != EXIT_CHAR &&
                    distFromExit != UNREACHABLE && distFromExit <= exitDistance) {

                    minBattles += (cell - '0');
                }
            }
        }

        System.out.println(minBattles);
        scanner.close();
    }

    /**
     * Performs Breadth-First Search (BFS) from a starting point.
     * Returns a 2D array where each cell contains the shortest distance
     * from the start point to that cell. Unreachable cells remain -1.
     * 
     * @param grid The 2D character grid
     * @param start The starting coordinate
     * @param rows Number of rows
     * @param columns Number of columns
     * @return 2D array of distances
     */
    private static int[][] bfs(char[][] grid, Point start, int rows, int columns) {
        int[][] distances = new int[rows][columns];

        // Initialize all distances to -1 (unreachable)
        for (int[] row : distances) {
            Arrays.fill(row, UNREACHABLE);
        }

        // Use ArrayDeque for better performance than LinkedList
        Queue<Point> queue = new ArrayDeque<>();
        queue.add(start);

        // Validate start position before setting distance
        if (start.r >= 0 && start.r < rows && start.c >= 0 && start.c < columns) {
            distances[start.r][start.c] = 0;
        } else {
            return distances; // Start is out of bounds
        }

        while (!queue.isEmpty()) {
            Point current = queue.poll();

            for (int i = 0; i < 4; i++) {
                int nextR = current.r + DR[i];
                int nextC = current.c + DC[i];

                if (isValidMove(nextR, nextC, rows, columns, grid, distances)) {
                    distances[nextR][nextC] = distances[current.r][current.c] + 1;
                    queue.add(new Point(nextR, nextC));
                }
            }
        }

        return distances;
    }

    /**
     * Checks if a move to (r, c) is valid.
     */
    private static boolean isValidMove(int r, int c, int rows, int columns, char[][] grid, int[][] distances) {
        // Check bounds against the logical grid dimensions
        if (r < 0 || r >= rows || c < 0 || c >= columns) {
            return false;
        }
        // Check if already visited
        if (distances[r][c] != UNREACHABLE) {
            return false;
        }
        // Check for obstacles
        // Note: Check grid row length to handle potential jagged input safely
        if (c >= grid[r].length || grid[r][c] == OBSTACLE_CHAR) {
            return false;
        }
        return true;
    }
}

import java.util.Arrays;
import java.util.LinkedList;
import java.util.Queue;
import java.util.Scanner;

public class BiridianForest {

    /**
     * Helper class to represent a coordinate (row, col) in the grid.
     * This replaces the use of separate static variables or parallel lists for coordinates.
     */
    private static class Point {
        int row;
        int col;

        Point(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        // Read grid dimensions
        if (!scanner.hasNextInt()) {
            return;
        }
        int rows = scanner.nextInt();
        int cols = scanner.nextInt();

        char[][] grid = new char[rows][cols];
        Point startPoint = null; // Coordinates for 'S'
        Point endPoint = null;   // Coordinates for 'E'

        // Read the grid content
        for (int i = 0; i < rows; i++) {
            String rowStr = scanner.next();
            for (int j = 0; j < cols; j++) {
                char ch = rowStr.charAt(j);
                grid[i][j] = ch;
                if (ch == 'S') {
                    startPoint = new Point(i, j);
                } else if (ch == 'E') {
                    endPoint = new Point(i, j);
                }
            }
        }

        // Perform BFS starting from 'E' to calculate distances to all cells.
        // The original logic computed distances starting from 'E'.
        int[][] distances = bfs(grid, endPoint, rows, cols);

        // Determine the shortest distance from 'E' to 'S'
        int shortestDistanceToStart = -1;
        if (startPoint != null && distances[startPoint.row][startPoint.col] != -1) {
            shortestDistanceToStart = distances[startPoint.row][startPoint.col];
        }

        // Calculate the sum of digits in cells that are reachable from 'E'
        // and are within the shortest distance to 'S'.
        int totalScore = 0;
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                char cell = grid[i][j];

                // Check if the cell contains a digit
                if (Character.isDigit(cell)) {
                    int digitValue = cell - '0';
                    int distance = distances[i][j];

                    // Condition: Cell must be reachable (distance != -1)
                    // and distance must be <= shortest distance to 'S'
                    if (distance != -1 && distance <= shortestDistanceToStart) {
                        totalScore += digitValue;
                    }
                }
            }
        }

        System.out.println(totalScore);
        scanner.close();
    }

    /**
     * Performs Breadth-First Search (BFS) to compute the shortest distance
     * from a starting point to all other reachable cells in the grid.
     *
     * @param grid    The 2D character grid.
     * @param start   The starting Point for the BFS.
     * @param rows    Number of rows in the grid.
     * @param cols    Number of columns in the grid.
     * @return        A 2D array where dist[i][j] is the distance from start to (i, j).
     */
    private static int[][] bfs(char[][] grid, Point start, int rows, int cols) {
        int[][] dist = new int[rows][cols];
        // Initialize distances to -1 (representing unreachable)
        for (int[] row : dist) {
            Arrays.fill(row, -1);
        }

        // Use a Queue for BFS. LinkedList implements Queue efficiently.
        Queue<Point> queue = new LinkedList<>();

        // Initialize start node
        dist[start.row][start.col] = 0;
        queue.add(start);

        // Direction vectors for Up, Down, Left, Right
        int[] dr = {-1, 1, 0, 0};
        int[] dc = {0, 0, -1, 1};

        while (!queue.isEmpty()) {
            Point current = queue.poll();

            // Explore adjacent cells
            for (int k = 0; k < 4; k++) {
                int r = current.row + dr[k];
                int c = current.col + dc[k];

                // Check boundaries
                if (r >= 0 && r < rows && c >= 0 && c < cols) {
                    // Check if not a tree ('T') and not yet visited
                    if (grid[r][c] != 'T' && dist[r][c] == -1) {
                        dist[r][c] = dist[current.row][current.col] + 1;
                        queue.add(new Point(r, c));
                    }
                }
            }
        }

        return dist;
    }
}

import java.io.*;
import java.util.*;

public class GridSolver {
    // Direction arrays: row changes, column changes
    private static final int[] ROW_DIRS = {-1, 1, 0, 0};
    private static final int[] COL_DIRS = {0, 0, -1, 1};
    private static final int UNREACHABLE = Integer.MAX_VALUE;

    private int rows, cols;
    private char[][] grid;
    private int[][] distances;
    private boolean[][] visited;
    private int startRow, startCol, endRow, endCol;

    public static void main(String[] args) throws IOException {
        GridSolver solver = new GridSolver();
        solver.run();
    }

    private void run() throws IOException {
        FastReader reader = new FastReader(System.in);
        PrintWriter out = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)));

        try {
            readInput(reader);
            computeDistances();
            long result = calculateResult();
            out.println(result);
        } finally {
            out.close();
        }
    }

    private void readInput(FastReader reader) {
        rows = reader.nextInt();
        cols = reader.nextInt();

        grid = new char[rows][cols];
        distances = new int[rows][cols];
        visited = new boolean[rows][cols];

        for (int i = 0; i < rows; i++) {
            String line = reader.next();
            for (int j = 0; j < cols; j++) {
                grid[i][j] = line.charAt(j);
                distances[i][j] = UNREACHABLE;

                if (grid[i][j] == 'S') {
                    startRow = i;
                    startCol = j;
                } else if (grid[i][j] == 'E') {
                    endRow = i;
                    endCol = j;
                }
            }
        }
    }

    private void computeDistances() {
        Queue<int[]> queue = new ArrayDeque<>();
        queue.offer(new int[]{endRow, endCol});
        visited[endRow][endCol] = true;
        distances[endRow][endCol] = 0;

        while (!queue.isEmpty()) {
            int[] current = queue.poll();
            int r = current[0];
            int c = current[1];

            for (int i = 0; i < 4; i++) {
                int nr = r + ROW_DIRS[i];
                int nc = c + COL_DIRS[i];

                if (isWithinBounds(nr, nc) && !visited[nr][nc] && grid[nr][nc] != 'T') {
                    visited[nr][nc] = true;
                    distances[nr][nc] = distances[r][c] + 1;
                    queue.offer(new int[]{nr, nc});
                }
            }
        }
    }

    private boolean isWithinBounds(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    private long calculateResult() {
        long sum = 0;
        int distanceToStart = distances[startRow][startCol];

        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] != 'S' && grid[i][j] != 'E' && distances[i][j] <= distanceToStart) {
                    sum += grid[i][j] - '0';
                }
            }
        }
        return sum;
    }

    /**
     * Fast I/O utility to handle BufferedReader and StringTokenizer efficiently.
     */
    private static class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastReader(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        public String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            String token = next();
            return token == null ? 0 : Integer.parseInt(token);
        }
    }
}

