/**
 * Refactored solution for grid path analysis.
 * 
 * Changes made:
 * 1. Renamed class to GridPathSolver for better semantics.
 * 2. Encapsulated state (n, m, grid) into local variables or instance scope.
 * 3. Used descriptive variable names (rows, cols, startRow, etc.).
 * 4. Implemented a Point class for BFS queue to improve readability and safety.
 * 5. Extracted logic into helper methods (bfs, isValid).
 * 6. Improved FastScanner robustness.
 */
public class GridPathSolver {

    // Helper class to store grid coordinates
    private static class Point {
        int r, c;
        Point(int r, int c) {
            this.r = r;
            this.c = c;
        }
    }

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner(System.in);

        // Read dimensions
        String nStr = scanner.next();
        if (nStr == null) return; // Handle empty input gracefully
        int rows = Integer.parseInt(nStr);
        int cols = scanner.nextInt();

        char[][] grid = new char[rows][cols];
        int startRow = -1, startCol = -1;
        int endRow = -1, endCol = -1;

        // Read grid and locate Start (S) and End (E)
        for (int i = 0; i < rows; i++) {
            String line = scanner.next();
            if (line == null) break; 
            for (int j = 0; j < cols; j++) {
                grid[i][j] = line.charAt(j);
                if (grid[i][j] == 'S') {
                    startRow = i;
                    startCol = j;
                } else if (grid[i][j] == 'E') {
                    endRow = i;
                    endCol = j;
                }
            }
        }

        // Distance matrix initialized to -1 (unvisited)
        int[][] distances = new int[rows][cols];
        for (int[] row : distances) {
            Arrays.fill(row, -1);
        }

        // BFS from End (E) to calculate distances to all reachable cells
        bfs(endRow, endCol, rows, cols, grid, distances);

        // The distance from End to Start
        int distanceToEnd = distances[startRow][startCol];

        // Calculate result: sum of numeric values of cells 
        // that are reachable and closer (or equal distance) to End than Start is.
        int result = 0;
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                // Check if cell is reachable, within distance limit, and not S or E
                if (distances[r][c] != -1 && 
                    distances[r][c] <= distanceToEnd && 
                    grid[r][c] != 'S' && 
                    grid[r][c] != 'E') {

                    // Add numeric value of the cell
                    // Assuming grid contains digits for valid cells
                    result += grid[r][c] - '0';
                }
            }
        }

        System.out.println(result);
    }

    /**
     * Performs Breadth-First Search starting from a given point to calculate
     * shortest path distances to all reachable cells in the grid.
     */
    private static void bfs(int startR, int startC, int rows, int cols, char[][] grid, int[][] distances) {
        Queue<Point> queue = new ArrayDeque<>();

        // Start BFS from End position
        queue.offer(new Point(startR, startC));
        distances[startR][startC] = 0;

        // Direction vectors: Up, Right, Left, Down
        int[] dr = {-1, 0, 0, 1};
        int[] dc = {0, 1, -1, 0};

        while (!queue.isEmpty()) {
            Point current = queue.poll();
            int r = current.r;
            int c = current.c;

            for (int i = 0; i < 4; i++) {
                int nr = r + dr[i];
                int nc = c + dc[i];

                // Check bounds
                if (isValid(nr, nc, rows, cols)) {
                    // Check if unvisited and not a Trap ('T')
                    if (distances[nr][nc] == -1 && grid[nr][nc] != 'T') {
                        distances[nr][nc] = 1 + distances[r][c];
                        queue.offer(new Point(nr, nc));
                    }
                }
            }
        }
    }

    private static boolean isValid(int r, int c, int rows, int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    // FastScanner utility class for efficient input reading
    private static class FastScanner {
        BufferedReader br;
        StringTokenizer st;

        public FastScanner(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
            st = new StringTokenizer("");
        }

        public String next() throws IOException {
            while (!st.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) return null;
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

        public int nextInt() throws IOException {
            String s = next();
            if (s == null) throw new IOException("Unexpected end of input");
            return Integer.parseInt(s);
        }
    }
}

import java.io.*;
import java.util.*;

public class Main {
    // Direction vectors for BFS (Down, Right, Up, Left)
    private static final int[] DR = {1, 0, -1, 0};
    private static final int[] DC = {0, 1, 0, -1};

    /**
     * Immutable point representation for grid coordinates.
     */
    private static class Point {
        final int r, c;
        Point(int r, int c) { this.r = r; this.c = c; }
    }

    /**
     * Fast input reader with tokenization support.
     */
    private static class InputReader implements AutoCloseable {
        private final BufferedReader br;
        private StringTokenizer st;

        InputReader(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        String next() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) return null;
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

        int nextInt() throws IOException {
            String s = next();
            if (s == null) throw new EOFException("Unexpected end of input");
            return Integer.parseInt(s);
        }

        @Override
        public void close() throws IOException {
            br.close();
        }
    }

    /**
     * Encapsulates grid processing logic. Follows Single Responsibility Principle.
     */
    private static class GridSolver {
        private final int rows, cols;
        private final char[][] grid;
        private final int[][] distances;
        private final boolean[][] visited;

        GridSolver(int rows, int cols) {
            this.rows = rows;
            this.cols = cols;
            this.grid = new char[rows][];
            this.distances = new int[rows][cols];
            this.visited = new boolean[rows][cols];
        }

        void readInput(InputReader reader) throws IOException {
            for (int i = 0; i < rows; i++) {
                String line = reader.next();
                if (line != null) {
                    grid[i] = line.toCharArray();
                }
                Arrays.fill(distances[i], -1);
            }
        }

        /**
         * Performs BFS from the starting point to calculate shortest distances
         * to all reachable cells, avoiding 'T' (obstacles).
         */
        void bfs(Point start) {
            Queue<Point> queue = new ArrayDeque<>();
            queue.add(start);
            visited[start.r][start.c] = true;
            distances[start.r][start.c] = 0;

            while (!queue.isEmpty()) {
                Point current = queue.poll();
                for (int d = 0; d < 4; d++) {
                    int nr = current.r + DR[d];
                    int nc = current.c + DC[d];

                    if (isValid(nr, nc) && grid[nr][nc] != 'T' && !visited[nr][nc]) {
                        visited[nr][nc] = true;
                        distances[nr][nc] = distances[current.r][current.c] + 1;
                        queue.add(new Point(nr, nc));
                    }
                }
            }
        }

        private boolean isValid(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }

        private boolean isBattleCell(char c) {
            return c >= '1' && c <= '9';
        }

        /**
         * Orchestrates the solving process: reads input, runs BFS, calculates result.
         */
        void solve(InputReader reader, PrintWriter out) throws IOException {
            readInput(reader);

            Point startE = findCharacter('E');
            if (startE == null) {
                out.println(0);
                return;
            }

            bfs(startE);

            Point startS = findCharacter('S');
            int stepsToS = (startS != null) ? distances[startS.r][startS.c] : -1;

            int battleCount = 0;
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (isBattleCell(grid[r][c]) && distances[r][c] >= 0 && distances[r][c] <= stepsToS) {
                        battleCount += grid[r][c] - '0';
                    }
                }
            }

            out.println(battleCount);
        }

        private Point findCharacter(char target) {
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] == target) {
                        return new Point(r, c);
                    }
                }
            }
            return null;
        }
    }

    public static void main(String[] args) throws IOException {
        // try-with-resources ensures proper cleanup of I/O streams
        try (InputReader reader = new InputReader(System.in);
             PrintWriter out = new PrintWriter(System.out)) {

            int rows = reader.nextInt();
            int cols = reader.nextInt();

            GridSolver solver = new GridSolver(rows, cols);
            solver.solve(reader, out);
        }
    }
}

import java.io.IOException;
import java.io.PrintWriter;
import java.util.ArrayDeque;
import java.util.Arrays;
import java.util.Queue;
import java.util.Scanner;

public class ProblemB {

    private static final int[] DELTA_X = {1, 0, -1, 0};
    private static final int[] DELTA_Y = {0, 1, 0, -1};

    private static final char START_CHAR = 'S';
    private static final char END_CHAR = 'E';
    private static final char TRAP_CHAR = 'T';

    public static void main(String[] args) {
        try (Scanner in = new Scanner(System.in);
             PrintWriter out = new PrintWriter(System.out)) {

            int rows = in.nextInt();
            int cols = in.nextInt();

            int[][] grid = new int[rows][cols];
            int startX = -1, startY = -1;
            int endX = -1, endY = -1;

            for (int i = 0; i < rows; i++) {
                String line = in.next();
                for (int j = 0; j < cols; j++) {
                    char cell = line.charAt(j);
                    switch (cell) {
                        case START_CHAR:
                            startX = j;
                            startY = i;
                            break;
                        case END_CHAR:
                            endX = j;
                            endY = i;
                            break;
                        case TRAP_CHAR:
                            grid[i][j] = -1; // Obstacle
                            break;
                        default:
                            if (Character.isDigit(cell)) {
                                grid[i][j] = Character.getNumericValue(cell);
                            }
                            break;
                    }
                }
            }

            int result = calculateTotalBattles(grid, startX, startY, endX, endY);
            out.println(result);
        }
        out.flush();
    }

    private static int calculateTotalBattles(int[][] grid, int startX, int startY, int endX, int endY) {
        int rows = grid.length;
        int cols = grid[0].length;

        // Maximum possible BFS depth in an unweighted grid is rows * cols
        int[] battlePointsPerStep = new int[rows * cols];

        Queue<Node> queue = new ArrayDeque<>();
        queue.add(new Node(endX, endY, 0));

        boolean[][] visited = new boolean[rows][cols];
        visited[endY][endX] = true;

        int shortestPathDistance = -1;

        while (!queue.isEmpty()) {
            Node current = queue.poll();
            int x = current.x;
            int y = current.y;
            int time = current.time;

            if (x == startX && y == startY) {
                shortestPathDistance = time;
            }

            // Accumulate battle points for the current time step
            if (grid[y][x] > 0) {
                battlePointsPerStep[time] += grid[y][x];
            }

            for (int d = 0; d < 4; d++) {
                int nextX = x + DELTA_X[d];
                int nextY = y + DELTA_Y[d];

                if (isValid(nextX, nextY, rows, cols) && grid[nextY][nextX] != -1 && !visited[nextY][nextX]) {
                    visited[nextY][nextX] = true;
                    queue.add(new Node(nextX, nextY, time + 1));
                }
            }
        }

        // Safety check for unreachable start position
        if (shortestPathDistance == -1) {
            return 0;
        }

        int totalBattles = 0;
        for (int t = 0; t <= shortestPathDistance; t++) {
            totalBattles += battlePointsPerStep[t];
        }

        return totalBattles;
    }

    private static boolean isValid(int x, int y, int rows, int cols) {
        return x >= 0 && x < cols && y >= 0 && y < rows;
    }

    /**
     * Lightweight state holder for BFS traversal.
     */
    private static class Node {
        final int x, y, time;

        Node(int x, int y, int time) {
            this.x = x;
            this.y = y;
            this.time = time;
        }
    }

    public static void debug(Object... o) {
        System.err.println(Arrays.deepToString(o));
    }
}

import java.io.*;
