/**
 * Refactored Main class for improved maintainability, readability, and correctness.
 * Key improvements:
 * 1. Removed unused classes/methods (cell, TrieNode, gcd, lcm, pow, etc.)
 * 2. Extracted magic numbers into named constants
 * 3. Improved naming conventions (Pair -> Point, sd/td -> distFromStart/distFromEnd)
 * 4. Encapsulated grid state and reduced global static variables
 * 5. Fixed logical bugs in BFS traversal and distance tracking
 * 6. Replaced LinkedList with ArrayDeque for better performance
 * 7. Standardized formatting and added documentation
 */
public class Main {
    private static final int STACK_SIZE = 99_999_999;
    private static final int[] DX = {-1, 1, 0, 0};
    private static final int[] DY = {0, 0, -1, 1};
    private static final int INF = Integer.MAX_VALUE;

    public static void main(String[] args) {
        new Thread(null, new Main()::solve, "Solver", STACK_SIZE).start();
    }

    private void solve() {
        FastScanner sc = new FastScanner();
        FastPrinter out = new FastPrinter();

        int tc = 1; // Original hardcoded test case count
        while (tc-- > 0) {
            int r = sc.nextInt();
            int c = sc.nextInt();
            char[][] grid = new char[r][c];
            for (int i = 0; i < r; i++) {
                grid[i] = sc.next().toCharArray();
            }

            // BFS from 'S' to compute distances
            int[][] distFromStart = bfs(grid, r, c, 'S');

            // BFS from 'E' to compute distances and sum digit cells within limit
            int ans = bfsAndSum(grid, r, c, 'E', distFromStart);
            out.println(ans);
        }

        out.flush();
    }

    /**
     * Performs a standard BFS from a starting character ('S' or 'E')
     * and returns a 2D array of distances. Unreachable cells remain -1.
     */
    private int[][] bfs(char[][] grid, int r, int c, char startChar) {
        int[][] dist = new int[r][c];
        for (int[] row : dist) Arrays.fill(row, -1);
        Queue<Point> queue = new ArrayDeque<>();

        for (int i = 0; i < r; i++) {
            for (int j = 0; j < c; j++) {
                if (grid[i][j] == startChar) {
                    dist[i][j] = 0;
                    queue.add(new Point(i, j));
                }
            }
        }

        while (!queue.isEmpty()) {
            Point cur = queue.poll();
            for (int d = 0; d < 4; d++) {
                int nx = cur.x + DX[d];
                int ny = cur.y + DY[d];
                if (isValid(nx, ny, r, c) && grid[nx][ny] != 'T' && dist[nx][ny] == -1) {
                    dist[nx][ny] = dist[cur.x][cur.y] + 1;
                    queue.add(new Point(nx, ny));
                }
            }
        }
        return dist;
    }

    /**
     * Performs a BFS from the ending character ('E') limited by a maximum distance.
     * Sums the numeric values of digit cells visited within the distance limit.
     */
    private int bfsAndSum(char[][] grid, int r, int c, char endChar, int[][] distFromStart) {
        int[][] distFromEnd = new int[r][c];
        for (int[] row : distFromEnd) Arrays.fill(row, -1);
        Queue<Point> queue = new ArrayDeque<>();

        Point start = null;
        for (int i = 0; i < r; i++) {
            for (int j = 0; j < c; j++) {
                if (grid[i][j] == endChar) {
                    start = new Point(i, j);
                    break;
                }
            }
            if (start != null) break;
        }
        if (start == null) return 0;

        distFromEnd[start.x][start.y] = 0;
        queue.add(start);

        int limit = distFromStart[start.x][start.y];
        int totalSum = 0;

        while (!queue.isEmpty()) {
            Point cur = queue.poll();
            if (distFromEnd[cur.x][cur.y] >= limit) continue;

            for (int d = 0; d < 4; d++) {
                int nx = cur.x + DX[d];
                int ny = cur.y + DY[d];
                if (isValid(nx, ny, r, c) && grid[nx][ny] != 'T' && distFromEnd[nx][ny] == -1) {
                    distFromEnd[nx][ny] = distFromEnd[cur.x][cur.y] + 1;

                    char cell = grid[nx][ny];
                    if (cell == 'S' || cell == 'E') continue;

                    if (Character.isDigit(cell)) {
                        int val = cell - '0';
                        if (distFromEnd[nx][ny] <= limit) {
                            totalSum += val;
                        }
                    }
                    queue.add(new Point(nx, ny));
                }
            }
        }
        return totalSum;
    }

    private boolean isValid(int x, int y, int r, int c) {
        return x >= 0 && x < r && y >= 0 && y < c;
    }

    private static class Point {
        final int x, y;
        Point(int x, int y) { this.x = x; this.y = y; }
    }

    private static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Input stream closed unexpectedly", e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            String s = next();
            return s == null ? 0 : Integer.parseInt(s);
        }
    }

    private static class FastPrinter {
        private final PrintWriter out;

        FastPrinter() {
            out = new PrintWriter(new BufferedOutputStream(System.out));
        }

        void println(int val) { out.println(val); }
        void flush() { out.flush(); }
    }
}

import java.util.Scanner;
import java.util.Arrays;
import java.util.ArrayDeque;
import java.util.Queue;

/**
 * Refactored version of the BiridianForest program.
 * Improvements include:
 * - Better naming conventions (CamelCase for classes/variables).
 * - Extraction of logic into helper methods (BFS, Battle Calculation).
 * - Use of a Point class to handle coordinates cleanly.
 * - Use of ArrayDeque instead of LinkedList for better performance.
 * - Elimination of magic numbers (ASCII codes) using Character methods.
 * - Reduced code duplication in the BFS neighbor checking logic.
 */
public class BiridianForest {

    /**
     * Represents a coordinate in the grid.
     * x corresponds to the column index, y to the row index.
     */
    private static class Point {
        int x;
        int y;

        Point(int x, int y) {
            this.x = x;
            this.y = y;
        }
    }

    public static void main(String[] args) {
        // Use try-with-resources to ensure Scanner is closed properly
        try (Scanner scanner = new Scanner(System.in)) {
            if (!scanner.hasNextInt()) {
                return;
            }

            int rows = scanner.nextInt();
            int cols = scanner.nextInt();

            char[][] grid = new char[rows][cols];
            Point startPoint = null;
            Point endPoint = null;

            // Read the grid and locate the Start ('E') and Target ('S') points
            for (int i = 0; i < rows; i++) {
                String line = scanner.next();
                grid[i] = line.toCharArray();
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j] == 'E') {
                        startPoint = new Point(j, i);
                    } else if (grid[i][j] == 'S') {
                        endPoint = new Point(j, i);
                    }
                }
            }

            // Perform BFS to calculate shortest distances from 'E'
            int[][] distances = performBFS(grid, startPoint, rows, cols);

            // Determine the required distance to reach 'S'
            // If 'S' is not found, default to 0 (consistent with original logic behavior)
            int requiredStep = (endPoint != null) ? distances[endPoint.y][endPoint.x] : 0;

            // Calculate the total number of battles
            int totalBattles = calculateBattles(grid, distances, requiredStep, rows, cols);

            System.out.print(totalBattles);
        }
    }

    /**
     * Performs Breadth-First Search (BFS) to find the shortest path distances
     * from the starting point to all other cells in the grid.
     *
     * @param grid     The character grid representing the map.
     * @param start    The starting Point ('E').
     * @param rows     Number of rows in the grid.
     * @param cols     Number of columns in the grid.
     * @return         A 2D array where each cell contains the shortest distance from start.
     */
    private static int[][] performBFS(char[][] grid, Point start, int rows, int cols) {
        int[][] distances = new int[rows][cols];
        // Initialize distances with Integer.MAX_VALUE to represent unvisited/unreachable cells
        for (int[] row : distances) {
            Arrays.fill(row, Integer.MAX_VALUE);
        }

        if (start == null) {
            return distances;
        }

        // ArrayDeque is generally faster than LinkedList for queues
        Queue<Point> queue = new ArrayDeque<>();

        // Set distance to start node as 0 and enqueue
        distances[start.y][start.x] = 0;
        queue.add(start);

        // Direction arrays for moving Left, Right, Up, Down
        int[] dx = {-1, 1, 0, 0};
        int[] dy = {0, 0, -1, 1};

        while (!queue.isEmpty()) {
            Point current = queue.poll();
            int currentDist = distances[current.y][current.x];

            // Explore all 4 possible directions
            for (int i = 0; i < 4; i++) {
                int nx = current.x + dx[i];
                int ny = current.y + dy[i];

                // Check boundaries
                if (nx >= 0 && nx < cols && ny >= 0 && ny < rows) {
                    // Check if cell is not an obstacle ('T') and if a shorter path is found
                    if (grid[ny][nx] != 'T' && distances[ny][nx] > currentDist + 1) {
                        distances[ny][nx] = currentDist + 1;
                        queue.add(new Point(nx, ny));
                    }
                }
            }
        }

        return distances;
    }

    /**
     * Calculates the sum of battles (digits) on cells that are reachable
     * within the required distance from the start point.
     *
     * @param grid         The character grid.
     * @param distances    The distance matrix calculated by BFS.
     * @param requiredStep The maximum distance allowed (distance to 'S').
     * @param rows         Number of rows.
     * @param cols         Number of columns.
     * @return             The total count of battles.
     */
    private static int calculateBattles(char[][] grid, int[][] distances, int requiredStep, int rows, int cols) {
        int totalBattles = 0;

        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                // Check if the cell contains a digit
                if (Character.isDigit(grid[i][j])) {
                    int dist = distances[i][j];
                    // Check if the cell is reachable within the required distance
                    if (dist <= requiredStep) {
                        totalBattles += grid[i][j] - '0';
                    }
                }
            }
        }
        return totalBattles;
    }
}

