public class TicketCostCalculator {
    // Constants for grid characters to improve readability and maintainability
    private static final char WALL = 'T';
    private static final char START = 'S';
    private static final char END = 'E';

    // Instance fields replace static globals, enabling state isolation and testability
    private final int rows;
    private final int cols;
    private final char[][] grid;
    private final int[][] distances;
    private final FastScanner scanner;
    private final PrintWriter writer;

    // Immutable value class for grid coordinates and associated data
    private static class Point {
        final int x, y;
        final int cost;

        Point(int x, int y, int cost) {
            this.x = x;
            this.y = y;
            this.cost = cost;
        }
    }

    public static void main(String[] args) {
        // Use buffered I/O for performance
        FastScanner in = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out));
        try {
            new TicketCostCalculator(in, out).solve();
        } catch (Exception e) {
            e.printStackTrace();
        } finally {
            out.flush();
        }
    }

    private TicketCostCalculator(FastScanner scanner, PrintWriter writer) {
        this.scanner = scanner;
        this.writer = writer;
        this.rows = scanner.nextInt();
        this.cols = scanner.nextInt();
        this.grid = new char[rows][cols];
        this.distances = new int[rows][cols];
        // Initialize distances to -1 (representing unvisited/unreachable)
        for (int[] row : distances) {
            Arrays.fill(row, -1);
        }
    }

    public void solve() {
        Point startPoint = null;
        Point endPoint = null;
        List<Point> ticketLocations = new ArrayList<>();

        // Parse the grid and identify key locations
        for (int i = 0; i < rows; i++) {
            String line = scanner.next();
            for (int j = 0; j < cols; j++) {
                char ch = line.charAt(j);
                grid[i][j] = ch;
                if (ch == START) {
                    startPoint = new Point(i, j, 0);
                } else if (ch == END) {
                    endPoint = new Point(i, j, 0);
                } else if (Character.isDigit(ch)) {
                    ticketLocations.add(new Point(i, j, ch - '0'));
                }
            }
        }

        // Run BFS from the entertainment center to compute shortest paths to all reachable cells
        bfs(endPoint);

        int distanceToStart = distances[startPoint.x][startPoint.y];
        long totalMinCost = 0;

        // Calculate total cost considering round trips (distance * 2 + ticket * 2)
        for (Point ticket : ticketLocations) {
            int distFromEnd = distances[ticket.x][ticket.y];
            // Only consider tickets that lie on or before the shortest path to the start
            if (distFromEnd != -1 && distFromEnd <= distanceToStart) {
                totalMinCost += (long) ticket.cost * 2;
            }
        }

        writer.println(totalMinCost);
    }

    // Checks boundaries and wall constraints
    private boolean isValid(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols && grid[r][c] != WALL;
    }

    // Standard BFS to find shortest path distances in an unweighted grid
    private void bfs(Point start) {
        int[] dx = {1, -1, 0, 0};
        int[] dy = {0, 0, -1, 1};
        Queue<Point> queue = new ArrayDeque<>();
        queue.add(start);
        distances[start.x][start.y] = 0;

        while (!queue.isEmpty()) {
            Point current = queue.poll();

            // Note: The original code contained `if(mat[pop.x][pop.y] == '*') continue;`
            // This was dead code as '*' is never present in the input. Removed for clarity.

            for (int i = 0; i < 4; i++) {
                int nx = current.x + dx[i];
                int ny = current.y + dy[i];
                if (isValid(nx, ny) && distances[nx][ny] == -1) {
                    distances[nx][ny] = distances[current.x][current.y] + 1;
                    queue.add(new Point(nx, ny, 0));
                }
            }
        }
    }

    // High-performance input reader for competitive programming / large inputs
    private static class FastScanner {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastScanner(InputStream stream) {
            this.reader = new BufferedReader(new InputStreamReader(stream));
            this.tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            String s = next();
            if (s == null) throw new RuntimeException("Unexpected end of input");
            return Integer.parseInt(s);
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Analyzes a grid to find the shortest path between 'S' and 'E',
 * then counts numeric characters reachable within that distance from 'E'.
 */
public class GridPathAnalyzer {

    /** Simple immutable coordinate class to replace magic number encoding */
    private static class Point {
        final int row;
        final int col;

        Point(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    /**
     * Performs BFS to find the shortest distance from start to end,
     * avoiding cells marked with 'T'.
     *
     * @return shortest distance, or -1 if unreachable
     */
    private int findShortestDistance(char[][] grid, int startRow, int startCol, 
                                     int endRow, int endCol, int rows, int cols) {
        if (grid[startRow][startCol] == 'T' || grid[endRow][endCol] == 'T') {
            return -1;
        }

        int[][] distances = new int[rows][cols];
        for (int[] row : distances) {
            Arrays.fill(row, -1);
        }

        Queue<Point> queue = new ArrayDeque<>();
        queue.add(new Point(startRow, startCol));
        distances[startRow][startCol] = 0;

        // Direction vectors: Up, Down, Left, Right
        int[] dr = {-1, 1, 0, 0};
        int[] dc = {0, 0, -1, 1};

        while (!queue.isEmpty()) {
            Point current = queue.poll();

            if (current.row == endRow && current.col == endCol) {
                return distances[current.row][current.col];
            }

            for (int i = 0; i < 4; i++) {
                int nr = current.row + dr[i];
                int nc = current.col + dc[i];

                if (nr >= 0 && nr < rows && nc >= 0 && nc < cols
                        && distances[nr][nc] == -1
                        && grid[nr][nc] != 'T') {

                    distances[nr][nc] = distances[current.row][current.col] + 1;
                    queue.add(new Point(nr, nc));
                }
            }
        }
        return -1; // Target is unreachable
    }

    /**
     * Performs a bounded BFS from the start point up to a maximum distance.
     * Counts the numeric values of reachable cells, ignoring 'T', 'S', and 'E'.
     */
    private int countNumbersWithinDistance(char[][] grid, int startRow, int startCol, 
                                           int rows, int cols, int maxDistance) {
        if (maxDistance < 0) {
            return 0;
        }

        int count = 0;
        int[][] distances = new int[rows][cols];
        for (int[] row : distances) {
            Arrays.fill(row, -1);
        }

        Queue<Point> queue = new ArrayDeque<>();
        queue.add(new Point(startRow, startCol));
        distances[startRow][startCol] = 0;

        int[] dr = {-1, 1, 0, 0};
        int[] dc = {0, 0, -1, 1};

        while (!queue.isEmpty()) {
            Point current = queue.poll();

            for (int i = 0; i < 4; i++) {
                int nr = current.row + dr[i];
                int nc = current.col + dc[i];

                if (nr >= 0 && nr < rows && nc >= 0 && nc < cols
                        && distances[nr][nc] == -1
                        && distances[current.row][current.col] + 1 <= maxDistance) {

                    distances[nr][nc] = distances[current.row][current.col] + 1;
                    char cell = grid[nr][nc];

                    // Only count digits; skip special markers
                    if (cell != 'T' && cell != 'S' && cell != 'E') {
                        if (cell >= '0' && cell <= '9') {
                            count += cell - '0';
                        }
                        queue.add(new Point(nr, nc));
                    }
                }
            }
        }
        return count;
    }

    public static void main(String[] args) {
        FastScanner in = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            int rows = in.nextInt();
            int cols = in.nextInt();
            char[][] grid = new char[rows][cols];
            int startRow = 0, startCol = 0, endRow = 0, endCol = 0;

            for (int i = 0; i < rows; i++) {
                String line = in.next();
                for (int j = 0; j < cols; j++) {
                    grid[i][j] = line.charAt(j);
                    if (grid[i][j] == 'S') {
                        startRow = i;
                        startCol = j;
                    } else if (grid[i][j] == 'E') {
                        endRow = i;
                        endCol = j;
                    }
                }
            }

            GridPathAnalyzer solver = new GridPathAnalyzer();
            int shortestDist = solver.findShortestDistance(grid, startRow, startCol, endRow, endCol, rows, cols);

            if (shortestDist == -1) {
                out.println(0);
            } else {
                // Count digits reachable from 'E' within the shortest path distance
                int count = solver.countNumbersWithinDistance(grid, endRow, endCol, rows, cols, shortestDist);
                out.println(count);
            }
        } catch (Exception e) {
            // Graceful fallback for malformed input in competitive programming context
            out.println(0);
        } finally {
            out.flush();
        }
    }

    /**
     * High-performance scanner for competitive programming input.
     */
    static class FastScanner {
        private final InputStream stream;
        private final byte[] buf = new byte[8192];
        private int curChar, numChars;
        private SpaceCharFilter filter;

        public FastScanner(InputStream stream) {
            this.stream = stream;
        }

        public int read() {
            if (numChars == -1) {
                throw new InputMismatchException();
            }
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0) {
                    return -1;
                }
            }
            return buf[curChar++];
        }

        public int nextInt() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                res *= 10;
                res += c - '0';
                c = read();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public String next() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            StringBuilder res = new StringBuilder();
            do {
                res.appendCodePoint(c);
                c = read();
            } while (!isSpaceChar(c));
            return res.toString();
        }

        public boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        public interface SpaceCharFilter {
            boolean isSpaceChar(int ch);
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.util.ArrayDeque;
import java.util.Arrays;
import java.util.StringTokenizer;

/**
 * Refactored solution for grid pathfinding.
 * 
 * Original Logic Summary:
 * 1. Reads a grid with Start ('S'), End ('E'), and Walls ('T').
 * 2. Performs BFS starting from 'E' to compute shortest distances to all cells.
 * 3. Sums the integer values of digits located in cells reachable from 'S' 
 *    within the distance threshold defined by the path from 'E' to 'S'.
 */
public class GridPathSolver {

    // Constants
    private static final int INF = Integer.MAX_VALUE;
    // Direction vectors: Right, Down, Left, Up
    private static final int[] DELTA_X = {0, 1, 0, -1};
    private static final int[] DELTA_Y = {1, 0, -1, 0};

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner(System.in);

        // Read grid dimensions
        int n = scanner.nextInt();
        int m = scanner.nextInt();

        // Read grid content
        char[][] grid = new char[n][];
        for (int i = 0; i < n; i++) {
            String rowStr = scanner.next();
            if (rowStr != null) {
                grid[i] = rowStr.trim().toCharArray();
            } else {
                grid[i] = new char[0];
            }
        }

        // Locate Start ('S') and End ('E') coordinates
        Point startPoint = new Point(0, 0);
        Point endPoint = new Point(0, 0);
        boolean foundStart = false;
        boolean foundEnd = false;

        for (int i = 0; i < n; i++) {
            // Safe iteration over potentially jagged array or null rows
            int rowLen = (grid[i] != null) ? grid[i].length : 0;
            for (int j = 0; j < rowLen; j++) {
                char cell = grid[i][j];
                if (cell == 'S') {
                    startPoint = new Point(i, j);
                    foundStart = true;
                } else if (cell == 'E') {
                    endPoint = new Point(i, j);
                    foundEnd = true;
                }
            }
        }

        // If Start or End is missing, result is 0
        if (!foundStart || !foundEnd) {
            System.out.println(0);
            return;
        }

        // Initialize distance matrix
        int[][] distances = new int[n][m];
        for (int[] row : distances) {
            Arrays.fill(row, INF);
        }

        // BFS Initialization
        ArrayDeque<Point> queue = new ArrayDeque<>();

        // BFS starts from 'E' (End point)
        distances[endPoint.x][endPoint.y] = 0;
        queue.add(endPoint);

        // Execute BFS
        while (!queue.isEmpty()) {
            Point current = queue.poll();

            // Explore neighbors
            for (int i = 0; i < 4; i++) {
                int nx = current.x + DELTA_X[i];
                int ny = current.y + DELTA_Y[i];

                // Boundary checks
                if (nx < 0 || nx >= n || ny < 0 || ny >= m) {
                    continue;
                }

                // Wall check: 'T' is an obstacle
                if (grid[nx][ny] == 'T') {
                    continue;
                }

                // Distance update
                // Using comparison to maintain original logic, though BFS typically checks for unvisited (INF)
                if (distances[nx][ny] > distances[current.x][current.y] + 1) {
                    distances[nx][ny] = distances[current.x][current.y] + 1;
                    queue.add(new Point(nx, ny));
                }
            }
        }

        // Calculate result
        // Threshold is the distance from 'E' to 'S'
        int threshold = distances[startPoint.x][startPoint.y];
        int sum = 0;

        for (int i = 0; i < n; i++) {
            int rowLen = (grid[i] != null) ? grid[i].length : 0;
            for (int j = 0; j < rowLen; j++) {
                char cell = grid[i][j];

                // Sum digits if they are within the distance threshold
                if (Character.isDigit(cell) && distances[i][j] <= threshold) {
                    sum += cell - '0';
                }
            }
        }

        System.out.println(sum);
    }

    /**
     * Helper class to store grid coordinates.
     */
    private static class Point {
        int x;
        int y;

        Point(int x, int y) {
            this.x = x;
            this.y = y;
        }
    }

    /**
     * FastScanner for efficient input processing.
     */
    static class FastScanner {
        BufferedReader br;
        StringTokenizer st;

        public FastScanner(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        private void scanLine() {
            try {
                String line = br.readLine();
                if (line != null) {
                    st = new StringTokenizer(line.trim());
                }
            } catch (IOException e) {
                throw new RuntimeException("Error reading input", e);
            }
        }

        public String next() {
            while (st == null || !st.hasMoreTokens()) {
                scanLine();
                if (st == null) {
                    return null;
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            String s = next();
            if (s == null) throw new RuntimeException("Unexpected end of input");
            return Integer.parseInt(s);
        }

        public long nextLong() {
            String s = next();
            if (s == null) throw new RuntimeException("Unexpected end of input");
            return Long.parseLong(s);
        }

        public double nextDouble() {
            String s = next();
            if (s == null) throw new RuntimeException("Unexpected end of input");
            return Double.parseDouble(s);
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.ArrayDeque;
import java.util.Queue;
import java.util.StringTokenizer;

public class Main {

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter out = new PrintWriter(System.out);

        // Read grid dimensions, skipping potential empty leading lines
        String line = br.readLine();
        while (line != null && line.trim().isEmpty()) {
            line = br.readLine();
        }
        if (line == null) {
            out.flush();
            return;
        }

        StringTokenizer st = new StringTokenizer(line);
        int rows = Integer.parseInt(st.nextToken());
        int cols = Integer.parseInt(st.nextToken());

        // -1: unvisited, -2: blocked ('T'), >=0: distance from 'E'
        int[][] distance = new int[rows][cols];
        int[][] values = new int[rows][cols];
        int startR = 0, startC = 0, endR = 0, endC = 0;

        // Parse the grid
        for (int i = 0; i < rows; i++) {
            String row = br.readLine();
            while (row != null && row.isEmpty()) { // Skip blank lines if any
                row = br.readLine();
            }
            for (int j = 0; j < cols; j++) {
                distance[i][j] = -1; // Mark as unvisited
                char c = row.charAt(j);
                if (c == 'T') {
                    distance[i][j] = -2; // Blocked cell
                } else if (c == 'S') {
                    startR = i;
                    startC = j;
                } else if (c == 'E') {
                    endR = i;
                    endC = j;
                } else {
                    values[i][j] = c - '0';
                }
            }
        }

        // BFS from 'E' to compute shortest distances to all reachable cells
        Queue<Integer> queue = new ArrayDeque<>();
        queue.add(endR * cols + endC);
        distance[endR][endC] = 0;

        int[] dr = {1, -1, 0, 0};
        int[] dc = {0, 0, 1, -1};

        int currentDist = 0;
        while (!queue.isEmpty()) {
            int levelSize = queue.size();
            for (int i = 0; i < levelSize; i++) {
                int pos = queue.poll();
                int r = pos / cols;
                int c = pos % cols;
                distance[r][c] = currentDist;

                for (int d = 0; d < 4; d++) {
                    int nr = r + dr[d];
                    int nc = c + dc[d];
                    // Check bounds and if cell is unvisited
                    if (nr >= 0 && nr < rows && nc >= 0 && nc < cols && distance[nr][nc] == -1) {
                        queue.add(nr * cols + nc);
                    }
                }
            }
            currentDist++;
        }

        // Sum values of cells within the distance from 'E' to 'S'
        int distToStart = distance[startR][startC];
        long totalSum = 0;
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (distance[i][j] != -1 && distance[i][j] <= distToStart) {
                    totalSum += values[i][j];
                }
            }
        }

        out.println(totalSum);
        out.flush();
    }
}

import java.io.*;
import java.util.*;

/**
 * Refactored MazeSolver.
 * 
 * This class solves a grid pathfinding problem using Breadth-First Search (BFS).
 * It identifies a start ('S') and end ('E') point on a grid, calculates the 
 * shortest distance from the end point to all reachable cells, and sums the 
 * numeric values of cells that are reachable within the distance of the start point.
 * 
 * Refactoring Improvements:
 * 1. Naming: Replaced generic names (B, f, dEn) with descriptive ones (MazeSolver, grid, distances).
 * 2. Structure: Separated I/O logic from algorithmic logic.
 * 3. Data Structures: Used a Point class for coordinates instead of interleaved Integers in a queue.
 * 4. Constants: Defined magic numbers and characters as named constants.
 * 5. Readability: Extracted BFS logic into a separate method and added comments.
 */
public class MazeSolver {

    // Constants
    private static final int[][] DIRECTIONS = { {-1, 0}, {0, -1}, {1, 0}, {0, 1} };
    private static final int INF = Integer.MAX_VALUE / 3;
    private static final char OBSTACLE = 'T';
    private static final char START_CHAR = 'S';
    private static final char END_CHAR = 'E';
    private static final char EMPTY_CHAR = '0';

    // I/O Fields
    private BufferedReader reader;
    private PrintWriter writer;
    private StringTokenizer tokenizer;

    /**
     * Simple Point class to store coordinates.
     */
    private static class Point {
        int x, y;
        Point(int x, int y) {
            this.x = x;
            this.y = y;
        }
    }

    public static void main(String[] args) {
        new MazeSolver().run();
    }

    public MazeSolver() {
        reader = new BufferedReader(new InputStreamReader(System.in));
        writer = new PrintWriter(System.out);
    }

    /**
     * Entry point for the solver logic.
     */
    public void run() {
        try {
            solve();
        } catch (IOException e) {
            e.printStackTrace();
        } finally {
            writer.flush();
            writer.close();
        }
    }

    private void solve() throws IOException {
        // 1. Read Grid Dimensions
        int rows = readInt();
        int cols = readInt();

        char[][] grid = new char[rows][];
        Point start = null;
        Point end = null;

        // 2. Read Grid Content and Locate Start/End Points
        for (int i = 0; i < rows; i++) {
            String line = readToken();
            if (line == null) break; 
            grid[i] = line.toCharArray();

            for (int j = 0; j < cols; j++) {
                // Safety check for row length
                if (j < grid[i].length) {
                    char cell = grid[i][j];
                    if (cell == START_CHAR) {
                        start = new Point(i, j);
                        grid[i][j] = EMPTY_CHAR; // Treat as empty space
                    } else if (cell == END_CHAR) {
                        end = new Point(i, j);
                        grid[i][j] = EMPTY_CHAR; // Treat as empty space
                    }
                }
            }
        }

        // 3. Perform BFS from the End point to calculate distances to all reachable cells
        int[][] distances = computeDistances(grid, rows, cols, end);

        // 4. Calculate the result based on distance constraints
        int ans = 0;
        // Distance from End to Start. If Start is unreachable, this is INF.
        int startDist = (start != null) ? distances[start.x][start.y] : INF;

        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (j >= grid[i].length) continue; // Safety check

                char cell = grid[i][j];

                // Condition from original code:
                // Cell must not be an obstacle ('T') and must not be empty ('0')
                if (cell != OBSTACLE && cell != EMPTY_CHAR) {
                    // Check if the cell is within the distance threshold of the Start point
                    // (i.e., closer to End than Start is)
                    if (distances[i][j] <= startDist) {
                        // Accumulate the numeric value of the character
                        ans += cell - '0';
                    }
                }
            }
        }

        writer.println(ans);
    }

    /**
     * Computes the shortest distance from the 'end' point to all other reachable cells
     * using Breadth-First Search (BFS).
     */
    private int[][] computeDistances(char[][] grid, int n, int m, Point startNode) {
        int[][] dist = new int[n][m];
        for (int[] row : dist) {
            Arrays.fill(row, INF);
        }

        Queue<Point> queue = new ArrayDeque<>();

        if (startNode != null) {
            dist[startNode.x][startNode.y] = 0;
            queue.add(startNode);
        }

        while (!queue.isEmpty()) {
            Point curr = queue.poll();

            for (int[] dir : DIRECTIONS) {
                int nx = curr.x + dir[0];
                int ny = curr.y + dir[1];

                if (isValid(nx, ny, n, m) && grid[nx][ny] != OBSTACLE) {
                    if (dist[nx][ny] > dist[curr.x][curr.y] + 1) {
                        dist[nx][ny] = dist[curr.x][curr.y] + 1;
                        queue.add(new Point(nx, ny));
                    }
                }
            }
        }
        return dist;
    }

    private boolean isValid(int x, int y, int n, int m) {
        return x >= 0 && x < n && y >= 0 && y < m;
    }

    // --- Input Parsing Methods ---

    private String readToken() throws IOException {
        while (tokenizer == null || !tokenizer.hasMoreTokens()) {
            try {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            } catch (IOException e) {
                throw e;
            }
        }
        return tokenizer.nextToken();
    }

    private int readInt() throws IOException {
        String s = readToken();
        if (s == null) throw new IOException("Unexpected end of input");
        return Integer.parseInt(s);
    }
}

