            char[][] grid = new char[rows][cols];
            int startR = -1, startC = -1;
            int endR = -1, endC = -1;

            // Parse grid and locate start/end positions
            for (int i = 0; i < rows; i++) {
                String line = in.next();
                for (int j = 0; j < cols; j++) {
                    grid[i][j] = line.charAt(j);
                    if (grid[i][j] == START_CHAR) {
                        startR = i;
                        startC = j;
                    } else if (grid[i][j] == END_CHAR) {
                        endR = i;
                        endC = j;
                    }
                }
            }

            // Compute distances from the END position to all reachable cells
            int[][] distances = computeDistancesFromEnd(grid, rows, cols, endR, endC);

            // Calculate the final answer based on distances and digit cells
            int result = calculateResult(grid, distances, rows, cols, startR, startC);

            out.println(result);
        } catch (Exception e) {
            e.printStackTrace();
        } finally {
            out.flush();
            out.close();
        }
    }

    /**
     * Performs BFS starting from the END position to compute shortest distances
     * to all reachable cells in the grid.
     */
    private static int[][] computeDistancesFromEnd(char[][] grid, int rows, int cols, int startR, int startC) {
        int[][] distances = new int[rows][cols];
        for (int[] row : distances) {
            Arrays.fill(row, UNVISITED);
        }

        if (startR == -1 || startC == -1) {
            return distances;
        }

        distances[startR][startC] = 0;
        Queue<Integer> queue = new ArrayDeque<>();
        queue.add(encodeCoordinate(startR, startC, cols));

        while (!queue.isEmpty()) {
            int current = queue.poll();
            int r = decodeRow(current, cols);
            int c = decodeCol(current, cols);
            int currentDist = distances[r][c];

            for (int[] dir : DIRECTIONS) {
                int nr = r + dir[0];
                int nc = c + dir[1];

                if (isValidPosition(nr, nc, rows, cols) &&
                    distances[nr][nc] == UNVISITED &&
                    grid[nr][nc] != WALL_CHAR) {
                    distances[nr][nc] = currentDist + 1;
                    queue.add(encodeCoordinate(nr, nc, cols));
                }
            }
        }
        return distances;
    }

    /**
     * Calculates the result by summing digits where the distance from END is 
     * less than or equal to the distance from END to START.
     */
    private static int calculateResult(char[][] grid, int[][] distances, int rows, int cols, int startR, int startC) {
        int result = 0;
        int startDist = distances[startR][startC];

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                char cell = grid[r][c];
                if (cell >= DIGIT_START && cell <= DIGIT_END && distances[r][c] > 0) {
                    int digit = cell - '0';
                    if (distances[r][c] <= startDist) {
                        result += digit;
                    }
                }
            }
        }
        return result;
    }

    // Coordinate encoding/decoding utilities to avoid object overhead in BFS queue
    private static int encodeCoordinate(int r, int c, int cols) {
        return r * cols + c;
    }

    private static int decodeRow(int encoded, int cols) {
        return encoded / cols;
    }

    private static int decodeCol(int encoded, int cols) {
        return encoded % cols;
    }

    private static boolean isValidPosition(int r, int c, int rows, int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /**
     * Fast input reader for competitive programming / large I/O.
     */
    static class InputReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            String s = next();
            return s == null ? 0 : Integer.parseInt(s);
        }

        public long nextLong() {
            String s = next();
            return s == null ? 0L : Long.parseLong(s);
        }

        public double nextDouble() {
            String s = next();
            return s == null ? 0.0 : Double.parseDouble(s);
        }
    }
}

import java.util.ArrayDeque;
import java.util.Arrays;
import java.util.Queue;
import java.util.Scanner;

/**
 * Refactored grid pathfinding solver.
 * 
 * Key Improvements:
 * 1. Fixed critical input parsing bug where boundary strings were incorrectly padded in a loop.
 * 2. Replaced magic numbers and hardcoded array sizes with dynamic allocation and constants.
 * 3. Improved naming conventions following Java standards (camelCase, descriptive names).
 * 4. Separated concerns into distinct, single-responsibility methods.
 * 5. Replaced String[] grid with char[][] for better memory usage and mutability.
 * 6. Cleaned up BFS implementation by decoding coordinates cleanly and using a proper distance constant.
 * 7. Added resource management for Scanner using try-with-resources.
 * 8. Added safety checks for missing start/end markers.
 */
public class Main {

    private static final int[] DR = {-1, 1, 0, 0};
    private static final int[] DC = {0, 0, -1, 1};
    private static final int INF = 1_000_000_000;

    private int rows;
    private int cols;
    private int paddedRows;
    private int paddedCols;
    private char[][] grid;
    private int[][] distances;
    private int startRow, startCol, endRow, endCol;

    public void run() {
        try (Scanner scanner = new Scanner(System.in)) {
            if (!scanner.hasNextInt()) return;

            rows = scanner.nextInt();
            cols = scanner.nextInt();
            scanner.nextLine(); // Consume the newline after dimensions

            paddedRows = rows + 2;
            paddedCols = cols + 2;

            grid = new char[paddedRows][paddedCols];
            distances = new int[paddedRows][paddedCols];

            initializeGrid(scanner);
            locateSpecialCells();

            // Guard against missing 'S' or 'E' markers
            if (startRow == 0 || endRow == 0) {
                System.out.println(0);
                return;
            }

            bfsFromEnd();
            System.out.println(calculateResult());
        }
    }

    private void initializeGrid(Scanner scanner) {
        // Initialize all boundaries with 'T' (walls/obstacles)
        for (int i = 0; i < paddedRows; i++) {
            Arrays.fill(grid[i], 'T');
        }

        // Read the actual grid rows and place them in the padded grid
        for (int i = 1; i <= rows; i++) {
            String line = scanner.nextLine().trim();
            for (int j = 0; j < line.length() && j < cols; j++) {
                grid[i][j + 1] = line.charAt(j);
            }
        }
    }

    private void locateSpecialCells() {
        for (int i = 1; i <= rows; i++) {
            for (int j = 1; j <= cols; j++) {
                char cell = grid[i][j];
                if (cell == 'S') {
                    startRow = i;
                    startCol = j;
                } else if (cell == 'E') {
                    endRow = i;
                    endCol = j;
                }
                distances[i][j] = INF;
            }
        }
    }

    private void bfsFromEnd() {
        Queue<Integer> queue = new ArrayDeque<>();
        // Encode 2D coordinates into a single integer for efficient queue storage
        queue.add(endRow * paddedCols + endCol);
        distances[endRow][endCol] = 0;

        while (!queue.isEmpty()) {
            int pos = queue.poll();
            int r = pos / paddedCols;
            int c = pos % paddedCols;
            int currentDist = distances[r][c];

            for (int k = 0; k < 4; k++) {
                int nr = r + DR[k];
                int nc = c + DC[k];

                // Boundaries are 'T', so implicit bounds check. 
                // Check if not a wall and if a shorter path is found.
                if (grid[nr][nc] != 'T' && distances[nr][nc] > currentDist + 1) {
                    distances[nr][nc] = currentDist + 1;
                    queue.add(nr * paddedCols + nc);
                }
            }
        }
    }

    private int calculateResult() {
        int total = 0;
        int endToStartDist = distances[startRow][startCol];

        for (int i = 1; i <= rows; i++) {
            for (int j = 1; j <= cols; j++) {
                char cell = grid[i][j];
                // Sum digits that are reachable from 'E' within the distance to 'S'
                if (cell >= '0' && cell <= '9' && distances[i][j] <= endToStartDist) {
                    total += cell - '0';
                }
            }
        }
        return total;
    }

    public static void main(String[] args) {
        new Main().run();
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.ArrayDeque;
import java.util.Queue;
import java.util.StringTokenizer;

public class ProblemC {

    private static final int[] DR = {-1, 0, 1, 0};
    private static final int[] DC = {0, 1, 0, -1};
    private static final char START = 'S';
    private static final char END = 'E';
    private static final char OBSTACLE = 'T';

    public static void main(String[] args) throws IOException {
        // Use try-with-resources for automatic and safe resource management
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
             PrintWriter out = new PrintWriter(System.out)) {

            FastReader scanner = new FastReader(br);
            int n = scanner.nextInt();
            int m = scanner.nextInt();

            char[][] grid = new char[n][];
            int startR = 0, startC = 0, endR = 0, endC = 0;

            // Read grid and locate start/end positions
            for (int i = 0; i < n; i++) {
                grid[i] = scanner.next().toCharArray();
                for (int j = 0; j < m; j++) {
                    if (grid[i][j] == START) {
                        startR = i;
                        startC = j;
                    } else if (grid[i][j] == END) {
                        endR = i;
                        endC = j;
                    }
                }
            }

            // Perform BFS from END to compute shortest distances to all reachable cells
            int[][] dist = bfs(grid, n, m, endR, endC);

            // Calculate the sum of digits within the shortest path distance from END to START
            int result = calculateResult(grid, dist, n, m, startR, startC);

            out.println(result);
            out.flush();
        }
    }

    /**
     * Performs a Breadth-First Search from the given start position to compute
     * the shortest distance to all reachable cells.
     */
    private static int[][] bfs(char[][] grid, int n, int m, int startR, int startC) {
        int[][] dist = new int[n][m]; // 0 indicates unvisited
        Queue<BfsNode> queue = new ArrayDeque<>();

        // Initialize BFS from the END position with distance 1
        queue.add(new BfsNode(startR, startC, 1));
        dist[startR][startC] = 1;

        while (!queue.isEmpty()) {
            BfsNode current = queue.poll();

            for (int i = 0; i < 4; i++) {
                int nr = current.r + DR[i];
                int nc = current.c + DC[i];

                if (isValid(nr, nc, n, m) && dist[nr][nc] == 0 && grid[nr][nc] != OBSTACLE) {
                    dist[nr][nc] = current.dist + 1;
                    queue.add(new BfsNode(nr, nc, current.dist + 1));
                }
            }
        }
        return dist;
    }

    /**
     * Checks if the given coordinates are within the grid boundaries.
     */
    private static boolean isValid(int r, int c, int n, int m) {
        return r >= 0 && r < n && c >= 0 && c < m;
    }

    /**
     * Sums the numeric values of all digit cells that are reachable from END
     * and have a distance less than or equal to the shortest path distance from END to START.
     */
    private static int calculateResult(char[][] grid, int[][] dist, int n, int m, int startR, int startC) {
        int result = 0;
        int maxDist = dist[startR][startC]; // Shortest distance from END to START

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                char cell = grid[i][j];
                if (cell >= '0' && cell <= '9' && dist[i][j] != 0 && dist[i][j] <= maxDist) {
                    result += cell - '0';
                }
            }
        }
        return result;
    }

    /**
     * Immutable helper class to store BFS state (row, column, distance).
     */
    private static class BfsNode {
        final int r, c, dist;

        BfsNode(int r, int c, int dist) {
            this.r = r;
            this.c = c;
            this.dist = dist;
        }
    }

    /**
     * Fast input reader using BufferedReader and StringTokenizer for better performance
     * and maintainability compared to custom byte-level parsers.
     */
    private static class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        FastReader(BufferedReader br) {
            this.br = br;
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            String s = next();
            return s == null ? 0 : Integer.parseInt(s);
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.ArrayDeque;
import java.util.Arrays;
import java.util.StringTokenizer;

public class Main {
    // Direction vectors for moving down, up, left, right
    private static final int[] DR = {0, 0, -1, 1};
    private static final int[] DC = {-1, 1, 0, 0};

    private BufferedReader in;
    private PrintWriter out;
    private StringTokenizer st;

    private int rows, cols;
    private int[][] grid;
    private int[][] distances;
    private int startX, startY;
    private int endX, endY;

    public static void main(String[] args) throws IOException {
        new Main().run();
    }

    private void run() throws IOException {
        in = new BufferedReader(new InputStreamReader(System.in));
        out = new PrintWriter(System.out);
        st = new StringTokenizer("");

        try {
            readGrid();
            bfs();
            printResult();
        } finally {
            out.flush();
            in.close();
            out.close();
        }
    }

    private void readGrid() throws IOException {
        rows = nextInt();
        cols = nextInt();
        grid = new int[rows][cols];
        distances = new int[rows][cols];

        // Initialize distances to infinity
        for (int[] row : distances) {
            Arrays.fill(row, Integer.MAX_VALUE);
        }

        for (int r = 0; r < rows; r++) {
            String line = nextToken();
            for (int c = 0; c < cols; c++) {
                char ch = line.charAt(c);
                switch (ch) {
                    case 'T':
                        grid[r][c] = -1; // Wall
                        break;
                    case 'S':
                        startX = c;
                        startY = r;
                        grid[r][c] = 0;
                        break;
                    case 'E':
                        endX = c;
                        endY = r;
                        grid[r][c] = 0;
                        break;
                    default:
                        grid[r][c] = ch - '0';
                }
            }
        }
    }

    private void bfs() {
        // BFS originates from 'E' to match original problem semantics
        distances[endY][endX] = 0;
        ArrayDeque<Integer> queue = new ArrayDeque<>();
        queue.offer(endY * cols + endX);

        while (!queue.isEmpty()) {
            int pos = queue.poll();
            int y = pos / cols;
            int x = pos % cols;
            int currentDist = distances[y][x];

            for (int i = 0; i < 4; i++) {
                int ny = y + DR[i];
                int nx = x + DC[i];

                if (isValidCell(ny, nx) && grid[ny][nx] != -1) {
                    if (currentDist + 1 < distances[ny][nx]) {
                        distances[ny][nx] = currentDist + 1;
                        queue.offer(ny * cols + nx);
                    }
                }
            }
        }
    }

    private void printResult() {
        // Sum values of cells reachable within the shortest path distance from E to S
        int shortestPathDist = distances[startY][startX];
        int totalScore = 0;

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (distances[r][c] <= shortestPathDist && grid[r][c] > 0) {
                    totalScore += grid[r][c];
                }
            }
        }
        out.println(totalScore);
    }

    private boolean isValidCell(int r, int c) {
        return r >= 0 && c >= 0 && r < rows && c < cols;
    }

    private String nextToken() throws IOException {
        while (!st.hasMoreTokens()) {
            String line = in.readLine();
            if (line == null) return null;
            st = new StringTokenizer(line);
        }
        return st.nextToken();
    }

    private int nextInt() throws IOException {
        String token = nextToken();
        if (token == null) throw new IOException("Unexpected end of input");
        return Integer.parseInt(token);
    }
}

