class TaskD {
    // Direction vectors for moving Up, Right, Down, Left
    private static final int[] DX = {-1, 0, 1, 0};
    private static final int[] DY = {0, 1, 0, -1};

    public void solve(InputReader in, PrintWriter out) {
        // Read grid dimensions
        int rows = in.nextInt();
        int cols = in.nextInt();

        int[][] grid = new int[rows][cols];
        int startX = -1, startY = -1;
        int endX = -1, endY = -1;

        // Parse the grid input
        for (int i = 0; i < rows; i++) {
            String line = in.next();
            for (int j = 0; j < cols; j++) {
                char ch = line.charAt(j);
                if (ch == 'T') {
                    grid[i][j] = -1; // Obstacle/Tree
                } else if (ch == 'S') {
                    startX = i;
                    startY = j;
                } else if (ch == 'E') {
                    endX = i;
                    endY = j;
                } else {
                    grid[i][j] = ch - '0'; // Cell weight
                }
            }
        }

        // BFS Initialization
        // dist[i][j] stores the shortest distance from 'E' to cell (i, j)
        // Initialize with -1 to indicate unvisited
        int[][] dist = new int[rows][cols];
        for (int[] row : dist) {
            Arrays.fill(row, -1);
        }

        // Queue for BFS implementation
        // Using parallel arrays for coordinates to avoid object overhead
        int[] qX = new int[rows * cols];
        int[] qY = new int[rows * cols];
        int head = 0;
        int tail = 0;

        // Start BFS from the 'E' (End) position
        dist[endX][endY] = 0;
        qX[tail] = endX;
        qY[tail] = endY;
        tail++;

        // BFS Loop
        while (head < tail) {
            int currX = qX[head];
            int currY = qY[head];
            head++;

            int currentDist = dist[currX][currY];

            // Check all 4 adjacent directions
            for (int d = 0; d < 4; d++) {
                int nextX = currX + DX[d];
                int nextY = currY + DY[d];

                // Check bounds, obstacle status, and if already visited
                if (isValid(nextX, nextY, rows, cols, grid) && dist[nextX][nextY] == -1) {
                    dist[nextX][nextY] = currentDist + 1;
                    qX[tail] = nextX;
                    qY[tail] = nextY;
                    tail++;
                }
            }
        }

        // Calculate the result
        // Sum the weights of all cells reachable from 'E' that are 
        // closer or equal distance to 'E' than the 'S' (Start) position is.
        int maxDistance = dist[startX][startY];
        int totalWeight = 0;

        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (dist[i][j] != -1 && dist[i][j] <= maxDistance) {
                    totalWeight += grid[i][j];
                }
            }
        }

        out.println(totalWeight);
    }

    // Helper method to check if coordinates are within grid and not an obstacle
    private boolean isValid(int x, int y, int rows, int cols, int[][] grid) {
        return x >= 0 && x < rows && y >= 0 && y < cols && grid[x][y] != -1;
    }
}

