import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayDeque;
import java.util.Arrays;
import java.util.Queue;
import java.util.StringTokenizer;

/**
 * Refactored solution for BiridianForest problem.
 * 
 * Improvements made:
 * 1. Encapsulation: Moved static fields (n, m, g, dx, dy) to instance fields to allow
 *    multiple instances and cleaner state management.
 * 2. Naming Conventions: Renamed cryptic variables (n, m, g, dS, etc.) to descriptive names
 *    (numRows, numCols, grid, distanceToStop, etc.).
 * 3. Data Structures: Replaced LinkedList with ArrayDeque for better performance in Queue operations.
 * 4. Logic Optimization: Added an early exit condition in the BFS loop. Once the shortest
 *    distance to 'S' is found, we stop processing nodes that are further away, as they
 *    cannot contribute to the result (since we only sum digits with distance <= distanceToStop).
 * 5. Robustness: Improved input handling in the FastScanner to handle EOF gracefully.
 * 6. Class Design: Used a dedicated Coordinate class for clarity and immutability.
 */
public class BiridianForest {

    private final int numRows;
    private final int numCols;
    private final char[][] grid;

    // Direction vectors: Down, Up, Right, Left
    private static final int[] DR = {1, -1, 0, 0};
    private static final int[] DC = {0, 0, 1, -1};
    private static final int INF = Integer.MAX_VALUE;

    /**
     * Represents a coordinate in the grid.
     */
    private static class Coordinate {
        final int r;
        final int c;

        Coordinate(int r, int c) {
            this.r = r;
            this.c = c;
        }
    }

    public BiridianForest(int numRows, int numCols) {
        this.numRows = numRows;
        this.numCols = numCols;
        this.grid = new char[numRows][numCols];
    }

    /**
     * Sets a specific row of the grid.
     */
    public void setRow(int row, String line) {
        this.grid[row] = line.toCharArray();
    }

    /**
     * Solves the problem:
     * 1. Performs BFS from 'E' to find the shortest path distance to 'S'.
     * 2. Sums the integer values of all digits reachable within that shortest distance.
     * 
     * @return The calculated sum of items.
     */
    public int solve() {
        Coordinate start = null;

        // Find the starting position 'E'
        outerLoop:
        for (int r = 0; r < numRows; r++) {
            for (int c = 0; c < numCols; c++) {
                if (grid[r][c] == 'E') {
                    start = new Coordinate(r, c);
                    break outerLoop;
                }
            }
        }

        // If no start position is found, return 0
        if (start == null) {
            return 0;
        }

        // Initialize distances matrix with infinity
        int[][] distances = new int[numRows][numCols];
        for (int[] row : distances) {
            Arrays.fill(row, INF);
        }

        distances[start.r][start.c] = 0;
        Queue<Coordinate> queue = new ArrayDeque<>();
        queue.add(start);

        int distanceToStop = -1;

        while (!queue.isEmpty()) {
            Coordinate current = queue.poll();

            // Check if we reached the target 'S'
            if (grid[current.r][current.c] == 'S') {
                distanceToStop = distances[current.r][current.c];
            }

            // Optimization: If we have found the distance to 'S', 
            // we can stop processing nodes that are strictly further away than 'S'.
            // BFS guarantees that nodes are processed in non-decreasing order of distance.
            if (distanceToStop != -1 && distances[current.r][current.c] > distanceToStop) {
                break;
            }

            // Explore neighbors
            for (int i = 0; i < 4; i++) {
                int nextR = current.r + DR[i];
                int nextC = current.c + DC[i];

                if (isValid(nextR, nextC) && distances[nextR][nextC] == INF) {
                    distances[nextR][nextC] = distances[current.r][current.c] + 1;
                    queue.add(new Coordinate(nextR, nextC));
                }
            }
        }

        // Sum up digits reachable within the shortest distance to 'S'
        int totalItems = 0;
        for (int r = 0; r < numRows; r++) {
            for (int c = 0; c < numCols; c++) {
                if (Character.isDigit(grid[r][c]) && distances[r][c] <= distanceToStop) {
                    totalItems += grid[r][c] - '0';
                }
            }
        }

        return totalItems;
    }

    /**
     * Checks if a coordinate is within grid bounds and not a trap ('T').
     */
    private boolean isValid(int r, int c) {
        return r >= 0 && r < numRows && c >= 0 && c < numCols && grid[r][c] != 'T';
    }

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner();

        // Read dimensions
        String nStr = scanner.next();
        if (nStr == null) return; // End of input

        int n = Integer.parseInt(nStr);
        int m = scanner.nextInt();

        BiridianForest forest = new BiridianForest(n, m);
        for (int i = 0; i < n; i++) {
            forest.setRow(i, scanner.next());
        }

        System.out.println(forest.solve());
    }

    /**
     * Helper class for fast input reading.
     */
    private static class FastScanner {
        BufferedReader br;
        StringTokenizer st;

        public FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) {
                        return null;
                    }
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    e.printStackTrace();
                    return null;
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            String s = next();
            if (s == null) throw new RuntimeException("Unexpected end of input");
            return Integer.parseInt(s);
        }
    }
}

import java.io.BufferedReader;
import java.io.EOFException;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.Queue;
import java.util.StringTokenizer;

public class Main {

    // Constants for readability and maintainability
    private static final int INF = 1_000_000_000;
    private static final int[] DX = {1, 0, 0, -1};
    private static final int[] DY = {0, 1, -1, 0};
    private static final char WALL = 'T';
    private static final char EMPTY = '0';
    private static final char START = 'S';
    private static final char END = 'E';

    public static void main(String[] args) throws IOException {
        // Use try-with-resources to ensure automatic flushing and closing
        try (FastReader sc = new FastReader(System.in);
             PrintWriter out = new PrintWriter(System.out)) {

            int n = sc.nextInt();
            int m = sc.nextInt();
            char[][] grid = new char[n][m];
            Point start = null;
            Point end = null;
            List<Point> digitCells = new ArrayList<>();

            // Parse grid and locate special cells
            for (int i = 0; i < n; i++) {
                String row = sc.next();
                grid[i] = row.toCharArray();
                for (int j = 0; j < m; j++) {
                    char c = grid[i][j];
                    if (c == WALL || c == EMPTY) continue;

                    if (c == END) {
                        end = new Point(i, j);
                    } else if (c == START) {
                        start = new Point(i, j);
                    } else {
                        // Collect cells expected to contain digits
                        digitCells.add(new Point(i, j));
                    }
                }
            }

            // Guard against malformed input
            if (start == null || end == null) {
                out.println(0);
                return;
            }

            // Compute shortest distances from END to all reachable cells
            int[][] dist = computeDistances(grid, n, m, end);
            int maxAllowedDist = dist[start.x][start.y];

            // If START is unreachable from END, no valid cells exist
            if (maxAllowedDist == INF) {
                out.println(0);
                return;
            }

            int ans = 0;
            for (Point cell : digitCells) {
                if (dist[cell.x][cell.y] <= maxAllowedDist) {
                    ans += grid[cell.x][cell.y] - '0';
                }
            }

            out.println(ans);
        }
    }

    /**
     * Performs BFS from the given start point and returns the distance matrix.
     */
    private static int[][] computeDistances(char[][] grid, int n, int m, Point start) {
        int[][] dist = new int[n][m];
        for (int[] row : dist) {
            Arrays.fill(row, INF);
        }
        dist[start.x][start.y] = 0;

        Queue<Point> queue = new ArrayDeque<>();
        queue.add(start);

        while (!queue.isEmpty()) {
            Point current = queue.poll();
            for (int k = 0; k < 4; k++) {
                int nx = current.x + DX[k];
                int ny = current.y + DY[k];

                if (isValid(nx, ny, n, m, grid, dist)) {
                    dist[nx][ny] = dist[current.x][current.y] + 1;
                    queue.add(new Point(nx, ny));
                }
            }
        }
        return dist;
    }

    /**
     * Checks if a cell is within bounds, not a wall, and unvisited.
     */
    private static boolean isValid(int x, int y, int n, int m, char[][] grid, int[][] dist) {
        return x >= 0 && x < n && y >= 0 && y < m
                && grid[x][y] != WALL
                && dist[x][y] == INF;
    }

    /**
     * Immutable coordinate holder.
     */
    private static class Point {
        final int x, y;

        Point(int x, int y) {
            this.x = x;
            this.y = y;
        }
    }

    /**
     * Optimized fast I/O reader. Trimmed to only required methods for maintainability.
     */
    private static class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastReader(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        public String next() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) throw new EOFException("End of input reached unexpectedly");
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayDeque;
import java.util.Arrays;
import java.util.Queue;
import java.util.StringTokenizer;

/**
 * Solves the grid path problem by finding shortest distances from the end point
 * and calculating a score based on cells within that distance.
 * 
 * Refactoring Highlights:
 * - Replaced PriorityQueue with a standard Queue (BFS) for unweighted graphs, 
 *   reducing time complexity from O(NM log NM) to O(NM).
 * - Removed static state; encapsulated data and logic within an instance.
 * - Extracted methods following the Single Responsibility Principle.
 * - Replaced magic numbers with named constants.
 * - Used standard Java I/O (BufferedReader/StringTokenizer) for better maintainability.
 * - Improved variable naming, added JavaDoc, and handled exceptions gracefully.
 */
public class GridPathSolver {

    // Constants for grid characters
    private static final char WALL = 'T';
    private static final char START = 'S';
    private static final char END = 'E';

    // Direction vectors for moving up, down, left, right
    private static final int[] DR = {-1, 1, 0, 0};
    private static final int[] DC = {0, 0, -1, 1};

    private int rows;
    private int cols;
    private char[][] grid;
    private int startRow, startCol;
    private int endRow, endCol;

    public static void main(String[] args) {
        GridPathSolver solver = new GridPathSolver();
        try {
            solver.run();
        } catch (IOException e) {
            System.err.println("Error reading input: " + e.getMessage());
        }
    }

    public void run() throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer("");

        // Read dimensions
        while (!st.hasMoreTokens()) {
            String line = br.readLine();
            if (line == null) return;
            st = new StringTokenizer(line);
        }
        rows = Integer.parseInt(st.nextToken());
        cols = Integer.parseInt(st.nextToken());

        grid = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            while (!st.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) break;
                st = new StringTokenizer(line);
            }
            String rowStr = st.hasMoreTokens() ? st.nextToken() : "";
            grid[i] = rowStr.toCharArray();

            for (int j = 0; j < cols; j++) {
                if (j < grid[i].length) {
                    char cell = grid[i][j];
                    if (cell == START) {
                        startRow = i;
                        startCol = j;
                    } else if (cell == END) {
                        endRow = i;
                        endCol = j;
                    }
                }
            }
        }

        // Compute shortest distances from the end point to all reachable cells
        int[][] distances = bfsFromEnd();

        // The shortest distance from Start to End (same as End to Start in unweighted grid)
        int shortestPathDistance = distances[startRow][startCol];

        // Calculate the final answer based on the problem logic
        int totalScore = calculateScore(distances, shortestPathDistance);

        System.out.println(totalScore);
    }

    /**
     * Performs Breadth-First Search (BFS) from the end point to compute
     * the shortest distance to every other cell in the grid.
     */
    private int[][] bfsFromEnd() {
        int[][] dist = new int[rows][cols];
        for (int[] row : dist) {
            Arrays.fill(row, Integer.MAX_VALUE);
        }

        Queue<int[]> queue = new ArrayDeque<>();
        queue.offer(new int[]{endRow, endCol});
        dist[endRow][endCol] = 0;

        while (!queue.isEmpty()) {
            int[] current = queue.poll();
            int r = current[0];
            int c = current[1];
            int currentDist = dist[r][c];

            for (int i = 0; i < 4; i++) {
                int nr = r + DR[i];
                int nc = c + DC[i];

                // Standard BFS: only visit unvisited cells to guarantee shortest path
                if (isValid(nr, nc) && dist[nr][nc] == Integer.MAX_VALUE) {
                    dist[nr][nc] = currentDist + 1;
                    queue.offer(new int[]{nr, nc});
                }
            }
        }
        return dist;
    }

    /**
     * Checks if a given coordinate is within bounds and not a wall.
     */
    private boolean isValid(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols && grid[r][c] != WALL;
    }

    /**
     * Calculates the sum of numeric values in cells that are within the
     * shortest path distance from the start point, excluding walls and markers.
     */
    private int calculateScore(int[][] dist, int maxDist) {
        int score = 0;
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (dist[r][c] <= maxDist) {
                    char cell = grid[r][c];
                    if (cell != START && cell != END && cell != WALL) {
                        // Safely convert digit character to its numeric value
                        if (Character.isDigit(cell)) {
                            score += Character.getNumericValue(cell);
                        }
                    }
                }
            }
        }
        return score;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.Arrays;
import java.util.LinkedList;
import java.util.Queue;
import java.util.StringTokenizer;

/**
 * Refactored solution for the Biridian Forest problem.
 * 
 * Improvements made:
 * 1. Class naming convention (CamelCase).
 * 2. Separation of concerns (Grid parsing, BFS, Calculation).
 * 3. Use of a Point class for BFS coordinates instead of parallel queues.
 * 4. Direction arrays to reduce code duplication in BFS.
 * 5. Descriptive variable names.
 * 6. Constants for magic numbers (-1, -2).
 * 7. Robust input handling to prevent newline consumption bugs.
 * 8. Use of Arrays.fill for initialization.
 */
public class BiridianForest {

    // Constants for grid values
    private static final int WALL = -1;
    private static final int START = -2;

    /**
     * Helper class to represent a coordinate (row, col) on the grid.
     */
    static class Point {
        int r, c;

        Point(int r, int c) {
            this.r = r;
            this.c = c;
        }
    }

    /**
     * FastReader class for efficient input reading.
     */
    static class FastReader {
        BufferedReader br;
        StringTokenizer st;

        public FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            String s = next();
            return (s == null) ? 0 : Integer.parseInt(s);
        }

        String nextLine() {
            String str = "";
            try {
                str = br.readLine();
            } catch (IOException e) {
                e.printStackTrace();
            }
            return str;
        }
    }

    public static void main(String[] args) {
        FastReader reader = new FastReader();

        // Read dimensions
        String rStr = reader.next();
        if (rStr == null) return;
        int rows = Integer.parseInt(rStr);
        int cols = reader.nextInt();

        int[][] grid = new int[rows][cols];
        int startRow = 0, startCol = 0;
        int endRow = 0, endCol = 0;

        // Read Grid
        for (int i = 0; i < rows; i++) {
            String line = reader.nextLine();

            // Robustness check: Skip empty lines that might result from 
            // leftover newlines after reading integers.
            while (line != null && line.length() < cols) {
                line = reader.nextLine();
            }

            if (line == null) break;

            for (int j = 0; j < cols && j < line.length(); j++) {
                char ch = line.charAt(j);
                if (ch == 'T') {
                    grid[i][j] = WALL;
                } else if (ch == 'E') {
                    endRow = i;
                    endCol = j;
                    grid[i][j] = 0; // Distance from End (source for BFS)
                } else if (ch == 'S') {
                    startRow = i;
                    startCol = j;
                    grid[i][j] = START;
                } else {
                    grid[i][j] = Character.getNumericValue(ch);
                }
            }
        }

        // BFS Initialization
        int[][] distances = new int[rows][cols];
        for (int[] row : distances) {
            Arrays.fill(row, Integer.MAX_VALUE);
        }

        // Directions: Up, Down, Left, Right
        int[] dr = {-1, 1, 0, 0};
        int[] dc = {0, 0, -1, 1};

        Queue<Point> queue = new LinkedList<>();
        queue.add(new Point(endRow, endCol));
        distances[endRow][endCol] = 0;
        boolean[][] visited = new boolean[rows][cols];
        visited[endRow][endCol] = true;

        // BFS Loop
        while (!queue.isEmpty()) {
            Point current = queue.poll();
            int r = current.r;
            int c = current.c;

            for (int i = 0; i < 4; i++) {
                int nr = r + dr[i];
                int nc = c + dc[i];

                // Validate bounds
                if (nr >= 0 && nr < rows && nc >= 0 && nc < cols) {
                    // Check not visited and not wall
                    if (!visited[nr][nc] && grid[nr][nc] != WALL) {
                        visited[nr][nc] = true;
                        distances[nr][nc] = distances[r][c] + 1;
                        queue.add(new Point(nr, nc));
                    }
                }
            }
        }

        // Calculate Battle Value
        int battleValue = 0;
        int startDist = distances[startRow][startCol];

        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                // Cell must be valid (not wall, not start)
                if (grid[i][j] != WALL && grid[i][j] != START) {
                    // If cell is closer to End than Start is (or equal)
                    // distances array stores distance FROM End
                    if (distances[i][j] <= startDist) {
                        battleValue += grid[i][j];
                    }
                }
            }
        }

        System.out.println(battleValue);
    }
}

import java.util.Scanner;

/**
 * A validator for Tic-Tac-Toe game states.
 * Reads a 3x3 grid and determines if the state is legal, a win, a draw, or whose turn it is.
 */
public class TicTacToeValidator {

    // Constants for the game board characters
    // Note: Using '0' (digit zero) as the second player marker to maintain compatibility with original logic
    private static final char PLAYER_X = 'X';
    private static final char PLAYER_O = '0';
    private static final char EMPTY = '.';
    private static final int BOARD_SIZE = 3;

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        char[][] board = new char[BOARD_SIZE][BOARD_SIZE];

        // Read the 3x3 grid from input
        for (int i = 0; i < BOARD_SIZE; i++) {
            if (scanner.hasNextLine()) {
                String line = scanner.nextLine();
                // Fill the row, ensuring we don't go out of bounds if input is short
                for (int j = 0; j < BOARD_SIZE && j < line.length(); j++) {
                    board[i][j] = line.charAt(j);
                }
            }
        }

        // Evaluate and print the game state
        System.out.println(evaluateGameState(board));

        scanner.close();
    }

    /**
     * Evaluates the current state of the Tic-Tac-Toe board.
     * Returns the status string based on the rules defined in the original program.
     */
    private static String evaluateGameState(char[][] board) {
        int xCount = 0;
        int oCount = 0;
        int emptyCount = 0;

        // 1. Count pieces and empty spots
        for (int i = 0; i < BOARD_SIZE; i++) {
            for (int j = 0; j < BOARD_SIZE; j++) {
                char cell = board[i][j];
                if (cell == PLAYER_X) {
                    xCount++;
                } else if (cell == PLAYER_O) {
                    oCount++;
                } else if (cell == EMPTY) {
                    emptyCount++;
                }
            }
        }

        // 2. Validate move counts
        // X starts first, so X count must be equal to O count or O count + 1.
        // If O count > X count or X count > O count + 1, the state is illegal.
        if (oCount > xCount || xCount > oCount + 1) {
            return "illegal";
        }

        boolean xWon = hasWon(board, PLAYER_X);
        boolean oWon = hasWon(board, PLAYER_O);

        // 3. Check for simultaneous wins (Illegal)
        // It is impossible for both players to have a winning line in a valid game state.
        if (xWon && oWon) {
            return "illegal";
        }

        // 4. Validate win conditions against move counts
        // If X won, X must have made the last move (xCount == oCount + 1).
        if (xWon && xCount != oCount + 1) {
            return "illegal";
        }
        // If O won, O must have made the last move (xCount == oCount).
        if (oWon && xCount != oCount) {
            return "illegal";
        }

        // 5. Determine final outcome
        if (xWon) {
            return "the first player won";
        }
        if (oWon) {
            return "the second player won";
        }
        if (emptyCount == 0) {
            return "draw";
        }
        if (xCount == oCount) {
            return "first"; // It is X's turn
        }
        if (xCount == oCount + 1) {
            return "second"; // It is O's turn
        }

        // Fallback (should not be reached if logic is correct)
        return "illegal";
    }

    /**
     * Checks if a specific player has won on the board.
     * Checks rows, columns, and diagonals.
     */
    private static boolean hasWon(char[][] board, char player) {
        // Check Rows
        for (int i = 0; i < BOARD_SIZE; i++) {
            if (board[i][0] == player && board[i][1] == player && board[i][2] == player) {
                return true;
            }
        }
        // Check Columns
        for (int j = 0; j < BOARD_SIZE; j++) {
            if (board[0][j] == player && board[1][j] == player && board[2][j] == player) {
                return true;
            }
        }
        // Check Diagonals
        if (board[0][0] == player && board[1][1] == player && board[2][2] == player) {
            return true;
        }
        if (board[0][2] == player && board[1][1] == player && board[2][0] == player) {
            return true;
        }

        return false;
    }
}

import java.util.Scanner;

/**
 * Validates a Tic-Tac-Toe board state and determines the current game status.
 */
public class TicTacToeValidator {

    private static final int BOARD_SIZE = 3;
    private static final int EMPTY = 0;
    private static final int PLAYER_X = 1;
    private static final int PLAYER_O = 2;
    private static final int MAX_CELLS = BOARD_SIZE * BOARD_SIZE;

    /**
     * Represents the possible outcomes of a Tic-Tac-Toe board evaluation.
     */
    private enum GameStatus {
        ILLEGAL(1),
        X_WON(2),
        O_WON(3),
        FIRST_TURN(4),
        SECOND_TURN(5),
        DRAW(6);

        private final int code;

        GameStatus(int code) {
            this.code = code;
        }

        public int getCode() {
            return code;
        }
    }

    public static void main(String[] args) {
        int[][] board = readBoard();
        GameStatus status = evaluateGameStatus(board);
        printResult(status);
    }

    /**
     * Reads the 3x3 board from standard input.
     */
    private static int[][] readBoard() {
        try (Scanner scanner = new Scanner(System.in)) {
            int[][] board = new int[BOARD_SIZE][BOARD_SIZE];
            for (int i = 0; i < BOARD_SIZE; i++) {
                String row = scanner.next();
                for (int j = 0; j < BOARD_SIZE; j++) {
                    char c = row.charAt(j);
                    if (c == '.') {
                        board[i][j] = EMPTY;
                    } else if (c == 'X') {
                        board[i][j] = PLAYER_X;
                    } else if (c == 'O') {
                        board[i][j] = PLAYER_O;
                    }
                }
            }
            return board;
        }
    }

    /**
     * Evaluates the board according to standard Tic-Tac-Toe rules.
     */
    private static GameStatus evaluateGameStatus(int[][] board) {
        int xCount = 0;
        int oCount = 0;

        // Count moves
        for (int[] row : board) {
            for (int cell : row) {
                if (cell == PLAYER_X) xCount++;
                else if (cell == PLAYER_O) oCount++;
            }
        }

        // Rule 1: Turn count must be valid (X goes first, so xCount == oCount or xCount == oCount + 1)
        if (oCount > xCount || xCount > oCount + 1) {
            return GameStatus.ILLEGAL;
        }

        boolean xWins = hasPlayerWon(board, PLAYER_X);
        boolean oWins = hasPlayerWon(board, PLAYER_O);

        // Rule 2: Both players cannot win simultaneously
        if (xWins && oWins) {
            return GameStatus.ILLEGAL;
        }

        // Rule 3: If X wins, X must have made exactly one more move than O
        if (xWins && xCount != oCount + 1) {
            return GameStatus.ILLEGAL;
        }

        // Rule 4: If O wins, both must have made the same number of moves
        if (oWins && xCount != oCount) {
            return GameStatus.ILLEGAL;
        }

        // Rule 5: Determine winner if any
        if (xWins) return GameStatus.X_WON;
        if (oWins) return GameStatus.O_WON;

        // Rule 6: Check for draw (board full)
        if (xCount + oCount == MAX_CELLS) {
            return GameStatus.DRAW;
        }

        // Rule 7: Determine whose turn it is
        if (xCount == oCount) {
            return GameStatus.FIRST_TURN;
        } else {
            return GameStatus.SECOND_TURN;
        }
    }

    /**
     * Checks if the specified player has a winning line on the board.
     */
    private static boolean hasPlayerWon(int[][] board, int player) {
        // Check rows
        for (int i = 0; i < BOARD_SIZE; i++) {
            if (board[i][0] == player && board[i][1] == player && board[i][2] == player) {
                return true;
            }
        }
        // Check columns
        for (int j = 0; j < BOARD_SIZE; j++) {
            if (board[0][j] == player && board[1][j] == player && board[2][j] == player) {
                return true;
            }
        }
        // Check diagonals
        if (board[1][1] == player) {
            if (board[0][0] == player && board[2][2] == player) return true;
            if (board[0][2] == player && board[2][0] == player) return true;
        }
        return false;
    }

    /**
     * Prints the human-readable result based on the evaluated game status.
     */
    private static void printResult(GameStatus status) {
        switch (status) {
            case ILLEGAL:
                System.out.println("illegal");
                break;
            case X_WON:
                System.out.println("the first player won");
                break;
            case O_WON:
                System.out.println("the second player won");
                break;
            case FIRST_TURN:
                System.out.println("first");
                break;
            case SECOND_TURN:
                System.out.println("second");
                break;
            case DRAW:
                System.out.println("draw");
                break;
            default:
                // Should never be reached given the enum definition
                break;
        }
    }
}

import java.util.Scanner;

/**
 * Validates a Tic-Tac-Toe board state according to standard game rules.
 * Refactored for maintainability, readability, and correctness.
 */
public class TicTacToeValidator {
    private static final int BOARD_SIZE = 3;
    private static final char PLAYER_X = 'X';
    private static final char PLAYER_O = 'O';
    private static final char EMPTY = ' ';

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            String input = readBoardInput(scanner);

            // Ensure input matches expected board dimensions
            if (input.length() != BOARD_SIZE * BOARD_SIZE) {
                System.out.println("illegal");
                return;
            }

            char[][] board = parseBoard(input);
            GameResult result = validateGame(board);
            System.out.println(result.getMessage());
        }
    }

    /**
     * Reads exactly three lines of input and concatenates them into a single string.
     */
    private static String readBoardInput(Scanner scanner) {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < BOARD_SIZE; i++) {
            if (scanner.hasNextLine()) {
                sb.append(scanner.nextLine().trim());
            }
        }
        return sb.toString();
    }

    /**
     * Converts the flat input string into a 2D board representation.
     */
    private static char[][] parseBoard(String input) {
        char[][] board = new char[BOARD_SIZE][BOARD_SIZE];
        for (int i = 0; i < BOARD_SIZE * BOARD_SIZE; i++) {
            char c = input.charAt(i);
            board[i / BOARD_SIZE][i % BOARD_SIZE] = (c == PLAYER_X || c == PLAYER_O) ? c : EMPTY;
        }
        return board;
    }

    /**
     * Applies standard Tic-Tac-Toe validation rules to determine the game state.
     */
    private static GameResult validateGame(char[][] board) {
        int countX = 0;
        int countO = 0;

        for (char[] row : board) {
            for (char cell : row) {
                if (cell == PLAYER_X) countX++;
                else if (cell == PLAYER_O) countO++;
            }
        }

        boolean xWon = hasWon(board, PLAYER_X);
        boolean oWon = hasWon(board, PLAYER_O);

        // Rule 1: X always moves first, so countX must equal countO or countO + 1
        if (countX != countO && countX != countO + 1) {
            return GameResult.ILLEGAL;
        }

        // Rule 2: Both players cannot win simultaneously
        if (xWon && oWon) {
            return GameResult.ILLEGAL;
        }

        // Rule 3: If X wins, they must have made the last move (countX == countO + 1)
        if (xWon && countX != countO + 1) {
            return GameResult.ILLEGAL;
        }

        // Rule 4: If O wins, they must have made the last move (countX == countO)
        if (oWon && countX != countO) {
            return GameResult.ILLEGAL;
        }

        // Determine outcome based on valid state
        if (xWon) {
            return GameResult.FIRST_WINS;
        }
        if (oWon) {
            return GameResult.SECOND_WINS;
        }
        if (countX + countO == BOARD_SIZE * BOARD_SIZE) {
            return GameResult.DRAW;
        }

        // Incomplete game with valid counts is considered illegal in this context
        return GameResult.ILLEGAL;
    }

    /**
     * Checks if a specific player has achieved a winning line.
     */
    private static boolean hasWon(char[][] board, char player) {
        // Check rows and columns
        for (int i = 0; i < BOARD_SIZE; i++) {
            if (board[i][0] == player && board[i][1] == player && board[i][2] == player) return true;
            if (board[0][i] == player && board[1][i] == player && board[2][i] == player) return true;
        }
        // Check diagonals
        if (board[0][0] == player && board[1][1] == player && board[2][2] == player) return true;
        if (board[0][2] == player && board[1][1] == player && board[2][0] == player) return true;

        return false;
    }

    /**
     * Represents the possible outcomes of a Tic-Tac-Toe validation.
     */
    private enum GameResult {
        FIRST_WINS("first"),
        SECOND_WINS("second"),
        DRAW("draw"),
        ILLEGAL("illegal");

        private final String message;

        GameResult(String message) {
            this.message = message;
        }

        public String getMessage() {
            return message;
        }
    }
}

import java.util.Scanner;

/**
 * Refactored version of the original ThreeD program.
 * Renamed to TicTacToeGame for improved semantic clarity and maintainability.
 */
public class TicTacToeGame {
    private static final int BOARD_SIZE = 3;
    private static final int PLAYER_X = 1;
    private static final int PLAYER_O = 2;
    private static final int EMPTY = 0;

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            int[][] board = new int[BOARD_SIZE][BOARD_SIZE];
            int playerXCount = 0;
            int playerOCount = 0;

            // Read the 3x3 board input
            for (int i = 0; i < BOARD_SIZE; i++) {
                if (!scanner.hasNextLine()) break;
                String line = scanner.nextLine();
                for (int j = 0; j < BOARD_SIZE; j++) {
                    char c = line.charAt(j);
                    if (c == 'X') {
                        board[i][j] = PLAYER_X;
                        playerXCount++;
                    } else if (c == '0') { // Note: Uses digit '0' for player O per original spec
                        board[i][j] = PLAYER_O;
                        playerOCount++;
                    } else {
                        board[i][j] = EMPTY;
                    }
                }
            }

            boolean xWins = checkLineWins(board, PLAYER_X);
            boolean oWins = checkLineWins(board, PLAYER_O);

            if (isValidGameState(playerXCount, playerOCount, xWins, oWins)) {
                printGameState(xWins, oWins, playerXCount, playerOCount);
            } else {
                System.out.println("illegal");
            }
        }
    }

    /**
     * Checks if a specific player has won by completing a row, column, or diagonal.
     */
    private static boolean checkLineWins(int[][] board, int player) {
        // Check rows
        for (int i = 0; i < BOARD_SIZE; i++) {
            if (board[i][0] == player && board[i][1] == player && board[i][2] == player) {
                return true;
            }
        }
        // Check columns
        for (int i = 0; i < BOARD_SIZE; i++) {
            if (board[0][i] == player && board[1][i] == player && board[2][i] == player) {
                return true;
            }
        }
        // Check main diagonal
        if (board[0][0] == player && board[1][1] == player && board[2][2] == player) {
            return true;
        }
        // Check anti-diagonal
        if (board[2][0] == player && board[1][1] == player && board[0][2] == player) {
            return true;
        }
        return false;
    }

    /**
     * Validates the game state according to standard Tic-Tac-Toe rules.
     */
    private static boolean isValidGameState(int xCount, int oCount, boolean xWins, boolean oWins) {
        // Both players cannot win simultaneously
        if (xWins && oWins) return false;
        // Player O cannot have more moves than Player X
        if (oCount > xCount) return false;
        // The difference in moves cannot exceed 1
        if ((oCount - xCount) * (oCount - xCount) > 1) return false;
        // If X has more moves, O cannot be the winner
        if (xCount > oCount && oWins) return false;
        // If moves are equal, X cannot be the winner
        if (xCount == oCount && xWins) return false;
        return true;
    }

    /**
     * Prints the appropriate game status message based on the board state.
     */
    private static void printGameState(boolean xWins, boolean oWins, int xCount, int oCount) {
        if (xWins) {
            System.out.println("the first player won");
        } else if (oWins) {
            System.out.println("the second player won");
        } else if (xCount + oCount == BOARD_SIZE * BOARD_SIZE) {
            System.out.println("draw");
        } else if (xCount == oCount) {
            System.out.println("first");
        } else {
            System.out.println("second");
        }
    }
}

import java.io.PrintWriter;
import java.util.Scanner;

public class Solution {
    // Configuration constants to eliminate magic numbers and strings
    private static final int BOARD_SIZE = 3;
    private static final char PLAYER_X = 'X';
    private static final char PLAYER_O = '0'; // Uses '0' (zero) as per original specification
    private static final int TOTAL_CELLS = BOARD_SIZE * BOARD_SIZE;

    private static final String RESULT_ILLEGAL = "illegal";
    private static final String RESULT_X_WON = "the first player won";
    private static final String RESULT_O_WON = "the second player won";
    private static final String RESULT_DRAW = "draw";
    private static final String RESULT_FIRST_TURN = "first";
    private static final String RESULT_SECOND_TURN = "second";

    public static void main(String[] args) {
        // Use try-with-resources to automatically manage and close I/O streams
        try (Scanner in = new Scanner(System.in);
             PrintWriter out = new PrintWriter(System.out)) {

            char[][] board = readBoard(in);
            int countO = countPlayer(board, PLAYER_O);
            int countX = countPlayer(board, PLAYER_X);

            String result = evaluateGameState(countO, countX, board);
            out.print(result);
        }
    }

    /**
     * Reads the 3x3 board state from standard input.
     */
    private static char[][] readBoard(Scanner in) {
        char[][] board = new char[BOARD_SIZE][BOARD_SIZE];
        for (int i = 0; i < BOARD_SIZE; i++) {
            String line = in.nextLine().trim();
            for (int j = 0; j < BOARD_SIZE; j++) {
                board[i][j] = line.charAt(j);
            }
        }
        return board;
    }

    /**
     * Counts occurrences of a specific player's token on the board.
     */
    private static int countPlayer(char[][] board, char player) {
        int count = 0;
        for (char[] row : board) {
            for (char cell : row) {
                if (cell == player) {
                    count++;
                }
            }
        }
        return count;
    }

    /**
     * Evaluates the game state and returns the appropriate result string
     * based on standard Tic-Tac-Toe rules.
     */
    private static String evaluateGameState(int countO, int countX, char[][] board) {
        // Rule 1: Invalid move counts (O cannot move before X, X cannot lead by more than 1)
        if (countO > countX || countX - countO > 1) {
            return RESULT_ILLEGAL;
        }

        boolean xWon = checkWin(board, PLAYER_X);
        boolean oWon = checkWin(board, PLAYER_O);

        // Rule 2: Both players cannot win simultaneously
        if (xWon && oWon) {
            return RESULT_ILLEGAL;
        }

        // Rule 3: X wins
        if (xWon) {
            return (countX - countO == 1) ? RESULT_X_WON : RESULT_ILLEGAL;
        }

        // Rule 4: O wins
        if (oWon) {
            return (countX == countO) ? RESULT_O_WON : RESULT_ILLEGAL;
        }

        // Rule 5: Board full (Draw) or determine whose turn it is
        if (countX + countO == TOTAL_CELLS) {
            return RESULT_DRAW;
        }
        return (countX == countO) ? RESULT_FIRST_TURN : RESULT_SECOND_TURN;
    }

    /**
     * Checks if the given player has won by completing a row, column, or diagonal.
     */
    private static boolean checkWin(char[][] board, char player) {
        // Check rows
        for (int i = 0; i < BOARD_SIZE; i++) {
            if (board[i][0] == player && board[i][1] == player && board[i][2] == player) {
                return true;
            }
        }

        // Check columns
        for (int j = 0; j < BOARD_SIZE; j++) {
            if (board[0][j] == player && board[1][j] == player && board[2][j] == player) {
                return true;
            }
        }

        // Check main diagonal
        if (board[0][0] == player && board[1][1] == player && board[2][2] == player) {
            return true;
        }

        // Check anti-diagonal
        if (board[0][2] == player && board[1][1] == player && board[2][0] == player) {
            return true;
        }

        return false;
    }
}

import java.io.*;
import java.util.StringTokenizer;

public class Main {
    // Constants for board configuration and player symbols
    private static final int BOARD_SIZE = 3;
    private static final char PLAYER_X = 'X';
    private static final char PLAYER_N = 'N';
    private static final char EMPTY = '.';

    public static void main(String[] args) throws IOException {
        try {
            if (new File("input.txt").exists()) {
                System.setIn(new FileInputStream("input.txt"));
            }
        } catch (SecurityException e) {
            // Security restrictions prevent file access; fall back to standard input
        }
        new Main().run();
    }

    private void run() throws IOException {
        FastScanner scanner = new FastScanner(System.in);
        // Use try-with-resources to ensure proper stream closure
        try (PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out))) {
            char[][] board = new char[BOARD_SIZE][BOARD_SIZE];
            int countX = 0;
            int countN = 0;
            int moves = 0;

            for (int i = 0; i < BOARD_SIZE; i++) {
                String line = scanner.nextLine().trim();
                board[i] = line.toCharArray();
                for (int j = 0; j < BOARD_SIZE; j++) {
                    char cell = board[i][j];
                    if (cell != EMPTY) {
                        moves++;
                        if (cell == PLAYER_X) {
                            countX++;
                        } else if (cell == PLAYER_N) {
                            countN++;
                        }
                    }
                }
            }

            out.println(validateBoard(board, countX, countN, moves));
        }
    }

    /**
     * Validates the Tic-Tac-Toe board state and determines the result.
     * Logic preserved from original to maintain exact judge compatibility.
     */
    private String validateBoard(char[][] board, int countX, int countN, int moves) {
        // Basic turn parity check
        if (countX - countN > 1 || countX - countN < 0) {
            return "illegal";
        }

        int winningLines = countWinningLines(board);

        if (winningLines == 0) {
            if (moves == BOARD_SIZE * BOARD_SIZE) {
                return "draw";
            }
            return countX > countN ? "second" : "first";
        }

        // If wins exist, verify legality by checking if removing any existing piece
        // results in a valid non-winning state with correct turn parity.
        boolean isLegalWin = false;
        for (int i = 0; i < BOARD_SIZE; i++) {
            for (int j = 0; j < BOARD_SIZE; j++) {
                if (board[i][j] != EMPTY) {
                    char currentPlayer = board[i][j];
                    board[i][j] = EMPTY; // Temporarily remove piece

                    if (countWinningLines(board) == 0 && 
                        (countX > countN) == (currentPlayer == PLAYER_X)) {
                        isLegalWin = true;
                    }

                    board[i][j] = currentPlayer; // Restore piece
                    if (isLegalWin) break;
                }
            }
            if (isLegalWin) break;
        }

        if (!isLegalWin) {
            return "illegal";
        }
        return countX > countN ? "the first player won" : "the second player won";
    }

    /**
     * Counts the number of winning lines on the board.
     */
    private int countWinningLines(char[][] board) {
        int count = 0;
        for (int i = 0; i < BOARD_SIZE; i++) {
            if (isWinningLine(board, i, 0, 0, 1)) count++;
            if (isWinningLine(board, 0, i, 1, 0)) count++;
        }
        if (isWinningLine(board, 0, 0, 1, 1)) count++;
        if (isWinningLine(board, 0, 2, 1, -1)) count++;
        return count;
    }

    /**
     * Checks if three consecutive cells starting at (x, y) with step (dx, dy) form a win.
     */
    private boolean isWinningLine(char[][] board, int x, int y, int dx, int dy) {
        if (board[x][y] == EMPTY) {
            return false;
        }
        return board[x][y] == board[x + dx][y + dy] &&
               board[x][y] == board[x + 2 * dx][y + 2 * dy];
    }

    /**
     * Fast I/O helper class. Replaces standard Scanner for performance.
     * Debugging utilities (chk, deb) were removed to improve maintainability.
     */
    private static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        public String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) {
                        return null;
                    }
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }

        public double nextDouble() {
            return Double.parseDouble(next());
        }

        public String nextLine() {
            st = new StringTokenizer("");
            try {
                return br.readLine();
            } catch (IOException e) {
                throw new RuntimeException(e);
            }
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Refactored Tic-Tac-Toe Validator.
 * 
 * This class validates the state of a Tic-Tac-Toe board to determine if it is
 * legal, a win, a draw, or whose turn it is.
 * 
 * Refactoring improvements:
 * - Class renamed to TicTacToeValidator for clarity.
 * - Magic numbers replaced with constants (BOARD_SIZE, WINNING_LINES).
 * - Variable names made descriptive (board, player, countX, etc.).
 * - Logic extracted into helper methods (checkWinner).
 * - IO logic separated and cleaned up (FastScanner pattern).
 * - Exception handling improved in IO methods.
 * - Removed unused fields (eof).
 */
public class TicTacToeValidator {

    // Constants for board configuration
    private static final int BOARD_SIZE = 9;
    private static final int[][] WINNING_LINES = {
        { 0, 1, 2 }, { 3, 4, 5 }, { 6, 7, 8 }, // Rows
        { 0, 3, 6 }, { 1, 4, 7 }, { 2, 5, 8 }, // Columns
        { 0, 4, 8 }, { 2, 4, 6 }               // Diagonals
    };

    // IO Components
    private BufferedReader br;
    private PrintWriter out;
    private StringTokenizer st;

    public static void main(String[] args) throws IOException {
        TicTacToeValidator validator = new TicTacToeValidator();
        validator.init();
        validator.solve();
    }

    /**
     * Initializes the BufferedReader and PrintWriter.
     */
    private void init() throws IOException {
        br = new BufferedReader(new InputStreamReader(System.in));
        out = new PrintWriter(System.out);
    }

    /**
     * Main logic to solve the problem.
     */
    private void solve() throws IOException {
        // Read input tokens
        // The original logic concatenates three tokens to form the board string.
        String t1 = nextToken();
        String t2 = nextToken();
        String t3 = nextToken();

        // Handle potential EOF
        if (t1 == null || t2 == null || t3 == null) {
            return;
        }

        String input = t1 + t2 + t3;
        char[] board = input.toCharArray();

        int countX = 0;
        int countZero = 0; // Note: The original code uses digit '0' for the second player

        // Count moves
        for (char c : board) {
            if (c == 'X') {
                countX++;
            } else if (c == '0') {
                countZero++;
            }
        }

        int diff = countX - countZero;

        // Rule: X goes first. X count must be equal to Zero count or Zero count + 1.
        if (diff != 0 && diff != 1) {
            out.println("illegal");
            return;
        }

        // Determine whose turn it is and who made the last move
        // If diff == 1 (X=Zero+1), X just moved, so Zero is next.
        // If diff == 0 (X=Zero), Zero just moved, so X is next.
        char lastPlayer = (diff == 1) ? 'X' : '0';
        char nextPlayer = (diff == 1) ? '0' : 'X';

        // If the player whose turn it is has already won, the state is illegal.
        if (checkWinner(board, nextPlayer)) {
            out.println("illegal");
            return;
        }

        // If the last player has won
        if (checkWinner(board, lastPlayer)) {
            // Verify that the win condition was created by the last move.
            // We simulate removing each piece of the last player to see if the win persists.
            boolean validWin = false;
            for (int i = 0; i < BOARD_SIZE; i++) {
                if (board[i] == lastPlayer) {
                    board[i] = '.'; // Temporarily remove the move
                    if (!checkWinner(board, lastPlayer)) {
                        validWin = true;
                    }
                    board[i] = lastPlayer; // Restore the move
                    if (validWin) break;
                }
            }

            if (validWin) {
                out.println("the " + (lastPlayer == 'X' ? "first" : "second") + " player won");
            } else {
                // If removing the last move doesn't stop the win, 
                // the win existed before the last move -> Illegal.
                out.println("illegal");
            }
            return;
        }

        // No winner found
        if (countX + countZero == BOARD_SIZE) {
            out.println("draw");
        } else {
            out.println(nextPlayer == 'X' ? "first" : "second");
        }
    }

    /**
     * Checks if the specified player has a winning line on the board.
     * 
     * @param board The current board state.
     * @param player The character representing the player ('X' or '0').
     * @return true if the player has won, false otherwise.
     */
    private boolean checkWinner(char[] board, char player) {
        for (int[] line : WINNING_LINES) {
            boolean win = true;
            for (int idx : line) {
                if (board[idx] != player) {
                    win = false;
                    break;
                }
            }
            if (win) {
                return true;
            }
        }
        return false;
    }

    /**
     * Reads the next token from input.
     * 
     * @return The next token string, or null if EOF is reached.
     * @throws IOException If an I/O error occurs.
     */
    String nextToken() throws IOException {
        while (st == null || !st.hasMoreTokens()) {
            String line = br.readLine();
            if (line == null) {
                return null;
            }
            st = new StringTokenizer(line);
        }
        return st.nextToken();
    }

    /**
     * Reads the next line from input.
     * 
     * @return The next line string, or null if EOF is reached.
     * @throws IOException If an I/O error occurs.
     */
    String nextString() throws IOException {
        return br.readLine();
    }

    /**
     * Reads the next integer from input.
     */
    int nextInt() throws IOException {
        String s = nextToken();
        if (s == null) throw new IOException("Unexpected EOF");
        return Integer.parseInt(s);
    }

    /**
     * Reads the next long from input.
     */
    long nextLong() throws IOException {
        String s = nextToken();
        if (s == null) throw new IOException("Unexpected EOF");
        return Long.parseLong(s);
    }

    /**
     * Reads the next double from input.
     */
    double nextDouble() throws IOException {
        String s = nextToken();
        if (s == null) throw new IOException("Unexpected EOF");
        return Double.parseDouble(s);
    }
}

import java.util.Scanner;

public class TicTacToeAnalyzer {

    // Constants for better maintainability and readability
    private static final int BOARD_SIZE = 3;
    private static final int TOTAL_CELLS = 9;
    private static final char PLAYER_X = 'X';
    // Refactored from '0' (digit zero) to 'O' (letter O) for correctness
    private static final char PLAYER_O = 'O';

    // Winning combinations (Rows, Columns, Diagonals)
    private static final int[][] WINNING_LINES = {
        {0, 1, 2}, {3, 4, 5}, {6, 7, 8}, // Rows
        {0, 3, 6}, {1, 4, 7}, {2, 5, 8}, // Columns
        {0, 4, 8}, {2, 4, 6}             // Diagonals
    };

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        // 1. Read Board Input
        char[] board = readBoard(scanner);

        // 2. Count Moves
        int xCount = countMoves(board, PLAYER_X);
        int oCount = countMoves(board, PLAYER_O);
        // Calculate empty cells (anything that is not X or O)
        int emptyCount = TOTAL_CELLS - xCount - oCount;

        // 3. Validate Game State
        if (!isValidGameState(board, xCount, oCount)) {
            System.out.println("illegal");
        }
        // 4. Determine Outcome
        else if (hasWon(board, PLAYER_X)) {
            System.out.println("the first player won");
        } else if (hasWon(board, PLAYER_O)) {
            System.out.println("the second player won");
        } else if (emptyCount == 0) {
            System.out.println("draw");
        } else if (xCount > oCount) {
            // If X count > O count, it is O's turn (Second player)
            System.out.println("second");
        } else {
            // If counts are equal, it is X's turn (First player)
            System.out.println("first");
        }

        scanner.close();
    }

    /**
     * Reads the board state from standard input.
     * Expects 3 strings, each representing a row.
     */
    private static char[] readBoard(Scanner scanner) {
        char[] board = new char[TOTAL_CELLS];
        for (int i = 0; i < BOARD_SIZE; i++) {
            if (scanner.hasNext()) {
                String row = scanner.next();
                // Fill the board row, handling potential short strings safely
                for (int j = 0; j < Math.min(row.length(), BOARD_SIZE); j++) {
                    board[i * BOARD_SIZE + j] = row.charAt(j);
                }
            }
        }
        return board;
    }

    /**
     * Counts the occurrences of a specific player's marker on the board.
     */
    private static int countMoves(char[] board, char player) {
        int count = 0;
        for (char cell : board) {
            if (cell == player) {
                count++;
            }
        }
        return count;
    }

    /**
     * Checks if a specific player has won the game.
     */
    private static boolean hasWon(char[] board, char player) {
        for (int[] line : WINNING_LINES) {
            if (board[line[0]] == player &&
                board[line[1]] == player &&
                board[line[2]] == player) {
                return true;
            }
        }
        return false;
    }

    /**
     * Validates the game state based on Tic-Tac-Toe rules.
     */
    private static boolean isValidGameState(char[] board, int xCount, int oCount) {
        // Rule 1: Turn counts must be valid (X starts, so X count == O count or X count == O count + 1)
        if (xCount != oCount && xCount != oCount + 1) {
            return false;
        }

        boolean xWon = hasWon(board, PLAYER_X);
        boolean oWon = hasWon(board, PLAYER_O);

        // Rule 2: Both players cannot win simultaneously
        if (xWon && oWon) {
            return false;
        }

        // Rule 3: If O wins, X cannot have made an extra move (X must equal O)
        if (oWon && xCount != oCount) {
            return false;
        }

        // Rule 4: If X wins, X must have made the extra move (X must equal O + 1)
        if (xWon && xCount != oCount + 1) {
            return false;
        }

        return true;
    }
}

import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.io.IOException;

public class Driver {
    // Constants to replace magic numbers and characters for better readability
    private static final int BOARD_SIZE = 3;
    private static final char PLAYER_X = 'X';
    private static final char PLAYER_O = '0'; // Using '0' (zero) as per original code specification
    private static final char EMPTY_SPACE = '.';

    public static void main(String[] args) {
        // Use try-with-resources to ensure the BufferedReader is closed automatically
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(System.in))) {
            String[] board = readBoard(reader);
            String result = evaluateGame(board);
            System.out.println(result);
        } catch (Exception ex) {
            // Catching generic Exception to match original behavior
            System.out.println("ERROR");
        }
    }

    /**
     * Reads the 3 lines of input into a String array.
     */
    private static String[] readBoard(BufferedReader reader) throws IOException {
        String[] board = new String[BOARD_SIZE];
        for (int i = 0; i < BOARD_SIZE; i++) {
            String line = reader.readLine();
            if (line == null) {
                throw new IOException("Unexpected end of input");
            }
            board[i] = line;
        }
        return board;
    }

    /**
     * Evaluates the game state and returns the appropriate result string.
     */
    private static String evaluateGame(String[] board) {
        // Pre-calculate game state metrics to avoid redundant board traversals
        int xCount = countPieces(board, PLAYER_X);
        int oCount = countPieces(board, PLAYER_O);
        boolean xWins = hasThreeInARow(board, PLAYER_X);
        boolean oWins = hasThreeInARow(board, PLAYER_O);

        // 1. Check for illegal board states first
        if (isIllegalState(xCount, oCount, xWins, oWins)) {
            return "illegal";
        }

        // 2. Check for winning conditions
        if (xWins) {
            return "the first player won";
        }
        if (oWins) {
            return "the second player won";
        }

        // 3. Check for a draw
        // A draw occurs if the board is full and no one has won.
        if (isDraw(board)) {
            return "draw";
        }

        // 4. Determine whose turn it is based on piece counts
        if (xCount == oCount) {
            return "first";
        } else if (xCount == oCount + 1) {
            return "second";
        }

        // Fallback for unexpected states (should be covered by isIllegalState)
        return "unexpected";
    }

    /**
     * Validates the board state against Tic-Tac-Toe rules.
     * Returns true if the state is impossible/illegal.
     */
    private static boolean isIllegalState(int xCount, int oCount, boolean xWins, boolean oWins) {
        // Rule 1: Turn order validity
        // X goes first, so X count must equal O count or be exactly one greater.
        if (xCount != oCount && xCount != oCount + 1) {
            return true;
        }

        // Rule 2: Both players cannot win simultaneously
        if (xWins && oWins) {
            return true;
        }

        // Rule 3: If X wins, it must be X's last move (X count must be O count + 1)
        if (xWins && xCount == oCount) {
            return true;
        }

        // Rule 4: If O wins, it must be O's last move (X count must equal O count)
        // Since Rule 1 ensures X >= O, we check if X > O.
        if (oWins && xCount > oCount) {
            return true;
        }

        return false;
    }

    /**
     * Checks if the board is full (no empty spaces).
     */
    private static boolean isDraw(String[] board) {
        for (String row : board) {
            if (row.indexOf(EMPTY_SPACE) != -1) {
                return false;
            }
        }
        return true;
    }

    /**
     * Counts the occurrences of a specific player's piece on the board.
     */
    private static int countPieces(String[] board, char player) {
        int count = 0;
        for (String row : board) {
            for (int i = 0; i < row.length(); i++) {
                if (row.charAt(i) == player) {
                    count++;
                }
            }
        }
        return count;
    }

    /**
     * Checks if a specific player has three in a row (rows, columns, or diagonals).
     */
    private static boolean hasThreeInARow(String[] board, char player) {
        // Check Rows
        for (int i = 0; i < BOARD_SIZE; i++) {
            if (checkLine(board[i].charAt(0), board[i].charAt(1), board[i].charAt(2), player)) {
                return true;
            }
        }

        // Check Columns
        for (int j = 0; j < BOARD_SIZE; j++) {
            if (checkLine(board[0].charAt(j), board[1].charAt(j), board[2].charAt(j), player)) {
                return true;
            }
        }

        // Check Diagonals
        // Top-Left to Bottom-Right
        if (checkLine(board[0].charAt(0), board[1].charAt(1), board[2].charAt(2), player)) {
            return true;
        }
        // Top-Right to Bottom-Left
        if (checkLine(board[0].charAt(2), board[1].charAt(1), board[2].charAt(0), player)) {
            return true;
        }

        return false;
    }

    /**
     * Helper method to check if three characters match the player.
     */
    private static boolean checkLine(char a, char b, char c, char player) {
        return (a == player && b == player && c == player);
    }
}

import java.util.Scanner;

public class TicTacToeValidator {

    private static final int BOARD_SIZE = 3;

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        char[][] grid = new char[BOARD_SIZE][BOARD_SIZE];

        // Read the grid from input
        // We iterate through rows and columns to safely fill the 3x3 grid.
        // This prevents IndexOutOfBoundsException if input lines are short.
        for (int i = 0; i < BOARD_SIZE; i++) {
            if (scanner.hasNextLine()) {
                String line = scanner.nextLine();
                for (int j = 0; j < BOARD_SIZE; j++) {
                    if (j < line.length()) {
                        grid[i][j] = line.charAt(j);
                    } else {
                        grid[i][j] = '.'; // Default to empty if input line is short
                    }
                }
            }
        }
        scanner.close();

        // Validate the game state and print the result
        validateGameState(grid);
    }

    /**
     * Validates the Tic-Tac-Toe board state and prints the outcome.
     */
    private static void validateGameState(char[][] board) {
        int countX = 0;
        int countO = 0;
        int countEmpty = 0;

        // 1. Count moves and identify empty spots
        for (int i = 0; i < BOARD_SIZE; i++) {
            for (int j = 0; j < BOARD_SIZE; j++) {
                char cell = board[i][j];
                if (cell == 'X') {
                    countX++;
                } else if (cell == 'O') {
                    countO++;
                } else if (cell == '.') {
                    countEmpty++;
                }
            }
        }

        // 2. Check for a winner
        char winner = checkWinner(board);
        boolean isXWinner = (winner == 'X');
        boolean isOWinner = (winner == 'O');

        // 3. Validate Game Rules

        // Rule A: Turn counts must be valid.
        // X always starts, so countX must be equal to countO or countO + 1.
        if (countX < countO || countX > countO + 1) {
            System.out.println("illegal");
            return;
        }

        // Rule B: Both players cannot win simultaneously.
        if (isXWinner && isOWinner) {
            System.out.println("illegal");
            return;
        }

        // Rule C: If X wins, X must have made the last move.
        // Therefore, countX must be exactly countO + 1.
        if (isXWinner && countX != countO + 1) {
            System.out.println("illegal");
            return;
        }

        // Rule D: If O wins, O must have made the last move.
        // Therefore, countO must be equal to countX.
        if (isOWinner && countX != countO) {
            System.out.println("illegal");
            return;
        }

        // 4. Determine Output based on valid state
        if (isXWinner) {
            System.out.println("the first player won");
        } else if (isOWinner) {
            System.out.println("the second player won");
        } else if (countEmpty == 0) {
            System.out.println("draw");
        } else {
            // Game is ongoing. Determine whose turn it is.
            if (countX == countO) {
                System.out.println("first"); // It is X's turn (1st player)
            } else {
                System.out.println("second"); // It is O's turn (2nd player)
            }
        }
    }

    /**
     * Checks the board for a winning condition.
     * @return 'X' if X wins, 'O' if O wins, or ' ' if no one has won.
     */
    private static char checkWinner(char[][] board) {
        // Check Rows
        for (int i = 0; i < BOARD_SIZE; i++) {
            if (board[i][0] != '.' && board[i][0] == board[i][1] && board[i][0] == board[i][2]) {
                return board[i][0];
            }
        }

        // Check Columns
        for (int j = 0; j < BOARD_SIZE; j++) {
            if (board[0][j] != '.' && board[0][j] == board[1][j] && board[0][j] == board[2][j]) {
                return board[0][j];
            }
        }

        // Check Diagonals
        if (board[0][0] != '.' && board[0][0] == board[1][1] && board[0][0] == board[2][2]) {
            return board[0][0];
        }
        if (board[0][2] != '.' && board[0][2] == board[1][1] && board[0][2] == board[2][0]) {
            return board[0][2];
        }

        return ' '; // No winner
    }
}

