import java.util.Scanner;

public class TicTacToe {
    private static final int BOARD_SIZE = 3;

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        char[][] board = new char[BOARD_SIZE][BOARD_SIZE];

        // Read the 3x3 board from input
        for (int i = 0; i < BOARD_SIZE; i++) {
            String row = scanner.next();
            if (row.length() != BOARD_SIZE) {
                throw new IllegalArgumentException("Each row must contain exactly 3 characters.");
            }
            // Normalize '0' to 'O' for consistent handling throughout the logic
            board[i] = row.replace('0', 'O').toCharArray();
        }

        // Validate the board state and print the result
        System.out.println(validateGame(board));
    }

    /**
     * Validates the Tic-Tac-Toe board according to standard rules and returns the game status.
     */
    private static String validateGame(char[][] board) {
        int xCount = 0;
        int oCount = 0;

        // Count the number of X and O marks on the board
        for (char[] row : board) {
            for (char cell : row) {
                if (cell == 'X') {
                    xCount++;
                } else if (cell == 'O') {
                    oCount++;
                }
            }
        }

        // Rule 1: X always goes first. Valid counts: xCount == oCount or xCount == oCount + 1
        if (oCount > xCount || xCount > oCount + 1) {
            return "illegal";
        }

        boolean xWins = checkWin(board, 'X');
        boolean oWins = checkWin(board, 'O');

        // Rule 2: Both players cannot win simultaneously
        if (xWins && oWins) {
            return "illegal";
        }

        // Rule 3: If X wins, X must have made the last move (xCount == oCount + 1)
        if (xWins) {
            return (xCount == oCount + 1) ? "the first player won" : "illegal";
        }

        // Rule 4: If O wins, O must have made the last move (xCount == oCount)
        if (oWins) {
            return (xCount == oCount) ? "the second player won" : "illegal";
        }

        // Rule 5: If the board is full and no one won, it's a draw
        if (xCount + oCount == BOARD_SIZE * BOARD_SIZE) {
            return "draw";
        }

        // Rule 6: The game is still in progress
        if (xCount == oCount) {
            return "first"; // X's turn
        } else {
            return "second"; // O's turn
        }
    }

    /**
     * Checks if the specified player has achieved a winning line.
     */
    private static boolean checkWin(char[][] board, char player) {
        // Check rows
        for (int i = 0; i < BOARD_SIZE; i++) {
            if (board[i][0] == player && board[i][1] == player && board[i][2] == player) {
                return true;
            }
        }

        // Check columns
        for (int j = 0; j < BOARD_SIZE; j++) {
            if (board[0][j] == player && board[1][j] == player && board[2][j] == player) {
                return true;
            }
        }

        // Check main diagonal
        if (board[0][0] == player && board[1][1] == player && board[2][2] == player) {
            return true;
        }

        // Check anti-diagonal
        if (board[0][2] == player && board[1][1] == player && board[2][0] == player) {
            return true;
        }

        return false;
    }
}

import java.util.Scanner;

public class Main {
    // Constants for board configuration and players
    private static final int BOARD_SIZE = 3;
    private static final char PLAYER_X = 'X';
    private static final char PLAYER_O = 'O'; // Corrected from '0' (zero) to 'O' (letter)
    private static final char EMPTY = '.';

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        try {
            // Validate input availability
            if (!scanner.hasNext() || !scanner.hasNext() || !scanner.hasNext()) {
                System.err.println("Error: Expected three strings as input.");
                return;
            }

            String row1 = scanner.next();
            String row2 = scanner.next();
            String row3 = scanner.next();

            evaluateGame(row1, row2, row3);
        } finally {
            scanner.close();
        }
    }

    /**
     * Parses the three input strings into a 3x3 character board.
     */
    private static char[][] parseBoard(String r1, String r2, String r3) {
        if (r1.length() != BOARD_SIZE || r2.length() != BOARD_SIZE || r3.length() != BOARD_SIZE) {
            throw new IllegalArgumentException("Each row must be exactly 3 characters long.");
        }
        char[][] board = new char[BOARD_SIZE][BOARD_SIZE];
        board[0] = r1.toCharArray();
        board[1] = r2.toCharArray();
        board[2] = r3.toCharArray();
        return board;
    }

    /**
     * Evaluates the current state of the board and prints the appropriate result.
     */
    public static void evaluateGame(String r1, String r2, String r3) {
        char[][] board = parseBoard(r1, r2, r3);
        BoardState state = analyzeBoard(board);
        boolean xWins = hasWon(board, PLAYER_X);
        boolean oWins = hasWon(board, PLAYER_O);

        if (isIllegal(state, xWins, oWins)) {
            System.out.println("illegal");
        } else if (xWins) {
            System.out.println("the first player won");
        } else if (oWins) {
            System.out.println("the second player won");
        } else if (state.emptyCount == 0) {
            System.out.println("draw");
        } else if (state.xCount == state.oCount) {
            System.out.println("first");
        } else {
            System.out.println("second");
        }
    }

    /**
     * Counts the occurrences of X, O, and empty spaces on the board.
     */
    private static BoardState analyzeBoard(char[][] board) {
        int xCount = 0;
        int oCount = 0;
        int emptyCount = 0;

        for (char[] row : board) {
            for (char cell : row) {
                switch (cell) {
                    case PLAYER_X: xCount++; break;
                    case PLAYER_O: oCount++; break;
                    case EMPTY: emptyCount++; break;
                    default: throw new IllegalArgumentException("Invalid character on board: " + cell);
                }
            }
        }
        return new BoardState(xCount, oCount, emptyCount);
    }

    /**
     * Checks if the current move counts and win conditions constitute an illegal state.
     */
    private static boolean isIllegal(BoardState state, boolean xWins, boolean oWins) {
        // O cannot have played more moves than X
        if (state.oCount > state.xCount) return true;
        // X cannot have played more than one extra move
        if (state.xCount - state.oCount > 1) return true;
        // If X wins, they must have played exactly one more move than O
        if (xWins && state.xCount != state.oCount + 1) return true;
        // If O wins, they must have played the same number of moves as X
        if (oWins && state.xCount != state.oCount) return true;
        // Both players cannot win simultaneously
        if (xWins && oWins) return true;

        return false;
    }

    /**
     * Checks if a specific player has won the game.
     */
    private static boolean hasWon(char[][] board, char player) {
        // Check rows
        for (int i = 0; i < BOARD_SIZE; i++) {
            if (board[i][0] == player && board[i][1] == player && board[i][2] == player) {
                return true;
            }
        }
        // Check columns
        for (int j = 0; j < BOARD_SIZE; j++) {
            if (board[0][j] == player && board[1][j] == player && board[2][j] == player) {
                return true;
            }
        }
        // Check diagonals
        if (board[0][0] == player && board[1][1] == player && board[2][2] == player) return true;
        if (board[0][2] == player && board[1][1] == player && board[2][0] == player) return true;

        return false;
    }

    /**
     * Simple data class to hold board state counts.
     */
    private static class BoardState {
        final int xCount;
        final int oCount;
        final int emptyCount;

        BoardState(int xCount, int oCount, int emptyCount) {
            this.xCount = xCount;
            this.oCount = oCount;
            this.emptyCount = emptyCount;
        }
    }
}

