        Scanner scanner = new Scanner(System.in);
        while (scanner.hasNext()) {
            int[][] board = new int[GRID_SIZE][GRID_SIZE];

            // Parse the 3x3 board from input
            for (int i = 0; i < GRID_SIZE; i++) {
                String row = scanner.next();
                for (int j = 0; j < GRID_SIZE; j++) {
                    char cell = row.charAt(j);
                    if (cell == '.') {
                        board[i][j] = EMPTY;
                    } else if (cell == 'X') {
                        board[i][j] = PLAYER1;
                    } else if (cell == '0') {
                        board[i][j] = PLAYER2;
                    }
                }
            }

            int player1Count = countTokens(board, PLAYER1);
            int player2Count = countTokens(board, PLAYER2);
            int player1Wins = countWins(board, PLAYER1);
            int player2Wins = countWins(board, PLAYER2);

            int resultIndex = evaluateGameState(player1Count, player2Count, player1Wins, player2Wins);
            System.out.println(RESULTS[resultIndex]);
        }
        scanner.close();
    }

    /**
     * Counts the number of tokens belonging to a specific player on the board.
     */
    private static int countTokens(int[][] board, int player) {
        int count = 0;
        for (int[] row : board) {
            for (int cell : row) {
                if (cell == player) {
                    count++;
                }
            }
        }
        return count;
    }

    /**
     * Counts the number of winning lines (rows, columns, diagonals) for a player.
     */
    private static int countWins(int[][] board, int player) {
        int wins = 0;
        // Check rows and columns
        for (int i = 0; i < GRID_SIZE; i++) {
            if (isWinningLine(board[i][0], board[i][1], board[i][2], player)) {
                wins++;
            }
            if (isWinningLine(board[0][i], board[1][i], board[2][i], player)) {
                wins++;
            }
        }
        // Check diagonals
        if (isWinningLine(board[0][0], board[1][1], board[2][2], player)) {
            wins++;
        }
        if (isWinningLine(board[0][2], board[1][1], board[2][0], player)) {
            wins++;
        }
        return wins;
    }

    /**
     * Helper method to check if three cells form a winning line.
     */
    private static boolean isWinningLine(int a, int b, int c, int player) {
        return a == player && b == player && c == player;
    }

    /**
     * Evaluates the game state based on token counts and win counts.
     * Returns an index into the RESULTS array.
     */
    private static int evaluateGameState(int p1Count, int p2Count, int p1Wins, int p2Wins) {
        if (p1Wins == 0 && p2Wins == 0) {
            if (p1Count == p2Count) return 1; // "first"
            if (p1Count == p2Count + 1) return 2; // "second"
            if (p1Count == 5 && p2Count == 4) return 5; // "draw"
        } else if (p1Wins == 1 && p2Wins == 0) {
            if (p1Count == p2Count + 1) return 3; // "the first player won"
        } else if (p1Wins == 0 && p2Wins == 1) {
            if (p1Count == p2Count) return 4; // "the second player won"
        }

        // Handle edge case where player 1 has two winning lines and the board is full
        if (p1Wins == 2 && p1Count == 5 && p2Count == 4) return 3;

        return 0; // "illegal"
    }
}

import java.io.*;
import java.util.StringTokenizer;

public class Main {

    // Constants for board configuration and output messages
    private static final int BOARD_SIZE = 3;
    private static final char PLAYER_X = 'X';
    private static final char PLAYER_O = '0'; // Note: Input specification uses digit '0'
    private static final char EMPTY = '.';

    private static final String MSG_ILLEGAL = "illegal";
    private static final String MSG_X_WON = "the first player won";
    private static final String MSG_O_WON = "the second player won";
    private static final String MSG_DRAW = "draw";
    private static final String MSG_FIRST = "first";
    private static final String MSG_SECOND = "second";

    public static void main(String[] args) {
        SpeedScanner scanner = new SpeedScanner();
        PrintWriter out = new PrintWriter(System.out);
        try {
            solveGame(scanner, out);
        } finally {
            out.flush();
            out.close();
        }
    }

    /**
     * Orchestrates the game state validation and output.
     */
    private static void solveGame(SpeedScanner scanner, PrintWriter out) {
        char[][] board = new char[BOARD_SIZE][BOARD_SIZE];
        int xCount = 0;
        int oCount = 0;
        int emptyCount = 0;

        // Read board rows and count pieces in a single pass
        for (int r = 0; r < BOARD_SIZE; r++) {
            String line = scanner.nextToken();
            for (int c = 0; c < line.length(); c++) {
                char ch = line.charAt(c);
                board[r][c] = ch;
                if (ch == PLAYER_X) {
                    xCount++;
                } else if (ch == PLAYER_O) {
                    oCount++;
                } else if (ch == EMPTY) {
                    emptyCount++;
                }
            }
        }

        // Validate move counts against Tic-Tac-Toe rules
        if (xCount - oCount > 1 || oCount > xCount) {
            out.print(MSG_ILLEGAL);
            return;
        }

        boolean xWins = hasWon(board, PLAYER_X);
        boolean oWins = hasWon(board, PLAYER_O);

        // Determine final game state
        if (xWins && oWins) {
            out.print(MSG_ILLEGAL);
        } else if (xWins) {
            out.print(xCount == oCount + 1 ? MSG_X_WON : MSG_ILLEGAL);
        } else if (oWins) {
            out.print(xCount == oCount ? MSG_O_WON : MSG_ILLEGAL);
        } else if (emptyCount == 0) {
            out.print(MSG_DRAW);
        } else {
            out.print(xCount == oCount ? MSG_FIRST : MSG_SECOND);
        }
    }

    /**
     * Checks if a specific player has won on the board.
     */
    private static boolean hasWon(char[][] board, char player) {
        // Check rows
        for (int r = 0; r < BOARD_SIZE; r++) {
            if (board[r][0] == player && board[r][1] == player && board[r][2] == player) {
                return true;
            }
        }
        // Check columns
        for (int c = 0; c < BOARD_SIZE; c++) {
            if (board[0][c] == player && board[1][c] == player && board[2][c] == player) {
                return true;
            }
        }
        // Check diagonals
        if (board[0][0] == player && board[1][1] == player && board[2][2] == player) {
            return true;
        }
        if (board[0][2] == player && board[1][1] == player && board[2][0] == player) {
            return true;
        }
        return false;
    }

    /**
     * Fast input reader utility (preserved from original, with improved error handling)
     */
    public static class SpeedScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public SpeedScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String nextToken() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) {
                        return null;
                    }
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input", e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(nextToken());
        }

        long nextLong() {
            return Long.parseLong(nextToken());
        }

        double nextDouble() {
            return Double.parseDouble(nextToken());
        }
    }
}

import java.io.BufferedReader;
import java.io.FileInputStream;
import java.io.IOException;
import java.io.InputStreamReader;

public class Main {
    // Constants to replace magic numbers and characters
    private static final char PLAYER_X = 'X';
    private static final char PLAYER_O = '0'; // Input uses '0' (zero)
    private static final char EMPTY = '.';
    private static final int BOARD_SIZE = 3;

    public static void main(String[] args) throws IOException {
        // Configuration for input source
        String inputSource = "System.in";

        // Use try-with-resources to ensure the reader is closed properly
        try (BufferedReader reader = createReader(inputSource)) {
            // 1. Read and Validate Board Structure
            char[][] board = readBoard(reader);

            // 2. Analyze Board State
            GameAnalysis analysis = analyzeBoard(board);

            // 3. Output Result
            System.out.println(analysis.getResultMessage());
        } catch (IOException e) {
            // Handle file reading errors
            System.err.println("Error reading input: " + e.getMessage());
            System.out.println("illegal");
        } catch (Exception e) {
            // Catch parsing errors (e.g., invalid characters, short lines)
            System.out.println("illegal");
        }
    }

    /**
     * Creates a BufferedReader based on the input source configuration.
     */
    private static BufferedReader createReader(String source) throws IOException {
        if ("System.in".equals(source)) {
            return new BufferedReader(new InputStreamReader(System.in));
        } else {
            return new BufferedReader(new InputStreamReader(new FileInputStream(source)));
        }
    }

    /**
     * Reads the 3x3 board from the input stream.
     * Validates that each line has at least 3 characters and contains valid symbols.
     */
    private static char[][] readBoard(BufferedReader reader) throws IOException {
        char[][] board = new char[BOARD_SIZE][BOARD_SIZE];
        String line;

        for (int i = 0; i < BOARD_SIZE; i++) {
            line = reader.readLine();
            if (line == null) {
                throw new IOException("Unexpected end of input");
            }
            if (line.length() < BOARD_SIZE) {
                throw new IOException("Line too short");
            }

            for (int j = 0; j < BOARD_SIZE; j++) {
                char c = line.charAt(j);
                // Validate character
                if (c != PLAYER_X && c != PLAYER_O && c != EMPTY) {
                    throw new IllegalArgumentException("Invalid character: " + c);
                }
                board[i][j] = c;
            }
        }
        return board;
    }

    /**
     * Analyzes the board state to determine the game status.
     * Returns a GameAnalysis object containing the result string.
     */
    private static GameAnalysis analyzeBoard(char[][] board) {
        int countX = 0;
        int countO = 0;
        boolean isFull = true;

        // Count pieces and check if board is full
        for (int i = 0; i < BOARD_SIZE; i++) {
            for (int j = 0; j < BOARD_SIZE; j++) {
                char c = board[i][j];
                if (c == PLAYER_X) countX++;
                else if (c == PLAYER_O) countO++;
                else isFull = false;
            }
        }

        // Rule 1: Validate Move Counts
        // O cannot have more moves than X
        if (countO > countX) {
            return new GameAnalysis("illegal");
        }
        // X cannot have more than one move than O
        if (countX > countO + 1) {
            return new GameAnalysis("illegal");
        }
        // If board is full, specific counts (5 X, 4 O) are required
        if (isFull && !(countX == 5 && countO == 4)) {
            return new GameAnalysis("illegal");
        }

        // Rule 2: Check for Winners
        boolean xWon = false;
        boolean oWon = false;

        // Check Rows
        for (int i = 0; i < BOARD_SIZE; i++) {
            if (board[i][0] != EMPTY && board[i][0] == board[i][1] && board[i][1] == board[i][2]) {
                if (board[i][0] == PLAYER_X) xWon = true;
                else oWon = true;
            }
        }

        // Check Columns
        for (int j = 0; j < BOARD_SIZE; j++) {
            if (board[0][j] != EMPTY && board[0][j] == board[1][j] && board[1][j] == board[2][j]) {
                if (board[0][j] == PLAYER_X) xWon = true;
                else oWon = true;
            }
        }

        // Check Diagonals
        if (board[0][0] != EMPTY && board[0][0] == board[1][1] && board[1][1] == board[2][2]) {
            if (board[0][0] == PLAYER_X) xWon = true;
            else oWon = true;
        }
        if (board[0][2] != EMPTY && board[0][2] == board[1][1] && board[1][1] == board[2][0]) {
            if (board[0][2] == PLAYER_X) xWon = true;
            else oWon = true;
        }

        // If both players have winning lines, the state is illegal
        if (xWon && oWon) {
            return new GameAnalysis("illegal");
        }

        // Rule 3: Determine Outcome based on Winner and Counts
        if (xWon) {
            // If X won, X must have played exactly one more move than O
            if (countX == countO + 1) {
                return new GameAnalysis("the first player won");
            } else {
                return new GameAnalysis("illegal");
            }
        } else if (oWon) {
            // If O won, move counts must be equal
            if (countX == countO) {
                return new GameAnalysis("the second player won");
            } else {
                return new GameAnalysis("illegal");
            }
        } else {
            // No winner
            if (isFull) {
                return new GameAnalysis("draw");
            } else {
                // Determine whose turn it is
                if (countX == countO) {
                    return new GameAnalysis("first"); // X's turn (First player)
                } else if (countX == countO + 1) {
                    return new GameAnalysis("second"); // O's turn (Second player)
                } else {
                    return new GameAnalysis("illegal");
                }
            }
        }
    }

    /**
     * Helper class to encapsulate the analysis result.
     */
    private static class GameAnalysis {
        private final String resultMessage;

        public GameAnalysis(String resultMessage) {
            this.resultMessage = resultMessage;
        }

        public String getResultMessage() {
            return resultMessage;
        }
    }
}

import java.util.Scanner;

/**
 * Analyzes a Tic-Tac-Toe board state to determine validity, winner, or next player.
 */
public class TicTacToeAnalyzer {
    private static final int BOARD_SIZE = 3;
    private static final char PLAYER_X = 'X';
    private static final char PLAYER_O = 'O'; // Corrected from '0' (zero) to 'O' (letter) for standard compliance

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        char[][] board = new char[BOARD_SIZE][BOARD_SIZE];

        // Read the 3x3 board from input
        for (int i = 0; i < BOARD_SIZE; i++) {
            if (!scanner.hasNext()) {
                System.out.println("illegal");
                return;
            }
            String line = scanner.next();
            if (line.length() != BOARD_SIZE) {
                System.out.println("illegal");
                return;
            }
            board[i] = line.toCharArray();
        }

        evaluateBoard(board);
    }

    private static void evaluateBoard(char[][] board) {
        int countX = 0;
        int countO = 0;

        // Count player moves
        for (char[] row : board) {
            for (char cell : row) {
                if (cell == PLAYER_X) {
                    countX++;
                } else if (cell == PLAYER_O) {
                    countO++;
                }
            }
        }

        boolean xWon = hasWon(board, PLAYER_X);
        boolean oWon = hasWon(board, PLAYER_O);

        // Validate game state according to Tic-Tac-Toe rules
        if (countO > countX || countX - countO > 1 ||
            (xWon && oWon) || (oWon && countO < countX) || (xWon && countX - countO != 1)) {
            System.out.println("illegal");
            return;
        }

        // Determine outcome
        if (xWon) {
            System.out.println("the first player won");
        } else if (oWon) {
            System.out.println("the second player won");
        } else if (countX == 5) { // Full board implies draw
            System.out.println("draw");
        } else if (countX - countO == 1) {
            System.out.println("second"); // Next turn: second player
        } else if (countX - countO == 0) {
            System.out.println("first"); // Next turn: first player
        }
    }

    /**
     * Checks if the given player has won the game.
     */
    private static boolean hasWon(char[][] board, char player) {
        // Check rows
        for (int i = 0; i < BOARD_SIZE; i++) {
            if (board[i][0] == player && board[i][1] == player && board[i][2] == player) {
                return true;
            }
        }
        // Check columns
        for (int i = 0; i < BOARD_SIZE; i++) {
            if (board[0][i] == player && board[1][i] == player && board[2][i] == player) {
                return true;
            }
        }
        // Check diagonals
        if (board[0][0] == player && board[1][1] == player && board[2][2] == player) {
            return true;
        }
        if (board[0][2] == player && board[1][1] == player && board[2][0] == player) {
            return true;
        }
        return false;
    }
}

import java.io.BufferedReader;
