import java.util.StringTokenizer;

/**
 * Validates a Tic-Tac-Toe board state and determines the game result.
 * 
 * Refactoring improvements:
 * - Replaced magic numbers with descriptive constants.
 * - Extracted win-checking logic into a dedicated method.
 * - Removed duplicated counting loops.
 * - Fixed inconsistent naming (e.g., cnt1 -> xCount).
 * - Corrected likely typo: '0' (digit) -> 'O' (letter).
 * - Removed unnecessary Thread/Runnable overhead.
 * - Encapsulated fast I/O in a clean helper class.
 * - Applied proper exception handling and resource management.
 */
public class TicTacToeValidator {

    private static final int BOARD_SIZE = 3;
    private static final int TOTAL_CELLS = BOARD_SIZE * BOARD_SIZE;

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            solve(scanner, out);
        } catch (IOException e) {
            e.printStackTrace();
        } finally {
            out.flush();
        }
    }

    private static void solve(FastScanner scanner, PrintWriter out) throws IOException {
        char[][] board = new char[BOARD_SIZE][BOARD_SIZE];
        int xCount = 0;
        int oCount = 0;

        // Read board and count marks
        for (int i = 0; i < BOARD_SIZE; i++) {
            String line = scanner.next();
            if (line == null) break;
            board[i] = line.toCharArray();
            for (char cell : board[i]) {
                if (cell == 'X') {
                    xCount++;
                } else if (cell == 'O') {
                    oCount++;
                }
            }
        }

        // Rule 1: Turn counts must be valid (X goes first, so X == O or X == O + 1)
        if (oCount > xCount || xCount > oCount + 1) {
            out.println("illegal");
            return;
        }

        boolean xWins = checkWin(board, 'X');
        boolean oWins = checkWin(board, 'O');

        // Rule 2: Both players cannot win simultaneously
        if (xWins && oWins) {
            out.println("illegal");
            return;
        }

        // Rule 3: If X wins, X must have played one more move than O
        if (xWins && xCount != oCount + 1) {
            out.println("illegal");
            return;
        }

        // Rule 4: If O wins, counts must be equal
        if (oWins && xCount != oCount) {
            out.println("illegal");
            return;
        }

        // Determine result
        if (xWins) {
            out.println("the first player won");
        } else if (oWins) {
            out.println("the second player won");
        } else if (xCount + oCount == TOTAL_CELLS) {
            out.println("draw");
        } else {
            // Incomplete game: indicate whose turn is next
            out.println(xCount > oCount ? "second" : "first");
        }
    }

    /**
     * Checks if the specified player has a winning line on the board.
     */
    private static boolean checkWin(char[][] board, char player) {
        // Check rows
        for (int i = 0; i < BOARD_SIZE; i++) {
            if (board[i][0] == player && board[i][1] == player && board[i][2] == player) {
                return true;
            }
        }
        // Check columns
        for (int j = 0; j < BOARD_SIZE; j++) {
            if (board[0][j] == player && board[1][j] == player && board[2][j] == player) {
                return true;
            }
        }
        // Check main diagonal
        if (board[0][0] == player && board[1][1] == player && board[2][2] == player) {
            return true;
        }
        // Check anti-diagonal
        if (board[0][2] == player && board[1][1] == player && board[2][0] == player) {
            return true;
        }
        return false;
    }

    /**
     * Lightweight helper for fast input reading.
     */
    private static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        public String next() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) {
                    return null;
                }
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }
    }
}

import java.io.PrintWriter;
import java.util.Scanner;

public class TicTacToeSolver {
    // Configuration constants
    private static final int BOARD_SIZE = 3;
    private static final char PLAYER_X = 'X';
    private static final char PLAYER_O = '0'; // Note: Problem specification uses '0' (zero)
    private static final char EMPTY = '.';

    /**
     * Represents the possible states of the board.
     * Mapped to the original return codes for direct compatibility.
     */
    private enum GameState {
        ILLEGAL(-1),
        FIRST_TO_MOVE(0),
        SECOND_TO_MOVE(1),
        DRAW(5),
        FIRST_WINS(3),
        SECOND_WINS(4);

        private final int code;
        GameState(int code) { this.code = code; }
        int getCode() { return code; }
    }

    private final Scanner in;
    private final PrintWriter out;

    public TicTacToeSolver(Scanner in, PrintWriter out) {
        this.in = in;
        this.out = out;
    }

    public void solve() {
        char[][] board = readBoard();
        GameState state = evaluateBoard(board);

        switch (state) {
            case ILLEGAL:
                out.println("illegal");
                break;
            case FIRST_TO_MOVE:
                out.println("first");
                break;
            case SECOND_TO_MOVE:
                out.println("second");
                break;
            case DRAW:
                out.println("draw");
                break;
            case FIRST_WINS:
                out.println(isWinValid(board, PLAYER_X) ? "the first player won" : "illegal");
                break;
            case SECOND_WINS:
                out.println(isWinValid(board, PLAYER_O) ? "the second player won" : "illegal");
                break;
        }
        out.flush();
    }

    private char[][] readBoard() {
        char[][] board = new char[BOARD_SIZE][BOARD_SIZE];
        for (int i = 0; i < BOARD_SIZE; i++) {
            board[i] = in.next().toCharArray();
        }
        return board;
    }

    /**
     * Validates move counts, checks for wins, and determines the current game state.
     */
    private GameState evaluateBoard(char[][] board) {
        int xCount = countPlayer(board, PLAYER_X);
        int oCount = countPlayer(board, PLAYER_O);

        // Rule 1: Move count must be valid (X goes first, so xCount == oCount or xCount == oCount + 1)
        if (xCount < oCount || xCount - oCount > 1) {
            return GameState.ILLEGAL;
        }

        boolean xWins = checkWin(board, PLAYER_X);
        boolean oWins = checkWin(board, PLAYER_O);

        // Rule 2: Both players cannot win simultaneously
        if (xWins && oWins) {
            return GameState.ILLEGAL;
        }

        // Rule 3: Win conditions must align with move counts
        if (xWins && xCount == oCount) {
            return GameState.ILLEGAL; // X cannot win if counts are equal
        }
        if (oWins && xCount > oCount) {
            return GameState.ILLEGAL; // O cannot win if X has made one more move
        }

        // Rule 4: Determine final state
        if (xWins) return GameState.FIRST_WINS;
        if (oWins) return GameState.SECOND_WINS;
        if (xCount + oCount == BOARD_SIZE * BOARD_SIZE) return GameState.DRAW;

        return xCount == oCount ? GameState.FIRST_TO_MOVE : GameState.SECOND_TO_MOVE;
    }

    private int countPlayer(char[][] board, char player) {
        int count = 0;
        for (char[] row : board) {
            for (char cell : row) {
                if (cell == player) {
                    count++;
                }
            }
        }
        return count;
    }

    /**
     * Checks if a player has won by examining all rows, columns, and diagonals.
     */
    private boolean checkWin(char[][] board, char player) {
        // Check rows and columns
        for (int i = 0; i < BOARD_SIZE; i++) {
            if (isLineWin(board, i, 0, 1, 0, player) || isLineWin(board, 0, i, 0, 1, player)) {
                return true;
            }
        }
        // Check diagonals
        return isLineWin(board, 0, 0, 1, 1, player) || 
               isLineWin(board, 0, BOARD_SIZE - 1, 1, -1, player);
    }

    /**
     * Checks if a specific line (row, column, or diagonal) is won by a player.
     */
    private boolean isLineWin(char[][] board, int rStart, int cStart, int rStep, int cStep, char player) {
        for (int i = 0; i < BOARD_SIZE; i++) {
            if (board[rStart + i * rStep][cStart + i * cStep] != player) {
                return false;
            }
        }
        return true;
    }

    /**
     * Validates a win state by backtracking one move.
     * If removing ANY winning piece breaks the win condition, the state is valid.
     * If removing ALL winning pieces still results in a win, the state is illegal (multiple winning lines).
     */
    private boolean isWinValid(char[][] board, char winner) {
        boolean anyRemovalBreaksWin = false;
        for (int i = 0; i < BOARD_SIZE; i++) {
            for (int j = 0; j < BOARD_SIZE; j++) {
                if (board[i][j] == winner) {
                    board[i][j] = EMPTY;
                    boolean stillWins = checkWin(board, winner);
                    board[i][j] = winner; // Restore board state
                    if (!stillWins) {
                        anyRemovalBreaksWin = true;
                    }
                }
            }
        }
        return anyRemovalBreaksWin;
    }

    public static void main(String[] args) {
        // Resource management handled via try-with-resources
        try (Scanner in = new Scanner(System.in)) {
            PrintWriter out = new PrintWriter(System.out);
            new TicTacToeSolver(in, out).solve();
        }
    }
}

