/**
 * Encapsulates all business logic for validating a Tic-Tac-Toe board state.
 * Separates I/O from core rules to improve testability and maintainability.
 */
class TicTacToeValidator {
    private static final int BOARD_SIZE = 3;
    private static final char EMPTY = '.';
    private static final char PLAYER_X = 'X';
    private static final char PLAYER_O = 'O';

    /**
     * Validates the board state and returns the appropriate game status string.
     */
    public String validate(char[][] board, boolean isFull) {
        int xCount = countPlayer(board, PLAYER_X);
        int oCount = countPlayer(board, PLAYER_O);

        // Rule 1: Move counts must be valid (X always goes first)
        if (oCount > xCount || xCount > oCount + 1) {
            return "illegal";
        }

        boolean xWins = hasWon(board, PLAYER_X);
        boolean oWins = hasWon(board, PLAYER_O);

        // Rule 2: Both players cannot win simultaneously
        if (xWins && oWins) {
            return "illegal";
        }

        // Rule 3: If X wins, X must have made exactly one more move than O
        if (xWins && xCount != oCount + 1) {
            return "illegal";
        }

        // Rule 4: If O wins, move counts must be equal
        if (oWins && xCount != oCount) {
            return "illegal";
        }

        // Determine outcome based on a valid state
        if (xWins) {
            return "the first player won";
        }
        if (oWins) {
            return "the second player won";
        }
        if (isFull) {
            return "draw";
        }
        if (xCount == oCount) {
            return "first";
        }
        if (xCount == oCount + 1) {
            return "second";
        }

        return "illegal";
    }

    /**
     * Counts the occurrences of a specific player's marks on the board.
     */
    private int countPlayer(char[][] board, char player) {
        int count = 0;
        for (char[] row : board) {
            for (char cell : row) {
                if (cell == player) {
                    count++;
                }
            }
        }
        return count;
    }

    /**
     * Checks if a specific player has achieved a winning line.
     */
    private boolean hasWon(char[][] board, char player) {
        // Check rows
        for (int i = 0; i < BOARD_SIZE; i++) {
            if (board[i][0] == player && board[i][1] == player && board[i][2] == player) {
                return true;
            }
        }
        // Check columns
        for (int j = 0; j < BOARD_SIZE; j++) {
            if (board[0][j] == player && board[1][j] == player && board[2][j] == player) {
                return true;
            }
        }
        // Check diagonals
        if (board[0][0] == player && board[1][1] == player && board[2][2] == player) {
            return true;
        }
        if (board[0][2] == player && board[1][1] == player && board[2][0] == player) {
            return true;
        }
        return false;
    }
}

