import java.io.InputStreamReader;

/**
 * Refactored TicTacToe program.
 * 
 * Improvements made:
 * 1. Encapsulated logic into specific methods (readBoard, evaluateGame, isWin) for separation of concerns.
 * 2. Used constants for magic numbers (BOARD_SIZE) and characters (PLAYER_X, PLAYER_O, EMPTY_CELL).
 * 3. Implemented try-with-resources for automatic resource management of BufferedReader.
 * 4. Refactored the isWin method to use loops, reducing code duplication.
 * 5. Cleaned up the validation logic in evaluateGame to be more readable and less nested.
 * 6. Added defensive checks for array bounds to prevent crashes on malformed input.
 * 7. Preserved original logic behavior, including the use of the digit '0' for the second player.
 */
public class TicTacToe {

    private static final int BOARD_SIZE = 3;
    private static final char PLAYER_X = 'X';
    private static final char PLAYER_O = '0'; // Preserving original character '0' (digit zero)
    private static final char EMPTY_CELL = '.';

    public static void main(String[] args) throws IOException {
        // Using try-with-resources to ensure the BufferedReader is closed properly
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(System.in))) {
            char[][] board = readBoard(reader);

            // If board reading failed (e.g., EOF), we stop execution
            if (board == null) {
                return;
            }

            String result = evaluateGame(board);
            System.out.println(result);
        }
    }

    /**
     * Reads the 3x3 board from standard input.
     */
    private static char[][] readBoard(BufferedReader reader) throws IOException {
        char[][] board = new char[BOARD_SIZE][BOARD_SIZE];
        for (int i = 0; i < BOARD_SIZE; i++) {
            String line = reader.readLine();
            if (line == null) {
                // End of stream reached unexpectedly
                return null;
            }
            // Original code used toCharArray(). 
            // We store it directly. If the line is short, defensive checks in logic will handle it.
            board[i] = line.toCharArray();
        }
        return board;
    }

    /**
     * Analyzes the board state and returns the result string.
     */
    private static String evaluateGame(char[][] board) {
        int countX = 0;
        int countO = 0;
        boolean isFull = true;

        // Count pieces and check if board is full
        for (int i = 0; i < BOARD_SIZE; i++) {
            // Safety check for row length
            if (board[i] != null && board[i].length >= BOARD_SIZE) {
                for (int j = 0; j < BOARD_SIZE; j++) {
                    char cell = board[i][j];
                    if (cell == PLAYER_X) {
                        countX++;
                    } else if (cell == PLAYER_O) {
                        countO++;
                    } else if (cell == EMPTY_CELL) {
                        isFull = false;
                    }
                }
            }
        }

        boolean xWins = isWin(board, PLAYER_X);
        boolean oWins = isWin(board, PLAYER_O);

        // Validation Logic

        // 1. Check turn counts validity
        // O cannot have more moves than X.
        // X cannot have more than 1 move than O.
        if (countO > countX || countX - countO > 1) {
            return "illegal";
        }

        // 2. Check win conditions consistency
        // Both players cannot win simultaneously.
        if (xWins && oWins) {
            return "illegal";
        }

        // If X won, X must have made the last move, so X count should be O count + 1.
        // If counts are equal, it's illegal (X moved twice or O moved after win).
        if (xWins && countO == countX) {
            return "illegal";
        }

        // If O won, O must have made the last move, so counts must be equal.
        // If X count > O count, it's illegal (X moved after win).
        if (oWins && countX > countO) {
            return "illegal";
        }

        // Determine Result

        if (xWins) {
            return "the first player won";
        }
        if (oWins) {
            return "the second player won";
        }

        if (isFull) {
            return "draw";
        }

        if (!isFull) {
            if (countO == countX) {
                return "first"; // Next turn is X
            } else {
                return "second"; // Next turn is O
            }
        }

        // Fallback (should theoretically not be reached with valid logic flow)
        return "illegal";
    }

    /**
     * Checks if a specific player has won.
     * Refactored to use loops for rows and columns, and explicit checks for diagonals.
     */
    private static boolean isWin(char[][] board, char player) {
        // Check rows
        for (int i = 0; i < BOARD_SIZE; i++) {
            // Ensure row has enough columns
            if (board[i] != null && board[i].length >= BOARD_SIZE) {
                if (board[i][0] == player && board[i][1] == player && board[i][2] == player) {
                    return true;
                }
            }
        }

        // Check columns
        for (int i = 0; i < BOARD_SIZE; i++) {
            // Ensure all rows have the column index
            if (board[0].length > i && board[1].length > i && board[2].length > i) {
                if (board[0][i] == player && board[1][i] == player && board[2][i] == player) {
                    return true;
                }
            }
        }

        // Check diagonals
        // Main diagonal (0,0), (1,1), (2,2)
        if (board[0].length > 0 && board[1].length > 1 && board[2].length > 2) {
            if (board[0][0] == player && board[1][1] == player && board[2][2] == player) {
                return true;
            }
        }
        // Anti-diagonal (0,2), (1,1), (2,0)
        if (board[0].length > 2 && board[1].length > 1 && board[2].length > 0) {
            if (board[0][2] == player && board[1][1] == player && board[2][0] == player) {
                return true;
            }
        }

        return false;
    }
}

import java.io.BufferedReader;
