/**
 * Refactored Tic-Tac-Toe Board Analyzer.
 * 
 * Improvements made:
 * 1. Separation of Concerns: Logic is moved out of main() into specific methods.
 * 2. Readability: Replaced magic numbers and long boolean expressions with constants and helper methods.
 * 3. Maintainability: Winning conditions are defined in a data structure rather than hardcoded if-statements.
 * 4. Safety: Added null checks for input reading and resource management (try-with-resources).
 * 5. Variable Naming: Renamed variables to be more descriptive (e.g., xs -> xCount).
 */
public class Main {

    // Constants for game characters
    // Note: The original code uses digit '0' for the second player (O).
    private static final char PLAYER_X = 'X';
    private static final char PLAYER_O = '0'; 
    private static final char EMPTY_CELL = '.';

    // Winning combinations indices for a 3x3 grid (0-8)
    private static final int[][] WINNING_COMBINATIONS = {
        {0, 1, 2}, {3, 4, 5}, {6, 7, 8}, // Rows
        {0, 3, 6}, {1, 4, 7}, {2, 5, 8}, // Columns
        {0, 4, 8}, {2, 4, 6}             // Diagonals
    };

    public static void main(String[] args) {
        // Use try-with-resources for automatic resource management
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(System.in))) {
            String line1 = reader.readLine();
            String line2 = reader.readLine();
            String line3 = reader.readLine();

            // Handle potential nulls from EOF safely to prevent NullPointerException
            if (line1 == null) line1 = "";
            if (line2 == null) line2 = "";
            if (line3 == null) line3 = "";

            String boardStr = line1 + line2 + line3;

            // Analyze the board and print the result
            String result = analyzeBoard(boardStr);
            System.out.println(result);

        } catch (IOException e) {
            // In a production application, use a proper logger.
            System.err.println("Error reading input: " + e.getMessage());
        }
    }

    /**
     * Analyzes the board string to determine the game status.
     */
    private static String analyzeBoard(String board) {
        char[] cells = board.toCharArray();

        // Ensure the board has enough characters to be valid
        if (cells.length < 9) {
            // Original code would crash on short input; treating as illegal/invalid is safer
            return "illegal"; 
        }

        int xCount = 0;
        int oCount = 0;
        int emptyCount = 0;

        // Count moves and empty cells
        // Note: The original code treats any character other than 'X' or '0' as empty/period.
        for (int i = 0; i < 9; i++) {
            char c = cells[i];
            if (c == PLAYER_X) {
                xCount++;
            } else if (c == PLAYER_O) {
                oCount++;
            } else {
                emptyCount++;
            }
        }

        // Basic validity checks
        boolean isEmptyBoard = (xCount == 0 && oCount == 0);
        boolean isIllegal = false;

        // Invalid move counts: O cannot move before X, X cannot move twice in a row
        if (oCount > xCount || xCount > oCount + 1) {
            isIllegal = true;
        }

        boolean xWins = checkWin(cells, PLAYER_X);
        boolean oWins = checkWin(cells, PLAYER_O);

        // Win validity checks
        // 1. Both players cannot win
        if (oWins && xWins) {
            isIllegal = true;
        }
        // 2. If O wins, X cannot have made more moves (X moves first)
        if (oWins && xCount > oCount) {
            isIllegal = true;
        }
        // 3. If X wins, X must have made the last move, so X count must be O count + 1.
        // If xCount == oCount, it implies O moved after X won.
        if (xWins && xCount == oCount) {
            isIllegal = true;
        }

        // Determine result based on status
        if (isIllegal) {
            return "illegal";
        }

        if (isEmptyBoard) {
            return "first";
        }

        if (xWins) {
            return "the first player won";
        }

        if (oWins) {
            return "the second player won";
        }

        if (emptyCount == 0) {
            return "draw";
        }

        // Determine whose turn it is next
        // If xCount > oCount, X just moved, so it's O's turn (Second player)
        // If xCount == oCount, O just moved, so it's X's turn (First player)
        if (xCount > oCount) {
            return "second";
        } else {
            return "first";
        }
    }

    /**
     * Checks if the specified player has won on the board.
     */
    private static boolean checkWin(char[] board, char player) {
        for (int[] combo : WINNING_COMBINATIONS) {
            if (board[combo[0]] == player && 
                board[combo[1]] == player && 
                board[combo[2]] == player) {
                return true;
            }
        }
        return false;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.OutputStream;
import java.io.PrintWriter;
import java.util.StringTokenizer;

public class Main {
    private static final int BOARD_SIZE = 3;

    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);

        TicTacToeEvaluator solver = new TicTacToeEvaluator();
        solver.evaluate(1, in, out);

        out.close();
    }

    /**
     * Encapsulates all Tic-Tac-Toe board evaluation logic.
     */
    static class TicTacToeEvaluator {
        public void evaluate(int testNumber, InputReader in, PrintWriter out) {
            char[][] board = new char[BOARD_SIZE][BOARD_SIZE];
            int xCount = 0;
            int oCount = 0;

            // Read board and count players in a single pass for O(N) efficiency
            for (int i = 0; i < BOARD_SIZE; i++) {
                String row = in.next();
                board[i] = row.toCharArray();
                for (char c : board[i]) {
                    if (c == 'X') {
                        xCount++;
                    } else if (c == 'O') {
                        oCount++;
                    }
                }
            }

            // Rule 1: Turn count must be equal or X has exactly one more move than O
            if (xCount - oCount != 1 && xCount - oCount != 0) {
                out.println("illegal");
                return;
            }

            boolean xWins = hasWon(board, 'X');
            boolean oWins = hasWon(board, 'O');

            // Rule 2: Both players cannot win simultaneously
            if (xWins && oWins) {
                out.println("illegal");
                return;
            }

            // Rule 3: O wins only if counts are equal
            if (oWins) {
                if (oCount == xCount) {
                    out.println("the second player won");
                } else {
                    out.println("illegal");
                    return;
                }
            }
            // Rule 4: X wins only if X has one more move
            else if (xWins) {
                if (xCount > oCount) {
                    out.println("the first player won");
                } else {
                    out.println("illegal");
                    return;
                }
            }
            // Rule 5: No winner
            else {
                if (xCount + oCount == BOARD_SIZE * BOARD_SIZE) {
                    out.println("draw");
                } else if (xCount > oCount) {
                    out.println("second");
                } else {
                    out.println("first");
                }
            }
        }

        /**
         * Checks if a specific player has won the game.
         * Eliminates code duplication between winX() and win0().
         */
        private boolean hasWon(char[][] board, char player) {
            // Check rows and columns
            for (int i = 0; i < BOARD_SIZE; i++) {
                boolean rowWin = true;
                boolean colWin = true;
                for (int j = 0; j < BOARD_SIZE; j++) {
                    if (board[i][j] != player) rowWin = false;
                    if (board[j][i] != player) colWin = false;
                }
                if (rowWin || colWin) return true;
            }

            // Check diagonals
            boolean diag1Win = true;
            boolean diag2Win = true;
            for (int i = 0; i < BOARD_SIZE; i++) {
                if (board[i][i] != player) diag1Win = false;
                if (board[i][BOARD_SIZE - 1 - i] != player) diag2Win = false;
            }
            return diag1Win || diag2Win;
        }
    }

    /**
     * Fast input reader for competitive programming / large I/O scenarios.
     */
    static class InputReader {
        private final BufferedReader br;
        private StringTokenizer st;

        public InputReader(InputStream inputStream) {
            this.br = new BufferedReader(new InputStreamReader(inputStream));
        }

        public String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) {
                        return null;
                    }
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input", e);
                }
            }
            return st.nextToken();
        }
    }
}

