            }

            // Validation Logic:
            // 1. O cannot have played more moves than X.
            // 2. X cannot have played more than 1 move than O.
            boolean isIllegal = oCount > xCount || (xCount - oCount) > 1;

            boolean xWins = false;
            boolean oWins = false;

            if (!isIllegal) {
                // Check for winning lines
                if (hasWinningLine(board, PLAYER_X)) {
                    // If X wins, X must have made the last move.
                    // Therefore, xCount must be exactly oCount + 1.
                    if (oCount >= xCount) {
                        isIllegal = true; // O played after X won, or counts are equal
                    } else {
                        xWins = true;
                    }
                } else if (hasWinningLine(board, PLAYER_O)) {
                    // If O wins, O must have made the last move.
                    // Therefore, xCount must be equal to oCount.
                    if (xCount > oCount) {
                        isIllegal = true; // X played after O won
                    } else {
                        oWins = true;
                    }
                }
            }

            // Determine and print the result
            if (isIllegal) {
                System.out.println("illegal");
            } else if (xWins) {
                System.out.println("the first player won");
            } else if (oWins) {
                System.out.println("the second player won");
            } else if (isBoardFull) {
                System.out.println("draw");
            } else {
                // Game is ongoing. Determine whose turn it is next.
                // If xCount > oCount, it's O's turn (Second player).
                // If xCount == oCount, it's X's turn (First player).
                System.out.println(xCount > oCount ? "second" : "first");
            }
        }
    }

    /**
     * Checks if the given player has a winning line on the board.
     * Checks all rows, columns, and diagonals.
     */
    private static boolean hasWinningLine(Board board, char player) {
        // Check Rows
        for (int i = 0; i < GRID_SIZE; i++) {
            if (board.get(i, 0) == player && board.get(i, 1) == player && board.get(i, 2) == player) {
                return true;
            }
        }
        // Check Columns
        for (int i = 0; i < GRID_SIZE; i++) {
            if (board.get(0, i) == player && board.get(1, i) == player && board.get(2, i) == player) {
                return true;
            }
        }
        // Check Diagonals
        if (board.get(0, 0) == player && board.get(1, 1) == player && board.get(2, 2) == player) {
            return true;
        }
        if (board.get(0, 2) == player && board.get(1, 1) == player && board.get(2, 0) == player) {
            return true;
        }

        return false;
    }

    /**
     * Represents the 3x3 Tic-Tac-Toe board.
     * Uses a 2D array for intuitive row/column access.
     */
    static class Board {
        private final char[][] grid = new char[GRID_SIZE][GRID_SIZE];

        public void set(int row, int col, char value) {
            grid[row][col] = value;
        }

        public char get(int row, int col) {
            return grid[row][col];
        }
    }
}

