import java.util.Scanner;

/**
 * Analyzes a Tic-Tac-Toe board state, validates turn order, checks for a winner,
 * and determines the next move or game outcome.
 */
public class TicTacToeAnalyzer {

    private static final int BOARD_SIZE = 3;
    private static final char PLAYER_X = 'x';
    private static final char PLAYER_O = 'o';
    private static final char EMPTY = '.';

    public static void main(String[] args) {
        // Use try-with-resources to automatically close the Scanner
        try (Scanner scanner = new Scanner(System.in)) {
            char[][] board = readBoard(scanner);
            analyzeBoard(board);
        }
    }

    /**
     * Reads the 3x3 board from standard input.
     */
    private static char[][] readBoard(Scanner scanner) {
        char[][] board = new char[BOARD_SIZE][BOARD_SIZE];
        for (int i = 0; i < BOARD_SIZE; i++) {
            String line = scanner.next();
            if (line == null || line.length() != BOARD_SIZE) {
                throw new IllegalArgumentException("Invalid board input: each row must contain exactly 3 characters.");
            }
            // Normalize to lowercase and treat '0' as 'o' for compatibility
            board[i] = line.toLowerCase().chars()
                    .mapToObj(c -> c == '0' ? 'o' : (char) c)
                    .toArray(char[]::new);
        }
        return board;
    }

    /**
     * Orchestrates board validation, winner detection, and move determination.
     */
    private static void analyzeBoard(char[][] board) {
        int xCount = 0;
        int oCount = 0;
        int emptyCount = 0;

        // Count pieces and validate board contents
        for (char[] row : board) {
            for (char cell : row) {
                if (cell == PLAYER_X) xCount++;
                else if (cell == PLAYER_O) oCount++;
                else if (cell == EMPTY) emptyCount++;
                else throw new IllegalArgumentException("Invalid character in board: " + cell);
            }
        }

        // 1. Validate turn order
        if (!isValidTurn(xCount, oCount)) {
            printResult("illegal");
            return;
        }

        // 2. Check for winning lines
        int xWins = countWins(board, PLAYER_X);
        int oWins = countWins(board, PLAYER_O);

        // Both players cannot win simultaneously
        if (xWins > 0 && oWins > 0) {
            printResult("illegal");
            return;
        }

        // 3. Validate win state against piece counts
        if (xWins > 0) {
            if (!isValidWinState(PLAYER_X, xCount, oCount)) {
                printResult("illegal");
                return;
            }
            printResult("the first player won");
            return;
        }

        if (oWins > 0) {
            if (!isValidWinState(PLAYER_O, xCount, oCount)) {
                printResult("illegal");
                return;
            }
            printResult("the second player won");
            return;
        }

        // 4. No winner: determine next move or draw
        determineNextMove(xCount, oCount, emptyCount);
    }

    private static boolean isValidTurn(int xCount, int oCount) {
        // In valid Tic-Tac-Toe, X goes first. Counts must be equal or X has one more.
        return xCount == oCount || xCount == oCount + 1;
    }

    private static int countWins(char[][] board, char player) {
        int wins = 0;

        // Check rows
        for (int i = 0; i < BOARD_SIZE; i++) {
            if (board[i][0] == player && board[i][1] == player && board[i][2] == player) {
                wins++;
            }
        }

        // Check columns
        for (int i = 0; i < BOARD_SIZE; i++) {
            if (board[0][i] == player && board[1][i] == player && board[2][i] == player) {
                wins++;
            }
        }

        // Check diagonals
        if (board[0][0] == player && board[1][1] == player && board[2][2] == player) {
            wins++;
        }
        if (board[2][0] == player && board[1][1] == player && board[0][2] == player) {
            wins++;
        }

        return wins;
    }

    private static boolean isValidWinState(char winner, int xCount, int oCount) {
        // If X wins, they must have played one more move than O
        if (winner == PLAYER_X) {
            return xCount == oCount + 1;
        }
        // If O wins, counts must be equal
        return xCount == oCount;
    }

    private static void determineNextMove(int xCount, int oCount, int emptyCount) {
        if (emptyCount == 0) {
            printResult("draw");
        } else if (xCount == oCount) {
            printResult("first");
        } else {
            printResult("second");
        }
    }

    private static void printResult(String message) {
        System.out.println(message);
    }
}

import java.util.Scanner;

public class Main {
    // Constants for board configuration and player markers
    private static final int BOARD_SIZE = 3;
    private static final char PLAYER_X = 'X';
    private static final char PLAYER_O = '0'; // Note: Input uses '0' (zero) for the second player
    private static final char EMPTY = '.';

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        char[][] board = new char[BOARD_SIZE][BOARD_SIZE];

        // Read input and populate the board
        try {
            for (int i = 0; i < BOARD_SIZE; i++) {
                if (scanner.hasNextLine()) {
                    String line = scanner.nextLine();
                    for (int j = 0; j < BOARD_SIZE; j++) {
                        // Ensure we don't go out of bounds if input line is short
                        if (j < line.length()) {
                            board[i][j] = line.charAt(j);
                        } else {
                            board[i][j] = EMPTY;
                        }
                    }
                }
            }
        } finally {
            scanner.close();
        }

        // Evaluate the game state and print the result
        System.out.println(evaluateBoard(board));
    }

    /**
     * Evaluates the current state of the Tic-Tac-Toe board.
     * 
     * @param board The 3x3 game board.
     * @return A string describing the game state ("illegal", "draw", "the first player won", etc.)
     */
    private static String evaluateBoard(char[][] board) {
        // 1. Count player marks
        int[] counts = countPlayers(board);
        int xCount = counts[0];
        int oCount = counts[1];

        // 2. Validate Turn Counts
        // X goes first, so X count must be equal to O count or O count + 1.
        if (xCount > oCount + 1) return "illegal";
        if (oCount > xCount) return "illegal";

        // 3. Check for Winning Conditions
        boolean xWon = hasWon(board, PLAYER_X);
        boolean oWon = hasWon(board, PLAYER_O);

        // 4. Validate Win States against Turn Counts
        // Both players cannot win simultaneously.
        if (xWon && oWon) return "illegal";

        // If X won, X must have played the last move (xCount == oCount + 1).
        // If xCount == oCount, it means O played after X won, which is illegal.
        if (xWon && xCount == oCount) return "illegal";

        // If O won, X and O must have played equal moves (xCount == oCount).
        // If xCount > oCount, it means X played after O won, which is illegal.
        if (oWon && xCount > oCount) return "illegal";

        // 5. Determine Game Status
        if (!xWon && !oWon) {
            // Check for Draw (Board full)
            if (xCount + oCount == BOARD_SIZE * BOARD_SIZE) return "draw";

            // Determine whose turn it is
            if (xCount == oCount) return "first";   // X's turn
            if (xCount > oCount) return "second";   // O's turn
        }

        // 6. Return Winner
        if (xWon) return "the first player won";
        if (oWon) return "the second player won";

        // Fallback (should technically not be reached with valid logic)
        return "not good";
    }

    /**
     * Counts the number of 'X' and '0' marks on the board.
     * 
     * @param board The game board.
     * @return An int array where index 0 is X count and index 1 is O count.
     */
    private static int[] countPlayers(char[][] board) {
        int xCount = 0;
        int oCount = 0;
        for (char[] row : board) {
            for (char cell : row) {
                if (cell == PLAYER_X) {
                    xCount++;
                } else if (cell == PLAYER_O) {
                    oCount++;
                }
            }
        }
        return new int[]{xCount, oCount};
    }

    /**
     * Checks if a specific player has won the game.
     * 
     * @param board The game board.
     * @param player The character representing the player ('X' or '0').
     * @return true if the player has a winning line (row, column, or diagonal), false otherwise.
     */
    private static boolean hasWon(char[][] board, char player) {
        // Check Rows
        for (int i = 0; i < BOARD_SIZE; i++) {
            if (board[i][0] == player && board[i][1] == player && board[i][2] == player) {
                return true;
            }
        }

        // Check Columns
        for (int j = 0; j < BOARD_SIZE; j++) {
            if (board[0][j] == player && board[1][j] == player && board[2][j] == player) {
                return true;
            }
        }

        // Check Diagonals
        // Main diagonal (top-left to bottom-right)
        if (board[0][0] == player && board[1][1] == player && board[2][2] == player) {
            return true;
        }
        // Anti-diagonal (top-right to bottom-left)
        if (board[0][2] == player && board[1][1] == player && board[2][0] == player) {
            return true;
        }

        return false;
    }
}

import java.util.Scanner;

/**
 * A validator for Tic-Tac-Toe game states.
 * It analyzes a 3x3 board represented by three strings and determines
 * if the state is legal, who won, whose turn it is, or if it's a draw.
 * 
 * Refactoring notes:
 * - Renamed class to TicTacToeValidator for clarity (optional, but good practice).
 * - Fixed typo in method name: countCharOccurance -> countOccurrences.
 * - Replaced magic numbers and characters with constants.
 * - Encapsulated board logic into a 2D char array for easier manipulation.
 * - Consolidated validation logic to reduce code duplication and improve readability.
 * - Used try-with-resources for Scanner management.
 * - Fixed variable naming (count0 -> countO).
 */
public class TicTacToe {

    // Constants for players and board dimensions
    // Note: Using '0' (digit zero) to match original input logic
    private static final char PLAYER_X = 'X';
    private static final char PLAYER_O = '0';
    private static final int BOARD_SIZE = 3;

    public static void main(String[] args) {
        // Use try-with-resources to ensure Scanner is closed properly
        try (Scanner input = new Scanner(System.in)) {
            // Check if input is available
            if (!input.hasNext() || !input.hasNext() || !input.hasNext()) {
                System.out.println("illegal");
                return;
            }

            String row1 = input.next();
            String row2 = input.next();
            String row3 = input.next();

            // Validate input string lengths to prevent IndexOutOfBoundsException
            if (row1.length() != BOARD_SIZE || row2.length() != BOARD_SIZE || row3.length() != BOARD_SIZE) {
                System.out.println("illegal");
                return;
            }

            // Convert input strings to a 2D char array for easier logic handling
            char[][] board = new char[BOARD_SIZE][BOARD_SIZE];
            board[0] = row1.toCharArray();
            board[1] = row2.toCharArray();
            board[2] = row3.toCharArray();

            // Evaluate the board state and print result
            evaluateGameState(board);
        }
    }

    /**
     * Analyzes the board state and prints the appropriate result.
     */
    private static void evaluateGameState(char[][] board) {
        // 1. Count moves for each player
        int countX = countOccurrences(board, PLAYER_X);
        int countO = countOccurrences(board, PLAYER_O);

        // 2. Basic validation: X goes first, so countX >= countO.
        // Also, X cannot have more than 1 extra move.
        if (countO > countX || countX > countO + 1) {
            System.out.println("illegal");
            return;
        }

        // 3. Check for winning conditions
        boolean xWin = checkWin(board, PLAYER_X);
        boolean oWin = checkWin(board, PLAYER_O);

        // 4. Validation: Both players cannot win simultaneously
        if (xWin && oWin) {
            System.out.println("illegal");
            return;
        }

        // 5. Determine result based on wins and counts
        if (xWin) {
            // If X wins, X must have made the last move, so countX == countO + 1
            if (countX == countO + 1) {
                System.out.println("the first player won");
            } else {
                System.out.println("illegal");
            }
            return;
        }

        if (oWin) {
            // If O wins, O must have made the last move, so counts must be equal
            if (countX == countO) {
                System.out.println("the second player won");
            } else {
                System.out.println("illegal");
            }
            return;
        }

        // 6. Game is not over (No winner)
        if (countX + countO == BOARD_SIZE * BOARD_SIZE) {
            // Board is full, no winner -> Draw
            System.out.println("draw");
        } else if (countX == countO) {
            // Equal moves, X's turn
            System.out.println("first");
        } else if (countX == countO + 1) {
            // X has one more move, O's turn
            System.out.println("second");
        } else {
            // Invalid state (e.g., counts don't match valid game progression)
            System.out.println("illegal");
        }
    }

    /**
     * Checks if a specific player has won the game.
     */
    private static boolean checkWin(char[][] board, char player) {
        // Check Rows
        for (int row = 0; row < BOARD_SIZE; row++) {
            if (board[row][0] == player && board[row][1] == player && board[row][2] == player) {
                return true;
            }
        }

        // Check Columns
        for (int col = 0; col < BOARD_SIZE; col++) {
            if (board[0][col] == player && board[1][col] == player && board[2][col] == player) {
                return true;
            }
        }

        // Check Main Diagonal
        if (board[0][0] == player && board[1][1] == player && board[2][2] == player) {
            return true;
        }

        // Check Anti-Diagonal
        if (board[0][2] == player && board[1][1] == player && board[2][0] == player) {
            return true;
        }

        return false;
    }

    /**
     * Counts occurrences of a specific character in the board.
     */
    private static int countOccurrences(char[][] board, char target) {
        int count = 0;
        for (int row = 0; row < BOARD_SIZE; row++) {
            for (int col = 0; col < BOARD_SIZE; col++) {
                if (board[row][col] == target) {
                    count++;
                }
            }
        }
        return count;
    }
}

import java.util.Scanner;

/**
 * Validates a 3x3 Tic-Tac-Toe board state and determines the current game status.
 * Refactored for improved maintainability, readability, and robustness.
 */
public class TicTacToe {

    // Constants to eliminate magic numbers and improve configurability
    private static final int BOARD_SIZE = 3;
    private static final char X_MARK = 'X';
    // Note: Changed from '0' to 'O' for standard Tic-Tac-Toe notation
    private static final char O_MARK = 'O'; 

    public static void main(String[] args) {
        // Use try-with-resources for automatic and safe resource management
        try (Scanner scanner = new Scanner(System.in)) {
            String[] board = readBoard(scanner);

            // Handle insufficient input gracefully
            if (board == null) {
                System.out.println("illegal");
                return;
            }

            System.out.println(determineGameState(board));
        }
    }

    /**
     * Reads exactly 3 rows of input from the scanner.
     * @return array of board rows, or null if input is insufficient
     */
    private static String[] readBoard(Scanner scanner) {
        String[] board = new String[BOARD_SIZE];
        for (int i = 0; i < BOARD_SIZE; i++) {
            if (scanner.hasNext()) {
                board[i] = scanner.next();
            } else {
                return null; // Indicates missing input
            }
        }
        return board;
    }

    /**
     * Validates board dimensions, character validity, move counts, and win conditions.
     * Returns the appropriate game status string.
     */
    private static String determineGameState(String[] board) {
        int xCount = 0;
        int oCount = 0;

        // 1. Validate board structure and count marks
        for (String row : board) {
            if (row == null || row.length() != BOARD_SIZE) {
                return "illegal";
            }
            for (int j = 0; j < BOARD_SIZE; j++) {
                char c = row.charAt(j);
                if (c == X_MARK) {
                    xCount++;
                } else if (c == O_MARK) {
                    oCount++;
                } else {
                    return "illegal"; // Invalid character found
                }
            }
        }

        // 2. Validate move counts (X always goes first)
        if (xCount < oCount || xCount > oCount + 1) {
            return "illegal";
        }

        // 3. Check win conditions
        boolean xWins = checkWinCondition(board, X_MARK);
        boolean oWins = checkWinCondition(board, O_MARK);

        // Both players cannot win simultaneously in a valid game
        if (xWins && oWins) {
            return "illegal";
        }

        // 4. Evaluate win states
        if (xWins) {
            return (xCount == oCount + 1) ? "the first player won" : "illegal";
        }
        if (oWins) {
            return (xCount == oCount) ? "the second player won" : "illegal";
        }

        // 5. Evaluate non-winning states
        int totalMoves = xCount + oCount;
        if (totalMoves == BOARD_SIZE * BOARD_SIZE) {
            return "draw";
        }
        if (xCount == oCount + 1) {
            return "second"; // Second player's turn
        }
        if (xCount == oCount) {
            return "first"; // First player's turn
        }

        // Fallback (should be unreachable due to earlier validation)
        return "illegal";
    }

    /**
     * Checks if a specific player has achieved a winning line (row, column, or diagonal).
     */
    private static boolean checkWinCondition(String[] board, char mark) {
        // Check rows
        for (int i = 0; i < BOARD_SIZE; i++) {
            if (board[i].charAt(0) == mark && board[i].charAt(1) == mark && board[i].charAt(2) == mark) {
                return true;
            }
        }

        // Check columns
        for (int j = 0; j < BOARD_SIZE; j++) {
            if (board[0].charAt(j) == mark && board[1].charAt(j) == mark && board[2].charAt(j) == mark) {
                return true;
            }
        }

        // Check main diagonal
        if (board[0].charAt(0) == mark && board[1].charAt(1) == mark && board[2].charAt(2) == mark) {
            return true;
        }

        // Check anti-diagonal
        if (board[0].charAt(2) == mark && board[1].charAt(1) == mark && board[2].charAt(0) == mark) {
            return true;
