/**
 * Refactored Tic-Tac-Toe Validator.
 * 
 * This version improves maintainability and code quality by:
 * 1. Removing unnecessary threading (Runnable interface) for a simple script.
 * 2. Encapsulating I/O logic into a dedicated FastScanner helper.
 * 3. Extracting magic numbers and characters into named constants.
 * 4. Simplifying the win-checking logic for better readability.
 * 5. Improving variable naming and code structure.
 */
public class TicTacToeValidator {

    // Constants for board configuration
    private static final int BOARD_SIZE = 3;
    private static final char PLAYER_X = 'X';
    private static final char PLAYER_O = '0'; // Using '0' (zero) to match original logic

    public static void main(String[] args) {
        try {
            solve();
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    private static void solve() throws IOException {
        FastScanner scanner = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out);

        char[][] board = new char[BOARD_SIZE][BOARD_SIZE];

        // Read the 3x3 board from input
        for (int i = 0; i < BOARD_SIZE; i++) {
            String line = scanner.next();
            if (line != null) {
                for (int j = 0; j < BOARD_SIZE; j++) {
                    if (j < line.length()) {
                        board[i][j] = line.charAt(j);
                    }
                }
            }
        }

        // Validate and print result
        out.println(validate(board));
        out.flush();
    }

    /**
     * Validates the current state of the Tic-Tac-Toe board.
     * Returns a string describing the game status.
     */
    private static String validate(char[][] board) {
        int crossCount = count(board, PLAYER_X);
        int zeroCount = count(board, PLAYER_O);

        // Rule 1: Check move counts validity
        // X (1st player) moves first. 
        // Valid states: X == O  OR  X == O + 1
        if (zeroCount > crossCount || crossCount > zeroCount + 1) {
            return "illegal";
        }

        boolean crossWin = checkWin(board, PLAYER_X);
        boolean zeroWin = checkWin(board, PLAYER_O);

        // Rule 2: Both players cannot win simultaneously
        if (crossWin && zeroWin) {
            return "illegal";
        }

        // Rule 3: If X won, X must have made the last move (X count > O count)
        if (crossWin) {
            if (crossCount == zeroCount) {
                return "illegal";
            }
            return "the first player won";
        }

        // Rule 4: If O won, O must have made the last move (O count == X count)
        if (zeroWin) {
            if (zeroCount != crossCount) {
                return "illegal";
            }
            return "the second player won";
        }

        // Rule 5: Board is full and no winner -> Draw
        if (crossCount + zeroCount == BOARD_SIZE * BOARD_SIZE) {
            return "draw";
        }

        // Rule 6: Game ongoing, determine whose turn it is
        if (crossCount == zeroCount) {
            return "first"; // It is X's turn
        } else {
            return "second"; // It is O's turn
        }
    }

    /**
     * Counts occurrences of a specific character in the board.
     */
    private static int count(char[][] board, char ch) {
        int cnt = 0;
        for (char[] row : board) {
            for (char cell : row) {
                if (cell == ch) {
                    cnt++;
                }
            }
        }
        return cnt;
    }

    /**
     * Checks if a specific player has won on the board.
     * Checks rows, columns, and diagonals.
     */
    private static boolean checkWin(char[][] board, char ch) {
        // Check Rows
        for (int i = 0; i < BOARD_SIZE; i++) {
            if (board[i][0] == ch && board[i][1] == ch && board[i][2] == ch) {
                return true;
            }
        }

        // Check Columns
        for (int j = 0; j < BOARD_SIZE; j++) {
            if (board[0][j] == ch && board[1][j] == ch && board[2][j] == ch) {
                return true;
            }
        }

        // Check Diagonals
        if (board[0][0] == ch && board[1][1] == ch && board[2][2] == ch) {
            return true;
        }
        if (board[0][2] == ch && board[1][1] == ch && board[2][0] == ch) {
            return true;
        }

        return false;
    }

    /**
     * Helper class for fast input reading.
     */
    static class FastScanner {
        BufferedReader br;
        StringTokenizer st;

        public FastScanner(java.io.InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
            st = new StringTokenizer("");
        }

        String next() throws IOException {
            while (!st.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) return null;
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

/**
 * Validates a Tic-Tac-Toe board state and determines the current game status.
 * 
 * Refactoring improvements:
 * - Replaced cryptic single-letter class/variable names with descriptive ones.
 * - Extracted win-checking logic into a reusable, readable method.
 * - Removed unused debug methods and redundant field initializations.
 * - Fixed potential EOF/NullPointer issues in token reading.
 * - Replaced magic numbers with named constants.
 * - Used try-with-resources for proper I/O stream management.
 * - Cleaned up output formatting (removed accidental trailing space).
 */
public class TicTacToeValidator {

    private static final int BOARD_SIZE = 3;
    private static final int PLAYER_X = 1;
    private static final int PLAYER_O = 2;

    public static void main(String[] args) throws IOException {
        // Try-with-resources ensures streams are closed automatically
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
             PrintWriter writer = new PrintWriter(System.out)) {
            validateBoard(reader, writer);
        }
    }

    private static void validateBoard(BufferedReader reader, PrintWriter writer) throws IOException {
        StringTokenizer tokenizer = new StringTokenizer("");
        int[][] board = new int[BOARD_SIZE][BOARD_SIZE];
        int countX = 0;
        int countO = 0;

        // Parse the 3x3 board from input tokens
        for (int i = 0; i < BOARD_SIZE; i++) {
            while (!tokenizer.hasMoreTokens()) {
                String line = reader.readLine();
                if (line == null) break; // Graceful EOF handling
                tokenizer = new StringTokenizer(line);
            }
            String rowStr = tokenizer.nextToken();

            for (int j = 0; j < BOARD_SIZE; j++) {
                char c = rowStr.charAt(j);
                if (c == 'X') {
                    board[i][j] = PLAYER_X;
                    countX++;
                } else if (c == '0') {
                    board[i][j] = PLAYER_O;
                    countO++;
                }
                // Unmarked cells remain 0 (empty)
            }
        }

        boolean xWins = checkWin(board, PLAYER_X);
        boolean oWins = checkWin(board, PLAYER_O);

        // Determine if the board state is illegal according to Tic-Tac-Toe rules
        boolean illegal = false;
        if (xWins && oWins) {
            illegal = true;
        } else if (countO > countX || countX > countO + 1) {
            illegal = true; // X always goes first, so counts can only be equal or X has 1 more
        } else if (xWins && countX == countO) {
            illegal = true; // If X wins, X must have just played, so countX == countO + 1
        } else if (oWins && countO != countX) {
            illegal = true; // If O wins, O must have just played, so countO == countX
        }

        // Output result based on validation
        if (illegal) {
            writer.println("illegal");
        } else if (xWins) {
            writer.println("the first player won");
        } else if (oWins) {
            writer.println("the second player won");
        } else if (countX + countO == BOARD_SIZE * BOARD_SIZE) {
            writer.println("draw");
        } else if (countX == countO) {
            writer.println("first");
        } else {
            writer.println("second");
        }
    }

    /**
     * Checks if the specified player has won on the board.
     * Verifies all rows, columns, and both diagonals.
     */
    private static boolean checkWin(int[][] board, int player) {
        // Check rows and columns simultaneously
        for (int i = 0; i < BOARD_SIZE; i++) {
            boolean rowWin = true;
            boolean colWin = true;
            for (int j = 0; j < BOARD_SIZE; j++) {
                if (board[i][j] != player) rowWin = false;
                if (board[j][i] != player) colWin = false;
            }
            if (rowWin || colWin) return true;
        }

        // Check main diagonal (top-left to bottom-right)
        boolean diag1Win = true;
        for (int i = 0; i < BOARD_SIZE; i++) {
            if (board[i][i] != player) {
                diag1Win = false;
                break;
            }
        }
        if (diag1Win) return true;

        // Check anti-diagonal (top-right to bottom-left)
        boolean diag2Win = true;
        for (int i = 0; i < BOARD_SIZE; i++) {
            if (board[i][BOARD_SIZE - 1 - i] != player) {
                diag2Win = false;
                break;
            }
        }
        return diag2Win;
    }
}

