    /**
     * Evaluates the game state based on the board configuration and move counts.
     * Returns the status string as required by the original logic.
     */
    private static String evaluateGameState(char[][] board, int xCount, int oCount) {
        // Rule 1: Basic move count validation
        // X always starts, so X count can be equal to O or O+1.
        if (xCount > oCount + 1 || oCount > xCount) {
            return "illegal";
        }

        // Rule 2: Check for winning lines
        char winner = detectWinner(board);

        // If 'i' is returned, it means both players have winning lines (illegal state)
        if (winner == 'i') {
            return "illegal";
        }

        // Rule 3: Validate winner against move counts
        if (winner == PLAYER_X) {
            // X wins only if X has made one more move than O
            if (xCount == oCount + 1) {
                return "the first player won";
            } else {
                return "illegal";
            }
        }

        if (winner == PLAYER_O) {
            // O wins only if move counts are equal
            if (oCount == xCount) {
                return "the second player won";
            } else {
                return "illegal";
            }
        }

        // Rule 4: No winner - determine if draw or next turn
        if (xCount + oCount == BOARD_SIZE * BOARD_SIZE) {
            return "draw";
        }

        if (xCount == oCount) {
            return "first"; // It is X's turn
        } else {
            return "second"; // It is O's turn (implies xCount == oCount + 1)
        }
    }

    /**
     * Scans the board for winning lines.
     * Returns:
     * 'X' if Player X won
     * '0' if Player O won
     * 'i' if both players have winning lines (illegal)
     * 'n' if no one won
     */
    private static char detectWinner(char[][] board) {
        char winner = 'n';

        // Check Rows
        for (int i = 0; i < BOARD_SIZE; i++) {
            if (isWinningLine(board[i])) {
                char currentWinner = board[i][0];
                winner = handleWin(winner, currentWinner);
                if (winner == 'i') return 'i';
            }
        }

        // Check Columns
        for (int j = 0; j < BOARD_SIZE; j++) {
            char[] col = {board[0][j], board[1][j], board[2][j]};
            if (isWinningLine(col)) {
                char currentWinner = col[0];
                winner = handleWin(winner, currentWinner);
                if (winner == 'i') return 'i';
            }
        }

        // Check Diagonals
        char[] diag1 = {board[0][0], board[1][1], board[2][2]};
        if (isWinningLine(diag1)) {
            char currentWinner = diag1[0];
            winner = handleWin(winner, currentWinner);
            if (winner == 'i') return 'i';
        }

        char[] diag2 = {board[0][2], board[1][1], board[2][0]};
        if (isWinningLine(diag2)) {
            char currentWinner = diag2[0];
            winner = handleWin(winner, currentWinner);
            if (winner == 'i') return 'i';
        }

        return winner;
    }

    /**
     * Helper to manage winner state.
     * If no winner set, sets it. If conflict (different players won), returns 'i'.
     */
    private static char handleWin(char currentWinner, char newWinner) {
        if (currentWinner == 'n') {
            return newWinner;
        } else if (currentWinner != newWinner) {
            return 'i'; // Conflict detected
        }
        return currentWinner; // Same winner, no conflict
    }

    /**
     * Checks if a line of 3 characters constitutes a winning line.
     */
    private static boolean isWinningLine(char[] line) {
        // Ensure the first char is a valid player mark
        if (line[0] != PLAYER_X && line[0] != PLAYER_O) {
            return false;
        }
        return line[0] == line[1] && line[1] == line[2];
    }
}

