            if (board[i][0] != EMPTY_CELL && 
                board[i][0] == board[i][1] && 
                board[i][1] == board[i][2]) {
                winners.add(board[i][0]);
            }
        }

        // Check Columns
        for (int j = 0; j < BOARD_SIZE; j++) {
            if (board[0][j] != EMPTY_CELL && 
                board[0][j] == board[1][j] && 
                board[1][j] == board[2][j]) {
                winners.add(board[0][j]);
            }
        }

        // Check Diagonals
        if (board[0][0] != EMPTY_CELL && 
            board[0][0] == board[1][1] && 
            board[1][1] == board[2][2]) {
            winners.add(board[0][0]);
        }

        if (board[0][2] != EMPTY_CELL && 
            board[0][2] == board[1][1] && 
            board[1][1] == board[2][0]) {
            winners.add(board[0][2]);
        }

        // Evaluate results based on unique winners found
        if (winners.size() > 1) {
            return ILLEGAL; // Multiple winners detected (e.g., X and O both won)
        } else if (winners.size() == 1) {
            return winners.iterator().next(); // Return the single winner
        } else {
            return DRAW; // No winner found
        }
    }

    /**
     * Analyzes the game counts and winner status to produce the final output string.
     * Validates move counts and win conditions against standard Tic-Tac-Toe rules.
     */
    private static String analyzeGameState(int xCount, int oCount, int emptyCount, char winnerStatus) {

        // 1. Validate Move Counts
        // X goes first, so X count must be equal to or 1 greater than O count.
        if (oCount > xCount || xCount > oCount + 1) {
            return "illegal";
        }

        // 2. Validate Win Conditions
        if (winnerStatus == PLAYER_X) {
            // If X won, X must have made one more move than O
            if (xCount == oCount + 1) {
                return "the first player won";
            } else {
                return "illegal"; // X won but move counts are invalid
            }
        }

        if (winnerStatus == PLAYER_O) {
            // If O won, move counts must be equal
            if (xCount == oCount) {
                return "the second player won";
            } else {
                return "illegal"; // O won but move counts are invalid
            }
        }

        if (winnerStatus == ILLEGAL) {
            return "illegal"; // Explicitly handle the multiple winners case
        }

        // 3. Check for Draw (Board full, no winner)
        if (emptyCount == 0) {
            return "draw";
        }

        // 4. Game in Progress
        // If counts are equal, it is X's turn (First player)
        // If X has one more move, it is O's turn (Second player)
        if (xCount == oCount) {
            return "first";
        } else {
            return "second";
        }
    }
}

import java.util.Scanner;

/**
 * A validator for Tic-Tac-Toe game states.
 * This class reads a 3x3 board configuration, validates the game state,
 * and determines the outcome (winner, draw, or next player).
 */
public class TicTacToeGameValidator {

    private static final int BOARD_SIZE = 3;
    private static final char PLAYER_X = 'X';
    private static final char PLAYER_O = '0'; // Using '0' to match original input logic

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        // 1. Read the board input
        char[][] board = readBoard(scanner);

        // 2. Analyze the board state
        boolean xWon = checkWin(board, PLAYER_X);
        boolean oWon = checkWin(board, PLAYER_O);
        int xCount = countMarks(board, PLAYER_X);
        int oCount = countMarks(board, PLAYER_O);

        // 3. Determine and print the result based on validation rules
        if (isIllegalState(xWon, oWon, xCount, oCount)) {
            System.out.println("illegal");
        } else if (xWon) {
            System.out.println("the first player won");
        } else if (oWon) {
            System.out.println("the second player won");
        } else if (isBoardFull(xCount, oCount)) {
            System.out.println("draw");
        } else if (xCount == oCount) {
            System.out.println("first");
        } else {
            System.out.println("second");
        }

        scanner.close();
    }

    /**
     * Reads the 3x3 board from standard input.
     * Expects 3 strings, each representing a row of the board.
     */
    private static char[][] readBoard(Scanner scanner) {
        char[][] board = new char[BOARD_SIZE][BOARD_SIZE];
        for (int i = 0; i < BOARD_SIZE; i++) {
            if (scanner.hasNext()) {
                String row = scanner.next();
                // Populate the row, handling potential input length variations gracefully
                for (int j = 0; j < BOARD_SIZE; j++) {
                    if (j < row.length()) {
                        board[i][j] = row.charAt(j);
                    }
                }
            }
        }
        return board;
    }

    /**
     * Checks if the specified player has won the game.
     * Checks rows, columns, and diagonals.
     */
    private static boolean checkWin(char[][] board, char player) {
        // Check rows
        for (int i = 0; i < BOARD_SIZE; i++) {
            if (board[i][0] == player && board[i][1] == player && board[i][2] == player) {
                return true;
            }
        }

        // Check columns
        for (int j = 0; j < BOARD_SIZE; j++) {
            if (board[0][j] == player && board[1][j] == player && board[2][j] == player) {
                return true;
            }
        }

        // Check main diagonal
        if (board[0][0] == player && board[1][1] == player && board[2][2] == player) {
            return true;
        }

        // Check anti-diagonal
        if (board[0][2] == player && board[1][1] == player && board[2][0] == player) {
            return true;
        }

        return false;
    }

    /**
     * Counts the total number of marks for a specific player on the board.
     */
    private static int countMarks(char[][] board, char player) {
        int count = 0;
        for (int i = 0; i < BOARD_SIZE; i++) {
            for (int j = 0; j < BOARD_SIZE; j++) {
                if (board[i][j] == player) {
                    count++;
                }
            }
        }
        return count;
    }

    /**
     * Validates if the current game state is legal according to Tic-Tac-Toe rules.
     * 
     * Rules:
     * 1. If X won, X must have exactly one more mark than O.
     * 2. If O won, X and O must have equal marks.
     * 3. If neither won, X must have equal or one more mark than O.
     */
    private static boolean isIllegalState(boolean xWon, boolean oWon, int xCount, int oCount) {
        // If X won, X must have one more mark than O
        if (xWon && xCount != oCount + 1) {
            return true;
        }
        // If O won, X and O must have equal marks
        if (oWon && xCount != oCount) {
            return true;
        }
        // If neither won, counts must be valid (X == O or X == O + 1)
        // If counts are neither equal nor +1, the state is illegal
        if (!xWon && !oWon && xCount != oCount && xCount != oCount + 1) {
            return true;
        }
        return false;
    }

    /**
     * Checks if the board is completely full.
     */
    private static boolean isBoardFull(int xCount, int oCount) {
        return (xCount + oCount) == 9;
    }
}

import java.util.Scanner;

/**
 * A validator for Tic-Tac-Toe game states.
 * It checks for illegal states, winners, draws, and determines whose turn is next.
 */
public class TicTacToeValidator {

    // Constants for board configuration and players
    private static final int BOARD_SIZE = 3;
    private static final char PLAYER_X = 'X';
    private static final char PLAYER_O = '0'; // Note: Using '0' (zero) as per original logic
    private static final char EMPTY_SPACE = ' ';

    private final char[][] board;

    /**
     * Constructs the validator with the game board.
     *
     * @param rows An array of 3 strings representing the rows of the board.
     */
    public TicTacToeValidator(String[] rows) {
        this.board = new char[BOARD_SIZE][BOARD_SIZE];
        for (int i = 0; i < BOARD_SIZE; i++) {
            String row = (rows != null && rows.length > i) ? rows[i] : "";
            for (int j = 0; j < BOARD_SIZE; j++) {
                this.board[i][j] = (j < row.length()) ? row.charAt(j) : EMPTY_SPACE;
            }
        }
    }

    /**
     * Validates the current board state and returns the game status.
     *
     * @return A string describing the state: "illegal", "the first player won",
     *         "the second player won", "draw", "first", or "second".
     */
    public String validate() {
        MoveCounts counts = countMoves();

        // 1. Basic move count validation
        // X goes first, so X count must be equal to O count or O count + 1.
        if (counts.xCount > counts.oCount + 1 || counts.oCount > counts.xCount) {
            return "illegal";
        }

        boolean xWins = checkWin(PLAYER_X);
        boolean oWins = checkWin(PLAYER_O);

        // 2. Both players cannot win simultaneously
        if (xWins && oWins) {
            return "illegal";
        }

        // 3. Check for X win
        if (xWins) {
            // If X wins, X must have made the last move, so X count should be O count + 1.
            if (counts.xCount == counts.oCount) {
                return "illegal";
            }
            return "the first player won";
        }

        // 4. Check for O win
        if (oWins) {
            // If O wins, O must have made the last move, so counts must be equal.
            // Original logic: if(o + 1 == x) illegal.
            if (counts.oCount + 1 == counts.xCount) {
                return "illegal";
            }
            return "the second player won";
        }

        // 5. No winner yet
        if (counts.emptyCount == 0) {
            return "draw";
        }

        // 6. Determine whose turn it is
        if (counts.xCount == counts.oCount) {
            return "first"; // X's turn
        } else {
            return "second"; // O's turn
        }
    }

    /**
     * Helper class to store move counts.
     */
    private static class MoveCounts {
        int xCount;
        int oCount;
        int emptyCount;

        MoveCounts(int x, int o, int e) {
            this.xCount = x;
            this.oCount = o;
            this.emptyCount = e;
        }
    }

    /**
     * Counts the number of X's, O's, and empty spaces on the board.
     */
    private MoveCounts countMoves() {
        int x = 0;
        int o = 0;
        int e = 0;

        for (int r = 0; r < BOARD_SIZE; r++) {
            for (int c = 0; c < BOARD_SIZE; c++) {
                char cell = board[r][c];
                if (cell == PLAYER_X) x++;
                else if (cell == PLAYER_O) o++;
                else e++;
            }
        }
        return new MoveCounts(x, o, e);
    }

    /**
     * Checks if the specified player has won.
     *
     * @param player The character representing the player ('X' or '0').
     * @return true if the player has a winning line, false otherwise.
     */
    private boolean checkWin(char player) {
        // Check Rows
        for (int r = 0; r < BOARD_SIZE; r++) {
            if (isLineWin(r, 0, 0, 1, player)) return true;
        }

        // Check Columns
        for (int c = 0; c < BOARD_SIZE; c++) {
            if (isLineWin(0, c, 1, 0, player)) return true;
        }

        // Check Diagonals
        if (isLineWin(0, 0, 1, 1, player)) return true;
        if (isLineWin(0, 2, 1, -1, player)) return true;

        return false;
    }

    /**
     * Checks a specific line (row, column, or diagonal) for a win.
     *
     * @param startRow The starting row index.
     * @param startCol The starting column index.
     * @param rowStep  The step to take for rows (0 or 1).
     * @param colStep  The step to take for columns (0, 1, or -1).
     * @param player   The player character to check.
     * @return true if the line is a win for the player.
     */
    private boolean isLineWin(int startRow, int startCol, int rowStep, int colStep, char player) {
        for (int i = 0; i < BOARD_SIZE; i++) {
            if (board[startRow + i * rowStep][startCol + i * colStep] != player) {
                return false;
            }
        }
        return true;
    }

    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);

        // Read the 3 rows of the grid
        String[] gridRows = new String[BOARD_SIZE];
        for (int i = 0; i < BOARD_SIZE; i++) {
            if (in.hasNext()) {
                gridRows[i] = in.next();
            } else {
                gridRows[i] = ""; // Fallback for missing input
            }
        }

        // Create validator and print result
        TicTacToeValidator validator = new TicTacToeValidator(gridRows);
        System.out.println(validator.validate());

        in.close();
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

/**
 * Refactored version of C3C.
 * Renamed to TicTacToeValidator to improve semantic clarity and maintainability.
 * This program analyzes a 3x3 Tic-Tac-Toe board state to determine the game status.
 * Input format: 3 lines, each containing a string of 3 characters ('X', '0', or space).
 */
public class TicTacToeValidator {

    // Constants for better readability and maintainability
    private static final int BOARD_SIZE = 3;
    private static final char PLAYER_X = 'X';
    private static final char PLAYER_O = '0'; // Note: Input uses '0' (zero) for the second player

    // Game State
    private char[][] board;
    private int xCount;
    private int oCount;

    // I/O Components
    private BufferedReader reader;
    private StringTokenizer tokenizer;

    /**
     * Constructor initializes the board and I/O resources.
     */
    public TicTacToeValidator() {
        this.reader = new BufferedReader(new InputStreamReader(System.in));
        this.board = new char[BOARD_SIZE][BOARD_SIZE];
        this.xCount = 0;
        this.oCount = 0;
        this.tokenizer = null;
    }

    /**
     * Main execution flow.
     */
    public void run() {
        try {
            readBoard();
            String result = analyzeGame();
            System.out.print(result);
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    /**
     * Reads the board configuration from standard input.
     * Expects 3 tokens, each representing a row.
     */
    private void readBoard() throws IOException {
        for (int i = 0; i < BOARD_SIZE; i++) {
            String rowStr = next();
            if (rowStr == null) break; // Handle unexpected EOF

            // Ensure the string is long enough to avoid IndexOutOfBoundsException
            for (int j = 0; j < BOARD_SIZE && j < rowStr.length(); j++) {
                char c = rowStr.charAt(j);
                board[i][j] = c;
                if (c == PLAYER_X) {
                    xCount++;
                } else if (c == PLAYER_O) {
                    oCount++;
                }
            }
        }
    }

    /**
     * Analyzes the current board state to determine the game outcome.
     * 
     * Logic Rules:
     * 1. X goes first. xCount must equal oCount or oCount + 1.
     * 2. If X wins, xCount must be oCount + 1.
     * 3. If O wins, xCount must be oCount.
     * 4. Both players cannot win simultaneously.
     * 5. If no winner and board is full, it's a draw.
     * 6. If no winner and board not full, return whose turn it is ("first" or "second").
     */
    private String analyzeGame() {
        boolean xWins = checkWin(PLAYER_X);
        boolean oWins = checkWin(PLAYER_O);

        // Rule 1: Validate move counts
        // X starts, so X can have at most 1 more move than O, and never fewer.
        if (xCount < oCount || xCount > oCount + 1) {
            return "illegal";
        }

        // Rule 2: Validate simultaneous wins
        if (xWins && oWins) {
            return "illegal";
        }

        // Rule 3: Validate X win
        if (xWins) {
            // If X wins, X must have made the last move.
            if (xCount == oCount + 1) {
                return "the first player won";
            } else {
                // X won but counts are equal (O played last), which is impossible for a valid win.
                return "illegal";
            }
        }

        // Rule 4: Validate O win
        if (oWins) {
            // If O wins, O must have made the last move.
            if (xCount == oCount) {
                return "the second player won";
            } else {
                // O won but X played last (xCount > oCount), which is impossible for a valid win.
                return "illegal";
            }
        }

        // Rule 5: No winner found
        int totalMoves = xCount + oCount;
        if (totalMoves == BOARD_SIZE * BOARD_SIZE) {
            return "draw";
        }

        // Rule 6: Game in progress
        if (xCount == oCount) {
            return "first"; // It is X's turn
        } else {
            return "second"; // It is O's turn
        }
    }

    /**
     * Checks if the specified player has a winning line (row, column, or diagonal).
     */
    private boolean checkWin(char player) {
        // Check Rows
        for (int i = 0; i < BOARD_SIZE; i++) {
            if (board[i][0] == player && board[i][1] == player && board[i][2] == player) {
                return true;
            }
        }

        // Check Columns
        for (int j = 0; j < BOARD_SIZE; j++) {
            if (board[0][j] == player && board[1][j] == player && board[2][j] == player) {
                return true;
            }
        }

        // Check Diagonals
        if (board[0][0] == player && board[1][1] == player && board[2][2] == player) return true;
        if (board[0][2] == player && board[1][1] == player && board[2][0] == player) return true;

        return false;
    }

    /**
     * Helper method to retrieve the next token from input, handling newlines.
     */
    private String next() throws IOException {
        while (tokenizer == null || !tokenizer.hasMoreTokens()) {
            String line = reader.readLine();
            if (line == null) return null;
            tokenizer = new StringTokenizer(line);
        }
        return tokenizer.nextToken();
    }

    public static void main(String[] args) {
        new TicTacToeValidator().run();
    }
}

import java.util.Scanner;

/**
 * Validates a Tic-Tac-Toe board state.
 * This program reads a 3x3 board configuration and determines if the state is valid,
 * who won, or whose turn it is.
 * 
 * Refactoring Notes:
 * 1. Class renamed to TicTacToeValidator for clarity.
 * 2. Magic numbers replaced with constants.
 * 3. Logic separated into helper methods (read input, validate counts, check wins).
 * 4. DRY principle applied to win-checking logic.
 * 5. Variable names made descriptive.
 * 6. Resource management improved using try-with-resources.
 */
public class TicTacToeValidator {

    private static final int BOARD_SIZE = 3;

    public static void main(String[] args) {
        // Use try-with-resources to ensure the Scanner is closed automatically
        try (Scanner scanner = new Scanner(System.in)) {
            char[][] board = new char[BOARD_SIZE][BOARD_SIZE];
            int xCount = 0;
            int oCount = 0;

            // 1. Read Input and Count Moves
            for (int i = 0; i < BOARD_SIZE; i++) {
                if (!scanner.hasNextLine()) {
                    break;
                }
                String line = scanner.nextLine();

                // Parse the line into the board and count pieces
                // Note: The original code uses '0' (digit zero) for the second player.
                for (int j = 0; j < BOARD_SIZE && j < line.length(); j++) {
                    char c = line.charAt(j);
                    board[i][j] = c;
                    if (c == 'X') {
                        xCount++;
                    } else if (c == '0') {
                        oCount++;
                    }
                }
            }

            // 2. Validate Move Counts
            // Original logic: o > x || x > 5 || o > 4 || x - o > 1
            if (isIllegalMoveCount(xCount, oCount)) {
                System.out.println("illegal");
                return;
            }

            // 3. Check for Wins
            // Note: Using '0' (digit zero) to match original logic
            boolean xWon = checkWin(board, 'X');
            boolean oWon = checkWin(board, '0');

            // 4. Determine Outcome
            if (xWon && oWon) {
                System.out.println("illegal");
            } else if (xWon) {
                if (xCount - oCount == 1) {
                    System.out.println("the first player won");
                } else {
                    System.out.println("illegal");
                }
            } else if (oWon) {
                if (xCount == oCount) {
                    System.out.println("the second player won");
                } else {
                    System.out.println("illegal");
                }
            } else {
                // No winner
                if (xCount == 5) {
                    System.out.println("draw");
                } else if (xCount == oCount) {
                    System.out.println("first");
                } else {
                    System.out.println("second");
                }
            }
        }
    }

    /**
     * Checks if the move counts violate Tic-Tac-Toe rules.
     * Rules:
     * 1. O cannot have played more moves than X.
     * 2. X cannot have played more than 5 moves (max in 3x3).
     * 3. O cannot have played more than 4 moves.
     * 4. X cannot have played more than 1 move ahead of O.
     */
    private static boolean isIllegalMoveCount(int xCount, int oCount) {
        return oCount > xCount || xCount > 5 || oCount > 4 || (xCount - oCount) > 1;
    }

    /**
     * Checks if the specified player has won the game.
     */
    private static boolean checkWin(char[][] board, char player) {
        // Check rows
        for (int i = 0; i < BOARD_SIZE; i++) {
            if (board[i][0] == player && board[i][1] == player && board[i][2] == player) {
                return true;
            }
        }

        // Check columns
        for (int j = 0; j < BOARD_SIZE; j++) {
            if (board[0][j] == player && board[1][j] == player && board[2][j] == player) {
                return true;
            }
        }

        // Check diagonals
        if (board[0][0] == player && board[1][1] == player && board[2][2] == player) {
            return true;
        }
        if (board[0][2] == player && board[1][1] == player && board[2][0] == player) {
            return true;
        }

        return false;
    }
}

import java.io.*;

/**
 * Solves a Tic-Tac-Toe board reachability problem.
 * Determines if a given board state is valid, who won, or whose turn it is next.
 */
public class TicTacToeSolver {

    private static final int BOARD_SIZE = 3;
    private static final char CROSS = 'X';
    private static final char ZERO = 'O'; // Letter 'O', not digit '0'
    private static final char EMPTY = '.';

    public static void main(String[] args) {
        // Try-with-resources ensures streams are closed properly
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
             PrintWriter writer = new PrintWriter(new BufferedOutputStream(System.out))) {

            solve(reader, writer);
            writer.flush();

        } catch (IOException e) {
            System.err.println("I/O Error: " + e.getMessage());
            System.exit(1);
        }
    }

    /**
     * Orchestrates reading input, solving, and writing output.
     */
    private static void solve(BufferedReader reader, PrintWriter writer) throws IOException {
        char[][] targetBoard = readBoard(reader);
        if (targetBoard == null) return;

        GameOutcome outcome = checkBoardReachability(targetBoard);

        if (!outcome.found) {
            writer.println("illegal");
            return;
        }

        if (hasWinner(targetBoard, CROSS)) {
            writer.println("the first player won");
        } else if (hasWinner(targetBoard, ZERO)) {
            writer.println("the second player won");
        } else if (outcome.isDraw) {
            writer.println("draw");
        } else {
            writer.println(outcome.whoseTurn == CROSS ? "first" : "second");
        }
    }

    /**
     * Reads exactly 3 lines from the input to form the target board.
     */
    private static char[][] readBoard(BufferedReader reader) throws IOException {
        char[][] board = new char[BOARD_SIZE][BOARD_SIZE];
        for (int i = 0; i < BOARD_SIZE; i++) {
            String line = reader.readLine();
            if (line == null || line.length() < BOARD_SIZE) {
                throw new IOException("Invalid input: expected a row of at least " + BOARD_SIZE + " characters.");
            }
            board[i] = line.trim().substring(0, BOARD_SIZE).toCharArray();
        }
        return board;
    }

    /**
     * Initiates the recursive search to determine if the target board is reachable.
     */
    private static GameOutcome checkBoardReachability(char[][] target) {
        char[][] current = new char[BOARD_SIZE][BOARD_SIZE];
        return explore(target, current, CROSS);
    }

    /**
     * Recursively explores all valid game states from an empty board.
     * Returns early once the target board is found.
     */
    private static GameOutcome explore(char[][] target, char[][] current, char nextPlayer) {
        // Check if current state matches the target
        if (boardsEqual(target, current)) {
            return new GameOutcome(true, nextPlayer, isFull(current));
        }

        // Prune branches where a winner already exists
        if (hasWinner(current, CROSS) || hasWinner(current, ZERO)) {
            return GameOutcome.ILLEGAL;
        }

        // Try placing the current player in every empty cell
        for (int i = 0; i < BOARD_SIZE; i++) {
            for (int j = 0; j < BOARD_SIZE; j++) {
                if (current[i][j] == EMPTY) {
                    current[i][j] = nextPlayer;
                    GameOutcome result = explore(target, current, nextPlayer == CROSS ? ZERO : CROSS);
                    if (result.found) {
                        return result; // Early exit for efficiency
                    }
                    current[i][j] = EMPTY; // Backtrack
                }
            }
        }
        return GameOutcome.ILLEGAL;
    }

    /**
     * Compares two 3x3 boards for equality.
     */
    private static boolean boardsEqual(char[][] a, char[][] b) {
        for (int i = 0; i < BOARD_SIZE; i++) {
            for (int j = 0; j < BOARD_SIZE; j++) {
                if (a[i][j] != b[i][j]) return false;
            }
        }
        return true;
    }

    /**
     * Checks if the board is completely filled.
     */
    private static boolean isFull(char[][] board) {
        for (char[] row : board) {
            for (char cell : row) {
                if (cell == EMPTY) return false;
            }
        }
        return true;
    }

    /**
     * Checks if a specific player has won on the board.
     */
    private static boolean hasWinner(char[][] board, char player) {
        // Check rows
        for (int i = 0; i < BOARD_SIZE; i++) {
            if (board[i][0] == player && board[i][1] == player && board[i][2] == player) return true;
        }
        // Check columns
        for (int j = 0; j < BOARD_SIZE; j++) {
            if (board[0][j] == player && board[1][j] == player && board[2][j] == player) return true;
        }
        // Check diagonals
        if (board[0][0] == player && board[1][1] == player && board[2][2] == player) return true;
        if (board[0][2] == player && board[1][1] == player && board[2][0] == player) return true;
        return false;
    }

    /**
     * Immutable result holder for the reachability search.
     */
    private static class GameOutcome {
        final boolean found;
        final char whoseTurn;
        final boolean isDraw;

        private GameOutcome(boolean found, char whoseTurn, boolean isDraw) {
            this.found = found;
            this.whoseTurn = whoseTurn;
            this.isDraw = isDraw;
        }

        static final GameOutcome ILLEGAL = new GameOutcome(false, 0, false);
    }
}

import java.io.*;
import java.util.*;

/**
 * Tic-Tac-Toe Solver using precomputed minimax with memoization.
 * Evaluates board states and determines the optimal outcome (win, loss, draw, or ongoing).
 */
public class TicTacToeSolver {

    // Game constants
    private static final int BOARD_SIZE = 9;
    private static final int BASE = 3;
    private static final int MAX_STATES = (int) Math.pow(BASE, BOARD_SIZE); // 19683
    private static final int EMPTY = 0;
    private static final int PLAYER_1 = 1;
    private static final int PLAYER_2 = 2;
    private static final int RESULT_DRAW = 3;
    private static final int RESULT_ONGOING = 0;

    // Memoization array: stores the game result for each encoded board state
    private final int[] memo = new int[MAX_STATES];

    // I/O streams
    private final BufferedReader reader;
    private final PrintWriter writer;

    public TicTacToeSolver() {
        this.reader = new BufferedReader(new InputStreamReader(System.in));
        this.writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)));
    }

    /**
     * Entry point: precomputes all reachable game states, then processes input.
     */
    public void run() {
        precomputeAllStates();
        try {
            solve();
        } catch (IOException e) {
            e.printStackTrace();
        } finally {
            writer.flush();
        }
    }

    /**
     * Runs the minimax algorithm from the empty board to fill the memoization table.
     */
    private void precomputeAllStates() {
        int[] board = new int[BOARD_SIZE];
        minimax(board, PLAYER_1);
    }

    /**
     * Recursive minimax with memoization.
     *
     * @param board         Current board state (modified in-place, backtracked after recursion)
     * @param currentPlayer The player whose turn it is
     * @return Game result: PLAYER_1 wins, PLAYER_2 wins, RESULT_DRAW, or RESULT_ONGOING
     */
    private int minimax(int[] board, int currentPlayer) {
        int stateCode = encodeBoard(board);
        if (memo[stateCode] != RESULT_ONGOING) {
            return memo[stateCode];
        }

        int winner = evaluateBoard(board);
        if (winner != RESULT_ONGOING) {
            memo[stateCode] = winner;
            return winner;
        }

        int nextPlayer = currentPlayer == PLAYER_1 ? PLAYER_2 : PLAYER_1;
        int bestOutcome = nextPlayer; // Assume loss initially

        for (int i = 0; i < BOARD_SIZE; i++) {
            if (board[i] == EMPTY) {
                board[i] = currentPlayer;
                int outcome = minimax(board, nextPlayer);
                board[i] = EMPTY; // Backtrack

                if (outcome == currentPlayer) {
                    bestOutcome = currentPlayer;
                    break; // Winning move found; no need to check further
                } else if (outcome == RESULT_DRAW) {
                    bestOutcome = RESULT_DRAW;
                    break; // Draw is better than loss; optimal path found
                }
            }
        }

        memo[stateCode] = bestOutcome;
        return bestOutcome;
    }

    /**
     * Evaluates the current board state for wins, draws, or ongoing games.
     */
    private int evaluateBoard(int[] board) {
        // Check rows
        for (int i = 0; i < BOARD_SIZE; i += 3) {
            if (board[i] != EMPTY && board[i] == board[i + 1] && board[i] == board[i + 2]) {
                return board[i];
            }
        }
        // Check columns
        for (int i = 0; i < 3; i++) {
            if (board[i] != EMPTY && board[i] == board[i + 3] && board[i] == board[i + 6]) {
                return board[i];
            }
        }
        // Check diagonals
        if (board[0] != EMPTY && board[0] == board[4] && board[0] == board[8]) return board[0];
        if (board[2] != EMPTY && board[2] == board[4] && board[2] == board[6]) return board[2];

        // Check for draw or ongoing
        for (int cell : board) {
            if (cell == EMPTY) return RESULT_ONGOING;
        }
        return RESULT_DRAW;
    }

    /**
     * Encodes a 9-element board array into a base-3 integer for memoization indexing.
     */
    private int encodeBoard(int[] board) {
        int code = 0;
        int multiplier = 1;
        for (int cell : board) {
            code += cell * multiplier;
            multiplier *= BASE;
        }
        return code;
    }

    /**
     * Processes a single test case: reads the board, validates it, and prints the result.
     */
    private void solve() throws IOException {
        int[] board = readBoard();
        int stateCode = encodeBoard(board);

        // If the state was never reached during precomputation, it's illegal/unreachable
        if (memo[stateCode] == RESULT_ONGOING) {
            writer.println("illegal");
            return;
        }

        int result = memo[stateCode];
        if (result == PLAYER_1) {
            writer.println("the first player won");
        } else if (result == PLAYER_2) {
            writer.println("the second player won");
        } else if (result == RESULT_DRAW) {
            writer.println("draw");
        } else {
            // Game is ongoing; determine whose turn it is
            int[] counts = new int[3];
            for (int cell : board) counts[cell]++;
            if (counts[PLAYER_1] > counts[PLAYER_2]) {
                writer.println("second");
            } else {
                writer.println("first");
            }
        }
    }

    /**
     * Reads the 3x3 board from standard input.
     */
    private int[] readBoard() throws IOException {
        int[] board = new int[BOARD_SIZE];
        for (int i = 0; i < BOARD_SIZE; i += 3) {
            String line = readToken();
            for (int j = 0; j < 3; j++) {
                char c = line.charAt(j);
                if (c == 'X') board[i + j] = PLAYER_1;
                else if (c == 'O' || c == '0') board[i + j] = PLAYER_2;
                else board[i + j] = EMPTY;
            }
        }
        return board;
    }

    /**
     * Reads the next whitespace-delimited token from input.
     */
    private String readToken() throws IOException {
        StringBuilder sb = new StringBuilder();
        int c;
        while ((c = reader.read()) != -1 && c <= ' ') {}
        if (c == -1) return "";
        while (c > ' ') {
            sb.append((char) c);
            c = reader.read();
        }
        return sb.toString();
    }

    public static void main(String[] args) {
        new TicTacToeSolver().run();
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;

public class TicTacToeValidator {

    private static final int BOARD_SIZE = 3;
    private static final int EMPTY = 0;
    private static final int PLAYER1 = 1; // Represents 'X'
    private static final int PLAYER2 = 2; // Represents '0'

    private final int[][] board;
    private int player1Count;
    private int player2Count;
    private boolean isBoardFull;

    public TicTacToeValidator() {
        board = new int[BOARD_SIZE][BOARD_SIZE];
        player1Count = 0;
        player2Count = 0;
        isBoardFull = true;
    }

    /**
     * Parses the input lines and populates the internal board state.
     */
    public void loadBoard(String[] lines) {
        for (int i = 0; i < BOARD_SIZE; i++) {
            String line = lines[i].trim();
            if (line.length() < BOARD_SIZE) {
                throw new IllegalArgumentException("Invalid board input at row " + i);
            }
            for (int j = 0; j < BOARD_SIZE; j++) {
                char c = line.charAt(j);
                if (c == 'X') {
                    board[i][j] = PLAYER1;
                    player1Count++;
                } else if (c == '0') {
                    board[i][j] = PLAYER2;
                    player2Count++;
                } else {
                    board[i][j] = EMPTY;
                    isBoardFull = false;
                }
            }
        }
    }

    /**
     * Determines if there is a winner. Returns -1 if the state is illegal 
     * (i.e., two different players have winning lines).
     */
    private int findWinner() {
        int winner = EMPTY;
        int winningPlayerCount = 0;

        // Check rows
        for (int i = 0; i < BOARD_SIZE; i++) {
            if (board[i][0] != EMPTY && board[i][0] == board[i][1] && board[i][1] == board[i][2]) {
                if (winner == EMPTY) {
                    winner = board[i][0];
                    winningPlayerCount++;
                } else if (winner != board[i][0]) {
                    winningPlayerCount++;
                }
            }
        }

        // Check columns
        for (int i = 0; i < BOARD_SIZE; i++) {
            if (board[0][i] != EMPTY && board[0][i] == board[1][i] && board[1][i] == board[2][i]) {
                if (winner == EMPTY) {
                    winner = board[0][i];
                    winningPlayerCount++;
                } else if (winner != board[0][i]) {
                    winningPlayerCount++;
                }
            }
        }

        // Check main diagonal
        if (board[0][0] != EMPTY && board[0][0] == board[1][1] && board[1][1] == board[2][2]) {
            if (winner == EMPTY) {
                winner = board[0][0];
                winningPlayerCount++;
            } else if (winner != board[0][0]) {
                winningPlayerCount++;
            }
        }

        // Check anti-diagonal
        if (board[0][2] != EMPTY && board[0][2] == board[1][1] && board[1][1] == board[2][0]) {
            if (winner == EMPTY) {
                winner = board[0][2];
                winningPlayerCount++;
            } else if (winner != board[0][2]) {
                winningPlayerCount++;
            }
        }

        // If two different players have winning lines, the state is illegal
        if (winningPlayerCount > 1) {
            return -1;
        }

        return winner;
    }

    /**
     * Evaluates the current board state and returns the result string.
     */
    public String evaluate() {
        int winner = findWinner();
        if (winner == -1) {
            return "illegal";
        }

        if (isBoardFull) {
            if (player1Count != player2Count + 1) {
                return "illegal";
            }
            if (winner == EMPTY) {
                return "draw";
            } else if (winner == PLAYER1) {
                return "the first player won";
            } else {
                return "the second player won";
            }
        }

        // Determine whose turn it is based on move counts
        int toMove;
        if (player1Count == player2Count) {
            toMove = PLAYER1;
        } else if (player1Count == player2Count + 1) {
            toMove = PLAYER2;
        } else {
            return "illegal";
        }

        if (winner != EMPTY) {
            // If there's a winner, the game should have ended on the previous move.
            // If the current player to move matches the winner, it's an illegal state.
            if (winner == toMove) {
                return "illegal";
            } else if (winner == PLAYER1) {
                return "the first player won";
            } else {
                return "the second player won";
            }
        } else {
            return toMove == PLAYER1 ? "first" : "second";
        }
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String[] lines = new String[BOARD_SIZE];

        for (int i = 0; i < BOARD_SIZE; i++) {
            lines[i] = br.readLine();
            if (lines[i] == null) {
                throw new IOException("Unexpected end of input");
            }
        }

        TicTacToeValidator validator = new TicTacToeValidator();
        validator.loadBoard(lines);
        System.out.println(validator.evaluate());
    }
}

import java.util.Scanner;

public class TicTacToe {

    // Constants for board configuration and players
    // Note: Changed '0' (digit) to 'O' (letter) for semantic correctness and readability.
    private static final int BOARD_SIZE = 3;
    private static final char PLAYER_X = 'X';
    private static final char PLAYER_O = 'O';

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        char[][] board = new char[BOARD_SIZE][BOARD_SIZE];
        int xCount = 0;
        int oCount = 0;

        // 1. Read the board state from input
        // Using Scanner for cleaner input handling compared to BufferedReader
        for (int i = 0; i < BOARD_SIZE; i++) {
            if (scanner.hasNextLine()) {
                String line = scanner.nextLine();
                // Ensure we don't go out of bounds if line is shorter than expected
                for (int j = 0; j < BOARD_SIZE && j < line.length(); j++) {
                    char cell = line.charAt(j);
                    board[i][j] = cell;
                    if (cell == PLAYER_X) {
                        xCount++;
                    } else if (cell == PLAYER_O) {
                        oCount++;
                    }
                }
            }
        }
        scanner.close();

        // 2. Check for winning conditions
        boolean xWon = checkWin(board, PLAYER_X);
        boolean oWon = checkWin(board, PLAYER_O);

        // 3. Determine the game state and result
        String result = evaluateGameState(xCount, oCount, xWon, oWon);
        System.out.println(result);
    }

    /**
     * Checks if a specific player has won the game.
     * A win is defined as having a complete row, column, or diagonal.
     */
    private static boolean checkWin(char[][] board, char player) {
        // Check Rows
        for (int i = 0; i < BOARD_SIZE; i++) {
            if (isLineWin(board[i], player)) {
                return true;
            }
        }

        // Check Columns
        for (int j = 0; j < BOARD_SIZE; j++) {
            char[] col = new char[BOARD_SIZE];
            for (int i = 0; i < BOARD_SIZE; i++) {
                col[i] = board[i][j];
            }
            if (isLineWin(col, player)) {
                return true;
            }
        }

        // Check Diagonals
        char[] diag1 = new char[BOARD_SIZE];
        char[] diag2 = new char[BOARD_SIZE];
        for (int i = 0; i < BOARD_SIZE; i++) {
            diag1[i] = board[i][i];
            diag2[i] = board[i][BOARD_SIZE - 1 - i];
        }

        return isLineWin(diag1, player) || isLineWin(diag2, player);
    }

    /**
     * Checks if a 1D array (line) consists entirely of the player's symbol.
     */
    private static boolean isLineWin(char[] line, char player) {
        for (char cell : line) {
            if (cell != player) {
                return false;
            }
        }
        return true;
    }

    /**
     * Evaluates the game state based on piece counts and win status.
     * Returns a string describing the outcome.
     */
    private static String evaluateGameState(int xCount, int oCount, boolean xWon, boolean oWon) {
        // --- Illegal State Checks ---

        // 1. Both players cannot win simultaneously
        if (xWon && oWon) {
            return "illegal";
        }

        // 2. Turn Order Checks
        // X goes first, so O cannot have more moves than X
        if (oCount > xCount) {
            return "illegal";
        }
        // X cannot have more than 1 extra move (X moves, then O, then X...)
        if (xCount - oCount > 1) {
            return "illegal";
        }

        // 3. Winning Move Validation
        // If X won, X must have made the last move (X count = O count + 1)
        if (xWon && xCount != oCount + 1) {
            return "illegal";
        }
        // If O won, O must have made the last move (X count = O count)
        if (oWon && oCount != xCount) {
            return "illegal";
        }

        // --- Valid State Checks ---

        // If X won, X wins
        if (xWon) {
            return "the first player won";
        }

        // If O won, O wins
        if (oWon) {
            return "the second player won";
        }

        // If board is full and no winner, it's a draw
        if (xCount + oCount == BOARD_SIZE * BOARD_SIZE) {
            return "draw";
        }

        // If board is not full, determine whose turn it is
        // If counts are equal, it's X's turn (First Player)
        if (xCount == oCount) {
            return "first";
        }
        // If X has one more move, it's O's turn (Second Player)
        if (xCount > oCount) {
            return "second";
        }

        // Fallback (should theoretically not be reached given checks above)
        return "illegal";
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;

public class Main {
    // Constants for better maintainability
    private static final int BOARD_SIZE = 3;
    private static final char PLAYER_X = 'X';
    private static final char PLAYER_O = '0'; // Using '0' (zero) to match original logic

    public static void main(String[] args) throws IOException {
        // Use try-with-resources for automatic resource management
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
             PrintWriter out = new PrintWriter(System.out)) {

            char[][] board = new char[BOARD_SIZE][BOARD_SIZE];
            int xCount = 0;
            int oCount = 0;

            // 1. Read Input and Count Moves
            for (int i = 0; i < BOARD_SIZE; i++) {
                String line = reader.readLine();
                // Safety check to prevent NullPointerException or IndexOutOfBoundsException
                if (line != null && line.length() >= BOARD_SIZE) {
                    for (int j = 0; j < BOARD_SIZE; j++) {
                        board[i][j] = line.charAt(j);
                        if (board[i][j] == PLAYER_X) {
                            xCount++;
                        } else if (board[i][j] == PLAYER_O) {
                            oCount++;
                        }
                    }
                }
            }

            // 2. Validate Move Counts
            // In a valid game, X must have played the same number of times as O,
            // or X must have played exactly one more time than O.
            int moveDifference = xCount - oCount;
            if (moveDifference < 0 || moveDifference > 1) {
                out.println("illegal");
                return;
            }

            // 3. Check for Winners
            boolean xWin = hasWon(board, PLAYER_X);
            boolean oWin = hasWon(board, PLAYER_O);

            // 4. Validate Win Conditions
            // - Both players cannot win simultaneously.
            // - If X wins, X must have made the last move (xCount = oCount + 1).
            // - If O wins, O must have made the last move (xCount = oCount).
            if (xWin && oWin) {
                out.println("illegal");
            } else if (xWin && moveDifference != 1) {
                out.println("illegal");
            } else if (oWin && moveDifference != 0) {
                out.println("illegal");
            }
            // 5. Output Results
            else if (xWin) {
                out.println("the first player won");
            } else if (oWin) {
                out.println("the second player won");
            } else if (xCount + oCount == BOARD_SIZE * BOARD_SIZE) {
                out.println("draw");
            } else {
                // Determine whose turn it is
                if (xCount == oCount) {
                    out.println("first");
                } else {
                    out.println("second");
                }
            }
        }
    }

    /**
     * Checks if the specified player has won the game.
     * Checks rows, columns, and diagonals.
     */
    private static boolean hasWon(char[][] board, char player) {
        // Check Rows
        for (int i = 0; i < BOARD_SIZE; i++) {
            if (board[i][0] == player && board[i][1] == player && board[i][2] == player) {
                return true;
            }
        }

        // Check Columns
        for (int j = 0; j < BOARD_SIZE; j++) {
            if (board[0][j] == player && board[1][j] == player && board[2][j] == player) {
                return true;
            }
        }

        // Check Diagonals
        if (board[0][0] == player && board[1][1] == player && board[2][2] == player) {
            return true;
        }
        if (board[0][2] == player && board[1][1] == player && board[2][0] == player) {
            return true;
        }

        return false;
    }
}

import java.util.Scanner;

public class Solution {
    private static final int BOARD_SIZE = 3;
    private static final char FIRST_PLAYER = 'X';
    private static final char SECOND_PLAYER = '0'; // Kept as '0' to match original input format
    private static final char EMPTY = '.';

    public static void main(String[] args) {
        char[][] board = new char[BOARD_SIZE][BOARD_SIZE];

        try (Scanner scanner = new Scanner(System.in)) {
            for (int i = 0; i < BOARD_SIZE; i++) {
                board[i] = scanner.next().toCharArray();
            }
        }

        GameResult result = validateBoard(board);
        System.out.println(result.getMessage());
    }

    /**
     * Validates the Tic-Tac-Toe board state and determines the outcome.
     */
    private static GameResult validateBoard(char[][] board) {
        int firstCount = 0;
        int secondCount = 0;

        // Count moves for each player
        for (char[] row : board) {
            for (char cell : row) {
                if (cell == FIRST_PLAYER) firstCount++;
                else if (cell == SECOND_PLAYER) secondCount++;
            }
        }

        // Rule: X must be equal to O or exactly one more than O
        if (secondCount > firstCount || firstCount > secondCount + 1) {
            return GameResult.ILLEGAL;
        }

        boolean firstWins = checkWin(board, FIRST_PLAYER);
        boolean secondWins = checkWin(board, SECOND_PLAYER);

        // Both players cannot win simultaneously
        if (firstWins && secondWins) {
            return GameResult.ILLEGAL;
        }

        // Validate win against move counts
        if (firstWins) {
            return firstCount == secondCount + 1 ? GameResult.FIRST_WINS : GameResult.ILLEGAL;
        }
        if (secondWins) {
            return secondCount == firstCount ? GameResult.SECOND_WINS : GameResult.ILLEGAL;
        }

        // No winner yet
        int totalMoves = firstCount + secondCount;
        if (totalMoves == BOARD_SIZE * BOARD_SIZE) {
            return GameResult.DRAW;
        }

        // Determine whose turn it is next
        return firstCount > secondCount ? GameResult.SECOND_TURN : GameResult.FIRST_TURN;
    }

    /**
     * Checks if a specific player has won on the board.
     */
    private static boolean checkWin(char[][] board, char player) {
        // Check rows
        for (int i = 0; i < BOARD_SIZE; i++) {
            if (board[i][0] == player && board[i][1] == player && board[i][2] == player) {
                return true;
            }
        }
        // Check columns
        for (int j = 0; j < BOARD_SIZE; j++) {
            if (board[0][j] == player && board[1][j] == player && board[2][j] == player) {
                return true;
            }
        }
        // Check diagonals (only possible if center is occupied by the player)
        if (board[1][1] == player) {
            if (board[0][0] == player && board[2][2] == player) return true;
            if (board[0][2] == player && board[2][0] == player) return true;
        }
        return false;
    }

    /**
     * Enumerates all possible game outcomes with their corresponding output messages.
     */
    public enum GameResult {
        FIRST_WINS("first player won"),
        SECOND_WINS("second player won"),
        DRAW("draw"),
        ILLEGAL("illegal"),
        FIRST_TURN("first"),
        SECOND_TURN("second");

        private final String message;

        GameResult(String message) {
            this.message = message;
        }

        public String getMessage() {
            return message;
        }
    }
}

