public class TicTacToe {
    // Constants replace magic numbers
    private static final int BOARD_SIZE = 3;
    private static final char PLAYER_X = 'X';
    private static final char PLAYER_ZERO = '0'; // Original spec uses digit '0'
    private static final char EMPTY = ' ';

    // Encapsulated board state
    private char[][] board = new char[BOARD_SIZE][BOARD_SIZE];

    public static void main(String[] args) {
        // Try-with-resources ensures the Scanner is properly closed
        try (Scanner scanner = new Scanner(System.in)) {
            TicTacToe game = new TicTacToe();
            game.parseInput(scanner);

            if (!game.isValidState()) {
                System.out.println("illegal");
                return;
            }

            System.out.println(game.getGameStatus());
        }
    }

    /**
     * Parses the 3x3 board input from the scanner.
     */
    private void parseInput(Scanner scanner) {
        for (int i = 0; i < BOARD_SIZE; i++) {
            String line = scanner.next();
            for (int j = 0; j < BOARD_SIZE; j++) {
                char c = line.charAt(j);
                if (c == PLAYER_X) {
                    board[i][j] = PLAYER_X;
                } else if (c == PLAYER_ZERO) {
                    board[i][j] = PLAYER_ZERO;
                } else {
                    board[i][j] = EMPTY;
                }
            }
        }
    }

    /**
     * Validates the board state according to Tic-Tac-Toe rules.
     */
    private boolean isValidState() {
        int xCount = 0;
        int zeroCount = 0;

        for (int i = 0; i < BOARD_SIZE; i++) {
            for (int j = 0; j < BOARD_SIZE; j++) {
                if (board[i][j] == PLAYER_X) xCount++;
                else if (board[i][j] == PLAYER_ZERO) zeroCount++;
            }
        }

        // X goes first, so counts must be equal or X has one more move
        if (xCount - zeroCount > 1 || xCount < zeroCount) {
            return false;
        }

        // Both players cannot win simultaneously
        if (checkWinner(PLAYER_X) && checkWinner(PLAYER_ZERO)) {
            return false;
        }

        return true;
    }

    /**
     * Checks if the specified player has a winning line.
     */
    private boolean checkWinner(char player) {
        // Check rows and columns
        for (int i = 0; i < BOARD_SIZE; i++) {
            if (board[i][0] == player && board[i][1] == player && board[i][2] == player) {
                return true;
            }
            if (board[0][i] == player && board[1][i] == player && board[2][i] == player) {
                return true;
            }
        }

        // Check diagonals
        if (board[0][0] == player && board[1][1] == player && board[2][2] == player) {
            return true;
        }
        if (board[2][0] == player && board[1][1] == player && board[0][2] == player) {
            return true;
        }

        return false;
    }

    /**
     * Determines the current game status or whose turn is next.
     */
    private String getGameStatus() {
        int xCount = 0;
        int zeroCount = 0;

        for (int i = 0; i < BOARD_SIZE; i++) {
            for (int j = 0; j < BOARD_SIZE; j++) {
                if (board[i][j] == PLAYER_X) xCount++;
                else if (board[i][j] == PLAYER_ZERO) zeroCount++;
            }
        }

        boolean xWins = checkWinner(PLAYER_X);
        boolean zeroWins = checkWinner(PLAYER_ZERO);

        if (xCount == zeroCount) {
            // O's turn or O just won
            if (zeroWins) {
                return "the second player won";
            }
            if (xWins) {
                // Should be caught by isValidState, kept for defensive programming
                return "illegal";
            }
            return "first";
        }

        // xCount == zeroCount + 1
        // X's turn or X just won
        if (xWins) {
            return "the first player won";
        }
        if (zeroWins) {
            // Should be caught by isValidState, kept for defensive programming
            return "illegal";
        }
        if (xCount + zeroCount == BOARD_SIZE * BOARD_SIZE) {
            return "draw";
        }

        return "second";
    }
}

