                } else if (board[i][j] == PLAYER_O) {
                    countO++;
                }
            }
        }

        // Validate move counts: X always goes first, so countX must equal countO or countO + 1
        if (countX != countO && countX != countO + 1) {
            out.println("illegal");
            return;
        }

        boolean xWins = checkWin(board, PLAYER_X);
        boolean oWins = checkWin(board, PLAYER_O);

        // Both players cannot win simultaneously in a valid game
        if (xWins && oWins) {
            out.println("illegal");
