                    for (int j = 0; j < BOARD_SIZE && j < line.length(); j++) {
                        board[i][j] = line.charAt(j);
                    }
                }
            }

            // Count moves for X and O
            int xCount = 0;
            int oCount = 0;
            for (int i = 0; i < BOARD_SIZE; i++) {
                for (int j = 0; j < BOARD_SIZE; j++) {
                    char cell = board[i][j];
                    if (cell == PLAYER_X) {
                        xCount++;
                    } else if (cell == PLAYER_O) {
                        oCount++;
                    }
                }
            }

            // Check win conditions
            boolean xWins = checkWin(board, PLAYER_X);
            boolean oWins = checkWin(board, PLAYER_O);

            // Determine the game result
            String result = determineResult(xCount, oCount, xWins, oWins);

            System.out.println(result);

        }
    }

    /**
     * Checks if the specified player has won the game.
     * Checks rows, columns, and diagonals.
     */
    private static boolean checkWin(char[][] board, char player) {
        // Check rows
        for (int i = 0; i < BOARD_SIZE; i++) {
            if (board[i][0] == player && board[i][1] == player && board[i][2] == player) {
                return true;
            }
        }

        // Check columns
        for (int j = 0; j < BOARD_SIZE; j++) {
            if (board[0][j] == player && board[1][j] == player && board[2][j] == player) {
                return true;
            }
        }

        // Check diagonals
        if (board[0][0] == player && board[1][1] == player && board[2][2] == player) {
            return true;
        }
        if (board[0][2] == player && board[1][1] == player && board[2][0] == player) {
            return true;
        }

        return false;
    }

    /**
     * Determines the game status based on move counts and win flags.
     */
    private static String determineResult(int xCount, int oCount, boolean xWins, boolean oWins) {
        // 1. Validate move counts
        // The difference between counts cannot be 2 or more.
        if (Math.abs(xCount - oCount) >= 2) {
            return "illegal";
        }
        // O cannot have more moves than X (since X goes first).
        if (oCount > xCount) {
            return "illegal";
        }

        // 2. Validate win conditions
        // Both players cannot win simultaneously.
        if (xWins && oWins) {
            return "illegal";
        }

        // If X wins, X must have made the last move (xCount == oCount + 1).
        if (xWins && xCount != oCount + 1) {
            return "illegal";
        }

        // If O wins, O must have made the last move (xCount == oCount).
        if (oWins && xCount != oCount) {
            return "illegal";
        }

        // 3. Determine outcome
        if (xWins) {
            return "the first player won";
        }
        if (oWins) {
            return "the second player won";
        }

        // Check for draw (board full)
        if (xCount + oCount == BOARD_SIZE * BOARD_SIZE) {
            return "draw";
        }

        // Determine whose turn is next
        if (xCount > oCount) {
            return "second"; // It is O's turn
        } else {
            return "first"; // It is X's turn
        }
    }
}

