/**
 * Refactored Tic-Tac-Toe Validator.
 * 
 * Improvements made:
 * 1. Extracted logic into methods (solveTicTacToe, checkWinner) for readability and testability.
 * 2. Used constants for magic numbers (board size, cell values, win sums).
 * 3. Improved variable naming (x_count -> xCount, grid -> board).
 * 4. Used try-with-resources for Scanner to ensure proper resource cleanup.
 * 5. Simplified conditional logic for determining the game state.
 * 6. Added input safety checks to prevent IndexOutOfBoundsException.
 */
public class Main {
    // Constants for board configuration
    private static final int BOARD_SIZE = 3;
    private static final int EMPTY = 0;
    private static final int PLAYER_X = 1;
    private static final int PLAYER_O = 10; // Magic value to allow sum-based win detection

    // Constants for win detection sums
    private static final int WIN_SUM_X = 3;   // 1 + 1 + 1
    private static final int WIN_SUM_O = 30;  // 10 + 10 + 10

    public static void main(String[] args) {
        // Use try-with-resources to ensure Scanner is closed
        try (Scanner scanner = new Scanner(System.in)) {
            String result = solveTicTacToe(scanner);
            System.out.print(result);
        }
    }

    private static String solveTicTacToe(Scanner scanner) {
        int[][] board = new int[BOARD_SIZE][BOARD_SIZE];
        int xCount = 0;
        int oCount = 0;

        // 1. Parse the input board
        for (int i = 0; i < BOARD_SIZE; i++) {
            if (!scanner.hasNext()) {
                break; // Should not happen if input is guaranteed
            }
            String rowStr = scanner.next();
            char[] chars = rowStr.toCharArray();

            for (int j = 0; j < BOARD_SIZE; j++) {
                // Safety check for row length
                if (j < chars.length) {
                    char c = chars[j];
                    int cellValue;

                    if (c == '.') {
                        cellValue = EMPTY;
                    } else if (c == 'X') {
                        cellValue = PLAYER_X;
                        xCount++;
                    } else if (c == 'O') {
                        cellValue = PLAYER_O;
                        oCount++;
                    } else {
                        // Unexpected character, treat as empty
                        cellValue = EMPTY; 
                    }
                    board[i][j] = cellValue;
                }
            }
        }

        // 2. Validate move counts (Basic Game Rules)
        // X always goes first. X count must equal O count or be exactly one greater.
        if (Math.abs(xCount - oCount) > 1 || oCount > xCount) {
            return "illegal";
        }

        // 3. Check for winning conditions
        boolean xWon = checkWinner(board, PLAYER_X, WIN_SUM_X);
        boolean oWon = checkWinner(board, PLAYER_O, WIN_SUM_O);

        // 4. Determine the game outcome
        if (!xWon && !oWon) {
            // No winner yet
            if (xCount + oCount == BOARD_SIZE * BOARD_SIZE) {
                return "draw";
            } else {
                // Game in progress, determine whose turn it is
                // If counts are equal, it's X's turn (First player)
                // If X has one more, it's O's turn (Second player)
                return (xCount == oCount) ? "first" : "second";
            }
        } else if (xWon && !oWon) {
            // Only X won
            // X must have made the last move, so xCount > oCount
            return (xCount > oCount) ? "the first player won" : "illegal";
        } else if (!xWon && oWon) {
            // Only O won
            // O must have made the last move, so xCount == oCount
            return (xCount == oCount) ? "the second player won" : "illegal";
        } else {
            // Both players have winning lines (Impossible in a valid game)
            return "illegal";
        }
    }

    /**
     * Checks if a specific player has won on the board.
     * Uses the sum of values in lines to detect wins.
     */
    private static boolean checkWinner(int[][] board, int playerValue, int winSum) {
        int n = BOARD_SIZE;

        // Check Rows
        for (int i = 0; i < n; i++) {
            int sum = 0;
            for (int j = 0; j < n; j++) {
                sum += board[i][j];
            }
            if (sum == winSum) return true;
        }

        // Check Columns
        for (int j = 0; j < n; j++) {
            int sum = 0;
            for (int i = 0; i < n; i++) {
                sum += board[i][j];
            }
            if (sum == winSum) return true;
        }

        // Check Diagonals
        int diag1 = board[0][0] + board[1][1] + board[2][2];
        int diag2 = board[0][2] + board[1][1] + board[2][0];

        if (diag1 == winSum || diag2 == winSum) return true;

        return false;
    }
}

import java.io.BufferedReader;
