public class TicTacToe {
    // Configuration constants
    private static final int GRID_SIZE = 3;
    private static final char PLAYER_X = 'X';
    private static final char PLAYER_O = 'O'; // Corrected from '0' (zero) to 'O' (letter O)

    public static void main(String[] args) throws IOException {
        // try-with-resources ensures the reader is closed automatically
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(System.in))) {
            char[][] board = parseBoard(reader);
            System.out.println(evaluateGameState(board));
        }
    }

    /**
     * Reads the 3x3 board configuration from standard input.
     */
    private static char[][] parseBoard(BufferedReader reader) throws IOException {
        char[][] board = new char[GRID_SIZE][GRID_SIZE];
        for (int i = 0; i < GRID_SIZE; i++) {
            String line = reader.readLine();
            if (line == null || line.length() < GRID_SIZE) {
                throw new IllegalArgumentException("Invalid board input: line " + (i + 1) + " is incomplete.");
            }
            for (int j = 0; j < GRID_SIZE; j++) {
                board[i][j] = line.charAt(j);
            }
        }
        return board;
    }

    /**
     * Evaluates the current board state according to standard Tic-Tac-Toe rules.
     */
    private static String evaluateGameState(char[][] board) {
        int xCount = countPlayers(board, PLAYER_X);
        int oCount = countPlayers(board, PLAYER_O);

        // Rule 1: Validate move counts (X goes first, so xCount must equal oCount or oCount + 1)
        if (Math.abs(xCount - oCount) > 1 || oCount > xCount) {
            return "illegal";
        }

        boolean xWins = hasWon(board, PLAYER_X);
        boolean oWins = hasWon(board, PLAYER_O);

        // Rule 2: Both players cannot win simultaneously
        if (xWins && oWins) {
            return "illegal";
        }

        // Rule 3: A winner must have made the correct number of moves
        if (xWins && xCount != oCount + 1) {
            return "illegal";
        }
        if (oWins && xCount != oCount) {
            return "illegal";
        }

        // Rule 4: Determine final game state
        int emptyCount = GRID_SIZE * GRID_SIZE - xCount - oCount;
        if (xWins) {
            return "the first player won";
        }
        if (oWins) {
            return "the second player won";
        }
        if (emptyCount == 0) {
            return "draw";
        }
        if (xCount == oCount) {
            return "first";
        }
        return "second";
    }

    /**
     * Counts occurrences of a specific player's symbol on the board.
     */
    private static int countPlayers(char[][] board, char player) {
        int count = 0;
        for (char[] row : board) {
            for (char cell : row) {
                if (cell == player) {
                    count++;
                }
            }
        }
        return count;
    }

    /**
     * Checks if a specific player has won the game.
     */
    private static boolean hasWon(char[][] board, char player) {
        // Check rows
        for (int i = 0; i < GRID_SIZE; i++) {
            if (board[i][0] == player && board[i][1] == player && board[i][2] == player) {
                return true;
            }
        }
        // Check columns
        for (int i = 0; i < GRID_SIZE; i++) {
            if (board[0][i] == player && board[1][i] == player && board[2][i] == player) {
                return true;
            }
        }
        // Check diagonals
        if (board[0][0] == player && board[1][1] == player && board[2][2] == player) {
            return true;
        }
        if (board[0][2] == player && board[1][1] == player && board[2][0] == player) {
            return true;
        }
        return false;
    }
}

