/**
 * Evaluates the state of a Tic-Tac-Toe game based on a 3x3 grid input.
 */
public class TicTacToeEvaluator {

    // Constants for board configuration and player symbols
    private static final int BOARD_SIZE = 3;
    private static final char PLAYER_X = 'X';
    private static final char PLAYER_0 = '0'; // Note: Using character '0' (zero) as per original logic

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        char[][] board = new char[BOARD_SIZE][BOARD_SIZE];

        // Read the 3x3 grid from input
        for (int i = 0; i < BOARD_SIZE; i++) {
            if (scanner.hasNext()) {
                String row = scanner.next();
                board[i] = row.toCharArray();
            }
        }
        scanner.close();

        // Analyze the board state
        int xCount = 0;
        int zeroCount = 0;

        // Count moves and check for wins
        for (int i = 0; i < BOARD_SIZE; i++) {
            for (int j = 0; j < BOARD_SIZE; j++) {
                if (board[i][j] == PLAYER_X) {
                    xCount++;
                } else if (board[i][j] == PLAYER_0) {
                    zeroCount++;
                }
            }
        }

        boolean xWon = checkWin(board, PLAYER_X);
        boolean zeroWon = checkWin(board, PLAYER_0);

        // Determine and print the game result
        String result = determineGameStatus(xCount, zeroCount, xWon, zeroWon);
        System.out.println(result);
    }

    /**
     * Checks if a specific player has won the game.
     */
    private static boolean checkWin(char[][] board, char player) {
        // Check rows
        for (int i = 0; i < BOARD_SIZE; i++) {
            if (board[i][0] == player && board[i][1] == player && board[i][2] == player) {
                return true;
            }
        }

        // Check columns
        for (int i = 0; i < BOARD_SIZE; i++) {
            if (board[0][i] == player && board[1][i] == player && board[2][i] == player) {
                return true;
            }
        }

        // Check main diagonal (top-left to bottom-right)
        if (board[0][0] == player && board[1][1] == player && board[2][2] == player) {
            return true;
        }

        // Check anti-diagonal (top-right to bottom-left)
        if (board[0][2] == player && board[1][1] == player && board[2][0] == player) {
            return true;
        }

        return false;
    }

    /**
     * Determines the status of the game based on move counts and win conditions.
     */
    private static String determineGameStatus(int xCount, int zeroCount, boolean xWon, boolean zeroWon) {
        // 1. Check for Illegal States

        // Both players cannot win simultaneously
        if (xWon && zeroWon) return "illegal";

        // Player 0 (zero) cannot have moved more times than Player 1 (X)
        if (zeroCount > xCount) return "illegal";

        // Player 1 (X) cannot have moved more than 1 time more than Player 0
        if (xCount - zeroCount > 1) return "illegal";

        // If X won, X must have made the last move (X count = 0 count + 1). 
        // If counts are equal, it implies 0 moved after X won.
        if (xWon && xCount == zeroCount) return "illegal";

        // If 0 won, 0 must have made the last move (0 count = X count). 
        // If X count is higher, it implies X moved after 0 won.
        if (zeroWon && xCount == zeroCount + 1) return "illegal";

        // 2. Check for Draw
        // Board is full (9 moves) and no winner
        if (xCount + zeroCount == BOARD_SIZE * BOARD_SIZE && !xWon && !zeroWon) {
            return "draw";
        }

        // 3. Check for Wins
        if (xWon) return "the first player won";
        if (zeroWon) return "the second player won";

        // 4. Determine whose turn it is (if game is not over)
        // If counts are equal, it is X's turn (Player 1)
        if (xCount == zeroCount) return "first";

        // Otherwise, it is 0's turn (Player 2)
        return "second";
    }
}

