        {{2, 0}, {2, 1}, {2, 2}},
        // Columns
        {{0, 0}, {1, 0}, {2, 0}},
        {{0, 1}, {1, 1}, {2, 1}},
        {{0, 2}, {1, 2}, {2, 2}},
        // Diagonals
        {{0, 0}, {1, 1}, {2, 2}},
        {{0, 2}, {1, 1}, {2, 0}}
    };

    private final char[][] board;

    /**
     * Constructs a TicTacToe3C instance with the given board state.
     */
    public TicTacToe3C(char[][] board) {
        this.board = board;
    }

    public static void main(String[] args) throws IOException {
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            String[] inputLines = new String[BOARD_SIZE];
            for (int i = 0; i < BOARD_SIZE; i++) {
                String line = br.readLine();
                if (line == null || line.length() < BOARD_SIZE) {
                    System.out.print("illegal");
                    return;
                }
                inputLines[i] = line;
            }

            char[][] parsedBoard = parseBoard(inputLines);
            TicTacToe3C game = new TicTacToe3C(parsedBoard);
            System.out.print(game.validateAndDetermineState());
        }
    }

    /**
     * Parses raw input lines into a 2D character board.
     */
    private char[][] parseBoard(String[] lines) {
        char[][] board = new char[BOARD_SIZE][BOARD_SIZE];
        for (int r = 0; r < BOARD_SIZE; r++) {
            for (int c = 0; c < BOARD_SIZE; c++) {
                char ch = lines[r].charAt(c);
                // Assumes valid input per problem specification
                board[r][c] = ch;
            }
        }
        return board;
    }

    /**
     * Orchestrates validation and state determination following SRP.
     */
    private String validateAndDetermineState() {
        int[] counts = countPieces();
        int xCount = counts[0];
        int oCount = counts[1];

        // Rule 1: Validate turn counts
        if (oCount > xCount || xCount > oCount + 1) {
            return "illegal";
        }

        boolean xWon = hasWon(PLAYER_X);
        boolean oWon = hasWon(PLAYER_O);

        // Rule 2: Both players cannot win simultaneously
        if (xWon && oWon) {
            return "illegal";
        }

        // Rule 3: Winning player must have made the correct number of moves
        if (xWon) {
            return xCount == oCount + 1 ? "the first player won" : "illegal";
        }
        if (oWon) {
            return xCount == oCount ? "the second player won" : "illegal";
        }

        // Rule 4: Draw condition
        if (xCount + oCount == BOARD_SIZE * BOARD_SIZE) {
            return "draw";
        }

        // Rule 5: Determine whose turn it is
        if (xCount == oCount) {
            return "first";
        }
        if (xCount == oCount + 1) {
            return "second";
        }

        return "-1"; // Fallback for unhandled edge cases
    }

    /**
     * Counts the number of X and O pieces on the board.
     */
    private int[] countPieces() {
        int xCount = 0;
        int oCount = 0;
        for (int r = 0; r < BOARD_SIZE; r++) {
            for (int c = 0; c < BOARD_SIZE; c++) {
                if (board[r][c] == PLAYER_X) xCount++;
                else if (board[r][c] == PLAYER_O) oCount++;
            }
        }
        return new int[]{xCount, oCount};
    }

    /**
     * Checks if the specified player has won using predefined winning lines.
     */
    private boolean hasWon(char player) {
        for (int[] line : WINNING_LINES) {
            if (board[line[0][0]][line[0][1]] == player &&
                board[line[1][0]][line[1][1]] == player &&
                board[line[2][0]][line[2][1]] == player) {
                return true;
            }
        }
        return false;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;

public class TicTacToe {
    // Constants for readability and maintainability
    private static final char EMPTY = '.';
    private static final char PLAYER_X = 'X';
    private static final char PLAYER_O = 'O'; // Corrected from '0' (zero) to 'O' (letter)
    private static final String FIRST_PLAYER_WON = "the first player won";
    private static final String SECOND_PLAYER_WON = "the second player won";

    private final char[][] board;

    public TicTacToe(char[][] board) {
        this.board = board;
    }

    /**
     * Evaluates the current board state and returns the appropriate result string.
     */
    public String evaluate() {
        if (!isValidState()) {
            return "illegal";
        }

        int xCount = countPlayer(PLAYER_X);
        int oCount = countPlayer(PLAYER_O);

        if (hasWon(PLAYER_X)) {
            return FIRST_PLAYER_WON;
        }
        if (hasWon(PLAYER_O)) {
            return SECOND_PLAYER_WON;
        }
        if (xCount + oCount == 9) {
            return "draw";
        }

        return (xCount == oCount) ? "first" : "second";
    }

    private int countPlayer(char player) {
        int count = 0;
        for (char[] row : board) {
            for (char cell : row) {
                if (cell == player) {
                    count++;
                }
            }
        }
        return count;
    }

    private boolean hasWon(char player) {
        // Check rows
        for (int i = 0; i < 3; i++) {
            if (board[i][0] == player && board[i][1] == player && board[i][2] == player) {
                return true;
            }
        }
        // Check columns
        for (int j = 0; j < 3; j++) {
            if (board[0][j] == player && board[1][j] == player && board[2][j] == player) {
                return true;
            }
        }
        // Check diagonals
        if (board[0][0] == player && board[1][1] == player && board[2][2] == player) {
            return true;
        }
        if (board[0][2] == player && board[1][1] == player && board[2][0] == player) {
            return true;
        }
        return false;
    }

    private boolean isValidState() {
        int xCount = countPlayer(PLAYER_X);
        int oCount = countPlayer(PLAYER_O);

        // Rule 1: O cannot have more moves than X, and X can have at most one more move than O
        if (oCount > xCount || xCount > oCount + 1) {
            return false;
        }

        boolean xWins = hasWon(PLAYER_X);
        boolean oWins = hasWon(PLAYER_O);

        // Rule 2: Both players cannot win simultaneously
        if (xWins && oWins) {
            return false;
        }

        // Rule 3: If X wins, X must have made the last move (xCount == oCount + 1)
        if (xWins && xCount == oCount) {
            return false;
        }

        // Rule 4: If O wins, the move counts must be equal (xCount == oCount)
        if (oWins && xCount > oCount) {
            return false;
        }

        return true;
    }

    public static void main(String[] args) throws IOException {
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(System.in))) {
            char[][] board = new char[3][3];
            for (int i = 0; i < 3; i++) {
                String line = reader.readLine();
                if (line == null || line.length() < 3) {
                    System.out.println("illegal");
                    return;
                }
                board[i] = line.substring(0, 3).toCharArray();
            }

            TicTacToe game = new TicTacToe(board);
            System.out.println(game.evaluate());
        }
    }
}

