/**
 * Solves the Tic-Tac-Toe board validation and game state determination problem.
 */
class TicTacToeSolver {
    private static final int BOARD_SIZE = 3;
    private static final char PLAYER_X = 'X';
    private static final char PLAYER_O = '0'; // Note: Uses '0' (zero) as per original specification

    // Output constants
    private static final String ILLEGAL = "illegal";
    private static final String FIRST_PLAYER_WON = "the first player won";
    private static final String SECOND_PLAYER_WON = "the second player won";
    private static final String DRAW = "draw";
    private static final String FIRST_TURN = "first";
    private static final String SECOND_TURN = "second";

    /**
     * Reads the board, validates turn counts, checks win conditions,
     * and prints the resulting game state.
     */
    public void solve(InputReader in, PrintWriter out) {
        char[][] board = new char[BOARD_SIZE][BOARD_SIZE];
        int countX = 0;
        int countO = 0;

        // Read board and count player moves
        for (int i = 0; i < BOARD_SIZE; i++) {
            String row = in.next();
            board[i] = row.toCharArray();
            for (char c : board[i]) {
                if (c == PLAYER_X) countX++;
                else if (c == PLAYER_O) countO++;
            }
        }

        // Validate turn sequence: X always starts, so counts must satisfy x == o or x == o + 1
        if (countX != countO && countX != countO + 1) {
            out.println(ILLEGAL);
            return;
        }

        boolean xWins = checkWin(board, PLAYER_X);
        boolean oWins = checkWin(board, PLAYER_O);

        out.println(determineGameState(countX, countO, xWins, oWins));
    }

    /**
     * Determines the game state based on move counts and win flags.
     */
    private String determineGameState(int countX, int countO, boolean xWins, boolean oWins) {
        if (xWins && oWins) return ILLEGAL;
        if (xWins) return countX == countO + 1 ? FIRST_PLAYER_WON : ILLEGAL;
        if (oWins) return countX == countO ? SECOND_PLAYER_WON : ILLEGAL;
        if (countX + countO == BOARD_SIZE * BOARD_SIZE) return DRAW;
        if (countX == countO) return FIRST_TURN;
        return SECOND_TURN;
    }

    /**
     * Checks if the specified player has achieved a winning line.
     */
    private boolean checkWin(char[][] board, char player) {
        // Check diagonals
        if (board[0][0] == player && board[1][1] == player && board[2][2] == player) return true;
        if (board[0][2] == player && board[1][1] == player && board[2][0] == player) return true;

        // Check rows and columns
        for (int i = 0; i < BOARD_SIZE; i++) {
            if (board[i][0] == player && board[i][1] == player && board[i][2] == player) return true;
            if (board[0][i] == player && board[1][i] == player && board[2][i] == player) return true;
        }
        return false;
    }
}

/**
 * Fast I/O helper for competitive programming environments.
 */
class InputReader {
