    /**
     * Reads the 3x3 board configuration from standard input.
     */
    private static char[][] readBoard(Scanner scanner) {
        char[][] board = new char[BOARD_SIZE][BOARD_SIZE];
        for (int i = 0; i < BOARD_SIZE; i++) {
            if (scanner.hasNextLine()) {
                String line = scanner.nextLine();
                // Safely populate the board row, handling potential short lines
                for (int j = 0; j < BOARD_SIZE && j < line.length(); j++) {
                    board[i][j] = line.charAt(j);
                }
            }
        }
        return board;
    }

    /**
     * Analyzes the board state and determines the game result.
     */
    private static String evaluateGame(char[][] board) {
        int countX = 0;
        int countO = 0;

        // Count the number of X's and O's
        for (int i = 0; i < BOARD_SIZE; i++) {
            for (int j = 0; j < BOARD_SIZE; j++) {
                char cell = board[i][j];
                if (cell == PLAYER_X) {
                    countX++;
                } else if (cell == PLAYER_O) {
                    countO++;
                }
            }
        }

        // Rule 1: Validate move counts
        // X goes first, so countX must be equal to countO or countO + 1.
        if (countX < countO || countX > countO + 1) {
            return "illegal";
        }

        boolean xWon = checkWin(board, PLAYER_X);
        boolean oWon = checkWin(board, PLAYER_O);

        // Rule 2: Check for X winning
        if (xWon) {
            // If X won, X must have made the last move, so countX should be countO + 1.
            // If counts are equal, X played twice in a row.
            if (countX == countO) {
                return "illegal";
            }
            return "the first player won";
        }

        // Rule 3: Check for O winning
        if (oWon) {
            // If O won, O must have made the last move, so countX should equal countO.
            // If countX > countO, X played after O won.
            if (countX > countO) {
                return "illegal";
            }
            return "the second player won";
        }

        // Rule 4: Check for Draw
        if (countX + countO == BOARD_SIZE * BOARD_SIZE) {
            return "draw";
        }

        // Rule 5: Determine whose turn it is
        if (countX == countO) {
            return "first";
        } else {
            return "second";
        }
    }

    /**
     * Checks if the specified player has won the game.
     */
    private static boolean checkWin(char[][] board, char player) {
        // Check rows
        for (int i = 0; i < BOARD_SIZE; i++) {
            if (board[i][0] == player && board[i][1] == player && board[i][2] == player) {
                return true;
            }
        }

        // Check columns
        for (int i = 0; i < BOARD_SIZE; i++) {
            if (board[0][i] == player && board[1][i] == player && board[2][i] == player) {
                return true;
            }
        }

        // Check diagonals
        if (board[0][0] == player && board[1][1] == player && board[2][2] == player) {
            return true;
        }
        if (board[0][2] == player && board[1][1] == player && board[2][0] == player) {
            return true;
        }

        return false;
    }
