    private static final String RESULT_SECOND_PLAYER_WON = "the second player won";
    private static final String RESULT_DRAW = "draw";
    private static final String RESULT_FIRST_TURN = "first";
    private static final String RESULT_SECOND_TURN = "second";

    // Game constants
    private static final char PLAYER_X = 'X';
    private static final char PLAYER_O = '0'; // Note: Input uses '0' (zero)
    private static final int BOARD_SIZE = 3;

    public static void main(String[] args) throws IOException
    {
        // Use try-with-resources to ensure the reader is closed automatically
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(System.in)))
        {
            char[][] board = new char[BOARD_SIZE][BOARD_SIZE];
            int xCount = 0;
            int oCount = 0;

            // 1. Read Input and Count Moves
            for (int i = 0; i < BOARD_SIZE; i++)
            {
                String line = reader.readLine();
                if (line == null) break;

                // Trim to handle potential leading/trailing whitespace
                line = line.trim();

                for (int j = 0; j < BOARD_SIZE; j++)
                {
                    // Safety check to avoid IndexOutOfBounds if input line is short
                    if (j < line.length())
                    {
                        char c = line.charAt(j);
                        board[i][j] = c;
                        if (c == PLAYER_X)
                        {
                            xCount++;
                        }
                        else if (c == PLAYER_O)
                        {
                            oCount++;
                        }
                    }
                }
            }

            // 2. Validate Move Counts
            // X (first player) must have equal or one more move than O (second player)
            if (xCount < oCount || xCount > oCount + 1)
            {
                System.out.println(RESULT_ILLEGAL);
                return;
            }

            // 3. Check for Winning Conditions
            boolean xWins = hasWon(board, PLAYER_X);
            boolean oWins = hasWon(board, PLAYER_O);

            // 4. Determine Game State and Output
            if (xWins && oWins)
            {
                // Both players cannot win in a valid game
                System.out.println(RESULT_ILLEGAL);
            }
            else if (xWins)
            {
                // X wins, so X must have made the last move (count must be oCount + 1)
                if (xCount == oCount + 1)
                {
                    System.out.println(RESULT_FIRST_PLAYER_WON);
                }
                else
                {
                    System.out.println(RESULT_ILLEGAL);
                }
            }
            else if (oWins)
            {
                // O wins, so O must have made the last move (counts must be equal)
                if (xCount == oCount)
                {
                    System.out.println(RESULT_SECOND_PLAYER_WON);
                }
                else
                {
                    System.out.println(RESULT_ILLEGAL);
                }
            }
            else
            {
                // No winner
                if (xCount + oCount == BOARD_SIZE * BOARD_SIZE)
                {
                    System.out.println(RESULT_DRAW);
                }
                else
                {
                    // Game ongoing, whose turn is it?
                    if (xCount == oCount)
                    {
                        System.out.println(RESULT_FIRST_TURN);
                    }
                    else
                    {
                        System.out.println(RESULT_SECOND_TURN);
                    }
                }
            }
        }
    }

    /**
     * Checks if the specified player has won the game by checking rows, columns, and diagonals.
     */
    private static boolean hasWon(char[][] board, char player)
    {
        // Check Rows
        for (int i = 0; i < BOARD_SIZE; i++)
        {
            if (board[i][0] == player && board[i][1] == player && board[i][2] == player)
            {
                return true;
            }
        }

        // Check Columns
        for (int j = 0; j < BOARD_SIZE; j++)
        {
            if (board[0][j] == player && board[1][j] == player && board[2][j] == player)
            {
                return true;
            }
        }

        // Check Diagonals
        if (board[0][0] == player && board[1][1] == player && board[2][2] == player)
        {
