import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

public class Main {

    private static final int BOARD_SIZE = 3;
    private static final char PLAYER_X = 'X';
    private static final char PLAYER_O = '0'; // Uses '0' (zero) per original specification
    private static final char EMPTY_CELL = '.';

    public static void main(String[] args) {
        InputReader reader = new InputReader(System.in);
        char[][] board = readBoard(reader);
        String result = analyzeBoardState(board);
        System.out.println(result);
    }

    /**
     * Reads the 3x3 board from standard input.
     */
    private static char[][] readBoard(InputReader reader) {
        char[][] board = new char[BOARD_SIZE][BOARD_SIZE];
        for (int i = 0; i < BOARD_SIZE; i++) {
            String line = reader.next();
            if (line == null || line.length() < BOARD_SIZE) {
                throw new IllegalArgumentException("Invalid board input at row " + i);
            }
            for (int j = 0; j < BOARD_SIZE; j++) {
                board[i][j] = line.charAt(j);
            }
        }
        return board;
    }

    /**
     * Analyzes the board state and returns the corresponding game result string.
     */
    private static String analyzeBoardState(char[][] board) {
        int xCount = countPlayer(board, PLAYER_X);
        int oCount = countPlayer(board, PLAYER_O);

        // 1. Validate basic move count rules
        if (!isValidMoveCount(xCount, oCount)) {
            return "illegal";
        }

        // 2. Check win conditions
        if (hasWon(board, PLAYER_X)) {
            if (xCount == oCount) return "illegal"; // X cannot win if O has made the same number of moves
            return "the first player won";
        }

        if (hasWon(board, PLAYER_O)) {
            if (xCount > oCount) return "illegal"; // O cannot win if X has made more moves
            return "the second player won";
        }

        // 3. Check for draw or next player
        if (xCount + oCount == BOARD_SIZE * BOARD_SIZE) {
            return "draw";
        }
        return xCount == oCount ? "first" : "second";
    }

    private static int countPlayer(char[][] board, char player) {
        int count = 0;
        for (char[] row : board) {
            for (char cell : row) {
                if (cell == player) {
                    count++;
                }
            }
        }
        return count;
    }

    private static boolean isValidMoveCount(int xCount, int oCount) {
        return xCount == oCount || xCount == oCount + 1;
    }

    private static boolean hasWon(char[][] board, char player) {
        // Check all rows and columns
        for (int i = 0; i < BOARD_SIZE; i++) {
            if (isRowWon(board, i, player) || isColumnWon(board, i, player)) {
                return true;
            }
        }
        // Check diagonals
        return isMainDiagonalWon(board, player) || isAntiDiagonalWon(board, player);
    }

    private static boolean isRowWon(char[][] board, int row, char player) {
        return board[row][0] == player && board[row][1] == player && board[row][2] == player;
    }

    private static boolean isColumnWon(char[][] board, int col, char player) {
        return board[0][col] == player && board[1][col] == player && board[2][col] == player;
    }

    private static boolean isMainDiagonalWon(char[][] board, char player) {
        return board[0][0] == player && board[1][1] == player && board[2][2] == player;
    }

    private static boolean isAntiDiagonalWon(char[][] board, char player) {
        return board[2][0] == player && board[1][1] == player && board[0][2] == player;
    }

    /**
     * Fast input reader for competitive programming / performance-critical environments.
     */
    private static class InputReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public InputReader(InputStream stream) {
            this.reader = new BufferedReader(new InputStreamReader(stream), 32768);
            this.tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input stream", e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

