    @Override
    public void run() {
        try {
            in = new BufferedReader(new InputStreamReader(System.in));
            pw = new PrintWriter(System.out);
            st = new StringTokenizer("");

            solve();
        } catch (IOException e) {
            e.printStackTrace();
            System.exit(1);
        } finally {
            pw.flush();
            pw.close();
        }
    }

    private void solve() throws IOException {
        char[][] board = new char[BOARD_SIZE][];
        for (int i = 0; i < BOARD_SIZE; i++) {
            board[i] = next().toCharArray();
        }
        pw.println(evaluateBoard(board));
    }

    /**
     * Evaluates the current state of a Tic-Tac-Toe board.
     * Returns: "illegal", "the first player won", "the second player won",
     *          "draw", "first", or "second".
     */
    private String evaluateBoard(char[][] board) {
        int xCount = 0;
        int oCount = 0;

        // Count player marks
        for (int i = 0; i < BOARD_SIZE; i++) {
            for (int j = 0; j < BOARD_SIZE; j++) {
                if (board[i][j] == PLAYER_X) {
                    xCount++;
                } else if (board[i][j] == PLAYER_O) {
                    oCount++;
                }
            }
        }

        // Validate turn counts: X always goes first, so xCount == oCount or xCount == oCount + 1
        if (oCount > xCount || xCount > oCount + 1) {
            return "illegal";
        }

        int xWins = countWinningLines(board, PLAYER_X);
        int oWins = countWinningLines(board, PLAYER_O);

        // Both players cannot win simultaneously
        if (xWins > 0 && oWins > 0) {
            return "illegal";
        }

        // Check win conditions against turn counts
        if (xWins > 0) {
            return (xCount == oCount + 1) ? "the first player won" : "illegal";
        }

        if (oWins > 0) {
            return (xCount == oCount) ? "the second player won" : "illegal";
        }

        // No winner: check for draw or next turn
        if (xCount + oCount == TOTAL_CELLS) {
            return "draw";
        }

        return (xCount == oCount) ? "first" : "second";
    }

    /**
     * Counts the number of winning lines for a specific player.
     */
    private int countWinningLines(char[][] board, char player) {
        int wins = 0;

        // Check rows
        for (int i = 0; i < BOARD_SIZE; i++) {
            if (isLineWinning(board, i, 0, 0, 1, player)) {
                wins++;
            }
        }

        // Check columns
        for (int j = 0; j < BOARD_SIZE; j++) {
            if (isLineWinning(board, 0, j, 1, 0, player)) {
                wins++;
            }
        }

        // Check main diagonal
        if (isLineWinning(board, 0, 0, 1, 1, player)) {
            wins++;
        }

        // Check anti-diagonal
        if (isLineWinning(board, 0, BOARD_SIZE - 1, 1, -1, player)) {
            wins++;
        }

        return wins;
    }

    /**
     * Checks if a line starting at (r, c) with direction (dr, dc) is a win for the given player.
     */
    private boolean isLineWinning(char[][] board, int r, int c, int dr, int dc, char player) {
        if (board[r][c] != player) {
            return false;
        }
        for (int k = 1; k < BOARD_SIZE; k++) {
            if (board[r + k * dr][c + k * dc] != player) {
                return false;
            }
        }
        return true;
    }

    // --- Fast I/O Utilities ---

    private String next() throws IOException {
        while (!st.hasMoreTokens()) {
            String line = in.readLine();
            if (line == null) {
                return null;
            }
            st = new StringTokenizer(line);
        }
        return st.nextToken();
    }

    // Note: Unused parsing methods (nextInt, nextLong, etc.) were removed to reduce bloat.
    // They can be safely added back if future requirements demand them.
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

/**
 * Refactored Solution for Tic-Tac-Toe state analysis.
 * 
 * Improvements made:
 * 1. Separation of Concerns: Logic is separated into distinct methods (solve, findWinner).
 * 2. Readability: Variable names are descriptive (e.g., 'board' instead of 'm', 'xCount' instead of 'x').
 * 3. Constants: Magic numbers (3) and strings are replaced with named constants.
 * 4. Robustness: Input handling is encapsulated in a FastScanner class with null checks.
 * 5. Logic Clarity: The winner detection logic ('vig') is rewritten to be more readable and less error-prone.
 */
public class Solution implements Runnable {

    // Constants for output messages to ensure consistency
    private static final String MSG_ILLEGAL = "illegal";
    private static final String MSG_DRAW = "draw";
    private static final String MSG_FIRST_PLAYER_WON = "the first player won";
    private static final String MSG_SECOND_PLAYER_WON = "the second player won";
    private static final String MSG_FIRST_TURN = "first";
    private static final String MSG_SECOND_TURN = "second";

    // Board configuration constants
    private static final int BOARD_SIZE = 3;
    private static final char EMPTY_CELL = '.';
    private static final char PLAYER_X = 'X';
    private static final char PLAYER_O = '0'; // Note: The original code uses '0' (zero)

    private FastScanner in;
    private PrintWriter out;

    public static void main(String[] args) {
        // Keeping the thread execution pattern from the original code
        new Thread(new Solution()).start();
    }

    @Override
    public void run() {
        try {
            in = new FastScanner();
            out = new PrintWriter(System.out);
            solve();
        } catch (IOException e) {
            e.printStackTrace();
        } finally {
            out.flush();
            out.close();
        }
    }

    private void solve() throws IOException {
        char[][] board = new char[BOARD_SIZE][BOARD_SIZE];
        int xCount = 0;
        int oCount = 0;

        // 1. Read the board and count moves
        for (int i = 0; i < BOARD_SIZE; i++) {
            String row = in.next();
            if (row == null) break; // Safety check for EOF
            for (int j = 0; j < BOARD_SIZE; j++) {
                board[i][j] = row.charAt(j);
                if (board[i][j] == PLAYER_X) {
                    xCount++;
                } else if (board[i][j] == PLAYER_O) {
                    oCount++;
                }
            }
        }

        // 2. Validate move counts
        // In a valid game, X (first player) goes first.
        // Therefore, xCount must be equal to oCount (O's turn) or xCount == oCount + 1 (X's turn).
        if (xCount != oCount && xCount != oCount + 1) {
            out.print(MSG_ILLEGAL);
            return;
        }

        // 3. Check for a winner
        char winner = findWinner(board);

        if (winner == EMPTY_CELL) {
            // No winner yet
            if (xCount + oCount == BOARD_SIZE * BOARD_SIZE) {
                out.print(MSG_DRAW);
            } else {
                // Determine whose turn it is based on move counts
                if (xCount == oCount) {
                    out.print(MSG_FIRST_TURN);
                } else {
                    out.print(MSG_SECOND_TURN);
                }
            }
        } else {
            // A winner exists
            if (winner == PLAYER_X) {
                // X wins only if X made the last move (xCount == oCount + 1)
                if (xCount == oCount + 1) {
                    out.print(MSG_FIRST_PLAYER_WON);
                } else {
                    out.print(MSG_ILLEGAL);
                }
            } else if (winner == PLAYER_O) {
                // O wins only if O made the last move (xCount == oCount)
                if (xCount == oCount) {
                    out.print(MSG_SECOND_PLAYER_WON);
                } else {
                    out.print(MSG_ILLEGAL);
                }
            } else {
                out.print(MSG_ILLEGAL);
            }
        }
    }

    /**
     * Checks the board for a winning line (row, column, or diagonal).
     * Returns the winning character ('X' or '0') or '.' if no winner.
     */
    private char findWinner(char[][] board) {
        // Check rows
        for (int i = 0; i < BOARD_SIZE; i++) {
            if (board[i][0] != EMPTY_CELL && 
                board[i][0] == board[i][1] && 
                board[i][1] == board[i][2]) {
                return board[i][0];
            }
        }

        // Check columns
        for (int i = 0; i < BOARD_SIZE; i++) {
            if (board[0][i] != EMPTY_CELL && 
                board[0][i] == board[1][i] && 
                board[1][i] == board[2][i]) {
                return board[0][i];
            }
        }

        // Check main diagonal (top-left to bottom-right)
        if (board[0][0] != EMPTY_CELL && 
            board[0][0] == board[1][1] && 
            board[1][1] == board[2][2]) {
            return board[0][0];
        }

        // Check anti-diagonal (top-right to bottom-left)
        if (board[0][2] != EMPTY_CELL && 
            board[0][2] == board[1][1] && 
            board[1][1] == board[2][0]) {
            return board[0][2];
        }

        return EMPTY_CELL;
    }

    /**
     * Helper class for fast input reading.
     */
    static class FastScanner {
        BufferedReader br;
        StringTokenizer st;

        public FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) {
                    return null;
                }
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;

public class TicTacToeValidator {

    private static final char PLAYER_X = 'X';
    private static final char PLAYER_O = 'O'; // Fixed typo: original used digit '0' instead of letter 'O'
    private static final char EMPTY = '.';
    private static final int BOARD_SIZE = 3;
    private static final int TOTAL_CELLS = BOARD_SIZE * BOARD_SIZE;

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        char[] board = readBoard(br);
        Result result = analyzeBoard(board);
        System.out.println(result.getMessage());
    }

    /**
     * Reads exactly 3 lines from input, strips whitespace, and validates length.
     */
    private static char[] readBoard(BufferedReader br) throws IOException {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < BOARD_SIZE; i++) {
            String line = br.readLine();
            if (line != null) {
                sb.append(line.trim());
            }
        }
        if (sb.length() != TOTAL_CELLS) {
            throw new IllegalArgumentException("Invalid board input. Expected exactly 9 characters.");
        }
        return sb.toString().toCharArray();
    }

    /**
     * Counts moves, checks win conditions, validates game rules, and determines the final state.
     */
    private static Result analyzeBoard(char[] board) {
        int countX = 0;
        int countO = 0;
        int emptyCount = 0;

        for (char cell : board) {
            switch (cell) {
                case PLAYER_X: countX++; break;
                case PLAYER_O: countO++; break;
                case EMPTY: emptyCount++; break;
                default: throw new IllegalArgumentException("Invalid character in board: " + cell);
            }
        }

        boolean xWins = checkWin(board, PLAYER_X);
        boolean oWins = checkWin(board, PLAYER_O);

        // Validate move counts against Tic-Tac-Toe rules
        if (countX < countO || countX - countO > 1) {
            return Result.ILLEGAL;
        }
        // Both players cannot win simultaneously
        if (xWins && oWins) {
            return Result.ILLEGAL;
        }
        // X wins, but O made an extra move
        if (xWins && countX == countO) {
            return Result.ILLEGAL;
        }
        // O wins, but X made an extra move
        if (oWins && countX > countO) {
            return Result.ILLEGAL;
        }

        // Determine game state based on validated rules
        if (xWins) return Result.FIRST_PLAYER_WON;
        if (oWins) return Result.SECOND_PLAYER_WON;
        if (emptyCount == 0) return Result.DRAW;
        if (countX == countO) return Result.FIRST_PLAYER_NEXT;
        return Result.SECOND_PLAYER_NEXT;
    }

    /**
     * Checks if a specific player has won by completing a row, column, or diagonal.
     */
    private static boolean checkWin(char[] board, char player) {
        // Check rows
        for (int i = 0; i < BOARD_SIZE; i++) {
            int base = i * BOARD_SIZE;
            if (board[base] == player && board[base + 1] == player && board[base + 2] == player) {
                return true;
            }
        }
        // Check columns
        for (int i = 0; i < BOARD_SIZE; i++) {
            if (board[i] == player && board[i + BOARD_SIZE] == player && board[i + BOARD_SIZE * 2] == player) {
                return true;
            }
        }
        // Check diagonals
        if (board[0] == player && board[4] == player && board[8] == player) return true;
        if (board[2] == player && board[4] == player && board[6] == player) return true;

        return false;
    }

    /**
     * Enumerates all possible valid game states with their corresponding output messages.
     */
    public enum Result {
        ILLEGAL("illegal"),
        FIRST_PLAYER_WON("the first player won"),
        SECOND_PLAYER_WON("the second player won"),
        DRAW("draw"),
        FIRST_PLAYER_NEXT("first"),
        SECOND_PLAYER_NEXT("second");

        private final String message;

        Result(String message) {
            this.message = message;
        }

        public String getMessage() {
            return message;
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;

public class TicTacToeValidator {
    private static final int BOARD_SIZE = 3;

    public static void main(String[] args) {
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(System.in))) {
            char[][] board = new char[BOARD_SIZE][BOARD_SIZE];
            int xCount = 0;
            int oCount = 0;

            // 1. Read and parse the board input
            for (int i = 0; i < BOARD_SIZE; i++) {
                String line = reader.readLine();
                if (line == null) {
                    System.out.println("illegal");
                    return;
                }
                // Normalize input: remove spaces to handle both "X X O" and "XXO" formats
                String cleanedLine = line.trim().replaceAll("\\s+", "");
                if (cleanedLine.length() < BOARD_SIZE) {
                    System.out.println("illegal");
                    return;
                }
                for (int j = 0; j < BOARD_SIZE; j++) {
                    char cell = cleanedLine.charAt(j);
                    board[i][j] = cell;
                    if (cell == 'X') xCount++;
                    else if (cell == 'O') oCount++;
                }
            }

            // 2. Validate game state and determine result
            ValidationResult result = validateGame(board, xCount, oCount);
            System.out.println(result.getMessage());

        } catch (IOException e) {
            System.err.println("Error reading input: " + e.getMessage());
        }
    }

    /**
     * Validates the board state based on standard Tic-Tac-Toe rules.
     */
    private static ValidationResult validateGame(char[][] board, int xCount, int oCount) {
        // Rule 1: Validate move counts
        if (xCount + oCount > 9) return ValidationResult.illegal();
        if (oCount > xCount) return ValidationResult.illegal(); // O cannot have more moves than X
        if (xCount - oCount > 1) return ValidationResult.illegal(); // X cannot have more than one extra move

        // Rule 2: Check win conditions
        boolean xWins = hasWinningLine(board, 'X');
        boolean oWins = hasWinningLine(board, 'O');

        if (xWins && oWins) return ValidationResult.illegal(); // Both players cannot win simultaneously
        if (xWins && xCount == oCount) return ValidationResult.illegal(); // X just moved, so xCount must be oCount + 1
        if (oWins && xCount > oCount) return ValidationResult.illegal(); // O just moved, so counts must be equal

        if (xWins) return ValidationResult.firstPlayerWon();
        if (oWins) return ValidationResult.secondPlayerWon();

        // Rule 3: Draw or determine next turn
        if (xCount == 5 && oCount == 4) return ValidationResult.draw();
        if (xCount == oCount) return ValidationResult.firstPlayerTurn();
        return ValidationResult.secondPlayerTurn();
    }

    /**
     * Checks if the specified player has a winning line (row, column, or diagonal).
     * Note: Original code had row/column checks swapped; this method correctly checks rows first, then columns.
     */
    private static boolean hasWinningLine(char[][] board, char player) {
        // Check rows
        for (int i = 0; i < BOARD_SIZE; i++) {
            if (board[i][0] == player && board[i][1] == player && board[i][2] == player) {
                return true;
            }
        }
        // Check columns
        for (int j = 0; j < BOARD_SIZE; j++) {
            if (board[0][j] == player && board[1][j] == player && board[2][j] == player) {
                return true;
            }
        }
        // Check diagonals
        if (board[0][0] == player && board[1][1] == player && board[2][2] == player) return true;
        if (board[0][2] == player && board[1][1] == player && board[2][0] == player) return true;

        return false;
    }

    /**
     * Immutable value class to encapsulate validation results.
     * Replaces side-effect printing inside validation methods with explicit return values.
     */
    private static class ValidationResult {
        private final String message;

        private ValidationResult(String message) {
            this.message = message;
        }

        public String getMessage() {
            return message;
        }

        static ValidationResult illegal() { return new ValidationResult("illegal"); }
        static ValidationResult firstPlayerWon() { return new ValidationResult("the first player won"); }
        static ValidationResult secondPlayerWon() { return new ValidationResult("the second player won"); }
        static ValidationResult draw() { return new ValidationResult("draw"); }
        static ValidationResult firstPlayerTurn() { return new ValidationResult("first"); }
        static ValidationResult secondPlayerTurn() { return new ValidationResult("second"); }
    }
}

import java.util.Scanner;

public class Main {
    private static final int BOARD_SIZE = 3;
    private static final char EMPTY_CELL = '.';
    private static final char PLAYER_X = 'X';
    private static final char PLAYER_O = '0'; // Uses digit '0' to match original specification

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        while (scanner.hasNext()) {
            char[][] board = readBoard(scanner);
            if (board == null) {
                break;
            }
            evaluateGame(board);
        }
        scanner.close();
    }

    private static char[][] readBoard(Scanner scanner) {
        char[][] board = new char[BOARD_SIZE][BOARD_SIZE];
        for (int i = 0; i < BOARD_SIZE; i++) {
            if (!scanner.hasNext()) {
                return null;
            }
            String row = scanner.next();
            board[i] = row.toCharArray();
        }
        return board;
    }

    private static void evaluateGame(char[][] board) {
        int xCount = 0;
        int oCount = 0;
        int emptyCount = 0;

        // Count pieces and empty cells
        for (int i = 0; i < BOARD_SIZE; i++) {
            for (int j = 0; j < BOARD_SIZE; j++) {
                char cell = board[i][j];
                if (cell == PLAYER_X) {
                    xCount++;
                } else if (cell == PLAYER_O) {
                    oCount++;
                } else if (cell == EMPTY_CELL) {
                    emptyCount++;
                }
            }
        }

        boolean xWins = hasWon(board, PLAYER_X);
        boolean oWins = hasWon(board, PLAYER_O);

        if (isIllegalState(xCount, oCount, xWins, oWins)) {
            System.out.println("illegal");
        } else if (xWins) {
            System.out.println("the first player won");
        } else if (oWins) {
            System.out.println("the second player won");
        } else if (emptyCount == 0) {
            System.out.println("draw");
        } else if (xCount <= oCount) {
            System.out.println("first");
        } else {
            System.out.println("second");
        }
    }

    private static boolean hasWon(char[][] board, char player) {
        // Check rows
        for (int i = 0; i < BOARD_SIZE; i++) {
            if (allCellsMatch(board[i], player)) {
                return true;
            }
        }

        // Check columns
        for (int j = 0; j < BOARD_SIZE; j++) {
            boolean colMatch = true;
            for (int i = 0; i < BOARD_SIZE; i++) {
                if (board[i][j] != player) {
                    colMatch = false;
                    break;
                }
            }
            if (colMatch) return true;
        }

        // Check main diagonal
        boolean diag1Match = true;
        for (int i = 0; i < BOARD_SIZE; i++) {
            if (board[i][i] != player) {
                diag1Match = false;
                break;
            }
        }
        if (diag1Match) return true;

        // Check anti-diagonal
        boolean diag2Match = true;
        for (int i = 0; i < BOARD_SIZE; i++) {
            if (board[i][BOARD_SIZE - 1 - i] != player) {
                diag2Match = false;
                break;
            }
        }
        return diag2Match;
    }

    private static boolean allCellsMatch(char[] row, char player) {
        for (char cell : row) {
            if (cell != player) {
                return false;
            }
        }
        return true;
    }

    private static boolean isIllegalState(int xCount, int oCount, boolean xWins, boolean oWins) {
        // Turn count must be valid
        if (xCount < oCount || xCount > oCount + 1) {
            return true;
        }
        // Both players cannot win simultaneously
        if (xWins && oWins) {
            return true;
        }
        // X wins only if it played one more turn than O
        if (xWins && xCount != oCount + 1) {
            return true;
        }
        // O wins only if both players played the same number of turns
        if (oWins && xCount > oCount) {
            return true;
        }
        return false;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.OutputStream;
import java.io.PrintWriter;
import java.util.StringTokenizer;

public class Main {

    // Constants for board configuration to avoid magic numbers
    private static final int BOARD_SIZE = 3;
    private static final char PLAYER_X = 'X';
    private static final char PLAYER_O = '0'; // Note: Using '0' (zero) as per original logic

    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);

        TicTacToeSolver solver = new TicTacToeSolver();
        solver.solve(1, in, out);

        out.close();
    }

    /**
     * Handles the logic for validating and solving the Tic-Tac-Toe state.
     */
    static class TicTacToeSolver {

        public void solve(int testNumber, InputReader in, PrintWriter out) {
            char[][] board = new char[BOARD_SIZE][BOARD_SIZE];

            // Read the board from input
            for (int i = 0; i < BOARD_SIZE; i++) {
                String row = in.next();
                board[i] = row.toCharArray();
            }

            // Count moves for each player
            int countX = 0;
            int countO = 0;
            for (char[] row : board) {
                for (char cell : row) {
                    if (cell == PLAYER_X) {
                        countX++;
                    } else if (cell == PLAYER_O) {
                        countO++;
                    }
                }
            }

            // Check winning conditions
            boolean xWon = checkWin(board, PLAYER_X);
            boolean oWon = checkWin(board, PLAYER_O);

            // Validate the board state and print the result
            if (isIllegalState(countX, countO, xWon, oWon)) {
                out.println("illegal");
            } else {
                if (xWon) {
                    out.println("the first player won");
                } else if (oWon) {
                    out.println("the second player won");
                } else if (countX + countO == BOARD_SIZE * BOARD_SIZE) {
                    out.println("draw");
                } else if (countX == countO) {
                    out.println("first");
                } else {
                    out.println("second");
                }
            }
        }

        /**
         * Checks if the specified player has won the game.
         */
        private boolean checkWin(char[][] board, char player) {
            // Check rows
            for (int r = 0; r < BOARD_SIZE; r++) {
                if (board[r][0] == player && board[r][1] == player && board[r][2] == player) {
                    return true;
                }
            }

            // Check columns
            for (int c = 0; c < BOARD_SIZE; c++) {
                if (board[0][c] == player && board[1][c] == player && board[2][c] == player) {
                    return true;
                }
            }

            // Check main diagonal
            if (board[0][0] == player && board[1][1] == player && board[2][2] == player) {
                return true;
            }

            // Check anti-diagonal
            if (board[0][2] == player && board[1][1] == player && board[2][0] == player) {
                return true;
            }

            return false;
        }

        /**
         * Validates if the current board state is legal according to Tic-Tac-Toe rules.
         */
        private boolean isIllegalState(int countX, int countO, boolean xWon, boolean oWon) {
            // Rule 1: O cannot have made more moves than X
            if (countO > countX) {
                return true;
            }
            // Rule 2: X cannot have made more than 1 move than O
            if (countX - countO > 1) {
                return true;
            }
            // Rule 3: Both players cannot win simultaneously
            if (xWon && oWon) {
                return true;
            }
            // Rule 4: If O wins, counts must be equal (O moved last)
            if (oWon && countX > countO) {
                return true;
            }
            // Rule 5: If X wins, X must have exactly 1 more move than O (X moved last)
            if (xWon && countX == countO) {
                return true;
            }

            return false;
        }
    }

    /**
     * Helper class for fast input reading.
     */
    static class InputReader {
        public BufferedReader reader;
        public StringTokenizer tokenizer;

        public InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            String s = next();
            if (s == null) throw new RuntimeException("End of input");
            return Integer.parseInt(s);
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

public class CF3C {

    // Constants for clarity and maintainability
    private static final int BOARD_SIZE = 3;
    private static final char PLAYER_X = 'X';
    private static final char PLAYER_O = '0'; // Note: Problem uses '0' instead of 'O'
    private static final int TOTAL_CELLS = BOARD_SIZE * BOARD_SIZE;

    public static void main(String[] args) {
        // Use try-with-resources for proper resource management
        try (PrintWriter out = new PrintWriter(System.out)) {
            char[][] board = readBoard();
            out.println(evaluateGame(board));
            out.flush();
        }
    }

    private static char[][] readBoard() {
        char[][] board = new char[BOARD_SIZE][BOARD_SIZE];
        for (int i = 0; i < BOARD_SIZE; i++) {
            board[i] = IN.next().toCharArray();
        }
        return board;
    }

    /**
     * Evaluates the Tic-Tac-Toe board state according to standard rules:
     * 1. X always moves first, so count(X) must equal count(O) or count(X) = count(O) + 1.
     * 2. Both players cannot win simultaneously.
     * 3. If a player wins, their move count must satisfy the turn order rule.
     * 4. If no one wins, determine if it's a draw or whose turn it is.
     */
    private static String evaluateGame(char[][] board) {
        int[] counts = countMoves(board);
        int xCount = counts[0];
        int oCount = counts[1];

        // Rule 1: Validate move counts
        if (oCount > xCount || xCount > oCount + 1) {
            return "illegal";
        }

        boolean xWins = hasWon(board, PLAYER_X);
        boolean oWins = hasWon(board, PLAYER_O);

        // Rule 2: Both players cannot win simultaneously
        if (xWins && oWins) {
            return "illegal";
        }

        // Rule 3: Validate win conditions against move counts
        if (xWins) {
            return xCount == oCount + 1 ? "the first player won" : "illegal";
        }
        if (oWins) {
            return xCount == oCount ? "the second player won" : "illegal";
        }

        // Rule 4: No winner -> check for draw or next turn
        if (xCount + oCount == TOTAL_CELLS) {
            return "draw";
        }
        return xCount == oCount ? "first" : "second";
    }

    private static int[] countMoves(char[][] board) {
        int xCount = 0;
        int oCount = 0;
        for (char[] row : board) {
            for (char cell : row) {
                if (cell == PLAYER_X) xCount++;
                else if (cell == PLAYER_O) oCount++;
            }
        }
        return new int[]{xCount, oCount};
    }

    /**
     * Checks if the given player has a winning line (row, column, or diagonal).
     */
    private static boolean hasWon(char[][] board, char player) {
        // Check rows and columns
        for (int i = 0; i < BOARD_SIZE; i++) {
            boolean rowWin = true;
            boolean colWin = true;
            for (int j = 0; j < BOARD_SIZE; j++) {
                if (board[i][j] != player) rowWin = false;
                if (board[j][i] != player) colWin = false;
            }
            if (rowWin || colWin) return true;
        }

        // Check diagonals
        boolean diag1Win = true;
        boolean diag2Win = true;
        for (int i = 0; i < BOARD_SIZE; i++) {
            if (board[i][i] != player) diag1Win = false;
            if (board[i][BOARD_SIZE - 1 - i] != player) diag2Win = false;
        }
        return diag1Win || diag2Win;
    }

    // Fast I/O helper class (improved exception handling)
    static final class IN {
        private static final BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        private static StringTokenizer st = null;

        public static String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return st.nextToken();
        }

        public static int nextInt() {
            return Integer.parseInt(next());
        }

        public static long nextLong() {
            return Long.parseLong(next());
        }
    }
}

