/**
 * Refactored Tic-Tac-Toe Validator.
 * 
 * Improvements made:
 * 1. Fixed Critical Bug: Changed '0' (digit zero) to 'O' (letter O) in counting and win checks.
 * 2. Removed Static State: Encapsulated board state in an instance variable for better OOP design.
 * 3. Improved Input Handling: Replaced custom InputReader with standard java.util.Scanner for readability.
 * 4. Extracted Logic: Moved win-checking and counting logic into dedicated methods (hasWon, countPieces).
 * 5. Enhanced Readability: Used meaningful variable names and organized validation logic into clear steps.
 * 6. Removed Boilerplate: Eliminated the custom InputReader class in favor of standard library utilities.
 */
public class TicTacToeValidator {

    private final char[][] board;

    public TicTacToeValidator(char[][] board) {
        this.board = board;
    }

    /**
     * Analyzes the board state and prints the result.
     */
    public void analyze() {
        int xCount = countPieces('X');
        int oCount = countPieces('O');

        // 1. Validate Piece Counts
        // Valid states: X count must equal O count, or X count must be O count + 1.
        // O count cannot be greater than X count.
        if (xCount != oCount && xCount != oCount + 1) {
            System.out.println("illegal");
            return;
        }

        boolean xWins = hasWon('X');
        boolean oWins = hasWon('O');

        // 2. Validate Win Conditions
        // Both players cannot win simultaneously in a valid game.
        if (xWins && oWins) {
            System.out.println("illegal");
            return;
        }

        // If X wins, X must have made the last move (X count == O count + 1).
        if (xWins && xCount != oCount + 1) {
            System.out.println("illegal");
            return;
        }

        // If O wins, O must have made the last move (X count == O count).
        if (oWins && xCount != oCount) {
            System.out.println("illegal");
            return;
        }

        // 3. Determine Result
        if (xWins) {
            System.out.println("the first player won");
        } else if (oWins) {
            System.out.println("the second player won");
        } else if (xCount == 5 && oCount == 4) {
            System.out.println("draw");
        } else if (xCount == oCount) {
            System.out.println("first"); // X's turn
        } else if (xCount == oCount + 1) {
            System.out.println("second"); // O's turn
        } else {
            // Fallback for any unhandled valid state
            System.out.println("illegal");
        }
    }

    /**
     * Counts occurrences of a specific piece on the board.
     */
    private int countPieces(char piece) {
        int count = 0;
        for (char[] row : board) {
            for (char cell : row) {
                if (cell == piece) {
                    count++;
                }
            }
        }
        return count;
    }

    /**
     * Checks if a specific player has won the game.
     */
    private boolean hasWon(char player) {
        // Check Rows
        for (int i = 0; i < 3; i++) {
            if (board[i][0] == player && board[i][1] == player && board[i][2] == player) {
                return true;
            }
        }

        // Check Columns
        for (int j = 0; j < 3; j++) {
            if (board[0][j] == player && board[1][j] == player && board[2][j] == player) {
                return true;
            }
        }

        // Check Diagonals
        if (board[0][0] == player && board[1][1] == player && board[2][2] == player) {
            return true;
        }
        if (board[0][2] == player && board[1][1] == player && board[2][0] == player) {
            return true;
        }

        return false;
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        char[][] board = new char[3][3];

        // Read the 3x3 grid
        // Assumes input format is 3 strings, each representing a row.
        for (int i = 0; i < 3; i++) {
            if (scanner.hasNext()) {
                String row = scanner.next();
                board[i] = row.toCharArray();
            }
        }

        TicTacToeValidator validator = new TicTacToeValidator(board);
        validator.analyze();

        scanner.close();
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayList;
import java.util.List;

public class TicTacToe {
    public static void main(String[] args) throws IOException {
        // Use try-with-resources to guarantee the reader is automatically closed
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(System.in))) {
            String result = evaluateGame(reader);
            System.out.println(result);
        }
    }

    /**
     * Orchestrates the entire game evaluation process.
     */
    private static String evaluateGame(BufferedReader reader) throws IOException {
        // 1. Parse and validate input
        List<Character> cells = parseInput(reader);
        if (cells.size() != 9) {
            return "illegal";
        }

        // 2. Initialize board and calculate counts in a single pass
        char[][] board = new char[3][3];
        int xCount = 0;
        int oCount = 0;
        int emptyCount = 0;

        for (int i = 0; i < 9; i++) {
            char c = cells.get(i);
            board[i / 3][i % 3] = c;

            if (c == 'X') {
                xCount++;
            } else if (c == 'O') { // Fixed: Original code used digit '0' instead of letter 'O'
                oCount++;
            } else {
                emptyCount++;
            }
        }

        // 3. Validate move counts (X always starts, so X count must equal or be one more than O count)
        if (xCount != oCount && xCount != oCount + 1) {
            return "illegal";
        }

        // 4. Check for a winner
        char winner = checkWinner(board);

        // 5. Determine final game state based on standard Tic-Tac-Toe rules
        if (winner == 'X') {
            return (xCount > oCount) ? "the first player won" : "illegal";
        } else if (winner == 'O') {
            return (xCount == oCount) ? "the second player won" : "illegal";
        } else if (emptyCount == 0) {
            return "draw";
        } else if (xCount == oCount) {
            return "first";
        } else {
            return "second";
        }
    }

    /**
     * Reads from the input stream, skipping whitespace and newlines,
     * until exactly 9 game cells are collected.
     */
    private static List<Character> parseInput(BufferedReader reader) throws IOException {
        List<Character> cells = new ArrayList<>(9);
        String line;

        while (cells.size() < 9 && (line = reader.readLine()) != null) {
            for (char c : line.toCharArray()) {
                if (!Character.isWhitespace(c)) {
                    cells.add(c);
                }
            }
        }
        return cells;
    }

    /**
     * Checks all rows, columns, and diagonals for a winning condition.
     * Returns the winning character ('X' or 'O'), or a space if no winner.
     */
    private static char checkWinner(char[][] board) {
        // Check rows
        for (int i = 0; i < 3; i++) {
            if (board[i][0] != ' ' && board[i][0] == board[i][1] && board[i][1] == board[i][2]) {
                return board[i][0];
            }
        }

        // Check columns
        for (int j = 0; j < 3; j++) {
            if (board[0][j] != ' ' && board[0][j] == board[1][j] && board[1][j] == board[2][j]) {
                return board[0][j];
            }
        }

        // Check main diagonal
        if (board[0][0] != ' ' && board[0][0] == board[1][1] && board[1][1] == board[2][2]) {
            return board[0][0];
        }

        // Check anti-diagonal
        if (board[0][2] != ' ' && board[0][2] == board[1][1] && board[1][1] == board[2][0]) {
            return board[0][2];
        }

        return ' ';
    }
}

import java.io.BufferedReader;
