/**
 * Refactored Tic-Tac-Toe Solver.
 * 
 * Key Improvements:
 * 1. Separation of Concerns: Logic (Solver) is separated from I/O (InputReader/PrintWriter).
 * 2. Readability: Meaningful variable names (xCount, oCount) and constants (BOARD_SIZE, PLAYER_X).
 * 3. Maintainability: Win-checking logic is extracted into a dedicated helper method, removing hardcoded repetitive checks.
 * 4. Robustness: InputReader handles EOF gracefully; Board representation uses char[][] for clarity.
 * 5. Validation: Game state validation is broken down into clear, logical steps.
 */
public class TicTacToe {

    // Constants for game configuration
    private static final int BOARD_SIZE = 3;
    private static final char PLAYER_X = 'X';
    private static final char PLAYER_O = '0'; // Note: Input uses '0' (zero) for second player

    public static void main(String[] args) {
        // Setup I/O streams
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;

        // Initialize readers and writer
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);

        // Execute solver
        TicTacToeSolver solver = new TicTacToeSolver();
        solver.solve(in, out);

        // Ensure output is written
        out.flush();
        out.close();
    }

    /**
     * Handles the game logic and validation.
     */
    static class TicTacToeSolver {

        /**
         * Main entry point for solving a game instance.
         */
        void solve(InputReader in, PrintWriter out) {
            char[][] board = readBoard(in);
            String result = analyzeGame(board);
            out.print(result);
        }

        /**
         * Reads the 3x3 board from input.
         */
        private char[][] readBoard(InputReader in) {
            char[][] board = new char[BOARD_SIZE][BOARD_SIZE];
            for (int i = 0; i < BOARD_SIZE; i++) {
                String row = in.next();
                // Handle potential null if input ends prematurely
                if (row == null) break; 

                for (int j = 0; j < BOARD_SIZE && j < row.length(); j++) {
                    board[i][j] = row.charAt(j);
                }
            }
            return board;
        }

        /**
         * Analyzes the board state to determine the game outcome.
         */
        private String analyzeGame(char[][] board) {
            int xCount = 0;
            int oCount = 0;

            // Count players and verify board content
            for (int i = 0; i < BOARD_SIZE; i++) {
                for (int j = 0; j < BOARD_SIZE; j++) {
                    char cell = board[i][j];
                    if (cell == PLAYER_X) {
                        xCount++;
                    } else if (cell == PLAYER_O) {
                        oCount++;
                    }
                }
            }

            boolean xWon = checkWin(board, PLAYER_X);
            boolean oWon = checkWin(board, PLAYER_O);

            // --- Validation Rules ---

            // 1. Count Validity: X starts, so X count must equal O count or be exactly 1 greater.
            //    Invalid if O count > X count OR X count >= O count + 2.
            if (oCount > xCount || xCount > oCount + 1) {
                return "illegal";
            }

            // 2. Winning Condition Validity:
            //    - Both players cannot win simultaneously.
            //    - If X wins, X must have made the last move (X count == O count + 1).
            //    - If O wins, O must have made the last move (X count == O count).
            if (xWon && oWon) {
                return "illegal";
            }
            if (xWon && xCount != oCount + 1) {
                return "illegal";
            }
            if (oWon && xCount != oCount) {
                return "illegal";
            }

            // --- Result Determination ---

            // Check for wins
            if (xWon) {
                return "the first player won";
            }
            if (oWon) {
                return "the second player won";
            }

            // Check for draw (board full)
            if (xCount + oCount == BOARD_SIZE * BOARD_SIZE) {
                return "draw";
            }

            // Determine whose turn it is for ongoing games
            if (xCount == oCount + 1) {
                return "second"; // Next player is O (second player)
            } else if (xCount == oCount) {
                return "first"; // Next player is X (first player)
            }

            // Fallback (should be unreachable given validation)
            return "draw";
        }

        /**
         * Checks if the specified player has won.
         */
        private boolean checkWin(char[][] board, char player) {
            // Check Rows
            for (int i = 0; i < BOARD_SIZE; i++) {
                if (board[i][0] == player && board[i][1] == player && board[i][2] == player) {
                    return true;
                }
            }

            // Check Columns
            for (int j = 0; j < BOARD_SIZE; j++) {
                if (board[0][j] == player && board[1][j] == player && board[2][j] == player) {
                    return true;
                }
            }

            // Check Diagonals
            if (board[0][0] == player && board[1][1] == player && board[2][2] == player) {
                return true;
            }
            if (board[0][2] == player && board[1][1] == player && board[2][0] == player) {
                return true;
            }

            return false;
        }
    }

    /**
     * Helper class for fast input reading.
     */
    static class InputReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public InputReader(InputStream stream) {
            this.reader = new BufferedReader(new InputStreamReader(stream), 32768);
            this.tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) {
                        return null;
                    }
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }
    }
}

