        System.out.println(result);
    }

    /**
     * Analyzes the board state to determine the game outcome or validity.
     * Encapsulates the complex logic into a readable method.
     */
    private static String analyzeBoardState(char[][] board) {
        int countX = 0;
        int countO = 0;
        int countEmpty = 0;

        // 1. Count pieces on the board
        for (int i = 0; i < BOARD_SIZE; i++) {
            for (int j = 0; j < BOARD_SIZE; j++) {
                char cell = board[i][j];
                if (cell == PLAYER_X) {
                    countX++;
                } else if (cell == PLAYER_O) {
                    countO++;
                } else if (cell == EMPTY) {
                    countEmpty++;
                }
            }
        }

        // 2. Check for winning lines
        boolean xWins = checkWinCondition(board, PLAYER_X);
        boolean oWins = checkWinCondition(board, PLAYER_O);

        // 3. Validate Game Rules (Check for Illegal States)

        // Rule 1: Both players cannot win simultaneously
        if (xWins && oWins) {
            return "illegal";
        }

        // Rule 2: If X wins, X must have played the last move (X count = O count + 1)
        // Original logic: numberOfXWins >= 1 && numberOfXs == numberOf0s
        if (xWins && countX == countO) {
            return "illegal";
        }

        // Rule 3: If O wins, O must have played the last move (X count = O count)
        // Original logic: numberOf0Wins >= 1 && numberOfXs == numberOf0s + 1
        if (oWins && countX == countO + 1) {
            return "illegal";
        }

        // Rule 4: Turn order must be valid (X starts, so X count >= O count, and difference <= 1)
        // Original logic: numberOfXs < numberOf0s || numberOfXs > numberOf0s + 1
        if (countX < countO || countX > countO + 1) {
            return "illegal";
        }

        // 4. Determine Game Status based on valid state
        if (xWins) {
            return "the first player won";
        }
        if (oWins) {
            return "the second player won";
        }
        if (countEmpty == 0) {
            return "draw";
        }
        if (countX == countO) {
            return "first"; // X's turn
        }
        if (countX == countO + 1) {
            return "second"; // O's turn
        }

        // Fallback (should technically be unreachable if logic is sound)
        return "illegal";
    }

    /**
     * Checks if a specific player has won the game.
     * Replaces the complex nested loops with clear row, column, and diagonal checks.
     */
    private static boolean checkWinCondition(char[][] board, char player) {
        // Check Rows
        for (int i = 0; i < BOARD_SIZE; i++) {
            if (board[i][0] == player && board[i][1] == player && board[i][2] == player) {
                return true;
            }
        }

        // Check Columns
        for (int i = 0; i < BOARD_SIZE; i++) {
            if (board[0][i] == player && board[1][i] == player && board[2][i] == player) {
                return true;
            }
        }

        // Check Diagonals
        // Forward Diagonal (Top-Left to Bottom-Right)
        if (board[0][0] == player && board[1][1] == player && board[2][2] == player) {
            return true;
        }
        // Backward Diagonal (Top-Right to Bottom-Left)
        if (board[0][2] == player && board[1][1] == player && board[2][0] == player) {
            return true;
        }

        return false;
    }
}

