            int oCount = 0;
            int emptyCount = 0;

            for (char[] row : board) {
                for (char cell : row) {
                    if (cell == PLAYER_X) {
                        xCount++;
                    } else if (cell == PLAYER_O) {
                        oCount++;
                    } else if (cell == EMPTY) {
                        emptyCount++;
                    }
                }
            }

            int winnerMask = checkWinner(board);
            String result;

            if (isIllegal(winnerMask, xCount, oCount)) {
                result = "illegal";
            } else if (winnerMask != 0) {
                result = winnerMask == 1 ? "the first player won" : "the second player won";
            } else if (emptyCount == 0) {
                result = "draw";
            } else if (xCount == oCount) {
                result = "first";
            } else {
                result = "second";
            }

            System.out.println(result);
        }
    }

    /**
     * Checks all possible winning lines on the board.
     * Returns a bitmask: 1 if X won, 2 if O won, 3 if both won, 0 otherwise.
     */
    private static int checkWinner(char[][] board) {
        int winnerMask = 0;

        // Check rows
        for (int i = 0; i < BOARD_SIZE; i++) {
            if (board[i][0] != EMPTY && board[i][0] == board[i][1] && board[i][1] == board[i][2]) {
                winnerMask |= (board[i][0] == PLAYER_X ? 1 : 2);
            }
        }

        // Check columns
        for (int i = 0; i < BOARD_SIZE; i++) {
            if (board[0][i] != EMPTY && board[0][i] == board[1][i] && board[1][i] == board[2][i]) {
                winnerMask |= (board[0][i] == PLAYER_X ? 1 : 2);
            }
        }

        // Check diagonals
        if (board[0][0] != EMPTY && board[0][0] == board[1][1] && board[1][1] == board[2][2]) {
            winnerMask |= (board[0][0] == PLAYER_X ? 1 : 2);
        }
        if (board[0][2] != EMPTY && board[0][2] == board[1][1] && board[1][1] == board[2][0]) {
            winnerMask |= (board[0][2] == PLAYER_X ? 1 : 2);
        }

        return winnerMask;
    }

    /**
     * Validates the game state according to standard Tic-Tac-Toe rules.
     * Returns true if the board configuration is impossible or violates turn order.
     */
    private static boolean isIllegal(int winnerMask, int xCount, int oCount) {
        // Both players have three in a row simultaneously
        if (winnerMask == 3) {
            return true;
        }
        // O has made more moves than X (X always goes first)
        if (oCount > xCount) {
            return true;
        }
        // X has made more than one extra move
        if (xCount - oCount > 1) {
            return true;
        }
        // O won, but X made the last move
        if (winnerMask == 2 && xCount == oCount + 1) {
            return true;
        }
        // X won, but O made the last move
        if (winnerMask == 1 && xCount == oCount) {
            return true;
        }

        return false;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;

/**
 * Validates a 3x3 Tic-Tac-Toe board state and determines the current game status.
 * 
 * Refactoring improvements:
 * - Separated I/O, validation, and win-checking logic into distinct methods
 * - Replaced magic strings/numbers with named constants
 * - Used try-with-resources for automatic stream management
 * - Clarified '0' -> 'O' for standard Tic-Tac-Toe notation
 * - Removed unnecessary threading and file I/O boilerplate for cleaner execution
 * - Added JavaDoc and inline comments for maintainability
 */
public class TicTacToeValidator {

    // Player tokens
    private static final char PLAYER_X = 'X';
    private static final char PLAYER_O = 'O'; // Changed from '0' for standard notation
    private static final int BOARD_SIZE = 3;

    // Output messages matching the original program's expected results
    private static final String MSG_FIRST_TURN = "first";
    private static final String MSG_SECOND_TURN = "second";
    private static final String MSG_ILLEGAL = "illegal";
    private static final String MSG_FIRST_WON = "the first player won";
    private static final String MSG_SECOND_WON = "the second player won";
    private static final String MSG_DRAW = "draw";

    public static void main(String[] args) {
        // try-with-resources ensures streams are closed even if an exception occurs
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
             PrintWriter writer = new PrintWriter(System.out)) {

            char[][] board = readBoard(reader);
            String result = validateBoard(board);
            writer.println(result);
            writer.flush();

        } catch (IOException e) {
            // In a production environment, consider using a proper logging framework
            e.printStackTrace();
        }
    }

    /**
     * Reads exactly 3 lines from the input and returns a 3x3 character board.
     */
    private static char[][] readBoard(BufferedReader reader) throws IOException {
        char[][] board = new char[BOARD_SIZE][BOARD_SIZE];
        for (int i = 0; i < BOARD_SIZE; i++) {
            String line = reader.readLine();
            if (line == null) {
                throw new IOException("Unexpected end of input: expected " + BOARD_SIZE + " rows.");
            }
            board[i] = line.trim().toCharArray();
        }
        return board;
    }

    /**
     * Validates the board state according to Tic-Tac-Toe rules and returns the game status.
     */
    private static String validateBoard(char[][] board) {
        int countX = 0;
        int countO = 0;

        // Count moves for each player
        for (char[] row : board) {
            for (char cell : row) {
                if (cell == PLAYER_X) {
                    countX++;
                } else if (cell == PLAYER_O) {
                    countO++;
                }
            }
        }

        // Rule 1: X always goes first. Valid counts are countX == countO or countX == countO + 1
        if (countO > countX || countX - countO > 1) {
            return MSG_ILLEGAL;
        }

        boolean xWon = checkWinCondition(board, PLAYER_X);
        boolean oWon = checkWinCondition(board, PLAYER_O);

        // Rule 2: Both players cannot win simultaneously
        if (xWon && oWon) {
            return MSG_ILLEGAL;
        }

        // Rule 3: If O won, the board must have equal moves (O moves second)
        if (oWon && countX != countO) {
            return MSG_ILLEGAL;
        }

        // Rule 4: If X won, X must have made exactly one more move than O
        if (xWon && countX != countO + 1) {
            return MSG_ILLEGAL;
        }

        // Determine final game state
        if (xWon) {
            return MSG_FIRST_WON;
        }
        if (oWon) {
            return MSG_SECOND_WON;
        }
        if (countX + countO == BOARD_SIZE * BOARD_SIZE) {
            return MSG_DRAW;
        }
        if (countX > countO) {
            return MSG_SECOND_TURN;
        }
        return MSG_FIRST_TURN;
    }

    /**
     * Checks if the specified player has achieved a winning line (row, column, or diagonal).
     */
    private static boolean checkWinCondition(char[][] board, char player) {
        // Check rows
        for (int i = 0; i < BOARD_SIZE; i++) {
            if (board[i][0] == player && board[i][1] == player && board[i][2] == player) {
                return true;
            }
        }
        // Check columns
        for (int j = 0; j < BOARD_SIZE; j++) {
            if (board[0][j] == player && board[1][j] == player && board[2][j] == player) {
                return true;
            }
        }
        // Check main diagonal
        if (board[0][0] == player && board[1][1] == player && board[2][2] == player) {
            return true;
        }
        // Check anti-diagonal
        if (board[0][2] == player && board[1][1] == player && board[2][0] == player) {
            return true;
        }
        return false;
    }
}

