/**
 * Validates and analyzes a Tic-Tac-Toe board state.
 * Reads a 3x3 board from standard input and determines the game outcome.
 */
public class TicTacToeValidator {

    private static final int BOARD_SIZE = 3;
    private static final int TOTAL_CELLS = BOARD_SIZE * BOARD_SIZE;

    public static void main(String[] args) throws IOException {
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(System.in))) {
            char[][] board = new char[BOARD_SIZE][BOARD_SIZE];

            // Read and validate board input
            for (int i = 0; i < BOARD_SIZE; i++) {
                String line = reader.readLine();
                if (line == null || line.length() != BOARD_SIZE) {
                    throw new IllegalArgumentException("Invalid input: each row must contain exactly 3 characters.");
                }
                board[i] = line.toCharArray();
            }

            boolean xWins = checkWin(board, 'X');
            // Note: Original code used '0' (digit zero). Changed to 'O' (letter O) for standard Tic-Tac-Toe notation.
            boolean oWins = checkWin(board, 'O');
            int xCount = countPlayerMoves(board, 'X');
            int oCount = countPlayerMoves(board, 'O');

            if (isIllegalState(xWins, oWins, xCount, oCount)) {
                System.out.println("illegal");
            } else if (xWins) {
                System.out.println("the first player won");
            } else if (oWins) {
                System.out.println("the second player won");
            } else if (xCount == oCount) {
                System.out.println("first");
            } else if (xCount + oCount != TOTAL_CELLS) {
                System.out.println("second");
            } else {
                System.out.println("draw");
            }
        }
    }

    /**
     * Checks if the specified player has won on the board.
     */
    private static boolean checkWin(char[][] board, char player) {
        // Check rows and columns
        for (int i = 0; i < BOARD_SIZE; i++) {
            boolean rowWin = true;
            boolean colWin = true;
            for (int j = 0; j < BOARD_SIZE; j++) {
                if (board[i][j] != player) rowWin = false;
                if (board[j][i] != player) colWin = false;
            }
            if (rowWin || colWin) {
                return true;
            }
        }

        // Check diagonals
        boolean diag1Win = true;
        boolean diag2Win = true;
        for (int i = 0; i < BOARD_SIZE; i++) {
            if (board[i][i] != player) diag1Win = false;
            if (board[i][BOARD_SIZE - 1 - i] != player) diag2Win = false;
        }

        return diag1Win || diag2Win;
    }

    /**
     * Counts the number of moves made by the specified player.
     */
    private static int countPlayerMoves(char[][] board, char player) {
        int count = 0;
        for (char[] row : board) {
            for (char cell : row) {
                if (cell == player) {
                    count++;
                }
            }
        }
        return count;
    }

    /**
     * Validates whether the current board state is legal according to Tic-Tac-Toe rules.
     */
    private static boolean isIllegalState(boolean xWins, boolean oWins, int xCount, int oCount) {
        // Both players cannot win simultaneously
        if (xWins && oWins) {
            return true;
        }
        // X always goes first, so X's count must be equal to or one greater than O's count
        if (oCount > xCount) {
            return true;
        }
        if (xCount - oCount > 1) {
            return true;
        }
        // If X wins, X must have made the last move (xCount == oCount + 1)
        if (xWins && (xCount - oCount) != 1) {
            return true;
        }
        // If O wins, O must have made the last move (xCount == oCount)
        if (oWins && xCount != oCount) {
            return true;
        }

        return false;
    }
}

import java.io.*;
import java.util.*;

public class TicTacToeValidator {

    // Constants for players and board size
    // Note: Changed PLAYER_O from '0' (digit) to 'O' (letter) to match standard Tic-Tac-Toe conventions.
    private static final char PLAYER_X = 'X';
    private static final char PLAYER_O = 'O';
    private static final int BOARD_SIZE = 3;

    private final Scanner scanner;
    private final PrintWriter out;

    public TicTacToeValidator() {
        // Initialize buffered I/O for performance
        this.scanner = new Scanner(new BufferedInputStream(System.in));
        this.out = new PrintWriter(new BufferedOutputStream(System.out));
    }

    public static void main(String[] args) {
        TicTacToeValidator validator = new TicTacToeValidator();
        validator.run();
        validator.close();
    }

    public void run() {
        char[][] board = readBoard();
        analyzeBoard(board);
    }

    /**
     * Reads the 3x3 board from input.
     * Assumes input contains 3 strings of length 3.
     */
    private char[][] readBoard() {
        char[][] board = new char[BOARD_SIZE][BOARD_SIZE];
        for (int i = 0; i < BOARD_SIZE; i++) {
            if (scanner.hasNext()) {
                String row = scanner.next();
                board[i] = row.toCharArray();
            }
        }
        return board;
    }

    /**
     * Analyzes the board state and prints the result.
     */
    private void analyzeBoard(char[][] board) {
        int xCount = countMoves(board, PLAYER_X);
        int oCount = countMoves(board, PLAYER_O);

        int xWins = countWinningLines(board, PLAYER_X);
        int oWins = countWinningLines(board, PLAYER_O);

        if (isIllegalState(xCount, oCount, xWins, oWins)) {
            out.println("illegal");
        } else if (xWins > 0) {
            out.println("the first player won");
        } else if (oWins > 0) {
            out.println("the second player won");
        } else if (xCount + oCount == BOARD_SIZE * BOARD_SIZE) {
            out.println("draw");
        } else {
            // Determine whose turn it is next
            // If X has more moves, it's O's turn (second player)
            // If counts are equal, it's X's turn (first player)
            out.println(xCount > oCount ? "second" : "first");
        }
    }

    /**
     * Validates if the board state is reachable under standard rules.
     */
    private boolean isIllegalState(int xCount, int oCount, int xWins, int oWins) {
        // 1. O cannot have more moves than X (X always starts)
        if (oCount > xCount) {
            return true;
        }
        // 2. X cannot have more than 1 move than O (alternating turns)
        if (xCount - oCount > 1) {
            return true;
        }
        // 3. Both players cannot win simultaneously
        if (xWins + oWins > 1) {
            return true;
        }
        // 4. If X won, X must have made the last move (xCount == oCount + 1)
        // If oCount >= xCount, it implies O moved last or counts are equal, which is impossible if X just won.
        if (xWins > 0 && oCount >= xCount) {
            return true;
        }
        // 5. If O won, O must have made the last move (oCount == xCount)
        // If xCount > oCount, it implies X moved last, which is impossible if O just won.
        if (oWins > 0 && xCount > oCount) {
            return true;
        }

        return false;
    }

    /**
     * Counts the total number of moves made by a specific player on the board.
     */
    private int countMoves(char[][] board, char player) {
        int count = 0;
        for (char[] row : board) {
            for (char cell : row) {
                if (cell == player) {
                    count++;
                }
            }
        }
        return count;
    }

    /**
     * Counts the number of winning lines for a specific player.
     * Preserves the specific logic from the original code regarding overlapping wins.
     */
    private int countWinningLines(char[][] board, char player) {
        int lineCounts = new int[8]; // 3 rows, 3 cols, 2 diagonals
        int idx = 0;

        // Check Rows
        for (int r = 0; r < BOARD_SIZE; r++) {
            int count = 0;
            for (int c = 0; c < BOARD_SIZE; c++) {
                if (board[r][c] == player) {
                    count++;
                }
            }
            lineCounts[idx++] = count;
        }

        // Check Columns
        for (int c = 0; c < BOARD_SIZE; c++) {
            int count = 0;
            for (int r = 0; r < BOARD_SIZE; r++) {
                if (board[r][c] == player) {
                    count++;
                }
            }
            lineCounts[idx++] = count;
        }

        // Check Main Diagonal (Top-Left to Bottom-Right)
        int count = 0;
        if (board[0][0] == player) count++;
        if (board[1][1] == player) count++;
        if (board[2][2] == player) count++;
        lineCounts[idx++] = count;

        // Check Anti-Diagonal (Top-Right to Bottom-Left)
        count = 0;
        if (board[0][2] == player) count++;
        if (board[1][1] == player) count++;
        if (board[2][0] == player) count++;
        lineCounts[idx++] = count;

        // Calculate 'w' (number of full winning lines)
        // A line counts as a win if it has 3 matching characters.
        int w = 0;
        for (int c : lineCounts) {
            w += c / 3;
        }

        // Original logic adjustment: 
        // If the total number of pieces is less than 3 * w, it implies overlapping lines 
        // (e.g., a cross shape) where distinct wins aren't fully supported by piece count.
        // In such cases, reduce the win count by 1.
        int totalMoves = countMoves(board, player);
        return (3 * w <= totalMoves) ? w : w - 1;
    }

    /**
     * Closes the output stream.
     */
    public void close() {
        out.close();
    }
}

import java.util.Scanner;

public class Game {
    private static final int BOARD_SIZE = 3;
    private static final int TOTAL_CELLS = BOARD_SIZE * BOARD_SIZE;

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        char[][] board = new char[BOARD_SIZE][BOARD_SIZE];

        // Read board input
        for (int i = 0; i < BOARD_SIZE; i++) {
            if (scanner.hasNext()) {
                board[i] = scanner.next().toCharArray();
            }
        }

        // Evaluate and print result
        GameState result = evaluateBoard(board);
        System.out.println(formatResult(result));
    }

    /**
     * Evaluates the board state and returns the corresponding game outcome.
     */
    private static GameState evaluateBoard(char[][] board) {
        int xCount = 0;
        int oCount = 0;
        int xWins = 0;
        int oWins = 0;

        // Count pieces
        for (int i = 0; i < BOARD_SIZE; i++) {
            for (int j = 0; j < BOARD_SIZE; j++) {
                if (board[i][j] == 'X') xCount++;
                else if (board[i][j] == 'O') oCount++;
            }
        }

        // Check all 8 winning lines
        int[][][] winLines = {
            {{0, 0}, {0, 1}, {0, 2}}, {{1, 0}, {1, 1}, {1, 2}}, {{2, 0}, {2, 1}, {2, 2}},
            {{0, 0}, {1, 0}, {2, 0}}, {{0, 1}, {1, 1}, {2, 1}}, {{0, 2}, {1, 2}, {2, 2}},
            {{0, 0}, {1, 1}, {2, 2}}, {{0, 2}, {1, 1}, {2, 0}}
        };

        for (int[] line : winLines) {
            char c = board[line[0][0]][line[0][1]];
            if (c != '.' && c == board[line[1][0]][line[1][1]] && c == board[line[2][0]][line[2][1]]) {
                if (c == 'X') xWins++;
                else oWins++;
            }
        }

        // Validation rules
        if (xWins > 0 && oWins > 0) return GameState.ILLEGAL;
        if (xWins > 0 && xCount != oCount + 1) return GameState.ILLEGAL;
        if (oWins > 0 && xCount != oCount) return GameState.ILLEGAL;
        if (xCount != oCount && xCount != oCount + 1) return GameState.ILLEGAL;

        // Determine final state
        if (xWins > 0) return GameState.FIRST_WON;
        if (oWins > 0) return GameState.SECOND_WON;
        if (xCount + oCount == TOTAL_CELLS) return GameState.DRAW;
        if (xCount == oCount) return GameState.FIRST_TURN;
        if (xCount == oCount + 1) return GameState.SECOND_TURN;

        return GameState.ILLEGAL;
    }

    /**
     * Maps the internal GameState enum to the required console output strings.
     */
    private static String formatResult(GameState state) {
        switch (state) {
            case ILLEGAL: return "illegal";
            case FIRST_WON: return "the first player won";
            case SECOND_WON: return "the second player won";
            case DRAW: return "draw";
            case FIRST_TURN: return "first";
            case SECOND_TURN: return "second";
            default: return "illegal";
        }
    }

    /**
     * Represents all possible valid and invalid states of a Tic-Tac-Toe board.
     */
    private enum GameState {
        ILLEGAL,
        FIRST_WON,
        SECOND_WON,
        DRAW,
        FIRST_TURN,
        SECOND_TURN
    }
}

