    private static final int RESULT_FIRST_WINS = 3;
    private static final int RESULT_SECOND_WINS = 4;
    private static final int RESULT_DRAW = 5;

    // Line coordinates: rows, columns, and diagonals
    private static final int[][][] LINES = {
        // Rows
        {{0, 0}, {0, 1}, {0, 2}},
        {{1, 0}, {1, 1}, {1, 2}},
        {{2, 0}, {2, 1}, {2, 2}},
        // Columns
        {{0, 0}, {1, 0}, {2, 0}},
        {{0, 1}, {1, 1}, {2, 1}},
        {{0, 2}, {1, 2}, {2, 2}},
        // Diagonals
        {{0, 0}, {1, 1}, {2, 2}},
        {{0, 2}, {1, 1}, {2, 0}}
    };

    // Memoization table: maps base-3 state index to outcome
    private final int[] memo;
    // Current board state used during backtracking
    private final int[][] board;

    public Main() {
        memo = new int[TOTAL_STATES];
        board = new int[BOARD_SIZE][BOARD_SIZE];
        precomputeOutcomes();
    }

    /**
     * Initializes the memoization table by computing outcomes for all reachable states.
     */
    private void precomputeOutcomes() {
        memoizeState(0, PLAYER_X);
    }

    /**
     * Checks if there is a winner on the current board state.
     * @return PLAYER_X, PLAYER_O, or EMPTY if no winner.
     */
    private int getWinner() {
        for (int[] line : LINES) {
            int firstCell = board[line[0][0]][line[0][1]];
            if (firstCell != EMPTY &&
                firstCell == board[line[1][0]][line[1][1]] &&
                firstCell == board[line[2][0]][line[2][1]]) {
                return firstCell;
            }
        }
        return EMPTY;
    }

    /**
     * Recursively computes the game outcome for a given board state using memoization.
     * @param stateIndex Base-3 integer representation of the board state.
     * @param nextPlayer The player whose turn it is to move next (1 or 2).
     */
    private void memoizeState(int stateIndex, int nextPlayer) {
        // Return immediately if this state has already been computed
        if (memo[stateIndex] != 0) {
            return;
        }

        int winner = getWinner();
        if (winner != EMPTY) {
            // A winner has been found. Map 1->3, 2->4 according to original logic.
            memo[stateIndex] = (winner == PLAYER_X) ? RESULT_FIRST_WINS : RESULT_SECOND_WINS;
            return;
        }

        // Default to the player who just moved (assumes optimal play leads to their win)
        memo[stateIndex] = (nextPlayer == PLAYER_X) ? RESULT_FIRST_TURN : RESULT_SECOND_TURN;

        boolean madeMove = false;
        int multiplier = 1;

        for (int i = 0; i < BOARD_SIZE; i++) {
            for (int j = 0; j < BOARD_SIZE; j++) {
                if (board[i][j] == EMPTY) {
                    board[i][j] = nextPlayer;
                    memoizeState(stateIndex + multiplier * nextPlayer, 3 - nextPlayer);
                    board[i][j] = EMPTY; // Backtrack
                    madeMove = true;
                }
                multiplier *= 3;
            }
        }

        // If no moves were possible, the game is a draw
        if (!madeMove) {
            memo[stateIndex] = RESULT_DRAW;
        }
    }

    /**
     * Parses the input board configuration into a base-3 state index.
     * @param inputLines Array of 3 strings representing the board rows.
     * @return The base-3 state index, or -1 if input is invalid.
     */
    private int parseBoardState(String[] inputLines) {
        if (inputLines.length != BOARD_SIZE) {
            return -1;
        }

        int stateIndex = 0;
        int multiplier = 1;

        for (String line : inputLines) {
            if (line == null || line.length() < BOARD_SIZE) {
                return -1;
            }
            for (int j = 0; j < BOARD_SIZE; j++) {
                char ch = line.charAt(j);
                if (ch == MARKER_X) {
                    stateIndex += multiplier * PLAYER_X;
                } else if (ch == MARKER_O) {
                    stateIndex += multiplier * PLAYER_O;
                } else if (ch == ' ' || ch == '.') {
                    // Empty cell, contributes 0
                } else {
                    return -1; // Invalid character
                }
                multiplier *= 3;
            }
        }
        return stateIndex;
    }

    /**
     * Maps the numeric result code to the corresponding output message.
     */
    private String getResultMessage(int result) {
        switch (result) {
            case RESULT_UNKNOWN: return "illegal";
            case RESULT_FIRST_TURN: return "first";
            case RESULT_SECOND_TURN: return "second";
            case RESULT_FIRST_WINS: return "the first player won";
            case RESULT_SECOND_WINS: return "the second player won";
            case RESULT_DRAW: return "draw";
            default: return "unknown state";
        }
    }

    public static void main(String[] args) {
        Main solver = new Main();
        try (Scanner scanner = new Scanner(System.in)) {
            String[] input = new String[BOARD_SIZE];
            for (int i = 0; i < BOARD_SIZE; i++) {
                input[i] = scanner.next();
            }

            int stateIndex = solver.parseBoardState(input);
            if (stateIndex == -1 || stateIndex >= TOTAL_STATES) {
                System.out.println("illegal");
            } else {
                System.out.println(solver.getResultMessage(solver.memo[stateIndex]));
            }
        }
    }
}

import java.util.Scanner;

public class TicTacToe {
    // Constants for board dimensions and player markers
    private static final int BOARD_SIZE = 3;
    private static final char PLAYER_X = 'X';
    // Note: The original code used '0' (digit zero) for the second player.
    // We retain this character to ensure functional compatibility with the provided logic.
    private static final char PLAYER_O = '0';

    public static void main(String[] args) {
        // Use try-with-resources to ensure the Scanner is closed automatically
        try (Scanner scanner = new Scanner(System.in)) {
            char[][] board = new char[BOARD_SIZE][BOARD_SIZE];
            int xCount = 0;
            int oCount = 0;

            // 1. Read the board state from input
            for (int r = 0; r < BOARD_SIZE; r++) {
                if (scanner.hasNextLine()) {
                    String line = scanner.nextLine();
                    // Read up to BOARD_SIZE characters, handling potential short lines safely
                    int colsToRead = Math.min(line.length(), BOARD_SIZE);
                    for (int c = 0; c < colsToRead; c++) {
                        char ch = line.charAt(c);
                        board[r][c] = ch;
                        if (ch == PLAYER_X) {
                            xCount++;
                        } else if (ch == PLAYER_O) {
                            oCount++;
                        }
                    }
                }
            }

            // 2. Validate move counts
            // X starts first, so xCount must be equal to oCount or oCount + 1.
            // Also, oCount cannot exceed xCount.
            if (Math.abs(xCount - oCount) > 1 || oCount > xCount) {
                System.out.println("illegal");
                return;
            }

            // 3. Check for winners
            boolean xWon = checkWinner(board, PLAYER_X);
            boolean oWon = checkWinner(board, PLAYER_O);

            // 4. Determine outcome based on wins and counts
            if (xWon && oWon) {
                // Both players cannot win simultaneously
                System.out.println("illegal");
            } else if (xWon) {
                // If X won, X must have made the last move (xCount == oCount + 1)
                if (xCount != oCount + 1) {
                    System.out.println("illegal");
                } else {
                    System.out.println("the first player won");
                }
            } else if (oWon) {
                // If O won, O must have made the last move (oCount == xCount)
                if (oCount != xCount) {
                    System.out.println("illegal");
                } else {
                    System.out.println("the second player won");
                }
            } else {
                // No winner
                if (xCount + oCount == BOARD_SIZE * BOARD_SIZE) {
                    System.out.println("draw");
                } else if ((xCount + oCount) % 2 == 1) {
                    // Odd total moves means it's O's turn (Second player)
                    System.out.println("second");
                } else {
                    // Even total moves means it's X's turn (First player)
                    System.out.println("first");
                }
            }
        }
    }

    /**
     * Checks if a specific player has won the game by checking rows, columns, and diagonals.
     *
     * @param board The game board
     * @param player The character representing the player ('X' or '0')
     * @return true if the player has won, false otherwise
     */
    private static boolean checkWinner(char[][] board, char player) {
        // Check rows
        for (int r = 0; r < BOARD_SIZE; r++) {
            if (board[r][0] == player && board[r][1] == player && board[r][2] == player) {
                return true;
            }
        }
        // Check columns
        for (int c = 0; c < BOARD_SIZE; c++) {
            if (board[0][c] == player && board[1][c] == player && board[2][c] == player) {
                return true;
            }
        }
        // Check diagonals
        if (board[0][0] == player && board[1][1] == player && board[2][2] == player) {
            return true;
        }
        if (board[0][2] == player && board[1][1] == player && board[2][0] == player) {
            return true;
        }
        return false;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;

public class Main {
    private static final int BOARD_SIZE = 3;
    private static final int TOTAL_CELLS = BOARD_SIZE * BOARD_SIZE;
    private static final char PLAYER_X = 'X';
    private static final char PLAYER_O = '0'; // Matches original specification

    private final char[][] board;
    private final int countX;
    private final int countO;

    public static void main(String[] args) throws IOException {
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            Main analyzer = new Main(br);
            analyzer.analyze();
        }
    }

    private Main(BufferedReader br) throws IOException {
        board = new char[BOARD_SIZE][BOARD_SIZE];
        int countX = 0;
        int countO = 0;

        for (int i = 0; i < BOARD_SIZE; i++) {
            String line = br.readLine();
            if (line == null || line.length() < BOARD_SIZE) {
                throw new IllegalArgumentException("Invalid input: expected 3 characters per row");
            }
            for (int j = 0; j < BOARD_SIZE; j++) {
                board[i][j] = line.charAt(j);
                if (board[i][j] == PLAYER_X) {
                    countX++;
                } else if (board[i][j] == PLAYER_O) {
                    countO++;
                }
            }
        }
        this.countX = countX;
        this.countO = countO;
    }

    public void analyze() {
        // Both players cannot win simultaneously
        if (isWin(PLAYER_X) && isWin(PLAYER_O)) {
            printIllegal();
            return;
        }

        // X always goes first, so counts must follow valid turn order
        if (countO > countX || countX > countO + 1) {
            printIllegal();
            return;
        }

        if (isWin(PLAYER_O)) {
            if (countO != countX) {
                printIllegal();
            } else {
                System.out.println("the second player won");
            }
            return;
        }

        if (isWin(PLAYER_X)) {
            if (countX != countO + 1) {
                printIllegal();
            } else {
                System.out.println("the first player won");
            }
            return;
        }

        if (countX + countO == TOTAL_CELLS) {
            System.out.println("draw");
        } else if (countX > countO) {
            System.out.println("second");
        } else if (countX == countO) {
            System.out.println("first");
        }
    }

    private boolean isWin(char player) {
        // Check rows
        for (int i = 0; i < BOARD_SIZE; i++) {
            if (isLineWin(i, 0, 0, 1, player)) return true;
        }
        // Check columns
        for (int i = 0; i < BOARD_SIZE; i++) {
            if (isLineWin(0, i, 1, 0, player)) return true;
        }
        // Check diagonals
        if (isLineWin(0, 0, 1, 1, player)) return true;
        if (isLineWin(0, BOARD_SIZE - 1, 1, -1, player)) return true;

        return false;
    }

    private boolean isLineWin(int rStart, int cStart, int rStep, int cStep, char player) {
        for (int i = 0; i < BOARD_SIZE; i++) {
            if (board[rStart + i * rStep][cStart + i * cStep] != player) {
                return false;
            }
        }
        return true;
    }

    private void printIllegal() {
        System.out.println("illegal");
    }
}

import java.io.BufferedReader;
import java.io.IOException;
