public class Problem3B {
    // Constants to replace magic numbers and improve readability
    private static final int BOARD_SIZE = 3;
    private static final char PLAYER_X = 'X';
    private static final char PLAYER_O = '0'; // Note: Original code uses '0' (zero) for the second player
    private static final char EMPTY = '.';

    public static void main(String[] args) throws IOException {
        // Use try-with-resources to ensure the reader is closed properly
        try (BufferedReader input = new BufferedReader(new InputStreamReader(System.in))) {
            char[][] board = new char[BOARD_SIZE][BOARD_SIZE];

            // Read input into the board
            for (int i = 0; i < BOARD_SIZE; i++) {
                String line = input.readLine();
                // Basic validation to prevent NullPointerExceptions or IndexOutOfBoundsExceptions
                if (line == null || line.length() < BOARD_SIZE) {
                    // If input is malformed, we fill remaining spots with empty or handle gracefully.
                    // For this refactoring, we assume valid input format as per original logic,
                    // but ensure safety.
                    if (line == null) break; 
                }

                for (int j = 0; j < BOARD_SIZE; j++) {
                    // Ensure index is within bounds of the actual string read
                    if (j < line.length()) {
                        board[i][j] = line.charAt(j);
                    } else {
                        board[i][j] = EMPTY;
                    }
                }
            }

            // Analyze the board state and print the result
            System.out.println(analyzeGameState(board));
        }
    }

    /**
     * Analyzes the Tic-Tac-Toe board state to determine the outcome or validity.
     * 
     * @param board The 3x3 game board
     * @return A string describing the game state ("illegal", "the first player won", etc.)
     */
    private static String analyzeGameState(char[][] board) {
        int xCount = 0;
        int oCount = 0;

        // 1. Count moves and validate basic board content
        for (int i = 0; i < BOARD_SIZE; i++) {
            for (int j = 0; j < BOARD_SIZE; j++) {
                char cell = board[i][j];
                if (cell == PLAYER_X) {
                    xCount++;
                } else if (cell == PLAYER_O) {
                    oCount++;
                }
            }
        }

        // 2. Validate move counts (Turn order logic)
        // X goes first. So X count must be equal to O count or exactly one more.
        // If oCount > xCount, it's impossible for X to have started.
        // If xCount > oCount + 1, X made two moves in a row.
        if (xCount < oCount || xCount > oCount + 1) {
            return "illegal";
        }

        // 3. Check for winning conditions
        boolean xWon = checkWinCondition(board, PLAYER_X);
        boolean oWon = checkWinCondition(board, PLAYER_O);

        // 4. Validate win conditions against move counts
        // Both players cannot win simultaneously
        if (xWon && oWon) {
            return "illegal";
        }

        // If X won, X must have made the last move (xCount == oCount + 1)
        // If xCount == oCount, it means O just moved (or board empty), so X couldn't have just won.
        if (xWon && xCount == oCount) {
            return "illegal";
        }

        // If O won, O must have made the last move (xCount == oCount)
        // If xCount > oCount, it means X just moved, so O couldn't have just won.
        if (oWon && xCount > oCount) {
            return "illegal";
        }

        // 5. Determine the result string
        if (xWon) {
            return "the first player won";
        }
        if (oWon) {
            return "the second player won";
        }

        // Check for draw (Board full)
        if (xCount + oCount == BOARD_SIZE * BOARD_SIZE) {
            return "draw";
        }

        // Determine whose turn it is
        // If xCount > oCount, X just played, so it's O's turn (second)
        // If xCount == oCount, X hasn't played yet (relative to O's last move), so it's X's turn (first)
        if (xCount > oCount) {
            return "second";
        } else {
            return "first";
        }
    }

    /**
     * Checks if a specific player has won on the board.
     * 
     * @param board The game board
     * @param player The character representing the player ('X' or '0')
     * @return true if the player has a winning line, false otherwise
     */
    private static boolean checkWinCondition(char[][] board, char player) {
        // Check Rows
        for (int i = 0; i < BOARD_SIZE; i++) {
            if (board[i][0] == player && board[i][1] == player && board[i][2] == player) {
                return true;
            }
        }

        // Check Columns
        for (int j = 0; j < BOARD_SIZE; j++) {
            if (board[0][j] == player && board[1][j] == player && board[2][j] == player) {
                return true;
            }
        }

        // Check Main Diagonal (Top-Left to Bottom-Right)
        if (board[0][0] == player && board[1][1] == player && board[2][2] == player) {
            return true;
        }

        // Check Anti-Diagonal (Bottom-Left to Top-Right)
        if (board[2][0] == player && board[1][1] == player && board[0][2] == player) {
            return true;
        }

        return false;
    }
}

