        int oCount = 0;
        for (char[] row : board) {
            for (char cell : row) {
                if (cell == PLAYER_X) {
                    xCount++;
                } else if (cell == PLAYER_O) {
                    oCount++;
                }
            }
        }
        return new int[]{xCount, oCount};
    }

    /**
     * Checks if a specific player has won the game.
     */
    private boolean hasWon(char player) {
        // Check rows
        for (int i = 0; i < BOARD_SIZE; i++) {
            if (board[i][0] == player && board[i][1] == player && board[i][2] == player) {
                return true;
            }
        }
        // Check columns
        for (int i = 0; i < BOARD_SIZE; i++) {
            if (board[0][i] == player && board[1][i] == player && board[2][i] == player) {
                return true;
            }
        }
        // Check diagonals
        if (board[1][1] == player) {
            if ((board[0][0] == player && board[2][2] == player) ||
                (board[0][2] == player && board[2][0] == player)) {
                return true;
            }
        }
        return false;
    }

    /**
     * Validates if the current board state follows Tic-Tac-Toe rules.
     */
    private boolean isLegal() {
        int[] counts = countPlayers();
        int xCount = counts[0];
        int oCount = counts[1];

        // Rule 1: Turn order must be maintained (X goes first, difference is 0 or 1)
        if (xCount != oCount && xCount != oCount + 1) {
            return false;
        }
        // Rule 2: If X won, X must have made one more move than O
        if (hasWon(PLAYER_X) && xCount == oCount) {
            return false;
        }
        // Rule 3: If O won, counts must be equal
        if (hasWon(PLAYER_O) && xCount != oCount + 1) {
            return false;
        }
        // Rule 4: Both players cannot win simultaneously
        if (hasWon(PLAYER_X) && hasWon(PLAYER_O)) {
            return false;
        }

        return true;
    }

