import java.util.Scanner;

public class TicTacToe {
    // Constants to replace magic numbers and characters
    private static final int BOARD_SIZE = 3;
    private static final char PLAYER_X = 'X';
    private static final char PLAYER_O = '0'; // Note: Using '0' (zero) as per original code
    private static final char EMPTY_CELL = '.';

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        try {
            TicTacToe game = new TicTacToe();
            game.evaluateGame(scanner);
        } finally {
            scanner.close();
        }
    }

    /**
     * Reads the board from input and evaluates the game state.
     */
    private void evaluateGame(Scanner scanner) {
        char[][] grid = new char[BOARD_SIZE][BOARD_SIZE];
        int xCount = 0;
        int oCount = 0;
        boolean hasEmpty = false;

        // 1. Read Input and Count Moves
        for (int i = 0; i < BOARD_SIZE; i++) {
            if (!scanner.hasNextLine()) break;
            String line = scanner.nextLine();

            // Ensure we don't go out of bounds if line is short
            for (int j = 0; j < BOARD_SIZE; j++) {
                if (j < line.length()) {
                    char c = line.charAt(j);
                    grid[i][j] = c;
                    if (c == PLAYER_X) {
                        xCount++;
                    } else if (c == PLAYER_O) {
                        oCount++;
                    } else if (c == EMPTY_CELL) {
                        hasEmpty = true;
                    }
                } else {
                    // Pad with empty if line is short (defensive coding)
                    grid[i][j] = EMPTY_CELL;
                }
            }
        }

        // 2. Validate Move Counts
        // In a valid game, X (first player) goes first.
        // So, count(X) must be equal to count(O) or count(X) = count(O) + 1.
        if (xCount != oCount && xCount != oCount + 1) {
            System.out.println("illegal");
            return;
        }

        // 3. Check for Winners
        boolean xWins = checkWin(grid, PLAYER_X);
        boolean oWins = checkWin(grid, PLAYER_O);

        // 4. Determine Game Result
        if (xWins && oWins) {
            // Both players cannot win in a valid game state
            System.out.println("illegal");
        } else if (xWins) {
            if (xCount == oCount + 1) {
                System.out.println("the first player won");
            } else {
                System.out.println("illegal");
            }
        } else if (oWins) {
            if (xCount == oCount) {
                System.out.println("the second player won");
            } else {
                System.out.println("illegal");
            }
        } else {
            // No winner
            if (hasEmpty) {
                if (xCount == oCount) {
                    System.out.println("first");
                } else {
                    System.out.println("second");
                }
            } else {
                System.out.println("draw");
            }
        }
    }

    /**
     * Checks if a specific player has won.
     * Checks rows, columns, and diagonals.
     */
    private boolean checkWin(char[][] grid, char player) {
        // Check Rows
        for (int i = 0; i < BOARD_SIZE; i++) {
            if (grid[i][0] == player && grid[i][1] == player && grid[i][2] == player) {
                return true;
            }
        }

        // Check Columns
        for (int i = 0; i < BOARD_SIZE; i++) {
            if (grid[0][i] == player && grid[1][i] == player && grid[2][i] == player) {
                return true;
            }
        }

        // Check Diagonals
        if (grid[0][0] == player && grid[1][1] == player && grid[2][2] == player) {
            return true;
        }
        if (grid[0][2] == player && grid[1][1] == player && grid[2][0] == player) {
            return true;
        }

        return false;
    }
}

import java.util.Scanner;

public class CodeForces {
    // Constants for better maintainability and readability
    private static final int BOARD_SIZE = 3;
    private static final char PLAYER_X = 'X';
    private static final char PLAYER_O = '0'; // Note: Input uses '0' (zero), not 'O'
    private static final int TOTAL_CELLS = BOARD_SIZE * BOARD_SIZE;

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        char[][] board = new char[BOARD_SIZE][BOARD_SIZE];

        int xCount = 0;
        int oCount = 0;

        // 1. Read Input and Count Moves
        // We read the board state and count the number of moves for each player.
        for (int i = 0; i < BOARD_SIZE; i++) {
            if (scanner.hasNextLine()) {
                String line = scanner.nextLine();
                // Ensure we don't go out of bounds if the input line is short
                for (int j = 0; j < BOARD_SIZE && j < line.length(); j++) {
                    char c = line.charAt(j);
                    board[i][j] = c;
                    if (c == PLAYER_X) {
                        xCount++;
                    } else if (c == PLAYER_O) {
                        oCount++;
                    }
                }
            }
        }

        // 2. Validate Move Counts
        // In Tic-Tac-Toe, X goes first. Therefore, the count of X must be equal 
        // to the count of O, or exactly one greater.
        if (xCount != oCount && xCount != oCount + 1) {
            System.out.println("illegal");
            return;
        }

        // 3. Check for Winning Conditions
        // Determine if either player has achieved a winning state.
        boolean xWins = hasWon(board, PLAYER_X);
        boolean oWins = hasWon(board, PLAYER_O);

        // 4. Validate Win States
        // A valid game state cannot have both players winning.
        if (xWins && oWins) {
            System.out.println("illegal");
            return;
        }

        // If X wins, X must have made the last move, meaning xCount == oCount + 1.
        if (xWins && xCount != oCount + 1) {
            System.out.println("illegal");
            return;
        }

        // If O wins, counts must be equal (O made the last move).
        if (oWins && xCount != oCount) {
            System.out.println("illegal");
            return;
        }

        // 5. Determine Result
        if (xWins) {
            System.out.println("the first player won");
        } else if (oWins) {
            System.out.println("the second player won");
        } else if (xCount + oCount == TOTAL_CELLS) {
            // If the board is full and no one won, it's a draw.
            System.out.println("draw");
        } else if (xCount == oCount) {
            // If counts are equal, it is X's turn (First player's turn).
            System.out.println("first");
        } else {
            // If xCount == oCount + 1, it is O's turn (Second player's turn).
            System.out.println("second");
        }

        scanner.close();
    }

    /**
     * Checks if a specific player has won the game.
     * @param board The game board
     * @param player The character representing the player ('X' or '0')
     * @return true if the player has 3 in a row, column, or diagonal
     */
    private static boolean hasWon(char[][] board, char player) {
        // Check Rows
        for (int i = 0; i < BOARD_SIZE; i++) {
            if (board[i][0] == player && board[i][1] == player && board[i][2] == player) {
                return true;
            }
        }

        // Check Columns
        for (int j = 0; j < BOARD_SIZE; j++) {
            if (board[0][j] == player && board[1][j] == player && board[2][j] == player) {
                return true;
            }
        }

        // Check Diagonal (Top-Left to Bottom-Right)
        if (board[0][0] == player && board[1][1] == player && board[2][2] == player) {
            return true;
        }

        // Check Diagonal (Top-Right to Bottom-Left)
        if (board[0][2] == player && board[1][1] == player && board[2][0] == player) {
            return true;
        }

        return false;
    }
}

import java.util.Scanner;

/**
 * A validator for Tic-Tac-Toe game states.
 * This program reads a 3x3 grid and determines if the state is legal,
 * identifies the winner, or predicts the next move.
 */
public class TicTacToeValidator {

    // Constants to define board dimensions and players
    private static final int BOARD_SIZE = 3;
    private static final char PLAYER_X = 'X';
    private static final char PLAYER_O = '0'; // Note: Using '0' (zero) as per original logic

    // Output messages (preserved from original to ensure compatibility)
    private static final String MSG_ILLEGAL = "illegal";
    private static final String MSG_X_WON = "the first player won";
    private static final String MSG_O_WON = "the second player won "; // Note: Trailing space preserved
    private static final String MSG_DRAW = "draw";
    private static final String MSG_TURN_SECOND = "second";
    private static final String MSG_TURN_FIRST = "first";

    private String[] board;

    /**
     * Constructor to initialize the game board.
     *
     * @param initialBoard The 3x3 grid representing the game state.
     */
    public TicTacToeValidator(String[] initialBoard) {
        this.board = initialBoard;
    }

    /**
     * Counts the number of occurrences of a specific player's mark on the board.
     *
     * @param player The character representing the player ('X' or '0').
     * @return The count of the player's marks.
     */
    private int countMoves(char player) {
        int count = 0;
        for (String row : board) {
            for (int i = 0; i < row.length(); i++) {
                if (row.charAt(i) == player) {
                    count++;
                }
            }
        }
        return count;
    }

    /**
     * Checks if a specific player has won the game.
     * A win is defined as 3 marks in a row, column, or diagonal.
     *
     * @param player The character representing the player to check.
     * @return true if the player has won, false otherwise.
     */
    private boolean hasWon(char player) {
        // Check Rows
        for (int r = 0; r < BOARD_SIZE; r++) {
            if (board[r].charAt(0) == player &&
                board[r].charAt(1) == player &&
                board[r].charAt(2) == player) {
                return true;
            }
        }

        // Check Columns
        for (int c = 0; c < BOARD_SIZE; c++) {
            if (board[0].charAt(c) == player &&
                board[1].charAt(c) == player &&
                board[2].charAt(c) == player) {
                return true;
            }
        }

        // Check Diagonals
        // Main Diagonal (Top-Left to Bottom-Right)
        if (board[0].charAt(0) == player &&
            board[1].charAt(1) == player &&
            board[2].charAt(2) == player) {
            return true;
        }

        // Anti-Diagonal (Top-Right to Bottom-Left)
        if (board[0].charAt(2) == player &&
            board[1].charAt(1) == player &&
            board[2].charAt(0) == player) {
            return true;
        }

        return false;
    }

    public static void main(String[] args) {
        // Use try-with-resources to ensure Scanner is closed properly
        try (Scanner in = new Scanner(System.in)) {
            String[] inputGrid = new String[BOARD_SIZE];

            // Read the 3x3 grid
            for (int i = 0; i < BOARD_SIZE; i++) {
                if (in.hasNext()) {
                    inputGrid[i] = in.next();
                }
            }

            // Instantiate the validator
            TicTacToeValidator validator = new TicTacToeValidator(inputGrid);

            // Run the validation logic
            validator.validateGameState();

        } catch (Exception e) {
            // In a real application, handle exceptions properly. 
            // For this script, we assume valid input format based on original code.
            System.err.println("Error reading input: " + e.getMessage());
        }
    }

    /**
     * Contains the logic to validate the game state and print the result.
     */
    private void validateGameState() {
        int xCount = countMoves(PLAYER_X);
        int oCount = countMoves(PLAYER_O);

        boolean isLegal = true;

        // Rule 1: Turn counts must be valid.
        // X goes first, so X count must equal O count or be exactly one greater.
        if (xCount != oCount && xCount - oCount != 1) {
            isLegal = false;
        }

        boolean xWon = hasWon(PLAYER_X);
        boolean oWon = hasWon(PLAYER_O);

        // Rule 2: Both players cannot win simultaneously.
        if (xWon && oWon) {
            isLegal = false;
        }

        // Rule 3: Win condition consistency.
        // If X wins, X must have made the last move (xCount == oCount + 1).
        // If O wins, O must have made the last move (xCount == oCount).
        if ((xWon && xCount == oCount) || (oWon && xCount > oCount)) {
            isLegal = false;
        }

        // Determine Output
        if (!isLegal) {
            System.out.println(MSG_ILLEGAL);
        } else if (xWon) {
            System.out.println(MSG_X_WON);
        } else if (oWon) {
            System.out.println(MSG_O_WON);
        } else if (xCount + oCount == BOARD_SIZE * BOARD_SIZE) {
            System.out.println(MSG_DRAW);
        } else if (xCount - oCount == 1) {
            // It is O's turn (Second player)
            System.out.println(MSG_TURN_SECOND);
        } else if (xCount == oCount) {
            // It is X's turn (First player)
            System.out.println(MSG_TURN_FIRST);
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;

/**
 * Refactored Tic-Tac-Toe Board Analyzer.
 * 
 * Improvements made:
 * 1. Encapsulation: Removed static fields and global state; uses instance variables.
 * 2. Readability: Replaced magic numbers (88, 48, 46, 50, 15, etc.) with named constants.
 * 3. Resource Management: Used try-with-resources for automatic stream closure.
 * 4. Logic Simplification: Removed unnecessary score calculations and the 'wins' array.
 *    Win checking is now performed by direct character comparison.
 * 5. Naming: Used descriptive variable and method names (e.g., 'xCount' instead of 'numX').
 * 6. Robustness: Added bounds checking for input reading.
 */
public class TicTacToeAnalyzer {

    // Constants
    private static final int BOARD_SIZE = 3;
    private static final char PLAYER_X = 'X';
    private static final char PLAYER_O = '0'; // ASCII 48
    private static final char EMPTY = '.';     // ASCII 46

    // Scoring constants (preserved from original logic for reference)
    private static final int SCORE_X = 50;
    private static final int SCORE_O = 15;

    // State
    private char[][] board;
    private int xCount;
    private int oCount;
    private boolean xWon;
    private boolean oWon;

    public static void main(String[] args) throws IOException {
        // Use try-with-resources to ensure the reader is closed automatically
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(System.in))) {
            TicTacToeAnalyzer analyzer = new TicTacToeAnalyzer();

            // 1. Parse Input
            analyzer.parseBoard(reader);

            // 2. Analyze Board State
            analyzer.analyze();

            // 3. Output Result
            System.out.println(analyzer.getStatus());
        }
    }

    private void parseBoard(BufferedReader reader) throws IOException {
        board = new char[BOARD_SIZE][BOARD_SIZE];
        xCount = 0;
        oCount = 0;

        for (int i = 0; i < BOARD_SIZE; i++) {
            String line = reader.readLine();
            // Handle unexpected end of input
            if (line == null) {
                break;
            }

            for (int j = 0; j < BOARD_SIZE; j++) {
                // Safe access to character, defaulting to EMPTY if line is short
                char c = (j < line.length()) ? line.charAt(j) : EMPTY;
                board[i][j] = c;

                if (c == PLAYER_X) {
                    xCount++;
                } else if (c == PLAYER_O) {
                    oCount++;
                }
            }
        }
    }

    private void analyze() {
        checkForWins();
    }

    private void checkForWins() {
        // Check Rows
        for (int i = 0; i < BOARD_SIZE; i++) {
            if (checkLine(board[i][0], board[i][1], board[i][2])) return;
        }
        // Check Columns
        for (int j = 0; j < BOARD_SIZE; j++) {
            if (checkLine(board[0][j], board[1][j], board[2][j])) return;
        }
        // Check Diagonals
        if (checkLine(board[0][0], board[1][1], board[2][2])) return;
        if (checkLine(board[0][2], board[1][1], board[2][0])) return;
    }

    private boolean checkLine(char a, char b, char c) {
        if (a == PLAYER_X && b == PLAYER_X && c == PLAYER_X) {
            xWon = true;
            return true;
        }
        if (a == PLAYER_O && b == PLAYER_O && c == PLAYER_O) {
            oWon = true;
            return true;
        }
        return false;
    }

    private boolean isIllegal() {
        int diff = xCount - oCount;

        // Rule 1: X must have played same number of times as O, or one more time (X starts)
        if (diff != 0 && diff != 1) {
            return true;
        }

        // Rule 2: Both players cannot win simultaneously
        if (xWon && oWon) {
            return true;
        }

        // Rule 3: If X won, X must have played the last move (diff == 1)
        if (xWon && diff != 1) {
            return true;
        }

        // Rule 4: If O won, O must have played the last move (diff == 0)
        if (oWon && diff != 0) {
            return true;
        }

        return false;
    }

    private boolean isDraw() {
        // A draw occurs if the board is full (9 moves made).
        // In the original code, this was checked via total score == 310.
        // 5 Xs (250) + 4 Os (60) = 310. This is equivalent to a full board.
        return (xCount + oCount == BOARD_SIZE * BOARD_SIZE);
    }

    private String getStatus() {
        if (isIllegal()) {
            return "illegal";
        }
        if (xWon) {
            return "the first player won";
        }
        if (oWon) {
            return "the second player won";
        }
        if (isDraw()) {
            return "draw";
        }
        return getTurn();
    }

    private String getTurn() {
        if (xCount == oCount) {
            return "first";
        }
        return "second";
    }
}

import java.util.Scanner;

public class Prob003C {
    private static final int BOARD_SIZE = 3;
    private static final char PLAYER_X = 'X';
    private static final char PLAYER_O = 'O'; // Fixed: Original used '0' (zero) instead of 'O' (letter)

    public static void main(String[] args) {
        // Use try-with-resources to ensure the Scanner is properly closed
        try (Scanner scanner = new Scanner(System.in)) {
            char[][] board = new char[BOARD_SIZE][BOARD_SIZE];
            for (int i = 0; i < BOARD_SIZE; i++) {
                board[i] = scanner.next().toCharArray();
            }

            int countX = countPlayer(board, PLAYER_X);
            int countO = countPlayer(board, PLAYER_O);

            boolean xWin = hasWon(board, PLAYER_X);
            boolean oWin = hasWon(board, PLAYER_O);

            System.out.println(determineGameState(countX, countO, xWin, oWin));
        }
    }

    /**
     * Counts the number of moves made by a specific player.
     */
    private static int countPlayer(char[][] board, char player) {
        int count = 0;
        for (char[] row : board) {
            for (char cell : row) {
                if (cell == player) {
                    count++;
                }
            }
        }
        return count;
    }

    /**
     * Checks if a player has won by completing a row, column, or diagonal.
     */
    private static boolean hasWon(char[][] board, char player) {
        // Check rows and columns
        for (int i = 0; i < BOARD_SIZE; i++) {
            boolean rowWin = true;
            boolean colWin = true;
            for (int j = 0; j < BOARD_SIZE; j++) {
                if (board[i][j] != player) rowWin = false;
                if (board[j][i] != player) colWin = false;
            }
            if (rowWin || colWin) {
                return true;
            }
        }

        // Check diagonals
        boolean diag1Win = true;
        boolean diag2Win = true;
        for (int i = 0; i < BOARD_SIZE; i++) {
            if (board[i][i] != player) diag1Win = false;
            if (board[i][BOARD_SIZE - 1 - i] != player) diag2Win = false;
        }

        return diag1Win || diag2Win;
    }

    /**
     * Determines the current state of the game based on move counts and win conditions.
     */
    private static String determineGameState(int countX, int countO, boolean xWin, boolean oWin) {
        // 1. Validate move count parity (X always starts, so X must equal O or O+1)
        if (countX != countO && countX != countO + 1) {
            return "illegal";
        }

        // 2. Both players cannot win simultaneously
        if (xWin && oWin) {
            return "illegal";
        }

        // 3. The winning player must have made the last move
        if (xWin && countX != countO + 1) {
            return "illegal";
        }
        if (oWin && countX != countO) {
            return "illegal";
        }

        // 4. Determine valid game states
        if (xWin) {
            return "the first player won";
        }
        if (oWin) {
            return "the second player won";
        }
        if (countX + countO == BOARD_SIZE * BOARD_SIZE) {
            return "draw";
        }
        if (countX == countO) {
            return "first";
        }
        return "second";
    }
}

import java.util.Scanner;
import java.util.HashSet;
import java.util.Set;

public class TicTacToe {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        char[][] board = new char[3][3];
        int[] moveCounts = new int[2]; // Index 0: 'X', Index 1: '0'
        boolean isBoardFull = true;

        // Read the board from input
        for (int row = 0; row < 3; row++) {
            if (scanner.hasNextLine()) {
                String line = scanner.nextLine();
                for (int col = 0; col < 3; col++) {
                    // Ensure we don't access out of bounds if line is short
                    if (col < line.length()) {
                        char c = line.charAt(col);
                        board[row][col] = c;

                        if (c == '.') {
                            isBoardFull = false;
                        }
                        if (c == 'X') {
                            moveCounts[0]++;
                        }
                        // Note: Original code uses digit '0' for the second player
                        if (c == '0') {
                            moveCounts[1]++;
                        }
                    } else {
                        // Treat missing characters as empty spaces
                        board[row][col] = '.';
                        isBoardFull = false;
                    }
                }
            }
        }

        // Evaluate the game state
        String winnerStatus = decideWinner(board, moveCounts);
        String turnStatus = decideTurn(moveCounts);

        // Output the result based on original logic
        if (turnStatus.equals("illegal") || winnerStatus.equals("illegal")) {
            System.out.println("illegal");
        } else if (winnerStatus.equals("draw") && isBoardFull) {
            System.out.println("draw");
        } else if (winnerStatus.equals("draw") && !isBoardFull) {
            System.out.println(turnStatus);
        } else {
            System.out.println(winnerStatus);
        }

        scanner.close();
    }

    /**
     * Determines if there is a winner or if the board state is illegal.
     * Returns "illegal", "the first player won", "the second player won", or "draw".
     */
    public static String decideWinner(char[][] board, int[] moveCounts) {
        Set<Character> winners = new HashSet<>();

        // Check Rows
        for (int row = 0; row < 3; row++) {
            if (board[row][0] == board[row][1] && board[row][1] == board[row][2]) {
                winners.add(board[row][0]);
            }
        }

        // Check Columns
        // Fixed: Original code had a duplicate check for Column 0.
        for (int col = 0; col < 3; col++) {
            if (board[0][col] == board[1][col] && board[1][col] == board[2][col]) {
                winners.add(board[0][col]);
            }
        }

        // Check Diagonals
        if (board[0][0] == board[1][1] && board[1][1] == board[2][2]) {
            winners.add(board[0][0]);
        }
        if (board[0][2] == board[1][1] && board[1][1] == board[2][0]) {
            winners.add(board[0][2]);
        }

        // Remove empty spaces from potential winners
        winners.remove('.');

        // If multiple different players won, the state is illegal
        if (winners.size() > 1) {
            return "illegal";
        }

        // Check validity for 'X' win
        if (winners.contains('X')) {
            // X moves first, so X count must be exactly 1 greater than O count
            if (moveCounts[0] != moveCounts[1] + 1) {
                return "illegal";
            }
            return "the first player won";
        }

        // Check validity for '0' win (Original code uses digit '0')
        if (winners.contains('0')) {
            // O moves second, so counts must be equal
            if (moveCounts[0] != moveCounts[1]) {
                return "illegal";
            }
            return "the second player won";
        }

        return "draw";
    }

    /**
     * Determines whose turn it is next or if the move counts are illegal.
     */
    public static String decideTurn(int[] moveCounts) {
        // X count cannot exceed O count by more than 1
        if (moveCounts[0] - moveCounts[1] > 1) {
            return "illegal";
        }
        // O count cannot exceed X count
        if (moveCounts[1] - moveCounts[0] > 0) {
            return "illegal";
        }

        // If X has made more moves, it is O's turn (second player)
        if (moveCounts[0] > moveCounts[1]) {
            return "second";
        }

        // Otherwise, it is X's turn (first player)
        return "first";
    }
}

