import java.util.StringTokenizer;

/**
 * Solves the "Fox and Two Dots" cycle detection problem on a 2D grid.
 * Refactored for maintainability, readability, and adherence to Java best practices.
 */
public class FoxAndTwoDots {
    // Direction vectors: Down, Up, Right, Left
    private static final int[] DX = {1, -1, 0, 0};
    private static final int[] DY = {0, 0, 1, -1};

    private int rows;
    private int cols;
    private char[][] grid;
    private boolean[][] visited;

    public static void main(String[] args) {
        FastReader reader = new FastReader();
        PrintWriter out = new PrintWriter(System.out);

        try {
            FoxAndTwoDots solver = new FoxAndTwoDots();
            solver.readInput(reader);
            boolean hasCycle = solver.hasCycle();
            out.println(hasCycle ? "Yes" : "No");
        } catch (Exception e) {
            System.err.println("Error processing input: " + e.getMessage());
        } finally {
            out.flush();
        }
    }

    /**
     * Reads grid dimensions and the grid itself from the input stream.
     */
    private void readInput(FastReader reader) {
        this.rows = reader.nextInt();
        this.cols = reader.nextInt();
        this.grid = new char[rows][cols];
        this.visited = new boolean[rows][cols];

        for (int i = 0; i < rows; i++) {
            String line = reader.next();
            if (line != null) {
                grid[i] = line.toCharArray();
            }
        }
    }

    /**
     * Checks if the grid contains a cycle of identical characters.
     */
    private boolean hasCycle() {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (!visited[i][j]) {
                    if (dfs(i, j, -1, -1, grid[i][j])) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Performs depth-first search to detect cycles.
     *
     * @param x            Current row index
     * @param y            Current column index
     * @param parentX      Row index of the previous cell (to avoid immediate backtracking)
     * @param parentY      Column index of the previous cell
     * @param targetChar   Character value that must match for path continuation
     * @return true if a cycle is found, false otherwise
     */
    private boolean dfs(int x, int y, int parentX, int parentY, char targetChar) {
        visited[x][y] = true;

        for (int i = 0; i < 4; i++) {
            int nx = x + DX[i];
            int ny = y + DY[i];

            if (isValid(nx, ny) && grid[nx][ny] == targetChar) {
                if (visited[nx][ny]) {
                    // If neighbor is already visited, it forms a cycle unless it's the immediate parent
                    if (!(nx == parentX && ny == parentY)) {
                        return true;
                    }
                } else {
                    // Continue DFS into unvisited neighbors
                    if (dfs(nx, ny, x, y, targetChar)) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Checks if the given coordinates are within grid bounds.
     */
    private boolean isValid(int x, int y) {
        return x >= 0 && x < rows && y >= 0 && y < cols;
    }

    /**
     * Fast input reader using BufferedReader and StringTokenizer.
     * Replaces the verbose custom byte-parser with standard, maintainable Java I/O.
     */
    static class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input", e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            String token = next();
            return token == null ? 0 : Integer.parseInt(token);
        }
    }
}

import java.util.Scanner;

public class FoxAndTwoDots {

    // Direction arrays for moving Up, Down, Left, Right
    private static final int[] DR = {-1, 1, 0, 0};
    private static final int[] DC = {0, 0, -1, 1};

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        // Read dimensions
        if (!scanner.hasNextInt()) {
            return;
        }
        int rows = scanner.nextInt();
        int cols = scanner.nextInt();

        // Read the grid
        char[][] grid = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            // Using next() is safer than nextLine() for tokenizing input
            if (scanner.hasNext()) {
                String line = scanner.next();
                grid[i] = line.toCharArray();
            }
        }
        scanner.close();

        // Visited array to keep track of cells visited in the current traversal
        boolean[][] visited = new boolean[rows][cols];
        boolean cycleFound = false;

        // Iterate over every cell to ensure we check all components of the graph
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                // If cell is not visited, start a DFS from here
                if (!visited[r][c]) {
                    // Start DFS. Parent is (-1, -1) as there is no parent for the starting node.
                    if (hasCycle(r, c, -1, -1, grid[r][c], visited, grid)) {
                        cycleFound = true;
                        break;
                    }
                }
            }
            if (cycleFound) {
                break;
            }
        }

        System.out.println(cycleFound ? "Yes" : "No");
    }

    /**
     * Performs Depth First Search to detect if a cycle exists.
     * 
     * @param r Current row index
     * @param c Current column index
     * @param parentR Row index of the previous cell in the path
     * @param parentC Column index of the previous cell in the path
     * @param color The character type we are tracing (e.g., 'a', 'b')
     * @param visited 2D boolean array tracking visited cells
     * @param grid The character grid representing the board
     * @return true if a cycle is detected, false otherwise
     */
    private static boolean hasCycle(int r, int c, int parentR, int parentC, char color, 
                                    boolean[][] visited, char[][] grid) {
        visited[r][c] = true;

        // Check all 4 adjacent neighbors
        for (int i = 0; i < 4; i++) {
            int nr = r + DR[i];
            int nc = c + DC[i];

            // Check boundaries
            if (nr >= 0 && nr < grid.length && nc >= 0 && nc < grid[0].length) {
                // Check if neighbor has the same character
                if (grid[nr][nc] == color) {
                    if (!visited[nr][nc]) {
                        // If not visited, continue DFS
                        if (hasCycle(nr, nc, r, c, color, visited, grid)) {
                            return true;
                        }
                    } else {
                        // If visited, check if it is the immediate parent.
                        // If it is visited and NOT the parent, a cycle is found.
                        if (nr != parentR || nc != parentC) {
                            return true;
                        }
                    }
                }
            }
        }
        return false;
    }
}

