import java.util.Scanner;

/**
 * A utility class to detect cycles in a grid of characters.
 * A cycle is defined as a path of identical characters that loops back on itself.
 */
public class CycleDetector {

    // Directions array for moving Right, Left, Down, and Up in the grid
    private static final int[][] DIRECTIONS = {
        {0, 1},  // Right
        {0, -1}, // Left
        {1, 0},  // Down
        {-1, 0}  // Up
    };

    public static void main(String[] args) {
        // Use try-with-resources to ensure the Scanner is closed automatically
        try (Scanner scanner = new Scanner(System.in)) {
            // Check if input exists
            if (!scanner.hasNextInt()) {
                return;
            }

            int n = scanner.nextInt();
            int m = scanner.nextInt();
            scanner.nextLine(); // Consume the newline character after reading integers

            char[][] grid = new char[n][m];

            // Read the grid rows
            for (int i = 0; i < n; i++) {
                String row = scanner.nextLine();
                for (int j = 0; j < m && j < row.length(); j++) {
                    grid[i][j] = row.charAt(j);
                }
            }

            // Determine if a cycle exists and print the result
            if (hasCycle(grid)) {
                System.out.println("Yes");
            } else {
                System.out.println("No");
            }
        }
    }

    /**
     * Iterates through the grid to find a cycle using Depth First Search (DFS).
     *
     * @param grid The character grid to search.
     * @return true if a cycle is found, false otherwise.
     */
    private static boolean hasCycle(char[][] grid) {
        int rows = grid.length;
        int cols = grid[0].length;
        boolean[][] visited = new boolean[rows][cols];

        // Iterate over every cell in the grid
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                // If the cell hasn't been visited yet, start a DFS from it
                if (!visited[i][j] && dfs(grid, visited, i, j, -1, -1)) {
                    return true;
                }
            }
        }
        return false;
    }

    /**
     * Performs a recursive DFS to detect cycles.
     *
     * @param grid The character grid.
     * @param visited 2D array tracking visited cells.
     * @param r Current row index.
     * @param c Current column index.
     * @param prevR Previous row index (to prevent moving back to the parent node).
     * @param prevC Previous column index (to prevent moving back to the parent node).
     * @return true if a cycle is detected, false otherwise.
     */
    private static boolean dfs(char[][] grid, boolean[][] visited, int r, int c, int prevR, int prevC) {
        visited[r][c] = true;

        // Explore all 4 possible directions
        for (int[] dir : DIRECTIONS) {
            int nextR = r + dir[0];
            int nextC = c + dir[1];

            // Check if the neighbor is within grid boundaries
            if (nextR >= 0 && nextR < grid.length && nextC >= 0 && nextC < grid[0].length) {

                // Check if the neighbor has the same character as the current cell
                if (grid[nextR][nextC] == grid[r][c]) {

                    // If the neighbor is already visited and it is not the immediate parent,
                    // we have found a cycle (a back-edge).
                    if (visited[nextR][nextC] && !(nextR == prevR && nextC == prevC)) {
                        return true;
                    }

                    // If the neighbor is not visited, continue the DFS traversal
                    if (!visited[nextR][nextC]) {
                        if (dfs(grid, visited, nextR, nextC, r, c)) {
                            return true;
                        }
                    }
                }
            }
        }
        return false;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

/**
 * Refactored Grid Cycle Detector.
 * 
 * Improvements made:
 * 1. Class Naming: Renamed 'main' to 'GridCycleDetector' for clarity.
 * 2. Encapsulation: Moved static fields (grid, visited, directions) to instance fields.
 * 3. Readability: Used descriptive variable names (grid, visited, dx, dy).
 * 4. Logic Fix: Corrected the parent check in DFS (original had 'py == py' typo).
 * 5. Structure: Separated logic (detectCycle) from I/O (main).
 * 6. I/O: Improved FastScanner robustness and removed unused constructors.
 * 7. Constants: Made direction arrays static final constants.
 */
public class GridCycleDetector {

    // Grid to store the input characters
    // Dimensions are (n+2) x (m+2) to allow 1-based indexing with padding
    private char[][] grid;

    // Visited array to track DFS state: 
    // 0 = unvisited, 1 = visiting (in current recursion stack), 2 = visited (finished)
    private int[][] visited;

    // Direction vectors for moving Right, Left, Down, Up
    private static final int[] DX = {0, 0, 1, -1};
    private static final int[] DY = {1, -1, 0, 0};

    public static void main(String[] args) {
        // Initialize I/O
        FastScanner in = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            // Check for empty input
            if (!in.hasMoreTokens()) {
                return;
            }

            int n = in.nextInt();
            int m = in.nextInt();

            // Instantiate the solver with specific dimensions
            GridCycleDetector detector = new GridCycleDetector(n, m);

            // Read grid data
            detector.readInput(in);

            // Run detection logic
            boolean cycleFound = detector.detectCycle();

            // Output result
            if (cycleFound) {
                out.println("Yes");
            } else {
                out.println("No");
            }

        } catch (Exception e) {
            e.printStackTrace();
        } finally {
            out.flush();
        }
    }

    /**
     * Constructor initializes the grid with padding.
     */
    public GridCycleDetector(int n, int m) {
        // Padding of 1 on all sides (0 and n+1, 0 and m+1)
        // Default char value is '\u0000', which acts as a boundary
        this.grid = new char[n + 2][m + 2];
        this.visited = new int[n + 2][m + 2];
    }

    private void readInput(FastScanner in) throws IOException {
        // Read n rows
        for (int i = 1; i <= grid.length - 2; i++) {
            String line = in.next();
            if (line != null) {
                // Fill the row into the grid (1-based index for columns)
                for (int j = 0; j < line.length() && j < grid[0].length - 2; j++) {
                    grid[i][j + 1] = line.charAt(j);
                }
            }
        }
    }

    /**
     * Iterates over the grid to find an unvisited node and starts DFS.
     */
    private boolean detectCycle() {
        int rows = grid.length;
        int cols = grid[0].length;

        // Iterate through the valid data range (1 to n, 1 to m)
        for (int i = 1; i <= rows - 2; i++) {
            for (int j = 1; j <= cols - 2; j++) {
                // If node is unvisited, start a new DFS traversal
                if (visited[i][j] == 0) {
                    // Pass -1, -1 as parent coordinates since the start node has no parent
                    if (dfs(i, j, grid[i][j], -1, -1)) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Depth First Search to detect cycles of identical characters.
     *
     * @param x Current row
     * @param y Current column
     * @param targetChar The character sequence we are tracking
     * @param parentX Row coordinate of the parent node
     * @param parentY Column coordinate of the parent node
     * @return true if a cycle is found, false otherwise
     */
    private boolean dfs(int x, int y, char targetChar, int parentX, int parentY) {
        visited[x][y] = 1; // Mark as currently visiting (Gray node)

        for (int i = 0; i < 4; i++) {
            int nx = x + DX[i];
            int ny = y + DY[i];

            // Check if neighbor is the parent to avoid going back up the immediate edge
            if (nx == parentX && ny == parentY) {
                continue;
            }

            // Check if neighbor has the same character
            if (grid[nx][ny] == targetChar) {
                if (visited[nx][ny] == 1) {
                    // Found a neighbor that is currently being visited.
                    // Since it's not the parent, this indicates a cycle.
                    return true;
                } else if (visited[nx][ny] == 0) {
                    // Neighbor is unvisited, continue DFS
                    if (dfs(nx, ny, targetChar, x, y)) {
                        return true;
                    }
                }
            }
        }

        visited[x][y] = 2; // Mark as fully visited (Black node)
        return false;
    }

    /**
     * Helper class for fast input reading.
     */
    static class FastScanner {
        BufferedReader br;
        StringTokenizer st;

        public FastScanner(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        public boolean hasMoreTokens() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) {
                        return false;
                    }
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    return false;
                }
            }
            return true;
        }

        public String next() {
            if (hasMoreTokens()) {
                return st.nextToken();
            }
            return null;
        }

        public int nextInt() {
            String s = next();
            if (s == null) throw new RuntimeException("End of input");
            return Integer.parseInt(s);
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

public class Main {
    public static void main(String[] args) {
        FastScanner sc = new FastScanner();
        PrintWriter out = new PrintWriter(System.out);

        try {
            // Read grid dimensions
            int n = sc.nextInt();
            int m = sc.nextInt();

            // Initialize grid with integer values for correct arithmetic comparison
            int[][] grid = new int[n][m];
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    grid[i][j] = sc.nextInt();
                }
            }

            boolean found = false;
            // Use a single visited array with a token counter to avoid O(N*M) reallocation per start cell.
            // This maintains O(1) reset cost while preventing cycles and redundant work.
            int[][] visited = new int[n][m];
            int visitToken = 0;

            // Iterate through each cell to start a search if it's a positive value
            for (int i = 0; i < n && !found; i++) {
                for (int j = 0; j < m && !found; j++) {
                    if (grid[i][j] > 0) {
                        visitToken++;
                        found = dfs(grid, i, j, grid[i][j], -1, visited, visitToken);
                    }
                }
            }

            out.println(found ? "Yes" : "No");
        } catch (Exception e) {
            e.printStackTrace();
        } finally {
            out.flush();
            out.close();
        }
    }

    /**
     * Depth-First Search to find a path from a starting cell to its negative counterpart.
     *
     * @param grid        The 2D grid of integers
     * @param r           Current row
     * @param c           Current column
     * @param target      The value we are trying to match (and find its negative)
     * @param prevDir     The direction index we came from (0:Up, 1:Right, 2:Down, 3:Left). -1 for start.
     * @param visited     Visited tracking array using tokens to avoid reallocation
     * @param visitToken  Current visitation token to mark visited cells without clearing the array
     * @return true if a path to -target is found, false otherwise
     */
    private static boolean dfs(int[][] grid, int r, int c, int target, int prevDir, int[][] visited, int visitToken) {
        int n = grid.length;
        int m = grid[0].length;

        // Boundary check
        if (r < 0 || r >= n || c < 0 || c >= m) {
            return false;
        }
        // Visited check using token to prevent cycles and redundant work
        if (visited[r][c] == visitToken) {
            return false;
        }

        // Check if we found the negative counterpart of the starting value
        if (grid[r][c] == -target) {
            return true;
        }
        // Path must consist of cells with identical values to the target
        if (grid[r][c] != target) {
            return false;
        }

        // Mark current cell as visited for this traversal
        visited[r][c] = visitToken;

        // Direction vectors: Up, Right, Down, Left
        int[] dr = {-1, 0, 1, 0};
        int[] dc = {0, 1, 0, -1};

        // Explore all valid adjacent cells
        for (int dir = 0; dir < 4; dir++) {
            // Avoid backtracking to the cell we just came from
            if (dir == prevDir) continue;

            // Recursively search in the new direction.
            // (dir + 2) % 4 calculates the opposite direction to pass as prevDir for the next step.
            if (dfs(grid, r + dr[dir], c + dc[dir], target, (dir + 2) % 4, visited, visitToken)) {
                return true;
            }
        }
        return false;
    }

    /**
     * Fast input reader using BufferedReader and StringTokenizer.
     * Replaces the buggy mixed I/O approach of the original code and handles whitespace/newlines robustly.
     */
    static class FastScanner {
        private BufferedReader br;
        private StringTokenizer st;

        public FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        public String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            String s = next();
            if (s == null) throw new RuntimeException("Unexpected end of input");
            return Integer.parseInt(s);
        }
    }
}

