class GridCycleDetector {
    private static final int[] DI = {1, -1, 0, 0};
    private static final int[] DJ = {0, 0, 1, -1};

    public void solve(FastScanner in, PrintWriter out) {
        int n = in.nextInt();
        int m = in.nextInt();

        char[][] grid = new char[n][m];
        boolean[][] visited = new boolean[n][m];

        for (int i = 0; i < n; i++) {
            grid[i] = in.nextWord();
        }

        boolean hasCycle = false;
        for (int i = 0; i < n && !hasCycle; i++) {
            for (int j = 0; j < m && !hasCycle; j++) {
                if (!visited[i][j]) {
                    if (dfs(grid, visited, i, j, -1, -1)) {
                        hasCycle = true;
                    }
                }
            }
        }

        out.println(hasCycle ? "Yes" : "No");
    }

    private boolean dfs(char[][] grid, boolean[][] visited, int i, int j, int prevI, int prevJ) {
        if (visited[i][j]) {
            return true; // Cycle detected
        }

        visited[i][j] = true;
        for (int k = 0; k < 4; k++) {
            int newI = i + DI[k];
            int newJ = j + DJ[k];

            if (isValid(grid, newI, newJ)) {
                if (!(newI == prevI && newJ == prevJ) && grid[i][j] == grid[newI][newJ]) {
                    if (dfs(grid, visited, newI, newJ, i, j)) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    private boolean isValid(char[][] grid, int i, int j) {
        return i >= 0 && i < grid.length && j >= 0 && j < grid[0].length;
    }
}

class FastScanner {
    private final BufferedReader reader;
    private StringTokenizer tokenizer;

    public FastScanner(InputStream stream) {
        reader = new BufferedReader(new InputStreamReader(stream));
    }

    public String next() {
        while (tokenizer == null || !tokenizer.hasMoreTokens()) {
            try {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            } catch (IOException e) {
                throw new RuntimeException("Error reading input", e);
            }
        }
        return tokenizer.nextToken();
    }

    public int nextInt() {
        String token = next();
        if (token == null) {
            throw new RuntimeException("Unexpected end of input");
        }
        return Integer.parseInt(token);
    }

    public char[] nextWord() {
        String token = next();
        return token != null ? token.toCharArray() : new char[0];
    }
}

import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

public class Graph {
    private final List<List<Integer>> adj;
    private final int numVertices;

    /**
     * Constructs a graph with the specified number of vertices.
     *
     * @param numVertices the number of vertices in the graph
     */
    public Graph(int numVertices) {
        this.numVertices = numVertices;
        this.adj = new ArrayList<>(numVertices);
        for (int i = 0; i < numVertices; i++) {
            adj.add(new ArrayList<>());
        }
    }

    /**
     * Adds an undirected edge between two vertices.
     *
     * @param u the first vertex
     * @param v the second vertex
     */
    public void addEdge(int u, int v) {
        adj.get(u).add(v);
        adj.get(v).add(u);
    }

    /**
     * Checks if the graph contains a cycle.
     *
     * @return true if a cycle exists, false otherwise
     */
    public boolean hasCycle() {
        boolean[] visited = new boolean[numVertices];
        for (int i = 0; i < numVertices; i++) {
            if (!visited[i] && dfs(i, -1, visited)) {
                return true;
            }
        }
        return false;
    }

    /**
     * Depth-First Search to detect cycles in an undirected graph.
     *
     * @param u       current vertex
     * @param parent  parent vertex in the DFS tree
     * @param visited array tracking visited vertices
     * @return true if a cycle is detected, false otherwise
     */
    private boolean dfs(int u, int parent, boolean[] visited) {
        visited[u] = true;
        for (int v : adj.get(u)) {
            if (!visited[v]) {
                if (dfs(v, u, visited)) {
                    return true;
                }
            } else if (v != parent) {
                return true;
            }
        }
        return false;
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        if (!scanner.hasNextInt()) {
            return;
        }

        int n = scanner.nextInt();
        int m = scanner.nextInt();

        Graph graph = new Graph(n * m);
        char[] grid = new char[n * m];
        int idx = 0;

        for (int i = 0; i < n; i++) {
            String line = scanner.next();
            for (int j = 0; j < m; j++) {
                grid[idx] = line.charAt(j);

                // Check horizontal neighbor (left)
                if (j > 0 && grid[idx] == grid[idx - 1]) {
                    graph.addEdge(idx, idx - 1);
                }

                // Check vertical neighbor (top)
                if (i > 0 && grid[idx] == grid[idx - m]) {
                    graph.addEdge(idx, idx - m);
                }

                idx++;
            }
        }

        System.out.println(graph.hasCycle() ? "Yes" : "No");
        scanner.close();
    }
}

import java.io.*;
import java.util.*;

public class Round290B {

    public static void main(String[] args) {
        FastReader reader = new FastReader();
        PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out));

        try {
            int n = reader.nextInt();
            int m = reader.nextInt();
            char[][] grid = new char[n][m];

            for (int i = 0; i < n; i++) {
                grid[i] = reader.next().toCharArray();
            }

            Graph graph = buildGraph(n, m, grid);
            out.println(graph.hasCycle() ? "Yes" : "No");
        } catch (Exception e) {
            e.printStackTrace();
        } finally {
            out.flush();
            out.close();
        }
    }

    /**
     * Builds an undirected graph where edges connect adjacent cells 
     * with identical characters in the grid.
     */
    private static Graph buildGraph(int n, int m, char[][] grid) {
        int numVertices = n * m;
        Graph graph = new Graph(numVertices);

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                int currentIdx = i * m + j;

                // Connect to right neighbor if characters match
                if (j + 1 < m && grid[i][j] == grid[i][j + 1]) {
                    graph.addEdge(currentIdx, currentIdx + 1);
                }

                // Connect to bottom neighbor if characters match
                if (i + 1 < n && grid[i][j] == grid[i + 1][j]) {
                    graph.addEdge(currentIdx, currentIdx + m);
                }
            }
        }
        return graph;
    }

    /**
     * Represents an undirected graph using an adjacency list.
     * Provides cycle detection via Depth-First Search.
     */
    static class Graph {
        private final List<List<Integer>> adj;
        private final int numVertices;

        Graph(int numVertices) {
            this.numVertices = numVertices;
            this.adj = new ArrayList<>(numVertices);
            for (int i = 0; i < numVertices; i++) {
                adj.add(new ArrayList<>());
            }
        }

        void addEdge(int u, int v) {
            adj.get(u).add(v);
            adj.get(v).add(u);
        }

        /**
         * Checks if the graph contains any cycle.
         * Handles disconnected components by iterating over all vertices.
         */
        boolean hasCycle() {
            boolean[] visited = new boolean[numVertices];
            for (int i = 0; i < numVertices; i++) {
                if (!visited[i] && hasCycleDFS(i, visited, -1)) {
                    return true;
                }
            }
            return false;
        }

        /**
         * Recursive DFS to detect cycles in an undirected graph.
         * @param u current vertex
         * @param visited tracks visited vertices
         * @param parent the vertex from which we arrived at u
         * @return true if a cycle is detected
         */
        private boolean hasCycleDFS(int u, boolean[] visited, int parent) {
            visited[u] = true;
            for (int v : adj.get(u)) {
                if (!visited[v]) {
                    if (hasCycleDFS(v, visited, u)) {
                        return true;
                    }
                } else if (v != parent) {
                    // Found a back edge to a visited node that isn't the parent -> cycle
                    return true;
                }
            }
            return false;
        }
    }

    /**
     * Fast I/O helper for competitive programming environments.
     */
    static class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            String s = next();
            return s == null ? 0 : Integer.parseInt(s);
        }
    }
}

import java.util.Scanner;

public class Cycle {

    // Constants for movement directions: Up, Down, Left, Right
    private static final int[] DR = {-1, 1, 0, 0};
    private static final int[] DC = {0, 0, -1, 1};

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        // Read dimensions n (rows) and m (cols)
        if (!scanner.hasNextInt()) {
            return;
        }
        int n = scanner.nextInt();
        int m = scanner.nextInt();

        // Consume the newline character left after reading integers
        scanner.nextLine();

        char[][] grid = new char[n][];
        for (int i = 0; i < n; i++) {
            String line = scanner.nextLine();
            grid[i] = line.toCharArray();
        }

        // Check if a cycle exists in the grid
        boolean hasCycle = findCycle(grid);

        // Output the result
        System.out.println(hasCycle ? "Yes" : "No");

        scanner.close();
    }

    /**
     * Iterates through the grid to detect if any cycle of identical characters exists.
     * 
     * @param grid The 2D character array representing the map
     * @return true if a cycle is found, false otherwise
     */
    private static boolean findCycle(char[][] grid) {
        int n = grid.length;
        if (n == 0) return false;
        int m = grid[0].length;

        boolean[][] visited = new boolean[n][m];

        // Iterate over every cell in the grid
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                // If the cell has not been visited, start a DFS from here
                if (!visited[i][j]) {
                    // Pass -1, -1 as parent coordinates for the starting node
                    if (dfs(grid, visited, i, j, -1, -1)) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Performs Depth First Search (DFS) to detect cycles.
     * 
     * @param grid The 2D character array
     * @param visited 2D boolean array tracking visited cells
     * @param r Current row index
     * @param c Current column index
     * @param pR Parent row index (to prevent immediate backtracking)
     * @param pC Parent column index (to prevent immediate backtracking)
     * @return true if a cycle is detected, false otherwise
     */
    private static boolean dfs(char[][] grid, boolean[][] visited, int r, int c, int pR, int pC) {
        visited[r][c] = true;

        // Check all 4 adjacent directions
        for (int i = 0; i < 4; i++) {
            int nr = r + DR[i];
            int nc = c + DC[i];

            // Check boundaries
            if (nr >= 0 && nr < grid.length && nc >= 0 && nc < grid[0].length) {

                // Optimization: Only proceed if the neighbor has the same character
                if (grid[nr][nc] == grid[r][c]) {
                    if (visited[nr][nc]) {
                        // If neighbor is visited, it forms a cycle UNLESS it is the parent node
                        // we just came from.
                        if (nr != pR || nc != pC) {
                            return true;
                        }
                    } else {
                        // If neighbor is not visited, recurse
                        if (dfs(grid, visited, nr, nc, r, c)) {
                            return true;
                        }
                    }
                }
            }
        }
        return false;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayList;
import java.util.List;
import java.util.StringTokenizer;

public class Solution {

    public static void main(String[] args) throws IOException {
        // Use try-with-resources to ensure the BufferedReader is closed automatically
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {

            // Read the first line for dimensions
            String line = br.readLine();
            if (line == null) {
                return;
            }

            StringTokenizer st = new StringTokenizer(line);
            if (!st.hasMoreTokens()) {
                return;
            }

            int rows = Integer.parseInt(st.nextToken());
            int cols = Integer.parseInt(st.nextToken());

            // Use char[][] for better semantic representation of the grid
            // The original code used int[][] but stored char values implicitly.
            char[][] grid = new char[rows][cols];

            // Read the grid rows
            for (int i = 0; i < rows; i++) {
                String rowStr = br.readLine();
                // Basic validation to prevent IndexOutOfBoundsException if input is malformed
                if (rowStr != null) {
                    for (int j = 0; j < cols && j < rowStr.length(); j++) {
                        grid[i][j] = rowStr.charAt(j);
                    }
                }
            }

            // Build the adjacency list for the graph
            // Nodes are indexed from 0 to (rows * cols - 1) for 0-based indexing consistency
            int totalNodes = rows * cols;
            List<List<Integer>> adj = new ArrayList<>(totalNodes);
            for (int i = 0; i < totalNodes; i++) {
                adj.add(new ArrayList<>());
            }

            // Populate the graph based on adjacent identical characters
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    int u = r * cols + c;
                    char val = grid[r][c];

                    // Check Right Neighbor (r, c+1)
                    if (c + 1 < cols && grid[r][c + 1] == val) {
                        int v = r * cols + (c + 1);
                        adj.get(u).add(v);
                        adj.get(v).add(u);
                    }

                    // Check Down Neighbor (r+1, c)
                    // Checking Down is sufficient to avoid duplicate edge additions
                    // in an undirected graph, as the neighbor would have added the edge
                    // when it processed its Up neighbor.
                    if (r + 1 < rows && grid[r + 1][c] == val) {
                        int v = (r + 1) * cols + c;
                        adj.get(u).add(v);
                        adj.get(v).add(u);
                    }
                }
            }

            boolean[] visited = new boolean[totalNodes];
            boolean hasCycle = false;

            // Iterate over all nodes to handle disconnected components
            for (int i = 0; i < totalNodes; i++) {
                if (!visited[i]) {
                    ComponentStats stats = dfs(adj, i, visited);

                    // In a connected component, if the number of edges is greater than 
                    // or equal to the number of vertices (V), a cycle exists.
                    // stats.degreeSum / 2 gives the number of edges.
                    // Original logic: edges > vertices - 1, which is equivalent to edges >= vertices for integers.
                    int edges = stats.degreeSum / 2;
                    if (edges >= stats.vertices) {
                        hasCycle = true;
                        break;
                    }
                }
            }

            System.out.println(hasCycle ? "Yes" : "No");
        }
    }

    /**
     * Performs Depth First Search to count vertices and sum of degrees 
     * in the connected component containing the start node.
     */
    private static ComponentStats dfs(List<List<Integer>> adj, int u, boolean[] visited) {
        visited[u] = true;
        int vertices = 1;
        int degreeSum = adj.get(u).size();

        for (int v : adj.get(u)) {
            if (!visited[v]) {
                ComponentStats subStats = dfs(adj, v, visited);
                vertices += subStats.vertices;
                degreeSum += subStats.degreeSum;
            }
        }
        return new ComponentStats(vertices, degreeSum);
    }

    /**
     * Helper class to store statistics of a graph component.
     * Replaces the generic 'Pair' class for better semantic clarity.
     */
    private static class ComponentStats {
        int vertices;
        int degreeSum;

        public ComponentStats(int vertices, int degreeSum) {
            this.vertices = vertices;
            this.degreeSum = degreeSum;
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;

public class Main {

    // Instance variables to replace static fields, improving encapsulation and testability
    private char[][] grid;
    private boolean[][] visited;
    private int rows;
    private int cols;

    public static void main(String[] args) throws IOException {
        Main solver = new Main();
        solver.run();
    }

    private void run() throws IOException {
        // Use try-with-resources for automatic resource management
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {

            // Read dimensions N and M
            String line = br.readLine();
            if (line == null) return;

            // Robust parsing of dimensions handling multiple spaces
            String[] parts = line.trim().split("\\s+");
            if (parts.length < 2) return;

            this.rows = Integer.parseInt(parts[0]);
            this.cols = Integer.parseInt(parts[1]);

            grid = new char[rows][cols];
            visited = new boolean[rows][cols];

            // Read grid characters
            // The original logic skips non-alphabetic characters to fill the grid sequentially.
            // We replicate this behavior to maintain compatibility with the input format.
            int count = 0;
            int totalCells = rows * cols;
            int c;

            while (count < totalCells) {
                c = br.read();
                if (c == -1) break; // End of stream

                if (Character.isAlphabetic(c)) {
                    grid[count / cols][count % cols] = (char) c;
                    count++;
                }
            }

            // Detect cycle
            boolean cycleFound = false;
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (!visited[i][j]) {
                        // Start DFS. Parent is (-1, -1) to indicate no parent for the root node.
                        // This replaces the magic number -15 used in the original code.
                        if (dfs(i, j, -1, -1)) {
                            cycleFound = true;
                            break;
                        }
                    }
                }
                if (cycleFound) break;
            }

            System.out.println(cycleFound ? "Yes" : "No");
        }
    }

    /**
     * Depth First Search to detect cycles in the grid.
     * 
     * @param r Current row
     * @param c Current column
     * @param prevR Row of the parent node (where we came from)
     * @param prevC Column of the parent node
     * @return true if a cycle is detected, false otherwise
     */
    private boolean dfs(int r, int c, int prevR, int prevC) {
        visited[r][c] = true;
        char currentChar = grid[r][c];

        // Directions: Down, Up, Right, Left
        int[] dr = {1, -1, 0, 0};
        int[] dc = {0, 0, 1, -1};

        for (int k = 0; k < 4; k++) {
            int nr = r + dr[k];
            int nc = c + dc[k];

            if (isValid(nr, nc) && grid[nr][nc] == currentChar) {
                if (!visited[nr][nc]) {
                    // If not visited, recurse
                    if (dfs(nr, nc, r, c)) {
                        return true;
                    }
                } else if (nr != prevR || nc != prevC) {
                    // If visited and not the parent, a cycle is found.
                    // Note: The original code used (x != oldx && y != oldy) which was logically flawed
                    // for grid connectivity (it required the neighbor to differ in BOTH coordinates
                    // from the parent). The correct logic is OR (||) to ensure we aren't just
                    // looking back at the immediate parent.
                    return true;
                }
            }
        }
        return false;
    }

    private boolean isValid(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

/**
 * A program to detect if there is a cycle in a 2D grid of characters.
 * A cycle is defined as a path of identical characters that starts and ends at the same cell,
 * without retracing the immediate previous step.
 */
public class GridCycleDetector {

    /**
     * FastScanner class for efficient input reading.
     * Replaces the original buggy implementation with a robust standard version.
     */
    static class FastScanner {
        BufferedReader br;
        StringTokenizer st;

        public FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        /**
         * Reads the next token from the input.
         * @return The next token string, or null if end of input is reached.
         */
        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    e.printStackTrace();
                    return null;
                }
            }
            return st.nextToken();
        }

        /**
         * Reads the next integer from the input.
         * @return The next integer.
         */
        int nextInt() {
            String s = next();
            if (s == null) throw new RuntimeException("End of input");
            return Integer.parseInt(s);
        }
    }

    static int rows;
    static int cols;
    static char[][] charGrid;
    static boolean[][] visited;

    // Direction arrays for moving Up, Left, Right, Down
    static final int[] dRow = {-1, 0, 0, 1};
    static final int[] dCol = {0, -1, 1, 0};

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner();

        // Read dimensions
        String nStr = scanner.next();
        if (nStr == null) return; // Handle empty input gracefully

        rows = Integer.parseInt(nStr);
        cols = scanner.nextInt();

        // Initialize grid with padding (size + 2) to handle boundary checks implicitly.
        // The padding cells will contain the default char value '\u0000', 
        // which will not match any valid input characters.
        charGrid = new char[rows + 2][cols + 2];
        visited = new boolean[rows + 2][cols + 2];

        // Read grid data
        // We use next() to read each row as a string token. 
        // This assumes rows do not contain whitespace characters.
        for (int i = 1; i <= rows; i++) {
            String rowStr = scanner.next();
            if (rowStr != null) {
                for (int j = 1; j <= cols; j++) {
                    if (j <= rowStr.length()) {
                        charGrid[i][j] = rowStr.charAt(j - 1);
                    }
                }
            }
        }

        boolean cycleFound = false;

        // Iterate through every cell to start DFS if not visited
        for (int i = 1; i <= rows; i++) {
            for (int j = 1; j <= cols; j++) {
                if (!visited[i][j]) {
                    if (hasCycle(i, j, -1, -1)) {
                        cycleFound = true;
                        break;
                    }
                }
            }
            if (cycleFound) break;
        }

        System.out.println(cycleFound ? "Yes" : "No");
    }

    /**
     * Performs DFS to detect a cycle in the grid.
     * 
     * @param r Current row index
     * @param c Current column index
     * @param parentR Parent row index (to prevent going back up the immediate edge)
     * @param parentC Parent column index
     * @return true if a cycle is detected, false otherwise
     */
    static boolean hasCycle(int r, int c, int parentR, int parentC) {
        visited[r][c] = true;

        for (int k = 0; k < 4; k++) {
            int nextR = r + dRow[k];
            int nextC = c + dCol[k];

            // Check if the neighbor is within the logical bounds (implicitly handled by padding size)
            // Valid indices are 0 to rows+1 (inclusive)
            if (nextR >= 0 && nextR <= rows + 1 && nextC >= 0 && nextC <= cols + 1) {
                if (charGrid[nextR][nextC] == charGrid[r][c]) {
                    // If neighbor is the parent, skip it (undirected graph edge)
                    if (nextR == parentR && nextC == parentC) {
                        continue;
                    }

                    // If neighbor is already visited, we found a cycle (back-edge)
                    if (visited[nextR][nextC]) {
                        return true;
                    }

                    // Recurse
                    if (hasCycle(nextR, nextC, r, c)) {
                        return true;
                    }
                }
            }
        }
        return false;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

public class Main {

    // Direction vectors for moving Up, Down, Left, Right
    private static final int[] ROW_DIR = {-1, 1, 0, 0};
    private static final int[] COL_DIR = {0, 0, -1, 1};

    public static void main(String[] args) throws IOException {
        // Use try-with-resources to ensure the BufferedReader is closed properly
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            String line = br.readLine();
            if (line == null || line.trim().isEmpty()) {
                return;
            }

            StringTokenizer st = new StringTokenizer(line);
            int rows = Integer.parseInt(st.nextToken());
            int cols = Integer.parseInt(st.nextToken());

            char[][] grid = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                String rowLine = br.readLine();
                // Ensure we handle potential null lines or empty input gracefully
                if (rowLine != null) {
                    grid[i] = rowLine.trim().toCharArray();
                }
            }

            // Boolean matrix to keep track of visited cells
            boolean[][] visited = new boolean[rows][cols];
            boolean cycleFound = false;

            // Iterate through every cell to handle disconnected components
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    // If the cell hasn't been visited, start a DFS from here
                    if (!visited[i][j]) {
                        // Start DFS with (-1, -1) as the parent coordinates
                        if (hasCycle(i, j, -1, -1, grid, visited)) {
                            cycleFound = true;
                            break;
                        }
                    }
                }
                if (cycleFound) {
                    break;
                }
            }

            System.out.println(cycleFound ? "Yes" : "No");
        }
    }

    /**
     * Performs Depth First Search (DFS) to detect if a cycle exists in the grid.
     * A cycle is defined as a path of identical characters that starts and ends
     * at the same position, moving only horizontally or vertically.
     *
     * @param r       Current row index
     * @param c       Current column index
     * @param parentR Row index of the parent node (to avoid going back immediately)
     * @param parentC Column index of the parent node
     * @param grid    The character grid
     * @param visited Boolean matrix tracking visited cells
     * @return true if a cycle is detected, false otherwise
     */
    private static boolean hasCycle(int r, int c, int parentR, int parentC, char[][] grid, boolean[][] visited) {
        // Mark the current cell as visited
        visited[r][c] = true;
        char currentChar = grid[r][c];

        // Explore all 4 adjacent directions
        for (int k = 0; k < 4; k++) {
            int newR = r + ROW_DIR[k];
            int newC = c + COL_DIR[k];

            // 1. Check boundaries
            if (newR < 0 || newR >= grid.length || newC < 0 || newC >= grid[0].length) {
                continue;
            }

            // 2. Check if the adjacent cell has the same character
            if (grid[newR][newC] != currentChar) {
                continue;
            }

            // 3. Check if the adjacent cell is the parent (to avoid traversing back up the edge)
            if (newR == parentR && newC == parentC) {
                continue;
            }

            // 4. If the adjacent cell is already visited, a cycle is found.
            // In an undirected graph DFS, encountering a visited node that isn't the parent
            // implies a back-edge to an ancestor in the recursion stack.
            if (visited[newR][newC]) {
                return true;
            }

            // 5. Recursively visit the adjacent cell
            if (hasCycle(newR, newC, r, c, grid, visited)) {
                return true;
            }
        }

        // If no cycle is found in this branch, return false
        return false;
    }
}

import java.io.*;
import java.util.*;

public class B510 {
    // Direction vectors for moving down, up, right, left
    private static final int[] DR = {1, -1, 0, 0};
    private static final int[] DC = {0, 0, 1, -1};

    public static void main(String[] args) throws IOException {
        // Use try-with-resources for automatic and safe resource management
        try (FastScanner scanner = new FastScanner(System.in);
             PrintWriter out = new PrintWriter(System.out)) {
            new B510().solve(scanner, out);
        }
    }

    private void solve(FastScanner in, PrintWriter out) throws IOException {
        int n = in.nextInt();
        int m = in.nextInt();

        // Dynamically allocate grid based on actual input dimensions
        char[][] grid = new char[n][m];
        for (int i = 0; i < n; i++) {
            grid[i] = in.next().toCharArray();
        }

        // 0: unvisited, 1: currently visiting (in recursion stack), 2: fully visited
        int[][] visited = new int[n][m];
        boolean cycleFound = false;

        // Iterate through each cell to handle potentially disconnected components
        for (int i = 0; i < n && !cycleFound; i++) {
            for (int j = 0; j < m && !cycleFound; j++) {
                if (visited[i][j] == 0) {
                    if (hasCycle(grid, visited, i, j, -1, -1)) {
                        cycleFound = true;
                    }
                }
            }
        }

        out.println(cycleFound ? "Yes" : "No");
    }

    /**
     * Performs DFS to detect cycles in the grid graph.
     * 
     * @param grid    The character grid
     * @param visited State tracking array (0: unvisited, 1: visiting, 2: visited)
     * @param r       Current row
     * @param c       Current column
     * @param prevR   Previous row (to avoid immediate backtracking)
     * @param prevC   Previous column (to avoid immediate backtracking)
     * @return true if a cycle is found, false otherwise
     */
    private boolean hasCycle(char[][] grid, int[][] visited, int r, int c, int prevR, int prevC) {
        if (!isValid(r, c, grid.length, grid[0].length)) {
            return false;
        }

        // If we encounter a node currently in the recursion stack, a cycle exists
        if (visited[r][c] == 1) {
            return true;
        }

        // If already fully processed, no cycle can be found through this path
        if (visited[r][c] == 2) {
            return false;
        }

        visited[r][c] = 1; // Mark as visiting

        for (int i = 0; i < 4; i++) {
            int nr = r + DR[i];
            int nc = c + DC[i];

            // Skip the parent node to prevent immediate backtracking
            if (nr == prevR && nc == prevC) {
                continue;
            }

            // Only proceed if the adjacent cell has the same character
            if (grid[nr][nc] == grid[r][c]) {
                if (hasCycle(grid, visited, nr, nc, r, c)) {
                    return true;
                }
            }
        }

        visited[r][c] = 2; // Mark as fully visited
        return false;
    }

    private boolean isValid(int r, int c, int rows, int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /**
     * Fast input reader optimized for competitive programming scenarios.
     * Replaces verbose template code with a focused, maintainable implementation.
     */
    private static class FastScanner {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastScanner(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                String line = reader.readLine();
                if (line == null) {
                    throw new IOException("Unexpected end of input");
                }
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}

import java.util.Scanner;

/**
 * Detects if a cycle exists in a 2D character grid.
 * A cycle is defined as a path of identical characters that connects back to 
 * a previously visited node without immediately retracing the last step.
 */
public class CodeForces {

    // Direction vectors for moving up, down, left, and right
    private static final int[] DR = {-1, 1, 0, 0};
    private static final int[] DC = {0, 0, -1, 1};

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        try {
            if (!scanner.hasNextInt()) return;

            int rows = scanner.nextInt();
            int cols = scanner.nextInt();

            char[][] grid = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                grid[i] = scanner.next().toCharArray();
            }

            boolean hasCycle = hasCycle(grid);
            System.out.println(hasCycle ? "Yes" : "No");
        } finally {
            scanner.close();
        }
    }

    /**
     * Checks if the grid contains a cycle of identical characters.
     *
     * @param grid The 2D character matrix
     * @return true if a cycle exists, false otherwise
     */
    public static boolean hasCycle(char[][] grid) {
        if (grid == null || grid.length == 0 || grid[0].length == 0) {
            return false;
        }

        int rows = grid.length;
        int cols = grid[0].length;
        boolean[][] visited = new boolean[rows][cols];

        // Iterate over each cell to handle disconnected components
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                // Start DFS only from unvisited cells
                if (!visited[r][c] && dfs(r, c, -1, -1, visited, grid)) {
                    return true;
                }
            }
        }
        return false;
    }

    /**
     * Performs Depth-First Search to detect cycles in the grid.
     *
     * @param r         Current row
     * @param c         Current column
     * @param parentR   Row of the parent node (prevents immediate backtracking)
     * @param parentC   Column of the parent node
     * @param visited   Visited state matrix
     * @param grid      The character grid
     * @return true if a cycle is found, false otherwise
     */
    private static boolean dfs(int r, int c, int parentR, int parentC, boolean[][] visited, char[][] grid) {
        visited[r][c] = true;
        char currentColor = grid[r][c];

        for (int i = 0; i < DR.length; i++) {
            int nextR = r + DR[i];
            int nextC = c + DC[i];

            // Skip the immediate parent to avoid false cycle detection
            if (nextR == parentR && nextC == parentC) {
                continue;
            }

            // Check bounds and ensure the neighbor has the same character color
            if (isInBounds(nextR, nextC, grid) && grid[nextR][nextC] == currentColor) {
                // If the neighbor is already visited, we found a cycle
                if (visited[nextR][nextC]) {
                    return true;
                }
                // Recurse into unvisited neighbors
                if (dfs(nextR, nextC, r, c, visited, grid)) {
                    return true;
                }
            }
        }
        return false;
    }

    /**
     * Checks if the given coordinates are within grid boundaries.
     */
    private static boolean isInBounds(int r, int c, char[][] grid) {
        return r >= 0 && r < grid.length && c >= 0 && c < grid[0].length;
    }
}

