/**
 * Refactored solution for grid cycle detection.
 * This version improves maintainability by:
 * 1. Using standard naming conventions (Main instead of _511B).
 * 2. Encapsulating I/O logic in a static nested helper class.
 * 3. Using PrintWriter for efficient output.
 * 4. Converting String grid to char[][] for better performance.
 * 5. Using direction arrays to reduce code duplication in DFS.
 * 6. Removing instance state (n, m) in favor of local variables.
 */
public class Main {

    public static void main(String[] args) {
        // Initialize I/O streams
        InputStream inputStream = System.in;
        PrintWriter out = new PrintWriter(System.out);

        Main solver = new Main();
        try {
            solver.solve(inputStream, out);
        } catch (IOException e) {
            e.printStackTrace();
        } finally {
            out.flush();
            out.close();
        }
    }

    /**
     * Main logic to read input and solve the problem.
     *
     * @param inputStream The input stream
     * @param out         The output writer
     * @throws IOException if an I/O error occurs
     */
    private void solve(InputStream inputStream, PrintWriter out) throws IOException {
        InputHelper in = new InputHelper(inputStream);

        // Read dimensions
        String nStr = in.next();
        if (nStr == null) return;
        int n = Integer.parseInt(nStr);

        String mStr = in.next();
        if (mStr == null) return;
        int m = Integer.parseInt(mStr);

        // Read grid into char array for efficient access
        // Using a jagged array to accommodate input rows directly
        char[][] grid = new char[n][];
        for (int i = 0; i < n; i++) {
            String row = in.next();
            if (row != null) {
                grid[i] = row.toCharArray();
            } else {
                grid[i] = new char[0];
            }
        }

        boolean[][] visited = new boolean[n][m];

        // Iterate through every cell to handle disconnected components
        for (int i = 0; i < n; i++) {
            // Ensure row exists and has length m to avoid IndexOutOfBounds
            if (grid[i] == null || grid[i].length < m) continue;

            for (int j = 0; j < m; j++) {
                if (!visited[i][j]) {
                    // If DFS finds a cycle, print Yes and exit
                    if (dfs(i, j, -1, -1, grid, visited)) {
                        out.println("Yes");
                        return;
                    }
                }
            }
        }

        // If no cycle found after checking all components
        out.println("No");
    }

    /**
     * Depth First Search to detect cycles in the grid graph.
     * A cycle exists if we encounter a visited node that is not the immediate parent.
     *
     * @param r       Current row
     * @param c       Current column
     * @param prevR   Row of the previous node (parent)
     * @param prevC   Column of the previous node (parent)
     * @param grid    The character grid
     * @param visited Visited status matrix
     * @return true if a cycle is detected, false otherwise
     */
    private boolean dfs(int r, int c, int prevR, int prevC, char[][] grid, boolean[][] visited) {
        // If we encounter a node that is already visited, it implies a cycle
        // (since we skip the parent, any other visited neighbor is a back-edge)
        if (visited[r][c]) {
            return true;
        }

        // Mark current node as visited
        visited[r][c] = true;

        // Directions: Up, Down, Left, Right
        int[] dr = {-1, 1, 0, 0};
        int[] dc = {0, 0, -1, 1};

        for (int k = 0; k < 4; k++) {
            int nr = r + dr[k];
            int nc = c + dc[k];

            // Check boundaries
            // Note: grid[nr] might be null or short if input is malformed, handled by bounds check
            if (nr < 0 || nr >= grid.length) {
                continue;
            }
            if (nc < 0 || nc >= grid[nr].length) {
                continue;
            }

            // Check if neighbor is the parent node (to avoid going back up the edge)
            if (nr == prevR && nc == prevC) {
                continue;
            }

            // Check if characters match (edge existence condition)
            if (grid[nr][nc] != grid[r][c]) {
                continue;
            }

            // Recurse
            if (dfs(nr, nc, r, c, grid, visited)) {
                return true;
            }
        }

        return false;
    }

    /**
     * Helper class for fast input reading.
     */
    static class InputHelper {
        private BufferedReader br;
        private StringTokenizer st;

        public InputHelper(InputStream inputStream) {
            this.br = new BufferedReader(new InputStreamReader(inputStream), 16384);
        }

        public String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) {
                        return null;
                    }
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            String s = next();
            return (s == null) ? 0 : Integer.parseInt(s);
        }

        public long nextLong() {
            String s = next();
            return (s == null) ? 0L : Long.parseLong(s);
        }
    }
}

import java.util.Scanner;

/**
 * A program to detect if there is a cycle of identical characters in a grid.
 * It reads a grid of size n x m and determines if a closed loop of the same character exists.
 */
public class Main {

    // Direction vectors for moving Up, Right, Down, Left respectively
    private static final int[] ROW_OFFSETS = {-1, 0, 1, 0};
    private static final int[] COL_OFFSETS = {0, 1, 0, -1};

    public static void main(String[] args) {
        // Use try-with-resources to ensure the Scanner is closed automatically
        try (Scanner scanner = new Scanner(System.in)) {

            // Check if input exists to prevent exceptions on empty input
            if (!scanner.hasNextInt()) {
                return;
            }

            int n = scanner.nextInt();
            int m = scanner.nextInt();

            char[][] grid = new char[n][m];

            // Read the grid rows
            for (int i = 0; i < n; i++) {
                String line = scanner.next();
                // Convert string to char array for easier access
                grid[i] = line.toCharArray();
            }

            // Determine if a cycle exists and print the result
            boolean hasCycle = detectCycle(grid);
            System.out.println(hasCycle ? "Yes" : "No");
        }
    }

    /**
     * Iterates through the grid to find a cycle of identical characters.
     * Uses a global visited array to track processed nodes across the entire grid.
     * This approach ensures O(N*M) time complexity.
     *
     * @param grid The 2D character array representing the map.
     * @return true if a cycle is found, false otherwise.
     */
    private static boolean detectCycle(char[][] grid) {
        int rows = grid.length;
        int cols = grid[0].length;
        boolean[][] visited = new boolean[rows][cols];

        // Iterate over every cell in the grid
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                // If the cell has not been visited, start a Depth First Search (DFS)
                // This handles disconnected components in the graph correctly
                if (!visited[r][c]) {
                    // Start DFS from (r, c) with no parent (-1, -1)
                    if (dfs(grid, visited, r, c, -1, -1)) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Performs a Depth First Search (DFS) to detect a cycle.
     * 
     * @param grid The 2D character array.
     * @param visited 2D boolean array tracking visited cells.
     * @param r Current row index.
     * @param c Current column index.
     * @param parentR Row index of the parent node (to avoid immediate backtracking).
     * @param parentC Column index of the parent node.
     * @return true if a cycle is detected, false otherwise.
     */
    private static boolean dfs(char[][] grid, boolean[][] visited, int r, int c, int parentR, int parentC) {
        // Mark the current cell as visited
        visited[r][c] = true;

        // Explore all 4 possible directions
        for (int i = 0; i < ROW_OFFSETS.length; i++) {
            int nextR = r + ROW_OFFSETS[i];
            int nextC = c + COL_OFFSETS[i];

            // Check boundaries
            if (nextR >= 0 && nextR < grid.length && nextC >= 0 && nextC < grid[0].length) {

                // Check if the neighbor has the same character as the current cell
                if (grid[nextR][nextC] == grid[r][c]) {

                    // If the neighbor is the parent node, skip it (don't go back up the edge we came from)
                    if (nextR == parentR && nextC == parentC) {
                        continue;
                    }

                    // If the neighbor is already visited and is not the parent, a cycle is found!
                    if (visited[nextR][nextC]) {
                        return true;
                    }

                    // If the neighbor is not visited, continue the DFS recursively
                    if (dfs(grid, visited, nextR, nextC, r, c)) {
                        return true;
                    }
                }
            }
        }

        // If no cycle found from this path, return false
        return false;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayList;
import java.util.List;
import java.util.StringTokenizer;

public class GridCycleDetector {
    // Constants for direction vectors and cycle length threshold
    private static final int[] ROW_DIRS = {-1, 0, 1, 0};
    private static final int[] COL_DIRS = {0, 1, 0, -1};
    private static final int MIN_CYCLE_LENGTH = 4;

    public static void main(String[] args) {
        FastReader reader = new FastReader();

        // Read grid dimensions
        String nStr = reader.next();
        if (nStr == null) return;
        int n = Integer.parseInt(nStr);
        int m = reader.nextInt();

        // Read grid characters
        char[][] grid = new char[n][m];
        for (int i = 0; i < n; i++) {
            grid[i] = reader.next().toCharArray();
        }

        // Build adjacency list and detect cycle
        List<List<Integer>> adjList = buildGraph(n, m, grid);
        boolean hasCycle = hasCycleOfLengthAtLeast4(n, m, adjList);

        // Output result
        System.out.println(hasCycle ? "Yes" : "No");
    }

    /**
     * Builds an undirected graph where adjacent cells with the same character are connected.
     * Uses 1D indexing (u = r * m + c) for the adjacency list.
     */
    private static List<List<Integer>> buildGraph(int n, int m, char[][] grid) {
        List<List<Integer>> adjList = new ArrayList<>(n * m);
        for (int i = 0; i < n * m; i++) {
            adjList.add(new ArrayList<>());
        }

        for (int r = 0; r < n; r++) {
            for (int c = 0; c < m; c++) {
                int u = r * m + c;
                for (int k = 0; k < 4; k++) {
                    int nr = r + ROW_DIRS[k];
                    int nc = c + COL_DIRS[k];

                    if (isValid(nr, nc, n, m) && grid[r][c] == grid[nr][nc]) {
                        int v = nr * m + nc;
                        adjList.get(u).add(v);
                    }
                }
            }
        }
        return adjList;
    }

    /**
     * Checks if the graph contains a cycle of length >= 4.
     */
    private static boolean hasCycleOfLengthAtLeast4(int n, int m, List<List<Integer>> adjList) {
        boolean[][] visited = new boolean[n][m];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (!visited[i][j]) {
                    if (dfs(adjList, i, j, -1, -1, visited, n, m, 1)) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Depth-First Search to detect cycles.
     * 
     * @param r, c       Current cell coordinates
     * @param parentR, parentC Parent cell coordinates (to avoid going back up the tree)
     * @param visited    2D boolean array tracking visited cells
     * @param n, m       Grid dimensions
     * @param depth      Current depth in the DFS traversal (starts at 1)
     * @return true if a cycle of length >= 4 is found
     */
    private static boolean dfs(List<List<Integer>> adjList, int r, int c, int parentR, int parentC,
                               boolean[][] visited, int n, int m, int depth) {
        visited[r][c] = true;
        int u = r * m + c;

        for (int v : adjList.get(u)) {
            int nr = v / m;
            int nc = v % m;

            // Skip the parent node to prevent immediate backtracking
            if (nr == parentR && nc == parentC) {
                continue;
            }

            if (visited[nr][nc]) {
                // Found a back-edge to a visited node.
                // In a grid graph, any cycle naturally has length >= 4.
                // If we've traversed at least 3 edges (depth >= 4), a cycle exists.
                if (depth >= MIN_CYCLE_LENGTH) {
                    return true;
                }
            } else {
                // Recurse into unvisited neighbor
                if (dfs(adjList, nr, nc, r, c, visited, n, m, depth + 1)) {
                    return true;
                }
            }
        }
        return false;
    }

    /**
     * Checks if coordinates are within grid boundaries.
     */
    private static boolean isValid(int r, int c, int n, int m) {
        return r >= 0 && r < n && c >= 0 && c < m;
    }

    /**
     * Standard, maintainable input reader using BufferedReader and StringTokenizer.
     */
    private static class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            String s = next();
            return s == null ? 0 : Integer.parseInt(s);
        }
    }
}

