/**
 * Refactored Grid Cycle Detector.
 * 
 * Improvements made:
 * 1. Encapsulation: Moved static fields to instance variables to improve reusability and testability.
 * 2. Algorithm Optimization: Changed from O(N^2 * M^2) to O(N * M).
 *    - Reuses a single 'visited' array instead of allocating a new one for every cell.
 *    - Uses standard DFS cycle detection (back-edge detection). In a grid graph, 
 *      any cycle must have a length of at least 4, so explicit length tracking is redundant.
 * 3. Readability: Renamed variables (e.g., 'g' -> 'grid', 'n' -> 'rows') and used 
 *    direction arrays for cleaner neighbor iteration.
 * 4. Robustness: Improved input handling and error checking in the FastScanner.
 */
public class GridCycleDetector {

    private int rows;
    private int cols;
    private char[][] grid;
    private boolean[][] visited;

    // Directions: Up, Down, Left, Right
    private static final int[] DR = {-1, 1, 0, 0};
    private static final int[] DC = {0, 0, -1, 1};

    public static void main(String[] args) {
        GridCycleDetector solver = new GridCycleDetector();
        if (solver.solve()) {
            System.out.println("Yes");
        } else {
            System.out.println("No");
