            if (mStr == null) return false;
            this.cols = Integer.parseInt(mStr);

            // Read grid
            this.grid = new char[this.rows][this.cols];
            for (int i = 0; i < this.rows; i++) {
                String line = scanner.next();
                if (line != null) {
                    this.grid[i] = line.toCharArray();
                }
            }
        } catch (Exception e) {
            // In a production environment, proper logging should be used.
            return false;
        }

        // Initialize visited array once for the entire grid
        this.visited = new boolean[this.rows][this.cols];

        // Iterate through every cell to find a cycle
        for (int r = 0; r < this.rows; r++) {
            for (int c = 0; c < this.cols; c++) {
                // If the cell hasn't been visited, start a DFS to explore its component
                if (!visited[r][c]) {
                    // Pass -1, -1 as parent coordinates to indicate no parent for the root
                    if (dfs(r, c, -1, -1)) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Depth First Search to detect cycles.
     * 
     * @param r Current row
     * @param c Current column
     * @param prevR Row of the parent node (to avoid going back immediately)
     * @param prevC Column of the parent node
     * @return true if a cycle is found, false otherwise
     */
    private boolean dfs(int r, int c, int prevR, int prevC) {
        visited[r][c] = true;
        char currentChar = grid[r][c];

        // Explore neighbors
        for (int k = 0; k < 4; k++) {
            int nr = r + DR[k];
            int nc = c + DC[k];

            // Check boundaries
            if (nr >= 0 && nr < rows && nc >= 0 && nc < cols) {
                // Check if neighbor has the same character
                if (grid[nr][nc] == currentChar) {
                    // If neighbor is the parent we just came from, skip it
                    if (nr == prevR && nc == prevC) {
                        continue;
                    }

                    // If neighbor is already visited, we found a cycle.
                    // In a grid graph, any cycle has length >= 4.
                    if (visited[nr][nc]) {
                        return true;
                    }

                    // Recurse
                    if (dfs(nr, nc, r, c)) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Helper class for fast input reading.
     */
    static class FastScanner {
