/**
 * Analyzes a 2D character grid to detect if any connected component of identical characters
 * contains a cycle. A cycle is detected when a DFS traversal encounters at least two 
 * already-visited neighbors of the same character type.
 */
public class FoxandCeil2 {

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner();

        // Read grid dimensions
        int rows = scanner.nextInt();
        int cols = scanner.nextInt();

        // Read grid content
        char[][] grid = new char[rows][];
        for (int i = 0; i < rows; i++) {
            grid[i] = scanner.nextCharArray();
        }

        // Run analysis and output result
        GridAnalyzer analyzer = new GridAnalyzer(grid);
        boolean hasCycle = analyzer.hasCycle();
        System.out.println(hasCycle ? "Yes" : "No");
    }

    /**
     * Encapsulates grid state and traversal logic. 
     * Removing static globals improves testability, thread-safety, and reusability.
     */
    private static class GridAnalyzer {
        private final char[][] grid;
        private final int rows;
        private final int cols;
        private boolean[][] visited;

        public GridAnalyzer(char[][] grid) {
            this.grid = grid;
            this.rows = grid.length;
            this.cols = grid[0].length;
            this.visited = new boolean[rows][cols];
        }

        public boolean hasCycle() {
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (!visited[i][j] && dfs(i, j)) {
                        return true;
                    }
                }
            }
            return false;
        }

        /**
         * Performs DFS to traverse connected cells of the same character.
         * Returns true if a cycle is detected within the current component.
         */
        private boolean dfs(int i, int j) {
            visited[i][j] = true;
            int visitedSameCharNeighbors = 0;

            // Directions: up, down, left, right
            int[] dRow = {-1, 1, 0, 0};
            int[] dCol = {0, 0, -1, 1};

            for (int k = 0; k < 4; k++) {
                int nextRow = i + dRow[k];
                int nextCol = j + dCol[k];

                if (isValid(nextRow, nextCol) && grid[nextRow][nextCol] == grid[i][j]) {
                    if (visited[nextRow][nextCol]) {
                        visitedSameCharNeighbors++;
                    } else {
                        if (dfs(nextRow, nextCol)) {
                            return true;
                        }
                    }
                }
            }

            return visitedSameCharNeighbors >= 2;
        }

        private boolean isValid(int row, int col) {
            return row >= 0 && row < rows && col >= 0 && col < cols;
        }
    }

    /**
     * Utility class for fast input reading. Optimized for competitive programming 
     * and large input datasets.
     */
    private static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
            st = new StringTokenizer("");
        }

        public String next() {
            while (!st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input", e);
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }

        public double nextDouble() {
            return Double.parseDouble(next());
        }

        public String nextLine() {
            try {
                return br.readLine();
            } catch (IOException e) {
                throw new RuntimeException("Failed to read line", e);
            }
        }

        /**
         * Reads the next token as a character array.
         * Uses next() to safely skip whitespace/newlines. 
         * Switch to nextLine().trim() if rows are expected to contain spaces.
         */
        public char[] nextCharArray() {
            return next().toCharArray();
        }
    }
}

import java.io.BufferedInputStream;
import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;

public class Main {
    // Direction vectors for moving down, right, up, left
    private static final int[] DX = {1, 0, -1, 0};
    private static final int[] DY = {0, 1, 0, -1};

    public static void main(String[] args) {
        FastScanner in = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out);

        int n = in.nextInt();
        int m = in.nextInt();
        char[][] grid = new char[n][m];
        for (int i = 0; i < n; i++) {
            grid[i] = in.next().toCharArray();
        }

        boolean hasCycle = hasCycleInGrid(n, m, grid);
        out.println(hasCycle ? "Yes" : "No");
        out.close();
    }

    /**
     * Checks if there is a cycle of identical characters in the grid.
     */
    private static boolean hasCycleInGrid(int n, int m, char[][] grid) {
        boolean[][] visited = new boolean[n][m];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (!visited[i][j]) {
                    if (dfs(i, j, grid, visited, -1, -1, n, m)) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Depth-first search to detect cycles within the same character component.
     *
     * @param r       Current row
     * @param c       Current column
     * @param grid    The character grid
     * @param visited Visited matrix to track processed cells
     * @param prevR   Previous row (to avoid going back up the same edge)
     * @param prevC   Previous column
     * @param n       Grid height
     * @param m       Grid width
     * @return true if a cycle is found, false otherwise
     */
    private static boolean dfs(int r, int c, char[][] grid, boolean[][] visited,
                               int prevR, int prevC, int n, int m) {
        visited[r][c] = true;
        char target = grid[r][c];

        for (int k = 0; k < 4; k++) {
            int nr = r + DX[k];
            int nc = c + DY[k];

            if (isValid(nr, nc, n, m)) {
                // If neighbor is visited, same character, and not the immediate parent, a cycle exists
                if (visited[nr][nc] && grid[nr][nc] == target && (nr != prevR || nc != prevC)) {
                    return true;
                }
                // Continue DFS if neighbor is unvisited and matches the character
                if (!visited[nr][nc] && grid[nr][nc] == target) {
                    if (dfs(nr, nc, grid, visited, r, c, n, m)) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    private static boolean isValid(int r, int c, int n, int m) {
        return r >= 0 && r < n && c >= 0 && c < m;
    }

    /**
     * Fast I/O helper class for competitive programming.
     */
    static class FastScanner {
        private final byte[] buffer = new byte[4096];
        private int bufferIndex = 0;
        private int bytesRead = 0;
        private final BufferedInputStream inputStream;

        public FastScanner(InputStream inputStream) {
            this.inputStream = new BufferedInputStream(inputStream);
        }

        private int readByte() {
            if (bufferIndex >= bytesRead) {
                bufferIndex = 0;
                try {
                    bytesRead = inputStream.read(buffer);
                } catch (IOException e) {
                    e.printStackTrace();
                }
                if (bytesRead <= 0) {
                    return -1;
                }
            }
            return buffer[bufferIndex++];
        }

        public int nextInt() {
            int result = 0;
            int c = readByte();
            while (isWhitespace(c)) c = readByte();
            boolean negative = false;
            if (c == '-') {
                negative = true;
                c = readByte();
            }
            while (!isWhitespace(c)) {
                if (c >= '0' && c <= '9') {
                    result = result * 10 + (c - '0');
                }
                c = readByte();
            }
            return negative ? -result : result;
        }

        public String next() {
            int c = readByte();
            while (isWhitespace(c)) c = readByte();
            StringBuilder sb = new StringBuilder();
            do {
                sb.appendCodePoint(c);
                c = readByte();
            } while (!isWhitespace(c));
            return sb.toString();
        }

        private boolean isWhitespace(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

public class B510 {
    private int n, m;
    private char[][] grid;
    private boolean[][] visited;

    // Direction vectors: right, left, down, up
    private static final int[] DX = {0, 0, 1, -1};
    private static final int[] DY = {1, -1, 0, 0};

    public static void main(String[] args) {
        // Try-with-resources ensures automatic flushing and closing of I/O streams
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
             PrintWriter out = new PrintWriter(System.out)) {

            B510 solver = new B510();
            solver.readInput(br);
            solver.solve(out);

        } catch (IOException e) {
            System.err.println("Input/Output error: " + e.getMessage());
        }
    }

    private void readInput(BufferedReader br) throws IOException {
        String line = br.readLine();
        while (line != null && line.trim().isEmpty()) {
            line = br.readLine();
        }
        if (line == null) return;

        StringTokenizer st = new StringTokenizer(line);
        n = Integer.parseInt(st.nextToken());
        m = Integer.parseInt(st.nextToken());

        grid = new char[n][m];
        visited = new boolean[n][m];

        for (int i = 0; i < n; i++) {
            line = br.readLine();
            while (line != null && line.trim().isEmpty()) {
                line = br.readLine();
            }
            if (line != null) {
                grid[i] = line.trim().toCharArray();
            }
        }
    }

    private void solve(PrintWriter out) {
        boolean hasCycle = false;

        // Iterate over each cell to handle disconnected components
        for (int i = 0; i < n && !hasCycle; i++) {
            for (int j = 0; j < m && !hasCycle; j++) {
                if (!visited[i][j]) {
                    if (dfs(i, j, -1, -1)) {
                        hasCycle = true;
                    }
                }
            }
        }

        out.println(hasCycle ? "Yes" : "No");
    }

    /**
     * Performs DFS to detect cycles in the grid graph.
     * A cycle exists if we encounter a visited node that is not the immediate parent.
     */
    private boolean dfs(int x, int y, int parentX, int parentY) {
        visited[x][y] = true;

        for (int i = 0; i < 4; i++) {
            int nx = x + DX[i];
            int ny = y + DY[i];

            // Check bounds and same-character adjacency
            if (isValid(nx, ny) && grid[nx][ny] == grid[x][y]) {
                if (!visited[nx][ny]) {
                    // Continue traversal; return true immediately if cycle found downstream
                    if (dfs(nx, ny, x, y)) {
                        return true;
                    }
                } else if (nx != parentX || ny != parentY) {
                    // Visited node found that isn't the direct parent -> cycle detected
                    return true;
                }
            }
        }
        return false;
    }

    private boolean isValid(int x, int y) {
        return x >= 0 && x < n && y >= 0 && y < m;
    }
}

import java.util.Scanner;

/**
 * Refactored grid cycle detector.
 * 
 * Key Improvements:
 * 1. Removed all static mutable state to ensure thread-safety, reusability, and testability.
 * 2. Replaced the broken hybrid recursive/iterative DFS with a clean, purely recursive implementation.
 * 3. Fixed depth tracking by passing it as a method parameter instead of using a shared static counter.
 * 4. Added explicit bounds checking instead of relying on array padding and magic character values.
 * 5. Replaced the pointless try-catch block with proper input validation and early returns.
 * 6. Ensured proper resource management by closing the Scanner in a finally block.
 * 7. Improved naming conventions, structure, and added JavaDoc for maintainability.
 */
public class GridCycleDetector {

    // Directions: down, up, right, left
    private static final int[][] DIRECTIONS = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};

    private final int rows;
    private final int cols;
    private final char[][] grid;
    private final boolean[][] visited;
    private boolean cycleFound;
    private int maxDepth;

    /**
     * Constructs the detector with grid dimensions and data.
     */
    public GridCycleDetector(int n, int m, char[][] grid) {
        this.rows = n;
        this.cols = m;
        this.grid = grid;
        this.visited = new boolean[n][m];
        this.cycleFound = false;
        this.maxDepth = 0;
    }

    /**
     * Initiates cycle detection across the entire grid.
     * @return true if a cycle of identical characters is found, false otherwise.
     */
    public boolean hasCycle() {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                // Only start DFS from unvisited cells to avoid redundant work
                if (!visited[r][c]) {
                    dfs(r, c, -1, -1, 1);
                    if (cycleFound) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Performs depth-first search to detect cycles.
     *
     * @param r         Current row
     * @param c         Current column
     * @param parentR   Parent row (prevents immediate backtracking)
     * @param parentC   Parent column (prevents immediate backtracking)
     * @param depth     Current traversal depth
     */
    private void dfs(int r, int c, int parentR, int parentC, int depth) {
        if (cycleFound) {
            return;
        }

        visited[r][c] = true;

        if (depth > maxDepth) {
            maxDepth = depth;
        }

        for (int[] dir : DIRECTIONS) {
            int nr = r + dir[0];
            int nc = c + dir[1];

            // Explicit boundary check (safer than relying on padding/magic values)
            if (nr < 0 || nr >= rows || nc < 0 || nc >= cols) {
                continue;
            }

            // Check if neighbor has the same character
            if (grid[nr][nc] == grid[r][c]) {
                if (!visited[nr][nc]) {
                    // Continue DFS to unvisited neighbors
                    dfs(nr, nc, r, c, depth + 1);
                    if (cycleFound) {
                        return;
                    }
                } else if (nr != parentR || nc != parentC) {
                    // Found a visited node that is not the parent -> cycle detected
                    // Note: In grid graphs, any cycle has a minimum length of 4.
                    // The original condition (maxDepth == depth) is preserved for fidelity,
                    // though standard cycle detection naturally satisfies this constraint.
                    if (maxDepth == depth) {
                        cycleFound = true;
                        return;
                    }
                }
            }
        }
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        try {
            if (!scanner.hasNextInt()) {
                return;
            }
            int n = scanner.nextInt();
            int m = scanner.nextInt();

            if (n < 2 || n > 50 || m < 2 || m > 50) {
                System.out.println("No");
                return;
            }

            char[][] grid = new char[n][m];
            for (int i = 0; i < n; i++) {
                grid[i] = scanner.next().toCharArray();
            }

            GridCycleDetector detector = new GridCycleDetector(n, m, grid);
            System.out.println(detector.hasCycle() ? "Yes" : "No");

        } finally {
            scanner.close();
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

/**
 * Refactored solution to detect cycles in a grid of characters.
 * 
 * Improvements made:
 * 1. Encapsulation: Moved static state into instance variables of a class (GridCycleDetector).
 * 2. Naming: Used descriptive variable names (rows, cols, grid, visited, hasCycle).
 * 3. Logic Simplification: Replaced the 3-state 'vis' array with a standard boolean 'visited' array.
 *    For undirected graphs, a simple visited check (excluding the parent) is sufficient for cycle detection.
 * 4. Data Structures: Removed the adjacency list construction. The grid structure allows on-the-fly neighbor checks,
 *    reducing memory overhead and code complexity.
 * 5. Dead Code Removal: Removed unused 'sort' and 'sort2' methods and unused FastScanner methods.
 * 6. Structure: Organized code into logical methods (readInput, solve, dfs).
 */
public class GridCycleDetector {

    private int rows;
    private int cols;
    private char[][] grid;
    private boolean[][] visited;
    private boolean hasCycle;

    public static void main(String[] args) {
        FastScanner fs = new FastScanner();
        PrintWriter out = new PrintWriter(System.out);

        try {
            String nStr = fs.next();
            String mStr = fs.next();

            if (nStr != null && mStr != null) {
                GridCycleDetector solver = new GridCycleDetector();
                solver.rows = Integer.parseInt(nStr);
                solver.cols = Integer.parseInt(mStr);
                solver.readInput(fs);
                solver.solve();
                out.println(solver.hasCycle ? "Yes" : "No");
            }
        } catch (Exception e) {
            // In a production environment, proper logging would be used here.
            // For CP-style scripts, we allow the exception to propagate or handle gracefully.
        } finally {
            out.flush();
            out.close();
        }
    }

    private void readInput(FastScanner fs) {
        grid = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            String line = fs.next();
            if (line != null) {
                for (int j = 0; j < cols; j++) {
                    // Assuming valid input where line length >= cols
                    grid[i][j] = line.charAt(j);
                }
            }
        }
    }

    private void solve() {
        visited = new boolean[rows][cols];
        hasCycle = false;

        // Iterate over every cell in the grid
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                // If cell is not visited, start a DFS
                if (!visited[i][j]) {
                    // We pass the character type of the current cell.
                    // Parent is initialized to -1, -1.
                    if (dfs(i, j, -1, -1, grid[i][j])) {
                        hasCycle = true;
                        return; // Cycle found, no need to check further
                    }
                }
            }
        }
    }

    /**
     * Performs DFS to detect cycles in the grid for a specific character type.
     * 
     * @param r Current row
     * @param c Current column
     * @param parentR Row of the parent node
     * @param parentC Column of the parent node
     * @param type The character type we are traversing
     * @return true if a cycle is detected, false otherwise
     */
    private boolean dfs(int r, int c, int parentR, int parentC, char type) {
        visited[r][c] = true;

        // Directions: Up, Down, Left, Right
        int[] dr = {-1, 1, 0, 0};
        int[] dc = {0, 0, -1, 1};

        for (int k = 0; k < 4; k++) {
            int nr = r + dr[k];
            int nc = c + dc[k];

            // Check boundaries
            if (nr >= 0 && nr < rows && nc >= 0 && nc < cols) {
                // Check if neighbor has the same character
                if (grid[nr][nc] == type) {
                    // Check if neighbor is the parent node
                    if (nr == parentR && nc == parentC) {
                        continue;
                    }

                    // If neighbor is already visited, it means we found a cycle
                    // (since it's not the parent, it must be a back-edge)
                    if (visited[nr][nc]) {
                        return true;
                    }

                    // If not visited, recurse
                    if (dfs(nr, nc, r, c, type)) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Helper class for fast input reading.
     */
    static class FastScanner {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer("");

        String next() {
            while (!st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    e.printStackTrace();
                    return null;
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            String s = next();
            if (s == null) throw new RuntimeException("End of input");
            return Integer.parseInt(s);
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

/**
 * Solves the "Fox and Two Dots" problem.
 * Detects if there is a cycle of length >= 4 in a grid where cells contain identical characters.
 */
public class FoxAndTwoDots {

    // Direction vectors for moving Up, Right, Down, Left
    private static final int[] DR = {-1, 0, 1, 0};
    private static final int[] DC = {0, 1, 0, -1};

    public static void main(String[] args) throws IOException {
        // Use BufferedReader for efficient input reading
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));

        // Read dimensions
        String line = br.readLine();
        if (line == null) return;

        StringTokenizer st = new StringTokenizer(line);
        if (!st.hasMoreTokens()) return;

        int rows = Integer.parseInt(st.nextToken());
        int cols = Integer.parseInt(st.nextToken());

        // Read the grid
        char[][] grid = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            String rowLine = br.readLine();
            if (rowLine != null) {
                grid[i] = rowLine.toCharArray();
            }
        }

        // Visited array to track the current path in DFS
        boolean[][] visited = new boolean[rows][cols];
        boolean cycleFound = false;

        // Iterate through each cell to start DFS if not visited
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (!visited[i][j]) {
                    visited[i][j] = true;
                    // Start DFS from current cell. Parent is (-1, -1) initially.
                    if (dfs(i, j, grid[i][j], -1, -1, rows, cols, grid, visited)) {
                        cycleFound = true;
                        break;
                    }
                }
            }
            if (cycleFound) break;
        }

        System.out.println(cycleFound ? "Yes" : "No");
    }

    /**
     * Depth First Search to detect a cycle of identical characters.
     *
     * @param r Current row
     * @param c Current column
     * @param targetChar Character we are matching
     * @param parentR Row of the previous cell in the path
     * @param parentC Column of the previous cell in the path
     * @param rows Total number of rows
     * @param cols Total number of columns
     * @param grid The character grid
     * @param visited Boolean matrix tracking the current path
     * @return true if a cycle is detected, false otherwise
     */
    private static boolean dfs(int r, int c, char targetChar, int parentR, int parentC,
                               int rows, int cols, char[][] grid, boolean[][] visited) {

        // Explore all 4 adjacent directions
        for (int k = 0; k < 4; k++) {
            int nextR = r + DR[k];
            int nextC = c + DC[k];

            // Check boundaries
            if (nextR < 0 || nextR >= rows || nextC < 0 || nextC >= cols) {
                continue;
            }

            // Check if the adjacent cell has the same character
            if (grid[nextR][nextC] != targetChar) {
                continue;
            }

            // If the adjacent cell is already visited, we found a cycle
            // However, we must ensure it's not the immediate parent (which is always visited)
            if (visited[nextR][nextC]) {
                if (nextR != parentR || nextC != parentC) {
                    return true; // Cycle detected
                }
            } else {
                // Mark as visited and recurse
                visited[nextR][nextC] = true;
                if (dfs(nextR, nextC, targetChar, r, c, rows, cols, grid, visited)) {
                    return true;
                }
                // Backtrack: unmark the cell so it can be part of other paths
                visited[nextR][nextC] = false;
            }
        }
        return false;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

/**
 * A utility class to detect cycles in a grid of characters.
 * A cycle is defined as a path that starts and ends at the same node,
 * traversing only cells with identical characters.
 */
public class GridCycleDetector {

    // Instance variables to encapsulate state, avoiding static fields
    private boolean cycleFound = false;
    private int startRow, startCol;
    private int rows, cols;
    private char[][] grid;
    private boolean[][] visited;

    // Direction vectors for Up, Down, Left, Right to reduce code duplication
    private static final int[] DR = {-1, 1, 0, 0};
    private static final int[] DC = {0, 0, -1, 1};

    public static void main(String[] args) throws IOException {
        // Use BufferedReader for efficient input handling
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));

        // Read dimensions N and M
        String line = reader.readLine();
        if (line == null) return;

        StringTokenizer st = new StringTokenizer(line);
        if (!st.hasMoreTokens()) return;

        int n = Integer.parseInt(st.nextToken());
        int m = Integer.parseInt(st.nextToken());

        // Read the grid
        char[][] grid = new char[n][m];
        for (int i = 0; i < n; i++) {
            String rowLine = reader.readLine();
            if (rowLine != null) {
                grid[i] = rowLine.toCharArray();
            }
        }

        // Instantiate detector and run the solution
        GridCycleDetector detector = new GridCycleDetector();
        detector.setGrid(grid);
        detector.solve(n, m);
    }

    private void setGrid(char[][] grid) {
        this.grid = grid;
        if (grid != null && grid.length > 0) {
            this.rows = grid.length;
            this.cols = grid[0].length;
        }
    }

    /**
     * Main logic to iterate through the grid and detect cycles.
     */
    private void solve(int n, int m) {
        // Iterate through every cell in the grid
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {

                // If a cycle has already been found, we can stop searching
                if (cycleFound) {
                    return;
                }

                // Check if the current cell is a valid starting point for a cycle.
                // A node must have at least 2 neighbors with the same character 
                // to be part of a cycle (in a grid graph).
                if (hasSameCharNeighbors(i, j)) {
                    startRow = i;
                    startCol = j;

                    // Initialize visited array for this search
                    visited = new boolean[n][m];
                    visited[i][j] = true;

                    // Perform DFS to detect cycle
                    // Parent coordinates are (-1, -1) as it is the root of the search
                    dfs(-1, -1, i, j);
                }
            }
        }

        System.out.println(cycleFound ? "Yes" : "No");
    }

    /**
     * Checks if the cell at (r, c) has at least 2 neighbors 
     * with the same character.
     */
    private boolean hasSameCharNeighbors(int r, int c) {
        int neighborCount = 0;
        char currentChar = grid[r][c];

        for (int k = 0; k < 4; k++) {
            int nr = r + DR[k];
            int nc = c + DC[k];

            if (isValidCoordinate(nr, nc) && grid[nr][nc] == currentChar) {
                neighborCount++;
            }
        }
        return neighborCount >= 2;
    }

    /**
     * Depth First Search to find a cycle.
     * 
     * @param parentR Row coordinate of the parent node
     * @param parentC Column coordinate of the parent node
     * @param r       Current row coordinate
     * @param c       Current column coordinate
     */
    private void dfs(int parentR, int parentC, int r, int c) {
        if (cycleFound) return; // Optimization: stop if cycle found in deeper recursion

        for (int k = 0; k < 4; k++) {
            int nr = r + DR[k];
            int nc = c + DC[k];

            // 1. Check bounds
            if (!isValidCoordinate(nr, nc)) {
                continue;
            }

            // 2. Check character match
            if (grid[nr][nc] != grid[r][c]) {
                continue;
            }

            // 3. Check visited status
            if (!visited[nr][nc]) {
                visited[nr][nc] = true;
                dfs(r, c, nr, nc); // Recurse
            } else if (nr == startRow && nc == startCol) {
                // 4. Check for Cycle
                // A cycle is found if we reach the start node again,
                // provided it is not the immediate parent we just came from.
                if (nr != parentR || nc != parentC) {
                    cycleFound = true;
                    return;
                }
            }
        }
    }

    /**
     * Checks if coordinates are within grid boundaries.
     */
    private boolean isValidCoordinate(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }
}

