     */
    static class GridCycleDetector {
        private int rows;
        private int cols;
        private char[][] grid;
        private boolean[][] visited;

        /**
         * Reads the grid from input and determines if a cycle exists.
         */
        public void solve(Scanner sc, PrintWriter out) {
            rows = sc.nextInt();
            cols = sc.nextInt();
            grid = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                grid[i] = sc.next().toCharArray();
            }

            visited = new boolean[rows][cols];
            boolean foundCycle = false;

            // Iterate over each cell to handle disconnected components
            for (int i = 0; i < rows && !foundCycle; i++) {
                for (int j = 0; j < cols && !foundCycle; j++) {
                    if (!visited[i][j]) {
                        if (hasCycle(i, j, -1, -1)) {
                            foundCycle = true;
                        }
                    }
                }
            }

            out.println(foundCycle ? "Yes" : "No");
        }

        /**
         * Performs DFS to detect cycles in the grid.
         *
         * @param r Current row
         * @param c Current column
         * @param prevR Previous row (to avoid traversing back to parent)
         * @param prevC Previous column
         * @return true if a cycle is found, false otherwise
         */
        private boolean hasCycle(int r, int c, int prevR, int prevC) {
            visited[r][c] = true;
            int[] dr = {-1, 1, 0, 0};
            int[] dc = {0, 0, -1, 1};

            for (int i = 0; i < 4; i++) {
                int nr = r + dr[i];
                int nc = c + dc[i];

                if (nr >= 0 && nr < rows && nc >= 0 && nc < cols) {
                    if (grid[nr][nc] == grid[r][c]) {
                        if (visited[nr][nc]) {
                            // Found a visited cell that is not the immediate parent -> cycle detected
                            if (nr != prevR || nc != prevC) {
                                return true;
                            }
                        } else {
                            // Continue DFS traversal
                            if (hasCycle(nr, nc, r, c)) {
                                return true;
                            }
                        }
                    }
                }
            }
            return false;
        }
    }
}

