/**
 * Solves Codeforces 510B - Fox And Two Dots.
 * Determines if there exists a cycle of identical characters in a 2D grid.
 * 
 * Refactoring improvements:
 * - Removed global mutable state (static flags and stacks) for thread-safety and testability.
 * - Replaced String[][] with char[][] for better performance and to fix unsafe string comparisons.
 * - Eliminated artificial padding by using a clean boundary-checking method.
 * - Replaced manual stack management with standard DFS using parent tracking.
 * - Used direction arrays to reduce code duplication and improve readability.
 * - Added early termination and proper resource management.
 */
public class CodeForce510B {

    // Direction vectors for moving up, down, left, right
    private static final int[] DX = {-1, 1, 0, 0};
    private static final int[] DY = {0, 0, -1, 1};

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        if (!scanner.hasNextInt()) {
            scanner.close();
            return;
        }

        int n = scanner.nextInt();
        int m = scanner.nextInt();

        char[][] grid = new char[n][m];
        for (int i = 0; i < n; i++) {
            grid[i] = scanner.next().toCharArray();
        }

        boolean[][] visited = new boolean[n][m];
        boolean hasCycle = false;

        // Iterate through each cell to handle disconnected components
        for (int i = 0; i < n && !hasCycle; i++) {
            for (int j = 0; j < m && !hasCycle; j++) {
                if (!visited[i][j]) {
                    hasCycle = dfs(grid, visited, i, j, -1, -1);
                }
            }
        }

        System.out.println(hasCycle ? "Yes" : "No");
        scanner.close();
    }

    /**
     * Performs Depth-First Search to detect cycles in the grid.
     *
     * @param grid       The character grid
     * @param visited    Tracks visited cells to avoid reprocessing
     * @param x          Current row index
     * @param y          Current column index
     * @param parentX    Parent row index (prevents immediate backtracking)
     * @param parentY    Parent column index
     * @return true if a cycle is detected, false otherwise
     */
    private static boolean dfs(char[][] grid, boolean[][] visited, int x, int y, int parentX, int parentY) {
        visited[x][y] = true;

        for (int k = 0; k < 4; k++) {
            int nx = x + DX[k];
            int ny = y + DY[k];

            if (isValid(nx, ny, grid) && grid[nx][ny] == grid[x][y]) {
                if (!visited[nx][ny]) {
                    // Recurse if neighbor is unvisited
                    if (dfs(grid, visited, nx, ny, x, y)) {
                        return true;
                    }
                } else if (nx != parentX || ny != parentY) {
                    // Cycle detected: neighbor is visited but not the immediate parent
                    return true;
                }
            }
        }
        return false;
    }

    /**
     * Checks if the given coordinates are within grid bounds.
     */
    private static boolean isValid(int x, int y, char[][] grid) {
        return x >= 0 && x < grid.length && y >= 0 && y < grid[0].length;
    }
}

