/**
 * Solves the grid cycle detection problem.
 * Determines if there exists a cycle of length >= 3 where adjacent cells share the same value.
 */
public class B {

    // Direction vectors for moving up, down, left, right
    private static final int[] DX = {1, -1, 0, 0};
    private static final int[] DY = {0, 0, 1, -1};

    // I/O helpers
    private BufferedReader reader;
    private PrintWriter writer;
    private StringTokenizer tokenizer;

    // Grid state
    private int[][] grid;
    private boolean[][] visited;
    private int rows;
    private int cols;

    public static void main(String[] args) throws IOException {
        B solver = new B();
        solver.init();
        try {
            solver.solve();
        } finally {
            solver.cleanup();
        }
    }

    /**
     * Initializes I/O streams and tokenizer.
     */
    private void init() {
        reader = new BufferedReader(new InputStreamReader(System.in));
        writer = new PrintWriter(new OutputStreamWriter(System.out));
        tokenizer = new StringTokenizer("");
    }

    /**
     * Ensures output is flushed and resources are closed.
     */
    private void cleanup() {
        writer.flush();
        writer.close();
    }

    /**
     * Reads the next token from input, handling line breaks and EOF gracefully.
     */
    private String nextToken() throws IOException {
        while (!tokenizer.hasMoreTokens()) {
            String line = reader.readLine();
            if (line == null) {
                return null;
            }
            tokenizer = new StringTokenizer(line);
        }
        return tokenizer.nextToken();
    }

    /**
     * Parses the next token as an integer.
     */
    private int nextInt() throws IOException {
        String token = nextToken();
        if (token == null) {
            throw new IOException("Unexpected end of input");
        }
        return Integer.parseInt(token);
    }

    /**
     * Main solving logic. Reads input, runs cycle detection, and outputs the result.
     */
    public void solve() throws IOException {
        rows = nextInt();
        cols = nextInt();

        grid = new int[rows][cols];
        visited = new boolean[rows][cols];

        // Read grid characters and map 'A'-'Z' to 1-26
        for (int i = 0; i < rows; i++) {
            String line = nextToken();
            for (int j = 0; j < cols; j++) {
                grid[i][j] = line.charAt(j) - 'A' + 1;
            }
        }

        boolean cycleFound = false;
        // Iterate over each cell to start DFS on unvisited components
        for (int i = 0; i < rows && !cycleFound; i++) {
            for (int j = 0; j < cols && !cycleFound; j++) {
                if (!visited[i][j]) {
                    if (hasCycle(i, j, -1, -1)) {
                        cycleFound = true;
                    }
                }
            }
        }

        writer.println(cycleFound ? "Yes" : "No");
    }

    /**
     * Performs DFS to detect cycles in an undirected grid component.
     * 
     * @param x         Current row
     * @param y         Current column
     * @param parentX   Parent row (to avoid false cycle detection on the edge we came from)
     * @param parentY   Parent column
     * @return true if a cycle is detected, false otherwise
     */
    private boolean hasCycle(int x, int y, int parentX, int parentY) {
        visited[x][y] = true;

        for (int dir = 0; dir < 4; dir++) {
            int nx = x + DX[dir];
            int ny = y + DY[dir];

            // Check bounds and same-value adjacency
            if (nx >= 0 && nx < rows && ny >= 0 && ny < cols && grid[nx][ny] == grid[x][y]) {
                if (!visited[nx][ny]) {
                    // Continue DFS to unvisited neighbor
                    if (hasCycle(nx, ny, x, y)) {
                        return true;
                    }
                } else if (nx != parentX || ny != parentY) {
                    // Found a visited node that isn't the immediate parent => cycle detected
                    return true;
                }
            }
        }
        return false;
    }
}

import java.util.Scanner;

public class Main {

    /**
     * Performs Depth-First Search to find a valid path/cycle configuration.
     *
     * @param current       The node currently being visited.
     * @param colorVisited  Tracks which colors have already been processed.
     * @return true if the target condition is met, false otherwise.
     */
    private static boolean dfs(Node current, boolean[] colorVisited) {
        current.visited = true;

        // Check all four cardinal directions
        Node[] neighbors = {current.up, current.down, current.left, current.right};

        for (Node neighbor : neighbors) {
            if (neighbor == null) {
                continue;
            }

            // Target condition: neighbor is marked as start (first) and not end (second)
            // Note: Fixed original typo where it checked !A.second instead of !neighbor.second
            if (neighbor.first && !neighbor.second) {
                colorVisited[current.color - 'A'] = true;
                return true;
            }

            // Recurse into unvisited neighbors
            if (!neighbor.visited) {
                if (current.first) {
                    neighbor.second = true;
                }
                if (dfs(neighbor, colorVisited)) {
                    return true;
                }
            }
        }
        return false;
    }

    /**
     * Checks if a node has at least two valid neighbors.
     */
    private static boolean hasAtLeastTwoNeighbors(Node node) {
        int count = 0;
        if (node.up != null) count++;
        if (node.down != null) count++;
        if (node.left != null) count++;
        if (node.right != null) count++;
        return count >= 2;
    }

    public static void main(String[] args) {
        // Use try-with-resources to automatically close the scanner
        try (Scanner scanner = new Scanner(System.in)) {
            if (!scanner.hasNextInt()) {
                return;
            }
            int rows = scanner.nextInt();
            int cols = scanner.nextInt();

            boolean[] colorVisited = new boolean[26]; // Assumes uppercase letters A-Z
            Node[][] grid = new Node[rows][cols];

            // Read grid input and initialize nodes
            for (int i = 0; i < rows; i++) {
                String line = scanner.next();
                for (int j = 0; j < cols; j++) {
                    grid[i][j] = new Node();
                    grid[i][j].setColor(line.charAt(j));
                }
            }

            // Build adjacency links based on matching colors
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    Node current = grid[i][j];
                    if (i > 0 && grid[i - 1][j].color == current.color) {
                        current.up = grid[i - 1][j];
                    }
                    if (i < rows - 1 && grid[i + 1][j].color == current.color) {
                        current.down = grid[i + 1][j];
                    }
                    if (j > 0 && grid[i][j - 1].color == current.color) {
                        current.left = grid[i][j - 1];
                    }
                    if (j < cols - 1 && grid[i][j + 1].color == current.color) {
                        current.right = grid[i][j + 1];
                    }
                }
            }

            // Traverse grid and run DFS from eligible starting points
            boolean found = false;
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    Node node = grid[i][j];
                    if (!node.visited && !colorVisited[node.color - 'A'] && hasAtLeastTwoNeighbors(node)) {
                        node.setFirst(true);
                        if (dfs(node, colorVisited)) {
                            found = true;
                            break;
                        }
                    }
                }
                if (found) {
                    break;
                }
            }

            System.out.print(found ? "Yes" : "No");
        }
    }

    /**
     * Represents a cell in the grid with directional connections and state flags.
     */
    static class Node {
        Node up, down, left, right;
        char color;
        boolean visited;
        boolean first;
        boolean second;

        public void setColor(char c) {
            this.color = c;
        }

        public void setFirst(boolean f) {
            this.first = f;
        }

        public void setSecond(boolean s) {
            this.second = s;
        }
    }
}

