public class DifferentStrings {
    // Direction vectors for moving up, down, left, right
    private static final int[] ROW_DIRS = {-1, 1, 0, 0};
    private static final int[] COL_DIRS = {0, 0, -1, 1};

    private final int rows;
    private final int cols;
    private final char[][] grid;
    private final boolean[][] visited;

    public DifferentStrings(int rows, int cols, char[][] grid) {
        this.rows = rows;
        this.cols = cols;
        this.grid = grid;
        this.visited = new boolean[rows][cols];
    }

    /**
     * Checks if the grid contains any cycle formed by identical characters.
     */
    public boolean hasCycle() {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (!visited[r][c]) {
                    if (dfs(r, c, -1, -1, grid[r][c])) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Performs DFS to detect cycles in the grid graph.
     *
     * @param r           Current row
     * @param c           Current column
     * @param parentR     Parent row (to avoid immediate backtracking)
     * @param parentC     Parent column (to avoid immediate backtracking)
     * @param targetChar  Character type we are traversing
     * @return true if a cycle is detected, false otherwise
     */
    private boolean dfs(int r, int c, int parentR, int parentC, char targetChar) {
        visited[r][c] = true;
        for (int i = 0; i < 4; i++) {
            int nextR = r + ROW_DIRS[i];
            int nextC = c + COL_DIRS[i];

            // Skip the immediate parent to prevent false cycle detection
            if (nextR == parentR && nextC == parentC) {
                continue;
            }

            // Check bounds and character match
            if (isValid(nextR, nextC) && grid[nextR][nextC] == targetChar) {
                // If we encounter a visited node that isn't the parent, a back-edge exists (cycle)
                if (visited[nextR][nextC]) {
                    return true;
                }
                if (dfs(nextR, nextC, r, c, targetChar)) {
                    return true;
                }
            }
        }
        return false;
    }

    /**
     * Validates grid coordinates.
     */
    private boolean isValid(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    public static void main(String[] args) {
        try (Scanner sc = new Scanner(System.in)) {
            if (!sc.hasNextInt()) return;
            int n = sc.nextInt();
            int m = sc.nextInt();
            char[][] grid = new char[n][m];
            for (int i = 0; i < n; i++) {
                grid[i] = sc.next().toCharArray();
            }

            DifferentStrings detector = new DifferentStrings(n, m, grid);
            System.out.println(detector.hasCycle() ? "Yes" : "No");
        }
    }
}

