class TaskA {
    private static final int MIN_CYCLE_LENGTH = 4;
    private static final int[] DR = {-1, 1, 0, 0};
    private static final int[] DC = {0, 0, -1, 1};

    public void solve(InputReader in, PrintWriter out) {
        int n = in.nextInt();
        int m = in.nextInt();
        char[][] grid = new char[n][m];
        int[] charFrequency = new int[26];

        // Read grid and count character frequencies
        for (int i = 0; i < n; i++) {
            String row = in.next();
            grid[i] = row.toCharArray();
            for (int j = 0; j < m; j++) {
                charFrequency[grid[i][j] - 'A']++;
            }
        }

        boolean cycleFound = false;
        boolean[][] visited = new boolean[n][m];

        // Iterate over each cell to start DFS if character count is sufficient
        for (int i = 0; i < n && !cycleFound; i++) {
            for (int j = 0; j < m && !cycleFound; j++) {
                char currentChar = grid[i][j];
                if (charFrequency[currentChar - 'A'] >= MIN_CYCLE_LENGTH && !visited[i][j]) {
                    if (hasCycle(i, j, -1, -1, 1, visited, grid)) {
                        cycleFound = true;
                    }
                }
            }
        }

        out.println(cycleFound ? "Yes" : "No");
    }

    private boolean hasCycle(int r, int c, int prevR, int prevC, int depth, boolean[][] visited, char[][] grid) {
        visited[r][c] = true;
        int rows = grid.length;
        int cols = grid[0].length;

        for (int k = 0; k < 4; k++) {
            int nr = r + DR[k];
            int nc = c + DC[k];

            // Check bounds and character match
            if (nr >= 0 && nr < rows && nc >= 0 && nc < cols && grid[nr][nc] == grid[r][c]) {
                // Skip the immediate parent to avoid false cycle detection
                if (nr == prevR && nc == prevC) {
                    continue;
                }

                if (visited[nr][nc]) {
                    // Found a back-edge. In a grid, any cycle is at least length 4.
                    // If current path depth is >= 4, we've found a valid cycle.
                    if (depth >= MIN_CYCLE_LENGTH) {
                        return true;
                    }
                } else {
                    if (hasCycle(nr, nc, r, c, depth + 1, visited, grid)) {
                        return true;
                    }
                }
            }
        }
        return false;
    }
}

class InputReader {
