/**
 * A refactored solution to detect if a grid contains a cycle of adjacent identical characters.
 * 
 * Refactoring Improvements:
 * 1. Removed Global State: Moved 'm' and 'n' from static fields to local variables/instance fields.
 * 2. Algorithm Optimization: Replaced the O((NM)^2) brute-force approach (resetting visited arrays 
 *    for every cell) with a standard O(NM) Depth First Search (DFS) cycle detection.
 * 3. Readability: Used descriptive variable names (rows, cols, grid, visited) instead of m, n, g.
 * 4. Robustness: Used StringTokenizer for safer integer parsing and try-with-resources for stream management.
 * 5. Maintainability: Encapsulated logic into methods (hasCycle, dfs) with clear JavaDoc comments.
 * 6. Cleaned up Index Logic: Replaced complex arithmetic index calculations with direction arrays.
 */
public class Main {

    private int rows;
    private int cols;
    private char[][] grid;
    private boolean[][] visited;

    public Main(int rows, int cols, char[][] grid) {
        this.rows = rows;
        this.cols = cols;
        this.grid = grid;
        // Initialize visited array to keep track of processed cells in the current traversal
        this.visited = new boolean[rows][cols];
    }

    public static void main(String[] args) throws IOException {
        // Use try-with-resources to ensure the BufferedReader is closed automatically
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            String line = br.readLine();
            if (line == null) return;

            // Use StringTokenizer to handle potential multiple spaces between numbers
            StringTokenizer st = new StringTokenizer(line);
            if (!st.hasMoreTokens()) return;

            int n = Integer.parseInt(st.nextToken());
            int m = Integer.parseInt(st.nextToken());

            char[][] grid = new char[n][];
            for (int i = 0; i < n; i++) {
                String rowStr = br.readLine();
                if (rowStr != null) {
                    // Store the row characters. 
                    // Note: Assumes input rows are well-formed strings.
                    grid[i] = rowStr.toCharArray();
                } else {
                    grid[i] = new char[0];
                }
            }

            Main solver = new Main(n, m, grid);
            // Output "Yes" if a cycle is found, otherwise "No"
            System.out.println(solver.hasCycle() ? "Yes" : "No");
        }
    }

    /**
     * Determines if there is a cycle in the grid formed by adjacent identical characters.
     * 
     * @return true if a cycle exists, false otherwise.
     */
    public boolean hasCycle() {
        // Iterate over every cell in the grid to handle disconnected components
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                // If the cell hasn't been visited in any previous traversal, start a DFS
                if (!visited[r][c]) {
                    // Pass -1, -1 to indicate no parent node initially
                    if (dfs(r, c, -1, -1)) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Performs a Depth First Search (DFS) to detect cycles in the grid.
     * 
     * @param r Current row index
     * @param c Current column index
     * @param pR Parent row index (to prevent traversing back up the immediate edge)
     * @param pC Parent column index
     * @return true if a cycle is detected, false otherwise
     */
    private boolean dfs(int r, int c, int pR, int pC) {
        visited[r][c] = true;

        // Directions: Up, Left, Down, Right
        int[] dr = {-1, 0, 1, 0};
        int[] dc = {0, -1, 0, 1};

        for (int k = 0; k < 4; k++) {
            int nr = r + dr[k];
            int nc = c + dc[k];

            // Check if neighbor is within grid boundaries
            if (nr >= 0 && nr < rows && nc >= 0 && nc < cols) {
                // If the neighbor is the node we just came from, skip it (avoid immediate backtrack)
                if (nr == pR && nc == pC) {
                    continue;
                }

                // Check if the neighbor has the same character as the current cell
                // Safety check for ragged arrays, though input is expected to be rectangular
                if (nc < grid[nr].length && grid[nr][nc] == grid[r][c]) {

                    // If the neighbor is already visited, we found a cycle
                    if (visited[nr][nc]) {
                        return true;
                    }

                    // Recursively visit the neighbor
                    if (dfs(nr, nc, r, c)) {
                        return true;
                    }
                }
            }
        }
        return false;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.LinkedList;
import java.util.Queue;

public class FoxDots {

    /**
     * Helper class to store grid coordinates and parent information for BFS traversal.
     * Storing the parent allows us to distinguish between the edge we just traversed
     * and a back-edge that indicates a cycle.
     */
    private static class Coordinate {
        int r, c;
        int parentR, parentC;

        public Coordinate(int r, int c, int parentR, int parentC) {
            this.r = r;
            this.c = c;
            this.parentR = parentR;
            this.parentC = parentC;
        }
    }

    public static void main(String[] args) throws IOException {
        // Use BufferedReader for efficient input reading
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));

        // Read dimensions N and M
        String line = br.readLine();
        if (line == null) return;

        // Robust splitting of input string handling multiple spaces
        String[] parts = line.trim().split("\\s+");
        int n = Integer.parseInt(parts[0]);
        int m = Integer.parseInt(parts[1]);

        // Read the grid
        char[][] grid = new char[n][m];
        for (int i = 0; i < n; i++) {
            String row = br.readLine();
            if (row != null) {
                grid[i] = row.trim().toCharArray();
            }
        }

        boolean[][] visited = new boolean[n][m];
        boolean cycleFound = false;

        // Direction vectors for moving Up, Down, Left, Right
        int[] dRow = {-1, 1, 0, 0};
        int[] dCol = {0, 0, -1, 1};

        // Iterate through every cell to handle disconnected components
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                // If the cell hasn't been visited, start a BFS from here
                if (!visited[i][j]) {
                    if (hasCycleBFS(i, j, n, m, grid, visited, dRow, dCol)) {
                        cycleFound = true;
                        break;
                    }
                }
            }
            if (cycleFound) break;
        }

        System.out.println(cycleFound ? "Yes" : "No");
    }

    /**
     * Performs BFS to detect cycles in the connected component of identical characters.
     * 
     * @param startR Starting row index
     * @param startC Starting column index
     * @param n Number of rows
     * @param m Number of columns
     * @param grid The character grid
     * @param visited Visited tracking matrix
     * @param dRow Direction array for rows
     * @param dCol Direction array for columns
     * @return true if a cycle is found, false otherwise
     */
    private static boolean hasCycleBFS(int startR, int startC, int n, int m,
                                       char[][] grid, boolean[][] visited,
                                       int[] dRow, int[] dCol) {
        Queue<Coordinate> queue = new LinkedList<>();

        // Initialize BFS
        // Parent is set to -1, -1 to indicate no parent for the starting node
        queue.add(new Coordinate(startR, startC, -1, -1));
        visited[startR][startC] = true;

        while (!queue.isEmpty()) {
            Coordinate current = queue.poll();

            // Explore all 4 neighbors
            for (int k = 0; k < 4; k++) {
                int r = current.r + dRow[k];
                int c = current.c + dCol[k];

                // Check boundaries
                if (r >= 0 && r < n && c >= 0 && c < m) {
                    // Check if the neighbor has the same character
                    if (grid[r][c] == grid[current.r][current.c]) {
                        if (!visited[r][c]) {
                            // If not visited, mark as visited and add to queue
                            // The current node becomes the parent of the neighbor
                            visited[r][c] = true;
                            queue.add(new Coordinate(r, c, current.r, current.c));
                        } else {
                            // If visited, check if it is the parent node.
                            // If it is visited and NOT the parent, a cycle exists.
                            if (r != current.parentR || c != current.parentC) {
                                return true;
                            }
                        }
                    }
                }
            }
        }
        return false;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

public class R290B {
    // Instance fields replace static state, improving testability, reusability, and thread safety
    private char[][] grid;
    private boolean[][] visited;
    private int rows, cols;

    // Direction vectors for adjacent cells (right, left, down, up)
    private static final int[][] DIRECTIONS = {{0, 1}, {0, -1}, {1, 0}, {-1, 0}};

    public static void main(String[] args) {
        R290B solver = new R290B();
        solver.run();
    }

    private void run() {
        FastScanner scanner = new FastScanner();
        PrintWriter out = new PrintWriter(System.out);

        try {
            String nStr = scanner.next();
            if (nStr == null) return;

            rows = Integer.parseInt(nStr);
            cols = scanner.nextInt();

            grid = new char[rows][cols];
            visited = new boolean[rows][cols];

            for (int i = 0; i < rows; i++) {
                grid[i] = scanner.next().toCharArray();
            }

            boolean cycleDetected = false;
            for (int i = 0; i < rows && !cycleDetected; i++) {
                for (int j = 0; j < cols && !cycleDetected; j++) {
                    if (!visited[i][j]) {
                        // Start DFS from unvisited cells; pass (-1, -1) as parent for the root
                        if (dfs(i, j, -1, -1)) {
                            cycleDetected = true;
                        }
                    }
                }
            }

            out.println(cycleDetected ? "Yes" : "No");
        } catch (Exception e) {
            // Graceful fallback for unexpected input or runtime errors
            out.println("No");
        } finally {
            out.flush();
        }
    }

    /**
     * Depth-First Search to detect cycles in the grid graph.
     * Edges connect adjacent cells containing the same character.
     *
     * @param r current row index
     * @param c current column index
     * @param pr parent row index in the DFS tree
     * @param pc parent column index in the DFS tree
     * @return true if a cycle is detected, false otherwise
     */
    private boolean dfs(int r, int c, int pr, int pc) {
        visited[r][c] = true;
        for (int[] dir : DIRECTIONS) {
            int nr = r + dir[0];
            int nc = c + dir[1];

            if (isValid(nr, nc) && grid[r][c] == grid[nr][nc]) {
                if (visited[nr][nc]) {
                    // If we encounter a visited node that is not the immediate parent, a cycle exists
                    if (nr != pr || nc != pc) {
                        return true;
                    }
                } else {
                    if (dfs(nr, nc, r, c)) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    private boolean isValid(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /**
     * Lightweight fast I/O helper to replace the bulky original InputReader.
     * Uses standard Java I/O classes for better readability and maintainability.
     */
    private static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input", e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            String s = next();
            return s == null ? 0 : Integer.parseInt(s);
        }
    }
}

