/**
 * TaskB: Solves the grid cycle detection problem.
 * Checks if there exists a cycle of length >= 3 (edges) in the grid.
 */
class TaskB {

    // Directions: Right, Left, Down, Up
    private static final int[][] DIRECTIONS = {
        {0, 1}, {0, -1}, {1, 0}, {-1, 0}
    };

    /**
     * Solves the problem by reading input and checking for cycles.
     */
    public void solve(InputReader in, PrintWriter out) {
        int n = in.nextInt();
        int m = in.nextInt();

        char[][] grid = new char[n][m];
        for (int i = 0; i < n; i++) {
            String row = in.next();
            grid[i] = row.toCharArray();
        }

        boolean foundCycle = false;

        // Iterate through every cell to treat it as a potential start of a cycle
        outerLoop:
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < m; c++) {
                // Reset visited array for each starting position
                boolean[][] visited = new boolean[n][m];

                if (hasCycle(grid, visited, r, c, r, c, 0)) {
                    foundCycle = true;
                    break outerLoop;
                }
            }
        }

        out.println(foundCycle ? "Yes" : "No");
    }

    /**
     * Checks if a valid cycle exists starting from (startR, startC).
     * 
     * @param grid The character grid
     * @param visited 2D boolean array to track visited cells in current path
     * @param startR Row index of the start node
     * @param startC Column index of the start node
     * @param currR Current row index
     * @param currC Current column index
     * @param steps Number of steps taken from the start node
     * @return true if a cycle of length >= 3 is found, false otherwise
     */
    private boolean hasCycle(char[][] grid, boolean[][] visited, 
                             int startR, int startC, 
                             int currR, int currC, int steps) {

        visited[currR][currC] = true;

        for (int[] dir : DIRECTIONS) {
            int nextR = currR + dir[0];
            int nextC = currC + dir[1];

            // Check if neighbor is the start node (cycle closing)
            if (nextR == startR && nextC == startC) {
                if (steps >= 3) {
                    return true;
                }
            } 
            // Check if neighbor is valid, unvisited, and has the same character
            else if (isValid(nextR, nextC, grid.length, grid[0].length) 
                     && !visited[nextR][nextC] 
                     && grid[nextR][nextC] == grid[startR][startC]) {

                if (hasCycle(grid, visited, startR, startC, nextR, nextC, steps + 1)) {
                    return true;
                }
            }
        }

        return false;
    }

    /**
     * Checks if coordinates are within grid boundaries.
     */
    private boolean isValid(int r, int c, int rows, int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }
}

