}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;

/**
 * Detects if a character grid contains any cycles formed by adjacent identical characters.
 * Uses Depth-First Search (DFS) with visited tracking for efficient traversal.
 */
public class GridConnectivityChecker {

    // Direction vectors for moving up, down, left, and right
    private static final int[] DR = {-1, 1, 0, 0};
    private static final int[] DC = {0, 0, -1, 1};

    public static void main(String[] args) {
        // Use try-with-resources to ensure the BufferedReader is properly closed
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            char[][] grid = readGrid(br);
            boolean hasCycle = detectCycle(grid);
            System.out.println(hasCycle ? "Yes" : "No");
        } catch (IOException e) {
            System.err.println("Failed to read input: " + e.getMessage());
            System.exit(1);
        }
    }

    /**
     * Reads the grid dimensions and rows from standard input.
     */
    private static char[][] readGrid(BufferedReader br) throws IOException {
        String line = br.readLine();
        if (line == null || line.trim().isEmpty()) {
            throw new IOException("Input is empty");
        }

        String[] dimensions = line.trim().split("\\s+");
        if (dimensions.length < 2) {
            throw new IOException("Invalid dimensions format");
        }

        int rows = Integer.parseInt(dimensions[0]);
        int cols = Integer.parseInt(dimensions[1]);

        char[][] grid = new char[rows][];
        for (int i = 0; i < rows; i++) {
            String rowStr = br.readLine();
            if (rowStr == null) {
                throw new IOException("Unexpected end of input while reading grid rows");
            }
            grid[i] = rowStr.trim().toCharArray();
        }
        return grid;
    }

    /**
     * Iterates through the grid and initiates DFS from each unvisited cell.
     * Returns true if a cycle is detected anywhere in the grid.
     */
    private static boolean detectCycle(char[][] grid) {
        if (grid == null || grid.length == 0 || grid[0].length == 0) {
            return false;
        }

        int rows = grid.length;
        int cols = grid[0].length;
        boolean[][] visited = new boolean[rows][cols];

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                // Only start DFS from unvisited cells to avoid redundant work
                if (!visited[r][c]) {
                    if (dfs(grid, r, c, visited, -1, -1)) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Performs DFS to detect cycles in the grid.
     *
     * @param grid       The character grid
     * @param row        Current row index
     * @param col        Current column index
     * @param visited    Tracks visited cells to prevent infinite loops
     * @param prevRow    Row index of the previous cell (to avoid immediate backtracking)
     * @param prevCol    Column index of the previous cell
     * @return true if a cycle is found, false otherwise
     */
    private static boolean dfs(char[][] grid, int row, int col, boolean[][] visited, int prevRow, int prevCol) {
        visited[row][col] = true;
        char currentChar = grid[row][col];

        for (int k = 0; k < 4; k++) {
            int nextRow = row + DR[k];
            int nextCol = col + DC[k];

            // Boundary check
            if (nextRow < 0 || nextRow >= grid.length || nextCol < 0 || nextCol >= grid[0].length) {
                continue;
            }
            // Skip the cell we just came from to prevent immediate backtracking
            if (nextRow == prevRow && nextCol == prevCol) {
                continue;
            }
            // Only traverse cells containing the same character
            if (grid[nextRow][nextCol] != currentChar) {
                continue;
            }
            // If we encounter an already visited cell, a cycle exists
            if (visited[nextRow][nextCol]) {
                return true;
            }
            // Continue DFS traversal
            if (dfs(grid, nextRow, nextCol, visited, row, col)) {
                return true;
            }
        }
        return false;
    }
}

import java.io.*;
import java.util.*;

/**
 * Detects cycles in a character grid where adjacent cells with identical characters form a cycle.
 * Uses depth-first search (DFS) on an undirected graph representation of the grid.
 */
public class Main {

    public static void main(String[] args) {
        new Main().run();
    }

    /**
     * Entry point for execution. Sets up I/O streams and runs the cycle detection algorithm.
     */
    public void run() {
        // try-with-resources ensures proper cleanup of streams
        try (FastScanner sc = new FastScanner(System.in);
             PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out))) {

            boolean hasCycle = detectCycle(sc, out);
            out.println(hasCycle ? "Yes" : "No");
            out.flush();
        } catch (IOException e) {
            System.err.println("I/O Error: " + e.getMessage());
        }
    }

    /**
     * Reads grid dimensions and data, then checks for cycles.
     */
    private boolean detectCycle(FastScanner sc, PrintWriter out) throws IOException {
        int n = sc.nextInt();
        int m = sc.nextInt();

        if (n <= 0 || m <= 0) {
            return false;
        }

        char[][] grid = new char[n][m];
        for (int i = 0; i < n; i++) {
            grid[i] = sc.next().toCharArray();
        }

        boolean[][] visited = new boolean[n][m];
        int[] dx = {1, 0, -1, 0};
        int[] dy = {0, 1, 0, -1};

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (!visited[i][j]) {
                    if (hasCycle(grid, visited, dx, dy, i, j, -1, -1, grid[i][j])) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Performs DFS to detect a cycle in the grid.
     * 
     * @param grid   The character grid
     * @param visited Boolean matrix tracking visited cells
     * @param dx     X-axis direction offsets
     * @param dy     Y-axis direction offsets
     * @param x      Current row index
     * @param y      Current column index
     * @param px     Previous row index (to avoid backtracking to parent)
     * @param py     Previous column index
     * @param c      Character value being traversed
     * @return true if a cycle is found, false otherwise
     */
    private boolean hasCycle(char[][] grid, boolean[][] visited, int[] dx, int[] dy,
                             int x, int y, int px, int py, char c) {
        if (visited[x][y]) {
            return true; // Cycle detected
        }
        visited[x][y] = true;

        for (int i = 0; i < 4; i++) {
            int nx = x + dx[i];
            int ny = y + dy[i];

            if (nx >= 0 && nx < grid.length && ny >= 0 && ny < grid[0].length
                    && !(nx == px && ny == py)
                    && grid[nx][ny] == c) {
                if (hasCycle(grid, visited, dx, dy, nx, ny, x, y, c)) {
                    return true;
                }
            }
        }
        return false;
    }

    /**
     * Fast I/O helper class optimized for competitive programming style input parsing.
     */
    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1024];
        private int ptr = 0;
        private int buflen = 0;

        public FastScanner(InputStream in) {
            this.in = in;
        }

        private int readByte() throws IOException {
            if (buflen == -1) throw new InputMismatchException();
            if (ptr >= buflen) {
                ptr = 0;
                buflen = in.read(buffer);
                if (buflen <= 0) return -1;
            }
            return buffer[ptr++];
        }

        private static boolean isSpaceChar(int c) {
            return !(c >= 33 && c <= 126);
        }

        private int skip() throws IOException {
            int b;
            while ((b = readByte()) != -1 && isSpaceChar(b));
            return b;
        }

        public String next() throws IOException {
            int b = skip();
            if (b == -1) throw new InputMismatchException();
            StringBuilder sb = new StringBuilder();
            while (!isSpaceChar(b)) {
                sb.appendCodePoint(b);
                b = readByte();
            }
            return sb.toString();
        }

        public int nextInt() throws IOException {
            int b = skip();
            if (b == -1) throw new InputMismatchException();
            boolean minus = false;
            if (b == '-') {
                minus = true;
                b = readByte();
            }
            int num = 0;
            while (b >= '0' && b <= '9') {
                num = num * 10 + (b - '0');
                b = readByte();
            }
            return minus ? -num : num;
        }
    }
}

import java.util.Scanner;

/**
 * Determines if a grid contains a cycle of length 4 or more
 * where all cells in the cycle contain the same character.
 */
public class GridCycleFinder {

    // Direction vectors for moving up, down, left, right
    private static final int[] DR = {-1, 1, 0, 0};
    private static final int[] DC = {0, 0, -1, 1};

    public static void main(String[] args) {
        // Use try-with-resources to automatically close the Scanner and prevent resource leaks
        try (Scanner scanner = new Scanner(System.in)) {
            if (!scanner.hasNextInt()) {
                return;
            }

            int n = scanner.nextInt();
            int m = scanner.nextInt();

            char[][] grid = new char[n][m];
            for (int i = 0; i < n; i++) {
                String row = scanner.next();
                grid[i] = row.toCharArray();
            }

            boolean cycleFound = hasCycleInGrid(grid);
            System.out.println(cycleFound ? "Yes" : "No");
        }
    }

    /**
     * Iterates through each cell in the grid and initiates a DFS
     * to detect a valid cycle.
     */
    private static boolean hasCycleInGrid(char[][] grid) {
        int n = grid.length;
        int m = grid[0].length;
        boolean[][] visited = new boolean[n][m];

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                // Only start DFS from unvisited cells. 
                // In undirected graph cycle detection, if a cycle exists, 
                // it will be found when DFS starts from any unvisited node on that cycle.
                if (!visited[i][j]) {
                    if (dfs(grid, visited, i, j, i, j, 1)) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Performs Depth-First Search to find a cycle of length >= 4.
     *
     * @param grid     The character grid
     * @param visited  Tracks visited cells in the current traversal
     * @param r        Current row
     * @param c        Current column
     * @param startR   Starting row of the cycle
     * @param startC   Starting column of the cycle
     * @param depth    Current depth/length of the path
     * @return true if a valid cycle is found, false otherwise
     */
    private static boolean dfs(char[][] grid, boolean[][] visited, int r, int c,
                               int startR, int startC, int depth) {
        visited[r][c] = true;
        char currentChar = grid[r][c];

        for (int dir = 0; dir < 4; dir++) {
            int nr = r + DR[dir];
            int nc = c + DC[dir];

            // Check boundaries and character match
            if (nr >= 0 && nr < grid.length && nc >= 0 && nc < grid[0].length && grid[nr][nc] == currentChar) {
                // Cycle detected if we return to the start cell with length >= 4
                if (nr == startR && nc == startC && depth >= 4) {
                    return true;
                }
                // Continue DFS if the neighbor hasn't been visited in this path
                if (!visited[nr][nc]) {
                    if (dfs(grid, visited, nr, nc, startR, startC, depth + 1)) {
                        return true;
                    }
                }
            }
        }
        return false;
    }
}

