public class Main {
    public static void main(String[] args) {
        FastScanner scanner = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out));
        GridCycleDetector solver = new GridCycleDetector();

        try {
            solver.solve(scanner, out);
        } catch (Exception e) {
            out.println("Error: " + e.getMessage());
        } finally {
            out.flush();
            out.close();
        }
    }

    /**
     * Detects if a cycle of identical characters exists in a 2D grid.
     * Uses DFS to traverse connected components and identify back-edges.
     */
    static class GridCycleDetector {
        private char[][] grid;
        private boolean[][] visited;
        private int n, m;
        // Direction arrays for right, left, down, up
        private static final int[] DX = {0, 0, 1, -1};
        private static final int[] DY = {1, -1, 0, 0};

        public void solve(FastScanner in, PrintWriter out) {
            n = in.nextInt();
            m = in.nextInt();

            // Allocate arrays based on actual input size instead of hardcoded limits
            grid = new char[n][m];
            visited = new boolean[n][m];

            for (int i = 0; i < n; i++) {
                String line = in.next();
                grid[i] = line.toCharArray();
            }

            boolean cycleFound = false;
            // Iterate through each cell to ensure all connected components are checked
            for (int i = 0; i < n && !cycleFound; i++) {
                for (int j = 0; j < m && !cycleFound; j++) {
                    if (!visited[i][j]) {
                        if (dfs(i, j, -1, -1)) {
                            cycleFound = true;
                        }
                    }
                }
            }
            out.println(cycleFound ? "Yes" : "No");
        }

        /**
         * Depth-First Search to detect cycles in the grid.
         * @param x Current row
         * @param y Current column
         * @param px Parent row (to avoid immediately backtracking)
         * @param py Parent column (to avoid immediately backtracking)
         * @return true if a cycle is found, false otherwise
         */
        private boolean dfs(int x, int y, int px, int py) {
            visited[x][y] = true;
            for (int d = 0; d < 4; d++) {
                int nx = x + DX[d];
                int ny = y + DY[d];

                // Check bounds
                if (nx >= 0 && nx < n && ny >= 0 && ny < m) {
                    // Only traverse cells with the same character
                    if (grid[nx][ny] == grid[x][y]) {
                        if (visited[nx][ny]) {
                            // If visited and not the immediate parent, a cycle exists
                            if (nx != px || ny != py) {
                                return true;
                            }
                        } else {
                            // Continue DFS
                            if (dfs(nx, ny, x, y)) {
                                return true;
                            }
                        }
                    }
                }
            }
            return false;
        }
    }

    /**
     * Fast and maintainable scanner for standard input.
     * Replaces complex byte-buffering with BufferedReader and StringTokenizer
     * for better readability, safety, and standard Java practices.
     */
    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        public String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input", e);
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

