/**
 * Refactored solution for "Fox and Two Dots".
 * 
 * Improvements made:
 * 1. Class Naming: Changed to PascalCase (FoxAndTwoDots) to follow Java conventions.
 * 2. Encapsulation: Moved state variables (grid, visited, dimensions) to instance fields
 *    instead of static variables, improving testability and reducing global state side effects.
 * 3. Input Parsing: Used StringTokenizer for robust whitespace handling and BufferedReader
 *    for efficient I/O.
 * 4. Algorithm Optimization: 
 *    - Removed the redundant 'status' array.
 *    - Utilized a single global 'visited' array. The original code allocated a new 'vis' 
 *      array for every cell, resulting in O(N*M^2) space complexity per check. 
 *      The refactored DFS uses O(N*M) total space.
 *    - Logic simplified to detect cycles in undirected graphs (checking for visited nodes 
 *      that are not the immediate parent).
 * 5. Code Structure: 
 *    - Used direction arrays (DR, DC) to replace repetitive if-statements for neighbors.
 *    - Added clear comments and method documentation.
 *    - Extracted logic into a 'solve' method.
 */
public class FoxAndTwoDots {

    private char[][] grid;
    private boolean[][] visited;
    private int rows;
    private int cols;

    // Direction vectors for moving Right, Down, Left, Up
    private static final int[] DR = {0, 1, 0, -1};
    private static final int[] DC = {1, 0, -1, 0};

    public static void main(String[] args) throws IOException {
        FoxAndTwoDots solver = new FoxAndTwoDots();
        solver.solve();
    }

    public void solve() throws IOException {
        // Initialize Input Reader
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));

        // Read dimensions
        String line = br.readLine();
        if (line == null) return;

        StringTokenizer st = new StringTokenizer(line);
        rows = Integer.parseInt(st.nextToken());
        cols = Integer.parseInt(st.nextToken());

        // Initialize Grid (jagged array is fine here as we assign rows directly)
        grid = new char[rows][];
        visited = new boolean[rows][cols];

        // Read the grid content
        for (int i = 0; i < rows; i++) {
            String rowStr = br.readLine();
            if (rowStr != null) {
                grid[i] = rowStr.toCharArray();
            }
        }
        br.close();

        // Check for cycles
        boolean foundCycle = false;

        // Iterate over every cell to ensure we check all connected components
        outerLoop:
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                // If the cell has not been visited yet, start a DFS from here
                if (!visited[i][j]) {
                    if (hasCycle(i, j, -1, -1)) {
                        foundCycle = true;
                        break outerLoop;
                    }
                }
            }
        }

        System.out.println(foundCycle ? "Yes" : "No");
    }

    /**
     * Depth First Search to detect a cycle of identical characters.
     * 
     * @param r Current row index
     * @param c Current column index
     * @param parentR Row index of the parent node in the DFS tree
     * @param parentC Column index of the parent node in the DFS tree
     * @return true if a cycle is detected, false otherwise
     */
    private boolean hasCycle(int r, int c, int parentR, int parentC) {
        // Mark current cell as visited
        visited[r][c] = true;

        // Explore all 4 neighbors
        for (int k = 0; k < 4; k++) {
            int nr = r + DR[k];
            int nc = c + DC[k];

            // Check boundaries
            if (nr >= 0 && nr < rows && nc >= 0 && nc < cols) {
                // Check if neighbor has the same character
                // Note: Assuming valid input where row length matches cols
                if (grid[nr][nc] == grid[r][c]) {

                    // If the neighbor is the parent we came from, skip it.
                    // This prevents immediate backtracking which isn't a cycle.
                    if (nr == parentR && nc == parentC) {
                        continue;
                    }

                    // If the neighbor is already visited, we found a cycle.
                    // Since it's not the parent, it must be a back-edge to an ancestor.
                    if (visited[nr][nc]) {
                        return true;
                    }

                    // Recursively check the neighbor
                    if (hasCycle(nr, nc, r, c)) {
                        return true;
                    }
                }
            }
        }
        return false;
    }
}

import java.io.*;
import java.util.InputMismatchException;

public class FoxAndTwoDots {

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out));
        new Solver().solve(scanner, out);
        out.flush();
    }

    static class Solver {
        private static final int[] DR = {-1, 0, 0, 1};
        private static final int[] DC = {0, -1, 1, 0};

        void solve(FastScanner scanner, PrintWriter out) {
            int rows = scanner.nextInt();
            int cols = scanner.nextInt();
            char[][] grid = new char[rows][cols];

            for (int i = 0; i < rows; i++) {
                grid[i] = scanner.next().toCharArray();
            }

            boolean[][] visited = new boolean[rows][cols];

            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (!visited[i][j] && hasCycle(grid, visited, i, j, -1, -1)) {
                        out.println("Yes");
                        return;
                    }
                }
            }
            out.println("No");
        }

        private boolean hasCycle(char[][] grid, boolean[][] visited, int r, int c, int prevR, int prevC) {
            visited[r][c] = true;
            for (int k = 0; k < 4; k++) {
                int nextR = r + DR[k];
                int nextC = c + DC[k];

                // Check boundary conditions
                if (nextR < 0 || nextR >= grid.length || nextC < 0 || nextC >= grid[0].length) {
                    continue;
                }

                // Skip the immediate parent to avoid false cycle detection
                if (nextR == prevR && nextC == prevC) {
                    continue;
                }

                // Only traverse cells with the same character
                if (grid[r][c] != grid[nextR][nextC]) {
                    continue;
                }

                // If we encounter an already visited node that isn't the parent, a cycle exists
                if (visited[nextR][nextC]) {
                    return true;
                }

                // Recurse into unvisited neighbors
                if (hasCycle(grid, visited, nextR, nextC, r, c)) {
                    return true;
                }
            }
            return false;
        }
    }

    static class FastScanner {
        private final InputStream stream;
        private final byte[] buffer = new byte[1 << 16];
        private int bufPtr = 0;
        private int bufLen = 0;

        public FastScanner(InputStream stream) {
            this.stream = stream;
        }

        private int readByte() {
            if (bufPtr >= bufLen) {
                bufPtr = 0;
                try {
                    bufLen = stream.read(buffer);
                } catch (IOException e) {
                    throw new InputMismatchException(e);
                }
                if (bufLen <= 0) {
                    return -1;
                }
            }
            return buffer[bufPtr++];
        }

        public String next() {
            int c = readByte();
            while (isSpaceChar(c)) {
                if (c == -1) throw new InputMismatchException();
                c = readByte();
            }
            StringBuilder sb = new StringBuilder();
            do {
                sb.appendCodePoint(c);
                c = readByte();
            } while (!isSpaceChar(c));
            return sb.toString();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        private static boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }
    }
}

import java.util.Scanner;

public class Solution {

    // Direction vectors for moving Up, Down, Left, Right
    private static final int[] ROW_OFFSETS = {-1, 1, 0, 0};
    private static final int[] COL_OFFSETS = {0, 0, -1, 1};

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        // Reading dimensions
        if (!scanner.hasNextInt()) return;
        int rows = scanner.nextInt();
        int cols = scanner.nextInt();

        // Reading the grid
        char[][] grid = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            if (scanner.hasNext()) {
                grid[i] = scanner.next().toCharArray();
            }
        }

        // Visited array to keep track of visited cells
        boolean[][] visited = new boolean[rows][cols];
        boolean hasCycle = false;

        // Iterate through each cell to handle disconnected components
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (!visited[i][j]) {
                    // Start DFS from this unvisited cell
                    // Pass -1, -1 as parent coordinates to indicate no parent
                    if (dfs(grid, visited, i, j, -1, -1)) {
                        hasCycle = true;
                        break;
                    }
                }
            }
            if (hasCycle) break;
        }

        System.out.println(hasCycle ? "Yes" : "No");
        scanner.close();
    }

    /**
     * Depth First Search to detect cycles in the grid.
     * 
     * @param grid The character grid
     * @param visited Boolean matrix to track visited cells
     * @param r Current row index
     * @param c Current column index
     * @param parentR Row index of the parent node (to avoid immediate back-tracking)
     * @param parentC Column index of the parent node
     * @return true if a cycle is detected, false otherwise
     */
    private static boolean dfs(char[][] grid, boolean[][] visited, int r, int c, int parentR, int parentC) {
        visited[r][c] = true;
        char currentChar = grid[r][c];

        // Explore all 4 adjacent directions
        for (int k = 0; k < 4; k++) {
            int nextR = r + ROW_OFFSETS[k];
            int nextC = c + COL_OFFSETS[k];

            // Check if the neighbor is valid and has the same character
            if (isValid(nextR, nextC, grid) && grid[nextR][nextC] == currentChar) {

                if (visited[nextR][nextC]) {
                    // If the neighbor is already visited, check if it is the parent.
                    // If it is visited and NOT the parent, a cycle is found.
                    if (nextR != parentR || nextC != parentC) {
                        return true;
                    }
                } else {
                    // If not visited, recursively visit it.
                    // Pass current (r, c) as the parent for the next step.
                    if (dfs(grid, visited, nextR, nextC, r, c)) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Checks if the given coordinates are within the grid boundaries.
     */
    private static boolean isValid(int r, int c, char[][] grid) {
        return r >= 0 && r < grid.length && c >= 0 && c < grid[0].length;
    }
}

