public class Main {

    // Directions for moving down, up, left, right
    private static final int[][] DIRECTIONS = {{1, -1, 0, 0}, {0, 0, -1, 1}};

    public static void main(String[] args) throws IOException {
        // Try-with-resources ensures PrintWriter is automatically flushed and closed
        try (PrintWriter out = new PrintWriter(System.out)) {
            FastScanner scanner = new FastScanner(System.in);

            int rows = scanner.nextInt();
            int cols = scanner.nextInt();
            char[][] grid = new char[rows][cols];

            for (int i = 0; i < rows; i++) {
                grid[i] = scanner.next().toCharArray();
            }

            boolean foundCycle = false;
            // Iterate through each cell to check if it can form a cycle of length >= 4
            for (int i = 0; i < rows && !foundCycle; i++) {
                for (int j = 0; j < cols && !foundCycle; j++) {
                    if (grid[i][j] != '*') {
                        boolean[][] visited = new boolean[rows][cols];
                        if (hasCycle(grid, i, j, grid[i][j], i, j, 0, visited)) {
                            foundCycle = true;
                        }
                    }
                }
            }

            out.println(foundCycle ? "Yes" : "No");
        }
    }

    /**
     * Performs DFS to find if a cycle of length >= 4 exists starting from (startR, startC)
     * consisting only of the target character.
     */
    private static boolean hasCycle(char[][] grid, int r, int c, char target,
                                    int startR, int startC, int steps, boolean[][] visited) {
        // If we've taken at least 4 steps and returned to the starting cell, a valid cycle exists
        if (steps >= 4 && r == startR && c == startC) {
            return true;
        }

        visited[r][c] = true;
        for (int[] dir : DIRECTIONS) {
            int nr = r + dir[0];
            int nc = c + dir[1];

            if (isValid(nr, nc, grid) && grid[nr][nc] == target && !visited[nr][nc]) {
                if (hasCycle(grid, nr, nc, target, startR, startC, steps + 1, visited)) {
                    return true;
                }
            }
        }
        // Backtrack: unmark the current cell so other paths can explore it
        visited[r][c] = false;
        return false;
    }

    /**
     * Checks if the given coordinates are within the grid boundaries.
     */
    private static boolean isValid(int r, int c, char[][] grid) {
        return r >= 0 && r < grid.length && c >= 0 && c < grid[0].length;
    }

