        int n = Integer.parseInt(st.nextToken());
        int m = Integer.parseInt(st.nextToken());

        // Read the grid
        char[][] grid = new char[n][m];
        for (int i = 0; i < n; i++) {
            String row = reader.readLine();
            if (row != null) {
                grid[i] = row.toCharArray();
            } else {
                grid[i] = new char[m];
            }
        }

        // Solve and print result
        System.out.println(solve(grid, n, m) ? "Yes" : "No");
    }

    /**
     * Determines if there are two disjoint paths (or a cycle) for any character.
     * In the context of grid graphs, this checks if any connected component of identical characters
     * contains a cycle.
     */
    private static boolean solve(char[][] grid, int n, int m) {
        boolean[][] visited = new boolean[n][m];

        // Iterate through every cell in the grid
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                // If the cell has not been visited, it belongs to a new connected component
                if (!visited[i][j]) {
                    char currentChar = grid[i][j];
                    // Check if this component contains a cycle
                    if (hasCycle(grid, n, m, visited, i, j, currentChar)) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Performs a BFS to detect if the connected component of 'targetChar' starting at (startRow, startCol)
     * contains a cycle.
     */
    private static boolean hasCycle(char[][] grid, int n, int m, boolean[][] visited, 
                                    int startRow, int startCol, char targetChar) {
        ArrayDeque<Visit> queue = new ArrayDeque<>();
        Pos startPos = new Pos(startCol, startRow);

        // Mark start as visited immediately. 
        // In undirected graph cycle detection, we mark visited when pushing to queue.
        visited[startRow][startCol] = true;
        queue.add(new Visit(startPos, null));

        while (!queue.isEmpty()) {
            Visit current = queue.poll();
            Pos p = current.pos;
            Pos parent = current.from;

            // Explore neighbors
            for (int k = 0; k < 4; k++) {
                int nextRow = p.y + DY[k];
                int nextCol = p.x + DX[k];

                // Check bounds
                if (nextRow >= 0 && nextRow < n && nextCol >= 0 && nextCol < m) {
                    // Check if neighbor has the same character
                    if (grid[nextRow][nextCol] == targetChar) {
                        if (!visited[nextRow][nextCol]) {
                            // If not visited, mark and add to queue
                            visited[nextRow][nextCol] = true;
                            Pos nextPos = new Pos(nextCol, nextRow);
                            queue.add(new Visit(nextPos, p));
                        } else {
                            // If visited, check if it's the parent.
                            // If it is visited and NOT the parent, we found a cycle.
                            if (parent == null || !(parent.x == nextCol && parent.y == nextRow)) {
                                return true;
                            }
                        }
                    }
                }
            }
        }
        return false;
    }
}

