public class TwoDots {

    private int rows;
    private int cols;
    private char[][] grid;
    private boolean[][] visited;

    // Direction vectors for moving Down, Up, Right, Left
    private static final int[] DR = {1, -1, 0, 0};
    private static final int[] DC = {0, 0, 1, -1};

    public static void main(String[] args) {
        TwoDots solver = new TwoDots();
        solver.solve();
    }

    public void solve() {
        Scanner sc = new Scanner(System.in);

        // Read dimensions
        if (sc.hasNextInt()) {
            this.rows = sc.nextInt();
            this.cols = sc.nextInt();
        } else {
            sc.close();
            return;
        }

        // Read grid
        grid = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            String line = sc.next();
            grid[i] = line.toCharArray();
        }

        // Check for cycle
        if (hasCycle()) {
            System.out.println("Yes");
        } else {
            System.out.println("No");
        }

        sc.close();
    }

    private boolean hasCycle() {
        // Initialize visited array once. 
        // If a node is visited, it means its component has been fully explored.
        visited = new boolean[rows][cols];

        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                // Start DFS only from unvisited nodes
                if (!visited[i][j]) {
                    if (dfs(i, j, -1, -1)) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Depth First Search to detect a cycle in the grid.
     *
     * @param r Current row index
     * @param c Current column index
     * @param prevR Previous row index (to avoid traversing back up the path)
     * @param prevC Previous column index (to avoid traversing back up the path)
     * @return true if a cycle is detected, false otherwise
     */
    private boolean dfs(int r, int c, int prevR, int prevC) {
        visited[r][c] = true;
        char currentColor = grid[r][c];

        for (int k = 0; k < 4; k++) {
            int nextR = r + DR[k];
            int nextC = c + DC[k];

            // Check boundaries
            if (nextR < 0 || nextR >= rows || nextC < 0 || nextC >= cols) {
                continue;
            }

            // Check if the neighbor has the same color
            if (grid[nextR][nextC] != currentColor) {
                continue;
            }

            // If the neighbor is the node we just came from, skip it
            if (nextR == prevR && nextC == prevC) {
                continue;
            }

            // If the neighbor is already visited, we found a cycle
            if (visited[nextR][nextC]) {
                return true;
            }

            // Recurse into the unvisited neighbor
            // Crucial: Check the return value of the recursive call
            if (dfs(nextR, nextC, r, c)) {
                return true;
            }
        }
        return false;
    }
}

import java.util.Scanner;

/**
 * Refactored solution for detecting cycles in a grid of characters.
 * 
 * Improvements made:
 * 1.  **Naming**: Renamed class and variables to be descriptive (e.g., `GridCycleSolver`, `rows`, `cols`, `grid`).
 * 2.  **Structure**: Moved logic out of the constructor into a `run()` method and separated concerns.
 * 3.  **Algorithm**: Replaced the complex iterative DFS with a helper class (`Node`) and a custom `hasNext` method 
 *     with a clean, standard recursive DFS. This significantly improves readability and maintainability.
 * 4.  **Input/Output**: Removed unused `BufferedReader` and fixed the mixing of input streams. Removed the empty 
 *     exception catch block which hid potential errors.
 * 5.  **Robustness**: Added basic checks for input validity and array bounds.
 */
public class GridCycleSolver {

    private int rows;
    private int cols;
    private char[][] grid;
    private boolean[][] visited;

    public static void main(String[] args) {
        GridCycleSolver solver = new GridCycleSolver();
        solver.run();
    }

    public void run() {
        Scanner scanner = new Scanner(System.in);

        // Check if input exists to prevent exceptions on empty streams
        if (!scanner.hasNextInt()) {
            return;
        }

        this.rows = scanner.nextInt();
        this.cols = scanner.nextInt();

        this.grid = new char[rows][cols];
        this.visited = new boolean[rows][cols];

        // Read the grid
        for (int i = 0; i < rows; i++) {
            if (scanner.hasNext()) {
                String rowStr = scanner.next();
                // Fill the row, ensuring we don't go out of bounds if input is malformed
                for (int j = 0; j < cols; j++) {
                    if (j < rowStr.length()) {
                        this.grid[i][j] = rowStr.charAt(j);
                    }
                }
            }
        }

        boolean hasCycle = false;

        // Iterate through every cell to handle disconnected components
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                // If the cell hasn't been visited yet, start a DFS from here
                if (!visited[i][j]) {
                    // Start DFS. Parent is (-1, -1) for the root of the tree
                    if (dfs(i, j, -1, -1)) {
                        hasCycle = true;
                        break; // Cycle found, no need to search further
                    }
                }
            }
            if (hasCycle) break;
        }

        System.out.println(hasCycle ? "Yes" : "No");
    }

    /**
     * Performs Depth First Search to detect a cycle in the grid.
     * 
     * @param r Current row index
     * @param c Current column index
     * @param pR Parent row index (to prevent immediate backtracking)
     * @param pC Parent column index (to prevent immediate backtracking)
     * @return true if a cycle is detected, false otherwise
     */
    private boolean dfs(int r, int c, int pR, int pC) {
        visited[r][c] = true;

        // Direction vectors: Up, Right, Down, Left
        int[] dr = {-1, 0, 1, 0};
        int[] dc = {0, 1, 0, -1};

        for (int i = 0; i < 4; i++) {
            int nr = r + dr[i];
            int nc = c + dc[i];

            // 1. Check boundaries
            if (nr < 0 || nr >= rows || nc < 0 || nc >= cols) {
                continue;
            }

            // 2. Check if the neighbor has the same character
            if (grid[nr][nc] != grid[r][c]) {
                continue;
            }

            // 3. Logic for visited nodes
            if (visited[nr][nc]) {
                // If we encounter a visited node that is NOT the parent, 
                // we have found a cycle.
                if (nr != pR || nc != pC) {
                    return true;
                }
            } else {
                // If not visited, recurse
                if (dfs(nr, nc, r, c)) {
                    return true;
                }
            }
        }

        return false;
    }
}

import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);

        GridPathSolver solver = new GridPathSolver();
        solver.solve(in, out);

        out.close();
    }

    /**
     * Solves the grid cycle problem.
     * Determines if there exists a simple cycle of length >= 4 where all cells
     * in the cycle contain the same character.
     */
    static class GridPathSolver {
        public void solve(InputReader in, PrintWriter out) {
            int n = in.nextInt();
            int m = in.nextInt();

            char[][] grid = new char[n][m];
            for (int i = 0; i < n; i++) {
                String row = in.next();
                grid[i] = row.toCharArray();
            }

            boolean found = false;
            for (int i = 0; i < n && !found; i++) {
                for (int j = 0; j < m && !found; j++) {
                    // Allocate visited array per starting cell to avoid backtracking complexity
                    int[][] visited = new int[n][m];
                    if (hasValidCycle(grid, i, j, i, j, visited, 0)) {
                        found = true;
                    }
                }
            }

            out.println(found ? "Yes" : "No");
        }

        /**
         * Depth-first search to find a cycle of length >= 4 starting and ending at (startX, startY).
         * All cells in the path must match the starting cell's character.
         */
        private boolean hasValidCycle(char[][] grid, int x, int y, int startX, int startY,
                                      int[][] visited, int pathLength) {
            int n = grid.length;
            int m = grid[0].length;

            // Boundary check
            if (x < 0 || x >= n || y < 0 || y >= m) {
                return false;
            }

            // Check if we returned to the start with a valid path length
            if (x == startX && y == startY && pathLength >= 4) {
                return true;
            }

            // Check character match and if cell is already visited in this path
            if (grid[x][y] != grid[startX][startY] || visited[x][y] == 1) {
                return false;
            }

            visited[x][y] = 1;
            pathLength++;

            // Explore all 4 directions with early exit on success
            if (hasValidCycle(grid, x + 1, y, startX, startY, visited, pathLength)) return true;
            if (hasValidCycle(grid, x - 1, y, startX, startY, visited, pathLength)) return true;
            if (hasValidCycle(grid, x, y + 1, startX, startY, visited, pathLength)) return true;
            if (hasValidCycle(grid, x, y - 1, startX, startY, visited, pathLength)) return true;

            return false;
        }
    }

    /**
     * Fast input reader for competitive programming.
     */
    static class InputReader {
        public BufferedReader reader;
        public StringTokenizer tokenizer;

        public InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }

        public double nextDouble() {
            return Double.parseDouble(next());
        }
    }

    /**
     * Common mathematical utilities (kept for template consistency).
     */
    static class Utils {
        public static long modPow(long base, long exp, long mod) {
            long res = 1;
            base %= mod;
            while (exp > 0) {
                if ((exp & 1) == 1) res = (res * base) % mod;
                base = (base * base) % mod;
                exp >>= 1;
            }
            return res;
        }

        public static int gcd(int a, int b) {
            while (b != 0) {
                int temp = b;
                b = a % b;
                a = temp;
            }
            return a;
        }

        public static long gcd(long a, long b) {
            while (b != 0) {
                long temp = b;
                b = a % b;
                a = temp;
            }
            return a;
        }
    }
}

import java.util.Scanner;

public class FoxAndTwoDots {

    /**
     * Performs Depth First Search (DFS) to detect a cycle of identical characters.
     *
     * @param grid    The 2D character array representing the grid.
     * @param visited A 2D boolean array tracking visited cells.
     * @param r       Current row index.
     * @param c       Current column index.
     * @param prevR   Previous row index (to avoid immediate backtracking).
     * @param prevC   Previous column index.
     * @return true if a cycle is detected, false otherwise.
     */
    private static boolean dfs(char[][] grid, boolean[][] visited, int r, int c, int prevR, int prevC) {
        // Mark the current cell as visited
        visited[r][c] = true;

        // Define direction vectors: Up, Left, Down, Right
        int[] dr = {-1, 0, 1, 0};
        int[] dc = {0, -1, 0, 1};

        // Iterate through all 4 adjacent neighbors
        for (int i = 0; i < 4; i++) {
            int nextR = r + dr[i];
            int nextC = c + dc[i];

            // Check if neighbor is within grid boundaries
            if (nextR >= 0 && nextR < grid.length && nextC >= 0 && nextC < grid[0].length) {

                // Check if neighbor has the same character
                if (grid[r][c] == grid[nextR][nextC]) {

                    if (visited[nextR][nextC]) {
                        // If the neighbor is already visited, check if it is the parent node.
                        // If it is visited AND not the parent, a cycle exists.
                        // Note: We use || here because if EITHER coordinate differs, it's not the parent.
                        if (nextR != prevR || nextC != prevC) {
                            return true;
                        }
                    } else {
                        // If the neighbor is not visited, continue DFS
                        if (dfs(grid, visited, nextR, nextC, r, c)) {
                            return true;
                        }
                    }
                }
            }
        }

        return false;
    }

    public static void main(String[] args) {
        // Use try-with-resources for automatic resource management
        try (Scanner sc = new Scanner(System.in)) {
            if (!sc.hasNextInt()) return;

            int n = sc.nextInt();
            int m = sc.nextInt();

            char[][] grid = new char[n][m];
            for (int i = 0; i < n; i++) {
                grid[i] = sc.next().toCharArray();
            }

            boolean[][] visited = new boolean[n][m];
            boolean cycleFound = false;

            // Iterate through each cell in the grid
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    // If the cell has not been visited, start a DFS traversal
                    if (!visited[i][j]) {
                        // Pass -1, -1 as previous coordinates for the starting node
                        if (dfs(grid, visited, i, j, -1, -1)) {
                            cycleFound = true;
                            break; // Optimization: Stop searching once a cycle is found
                        }
                    }
                }
                if (cycleFound) break;
            }

            System.out.println(cycleFound ? "Yes" : "No");
        }
    }
}

