public class GridCycleDetector {

    /**
     * FastScanner utility for efficient input reading.
     * Encapsulated as a private static inner class.
     */
    private static class FastScanner {
        BufferedReader br;
        StringTokenizer st;

        public FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) {
                        return null;
                    }
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    e.printStackTrace();
                    return null;
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            String s = next();
            return (s == null) ? 0 : Integer.parseInt(s);
        }

        long nextLong() {
            String s = next();
            return (s == null) ? 0L : Long.parseLong(s);
        }

        double nextDouble() {
            String s = next();
            return (s == null) ? 0.0 : Double.parseDouble(s);
        }
    }

    public static void main(String[] args) {
        FastScanner sc = new FastScanner();
        PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out));

        // Read dimensions M (rows) and N (columns)
        String mStr = sc.next();
        if (mStr == null) {
            out.flush();
            return;
        }
        int M = Integer.parseInt(mStr);
        int N = sc.nextInt();

        char[][] board = new char[M][N];
        for (int r = 0; r < M; r++) {
            String row = sc.next();
            // Safely copy the row characters, assuming valid input length
            if (row != null && row.length() >= N) {
                board[r] = row.substring(0, N).toCharArray();
            }
        }

        boolean hasCycle = false;
        // Use a separate visited array to track state without mutating the input board.
        // This improves maintainability and prevents side effects.
        boolean[][] visited = new boolean[M][N];

        // Iterate through every cell to ensure all disconnected components are checked
        for (int r = 0; r < M; r++) {
            for (int c = 0; c < N; c++) {
                if (!visited[r][c]) {
                    // Start DFS from this unvisited cell
                    // -1, -1 indicates no parent initially
                    if (dfs(board, visited, r, c, -1, -1)) {
                        hasCycle = true;
                        break;
                    }
                }
            }
            if (hasCycle) break;
        }

        out.println(hasCycle ? "Yes" : "No");
        out.flush();
        out.close();
    }

    // Directions: Up, Down, Left, Right
    private static final int[][] DIRS = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};

    /**
     * Performs Depth First Search (DFS) to detect a cycle in the grid.
     * A cycle is detected if we encounter a visited node that is not the immediate parent
     * and has the same character (case-insensitive).
     *
     * @param board The grid of characters
     * @param visited Boolean matrix to track visited cells
     * @param r Current row index
     * @param c Current column index
     * @param prevR Row index of the previous cell (parent)
     * @param prevC Column index of the previous cell (parent)
     * @return true if a cycle is found, false otherwise
     */
    private static boolean dfs(char[][] board, boolean[][] visited, int r, int c, int prevR, int prevC) {
        visited[r][c] = true;
        char currentChar = Character.toLowerCase(board[r][c]);

        for (int[] dir : DIRS) {
            int nextR = r + dir[0];
            int nextC = c + dir[1];

            // Boundary Check
            // Fixed logic from original code: ensures both coordinates are within bounds
            if (nextR < 0 || nextR >= board.length || nextC < 0 || nextC >= board[0].length) {
                continue;
            }

            // Check if neighbor has the same character (case-insensitive)
            if (Character.toLowerCase(board[nextR][nextC]) != currentChar) {
                continue;
            }

            if (visited[nextR][nextC]) {
                // If neighbor is visited, it constitutes a cycle 
                // unless it is the immediate parent we just came from.
                if (nextR != prevR || nextC != prevC) {
                    return true;
                }
            } else {
                // If neighbor is not visited, recurse
                if (dfs(board, visited, nextR, nextC, r, c)) {
                    return true;
                }
            }
        }
        return false;
    }
}

