 */
public class TwoDots {

    private int rows;
    private int cols;
    private char[][] grid;
    private boolean[][] visited;

    // Direction vectors: Down, Up, Right, Left
    private static final int[] DR = {1, -1, 0, 0};
    private static final int[] DC = {0, 0, 1, -1};

    public static void main(String[] args) {
        // Standard entry point for Java applications
        new TwoDots().solve();
    }

    public void solve() {
        FastScanner scanner = new FastScanner();
        PrintWriter out = new PrintWriter(System.out);

        try {
            // Check if input exists
            if (!scanner.hasNext()) {
                out.flush();
                return;
            }

            rows = scanner.nextInt();
            cols = scanner.nextInt();

            grid = new char[rows][cols];
            visited = new boolean[rows][cols];

            // Read grid data
            for (int i = 0; i < rows; i++) {
                String line = scanner.next();
                if (line != null) {
                    grid[i] = line.toCharArray();
                }
            }

            // Perform cycle detection
            if (hasCycle()) {
                out.println("Yes");
            } else {
                out.println("No");
            }
        } catch (Exception e) {
            e.printStackTrace();
        } finally {
            out.flush();
            out.close();
        }
    }

    /**
     * Iterates through the grid to find a cycle.
     * @return true if a cycle is found, false otherwise.
     */
    private boolean hasCycle() {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (!visited[i][j]) {
                    // Start DFS from unvisited cell. 
                    // Parent is (-1, -1) indicating no parent.
                    if (dfs(i, j, -1, -1)) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Depth First Search to detect cycles.
     *
     * @param r Current row index
     * @param c Current column index
     * @param prevR Previous row index (parent)
     * @param prevC Previous column index (parent)
     * @return true if a cycle is detected, false otherwise
     */
    private boolean dfs(int r, int c, int prevR, int prevC) {
        visited[r][c] = true;

        for (int k = 0; k < 4; k++) {
            int nextR = r + DR[k];
            int nextC = c + DC[k];

            // Check boundaries
            if (nextR >= 0 && nextR < rows && nextC >= 0 && nextC < cols) {
                // Skip the immediate parent to avoid going back up the tree
                if (nextR == prevR && nextC == prevC) {
                    continue;
                }

                // Check if the neighbor has the same character
                if (grid[nextR][nextC] == grid[r][c]) {
                    if (visited[nextR][nextC]) {
                        // Found a visited node that is not the parent -> Cycle detected
                        return true;
                    } else {
                        // Continue DFS
                        if (dfs(nextR, nextC, r, c)) {
                            return true;
                        }
                    }
                }
            }
        }
        return false;
    }

    /**
     * Helper class for fast input reading.
     */
    static class FastScanner {
        BufferedReader br;
        StringTokenizer st;

        public FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        boolean hasNext() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) {
                        return false;
                    }
                    // Skip empty lines
                    if (line.trim().isEmpty()) {
                        continue;
                    }
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    return false;
                }
            }
            return true;
        }

        String next() {
            if (hasNext()) {
