public class School {

    private static final int[] DX = {1, -1, 0, 0};
    private static final int[] DY = {0, 0, 1, -1};

    /**
     * Immutable coordinate class. Kept for API compatibility.
     */
    public static class Point {
        private final int x;
        private final int y;

        public Point(int x, int y) {
            this.x = x;
            this.y = y;
        }

        public int getX() { return x; }
        public int getY() { return y; }

        @Override
        public boolean equals(Object obj) {
            if (this == obj) return true;
            if (obj == null || getClass() != obj.getClass()) return false;
            Point point = (Point) obj;
            return x == point.x && y == point.y;
        }

        @Override
        public int hashCode() {
            return Objects.hash(x, y);
        }

        @Override
        public String toString() {
            return "[" + x + ", " + y + "]";
        }
    }

    public static void main(String[] args) {
        InputReader in = new InputReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            int n = in.nextInt();
            int m = in.nextInt();

            char[][] grid = new char[n][];
            for (int i = 0; i < n; i++) {
                grid[i] = in.next().toCharArray();
            }

            out.println(hasCycle(grid) ? "Yes" : "No");
        } finally {
            out.flush();
        }
    }

    /**
     * Checks if the grid contains any cycle formed by adjacent cells with the same character.
     */
    private static boolean hasCycle(char[][] grid) {
        int n = grid.length;
        int m = grid[0].length;
        boolean[][] visited = new boolean[n][m];

        // Iterate over every cell to handle disconnected components
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (!visited[i][j]) {
                    if (dfs(grid, visited, i, j, -1, -1)) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Performs DFS to detect cycles in the undirected graph formed by same-character neighbors.
     * Tracks the parent coordinate to avoid false positives from the immediate back-edge.
     */
    private static boolean dfs(char[][] grid, boolean[][] visited, int x, int y, int parentX, int parentY) {
        visited[x][y] = true;

        for (int i = 0; i < DX.length; i++) {
            int nx = x + DX[i];
            int ny = y + DY[i];

            if (isValid(nx, ny, grid) && grid[nx][ny] == grid[x][y]) {
                if (!visited[nx][ny]) {
                    if (dfs(grid, visited, nx, ny, x, y)) {
                        return true;
                    }
                } else if (nx != parentX || ny != parentY) {
                    // Found a visited neighbor that isn't the parent -> cycle detected
                    return true;
                }
            }
        }
        return false;
    }

    /**
     * Checks if coordinates are within grid bounds.
     */
    private static boolean isValid(int x, int y, char[][] grid) {
        return x >= 0 && x < grid.length && y >= 0 && y < grid[0].length;
    }

    /**
     * Fast I/O helper class for competitive programming / large inputs.
     */
    public static class InputReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Input stream error", e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            String s = next();
            if (s == null) throw new RuntimeException("Unexpected end of input");
            return Integer.parseInt(s);
        }

        public long nextLong() {
            return Long.parseLong(next());
        }

        public int[] nextIntArr(int n) {
            int[] arr = new int[n];
            for (int i = 0; i < n; i++) {
                arr[i] = nextInt();
            }
            return arr;
        }
    }
}

import java.util.Scanner;

/**
 * Refactored version of the Grid Cycle Detector.
 * 
 * Improvements made:
 * 1. Encapsulation: Moved state (grid, visited, dimensions) from static fields to instance variables.
 * 2. Algorithmic Efficiency: Removed the redundant O(N^2 * M^2) loop that reset the 'visited' array 
 *    before every DFS call. The new logic visits each connected component exactly once.
 * 3. Readability: Replaced magic numbers with named constants (DIRECTIONS) and descriptive variable names.
 * 4. Safety: Used (-1, -1) as the initial parent coordinates in DFS to avoid ambiguity with grid indices.
 * 5. Structure: Separated input logic and core logic into distinct methods.
 */
public class Main {

    // Instance fields to hold the grid state
    private char[][] grid;
    private boolean[][] visited;
    private int rows;
    private int cols;

    // Directions: Up, Down, Left, Right
    private static final int[][] DIRECTIONS = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};

    public static void main(String[] args) {
        Main solver = new Main();
        // Run the solver and print result
        if (solver.solve()) {
            System.out.println("Yes");
        } else {
            System.out.println("No");
        }
    }

    /**
     * Orchestrates input reading and the cycle detection algorithm.
     * @return true if a cycle is found, false otherwise.
     */
    private boolean solve() {
        Scanner scanner = new Scanner(System.in);

        // Check if input is available
        if (!scanner.hasNextInt()) {
            return false;
        }

        this.rows = scanner.nextInt();
        this.cols = scanner.nextInt();
        scanner.nextLine(); // Consume the newline character left by nextInt()

        // Initialize grid and visited array
        this.grid = new char[this.rows][this.cols];
        this.visited = new boolean[this.rows][this.cols];

        // Read the grid
        for (int i = 0; i < this.rows; i++) {
            String line = scanner.nextLine();
            // Fill the row, handling cases where line might be shorter than expected
            for (int j = 0; j < this.cols && j < line.length(); j++) {
                this.grid[i][j] = line.charAt(j);
            }
        }

        // Iterate through every cell to find connected components
        // We only need to start a DFS from unvisited cells
        for (int i = 0; i < this.rows; i++) {
            for (int j = 0; j < this.cols; j++) {
                if (!this.visited[i][j]) {
                    // Start DFS from this unvisited cell.
                    // Pass -1, -1 as parent coordinates to indicate no parent.
                    if (this.dfs(i, j, -1, -1, this.grid[i][j])) {
                        return true; // Cycle detected
                    }
                }
            }
        }

        return false;
    }

    /**
     * Performs Depth First Search to detect a cycle in the grid.
     * 
     * @param r Current row index
     * @param c Current column index
     * @param prevR Row index of the parent node
     * @param prevC Column index of the parent node
     * @param color The character color we are tracing
     * @return true if a cycle is found, false otherwise
     */
    private boolean dfs(int r, int c, int prevR, int prevC, char color) {
        this.visited[r][c] = true;

        for (int[] dir : DIRECTIONS) {
            int nr = r + dir[0];
            int nc = c + dir[1];

            // Check boundaries
            if (nr < 0 || nr >= this.rows || nc < 0 || nc >= this.cols) {
                continue;
            }

            // Check if neighbor has the same color
            if (this.grid[nr][nc] == color) {
                if (this.visited[nr][nc]) {
                    // If neighbor is visited and it is NOT the immediate parent,
                    // we have found a cycle.
                    if (nr != prevR || nc != prevC) {
                        return true;
                    }
                } else {
                    // If neighbor is not visited, continue DFS
                    if (this.dfs(nr, nc, r, c, color)) {
                        return true;
                    }
                }
            }
        }
        return false;
    }
}

