/**
 * Main class to detect if a 2D character grid contains any connected component
 * of identical adjacent characters with a size of 3 or more.
 */
public class Main {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            int rows = reader.nextInt();
            int cols = reader.nextInt();

            char[][] grid = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                // Read line, trim whitespace, and convert to char array
                String line = reader.nextLine();
                grid[i] = (line != null) ? line.trim().toCharArray() : new char[0];
            }

            boolean hasLargeComponent = findComponentOfThreeOrMore(grid);
            out.println(hasLargeComponent ? "Yes" : "No");
        } catch (Exception e) {
            // In production code, log the exception. For CP, default to "No".
            out.println("No");
        } finally {
            out.flush();
        }
    }

    /**
     * Scans the grid to find if any connected component of identical characters
     * has a size of 3 or more.
     */
    private static boolean findComponentOfThreeOrMore(char[][] grid) {
        int rows = grid.length;
        int cols = grid[0].length;
        boolean[][] visited = new boolean[rows][cols];

        // Pre-allocate stack arrays to avoid repeated memory allocation
        int[] stackR = new int[rows * cols];
        int[] stackC = new int[rows * cols];

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (!visited[r][c]) {
                    int componentSize = dfsIterative(r, c, grid[r][c], grid, visited, stackR, stackC);
                    if (componentSize >= 3) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Iterative Depth-First Search to count the size of a connected component.
     * Uses explicit stack to prevent StackOverflowError on large inputs.
     */
    private static int dfsIterative(int startR, int startC, char targetChar, 
                                    char[][] grid, boolean[][] visited, 
                                    int[] stackR, int[] stackC) {
        int size = 0;
        int[] dr = {-1, 1, 0, 0};
        int[] dc = {0, 0, -1, 1};

        int top = 0;
        stackR[top] = startR;
        stackC[top] = startC;
        top++;
        visited[startR][startC] = true;
        size++;

        while (top > 0) {
            top--;
            int r = stackR[top];
            int c = stackC[top];

            for (int i = 0; i < 4; i++) {
                int nr = r + dr[i];
                int nc = c + dc[i];

                if (isValid(nr, nc, grid) && !visited[nr][nc] && grid[nr][nc] == targetChar) {
                    visited[nr][nc] = true;
                    size++;
                    stackR[top] = nr;
                    stackC[top] = nc;
                    top++;
                }
            }
        }
        return size;
    }

    /**
     * Checks if the given coordinates are within grid boundaries.
     */
    private static boolean isValid(int r, int c, char[][] grid) {
        return r >= 0 && r < grid.length && c >= 0 && c < grid[0].length;
    }

    /**
     * Fast input reader using BufferedReader and StringTokenizer.
     * Provides a maintainable alternative to byte-level scanners while preserving performance.
     */
    public static class FastReader {
        private final BufferedReader br;
        private java.util.StringTokenizer st;

        public FastReader(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        public String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) {
                        throw new IOException("End of input");
                    }
                    st = new java.util.StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public String nextLine() {
            try {
                return br.readLine();
            } catch (IOException e) {
                throw new RuntimeException(e);
            }
        }
    }
}

