/**
 * Refactored solution for Codeforces 510B - Fox And Two Dots.
 * 
 * Key improvements:
 * 1. Removed global mutable state (static fields) to improve testability and thread safety.
 * 2. Eliminated unused code (Pair class, hash array).
 * 3. Replaced custom InputReader with standard BufferedReader + StringTokenizer for readability and maintainability.
 * 4. DFS now returns a boolean instead of relying on a global flag, providing cleaner control flow.
 * 5. Used char[][] for the grid to improve readability over integer mappings.
 * 6. Added constants, documentation, and early-exit optimizations.
 */
public class Cf510B {

    private static final int[][] DIRECTIONS = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};

    public static void main(String[] args) throws IOException {
        FastScanner scanner = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out);

        int n = scanner.nextInt();
        int m = scanner.nextInt();

        char[][] grid = new char[n][m];
        for (int i = 0; i < n; i++) {
            grid[i] = scanner.next().toCharArray();
        }

        boolean[][] visited = new boolean[n][m];
        boolean hasCycle = false;

        // Iterate through each cell to start DFS if unvisited
        for (int i = 0; i < n && !hasCycle; i++) {
            for (int j = 0; j < m && !hasCycle; j++) {
                if (!visited[i][j]) {
                    if (dfs(i, j, -1, -1, grid, visited)) {
                        hasCycle = true;
                    }
                }
            }
        }

        out.println(hasCycle ? "Yes" : "No");
        out.flush();
    }

    /**
     * Performs depth-first search to detect cycles in the grid.
     *
     * @param x         Current row index
     * @param y         Current column index
     * @param parentX   Row index of the parent cell (to avoid immediate backtracking)
     * @param parentY   Column index of the parent cell
     * @param grid      The character grid
     * @param visited   Visited cells tracker
     * @return true if a cycle is found, false otherwise
     */
    private static boolean dfs(int x, int y, int parentX, int parentY, char[][] grid, boolean[][] visited) {
        visited[x][y] = true;

        for (int[] dir : DIRECTIONS) {
            int nx = x + dir[0];
            int ny = y + dir[1];

            // Check boundaries
            if (nx < 0 || nx >= grid.length || ny < 0 || ny >= grid[0].length) {
                continue;
            }

            // Skip the cell we just came from
            if (nx == parentX && ny == parentY) {
                continue;
            }

            // Only traverse cells with the same character
            if (grid[nx][ny] != grid[x][y]) {
                continue;
            }

            // If already visited, a cycle exists
            if (visited[nx][ny]) {
                return true;
            }

            // Recurse into unvisited neighbors
            if (dfs(nx, ny, x, y, grid, visited)) {
                return true;
            }
        }
        return false;
    }

    /**
     * Fast input reader using BufferedReader and StringTokenizer.
     * Replaces the verbose custom InputReader for better maintainability.
     */
    private static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        public String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) {
                        return null;
                    }
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input", e);
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            String s = next();
            if (s == null) {
                throw new RuntimeException("Unexpected end of input");
            }
            return Integer.parseInt(s);
        }
    }
}

import java.util.Scanner;

public class Solution {

    // Direction vectors for moving Up, Down, Left, Right
    // DR: Delta Row, DC: Delta Column
    private static final int[] DR = {-1, 1, 0, 0};
    private static final int[] DC = {0, 0, -1, 1};

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        // Read dimensions
        if (!scanner.hasNextInt()) {
            return;
        }
        int rows = scanner.nextInt();
        int cols = scanner.nextInt();

        char[][] grid = new char[rows][cols];
        boolean[][] visited = new boolean[rows][cols];

        // Read the grid
        for (int i = 0; i < rows; i++) {
            if (scanner.hasNext()) {
                grid[i] = scanner.next().toCharArray();
            }
        }

        boolean hasCycle = false;

        // Iterate through each cell to ensure all connected components are checked
        for (int i = 0; i < rows && !hasCycle; i++) {
            for (int j = 0; j < cols; j++) {
                if (!visited[i][j]) {
                    // Start DFS from unvisited node
                    if (dfs(grid, visited, i, j, -1, -1)) {
                        hasCycle = true;
                    }
                }
            }
        }

        System.out.println(hasCycle ? "Yes" : "No");
        scanner.close();
    }

    /**
     * Depth First Search to detect cycles of identical characters.
     *
     * @param grid       The character grid.
     * @param visited    2D array tracking visited cells.
     * @param r          Current row index.
     * @param c          Current column index.
     * @param parentR    Row index of the parent node (to prevent immediate backtracking).
     * @param parentC    Column index of the parent node.
     * @return true if a cycle is detected, false otherwise.
     */
    private static boolean dfs(char[][] grid, boolean[][] visited, int r, int c, int parentR, int parentC) {
        visited[r][c] = true;

        // Explore all 4 adjacent directions
        for (int i = 0; i < 4; i++) {
            int nr = r + DR[i];
            int nc = c + DC[i];

            if (isValid(nr, nc, grid)) {
                // Check if the adjacent cell has the same character
                if (grid[nr][nc] == grid[r][c]) {
                    if (!visited[nr][nc]) {
                        // If not visited, recurse
                        if (dfs(grid, visited, nr, nc, r, c)) {
                            return true;
                        }
                    } else if (nr != parentR || nc != parentC) {
                        // If visited and it's not the parent node, a cycle is detected.
                        // Note: The original code had a logic flaw here (parentR != r && parentC != c+1)
                        // which failed to detect cycles in certain horizontal/vertical configurations.
                        // The corrected logic checks if the neighbor is strictly NOT the parent.
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Checks if the given coordinates are within the grid boundaries.
     */
    private static boolean isValid(int r, int c, char[][] grid) {
        return r >= 0 && c >= 0 && r < grid.length && c < grid[r].length;
    }
}

