import java.util.StringTokenizer;

public class Main {

    public static void main(String[] args) throws IOException {
        FastScanner scanner = new FastScanner();
        int n = scanner.nextInt();
        int m = scanner.nextInt();

        // Read the character grid
        char[][] grid = new char[n][m];
        for (int i = 0; i < n; i++) {
            grid[i] = scanner.next().toCharArray();
        }

        // Build adjacency list for the graph.
        // Nodes are 1-indexed: index = i * m + j + 1
        int totalNodes = n * m;
        List<Set<Integer>> adjacencyList = new ArrayList<>(totalNodes + 1);
        for (int i = 0; i <= totalNodes; i++) {
            adjacencyList.add(new HashSet<>());
        }

        // Direction vectors for up, down, left, right
        int[] dr = {-1, 1, 0, 0};
        int[] dc = {0, 0, -1, 1};

        // Connect adjacent cells with identical characters
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                int u = i * m + j + 1;
                for (int k = 0; k < 4; k++) {
                    int ni = i + dr[k];
                    int nj = j + dc[k];

                    if (ni >= 0 && ni < n && nj >= 0 && nj < m && grid[ni][nj] == grid[i][j]) {
                        int v = ni * m + nj + 1;
                        adjacencyList.get(u).add(v);
                        adjacencyList.get(v).add(u);
                    }
                }
            }
        }

        // Detect cycles across all connected components
        boolean[] visited = new boolean[totalNodes + 1];
        boolean hasCycle = false;

        for (int i = 1; i <= totalNodes; i++) {
            if (!visited[i]) {
                if (hasCycleDFS(i, -1, visited, adjacencyList)) {
                    hasCycle = true;
                    break;
                }
            }
        }

        System.out.println(hasCycle ? "Yes" : "No");
    }

    /**
     * Recursive DFS to detect cycles in an undirected graph.
     *
     * @param node      Current node being visited
     * @param parent    Parent node in the DFS tree to avoid false cycle detection
     * @param visited   Array tracking visited nodes
     * @param adj       Adjacency list of the graph
     * @return true if a cycle is detected, false otherwise
     */
    private static boolean hasCycleDFS(int node, int parent, boolean[] visited, List<Set<Integer>> adj) {
        visited[node] = true;
        for (int neighbor : adj.get(node)) {
            if (!visited[neighbor]) {
                if (hasCycleDFS(neighbor, node, visited, adj)) {
                    return true;
                }
            } else if (neighbor != parent) {
                // Found a back edge to an already visited node that is not the direct parent
                return true;
            }
        }
        return false;
    }

    /**
     * Lightweight fast I/O helper to replace slow Scanner overhead.
     */
    private static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

