            writer.println("No");
        }
    }

    /**
     * Iterates through the grid to find connected components and checks for cycles.
     */
    private boolean hasCycle() {
        // Visited array to keep track of processed cells
        boolean[][] visited = new boolean[n][m];

        // Iterate through every cell in the grid
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                // If cell is not a wall ('#') and not yet visited
                if (grid[i][j] != '#' && !visited[i][j]) {
                    // Start BFS from this cell to explore the component
                    if (bfs(i, j, visited)) {
                        return true; // Cycle detected
                    }
                }
            }
        }
        return false;
    }

    /**
     * Performs BFS to detect if a cycle exists in the connected component
     * starting from (startRow, startCol).
     * 
     * @param startRow Starting row index
     * @param startCol Starting column index
     * @param visited  2D array tracking visited cells
     * @return true if a cycle is found, false otherwise
     */
    private boolean bfs(int startRow, int startCol, boolean[][] visited) {
        // Queue stores arrays: {currentRow, currentCol, parentRow, parentCol}
        // Storing parent allows us to distinguish between a back-edge to the 
        // immediate parent (which is valid in trees) and a cycle (cross-edge).
        Queue<int[]> queue = new LinkedList<>();
        queue.offer(new int[]{startRow, startCol, -1, -1});
        visited[startRow][startCol] = true;

        while (!queue.isEmpty()) {
            int[] current = queue.poll();
            int r = current[0];
            int c = current[1];
            int pR = current[2];
            int pC = current[3];

            // Explore neighbors
            for (int[] dir : DIRECTIONS) {
                int nr = r + dir[0];
                int nc = c + dir[1];

                // Check boundaries
                if (nr >= 0 && nr < n && nc >= 0 && nc < m) {
                    // Check if neighbor has the same character
                    if (grid[nr][nc] == grid[r][c]) {
                        if (!visited[nr][nc]) {
                            // If not visited, mark it and add to queue
                            visited[nr][nc] = true;
                            queue.offer(new int[]{nr, nc, r, c});
                        } else {
                            // If visited, check if it's the parent.
                            // If it's visited and NOT the parent, we found a cycle.
                            if (nr != pR || nc != pC) {
                                return true;
                            }
                        }
                    }
                }
            }
        }
        return false;
    }

    /**
     * Helper class for fast input reading.
     */
    private static class FastScanner {
        private BufferedReader br;
        private StringTokenizer st;

        public FastScanner(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        public String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            String s = next();
            if (s == null) throw new RuntimeException("Unexpected end of input");
            return Integer.parseInt(s);
        }
    }
}

