            int[][] grid = new int[rows][cols];
            for (int i = 0; i < rows; i++) {
                String line = br.readLine();
                for (int j = 0; j < cols; j++) {
                    // Convert character to 1-based index (A=1, B=2, ...)
                    grid[i][j] = line.charAt(j) - 'A' + 1;
                }
            }

            boolean[][] visited = new boolean[rows][cols];
            boolean cycleFound = false;

            // Iterate through each cell to handle disconnected components
            for (int i = 0; i < rows && !cycleFound; i++) {
                for (int j = 0; j < cols && !cycleFound; j++) {
                    if (!visited[i][j]) {
                        cycleFound = dfs(i, j, -1, -1, grid, visited);
                    }
                }
            }

            out.println(cycleFound ? "Yes" : "No");
        }
    }

    /**
     * Performs DFS to detect cycles in the grid graph.
     *
     * @param r         Current row
     * @param c         Current column
     * @param parentR   Row of the parent node
     * @param parentC   Column of the parent node
     * @param grid      The input grid
     * @param visited   Tracks visited cells
     * @return true if a cycle is found, false otherwise
     */
    private static boolean dfs(int r, int c, int parentR, int parentC, int[][] grid, boolean[][] visited) {
        visited[r][c] = true;

        for (int[] dir : DIRECTIONS) {
            int nr = r + dir[0];
            int nc = c + dir[1];

            // Check boundaries
            if (nr >= 0 && nr < grid.length && nc >= 0 && nc < grid[0].length) {
                // Only traverse cells with the same value
                if (grid[nr][nc] == grid[r][c]) {
                    if (visited[nr][nc]) {
                        // If visited and not the parent, a cycle exists
                        if (nr != parentR || nc != parentC) {
                            return true;
                        }
                    } else {
                        // Continue DFS
                        if (dfs(nr, nc, r, c, grid, visited)) {
                            return true;
                        }
                    }
                }
            }
        }
        return false;
    }
}

import java.util.Scanner;

public class Main {
    // Direction vectors for moving Right, Down, Left, Up
    private static final int[] DR = {0, 1, 0, -1};
    private static final int[] DC = {1, 0, -1, 0};

    private char[][] grid;
    private boolean[][] visited;
    private int rows;
    private int cols;

    public static void main(String[] args) {
        Main solver = new Main();
        solver.solve();
    }

    public void solve() {
        // Use try-with-resources to ensure the scanner is closed
        try (Scanner scanner = new Scanner(System.in)) {
            if (!scanner.hasNextInt()) return;

            // Read grid dimensions
            this.rows = scanner.nextInt();
            this.cols = scanner.nextInt();

            // Initialize grid and visited array
            this.grid = new char[rows][cols];
            this.visited = new boolean[rows][cols];

            // Read the grid content
            for (int i = 0; i < rows; i++) {
                String line = scanner.next();
                this.grid[i] = line.toCharArray();
            }

            // Iterate through each cell to detect cycles
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    // If the cell hasn't been visited, start a DFS
                    if (!visited[i][j]) {
                        if (hasCycle(i, j, -1, -1, grid[i][j])) {
                            System.out.println("Yes");
                            return;
                        }
                    }
                }
            }

            // If no cycle is found after checking the entire grid
            System.out.println("No");
        }
    }

    /**
     * Performs a Depth First Search (DFS) to detect a cycle in the grid.
     * 
     * @param r           Current row index
     * @param c           Current column index
     * @param parentR     Row index of the parent node (to prevent immediate backtracking)
     * @param parentC     Column index of the parent node
     * @param targetChar  The character type that must match for the path to continue
     * @return            true if a cycle is detected, false otherwise
     */
    private boolean hasCycle(int r, int c, int parentR, int parentC, char targetChar) {
        // Mark the current cell as visited
        visited[r][c] = true;

        // Explore all 4 adjacent directions
        for (int k = 0; k < 4; k++) {
            int nextR = r + DR[k];
            int nextC = c + DC[k];

            // 1. Check boundaries
            if (nextR < 0 || nextR >= rows || nextC < 0 || nextC >= cols) {
                continue;
            }

            // 2. Check if the neighbor has the same character
            if (grid[nextR][nextC] != targetChar) {
                continue;
            }

            // 3. Check if the neighbor is the immediate parent (avoid going back up the tree)
            if (nextR == parentR && nextC == parentC) {
                continue;
            }

            // 4. If the neighbor is already visited, we have found a cycle
            if (visited[nextR][nextC]) {
                return true;
            }

            // 5. Recursively visit the unvisited neighbor
            if (hasCycle(nextR, nextC, r, c, targetChar)) {
                return true;
            }
        }
        return false;
    }
}

