/**
 * Refactored solution for detecting cycles in a grid of characters.
 * 
 * Improvements made:
 * 1. Class and variable naming: Replaced generic names (ProblemB, rd, n, m, c, v, k, prev) 
 *    with descriptive names (GridCycleDetector, rows, cols, grid, visited, etc.).
 * 2. Modularity: Separated input parsing, grid processing, and cycle detection logic.
 * 3. Algorithm Optimization: 
 *    - Replaced the 'prev' array and 'k' component ID tracking with a simpler 
 *      'visited' boolean array and parent tracking via the BFS Queue.
 *    - Used ArrayDeque instead of LinkedList for better performance.
 * 4. Input Handling: Replaced custom string splitting logic with BufferedReader 
 *    and StringTokenizer for robust and efficient parsing.
 * 5. Readability: Added comments and structured the code for better flow.
 */
public class GridCycleDetector {

    public static void main(String[] args) {
        GridCycleDetector solver = new GridCycleDetector();
        try {
            solver.solve();
        } catch (IOException e) {
            System.err.println("Error reading input: " + e.getMessage());
        }
    }

    private void solve() throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));

        // Read the first line to get the number of rows (N)
        // The original code inferred M from the grid width, so we do the same.
        String line = br.readLine();
        if (line == null || line.trim().isEmpty()) {
            return;
        }

        StringTokenizer st = new StringTokenizer(line);
        int rows = Integer.parseInt(st.nextToken());

        // Note: The original code ignored the second integer if present (M), 
        // deriving it from grid[0].length. We preserve this behavior.

        char[][] grid = new char[rows][];
        for (int i = 0; i < rows; i++) {
            String rowLine = br.readLine();
            // Handle potential null if input ends prematurely
            if (rowLine == null) {
                break;
            }
            grid[i] = rowLine.toCharArray();
        }

        if (rows == 0 || grid[0] == null) {
            System.out.println("No");
            return;
        }

        int cols = grid[0].length;
        boolean[][] visited = new boolean[rows][cols];

        // Iterate through every cell to handle disconnected components
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (!visited[i][j]) {
                    if (hasCycle(i, j, grid, visited)) {
                        System.out.println("Yes");
                        return;
                    }
                }
            }
        }

        System.out.println("No");
    }

    /**
     * Performs BFS to detect a cycle in the connected component starting at (startR, startC).
     * 
     * @param startR The starting row index.
     * @param startC The starting column index.
     * @param grid The character grid.
     * @param visited A 2D array tracking visited cells.
     * @return true if a cycle is detected, false otherwise.
     */
    private boolean hasCycle(int startR, int startC, char[][] grid, boolean[][] visited) {
        // Queue stores: {currentRow, currentCol, parentRow, parentCol}
        // Using ArrayDeque is more efficient than LinkedList for queue operations.
        Queue<int[]> queue = new ArrayDeque<>();
        queue.offer(new int[]{startR, startC, -1, -1});
        visited[startR][startC] = true;

        // Direction vectors for moving up, down, left, right
        int[] dr = {-1, 1, 0, 0};
        int[] dc = {0, 0, -1, 1};

        while (!queue.isEmpty()) {
            int[] current = queue.poll();
            int r = current[0];
            int c = current[1];
            int pR = current[2];
            int pC = current[3];

            char currentChar = grid[r][c];

            for (int k = 0; k < 4; k++) {
                int nr = r + dr[k];
                int nc = c + dc[k];

                // Check bounds
                if (nr >= 0 && nr < grid.length && nc >= 0 && nc < grid[0].length) {
                    // Check if neighbor has the same character
                    if (grid[nr][nc] == currentChar) {
                        if (!visited[nr][nc]) {
                            // If not visited, mark it and add to queue with current node as parent
                            visited[nr][nc] = true;
                            queue.offer(new int[]{nr, nc, r, c});
                        } else if (nr != pR || nc != pC) {
                            // If visited and it is NOT the parent node, a cycle exists
                            return true;
                        }
                    }
                }
            }
        }
        return false;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.Arrays;
import java.util.StringTokenizer;

public class Main {
    // Constants
    private static final int MIN_CYCLE_LENGTH = 4;
    // Directions: Up, Down, Left, Right
    private static final int[] DR = {-1, 1, 0, 0};
    private static final int[] DC = {0, 0, -1, 1};

    // State variables encapsulated within the instance
    private int rows, cols;
    private char[][] grid;
    private int[][] depthMap; // Tracks the depth of the current path
    private boolean[][] visited;
    private boolean cycleFound;

    public static void main(String[] args) throws IOException {
        // Initialize BufferedReader for efficient input reading
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));

        // Read dimensions N and M
        String line = reader.readLine();
        if (line == null) return; // Handle empty input gracefully

        StringTokenizer tokenizer = new StringTokenizer(line);
        // Ensure tokens exist before parsing to avoid exceptions
        if (!tokenizer.hasMoreTokens()) return;
        int n = Integer.parseInt(tokenizer.nextToken());

        if (!tokenizer.hasMoreTokens()) return;
        int m = Integer.parseInt(tokenizer.nextToken());

        // Create solver instance and run
        Main solver = new Main();
        solver.init(n, m, reader);
        solver.solve();
    }

    /**
     * Initializes the grid and auxiliary arrays.
     */
    private void init(int n, int m, BufferedReader reader) throws IOException {
        this.rows = n;
        this.cols = m;
        this.grid = new char[n][m];
        this.depthMap = new int[n][m];
        this.visited = new boolean[n][m];
        this.cycleFound = false;

        // Read the grid content
        for (int i = 0; i < n; i++) {
            String rowStr = reader.readLine();
            if (rowStr != null) {
                // Safety check for line length to prevent IndexOutOfBounds
                int limit = Math.min(m, rowStr.length());
                for (int j = 0; j < limit; j++) {
                    grid[i][j] = rowStr.charAt(j);
                }
            }
            // Initialize depth map for the current row to -1 (representing unvisited)
            Arrays.fill(depthMap[i], -1);
        }
    }

    /**
     * Main logic to detect cycles in the grid.
     */
    private void solve() {
        // Iterate through every cell to ensure all connected components are checked
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                // If the cell hasn't been visited, start a DFS traversal
                if (!visited[i][j]) {
                    dfs(i, j, 0);

                    // If a cycle of length >= 4 is found, output "Yes" and terminate
                    if (cycleFound) {
                        System.out.println("Yes");
                        return;
                    }
                }
            }
        }

        // If no cycle is found after checking all cells
        System.out.println("No");
    }

    /**
     * Depth First Search (DFS) to traverse the grid and detect cycles.
     * 
     * @param r Current row index
     * @param c Current column index
     * @param currentDepth The depth of the current node in the traversal path
     */
    private void dfs(int r, int c, int currentDepth) {
        visited[r][c] = true;
        depthMap[r][c] = currentDepth;

        // Explore all 4 adjacent directions
        for (int k = 0; k < 4; k++) {
            int nextR = r + DR[k];
            int nextC = c + DC[k];

            // Check boundaries
            if (nextR < 0 || nextR >= rows || nextC < 0 || nextC >= cols) {
                continue;
            }

            // Check if the neighbor has the same character
            if (grid[nextR][nextC] != grid[r][c]) {
                continue;
            }

            // Cycle detection logic
            // If the neighbor has been visited in the current path (depthMap != -1)
            if (depthMap[nextR][nextC] != -1) {
                // Calculate cycle length: current_depth - neighbor_depth + 1
                if (currentDepth - depthMap[nextR][nextC] + 1 >= MIN_CYCLE_LENGTH) {
                    cycleFound = true;
                    return;
                }
            } 
            // If neighbor not visited, continue DFS
            else if (!visited[nextR][nextC]) {
                dfs(nextR, nextC, currentDepth + 1);
                // Optimization: Stop recursion if cycle is already found
                if (cycleFound) {
                    return;
                }
            }
        }
    }
}

import java.util.Scanner;

/**
 * Detects cycles in a 2D character grid.
 * A cycle exists if there is a path of identical characters that starts and ends at the same cell,
 * moving only to adjacent cells (up, down, left, right).
 */
public class GridCycleDetector {

    private static final int[] ROW_DIRECTIONS = {-1, 1, 0, 0};
    private static final int[] COL_DIRECTIONS = {0, 0, -1, 1};

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            if (!scanner.hasNextInt()) {
                return;
            }
            int rows = scanner.nextInt();
            int cols = scanner.nextInt();

            char[][] grid = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                String rowString = scanner.next();
                grid[i] = rowString.toCharArray();
            }

            boolean[][] visited = new boolean[rows][cols];
            boolean cycleFound = false;

            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (!visited[i][j]) {
                        if (hasCycle(grid, visited, i, j, -1, -1)) {
                            cycleFound = true;
                            break;
                        }
                    }
                }
                if (cycleFound) {
                    break;
                }
            }

            System.out.println(cycleFound ? "Yes" : "No");
        }
    }

    /**
     * Performs DFS to detect cycles in the grid.
     *
     * @param grid        The character grid
     * @param visited     Tracks visited cells
     * @param row         Current row index
     * @param col         Current column index
     * @param parentRow   Row index of the parent cell (to avoid going back)
     * @param parentCol   Column index of the parent cell
     * @return true if a cycle is detected, false otherwise
     */
    private static boolean hasCycle(char[][] grid, boolean[][] visited, int row, int col, int parentRow, int parentCol) {
        visited[row][col] = true;

        for (int k = 0; k < 4; k++) {
            int newRow = row + ROW_DIRECTIONS[k];
            int newCol = col + COL_DIRECTIONS[k];

            // Check boundaries
            if (newRow < 0 || newRow >= grid.length || newCol < 0 || newCol >= grid[0].length) {
                continue;
            }

            // Skip the parent cell to avoid immediate backtracking
            if (newRow == parentRow && newCol == parentCol) {
                continue;
            }

            // Check if the adjacent cell has the same character
            if (grid[newRow][newCol] == grid[row][col]) {
                // If already visited, a cycle is found
                if (visited[newRow][newCol]) {
                    return true;
                }
                // Recursively explore unvisited cells
                if (hasCycle(grid, visited, newRow, newCol, row, col)) {
                    return true;
                }
            }
        }
        return false;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

/**
 * Refactored Grid Cycle Finder.
 * 
 * Improvements made:
 * 1. Encapsulation: Moved logic into methods and removed global static state.
 * 2. Readability: Replaced magic numbers (-1000000000) with meaningful constants (0 for unvisited).
 * 3. Performance: Used char[][] instead of String[] for grid storage to avoid repeated charAt() calls.
 * 4. Robustness: Used BufferedReader with StringTokenizer for safer input parsing.
 * 5. Resource Management: Used try-with-resources for automatic stream closing.
 * 6. Naming: Used descriptive variable names (rows, cols, targetChar, etc.).
 */
public class Main {

    // Constants for movement directions (Up, Down, Left, Right)
    private static final int[] ROW_OFFSETS = {-1, 1, 0, 0};
    private static final int[] COL_OFFSETS = {0, 0, -1, 1};

    // Sentinel value for unvisited nodes (0 is the default initialization for int arrays)
    private static final int UNVISITED = 0;

    public static void main(String[] args) throws IOException {
        // Use try-with-resources to ensure the reader is closed automatically
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(System.in))) {

            // Read dimensions
            String line = reader.readLine();
            if (line == null) return;

            StringTokenizer tokenizer = new StringTokenizer(line);
            if (!tokenizer.hasMoreTokens()) return;

            int rows = Integer.parseInt(tokenizer.nextToken());
            int cols = Integer.parseInt(tokenizer.nextToken());

            // Use char[][] for efficient character access
            char[][] grid = new char[rows][cols];

            for (int i = 0; i < rows; i++) {
                String rowStr = reader.readLine();
                if (rowStr != null) {
                    grid[i] = rowStr.toCharArray();
                }
            }

            // Visited array stores the depth at which a cell was visited.
            // 0 indicates unvisited.
            int[][] visited = new int[rows][cols];

            boolean cycleFound = false;

            // Iterate through every cell to handle disconnected components
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    // If cell is unvisited, start DFS
                    if (visited[i][j] == UNVISITED) {
                        if (dfs(grid, visited, i, j, 1, grid[i][j])) {
                            cycleFound = true;
                            break;
                        }
                    }
                }
                if (cycleFound) break;
            }

            System.out.println(cycleFound ? "Yes" : "No");

        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    /**
     * Performs Depth First Search to detect a cycle of identical characters.
     * 
     * @param grid The character grid
     * @param visited 2D array storing the depth of visitation (0 if unvisited)
     * @param r Current row
     * @param c Current column
     * @param depth Current depth in the DFS tree
     * @param targetChar The character we are tracing
     * @return true if a cycle is found, false otherwise
     */
    private static boolean dfs(char[][] grid, int[][] visited, int r, int c, int depth, char targetChar) {
        // Mark current cell with current depth
        visited[r][c] = depth;

        // Explore neighbors
        for (int i = 0; i < 4; i++) {
            int nr = r + ROW_OFFSETS[i];
            int nc = c + COL_OFFSETS[i];

            if (isValid(grid, nr, nc)) {
                // Check if neighbor has the same character
                if (grid[nr][nc] == targetChar) {
                    // Check if neighbor is already visited
                    if (visited[nr][nc] != UNVISITED) {
                        // If visited, it must not be the immediate parent in the DFS tree.
                        // The parent's depth would be depth - 1.
                        if (visited[nr][nc] != depth - 1) {
                            return true; // Cycle detected
                        }
                    } else {
                        // Neighbor is unvisited, recurse
                        if (dfs(grid, visited, nr, nc, depth + 1, targetChar)) {
                            return true;
                        }
                    }
                }
            }
        }
        return false;
    }

    /**
     * Checks if coordinates are within grid bounds.
     */
    private static boolean isValid(char[][] grid, int r, int c) {
        return r >= 0 && r < grid.length && c >= 0 && c < grid[r].length;
    }
}

