/**
 * Refactored solution for FoxAndTwoDots.
 * 
 * Problem: Determine if there is a cycle of length at least 4 consisting of 
 * identical characters in a grid.
 * 
 * Improvements:
 * 1. Complexity: Reduced from O((N*M)^2) to O(N*M) using efficient DFS.
 * 2. Maintainability: Encapsulated logic, descriptive naming, and Javadoc.
 * 3. Robustness: Safer input handling and direction vector iteration.
 */
public class FoxAndTwoDots {

    private final int rows;
    private final int cols;
    private final char[][] grid;
    private final boolean[][] visited;

    /**
     * Constructs the solver with the given grid dimensions and content.
     *
     * @param rows Number of rows in the grid.
     * @param cols Number of columns in the grid.
     * @param grid The character grid to analyze.
     */
    public FoxAndTwoDots(int rows, int cols, char[][] grid) {
        this.rows = rows;
        this.cols = cols;
        this.grid = grid;
        this.visited = new boolean[rows][cols];
    }

    /**
     * Entry point for the solution logic.
     * Iterates through the grid to find any cycle in connected components.
     *
     * @return true if a cycle is found, false otherwise.
     */
    public boolean hasCycle() {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                // If the cell hasn't been visited yet, start a DFS from here.
                // This ensures we explore every connected component of identical characters.
                if (!visited[r][c]) {
                    // Parent coordinates are (-1, -1) to indicate no parent for the root of the DFS tree.
                    if (dfs(r, c, -1, -1, grid[r][c])) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Performs Depth First Search to detect a cycle.
     * 
     * In a grid graph (which is bipartite), any cycle must have a length of at least 4.
     * Therefore, detecting any back-edge to a visited node (that is not the immediate parent)
     * is sufficient to confirm a valid cycle.
     *
     * @param r Current row index.
     * @param c Current column index.
     * @param parentR Row index of the previous node in the path.
     * @param parentC Column index of the previous node in the path.
     * @param type The character type we are tracking for this path.
     * @return true if a cycle is detected, false otherwise.
     */
    private boolean dfs(int r, int c, int parentR, int parentC, char type) {
        visited[r][c] = true;

        // Directions: Up, Down, Left, Right
        int[] dr = {-1, 1, 0, 0};
        int[] dc = {0, 0, -1, 1};

        for (int i = 0; i < 4; i++) {
            int nr = r + dr[i];
            int nc = c + dc[i];

            // Check boundary conditions
            if (nr >= 0 && nr < rows && nc >= 0 && nc < cols) {
                // Check if the neighbor has the same character
                if (grid[nr][nc] == type) {
                    // If the neighbor is already visited, we have a cycle
                    // EXCEPT if it is the immediate parent (which is just going back up the tree)
                    if (visited[nr][nc] && (nr != parentR || nc != parentC)) {
                        return true;
                    }
                    // If not visited, continue DFS
                    if (!visited[nr][nc]) {
                        if (dfs(nr, nc, r, c, type)) {
                            return true;
                        }
                    }
                }
            }
        }
        return false;
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        // Check for valid input
        if (scanner.hasNextInt()) {
            int n = scanner.nextInt();
            int m = scanner.nextInt();
            scanner.nextLine(); // Consume the newline character after integers

            char[][] grid = new char[n][m];
            for (int i = 0; i < n; i++) {
                String line = scanner.nextLine();
                // Fill the row, handling potential short lines safely
                for (int j = 0; j < m; j++) {
                    if (j < line.length()) {
                        grid[i][j] = line.charAt(j);
                    } else {
                        grid[i][j] = ' '; // Default placeholder if input is malformed
                    }
                }
            }

            FoxAndTwoDots solver = new FoxAndTwoDots(n, m, grid);

            if (solver.hasCycle()) {
                System.out.println("Yes");
            } else {
                System.out.println("No");
            }
        }
        scanner.close();
    }
}

import java.util.Scanner;

/**
 * GridCycleDetector analyzes a 2D grid of characters to detect cycles.
 * A cycle exists if there is a path between two adjacent cells with the same character
 * that does not immediately backtrack to the previous node.
 */
public class GridCycleDetector {

    // Instance variables for encapsulation instead of static global state
    private int rows, cols;
    private char[][] grid;
    private boolean[][] visited;
    private int[][] parentRow;
    private int[][] parentCol;

    public static void main(String[] args) {
        GridCycleDetector detector = new GridCycleDetector();
        detector.solve();
    }

    /**
     * Main entry point for the logic. Coordinates reading, processing, and output.
     */
    private void solve() {
        readInput();

        // Iterate through every cell in the grid to find connected components
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                // If the cell hasn't been visited, start a BFS from here
                if (!visited[i][j]) {
                    if (bfs(i, j)) {
                        System.out.println("Yes");
                        return; // Cycle found, exit program
                    }
                }
            }
        }

        // If no cycle is found after checking all components
        System.out.println("No");
    }

    /**
     * Reads input from Standard Input.
     */
    private void readInput() {
        Scanner scanner = new Scanner(System.in);

        if (scanner.hasNextInt()) {
            rows = scanner.nextInt();
            cols = scanner.nextInt();
        } else {
            return; // Handle empty input gracefully
        }

        // Consume the newline character left after nextInt()
        scanner.nextLine();

        // Initialize data structures based on input dimensions
        grid = new char[rows][cols];
        visited = new boolean[rows][cols];
        parentRow = new int[rows][cols];
        parentCol = new int[rows][cols];

        for (int i = 0; i < rows; i++) {
            String line = scanner.nextLine();
            // Handle potential line length mismatches, though input is usually guaranteed correct
            if (line.length() >= cols) {
                grid[i] = line.substring(0, cols).toCharArray();
            } else {
                grid[i] = line.toCharArray();
            }
        }
    }

    /**
     * Performs Breadth-First Search (BFS) to detect cycles in the connected component.
     * 
     * @param startRow The starting row index
     * @param startCol The starting column index
     * @return true if a cycle is detected, false otherwise
     */
    private boolean bfs(int startRow, int startCol) {
        // Queue for BFS: stores coordinates [row, col]
        // Max size is rows * cols because each node is enqueued at most once
        int[] qRow = new int[rows * cols];
        int[] qCol = new int[rows * cols];
        int head = 0;
        int tail = 0;

        // Initialize start node
        qRow[tail] = startRow;
        qCol[tail] = startCol;
        tail++;

        visited[startRow][startCol] = true;
        // Mark root as having no parent (-1, -1)
        parentRow[startRow][startCol] = -1; 
        parentCol[startRow][startCol] = -1;

        // Directions: Up, Down, Left, Right
        // This reduces code duplication (DRY principle)
        int[] dRow = {-1, 1, 0, 0};
        int[] dCol = {0, 0, -1, 1};

        while (head < tail) {
            int currRow = qRow[head];
            int currCol = qCol[head];
            head++;

            char currentChar = grid[currRow][currCol];

            // Check all 4 neighbors
            for (int k = 0; k < 4; k++) {
                int nextRow = currRow + dRow[k];
                int nextCol = currCol + dCol[k];

                // Check bounds
                if (nextRow >= 0 && nextRow < rows && nextCol >= 0 && nextCol < cols) {
                    // Check if neighbor has the same character
                    if (grid[nextRow][nextCol] == currentChar) {
                        if (visited[nextRow][nextCol]) {
                            // If visited, it must be the parent node we came from.
                            // If it's not the parent, we found a cycle.
                            if (!(nextRow == parentRow[currRow][currCol] && nextCol == parentCol[currRow][currCol])) {
                                return true; // Cycle detected
                            }
                        } else {
                            // If not visited, mark it and add to queue
                            visited[nextRow][nextCol] = true;
                            parentRow[nextRow][nextCol] = currRow;
                            parentCol[nextRow][nextCol] = currCol;

                            qRow[tail] = nextRow;
                            qCol[tail] = nextCol;
                            tail++;
                        }
                    }
                }
            }
        }

        return false; // No cycle found in this component
    }
}

import java.io.BufferedReader;
import java.io.BufferedWriter;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.OutputStreamWriter;
import java.io.PrintWriter;
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Deque;
import java.util.List;

public class Main {

    public static void main(String[] args) throws IOException {
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
             PrintWriter writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)))) {

            String[] dims = reader.readLine().trim().split("\\s+");
            int n = Integer.parseInt(dims[0]);
            int m = Integer.parseInt(dims[1]);

            char[][] grid = new char[n][m];
            for (int i = 0; i < n; i++) {
                String row = reader.readLine().trim();
                grid[i] = row.toCharArray();
            }

            boolean hasCycle = detectCycle(grid, n, m);
            writer.println(hasCycle ? "Yes" : "No");
            writer.flush();
        }
    }

    private static boolean detectCycle(char[][] grid, int n, int m) {
        Node[][] nodes = buildGraph(grid, n, m);
        boolean[][] visited = new boolean[n][m];

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (!visited[i][j]) {
                    if (dfsCycle(nodes, visited, i, j, null)) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    private static boolean dfsCycle(Node[][] nodes, boolean[][] visited, int r, int c, Node parent) {
        Deque<Node> stack = new ArrayDeque<>();
        Deque<Node> parentStack = new ArrayDeque<>();

        stack.push(nodes[r][c]);
        parentStack.push(parent);
        visited[r][c] = true;

        while (!stack.isEmpty()) {
            Node curr = stack.pop();
            Node currParent = parentStack.pop();

            for (Node neighbor : curr.getNeighbors()) {
                if (visited[neighbor.getR()][neighbor.getC()]) {
                    if (neighbor != currParent) {
                        return true; // Cycle detected in undirected graph
                    }
                } else {
                    visited[neighbor.getR()][neighbor.getC()] = true;
                    stack.push(neighbor);
                    parentStack.push(curr);
                }
            }
        }
        return false;
    }

    private static Node[][] buildGraph(char[][] grid, int n, int m) {
        Node[][] nodes = new Node[n][m];
        int[] dr = {-1, 1, 0, 0};
        int[] dc = {0, 0, -1, 1};

        // Initialize nodes
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                nodes[i][j] = new Node(i, j, grid[i][j]);
            }
        }

        // Build adjacency lists
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                Node current = nodes[i][j];
                List<Node> neighbors = new ArrayList<>(4);
                for (int k = 0; k < 4; k++) {
                    int ni = i + dr[k];
                    int nj = j + dc[k];
                    if (ni >= 0 && ni < n && nj >= 0 && nj < m && grid[ni][nj] == current.color) {
                        neighbors.add(nodes[ni][nj]);
                    }
                }
                current.setNeighbors(neighbors);
            }
        }
        return nodes;
    }

    static class Node {
        final int r, c;
        final char color;
        private List<Node> neighbors;

        public Node(int r, int c, char color) {
            this.r = r;
            this.c = c;
            this.color = color;
        }

        public List<Node> getNeighbors() {
            return neighbors;
        }

        public void setNeighbors(List<Node> neighbors) {
            this.neighbors = neighbors;
        }

        public int getR() {
            return r;
        }

        public int getC() {
            return c;
        }
    }
}

import java.util.LinkedList;
import java.util.Queue;
import java.util.Scanner;

/**
 * Solution for Codeforces 510B - Fox And Two Dots.
 * Detects if there is a cycle of identical characters in the grid.
 */
public class FoxAndTwoDots {

    // Direction vectors: Down, Up, Right, Left
    // Index 0: Down (1, 0)
    // Index 1: Up (-1, 0)
    // Index 2: Right (0, 1)
    // Index 3: Left (0, -1)
    private static final int[] DX = {1, -1, 0, 0};
    private static final int[] DY = {0, 0, 1, -1};

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        // Read grid dimensions
        if (!scanner.hasNextInt()) return;
        int n = scanner.nextInt();
        int m = scanner.nextInt();

        // Read the grid
        char[][] grid = new char[n][m];
        for (int i = 0; i < n; i++) {
            String row = scanner.next();
            grid[i] = row.toCharArray();
        }

        // Solve the problem
        boolean hasCycle = solve(n, m, grid);

        // Output result
        System.out.println(hasCycle ? "Yes" : "No");

        scanner.close();
    }

    /**
     * Orchestrates the cycle detection process.
     */
    private static boolean solve(int n, int m, char[][] grid) {
        boolean[][] visited = new boolean[n][m];

        // Iterate through every cell to handle disconnected components
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                // If the cell has not been visited, start a BFS from here
                if (!visited[i][j]) {
                    if (bfs(i, j, n, m, grid, visited)) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Performs BFS to detect a cycle starting from (startX, startY).
     * 
     * @param startX Starting X coordinate
     * @param startY Starting Y coordinate
     * @param n Number of rows
     * @param m Number of columns
     * @param grid The character grid
     * @param visited Visited matrix to keep track of explored cells
     * @return true if a cycle is found, false otherwise
     */
    private static boolean bfs(int startX, int startY, int n, int m, char[][] grid, boolean[][] visited) {
        Queue<State> queue = new LinkedList<>();

        // Add starting state: current position, no parent (-1, -1)
        queue.add(new State(startX, startY, -1, -1));
        visited[startX][startY] = true;

        while (!queue.isEmpty()) {
            State current = queue.poll();

            // Explore all 4 directions
            for (int k = 0; k < 4; k++) {
                int nx = current.x + DX[k];
                int ny = current.y + DY[k];

                // 1. Boundary check
                if (nx < 0 || nx >= n || ny < 0 || ny >= m) {
                    continue;
                }

                // 2. Character match check (cycle must consist of same characters)
                if (grid[current.x][current.y] != grid[nx][ny]) {
                    continue;
                }

                // 3. Parent check (do not go back to the immediate previous cell)
                if (nx == current.prevX && ny == current.prevY) {
                    continue;
                }

                // 4. Cycle detection
                // If the neighbor is already visited, it means we found a path 
                // to an already explored node, forming a cycle.
                if (visited[nx][ny]) {
                    return true;
                }

                // 5. Mark as visited and enqueue
                visited[nx][ny] = true;
                queue.add(new State(nx, ny, current.x, current.y));
            }
        }
        return false;
    }

    /**
     * Represents a state in the BFS traversal.
     */
    private static class State {
        int x, y;       // Current coordinates
        int prevX, prevY; // Coordinates of the parent node (to prevent immediate backtrack)

        State(int x, int y, int prevX, int prevY) {
            this.x = x;
            this.y = y;
            this.prevX = prevX;
            this.prevY = prevY;
        }
    }
}

