/**
 * Solver class for detecting cycles in a character grid.
 * A cycle is defined as a path of identical characters that connects back to a previously visited node
 * in the current traversal, excluding the immediate parent node.
 */
class GridCycleSolver {
    // Direction vectors for moving Up, Right, Down, Left
    private static final int[] DX = {-1, 0, 0, 1};
    private static final int[] DY = {0, 1, -1, 0};

    /**
     * Determines if the grid contains a cycle of identical characters.
     * 
     * @param grid The 2D character array representing the grid.
     * @return true if a cycle is found, false otherwise.
     */
    public boolean hasCycle(char[][] grid) {
        if (grid == null || grid.length == 0) {
            return false;
        }

        int n = grid.length;
        int m = grid[0].length;

        // Visited array to keep track of visited cells during DFS.
        // Using a single global visited array is efficient (O(N*M)) compared to 
        // resetting it for every starting cell in the original code.
        boolean[][] visited = new boolean[n][m];

        // Iterate through every cell in the grid to handle disconnected components
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                // If the cell hasn't been visited, start a DFS from here
                if (!visited[i][j]) {
                    if (dfs(grid, i, j, -1, -1, visited)) {
                        return true; // Cycle detected
                    }
                }
            }
        }
        return false;
    }

    /**
     * Depth First Search to detect cycles.
     * 
     * @param grid The grid data.
     * @param x Current row index.
     * @param y Current column index.
     * @param prevX Row index of the previous cell (to avoid backtracking immediately).
     * @param prevY Column index of the previous cell.
     * @param visited 2D boolean array tracking visited cells.
     * @return true if a cycle is detected in the current path/component.
     */
    private boolean dfs(char[][] grid, int x, int y, int prevX, int prevY, boolean[][] visited) {
        visited[x][y] = true;

        // Check all 4 possible directions
        for (int k = 0; k < 4; k++) {
            int nx = x + DX[k];
            int ny = y + DY[k];

            // Check boundaries
            if (nx >= 0 && nx < grid.length && ny >= 0 && ny < grid[0].length) {

                // Check if the neighbor is the immediate parent node.
                // In an undirected graph DFS, we must not go back to the node we just came from.
                if (nx == prevX && ny == prevY) {
                    continue;
                }

                // Check if the neighbor has the same character as the current cell
                if (grid[nx][ny] == grid[x][y]) {
                    if (visited[nx][ny]) {
                        // If we encounter a visited node that is not the parent,
                        // it means we found a back-edge, which indicates a cycle.
                        return true;
                    }

                    // If not visited, recurse
                    if (dfs(grid, nx, ny, x, y, visited)) {
                        return true;
                    }
                }
            }
        }
        return false;
    }
}

