/**
 * Detects if there is a cycle in a grid where adjacent cells with the same character form edges.
 * Refactored for improved maintainability, readability, and performance.
 */
public class TaskB {

    // Direction vectors for moving Right, Down, Left, Up
    private static final int[] DX = {1, 0, -1, 0};
    private static final int[] DY = {0, 1, 0, -1};

    private int rows;
    private int cols;
    private char[][] grid;
    private boolean[][] visited;
    private boolean hasCycle;

    private Scanner scanner;
    private PrintWriter out;

    public TaskB() {
        this.scanner = new Scanner(System.in);
        this.out = new PrintWriter(new OutputStreamWriter(System.out));
    }

    public static void main(String[] args) {
        TaskB solver = new TaskB();
        solver.run();
    }

    /**
     * Orchestrates the reading, solving, and output phases.
     */
    public void run() {
        readInput();
        solve();
        outputResult();
    }

    /**
     * Reads the grid dimensions and the grid content from input.
     */
    private void readInput() {
        if (scanner.hasNextInt()) {
            this.rows = scanner.nextInt();
            this.cols = scanner.nextInt();
            // Using char[][] is more efficient than List<String> for grid access
            this.grid = new char[rows][cols];

            for (int i = 0; i < rows; i++) {
                String line = scanner.next();
                this.grid[i] = line.toCharArray();
            }
        }
    }

    /**
     * Iterates through the grid to find cycles using DFS.
     */
    private void solve() {
        this.visited = new boolean[rows][cols];
        this.hasCycle = false;

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (!visited[r][c]) {
                    dfs(r, c, -1, -1);
                    if (hasCycle) {
                        return; // Optimization: Stop processing once a cycle is found
                    }
                }
            }
        }
    }

    /**
     * Performs Depth First Search to detect cycles.
     *
     * @param r Current row
     * @param c Current column
     * @param parentR Row of the parent node (to avoid traversing back up)
     * @param parentC Column of the parent node
     */
    private void dfs(int r, int c, int parentR, int parentC) {
        visited[r][c] = true;

        for (int i = 0; i < 4; i++) {
            int nextR = r + DX[i];
            int nextC = c + DY[i];

            // Check boundaries
            if (nextR >= 0 && nextR < rows && nextC >= 0 && nextC < cols) {
                // Skip the immediate parent node to avoid going back up the recursion tree
                if (nextR == parentR && nextC == parentC) {
                    continue;
                }

                // Check if the neighbor has the same character (valid edge)
                if (grid[r][c] == grid[nextR][nextC]) {
                    if (visited[nextR][nextC]) {
                        // Found a visited node that is not the parent -> Cycle detected
                        hasCycle = true;
                        return;
                    } else {
                        dfs(nextR, nextC, r, c);
                        if (hasCycle) return; // Propagate cycle found status up the recursion stack
                    }
                }
            }
        }
    }

    /**
     * Outputs the result to the console.
     */
    private void outputResult() {
        out.println(hasCycle ? "Yes" : "No");
        out.flush();
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

public class Solution {
    // Directions for moving up, down, left, right
    private static final int[][] DIRECTIONS = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner();
        int n = scanner.nextInt();
        int m = scanner.nextInt();
        char[][] grid = scanner.readCharMat(n, m);

        boolean hasCycle = detectCycle(grid);
        System.out.println(hasCycle ? "Yes" : "No");
    }

    /**
     * Detects if there is a cycle in the grid formed by adjacent cells with the same character.
     */
    private static boolean detectCycle(char[][] grid) {
        int n = grid.length;
        if (n == 0) return false;
        int m = grid[0].length;
        boolean[][] visited = new boolean[n][m];

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (!visited[i][j]) {
                    if (dfs(grid, visited, i, j, -1, -1)) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Depth-First Search to detect cycles.
     *
     * @param grid     The character grid
     * @param visited  Visited cell tracker
     * @param i        Current row
     * @param j        Current column
     * @param prevI    Previous row (to avoid going back to parent)
     * @param prevJ    Previous column
     * @return true if a cycle is detected, false otherwise
     */
    private static boolean dfs(char[][] grid, boolean[][] visited,
                               int i, int j, int prevI, int prevJ) {
        // Boundary check
        if (i < 0 || i >= grid.length || j < 0 || j >= grid[0].length) {
            return false;
        }

        // If the cell is already visited
        if (visited[i][j]) {
            // A cycle is detected if we encounter a visited cell that is not the immediate parent
            return i != prevI || j != prevJ;
        }

        // Mark the current cell as visited
        visited[i][j] = true;

        // Explore all four directions
        for (int[] dir : DIRECTIONS) {
            int ni = i + dir[0];
            int nj = j + dir[1];

            // Only traverse to adjacent cells with the same character
            if (grid[ni][nj] == grid[i][j]) {
                if (dfs(grid, visited, ni, nj, i, j)) {
                    return true;
                }
            }
        }
        return false;
    }

    /**
     * FastScanner for efficient input reading.
     */
    private static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) {
                        return null;
                    }
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            String s = next();
            return s == null ? 0 : Integer.parseInt(s);
        }

        char[][] readCharMat(int n, int m) {
            char[][] grid = new char[n][m];
            for (int i = 0; i < n; i++) {
                String row = next();
                for (int j = 0; j < m; j++) {
                    grid[i][j] = row.charAt(j);
                }
            }
            return grid;
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.Stack;

/**
 * Refactored version of the Grid Cycle Detector.
 * 
 * Improvements made:
 * 1. Class Name: Renamed 'C' to 'GridCycleDetector' for descriptive clarity.
 * 2. Data Structures: Replaced parallel 'Stack<Integer>' arrays with a custom 'Frame' class
 *    to hold coordinates and parent information, improving readability and type safety.
 * 3. Variable Naming: Renamed generic variables (n, m, a, x, y) to descriptive names 
 *    (rows, cols, grid, r, c) to reduce cognitive load.
 * 4. Input Handling: Used 'try-with-resources' for automatic resource management of BufferedReader.
 *    Used regex split("\\s+") for robust whitespace handling.
 * 5. Algorithm Logic: 
 *    - Standardized direction vectors into arrays (dRow, dCol).
 *    - Ensured boundary checks are performed before array access to prevent exceptions.
 *    - Marked the starting node of a DFS traversal as visited immediately to handle 
 *      disconnected components correctly.
 * 6. Separation of Concerns: Separated input/output logic from the core algorithm.
 */
public class GridCycleDetector {

    /**
     * Helper class to store grid coordinates and parent coordinates in the DFS stack.
     * This replaces the need for multiple parallel stacks.
     */
    private static class Frame {
        int r, c;       // Current cell coordinates (row, col)
        int pR, pC;     // Parent cell coordinates (row, col) to avoid backtracking

        public Frame(int r, int c, int pR, int pC) {
            this.r = r;
            this.c = c;
            this.pR = pR;
            this.pC = pC;
        }
    }

    public static void main(String[] args) throws IOException {
        // Use try-with-resources to ensure the BufferedReader is closed automatically
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {

            // Read dimensions: rows (n) and cols (m)
            // Using split("\\s+") handles multiple spaces between numbers robustly
            String[] dims = br.readLine().trim().split("\\s+");
            int rows = Integer.parseInt(dims[0]);
            int cols = Integer.parseInt(dims[1]);

            // Read the grid content
            char[][] grid = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                // readLine().trim() removes leading/trailing whitespace
                grid[i] = br.readLine().trim().toCharArray();
            }

            // Execute the cycle detection algorithm
            boolean hasCycle = solve(rows, cols, grid);

            // Output the result
            System.out.println(hasCycle ? "Yes" : "No");
        }
    }

    /**
     * Solves the problem using Iterative Depth First Search (DFS).
     * Detects if there is a cycle in the grid where connected cells have the same character.
     *
     * @param rows Number of rows in the grid
     * @param cols Number of columns in the grid
     * @param grid The 2D character array representing the grid
     * @return true if a cycle is found, false otherwise
     */
    private static boolean solve(int rows, int cols, char[][] grid) {
        boolean[][] visited = new boolean[rows][cols];
        Stack<Frame> stack = new Stack<>();

        // Direction vectors for moving Up, Down, Left, Right
        int[] dRow = {-1, 1, 0, 0};
        int[] dCol = {0, 0, -1, 1};

        // Iterate over every cell in the grid to handle disconnected components
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                // If the cell has already been visited in a previous traversal, skip it
                if (visited[r][c]) {
                    continue;
                }

                // Start a new DFS traversal from this unvisited node
                // Mark as visited immediately to handle the start node correctly
                visited[r][c] = true;
                // Parent is initialized to (-1, -1) as it is the root of this traversal
                stack.push(new Frame(r, c, -1, -1));

                while (!stack.isEmpty()) {
                    Frame current = stack.pop();

                    // Explore all 4 adjacent neighbors
                    for (int i = 0; i < 4; i++) {
                        int neighborR = current.r + dRow[i];
                        int neighborC = current.c + dCol[i];

                        // 1. Boundary Check
                        // Must be checked before array access to prevent IndexOutOfBoundsException
                        if (neighborR < 0 || neighborR >= rows || 
                            neighborC < 0 || neighborC >= cols) {
                            continue;
                        }

                        // 2. Character Match Check
                        // We only traverse edges between cells with the same character
                        if (grid[current.r][current.c] != grid[neighborR][neighborC]) {
                            continue;
                        }

                        // 3. Parent Check
                        // In an undirected graph DFS, we must not go back to the immediate parent
                        if (neighborR == current.pR && neighborC == current.pC) {
                            continue;
                        }

                        // 4. Cycle Detection
                        // If we encounter a visited node that is not the parent, a cycle exists
                        if (visited[neighborR][neighborC]) {
                            return true;
                        }

                        // 5. Mark neighbor as visited and push to stack
                        visited[neighborR][neighborC] = true;
                        stack.push(new Frame(neighborR, neighborC, current.r, current.c));
                    }
                }
            }
        }
        return false;
    }
}

import java.util.Scanner;

/**
 * Refactored Main class for cycle detection in a grid.
 * 
 * Improvements made:
 * 1. Encapsulation: Removed static global state; variables are now instance fields.
 * 2. Dynamic Sizing: Arrays are allocated based on input dimensions (n, m), removing magic numbers (500+5).
 * 3. Naming: Used descriptive names (grid, visited, directions) instead of abbreviations.
 * 4. Constants: Direction vectors are defined as a static final constant.
 * 5. Readability: Simplified boolean checks and loop structures.
 * 6. Logic: Ensured character matching is checked before cycle detection to avoid false positives.
 */
public class Main {

    // Directions for moving in the grid: Down, Up, Right, Left
    private static final int[][] DIRECTIONS = {
        {1, 0}, {-1, 0}, {0, 1}, {0, -1}
    };

    private int rows;
    private int cols;
    private char[][] grid;
    private boolean[][] visited;

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        // Check if input is available
        if (scanner.hasNextInt()) {
            int n = scanner.nextInt();
            int m = scanner.nextInt();

            // Allocate grid dynamically based on input dimensions
            char[][] maze = new char[n][m];

            // Read the grid rows
            for (int i = 0; i < n; i++) {
                if (scanner.hasNext()) {
                    String row = scanner.next();
                    // Ensure we do not go out of bounds if input string is shorter than m
                    for (int j = 0; j < m && j < row.length(); j++) {
                        maze[i][j] = row.charAt(j);
                    }
                }
            }

            // Create solver instance and run logic
            Main solver = new Main();
            boolean hasCycle = solver.hasCycle(n, m, maze);

            System.out.println(hasCycle ? "Yes" : "No");
        }

        scanner.close();
    }

    /**
     * Checks if the grid contains a cycle of identical characters.
     *
     * @param r Number of rows
     * @param c Number of columns
     * @param inputGrid The character grid to analyze
     * @return true if a cycle exists, false otherwise
     */
    public boolean hasCycle(int r, int c, char[][] inputGrid) {
        this.rows = r;
        this.cols = c;
        this.grid = inputGrid;
        this.visited = new boolean[r][c];

        // Iterate through every cell to handle disconnected components
        for (int i = 0; i < r; i++) {
            for (int j = 0; j < c; j++) {
                // If the cell hasn't been visited, start a DFS traversal
                if (!visited[i][j]) {
                    // Start DFS. Parent coordinates are (-1, -1) to indicate no parent.
                    if (dfs(i, j, -1, -1, grid[i][j])) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Performs Depth First Search (DFS) to detect cycles.
     *
     * @param x Current row index
     * @param y Current column index
     * @param parentX Row index of the parent node (prevents immediate backtracking)
     * @param parentY Column index of the parent node
     * @param targetChar The character sequence being tracked
     * @return true if a cycle is detected, false otherwise
     */
    private boolean dfs(int x, int y, int parentX, int parentY, char targetChar) {
        visited[x][y] = true;

        for (int[] direction : DIRECTIONS) {
            int nextX = x + direction[0];
            int nextY = y + direction[1];

            // Do not traverse back to the immediate parent
            if (nextX == parentX && nextY == parentY) {
                continue;
            }

            // Check boundaries
            if (nextX >= 0 && nextX < rows && nextY >= 0 && nextY < cols) {
                // Only process neighbors with the same character
                if (grid[nextX][nextY] == targetChar) {
                    // If we encounter a visited node (that isn't the parent), a cycle exists
                    if (visited[nextX][nextY]) {
                        return true;
                    }
                    // If not visited, recurse
                    if (dfs(nextX, nextY, x, y, targetChar)) {
                        return true;
                    }
                }
            }
        }
        return false;
    }
}

import java.io.*;
import java.util.*;

public class Main {
    // Direction vectors for moving up, down, left, right
    private static final int[] DR = {-1, 1, 0, 0};
    private static final int[] DC = {0, 0, -1, 1};

    public static void main(String[] args) throws IOException {
        // Use try-with-resources for automatic resource management
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
             PrintWriter pw = new PrintWriter(new BufferedOutputStream(System.out))) {

            String line = br.readLine();
            if (line == null || line.trim().isEmpty()) {
                return;
            }

            String[] dimensions = line.trim().split("\\s+");
            int rows = Integer.parseInt(dimensions[0]);
            int cols = Integer.parseInt(dimensions[1]);

            char[][] grid = new char[rows][cols];
            Set<Character> uniqueCharacters = new HashSet<>();

            // Read grid and collect unique characters
            for (int i = 0; i < rows; i++) {
                String rowLine = br.readLine();
                if (rowLine != null) {
                    rowLine = rowLine.trim();
                    grid[i] = rowLine.toCharArray();
                    for (char c : rowLine.toCharArray()) {
                        uniqueCharacters.add(c);
                    }
                }
            }

            boolean cycleFound = false;
            // Check each unique character for cycles
            for (char ch : uniqueCharacters) {
                if (hasCycle(ch, grid)) {
                    cycleFound = true;
                    break;
                }
            }

            pw.println(cycleFound ? "Yes" : "No");
            pw.flush();
        }
    }

    /**
     * Checks if there is a cycle in the grid formed by the specified character.
     */
    private static boolean hasCycle(char targetChar, char[][] grid) {
        int n = grid.length;
        int m = grid[0].length;
        boolean[][] visited = new boolean[n][m];

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == targetChar && !visited[i][j]) {
                    if (dfs(i, j, -1, -1, visited, grid)) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Performs DFS to detect cycles in an undirected graph represented by the grid.
     *
     * @param r Current row
     * @param c Current column
     * @param pr Parent row
     * @param pc Parent column
     * @param visited Visited status of cells
     * @param grid 2D character array
     * @return true if a cycle is detected, false otherwise
     */
    private static boolean dfs(int r, int c, int pr, int pc, boolean[][] visited, char[][] grid) {
        visited[r][c] = true;

        for (int k = 0; k < 4; k++) {
            int nr = r + DR[k];
            int nc = c + DC[k];

            // Check bounds and if neighbor has the same character
            if (nr >= 0 && nr < grid.length && nc >= 0 && nc < grid[0].length &&
                grid[nr][nc] == grid[r][c]) {

                if (!visited[nr][nc]) {
                    if (dfs(nr, nc, r, c, visited, grid)) {
                        return true;
                    }
                } else if (nr != pr || nc != pc) {
                    // Found a visited node that is not the immediate parent -> cycle
                    return true;
                }
            }
        }
        return false;
    }
}

import java.io.*;
import java.util.*;

/**
 * Detects if there exists a cycle of identical characters in a 2D grid.
 * Uses DFS with back-edge detection for O(V+E) complexity.
 */
public class B_510 implements Runnable {

    // Direction vectors: Up, Down, Left, Right
    private static final int[] DR = {-1, 1, 0, 0};
    private static final int[] DC = {0, 0, -1, 1};
    private static final int DEFAULT_STACK_SIZE = 1 << 26;

    private int rows, cols;
    private char[][] grid;
    private boolean[][] visited;
    private boolean hasCycle;

    @Override
    public void run() {
        InputReader scan = new InputReader(System.in);
        PrintWriter out = new PrintWriter(System.out);
        solve(scan, out);
        out.flush();
        out.close();
    }

    private void solve(InputReader scan, PrintWriter out) {
        rows = scan.nextInt();
        cols = scan.nextInt();
        grid = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            grid[i] = scan.next().toCharArray();
        }

        visited = new boolean[rows][cols];
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                // Only start DFS from unvisited cells to process each connected component once
                if (!visited[i][j]) {
                    hasCycle = false;
                    dfs(i, j, -1, -1, grid[i][j]);
                    if (hasCycle) {
                        out.println("Yes");
                        return;
                    }
                }
            }
        }
        out.println("No");
    }

    /**
     * Performs DFS to detect cycles in the grid.
     * @param r Current row
     * @param c Current column
     * @param pr Previous row (to prevent going back)
     * @param pc Previous column (to prevent going back)
     * @param target Character value to match
     */
    private void dfs(int r, int c, int pr, int pc, char target) {
        visited[r][c] = true;

        for (int dir = 0; dir < 4; dir++) {
            int nr = r + DR[dir];
            int nc = c + DC[dir];

            if (isValidMove(nr, nc, pr, pc, target)) {
                if (visited[nr][nc]) {
                    // Found a visited node that is not the parent -> cycle detected
                    hasCycle = true;
                    return;
                }
                dfs(nr, nc, r, c, target);
                if (hasCycle) return; // Early exit on cycle detection
            }
        }
    }

    /**
     * Checks if a move to (r, c) is valid.
     */
    private boolean isValidMove(int r, int c, int pr, int pc, char target) {
        return r >= 0 && r < rows && c >= 0 && c < cols
               && !(r == pr && c == pc)
               && grid[r][c] == target;
    }

    public static void main(String[] args) {
        // Run in a separate thread with increased stack size to prevent StackOverflowError on deep recursion
        new Thread(null, new B_510(), "Main", DEFAULT_STACK_SIZE).start();
    }

    /**
     * Fast I/O helper for competitive programming.
     */
    static class InputReader {
        private InputStream stream;
        private byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;
        private SpaceCharFilter filter;
        private BufferedReader br = new BufferedReader(new InputStreamReader(System.in));

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        public int read() {
            if (numChars == -1) {
                throw new InputMismatchException();
            }

            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }

                if (numChars <= 0) {
                    return -1;
                }
            }
            return buf[curChar++];
        }

        public String nextLine() {
            String str = "";
            try {
                str = br.readLine();
            } catch (IOException e) {
                e.printStackTrace();
            }
            return str;
        }

        public int nextInt() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }

            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }

            int res = 0;
            do {
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                res *= 10;
                res += c - '0';
                c = read();
            } while (!isSpaceChar(c));

            return res * sgn;
        }

        public long nextLong() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            long res = 0;

            do {
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                res *= 10;
                res += c - '0';
                c = read();
            } while (!isSpaceChar(c));

            return res * sgn;
        }

        public double nextDouble() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            double res = 0;
            while (!isSpaceChar(c) && c != '.') {
                if (c == 'e' || c == 'E') {
                    return res * Math.pow(10, nextInt());
                }
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                res *= 10;
                res += c - '0';
                c = read();
            }
            if (c == '.') {
                c = read();
                double m = 1;
                while (!isSpaceChar(c)) {
                    if (c == 'e' || c == 'E') {
                        return res * Math.pow(10, nextInt());
                    }
                    if (c < '0' || c > '9') {
                        throw new InputMismatchException();
                    }
                    m /= 10;
                    res += (c - '0') * m;
                    c = read();
                }
            }
            return res * sgn;
        }

        public String readString() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            StringBuilder res = new StringBuilder();
            do {
                res.appendCodePoint(c);
                c = read();
            } while (!isSpaceChar(c));

            return res.toString();
        }

        public boolean isSpaceChar(int c) {
            if (filter != null) {
                return filter.isSpaceChar(c);
            }
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        public String next() {
            return readString();
        }

        public long[] nla(int n) { 
            long[] ar = new long[n];
            for (int i = 0; i < n; i++) {
                ar[i] = this.nextLong();
            }
            return ar;
        }

        public int[] nia(int n) {
            int[] ar = new int[n];
            for (int i = 0; i < n; i++) {
                ar[i] = this.nextInt();
            }
            return ar;
        }

        public interface SpaceCharFilter {
            public boolean isSpaceChar(int ch);
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.math.BigInteger;
import java.util.StringTokenizer;

/**
 * Solves a grid cycle detection problem (e.g., Codeforces 290B).
 * Determines if there exists a cycle of length >= 3 formed by adjacent cells
 * containing the same character.
 * 
 * Algorithm:
 * - Uses DFS to traverse connected components of identical characters.
 * - Maintains a recursion stack (`inPath`) to detect back-edges (cycles).
 * - Uses a `depth` array to calculate cycle length when a back-edge is found.
 * - Uses a `processed` array to avoid re-traversing fully explored components.
 */
public class CycleInGrid {

    // Direction vectors for moving up, down, left, right
    private static final int[] DX = {-1, 1, 0, 0};
    private static final int[] DY = {0, 0, 1, -1};

    private FastScanner in;
    private PrintWriter out;

    /**
     * Reads input and orchestrates the cycle detection process.
     */
    public void solve() throws IOException {
        int n = in.nextInt();
        int m = in.nextInt();

        // Efficiently read grid rows directly into character arrays
        char[][] grid = new char[n][];
        for (int i = 0; i < n; i++) {
            grid[i] = in.next().toCharArray();
        }

        // inPath: Tracks nodes currently in the DFS recursion stack
        // processed: Tracks nodes that have been fully explored in previous DFS runs
        // depth: Stores the recursion depth of each node to calculate cycle length
        boolean[][] inPath = new boolean[n][m];
        boolean[][] processed = new boolean[n][m];
        int[][] depth = new int[n][m];

        // Iterate over each cell to start DFS from unprocessed nodes
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (processed[i][j]) {
                    continue;
                }

                depth[i][j] = 1;
                if (hasCycle(grid, processed, inPath, 1, i, j, grid[i][j], depth)) {
                    out.println("Yes");
                    return;
                }
            }
        }

        out.println("No");
    }

    /**
     * Performs DFS to detect a cycle of length >= 3.
     *
     * @param grid          The input character grid
     * @param processed     Marks nodes that have been completely explored
     * @param inPath        Marks nodes currently in the active recursion stack
     * @param currentDepth  Depth of the current node in the DFS tree
     * @param x             Current row index
     * @param y             Current column index
     * @param targetChar    Character value that must match for traversal
     * @param depth         Array storing the depth at which each node was first visited
     * @return true if a valid cycle is found, false otherwise
     */
    private boolean hasCycle(char[][] grid, boolean[][] processed, boolean[][] inPath,
                             int currentDepth, int x, int y, char targetChar, int[][] depth) {
        inPath[x][y] = true;
        processed[x][y] = true;
        depth[x][y] = currentDepth;

        for (int i = 0; i < 4; i++) {
            int newX = x + DX[i];
            int newY = y + DY[i];

            // Boundary and character match validation
            if (newX < 0 || newY < 0 || newX >= grid.length || newY >= grid[0].length ||
                grid[newX][newY] != targetChar) {
                continue;
            }

            // If neighbor is in the current path, we found a back-edge (cycle)
            if (inPath[newX][newY]) {
                // Cycle length = current depth - neighbor's depth
                if (Math.abs(currentDepth - depth[newX][newY]) >= 3) {
                    return true;
                }
            } 
            // If neighbor hasn't been processed yet, continue DFS
            else if (!processed[newX][newY]) {
                if (hasCycle(grid, processed, inPath, currentDepth + 1, newX, newY, targetChar, depth)) {
                    return true;
                }
            }
        }

        // Backtrack: remove current node from the recursion stack
        inPath[x][y] = false;
        return false;
    }

    /**
     * Entry point for I/O setup and execution.
     */
    public void run() {
        in = new FastScanner();
        out = new PrintWriter(System.out);
        try {
            solve();
        } catch (IOException e) {
            e.printStackTrace();
        } finally {
            out.flush();
            out.close();
        }
    }

    /**
     * Optimized scanner for fast competitive programming I/O.
     */
    private static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        public String next() {
            while (st == null || !st.hasMoreTokens()) {
