public class CF510B {

    // Direction vectors for grid traversal (Up, Down, Left, Right)
    private static final int[] DX = {-1, 1, 0, 0};
    private static final int[] DY = {0, 0, -1, 1};

    private final FastScanner scanner;
    private final PrintWriter out;

    private int n, m;
    private char[][] grid;
    private boolean[][] visited;

    public CF510B(FastScanner scanner, PrintWriter out) {
        this.scanner = scanner;
        this.out = out;
    }

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner(System.in);
        // BufferedOutputStream improves output performance for large answers
        PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out));
        try {
            new CF510B(scanner, out).solve();
        } finally {
            out.flush();
        }
    }

    /**
     * Reads input, initializes state, runs cycle detection, and prints the result.
     */
    public void solve() {
        n = scanner.nextInt();
        m = scanner.nextInt();

        grid = new char[n][m];
        visited = new boolean[n][m];

        for (int i = 0; i < n; i++) {
            grid[i] = scanner.next().toCharArray();
        }

        boolean hasCycle = false;
        outerLoop:
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (!visited[i][j]) {
                    if (dfs(i, j, -1, -1, grid[i][j])) {
                        hasCycle = true;
                        break outerLoop;
                    }
                }
            }
        }

        out.println(hasCycle ? "Yes" : "No");
    }

    /**
     * Performs DFS to detect cycles in the grid graph.
     * 
     * @param x Current row
     * @param y Current column
     * @param px Parent row (to avoid immediate backtracking)
     * @param py Parent column
     * @param targetChar Character we are traversing
     * @return true if a cycle is found, false otherwise
     */
    private boolean dfs(int x, int y, int px, int py, char targetChar) {
        visited[x][y] = true;

        for (int i = 0; i < 4; i++) {
            int nx = x + DX[i];
            int ny = y + DY[i];

            // Skip the node we came from
            if (nx == px && ny == py) continue;
            // Skip out-of-bounds coordinates
            if (nx < 0 || nx >= n || ny < 0 || ny >= m) continue;
            // Skip cells with different characters
            if (grid[nx][ny] != targetChar) continue;
            // If we encounter an already visited node in the current component, a cycle exists
            if (visited[nx][ny]) return true;
            // Recurse; propagate cycle detection up the call stack
            if (dfs(nx, ny, x, y, targetChar)) return true;
        }

        return false;
    }

    /**
     * Lightweight Fast I/O helper for competitive programming.
     */
    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        public String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input", e);
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            String s = next();
            return s == null ? 0 : Integer.parseInt(s);
        }
    }
}

import java.util.Scanner;

/**
 * Refactored Grid Cycle Finder.
 * 
 * This class solves the problem of detecting if there is a cycle of identical 
 * characters in a 2D grid. It uses Depth First Search (DFS) to traverse 
 * connected components and detect back-edges, which indicate cycles.
 * 
 * Improvements made:
 * 1. Encapsulation: Removed global static variables in favor of instance fields.
 * 2. Naming: Used descriptive names (e.g., rows, cols, grid, hasCycle).
 * 3. Efficiency: Optimized the algorithm to run in O(N*M) time by avoiding 
 *    resetting the visited array for every starting cell.
 * 4. Readability: Removed the custom object wrapper for DFS state, using 
 *    simple parameters instead.
 * 5. Robustness: Added input validation and cleaner I/O handling.
 */
public class GridCycleFinder {

    // Grid dimensions
    private int rows;
    private int cols;

    // The character grid
    private char[][] grid;

    // Tracks visited cells to prevent infinite loops and redundant processing
    private boolean[][] visited;

    // Direction vectors for moving Up, Down, Left, Right
    private static final int[] DR = {-1, 1, 0, 0};
    private static final int[] DC = {0, 0, -1, 1};

    public static void main(String[] args) {
        GridCycleFinder solver = new GridCycleFinder();
        solver.run();
    }

    public void run() {
        Scanner scanner = new Scanner(System.in);

        // Read dimensions safely
        if (!scanner.hasNextInt()) {
            return;
        }
        this.rows = scanner.nextInt();
        this.cols = scanner.nextInt();
        scanner.nextLine(); // Consume the newline character after integers

        // Initialize grid and read input
        this.grid = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            String line = scanner.nextLine().trim();
            // Fill the row, handling potential input length mismatches gracefully
            for (int j = 0; j < cols; j++) {
                if (j < line.length()) {
                    grid[i][j] = line.charAt(j);
                } else {
                    grid[i][j] = ' '; // Default filler if input is short
                }
            }
        }

        this.visited = new boolean[rows][cols];
        boolean cycleDetected = false;

        // Iterate through every cell to ensure all connected components are checked
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                // If the cell hasn't been visited, start a DFS from here
                if (!visited[r][c]) {
                    // Pass -1, -1 as parent coordinates to indicate no parent
                    if (hasCycle(r, c, -1, -1)) {
                        cycleDetected = true;
                        break;
                    }
                }
            }
            if (cycleDetected) {
                break;
            }
        }

        System.out.println(cycleDetected ? "Yes" : "No");
        scanner.close();
    }

    /**
     * Performs a Depth First Search to detect if a cycle exists in the 
     * connected component of identical characters starting at (r, c).
     *
     * @param r         Current row index
     * @param c         Current column index
     * @param parentR   Row index of the parent node (to avoid going back up the same edge)
     * @param parentC   Column index of the parent node
     * @return true if a cycle is detected, false otherwise
     */
    private boolean hasCycle(int r, int c, int parentR, int parentC) {
        visited[r][c] = true;
        char currentChar = grid[r][c];

        for (int i = 0; i < 4; i++) {
            int nextR = r + DR[i];
            int nextC = c + DC[i];

            // 1. Check boundaries
            if (nextR < 0 || nextR >= rows || nextC < 0 || nextC >= cols) {
                continue;
            }

            // 2. Check if the neighbor has the same character
            if (grid[nextR][nextC] != currentChar) {
                continue;
            }

            // 3. If the neighbor is the parent we came from, skip it
            // This prevents the algorithm from immediately backtracking
            if (nextR == parentR && nextC == parentC) {
                continue;
            }

            // 4. Cycle Detection
            // If we encounter a neighbor that is already visited, it means we 
            // have found a back-edge to an ancestor in the current DFS tree.
            // Since it's not the parent, it must be a cycle.
            if (visited[nextR][nextC]) {
                return true;
            }

            // 5. Recurse into unvisited neighbors
            if (hasCycle(nextR, nextC, r, c)) {
                return true;
            }
        }
        return false;
    }
}

import java.io.*;
