/**
 * Detects cycles in a 2D character grid where adjacent cells with the same character form a cycle.
 * Refactored for improved maintainability, encapsulation, and robust I/O handling.
 */
public class CycleDetector {

    private static final int[][] DIRECTIONS = {
        {1, 0}, {0, 1}, {-1, 0}, {0, -1}
    };

    private int rows;
    private int cols;
    private char[][] grid;
    private boolean[][] visited;

    public static void main(String[] args) throws IOException {
        // Use try-with-resources for automatic and safe resource cleanup
        try (FastScanner scanner = new FastScanner(System.in);
             PrintWriter out = new PrintWriter(new OutputStreamWriter(System.out))) {

            CycleDetector detector = new CycleDetector();
            detector.solve(scanner, out);
        }
    }

    /**
     * Orchestrates input reading, cycle detection, and output formatting.
     */
    public void solve(FastScanner scanner, PrintWriter out) throws IOException {
        rows = scanner.nextInt();
        cols = scanner.nextInt();

        grid = new char[rows][cols];
        visited = new boolean[rows][cols];

        for (int i = 0; i < rows; i++) {
            String line = scanner.readLine();
            if (line == null) {
                throw new IOException("Unexpected end of input while reading grid row " + i);
            }
            grid[i] = line.trim().toCharArray();
        }

        boolean foundCycle = false;
        outerLoop:
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (!visited[r][c]) {
                    if (hasCycle(r, c, -1, -1)) {
                        foundCycle = true;
                        break outerLoop;
                    }
                }
            }
        }

        out.println(foundCycle ? "Yes" : "No");
    }

    /**
     * Performs DFS to detect a cycle in the grid.
     *
     * @param r         Current row
     * @param c         Current column
     * @param parentR   Row of the parent cell (to avoid immediate backtracking)
     * @param parentC   Column of the parent cell
     * @return true if a cycle is detected, false otherwise
     */
    private boolean hasCycle(int r, int c, int parentR, int parentC) {
        visited[r][c] = true;

        for (int[] dir : DIRECTIONS) {
            int nr = r + dir[0];
            int nc = c + dir[1];

            if (isValid(nr, nc) && !(nr == parentR && nc == parentC)) {
                // If neighbor is already visited, we found a cycle
                if (visited[nr][nc]) {
                    return true;
                }
                // Continue DFS only if the character matches
                if (grid[r][c] == grid[nr][nc]) {
                    if (hasCycle(nr, nc, r, c)) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    private boolean isValid(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /**
     * Fast I/O helper class optimized for performance-critical applications.
     * Implements AutoCloseable for safe resource management.
     */
    static class FastScanner implements AutoCloseable {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastScanner(InputStream stream) {
            this.reader = new BufferedReader(new InputStreamReader(stream));
            this.tokenizer = new StringTokenizer("");
        }

        public String next() throws IOException {
            while (!tokenizer.hasMoreTokens()) {
                String line = reader.readLine();
                if (line == null) {
                    return null;
                }
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            String token = next();
            if (token == null) {
                throw new IOException("Unexpected end of input");
            }
            return Integer.parseInt(token);
        }

        public String readLine() throws IOException {
            return reader.readLine();
        }

        @Override
        public void close() throws IOException {
            reader.close();
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;

public class Foxdots {

    public static void main(String[] args) throws IOException {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));

        String line = reader.readLine();
        if (line == null || line.trim().isEmpty()) {
            return;
        }

        String[] dimensions = line.trim().split("\\s+");
        if (dimensions.length < 2) {
            throw new IllegalArgumentException("Input must contain rows and columns.");
        }

        int rows = Integer.parseInt(dimensions[0]);
        int cols = Integer.parseInt(dimensions[1]);

        char[][] grid = new char[rows][];
        for (int i = 0; i < rows; i++) {
            String rowLine = reader.readLine();
            grid[i] = (rowLine != null) ? rowLine.trim().toCharArray() : new char[0];
        }

        UnionFind uf = new UnionFind(rows * cols);
        boolean cycleDetected = false;

        for (int r = 0; r < rows && !cycleDetected; r++) {
            for (int c = 0; c < cols && !cycleDetected; c++) {
                int currentIdx = r * cols + c;
                char currentChar = grid[r][c];

                // Check right neighbor
                if (c + 1 < cols) {
                    int rightIdx = currentIdx + 1;
                    if (currentChar == grid[r][c + 1]) {
                        if (!uf.union(currentIdx, rightIdx)) {
                            cycleDetected = true;
                        }
                    }
                }

                // Check down neighbor
                if (r + 1 < rows) {
                    int downIdx = currentIdx + cols;
                    if (currentChar == grid[r + 1][c]) {
                        if (!uf.union(currentIdx, downIdx)) {
                            cycleDetected = true;
                        }
                    }
                }
            }
        }

        System.out.println(cycleDetected ? "Yes" : "No");
    }

    /**
     * Union-Find (Disjoint Set Union) data structure with path compression and union by rank.
     * Efficiently tracks connected components and detects cycles among nodes with matching labels.
     */
    static class UnionFind {
        private final int[] parent;
        private final int[] rank;

        public UnionFind(int size) {
            parent = new int[size];
            rank = new int[size];
            for (int i = 0; i < size; i++) {
                parent[i] = i;
                rank[i] = 0;
            }
        }

        /**
         * Finds the root representative of the set containing element x with path compression.
         */
        public int find(int x) {
            int root = x;
            while (root != parent[root]) {
                root = parent[root];
            }
            // Path compression step
            while (x != root) {
                int next = parent[x];
                parent[x] = root;
                x = next;
            }
            return root;
        }

        /**
         * Unites the sets containing elements x and y.
         * @return false if x and y were already in the same set (cycle detected), true otherwise.
         */
        public boolean union(int x, int y) {
            int rootX = find(x);
            int rootY = find(y);

            if (rootX == rootY) {
                return false;
            }

            // Union by rank to keep tree height logarithmic
            if (rank[rootX] < rank[rootY]) {
                parent[rootX] = rootY;
            } else if (rank[rootX] > rank[rootY]) {
                parent[rootY] = rootX;
            } else {
                parent[rootY] = rootX;
                rank[rootX]++;
            }
            return true;
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

public class Main {
    private static final int CYCLE_LENGTH = 4;
    // Direction vectors: down, up, right, left
    private static final int[] DR = {1, -1, 0, 0};
    private static final int[] DC = {0, 0, 1, -1};

    public static void main(String[] args) throws IOException {
        FastReader reader = new FastReader();
        int rows = reader.nextInt();
        int cols = reader.nextInt();

        // A cycle of length 4 requires at least a 2x2 grid
        if (rows < 2 || cols < 2) {
            System.out.println("No");
            return;
        }

        char[][] grid = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            // Use next() instead of nextLine() to safely skip whitespace/newlines
            String line = reader.next();
            for (int j = 0; j < cols; j++) {
                grid[i][j] = line.charAt(j);
            }
        }

        boolean found = false;
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                // Allocate visited array per starting cell to avoid state leakage
                boolean[][] visited = new boolean[rows][cols];
                if (dfs(i, j, i, j, 1, grid, visited, rows, cols, grid[i][j])) {
                    found = true;
                    break;
                }
            }
            if (found) {
                break;
            }
        }

        System.out.println(found ? "Yes" : "No");
    }

    /**
     * Performs DFS to find a cycle of the target character starting and ending at (startRow, startCol).
     *
     * @param row       Current row
     * @param col       Current column
     * @param startRow  Starting row of the path
     * @param startCol  Starting column of the path
     * @param steps     Number of steps taken so far
     * @param grid      The character grid
     * @param visited   Visited tracking for the current DFS traversal
     * @param rows      Grid height
     * @param cols      Grid width
     * @param targetChar Character to match for the entire path
     * @return true if a valid cycle is found, false otherwise
     */
    private static boolean dfs(int row, int col, int startRow, int startCol, int steps,
                               char[][] grid, boolean[][] visited, int rows, int cols, char targetChar) {
        // Cycle completed successfully
        if (steps >= CYCLE_LENGTH && row == startRow && col == startCol) {
            return true;
        }

        // Already visited in the current path
        if (visited[row][col]) {
            return false;
        }

        visited[row][col] = true;

        // Explore all 4 adjacent cells
        for (int k = 0; k < 4; k++) {
            int nextRow = row + DR[k];
            int nextCol = col + DC[k];

            if (nextRow >= 0 && nextRow < rows && nextCol >= 0 && nextCol < cols) {
                if (grid[nextRow][nextCol] == targetChar) {
                    if (dfs(nextRow, nextCol, startRow, startCol, steps + 1, grid, visited, rows, cols, targetChar)) {
                        return true;
                    }
                }
            }
        }

        return false;
    }

    /**
     * Fast input reader for competitive programming / high-throughput scenarios.
     */
    static class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) {
                        return null;
                    }
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input stream", e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            String token = next();
            return token == null ? 0 : Integer.parseInt(token);
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Solves the problem of detecting a cycle of length at least 4
 * in a grid where all cells in the cycle share the same character.
 */
public class CycleFinder {
    private static final int[][] DIRECTIONS = {
        {0, 1}, {1, 0}, {0, -1}, {-1, 0}
    };
    private static final int MIN_CYCLE_LENGTH = 4;

    private final int rows;
    private final int cols;
    private final char[][] grid;
    private final int[][] visited;
    private final boolean[][] explored;

    /**
     * Constructs a CycleFinder with the given grid dimensions and data.
     *
     * @param rows  number of rows in the grid
     * @param cols  number of columns in the grid
     * @param grid  2D character array representing the grid
     */
    public CycleFinder(int rows, int cols, char[][] grid) {
        this.rows = rows;
        this.cols = cols;
        this.grid = grid;
        this.visited = new int[rows][cols];
        this.explored = new boolean[rows][cols];
    }

    /**
     * Initiates the cycle detection process and prints the result.
     *
     * @param out the output writer
     * @return true if a valid cycle was found, false otherwise
     */
    public boolean solve(PrintWriter out) {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (!explored[r][c]) {
                    if (hasCycle(r, c, -1, -1, 1, grid[r][c])) {
                        out.println("Yes");
                        return true;
                    }
                }
            }
        }
        out.println("No");
        return false;
    }

    /**
     * Performs DFS to detect a cycle of the target character.
     *
     * @param r            current row
     * @param c            current column
     * @param prevR        previous row (to avoid traversing back)
     * @param prevC        previous column (to avoid traversing back)
     * @param depth        current depth in the DFS traversal
     * @param targetChar   the character we are searching for
     * @return true if a valid cycle is found, false otherwise
     */
    private boolean hasCycle(int r, int c, int prevR, int prevC, int depth, char targetChar) {
        if (grid[r][c] != targetChar) {
            return false;
        }
        explored[r][c] = true;

        if (visited[r][c] > 0) {
            return (depth - visited[r][c]) >= MIN_CYCLE_LENGTH;
        }

        visited[r][c] = depth;
        for (int[] dir : DIRECTIONS) {
            int nr = r + dir[0];
            int nc = c + dir[1];

            if (nr == prevR && nc == prevC) {
                continue;
            }
            if (isOutOfBounds(nr, nc)) {
                continue;
            }

            if (hasCycle(nr, nc, r, c, depth + 1, targetChar)) {
                return true;
            }
        }

        visited[r][c] = 0; // Backtrack: unmark depth to allow other paths
        return false;
    }

    private boolean isOutOfBounds(int r, int c) {
        return r < 0 || r >= rows || c < 0 || c >= cols;
    }

    public static void main(String[] args) throws IOException {
        FastScanner scanner = new FastScanner(System.in);
        try (PrintWriter out = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)))) {
            int rows = scanner.nextInt();
            int cols = scanner.nextInt();
            char[][] grid = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                grid[i] = scanner.next().toCharArray();
            }

            CycleFinder finder = new CycleFinder(rows, cols, grid);
            finder.solve(out);
        }
    }

    /**
     * Helper class for fast and robust input reading.
     */
    private static class FastScanner {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastScanner(InputStream stream) {
            this.reader = new BufferedReader(new InputStreamReader(stream));
            this.tokenizer = new StringTokenizer("");
        }

        public String next() throws IOException {
            while (!tokenizer.hasMoreTokens()) {
                String line = reader.readLine();
                if (line == null) {
                    throw new EOFException("Unexpected end of input");
                }
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}

