                for (int i = 0; i < n; i++) {
                    String row = in.next();
                    grid[i] = row.toCharArray();
                }

                // Initialize visited array
                visited = new boolean[n][m];
                boolean cycleFound = false;

                // Iterate through each cell to handle disconnected components
                searchLoop:
                for (int i = 0; i < n; i++) {
                    for (int j = 0; j < m; j++) {
                        // If cell is not visited, start DFS
                        if (!visited[i][j]) {
                            if (hasCycle(i, j, -1, -1)) {
                                cycleFound = true;
                                break searchLoop;
                            }
                        }
                    }
                }

                // Output result
                out.println(cycleFound ? "Yes" : "No");

            } catch (Exception e) {
                // In a robust application, handle exceptions. 
                // For CP, we might just let it crash or ignore.
                e.printStackTrace();
            }
        }

        /**
         * Performs DFS to detect a cycle in the grid.
         * 
         * @param r       Current row index
         * @param c       Current column index
         * @param parentR Parent row index (to avoid backtracking immediately)
         * @param parentC Parent column index
         * @return true if a cycle is detected, false otherwise
         */
        private boolean hasCycle(int r, int c, int parentR, int parentC) {
            // Mark current node as visited
            visited[r][c] = true;
            char currentChar = grid[r][c];

            // Explore neighbors
            for (int k = 0; k < 4; k++) {
                int nextR = r + DR[k];
                int nextC = c + DC[k];

                // Check boundaries
                if (nextR < 0 || nextC < 0 || nextR >= n || nextC >= m) {
                    continue;
                }

                // Skip the parent node to prevent trivial backtracking
                if (nextR == parentR && nextC == parentC) {
                    continue;
                }

                // Edges only exist between identical characters
                if (grid[nextR][nextC] != currentChar) {
                    continue;
                }

                // If the neighbor is already visited, we found a cycle
                // (Since we skip the parent, any other visited node implies a cycle)
                if (visited[nextR][nextC]) {
                    return true;
                }

                // Recursively check the neighbor
                if (hasCycle(nextR, nextC, r, c)) {
                    return true;
                }
            }

            // Note: We do NOT unmark visited[r][c] here.
            // In an undirected graph, once a node is visited, it is part of a component.
            // If that component had a cycle, we would have returned true already.
            // Marking it permanently avoids redundant processing and improves performance.
            return false;
        }
    }

    /**
     * FastScanner class for efficient input reading.
     */
    static class FastScanner {
        public BufferedReader reader;
        public StringTokenizer tokenizer;

        public FastScanner(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            String s = next();
            if (s == null) throw new RuntimeException("End of stream");
            return Integer.parseInt(s);
        }
    }
}

import java.io.*;
import java.util.*;

public class Main {
    // Direction vectors for moving up, down, left, right
    private static final int[] DR = {-1, 1, 0, 0};
    private static final int[] DC = {0, 0, -1, 1};

    private final int rows;
    private final int cols;
    private final char[][] grid;
    private final PrintWriter out;

    public Main(int rows, int cols, char[][] grid) {
        this.rows = rows;
        this.cols = cols;
        this.grid = grid;
        this.out = new PrintWriter(System.out);
    }

    /**
     * Entry point for the cycle detection algorithm.
     * Iterates over each cell, treating it as a potential starting point
     * for a cycle of identical characters with length >= 4.
     */
    public void solve() {
        boolean[][] visited = new boolean[rows][cols];

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                // Reset visited state for each new starting cell
                resetVisited(visited);

                if (hasCycleOfLengthAtLeast4(r, c, grid[r][c], r, c, 1, visited)) {
                    out.println("Yes");
                    out.flush();
                    return;
                }
            }
        }

        out.println("No");
        out.flush();
    }

    /**
     * Resets the visited tracking array to all false.
     */
    private void resetVisited(boolean[][] visited) {
        for (int i = 0; i < rows; i++) {
            Arrays.fill(visited[i], false);
        }
    }

    /**
     * Depth-First Search to detect a cycle of the target character.
     * Returns true if a cycle of length >= 4 is found starting from (startR, startC).
     */
    private boolean hasCycleOfLengthAtLeast4(int r, int c, char targetChar, 
                                             int startR, int startC, int count, 
                                             boolean[][] visited) {
        // Boundary check
        if (r < 0 || r >= rows || c < 0 || c >= cols) {
            return false;
        }
        // Character match check
        if (grid[r][c] != targetChar) {
            return false;
        }
        // Cycle detection: returned to start with sufficient path length
        if (r == startR && c == startC && visited[r][c] && count >= 4) {
            return true;
        }
        // Already visited in current traversal path
        if (visited[r][c]) {
            return false;
        }

        visited[r][c] = true;

        // Explore all 4 adjacent neighbors
        for (int i = 0; i < 4; i++) {
            if (hasCycleOfLengthAtLeast4(r + DR[i], c + DC[i], targetChar, 
                                         startR, startC, count + 1, visited)) {
                return true;
            }
        }
        return false;
    }

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner(System.in);

        // Read grid dimensions
        int rows = scanner.nextInt();
        int cols = scanner.nextInt();

        // Read grid content
        char[][] grid = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            grid[i] = scanner.next().toCharArray();
        }

        // Execute solver
        new Main(rows, cols, grid).solve();
    }

    /**
     * Fast I/O helper class. Replaces the custom Reader with a standard,
     * robust implementation using BufferedReader and StringTokenizer.
     */
    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        public String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) {
                        return null;
                    }
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input", e);
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            String token = next();
            if (token == null) {
                throw new RuntimeException("Unexpected end of input");
            }
            return Integer.parseInt(token);
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.ArrayList;
import java.util.List;
import java.util.StringTokenizer;

/**
 * Refactored solution for Fox and Two Dots.
 * Detects if there is a cycle in a grid graph where nodes with identical characters are connected.
 */
public class FoxAndTwoDots {

    private int rows;
    private int cols;
    private char[][] grid;
    private List<List<Integer>> adjacencyList;
    private boolean[] visited;

    public static void main(String[] args) {
        // Use try-with-resources for automatic resource management
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
             PrintWriter out = new PrintWriter(System.out)) {

            FastScanner scanner = new FastScanner(reader);
            FoxAndTwoDots solver = new FoxAndTwoDots();
            solver.solve(scanner, out);

        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    /**
     * Orchestrates the solving process.
     *
     * @param in  FastScanner for input
     * @param out PrintWriter for output
     */
    void solve(FastScanner in, PrintWriter out) {
        try {
            // Read dimensions
            String rowStr = in.nextToken();
            String colStr = in.nextToken();

            if (rowStr == null || colStr == null) return;

            this.rows = Integer.parseInt(rowStr);
            this.cols = Integer.parseInt(colStr);

            // Read grid
            this.grid = new char[rows][];
            for (int i = 0; i < rows; i++) {
                String line = in.nextToken();
                if (line != null) {
                    this.grid[i] = line.toCharArray();
                }
            }

            // Build graph and detect cycle
            buildGraph();
            boolean hasCycle = detectCycle();

            if (hasCycle) {
                out.println("Yes");
            } else {
                out.println("No");
            }

        } catch (Exception e) {
            // In a production environment, proper logging should be used.
            // For competitive programming, crashing or ignoring is often acceptable.
            e.printStackTrace();
        }
    }

    /**
     * Constructs the adjacency list representation of the grid graph.
     * Nodes are indexed linearly: index = row * cols + col.
     */
    private void buildGraph() {
        int totalNodes = rows * cols;
        this.adjacencyList = new ArrayList<>(totalNodes);

        // Initialize adjacency lists
        for (int i = 0; i < totalNodes; i++) {
            adjacencyList.add(new ArrayList<>());
        }

        // Iterate through the grid to add edges
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                int u = r * cols + c;
                char currentChar = grid[r][c];

                // Check neighbor below (r+1, c)
                if (r + 1 < rows && grid[r + 1][c] == currentChar) {
                    int v = (r + 1) * cols + c;
                    addUndirectedEdge(u, v);
                }

                // Check neighbor to the right (r, c+1)
                if (c + 1 < cols && grid[r][c + 1] == currentChar) {
                    int v = r * cols + (c + 1);
                    addUndirectedEdge(u, v);
                }
            }
        }
    }

    private void addUndirectedEdge(int u, int v) {
        adjacencyList.get(u).add(v);
        adjacencyList.get(v).add(u);
    }

    /**
     * Detects if there is a cycle in the graph using DFS.
     *
     * @return true if a cycle is found, false otherwise
     */
    private boolean detectCycle() {
        int totalNodes = rows * cols;
        this.visited = new boolean[totalNodes];

        // Check each connected component
        for (int i = 0; i < totalNodes; i++) {
            if (!visited[i]) {
                if (dfs(i, -1)) {
                    return true;
                }
            }
        }
        return false;
    }

    /**
     * Depth First Search to detect back edges (cycles).
     *
     * @param u      Current node index
     * @param parent Parent node index to avoid traversing back up the tree
     * @return true if a cycle is found, false otherwise
     */
    private boolean dfs(int u, int parent) {
        visited[u] = true;

        for (int v : adjacencyList.get(u)) {
            if (v == parent) {
                continue; // Don't go back to the node we just came from
            }

            if (visited[v]) {
                // If we encounter a visited node that is not the parent,
                // we have found a back edge, which implies a cycle.
                return true;
            }

            if (dfs(v, u)) {
                return true;
            }
        }

        return false;
    }

    /**
     * Helper class for fast input reading.
     */
    static class FastScanner {
        private final BufferedReader in;
        private StringTokenizer st;

        public FastScanner(BufferedReader in) {
            this.in = in;
        }

        public String nextToken() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = in.readLine();
                    if (line == null) {
                        return null;
                    }
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            String token = nextToken();
            if (token == null) throw new RuntimeException("End of input");
            return Integer.parseInt(token);
        }

        public long nextLong() {
            String token = nextToken();
            if (token == null) throw new RuntimeException("End of input");
            return Long.parseLong(token);
        }

        public double nextDouble() {
            String token = nextToken();
            if (token == null) throw new RuntimeException("End of input");
            return Double.parseDouble(token);
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayDeque;
import java.util.Deque;
import java.util.StringTokenizer;

public class cf510B {
    // Direction vectors for moving up, down, left, and right
    private static final int[][] DIRECTIONS = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};

    /**
     * Represents a frame on the DFS stack.
     * Tracks current coordinates and the index of the node that discovered it.
     */
    private static class StackFrame {
        final int r, c, parentIdx;

        StackFrame(int r, int c, int parentIdx) {
            this.r = r;
            this.c = c;
            this.parentIdx = parentIdx;
        }
    }

    /**
     * Fast and maintainable input reader using BufferedReader and StringTokenizer.
     * Replaces the original hybrid InputStream/BufferedReader reader which was error-prone.
     */
    private static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input", e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            String token = next();
            return token == null ? 0 : Integer.parseInt(token);
        }
    }

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner();
        String sStr = scanner.next();
        if (sStr == null) return;

        int rows = Integer.parseInt(sStr);
        int cols = scanner.nextInt();

        char[][] grid = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            String line = scanner.next();
            grid[i] = line.toCharArray();
        }

        boolean[][] visited = new boolean[rows][cols];
        boolean cycleFound = false;

        // Iterate over every cell to ensure disconnected components are processed
        for (int i = 0; i < rows && !cycleFound; i++) {
            for (int j = 0; j < cols && !cycleFound; j++) {
                if (!visited[i][j]) {
                    cycleFound = hasCycle(grid, visited, i, j);
                }
            }
        }

        System.out.println(cycleFound ? "Yes" : "No");
    }

    /**
     * Performs iterative DFS to detect cycles in the grid graph.
     * Nodes are grid cells. Edges connect adjacent cells with identical characters.
     * A cycle is detected when we encounter a visited neighbor that is not the direct parent.
     */
    private static boolean hasCycle(char[][] grid, boolean[][] visited, int startR, int startC) {
        int rows = grid.length;
        int cols = grid[0].length;

        visited[startR][startC] = true;
        int startIdx = startR * cols + startC;

        Deque<StackFrame> stack = new ArrayDeque<>();
        stack.push(new StackFrame(startR, startC, -1));

        while (!stack.isEmpty()) {
            StackFrame current = stack.pop();
            int r = current.r;
            int c = current.c;
            int parentIdx = current.parentIdx;
            int currentIdx = r * cols + c;

            for (int[] dir : DIRECTIONS) {
                int nr = r + dir[0];
                int nc = c + dir[1];

                // Validate bounds and check if adjacent cell has the same character
                if (nr >= 0 && nr < rows && nc >= 0 && nc < cols && grid[nr][nc] == grid[r][c]) {
                    int neighborIdx = nr * cols + nc;

                    if (visited[nr][nc]) {
                        // Visited neighbor found. If it's not the parent, a cycle exists.
                        if (neighborIdx != parentIdx) {
                            return true;
                        }
                    } else {
                        // Mark as visited immediately to prevent duplicate stack entries
                        visited[nr][nc] = true;
                        stack.push(new StackFrame(nr, nc, currentIdx));
                    }
                }
            }
        }
        return false;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.OutputStream;
import java.io.PrintWriter;
import java.util.StringTokenizer;

public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        FastScanner in = new FastScanner(inputStream);
        PrintWriter out = new PrintWriter(outputStream);

        FoxAndTwoDots solver = new FoxAndTwoDots();
        solver.solve(in, out);

        out.close();
    }

    static class FoxAndTwoDots {
        public void solve(FastScanner in, PrintWriter out) {
            String nStr = in.next();
            if (nStr == null) return;
            int n = Integer.parseInt(nStr);
            int m = in.nextInt();

            char[][] grid = new char[n][];
            for (int i = 0; i < n; i++) {
                grid[i] = in.next().toCharArray();
            }

            boolean[][] visited = new boolean[n][m];
            boolean cycleFound = false;

            // Iterate over every cell to handle disconnected components
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    if (!visited[i][j]) {
                        // Start DFS from this cell. 
                        // Parent coordinates initialized to (-1, -1) to indicate no parent.
                        if (hasCycle(i, j, -1, -1, visited, grid)) {
                            cycleFound = true;
                            break;
                        }
                    }
                }
                if (cycleFound) break;
            }

            out.println(cycleFound ? "Yes" : "No");
        }

        /**
         * Performs DFS to detect a cycle in the grid.
         * A cycle exists if we encounter a visited node that is not the immediate parent.
         * In a grid graph, any cycle must have a length of at least 4.
         */
        private boolean hasCycle(int r, int c, int pr, int pc, boolean[][] visited, char[][] grid) {
            visited[r][c] = true;

            // Directions: Right, Left, Down, Up
            int[] dr = {0, 0, 1, -1};
            int[] dc = {1, -1, 0, 0};

            for (int k = 0; k < 4; k++) {
                int nr = r + dr[k];
                int nc = c + dc[k];

                // Check boundaries
                if (nr >= 0 && nr < grid.length && nc >= 0 && nc < grid[0].length) {
                    // Must be the same character to form a path
                    if (grid[nr][nc] == grid[r][c]) {
                        // If neighbor is visited and it's not the parent we came from,
                        // we found a back-edge, which implies a cycle.
                        if (visited[nr][nc] && !(nr == pr && nc == pc)) {
                            return true;
                        }
                        // If not visited, continue DFS
                        if (!visited[nr][nc]) {
                            if (hasCycle(nr, nc, r, c, visited, grid)) {
                                return true;
                            }
                        }
                    }
                }
            }
            return false;
        }
    }

    static class FastScanner {
        private BufferedReader br;
        private StringTokenizer st;

        public FastScanner(InputStream stream) {
            br = new BufferedReader(new InputStreamReader(stream), 32768);
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            String s = next();
            return s == null ? 0 : Integer.parseInt(s);
        }
    }
}

import java.util.Scanner;

/**
 * Refactored version of the grid analysis program.
 * 
 * Improvements made:
 * 1. Class Structure: Moved Node class inside Main as a static inner class for better encapsulation.
 * 2. Naming: Renamed variables and methods for clarity (e.g., 'c' -> 'grid', 'z' -> 'character', 'val' -> 'id').
 * 3. DSU Implementation: 
 *    - Converted 'find' to an iterative approach to prevent StackOverflowError on deep trees.
 *    - Encapsulated logic into clear static methods.
 *    - Used Union by Rank logic correctly.
 * 4. Code Quality: Added Javadoc comments, improved indentation, and removed redundant checks.
 * 5. Safety: Added basic input validation.
 */
public class Main {

    /**
     * Represents a node in the grid, used for the Union-Find data structure.
     */
    static class Node {
        private final int id;
        private final char character;
        Node parent;

        public Node(int id, char character) {
            this.id = id;
            this.character = character;
            this.parent = null;
        }
    }

    /**
     * Finds the representative (root) of the set containing the given node.
     * Implements path compression to flatten the structure.
     * 
     * @param node The node to find the root for.
     * @return The root node of the set.
     */
    private static Node find(Node node) {
        if (node.parent == null) {
            return node;
        }

        // Iterative path compression to find the root
        Node root = node;
        while (root.parent != null) {
            root = root.parent;
        }

        // Path compression step: point all nodes on the path directly to the root
        Node current = node;
        while (current != root) {
            Node next = current.parent;
            current.parent = root;
            current = next;
        }

        return root;
    }

    /**
     * Unites the sets containing node1 and node2 using union by rank.
     * 
     * @param node1 First node.
     * @param node2 Second node.
     * @param rank  Array storing the rank (approximate depth) of each root.
     */
    private static void union(Node node1, Node node2, int[] rank) {
        Node root1 = find(node1);
        Node root2 = find(node2);

        // If they are already in the same set, no action needed
        if (root1.id == root2.id) {
            return;
        }

        // Union by rank: attach smaller rank tree under root of higher rank tree
        if (rank[root1.id] < rank[root2.id]) {
            root1.parent = root2;
        } else if (rank[root1.id] > rank[root2.id]) {
            root2.parent = root1;
        } else {
            root1.parent = root2;
            rank[root2.id]++;
        }
    }

    /**
     * Checks if two nodes belong to the same set.
     * 
     * @param node1 First node.
     * @param node2 Second node.
     * @return true if nodes are in the same set, false otherwise.
     */
    private static boolean isSame(Node node1, Node node2) {
        return find(node1).id == find(node2).id;
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        // Read dimensions
        if (!scanner.hasNextInt()) return;
        int n = scanner.nextInt();
        int m = scanner.nextInt();

        // Handle edge case for empty grid
        if (n <= 0 || m <= 0) {
            System.out.println("No");
            return;
        }

        Node[][] grid = new Node[n][m];
        int[] rank = new int[n * m];

        // Initialize grid nodes
        for (int i = 0; i < n; i++) {
            String row = scanner.next();
            for (int j = 0; j < m; j++) {
                // Safe access to character
                char c = (j < row.length()) ? row.charAt(j) : ' ';
                grid[i][j] = new Node(i * m + j, c);
            }
        }

        // Process grid to detect cycles of identical characters
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                Node current = grid[i][j];

                // Check Right Neighbor
                if (j + 1 < m) {
                    Node right = grid[i][j + 1];
                    if (current.character == right.character) {
                        if (isSame(current, right)) {
                            System.out.println("Yes");
                            return;
                        }
                        union(current, right, rank);
                    }
                }

                // Check Down Neighbor
                if (i + 1 < n) {
                    Node down = grid[i + 1][j];
                    if (current.character == down.character) {
                        if (isSame(current, down)) {
                            System.out.println("Yes");
                            return;
                        }
                        union(current, down, rank);
                    }
                }
            }
        }

        System.out.println("No");
        scanner.close();
    }
}

import java.util.Scanner;
