public class Dots {
    // Constant for the target path/cycle length
    private static final int TARGET_LENGTH = 4;

    public static void main(String[] args) {
        // Use try-with-resources to ensure the Scanner is closed automatically
        try (Scanner scanner = new Scanner(System.in)) {
            if (!scanner.hasNextInt()) {
                return;
            }

            int rows = scanner.nextInt();
            int cols = scanner.nextInt();

            char[][] grid = new char[rows][cols];

            // Read the grid
            // Note: The original logic assumes each row is provided as a single string token
            // without spaces between characters (e.g., "AAAA").
            for (int i = 0; i < rows; i++) {
                if (scanner.hasNext()) {
                    String line = scanner.next();
                    // Fill the row, handling cases where input might be shorter than expected
                    int length = Math.min(line.length(), cols);
                    for (int j = 0; j < length; j++) {
                        grid[i][j] = line.charAt(j);
                    }
                }
            }

            Dots solver = new Dots();
            boolean found = solver.hasCycleOfLength4(grid, rows, cols);

            System.out.println(found ? "Yes" : "No");
        }
    }

    /**
     * Determines if there is a cycle of length >= TARGET_LENGTH in the grid.
     * It iterates through every cell as a potential starting point for a search.
     */
    private boolean hasCycleOfLength4(char[][] grid, int rows, int cols) {
        // Visited array to store the depth (step count) at which a cell was first visited
        int[][] visitedDepths = new int[rows][cols];

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                // Reset visited array for each new starting point search
                resetVisited(visitedDepths);

                // Start DFS from (r, c) with depth 1
                if (dfs(grid, visitedDepths, r, c, rows, cols, 1)) {
                    return true;
                }
            }
        }
        return false;
    }

    /**
     * Resets the visitedDepths array to 0.
     */
    private void resetVisited(int[][] visited) {
        for (int i = 0; i < visited.length; i++) {
            Arrays.fill(visited[i], 0);
        }
    }

    /**
     * Depth First Search to find a cycle of length >= TARGET_LENGTH.
     *
     * @param grid The character grid
     * @param visitedDepths Stores the depth when a cell was first visited in the current path
     * @param r Current row
     * @param c Current column
     * @param rows Total rows
     * @param cols Total columns
     * @param currentDepth Current depth in the recursion
     * @return true if a valid cycle is found, false otherwise
     */
    private boolean dfs(char[][] grid, int[][] visitedDepths, int r, int c, int rows, int cols, int currentDepth) {
        // If we encounter a node already visited in the current path
        if (visitedDepths[r][c] != 0) {
            // Check if the cycle length (current depth - visit depth) meets the target
            if (currentDepth - visitedDepths[r][c] >= TARGET_LENGTH) {
                return true;
            }
            // If cycle is too short, this path branch is invalid
            return false;
        }

        // Mark the current node as visited with the current depth
        visitedDepths[r][c] = currentDepth;

        // Define movement directions: Up, Down, Left, Right
        int[] dr = {-1, 1, 0, 0};
        int[] dc = {0, 0, -1, 1};

        for (int k = 0; k < 4; k++) {
            int nr = r + dr[k];
            int nc = c + dc[k];

            // Check bounds and character match
            if (isValid(nr, nc, rows, cols) && grid[nr][nc] == grid[r][c]) {
                if (dfs(grid, visitedDepths, nr, nc, rows, cols, currentDepth + 1)) {
                    return true;
                }
            }
        }

        // Backtrack: unmark the node so it can be used in other paths
        visitedDepths[r][c] = 0;
        return false;
    }

    /**
     * Checks if the given coordinates are within the grid boundaries.
     */
    private boolean isValid(int r, int c, int rows, int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }
}

