/**
 * Core logic for detecting cycles of length >= 4 in a colored grid.
 * Uses DFS with a dedicated visited array to avoid in-place mutation 
 * and mutable instance state, making the algorithm pure and thread-safe.
 */
class GridCycleChecker {
    private static final int[] DX = {1, -1, 0, 0};
    private static final int[] DY = {0, 0, 1, -1};
    private static final int MIN_CYCLE_LENGTH = 4;

    /**
     * Checks if the grid contains a cycle of the same color with length >= 4.
     *
     * @param grid The input grid of characters
     * @return true if a valid cycle exists, false otherwise
     */
    public boolean hasCycleOfLengthAtLeast4(char[][] grid) {
        int rows = grid.length;
        int cols = grid[0].length;
        boolean[][] visited = new boolean[rows][cols];

        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                // Only start DFS from unvisited cells to handle disconnected components
                if (!visited[i][j]) {
                    if (dfs(i, j, -1, -1, grid[i][j], 1, grid, visited)) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Performs depth-first search to detect cycles.
     *
     * @param x         Current row
     * @param y         Current column
     * @param parentX   Parent row (prevents immediate backtracking)
     * @param parentY   Parent column
     * @param color     Target color to traverse
     * @param depth     Current depth in the DFS path
     * @param grid      The grid being traversed
     * @param visited   Visited cell tracking array
     * @return true if a cycle of length >= MIN_CYCLE_LENGTH is found
     */
    private boolean dfs(int x, int y, int parentX, int parentY, char color, int depth, char[][] grid, boolean[][] visited) {
        visited[x][y] = true;

        for (int d = 0; d < 4; d++) {
            int nextX = x + DX[d];
            int nextY = y + DY[d];

            // Skip the immediate parent to avoid false cycle detection
            if (nextX == parentX && nextY == parentY) {
                continue;
            }

            if (!isValidCell(nextX, nextY, grid)) {
                continue;
            }

            // Only traverse cells matching the current color
            if (grid[nextX][nextY] != color) {
                continue;
            }

            if (visited[nextX][nextY]) {
                // Found a back-edge to a visited node.
                // In grid graphs, this indicates a cycle.
                // depth >= 4 ensures the cycle length is at least 4.
                if (depth >= MIN_CYCLE_LENGTH) {
                    return true;
                }
            } else {
                // Continue DFS to unvisited nodes
                if (dfs(nextX, nextY, x, y, color, depth + 1, grid, visited)) {
                    return true;
                }
            }
        }
        return false;
    }

    private boolean isValidCell(int row, int col, char[][] grid) {
        return row >= 0 && row < grid.length && col >= 0 && col < grid[0].length;
    }
}

