        writer.println();
    }

    public void close() {
        writer.close();
    }
}

import java.util.Scanner;

public class GridCycleDetector {

    // Direction vectors for moving Up, Right, Down, Left
    private static final int[] DR = {-1, 0, 1, 0};
    private static final int[] DC = {0, 1, 0, -1};

    /**
     * Helper class to track statistics of a connected component.
     */
    private static class ComponentMetrics {
        int nodeCount = 0;
        int edgeCount = 0;
    }

    /**
     * Performs a Depth First Search (DFS) to traverse a connected component.
     *
     * @param board   The grid of characters.
     * @param visited Boolean matrix to track visited cells.
     * @param r       Current row index.
     * @param c       Current column index.
     * @param metrics Object to accumulate node and edge counts.
     */
    private static void traverse(char[][] board, boolean[][] visited, int r, int c, ComponentMetrics metrics) {
        visited[r][c] = true;
        metrics.nodeCount++;

        // Check all 4 neighbors
        for (int k = 0; k < 4; k++) {
            int nextRow = r + DR[k];
            int nextCol = c + DC[k];

            // Check bounds and if neighbor has the same color
            if (isValid(board, nextRow, nextCol) && board[nextRow][nextCol] == board[r][c]) {
                metrics.edgeCount++;

                // If neighbor not visited, recurse
                if (!visited[nextRow][nextCol]) {
                    traverse(board, visited, nextRow, nextCol, metrics);
                }
            }
        }
    }

    /**
     * Checks if the given coordinates are within the grid bounds.
     */
    private static boolean isValid(char[][] board, int r, int c) {
        return r >= 0 && r < board.length && c >= 0 && c < board[0].length;
    }

    public static void main(String[] args) {
        // Use try-with-resources to ensure Scanner is closed
        try (Scanner scanner = new Scanner(System.in)) {
            if (!scanner.hasNextInt()) return;

            int rows = scanner.nextInt();
            int cols = scanner.nextInt();

            char[][] board = new char[rows][cols];
            boolean[][] visited = new boolean[rows][cols];

            // Read the grid
            for (int i = 0; i < rows; i++) {
                String line = scanner.next();
                board[i] = line.toCharArray();
            }

            boolean hasCycle = false;

            // Iterate through every cell to find connected components
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (!visited[i][j]) {
                        ComponentMetrics metrics = new ComponentMetrics();
                        traverse(board, visited, i, j, metrics);

                        // A connected component is a tree if it has exactly (Nodes - 1) edges.
                        // Our counting method counts each edge twice (once from each node).
                        // Therefore, the condition for a tree is: edgeCount == 2 * (nodeCount - 1).
                        // If this does not hold, the component contains a cycle.
                        if (metrics.edgeCount != 2 * (metrics.nodeCount - 1)) {
                            hasCycle = true;
                            break;
                        }
                    }
                }
                if (hasCycle) break;
            }

            System.out.println(hasCycle ? "Yes" : "No");
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;

public class Solution {

    public static void main(String[] args) throws IOException {
        // Use try-with-resources to ensure the reader is closed automatically
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            String line = br.readLine();
            if (line == null) return;

            // Split by whitespace to handle multiple spaces between numbers robustly
            String[] dimensions = line.trim().split("\\s+");
            int rows = Integer.parseInt(dimensions[0]);
            int cols = Integer.parseInt(dimensions[1]);

            // Use char[][] to store the grid as it contains characters
            char[][] grid = new char[rows][cols];

            for (int i = 0; i < rows; i++) {
                String rowStr = br.readLine();
                // Basic validation to prevent IndexOutOfBoundsException
                if (rowStr != null) {
                    for (int j = 0; j < cols && j < rowStr.length(); j++) {
                        grid[i][j] = rowStr.charAt(j);
                    }
                }
            }

            // DSU is 1-indexed, so capacity is rows * cols + 1
            DSU dsu = new DSU(rows * cols);

            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    int currentVertex = i * cols + j + 1; // 1-based index

                    // Check Top Neighbor (i-1, j)
                    if (i > 0 && grid[i - 1][j] == grid[i][j]) {
                        int topVertex = (i - 1) * cols + j + 1;
                        if (dsu.find(currentVertex) == dsu.find(topVertex)) {
                            System.out.println("Yes");
                            return;
                        }
                        dsu.union(currentVertex, topVertex);
                    }

                    // Check Left Neighbor (i, j-1)
                    if (j > 0 && grid[i][j - 1] == grid[i][j]) {
                        int leftVertex = i * cols + (j - 1) + 1;
                        if (dsu.find(currentVertex) == dsu.find(leftVertex)) {
                            System.out.println("Yes");
                            return;
                        }
                        dsu.union(currentVertex, leftVertex);
                    }
                }
            }

            System.out.println("No");
        }
    }

    /**
     * Disjoint Set Union (DSU) data structure implementation.
     * Supports Path Compression and Union by Size.
     */
    private static class DSU {
        private int[] parent;
        private int[] size;

        /**
         * Initializes the DSU structure.
         * @param n The number of elements (vertices).
         */
        public DSU(int n) {
            // Arrays are 1-indexed to match the vertex numbering logic (1 to n)
            parent = new int[n + 1];
            size = new int[n + 1];
            for (int i = 1; i <= n; i++) {
                parent[i] = i;
                size[i] = 1;
            }
        }

        /**
         * Finds the representative (root) of the set containing the given vertex.
         * Uses Path Compression to flatten the structure.
         * @param vertex The vertex to find.
         * @return The root of the set.
         */
        public int find(int vertex) {
            if (parent[vertex] == vertex) {
                return vertex;
            }
            // Path compression: recursively find root and update parent pointer
            parent[vertex] = find(parent[vertex]);
            return parent[vertex];
        }

        /**
         * Unites the sets containing vertices u and v.
         * Uses Union by Size to keep tree height low.
         * @param u First vertex.
         * @param v Second vertex.
         */
        public void union(int u, int v) {
            int rootU = find(u);
            int rootV = find(v);

            if (rootU != rootV) {
                // Attach smaller tree to larger tree
                if (size[rootU] < size[rootV]) {
                    parent[rootU] = rootV;
                    size[rootV] += size[rootU];
                } else {
                    parent[rootV] = rootU;
                    size[rootU] += size[rootV];
                }
            }
        }
    }
}

