/**
 * Refactored solution for Fox And Two Dots.
 * Detects if there is a cycle of identical characters in a grid.
 */
public class FoxAndTwoDots {

    // Grid dimensions
    private int rows;
    private int cols;

    // Data structures
    private char[][] grid;
    private boolean[][] visited;

    // Result flag
    private boolean hasCycle;

    // Direction vectors for moving Up, Right, Down, Left
    // Using static final constants improves readability and performance
    private static final int[] DR = {-1, 0, 1, 0};
    private static final int[] DC = {0, 1, 0, -1};

    public static void main(String[] args) throws IOException {
        // Use try-with-resources for automatic resource management
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
             PrintWriter out = new PrintWriter(System.out)) {

            FoxAndTwoDots solver = new FoxAndTwoDots();
            solver.solve(reader, out);
        }
    }

    public void solve(BufferedReader reader, PrintWriter out) throws IOException {
        String line = reader.readLine();
        if (line == null) return;

        // Use StringTokenizer for robust whitespace handling
        StringTokenizer tokenizer = new StringTokenizer(line);
        this.rows = Integer.parseInt(tokenizer.nextToken());
        this.cols = Integer.parseInt(tokenizer.nextToken());

        this.grid = new char[rows][cols];
        this.visited = new boolean[rows][cols];
        this.hasCycle = false;

        // Read the grid
        for (int i = 0; i < rows; i++) {
            String rowStr = reader.readLine();
            if (rowStr != null) {
                for (int j = 0; j < cols && j < rowStr.length(); j++) {
                    this.grid[i][j] = rowStr.charAt(j);
                }
            }
        }

        // Iterate through every cell to find cycles in disconnected components
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (!visited[i][j]) {
                    dfs(i, j, -1, -1);
                    if (hasCycle) break;
                }
            }
            if (hasCycle) break;
        }

        out.println(hasCycle ? "Yes" : "No");
    }

    /**
     * Depth First Search to detect cycles.
     *
     * @param r Current row
     * @param c Current column
     * @param prevR Previous row (parent)
     * @param prevC Previous column (parent)
     */
    private void dfs(int r, int c, int prevR, int prevC) {
        visited[r][c] = true;

        for (int k = 0; k < 4; k++) {
            int nextR = r + DR[k];
            int nextC = c + DC[k];

            // Check boundaries
            if (nextR < 0 || nextR >= rows || nextC < 0 || nextC >= cols) {
                continue;
            }

            // Check if the neighbor has the same character
            if (grid[nextR][nextC] != grid[r][c]) {
                continue;
            }

            // If neighbor is visited and is not the parent, a cycle is found
            if (visited[nextR][nextC] && (nextR != prevR || nextC != prevC)) {
                hasCycle = true;
                return;
            }

            // If neighbor is not visited, continue DFS
            if (!visited[nextR][nextC]) {
                dfs(nextR, nextC, r, c);
                if (hasCycle) return; // Optimization: stop recursion if cycle found
            }
        }
    }
}

import java.io.*;
import java.math.BigInteger;
import java.util.StringTokenizer;

/**
 * Solution class for grid-based pathfinding problem.
 * Refactored for maintainability, safety, and performance.
 */
public class Solution {

    /**
     * Efficient scanner for fast I/O.
     * Replaced recursive token parsing with iterative to prevent stack overflow.
     */
    static class FastScanner {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastScanner(InputStream in) {
            reader = new BufferedReader(new InputStreamReader(in));
            tokenizer = new StringTokenizer("");
        }

        public FastScanner(File f) throws FileNotFoundException {
            reader = new BufferedReader(new FileReader(f));
            tokenizer = new StringTokenizer("");
        }

        private String readNextToken() throws IOException {
            while (!tokenizer.hasMoreTokens()) {
                String line = reader.readLine();
                if (line == null) {
                    return null;
                }
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            String token = readNextToken();
            if (token == null) throw new EOFException("Unexpected end of input");
            return Integer.parseInt(token);
        }

        public long nextLong() throws IOException {
            String token = readNextToken();
            if (token == null) throw new EOFException("Unexpected end of input");
            return Long.parseLong(token);
        }

        public double nextDouble() throws IOException {
            String token = readNextToken();
            if (token == null) throw new EOFException("Unexpected end of input");
            return Double.parseDouble(token);
        }

        public BigInteger nextBigInteger() throws IOException {
            String token = readNextToken();
            if (token == null) throw new EOFException("Unexpected end of input");
            return new BigInteger(token);
        }

        public String nextString() throws IOException {
            String token = readNextToken();
            if (token == null) throw new EOFException("Unexpected end of input");
            return token;
        }

        public String readLine() throws IOException {
            return reader.readLine();
        }

        public void close() throws IOException {
            reader.close();
        }
    }

    // --- Mathematical Utilities ---

    /** Modular exponentiation: (base^exp) % mod */
    private static long power(long base, long exp, long mod) {
        long res = 1;
        long b = base % mod;
        while (exp > 0) {
            if ((exp & 1) == 1) {
                res = (res * b) % mod;
            }
            b = (b * b) % mod;
            exp >>= 1;
        }
        return res;
    }

    /** Counts divisors in O(sqrt(n)) time. Fixed original O(n) loop bug. */
    private static int countDivisors(long n) {
        int count = 0;
        for (long i = 1; i * i <= n; i++) {
            if (n % i == 0) {
                count++;
                if (i * i != n) {
                    count++;
                }
            }
        }
        return count;
    }

    /** Greatest Common Divisor */
    public static long gcd(long a, long b) {
        return b == 0 ? a : gcd(b, a % b);
    }

    /** Least Common Multiple. Uses long to prevent overflow. */
    public static long lcm(long a, long b) {
        if (a == 0 || b == 0) return 0;
        return (a / gcd(a, b)) * b;
    }

    /** Modular Inverse using Extended Euclidean Algorithm */
    private static long modularInverse(long a, long mod) {
        long m = mod, p = 1, q = 0;
        while (m > 0) {
            long c = a / m;
            long d = a;
            a = m;
            m = d % m;
            d = p;
            p = q;
            q = d - c * q;
        }
        return p < 0 ? p + mod : p;
    }

    // --- Problem State ---
    private int rows;
    private int cols;
    private char[][] grid;
    private boolean[][] visited;
    private int targetRow;
    private int targetCol;

    /**
     * Depth-First Search to find a path of length >= 4 matching the target character.
     * Includes backtracking to correctly explore all possible paths.
     */
    private boolean dfs(int r, int c, int count) {
        // Boundary checks
        if (r < 0 || r >= rows || c < 0 || c >= cols) {
            return false;
        }
        // Target reached with sufficient length
        if (r == targetRow && c == targetCol && count >= 4) {
            return true;
        }
        // Already visited in current path
        if (visited[r][c]) {
            return false;
        }

        visited[r][c] = true;
        char targetChar = grid[targetRow][targetCol];

        // Explore neighbors (down, up, right, left)
        boolean found = dfs(r + 1, c, count + 1) ||
                        dfs(r - 1, c, count + 1) ||
                        dfs(r, c + 1, count + 1) ||
                        dfs(r, c - 1, count + 1);

        // Backtrack for other paths
        visited[r][c] = false;
        return found;
    }

    /**
     * Solves the problem: reads input, processes grid, and prints result.
     * I/O resources are managed locally to avoid static state pollution.
     */
    public void solve() throws IOException {
        FastScanner scanner = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));

        try {
            rows = scanner.nextInt();
            cols = scanner.nextInt();
            grid = new char[rows][cols];

            for (int i = 0; i < rows; i++) {
                String line = scanner.nextString();
                grid[i] = line.toCharArray();
            }

            boolean found = false;
            outer:
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    visited = new boolean[rows][cols];
                    targetRow = i;
                    targetCol = j;
                    if (dfs(i, j, 0)) {
                        found = true;
                        break outer;
                    }
                }
            }

            out.println(found ? "Yes" : "No");
        } finally {
            scanner.close();
            out.flush();
            out.close();
        }
    }

    public static void main(String[] args) throws IOException {
        new Solution().solve();
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayDeque;
import java.util.Deque;
import java.util.Queue;

/**
 * Solves a grid-based path/arrow placement problem.
 * Refactored for maintainability, readability, and standard Java practices.
 */
public class ProblemB {
    // Standard 4-directional movement (Up, Down, Left, Right)
    private static final int[][] DIRECTIONS = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};

    // Expansion offsets used during drawing. Preserved exactly as in original code.
    private static final int[][] EXPANSION_OFFSETS = {{-1, 0}, {2, 0}, {0, -1}, {1, -1}, {0, 1}, {1, 1}};

    private int rows;
    private int cols;
    private char[][] grid;
    private final BufferedReader reader;

    public ProblemB() throws IOException {
        this.reader = new BufferedReader(new InputStreamReader(System.in));
        solve();
    }

    private void solve() throws IOException {
        // 1. Read dimensions
        String line = reader.readLine();
        if (line == null) return;
        String[] dims = line.trim().split("\\s+");
        rows = Integer.parseInt(dims[0]);
        cols = Integer.parseInt(dims[1]);

        // 2. Read grid
        grid = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            String rowLine = reader.readLine();
            grid[i] = (rowLine != null) ? rowLine.trim().toCharArray() : new char[cols];
        }

        // 3. Initial scan: find cells with exactly 1 empty neighbor
        Deque<int[]> candidates = new ArrayDeque<>();
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '.') {
                    int neighbors = countNeighbors(r, c);
                    if (neighbors == 0) {
                        printResult("Not unique");
                        return;
                    }
                    if (neighbors == 1) {
                        candidates.offer(new int[]{r, c});
                    }
                }
            }
        }

        // 4. Process candidates iteratively
        while (!candidates.isEmpty()) {
            int[] cell = candidates.poll();
            int[] singleDir = findSingleDirection(cell);

            if (singleDir != null) {
                boolean isVertical = singleDir[0] != 0;
                Queue<int[]> expansionQueue = new ArrayDeque<>();
                draw(cell, isVertical, expansionQueue);

                for (int[] expanded : expansionQueue) {
                    if (countNeighbors(expanded[0], expanded[1]) == 1) {
                        candidates.offer(expanded);
                    }
                }
            }
        }

        // 5. Validate and process remaining unvisited components
        boolean[][] visited = new boolean[rows][cols];
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '.' && !visited[r][c]) {
                    if (!processComponent(r, c, visited)) {
                        printResult("Not unique");
                        return;
                    }
                }
            }
        }

        // 6. Output successful result
        StringBuilder sb = new StringBuilder();
        for (int r = 0; r < rows; r++) {
            sb.append(grid[r]).append('\n');
        }
        printResult(sb.toString());
    }

    /**
     * Counts the number of adjacent '.' cells in the 4 cardinal directions.
     */
    private int countNeighbors(int r, int c) {
        int count = 0;
        for (int[] d : DIRECTIONS) {
            int nr = r + d[0];
            int nc = c + d[1];
            if (isValid(nr, nc) && grid[nr][nc] == '.') {
                count++;
            }
        }
        return count;
    }

    /**
     * Checks if there is exactly one adjacent '.' cell. Returns its direction, or null.
     */
    private int[] findSingleDirection(int[] cell) {
        int[] dir = null;
        for (int[] d : DIRECTIONS) {
            int nr = cell[0] + d[0];
            int nc = cell[1] + d[1];
            if (isValid(nr, nc) && grid[nr][nc] == '.') {
                if (dir == null) {
                    dir = d;
                } else {
                    return null; // More than one direction found
                }
            }
        }
        return dir;
    }

    /**
     * Performs BFS on an unvisited component, validates constraints, and draws arrows.
     */
    private boolean processComponent(int startR, int startC, boolean[][] visited) {
        Queue<int[]> bfsQueue = new ArrayDeque<>();
        bfsQueue.offer(new int[]{startR, startC});
        visited[startR][startC] = true;

        int[] startCell = null;
        boolean isVerticalStart = true;
        int componentSize = 0;

        while (!bfsQueue.isEmpty()) {
            int[] curr = bfsQueue.poll();
            componentSize++;
            int neighbors = 0;
            boolean localVertical = true;

            for (int[] d : DIRECTIONS) {
                int nr = curr[0] + d[0];
                int nc = curr[1] + d[1];
                if (isValid(nr, nc)) {
                    if (grid[nr][nc] == '.') {
                        if (!visited[nr][nc]) {
                            visited[nr][nc] = true;
                            bfsQueue.offer(new int[]{nr, nc});
                            localVertical = d[0] != 0;
                        }
                    } else {
                        neighbors++;
                    }
                } else {
                    neighbors++;
                }
            }

            if (neighbors == 4) return false;
            if (neighbors == 3 && startCell == null) {
                startCell = curr;
                isVerticalStart = localVertical;
            }
        }

        // Validation checks
        if (componentSize % 2 != 0 || startCell == null) {
            return false;
        }

        // Draw the validated component
        Queue<int[]> expansionQueue = new ArrayDeque<>();
        expansionQueue.offer(startCell);
        while (!expansionQueue.isEmpty()) {
            int[] cell = expansionQueue.poll();
            if (grid[cell[0]][cell[1]] == '.') {
                draw(cell, isVerticalStart, expansionQueue);
            }
        }
        return true;
    }

    /**
     * Places directional arrows and adds newly discovered '.' cells to the target queue.
     */
    private void draw(int[] cell, boolean isVertical, Queue<int[]> targetQueue) {
        if (isVertical) {
            int y0 = -1, y1 = -1;
            if (cell[0] > 0 && grid[cell[0] - 1][cell[1]] == '.') {
                y0 = cell[0] - 1;
                y1 = cell[0];
            } else if (cell[0] < rows - 1 && grid[cell[0] + 1][cell[1]] == '.') {
                y0 = cell[0];
                y1 = cell[0] + 1;
            }

            if (y0 != -1 && y1 != -1) {
                grid[y0][cell[1]] = '^';
                grid[y1][cell[1]] = 'v';
                for (int[] d : EXPANSION_OFFSETS) {
                    int nr = y0 + d[0];
                    int nc = cell[1] + d[1];
                    if (isValid(nr, nc) && grid[nr][nc] == '.') {
                        targetQueue.offer(new int[]{nr, nc});
                    }
                }
            }
        } else {
            int x0 = -1, x1 = -1;
            if (cell[1] > 0 && grid[cell[0]][cell[1] - 1] == '.') {
                x0 = cell[1] - 1;
                x1 = cell[1];
            } else if (cell[1] < cols - 1 && grid[cell[0]][cell[1] + 1] == '.') {
                x0 = cell[1];
                x1 = cell[1] + 1;
            }

            if (x0 != -1 && x1 != -1) {
                grid[cell[0]][x0] = '<';
                grid[cell[0]][x1] = '>';
                for (int[] d : EXPANSION_OFFSETS) {
                    // Note: Preserving original index-swapping behavior for horizontal expansion
                    int nr = cell[0] + d[1];
                    int nc = x0 + d[0];
                    if (isValid(nr, nc) && grid[nr][nc] == '.') {
                        targetQueue.offer(new int[]{nr, nc});
                    }
                }
            }
        }
    }

    private boolean isValid(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    private void printResult(Object output) {
        System.out.println(output);
    }

    public static void main(String[] args) throws IOException {
        new ProblemB();
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.LinkedList;
import java.util.Queue;
import java.util.StringTokenizer;

/**
 * Solves a grid-based puzzle by propagating directional arrows through empty cells.
 * Refactored for maintainability, performance, and clear separation of concerns.
 */
public class GridSolver {

    // Constants for grid characters
    private static final char EMPTY = '.';
    private static final char DIR_UP = '^';
    private static final char DIR_DOWN = 'v';
    private static final char DIR_LEFT = '<';
    private static final char DIR_RIGHT = '>';

    // Direction vectors: Down, Left, Up, Right
    private static final int[] DR = {1, 0, -1, 0};
    private static final int[] DC = {0, -1, 0, 1};

    private char[][] grid;
    private int rows;
    private int cols;
    private PrintWriter out;

    /**
     * Entry point for the solver. Handles I/O setup and triggers processing.
     */
    public void solve() {
        FastScanner sc = new FastScanner();
        if (!sc.hasMoreTokens()) {
            return;
        }

        rows = sc.nextInt();
        cols = sc.nextInt();
        grid = new char[rows][cols];

        for (int i = 0; i < rows; i++) {
            String line = sc.next();
            grid[i] = line.toCharArray();
        }

        out = new PrintWriter(System.out);
        processGrid();
        out.flush();
    }

    /**
     * Core algorithm: BFS-like traversal to pair adjacent empty cells with directional arrows.
     */
    private void processGrid() {
        Queue<int[]> queue = new LinkedList<>();

        // Initialize queue with empty cells that have exactly one adjacent empty cell
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == EMPTY && countAdjacentEmpty(r, c) == 1) {
                    queue.offer(new int[]{r, c});
                }
            }
        }

        while (!queue.isEmpty()) {
            int[] current = queue.poll();
            int r = current[0];
            int c = current[1];

            // Skip if already processed or modified
            if (grid[r][c] != EMPTY) {
                continue;
            }

            // Find the first adjacent empty cell to pair with
            for (int i = 0; i < 4; i++) {
                int nr = r + DR[i];
                int nc = c + DC[i];

                if (isInBounds(nr, nc) && grid[nr][nc] == EMPTY) {
                    placeArrows(r, c, nr, nc);

                    // Check neighbors of the paired cell to add new starting points
                    for (int j = 0; j < 4; j++) {
                        int nnr = nr + DR[j];
                        int nnc = nc + DC[j];
                        if (isInBounds(nnr, nnc) && countAdjacentEmpty(nnr, nnc) == 1) {
                            queue.offer(new int[]{nnr, nnc});
                        }
                    }
                    break; // Original logic breaks after first successful match
                }
            }
        }

        // Verify all empty cells have been resolved
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == EMPTY) {
                    out.println("Not unique");
                    return;
                }
            }
        }

        outputGrid();
    }

    /**
     * Checks if coordinates are within grid boundaries.
     */
    private boolean isInBounds(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /**
     * Counts how many adjacent cells are currently empty ('.').
     */
    private int countAdjacentEmpty(int r, int c) {
        int count = 0;
        for (int i = 0; i < 4; i++) {
            int nr = r + DR[i];
            int nc = c + DC[i];
            if (isInBounds(nr, nc) && grid[nr][nc] == EMPTY) {
                count++;
            }
        }
        return count;
    }

    /**
     * Places directional arrows between two adjacent empty cells.
     * Vertical pairs get '^' (top) and 'v' (bottom).
     * Horizontal pairs get '<' (left) and '>' (right).
     */
    private void placeArrows(int r1, int c1, int r2, int c2) {
        if (c1 == c2) {
            // Same column: vertical alignment
            if (r1 < r2) {
                grid[r1][c1] = DIR_UP;
                grid[r2][c1] = DIR_DOWN;
            } else {
                grid[r2][c1] = DIR_UP;
                grid[r1][c1] = DIR_DOWN;
            }
        } else {
            // Same row: horizontal alignment
            if (c1 < c2) {
                grid[r1][c1] = DIR_LEFT;
                grid[r1][c2] = DIR_RIGHT;
            } else {
                grid[r1][c2] = DIR_LEFT;
                grid[r1][c1] = DIR_RIGHT;
            }
        }
    }

    /**
     * Formats and writes the final grid to the output stream.
     */
    private void outputGrid() {
        for (int r = 0; r < rows; r++) {
            out.println(grid[r]);
        }
    }

    /**
     * Lightweight fast I/O helper for competitive programming style inputs.
     */
    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            String token = next();
            return token == null ? 0 : Integer.parseInt(token);
        }

        boolean hasMoreTokens() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return false;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return true;
        }
    }

    public static void main(String[] args) {
        new GridSolver().solve();
    }
}

import java.util.ArrayDeque;
import java.util.Scanner;

public class GridArrowSolver {
    // Direction vectors for row and column changes
    private static final int[] DR = {0, 0, 1, -1};
    private static final int[] DC = {1, -1, 0, 0};

    // Arrow characters
    private static final char DIR_LEFT = '<';
    private static final char DIR_RIGHT = '>';
    private static final char DIR_UP = '^';
    private static final char DIR_DOWN = 'v';

    private int rows;
    private int cols;
    private char[][] grid;

    public static void main(String[] args) {
        // Use try-with-resources to ensure Scanner is properly closed
        try (Scanner scanner = new Scanner(System.in)) {
            GridArrowSolver solver = new GridArrowSolver();
            if (solver.readInput(scanner)) {
                solver.solve();
                solver.printOutput();
            }
        }
    }

    /**
     * Reads grid dimensions and layout from input.
     */
    private boolean readInput(Scanner scanner) {
        if (!scanner.hasNextInt()) return false;
        rows = scanner.nextInt();
        cols = scanner.nextInt();

        grid = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            String line = scanner.next();
            grid[i] = line.toCharArray();
        }
        return true;
    }

    /**
     * Orchestrates the solving process using a queue-based propagation algorithm.
     */
    private void solve() {
        ArrayDeque<CoordPair> queue = new ArrayDeque<>();
        initializeQueue(queue);

        while (!queue.isEmpty()) {
            CoordPair pair = queue.poll();
            if (pair == null) continue;

            // Only process if both cells are still unassigned
            if (isCellFree(pair.from().row(), pair.from().col()) &&
                isCellFree(pair.to().row(), pair.to().col())) {

                assignArrows(pair.from(), pair.to());
                propagateChanges(pair.from(), pair.to(), queue);
            }
        }
    }

    /**
     * Initial scan to populate the queue with candidate coordinate pairs.
     */
    private void initializeQueue(ArrayDeque<CoordPair> queue) {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (isCellFree(r, c)) {
                    addCandidatePairs(r, c, queue);
                }
            }
        }
    }

    /**
     * Checks if a cell has exactly 3 free neighbors. If so, adds the cell 
     * and one of its free neighbors to the queue.
     */
    private void addCandidatePairs(int r, int c, ArrayDeque<CoordPair> queue) {
        int freeNeighborCount = 0;
        Coord lastFreeNeighbor = null;

        for (int i = 0; i < 4; i++) {
            int nr = r + DR[i];
            int nc = c + DC[i];
            if (isCellFree(nr, nc)) {
                freeNeighborCount++;
                lastFreeNeighbor = new Coord(nr, nc);
            }
        }

        // Original logic: sc starts at 4, decremented for each free neighbor.
        // sc == 3 means exactly 3 neighbors are free.
        if (freeNeighborCount == 3 && lastFreeNeighbor != null) {
            queue.add(new CoordPair(new Coord(r, c), lastFreeNeighbor));
        }
    }

    /**
     * Validates bounds and checks if a cell is unassigned ('.').
     */
    private boolean isCellFree(int r, int c) {
        if (r < 0 || c < 0 || r >= rows || c >= cols) {
            return false;
        }
        return grid[r][c] == '.';
    }

    /**
     * Assigns directional arrows pointing toward each other based on relative positions.
     */
    private void assignArrows(Coord from, Coord to) {
        if (from.row() == to.row()) {
            // Horizontal alignment
            if (from.col() < to.col()) {
                grid[from.row()][from.col()] = DIR_LEFT;
                grid[to.row()][to.col()] = DIR_RIGHT;
            } else {
                grid[to.row()][to.col()] = DIR_LEFT;
                grid[from.row()][from.col()] = DIR_RIGHT;
            }
        } else {
            // Vertical alignment
            if (from.row() < to.row()) {
                grid[from.row()][from.col()] = DIR_UP;
                grid[to.row()][to.col()] = DIR_DOWN;
            } else {
                grid[to.row()][to.col()] = DIR_UP;
                grid[from.row()][from.col()] = DIR_DOWN;
            }
        }
    }

    /**
     * Re-evaluates neighbors of assigned cells to potentially add new pairs to the queue.
     */
    private void propagateChanges(Coord from, Coord to, ArrayDeque<CoordPair> queue) {
        for (int i = 0; i < 4; i++) {
            int nr1 = from.row() + DR[i];
            int nc1 = from.col() + DC[i];
            if (isCellFree(nr1, nc1)) {
                addCandidatePairs(nr1, nc1, queue);
            }

            int nr2 = to.row() + DR[i];
            int nc2 = to.col() + DC[i];
            if (isCellFree(nr2, nc2)) {
                addCandidatePairs(nr2, nc2, queue);
            }
        }
    }

    /**
     * Checks if all cells have been assigned arrows.
     */
    private boolean isSolved() {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '.') {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Prints the final grid or a failure message.
     */
    private void printOutput() {
        if (isSolved()) {
            for (int r = 0; r < rows; r++) {
                System.out.println(new String(grid[r]));
            }
        } else {
            System.out.println("Not unique");
        }
    }

    // Helper records to improve type safety and readability over flat integer queues
    private static record Coord(int row, int col) {}
    private static record CoordPair(Coord from, Coord to) {}
}

import java.io.*;
import java.util.*;

public class Main {
    private static final int[] DX = {1, -1, 0, 0};
    private static final int[] DY = {0, 0, 1, -1};

    private int rows, cols;
    private char[][] grid;
    private int[][] degrees;
    private Queue<int[]> queue;

    public static void main(String[] args) {
        new Main().run();
    }

    public void run() {
        FastScanner scanner = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out);
        try {
            solve(scanner, out);
        } catch (IOException e) {
            out.println("Input error: " + e.getMessage());
        } finally {
            out.flush();
        }
    }

    private void solve(FastScanner scanner, PrintWriter out) throws IOException {
        if (!scanner.hasMoreTokens()) return;

        rows = scanner.nextInt();
        cols = scanner.nextInt();

        grid = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            grid[i] = scanner.next().toCharArray();
        }

        computeInitialDegrees();
        initializeQueue();
        processQueue();
        printResult(out);
    }

    private void computeInitialDegrees() {
        degrees = new int[rows][cols];
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (isValidCell(i, j)) {
                    for (int k = 0; k < 4; k++) {
                        int ni = i + DX[k];
                        int nj = j + DY[k];
                        if (isValidCell(ni, nj)) {
                            degrees[i][j]++;
                        }
                    }
                }
            }
        }
    }

    private void initializeQueue() {
        queue = new ArrayDeque<>();
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (degrees[i][j] == 1) {
                    queue.offer(new int[]{i, j});
                }
            }
        }
    }

    private void processQueue() {
        while (!queue.isEmpty()) {
            int[] current = queue.poll();
            int x = current[0];
            int y = current[1];

            int[] neighbor = findValidNeighbor(x, y);
            if (neighbor == null) continue;

            int nx = neighbor[0];
            int ny = neighbor[1];

            markArrows(x, y, nx, ny);
            processProcessedCell(x, y);
            processProcessedCell(nx, ny);
        }
    }

    private int[] findValidNeighbor(int x, int y) {
        for (int k = 0; k < 4; k++) {
            int nx = x + DX[k];
            int ny = y + DY[k];
            if (isValidCell(nx, ny) && degrees[nx][ny] > 0) {
                return new int[]{nx, ny};
            }
        }
        return null;
    }

    private void markArrows(int x, int y, int nx, int ny) {
        if (x == nx) { // Horizontal alignment
            if (y < ny) {
                grid[x][y] = '<';
                grid[nx][ny] = '>';
            } else {
                grid[x][y] = '>';
                grid[nx][ny] = '<';
            }
        } else { // Vertical alignment
            if (x < nx) {
                grid[x][y] = '^';
                grid[nx][ny] = 'v';
            } else {
                grid[x][y] = 'v';
                grid[nx][ny] = '^';
            }
        }
    }

    private void processProcessedCell(int x, int y) {
        degrees[x][y] = 0;
        for (int k = 0; k < 4; k++) {
            int nx = x + DX[k];
            int ny = y + DY[k];
            if (isValidCell(nx, ny)) {
                degrees[nx][ny]--;
                if (degrees[nx][ny] == 1) {
                    queue.offer(new int[]{nx, ny});
                }
            }
        }
    }

    private boolean isValidCell(int x, int y) {
        return x >= 0 && x < rows && y >= 0 && y < cols && grid[x][y] == '.';
    }

    private void printResult(PrintWriter out) {
        boolean allFilled = true;
        outerLoop:
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == '.') {
                    allFilled = false;
                    break outerLoop;
                }
            }
        }

        if (!allFilled) {
            out.println("Not unique");
        } else {
            for (int i = 0; i < rows; i++) {
                out.println(new String(grid[i]));
            }
        }
    }

    /**
     * Lightweight scanner for competitive programming / fast I/O.
     */
    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        public boolean hasMoreTokens() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return false;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    return false;
                }
            }
            return true;
        }

        public String next() throws IOException {
            if (hasMoreTokens()) return st.nextToken();
            throw new NoSuchElementException("No more tokens available");
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayDeque;
import java.util.Arrays;
import java.util.Deque;
import java.util.StringTokenizer;

public class Main {
    private static final int[][] DIRS = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};
    private static final char[] OTHER_DIR = {'^', 'v', '<', '>'};
    private static final char[] SELF_DIR = {'v', '^', '>', '<'};

    private static int n, m;
    private static char[][] grid;
    private static int[][] num;
    private static boolean possible = true;
    private static final Deque<Pair> stack = new ArrayDeque<>();

    private static BufferedReader reader;
    private static StringTokenizer tokenizer;

    public static void main(String[] args) throws IOException {
        reader = new BufferedReader(new InputStreamReader(System.in));
        tokenizer = new StringTokenizer("");

        n = nextInt();
        m = nextInt();

        // Initialize grid with padding to avoid boundary checks
        grid = new char[n + 2][m + 2];
        for (char[] row : grid) {
            Arrays.fill(row, '*');
        }

        // Read grid data
        for (int i = 1; i <= n; i++) {
            String line = next();
            for (int j = 1; j <= m; j++) {
                grid[i][j] = line.charAt(j - 1);
            }
        }

        // Pre-process grid: count adjacent dots and seed the stack
        num = new int[n + 2][m + 2];
        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= m; j++) {
                if (grid[i][j] == '.') {
                    updatePossible(i, j);
                    if (num[i][j] == 0) {
                        possible = false;
                    } else if (num[i][j] == 1) {
                        stack.push(new Pair(i, j));
                    }
                }
            }
        }

        // Process cells with exactly one adjacent dot
        while (!stack.isEmpty()) {
            Pair p = stack.pop();
            for (int d = 0; d < 4; d++) {
                int tr = p.r + DIRS[d][0];
                int tc = p.c + DIRS[d][1];
                if (grid[tr][tc] == '.') {
                    grid[p.r][p.c] = SELF_DIR[d];
                    grid[tr][tc] = OTHER_DIR[d];
                    updateVicinity(tr, tc);
                    break;
                }
            }
        }

        // Verify that all dots have been resolved
        boolean complete = true;
        outer:
        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= m; j++) {
                if (grid[i][j] == '.') {
                    complete = false;
                    break outer;
                }
            }
        }

        if (!possible || !complete) {
            System.out.println("Not unique");
        } else {
            for (int i = 1; i <= n; i++) {
                System.out.println(new String(grid[i], 1, m));
            }
        }
    }

    /**
     * Updates the neighbor count for a specific cell.
     */
    private static void updatePossible(int r, int c) {
        if (grid[r][c] == '.') {
            int count = 0;
            for (int[] dir : DIRS) {
                if (grid[r + dir[0]][c + dir[1]] == '.') {
                    count++;
                }
            }
            num[r][c] = count;
        } else {
            num[r][c] = 0;
        }
    }

    /**
     * Updates the current cell and its neighbors after a placement.
     */
    private static void updateVicinity(int r, int c) {
        updatePossible(r, c);
        for (int[] dir : DIRS) {
            int tr = r + dir[0];
            int tc = c + dir[1];
            updatePossible(tr, tc);
            if (grid[tr][tc] == '.' && num[tr][tc] == 0) {
                possible = false;
            }
            if (grid[tr][tc] == '.' && num[tr][tc] == 1) {
                stack.push(new Pair(tr, tc));
            }
        }
    }

    /**
     * Reads the next token from input.
     */
    private static String next() throws IOException {
        while (tokenizer == null || !tokenizer.hasMoreTokens()) {
            String line = reader.readLine();
            if (line == null) return null;
            tokenizer = new StringTokenizer(line);
        }
        return tokenizer.nextToken();
    }

    /**
     * Reads the next integer from input.
     */
    private static int nextInt() throws IOException {
        String token = next();
        return token == null ? 0 : Integer.parseInt(token);
    }

    /**
     * Simple value class to represent grid coordinates.
     */
    private static class Pair {
        final int r, c;

        Pair(int r, int c) {
            this.r = r;
            this.c = c;
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.ArrayDeque;
import java.util.Queue;
import java.util.StringTokenizer;

public class DrazilAndTiles {

    // Directions: Down, Left, Up, Right
    private static final int[] DX = {1, 0, -1, 0};
    private static final int[] DY = {0, -1, 0, 1};

    // Arrow mappings: [directionIndex][0] for current cell, [directionIndex][1] for neighbor
    private static final char[][] ARROWS = {
        {'^', 'v'}, // Down
        {'>', '<'}, // Left
        {'v', '^'}, // Up
        {'<', '>'}  // Right
    };

    private int rows, cols;
    private char[][] grid;
    private int[][] degrees;
    private Queue<Cell> queue;
    private int remainingEmpty;

    public static void main(String[] args) throws IOException {
        FastScanner sc = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            DrazilAndTiles solver = new DrazilAndTiles();
            solver.solve(sc, out);
        } finally {
            out.flush();
            out.close();
        }
    }

    /**
     * Solves the grid pairing problem using a topological sort (BFS) approach.
     * Cells with only one valid neighbor are processed first, pairing them up
     * and updating neighbor degrees until all cells are paired or a cycle is detected.
     */
    public void solve(FastScanner sc, PrintWriter out) throws IOException {
        rows = sc.nextInt();
        cols = sc.nextInt();
        grid = new char[rows][cols];
        degrees = new int[rows][cols];
        queue = new ArrayDeque<>();
        remainingEmpty = 0;

        // Initialize grid and compute initial connectivity degrees
        for (int r = 0; r < rows; r++) {
            String line = sc.next();
            grid[r] = line.toCharArray();
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '*') continue;

                int degree = countValidNeighbors(r, c);
                degrees[r][c] = degree;

                if (grid[r][c] == '.') {
                    remainingEmpty++;
                    if (degree == 1) {
                        queue.add(new Cell(r, c));
                    }
                }
            }
        }

        // Process cells with degree 1 using BFS
        processQueue();

        // Determine result based on remaining unpaired cells
        if (remainingEmpty > 0) {
            out.println("Not unique");
        } else {
            for (int r = 0; r < rows; r++) {
                out.println(new String(grid[r]));
            }
        }
    }

    private int countValidNeighbors(int r, int c) {
        int count = 0;
        for (int i = 0; i < 4; i++) {
            int nr = r + DX[i];
            int nc = c + DY[i];
            if (isValid(nr, nc) && grid[nr][nc] != '*') {
                count++;
            }
        }
        return count;
    }

    private boolean isValid(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    private void processQueue() {
        while (!queue.isEmpty()) {
            Cell current = queue.poll();

            for (int i = 0; i < 4; i++) {
                int nr = current.row + DX[i];
                int nc = current.col + DY[i];

                if (isValid(nr, nc) && grid[nr][nc] == '.') {
                    // Pair found: mark both as processed
                    degrees[current.row][current.col] = 0;
                    degrees[nr][nc] = 0;
                    remainingEmpty -= 2;

                    // Update degrees of remaining unprocessed neighbors
                    for (int k = 0; k < 4; k++) {
                        int nnr = nr + DX[k];
                        int nnc = nc + DY[k];
                        if (isValid(nnr, nnc) && grid[nnr][nnc] == '.') {
                            degrees[nnr][nnc]--;
                            if (degrees[nnr][nnc] == 1) {
                                queue.add(new Cell(nnr, nnc));
                            }
                        }
                    }

                    // Assign directional arrows based on movement direction
                    grid[current.row][current.col] = ARROWS[i][0];
                    grid[nr][nc] = ARROWS[i][1];
                    break; // Each cell only forms one pair
                }
            }
        }
    }

    /** Immutable representation of a grid cell */
    private static final class Cell {
        final int row, col;

        Cell(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    /** Fast input reader optimized for competitive programming style I/O */
    private static final class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        String next() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) throw new IOException("Unexpected end of input");
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Solves the arrow grid puzzle by propagating directional constraints.
 * The algorithm identifies cells with exactly three non-empty neighbors,
 * assigns directional arrows, and re-evaluates affected cells until
 * the grid is fully resolved or determined to be non-unique.
 */
public class ArrowGridSolver {

    // Grid state constants
    private static final int EMPTY = 0;
    private static final int OBSTACLE = -1;

    // Direction offsets: Left, Right, Up, Down
    private static final int[] DX = {-1, 1, 0, 0};
    private static final int[] DY = {0, 0, -1, 1};

    // Arrow character representation
    private static final char[] ARROW_CHARS = {'<', '>', '^', 'v'};

    // Mapping from direction index to grid value for the arrow pointing in that direction.
    // Preserves original switch-case logic: 0->3, 1->4, 2->1, 3->2
    private static final int[] DIRECTION_TO_ARROW_VALUE = {3, 4, 1, 2};
    private static final int[] DIRECTION_TO_REVERSE_ARROW_VALUE = {4, 3, 2, 1};

    // I/O components
    private BufferedReader reader;
    private PrintWriter out;
    private StringTokenizer tokenizer;

    /**
     * Entry point for the program.
     */
    public static void main(String[] args) {
        new ArrowGridSolver().run();
    }

    /**
     * Initializes I/O streams and executes the core solution.
     * Uses try-with-resources to guarantee proper stream closure.
     */
    public void run() {
        try (reader = new BufferedReader(new InputStreamReader(System.in));
             out = new PrintWriter(new OutputStreamWriter(System.out))) {
            solve();
        } catch (IOException e) {
            out.println("Error reading input.");
            e.printStackTrace();
        }
    }

    /**
     * Core logic for solving the grid puzzle.
     */
    private void solve() throws IOException {
        int n = nextInt();
        int m = nextInt();

        // Allocate grid with a 1-cell padding for boundary handling
        int[][] grid = new int[n + 2][m + 2];
        initializeBoundaries(grid, n, m);
        loadObstacles(grid, n, m);

        PriorityQueue<Point> constraintQueue = new PriorityQueue<>();
        initializeQueue(grid, n, m, constraintQueue);

        processQueue(grid, constraintQueue);

        if (!isGridFullyFilled(grid, n, m)) {
            out.println("Not unique");
        } else {
            printGrid(grid, n, m);
        }
    }

    // ==================== Grid Management ====================

    private void initializeBoundaries(int[][] grid, int n, int m) {
        for (int i = 0; i <= n; i++) {
            grid[i][0] = OBSTACLE;
            grid[i][m + 1] = OBSTACLE;
        }
        for (int i = 0; i <= m; i++) {
            grid[0][i] = OBSTACLE;
            grid[n + 1][i] = OBSTACLE;
        }
    }

    private void loadObstacles(int[][] grid, int n, int m) throws IOException {
        for (int i = 0; i < n; i++) {
            String row = nextToken();
            for (int j = 0; j < m; j++) {
                if (row.charAt(j) == '*') {
                    grid[i + 1][j + 1] = OBSTACLE;
                }
            }
        }
    }

    private boolean hasExactlyThreeNonEmptyNeighbors(Point p, int[][] grid) {
        int count = 0;
        for (int i = 0; i < 4; i++) {
            if (grid[p.x + DX[i]][p.y + DY[i]] != EMPTY) {
                count++;
            }
        }
        return count == 3;
    }

    private void enqueuePotentialCells(Point p, int[][] grid, PriorityQueue<Point> pq) {
        for (int i = 0; i < 4; i++) {
            int nx = p.x + DX[i];
            int ny = p.y + DY[i];
            if (grid[nx][ny] == EMPTY && hasExactlyThreeNonEmptyNeighbors(new Point(nx, ny), grid)) {
                pq.add(new Point(nx, ny));
            }
        }
    }

    private void initializeQueue(int[][] grid, int n, int m, PriorityQueue<Point> pq) {
        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= m; j++) {
                if (grid[i][j] == EMPTY && hasExactlyThreeNonEmptyNeighbors(new Point(i, j), grid)) {
                    pq.add(new Point(i, j));
                }
            }
        }
    }

    // ==================== Processing Logic ====================

    private void processQueue(int[][] grid, PriorityQueue<Point> pq) {
        while (!pq.isEmpty()) {
            Point current = pq.poll();
            if (grid[current.x][current.y] != EMPTY) continue;

            for (int i = 0; i < 4; i++) {
                int nx = current.x + DX[i];
                int ny = current.y + DY[i];
                if (grid[nx][ny] == EMPTY) {
                    grid[nx][ny] = DIRECTION_TO_ARROW_VALUE[i];
                    grid[current.x][current.y] = DIRECTION_TO_REVERSE_ARROW_VALUE[i];

                    enqueuePotentialCells(new Point(nx, ny), grid, pq);
                    enqueuePotentialCells(current, grid, pq);
                    break;
                }
            }
        }
    }

    private boolean isGridFullyFilled(int[][] grid, int n, int m) {
        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= m; j++) {
                if (grid[i][j] == EMPTY) return false;
            }
        }
        return true;
    }

    private void printGrid(int[][] grid, int n, int m) {
        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= m; j++) {
                int val = grid[i][j];
                if (val == OBSTACLE) {
                    out.print('*');
                } else {
                    out.print(ARROW_CHARS[val - 1]);
                }
            }
            out.println();
        }
    }

    // ==================== I/O Utilities ====================

    private String nextToken() throws IOException {
        while (tokenizer == null || !tokenizer.hasMoreTokens()) {
            String line = reader.readLine();
            if (line == null) throw new EOFException("Unexpected end of input");
            tokenizer = new StringTokenizer(line);
        }
        return tokenizer.nextToken();
    }

    private int nextInt() throws IOException {
        return Integer.parseInt(nextToken());
    }

    private long nextLong() throws IOException {
        return Long.parseLong(nextToken());
    }

    private double nextDouble() throws IOException {
        return Double.parseDouble(nextToken());
    }

    // ==================== Data Structures ====================

    /**
     * Represents a coordinate on the grid.
     * Made static to avoid implicit reference to outer class instance.
     */
    public static class Point implements Comparable<Point> {
        final int x, y;

        public Point(int x, int y) {
            this.x = x;
            this.y = y;
        }

        @Override
        public int compareTo(Point other) {
            if (this.x != other.x) return this.y - other.y;
            return this.x - other.x;
        }
    }
}

import java.util.LinkedList;
import java.util.Queue;
import java.util.Scanner;

/**
 * Solution class for processing grid tiles.
 */
public class Solution {
    // Direction vectors: Up, Down, Left, Right
    private static final int[] DR = {-1, 1, 0, 0};
    private static final int[] DC = {0, 0, -1, 1};
    // Corresponding characters for directions
    private static final char[] ARROWS = {'^', 'v', '<', '>'};

    /**
     * Represents a coordinate on the grid.
     */
    private static class Point {
        int r, c;

        Point(int r, int c) {
            this.r = r;
            this.c = c;
        }
    }

    public static void main(String[] args) {
        new Solution().drazilTiles();
    }

    /**
     * Entry point for the solution. Handles input reading and invokes the solver.
     */
    public void drazilTiles() {
        Scanner scanner = new Scanner(System.in);
        if (!scanner.hasNextInt()) return;

        int rows = scanner.nextInt();
        int cols = scanner.nextInt();
        char[][] board = new char[rows][cols];

        for (int i = 0; i < rows; i++) {
            // next() automatically skips whitespace and reads the token
            board[i] = scanner.next().toCharArray();
        }
        scanner.close();

        solve(board);
    }

    /**
     * Core logic to process the board and resolve tile directions.
     */
    private void solve(char[][] board) {
        Queue<Point> terminals = new LinkedList<>();

        // 1. Identify initial terminal cells
        // A terminal is an empty cell ('.') with exactly one adjacent empty cell.
        for (int r = 0; r < board.length; r++) {
            for (int c = 0; c < board[r].length; c++) {
                if (isTerminal(board, r, c)) {
                    terminals.add(new Point(r, c));
                }
            }
        }

        // 2. Process terminals in a queue
        while (!terminals.isEmpty()) {
            Point p = terminals.poll();
            int directionIndex = getDirection(board, p.r, p.c);

            if (directionIndex != -1) {
                // Update current cell to point in the direction
                board[p.r][p.c] = ARROWS[directionIndex];

                // Update neighbor cell to point back (opposite direction)
                int nr = p.r + DR[directionIndex];
                int nc = p.c + DC[directionIndex];
                board[nr][nc] = ARROWS[(directionIndex + 2) % 4];

                // Check neighbors of the modified cells to see if they became terminals.
                // We check both the current cell and the neighbor because the state change
                // might affect the neighbor count of their neighbors.
                addPotentialTerminals(terminals, board, p.r, p.c);
                addPotentialTerminals(terminals, board, nr, nc);
            }
        }

        // 3. Validation: Check if any empty cells remain
        if (hasEmptyCells(board)) {
            System.out.println("Not unique");
        } else {
            printBoard(board);
        }
    }

    /**
     * Checks neighbors of (r, c) and adds any new terminals to the queue.
     */
    private void addPotentialTerminals(Queue<Point> queue, char[][] board, int r, int c) {
        for (int k = 0; k < 4; k++) {
            int nr = r + DR[k];
            int nc = c + DC[k];
            if (isOnBoard(board, nr, nc)) {
                if (isTerminal(board, nr, nc)) {
                    queue.add(new Point(nr, nc));
                }
            }
        }
    }

    /**
     * Finds the direction index of an adjacent empty cell ('.').
     * Returns -1 if no such cell exists.
     */
    private int getDirection(char[][] board, int r, int c) {
        for (int k = 0; k < 4; k++) {
            int nr = r + DR[k];
            int nc = c + DC[k];
            if (isOnBoard(board, nr, nc) && board[nr][nc] == '.') {
                return k;
            }
        }
        return -1;
    }

    /**
     * Checks if a cell is a terminal.
     * A terminal is an empty cell ('.') with exactly one adjacent empty cell.
     */
    private boolean isTerminal(char[][] board, int r, int c) {
        if (!isOnBoard(board, r, c) || board[r][c] != '.') {
            return false;
        }
        int count = 0;
        for (int k = 0; k < 4; k++) {
            int nr = r + DR[k];
            int nc = c + DC[k];
            if (isOnBoard(board, nr, nc) && board[nr][nc] == '.') {
                count++;
            }
        }
        return count == 1;
    }

    private boolean isOnBoard(char[][] board, int r, int c) {
        return r >= 0 && r < board.length && c >= 0 && c < board[r].length;
    }

    private boolean hasEmptyCells(char[][] board) {
        for (char[] row : board) {
            for (char cell : row) {
                if (cell == '.') {
                    return true;
                }
            }
        }
        return false;
    }

    private void printBoard(char[][] board) {
        for (char[] row : board) {
            System.out.println(new String(row));
        }
    }
}

import java.util.Deque;
import java.util.ArrayDeque;
import java.io.*;
import java.util.InputMismatchException;

/**
 * Entry point for the competitive programming solution.
 * Sets up fast I/O and delegates solving to TaskD.
 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        OutputWriter out = new OutputWriter(outputStream);

        TaskD solver = new TaskD();
        solver.solve(1, in, out);
        out.close();
    }
}

/**
 * Core solver for the grid direction assignment problem.
 * Uses a BFS approach to propagate directional constraints from 
 * cells with exactly one empty neighbor until the grid is fully resolved.
 */
class TaskD {
    // Grid constants
    private static final char EMPTY_CELL = '.';
    private static final char DIR_UP = '^';
    private static final char DIR_DOWN = 'v';
    private static final char DIR_RIGHT = '>';
    private static final char DIR_LEFT = '<';
    private static final String RESULT_NOT_UNIQUE = "Not unique";

    // Direction vectors for 4-connectivity
    private static final int[] DX4 = {1, 0, -1, 0};
    private static final int[] DY4 = {0, -1, 0, 1};

    /**
     * Solves the problem for a single test case.
     *
     * @param testNumber Identifier for the test case (unused in logic)
     * @param in         Fast input reader
     * @param out        Fast output writer
     */
    public void solve(int testNumber, InputReader in, OutputWriter out) {
        int n = in.readInt();
        int m = in.readInt();
        char[][] table = IOUtils.readTable(in, n, m);
        Deque<IntPair> processingQueue = new ArrayDeque<>();

        // Phase 1: Initial scan to identify seed cells
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (table[i][j] == EMPTY_CELL) {
                    int adjacentEmptyCount = countAdjacentEmptyCells(i, j, table);
                    if (adjacentEmptyCount == 0) {
                        out.printLine(RESULT_NOT_UNIQUE);
                        return;
                    }
                    if (adjacentEmptyCount == 1) {
                        processingQueue.add(new IntPair(i, j));
                    }
                }
            }
        }

        // Phase 2: BFS propagation
        while (!processingQueue.isEmpty()) {
            IntPair current = processingQueue.pollFirst();
            // Skip if already processed/filled
            if (table[current.first][current.second] != EMPTY_CELL) {
                continue;
            }

            if (!assignDirectionsAndPropagate(current, table, processingQueue)) {
                out.printLine(RESULT_NOT_UNIQUE);
                return;
            }
        }

        // Phase 3: Verify all cells are filled
        for (char[] row : table) {
            for (char cell : row) {
                if (cell == EMPTY_CELL) {
                    out.printLine(RESULT_NOT_UNIQUE);
                    return;
                }
            }
        }

        IOUtils.printTable(out, table);
    }

    /**
     * Counts how many adjacent cells are still empty.
     */
    private int countAdjacentEmptyCells(int x, int y, char[][] grid) {
        int count = 0;
        for (int i = 0; i < 4; i++) {
            int nx = x + DX4[i];
            int ny = y + DY4[i];
            if (MiscUtils.isValidCell(nx, ny, grid) && grid[nx][ny] == EMPTY_CELL) {
                count++;
            }
        }
        return count;
    }

    /**
     * Assigns directional arrows between the current cell and its empty neighbor,
     * then propagates constraints to the neighbor's other empty neighbors.
     */
    private boolean assignDirectionsAndPropagate(IntPair current, char[][] grid, Deque<IntPair> queue) {
        int x = current.first;
        int y = current.second;
        IntPair emptyNeighbor = null;

        // Assign directions to the empty neighbor
        for (int i = 0; i < 4; i++) {
            int nx = x + DX4[i];
            int ny = y + DY4[i];
            if (MiscUtils.isValidCell(nx, ny, grid) && grid[nx][ny] == EMPTY_CELL) {
                assignDirectionPair(x, y, nx, ny, grid);
                emptyNeighbor = new IntPair(nx, ny);
            }
        }

        // If no empty neighbor was found, the state is invalid for this path
        if (emptyNeighbor == null) {
            return false;
        }

        // Propagate to the empty neighbor's other neighbors
        for (int i = 0; i < 4; i++) {
            int nx = emptyNeighbor.first + DX4[i];
            int ny = emptyNeighbor.second + DY4[i];
            if (MiscUtils.isValidCell(nx, ny, grid) && grid[nx][ny] == EMPTY_CELL && (nx != x || ny != y)) {
                int adjCount = countAdjacentEmptyCells(nx, ny, grid);
                if (adjCount == 0) {
                    return false; // Dead end detected
                }
                if (adjCount == 1) {
                    queue.add(new IntPair(nx, ny));
                }
            }
        }
        return true;
    }

    /**
     * Sets directional arrows between two adjacent cells based on their relative positions.
     */
    private void assignDirectionPair(int x1, int y1, int x2, int y2, char[][] grid) {
        if (x2 < x1) {
            grid[x1][y1] = DIR_DOWN;
            grid[x2][y2] = DIR_UP;
        } else if (x2 > x1) {
            grid[x1][y1] = DIR_UP;
            grid[x2][y2] = DIR_DOWN;
        } else if (y2 < y1) {
            grid[x1][y1] = DIR_RIGHT;
            grid[x2][y2] = DIR_LEFT;
        } else {
            grid[x1][y1] = DIR_LEFT;
            grid[x2][y2] = DIR_RIGHT;
        }
    }
}

/**
 * Immutable pair representing grid coordinates.
 */
class IntPair {
    public final int first, second;

    public IntPair(int first, int second) {
        this.first = first;
        this.second = second;
    }

    @Override
    public String toString() {
        return "(" + first + "," + second + ")";
    }

    @Override
    public boolean equals(Object o) {
        if (this == o) return true;
        if (o == null || getClass() != o.getClass()) return false;
        IntPair intPair = (IntPair) o;
        return first == intPair.first && second == intPair.second;
    }

    @Override
    public int hashCode() {
        int result = first;
        result = 31 * result + second;
        return result;
    }
}

/**
 * Fast input reader for competitive programming.
 */
class InputReader {
    private final InputStream stream;
    private final byte[] buf = new byte[1024];
    private int curChar;
    private int numChars;
    private SpaceCharFilter filter;

    public InputReader(InputStream stream) {
        this.stream = stream;
    }

    public int read() {
        if (numChars == -1) {
            throw new InputMismatchException();
        }
        if (curChar >= numChars) {
            curChar = 0;
            try {
                numChars = stream.read(buf);
            } catch (IOException e) {
                throw new InputMismatchException();
            }
            if (numChars <= 0) {
                return -1;
            }
        }
        return buf[curChar++];
    }

    public int readInt() {
        int c = read();
        while (isSpaceChar(c)) {
            c = read();
        }
        int sgn = 1;
        if (c == '-') {
            sgn = -1;
            c = read();
        }
        int res = 0;
        do {
            if (c < '0' || c > '9') {
                throw new InputMismatchException();
            }
            res *= 10;
            res += c - '0';
            c = read();
        } while (!isSpaceChar(c));
        return res * sgn;
    }

    public boolean isSpaceChar(int c) {
        return filter != null ? filter.isSpaceChar(c) : isWhitespace(c);
    }

    public static boolean isWhitespace(int c) {
        return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
    }

    public char readCharacter() {
        int c = read();
        while (isSpaceChar(c)) {
            c = read();
        }
        return (char) c;
    }

    @FunctionalInterface
    public interface SpaceCharFilter {
        boolean isSpaceChar(int ch);
    }
}

/**
 * Fast output writer for competitive programming.
 */
class OutputWriter {
    private final PrintWriter writer;

    public OutputWriter(OutputStream outputStream) {
        writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(outputStream)));
    }

    public void print(Object... objects) {
        for (int i = 0; i < objects.length; i++) {
            if (i != 0) {
                writer.print(' ');
            }
            writer.print(objects[i]);
        }
    }

    public void printLine(Object... objects) {
        print(objects);
        writer.println();
    }

    public void close() {
        writer.close();
    }
}

/**
 * Utility methods for reading and writing 2D character grids.
 */
class IOUtils {
    public static char[] readCharArray(InputReader in, int size) {
        char[] array = new char[size];
        for (int i = 0; i < size; i++) {
            array[i] = in.readCharacter();
        }
        return array;
    }

    public static char[][] readTable(InputReader in, int rowCount, int columnCount) {
        char[][] table = new char[rowCount][];
        for (int i = 0; i < rowCount; i++) {
            table[i] = readCharArray(in, columnCount);
        }
        return table;
    }

    public static void printTable(OutputWriter out, char[][] table) {
        for (char[] row : table) {
            out.printLine(new String(row));
        }
    }
}

/**
 * Miscellaneous grid utilities.
 */
class MiscUtils {
