        return row >= 0 && row < grid.length && column >= 0 && column < grid[0].length;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.OutputStream;
import java.io.PrintWriter;
import java.util.ArrayDeque;
import java.util.Queue;
import java.util.StringTokenizer;

/**
 * Solves the grid arrow propagation problem.
 * Iteratively fills empty cells with directional arrows based on neighbor constraints.
 */
public class D515 {

    // Direction vectors: Left, Down, Right, Up
    private static final int[] DX = {-1, 0, 1, 0};
    private static final int[] DY = {0, 1, 0, -1};
    private static final char[] DIRECTIONS = {'<', 'v', '>', '^'};

    public static void main(String[] args) {
        InputReader in = new InputReader(System.in);
        PrintWriter out = new PrintWriter(System.out);
        new D515().solve(in, out);
        out.close();
    }

    /**
     * Entry point for solving a single test case.
     */
    public void solve(InputReader in, PrintWriter out) {
        int n = in.nextInt();
        int m = in.nextInt();
        char[][] grid = new char[n][m];

        for (int i = 0; i < n; i++) {
            grid[i] = in.next().toCharArray();
        }

        boolean isUnique = processGrid(grid, n, m);

        if (!isUnique) {
            out.println("Not unique");
        } else {
            for (char[] row : grid) {
                out.println(row);
            }
        }
    }

    /**
     * Processes the grid to fill empty cells with directional arrows.
     * Uses an iterative BFS approach to avoid potential StackOverflowError
     * and improve maintainability over the original recursive implementation.
     *
     * @return true if all empty cells were successfully filled, false otherwise.
     */
    private boolean processGrid(char[][] grid, int n, int m) {
        Queue<int[]> queue = new ArrayDeque<>();

        // Initialize queue with all empty cells
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == '.') {
                    queue.offer(new int[]{i, j});
                }
            }
        }

        while (!queue.isEmpty()) {
            int[] current = queue.poll();
            int y = current[0];
            int x = current[1];

            // Skip if already processed/filled
            if (grid[y][x] != '.') {
                continue;
            }

            int[] neighbor = findSingleEmptyNeighbor(grid, y, x, n, m);
            if (neighbor != null) {
                fillArrows(grid, y, x, neighbor[0], neighbor[1]);

                // Add newly filled cell's empty neighbors to the queue for further processing
                for (int d = 0; d < 4; d++) {
                    int ny = neighbor[0] + DY[d];
                    int nx = neighbor[1] + DX[d];
                    if (ny >= 0 && ny < n && nx >= 0 && nx < m && grid[ny][nx] == '.') {
                        queue.offer(new int[]{ny, nx});
                    }
                }
            }
        }

        // Verify if any empty cell remains
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == '.') {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Finds the single adjacent empty cell if exactly one exists.
     *
     * @return int[] {y, x} of the neighbor, or null if count != 1
     */
    private int[] findSingleEmptyNeighbor(char[][] grid, int y, int x, int n, int m) {
        int count = 0;
        int dir = -1;
        for (int d = 0; d < 4; d++) {
            int ny = y + DY[d];
            int nx = x + DX[d];
            if (ny >= 0 && ny < n && nx >= 0 && nx < m && grid[ny][nx] == '.') {
                count++;
                dir = d;
            }
        }
        return count == 1 ? new int[]{y + DY[dir], x + DX[dir]} : null;
    }

    /**
     * Fills two adjacent cells with directional arrows.
     * Preserves the exact logic and direction mapping of the original implementation.
     */
    private void fillArrows(char[][] grid, int y1, int x1, int y2, int x2) {
        int dirToNeighbor = getDirectionIndex(y1, x1, y2, x2);
        int dirOpposite = (dirToNeighbor + 2) % 4;

        grid[y2][x2] = DIRECTIONS[dirToNeighbor];
        grid[y1][x1] = DIRECTIONS[dirOpposite];
    }

    /**
     * Determines the direction index from (y1, x1) to (y2, x2).
     */
    private int getDirectionIndex(int y1, int x1, int y2, int x2) {
        for (int d = 0; d < 4; d++) {
            if (y1 + DY[d] == y2 && x1 + DX[d] == x2) {
                return d;
            }
        }
        throw new IllegalStateException("Invalid coordinates: no valid direction found.");
    }

    /**
     * Fast I/O helper class for competitive programming style inputs.
     */
    public static class InputReader {
        public BufferedReader reader;
        public StringTokenizer tokenizer;

        public InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input", e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            String s = next();
            return s == null ? 0 : Integer.parseInt(s);
        }

        public long nextLong() {
            String s = next();
            return s == null ? 0L : Long.parseLong(s);
        }

        public double nextDouble() {
            String s = next();
            return s == null ? 0.0 : Double.parseDouble(s);
        }
    }
}

import java.util.ArrayDeque;
import java.util.Deque;
import java.util.Scanner;

public class DrazilAndTiles {
    // Direction vectors for Up, Down, Left, Right
    private static final int[] DX = {-1, 1, 0, 0};
    private static final int[] DY = {0, 0, -1, 1};

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        if (!scanner.hasNextInt()) return;

        int n = scanner.nextInt();
        int m = scanner.nextInt();

        char[][] grid = new char[n][m];
        for (int i = 0; i < n; i++) {
            grid[i] = scanner.next().toCharArray();
        }

        solve(grid, n, m);
    }

    /**
     * Core algorithm to fill the grid with directional arrows.
     * Uses a topological sort approach on the grid graph.
     */
    private static void solve(char[][] grid, int n, int m) {
        // Explicitly track in-degrees for O(1) updates instead of recalculating repeatedly
        int[][] inDegree = new int[n][m];
        Deque<Point> queue = new ArrayDeque<>();

        // Initialize in-degrees and populate queue with initial degree-1 cells
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == '.') {
                    int degree = 0;
                    for (int k = 0; k < 4; k++) {
                        int ni = i + DX[k];
                        int nj = j + DY[k];
                        if (isValid(ni, nj, n, m) && grid[ni][nj] == '.') {
                            degree++;
                        }
                    }
                    inDegree[i][j] = degree;
                    if (degree == 1) {
                        queue.add(new Point(i, j));
                    }
                }
            }
        }

        // Process cells using a topological sort approach
        while (!queue.isEmpty()) {
            Point p1 = queue.poll();
            Point p2 = findEmptyNeighbor(p1, grid, n, m);

            // If no empty neighbor exists or neighbor is already filled, solution is not unique
            if (p2 == null || grid[p2.y][p2.x] != '.') {
                System.out.println("Not unique");
                return;
            }

            assignDirection(grid, p1, p2);

            // Update degrees of p2's neighbors
            for (int k = 0; k < 4; k++) {
                int ni = p2.y + DX[k];
                int nj = p2.x + DY[k];
                if (isValid(ni, nj, n, m) && grid[ni][nj] == '.') {
                    inDegree[ni][nj]--;
                    if (inDegree[ni][nj] == 1) {
                        queue.add(new Point(ni, nj));
                    }
                }
            }
        }

        // If any '.' remains, the grid cannot be uniquely filled
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == '.') {
                    System.out.println("Not unique");
                    return;
                }
            }
        }

        // Output the successfully filled grid
        for (char[] row : grid) {
            System.out.println(new String(row));
        }
    }

    /**
     * Finds the single '.' neighbor of a given point.
     */
    private static Point findEmptyNeighbor(Point p, char[][] grid, int n, int m) {
        for (int k = 0; k < 4; k++) {
            int ni = p.y + DX[k];
            int nj = p.x + DY[k];
            if (isValid(ni, nj, n, m) && grid[ni][nj] == '.') {
                return new Point(ni, nj);
            }
        }
        return null;
    }

    /**
     * Assigns directional arrows between two adjacent cells based on their relative positions.
     */
    private static void assignDirection(char[][] grid, Point p1, Point p2) {
        if (p2.x > p1.x) {
            grid[p1.y][p1.x] = '<';
            grid[p2.y][p2.x] = '>';
        } else if (p2.x < p1.x) {
            grid[p1.y][p1.x] = '>';
            grid[p2.y][p2.x] = '<';
        } else if (p2.y < p1.y) {
            grid[p1.y][p1.x] = 'v';
            grid[p2.y][p2.x] = '^';
        } else {
            grid[p1.y][p1.x] = '^';
            grid[p2.y][p2.x] = 'v';
        }
    }

    /**
     * Checks if coordinates are within grid boundaries.
     */
    private static boolean isValid(int r, int c, int n, int m) {
        return r >= 0 && r < n && c >= 0 && c < m;
    }

    /**
     * Simple immutable class to represent grid coordinates.
     */
    private static class Point {
        final int y, x;
        Point(int y, int x) {
            this.y = y;
            this.x = x;
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.ArrayDeque;
import java.util.Queue;
import java.util.StringTokenizer;

public class DrazilAndTiles {

    // Direction vectors: Down, Up, Right, Left
    private static final int[] DR = {1, -1, 0, 0};
    private static final int[] DC = {0, 0, 1, -1};

    // Corresponding tile characters: [current_cell, neighbor_cell]
    private static final char[][] TILE_CHARS = {
        {'^', 'v'}, // Down
        {'v', '^'}, // Up
        {'<', '>'}, // Right
        {'>', '<'}  // Left
    };

    public static void main(String[] args) {
        FastScanner sc = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out);
        try {
            solve(sc, out);
        } finally {
            out.flush();
        }
    }

    private static void solve(FastScanner sc, PrintWriter out) {
        int n = sc.nextInt();
        int m = sc.nextInt();
        char[][] grid = new char[n][m];

        for (int i = 0; i < n; i++) {
            String line = sc.next();
            grid[i] = line.toCharArray();
        }

        int[][] degree = new int[n][m];
        Queue<Integer> queue = new ArrayDeque<>();

        // Initialize degrees and seed the queue with boundary cells (degree == 1)
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == '*') continue;

                int deg = 0;
                for (int d = 0; d < 4; d++) {
                    int nr = i + DR[d];
                    int nc = j + DC[d];
                    if (isValid(nr, nc, n, m) && grid[nr][nc] == '.') {
                        deg++;
                    }
                }
                degree[i][j] = deg;
                if (deg == 1) {
                    queue.offer(i * m + j);
                }
            }
        }

        // Process cells in topological order (Kahn's algorithm variant)
        while (!queue.isEmpty()) {
            int idx = queue.poll();
            int r = idx / m;
            int c = idx % m;

            // Skip if already processed (defensive check)
            if (grid[r][c] != '.') continue;

            // Find the single available '.' neighbor
            int neighborR = -1, neighborC = -1;
            int dirIdx = -1;
            for (int d = 0; d < 4; d++) {
                int nr = r + DR[d];
                int nc = c + DC[d];
                if (isValid(nr, nc, n, m) && grid[nr][nc] == '.') {
                    neighborR = nr;
                    neighborC = nc;
                    dirIdx = d;
                    break;
                }
            }

            // If no valid neighbor found, this cell is isolated or already handled
            if (neighborR == -1) continue;

            // Place the tiles
            grid[r][c] = TILE_CHARS[dirIdx][0];
            grid[neighborR][neighborC] = TILE_CHARS[dirIdx][1];

            // Update degrees for neighbors of the newly filled cell
            for (int d = 0; d < 4; d++) {
                int nr = neighborR + DR[d];
                int nc = neighborC + DC[d];
                if (isValid(nr, nc, n, m) && grid[nr][nc] == '.') {
                    degree[nr][nc]--;
                    if (degree[nr][nc] == 1) {
                        queue.offer(nr * m + nc);
                    }
                }
            }
        }

        // Check if any '.' cells remain (indicates non-unique or impossible solution)
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == '.') {
                    out.println("Not unique");
                    return;
                }
            }
        }

        // Output the solved grid
        for (int i = 0; i < n; i++) {
            out.println(grid[i]);
        }
    }

    private static boolean isValid(int r, int c, int n, int m) {
        return r >= 0 && r < n && c >= 0 && c < m;
    }

    /**
     * Fast I/O helper class optimized for competitive programming and large inputs.
     */
    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input", e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.ArrayDeque;
import java.util.Arrays;
import java.util.StringTokenizer;

public class B {
    private final PrintWriter writer = new PrintWriter(System.out);

    public static void main(String[] args) throws IOException {
        new B().solve();
    }

    void solve() throws IOException {
        FastScanner scanner = new FastScanner();
        int n = scanner.nextInt();
        int m = scanner.nextInt();

        // Grid with padding to avoid boundary checks
        char[][] grid = new char[n + 2][m + 2];
        for (char[] row : grid) {
            Arrays.fill(row, '*');
        }

        for (int i = 1; i <= n; i++) {
            String line = scanner.next();
            System.arraycopy(line.toCharArray(), 0, grid[i], 1, m);
        }

        // Initialize queue with boundary cells (<= 1 neighbor)
        ArrayDeque<int[]> queue = new ArrayDeque<>();
        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= m; j++) {
                if (grid[i][j] == '.' && countNeighbors(grid, i, j) <= 1) {
                    queue.add(new int[]{i, j});
                }
            }
        }

        boolean isPossible = true;
        while (!queue.isEmpty()) {
            int[] cell = queue.poll();
            int r = cell[0];
            int c = cell[1];

            // Skip already processed cells
            if (grid[r][c] != '.') {
                continue;
            }

            // Find the only remaining '.' neighbor
            int nextR = -1;
            int nextC = -1;
            int dirIdx = -1;

            for (int k = 0; k < 4; k++) {
                int nr = r + DR[k];
                int nc = c + DC[k];
                if (grid[nr][nc] == '.') {
                    nextR = nr;
                    nextC = nc;
                    dirIdx = k;
                    break;
                }
            }

            // If no '.' neighbor exists, configuration is invalid
            if (nextR == -1) {
                isPossible = false;
                break;
            }

            // Assign opposite directions
            grid[r][c] = DIR_CHARS[dirIdx];
            grid[nextR][nextC] = OPPOSITE_DIR_CHARS[dirIdx];

            // Check if neighbors of the newly assigned cell should be added to queue
            for (int k = 0; k < 4; k++) {
                int nr = nextR + DR[k];
                int nc = nextC + DC[k];
                if (grid[nr][nc] == '.' && countNeighbors(grid, nr, nc) <= 1) {
                    queue.add(new int[]{nr, nc});
                }
            }
        }

        // Verify all '.' cells have been assigned
        for (int i = 1; i <= n && isPossible; i++) {
            for (int j = 1; j <= m; j++) {
                if (grid[i][j] == '.') {
                    isPossible = false;
                    break;
                }
            }
        }

        if (!isPossible) {
            writer.println("Not unique");
        } else {
            for (int i = 1; i <= n; i++) {
                writer.println(new String(grid[i], 1, m));
            }
        }

        writer.flush();
    }

    // Direction vectors and character mappings
    private static final int[] DR = {-1, 0, 1, 0};
    private static final int[] DC = {0, 1, 0, -1};
    private static final char[] DIR_CHARS = {'v', '<', '^', '>'};
    private static final char[] OPPOSITE_DIR_CHARS = {'^', '>', 'v', '<'};

    // Counts the number of '.' neighbors for a given cell
    private static int countNeighbors(char[][] grid, int r, int c) {
        int count = 0;
        for (int k = 0; k < 4; k++) {
            if (grid[r + DR[k]][c + DC[k]] == '.') {
                count++;
            }
        }
        return count;
    }

    // Fast I/O helper to handle tokenized input efficiently
    private static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            String token = next();
            if (token == null) throw new RuntimeException("Unexpected end of input");
            return Integer.parseInt(token);
        }
    }
}

import java.util.ArrayDeque;
import java.util.Deque;
import java.util.Scanner;

public class Main {
    // Constants representing cell states
    private static final byte STATE_EMPTY = 0;
    private static final byte STATE_BLOCKED = 1;
    private static final byte STATE_RIGHT = 6;
    private static final byte STATE_LEFT = 7;
    private static final byte STATE_DOWN = 8;
    private static final byte STATE_UP = 9;

    public static void main(String[] args) {
        new Main().solve();
    }

    public void solve() {
        Parser parser = new Parser();
        int n = parser.nextInt();
        int m = parser.nextInt();
        parser.nextLine(); // Consume newline after m

        Grid grid = new Grid(n, m);
        Deque<int[]> retryStack = new ArrayDeque<>();
        boolean[] failed = {false};

        // 1. Parse input and place blocked cells
        for (int i = 0; i < n; i++) {
            String line = parser.nextLine();
            for (int j = 0; j < m; j++) {
                if (line.charAt(j) == '*') {
                    grid.set(i, j, STATE_BLOCKED);
                }
            }
        }

        // 2. Pad grid with walls
        for (int i = 0; i < n; i++) {
            grid.set(i, -1, STATE_BLOCKED);
            grid.set(i, m, STATE_BLOCKED);
        }
        for (int j = 0; j < m; j++) {
            grid.set(-1, j, STATE_BLOCKED);
            grid.set(n, j, STATE_BLOCKED);
        }

        // 3. Initial constraint propagation
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                attemptPlacement(grid, i, j, retryStack, failed);
            }
        }

        // 4. Process retry stack
        while (!retryStack.isEmpty() && !failed[0]) {
            int[] pos = retryStack.pop();
            attemptPlacement(grid, pos[0], pos[1], retryStack, failed);
        }

        // 5. Verify solution completeness
        boolean solved = !failed[0];
        if (solved) {
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    if (grid.get(i, j) == STATE_EMPTY) {
                        solved = false;
                        break;
                    }
                }
                if (!solved) break;
            }
        }

        if (!solved) {
            System.out.println("Not unique");
            return;
        }

        // 6. Format and print output
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                sb.append(stateToChar(grid.get(i, j)));
            }
            sb.append('\n');
        }
        System.out.print(sb);
    }

    private void attemptPlacement(Grid grid, int i, int j, Deque<int[]> retryStack, boolean[] failed) {
        if (grid.get(i, j) != STATE_EMPTY) return;

        int emptyNeighbors = countNeighbors(grid, i, j, STATE_EMPTY);
        if (emptyNeighbors > 1) return;
        if (emptyNeighbors == 0) {
            failed[0] = true;
            return;
        }

        // Try placing arrows in each direction if the neighbor is empty
        if (grid.get(i - 1, j) == STATE_EMPTY) {
            grid.set(i - 1, j, STATE_UP);
            grid.set(i, j, STATE_DOWN);
            pushRetry(grid, retryStack, i - 2, j);
            pushRetry(grid, retryStack, i - 1, j - 1);
            pushRetry(grid, retryStack, i - 1, j + 1);
        }
        if (grid.get(i + 1, j) == STATE_EMPTY) {
            grid.set(i, j, STATE_UP);
            grid.set(i + 1, j, STATE_DOWN);
            pushRetry(grid, retryStack, i + 2, j);
            pushRetry(grid, retryStack, i + 1, j + 1);
            pushRetry(grid, retryStack, i + 1, j - 1);
        }
        if (grid.get(i, j - 1) == STATE_EMPTY) {
            grid.set(i, j - 1, STATE_LEFT);
            grid.set(i, j, STATE_RIGHT);
            pushRetry(grid, retryStack, i, j - 2);
            pushRetry(grid, retryStack, i - 1, j - 1);
            pushRetry(grid, retryStack, i + 1, j - 1);
        }
        if (grid.get(i, j + 1) == STATE_EMPTY) {
            grid.set(i, j + 1, STATE_RIGHT);
            grid.set(i, j, STATE_LEFT);
            pushRetry(grid, retryStack, i, j + 2);
            pushRetry(grid, retryStack, i + 1, j + 1);
            pushRetry(grid, retryStack, i - 1, j + 1);
        }
    }

    private int countNeighbors(Grid grid, int i, int j, byte target) {
        int count = 0;
        if (grid.get(i - 1, j) == target) count++;
        if (grid.get(i + 1, j) == target) count++;
        if (grid.get(i, j - 1) == target) count++;
        if (grid.get(i, j + 1) == target) count++;
        return count;
    }

    private void pushRetry(Grid grid, Deque<int[]> retryStack, int i, int j) {
        if (grid.get(i, j) != STATE_EMPTY) return;
        retryStack.push(new int[]{i, j});
    }

    private char stateToChar(byte state) {
        return switch (state) {
            case STATE_BLOCKED -> '*';
            case STATE_UP -> '^';
            case STATE_DOWN -> 'v';
            case STATE_LEFT -> '<';
            case STATE_RIGHT -> '>';
            default -> '?';
        };
    }

    /**
     * Encapsulates grid data and safe indexing logic.
     * Uses a flattened 1D array with padding for boundary checks.
     */
    private static class Grid {
        private final int n, m, width;
        private final byte[] data;

        public Grid(int n, int m) {
            this.n = n;
            this.m = m;
            this.width = m + 2;
            this.data = new byte[(n + 2) * width];
        }

        public byte get(int i, int j) {
            return data[(i + 1) * width + j + 1];
        }

        public void set(int i, int j, byte value) {
            data[(i + 1) * width + j + 1] = value;
        }
    }

    /**
     * Input parsing helper class.
     */
    public static class Parser {
        private final Scanner scanner;

        public Parser() {
            scanner = new Scanner(System.in);
        }

        public Parser(String str) {
            scanner = new Scanner(str);
        }

        public int nextInt() {
            return scanner.nextInt();
        }

        public int nextInteger() {
            return nextInt();
        }

        public long nextLong() {
            return scanner.nextLong();
        }

        public double nextDouble() {
            return scanner.nextDouble();
        }

        public String nextLine() {
            return scanner.nextLine();
        }

        public int[] nextIntegers(int count) {
            int[] result = new int[count];
            for (int i = 0; i < count; i++) {
                result[i] = nextInt();
            }
            return result;
        }

        public long[] nextLongs(int count) {
            long[] result = new long[count];
            for (int i = 0; i < count; i++) {
                result[i] = nextLong();
            }
            return result;
        }

        public int[][] nextIntegers(int fields, int count) {
            int[][] result = new int[fields][];
            for (int i = 0; i < fields; i++) {
                result[i] = new int[count];
            }
            for (int c = 0; c < count; c++) {
                for (int i = 0; i < fields; i++) {
                    result[i][c] = nextInt();
                }
            }
            return result;
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.ArrayDeque;
import java.util.Deque;
import java.util.StringTokenizer;

/**
 * Solves Codeforces 515D - Drazil and Tiles.
 * Uses a topological sort (Kahn's algorithm) approach on a grid graph.
 */
public class DrazilAndTiles515D {

    /** Immutable coordinate class for grid cells */
    private static final class Cell {
        final int r, c;

        Cell(int r, int c) {
            this.r = r;
            this.c = c;
        }
    }

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            solve(scanner, out);
        } finally {
            out.flush();
            out.close();
        }
    }

    /**
     * Core solving logic. Separated from I/O initialization for better testability and structure.
     */
    private static void solve(FastScanner in, PrintWriter out) {
        int n = in.nextInt();
        int m = in.nextInt();

        // 1-based indexing with padding simplifies boundary checks
        char[][] grid = new char[n + 2][m + 2];
        for (int i = 1; i <= n; i++) {
            String row = in.next();
            for (int j = 1; j <= m; j++) {
                grid[i][j] = row.charAt(j - 1);
            }
        }

        // Degree array tracks how many adjacent empty cells each cell has
        int[][] degree = new int[n + 2][m + 2];
        Deque<Cell> degreeOneCells = new ArrayDeque<>();
        int remainingEmptyCells = 0;

        // Calculate initial degrees and seed the queue with leaf nodes (degree == 1)
        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= m; j++) {
                if (grid[i][j] == '.') {
                    remainingEmptyCells++;

                    // Check right neighbor
                    if (grid[i][j + 1] == '.') {
                        degree[i][j]++;
                        degree[i][j + 1]++;
                    }
                    // Check bottom neighbor
                    if (grid[i + 1][j] == '.') {
                        degree[i][j]++;
                        degree[i + 1][j]++;
                    }

                    if (degree[i][j] == 1) {
                        degreeOneCells.push(new Cell(i, j));
                    }
                }
            }
        }

        // Process cells with exactly one empty neighbor (Topological Sort / Kahn's Algorithm)
        while (!degreeOneCells.isEmpty()) {
            Cell current = degreeOneCells.pop();

            // Skip stale entries or already processed cells
            if (grid[current.r][current.c] != '.' || degree[current.r][current.c] != 1) {
                continue;
            }

            // Find the single empty neighbor and place the corresponding tiles
            if (grid[current.r][current.c - 1] == '.') {
                grid[current.r][current.c - 1] = '<';
                grid[current.r][current.c] = '>';
                updateDegrees(degree, current.r, current.c - 1, degreeOneCells);
            } else if (grid[current.r][current.c + 1] == '.') {
                grid[current.r][current.c + 1] = '>';
                grid[current.r][current.c] = '<';
                updateDegrees(degree, current.r, current.c + 1, degreeOneCells);
            } else if (grid[current.r + 1][current.c] == '.') {
                grid[current.r + 1][current.c] = 'v';
                grid[current.r][current.c] = '^';
                updateDegrees(degree, current.r + 1, current.c, degreeOneCells);
            } else if (grid[current.r - 1][current.c] == '.') {
                grid[current.r - 1][current.c] = '^';
                grid[current.r][current.c] = 'v';
                updateDegrees(degree, current.r - 1, current.c, degreeOneCells);
            }

            remainingEmptyCells -= 2;
        }

        if (remainingEmptyCells != 0) {
            out.println("Not unique");
        } else {
            for (int i = 1; i <= n; i++) {
                out.println(new String(grid[i], 1, m));
            }
        }
    }

    /**
     * Decreases the degree of neighbors when a tile is placed.
     * If a neighbor's degree drops to 1, it becomes a candidate for processing.
     */
    private static void updateDegrees(int[][] degree, int r, int c, Deque<Cell> queue) {
        // Mark the newly placed cell as processed
        degree[r][c] = 0;

        // Directions: up, down, left, right
        int[] dr = {-1, 1, 0, 0};
        int[] dc = {0, 0, -1, 1};

        for (int i = 0; i < 4; i++) {
            int nr = r + dr[i];
            int nc = c + dc[i];

            // Only update if the neighbor has an active degree
            if (degree[nr][nc] > 0) {
                degree[nr][nc]--;
                if (degree[nr][nc] == 1) {
                    queue.push(new Cell(nr, nc));
                }
            }
        }
    }

    /**
     * Fast I/O helper using standard Java libraries for better maintainability
     * compared to custom byte-buffer implementations.
     */
    private static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner(java.io.InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input", e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.ArrayDeque;
import java.util.Queue;
import java.util.StringTokenizer;

/**
 * Solves a grid-based puzzle by processing cells with a single valid neighbor.
 * Uses a queue-based approach similar to topological sorting to propagate changes.
 */
public class GridSolver {

    private static final int[] DX = {0, 0, -1, 1};
    private static final int[] DY = {-1, 1, 0, 0};
    private static final char[] ARROW_MAP_1 = {'>', '<', 'v', '^'};
    private static final char[] ARROW_MAP_2 = {'<', '>', '^', 'v'};

    private int rows;
    private int cols;
    private char[][] grid;

    public static void main(String[] args) throws IOException {
        // Use try-with-resources for automatic and safe resource management
        try (InputReader sc = new InputReader(System.in);
             PrintWriter out = new PrintWriter(System.out)) {
            new GridSolver().solve(sc, out);
        }
    }

    /**
     * Orchestrates the reading, processing, and output of the grid puzzle.
     */
    void solve(InputReader sc, PrintWriter out) throws IOException {
        rows = sc.nextInt();
        cols = sc.nextInt();
        grid = new char[rows][cols];

        for (int i = 0; i < rows; i++) {
            grid[i] = sc.next().toCharArray();
        }

        // Use 2D arrays for clarity instead of 1D flattened index math
        int[][] degree = new int[rows][cols];
        boolean[][] inQueue = new boolean[rows][cols];
        Queue<int[]> queue = new ArrayDeque<>();
        int remainingCells = 0;

        // Initialize degrees and populate the queue with cells having exactly one valid neighbor
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == '.') {
                    remainingCells++;
                    int currentDegree = 0;
                    for (int k = 0; k < 4; k++) {
                        int ni = i + DX[k];
                        int nj = j + DY[k];
                        if (isValid(ni, nj)) {
                            currentDegree++;
                        }
                    }
                    degree[i][j] = currentDegree;
                    if (currentDegree == 1) {
                        inQueue[i][j] = true;
                        queue.add(new int[]{i, j});
                    }
                }
            }
        }

        // Process cells in the queue
        while (!queue.isEmpty()) {
            int[] current = queue.poll();
            int x = current[0];
            int y = current[1];
            remainingCells--;

            boolean matchFound = false;
            for (int k = 0; k < 4; k++) {
                int ni = x + DX[k];
                int nj = y + DY[k];
                if (isValid(ni, nj)) {
                    degree[ni][nj]--;
                    if (degree[ni][nj] == 1 && !inQueue[ni][nj]) {
                        inQueue[ni][nj] = true;
                        queue.add(new int[]{ni, nj});
                    }

                    if (!matchFound) {
                        matchFound = true;
                        grid[x][y] = ARROW_MAP_1[k];
                        grid[ni][nj] = ARROW_MAP_2[k];
                        if (!inQueue[ni][nj]) {
                            inQueue[ni][nj] = true;
                            queue.add(new int[]{ni, nj});
                        }
                    }
                }
            }

            if (!matchFound) {
                remainingCells++;
            }
        }

        if (remainingCells != 0) {
            out.println("Not unique");
        } else {
            for (char[] row : grid) {
                out.println(row);
            }
        }
    }

    /**
     * Checks if a coordinate is within bounds and points to an unprocessed cell.
     */
    private boolean isValid(int x, int y) {
        return x >= 0 && y >= 0 && x < rows && y < cols && grid[x][y] == '.';
    }

    /**
     * Fast input reader for performance-critical applications.
     * Replaces java.util.Scanner to avoid overhead and fix EOF handling bugs.
     */
    static class InputReader {
        private BufferedReader br;
        private StringTokenizer st;

        public InputReader(InputStream input) {
            br = new BufferedReader(new InputStreamReader(input));
        }

        public String next() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) {
                    throw new IOException("Unexpected end of input");
                }
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        public long nextLong() throws IOException {
            return Long.parseLong(next());
        }

        public double nextDouble() throws IOException {
            return Double.parseDouble(next());
        }
    }
}

import java.io.InputStream;
import java.io.OutputStream;
import java.io.PrintWriter;
import java.util.Scanner;
import java.util.Queue;
import java.util.ArrayDeque;

public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        Scanner in = new Scanner(inputStream);
        PrintWriter out = new PrintWriter(outputStream);

        TaskD solver = new TaskD();
        solver.solve(in, out);

        out.close();
    }

    static class TaskD {
        // Direction vectors: Up, Down, Left, Right
        // k=0: (0, -1) -> Up
        // k=1: (0, 1) -> Down
        // k=2: (-1, 0) -> Left
        // k=3: (1, 0) -> Right
        private static final int[] DX = {0, 0, -1, 1};
        private static final int[] DY = {-1, 1, 0, 0};

        // Character mappings for directions
        // k=0 (Up): Source '>', Target '<'
        // k=1 (Down): Source '<', Target '>'
        // k=2 (Left): Source 'v', Target '^'
        // k=3 (Right): Source '^', Target 'v'
        private static final char[] SOURCE_CHARS = {'>', '<', 'v', '^'};
        private static final char[] TARGET_CHARS = {'<', '>', '^', 'v'};

        public void solve(Scanner in, PrintWriter out) {
            if (!in.hasNextInt()) return;
            int rows = in.nextInt();
            int cols = in.nextInt();

            char[][] grid = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                String line = in.next();
                grid[i] = line.toCharArray();
            }

            // 2D arrays for degree calculation and queue tracking
            // Using 2D arrays improves readability over flattened 1D indexing
            int[][] degrees = new int[rows][cols];
            boolean[][] inQueue = new boolean[rows][cols];
            Queue<int[]> queue = new ArrayDeque<>();

            int emptyCellsCount = 0;

            // Initialization: Calculate degrees and seed queue
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] == '.') {
                        emptyCellsCount++;
                        int degree = 0;
                        for (int k = 0; k < 4; k++) {
                            int nr = r + DX[k];
                            int nc = c + DY[k];
                            if (isValid(nr, nc, rows, cols, grid)) {
                                degree++;
                            }
                        }
                        degrees[r][c] = degree;
                        if (degree == 1) {
                            inQueue[r][c] = true;
                            queue.add(new int[]{r, c});
                        }
                    }
                }
            }

            // Processing: BFS-like traversal
            while (!queue.isEmpty()) {
                int[] current = queue.poll();
                int r = current[0];
                int c = current[1];

                emptyCellsCount--;
                boolean isAssigned = grid[r][c] != '.';

                for (int k = 0; k < 4; k++) {
                    int nr = r + DX[k];
                    int nc = c + DY[k];

                    if (isValid(nr, nc, rows, cols, grid)) {
                        degrees[nr][nc]--;
                        if (degrees[nr][nc] == 1) {
                            inQueue[nr][nc] = true;
                            queue.add(new int[]{nr, nc});
                        }

                        // Logic to assign characters if current cell is not yet assigned
                        if (!isAssigned) {
                            isAssigned = true; // Mark current cell as assigned
                            grid[r][c] = SOURCE_CHARS[k];
                            grid[nr][nc] = TARGET_CHARS[k]; // Assign neighbor as well

                            // If neighbor was not in queue, add it
                            if (!inQueue[nr][nc]) {
                                inQueue[nr][nc] = true;
                                queue.add(new int[]{nr, nc});
                            }
                        }
                    }
                }

                if (!isAssigned) {
                    emptyCellsCount++;
                }
            }

            if (emptyCellsCount != 0) {
                out.println("Not unique");
            } else {
                for (char[] row : grid) {
                    out.println(row);
                }
            }
        }

        private boolean isValid(int r, int c, int rows, int cols, char[][] grid) {
            return r >= 0 && r < rows && c >= 0 && c < cols && grid[r][c] == '.';
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.OutputStreamWriter;
import java.io.PrintWriter;
import java.util.ArrayList;
import java.util.LinkedList;
import java.util.List;
import java.util.Queue;

/**
 * Solves a grid path-filling problem by marking directional arrows for 
 * cells that have exactly one adjacent empty neighbor.
 */
public class GridPathSolver {

    private static final String RESULT_NOT_UNIQUE = "Not unique";

    private final int rows;
    private final int cols;
    private char[][] grid;

    public GridPathSolver(int rows, int cols, char[][] grid) {
        this.rows = rows;
        this.cols = cols;
        this.grid = grid;
    }

    public static void main(String[] args) throws IOException {
        // Try-with-resources ensures streams are properly closed even if exceptions occur
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
             PrintWriter out = new PrintWriter(new OutputStreamWriter(System.out))) {

            String[] dimensions = br.readLine().trim().split("\\s+");
            int rows = Integer.parseInt(dimensions[0]);
            int cols = Integer.parseInt(dimensions[1]);

            char[][] grid = new char[rows][cols];
            for (int r = 0; r < rows; r++) {
                grid[r] = br.readLine().trim().toCharArray();
            }

            GridPathSolver solver = new GridPathSolver(rows, cols, grid);
            solver.solve();

            if (solver.isFullyFilled()) {
                for (char[] row : grid) {
                    out.println(row);
                }
            } else {
                out.println(RESULT_NOT_UNIQUE);
            }
        }
    }

    /**
     * Entry point for the solving logic.
     */
    public void solve() {
        findConnections();
    }

    /**
     * Scans the grid and initiates processing for cells with exactly one empty neighbor.
     */
    private void findConnections() {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '.' && getAdjacentEmptyCells(r, c).size() == 1) {
                    processCell(r, c);
                }
            }
        }
    }

    /**
     * Performs a BFS traversal starting from a cell with a single empty neighbor,
     * marking directional arrows and propagating to adjacent cells.
     */
    private void processCell(int startRow, int startCol) {
        Queue<Coordinate> queue = new LinkedList<>();
        if (grid[startRow][startCol] == '.') {
            queue.add(new Coordinate(startRow, startCol));
        }

        while (!queue.isEmpty()) {
            Coordinate current = queue.poll();
            List<Coordinate> adjacent = getAdjacentEmptyCells(current.row, current.col);

            if (adjacent.size() == 1) {
                Coordinate neighbor = adjacent.get(0);
                markDirection(current.row, current.col, neighbor.row, neighbor.col);

                for (Coordinate next : getAdjacentEmptyCells(neighbor.row, neighbor.col)) {
                    queue.add(next);
                }
            }
        }
    }

    /**
     * Marks directional characters based on the relative positions of two cells.
     */
    private void markDirection(int r1, int c1, int r2, int c2) {
        if (r1 == r2) {
            grid[r1][Math.max(c1, c2)] = '>';
            grid[r1][Math.min(c1, c2)] = '<';
        } else {
            grid[Math.max(r1, r2)][c1] = 'v';
            grid[Math.min(r1, r2)][c2] = '^';
        }
    }

    /**
     * Returns a list of adjacent empty cells ('.') within grid boundaries.
     */
    private List<Coordinate> getAdjacentEmptyCells(int row, int col) {
        List<Coordinate> adjacent = new ArrayList<>();
        if (row > 0 && grid[row - 1][col] == '.') adjacent.add(new Coordinate(row - 1, col));
        if (col > 0 && grid[row][col - 1] == '.') adjacent.add(new Coordinate(row, col - 1));
        if (row < rows - 1 && grid[row + 1][col] == '.') adjacent.add(new Coordinate(row + 1, col));
        if (col < cols - 1 && grid[row][col + 1] == '.') adjacent.add(new Coordinate(row, col + 1));
        return adjacent;
    }

    /**
     * Checks if every cell in the grid has been filled.
     */
    public boolean isFullyFilled() {
        for (char[] row : grid) {
            for (char cell : row) {
                if (cell == '.') {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Immutable value class representing a grid coordinate.
     */
    private static class Coordinate {
        final int row;
        final int col;

        Coordinate(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }
}

