/**
 * Represents a coordinate on the grid.
 */
final class Vertex {
    final int x, y;

    Vertex(int x, int y) {
        this.x = x;
        this.y = y;
    }
}

/**
 * Core solver for the grid processing task.
 * Encapsulates all algorithmic logic and separates concerns for maintainability.
 */
class Task {
    private static final int[] DX = {0, 0, 1, -1};
    private static final int[] DY = {1, -1, 0, 0};
    private static final char[] START_DIRECTION = {'<', '>', '^', 'v'};
    private static final char[] END_DIRECTION = {'>', '<', 'v', '^'};

    private int n, m;
    private char[][] grid;
    private final FastScanner scanner;
    private final PrintWriter writer;

    Task(FastScanner scanner, PrintWriter writer) {
        this.scanner = scanner;
        this.writer = writer;
    }

    public void solve() {
        readGrid();
        Queue<Vertex> queue = new ArrayDeque<>(n * m);
        initializeQueue(queue);
        processQueue(queue);
        validateAndOutput();
    }

    private void readGrid() {
        n = scanner.nextInt();
        m = scanner.nextInt();
        grid = new char[n][m];
        for (int i = 0; i < n; i++) {
            grid[i] = scanner.next().toCharArray();
        }
    }

    private void initializeQueue(Queue<Vertex> queue) {
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == '.' && countAdjacentEmptyCells(i, j) == 1) {
                    queue.add(new Vertex(i, j));
                }
            }
        }
    }

    /**
     * Counts how many orthogonal neighbors are still empty ('.').
     */
    private int countAdjacentEmptyCells(int x, int y) {
        int count = 0;
        for (int k = 0; k < 4; k++) {
            int nx = x + DX[k];
            int ny = y + DY[k];
            if (isInBounds(nx, ny) && grid[nx][ny] == '.') {
                count++;
            }
        }
        return count;
    }

    private void processQueue(Queue<Vertex> queue) {
        while (!queue.isEmpty()) {
            Vertex current = queue.poll();
            if (grid[current.x][current.y] != '.') {
                continue;
            }

            int adjacentCount = countAdjacentEmptyCells(current.x, current.y);
            if (adjacentCount != 1) {
                writer.println("Not unique");
                return;
            }

            int dir = findDirection(current.x, current.y);
            grid[current.x][current.y] = START_DIRECTION[dir];

            int nx = current.x + DX[dir];
            int ny = current.y + DY[dir];
            grid[nx][ny] = END_DIRECTION[dir];

            // Propagate to newly affected neighbors
            for (int k = 0; k < 4; k++) {
                int nnx = nx + DX[k];
                int nny = ny + DY[k];
                if (isInBounds(nnx, nny) && grid[nnx][nny] == '.' && countAdjacentEmptyCells(nnx, nny) == 1) {
                    queue.add(new Vertex(nnx, nny));
                }
            }
        }
    }

    /**
     * Finds the direction index (0-3) of the single adjacent empty cell.
     */
    private int findDirection(int x, int y) {
        for (int k = 0; k < 4; k++) {
            int nx = x + DX[k];
            int ny = y + DY[k];
            if (isInBounds(nx, ny) && grid[nx][ny] == '.') {
                return k;
            }
        }
        throw new IllegalStateException("Expected exactly one adjacent empty cell");
    }

    private void validateAndOutput() {
        // Check if any empty cells remain unprocessed
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == '.') {
                    writer.println("Not unique");
                    return;
                }
            }
        }

        // Output the final grid
        for (int i = 0; i < n; i++) {
            writer.println(new String(grid[i]));
        }
    }

    private boolean isInBounds(int x, int y) {
        return x >= 0 && x < n && y >= 0 && y < m;
    }
}

/**
 * Fast input reader for competitive programming / high-throughput scenarios.
 */
class FastScanner {
    private final BufferedReader reader;
    private StringTokenizer tokenizer;

    FastScanner(InputStream stream) {
        reader = new BufferedReader(new InputStreamReader(stream), 32768);
    }

    String next() {
        while (tokenizer == null || !tokenizer.hasMoreTokens()) {
            try {
                String line = reader.readLine();
                if (line == null) {
                    throw new EOFException();
                }
                tokenizer = new StringTokenizer(line);
            } catch (IOException e) {
                throw new RuntimeException("Failed to read input", e);
            }
        }
        return tokenizer.nextToken();
    }

    int nextInt() {
        return Integer.parseInt(next());
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.List;
import java.util.Queue;
import java.util.StringTokenizer;

public class CF292B {
    // Constants for grid characters and directions
    private static final char UNPRESSED = '.';
    private static final char UP = '^';
    private static final char DOWN = 'v';
    private static final char LEFT = '<';
    private static final char RIGHT = '>';

    private static final int[] DR = {0, 0, 1, -1};
    private static final int[] DC = {1, -1, 0, 0};

    public static void main(String[] args) throws IOException {
        FastScanner scanner = new FastScanner();
        int n = scanner.nextInt();
        int m = scanner.nextInt();

        char[][] grid = new char[n][];
        for (int i = 0; i < n; i++) {
            grid[i] = scanner.next().toCharArray();
        }

        Queue<Point> queue = new ArrayDeque<>();

        // Initialize queue with unpressed buttons that have exactly one unpressed neighbor
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < m; c++) {
                if (grid[r][c] == UNPRESSED && getUnpressedNeighbors(grid, r, c, n, m).size() == 1) {
                    queue.add(new Point(r, c));
                }
            }
        }

        // Process the queue using a BFS-like approach
        while (!queue.isEmpty()) {
            Point current = queue.poll();
            List<Point> neighbors = getUnpressedNeighbors(grid, current.r, current.c, n, m);

            if (neighbors.size() != 1) {
                continue;
            }

            Point neighbor = neighbors.get(0);
            updateGridWithDirection(grid, current, neighbor);

            // Check if the neighbor's other unpressed neighbors now have exactly one unpressed neighbor
            for (Point nextNeighbor : getUnpressedNeighbors(grid, neighbor.r, neighbor.c, n, m)) {
                if (getUnpressedNeighbors(grid, nextNeighbor.r, nextNeighbor.c, n, m).size() == 1) {
                    queue.add(nextNeighbor);
                }
            }
        }

        // Verify if all buttons are resolved
        if (hasUnpressedButtons(grid)) {
            System.out.println("Not unique");
        } else {
            for (char[] row : grid) {
                System.out.println(new String(row));
            }
        }
    }

    /**
     * Returns a list of adjacent unpressed button coordinates.
     */
    private static List<Point> getUnpressedNeighbors(char[][] grid, int r, int c, int n, int m) {
        List<Point> neighbors = new ArrayList<>();
        for (int d = 0; d < 4; d++) {
            int nr = r + DR[d];
            int nc = c + DC[d];
            if (isInBounds(nr, nc, n, m) && grid[nr][nc] == UNPRESSED) {
                neighbors.add(new Point(nr, nc));
            }
        }
        return neighbors;
    }

    /**
     * Checks if coordinates are within grid boundaries.
     */
    private static boolean isInBounds(int r, int c, int n, int m) {
        return r >= 0 && c >= 0 && r < n && c < m;
    }

    /**
     * Updates the grid with directional arrows based on the relative positions of two buttons.
     */
    private static void updateGridWithDirection(char[][] grid, Point p1, Point p2) {
        if (p1.r == p2.r) {
            // Same row: horizontal relationship
            if (p1.c < p2.c) {
                grid[p1.r][p1.c] = LEFT;
                grid[p2.r][p2.c] = RIGHT;
            } else {
                grid[p1.r][p1.c] = RIGHT;
                grid[p2.r][p2.c] = LEFT;
            }
        } else {
            // Same column: vertical relationship
            if (p1.r < p2.r) {
                grid[p1.r][p1.c] = UP;
                grid[p2.r][p2.c] = DOWN;
            } else {
                grid[p1.r][p1.c] = DOWN;
                grid[p2.r][p2.c] = UP;
            }
        }
    }

    /**
     * Checks if any unpressed buttons remain in the grid.
     */
    private static boolean hasUnpressedButtons(char[][] grid) {
        for (char[] row : grid) {
            for (char c : row) {
                if (c == UNPRESSED) {
                    return true;
                }
            }
        }
        return false;
    }

    /**
     * Immutable value class representing grid coordinates.
     */
    private record Point(int r, int c) {}

    /**
     * Fast input reader for competitive programming environments.
     */
    private static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        public String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            String token = next();
            return token == null ? 0 : Integer.parseInt(token);
        }
    }
}

import java.util.ArrayDeque;
import java.util.Scanner;

/**
 * Refactored solution for Grid Tiling (Codeforces 515D).
 * 
 * Improvements made:
 * 1. Encapsulation: Moved logic into methods (solve, checkAndEnqueueBoundary, etc.).
 * 2. Variable Naming: Replaced cryptic names (n, m, d, c, cc) with descriptive ones.
 * 3. Constants: Extracted magic numbers and arrays (directions, characters) to static constants.
 * 4. Scope Management: Removed instance variables used for loop counters to prevent state pollution.
 * 5. Readability: Added comments and structured the code flow logically.
 */
public class CF515D {

    // Constants for direction offsets: Right, Left, Down, Up
    private static final int[][] DIRECTIONS = {
        {0, 1},  // Right
        {0, -1}, // Left
        {1, 0},  // Down
        {-1, 0}  // Up
    };

    // Characters to place for each direction pair.
    // Index 0 (Right): '<' at source, '>' at dest
    // Index 1 (Left): '>' at source, '<' at dest
    // Index 2 (Down): '^' at source, 'v' at dest
    // Index 3 (Up): 'v' at source, '^' at dest
    private static final char[][] PLACEMENT_CHARS = {
        {'<', '>'},
        {'>', '<'},
        {'^', 'v'},
        {'v', '^'}
    };

    private int rows;
    private int cols;
    private int emptyCount;
    private char[][] grid;
    private ArrayDeque<Integer> queue;

    public static void main(String[] args) {
        CF515D solver = new CF515D();
        solver.solve();
    }

    public void solve() {
        Scanner scanner = new Scanner(System.in);

        // Read dimensions
        if (!scanner.hasNextInt()) return;
        rows = scanner.nextInt();
        cols = scanner.nextInt();

        grid = new char[rows][cols];
        emptyCount = 0;

        // Read grid input
        for (int r = 0; r < rows; r++) {
            String line = scanner.next();
            grid[r] = line.toCharArray();
        }

        queue = new ArrayDeque<>();

        // Initial pass: Identify empty spots and check for boundary conditions
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '.') {
                    emptyCount++;
                    checkAndEnqueueBoundary(r, c);
                }
            }
        }

        // Process queue: Peel away boundary dominoes
        while (!queue.isEmpty() && emptyCount > 0) {
            int r = queue.poll();
            int c = queue.poll();
            int directionIndex = queue.poll();

            int nextR = r + DIRECTIONS[directionIndex][0];
            int nextC = c + DIRECTIONS[directionIndex][1];

            // Place the domino characters
            // Note: We assume the cells are '.' based on queue logic, 
            // but in a production environment, a check might be added.
            grid[r][c] = PLACEMENT_CHARS[directionIndex][0];
            grid[nextR][nextC] = PLACEMENT_CHARS[directionIndex][1];
            emptyCount -= 2;

            // Check neighbors of the placed cells to see if they become new boundaries
            checkNeighborsAndEnqueue(r, c);
            checkNeighborsAndEnqueue(nextR, nextC);
        }

        // Output result
        if (emptyCount > 0) {
            System.out.println("Not unique");
        } else {
            for (int r = 0; r < rows; r++) {
                System.out.println(grid[r]);
            }
        }

        scanner.close();
    }

    /**
     * Checks if a cell is within bounds and is currently an empty spot ('.').
     */
    private boolean isFree(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols && grid[r][c] == '.';
    }

    /**
     * Checks a specific cell. If it is a free spot with exactly one free neighbor,
     * it is added to the queue as a boundary candidate.
     */
    private void checkAndEnqueueBoundary(int r, int c) {
        if (!isFree(r, c)) return;

        int freeNeighborCount = 0;
        int directionOfFreeNeighbor = -1;

        for (int k = 0; k < DIRECTIONS.length; k++) {
            int nr = r + DIRECTIONS[k][0];
            int nc = c + DIRECTIONS[k][1];
            if (isFree(nr, nc)) {
                freeNeighborCount++;
                directionOfFreeNeighbor = k;
            }
        }

        if (freeNeighborCount == 1) {
            queue.add(r);
            queue.add(c);
            queue.add(directionOfFreeNeighbor);
        }
    }

    /**
     * Iterates through all neighbors of a cell. If a neighbor is free,
     * it checks if that neighbor qualifies as a boundary spot.
     */
    private void checkNeighborsAndEnqueue(int r, int c) {
        for (int k = 0; k < DIRECTIONS.length; k++) {
            int nr = r + DIRECTIONS[k][0];
            int nc = c + DIRECTIONS[k][1];

            if (isFree(nr, nc)) {
                checkAndEnqueueBoundary(nr, nc);
            }
        }
    }
}

import java.io.BufferedReader;
import java.io.BufferedWriter;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.OutputStreamWriter;
import java.io.PrintWriter;
import java.util.LinkedList;
import java.util.Queue;
import java.util.StringTokenizer;

public class B {

    public static void main(String[] args) throws IOException {
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
             PrintWriter pw = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)))) {
            new GridSolver().solve(br, pw);
        }
    }

    private static class GridSolver {
        private int rows, cols;
        private char[][] grid;
        private int[][] adjacentEmptyCount;
        private static final int[] DX = {1, -1, 0, 0};
        private static final int[] DY = {0, 0, 1, -1};

        void solve(BufferedReader br, PrintWriter pw) throws IOException {
            FastScanner scanner = new FastScanner(br);
            readInput(scanner);
            calculateAdjacentCounts();

            if (!processQueue()) {
                pw.println("Not unique");
                return;
            }

            printOutput(pw);
        }

        private void readInput(FastScanner scanner) throws IOException {
            rows = scanner.nextInt();
            cols = scanner.nextInt();
            grid = new char[rows + 1][cols + 1];
            for (int i = 1; i <= rows; i++) {
                String line = scanner.next();
                for (int j = 1; j <= cols; j++) {
                    grid[i][j] = line.charAt(j - 1);
                }
            }
            adjacentEmptyCount = new int[rows + 1][cols + 1];
        }

        private void calculateAdjacentCounts() {
            for (int r = 1; r <= rows; r++) {
                for (int c = 1; c <= cols; c++) {
                    adjacentEmptyCount[r][c] = countAdjacentEmpty(r, c);
                }
            }
        }

        private int countAdjacentEmpty(int r, int c) {
            int count = 0;
            for (int i = 0; i < 4; i++) {
                int nr = r + DX[i];
                int nc = c + DY[i];
                if (isInBounds(nr, nc) && grid[nr][nc] == '.') {
                    count++;
                }
            }
            return count;
        }

        private boolean processQueue() {
            Queue<int[]> queue = new LinkedList<>();
            for (int r = 1; r <= rows; r++) {
                for (int c = 1; c <= cols; c++) {
                    if (grid[r][c] == '.' && adjacentEmptyCount[r][c] == 1) {
                        queue.add(new int[]{r, c});
                    }
                }
            }

            while (!queue.isEmpty()) {
                int[] cell = queue.poll();
                int r = cell[0];
                int c = cell[1];

                if (grid[r][c] != '.') continue;
                if (adjacentEmptyCount[r][c] == 0) {
                    return false;
                }

                int nr = -1, nc = -1;
                for (int i = 0; i < 4; i++) {
                    int tr = r + DX[i];
                    int tc = c + DY[i];
                    if (isInBounds(tr, tc) && grid[tr][tc] == '.') {
                        nr = tr;
                        nc = tc;
                        break;
                    }
                }

                if (nr == -1) continue;

                assignDirectionAndResolve(r, c, nr, nc);

                updateCounts(r, c);
                updateCounts(nr, nc);

                for (int i = 0; i < 4; i++) {
                    int tr = r + DX[i];
                    int tc = c + DY[i];
                    if (isInBounds(tr, tc) && grid[tr][tc] == '.' && adjacentEmptyCount[tr][tc] == 1) {
                        queue.add(new int[]{tr, tc});
                    }
                    tr = nr + DX[i];
                    tc = nc + DY[i];
                    if (isInBounds(tr, tc) && grid[tr][tc] == '.' && adjacentEmptyCount[tr][tc] == 1) {
                        queue.add(new int[]{tr, tc});
                    }
                }
            }
            return true;
        }

        private void assignDirectionAndResolve(int r1, int c1, int r2, int c2) {
            grid[r1][c1] = getDirectionChar(r1, c1, r2, c2);
            grid[r2][c2] = getDirectionChar(r2, c2, r1, c1);
        }

        private char getDirectionChar(int r1, int c1, int r2, int c2) {
            if (r1 == r2) {
                return c1 < c2 ? '<' : '>';
            }
            return r1 < r2 ? '^' : 'v';
        }

        private void updateCounts(int r, int c) {
            adjacentEmptyCount[r][c] = countAdjacentEmpty(r, c);
        }

        private boolean isInBounds(int r, int c) {
            return r >= 1 && r <= rows && c >= 1 && c <= cols;
        }

        private void printOutput(PrintWriter pw) {
            for (int i = 1; i <= rows; i++) {
                for (int j = 1; j <= cols; j++) {
                    if (grid[i][j] == '.') {
                        pw.println("Not unique");
                        return;
                    }
                }
            }
            for (int i = 1; i <= rows; i++) {
                pw.println(new String(grid[i], 1, cols));
            }
        }

        private static class FastScanner {
            private final BufferedReader br;
            private StringTokenizer st;

            FastScanner(BufferedReader br) {
                this.br = br;
            }

            String next() throws IOException {
                while (st == null || !st.hasMoreTokens()) {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                }
                return st.nextToken();
            }

            int nextInt() throws IOException {
                return Integer.parseInt(next());
            }
        }
    }
}

import java.util.ArrayDeque;
import java.util.Queue;
import java.util.Scanner;

/**
 * A solver for grid flow problems that assigns directional arrows to empty cells.
 * It identifies cells with exactly one empty neighbor (and 3 solid neighbors)
 * and propagates flow through the grid.
 */
public class GridFlowSolver {

    private char[][] grid;
    private int rows;
    private int cols;
    private Queue<Coordinate> queue;

    // Direction vectors: Up, Down, Left, Right
    private static final int[] DR = {-1, 1, 0, 0};
    private static final int[] DC = {0, 0, -1, 1};

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        // Check for valid input
        if (!scanner.hasNextInt()) {
            return;
        }

        int n = scanner.nextInt();
        int m = scanner.nextInt();

        GridFlowSolver solver = new GridFlowSolver(n, m);
        solver.readGrid(scanner);
        solver.solve();
    }

    private GridFlowSolver(int n, int m) {
        this.rows = n;
        this.cols = m;
        this.grid = new char[n][m];
        this.queue = new ArrayDeque<>();
    }

    /**
     * Reads the grid from the scanner.
     */
    private void readGrid(Scanner scanner) {
        for (int i = 0; i < rows; i++) {
            String rowStr = scanner.next();
            grid[i] = rowStr.toCharArray();
        }
    }

    /**
     * Executes the main logic of the solver.
     */
    private void solve() {
        // Initial pass: Identify cells with 3 solid neighbors and add them to the queue
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] != '*') {
                    check(r, c);
                }
            }
        }

        // Process the queue to assign arrows and propagate changes
        while (!queue.isEmpty()) {
            Coordinate u = queue.poll();
            Coordinate v = queue.poll();

            // Safety check for nulls, though logic ensures pairs
            if (u == null || v == null) break;

            // If either cell is no longer empty, skip processing
            if (grid[u.r][u.c] != '.' || grid[v.r][v.c] != '.') {
                continue;
            }

            assignArrows(u, v);

            // Propagate changes to neighbors of both cells
            propagate(u);
            propagate(v);
        }

        printResult();
    }

    /**
     * Checks if a cell has exactly 3 solid neighbors.
     * If so, adds the cell and its single empty neighbor to the queue.
     *
     * @param r The row index of the cell to check.
     * @param c The column index of the cell to check.
     */
    private void check(int r, int c) {
        int solidCount = 0;
        Coordinate emptyNeighbor = null;

        for (int d = 0; d < 4; d++) {
            int nr = r + DR[d];
            int nc = c + DC[d];
            if (isSolid(nr, nc)) {
                solidCount++;
            } else {
                emptyNeighbor = new Coordinate(nr, nc);
            }
        }

        // If exactly 1 neighbor is empty (meaning 3 are solid), add to queue
        if (solidCount == 3 && emptyNeighbor != null) {
            queue.add(new Coordinate(r, c));
            queue.add(emptyNeighbor);
        }
    }

    /**
     * Assigns directional arrows to the two connected empty cells based on their relative positions.
     *
     * @param u The first coordinate (current cell).
     * @param v The second coordinate (empty neighbor).
     */
    private void assignArrows(Coordinate u, Coordinate v) {
        if (u.r != v.r) {
            // Different rows (Vertical alignment)
            if (u.r > v.r) {
                // u is below v
                grid[v.r][v.c] = '^'; // v points up
                grid[u.r][u.c] = 'v'; // u points down
            } else {
                // u is above v
                grid[v.r][v.c] = 'v'; // v points down
                grid[u.r][u.c] = '^'; // u points up
            }
        } else {
            // Same row (Horizontal alignment)
            if (u.c > v.c) {
                // u is right of v
                grid[v.r][v.c] = '<'; // v points left
                grid[u.r][u.c] = '>'; // u points right
            } else {
                // u is left of v
                grid[v.r][v.c] = '>'; // v points right
                grid[u.r][u.c] = '<'; // u points left
            }
        }
    }

    /**
     * Checks neighbors of a coordinate and triggers 'check' if they are empty.
     * This propagates the flow state to adjacent cells.
     *
     * @param coord The coordinate to propagate from.
     */
    private void propagate(Coordinate coord) {
        for (int d = 0; d < 4; d++) {
            int nr = coord.r + DR[d];
            int nc = coord.c + DC[d];
            if (!isSolid(nr, nc)) {
                check(nr, nc);
            }
        }
    }

    /**
     * Checks if a coordinate is out of bounds or contains a solid object.
     *
     * @param r The row index.
     * @param c The column index.
     * @return true if the position is solid (blocked or out of bounds), false if empty.
     */
    private boolean isSolid(int r, int c) {
        if (r < 0 || c < 0 || r >= rows || c >= cols) {
            return true;
        }
        return grid[r][c] != '.';
    }

    /**
     * Prints the final grid or "Not unique" if the grid is not fully filled.
     */
    private void printResult() {
        boolean isFull = true;
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '.') {
                    isFull = false;
                    break;
                }
            }
            if (!isFull) break;
        }

        if (isFull) {
            StringBuilder sb = new StringBuilder();
            for (int r = 0; r < rows; r++) {
                sb.append(grid[r]).append('\n');
            }
            System.out.print(sb);
        } else {
            System.out.println("Not unique");
        }
    }

    /**
     * Simple data class for storing grid coordinates.
     */
    private static class Coordinate {
        int r, c;

        Coordinate(int r, int c) {
            this.r = r;
            this.c = c;
        }
    }
}

import java.util.ArrayDeque;
import java.util.Queue;
import java.util.Scanner;

public class Task4 {

    // Direction vectors: Up, Right, Down, Left
    private static final int[] DX = {-1, 0, 1, 0};
    private static final int[] DY = {0, 1, 0, -1};
    private static final char[] SYM = {'v', '<', '^', '>'};

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        if (!scanner.hasNextInt()) {
            return;
        }

        int n = scanner.nextInt();
        int m = scanner.nextInt();

        // Use a padded grid to simplify boundary checks
        char[][] grid = new char[n + 2][m + 2];

        // Initialize padding with walls
        for (int i = 0; i < n + 2; i++) {
            for (int j = 0; j < m + 2; j++) {
                grid[i][j] = '#';
            }
        }

        // Read the grid content
        for (int i = 0; i < n; i++) {
            String row = scanner.next();
            for (int j = 0; j < m; j++) {
                grid[i + 1][j + 1] = row.charAt(j);
            }
        }
        scanner.close();

        // Queue to store coordinates of cells with exactly one empty neighbor
        Queue<int[]> queue = new ArrayDeque<>();

        // Identify initial candidates
        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= m; j++) {
                if (grid[i][j] == '.' && countEmptyNeighbors(grid, i, j) == 1) {
                    queue.add(new int[]{i, j});
                }
            }
        }

        // Process the queue
        while (!queue.isEmpty()) {
            int[] pos = queue.poll();
            int r = pos[0];
            int c = pos[1];

            // Re-verify condition as the grid state may have changed
            if (grid[r][c] != '.' || countEmptyNeighbors(grid, r, c) != 1) {
                continue;
            }

            int dir = fill(grid, r, c);
            if (dir == -1) continue; // Should not occur if countEmptyNeighbors == 1

            // Check newly affected neighbors
            for (int d = 0; d < 4; d++) {
                int nr1 = r + DX[d];
                int nc1 = c + DY[d];
                if (grid[nr1][nc1] == '.' && countEmptyNeighbors(grid, nr1, nc1) == 1) {
                    queue.add(new int[]{nr1, nc1});
                }

                int nr2 = r + DX[d] + DX[dir];
                int nc2 = c + DY[d] + DY[dir];
                if (grid[nr2][nc2] == '.' && countEmptyNeighbors(grid, nr2, nc2) == 1) {
                    queue.add(new int[]{nr2, nc2});
                }
            }
        }

        // Verify if all empty spaces have been filled
        boolean allFilled = true;
        outerLoop:
        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= m; j++) {
                if (grid[i][j] == '.') {
                    allFilled = false;
                    break outerLoop;
                }
            }
        }

        if (!allFilled) {
            System.out.println("Not unique");
        } else {
            StringBuilder output = new StringBuilder();
            for (int i = 1; i <= n; i++) {
                for (int j = 1; j <= m; j++) {
                    output.append(grid[i][j]);
                }
                output.append('\n');
            }
            System.out.print(output);
        }
    }

    /**
     * Counts the number of adjacent '.' cells.
     * Returns 0 if the cell itself is not '.'.
     */
    private static int countEmptyNeighbors(char[][] grid, int r, int c) {
        if (grid[r][c] != '.') return 0;
        int count = 0;
        for (int i = 0; i < 4; i++) {
            if (grid[r + DX[i]][c + DY[i]] == '.') {
                count++;
            }
        }
        return count;
    }

    /**
     * Fills the current cell and its empty neighbor with directional arrows.
     * Returns the direction index used, or -1 if no empty neighbor exists.
     */
    private static int fill(char[][] grid, int r, int c) {
        for (int i = 0; i < 4; i++) {
            if (grid[r + DX[i]][c + DY[i]] == '.') {
                grid[r][c] = SYM[i];
                grid[r + DX[i]][c + DY[i]] = SYM[(i + 2) % 4];
                return i;
            }
        }
        return -1;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.Arrays;
import java.util.StringTokenizer;

public class Main {
    // Direction vectors: Down, Right, Up, Left
    private static final int[] DR = {1, 0, -1, 0};
    private static final int[] DC = {0, 1, 0, -1};

    private int n, m;
    private char[][] grid;
    private int[][] degree;
    private PrintWriter out;

    public static void main(String[] args) throws IOException {
        Main solver = new Main();
        solver.solve();
    }

    private void solve() throws IOException {
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            out = new PrintWriter(System.out);
            String line = br.readLine();
            if (line == null) return;

            StringTokenizer st = new StringTokenizer(line);
            n = Integer.parseInt(st.nextToken());
            m = Integer.parseInt(st.nextToken());

            // Allocate with padding to safely access neighbors without bounds checks
            grid = new char[n + 2][m + 2];
            degree = new int[n + 2][m + 2];

            // Initialize border and grid
            for (int i = 0; i <= n + 1; i++) {
                Arrays.fill(degree[i], -1);
                Arrays.fill(grid[i], ' ');
            }

            // Read input grid and initialize degrees
            for (int i = 1; i <= n; i++) {
                String row = br.readLine();
                if (row == null) break;
                for (int j = 1; j <= m; j++) {
                    grid[i][j] = row.charAt(j - 1);
                    degree[i][j] = (grid[i][j] == '*') ? -1 : 0;
                }
            }

            // Calculate initial degrees for empty cells
            for (int i = 1; i <= n; i++) {
                for (int j = 1; j <= m; j++) {
                    if (degree[i][j] == 0) {
                        for (int k = 0; k < 4; k++) {
                            if (degree[i + DR[k]][j + DC[k]] != -1) {
                                degree[i][j]++;
                            }
                        }
                    }
                }
            }

            // Process the grid
            for (int i = 1; i <= n; i++) {
                for (int j = 1; j <= m; j++) {
                    fill(i, j);
                }
            }

            // Validate result
            for (int i = 1; i <= n; i++) {
                for (int j = 1; j <= m; j++) {
                    if (grid[i][j] == '.') {
                        out.println("Not unique");
                        out.flush();
                        return;
                    }
                }
            }

            // Output result
            for (int i = 1; i <= n; i++) {
                out.println(new String(grid[i], 1, m));
            }
        } finally {
            out.flush();
        }
    }

    /**
     * Recursively processes degree-1 cells, marks directions, and updates neighbor degrees.
     * Relies on grid padding to avoid ArrayIndexOutOfBoundsException.
     * Note: Recursion depth is bounded by the grid diameter for this specific algorithm.
     */
    private void fill(int r, int c) {
        if (degree[r][c] != 1) return;

        degree[r][c] = -1;
        for (int k = 0; k < 4; k++) {
            int nr = r + DR[k];
            int nc = c + DC[k];
            if (degree[nr][nc] != -1) {
                degree[nr][nc] = -1;

                markDirections(r, c, nr, nc, k);

                // Decrement degrees of all 4 neighbors for both cells
                for (int dk = 0; dk < 4; dk++) {
                    int dr1 = r + DR[dk];
                    int dc1 = c + DC[dk];
                    if (degree[dr1][dc1] != -1) degree[dr1][dc1]--;

                    int dr2 = nr + DR[dk];
                    int dc2 = nc + DC[dk];
                    if (degree[dr2][dc2] != -1) degree[dr2][dc2]--;
                }

                // Recursively process neighbors
                for (int dk = 0; dk < 4; dk++) {
                    fill(r + DR[dk], c + DC[dk]);
                    fill(nr + DR[dk], nc + DC[dk]);
                }
                return;
            }
        }
    }

    private void markDirections(int r, int c, int nr, int nc, int k) {
        switch (k) {
            case 0: // Down
                grid[r][c] = '^';
                grid[r + 1][c] = 'v';
                break;
            case 1: // Right
                grid[r][c] = '<';
                grid[r][c + 1] = '>';
                break;
            case 2: // Up
                grid[r - 1][c] = '^';
                grid[r][c] = 'v';
                break;
            case 3: // Left
                grid[r][c - 1] = '<';
                grid[r][c] = '>';
                break;
        }
    }
}

import java.awt.Point;
import java.io.BufferedReader;
import java.io.BufferedInputStream;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayDeque;
import java.util.Queue;
import java.util.StringTokenizer;

/**
 * Solves the grid path problem (Div2 292 D).
 * Uses a topological sort approach (peeling the onion) to determine the path.
 */
public class GridPathSolver {

    // Direction vectors: Up, Down, Left, Right
    // Corresponding to indices 0, 1, 2, 3
    private static final int[] DX = {0, 0, -1, 1};
    private static final int[] DY = {-1, 1, 0, 0};

    // Character representations for the arrows
    // Index matches DX/DY arrays
    private static final char[] ARROW_CURRENT = {'>', '<', 'v', '^'};
    private static final char[] ARROW_NEIGHBOR = {'<', '>', '^', 'v'};

    private static final char WALL = '*';
    private static final char EMPTY = '.';

    public static void main(String[] args) throws IOException {
        // Initialize fast I/O
        BufferedReader reader = new BufferedReader(new InputStreamReader(new BufferedInputStream(System.in)));

        // Read dimensions N and M
        String line = reader.readLine();
        if (line == null) return;
        StringTokenizer tokenizer = new StringTokenizer(line);

        int n = Integer.parseInt(tokenizer.nextToken());
        int m = Integer.parseInt(tokenizer.nextToken());

        char[][] grid = new char[n][m];
        for (int i = 0; i < n; i++) {
            String rowLine = reader.readLine();
            // Ensure we handle the line correctly
            grid[i] = (rowLine != null) ? rowLine.toCharArray() : new char[0];
        }

        boolean solutionFound = solve(n, m, grid);

        if (solutionFound) {
            for (int i = 0; i < n; i++) {
                System.out.println(grid[i]);
            }
        } else {
            System.out.println("Not unique");
        }
    }

    /**
     * Core logic to solve the grid path problem.
     */
    private static boolean solve(int n, int m, char[][] grid) {
        int[][] degrees = new int[n][m];
        Queue<Point> queue = new ArrayDeque<>();

        // 1. Calculate initial degrees (number of valid empty neighbors)
        // and identify starting points (degree == 1).
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == WALL) continue;

                int degree = 0;
                for (int k = 0; k < DX.length; k++) {
                    int neighborX = i + DX[k];
                    int neighborY = j + DY[k];
                    if (isValidCoordinate(neighborX, neighborY, n, m) && grid[neighborX][neighborY] != WALL) {
                        degree++;
                    }
                }
                degrees[i][j] = degree;

                // Start with nodes that have only 1 valid neighbor (ends of a path)
                if (degree == 1) {
                    queue.add(new Point(i, j));
                }
            }
        }

        // 2. Process the queue (Topological Sort / Peeling)
        while (!queue.isEmpty()) {
            Point current = queue.poll();

            // If degree is not 1, it means this node was already processed or invalid
            if (degrees[current.x][current.y] != 1) {
                continue;
            }

            boolean edgeConnected = false;

            // Find the single valid neighbor to connect to
            for (int k = 0; k < DX.length; k++) {
                int neighborX = current.x + DX[k];
                int neighborY = current.y + DY[k];

                if (isValidCoordinate(neighborX, neighborY, n, m) && grid[neighborX][neighborY] == EMPTY) {
                    // Connect current to neighbor
                    degrees[neighborX][neighborY] = -1; // Mark as processed
                    grid[current.x][current.y] = ARROW_CURRENT[k];
                    grid[neighborX][neighborY] = ARROW_NEIGHBOR[k];

                    edgeConnected = true;

                    // Update neighbors of the neighbor (since it's now "removed" from the empty set)
                    updateNeighborDegrees(neighborX, neighborY, degrees, grid, queue);
                }
            }

            // If we found a connection, we also need to update neighbors of the current node
            // (standard topological sort removal logic)
            if (edgeConnected) {
                updateNeighborDegrees(current.x, current.y, degrees, grid, queue);
            }
        }

        // 3. Verify if the grid is fully resolved (no empty cells left)
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == EMPTY) {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Checks if coordinates are within grid bounds.
     */
    private static boolean isValidCoordinate(int x, int y, int n, int m) {
        return x >= 0 && x < n && y >= 0 && y < m;
    }

    /**
     * Decrements the degree of valid empty neighbors of the specified cell.
     * If a neighbor's degree drops to 1, adds it to the processing queue.
     */
    private static void updateNeighborDegrees(int row, int col, int[][] degrees, char[][] grid, Queue<Point> queue) {
        for (int k = 0; k < DX.length; k++) {
            int neighborX = row + DX[k];
            int neighborY = col + DY[k];

            if (isValidCoordinate(neighborX, neighborY, degrees.length, degrees[0].length) && grid[neighborX][neighborY] == EMPTY) {
                degrees[neighborX][neighborY]--;
                if (degrees[neighborX][neighborY] == 1) {
                    queue.add(new Point(neighborX, neighborY));
                }
            }
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

/**
 * Solves the Drazil Tiles problem by placing directional tiles on a grid.
 * Refactored for maintainability, encapsulation, and robust I/O handling.
 */
public class D515_DrazilTiles implements AutoCloseable {

    // Direction vectors: Up, Left, Down, Right
    private static final int[] DR = {-1, 0, 1, 0};
    private static final int[] DC = {0, -1, 0, 1};

    private final BufferedReader reader;
    private final PrintWriter writer;
    private StringTokenizer tokenizer;
    private char[][] board;

    public D515_DrazilTiles() {
        this.reader = new BufferedReader(new InputStreamReader(System.in));
        this.writer = new PrintWriter(System.out);
    }

    /**
     * Reads the next token from input.
     */
    private String next() throws IOException {
        while (tokenizer == null || !tokenizer.hasMoreTokens()) {
            String line = reader.readLine();
            if (line == null) {
                throw new IOException("Unexpected end of input");
            }
            tokenizer = new StringTokenizer(line);
        }
        return tokenizer.nextToken();
    }

    /**
     * Reads the next integer from input.
     */
    private int nextInt() throws IOException {
        return Integer.parseInt(next());
    }

    /**
     * Orchestrates the solving process: input, processing, validation, and output.
     */
    public void solve() throws IOException {
        int rows = nextInt();
        int cols = nextInt();

        if (rows == 0 || cols == 0) {
            return;
        }

        board = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            board[i] = next().toCharArray();
        }

        processBoard(rows, cols);
        validateAndPrint(rows, cols);
    }

    /**
     * Iterates through the board and triggers tile placement logic for empty cells.
     */
    private void processBoard(int rows, int cols) {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (board[i][j] == '.') {
                    force(i, j);
                }
            }
        }
    }

    /**
     * Places tiles based on exactly one adjacent empty cell and propagates recursively.
     */
    private void force(int row, int col) {
        int mask = 0;
        for (int dir = 0; dir < 4; dir++) {
            int nr = row + DR[dir];
            int nc = col + DC[dir];
            if (isEmpty(nr, nc)) {
                mask |= (1 << dir);
            }
        }

        // Must have exactly one adjacent empty cell to form a valid tile pair
        if (Integer.bitCount(mask) != 1) {
            return;
        }

        char selfTile, neighborTile;
        int nr, nc;

        // Determine tile orientation and coordinates based on the single empty neighbor
        switch (mask) {
            case 1: // Up
                selfTile = 'v'; neighborTile = '^'; nr = row - 1; nc = col; break;
            case 2: // Left
                selfTile = '>'; neighborTile = '<'; nr = row; nc = col - 1; break;
            case 4: // Down
                selfTile = '^'; neighborTile = 'v'; nr = row + 1; nc = col; break;
            case 8: // Right
                selfTile = '<'; neighborTile = '>'; nr = row; nc = col + 1; break;
            default:
                return;
        }

        board[row][col] = selfTile;
        board[nr][nc] = neighborTile;

        // Propagate to neighbors of the newly placed tile
        for (int dir = 0; dir < 4; dir++) {
            int nextR = nr + DR[dir];
            int nextC = nc + DC[dir];
            if (isEmpty(nextR, nextC)) {
                force(nextR, nextC);
            }
        }
    }

    /**
     * Checks if a cell is within bounds and empty.
     */
    private boolean isEmpty(int row, int col) {
        return row >= 0 && row < board.length && col >= 0 && col < board[0].length && board[row][col] == '.';
    }

    /**
     * Validates that the board is fully covered and prints the result.
     */
    private void validateAndPrint(int rows, int cols) {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (board[i][j] == '.') {
                    writer.println("Not unique");
                    return;
                }
            }
        }
        for (int i = 0; i < rows; i++) {
            writer.println(new String(board[i]));
        }
    }

    @Override
    public void close() throws IOException {
        writer.flush();
        writer.close();
        reader.close();
    }

    public static void main(String[] args) throws IOException {
        try (D515_DrazilTiles solver = new D515_DrazilTiles()) {
            solver.solve();
        }
    }
}

