class TaskD {
    private static final int[] DR = {-1, 0, 1, 0};
    private static final int[] DC = {0, -1, 0, 1};

    private char[][] board;
    private int rows, cols;

    /**
     * Solves the grid problem by propagating arrow placements iteratively.
     */
    public void solve(FastScanner in, PrintWriter out) {
        rows = in.nextInt();
        cols = in.nextInt();
        board = new char[rows][];
        for (int i = 0; i < rows; i++) {
            board[i] = in.next().toCharArray();
        }

        // Initialize queue with all empty cells
        Queue<int[]> queue = new ArrayDeque<>();
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (board[i][j] == '.') {
                    queue.add(new int[]{i, j});
                }
            }
        }

        // Iterative propagation to avoid recursion depth limits
        while (!queue.isEmpty()) {
            int[] curr = queue.poll();
            int r = curr[0], c = curr[1];

            // Skip if already resolved
            if (board[r][c] != '.') continue;

            int mask = 0;
            for (int i = 0; i < 4; i++) {
                if (isEmpty(r + DR[i], c + DC[i])) {
                    mask |= (1 << i);
                }
            }

            // Only proceed if exactly one neighbor is empty
            if (Integer.bitCount(mask) != 1) continue;

            int nr = r, nc = c;
            char currentChar, neighborChar;

            if (mask == 1) {
                // Up is empty
                currentChar = 'v'; neighborChar = '^'; nr = r - 1; nc = c;
            } else if (mask == 2) {
                // Left is empty
                currentChar = '>'; neighborChar = '<'; nr = r; nc = c - 1;
            } else if (mask == 4) {
                // Down is empty
                currentChar = '^'; neighborChar = 'v'; nr = r + 1; nc = c;
            } else {
                // mask == 8, Right is empty
                currentChar = '<'; neighborChar = '>'; nr = r; nc = c + 1;
            }

            board[r][c] = currentChar;
            board[nr][nc] = neighborChar;

            // Add the newly filled cell to the queue so its neighbors can be re-evaluated
            queue.add(new int[]{nr, nc});
        }

        // Check for any remaining empty cells
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (board[i][j] == '.') {
                    out.println("Not unique");
                    return;
                }
            }
            out.println(new String(board[i]));
        }
    }

    private boolean isEmpty(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols && board[r][c] == '.';
    }
}

/**
 * High-performance scanner for competitive programming and fast I/O.
 */
class FastScanner {
    private final InputStream in;
    private final byte[] buffer = new byte[1 << 16];
    private int ptr = 0;
    private int buflen = 0;

    public FastScanner(InputStream in) {
        this.in = in;
    }

    private boolean hasNextByte() {
        if (ptr < buflen) {
            return true;
        }
        ptr = 0;
        try {
            buflen = in.read(buffer);
        } catch (IOException e) {
            throw new RuntimeException(e);
        }
        return buflen > 0;
    }

    private int readByte() {
        if (hasNextByte()) return buffer[ptr++];
        else return -1;
    }

    private static boolean isPrintableChar(int c) {
        return c >= 33 && c <= 126;
    }

    public boolean hasNext() {
        while (hasNextByte() && !isPrintableChar(buffer[ptr])) ptr++;
        return hasNextByte();
    }

    public String next() {
        if (!hasNext()) throw new NoSuchElementException();
        StringBuilder sb = new StringBuilder();
        int b = readByte();
        while (isPrintableChar(b)) {
            sb.appendCodePoint(b);
            b = readByte();
        }
        return sb.toString();
    }

    public int nextInt() {
        return Integer.parseInt(next());
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

public class GridPathSolver {
    // Direction vectors: Right, Left, Down, Up
    private static final int[] DX = {0, 0, 1, -1};
    private static final int[] DY = {1, -1, 0, 0};

    private int n, m;
    private char[][] grid;

    public static void main(String[] args) {
        // Use try-with-resources to ensure proper cleanup
        try (GridPathSolver solver = new GridPathSolver()) {
            solver.run();
        } catch (IOException e) {
            System.err.println("I/O error occurred: " + e.getMessage());
            e.printStackTrace();
        }
    }

    /**
     * Initializes I/O streams and delegates to the core solving logic.
     */
    public void run() throws IOException {
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
             PrintWriter writer = new PrintWriter(System.out)) {

            FastScanner scanner = new FastScanner(reader);
            solve(scanner, writer);

            writer.flush();
        }
    }

    /**
     * Core algorithm: Reads input, processes the grid using a topological sort-like approach,
     * and outputs the result or a failure message.
     */
    private void solve(FastScanner scanner, PrintWriter writer) throws IOException {
        n = scanner.nextInt();
        m = scanner.nextInt();
        grid = new char[n][];
        for (int i = 0; i < n; i++) {
            grid[i] = scanner.next().toCharArray();
        }

        // Queue for processing leaf nodes (degree 1)
        int[] queueRow = new int[n * m];
        int[] queueCol = new int[n * m];
        int head = 0;
        int tail = 0;

        // Initialize queue with boundary/leaf cells
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < m; c++) {
                if (isValid(r, c) && countValidNeighbors(r, c) == 1) {
                    queueRow[tail] = r;
                    queueCol[tail++] = c;
                }
            }
        }

        // Process queue
        while (head < tail) {
            int r = queueRow[head];
            int c = queueCol[head++];

            // Skip if already processed or invalid
            if (!isValid(r, c)) {
                continue;
            }

            int direction = placeDomino(r, c);
            if (direction == -1) {
                writer.println("Not unique");
                return;
            }

            int nr = r + DX[direction];
            int nc = c + DY[direction];

            // Check neighbors of the placed domino's other end
            for (int i = 0; i < 4; i++) {
                int nnr = nr + DX[i];
                int nnc = nc + DY[i];
                if (isValid(nnr, nnc) && countValidNeighbors(nnr, nnc) == 1) {
                    queueRow[tail] = nnr;
                    queueCol[tail++] = nnc;
                }
            }
        }

        // Verify that all cells have been visited
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < m; c++) {
                if (isValid(r, c)) {
                    writer.println("Not unique");
                    return;
                }
            }
        }

        // Output the solved grid
        for (int r = 0; r < n; r++) {
            writer.println(new String(grid[r]));
        }
    }

    /**
     * Checks if a cell is within bounds and unvisited.
     */
    private boolean isValid(int r, int c) {
        return r >= 0 && r < n && c >= 0 && c < m && grid[r][c] == '.';
    }

    /**
     * Counts the number of valid (unvisited) neighbors for a cell.
     */
    private int countValidNeighbors(int r, int c) {
        int count = 0;
        for (int i = 0; i < 4; i++) {
            if (isValid(r + DX[i], c + DY[i])) {
                count++;
            }
        }
        return count;
    }

    /**
     * Places a domino in a valid direction, updates the grid, and returns the direction index.
     */
    private int placeDomino(int r, int c) {
        for (int i = 0; i < 4; i++) {
            int nr = r + DX[i];
            int nc = c + DY[i];
            if (!isValid(nr, nc)) {
                continue;
            }

            char selfChar, neighborChar;
            switch (i) {
                case 0: selfChar = '<'; neighborChar = '>'; break; // Right
                case 1: selfChar = '>'; neighborChar = '<'; break; // Left
                case 2: selfChar = '^'; neighborChar = 'v'; break; // Down
                case 3: selfChar = 'v'; neighborChar = '^'; break; // Up
                default: throw new IllegalStateException("Invalid direction index");
            }

            grid[r][c] = selfChar;
            grid[nr][nc] = neighborChar;
            return i;
        }
        return -1;
    }

    /**
     * Lightweight token scanner for fast input parsing.
     */
    private static class FastScanner {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastScanner(BufferedReader reader) {
            this.reader = reader;
        }

        public String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                String line = reader.readLine();
                if (line == null) {
                    throw new IOException("Unexpected end of input");
                }
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayDeque;
import java.util.Queue;

public class GridPuzzleSolver {
    // Cell state constants
    private static final int EMPTY = 0;
    private static final int WALL = 1;
    private static final int LEFT_PAIR = 2;
    private static final int RIGHT_PAIR = 3;
    private static final int UP_PAIR = 4;
    private static final int DOWN_PAIR = 5;

    private final int rows;
    private final int cols;
    private final int[][] grid;

    public GridPuzzleSolver(int rows, int cols, int[][] grid) {
        this.rows = rows;
        this.cols = cols;
        this.grid = grid;
    }

    public void solve() throws IOException {
        int emptyCount = countEmptyCells();

        if (emptyCount % 2 != 0) {
            System.out.println("Not unique");
            return;
        }

        if (emptyCount == 0) {
            printGrid();
            return;
        }

        Queue<Integer> queue = new ArrayDeque<>();
        boolean[] inQueue = new boolean[rows * cols];
        boolean[] processed = new boolean[rows * cols];

        // Initialize queue with cells that have exactly one empty neighbor
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == EMPTY) {
                    int idx = toIndex(r, c);
                    if (countEmptyNeighbors(r, c) == 1 && !inQueue[idx]) {
                        queue.offer(idx);
                        inQueue[idx] = true;
                    }
                }
            }
        }

        while (!queue.isEmpty()) {
            int v1 = queue.poll();
            if (processed[v1]) {
                continue;
            }

            int v2 = findFirstEmptyNeighbor(v1);
            if (v2 == -1) {
                System.out.println("Not unique");
                return;
            }

            processed[v1] = true;
            processed[v2] = true;

            int r1 = getRow(v1);
            int c1 = getCol(v1);
            int r2 = getRow(v2);
            int c2 = getCol(v2);

            // Assign pair values based on relative positions
            if (r1 == r2) {
                grid[r1][c1] = (c1 < c2) ? LEFT_PAIR : RIGHT_PAIR;
                grid[r2][c2] = (c1 < c2) ? RIGHT_PAIR : LEFT_PAIR;
            } else {
                grid[r1][c1] = (r1 < r2) ? UP_PAIR : DOWN_PAIR;
                grid[r2][c2] = (r1 < r2) ? DOWN_PAIR : UP_PAIR;
            }

            updateQueueForNeighbors(v1, queue, inQueue);
            updateQueueForNeighbors(v2, queue, inQueue);
            emptyCount -= 2;
        }

        if (emptyCount > 0) {
            System.out.println("Not unique");
        } else {
            printGrid();
        }
    }

    private int countEmptyCells() {
        int count = 0;
        for (int[] row : grid) {
            for (int cell : row) {
                if (cell == EMPTY) {
                    count++;
                }
            }
        }
        return count;
    }

    private int countEmptyNeighbors(int r, int c) {
        int count = 0;
        if (isInBounds(r - 1, c) && grid[r - 1][c] == EMPTY) count++;
        if (isInBounds(r + 1, c) && grid[r + 1][c] == EMPTY) count++;
        if (isInBounds(r, c - 1) && grid[r][c - 1] == EMPTY) count++;
        if (isInBounds(r, c + 1) && grid[r][c + 1] == EMPTY) count++;
        return count;
    }

    private int findFirstEmptyNeighbor(int idx) {
        int r = getRow(idx);
        int c = getCol(idx);
        if (isInBounds(r - 1, c) && grid[r - 1][c] == EMPTY) return toIndex(r - 1, c);
        if (isInBounds(r + 1, c) && grid[r + 1][c] == EMPTY) return toIndex(r + 1, c);
        if (isInBounds(r, c - 1) && grid[r][c - 1] == EMPTY) return toIndex(r, c - 1);
        if (isInBounds(r, c + 1) && grid[r][c + 1] == EMPTY) return toIndex(r, c + 1);
        return -1;
    }

    private void updateQueueForNeighbors(int v, Queue<Integer> queue, boolean[] inQueue) {
        int r = getRow(v);
        int c = getCol(v);
        int[] dr = {-1, 1, 0, 0};
        int[] dc = {0, 0, -1, 1};

        for (int i = 0; i < 4; i++) {
            int nr = r + dr[i];
            int nc = c + dc[i];
            if (isInBounds(nr, nc) && grid[nr][nc] == EMPTY) {
                int nIdx = toIndex(nr, nc);
                if (countEmptyNeighbors(nr, nc) == 1 && !inQueue[nIdx]) {
                    queue.offer(nIdx);
                    inQueue[nIdx] = true;
                }
            }
        }
    }

    private boolean isInBounds(int r, int c) {
        return r >= 0 && c >= 0 && r < rows && c < cols;
    }

    private int toIndex(int r, int c) {
        return r * cols + c;
    }

    private int getRow(int idx) {
        return idx / cols;
    }

    private int getCol(int idx) {
        return idx % cols;
    }

    private void printGrid() {
        StringBuilder sb = new StringBuilder();
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                switch (grid[r][c]) {
                    case WALL: sb.append('*'); break;
                    case LEFT_PAIR: sb.append('<'); break;
                    case RIGHT_PAIR: sb.append('>'); break;
                    case UP_PAIR: sb.append('^'); break;
                    case DOWN_PAIR: sb.append('v'); break;
                }
            }
            sb.append('\n');
        }
        System.out.print(sb);
    }

    public static void main(String[] args) throws IOException {
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            String line = br.readLine();
            if (line == null || line.trim().isEmpty()) {
                return;
            }
            String[] parts = line.trim().split("\\s+");
            int n = Integer.parseInt(parts[0]);
            int m = Integer.parseInt(parts[1]);

            int[][] grid = new int[n][m];
            for (int i = 0; i < n; i++) {
                String rowStr = br.readLine();
                if (rowStr == null) break;
                for (int j = 0; j < rowStr.length(); j++) {
                    if (rowStr.charAt(j) == '*') {
                        grid[i][j] = WALL;
                    } else {
                        grid[i][j] = EMPTY;
                    }
                }
            }

            GridPuzzleSolver solver = new GridPuzzleSolver(n, m, grid);
            solver.solve();
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

/**
 * Refactored Grid Solver.
 * 
 * Key Improvements:
 * 1. Removed static state: All mutable state is encapsulated in instance fields,
 *    making the class thread-safe and testable.
 * 2. Clear naming: `rows`/`cols` instead of `m`/`n`, `grid`/`degrees` instead of `s`/`deg`.
 * 3. Dynamic sizing: Queue and grid arrays are sized based on actual input dimensions.
 * 4. Modular design: Separated input reading, computation, and output into distinct methods.
 * 5. Standard I/O: Replaced custom fast I/O with standard `BufferedReader`/`StringTokenizer`
 *    for better maintainability while retaining performance.
 * 6. Direction mapping: Explicit arrays for deltas, characters, and opposites improve readability.
 * 7. Clean queue management: Replaced confusing `fir`/`las` indices with standard `head`/`tail`.
 */
public class Main {

    // Direction vectors: Left, Right, Up, Down
    private static final int[] DX = {0, 0, -1, 1};
    private static final int[] DY = {-1, 1, 0, 0};
    private static final char[] DIR_CHARS = {'<', '>', '^', 'v'};
    private static final int[] OPPOSITE = {1, 0, 3, 2}; // Maps direction index to its opposite

    private int rows;
    private int cols;
    private char[][] grid;
    private int[][] degrees;
    private int[] queueX;
    private int[] queueY;
    private int head;
    private int tail;

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            Main solver = new Main();
            solver.readInput(scanner);
            solver.compute();
            solver.printResult(out);
        } finally {
            out.flush();
            out.close();
        }
    }

    private void readInput(FastScanner scanner) {
        rows = scanner.nextInt();
        cols = scanner.nextInt();
        grid = new char[rows][cols];
        degrees = new int[rows][cols];
        // Each cell is enqueued at most once, so rows*cols is a safe upper bound
        queueX = new int[rows * cols];
        queueY = new int[rows * cols];

        for (int i = 0; i < rows; i++) {
            String line = scanner.next();
            grid[i] = line.toCharArray();
        }
    }

    private void compute() {
        // 1. Calculate initial degrees for each '.' cell
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == '.') {
                    for (int d = 0; d < 4; d++) {
                        int ni = i + DX[d];
                        int nj = j + DY[d];
                        if (isValid(ni, nj) && grid[ni][nj] == '.') {
                            degrees[i][j]++;
                        }
                    }
                }
            }
        }

        // 2. Initialize queue and enqueue all cells with degree 1
        head = 0;
        tail = -1;
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == '.' && degrees[i][j] == 1) {
                    enqueue(i, j);
                }
            }
        }

        // 3. Process BFS (Topological-like peeling)
        while (head <= tail) {
            int x = queueX[head];
            int y = queueY[head];
            head++;

            // Skip if already processed or degree condition changed
            if (grid[x][y] != '.' || degrees[x][y] != 1) continue;

            // Find a valid '.' neighbor to connect to (priority: Left, Right, Up, Down)
            int nx = -1, ny = -1, dirIdx = -1;
            for (int d = 0; d < 4; d++) {
                int ni = x + DX[d];
                int nj = y + DY[d];
                if (isValid(ni, nj) && grid[ni][nj] == '.') {
                    nx = ni;
                    ny = nj;
                    dirIdx = d;
                    break;
                }
            }

            if (nx == -1) continue;

            // Mark the connection directions
            grid[nx][ny] = DIR_CHARS[dirIdx];
            grid[x][y] = DIR_CHARS[OPPOSITE[dirIdx]];

            // Update degrees for neighbors of both connected cells
            int[] cells = {0, 1}; // Indices representing (x,y) and (nx,ny)
            for (int c = 0; c < 2; c++) {
                int currX = (c == 0) ? x : nx;
                int currY = (c == 0) ? y : ny;
                for (int d = 0; d < 4; d++) {
                    int ni = currX + DX[d];
                    int nj = currY + DY[d];
                    if (isValid(ni, nj) && grid[ni][nj] == '.') {
                        degrees[ni][nj]--;
                        if (degrees[ni][nj] == 1) {
                            enqueue(ni, nj);
                        }
                    }
                }
            }
        }
    }

    private void printResult(PrintWriter out) {
        // Check if any '.' cells remain unprocessed
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == '.') {
                    out.println("Not unique");
                    return;
                }
            }
        }
        // Output the resolved grid
        for (int i = 0; i < rows; i++) {
            out.println(grid[i]);
        }
    }

    private boolean isValid(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    private void enqueue(int r, int c) {
        tail++;
        queueX[tail] = r;
        queueY[tail] = c;
    }

    /**
     * Lightweight, standard-compliant FastScanner using BufferedReader.
     * Replaces the custom InputReader for better maintainability.
     */
    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner(java.io.InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input", e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            String token = next();
            return token == null ? 0 : Integer.parseInt(token);
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Solves a grid direction assignment puzzle by processing cells with a single
 * open neighbor (degree 1) using a topological sort-like approach.
 */
public class GridDirectionSolver {

    private static final int[] DX = {-1, 0, 1, 0};
    private static final int[] DY = {0, 1, 0, -1};

    private FastScanner in;
    private PrintWriter out;

    /**
     * Entry point for execution. Initializes I/O and runs the solver.
     */
    public void run() {
        in = new FastScanner();
        out = new PrintWriter(System.out);
        solve();
        out.close();
    }

    /**
     * Orchestrates the grid processing pipeline.
     */
    private void solve() {
        int n = in.nextInt();
        int m = in.nextInt();

        char[][] grid = readGrid(n, m);
        int[][] degrees = computeDegrees(grid, n, m);
        Deque<int[]> queue = initializeQueue(grid, degrees, n, m);

        while (!queue.isEmpty()) {
            int[] curr = queue.poll();
            int i = curr[0], j = curr[1];

            // Skip already processed cells
            if (grid[i][j] != '.') {
                continue;
            }

            int[] neighbor = findSingleNeighbor(grid, i, j, n, m);
            if (neighbor == null) {
                out.println("Not unique");
                return;
            }

            assignDirection(grid, i, j, neighbor[0], neighbor[1]);
            updateDegrees(grid, degrees, neighbor[0], neighbor[1], n, m, queue);
        }

        validateAndPrint(grid, n, m);
    }

    /**
     * Reads the grid dimensions and cell contents from input.
     */
    private char[][] readGrid(int n, int m) {
        char[][] grid = new char[n][m];
        for (int i = 0; i < n; i++) {
            grid[i] = in.nextToken().toCharArray();
        }
        return grid;
    }

    /**
     * Computes the number of open ('.') neighbors for each cell.
     */
    private int[][] computeDegrees(char[][] grid, int n, int m) {
        int[][] degrees = new int[n][m];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == '*') {
                    continue;
                }
                for (int d = 0; d < 4; d++) {
                    int ni = i + DX[d];
                    int nj = j + DY[d];
                    if (isValid(ni, nj, n, m) && grid[ni][nj] == '.') {
                        degrees[i][j]++;
                    }
                }
            }
        }
        return degrees;
    }

    /**
     * Initializes the processing queue with all cells having exactly one open neighbor.
     */
    private Deque<int[]> initializeQueue(char[][] grid, int[][] degrees, int n, int m) {
        Deque<int[]> queue = new ArrayDeque<>();
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (degrees[i][j] == 1) {
                    queue.offer(new int[]{i, j});
                }
            }
        }
        return queue;
    }

    /**
     * Validates grid coordinates against bounds.
     */
    private boolean isValid(int r, int c, int n, int m) {
        return r >= 0 && r < n && c >= 0 && c < m;
    }

    /**
     * Finds the single remaining open neighbor for a given cell.
     */
    private int[] findSingleNeighbor(char[][] grid, int r, int c, int n, int m) {
        for (int d = 0; d < 4; d++) {
            int nr = r + DX[d];
            int nc = c + DY[d];
            if (isValid(nr, nc, n, m) && grid[nr][nc] == '.') {
                return new int[]{nr, nc};
            }
        }
        return null;
    }

    /**
     * Assigns directional characters to both the current cell and its neighbor.
     */
    private void assignDirection(char[][] grid, int r1, int c1, int r2, int c2) {
        if (r1 == r2) {
            // Horizontal relationship
            grid[r1][c1] = c1 < c2 ? '<' : '>';
            grid[r2][c2] = c1 < c2 ? '>' : '<';
        } else {
            // Vertical relationship
            grid[r1][c1] = r1 < r2 ? '^' : 'v';
            grid[r2][c2] = r1 < r2 ? 'v' : '^';
        }
    }

    /**
     * Decrements neighbor degrees and enqueues newly formed degree-1 cells.
     */
    private void updateDegrees(char[][] grid, int[][] degrees, int r, int c, int n, int m, Deque<int[]> queue) {
        for (int d = 0; d < 4; d++) {
            int nr = r + DX[d];
            int nc = c + DY[d];
            if (isValid(nr, nc, n, m) && grid[nr][nc] == '.') {
                degrees[nr][nc]--;
                if (degrees[nr][nc] == 1) {
                    queue.offer(new int[]{nr, nc});
                }
            }
        }
    }

    /**
     * Validates that all open cells have been processed and prints the result.
     */
    private void validateAndPrint(char[][] grid, int n, int m) {
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == '.') {
                    out.println("Not unique");
                    return;
                }
            }
        }
        for (int i = 0; i < n; i++) {
            out.println(new String(grid[i]));
        }
    }

    /**
     * High-performance utility for reading structured input.
     */
    private static class FastScanner {
        private BufferedReader br;
        private StringTokenizer st;

        public FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String nextToken() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) {
                        return null;
                    }
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            String token = nextToken();
            if (token == null) throw new NoSuchElementException();
            return Integer.parseInt(token);
        }

        long nextLong() {
            String token = nextToken();
            if (token == null) throw new NoSuchElementException();
            return Long.parseLong(token);
        }

        double nextDouble() {
            String token = nextToken();
            if (token == null) throw new NoSuchElementException();
            return Double.parseDouble(token);
        }
    }

    public static void main(String[] args) {
        new GridDirectionSolver().run();
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.ArrayDeque;
import java.util.Queue;
import java.util.StringTokenizer;

/**
 * Solves the Drazil Tiles problem using a topological sort approach.
 * Processes grid cells with exactly one empty neighbor, pairs them with directional arrows,
 * and updates neighbor counts until all empty cells are resolved or proven non-unique.
 */
public class DrazilTiles {

    // Direction vectors: Up, Left, Right, Down
    private static final int[] DX = {-1, 0, 0, 1};
    private static final int[] DY = {0, -1, 1, 0};

    private static final char EMPTY = '.';
    private static final String NOT_UNIQUE = "Not unique";

    private FastScanner in;
    private PrintWriter out;

    public DrazilTiles() {
        this.in = new FastScanner(new BufferedReader(new InputStreamReader(System.in)));
        this.out = new PrintWriter(System.out);
    }

    public void solve() {
        int rows = in.nextInt();
        int cols = in.nextInt();
        char[][] grid = new char[rows][];
        for (int i = 0; i < rows; i++) {
            grid[i] = in.nextToken().toCharArray();
        }

        int emptyCellCount = 0;
        int[][] neighborCount = new int[rows][cols];
        Queue<int[]> queue = new ArrayDeque<>();

        // Initialize neighbor counts and identify initial leaf nodes (cells with exactly 1 empty neighbor)
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == EMPTY) {
                    emptyCellCount++;
                    int count = 0;
                    for (int k = 0; k < 4; k++) {
                        int ni = i + DX[k];
                        int nj = j + DY[k];
                        if (isInside(ni, nj, rows, cols) && grid[ni][nj] == EMPTY) {
                            count++;
                        }
                    }
                    neighborCount[i][j] = count;
                    if (count == 1) {
                        queue.offer(new int[]{i, j});
                    }
                }
            }
        }

        // Process cells using a topological sort-like approach
        while (!queue.isEmpty()) {
            int[] current = queue.poll();
            int currRow = current[0];
            int currCol = current[1];

            // Skip if already processed/paired
            if (grid[currRow][currCol] != EMPTY) {
                continue;
            }

            for (int dir = 0; dir < 4; dir++) {
                int nextRow = currRow + DX[dir];
                int nextCol = currCol + DY[dir];

                if (isInside(nextRow, nextCol, rows, cols) && grid[nextRow][nextCol] == EMPTY) {
                    emptyCellCount -= 2;

                    char currentArrow, nextArrow;
                    switch (dir) {
                        case 0: // Up
                            currentArrow = 'v'; nextArrow = '^'; break;
                        case 1: // Left
                            currentArrow = '>'; nextArrow = '<'; break;
                        case 2: // Right
                            currentArrow = '<'; nextArrow = '>'; break;
                        case 3: // Down
                            currentArrow = '^'; nextArrow = 'v'; break;
                        default: continue;
                    }

                    grid[currRow][currCol] = currentArrow;
                    grid[nextRow][nextCol] = nextArrow;

                    // Update neighbor counts for adjacent empty cells
                    for (int k = 0; k < 4; k++) {
                        int neighborRow = nextRow + DX[k];
                        int neighborCol = nextCol + DY[k];
                        if (isInside(neighborRow, neighborCol, rows, cols) && grid[neighborRow][neighborCol] == EMPTY) {
                            if (--neighborCount[neighborRow][neighborCol] == 1) {
                                queue.offer(new int[]{neighborRow, neighborCol});
                            }
                        }
                    }
                    break; // Each cell is paired exactly once
                }
            }
        }

        if (emptyCellCount != 0) {
            out.println(NOT_UNIQUE);
        } else {
            for (int i = 0; i < rows; i++) {
                out.println(new String(grid[i]));
            }
        }
        out.flush();
    }

    /**
     * Checks if the given coordinates are within the grid boundaries.
     */
    private boolean isInside(int row, int col, int rows, int cols) {
        return row >= 0 && row < rows && col >= 0 && col < cols;
    }

    public static void main(String[] args) {
        new DrazilTiles().solve();
    }

    /**
     * Optimized scanner for fast input reading in competitive programming environments.
     */
    static class FastScanner {
        private final BufferedReader in;
        private StringTokenizer st;

        public FastScanner(BufferedReader in) {
            this.in = in;
        }

        public String nextToken() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = in.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(nextToken());
        }

        public long nextLong() {
            return Long.parseLong(nextToken());
        }

        public double nextDouble() {
            return Double.parseDouble(nextToken());
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.ArrayDeque;
import java.util.StringTokenizer;

/**
 * Solves a grid path orientation problem.
 * Processes '.' cells to assign directional arrows based on connectivity.
 */
public class GridPathSolver {

    // Direction vectors: Up, Down, Left, Right
    private static final int[] DX = {0, 0, -1, 1};
    private static final int[] DY = {-1, 1, 0, 0};
    // Corresponding characters for each direction index
    private static final char[] DIRECTION_CHARS = {'^', 'v', '<', '>'};

    private final int rows;
    private final int cols;
    private char[][] grid;

    public static void main(String[] args) {
        FastScanner sc = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            GridPathSolver solver = new GridPathSolver(sc.nextInt(), sc.nextInt());
            solver.readGrid(sc);
            solver.processGrid();
            solver.outputGrid(out);
        } finally {
            out.flush();
            out.close();
        }
    }

    public GridPathSolver(int rows, int cols) {
        this.rows = rows;
        this.cols = cols;
        this.grid = new char[rows][cols];
    }

    /**
     * Reads the grid from the scanner input.
     */
    private void readGrid(FastScanner sc) {
        for (int y = 0; y < rows; y++) {
            String line = sc.next();
            grid[y] = line.toCharArray();
        }
    }

    /**
     * Processes the grid to assign directional arrows to connected '.' cells.
     */
    private void processGrid() {
        ArrayDeque<Integer> queueX = new ArrayDeque<>();
        ArrayDeque<Integer> queueY = new ArrayDeque<>();

        // Seed the queue with all empty cells
        for (int y = 0; y < rows; y++) {
            for (int x = 0; x < cols; x++) {
                if (grid[y][x] == '.') {
                    queueX.add(x);
                    queueY.add(y);
                }
            }
        }

        while (!queueX.isEmpty()) {
            int x = queueX.poll();
            int y = queueY.poll();

            // Skip if already processed into a directional cell
            if (grid[y][x] != '.') {
                continue;
            }

            int adjacentEmptyCount = 0;
            for (int d = 0; d < 4; d++) {
                int nx = x + DX[d];
                int ny = y + DY[d];
                if (isValid(nx, ny) && grid[ny][nx] == '.') {
                    adjacentEmptyCount++;
                }
            }

            // If exactly one adjacent empty cell, establish a directed path
            if (adjacentEmptyCount == 1) {
                for (int d = 0; d < 4; d++) {
                    int nx = x + DX[d];
                    int ny = y + DY[d];
                    if (isValid(nx, ny) && grid[ny][nx] == '.') {
                        // Assign opposite direction to current cell, forward direction to neighbor
                        int oppositeD = (d % 2 == 0) ? d + 1 : d - 1;
                        grid[y][x] = DIRECTION_CHARS[oppositeD];
                        grid[ny][nx] = DIRECTION_CHARS[d];

                        // Add neighbor's surroundings to queue for further propagation
                        for (int nd = 0; nd < 4; nd++) {
                            int nnx = nx + DX[nd];
                            int nny = ny + DY[nd];
                            if (isValid(nnx, nny)) {
                                queueX.add(nnx);
                                queueY.add(nny);
                            }
                        }
                        break; // Only one adjacent cell, so we're done for this node
                    }
                }
            }
        }
    }

    /**
     * Checks if coordinates are within grid bounds.
     */
    private boolean isValid(int x, int y) {
        return x >= 0 && y >= 0 && x < cols && y < rows;
    }

    /**
     * Outputs the result grid or a message if the solution is not unique.
     */
    private void outputGrid(PrintWriter out) {
        boolean hasEmptyCells = false;
        outerLoop:
        for (int y = 0; y < rows; y++) {
            for (int x = 0; x < cols; x++) {
                if (grid[y][x] == '.') {
                    hasEmptyCells = true;
                    break outerLoop;
                }
            }
        }

        if (hasEmptyCells) {
            out.println("Not unique");
        } else {
            for (int y = 0; y < rows; y++) {
                out.println(new String(grid[y]));
            }
        }
    }

    /**
     * Standard fast input scanner using BufferedReader and StringTokenizer.
     */
    public static class FastScanner {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastScanner(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input", e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            String token = next();
            return (token == null) ? 0 : Integer.parseInt(token);
        }
    }
}

import java.io.*;
import java.util.*;

public class Main {

    // Direction vectors: Up, Left, Down, Right
    private static final int[][] DIRECTIONS = {{-1, 0}, {0, -1}, {1, 0}, {0, 1}};

    public static void main(String[] args) {
        // Use try-with-resources to ensure streams are properly closed
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
             PrintWriter writer = new PrintWriter(new OutputStreamWriter(System.out))) {

            GridSolver solver = new GridSolver(reader, writer);
            solver.solve();
        } catch (IOException e) {
            System.err.println("I/O Error: " + e.getMessage());
            System.exit(1);
        }
    }

    /**
     * Encapsulates the grid processing algorithm and input/output handling.
     */
    static class GridSolver {
        private final BufferedReader reader;
        private final PrintWriter writer;
        private StringTokenizer tokenizer;

        public GridSolver(BufferedReader reader, PrintWriter writer) {
            this.reader = reader;
            this.writer = writer;
        }

        public void solve() throws IOException {
            int rows = nextInt();
            int cols = nextInt();
            char[][] grid = new char[rows][];

            for (int i = 0; i < rows; i++) {
                grid[i] = next().toCharArray();
            }

            int[][] adjCount = new int[rows][cols];
            Queue<Point> queue = new LinkedList<>();

            // 1. Calculate initial adjacency counts and seed the queue
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] == '*') continue;

                    int count = 0;
                    for (int[] dir : DIRECTIONS) {
                        int nr = r + dir[0];
                        int nc = c + dir[1];
                        if (isValid(nr, nc, rows, cols) && grid[nr][nc] == '.') {
                            count++;
                        }
                    }
                    adjCount[r][c] = count;
                    if (count == 1) {
                        queue.add(new Point(r, c));
                    }
                }
            }

            // 2. Process cells with exactly one open neighbor (topological peeling)
            while (!queue.isEmpty()) {
                Point current = queue.poll();
                int r = current.row;
                int c = current.col;

                if (grid[r][c] != '.') continue;

                // Find the single adjacent '.' neighbor
                Point neighbor = findNeighbor(r, c, rows, cols, grid);
                if (neighbor == null) {
                    writer.println("Not unique");
                    return;
                }

                // Assign directional arrows based on relative coordinates
                assignArrows(grid, r, c, neighbor.row, neighbor.col);

                // Update adjacency counts for the neighbor's surroundings
                for (int[] dir : DIRECTIONS) {
                    int nr = neighbor.row + dir[0];
                    int nc = neighbor.col + dir[1];
                    if (isValid(nr, nc, rows, cols) && grid[nr][nc] == '.' && adjCount[nr][nc] > 0) {
                        adjCount[nr][nc]--;
                        // Since adjCount only decreases, == 1 acts as a one-time trigger
                        if (adjCount[nr][nc] == 1) {
                            queue.add(new Point(nr, nc));
                        }
                    }
                }
            }

            // 3. Verify all '.' cells were processed
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] == '.') {
                        writer.println("Not unique");
                        return;
                    }
                }
            }

            // 4. Output the final grid
            for (int r = 0; r < rows; r++) {
                writer.println(new String(grid[r]));
            }
        }

        private boolean isValid(int r, int c, int rows, int cols) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }

        private Point findNeighbor(int r, int c, int rows, int cols, char[][] grid) {
            for (int[] dir : DIRECTIONS) {
                int nr = r + dir[0];
                int nc = c + dir[1];
                if (isValid(nr, nc, rows, cols) && grid[nr][nc] == '.') {
                    return new Point(nr, nc);
                }
            }
            return null;
        }

        private void assignArrows(char[][] grid, int r1, int c1, int r2, int c2) {
            if (r1 == r2) {
                if (c1 < c2) {
                    grid[r1][c1] = '<';
                    grid[r2][c2] = '>';
                } else {
                    grid[r1][c1] = '>';
                    grid[r2][c2] = '<';
                }
            } else {
                if (r1 > r2) {
                    grid[r1][c1] = 'v';
                    grid[r2][c2] = '^';
                } else {
                    grid[r1][c1] = '^';
                    grid[r2][c2] = 'v';
                }
            }
        }

        private String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        private int nextInt() throws IOException {
            String token = next();
            return token == null ? 0 : Integer.parseInt(token);
        }
    }

    /**
     * Immutable coordinate holder to replace integer encoding/decoding.
     */
    static class Point {
        final int row;
        final int col;

        Point(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }
}

import java.io.*;
import java.util.*;

public class DirectionGridSolver {
    // Constants for grid states and directions
    private static final char OBSTACLE_CHAR = '*';
    private static final int STATE_OBSTACLE = -1;
    private static final int STATE_EMPTY = -2;
    private static final String DIRECTIONS = "^v<>";
    private static final int[] DR = {-1, 1, 0, 0};
    private static final int[] DC = {0, 0, -1, 1};

    // Grid dimensions
    private final int rows, cols;

    // Flattened data structures for performance
    // gridState: Stores STATE_OBSTACLE, STATE_EMPTY, or direction index (0-3)
    private final int[][] gridState;

    // adj: Flattened adjacency list. adj[nodeId * 4 + dirIndex] = neighborId
    private final int[] adj;

    // nodeCoords: Flattened coordinates. nodeCoords[nodeId * 2] = row, nodeCoords[nodeId * 2 + 1] = col
    private final int[] nodeCoords;

    // I/O references
    private final FastScanner scanner;
    private final PrintWriter out;

    public DirectionGridSolver(FastScanner scanner, PrintWriter out) {
        this.scanner = scanner;
        this.out = out;
        this.rows = scanner.nextInt();
        this.cols = scanner.nextInt();

        this.gridState = new int[rows][cols];
        this.adj = new int[rows * cols * 4];
        Arrays.fill(this.adj, -1);
        this.nodeCoords = new int[rows * cols * 2];
    }

    /** Entry point for the solver logic */
    public void solve() {
        readGrid();
        buildGraph();
        processQueue();
        validateAndPrint();
    }

    /** Reads the input grid and initializes cell states */
    private void readGrid() {
        for (int r = 0; r < rows; r++) {
            String line = scanner.next();
            for (int c = 0; c < cols; c++) {
                gridState[r][c] = (line.charAt(c) == OBSTACLE_CHAR) ? STATE_OBSTACLE : STATE_EMPTY;
            }
        }
    }

    /** Computes a unique node ID from grid coordinates */
    private int nodeId(int r, int c) {
        if (r < 0 || c < 0 || r >= rows || c >= cols) return -1;
        return r * cols + c;
    }

    /** Converts a displacement (dr, dc) to a direction index (0-3) */
    private int directionIndex(int dr, int dc) {
        if (dr == -1) return 0; // ^
        if (dr == 1)  return 1; // v
        if (dc == -1) return 2; // <
        return 3;               // >
    }

    /** Builds the adjacency graph for all non-obstacle cells */
    private void buildGraph() {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (gridState[r][c] == STATE_EMPTY) {
                    int id = nodeId(r, c);
                    nodeCoords[id * 2] = r;
                    nodeCoords[id * 2 + 1] = c;

                    for (int d = 0; d < 4; d++) {
                        int nr = r + DR[d];
                        int nc = c + DC[d];
                        int neighborId = nodeId(nr, nc);
                        if (neighborId != -1 && gridState[nr][nc] == STATE_EMPTY) {
                            // Each direction maps to exactly one slot in the flattened array
                            adj[id * 4 + d] = neighborId;
                        }
                    }
                }
            }
        }
    }

    /** Peels nodes with degree 1 and assigns directions along edges */
    private void processQueue() {
        int[] queue = new int[rows * cols];
        int head = 0, tail = 0;

        // Initialize queue with nodes that have exactly one neighbor
        for (int id = 0; id < rows * cols; id++) {
            if (gridState[nodeCoords[id * 2]][nodeCoords[id * 2 + 1]] != STATE_EMPTY) continue;

            int degree = 0;
            for (int d = 0; d < 4; d++) {
                if (adj[id * 4 + d] != -1) degree++;
            }
            if (degree == 1) {
                queue[tail++] = id;
            }
        }

        while (head < tail) {
            int currentId = queue[head++];
            int r = nodeCoords[currentId * 2];
            int c = nodeCoords[currentId * 2 + 1];

            // Find the single remaining neighbor
            int neighborId = -1;
            int dirToNeighbor = -1;
            for (int d = 0; d < 4; d++) {
                if (adj[currentId * 4 + d] != -1) {
                    neighborId = adj[currentId * 4 + d];
                    dirToNeighbor = d;
                    adj[currentId * 4 + d] = -1; // Remove edge
                    break;
                }
            }

            if (neighborId == -1) continue;

            int r2 = nodeCoords[neighborId * 2];
            int c2 = nodeCoords[neighborId * 2 + 1];

            // Assign directional characters to both cells
            gridState[r][c] = directionIndex(r2 - r, c2 - c);
            gridState[r2][c2] = directionIndex(r - r2, c - c2);

            // Update neighbor's degree and check if it becomes a new leaf
            for (int d = 0; d < 4; d++) {
                int neighbor = adj[neighborId * 4 + d];
                if (neighbor == -1) continue;

                // Remove the edge back to currentId
                for (int dd = 0; dd < 4; dd++) {
                    if (adj[neighbor * 4 + dd] == currentId) {
                        adj[neighbor * 4 + dd] = -1;
                        break;
                    }
                }

                // Recalculate degree
                int degree = 0;
                for (int dd = 0; dd < 4; dd++) {
                    if (adj[neighbor * 4 + dd] != -1) degree++;
                }
                if (degree == 1) {
                    queue[tail++] = neighbor;
                }
            }
        }
    }

    /** Validates that all cells were processed and prints the result */
    private void validateAndPrint() {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (gridState[r][c] == STATE_EMPTY) {
                    out.println("Not unique");
                    return;
                }
            }
        }

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (gridState[r][c] == STATE_OBSTACLE) {
                    out.print(OBSTACLE_CHAR);
                } else {
                    out.print(DIRECTIONS.charAt(gridState[r][c]));
                }
            }
            out.println();
        }
    }

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner();
        PrintWriter out = new PrintWriter(System.out);
        new DirectionGridSolver(scanner, out).solve();
        out.flush();
    }
}

/**
 * FastScanner for efficient competitive programming I/O.
 * Preserved from original to maintain performance characteristics.
 */
class FastScanner {
    private final InputStream stream;
    private final byte[] buf = new byte[1024];
    private int curChar;
    private int numChars;

    public FastScanner() {
        this.stream = System.in;
    }

    int read() {
        if (numChars == -1) {
            throw new InputMismatchException();
        }
        if (curChar >= numChars) {
            curChar = 0;
            try {
                numChars = stream.read(buf);
            } catch (IOException e) {
                throw new InputMismatchException();
            }
            if (numChars <= 0) {
                return -1;
            }
        }
        return buf[curChar++];
    }

    boolean isSpaceChar(int c) {
        return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
    }

    boolean isEndline(int c) {
        return c == '\n' || c == '\r' || c == -1;
    }

    int nextInt() {
        return Integer.parseInt(next());
    }

    long nextLong() {
        return Long.parseLong(next());
    }

    double nextDouble() {
        return Double.parseDouble(next());
    }

    String next() {
        int c = read();
        while (isSpaceChar(c)) {
            c = read();
        }
        StringBuilder res = new StringBuilder();
        do {
            res.appendCodePoint(c);
            c = read();
        } while (!isSpaceChar(c));
        return res.toString();
    }

    String nextLine() {
        int c = read();
        while (isEndline(c)) {
            c = read();
        }
        StringBuilder res = new StringBuilder();
        do {
            res.appendCodePoint(c);
            c = read();
        } while (!isEndline(c));
        return res.toString();
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.ArrayDeque;
import java.util.NoSuchElementException;
import java.util.Queue;
import java.util.StringTokenizer;
import java.util.UncheckedIOException;

public class Dreamoon {

    private static final char EMPTY = '.';
    private static final char BLOCK = '*';
    private static final String NOT_UNIQUE = "Not unique";
    private static final int[][] DIRECTIONS = { {-1, 0}, {0, -1}, {0, 1}, {1, 0} };

    public static void main(String[] args) {
        FastScanner sc = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out);
        try {
            solve(sc, out);
        } finally {
            out.flush();
        }
    }

    private static void solve(FastScanner sc, PrintWriter out) {
        int n = sc.nextInt();
        int m = sc.nextInt();
        char[][] grid = new char[n][];
        for (int i = 0; i < n; i++) {
            grid[i] = sc.next().toCharArray();
        }

        int[][] adjacentDots = new int[n][m];
        Queue<Point> queue = new ArrayDeque<>();

        // Phase 1: Initialize adjacency counts and seed the queue
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == BLOCK) continue;

                int count = 0;
                for (int[] dir : DIRECTIONS) {
                    if (isInside(i + dir[0], j + dir[1], n, m) && grid[i + dir[0]][j + dir[1]] == EMPTY) {
                        count++;
                    }
                }

                if (count == 0) {
                    out.println(NOT_UNIQUE);
                    return;
                }
                adjacentDots[i][j] = count;
                if (count == 1) {
                    queue.add(new Point(i, j));
                }
            }
        }

        // Phase 2: Process constrained cells (constraint propagation)
        while (!queue.isEmpty()) {
            Point p = queue.poll();
            int r = p.r, c = p.c;

            // Find the single adjacent empty cell
            int nr = -1, nc = -1;
            for (int[] dir : DIRECTIONS) {
                int ni = r + dir[0], nj = c + dir[1];
                if (isInside(ni, nj, n, m) && grid[ni][nj] == EMPTY) {
                    nr = ni;
                    nc = nj;
                    break;
                }
            }

            if (nr == -1) continue; // Should not occur given initial validation

            placeArrows(grid, r, c, nr, nc);

            // Decrement counts for the connected cells
            adjacentDots[r][c]--;
            adjacentDots[nr][nc]--;

            // Propagate constraints to the neighbor's other adjacent cells
            for (int[] dir : DIRECTIONS) {
                int nnr = nr + dir[0], nnc = nc + dir[1];
                if (isInside(nnr, nnc, n, m) && grid[nnr][nnc] == EMPTY) {
                    adjacentDots[nnr][nnc]--;
                    if (adjacentDots[nnr][nnc] == 0) {
                        out.println(NOT_UNIQUE);
                        return;
                    }
                    if (adjacentDots[nnr][nnc] == 1) {
                        queue.add(new Point(nnr, nnc));
                    }
                }
            }
        }

        // Phase 3: Final validation
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == EMPTY) {
                    out.println(NOT_UNIQUE);
                    return;
                }
            }
        }

        // Phase 4: Output the solved grid
        for (int i = 0; i < n; i++) {
            out.println(new String(grid[i]));
        }
    }

    private static boolean isInside(int r, int c, int n, int m) {
        return r >= 0 && r < n && c >= 0 && c < m;
    }

    private static void placeArrows(char[][] grid, int r1, int c1, int r2, int c2) {
        if (r1 == r2) { // Horizontal placement
            int minC = Math.min(c1, c2);
            grid[r1][minC] = '<';
            grid[r1][minC + 1] = '>';
        } else { // Vertical placement
            int minR = Math.min(r1, r2);
            grid[minR][c1] = '^';
            grid[minR + 1][c1] = 'v';
        }
    }

    /** Lightweight coordinate holder */
    private static class Point {
        final int r, c;
        Point(int r, int c) { this.r = r; this.c = c; }
    }

    /** Fast I/O helper class */
    private static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            String s = next();
            if (s == null) throw new NoSuchElementException();
            return Integer.parseInt(s);
        }
    }
}

