/**
 * Solves the grid matching problem using a greedy matching strategy.
 * Identifies uniquely pairable cells and assigns directional arrows accordingly.
 */
class GridSolver {
    private static final int[] ROW_DELTA = {-1, 1, 0, 0};
    private static final int[] COL_DELTA = {0, 0, -1, 1};
    private static final int UNMATCHED = -1;

    /**
     * Executes the solving process.
     *
     * @param in  Fast input reader
     * @param out Fast output writer
     */
    public void solve(InputReader in, OutputWriter out) {
        int n = in.readInt();
        int m = in.readInt();
        char[][] grid = new char[n][m];
        for (int i = 0; i < n; i++) {
            grid[i] = in.next().toCharArray();
        }

        int[] degree = new int[n * m];
        boolean[] visited = new boolean[n * m];
        int[] matchedWith = new int[n * m];
        Arrays.fill(matchedWith, UNMATCHED);

        // Calculate initial neighbor degrees for each non-wall cell
        calculateDegrees(grid, n, m, degree);

        // Initialize queue with cells having degree <= 1 (leaves or isolated)
        Queue<Integer> queue = new ArrayDeque<>();
        for (int i = 0; i < n * m; i++) {
            if (degree[i] <= 1) {
                visited[i] = true;
                queue.add(i);
            }
        }

        // Perform greedy matching until no more matches can be made
        performMatching(grid, n, m, degree, visited, matchedWith, queue);

        // Apply matched arrows to the grid
        applyArrows(grid, n, m, matchedWith);

        // Check for unassigned cells
        if (hasUnassignedCells(grid, n, m)) {
            out.println("Not unique");
            return;
        }

        // Output the result
        printGrid(out, grid, n, m);
    }

    private void calculateDegrees(char[][] grid, int n, int m, int[] degree) {
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < m; c++) {
                if (grid[r][c] == '*') continue;
                for (int d = 0; d < 4; d++) {
                    int nr = r + ROW_DELTA[d];
                    int nc = c + COL_DELTA[d];
                    if (isValid(nr, nc, n, m) && grid[nr][nc] != '*') {
                        degree[toIndex(nr, nc, m)]++;
                    }
                }
            }
        }
    }

    private void performMatching(char[][] grid, int n, int m, int[] degree, boolean[] visited, int[] matchedWith, Queue<Integer> queue) {
        while (!queue.isEmpty()) {
            int p = queue.poll();
            int r1 = p / m;
            int c1 = p % m;

            for (int d = 0; d < 4; d++) {
                int r2 = r1 + ROW_DELTA[d];
                int c2 = c1 + COL_DELTA[d];

                if (!isValid(r2, c2, n, m) || grid[r1][c1] == '*' || grid[r2][c2] == '*') {
                    continue;
                }

                int i = toIndex(r2, c2, m);
                if (matchedWith[i] == UNMATCHED && matchedWith[p] == UNMATCHED) {
                    matchedWith[i] = p;
                    matchedWith[p] = i;
                    if (!visited[i]) {
                        visited[i] = true;
                        queue.add(i);
                    }
                }
                if (--degree[i] <= 1 && !visited[i]) {
                    visited[i] = true;
                    queue.add(i);
                }
            }
        }
    }

    private void applyArrows(char[][] grid, int n, int m, int[] matchedWith) {
        for (int i = 0; i < n * m; i++) {
            if (matchedWith[i] == UNMATCHED) continue;

            int r1 = i / m;
            int c1 = i % m;
            int r2 = matchedWith[i] / m;
            int c2 = matchedWith[i] % m;

            if (r1 == r2) {
                grid[r1][Math.min(c1, c2)] = '<';
                grid[r1][Math.max(c1, c2)] = '>';
            } else {
                grid[Math.min(r1, r2)][c1] = '^';
                grid[Math.max(r1, r2)][c2] = 'v';
            }
        }
    }

    private boolean hasUnassignedCells(char[][] grid, int n, int m) {
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < m; c++) {
                if (grid[r][c] == '.') return true;
            }
        }
        return false;
    }

    private void printGrid(OutputWriter out, char[][] grid, int n, int m) {
        for (int r = 0; r < n; r++) {
            out.println(new String(grid[r]));
        }
    }

    private boolean isValid(int r, int c, int n, int m) {
        return r >= 0 && r < n && c >= 0 && c < m;
    }

    private int toIndex(int r, int c, int m) {
        return r * m + c;
    }
}

/**
 * Fast input reader for competitive programming and performance-critical applications.
 */
class InputReader {
    private final InputStream stream;
    private final byte[] buf = new byte[1024];
    private int curChar;
    private int numChars;
    private SpaceCharFilter filter;

    public InputReader(InputStream stream) {
        this.stream = stream;
    }

    public int read() {
        if (numChars == -1) {
            throw new InputMismatchException();
        }
        if (curChar >= numChars) {
            curChar = 0;
            try {
                numChars = stream.read(buf);
            } catch (IOException e) {
                throw new InputMismatchException();
            }
            if (numChars <= 0) {
                return -1;
            }
        }
        return buf[curChar++];
    }

    public int readInt() {
        int c = read();
        while (isSpaceChar(c)) {
            c = read();
        }
        int sgn = 1;
        if (c == '-') {
            sgn = -1;
            c = read();
        }
        int res = 0;
        do {
            if (c < '0' || c > '9') {
                throw new InputMismatchException();
            }
            res *= 10;
            res += c - '0';
            c = read();
        } while (!isSpaceChar(c));
        return res * sgn;
    }

    public String readString() {
        int c = read();
        while (isSpaceChar(c)) {
            c = read();
        }
        StringBuilder res = new StringBuilder();
        do {
            if (Character.isValidCodePoint(c)) {
                res.appendCodePoint(c);
            }
            c = read();
        } while (!isSpaceChar(c));
        return res.toString();
    }

    public boolean isSpaceChar(int c) {
        return filter != null ? filter.isSpaceChar(c) : isWhitespace(c);
    }

    public static boolean isWhitespace(int c) {
        return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
    }

    public String next() {
        return readString();
    }

    public interface SpaceCharFilter {
        boolean isSpaceChar(int ch);
    }
}

/**
 * Fast output writer for competitive programming and performance-critical applications.
 */
class OutputWriter {
    private final PrintWriter writer;

    public OutputWriter(OutputStream outputStream) {
        writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(outputStream)));
    }

    public void print(Object... objects) {
        for (int i = 0; i < objects.length; i++) {
            if (i != 0) {
                writer.print(' ');
            }
            writer.print(objects[i]);
        }
    }

    public void println(Object... objects) {
