        writer.println();
    }

    public void close() {
        writer.close();
    }
}

import java.util.*;
import java.io.*;

/**
 * A solver for grid path problems involving unique path identification
 * and direction symbol assignment.
 */
public class GridPathSolver {

    // Direction vectors: Right, Left, Down, Up
    private static final int[][] DIRECTIONS = {
        {0, 1}, {0, -1}, {1, 0}, {-1, 0}
    };

    // Mapping arrays based on original logic:
    // SOURCE_SYMBOLS[k] is assigned to the source cell (p)
    // TARGET_SYMBOLS[k] is assigned to the neighbor cell (x, y)
    // Corresponds to original: bla = "<>^v", ble = "><v^"
    private static final char[] SOURCE_SYMBOLS = {'<', '>', '^', 'v'};
    private static final char[] TARGET_SYMBOLS = {'>', '<', 'v', '^'};

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner();

        // Basic input validation
        if (!scanner.hasMoreTokens()) {
            return;
        }

        int n = scanner.nextInt();
        int m = scanner.nextInt();
        char[][] grid = new char[n][m];

        for (int i = 0; i < n; i++) {
            grid[i] = scanner.next().toCharArray();
        }

        solve(grid, n, m);
    }

    /**
     * Solves the grid path problem by processing cells with degree 1
     * and propagating the path filling logic.
     */
    private static void solve(char[][] grid, int n, int m) {
        int[][] degrees = new int[n][m];
        Deque<Point> queue = new LinkedList<>();

        // 1. Calculate initial degrees for '.' cells and populate queue
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == '.') {
                    int degree = 0;
                    for (int[] d : DIRECTIONS) {
                        int r = i + d[0];
                        int c = j + d[1];
                        if (isValid(r, c, n, m) && grid[r][c] == '.') {
                            degree++;
                        }
                    }
                    degrees[i][j] = degree;
                    if (degree == 1) {
                        queue.add(new Point(i, j));
                    }
                }
            }
        }

        // 2. Process the queue (Topological sort / Peeling logic)
        while (!queue.isEmpty()) {
            Point p = queue.pollFirst();

            for (int k = 0; k < DIRECTIONS.length; k++) {
                int r = p.x + DIRECTIONS[k][0];
                int c = p.y + DIRECTIONS[k][1];

                // Check if neighbor is valid and unprocessed ('.')
                if (isValid(r, c, n, m) && grid[r][c] == '.') {

                    // Assign directional symbols
                    grid[p.x][p.y] = SOURCE_SYMBOLS[k];
                    grid[r][c] = TARGET_SYMBOLS[k];

                    // Decrement degrees for the processed cells
                    degrees[p.x][p.y]--;
                    degrees[r][c]--;

                    // Propagate degree reduction to neighbors of the target cell (r, c)
                    for (int[] d : DIRECTIONS) {
                        int r2 = r + d[0];
                        int c2 = c + d[1];
                        if (isValid(r2, c2, n, m) && grid[r2][c2] == '.') {
                            degrees[r2][c2]--;
                            // If degree drops to 1, it becomes a new endpoint
                            if (degrees[r2][c2] == 1) {
                                queue.add(new Point(r2, c2));
                            }
                        }
                    }
                }
            }
        }

        // 3. Validation: Check if any '.' remains
        boolean allProcessed = true;
        outerLoop:
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == '.') {
                    allProcessed = false;
                    break outerLoop;
                }
            }
        }

        // 4. Output result
        if (!allProcessed) {
            System.out.println("Not unique");
        } else {
            for (int i = 0; i < n; i++) {
                System.out.println(new String(grid[i]));
            }
        }
    }

    /**
     * Checks if coordinates are within grid bounds.
     */
    private static boolean isValid(int x, int y, int n, int m) {
        return x >= 0 && x < n && y >= 0 && y < m;
    }

    /**
     * Helper class to represent a coordinate point.
     */
    static class Point {
        int x, y;

        public Point(int x, int y) {
            this.x = x;
            this.y = y;
        }
    }

    /**
     * FastScanner for efficient input reading.
     */
    static class FastScanner {
        BufferedReader reader;
        StringTokenizer tokenizer;

        public FastScanner() {
            reader = new BufferedReader(new InputStreamReader(System.in), 32768);
            tokenizer = null;
        }

        public boolean hasMoreTokens() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return false;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return true;
        }

        public String next() {
            if (hasMoreTokens()) {
                return tokenizer.nextToken();
            }
            throw new NoSuchElementException();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }

        public double nextDouble() {
            return Double.parseDouble(next());
        }

        public String nextLine() {
            try {
                return reader.readLine();
            } catch (IOException e) {
                throw new RuntimeException(e);
            }
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.util.ArrayDeque;
import java.util.Deque;
import java.util.StringTokenizer;

/**
 * Solves the "Drazil and Tiles" problem using a topological sort approach on a grid graph.
 * Empty cells ('.') are treated as nodes, and adjacent empty cells are connected by edges.
 * Cells with exactly one neighbor are processed first, placing directional arrows between them,
 * and propagating the constraint to their remaining neighbors.
 */
public class CR292_drazil_and_tiles {

    // Direction deltas: up, left, down, right
    private static final int[] DELTA_ROW = {-1, 0, 1, 0};
    private static final int[] DELTA_COL = {0, -1, 0, 1};
    private static final int NUM_DIRECTIONS = 4;

    public static void main(String[] args) throws IOException {
        FastScanner scanner = new FastScanner(System.in);
        int rows = scanner.nextInt();
        int cols = scanner.nextInt();

        char[][] grid = new char[rows][cols];
        int[][] degree = new int[rows][cols];

        // 1. Read grid and compute initial neighbor counts for empty cells
        for (int i = 0; i < rows; i++) {
            String line = scanner.next();
            grid[i] = line.toCharArray();
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == '.') {
                    degree[i][j] = countEmptyNeighbors(i, j, grid, rows, cols);
                }
            }
        }

        // 2. Initialize queue with boundary cells (degree == 1)
        Deque<Integer> queue = new ArrayDeque<>();
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (degree[i][j] == 1) {
                    queue.add(i * cols + j); // Encode coordinates as a single integer
                }
            }
        }

        // 3. Process queue (topological sort)
        processQueue(grid, degree, queue, rows, cols);

        // 4. Validate: if any '.' remains, the solution is not unique
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == '.') {
                    System.out.println("Not unique");
                    return;
                }
            }
        }

        // 5. Output result
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < rows; i++) {
            sb.append(grid[i]).append('\n');
        }
        System.out.print(sb);
    }

    /**
     * Counts the number of adjacent empty cells ('.') for a given position.
     */
    private static int countEmptyNeighbors(int r, int c, char[][] grid, int rows, int cols) {
        int count = 0;
        for (int d = 0; d < NUM_DIRECTIONS; d++) {
            int nr = r + DELTA_ROW[d];
            int nc = c + DELTA_COL[d];
            if (isValid(nr, nc, rows, cols) && grid[nr][nc] == '.') {
                count++;
            }
        }
        return count;
    }

    /**
     * Checks if coordinates are within grid bounds.
     */
    private static boolean isValid(int r, int c, int rows, int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /**
     * Processes the queue using a topological sort approach.
     * Places arrows between cells with exactly one empty neighbor and updates neighbor degrees.
     */
    private static void processQueue(char[][] grid, int[][] degree, Deque<Integer> queue, int rows, int cols) {
        while (!queue.isEmpty()) {
            int idx = queue.poll();
            int r = idx / cols;
            int c = idx % cols;

            // Skip if already processed (marked with an arrow)
            if (grid[r][c] != '.') {
                continue;
            }

            // Find the single remaining empty neighbor
            int nr = -1, nc = -1;
            for (int d = 0; d < NUM_DIRECTIONS; d++) {
                int nextR = r + DELTA_ROW[d];
                int nextC = c + DELTA_COL[d];
                if (isValid(nextR, nextC, rows, cols) && grid[nextR][nextC] == '.') {
                    nr = nextR;
                    nc = nextC;
                    break;
                }
            }

            // Safety check: if no empty neighbor exists, skip
            if (nr == -1) {
                continue;
            }

            // Place directional arrows between the two connected cells
            placeArrows(grid, r, c, nr, nc);

            // Decrement degree of adjacent empty cells to the newly placed cell
            for (int d = 0; d < NUM_DIRECTIONS; d++) {
                int adjR = nr + DELTA_ROW[d];
                int adjC = nc + DELTA_COL[d];
                if (isValid(adjR, adjC, rows, cols) && grid[adjR][adjC] == '.') {
                    degree[adjR][adjC]--;
                    if (degree[adjR][adjC] == 1) {
                        queue.add(adjR * cols + adjC);
                    }
                }
            }
        }
    }

    /**
     * Places appropriate arrow characters between two adjacent cells.
     * Assumes cells are strictly horizontal or vertical neighbors.
     */
    private static void placeArrows(char[][] grid, int r1, int c1, int r2, int c2) {
        if (r1 == r2) {
            // Horizontal placement
            grid[r1][Math.min(c1, c2)] = '<';
            grid[r1][Math.max(c1, c2)] = '>';
        } else {
            // Vertical placement (columns must be equal)
            grid[Math.min(r1, r2)][c1] = '^';
            grid[Math.max(r1, r2)][c1] = 'v';
        }
    }

    /**
     * Fast input reader for competitive programming scenarios.
     */
    private static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner(InputStream in) {
            this.br = new BufferedReader(new InputStreamReader(in));
        }

        public String next() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) {
                    return null;
                }
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

        public int nextInt() throws IOException {
            String s = next();
            return s == null ? 0 : Integer.parseInt(s);
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Processes a grid of characters by resolving directional relationships 
 * starting from leaf nodes (cells with exactly one adjacent '.' neighbor).
 */
public class GridProcessor {

    // Directional deltas and corresponding symbols
    private static final int[] DELTA_ROW = {-1, 0, 1, 0};
    private static final int[] DELTA_COL = {0, 1, 0, -1};
    private static final char[] DIRECTION_SYMBOLS = {'^', '>', 'v', '<'};

    public static void main(String[] args) throws IOException {
        FastScanner scanner = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out));

        try {
            int rows = scanner.nextInt();
            int cols = scanner.nextInt();

            char[][] grid = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                grid[i] = scanner.next().toCharArray();
            }

            int[][] degreeGrid = calculateDegrees(grid);
            Queue<Point> leafQueue = findInitialLeaves(grid, degreeGrid);

            processGrid(grid, degreeGrid, leafQueue);

            if (isGridComplete(grid)) {
                printGrid(out, grid);
            } else {
                out.println("Not unique");
            }
        } finally {
            out.flush();
            out.close();
        }
    }

    /**
     * Calculates the number of adjacent '.' cells for each cell in the grid.
     */
    private static int[][] calculateDegrees(char[][] grid) {
        int rows = grid.length;
        int cols = grid[0].length;
        int[][] degrees = new int[rows][cols];

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] != '.') continue;

                int degree = 0;
                for (int d = 0; d < 4; d++) {
                    int nr = r + DELTA_ROW[d];
                    int nc = c + DELTA_COL[d];
                    if (isValid(nr, nc, rows, cols) && grid[nr][nc] == '.') {
                        degree++;
                    }
                }
                degrees[r][c] = degree;
            }
        }
        return degrees;
    }

    /**
     * Identifies initial leaf nodes (degree == 1) and marks them as processed.
     */
    private static Queue<Point> findInitialLeaves(char[][] grid, int[][] degrees) {
        Queue<Point> leaves = new ArrayDeque<>();
        int rows = grid.length;
        int cols = grid[0].length;

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (degrees[r][c] == 1 && grid[r][c] == '.') {
                    leaves.add(new Point(r, c));
                    degrees[r][c] = 0; // Mark as processed to prevent re-queueing
                }
            }
        }
        return leaves;
    }

    /**
     * Processes the grid by resolving directions between leaf nodes and their neighbors.
     */
    private static void processGrid(char[][] grid, int[][] degrees, Queue<Point> queue) {
        int rows = grid.length;
        int cols = grid[0].length;

        while (!queue.isEmpty()) {
            Point current = queue.poll();

            for (int d = 0; d < 4; d++) {
                int nr = current.r + DELTA_ROW[d];
                int nc = current.c + DELTA_COL[d];

                if (!isValid(nr, nc, rows, cols) || grid[nr][nc] != '.') {
                    continue;
                }

                // Mark neighbor as processed
                degrees[nr][nc] = 0;
                grid[nr][nc] = DIRECTION_SYMBOLS[d];
                grid[current.r][current.c] = DIRECTION_SYMBOLS[(d + 2) % 4];

                // Update degrees of the neighbor's adjacent '.' cells
                for (int nd = 0; nd < 4; nd++) {
                    int nnr = nr + DELTA_ROW[nd];
                    int nnc = nc + DELTA_COL[nd];
                    if (isValid(nnr, nnc, rows, cols) && grid[nnr][nnc] == '.') {
                        degrees[nnr][nnc]--;
                        if (degrees[nnr][nnc] == 1) {
                            queue.add(new Point(nnr, nnc));
                        }
                    }
                }
            }
        }
    }

    /**
     * Checks if all '.' cells have been resolved.
     */
    private static boolean isGridComplete(char[][] grid) {
        for (char[] row : grid) {
            for (char cell : row) {
                if (cell == '.') return false;
            }
        }
        return true;
    }

    /**
     * Prints the final grid to the output writer.
     */
    private static void printGrid(PrintWriter out, char[][] grid) {
        for (char[] row : grid) {
            out.println(row);
        }
    }

    /**
     * Validates grid boundaries.
     */
    private static boolean isValid(int r, int c, int rows, int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /**
     * Simple record-like class to store 2D coordinates.
     */
    private static class Point {
        final int r, c;
        Point(int r, int c) {
            this.r = r;
            this.c = c;
        }
    }

    /**
     * Fast I/O utility for competitive programming / large inputs.
     */
    private static class FastScanner {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        FastScanner(InputStream in) {
            reader = new BufferedReader(new InputStreamReader(in));
            tokenizer = new StringTokenizer("");
        }

        String next() throws IOException {
            while (!tokenizer.hasMoreTokens()) {
                String line = reader.readLine();
                if (line == null) throw new EOFException("End of input stream");
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        double nextDouble() throws IOException {
            return Double.parseDouble(next());
        }

        long nextLong() throws IOException {
            return Long.parseLong(next());
        }
    }
}

import java.io.*;
import java.util.*;

public class GridPairingSolver {
    private static final int[] DR = {1, 0, -1, 0};
    private static final int[] DC = {0, -1, 0, 1};
    private static final String NOT_UNIQUE = "Not unique";

    private final BufferedReader reader;
    private final PrintWriter writer;
    private StringTokenizer tokenizer;

    private int R, C;
    private char[][] inputGrid;

    public GridPairingSolver(BufferedReader reader, PrintWriter writer) {
        this.reader = reader;
        this.writer = writer;
        this.tokenizer = new StringTokenizer("");
    }

    public static void main(String[] args) {
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
             PrintWriter writer = new PrintWriter(new BufferedOutputStream(System.out))) {
            new GridPairingSolver(reader, writer).solve();
        } catch (IOException e) {
            System.err.println("I/O Error: " + e.getMessage());
        }
    }

    public void solve() throws IOException {
        R = readInt();
        C = readInt();
        inputGrid = new char[R][];
        for (int i = 0; i < R; i++) {
            inputGrid[i] = nextToken().toCharArray();
        }

        Queue<Point> queue = new ArrayDeque<>();
        int[][] adjacentEmptyCount = new int[R][C];

        // Initialize neighbor counts and seed the queue with degree-1 cells
        for (int r = 0; r < R; r++) {
            for (int c = 0; c < C; c++) {
                if (inputGrid[r][c] == '.') {
                    int count = 0;
                    for (int k = 0; k < 4; k++) {
                        int nr = r + DR[k];
                        int nc = c + DC[k];
                        if (isWithinBounds(nr, nc) && inputGrid[nr][nc] == '.') {
                            count++;
                        }
                    }
                    adjacentEmptyCount[r][c] = count;
                    if (count == 1) {
                        queue.add(new Point(r, c));
                    }
                }
            }
        }

        char[][] outputGrid = new char[R][];
        for (int r = 0; r < R; r++) {
            outputGrid[r] = inputGrid[r].clone();
        }

        boolean[][] isProcessed = new boolean[R][C];

        while (!queue.isEmpty()) {
            Point p = queue.poll();
            if (isProcessed[p.r] || adjacentEmptyCount[p.r][p.c] != 1) {
                continue;
            }

            int r1 = -1, c1 = -1;
            for (int k = 0; k < 4; k++) {
                int nr = p.r + DR[k];
                int nc = p.c + DC[k];
                if (isWithinBounds(nr, nc) && !isProcessed[nr][nc] && inputGrid[nr][nc] == '.') {
                    r1 = nr;
                    c1 = nc;
                    break;
                }
            }

            if (r1 == -1) continue;

            placeArrows(outputGrid, p.r, p.c, r1, c1);
            isProcessed[p.r][p.c] = isProcessed[r1][c1] = true;

            // Update neighbor counts for the newly processed cell
            for (int k = 0; k < 4; k++) {
                int nr = r1 + DR[k];
                int nc = c1 + DC[k];
                if (isWithinBounds(nr, nc) && !isProcessed[nr][nc] && inputGrid[nr][nc] == '.') {
                    adjacentEmptyCount[nr][nc]--;
                    if (adjacentEmptyCount[nr][nc] == 1) {
                        queue.add(new Point(nr, nc));
                    }
                }
            }
        }

        // Verify all '.' cells were successfully paired
        for (int r = 0; r < R; r++) {
            for (int c = 0; c < C; c++) {
                if (!isProcessed[r][c] && inputGrid[r][c] == '.') {
                    writer.println(NOT_UNIQUE);
                    return;
                }
            }
        }

        for (int r = 0; r < R; r++) {
            writer.println(outputGrid[r]);
        }
        writer.flush();
    }

    private boolean isWithinBounds(int r, int c) {
        return r >= 0 && r < R && c >= 0 && c < C;
    }

    private void placeArrows(char[][] grid, int r0, int c0, int r1, int c1) {
        // Normalize coordinates so r0 < r1 or (r0 == r1 && c0 < c1)
        if (r0 > r1 || (r0 == r1 && c0 > c1)) {
            int tempR = r0; r0 = r1; r1 = tempR;
            int tempC = c0; c0 = c1; c1 = tempC;
        }
        if (r0 < r1) {
            grid[r0][c0] = '^';
            grid[r1][c1] = 'v';
        } else {
            grid[r0][c0] = '<';
            grid[r1][c1] = '>';
        }
    }

    private String nextToken() throws IOException {
        while (!tokenizer.hasMoreTokens()) {
            String line = reader.readLine();
            if (line == null) return null;
            tokenizer = new StringTokenizer(line);
        }
        return tokenizer.nextToken();
    }

    private int readInt() throws IOException {
        String token = nextToken();
        if (token == null) throw new EOFException("Unexpected end of input");
        return Integer.parseInt(token);
    }

    private record Point(int r, int c) {}
}

import java.io.*;
import java.util.*;

public class D292 {
    // Direction vectors and corresponding arrow characters
    // Order matches original: Up, Left, Down, Right
    private static final int[] DR = {-1, 0, 1, 0};
    private static final int[] DC = {0, -1, 0, 1};
    private static final char[] ARROWS = {'v', '>', '^', '<'};

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out));

        int R = scanner.nextInt();
        int C = scanner.nextInt();

        char[][] grid = new char[R][C];
        for (int i = 0; i < R; i++) {
            grid[i] = scanner.next().toCharArray();
        }

        boolean isComplete = solve(R, C, grid);

        if (!isComplete) {
            out.println("Not unique");
        } else {
            for (char[] row : grid) {
                out.println(row);
            }
        }

        out.flush();
    }

    /**
     * Solves the grid puzzle by propagating arrow placements from cells
     * that have exactly one adjacent empty neighbor.
     * Returns true if all '.' cells are successfully filled.
     */
    private static boolean solve(int R, int C, char[][] grid) {
        // Count adjacent empty cells for each position
        int[][] emptyNeighbors = new int[R][C];
        ArrayDeque<int[]> queue = new ArrayDeque<>();

        // Initialize counts and seed the queue with cells having exactly 1 empty neighbor
        for (int r = 0; r < R; r++) {
            for (int c = 0; c < C; c++) {
                if (grid[r][c] == '.') {
                    int count = 0;
                    for (int d = 0; d < 4; d++) {
                        int nr = r + DR[d];
                        int nc = c + DC[d];
                        if (isValid(nr, nc, R, C) && grid[nr][nc] == '.') {
                            count++;
                        }
                    }
                    emptyNeighbors[r][c] = count;
                    if (count == 1) {
                        queue.add(new int[]{r, c});
                    }
                }
            }
        }

        // Process cells with exactly one empty neighbor (topological peeling)
        while (!queue.isEmpty()) {
            int[] current = queue.poll();
            int r = current[0];
            int c = current[1];

            // Skip if already processed/filled
            if (grid[r][c] != '.') {
                continue;
            }

            // Find the single adjacent empty neighbor
            int dirIdx = -1;
            int nr = -1, nc = -1;
            for (int d = 0; d < 4; d++) {
                int nextR = r + DR[d];
                int nextC = c + DC[d];
                if (isValid(nextR, nextC, R, C) && grid[nextR][nextC] == '.') {
                    dirIdx = d;
                    nr = nextR;
                    nc = nextC;
                    break;
                }
            }

            if (dirIdx == -1) {
                continue; // Should not occur if emptyNeighbors was accurate
            }

            // Place arrows between the two connected cells
            grid[r][c] = ARROWS[dirIdx];
            grid[nr][nc] = ARROWS[(dirIdx + 2) % 4];

            // Update neighbor counts for the newly filled cell's surroundings
            for (int d = 0; d < 4; d++) {
                int nnr = nr + DR[d];
                int nnc = nc + DC[d];
                if (isValid(nnr, nnc, R, C) && grid[nnr][nnc] == '.') {
                    emptyNeighbors[nnr][nnc]--;
                    if (emptyNeighbors[nnr][nnc] == 1) {
                        queue.add(new int[]{nnr, nnc});
                    }
                }
            }
        }

        // Verify if any empty cells remain
        for (int r = 0; r < R; r++) {
            for (int c = 0; c < C; c++) {
                if (grid[r][c] == '.') {
                    return false;
                }
            }
        }
        return true;
    }

    private static boolean isValid(int r, int c, int R, int C) {
        return r >= 0 && r < R && c >= 0 && c < C;
    }

    /**
     * Standard fast I/O helper for competitive programming.
     * Replaces the custom Jolty class for better maintainability and readability.
     */
    private static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) {
                        return null;
                    }
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            String s = next();
            return s == null ? 0 : Integer.parseInt(s);
        }
    }
}

import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.ArrayDeque;
import java.util.InputMismatchException;
import java.util.Queue;

public class GridProcessor {
    private final FastScanner in = new FastScanner(System.in);
    private final PrintWriter out = new PrintWriter(System.out);

    // Direction vectors: up, left, right, down
    private static final int[] DR = {-1, 0, 0, 1};
    private static final int[] DC = {0, -1, 1, 0};

    /** Represents a cell and its single adjacent open neighbor */
    static class Cell {
        final int r, c, nr, nc;

        Cell(int r, int c, int nr, int nc) {
            this.r = r;
            this.c = c;
            this.nr = nr;
            this.nc = nc;
        }
    }

    public void solve() {
        int n = in.nextInt();
        int m = in.nextInt();
        char[][] grid = new char[n][];

        for (int i = 0; i < n; i++) {
            grid[i] = in.next().toCharArray();
        }

        Queue<Cell> queue = new ArrayDeque<>();
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == '.') {
                    int[] neighbor = findSingleNeighbor(grid, i, j);
                    if (neighbor != null) {
                        queue.add(new Cell(j, i, neighbor[0], neighbor[1]));
                    }
                }
            }
        }

        while (!queue.isEmpty()) {
            Cell curr = queue.poll();

            // Skip if already processed or invalidated
            if (grid[curr.r][curr.c] != '.' || grid[curr.nr][curr.nc] != '.') {
                continue;
            }

            assignDirection(grid, curr.r, curr.c, curr.nr, curr.nc);

            // Check neighbors of the newly assigned cell for new single-neighbor conditions
            for (int d = 0; d < 4; d++) {
                int nr = curr.nr + DR[d];
                int nc = curr.nc + DC[d];
                if (isValid(nr, nc, n, m) && grid[nr][nc] == '.') {
                    int[] nextNeighbor = findSingleNeighbor(grid, nr, nc);
                    if (nextNeighbor != null) {
                        queue.add(new Cell(nc, nr, nextNeighbor[0], nextNeighbor[1]));
                    }
                }
            }
        }

        // Check if any '.' remains unassigned
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == '.') {
                    out.println("Not unique");
                    out.flush();
                    return;
                }
            }
        }

        // Output the processed grid
        for (int i = 0; i < n; i++) {
            out.println(grid[i]);
        }
        out.flush();
    }

    /**
     * Finds the single adjacent '.' cell. Returns coordinates as {row, col} or null.
     */
    private int[] findSingleNeighbor(char[][] grid, int r, int c) {
        int count = 0;
        int nr = -1, nc = -1;
        for (int d = 0; d < 4; d++) {
            int dr = r + DR[d];
            int dc = c + DC[d];
            if (isValid(dr, dc, grid.length, grid[0].length) && grid[dr][dc] == '.') {
                count++;
                nr = dr;
                nc = dc;
            }
        }
        return count == 1 ? new int[]{nr, nc} : null;
    }

    private boolean isValid(int r, int c, int rows, int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /**
     * Assigns directional characters to the pair of cells.
     * Note: Logic preserved exactly as original to maintain problem-specific behavior.
     */
    private void assignDirection(char[][] grid, int r1, int c1, int r2, int c2) {
        if (r1 - r2 == 1) {
            grid[r1][c1] = 'v';
            grid[r2][c2] = '^';
        } else if (r1 - r2 == -1) {
            grid[r1][c1] = '^';
            grid[r2][c2] = 'v';
        } else if (c1 - c2 == -1) {
            grid[r1][c1] = '<';
            grid[r2][c2] = '>';
        } else if (c1 - c2 == 1) {
            grid[r1][c1] = '>';
            grid[r2][c2] = '<';
        }
    }

    public static void main(String[] args) {
        new GridProcessor().solve();
    }

    /** High-performance scanner for competitive programming / fast I/O */
    static class FastScanner {
        private final InputStream stream;
        private final byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;

        public FastScanner(InputStream stream) {
            this.stream = stream;
        }

        private int read() {
            if (numChars == -1) {
                throw new InputMismatchException();
            }
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0) {
                    return -1;
                }
            }
            return buf[curChar++];
        }

        private boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        private boolean isEndline(int c) {
            return c == '\n' || c == '\r' || c == -1;
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public String next() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            StringBuilder res = new StringBuilder();
            do {
                res.appendCodePoint(c);
                c = read();
            } while (!isSpaceChar(c));
            return res.toString();
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.OutputStreamWriter;
import java.io.PrintWriter;
import java.util.ArrayDeque;
import java.util.Queue;
import java.util.StringTokenizer;

public class Solution {

    /**
     * Fast input reader optimized for competitive programming style inputs.
     */
    private static class FastScanner {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastScanner() {
            this.reader = new BufferedReader(new InputStreamReader(System.in));
            this.tokenizer = new StringTokenizer("");
        }

        private String next() throws IOException {
            while (!tokenizer.hasMoreTokens()) {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public String readLine() throws IOException {
            return reader.readLine();
        }

        public int nextInt() throws IOException {
            String s = next();
            return s == null ? 0 : Integer.parseInt(s);
        }
    }

    /**
     * Simple immutable coordinate class.
     */
    private static class Point {
        final int x, y;
        Point(int x, int y) {
            this.x = x;
            this.y = y;
        }
    }

    // Instance fields instead of static to improve encapsulation and testability
    private int rows, cols;
    private char[][] grid;
    private FastScanner scanner;
    private PrintWriter out;

    public static void main(String[] args) throws IOException {
        new Solution().solve();
    }

    public void solve() throws IOException {
        scanner = new FastScanner();
        out = new PrintWriter(new OutputStreamWriter(System.out));

        try {
            String nStr = scanner.next();
            if (nStr == null) return;

            rows = Integer.parseInt(nStr);
            cols = scanner.nextInt();

            grid = new char[rows][cols];
            int dotCount = 0;

            // Read grid and count initial dots
            for (int i = 0; i < rows; i++) {
                String line = scanner.readLine();
                if (line != null) {
                    grid[i] = line.toCharArray();
                    for (char c : grid[i]) {
                        if (c == '.') dotCount++;
                    }
                }
            }

            // Odd number of dots means pairing is impossible
            if (dotCount % 2 != 0) {
                out.println("Not unique");
                return;
            }

            // Queue for points with exactly one adjacent dot (peeling approach)
            Queue<Point> queue = new ArrayDeque<>();
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j] == '.' && countAdjacentDots(i, j) == 1) {
                        queue.add(new Point(i, j));
                    }
                }
            }

            int[] dx = {-1, 1, 0, 0};
            int[] dy = {0, 0, -1, 1};
            char[] neighborArrows = {'^', 'v', '<', '>'};
            char[] currentArrows = {'v', '^', '>', '<'};

            while (!queue.isEmpty()) {
                Point p = queue.poll();
                if (grid[p.x][p.y] != '.') continue; // Already processed

                int adjX = -1, adjY = -1;
                int dirIdx = -1;

                // Find the single adjacent dot
                for (int k = 0; k < 4; k++) {
                    int nx = p.x + dx[k];
                    int ny = p.y + dy[k];
                    if (isValid(nx, ny) && grid[nx][ny] == '.') {
                        adjX = nx;
                        adjY = ny;
                        dirIdx = k;
                        break;
                    }
                }

                // If no adjacent dot exists, configuration is invalid
                if (adjX == -1) {
                    out.println("Not unique");
                    return;
                }

                // Mark arrows
                grid[p.x][p.y] = currentArrows[dirIdx];
                grid[adjX][adjY] = neighborArrows[dirIdx];

                // Check neighbors of the newly marked point
                for (int k = 0; k < 4; k++) {
                    int nx = adjX + dx[k];
                    int ny = adjY + dy[k];
                    if (isValid(nx, ny) && grid[nx][ny] == '.') {
                        int adjCount = countAdjacentDots(nx, ny);
                        if (adjCount == 0) {
                            out.println("Not unique");
                            return;
                        } else if (adjCount == 1) {
                            queue.add(new Point(nx, ny));
                        }
                    }
                }
            }

            // If any dots remain unpaired, configuration is invalid
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j] == '.') {
                        out.println("Not unique");
                        return;
                    }
                }
            }

            // Output the solved grid
            for (int i = 0; i < rows; i++) {
                out.println(new String(grid[i]));
            }

        } finally {
            out.flush();
        }
    }

    private boolean isValid(int x, int y) {
        return x >= 0 && x < rows && y >= 0 && y < cols;
    }

    private int countAdjacentDots(int x, int y) {
        int count = 0;
        int[] dx = {-1, 1, 0, 0};
        int[] dy = {0, 0, -1, 1};
        for (int k = 0; k < 4; k++) {
            int nx = x + dx[k];
            int ny = y + dy[k];
            if (isValid(nx, ny) && grid[nx][ny] == '.') {
                count++;
            }
        }
        return count;
    }
}

