class TaskB {
    /**
     * Solves the grid covering problem for the given test case.
     */
    public void solve(int testNumber, InputReader in, PrintWriter out) {
        int n = in.nextInt();
        int m = in.nextInt();
        char[][] grid = new char[n][];
        for (int i = 0; i < n; i++) {
            grid[i] = in.next().toCharArray();
        }

        int emptyCells = countEmptyCells(grid);
        Queue<int[]> queue = new ArrayDeque<>();
        boolean[][] inQueue = new boolean[n][m];

        // Initialize queue with leaf nodes (degree == 1)
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == EMPTY_CELL && getDegree(grid, i, j, n, m) == 1) {
                    queue.offer(new int[]{i, j});
                    inQueue[i][j] = true;
                }
            }
        }

        // Process leaves iteratively
        while (!queue.isEmpty()) {
            int[] current = queue.poll();
            int x = current[0];
            int y = current[1];

            // Skip if already covered or processed
            if (grid[x][y] != EMPTY_CELL) {
                continue;
            }

            int[] neighbor = findAdjacentEmptyCell(grid, x, y, n, m);
            if (neighbor == null) {
                continue;
            }

            int nx = neighbor[0];
            int ny = neighbor[1];

            // Cover the pair and update remaining count
            coverCells(grid, x, y, nx, ny);
            emptyCells -= 2;

            // Check orthogonal neighbors for newly created leaves
            checkAndUpdateQueue(grid, x, y, n, m, queue, inQueue);
            checkAndUpdateQueue(grid, nx, ny, n, m, queue, inQueue);
        }

        if (emptyCells > 0) {
            out.println("Not unique");
        } else {
            for (char[] row : grid) {
                out.println(row);
            }
        }
    }

    private int countEmptyCells(char[][] grid) {
        int count = 0;
        for (char[] row : grid) {
            for (char c : row) {
                if (c == EMPTY_CELL) {
                    count++;
                }
            }
        }
        return count;
    }

    private int getDegree(char[][] grid, int i, int j, int n, int m) {
        if (i < 0 || i >= n || j < 0 || j >= m || grid[i][j] != EMPTY_CELL) {
            return 0;
        }
        int deg = 0;
        if (i > 0 && grid[i - 1][j] == EMPTY_CELL) deg++;
        if (i + 1 < n && grid[i + 1][j] == EMPTY_CELL) deg++;
        if (j > 0 && grid[i][j - 1] == EMPTY_CELL) deg++;
        if (j + 1 < m && grid[i][j + 1] == EMPTY_CELL) deg++;
        return deg;
    }

    private int[] findAdjacentEmptyCell(char[][] grid, int x, int y, int n, int m) {
        if (x > 0 && grid[x - 1][y] == EMPTY_CELL) return new int[]{x - 1, y};
        if (x + 1 < n && grid[x + 1][y] == EMPTY_CELL) return new int[]{x + 1, y};
        if (y > 0 && grid[x][y - 1] == EMPTY_CELL) return new int[]{x, y - 1};
        if (y + 1 < m && grid[x][y + 1] == EMPTY_CELL) return new int[]{x, y + 1};
        return null;
    }

    private void coverCells(char[][] grid, int x1, int y1, int x2, int y2) {
        if (x1 == x2) {
            grid[x1][Math.min(y1, y2)] = '<';
            grid[x2][Math.max(y1, y2)] = '>';
        } else {
            grid[Math.min(x1, x2)][y1] = '^';
            grid[Math.max(x1, x2)][y2] = 'v';
        }
    }

    /**
     * Checks orthogonal neighbors of a cell. If a neighbor becomes a leaf (degree 1),
     * adds it to the queue while preventing duplicates.
     */
    private void checkAndUpdateQueue(char[][] grid, int i, int j, int n, int m, 
                                     Queue<int[]> queue, boolean[][] inQueue) {
        // Only orthogonal neighbors affect grid degree. Diagonals are ignored for correctness and performance.
        int[] dirs = {-1, 0, 1, 0, -1}; // up, right, down, left
        for (int d = 0; d < 4; d++) {
            int ni = i + dirs[d];
            int nj = j + dirs[d + 1];
            if (ni >= 0 && ni < n && nj >= 0 && nj < m && grid[ni][nj] == EMPTY_CELL) {
                if (getDegree(grid, ni, nj, n, m) == 1 && !inQueue[ni][nj]) {
                    queue.offer(new int[]{ni, nj});
                    inQueue[ni][nj] = true;
                }
            }
        }
    }
}

class InputReader {
    private final BufferedReader reader;
    private StringTokenizer tokenizer;

    public InputReader(InputStream stream) {
        reader = new BufferedReader(new InputStreamReader(stream), 32768);
        tokenizer = null;
    }

    public String next() {
        while (tokenizer == null || !tokenizer.hasMoreTokens()) {
            try {
                String line = reader.readLine();
                if (line == null) {
                    return null;
                }
                tokenizer = new StringTokenizer(line);
            } catch (IOException e) {
                throw new RuntimeException("Failed to read input", e);
            }
        }
        return tokenizer.nextToken();
    }

    public int nextInt() {
        String token = next();
        if (token == null) {
            throw new RuntimeException("Unexpected end of input");
        }
        return Integer.parseInt(token);
    }

    public void close() {
        try {
            reader.close();
        } catch (IOException e) {
            throw new RuntimeException("Failed to close input reader", e);
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.OutputStreamWriter;
import java.io.PrintWriter;
import java.util.ArrayDeque;
import java.util.Queue;
import java.util.StringTokenizer;

public class GridPathSolver {

    private static final int[] DX = {-1, 0, 1, 0};
    private static final int[] DY = {0, 1, 0, -1};
    private static final String RESULT_NOT_UNIQUE = "Not unique";

    public static void main(String[] args) throws IOException {
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
             PrintWriter writer = new PrintWriter(new OutputStreamWriter(System.out))) {

            String line = reader.readLine();
            if (line == null) {
                return;
            }

            StringTokenizer tokenizer = new StringTokenizer(line);
            int rows = Integer.parseInt(tokenizer.nextToken());
            int cols = Integer.parseInt(tokenizer.nextToken());

            char[][] grid = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                grid[i] = reader.readLine().toCharArray();
            }

            Queue<Point> queue = new ArrayDeque<>();
            boolean[][] visited = new boolean[rows][cols];

            // Initialize queue with empty cells that have exactly one empty neighbor
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j] == '.' && countEmptyNeighbors(i, j, grid) == 1) {
                        visited[i][j] = true;
                        queue.add(new Point(i, j));
                    }
                }
            }

            while (!queue.isEmpty()) {
                Point current = queue.poll();
                int x = current.x;
                int y = current.y;

                for (int d = 0; d < 4; d++) {
                    int nx = x + DX[d];
                    int ny = y + DY[d];

                    if (!isValid(nx, ny, rows, cols) || grid[nx][ny] != '.') {
                        continue;
                    }

                    // Update directional markers between current and neighbor
                    setDirectionMarker(x, y, nx, ny, grid);

                    // Check neighbors of both the current cell and the newly visited neighbor
                    for (int dd = 0; dd < 4; dd++) {
                        processNeighbor(nx, ny, dd, rows, cols, grid, visited, queue);
                        processNeighbor(x, y, dd, rows, cols, grid, visited, queue);
                    }
                }
            }

            if (!allCellsReplaced(grid)) {
                writer.println(RESULT_NOT_UNIQUE);
            } else {
                for (char[] row : grid) {
                    writer.println(new String(row));
                }
            }
        }
    }

    /**
     * Counts the number of adjacent empty cells ('.') for a given coordinate.
     */
    private static int countEmptyNeighbors(int x, int y, char[][] grid) {
        int count = 0;
        for (int d = 0; d < 4; d++) {
            int nx = x + DX[d];
            int ny = y + DY[d];
            if (isValid(nx, ny, grid.length, grid[0].length) && grid[nx][ny] == '.') {
                count++;
            }
        }
        return count;
    }

    /**
     * Checks if coordinates are within grid boundaries.
     */
    private static boolean isValid(int x, int y, int rows, int cols) {
        return x >= 0 && y >= 0 && x < rows && y < cols;
    }

    /**
     * Sets directional markers between two adjacent cells.
     */
    private static void setDirectionMarker(int x1, int y1, int x2, int y2, char[][] grid) {
        if (x2 < x1) {
            grid[x2][y2] = '^';
            grid[x1][y1] = 'v';
        } else if (x2 > x1) {
            grid[x2][y2] = 'v';
            grid[x1][y1] = '^';
        } else if (y2 < y1) {
            grid[x2][y2] = '<';
            grid[x1][y1] = '>';
        } else {
            grid[x2][y2] = '>';
            grid[x1][y1] = '<';
        }
    }

    /**
     * Validates and adds a neighbor to the queue if it meets the algorithm's criteria.
     */
    private static void processNeighbor(int x, int y, int d, int rows, int cols, 
                                        char[][] grid, boolean[][] visited, Queue<Point> queue) {
        int nx = x + DX[d];
        int ny = y + DY[d];

        if (isValid(nx, ny, rows, cols) && grid[nx][ny] == '.' && !visited[nx][ny] && countEmptyNeighbors(nx, ny, grid) == 1) {
            visited[nx][ny] = true;
            queue.add(new Point(nx, ny));
        }
    }

    /**
     * Checks if all empty cells ('.') have been replaced.
     */
    private static boolean allCellsReplaced(char[][] grid) {
        for (char[] row : grid) {
            for (char cell : row) {
                if (cell == '.') {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Simple immutable value class for 2D coordinates.
     */
    private static final class Point {
        final int x;
        final int y;

        Point(int x, int y) {
            this.x = x;
            this.y = y;
        }
    }
}

