class TaskB {
    // Direction vectors and corresponding character mappings
    private static final int[] DX = {-1, 0, 0, 1};
    private static final int[] DY = {0, -1, 1, 0};
    private static final char[] DIR_CHARS_1 = {'v', '>', '<', '^'};
    private static final char[] DIR_CHARS_2 = {'^', '<', '>', 'v'};
    private static final int MIN_NEIGHBOR_THRESHOLD = 1;

    private int n, m;
    private char[][] grid;
    private int[][] neighborCounts;

    public void solve(InputReader in, PrintWriter out) {
        n = in.readInt();
        m = in.readInt();
        grid = new char[n][m];
        neighborCounts = new int[n][m];

        for (int i = 0; i < n; i++) {
            grid[i] = in.readString().toCharArray();
        }

        if (solveGrid()) {
            for (int i = 0; i < n; i++) {
                out.println(grid[i]);
            }
        } else {
            out.print("Not unique");
        }
    }

    private boolean solveGrid() {
        Queue<Cell> queue = new ArrayDeque<>(n * m);
        initializeQueue(queue);

        while (!queue.isEmpty()) {
            Cell current = queue.poll();
            if (grid[current.x][current.y] != '.') {
                continue;
            }

            int directionIdx = findFirstEmptyNeighbor(current.x, current.y);
            if (directionIdx == -1) {
                return false;
            }

            placeDirectionSymbols(current.x, current.y, directionIdx);
            Cell nextCell = new Cell(current.x + DX[directionIdx], current.y + DY[directionIdx]);
            updateNeighborCounts(nextCell, queue);
        }

        return !hasRemainingEmptyCells();
    }

    private void initializeQueue(Queue<Cell> queue) {
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == '.') {
                    int count = countEmptyNeighbors(i, j);
                    neighborCounts[i][j] = count;
                    if (count <= MIN_NEIGHBOR_THRESHOLD) {
                        queue.add(new Cell(i, j));
                    }
                }
            }
        }
    }

    private int countEmptyNeighbors(int x, int y) {
        int count = 0;
        for (int d = 0; d < 4; d++) {
            int nx = x + DX[d];
            int ny = y + DY[d];
            if (isValid(nx, ny) && grid[nx][ny] == '.') {
                count++;
            }
        }
        return count;
    }

    private int findFirstEmptyNeighbor(int x, int y) {
        for (int d = 0; d < 4; d++) {
            int nx = x + DX[d];
            int ny = y + DY[d];
            if (isValid(nx, ny) && grid[nx][ny] == '.') {
                return d;
            }
        }
        return -1;
    }

    private void placeDirectionSymbols(int x, int y, int dirIdx) {
        grid[x][y] = DIR_CHARS_1[dirIdx];
        grid[x + DX[dirIdx]][y + DY[dirIdx]] = DIR_CHARS_2[dirIdx];
    }

    private void updateNeighborCounts(Cell current, Queue<Cell> queue) {
        for (int d = 0; d < 4; d++) {
            int nx = current.x + DX[d];
            int ny = current.y + DY[d];
            if (isValid(nx, ny) && grid[nx][ny] == '.') {
                neighborCounts[nx][ny]--;
                if (neighborCounts[nx][ny] <= MIN_NEIGHBOR_THRESHOLD) {
                    queue.add(new Cell(nx, ny));
                }
            }
        }
    }

    private boolean hasRemainingEmptyCells() {
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == '.') {
                    return true;
                }
            }
        }
        return false;
    }

    private boolean isValid(int x, int y) {
        return x >= 0 && x < n && y >= 0 && y < m;
    }
}

