/**
 * Optimized fast I/O reader. Removed unused methods and simplified internal structure.
 */
class InputReader {
    private final InputStream stream;
    private final byte[] buffer = new byte[1024];
    private int bufferPos;
    private int bytesRead;

    public InputReader(InputStream stream) {
        this.stream = stream;
    }

    private int read() {
        if (bufferPos >= bytesRead) {
            bufferPos = 0;
            try {
                bytesRead = stream.read(buffer);
            } catch (IOException e) {
                throw new InputMismatchException();
            }
            if (bytesRead <= 0) {
                return -1;
            }
        }
        return buffer[bufferPos++];
    }

    public int readInt() {
        int c = read();
        while (isSpaceChar(c)) {
            c = read();
        }
        int sign = 1;
        if (c == '-') {
            sign = -1;
            c = read();
        }
        int res = 0;
        do {
            if (c < '0' || c > '9') {
                throw new InputMismatchException();
            }
            res = res * 10 + (c - '0');
            c = read();
        } while (!isSpaceChar(c));
        return res * sign;
    }

    public String readString() {
        int c = read();
        while (isSpaceChar(c)) {
            c = read();
        }
        StringBuilder sb = new StringBuilder();
        do {
            if (Character.isValidCodePoint(c)) {
                sb.appendCodePoint(c);
            }
            c = read();
        } while (!isSpaceChar(c));
        return sb.toString();
    }

    private boolean isSpaceChar(int c) {
        return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
    }
}

import java.io.IOException;
import java.io.InputStream;
import java.io.OutputStream;
import java.io.PrintWriter;
import java.util.ArrayDeque;
import java.util.InputMismatchException;
import java.util.Queue;

public class Main {
    public static void main(String[] args) {
        // Use try-with-resources to ensure proper cleanup of I/O streams
        try (InputStream inputStream = System.in;
             OutputStream outputStream = System.out;
             PrintWriter out = new PrintWriter(outputStream)) {

            InputReader in = new InputReader(inputStream);
            Solver solver = new Solver();
            solver.solve(in, out);
        }
    }

    /**
     * Core solver for the grid path problem.
     * Uses a topological sort / BFS approach based on cell degrees.
     */
    static class Solver {
        // Direction vectors: Down, Up, Right, Left
        private static final int[] DX = {1, -1, 0, 0};
        private static final int[] DY = {0, 0, 1, -1};

        public void solve(InputReader in, PrintWriter out) {
            int rows = in.readInt();
            int cols = in.readInt();
            char[][] grid = new char[rows][cols];

            for (int i = 0; i < rows; i++) {
                grid[i] = in.readLine().toCharArray();
            }

            int[][] degree = new int[rows][cols];
            Queue<int[]> queue = new ArrayDeque<>();

            // Calculate initial degrees for each empty cell and enqueue boundary cells (degree == 1)
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] == '.') {
                        if (r + 1 < rows && grid[r + 1][c] == '.') {
                            degree[r][c]++;
                            degree[r + 1][c]++;
                        }
                        if (c + 1 < cols && grid[r][c + 1] == '.') {
                            degree[r][c]++;
                            degree[r][c + 1]++;
                        }
                    }
                    if (degree[r][c] == 1) {
                        queue.offer(new int[]{r, c});
                    }
                }
            }

            // Process cells using a BFS/topological sort approach
            while (!queue.isEmpty()) {
                int[] current = queue.poll();
                int r = current[0];
                int c = current[1];

                if (grid[r][c] != '.') continue;

                int neighborR = -1, neighborC = -1, directionIdx = -1;
                // Find the single unprocessed neighbor
                for (int i = 0; i < 4; i++) {
                    int nr = r + DX[i];
                    int nc = c + DY[i];
                    if (nr >= 0 && nr < rows && nc >= 0 && nc < cols && grid[nr][nc] == '.') {
                        neighborR = nr;
                        neighborC = nc;
                        directionIdx = i;
                        break;
                    }
                }

                // If no valid neighbor is found, the solution is not unique
                if (directionIdx == -1) {
                    out.println("Not unique");
                    return;
                }

                // Place arrows based on the direction index
                grid[r][c] = getArrow(directionIdx, false);
                grid[neighborR][neighborC] = getArrow(directionIdx, true);
                degree[r][c]--;

                // Update degrees for neighbors of the newly placed cell
                for (int i = 0; i < 4; i++) {
                    int nr = neighborR + DX[i];
                    int nc = neighborC + DY[i];
                    if (nr >= 0 && nr < rows && nc >= 0 && nc < cols) {
                        degree[nr][nc]--;
                        if (grid[nr][nc] == '.' && degree[nr][nc] == 1) {
                            queue.offer(new int[]{nr, nc});
                        }
                    }
                }
            }

            // Check if any empty cells remain unprocessed
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] == '.') {
                        out.println("Not unique");
                        return;
                    }
                }
            }

            // Output the solved grid
            for (int r = 0; r < rows; r++) {
                out.println(new String(grid[r]));
            }
        }

        /**
         * Maps a direction index to the appropriate arrow character.
         * Preserves the original mapping logic:
         * idx 0 (Down): current='^', neighbor='v'
         * idx 1 (Up): current='v', neighbor='^'
         * idx 2 (Right): current='<', neighbor='>'
         * idx 3 (Left): current='>', neighbor='<'
         */
        private char getArrow(int directionIdx, boolean isCurrent) {
            if (directionIdx == 0) return isCurrent ? '^' : 'v';
            if (directionIdx == 1) return isCurrent ? 'v' : '^';
            if (directionIdx == 2) return isCurrent ? '<' : '>';
            return isCurrent ? '>' : '<'; // directionIdx == 3
        }
    }

    /**
     * Fast input reader optimized for competitive programming.
     */
    static class InputReader {
        private final InputStream stream;
        private final byte[] buffer = new byte[1024];
        private int bufferPtr;
        private int bytesRead;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        public int read() {
            if (bytesRead == -1) {
                throw new InputMismatchException("End of stream");
            }
            if (bufferPtr >= bytesRead) {
                bufferPtr = 0;
                try {
                    bytesRead = stream.read(buffer);
                } catch (IOException e) {
                    throw new InputMismatchException("IO Error");
                }
                if (bytesRead <= 0) {
                    return -1;
                }
            }
            return buffer[bufferPtr++];
        }

        public int readInt() {
            int c = read();
            while (isSpaceChar(c)) {
                if (c == -1) throw new InputMismatchException("Unexpected end of input");
                c = read();
            }
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int result = 0;
            do {
                if (c < '0' || c > '9') {
                    throw new InputMismatchException("Invalid integer");
                }
                result = result * 10 + (c - '0');
                c = read();
            } while (!isSpaceChar(c));
            return result * sign;
        }

        public String readLine() {
            StringBuilder line = new StringBuilder();
            int c = read();
            while (c != '\n' && c != -1) {
                if (c != '\r') {
                    line.appendCodePoint(c);
                }
                c = read();
            }
            String result = line.toString();
            // Skip empty lines if any (common in competitive programming inputs)
            while (result.trim().isEmpty()) {
                c = read();
                line.setLength(0);
                while (c != '\n' && c != -1) {
                    if (c != '\r') {
                        line.appendCodePoint(c);
                    }
                    c = read();
                }
                result = line.toString();
            }
            return result;
        }

        public boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.LinkedList;
import java.util.Queue;
import java.util.StringTokenizer;

/**
 * Refactored version of the grid path solver.
 * 
 * Improvements made:
 * 1. Naming: Renamed class and variables to be descriptive (e.g., ArrowGridSolver, resultGrid).
 * 2. Structure: Extracted logic into a 'solve' method and helper classes.
 * 3. Constants: Extracted magic numbers (directions, arrows) into named constants.
 * 4. Data Structures: Used a 'Point' class for coordinates instead of parallel queues.
 * 5. Input/Output: Encapsulated Fast I/O in a cleaner 'FastScanner' class.
 * 6. Robustness: Added bounds checking helper and better error handling.
 */
public class ArrowGridSolver {

    // Direction vectors: Right, Down, Left, Up
    // Corresponds to original: di={0, 1, 0, -1}, dj={1, 0, -1, 0}
    private static final int[] DR = {0, 1, 0, -1};
    private static final int[] DC = {1, 0, -1, 0};

    // Arrow mappings based on the direction index of the neighbor.
    // 0: Right neighbor, 1: Down neighbor, 2: Left neighbor, 3: Up neighbor
    // Logic derived from original if-else chain:
    // d=0 (Right): Current '<', Neighbor '>'
    // d=1 (Down):  Current '^', Neighbor 'v'
    // d=2 (Left):  Current '>', Neighbor '<'
    // d=3 (Up):    Current 'v', Neighbor '^'
    private static final char[] CURRENT_ARROWS = {'<', '^', '>', 'v'};
    private static final char[] NEIGHBOR_ARROWS = {'>', 'v', '<', '^'};

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            solve(scanner, out);
        } catch (IOException e) {
            e.printStackTrace();
        } finally {
            out.flush();
            out.close();
        }
    }

    private static void solve(FastScanner scanner, PrintWriter out) throws IOException {
        if (!scanner.hasMoreTokens()) return;

        int n = scanner.nextInt();
        int m = scanner.nextInt();

        char[][] originalGrid = new char[n][m];
        char[][] resultGrid = new char[n][m];

        // Read grid input
        for (int i = 0; i < n; i++) {
            String row = scanner.next();
            for (int j = 0; j < m; j++) {
                char c = row.charAt(j);
                originalGrid[i][j] = c;
                resultGrid[i][j] = c;
            }
        }

        // Degree array to track number of empty neighbors
        int[][] degrees = new int[n][m];
        Queue<Point> queue = new LinkedList<>();

        // Pre-calculate degrees and initialize queue with leaf nodes (degree 1)
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                // Original logic: Skip cells where (i+j) is even or cell is '*'
                if ((i + j) % 2 == 0 || originalGrid[i][j] == '*') {
                    continue;
                }

                int degree = 0;
                for (int k = 0; k < 4; k++) {
                    int ni = i + DR[k];
                    int nj = j + DC[k];
                    if (isValid(ni, nj, n, m) && originalGrid[ni][nj] == '.') {
                        degree++;
                    }
                }
                degrees[i][j] = degree;

                if (degree == 1) {
                    queue.add(new Point(i, j));
                }
            }
        }

        // Process the queue (BFS-like propagation)
        while (!queue.isEmpty()) {
            Point current = queue.poll();
            int r = current.r;
            int c = current.c;

            int directionIndex = -1;

            // Find the single empty neighbor
            for (int k = 0; k < 4; k++) {
                int ni = r + DR[k];
                int nj = c + DC[k];
                if (isValid(ni, nj, n, m) && resultGrid[ni][nj] == '.') {
                    directionIndex = k;
                    break; // Found the neighbor
                }
            }

            // If no empty neighbor is found, stop
            if (directionIndex == -1) {
                break;
            }

            int nextR = r + DR[directionIndex];
            int nextC = c + DC[directionIndex];

            // Apply arrows based on direction
            resultGrid[r][c] = CURRENT_ARROWS[directionIndex];
            resultGrid[nextR][nextC] = NEIGHBOR_ARROWS[directionIndex];

            // Update degrees of neighbors of the newly filled cell (nextR, nextC)
            for (int k = 0; k < 4; k++) {
                int ni = nextR + DR[k];
                int nj = nextC + DC[k];
                if (isValid(ni, nj, n, m) && originalGrid[ni][nj] == '.') {
                    degrees[ni][nj]--;
                    if (degrees[ni][nj] == 1) {
                        queue.add(new Point(ni, nj));
                    }
                }
            }
        }

        // Check if the grid is fully filled
        boolean isComplete = true;
        outerLoop:
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (resultGrid[i][j] == '.') {
                    isComplete = false;
                    break outerLoop;
                }
            }
        }

        if (isComplete) {
            for (char[] row : resultGrid) {
                out.println(new String(row));
            }
        } else {
            out.println("Not unique");
        }
    }

    private static boolean isValid(int r, int c, int n, int m) {
        return r >= 0 && r < n && c >= 0 && c < m;
    }

    /**
     * Helper class to store grid coordinates.
     */
    private static class Point {
        int r, c;

        Point(int r, int c) {
            this.r = r;
            this.c = c;
        }
    }

    /**
     * Fast I/O helper class.
     */
    static class FastScanner {
        BufferedReader reader;
        StringTokenizer tokenizer;

        FastScanner(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
            tokenizer = new StringTokenizer("");
        }

        boolean hasMoreTokens() throws IOException {
            while (!tokenizer.hasMoreTokens()) {
                String line = reader.readLine();
                if (line == null) {
                    return false;
                }
                tokenizer = new StringTokenizer(line);
            }
            return true;
        }

        String next() throws IOException {
            if (hasMoreTokens()) {
                return tokenizer.nextToken();
            }
            return null;
        }

        int nextInt() throws IOException {
            String s = next();
            if (s == null) throw new IOException("No more tokens");
            return Integer.parseInt(s);
        }
    }
}

import java.io.*;
import java.util.*;

public class Main {
    private static final String RESULT_NOT_UNIQUE = "Not unique";
    private static final int[] DX = {1, 0, -1, 0};
    private static final int[] DY = {0, 1, 0, -1};

    private final InputReader ir;
    private final PrintWriter out;

    public Main() {
        this.ir = new InputReader(System.in);
        this.out = new PrintWriter(System.out);
    }

    public void run() {
        try {
            solve();
        } finally {
            out.flush();
            out.close();
        }
    }

    private void solve() {
        int n = ir.readInt();
        int m = ir.readInt();

        char[][] grid = new char[n][m];
        for (int i = 0; i < n; i++) {
            grid[i] = ir.readString().toCharArray();
        }

        int[][] emptyNeighbors = new int[n][m];
        int[] queueRow = new int[n * m];
        int[] queueCol = new int[n * m];
        int head = 0;
        int tail = 0;

        // Initialize neighbor counts and seed the processing queue
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == '*') continue;

                int count = 0;
                for (int k = 0; k < 4; k++) {
                    int ni = i + DX[k];
                    int nj = j + DY[k];
                    if (isValid(ni, nj, n, m) && grid[ni][nj] == '.') {
                        count++;
                    }
                }
                emptyNeighbors[i][j] = count;

                if (count == 0) {
                    out.println(RESULT_NOT_UNIQUE);
                    return;
                } else if (count == 1) {
                    queueRow[tail] = i;
                    queueCol[tail++] = j;
                }
            }
        }

        // Process constrained cells in queue order
        while (head < tail) {
            int i = queueRow[head];
            int j = queueCol[head++];

            if (grid[i][j] != '.') continue;

            for (int k = 0; k < 4; k++) {
                int ni = i + DX[k];
                int nj = j + DY[k];

                if (isValid(ni, nj, n, m) && grid[ni][nj] == '.') {
                    // Place directional arrows between the two cells
                    if (DX[k] == 0) { // Horizontal
                        grid[ni][Math.min(nj, j)] = '<';
                        grid[ni][Math.max(nj, j)] = '>';
                    } else { // Vertical
                        grid[Math.min(ni, i)][nj] = '^';
                        grid[Math.max(ni, i)][nj] = 'v';
                    }

                    emptyNeighbors[i][j]--;
                    emptyNeighbors[ni][nj]--;

                    if (emptyNeighbors[ni][nj] == 0) {
                        out.println(RESULT_NOT_UNIQUE);
                        return;
                    } else if (emptyNeighbors[ni][nj] == 1) {
                        queueRow[tail] = ni;
                        queueCol[tail++] = nj;
                    }

                    // Propagate constraint changes to neighbors of the placed cell
                    for (int kk = 0; kk < 4; kk++) {
                        int nni = ni + DX[kk];
                        int nnj = nj + DY[kk];
                        if (isValid(nni, nnj, n, m) && grid[nni][nnj] == '.') {
                            emptyNeighbors[nni][nnj]--;
                            if (emptyNeighbors[nni][nnj] == 0) {
                                out.println(RESULT_NOT_UNIQUE);
                                return;
                            } else if (emptyNeighbors[nni][nnj] == 1) {
                                queueRow[tail] = nni;
                                queueCol[tail++] = nnj;
                            }
                        }
                    }
                }
            }
        }

        // Verify that all empty cells have been resolved
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == '.') {
                    out.println(RESULT_NOT_UNIQUE);
                    return;
                }
            }
        }

        // Output the final grid
        for (int i = 0; i < n; i++) {
            out.println(new String(grid[i]));
        }
    }

    private boolean isValid(int r, int c, int n, int m) {
        return r >= 0 && r < n && c >= 0 && c < m;
    }

    public static void main(String[] args) {
        new Main().run();
    }
}

/**
 * Fast I/O helper class for competitive programming.
 */
class InputReader {
    private InputStream stream;
    private byte[] buf = new byte[1024];
    private int curChar;
    private int numChars;
    private SpaceCharFilter filter;

    public InputReader(InputStream stream) {
        this.stream = stream;
    }

    public int read() {
        if (numChars == -1) {
            throw new InputMismatchException();
        }
        if (curChar >= numChars) {
            curChar = 0;
            try {
                numChars = stream.read(buf);
            } catch (IOException e) {
                throw new InputMismatchException();
            }
            if (numChars <= 0) {
                return -1;
            }
        }
        return buf[curChar++];
    }

    public final int readInt() {
        int c = read();
        while (isSpaceChar(c)) {
            c = read();
        }
        int sgn = 1;
        if (c == '-') {
            sgn = -1;
            c = read();
        }
        int res = 0;
        do {
            if (c < '0' || c > '9') {
                throw new InputMismatchException();
            }
            res *= 10;
            res += c - '0';
            c = read();
        } while (!isSpaceChar(c));
        return res * sgn;
    }

    public long readLong() {
        int c = read();
        while (isSpaceChar(c)) {
            c = read();
        }
        int sgn = 1;
        if (c == '-') {
            sgn = -1;
            c = read();
        }
        long res = 0;
        do {
            if (c < '0' || c > '9') {
                throw new InputMismatchException();
            }
            res *= 10;
            res += c - '0';
            c = read();
        } while (!isSpaceChar(c));
        return res * sgn;
    }

    public String readString() {
        int c = read();
        while (isSpaceChar(c)) {
            c = read();
        }
        StringBuilder res = new StringBuilder();
        do {
            res.appendCodePoint(c);
            c = read();
        } while (!isSpaceChar(c));
        return res.toString();
    }

    public boolean isSpaceChar(int c) {
        return filter != null ? filter.isSpaceChar(c) : isWhitespace(c);
    }

    public double readDouble() {
        return Double.parseDouble(readString());
    }

    public static boolean isWhitespace(int c) {
        return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
    }

    public String next() {
        return readString();
    }

    public interface SpaceCharFilter {
        boolean isSpaceChar(int ch);
    }
}

