import java.util.StringTokenizer;

/**
 * Entry point for the application. Handles I/O setup and delegates to the solver.
 */
public class Main {
    public static void main(String[] args) {
        // Use try-with-resources to ensure streams are properly closed
        try (InputStream inputStream = System.in;
             OutputStream outputStream = System.out) {

            InputReader in = new InputReader(inputStream);
            PrintWriter out = new PrintWriter(outputStream);

            TaskB solver = new TaskB();
            // testNumber is passed for potential future extensibility but unused in current logic
            solver.solve(1, in, out);

            out.flush();
        } catch (IOException e) {
            throw new RuntimeException("I/O error occurred during execution", e);
        }
    }
}

/**
 * Core solver class. Refactored to be stateless to improve testability and reusability.
 * All grid state and dimensions are passed as method parameters.
 */
class TaskB {
    public void solve(int testNumber, InputReader in, PrintWriter out) {
        int n = in.nextInt();
        int m = in.nextInt();
        char[][] grid = new char[n][m];

        // Read grid input
        for (int i = 0; i < n; i++) {
            grid[i] = in.next().toCharArray();
        }

        // Count initial empty cells
        int emptyCells = 0;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == '.') {
                    emptyCells++;
                }
            }
        }

        // Initialize queue with degree-1 empty cells
        Queue<Coordinate> queue = new LinkedList<>();
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (getDegree(grid, n, m, i, j) == 1) {
                    queue.add(new Coordinate(i, j));
                }
            }
        }

        // Process queue until empty
        while (!queue.isEmpty()) {
            Coordinate current = queue.poll();

            // Skip already covered/processed cells
            if (grid[current.x][current.y] != '.') {
                continue;
            }

            Coordinate neighbor = findAdjacentEmpty(grid, n, m, current);
            if (neighbor == null) {
                continue;
            }

            coverPair(grid, current, neighbor);
            expandQueueWithNeighbors(queue, grid, n, m, current, neighbor);
            emptyCells -= 2;
        }

        // Output result
        if (emptyCells > 0) {
            out.println("Not unique");
        } else {
            for (int i = 0; i < n; i++) {
                out.println(new String(grid[i]));
            }
        }
    }

    /**
     * Calculates the orthogonal degree of a cell (number of adjacent empty cells).
     */
    private int getDegree(char[][] grid, int n, int m, int i, int j) {
        if (i < 0 || i >= n || j < 0 || j >= m || grid[i][j] != '.') {
            return 0;
        }
        int degree = 0;
        if (i > 0 && grid[i - 1][j] == '.') degree++;
        if (i + 1 < n && grid[i + 1][j] == '.') degree++;
        if (j > 0 && grid[i][j - 1] == '.') degree++;
        if (j + 1 < m && grid[i][j + 1] == '.') degree++;
        return degree;
    }

    /**
     * Finds the first orthogonally adjacent empty cell.
     */
    private Coordinate findAdjacentEmpty(char[][] grid, int n, int m, Coordinate p) {
        int[] dx = {-1, 1, 0, 0};
        int[] dy = {0, 0, -1, 1};
        for (int k = 0; k < 4; k++) {
            int nx = p.x + dx[k];
            int ny = p.y + dy[k];
            if (nx >= 0 && nx < n && ny >= 0 && ny < m && grid[nx][ny] == '.') {
                return new Coordinate(nx, ny);
            }
        }
        return null;
    }

    /**
     * Adds 8-directional neighbors with degree 1 to the processing queue.
     */
    private void expandQueueWithNeighbors(Queue<Coordinate> queue, char[][] grid, int n, int m, 
                                          Coordinate p1, Coordinate p2) {
        for (int dx = -1; dx <= 1; dx++) {
            for (int dy = -1; dy <= 1; dy++) {
                if (getDegree(grid, n, m, p1.x + dx, p1.y + dy) == 1) {
                    queue.add(new Coordinate(p1.x + dx, p1.y + dy));
                }
                if (getDegree(grid, n, m, p2.x + dx, p2.y + dy) == 1) {
                    queue.add(new Coordinate(p2.x + dx, p2.y + dy));
                }
            }
        }
    }

    /**
     * Marks a pair of adjacent cells with directional characters indicating orientation.
     */
    private void coverPair(char[][] grid, Coordinate p1, Coordinate p2) {
        if (p1.x == p2.x) {
            // Horizontal pair
            grid[p1.x][Math.min(p1.y, p2.y)] = '<';
            grid[p2.x][Math.max(p1.y, p2.y)] = '>';
        } else {
            // Vertical pair
            grid[Math.min(p1.x, p2.x)][p1.y] = '^';
            grid[Math.max(p1.x, p2.x)][p2.y] = 'v';
        }
    }

    /**
     * Immutable coordinate class for grid positions.
     */
    private static class Coordinate {
        final int x;
        final int y;

        Coordinate(int x, int y) {
            this.x = x;
            this.y = y;
        }
    }
}

/**
 * Fast input reader for competitive programming / performance-critical environments.
 */
class InputReader {
    private final BufferedReader reader;
    private StringTokenizer tokenizer;

    public InputReader(InputStream stream) {
        this.reader = new BufferedReader(new InputStreamReader(stream), 32768);
        this.tokenizer = null;
    }

    public String next() {
        while (tokenizer == null || !tokenizer.hasMoreTokens()) {
            try {
                String line = reader.readLine();
                if (line == null) {
                    return null;
                }
                tokenizer = new StringTokenizer(line);
            } catch (IOException e) {
                throw new RuntimeException("Failed to read input stream", e);
            }
        }
        return tokenizer.nextToken();
    }

    public int nextInt() {
        String token = next();
        if (token == null) {
            throw new RuntimeException("Unexpected end of input");
        }
        return Integer.parseInt(token);
    }
}

import java.io.*;
import java.util.*;

public class GridPathSolver {
    // Direction vectors: UP, RIGHT, DOWN, LEFT
    private static final int[] DX = {-1, 0, 1, 0};
    private static final int[] DY = {0, 1, 0, -1};

    // Maps each direction index to its opposite index (0↔2, 1↔3)
    private static final int[] OPPOSITE = {2, 3, 0, 1};

    // Direction symbols corresponding to indices 0, 1, 2, 3
    // Preserved from original logic: 0:UP->'v', 1:RIGHT->'<', 2:DOWN->'^', 3:LEFT->'>'
    private static final char[] DIRECTION_SYMBOLS = {'v', '<', '^', '>'};

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out));

        try {
            int n = scanner.nextInt();
            int m = scanner.nextInt();
            char[][] grid = new char[n][m];

            // Read grid input
            for (int i = 0; i < n; i++) {
                String line = scanner.next();
                grid[i] = line.toCharArray();
            }

            // Identify starting cells with exactly one adjacent '.'
            List<Integer> currentWave = new ArrayList<>();
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    if (isValid(grid, i, j, n, m) && countAdjacentDots(grid, i, j, n, m) == 1) {
                        currentWave.add(i * m + j);
                    }
                }
            }

            // Process waves of cells
            while (!currentWave.isEmpty()) {
                List<Integer> nextWave = new ArrayList<>();
                for (int pos : currentWave) {
                    int x = pos / m;
                    int y = pos % m;
                    int dir = getDirectionToNeighbor(grid, x, y, n, m);

                    if (dir == -1) continue;

                    int nx = x + DX[dir];
                    int ny = y + DY[dir];

                    // Mark current and neighbor cells with direction symbols
                    grid[x][y] = DIRECTION_SYMBOLS[dir];
                    grid[nx][ny] = DIRECTION_SYMBOLS[OPPOSITE[dir]];

                    // Check neighbors of the newly marked cell for next wave candidates
                    for (int d = 0; d < 4; d++) {
                        int nnx = nx + DX[d];
                        int nny = ny + DY[d];
                        if (isValid(grid, nnx, nny, n, m) && countAdjacentDots(grid, nnx, nny, n, m) == 1) {
                            nextWave.add(nnx * m + nny);
                        }
                    }
                }
                currentWave = nextWave;
            }

            // Check if any '.' cells remain unprocessed
            boolean hasRemainingDots = false;
            outer:
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    if (grid[i][j] == '.') {
                        hasRemainingDots = true;
                        break outer;
                    }
                }
            }

            if (hasRemainingDots) {
                out.println("Not unique");
            } else {
                for (int i = 0; i < n; i++) {
                    out.println(new String(grid[i]));
                }
            }
        } catch (Exception e) {
            e.printStackTrace();
        } finally {
            out.flush();
            out.close();
            try { scanner.br.close(); } catch (IOException ignored) {}
        }
    }

    /**
     * Checks if coordinates are within bounds and the cell contains '.'
     */
    private static boolean isValid(char[][] grid, int x, int y, int n, int m) {
        return x >= 0 && x < n && y >= 0 && y < m && grid[x][y] == '.';
    }

    /**
     * Counts the number of adjacent '.' cells
     */
    private static int countAdjacentDots(char[][] grid, int x, int y, int n, int m) {
        int count = 0;
        for (int d = 0; d < 4; d++) {
            if (isValid(grid, x + DX[d], y + DY[d], n, m)) {
                count++;
            }
        }
        return count;
    }

    /**
     * Returns the direction index to the single adjacent '.' cell.
     * Returns -1 if none exist. The algorithm guarantees exactly one when called.
     */
    private static int getDirectionToNeighbor(char[][] grid, int x, int y, int n, int m) {
        for (int d = 0; d < 4; d++) {
            if (isValid(grid, x + DX[d], y + DY[d], n, m)) {
                return d;
            }
        }
        return -1;
    }

    /**
     * Fast I/O helper class to replace standard Scanner for performance.
     */
    private static class FastScanner {
        BufferedReader br;
        StringTokenizer st;

        public FastScanner(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            String s = next();
            if (s == null) throw new NoSuchElementException("Unexpected end of input");
            return Integer.parseInt(s);
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.util.ArrayList;
import java.util.List;
import java.util.PriorityQueue;
import java.util.StringTokenizer;

public class GridTileSolver {

    /**
     * Represents a cell in the grid with its current degree in the dependency graph.
     */
    private static class Cell implements Comparable<Cell> {
        final int row;
        final int col;
        final int degree;

        Cell(int row, int col, int degree) {
            this.row = row;
            this.col = col;
            this.degree = degree;
        }

        @Override
        public int compareTo(Cell other) {
            return Integer.compare(this.degree, other.degree);
        }
    }

    private final int rows;
    private final int cols;
    private final char[][] grid;
    private final boolean[][] visited;
    private final int[][] degrees;
    private final PriorityQueue<Cell> pq;

    public GridTileSolver(String[] initialGrid) {
        this.rows = initialGrid.length;
        this.cols = initialGrid[0].length();
        this.grid = new char[rows][cols];
        this.visited = new boolean[rows][cols];
        this.degrees = new int[rows][cols];
        this.pq = new PriorityQueue<>();

        for (int i = 0; i < rows; i++) {
            grid[i] = initialGrid[i].toCharArray();
        }
    }

    /**
     * Executes the topological peeling algorithm to resolve tile directions.
     * @return The solved grid as a string, or "Not unique" if the solution is invalid.
     */
    public String solve() {
        initializeDegreesAndPriorityQueue();
        processTopologicalPeeling();
        validateCompletion();
        return formatOutput();
    }

    private void initializeDegreesAndPriorityQueue() {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '*') continue;

                int deg = getValidNeighbors(r, c).size();
                degrees[r][c] = deg;

                if (deg == 0) {
                    return; // Handled in validation step
                }
                if (deg == 1) {
                    pq.add(new Cell(r, c, 1));
                }
            }
        }
    }

    private void processTopologicalPeeling() {
        while (!pq.isEmpty()) {
            Cell current = pq.poll();

            // Skip if degree has changed or already processed
            if (current.degree != degrees[current.row][current.col] || visited[current.row][current.col]) {
                continue;
            }

            visited[current.row][current.col] = true;
            List<Cell> neighbors = getValidNeighbors(current.row, current.col);

            if (neighbors.size() != 1) {
                return; // Invalid state, handled in validation
            }

            Cell neighbor = neighbors.get(0);
            applyDirection(current, neighbor);
            visited[neighbor.row][neighbor.col] = true;

            List<Cell> updatedNeighbors = getValidNeighbors(neighbor.row, neighbor.col);
            for (Cell nextCell : updatedNeighbors) {
                if (!visited[nextCell.row][nextCell.col]) {
                    degrees[nextCell.row][nextCell.col]--;
                    if (degrees[nextCell.row][nextCell.col] == 1) {
                        pq.add(new Cell(nextCell.row, nextCell.col, 1));
                    }
                }
            }
        }
    }

    private void validateCompletion() {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (!visited[r][c] && grid[r][c] == '.') {
                    System.out.println("Not unique");
                    System.exit(0);
                }
            }
        }
    }

    private String formatOutput() {
        StringBuilder sb = new StringBuilder();
        for (char[] row : grid) {
            sb.append(row).append('\n');
        }
        return sb.toString();
    }

    /**
     * Returns a list of valid neighboring cells (empty and unvisited).
     */
    private List<Cell> getValidNeighbors(int r, int c) {
        List<Cell> neighbors = new ArrayList<>(4);
        int[] dr = {-1, 0, 0, 1};
        int[] dc = {0, -1, 1, 0};

        for (int k = 0; k < 4; k++) {
            int nr = r + dr[k];
            int nc = c + dc[k];
            if (isValid(nr, nc)) {
                neighbors.add(new Cell(nr, nc, 0));
            }
        }
        return neighbors;
    }

    private boolean isValid(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols 
            && grid[r][c] == '.' && !visited[r][c];
    }

    /**
     * Applies directional characters to the grid based on relative positions.
     */
    private void applyDirection(Cell c1, Cell c2) {
        char dir1, dir2;
        if (c1.row < c2.row) {
            dir1 = '^'; dir2 = 'v';
        } else if (c1.row > c2.row) {
            dir1 = 'v'; dir2 = '^';
        } else if (c1.col < c2.col) {
            dir1 = '<'; dir2 = '>';
        } else {
            dir1 = '>'; dir2 = '<';
        }
        grid[c1.row][c1.col] = dir1;
        grid[c2.row][c2.col] = dir2;
    }

    /**
     * Fast input reader for competitive programming environments.
     */
    private static class InputHelper {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public InputHelper(InputStream inputStream) {
            this.reader = new BufferedReader(new InputStreamReader(inputStream), 16384);
        }

        public String read() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input", e);
                }
            }
            return tokenizer.nextToken();
        }

        public int readInteger() {
            String token = read();
            if (token == null) throw new IllegalStateException("Unexpected end of input");
            return Integer.parseInt(token);
        }

        public long readLong() {
            String token = read();
            if (token == null) throw new IllegalStateException("Unexpected end of input");
            return Long.parseLong(token);
        }
    }

    public static void main(String[] args) {
        InputHelper in = new InputHelper(System.in);
        String nStr = in.read();
        if (nStr == null) return;

        int n = Integer.parseInt(nStr);
        int m = in.readInteger();

        String[] grid = new String[n];
        for (int i = 0; i < n; i++) {
            grid[i] = in.read();
        }

        System.out.print(new GridTileSolver(grid).solve());
    }
}

import java.util.LinkedList;
import java.util.Queue;
import java.util.Scanner;

/**
 * Solves a grid puzzle by filling empty cells with directional symbols
 * based on a topological sort-like approach (processing leaves first).
 */
public class GridSolver {

    // Direction vectors: Down (1,0), Right (0,1), Up (-1,0), Left (0,-1)
    // These correspond to the indices used for symbol mapping.
    private static final int[] ROW_OFFSETS = {1, 0, -1, 0};
    private static final int[] COL_OFFSETS = {0, 1, 0, -1};

    // Symbols corresponding to the directions above.
    // Preserving original mapping logic:
    // i=0 (Down):  S1='^', S2='v'
    // i=1 (Right): S1='<', S2='>'
    // i=2 (Up):    S1='v', S2='^'
    // i=3 (Left):  S1='>', S2='<'
    private static final char[] SYMBOL_A = {'^', '<', 'v', '>'};
    private static final char[] SYMBOL_B = {'v', '>', '^', '<'};

    /**
     * Helper class to store coordinates (row, col) in the grid.
     */
    private static class Point {
        int r, c;

        Point(int r, int c) {
            this.r = r;
            this.c = c;
        }
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        try {
            GridSolver solver = new GridSolver();
            solver.solve(scanner);
        } catch (Exception e) {
            // In a production environment, proper logging should be used.
            e.printStackTrace();
        } finally {
            scanner.close();
        }
    }

    /**
     * Executes the grid solving logic.
     *
     * @param scanner The input scanner.
     * @throws Exception If input reading fails.
     */
    public void solve(Scanner scanner) throws Exception {
        if (!scanner.hasNextInt()) return;

        int rows = scanner.nextInt();
        int cols = scanner.nextInt();

        char[][] grid = new char[rows][];
        int emptyCellCount = 0;
        int[][] degrees = new int[rows][cols];

        // 1. Read input grid and calculate initial degrees (number of empty neighbors)
        for (int r = 0; r < rows; r++) {
            String line = scanner.next();
            grid[r] = line.toCharArray();
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '.') {
                    emptyCellCount++;
                    // Count empty neighbors
                    for (int i = 0; i < 4; i++) {
                        int nr = r + ROW_OFFSETS[i];
                        int nc = c + COL_OFFSETS[i];
                        if (isValid(nr, nc, rows, cols) && grid[nr][nc] == '.') {
                            degrees[r][c]++;
                        }
                    }
                }
            }
        }

        // 2. Initialize queue with cells having degree 1 (leaves of the graph)
        Queue<Point> queue = new LinkedList<>();
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '.' && degrees[r][c] == 1) {
                    queue.add(new Point(r, c));
                }
            }
        }

        // 3. Process the queue (Topological sort / Peeling layers)
        while (!queue.isEmpty()) {
            Point p = queue.poll();
            int r = p.r;
            int c = p.c;

            // Iterate over neighbors to find the empty one
            for (int i = 0; i < 4; i++) {
                int nr = r + ROW_OFFSETS[i];
                int nc = c + COL_OFFSETS[i];

                // Check bounds and if neighbor is still empty
                if (isValid(nr, nc, rows, cols) && grid[nr][nc] == '.') {

                    // Found a pair of empty cells (r,c) and (nr,nc) to resolve
                    emptyCellCount -= 2;

                    // Assign symbols based on direction index
                    grid[r][c] = SYMBOL_A[i];
                    grid[nr][nc] = SYMBOL_B[i];

                    // Update degrees of neighbors of the newly occupied cell (nr, nc).
                    // Since (nr, nc) is no longer empty, its empty neighbors lose a degree.
                    for (int j = 0; j < 4; j++) {
                        int fr = nr + ROW_OFFSETS[j];
                        int fc = nc + COL_OFFSETS[j];

                        if (isValid(fr, fc, rows, cols) && grid[fr][fc] == '.') {
                            degrees[fr][fc]--;
                            // If a neighbor's degree drops to 1, it becomes a new leaf
                            if (degrees[fr][fc] == 1) {
                                queue.add(new Point(fr, fc));
                            }
                        }
                    }
                    // Note: The loop continues, but since (r,c) is now occupied, 
                    // subsequent checks for neighbors of (r,c) won't trigger logic 
                    // because grid[fr][fc] check will fail for (r,c).
                }
            }
        }

        // 4. Output result
        StringBuilder output = new StringBuilder();
        if (emptyCellCount > 0) {
            output.append("Not unique\n");
        } else {
            for (int r = 0; r < rows; r++) {
                output.append(grid[r]);
                output.append('\n');
            }
        }
        System.out.print(output);
    }

    /**
     * Checks if coordinates are within grid boundaries.
     */
    private boolean isValid(int r, int c, int rows, int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.LinkedList;
import java.util.Queue;
import java.util.StringTokenizer;

public class Main {

    // Direction vectors: Up, Down, Left, Right
    private static final int[] DR = {-1, 1, 0, 0};
    private static final int[] DC = {0, 0, -1, 1};

    // Directional arrows: [current_cell_arrow, neighbor_cell_arrow] for each direction
    private static final char[][] DIRECTION_ARROWS = {
        {'v', '^'}, // Up
        {'^', 'v'}, // Down
        {'>', '<'}, // Left
        {'<', '>'}  // Right
    };

    public static void main(String[] args) throws IOException {
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(System.in))) {
            String line = reader.readLine();
            if (line == null || line.trim().isEmpty()) {
                return;
            }

            StringTokenizer tokenizer = new StringTokenizer(line);
            int rows = Integer.parseInt(tokenizer.nextToken());
            int cols = Integer.parseInt(tokenizer.nextToken());

            char[][] grid = new char[rows][];
            for (int i = 0; i < rows; i++) {
                String rowLine = reader.readLine();
                grid[i] = (rowLine != null) ? rowLine.toCharArray() : new char[cols];
            }

            String result = solve(grid);
            System.out.print(result);
        }
    }

    /**
     * Orchestrates the grid processing algorithm.
     */
    private static String solve(char[][] grid) {
        int rows = grid.length;
        int cols = grid[0].length;

        int[][] degrees = calculateDegrees(grid, rows, cols);
        Queue<Point> queue = new LinkedList<>();

        // Initialize queue with boundary points (degree == 1)
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (degrees[r][c] == 1) {
                    queue.offer(new Point(r, c));
                }
            }
        }

        processGrid(grid, degrees, queue, rows, cols);

        return buildOutput(grid, rows, cols);
    }

    /**
     * Calculates the number of valid adjacent non-wall cells for each cell.
     */
    private static int[][] calculateDegrees(char[][] grid, int rows, int cols) {
        int[][] degrees = new int[rows][cols];
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '*') continue;
                for (int k = 0; k < 4; k++) {
                    int nr = r + DR[k];
                    int nc = c + DC[k];
                    if (isValid(nr, nc, rows, cols) && grid[nr][nc] != '*') {
                        degrees[r][c]++;
                    }
                }
            }
        }
        return degrees;
    }

    /**
     * Checks if coordinates are within grid boundaries.
     */
    private static boolean isValid(int r, int c, int rows, int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /**
     * Processes the queue, peeling layers and placing directional arrows.
     */
    private static void processGrid(char[][] grid, int[][] degrees, Queue<Point> queue, int rows, int cols) {
        while (!queue.isEmpty()) {
            Point current = queue.poll();
            if (current == null) continue;

            for (int k = 0; k < 4; k++) {
                int nr = current.r + DR[k];
                int nc = current.c + DC[k];

                if (isValid(nr, nc, rows, cols) && grid[nr][nc] == '.') {
                    // Place directional arrows
                    grid[current.r][current.c] = DIRECTION_ARROWS[k][0];
                    grid[nr][nc] = DIRECTION_ARROWS[k][1];

                    // Update degrees for the neighbor's other valid neighbors
                    for (int k2 = 0; k2 < 4; k2++) {
                        int nnr = nr + DR[k2];
                        int nnc = nc + DC[k2];
                        if (isValid(nnr, nnc, rows, cols) && grid[nnr][nnc] == '.') {
                            degrees[nnr][nnc]--;
                            if (degrees[nnr][nnc] == 1) {
                                queue.offer(new Point(nnr, nnc));
                            }
                        }
                    }
                    break; // Process only the first valid direction per point
                }
            }
        }
    }

    /**
     * Validates the final grid and formats the output.
     */
    private static String buildOutput(char[][] grid, int rows, int cols) {
        StringBuilder sb = new StringBuilder();
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '.') {
                    return "Not unique";
                }
                sb.append(grid[r][c]);
            }
            sb.append('\n');
        }
        return sb.toString();
    }

    /**
     * Immutable coordinate class representing a grid cell.
     */
    private static class Point {
        final int r;
        final int c;

        Point(int r, int c) {
            this.r = r;
            this.c = c;
        }
    }
}

import java.io.BufferedReader;
import java.io.FileInputStream;
import java.io.FileNotFoundException;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayDeque;
import java.util.Queue;
import java.util.StringTokenizer;

public class Main {
    // Direction indices: 0=RIGHT, 1=DOWN, 2=LEFT, 3=UP
    private static final int[] DELTA_ROW = {0, 1, 0, -1};
    private static final int[] DELTA_COL = {1, 0, -1, 0};

    // Tile mappings corresponding to direction indices.
    // tile[k][0] is placed at (y, x), tile[k][1] at (y + dy[k], x + dx[k])
    private static final char[][] TILE_MAP = {
            {'<', '>'},    // RIGHT
            {'^', 'v'},    // DOWN
            {'>', '<'},    // LEFT
            {'v', '^'}     // UP
    };

    public static void main(String[] args) throws IOException {
        ContestScanner scanner = new ContestScanner();
        int n = scanner.nextInt();
        int m = scanner.nextInt();

        char[][] grid = new char[n][m];
        int remainingEmptyCells = 0;

        for (int i = 0; i < n; i++) {
            String line = scanner.nextToken();
            grid[i] = line.toCharArray();
            for (char c : grid[i]) {
                if (c == '.') remainingEmptyCells++;
            }
        }

        Queue<Val> queue = new ArrayDeque<>();
        initializeQueue(grid, n, m, queue);

        while (!queue.isEmpty() && remainingEmptyCells > 0) {
            Val val = queue.poll();
            if (!processCell(grid, val)) {
                continue;
            }

            remainingEmptyCells -= 2;
            placeArrows(grid, val);

            if (remainingEmptyCells == 0) break;

            // Propagate logic to the newly filled neighbor
            int nextY = val.y + DELTA_ROW[val.k];
            int nextX = val.x + DELTA_COL[val.k];
            propagateFrom(grid, nextY, nextX, n, m, queue);
        }

        if (remainingEmptyCells == 0) {
            System.out.println(formatOutput(grid));
        } else {
            System.out.println("Not unique");
        }
    }

    /**
     * Scans the grid initially and adds cells with exactly one empty neighbor to the queue.
     */
    private static void initializeQueue(char[][] grid, int n, int m, Queue<Val> queue) {
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == '.') {
                    if (countEmptyNeighbors(grid, i, j, n, m) == 1) {
                        queue.add(new Val(i, j, findDirectionToEmpty(grid, i, j, n, m)));
                    }
                }
            }
        }
    }

    /**
     * Validates if the cell and its target neighbor are still empty and in bounds.
     */
    private static boolean processCell(char[][] grid, Val val) {
        int y = val.y;
        int x = val.x;
        int k = val.k;
        int nextY = y + DELTA_ROW[k];
        int nextX = x + DELTA_COL[k];

        if (!isInBounds(y, x, grid.length, grid[0].length)) return false;
        if (grid[y][x] != '.' || grid[nextY][nextX] != '.') return false;
        return true;
    }

    /**
     * Places the directional arrows on the grid based on the queue element.
     */
    private static void placeArrows(char[][] grid, Val val) {
        int k = val.k;
        grid[val.y][val.x] = TILE_MAP[k][0];
        grid[val.y + DELTA_ROW[k]][val.x + DELTA_COL[k]] = TILE_MAP[k][1];
    }

    /**
     * Checks the newly filled cell's neighbors. If any now have exactly one empty neighbor,
     * they are added to the queue for processing.
     */
    private static void propagateFrom(char[][] grid, int y, int x, int n, int m, Queue<Val> queue) {
        for (int k = 0; k < 4; k++) {
            int ny = y + DELTA_ROW[k];
            int nx = x + DELTA_COL[k];
            if (!isInBounds(ny, nx, n, m) || grid[ny][nx] != '.') continue;

            if (countEmptyNeighbors(grid, ny, nx, n, m) == 1) {
                queue.add(new Val(ny, nx, findDirectionToEmpty(grid, ny, nx, n, m)));
            }
        }
    }

    private static boolean isInBounds(int y, int x, int n, int m) {
        return y >= 0 && y < n && x >= 0 && x < m;
    }

    private static int countEmptyNeighbors(char[][] grid, int y, int x, int n, int m) {
        int count = 0;
        for (int k = 0; k < 4; k++) {
            int ny = y + DELTA_ROW[k];
            int nx = x + DELTA_COL[k];
            if (isInBounds(ny, nx, n, m) && grid[ny][nx] == '.') {
                count++;
            }
        }
        return count;
    }

    private static int findDirectionToEmpty(char[][] grid, int y, int x, int n, int m) {
        for (int k = 0; k < 4; k++) {
            int ny = y + DELTA_ROW[k];
            int nx = x + DELTA_COL[k];
            if (isInBounds(ny, nx, n, m) && grid[ny][nx] == '.') {
                return k;
            }
        }
        return -1; // Should not occur when called correctly
    }

    private static String formatOutput(char[][] grid) {
        StringBuilder sb = new StringBuilder();
        for (char[] row : grid) {
            sb.append(row).append('\n');
        }
        return sb.toString();
    }

    /**
     * Immutable data class representing a queue element.
     */
    static class Val {
        final int y, x, k;
        Val(int y, int x, int k) {
            this.y = y;
            this.x = x;
            this.k = k;
        }
    }

    /**
     * Robust input scanner using StringTokenizer to handle whitespace and newlines safely.
     */
    static class ContestScanner {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public ContestScanner() throws FileNotFoundException {
            this("stdin");
        }

        public ContestScanner(String source) throws FileNotFoundException {
            if (source.equals("stdin")) {
                reader = new BufferedReader(new InputStreamReader(System.in));
            } else {
                reader = new BufferedReader(new InputStreamReader(new FileInputStream(source)));
            }
            tokenizer = null;
        }

        private String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                String line = reader.readLine();
                if (line == null) throw new IOException("Unexpected end of input");
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public String nextToken() throws IOException {
            return next();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        public long nextLong() throws IOException {
            return Long.parseLong(next());
        }

        public double nextDouble() throws IOException {
            return Double.parseDouble(next());
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

/**
 * Solves a grid pathfinding problem.
 * Determines if there is a unique path through all '.' cells in the grid.
 * If valid, marks directions and prints the grid. Otherwise, prints "Not unique".
 */
public class GridPathSolver {
    private final int rows;
    private final int cols;
    private char[][] grid;
    private int totalDots;
    private int visitedDots;
    private boolean[][] visited;

    // Direction vectors: Down, Up, Right, Left
    private static final int[] DX = {1, -1, 0, 0};
    private static final int[] DY = {0, 0, 1, -1};
    // Corresponding direction characters for each vector index
    private static final char[] DIR_CHARS = {'v', '^', '>', '<'};

    public GridPathSolver(int rows, int cols) {
        this.rows = rows;
        this.cols = cols;
        this.grid = new char[rows][cols];
    }

    public static void main(String[] args) throws IOException {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        String line = reader.readLine();
        if (line == null || line.trim().isEmpty()) {
            return;
        }

        StringTokenizer st = new StringTokenizer(line);
        int n = Integer.parseInt(st.nextToken());
        int m = Integer.parseInt(st.nextToken());

        GridPathSolver solver = new GridPathSolver(n, m);
        solver.readInput(reader);
        solver.solve();
    }

    private void readInput(BufferedReader reader) throws IOException {
        for (int i = 0; i < rows; i++) {
            String rowLine = reader.readLine();
            if (rowLine != null) {
                grid[i] = rowLine.toCharArray();
            }
        }
    }

    public void solve() {
        totalDots = countDots();
        if (totalDots == 0) {
            printGrid();
            return;
        }

        visited = new boolean[rows][cols];
        int startR = -1;
        int startC = -1;

        // Find a starting point (a '.' with exactly one neighbor)
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '.' && countAdjacentDots(r, c) == 1) {
                    startR = r;
                    startC = c;
                    break;
                }
            }
            if (startR != -1) break;
        }

        // If no starting point found, it's not a valid simple path
        if (startR == -1) {
            System.out.println("Not unique");
            return;
        }

        visitedDots = 0;
        dfs(startR, startC);

        if (visitedDots == totalDots) {
            printGrid();
        } else {
            System.out.println("Not unique");
        }
    }

    private int countDots() {
        int count = 0;
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '.') {
                    count++;
                }
            }
        }
        return count;
    }

    private int countAdjacentDots(int r, int c) {
        int count = 0;
        for (int i = 0; i < 4; i++) {
            int nr = r + DX[i];
            int nc = c + DY[i];
            if (isInBounds(nr, nc) && grid[nr][nc] == '.') {
                count++;
            }
        }
        return count;
    }

    private void dfs(int r, int c) {
        if (!isInBounds(r, c) || grid[r][c] != '.' || visited[r][c]) {
            return;
        }

        visited[r][c] = true;
        visitedDots++;

        // Find the next unvisited neighbor
        for (int i = 0; i < 4; i++) {
            int nr = r + DX[i];
            int nc = c + DY[i];

            if (isInBounds(nr, nc) && grid[nr][nc] == '.' && !visited[nr][nc]) {
                // Mark direction from current cell to next cell
                grid[r][c] = DIR_CHARS[i];
                // Mark direction from next cell back to current cell
                grid[nr][nc] = DIR_CHARS[(i + 2) % 4];

                // Recurse to the next cell
                dfs(nr, nc);
                return; // Linear path assumption: only one valid next step
            }
        }
        // If no next neighbor, we've reached the end of the path
    }

    private boolean isInBounds(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    private void printGrid() {
        StringBuilder sb = new StringBuilder();
        for (int r = 0; r < rows; r++) {
            sb.append(grid[r]);
            sb.append('\n');
        }
        System.out.println(sb);
    }
}

import java.io.*;
import java.util.*;

/**
 * Solves the tile pairing problem by greedily pairing adjacent empty cells
 * with directional characters. Outputs "Not unique" if no valid pairing exists
 * or if multiple solutions are detected (though the greedy approach assumes uniqueness).
 */
public class TilePairingSolver {

    private static final String BAD_SOLUTION = "Not unique";
    private static final int[] DX = {-1, 0, 1, 0};
    private static final int[] DY = {0, -1, 0, 1};

    private final InputReader in;
    private final PrintWriter out;
    private int N, M;
    private char[][] grid;
    private int[] qx, qy;
    private int front, back;

    public TilePairingSolver(InputReader in, PrintWriter out) {
        this.in = in;
        this.out = out;
    }

    public static void main(String[] args) {
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
             PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out))) {

            InputReader inputReader = new InputReader(reader);
            TilePairingSolver solver = new TilePairingSolver(inputReader, out);
            solver.solve();
            out.flush();
        } catch (IOException e) {
            throw new RuntimeException("I/O error occurred", e);
        }
    }

    public void solve() {
        try {
            N = in.nextInt();
            M = in.nextInt();
            grid = new char[N][M];
            for (int i = 0; i < N; i++) {
                grid[i] = in.next().toCharArray();
            }

            int emptyCount = countEmptyCells();
            if (emptyCount % 2 != 0) {
                out.println(BAD_SOLUTION);
                return;
            }
            if (emptyCount == 0) {
                printGrid();
                return;
            }

            if (processGrid()) {
                printGrid();
            } else {
                out.println(BAD_SOLUTION);
            }
        } catch (Exception e) {
            out.println(BAD_SOLUTION);
        }
    }

    private int countEmptyCells() {
        int count = 0;
        for (int i = 0; i < N; i++) {
            for (int j = 0; j < M; j++) {
                if (grid[i][j] == '.') {
                    count++;
                }
            }
        }
        return count;
    }

    private int countNeighbors(int r, int c) {
        int count = 0;
        for (int k = 0; k < 4; k++) {
            int nr = r + DX[k];
            int nc = c + DY[k];
            if (isValid(nr, nc) && grid[nr][nc] == '.') {
                count++;
            }
        }
        return count;
    }

    private boolean isValid(int r, int c) {
        return r >= 0 && r < N && c >= 0 && c < M;
    }

    private boolean processGrid() {
        int maxCells = N * M;
        qx = new int[maxCells];
        qy = new int[maxCells];
        front = 0;
        back = 0;

        // Initial scan: identify cells with exactly one empty neighbor
        for (int i = 0; i < N; i++) {
            for (int j = 0; j < M; j++) {
                if (grid[i][j] == '.') {
                    int neighbors = countNeighbors(i, j);
                    if (neighbors == 0) {
                        return false;
                    } else if (neighbors == 1) {
                        qx[back] = i;
                        qy[back++] = j;
                    }
                }
            }
        }

        while (front < back) {
            int x = qx[front];
            int y = qy[front++];

            // Skip if already paired
            if (grid[x][y] != '.') {
                continue;
            }

            // Re-check neighbors in case state changed
            if (countNeighbors(x, y) == 0) {
                return false;
            }

            // Find an available neighbor to pair with
            int pairR = x, pairC = y;
            boolean paired = false;

            for (int k = 0; k < 4; k++) {
                int nr = x + DX[k];
                int nc = y + DY[k];
                if (isValid(nr, nc) && grid[nr][nc] == '.') {
                    pairCell(x, y, k);
                    pairR = nr;
                    pairC = nc;
                    paired = true;
                    break;
                }
            }

            if (!paired) {
                return false;
            }

            // Propagate to neighbors of the newly paired cell
            for (int k = 0; k < 4; k++) {
                int nr = pairR + DX[k];
                int nc = pairC + DY[k];
                if (isValid(nr, nc) && grid[nr][nc] == '.') {
                    int neighbors = countNeighbors(nr, nc);
                    if (neighbors == 0) {
                        return false;
                    } else if (neighbors == 1) {
                        qx[back] = nr;
                        qy[back++] = nc;
                    }
                }
            }
        }

        // Final validation: ensure no empty cells remain
        for (int i = 0; i < N; i++) {
            for (int j = 0; j < M; j++) {
                if (grid[i][j] == '.') {
                    return false;
                }
            }
        }
        return true;
    }

    private void pairCell(int r, int c, int dir) {
        char selfChar, pairChar;
        switch (dir) {
            case 0: selfChar = 'v'; pairChar = '^'; break; // Up
            case 1: selfChar = '>'; pairChar = '<'; break; // Left
            case 2: selfChar = '^'; pairChar = 'v'; break; // Down
            case 3: selfChar = '<'; pairChar = '>'; break; // Right
            default: throw new IllegalArgumentException("Invalid direction");
        }
        grid[r][c] = selfChar;
        grid[r + DX[dir]][c + DY[dir]] = pairChar;
    }

    private void printGrid() {
        for (int i = 0; i < N; i++) {
            out.println(new String(grid[i]));
        }
    }

    /**
     * Fast input reader for competitive programming scenarios.
     */
    static class InputReader {
        public BufferedReader reader;
        public StringTokenizer tokenizer;

        public InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            String s = next();
            if (s == null) throw new NoSuchElementException();
            return Integer.parseInt(s);
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Solves the arrow placement grid problem.
 * Refactored for maintainability, readability, and robust I/O handling.
 */
public class ArrowGridSolver {

    // Direction mappings: 0=down, 1=up, 2=right, 3=left
    // Note: Arrow symbols are mapped to these indices exactly as in the original implementation.
    private static final int[] DIR_R = {1, -1, 0, 0};
    private static final int[] DIR_C = {0, 0, 1, -1};
    private static final char[] ARROW_SYMBOLS = {'^', 'v', '<', '>'};

    private FastScanner in;
    private int rows;
    private int cols;
    private char[][] grid;

    public void run() {
        in = new FastScanner(System.in);
        // Use try-with-resources for automatic and safe resource cleanup
        try (PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out))) {
            solve(out);
            out.flush();
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    private void solve(PrintWriter out) throws IOException {
        rows = in.nextInt();
        cols = in.nextInt();
        grid = new char[rows][];
        for (int i = 0; i < rows; i++) {
            grid[i] = in.next().toCharArray();
        }

        // Attempt to resolve all '.' cells using DFS propagation
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (!dfs(r, c)) {
                    out.println("Not unique");
                    return;
                }
            }
        }

        // Verify no '.' cells remain unresolved
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '.') {
                    out.println("Not unique");
                    return;
                }
            }
        }

        // Output the resolved grid
        for (int r = 0; r < rows; r++) {
            out.println(new String(grid[r]));
        }
    }

    /**
     * Counts how many of the 4 neighboring cells are either out of bounds or not '.'
     */
    private int countValidNeighbors(int r, int c) {
        int count = 0;
        for (int d = 0; d < 4; d++) {
            int nr = r + DIR_R[d];
            int nc = c + DIR_C[d];
            if (nr < 0 || nr >= rows || nc < 0 || nc >= cols || grid[nr][nc] != '.') {
                count++;
            }
        }
        return count;
    }

    /**
     * Finds the direction index of the first '.' neighbor, or -1 if none exists.
     */
    private int findDotNeighborIndex(int r, int c) {
        for (int d = 0; d < 4; d++) {
            int nr = r + DIR_R[d];
            int nc = c + DIR_C[d];
            if (nr >= 0 && nr < rows && nc >= 0 && nc < cols && grid[nr][nc] == '.') {
                return d;
            }
        }
        return -1;
    }

    /**
     * Places an arrow symbol at the given cell based on the direction index.
     */
    private void placeArrow(int r, int c, int directionIndex) {
        grid[r][c] = ARROW_SYMBOLS[directionIndex];
    }

    /**
     * Recursive DFS to resolve forced arrow placements.
     * Returns false if a contradiction is found (unresolvable '.' cell).
     */
    private boolean dfs(int r, int c) {
        // Base case: out of bounds or not a dot
        if (r < 0 || r >= rows || c < 0 || c >= cols || grid[r][c] != '.') {
            return true;
        }

        int validNeighbors = countValidNeighbors(r, c);

        // If all 4 neighbors are invalid, placement is impossible
        if (validNeighbors == 4) {
            return false;
        }

        // If exactly 1 neighbor is a dot, we are forced to place arrows
        if (validNeighbors == 3) {
            int dotDirIndex = findDotNeighborIndex(r, c);
            int nr = r + DIR_R[dotDirIndex];
            int nc = c + DIR_C[dotDirIndex];

            // Place arrow at current cell
            placeArrow(r, c, dotDirIndex);
            // Place opposite arrow at the dot cell pointing back
            placeArrow(nr, nc, dotDirIndex ^ 1);

            // Recursively check the 4 neighbors of the newly placed arrow
            for (int d = 0; d < 4; d++) {
                if (!dfs(nr + DIR_R[d], nc + DIR_C[d])) {
                    return false;
                }
            }
        }

        return true;
    }

    public static void main(String[] args) {
        new ArrowGridSolver().run();
    }

    /**
     * Fast I/O helper class for competitive programming scenarios.
     */
    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input", e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            String token = next();
            if (token == null) throw new NoSuchElementException("End of input");
            return Integer.parseInt(token);
        }
    }
}

import java.io.InputStream;
import java.io.OutputStream;
import java.io.PrintWriter;
import java.util.LinkedList;
import java.util.Queue;
import java.util.InputMismatchException;
import java.io.IOException;

public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        TaskB solver = new TaskB();
        solver.solve(1, in, out);
        out.close();
    }
}

class TaskB {
    private static final int[] DI = {1, 0, -1, 0};
    private static final int[] DJ = {0, -1, 0, 1};
    private static final char EMPTY = '.';

    public void solve(int testNumber, InputReader in, PrintWriter out) {
        int n = in.nextInt();
        int m = in.nextInt();
        char[][] grid = new char[n][];
        for (int i = 0; i < n; i++) {
            grid[i] = in.nextString().toCharArray();
        }

        int[][] adjCount = new int[n][m];
        Queue<Point> queue = new LinkedList<>();

        // Initialize adjacency counts and seed the queue with leaf nodes
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == EMPTY) {
                    int count = countAdjacentEmpty(grid, i, j);
                    adjCount[i][j] = count;
                    if (count == 1) {
                        queue.add(new Point(i, j));
                    }
                }
            }
        }

        // Process the queue (BFS-like traversal)
        while (!queue.isEmpty()) {
            Point current = queue.poll();
            if (grid[current.r][current.c] != EMPTY) {
                continue;
            }

            Point neighbor = findAdjacentEmpty(grid, current.r, current.c);
            if (neighbor == null) {
                continue;
            }

            markDirection(grid, current, neighbor);
            updateNeighborCount(grid, adjCount, neighbor, queue);
        }

        // Validate that all empty cells have been processed
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == EMPTY) {
                    out.println("Not unique");
                    return;
                }
            }
        }

        // Output the processed grid
        for (char[] row : grid) {
            out.println(row);
        }
    }

    private int countAdjacentEmpty(char[][] grid, int r, int c) {
        int count = 0;
        for (int d = 0; d < 4; d++) {
            int nr = r + DI[d];
            int nc = c + DJ[d];
            if (isValid(grid, nr, nc) && grid[nr][nc] == EMPTY) {
                count++;
            }
        }
        return count;
    }

    private boolean isValid(char[][] grid, int r, int c) {
        return r >= 0 && r < grid.length && c >= 0 && c < grid[0].length;
    }

    private Point findAdjacentEmpty(char[][] grid, int r, int c) {
        for (int d = 0; d < 4; d++) {
            int nr = r + DI[d];
            int nc = c + DJ[d];
            if (isValid(grid, nr, nc) && grid[nr][nc] == EMPTY) {
                return new Point(nr, nc);
            }
        }
        return null;
    }

    private void markDirection(char[][] grid, Point current, Point neighbor) {
        if (current.r == neighbor.r) {
            grid[current.r][current.c] = current.c > neighbor.c ? '>' : '<';
        } else {
            grid[current.r][current.c] = current.r > neighbor.r ? 'v' : '^';
        }
    }

    private void updateNeighborCount(char[][] grid, int[][] adjCount, Point neighbor, Queue<Point> queue) {
        adjCount[neighbor.r][neighbor.c]--;
        if (adjCount[neighbor.r][neighbor.c] == 1) {
            queue.add(neighbor);
        }
    }

    private static final class Point {
        final int r, c;

        Point(int r, int c) {
            this.r = r;
            this.c = c;
        }
    }
}

class InputReader {
    private final InputStream stream;
    private final byte[] buf = new byte[1024];
    private int curChar;
    private int numChars;

    public InputReader(InputStream stream) {
        this.stream = stream;
    }

    public int read() {
        if (numChars == -1) {
            throw new InputMismatchException();
        }
        if (curChar >= numChars) {
            curChar = 0;
            try {
                numChars = stream.read(buf);
            } catch (IOException e) {
                throw new InputMismatchException();
            }
            if (numChars <= 0) {
                return -1;
            }
        }
        return buf[curChar++];
    }

    public int nextInt() {
        return Integer.parseInt(nextString());
    }

    public String nextString() {
        int c = read();
        while (isSpaceChar(c)) {
            c = read();
        }
        StringBuilder res = new StringBuilder();
        do {
            res.appendCodePoint(c);
            c = read();
        } while (!isSpaceChar(c));
        return res.toString();
    }

    private boolean isSpaceChar(int c) {
        return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayDeque;
import java.util.Arrays;
import java.util.Deque;
import java.util.StringTokenizer;

public class CF292B {

    private static final String NOT_UNIQUE = "Not unique";
    private static final char EMPTY = '.';
    private static final char BOUNDARY = '*';

    /**
     * Represents movement direction on the grid along with the corresponding arrow characters.
     * Standard matrix coordinates: row increases downward, column increases rightward.
     */
    private enum Direction {
        DOWN(1, 0, 'v', '^'),
        UP(-1, 0, '^', 'v'),
        RIGHT(0, 1, '>', '<'),
        LEFT(0, -1, '<', '>');

        final int dr, dc;
        final char arrowAtCurrent, arrowAtNext;

        Direction(int dr, int dc, char cur, char next) {
            this.dr = dr;
            this.dc = dc;
            this.arrowAtCurrent = cur;
            this.arrowAtNext = next;
        }
    }

    /**
     * Holds the state for queue processing: cell coordinates and the direction to fill.
     */
    private static class State {
        final int r, c;
        final Direction dir;

        State(int r, int c, Direction dir) {
            this.r = r;
            this.c = c;
            this.dir = dir;
        }
    }

    public static void main(String[] args) {
        FastScanner sc = new FastScanner();
        int rows = sc.nextInt();
        int cols = sc.nextInt();

        // 1. Read input and pad the board to avoid boundary checks
        char[][] board = padBoard(rows, cols, sc);

        // 2. Quick parity check: odd number of empty cells means impossible to pair
        int emptyCount = countEmpties(board);
        if (emptyCount % 2 != 0) {
            System.out.println(NOT_UNIQUE);
            return;
        }

        // 3. Initialize queue with cells that have exactly one empty neighbor
        Deque<State> queue = initializeQueue(board);

        // 4. Greedily fill pairs and propagate changes
        emptyCount = processQueue(board, queue, emptyCount);

        // 5. Output result
        if (emptyCount != 0) {
            System.out.println(NOT_UNIQUE);
        } else {
            printBoard(board);
        }
    }

    private static char[][] padBoard(int rows, int cols, FastScanner sc) {
        char[][] board = new char[rows + 2][cols + 2];
        Arrays.fill(board[0], BOUNDARY);
        Arrays.fill(board[board.length - 1], BOUNDARY);

        for (int i = 1; i <= rows; i++) {
            String line = sc.next();
            board[i][0] = BOUNDARY;
            board[i][cols + 1] = BOUNDARY;
            for (int j = 0; j < cols; j++) {
                board[i][j + 1] = line.charAt(j);
            }
        }
        return board;
    }

    private static int countEmpties(char[][] board) {
        int count = 0;
        for (int i = 1; i < board.length - 1; i++) {
            for (int j = 1; j < board[i].length - 1; j++) {
                if (board[i][j] == EMPTY) {
                    count++;
                }
            }
        }
        return count;
    }

    private static Deque<State> initializeQueue(char[][] board) {
        Deque<State> queue = new ArrayDeque<>();
        for (int i = 1; i < board.length - 1; i++) {
            for (int j = 1; j < board[i].length - 1; j++) {
                if (board[i][j] == EMPTY) {
                    Direction dir = findSingleEmptyNeighbor(board, i, j);
                    if (dir != null) {
                        queue.add(new State(i, j, dir));
                    }
                }
            }
        }
        return queue;
    }

    /**
     * Returns the Direction if exactly one neighbor is empty, otherwise null.
     */
    private static Direction findSingleEmptyNeighbor(char[][] board, int r, int c) {
        Direction found = null;
        for (Direction d : Direction.values()) {
            if (board[r + d.dr][c + d.dc] == EMPTY) {
                if (found != null) {
                    return null; // More than one empty neighbor
                }
                found = d;
            }
        }
        return found;
    }

    /**
     * Processes the queue, fills arrow pairs, and propagates new candidates.
     * Returns the remaining number of empty cells.
     */
    private static int processQueue(char[][] board, Deque<State> queue, int emptyCount) {
        while (!queue.isEmpty()) {
            State current = queue.poll();
            int r = current.r;
            int c = current.c;
            Direction dir = current.dir;

            // Skip if already filled (handles duplicate queue entries safely)
            if (board[r][c] != EMPTY) continue;

            int nr = r + dir.dr;
            int nc = c + dir.dc;
            if (board[nr][nc] != EMPTY) continue;

            // Fill the pair
            board[r][c] = dir.arrowAtCurrent;
            board[nr][nc] = dir.arrowAtNext;
            emptyCount -= 2;

            // Check neighbors of the newly filled cell for new candidates
            for (Direction d : Direction.values()) {
                int ni = nr + d.dr;
                int nj = nc + d.dc;
                if (board[ni][nj] == EMPTY) {
                    Direction singleDir = findSingleEmptyNeighbor(board, ni, nj);
                    if (singleDir != null) {
                        queue.add(new State(ni, nj, singleDir));
                    }
                }
            }
        }
        return emptyCount;
    }

    private static void printBoard(char[][] board) {
        StringBuilder sb = new StringBuilder();
        for (int i = 1; i < board.length - 1; i++) {
            sb.append(board[i], 1, board[i].length - 2);
            sb.append('\n');
        }
        System.out.print(sb);
    }

    /**
     * Fast I/O utility class. Replaces java.util.Scanner for performance.
     */
    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input", e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            String token = next();
            return token == null ? 0 : Integer.parseInt(token);
        }
    }
}

import java.io.*;
import java.util.*;

public class Solution {
    // Direction deltas for moving up, down, left, right
    private static final int[] DX = {1, -1, 0, 0};
    private static final int[] DY = {0, 0, 1, -1};

    private int[][] degree;
    private int[] queue;
    private int rows, cols;
    private char[][] grid;

    public static void main(String[] args) {
        // Use try-with-resources for automatic resource management
        try (FastReader reader = new FastReader(System.in);
             PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out))) {
            Solution solver = new Solution();
            solver.processInput(reader, out);
            out.flush();
        } catch (IOException e) {
            System.err.println("I/O error: " + e.getMessage());
        }
    }

    /**
     * Orchestrates the grid processing pipeline:
     * 1. Reads dimensions and grid data
     * 2. Computes initial adjacency degrees
     * 3. Runs a topological-sort-like leaf peeling algorithm
     * 4. Validates uniqueness and outputs the result
     */
    private void processInput(FastReader reader, PrintWriter out) throws IOException {
        rows = reader.nextInt();
        cols = reader.nextInt();
        grid = new char[rows][cols];
        degree = new int[rows][cols];
        queue = new int[rows * cols]; // Dynamic sizing replaces hardcoded max

        // Read the grid rows
        for (int i = 0; i < rows; i++) {
            String line = reader.nextLine();
            if (line != null) {
                grid[i] = line.toCharArray();
            }
        }

        // Compute initial adjacency degrees for each '.' cell
        computeDegrees();

        // Process the queue using a leaf-peeling approach
        processQueue(out);

        // Validate and print the result
        validateAndOutput(out);
    }

    /** Checks if coordinates are within the grid boundaries */
    private boolean isWithinBounds(int x, int y) {
        return x >= 0 && x < rows && y >= 0 && y < cols;
    }

    /**
     * Marks the directional relationship between two adjacent cells.
     * Ensures consistent arrow directions for horizontal and vertical edges.
     */
    private void markEdge(int x1, int y1, int x2, int y2) {
        if (x1 == x2) { // Horizontal edge
            if (y1 > y2) {
                int temp = y2; y2 = y1; y1 = temp;
            }
            grid[x1][y1] = '<';
            grid[x2][y2] = '>';
        } else { // Vertical edge
            if (x1 > x2) {
                int temp = x1; x1 = x2; x2 = temp;
            }
            grid[x1][y1] = '^';
            grid[x2][y2] = 'v';
        }
    }

    /** Calculates the number of adjacent '.' neighbors for each cell */
    private void computeDegrees() {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == '*') continue;
                for (int d = 0; d < 4; d++) {
                    int nx = i + DX[d];
                    int ny = j + DY[d];
                    if (isWithinBounds(nx, ny) && grid[nx][ny] == '.') {
                        degree[i][j]++;
                    }
                }
            }
        }
    }

    /**
     * Processes the queue using a topological-sort-like leaf peeling algorithm.
     * Iteratively removes leaf nodes (degree == 1) and marks edges until
     * no more leaves exist or the graph is fully processed.
     */
    private void processQueue(PrintWriter out) {
        int head = 0, tail = 0;

        // Initialize queue with leaf nodes
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (degree[i][j] == 1) {
                    queue[tail++] = i * cols + j;
                }
            }
        }

        while (head < tail) {
            int v = queue[head++];
            int cx = v / cols;
            int cy = v % cols;

            // Skip if already processed or modified
            if (grid[cx][cy] != '.') continue;

            for (int d = 0; d < 4; d++) {
                int nx = cx + DX[d];
                int ny = cy + DY[d];

                if (!isWithinBounds(nx, ny) || grid[nx][ny] != '.') continue;

                // Mark the edge between current cell and neighbor
                markEdge(nx, ny, cx, cy);

                // Decrease degree of all '.' neighbors of the marked neighbor
                for (int i = 0; i < 4; i++) {
                    int x = nx + DX[i];
                    int y = ny + DY[i];
                    if (isWithinBounds(x, y) && grid[x][y] == '.') {
                        degree[x][y]--;
                        if (degree[x][y] == 1) {
                            queue[tail++] = x * cols + y;
                        }
                    }
                }
            }
        }
    }

    /** Checks if any '.' remains unmarked and outputs the appropriate result */
    private void validateAndOutput(PrintWriter out) {
        // If any '.' remains, the solution is not unique
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == '.') {
                    out.println("Not unique");
                    return;
                }
            }
        }

        // Output the successfully processed grid
        for (int i = 0; i < rows; i++) {
            out.println(new String(grid[i]));
        }
    }

    /**
     * Fast I/O helper class to handle tokenized and line-based input efficiently.
     * Replaces inline BufferedReader/StringTokenizer logic with a reusable component.
     */
    static class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastReader(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        public String nextToken() {
            try {
                while (st == null || !st.hasMoreTokens()) {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                }
                return st.nextToken();
            } catch (IOException e) {
                throw new RuntimeException("Failed to read input", e);
            }
        }

        public String nextLine() {
            try {
                return br.readLine();
            } catch (IOException e) {
                throw new RuntimeException("Failed to read line", e);
            }
        }

        public int nextInt() {
            String token = nextToken();
            return token == null ? 0 : Integer.parseInt(token);
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.Arrays;

/**
 * Solves a grid-based path uniqueness problem using constraint propagation.
 * Reads dimensions and a grid, resolves forced moves, and outputs the resulting path
 * or "Not unique" if constraints cannot be satisfied.
 */
public class GridPathSolver {

    // Grid cell states
    private static final int EMPTY = 0;
    private static final int WALL = 1;
    private static final int DIR_DOWN = 2;
    private static final int DIR_UP = 3;
    private static final int DIR_RIGHT = 4;
    private static final int DIR_LEFT = 5;

    public static void main(String[] args) throws IOException {
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(System.in))) {
            String[] dimensions = reader.readLine().trim().split("\\s+");
            int n = Integer.parseInt(dimensions[0]);
            int m = Integer.parseInt(dimensions[1]);

            int[][] grid = initializeGrid(reader, n, m);

            if (!solveAndPrint(grid, n, m)) {
                System.out.println("Not unique");
            }
        }
    }

    /**
     * Reads the grid from input and wraps it with a border of walls.
     */
    private static int[][] initializeGrid(BufferedReader reader, int n, int m) throws IOException {
        int[][] map = new int[n + 2][m + 2];
        for (int[] row : map) {
            Arrays.fill(row, WALL);
        }
        for (int i = 0; i < n; i++) {
            String line = reader.readLine();
            for (int j = 0; j < m; j++) {
                map[i + 1][j + 1] = (line.charAt(j) == '.') ? EMPTY : WALL;
            }
        }
        return map;
    }

    /**
     * Runs the constraint propagation algorithm and prints the result.
     */
    private static boolean solveAndPrint(int[][] map, int n, int m) {
        int[][] degrees = calculateAdjacentEmptyCounts(map, n, m);
        boolean changed = true;

        while (changed) {
            boolean allResolvedOrTriggered = true;
            changed = false;

            for (int i = 1; i <= n; i++) {
                for (int j = 1; j <= m; j++) {
                    if (map[i][j] == EMPTY && degrees[i][j] == 1) {
                        changed = true;
                        if (!traceAndResolvePath(map, degrees, i, j)) {
                            return false;
                        }
                    } else if (map[i][j] == EMPTY) {
                        allResolvedOrTriggered = false;
                    }
                }
            }

            // If we didn't find any cells with exactly 1 neighbor to trigger resolution,
            // but there are still unresolved empty cells, the path is not unique/valid.
            if (!allResolvedOrTriggered && !changed) {
                return false;
            }
        }

        printGrid(map, n, m);
        return true;
    }

    /**
     * Calculates the number of adjacent empty neighbors for each cell.
     */
    private static int[][] calculateAdjacentEmptyCounts(int[][] map, int n, int m) {
        int[][] degrees = new int[n + 2][m + 2];
        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= m; j++) {
                if (map[i][j] != EMPTY) continue;
                degrees[i][j] = countEmptyNeighbors(map, i, j);
            }
        }
        return degrees;
    }

    private static int countEmptyNeighbors(int[][] map, int i, int j) {
        int count = 0;
        if (map[i - 1][j] == EMPTY) count++;
        if (map[i + 1][j] == EMPTY) count++;
        if (map[i][j - 1] == EMPTY) count++;
        if (map[i][j + 1] == EMPTY) count++;
        return count;
    }

    /**
     * Traces and resolves a path starting from a cell with exactly one empty neighbor.
     * Propagates constraints until the path terminates or a conflict is detected.
     */
    private static boolean traceAndResolvePath(int[][] map, int[][] degrees, int startI, int startJ) {
        int k = startI;
        int l = startJ;

        while (map[k][l] == EMPTY && degrees[k][l] == 1) {
            boolean moved = false;

            // Check UP
            if (map[k - 1][l] == EMPTY) {
                map[k][l] = DIR_DOWN;
                map[k - 1][l] = DIR_UP;
                relax(degrees, k, l);
                k--;
                relax(degrees, k, l);
                if (degrees[k - 1][l] == 1) k--;
                if (degrees[k][l - 1] == 1) l--;
                if (degrees[k][l + 1] == 1) l++;
                moved = true;
            }
            // Check LEFT
            else if (map[k][l - 1] == EMPTY) {
                map[k][l] = DIR_RIGHT;
                map[k][l - 1] = DIR_LEFT;
                relax(degrees, k, l);
                l--;
                relax(degrees, k, l);
                if (degrees[k - 1][l] == 1) k--;
                if (degrees[k + 1][l] == 1) k++;
                if (degrees[k][l - 1] == 1) l--;
                moved = true;
            }
            // Check DOWN
            else if (map[k + 1][l] == EMPTY) {
                map[k][l] = DIR_UP;
                map[k + 1][l] = DIR_DOWN;
                relax(degrees, k, l);
                k++;
                relax(degrees, k, l);
                if (degrees[k + 1][l] == 1) k++;
                if (degrees[k][l - 1] == 1) l--;
                if (degrees[k][l + 1] == 1) l++;
                moved = true;
            }
            // Check RIGHT
            else if (map[k][l + 1] == EMPTY) {
                map[k][l] = DIR_LEFT;
                map[k][l + 1] = DIR_RIGHT;
                relax(degrees, k, l);
                l++;
                relax(degrees, k, l);
                if (degrees[k - 1][l] == 1) k--;
                if (degrees[k + 1][l] == 1) k++;
                if (degrees[k][l + 1] == 1) l++;
                moved = true;
            }

            if (!moved) {
                return false;
            }
        }
        return true;
    }

    /**
     * Decrements the neighbor degree counts after a cell is processed.
     */
    private static void relax(int[][] degrees, int k, int l) {
        if (degrees[k - 1][l] > 0) degrees[k - 1][l]--;
        if (degrees[k + 1][l] > 0) degrees[k + 1][l]--;
        if (degrees[k][l - 1] > 0) degrees[k][l - 1]--;
        if (degrees[k][l + 1] > 0) degrees[k][l + 1]--;
    }

    /**
     * Prints the resolved grid to standard output.
     */
    private static void printGrid(int[][] map, int n, int m) {
        for (int i = 1; i <= n; i++) {
            StringBuilder line = new StringBuilder();
            for (int j = 1; j <= m; j++) {
                int state = map[i][j];
                if (state == WALL) {
                    line.append('*');
                } else {
                    line.append(getDirectionChar(state));
                }
            }
            System.out.println(line);
        }
    }

    private static char getDirectionChar(int state) {
        switch (state) {
            case DIR_DOWN: return 'v';
            case DIR_UP: return '^';
            case DIR_RIGHT: return '>';
            case DIR_LEFT: return '<';
            default: return ' ';
        }
    }
}

import java.io.*;
import java.util.*;

public class Main {
    // Direction vectors: Down, Up, Right, Left
    private static final int[] DX = {1, -1, 0, 0};
    private static final int[] DY = {0, 0, 1, -1};

    public static void main(String[] args) throws IOException {
        FastScanner sc = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out);

        int n = sc.nextInt();
        int m = sc.nextInt();

        char[][] grid = new char[n][m];
        for (int i = 0; i < n; i++) {
            grid[i] = sc.next().toCharArray();
        }

        // Count valid adjacent '.' cells for each position
        int[][] neighborCount = new int[n][m];
        Queue<Point> queue = new ArrayDeque<>();

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == '.') {
                    int count = 0;
                    for (int d = 0; d < 4; d++) {
                        int ni = i + DX[d];
                        int nj = j + DY[d];
                        if (isValid(ni, nj, n, m) && grid[ni][nj] == '.') {
                            count++;
                        }
                    }
                    neighborCount[i][j] = count;
                    // Start processing from cells with exactly one neighbor (leaves of the graph)
                    if (count == 1) {
                        queue.add(new Point(i, j));
                    }
                }
            }
        }

        // Process cells in topological order (leaves inward)
        while (!queue.isEmpty()) {
            Point p = queue.poll();
            int r = p.row;
            int c = p.col;

            // Skip if already resolved or invalid count
            if (neighborCount[r][c] <= 0 || grid[r][c] != '.') {
                continue;
            }

            // Find the only remaining neighbor
            int targetR = -1, targetC = -1;
            for (int d = 0; d < 4; d++) {
                int nr = r + DX[d];
                int nc = c + DY[d];
                if (isValid(nr, nc, n, m) && grid[nr][nc] == '.') {
                    targetR = nr;
                    targetC = nc;
                    break;
                }
            }

            // Safety check: should not happen if count was 1
            if (targetR == -1) continue;

            // Determine relative direction and assign appropriate arrows
            int dr = targetR - r;
            int dc = targetC - c;

            char currentArrow, targetArrow;
            if (dr == -1) {          // Moving Up
                currentArrow = 'v';
                targetArrow = '^';
            } else if (dc == -1) {   // Moving Left
                currentArrow = '>';
                targetArrow = '<';
            } else if (dc == 1) {    // Moving Right
                currentArrow = '<';
                targetArrow = '>';
            } else {                 // Moving Down
                currentArrow = '^';
                targetArrow = 'v';
            }

            grid[r][c] = currentArrow;
            grid[targetR][targetC] = targetArrow;

            // Update neighbor counts for the target cell's neighbors
            // The resolved cell is no longer a valid neighbor, so decrement counts
            for (int d = 0; d < 4; d++) {
                int nnr = targetR + DX[d];
                int nnc = targetC + DY[d];
                if (isValid(nnr, nnc, n, m) && grid[nnr][nnc] == '.') {
                    neighborCount[nnr][nnc]--;
                    if (neighborCount[nnr][nnc] == 1) {
                        queue.add(new Point(nnr, nnc));
                    }
                }
            }
        }

        // Check if any '.' remains unresolved
        boolean hasUnresolved = false;
        outerLoop:
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == '.') {
                    hasUnresolved = true;
                    break outerLoop;
                }
            }
        }

        if (hasUnresolved) {
            out.println("Not unique");
        } else {
            for (int i = 0; i < n; i++) {
                out.println(grid[i]);
            }
        }
        out.flush();
    }

    /** Checks if coordinates are within grid bounds */
    private static boolean isValid(int r, int c, int rows, int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /** Immutable class to hold 2D coordinates */
    private static class Point {
        final int row, col;
        Point(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    /** Fast I/O helper class for competitive programming / large inputs */
    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

