public class Main {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        PrintWriter out = new PrintWriter(System.out);
        new GridPairingSolver().solve(in, out);
        out.flush();
    }

    /**
     * Solves the grid pairing problem by treating dots as nodes in a graph
     * and iteratively pairing leaves (cells with exactly one valid neighbor).
     */
    private static class GridPairingSolver {
        private int n, m;
        private static final int[] DR = {-1, 1, 0, 0};
        private static final int[] DC = {0, 0, -1, 1};

        void solve(Scanner in, PrintWriter out) {
            n = in.nextInt();
            m = in.nextInt();
            char[][] grid = new char[n][m];
            for (int i = 0; i < n; i++) {
                grid[i] = in.next().toCharArray();
            }

            int[][] neighborCount = new int[n][m];
            int[][] pairedWith = new int[n][m]; // Stores encoded coordinate of paired cell
            boolean[][] isPaired = new boolean[n][m];
            Queue<int[]> queue = new ArrayDeque<>();

            // Step 1: Initialize neighbor counts and seed the queue with leaf nodes
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    if (grid[i][j] == '.') {
                        int count = countValidNeighbors(i, j, grid, isPaired);
                        neighborCount[i][j] = count;
                        if (count == 0) {
                            out.print("Not unique");
                            return;
                        }
                        if (count == 1) {
                            queue.offer(new int[]{i, j});
                        }
                    }
                }
            }

            // Step 2: Process cells with exactly one valid neighbor (peeling leaves)
            while (!queue.isEmpty()) {
                int[] curr = queue.poll();
                int r = curr[0];
                int c = curr[1];

                // If already paired or count changed, the solution is invalid
                if (isPaired[r][c] || neighborCount[r][c] != 1) {
                    out.print("Not unique");
                    return;
                }

                int[] neighbor = findSingleNeighbor(r, c, grid, isPaired);
                if (neighbor == null) {
                    out.print("Not unique");
                    return;
                }
                int nr = neighbor[0];
                int nc = neighbor[1];

                // Pair the cells
                isPaired[r][c] = true;
                isPaired[nr][nc] = true;
                pairedWith[r][c] = encode(nr, nc);
                pairedWith[nr][nc] = encode(r, c);

                // Update neighbor counts for adjacent cells and enqueue newly valid ones
                updateAndEnqueue(r, c, grid, isPaired, neighborCount, queue);
                updateAndEnqueue(nr, nc, grid, isPaired, neighborCount, queue);
            }

            // Step 3: Verify all dots were successfully paired
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    if (grid[i][j] == '.' && !isPaired[i][j]) {
                        out.print("Not unique");
                        return;
                    }
                }
            }

            // Step 4: Output the result
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    if (grid[i][j] != '.') {
                        out.print('*');
                    } else {
                        int[] paired = decode(pairedWith[i][j]);
                        out.print(getArrow(i, j, paired[0], paired[1]));
                    }
                }
                out.println();
            }
        }

        private boolean isValid(int r, int c, char[][] grid, boolean[][] isPaired) {
            return r >= 0 && c >= 0 && r < n && c < m && grid[r][c] == '.' && !isPaired[r][c];
        }

        private int countValidNeighbors(int r, int c, char[][] grid, boolean[][] isPaired) {
            int count = 0;
            for (int k = 0; k < 4; k++) {
                if (isValid(r + DR[k], c + DC[k], grid, isPaired)) {
                    count++;
                }
            }
            return count;
        }

        private int[] findSingleNeighbor(int r, int c, char[][] grid, boolean[][] isPaired) {
            for (int k = 0; k < 4; k++) {
                int nr = r + DR[k];
                int nc = c + DC[k];
                if (isValid(nr, nc, grid, isPaired)) {
                    return new int[]{nr, nc};
                }
            }
            return null;
        }

        private void updateAndEnqueue(int r, int c, char[][] grid, boolean[][] isPaired, 
                                      int[][] neighborCount, Queue<int[]> queue) {
            for (int k = 0; k < 4; k++) {
                int nr = r + DR[k];
                int nc = c + DC[k];
                if (isValid(nr, nc, grid, isPaired)) {
                    neighborCount[nr][nc]--;
                    if (neighborCount[nr][nc] == 1) {
                        queue.offer(new int[]{nr, nc});
                    }
                }
            }
        }

        private int encode(int r, int c) {
            return r * m + c;
        }

        private int[] decode(int encoded) {
            return new int[]{encoded / m, encoded % m};
        }

        private char getArrow(int r, int c, int pr, int pc) {
            if (r == pr) {
                return c < pc ? '>' : '<';
            } else {
                return r < pr ? 'v' : '^';
            }
        }
    }
}

