/**
 * Encapsulates the grid propagation logic.
 * All state is local to the solve method to ensure thread-safety and reusability.
 */
class Solver {
    private static final String RESULT_NOT_UNIQUE = "Not unique";
    private static final int[] DX = {1, -1, 0, 0};
    private static final int[] DY = {0, 0, 1, -1};
    private static final String ARROW_CHARS = "<>^v";

    public void solve(FastScanner in, PrintWriter out) {
        int height = in.nextInt();
        int width = in.nextInt();
        char[][] grid = new char[height][];
        for (int i = 0; i < height; i++) {
            grid[i] = in.next().toCharArray();
        }

        boolean[][] visited = new boolean[height][width];
        Queue<int[]> queue = new ArrayDeque<>();

        // Phase 1: Identify cells with exactly one empty neighbor
        for (int r = 0; r < height; r++) {
            for (int c = 0; c < width; c++) {
                int blockedNeighbors = countBlockedNeighbors(grid, r, c, height, width);
                if (blockedNeighbors == 4) {
                    out.println(RESULT_NOT_UNIQUE);
                    return;
                }
                if (blockedNeighbors == 3) {
                    visited[r][c] = true;
                    queue.add(new int[]{r, c});
                }
            }
        }

        // Phase 2: BFS propagation to fill arrows
        while (!queue.isEmpty()) {
            int[] current = queue.poll();
            int r = current[0];
            int c = current[1];

            if (isArrow(grid[r][c])) {
                continue;
            }

            int[] target = findSingleEmptyNeighbor(grid, r, c, height, width);
            if (target == null) {
                out.println(RESULT_NOT_UNIQUE);
                return;
            }

            int nr = target[0];
            int nc = target[1];
            placeArrows(grid, r, c, nr, nc);

            // Re-evaluate neighbors of the newly placed cell
            for (int d = 0; d < 4; d++) {
                int nnr = nr + DX[d];
                int nnc = nc + DY[d];
                if (isValid(nnr, nnc, height, width)) {
                    int blocked = countBlockedNeighbors(grid, nnr, nnc, height, width);
                    if (blocked == 4) {
                        out.println(RESULT_NOT_UNIQUE);
                        return;
                    }
                    if (blocked == 3 && !visited[nnr][nnc]) {
                        visited[nnr][nnc] = true;
                        queue.add(new int[]{nnr, nnc});
                    }
                }
            }
        }

        // Phase 3: Final validation
        for (int r = 0; r < height; r++) {
            for (int c = 0; c < width; c++) {
                if (grid[r][c] == '.') {
                    out.println(RESULT_NOT_UNIQUE);
                    return;
                }
            }
        }

        // Output result
        for (int r = 0; r < height; r++) {
            out.println(new String(grid[r]));
        }
    }

    /**
     * Counts how many adjacent cells are out of bounds or not empty ('.').
     * Returns 0 if the cell itself is not empty.
     */
    private int countBlockedNeighbors(char[][] grid, int r, int c, int h, int w) {
        if (grid[r][c] != '.') {
            return 0;
        }
        int count = 0;
        for (int d = 0; d < 4; d++) {
            int nr = r + DX[d];
            int nc = c + DY[d];
            if (!isValid(nr, nc, h, w) || grid[nr][nc] != '.') {
                count++;
            }
        }
        return count;
    }

    /**
     * Finds the single empty neighbor. Returns null if 0 or >1 empty neighbors exist.
     * Throws an exception if multiple empty neighbors are found (logical constraint violation).
     */
    private int[] findSingleEmptyNeighbor(char[][] grid, int r, int c, int h, int w) {
        int[] result = null;
        for (int d = 0; d < 4; d++) {
            int nr = r + DX[d];
            int nc = c + DY[d];
            if (isValid(nr, nc, h, w) && grid[nr][nc] == '.') {
                if (result != null) {
                    throw new IllegalStateException(
                        "Constraint violation: Multiple empty neighbors at (" + r + "," + c + ")"
                    );
                }
                result = new int[]{nr, nc};
            }
        }
        return result;
    }

    /**
     * Places directional arrows between two orthogonally adjacent cells.
     */
    private void placeArrows(char[][] grid, int r1, int c1, int r2, int c2) {
        if (r1 == r2) {
            grid[r1][Math.min(c1, c2)] = '<';
            grid[r1][Math.max(c1, c2)] = '>';
        } else if (c1 == c2) {
            grid[Math.min(r1, r2)][c1] = '^';
            grid[Math.max(r1, r2)][c1] = 'v';
        } else {
            throw new IllegalStateException(
                "Constraint violation: Diagonal placement not allowed (" + r1 + "," + c1 + ") -> (" + r2 + "," + c2 + ")"
            );
        }
    }

    private boolean isArrow(char c) {
        return ARROW_CHARS.indexOf(c) != -1;
    }

    private boolean isValid(int r, int c, int h, int w) {
        return r >= 0 && r < h && c >= 0 && c < w;
    }
}

/**
 * Fast input reader for competitive programming / high-throughput scenarios.
 */
class FastScanner {
    private final BufferedReader reader;
    private StringTokenizer tokenizer;

    public FastScanner(InputStream in) {
        reader = new BufferedReader(new InputStreamReader(in));
    }

    public String next() {
        while (tokenizer == null || !tokenizer.hasMoreTokens()) {
            try {
                String line = reader.readLine();
                if (line == null) {
                    throw new EOFException("Unexpected end of input");
                }
                tokenizer = new StringTokenizer(line);
            } catch (IOException e) {
                throw new RuntimeException("Failed to read input", e);
            }
        }
        return tokenizer.nextToken();
    }

    public int nextInt() {
        return Integer.parseInt(next());
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.ArrayDeque;
import java.util.Queue;
import java.util.StringTokenizer;

public class Main {
    // Direction deltas: Up, Right, Down, Left
    private static final int[] DX = {0, 1, 0, -1};
    private static final int[] DY = {-1, 0, 1, 0};

    // Mapping for each direction: [current_cell_arrow, neighbor_cell_arrow]
    private static final char[][] DIRECTION_MAP = {
        {'v', '^'}, // Up
        {'<', '>'}, // Right
        {'^', 'v'}, // Down
        {'>', '<'}  // Left
    };

    private static final char EMPTY_CELL = '.';
    private static final int DIRECTION_COUNT = 4;

    private int rows;
    private int cols;
    private char[][] grid;

    /**
     * Checks if coordinates are within grid bounds.
     */
    private boolean isLegal(int x, int y) {
        return x >= 0 && x < cols && y >= 0 && y < rows;
    }

    /**
     * Solves the grid using a topological sort-like approach.
     * Cells with exactly one adjacent empty neighbor are "leaves" that can be resolved.
     * Resolving a leaf assigns arrows between it and its empty neighbor, reducing the
     * neighbor's degree until all cells are filled or a cycle/ambiguity is detected.
     */
    private boolean solve() {
        int[][] degree = new int[rows][cols];
        Queue<Point> queue = new ArrayDeque<>();

        // Initialize degrees and find initial leaf nodes
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] != EMPTY_CELL) continue;

                int emptyNeighbors = 0;
                for (int d = 0; d < DIRECTION_COUNT; d++) {
                    if (isLegal(c + DX[d], r + DY[d]) && grid[r + DY[d]][c + DX[d]] == EMPTY_CELL) {
                        emptyNeighbors++;
                    }
                }
                degree[r][c] = emptyNeighbors;
                if (emptyNeighbors == 1) {
                    queue.add(new Point(c, r));
                }
            }
        }

        // Process queue until no more leaves can be resolved
        while (!queue.isEmpty()) {
            Point current = queue.poll();
            degree[current.y][current.x] = 0; // Mark as resolved

            Point neighbor = null;
            int direction = -1;

            // Find the single unresolved empty neighbor
            for (int d = 0; d < DIRECTION_COUNT; d++) {
                int nx = current.x + DX[d];
                int ny = current.y + DY[d];
                if (isLegal(nx, ny) && grid[ny][nx] == EMPTY_CELL) {
                    neighbor = new Point(nx, ny);
                    direction = d;
                    break;
                }
            }

            if (neighbor == null) continue;

            // Assign arrows between current and neighbor
            grid[current.y][current.x] = DIRECTION_MAP[direction][0];
            grid[neighbor.y][neighbor.x] = DIRECTION_MAP[direction][1];

            // Update degrees of the neighbor's neighbors
            for (int d = 0; d < DIRECTION_COUNT; d++) {
                int nnx = neighbor.x + DX[d];
                int nny = neighbor.y + DY[d];
                if (isLegal(nnx, nny)) {
                    degree[nny][nnx]--;
                    if (degree[nny][nnx] == 1) {
                        queue.add(new Point(nnx, nny));
                    }
                }
            }
        }

        // Verify all cells are resolved
        for (char[] row : grid) {
            for (char cell : row) {
                if (cell == EMPTY_CELL) return false;
            }
        }
        return true;
    }

    /**
     * Handles input/output and orchestrates the solution.
     */
    private void run() {
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
             PrintWriter out = new PrintWriter(System.out)) {

            FastScanner scanner = new FastScanner(br);

            String rowStr = scanner.next();
            if (rowStr == null) return;
            rows = Integer.parseInt(rowStr);
            cols = Integer.parseInt(scanner.next());

            grid = new char[rows][];
            for (int i = 0; i < rows; i++) {
                grid[i] = scanner.next().toCharArray();
            }

            if (!solve()) {
                out.println("Not unique");
            } else {
                for (char[] row : grid) {
                    out.println(row);
                }
            }
            out.flush();
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    public static void main(String[] args) {
        new Main().run();
    }

    /**
     * Immutable point representation for grid coordinates.
     */
    private static class Point {
        final int x, y;
        Point(int x, int y) {
            this.x = x;
            this.y = y;
        }
    }

    /**
     * Lightweight, maintainable scanner using BufferedReader and StringTokenizer.
     */
    private static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner(BufferedReader br) {
            this.br = br;
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }
    }
}

import java.io.*;
import java.util.*;

public class Main {

    // Direction deltas: Down, Left, Up, Right
    private static final int[] DX = {1, 0, -1, 0};
    private static final int[] DY = {0, -1, 0, 1};
    private static final char[] ARROWS = {'>', '^', '<', 'v'};
    private static final char EMPTY = '.';

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out);
        try {
            String result = solve(scanner);
            out.println(result);
        } finally {
            out.flush();
            out.close();
        }
    }

    private static String solve(FastScanner scanner) {
        int n = scanner.nextInt();
        int m = scanner.nextInt();
        Grid grid = new Grid(n, m);

        for (int i = 0; i < n; i++) {
            grid.cells[i] = scanner.next().toCharArray();
        }

        Queue<Point> queue = new LinkedList<>();

        // Initial scan: identify empty cells with exactly one empty neighbor
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid.cells[i][j] == EMPTY) {
                    int count = grid.countAdjacentEmpty(i, j);
                    if (count == 0) {
                        return "Not unique";
                    }
                    if (count == 1) {
                        queue.add(new Point(i, j));
                    }
                }
            }
        }

        // BFS propagation
        while (!queue.isEmpty()) {
            Point p = queue.poll();
            if (grid.cells[p.x][p.y] != EMPTY) {
                continue;
            }

            boolean placed = false;
            for (int i = 0; i < 4; i++) {
                int nx = p.x + DX[i];
                int ny = p.y + DY[i];
                if (grid.isValid(nx, ny) && grid.cells[nx][ny] == EMPTY) {
                    // Place opposite arrow at current cell, arrow at neighbor
                    grid.placeArrow(p.x, p.y, ARROWS[i ^ 2], queue);
                    grid.placeArrow(nx, ny, ARROWS[i], queue);
                    placed = true;
                }
            }
            if (!placed) {
                return "Not unique";
            }
        }

        // Verify no empty cells remain
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid.cells[i][j] == EMPTY) {
                    return "Not unique";
                }
            }
        }

        // Format output
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < n; i++) {
            sb.append(grid.cells[i]).append('\n');
        }
        return sb.toString().trim();
    }

    /** Encapsulates grid state and board manipulation logic */
    private static class Grid {
        final int n, m;
        char[][] cells;

        Grid(int n, int m) {
            this.n = n;
            this.m = m;
            this.cells = new char[n][m];
        }

        boolean isValid(int x, int y) {
            return x >= 0 && x < n && y >= 0 && y < m;
        }

        int countAdjacentEmpty(int x, int y) {
            int count = 0;
            for (int i = 0; i < 4; i++) {
                int nx = x + DX[i];
                int ny = y + DY[i];
                if (isValid(nx, ny) && cells[nx][ny] == EMPTY) {
                    count++;
                }
            }
            return count;
        }

        void placeArrow(int x, int y, char arrow, Queue<Point> queue) {
            if (cells[x][y] != EMPTY) {
                return;
            }
            cells[x][y] = arrow;
            for (int i = 0; i < 4; i++) {
                int nx = x + DX[i];
                int ny = y + DY[i];
                if (isValid(nx, ny) && cells[nx][ny] == EMPTY) {
                    if (countAdjacentEmpty(nx, ny) == 1) {
                        queue.add(new Point(nx, ny));
                    }
                }
            }
        }
    }

    /** Immutable coordinate holder */
    private static class Point {
        final int x, y;

        Point(int x, int y) {
            this.x = x;
            this.y = y;
        }
    }

    /** High-performance input reader */
    private static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner(InputStream is) {
            br = new BufferedReader(new InputStreamReader(is));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) {
                        throw new IOException("Unexpected end of input");
                    }
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.ArrayDeque;
import java.util.Arrays;
import java.util.Queue;
import java.util.StringTokenizer;

public class Main {
    // Direction vectors: Up, Down, Left, Right
    private static final int[] DR = {-1, 1, 0, 0};
    private static final int[] DC = {0, 0, -1, 1};
    // Arrow characters corresponding to DR/DC indices
    private static final char[] DIR_CHARS = {'v', '^', '>', '<'};
    // Opposite arrows for pairing connections
    private static final char[] OPPOSITE_ARROWS = {'^', 'v', '<', '>'};

    private static final char BLOCK_CHAR = '*';
    private static final char DEFAULT_CHAR = '*';

    public static void main(String[] args) {
        FastScanner in = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out);
        new Main().solve(in, out);
        out.flush();
    }

    /**
     * Core logic for processing the grid and determining arrow placements.
     */
    void solve(FastScanner in, PrintWriter out) {
        int n = in.nextInt();
        int m = in.nextInt();

        // Grid storing the number of valid (non-blocked) neighbors for each cell
        int[][] neighborCounts = new int[n][m];
        for (int[] row : neighborCounts) {
            Arrays.fill(row, 4);
        }

        // Tracks whether a cell has been successfully assigned a direction
        boolean[][] isCovered = new boolean[n][m];
        // Stores the final arrow directions for each cell
        char[][] directionGrid = new char[n][m];
        for (char[] row : directionGrid) {
            Arrays.fill(row, DEFAULT_CHAR);
        }

        // Read input grid and initialize blocked cells
        for (int i = 0; i < n; i++) {
            String line = in.next();
            for (int j = 0; j < m; j++) {
                if (line.charAt(j) == BLOCK_CHAR) {
                    neighborCounts[i][j] = 0;
                    isCovered[i][j] = true;
                }
            }
        }

        // Queue for cells that currently have exactly one valid neighbor
        Queue<int[]> queue = new ArrayDeque<>();

        // Initialize neighbor counts and populate the queue with seed cells
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (neighborCounts[i][j] > 0) {
                    int count = 0;
                    for (int d = 0; d < 4; d++) {
                        int ni = i + DR[d];
                        int nj = j + DC[d];
                        if (isValid(ni, nj, n, m) && neighborCounts[ni][nj] > 0) {
                            count++;
                        }
                    }
                    neighborCounts[i][j] = count;
                    if (count == 1) {
                        queue.offer(new int[]{i, j});
                    }
                }
            }
        }

        // Process cells with exactly one neighbor until the queue is empty
        while (!queue.isEmpty()) {
            int[] cell = queue.poll();
            int r = cell[0];
            int c = cell[1];

            // Skip if the condition changed while the cell was waiting in the queue
            if (neighborCounts[r][c] != 1) continue;

            for (int d = 0; d < 4; d++) {
                int nr = r + DR[d];
                int nc = c + DC[d];

                if (isValid(nr, nc, n, m) && neighborCounts[nr][nc] > 0) {
                    // Assign opposite arrows to the connected pair
                    directionGrid[r][c] = DIR_CHARS[d];
                    directionGrid[nr][nc] = OPPOSITE_ARROWS[d];
                    isCovered[r][c] = true;
                    isCovered[nr][nc] = true;

                    // Decrement neighbor counts for the target cell's neighbors
                    for (int nd = 0; nd < 4; nd++) {
                        int nnr = nr + DR[nd];
                        int nnc = nc + DC[nd];
                        if (isValid(nnr, nnc, n, m) && neighborCounts[nnr][nnc] > 0) {
                            neighborCounts[nnr][nnc]--;
                            if (neighborCounts[nnr][nnc] == 1) {
                                queue.offer(new int[]{nnr, nnc});
                            }
                        }
                    }

                    // Mark target cell as processed to prevent re-evaluation
                    neighborCounts[nr][nc] = 0;
                    break;
                }
            }
        }

        // Verify if all cells have been covered
        boolean allCovered = true;
        outerLoop:
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (!isCovered[i][j]) {
                    allCovered = false;
                    break outerLoop;
                }
            }
        }

        if (!allCovered) {
            out.println("Not unique");
        } else {
            for (int i = 0; i < n; i++) {
                out.println(new String(directionGrid[i]));
            }
        }
    }

    /**
     * Checks if the given coordinates are within grid bounds.
     */
    private boolean isValid(int r, int c, int n, int m) {
        return r >= 0 && r < n && c >= 0 && c < m;
    }

    /**
     * Lightweight fast I/O helper to replace Scanner for better performance.
     */
    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner(java.io.InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.ArrayDeque;
import java.util.Queue;
import java.util.StringTokenizer;

/**
 * Solves a grid puzzle by replacing '.' characters with directional arrows
 * to form a unique path configuration. Uses a queue-based peeling algorithm
 * that processes cells starting from those with exactly one neighbor.
 */
public class ArrowGridSolver {

    // Direction vectors: Down, Up, Right, Left
    private static final int[] DR = {1, -1, 0, 0};
    private static final int[] DC = {0, 0, 1, -1};

    // Arrow pairs: [start, end] corresponding to each direction vector
    private static final char[][] ARROW_PAIRS = {
        {'^', 'v'}, // Down
        {'v', '^'}, // Up
        {'<', '>'}, // Right
        {'>', '<'}  // Left
    };

    private char[][] grid;
    private int[] degree;
    private int rows;
    private int cols;

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter out = new PrintWriter(System.out);

        try {
            // Read dimensions, skipping any leading empty lines
            String line = br.readLine();
            while (line != null && line.trim().isEmpty()) {
                line = br.readLine();
            }
            if (line == null) {
                out.flush();
                return;
            }

            StringTokenizer st = new StringTokenizer(line);
            int n = Integer.parseInt(st.nextToken());
            int m = Integer.parseInt(st.nextToken());

            ArrowGridSolver solver = new ArrowGridSolver(n, m);
            solver.readGrid(br);
            solver.solve(out);
        } catch (Exception e) {
            out.println("Error: " + e.getMessage());
        } finally {
            out.flush();
        }
    }

    private ArrowGridSolver(int rows, int cols) {
        this.rows = rows;
        this.cols = cols;
        this.grid = new char[rows][];
        this.degree = new int[rows * cols];
    }

    private void readGrid(BufferedReader br) throws IOException {
        for (int i = 0; i < rows; i++) {
            String line = br.readLine();
            while (line != null && line.trim().isEmpty()) {
                line = br.readLine();
            }
            if (line == null) break;
            grid[i] = line.trim().toCharArray();
        }
    }

    private void solve(PrintWriter out) {
        Queue<Integer> queue = new ArrayDeque<>();

        // Initialize degrees and enqueue boundary cells (degree == 1)
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '.') {
                    int idx = r * cols + c;
                    degree[idx] = countNeighbors(r, c);
                    if (degree[idx] == 1) {
                        queue.add(idx);
                    }
                }
            }
        }

        // Process queue using topological peeling logic
        while (!queue.isEmpty()) {
            int currentIdx = queue.poll();
            int r = currentIdx / cols;
            int c = currentIdx % cols;

            if (grid[r][c] != '.') {
                continue;
            }

            int neighborIdx = placeArrows(r, c);
            if (neighborIdx == -1) {
                continue; // Should not occur if degree is 1
            }

            int nr = neighborIdx / cols;
            int nc = neighborIdx % cols;

            // Check neighbors of the newly placed arrow
            for (int k = 0; k < 4; k++) {
                int nextR = nr + DR[k];
                int nextC = nc + DC[k];
                int nextIdx = nextR * cols + nextC;

                if (isValid(nextR, nextC) && grid[nextR][nextC] == '.') {
                    degree[nextIdx]--;
                    if (degree[nextIdx] == 1) {
                        queue.add(nextIdx);
                    }
                }
            }
        }

        // Check for unprocessed dots
        if (hasRemainingDots()) {
            out.println("Not unique");
        } else {
            for (char[] row : grid) {
                out.println(row);
            }
        }
    }

    private int countNeighbors(int r, int c) {
        int count = 0;
        for (int k = 0; k < 4; k++) {
            int nr = r + DR[k];
            int nc = c + DC[k];
            if (isValid(nr, nc) && grid[nr][nc] == '.') {
                count++;
            }
        }
        return count;
    }

    private int placeArrows(int r, int c) {
        for (int k = 0; k < 4; k++) {
            int nr = r + DR[k];
            int nc = c + DC[k];
            if (isValid(nr, nc) && grid[nr][nc] == '.') {
                grid[r][c] = ARROW_PAIRS[k][0];
                grid[nr][nc] = ARROW_PAIRS[k][1];
                return nr * cols + nc;
            }
        }
        return -1; // No valid neighbor found
    }

    private boolean isValid(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    private boolean hasRemainingDots() {
        for (char[] row : grid) {
            for (char cell : row) {
                if (cell == '.') {
                    return true;
                }
            }
        }
        return false;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayDeque;
import java.util.Queue;
import java.util.StringTokenizer;

public class Main {
    // Direction vectors: Right, Down, Left, Up
    private static final int[][] DIRS = {{0, 1}, {1, 0}, {0, -1}, {-1, 0}};
    private static final char[] ARROWS = {'>', 'v', '<', '^'};

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line = br.readLine();
        if (line == null) return;

        StringTokenizer st = new StringTokenizer(line);
        int rows = Integer.parseInt(st.nextToken());
        int cols = Integer.parseInt(st.nextToken());

        char[][] grid = new char[rows][cols];
        int[][] adjCount = new int[rows][cols];
        boolean[][] processed = new boolean[rows][cols];

        // Read grid input
        for (int i = 0; i < rows; i++) {
            String rowLine = br.readLine();
            grid[i] = rowLine.toCharArray();
        }

        // Calculate initial adjacency counts for all empty cells
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == '.') {
                    adjCount[i][j] = countAdjacent(grid, i, j, rows, cols);
                }
            }
        }

        // Initialize queue with cells that have exactly one unprocessed neighbor
        Queue<int[]> queue = new ArrayDeque<>();
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == '.' && adjCount[i][j] == 1) {
                    queue.offer(new int[]{i, j});
                }
            }
        }

        // Process cells iteratively using a BFS-like approach
        while (!queue.isEmpty()) {
            int[] current = queue.poll();
            int r = current[0];
            int c = current[1];

            // Skip if already processed or no longer an empty cell
            if (processed[r][c] || grid[r][c] != '.') continue;

            // Find the single unprocessed '.' neighbor
            int[] neighbor = null;
            int neighborDir = -1;
            for (int d = 0; d < 4; d++) {
                int nr = r + DIRS[d][0];
                int nc = c + DIRS[d][1];
                if (isInBounds(nr, nc, rows, cols) && grid[nr][nc] == '.' && !processed[nr][nc]) {
                    neighbor = new int[]{nr, nc};
                    neighborDir = d;
                    break;
                }
            }

            if (neighbor == null) continue;

            int nr = neighbor[0];
            int nc = neighbor[1];

            // Place arrows pointing towards each other
            grid[r][c] = ARROWS[neighborDir];
            grid[nr][nc] = ARROWS[(neighborDir + 2) % 4];

            // Mark both cells as processed
            processed[r][c] = true;
            processed[nr][nc] = true;

            // Update adjacency counts for the neighbor's other unprocessed '.' neighbors
            for (int d = 0; d < 4; d++) {
                int nnr = nr + DIRS[d][0];
                int nnc = nc + DIRS[d][1];
                if (isInBounds(nnr, nnc, rows, cols) && grid[nnr][nnc] == '.' && !processed[nnr][nnc]) {
                    adjCount[nnr][nnc]--;
                    if (adjCount[nnr][nnc] == 1) {
                        queue.offer(new int[]{nnr, nnc});
                    }
                }
            }
        }

        // Check if any empty cells remain
        boolean hasRemaining = false;
        outer:
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == '.') {
                    hasRemaining = true;
                    break outer;
                }
            }
        }

        if (hasRemaining) {
            System.out.println("Not unique");
        } else {
            for (int i = 0; i < rows; i++) {
                System.out.println(new String(grid[i]));
            }
        }
    }

    /**
     * Counts the number of adjacent empty cells ('.') for a given position.
     */
    private static int countAdjacent(char[][] grid, int r, int c, int rows, int cols) {
        int count = 0;
        for (int[] dir : DIRS) {
            int nr = r + dir[0];
            int nc = c + dir[1];
            if (isInBounds(nr, nc, rows, cols) && grid[nr][nc] == '.') {
                count++;
            }
        }
        return count;
    }

    /**
     * Checks if coordinates are within grid boundaries.
     */
    private static boolean isInBounds(int r, int c, int rows, int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }
}

import java.io.*;
import java.util.*;

/**
 * Entry point for the grid path solver.
 * Uses try-with-resources for automatic I/O cleanup.
 */
public class Main {
    public static void main(String[] args) {
        try (FastScanner in = new FastScanner(System.in);
             FastPrinter out = new FastPrinter(System.out)) {
            new GridPathSolver().solve(in, out);
        }
    }
}

/**
 * Core solver implementing a topological sort (Kahn's algorithm) on a grid graph.
 * Processes cells with exactly one unvisited neighbor until the graph is exhausted.
 */
class GridPathSolver {
    // Direction offsets: DOWN, LEFT, UP, RIGHT
    private static final int[] DX = {1, 0, -1, 0};
    private static final int[] DY = {0, -1, 0, 1};

    // Arrow mappings for the source cell (current) and destination cell (neighbor)
    // Index corresponds to DX/DY direction index
    private static final char[] FROM_ARROWS = {'^', '>', 'v', '<'};
    private static final char[] TO_ARROWS = {'v', '<', '^', '>'};

    public void solve(FastScanner in, FastPrinter out) {
        int rows = in.nextInt();
        int cols = in.nextInt();
        char[][] grid = readGrid(in, rows, cols);
        int[][] degrees = calculateDegrees(grid, rows, cols);

        // Initialize queue with leaf nodes (degree == 1)
        Queue<Cell> queue = new ArrayDeque<>();
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '.' && degrees[r][c] == 1) {
                    queue.add(new Cell(r, c));
                }
            }
        }

        // Process the graph topologically
        while (!queue.isEmpty()) {
            Cell current = queue.poll();
            int r = current.row;
            int c = current.col;

            // Find the single adjacent unprocessed '.' cell
            int neighborR = -1, neighborC = -1;
            int dirIdx = -1;
            for (int i = 0; i < 4; i++) {
                int nr = r + DX[i];
                int nc = c + DY[i];
                if (isValid(nr, nc, rows, cols) && grid[nr][nc] == '.') {
                    neighborR = nr;
                    neighborC = nc;
                    dirIdx = i;
                    break;
                }
            }

            if (neighborR == -1) continue;

            // Update directional arrows based on movement direction
            grid[r][c] = FROM_ARROWS[dirIdx];
            grid[neighborR][neighborC] = TO_ARROWS[dirIdx];

            // Decrease degree of neighbors of the destination cell
            for (int i = 0; i < 4; i++) {
                int nnr = neighborR + DX[i];
                int nnc = neighborC + DY[i];
                if (isValid(nnr, nnc, rows, cols) && grid[nnr][nnc] == '.') {
                    degrees[nnr][nnc]--;
                    if (degrees[nnr][nnc] == 1) {
                        queue.add(new Cell(nnr, nnc));
                    }
                }
            }
        }

        // Validate: if any '.' remains, the solution is not unique or disconnected
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '.') {
                    out.println("Not unique");
                    return;
                }
            }
        }

        // Output the resolved grid
        for (char[] row : grid) {
            out.println(new String(row));
        }
    }

    /** Reads the character grid from input, skipping whitespace. */
    private char[][] readGrid(FastScanner in, int rows, int cols) {
        char[][] grid = new char[rows][];
        for (int i = 0; i < rows; i++) {
            grid[i] = new char[cols];
            for (int j = 0; j < cols; j++) {
                grid[i][j] = in.nextChar();
            }
        }
        return grid;
    }

    /** Calculates the number of adjacent '.' cells for each cell. */
    private int[][] calculateDegrees(char[][] grid, int rows, int cols) {
        int[][] degrees = new int[rows][cols];
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '.') {
                    for (int i = 0; i < 4; i++) {
                        int nr = r + DX[i];
                        int nc = c + DY[i];
                        if (isValid(nr, nc, rows, cols) && grid[nr][nc] == '.') {
                            degrees[r][c]++;
                        }
                    }
                }
            }
        }
        return degrees;
    }

    /** Checks if coordinates are within grid bounds. */
    private boolean isValid(int r, int c, int rows, int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }
}

/** Lightweight immutable coordinate container. */
class Cell {
    final int row, col;
    Cell(int row, int col) {
        this.row = row;
        this.col = col;
    }
}

/** High-performance input reader optimized for competitive programming. */
class FastScanner {
    private final InputStream in;
    private final byte[] buffer = new byte[1024];
    private int ptr = 0;
    private int buflen = 0;

    public FastScanner(InputStream in) {
        this.in = in;
    }

    private int readByte() {
        if (ptr >= buflen) {
            ptr = 0;
            try {
                buflen = in.read(buffer);
            } catch (IOException e) {
                throw new RuntimeException("Failed to read input", e);
            }
            if (buflen <= 0) return -1;
        }
        return buffer[ptr++];
    }

    public int nextInt() {
        int c = readByte();
        while (isSpaceChar(c)) c = readByte();

        int sgn = 1;
        if (c == '-') {
            sgn = -1;
            c = readByte();
        }

        int res = 0;
        do {
            if (c < '0' || c > '9') throw new InputMismatchException("Invalid integer");
            res = res * 10 + (c - '0');
            c = readByte();
        } while (!isSpaceChar(c));

        return res * sgn;
    }

    public char nextChar() {
        int c = readByte();
        while (isSpaceChar(c)) c = readByte();
        return (char) c;
    }

    private boolean isSpaceChar(int c) {
        return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
    }
}

/** High-performance output writer with buffering. */
class FastPrinter {
    private final PrintWriter out;

    public FastPrinter(OutputStream outputStream) {
        this.out = new PrintWriter(new BufferedOutputStream(outputStream));
    }

    public void println(String line) {
        out.println(line);
    }

    public void flush() {
        out.flush();
    }

    public void close() {
        out.close();
    }
}

import java.io.*;
import java.util.*;

public class GridDirectionSolver {

    private static final char EMPTY = '.';
    private static final char DIR_DOWN = 'v';
    private static final char DIR_UP = '^';
    private static final char DIR_LEFT = '<';
    private static final char DIR_RIGHT = '>';

    public static void main(String[] args) {
        new GridDirectionSolver().solve();
    }

    /**
     * Entry point for the solver. Orchestrates reading, processing, and output.
     */
    public void solve() {
        FastScanner sc = new FastScanner(System.in);
        if (!sc.hasNext()) return;

        int n = sc.nextInt();
        int m = sc.nextInt();
        char[][] grid = readGrid(sc, n, m);

        processGrid(grid, n, m);
        printGrid(grid);
    }

    /**
     * Reads the grid dimensions and character data from input.
     */
    private char[][] readGrid(FastScanner sc, int n, int m) {
        char[][] grid = new char[n][m];
        for (int i = 0; i < n; i++) {
            String line = sc.next();
            if (line == null || line.length() != m) {
                throw new IllegalArgumentException("Invalid grid input at row " + i);
            }
            grid[i] = line.toCharArray();
        }
        return grid;
    }

    /**
     * Core algorithm: Processes cells with exactly one empty neighbor,
     * assigns directional characters, and propagates changes to the queue.
     */
    private void processGrid(char[][] grid, int n, int m) {
        Queue<Loc> queue = new ArrayDeque<>();

        // Initialize queue with boundary cells having exactly one empty neighbor
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < m; c++) {
                if (grid[r][c] == EMPTY && getEmptyNeighbors(grid, r, c).size() == 1) {
                    queue.add(new Loc(r, c));
                }
            }
        }

        while (!queue.isEmpty()) {
            Loc current = queue.poll();
            int r = current.x();
            int c = current.y();

            // Skip if already processed or modified by a previous iteration
            if (grid[r][c] != EMPTY) {
                continue;
            }

            List<Loc> neighbors = getEmptyNeighbors(grid, r, c);
            // Only proceed if exactly one empty neighbor remains
            if (neighbors.size() != 1) {
                continue;
            }

            Loc neighbor = neighbors.get(0);
            int nr = neighbor.x();
            int nc = neighbor.y();

            // Determine directional characters based on relative position
            char currentDir, neighborDir;
            if (r > nr) {
                currentDir = DIR_DOWN;
                neighborDir = DIR_UP;
            } else if (r < nr) {
                currentDir = DIR_UP;
                neighborDir = DIR_DOWN;
            } else if (c < nc) {
                currentDir = DIR_LEFT;
                neighborDir = DIR_RIGHT;
            } else {
                currentDir = DIR_RIGHT;
                neighborDir = DIR_LEFT;
            }

            grid[r][c] = currentDir;
            grid[nr][nc] = neighborDir;

            // Re-evaluate adjacent empty cells of the updated neighbor
            for (Loc adj : getEmptyNeighbors(grid, nr, nc)) {
                queue.add(adj);
            }
        }
    }

    /**
     * Prints the final grid or "Not unique" if empty cells remain.
     */
    private void printGrid(char[][] grid) {
        boolean allFilled = true;
        outerLoop:
        for (char[] row : grid) {
            for (char cell : row) {
                if (cell == EMPTY) {
                    allFilled = false;
                    break outerLoop;
                }
            }
        }

        if (!allFilled) {
            System.out.println("Not unique");
        } else {
            StringBuilder sb = new StringBuilder();
            for (char[] row : grid) {
                sb.append(row).append('\n');
            }
            System.out.print(sb);
        }
    }

    /**
     * Returns a list of adjacent coordinates that are still marked as EMPTY.
     */
    private List<Loc> getEmptyNeighbors(char[][] grid, int r, int c) {
        List<Loc> neighbors = new ArrayList<>();
        int[] dr = {-1, 1, 0, 0};
        int[] dc = {0, 0, -1, 1};

        for (int i = 0; i < 4; i++) {
            int nr = r + dr[i];
            int nc = c + dc[i];
            if (nr >= 0 && nr < grid.length && nc >= 0 && nc < grid[0].length && grid[nr][nc] == EMPTY) {
                neighbors.add(new Loc(nr, nc));
            }
        }
        return neighbors;
    }

    /**
     * Immutable record representing grid coordinates.
     */
    private static record Loc(int x, int y) {}

    /**
     * Lightweight, robust fast I/O helper to replace java.util.Scanner overhead.
     */
    private static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        public boolean hasNext() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) {
                        return false;
                    }
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return true;
        }

        public String next() {
            if (!hasNext()) {
                throw new NoSuchElementException();
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.*;
import java.util.*;

public class Main {

    // Directions mapped to bitmask positions: 0=left, 1=up, 2=down, 3=right
    private static final int[] DR = {0, -1, 0, 1};
    private static final int[] DC = {-1, 0, 1, 0};

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out));
        try {
            solve(scanner, out);
        } catch (IOException e) {
            System.err.println("I/O error: " + e.getMessage());
        } finally {
            out.flush();
            out.close();
        }
    }

    private static void solve(FastScanner scanner, PrintWriter out) throws IOException {
        int n = scanner.nextInt();
        int m = scanner.nextInt();

        char[][] grid = new char[n][m];
        for (int i = 0; i < n; i++) {
            grid[i] = scanner.next().toCharArray();
        }

        // Deep copy for the result grid to avoid mutating the input
        char[][] resultGrid = new char[n][m];
        for (int i = 0; i < n; i++) {
            System.arraycopy(grid[i], 0, resultGrid[i], 0, m);
        }

        int[][] openNeighborCount = new int[n][m];
        Queue<int[]> queue = new ArrayDeque<>();

        // Initialize degrees: count how many adjacent cells are open ('.')
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < m; c++) {
                if (grid[r][c] == '.') {
                    openNeighborCount[r][c] = countOpenNeighbors(r, c, grid, n, m);
                    if (openNeighborCount[r][c] == 1) {
                        queue.offer(new int[]{r, c});
                    }
                }
            }
        }

        // Process queue: topological peel on the grid graph of '.' cells
        while (!queue.isEmpty()) {
            int[] cur = queue.poll();
            int r = cur[0], c = cur[1];

            // Already processed or isolated
            if (openNeighborCount[r][c] == 0) continue;

            // Determine which neighbor is open using a bitmask
            int mask = 0;
            int targetR = r, targetC = c;
            for (int k = 0; k < 4; k++) {
                int nr = r + DR[k];
                int nc = c + DC[k];
                if (isOpen(nr, nc, n, m, resultGrid)) {
                    mask |= (1 << k);
                    targetR = nr;
                    targetC = nc;
                }
            }

            applyDirection(r, c, targetR, targetC, mask, resultGrid);

            // Update the neighbor's degree and propagate to its neighbors
            openNeighborCount[targetR][targetC]--;
            updateNeighbors(targetR, targetC, openNeighborCount, queue, n, m, resultGrid);
        }

        // Check if any cell remains unprocessed
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < m; c++) {
                if (resultGrid[r][c] == '.') {
                    out.println("Not unique");
                    return;
                }
            }
        }

        // Output the final grid
        for (int r = 0; r < n; r++) {
            out.println(new String(resultGrid[r]));
        }
    }

    private static int countOpenNeighbors(int r, int c, char[][] grid, int n, int m) {
        int count = 0;
        for (int k = 0; k < 4; k++) {
            int nr = r + DR[k];
            int nc = c + DC[k];
            if (isOpen(nr, nc, n, m, grid)) {
                count++;
            }
        }
        return count;
    }

    private static boolean isOpen(int r, int c, int n, int m, char[][] grid) {
        if (r < 0 || c < 0 || r >= n || c >= m) return false;
        return grid[r][c] == '.';
    }

    private static void applyDirection(int r, int c, int targetR, int targetC, int mask, char[][] grid) {
        // Preserves original bitmask-to-arrow mapping logic
        if (mask == 1) {
            grid[r][c] = '>';
            grid[targetR][targetC] = '<';
        } else if (mask == 2) {
            grid[r][c] = 'v';
            grid[targetR][targetC] = '^';
        } else if (mask == 4) {
            grid[r][c] = '<';
            grid[targetR][targetC] = '>';
        } else if (mask == 8) {
            grid[r][c] = '^';
            grid[targetR][targetC] = 'v';
        } else {
            throw new IllegalStateException("Unexpected mask value: " + mask + " at (" + r + ", " + c + ")");
        }
    }

    private static void updateNeighbors(int r, int c, int[][] openNeighborCount, Queue<int[]> queue, int n, int m, char[][] grid) {
        for (int k = 0; k < 4; k++) {
            int nr = r + DR[k];
            int nc = c + DC[k];
            if (nr >= 0 && nc >= 0 && nr < n && nc < m && grid[nr][nc] == '.') {
                openNeighborCount[nr][nc]--;
                if (openNeighborCount[nr][nc] == 1) {
                    queue.offer(new int[]{nr, nc});
                }
            }
        }
    }

    /**
     * Lightweight fast I/O helper to avoid global state and improve robustness.
     */
    private static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        public String next() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) throw new IOException("Unexpected end of input");
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.ArrayDeque;
import java.util.StringTokenizer;

/**
 * Refactored Grid Solver.
 * 
 * This class solves a grid problem involving propagation and path finding.
 * It reads a grid, identifies "leaf" nodes (cells with exactly one empty neighbor),
 * and processes them to determine a unique flow or state.
 * 
 * Refactoring improvements:
 * 1. Extracted magic numbers into named constants.
 * 2. Separated logic into distinct methods (Input, Processing, Output).
 * 3. Improved variable naming for readability.
 * 4. Encapsulated resource management using try-with-resources.
 * 5. Removed redundant code (dead 'flag' variable).
 */
public class GridSolver {

    // Constants for grid states
    private static final int EMPTY = 0;
    private static final int WALL = -1;

    // Constants for directions (mapped to output characters)
    // 1: 'v' (Down), 2: '^' (Up), 3: '>' (Right), 4: '<' (Left)
    private static final int DIR_DOWN = 1;
    private static final int DIR_UP = 2;
    private static final int DIR_RIGHT = 3;
    private static final int DIR_LEFT = 4;

    public static void main(String[] args) throws IOException {
        // Use try-with-resources for automatic resource management
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
             PrintWriter writer = new PrintWriter(System.out)) {

            StringTokenizer tokenizer = new StringTokenizer(reader.readLine());
            if (!tokenizer.hasMoreTokens()) return;

            int rows = Integer.parseInt(tokenizer.nextToken());
            int cols = Integer.parseInt(tokenizer.nextToken());

            int[][] grid = new int[rows][cols];
            for (int i = 0; i < rows; i++) {
                String line = reader.readLine();
                if (line == null) break;
                for (int j = 0; j < cols; j++) {
                    grid[i][j] = (line.charAt(j) == '.') ? EMPTY : WALL;
                }
            }

            ArrayDeque<int[]> queue = new ArrayDeque<>();

            // Initial scan: Find cells with exactly 1 empty neighbor (leaves)
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j] == EMPTY) {
                        if (countEmptyNeighbors(grid, i, j, rows, cols) == 1) {
                            queue.add(new int[]{i, j});
                        }
                    }
                }
            }

            // Process the queue
            while (!queue.isEmpty()) {
                int[] current = queue.pollLast();
                int r = current[0];
                int c = current[1];

                // Apply neighbor logic (sets flow directions)
                applyNeighborLogic(grid, r, c, rows, cols);

                // Propagate checks to neighbors (5x5 area)
                propagateChecks(grid, r, c, queue, rows, cols);
            }

            // Validation: Check if any empty cells remain
            boolean isUnique = true;
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j] == EMPTY) {
                        isUnique = false;
                        break;
                    }
                }
                if (!isUnique) break;
            }

            if (!isUnique) {
                writer.println("Not unique");
            } else {
                printGrid(grid, writer);
            }

            writer.flush();
        }
    }

    /**
     * Counts the number of adjacent empty cells (up, down, left, right).
     */
    private static int countEmptyNeighbors(int[][] grid, int r, int c, int rows, int cols) {
        int count = 0;
        if (r > 0 && grid[r - 1][c] == EMPTY) count++;
        if (c > 0 && grid[r][c - 1] == EMPTY) count++;
        if (r < rows - 1 && grid[r + 1][c] == EMPTY) count++;
        if (c < cols - 1 && grid[r][c + 1] == EMPTY) count++;
        return count;
    }

    /**
     * Applies the logic to update grid values based on empty neighbors.
     * Order matters as it overwrites grid[r][c] multiple times.
     */
    private static void applyNeighborLogic(int[][] grid, int r, int c, int rows, int cols) {
        // Check Up
        if (r > 0 && grid[r - 1][c] == EMPTY) {
            grid[r - 1][c] = DIR_UP;
            grid[r][c] = DIR_DOWN;
        }
        // Check Left
        if (c > 0 && grid[r][c - 1] == EMPTY) {
            grid[r][c - 1] = DIR_LEFT;
            grid[r][c] = DIR_RIGHT;
        }
        // Check Down
        if (r < rows - 1 && grid[r + 1][c] == EMPTY) {
            grid[r + 1][c] = DIR_DOWN;
            grid[r][c] = DIR_UP;
        }
        // Check Right
        if (c < cols - 1 && grid[r][c + 1] == EMPTY) {
            grid[r][c + 1] = DIR_RIGHT;
            grid[r][c] = DIR_LEFT;
        }
    }

    /**
     * Checks a 5x5 area around the current cell and enqueues valid leaves.
     */
    private static void propagateChecks(int[][] grid, int r, int c, ArrayDeque<int[]> queue, int rows, int cols) {
        for (int rowOffset = -2; rowOffset <= 2; rowOffset++) {
            for (int colOffset = -2; colOffset <= 2; colOffset++) {
                checkAndEnqueue(grid, r + rowOffset, c + colOffset, queue, rows, cols);
            }
        }
    }

    /**
     * Checks if a cell is a valid leaf (empty with exactly 1 empty neighbor) and adds to queue.
     */
    private static void checkAndEnqueue(int[][] grid, int r, int c, ArrayDeque<int[]> queue, int rows, int cols) {
        if (r < 0 || c < 0 || r >= rows || c >= cols) {
            return;
        }
        if (grid[r][c] == EMPTY) {
            if (countEmptyNeighbors(grid, r, c, rows, cols) == 1) {
                queue.add(new int[]{r, c});
            }
        }
    }

    /**
     * Prints the grid using the mapped characters.
     */
    private static void printGrid(int[][] grid, PrintWriter writer) {
        for (int i = 0; i < grid.length; i++) {
            for (int j = 0; j < grid[i].length; j++) {
                writer.print(getCharForValue(grid[i][j]));
            }
            writer.println();
        }
    }

    private static char getCharForValue(int val) {
        switch (val) {
            case -1: return '*';
            case 1: return 'v';
            case 2: return '^';
            case 3: return '>';
            case 4: return '<';
            default: return '?'; // Should not occur for valid output
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayDeque;
import java.util.Queue;
import java.util.StringTokenizer;

public class DrazilAndTiles {
    // Directions: 0=UP, 1=RIGHT, 2=DOWN, 3=LEFT
    private static final int[] DR = {-1, 0, 1, 0};
    private static final int[] DC = {0, 1, 0, -1};

    public static void main(String[] args) {
        FastReader scanner = new FastReader();
        int n = scanner.nextInt();
        int m = scanner.nextInt();
        char[][] board = readBoard(scanner, n, m);

        if (solve(board, n, m)) {
            printBoard(board);
        } else {
            System.out.println("Not unique");
        }
    }

    /**
     * Reads the board dimensions and grid from the input scanner.
     */
    private static char[][] readBoard(FastReader scanner, int n, int m) {
        char[][] board = new char[n][];
        for (int i = 0; i < n; i++) {
            board[i] = scanner.next().toCharArray();
        }
        return board;
    }

    /**
     * Processes the board by expanding tiles and checks if a unique solution exists.
     */
    private static boolean solve(char[][] board, int n, int m) {
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < m; c++) {
                if (board[r][c] == '.') {
                    expand(board, n, m, r, c);
                }
            }
        }
        return !hasEmptyTiles(board, n, m);
    }

    /**
     * Propagates tile placements using BFS starting from a given empty cell.
     */
    private static void expand(char[][] board, int n, int m, int startR, int startC) {
        int startDir = getDirection(board, n, m, startR, startC);
        if (startDir < 0) {
            return;
        }

        // Queue stores {row, col, direction}
        Queue<int[]> queue = new ArrayDeque<>();
        queue.offer(new int[]{startR, startC, startDir});
        updateBoard(board, n, m, startR, startC, startDir);

        while (!queue.isEmpty()) {
            int[] current = queue.poll();
            int r = current[0];
            int c = current[1];
            int d = current[2];

            // Move one step in the determined direction to find the adjacent cell
            int nextR = r + DR[d];
            int nextC = c + DC[d];

            // Check all 4 neighbors of the adjacent cell for new placements
            for (int i = 0; i < 4; i++) {
                int neighborR = nextR + DR[i];
                int neighborC = nextC + DC[i];
                int neighborDir = getDirection(board, n, m, neighborR, neighborC);
                if (neighborDir >= 0) {
                    updateBoard(board, n, m, neighborR, neighborC, neighborDir);
                    queue.offer(new int[]{neighborR, neighborC, neighborDir});
                }
            }
        }
    }

    /**
     * Updates the board with directional arrows based on the determined direction.
     */
    private static void updateBoard(char[][] board, int n, int m, int r, int c, int d) {
        switch (d) {
            case 0: // UP
                board[r - 1][c] = '^';
                board[r][c] = 'v';
                break;
            case 1: // RIGHT
                board[r][c] = '<';
                board[r][c + 1] = '>';
                break;
            case 2: // DOWN
                board[r][c] = '^';
                board[r + 1][c] = 'v';
                break;
            case 3: // LEFT
                board[r][c - 1] = '<';
                board[r][c] = '>';
                break;
        }
    }

    /**
     * Determines the unique direction to an adjacent empty cell.
     * Returns -1 if the cell is out of bounds, not empty, or has multiple adjacent empty cells.
     */
    private static int getDirection(char[][] board, int n, int m, int r, int c) {
        if (!isValid(n, m, r, c) || board[r][c] != '.') {
            return -1;
        }

        int direction = -1;
        boolean found = false;
        for (int i = 0; i < 4; i++) {
            int nr = r + DR[i];
            int nc = c + DC[i];
            if (isValid(n, m, nr, nc) && board[nr][nc] == '.') {
                if (found) {
                    return -1; // Ambiguous: more than one adjacent empty cell
                }
                direction = i;
                found = true;
            }
        }
        return direction;
    }

    /**
     * Checks if row and column indices are within board boundaries.
     */
    private static boolean isValid(int n, int m, int r, int c) {
        return r >= 0 && r < n && c >= 0 && c < m;
    }

    /**
     * Checks if any empty tiles remain on the board.
     */
    private static boolean hasEmptyTiles(char[][] board, int n, int m) {
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < m; c++) {
                if (board[r][c] == '.') {
                    return true;
                }
            }
        }
        return false;
    }

    /**
     * Prints the final board state to standard output.
     */
    private static void printBoard(char[][] board) {
        for (char[] row : board) {
            System.out.println(new String(row));
        }
    }

    /**
     * Fast I/O helper class using BufferedReader and StringTokenizer.
     */
    private static class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        public String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            String s = next();
            return s == null ? 0 : Integer.parseInt(s);
        }
    }
}

import java.util.ArrayDeque;
import java.util.Queue;
import java.util.Scanner;

/**
 * Solves a grid direction puzzle by propagating directional markers
 * from cells with exactly one empty neighbor.
 */
public class GridDirectionSolver {

    private static final int[] DR = {0, 0, -1, 1};
    private static final int[] DC = {-1, 1, 0, 0};

    private final int rows;
    private final int cols;
    private char[][] grid;
    private boolean[][] visited;
    private final Queue<Cell> queue;

    /** Represents a coordinate in the grid. */
    private static class Cell {
        final int r;
        final int c;

        Cell(int r, int c) {
            this.r = r;
            this.c = c;
        }
    }

    public GridDirectionSolver(int rows, int cols) {
        this.rows = rows;
        this.cols = cols;
        this.grid = new char[rows][cols];
        this.visited = new boolean[rows][cols];
        this.queue = new ArrayDeque<>();
    }

    /** Reads the grid configuration from standard input. */
    public void readInput(Scanner scanner) {
        for (int i = 0; i < rows; i++) {
            String line = scanner.nextLine();
            grid[i] = line.toCharArray();
        }
    }

    /**
     * Calculates the number of adjacent '.' cells.
     * Returns 0 if out of bounds or the cell itself is not '.'.
     */
    private int calculateDegree(int r, int c) {
        if (r < 0 || r >= rows || c < 0 || c >= cols || grid[r][c] != '.') {
            return 0;
        }
        int degree = 0;
        for (int k = 0; k < 4; k++) {
            int nr = r + DR[k];
            int nc = c + DC[k];
            if (nr >= 0 && nr < rows && nc >= 0 && nc < cols && grid[nr][nc] == '.') {
                degree++;
            }
        }
        return degree;
    }

    /**
     * Processes a cell with exactly one empty neighbor.
     * Updates the grid with directional markers and queues adjacent cells
     * that also have exactly one empty neighbor.
     */
    private void processCell(int r, int c) {
        if (calculateDegree(r, c) != 1) {
            return;
        }

        int neighborR = -1;
        int neighborC = -1;
        int directionIndex = -1;

        // Find the single adjacent '.' neighbor
        for (int k = 0; k < 4; k++) {
            int nr = r + DR[k];
            int nc = c + DC[k];
            if (nr >= 0 && nr < rows && nc >= 0 && nc < cols && grid[nr][nc] == '.') {
                neighborR = nr;
                neighborC = nc;
                directionIndex = k;
                break;
            }
        }

        if (neighborR == -1) {
            return; // Should not happen if degree is 1
        }

        // Apply directional markers based on the neighbor's relative position
        switch (directionIndex) {
            case 0: // Left
                grid[r][c - 1] = '<';
                grid[r][c] = '>';
                break;
            case 1: // Right
                grid[r][c] = '<';
                grid[r][c + 1] = '>';
                break;
            case 2: // Top
                grid[r - 1][c] = '^';
                grid[r][c] = 'v';
                break;
            case 3: // Bottom
                grid[r][c] = '^';
                grid[r + 1][c] = 'v';
                break;
        }

        // Check neighbors of the empty cell and queue those with degree 1
        for (int k = 0; k < 4; k++) {
            int nr = neighborR + DR[k];
            int nc = neighborC + DC[k];
            if (nr >= 0 && nr < rows && nc >= 0 && nc < cols
                    && !visited[nr][nc] && calculateDegree(nr, nc) == 1) {
                queue.add(new Cell(nr, nc));
                visited[nr][nc] = true;
            }
        }
    }

    /** Orchestrates the solving process: initial scan, propagation, and validation. */
    public void solve() {
        // Initial pass: identify all starting cells with exactly one empty neighbor
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == '.' && !visited[i][j] && calculateDegree(i, j) == 1) {
                    queue.add(new Cell(i, j));
                    visited[i][j] = true;
                }
            }
        }

        // Process cells in the order they were added (BFS-like propagation)
        while (!queue.isEmpty()) {
            Cell cell = queue.poll();
            processCell(cell.r, cell.c);
        }

        // Verify if any '.' remains unprocessed
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == '.') {
                    System.out.println("Not unique");
                    return;
                }
            }
        }

        // Output the final grid
        for (int i = 0; i < rows; i++) {
            System.out.println(new String(grid[i]));
        }
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        if (!scanner.hasNextInt()) {
            scanner.close();
            return;
        }

        int n = scanner.nextInt();
        int m = scanner.nextInt();
        scanner.nextLine(); // Consume the newline after m

        GridDirectionSolver solver = new GridDirectionSolver(n, m);
        solver.readInput(scanner);
        solver.solve();

        scanner.close();
    }
}

import java.io.*;
import java.util.*;

public class Solution {
    // I/O Components
    private BufferedReader reader;
    private PrintWriter writer;
    private StringTokenizer tokenizer;

    // Grid State
    private int rows;
    private int cols;
    private char[][] grid;
    private boolean[][] used;

    // Direction Vectors (Up, Down, Left, Right)
    private static final int[] DR = {-1, 1, 0, 0};
    private static final int[] DC = {0, 0, -1, 1};

    public static void main(String[] args) throws IOException {
        new Solution().solve();
    }

    public void solve() throws IOException {
        initIO();
        try {
            readInput();
            processGrid();
            printResult();
        } finally {
            closeIO();
        }
    }

    private void initIO() {
        reader = new BufferedReader(new InputStreamReader(System.in));
        writer = new PrintWriter(new OutputStreamWriter(System.out));
    }

    private void closeIO() {
        try {
            reader.close();
            writer.flush();
            writer.close();
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    private void readInput() throws IOException {
        rows = nextInt();
        cols = nextInt();

        grid = new char[rows][cols];

        for (int i = 0; i < rows; i++) {
            String line = reader.readLine();
            if (line != null) {
                // Safety check to prevent StringIndexOutOfBoundsException
                int limit = Math.min(cols, line.length());
                for (int j = 0; j < limit; j++) {
                    grid[i][j] = line.charAt(j);
                }
            }
        }
    }

    private void processGrid() throws IOException {
        used = new boolean[rows][cols];
        Queue<Point> queue = new LinkedList<>();

        // First pass: Identify pairs and initialize queue
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == '.') {
                    Point partner = findPartner(i, j);
                    if (partner != null) {
                        used[partner.r][partner.c] = true;
                        queue.add(partner);
                    }
                }
            }
        }

        // BFS: Propagate and find more pairs if necessary
        while (!queue.isEmpty()) {
            Point current = queue.poll();

            for (int k = 0; k < 4; k++) {
                int nr = current.r + DR[k];
                int nc = current.c + DC[k];

                if (isValid(nr, nc)) {
                    Point partner = findPartner(nr, nc);
                    if (partner != null && !used[partner.r][partner.c]) {
                        used[partner.r][partner.c] = true;
                        queue.add(partner);
                    }
                }
            }
        }
    }

    /**
     * Finds a valid partner for the cell at (r, c).
     * A valid partner is an adjacent '.' cell.
     * If exactly one partner is found, the grid is updated with directional characters,
     * and the partner's coordinates are returned.
     * Otherwise, returns null.
     */
    private Point findPartner(int r, int c) {
        if (!isValid(r, c) || grid[r][c] != '.') {
            return null;
        }

        Point partner = null;

        // Check all 4 adjacent cells
        for (int k = 0; k < 4; k++) {
            int nr = r + DR[k];
            int nc = c + DC[k];

            if (isValid(nr, nc) && grid[nr][nc] == '.') {
                if (partner != null) {
                    // Found more than one partner -> Invalid configuration
                    return null;
                }
                partner = new Point(nr, nc);
            }
        }

        if (partner == null) {
            // No partner found
            return null;
        }

        // Update grid characters based on relative position
        int pr = partner.r;
        int pc = partner.c;

        if (pr < r) {
            // Partner is above
            grid[pr][c] = '^';
            grid[r][c] = 'v';
        } else if (pr > r) {
            // Partner is below
            grid[r][c] = '^';
            grid[pr][c] = 'v';
        } else if (pc < c) {
            // Partner is to the left
            grid[r][pc] = '<';
            grid[r][c] = '>';
        } else if (pc > c) {
            // Partner is to the right
            grid[r][c] = '<';
            grid[r][pc] = '>';
        }

        return partner;
    }

    private boolean isValid(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    private void printResult() {
        // Check if any dot remains unpaired
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == '.') {
                    writer.println("Not unique");
                    return;
                }
            }
        }

        // Print the modified grid
        for (int i = 0; i < rows; i++) {
            writer.println(new String(grid[i]));
        }
    }

    // Fast I/O Helper Methods
    private String next() throws IOException {
        while (tokenizer == null || !tokenizer.hasMoreTokens()) {
            String line = reader.readLine();
            if (line == null) return null;
            tokenizer = new StringTokenizer(line);
        }
        return tokenizer.nextToken();
    }

    private int nextInt() throws IOException {
        String s = next();
        return (s == null) ? 0 : Integer.parseInt(s);
    }

    // Helper class for coordinates
    private static class Point {
        int r, c;

        Point(int r, int c) {
            this.r = r;
            this.c = c;
        }
    }
}

import java.io.BufferedReader;
import java.io.FileNotFoundException;
import java.io.FileReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayDeque;
import java.util.Queue;
import java.util.StringTokenizer;

/**
 * Refactored solution for Codeforces 292D (or similar problem).
 * Improvements made:
 * 1. Removed global static state where possible to improve thread safety and testability.
 * 2. Used meaningful variable and method names (e.g., 'grid' instead of 'mat', 'DR/DC' instead of 'xdir/ydir').
 * 3. Encapsulated logic into helper methods to reduce code duplication and complexity.
 * 4. Used standard Java libraries (StringTokenizer) for robust input parsing.
 * 5. Improved input handling to match original intent (file fallback) but with cleaner structure.
 * 6. Added defensive checks for array bounds.
 */
public class DominoTilingSolver {

    // Direction vectors: Up, Down, Left, Right
    private static final int[] DR = {-1, 1, 0, 0};
    private static final int[] DC = {0, 0, -1, 1};

    public static void main(String[] args) throws IOException {
        solve();
    }

    private static void solve() throws IOException {
        // Setup Input Reader
        // Original logic attempts to read from "cf292D.in", falling back to System.in
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        try {
            br = new BufferedReader(new FileReader("cf292D.in"));
        } catch (FileNotFoundException e) {
            // Fallback to System.in is already set up
        }

        String line = br.readLine();
        if (line == null || line.trim().isEmpty()) {
            return;
        }

        // Parse n and m using StringTokenizer for robustness against whitespace
        StringTokenizer st = new StringTokenizer(line);
        int n = Integer.parseInt(st.nextToken());
        int m = Integer.parseInt(st.nextToken());

        char[][] grid = new char[n][m];
        for (int i = 0; i < n; i++) {
            String row = br.readLine();
            if (row != null) {
                grid[i] = row.toCharArray();
            } else {
                grid[i] = new char[m]; // Fill with empty/nulls if line missing
            }
        }

        Queue<Domino> queue = new ArrayDeque<>();

        // 1. Identify initial dominoes (cells with exactly 1 empty neighbor)
        // This acts as a topological sort / peeling process
        for (int r = 0; r < n; r++) {
            // Safety check for row length
            if (grid[r] == null || grid[r].length < m) continue;

            for (int c = 0; c < m; c++) {
                if (grid[r][c] == '.') {
                    Point neighbor = getSingleEmptyNeighbor(r, c, n, m, grid);
                    if (neighbor != null) {
                        queue.add(new Domino(new Point(r, c), neighbor));
                    }
                }
            }
        }

        // 2. Process the queue
        while (!queue.isEmpty()) {
            Domino d = queue.poll();

            // Check if domino is still valid
            // d.p1 is the cell that triggered this domino (was degree 1)
            // d.p2 is the neighbor
            // If p1 is empty, p2 MUST be empty.
            // If p2 is occupied, p1 has lost its only neighbor, implying a conflict or isolation.

            // Bounds check (defensive)
            if (!isValid(d.p1.r, d.p1.c, n, m) || !isValid(d.p2.r, d.p2.c, n, m)) continue;

            if (grid[d.p1.r][d.p1.c] == '.' && grid[d.p2.r][d.p2.c] != '.') {
                System.out.println("Not unique");
                return;
            }

            // If p1 is empty, we place the domino
            if (grid[d.p1.r][d.p1.c] == '.') {
                placeDomino(grid, d.p1, d.p2);

                // After placing at p2, check neighbors of p2 for new degree-1 nodes
                // (p1 is already processed/marked, so we look at p2's other neighbors)
                checkNeighborsForNewDominoes(d.p2, n, m, grid, queue);
            }
        }

        // 3. Check for remaining empty cells
        // If any '.' remains, the tiling is not unique or impossible
        for (int r = 0; r < n; r++) {
            if (grid[r] == null) continue;
            for (int c = 0; c < m; c++) {
                if (c < grid[r].length && grid[r][c] == '.') {
                    System.out.println("Not unique");
                    return;
                }
            }
        }

        // 4. Output
        StringBuilder sb = new StringBuilder();
        for (int r = 0; r < n; r++) {
            if (grid[r] != null) {
                sb.append(grid[r]);
            }
            sb.append('\n');
        }
        System.out.print(sb);
    }

    /**
     * Finds if a cell at (r, c) has exactly one empty neighbor ('.').
     * Returns that neighbor's coordinates, or null if count != 1.
     */
    private static Point getSingleEmptyNeighbor(int r, int c, int n, int m, char[][] grid) {
        Point neighbor = null;
        int count = 0;
        for (int k = 0; k < 4; k++) {
            int nr = r + DR[k];
            int nc = c + DC[k];
            if (isValid(nr, nc, n, m) && grid[nr][nc] == '.') {
                count++;
                neighbor = new Point(nr, nc);
            }
        }
        return (count == 1) ? neighbor : null;
    }

    /**
     * Checks neighbors of a cell to see if they became degree-1 after a domino placement.
     */
    private static void checkNeighborsForNewDominoes(Point p, int n, int m, char[][] grid, Queue<Domino> queue) {
        for (int k = 0; k < 4; k++) {
            int nr = p.r + DR[k];
            int nc = p.c + DC[k];
            if (isValid(nr, nc, n, m) && grid[nr][nc] == '.') {
                // Check if this neighbor now has exactly 1 empty neighbor
                // Note: The current cell p is marked (arrow), so it won't count as '.'
                Point neighbor = getSingleEmptyNeighbor(nr, nc, n, m, grid);
                if (neighbor != null) {
                    queue.add(new Domino(new Point(nr, nc), neighbor));
                }
            }
        }
    }

    private static boolean isValid(int r, int c, int n, int m) {
        return r >= 0 && r < n && c >= 0 && c < m;
    }

    private static void placeDomino(char[][] grid, Point p1, Point p2) {
        // Determine direction based on relative position
        // p1 is the "source" (the one that had degree 1)
        // p2 is the "target"

        // p1 above p2 (p1.r < p2.r)
        if (p1.r == p2.r - 1) { 
            grid[p1.r][p1.c] = '^';
            grid[p2.r][p2.c] = 'v';
        } 
        // p1 below p2
        else if (p1.r == p2.r + 1) { 
            grid[p1.r][p1.c] = 'v';
            grid[p2.r][p2.c] = '^';
        } 
        // p1 left of p2 (p1.c < p2.c)
        else if (p1.c == p2.c - 1) { 
            grid[p1.r][p1.c] = '<';
            grid[p2.r][p2.c] = '>';
        } 
        // p1 right of p2
        else if (p1.c == p2.c + 1) { 
            grid[p1.r][p1.c] = '>';
            grid[p2.r][p2.c] = '<';
        }
    }

    /**
     * Represents a coordinate in the grid.
     */
    static class Point {
        int r, c;
        Point(int r, int c) { this.r = r; this.c = c; }
    }

    /**
     * Represents a domino connecting two points.
     */
    static class Domino {
        Point p1, p2;
        Domino(Point p1, Point p2) { this.p1 = p1; this.p2 = p2; }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

/**
 * Solves a grid pairing problem by finding a unique perfect matching on '.' cells.
 * Uses a degree-based peeling algorithm similar to topological sorting to pair adjacent cells.
 */
public class GridPairingSolver {

    private int rows;
    private int cols;
    private char[][] grid;
    private int[] degree;

    // Direction vectors: Down, Up, Right, Left
    private static final int[] ROW_DELTA = {1, -1, 0, 0};
    private static final int[] COL_DELTA = {0, 0, 1, -1};

    // Character mappings for paired directions
    private static final char[] FIRST_CHAR = {'^', 'v', '<', '>'};
    private static final char[] SECOND_CHAR = {'v', '^', '>', '<'};

    public static void main(String[] args) {
        new GridPairingSolver().solve();
    }

    public void solve() {
        FastScanner sc = new FastScanner();
        PrintWriter pw = new PrintWriter(System.out);

        try {
            rows = sc.nextInt();
            cols = sc.nextInt();
            int totalCells = rows * cols;
            grid = new char[rows][cols];

            for (int i = 0; i < rows; i++) {
                grid[i] = sc.next().toCharArray();
            }

            degree = new int[totalCells];
            int[] queue = new int[totalCells + 10];
            int head = 0;
            int tail = 0;
            int remainingDots = 0;

            // Initialize degrees and seed the queue with degree-1 nodes
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j] == '.') {
                        remainingDots++;
                        // Count edges to right and down neighbors to avoid double counting
                        for (int k = 0; k < 4; k += 2) {
                            int nr = i + ROW_DELTA[k];
                            int nc = j + COL_DELTA[k];
                            if (isValid(nr, nc) && grid[nr][nc] == '.') {
                                degree[i * cols + j]++;
                                degree[nr * cols + nc]++;
                            }
                        }
                        if (degree[i * cols + j] == 1) {
                            queue[tail++] = i * cols + j;
                        }
                    }
                }
            }

            boolean allProcessed = true;
            while (head != tail) {
                int p = queue[head++];
                int r = p / cols;
                int c = p % cols;

                // Skip if already processed
                if (grid[r][c] != '.') {
                    continue;
                }

                remainingDots -= 2;
                boolean foundNeighbor = false;

                for (int k = 0; k < 4; k++) {
                    int nr = r + ROW_DELTA[k];
                    int nc = c + COL_DELTA[k];
                    if (isValid(nr, nc) && grid[nr][nc] == '.') {
                        foundNeighbor = true;
                        grid[r][c] = FIRST_CHAR[k];
                        grid[nr][nc] = SECOND_CHAR[k];

                        // Update degrees for neighbors of the matched pair
                        for (int k2 = 0; k2 < 4; k2++) {
                            int nnr = nr + ROW_DELTA[k2];
                            int nnc = nc + COL_DELTA[k2];
                            if (isValid(nnr, nnc) && --degree[nnr * cols + nnc] == 1) {
                                queue[tail++] = nnr * cols + nnc;
                            }
                        }
                        break;
                    }
                }
                allProcessed &= foundNeighbor;
            }

            if (!allProcessed || remainingDots > 0) {
                pw.println("Not unique");
            } else {
                for (int i = 0; i < rows; i++) {
                    pw.println(new String(grid[i]));
                }
            }
        } catch (Exception e) {
            pw.println("Error during processing: " + e.getMessage());
        } finally {
            pw.flush();
            pw.close();
        }
    }

    private boolean isValid(int r, int c) {
        return r >= 0 && c >= 0 && r < rows && c < cols;
    }

    /**
     * Fast I/O helper class optimized for competitive programming.
     */
    private static class FastScanner {
        private BufferedReader br;
        private StringTokenizer st;

        public FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    e.printStackTrace();
                    return null;
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            String s = next();
            return s == null ? 0 : Integer.parseInt(s);
        }

        long nextLong() {
            String s = next();
            return s == null ? 0L : Long.parseLong(s);
        }

        double nextDouble() {
            String s = next();
            return s == null ? 0.0 : Double.parseDouble(s);
        }

        String nextLine() {
            String str = "";
            try {
                str = br.readLine();
            } catch (IOException e) {
                e.printStackTrace();
            }
            return str;
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayDeque;
import java.util.Queue;

/**
 * Solves the "Drazil and Tiles" problem by filling empty grid cells with directional arrows.
 * Uses a topological sort approach (Kahn's algorithm) based on the count of adjacent empty cells.
 */
public class DrazilAndTiles {

    private static final int[] DX = {-1, 1, 0, 0};
    private static final int[] DY = {0, 0, -1, 1};

    public static void main(String[] args) throws IOException {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));

        // Read grid dimensions
        String[] dimensions = reader.readLine().split("\\s+");
        int n = Integer.parseInt(dimensions[0]);
        int m = Integer.parseInt(dimensions[1]);

        // Read grid layout
        char[][] grid = new char[n][];
        for (int i = 0; i < n; i++) {
            grid[i] = reader.readLine().trim().toCharArray();
        }

        // Calculate initial adjacency counts for empty cells
        int[][] adjCount = new int[n][m];
        Queue<int[]> queue = new ArrayDeque<>();

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == '*') {
                    continue;
                }

                int count = 0;
                for (int d = 0; d < 4; d++) {
                    int ni = i + DX[d];
                    int nj = j + DY[d];
                    if (isInBounds(ni, nj, n, m) && grid[ni][nj] == '.') {
                        count++;
                    }
                }

                adjCount[i][j] = count;
                if (count == 0) {
                    System.out.println("Not unique");
                    return;
                }
                if (count == 1) {
                    queue.offer(new int[]{i, j});
                }
            }
        }

        // Process queue using topological sort logic
        while (!queue.isEmpty()) {
            int[] curr = queue.poll();
            int i = curr[0];
            int j = curr[1];

            // Skip if already processed
            if (grid[i][j] != '.') {
                continue;
            }

            // If count dropped below 1, solution is invalid
            if (adjCount[i][j] < 1) {
                System.out.println("Not unique");
                return;
            }

            // Find the single adjacent empty cell
            int ni = -1, nj = -1;
            for (int d = 0; d < 4; d++) {
                int nextI = i + DX[d];
                int nextJ = j + DY[d];
                if (isInBounds(nextI, nextJ, n, m) && grid[nextI][nextJ] == '.') {
                    ni = nextI;
                    nj = nextJ;
                    break;
                }
            }

            // Place arrows between the two cells
            grid[i][j] = getArrowChar(i, j, ni, nj);
            grid[ni][nj] = getArrowChar(ni, nj, i, j);

            // Update adjacency counts for neighbors of the newly filled cell
            for (int d = 0; d < 4; d++) {
                int adjI = ni + DX[d];
                int adjJ = nj + DY[d];
                if (isInBounds(adjI, adjJ, n, m) && grid[adjI][adjJ] == '.') {
                    adjCount[adjI][adjJ]--;
                    if (adjCount[adjI][adjJ] == 1) {
                        queue.offer(new int[]{adjI, adjJ});
                    }
                }
            }
        }

        // Verify all cells are filled
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == '.') {
                    System.out.println("Not unique");
                    return;
                }
            }
        }

        // Output result
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < n; i++) {
            sb.append(grid[i]).append('\n');
        }
        System.out.print(sb);
    }

    /**
     * Checks if the given coordinates are within the grid boundaries.
     */
    private static boolean isInBounds(int r, int c, int rows, int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /**
     * Determines the correct arrow character based on relative positions.
     */
    private static char getArrowChar(int r1, int c1, int r2, int c2) {
        if (r1 == r2) {
            return c1 < c2 ? '<' : '>';
        }
        if (c1 == c2) {
            return r1 < r2 ? '^' : 'v';
        }
        return 0; // Should not be reached in valid inputs
    }
}

import java.io.BufferedReader;
