class TaskB {
    private static final int[] DR = {1, -1, 0, 0};
    private static final int[] DC = {0, 0, 1, -1};
    private static final char[] DIR_CHARS = {'^', 'v', '<', '>'};

    public void solve(FastScanner in, PrintWriter out) {
        int n = in.nextInt();
        int m = in.nextInt();
        char[][] grid = new char[n][];
        for (int i = 0; i < n; i++) {
            grid[i] = in.next().toCharArray();
        }

        int[][] neighborCounts = new int[n][m];
        // Queue stores packed coordinates: (row * m) + col
        Queue<Integer> queue = new ArrayDeque<>();

        // Initialize neighbor counts and seed the queue with cells having exactly 1 valid neighbor
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < m; c++) {
                if (grid[r][c] == '*') continue;

                int count = 0;
                for (int d = 0; d < 4; d++) {
                    int nr = r + DR[d];
                    int nc = c + DC[d];
                    if (isValid(nr, nc, n, m) && grid[nr][nc] == '.') {
                        count++;
                    }
                }
                neighborCounts[r][c] = count;
                if (count == 1) {
                    queue.add(r * m + c);
                }
            }
        }

        // Process cells using BFS/topological propagation
        while (!queue.isEmpty()) {
            int pos = queue.poll();
            int r = pos / m;
            int c = pos % m;

            // Skip if already assigned or processed
            if (grid[r][c] != '.') continue;

            for (int d = 0; d < 4; d++) {
                int nr = r + DR[d];
                int nc = c + DC[d];
                if (isValid(nr, nc, n, m) && grid[nr][nc] == '.') {
                    grid[r][c] = DIR_CHARS[d];
                    grid[nr][nc] = DIR_CHARS[d ^ 1]; // Opposite direction
                    updateNeighbors(r, c, neighborCounts, queue, n, m, grid);
                    updateNeighbors(nr, nc, neighborCounts, queue, n, m, grid);
                    break; // Each cell is assigned exactly once
                }
            }
        }

        // Verify if all empty cells were successfully assigned
        boolean allAssigned = true;
        outer:
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < m; c++) {
                if (grid[r][c] == '.') {
                    allAssigned = false;
                    break outer;
                }
            }
        }

        if (!allAssigned) {
            out.println("Not unique");
        } else {
            for (int r = 0; r < n; r++) {
                out.println(new String(grid[r]));
            }
        }
    }

    private boolean isValid(int r, int c, int n, int m) {
        return r >= 0 && r < n && c >= 0 && c < m;
    }

    private void updateNeighbors(int r, int c, int[][] neighborCounts,
                                 Queue<Integer> queue, int n, int m, char[][] grid) {
        for (int d = 0; d < 4; d++) {
            int nr = r + DR[d];
            int nc = c + DC[d];
            if (isValid(nr, nc, n, m) && grid[nr][nc] == '.') {
                neighborCounts[nr][nc]--;
                if (neighborCounts[nr][nc] == 1) {
                    queue.add(nr * m + nc);
                }
            }
        }
    }

    /**
     * Fast input reader for competitive programming / performance-critical contexts.
     */
    static class FastScanner {
        private BufferedReader br;
        private StringTokenizer st;

        public FastScanner(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input", e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            String s = next();
            if (s == null) throw new RuntimeException("Unexpected end of input");
            return Integer.parseInt(s);
        }
    }
}

import java.io.*;
import java.util.*;

public class Main {
    // Direction vectors: Up, Down, Left, Right
    private static final int[] DR = {-1, 1, 0, 0};
    private static final int[] DC = {0, 0, -1, 1};

    public static void main(String[] args) {
        // Run in a thread with increased stack size (common in competitive programming environments)
        new Thread(null, new Runnable() {
            @Override
            public void run() {
                try {
                    solve();
                } catch (Exception e) {
                    e.printStackTrace();
                    System.exit(1);
                }
            }
        }, "Main", 1 << 28).start();
    }

    private static void solve() throws IOException {
        FastScanner sc = new FastScanner();
        PrintWriter out = new PrintWriter(System.out);

        // Ensure consistent number parsing
        Locale.setDefault(Locale.US);

        // Read dimensions
        // Check for EOF or invalid input gracefully
        String nStr = sc.next();
        if (nStr == null) {
            out.close();
            return;
        }
        int rows = Integer.parseInt(nStr);
        int cols = sc.nextInt();

        char[][] grid = new char[rows][cols];

        // Read grid
        for (int r = 0; r < rows; ++r) {
            String line = sc.next();
            if (line != null) {
                grid[r] = line.toCharArray();
            }
        }

        Queue<Cell> queue = new LinkedList<>();

        // Initial pass: Identify all '.' cells with exactly 1 '.' neighbor
        for (int r = 0; r < rows; ++r) {
            for (int c = 0; c < cols; ++c) {
                if (grid[r][c] == '.') {
                    int emptyNeighbors = countEmptyNeighbors(grid, r, c, rows, cols);
                    if (emptyNeighbors == 1) {
                        queue.add(new Cell(r, c));
                    }
                }
            }
        }

        // Process the queue
        while (!queue.isEmpty()) {
            Cell current = queue.poll();
            int r = current.r;
            int c = current.c;

            // If the cell is no longer '.', it has already been processed
            if (grid[r][c] != '.') {
                continue;
            }

            int emptyNeighbors = countEmptyNeighbors(grid, r, c, rows, cols);

            // Logic applies only if the cell still has exactly 1 empty neighbor
            if (emptyNeighbors == 1) {
                int[] neighbor = findEmptyNeighbor(grid, r, c, rows, cols);
                int nr = neighbor[0];
                int nc = neighbor[1];

                // Assign directional arrows
                assignDirections(grid, r, c, nr, nc);

                // Add neighbors of the modified cell to the queue to propagate changes
                for (int k = 0; k < 4; ++k) {
                    int nr2 = nr + DR[k];
                    int nc2 = nc + DC[k];
                    if (isValid(nr2, nc2, rows, cols) && grid[nr2][nc2] == '.') {
                        queue.add(new Cell(nr2, nc2));
                    }
                }
            }
        }

        // Check if any '.' remains unassigned
        for (int r = 0; r < rows; ++r) {
            for (int c = 0; c < cols; ++c) {
                if (grid[r][c] == '.') {
                    out.println("Not unique");
                    out.close();
                    return;
                }
            }
        }

        // Print the resulting grid
        for (int r = 0; r < rows; ++r) {
            out.println(new String(grid[r]));
        }

        out.close();
    }

    /**
     * Checks if coordinates are within grid bounds.
     */
    private static boolean isValid(int r, int c, int rows, int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /**
     * Counts the number of '.' neighbors for a given cell.
     */
    private static int countEmptyNeighbors(char[][] grid, int r, int c, int rows, int cols) {
        int count = 0;
        for (int k = 0; k < 4; ++k) {
            int nr = r + DR[k];
            int nc = c + DC[k];
            if (isValid(nr, nc, rows, cols) && grid[nr][nc] == '.') {
                count++;
            }
        }
        return count;
    }

    /**
     * Finds the coordinates of the single '.' neighbor.
     * Returns an array {row, col} or null if not found.
     */
    private static int[] findEmptyNeighbor(char[][] grid, int r, int c, int rows, int cols) {
        for (int k = 0; k < 4; ++k) {
            int nr = r + DR[k];
            int nc = c + DC[k];
            if (isValid(nr, nc, rows, cols) && grid[nr][nc] == '.') {
                return new int[]{nr, nc};
            }
        }
        return null;
    }

    /**
     * Assigns directional arrows to the current cell and its neighbor.
     * Logic preserved from original code: arrows point away from the connection.
     */
    private static void assignDirections(char[][] grid, int r, int c, int nr, int nc) {
        if (r < nr) {
            grid[r][c] = '^';
            grid[nr][nc] = 'v';
        } else if (r > nr) {
            grid[r][c] = 'v';
            grid[nr][nc] = '^';
        } else if (c < nc) {
            grid[r][c] = '<';
            grid[nr][nc] = '>';
        } else {
            // c > nc
            grid[r][c] = '>';
            grid[nr][nc] = '<';
        }
    }

    // --- Helper Classes ---

    /**
     * Represents a cell coordinate in the grid.
     */
    private static class Cell {
        int r, c;

        Cell(int r, int c) {
            this.r = r;
            this.c = c;
        }
    }

    /**
     * FastScanner for efficient input reading.
     */
    private static class FastScanner {
        BufferedReader in;
        StringTokenizer tok;

        FastScanner() {
            in = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() throws IOException {
            while (tok == null || !tok.hasMoreTokens()) {
                String line = in.readLine();
                if (line == null) {
                    return null;
                }
                tok = new StringTokenizer(line);
            }
            return tok.nextToken();
        }

        int nextInt() throws IOException {
            String s = next();
            if (s == null) throw new IOException("Unexpected end of input");
            return Integer.parseInt(s);
        }
    }
}

import java.io.*;
import java.util.*;

public class DrazilAndTiles515D {

    // Direction deltas: Left, Up, Right, Down
    private static final int[][] DIRECTIONS = {{0, -1}, {-1, 0}, {0, 1}, {1, 0}};
    // Corresponding tile symbols for (current, neighbor)
    private static final char[][] DIRECTION_SYMBOLS = {{'>', '<'}, {'v', '^'}, {'<', '>'}, {'^', 'v'}};

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out));

        try {
            solve(scanner, out);
        } finally {
            out.flush();
            out.close();
        }
    }

    private static void solve(FastScanner scanner, PrintWriter out) {
        int n = scanner.nextInt();
        int m = scanner.nextInt();

        // Pad grid with an extra border to simplify boundary checks
        char[][] grid = new char[n + 2][m + 2];
        for (int i = 1; i <= n; i++) {
            String row = scanner.next();
            row.getChars(0, m, grid[i], 1);
        }

        GridSolver solver = new GridSolver(n, m, grid);
        solver.process();

        if (solver.getRemainingEmptyCount() > 0) {
            out.println("Not unique");
        } else {
            for (int i = 1; i <= n; i++) {
                out.println(new String(grid[i], 1, m));
            }
        }
    }

    /**
     * Encapsulates the grid processing logic using a topological sort approach.
     * Cells with exactly one empty neighbor are placed first, propagating constraints.
     */
    private static class GridSolver {
        private final int rows;
        private final int cols;
        private final char[][] grid;
        private final int[][] degrees;
        private final Queue<int[]> queue;
        private int remainingEmptyCount;

        public GridSolver(int rows, int cols, char[][] grid) {
            this.rows = rows;
            this.cols = cols;
            this.grid = grid;
            this.degrees = new int[rows + 2][cols + 2];
            this.queue = new ArrayDeque<>();
            this.remainingEmptyCount = 0;
            initialize();
        }

        private void initialize() {
            for (int i = 1; i <= rows; i++) {
                for (int j = 1; j <= cols; j++) {
                    if (grid[i][j] == '.') {
                        remainingEmptyCount++;
                        int degree = countAdjacentEmptyCells(i, j);
                        degrees[i][j] = degree;
                        if (degree == 1) {
                            queue.offer(new int[]{i, j});
                        }
                    }
                }
            }
        }

        private int countAdjacentEmptyCells(int r, int c) {
            int count = 0;
            for (int[] dir : DIRECTIONS) {
                if (grid[r + dir[0]][c + dir[1]] == '.') {
                    count++;
                }
            }
            return count;
        }

        public void process() {
            while (!queue.isEmpty()) {
                int[] cell = queue.poll();
                int r = cell[0];
                int c = cell[1];

                // Skip if already filled or if degree condition is no longer met
                if (grid[r][c] != '.' || degrees[r][c] != 1) {
                    continue;
                }

                int nr = -1, nc = -1;
                int symbolIndex = -1;

                // Find the only adjacent empty cell
                for (int i = 0; i < 4; i++) {
                    int[] dir = DIRECTIONS[i];
                    if (grid[r + dir[0]][c + dir[1]] == '.') {
                        nr = r + dir[0];
                        nc = c + dir[1];
                        symbolIndex = i;
                        break;
                    }
                }

                if (nr == -1) continue; // Should not happen if degree == 1

                // Place the tiles
                grid[r][c] = DIRECTION_SYMBOLS[symbolIndex][0];
                grid[nr][nc] = DIRECTION_SYMBOLS[symbolIndex][1];

                // Update degrees for neighbors of the newly placed cell
                for (int[] dir : DIRECTIONS) {
                    int neighborR = nr + dir[0];
                    int neighborC = nc + dir[1];
                    if (grid[neighborR][neighborC] == '.') {
                        degrees[neighborR][neighborC]--;
                        if (degrees[neighborR][neighborC] == 1) {
                            queue.offer(new int[]{neighborR, neighborC});
                        }
                    }
                }
                remainingEmptyCount -= 2;
            }
        }

        public int getRemainingEmptyCount() {
            return remainingEmptyCount;
        }
    }

    /**
     * High-performance input reader for competitive programming.
     */
    static class FastScanner {
        private final InputStream stream;
        private final byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;

        public FastScanner(InputStream stream) {
            this.stream = stream;
        }

        public int read() {
            if (numChars == -1) {
                throw new InputMismatchException();
            }
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0) {
                    return -1;
                }
            }
            return buf[curChar++];
        }

        public int nextInt() {
            return (int) nextLong();
        }

        public long nextLong() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            long res = 0;
            do {
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                res *= 10;
                res += c - '0';
                c = read();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public String next() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            StringBuilder sb = new StringBuilder();
            do {
                sb.append((char) c);
                c = read();
            } while (!isSpaceChar(c));
            return sb.toString();
        }

        public static boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }
    }
}

