class SolverD {

    // Direction vectors: Up, Down, Left, Right
    private static final int[] DR = {-1, 1, 0, 0};
    private static final int[] DC = {0, 0, -1, 1};

    public void solve(FastScanner in, PrintWriter out) {
        int n = in.nextInt();
        int m = in.nextInt();

        // Pad grid with '*' to safely handle boundary checks implicitly
        char[][] grid = new char[n + 2][m + 2];

        initializeBoundaries(grid, n, m);
        readGrid(in, grid, n, m);

        Queue<Position> queue = new ArrayDeque<>();
        initializeLeafQueue(grid, n, m, queue);

        processQueue(grid, queue);

        if (hasRemainingEmptyCells(grid, n, m)) {
            out.println("Not unique");
        } else {
            printResultGrid(out, grid, n, m);
        }
    }

    private void initializeBoundaries(char[][] grid, int n, int m) {
        for (int i = 0; i <= m + 1; i++) {
            grid[0][i] = '*';
            grid[n + 1][i] = '*';
        }
        for (int i = 0; i <= n + 1; i++) {
            grid[i][0] = '*';
            grid[i][m + 1] = '*';
        }
    }

    private void readGrid(FastScanner in, char[][] grid, int n, int m) {
        for (int i = 1; i <= n; i++) {
            String row = in.next();
            for (int j = 1; j <= m; j++) {
                grid[i][j] = row.charAt(j - 1);
            }
        }
    }

    private void initializeLeafQueue(char[][] grid, int n, int m, Queue<Position> queue) {
        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= m; j++) {
                if (grid[i][j] == '.' && isLeaf(grid, i, j)) {
                    queue.add(new Position(i, j));
                }
            }
        }
    }

    private void processQueue(char[][] grid, Queue<Position> queue) {
        while (!queue.isEmpty()) {
            Position current = queue.poll();

            // Skip if already processed (marked with directional character)
            if (grid[current.r][current.c] != '.') {
                continue;
            }

            Position next = findAdjacentEmpty(grid, current);
            if (next == null) {
                continue;
            }

            // Check neighbors of the newly visited cell for new leaves
            for (int k = 0; k < 4; k++) {
                int nr = next.r + DR[k];
                int nc = next.c + DC[k];
                if (isLeaf(grid, nr, nc)) {
                    queue.add(new Position(nr, nc));
                }
            }
        }
    }

    /**
     * Checks if a cell has exactly one adjacent empty cell ('.').
     * Boundary cells are padded with '*', so they naturally return false.
     */
    private boolean isLeaf(char[][] grid, int r, int c) {
        if (grid[r][c] != '.') {
            return false;
        }
        int adjacentEmptyCount = 0;
        for (int k = 0; k < 4; k++) {
            if (grid[r + DR[k]][c + DC[k]] == '.') {
                adjacentEmptyCount++;
            }
        }
        return adjacentEmptyCount == 1;
    }

    /**
     * Finds the first adjacent empty cell and marks the edge between 
     * current and next with directional characters.
     */
    private Position findAdjacentEmpty(char[][] grid, Position current) {
        for (int k = 0; k < 4; k++) {
            int nr = current.r + DR[k];
            int nc = current.c + DC[k];
            if (grid[nr][nc] == '.') {
                setDirectionMarkers(grid, current, new Position(nr, nc), k);
                return new Position(nr, nc);
            }
        }
        return null;
    }

    private void setDirectionMarkers(char[][] grid, Position from, Position to, int dirIndex) {
        grid[from.r][from.c] = getDirectionChar(dirIndex, false);
        grid[to.r][to.c] = getDirectionChar(dirIndex, true);
    }

    private char getDirectionChar(int dirIndex, boolean isTarget) {
        switch (dirIndex) {
            case 0: // Up
                return isTarget ? '^' : 'v';
            case 1: // Down
                return isTarget ? 'v' : '^';
            case 2: // Left
                return isTarget ? '<' : '>';
            case 3: // Right
                return isTarget ? '>' : '<';
            default:
                throw new IllegalArgumentException("Invalid direction index: " + dirIndex);
        }
    }

    private boolean hasRemainingEmptyCells(char[][] grid, int n, int m) {
        outer:
        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= m; j++) {
                if (grid[i][j] == '.') {
                    return true;
                }
            }
        }
        return false;
    }

    private void printResultGrid(PrintWriter out, char[][] grid, int n, int m) {
        for (int i = 1; i <= n; i++) {
            out.println(new String(grid[i], 1, m));
        }
    }

    /**
     * Represents a coordinate in the grid.
     */
    static class Position {
        int r, c;

        Position(int r, int c) {
            this.r = r;
            this.c = c;
        }
    }

    /**
     * Optimized input reader for competitive programming scenarios.
     */
    static class FastScanner {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        FastScanner(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input", e);
                }
            }
            return tokenizer.nextToken();
        }

        int nextInt() {
            String token = next();
            return token == null ? 0 : Integer.parseInt(token);
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayDeque;
import java.util.Queue;
import java.util.StringTokenizer;

/**
 * Solves a grid-based arrow placement puzzle.
 * Fills '.' cells with directional arrows such that each cell points to exactly one other '.' cell.
 */
public class ArrowGridSolver {

    private static final String ERROR_MESSAGE = "Not unique";

    /**
     * Enum encapsulating direction deltas and corresponding arrow characters.
     * Matches the original index mapping: 0=DOWN, 1=UP, 2=RIGHT, 3=LEFT
     */
    enum Direction {
        DOWN(1, 0, '^', 'v'),
        UP(-1, 0, 'v', '^'),
        RIGHT(0, 1, '<', '>'),
        LEFT(0, -1, '>', '<');

        final int dr, dc;
        final char fromChar, toChar;

        Direction(int dr, int dc, char fromChar, char toChar) {
            this.dr = dr;
            this.dc = dc;
            this.fromChar = fromChar;
            this.toChar = toChar;
        }

        static Direction fromIndex(int index) {
            return values()[index];
        }
    }

    /**
     * Represents a grid cell that has exactly one valid directional option.
     */
    private static class CellWithDirection {
        final int r, c;
        final Direction dir;

        CellWithDirection(int r, int c, Direction dir) {
            this.r = r;
            this.c = c;
            this.dir = dir;
        }
    }

    private int rows, cols;
    private char[][] grid;
    private int[][] remainingOptions;
    private final Queue<CellWithDirection> queue = new ArrayDeque<>();

    /**
     * Entry point for the solver. Orchestrates the full pipeline.
     */
    public void solve() throws IOException {
        readInput();
        initialize();
        processQueue();
        validateCompletion();
        printResult();
    }

    private void readInput() throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        this.rows = Integer.parseInt(st.nextToken());
        this.cols = Integer.parseInt(st.nextToken());
        this.grid = new char[rows][cols];
        this.remainingOptions = new int[rows][cols];

        for (int i = 0; i < rows; i++) {
            grid[i] = br.readLine().toCharArray();
        }
    }

    private void initialize() {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '.') {
                    remainingOptions[r][c] = countValidNeighbors(r, c);
                    if (remainingOptions[r][c] == 0) {
                        fail();
                    }
                    if (remainingOptions[r][c] == 1) {
                        Direction dir = findSingleDirection(r, c);
                        queue.add(new CellWithDirection(r, c, dir));
                    }
                } else {
                    remainingOptions[r][c] = -1; // Mark obstacles
                }
            }
        }
    }

    private int countValidNeighbors(int r, int c) {
        int count = 0;
        for (Direction dir : Direction.values()) {
            if (isValid(r + dir.dr, c + dir.dc)) {
                count++;
            }
        }
        return count;
    }

    private Direction findSingleDirection(int r, int c) {
        for (Direction dir : Direction.values()) {
            if (isValid(r + dir.dr, c + dir.dc)) {
                return dir;
            }
        }
        return null; // Should not occur if remainingOptions == 1
    }

    private boolean isValid(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols && grid[r][c] == '.';
    }

    private void processQueue() {
        while (!queue.isEmpty()) {
            CellWithDirection cell = queue.poll();

            // Skip if already processed (grid cell was updated)
            if (!isValid(cell.r, cell.c)) {
                continue;
            }

            Direction dir = cell.dir;
            int nr = cell.r + dir.dr;
            int nc = cell.c + dir.dc;

            // Mark both cells as processed
            remainingOptions[cell.r][cell.c] = -1;
            remainingOptions[nr][nc] = -1;

            // Place arrows
            grid[cell.r][cell.c] = dir.fromChar;
            grid[nr][nc] = dir.toChar;

            // Update neighbor counts for the destination cell
            for (Direction neighborDir : Direction.values()) {
                int rNeighbor = nr + neighborDir.dr;
                int cNeighbor = nc + neighborDir.dc;

                if (isValid(rNeighbor, cNeighbor)) {
                    // If a cell already had only 1 option left, decrementing makes it 0 -> invalid
                    if (remainingOptions[rNeighbor][cNeighbor] == 1) {
                        fail();
                    }
                    remainingOptions[rNeighbor][cNeighbor]--;

                    // If it now has exactly 1 option, it becomes deterministic
                    if (remainingOptions[rNeighbor][cNeighbor] == 1) {
                        Direction singleDir = findSingleDirection(rNeighbor, cNeighbor);
                        queue.add(new CellWithDirection(rNeighbor, cNeighbor, singleDir));
                    }
                }
            }
        }
    }

    private void validateCompletion() {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (isValid(r, c)) {
                    fail();
                }
            }
        }
    }

    private void fail() {
        System.out.println(ERROR_MESSAGE);
        System.exit(0);
    }

    private void printResult() {
        for (int r = 0; r < rows; r++) {
            System.out.println(new String(grid[r]));
        }
    }

    public static void main(String[] args) throws IOException {
        new ArrowGridSolver().solve();
    }
}

import java.util.*;

/**
 * Refactored Maze Solver.
 * Solves a grid-based puzzle by propagating constraints from cells with 3 blocked neighbors.
 */
public class MazeSolver {

    // Constants
    private static final int NUM_DIRECTIONS = 4;
    private static final int BLOCKED_THRESHOLD = 3;

    // Direction vectors: Up, Down, Right, Left
    private static final int[] DX = {-1, 1, 0, 0};
    private static final int[] DY = {0, 0, -1, 1};

    // Tile mappings corresponding to direction indices.
    // Index 0: Up/Down, 1: Down/Up, 2: Right/Left, 3: Left/Right
    private static final char[][] TILE_MAP = {
        {'v', '^'}, // 0
        {'^', 'v'}, // 1
        {'>', '<'}, // 2
        {'<', '>'}  // 3
    };

    public static void main(String[] args) {
        // Use try-with-resources to ensure Scanner is closed
        try (Scanner scanner = new Scanner(System.in)) {
            if (!scanner.hasNextInt()) {
                return;
            }

            int rows = scanner.nextInt();
            int cols = scanner.nextInt();

            char[][] maze = new char[rows][];
            for (int i = 0; i < rows; i++) {
                maze[i] = scanner.next().toCharArray();
            }

            solve(rows, cols, maze);
        }
    }

    /**
     * Main solving logic.
     */
    private static void solve(int rows, int cols, char[][] maze) {
        // deg[r][c] stores the number of non-empty (blocked) neighbors for cell (r, c)
        int[][] blockedCounts = new int[rows][cols];
        Queue<Point> queue = new LinkedList<>();

        // 1. Initialize degrees and identify initial deterministic moves
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (maze[r][c] == '.') {
                    int blocked = countBlockedNeighbors(r, c, rows, cols, maze);
                    blockedCounts[r][c] = blocked;
                    // If 3 neighbors are blocked, the 4th one is deterministic
                    if (blocked == BLOCKED_THRESHOLD) {
                        queue.add(new Point(r, c));
                    }
                }
            }
        }

        // 2. Process the queue (BFS)
        while (!queue.isEmpty()) {
            Point current = queue.poll();
            int r = current.r;
            int c = current.c;

            // Find the single empty neighbor
            Point emptyNeighbor = findEmptyNeighbor(r, c, rows, cols, maze);

            if (emptyNeighbor != null) {
                // Determine which direction index corresponds to the move
                int directionIndex = getDirectionIndex(r, c, emptyNeighbor.r, emptyNeighbor.c);

                // Place tiles
                // The current cell (source of constraint) gets the first tile
                // The empty neighbor (destination) gets the matching tile
                maze[r][c] = TILE_MAP[directionIndex][0];
                maze[emptyNeighbor.r][emptyNeighbor.c] = TILE_MAP[directionIndex][1];

                // Update neighbors of the newly filled cell
                // Since the neighbor is now filled, its empty neighbors have one more blocked neighbor
                updateNeighbors(emptyNeighbor.r, emptyNeighbor.c, rows, cols, maze, blockedCounts, queue);
            }
        }

        // 3. Validation: Check if any empty cells remain
        boolean hasEmptyCells = false;
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (maze[r][c] == '.') {
                    hasEmptyCells = true;
                    break;
                }
            }
            if (hasEmptyCells) break;
        }

        if (hasEmptyCells) {
            System.out.println("Not unique");
        } else {
            // 4. Output result
            for (char[] row : maze) {
                System.out.println(row);
            }
        }
    }

    /**
     * Counts how many neighbors of (r, c) are not empty cells ('.').
     */
    private static int countBlockedNeighbors(int r, int c, int rows, int cols, char[][] maze) {
        int count = 0;
        for (int k = 0; k < NUM_DIRECTIONS; k++) {
            int nr = r + DX[k];
            int nc = c + DY[k];
            if (isValid(nr, nc, rows, cols) && maze[nr][nc] != '.') {
                count++;
            }
        }
        return count;
    }

    /**
     * Finds the single empty neighbor of (r, c).
     * Assumes countBlockedNeighbors is 3 (so exactly 1 empty neighbor exists).
     */
    private static Point findEmptyNeighbor(int r, int c, int rows, int cols, char[][] maze) {
        for (int k = 0; k < NUM_DIRECTIONS; k++) {
            int nr = r + DX[k];
            int nc = c + DY[k];
            if (isValid(nr, nc, rows, cols) && maze[nr][nc] == '.') {
                return new Point(nr, nc);
            }
        }
        return null;
    }

    /**
     * Updates the blocked counts for neighbors of the newly filled cell (r, c).
     */
    private static void updateNeighbors(int r, int c, int rows, int cols, char[][] maze, int[][] blockedCounts, Queue<Point> queue) {
        for (int k = 0; k < NUM_DIRECTIONS; k++) {
            int nr = r + DX[k];
            int nc = c + DY[k];
            // Check if neighbor is valid and currently empty
            if (isValid(nr, nc, rows, cols) && maze[nr][nc] == '.') {
                blockedCounts[nr][nc]++;
                if (blockedCounts[nr][nc] == BLOCKED_THRESHOLD) {
                    queue.add(new Point(nr, nc));
                }
            }
        }
    }

    /**
     * Checks if coordinates are within bounds.
     */
    private static boolean isValid(int r, int c, int rows, int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /**
     * Determines the direction index (0-3) from start (r1, c1) to end (r2, c2).
     */
    private static int getDirectionIndex(int r1, int c1, int r2, int c2) {
        for (int k = 0; k < NUM_DIRECTIONS; k++) {
            if (r1 + DX[k] == r2 && c1 + DY[k] == c2) {
                return k;
            }
        }
        return -1; // Should not happen if logic is correct
    }

    /**
     * Simple Point class to store coordinates.
     */
    private static class Point {
        int r, c;

        Point(int r, int c) {
            this.r = r;
            this.c = c;
        }
    }
}

import java.util.ArrayDeque;
import java.util.Queue;
import java.util.Scanner;

/**
 * Refactored solution for CF_515D.
 * 
 * Improvements made:
 * 1. Object-Oriented Design: Moved static state to instance fields to allow for 
 *    multiple instances and better state management.
 * 2. Readability: Renamed variables for clarity (e.g., 'field' -> 'grid', 'dir' -> 'DIRECTIONS').
 * 3. Constants: Defined direction vectors as a static final constant.
 * 4. Helper Methods: Extracted bounds checking and logic into separate methods.
 * 5. Performance: Used toCharArray() for grid parsing and StringBuilder for output.
 * 6. Safety: Added input validation and resource management.
 */
public class CF_515D {

    // Constants
    private static final int[][] DIRECTIONS = {
        {0, 1},   // Right
        {0, -1},  // Left
        {-1, 0},  // Up
        {1, 0}    // Down
    };

    // State variables
    private char[][] grid;
    private boolean[][] visited;
    private int[][] power;
    private Queue<int[]> queue;
    private int rows;
    private int cols;

    public static void main(String[] args) {
        CF_515D solver = new CF_515D();
        solver.run();
    }

    public void run() {
        Scanner scanner = new Scanner(System.in);

        // Basic input validation
        if (!scanner.hasNextInt()) {
            return;
        }

        this.rows = scanner.nextInt();
        this.cols = scanner.nextInt();

        // Initialize data structures
        this.grid = new char[rows][cols];
        this.visited = new boolean[rows][cols];
        this.power = new int[rows][cols];
        this.queue = new ArrayDeque<>();

        // Read grid input
        for (int i = 0; i < rows; i++) {
            String line = scanner.next();
            // Using toCharArray is more efficient than charAt loop
            this.grid[i] = line.toCharArray(); 
        }

        // Initialize power values for all cells
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                updatePower(i, j);
            }
        }

        // Process the queue until empty
        while (!queue.isEmpty()) {
            int[] cell = queue.poll();
            fill(cell[0], cell[1]);
        }

        // Output result
        if (isSolutionComplete()) {
            StringBuilder sb = new StringBuilder();
            for (char[] row : grid) {
                sb.append(row).append('\n');
            }
            System.out.print(sb);
        } else {
            System.out.println("Not unique");
        }
    }

    /**
     * Checks if coordinates are within grid bounds.
     */
    private boolean isValid(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /**
     * Calculates the number of empty neighbors for a cell.
     * If the cell has exactly 1 empty neighbor and hasn't been visited, 
     * it is added to the processing queue.
     */
    private void updatePower(int r, int c) {
        if (!isValid(r, c)) return;

        // If cell is not empty, it contributes 0 to power logic
        if (grid[r][c] != '.') {
            power[r][c] = 0;
            return;
        }

        int emptyNeighbors = 0;
        for (int[] d : DIRECTIONS) {
            int nr = r + d[0];
            int nc = c + d[1];
            if (isValid(nr, nc) && grid[nr][nc] == '.') {
                emptyNeighbors++;
            }
        }

        power[r][c] = emptyNeighbors;

        // If a cell has exactly one empty neighbor, it's a candidate for connection
        if (power[r][c] == 1 && !visited[r][c]) {
            queue.add(new int[]{r, c});
            visited[r][c] = true;
        }
    }

    /**
     * Connects a cell to its unique empty neighbor.
     * Updates the grid characters and propagates power updates to neighbors.
     */
    private void fill(int r, int c) {
        // Pre-checks: must be empty and have exactly 1 empty neighbor
        if (grid[r][c] != '.' || power[r][c] != 1) {
            return;
        }

        int neighborR = -1;
        int neighborC = -1;
        int dirIndex = -1;

        // Find the first valid empty neighbor
        for (int k = 0; k < DIRECTIONS.length; k++) {
            int[] d = DIRECTIONS[k];
            int nr = r + d[0];
            int nc = c + d[1];

            if (isValid(nr, nc) && grid[nr][nc] == '.') {
                neighborR = nr;
                neighborC = nc;
                dirIndex = k;
                break; // Found the unique neighbor
            }
        }

        // Safety check, though logic guarantees this shouldn't be reached if power is 1
        if (neighborR == -1) return;

        // Apply connection logic based on direction
        // Note: Preserving original arrow mapping logic
        switch (dirIndex) {
            case 0: // Right
                grid[r][c] = '<';
                grid[neighborR][neighborC] = '>';
                break;
            case 1: // Left
                grid[r][c] = '>';
                grid[neighborR][neighborC] = '<';
                break;
            case 2: // Up
                grid[r][c] = 'v';
                grid[neighborR][neighborC] = '^';
                break;
            case 3: // Down
                grid[r][c] = '^';
                grid[neighborR][neighborC] = 'v';
                break;
        }

        // Reset power for connected cells as they are no longer "empty" candidates
        power[r][c] = 0;
        power[neighborR][neighborC] = 0;

        // Update power for neighbors of the connected cell
        // This might trigger new cells to be added to the queue
        for (int[] d : DIRECTIONS) {
            updatePower(neighborR + d[0], neighborC + d[1]);
        }
    }

    /**
     * Checks if the grid is fully filled (no empty cells remain).
     */
    private boolean isSolutionComplete() {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == '.') {
                    return false;
                }
            }
        }
        return true;
    }
}

import java.io.*;
import java.util.*;

public class GridPathSolver {

    // Direction vectors for moving up, down, left, right
    private static final int[] DR = {1, -1, 0, 0};
    private static final int[] DC = {0, 0, 1, -1};

    // Character mappings for background and end states
    private static final char[] BACKGROUND = {'^', 'v', '<', '>'};
    private static final char[] END = {'v', '^', '>', '<'};

    public static void main(String[] args) {
        boolean useFiles = true;

        // Try file-based I/O first
        try (BufferedReader reader = new BufferedReader(new FileReader("input.txt"));
             PrintWriter writer = new PrintWriter(new FileWriter("output.txt"))) {
            processInput(reader, writer);
        } catch (FileNotFoundException e) {
            useFiles = false;
        } catch (IOException e) {
            e.printStackTrace();
            return;
        }

        // Fallback to standard input/output if files are unavailable
        if (!useFiles) {
            try (BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
                 PrintWriter writer = new PrintWriter(new OutputStreamWriter(System.out))) {
                processInput(reader, writer);
            } catch (IOException e) {
                e.printStackTrace();
            }
        }
    }

    /**
     * Handles parsing and delegates to the solver.
     */
    private static void processInput(BufferedReader reader, PrintWriter writer) throws IOException {
        FastReader sc = new FastReader(reader);
        int n = sc.nextInt();
        int m = sc.nextInt();

        char[][] grid = new char[n][m];
        for (int i = 0; i < n; i++) {
            grid[i] = sc.next().toCharArray();
        }

        List<String> result = solve(n, m, grid);
        for (String line : result) {
            writer.println(line);
        }
        writer.flush();
    }

    /**
     * Core algorithm: peels boundary points and verifies path uniqueness.
     */
    public static List<String> solve(int n, int m, char[][] grid) {
        Queue<Point> queue = new LinkedList<>();

        // Initialize queue with boundary points (exactly one adjacent '.')
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < m; c++) {
                if (grid[r][c] == '.' && countAdjacentDots(grid, r, c, n, m) == 1) {
                    queue.add(new Point(r, c));
                }
            }
        }

        while (!queue.isEmpty()) {
            Point p = queue.poll();
            if (grid[p.r()][p.c()] != '.') continue; // Already processed

            int adjacentCount = 0;
            int direction = -1;
            for (int d = 0; d < 4; d++) {
                int nr = p.r() + DR[d];
                int nc = p.c() + DC[d];
                if (isValid(nr, nc, n, m) && grid[nr][nc] == '.') {
                    adjacentCount++;
                    direction = d;
                }
            }

            // If a popped point doesn't have exactly one '.', the path isn't unique
            if (adjacentCount != 1) {
                return Collections.singletonList("Not unique");
            }

            int nr = p.r() + DR[direction];
            int nc = p.c() + DC[direction];

            // Update grid states
            grid[nr][nc] = END[direction];
            grid[p.r()][p.c()] = BACKGROUND[direction];

            // Check neighbors of the newly updated cell for new boundary conditions
            for (int d = 0; d < 4; d++) {
                int nnr = nr + DR[d];
                int nnc = nc + DC[d];
                if (isValid(nnr, nnc, n, m) && grid[nnr][nnc] == '.' &&
                    countAdjacentDots(grid, nnr, nnc, n, m) == 1) {
                    queue.add(new Point(nnr, nnc));
                }
            }
        }

        // Verify no '.' remains in the grid
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < m; c++) {
                if (grid[r][c] == '.') {
                    return Collections.singletonList("Not unique");
                }
            }
        }

        // Convert grid to output format
        List<String> result = new ArrayList<>(n);
        for (int r = 0; r < n; r++) {
            result.add(new String(grid[r]));
        }
        return result;
    }

    private static boolean isValid(int r, int c, int n, int m) {
        return r >= 0 && r < n && c >= 0 && c < m;
    }

    private static int countAdjacentDots(char[][] grid, int r, int c, int n, int m) {
        int count = 0;
        for (int d = 0; d < 4; d++) {
            int nr = r + DR[d];
            int nc = c + DC[d];
            if (isValid(nr, nc, n, m) && grid[nr][nc] == '.') {
                count++;
            }
        }
        return count;
    }

    /**
     * Immutable coordinate holder using modern Java record.
     */
    private record Point(int r, int c) {}

    /**
     * Fast token-based reader for competitive programming style inputs.
     */
    private static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(BufferedReader reader) {
            this.reader = reader;
        }

        public String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                String line = reader.readLine();
                if (line == null) throw new EOFException("Unexpected end of input");
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}

import java.io.*;
import java.math.BigInteger;
import java.util.*;

public class Main {
    // Direction vectors: Up, Down, Left, Right
    private static final int[][] DIRS = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};

    // Grid state
    private int rows, cols;
    private char[][] grid;
    private boolean[][] visited;
    private boolean[][] inQueue;

    public static void main(String[] args) {
        Main solver = new Main();
        solver.run();
    }

    /**
     * Entry point for execution. Handles I/O setup and exception boundaries.
     */
    private void run() {
        FastReader in = new FastReader(System.in);
        PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out));
        try {
            solve(in, out);
        } finally {
            out.flush();
        }
    }

    /**
     * Core algorithm implementation.
     */
    private void solve(FastReader in, PrintWriter out) {
        rows = in.nextInt();
        cols = in.nextInt();

        grid = new char[rows][cols];
        visited = new boolean[rows][cols];
        inQueue = new boolean[rows][cols];

        for (int i = 0; i < rows; i++) {
            String line = in.nextLine().trim();
            grid[i] = line.toCharArray();
        }

        // Initialize queue with '.' cells that have exactly one unvisited '.' neighbor
        Queue<Cell> queue = new ArrayDeque<>();
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '.' && getUnvisitedNeighborsCount(r, c) == 1) {
                    queue.add(new Cell(r, c));
                    inQueue[r][c] = true;
                }
            }
        }

        List<Cell> matchedPairs = new ArrayList<>();

        while (!queue.isEmpty()) {
            Cell current = queue.poll();
            if (visited[current.r][current.c]) {
                continue;
            }

            visited[current.r][current.c] = true;
            int unvisitedNeighbors = getUnvisitedNeighborsCount(current.r, current.c);

            if (unvisitedNeighbors == 0) {
                out.println("Not unique");
                return;
            }

            // Find the first unvisited '.' neighbor to form a pair
            Cell matched = null;
            for (int[] dir : DIRS) {
                int nr = current.r + dir[0];
                int nc = current.c + dir[1];
                if (isInside(nr, nc) && grid[nr][nc] == '.' && !visited[nr][nc]) {
                    visited[nr][nc] = true;
                    matched = new Cell(nr, nc);
                    matchedPairs.add(current);
                    matchedPairs.add(matched);
                    break;
                }
            }

            // Update queue state for both cells in the matched pair
            updateQueueForCell(current, visited, inQueue, queue);
            if (matched != null) {
                updateQueueForCell(matched, visited, inQueue, queue);
            }
        }

        // Verify all '.' cells were successfully matched
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '.' && !visited[r][c]) {
                    out.println("Not unique");
                    return;
                }
            }
        }

        // Format the output grid with directional arrows
        for (int i = 0; i < matchedPairs.size(); i += 2) {
            Cell first = matchedPairs.get(i);
            Cell second = matchedPairs.get(i + 1);

            if (first.r == second.r) {
                // Horizontal pair
                if (first.c < second.c) {
                    grid[first.r][first.c] = '<';
                    grid[first.r][second.c] = '>';
                } else {
                    grid[first.r][first.c] = '>';
                    grid[first.r][second.c] = '<';
                }
            } else {
                // Vertical pair
                if (first.r < second.r) {
                    grid[first.r][first.c] = '^';
                    grid[second.r][first.c] = 'v';
                } else {
                    grid[first.r][first.c] = 'v';
                    grid[second.r][first.c] = '^';
                }
            }
        }

        // Print the final grid
        for (int r = 0; r < rows; r++) {
            out.println(new String(grid[r]));
        }
    }

    /**
     * Checks if coordinates are within grid bounds.
     */
    private boolean isInside(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /**
     * Counts unvisited '.' neighbors for a given cell.
     */
    private int getUnvisitedNeighborsCount(int r, int c) {
        int count = 0;
        for (int[] dir : DIRS) {
            int nr = r + dir[0];
            int nc = c + dir[1];
            if (isInside(nr, nc) && grid[nr][nc] == '.' && !visited[nr][nc]) {
                count++;
            }
        }
        return count;
    }

    /**
     * Updates the queue with newly created degree-1 neighbors.
     */
    private void updateQueueForCell(Cell cell, boolean[][] visited, boolean[][] inQueue, Queue<Cell> queue) {
        for (int[] dir : DIRS) {
            int nr = cell.r + dir[0];
            int nc = cell.c + dir[1];
            if (isInside(nr, nc) && grid[nr][nc] == '.' && !visited[nr][nc] && !inQueue[nr][nc]) {
                if (getUnvisitedNeighborsCount(nr, nc) == 1) {
                    queue.add(new Cell(nr, nc));
                    inQueue[nr][nc] = true;
                }
            }
        }
    }

    /**
     * Lightweight representation of a grid coordinate.
     */
    static class Cell {
        final int r, c;
        Cell(int r, int c) {
            this.r = r;
            this.c = c;
        }
    }

    /**
     * Fast input reader for competitive programming.
     */
    static class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        FastReader(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        long nextLong() {
            return Long.parseLong(next());
        }

        String nextLine() {
            String str = "";
            try {
                str = br.readLine();
            } catch (IOException e) {
                e.printStackTrace();
            }
            return str;
        }
    }
}

/**
 * Mathematical utility class for modular arithmetic.
 */
public final class Utils {
    private Utils() {
        // Utility class, prevent instantiation
    }

    public static long binpow(long a, long exp, long mod) {
        if (exp == 0) return 1;
        if (exp % 2 == 0) {
            long temp = binpow(a, exp / 2, mod);
            return (temp * temp) % mod;
        }
        return (binpow(a, exp - 1, mod) * a) % mod;
    }

    public static long inv(long a, long mod) {
        return binpow(a, mod - 2, mod);
    }

    public static long addmod(long a, long b, long mod) {
        return ((a + b) % mod + mod) % mod;
    }

    public static long gcd(long a, long b) {
        return b == 0 ? a : gcd(b, a % b);
    }

    /**
     * Safe multiplication modulo mod. Uses BigInteger to prevent long overflow.
     */
    public static long mulmod(long a, long b, long mod) {
        return BigInteger.valueOf(a)
                         .multiply(BigInteger.valueOf(b))
                         .mod(BigInteger.valueOf(mod))
                         .longValue();
    }
}

