/**
 * Solves the grid direction assignment problem.
 * State is kept local to the solve method to ensure thread-safety and reusability.
 */
class GridDirectionSolver {
    private static final int[] DIR_ROWS = {0, 0, -1, 1};
    private static final int[] DIR_COLS = {1, -1, 0, 0};

    /** Simple immutable value object for grid coordinates */
    static class Cell {
        final int r, c;
        Cell(int r, int c) {
            this.r = r;
            this.c = c;
        }
    }

    void solve(Scanner in, PrintWriter out) {
        int n = in.nextInt();
        int m = in.nextInt();

        char[][] grid = new char[n][m];
        int[][] neighborCount = new int[n][m];
        Queue<Cell> queue = new ArrayDeque<>();

        // Read grid
        for (int i = 0; i < n; i++) {
            grid[i] = in.next().toCharArray();
        }

        // Initialize neighbor counts and seed the queue with degree-1 cells
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == '.') {
                    int count = 0;
                    for (int k = 0; k < 4; k++) {
                        int ni = i + DIR_ROWS[k];
                        int nj = j + DIR_COLS[k];
                        if (isValid(ni, nj, n, m) && grid[ni][nj] == '.') {
                            count++;
                        }
                    }
                    neighborCount[i][j] = count;
                    if (count == 1) {
                        queue.add(new Cell(i, j));
                    }
                }
            }
        }

        boolean possible = true;
        while (!queue.isEmpty()) {
            Cell cell = queue.poll();

            // If a cell in the queue has 0 valid neighbors, the solution is invalid
            if (neighborCount[cell.r][cell.c] == 0) {
                possible = false;
                break;
            }

            // Find the single valid empty neighbor
            int neighborR = -1, neighborC = -1;
            int dirIndex = -1;
            for (int k = 0; k < 4; k++) {
                int ni = cell.r + DIR_ROWS[k];
                int nj = cell.c + DIR_COLS[k];
                if (isValid(ni, nj, n, m) && grid[ni][nj] == '.') {
                    neighborR = ni;
                    neighborC = nj;
                    dirIndex = k;
                    break;
                }
            }

            if (neighborR == -1) {
                possible = false;
                break;
            }

            // Assign directional characters between the cell and its neighbor
            assignDirection(grid, cell.r, cell.c, neighborR, neighborC, dirIndex);

            // Update neighbor's degree and enqueue if it becomes a leaf
            neighborCount[neighborR][neighborC]--;
            if (neighborCount[neighborR][neighborC] == 1) {
                queue.add(new Cell(neighborR, neighborC));
            }
        }

        // Verify all cells have been assigned a direction
        if (possible) {
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    if (grid[i][j] == '.') {
                        possible = false;
                        break;
                    }
                }
                if (!possible) break;
            }
        }

        // Output result
        if (!possible) {
            out.println("Not unique");
        } else {
            for (int i = 0; i < n; i++) {
                out.println(grid[i]);
            }
        }
    }

    /** Checks if coordinates are within grid bounds */
    private boolean isValid(int r, int c, int n, int m) {
        return r >= 0 && r < n && c >= 0 && c < m;
    }

    /**
     * Assigns directional characters to two adjacent cells.
     * dirIndex: 0=Right, 1=Left, 2=Up, 3=Down
     * Characters point towards each other.
     */
    private void assignDirection(char[][] grid, int r1, int c1, int r2, int c2, int dirIndex) {
        char[] pointingChars = {'<', '>', 'v', '^'};  // Points from r1,c1 towards r2,c2
        char[] backChars     = {'>', '<', '^', 'v'};  // Points from r2,c2 back to r1,c1

        grid[r1][c1] = pointingChars[dirIndex];
        grid[r2][c2] = backChars[dirIndex];
    }
}

import java.util.ArrayDeque;
import java.util.Queue;
import java.util.Scanner;

public class GridPathSolver {
    // Direction vectors for right, left, down, up
    private static final int[] DX = {0, 0, 1, -1};
    private static final int[] DY = {1, -1, 0, 0};

    // Direction characters
    private static final char DIR_LEFT = '<';
    private static final char DIR_RIGHT = '>';
    private static final char DIR_UP = '^';
    private static final char DIR_DOWN = 'v';

    private final int rows;
    private final int cols;
    private char[][] grid;
    private final Queue<Pair> queue = new ArrayDeque<>();

    // Helper records for coordinates and paired processing
    private record Point(int row, int col) {}
    private record Pair(Point first, Point second) {}

    public GridPathSolver(Scanner scanner) {
        readInput(scanner);
        processGrid();
        printResult();
    }

    private void readInput(Scanner scanner) {
        this.rows = scanner.nextInt();
        this.cols = scanner.nextInt();
        this.grid = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            this.grid[i] = scanner.next().toCharArray();
        }
    }

    private boolean isBlocked(int r, int c) {
        return r < 0 || c < 0 || r >= rows || c >= cols || grid[r][c] != '.';
    }

    /**
     * Finds the single non-blocked neighbor of a cell.
     * Returns the neighbor if exactly one exists, otherwise null.
     */
    private Point findOpenNeighbor(int r, int c) {
        Point openNeighbor = null;
        int openCount = 0;
        for (int d = 0; d < 4; d++) {
            int nr = r + DX[d];
            int nc = c + DY[d];
            if (!isBlocked(nr, nc)) {
                openCount++;
                openNeighbor = new Point(nr, nc);
            }
        }
        return openCount == 1 ? openNeighbor : null;
    }

    /**
     * If a cell has exactly one open neighbor, adds the pair to the processing queue.
     */
    private void tryAddToQueue(int r, int c) {
        if (!isBlocked(r, c)) {
            Point neighbor = findOpenNeighbor(r, c);
            if (neighbor != null) {
                queue.add(new Pair(new Point(r, c), neighbor));
            }
        }
    }

    private void markDirection(Point p1, Point p2) {
        char dir1, dir2;
        if (p1.row() == p2.row()) {
            // Horizontal alignment
            if (p1.col() < p2.col()) {
                dir1 = DIR_LEFT;
                dir2 = DIR_RIGHT;
            } else {
                dir1 = DIR_RIGHT;
                dir2 = DIR_LEFT;
            }
        } else {
            // Vertical alignment
            if (p1.row() < p2.row()) {
                dir1 = DIR_UP;
                dir2 = DIR_DOWN;
            } else {
                dir1 = DIR_DOWN;
                dir2 = DIR_UP;
            }
        }
        grid[p1.row()][p1.col()] = dir1;
        grid[p2.row()][p2.col()] = dir2;
    }

    private void processGrid() {
        // Initial wavefront seeding
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] != '*') {
                    tryAddToQueue(i, j);
                }
            }
        }

        // Process queued pairs
        while (!queue.isEmpty()) {
            Pair pair = queue.poll();
            Point p1 = pair.first();
            Point p2 = pair.second();

            // Only process if both cells are still unmarked
            if (grid[p1.row()][p1.col()] == '.' && grid[p2.row()][p2.col()] == '.') {
                markDirection(p1, p2);

                // Propagate to neighbors to continue the wavefront
                for (int d = 0; d < 4; d++) {
                    tryAddToQueue(p1.row() + DX[d], p1.col() + DY[d]);
                    tryAddToQueue(p2.row() + DX[d], p2.col() + DY[d]);
                }
            }
        }
    }

    private void printResult() {
        boolean allFilled = true;
        outer:
        for (char[] row : grid) {
            for (char cell : row) {
                if (cell == '.') {
                    allFilled = false;
                    break outer;
                }
            }
        }

        if (allFilled) {
            for (char[] row : grid) {
                System.out.println(new String(row));
            }
        } else {
            System.out.println("Not unique");
        }
    }

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            new GridPathSolver(scanner);
        }
    }
}

