class TaskD {
    // Constants for grid characters to improve readability and maintainability
    private static final char EMPTY = '.';
    private static final char BLOCKED = '*';
    private static final char LEFT = '<';
    private static final char RIGHT = '>';
    private static final char UP = '^';
    private static final char DOWN = 'v';

    public void solve(InputReader in, OutputWriter out) {
        int rows = in.nextInt();
        int cols = in.nextInt();

        char[][] grid = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            grid[i] = in.next().toCharArray();
        }

        Queue<Pair> queue = new ArrayDeque<>();
        // Initialize queue with cells that have exactly one free neighbor
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] != BLOCKED && hasOnlyOneFreeNeighbor(grid, rows, cols, r, c)) {
                    queue.add(new Pair(r, c));
                }
            }
        }

        // Process the queue until it's empty or we hit a dead end
        while (!queue.isEmpty()) {
            Pair current = queue.poll();
            // Skip if already processed
            if (grid[current.r][current.c] != EMPTY) continue;

            Pair neighbor = findFreeNeighbor(grid, rows, cols, current);
            if (neighbor == null) break;

            assignArrows(grid, current, neighbor);

            // Check neighbors of the newly assigned cell for new candidates
            List<Pair> nextCandidates = findNextCandidates(grid, rows, cols, neighbor);
            queue.addAll(nextCandidates);
        }

        // Output result based on whether the grid is completely filled
        if (isComplete(grid, rows, cols)) {
            for (int i = 0; i < rows; i++) {
                out.printLine(new String(grid[i]));
            }
        } else {
            out.printLine("Not unique");
        }
    }

    private List<Pair> findNextCandidates(char[][] grid, int rows, int cols, Pair cell) {
        List<Pair> candidates = new ArrayList<>();
        int[] dr = {-1, 1, 0, 0};
        int[] dc = {0, 0, -1, 1};

        for (int d = 0; d < 4; d++) {
            int r = cell.r + dr[d];
            int c = cell.c + dc[d];
            if (isWithinBounds(rows, cols, r, c) && hasOnlyOneFreeNeighbor(grid, rows, cols, r, c)) {
                candidates.add(new Pair(r, c));
            }
        }
        return candidates;
    }

    private boolean isComplete(char[][] grid, int rows, int cols) {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == EMPTY) return false;
            }
        }
        return true;
    }

    private void assignArrows(char[][] grid, Pair p1, Pair p2) {
        if (p1.r == p2.r) {
            // Horizontal relationship
            if (p1.c < p2.c) {
                grid[p1.r][p1.c] = LEFT;
                grid[p2.r][p2.c] = RIGHT;
            } else {
                grid[p1.r][p1.c] = RIGHT;
                grid[p2.r][p2.c] = LEFT;
            }
        } else {
            // Vertical relationship
            if (p1.r < p2.r) {
                grid[p1.r][p1.c] = UP;
                grid[p2.r][p2.c] = DOWN;
            } else {
                grid[p1.r][p1.c] = DOWN;
                grid[p2.r][p2.c] = UP;
            }
        }
    }

    private Pair findFreeNeighbor(char[][] grid, int rows, int cols, Pair cell) {
        if (isFree(grid, rows, cols, cell.r - 1, cell.c)) return new Pair(cell.r - 1, cell.c);
        if (isFree(grid, rows, cols, cell.r + 1, cell.c)) return new Pair(cell.r + 1, cell.c);
        if (isFree(grid, rows, cols, cell.r, cell.c - 1)) return new Pair(cell.r, cell.c - 1);
        if (isFree(grid, rows, cols, cell.r, cell.c + 1)) return new Pair(cell.r, cell.c + 1);
        return null;
    }

    private boolean hasOnlyOneFreeNeighbor(char[][] grid, int rows, int cols, int r, int c) {
        if (!isWithinBounds(rows, cols, r, c)) return false;
        int freeCount = 0;
        freeCount += isFree(grid, rows, cols, r - 1, c) ? 1 : 0;
        freeCount += isFree(grid, rows, cols, r + 1, c) ? 1 : 0;
        freeCount += isFree(grid, rows, cols, r, c - 1) ? 1 : 0;
        freeCount += isFree(grid, rows, cols, r, c + 1) ? 1 : 0;
        return freeCount == 1;
    }

    private boolean isFree(char[][] grid, int rows, int cols, int r, int c) {
        return isWithinBounds(rows, cols, r, c) && grid[r][c] == EMPTY;
    }

    private boolean isWithinBounds(int rows, int cols, int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    // Immutable coordinate pair
    private static class Pair {
        final int r, c;

        Pair(int r, int c) {
            this.r = r;
            this.c = c;
        }
    }
}

