import java.io.BufferedWriter;
import java.io.IOException;
import java.io.InputStream;
import java.io.OutputStream;
import java.io.OutputStreamWriter;
import java.io.PrintWriter;
import java.io.Writer;
import java.util.ArrayDeque;
import java.util.InputMismatchException;
import java.util.Queue;

public class Main {
    public static void main(String[] args) {
        InputReader in = new InputReader(System.in);
        OutputWriter out = new OutputWriter(System.out);
        new GridPatternSolver().solve(in, out);
        out.close();
    }

    /**
     * Solves the grid pattern problem by iteratively filling empty cells
     * that have exactly one empty neighbor (topological peeling approach).
     */
    static class GridPatternSolver {
        private static final char EMPTY = '.';
        private static final String[] COLORS = {"v^", "<>", "^v", "><"};
        private static final int[] DX = {-1, 0, 1, 0};
        private static final int[] DY = {0, 1, 0, -1};

        public void solve(InputReader in, OutputWriter out) {
            int n = in.readInt();
            int m = in.readInt();
            char[][] field = new char[n][m];

            // Read grid
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    field[i][j] = in.readCharacter();
                }
            }

            // Initialize queue with empty cells having exactly one empty neighbor
            Queue<Point> queue = new ArrayDeque<>();
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    if (field[i][j] == EMPTY && getDegree(field, i, j, n, m) == 1) {
                        queue.add(new Point(i, j));
                    }
                }
            }

            // Process queue (topological peeling)
            while (!queue.isEmpty()) {
                Point cur = queue.poll();
                int r = cur.row;
                int c = cur.col;

                for (int d = 0; d < 4; d++) {
                    int nr = r + DX[d];
                    int nc = c + DY[d];

                    if (isInside(nr, nc, n, m) && field[nr][nc] == EMPTY) {
                        fill(field, r, c, d);
                        // Check neighbors of both the current cell and the newly filled cell
                        checkAndEnqueueIfDegreeOne(field, r, c, n, m, queue);
                        checkAndEnqueueIfDegreeOne(field, nr, nc, n, m, queue);
                    }
                }
            }

            // Verify all cells are filled
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    if (field[i][j] == EMPTY) {
                        out.print("Not unique");
                        return;
                    }
                }
            }

            // Output result
            for (char[] row : field) {
                out.printLine(row);
            }
        }

        private void fill(char[][] field, int r, int c, int direction) {
            String color = COLORS[direction];
            field[r][c] = color.charAt(0);
            field[r + DX[direction]][c + DY[direction]] = color.charAt(1);
        }

        private int getDegree(char[][] field, int r, int c, int n, int m) {
            int degree = 0;
            for (int d = 0; d < 4; d++) {
                int nr = r + DX[d];
                int nc = c + DY[d];
                if (isInside(nr, nc, n, m) && field[nr][nc] == EMPTY) {
                    degree++;
                }
            }
            return degree;
        }

        private void checkAndEnqueueIfDegreeOne(char[][] field, int r, int c, int n, int m, Queue<Point> queue) {
            for (int d = 0; d < 4; d++) {
                int nr = r + DX[d];
                int nc = c + DY[d];
                if (isInside(nr, nc, n, m) && field[nr][nc] == EMPTY && getDegree(field, nr, nc, n, m) == 1) {
                    queue.add(new Point(nr, nc));
                }
            }
        }

        private boolean isInside(int r, int c, int n, int m) {
            return r >= 0 && r < n && c >= 0 && c < m;
        }
    }

    /**
     * Immutable point class representing grid coordinates.
     */
    static class Point {
        final int row;
        final int col;

        Point(int row, int col) {
            this.row = row;
            this.col = col;
        }

        @Override
        public boolean equals(Object o) {
            if (this == o) return true;
            if (!(o instanceof Point)) return false;
            Point point = (Point) o;
            return row == point.row && col == point.col;
        }

        @Override
        public int hashCode() {
            return 31 * row + col;
        }

        @Override
        public String toString() {
            return "(" + row + "," + col + ")";
        }
    }

    /**
     * Fast input reader optimized for competitive programming.
     */
    static class InputReader {
        private final InputStream stream;
        private final byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        public int read() {
            if (numChars == -1) {
                throw new InputMismatchException();
            }
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0) {
                    return -1;
                }
            }
            return buf[curChar++];
        }

        public int readInt() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                res *= 10;
                res += c - '0';
                c = read();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public char readCharacter() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            return (char) c;
        }

        public boolean isSpaceChar(int c) {
            return isWhitespace(c);
        }

        public static boolean isWhitespace(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }
    }

    /**
     * Buffered output writer for competitive programming.
     */
    static class OutputWriter {
        private final PrintWriter writer;

        public OutputWriter(OutputStream outputStream) {
            this.writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(outputStream)));
        }

        public OutputWriter(Writer writer) {
            this.writer = new PrintWriter(writer);
        }

        public void print(Object... objects) {
            for (int i = 0; i < objects.length; i++) {
                if (i != 0) {
                    writer.print(' ');
                }
                writer.print(objects[i]);
            }
        }

        public void printLine(char[] array) {
            writer.println(array);
        }

        public void close() {
            writer.close();
        }
    }
}

