/**
 * Solves the grid pairing problem by processing leaf nodes (degree 1)
 * and pairing them with their neighbors until all empty cells are covered.
 */
class GridPairingSolver {
    // Direction vectors for right, down, left, up
    private static final int[] DX = {0, 1, 0, -1};
    private static final int[] DY = {1, 0, -1, 0};

    private static final char DIR_LEFT = '<';
    private static final char DIR_RIGHT = '>';
    private static final char DIR_UP = '^';
    private static final char DIR_DOWN = 'v';

    private static final String RESULT_NOT_UNIQUE = "Not unique";

    /**
     * Entry point for solving a single test case.
     */
    public void solve(InputReader in, PrintWriter out) {
        int n = in.nextInt();
        int m = in.nextInt();

        // Padding with +2 simplifies boundary checks
        char[][] grid = new char[n + 2][m + 2];
        int[][] degree = new int[n + 2][m + 2];
        int remainingEmptyCells = 0;

        // Read grid input
        for (int i = 1; i <= n; i++) {
            String row = in.next();
            for (int j = 1; j <= m; j++) {
                grid[i][j] = row.charAt(j - 1);
            }
        }

        // Queue for BFS/Topological leaf-peeling processing
        Queue<Cell> queue = new ArrayDeque<>();

        // Initialize degrees and populate queue with leaf nodes (degree == 1)
        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= m; j++) {
                if (grid[i][j] == '.') {
                    remainingEmptyCells++;
                    int adjCount = 0;
                    for (int k = 0; k < 4; k++) {
                        int nx = i + DX[k];
                        int ny = j + DY[k];
                        if (grid[nx][ny] == '.') {
                            adjCount++;
                        }
                    }
                    degree[i][j] = adjCount;
                    if (adjCount == 1) {
                        queue.add(new Cell(i, j));
                    }
                }
            }
        }

        // Process the queue
        while (!queue.isEmpty()) {
            Cell leaf = queue.poll();

            // Skip if already covered by a previous pairing
            if (grid[leaf.x][leaf.y] != '.') {
                continue;
            }

            Cell neighbor = findAdjacentEmptyCell(leaf, grid);
            if (neighbor == null) {
                out.println(RESULT_NOT_UNIQUE);
                return;
            }

            applyPairingDirections(grid, leaf, neighbor);
            degree[leaf.x][leaf.y] = 0;
            degree[neighbor.x][neighbor.y] = 0;
            remainingEmptyCells -= 2;

            // Update degrees for neighbors of the paired cell
            for (int k = 0; k < 4; k++) {
                int nx = neighbor.x + DX[k];
                int ny = neighbor.y + DY[k];
                if (grid[nx][ny] == '.' && degree[nx][ny] > 0) {
                    degree[nx][ny]--;
                    if (degree[nx][ny] == 1) {
                        queue.add(new Cell(nx, ny));
                    }
                }
            }
        }

        // Output result
        if (remainingEmptyCells > 0) {
            out.println(RESULT_NOT_UNIQUE);
        } else {
            for (int i = 1; i <= n; i++) {
                out.println(new String(grid[i], 1, m));
            }
        }
    }

    private Cell findAdjacentEmptyCell(Cell cell, char[][] grid) {
        for (int k = 0; k < 4; k++) {
            int nx = cell.x + DX[k];
            int ny = cell.y + DY[k];
            if (grid[nx][ny] == '.') {
                return new Cell(nx, ny);
            }
        }
        return null;
    }

    private void applyPairingDirections(char[][] grid, Cell a, Cell b) {
        if (a.x == b.x) {
            grid[a.x][Math.min(a.y, b.y)] = DIR_LEFT;
            grid[a.x][Math.max(a.y, b.y)] = DIR_RIGHT;
        } else {
            grid[Math.min(a.x, b.x)][a.y] = DIR_UP;
            grid[Math.max(a.x, b.x)][b.y] = DIR_DOWN;
        }
    }

    /**
     * Immutable value class representing a grid coordinate.
     */
    private static class Cell {
        final int x;
        final int y;

        Cell(int x, int y) {
            this.x = x;
            this.y = y;
        }
    }
}

