import java.io.*;
import java.util.*;

/**
 * Solves a grid-based pathfinding/puzzle problem by propagating constraints
 * from endpoint cells (cells with exactly one adjacent '.') until the grid
 * is fully resolved or determined to be non-unique.
 * 
 * Refactoring highlights:
 * - Applied standard Java naming conventions (PascalCase for classes, camelCase for members)
 * - Removed dead code (unused methods: gcd, isPrime, ok, razl, Pair, etc.)
 * - Encapsulated I/O in a dedicated FastScanner class
 * - Fixed resource management (proper flush/close, removed System.exit)
 * - Simplified complex grid traversal logic into single-responsibility methods
 * - Eliminated magic numbers and hardcoded state that wasn't reset between runs
 * - Improved readability and maintainability while preserving original algorithm
 */
public class Solver implements Runnable {

    private final boolean isOnlineJudge;
    private final FastScanner in;
    private final PrintWriter out;

    // Grid state
    private int n, m;
    private char[][] grid;
    private int[][] neighborCounts;
    private boolean[][] inQueue;
    private final ArrayDeque<Integer> queueX = new ArrayDeque<>();
    private final ArrayDeque<Integer> queueY = new ArrayDeque<>();
    private final int[] dx = {-1, 1, 0, 0};
    private final int[] dy = {0, 0, 1, -1};

    public Solver() {
        this.isOnlineJudge = System.getProperty("ONLINE_JUDGE") != null;
        this.in = new FastScanner();
        this.out = new PrintWriter(System.out);
    }

    @Override
    public void run() {
        long startTime = System.currentTimeMillis();
        try {
            if (!isOnlineJudge) {
                in.setFile("input.txt");
                out.setFile("output.txt");
            }
            solve();
        } catch (Exception e) {
            e.printStackTrace(System.err);
            System.exit(-1);
        } finally {
            out.flush();
            long endTime = System.currentTimeMillis();
            if (!isOnlineJudge) {
                System.err.println("Time = " + (endTime - startTime));
            }
        }
    }

    private void solve() throws IOException {
        n = in.nextInt();
        m = in.nextInt();

        grid = new char[n][];
        neighborCounts = new int[n][m];
        inQueue = new boolean[n][m];

        for (int i = 0; i < n; i++) {
            grid[i] = in.next().toCharArray();
        }

        initializeNeighborCounts();
        processQueue();
        printResult();
    }

    /**
     * Scans the grid, counts adjacent '.' cells for each, 
     * and seeds the processing queue with endpoint cells (count == 1).
     */
    private void initializeNeighborCounts() {
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == '.') {
                    int count = countAdjacentDots(i, j);
                    neighborCounts[i][j] = count;
                    if (count == 1) {
                        queueX.add(i);
                        queueY.add(j);
                        inQueue[i][j] = true;
                    }
                }
            }
        }
    }

    private void processQueue() {
        while (!queueX.isEmpty()) {
            int x = queueX.pollFirst();
            int y = queueY.pollFirst();
            resolveCell(x, y);
        }
    }

    /**
     * Resolves a cell that has exactly one valid '.' neighbor.
     * Places directional arrows and propagates updates to affected neighbors.
     */
    private void resolveCell(int x, int y) {
        if (!isValid(x, y) || grid[x][y] != '.' || neighborCounts[x][y] == 0) {
            return;
        }

        int neighborX = -1, neighborY = -1;
        for (int d = 0; d < 4; d++) {
            int nx = x + dx[d];
            int ny = y + dy[d];
            if (isValid(nx, ny) && grid[nx][ny] == '.') {
                neighborX = nx;
                neighborY = ny;
                break;
            }
        }

        if (neighborX == -1) return;

        // Determine directional arrows based on relative position
        char arrowFromCurrent, arrowToNeighbor;
        if (neighborY == y + 1) {      // Right
            arrowFromCurrent = '<'; arrowToNeighbor = '>';
        } else if (neighborY == y - 1) { // Left
            arrowFromCurrent = '>'; arrowToNeighbor = '<';
        } else if (neighborX == x + 1) { // Down
            arrowFromCurrent = '^'; arrowToNeighbor = 'v';
        } else {                         // Up
            arrowFromCurrent = 'v'; arrowToNeighbor = '^';
        }

        grid[x][y] = arrowFromCurrent;
        grid[neighborX][neighborY] = arrowToNeighbor;

        // Recalculate neighbor counts for all adjacent cells of both modified cells
        updateAffectedNeighbors(x, y);
        updateAffectedNeighbors(neighborX, neighborY);
    }

    private void updateAffectedNeighbors(int x, int y) {
        for (int d = 0; d < 4; d++) {
            int ni = x + dx[d];
            int nj = y + dy[d];
            if (isValid(ni, nj) && grid[ni][nj] == '.') {
                recalculateAndEnqueueIfNeeded(ni, nj);
            }
        }
    }

    private void recalculateAndEnqueueIfNeeded(int x, int y) {
        int count = countAdjacentDots(x, y);
        neighborCounts[x][y] = count;
        if (count == 1 && !inQueue[x][y]) {
            queueX.add(x);
            queueY.add(y);
            inQueue[x][y] = true;
        }
    }

    private int countAdjacentDots(int x, int y) {
        int count = 0;
        for (int d = 0; d < 4; d++) {
            int ni = x + dx[d];
            int nj = y + dy[d];
            if (isValid(ni, nj) && grid[ni][nj] == '.') {
                count++;
            }
        }
        return count;
    }

    private boolean isValid(int x, int y) {
        return x >= 0 && x < n && y >= 0 && y < m;
    }

    private void printResult() {
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == '.') {
                    out.println("Not unique");
                    return;
                }
            }
        }
        for (int i = 0; i < n; i++) {
            out.println(new String(grid[i]));
        }
    }

    /**
     * Fast input reader optimized for competitive programming.
     */
    static class FastScanner {
        private BufferedReader br;
        private StringTokenizer st;

        FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        void setFile(String path) {
            try {
                br = new BufferedReader(new FileReader(path));
            } catch (IOException e) {
                e.printStackTrace();
            }
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input", e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            String token = next();
            if (token == null) throw new NoSuchElementException("End of input");
            return Integer.parseInt(token);
        }
    }

    public static void main(String[] args) {
        // Allocate sufficient stack space for deep recursion if needed
        new Thread(null, new Solver(), "Solver", 256 * (1L << 20)).start();
    }
}

import java.util.LinkedList;
import java.util.Queue;
import java.util.Scanner;

public class GridSimulation {
    // Constants for grid characters
    private static final char EMPTY = '.';
    private static final char DIR_DOWN = 'v';
    private static final char DIR_UP = '^';
    private static final char DIR_RIGHT = '>';
    private static final char DIR_LEFT = '<';

    // Instance state
    private int rows;
    private int cols;
    private char[][] grid;
    private int[][] emptyNeighborCounts;
    private Queue<Coordinate> currentWave;

    /**
     * Simple immutable coordinate holder.
     */
    private static class Coordinate {
        final int r;
        final int c;

        Coordinate(int r, int c) {
            this.r = r;
            this.c = c;
        }
    }

    public static void main(String[] args) {
        GridSimulation solver = new GridSimulation();
        solver.run();
    }

    /**
     * Orchestrates the simulation pipeline.
     */
    private void run() {
        readInput();
        initialize();
        simulate();
        printResult();
    }

    /**
     * Reads grid dimensions and initial state from standard input.
     */
    private void readInput() {
        Scanner scanner = new Scanner(System.in);
        rows = scanner.nextInt();
        cols = scanner.nextInt();
        scanner.nextLine(); // consume the newline after cols

        grid = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            String line = scanner.nextLine();
            for (int j = 0; j < cols; j++) {
                grid[i][j] = line.charAt(j);
            }
        }
    }

    /**
     * Initializes neighbor counts and populates the first processing wave.
     */
    private void initialize() {
        emptyNeighborCounts = new int[rows][cols];
        currentWave = new LinkedList<>();

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                updateEmptyNeighborCounts(r, c, currentWave);
            }
        }
    }

    /**
     * Calculates the number of empty neighbors for a cell.
     * If exactly one empty neighbor exists, adds the coordinate to the processing queue.
     */
    private void updateEmptyNeighborCounts(int r, int c, Queue<Coordinate> nextWave) {
        if (!isInside(r, c)) {
            return;
        }

        int count = 0;
        if (isInside(r - 1, c) && grid[r - 1][c] == EMPTY) count++;
        if (isInside(r + 1, c) && grid[r + 1][c] == EMPTY) count++;
        if (isInside(r, c - 1) && grid[r][c - 1] == EMPTY) count++;
        if (isInside(r, c + 1) && grid[r][c + 1] == EMPTY) count++;

        emptyNeighborCounts[r][c] = count;

        if (count == 1 && grid[r][c] == EMPTY) {
            nextWave.add(new Coordinate(r, c));
        }
    }

    /**
     * Checks if coordinates are within grid boundaries.
     */
    private boolean isInside(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /**
     * Runs the wave-based simulation until no more cells can be processed.
     */
    private void simulate() {
        while (!currentWave.isEmpty()) {
            Queue<Coordinate> nextWave = new LinkedList<>();

            for (Coordinate coord : currentWave) {
                if (grid[coord.r][coord.c] != EMPTY) {
                    continue;
                }

                int r = coord.r;
                int c = coord.c;

                // Check UP
                if (r > 0 && grid[r - 1][c] == EMPTY) {
                    grid[r][c] = DIR_UP;
                    grid[r - 1][c] = DIR_DOWN;
                    updateEmptyNeighborCounts(r - 2, c, nextWave);
                    updateEmptyNeighborCounts(r - 1, c - 1, nextWave);
                    updateEmptyNeighborCounts(r - 1, c + 1, nextWave);
                }
                // Check DOWN
                if (r < rows - 1 && grid[r + 1][c] == EMPTY) {
                    grid[r][c] = DIR_DOWN;
                    grid[r + 1][c] = DIR_UP;
                    updateEmptyNeighborCounts(r + 2, c, nextWave);
                    updateEmptyNeighborCounts(r + 1, c - 1, nextWave);
                    updateEmptyNeighborCounts(r + 1, c + 1, nextWave);
                }
                // Check LEFT
                if (c > 0 && grid[r][c - 1] == EMPTY) {
                    grid[r][c] = DIR_RIGHT;
                    grid[r][c - 1] = DIR_LEFT;
                    updateEmptyNeighborCounts(r, c - 2, nextWave);
                    updateEmptyNeighborCounts(r - 1, c - 1, nextWave);
                    updateEmptyNeighborCounts(r + 1, c - 1, nextWave);
                }
                // Check RIGHT
                if (c < cols - 1 && grid[r][c + 1] == EMPTY) {
                    grid[r][c] = DIR_LEFT;
                    grid[r][c + 1] = DIR_RIGHT;
                    updateEmptyNeighborCounts(r, c + 2, nextWave);
                    updateEmptyNeighborCounts(r - 1, c + 1, nextWave);
                    updateEmptyNeighborCounts(r + 1, c + 1, nextWave);
                }
            }
            currentWave = nextWave;
        }
    }

    /**
     * Outputs the result: "Not unique" if empty cells remain, otherwise prints the grid.
     */
    private void printResult() {
        boolean hasEmpty = false;
        outerLoop:
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == EMPTY) {
                    hasEmpty = true;
                    break outerLoop;
                }
            }
        }

        if (hasEmpty) {
            System.out.println("Not unique");
        } else {
            StringBuilder sb = new StringBuilder();
            for (int r = 0; r < rows; r++) {
                sb.append(grid[r]);
                sb.append('\n');
            }
            System.out.println(sb.toString());
        }
    }
}

