class TaskD {
    private static final char OCCUPIED = 'x';
    private static final char PIECE = 'o';
    private static final char EMPTY = '.';

    public void solve(int testNumber, FastScanner in, PrintWriter out) {
        int n = in.nextInt();
        char[][] board = readBoard(in, n);
        char[][] resultGrid = initializeResultGrid(n);
        char[][] transformedBoard = copyBoard(board);

        findAndApplyValidShifts(board, transformedBoard, resultGrid, n);

        if (areBoardsEqual(board, transformedBoard)) {
            printSuccess(resultGrid, n, out);
        } else {
            printFailure(out);
        }
    }

    private char[][] readBoard(FastScanner in, int n) {
        char[][] board = new char[n][];
        for (int i = 0; i < n; i++) {
            board[i] = in.next().toCharArray();
        }
        return board;
    }

    private char[][] initializeResultGrid(int n) {
        int size = 2 * n - 1;
        char[][] grid = new char[size][size];
        for (char[] row : grid) {
            Arrays.fill(row, EMPTY);
        }
        grid[n - 1][n - 1] = PIECE;
        return grid;
    }

    private char[][] copyBoard(char[][] source) {
        char[][] copy = new char[source.length][];
        for (int i = 0; i < source.length; i++) {
            copy[i] = Arrays.copyOf(source[i], source[i].length);
        }
        return copy;
    }

    private void findAndApplyValidShifts(char[][] board, char[][] transformed, char[][] resultGrid, int n) {
        int offset = n - 1;
        for (int dx = -(n - 1); dx <= n - 1; dx++) {
            for (int dy = -(n - 1); dy <= n - 1; dy++) {
                if (dx == 0 && dy == 0) continue;

                if (isValidShift(board, dx, dy)) {
                    resultGrid[offset + dx][offset + dy] = OCCUPIED;
                    applyShift(transformed, dx, dy, n);
                }
            }
        }
    }

    private void applyShift(char[][] grid, int dx, int dy, int n) {
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == PIECE) {
                    int ni = i + dx;
                    int nj = j + dy;
                    if (isWithinBounds(n, ni, nj) && grid[ni][nj] == EMPTY) {
                        grid[ni][nj] = OCCUPIED;
                    }
                }
            }
        }
    }

    private boolean isValidShift(char[][] board, int dx, int dy) {
        int n = board.length;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (board[i][j] == PIECE) {
                    int ni = i + dx;
                    int nj = j + dy;
                    if (isWithinBounds(n, ni, nj) && board[ni][nj] == EMPTY) {
                        return false;
                    }
                } else if (board[i][j] == EMPTY) {
                    int ni = i - dx;
                    int nj = j - dy;
                    if (isWithinBounds(n, ni, nj) && board[ni][nj] == PIECE) {
                        return false;
                    }
                }
            }
        }
        return true;
    }

    private boolean isWithinBounds(int n, int x, int y) {
        return x >= 0 && x < n && y >= 0 && y < n;
    }

    private boolean areBoardsEqual(char[][] a, char[][] b) {
        for (int i = 0; i < a.length; i++) {
            if (!Arrays.equals(a[i], b[i])) {
                return false;
            }
        }
        return true;
    }

    private void printSuccess(char[][] grid, int n, PrintWriter out) {
        out.println("YES");
        for (int i = 0; i < 2 * n - 1; i++) {
            out.println(new String(grid[i]));
        }
    }

    private void printFailure(PrintWriter out) {
        out.println("NO");
    }
}

