import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.StringTokenizer;

/**
 * Solves a grid-based reachability/attack validation problem.
 * 
 * Algorithm Overview:
 * 1. Parse the input grid and mark occupied cells ('x' or 'o').
 * 2. Compute a validity map for relative offsets from a piece. An offset is invalid
 *    if any piece can see an empty cell ('.') at that relative distance.
 * 3. Compute which cells are reachable by pieces using only valid offsets.
 * 4. Validate that reachable cells exactly match the originally occupied cells.
 * 5. Output "YES"/"NO" and the offset validity grid.
 */
public class Solution {

    /** Fast input reader for competitive programming scenarios. */
    private static final class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input", e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        long nextLong() {
            return Long.parseLong(next());
        }
    }

    private final FastScanner in;
    private final PrintWriter out;

    public Solution() {
        in = new FastScanner();
        out = new PrintWriter(System.out);
    }

    public static void main(String[] args) {
        try (Solution solver = new Solution()) {
            solver.run();
        }
    }

    /** Orchestrates the solution execution and ensures output is flushed/closed. */
    void run() {
        try {
            solve();
        } catch (Exception e) {
            // In CP contexts, we typically propagate unexpected errors.
            throw new RuntimeException("Unexpected error during solve", e);
        } finally {
            out.close();
        }
    }

    private void solve() {
        int gridSize = in.nextInt();
        boolean[][] isOccupied = new boolean[gridSize][gridSize];
        ArrayList<int[]> piecePositions = new ArrayList<>();

        // 1. Parse input grid
        for (int i = 0; i < gridSize; i++) {
            String row = in.next();
            for (int j = 0; j < gridSize; j++) {
                char ch = row.charAt(j);
                if (ch == 'x' || ch == 'o') {
                    isOccupied[i][j] = true;
                    if (ch == 'o') {
                        piecePositions.add(new int[]{i, j});
                    }
                }
            }
        }

        // 2. Compute offset validity map
        // Size is (2n-1) x (2n-1) to accommodate negative and positive relative offsets.
        // Index mapping: offset + gridSize - 1
        int offsetSize = 2 * gridSize - 1;
        boolean[][] offsetValidity = new boolean[offsetSize][offsetSize];

        // Initially assume all offsets are valid except the piece's own position (0,0)
        for (int i = 0; i < offsetSize; i++) {
            Arrays.fill(offsetValidity[i], true);
        }
        offsetValidity[gridSize - 1][gridSize - 1] = false;

        // Mark invalid offsets: if a piece can see a '.' cell at relative offset (dr, dc),
        // that offset is globally invalid.
        for (int[] piece : piecePositions) {
            markInvalidOffsets(piece[0], piece[1], gridSize, isOccupied, offsetValidity);
        }

        // 3. Compute reachable cells using only valid offsets
        boolean[][] reachableCells = new boolean[gridSize][gridSize];
        for (int[] piece : piecePositions) {
            markReachableCells(piece[0], piece[1], gridSize, offsetValidity, reachableCells);
        }

        // 4. Validate: reachable cells must exactly match occupied cells
        for (int i = 0; i < gridSize; i++) {
            for (int j = 0; j < gridSize; j++) {
                if (reachableCells[i][j] != isOccupied[i][j]) {
                    out.println("NO");
                    return;
                }
            }
        }

        // 5. Output result
        out.println("YES");
        printOffsetGrid(offsetValidity, gridSize);
    }

    /**
     * Marks relative offsets as invalid if a piece at (pieceRow, pieceCol) 
     * can see an empty cell ('.') at that offset.
     */
    private void markInvalidOffsets(int pieceRow, int pieceCol, int gridSize,
                                    boolean[][] isOccupied, boolean[][] offsetValidity) {
        int centerOffset = gridSize - 1;
        // Offsets range from -(gridSize-1) to (gridSize-1)
        for (int dr = 1 - gridSize; dr <= gridSize - 1; dr++) {
            for (int dc = 1 - gridSize; dc <= gridSize - 1; dc++) {
                int targetRow = pieceRow + dr;
                int targetCol = pieceCol + dc;

                if (targetRow >= 0 && targetCol >= 0 && targetRow < gridSize && targetCol < gridSize) {
                    if (!isOccupied[targetRow][targetCol]) {
                        offsetValidity[dr + centerOffset][dc + centerOffset] = false;
                    }
                }
            }
        }
    }

    /**
     * Marks cells as reachable if a piece at (pieceRow, pieceCol) 
     * can reach them using a valid offset or its own position.
     */
    private void markReachableCells(int pieceRow, int pieceCol, int gridSize,
                                    boolean[][] offsetValidity, boolean[][] reachableCells) {
        int centerOffset = gridSize - 1;
        for (int dr = 1 - gridSize; dr <= gridSize - 1; dr++) {
            for (int dc = 1 - gridSize; dc <= gridSize - 1; dc++) {
                int targetRow = pieceRow + dr;
                int targetCol = pieceCol + dc;

                if (targetRow >= 0 && targetCol >= 0 && targetRow < gridSize && targetCol < gridSize) {
                    boolean isValidOffset = offsetValidity[dr + centerOffset][dc + centerOffset];
                    boolean isOwnPosition = (dr == 0 && dc == 0);

                    if (isValidOffset || isOwnPosition) {
                        reachableCells[targetRow][targetCol] = true;
                    }
                }
            }
        }
    }

    /**
     * Prints the offset validity grid to output.
     * Center cell is 'o', valid offsets are 'x', invalid are '.'
     */
    private void printOffsetGrid(boolean[][] offsetValidity, int gridSize) {
        int centerOffset = gridSize - 1;
        int offsetSize = offsetValidity.length;

        for (int r = 0; r < offsetSize; r++) {
            for (int c = 0; c < offsetSize; c++) {
                if (r == centerOffset && c == centerOffset) {
                    out.print("o");
                } else if (offsetValidity[r][c]) {
                    out.print("x");
                } else {
                    out.print(".");
                }
            }
            out.println();
        }
    }
}

import java.util.Scanner;

/**
 * Solves a grid-based piece movement coverage problem.
 * Reads an n x n grid, calculates possible moves for each piece,
 * merges them, verifies coverage of empty cells, and prints the result.
 */
public class GridPieceSolver {

    // Values relative to the baseline character 'x' for arithmetic comparison
    private static final int PIECE_VALUE = 'o' - 'x';
    private static final int EMPTY_VALUE = '.' - 'x';

    private final int n;
    private final int[][] board;

    public GridPieceSolver(int n, int[][] board) {
        this.n = n;
        this.board = board;
    }

    public static void main(String[] args) {
        // Use try-with-resources to ensure Scanner is properly closed
        try (Scanner scanner = new Scanner(System.in)) {
            if (!scanner.hasNextInt()) {
                return;
            }
            int n = scanner.nextInt();
            // Create a padded board to simplify boundary checks
            int[][] board = new int[3 * n][3 * n];

            // Read the n x n grid and place it in the center of the padded board
            for (int row = 0; row < n; row++) {
                String line = scanner.next();
                for (int col = 0; col < n; col++) {
                    board[n + row][n + col] = line.charAt(col) - 'x';
                }
            }

            GridPieceSolver solver = new GridPieceSolver(n, board);
            solver.solve();
        }
    }

    private void solve() {
        boolean[][] combinedMoves = new boolean[2 * n - 1][2 * n - 1];

        // Calculate and merge possible moves for each piece
        for (int row = 0; row < n; row++) {
            for (int col = 0; col < n; col++) {
                int gridRow = n + row;
                int gridCol = n + col;

                if (board[gridRow][gridCol] == PIECE_VALUE) {
                    boolean[][] pieceMoves = calculateMoves(board, n, gridRow, gridCol);
                    mergeMoves(combinedMoves, pieceMoves);
                }
            }
        }

        // Apply moves to determine coverage
        int[][] coverageGrid = new int[3 * n][3 * n];
        for (int row = 0; row < n; row++) {
            for (int col = 0; col < n; col++) {
                int gridRow = n + row;
                int gridCol = n + col;

                if (board[gridRow][gridCol] == PIECE_VALUE) {
                    applyMoves(combinedMoves, coverageGrid, row, col);
                }
            }
        }

        // Verify all originally empty cells are covered
        for (int row = 0; row < n; row++) {
            for (int col = 0; col < n; col++) {
                int gridRow = n + row;
                int gridCol = n + col;

                if (board[gridRow][gridCol] == EMPTY_VALUE) {
                    if (coverageGrid[gridRow][gridCol] != 1) {
                        System.out.println("NO");
                        return;
                    }
                }
            }
        }

        System.out.println("YES");
        printMoves(combinedMoves);
    }

    /**
     * Calculates possible moves for a piece at (centerRow, centerCol).
     * Returns a (2n-1)x(2n-1) boolean grid where true indicates an empty cell.
     */
    private boolean[][] calculateMoves(int[][] board, int n, int centerRow, int centerCol) {
        boolean[][] moves = new boolean[2 * n - 1][2 * n - 1];
        for (int rowOffset = -n + 1; rowOffset < n; rowOffset++) {
            for (int colOffset = -n + 1; colOffset < n; colOffset++) {
                int targetRow = centerRow + rowOffset;
                int targetCol = centerCol + colOffset;
                int mappedRow = rowOffset + n - 1;
                int mappedCol = colOffset + n - 1;
                moves[mappedRow][mappedCol] = (board[targetRow][targetCol] == EMPTY_VALUE);
            }
        }
        return moves;
    }

    /**
     * Merges two move grids using logical OR.
     */
    private void mergeMoves(boolean[][] target, boolean[][] source) {
        int size = source.length;
        for (int i = 0; i < size; i++) {
            for (int j = 0; j < size; j++) {
                target[i][j] = target[i][j] || source[i][j];
            }
        }
    }

    /**
     * Applies the combined moves to the coverage grid.
     */
    private void applyMoves(boolean[][] moves, int[][] coverageGrid, int pieceRow, int pieceCol) {
        for (int row = pieceRow + 1; row < pieceRow + 2 * n; row++) {
            for (int col = pieceCol + 1; col < pieceCol + 2 * n; col++) {
                int moveRow = row - pieceRow - 1;
                int moveCol = col - pieceCol - 1;
                if (!moves[moveRow][moveCol]) {
                    coverageGrid[row][col] = 1;
                }
            }
        }
    }

    /**
     * Prints the combined move grid.
     */
    private void printMoves(boolean[][] moves) {
        int size = 2 * n - 1;
        for (int row = 0; row < size; row++) {
            for (int col = 0; col < size; col++) {
                if (row == n - 1 && col == n - 1) {
                    System.out.print('o');
                } else {
                    System.out.print(moves[row][col] ? '.' : 'x');
                }
            }
            System.out.println();
        }
    }
}

