/**
 * Handles the core business logic for the grid problem.
 * Separated from IO to improve testability and maintainability.
 */
class Solver {

    /**
     * Lightweight coordinate class to replace java.awt.Point.
     * Immutable and efficient for algorithmic use.
     */
    private static class Coordinate {
        final int x;
        final int y;

        Coordinate(int x, int y) {
            this.x = x;
            this.y = y;
        }
    }

    /**
     * Main entry point for the solving logic.
     *
     * @param in  InputReader for reading the grid
     * @param out PrintWriter for outputting the result
     */
    void solve(InputReader in, PrintWriter out) {
        // 1. Read Input
        int n = in.nextInt();
        char[][] board = readBoard(in, n);

        // 2. Identify occupied squares ('o')
        List<Coordinate> occupiedSquares = findOccupiedSquares(board);

        // 3. Generate Result Grid and Identify Valid Moves
        // The result grid is larger (2n-1) to accommodate all possible translations
        char[][] resultGrid = new char[2 * n - 1][2 * n - 1];
        List<Coordinate> validMoves = new ArrayList<>();
        int center = n - 1;

        for (int row = 0; row < resultGrid.length; row++) {
            for (int col = 0; col < resultGrid[0].length; col++) {

                // The center of the result grid corresponds to the original board position (offset 0,0)
                if (row == center && col == center) {
                    resultGrid[row][col] = 'o';
                    continue;
                }

                // Calculate offset relative to the center
                int offsetX = col - center;
                int offsetY = row - center;

                boolean isDot = false;
                // Check if shifting the shape by (offsetX, offsetY) lands at least one piece on a '.'
                for (Coordinate square : occupiedSquares) {
                    int destX = square.x + offsetX;
                    int destY = square.y + offsetY;

                    if (isWithinBounds(destX, destY, n)) {
                        if (board[destY][destX] == '.') {
                            isDot = true;
                            break;
                        }
                    }
                }

                if (isDot) {
                    resultGrid[row][col] = '.';
                } else {
                    resultGrid[row][col] = 'x';
                    validMoves.add(new Coordinate(offsetX, offsetY));
                }
            }
        }

        // 4. Validation Phase
        // Check if every 'x' on the original board can be reached by a valid move from an 'o'
        boolean allXReachable = true;
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < n; c++) {
                if (board[r][c] == 'x') {
                    boolean found = false;
                    for (Coordinate move : validMoves) {
                        // Check if (r, c) is reachable from an 'o' using 'move'
                        // Logic: dest = source + move => source = dest - move
                        int sourceX = c - move.x;
                        int sourceY = r - move.y;

                        if (isWithinBounds(sourceX, sourceY, n) && board[sourceY][sourceX] == 'o') {
                            found = true;
                            break;
                        }
                    }
                    if (!found) {
                        allXReachable = false;
                        break;
                    }
                }
            }
            if (!allXReachable) break;
        }

        // 5. Output
        if (!allXReachable) {
            out.println("NO");
        } else {
            out.println("YES");
            for (char[] row : resultGrid) {
                out.println(new String(row));
            }
        }
    }

    /**
     * Reads the grid dimensions and the board characters from the input.
     */
    private char[][] readBoard(InputReader in, int n) {
        char[][] board = new char[n][];
        for (int i = 0; i < n; i++) {
            board[i] = in.next().toCharArray();
        }
        return board;
    }

    /**
     * Finds all coordinates of occupied squares ('o') in the board.
     */
    private List<Coordinate> findOccupiedSquares(char[][] board) {
        List<Coordinate> squares = new ArrayList<>();
        for (int r = 0; r < board.length; r++) {
            for (int c = 0; c < board[r].length; c++) {
                if (board[r][c] == 'o') {
                    squares.add(new Coordinate(c, r));
                }
            }
        }
        return squares;
    }

    /**
     * Checks if coordinates are within the bounds of the n x n board.
     */
    private boolean isWithinBounds(int x, int y, int n) {
        return x >= 0 && x < n && y >= 0 && y < n;
    }
}

/**
 * Fast Input Reader for competitive programming style I/O.
 * Uses BufferedReader and StringTokenizer for efficiency.
 */
class InputReader {
    private BufferedReader reader;
    private StringTokenizer tokenizer;

    public InputReader(InputStream stream) {
        reader = new BufferedReader(new InputStreamReader(stream), 32768);
        tokenizer = null;
    }

    public String next() {
        while (tokenizer == null || !tokenizer.hasMoreTokens()) {
            try {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            } catch (IOException e) {
                throw new RuntimeException(e);
            }
        }
        return tokenizer.nextToken();
    }

    public int nextInt() {
        String s = next();
        if (s == null) throw new RuntimeException("End of input");
        return Integer.parseInt(s);
    }
}

