/**
 * Contains the core business logic for processing the board configuration.
 */
class TaskD {
    private final FastScanner in;
    private final PrintWriter out;

    public TaskD(FastScanner in, PrintWriter out) {
        this.in = in;
        this.out = out;
    }

    /**
     * Orchestrates the reading, processing, validation, and output phases.
     */
    public void solve() throws IOException {
        int n = in.nextInt();
        String[] board = readBoard(n);
        List<Point> oPositions = extractOPositions(board);
        char[][] transformedGrid = computeTransformedGrid(board, oPositions, n);
        boolean isValid = validateGrid(board, transformedGrid, oPositions);

        if (isValid) {
            out.println("YES");
            printGrid(transformedGrid);
        } else {
            out.println("NO");
        }
    }

    private String[] readBoard(int n) throws IOException {
        String[] board = new String[n];
        for (int i = 0; i < n; i++) {
            board[i] = in.next();
        }
        return board;
    }

    private List<Point> extractOPositions(String[] board) {
        List<Point> positions = new ArrayList<>();
        for (int i = 0; i < board.length; i++) {
            for (int j = 0; j < board[i].length(); j++) {
                if (board[i].charAt(j) == 'o') {
                    positions.add(new Point(i, j));
                }
            }
        }
        return positions;
    }

    private char[][] computeTransformedGrid(String[] board, List<Point> oPositions, int n) {
        int size = 2 * n - 1;
        char[][] grid = new char[size][size];
        for (int i = 0; i < size; i++) {
            Arrays.fill(grid[i], 'x');
        }
        grid[n - 1][n - 1] = 'o';

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (board[i].charAt(j) == '.') {
                    for (Point o : oPositions) {
                        int dx = i - o.row;
                        int dy = j - o.col;
                        grid[n - 1 + dx][n - 1 + dy] = '.';
                    }
                }
            }
        }
        return grid;
    }

    private boolean validateGrid(String[] board, char[][] transformedGrid, List<Point> oPositions) {
        int n = board.length;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (board[i].charAt(j) == 'x') {
                    boolean isCovered = false;
                    for (Point o : oPositions) {
                        int dx = i - o.row;
                        int dy = j - o.col;
                        if (transformedGrid[n - 1 + dx][n - 1 + dy] == 'x') {
                            isCovered = true;
                            break;
                        }
                    }
                    if (!isCovered) {
                        return false;
                    }
                }
            }
        }
        return true;
    }

    private void printGrid(char[][] grid) {
        for (char[] row : grid) {
            out.println(new String(row));
        }
    }

    /**
     * Simple immutable data class to store grid coordinates.
     */
    private static class Point {
        final int row;
        final int col;

        Point(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }
}

/**
 * High-performance scanner for competitive programming / fast I/O.
 */
class FastScanner {
    private final BufferedReader br;
    private String line = "";
    private int pos = 0;

    public FastScanner(InputStream is) {
        this.br = new BufferedReader(new InputStreamReader(is));
    }

    public FastScanner(Reader reader) {
        this.br = new BufferedReader(reader);
    }

    public String next() throws IOException {
        while (true) {
            if (pos < line.length()) {
                return readToken();
            }
            line = br.readLine();
            if (line == null) {
                return null;
            }
            pos = 0;
            skipWhitespace();
        }
    }

    public int nextInt() throws IOException {
        String token = next();
        if (token == null) {
            throw new IOException("Unexpected end of input");
        }
        return Integer.parseInt(token);
    }

    private String readToken() {
        int start = pos;
        while (pos < line.length()) {
            char c = line.charAt(pos);
            if (c == ' ' || c == '\t') {
                break;
            }
            pos++;
        }
        String token = line.substring(start, pos);
        skipWhitespace();
        return token;
    }

    private void skipWhitespace() {
        while (pos < line.length()) {
            char c = line.charAt(pos);
            if (c != ' ' && c != '\t') {
                break;
            }
            pos++;
        }
    }
}

