/**
 * Core solver for the grid-based problem.
 * Refactored to be stateless: all mutable state is now local to the solve method,
 * and helper methods are static with explicit parameters. This improves testability,
 * thread-safety, and overall maintainability.
 */
class TaskD {
    /**
     * Solves the problem for a single test case.
     *
     * @param testNumber Unused test case identifier (kept for API compatibility)
     * @param in         FastReader for input
     * @param out        PrintWriter for output
     */
    @SuppressWarnings("unused")
    public void solve(int testNumber, FastReader in, PrintWriter out) {
        int n = in.nextInt();
        char[][] grid = new char[n][];
        int[] oRows = new int[n * n];
        int[] oCols = new int[n * n];
        int oCount = 0;

        // Parse grid and collect positions of 'o'
        for (int i = 0; i < n; i++) {
            grid[i] = in.nextString().toCharArray();
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 'o') {
                    oRows[oCount] = i;
                    oCols[oCount] = j;
                    oCount++;
                }
            }
        }

        int baseRow = n - 1;
        int baseCol = n - 1;
        int size = 2 * n - 1;
        boolean[][] safe = new boolean[size][size];

        // Mark safe positions based on '.' cells
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == '.') {
                    markSafe(i, j, oRows, oCols, oCount, baseRow, baseCol, safe);
                }
            }
        }

        // Verify all 'x' cells are attacked
        boolean allAttacked = true;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 'x') {
                    if (!isAttacked(i, j, oRows, oCols, oCount, baseRow, baseCol, safe)) {
                        allAttacked = false;
                    }
                }
            }
        }

        if (!allAttacked) {
            out.println("NO");
            return;
        }

        out.println("YES");
        // Output transformed grid
        for (int i = 0; i < size; i++) {
            for (int j = 0; j < size; j++) {
                if (i == baseRow && j == baseCol) {
                    out.print('o');
                } else {
                    out.print(safe[i][j] ? '.' : 'x');
                }
            }
            out.println();
        }
    }

    /**
     * Marks cells as safe in the transformed coordinate space.
     */
    private static void markSafe(int i, int j, int[] oRows, int[] oCols, int oCount,
                                 int baseRow, int baseCol, boolean[][] safe) {
        for (int k = 0; k < oCount; k++) {
            int di = i - oRows[k];
            int dj = j - oCols[k];
            safe[baseRow + di][baseCol + dj] = true;
        }
    }

    /**
     * Checks if a cell at (i, j) is attacked by any 'o' cell.
     * Returns true if attacked, false otherwise.
     */
    private static boolean isAttacked(int i, int j, int[] oRows, int[] oCols, int oCount,
                                      int baseRow, int baseCol, boolean[][] safe) {
        for (int k = 0; k < oCount; k++) {
            int di = i - oRows[k];
            int dj = j - oCols[k];
            if (!safe[baseRow + di][baseCol + dj]) {
                return true;
            }
        }
        return false;
    }
}

/**
 * High-performance input reader for competitive programming environments.
 * Refactored with descriptive naming, proper encapsulation, and improved error handling.
 */
class FastReader {
    private final InputStream stream;
    private final byte[] buffer = new byte[1024];
    private int bufferPointer = 0;
    private int bytesRead = 0;
    private SpaceCharFilter spaceCharFilter;

    public FastReader(InputStream stream) {
        this.stream = stream;
    }

    /**
     * Reads the next byte from the input stream.
     * @return The next byte, or -1 if end of stream
     * @throws InputMismatchException if stream is closed or read fails
     */
    public int read() {
        if (bytesRead == -1) {
            throw new InputMismatchException("End of stream reached");
        }
        if (bufferPointer >= bytesRead) {
            bufferPointer = 0;
            try {
                bytesRead = stream.read(buffer);
            } catch (IOException e) {
                throw new InputMismatchException("Failed to read from stream", e);
            }
            if (bytesRead <= 0) {
                return -1;
            }
        }
        return buffer[bufferPointer++];
    }

    /**
     * Reads the next integer token from input.
     */
    public int nextInt() {
        int c = read();
        while (isWhitespace(c)) {
            c = read();
        }
        int sign = 1;
        if (c == '-') {
            sign = -1;
            c = read();
        }
        int result = 0;
        do {
            if (c < '0' || c > '9') {
                throw new InputMismatchException("Invalid integer character: " + (char) c);
            }
            result = result * 10 + (c - '0');
            c = read();
        } while (!isWhitespace(c));
        return result * sign;
    }

    /**
     * Reads the next string token from input.
     */
    public String nextString() {
        int c = read();
        while (isWhitespace(c)) {
            c = read();
        }
        StringBuilder sb = new StringBuilder();
        do {
            sb.appendCodePoint(c);
            c = read();
        } while (!isWhitespace(c));
        return sb.toString();
    }

    /**
     * Checks if a character is considered whitespace.
     */
    public boolean isWhitespace(int c) {
        return spaceCharFilter != null ? spaceCharFilter.isSpaceChar(c) :
               c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
    }

    /**
     * Allows custom whitespace detection logic.
     */
    public void setSpaceCharFilter(SpaceCharFilter filter) {
        this.spaceCharFilter = filter;
    }

    /**
     * Functional interface for custom space character filtering.
     */
    @FunctionalInterface
    public interface SpaceCharFilter {
        boolean isSpaceChar(int ch);
    }
}

import java.io.*;
import java.util.*;

public class Main {
    // Constants for grid characters to eliminate magic values
    private static final char EMPTY_CELL = '.';
    private static final char FILLED_CELL = 'x';
    private static final char CENTER_CELL = 'o';

    public static void main(String[] args) throws IOException {
        FastReader sc = new FastReader();
        PrintWriter out = new PrintWriter(System.out);

        // Hardcoded to 1 based on original logic, but easily configurable
        int totalCases = 1;
        for (int t = 1; t <= totalCases; t++) {
            InputData data = readInput(sc);
            if (data == null) break;
            solve(data, out);
        }
        out.flush();
    }

    /**
     * Reads the input for a single test case.
     * Returns null if EOF is reached.
     */
    private static InputData readInput(FastReader sc) {
        String nStr = sc.next();
        if (nStr == null) return null;

        int n = Integer.parseInt(nStr);
        char[][] arr = new char[n][n];
        // Pre-allocate maximum possible positions for 'o'
        int[][] pos = new int[n * n][2];
        int index = 0;

        for (int i = 0; i < n; i++) {
            String row = sc.next();
            for (int j = 0; j < n; j++) {
                arr[i][j] = row.charAt(j);
                if (arr[i][j] == CENTER_CELL) {
                    pos[index][0] = i;
                    pos[index][1] = j;
                    index++;
                }
            }
        }
        return new InputData(n, arr, pos, index);
    }

    /**
     * Core logic for solving a single test case.
     */
    private static void solve(InputData data, PrintWriter out) {
        int n = data.n;
        char[][] arr = data.arr;
        int[][] pos = data.pos;
        int index = data.index;

        int gridSize = 2 * n - 1;
        char[][] soln = new char[gridSize][gridSize];

        // Initialize solution grid with 'x'
        for (int i = 0; i < gridSize; i++) {
            Arrays.fill(soln[i], FILLED_CELL);
        }
        soln[n - 1][n - 1] = CENTER_CELL;

        boolean possible = true;

        // Step 1: Apply transformations for '.' cells
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (arr[i][j] == EMPTY_CELL) {
                    for (int k = 0; k < index; k++) {
                        int di = pos[k][0] - i;
                        int dj = pos[k][1] - j;
                        soln[n - 1 - di][n - 1 - dj] = EMPTY_CELL;
                    }
                }
            }
        }

        // Step 2: Validate 'x' cells
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (arr[i][j] == FILLED_CELL) {
                    int matchCount = 0;
                    for (int k = 0; k < index; k++) {
                        int di = pos[k][0] - i;
                        int dj = pos[k][1] - j;
                        if (soln[n - 1 - di][n - 1 - dj] == FILLED_CELL) {
                            matchCount++;
                        }
                    }
                    if (matchCount == 0) {
                        possible = false;
                        break; // Early exit on validation failure
                    }
                }
            }
            if (!possible) break;
        }

        // Output results
        if (possible) {
            out.println("YES");
            printGrid(soln, out);
        } else {
            out.println("NO");
        }
    }

    /**
     * Prints the solution grid efficiently using buffered output.
     */
    private static void printGrid(char[][] grid, PrintWriter out) {
        for (char[] row : grid) {
            out.write(row);
            out.println();
        }
    }

    /**
     * Encapsulates test case data to avoid passing multiple parameters.
     */
    private static class InputData {
        final int n;
        final char[][] arr;
        final int[][] pos;
        final int index;

        InputData(int n, char[][] arr, int[][] pos, int index) {
            this.n = n;
            this.arr = arr;
            this.pos = pos;
            this.index = index;
        }
    }

    /**
     * Fast I/O helper class for competitive programming style input.
     */
    static class FastReader {
        BufferedReader br;
        StringTokenizer st;

        public FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return st.nextToken();
        }
    }
}

import java.util.*;

/**
 * Solves a pattern matching problem on a grid.
 * Reads an n x n grid, constructs a transformed output grid,
 * and verifies if all 'x' positions in the input are valid.
 */
public class PatternGridSolver {

    /** Represents a coordinate on the grid. */
    private static final class Point {
        final int row;
        final int col;

        Point(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            if (!scanner.hasNextInt()) {
                return;
            }

            int gridSize = scanner.nextInt();
            scanner.nextLine(); // Consume the newline after the integer

            char[][] inputGrid = new char[gridSize][];
            List<Point> xPositions = new ArrayList<>();
            List<Point> oPositions = new ArrayList<>();
            List<Point> dotPositions = new ArrayList<>();

            // Parse input grid and categorize positions
            for (int i = 0; i < gridSize; i++) {
                String line = scanner.nextLine();
                inputGrid[i] = line.toCharArray();
                for (int j = 0; j < gridSize; j++) {
                    char c = inputGrid[i][j];
                    if (c == 'x') {
                        xPositions.add(new Point(i, j));
                    } else if (c == 'o') {
                        oPositions.add(new Point(i, j));
                    } else if (c == '.') {
                        dotPositions.add(new Point(i, j));
                    }
                }
            }

            int outputSize = 2 * gridSize - 1;
            char[][] outputGrid = new char[outputSize][outputSize];

            // Initialize output grid with 'x'
            initializeGrid(outputGrid, 'x');
            // Place the central 'o'
            outputGrid[gridSize - 1][gridSize - 1] = 'o';

            // Place '.' based on input patterns relative to each 'o'
            placePatternDots(outputGrid, oPositions, dotPositions, gridSize);

            // Verify if all 'x' positions from input are valid in the output
            if (validateXPositions(outputGrid, xPositions, oPositions, gridSize)) {
                System.out.println("YES");
                printGrid(outputGrid);
            } else {
                System.out.println("NO");
            }
        }
    }

    /** Fills a 2D character array with a specified character. */
    private static void initializeGrid(char[][] grid, char fillChar) {
        for (char[] row : grid) {
            Arrays.fill(row, fillChar);
        }
    }

    /**
     * Places '.' characters in the output grid based on the relative positions
     * of dots in the input grid, anchored at each 'o' position.
     */
    private static void placePatternDots(char[][] outputGrid, List<Point> oPositions,
                                         List<Point> dotPositions, int gridSize) {
        int centerOffset = gridSize - 1;
        for (Point anchor : oPositions) {
            for (Point dot : dotPositions) {
                int newRow = centerOffset - anchor.row + dot.row;
                int newCol = centerOffset - anchor.col + dot.col;
                outputGrid[newRow][newCol] = '.';
            }
        }
    }

    /**
     * Validates that every 'x' in the input grid corresponds to an 'x' in the
     * output grid when transformed relative to any 'o' anchor.
     */
    private static boolean validateXPositions(char[][] outputGrid, List<Point> xPositions,
                                              List<Point> oPositions, int gridSize) {
        int centerOffset = gridSize - 1;
        for (Point targetX : xPositions) {
            boolean isMatched = false;
            for (Point anchor : oPositions) {
                int newRow = centerOffset - anchor.row + targetX.row;
                int newCol = centerOffset - anchor.col + targetX.col;
                if (outputGrid[newRow][newCol] == 'x') {
                    isMatched = true;
                    break;
                }
            }
            if (!isMatched) {
                return false;
            }
        }
        return true;
    }

    /** Prints the 2D character grid to standard output. */
    private static void printGrid(char[][] grid) {
        for (char[] row : grid) {
            System.out.println(new String(row));
        }
    }
}

import java.io.BufferedReader;
import java.io.BufferedWriter;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.OutputStreamWriter;
import java.io.PrintWriter;
import java.util.StringTokenizer;

public class Main {

    public static void main(String[] args) throws IOException {
        FastScanner scanner = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)));

        new Main().solve(scanner, out);

        out.flush();
        out.close();
    }

    /**
     * Main logic for solving the problem.
     * Reads input, computes valid shifts, validates coverage, and writes output.
     */
    void solve(FastScanner scanner, PrintWriter out) {
        String nStr = scanner.next();
        if (nStr == null) return;
        int n = Integer.parseInt(nStr);
        if (n <= 0) return;

        char[][] grid = new char[n][n];
        int[][] patternPositions = new int[n * n][2];
        int patternCount = 0;

        // Read grid and collect 'o' positions
        for (int i = 0; i < n; i++) {
            String line = scanner.next();
            for (int j = 0; j < n; j++) {
                grid[i][j] = line.charAt(j);
                if (grid[i][j] == 'o') {
                    patternPositions[patternCount][0] = i;
                    patternPositions[patternCount][1] = j;
                    patternCount++;
                }
            }
        }

        int shiftRange = n - 1;
        char[][] resultGrid = new char[2 * n - 1][2 * n - 1];
        boolean[][] isCovered = new boolean[n][n];

        // Iterate over all possible shifts
        for (int dx = -shiftRange; dx <= shiftRange; dx++) {
            for (int dy = -shiftRange; dy <= shiftRange; dy++) {
                int r = dx + shiftRange;
                int c = dy + shiftRange;

                if (isValidShift(grid, patternPositions, patternCount, n, dx, dy)) {
                    resultGrid[r][c] = 'x';
                    markCovered(patternPositions, patternCount, n, dx, dy, isCovered);
                } else {
                    resultGrid[r][c] = '.';
                }
            }
        }

        // The center corresponds to the original unshifted pattern
        resultGrid[shiftRange][shiftRange] = 'o';

        // Verify that every 'o' in the original grid is covered by at least one valid shift
        boolean allCovered = true;
        outerLoop:
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 'o' && !isCovered[i][j]) {
                    allCovered = false;
                    break outerLoop;
                }
            }
        }

        if (allCovered) {
            out.println("YES");
            for (int i = 0; i < 2 * n - 1; i++) {
                out.println(resultGrid[i]);
            }
        } else {
            out.println("NO");
        }
    }

    /**
     * Checks if shifting the pattern by (dx, dy) causes any 'o' to land on a '.' cell.
     */
    private boolean isValidShift(char[][] grid, int[][] pattern, int count, int n, int dx, int dy) {
        for (int k = 0; k < count; k++) {
            int px = pattern[k][0] + dx;
            int py = pattern[k][1] + dy;
            if (px >= 0 && px < n && py >= 0 && py < n) {
                if (grid[px][py] == '.') {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Marks all cells covered by the pattern when shifted by (dx, dy).
     */
    private void markCovered(int[][] pattern, int count, int n, int dx, int dy, boolean[][] isCovered) {
        for (int k = 0; k < count; k++) {
            int px = pattern[k][0] + dx;
            int py = pattern[k][1] + dy;
            if (px >= 0 && px < n && py >= 0 && py < n) {
                isCovered[px][py] = true;
            }
        }
    }

    /**
     * Efficient input scanner for fast I/O.
     * Replaces the original buggy Reader class that ignored the filename parameter.
     */
    private static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        public String next() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) return null;
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }
    }
}

