class TaskD {
    /**
     * Solves the problem by constructing an attack grid and validating field constraints.
     *
     * @param testNumber Test case identifier (unused but kept for compatibility)
     * @param in         Fast input reader
     * @param out        Fast output writer
     */
    public void solve(int testNumber, InputReader in, PrintWriter out) {
        int n = in.nextInt();
        char[][] field = new char[n][n];
        for (int i = 0; i < n; i++) {
            field[i] = in.next().toCharArray();
        }

        char[][] attackGrid = buildAttackGrid(n, field);
        boolean isValid = validateFieldConstraints(n, field, attackGrid);

        if (isValid) {
            out.println("YES");
            for (char[] row : attackGrid) {
                out.println(new String(row));
            }
        } else {
            out.println("NO");
        }
    }

    /**
     * Constructs the 2n-1 x 2n-1 attack grid.
     * Initializes all cells to 'x', places 'o' at the center,
     * and marks relative offsets from every 'o' to every '.' as '.'.
     */
    private char[][] buildAttackGrid(int n, char[][] field) {
        int size = 2 * n - 1;
        char[][] attackGrid = new char[size][size];

        // Initialize grid with 'x'
        for (char[] row : attackGrid) {
            Arrays.fill(row, 'x');
        }

        // Place origin 'o' at the center
        attackGrid[n - 1][n - 1] = 'o';

        // Mark relative positions from 'o' to '.'
        for (int r0 = 0; r0 < n; r0++) {
            for (int c0 = 0; c0 < n; c0++) {
                if (field[r0][c0] == 'o') {
                    for (int r1 = 0; r1 < n; r1++) {
                        for (int c1 = 0; c1 < n; c1++) {
                            if (field[r1][c1] == '.') {
                                attackGrid[n - 1 + (r1 - r0)][n - 1 + (c1 - c0)] = '.';
                            }
                        }
                    }
                }
            }
        }
        return attackGrid;
    }

    /**
     * Validates that every 'x' in the original field has at least one valid 'o'
     * in the attack grid that aligns with an 'x' relative position.
     */
    private boolean validateFieldConstraints(int n, char[][] field, char[][] attackGrid) {
        for (int r1 = 0; r1 < n; r1++) {
            for (int c1 = 0; c1 < n; c1++) {
                if (field[r1][c1] == 'x') {
                    boolean found = false;
                    for (int r0 = 0; r0 < n; r0++) {
                        for (int c0 = 0; c0 < n; c0++) {
                            if (field[r0][c0] == 'o') {
                                if (attackGrid[n - 1 + (r1 - r0)][n - 1 + (c1 - c0)] == 'x') {
                                    found = true;
                                    break;
                                }
                            }
                        }
                        if (found) break;
                    }
                    if (!found) {
                        return false;
                    }
                }
            }
        }
        return true;
    }
}

/**
 * Fast input reader for competitive programming and high-performance I/O.
 */
class InputReader {
    private final BufferedReader reader;
    private StringTokenizer tokenizer;

    public InputReader(InputStream stream) {
        reader = new BufferedReader(new InputStreamReader(stream), 32768);
        tokenizer = null;
    }

    public String next() {
        while (tokenizer == null || !tokenizer.hasMoreTokens()) {
            try {
                String line = reader.readLine();
                if (line == null) {
                    throw new IOException("Unexpected end of input");
                }
                tokenizer = new StringTokenizer(line);
            } catch (IOException e) {
                throw new RuntimeException("Failed to read input stream", e);
            }
        }
        return tokenizer.nextToken();
    }

    public int nextInt() {
        return Integer.parseInt(next());
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayList;
import java.util.List;

/**
 * Analyzes a chessboard configuration to determine if attacked squares 
 * meet specific diagonal coverage criteria. Outputs a validity check 
 * and a visual representation of the diagonal mapping.
 */
public class ChessSolver {

    public static void main(String[] args) throws IOException {
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(System.in))) {
            String line = reader.readLine();
            if (line == null) return;

            int n = Integer.parseInt(line.trim());

            List<Point> pieces = new ArrayList<>();
            List<Point> attacked = new ArrayList<>();
            List<Point> emptySquares = new ArrayList<>();

            // Parse the input grid
            for (int i = 0; i < n; i++) {
                String row = reader.readLine();
                if (row == null) break;
                for (int j = 0; j < n; j++) {
                    char c = row.charAt(j);
                    Point p = new Point(i, j);
                    if (c == 'o') {
                        pieces.add(p);
                    } else if (c == 'x') {
                        attacked.add(p);
                    } else if (c == '.') {
                        emptySquares.add(p);
                    }
                }
            }

            // Remove unused grid array from original code
            // boolean[][] a represents diagonal coordinates offset by n-1
            boolean[][] diagonalMap = new boolean[2 * n - 1][2 * n - 1];

            // Mark diagonals: for each empty square, mark its relative diagonal offset 
            // from every piece. This creates a coordinate system where (0,0) is the 
            // top-left difference and (2n-2, 2n-2) is the bottom-right difference.
            for (Point empty : emptySquares) {
                for (Point piece : pieces) {
                    int dx = empty.x - piece.x;
                    int dy = empty.y - piece.y;
                    diagonalMap[dx + n - 1][dy + n - 1] = true;
                }
            }

            // Verify attacked squares against the diagonal map
            for (Point target : attacked) {
                boolean allPiecesMarked = true;
                for (Point piece : pieces) {
                    int dx = target.x - piece.x;
                    int dy = target.y - piece.y;
                    if (!diagonalMap[dx + n - 1][dy + n - 1]) {
                        allPiecesMarked = false;
                        break;
                    }
                }

                // If all pieces cover the target's diagonal, output NO and exit gracefully
                if (allPiecesMarked) {
                    System.out.println("NO");
                    return;
                }
            }

            System.out.println("YES");

            // Build output efficiently using StringBuilder
            StringBuilder output = new StringBuilder();
            for (int i = 0; i < 2 * n - 1; i++) {
                for (int j = 0; j < 2 * n - 1; j++) {
                    if (i == n - 1 && j == n - 1) {
                        output.append('o');
                    } else if (diagonalMap[i][j]) {
                        output.append('.');
                    } else {
                        output.append('x');
                    }
                }
                output.append('\n');
            }
            System.out.print(output);
        }
    }

    /**
     * Represents a coordinate on the board.
     */
    private static class Point {
        final int x;
        final int y;

        Point(int x, int y) {
            this.x = x;
            this.y = y;
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * A solver for grid pattern validation problems.
 * Refactored for improved maintainability, readability, and code quality.
 */
public class GridPatternSolver {

    /**
     * Represents a coordinate in a 2D grid.
     */
    private static class Coordinate {
        int x, y;

        Coordinate(int x, int y) {
            this.x = x;
            this.y = y;
        }
    }

    /**
     * FastScanner for efficient input reading.
     */
    private static class FastScanner {
        private BufferedReader br;
        private StringTokenizer st;

        public FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        public String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) {
                        return null;
                    }
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            String s = next();
            if (s == null) throw new RuntimeException("End of input reached");
            return Integer.parseInt(s);
        }
    }

    // Static output writer for buffered printing
    static PrintWriter out;
    static FastScanner in;

    public static void main(String[] args) {
        long startTime = System.currentTimeMillis();

        in = new FastScanner();
        out = new PrintWriter(System.out);

        // Instantiate solver and run logic
        new GridPatternSolver().solve();

        out.flush();
        out.close();

        // Optional: Print execution time
        // System.out.println("Execution time: " + (System.currentTimeMillis() - startTime) + " ms");
    }

    public void solve() {
        // Read grid dimension
        int n = in.nextInt();

        // Read input grid
        char[][] inputGrid = new char[n][];
        for (int i = 0; i < n; ++i) {
            inputGrid[i] = in.next().toCharArray();
        }

        // List to store coordinates of 'o' points found in the input grid
        List<Coordinate> oCoordinates = new ArrayList<>();

        // Initialize result grid
        // Size is (2n - 1) to accommodate offsets from the center
        int resultSize = 2 * n - 1;
        char[][] outputGrid = new char[resultSize][resultSize];

        // Fill result grid with default 'x'
        for (char[] row : outputGrid) {
            Arrays.fill(row, 'x');
        }

        // Set center of result grid to 'o'
        int centerOffset = n - 1;
        outputGrid[centerOffset][centerOffset] = 'o';

        // 1. Identify all 'o' coordinates in the input grid
        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < n; ++j) {
                if (inputGrid[i][j] == 'o') {
                    oCoordinates.add(new Coordinate(i, j));
                }
            }
        }

        // 2. Map '.' positions from input to output grid based on relative offsets to 'o's
        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < n; ++j) {
                if (inputGrid[i][j] == '.') {
                    for (Coordinate p : oCoordinates) {
                        int dx = i - p.x;
                        int dy = j - p.y;
                        // Map relative coordinate to absolute coordinate in outputGrid
                        outputGrid[dx + centerOffset][dy + centerOffset] = '.';
                    }
                }
            }
        }

        // 3. Validate 'x' positions in input grid
        // An 'x' in input is valid if the corresponding relative position in outputGrid is 'x'
        // (meaning it wasn't overwritten by a '.' or 'o' in the previous step)
        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < n; ++j) {
                if (inputGrid[i][j] == 'x') {
                    boolean isValid = false;
                    for (Coordinate p : oCoordinates) {
                        int dx = i - p.x;
                        int dy = j - p.y;

                        // Check bounds just to be safe, though logic implies validity
                        int outX = dx + centerOffset;
                        int outY = dy + centerOffset;

                        if (outX >= 0 && outX < resultSize && outY >= 0 && outY < resultSize) {
                            if (outputGrid[outX][outY] == 'x') {
                                isValid = true;
                                break;
                            }
                        }
                    }

                    if (!isValid) {
                        out.println("NO");
                        return;
                    }
                }
            }
        }

        // If validation passes
        out.println("YES");
        for (int i = 0; i < resultSize; ++i) {
            out.println(outputGrid[i]);
        }
    }
}

import java.io.IOException;
import java.io.InputStream;
import java.util.Arrays;
import java.util.InputMismatchException;

/**
 * Solves the attack pattern validation problem.
 * <p>
 * Reads a grid containing observers ('o'), targets ('x'), and empty cells ('.').
 * Determines which relative offsets from an observer are valid for attacking
 * (i.e., do not land on an empty cell). Then verifies if all targets are attacked
 * by at least one observer. Outputs "YES"/"NO" and the valid attack pattern.
 */
public class AttackGridSolver {

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner();
        solve(scanner);
    }

    /**
     * Orchestrates the solution flow: reads input, computes logic, validates, and prints output.
     */
    public static void solve(FastScanner in) {
        int gridSize = in.nextInt();
        char[][] grid = readGrid(in, gridSize);
        boolean[][] validAttackOffsets = computeValidAttackOffsets(grid, gridSize);
        boolean[][] attackedCells = computeAttackedCells(grid, validAttackOffsets, gridSize);

        if (!validateAllTargetsAttacked(grid, attackedCells, gridSize)) {
            System.out.println("NO");
            return;
        }

        System.out.println("YES");
        printAttackPattern(validAttackOffsets, gridSize);
    }

    /**
     * Reads the N x N character grid from the scanner.
     */
    private static char[][] readGrid(FastScanner in, int n) {
        char[][] grid = new char[n][n];
        for (int i = 0; i < n; i++) {
            grid[i] = in.next().toCharArray();
        }
        return grid;
    }

    /**
     * Computes which relative offsets (dr, dc) are valid for attacking.
     * An offset is invalid if any observer ('o') can see an empty cell ('.') at that relative position.
     */
    private static boolean[][] computeValidAttackOffsets(char[][] grid, int n) {
        int center = n - 1;
        int offsetSize = 2 * n - 1;
        boolean[][] validOffsets = new boolean[offsetSize][offsetSize];

        // Initially assume all offsets are valid
        for (int i = 0; i < offsetSize; i++) {
            Arrays.fill(validOffsets[i], true);
        }

        // Check each observer to invalidate offsets that land on empty cells
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < n; c++) {
                if (grid[r][c] == 'o') {
                    for (int dr = -center; dr <= center; dr++) {
                        for (int dc = -center; dc <= center; dc++) {
                            int nr = r + dr;
                            int nc = c + dc;

                            if (isInBounds(nr, nc, n) && grid[nr][nc] == '.') {
                                // Map relative offset to array index: [0, 2N-2]
                                validOffsets[dr + center][dc + center] = false;
                            }
                        }
                    }
                }
            }
        }
        return validOffsets;
    }

    /**
     * Marks cells as attacked based on valid offsets from each observer.
     */
    private static boolean[][] computeAttackedCells(char[][] grid, boolean[][] validOffsets, int n) {
        int center = n - 1;
        boolean[][] attacked = new boolean[n][n];

        for (int r = 0; r < n; r++) {
            for (int c = 0; c < n; c++) {
                if (grid[r][c] == 'o') {
                    for (int dr = -center; dr <= center; dr++) {
                        for (int dc = -center; dc <= center; dc++) {
                            if (validOffsets[dr + center][dc + center]) {
                                int nr = r + dr;
                                int nc = c + dc;
                                if (isInBounds(nr, nc, n)) {
                                    attacked[nr][nc] = true;
                                }
                            }
                        }
                    }
                }
            }
        }
        return attacked;
    }

    /**
     * Validates that every target ('x') cell is covered by at least one attack.
     */
    private static boolean validateAllTargetsAttacked(char[][] grid, boolean[][] attacked, int n) {
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < n; c++) {
                if (grid[r][c] == 'x' && !attacked[r][c]) {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Prints the attack pattern relative to an observer at the center.
     */
    private static void printAttackPattern(boolean[][] validOffsets, int n) {
        int center = n - 1;
        int offsetSize = 2 * n - 1;

        StringBuilder sb = new StringBuilder(offsetSize * 2);
        for (int i = 0; i < offsetSize; i++) {
            sb.setLength(0);
            for (int j = 0; j < offsetSize; j++) {
                if (i == center && j == center) {
                    sb.append('o');
                } else {
                    sb.append(validOffsets[i][j] ? 'x' : '.');
                }
            }
            System.out.println(sb);
        }
    }

    /**
     * Checks if row and column indices are within grid boundaries.
     */
    private static boolean isInBounds(int r, int c, int n) {
        return r >= 0 && r < n && c >= 0 && c < n;
    }

    /**
     * High-performance scanner for competitive programming style inputs.
     */
    private static class FastScanner {
        private final InputStream stream;
        private final byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;

        public FastScanner() {
            this.stream = System.in;
        }

        private int read() {
            if (numChars == -1) {
                throw new InputMismatchException();
            }
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0) {
                    return -1;
                }
            }
            return buf[curChar++];
        }

        private boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        private boolean isEndline(int c) {
            return c == '\n' || c == '\r' || c == -1;
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }

        public double nextDouble() {
            return Double.parseDouble(next());
        }

        public String next() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            StringBuilder res = new StringBuilder();
            do {
                res.appendCodePoint(c);
                c = read();
            } while (!isSpaceChar(c));
            return res.toString();
        }

        public String nextLine() {
            int c = read();
            while (isEndline(c)) {
                c = read();
            }
            StringBuilder res = new StringBuilder();
            do {
                res.appendCodePoint(c);
                c = read();
            } while (!isEndline(c));
            return res.toString();
        }
    }
}

import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.Scanner;

public class GridSolver {
    // Constants for grid cell types to replace magic numbers
    private static final int EMPTY = 0;
    private static final int BLOCK = 1;
    private static final int CENTER = 2;

    public static void main(String[] args) {
        // Use try-with-resources for automatic resource management
        try (Scanner scanner = new Scanner(System.in)) {
            if (!scanner.hasNextInt()) {
                return;
            }
            int n = scanner.nextInt();

            int[][] inputGrid = new int[n][n];
            List<int[]> oPositions = new ArrayList<>();

            // Parse input grid and collect 'o' coordinates
            for (int i = 0; i < n; i++) {
                String row = scanner.next();
                for (int j = 0; j < n; j++) {
                    char c = row.charAt(j);
                    if (c == 'x') {
                        inputGrid[i][j] = BLOCK;
                    } else if (c == 'o') {
                        inputGrid[i][j] = CENTER;
                        oPositions.add(new int[]{i, j});
                    } else if (c == '.') {
                        inputGrid[i][j] = EMPTY;
                    }
                }
            }

            // Generate the transformed result grid
            int[][] resultGrid = buildResultGrid(n, inputGrid, oPositions);

            // Validate constraints and print the final output
            processOutput(n, inputGrid, resultGrid, oPositions);
        }
    }

    /**
     * Constructs the (2n-1)x(2n-1) result grid according to the specified rules.
     * Initializes with BLOCKs, places a CENTER at the middle, and marks EMPTY
     * cells based on relative offsets from each 'o' position.
     */
    private static int[][] buildResultGrid(int n, int[][] inputGrid, List<int[]> oPositions) {
        int size = 2 * n - 1;
        int[][] grid = new int[size][size];

        // Initialize grid with BLOCKs
        for (int[] row : grid) {
            Arrays.fill(row, BLOCK);
        }

        int mid = n - 1;
        grid[mid][mid] = CENTER;

        // Mark EMPTY cells based on input '.' positions relative to each 'o'
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (inputGrid[i][j] == EMPTY) {
                    for (int[] oPos : oPositions) {
                        int r = mid + i - oPos[0];
                        int c = mid + j - oPos[1];
                        grid[r][c] = EMPTY;
                    }
                }
            }
        }
        return grid;
    }

    /**
     * Validates that all 'x' cells in the input are properly covered in the result grid.
     * Prints "NO" and exits if validation fails, otherwise prints "YES" and the grid.
     */
    private static void processOutput(int n, int[][] inputGrid, int[][] resultGrid, List<int[]> oPositions) {
        int mid = n - 1;

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (inputGrid[i][j] == BLOCK) {
                    boolean isCovered = false;
                    for (int[] oPos : oPositions) {
                        int r = mid + i - oPos[0];
                        int c = mid + j - oPos[1];
                        if (resultGrid[r][c] == BLOCK) {
                            isCovered = true;
                            break; // Optimization: early exit once covered
                        }
                    }
                    if (!isCovered) {
                        System.out.println("NO");
                        return;
                    }
                }
            }
        }

        System.out.println("YES");
        printGrid(resultGrid);
    }

    /**
     * Prints the result grid to standard output.
     */
    private static void printGrid(int[][] grid) {
        for (int[] row : grid) {
            for (int val : row) {
                System.out.print(val == EMPTY ? '.' : (val == BLOCK ? 'x' : 'o'));
            }
            System.out.println();
        }
    }
}

