/**
 * Contains the core business logic for solving the grid pattern problem.
 */
class GridSolver {

    /**
     * Orchestrates the solution: reads input, computes validity, validates, and prints output.
     */
    public void solve(FastScanner in, PrintWriter out) {
        int n = in.nextInt();
        char[][] grid = readGrid(in, n);

        boolean[][] good = initializeGoodOffsets(n);
        markInvalidOffsets(grid, good, n);
        boolean[][] covered = markCoveredCells(grid, good, n);

        if (!isAllXCovered(grid, covered, n)) {
            out.println("NO");
            return;
        }

        out.println("YES");
        printResultGrid(good, n, out);
    }

    /**
     * Reads the n x n character grid from input.
     */
    private char[][] readGrid(FastScanner in, int n) {
        char[][] grid = new char[n][];
        for (int i = 0; i < n; i++) {
            grid[i] = in.next().toCharArray();
        }
        return grid;
    }

    /**
     * Initializes the 'good' offset matrix.
     * Maps coordinate differences [-n, n] to array indices [0, 2n] using an offset of n.
     */
    private boolean[][] initializeGoodOffsets(int n) {
        int size = 2 * n + 1;
        boolean[][] good = new boolean[size][size];
        for (int dx = -n; dx <= n; dx++) {
            for (int dy = -n; dy <= n; dy++) {
                if (dx != 0 || dy != 0) {
                    good[dx + n][dy + n] = true;
                }
            }
        }
        return good;
    }

    /**
     * Marks offsets as invalid when an 'o' and a '.' appear at that relative displacement.
     */
    private void markInvalidOffsets(char[][] grid, boolean[][] good, int n) {
        for (int x = 0; x < n; x++) {
            for (int y = 0; y < n; y++) {
                if (grid[x][y] == 'o') {
                    for (int i = 0; i < n; i++) {
                        for (int j = 0; j < n; j++) {
                            if (grid[i][j] == '.') {
                                good[i - x + n][j - y + n] = false;
                            }
                        }
                    }
                }
            }
        }
    }

    /**
     * Determines which cells are covered by at least one 'o' using valid offsets.
     */
    private boolean[][] markCoveredCells(char[][] grid, boolean[][] good, int n) {
        boolean[][] covered = new boolean[n][n];
        for (int x = 0; x < n; x++) {
            for (int y = 0; y < n; y++) {
                if (grid[x][y] == 'o') {
                    for (int i = 0; i < n; i++) {
                        for (int j = 0; j < n; j++) {
                            if (good[i - x + n][j - y + n]) {
                                covered[i][j] = true;
                            }
                        }
                    }
                }
            }
        }
        return covered;
    }

    /**
     * Validates that every 'x' in the grid is covered by at least one valid offset.
     */
    private boolean isAllXCovered(char[][] grid, boolean[][] covered, int n) {
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 'x' && !covered[i][j]) {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Prints the resulting offset grid.
     * The center (n, n) is always 'o', others are 'x' if valid, '.' otherwise.
     */
    private void printResultGrid(boolean[][] good, int n, PrintWriter out) {
        int limit = 2 * n;
        for (int i = 1; i < limit; i++) {
            for (int j = 1; j < limit; j++) {
                if (i == n && j == n) {
                    out.print('o');
                } else {
                    out.print(good[i][j] ? 'x' : '.');
                }
            }
            out.println();
        }
    }
}

/**
 * Fast input scanner for competitive programming and performance-critical I/O.
 */
class FastScanner implements Closeable {
    private final BufferedReader reader;
    private StringTokenizer tokenizer;

    public FastScanner(InputStream inputStream) {
        this.reader = new BufferedReader(new InputStreamReader(inputStream));
    }

    /**
     * Returns the next token from input.
     * @return next string token, or null if end of stream is reached
     */
    public String next() {
        while (tokenizer == null || !tokenizer.hasMoreTokens()) {
            try {
                String line = reader.readLine();
                if (line == null) {
                    return null;
                }
                tokenizer = new StringTokenizer(line);
            } catch (IOException e) {
                // Fail fast instead of silently swallowing exceptions
                throw new RuntimeException("Failed to read input", e);
            }
        }
        return tokenizer.nextToken();
    }

    /**
     * Parses the next token as an integer.
     */
    public int nextInt() {
        String token = next();
        if (token == null) {
            throw new RuntimeException("Unexpected end of input");
        }
        return Integer.parseInt(token);
    }

    @Override
    public void close() throws IOException {
        reader.close();
    }
}

import java.io.*;
import java.util.*;

/**
 * Solves a grid transformation problem by finding valid shifts that cover all 'x' cells
 * using 'o' cells, then outputs the resulting target grid or "NO" if impossible.
 */
public class GridSolver {

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner();
        PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out));
        try {
            solve(scanner, out);
        } finally {
            out.flush();
        }
    }

    private static void solve(FastScanner scanner, PrintWriter out) {
        int n = scanner.nextInt();
        char[][] grid = new char[n][];
        for (int i = 0; i < n; i++) {
            grid[i] = scanner.next().toCharArray();
        }

        int m = 2 * n - 1;
        char[][] targetGrid = new char[m][m];
        for (int i = 0; i < m; i++) {
            Arrays.fill(targetGrid[i], '.');
        }
        boolean[][] coverageMask = new boolean[n][n];

        // Iterate over all possible row and column shifts
        for (int rowShift = 1 - n; rowShift < n; rowShift++) {
            for (int colShift = 1 - n; colShift < n; colShift++) {
                if (isShiftValid(grid, n, rowShift, colShift)) {
                    targetGrid[rowShift + n - 1][colShift + n - 1] = 'x';
                    updateCoverageMask(grid, n, rowShift, colShift, coverageMask);
                }
            }
        }

        boolean isPossible = verifyXCoverage(grid, n, coverageMask);

        if (isPossible) {
            targetGrid[n - 1][n - 1] = 'o';
            out.println("YES");
            printGrid(targetGrid, out);
        } else {
            out.println("NO");
        }
    }

    /**
     * Checks if a given shift is valid: every 'o' must land on a non-empty cell
     * if the shifted position remains within bounds.
     */
    private static boolean isShiftValid(char[][] grid, int n, int rowShift, int colShift) {
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 'o') {
                    int ii = i + rowShift;
                    int jj = j + colShift;
                    if (ii >= 0 && jj >= 0 && ii < n && jj < n) {
                        if (grid[ii][jj] == '.') {
                            return false;
                        }
                    }
                }
            }
        }
        return true;
    }

    /**
     * Marks all valid landing positions of 'o' cells after applying the shift.
     */
    private static void updateCoverageMask(char[][] grid, int n, int rowShift, int colShift, boolean[][] mask) {
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 'o') {
                    int ii = i + rowShift;
                    int jj = j + colShift;
                    if (ii >= 0 && jj >= 0 && ii < n && jj < n) {
                        mask[ii][jj] = true;
                    }
                }
            }
        }
    }

    /**
     * Verifies that every 'x' in the original grid is covered by at least one valid shift.
     */
    private static boolean verifyXCoverage(char[][] grid, int n, boolean[][] mask) {
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 'x' && !mask[i][j]) {
                    return false;
                }
            }
        }
        return true;
    }

    private static void printGrid(char[][] grid, PrintWriter out) {
        for (char[] row : grid) {
            out.println(new String(row));
        }
    }

    /**
     * Lightweight, standard-compliant fast I/O scanner.
     */
    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) throw new EOFException();
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

