/**
 * Encapsulates the logic for determining if a grid shift can cover all target 'x' cells
 * without overlapping any 'o' cells or landing on invalid '.' cells.
 */
class GridShiftSolver {

    public void solve(int n, FastScanner in, PrintWriter out) {
        char[][] grid = readGrid(in, n);
        boolean[][] isCovered = new boolean[n][n];
        char[][] resultGrid = initializeResultGrid(n);

        boolean possible = false;

        // Iterate over all valid translation vectors
        for (int shiftRow = -n + 1; shiftRow < n; shiftRow++) {
            for (int shiftCol = -n + 1; shiftCol < n; shiftCol++) {
                if (isValidShift(grid, n, shiftRow, shiftCol)) {
                    markCoveredPositions(grid, n, shiftRow, shiftCol, isCovered);

                    // Record the shift vector in the output grid (exclude identity shift)
                    if (shiftRow != 0 || shiftCol != 0) {
                        resultGrid[shiftRow + n - 1][shiftCol + n - 1] = 'x';
                    }

                    if (allTargetsCovered(grid, n, isCovered)) {
                        possible = true;
                    }
                }
            }
        }

        if (possible) {
            out.println("YES");
            for (char[] row : resultGrid) {
                out.println(row);
            }
        } else {
            out.println("NO");
        }
    }

    private char[][] readGrid(FastScanner in, int n) {
        char[][] grid = new char[n][];
        for (int i = 0; i < n; i++) {
            grid[i] = in.next().toCharArray();
        }
        return grid;
    }

    private char[][] initializeResultGrid(int n) {
        int size = 2 * n - 1;
        char[][] grid = new char[size][size];
        for (int i = 0; i < size; i++) {
            Arrays.fill(grid[i], '.');
        }
        grid[n - 1][n - 1] = 'o';
        return grid;
    }

    /**
     * Validates a potential shift vector.
     * A shift is invalid if any 'o' would move onto a '.' cell within bounds.
     */
    private boolean isValidShift(char[][] grid, int n, int shiftRow, int shiftCol) {
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < n; c++) {
                if (grid[r][c] == 'o') {
                    int newR = r + shiftRow;
                    int newC = c + shiftCol;
                    if (newR >= 0 && newR < n && newC >= 0 && newC < n) {
                        if (grid[newR][newC] == '.') {
                            return false;
                        }
                    }
                }
            }
        }
        return true;
    }

    /**
     * Marks grid coordinates as covered if an 'o' shifts onto an 'x'.
     */
    private void markCoveredPositions(char[][] grid, int n, int shiftRow, int shiftCol, boolean[][] isCovered) {
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < n; c++) {
                if (grid[r][c] == 'o') {
                    int newR = r + shiftRow;
                    int newC = c + shiftCol;
                    if (newR >= 0 && newR < n && newC >= 0 && newC < n && grid[newR][newC] == 'x') {
                        isCovered[newR][newC] = true;
                    }
                }
            }
        }
    }

    /**
     * Checks whether every 'x' in the original grid has been successfully covered.
     */
    private boolean allTargetsCovered(char[][] grid, int n, boolean[][] isCovered) {
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < n; c++) {
                if (grid[r][c] == 'x' && !isCovered[r][c]) {
                    return false;
                }
            }
        }
        return true;
    }
}

