import java.io.*;
import java.util.*;

public class GridPlacementSolver {
    // Constants representing grid cell states
    private static final int EMPTY = 0;
    private static final int OBSTACLE = 1;
    private static final int SHAPE = 2;

    private FastScanner in;
    private PrintWriter out;

    public static void main(String[] args) {
        new GridPlacementSolver().run();
    }

    /**
     * Entry point for execution. Sets up I/O and handles the main solve flow.
     */
    public void run() {
        in = new FastScanner(System.in);
        out = new PrintWriter(new BufferedOutputStream(System.out));
        try {
            solve();
        } catch (IOException e) {
            out.println("Error during execution: " + e.getMessage());
        } finally {
            out.flush();
            out.close();
        }
    }

    /**
     * Core logic: reads input, finds valid placement, validates coverage, and outputs result.
     */
    private void solve() throws IOException {
        int n = in.nextInt();
        int[][] grid = new int[n][n];
        List<Point> shapePieces = new ArrayList<>();

        // Parse input grid and collect shape piece coordinates
        for (int i = 0; i < n; i++) {
            String row = in.next();
            for (int j = 0; j < n; j++) {
                char c = row.charAt(j);
                if (c == '.') {
                    grid[i][j] = EMPTY;
                } else if (c == 'x') {
                    grid[i][j] = OBSTACLE;
                } else if (c == 'o') {
                    grid[i][j] = SHAPE;
                    shapePieces.add(new Point(i, j));
                }
            }
        }

        int numShapePieces = shapePieces.size();
        int validOffsetRow = -1;
        int validOffsetCol = -1;
        boolean placementFound = false;

        // Iterate through all possible translation offsets
        for (int offsetRow = -n + 1; offsetRow < n; offsetRow++) {
            for (int offsetCol = -n + 1; offsetCol < n; offsetCol++) {
                int emptyCellsCovered = 0;

                // Check if placing the shape at this offset covers any empty cells
                for (Point piece : shapePieces) {
                    int newRow = piece.row + offsetRow;
                    int newCol = piece.col + offsetCol;

                    if (!isValidPosition(newRow, newCol, n)) {
                        continue;
                    }

                    if (grid[newRow][newCol] == EMPTY) {
                        emptyCellsCovered++;
                    }
                }

                // If no empty cells are covered, this is a valid placement
                if (emptyCellsCovered == 0) {
                    validOffsetRow = offsetRow;
                    validOffsetCol = offsetCol;
                    placementFound = true;
                    break;
                }
            }
            if (placementFound) {
                break;
            }
        }

        if (!placementFound) {
            out.println("NO");
            return;
        }

        // Verify that all obstacles are covered by the shape placement
        int[][] coverage = new int[n][n];
        for (Point piece : shapePieces) {
            int newRow = piece.row + validOffsetRow;
            int newCol = piece.col + validOffsetCol;
            if (isValidPosition(newRow, newCol, n)) {
                coverage[newRow][newCol] = 1;
            }
        }

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == OBSTACLE && coverage[i][j] == 0) {
                    out.println("NO");
                    return;
                }
            }
        }

        out.println("YES");
        printResult(n, shapePieces, validOffsetRow, validOffsetCol);
    }

    /**
     * Checks if coordinates are within the grid boundaries.
     */
    private boolean isValidPosition(int row, int col, int n) {
        return row >= 0 && col >= 0 && row < n && col < n;
    }

    /**
     * Constructs and prints the final result grid.
     */
    private void printResult(int n, List<Point> shapePieces, int offsetRow, int offsetCol) {
        int outSize = 2 * n - 1;
        char[][] resultGrid = new char[outSize][outSize];

        // Initialize with empty spaces
        for (int i = 0; i < outSize; i++) {
            Arrays.fill(resultGrid[i], '.');
        }

        // Mark covered obstacles as 'x'
        for (Point piece : shapePieces) {
            int newRow = piece.row + offsetRow;
            int newCol = piece.col + offsetCol;
            if (isValidPosition(newRow, newCol, n)) {
                // Map grid coordinates to output grid coordinates
                resultGrid[newRow + n - 1][newCol + n - 1] = 'x';
            }
        }

        // Place the shape marker at the center
        resultGrid[n - 1][n - 1] = 'o';

        // Output the grid
        for (int i = 0; i < outSize; i++) {
            out.println(resultGrid[i]);
        }
    }

    /**
     * Helper class to represent 2D coordinates.
     */
    private static class Point {
        final int row;
        final int col;

        Point(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    /**
     * Fast I/O helper for competitive programming style input.
     */
