import java.io.*;
import java.util.*;

public class GridVectorAnalyzer {

    public static void main(String[] args) throws IOException {
        // Use try-with-resources for automatic and safe resource cleanup
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
             PrintWriter out = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)))) {

            FastScanner scanner = new FastScanner(br);
            String token;

            // Read test cases until EOF instead of using Integer.MAX_VALUE
            while ((token = scanner.next()) != null) {
                int n = Integer.parseInt(token);
                char[][] grid = readGrid(br, n);

                boolean[][] attacked = new boolean[n][n];
                boolean[][] validVectors = new boolean[2 * n - 1][2 * n - 1];

                processGrid(grid, n, attacked, validVectors);

                if (allXCellsCovered(grid, attacked)) {
                    out.println("YES");
                } else {
                    out.println("NO");
                }

                printResultGrid(validVectors, n, out);
            }
            out.flush();
        }
    }

    /**
     * Reads the n x n character grid from the buffer.
     * Skips empty lines that may occur between test cases.
     */
    private static char[][] readGrid(BufferedReader br, int n) throws IOException {
        char[][] grid = new char[n][n];
        for (int i = 0; i < n; i++) {
            String line = br.readLine();
            while (line != null && line.trim().isEmpty()) {
                line = br.readLine();
            }
            if (line == null) break;
            for (int j = 0; j < n; j++) {
                grid[i][j] = line.charAt(j);
            }
        }
        return grid;
    }

    /**
     * Iterates through all possible translation vectors, 
     * validates them, and marks attacked cells.
     */
    private static void processGrid(char[][] grid, int n, boolean[][] attacked, boolean[][] validVectors) {
        int offset = n - 1;
        for (int dx = -offset; dx <= offset; dx++) {
            for (int dy = -offset; dy <= offset; dy++) {
                if (isValidTranslation(grid, n, dx, dy)) {
                    validVectors[dx + offset][dy + offset] = true;
                    markAttackedCells(grid, n, dx, dy, attacked);
                }
            }
        }
    }

    /**
     * Checks if translating all 'o' cells by (dx, dy) 
     * results in valid positions (within bounds and not on '.').
     */
    private static boolean isValidTranslation(char[][] grid, int n, int dx, int dy) {
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] != 'o') continue;
                int nx = i + dx;
                int ny = j + dy;
                if (nx < 0 || nx >= n || ny < 0 || ny >= n) continue;
                if (grid[nx][ny] == '.') {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Marks all cells that would be covered by a valid translation vector.
     */
    private static void markAttackedCells(char[][] grid, int n, int dx, int dy, boolean[][] attacked) {
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] != 'o') continue;
                int nx = i + dx;
                int ny = j + dy;
                if (nx >= 0 && nx < n && ny >= 0 && ny < n) {
                    attacked[nx][ny] = true;
                }
            }
        }
    }

    /**
     * Verifies that every 'x' cell in the grid has been marked as attacked.
     */
    private static boolean allXCellsCovered(char[][] grid, boolean[][] attacked) {
        for (int i = 0; i < grid.length; i++) {
            for (int j = 0; j < grid[i].length; j++) {
                if (grid[i][j] == 'x' && !attacked[i][j]) {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Prints the translation vector grid to the output.
     */
    private static void printResultGrid(boolean[][] validVectors, int n, PrintWriter out) {
        int offset = n - 1;
        for (int i = 0; i < validVectors.length; i++) {
            for (int j = 0; j < validVectors[i].length; j++) {
                if (i == offset && j == offset) {
                    out.print('o');
                } else if (validVectors[i][j]) {
                    out.print('x');
                } else {
                    out.print('.');
                }
            }
            out.println();
        }
    }

    /**
     * Lightweight tokenizer for fast whitespace-delimited input reading.
     */
    private static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner(BufferedReader br) {
            this.br = br;
        }

        public String next() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) return null;
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.StringTokenizer;

/**
 * Solves the WeirdChess problem by finding a valid translation for the 'o' pieces
 * that covers all 'x' cells in the original grid without landing on any '.'.
 */
public class WeirdChess {

    public static void main(String[] args) {
        InputReader reader = new InputReader(System.in);
        int n = reader.nextInt();
        char[][] grid = new char[n][n];
        List<Position> pieces = new ArrayList<>();

        // Parse input grid and collect piece positions
        for (int i = 0; i < n; i++) {
            String line = reader.next();
            grid[i] = line.toCharArray();
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 'o') {
                    pieces.add(new Position(i, j));
                }
            }
        }

        // Find and apply a valid translation
        char[][] resultGrid = solve(n, grid, pieces);

        if (resultGrid == null) {
            System.out.println("NO");
        } else {
            System.out.println("YES");
            printGrid(resultGrid);
        }
    }

    /**
     * Searches for the first translation (dx, dy) that satisfies all constraints.
     */
    private static char[][] solve(int n, char[][] grid, List<Position> pieces) {
        int resultSize = 2 * n - 1;
        int centerOffset = n - 1;

        for (int dx = -n + 1; dx < n; dx++) {
            for (int dy = -n + 1; dy < n; dy++) {
                if (isValidTranslation(n, grid, pieces, dx, dy)) {
                    return applyTranslation(n, grid, pieces, resultSize, centerOffset, dx, dy);
                }
            }
        }
        return null;
    }

    /**
     * Checks if translating all pieces by (dx, dy) avoids landing on any '.'.
     */
    private static boolean isValidTranslation(int n, char[][] grid, List<Position> pieces, int dx, int dy) {
        for (Position p : pieces) {
            int nx = p.row + dx;
            int ny = p.col + dy;
            // Only check bounds where the piece would land inside the grid
            if (nx >= 0 && nx < n && ny >= 0 && ny < n) {
                if (grid[nx][ny] == '.') {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Applies the translation, verifies coverage of all 'x' cells, and constructs the result grid.
     */
    private static char[][] applyTranslation(int n, char[][] grid, List<Position> pieces, 
                                             int resultSize, int centerOffset, int dx, int dy) {
        char[][] resultGrid = new char[resultSize][resultSize];
        for (char[] row : resultGrid) {
            Arrays.fill(row, '.');
        }

        boolean[][] covered = new boolean[n][n];
        int targetX = centerOffset + dx;
        int targetY = centerOffset + dy;

        // Mark which original cells are covered by the translated pieces
        for (Position p : pieces) {
            int nx = p.row + dx;
            int ny = p.col + dy;
            if (nx >= 0 && nx < n && ny >= 0 && ny < n) {
                covered[nx][ny] = true;
            }
        }

        // Mark the translated position in the result grid
        resultGrid[targetX][targetY] = 'x';

        // Verify that every 'x' in the original grid is covered by this translation
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 'x' && !covered[i][j]) {
                    return null; // Coverage constraint failed
                }
            }
        }

        // Place the piece at the center of the result grid as specified
        resultGrid[centerOffset][centerOffset] = 'o';
        return resultGrid;
    }

    /**
     * Prints the 2D character grid to standard output efficiently.
     */
    private static void printGrid(char[][] grid) {
        StringBuilder sb = new StringBuilder();
        for (char[] row : grid) {
            sb.append(row).append('\n');
        }
        System.out.print(sb);
    }

    /**
     * Lightweight immutable class representing a 2D grid coordinate.
     * Replaces java.awt.Point to avoid unnecessary AWT dependencies.
     */
    static class Position {
        final int row;
        final int col;

        Position(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    /**
     * Fast input reader optimized for whitespace-delimited tokens.
     */
    static class InputReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public InputReader(InputStream stream) {
            this.reader = new BufferedReader(new InputStreamReader(stream));
            this.tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input", e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            String token = next();
            if (token == null) throw new RuntimeException("Unexpected end of input");
            return Integer.parseInt(token);
        }
    }
}

import java.util.Arrays;
import java.util.Scanner;

/**
 * Analyzes grid movements and simulates piece transitions based on specific rules.
 * Refactored for improved maintainability, readability, and adherence to Java best practices.
 */
public class GridMovementAnalyzer {

    // Constants to replace magic characters and improve readability
    private static final char EMPTY = '.';
    private static final char PIECE_O = 'o';
    private static final char PIECE_X = 'x';
    private static final char PIECE_Y = 'y';
    private static final char RESULT_GRID_PLACEHOLDER = '.';
    private static final char RESULT_GRID_MARK = 'x';
    private static final char RESULT_GRID_CENTER = 'o';

    public static void main(String[] args) {
        // Use try-with-resources to ensure the Scanner is properly closed
        try (Scanner scanner = new Scanner(System.in)) {
            if (!scanner.hasNextInt()) {
                return;
            }
            int size = scanner.nextInt();
            char[][] initialBoard = readInputBoard(scanner, size);

            String output = processGrid(size, initialBoard);
            System.out.println(output);
        }
    }

    /**
     * Reads the n x n board from standard input.
     */
    private static char[][] readInputBoard(Scanner scanner, int size) {
        char[][] board = new char[size][size];
        for (int i = 0; i < size; i++) {
            board[i] = scanner.next().toCharArray();
        }
        return board;
    }

    /**
     * Core logic: creates the result grid, simulates movements, and determines the final output.
     */
    private static String processGrid(int size, char[][] initialBoard) {
        char[][] resultGrid = createResultGrid(size);
        // Clone the board to prevent unintended side-effects on the original input array
        char[][] currentBoard = cloneBoard(initialBoard);

        int centerIndex = size - 1;
        int resultGridSize = 2 * size - 1;

        for (int row = 0; row < resultGridSize; row++) {
            for (int col = 0; col < resultGridSize; col++) {
                // Skip the center position as it's pre-filled
                if (row == centerIndex && col == centerIndex) {
                    continue;
                }

                int deltaRow = row - centerIndex;
                int deltaCol = col - centerIndex;

                // If no 'o' can move to an empty spot, the move is allowed
                if (!canAnyPieceMove(currentBoard, deltaRow, deltaCol)) {
                    simulateMove(currentBoard, deltaRow, deltaCol);
                    resultGrid[row][col] = RESULT_GRID_MARK;
                }
            }
        }

        // Check if any 'x' pieces remain on the board
        if (hasRemainingPieces(currentBoard, PIECE_X)) {
            return "NO";
        } else {
            StringBuilder output = new StringBuilder("YES\n");
            for (char[] row : resultGrid) {
                output.append(new String(row)).append('\n');
            }
            return output.toString().trim();
        }
    }

    /**
     * Creates and initializes the 2n-1 x 2n-1 result grid.
     */
    private static char[][] createResultGrid(int size) {
        int gridSize = 2 * size - 1;
        char[][] grid = new char[gridSize][gridSize];
        for (char[] row : grid) {
            Arrays.fill(row, RESULT_GRID_PLACEHOLDER);
        }
        grid[size - 1][size - 1] = RESULT_GRID_CENTER;
        return grid;
    }

    /**
     * Checks if any 'o' piece can successfully move to an empty cell in the given direction.
     */
    private static boolean canAnyPieceMove(char[][] board, int deltaRow, int deltaCol) {
        for (int r = 0; r < board.length; r++) {
            for (int c = 0; c < board[0].length; c++) {
                if (board[r][c] == PIECE_O) {
                    int targetR = r + deltaRow;
                    int targetC = c + deltaCol;
                    if (isValidTarget(board, targetR, targetC) && board[targetR][targetC] == EMPTY) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Validates if the target coordinates are within the board boundaries.
     */
    private static boolean isValidTarget(char[][] board, int r, int c) {
        return r >= 0 && r < board.length && c >= 0 && c < board[0].length;
    }

    /**
     * Simulates a move by replacing 'x' pieces at valid target positions with 'y'.
     */
    private static void simulateMove(char[][] board, int deltaRow, int deltaCol) {
        for (int r = 0; r < board.length; r++) {
            for (int c = 0; c < board[0].length; c++) {
                if (board[r][c] == PIECE_O) {
                    int targetR = r + deltaRow;
                    int targetC = c + deltaCol;
                    if (isValidTarget(board, targetR, targetC) && board[targetR][targetC] == PIECE_X) {
                        board[targetR][targetC] = PIECE_Y;
                    }
                }
            }
        }
    }

    /**
     * Checks if the specified character still exists anywhere on the board.
     */
    private static boolean hasRemainingPieces(char[][] board, char targetChar) {
        for (char[] row : board) {
            for (char cell : row) {
                if (cell == targetChar) {
                    return true;
                }
            }
        }
        return false;
    }

    /**
     * Creates a deep copy of the 2D character array to avoid mutating the original input.
     */
    private static char[][] cloneBoard(char[][] original) {
        char[][] clone = new char[original.length][original[0].length];
        for (int i = 0; i < original.length; i++) {
            clone[i] = Arrays.copyOf(original[i], original[i].length);
        }
        return clone;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
