import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.StringTokenizer;

/**
 * Entry point for the solution.
 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        FastScanner in = new FastScanner(inputStream);
        PrintWriter out = new PrintWriter(outputStream);

        TaskD solver = new TaskD();
        solver.solve(in, out);

        out.flush();
        out.close();
    }
}

/**
 * Core logic for solving the grid transformation problem.
 */
class TaskD {

    /**
     * Solves the problem by reading input, constructing the answer grid,
     * validating it, and writing the result.
     */
    public void solve(FastScanner in, PrintWriter out) {
        int n = in.nextInt();
        // 1-based indexing with padding for boundary checks
        char[][] grid = new char[n + 2][n + 2];
        List<Point> pieces = new ArrayList<>();

        // Read grid and collect positions of 'o'
        for (int i = 1; i <= n; i++) {
            String row = in.next();
            for (int j = 1; j <= n; j++) {
                grid[i][j] = row.charAt(j - 1);
                if (grid[i][j] == 'o') {
                    pieces.add(new Point(i, j));
                }
            }
        }

        Point[] piecePositions = pieces.toArray(new Point[0]);
        int numPieces = piecePositions.length;

        // Answer grid size is (2*N - 1) to accommodate all translations
        char[][] ans = new char[2 * n - 1][2 * n - 1];

        // Initialize with 'x'
        for (char[] row : ans) {
            Arrays.fill(row, 'x');
        }
        ans[n - 1][n - 1] = 'o'; // Center position

        // Determine valid positions for 'o' in the answer grid
        for (int i = 0; i < 2 * n - 1; i++) {
            for (int j = 0; j < 2 * n - 1; j++) {
                if (i == n - 1 && j == n - 1) continue;

                int dx = i - (n - 1);
                int dy = j - (n - 1);
                boolean isValid = false;

                // Check if translating any piece to (i, j) lands on a '.' in the original grid
                for (Point p : piecePositions) {
                    int x = p.x + dx;
                    int y = p.y + dy;
                    if (x >= 1 && x <= n && y >= 1 && y <= n && grid[x][y] == '.') {
                        isValid = true;
                        break;
                    }
                }

                if (isValid) {
                    ans[i][j] = '.';
                }
            }
        }

        // Validate the constructed solution
        if (isSolutionValid(n, ans, grid, piecePositions)) {
            out.println("YES");
            StringBuilder sb = new StringBuilder();
            for (int i = 0; i < 2 * n - 1; i++) {
                sb.append(ans[i]);
                sb.append('\n');
            }
            out.print(sb);
        } else {
            out.println("NO");
        }
    }

    /**
     * Validates that every 'x' in the original grid can be mapped to an 'x'
     * in the answer grid via translation by one of the collected pieces.
     */
    private boolean isSolutionValid(int n, char[][] ans, char[][] grid, Point[] piecePositions) {
        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= n; j++) {
                if (grid[i][j] == 'x') {
                    boolean matched = false;
                    for (Point p : piecePositions) {
                        int dx = i - p.x;
                        int dy = j - p.y;
                        if (ans[n - 1 + dx][n - 1 + dy] == 'x') {
                            matched = true;
                            break;
                        }
                    }
                    if (!matched) {
                        return false;
                    }
                }
            }
        }
        return true;
    }

    /**
     * Immutable point representation for grid coordinates.
     */
    private static class Point {
        final int x;
        final int y;

        Point(int x, int y) {
            this.x = x;
            this.y = y;
        }
    }
}

