import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

public class PatternChecker {
    private FastScanner scanner;
    private PrintWriter writer;

    /**
     * Entry point for the application. Sets up I/O streams and executes the solution.
     */
    public void run() {
        scanner = new FastScanner(System.in);
        writer = new PrintWriter(System.out);
        try {
            solve();
        } finally {
            writer.flush();
        }
    }

    /**
     * Orchestrates the solution: reads input, processes the pattern, validates, and prints output.
     */
    private void solve() {
        int n = scanner.nextInt();
        char[][] input = readInput(n);
        char[][] answerGrid = initializeAnswerGrid(n);
        List<Point> oPositions = extractOPositions(n, input);
        computePatternOffsets(n, input, answerGrid);
        boolean isValid = validatePattern(n, input, oPositions, answerGrid);

        if (isValid) {
            writer.println("YES");
            printGrid(answerGrid);
        } else {
            writer.println("NO");
        }
    }

    /**
     * Reads the n x n character grid from input.
     */
    private char[][] readInput(int n) {
        char[][] grid = new char[n][];
        for (int i = 0; i < n; i++) {
            grid[i] = scanner.next().toCharArray();
        }
        return grid;
    }

    /**
     * Creates and initializes the answer grid of size (2n-1) x (2n-1).
     */
    private char[][] initializeAnswerGrid(int n) {
        int size = 2 * n - 1;
        char[][] grid = new char[size][size];
        int center = n - 1;

        for (int i = 0; i < size; i++) {
            Arrays.fill(grid[i], 'x');
        }
        grid[center][center] = 'o';
        return grid;
    }

    /**
     * Collects coordinates of all 'o' cells in the input grid.
     */
    private List<Point> extractOPositions(int n, char[][] input) {
        List<Point> positions = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (input[i][j] == 'o') {
                    positions.add(new Point(i, j));
                }
            }
        }
        return positions;
    }

    /**
     * Computes relative offsets of '.' cells with respect to each 'o' cell
     * and marks them in the answer grid.
     */
    private void computePatternOffsets(int n, char[][] input, char[][] answerGrid) {
        int center = n - 1;
        for (int i1 = 0; i1 < n; i1++) {
            for (int j1 = 0; j1 < n; j1++) {
                if (input[i1][j1] != 'o') continue;

                for (int i2 = 0; i2 < n; i2++) {
                    for (int j2 = 0; j2 < n; j2++) {
                        if (input[i2][j2] == '.') {
                            answerGrid[center + i2 - i1][center + j2 - j1] = '.';
                        }
                    }
                }
            }
        }
    }

    /**
     * Validates if the computed pattern correctly covers all '.' positions 
     * when translated by each 'o' position in the input grid.
     */
    private boolean validatePattern(int n, char[][] input, List<Point> oPositions, char[][] answerGrid) {
        int center = n - 1;
        int size = 2 * n - 1;

        // Collect relative offsets of '.' cells in the answer grid
        int[] relRows = new int[n * n];
        int[] relCols = new int[n * n];
        int count = 0;
        for (int i = 0; i < size; i++) {
            for (int j = 0; j < size; j++) {
                if (answerGrid[i][j] == '.') {
                    relRows[count] = i - center;
                    relCols[count] = j - center;
                    count++;
                }
            }
        }

        char[][] checkGrid = new char[n][n];
        for (int i = 0; i < n; i++) {
            Arrays.fill(checkGrid[i], '.');
        }

        // Translate the pattern by each 'o' position and mark valid cells
        for (Point oPos : oPositions) {
            for (int k = 0; k < count; k++) {
                int ni = oPos.row + relRows[k];
                int nj = oPos.col + relCols[k];
                if (ni >= 0 && ni < n && nj >= 0 && nj < n && checkGrid[ni][nj] != 'o') {
                    checkGrid[ni][nj] = 'x';
                }
            }
        }

        // Compare generated pattern with original input
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (checkGrid[i][j] != input[i][j]) {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Prints the final answer grid row by row.
     */
    private void printGrid(char[][] grid) {
        for (char[] row : grid) {
            writer.println(new String(row));
        }
    }

    /**
     * Immutable value class representing a 2D coordinate.
     */
    private static class Point {
        final int row;
        final int col;

        Point(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    /**
     * High-performance scanner for competitive programming style input.
     */
    private static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input", e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            String s = next();
            if (s == null) throw new RuntimeException("Unexpected end of input");
            return Integer.parseInt(s);
        }
    }

    public static void main(String[] args) {
        new PatternChecker().run();
    }
}

