/**
 * Solves the grid placement problem by evaluating all valid shifts,
 * marking covered positions, and verifying constraints.
 */
class TaskD {

    /**
     * Main entry point for solving the task.
     */
    public void solve(Reader in, PrintWriter out) {
        int n = in.nextInt();
        char[][] grid = new char[n][n];
        for (int i = 0; i < n; i++) {
            grid[i] = in.next().toCharArray();
        }

        int gridSize = 2 * n - 1;
        char[][] ans = new char[gridSize][gridSize];
        boolean[][] beat = new boolean[n][n];

        // Initialize the answer grid with '.'
        for (char[] row : ans) {
            Arrays.fill(row, '.');
        }
        ans[n - 1][n - 1] = 'o';

        // Try all possible shifts (dx, dy) from -(n-1) to (n-1)
        for (int shiftX = -(n - 1); shiftX < n; shiftX++) {
            for (int shiftY = -(n - 1); shiftY < n; shiftY++) {
                // Skip the center position as it's already set to 'o'
                if (shiftX == 0 && shiftY == 0) {
                    continue;
                }

                if (isValidPlacement(grid, n, shiftX, shiftY)) {
                    markBeaten(grid, n, shiftX, shiftY, beat);
                    ans[n - 1 + shiftX][n - 1 + shiftY] = 'x';
                }
            }
        }

        // Verify that every 'x' in the original grid is covered by a shifted 'o'
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 'x' && !beat[i][j]) {
                    out.println("NO");
                    return;
                }
            }
        }

        out.println("YES");
        printGrid(out, ans);
    }

    /**
     * Checks if placing an 'x' at the shifted position is valid.
     * A placement is invalid if any 'o' in the original grid, when shifted,
     * lands on a '.' in the original grid.
     */
    private boolean isValidPlacement(char[][] grid, int n, int shiftX, int shiftY) {
        for (int x = 0; x < n; x++) {
            for (int y = 0; y < n; y++) {
                if (grid[x][y] == 'o' && isWithinBounds(n, x + shiftX, y + shiftY)) {
                    if (grid[x + shiftX][y + shiftY] == '.') {
                        return false;
                    }
                }
            }
        }
        return true;
    }

    /**
     * Marks positions in the 'beat' array that are covered by a shifted 'o'.
     */
    private void markBeaten(char[][] grid, int n, int shiftX, int shiftY, boolean[][] beat) {
        for (int x = 0; x < n; x++) {
            for (int y = 0; y < n; y++) {
                if (grid[x][y] == 'o' && isWithinBounds(n, x + shiftX, y + shiftY)) {
                    if (grid[x + shiftX][y + shiftY] == 'x') {
                        beat[x + shiftX][y + shiftY] = true;
                    }
                }
            }
        }
    }

    /**
     * Checks if coordinates are within the bounds of the n x n grid.
     */
    private boolean isWithinBounds(int n, int x, int y) {
        return x >= 0 && x < n && y >= 0 && y < n;
    }

    /**
     * Prints the 2D character grid to the output stream.
     */
    private void printGrid(PrintWriter out, char[][] grid) {
        for (char[] row : grid) {
            out.println(row);
        }
    }
}

