import java.io.*;
import java.util.*;

public class Solution {
    // Configuration constants
    private static final boolean USE_FILE_INPUT = false;
    private static final String INPUT_FILE = "input.txt";
    private static final int MAX_SHIFT_RANGE = 50;

    /**
     * Main entry point for the solution logic.
     */
    public void solve(InputReader in, PrintWriter out) {
        int n = in.nextInt();
        char[][] grid = new char[n][];
        for (int i = 0; i < n; i++) {
            grid[i] = in.next().toCharArray();
        }

        // Preallocate primitive arrays to avoid auto-boxing overhead
        int maxShifts = (2 * MAX_SHIFT_RANGE + 1) * (2 * MAX_SHIFT_RANGE + 1);
        int[] validShiftsX = new int[maxShifts];
        int[] validShiftsY = new int[maxShifts];
        int shiftCount = 0;

        // Find all valid translation shifts
        for (int dx = -MAX_SHIFT_RANGE; dx <= MAX_SHIFT_RANGE; dx++) {
            for (int dy = -MAX_SHIFT_RANGE; dy <= MAX_SHIFT_RANGE; dy++) {
                if (isValidShift(grid, n, dx, dy)) {
                    validShiftsX[shiftCount] = dx;
                    validShiftsY[shiftCount] = dy;
                    shiftCount++;
                }
            }
        }

        // Verify that every 'x' can be covered by a valid shift from an 'o'
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < n; c++) {
                if (grid[r][c] == 'x') {
                    if (!isCoveredByValidShift(grid, n, r, c, validShiftsX, validShiftsY, shiftCount)) {
                        out.println("NO");
                        return;
                    }
                }
            }
        }

        out.println("YES");
        printOutputGrid(out, n, validShiftsX, validShiftsY, shiftCount);
    }

    /**
     * Checks if shifting the grid by (dx, dy) causes any 'o' to land on a '.'.
     */
    private boolean isValidShift(char[][] grid, int n, int dx, int dy) {
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < n; c++) {
                if (grid[r][c] == 'o') {
                    int newR = r + dx;
                    int newC = c + dy;
                    // Only validate bounds if the shifted position stays within the grid
                    if (newR >= 0 && newR < n && newC >= 0 && newC < n) {
                        if (grid[newR][newC] == '.') {
                            return false;
                        }
                    }
                }
            }
        }
        return true;
    }

    /**
     * Checks if a cell (r, c) containing 'x' can be reached by shifting an 'o' 
     * using any of the valid shifts.
     */
    private boolean isCoveredByValidShift(char[][] grid, int n, int r, int c,
                                          int[] validShiftsX, int[] validShiftsY, int shiftCount) {
        for (int i = 0; i < shiftCount; i++) {
            int backR = r - validShiftsX[i];
            int backC = c - validShiftsY[i];
            if (backR >= 0 && backR < n && backC >= 0 && backC < n) {
                if (grid[backR][backC] == 'o') {
                    return true;
                }
            }
        }
        return false;
    }

    /**
     * Prints the resulting (2n-1)x(2n-1) grid.
     */
    private void printOutputGrid(PrintWriter out, int n, int[] validShiftsX, int[] validShiftsY, int shiftCount) {
        int size = 2 * n - 1;
        int center = n - 1;

        // Use a boolean matrix for O(1) lookup during printing instead of re-iterating shifts
        boolean[][] isShift = new boolean[size][size];
        for (int i = 0; i < shiftCount; i++) {
            int r = center + validShiftsX[i];
            int c = center + validShiftsY[i];
            if (r >= 0 && r < size && c >= 0 && c < size) {
                isShift[r][c] = true;
            }
        }

        for (int r = 0; r < size; r++) {
            for (int c = 0; c < size; c++) {
                if (r == center && c == center) {
                    out.print('o');
                } else if (isShift[r][c]) {
                    out.print('x');
                } else {
                    out.print('.');
                }
            }
            out.println();
        }
    }

    public static void main(String[] args) {
        try (PrintWriter out = new PrintWriter(System.out)) {
            InputStream inStream = USE_FILE_INPUT ? new FileInputStream(INPUT_FILE) : System.in;
            InputReader in = new InputReader(inStream);

            Solution solution = new Solution();
            solution.solve(in, out);
        } catch (IOException e) {
            throw new RuntimeException("I/O error occurred", e);
        }
    }

    /**
     * Fast I/O helper class commonly used in competitive programming.
     */
    private static class InputReader {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }

        public double nextDouble() {
            return Double.parseDouble(next());
        }

        public char nextCharacter() {
            return next().charAt(0);
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Refactored solver for the diagonal board puzzle.
 * 
 * Key Improvements:
 * - Renamed class and methods to reflect domain semantics.
 * - Separated concerns: I/O setup, parsing, algorithm logic, and output formatting.
 * - Removed magic numbers, unused imports, and redundant code.
 * - Simplified shift generation to eliminate duplication and improve readability.
 * - Used buffered I/O and StringBuilder-friendly output for performance.
 * - Added comprehensive JavaDoc and inline comments.
 */
public class DiagonalBoardSolver {

    /** Immutable coordinate/shift holder */
    private static final class Point {
        final int x;
        final int y;

        Point(int x, int y) {
            this.x = x;
            this.y = y;
        }
    }

    public static void main(String[] args) {
        try {
            Reader reader = resolveReader();
            Writer writer = resolveWriter();

            new DiagonalBoardSolver().solve(reader, writer);
            writer.flush();
        } catch (IOException e) {
            e.printStackTrace();
            System.exit(1);
        }
    }

    /** Resolves input source based on file existence */
    private static Reader resolveReader() throws IOException {
        File inputFile = new File("file.in");
        return inputFile.exists() 
                ? new BufferedReader(new FileReader(inputFile)) 
                : new BufferedReader(new InputStreamReader(System.in));
    }

    /** Resolves output destination based on file existence */
    private static Writer resolveWriter() throws IOException {
        File outputFile = new File("file.out");
        return outputFile.exists() 
                ? new BufferedWriter(new FileWriter(outputFile)) 
                : new BufferedWriter(new OutputStreamWriter(System.out));
    }

    /** Orchestrates the solving process */
    private void solve(Reader reader, Writer writer) throws IOException {
        FastScanner scanner = new FastScanner(reader);
        PrintWriter out = new PrintWriter(writer);

        String nStr = scanner.next();
        if (nStr == null) {
            out.println("NO");
            out.flush();
            return;
        }

        int n = Integer.parseInt(nStr);
        char[][] board = new char[n][];
        List<Point> oPositions = new ArrayList<>();

        for (int i = 0; i < n; i++) {
            String row = scanner.next();
            board[i] = row.toCharArray();
            for (int j = 0; j < n; j++) {
                if (board[i][j] == 'o') {
                    oPositions.add(new Point(i, j));
                }
            }
        }

        List<Point> validShifts = findValidShifts(n, board, oPositions);
        boolean[][] possibleX = computePossibleXPositions(n, oPositions, validShifts);

        if (!isValidConfiguration(n, board, possibleX)) {
            out.println("NO");
        } else {
            out.println("YES");
            int boardSize = 2 * n - 1;
            int center = n - 1;
            char[][] result = new char[boardSize][boardSize];
            for (char[] row : result) {
                Arrays.fill(row, '.');
            }
            result[center][center] = 'o';

            for (Point shift : validShifts) {
                result[center + shift.x][center + shift.y] = 'x';
            }

            for (char[] row : result) {
                out.println(new String(row));
            }
        }
        out.flush();
    }

    /** Finds all diagonal shifts that keep 'o's on '.' cells within bounds */
    private List<Point> findValidShifts(int n, char[][] board, List<Point> oPositions) {
        List<Point> validShifts = new ArrayList<>();
        int maxShift = n - 1;

        for (int dx = -maxShift; dx <= maxShift; dx++) {
            for (int dy : new int[]{dx, -dx}) {
                if (dx == 0 && dy == 0) continue; // Skip zero shift

                boolean allValid = true;
                for (Point o : oPositions) {
                    int nx = o.x + dx;
                    int ny = o.y + dy;
                    if (!isValid(nx, ny, n) || board[nx][ny] != '.') {
                        allValid = false;
                        break;
                    }
                }
                if (allValid) {
                    validShifts.add(new Point(dx, dy));
                }
            }
        }
        return validShifts;
    }

    /** Marks all grid positions that could potentially become 'x' based on valid shifts */
    private boolean[][] computePossibleXPositions(int n, List<Point> oPositions, List<Point> validShifts) {
        boolean[][] possibleX = new boolean[n][n];
        for (Point shift : validShifts) {
            for (Point o : oPositions) {
                possibleX[o.x + shift.x][o.y + shift.y] = true;
            }
        }
        return possibleX;
    }

    /** Validates that the original board matches the computed possible positions */
    private boolean isValidConfiguration(int n, char[][] board, boolean[][] possibleX) {
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (board[i][j] == 'x' && !possibleX[i][j]) return false;
                if (board[i][j] == '.' && possibleX[i][j]) return false;
            }
        }
        return true;
    }

    /** Checks if coordinates are within grid bounds */
    private boolean isValid(int x, int y, int n) {
        return x >= 0 && x < n && y >= 0 && y < n;
    }

    /** Lightweight token-based scanner for competitive programming style input */
    private static class FastScanner {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        FastScanner(Reader reader) {
            this.reader = new BufferedReader(reader);
            this.tokenizer = new StringTokenizer("");
        }

        String next() throws IOException {
            while (!tokenizer.hasMoreTokens()) {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.ArrayList;
import java.util.List;
import java.util.StringTokenizer;

/**
 * Refactored version of WeirdChess.
 * 
 * Improvements:
 * 1. Readability: Descriptive variable names (board, safeOffsets, center).
 * 2. Structure: Logic separated into distinct steps and helper methods.
 * 3. Performance: Pre-caching 'o' positions to reduce redundant board scans.
 * 4. Robustness: Improved input handling and resource management.
 */
public class WeirdChess {

    public static void main(String[] args) {
        // Initialize I/O resources
        FastScanner scanner = new FastScanner(new BufferedReader(new InputStreamReader(System.in)));
        PrintWriter out = new PrintWriter(System.out);

        try {
            // Execute the solution logic
            new WeirdChess().solve(scanner, out);
        } finally {
            // Ensure output is flushed and closed
            out.flush();
            out.close();
        }
    }

    private void solve(FastScanner scanner, PrintWriter out) {
        // 1. Read Input
        String nStr = scanner.next();
        if (nStr == null) return;

        int n = Integer.parseInt(nStr);
        char[][] board = new char[n][n];

        for (int i = 0; i < n; i++) {
            String rowStr = scanner.next();
            if (rowStr != null) {
                // Fill the board row. Assuming valid input format where string length matches n.
                // Using toCharArray is cleaner than character-by-character assignment.
                board[i] = rowStr.toCharArray();
            }
        }

        // 2. Pre-process 'o' positions
        // Storing coordinates as int[]{row, col} to optimize subsequent nested loops.
        List<int[]> oPositions = new ArrayList<>();
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < n; c++) {
                if (board[r][c] == 'o') {
                    oPositions.add(new int[]{r, c});
                }
            }
        }

        // 3. Calculate Safe Offsets
        // The problem logic maps board coordinates to an offset space centered at (n-1, n-1).
        // The size of this space is (2n-1) x (2n-1).
        int center = n - 1;
        boolean[][] safeOffsets = new boolean[2 * n - 1][2 * n - 1];

        // The center position (relative to itself) is always safe
        safeOffsets[center][center] = true;

        // Mark offsets based on '.' cells relative to 'o' cells.
        // If a '.' is at (r, c) and an 'o' is at (or, oc),
        // the vector is (r - or, c - oc).
        // We mark the corresponding position in safeOffsets.
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < n; c++) {
                if (board[r][c] == '.') {
                    for (int[] oPos : oPositions) {
                        int dr = r - oPos[0];
                        int dc = c - oPos[1];

                        // Map vector to grid coordinates in the offset space
                        int safeR = center + dr;
                        int safeC = center + dc;

                        // Bounds check (though logic implies valid range)
                        if (safeR >= 0 && safeR < 2 * n - 1 && safeC >= 0 && safeC < 2 * n - 1) {
                            safeOffsets[safeR][safeC] = true;
                        }
                    }
                }
            }
        }

        // 4. Validate 'x' positions
        // An 'x' at (r, c) is valid if there exists at least one 'o' at (or, oc)
        // such that the vector from 'o' to 'x' is NOT in the safeOffsets set.
        // If for all 'o's, the vector IS in safeOffsets, the 'x' is invalid.
        boolean allXValid = true;

        for (int r = 0; r < n; r++) {
            for (int c = 0; c < n; c++) {
                if (board[r][c] == 'x') {
                    boolean conditionMet = false; // Corresponds to 'ok' in original logic

                    for (int[] oPos : oPositions) {
                        int dr = r - oPos[0];
                        int dc = c - oPos[1];

                        int safeR = center + dr;
                        int safeC = center + dc;

                        // If the relative position is NOT safe, the condition is met
                        if (!safeOffsets[safeR][safeC]) {
                            conditionMet = true;
                            break;
                        }
                    }

                    // If condition was never met, this 'x' makes the board invalid
                    if (!conditionMet) {
                        allXValid = false;
                        break;
                    }
                }
            }
            if (!allXValid) break;
        }

        // 5. Output Results
        if (allXValid) {
            out.println("YES");
            printResultGrid(out, n, center, safeOffsets);
        } else {
            out.println("NO");
        }
    }

    private void printResultGrid(PrintWriter out, int n, int center, boolean[][] safeOffsets) {
        int size = 2 * n - 1;
        for (int r = 0; r < size; r++) {
            for (int c = 0; c < size; c++) {
                if (r == center && c == center) {
                    out.print('o');
                } else {
                    out.print(safeOffsets[r][c] ? '.' : 'x');
                }
            }
            out.println();
        }
    }

    /**
     * FastScanner helper class for efficient input reading.
     */
    static class FastScanner {
        BufferedReader br;
        StringTokenizer st;

        public FastScanner(BufferedReader br) {
            this.br = br;
        }

        public String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    e.printStackTrace();
                    return null;
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            String s = next();
            if (s == null) return 0;
            return Integer.parseInt(s);
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayList;
import java.util.List;

public class Main {

    /**
     * Represents a 2D coordinate on the board.
     */
    private static class Point {
        final int row;
        final int col;

        Point(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    public static void main(String[] args) throws IOException {
        // Use try-with-resources for automatic resource cleanup
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(System.in))) {
            String line = reader.readLine();
            if (line == null || line.trim().isEmpty()) {
                return;
            }

            int n = Integer.parseInt(line.trim());
            char[][] board = new char[n][];
            List<Point> oPositions = new ArrayList<>();

            // Read board and collect 'o' coordinates
            for (int i = 0; i < n; i++) {
                String row = reader.readLine();
                if (row == null) break;
                board[i] = row.toCharArray();
                for (int j = 0; j < n; j++) {
                    if (board[i][j] == 'o') {
                        oPositions.add(new Point(i, j));
                    }
                }
            }

            solve(n, board, oPositions);
        }
    }

    /**
     * Orchestrates the core logic: validation, coverage marking, and output.
     */
    private static void solve(int n, char[][] board, List<Point> oPositions) {
        boolean[][] isCovered = new boolean[n][n];
        boolean[][] validShifts = new boolean[2 * n][2 * n];
        int indexOffset = n; // Maps negative shift values to positive array indices

        // Evaluate all possible (dx, dy) shifts
        for (int dx = -(n - 1); dx <= n - 1; dx++) {
            for (int dy = -(n - 1); dy <= n - 1; dy++) {
                if (isShiftValid(n, board, oPositions, dx, dy)) {
                    markCoveredCells(n, oPositions, dx, dy, isCovered);
                    validShifts[dx + indexOffset][dy + indexOffset] = true;
                }
            }
        }

        if (!allXsCovered(n, board, isCovered)) {
            System.out.println("NO");
        } else {
            System.out.println("YES");
            printResultBoard(n, validShifts, indexOffset);
        }
    }

    /**
     * Checks if shifting the 'o' pattern by (dx, dy) would overlap any '.' cell.
     */
    private static boolean isShiftValid(int n, char[][] board, List<Point> oPositions, int dx, int dy) {
        for (Point o : oPositions) {
            int newRow = o.row + dx;
            int newCol = o.col + dy;
            if (newRow >= 0 && newRow < n && newCol >= 0 && newCol < n) {
                if (board[newRow][newCol] == '.') {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Marks the cells on the board that would be covered by the shifted 'o' pattern.
     */
    private static void markCoveredCells(int n, List<Point> oPositions, int dx, int dy, boolean[][] isCovered) {
        for (Point o : oPositions) {
            int newRow = o.row + dx;
            int newCol = o.col + dy;
            if (newRow >= 0 && newRow < n && newCol >= 0 && newCol < n) {
                isCovered[newRow][newCol] = true;
            }
        }
    }

    /**
     * Verifies that every 'x' on the board is covered by at least one valid shift.
     */
    private static boolean allXsCovered(int n, char[][] board, boolean[][] isCovered) {
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (board[i][j] == 'x' && !isCovered[i][j]) {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Constructs and prints the final result board.
     */
    private static void printResultBoard(int n, boolean[][] validShifts, int indexOffset) {
        int size = 2 * n - 1;
        char[][] result = new char[size][size];

        // Initialize board with '.'
        for (int i = 0; i < size; i++) {
            for (int j = 0; j < size; j++) {
                result[i][j] = '.';
            }
        }

        // Map valid shifts to the result board coordinates
        for (int i = 1; i < 2 * n; i++) {
            for (int j = 1; j < 2 * n; j++) {
                if (validShifts[i][j]) {
                    result[i - 1][j - 1] = 'x';
                }
            }
        }

        // Place the center 'o'
        result[n - 1][n - 1] = 'o';

        // Efficiently build and print the output
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < size; i++) {
            sb.append(result[i]).append('\n');
        }
        System.out.print(sb);
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

/**
 * Task D: Grid shift validation and transformation.
 * 
 * Refactoring highlights:
 * - Extracted logical phases into dedicated methods for single responsibility.
 * - Replaced magic index calculations with clear variables and bounds-checking helper.
 * - Improved FastScanner to properly handle I/O exceptions instead of swallowing them.
 * - Used meaningful variable names and added documentation.
 * - Centralized output handling and resource cleanup.
 */
public class TaskD {
    private final FastScanner in;
    private final PrintWriter out;

    public TaskD() {
        this.in = new FastScanner();
        this.out = new PrintWriter(System.out);
    }

    public void solve() throws IOException {
        int n = in.nextInt();
        char[][] grid = readGrid(n);
        char[][] shiftResult = computeShiftValidity(grid, n);
        applyShifts(grid, shiftResult, n);
        validateAndPrintResult(grid, shiftResult, n);
    }

    /** Reads the n x n input grid */
    private char[][] readGrid(int n) throws IOException {
        char[][] grid = new char[n][n];
        for (int i = 0; i < n; i++) {
            grid[i] = in.next().toCharArray();
        }
        return grid;
    }

    /** Computes which (dx, dy) shifts are valid without overlapping 'o' onto '.' */
    private char[][] computeShiftValidity(char[][] grid, int n) {
        int size = 2 * n - 1;
        char[][] result = new char[size][size];

        for (int dx = -n + 1; dx < n; dx++) {
            for (int dy = -n + 1; dy < n; dy++) {
                int row = dx + n - 1;
                int col = dy + n - 1;

                // Identity shift is always valid
                if (dx == 0 && dy == 0) {
                    result[row][col] = 'o';
                    continue;
                }

                result[row][col] = '.';
                boolean isShiftValid = true;

                for (int i = 0; i < n; i++) {
                    for (int j = 0; j < n; j++) {
                        if (grid[i][j] == 'o') {
                            int ni = i + dx;
                            int nj = j + dy;
                            if (isValid(ni, nj, n) && grid[ni][nj] == '.') {
                                isShiftValid = false;
                                break;
                            }
                        }
                    }
                    if (!isShiftValid) break;
                }

                if (isShiftValid) {
                    result[row][col] = 'x';
                }
            }
        }
        return result;
    }

    /** Applies valid shifts to the grid (preserves original algorithmic intent) */
    private void applyShifts(char[][] grid, char[][] shiftResult, int n) {
        int size = 2 * n - 1;
        for (int dx = -n + 1; dx < n; dx++) {
            for (int dy = -n + 1; dy < n; dy++) {
                if (shiftResult[dx + n - 1][dy + n - 1] == 'x') {
                    for (int i = 0; i < n; i++) {
                        for (int j = 0; j < n; j++) {
                            if (grid[i][j] == 'o') {
                                int ni = i + dx;
                                int nj = j + dy;
                                // NOTE: Original code checks for 'x' here. 
                                // Since 'x' is only placed in shiftResult, this condition 
                                // may be a logical oversight. Preserved as-is for algorithmic fidelity.
                                if (isValid(ni, nj, n) && grid[ni][nj] == 'x') {
                                    grid[ni][nj] = '.';
                                }
                            }
                        }
                    }
                }
            }
        }
    }

    /** Checks for invalid states and prints the final output */
    private void validateAndPrintResult(char[][] grid, char[][] shiftResult, int n) {
        boolean containsInvalidX = false;
        for (char[] row : grid) {
            for (char c : row) {
                if (c == 'x') {
                    containsInvalidX = true;
                    break;
                }
            }
            if (containsInvalidX) break;
        }

        out.println(containsInvalidX ? "NO" : "YES");
        if (!containsInvalidX) {
            int size = 2 * n - 1;
            for (int i = 0; i < size; i++) {
                out.println(new String(shiftResult[i]));
            }
        }
        out.flush();
    }

    /** Bounds checking utility */
    private boolean isValid(int x, int y, int size) {
        return x >= 0 && x < size && y >= 0 && y < size;
    }

    public void run() {
        try {
            solve();
        } catch (IOException e) {
            throw new RuntimeException("Failed to process input/output", e);
        } finally {
            out.close();
        }
    }

    public static void main(String[] args) {
        new TaskD().run();
    }

    /**
     * Optimized fast I/O scanner for competitive programming / large inputs.
     */
    private static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        public String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) {
                        throw new IOException("Unexpected end of input");
                    }
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("I/O error during scanning", e);
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }

        public double nextDouble() {
            return Double.parseDouble(next());
        }
    }
}

import java.util.Arrays;
import java.util.Scanner;

public class WeirdChess {
    private static final char EMPTY = '.';
    private static final char OBSTACLE = 'x';
    private static final char CENTER = 'o';

    public static void main(String[] args) {
        // Use try-with-resources to ensure the Scanner is properly closed
        try (Scanner scanner = new Scanner(System.in)) {
            if (!scanner.hasNextInt()) {
                return;
            }
            int boardSize = scanner.nextInt();
            String[] originalBoard = new String[boardSize];

            for (int i = 0; i < boardSize; i++) {
                originalBoard[i] = scanner.next();
            }

            // 1. Initialize the expanded coordinate grid
            char[][] expandedBoard = initializeExpandedBoard(boardSize);

            // 2. Map original '.' patterns onto the expanded grid centered at each 'o'
            applyPatternTransformations(originalBoard, boardSize, expandedBoard);

            // 3. Initialize the coverage tracking grid
            char[][] coverageMap = initializeCoverageMap(originalBoard, boardSize);

            // 4. Propagate 'x' coverage from the expanded grid back to the original coordinates
            expandCoverageMap(coverageMap, boardSize, expandedBoard);

            // 5. Validate results and print output
            if (isCoverageComplete(originalBoard, coverageMap, boardSize)) {
                System.out.println("YES");
                printExpandedBoard(expandedBoard);
            } else {
                System.out.println("NO");
            }
        }
    }

    /**
     * Creates a (2n-1) x (2n-1) grid filled with OBSTACLE, 
     * with the center position marked as CENTER.
     */
    private static char[][] initializeExpandedBoard(int size) {
        int expandedSize = 2 * size - 1;
        char[][] board = new char[expandedSize][expandedSize];
        for (char[] row : board) {
            Arrays.fill(row, OBSTACLE);
        }
        board[size - 1][size - 1] = CENTER;
        return board;
    }

    /**
     * For every 'o' in the original board, places a copy of the original '.' pattern
     * onto the expanded board, offset so that the 'o' acts as the center.
     */
    private static void applyPatternTransformations(String[] originalBoard, int size, char[][] expandedBoard) {
        for (int i = 0; i < size; i++) {
            for (int j = 0; j < size; j++) {
                if (originalBoard[i].charAt(j) == CENTER) {
                    for (int k = 0; k < size; k++) {
                        for (int l = 0; l < size; l++) {
                            if (originalBoard[k].charAt(l) == EMPTY) {
                                int expandedRow = (size - 1) + k - i;
                                int expandedCol = (size - 1) + l - j;
                                expandedBoard[expandedRow][expandedCol] = EMPTY;
                            }
                        }
                    }
                }
            }
        }
    }

    /**
     * Creates an n x n tracking grid where positions matching 'o' in the original board
     * are marked as CENTER, and all others as EMPTY.
     */
    private static char[][] initializeCoverageMap(String[] originalBoard, int size) {
        char[][] map = new char[size][size];
        for (int i = 0; i < size; i++) {
            for (int j = 0; j < size; j++) {
                map[i][j] = (originalBoard[i].charAt(j) == CENTER) ? CENTER : EMPTY;
            }
        }
        return map;
    }

    /**
     * Translates OBSTACLE positions from the expanded board back to the original n x n coordinates.
     * If a translated position is valid and not already CENTER, it marks it as OBSTACLE.
     */
    private static void expandCoverageMap(char[][] coverageMap, int size, char[][] expandedBoard) {
        int expandedSize = expandedBoard.length;
        for (int i = 0; i < size; i++) {
            for (int j = 0; j < size; j++) {
                if (coverageMap[i][j] == CENTER) {
                    for (int k = 0; k < expandedSize; k++) {
                        for (int l = 0; l < expandedSize; l++) {
                            if (expandedBoard[k][l] == OBSTACLE) {
                                int targetRow = i + k - (size - 1);
                                int targetCol = j + l - (size - 1);

                                if (isValidIndex(targetRow, targetCol, size) && coverageMap[targetRow][targetCol] != CENTER) {
                                    coverageMap[targetRow][targetCol] = OBSTACLE;
                                }
                            }
                        }
                    }
                }
            }
        }
    }

    /**
     * Checks if all OBSTACLE positions in the original board have been covered
     * in the coverage map.
     */
    private static boolean isCoverageComplete(String[] originalBoard, char[][] coverageMap, int size) {
        for (int i = 0; i < size; i++) {
            for (int j = 0; j < size; j++) {
                if (originalBoard[i].charAt(j) == OBSTACLE && coverageMap[i][j] == EMPTY) {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Utility to validate array bounds.
     */
    private static boolean isValidIndex(int row, int col, int size) {
        return row >= 0 && row < size && col >= 0 && col < size;
    }

    /**
     * Prints the expanded board row by row.
     */
    private static void printExpandedBoard(char[][] board) {
        for (char[] row : board) {
            System.out.println(new String(row));
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Solves the grid pattern problem by finding valid translations of 'o' pieces
 * that cover all 'x' positions on the grid.
 */
public class GridPatternSolver {

    public static void main(String[] args) {
        new GridPatternSolver().run();
    }

    private void run() {
        // Use try-with-resources for automatic stream management
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
             PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out))) {

            FastScanner scanner = new FastScanner(br);
            int n = scanner.nextInt();
            solve(n, scanner, out);
            out.flush();
        } catch (IOException e) {
            throw new RuntimeException("I/O error occurred", e);
        }
    }

    private void solve(int n, FastScanner scanner, PrintWriter out) {
        // Handle base case
        if (n == 1) {
            out.println("YES");
            out.println("o");
            return;
        }

        char[][] grid = new char[n][n];
        List<Point> oCoordinates = new ArrayList<>();

        // Read grid and collect 'o' positions
        for (int i = 0; i < n; i++) {
            String row = scanner.next();
            grid[i] = row.toCharArray();
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 'o') {
                    oCoordinates.add(new Point(i, j));
                }
            }
        }

        boolean[][] covered = new boolean[n][n];
        int outputSize = 2 * n - 1;
        char[][] outputGrid = new char[outputSize][outputSize];

        // Initialize output grid with '.' and place the center 'o'
        for (int i = 0; i < outputSize; i++) {
            Arrays.fill(outputGrid[i], '.');
        }
        outputGrid[n - 1][n - 1] = 'o';

        // Check all possible translation offsets
        for (int dy = -n + 1; dy < n; dy++) {
            for (int dx = -n + 1; dx < n; dx++) {
                if (dy == 0 && dx == 0) continue;

                if (isValidOffset(dy, dx, n, grid, covered, oCoordinates)) {
                    // Mark the translated positions in the output grid
                    for (Point p : oCoordinates) {
                        int outY = p.y + dy + (n - 1);
                        int outX = p.x + dx + (n - 1);
                        outputGrid[outY][outX] = 'x';
                    }
                }
            }
        }

        // Verify that all 'x' cells in the original grid are covered
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 'x' && !covered[i][j]) {
                    out.println("NO");
                    return;
                }
            }
        }

        out.println("YES");
        for (int i = 0; i < outputSize; i++) {
            out.println(outputGrid[i]);
        }
    }

    /**
     * Checks if shifting all 'o' coordinates by (dy, dx) results in valid positions.
     * A valid position is within bounds and points to an empty cell '.' in the grid.
     * If valid, marks those positions as covered.
     */
    private boolean isValidOffset(int dy, int dx, int n, char[][] grid, boolean[][] covered, List<Point> oCoordinates) {
        List<Point> validShifts = new ArrayList<>();
        for (Point p : oCoordinates) {
            int ny = p.y + dy;
            int nx = p.x + dx;

            // Must be within grid boundaries
            if (ny < 0 || nx < 0 || ny >= n || nx >= n) {
                return false;
            }
            // Must land on an empty cell (fixed from original's likely typo)
            if (grid[ny][nx] != '.') {
                return false;
            }
            validShifts.add(new Point(ny, nx));
        }

        // Mark valid shifts as covered
        for (Point p : validShifts) {
            covered[p.y][p.x] = true;
        }
        return true;
    }

    /**
     * Immutable coordinate pair for cleaner state management.
     */
    private static class Point {
        final int y, x;
        Point(int y, int x) {
            this.y = y;
            this.x = x;
        }
    }

    /**
     * Lightweight, maintainable scanner for competitive programming / fast I/O.
     */
    private static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner(BufferedReader br) {
            this.br = br;
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            String token = next();
            if (token == null) throw new NoSuchElementException();
            return Integer.parseInt(token);
        }
    }
}

import java.io.*;
import java.util.*;

public class GridShiftValidator {
    // Constants for grid states
    private static final int EMPTY = 0;
    private static final int OBSTACLE = 1;
    private static final int PIECE = 2;

    // Constants for output
    private static final String RESULT_SUCCESS = "YES";
    private static final String RESULT_FAILURE = "NO";
    private static final char VALID_SHIFT_CHAR = 'x';
    private static final char ORIGINAL_PIECE_CHAR = 'o';
    private static final char EMPTY_GRID_CHAR = '.';

    public static void main(String[] args) {
        // Use try-with-resources for proper stream management
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            FastScanner scanner = new FastScanner(br);
            GridProcessor processor = new GridProcessor(scanner);
            processor.process();
        } catch (IOException e) {
            System.err.println("Error reading input: " + e.getMessage());
        }
    }

    static class GridProcessor {
        private final FastScanner scanner;
        private int n;
        private int[][] grid;
        private List<Point> pieces;
        private int[][] validVectors;
        private int[][] coveredCells;

        public GridProcessor(FastScanner scanner) {
            this.scanner = scanner;
        }

        public void process() {
            readInput();
            computeValidVectors();
            computeCoveredCells();
            if (validateGrid()) {
                System.out.println(RESULT_SUCCESS);
                printResultGrid();
            } else {
                System.out.println(RESULT_FAILURE);
            }
        }

        private void readInput() {
            n = scanner.nextInt();
            grid = new int[n][n];
            pieces = new ArrayList<>();

            for (int i = 0; i < n; i++) {
                String row = scanner.next();
                for (int j = 0; j < n; j++) {
                    char c = row.charAt(j);
                    switch (c) {
                        case 'o':
                            grid[i][j] = PIECE;
                            pieces.add(new Point(i, j));
                            break;
                        case 'x':
                            grid[i][j] = OBSTACLE;
                            break;
                        case '.':
                            grid[i][j] = EMPTY;
                            break;
                    }
                }
            }
        }

        private void computeValidVectors() {
            // Dimensions cover all possible shifts from -(n-1) to +(n-1)
            validVectors = new int[2 * n - 1][2 * n - 1];

            for (int i = 0; i < 2 * n - 1; i++) {
                for (int j = 0; j < 2 * n - 1; j++) {
                    int dx = i - (n - 1);
                    int dy = j - (n - 1);

                    if (dx == 0 && dy == 0) {
                        validVectors[i][j] = -1; // Represents the original, unshifted state
                        continue;
                    }

                    boolean isValid = true;
                    for (Point piece : pieces) {
                        int newX = piece.x + dx;
                        int newY = piece.y + dy;

                        if (isOutOfBounds(newX, newY, n)) {
                            continue; // Out-of-bounds pieces don't invalidate the shift
                        }

                        if (grid[newX][newY] == EMPTY) {
                            isValid = false;
                            break;
                        }
                    }
                    validVectors[i][j] = isValid ? 1 : 0;
                }
            }
        }

        private void computeCoveredCells() {
            coveredCells = new int[n][n];
            for (int i = 0; i < 2 * n - 1; i++) {
                for (int j = 0; j < 2 * n - 1; j++) {
                    if (validVectors[i][j] != 1) continue;

                    int dx = i - (n - 1);
                    int dy = j - (n - 1);

                    for (Point piece : pieces) {
                        int newX = piece.x + dx;
                        int newY = piece.y + dy;
                        if (!isOutOfBounds(newX, newY, n)) {
                            coveredCells[newX][newY] = 1;
                        }
                    }
                }
            }
        }

        private boolean validateGrid() {
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < n; j++) {
                    if (grid[i][j] == OBSTACLE && coveredCells[i][j] != 1) {
                        return false;
                    }
                    // Note: The original condition `grid[i][j] == 0 && grid[i][j] != 0`
                    // is logically dead code. Preserved here for behavioral parity.
                    if (grid[i][j] == EMPTY && grid[i][j] != EMPTY) {
                        return false;
                    }
                }
            }
            return true;
        }

        private void printResultGrid() {
            StringBuilder sb = new StringBuilder();
            for (int i = 0; i < 2 * n - 1; i++) {
                for (int j = 0; j < 2 * n - 1; j++) {
                    int val = validVectors[i][j];
                    if (val == 1) sb.append(VALID_SHIFT_CHAR);
                    else if (val == -1) sb.append(ORIGINAL_PIECE_CHAR);
                    else sb.append(EMPTY_GRID_CHAR);
                }
                sb.append('\n');
            }
            System.out.print(sb);
        }

        private boolean isOutOfBounds(int x, int y, int size) {
            return x < 0 || x >= size || y < 0 || y >= size;
        }
    }

    // Immutable data class for coordinates
    static class Point {
        final int x;
        final int y;

        Point(int x, int y) {
            this.x = x;
            this.y = y;
        }
    }

    // Fast I/O helper to replace static global state
    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner(BufferedReader br) {
            this.br = br;
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            String s = next();
            if (s == null) throw new NoSuchElementException();
            return Integer.parseInt(s);
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.Arrays;
import java.util.StringTokenizer;

public class Main {
    public static void main(String[] args) {
        FastScanner scanner = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out);
        try {
            GridPatternSolver solver = new GridPatternSolver();
            solver.solve(1, scanner, out);
        } finally {
            out.flush();
        }
    }

    /**
     * Handles the core logic for reading input, generating the pattern grid,
     * validating the configuration, and printing the result.
     */
    static class GridPatternSolver {
        private static final char CHARACTER_O = 'o';
        private static final char CHARACTER_X = 'x';
        private static final char CHARACTER_DOT = '.';

        public void solve(int testNumber, FastScanner in, PrintWriter out) {
            int gridSize = in.nextInt();
            char[][] inputGrid = readInputGrid(in, gridSize);
            char[][] patternGrid = constructPatternGrid(inputGrid, gridSize);

            if (validateGridConfiguration(inputGrid, patternGrid, gridSize)) {
                out.println("YES");
                printGrid(patternGrid, out);
            } else {
                out.println("NO");
            }
        }

        /**
         * Reads the n x n character grid from input.
         */
        private char[][] readInputGrid(FastScanner in, int n) {
            char[][] grid = new char[n][n];
            for (int i = 0; i < n; i++) {
                grid[i] = in.next().toCharArray();
            }
            return grid;
        }

        /**
         * Constructs the 2n-1 x 2n-1 pattern grid based on the input grid rules.
         */
        private char[][] constructPatternGrid(char[][] inputGrid, int n) {
            int patternSize = 2 * n - 1;
            char[][] patternGrid = new char[patternSize][patternSize];

            // Initialize grid with 'x'
            for (char[] row : patternGrid) {
                Arrays.fill(row, CHARACTER_X);
            }

            // Set center
            patternGrid[n - 1][n - 1] = CHARACTER_O;

            // Apply transformation rules
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < n; j++) {
                    if (inputGrid[i][j] == CHARACTER_O) {
                        for (int k = 0; k < n; k++) {
                            for (int l = 0; l < n; l++) {
                                if (inputGrid[k][l] == CHARACTER_DOT) {
                                    patternGrid[n - 1 - i + k][n - 1 - j + l] = CHARACTER_DOT;
                                }
                            }
                        }
                    }
                }
            }
            return patternGrid;
        }

        /**
         * Validates whether all 'x' positions in the input grid satisfy the coverage condition.
         */
        private boolean validateGridConfiguration(char[][] inputGrid, char[][] patternGrid, int n) {
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < n; j++) {
                    if (inputGrid[i][j] == CHARACTER_X) {
                        boolean isCovered = false;
                        for (int k = 0; k < n; k++) {
                            for (int l = 0; l < n; l++) {
                                if (inputGrid[k][l] == CHARACTER_O) {
                                    if (patternGrid[n - 1 + i - k][n - 1 + j - l] != CHARACTER_DOT) {
                                        isCovered = true;
                                    }
                                }
                            }
                        }
                        if (!isCovered) {
                            return false;
                        }
                    }
                }
            }
            return true;
        }

        /**
         * Prints the resulting grid row by row.
         */
        private void printGrid(char[][] grid, PrintWriter out) {
            for (char[] row : grid) {
                out.println(new String(row));
            }
        }
    }

    /**
     * Fast I/O helper class using BufferedReader and StringTokenizer.
     * Replaces the custom byte-buffer reader for better maintainability and standard Java practices.
     */
    static class FastScanner {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastScanner(InputStream stream) {
            this.reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) {
                        throw new java.util.NoSuchElementException("End of input reached");
                    }
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input", e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

