class TaskD {
    public void solve(FastScanner in, PrintWriter out) {
        int n = in.nextInt();
        char[][] grid = new char[n][];
        boolean[][] occupied = new boolean[n][n];

        // First pass: read grid, mark occupied cells, and count pieces
        int pieceCount = 0;
        for (int r = 0; r < n; r++) {
            grid[r] = in.next().toCharArray();
            for (int c = 0; c < n; c++) {
                if (grid[r][c] != '.') {
                    occupied[r][c] = true;
                }
                if (grid[r][c] == 'o') {
                    pieceCount++;
                }
            }
        }

        // Second pass: store piece coordinates
        int[] pieceRows = new int[pieceCount];
        int[] pieceCols = new int[pieceCount];
        int idx = 0;
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < n; c++) {
                if (grid[r][c] == 'o') {
                    pieceRows[idx] = r;
                    pieceCols[idx] = c;
                    idx++;
                }
            }
        }

        int gridSize = 2 * n - 1;
        boolean[][] validShifts = new boolean[gridSize][gridSize];
        boolean[][] coveredCells = new boolean[n][n];
        int centerOffset = n - 1;

        // Evaluate all possible shifts
        for (int dr = -centerOffset; dr <= centerOffset; dr++) {
            for (int dc = -centerOffset; dc <= centerOffset; dc++) {
                if (isShiftValid(pieceRows, pieceCols, pieceCount, dr, dc, n, occupied)) {
                    validShifts[centerOffset + dr][centerOffset + dc] = true;
                    applyShift(pieceRows, pieceCols, pieceCount, dr, dc, n, coveredCells);
                }
            }
        }

        // Verify if all occupied cells are covered by valid shifts
        if (!checkCoverageMatch(occupied, coveredCells)) {
            out.println("NO");
            return;
        }

        out.println("YES");
        printShiftGrid(validShifts, gridSize, out);
    }

    /**
     * Checks if a shift (dr, dc) is valid.
     * A shift is valid if every piece that lands inside the grid 
     * lands on an originally occupied cell. Pieces moving out of bounds are ignored.
     */
    private boolean isShiftValid(int[] rows, int[] cols, int count, int dr, int dc, int n, boolean[][] occupied) {
        for (int i = 0; i < count; i++) {
            int nr = rows[i] + dr;
            int nc = cols[i] + dc;

            // Pieces moving out of bounds are ignored for this shift
            if (nr < 0 || nr >= n || nc < 0 || nc >= n) {
                continue;
            }
            // Must land on an originally occupied cell
            if (!occupied[nr][nc]) {
                return false;
            }
        }
        return true;
    }

    /**
     * Marks cells in the grid that are covered by the given shift.
     */
    private void applyShift(int[] rows, int[] cols, int count, int dr, int dc, int n, boolean[][] covered) {
        for (int i = 0; i < count; i++) {
            int nr = rows[i] + dr;
            int nc = cols[i] + dc;
            if (nr >= 0 && nr < n && nc >= 0 && nc < n) {
                covered[nr][nc] = true;
            }
        }
    }

    /**
     * Checks if the covered cells exactly match the originally occupied cells.
     */
    private boolean checkCoverageMatch(boolean[][] expected, boolean[][] actual) {
        for (int r = 0; r < expected.length; r++) {
            for (int c = 0; c < expected[r].length; c++) {
                if (expected[r][c] != actual[r][c]) {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Prints the shift result grid.
     * Center is 'o', valid shifts are 'x', others are '.'.
     */
    private void printShiftGrid(boolean[][] shifts, int size, PrintWriter out) {
        int center = size / 2;
        for (int i = 0; i < size; i++) {
            for (int j = 0; j < size; j++) {
                if (i == center && j == center) {
                    out.print('o');
                } else if (shifts[i][j]) {
                    out.print('x');
                } else {
                    out.print('.');
                }
            }
            out.println();
        }
    }
}

