/**
 * Core solver for Task D. Encapsulates grid analysis and shift validation logic.
 */
class TaskD {

    /**
     * Immutable 2D coordinate point. Used as a key in HashSet.
     */
    private static class Point {
        final int x, y;

        Point(int x, int y) {
            this.x = x;
            this.y = y;
        }

        @Override
        public boolean equals(Object o) {
            if (this == o) return true;
            if (!(o instanceof Point)) return false;
            Point p = (Point) o;
            return x == p.x && y == p.y;
        }

        @Override
        public int hashCode() {
            return 31 * x + y;
        }

        @Override
        public String toString() {
            return "Point{" + "x=" + x + ", y=" + y + '}';
        }
    }

    /**
     * Entry point for solving the problem. Orchestrates parsing, validation, and output.
     */
    public void solve(InputReader in, PrintWriter out) {
        int n = in.nextInt();
        String[] grid = new String[n];
        Set<Point> originalPositions = new HashSet<>();
        Set<Point> targetPositions = new HashSet<>();

        // 1. Parse input and collect positions
        for (int i = 0; i < n; i++) {
            grid[i] = in.next();
            for (int j = 0; j < n; j++) {
                char c = grid[i].charAt(j);
                if (c == 'o') {
                    originalPositions.add(new Point(i, j));
                } else if (c == 'x') {
                    targetPositions.add(new Point(i, j));
                }
            }
        }

        // 2. Compute valid translation vectors
        Set<Point> validShifts = computeValidShifts(n, originalPositions, targetPositions);

        // 3. Validate that every 'x' can be explained by at least one valid shift
        if (!validateTargets(targetPositions, originalPositions, validShifts)) {
            out.println("NO");
            return;
        }

        // 4. Output result and shift visualization
        out.println("YES");
        printShiftGrid(validShifts, n, out);
    }

    /**
     * Determines all (dx, dy) shifts where moving all 'o' markers keeps them
     * within bounds and on top of either an 'o' or an 'x'.
     */
    private Set<Point> computeValidShifts(int n, Set<Point> originalPositions, Set<Point> targetPositions) {
        Set<Point> validShifts = new HashSet<>();
        int limit = n - 1;

        for (int dx = -limit; dx <= limit; dx++) {
            for (int dy = -limit; dy <= limit; dy++) {
                if (isShiftValid(n, originalPositions, targetPositions, dx, dy)) {
                    validShifts.add(new Point(dx, dy));
                }
            }
        }
        return validShifts;
    }

    /**
     * Checks if a specific shift vector maintains grid constraints for all original markers.
     */
    private boolean isShiftValid(int n, Set<Point> originalPositions, Set<Point> targetPositions, int dx, int dy) {
        for (Point p : originalPositions) {
            int nx = p.x + dx;
            int ny = p.y + dy;

            // Out-of-bounds shifts are ignored for that specific marker
            if (nx < 0 || nx >= n || ny < 0 || ny >= n) {
                continue;
            }

            // Must land on an existing 'o' or 'x'
            if (!originalPositions.contains(new Point(nx, ny)) &&
                !targetPositions.contains(new Point(nx, ny))) {
                return false;
            }
        }
        return true;
    }

    /**
     * Ensures every target 'x' position can be reached by shifting at least one 'o'
     * using a valid shift vector.
     */
    private boolean validateTargets(Set<Point> targetPositions, Set<Point> originalPositions, Set<Point> validShifts) {
        for (Point target : targetPositions) {
            boolean explained = false;
            for (Point original : originalPositions) {
                int dx = target.x - original.x;
                int dy = target.y - original.y;
                if (validShifts.contains(new Point(dx, dy))) {
                    explained = true;
                    break;
                }
            }
            if (!explained) {
                return false;
            }
        }
        return true;
    }

    /**
     * Prints the YES confirmation and visualizes the valid shift grid.
     */
    private void printShiftGrid(Set<Point> validShifts, int n, PrintWriter out) {
        int gridSize = 2 * n - 1;
        char[][] grid = new char[gridSize][gridSize];

        // Initialize with '.'
        for (int i = 0; i < gridSize; i++) {
            Arrays.fill(grid[i], '.');
        }

        // Map valid shifts to grid coordinates (centered at n-1, n-1)
        for (Point shift : validShifts) {
            int row = n - 1 + shift.x;
            int col = n - 1 + shift.y;
            grid[row][col] = 'x';
        }

        // Mark center as 'o'
        grid[n - 1][n - 1] = 'o';

        // Output row by row
        for (int i = 0; i < gridSize; i++) {
            out.println(new String(grid[i]));
        }
    }
}

