/**
 * Solves the grid-based visibility problem.
 * Determines if every 'x' in the grid is visible to at least one 'o'
 * under specific relative offset constraints, and outputs the resulting pattern.
 */
class GridSolver {
    public void solve(FastReader in, FastWriter out) {
        int n = in.nextInt();
        char[][] grid = in.readGrid(n, n);

        // Relative offset mask: initialized to 1 (valid)
        // Size is (2n - 1) x (2n - 1) to accommodate offsets from -(n-1) to (n-1)
        int[][] validOffsets = new int[2 * n - 1][2 * n - 1];
        for (int[] row : validOffsets) {
            Arrays.fill(row, 1);
        }

        // Step 1: Mark offsets as invalid (0) if an 'o' sees a '.' at that relative position
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 'o') {
                    markInvalidOffsets(n, i, j, grid, validOffsets);
                }
            }
        }

        // Step 2: Count how many 'o's see each '.' with a valid offset
        int[][] oVisibilityCount = new int[n][n];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 'o') {
                    countValidVisits(n, i, j, grid, validOffsets, oVisibilityCount);
                }
            }
        }

        // Step 3: Check if any 'x' is not visible to any 'o'
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 'x' && oVisibilityCount[i][j] == 0) {
                    out.println("NO");
                    return;
                }
            }
        }

        out.println("YES");
        printResultGrid(n, validOffsets, out);
    }

    /**
     * Iterates over all relative offsets from a base 'o' position.
     * If an offset points to a '.', marks that offset as invalid (0).
     */
    private void markInvalidOffsets(int n, int baseI, int baseJ, char[][] grid, int[][] validOffsets) {
        for (int dx = -n + 1; dx < n; dx++) {
            for (int dy = -n + 1; dy < n; dy++) {
                int x = baseI + dx;
                int y = baseJ + dy;
                if (x >= 0 && x < n && y >= 0 && y < n && grid[x][y] == '.') {
                    validOffsets[dx + n - 1][dy + n - 1] = 0;
                }
            }
        }
    }

    /**
     * Iterates over all relative offsets from a base 'o' position.
     * Increments the visibility count for '.' cells that align with valid offsets.
     */
    private void countValidVisits(int n, int baseI, int baseJ, char[][] grid, int[][] validOffsets, int[][] oVisibilityCount) {
        for (int dx = -n + 1; dx < n; dx++) {
            for (int dy = -n + 1; dy < n; dy++) {
                int x = baseI + dx;
                int y = baseJ + dy;
                if (x >= 0 && x < n && y >= 0 && y < n && validOffsets[dx + n - 1][dy + n - 1] != 0) {
                    oVisibilityCount[x][y]++;
                }
            }
        }
    }

    /**
     * Prints the final result grid based on the valid offsets mask.
     * Center is 'o', valid offsets become 'x', invalid become '.'.
     */
    private void printResultGrid(int n, int[][] validOffsets, FastWriter out) {
        for (int i = 0; i < 2 * n - 1; i++) {
            for (int j = 0; j < 2 * n - 1; j++) {
                if (i == n - 1 && j == n - 1) {
                    out.print('o');
                } else if (validOffsets[i][j] == 1) {
                    out.print('x');
                } else {
                    out.print('.');
                }
            }
            out.println();
        }
    }
}

/**
 * Fast input reader using BufferedReader for efficient character parsing.
 */
class FastReader {
    private final BufferedReader br;

    public FastReader(InputStream in) {
        br = new BufferedReader(new InputStreamReader(in));
    }

    public String next() {
        StringBuilder sb = new StringBuilder();
        int c = read();
        while (isWhitespace(c)) {
            c = read();
        }
        if (c < 0) return null;
        while (c >= 0 && !isWhitespace(c)) {
            sb.appendCodePoint(c);
            c = read();
        }
        return sb.toString();
    }

    public int nextInt() {
        int c = read();
        while (isWhitespace(c)) c = read();
        int sgn = 1;
        if (c == '-') {
            sgn = -1;
            c = read();
        }
        int ret = 0;
        while (c >= 0 && !isWhitespace(c)) {
            if (c < '0' || c > '9') {
                throw new NumberFormatException("Invalid character: " + (char) c);
            }
            ret = ret * 10 + c - '0';
            c = read();
        }
        return ret * sgn;
    }

    public char[][] readGrid(int n, int m) {
        char[][] grid = new char[n][];
        for (int i = 0; i < n; i++) {
            String line = next();
            if (line == null || line.length() != m) {
                throw new IllegalArgumentException("Expected line of length " + m + ", got: " + line);
            }
            grid[i] = line.toCharArray();
        }
        return grid;
    }

    private int read() {
        try {
            return br.read();
        } catch (IOException e) {
            throw new RuntimeException("IO error during read", e);
        }
    }

    private static boolean isWhitespace(int c) {
        return c <= 32;
    }
}

