import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.ArrayList;
import java.util.InputMismatchException;
import java.util.List;

public class Template {

    public static void main(String[] args) {
        FastScanner sc = new FastScanner();
        PrintWriter out = new PrintWriter(System.out);
        try {
            solve(sc, out);
        } finally {
            out.flush();
        }
    }

    /**
     * Orchestrates the reading, processing, validation, and output phases.
     */
    private static void solve(FastScanner sc, PrintWriter out) {
        int n = sc.nextInt();
        char[][] input = new char[n][n];
        List<Integer> oXCoords = new ArrayList<>();
        List<Integer> oYCoords = new ArrayList<>();

        // Read input grid and collect coordinates of all 'o' cells
        for (int r = 0; r < n; r++) {
            String line = sc.next();
            input[r] = line.toCharArray();
            for (int c = 0; c < n; c++) {
                if (input[r][c] == 'o') {
                    oXCoords.add(c);
                    oYCoords.add(r);
                }
            }
        }

        // Compute the answer grid
        char[][] ans = computeAnswerGrid(n, input, oXCoords, oYCoords);

        // Validate the computed grid against constraints
        if (!validateGrid(n, input, ans, oXCoords, oYCoords)) {
            out.println("NO");
            return;
        }

        // Output the result
        out.println("YES");
        for (char[] row : ans) {
            out.println(row);
        }
    }

    /**
     * Computes the answer grid based on the attack logic.
     * Size is (2N-1) x (2N-1). Center is at (N-1, N-1).
     */
    private static char[][] computeAnswerGrid(int n, char[][] input, List<Integer> oXCoords, List<Integer> oYCoords) {
        int size = 2 * n - 1;
        int center = n - 1;
        char[][] ans = new char[size][size];
        ans[center][center] = 'o';

        for (int r = 0; r < size; r++) {
            for (int c = 0; c < size; c++) {
                if (r == center && c == center) {
                    continue;
                }

                int dy = r - center;
                int dx = c - center;
                boolean attack = true;

                for (int i = 0; i < oXCoords.size(); i++) {
                    int nx = oXCoords.get(i) + dx;
                    int ny = oYCoords.get(i) + dy;

                    // Out of bounds in the input grid means this 'o' doesn't constrain this position
                    if (nx < 0 || ny < 0 || nx >= n || ny >= n) {
                        continue;
                    }

                    if (input[ny][nx] == '.') {
                        attack = false;
                        break;
                    }
                }
                ans[r][c] = attack ? 'x' : '.';
            }
        }
        return ans;
    }

    /**
     * Validates the answer grid against the problem constraints.
     * Returns true if valid, false otherwise.
     */
    private static boolean validateGrid(int n, char[][] input, char[][] ans, List<Integer> oXCoords, List<Integer> oYCoords) {
        int size = ans.length;
        int center = n - 1;
        boolean[][] covered = new boolean[n][n];

        for (int p = 0; p < oXCoords.size(); p++) {
            int ox = oXCoords.get(p);
            int oy = oYCoords.get(p);

            for (int r = 0; r < size; r++) {
                for (int c = 0; c < size; c++) {
                    int nx = ox + c - center;
                    int ny = oy + r - center;

                    if (nx < 0 || ny < 0 || nx >= n || ny >= n) {
                        continue;
                    }

                    if (ans[r][c] == 'x') {
                        covered[ny][nx] = true;
                        // An 'x' in the answer grid cannot map to a '.' in the input grid
                        if (input[ny][nx] == '.') {
                            return false;
                        }
                    }
                }
            }
        }

        // Any 'x' in the input grid must be covered by at least one 'x' in the answer grid
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < n; c++) {
                if (!covered[r][c] && input[r][c] == 'x') {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Fast input scanner optimized for competitive programming environments.
     */
    static class FastScanner {
        private final InputStream stream;
        private final byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;

        public FastScanner() {
            this.stream = System.in;
        }

        private int read() {
            if (numChars == -1) {
                throw new InputMismatchException();
            }
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0) {
                    return -1;
                }
            }
            return buf[curChar++];
        }

        private boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        private boolean isEndline(int c) {
            return c == '\n' || c == '\r' || c == -1;
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public int[] nextInt(int v) {
            int[] temp = new int[v];
            for (int i = 0; i < v; i++) {
                temp[i] = nextInt();
            }
            return temp;
        }

        public long nextLong() {
            return Long.parseLong(next());
        }

        public long[] nextLong(int v) {
            long[] temp = new long[v];
            for (int i = 0; i < v; i++) {
                temp[i] = nextLong();
            }
            return temp;
        }

        public double nextDouble() {
            return Double.parseDouble(next());
        }

        public double[] nextDouble(int v) {
            double[] temp = new double[v];
            for (int i = 0; i < v; i++) {
                temp[i] = nextDouble();
            }
            return temp;
        }

        public String next() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            StringBuilder res = new StringBuilder();
            do {
                res.appendCodePoint(c);
                c = read();
            } while (!isSpaceChar(c));
            return res.toString();
        }

        public String[] next(int v) {
            String[] temp = new String[v];
            for (int i = 0; i < v; i++) {
                temp[i] = next();
            }
            return temp;
        }

        public String nextLine() {
            int c = read();
            while (isEndline(c)) {
                c = read();
            }
            StringBuilder res = new StringBuilder();
            do {
                res.appendCodePoint(c);
                c = read();
            } while (!isEndline(c));
            return res.toString();
        }

        public String[] nextLine(int v) {
            String[] temp = new String[v];
            for (int i = 0; i < v; i++) {
                temp[i] = nextLine();
            }
            return temp;
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.StringTokenizer;

/**
 * Solves a grid-based game problem where 'o' pieces must explain the positions of 'x' markers.
 * It validates if a uniform move vector can explain all 'x' positions, and if so,
 * generates a visualization grid of all valid moves.
 */
public class BoardGameSolver {

    // Maximum range to check for valid moves. Matches original hardcoded bounds.
    private static final int MAX_MOVE_RANGE = 50;

    public static void main(String[] args) {
        // Proper resource management for standard input
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(System.in))) {
            BoardGameSolver solver = new BoardGameSolver(reader);
            solver.solve();
        } catch (IOException e) {
            System.err.println("Failed to read input: " + e.getMessage());
        }
    }

    private final BufferedReader reader;
    private int boardSize;
    private char[][] board;
    private final List<Point> pieces = new ArrayList<>();

    public BoardGameSolver(BufferedReader reader) {
        this.reader = reader;
    }

    /**
     * Orchestrates the solving process: reads input, validates, and outputs results.
     */
    private void solve() throws IOException {
        boardSize = readInt();
        board = new char[boardSize][];
        for (int i = 0; i < boardSize; i++) {
            String line = reader.readLine();
            if (line == null) {
                throw new IOException("Unexpected end of input while reading board rows.");
            }
            // Trim to handle trailing whitespace common in competitive programming inputs
            board[i] = line.trim().toCharArray();
        }

        collectPieces();
        if (!validateAllXPositions()) {
            return;
        }
        generateAndPrintResult();
    }

    /**
     * Reads the next integer token from input, skipping empty lines.
     */
    private int readInt() throws IOException {
        String line = reader.readLine();
        while (line != null && line.trim().isEmpty()) {
            line = reader.readLine();
        }
        if (line == null) {
            throw new IOException("End of input reached unexpectedly.");
        }
        StringTokenizer st = new StringTokenizer(line);
        return Integer.parseInt(st.nextToken());
    }

    /**
     * Scans the board and collects coordinates of all 'o' pieces.
     */
    private void collectPieces() {
        for (int i = 0; i < boardSize; i++) {
            for (int j = 0; j < board[i].length; j++) {
                if (board[i][j] == 'o') {
                    pieces.add(new Point(i, j));
                }
            }
        }
    }

    /**
     * Validates that every 'x' on the board can be explained by at least one 'o' piece
     * making a valid move.
     */
    private boolean validateAllXPositions() {
        for (int i = 0; i < boardSize; i++) {
            for (int j = 0; j < board[i].length; j++) {
                if (board[i][j] == 'x') {
                    if (!isAnyPieceExplainable(i, j)) {
                        System.out.println("NO");
                        return false;
                    }
                }
            }
        }
        return true;
    }

    /**
     * Checks if any piece can reach (targetRow, targetCol) with a valid move vector.
     */
    private boolean isAnyPieceExplainable(int targetRow, int targetCol) {
        for (Point piece : pieces) {
            int moveRow = targetRow - piece.row;
            int moveCol = targetCol - piece.col;
            if (isMoveValid(moveRow, moveCol)) {
                return true;
            }
        }
        return false;
    }

    /**
     * Determines if a move vector (moveRow, moveCol) is valid for all pieces.
     * Preserves original logic: returns false if ANY piece would land on an empty cell '.'.
     */
    private boolean isMoveValid(int moveRow, int moveCol) {
        for (Point piece : pieces) {
            int destRow = piece.row + moveRow;
            int destCol = piece.col + moveCol;

            // If destination is within bounds and is empty, the move is invalid
            if (destRow >= 0 && destRow < boardSize && destCol >= 0 && destCol < boardSize) {
                if (board[destRow][destCol] == '.') {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Generates the result visualization grid and prints it.
     */
    private void generateAndPrintResult() {
        int gridSize = 2 * boardSize - 1;
        char[][] resultGrid = new char[gridSize][gridSize];
        for (char[] row : resultGrid) {
            Arrays.fill(row, '.');
        }

        int center = boardSize - 1;
        resultGrid[center][center] = 'o';

        // Check all possible moves within the defined range
        for (int i = -MAX_MOVE_RANGE; i <= MAX_MOVE_RANGE; i++) {
            for (int j = -MAX_MOVE_RANGE; j <= MAX_MOVE_RANGE; j++) {
                if (i == 0 && j == 0) {
                    continue;
                }

                if (isMoveValid(i, j)) {
                    int resRow = center + i;
                    int resCol = center + j;
                    if (resRow >= 0 && resRow < gridSize && resCol >= 0 && resCol < gridSize) {
                        resultGrid[resRow][resCol] = 'x';
                    }
                }
            }
        }

        System.out.println("YES");
        for (char[] row : resultGrid) {
            System.out.println(new String(row));
        }
    }

    /**
     * Immutable record to store 2D grid coordinates.
     * Replaces parallel ArrayList<Integer> structures for better type safety.
     */
    private record Point(int row, int col) {}
}

import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

/**
 * Refactored version of the original Board Solver.
 * 
 * Improvements made:
 * 1. Class naming: Changed 'D' to 'BoardSolver' for clarity.
 * 2. Structure: Extracted logic from 'main' into specific methods (read, solve, print).
 * 3. Data Structures: Replaced parallel ArrayLists with a custom 'Coordinate' class.
 * 4. Readability: Used descriptive variable names (e.g., 'rowOffset' instead of 'dx').
 * 5. Encapsulation: Hidden implementation details of grid operations.
 * 6. Resource Management: Ensured Scanner is closed properly.
 */
public class BoardSolver {

    /**
     * Helper class to store grid coordinates.
     */
    private static class Coordinate {
        int row;
        int col;

        Coordinate(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        try {
            solve(scanner);
        } finally {
            scanner.close();
        }
    }

    /**
     * Orchestrates the reading, processing, and printing of the board solution.
     */
    private static void solve(Scanner scanner) {
        if (!scanner.hasNextInt()) {
            return;
        }

        int n = scanner.nextInt();
        scanner.nextLine(); // Consume the newline character after the integer

        char[][] board = readBoard(scanner, n);
        List<Coordinate> pieces = findPieces(board, n);

        int gridSize = 2 * n - 1;
        char[][] solutionGrid = new char[gridSize][gridSize];

        // The center of the solution grid is fixed as 'o'
        int center = n - 1;
        solutionGrid[center][center] = 'o';

        // Iterate through every cell in the expanded solution grid
        for (int r = 0; r < gridSize; r++) {
            for (int c = 0; c < gridSize; c++) {
                // Skip the center cell as it is already initialized
                if (r == center && c == center) {
                    continue;
                }

                int rowOffset = r - center;
                int colOffset = c - center;

                // Check if placing a piece at (r, c) is valid (not "attacked")
                if (isMoveSafe(rowOffset, colOffset, n, pieces, board)) {
                    solutionGrid[r][c] = 'x';
                    // Apply side effects to the board if the move is valid
                    applyMoveEffects(rowOffset, colOffset, n, pieces, board);
                } else {
                    solutionGrid[r][c] = '.';
                }
            }
        }

        // Final validation: check if any 'x' remains on the board
        if (hasRemainingPieces(board, n)) {
            System.out.println("NO");
        } else {
            System.out.println("YES");
            printGrid(solutionGrid, gridSize);
        }
    }

    /**
     * Reads the n x n character grid from the scanner.
     */
    private static char[][] readBoard(Scanner scanner, int n) {
        char[][] board = new char[n][n];
        for (int i = 0; i < n; i++) {
            String line = scanner.nextLine().trim();
            board[i] = line.toCharArray();
        }
        return board;
    }

    /**
     * Identifies coordinates of all pieces ('o') on the board.
     */
    private static List<Coordinate> findPieces(char[][] board, int n) {
        List<Coordinate> pieces = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (board[i][j] == 'o') {
                    pieces.add(new Coordinate(i, j));
                }
            }
        }
        return pieces;
    }

    /**
     * Checks if a move defined by (rowOffset, colOffset) is safe.
     * A move is safe if shifting every piece by the offset does not land on an empty spot ('.').
     */
    private static boolean isMoveSafe(int rowOffset, int colOffset, int n, List<Coordinate> pieces, char[][] board) {
        for (Coordinate piece : pieces) {
            int targetRow = piece.row + rowOffset;
            int targetCol = piece.col + colOffset;

            // Check if the shifted position is within the board boundaries
            if (isWithinBounds(targetRow, targetCol, n)) {
                // If the target spot is empty, the move is unsafe (attacked)
                if (board[targetRow][targetCol] == '.') {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Updates the board state based on a valid move.
     * Specifically, upgrades 'x' to 'X' if covered by a piece shift.
     */
    private static void applyMoveEffects(int rowOffset, int colOffset, int n, List<Coordinate> pieces, char[][] board) {
        for (Coordinate piece : pieces) {
            int targetRow = piece.row + rowOffset;
            int targetCol = piece.col + colOffset;

            if (isWithinBounds(targetRow, targetCol, n)) {
                if (board[targetRow][targetCol] == 'x') {
                    board[targetRow][targetCol] = 'X';
                }
            }
        }
    }

    /**
     * Checks if coordinates are within the n x n board.
     */
    private static boolean isWithinBounds(int row, int col, int n) {
        return row >= 0 && row < n && col >= 0 && col < n;
    }

    /**
     * Checks if the board still contains any 'x' characters.
     */
    private static boolean hasRemainingPieces(char[][] board, int n) {
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (board[i][j] == 'x') {
                    return true;
                }
            }
        }
        return false;
    }

    /**
     * Prints the solution grid to the console.
     */
    private static void printGrid(char[][] grid, int size) {
        for (int i = 0; i < size; i++) {
            for (int j = 0; j < size; j++) {
                System.out.print(grid[i][j]);
            }
            System.out.println();
        }
    }
}

import java.io.*;
import java.nio.charset.StandardCharsets;
import java.util.*;

public class Main {
    public static void main(String[] args) {
        FastScanner scanner = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out));
        try {
            solve(scanner, out);
        } finally {
            out.flush();
        }
    }

    private static void solve(FastScanner in, PrintWriter out) {
        String nStr = in.next();
        if (nStr == null) return;
        int n = Integer.parseInt(nStr);

        char[][] grid = new char[n][n];
        for (int i = 0; i < n; i++) {
            String row = in.next();
            grid[i] = row.toCharArray();
        }

        // Collect positions of all 'o' characters
        List<Integer> oRows = new ArrayList<>();
        List<Integer> oCols = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 'o') {
                    oRows.add(i);
                    oCols.add(j);
                }
            }
        }

        List<Integer> validDx = new ArrayList<>();
        List<Integer> validDy = new ArrayList<>();
        boolean[][] covered = new boolean[n][n];

        // Check all possible translation vectors
        for (int dx = -n + 1; dx < n; dx++) {
            for (int dy = -n + 1; dy < n; dy++) {
                if (dx == 0 && dy == 0) continue;

                if (isValidTranslation(n, grid, oRows, oCols, dx, dy)) {
                    validDx.add(dx);
                    validDy.add(dy);
                    markCovered(n, oRows, oCols, dx, dy, covered);
                }
            }
        }

        // Verify that all 'x' positions are covered by at least one valid translation
        if (!allXAreCovered(n, grid, covered)) {
            out.println("NO");
            return;
        }

        out.println("YES");
        char[][] resultGrid = buildResultGrid(n, oRows, oCols, validDx, validDy);
        for (int i = 0; i < resultGrid.length; i++) {
            out.println(resultGrid[i]);
        }
    }

    /**
     * Determines if translating all 'o' positions by (dx, dy) only lands on 
     * non-'.' cells or moves off the board.
     */
    private static boolean isValidTranslation(int n, char[][] grid, List<Integer> oRows, List<Integer> oCols, int dx, int dy) {
        for (int k = 0; k < oRows.size(); k++) {
            int r = oRows.get(k);
            int c = oCols.get(k);
            int nr = r + dx;
            int nc = c + dy;

            // Skip 'o' characters that move off the board
            if (nr < 0 || nr >= n || nc < 0 || nc >= n) {
                continue;
            }
            // If any translated 'o' lands on '.', this translation is invalid
            if (grid[nr][nc] == '.') {
                return false;
            }
        }
        return true;
    }

    /**
     * Marks the grid cells that are covered by a valid translation vector.
     */
    private static void markCovered(int n, List<Integer> oRows, List<Integer> oCols, int dx, int dy, boolean[][] covered) {
        for (int k = 0; k < oRows.size(); k++) {
            int r = oRows.get(k);
            int c = oCols.get(k);
            int nr = r + dx;
            int nc = c + dy;
            if (nr >= 0 && nr < n && nc >= 0 && nc < n) {
                covered[nr][nc] = true;
            }
        }
    }

    /**
     * Checks if every 'x' in the original grid is covered by at least one valid translation.
     */
    private static boolean allXAreCovered(int n, char[][] grid, boolean[][] covered) {
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 'x' && !covered[i][j]) {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Constructs and returns the final answer grid based on valid translations.
     */
    private static char[][] buildResultGrid(int n, List<Integer> oRows, List<Integer> oCols, List<Integer> validDx, List<Integer> validDy) {
        int size = 2 * n - 1;
        char[][] result = new char[size][size];
        for (int i = 0; i < size; i++) {
            Arrays.fill(result[i], '.');
        }
        result[n - 1][n - 1] = 'o';

        for (int i = 0; i < validDx.size(); i++) {
            int dx = validDx.get(i);
            int dy = validDy.get(i);
            result[n - 1 + dx][n - 1 + dy] = 'x';
        }
        return result;
    }

    /**
     * Fast I/O utility class to handle tokenized input efficiently.
     * Replaces static state with instance-based, thread-safe, and robust parsing.
     */
    static class FastScanner {
        private BufferedReader br;
        private StringTokenizer st;

        FastScanner(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in, StandardCharsets.UTF_8));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return st.nextToken();
        }
    }
}

