/**
 * Solves the grid pattern problem.
 * Encapsulates all business logic for grid initialization, pattern propagation, and validation.
 */
class GridSolver {

    /**
     * Orchestrates the solving process: parsing, grid construction, validation, and output.
     */
    public void solve(FastScanner scanner, PrintWriter writer) {
        int n = scanner.nextInt();
        char[][] inputGrid = new char[n][n];

        // Read the n x n input grid
        for (int i = 0; i < n; i++) {
            inputGrid[i] = scanner.next().toCharArray();
        }

        // Initialize output grid of size (2n-1) x (2n-1) filled with 'x'
        int gridSize = 2 * n - 1;
        char[][] outputGrid = new char[gridSize][gridSize];
        for (char[] row : outputGrid) {
            Arrays.fill(row, 'x');
        }

        // Place the anchor 'o' at the exact center
        int center = n - 1;
        outputGrid[center][center] = 'o';

        // Propagate '.' patterns from input grid to output grid based on 'o' positions
        populatePattern(inputGrid, outputGrid, center);

        // Validate that all 'x' positions in input satisfy the required condition
        boolean isValid = validateAgainstX(inputGrid, outputGrid, center);

        // Output results
        if (isValid) {
            writer.println("YES");
            for (char[] row : outputGrid) {
                writer.println(row);
            }
        } else {
            writer.println("NO");
        }
    }

    /**
     * Translates the '.' pattern from the input grid to the output grid.
     * For every 'o' in the input grid, the entire '.' pattern is shifted so that
     * the 'o' aligns with the center coordinate of the output grid.
     */
    private void populatePattern(char[][] input, char[][] output, int center) {
        int n = input.length;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (input[i][j] == 'o') {
                    for (int k = 0; k < n; k++) {
                        for (int m = 0; m < n; m++) {
                            if (input[k][m] == '.') {
                                output[center + (k - i)][center + (m - j)] = '.';
                            }
                        }
                    }
                }
            }
        }
    }

    /**
     * Validates the configuration against 'x' positions in the input grid.
     * For each 'x' in the input, checks if there exists at least one 'o' in the input
     * such that the corresponding mapped position in the output grid is also 'x'.
     * Returns false immediately if any 'x' fails this condition.
     */
    private boolean validateAgainstX(char[][] input, char[][] output, int center) {
        int n = input.length;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (input[i][j] == 'x') {
                    boolean foundMatch = false;
                    for (int k = 0; k < n; k++) {
                        for (int m = 0; m < n; m++) {
                            if (input[k][m] == 'o') {
                                if (output[center + (i - k)][center + (j - m)] == 'x') {
                                    foundMatch = true;
                                    break;
                                }
                            }
                        }
                        if (foundMatch) break;
                    }
                    if (!foundMatch) {
                        return false;
                    }
                }
            }
        }
        return true;
    }
}

