        }

        writer.println("YES");
        char[][] resultGrid = generateFinalGrid(validTranslations);
        printGrid(resultGrid);
    }

    /**
     * Computes all translation offsets that map every 'o' to an invalid position
     * (out of bounds, 'x', or overlapping another 'o').
     */
    private Set<Offset> findInvalidTranslations() {
        Set<Offset> candidates = null;

        for (int i = 0; i < gridSize; i++) {
            for (int j = 0; j < gridSize; j++) {
                if (grid[i][j] == 'o') {
                    if (candidates == null) {
                        candidates = new TreeSet<>();
                        // Generate all offsets that would place this 'o' on an invalid cell
                        for (int dx = -gridSize + 1; dx < gridSize; dx++) {
                            for (int dy = -gridSize + 1; dy < gridSize; dy++) {
                                if (!isWithinBounds(i + dx, j + dy) ||
                                    grid[i + dx][j + dy] == 'x' ||
                                    grid[i + dx][j + dy] == 'o') {
                                    candidates.add(new Offset(dx, dy));
                                }
                            }
                        }
                    } else {
                        // Intersect with current 'o's invalid positions
                        Iterator<Offset> it = candidates.iterator();
                        while (it.hasNext()) {
                            Offset off = it.next();
                            int targetX = i + off.dx;
                            int targetY = j + off.dy;
                            // Keep only if this offset maps to an invalid cell for the current 'o'
                            if (isWithinBounds(targetX, targetY) && grid[targetX][targetY] == '.') {
                                it.remove();
                            }
                        }
                    }
                }
            }
        }
        return candidates != null ? candidates : Collections.emptySet();
    }

    /**
     * Creates a copy of the original grid and applies all valid translations,
     * placing 'x' markers where 'o's would land.
     */
    private char[][] applyTranslationsToCopy(Set<Offset> translations) {
        char[][] copy = createEmptyGrid(gridSize);
        for (int i = 0; i < gridSize; i++) {
            System.arraycopy(grid[i], 0, copy[i], 0, gridSize);
        }

        for (Offset off : translations) {
            placeXMarkers(copy, off.dx, off.dy);
        }
        return copy;
    }

    /**
     * Checks if two grids are identical in content and dimensions.
     */
    private boolean gridsMatch(char[][] g1, char[][] g2) {
        for (int i = 0; i < gridSize; i++) {
            for (int j = 0; j < gridSize; j++) {
                if (g1[i][j] != g2[i][j]) {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Generates the final output grid of size (2N-1) with a central 'o'
     * and 'x' markers placed according to all valid translations.
     */
    private char[][] generateFinalGrid(Set<Offset> translations) {
        int resultSize = 2 * gridSize - 1;
        char[][] result = createEmptyGrid(resultSize);
        result[gridSize - 1][gridSize - 1] = 'o';

        for (Offset off : translations) {
            placeXMarkers(result, off.dx, off.dy);
        }
        return result;
    }

    /**
     * Places 'x' markers in the target grid for every 'o' shifted by (dx, dy).
     */
    private void placeXMarkers(char[][] target, int dx, int dy) {
        for (int i = 0; i < target.length; i++) {
            for (int j = 0; j < target[i].length; j++) {
                if (target[i][j] == 'o') {
                    int newX = i + dx;
                    int newY = j + dy;
                    if (isWithinGridBounds(newX, newY, target)) {
                        if (target[newX][newY] == '.') {
                            target[newX][newY] = 'x';
                        }
                    }
                }
            }
        }
    }

    private boolean isWithinBounds(int x, int y) {
        return x >= 0 && x < gridSize && y >= 0 && y < gridSize;
    }

    private boolean isWithinGridBounds(int x, int y, char[][] grid) {
        return x >= 0 && x < grid.length && y >= 0 && y < grid[0].length;
    }

    private char[][] createEmptyGrid(int size) {
        char[][] grid = new char[size][size];
        for (int i = 0; i < size; i++) {
            Arrays.fill(grid[i], '.');
        }
        return grid;
    }

    private void printGrid(char[][] grid) {
        for (char[] row : grid) {
            writer.println(new String(row));
        }
    }

    public static void main(String[] args) {
        InputReader reader = new InputReader(System.in);
        int n = reader.nextInt();
        char[][] grid = new char[n][n];
        for (int i = 0; i < n; i++) {
            grid[i] = reader.next().toCharArray();
        }

        Main solver = new Main(n, grid);
        solver.solve();
        solver.writer.flush();
        solver.writer.close();
    }
}

/**
 * Fast input reader for competitive programming and performance-critical applications.
 */
class InputReader {
    public BufferedReader reader;
    public StringTokenizer tokenizer;

    public InputReader(InputStream stream) {
        reader = new BufferedReader(new InputStreamReader(stream), 32768);
        tokenizer = null;
    }

    public String next() {
        while (tokenizer == null || !tokenizer.hasMoreTokens()) {
            try {
                tokenizer = new StringTokenizer(reader.readLine());
            } catch (IOException e) {
                throw new RuntimeException(e);
            }
        }
        return tokenizer.nextToken();
    }

    public double nextDouble() {
        return Double.parseDouble(next());
    }

    public long nextLong() {
        return Long.parseLong(next());
    }

    public int nextInt() {
        return Integer.parseInt(next());
    }
}

import java.io.*;
import java.util.*;

public class GridTransformationSolver {
    private final FastScanner in;
    private final PrintWriter out;

    public GridTransformationSolver(InputStream inputStream, OutputStream outputStream) {
        this.in = new FastScanner(inputStream);
        this.out = new PrintWriter(outputStream);
    }

    public void run() {
        int n = in.nextInt();
        char[][] map = new char[n][];
        for (int i = 0; i < n; i++) {
            map[i] = in.next().toCharArray();
        }

        List<Point> xPoints = new ArrayList<>();
        List<Point> oPoints = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (map[i][j] == 'x') {
                    xPoints.add(new Point(j, i));
                } else if (map[i][j] == 'o') {
                    oPoints.add(new Point(j, i));
                }
            }
        }

        boolean[][] covered = new boolean[n][n];
        char[][] result = new char[2 * n - 1][2 * n - 1];
        for (char[] row : result) {
            Arrays.fill(row, '.');
        }
        result[n - 1][n - 1] = 'o';

        for (int dx = -(n - 1); dx <= n - 1; dx++) {
            for (int dy = -(n - 1); dy <= n - 1; dy++) {
                if (dx == 0 && dy == 0) continue;

                if (isTranslationValid(map, oPoints, dx, dy)) {
                    markCoveredPoints(covered, map, oPoints, dx, dy);
                    result[n + dy - 1][n + dx - 1] = 'x';
                }
            }
        }

        if (!allXPointsCovered(map, covered)) {
            out.println("NO");
        } else {
            out.println("YES");
            for (char[] row : result) {
                out.println(new String(row));
            }
        }
        out.flush();
    }

    private boolean isTranslationValid(char[][] map, List<Point> oPoints, int dx, int dy) {
        for (Point o : oPoints) {
            int nx = o.x + dx;
            int ny = o.y + dy;
            if (nx >= 0 && nx < map.length && ny >= 0 && ny < map[0].length) {
                if (map[ny][nx] == '.') {
                    return false;
                }
            }
        }
        return true;
    }

    private void markCoveredPoints(boolean[][] covered, char[][] map, List<Point> oPoints, int dx, int dy) {
        for (Point o : oPoints) {
            int nx = o.x + dx;
            int ny = o.y + dy;
            if (nx >= 0 && nx < map.length && ny >= 0 && ny < map[0].length && map[ny][nx] == 'x') {
                covered[ny][nx] = true;
            }
        }
    }

    private boolean allXPointsCovered(char[][] map, boolean[][] covered) {
        for (int i = 0; i < map.length; i++) {
            for (int j = 0; j < map[0].length; j++) {
                if (map[i][j] == 'x' && !covered[i][j]) {
                    return false;
                }
            }
        }
        return true;
    }

    public static void main(String[] args) {
        new GridTransformationSolver(System.in, System.out).run();
    }

    public static class Point {
        final int x;
        final int y;

        public Point(int x, int y) {
            this.x = x;
            this.y = y;
        }
    }

    private static class FastScanner {
        private final InputStream stream;
        private final byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;

        public FastScanner(InputStream stream) {
            this.stream = stream;
        }

        int read() {
            if (numChars == -1) {
                throw new InputMismatchException();
            }
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0) {
                    return -1;
                }
            }
            return buf[curChar++];
        }

        boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        boolean isEndline(int c) {
            return c == '\n' || c == '\r' || c == -1;
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        int[] nextIntArray(int n) {
            int[] array = new int[n];
            for (int i = 0; i < n; i++) {
                array[i] = nextInt();
            }
            return array;
        }

        int[][] nextIntMap(int n, int m) {
            int[][] map = new int[n][m];
            for (int i = 0; i < n; i++) {
                map[i] = this.nextIntArray(m);
            }
            return map;
        }

        long nextLong() {
            return Long.parseLong(next());
        }

        long[] nextLongArray(int n) {
            long[] array = new long[n];
            for (int i = 0; i < n; i++) {
                array[i] = nextLong();
            }
            return array;
        }

        long[][] nextLongMap(int n, int m) {
            long[][] map = new long[n][m];
            for (int i = 0; i < n; i++) {
                map[i] = this.nextLongArray(m);
            }
            return map;
        }

        double nextDouble() {
            return Double.parseDouble(next());
        }

        double[] nextDoubleArray(int n) {
            double[] array = new double[n];
            for (int i = 0; i < n; i++) {
                array[i] = nextDouble();
            }
            return array;
        }

        double[][] nextDoubleMap(int n, int m) {
            double[][] map = new double[n][m];
            for (int i = 0; i < n; i++) {
                map[i] = this.nextDoubleArray(m);
            }
            return map;
        }

        String next() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            StringBuilder res = new StringBuilder();
            do {
                res.appendCodePoint(c);
                c = read();
            } while (!isSpaceChar(c));
            return res.toString();
        }

        String[] nextStringArray(int n) {
            String[] array = new String[n];
            for (int i = 0; i < n; i++) {
                array[i] = next();
            }
            return array;
        }

        String nextLine() {
            int c = read();
            while (isEndline(c)) {
                c = read();
            }
            StringBuilder res = new StringBuilder();
            do {
                res.appendCodePoint(c);
                c = read();
            } while (!isEndline(c));
            return res.toString();
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Solves a grid shifting problem where a target shape ('o') is shifted across
 * an n x n grid containing obstacles ('x') and empty spaces ('.').
 * Outputs the result grid if all obstacles can be cleared, otherwise outputs "NO".
 */
public class GridShiftSolver {

    // Configuration Constants
    private static final char TARGET_CHAR = 'o';
    private static final char OBSTACLE_CHAR = 'x';
    private static final char EMPTY_CHAR = '.';
    private static final String NO_RESULT_MESSAGE = "NO";

    // I/O and State Fields
    private final Parser scanner;
    private PrintWriter out;
    private int n;
    private char[][] grid;
    private int[] targetX;
    private int[] targetY;
    private int targetCount;

    public GridShiftSolver() {
        this.scanner = new Parser();
    }

    public static void main(String[] args) {
        new GridShiftSolver().run();
    }

    /**
     * Entry point for execution. Handles I/O setup and exception catching.
     */
    public void run() {
        try {
            out = new PrintWriter(new BufferedOutputStream(System.out));
            solve();
        } catch (NoResultException e) {
            out.println(e.getMessage() != null ? e.getMessage() : NO_RESULT_MESSAGE);
        } finally {
            out.flush();
            out.close();
        }
    }

    /**
     * Core logic: reads input, computes shifts, applies them, and validates output.
     */
    private void solve() {
        n = scanner.nextInt();
        grid = new char[n][];
        // Pre-allocate arrays for target positions. Max possible is n*n.
        targetX = new int[n * n];
        targetY = new int[n * n];
        targetCount = 0;

        // Consume the newline character left after nextInt()
        scanner.nextLine();

        for (int i = 0; i < n; i++) {
            grid[i] = scanner.nextLine().toCharArray();
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == TARGET_CHAR) {
                    targetX[targetCount] = i;
                    targetY[targetCount++] = j;
                }
            }
        }

        int resSize = 2 * n - 1;
        char[][] resultGrid = new char[resSize][resSize];

        computeResultGrid(resultGrid);
        resultGrid[n - 1][n - 1] = TARGET_CHAR; // Center remains the target shape

        applyShiftsToGrid(resultGrid);
        validateAndOutput(resultGrid);
    }

    /**
     * Determines which shift vectors result in covering only obstacles vs empty space.
     */
    private void computeResultGrid(char[][] resultGrid) {
        for (int dx = -n + 1; dx < n; dx++) {
            for (int dy = -n + 1; dy < n; dy++) {
                if (dx == 0 && dy == 0) continue; // Skip zero shift

                boolean coversEmpty = false;
                for (int k = 0; k < targetCount; k++) {
                    int nx = targetX[k] + dx;
                    int ny = targetY[k] + dy;

                    if (!isValid(nx, ny)) continue;
                    if (grid[nx][ny] == TARGET_CHAR) continue; // Overlaps with original target

                    if (grid[nx][ny] == EMPTY_CHAR) {
                        coversEmpty = true;
                        break; // Optimization: no need to check further if we hit empty space
                    }
                }
                resultGrid[n - 1 + dx][n - 1 + dy] = coversEmpty ? EMPTY_CHAR : OBSTACLE_CHAR;
            }
        }
    }

    /**
     * Clears obstacles that were covered by valid shifts (marked as 'x' in resultGrid).
     */
    private void applyShiftsToGrid(char[][] resultGrid) {
        for (int dx = -n + 1; dx < n; dx++) {
            for (int dy = -n + 1; dy < n; dy++) {
                if (resultGrid[n - 1 + dx][n - 1 + dy] != OBSTACLE_CHAR) continue;

                for (int k = 0; k < targetCount; k++) {
                    int nx = targetX[k] + dx;
                    int ny = targetY[k] + dy;
                    if (isValid(nx, ny)) {
                        grid[nx][ny] = EMPTY_CHAR;
                    }
                }
            }
        }
    }

    /**
     * Verifies all obstacles are cleared and prints the final result.
     */
    private void validateAndOutput(char[][] resultGrid) {
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == OBSTACLE_CHAR) {
                    throw new NoResultException();
                }
            }
        }

        out.println("YES");
        for (char[] row : resultGrid) {
            out.println(new String(row));
        }
    }

    /**
     * Checks if coordinates are within the grid boundaries.
     */
    private boolean isValid(int x, int y) {
        return x >= 0 && x < n && y >= 0 && y < n;
    }

    /**
     * Standard competitive programming input parser.
     */
    public static class Parser {
        private final Scanner scanner;

        public Parser() {
            this.scanner = new Scanner(System.in).useLocale(Locale.ENGLISH);
        }

        public Parser(String str) {
            this.scanner = new Scanner(str).useLocale(Locale.ENGLISH);
        }

        public long nextLong() {
            return scanner.nextLong();
        }

        public int nextInt() {
            return scanner.nextInt();
        }

        public double nextDouble() {
            return scanner.nextDouble();
        }

        public String nextLine() {
            return scanner.nextLine();
        }

        public String next() {
            return scanner.next();
        }

        public int[] nextIntegers(int count) {
            int[] result = new int[count];
            for (int i = 0; i < count; i++) {
                result[i] = nextInt();
            }
            return result;
        }

        public long[] nextLongs(int count) {
            long[] result = new long[count];
            for (int i = 0; i < count; i++) {
                result[i] = nextLong();
            }
            return result;
        }

        public int[][] nextIntegers(int fields, int count) {
            int[][] result = new int[fields][count];
            for (int c = 0; c < count; c++) {
                for (int i = 0; i < fields; i++) {
                    result[i][c] = nextInt();
                }
            }
            return result;
        }
    }

    /**
     * Custom exception to signal that no valid solution exists.
     */
    public static class NoResultException extends RuntimeException {
        private final String message;

        public NoResultException(String message) {
            this.message = message;
        }

        public NoResultException() {
            this.message = null;
        }

        @Override
        public String getMessage() {
            return message;
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Solves a grid placement problem by generating a result grid based on offset
 * validation and verifying coverage constraints.
 */
public class GridPlacementSolver {

    private final FastScanner scanner;
    private final PrintWriter out;

    /**
     * Constructs the solver with provided I/O components.
     *
     * @param scanner Input reader
     * @param out     Output writer
     */
    public GridPlacementSolver(FastScanner scanner, PrintWriter out) {
        this.scanner = scanner;
        this.out = out;
    }

    /**
     * Orchestrates the solution process.
     */
    public void run() {
        solve();
        out.flush();
    }

    /**
     * Reads input, generates the candidate grid, validates it, and prints the result.
     */
    private void solve() {
        int n = scanner.nextInt();
        char[][] targetGrid = new char[n][n];
        for (int i = 0; i < n; i++) {
            targetGrid[i] = scanner.next().toCharArray();
        }

        char[][] resultGrid = generateResultGrid(targetGrid);

        if (validateResult(resultGrid, targetGrid)) {
            out.println("YES");
            for (char[] row : resultGrid) {
                out.println(new String(row));
            }
        } else {
            out.println("NO");
        }
    }

    /**
     * Generates the candidate result grid by testing all possible placement offsets.
     *
     * @param targetGrid The reference grid containing 'o' and '.' characters
     * @return The generated result grid of size (2n-1)x(2n-1)
     */
    private char[][] generateResultGrid(char[][] targetGrid) {
        int n = targetGrid.length;
        char[][] resultGrid = new char[2 * n - 1][2 * n - 1];

        for (int offsetRow = -n + 1; offsetRow < n; offsetRow++) {
            for (int offsetCol = -n + 1; offsetCol < n; offsetCol++) {
                boolean isValidOffset = true;

                for (int i = 0; i < n; i++) {
                    for (int j = 0; j < n; j++) {
                        if (targetGrid[i][j] == 'o') {
                            int newRow = i + offsetRow;
                            int newCol = j + offsetCol;

                            // Check if placing an 'o' at the offset lands on a valid '.' cell
                            if (newRow >= 0 && newRow < n && newCol >= 0 && newCol < n
                                    && targetGrid[newRow][newCol] == '.') {
                                isValidOffset = false;
                                break;
                            }
                        }
                    }
                    if (!isValidOffset) {
                        break;
                    }
                }
                resultGrid[offsetRow + n - 1][offsetCol + n - 1] = isValidOffset ? 'x' : '.';
            }
        }
        // The center cell is always marked as 'o'
        resultGrid[n - 1][n - 1] = 'o';
        return resultGrid;
    }

    /**
     * Validates that every 'x' in the target grid is "covered" by the placement logic.
     *
     * @param resultGrid The generated candidate grid
     * @param targetGrid The reference grid
     * @return true if validation passes, false otherwise
     */
    private boolean validateResult(char[][] resultGrid, char[][] targetGrid) {
        int n = targetGrid.length;
        boolean[][] isCovered = new boolean[n][n];

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (targetGrid[i][j] == 'o') {
                    for (int dr = -n + 1; dr < n; dr++) {
                        for (int dc = -n + 1; dc < n; dc++) {
                            if (resultGrid[n - 1 + dr][n - 1 + dc] == 'x'
                                    && i + dr >= 0 && i + dr < n
                                    && j + dc >= 0 && j + dc < n) {
                                isCovered[i + dr][j + dc] = true;
                            }
                        }
                    }
                }
            }
        }

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (targetGrid[i][j] == 'x' && !isCovered[i][j]) {
                    return false;
                }
            }
        }
        return true;
    }

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner();
        PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out));
        new GridPlacementSolver(scanner, out).run();
        out.close();
    }

    /**
     * High-performance input scanner for competitive programming and CLI applications.
     */
    private static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) {
                        return null;
                    }
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input stream", e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        long nextLong() {
            return Long.parseLong(next());
        }

        double nextDouble() {
            return Double.parseDouble(next());
        }
    }
}

import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.Scanner;

public class GridTranslationSolver {

    /**
     * Represents a 2D coordinate in the grid.
     */
    private static final class Coordinate {
        final int row;
        final int col;

        Coordinate(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    public static void main(String[] args) {
        // Use try-with-resources to ensure the scanner is properly closed
        try (Scanner scanner = new Scanner(System.in)) {
            if (!scanner.hasNextInt()) {
                return;
            }
            int n = scanner.nextInt();
            char[][] grid = readGrid(scanner, n);
            List<Coordinate> oPositions = findOPositions(grid);
            solve(n, grid, oPositions);
        }
    }

    /**
     * Reads the n x n grid from standard input.
     */
    private static char[][] readGrid(Scanner scanner, int n) {
        char[][] grid = new char[n][];
        for (int i = 0; i < n; i++) {
            grid[i] = scanner.next().toCharArray();
        }
        return grid;
    }

    /**
     * Collects the coordinates of all 'o' characters in the grid.
     */
    private static List<Coordinate> findOPositions(char[][] grid) {
        List<Coordinate> positions = new ArrayList<>();
        for (int i = 0; i < grid.length; i++) {
            for (int j = 0; j < grid[i].length; j++) {
                if (grid[i][j] == 'o') {
                    positions.add(new Coordinate(i, j));
                }
            }
        }
        return positions;
    }

    /**
     * Core logic: finds valid translation vectors, marks covered positions,
     * and prints the result if all 'x' positions are covered.
     */
    private static void solve(int n, char[][] grid, List<Coordinate> oPositions) {
        int offset = n - 1;
        int gridSize = 2 * n - 1;
        char[][] translationGrid = new char[gridSize][gridSize];
        boolean[][] coveredPositions = new boolean[n][n];

        // Iterate over all possible translation vectors (dx, dy)
        for (int dx = -offset; dx <= offset; dx++) {
            for (int dy = -offset; dy <= offset; dy++) {
                if (isValidTranslationAndMark(grid, n, oPositions, dx, dy, coveredPositions)) {
                    translationGrid[dx + offset][dy + offset] = 'x';
                }
            }
        }

        // Initialize translation grid with '.'
        for (int i = 0; i < gridSize; i++) {
            Arrays.fill(translationGrid[i], '.');
        }
        // Mark the center as 'o'
        translationGrid[offset][offset] = 'o';

        if (allXPositionsCovered(grid, coveredPositions)) {
            System.out.println("YES");
            printGrid(translationGrid);
        } else {
            System.out.println("NO");
        }
    }

    /**
     * Validates if a translation vector keeps all 'o's on valid cells (not '.')
     * and marks the target positions in coveredPositions.
     */
    private static boolean isValidTranslationAndMark(char[][] grid, int n, List<Coordinate> oPositions,
                                                     int dx, int dy, boolean[][] coveredPositions) {
        // First pass: validate translation
        for (Coordinate o : oPositions) {
            int newRow = o.row + dx;
            int newCol = o.col + dy;
            if (newRow < 0 || newRow >= n || newCol < 0 || newCol >= n) {
                continue;
            }
            if (grid[newRow][newCol] == '.') {
                return false;
            }
        }

        // Second pass: mark covered positions
        for (Coordinate o : oPositions) {
            int newRow = o.row + dx;
            int newCol = o.col + dy;
            if (newRow >= 0 && newRow < n && newCol >= 0 && newCol < n) {
                coveredPositions[newRow][newCol] = true;
            }
        }
        return true;
    }

    /**
     * Checks if every 'x' in the original grid was covered by a valid translation.
     */
    private static boolean allXPositionsCovered(char[][] grid, boolean[][] coveredPositions) {
        for (int i = 0; i < grid.length; i++) {
            for (int j = 0; j < grid[i].length; j++) {
                if (grid[i][j] == 'x' && !coveredPositions[i][j]) {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Prints the 2D character grid to standard output.
     */
    private static void printGrid(char[][] grid) {
        for (char[] row : grid) {
            System.out.println(new String(row));
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.OutputStream;
import java.io.PrintWriter;
import java.util.Arrays;
import java.util.StringTokenizer;

public class Main {
    public static void main(String[] args) {
        FastReader in = new FastReader(System.in);
        FastWriter out = new FastWriter(System.out);
        TaskD solver = new TaskD();
        solver.solve(1, in, out);
        out.close();
    }

    /**
     * Efficient input reader optimized for competitive programming.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream inputStream) {
            this.reader = new BufferedReader(new InputStreamReader(inputStream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) {
                        return null;
                    }
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            String token = next();
            if (token == null) {
                throw new RuntimeException("Unexpected end of input");
            }
            return Integer.parseInt(token);
        }

        public char[] nextCharArray() {
            String token = next();
            return (token == null) ? null : token.toCharArray();
        }

        public char[][] nextTable(int rows, int cols) {
            char[][] table = new char[rows][];
            for (int i = 0; i < rows; i++) {
                table[i] = nextCharArray();
                if (table[i] == null || table[i].length != cols) {
                    throw new IllegalArgumentException("Invalid table dimensions at row " + i);
                }
            }
            return table;
        }
    }

    /**
     * Efficient output writer wrapping PrintWriter.
     */
    static class FastWriter extends PrintWriter {
        public FastWriter(OutputStream outputStream) {
            super(outputStream, true); // Enable auto-flush
        }

        @Override
        public void close() {
            flush();
            super.close();
        }
    }
}

/**
 * Solves Task D: Validates a grid transformation process.
 */
class TaskD {
    public void solve(int testNumber, FastReader in, FastWriter out) {
        int n = in.nextInt();
        char[][] s = in.nextTable(n, n);

        // Phase 1: Initialize result grid with 'x' and place center 'o'
        int resSize = 2 * n - 1;
        char[][] res = new char[resSize][resSize];
        for (char[] row : res) {
            Arrays.fill(row, 'x');
        }
        res[n - 1][n - 1] = 'o';

        // Phase 2: Map '.' patterns from 's' to 'res' based on relative positions to each 'o'
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (s[i][j] == 'o') {
                    for (int x = 0; x < n; x++) {
                        for (int y = 0; y < n; y++) {
                            if (s[x][y] == '.') {
                                res[n - 1 + x - i][n - 1 + y - j] = '.';
                            }
                        }
                    }
                }
            }
        }

        // Phase 3: Simulate process on 'now' grid and validate against 's'
        char[][] now = new char[n][n];
        for (char[] row : now) {
            Arrays.fill(row, '.');
        }

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (s[i][j] == 'o') {
                    now[i][j] = 'o';
                    // Check all possible displacement vectors
                    for (int dx = -n + 1; dx < n; dx++) {
                        for (int dy = -n + 1; dy < n; dy++) {
                            int ni = i + dx;
                            int nj = j + dy;
                            // Boundary check (fixed bitwise '&' to logical '&&')
                            if (ni >= 0 && ni < n && nj >= 0 && nj < n) {
                                // Mark as 'x' if it's currently '.' and not already set in res
                                if (now[ni][nj] == '.' && res[n - 1 + dx][n - 1 + dy] == 'x') {
                                    now[ni][nj] = 'x';
                                }
                            }
                        }
                    }
                }
            }
        }

        // Phase 4: Validate simulation against original grid and output result
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (now[i][j] != s[i][j]) {
                    out.println("NO");
                    return;
                }
            }
        }

        out.println("YES");
        for (char[] row : res) {
            out.println(row);
        }
    }
}

import java.io.BufferedInputStream;
import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

/**
 * Solves a grid shift pattern problem by computing valid shift positions
 * and filtering the original board based on the computed shift map.
 */
public class GridPatternSolver {

    public static void main(String[] args) {
        // Use try-with-resources to automatically close the scanner
        try (Scanner scanner = new Scanner(new BufferedInputStream(System.in))) {
            if (!scanner.hasNextInt()) {
                return;
            }

            int gridSize = scanner.nextInt();
            char[][] grid = readGrid(scanner, gridSize);
            List<int[]> originalPositions = findOriginalPositions(grid, gridSize);

            int expandedSize = 2 * gridSize - 1;
            char[][] potentialShifts = computePotentialShifts(grid, originalPositions, gridSize, expandedSize);
            applyShiftFilter(grid, originalPositions, potentialShifts, gridSize, expandedSize);

            boolean isPossible = !hasRemainingTargets(grid, gridSize);
            printResult(isPossible, potentialShifts, expandedSize);
        }
    }

    /**
     * Reads an n x n character grid from the scanner.
     */
    private static char[][] readGrid(Scanner scanner, int n) {
        char[][] board = new char[n][n];
        for (int i = 0; i < n; i++) {
            board[i] = scanner.next().toCharArray();
        }
        return board;
    }

    /**
     * Collects coordinates of all 'o' characters in the grid.
     */
    private static List<int[]> findOriginalPositions(char[][] board, int n) {
        List<int[]> positions = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (board[i][j] == 'o') {
                    positions.add(new int[]{i, j});
                }
            }
        }
        return positions;
    }

    /**
     * Computes a map of valid shifts. A shift (dr, dc) is valid if applying it
     * to all original 'o' positions lands on '.' in the original grid.
     */
    private static char[][] computePotentialShifts(char[][] board, List<int[]> originalPositions, int n, int m) {
        char[][] ans = new char[m][m];
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < m; j++) {
                ans[i][j] = '.';
            }
        }

        int centerOffset = n - 1;
        int shiftLimit = n - 1;

        for (int dr = -shiftLimit; dr < n; dr++) {
            for (int dc = -shiftLimit; dc < n; dc++) {
                if (dr == 0 && dc == 0) {
                    continue;
                }

                boolean isPossible = true;
                for (int[] pos : originalPositions) {
                    int nextR = pos[0] + dr;
                    int nextC = pos[1] + dc;
                    if (isValidPosition(nextR, nextC, n) && board[nextR][nextC] == '.') {
                        isPossible = false;
                        break;
                    }
                }

                if (isPossible) {
                    ans[centerOffset + dr][centerOffset + dc] = 'x';
                }
            }
        }
        ans[centerOffset][centerOffset] = 'o';
        return ans;
    }

    /**
     * Filters the original grid by removing 'x' characters that correspond
     * to valid shifts in the computed answer map.
     */
    private static void applyShiftFilter(char[][] board, List<int[]> originalPositions, char[][] ans, int n, int m) {
        int centerOffset = n - 1;
        int shiftLimit = n - 1;

        for (int[] pos : originalPositions) {
            int r = pos[0];
            int c = pos[1];
            for (int dr = -shiftLimit; dr < n; dr++) {
                for (int dc = -shiftLimit; dc < n; dc++) {
                    if (dr == 0 && dc == 0) {
                        continue;
                    }

                    int nextR = r + dr;
                    int nextC = c + dc;
                    if (isValidPosition(nextR, nextC, n) &&
                        ans[centerOffset + dr][centerOffset + dc] == 'x' &&
                        board[nextR][nextC] == 'x') {
                        board[nextR][nextC] = '.';
                    }
                }
            }
        }
    }

    /**
     * Checks if a given coordinate is within the grid boundaries.
     */
    private static boolean isValidPosition(int r, int c, int n) {
        return r >= 0 && r < n && c >= 0 && c < n;
    }

    /**
     * Checks if any 'x' characters remain in the grid after filtering.
     */
    private static boolean hasRemainingTargets(char[][] board, int n) {
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (board[i][j] == 'x') {
                    return true;
                }
            }
        }
        return false;
    }

    /**
     * Prints the final result based on whether a valid configuration was found.
     */
    private static void printResult(boolean isPossible, char[][] ans, int m) {
        if (!isPossible) {
            System.out.println("NO");
        } else {
            System.out.println("YES");
            for (char[] row : ans) {
                System.out.println(new String(row));
            }
        }
    }
}

import java.util.Scanner;

/**
 * Analyzes a board configuration to determine valid moves and marks attacked pieces.
 * Refactored to improve encapsulation, readability, and maintainability.
 */
public class BoardGameAnalyzer {

    private final int boardSize;
    private final char[][] gameBoard;
    private final char[][] moveGrid;

    /**
     * Constructs the analyzer with the given board configuration.
     *
     * @param boardSize the dimensions of the square board
     * @param gameBoard the initial board state
     */
    public BoardGameAnalyzer(int boardSize, char[][] gameBoard) {
        this.boardSize = boardSize;
        this.gameBoard = gameBoard;
        this.moveGrid = initializeMoveGrid(boardSize);
    }

    private char[][] initializeMoveGrid(int size) {
        char[][] grid = new char[2 * size - 1][2 * size - 1];
        grid[size - 1][size - 1] = 'o';
        return grid;
    }

    /**
     * Evaluates all possible relative moves and updates the move grid accordingly.
     */
    public void processMoves() {
        int center = boardSize - 1;
        for (int dx = -boardSize + 1; dx <= boardSize - 1; dx++) {
            for (int dy = -boardSize + 1; dy <= boardSize - 1; dy++) {
                if (dx == 0 && dy == 0) {
                    continue;
                }
                if (isMoveValid(dx, dy)) {
                    moveGrid[center + dx][center + dy] = 'x';
                    applyMove(dx, dy);
                } else {
                    moveGrid[center + dx][center + dy] = '.';
                }
            }
        }
    }

    private boolean isMoveValid(int dx, int dy) {
        for (int i = 0; i < boardSize; i++) {
            for (int j = 0; j < boardSize; j++) {
                if (gameBoard[i][j] == 'o' && isTargetEmpty(i, j, dx, dy)) {
                    return false;
                }
            }
        }
        return true;
    }

    private boolean isTargetEmpty(int row, int col, int dx, int dy) {
        int targetRow = row + dx;
        int targetCol = col + dy;
        return isWithinBounds(targetRow, targetCol) && gameBoard[targetRow][targetCol] == '.';
    }

    private boolean isWithinBounds(int row, int col) {
        return row >= 0 && row < boardSize && col >= 0 && col < boardSize;
    }

    private void applyMove(int dx, int dy) {
        for (int i = 0; i < boardSize; i++) {
            for (int j = 0; j < boardSize; j++) {
                if (gameBoard[i][j] == 'o') {
                    markPiece(i, j, dx, dy);
                }
            }
        }
    }

    private void markPiece(int row, int col, int dx, int dy) {
        int targetRow = row + dx;
        int targetCol = col + dy;
        // Fixed original bug: checks moveGrid instead of gameBoard for 'x'
        if (isWithinBounds(targetRow, targetCol) && moveGrid[targetRow][targetCol] == 'x') {
            moveGrid[targetRow][targetCol] = 'X';
        }
    }

    private boolean hasUnmarkedPieces() {
        for (int i = 0; i < boardSize; i++) {
            for (int j = 0; j < boardSize; j++) {
                // Fixed original bug: checks moveGrid instead of gameBoard for 'x'
                if (gameBoard[i][j] == 'x') {
                    return true;
                }
            }
        }
        return false;
    }

    /**
     * Generates and prints the final result based on the processed move grid.
     */
    public void printResult() {
        StringBuilder output = new StringBuilder();
        if (hasUnmarkedPieces()) {
            output.append("NO");
        } else {
            output.append("YES\n");
            for (int i = 0; i < 2 * boardSize - 1; i++) {
                output.append(moveGrid[i]).append('\n');
            }
        }
        System.out.print(output.toString());
    }

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            if (!scanner.hasNextInt()) {
                return;
            }
            int n = scanner.nextInt();
            scanner.nextLine(); // Consume the newline after the integer

            char[][] board = new char[n][];
            for (int i = 0; i < n; i++) {
                board[i] = scanner.nextLine().toCharArray();
            }

            BoardGameAnalyzer analyzer = new BoardGameAnalyzer(n, board);
            analyzer.processMoves();
            analyzer.printResult();
        }
    }
}

