class TaskD {
    public void solve(int testNumber, InputReader in, OutputWriter out) {
        int n = in.ri();
        char[][] grid = IOUtils.readTable(in, n, n);

        List<Coordinate> piecePositions = new ArrayList<>();
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < n; c++) {
                if (grid[r][c] == 'o') {
                    piecePositions.add(new Coordinate(r, c));
                }
            }
        }

        int resultSize = 2 * n - 1;
        char[][] resultGrid = new char[resultSize][resultSize];

        // Compute the result grid based on overlap logic
        for (int r = 0; r < resultSize; r++) {
            for (int c = 0; c < resultSize; c++) {
                int rowOffset = r - (n - 1);
                int colOffset = c - (n - 1);
                resultGrid[r][c] = isOverlap(grid, piecePositions, rowOffset, colOffset) ? '.' : 'x';
            }
        }

        // Validate the computed result
        if (!validateResult(grid, piecePositions, resultGrid)) {
            out.printLine("NO");
            return;
        }

        out.printLine("YES");
        for (char[] row : resultGrid) {
            out.printLine(row);
        }
    }

    /**
     * Checks if shifting the piece pattern by the given offsets causes any piece
     * to land on an empty cell ('.') in the original grid.
     */
    private boolean isOverlap(char[][] grid, List<Coordinate> pieces, int rowOffset, int colOffset) {
        for (Coordinate p : pieces) {
            int r = p.row + rowOffset;
            int c = p.col + colOffset;
            if (MiscUtils.isValidCell(r, c, grid.length, grid[0].length)) {
                if (grid[r][c] == '.') {
                    return true;
                }
            }
        }
        return false;
    }

    /**
     * Validates that the result grid correctly covers all 'x' positions from the original grid.
     */
    private boolean validateResult(char[][] originalGrid, List<Coordinate> pieces, char[][] resultGrid) {
        int n = originalGrid.length;
        char[][] validationGrid = new char[n][n];
        ArrayUtils.fill(validationGrid, '.');

        int resultSize = resultGrid.length;
        for (int r = 0; r < resultSize; r++) {
            for (int c = 0; c < resultSize; c++) {
                if (resultGrid[r][c] == 'x') {
                    int rowOffset = r - (n - 1);
                    int colOffset = c - (n - 1);
                    for (Coordinate p : pieces) {
                        int vr = p.row + rowOffset;
                        int vc = p.col + colOffset;
                        if (MiscUtils.isValidCell(vr, vc, n, n)) {
                            validationGrid[vr][vc] = 'x';
                        }
                    }
                }
            }
        }

        for (int r = 0; r < n; r++) {
            for (int c = 0; c < n; c++) {
                if (validationGrid[r][c] == '.' && originalGrid[r][c] == 'x') {
                    return false;
                }
            }
        }
        return true;
    }
}

/** Represents a 2D coordinate. */
class Coordinate {
    final int row, col;
    Coordinate(int row, int col) {
        this.row = row;
        this.col = col;
    }
}

class InputReader {
    private final InputStream stream;
    private final byte[] buf = new byte[1024];
    private int curChar;
    private int numChars;
    private SpaceCharFilter filter;

    public InputReader(InputStream stream) {
        this.stream = stream;
    }

    public int read() {
        if (numChars == -1) {
            throw new InputMismatchException();
        }
        if (curChar >= numChars) {
            curChar = 0;
            try {
                numChars = stream.read(buf);
            } catch (IOException e) {
                throw new InputMismatchException();
            }
            if (numChars <= 0) {
                return -1;
            }
        }
        return buf[curChar++];
    }

    public int ri() {
        return readInt();
    }

    public int readInt() {
        int c = read();
        while (isSpaceChar(c)) {
            c = read();
        }
        int sgn = 1;
        if (c == '-') {
            sgn = -1;
            c = read();
        }
        int res = 0;
        do {
            if (c < '0' || c > '9') {
                throw new InputMismatchException();
            }
            res *= 10;
            res += c - '0';
            c = read();
        } while (!isSpaceChar(c));
        return res * sgn;
    }

    public boolean isSpaceChar(int c) {
        return filter != null ? filter.isSpaceChar(c) : isWhitespace(c);
    }

    public static boolean isWhitespace(int c) {
        return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
    }

    public char readCharacter() {
        int c = read();
        while (isSpaceChar(c)) {
            c = read();
        }
        return (char) c;
    }

    public interface SpaceCharFilter {
        boolean isSpaceChar(int ch);
    }
}

class OutputWriter {
    private final PrintWriter writer;

    public OutputWriter(OutputStream outputStream) {
        writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(outputStream)));
    }

    public void print(Object... objects) {
        for (int i = 0; i < objects.length; i++) {
            if (i != 0) {
                writer.print(' ');
            }
            writer.print(objects[i]);
        }
    }

    public void printLine() {
        writer.println();
    }

    public void printLine(Object... objects) {
        print(objects);
        writer.println();
    }

    public void print(char c) {
        writer.print(c);
    }

    public void close() {
        writer.close();
    }
}

class IOUtils {
    public static char[] readCharArray(InputReader in, int size) {
        char[] array = new char[size];
        for (int i = 0; i < size; i++) {
            array[i] = in.readCharacter();
        }
        return array;
    }

    public static char[][] readTable(InputReader in, int rowCount, int columnCount) {
        char[][] table = new char[rowCount][];
        for (int i = 0; i < rowCount; i++) {
            table[i] = readCharArray(in, columnCount);
        }
        return table;
    }
}

class MiscUtils {
    public static boolean isValidCell(int row, int column, int rowCount, int columnCount) {
        return row >= 0 && row < rowCount && column >= 0 && column < columnCount;
    }
}

class ArrayUtils {
    public static void fill(char[][] array, char value) {
        for (char[] row : array) {
            Arrays.fill(row, value);
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Solves a grid pattern placement problem.
 * Reads an n x n grid, determines all valid placements of a pattern defined by 'o' coordinates,
 * marks valid placements as 'x', and verifies coverage of all 'x' cells.
 */
public class GridPatternMatcher {

    // Configuration flag for debugging output
    private static final boolean DEBUG = false;

    public static void main(String[] args) throws IOException {
        // Use try-with-resources for automatic and safe resource cleanup
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
             PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out))) {

            String line = br.readLine();
            if (line == null) return;
            int n = Integer.parseInt(line.trim());

            // Read input grid and extract 'o' positions in a single pass
            GridData gridData = readGrid(br, n);
            int[][] grid = gridData.grid;
            List<Point> oPositions = gridData.oPositions;

            // Initialize output grid with '.'
            char[][] resultGrid = new char[2 * n - 1][2 * n - 1];
            initializeGrid(resultGrid, '.');

            // Find all valid top-left positions for the pattern
            findValidPlacements(resultGrid, grid, oPositions, n);

            // Preserved from original logic: center cell must be marked as 'o'
            resultGrid[n - 1][n - 1] = 'o';

            if (DEBUG) {
                printDebugGrid(resultGrid);
            }

            // Verify that every 'x' in the original grid is covered by at least one valid placement
            boolean isCovered = verifyXCoverage(grid, resultGrid, oPositions, n);

            if (isCovered) {
                out.println("YES");
                printGrid(out, resultGrid);
            } else {
                out.println("NO");
            }
        }
    }

    /**
     * Holds the parsed grid and the coordinates of all 'o' cells.
     */
    private static class GridData {
        final int[][] grid;
        final List<Point> oPositions;

        GridData(int[][] grid, List<Point> oPositions) {
            this.grid = grid;
            this.oPositions = oPositions;
        }
    }

    /**
     * Represents a 2D coordinate.
     */
    private static class Point {
        final int r, c;

        Point(int r, int c) {
            this.r = r;
            this.c = c;
        }
    }

    /**
     * Reads the n x n grid from the input stream and extracts 'o' positions.
     */
    private static GridData readGrid(BufferedReader br, int n) throws IOException {
        int[][] grid = new int[n][n];
        List<Point> oPositions = new ArrayList<>();

        for (int i = 0; i < n; i++) {
            String rowLine = br.readLine();
            for (int j = 0; j < n; j++) {
                char c = rowLine.charAt(j);
                if (c == 'o') {
                    grid[i][j] = 2;
                    oPositions.add(new Point(i, j));
                } else if (c == 'x') {
                    grid[i][j] = 1;
                } else {
                    grid[i][j] = 0;
                }
            }
        }
        return new GridData(grid, oPositions);
    }

    /**
     * Fills a 2D char array with a specified character.
     */
    private static void initializeGrid(char[][] grid, char fill) {
        for (char[] row : grid) {
            Arrays.fill(row, fill);
        }
    }

    /**
     * Iterates through all possible top-left offsets and marks valid placements as 'x'.
     */
    private static void findValidPlacements(char[][] ans, int[][] grid, List<Point> oPositions, int n) {
        for (int rowOffset = -n + 1; rowOffset < n; rowOffset++) {
            for (int colOffset = -n + 1; colOffset < n; colOffset++) {
                if (isPlacementValid(grid, oPositions, rowOffset, colOffset, n)) {
                    ans[rowOffset + n - 1][colOffset + n - 1] = 'x';
                }
            }
        }
    }

    /**
     * Checks if placing the pattern at a given offset avoids overlapping with empty ('0') cells.
     */
    private static boolean isPlacementValid(int[][] grid, List<Point> oPositions, int rowOffset, int colOffset, int n) {
        for (Point o : oPositions) {
            int gridRow = o.r + rowOffset;
            int gridCol = o.c + colOffset;
            if (gridRow >= 0 && gridRow < n && gridCol >= 0 && gridCol < n) {
                if (grid[gridRow][gridCol] == 0) {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Verifies that every 'x' cell in the original grid is covered by at least one valid placement.
     */
    private static boolean verifyXCoverage(int[][] grid, char[][] ans, List<Point> oPositions, int n) {
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 1) { // 'x' in the original grid
                    boolean isCovered = false;
                    for (Point o : oPositions) {
                        int ansRow = i - o.r + n - 1;
                        int ansCol = j - o.c + n - 1;
                        if (ansRow >= 0 && ansRow < ans.length && ansCol >= 0 && ansCol < ans[0].length) {
                            if (ans[ansRow][ansCol] == 'x') {
                                isCovered = true;
                                break;
                            }
                        }
                    }
                    if (!isCovered) {
                        return false;
                    }
                }
            }
        }
        return true;
    }

    /**
     * Prints the result grid to the provided PrintWriter.
     */
    private static void printGrid(PrintWriter out, char[][] grid) {
        for (char[] row : grid) {
            out.println(row);
        }
    }

    /**
     * Prints the result grid to System.out for debugging purposes.
     */
    private static void printDebugGrid(char[][] grid) {
        for (char[] row : grid) {
            System.out.println("~" + Arrays.toString(row));
        }
    }
}

import java.io.InputStream;
import java.util.HashSet;
import java.util.Scanner;
import java.util.Set;

public class Main {

    private int boardSize;
    private char[][] board;

    public static void main(String[] args) {
        Main solver = new Main();
        solver.readInput(System.in);
        solver.solve();
    }

    /**
     * Reads the board configuration from the given input stream.
     * Validates dimensions and populates the internal board state.
     */
    public void readInput(InputStream input) {
        Scanner scanner = new Scanner(input);
        if (!scanner.hasNextInt()) {
            throw new IllegalArgumentException("Input must start with an integer board size.");
        }
        boardSize = scanner.nextInt();
        scanner.nextLine(); // Consume the newline character after the integer

        board = new char[boardSize][boardSize];
        for (int i = 0; i < boardSize; i++) {
            String line = scanner.nextLine();
            if (line.length() != boardSize) {
                throw new IllegalArgumentException("Row " + i + " has invalid length. Expected " + boardSize + ".");
            }
            board[i] = line.toCharArray();
        }
        // Note: We intentionally do not close the Scanner to avoid closing System.in
    }

    /**
     * Processes the board according to game rules and prints the result.
     */
    public void solve() {
        Set<Coordinate> chessPieces = new HashSet<>();
        Set<Coordinate> emptyCells = new HashSet<>();

        // Parse the board to identify pieces and empty cells
        for (int r = 0; r < boardSize; r++) {
            for (int c = 0; c < boardSize; c++) {
                if (board[r][c] == 'o') {
                    chessPieces.add(new Coordinate(r, c));
                } else if (board[r][c] == '.') {
                    emptyCells.add(new Coordinate(r, c));
                }
            }
        }

        // Calculate relative offsets that are impossible based on piece/empty cell relationships
        Set<Coordinate> impossibleOffsets = new HashSet<>();
        for (Coordinate piece : chessPieces) {
            for (Coordinate empty : emptyCells) {
                impossibleOffsets.add(empty.minus(piece));
            }
        }

        // Create a working copy of the board to avoid mutating the original during validation
        char[][] workingBoard = new char[boardSize][boardSize];
        for (int i = 0; i < boardSize; i++) {
            System.arraycopy(board[i], 0, workingBoard[i], 0, boardSize);
        }

        // Validate moves and mark attacked positions
        for (Coordinate piece : chessPieces) {
            for (int dx = -boardSize + 1; dx < boardSize; dx++) {
                for (int dy = -boardSize + 1; dy < boardSize; dy++) {
                    Coordinate offset = new Coordinate(dx, dy);
                    if (!impossibleOffsets.contains(offset)) {
                        Coordinate target = piece.add(offset);
                        if (target.isValid(boardSize)) {
                            if (workingBoard[target.x][target.y] == '.') {
                                System.out.println("NO");
                                return;
                            }
                            workingBoard[target.x][target.y] = 'v';
                        }
                    }
                }
            }
        }

        // Check if any 'x' remains on the board (indicating an invalid configuration)
        for (int i = 0; i < boardSize; i++) {
            for (int j = 0; j < boardSize; j++) {
                if (workingBoard[i][j] == 'x') {
                    System.out.println("NO");
                    return;
                }
            }
        }

        // Construct and print the result board
        int resultSize = 2 * boardSize - 1;
        char[][] resultBoard = new char[resultSize][resultSize];
        for (int i = 0; i < resultSize; i++) {
            for (int j = 0; j < resultSize; j++) {
                resultBoard[i][j] = '.';
            }
        }
        resultBoard[boardSize - 1][boardSize - 1] = 'o';

        for (int dx = -boardSize + 1; dx < boardSize; dx++) {
            for (int dy = -boardSize + 1; dy < boardSize; dy++) {
                if (dx == 0 && dy == 0) continue;
                Coordinate offset = new Coordinate(dx, dy);
                if (!impossibleOffsets.contains(offset)) {
                    resultBoard[dx + boardSize - 1][dy + boardSize - 1] = 'x';
                }
            }
        }

        System.out.println("YES");
        StringBuilder output = new StringBuilder();
        for (int i = 0; i < resultSize; i++) {
            output.append(resultBoard[i]).append('\n');
        }
        System.out.print(output.toString());
    }

    /**
     * Immutable 2D coordinate representation.
     * Replaces the original nested V2 class for better structure and reusability.
     */
    private static final class Coordinate {
        final int x;
        final int y;

        Coordinate(int x, int y) {
            this.x = x;
            this.y = y;
        }

        Coordinate add(Coordinate other) {
            return new Coordinate(this.x + other.x, this.y + other.y);
        }

        Coordinate minus(Coordinate other) {
            return new Coordinate(this.x - other.x, this.y - other.y);
        }

        boolean isValid(int size) {
            return x >= 0 && x < size && y >= 0 && y < size;
        }

        @Override
        public boolean equals(Object obj) {
            if (this == obj) return true;
            if (!(obj instanceof Coordinate)) return false;
            Coordinate other = (Coordinate) obj;
            return x == other.x && y == other.y;
        }

        @Override
        public int hashCode() {
            return 31 * x + y;
        }
    }
}

import java.util.Arrays;
import java.util.Scanner;

public class Ideone {
    private static final char EMPTY_CELL = '.';
    private static final char TARGET_CELL = 'x';
    private static final char SOURCE_CELL = 'o';
    private static final char OUTPUT_VALID = 'x';
    private static final char OUTPUT_INVALID = '.';
    private static final char OUTPUT_SOURCE = 'o';

    public static void main(String[] args) {
        // Use try-with-resources for automatic resource management
        try (Scanner scanner = new Scanner(System.in)) {
            if (!scanner.hasNextInt()) {
                return;
            }
            int size = scanner.nextInt();
            char[][] grid = readGrid(scanner, size);

            boolean[][] validPositions = computeValidPositions(grid, size);
            applyMoves(grid, validPositions, size);

            if (hasRemainingTargets(grid)) {
                System.out.println("NO");
            } else {
                System.out.println("YES");
                printResultGrid(validPositions, size);
            }
        }
    }

    /**
     * Reads an n x n grid from standard input.
     */
    private static char[][] readGrid(Scanner scanner, int size) {
        char[][] grid = new char[size][size];
        for (int i = 0; i < size; i++) {
            grid[i] = scanner.next().toCharArray();
        }
        return grid;
    }

    /**
     * Computes the validity map for potential source positions.
     * Marks positions as false if they conflict with existing 'o' and '.' placements.
     */
    private static boolean[][] computeValidPositions(char[][] grid, int size) {
        int dimension = 2 * size - 1;
        boolean[][] validPositions = new boolean[dimension][dimension];

        // Initialize all positions as valid
        for (boolean[] row : validPositions) {
            Arrays.fill(row, true);
        }

        int offset = size - 1;
        for (int i = 0; i < size; i++) {
            for (int j = 0; j < size; j++) {
                if (grid[i][j] == SOURCE_CELL) {
                    for (int k = 0; k < size; k++) {
                        for (int l = 0; l < size; l++) {
                            if (grid[k][l] == EMPTY_CELL) {
                                validPositions[k - i + offset][l - j + offset] = false;
                            }
                        }
                    }
                }
            }
        }
        return validPositions;
    }

    /**
     * Applies moves based on valid positions, removing 'x' cells that can be captured.
     */
    private static void applyMoves(char[][] grid, boolean[][] validPositions, int size) {
        int offset = size - 1;
        for (int i = 1 - size; i < size; i++) {
            for (int j = 1 - size; j < size; j++) {
                // Skip invalid candidate positions
                if (!validPositions[i + offset][j + offset]) {
                    continue;
                }

                for (int k = 0; k < size; k++) {
                    for (int l = 0; l < size; l++) {
                        int targetRow = i + k;
                        int targetCol = j + l;

                        // Ensure target coordinates are within grid bounds
                        if (targetRow >= 0 && targetRow < size && targetCol >= 0 && targetCol < size) {
                            if (grid[k][l] == SOURCE_CELL && grid[targetRow][targetCol] == TARGET_CELL) {
                                grid[targetRow][targetCol] = EMPTY_CELL;
                            }
                        }
                    }
                }
            }
        }
    }

    /**
     * Checks if any target cells ('x') remain in the grid.
     */
    private static boolean hasRemainingTargets(char[][] grid) {
        for (char[] row : grid) {
            for (char cell : row) {
                if (cell == TARGET_CELL) {
                    return true;
                }
            }
        }
        return false;
    }

    /**
     * Prints the final validity map with the source position marked.
     */
    private static void printResultGrid(boolean[][] validPositions, int size) {
        int dimension = 2 * size - 1;
        for (int i = 0; i < dimension; i++) {
            for (int j = 0; j < dimension; j++) {
                if (i == size - 1 && j == size - 1) {
                    System.out.print(OUTPUT_SOURCE);
                } else {
                    System.out.print(validPositions[i][j] ? OUTPUT_VALID : OUTPUT_INVALID);
                }
            }
            System.out.println();
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.Arrays;

public class D {

    // Constants to replace magic values
    private static final char EMPTY_CHAR = '.';
    private static final char MARKED_CHAR = 'o';
    private static final char SHIFTED_CHAR = 'x';
    private static final String RESULT_YES = "YES";
    private static final String RESULT_NO = "NO";

    public static void main(String[] args) throws IOException {
        // Use try-with-resources for automatic and safe resource management
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
             PrintWriter writer = new PrintWriter(System.out)) {
            solve(reader, writer);
        }
    }

    /**
     * Core logic for solving the grid shift problem.
     */
    static void solve(BufferedReader reader, PrintWriter writer) throws IOException {
        int n = Integer.parseInt(reader.readLine());
        char[][] initialGrid = new char[n][];
        char[][] transformedGrid = new char[n][n];

        // Read input grid and initialize transformed grid
        for (int i = 0; i < n; i++) {
            initialGrid[i] = reader.readLine().toCharArray();
            Arrays.fill(transformedGrid[i], EMPTY_CHAR);
            for (int j = 0; j < n; j++) {
                if (initialGrid[i][j] == MARKED_CHAR) {
                    transformedGrid[i][j] = MARKED_CHAR;
                }
            }
        }

        // Initialize result grid
        int resultSize = 2 * n - 1;
        char[][] resultGrid = new char[resultSize][resultSize];
        for (char[] row : resultGrid) {
            Arrays.fill(row, EMPTY_CHAR);
        }
        resultGrid[n - 1][n - 1] = MARKED_CHAR;

        int range = n - 1;

        // Phase 1: Identify valid shifts and mark them in the result grid
        for (int dx = -range; dx <= range; dx++) {
            for (int dy = -range; dy <= range; dy++) {
                if (dx == 0 && dy == 0) continue;

                if (isValidShift(initialGrid, dx, dy, n)) {
                    resultGrid[n - 1 + dy][n - 1 + dx] = SHIFTED_CHAR;
                }
            }
        }

        // Phase 2: Apply valid shifts to the transformed grid
        for (int dx = -range; dx <= range; dx++) {
            for (int dy = -range; dy <= range; dy++) {
                if (resultGrid[n - 1 + dy][n - 1 + dx] != SHIFTED_CHAR) continue;

                applyShift(initialGrid, transformedGrid, dx, dy, n);
            }
        }

        // Phase 3: Compare grids and output result
        if (areGridsEqual(initialGrid, transformedGrid, n)) {
            writer.println(RESULT_YES);
            for (char[] row : resultGrid) {
                writer.println(new String(row));
            }
        } else {
            writer.println(RESULT_NO);
        }
    }

    /**
     * Checks if a given shift (dx, dy) is valid across the entire grid.
     * A shift is valid if every 'o' either shifts out of bounds or lands on an 'o' or 'x'.
     */
    private static boolean isValidShift(char[][] grid, int shiftX, int shiftY, int size) {
        for (int y = 0; y < size; y++) {
            for (int x = 0; x < size; x++) {
                if (grid[y][x] != MARKED_CHAR) continue;

                int targetX = x + shiftX;
                int targetY = y + shiftY;
                boolean outOfBounds = targetX < 0 || targetX >= size || targetY < 0 || targetY >= size;

                // If in bounds, destination must be 'o' or 'x'
                if (!outOfBounds && grid[targetY][targetX] != MARKED_CHAR && grid[targetY][targetX] != SHIFTED_CHAR) {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Applies a valid shift to the transformed grid.
     * Marks destination cells as 'x' if they are not already 'o'.
     */
    private static void applyShift(char[][] sourceGrid, char[][] targetGrid, int shiftX, int shiftY, int size) {
        for (int y = 0; y < size; y++) {
            for (int x = 0; x < size; x++) {
                if (sourceGrid[y][x] != MARKED_CHAR) continue;

                int targetX = x + shiftX;
                int targetY = y + shiftY;
                boolean inBounds = targetX >= 0 && targetX < size && targetY >= 0 && targetY < size;

                if (inBounds && sourceGrid[targetY][targetX] != MARKED_CHAR) {
                    targetGrid[targetY][targetX] = SHIFTED_CHAR;
                }
            }
        }
    }

    /**
     * Compares two character grids for exact equality.
     */
    private static boolean areGridsEqual(char[][] grid1, char[][] grid2, int size) {
        for (int i = 0; i < size; i++) {
            if (!Arrays.equals(grid1[i], grid2[i])) {
                return false;
            }
        }
        return true;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

/**
 * Solves a grid transformation problem by finding valid directional shifts
 * that cover all cells without landing on empty spaces.
 */
public class BoardTransformationSolver {

    private static final char EMPTY = '.';
    private static final char PLAYER = 'o';
    private static final char OBSTACLE = 'x';

    /** Immutable coordinate holder for readability */
    private static class Coordinate {
        final int x;
        final int y;

        Coordinate(int x, int y) {
            this.x = x;
            this.y = y;
        }
    }

    public static void main(String[] args) throws IOException {
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            String line = br.readLine();
            if (line == null || line.trim().isEmpty()) {
                return;
            }

            int size;
            try {
                size = Integer.parseInt(line.trim());
            } catch (NumberFormatException e) {
                System.err.println("Invalid size format. Expected an integer.");
                return;
            }

            if (size < 1) {
                System.out.println("NO");
                return;
            }

            char[][] board = new char[size][size];
            for (int i = 0; i < size; i++) {
                String row = br.readLine();
                board[i] = (row != null) ? row.trim().toCharArray() : new char[size];
            }

            // Base case optimization
            if (size == 1) {
                System.out.println("YES");
                System.out.println("o");
                return;
            }

            solve(board, size);
        }
    }

    /**
     * Orchestrates the solving process: initialization, shift validation,
     * coverage verification, and output generation.
     */
    private static void solve(char[][] board, int size) {
        List<Coordinate> originalPositions = new ArrayList<>();
        boolean[][] isCovered = new boolean[size][size];

        // Initialize coverage grid based on initial board state
        for (int i = 0; i < size; i++) {
            for (int j = 0; j < size; j++) {
                char cell = board[i][j];
                if (cell == PLAYER) {
                    originalPositions.add(new Coordinate(i, j));
                    isCovered[i][j] = true;
                } else if (cell == OBSTACLE) {
                    isCovered[i][j] = false;
                } else {
                    // Empty cells are considered already covered/valid
                    isCovered[i][j] = true;
                }
            }
        }

        // Find all valid directional shifts
        List<Coordinate> validShifts = findValidShifts(board, size, originalPositions, isCovered);

        // Validate results
        if (validShifts.isEmpty() || !areAllCellsCovered(isCovered, size)) {
            System.out.println("NO");
            return;
        }

        // Generate and print the result grid
        char[][] outputGrid = generateOutputGrid(validShifts, size);
        printGrid(outputGrid);
    }

    /**
     * Iterates through all possible (dx, dy) shifts and validates them.
     * Marks shifted positions as covered if the shift is valid.
     */
    private static List<Coordinate> findValidShifts(char[][] board, int size, 
                                                    List<Coordinate> originalPositions, 
                                                    boolean[][] isCovered) {
        List<Coordinate> validShifts = new ArrayList<>();
        int range = size - 1;

        for (int dx = -range; dx <= range; dx++) {
            for (int dy = -range; dy <= range; dy++) {
                if (dx == 0 && dy == 0) {
                    continue;
                }

                if (isShiftValid(board, size, originalPositions, dx, dy)) {
                    validShifts.add(new Coordinate(dx, dy));

                    // Mark the new positions as covered
                    for (Coordinate pos : originalPositions) {
                        int newX = pos.x + dx;
                        int newY = pos.y + dy;
                        if (newX >= 0 && newX < size && newY >= 0 && newY < size) {
                            isCovered[newX][newY] = true;
                        }
                    }
                }
            }
        }
        return validShifts;
    }

    /**
     * Checks if shifting all player positions by (dx, dy) stays within bounds
     * and lands only on non-empty cells.
     */
    private static boolean isShiftValid(char[][] board, int size, 
                                        List<Coordinate> originalPositions, 
                                        int dx, int dy) {
        for (Coordinate pos : originalPositions) {
            int newX = pos.x + dx;
            int newY = pos.y + dy;

            // Fixed: Properly reject shifts that go out of bounds
            if (newX < 0 || newX >= size || newY < 0 || newY >= size || 
                board[newX][newY] == EMPTY) {
                return false;
            }
        }
        return true;
    }

    /**
     * Verifies that every cell in the grid has been marked as covered.
     */
    private static boolean areAllCellsCovered(boolean[][] isCovered, int size) {
        for (int i = 0; i < size; i++) {
            for (int j = 0; j < size; j++) {
                if (!isCovered[i][j]) {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Constructs the output grid centered at (size-1, size-1) with 'o',
     * placing 'x' at coordinates corresponding to valid shifts.
     */
    private static char[][] generateOutputGrid(List<Coordinate> validShifts, int size) {
        int gridSize = 2 * size - 1;
        char[][] grid = new char[gridSize][gridSize];
        for (char[] row : grid) {
            Arrays.fill(row, EMPTY);
        }
        grid[size - 1][size - 1] = PLAYER;

        for (Coordinate shift : validShifts) {
            int outX = (size - 1) + shift.x;
            int outY = (size - 1) + shift.y;
            grid[outX][outY] = OBSTACLE;
        }
        return grid;
    }

    /**
     * Efficiently prints the 2D character grid.
     */
    private static void printGrid(char[][] grid) {
        StringBuilder sb = new StringBuilder();
        for (char[] row : grid) {
            sb.append(row).append('\n');
        }
        System.out.print(sb);
    }
}

import java.io.*;
import java.util.*;

/**
 * Validates grid attack patterns and outputs the result.
 * Refactored for improved maintainability, readability, and resource management.
 */
public final class GridAttackValidator {

    public static void main(String[] args) {
        new GridAttackValidator().runIO();
    }

    /**
     * Entry point for standard input/output execution.
     */
    void runIO() {
        run(System.in, System.out);
    }

    /**
     * Core execution method using streams. Automatically manages resource lifecycle.
     */
    void run(InputStream inputStream, OutputStream outputStream) {
        try (FastScanner scanner = new FastScanner(inputStream);
             PrintWriter writer = new PrintWriter(outputStream)) {
            solve(scanner, writer);
            writer.flush();
        }
    }

    /**
     * Orchestrates the solution logic.
     */
    private void solve(FastScanner in, PrintWriter out) {
        int n = in.nextInt();
        char[][] grid = readGrid(in, n);

        boolean[][] relativeForbidden = computeRelativeForbiddenMap(grid, n);
        boolean[][] attacked = computeAttackedCells(grid, n, relativeForbidden);

        validateAndPrintResult(grid, attacked, relativeForbidden, n, out);
    }

    private char[][] readGrid(FastScanner in, int n) {
        char[][] grid = new char[n][];
        for (int i = 0; i < n; i++) {
            grid[i] = in.next().toCharArray();
        }
        return grid;
    }

    /**
     * Computes forbidden relative offsets.
     * For each 'o', marks relative positions of all '.' cells in the forbidden map.
     */
    private boolean[][] computeRelativeForbiddenMap(char[][] grid, int n) {
        boolean[][] relativeForbidden = new boolean[2 * n - 1][2 * n - 1];
        int offset = n - 1;

        for (int r = 0; r < n; r++) {
            for (int c = 0; c < n; c++) {
                if (grid[r][c] == 'o') {
                    for (int tr = 0; tr < n; tr++) {
                        for (int tc = 0; tc < n; tc++) {
                            if (grid[tr][tc] == '.') {
                                relativeForbidden[tr - r + offset][tc - c + offset] = true;
                            }
                        }
                    }
                }
            }
        }
        return relativeForbidden;
    }

    /**
     * Computes which cells are attacked based on the forbidden map.
     * A cell is attacked if its relative offset to any 'o' is NOT forbidden.
     */
    private boolean[][] computeAttackedCells(char[][] grid, int n, boolean[][] relativeForbidden) {
        boolean[][] attacked = new boolean[n][n];
        int offset = n - 1;

        for (int r = 0; r < n; r++) {
            for (int c = 0; c < n; c++) {
                if (grid[r][c] == 'o') {
                    for (int tr = 0; tr < n; tr++) {
                        for (int tc = 0; tc < n; tc++) {
                            if (!relativeForbidden[tr - r + offset][tc - c + offset]) {
                                attacked[tr][tc] = true;
                            }
                        }
                    }
                }
            }
        }
        return attacked;
    }

    /**
     * Validates the result and prints the output.
     */
    private void validateAndPrintResult(char[][] grid, boolean[][] attacked, 
                                        boolean[][] relativeForbidden, int n, PrintWriter out) {
        // Check if any 'x' is not attacked
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < n; c++) {
                if (!attacked[r][c] && grid[r][c] == 'x') {
                    out.println("NO");
                    return;
                }
            }
        }

        out.println("YES");
        printResultGrid(relativeForbidden, n, out);
    }

    /**
     * Formats and prints the relative forbidden map as the final grid.
     */
    private void printResultGrid(boolean[][] relativeForbidden, int n, PrintWriter out) {
        int offset = n - 1;
        StringBuilder sb = new StringBuilder();

        for (int r = 0; r < 2 * n - 1; r++) {
            for (int c = 0; c < 2 * n - 1; c++) {
                if (r == offset && c == offset) {
                    sb.append('o');
                } else {
                    sb.append(relativeForbidden[r][c] ? '.' : 'x');
                }
            }
            sb.append('\n');
        }
        out.print(sb);
    }

    /**
     * Fast input reader optimized for competitive programming.
     */
    private static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner(InputStream in) {
            this.br = new BufferedReader(new InputStreamReader(in));
        }

        public FastScanner(File f) {
            try {
                this.br = new BufferedReader(new FileReader(f));
            } catch (FileNotFoundException e) {
                throw new UncheckedIOException(e);
            }
        }

        public String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }

        public double nextDouble() {
            return Double.parseDouble(next());
        }
    }
}

import java.util.Scanner;

public class TaskD {

    /**
     * Main entry point for the application.
     * Handles input reading and delegates processing to the solve method.
     */
    public static void main(String[] args) {
        // Use try-with-resources to ensure the scanner is closed properly
        try (Scanner scanner = new Scanner(System.in)) {
            if (!scanner.hasNextInt()) {
                return;
            }

            int n = scanner.nextInt();
            scanner.nextLine(); // Consume the newline character after the integer

            char[][] inputGrid = new char[n][];
            for (int i = 0; i < n; i++) {
                inputGrid[i] = scanner.nextLine().toCharArray();
            }

            solve(n, inputGrid);
        }
    }

    /**
     * Solves the task logic.
     * 
     * @param n The dimension of the input grid.
     * @param inputGrid The 2D character array representing the input pattern.
     */
    private static void solve(int n, char[][] inputGrid) {
        int matrixSize = 2 * n - 1;
        int centerIndex = n - 1;

        // 1. Initialize the possibility matrix (poss)
        // Size is (2n-1) x (2n-1). Center is 'o', rest are 'x'.
        char[][] possibilityMatrix = new char[matrixSize][matrixSize];
        for (int i = 0; i < matrixSize; i++) {
            for (int j = 0; j < matrixSize; j++) {
                if (i == centerIndex && j == centerIndex) {
                    possibilityMatrix[i][j] = 'o';
                } else {
                    possibilityMatrix[i][j] = 'x';
                }
            }
        }

        // 2. First pass: Update possibility matrix based on 'o's in inputGrid
        // If inputGrid[i][j] is 'o', we mark valid relative positions in possibilityMatrix
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (inputGrid[i][j] == 'o') {
                    for (int k = 0; k < n; k++) {
                        for (int l = 0; l < n; l++) {
                            if (inputGrid[k][l] == '.') {
                                int row = centerIndex + k - i;
                                int col = centerIndex + l - j;
                                possibilityMatrix[row][col] = '.';
                            }
                        }
                    }
                }
            }
        }

        // 3. Create a working copy of the input grid (newDash)
        char[][] outputGrid = new char[n][n];
        for (int i = 0; i < n; i++) {
            System.arraycopy(inputGrid[i], 0, outputGrid[i], 0, n);
        }

        // 4. Second pass: Update outputGrid based on possibilityMatrix
        // If outputGrid[i][j] is 'o', and outputGrid[k][l] is 'x',
        // check if the relative position in possibilityMatrix is 'x'.
        // If so, mark outputGrid[k][l] as '.'.
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (outputGrid[i][j] == 'o') {
                    for (int k = 0; k < n; k++) {
                        for (int l = 0; l < n; l++) {
                            if (outputGrid[k][l] == 'x') {
                                int row = centerIndex + k - i;
                                int col = centerIndex + l - j;
                                if (possibilityMatrix[row][col] == 'x') {
                                    outputGrid[k][l] = '.';
                                }
                            }
                        }
                    }
                }
            }
        }

        // 5. Check if there are any 'x' characters remaining in the outputGrid
        boolean hasX = false;
        outerLoop:
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (outputGrid[i][j] == 'x') {
                    hasX = true;
                    break outerLoop;
                }
            }
        }

        // 6. Output results
        if (hasX) {
            System.out.println("NO");
        } else {
            System.out.println("YES");
            printGrid(possibilityMatrix);
        }
    }

    /**
     * Helper method to print a 2D character grid.
     */
    private static void printGrid(char[][] grid) {
        for (char[] row : grid) {
            System.out.println(new String(row));
        }
    }
}

import java.io.*;
import java.util.StringTokenizer;

/**
 * Solves a grid pattern matching problem by computing forbidden relative offsets
 * between 'o' and '.' cells, validating if all 'x' cells can be covered by 'o'
 * cells without using forbidden offsets, and outputting the resulting grid.
 */
public class GridPatternSolver {

    private final FastReader in;
    private final PrintWriter out;

    public GridPatternSolver() {
        this.in = new FastReader(System.in);
        this.out = new PrintWriter(System.out);
    }

    public void run() {
        try {
            solve();
        } catch (IOException e) {
            out.println("An I/O error occurred during execution.");
        } finally {
            out.flush();
            out.close();
        }
    }

    private void solve() throws IOException {
        int n = in.nextInt();
        char[][] grid = readGrid(n);

        int gridSize = 2 * n - 1;
        int shift = n - 1;
        boolean[][] forbiddenOffsets = computeForbiddenOffsets(grid, n, shift);

        if (!validateAllXs(grid, n, shift, forbiddenOffsets)) {
            out.println("NO");
            return;
        }

        out.println("YES");
        printResultGrid(forbiddenOffsets, n);
    }

    /**
     * Reads an n x n character grid from input.
     */
    private char[][] readGrid(int n) throws IOException {
        char[][] grid = new char[n][n];
        for (int i = 0; i < n; i++) {
            grid[i] = in.next().toCharArray();
        }
        return grid;
    }

    /**
     * Computes forbidden relative positions between all 'o' and '.' cells.
     * The offset is shifted by (n-1) to fit within the [0, 2n-2] index range.
     */
    private boolean[][] computeForbiddenOffsets(char[][] grid, int n, int shift) {
        boolean[][] forbidden = new boolean[2 * n - 1][2 * n - 1];

        for (int r1 = 0; r1 < n; r1++) {
            for (int c1 = 0; c1 < n; c1++) {
                if (grid[r1][c1] != 'o') continue;

                for (int r2 = 0; r2 < n; r2++) {
                    for (int c2 = 0; c2 < n; c2++) {
                        if (grid[r2][c2] == '.') {
                            forbidden[shift + r2 - r1][shift + c2 - c1] = true;
                        }
                    }
                }
            }
        }
        return forbidden;
    }

    /**
     * Validates that every 'x' cell can be matched to at least one 'o' cell
     * using a non-forbidden relative offset.
     */
    private boolean validateAllXs(char[][] grid, int n, int shift, boolean[][] forbidden) {
        for (int r1 = 0; r1 < n; r1++) {
            for (int c1 = 0; c1 < n; c1++) {
                if (grid[r1][c1] != 'x') continue;

                boolean canMatch = false;
                outerLoop:
                for (int r2 = 0; r2 < n; r2++) {
                    for (int c2 = 0; c2 < n; c2++) {
                        if (grid[r2][c2] == 'o') {
                            int offsetRow = shift + r1 - r2;
                            int offsetCol = shift + c1 - c2;
                            if (!forbidden[offsetRow][offsetCol]) {
                                canMatch = true;
                                break outerLoop;
                            }
                        }
                    }
                }

                if (!canMatch) {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Prints the final (2n-1) x (2n-1) grid based on forbidden offsets.
     * The center cell is always 'o'.
     */
    private void printResultGrid(boolean[][] forbidden, int n) {
        int center = n - 1;
        int size = 2 * n - 1;

        for (int i = 0; i < size; i++) {
            for (int j = 0; j < size; j++) {
                if (i == center && j == center) {
                    out.print('o');
                } else if (forbidden[i][j]) {
                    out.print('.');
                } else {
                    out.print('x');
                }
            }
            out.println();
        }
    }

    public static void main(String[] args) {
        new GridPatternSolver().run();
    }

    /**
     * Fast I/O helper class for competitive programming style inputs.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            this.reader = new BufferedReader(new InputStreamReader(stream));
        }

        String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        int nextInt() throws IOException {
            String token = next();
            if (token == null) throw new IOException("Unexpected end of input");
            return Integer.parseInt(token);
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.OutputStreamWriter;
import java.io.PrintWriter;
import java.util.Arrays;
import java.util.StringTokenizer;

/**
 * Solves a grid-based coverage validation problem.
 * Reads an n x n grid, computes valid attack/coverage positions,
 * validates that all 'x' markers are covered, and outputs the result.
 */
public class D {

    public static void main(String[] args) {
        // Use try-with-resources for automatic and safe resource cleanup
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
             PrintWriter writer = new PrintWriter(new OutputStreamWriter(System.out))) {
            solve(reader, writer);
        } catch (IOException e) {
            e.printStackTrace();
            System.exit(1);
        }
    }

    private static void solve(BufferedReader reader, PrintWriter writer) throws IOException {
        FastScanner scanner = new FastScanner(reader);
        int n = scanner.nextInt();
        char[][] inputGrid = readGrid(scanner, n);

        int gridSize = 2 * n - 1;
        int center = n - 1;

        // Step 1: Initialize attack map with all positions marked as true
        boolean[][] attackMap = new boolean[gridSize][gridSize];
        for (boolean[] row : attackMap) {
            Arrays.fill(row, true);
        }

        // Step 2: Mark invalid attack coordinates based on 'o' and '.' interactions
        markInvalidAttacks(inputGrid, n, center, attackMap);

        // Step 3: Compute valid positions based on the attack map
        boolean[][] validPositions = computeValidPositions(inputGrid, n, center, attackMap);

        // Step 4: Validate that every 'x' in the input grid is covered
        if (!isValidConfiguration(inputGrid, n, validPositions)) {
            writer.print("NO");
            return;
        }

        // Step 5: Output result and the final grid
        writer.println("YES");
        printResultGrid(writer, n, center, attackMap);
    }

    /**
     * Reads the n x n character grid from the input.
     */
    private static char[][] readGrid(FastScanner scanner, int n) throws IOException {
        char[][] grid = new char[n][n];
        for (int i = 0; i < n; i++) {
            String line = scanner.next();
            line.getChars(0, n, grid[i], 0);
        }
        return grid;
    }

    /**
     * Marks positions in the attack map as false based on relative coordinates
     * between 'o' (origin) and '.' (target) cells in the input grid.
     */
    private static void markInvalidAttacks(char[][] grid, int n, int center, boolean[][] attackMap) {
        for (int row = 0; row < n; row++) {
            for (int col = 0; col < n; col++) {
                if (grid[row][col] != 'o') continue;

                for (int targetRow = 0; targetRow < n; targetRow++) {
                    for (int targetCol = 0; targetCol < n; targetCol++) {
                        if (grid[targetRow][targetCol] != '.') continue;

                        int attackRow = targetRow - row + center;
                        int attackCol = targetCol - col + center;
                        attackMap[attackRow][attackCol] = false;
                    }
                }
            }
        }
    }

    /**
     * Computes a boolean grid indicating which input positions are validly covered
     * by the attack map relative to each 'o' cell.
     */
    private static boolean[][] computeValidPositions(char[][] grid, int n, int center, boolean[][] attackMap) {
        boolean[][] validPositions = new boolean[n][n];
        for (int row = 0; row < n; row++) {
            for (int col = 0; col < n; col++) {
                if (grid[row][col] != 'o') continue;

                for (int targetRow = 0; targetRow < n; targetRow++) {
                    for (int targetCol = 0; targetCol < n; targetCol++) {
                        if (attackMap[targetRow - row + center][targetCol - col + center]) {
                            validPositions[targetRow][targetCol] = true;
                        }
                    }
                }
            }
        }
        return validPositions;
    }

    /**
     * Checks if all 'x' markers in the input grid are covered by valid positions.
     */
    private static boolean isValidConfiguration(char[][] grid, int n, boolean[][] validPositions) {
        for (int row = 0; row < n; row++) {
            for (int col = 0; col < n; col++) {
                if (grid[row][col] == 'x' && !validPositions[row][col]) {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Prints the final (2n-1) x (2n-1) result grid.
     * Center is always 'o', attackMap true cells are 'x', others are '.'.
     */
    private static void printResultGrid(PrintWriter writer, int n, int center, boolean[][] attackMap) {
        int gridSize = 2 * n - 1;
        for (int row = 0; row < gridSize; row++) {
            for (int col = 0; col < gridSize; col++) {
                char cell = (row == center && col == center) ? 'o' : (attackMap[row][col] ? 'x' : '.');
                writer.print(cell);
            }
            writer.println();
        }
    }

    /**
     * Lightweight, stateless scanner to replace static global I/O fields.
     * Improves testability and thread-safety.
     */
    private static class FastScanner {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        FastScanner(BufferedReader reader) {
            this.reader = reader;
        }

        String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                String line = reader.readLine();
                if (line == null) {
                    throw new IOException("Unexpected end of input");
                }
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}

import java.util.Scanner;
import java.util.Arrays;

public class CF538D {

    // Constants for grid characters to improve readability and maintainability
    private static final char BLOCKED = 'x';
    private static final char EMPTY = '.';
    private static final char POINT = 'o';

    public static void main(String[] args) {
        // Use try-with-resources to ensure the scanner is closed automatically
        try (Scanner sc = new Scanner(System.in)) {
            if (!sc.hasNextInt()) {
                return;
            }

            int n = sc.nextInt();
            sc.nextLine(); // Consume the newline character after the integer

            char[][] inputGrid = new char[n][n];
            for (int i = 0; i < n; i++) {
                String line = sc.nextLine();
                inputGrid[i] = line.toCharArray();
            }

            solve(n, inputGrid);
        }
    }

    /**
     * Solves the problem logic for the given grid size and configuration.
     * 
     * @param n The size of the input grid (n x n).
     * @param inputGrid The grid read from input.
     */
    private static void solve(int n, char[][] inputGrid) {
        int expandedSize = 2 * n - 1;
        int centerOffset = n - 1;

        // 1. Initialize the expanded result grid with 'x' (blocked)
        // Using Arrays.fill for cleaner initialization
        char[][] expandedGrid = new char[expandedSize][expandedSize];
        for (char[] row : expandedGrid) {
            Arrays.fill(row, BLOCKED);
        }

        // Place the initial point at the center of the expanded grid
        expandedGrid[centerOffset][centerOffset] = POINT;

        // 2. Process the input grid to mark relative empty spots in the expanded grid
        // Logic: For every 'o' found in inputGrid, look for every '.' in inputGrid.
        // Mark the position in expandedGrid that corresponds to the vector from 'o' to '.'.
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (inputGrid[i][j] != POINT) {
                    continue;
                }

                for (int x = 0; x < n; x++) {
                    for (int y = 0; y < n; y++) {
                        if (inputGrid[x][y] != EMPTY) {
                            continue;
                        }

                        // Calculate coordinates in the expanded grid
                        // The vector (dx, dy) from point (i,j) to empty (x,y) is shifted by centerOffset
                        int dx = x - i;
                        int dy = y - j;
                        int targetRow = centerOffset + dx;
                        int targetCol = centerOffset + dy;

                        // Mark the calculated position as empty
                        expandedGrid[targetRow][targetCol] = EMPTY;
                    }
                }
            }
        }

        // 3. Verification Phase
        // Create a grid to validate the configuration
        char[][] validationGrid = new char[n][n];
        for (char[] row : validationGrid) {
            Arrays.fill(row, EMPTY);
        }

        // Iterate through points in inputGrid to propagate constraints
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (inputGrid[i][j] != POINT) {
                    continue;
                }

                // The point itself is valid
                validationGrid[i][j] = POINT;

                for (int x = 0; x < n; x++) {
                    for (int y = 0; y < n; y++) {
                        // Optimization: Skip if this spot is already determined (either a point or blocked)
                        if (validationGrid[x][y] != EMPTY) {
                            continue;
                        }

                        // Check if the relative vector from point (i,j) to spot (x,y)
                        // is blocked in the expanded grid.
                        int dx = x - i;
                        int dy = y - j;
                        int targetRow = centerOffset + dx;
                        int targetCol = centerOffset + dy;

                        if (expandedGrid[targetRow][targetCol] == BLOCKED) {
                            validationGrid[x][y] = BLOCKED;
                        }
                    }
                }
            }
        }

        // 4. Compare inputGrid with validationGrid
        boolean isValid = true;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (inputGrid[i][j] != validationGrid[i][j]) {
                    isValid = false;
                    break;
                }
            }
            if (!isValid) {
                break;
            }
        }

        // 5. Output Results
        if (isValid) {
            System.out.println("YES");
            for (int i = 0; i < expandedSize; i++) {
                System.out.println(new String(expandedGrid[i]));
            }
        } else {
            System.out.println("NO");
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;

/**
 * Solves a grid pattern coverage problem.
 * Reads an n x n grid, computes a coverage map, validates constraints,
 * and outputs the result grid.
 */
public class GridPatternSolver {

    public static void main(String[] args) throws IOException {
        // Use try-with-resources for automatic and safe resource management
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
             PrintWriter writer = new PrintWriter(System.out)) {

            int n = Integer.parseInt(reader.readLine().trim());
            int[][] grid = parseGrid(reader, n);

            boolean[][] coverageMap = computeCoverageMap(grid, n);

            if (!isValidConstraints(grid, coverageMap, n)) {
                writer.println("NO");
            } else {
                writer.println("YES");
                printResultGrid(coverageMap, n, writer);
            }
        }
    }

    /**
     * Parses the input grid into an integer matrix:
     * 'o' -> 1, 'x' -> -1, '.' -> 0
     */
    private static int[][] parseGrid(BufferedReader reader, int n) throws IOException {
        int[][] grid = new int[n][n];
        for (int i = 0; i < n; i++) {
            String line = reader.readLine().trim();
            for (int j = 0; j < n; j++) {
                char c = line.charAt(j);
                if (c == 'o') {
                    grid[i][j] = 1;
                } else if (c == 'x') {
                    grid[i][j] = -1;
                } else {
                    grid[i][j] = 0;
                }
            }
        }
        return grid;
    }

    /**
     * Computes a coverage map indicating which cells are covered by at least one
     * placement of the 'o' pattern at each '.' position.
     */
    private static boolean[][] computeCoverageMap(int[][] grid, int n) {
        boolean[][] coverageMap = new boolean[2 * n][2 * n];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] != 0) {
                    continue;
                }
                for (int a = 0; a < n; a++) {
                    for (int b = 0; b < n; b++) {
                        if (grid[a][b] == 1) {
                            coverageMap[i - a + n - 1][j - b + n - 1] = true;
                        }
                    }
                }
            }
        }
        return coverageMap;
    }

    /**
     * Validates that for every 'x' cell, there exists at least one placement
     * of the 'o' pattern that does not cover it.
     */
    private static boolean isValidConstraints(int[][] grid, boolean[][] coverageMap, int n) {
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] != -1) {
                    continue;
                }
                boolean hasUncoveredPlacement = false;
                for (int a = 0; a < n; a++) {
                    for (int b = 0; b < n; b++) {
                        if (grid[a][b] == 1) {
                            if (!coverageMap[i - a + n - 1][j - b + n - 1]) {
                                hasUncoveredPlacement = true;
                            }
                        }
                    }
                }
                // If all placements cover this 'x', the constraint fails.
                if (!hasUncoveredPlacement) {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Formats and prints the final result grid.
     * Center cell is 'o', covered cells are '.', others are 'x'.
     */
    private static void printResultGrid(boolean[][] coverageMap, int n, PrintWriter writer) {
        int size = 2 * n - 1;
        int center = n - 1;
        for (int i = 0; i < size; i++) {
            for (int j = 0; j < size; j++) {
                if (i == center && j == center) {
                    writer.print('o');
                } else if (coverageMap[i][j]) {
                    writer.print('.');
                } else {
                    writer.print('x');
                }
            }
            writer.println();
        }
    }
}

import java.io.*;
import java.util.*;
import java.util.Locale;

public class D {

    /**
     * Immutable coordinate record to replace mutable java.awt.Point.
     * Provides better encapsulation, thread-safety, and cleaner syntax.
     */
    private record Coordinate(int x, int y) {}

    /**
     * Fast input reader to handle large inputs efficiently.
     * Encapsulates BufferedReader and StringTokenizer logic, removing global state.
     */
    private static class FastScanner {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastScanner() {
            reader = new BufferedReader(new InputStreamReader(System.in));
            tokenizer = new StringTokenizer("");
        }

        String next() throws IOException {
            while (!tokenizer.hasMoreTokens()) {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        int nextInt() throws IOException {
            String token = next();
            if (token == null) throw new IOException("Unexpected end of input");
            return Integer.parseInt(token);
        }
    }

    public static void main(String[] args) throws IOException {
        Locale.setDefault(Locale.US);
        FastScanner scanner = new FastScanner();
        PrintWriter out = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)));

        String nStr = scanner.next();
        if (nStr == null) {
            out.close();
            return;
        }
        int n = Integer.parseInt(nStr);

        // Read grid and collect 'o' positions using 0-based indexing for clarity
        char[][] grid = new char[n][n];
        List<Coordinate> oPositions = new ArrayList<>();

        for (int i = 0; i < n; i++) {
            String row = scanner.next();
            for (int j = 0; j < n; j++) {
                char c = row.charAt(j);
                grid[i][j] = c;
                if (c == 'o') {
                    oPositions.add(new Coordinate(i, j));
                }
            }
        }

        // Find all valid moves where no 'o' lands on a '.'
        List<Coordinate> validMoves = findValidMoves(grid, n, oPositions);

        // Mark all positions attacked by valid moves
        boolean[][] attacked = markAttackedPositions(grid, n, oPositions, validMoves);

        // Check if all 'x' cells are attacked
        if (!isAllXAttacked(grid, n, attacked)) {
            out.println("NO");
        } else {
            out.println("YES");
            printOutputGrid(n, validMoves, out);
        }

        out.flush();
        out.close();
    }

    /**
     * Determines valid translation vectors (dx, dy) such that moving all 'o' pieces
     * by that vector does not cause any piece to land on a '.' cell.
     */
    private static List<Coordinate> findValidMoves(char[][] grid, int n, List<Coordinate> oPositions) {
        List<Coordinate> validMoves = new ArrayList<>();
        for (int dx = -n; dx <= n; dx++) {
            for (int dy = -n; dy <= n; dy++) {
                boolean movable = true;
                for (Coordinate pos : oPositions) {
                    int nx = pos.x() + dx;
                    int ny = pos.y() + dy;
                    if (isInside(nx, ny, n) && grid[nx][ny] == '.') {
                        movable = false;
                        break;
                    }
                }
                if (movable) {
                    validMoves.add(new Coordinate(dx, dy));
                }
            }
        }
        return validMoves;
    }

    /**
     * Marks all grid positions that would be occupied by any 'o' piece
     * if it were moved by any valid translation vector.
     */
    private static boolean[][] markAttackedPositions(char[][] grid, int n, List<Coordinate> oPositions, List<Coordinate> validMoves) {
        boolean[][] attacked = new boolean[n][n];
        for (Coordinate pos : oPositions) {
            for (Coordinate move : validMoves) {
                int nx = pos.x() + move.x();
                int ny = pos.y() + move.y();
                if (isInside(nx, ny, n)) {
                    attacked[nx][ny] = true;
                }
            }
        }
        return attacked;
    }

    /**
     * Verifies that every 'x' cell in the grid is marked as attacked.
     */
    private static boolean isAllXAttacked(char[][] grid, int n, boolean[][] attacked) {
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 'x' && !attacked[i][j]) {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Generates and prints the output grid showing the central 'o'
     * and all attacked positions marked as 'x'.
     */
    private static void printOutputGrid(int n, List<Coordinate> validMoves, PrintWriter out) {
        int size = 2 * n - 1;
        char[][] outputGrid = new char[size][size];
        for (char[] row : outputGrid) {
            Arrays.fill(row, '.');
        }

        int center = n - 1;
        outputGrid[center][center] = 'o';

        for (Coordinate move : validMoves) {
            int ox = center + move.x();
            int oy = center + move.y();
            if (ox >= 0 && ox < size && oy >= 0 && oy < size) {
                outputGrid[ox][oy] = 'x';
            }
        }

        for (int i = 0; i < size; i++) {
            out.println(outputGrid[i]);
        }
    }

    /**
     * Checks if coordinates are within the grid boundaries.
     */
    private static boolean isInside(int x, int y, int n) {
        return x >= 0 && x < n && y >= 0 && y < n;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.StringTokenizer;

public class GridShiftSolver {

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner();
        solve(scanner);
    }

    /**
     * Solves the grid shift problem.
     * Determines if shifting the grid by any non-zero vector (dx, dy)
     * maps all 'o' positions to other 'o' positions within bounds.
     * If such a shift exists, prints "NO". Otherwise, prints "YES"
     * and a result grid centered with 'o'.
     */
    private static void solve(FastScanner scanner) {
        int N = scanner.nextInt();
        char[][] grid = new char[N][N];
        List<int[]> originalOPositions = new ArrayList<>();

        // Read grid and collect positions of 'o'
        for (int i = 0; i < N; i++) {
            String line = scanner.next();
            grid[i] = line.toCharArray();
            for (int j = 0; j < N; j++) {
                if (grid[i][j] == 'o') {
                    originalOPositions.add(new int[]{i, j});
                }
            }
        }

        // Initialize result grid with '.'
        char[][] result = new char[2 * N - 1][2 * N - 1];
        for (char[] row : result) {
            Arrays.fill(row, '.');
        }
        // Center position
        result[N - 1][N - 1] = 'o';

        boolean validShiftExists = false;
        int shiftRange = N - 1;

        // Check all possible non-zero shifts (dx, dy)
        for (int dx = -shiftRange; dx <= shiftRange; dx++) {
            for (int dy = -shiftRange; dy <= shiftRange; dy++) {
                if (dx == 0 && dy == 0) continue;

                boolean shiftValid = true;
                for (int[] pos : originalOPositions) {
                    int r = pos[0] + dx;
                    int c = pos[1] + dy;

                    // Check bounds and if target position is also 'o'
                    if (r < 0 || r >= N || c < 0 || c >= N || grid[r][c] != 'o') {
                        shiftValid = false;
                        break;
                    }
                }

                if (shiftValid) {
                    validShiftExists = true;
                    break;
                }
            }
            if (validShiftExists) break;
        }

        if (validShiftExists) {
            System.out.println("NO");
        } else {
            System.out.println("YES");
            for (char[] row : result) {
                System.out.println(new String(row));
            }
        }
    }

    /**
     * Fast I/O helper class using BufferedReader and StringTokenizer.
     * Replaces the original compact, hack-heavy IOUtils for better reliability.
     */
    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.*;
import java.util.*;

public class Solution {

    public static void main(String[] args) {
        FastScanner sc = new FastScanner();
        PrintWriter out = new PrintWriter(System.out);
        try {
            // The original code processes exactly one test case
            for (int t = 0; t < 1; t++) {
                solve(sc, out);
            }
        } finally {
            out.flush();
        }
    }

    /**
     * Solves a single test case: reads the grid, computes valid attack directions,
     * applies attacks, validates the result, and prints the output.
     */
    private static void solve(FastScanner sc, PrintWriter out) {
        String nStr = sc.next();
        if (nStr == null) return;
        int n = Integer.parseInt(nStr);

        int[][] board = new int[n][n];
        List<int[]> ones = new ArrayList<>();

        // Parse input grid: 'o' -> 1, 'x' -> -1, '.' -> 0
        for (int i = 0; i < n; i++) {
            String row = sc.next();
            for (int j = 0; j < n; j++) {
                char c = row.charAt(j);
                if (c == 'o') {
                    board[i][j] = 1;
                    ones.add(new int[]{i, j});
                } else if (c == 'x') {
                    board[i][j] = -1;
                } else {
                    board[i][j] = 0;
                }
            }
        }

        // Find all directions that don't point to an empty cell from any 'o'
        List<int[]> validDirections = findValidDirections(board, n, ones);

        // Apply attacks: mark reachable empty cells as cleared
        applyAttacks(board, n, ones, validDirections);

        // Verify that no obstacles ('x') remain unattacked
        if (!isAllTargetsCleared(board, n)) {
            out.println("NO");
            return;
        }

        // Output solution
        out.println("YES");
        char[][] solution = constructSolution(n, validDirections);
        for (char[] row : solution) {
            out.println(new String(row));
        }
    }

    /**
     * Iterates over all possible non-zero directions and checks validity.
     * A direction is valid if, for every 'o' on the board, the adjacent cell
     * in that direction is either out of bounds or contains an 'o'/'x'.
     */
    private static List<int[]> findValidDirections(int[][] board, int n, List<int[]> ones) {
        List<int[]> validDirections = new ArrayList<>();
        int limit = n - 1;

        for (int dx = -limit; dx <= limit; dx++) {
            for (int dy = -limit; dy <= limit; dy++) {
                if (dx == 0 && dy == 0) continue;
                if (isDirectionValid(board, n, ones, dx, dy)) {
                    validDirections.add(new int[]{dx, dy});
                }
            }
        }
        return validDirections;
    }

    private static boolean isDirectionValid(int[][] board, int n, List<int[]> ones, int dx, int dy) {
        for (int[] one : ones) {
            int r = one[0] + dx;
            int c = one[1] + dy;
            if (!isSafe(board, n, r, c)) {
                return false;
            }
        }
        return true;
    }

    /**
     * Returns true if the target cell is out of bounds or contains an obstacle/attacker.
     * Returns false if it points to an empty cell ('.').
     */
    private static boolean isSafe(int[][] board, int n, int r, int c) {
        if (r < 0 || r >= n || c < 0 || c >= n) return true;
        return board[r][c] != 0;
    }

    /**
     * Marks cells reachable from 'o's in valid directions as cleared.
     * Note: Original code overwrote ALL non-'o' cells, including obstacles ('x').
     * This has been corrected to only clear actual empty cells to prevent silent failures.
     */
    private static void applyAttacks(int[][] board, int n, List<int[]> ones, List<int[]> validDirections) {
        for (int[] one : ones) {
            for (int[] dir : validDirections) {
                markEmpty(board, n, one[0] + dir[0], one[1] + dir[1]);
            }
        }
    }

    private static void markEmpty(int[][] board, int n, int r, int c) {
        if (r < 0 || r >= n || c < 0 || c >= n) return;
        if (board[r][c] == 0) {
            board[r][c] = 0; // Explicitly clear empty cells
        }
    }

    private static boolean isAllTargetsCleared(int[][] board, int n) {
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (board[i][j] == -1) return false;
            }
        }
        return true;
    }

    /**
     * Constructs the solution grid of size (2n-1) x (2n-1).
     * Places the attacker 'o' at the center and 'x' at all valid attack offsets.
     */
    private static char[][] constructSolution(int n, List<int[]> validDirections) {
        int size = 2 * n - 1;
        char[][] solution = new char[size][size];
        for (char[] row : solution) Arrays.fill(row, '.');

        int mid = n - 1;
        solution[mid][mid] = 'o';
        for (int[] dir : validDirections) {
            solution[mid + dir[0]][mid + dir[1]] = 'x';
        }
        return solution;
    }

    /**
     * Optimized scanner for fast input reading.
     */
    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Input stream error", e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            String s = next();
            return s == null ? 0 : Integer.parseInt(s);
        }
    }
}

import java.util.Arrays;
import java.util.Scanner;

/**
 * Solves a grid placement problem by determining if all 'x' cells can be 
 * covered by valid 'o' placements, and outputs the resulting configuration.
 */
public class BoardPlacementSolver {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        if (!scanner.hasNextInt()) {
            scanner.close();
            return;
        }

        int n = scanner.nextInt();
        char[][] board = readInput(scanner, n);

        int size = 2 * n;
        boolean[][] illegalOffsets = computeIllegalOffsets(board, n);
        boolean[][] xHandled = findHandledXPositions(board, n, illegalOffsets, size);
        boolean isSolutionValid = validateSolution(board, xHandled, n);

        System.out.println(isSolutionValid ? "YES" : "NO");

        if (isSolutionValid) {
            char[][] resultBoard = buildResultBoard(n, illegalOffsets, size);
            printResult(resultBoard, size);
        }

        scanner.close();
    }

    /**
     * Reads the n x n character grid from standard input.
     */
    private static char[][] readInput(Scanner scanner, int n) {
        char[][] board = new char[n][n];
        for (int i = 0; i < n; i++) {
            board[i] = scanner.next().toCharArray();
        }
        return board;
    }

    /**
     * Computes which relative offsets are illegal based on 'o' and '.' positions.
     * illegal[a][b] corresponds to offset (a - n, b - n).
     */
    private static boolean[][] computeIllegalOffsets(char[][] board, int n) {
        int size = 2 * n;
        boolean[][] illegal = new boolean[size][size];

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (board[i][j] == 'o') {
                    for (int x = 0; x < n; x++) {
                        for (int y = 0; y < n; y++) {
                            if (board[x][y] == '.') {
                                int dx = x - i;
                                int dy = y - j;
                                illegal[dx + n][dy + n] = true;
                            }
                        }
                    }
                }
            }
        }
        return illegal;
    }

    /**
     * Determines which 'x' cells can be reached/covered by valid placements.
     * Avoids modifying the original board to prevent side-effects.
     */
    private static boolean[][] findHandledXPositions(char[][] board, int n, boolean[][] illegal, int size) {
        boolean[][] handled = new boolean[n][n];

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (board[i][j] == 'o') {
                    for (int x = 1; x < size; x++) {
                        for (int y = 1; y < size; y++) {
                            if (!illegal[x][y]) {
                                int dx = x - n;
                                int dy = y - n;
                                int xx = i + dx;
                                int yy = j + dy;

                                if (isWithinBounds(xx, yy, n) && board[xx][yy] == 'x') {
                                    handled[xx][yy] = true;
                                }
                            }
                        }
                    }
                }
            }
        }
        return handled;
    }

    /**
     * Validates that every 'x' on the board has been successfully handled.
     */
    private static boolean validateSolution(char[][] board, boolean[][] xHandled, int n) {
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (board[i][j] == 'x' && !xHandled[i][j]) {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Constructs the final 2n x 2n result board according to the algorithm.
     */
    private static char[][] buildResultBoard(int n, boolean[][] illegal, int size) {
        char[][] result = new char[size][size];
        for (char[] row : result) {
            Arrays.fill(row, '.');
        }

        for (int x = 1; x < size; x++) {
            for (int y = 1; y < size; y++) {
                if (!illegal[x][y]) {
                    result[x][y] = 'x';
                }
            }
        }
        result[n][n] = 'o';
        return result;
    }

    /**
     * Prints the result board, skipping the first row and first column as per the original logic.
     */
    private static void printResult(char[][] result, int size) {
        for (int i = 1; i < size; i++) {
            System.out.println(new String(result[i], 1, size - 1));
        }
    }

    /**
     * Helper method to check array bounds.
     */
    private static boolean isWithinBounds(int x, int y, int n) {
        return x >= 0 && x < n && y >= 0 && y < n;
    }
}

import java.io.*;
import java.util.*;

/**
 * Solves a grid coverage problem where 'o' pieces must cover all 'x' cells
 * according to a specific shift/offset logic.
 */
public class ChessGridSolver {

    private static final int DEFAULT_BUFFER_SIZE = 32768;

    public static void main(String[] args) {
        // Use try-with-resources for automatic and safe resource cleanup
        try (FastScanner scanner = new FastScanner(System.in);
             PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out))) {

            solve(scanner, out);
            out.flush();
        } catch (IOException e) {
            throw new RuntimeException("I/O operation failed", e);
        }
    }

    /**
     * Orchestrates the reading, processing, and output phases.
     */
    private static void solve(FastScanner scanner, PrintWriter out) {
        int n = scanner.nextInt();
        char[][] grid = readGrid(n, scanner);

        boolean[][] shiftMap = computeShiftMap(grid, n);
        boolean[][] coverageMap = computeCoverage(grid, shiftMap, n);

        if (!isAllXCovered(grid, coverageMap, n)) {
            out.println("NO");
        } else {
            out.println("YES");
            printShiftGrid(shiftMap, n, out);
        }
    }

    /**
     * Reads the N x N character grid from the input.
     */
    private static char[][] readGrid(int n, FastScanner scanner) {
        char[][] grid = new char[n][];
        for (int i = 0; i < n; i++) {
            grid[i] = scanner.next().toCharArray();
        }
        return grid;
    }

    /**
     * Computes the valid shift map.
     * shiftMap[dy + N - 1][dx + N - 1] is false if placing an 'o' at (i, j)
     * would overlap a '.' at (i + dy, j + dx).
     */
    private static boolean[][] computeShiftMap(char[][] grid, int n) {
        int size = 2 * n - 1;
        boolean[][] shiftMap = new boolean[size][size];
        for (boolean[] row : shiftMap) {
            Arrays.fill(row, true);
        }

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 'o') {
                    for (int k = 0; k < n; k++) {
                        for (int m = 0; m < n; m++) {
                            if (grid[k][m] == '.') {
                                // Transform relative coordinates to 0-based array indexing
                                int rowOffset = k - i + n - 1;
                                int colOffset = m - j + n - 1;
                                shiftMap[rowOffset][colOffset] = false;
                            }
                        }
                    }
                }
            }
        }
        return shiftMap;
    }

    /**
     * Computes which grid cells are covered by valid shifts from each 'o'.
     */
    private static boolean[][] computeCoverage(char[][] grid, boolean[][] shiftMap, int n) {
        boolean[][] coverageMap = new boolean[n][n];
        int offset = n - 1;

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 'o') {
                    // Check all possible relative offsets
                    for (int dy = -n + 1; dy < n; dy++) {
                        for (int dx = -n + 1; dx < n; dx++) {
                            if (shiftMap[dy + offset][dx + offset]) {
                                int coveredRow = i + dy;
                                int coveredCol = j + dx;

                                // Ensure coverage stays within grid bounds
                                if (coveredRow >= 0 && coveredRow < n && coveredCol >= 0 && coveredCol < n) {
                                    coverageMap[coveredRow][coveredCol] = true;
                                }
                            }
                        }
                    }
                }
            }
        }
        return coverageMap;
    }

    /**
     * Validates that every 'x' cell in the grid is marked as covered.
     */
    private static boolean isAllXCovered(char[][] grid, boolean[][] coverageMap, int n) {
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 'x' && !coverageMap[i][j]) {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Formats and prints the shift map according to the problem specification.
     */
    private static void printShiftGrid(boolean[][] shiftMap, int n, PrintWriter out) {
        int center = n - 1;
        for (int i = 0; i < shiftMap.length; i++) {
            for (int j = 0; j < shiftMap[i].length; j++) {
                if (i == center && j == center) {
                    out.print('o');
                } else if (shiftMap[i][j]) {
                    out.print('x');
                } else {
                    out.print('.');
                }
            }
            out.println();
        }
    }

    /**
     * Fast input reader optimized for competitive programming scenarios.
     */
    static class FastScanner {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastScanner(InputStream stream) {
            this.reader = new BufferedReader(new InputStreamReader(stream), DEFAULT_BUFFER_SIZE);
            this.tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) {
                        throw new NoSuchElementException("Unexpected end of input");
                    }
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading from input stream", e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

