/**
 * Encapsulates the grid transformation and validation logic.
 * Extracted from the original monolithic solve() method to improve cohesion and testability.
 */
class GridSolver {

    /**
     * Orchestrates the reading, transformation, validation, and output phases.
     */
    public void solve(BufferedReader reader, PrintWriter out) throws IOException {
        String line = reader.readLine();
        if (line == null || line.trim().isEmpty()) {
            return;
        }

        int n = Integer.parseInt(line.trim());
        char[][] inputGrid = readInputGrid(reader, n);

        int resultSize = 2 * n - 1;
        char[][] resultGrid = initializeResultGrid(resultSize, n);

        mapEmptySpaces(inputGrid, resultGrid, n);

        if (!validateXPositions(inputGrid, resultGrid, n)) {
            out.println("NO");
            return;
        }

        out.println("YES");
        printResultGrid(resultGrid, out);
    }

    /**
     * Reads the n x n input grid from the buffer.
     */
    private char[][] readInputGrid(BufferedReader reader, int n) throws IOException {
        char[][] grid = new char[n][n];
        for (int i = 0; i < n; i++) {
            String row = reader.readLine();
            if (row != null) {
                grid[i] = row.trim().toCharArray();
            } else {
                // Fallback for unexpected EOF; maintains array dimensions
                grid[i] = new char[n];
            }
        }
        return grid;
    }

    /**
     * Initializes the result grid with default 'x' characters and places the center 'o'.
     * Replaces the original post-initialization null-to-'x' replacement pass.
     */
    private char[][] initializeResultGrid(int size, int n) {
        char[][] grid = new char[size][size];
        for (char[] row : grid) {
            Arrays.fill(row, 'x');
        }
        grid[n - 1][n - 1] = 'o';
        return grid;
    }

    /**
     * Maps '.' positions from the input grid to the result grid based on 
     * the relative coordinates of all 'o' characters.
     */
    private void mapEmptySpaces(char[][] inputGrid, char[][] resultGrid, int n) {
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (inputGrid[i][j] == '.') {
                    for (int k = 0; k < n; k++) {
                        for (int l = 0; l < n; l++) {
                            if (inputGrid[k][l] == 'o') {
                                int rRow = n + i - k - 1;
                                int rCol = n + j - l - 1;
                                resultGrid[rRow][rCol] = '.';
                            }
                        }
                    }
                }
            }
        }
    }

    /**
     * Validates that every 'x' in the input grid has at least one 'o' 
     * that maps to a non-'.' position in the result grid.
     */
    private boolean validateXPositions(char[][] inputGrid, char[][] resultGrid, int n) {
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (inputGrid[i][j] == 'x') {
                    if (!hasValidMapping(i, j, inputGrid, resultGrid, n)) {
                        return false;
                    }
                }
            }
        }
        return true;
    }

    /**
     * Checks if a given (i, j) position has at least one valid transformation
     * that lands on a non-'.' cell in the result grid.
     */
    private boolean hasValidMapping(int i, int j, char[][] inputGrid, char[][] resultGrid, int n) {
        for (int k = 0; k < n; k++) {
            for (int l = 0; l < n; l++) {
                if (inputGrid[k][l] == 'o') {
                    int rRow = n + i - k - 1;
                    int rCol = n + j - l - 1;
                    if (resultGrid[rRow][rCol] != '.') {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Outputs the final result grid row by row.
     */
    private void printResultGrid(char[][] grid, PrintWriter out) {
        for (char[] row : grid) {
            out.println(new String(row));
        }
    }
}

