/**
 * Entry point for the board solving application.
 * Sets up fast I/O and delegates execution to the solver.
 */
public class Main {
    public static void main(String[] args) {
        FastScanner in = new FastScanner(System.in);
        FastPrinter out = new FastPrinter(System.out);
        new BoardSolver().solve(in, out);
        out.close();
    }
}

/**
 * Core business logic for solving the board puzzle.
 * Extracted from the original TaskD for better separation of concerns.
 */
class BoardSolver {
    public void solve(FastScanner in, FastPrinter out) {
        int boardSize = in.nextInt();
        char[][] board = BoardUtils.readBoard(in, boardSize);

        List<Coordinate> piecePositions = new ArrayList<>();
        for (int r = 0; r < boardSize; r++) {
            for (int c = 0; c < boardSize; c++) {
                if (board[r][c] == 'o') {
                    piecePositions.add(new Coordinate(r, c));
                }
            }
        }

        List<Coordinate> validMoves = findValidMoves(board, boardSize, piecePositions);

        if (!canReachAllX(board, boardSize, piecePositions, validMoves)) {
            out.println("NO");
            return;
        }

        char[][] resultBoard = constructResultBoard(boardSize, validMoves);
        out.println("YES");
        for (char[] row : resultBoard) {
            out.println(row);
        }
    }

    /**
     * Identifies all translation vectors (dx, dy) that shift every 'o' piece
     * without landing on any empty '.' cell.
     */
    private List<Coordinate> findValidMoves(char[][] board, int size, List<Coordinate> pieces) {
        List<Coordinate> validMoves = new ArrayList<>();
        int limit = size - 1;
        for (int dx = -limit; dx <= limit; dx++) {
            for (int dy = -limit; dy <= limit; dy++) {
                if (dx == 0 && dy == 0) continue;

                boolean isValid = true;
                for (Coordinate piece : pieces) {
                    int newRow = piece.r + dx;
                    int newCol = piece.c + dy;
                    if (BoardUtils.isValidPosition(newRow, newCol, size) && board[newRow][newCol] == '.') {
                        isValid = false;
                        break;
                    }
                }
                if (isValid) {
                    validMoves.add(new Coordinate(dx, dy));
                }
            }
        }
        return validMoves;
    }

    /**
     * Verifies that every 'x' piece can be covered by shifting an 'o' piece
     * using one of the previously identified valid moves.
     */
    private boolean canReachAllX(char[][] board, int size, List<Coordinate> pieces, List<Coordinate> validMoves) {
        for (int r = 0; r < size; r++) {
            for (int c = 0; c < size; c++) {
                if (board[r][c] == 'x') {
                    boolean canReach = false;
                    for (Coordinate move : validMoves) {
                        int sourceR = r - move.r;
                        int sourceC = c - move.c;
                        if (BoardUtils.isValidPosition(sourceR, sourceC, size) && board[sourceR][sourceC] == 'o') {
                            canReach = true;
                            break;
                        }
                    }
                    if (!canReach) return false;
                }
            }
        }
        return true;
    }

    /**
     * Constructs the output board representation.
     * Centers the 'o' pieces and marks valid move vectors with 'x'.
     */
    private char[][] constructResultBoard(int size, List<Coordinate> validMoves) {
        int outputSize = 2 * size - 1;
        char[][] result = new char[outputSize][outputSize];
        BoardUtils.fill(result, '.');

        // Place the reference 'o' at the center
        result[size - 1][size - 1] = 'o';

        // Mark valid translation vectors with 'x'
        for (Coordinate move : validMoves) {
            result[size + move.r - 1][size + move.c - 1] = 'x';
        }
        return result;
    }
}

/**
 * Fast I/O utility for reading integers and characters.
 * Optimized for competitive programming scenarios.
 */
class FastScanner {
    private final InputStream stream;
    private final byte[] buffer = new byte[1024];
    private int bufferPtr, bytesRead;

    public FastScanner(InputStream stream) {
        this.stream = stream;
    }

    private int read() {
        if (bytesRead == -1) throw new InputMismatchException();
        if (bufferPtr >= bytesRead) {
            bufferPtr = 0;
            try {
                bytesRead = stream.read(buffer);
            } catch (IOException e) {
                throw new InputMismatchException();
            }
            if (bytesRead <= 0) return -1;
        }
        return buffer[bufferPtr++];
    }

    public int nextInt() {
        int c = read();
        while (isWhitespace(c)) c = read();
        int sign = 1;
        if (c == '-') { sign = -1; c = read(); }
        int res = 0;
        do {
            if (c < '0' || c > '9') throw new InputMismatchException();
            res = res * 10 + (c - '0');
            c = read();
        } while (!isWhitespace(c));
        return res * sign;
    }

    public char nextChar() {
        int c = read();
        while (isWhitespace(c)) c = read();
        return (char) c;
    }

    private boolean isWhitespace(int c) {
        return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
    }
}

/**
 * Fast I/O utility for printing output.
 * Wraps PrintWriter with BufferedWriter for performance.
 */
class FastPrinter {
    private final PrintWriter writer;

    public FastPrinter(OutputStream outputStream) {
        writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(outputStream)));
    }

    public void println(Object... objects) {
        for (int i = 0; i < objects.length; i++) {
            if (i > 0) writer.print(' ');
            writer.print(objects[i]);
        }
        writer.println();
    }

    public void println(char[] array) {
        writer.println(array);
    }

    public void close() {
        writer.flush();
        writer.close();
    }
}

/**
 * Utility class for board manipulation and validation.
 */
class BoardUtils {
    public static char[][] readBoard(FastScanner in, int size) {
        char[][] board = new char[size][size];
        for (int i = 0; i < size; i++) {
            for (int j = 0; j < size; j++) {
                board[i][j] = in.nextChar();
            }
        }
        return board;
    }

    public static boolean isValidPosition(int row, int col, int size) {
        return row >= 0 && row < size && col >= 0 && col < size;
    }

    public static void fill(char[][] board, char value) {
        for (char[] row : board) Arrays.fill(row, value);
    }
}

/**
 * Immutable coordinate/point representation.
 * Replaces the original IntPair with a more descriptive name and cleaner implementation.
 */
class Coordinate {
    public final int r, c;

    public Coordinate(int r, int c) {
        this.r = r;
        this.c = c;
    }

    @Override
    public String toString() {
        return "(" + r + "," + c + ")";
    }

    @Override
    public boolean equals(Object o) {
        if (this == o) return true;
        if (!(o instanceof Coordinate)) return false;
        Coordinate that = (Coordinate) o;
        return r == that.r && c == that.c;
    }

    @Override
    public int hashCode() {
        int result = r;
        result = 31 * result + c;
        return result;
    }
}

import java.io.*;
import java.util.*;

/**
 * Solves a grid movement/tiling problem by determining valid translation vectors
 * for a given pattern and verifying coverage.
 */
public class GridMovementSolver {

    public static void main(String[] args) throws IOException {
        // Use try-with-resources to guarantee proper cleanup of I/O streams
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
             PrintWriter writer = new PrintWriter(new OutputStreamWriter(System.out))) {

            int gridSize = Integer.parseInt(reader.readLine());
            char[][] grid = readGrid(reader, gridSize);

            boolean[][] validMoves = new boolean[gridSize][gridSize];
            char[][] resultGrid = new char[2 * gridSize - 1][2 * gridSize - 1];
            initializeResultGrid(resultGrid, gridSize);

            // Iterate over all possible translation vectors (deltaRow, deltaCol)
            for (int deltaRow = -gridSize + 1; deltaRow < gridSize; deltaRow++) {
                for (int deltaCol = -gridSize + 1; deltaCol < gridSize; deltaCol++) {
                    // Skip the zero translation vector
                    if (deltaRow == 0 && deltaCol == 0) continue;

                    if (isValidMove(grid, deltaRow, deltaCol, gridSize)) {
                        applyMove(grid, deltaRow, deltaCol, gridSize, validMoves);
                        resultGrid[gridSize - 1 + deltaRow][gridSize - 1 + deltaCol] = 'x';
                    }
                }
            }

            boolean canComplete = checkAllXCovered(grid, validMoves, gridSize);

            if (!canComplete) {
                writer.println("NO");
            } else {
                writer.println("YES");
                printGrid(writer, resultGrid);
            }
            writer.flush();
        }
    }

    /**
     * Reads an n x n character grid from the input stream.
     */
    private static char[][] readGrid(BufferedReader reader, int size) throws IOException {
        char[][] grid = new char[size][size];
        for (int i = 0; i < size; i++) {
            grid[i] = reader.readLine().toCharArray();
        }
        return grid;
    }

    /**
     * Initializes the result grid with '.' and places the center marker 'o'.
     */
    private static void initializeResultGrid(char[][] grid, int gridSize) {
        for (char[] row : grid) {
            Arrays.fill(row, '.');
        }
        grid[gridSize - 1][gridSize - 1] = 'o';
    }

    /**
     * Checks if translating the grid by (deltaRow, deltaCol) would cause any 'o'
     * to overlap with an empty space '.'.
     */
    private static boolean isValidMove(char[][] grid, int deltaRow, int deltaCol, int size) {
        for (int i = 0; i < size; i++) {
            int newRow = i + deltaRow;
            if (newRow < 0 || newRow >= size) continue;

            for (int j = 0; j < size; j++) {
                int newCol = j + deltaCol;
                if (newCol < 0 || newCol >= size) continue;

                if (grid[i][j] == 'o' && grid[newRow][newCol] == '.') {
                    return false; // Overlaps with empty space
                }
            }
        }
        return true;
    }

    /**
     * Marks all translated positions in validMoves if the move is valid.
     */
    private static void applyMove(char[][] grid, int deltaRow, int deltaCol, int size, boolean[][] validMoves) {
        for (int i = 0; i < size; i++) {
            int newRow = i + deltaRow;
            if (newRow < 0 || newRow >= size) continue;

            for (int j = 0; j < size; j++) {
                int newCol = j + deltaCol;
                if (newCol < 0 || newCol >= size) continue;

                if (grid[i][j] == 'o') {
                    validMoves[newRow][newCol] = true;
                }
            }
        }
    }

    /**
     * Verifies that every 'x' in the original grid has a corresponding valid move.
     */
    private static boolean checkAllXCovered(char[][] grid, boolean[][] validMoves, int size) {
        for (int i = 0; i < size; i++) {
            for (int j = 0; j < size; j++) {
                if (grid[i][j] == 'x' && !validMoves[i][j]) {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Prints the result grid to the output writer.
     */
    private static void printGrid(PrintWriter writer, char[][] grid) {
        for (char[] row : grid) {
            writer.println(new String(row));
        }
    }
}

import java.util.Scanner;

/**
 * Analyzes a grid to determine if obstacles are covered based on piece movements.
 * This class refactors the original logic into modular, readable components.
 */
public class GridAttackValidator {

    // Constants to represent grid states for better readability
    private static final char EMPTY = '.';
    private static final char PIECE = 'o';
    private static final char OBSTACLE = 'x';
    private static final char UNREACHABLE = 'x'; // Represents 0 in mask (unreachable relative position)

    public static void main(String[] args) {
        // Use try-with-resources to ensure Scanner is properly closed
        try (Scanner scanner = new Scanner(System.in)) {
            if (!scanner.hasNextInt()) {
                return;
            }

            int gridSize = scanner.nextInt();
            scanner.nextLine(); // Consume the newline character after the integer

            char[][] grid = readGrid(scanner, gridSize);
            char[][] coverageMap = calculateCoverageMap(grid, gridSize);

            if (validateObstacles(grid, coverageMap, gridSize)) {
                System.out.println("YES");
                printGrid(coverageMap);
            } else {
                System.out.println("NO");
            }
        }
    }

    /**
     * Reads the grid configuration from the input.
     */
    private static char[][] readGrid(Scanner scanner, int n) {
        char[][] board = new char[n][];
        for (int i = 0; i < n; i++) {
            board[i] = scanner.nextLine().toCharArray();
        }
        return board;
    }

    /**
     * Calculates the coverage map (mask) representing relative reachable positions.
     */
    private static char[][] calculateCoverageMap(char[][] board, int n) {
        int maskSize = 2 * n - 1;
        char[][] mask = new char[maskSize][maskSize];

        // Center of the mask corresponds to the origin relative to a piece
        int center = n - 1;
        mask[center][center] = PIECE;

        // Determine reachable relative positions
        // If a piece is at (pieceX, pieceY) and there is an empty spot at (freeX, freeY),
        // the relative position (freeX - pieceX, freeY - pieceY) is marked as reachable (EMPTY).
        for (int freeX = 0; freeX < n; freeX++) {
            for (int freeY = 0; freeY < n; freeY++) {
                if (board[freeX][freeY] == EMPTY) {
                    for (int pieceX = 0; pieceX < n; pieceX++) {
                        for (int pieceY = 0; pieceY < n; pieceY++) {
                            if (board[pieceX][pieceY] == PIECE) {
                                int maskX = center + (freeX - pieceX);
                                int maskY = center + (freeY - pieceY);
                                mask[maskX][maskY] = EMPTY;
                            }
                        }
                    }
                }
            }
        }

        // Fill unreachable positions with 'x' (UNREACHABLE)
        for (int x = 0; x < maskSize; x++) {
            for (int y = 0; y < maskSize; y++) {
                if (mask[x][y] == 0) { // Default char value is 0
                    mask[x][y] = UNREACHABLE;
                }
            }
        }

        return mask;
    }

    /**
     * Validates if all obstacles on the grid are covered/hit according to the rules.
     */
    private static boolean validateObstacles(char[][] board, char[][] mask, int n) {
        int center = n - 1;

        for (int attackX = 0; attackX < n; attackX++) {
            for (int attackY = 0; attackY < n; attackY++) {
                if (board[attackX][attackY] == OBSTACLE) {
                    boolean canHit = false;

                    // Check if any piece can "hit" this obstacle.
                    // Logic: An obstacle is hit if, relative to a piece, its position 
                    // corresponds to an UNREACHABLE spot in the mask.
                    for (int pieceX = 0; pieceX < n; pieceX++) {
                        for (int pieceY = 0; pieceY < n; pieceY++) {
                            if (board[pieceX][pieceY] == PIECE) {
                                int maskX = center + (attackX - pieceX);
                                int maskY = center + (attackY - pieceY);

                                if (mask[maskX][maskY] == UNREACHABLE) {
                                    canHit = true;
                                    break;
                                }
                            }
                        }
                        if (canHit) break;
                    }

                    if (!canHit) {
                        return false;
                    }
                }
            }
        }
        return true;
    }

    /**
     * Prints the grid to the console.
     */
    private static void printGrid(char[][] grid) {
        for (char[] row : grid) {
            System.out.println(row);
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.Arrays;
import java.util.StringTokenizer;

public class Main {
    private final BufferedReader in;
    private final PrintWriter out;
    private StringTokenizer tokenizer;

    public Main() {
        this.in = new BufferedReader(new InputStreamReader(System.in));
        this.out = new PrintWriter(System.out);
    }

    public static void main(String[] args) {
        Main solver = new Main();
        try {
            solver.solve();
        } catch (IOException e) {
            System.err.println("IO Error: " + e.getMessage());
        } finally {
            solver.close();
        }
    }

    /**
     * Orchestrates the core problem-solving logic.
     */
    public void solve() throws IOException {
        int n = readInt();
        char[][] inputGrid = readGrid(n);

        // Initialize result grid with 'x'
        char[][] resultGrid = new char[2 * n - 1][2 * n - 1];
        for (char[] row : resultGrid) {
            Arrays.fill(row, 'x');
        }
        resultGrid[n - 1][n - 1] = 'o';

        // Mark positions covered by 'o' cells in the input grid
        markCoveredPositions(inputGrid, resultGrid, n);

        // Validate if all 'x' cells in the input grid are properly covered
        boolean isValid = isCoverageValid(inputGrid, resultGrid, n);

        if (isValid) {
            out.println("YES");
            for (char[] row : resultGrid) {
                out.println(new String(row));
            }
        } else {
            out.println("NO");
        }
    }

    private void markCoveredPositions(char[][] inputGrid, char[][] resultGrid, int n) {
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (inputGrid[i][j] == 'o') {
                    for (int ii = 0; ii < n; ii++) {
                        for (int jj = 0; jj < n; jj++) {
                            if (inputGrid[ii][jj] == '.') {
                                int dx = ii - i;
                                int dy = jj - j;
                                resultGrid[n - 1 + dx][n - 1 + dy] = '.';
                            }
                        }
                    }
                }
            }
        }
    }

    private boolean isCoverageValid(char[][] inputGrid, char[][] resultGrid, int n) {
        for (int ii = 0; ii < n; ii++) {
            for (int jj = 0; jj < n; jj++) {
                if (inputGrid[ii][jj] == 'x') {
                    boolean isCovered = false;
                    for (int i = 0; i < n; i++) {
                        for (int j = 0; j < n; j++) {
                            if (inputGrid[i][j] == 'o') {
                                int dx = ii - i;
                                int dy = jj - j;
                                if (resultGrid[n - 1 + dx][n - 1 + dy] == 'x') {
                                    isCovered = true;
                                }
                            }
                        }
                    }
                    if (!isCovered) {
                        return false;
                    }
                }
            }
        }
        return true;
    }

    private char[][] readGrid(int n) throws IOException {
        char[][] grid = new char[n][n];
        for (int i = 0; i < n; i++) {
            grid[i] = nextToken().toCharArray();
        }
        return grid;
    }

    private int readInt() throws IOException {
        return Integer.parseInt(nextToken());
    }

    private String nextToken() throws IOException {
        while (tokenizer == null || !tokenizer.hasMoreTokens()) {
            String line = in.readLine();
            if (line == null) {
                throw new IOException("Unexpected end of input");
            }
            tokenizer = new StringTokenizer(line);
        }
        return tokenizer.nextToken();
    }

    private void close() {
        try {
            in.close();
        } catch (IOException ignored) {
            // Ignore close exceptions
        }
        out.flush();
        out.close();
    }
}

import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

/**
 * Solves the grid shift problem.
 * Identifies valid positions for a shape ('o's) on a grid ('.')
 * and checks if these positions can cover target locations ('x's).
 */
public class GridShiftSolver {

    /**
     * Represents a coordinate point (row, column).
     * Used for storing positions of 'o's and 'x's.
     * Implements equals and hashCode to allow correct usage in collections.
     */
    private static class Point {
        final int r;
        final int c;

        Point(int r, int c) {
            this.r = r;
            this.c = c;
        }

        @Override
        public boolean equals(Object obj) {
            if (this == obj) return true;
            if (!(obj instanceof Point)) return false;
            Point other = (Point) obj;
            return r == other.r && c == other.c;
        }

        @Override
        public int hashCode() {
            // Simple hash combining row and column
            return 31 * r + c;
        }
    }

    /**
     * Main execution logic for the solver.
     */
    public void solve() {
        Scanner scanner = new Scanner(System.in);

        // Read grid size
        if (!scanner.hasNextInt()) {
            return;
        }
        int n = scanner.nextInt();

        char[][] grid = new char[n][];
        List<Point> shapePositions = new ArrayList<>(); // Stores coordinates of 'o'
        List<Point> targetPositions = new ArrayList<>(); // Stores coordinates of 'x'

        // Read the grid and populate position lists
        for (int i = 0; i < n; i++) {
            if (scanner.hasNext()) {
                String row = scanner.next();
                grid[i] = row.toCharArray();
                for (int j = 0; j < n; j++) {
                    // Safety check for row length, though problem constraints usually guarantee n
                    if (j < grid[i].length) {
                        char ch = grid[i][j];
                        if (ch == 'o') {
                            shapePositions.add(new Point(i, j));
                        } else if (ch == 'x') {
                            targetPositions.add(new Point(i, j));
                        }
                    }
                }
            }
        }

        // Dimensions for the result grid
        int resSize = 2 * n - 1;
        char[][] resultGrid = new char[resSize][resSize];
        boolean[][] isCovered = new boolean[n][n]; // Tracks coverage of original 'x' positions

        // Initialize result grid with empty space
        for (int i = 0; i < resSize; i++) {
            for (int j = 0; j < resSize; j++) {
                resultGrid[i][j] = '.';
            }
        }

        int center = n - 1;

        // Iterate through all possible shifts (positions in the result grid)
        for (int i = 0; i < resSize; i++) {
            for (int j = 0; j < resSize; j++) {

                // Special case: The center of the result grid is hardcoded to 'o'
                if (i == center && j == center) {
                    resultGrid[i][j] = 'o';
                    continue;
                }

                // Calculate shift vector relative to the center
                int dy = i - center;
                int dx = j - center;

                boolean isValidShift = true;

                // Check if the shape fits and lands only on empty cells ('.')
                for (Point p : shapePositions) {
                    int ni = p.r + dy;
                    int nj = p.c + dx;

                    // Check bounds
                    if (ni < 0 || ni >= n || nj < 0 || nj >= n) {
                        isValidShift = false;
                        break;
                    }
                    // Check if the target cell in the original grid is empty
                    if (grid[ni][nj] != '.') {
                        isValidShift = false;
                        break;
                    }
                }

                if (isValidShift) {
                    // Mark this position as valid in the result grid
                    resultGrid[i][j] = 'x';

                    // Mark the cells in the original grid that are covered by this shift
                    for (Point p : shapePositions) {
                        int ni = p.r + dy;
                        int nj = p.c + dx;

                        // Bounds check (should be true if isValidShift is true, but safe to keep)
                        if (ni >= 0 && ni < n && nj >= 0 && nj < n) {
                            isCovered[ni][nj] = true;
                        }
                    }
                }
            }
        }

        // Determine if all target 'x' positions are covered
        boolean allCovered = true;
        for (Point target : targetPositions) {
            if (!isCovered[target.r][target.c]) {
                allCovered = false;
                break;
            }
        }

        // Output results
        if (allCovered) {
            System.out.println("YES");
            for (int i = 0; i < resSize; i++) {
                System.out.println(new String(resultGrid[i]));
            }
        } else {
            System.out.println("NO");
        }

        scanner.close();
    }

    public static void main(String[] args) {
        new GridShiftSolver().solve();
    }
}

import java.io.*;
import java.util.*;

/**
 * Validates grid shifts based on specific movement rules.
 * Determines valid shifts that map 'o' cells to other 'o' cells,
 * then checks if propagating these shifts covers all 'o' cells.
 */
public class GridShiftValidator {

    private FastScanner in;
    private PrintWriter out;

    /**
     * Entry point for execution. Initializes I/O and runs the solution.
     */
    public void run() {
        in = new FastScanner();
        out = new PrintWriter(System.out);
        solve();
        out.close();
    }

    private void solve() {
        int n = in.nextInt();
        char[][] grid = new char[n][n];
        for (int i = 0; i < n; i++) {
            grid[i] = in.nextToken().toCharArray();
        }

        int offset = n - 1;
        char[][] shiftMap = createFilledGrid(2 * n - 1, 2 * n - 1, '.');

        // The zero-shift (0,0) is always valid and marked as 'o'
        shiftMap[offset][offset] = 'o';

        // Evaluate all possible shifts
        for (int dx = -offset; dx <= offset; dx++) {
            for (int dy = -offset; dy <= offset; dy++) {
                if (dx == 0 && dy == 0) {
                    continue;
                }
                if (isShiftValid(grid, dx, dy, n)) {
                    shiftMap[offset + dx][offset + dy] = 'x';
                }
            }
        }

        // Initialize target grid with '.' and copy original 'o' positions
        char[][] targetGrid = createFilledGrid(n, n, '.');
        copyOriginalCells(grid, targetGrid);

        // Propagate valid shifts to mark reachable positions as 'x'
        propagateShifts(grid, shiftMap, targetGrid, n);

        // Compare original grid with target grid
        if (Arrays.deepEquals(grid, targetGrid)) {
            out.println("YES");
            for (char[] row : shiftMap) {
                out.println(new String(row));
            }
        } else {
            out.println("NO");
        }
    }

    /**
     * Checks if shifting the grid by (shiftX, shiftY) is valid.
     * A shift is valid if every 'o' cell shifted within bounds lands on another 'o'.
     */
    private boolean isShiftValid(char[][] grid, int shiftX, int shiftY, int n) {
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 'o') {
                    int ni = i + shiftX;
                    int nj = j + shiftY;
                    if (isWithinBounds(ni, nj, n) && grid[ni][nj] == '.') {
                        return false;
                    }
                }
            }
        }
        return true;
    }

    /**
     * Copies 'o' positions from the source grid to the target grid.
     */
    private void copyOriginalCells(char[][] source, char[][] target) {
        for (int i = 0; i < source.length; i++) {
            for (int j = 0; j < source[i].length; j++) {
                if (source[i][j] == 'o') {
                    target[i][j] = 'o';
                }
            }
        }
    }

    /**
     * Propagates valid shifts from the shiftMap to mark reachable positions in targetGrid.
     */
    private void propagateShifts(char[][] sourceGrid, char[][] shiftMap, char[][] targetGrid, int n) {
        int offset = n - 1;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (sourceGrid[i][j] == 'o') {
                    for (int dx = -offset; dx <= offset; dx++) {
                        for (int dy = -offset; dy <= offset; dy++) {
                            if (shiftMap[offset + dx][offset + dy] == 'x') {
                                int ni = i + dx;
                                int nj = j + dy;
                                if (isWithinBounds(ni, nj, n) && targetGrid[ni][nj] == '.') {
                                    targetGrid[ni][nj] = 'x';
                                }
                            }
                        }
                    }
                }
            }
        }
    }

    /**
     * Checks if coordinates are within the bounds of an n x n grid.
     */
    private boolean isWithinBounds(int x, int y, int n) {
        return x >= 0 && x < n && y >= 0 && y < n;
    }

    /**
     * Creates a 2D character array filled with a specified character.
     */
    private char[][] createFilledGrid(int rows, int cols, char fillChar) {
        char[][] grid = new char[rows][cols];
        for (char[] row : grid) {
            Arrays.fill(row, fillChar);
        }
        return grid;
    }

    public static void main(String[] args) {
        new GridShiftValidator().run();
    }

    /**
     * FastScanner utility for efficient input reading.
     */
    private static class FastScanner {
        private BufferedReader br;
        private StringTokenizer st;

        public FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        public FastScanner(String path) {
            try {
                br = new BufferedReader(new FileReader(path));
            } catch (FileNotFoundException e) {
                throw new RuntimeException(e);
            }
        }

        public String nextToken() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) {
                        throw new NoSuchElementException("End of input reached");
                    }
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(nextToken());
        }

        public long nextLong() {
            return Long.parseLong(nextToken());
        }

        public double nextDouble() {
            return Double.parseDouble(nextToken());
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.Arrays;

public class Main {

    public static void main(String[] args) throws IOException {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));

        // Read grid dimensions and populate the input grid
        int n = Integer.parseInt(reader.readLine().trim());
        char[][] grid = new char[n][n];
        for (int i = 0; i < n; i++) {
            grid[i] = reader.readLine().trim().toCharArray();
        }

        // Initialize the transformed grid with 'x'
        int gridSize = 2 * n - 1;
        char[][] transformedGrid = new char[gridSize][gridSize];
        for (char[] row : transformedGrid) {
            Arrays.fill(row, 'x');
        }

        // Count 'o's and apply transformation logic
        int oCount = 0;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 'o') {
                    oCount++;
                    for (int x = 0; x < n; x++) {
                        for (int y = 0; y < n; y++) {
                            if (grid[x][y] == '.') {
                                transformedGrid[gridSize / 2 + (x - i)][gridSize / 2 + (y - j)] = '.';
                            }
                        }
                    }
                }
            }
        }

        // Validate mismatch counts across all 'o' positions
        int[][] mismatchCount = new int[n][n];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 'o') {
                    for (int x = 0; x < n; x++) {
                        for (int y = 0; y < n; y++) {
                            int dx = x - i;
                            int dy = y - j;
                            char transformedChar = transformedGrid[gridSize / 2 + dx][gridSize / 2 + dy];
                            char gridChar = grid[x][y];

                            if ((gridChar == 'x' && transformedChar == '.') || 
                                (gridChar == '.' && transformedChar == 'x')) {
                                mismatchCount[x][y]++;
                            }
                        }
                    }
                }
            }
        }

        // Check validation condition
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (mismatchCount[i][j] == oCount) {
                    System.out.println("NO");
                    return;
                }
            }
        }

        // Prepare and print successful output
        StringBuilder output = new StringBuilder();
        output.append("YES\n");
        transformedGrid[gridSize / 2][gridSize / 2] = 'o';
        for (int i = 0; i < gridSize; i++) {
            output.append(transformedGrid[i]).append('\n');
        }
        System.out.print(output);
    }
}

import java.io.*;
import java.util.*;

public class Task {
    private static final char EMPTY = '.';
    private static final char ORIGIN = 'o';
    private static final char TARGET = 'x';

    public static void main(String[] args) throws IOException {
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
             PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out))) {
            new Task(br, out).solve();
        }
    }

    private final BufferedReader br;
    private final PrintWriter out;
    private StringTokenizer st;

    public Task(BufferedReader br, PrintWriter out) {
        this.br = br;
        this.out = out;
    }

    public void solve() throws IOException {
        int n = nextInt();
        String[] board = readBoard(n);
        List<int[]> originPositions = findOriginPositions(board, n);

        List<Move> candidates = generateCandidates(n);
        filterInvalidMoves(board, n, candidates, originPositions);

        if (!isValid(board, n, candidates, originPositions)) {
            out.println("NO");
            return;
        }

        out.println("YES");
        printResultBoard(n, candidates);
    }

    private String[] readBoard(int n) throws IOException {
        String[] board = new String[n];
        for (int i = 0; i < n; i++) {
            board[i] = nextToken();
        }
        return board;
    }

    private List<int[]> findOriginPositions(String[] board, int n) {
        List<int[]> positions = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            int idx = board[i].indexOf(ORIGIN);
            if (idx != -1) {
                positions.add(new int[]{i, idx});
            }
        }
        return positions;
    }

    private List<Move> generateCandidates(int n) {
        // Use a Set to automatically deduplicate offset combinations
        Set<Move> candidateSet = new HashSet<>();
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                candidateSet.add(new Move(i, j));
                candidateSet.add(new Move(-i, -j));
                candidateSet.add(new Move(-i, j));
                candidateSet.add(new Move(i, -j));
            }
        }
        return new ArrayList<>(candidateSet);
    }

    private void filterInvalidMoves(String[] board, int n, List<Move> candidates, List<int[]> originPositions) {
        Iterator<Move> it = candidates.iterator();
        while (it.hasNext()) {
            Move move = it.next();
            for (int[] pos : originPositions) {
                int destY = pos[0] + move.dy;
                int destX = pos[1] + move.dx;
                if (isInsideBoard(destY, destX, n) && board[destY].charAt(destX) == EMPTY) {
                    it.remove();
                    break;
                }
            }
        }
    }

    private boolean isValid(String[] board, int n, List<Move> candidates, List<int[]> originPositions) {
        boolean[][] mark = new boolean[n][n];

        for (int[] pos : originPositions) {
            int oy = pos[0];
            int ox = pos[1];
            mark[oy][ox] = true;
            for (Move move : candidates) {
                int destY = oy + move.dy;
                int destX = ox + move.dx;
                if (isInsideBoard(destY, destX, n)) {
                    mark[destY][destX] = true;
                }
            }
        }

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (board[i].charAt(j) == TARGET && !mark[i][j]) {
                    return false;
                }
            }
        }
        return true;
    }

    private void printResultBoard(int n, List<Move> candidates) {
        int size = 2 * n - 1;
        int center = n - 1;
        boolean[][] result = new boolean[size][size];

        for (Move move : candidates) {
            int r = center + move.dy;
            int c = center + move.dx;
            if (isInsideBoard(r, c, size)) {
                result[r][c] = true;
            }
        }

        for (int i = 0; i < size; i++) {
            for (int j = 0; j < size; j++) {
                if (i == center && j == center) {
                    out.print(ORIGIN);
                } else if (result[i][j]) {
                    out.print(TARGET);
                } else {
                    out.print(EMPTY);
                }
            }
            out.println();
        }
    }

    private boolean isInsideBoard(int y, int x, int n) {
        return y >= 0 && y < n && x >= 0 && x < n;
    }

    private String nextToken() throws IOException {
        while (st == null || !st.hasMoreTokens()) {
            try {
                st = new StringTokenizer(br.readLine());
            } catch (Exception e) {
                return null;
            }
        }
        return st.nextToken();
    }

    private int nextInt() throws IOException {
        String token = nextToken();
        return token == null ? 0 : Integer.parseInt(token);
    }

    private long nextLong() throws IOException {
        String token = nextToken();
        return token == null ? 0L : Long.parseLong(token);
    }

    private double nextDouble() throws IOException {
        String token = nextToken();
        return token == null ? 0.0 : Double.parseDouble(token);
    }

    /**
     * Represents a directional offset on the grid.
     */
    public static class Move {
        public final int dy, dx;

        public Move(int dy, int dx) {
            this.dy = dy;
            this.dx = dx;
        }

        @Override
        public boolean equals(Object o) {
            if (this == o) return true;
            if (!(o instanceof Move)) return false;
            Move move = (Move) o;
            return dy == move.dy && dx == move.dx;
        }

        @Override
        public int hashCode() {
            return Objects.hash(dy, dx);
        }

        @Override
        public String toString() {
            return dy + " " + dx;
        }
    }
}

