/**
 * Solver class containing the logic for Task D.
 */
class GridSolver {

    /**
     * Solves the problem by analyzing the grid configuration.
     *
     * @param in   The input scanner.
     * @param out  The output writer.
     */
    public void solve(FastScanner in, PrintWriter out) {
        int n = in.nextInt();
        char[][] grid = new char[n][];
        for (int i = 0; i < n; i++) {
            grid[i] = in.nextWord();
        }

        // The validPlacementMap represents a grid of size (2n-1) x (2n-1).
        // true means a position is valid for 'x', false means it is not.
        int gridSize = 2 * n - 1;
        boolean[][] validPlacementMap = new boolean[gridSize][gridSize];

        // Initialize all positions as valid
        for (boolean[] row : validPlacementMap) {
            Arrays.fill(row, true);
        }

        int centerIndex = n - 1;

        // The center of the output grid corresponds to the 'o' in the input.
        // It cannot be 'x'.
        validPlacementMap[centerIndex][centerIndex] = false;

        // Step 1: Determine forbidden positions for 'x' based on 'o' and '.' relationships.
        // If the input grid has an 'o' at (r, c) and a '.' at (dr, dc),
        // it implies that in the expanded grid, the position relative to 'o'
        // corresponding to the vector (dr-r, dc-c) cannot contain an 'x'.
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < n; c++) {
                if (grid[r][c] == 'o') {
                    for (int dr = 0; dr < n; dr++) {
                        for (int dc = 0; dc < n; dc++) {
                            if (grid[dr][dc] == '.') {
                                // Map the relative vector to the global grid coordinates
                                int globalRow = centerIndex + dr - r;
                                int globalCol = centerIndex + dc - c;
                                validPlacementMap[globalRow][globalCol] = false;
                            }
                        }
                    }
                }
            }
        }

        // Step 2: Check if all 'x's present in the input grid are valid.
        // An 'x' at (r, c) in the input is valid if it is compatible with at least one 'o'
        // in the input grid according to the validPlacementMap.
        boolean[][] xIsCovered = new boolean[n][n];

        for (int r = 0; r < n; r++) {
            for (int c = 0; c < n; c++) {
                if (grid[r][c] == 'o') { // This 'o' acts as a pivot
                    // Check every potential 'x' position (dr, dc) in the input grid
                    for (int dr = 0; dr < n; dr++) {
                        for (int dc = 0; dc < n; dc++) {
                            // Calculate global coordinates relative to the pivot 'o'
                            int globalRow = centerIndex + dr - r;
                            int globalCol = centerIndex + dc - c;

                            // If the global position allows an 'x', mark this input cell as covered
                            if (validPlacementMap[globalRow][globalCol]) {
                                xIsCovered[dr][dc] = true;
                            }
                        }
                    }
                }
            }
        }

        // Step 3: Validation
        // If any 'x' in the input grid is not covered (valid), the configuration is impossible.
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < n; c++) {
                if (grid[r][c] == 'x' && !xIsCovered[r][c]) {
                    out.println("NO");
                    return;
                }
            }
        }

        // Step 4: Output Result
        out.println("YES");
        for (int r = 0; r < validPlacementMap.length; r++) {
            for (int c = 0; c < validPlacementMap.length; c++) {
                // Center is 'o', valid spots are 'x', others are '.'
                char cell = (r == centerIndex && c == centerIndex) 
                            ? 'o' 
                            : (validPlacementMap[r][c] ? 'x' : '.');
                out.print(cell);
            }
            out.println();
        }
    }
}

