class TaskD {
    private static final char OBSTACLE = 'o';
    private static final char EMPTY = '.';
    private static final char MARKER = 'x';

    public void solve(Scanner in, PrintWriter out) {
        int n = in.nextInt();
        char[][] grid = new char[n][n];
        for (int i = 0; i < n; i++) {
            grid[i] = in.next().toCharArray();
        }

        int gridSize = 2 * n - 1;
        int centerOffset = n - 1;

        // Initialize placement validity grid (true means valid)
        boolean[][] isValidPlacement = new boolean[gridSize][gridSize];
        for (boolean[] row : isValidPlacement) {
            Arrays.fill(row, true);
        }

        // Mark invalid placements based on obstacle ('o') and empty ('.') positions
        markInvalidPlacements(grid, n, centerOffset, isValidPlacement);

        // Determine valid top-left positions for the pattern
        boolean[][] validTopLeftPositions = calculateValidTopLeftPositions(grid, n, centerOffset, isValidPlacement);

        // Validate that all markers ('x') have a valid top-left position
        if (!validateMarkers(grid, n, validTopLeftPositions)) {
            out.println("NO");
            return;
        }

        out.println("YES");
        printResult(isValidPlacement, n, centerOffset, out);
    }

    private void markInvalidPlacements(char[][] grid, int n, int centerOffset, boolean[][] isValidPlacement) {
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == OBSTACLE) {
                    for (int x = 0; x < n; x++) {
                        for (int y = 0; y < n; y++) {
                            if (grid[x][y] == EMPTY) {
                                int placementRow = x - i + centerOffset;
                                int placementCol = y - j + centerOffset;
                                isValidPlacement[placementRow][placementCol] = false;
                            }
                        }
                    }
                }
            }
        }
    }

    private boolean[][] calculateValidTopLeftPositions(char[][] grid, int n, int centerOffset, boolean[][] isValidPlacement) {
        boolean[][] validTopLeft = new boolean[n][n];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == OBSTACLE) {
                    for (int x = 0; x < n; x++) {
                        for (int y = 0; y < n; y++) {
                            if (isValidPlacement[x - i + centerOffset][y - j + centerOffset]) {
                                validTopLeft[x][y] = true;
                            }
                        }
                    }
                }
            }
        }
        return validTopLeft;
    }

    private boolean validateMarkers(char[][] grid, int n, boolean[][] validTopLeft) {
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == MARKER && !validTopLeft[i][j]) {
                    return false;
                }
            }
        }
        return true;
    }

    private void printResult(boolean[][] isValidPlacement, int n, int centerOffset, PrintWriter out) {
        int gridSize = 2 * n - 1;
        for (int i = 0; i < gridSize; i++) {
            for (int j = 0; j < gridSize; j++) {
                if (i == centerOffset && j == centerOffset) {
                    out.print(OBSTACLE);
                } else if (isValidPlacement[i][j]) {
                    out.print(MARKER);
                } else {
                    out.print(EMPTY);
                }
            }
            out.println();
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Validates a board configuration based on specific rules regarding forbidden
 * vectors and obstacle placement.
 */
public class BoardValidator {

    private FastScanner in;
    private PrintWriter out;
    private int n;
    private List<Point> forbiddenCenters;
    private List<Point> emptyCells;
    private List<Point> obstacles;
    private boolean[][] observedVectors;
    private boolean[][] safePositions;

    public BoardValidator() {
        this.in = new FastScanner(System.in);
        this.out = new PrintWriter(new BufferedOutputStream(System.out));
    }

    public void run() {
        try {
            Locale.setDefault(Locale.US);
            solve();
        } catch (IOException e) {
            e.printStackTrace();
            System.exit(1);
        } finally {
            out.close();
        }
    }

    private void solve() throws IOException {
        readInput();
        processLogic();
        printOutput();
    }

    private void readInput() throws IOException {
        n = in.nextInt();
        forbiddenCenters = new ArrayList<>();
        emptyCells = new ArrayList<>();
        obstacles = new ArrayList<>();

        for (int i = 0; i < n; i++) {
            String row = in.next();
            for (int j = 0; j < n; j++) {
                char c = row.charAt(j);
                if (c == 'o') {
                    forbiddenCenters.add(new Point(i, j));
                } else if (c == '.') {
                    emptyCells.add(new Point(i, j));
                } else if (c == 'x') {
                    obstacles.add(new Point(i, j));
                }
            }
        }
    }

    private void processLogic() {
        // observedVectors stores relative vectors (dx, dy) observed between
        // any forbidden center ('o') and any empty cell ('.').
        // Size is 2n-1 to accommodate negative indices via offset (n-1).
        observedVectors = new boolean[2 * n - 1][2 * n - 1];

        for (Point center : forbiddenCenters) {
            for (Point empty : emptyCells) {
                int dx = empty.x - center.x;
                int dy = empty.y - center.y;
                observedVectors[dx + n - 1][dy + n - 1] = true;
            }
        }

        // safePositions marks cells that are valid for obstacles ('x').
        // A cell is safe if the relative vector from ANY forbidden center to that cell
        // is NOT present in observedVectors.
        safePositions = new boolean[n][n];

        for (Point center : forbiddenCenters) {
            for (int x = 0; x < n; x++) {
                for (int y = 0; y < n; y++) {
                    int dx = x - center.x;
                    int dy = y - center.y;

                    // Check if the vector (dx, dy) is observed.
                    // Indices are shifted by n-1.
                    if (!observedVectors[dx + n - 1][dy + n - 1]) {
                        safePositions[x][y] = true;
                    }
                }
            }
        }
    }

    private void printOutput() {
        // Check if any obstacle ('x') is in an unsafe position
        boolean possible = true;
        for (Point obstacle : obstacles) {
            if (!safePositions[obstacle.x][obstacle.y]) {
                possible = false;
                break;
            }
        }

        if (!possible) {
            out.println("NO");
        } else {
            out.println("YES");
            // Print the observed vectors grid, centered at (n-1, n-1)
            for (int i = 0; i < 2 * n - 1; i++) {
                for (int j = 0; j < 2 * n - 1; j++) {
                    if (i == n - 1 && j == n - 1) {
                        out.print("o");
                    } else {
                        out.print(observedVectors[i][j] ? "." : "x");
                    }
                }
                out.println();
            }
        }
    }

    /**
     * Simple Point class to store coordinates.
     */
    private static class Point {
        int x, y;

        Point(int x, int y) {
            this.x = x;
            this.y = y;
        }
    }

    /**
     * FastScanner for efficient input reading.
     */
    private static class FastScanner {
        BufferedReader br;
        StringTokenizer st;

        FastScanner(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        String next() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) return null;
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

        int nextInt() throws IOException {
            String s = next();
            return (s == null) ? 0 : Integer.parseInt(s);
        }
    }

    public static void main(String[] args) {
        new BoardValidator().run();
    }
}

import java.io.BufferedReader;
import java.io.BufferedWriter;
import java.io.Closeable;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.OutputStreamWriter;
import java.io.PrintWriter;
import java.util.Arrays;
import java.util.StringTokenizer;

/**
 * Solves a board validation problem by computing move grids and verifying 
 * board configurations against expected patterns.
 */
public class BoardGameSolver implements Closeable {
    private final BufferedReader reader;
    private final PrintWriter writer;
    private StringTokenizer tokenizer;

    public BoardGameSolver() {
        this.reader = new BufferedReader(new InputStreamReader(System.in));
        this.writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)));
    }

    /**
     * Reads the next token from input, handling line breaks and EOF gracefully.
     */
    private String next() throws IOException {
        while (tokenizer == null || !tokenizer.hasMoreTokens()) {
            String line = reader.readLine();
            if (line == null) {
                throw new IOException("Unexpected end of input");
            }
            tokenizer = new StringTokenizer(line);
        }
        return tokenizer.nextToken();
    }

    private int nextInt() throws IOException {
        return Integer.parseInt(next());
    }

    /**
     * Orchestrates the core solving logic.
     */
    public void solve() throws IOException {
        int n = nextInt();
        char[][] board = readBoard(n);
        char[][] moveGrid = computeMoveGrid(board, n);
        char[][] validationGrid = computeValidationGrid(board, moveGrid, n);

        if (areBoardsEqual(board, validationGrid)) {
            writer.println("YES");
            printGrid(moveGrid);
        } else {
            writer.println("NO");
        }
    }

    /**
     * Reads an n x n character grid from standard input.
     */
    private char[][] readBoard(int n) throws IOException {
        char[][] board = new char[n][n];
        for (int i = 0; i < n; i++) {
            board[i] = next().toCharArray();
        }
        return board;
    }

    /**
     * Computes the move grid based on 'o' positions in the board.
     * Marks relative positions where the board contains '.' as '.' in the move grid.
     */
    private char[][] computeMoveGrid(char[][] board, int n) {
        int gridSize = 2 * n - 1;
        char[][] moveGrid = new char[gridSize][gridSize];
        for (char[] row : moveGrid) {
            Arrays.fill(row, 'x');
        }
        int center = n - 1;

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (board[i][j] == 'o') {
                    for (int r = 0; r < n; r++) {
                        for (int c = 0; c < n; c++) {
                            if (board[r][c] == '.') {
                                moveGrid[center + r - i][center + c - j] = '.';
                            }
                        }
                    }
                }
            }
        }
        return moveGrid;
    }

    /**
     * Validates the board against the computed move grid.
     * Generates a validation grid and marks cells as 'x' if corresponding move grid positions are 'x'.
     */
    private char[][] computeValidationGrid(char[][] board, char[][] moveGrid, int n) {
        char[][] validationGrid = new char[n][n];
        for (char[] row : validationGrid) {
            Arrays.fill(row, '.');
        }
        int center = n - 1;

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (board[i][j] == 'o') {
                    validationGrid[i][j] = 'o';
                    for (int r = 0; r < n; r++) {
                        for (int c = 0; c < n; c++) {
                            if (validationGrid[r][c] == '.' && moveGrid[center + r - i][center + c - j] == 'x') {
                                validationGrid[r][c] = 'x';
                            }
                        }
                    }
                }
            }
        }
        return validationGrid;
    }

    /**
     * Compares two character grids for structural equality.
     */
    private boolean areBoardsEqual(char[][] board1, char[][] board2) {
        for (int i = 0; i < board1.length; i++) {
            if (!Arrays.equals(board1[i], board2[i])) {
                return false;
            }
        }
        return true;
    }

    /**
     * Prints a character grid to standard output.
     */
    private void printGrid(char[][] grid) {
        for (char[] row : grid) {
            writer.println(row);
        }
    }

    public static void main(String[] args) {
        try (BoardGameSolver solver = new BoardGameSolver()) {
            solver.solve();
        } catch (IOException e) {
            System.err.println("I/O Error: " + e.getMessage());
        }
    }

    @Override
    public void close() throws IOException {
        writer.flush();
        reader.close();
    }
}

import java.util.Arrays;
import java.util.Scanner;

public class Prob04 {

    public static void main(String[] args) {
        // Use try-with-resources to ensure the Scanner is properly closed
        try (Scanner scanner = new Scanner(System.in)) {
            if (!scanner.hasNextLine()) {
                return;
            }

            int gridSize = Integer.parseInt(scanner.nextLine().trim());
            char[][] initialBoard = readInputBoard(scanner, gridSize);
            char[][] resultGrid = initializeResultGrid(gridSize);

            processGrids(initialBoard, resultGrid, gridSize);

            if (hasRemainingX(initialBoard)) {
                System.out.println("NO");
            } else {
                System.out.println("YES");
                printResultGrid(resultGrid);
            }
        }
    }

    /**
     * Reads the n x n character grid from standard input.
     */
    private static char[][] readInputBoard(Scanner scanner, int n) {
        char[][] board = new char[n][n];
        for (int i = 0; i < n; i++) {
            board[i] = scanner.nextLine().toCharArray();
        }
        return board;
    }

    /**
     * Initializes the expanded result grid with 'x' and places the center anchor 'o'.
     */
    private static char[][] initializeResultGrid(int n) {
        int expandedSize = 2 * n - 1;
        char[][] grid = new char[expandedSize][expandedSize];
        for (char[] row : grid) {
            Arrays.fill(row, 'x');
        }
        grid[n - 1][n - 1] = 'o';
        return grid;
    }

    /**
     * Executes the two-phase transformation logic on the grids.
     * Phase 1: Maps '.' positions relative to each 'o' anchor to the result grid.
     * Phase 2: Marks positions in the initial board as 'y' where both the board 
     *          and the result grid contain 'x' at corresponding relative coordinates.
     */
    private static void processGrids(char[][] initialBoard, char[][] resultGrid, int n) {
        int centerOffset = n - 1;

        // Phase 1: Map '.' positions relative to each 'o' anchor
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (initialBoard[i][j] != 'o') {
                    continue;
                }

                for (int p = 0; p < n; p++) {
                    for (int q = 0; q < n; q++) {
                        if (initialBoard[p][q] == '.') {
                            resultGrid[centerOffset + p - i][centerOffset + q - j] = '.';
                        }
                    }
                }
            }
        }

        // Phase 2: Mark overlapping 'x' positions as 'y'
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (initialBoard[i][j] != 'o') {
                    continue;
                }

                for (int p = 0; p < n; p++) {
                    for (int q = 0; q < n; q++) {
                        if (initialBoard[p][q] == 'x' &&
                            resultGrid[centerOffset + p - i][centerOffset + q - j] == 'x') {
                            initialBoard[p][q] = 'y';
                        }
                    }
                }
            }
        }
    }

    /**
     * Checks if any cell in the board remains 'x', indicating an unresolved state.
     */
    private static boolean hasRemainingX(char[][] board) {
        for (char[] row : board) {
            for (char cell : row) {
                if (cell == 'x') {
                    return true;
                }
            }
        }
        return false;
    }

    /**
     * Prints the final result grid to standard output.
     */
    private static void printResultGrid(char[][] grid) {
        for (char[] row : grid) {
            System.out.println(new String(row));
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayDeque;
import java.util.Deque;

public class Solution {

    private static final int[][] DIRECTIONS = {
        {-1, 0}, {1, 0}, {0, -1}, {0, 1} // Up, Down, Left, Right
    };

    public static void main(String[] args) {
        // Use try-with-resources for automatic resource cleanup
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(System.in))) {
            Solution solution = new Solution();
            solution.run(reader);
        } catch (IOException e) {
            System.err.println("Failed to read input: " + e.getMessage());
        }
    }

    /**
     * Handles all input parsing and delegates to the pathfinding algorithm.
     */
    public void run(BufferedReader reader) throws IOException {
        String[] dimensions = reader.readLine().trim().split("\\s+");
        int rows = Integer.parseInt(dimensions[0]);
        int cols = Integer.parseInt(dimensions[1]);

        char[][] grid = new char[rows][];
        for (int i = 0; i < rows; i++) {
            grid[i] = reader.readLine().trim().toCharArray();
        }

        String[] startInput = reader.readLine().trim().split("\\s+");
        int startRow = Integer.parseInt(startInput[0]) - 1; // Convert to 0-based index
        int startCol = Integer.parseInt(startInput[1]) - 1;

        String[] endInput = reader.readLine().trim().split("\\s+");
        int endRow = Integer.parseInt(endInput[0]) - 1;
        int endCol = Integer.parseInt(endInput[1]) - 1;

        PathFinder finder = new PathFinder(rows, cols, grid);
        finder.findPath(startRow, startCol, endRow, endCol);
    }

    /**
     * Encapsulates the DFS pathfinding logic and grid traversal rules.
     */
    private static class PathFinder {
        private final int rows;
        private final int cols;
        private final char[][] grid;

        // Simple coordinate class for stack storage
        private static class Point {
            final int row;
            final int col;

            Point(int row, int col) {
                this.row = row;
                this.col = col;
            }
        }

        public PathFinder(int rows, int cols, char[][] grid) {
            this.rows = rows;
            this.cols = cols;
            this.grid = grid;
        }

        public void findPath(int startRow, int startCol, int endRow, int endCol) {
            // ArrayDeque is preferred over legacy Stack for better performance
            Deque<Point> stack = new ArrayDeque<>();
            boolean[][] visited = new boolean[rows][cols];

            stack.push(new Point(startRow, startCol));
            visited[startRow][startCol] = true;

            while (!stack.isEmpty()) {
                Point current = stack.pop();
                int currRow = current.row;
                int currCol = current.col;

                // Check destination and apply the specific neighbor-count condition
                if (currRow == endRow && currCol == endCol && countValidNeighbors(startRow, startCol, currRow, currCol) > 1) {
                    System.out.println("YES");
                    return;
                }

                // Explore all 4 directional neighbors
                for (int[] dir : DIRECTIONS) {
                    int nextRow = currRow + dir[0];
                    int nextCol = currCol + dir[1];

                    if (isValidMove(nextRow, nextCol, endRow, endCol) && !visited[nextRow][nextCol]) {
                        visited[nextRow][nextCol] = true;
                        stack.push(new Point(nextRow, nextCol));
                    }
                }
            }

            System.out.println("NO");
        }

        /**
         * Determines if a move to (r, c) is allowed based on grid content and boundaries.
         * '.' is always traversable. 'X' is only allowed if it's the destination.
         */
        private boolean isValidMove(int r, int c, int endRow, int endCol) {
            if (r < 0 || r >= rows || c < 0 || c >= cols) {
                return false;
            }
            char cell = grid[r][c];
            return cell == '.' || (cell == 'X' && r == endRow && c == endCol);
        }

        /**
         * Counts valid exits from the current cell.
         * Mirrors the original `res` method logic:
         * - Counts 1 if the current cell itself is 'X'
         * - Counts 1 for each adjacent '.' cell
         * - Counts 1 for an adjacent 'X' cell only if it's the start position
         */
        private int countValidNeighbors(int startRow, int startCol, int currentRow, int currentCol) {
            int count = 0;
            if (grid[currentRow][currentCol] == 'X') {
                count++;
            }

            for (int[] dir : DIRECTIONS) {
                int nr = currentRow + dir[0];
                int nc = currentCol + dir[1];

                if (nr >= 0 && nr < rows && nc >= 0 && nc < cols) {
                    char neighbor = grid[nr][nc];
                    if (neighbor == '.' || (neighbor == 'X' && nr == startRow && nc == startCol)) {
                        count++;
                    }
                }
            }
            return count;
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

public class TaskA {

    /**
     * FastScanner for efficient input reading in competitive programming contexts.
     */
    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        String next() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) {
                    throw new IOException("Unexpected end of input");
                }
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }

    /**
     * Encapsulates grid traversal, neighbor counting, and pathfinding logic.
     */
    static class PathFinder {
        private final int rows;
        private final int cols;
        private final boolean[][] obstacles;
        private final boolean[][] visited;
        private final int[] dr = {0, 1, -1, 0};
        private final int[] dc = {1, 0, 0, -1};
        private boolean targetReached = false;

        PathFinder(int rows, int cols, boolean[][] obstacles) {
            this.rows = rows;
            this.cols = cols;
            this.obstacles = obstacles;
            this.visited = new boolean[rows][cols];
        }

        public boolean canReach(int startR, int startC, int targetR, int targetC) {
            dfs(startR, startC, targetR, targetC);
            return targetReached;
        }

        private void dfs(int r, int c, int targetR, int targetC) {
            if (targetReached) return;
            visited[r][c] = true;

            for (int i = 0; i < 4; i++) {
                int nr = r + dr[i];
                int nc = c + dc[i];

                if (isValid(nr, nc)) {
                    if (nr == targetR && nc == targetC) {
                        targetReached = true;
                        return;
                    }
                    if (!obstacles[nr][nc] && !visited[nr][nc]) {
                        dfs(nr, nc, targetR, targetC);
                    }
                }
            }
        }

        private boolean isValid(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }

        public int countOpenNeighbors(int r, int c) {
            int count = 0;
            for (int i = 0; i < 4; i++) {
                int nr = r + dr[i];
                int nc = c + dc[i];
                if (isValid(nr, nc) && !obstacles[nr][nc]) {
                    count++;
                }
            }
            return count;
        }

        public boolean isAdjacent(int r1, int c1, int r2, int c2) {
            return (Math.abs(r1 - r2) == 1 && Math.abs(c1 - c2) == 0) ||
                   (Math.abs(r1 - r2) == 0 && Math.abs(c1 - c2) == 1);
        }

        /**
         * Evaluates the problem-specific conditions to determine the output.
         */
        public boolean shouldOutputYes(int startR, int startC, int targetR, int targetC) {
            boolean isTargetCracked = obstacles[targetR][targetC];
            int openNeighbors = countOpenNeighbors(targetR, targetC);
            boolean reached = canReach(startR, startC, targetR, targetC);

            if (!reached) return false;
            if (isTargetCracked) return true;
            if (isAdjacent(startR, startC, targetR, targetC) && openNeighbors >= 1) return true;
            if (openNeighbors >= 2) return true;
            return false;
        }
    }

    public static void main(String[] args) throws IOException {
        FastScanner scanner = new FastScanner(System.in);
        int n = scanner.nextInt();
        int m = scanner.nextInt();

        boolean[][] grid = new boolean[n][m];
        for (int i = 0; i < n; i++) {
            String line = scanner.next();
            for (int j = 0; j < m; j++) {
                grid[i][j] = line.charAt(j) == '#'; // true represents an obstacle
            }
        }

        // Convert 1-based input coordinates to 0-based indexing
        int r1 = scanner.nextInt() - 1;
        int c1 = scanner.nextInt() - 1;
        int r2 = scanner.nextInt() - 1;
        int c2 = scanner.nextInt() - 1;

        PathFinder finder = new PathFinder(n, m, grid);
        boolean result = finder.shouldOutputYes(r1, c1, r2, c2);
        System.out.println(result ? "YES" : "NO");
    }
}

import java.util.Scanner;

/**
 * A solver for grid pathfinding problems.
 * Determines if a path exists from a start point to an end point,
 * considering obstacles ('X') and specific exit conditions.
 */
public class GridPathSolver {

    // Direction vectors for moving Right, Down, Left, Up
    private static final int[] DR = {0, 1, 0, -1};
    private static final int[] DC = {1, 0, -1, 0};

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        try {
            solve(scanner);
        } finally {
            scanner.close();
        }
    }

    /**
     * Main logic to solve the pathfinding problem.
     */
    public static void solve(Scanner scanner) {
        // 1. Read Dimensions
        if (!scanner.hasNextInt()) return;
        int rows = scanner.nextInt();
        int cols = scanner.nextInt();

        // Consume the newline character after reading integers
        scanner.nextLine();

        // 2. Read Grid
        char[][] grid = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            String line = scanner.nextLine();
            // Note: toCharArray() creates a copy. 
            // We assume input lines are at least 'cols' long.
            grid[i] = line.toCharArray();
        }

        // 3. Read Coordinates (1-based to 0-based conversion)
        int startRow = scanner.nextInt() - 1;
        int startCol = scanner.nextInt() - 1;
        int endRow = scanner.nextInt() - 1;
        int endCol = scanner.nextInt() - 1;

        // 4. Handle Start == End Case
        if (startRow == endRow && startCol == endCol) {
            // If start and end are the same, check if there is at least one valid neighbor
            // (either '.' or the start point itself).
            int validNeighbors = countValidNeighbors(grid, endRow, endCol, rows, cols, startRow, startCol);
            System.out.println(validNeighbors > 0 ? "YES" : "NO");
            return;
        }

        // 5. Pathfinding Setup
        boolean[][] visited = new boolean[rows][cols];

        // Mark 'X' cells as visited (blocked)
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                // Check bounds for row length just in case input is malformed
                if (j < grid[i].length && grid[i][j] == 'X') {
                    visited[i][j] = true;
                }
            }
        }

        // Ensure destination is not marked as visited initially
        // (It might be 'X', but we need to be able to reach it)
        if (isValid(endRow, endCol, rows, cols)) {
            visited[endRow][endCol] = false;
        }

        // 6. Run DFS from start position
        if (isValid(startRow, startCol, rows, cols)) {
            dfs(startRow, startCol, visited);
        }

        boolean pathFound = visited[endRow][endCol];

        if (pathFound) {
            // Check destination cell type
            boolean isDestinationEmpty = isValid(endRow, endCol, rows, cols) 
                                         && endCol < grid[endRow].length 
                                         && grid[endRow][endCol] == '.';

            if (isDestinationEmpty) {
                // If destination is '.', we need > 1 valid neighbors (exits)
                int validNeighbors = countValidNeighbors(grid, endRow, endCol, rows, cols, startRow, startCol);
                System.out.println(validNeighbors > 1 ? "YES" : "NO");
            } else {
                // If destination is not '.' (e.g., 'X'), just reaching it is enough
                System.out.println("YES");
            }
        } else {
            System.out.println("NO");
        }
    }

    /**
     * Counts neighbors of (r, c) that are either '.' or the start point (startR, startC).
     */
    private static int countValidNeighbors(char[][] grid, int r, int c, int n, int m, int startR, int startC) {
        int count = 0;
        for (int i = 0; i < 4; i++) {
            int nr = r + DR[i];
            int nc = c + DC[i];

            if (isValid(nr, nc, n, m)) {
                // Check if neighbor is the start point
                boolean isStart = (nr == startR && nc == startC);
                // Check if neighbor is an empty space
                boolean isDot = (nc < grid[nr].length && grid[nr][nc] == '.');

                if (isDot || isStart) {
                    count++;
                }
            }
        }
        return count;
    }

    /**
     * Checks if coordinates are within grid bounds.
     */
    private static boolean isValid(int r, int c, int n, int m) {
        return r >= 0 && r < n && c >= 0 && c < m;
    }

    /**
     * Recursive DFS to mark reachable cells in the visited array.
     */
    private static void dfs(int r, int c, boolean[][] visited) {
        int n = visited.length;
        int m = visited[0].length;

        visited[r][c] = true;

        for (int i = 0; i < 4; i++) {
            int nr = r + DR[i];
            int nc = c + DC[i];

            if (isValid(nr, nc, n, m) && !visited[nr][nc]) {
                dfs(nr, nc, visited);
            }
        }
    }
}

import java.util.ArrayDeque;
import java.util.Queue;
import java.util.Scanner;

public class GridPathfinder {

    // Direction vectors: Right, Down, Left, Up
    private static final int[][] DIRECTIONS = {
        {0, 1}, {1, 0}, {0, -1}, {-1, 0}
    };

    // Grid state constants
    private static final int STATE_WALKABLE = 2;
    private static final int STATE_WALL = 1;

    public static void main(String[] args) {
        // Proper resource management for Scanner
        try (Scanner scanner = new Scanner(System.in)) {
            new GridPathfinder().run(scanner);
        }
    }

    /**
     * Orchestrates input reading, grid creation, and pathfinding execution.
     */
    public void run(Scanner scanner) {
        int rows = scanner.nextInt();
        int cols = scanner.nextInt();

        int[][] grid = createGrid(scanner, rows, cols);

        int startRow = scanner.nextInt() - 1;
        int startCol = scanner.nextInt() - 1;
        int targetRow = scanner.nextInt() - 1;
        int targetCol = scanner.nextInt() - 1;

        boolean success = traverse(grid, startRow, startCol, targetRow, targetCol);
        System.out.println(success ? "YES" : "NO");
    }

    /**
     * Reads the grid input and converts it to an integer matrix.
     * '.' becomes STATE_WALKABLE (2), any other character becomes STATE_WALL (1).
     */
    private int[][] createGrid(Scanner scanner, int rows, int cols) {
        int[][] grid = new int[rows][cols];
        for (int i = 0; i < rows; i++) {
            String rowString = scanner.next();
            for (int j = 0; j < cols; j++) {
                grid[i][j] = (rowString.charAt(j) == '.') ? STATE_WALKABLE : STATE_WALL;
            }
        }
        return grid;
    }

    /**
     * Performs a traversal to determine if the target is reachable under the 
     * original algorithm's rules.
     */
    private boolean traverse(int[][] grid, int startRow, int startCol, 
                             int targetRow, int targetCol) {
        Queue<Point> queue = new ArrayDeque<>();
        queue.offer(new Point(startRow, startCol));

        // Mark start position as active/walkable
        grid[startRow][startCol] = STATE_WALKABLE;

        while (!queue.isEmpty()) {
            Point current = queue.poll();

            // Check if target reached and meets original condition
            if (current.row == targetRow && current.col == targetCol 
                    && grid[targetRow][targetCol] == STATE_WALL) {
                return true;
            }

            // Skip processing if cell is a wall
            if (grid[current.row][current.col] == STATE_WALL) {
                continue;
            }

            // Decrement cell state (acts as a visit counter/health mechanic)
            grid[current.row][current.col]--;

            // Explore neighbors
            for (int[] direction : DIRECTIONS) {
                int nextRow = current.row + direction[0];
                int nextCol = current.col + direction[1];

                if (isValidCoordinate(nextRow, nextCol, grid.length, grid[0].length)) {
                    queue.offer(new Point(nextRow, nextCol));
                }
            }
        }
        return false;
    }

    /**
     * Checks if coordinates are within grid boundaries.
     */
    private boolean isValidCoordinate(int row, int col, int maxRow, int maxCol) {
        return row >= 0 && row < maxRow && col >= 0 && col < maxCol;
    }

    /**
     * Immutable coordinate holder.
     */
    private static class Point {
        final int row;
        final int col;

        Point(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

/**
 * Refactored solution for CF540C (or similar grid traversal problem).
 * Improvements include better naming, separation of concerns, and robust input parsing.
 */
public class CF540C {

    // Constants to replace magic numbers in the logic
    private static final int NEIGHBORS_REQUIRED_FOR_DESTINATION = 2;
    private static final int NEIGHBORS_REQUIRED_FOR_START = 1;

    // Direction vectors for grid traversal (Up, Down, Left, Right)
    private static final int[] DR = {-1, 1, 0, 0};
    private static final int[] DC = {0, 0, -1, 1};

    public static void main(String[] args) {
        FastScanner sc = new FastScanner();
        PrintWriter out = new PrintWriter(System.out);

        try {
            // Read dimensions
            String nStr = sc.next();
            if (nStr == null) return; // Handle empty input gracefully
            int n = Integer.parseInt(nStr);
            int m = sc.nextInt();

            // Grid representation: true = passable ('.'), false = obstacle
            boolean[][] grid = new boolean[n][m];

            // Read grid
            for (int i = 0; i < n; i++) {
                String rowStr = sc.next();
                // Use toCharArray for robust character parsing.
                // Note: Original code used split(""), which creates an empty string at index 0 in Java.
                // This fix ensures the first character is parsed correctly.
                char[] chars = rowStr.toCharArray();
                for (int j = 0; j < m; j++) {
                    if (j < chars.length) {
                        grid[i][j] = (chars[j] == '.');
                    } else {
                        grid[i][j] = false; // Default to obstacle if string is short
                    }
                }
            }

            // Read coordinates (convert 1-based input to 0-based)
            int startRow = sc.nextInt() - 1;
            int startCol = sc.nextInt() - 1;
            int endRow = sc.nextInt() - 1;
            int endCol = sc.nextInt() - 1;

            // Solve and print result
            boolean result = solve(grid, startRow, startCol, endRow, endCol);
            out.println(result ? "YES" : "NO");

        } catch (Exception e) {
            e.printStackTrace();
        } finally {
            out.flush();
        }
    }

    /**
     * Determines if the destination is reachable under specific constraints.
     */
    private static boolean solve(boolean[][] grid, int startRow, int startCol, int endRow, int endCol) {
        // 1. Check reachability using DFS
        // We pass a visited array to keep track of traversal state.
        boolean[][] visited = new boolean[grid.length][grid[0].length];

        // Pass start coordinates to DFS to handle the logic where the start cell
        // is treated as passable even if it was originally an obstacle (mimicking original mat[source]=true).
        boolean isReachable = dfs(grid, startRow, startCol, startRow, startCol, endRow, endCol, visited);

        if (!isReachable) {
            return false;
        }

        // 2. Check specific conditions for the destination cell
        // Logic derived from original return statement:
        // return dfs(...) && (!mat[destRow][destCol] || adjBlank >= 2 
        //          || (sourceRow == destRow && sourceCol == destCol && adjBlank >= 1));

        int adjacentPassableCount = countAdjacentPassable(grid, endRow, endCol);
        boolean isDestinationObstacle = !grid[endRow][endCol];
        boolean isStartEqualToEnd = (startRow == endRow && startCol == endCol);

        // Condition 1: Destination is an obstacle (logic allows passing through obstacles at dest)
        if (isDestinationObstacle) {
            return true;
        }

        // Condition 2: Destination is passable
        // If start and end are the same, we need at least 1 neighbor
        if (isStartEqualToEnd) {
            return adjacentPassableCount >= NEIGHBORS_REQUIRED_FOR_START;
        }

        // Condition 3: Normal case, need at least 2 neighbors
        return adjacentPassableCount >= NEIGHBORS_REQUIRED_FOR_DESTINATION;
    }

    /**
     * Counts the number of adjacent passable cells.
     */
    private static int countAdjacentPassable(boolean[][] grid, int r, int c) {
        int count = 0;
        for (int k = 0; k < 4; k++) {
            int nr = r + DR[k];
            int nc = c + DC[k];

            if (isValidCell(grid, nr, nc) && grid[nr][nc]) {
                count++;
            }
        }
        return count;
    }

    /**
     * Checks if coordinates are within grid bounds.
     */
    private static boolean isValidCell(boolean[][] grid, int r, int c) {
        return r >= 0 && r < grid.length && c >= 0 && c < grid[0].length;
    }

    /**
     * Depth First Search to check path existence.
     * 
     * @param grid The grid map
     * @param r Current row
     * @param c Current column
     * @param startR Start row (used to force passability at start)
     * @param startC Start column (used to force passability at start)
     * @param endR Destination row
     * @param endC Destination column
     * @param visited Visited matrix
     */
    private static boolean dfs(boolean[][] grid, int r, int c, int startR, int startC, int endR, int endC, boolean[][] visited) {
        // Boundary check
        if (!isValidCell(grid, r, c)) {
            return false;
        }

        // Visited check
        if (visited[r][c]) {
            return false;
        }

        // Mark current cell as visited
        visited[r][c] = true;

        // Check if we reached the destination
        // This check happens BEFORE checking if the cell is passable.
        // This matches the original logic allowing traversal into an obstacle at the destination.
        if (r == endR && c == endC) {
            return true;
        }

        // Determine if current cell is passable.
        // Original code: mat[sourceRow][sourceCol] = true;
        // This implies the start cell is always passable.
        boolean isPassable = grid[r][c];
        if (r == startR && c == startC) {
            isPassable = true;
        }

        // If not destination and not passable, cannot proceed
        if (!isPassable) {
            return false;
        }

        // Explore neighbors
        return dfs(grid, r - 1, c, startR, startC, endR, endC, visited) ||
               dfs(grid, r + 1, c, startR, startC, endR, endC, visited) ||
               dfs(grid, r, c - 1, startR, startC, endR, endC, visited) ||
               dfs(grid, r, c + 1, startR, startC, endR, endC, visited);
    }

    // FastScanner Utility Class
    static class FastScanner {
        BufferedReader in;
        StringTokenizer st;

        public FastScanner() {
            in = new BufferedReader(new InputStreamReader(System.in));
        }

        public String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = in.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            String s = next();
            return (s == null) ? 0 : Integer.parseInt(s);
        }

        public long nextLong() {
            String s = next();
            return (s == null) ? 0L : Long.parseLong(s);
        }
    }
}

import java.io.*;
import java.util.*;

public class Main {
    // Directions for Up, Down, Left, Right
    private static final int[][] DIRECTIONS = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};

    public static void main(String[] args) {
        FastReader in = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        new GridPathChecker().solve(in, out);

        out.flush(); // Ensure all output is written
    }

    /**
     * Encapsulates the core grid connectivity logic.
     */
    static class GridPathChecker {
        private int n, m;
        private boolean[][] walkable;
        private boolean[][] visited;
        private int startX, startY, targetX, targetY;

        void solve(FastReader in, PrintWriter out) {
            readInput(in);
            markReachableCells();
            checkTargetCondition(out);
        }

        private void readInput(FastReader in) {
            n = in.nextInt();
            m = in.nextInt();

            walkable = new boolean[n][m];
            for (int i = 0; i < n; i++) {
                String row = in.next();
                for (int j = 0; j < m; j++) {
                    walkable[i][j] = row.charAt(j) == '.';
                }
            }

            // Convert 1-based input to 0-based internal indexing
            startX = in.nextInt() - 1;
            startY = in.nextInt() - 1;
            targetX = in.nextInt() - 1;
            targetY = in.nextInt() - 1;
        }

        private void markReachableCells() {
            visited = new boolean[n][m];
            Deque<int[]> stack = new ArrayDeque<>();

            // Only start DFS if the starting position is valid
            if (isValid(startX, startY)) {
                stack.addLast(new int[]{startX, startY});
            }

            while (!stack.isEmpty()) {
                int[] curr = stack.pollLast();
                int x = curr[0];
                int y = curr[1];

                if (visited[x][y]) continue;
                visited[x][y] = true;

                for (int[] dir : DIRECTIONS) {
                    int nx = x + dir[0];
                    int ny = y + dir[1];

                    if (isValid(nx, ny) && walkable[nx][ny] && !visited[nx][ny]) {
                        stack.addLast(new int[]{nx, ny});
                    }
                }
            }
        }

        private boolean isValid(int x, int y) {
            return x >= 0 && x < n && y >= 0 && y < m;
        }

        private int countReachableNeighbors(int x, int y) {
            int count = 0;
            for (int[] dir : DIRECTIONS) {
                int nx = x + dir[0];
                int ny = y + dir[1];
                if (isValid(nx, ny) && visited[nx][ny]) {
                    count++;
                }
            }
            return count;
        }

        private void checkTargetCondition(PrintWriter out) {
            int reachableNeighbors = countReachableNeighbors(targetX, targetY);
            boolean isTargetWalkable = walkable[targetX][targetY];

            // Original logic:
            // If target is blocked, YES if >=1 neighbor is reachable
            // If target is open, YES if >=2 neighbors are reachable
            if (!isTargetWalkable) {
                out.println(reachableNeighbors > 0 ? "YES" : "NO");
            } else {
                out.println(reachableNeighbors >= 2 ? "YES" : "NO");
            }
        }
    }

    /**
     * Fast I/O helper for competitive programming / performance-critical reads.
     */
    static class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastReader(InputStream stream) {
            br = new BufferedReader(new InputStreamReader(stream), 32768);
        }

        public String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Input stream error", e);
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }

        public double nextDouble() {
            return Double.parseDouble(next());
        }
    }
}

import java.util.ArrayDeque;
import java.util.Arrays;
import java.util.Deque;
import java.util.Scanner;

public class Main {
    // Constants for better maintainability and readability
    private static final char WALL = 'X';
    private static final char EMPTY = '.';
    private static final int[][] DIRECTIONS = { {0, 1}, {1, 0}, {0, -1}, {-1, 0} };
    private static final String RESULT_YES = "YES";
    private static final String RESULT_NO = "NO";

    public static void main(String[] args) {
        // Use try-with-resources for automatic resource management
        try (Scanner sc = new Scanner(System.in)) {
            if (!sc.hasNextInt()) return;

            int H = sc.nextInt();
            int W = sc.nextInt();

            char[][] grid = readGrid(sc, H, W);
            int[] start = readCoordinates(sc);
            int[] goal = readCoordinates(sc);

            // Pre-evaluate goal conditions to handle special cases early
            boolean shouldRunBfs = evaluateGoalConditions(grid, start, goal);

            // If pre-evaluation didn't resolve the answer, run BFS
            if (shouldRunBfs) {
                if (bfs(grid, start, goal, H, W)) {
                    System.out.println(RESULT_YES);
                } else {
                    System.out.println(RESULT_NO);
                }
            }
        }
    }

    /**
     * Reads and constructs the padded grid from input.
     */
    private static char[][] readGrid(Scanner sc, int H, int W) {
        char[][] grid = new char[H + 2][];
        grid[0] = new char[W + 2];
        grid[H + 1] = new char[W + 2];
        Arrays.fill(grid[0], WALL);
        Arrays.fill(grid[H + 1], WALL);

        for (int i = 1; i <= H; i++) {
            grid[i] = ("X" + sc.next() + "X").toCharArray();
        }
        return grid;
    }

    /**
     * Reads a pair of coordinates from the scanner.
     */
    private static int[] readCoordinates(Scanner sc) {
        return new int[] { sc.nextInt(), sc.nextInt() };
    }

    /**
     * Evaluates special conditions for the goal cell.
     * Prints the result and returns false if the answer is determined.
     * Returns true if the algorithm should proceed to BFS.
     */
    private static boolean evaluateGoalConditions(char[][] grid, int[] start, int[] goal) {
        int dist = manhattanDistance(start, goal);

        if (grid[goal[0]][goal[1]] == WALL) {
            if (dist == 1) {
                System.out.println(RESULT_YES);
                return false;
            }
            if (countOpenNeighbors(grid, goal[0], goal[1]) == 0) {
                System.out.println(RESULT_NO);
                return false;
            }
        } else {
            int openNeighbors = countOpenNeighbors(grid, goal[0], goal[1]);
            if (dist == 1 && openNeighbors >= 1) {
                System.out.println(RESULT_YES);
                return false;
            }
            if (openNeighbors < 2) {
                System.out.println(RESULT_NO);
                return false;
            }
        }
        return true;
    }

    /**
     * Counts the number of adjacent open cells around a given coordinate.
     */
    private static int countOpenNeighbors(char[][] grid, int r, int c) {
        int count = 0;
        for (int[] dir : DIRECTIONS) {
            if (grid[r + dir[0]][c + dir[1]] == EMPTY) {
                count++;
            }
        }
        return count;
    }

    /**
     * Calculates the Manhattan distance between two points.
     */
    private static int manhattanDistance(int[] a, int[] b) {
        return Math.abs(a[0] - b[0]) + Math.abs(a[1] - b[1]);
    }

    /**
     * Performs Breadth-First Search to find if the goal is reachable.
     */
    private static boolean bfs(char[][] grid, int[] start, int[] goal, int H, int W) {
        int rows = H + 2;
        int cols = W + 2;
        boolean[][] visited = new boolean[rows][cols];
        Deque<Point> queue = new ArrayDeque<>();

        queue.add(new Point(start[0], start[1]));
        visited[start[0]][start[1]] = true;

        while (!queue.isEmpty()) {
            Point current = queue.poll();

            for (int[] dir : DIRECTIONS) {
                int nr = current.r + dir[0];
                int nc = current.c + dir[1];

                // Check if we reached the goal
                if (nr == goal[0] && nc == goal[1]) {
                    return true;
                }
                // Skip walls and already visited cells
                if (grid[nr][nc] == WALL || visited[nr][nc]) {
                    continue;
                }

                visited[nr][nc] = true;
                queue.add(new Point(nr, nc));
            }
        }
        return false;
    }

    /**
     * Lightweight record to represent 2D coordinates.
     * Replaces Integer[] arrays for better readability, type safety, and performance.
     */
    private record Point(int r, int c) {}
}

import java.io.*;
import java.util.*;

/**
 * Solves a grid pathfinding problem with specific conditions.
 * Checks if a path exists from a start point to a target point, considering
 * whether the target was initially blocked and the number of free adjacent cells.
 */
public class Main {
    private static final int[][] DIRECTIONS = {{0, 1}, {0, -1}, {1, 0}, {-1, 0}};

    public static void main(String[] args) {
        FastScanner in = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out));
        try {
            new Main().solve(in, out);
        } finally {
            out.flush();
            out.close();
        }
    }

    /**
     * Orchestrates input reading, grid processing, and pathfinding logic.
     */
    void solve(FastScanner in, PrintWriter out) {
        int rows = in.nextInt();
        int cols = in.nextInt();

        boolean[][] grid = new boolean[rows][cols];
        for (int i = 0; i < rows; i++) {
            String line = in.next();
            for (int j = 0; j < cols; j++) {
                grid[i][j] = line.charAt(j) == '.';
            }
        }

        int startX = in.nextInt() - 1;
        int startY = in.nextInt() - 1;
        int targetX = in.nextInt() - 1;
        int targetY = in.nextInt() - 1;

        // Ensure start and target positions are walkable
        grid[startX][startY] = true;
        boolean targetInitiallyBlocked = !grid[targetX][targetY];
        grid[targetX][targetY] = true;

        // Count free adjacent cells to the target
        int freeAdjacentCount = 0;
        for (int[] dir : DIRECTIONS) {
            int adjX = targetX + dir[0];
            int adjY = targetY + dir[1];
            if (inBounds(adjX, adjY, rows, cols) && grid[adjX][adjY]) {
                freeAdjacentCount++;
            }
        }

        // Handle start == target case separately to preserve original logic
        if (startX == targetX && startY == targetY) {
            out.println(freeAdjacentCount >= 1 ? "YES" : "NO");
        } else {
            boolean[][] visited = new boolean[rows][cols];
            boolean canReach = dfs(startX, startY, targetX, targetY, rows, cols, grid, visited);
            boolean possible = canReach && (targetInitiallyBlocked || freeAdjacentCount > 1);
            out.println(possible ? "YES" : "NO");
        }
    }

    /**
     * Performs depth-first search to find a path from (x, y) to (targetX, targetY).
     * Uses a separate visited array to avoid mutating the original grid state.
     */
    private boolean dfs(int x, int y, int targetX, int targetY, int rows, int cols, 
                        boolean[][] grid, boolean[][] visited) {
        if (!grid[x][y] || visited[x][y]) {
            return false;
        }
        if (x == targetX && y == targetY) {
            return true;
        }

        visited[x][y] = true;
        for (int[] dir : DIRECTIONS) {
            int nextX = x + dir[0];
            int nextY = y + dir[1];
            if (inBounds(nextX, nextY, rows, cols) && grid[nextX][nextY]) {
                if (dfs(nextX, nextY, targetX, targetY, rows, cols, grid, visited)) {
                    return true;
                }
            }
        }
        return false;
    }

    /**
     * Checks if coordinates are within grid boundaries.
     */
    private boolean inBounds(int x, int y, int rows, int cols) {
        return x >= 0 && y >= 0 && x < rows && y < cols;
    }

    /**
     * Fast input reader optimized for competitive programming.
     */
    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) {
                        throw new EOFException("End of input reached unexpectedly");
                    }
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.ArrayDeque;
import java.util.Queue;
import java.util.StringTokenizer;

public class IceCave {

    private int rows, cols;
    private char[][] grid;
    private boolean[][] visited;
    private int startRow, startCol, endRow, endCol;

    private static final int[] DR = {-1, 1, 0, 0};
    private static final int[] DC = {0, 0, -1, 1};

    public static void main(String[] args) {
        IceCave solver = new IceCave();
        solver.solve();
    }

    public void solve() {
        FastScanner scanner = new FastScanner();
        PrintWriter out = new PrintWriter(System.out);

        try {
            rows = scanner.nextInt();
            cols = scanner.nextInt();

            grid = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                String line = scanner.next();
                for (int j = 0; j < cols; j++) {
                    grid[i][j] = line.charAt(j);
                }
            }

            startRow = scanner.nextInt() - 1;
            startCol = scanner.nextInt() - 1;
            endRow = scanner.nextInt() - 1;
            endCol = scanner.nextInt() - 1;

            visited = new boolean[rows][cols];

            // Prepare start position for traversal: ice at start breaks immediately
            if (grid[startRow][startCol] == 'X') {
                grid[startRow][startCol] = '.';
            }

            // Find all reachable empty cells
            bfs(startRow, startCol);

            // Determine and print the result
            out.println(determineResult());
        } finally {
            out.flush();
        }
    }

    private String determineResult() {
        boolean targetVisited = visited[endRow][endCol];
        int adjacentVisitedCount = countAdjacentVisited(endRow, endCol);
        boolean isStartEnd = (startRow == endRow && startCol == endCol);

        if (targetVisited) {
            // Target is reachable and is an empty cell
            if (isStartEnd) {
                // Must step out and come back to a different adjacent cell
                return adjacentVisitedCount >= 1 ? "YES" : "NO";
            }
            return "YES";
        }

        // Target is not visited, so it must be ice ('X')
        // Need at least 2 adjacent visited cells to break the ice and enter safely
        return adjacentVisitedCount >= 2 ? "YES" : "NO";
    }

    private void bfs(int startR, int startC) {
        Queue<int[]> queue = new ArrayDeque<>();
        queue.offer(new int[]{startR, startC});
        visited[startR][startC] = true;

        while (!queue.isEmpty()) {
            int[] current = queue.poll();
            int r = current[0];
            int c = current[1];

            for (int i = 0; i < 4; i++) {
                int nr = r + DR[i];
                int nc = c + DC[i];

                if (isValid(nr, nc) && !visited[nr][nc] && grid[nr][nc] == '.') {
                    visited[nr][nc] = true;
                    queue.offer(new int[]{nr, nc});
                }
            }
        }
    }

    private boolean isValid(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    private int countAdjacentVisited(int r, int c) {
        int count = 0;
        for (int i = 0; i < 4; i++) {
            int nr = r + DR[i];
            int nc = c + DC[i];
            if (isValid(nr, nc) && visited[nr][nc]) {
                count++;
            }
        }
        return count;
    }

    // Efficient input reader
    private static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    e.printStackTrace();
                    return null;
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            String s = next();
            return s == null ? 0 : Integer.parseInt(s);
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayDeque;
import java.util.HashSet;
import java.util.Objects;
import java.util.Queue;
import java.util.Set;
import java.util.StringTokenizer;

public class ProblemC {

    private static final int[][] DIRECTIONS = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};

    public static void main(String[] args) throws IOException {
        FastScanner scanner = new FastScanner();
        ProblemC solver = new ProblemC();
        solver.run(scanner);
    }

    public void run(FastScanner scanner) throws IOException {
        char[][] grid = readGrid(scanner);
        Point start = readPoint(scanner);
        Point end = readPoint(scanner);

        boolean result = determineReachability(grid, start, end);
        System.out.println(result ? "YES" : "NO");
    }

    private char[][] readGrid(FastScanner scanner) throws IOException {
        int n = scanner.nextInt();
        int m = scanner.nextInt();
        char[][] grid = new char[n][];
        for (int i = 0; i < n; i++) {
            grid[i] = scanner.next().toCharArray();
        }
        return grid;
    }

    private Point readPoint(FastScanner scanner) {
        int r = scanner.nextInt() - 1;
        int c = scanner.nextInt() - 1;
        return new Point(r, c);
    }

    private boolean determineReachability(char[][] grid, Point start, Point end) {
        int adjacentDots = countAdjacentDots(grid, end);
        boolean isStartSameAsEnd = start.equals(end);
        boolean isAdjacent = isAdjacent(start, end);

        if (isStartSameAsEnd) {
            return adjacentDots > 0;
        }

        char endChar = grid[end.r][end.c];
        if (endChar == '.' && adjacentDots == 0) {
            return false;
        }
        if (endChar == '.' && adjacentDots == 1) {
            return isAdjacent && grid[start.r][start.c] == 'X';
        }
        if (endChar == 'X' && adjacentDots == 0) {
            return isAdjacent;
        }

        return bfs(grid, start, end);
    }

    private int countAdjacentDots(char[][] grid, Point p) {
        int count = 0;
        for (int[] dir : DIRECTIONS) {
            int nr = p.r + dir[0];
            int nc = p.c + dir[1];
            if (isValid(grid, nr, nc) && grid[nr][nc] == '.') {
                count++;
            }
        }
        return count;
    }

    private boolean isAdjacent(Point p1, Point p2) {
        return (Math.abs(p1.r - p2.r) == 1 && p1.c == p2.c) ||
               (Math.abs(p1.c - p2.c) == 1 && p1.r == p2.r);
    }

    private boolean bfs(char[][] grid, Point start, Point end) {
        Set<Point> visited = new HashSet<>();
        Queue<Point> queue = new ArrayDeque<>();
        queue.add(start);
        visited.add(start);

        while (!queue.isEmpty()) {
            Point current = queue.poll();
            if (current.equals(end)) {
                return true;
            }

            for (int[] dir : DIRECTIONS) {
                Point next = new Point(current.r + dir[0], current.c + dir[1]);
                if (isValid(grid, next.r, next.c)) {
                    char cell = grid[next.r][next.c];
                    if ((cell == '.' || next.equals(end)) && !visited.contains(next)) {
                        visited.add(next);
                        queue.add(next);
                    }
                }
            }
        }
        return false;
    }

    private boolean isValid(char[][] grid, int r, int c) {
        return r >= 0 && r < grid.length && c >= 0 && c < grid[0].length;
    }

    private static class Point {
        final int r, c;

        Point(int r, int c) {
            this.r = r;
            this.c = c;
        }

        @Override
        public boolean equals(Object o) {
            if (this == o) return true;
            if (!(o instanceof Point)) return false;
            Point point = (Point) o;
            return r == point.r && c == point.c;
        }

        @Override
        public int hashCode() {
            return Objects.hash(r, c);
        }
    }

    private static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.util.Scanner;

/**
 * Refactored IceCave solver.
 * 
 * This version improves maintainability and code quality by:
 * 1. Encapsulating state within an instance rather than using static fields.
 * 2. Using descriptive variable names (e.g., 'rows', 'cols', 'iceGrid').
 * 3. Separating input/output logic from the core algorithm.
 * 4. Improving readability and structure of the DFS traversal.
 * 5. Using try-with-resources for proper resource management.
 */
public class IceCave {

    private final int rows;
    private final int cols;
    private boolean[][] iceGrid; // Mutable state to track cracked/walkable cells
    private boolean[][] visited; // Tracks paths that have already been explored and failed
    private final int startR, startC;
    private final int targetR, targetC;

    /**
     * Initializes the solver with grid dimensions, state, and coordinates.
     *
     * @param rows    Number of rows
     * @param cols    Number of columns
     * @param iceGrid The grid state (true if 'X'/'cracked', false if '.')
     * @param startR  Start row (0-indexed)
     * @param startC  Start column (0-indexed)
     * @param targetR Target row (0-indexed)
     * @param targetC Target column (0-indexed)
     */
    public IceCave(int rows, int cols, boolean[][] iceGrid, int startR, int startC, int targetR, int targetC) {
        this.rows = rows;
        this.cols = cols;
        this.iceGrid = iceGrid;
        this.visited = new boolean[rows][cols];
        this.startR = startR;
        this.startC = startC;
        this.targetR = targetR;
        this.targetC = targetC;
    }

    /**
     * Orchestrates the solving process.
     *
     * @return "YES" if the target is reachable/breakable, "NO" otherwise.
     */
    public String solve() {
        // The starting cell is forced to be walkable (not cracked)
        iceGrid[startR][startC] = false;

        if (canReach(startR, startC)) {
            return "YES";
        } else {
            return "NO";
        }
    }

    /**
     * Depth-First Search to determine if the target can be reached.
     *
     * @param r Current row
     * @param c Current column
     * @return true if the target is reachable from (r, c), false otherwise.
     */
    private boolean canReach(int r, int c) {
        // Base Case: Check if we have reached the target coordinates
        if (r == targetR && c == targetC) {
            // If the target cell is a crack ('X'), we assume it's breakable/reachable
            if (iceGrid[r][c]) {
                return true;
            }
            // If the target cell is empty, it must have at least one non-cracked neighbor
            return hasUnbrokenNeighbor(r, c);
        }

        // Boundary checks and state checks
        // Blocked if out of bounds, currently a crack, or already visited in a failed path
        if (r < 0 || r >= rows || c < 0 || c >= cols || iceGrid[r][c] || visited[r][c]) {
            return false;
        }

        // Mark current cell as a temporary crack (acts as a visited marker for the current path)
        // This prevents cycles during traversal.
        iceGrid[r][c] = true;

        // Explore all 4 directions
        // Using a loop for cleaner expansion if directions change
        int[] dr = {-1, 1, 0, 0};
        int[] dc = {0, 0, -1, 1};

        for (int i = 0; i < 4; i++) {
            if (canReach(r + dr[i], c + dc[i])) {
                return true;
            }
        }

        // Backtracking logic
        // If no path was found from this cell:
        // 1. Restore the ice state (unmark as crack) so other paths can potentially pass through.
        // 2. Mark as permanently visited (failed) to avoid re-exploring this dead end.
        if (!canReach(r, c)) { // Note: Logic check above returns false if loop finishes without true
             // Actually, since we returned true inside the loop, if we are here, result is false.
             // But we need to restore state.
             // Wait, the loop returns true immediately. If we exit loop, result is false.
        }

        // Correct Backtracking Logic based on original code flow:
        // The original code used || short-circuiting. If all return false, we are here.

        // Restore state
        iceGrid[r][c] = false;
        visited[r][c] = true;

        return false;
    }

    /**
     * Checks if a cell has at least one neighbor that is not a crack.
     *
     * @param r Row of the cell
     * @param c Column of the cell
     * @return true if a non-cracked neighbor exists, false otherwise.
     */
    private boolean hasUnbrokenNeighbor(int r, int c) {
        int[] dr = {-1, 1, 0, 0};
        int[] dc = {0, 0, -1, 1};

        for (int i = 0; i < 4; i++) {
            int nr = r + dr[i];
            int nc = c + dc[i];

            // Check bounds
            if (nr >= 0 && nr < rows && nc >= 0 && nc < cols) {
                // If neighbor is NOT cracked (walkable), we found a good neighbor
                if (!iceGrid[nr][nc]) {
                    return true;
                }
            }
        }
        return false;
    }

    public static void main(String[] args) {
        // Use try-with-resources to ensure Scanner is closed
        try (Scanner scan = new Scanner(System.in)) {
            if (!scan.hasNextInt()) return;

            int n = scan.nextInt();
            int m = scan.nextInt();

            boolean[][] grid = new boolean[n][m];
            for (int i = 0; i < n; i++) {
                String rowStr = scan.next();
                for (int j = 0; j < m; j++) {
                    // 'X' represents a crack (true), '.' represents empty (false)
                    grid[i][j] = (rowStr.charAt(j) == 'X');
                }
            }

            // Convert 1-based input to 0-based indexing
            int r1 = scan.nextInt() - 1;
            int c1 = scan.nextInt() - 1;
            int r2 = scan.nextInt() - 1;
            int c2 = scan.nextInt() - 1;

            IceCave solver = new IceCave(n, m, grid, r1, c1, r2, c2);
            System.out.println(solver.solve());

        } catch (Exception e) {
            // In a real application, handle or log the exception appropriately
            e.printStackTrace();
        }
    }
}

import java.util.Scanner;
import java.util.ArrayDeque;
import java.util.Deque;

/**
 * Refactored Ice Cave Solver.
 * 
 * Improvements:
 * 1. Removed global static state for better encapsulation.
 * 2. Replaced recursion with Iterative DFS to prevent StackOverflowError.
 * 3. Fixed pathfinding logic (original code had a bug checking if target was 'X').
 * 4. Improved variable naming and removed unused code.
 * 5. Handled Scanner buffer correctly.
 */
public class IceCaveSolver {

    // Direction vectors: Right, Down, Left, Up
    private static final int[] ROW_OFFSETS = {0, 1, 0, -1};
    private static final int[] COL_OFFSETS = {1, 0, -1, 0};

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        // Read grid dimensions
        if (!scanner.hasNextInt()) {
            return;
        }
        int rows = scanner.nextInt();
        int cols = scanner.nextInt();

        // Consume the newline character left after reading integers
        scanner.nextLine();

        // Initialize the grid
        char[][] grid = new char[rows][cols];

        // Read the grid rows
        for (int i = 0; i < rows; i++) {
            String line = scanner.nextLine();
            // Fill the row, handling potential short lines gracefully
            for (int j = 0; j < Math.min(line.length(), cols); j++) {
                grid[i][j] = line.charAt(j);
            }
        }

        // Read start and end coordinates
        // Input is typically 1-based, so we convert to 0-based indexing
        int startRow = scanner.nextInt() - 1;
        int startCol = scanner.nextInt() - 1;
        int endRow = scanner.nextInt() - 1;
        int endCol = scanner.nextInt() - 1;

        // Solve the problem
        boolean reachable = findPath(grid, startRow, startCol, endRow, endCol);

        // Output result
        System.out.println(reachable ? "YES" : "NO");

        scanner.close();
    }

    /**
     * Finds if a path exists from start to end using Iterative DFS.
     */
    private static boolean findPath(char[][] grid, int startR, int startC, int endR, int endC) {
        // Basic validation for start position
        if (!isValid(grid, startR, startC)) {
            return false;
        }

        // If start is the same as end
        if (startR == endR && startC == endC) {
            return true;
        }

        // Visited array to track explored cells
        boolean[][] visited = new boolean[grid.length][grid[0].length];

        // Stack for Iterative DFS
        Deque<int[]> stack = new ArrayDeque<>();

        // Push start position
        stack.push(new int[]{startR, startC});
        visited[startR][startC] = true;

        while (!stack.isEmpty()) {
            int[] current = stack.pop();
            int r = current[0];
            int c = current[1];

            // Explore all 4 directions
            for (int i = 0; i < 4; i++) {
                int nextR = r + ROW_OFFSETS[i];
                int nextC = c + COL_OFFSETS[i];

                // Check if we reached the destination
                if (nextR == endR && nextC == endC) {
                    return true;
                }

                // Check if the neighbor is valid, unvisited, and is a walkable path ('.')
                if (isValid(grid, nextR, nextC) && 
                    !visited[nextR][nextC] && 
                    grid[nextR][nextC] == '.') {

                    visited[nextR][nextC] = true;
                    stack.push(new int[]{nextR, nextC});
                }
            }
        }

        return false;
    }

    /**
     * Checks if coordinates are within the grid boundaries.
     */
    private static boolean isValid(char[][] grid, int r, int c) {
        return r >= 0 && r < grid.length && c >= 0 && c < grid[0].length;
    }
}

import java.io.BufferedReader;
import java.io.EOFException;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.ArrayDeque;
import java.util.Deque;
import java.util.Objects;
import java.util.StringTokenizer;

public class Main {

    public static void main(String[] args) throws IOException {
        FastScanner scanner = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out);

        int n = scanner.nextInt();
        int m = scanner.nextInt();
        char[][] grid = new char[n][m];
        for (int i = 0; i < n; i++) {
            grid[i] = scanner.next().toCharArray();
        }

        // Convert 1-based input to 0-based coordinates
        int r1 = scanner.nextInt() - 1;
        int c1 = scanner.nextInt() - 1;
        int r2 = scanner.nextInt() - 1;
        int c2 = scanner.nextInt() - 1;

        GridSolver solver = new GridSolver(n, m, grid, new Point(r1, c1), new Point(r2, c2));
        out.println(solver.solve());

        out.flush();
        out.close();
    }

    /**
     * Encapsulates all grid logic and state. Eliminates global variables
     * and makes the solver reusable and testable.
     */
    static class GridSolver {
        private final int rows;
        private final int cols;
        private final char[][] grid;
        private final Point start;
        private final Point end;

        // Direction vectors: Right, Left, Down, Up
        private static final int[] DR = {0, 0, 1, -1};
        private static final int[] DC = {1, -1, 0, 0};

        public GridSolver(int rows, int cols, char[][] grid, Point start, Point end) {
            this.rows = rows;
            this.cols = cols;
            this.grid = grid;
            this.start = start;
            this.end = end;
        }

        public String solve() {
            // Case 1: Start and end are the same
            if (start.equals(end)) {
                return isSurrounded(start, 1) ? "YES" : "NO";
            }

            // Case 2: Start and end differ
            boolean endIsBlockedOrSurrounded = (grid[end.row][end.col] == 'X') || isSurrounded(end, 2);
            boolean pathExists = canReach(start, end);

            return (endIsBlockedOrSurrounded && pathExists) ? "YES" : "NO";
        }

        private boolean isValid(int r, int c) {
            return r >= 0 && c >= 0 && r < rows && c < cols;
        }

        /**
         * Checks if a point is surrounded by at least `requiredOpenNeighbors` valid neighbors.
         * Preserves the original rule: if the start point is adjacent and contains 'X',
         * it counts as an open neighbor.
         */
        private boolean isSurrounded(Point p, int requiredOpenNeighbors) {
            int openCount = 0;
            for (int k = 0; k < 4; k++) {
                int nr = p.row + DR[k];
                int nc = p.col + DC[k];
                if (isValid(nr, nc) && grid[nr][nc] == '.') {
                    openCount++;
                }
            }

            // Special rule: adjacent 'X' at start position counts toward the threshold
            for (int k = 0; k < 4; k++) {
                int nr = p.row + DR[k];
                int nc = p.col + DC[k];
                if (nr == start.row && nc == start.col && grid[nr][nc] == 'X') {
                    openCount++;
                    break; // Only count once
                }
            }

            return openCount >= requiredOpenNeighbors;
        }

        /**
         * Iterative DFS to check if a path exists from `from` to `to`.
         * Uses a stack to prevent StackOverflowError on large grids.
         */
        private boolean canReach(Point from, Point to) {
            boolean[][] visited = new boolean[rows][cols];
            Deque<Point> stack = new ArrayDeque<>();

            stack.push(from);
            visited[from.row][from.col] = true;

            while (!stack.isEmpty()) {
                Point curr = stack.pop();
                if (curr.equals(to)) {
                    return true;
                }

                for (int k = 0; k < 4; k++) {
                    int nr = curr.row + DR[k];
                    int nc = curr.col + DC[k];

                    if (isValid(nr, nc) && !visited[nr][nc]) {
                        // Allow moving to the target regardless of 'X', 
                        // or move to any non-'X' cell
                        if (nr == to.row && nc == to.col || grid[nr][nc] != 'X') {
                            visited[nr][nc] = true;
                            stack.push(new Point(nr, nc));
                        }
                    }
                }
            }
            return false;
        }
    }

    /**
     * Immutable value class representing grid coordinates.
     */
    static class Point {
        final int row;
        final int col;

        Point(int row, int col) {
            this.row = row;
            this.col = col;
        }

        @Override
        public boolean equals(Object o) {
            if (this == o) return true;
            if (!(o instanceof Point)) return false;
            Point point = (Point) o;
            return row == point.row && col == point.col;
        }

        @Override
        public int hashCode() {
            return Objects.hash(row, col);
        }
    }

    /**
     * Fast I/O helper class. Replaces java.util.Scanner for better performance
     * while maintaining clean, standard Java practices.
     */
    static class FastScanner {
        private BufferedReader br;
        private StringTokenizer st;

        public FastScanner(InputStream s) {
            br = new BufferedReader(new InputStreamReader(s));
        }

        public String next() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) throw new EOFException();
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        public long nextLong() throws IOException {
            return Long.parseLong(next());
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

/**
 * Refactored solution for the Ice Cave problem.
 * 
 * Improvements made:
 * 1. Class Renaming: Renamed to IceCaveSolver for better descriptive naming.
 * 2. Encapsulation: Moved instance variables to private fields and initialized them cleanly.
 * 3. Constants: Defined direction vectors and grid values as constants to avoid magic numbers.
 * 4. Readability: Renamed variables (e.g., 'A' to 'grid', 'dx'/'dy' to 'DIRECTIONS') for clarity.
 * 5. Structure: Separated input reading, logic execution, and helper methods.
 * 6. Robustness: Improved FastScanner to handle End-of-File (EOF) gracefully.
 * 7. Methods: Extracted neighbor checking logic into helper methods to reduce code duplication.
 */
public class IceCaveSolver {

    // Constants for grid values
    private static final int OPEN = 1;
    private static final int BLOCKED = 0;

    // Direction vectors: Right, Left, Down, Up
    private static final int[][] DIRECTIONS = {
        {0, 1}, {0, -1}, {1, 0}, {-1, 0}
    };

    // State variables
    private int rows;
    private int cols;
    private int[][] grid;
    private boolean[][] visited;

    // Coordinates (0-indexed)
    private int startRow, startCol;
    private int endRow, endCol;

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            IceCaveSolver solver = new IceCaveSolver();
            solver.solve(scanner, out);
        } finally {
            out.flush();
            out.close();
        }
    }

    /**
     * Main entry point for the solution logic.
     */
    public void solve(FastScanner in, PrintWriter out) {
        readInput(in);
        processGame(out);
    }

    /**
     * Reads dimensions, grid, and coordinates from input.
     */
    private void readInput(FastScanner in) {
        this.rows = in.nextInt();
        this.cols = in.nextInt();

        grid = new int[rows][cols];
        for (int i = 0; i < rows; i++) {
            String rowStr = in.next();
            for (int j = 0; j < cols; j++) {
                grid[i][j] = (rowStr.charAt(j) == '.') ? OPEN : BLOCKED;
            }
        }

        // Convert 1-based input coordinates to 0-based
        this.startRow = in.nextInt() - 1;
        this.startCol = in.nextInt() - 1;
        this.endRow = in.nextInt() - 1;
        this.endCol = in.nextInt() - 1;
    }

    /**
     * Executes the core game logic.
     */
    private void processGame(PrintWriter out) {
        // Case 1: Start position is the same as End position
        if (startRow == endRow && startCol == endCol) {
            if (hasOpenNeighbor(endRow, endCol)) {
                out.println("YES");
            } else {
                out.println("NO");
            }
            return;
        }

        // Initialize visited array for pathfinding
        visited = new boolean[rows][cols];
        boolean pathFound = dfs(startRow, startCol);

        if (pathFound) {
            // If destination is already blocked (0), it's considered reachable/broken
            if (grid[endRow][endCol] == BLOCKED) {
                out.println("YES");
            } else {
                // Destination is open (1). 
                // Logic: Can we enter it? (Requires >= 2 valid neighbors based on original logic)
                int validNeighbors = countValidNeighbors(endRow, endCol);
                if (validNeighbors >= 2) {
                    out.println("YES");
                } else {
                    out.println("NO");
                }
            }
        } else {
            out.println("NO");
        }
    }

    /**
     * Depth First Search to find a path to the destination.
     * Modifies the grid to mark visited cells as blocked (0) to prevent cycles.
     */
    private boolean dfs(int r, int c) {
        // Mark current cell as visited and "destroyed" (set to 0)
        grid[r][c] = BLOCKED;
        visited[r][c] = true;

        for (int[] dir : DIRECTIONS) {
            int nr = r + dir[0];
            int nc = c + dir[1];

            if (isValid(nr, nc)) {
                // If we see the destination, we found a path
                if (nr == endRow && nc == endCol) {
                    return true;
                }
                // Only traverse if the neighbor is open (1)
                if (grid[nr][nc] == OPEN) {
                    if (dfs(nr, nc)) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Checks if coordinates are within grid boundaries.
     */
    private boolean isValid(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /**
     * Checks if the given cell has at least one open neighbor.
     */
    private boolean hasOpenNeighbor(int r, int c) {
        for (int[] dir : DIRECTIONS) {
            int nr = r + dir[0];
            int nc = c + dir[1];
            if (isValid(nr, nc) && grid[nr][nc] == OPEN) {
                return true;
            }
        }
        return false;
    }

    /**
     * Counts neighbors that are either part of the visited path or are open cells.
     */
    private int countValidNeighbors(int r, int c) {
        int count = 0;
        for (int[] dir : DIRECTIONS) {
            int nr = r + dir[0];
            int nc = c + dir[1];
            if (isValid(nr, nc)) {
                // A neighbor is valid if it was visited (part of path) or is open
                if (visited[nr][nc] || grid[nr][nc] == OPEN) {
                    count++;
                }
            }
        }
        return count;
    }

    /**
     * FastScanner helper class for efficient input reading.
     */
    static class FastScanner {
        BufferedReader in;
        StringTokenizer st;

        public FastScanner(InputStream in) {
            this.in = new BufferedReader(new InputStreamReader(in));
        }

        public String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = in.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            String s = next();
            if (s == null) throw new RuntimeException("Unexpected End of Input");
            return Integer.parseInt(s);
        }

        public long nextLong() {
            String s = next();
            if (s == null) throw new RuntimeException("Unexpected End of Input");
            return Long.parseLong(s);
        }

        public double nextDouble() {
            String s = next();
            if (s == null) throw new RuntimeException("Unexpected End of Input");
            return Double.parseDouble(s);
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.OutputStream;
import java.io.PrintWriter;
import java.util.LinkedList;
import java.util.Queue;
import java.util.StringTokenizer;

public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);

        TaskC solver = new TaskC();
        solver.solve(in, out);

        out.close();
    }

    static class TaskC {
        // Direction vectors for moving Right, Left, Down, Up
        private static final int[] DR = {0, 0, 1, -1};
        private static final int[] DC = {1, -1, 0, 0};

        public void solve(InputReader in, PrintWriter out) {
            int n = in.nextInt();
            int m = in.nextInt();

            char[][] grid = new char[n][m];
            for (int i = 0; i < n; i++) {
                // Reading grid row. Using next() is generally safer for token-based input 
                // and avoids potential issues with empty lines or whitespace handling 
                // compared to nextLine() in mixed-mode readers, assuming grid rows 
                // do not contain spaces.
                String row = in.next();
                grid[i] = row.toCharArray();
            }

            // Convert 1-based coordinates to 0-based
            int r1 = in.nextInt() - 1;
            int c1 = in.nextInt() - 1;
            int r2 = in.nextInt() - 1;
            int c2 = in.nextInt() - 1;

            boolean result = bfs(grid, n, m, r1, c1, r2, c2);
            out.println(result ? "YES" : "NO");
        }

        private boolean bfs(char[][] grid, int n, int m, int startR, int startC, int targetR, int targetC) {
            // Basic bounds check for start position
            if (startR < 0 || startR >= n || startC < 0 || startC >= m) {
                return false;
            }

            // Visited array to track processed cells. 
            // This replaces the original approach of modifying the grid with 'S'.
            boolean[][] visited = new boolean[n][m];

            // Queue for BFS, storing coordinates as int arrays {row, col}
            Queue<int[]> queue = new LinkedList<>();

            // Add start position
            queue.add(new int[]{startR, startC});
            visited[startR][startC] = true;

            while (!queue.isEmpty()) {
                int[] current = queue.poll();
                int r = current[0];
                int c = current[1];

                // If we reached the target cell
                if (r == targetR && c == targetC) {
                    return checkTargetCondition(grid, n, m, r, c, visited);
                }

                // Explore all 4 adjacent neighbors
                for (int i = 0; i < 4; i++) {
                    int nr = r + DR[i];
                    int nc = c + DC[i];

                    // Check boundaries
                    if (nr >= 0 && nr < n && nc >= 0 && nc < m) {
                        // If neighbor is the target
                        if (nr == targetR && nc == targetC) {
                            // Check if the target satisfies the condition
                            if (checkTargetCondition(grid, n, m, nr, nc, visited)) {
                                return true;
                            }
                            // If condition fails, we do not traverse through the target 
                            // (based on original logic treating 'X' as a terminal state)
                            continue;
                        }

                        // If neighbor is a walkable cell ('.') and not visited
                        if (grid[nr][nc] == '.' && !visited[nr][nc]) {
                            visited[nr][nc] = true;
                            queue.add(new int[]{nr, nc});
                        }
                    }
                }
            }
            return false;
        }

        private boolean checkTargetCondition(char[][] grid, int n, int m, int r, int c, boolean[][] visited) {
            // Original logic checks if the target cell contains 'X'
            if (grid[r][c] != 'X') {
                return false;
            }

            int openNeighbors = 0; // Count of neighbors that are '.'
            int visitedNeighbors = 0; // Count of neighbors that have been visited

            for (int i = 0; i < 4; i++) {
                int nr = r + DR[i];
                int nc = c + DC[i];

                if (nr >= 0 && nr < n && nc >= 0 && nc < m) {
                    // Check for open neighbors ('.')
                    if (grid[nr][nc] == '.') {
                        openNeighbors++;
                    }
                    // Check for visited neighbors
                    // In the original code, visited cells were marked with 'S'.
                    // Here, we use the visited array.
                    if (visited[nr][nc]) {
                        visitedNeighbors++;
                    }
                }
            }

            // Condition: at least 1 open neighbor OR at least 2 visited neighbors
            return openNeighbors >= 1 || visitedNeighbors >= 2;
        }
    }

    static class InputReader {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public InputReader(InputStream inputStream) {
            this.reader = new BufferedReader(new InputStreamReader(inputStream));
            this.tokenizer = new StringTokenizer("");
        }

        public String next() {
            while (!tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) {
                        return null;
                    }
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            String s = next();
            if (s == null) return 0;
            return Integer.parseInt(s);
        }
    }
}

import java.util.ArrayDeque;
import java.util.Deque;
import java.util.Scanner;

/**
 * Validates path existence and neighbor conditions on a 2D grid.
 * Refactored for improved maintainability, readability, and robustness.
 */
public class GridPathValidator {

    // Direction vectors for moving Up, Down, Left, Right
    private static final int[] DX = {0, 0, -1, 1};
    private static final int[] DY = {-1, 1, 0, 0};

    public static void main(String[] args) {
        // Use try-with-resources to automatically close the scanner
        try (Scanner scanner = new Scanner(System.in)) {
            if (!scanner.hasNextInt()) {
                return;
            }

            int rows = scanner.nextInt();
            int cols = scanner.nextInt();
            scanner.nextLine(); // Consume the newline character after the second integer

            char[][] grid = readGrid(scanner, rows, cols);
            int[] startCoords = readCoordinates(scanner);
            int[] endCoords = readCoordinates(scanner);

            // Convert 1-based input coordinates to 0-based indices
            int startR = startCoords[0] - 1;
            int startC = startCoords[1] - 1;
            int endR = endCoords[0] - 1;
            int endC = endCoords[1] - 1;

            if (isPathExists(grid, startR, startC, endR, endC)) {
                if (grid[endR][endC] == 'X') {
                    System.out.println("YES");
                } else {
                    int validNeighborCount = countOpenNeighbors(grid, startR, startC, endR, endC);
                    System.out.println(validNeighborCount > 1 ? "YES" : "NO");
                }
            } else {
                System.out.println("NO");
            }
        }
    }

    /**
     * Reads the grid content from the scanner.
     */
    private static char[][] readGrid(Scanner scanner, int rows, int cols) {
        char[][] grid = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            String line = scanner.nextLine();
            for (int j = 0; j < cols; j++) {
                grid[i][j] = line.charAt(j);
            }
        }
        return grid;
    }

    /**
     * Reads a pair of coordinates from the scanner.
     */
    private static int[] readCoordinates(Scanner scanner) {
        return new int[]{scanner.nextInt(), scanner.nextInt()};
    }

    /**
     * Checks if a valid path exists from start to end using Depth-First Search.
     */
    private static boolean isPathExists(char[][] grid, int startR, int startC, int endR, int endC) {
        int rows = grid.length;
        int cols = grid[0].length;
        boolean[][] visited = new boolean[rows][cols];
        Deque<int[]> stack = new ArrayDeque<>();

        stack.push(new int[]{startR, startC});
        visited[startR][startC] = true;

        while (!stack.isEmpty()) {
            int[] current = stack.pop();
            int r = current[0];
            int c = current[1];

            // Check if destination has been reached
            if (r == endR && c == endC) {
                return true;
            }

            // Explore all 4 adjacent directions
            for (int i = 0; i < 4; i++) {
                int nr = r + DX[i];
                int nc = c + DY[i];

                if (isValidPosition(nr, nc, rows, cols) && !visited[nr][nc] && grid[nr][nc] != 'X') {
                    visited[nr][nc] = true;
                    stack.push(new int[]{nr, nc});
                }
            }
        }
        return false;
    }

    /**
     * Counts adjacent cells that are either empty ('.') or the starting position.
     */
    private static int countOpenNeighbors(char[][] grid, int startR, int startC, int endR, int endC) {
        int count = 0;
        int rows = grid.length;
        int cols = grid[0].length;

        for (int i = 0; i < 4; i++) {
            int nr = endR + DX[i];
            int nc = endC + DY[i];

            if (isValidPosition(nr, nc, rows, cols)) {
                if (grid[nr][nc] == '.' || (nr == startR && nc == startC)) {
                    count++;
                }
            }
        }
        return count;
    }

    /**
     * Checks if a given position is within the grid boundaries.
     */
    private static boolean isValidPosition(int r, int c, int rows, int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }
}

import java.util.Scanner;

/**
 * Refactored version of rnd301_C.
 * 
 * Improvements made:
 * 1.  **Encapsulation:** Moved global static fields into instance variables to improve state management and testability.
 * 2.  **Naming Conventions:** Renamed variables for clarity (e.g., `l` -> `grid`, `vis` -> `visited`, `s` -> `scanner`).
 * 3.  **Indexing:** Switched from 1-based indexing (with padded arrays) to standard 0-based indexing for cleaner logic.
 * 4.  **Bug Fixes:**
 *     - Fixed inconsistent initialization of the `visited` array (was not reset in the first neighbor check).
 *     - Fixed a duplicate DFS call in the original code's right-neighbor check block.
 * 5.  **Code Quality:**
 *     - Used `boolean[][]` for the visited array for semantic clarity.
 *     - Extracted logic into helper methods (`dfs`, `isAdjacentToTargetVisited`, `initializeVisited`).
 *     - Used direction arrays to reduce code duplication in neighbor checks.
 * 6.  **Robustness:** Added bounds checking and input validation.
 */
public class rnd301_C {

    private int rows, cols;
    private char[][] grid;
    private boolean[][] visited;
    private int startR, startC;
    private int targetR, targetC;

    public static void main(String[] args) {
        rnd301_C solver = new rnd301_C();
        solver.run();
    }

    public void run() {
        Scanner scanner = new Scanner(System.in);
        if (!scanner.hasNextInt()) return;

        this.rows = scanner.nextInt();
        this.cols = scanner.nextInt();
        scanner.nextLine(); // Consume the newline after integers

        this.grid = new char[this.rows][this.cols];
        for (int i = 0; i < this.rows; i++) {
            String line = scanner.nextLine();
            for (int j = 0; j < this.cols && j < line.length(); j++) {
                this.grid[i][j] = line.charAt(j);
            }
        }

        // Convert 1-based input coordinates to 0-based
        this.startR = scanner.nextInt() - 1;
        this.startC = scanner.nextInt() - 1;
        this.targetR = scanner.nextInt() - 1;
        this.targetC = scanner.nextInt() - 1;

        solve();
    }

    private void solve() {
        // Case 1: Target is blocked ('X')
        // Logic: Check if we can reach any neighbor of the target.
        if (this.grid[this.targetR][this.targetC] == 'X') {
            initializeVisited();
            dfs(this.startR, this.startC);
            if (isAdjacentToTargetVisited()) {
                System.out.println("YES");
            } else {
                System.out.println("NO");
            }
        } 
        // Case 2: Target is open ('.')
        // Logic: Try blocking each neighbor of the target one by one.
        // If blocking a neighbor still allows reaching the target, output YES.
        else {
            boolean possible = false;
            // Directions: Up, Down, Left, Right
            int[] dr = {-1, 1, 0, 0};
            int[] dc = {0, 0, -1, 1};

            for (int i = 0; i < 4; i++) {
                int nr = this.targetR + dr[i];
                int nc = this.targetC + dc[i];

                // Check bounds
                if (nr >= 0 && nr < this.rows && nc >= 0 && nc < this.cols) {
                    // Original logic: Only consider blocking if the neighbor is currently '.'
                    if (this.grid[nr][nc] == '.') {
                        // Temporarily block the neighbor
                        this.grid[nr][nc] = 'X';

                        // Reset visited array for this new check
                        initializeVisited();
                        dfs(this.startR, this.startC);

                        // Check if target is reachable
                        if (this.visited[this.targetR][this.targetC]) {
                            possible = true;
                        }

                        // Restore neighbor to allow checking other neighbors
                        this.grid[nr][nc] = '.';

                        if (possible) break;
                    }
                }
            }

            if (possible) {
                System.out.println("YES");
            } else {
                System.out.println("NO");
            }
        }
    }

    private void initializeVisited() {
        this.visited = new boolean[this.rows][this.cols];
    }

    private void dfs(int r, int c) {
        this.visited[r][c] = true;

        int[] dr = {-1, 1, 0, 0};
        int[] dc = {0, 0, -1, 1};

        for (int i = 0; i < 4; i++) {
            int nr = r + dr[i];
            int nc = c + dc[i];

            // Bounds check
            if (nr >= 0 && nr < this.rows && nc >= 0 && nc < this.cols) {
                // Check if path is valid ('.') and not yet visited
                if (this.grid[nr][nc] == '.' && !this.visited[nr][nc]) {
                    dfs(nr, nc);
                }
            }
        }
    }

    private boolean isAdjacentToTargetVisited() {
        int[] dr = {-1, 1, 0, 0};
        int[] dc = {0, 0, -1, 1};

        for (int i = 0; i < 4; i++) {
            int nr = this.targetR + dr[i];
            int nc = this.targetC + dc[i];

            if (nr >= 0 && nr < this.rows && nc >= 0 && nc < this.cols) {
                if (this.visited[nr][nc]) {
                    return true;
                }
            }
        }
        return false;
    }
}

import java.io.*;
import java.util.*;

public class D {

    /**
     * Immutable value class representing a grid coordinate.
     */
    private static final class Point {
        final int x;
        final int y;

        Point(int x, int y) {
            this.x = x;
            this.y = y;
        }

        @Override
        public boolean equals(Object o) {
            if (this == o) return true;
            if (!(o instanceof Point)) return false;
            Point point = (Point) o;
            return x == point.x && y == point.y;
        }

        @Override
        public int hashCode() {
            return 31 * x + y;
        }
    }

    /**
     * Simple data class to encapsulate search results without relying on global state.
     */
    private static class PathResult {
        final boolean foundPath;
        final boolean answer;

        PathResult(boolean foundPath, boolean answer) {
            this.foundPath = foundPath;
            this.answer = answer;
        }
    }

    public static void main(String[] args) {
        FastScanner sc = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out));

        try {
            int n = sc.nextInt();
            int m = sc.nextInt();

            int[][] grid = new int[n][m];
            for (int i = 0; i < n; i++) {
                String row = sc.next();
                for (int j = 0; j < m; j++) {
                    grid[i][j] = (row.charAt(j) == '.') ? 0 : 1;
                }
            }

            // Convert 1-based input coordinates to 0-based
            int startR = sc.nextInt() - 1;
            int startC = sc.nextInt() - 1;
            int targetR = sc.nextInt() - 1;
            int targetC = sc.nextInt() - 1;

            PathResult result = solvePath(grid, n, m, startR, startC, targetR, targetC);

            out.println(result.foundPath ? "YES" : "NO");
        } catch (Exception e) {
            // In a production environment, proper logging should be used.
            // For algorithmic contexts, we can safely ignore or handle gracefully.
        } finally {
            out.flush();
        }
    }

    /**
     * Performs an iterative BFS to find a path from start to target.
     * Replaces the original recursive DFS to prevent stack overflow and improve performance.
     */
    private static PathResult solvePath(int[][] grid, int n, int m, int startR, int startC, int targetR, int targetC) {
        boolean[][] visited = new boolean[n][m];
        Queue<Point> queue = new ArrayDeque<>();

        queue.add(new Point(startR, startC));
        visited[startR][startC] = true;

        int[] dr = {-1, 1, 0, 0};
        int[] dc = {0, 0, -1, 1};

        while (!queue.isEmpty()) {
            Point current = queue.poll();

            if (current.x == targetR && current.y == targetC) {
                boolean foundPath = true;
                boolean answer = evaluateConditions(grid, current.x, current.y, startR, startC, targetR, targetC);
                return new PathResult(foundPath, answer);
            }

            for (int i = 0; i < 4; i++) {
                int nx = current.x + dr[i];
                int ny = current.y + dc[i];

                if (nx >= 0 && nx < n && ny >= 0 && ny < m && !visited[nx][ny]) {
                    // Movement allowed to empty cells, or directly to the target regardless of cell type
                    if (grid[nx][ny] == 0 || (nx == targetR && ny == targetC)) {
                        visited[nx][ny] = true;
                        queue.add(new Point(nx, ny));
                    }
                }
            }
        }

        return new PathResult(false, false);
    }

    /**
     * Evaluates the specific game/algorithm conditions at the target cell.
     * Extracted from the search logic to improve separation of concerns.
     */
    private static boolean evaluateConditions(int[][] grid, int x, int y, int startR, int startC, int targetR, int targetC) {
        int emptyNeighbors = 0;
        int[] dr = {-1, 1, 0, 0};
        int[] dc = {0, 0, -1, 1};

        for (int i = 0; i < 4; i++) {
            int nx = x + dr[i];
            int ny = y + dc[i];
            if (nx >= 0 && nx < grid.length && ny >= 0 && ny < grid[0].length && grid[nx][ny] == 0) {
                emptyNeighbors++;
            }
        }

        int startTargetDist = Math.abs(targetR - startR) + Math.abs(targetC - startC);

        if (grid[x][y] == 1 && emptyNeighbors > 0) return true;
        if (grid[x][y] == 0 && emptyNeighbors > 1) return true;
        if (grid[x][y] == 1 && startTargetDist == 1) return true;
        if (startTargetDist == 1 && emptyNeighbors >= 1) return true;

        return false;
    }

    /**
     * Optimized input scanner for competitive programming / fast I/O.
     */
    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) throw new IOException("End of input");
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.ArrayDeque;
import java.util.Queue;
import java.util.StringTokenizer;

public class cf_301_c {
    // Direction vectors for moving down, up, right, left
    private static final int[] DR = {1, -1, 0, 0};
    private static final int[] DC = {0, 0, 1, -1};

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner();
        PrintWriter out = new PrintWriter(System.out);
        try {
            new cf_301_c().solve(scanner, out);
        } finally {
            out.flush();
            out.close();
        }
    }

    public void solve(FastScanner in, PrintWriter out) {
        int n = in.nextInt();
        int m = in.nextInt();
        char[][] grid = new char[n][m];
        for (int i = 0; i < n; i++) {
            grid[i] = in.next().toCharArray();
        }

        int startRow = in.nextInt() - 1;
        int startCol = in.nextInt() - 1;
        int endRow = in.nextInt() - 1;
        int endCol = in.nextInt() - 1;

        // Precompute necessary conditions for cleaner decision logic
        int validNeighbors = countValidNeighbors(grid, endRow, endCol, n, m);
        boolean isAdjacent = isAdjacent(startRow, startCol, endRow, endCol);
        boolean isReachable = canReach(grid, startRow, startCol, endRow, endCol, n, m);

        // Apply problem-specific rules based on precomputed conditions
        if (startRow == endRow && startCol == endCol) {
            out.print(validNeighbors >= 1 ? "YES" : "NO");
        } else if (isAdjacent) {
            out.print(grid[endRow][endCol] == 'X' || validNeighbors >= 1 ? "YES" : "NO");
        } else if (isReachable) {
            out.print(grid[endRow][endCol] == 'X' || validNeighbors >= 2 ? "YES" : "NO");
        } else {
            out.print("NO");
        }
    }

    /**
     * Counts the number of valid adjacent cells containing '.'.
     */
    private int countValidNeighbors(char[][] grid, int r, int c, int n, int m) {
        int count = 0;
        for (int i = 0; i < 4; i++) {
            int nr = r + DR[i];
            int nc = c + DC[i];
            if (nr >= 0 && nr < n && nc >= 0 && nc < m && grid[nr][nc] == '.') {
                count++;
            }
        }
        return count;
    }

    /**
     * Checks if the start position is directly adjacent to the end position.
     */
    private boolean isAdjacent(int r1, int c1, int r2, int c2) {
        for (int i = 0; i < 4; i++) {
            if (r2 + DR[i] == r1 && c2 + DC[i] == c1) {
                return true;
            }
        }
        return false;
    }

    /**
     * Performs BFS to determine if a path exists from start to end through '.' cells.
     * Uses a visited array instead of mutating the input grid for better maintainability.
     */
    private boolean canReach(char[][] grid, int startR, int startC, int endR, int endC, int n, int m) {
        boolean[][] visited = new boolean[n][m];
        Queue<Integer> queue = new ArrayDeque<>();
        queue.offer(startR * m + startC);
        visited[startR][startC] = true;

        while (!queue.isEmpty()) {
            int curr = queue.poll();
            int r = curr / m;
            int c = curr % m;

            for (int i = 0; i < 4; i++) {
                int nr = r + DR[i];
                int nc = c + DC[i];

                // Early exit if destination is reached
                if (nr == endR && nc == endC) {
                    return true;
                }

                // Enqueue valid, unvisited neighbors
                if (nr >= 0 && nr < n && nc >= 0 && nc < m && grid[nr][nc] == '.' && !visited[nr][nc]) {
                    visited[nr][nc] = true;
                    queue.offer(nr * m + nc);
                }
            }
        }
        return false;
    }

    /**
     * Lightweight input scanner for competitive programming environments.
     */
    static class FastScanner {
        private BufferedReader br;
        private StringTokenizer st;

        public FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        public String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.util.ArrayDeque;
import java.util.StringTokenizer;

public class IceCave {

    /** Direction vectors: Down, Up, Right, Left */
    private static final int[][] DIRECTIONS = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};

    public static void main(String[] args) {
        InputReader reader = new InputReader(System.in);

        int rows = reader.nextInt();
        int cols = reader.nextInt();

        char[][] grid = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            grid[i] = reader.next().toCharArray();
        }

        // Convert 1-based input coordinates to 0-based
        int startX = reader.nextInt() - 1;
        int startY = reader.nextInt() - 1;
        int targetX = reader.nextInt() - 1;
        int targetY = reader.nextInt() - 1;

        boolean[][] visited = new boolean[rows][cols];
        boolean isDirectlyReachable = bfs(grid, startX, startY, targetX, targetY, visited);

        // Original second pass: check if target is 'X' and adjacent to a visited cell
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (visited[r][c] && grid[r][c] == '.') {
                    for (int[] dir : DIRECTIONS) {
                        int nr = r + dir[0];
                        int nc = c + dir[1];
                        if (isWithinBounds(nr, nc, rows, cols) 
                                && nr == targetX && nc == targetY 
                                && grid[nr][nc] == 'X') {
                            isDirectlyReachable = true;
                        }
                    }
                }
            }
        }

        int reachableNeighborCount = countReachableNeighbors(targetX, targetY, grid, visited, startX, startY, rows, cols);

        if (grid[targetX][targetY] == 'X') {
            if (reachableNeighborCount >= 1) {
                System.out.println("YES");
                return;
            }
        } else if (isDirectlyReachable) {
            int plainNeighborCount = countPlainNeighbors(targetX, targetY, grid, visited, startX, startY, rows, cols);
            if (plainNeighborCount >= 2) {
                System.out.println("YES");
                return;
            }
        }

        System.out.println("NO");
    }

    /**
     * Performs BFS to find all reachable '.' cells and determines if the target is directly reachable.
     * Coordinates are encoded as (x * cols + y) for efficient queue storage.
     */
    private static boolean bfs(char[][] grid, int startX, int startY, int targetX, int targetY, boolean[][] visited) {
        int rows = grid.length;
        int cols = grid[0].length;
        ArrayDeque<Integer> queue = new ArrayDeque<>();

        queue.add(startX * cols + startY);
        visited[startX][startY] = true;
        boolean isReachable = false;

        while (!queue.isEmpty()) {
            int current = queue.poll();
            int cx = current / cols;
            int cy = current % cols;

            if (cx == targetX && cy == targetY) {
                isReachable = true;
            }

            for (int[] dir : DIRECTIONS) {
                int nx = cx + dir[0];
                int ny = cy + dir[1];
                if (isWithinBounds(nx, ny, rows, cols) && grid[nx][ny] == '.' && !visited[nx][ny]) {
                    queue.add(nx * cols + ny);
                    visited[nx][ny] = true;
                }
            }
        }
        return isReachable;
    }

    private static boolean isWithinBounds(int x, int y, int rows, int cols) {
        return x >= 0 && x < rows && y >= 0 && y < cols;
    }

    private static int countReachableNeighbors(int tx, int ty, char[][] grid, boolean[][] visited, 
                                               int sx, int sy, int rows, int cols) {
        int count = 0;
        for (int[] dir : DIRECTIONS) {
            int nx = tx + dir[0];
            int ny = ty + dir[1];
            if (isWithinBounds(nx, ny, rows, cols)) {
                if (grid[nx][ny] == '.' && visited[nx][ny]) {
                    count++;
                }
                if (nx == sx && ny == sy) {
                    count++;
                }
            }
        }
        return count;
    }

    private static int countPlainNeighbors(int tx, int ty, char[][] grid, boolean[][] visited, 
                                           int sx, int sy, int rows, int cols) {
        int count = 0;
        for (int[] dir : DIRECTIONS) {
            int nx = tx + dir[0];
            int ny = ty + dir[1];
            if (isWithinBounds(nx, ny, rows, cols)) {
                if (grid[nx][ny] == '.') {
                    count++;
                }
                if (nx == sx && ny == sy) {
                    count++;
                }
            }
        }
        return count;
    }

    /**
     * Fast input reader for competitive programming and bulk data ingestion.
     */
    static class InputReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public InputReader(InputStream stream) {
            this.reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) {
                        return null;
                    }
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input stream", e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            String token = next();
            if (token == null) {
                throw new RuntimeException("Unexpected end of input");
            }
            return Integer.parseInt(token);
        }
    }
}

