/**
 * Solves Task C: Determines path connectivity in a grid with obstacles.
 */
class TaskC {
    public void solve(FastScanner in, FastPrinter out) {
        int n = in.nextInt();
        int m = in.nextInt();
        char[][] grid = in.readCharacterFieldTokens(n, m);

        int r1 = in.nextInt() - 1;
        int c1 = in.nextInt() - 1;
        int r2 = in.nextInt() - 1;
        int c2 = in.nextInt() - 1;

        boolean isDestinationX = grid[r2][c2] == 'X';

        // Temporarily mark start and destination as walkable for DSU construction
        grid[r1][c1] = '.';
        grid[r2][c2] = '.';

        DisjointSetUnion dsu = new DisjointSetUnion(n * m);
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] != '.') continue;
                // Union with down neighbor
                if (i + 1 < n && grid[i + 1][j] == '.') {
                    dsu.union(i * m + j, (i + 1) * m + j);
                }
                // Union with right neighbor
                if (j + 1 < m && grid[i][j + 1] == '.') {
                    dsu.union(i * m + j, i * m + j + 1);
                }
            }
        }

        int startNode = r1 * m + c1;
        int endNode = r2 * m + c2;

        // Case 1: Start and end coordinates are identical
        if (r1 == r2 && c1 == c2) {
            int walkableNeighbors = countWalkableNeighbors(r2, c2, n, m, grid);
            out.println(walkableNeighbors >= 1 ? "YES" : "NO");
            return;
        }

        // Case 2: Destination is an obstacle ('X')
        if (isDestinationX) {
            out.println(dsu.find(startNode) == dsu.find(endNode) ? "YES" : "NO");
        } else {
            // Case 3: Destination is walkable; requires connectivity and at least 2 adjacent walkable cells
            int walkableNeighbors = countWalkableNeighbors(r2, c2, n, m, grid);
            out.println(walkableNeighbors >= 2 && dsu.find(startNode) == dsu.find(endNode) ? "YES" : "NO");
        }
    }

    /**
     * Counts the number of adjacent walkable cells (not 'X') for a given coordinate.
     */
    private int countWalkableNeighbors(int r, int c, int n, int m, char[][] grid) {
        int count = 0;
        int[] dr = {-1, 1, 0, 0};
        int[] dc = {0, 0, -1, 1};
        for (int i = 0; i < 4; i++) {
            int nr = r + dr[i];
            int nc = c + dc[i];
            if (nr >= 0 && nr < n && nc >= 0 && nc < m && grid[nr][nc] != 'X') {
                count++;
            }
        }
        return count;
    }
}

/**
 * Fast input scanner using BufferedReader and StringTokenizer for efficient parsing.
 * Uses composition over inheritance for better encapsulation and testability.
 */
class FastScanner {
    private final BufferedReader reader;
    private StringTokenizer tokenizer;

    public FastScanner(InputStream inputStream) {
        this.reader = new BufferedReader(new InputStreamReader(inputStream));
    }

    private String next() {
        while (tokenizer == null || !tokenizer.hasMoreTokens()) {
            try {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            } catch (IOException e) {
                throw new RuntimeException("Failed to read input", e);
            }
        }
        return tokenizer.nextToken();
    }

    public int nextInt() {
        String token = next();
        if (token == null) throw new RuntimeException("Unexpected end of input");
        return Integer.parseInt(token);
    }

    public char[][] readCharacterFieldTokens(int n, int m) {
        char[][] grid = new char[n][];
        for (int i = 0; i < n; i++) {
            String row = next();
            if (row == null || row.length() != m) {
                throw new IllegalArgumentException(
                    "Expected row length " + m + ", got " + (row == null ? "null" : row.length())
                );
            }
            grid[i] = row.toCharArray();
        }
        return grid;
    }
}

/**
 * Fast output printer wrapping PrintWriter.
 */
class FastPrinter extends PrintWriter {
    public FastPrinter(OutputStream outputStream) {
        super(outputStream);
    }
}

/**
 * Disjoint Set Union (DSU) / Union-Find data structure with path compression and union by rank.
 * Provides near-constant time complexity for union and find operations.
 */
class DisjointSetUnion {
    private final int[] parent;
    private final int[] rank;

    public DisjointSetUnion(int size) {
        parent = new int[size];
        rank = new int[size];
        for (int i = 0; i < size; i++) {
            parent[i] = i;
            rank[i] = 0;
        }
    }

    /**
     * Finds the representative of the set containing x with iterative path compression.
     */
    public int find(int x) {
        int root = x;
        while (parent[root] != root) {
            root = parent[root];
        }
        // Path compression
        while (x != root) {
            int next = parent[x];
            parent[x] = root;
            x = next;
        }
        return root;
    }

    /**
     * Unites the sets containing x and y. Returns true if they were in different sets.
     */
    public boolean union(int x, int y) {
        int rootX = find(x);
        int rootY = find(y);
        if (rootX != rootY) {
            if (rank[rootX] > rank[rootY]) {
                parent[rootY] = rootX;
            } else if (rank[rootX] < rank[rootY]) {
                parent[rootX] = rootY;
            } else {
                parent[rootY] = rootX;
                rank[rootX]++;
            }
            return true;
        }
        return false;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

/**
 * Refactored Grid Path Solver.
 * 
 * Improvements made:
 * 1. Encapsulation: Moved static fields to instance fields to allow multiple instances and thread safety.
 * 2. Naming: Renamed cryptic variables (isc, vis, crck, ncrckn) to descriptive names.
 * 3. Structure: Separated input reading, grid parsing, and solving logic into distinct methods.
 * 4. Robustness: Added bounds checking and safer input tokenization.
 * 5. Readability: Extracted neighbor counting logic into a helper method.
 */
public class Main {

    private int rows;
    private int cols;
    private boolean[][] isObstacle;
    private boolean[][] visited;

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter out = new PrintWriter(System.out);

        try {
            // 1. Read Dimensions
            StringTokenizer st = readTokenizer(br);
            if (st == null) return;

            int n = Integer.parseInt(st.nextToken());
            int m = Integer.parseInt(st.nextToken());

            Main solver = new Main(n, m);

            // 2. Read Grid
            solver.readGrid(br);

            // 3. Read Coordinates
            st = readTokenizer(br);
            int startX = Integer.parseInt(st.nextToken()) - 1;
            int startY = Integer.parseInt(st.nextToken()) - 1;

            st = readTokenizer(br);
            int targetX = Integer.parseInt(st.nextToken()) - 1;
            int targetY = Integer.parseInt(st.nextToken()) - 1;

            // 4. Solve
            // Check if a path exists from start to target
            boolean pathExists = solver.canReach(startX, startY, targetX, targetY);

            // Check "crack" condition: Target is an obstacle OR Start equals Target
            boolean targetCracked = solver.isObstacle(targetX, targetY) || (startX == targetX && startY == targetY);

            if (!pathExists) {
                out.println("NO");
            } else if (targetCracked) {
                out.println("YES");
            } else {
                // Count valid neighbors of the target
                int validNeighbors = solver.countValidNeighbors(targetX, targetY, startX, startY);
                if (validNeighbors > 1) {
                    out.println("YES");
                } else {
                    out.println("NO");
                }
            }

        } catch (Exception e) {
            e.printStackTrace();
        } finally {
            out.flush();
        }
    }

    /**
     * Helper to read the next non-empty line and tokenize it.
     */
    private static StringTokenizer readTokenizer(BufferedReader br) throws IOException {
        String line = br.readLine();
        while (line != null && line.trim().isEmpty()) {
            line = br.readLine();
        }
        return line != null ? new StringTokenizer(line) : null;
    }

    public Main(int n, int m) {
        this.rows = n;
        this.cols = m;
        this.isObstacle = new boolean[n][m];
        this.visited = new boolean[n][m];
    }

    private void readGrid(BufferedReader br) throws IOException {
        for (int i = 0; i < rows; i++) {
            String line = br.readLine();
            if (line == null) break;

            // Parse the grid row. 'X' indicates an obstacle.
            int len = Math.min(line.length(), cols);
            for (int j = 0; j < len; j++) {
                if (line.charAt(j) == 'X') {
                    isObstacle[i][j] = true;
                }
            }
        }
    }

    /**
     * Initiates the pathfinding search.
     */
    private boolean canReach(int startX, int startY, int targetX, int targetY) {
        // Reset visited array (though new instance implies fresh array)
        // If this method were called multiple times on the same instance, we would need to clear visited.
        for (boolean[] row : visited) {
            java.util.Arrays.fill(row, false);
        }
        return dfs(startX, startY, targetX, targetY, true);
    }

    /**
     * Depth First Search to find a path.
     * 
     * @param currX Current row index
     * @param currY Current column index
     * @param targetX Target row index
     * @param targetY Target column index
     * @param isStartNode True if the current cell is the starting position
     * @return true if a path is found, false otherwise
     */
    private boolean dfs(int currX, int currY, int targetX, int targetY, boolean isStartNode) {
        // Base Case: Reached Target
        if (currX == targetX && currY == targetY) {
            // Logic from original: must not be the start node (implies we moved at least once)
            // Original: if (x0 == x1 && y0 == y1 && !f) return true;
            if (!isStartNode) return true;
        }

        // Bounds Check
        if (currX < 0 || currX >= rows || currY < 0 || currY >= cols) {
            return false;
        }

        // Visited Check
        if (visited[currX][currY]) {
            return false;
        }

        // Obstacle Check
        // If current cell is obstacle AND it's not the start node, we can't be here.
        if (isObstacle[currX][currY] && !isStartNode) {
            return false;
        }

        // Mark Visited
        visited[currX][currY] = true;

        // Explore Neighbors
        // Order: Up, Left, Down, Right (matching original logic)

        // Up (x-1)
        if (currX > 0) {
            if (dfs(currX - 1, currY, targetX, targetY, false)) return true;
        }
        // Left (y-1)
        if (currY > 0) {
            if (dfs(currX, currY - 1, targetX, targetY, false)) return true;
        }
        // Down (x+1)
        if (currX < rows - 1) {
            if (dfs(currX + 1, currY, targetX, targetY, false)) return true;
        }
        // Right (y+1)
        if (currY < cols - 1) {
            if (dfs(currX, currY + 1, targetX, targetY, false)) return true;
        }

        return false;
    }

    /**
     * Counts neighbors of the target that are either free or the start node.
     */
    private int countValidNeighbors(int targetX, int targetY, int startX, int startY) {
        int count = 0;

        // Up
        if (targetX > 0) {
            if (isValidNeighbor(targetX - 1, targetY, startX, startY)) count++;
        }
        // Down
        if (targetX < rows - 1) {
            if (isValidNeighbor(targetX + 1, targetY, startX, startY)) count++;
        }
        // Left
        if (targetY > 0) {
            if (isValidNeighbor(targetX, targetY - 1, startX, startY)) count++;
        }
        // Right
        if (targetY < cols - 1) {
            if (isValidNeighbor(targetX, targetY + 1, startX, startY)) count++;
        }

        return count;
    }

    /**
     * Checks if a cell is valid for the neighbor count logic.
     * Valid if it is NOT an obstacle OR if it IS the start node.
     */
    private boolean isValidNeighbor(int r, int c, int startX, int startY) {
        boolean isFree = !isObstacle[r][c];
        boolean isStart = (r == startX && c == startY);
        return isFree || isStart;
    }

    /**
     * Safe accessor for isObstacle array.
     */
    private boolean isObstacle(int r, int c) {
        return isObstacle[r][c];
    }
}

import java.io.*;
import java.util.*;

/**
 * Refactored solution for Problem 540C.
 * 
 * Key Improvements:
 * 1. Replaced C-style linked list graph with Java's List-based adjacency list for readability and safety.
 * 2. Eliminated instance variables for algorithm state (dist, prev) to prevent side effects and improve thread-safety.
 * 3. Used implicit grid traversal logic for cleaner graph construction.
 * 4. Replaced direct grid mutation during path reconstruction with a boolean tracking array.
 * 5. Standardized I/O handling, removed unused methods, and applied proper exception handling.
 * 6. Applied Java best practices: Integer.compare, final fields, clear naming, and encapsulation.
 */
public class Problem_540_C {

    private static final int INF = Integer.MAX_VALUE / 2;
    private static final int[] DR = {-1, 0, 1, 0};
    private static final int[] DC = {0, 1, 0, -1};

    public static void main(String[] args) {
        FastScanner in = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out));
        new Problem_540_C().solve(in, out);
        out.flush();
    }

    void solve(FastScanner in, PrintWriter out) {
        int n = in.nextInt();
        int m = in.nextInt();
        char[][] grid = new char[n][];
        for (int i = 0; i < n; i++) {
            grid[i] = in.next().toCharArray();
        }

        int startX = in.nextInt() - 1;
        int startY = in.nextInt() - 1;
        int targetX = in.nextInt() - 1;
        int targetY = in.nextInt() - 1;

        // Build graph where edges represent valid moves
        @SuppressWarnings("unchecked")
        List<Integer>[] adj = buildAdjacency(grid, n, m, targetX, targetY);

        int[] dist = new int[n * m];
        int[] prev = new int[n * m];
        Arrays.fill(dist, INF);
        Arrays.fill(prev, -1);

        dijkstra(adj, toIndex(startX, startY, m), dist, prev);

        int targetIdx = toIndex(targetX, targetY, m);
        if (dist[targetIdx] == INF) {
            out.println("NO");
            return;
        }

        // Identify cells on the shortest path to simulate blocking them
        boolean[] isOnPath = new boolean[n * m];
        int cur = targetIdx;
        int startIdx = toIndex(startX, startY, m);
        while (cur != -1 && cur != startIdx) {
            isOnPath[cur] = true;
            cur = prev[cur];
        }

        // Check if target has any accessible '.' neighbor not on the path
        int validNeighbors = 0;
        for (int i = 0; i < 4; i++) {
            int nx = targetX + DR[i];
            int ny = targetY + DC[i];
            if (isValid(nx, ny, n, m) && grid[nx][ny] == '.' && !isOnPath[toIndex(nx, ny, m)]) {
                validNeighbors++;
            }
        }

        boolean wasTargetBlocked = grid[targetX][targetY] == 'X';
        boolean startDiffersFromTarget = startX != targetX || startY != targetY;

        if (validNeighbors > 0 || (wasTargetBlocked && startDiffersFromTarget)) {
            out.println("YES");
        } else {
            out.println("NO");
        }
    }

    private List<Integer>[] buildAdjacency(char[][] grid, int n, int m, int tx, int ty) {
        @SuppressWarnings("unchecked")
        List<Integer>[] adj = new ArrayList[n * m];
        for (int i = 0; i < adj.length; i++) {
            adj[i] = new ArrayList<>();
        }

        for (int r = 0; r < n; r++) {
            for (int c = 0; c < m; c++) {
                int u = toIndex(r, c, m);
                for (int d = 0; d < 4; d++) {
                    int nr = r + DR[d];
                    int nc = c + DC[d];
                    if (isValid(nr, nc, n, m)) {
                        int v = toIndex(nr, nc, m);
                        // Can move to neighbor if it's not 'X', or if it's the target cell
                        if (grid[nr][nc] != 'X' || (nr == tx && nc == ty)) {
                            adj[u].add(v);
                        }
                    }
                }
            }
        }
        return adj;
    }

    private void dijkstra(List<Integer>[] adj, int source, int[] dist, int[] prev) {
        PriorityQueue<Node> pq = new PriorityQueue<>();
        dist[source] = 0;
        pq.add(new Node(source, 0));

        while (!pq.isEmpty()) {
            Node current = pq.poll();
            int u = current.v;

            // Skip stale entries (lazy deletion)
            if (current.dist > dist[u]) {
                continue;
            }

            for (int v : adj[u]) {
                int newDist = dist[u] + 1;
                if (newDist < dist[v]) {
                    dist[v] = newDist;
                    prev[v] = u;
                    pq.add(new Node(v, newDist));
                }
            }
        }
    }

    private int toIndex(int r, int c, int m) {
        return r * m + c;
    }

    private boolean isValid(int r, int c, int n, int m) {
        return r >= 0 && r < n && c >= 0 && c < m;
    }

    /**
     * Represents a node in the priority queue for Dijkstra's algorithm.
     */
    private static class Node implements Comparable<Node> {
        final int v;
        final int dist;

        Node(int v, int dist) {
            this.v = v;
            this.dist = dist;
        }

        @Override
        public int compareTo(Node other) {
            return Integer.compare(this.dist, other.dist);
        }
    }

    /**
     * Fast input reader for competitive programming / large I/O.
     */
    private static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) throw new EOFException();
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.BufferedReader;
