public class Main {

    public static void main(String[] args) {
        FastReader reader = new FastReader();

        int rows = reader.nextInt();
        int cols = reader.nextInt();

        char[][] grid = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            grid[i] = reader.next().toCharArray();
        }

        // Input coordinates are 1-based; convert to 0-based
        int startR = reader.nextInt() - 1;
        int startC = reader.nextInt() - 1;
        int targetR = reader.nextInt() - 1;
        int targetC = reader.nextInt() - 1;

        GridPathfinder pathfinder = new GridPathfinder(grid, rows, cols, targetR, targetC);
        boolean canReach = pathfinder.canReach(startR, startC);

        System.out.println(canReach ? "YES" : "NO");
    }

    /**
     * Encapsulates grid traversal logic, replacing global static variables with instance state.
     */
    static class GridPathfinder {
        private final char[][] grid;
        private final int rows;
        private final int cols;
        private final int targetR;
        private final int targetC;
        private boolean found;
        private boolean[][] visited;

        public GridPathfinder(char[][] grid, int rows, int cols, int targetR, int targetC) {
            this.grid = grid;
            this.rows = rows;
            this.cols = cols;
            this.targetR = targetR;
            this.targetC = targetC;
            this.visited = new boolean[rows][cols];
        }

        public boolean canReach(int startR, int startC) {
            if (!isValid(startR, startC)) {
                return false;
            }

            char startChar = grid[startR][startC];

            if (startChar == 'X') {
                exploreNeighbors(startR, startC);
            } else {
                int adjacentDotCount = countAdjacentDots(startR, startC);
                if (adjacentDotCount >= 2) {
                    exploreNeighbors(startR, startC);
                } else if (adjacentDotCount == 1) {
                    // Original logic: only check adjacency to target when exactly one '.' neighbor exists
                    if (isAdjacentToTarget(startR, startC)) {
                        found = true;
                    }
                    // Note: Original code does not call DFS here when count == 1
                }
            }

            return found;
        }

        private void exploreNeighbors(int r, int c) {
            for (int[] dir : DIRECTIONS) {
                int nr = r + dir[0];
                int nc = c + dir[1];
                if (isValid(nr, nc)) {
                    dfs(nr, nc);
                    if (found) return; // Early exit optimization
                }
            }
        }

        private int countAdjacentDots(int r, int c) {
            int count = 0;
            for (int[] dir : DIRECTIONS) {
                int nr = r + dir[0];
                int nc = c + dir[1];
                if (isValid(nr, nc) && grid[nr][nc] == '.') {
                    count++;
                }
            }
            return count;
        }

        private boolean isAdjacentToTarget(int r, int c) {
            // Checks if (r,c) is directly above, below, left, or right of the target
            return (r == targetR && Math.abs(c - targetC) == 1) ||
                   (c == targetC && Math.abs(r - targetR) == 1);
        }

        /**
         * Standard DFS with visited tracking and early termination.
         * Note: Original code mutated the grid for visited tracking. This version uses 
         * a dedicated `visited` array, which is safer, cleaner, and avoids side effects.
         */
        private void dfs(int r, int c) {
            if (found) return;
            if (!isValid(r, c) || visited[r][c]) return;

            visited[r][c] = true;

            if (grid[r][c] == 'X') {
                if (r == targetR && c == targetC) {
                    found = true;
                }
                return; // Stop exploring this branch on 'X' unless it's the target
            }

            if (r == targetR && c == targetC) {
                found = true;
                return;
            }

            for (int[] dir : DIRECTIONS) {
                dfs(r + dir[0], c + dir[1]);
                if (found) return;
            }
        }

        private boolean isValid(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }

        private static final int[][] DIRECTIONS = {
            {-1, 0}, {1, 0}, {0, -1}, {0, 1}
        };
    }

    /**
     * Fast I/O helper for competitive programming / large inputs.
     */
    static class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) throw new IOException("End of input stream");
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input", e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        long nextLong() {
            return Long.parseLong(next());
        }

        double nextDouble() {
            return Double.parseDouble(next());
        }

        String nextLine() {
            try {
                return br.readLine();
            } catch (IOException e) {
                throw new RuntimeException("Failed to read line", e);
            }
        }
    }
}

