class TaskC {
    // Direction vectors for moving up, left, right, down
    private static final int[] DR = {-1, 0, 0, 1};
    private static final int[] DC = {0, -1, 1, 0};

    public void solve(int testNumber, InputReader in, PrintWriter out) {
        int rows = in.nextInt();
        int cols = in.nextInt();
        char[][] grid = new char[rows][cols];
        boolean[][] visited = new boolean[rows][cols];

        for (int i = 0; i < rows; i++) {
            grid[i] = in.next().toCharArray();
        }

        int startR = in.nextInt() - 1;
        int startC = in.nextInt() - 1;
        int endR = in.nextInt() - 1;
        int endC = in.nextInt() - 1;

        boolean endReached = bfs(grid, visited, rows, cols, startR, startC, endR, endC);

        if (!endReached) {
            out.println("NO");
        } else if (grid[endR][endC] == 'X') {
            out.println("YES");
        } else {
            int validNeighbors = 0;
            for (int i = 0; i < 4; i++) {
                int nr = endR + DR[i];
                int nc = endC + DC[i];
                if (nr == startR && nc == startC) {
                    validNeighbors++;
                } else if (nr >= 0 && nr < rows && nc >= 0 && nc < cols && grid[nr][nc] == '.') {
                    validNeighbors++;
                }
            }
            out.println(validNeighbors >= 2 ? "YES" : "NO");
        }
    }

    private boolean bfs(char[][] grid, boolean[][] visited, int rows, int cols,
                        int startR, int startC, int endR, int endC) {
        // Use ArrayDeque for better performance than LinkedList
        Queue<int[]> queue = new ArrayDeque<>();
        queue.add(new int[]{startR, startC});

        // Mark start as visited to prevent infinite cycles
        visited[startR][startC] = true;

        while (!queue.isEmpty()) {
            int[] curr = queue.poll();
            int r = curr[0];
            int c = curr[1];

            for (int i = 0; i < 4; i++) {
                int nr = r + DR[i];
                int nc = c + DC[i];

                // Early exit when target is reached
                if (nr == endR && nc == endC) {
                    return true;
                }

                if (isValidCell(grid, visited, rows, cols, nr, nc)) {
                    visited[nr][nc] = true;
                    queue.add(new int[]{nr, nc});
                }
            }
        }
        return false;
    }

    private boolean isValidCell(char[][] grid, boolean[][] visited, int rows, int cols, int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols
                && !visited[r][c]
                && grid[r][c] != 'X';
    }
}

