class GridPathFinder {
    private final int rows, cols;
    private final int[][] grid;
    private final boolean[][] visited;
    private final int startRow, startCol, endRow, endCol;
    private static final int[][] DIRECTIONS = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};

    public GridPathFinder(int rows, int cols, int startRow, int startCol, int endRow, int endCol, int[][] grid) {
        this.rows = rows;
        this.cols = cols;
        this.startRow = startRow;
        this.startCol = startCol;
        this.endRow = endRow;
        this.endCol = endCol;
        this.grid = grid;
        this.visited = new boolean[rows][cols];
    }

    public void traverse() {
        dfs(startRow, startCol);
    }

    private void dfs(int r, int c) {
        visited[r][c] = true;
        for (int[] dir : DIRECTIONS) {
            int nextR = r + dir[0];
            int nextC = c + dir[1];
            if (isSafe(nextR, nextC) && !visited[nextR][nextC]) {
                // Traverse empty cells, or step onto the target cell even if it's an obstacle
                if (grid[nextR][nextC] == 0 || (nextR == endRow && nextC == endCol)) {
                    dfs(nextR, nextC);
                }
            }
        }
    }

    public void solve() {
        if (!visited[endRow][endCol]) {
            System.out.println("NO");
            return;
        }

        int freeNeighbors = countFreeNeighbors(endRow, endCol);
        boolean startEqualsEnd = (startRow == endRow && startCol == endCol);
        boolean startAdjacentToEnd = (Math.abs(startRow - endRow) == 1 && startCol == endCol) ||
                                     (Math.abs(startCol - endCol) == 1 && startRow == endRow);

        if (startEqualsEnd) {
            System.out.println(freeNeighbors >= 1 ? "YES" : "NO");
        } else if (startAdjacentToEnd) {
            if (freeNeighbors >= 1) {
                System.out.println("YES");
            } else if (grid[endRow][endCol] == 1) {
                System.out.println("YES");
            } else {
                System.out.println("NO");
            }
        } else {
            if (freeNeighbors >= 2) {
                System.out.println("YES");
            } else if (grid[endRow][endCol] == 1) {
                System.out.println("YES");
            } else {
                System.out.println("NO");
            }
        }
    }

    private int countFreeNeighbors(int r, int c) {
        int count = 0;
        for (int[] dir : DIRECTIONS) {
            int nextR = r + dir[0];
            int nextC = c + dir[1];
            if (isSafe(nextR, nextC) && grid[nextR][nextC] == 0) {
                count++;
            }
        }
        return count;
    }

    private boolean isSafe(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }
}

