        PrintWriter out = new PrintWriter(System.out);
        try {
            solve(scanner, out);
        } catch (Exception e) {
            // In production, proper logging/error handling would be implemented here
        } finally {
            out.flush();
        }
    }

    /**
     * Encapsulates the core problem-solving logic.
     * Accepts dependencies explicitly instead of relying on instance state.
     */
    private static void solve(FastScanner scanner, PrintWriter out) {
        int n = scanner.nextInt();
        int m = scanner.nextInt();

        char[][] grid = new char[n][m];
        for (int i = 0; i < n; i++) {
            grid[i] = scanner.next().toCharArray();
        }

        int r1 = scanner.nextInt() - 1;
        int c1 = scanner.nextInt() - 1;
        int r2 = scanner.nextInt() - 1;
        int c2 = scanner.nextInt() - 1;

        // Ensure the starting position is walkable
        grid[r1][c1] = '.';

        boolean[][] visited = new boolean[n][m];
        boolean canReach = dfs(grid, visited, r1, c1, r2, c2);

        out.println(canReach ? "YES" : "NO");
    }

    /**
     * Depth-First Search to determine if the target cell is reachable.
     * Returns a boolean instead of mutating a global flag, improving testability.
     * Uses explicit boundary checks instead of padded arrays for clarity.
     */
    private static boolean dfs(char[][] grid, boolean[][] visited, int r, int c, int r2, int c2) {
        // Target reached
        if (r == r2 && c == c2) {
            return true;
        }

        // Boundary validation
        if (r < 0 || r >= grid.length || c < 0 || c >= grid[0].length) {
            return false;
        }

        // Prune: already visited or blocked by unbreakable ice
        if (visited[r][c] || grid[r][c] == 'X') {
            return false;
        }

        visited[r][c] = true;

        // Explore adjacent cells
        for (int i = 0; i < 4; i++) {
            int nr = r + DR[i];
            int nc = c + DC[i];
            if (dfs(grid, visited, nr, nc, r2, c2)) {
                return true;
            }
        }

        return false;
    }

    /**
     * Maintainable, standard-Java I/O utility.
     * Replaces the complex byte-buffer parsing with BufferedReader + StringTokenizer.
     * This drastically improves readability, reduces bug surface area, and aligns
     * with modern Java best practices while retaining competitive programming performance.
     */
    private static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input", e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            String s = next();
            return s == null ? 0 : Integer.parseInt(s);
        }
    }
}

import java.util.ArrayDeque;
import java.util.Queue;
import java.util.Scanner;
import java.io.PrintWriter;

public class GridPathAnalyzer {

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in);
             PrintWriter out = new PrintWriter(System.out)) {

            int rows = scanner.nextInt();
            int cols = scanner.nextInt();

            char[][] grid = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                grid[i] = scanner.next().toCharArray();
            }

            Point source = new Point(scanner.nextInt() - 1, scanner.nextInt() - 1);
            Point sink = new Point(scanner.nextInt() - 1, scanner.nextInt() - 1);

            boolean result = analyzeConnectivity(grid, source, sink);
            out.println(result ? "YES" : "NO");
            out.flush();
        }
    }

    /**
     * Determines if a valid path exists from source to sink based on the problem's constraints.
     */
    private static boolean analyzeConnectivity(char[][] grid, Point source, Point sink) {
        int intactNeighbors = countOpenNeighbors(grid, sink);

        if (source.equals(sink)) {
            return intactNeighbors >= 1;
        }

        if (source.isAdjacent(sink)) {
            if (grid[sink.row][sink.col] == 'X') return true;
            if (intactNeighbors >= 2) return true;
            if (intactNeighbors >= 1 && grid[source.row][source.col] == 'X') return true;
            return false;
        }

        if (findPath(grid, source, sink)) {
            if (grid[sink.row][sink.col] == 'X') return true;
            if (intactNeighbors >= 2) return true;
            return false;
        }

        return false;
    }

    /**
     * Performs BFS to check if a path exists from start to end.
     * Uses a visited array to avoid mutating the input grid.
     */
    private static boolean findPath(char[][] grid, Point start, Point end) {
        int rows = grid.length;
        int cols = grid[0].length;
        boolean[][] visited = new boolean[rows][cols];
        Queue<Point> queue = new ArrayDeque<>();

        queue.add(start);
        visited[start.row][start.col] = true;

        int[] dr = {0, 0, -1, 1};
        int[] dc = {-1, 1, 0, 0};

        while (!queue.isEmpty()) {
            Point current = queue.poll();

            if (current.equals(end)) {
                return true;
            }

            // 'X' cells are obstacles unless they are the starting point
            if (!current.equals(start) && grid[current.row][current.col] == 'X') {
                continue;
            }

            for (int i = 0; i < 4; i++) {
                int nr = current.row + dr[i];
                int nc = current.col + dc[i];

                if (nr >= 0 && nr < rows && nc >= 0 && nc < cols && !visited[nr][nc]) {
                    visited[nr][nc] = true;
                    queue.add(new Point(nr, nc));
                }
            }
        }
        return false;
    }

    /**
     * Counts the number of adjacent '.' (open) cells around a given point.
     */
    private static int countOpenNeighbors(char[][] grid, Point point) {
        int count = 0;
        int rows = grid.length;
        int cols = grid[0].length;
        int[] dr = {-1, 1, 0, 0};
        int[] dc = {0, 0, -1, 1};

        for (int i = 0; i < 4; i++) {
            int nr = point.row + dr[i];
            int nc = point.col + dc[i];

            if (nr >= 0 && nr < rows && nc >= 0 && nc < cols && grid[nr][nc] == '.') {
                count++;
            }
        }
        return count;
    }

    /**
     * Immutable coordinate pair representing a cell in the grid.
     */
    public static class Point {
        final int row;
        final int col;

        public Point(int row, int col) {
            this.row = row;
            this.col = col;
        }

        public boolean equals(Point other) {
            return this.row == other.row && this.col == other.col;
        }

        public boolean isAdjacent(Point other) {
            return Math.abs(this.row - other.row) + Math.abs(this.col - other.col) == 1;
        }
    }
}

import java.util.Scanner;
import java.util.ArrayDeque;
import java.util.Queue;
import java.util.Objects;

/**
 * Refactored solution for the Ice Cave pathfinding problem.
 * 
 * Improvements made:
 * 1. Object-Oriented Design: Encapsulated state (grid, visited, dimensions) and logic
 *    within an instance of the class, removing reliance on static global variables.
 * 2. Removed Dead Code: The unused recursive 'traverse' method and the unused 'avail' 
 *    helper were removed to reduce complexity.
 * 3. Algorithm Correction: The original BFS implementation had a flaw where it checked 
 *    for visited status *after* adding nodes to the queue, potentially leading to 
 *    exponential queue growth. This was corrected to check visited status *before* 
 *    adding to the queue.
 * 4. Data Structures: Replaced 'LinkedList' (used inefficiently as a queue) with 
 *    'ArrayDeque' for better performance.
 * 5. Readability: Renamed cryptic variables (w, h, vx, vy) to descriptive names 
 *    (width, height, queueX, etc.) and used a 'Point' class for coordinate management.
 * 6. Edge Cases: Added handling for the case where Start == Target.
 */
public class IceCave {

    /**
     * Represents a coordinate (x, y) on the grid.
     * x corresponds to the column index, y corresponds to the row index.
     */
    private static class Point {
        final int x;
        final int y;

        Point(int x, int y) {
            this.x = x;
            this.y = y;
        }

        @Override
        public boolean equals(Object o) {
            if (this == o) return true;
            if (!(o instanceof Point)) return false;
            Point point = (Point) o;
            return x == point.x && y == point.y;
        }

        @Override
        public int hashCode() {
            return Objects.hash(x, y);
        }
    }

    private int width;
    private int height;
    private boolean[][] grid; // true = obstacle ('X')
    private boolean[][] visited;
    private int startX, startY, targetX, targetY;

    /**
     * Solves the pathfinding problem using Breadth-First Search (BFS).
     * @return true if a path exists from start to target, false otherwise.
     */
    public boolean solve() {
        // Edge case: If start and target are the same, path exists.
        if (startX == targetX && startY == targetY) {
            return true;
        }

        // Validate start and target positions are within bounds
        if (!isInBounds(startX, startY) || !isInBounds(targetX, targetY)) {
            return false;
        }

        // Heuristic check (preserved from original logic):
        // If the target is an open space but has <= 1 open neighbor, 
        // it is likely unreachable (isolated).
        int openNeighbors = countOpenNeighbors(targetX, targetY);
        if (openNeighbors <= 1 && !grid[targetX][targetY]) {
            return false;
        }

        // BFS Initialization
        Queue<Point> queue = new ArrayDeque<>();
        queue.add(new Point(startX, startY));
        visited[startX][startY] = true;

        // Direction vectors: Right, Left, Down, Up
        // x is column index, y is row index
        int[] dx = {1, -1, 0, 0};
        int[] dy = {0, 0, 1, -1};

        while (!queue.isEmpty()) {
            Point current = queue.poll();

            // Check if we reached the target
            if (current.x == targetX && current.y == targetY) {
                return true;
            }

            // Explore neighbors
            for (int i = 0; i < 4; i++) {
                int nx = current.x + dx[i];
                int ny = current.y + dy[i];

                // If neighbor is valid and not visited, add to queue
                // Note: Checking visited here prevents duplicate entries in the queue
                if (isValid(nx, ny) && !visited[nx][ny]) {
                    visited[nx][ny] = true;
                    queue.add(new Point(nx, ny));
                }
            }
        }

        return false;
    }

    /**
     * Checks if coordinates are within the grid boundaries.
     */
    private boolean isInBounds(int x, int y) {
        return x >= 0 && x < width && y >= 0 && y < height;
    }

    /**
     * Checks if a cell is walkable (in bounds and not an obstacle).
     */
    private boolean isValid(int x, int y) {
        return isInBounds(x, y) && !grid[x][y];
    }

    /**
     * Counts the number of valid (walkable and in bounds) neighbors for a cell.
     */
    private int countOpenNeighbors(int x, int y) {
        int count = 0;
        int[] dx = {1, -1, 0, 0};
        int[] dy = {0, 0, 1, -1};
        for (int i = 0; i < 4; i++) {
            int nx = x + dx[i];
            int ny = y + dy[i];
            if (isValid(nx, ny)) {
                count++;
            }
        }
        return count;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        // Read dimensions
        if (!sc.hasNextInt()) return;
        int h = sc.nextInt(); // height (rows)
        int w = sc.nextInt(); // width (cols)

        IceCave solver = new IceCave();
        solver.width = w;
        solver.height = h;

        // Initialize grid. 
        // Using grid[row][col] convention (h rows, w cols) for standard Java 2D array usage.
        solver.grid = new boolean[h][w];
        solver.visited = new boolean[h][w];

        // Read grid data
        for (int y = 0; y < h; y++) {
            String rowStr = sc.next();
            for (int x = 0; x < w; x++) {
                if (rowStr.charAt(x) == 'X') {
                    solver.grid[y][x] = true;
                }
            }
        }

        // Read coordinates
        // Input format: sy sx ty tx
        // sy (start row), sx (start col)
        // ty (target row), tx (target col)
        // Adjusting to 0-based index
        if (sc.hasNextInt()) solver.startY = sc.nextInt() - 1;
        if (sc.hasNextInt()) solver.startX = sc.nextInt() - 1;
        if (sc.hasNextInt()) solver.targetY = sc.nextInt() - 1;
        if (sc.hasNextInt()) solver.targetX = sc.nextInt() - 1;

        // Solve and print result
        if (solver.solve()) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }

        sc.close();
    }
}

import java.util.*;

/**
 * Refactored Grid Path Solver.
 * 
 * Improvements made:
 * 1. Readability: Renamed variables (e.g., 'field' -> 'grid', 'way' -> 'distances') and class.
 * 2. Structure: Separated logic into 'main' and 'solveGrid' methods.
 * 3. Data Structures: Replaced ArrayList-based queues with ArrayDeque for O(1) removal.
 * 4. Algorithm: Implemented standard BFS with a Point helper class.
 * 5. Robustness: Used Integer.MAX_VALUE for initialization and cleaner bounds checking.
 */
public class Main {

    // Helper class to store coordinates
    static class Point {
        int r, c;

        Point(int r, int c) {
            this.r = r;
            this.c = c;
        }
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        // Read dimensions
        if (!scanner.hasNextInt()) return;
        int n = scanner.nextInt();
        int m = scanner.nextInt();
        scanner.nextLine(); // Consume the newline after integers

        // Read grid
        char[][] grid = new char[n][m];
        for (int i = 0; i < n; i++) {
            String line = scanner.nextLine();
            grid[i] = line.toCharArray();
        }

        // Read start and end coordinates (converting 1-based input to 0-based)
        int startRow = scanner.nextInt() - 1;
        int startCol = scanner.nextInt() - 1;
        int endRow = scanner.nextInt() - 1;
        int endCol = scanner.nextInt() - 1;

        // Solve and print result
        System.out.println(solveGrid(n, m, grid, startRow, startCol, endRow, endCol));
    }

    private static String solveGrid(int n, int m, char[][] grid, 
                                    int startRow, int startCol, 
                                    int endRow, int endCol) {

        // Distance matrix initialized to a large value
        int[][] distances = new int[n][m];
        for (int[] row : distances) {
            Arrays.fill(row, Integer.MAX_VALUE);
        }

        // BFS Queue
        Queue<Point> queue = new ArrayDeque<>();

        // Start position
        queue.add(new Point(startRow, startCol));
        distances[startRow][startCol] = 0;

        boolean found = false;
        int targetDistance = -1;

        // Direction vectors: Up, Down, Left, Right
        int[] dr = {-1, 1, 0, 0};
        int[] dc = {0, 0, -1, 1};

        while (!queue.isEmpty()) {
            Point current = queue.poll();

            // Check if we reached the target
            if (current.r == endRow && current.c == endCol) {
                found = true;
                targetDistance = distances[current.r][current.c];
                break; // BFS guarantees shortest path found first
            }

            // Explore neighbors
            for (int i = 0; i < 4; i++) {
                int nr = current.r + dr[i];
                int nc = current.c + dc[i];

                // Check boundaries
                if (nr < 0 || nr >= n || nc < 0 || nc >= m) {
                    continue;
                }

                // Determine if we can move to this neighbor
                // Logic derived from original code:
                // 1. If it's the target cell (allowed even if 'X')
                // 2. If it's a path cell '.' AND not visited yet (distance > current + 1)

                boolean isTarget = (nr == endRow && nc == endCol);
                boolean isPath = (grid[nr][nc] == '.');
                boolean unvisited = (distances[nr][nc] > distances[current.r][current.c] + 1);

                if (isTarget || (isPath && unvisited)) {
                    distances[nr][nc] = distances[current.r][current.c] + 1;
                    queue.add(new Point(nr, nc));
                }
            }
        }

        if (!found) {
            return "NO";
        }

        // Calculate number of valid exits from the target cell
        // A valid exit is a neighbor that contains '.'
        int validExits = 0;
        for (int i = 0; i < 4; i++) {
            int nr = endRow + dr[i];
            int nc = endCol + dc[i];

            if (nr >= 0 && nr < n && nc >= 0 && nc < m) {
                if (grid[nr][nc] == '.') {
                    validExits++;
                }
            }
        }

        // Apply the specific business logic from the original code
        if (grid[endRow][endCol] == 'X') {
            // If target is 'X'
            if (validExits == 0 && startRow == endRow && startCol == endCol) {
                return "NO";
            } else {
                return "YES";
            }
        } else {
            // If target is '.'
            if (targetDistance == 1 && validExits != 0) {
                return "YES";
            } else if (validExits <= 1) {
                return "NO";
            } else {
                return "YES";
            }
        }
    }
}

import java.io.*;
import java.util.*;

public class GridPathSolver {
    // Direction vectors for moving up, down, left, right
    private static final int[] DR = {-1, 1, 0, 0};
    private static final int[] DC = {0, 0, -1, 1};
    private static final char EMPTY_CELL = '.';

    private InputReader in;
    private OutputWriter out;

    /**
     * Entry point for solving the problem.
     * Reads input, processes the grid, and outputs the result.
     */
    public void solve() throws IOException {
        in = new InputReader("__std");
        out = new OutputWriter("__std");

        int rows = in.readInt();
        int cols = in.readInt();
        char[][] grid = new char[rows][];
        for (int i = 0; i < rows; i++) {
            grid[i] = in.readToken().toCharArray();
        }

        // Convert 1-based coordinates to 0-based
        int startR = in.readInt() - 1;
        int startC = in.readInt() - 1;
        int endR = in.readInt() - 1;
        int endC = in.readInt() - 1;

        boolean canReach = evaluatePath(grid, rows, cols, startR, startC, endR, endC);
        out.println(canReach ? "YES" : "NO");

        out.close();
        System.exit(0);
    }

    /**
     * Evaluates whether a valid path exists from start to end based on the problem rules.
     */
    private boolean evaluatePath(char[][] grid, int rows, int cols, int startR, int startC, int endR, int endC) {
        // Special condition: If the destination is an empty cell, it must satisfy adjacency rules
        if (grid[endR][endC] == EMPTY_CELL) {
            int adjacentEmptyCount = countAdjacentEmptyCells(grid, endR, endC, rows, cols);
            boolean isAdjacentToStart = Math.abs(startR - endR) + Math.abs(startC - endC) == 1;

            // If the condition isn't met, the path is invalid regardless of reachability
            if (!(adjacentEmptyCount > 1 || (adjacentEmptyCount == 1 && isAdjacentToStart))) {
                return false;
            }
        }

        // Perform BFS to check connectivity from start to end
        return performBFS(grid, rows, cols, startR, startC, endR, endC);
    }

    /**
     * Counts the number of adjacent empty cells around a given position.
     */
    private int countAdjacentEmptyCells(char[][] grid, int r, int c, int rows, int cols) {
        int count = 0;
        for (int i = 0; i < 4; i++) {
            int nr = r + DR[i];
            int nc = c + DC[i];
            if (isWithinBounds(nr, nc, rows, cols) && grid[nr][nc] == EMPTY_CELL) {
                count++;
            }
        }
        return count;
    }

    /**
     * Checks if coordinates are within the grid boundaries.
     */
    private boolean isWithinBounds(int r, int c, int rows, int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /**
     * Performs a Breadth-First Search to determine if the destination is reachable
     * from the start position via empty cells.
     */
    private boolean performBFS(char[][] grid, int rows, int cols, int startR, int startC, int endR, int endC) {
        boolean[][] visited = new boolean[rows][cols];
        Queue<Integer> qR = new ArrayDeque<>();
        Queue<Integer> qC = new ArrayDeque<>();

        qR.offer(startR);
        qC.offer(startC);
        visited[startR][startC] = true;

        while (!qR.isEmpty()) {
            int r = qR.poll();
            int c = qC.poll();

            // Early exit if destination is reached
            if (r == endR && c == endC) {
                return true;
            }

            for (int i = 0; i < 4; i++) {
                int nr = r + DR[i];
                int nc = c + DC[i];

                if (isWithinBounds(nr, nc, rows, cols) && !visited[nr][nc] && grid[nr][nc] == EMPTY_CELL) {
                    visited[nr][nc] = true;
                    qR.offer(nr);
                    qC.offer(nc);
                }
            }
        }
        return false;
    }

    /**
     * Fast input reader for competitive programming style I/O.
     */
    static class InputReader {
        private final InputStream stream;
        private final byte[] buffer = new byte[1024];
        private int pos, len;
        private int cur;

        public InputReader(InputStream stream) {
            this.stream = stream;
            this.cur = read();
        }

        public InputReader(String name) throws IOException {
            this(name.equals("__std") ? System.in : new FileInputStream(name));
        }

        private int read() throws IOException {
            if (len == -1) {
                return -1;
            }
            if (pos >= len) {
                pos = 0;
                len = stream.read(buffer);
                if (len == -1) {
                    return -1;
                }
            }
            return buffer[pos++];
        }

        private boolean isWhitespace(int ch) {
            return ch == ' ' || ch == '\t' || ch == '\r' || ch == '\n' || ch == -1;
        }

        public char readChar() throws IOException {
            if (cur == -1) throw new EOFException("Unexpected end of input");
            char res = (char) cur;
            cur = read();
            return res;
        }

        public int readInt() throws IOException {
            if (cur == -1) throw new EOFException("Unexpected end of input");
            while (isWhitespace(cur)) cur = read();
            if (cur == -1) throw new EOFException("Unexpected end of input");

            int sign = 1;
            if (cur == '-') {
                sign = -1;
                cur = read();
            }
            int res = 0;
            while (!isWhitespace(cur)) {
                if (cur < '0' || cur > '9') throw new NumberFormatException("Invalid integer format");
                res = res * 10 + (cur - '0');
                cur = read();
            }
            return res * sign;
        }

        public long readLong() throws IOException {
            return Long.parseLong(readToken());
        }

        public double readDouble() throws IOException {
            return Double.parseDouble(readToken());
        }

        public String readLine() throws IOException {
            if (cur == -1) throw new EOFException("Unexpected end of input");
            StringBuilder sb = new StringBuilder(32);
            while (cur != -1 && cur != '\r' && cur != '\n') {
                sb.append((char) cur);
                cur = read();
            }
            if (cur == '\r') cur = read();
            if (cur == '\n') cur = read();
            return sb.toString();
        }

        public String readToken() throws IOException {
            if (cur == -1) throw new EOFException("Unexpected end of input");
            while (isWhitespace(cur)) cur = read();
            if (cur == -1) throw new EOFException("Unexpected end of input");

            StringBuilder sb = new StringBuilder(32);
            while (!isWhitespace(cur)) {
                sb.append((char) cur);
                cur = read();
            }
            return sb.toString();
        }

        public boolean eof() {
            return cur == -1;
        }
    }

    /**
     * Fast output writer for competitive programming style I/O.
     */
    static class OutputWriter {
        private final PrintWriter writer;

        public OutputWriter(OutputStream stream) {
            this.writer = new PrintWriter(stream);
        }

        public OutputWriter(String name) throws IOException {
            this(name.equals("__std") ? System.out : new FileOutputStream(name));
        }

        public void print(String format, Object... args) {
            writer.print(String.format(Locale.US, format, args));
        }

        public void println(String format, Object... args) {
            writer.println(String.format(Locale.US, format, args));
        }

        public void print(Object value) {
            writer.print(value);
        }

        public void println(Object value) {
            writer.println(value);
        }

        public void println() {
            writer.println();
        }

        public void flush() {
            writer.flush();
        }

        public void close() {
            writer.flush();
            writer.close();
        }
    }

    public static void main(String[] args) throws IOException {
        new GridPathSolver().solve();
    }
}

import java.util.ArrayDeque;
import java.util.Queue;
import java.util.Scanner;

public class Solution2 {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        if (!scanner.hasNextInt()) return;

        int rows = scanner.nextInt();
        int cols = scanner.nextInt();

        boolean[][] grid = new boolean[rows][cols];
        for (int i = 0; i < rows; i++) {
            String line = scanner.next();
            for (int j = 0; j < cols; j++) {
                grid[i][j] = (line.charAt(j) == '.');
            }
        }

        // Convert 1-based input coordinates to 0-based for internal processing
        int startR = scanner.nextInt() - 1;
        int startC = scanner.nextInt() - 1;
        int endR = scanner.nextInt() - 1;
        int endC = scanner.nextInt() - 1;

        PathFinder solver = new PathFinder(rows, cols, grid);
        boolean canReach = solver.canReach(startR, startC, endR, endC);

        System.out.println(canReach ? "YES" : "NO");
        scanner.close();
    }

    /**
     * Encapsulates grid traversal logic to eliminate global state and improve testability.
     */
    private static class PathFinder {
        private final int rows;
        private final int cols;
        private final boolean[][] grid;

        public PathFinder(int rows, int cols, boolean[][] grid) {
            this.rows = rows;
            this.cols = cols;
            this.grid = grid;
        }

        public boolean canReach(int startR, int startC, int endR, int endC) {
            if (!isValid(startR, startC) || !isValid(endR, endC)) {
                return false;
            }

            // Validate initial reachability conditions
            if (!meetsReachabilityCondition(startR, startC, endR, endC)) {
                return false;
            }

            // Handle trivial case where start and end are the same
            if (startR == endR && startC == endC) {
                return true;
            }

            // Standard BFS implementation
            boolean[][] visited = new boolean[rows][cols];
            Queue<int[]> queue = new ArrayDeque<>();

            queue.offer(new int[]{startR, startC});
            visited[startR][startC] = true;

            int[] dr = {-1, 0, 1, 0};
            int[] dc = {0, 1, 0, -1};

            while (!queue.isEmpty()) {
                int[] curr = queue.poll();
                int r = curr[0];
                int c = curr[1];

                // Check if we are adjacent to the target
                if (isAdjacentToTarget(r, c, endR, endC)) {
                    return true;
                }

                for (int i = 0; i < 4; i++) {
                    int nr = r + dr[i];
                    int nc = c + dc[i];

                    if (isValid(nr, nc) && grid[nr][nc] && !visited[nr][nc]) {
                        visited[nr][nc] = true;
                        queue.offer(new int[]{nr, nc});
                    }
                }
            }
            return false;
        }

        private boolean isValid(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }

        private boolean isAdjacentToTarget(int r, int c, int endR, int endC) {
            return (r == endR && Math.abs(c - endC) == 1) ||
                   (c == endC && Math.abs(r - endR) == 1);
        }

        /**
         * Replicates the original 'firstCheck' logic with clearer naming and structure.
         * Determines if the target cell meets the required "gate" conditions based on
         * its open neighbors and relationship to the start position.
         */
        private boolean meetsReachabilityCondition(int startR, int startC, int endR, int endC) {
            boolean sideBySide = isAdjacentToTarget(startR, startC, endR, endC);
            int reqGate;

            if (sideBySide) {
                reqGate = grid[endR][endC] ? 1 : 0;
            } else if (startR == endR && startC == endC) {
                reqGate = 1;
            } else {
                reqGate = grid[endR][endC] ? 2 : 1;
            }

            int gate = 0;
            if (isValid(endR - 1, endC) && grid[endR - 1][endC]) gate++;
            if (isValid(endR, endC - 1) && grid[endR][endC - 1]) gate++;
            if (isValid(endR + 1, endC) && grid[endR + 1][endC]) gate++;
            if (isValid(endR, endC + 1) && grid[endR][endC + 1]) gate++;

            return gate >= reqGate;
        }
    }
}

import java.util.Scanner;
import java.util.ArrayDeque;
import java.util.Deque;

/**
 * Solves a pathfinding problem on a 2D grid.
 * Determines if a valid path exists from a starting coordinate to an ending coordinate
 * by moving only through '.' cells.
 * 
 * Refactoring Highlights:
 * - Removed unused inner class (Status) and unnecessary fields (steps, isDebugging).
 * - Replaced Integer[] coordinates with a lightweight record (Point).
 * - Encapsulated state; grid and coordinates are now private final fields.
 * - Fixed the DFS algorithm: uses a dedicated visited matrix instead of mutating the grid.
 * - Eliminated magic numbers by using direction vectors and proper bounds checking.
 * - Replaced LinkedList with ArrayDeque for better stack performance.
 * - Improved input parsing and added validation for robustness.
 * - Removed scattered debug prints for cleaner execution.
 */
public class Ice {

    /** Represents a 2D coordinate using row and column indices. */
    private record Point(int row, int col) {}

    private final char[][] grid;
    private final int rows;
    private final int cols;
    private final Point start;
    private final Point end;

    // Direction vectors: Up, Right, Down, Left
    private static final int[] DR = {-1, 0, 1, 0};
    private static final int[] DC = {0, 1, 0, -1};

    /**
     * Constructs the pathfinder with the given grid and coordinates.
     * Coordinates are expected to be 0-indexed.
     */
    public Ice(char[][] grid, Point start, Point end) {
        if (grid == null || grid.length == 0) {
            throw new IllegalArgumentException("Grid cannot be null or empty.");
        }
        this.grid = grid;
        this.rows = grid.length;
        this.cols = grid[0].length;
        this.start = start;
        this.end = end;
        validateCoordinates(start, end);
    }

    private void validateCoordinates(Point s, Point e) {
        if (!isValid(s.row(), s.col()) || !isValid(e.row(), e.col())) {
            throw new IllegalArgumentException("Start or end coordinates are out of bounds.");
        }
    }

    /** Checks if a coordinate is within grid boundaries. */
    private boolean isValid(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /** Checks if a cell is walkable. */
    private boolean isWalkable(int r, int c) {
        return grid[r][c] == '.';
    }

    /** Checks if a Point coordinate is walkable. */
    private boolean isWalkable(Point p) {
        return isWalkable(p.row(), p.col());
    }

    /**
     * Performs a Depth-First Search to determine if a path exists from start to end.
     * @return true if a path exists, false otherwise.
     */
    public boolean hasPath() {
        // Path is impossible if start or end is not a walkable cell
        if (!isWalkable(start) || !isWalkable(end)) {
            return false;
        }

        boolean[][] visited = new boolean[rows][cols];
        Deque<Point> stack = new ArrayDeque<>();

        stack.push(start);
        visited[start.row()][start.col()] = true;

        while (!stack.isEmpty()) {
            Point current = stack.pop();

            // Target reached
            if (current.row() == end.row() && current.col() == end.col()) {
                return true;
            }

            // Explore neighbors
            for (int i = 0; i < 4; i++) {
                int nr = current.row() + DR[i];
                int nc = current.col() + DC[i];

                if (isValid(nr, nc) && !visited[nr][nc] && isWalkable(nr, nc)) {
                    visited[nr][nc] = true;
                    stack.push(new Point(nr, nc));
                }
            }
        }
        return false;
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        // Read grid dimensions
        if (!scanner.hasNextInt()) {
            return;
        }
        int rows = scanner.nextInt();
        int cols = scanner.nextInt();

        char[][] grid = new char[rows][];
        for (int i = 0; i < rows; i++) {
            grid[i] = scanner.next().toCharArray();
        }

        // Read coordinates (convert from 1-based to 0-based)
        int startR = scanner.nextInt() - 1;
        int startC = scanner.nextInt() - 1;
        int endR = scanner.nextInt() - 1;
        int endC = scanner.nextInt() - 1;

        Ice pathfinder = new Ice(grid, new Point(startR, startC), new Point(endR, endC));
        System.out.println(pathfinder.hasPath() ? "YES" : "NO");

        scanner.close();
    }
}

import java.util.Scanner;
import java.util.ArrayDeque;
import java.util.Deque;

public class Solution {

    // Direction vectors for moving Up, Down, Left, Right
    private static final int[] DR = {-1, 1, 0, 0};
    private static final int[] DC = {0, 0, -1, 1};

    /**
     * Helper class to represent a coordinate in the grid.
     */
    private static class Point {
        int r, c;

        Point(int r, int c) {
            this.r = r;
            this.c = c;
        }
    }

    /**
     * Checks if the given coordinates are within the grid boundaries.
     */
    private static boolean isValid(int r, int c, int rows, int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /**
     * Counts the number of solid (non-'X') neighbors for a given cell.
     * Replaces the confusing loop logic from the original code.
     */
    private static int countSolidNeighbors(char[][] map, int r, int c) {
        int count = 0;
        int rows = map.length;
        int cols = map[0].length;

        for (int i = 0; i < 4; i++) {
            int nr = r + DR[i];
            int nc = c + DC[i];

            if (isValid(nr, nc, rows, cols) && map[nr][nc] != 'X') {
                count++;
            }
        }
        return count;
    }

    /**
     * Performs a Depth First Search (DFS) to check if a path exists from (r1, c1) to (r2, c2).
     * Uses ArrayDeque instead of the legacy Stack class for better performance.
     * Uses a boolean array for visited tracking instead of a HashSet for efficiency.
     */
    private static boolean hasPath(char[][] map, int r1, int c1, int r2, int c2) {
        // If start and end are adjacent, a path exists (direct step)
        if (Math.abs(r1 - r2) + Math.abs(c1 - c2) == 1) {
            return true;
        }

        int rows = map.length;
        int cols = map[0].length;

        // Visited array to keep track of processed cells
        boolean[][] visited = new boolean[rows][cols];
        Deque<Point> stack = new ArrayDeque<>();

        stack.push(new Point(r1, c1));
        visited[r1][c1] = true;

        while (!stack.isEmpty()) {
            Point current = stack.pop();

            // Explore all 4 directions
            for (int i = 0; i < 4; i++) {
                int nr = current.r + DR[i];
                int nc = current.c + DC[i];

                // Check if neighbor is the target
                // Note: We check target status before checking if it's an obstacle ('X')
                // to match the original logic behavior.
                if (nr == r2 && nc == c2) {
                    return true;
                }

                // Check bounds, if not 'X', and if not visited
                if (isValid(nr, nc, rows, cols) && map[nr][nc] != 'X' && !visited[nr][nc]) {
                    visited[nr][nc] = true;
                    stack.push(new Point(nr, nc));
                }
            }
        }
        return false;
    }

    /**
     * Main logic to determine if the move is valid based on grid rules.
     * Preserves the original logic flow but improves readability.
     */
    public static boolean solve(char[][] map, int r1, int c1, int r2, int c2) {
        // Condition 1: Start and End are the same, and the cell has solid neighbors
        if (r1 == r2 && c1 == c2 && countSolidNeighbors(map, r1, c1) > 0) {
            return true;
        }

        // Condition 2: Adjacent to target, and target is an obstacle ('X')
        if (Math.abs(r1 - r2) + Math.abs(c1 - c2) == 1 && map[r2][c2] == 'X') {
            return true;
        }

        // Condition 3: Adjacent to target, and target has solid neighbors
        if (Math.abs(r1 - r2) + Math.abs(c1 - c2) == 1 && countSolidNeighbors(map, r2, c2) > 0) {
            return true;
        }

        // Condition 4: Check if a valid path exists (avoiding 'X' cells)
        if (!hasPath(map, r1, c1, r2, c2)) {
            return false;
        }

        // Condition 5: Target is an obstacle, but has solid neighbors
        // (Note: In the original logic, this block is effectively unreachable if map[r2][c2] == 'X'
        // because hasPath returns false for 'X' destinations, but preserved for fidelity).
        if (map[r2][c2] == 'X' && countSolidNeighbors(map, r2, c2) > 0) {
            return true;
        }

        // Condition 6: Target has more than 1 solid neighbor
        if (countSolidNeighbors(map, r2, c2) > 1) {
            return true;
        }

        return false;
    }

    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);

        // Read dimensions
        if (!in.hasNextInt()) return;
        int n = in.nextInt();
        int m = in.nextInt();
        in.nextLine(); // Consume the newline character after m

        char[][] map = new char[n][];
        for (int i = 0; i < n; i++) {
            map[i] = in.nextLine().toCharArray();
        }

        // Read coordinates
        if (!in.hasNextInt()) return;
        int r1 = in.nextInt() - 1; // Convert 1-based to 0-based
        int c1 = in.nextInt() - 1;
        int r2 = in.nextInt() - 1;
        int c2 = in.nextInt() - 1;

        if (solve(map, r1, c1, r2, c2)) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }

        in.close();
    }
}

import java.io.*;
import java.util.*;

public class Cf301C {
    public static void main(String[] args) {
        FastScanner scanner = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out);

        int n = scanner.nextInt();
        int m = scanner.nextInt();

        char[][] grid = new char[n][m];
        for (int i = 0; i < n; i++) {
            grid[i] = scanner.next().toCharArray();
        }

        int startX = scanner.nextInt() - 1;
        int startY = scanner.nextInt() - 1;
        int endX = scanner.nextInt() - 1;
        int endY = scanner.nextInt() - 1;

        // Mark the starting position as traversable
        grid[startX][startY] = '.';

        boolean[][] visited = new boolean[n][m];
        bfs(grid, visited, startX, startY, endX, endY, n, m);

        boolean reachable = visited[endX][endY];
        if (reachable) {
            if (grid[endX][endY] == 'X') {
                out.println("YES");
            } else {
                int emptyNeighbors = countEmptyNeighbors(grid, endX, endY, n, m);
                if (startX == endX && startY == endY) {
                    out.println(emptyNeighbors > 0 ? "YES" : "NO");
                } else {
                    out.println(emptyNeighbors > 1 ? "YES" : "NO");
                }
            }
        } else {
            out.println("NO");
        }

        out.flush();
    }

    /**
     * Iterative BFS to find all reachable cells.
     * Replaces the original recursive DFS to prevent StackOverflowError on large grids.
     */
    private static void bfs(char[][] grid, boolean[][] visited, int startR, int startC, 
                            int endR, int endC, int n, int m) {
        Queue<int[]> queue = new ArrayDeque<>();
        queue.offer(new int[]{startR, startC});
        visited[startR][startC] = true;

        int[] dr = {-1, 1, 0, 0};
        int[] dc = {0, 0, -1, 1};

        while (!queue.isEmpty()) {
            int[] curr = queue.poll();
            int r = curr[0];
            int c = curr[1];

            if (r == endR && c == endC) break;

            for (int i = 0; i < 4; i++) {
                int nr = r + dr[i];
                int nc = c + dc[i];

                if (nr >= 0 && nr < n && nc >= 0 && nc < m && !visited[nr][nc]) {
                    // Cannot pass through 'X' unless it's the destination
                    if (grid[nr][nc] == 'X' && (nr != endR || nc != endC)) {
                        continue;
                    }
                    visited[nr][nc] = true;
                    queue.offer(new int[]{nr, nc});
                }
            }
        }
    }

    /**
     * Counts the number of adjacent empty ('.') cells around (r, c).
     */
    private static int countEmptyNeighbors(char[][] grid, int r, int c, int n, int m) {
        int count = 0;
        int[] dr = {-1, 1, 0, 0};
        int[] dc = {0, 0, -1, 1};

        for (int i = 0; i < 4; i++) {
            int nr = r + dr[i];
            int nc = c + dc[i];
            if (nr >= 0 && nr < n && nc >= 0 && nc < m && grid[nr][nc] == '.') {
                count++;
            }
        }
        return count;
    }

    /**
     * Fast input reader optimized for competitive programming.
     */
    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[8192];
        private int ptr = 0;
        private int buflen = 0;

        public FastScanner(InputStream in) {
            this.in = in;
        }

        private byte readByte() {
            if (ptr >= buflen) {
                ptr = 0;
                try {
                    buflen = in.read(buffer);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
                if (buflen <= 0) return -1;
            }
            return buffer[ptr++];
        }

        public int nextInt() {
            int c = readByte();
            while (isSpaceChar(c)) c = readByte();
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = readByte();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9') throw new InputMismatchException();
                res = res * 10 + (c - '0');
                c = readByte();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public String next() {
            int c = readByte();
            while (isSpaceChar(c)) c = readByte();
            StringBuilder sb = new StringBuilder();
            do {
                sb.appendCodePoint(c);
                c = readByte();
            } while (!isSpaceChar(c));
            return sb.toString();
        }

        private boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.LinkedList;
import java.util.Queue;
import java.util.StringTokenizer;

/**
 * Refactored Grid Pathfinding Solution.
 * 
 * Improvements made:
 * 1. Readability: Renamed variables (e.g., r1 -> startRow, dx -> DELTA_ROW).
 * 2. Structure: Encapsulated input parsing in a FastScanner class.
 * 3. Data Types: Used boolean[][] for grid logic (true = walkable) instead of 0/1 magic numbers.
 * 4. Algorithm: Implemented a proper visited array to prevent infinite loops in BFS.
 * 5. Indexing: Converted 1-based indexing to 0-based indexing for cleaner array access.
 * 6. Resource Management: Used try-with-resources or explicit closing for I/O streams.
 */
public class Main {

    // Direction vectors: Up, Down, Left, Right
    private static final int[] DELTA_ROW = {-1, 1, 0, 0};
    private static final int[] DELTA_COL = {0, 0, -1, 1};

    public static void main(String[] args) {
        new Main().run();
    }

    public void run() {
        // Initialize I/O
        FastScanner sc = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            solve(sc, out);
        } catch (IOException e) {
            // In a production environment, log this. 
            // For CP/algorithmic problems, we often ignore or print stack trace.
            e.printStackTrace();
        } finally {
            out.flush();
            out.close();
        }
    }

    private void solve(FastScanner sc, PrintWriter out) throws IOException {
        // Read dimensions
        int n = sc.nextInt();
        int m = sc.nextInt();

        // Grid: true represents a walkable cell (originally 1), false is obstacle (originally 0)
        boolean[][] isWalkable = new boolean[n][m];

        // Read Grid
        for (int i = 0; i < n; i++) {
            String row = sc.nextLine();
            // Handle potential empty lines or trailing spaces if input is malformed, 
            // though standard CP inputs are usually well-formed.
            if (row.length() < m) {
                // Fallback or error handling could go here, but assuming valid input
                continue; 
            }
            for (int j = 0; j < m; j++) {
                isWalkable[i][j] = (row.charAt(j) != 'X');
            }
        }

        // Read coordinates (1-based in input)
        int startRow = sc.nextInt() - 1;
        int startCol = sc.nextInt() - 1;
        int endRow = sc.nextInt() - 1;
        int endCol = sc.nextInt() - 1;

        // Calculate valid neighbors for the End point
        // Logic: Count neighbors that are inside bounds AND (walkable OR is the Start point)
        int validNeighborsCount = 0;
        for (int k = 0; k < 4; k++) {
            int r = endRow + DELTA_ROW[k];
            int c = endCol + DELTA_COL[k];

            if (r >= 0 && r < n && c >= 0 && c < m) {
                boolean isWalkableCell = isWalkable[r][c];
                boolean isStartPoint = (r == startRow && c == startCol);
                if (isWalkableCell || isStartPoint) {
                    validNeighborsCount++;
                }
            }
        }

        // BFS to find path
        boolean isConnected = bfs(n, m, startRow, startCol, endRow, endCol, isWalkable);

        // Output Logic
        if (isConnected) {
            // If the End point itself is walkable, check the neighbor count logic
            // (Preserving original logic: if grid[r2][c2] == 1)
            if (isWalkable[endRow][endCol]) {
                out.println(validNeighborsCount > 1 ? "YES" : "NO");
            } else {
                out.println("YES");
            }
        } else {
            out.println("NO");
        }
    }

    private boolean bfs(int n, int m, int startR, int startC, int endR, int endC, boolean[][] isWalkable) {
        if (startR < 0 || startR >= n || startC < 0 || startC >= m ||
            endR < 0 || endR >= n || endC < 0 || endC >= m) {
            return false;
        }

        Queue<Point> queue = new LinkedList<>();
        boolean[][] visited = new boolean[n][m];

        // Add start point
        queue.add(new Point(startR, startC));
        visited[startR][startC] = true;

        while (!queue.isEmpty()) {
            Point current = queue.poll();

            // Check if we reached the target
            if (current.r == endR && current.c == endC) {
                return true;
            }

            // Explore neighbors
            for (int k = 0; k < 4; k++) {
                int nextR = current.r + DELTA_ROW[k];
                int nextC = current.c + DELTA_COL[k];

                // Check bounds
                if (nextR >= 0 && nextR < n && nextC >= 0 && nextC < m) {
                    // Check if walkable and not visited
                    if (isWalkable[nextR][nextC] && !visited[nextR][nextC]) {
                        visited[nextR][nextC] = true;
                        queue.add(new Point(nextR, nextC));
                    }
                }
            }
        }

        return false;
    }

    // Helper class to store coordinates
    private static class Point {
        int r, c;
        Point(int r, int c) {
            this.r = r;
            this.c = c;
        }
    }

    // FastScanner for efficient input reading
    static class FastScanner {
        BufferedReader br;
        StringTokenizer st;

        public FastScanner(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            String s = next();
            if (s == null) throw new RuntimeException("End of input");
            return Integer.parseInt(s);
        }

        String nextLine() {
            String str = "";
            try {
                str = br.readLine();
            } catch (IOException e) {
                throw new RuntimeException(e);
            }
            return str;
        }
    }
}

