class TaskC {
    private static final int[][] DIRECTIONS = {{0, -1}, {-1, 0}, {0, 1}, {1, 0}};
    private static final char WALL = 'X';
    private static final char EMPTY = '.';
    private static final String RESULT_YES = "YES";
    private static final String RESULT_NO = "NO";

    static class Point {
        final int x, y;
        Point(int x, int y) {
            this.x = x;
            this.y = y;
        }
    }

    void solve(FastReader in, PrintWriter out) {
        int n = in.nextInt();
        int m = in.nextInt();
        String[] grid = new String[n];
        for (int i = 0; i < n; i++) {
            grid[i] = in.next();
        }

        int startRow = in.nextInt() - 1;
        int startCol = in.nextInt() - 1;
        int endRow = in.nextInt() - 1;
        int endCol = in.nextInt() - 1;

        if (startRow == endRow && startCol == endCol) {
            out.println(canMoveToAdjacent(grid, n, m, startRow, startCol) ? RESULT_YES : RESULT_NO);
            return;
        }

        if (!canReachEndFromNeighbors(grid, n, m, startRow, startCol, endRow, endCol)) {
            out.println(RESULT_NO);
            return;
        }

        boolean[][] visited = bfs(grid, n, m, startRow, startCol);

        out.println(isReachable(grid, n, m, startRow, startCol, endRow, endCol, visited) ? RESULT_YES : RESULT_NO);
    }

    private boolean canMoveToAdjacent(String[] grid, int n, int m, int r, int c) {
        for (int[] dir : DIRECTIONS) {
            int nr = r + dir[0];
            int nc = c + dir[1];
            if (isValid(nr, nc, n, m) && grid[nr].charAt(nc) == EMPTY) {
                return true;
            }
        }
        return false;
    }

    private boolean canReachEndFromNeighbors(String[] grid, int n, int m, int sr, int sc, int er, int ec) {
        if (grid[er].charAt(ec) != EMPTY) return false;

        int validNeighbors = 0;
        for (int[] dir : DIRECTIONS) {
            int nr = er + dir[0];
            int nc = ec + dir[1];
            if (isValid(nr, nc, n, m) && (grid[nr].charAt(nc) == EMPTY || (nr == sr && nc == sc))) {
                validNeighbors++;
            }
        }
        return validNeighbors >= 2;
    }

    private boolean[][] bfs(String[] grid, int n, int m, int startR, int startC) {
        boolean[][] visited = new boolean[n][m];
        ArrayDeque<Point> queue = new ArrayDeque<>();
        queue.add(new Point(startR, startC));
        visited[startR][startC] = true;

        while (!queue.isEmpty()) {
            Point curr = queue.poll();
            for (int[] dir : DIRECTIONS) {
                int nr = curr.x + dir[0];
                int nc = curr.y + dir[1];
                if (isValid(nr, nc, n, m) && !visited[nr][nc] && grid[nr].charAt(nc) != WALL) {
                    visited[nr][nc] = true;
                    queue.add(new Point(nr, nc));
                }
            }
        }
        return visited;
    }

    private boolean isReachable(String[] grid, int n, int m, int sr, int sc, int er, int ec, boolean[][] visited) {
        for (int[] dir : DIRECTIONS) {
            int nr = er + dir[0];
            int nc = ec + dir[1];
            if (isValid(nr, nc, n, m) && visited[nr][nc]) {
                return true;
            }
        }
        return false;
    }

    private boolean isValid(int r, int c, int n, int m) {
        return r >= 0 && r < n && c >= 0 && c < m;
    }
}

class FastReader {
