public class IceCave {
    // Constants for direction vectors (Right, Down, Left, Up)
    // Extracted to static final to avoid re-allocation and improve readability
    private static final int[] DR = {0, 1, 0, -1};
    private static final int[] DC = {1, 0, -1, 0};

    // Instance variables to encapsulate state
    // Avoids the use of static fields, making the class reusable and thread-safe
    private int rows;
    private int cols;
    private char[][] grid;
    private boolean[][] visited;

    public static void main(String[] args) {
        IceCave solver = new IceCave();
