    public void run() {
        Scanner scanner = new Scanner(System.in);

        // Read dimensions
        if (!scanner.hasNextInt()) return;
        this.rows = scanner.nextInt();
        this.cols = scanner.nextInt();

        // Read grid content
        this.grid = new char[this.rows][this.cols];
        for (int i = 0; i < this.rows; i++) {
            if (scanner.hasNext()) {
                this.grid[i] = scanner.next().toCharArray();
            }
        }

        // Read start and end coordinates (convert from 1-based to 0-based)
        int startR = scanner.nextInt() - 1;
        int startC = scanner.nextInt() - 1;
        int targetR = scanner.nextInt() - 1;
        int targetC = scanner.nextInt() - 1;

        scanner.close();

        // Execute the core logic
        solve(startR, startC, targetR, targetC);
    }

    private void solve(int startR, int startC, int targetR, int targetC) {
        // Save the original state of the target cell before modifying the grid
        char originalTargetChar = this.grid[targetR][targetC];

        // Clear the start and target cells to simulate movement/breaking ice
        this.grid[startR][startC] = '.';
        this.grid[targetR][targetC] = '.';

        // Count the number of empty ('.') neighbors of the target cell
        // This is crucial for the logic regarding breaking ice at the target
        int emptyNeighborCount = 0;
        for (int i = 0; i < 4; i++) {
            int nr = targetR + DR[i];
            int nc = targetC + DC[i];
            if (isValid(nr, nc) && this.grid[nr][nc] == '.') {
                emptyNeighborCount++;
            }
        }

        // Case 1: Start and End are the same
        if (startR == targetR && startC == targetC) {
            if (emptyNeighborCount >= 1) {
                System.out.println("YES");
            } else {
                System.out.println("NO");
            }
        } 
        // Case 2: Start and End are different
        else {
            // Initialize visited array and run DFS from start
            this.visited = new boolean[this.rows][this.cols];
            dfs(startR, startC);

            if (this.visited[targetR][targetC]) {
                // Target is reachable
                if (emptyNeighborCount <= 1) {
                    // Specific logic for when the target was originally ice ('X')
                    if (originalTargetChar == 'X') {
                        System.out.println("YES");
                    } else {
                        System.out.println("NO");
                    }
                } else {
                    System.out.println("YES");
                }
            } else {
                System.out.println("NO");
            }
        }
    }

    private void dfs(int r, int c) {
        this.visited[r][c] = true;

        for (int i = 0; i < 4; i++) {
            int nr = r + DR[i];
            int nc = c + DC[i];

            // Check bounds, if cell is empty ('.'), and if not visited
            if (isValid(nr, nc) && this.grid[nr][nc] == '.' && !this.visited[nr][nc]) {
                dfs(nr, nc);
            }
        }
    }

    private boolean isValid(int r, int c) {
        return r >= 0 && r < this.rows && c >= 0 && c < this.cols;
    }
}

import java.util.ArrayDeque;
import java.util.Queue;
import java.util.Scanner;

public class Main {

    public static void main(String[] args) {
        try (Scanner scan = new Scanner(System.in)) {
            if (!scan.hasNextInt()) return;

            int rows = scan.nextInt();
            int cols = scan.nextInt();
            scan.nextLine(); // Consume the newline after integers

            // Edge case: 1x1 grid cannot have a distinct path
            if (rows * cols == 1) {
                System.out.println("NO");
                return;
            }

            char[][] grid = new char[rows][cols];
            for (int r = 0; r < rows; r++) {
                String line = scan.nextLine();
                grid[r] = line.toCharArray();
            }

            // Input format: startY startX endY endX (1-indexed)
            int startRow = scan.nextInt() - 1;
            int startCol = scan.nextInt() - 1;
            int endRow = scan.nextInt() - 1;
            int endCol = scan.nextInt() - 1;

            // Validate coordinates
            if (!isValidCoord(startRow, startCol, rows, cols) || !isValidCoord(endRow, endCol, rows, cols)) {
                System.out.println("NO");
                return;
            }

            // Special condition: Destination must have at least 2 intact neighbors if it's a '.'
            if (grid[endRow][endCol] == '.' && countIntactNeighbors(grid, endRow, endCol, startRow, startCol, rows, cols) < 2) {
                System.out.println("NO");
                return;
            }

            // Perform BFS to find path
            if (bfs(grid, startRow, startCol, endRow, endCol, rows, cols)) {
                System.out.println("YES");
            } else {
                System.out.println("NO");
            }
        }
    }

    /**
     * Performs Breadth-First Search to determine if end is reachable from start.
     */
    private static boolean bfs(char[][] grid, int startRow, int startCol, int endRow, int endCol, int rows, int cols) {
        // Trivial case: start and end are the same
        if (startRow == endRow && startCol == endCol) {
            return true;
        }

        boolean[][] visited = new boolean[rows][cols];
        Queue<int[]> queue = new ArrayDeque<>();

        queue.add(new int[]{startRow, startCol});
        visited[startRow][startCol] = true;

        // Direction vectors: up, down, left, right
        int[] dr = {-1, 1, 0, 0};
        int[] dc = {0, 0, -1, 1};

        while (!queue.isEmpty()) {
            int[] current = queue.poll();
            int r = current[0];
            int c = current[1];

            for (int i = 0; i < 4; i++) {
                int nr = r + dr[i];
                int nc = c + dc[i];

                // Check bounds, visited status, and walkable terrain
                if (nr >= 0 && nr < rows && nc >= 0 && nc < cols && 
                    !visited[nr][nc] && grid[nr][nc] != 'X') {

                    if (nr == endRow && nc == endCol) {
                        return true;
                    }

                    visited[nr][nc] = true;
                    queue.add(new int[]{nr, nc});
                }
            }
        }

        return false;
    }

    /**
     * Counts neighbors of a cell that are either '.' or the starting position.
     */
    private static int countIntactNeighbors(char[][] grid, int row, int col, int startRow, int startCol, int rows, int cols) {
        int count = 0;
        int[] dr = {-1, 1, 0, 0};
        int[] dc = {0, 0, -1, 1};

        for (int k = 0; k < 4; k++) {
            int nr = row + dr[k];
            int nc = col + dc[k];

            if (nr >= 0 && nr < rows && nc >= 0 && nc < cols) {
                if (grid[nr][nc] == '.' || (nr == startRow && nc == startCol)) {
                    count++;
                }
            }
        }
        return count;
    }

    /**
     * Utility method to check if coordinates are within grid bounds.
     */
    private static boolean isValidCoord(int row, int col, int rows, int cols) {
        return row >= 0 && row < rows && col >= 0 && col < cols;
    }
}

