public class Main {
    public static void main(String[] args) {
        FastScanner scanner = new FastScanner();
        PrintWriter out = new PrintWriter(System.out);

        try {
            int n = scanner.nextInt();
            int m = scanner.nextInt();

            char[][] grid = new char[n][m];
            for (int i = 0; i < n; i++) {
                String row = scanner.next();
                grid[i] = row.toCharArray();
            }

            // Convert 1-based coordinates to 0-based
            int startR = scanner.nextInt() - 1;
            int startC = scanner.nextInt() - 1;
            int targetR = scanner.nextInt() - 1;
            int targetC = scanner.nextInt() - 1;

            boolean reachable = solve(grid, n, m, startR, startC, targetR, targetC);

            out.println(reachable ? "YES" : "NO");
        } catch (Exception e) {
            // Gracefully handle malformed input or unexpected EOF
            out.println("NO");
        } finally {
            out.flush();
        }
    }

    /**
     * Determines if the target cell is reachable from the start cell using BFS.
     * Walkable cells are '.', and the target cell is marked as 'X' in the grid.
     */
    private static boolean solve(char[][] grid, int n, int m, 
                                 int startR, int startC, 
                                 int targetR, int targetC) {
        // Validate boundary conditions
        if (startR < 0 || startR >= n || startC < 0 || startC >= m ||
            targetR < 0 || targetR >= n || targetC < 0 || targetC >= m) {
            return false;
        }

        boolean[][] visited = new boolean[n][m];
        Queue<int[]> queue = new ArrayDeque<>();

        // Starting cell must be walkable ('.') or be the target itself ('X')
        char startCell = grid[startR][startC];
        if (startCell != '.' && !(startR == targetR && startC == targetC)) {
            return false;
        }

        visited[startR][startC] = true;
        queue.offer(new int[]{startR, startC});

        // Direction vectors: Up, Down, Left, Right
        int[] dr = {-1, 1, 0, 0};
        int[] dc = {0, 0, -1, 1};

        while (!queue.isEmpty()) {
            int[] current = queue.poll();
            int r = current[0];
            int c = current[1];

            // Check if we reached the target
            if (r == targetR && c == targetC) {
                return true;
            }

            for (int i = 0; i < 4; i++) {
                int nr = r + dr[i];
                int nc = c + dc[i];

                // Check boundaries and visited status
                if (nr >= 0 && nr < n && nc >= 0 && nc < m && !visited[nr][nc]) {
                    char cell = grid[nr][nc];

                    // If it's the target cell (marked as 'X' in input)
                    if (nr == targetR && nc == targetC && cell == 'X') {
                        return true;
                    }

                    // If it's a walkable path
                    if (cell == '.') {
                        visited[nr][nc] = true;
                        queue.offer(new int[]{nr, nc});
                    }
                }
            }
        }

        return false;
    }

    /**
     * Fast input reader optimized for competitive programming and performance-critical applications.
     */
    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        public String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input", e);
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            String token = next();
            if (token == null) throw new RuntimeException("Unexpected end of input");
            return Integer.parseInt(token);
        }
    }
}

