/**
 * Refactored solution for Codeforces 540C - Ice Cave.
 * 
 * Improvements over original:
 * - Clear, consistent variable naming and formatting.
 * - Separated concerns: pathfinding, neighbor counting, and I/O.
 * - Fixed BFS to properly track visited cells and validate bounds.
 * - Eliminated highly repetitive code using loops and helper methods.
 * - Added comprehensive documentation and comments.
 */
public class Rating2000_540C {
    private static final InputReader in = new InputReader(System.in);
    private static final PrintWriter out = new PrintWriter(System.out);

    public static void main(String[] args) {
        int rows = in.nextInt();
        int cols = in.nextInt();

        char[][] grid = new char[rows][cols];
        char[][] originalGrid = new char[rows][cols];

        for (int i = 0; i < rows; i++) {
            String line = in.next();
            for (int j = 0; j < cols; j++) {
                grid[i][j] = line.charAt(j);
                originalGrid[i][j] = line.charAt(j);
            }
        }

        int startR = in.nextInt() - 1;
        int startC = in.nextInt() - 1;
        int endR = in.nextInt() - 1;
        int endC = in.nextInt() - 1;

        boolean canReach = bfs(rows, cols, startR, startC, endR, endC);
        boolean endInitiallyCracked = originalGrid[endR][endC] == 'X';
        boolean areAdjacent = Math.abs(startR - endR) + Math.abs(startC - endC) == 1;

        if (!canReach) {
            out.println("NO");
        } else {
            int adjacentEmptyCount = countAdjacentEmpty(originalGrid, endR, endC);
            boolean result;

            if (areAdjacent) {
                result = !endInitiallyCracked || adjacentEmptyCount >= 1;
            } else if (endInitiallyCracked) {
                result = adjacentEmptyCount >= 1;
            } else {
                result = adjacentEmptyCount >= 2;
            }
            out.println(result ? "YES" : "NO");
        }
        out.flush();
    }

    /**
     * Performs BFS to determine if a path exists from start to end.
     * Treats both '.' and 'X' as passable cells.
     */
    private static boolean bfs(int rows, int cols, int startR, int startC, int endR, int endC) {
        boolean[][] visited = new boolean[rows][cols];
        Queue<int[]> queue = new LinkedList<>();

        queue.offer(new int[]{startR, startC});
        visited[startR][startC] = true;

        int[] dr = {-1, 1, 0, 0};
        int[] dc = {0, 0, -1, 1};

        while (!queue.isEmpty()) {
            int[] curr = queue.poll();
            int r = curr[0];
            int c = curr[1];

            if (r == endR && c == endC) {
                return true;
            }

            for (int i = 0; i < 4; i++) {
                int nr = r + dr[i];
                int nc = c + dc[i];

                if (isValid(nr, nc, rows, cols) && !visited[nr][nc]) {
                    visited[nr][nc] = true;
                    queue.offer(new int[]{nr, nc});
                }
            }
        }
        return false;
    }

    /**
     * Counts the number of adjacent '.' cells in the original grid.
     */
    private static int countAdjacentEmpty(char[][] grid, int r, int c) {
        int count = 0;
        int[] dr = {-1, 1, 0, 0};
        int[] dc = {0, 0, -1, 1};
        int rows = grid.length;
        int cols = grid[0].length;

        for (int i = 0; i < 4; i++) {
            int nr = r + dr[i];
            int nc = c + dc[i];
            if (isValid(nr, nc, rows, cols) && grid[nr][nc] == '.') {
                count++;
            }
        }
        return count;
    }

    private static boolean isValid(int r, int c, int rows, int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /**
     * Fast input reader for competitive programming.
     */
    static class InputReader {
