/**
 * Handles grid construction and depth-first search pathfinding.
 * Separates traversal logic from input/output concerns.
 */
class GridPathfinder {
    private final int rows;
    private final int cols;
    private final char[][] grid;
    private boolean[][] visited;

    /**
     * Initializes the pathfinder with grid dimensions and layout.
     *
     * @param rows Number of rows in the grid
     * @param cols Number of columns in the grid
     * @param grid Character array representing the grid layout
     */
    public GridPathfinder(int rows, int cols, char[][] grid) {
        this.rows = rows;
        this.cols = cols;
        this.grid = grid;
        this.visited = new boolean[rows][cols];
    }

    /**
     * Determines if a valid path exists from the start coordinates to the target coordinates.
     *
     * @param startRow    Start row index (0-based)
     * @param startCol    Start column index (0-based)
     * @param targetRow   Target row index (0-based)
     * @param targetCol   Target column index (0-based)
     * @return true if a path exists, false otherwise
     */
    public boolean canReach(int startRow, int startCol, int targetRow, int targetCol) {
        if (!isWithinBounds(startRow, startCol) || !isWithinBounds(targetRow, targetCol)) {
            return false;
        }
        if (grid[startRow][startCol] == OBSTACLE || grid[targetRow][targetCol] == OBSTACLE) {
            return false;
        }

        return performDfs(startRow, startCol, targetRow, targetCol);
    }

    /**
     * Recursively explores the grid using Depth-First Search.
     *
     * @param currentRow    Current row being explored
     * @param currentCol    Current column being explored
     * @param targetRow     Target row index
     * @param targetCol     Target column index
     * @return true if target is reachable from current position
     */
    private boolean performDfs(int currentRow, int currentCol, int targetRow, int targetCol) {
        // Base case: Target reached
        if (currentRow == targetRow && currentCol == targetCol) {
            return true;
        }

        // Prune invalid paths
        if (!isWithinBounds(currentRow, currentCol) || visited[currentRow][currentCol] ||
            grid[currentRow][currentCol] == OBSTACLE) {
            return false;
        }

        // Mark current cell as visited
        visited[currentRow][currentCol] = true;

        // Explore all 4 cardinal directions
        if (performDfs(currentRow + 1, currentCol, targetRow, targetCol) ||
            performDfs(currentRow - 1, currentCol, targetRow, targetCol) ||
            performDfs(currentRow, currentCol + 1, targetRow, targetCol) ||
            performDfs(currentRow, currentCol - 1, targetRow, targetCol)) {
            return true;
        }

        // Backtrack: unmark current cell to allow other paths to traverse it
        visited[currentRow][currentCol] = false;
        return false;
    }

    /**
     * Checks if the given coordinates are within the grid boundaries.
     *
     * @param row Row index to check
     * @param col Column index to check
     * @return true if coordinates are valid, false otherwise
     */
    private boolean isWithinBounds(int row, int col) {
        return row >= 0 && row < rows && col >= 0 && col < cols;
    }
}

import java.io.*;
import java.util.StringTokenizer;

public class Main {
    public static void main(String[] args) {
        FastScanner scanner = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out);
        IceCaveSolver solver = new IceCaveSolver();

        solver.solve(scanner, out);
        out.flush();
    }

    /**
     * Encapsulates the grid traversal logic for the Ice Cave problem.
     * All state is instance-based to improve maintainability and testability.
     */
    static class IceCaveSolver {
        private int n, m;
        private char[][] grid;
        private boolean[][] visited;
        private int startX, startY, endX, endY;

        // Cardinal directions: right, left, down, up
        private static final int[][] DIRECTIONS = {{0, 1}, {0, -1}, {1, 0}, {-1, 0}};

        public void solve(FastScanner sc, PrintWriter out) {
            n = sc.nextInt();
            m = sc.nextInt();

            grid = new char[n][m];
            visited = new boolean[n][m];

            for (int i = 0; i < n; i++) {
                grid[i] = sc.next().toCharArray();
            }

            // Convert 1-based input coordinates to 0-based
            startX = sc.nextInt() - 1;
            startY = sc.nextInt() - 1;
            endX = sc.nextInt() - 1;
            endY = sc.nextInt() - 1;

            boolean canReach = dfs(startX, startY);
            out.println(canReach ? "YES" : "NO");
        }

        /**
         * Depth-First Search to determine if the target is reachable.
         * Returns true if a valid path exists that satisfies the ice-breaking rules.
         */
        private boolean dfs(int x, int y) {
            // Base case: Reached the target
            if (x == endX && y == endY) {
                if (grid[x][y] == '.') {
                    grid[x][y] = 'X'; // Break the ice at the target
                    // Must be able to move to at least one adjacent cell after breaking
                    for (int[] dir : DIRECTIONS) {
                        int nx = x + dir[0];
                        int ny = y + dir[1];
                        if (isValid(nx, ny) && !visited[nx][ny]) {
                            if (dfs(nx, ny)) return true;
                        }
                    }
                    return false; // Reached target but cannot move out
                } else {
                    // Target is 'X', can step on it exactly once
                    for (int[] dir : DIRECTIONS) {
                        int nx = x + dir[0];
                        int ny = y + dir[1];
                        if (isValid(nx, ny) && !visited[nx][ny]) {
                            if (dfs(nx, ny)) return true;
                        }
                    }
                    return false;
                }
            }

            // Mark current cell as visited
            visited[x][y] = true;

            // Cannot traverse 'X' cells unless it's the target
            if (grid[x][y] == 'X') {
                return false;
            }

            // Explore neighbors
            for (int[] dir : DIRECTIONS) {
                int nx = x + dir[0];
                int ny = y + dir[1];
                if (isValid(nx, ny) && !visited[nx][ny]) {
                    if (dfs(nx, ny)) return true;
                }
            }

            return false;
        }

        /**
         * Checks if coordinates are within grid bounds.
         */
        private boolean isValid(int x, int y) {
            return x >= 0 && x < n && y >= 0 && y < m;
        }
    }

    /**
     * Fast input reader optimized for competitive programming and bulk I/O.
     */
    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        public String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) throw new EOFException("Unexpected end of input");
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input", e);
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

