        for (int i = 0; i < n; i++) {
            String row = scanner.next();
            map[i] = row != null ? row.toCharArray() : new char[0];
        }

        // Convert 1-based coordinates to 0-based
        int r1 = scanner.nextInt() - 1;
        int c1 = scanner.nextInt() - 1;
        int r2 = scanner.nextInt() - 1;
        int c2 = scanner.nextInt() - 1;

        System.out.println(canReachWithConditions(r1, c1, r2, c2, n, m, map) ? "YES" : "NO");
    }

    /**
     * Encapsulates the problem-specific conditions for determining reachability.
     */
    private static boolean canReachWithConditions(int startR, int startC, int endR, int endC, 
                                                  int n, int m, char[][] map) {
        int openNeighbors = 0;
        for (int i = 0; i < 4; i++) {
            int nr = endR + DX[i];
            int nc = endC + DY[i];

            if (isInBounds(nr, nc, n, m)) {
                if (map[nr][nc] == EMPTY_CELL) {
                    openNeighbors++;
                }
                if (nr == startR && nc == startC) {
                    openNeighbors++;
                }
            }
        }

        // Condition 1: Destination must have at least 2 open neighbors if it's an empty cell
        if (map[endR][endC] == EMPTY_CELL && openNeighbors < 2) {
            return false;
        }

        // Condition 2: Start and end are the same cell
        if (startR == endR && startC == endC) {
            return openNeighbors > 0;
        }

        // Condition 3: Standard pathfinding
        return isPathExists(startR, startC, endR, endC, n, m, map);
    }

    /**
     * Iterative BFS to check if a path exists from start to end.
     * Replaces the original recursive DFS to prevent stack overflow and remove side-effects.
     */
    private static boolean isPathExists(int startR, int startC, int endR, int endC, 
                                        int n, int m, char[][] map) {
        boolean[][] visited = new boolean[n][m];
        Queue<int[]> queue = new ArrayDeque<>();
        queue.offer(new int[]{startR, startC});
        visited[startR][startC] = true;

        while (!queue.isEmpty()) {
            int[] current = queue.poll();
            int r = current[0];
            int c = current[1];

            for (int i = 0; i < 4; i++) {
                int nr = r + DX[i];
                int nc = c + DY[i];

                if (isInBounds(nr, nc, n, m) && !visited[nr][nc]) {
                    // Early exit: match original behavior where target is reached regardless of cell type
                    if (nr == endR && nc == endC) {
                        return true;
                    }
                    // Only traverse through empty cells
                    if (map[nr][nc] == EMPTY_CELL) {
                        visited[nr][nc] = true;
                        queue.offer(new int[]{nr, nc});
                    }
                }
            }
        }
        return false;
    }

    private static boolean isInBounds(int x, int y, int n, int m) {
        return x >= 0 && x < n && y >= 0 && y < m;
    }

    /**
     * Extracted and cleaned-up FastScanner for competitive programming style I/O.
     */
    private static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner(InputStream input) {
            br = new BufferedReader(new InputStreamReader(input));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                String line = readLine();
                if (line == null) return null;
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

        int nextInt() {
            String s = next();
            if (s == null) throw new RuntimeException("Unexpected end of input");
            return Integer.parseInt(s);
        }

        private String readLine() {
            try {
                return br.readLine();
            } catch (IOException e) {
                throw new RuntimeException("Error reading input", e);
            }
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.OutputStream;
import java.io.PrintWriter;
import java.util.ArrayDeque;
import java.util.NoSuchElementException;
import java.util.Queue;
import java.util.StringTokenizer;

public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        FastScanner in = new FastScanner(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        TaskC solver = new TaskC();
        solver.solve(1, in, out);
        out.close();
    }

    static class TaskC {
        private static final int[][] DIRS = {{0, 1}, {0, -1}, {1, 0}, {-1, 0}};

        private int rows;
        private int cols;
        private boolean[][] isCracked;
        private boolean[][] visited;
        private int startRow, startCol, endRow, endCol;

        private boolean isValid(int r, int c) {
            return r >= 0 && c >= 0 && r < rows && c < cols;
        }

        private void floodFill(int startR, int startC, int endR, int endC) {
            Queue<int[]> queue = new ArrayDeque<>();
            queue.offer(new int[]{startR, startC});
            visited[startR][startC] = true;

            while (!queue.isEmpty()) {
                int[] curr = queue.poll();
                int r = curr[0], c = curr[1];

                for (int[] dir : DIRS) {
                    int nr = r + dir[0];
                    int nc = c + dir[1];

                    if (isValid(nr, nc) && !visited[nr][nc]) {
                        // Can only step onto non-cracked cells, or the destination if it's cracked
                        if (!isCracked[nr][nc] || (nr == endR && nc == endC)) {
                            visited[nr][nc] = true;
                            // Only continue traversal from non-cracked cells
                            if (!isCracked[nr][nc]) {
                                queue.offer(new int[]{nr, nc});
                            }
                        }
                    }
                }
            }
        }

        public void solve(int testNumber, FastScanner sc, PrintWriter out) {
            rows = sc.nextInt();
            cols = sc.nextInt();
            visited = new boolean[rows][cols];
            isCracked = new boolean[rows][cols];

            for (int i = 0; i < rows; i++) {
                String line = sc.next();
                for (int j = 0; j < cols; j++) {
                    isCracked[i][j] = line.charAt(j) == 'X';
                }
            }

            startRow = sc.nextInt() - 1;
            startCol = sc.nextInt() - 1;
            endRow = sc.nextInt() - 1;
            endCol = sc.nextInt() - 1;

            // Handle case where start and end are the same
            if (startRow == endRow && startCol == endCol) {
                for (int[] dir : DIRS) {
                    int nr = startRow + dir[0];
                    int nc = startCol + dir[1];
                    if (isValid(nr, nc) && !isCracked[nr][nc]) {
                        out.println("YES");
                        return;
                    }
                }
                out.println("NO");
                return;
            }

            floodFill(startRow, startCol, endRow, endCol);

            // If destination is cracked, it's reachable only if marked during flood fill
            if (isCracked[endRow][endCol]) {
                out.println(visited[endRow][endCol] ? "YES" : "NO");
                return;
            }

            // Check neighbors of the destination
            int adjacentNonCrackedOrStart = 0;
            boolean adjacentToReachable = false;
            for (int[] dir : DIRS) {
                int nr = endRow + dir[0];
                int nc = endCol + dir[1];
                if (isValid(nr, nc)) {
                    if (visited[nr][nc]) {
                        adjacentToReachable = true;
                    }
                    if (nr == startRow && nc == startCol || !isCracked[nr][nc]) {
                        adjacentNonCrackedOrStart++;
                    }
                }
            }
            out.println((adjacentNonCrackedOrStart >= 2 && adjacentToReachable) ? "YES" : "NO");
        }
    }

    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        public String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            String s = next();
            if (s == null) throw new NoSuchElementException("Unexpected end of input");
            return Integer.parseInt(s);
        }
    }
}

import java.util.Scanner;
import java.util.Deque;
import java.util.ArrayDeque;

/**
 * A maze solver using Depth-First Search (DFS).
 * Reads grid dimensions, the grid itself, and start/end coordinates.
 * Outputs "YES" if a path exists, "NO" otherwise.
 */
public class MazeSolver {

    /**
     * Helper class to store row and column coordinates.
     */
    private static class Point {
        int r;
        int c;

        Point(int r, int c) {
            this.r = r;
            this.c = c;
        }
    }

    // Direction vectors: Right, Left, Down, Up
    // Format: {row_change, col_change}
    private static final int[][] DIRECTIONS = {
        {0, 1},   // Right
        {0, -1},  // Left
        {1, 0},   // Down
        {-1, 0}   // Up
    };

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        // Read grid dimensions
        if (!scanner.hasNextInt()) {
            return;
        }
        int rows = scanner.nextInt();
        int cols = scanner.nextInt();

        // Read the grid
        String[] grid = new String[rows];
        for (int i = 0; i < rows; i++) {
            grid[i] = scanner.next();
        }

        // Read start and end positions
        // Input is 1-based index, converting to 0-based for array access
        int startRow = scanner.nextInt() - 1;
        int startCol = scanner.nextInt() - 1;
        int endRow = scanner.nextInt() - 1;
        int endCol = scanner.nextInt() - 1;

        // Solve the maze
        boolean pathFound = findPath(grid, rows, cols, startRow, startCol, endRow, endCol);

        if (pathFound) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }

        scanner.close();
    }

    /**
     * Finds if there is a path from start to end in the grid using DFS.
     *
     * @param grid The maze grid
     * @param rows Number of rows
     * @param cols Number of columns
     * @param startRow Starting row index (0-based)
     * @param startCol Starting column index (0-based)
     * @param endRow Ending row index (0-based)
     * @param endCol Ending column index (0-based)
     * @return true if a path exists, false otherwise
     */
    private static boolean findPath(String[] grid, int rows, int cols,
                                    int startRow, int startCol,
                                    int endRow, int endCol) {

        // Basic validation for start position
        if (startRow < 0 || startRow >= rows || startCol < 0 || startCol >= cols) {
            return false;
        }
        // If the starting cell is a wall ('X'), no path is possible
        if (grid[startRow].charAt(startCol) == 'X') {
            return false;
        }

        boolean[][] visited = new boolean[rows][cols];
        // ArrayDeque is preferred over Stack for better performance and API
        Deque<Point> stack = new ArrayDeque<>();

        stack.push(new Point(startRow, startCol));

        while (!stack.isEmpty()) {
            Point current = stack.pop();

            // Check if we reached the destination
            if (current.r == endRow && current.c == endCol) {
                return true;
            }

            // Mark current cell as visited
            visited[current.r][current.c] = true;

            // Explore all 4 directions
            for (int[] direction : DIRECTIONS) {
                int nextR = current.r + direction[0];
                int nextC = current.c + direction[1];

                // Check boundaries
                if (nextR >= 0 && nextR < rows && nextC >= 0 && nextC < cols) {
                    // Check if not visited and not an obstacle ('X')
                    if (!visited[nextR][nextC] && grid[nextR].charAt(nextC) != 'X') {
                        stack.push(new Point(nextR, nextC));
                    }
                }
            }
        }

        return false;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayDeque;
import java.util.Deque;
import java.util.StringTokenizer;

/**
 * Solves a grid-based reachability problem.
 * Determines if a target cell can be reached from a start cell under specific adjacency rules.
 */
public class GridPathSolver {

    // Direction vectors for up, right, down, left
    private static final int[] DELTA_X = {-1, 0, 1, 0};
    private static final int[] DELTA_Y = {0, 1, 0, -1};

    private static final char EMPTY_CELL = '.';
    private static final char OBSTACLE = 'X';

    public static void main(String[] args) throws IOException {
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(System.in))) {
            // Read grid dimensions
            StringTokenizer tokenizer = new StringTokenizer(reader.readLine());
            int n = Integer.parseInt(tokenizer.nextToken());
            int m = Integer.parseInt(tokenizer.nextToken());

            // Read grid layout
            char[][] grid = new char[n][m];
            for (int i = 0; i < n; i++) {
                grid[i] = reader.readLine().toCharArray();
            }

            // Read start position (convert 1-based input to 0-based)
            tokenizer = new StringTokenizer(reader.readLine());
            Coordinate start = new Coordinate(
                    Integer.parseInt(tokenizer.nextToken()) - 1,
                    Integer.parseInt(tokenizer.nextToken()) - 1
            );

            // Read target position (convert 1-based input to 0-based)
            tokenizer = new StringTokenizer(reader.readLine());
            Coordinate target = new Coordinate(
                    Integer.parseInt(tokenizer.nextToken()) - 1,
                    Integer.parseInt(tokenizer.nextToken()) - 1
            );

            // Solve and print result
            System.out.println(solve(grid, start, target) ? "YES" : "NO");
        }
    }

    /**
     * Determines if the target is reachable from the start according to the problem rules.
     */
    private static boolean solve(char[][] grid, Coordinate start, Coordinate target) {
        int targetEmptyNeighbors = countAdjacentEmpty(grid, target, grid.length, grid[0].length);

        // Rule 1: Directly adjacent to target, and target is either an obstacle or has at least one empty neighbor
        if (areAdjacent(start, target) && (grid[target.x][target.y] == OBSTACLE || targetEmptyNeighbors >= 1)) {
            return true;
        }

        // Rule 2: Target is an obstacle or has more than one empty neighbor
        if (grid[target.x][target.y] == OBSTACLE || targetEmptyNeighbors >= 2) {
            boolean[][] visited = new boolean[grid.length][grid[0].length];
            visited[start.x][start.y] = true;
            dfs(grid, visited, start, grid.length, grid[0].length);

            // Check if any neighbor of the target is reachable
            for (int i = 0; i < DELTA_X.length; i++) {
                int adjX = target.x + DELTA_X[i];
                int adjY = target.y + DELTA_Y[i];
                if (isValid(adjX, adjY, grid.length, grid[0].length) && visited[adjX][adjY]) {
                    return true;
                }
            }
        }

        return false;
    }

    /**
     * Iterative DFS to mark all reachable empty cells from the start position.
     * Uses a stack to prevent StackOverflowError on large grids.
     */
    private static void dfs(char[][] grid, boolean[][] visited, Coordinate start, int rows, int cols) {
        Deque<Coordinate> stack = new ArrayDeque<>();
        stack.push(start);

        while (!stack.isEmpty()) {
            Coordinate current = stack.pop();

            for (int i = 0; i < DELTA_X.length; i++) {
                int nextX = current.x + DELTA_X[i];
                int nextY = current.y + DELTA_Y[i];

                if (isValid(nextX, nextY, rows, cols)
                        && !visited[nextX][nextY]
                        && grid[nextX][nextY] == EMPTY_CELL) {
                    visited[nextX][nextY] = true;
                    stack.push(new Coordinate(nextX, nextY));
                }
            }
        }
    }

    /**
     * Counts the number of adjacent empty cells ('.') for a given coordinate.
     */
    private static int countAdjacentEmpty(char[][] grid, Coordinate coord, int rows, int cols) {
        int count = 0;
        for (int i = 0; i < DELTA_X.length; i++) {
            int adjX = coord.x + DELTA_X[i];
            int adjY = coord.y + DELTA_Y[i];
            if (isValid(adjX, adjY, rows, cols) && grid[adjX][adjY] == EMPTY_CELL) {
                count++;
            }
        }
        return count;
    }

    /**
     * Checks if two coordinates are orthogonally adjacent using Manhattan distance.
     */
    private static boolean areAdjacent(Coordinate p1, Coordinate p2) {
        return Math.abs(p1.x - p2.x) + Math.abs(p1.y - p2.y) == 1;
    }

    /**
     * Validates if coordinates are within grid bounds.
     */
    private static boolean isValid(int x, int y, int rows, int cols) {
        return x >= 0 && x < rows && y >= 0 && y < cols;
    }

    /**
     * Immutable 2D grid coordinate.
     */
    private static final class Coordinate {
        final int x;
        final int y;

        Coordinate(int x, int y) {
            this.x = x;
            this.y = y;
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.ArrayDeque;
import java.util.Queue;

public class Main {
    private static final int[] DX = {1, -1, 0, 0};
    private static final int[] DY = {0, 0, 1, -1};

    public static void main(String[] args) throws IOException {
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
             PrintWriter writer = new PrintWriter(System.out)) {

            String[] dimensions = reader.readLine().split("\\s+");
            int rows = Integer.parseInt(dimensions[0]);
            int cols = Integer.parseInt(dimensions[1]);

            char[][] grid = new char[rows][];
            for (int i = 0; i < rows; i++) {
                grid[i] = reader.readLine().toCharArray();
            }

            String[] startCoords = reader.readLine().split("\\s+");
            int startX = Integer.parseInt(startCoords[0]) - 1;
            int startY = Integer.parseInt(startCoords[1]) - 1;

            String[] endCoords = reader.readLine().split("\\s+");
            int endX = Integer.parseInt(endCoords[0]) - 1;
            int endY = Integer.parseInt(endCoords[1]) - 1;

            boolean possible = solve(grid, rows, cols, startX, startY, endX, endY);
            writer.println(possible ? "YES" : "NO");
        }
    }

    /**
     * Determines if a valid path exists according to the problem rules.
     */
    private static boolean solve(char[][] grid, int rows, int cols, int startX, int startY, int endX, int endY) {
        // Case 1: Start and end are the same
        if (startX == endX && startY == endY) {
            return countWalkableNeighbors(grid, rows, cols, startX, startY) >= 1;
        }

        // Case 2: Start and end are adjacent
        if (isAdjacent(startX, startY, endX, endY)) {
            if (grid[endX][endY] == 'X') {
                return true;
            }
            return countWalkableNeighbors(grid, rows, cols, endX, endY) >= 1;
        }

        // Case 3: General pathfinding via BFS
        boolean reached = bfs(grid, rows, cols, startX, startY, endX, endY);
        if (!reached) {
            return false;
        }

        // Additional constraint: if destination is '.', it needs at least 2 walkable neighbors
        if (grid[endX][endY] == '.') {
            return countWalkableNeighbors(grid, rows, cols, endX, endY) >= 2;
        }
        return true;
    }

    /**
     * Counts adjacent cells that contain '.' (walkable paths).
     */
    private static int countWalkableNeighbors(char[][] grid, int rows, int cols, int x, int y) {
        int count = 0;
        for (int i = 0; i < 4; i++) {
            int nx = x + DX[i];
            int ny = y + DY[i];
            if (isValid(rows, cols, nx, ny) && grid[nx][ny] == '.') {
                count++;
            }
        }
        return count;
    }

    /**
     * Checks if two coordinates are orthogonally adjacent.
     */
    private static boolean isAdjacent(int x1, int y1, int x2, int y2) {
        return Math.abs(x1 - x2) + Math.abs(y1 - y2) == 1;
    }

    /**
     * Performs BFS to determine if endX, endY is reachable from startX, startY.
     */
    private static boolean bfs(char[][] grid, int rows, int cols, int startX, int startY, int endX, int endY) {
        boolean[][] visited = new boolean[rows][cols];
        Queue<Point> queue = new ArrayDeque<>();
        queue.add(new Point(startX, startY));
        visited[startX][startY] = true;

        while (!queue.isEmpty()) {
            Point current = queue.poll();
            if (current.x == endX && current.y == endY) {
                return true;
            }

            for (int i = 0; i < 4; i++) {
                int nx = current.x + DX[i];
                int ny = current.y + DY[i];
                if (isValid(rows, cols, nx, ny) && !visited[nx][ny] && isWalkable(grid, nx, ny, endX, endY)) {
                    visited[nx][ny] = true;
                    queue.add(new Point(nx, ny));
                }
            }
        }
        return false;
    }

    /**
     * Checks if a cell is walkable: '.' always, or 'X' only if it's the destination.
     */
    private static boolean isWalkable(char[][] grid, int x, int y, int endX, int endY) {
        char cell = grid[x][y];
        if (cell == '.') {
            return true;
        }
        return cell == 'X' && x == endX && y == endY;
    }

    /**
     * Validates coordinates are within grid bounds.
     */
    private static boolean isValid(int rows, int cols, int x, int y) {
        return x >= 0 && x < rows && y >= 0 && y < cols;
    }

    /**
     * Immutable coordinate record for cleaner BFS state management.
     */
    private record Point(int x, int y) {}
}

import java.util.Scanner;

public class C540 {
    // Direction vectors for Up, Down, Left, Right
    private static final int[][] DIRECTIONS = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};

    private char[][] grid;
    private int rows;
    private int cols;
    private int targetRow;
    private int targetCol;

    public C540(int rows, int cols) {
        this.rows = rows;
        this.cols = cols;
        this.grid = new char[rows][cols];
    }

    public void readInput(Scanner scanner) {
        for (int i = 0; i < rows; i++) {
            grid[i] = scanner.next().toCharArray();
        }
        targetRow = scanner.nextInt() - 1;
        targetCol = scanner.nextInt() - 1;
    }

    public boolean canReach(int startRow, int startCol) {
        // Special case: Start and end coordinates are identical
        if (startRow == targetRow && startCol == targetCol) {
            return hasAdjacentEmptyCell(startRow, startCol);
        }

        boolean[][] visited = new boolean[rows][cols];
        return dfs(startRow, startCol, visited);
    }

    private boolean hasAdjacentEmptyCell(int r, int c) {
        for (int[] dir : DIRECTIONS) {
            int nr = r + dir[0];
            int nc = c + dir[1];
            if (isValid(nr, nc) && grid[nr][nc] == '.') {
                return true;
            }
        }
        return false;
    }

    private boolean dfs(int r, int c, boolean[][] visited) {
        if (r == targetRow && c == targetCol) {
            return true;
        }
        visited[r][c] = true;

        for (int[] dir : DIRECTIONS) {
            int nr = r + dir[0];
            int nc = c + dir[1];

            if (isValid(nr, nc) && !visited[nr][nc] && grid[nr][nc] == '.') {
                if (dfs(nr, nc, visited)) {
                    return true;
                }
            }
        }
        return false;
    }

    private boolean isValid(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        int m = scanner.nextInt();

        C540 solver = new C540(n, m);
        solver.readInput(scanner);

        int startRow = scanner.nextInt() - 1;
        int startCol = scanner.nextInt() - 1;

        if (solver.canReach(startRow, startCol)) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }
    }
}

import java.io.*;
import java.util.*;
import java.util.Locale;

public class Solution {
    private static final int[][] DIRECTIONS = {{0, 1}, {0, -1}, {-1, 0}, {1, 0}};
    private final IO io;

    public Solution(IO io) throws IOException {
        this.io = io;
        solve();
    }

    private void solve() throws IOException {
        int n = io.nI();
        int m = io.nI();

        boolean[][] traversable = new boolean[n][m];
        io.wc(".X");
        for (int i = 0; i < n; i++) {
            String row = io.nS();
            for (int j = 0; j < m; j++) {
                traversable[i][j] = row.charAt(j) == '.';
            }
        }

        int startX = io.nI() - 1;
        int startY = io.nI() - 1;
        int finishX = io.nI() - 1;
        int finishY = io.nI() - 1;

        // Special case: start and finish are the same cell
        if (startX == finishX && startY == finishY) {
            if (hasTraversableNeighbor(startX, startY, n, m, traversable)) {
                io.wln("YES");
            } else {
                io.wln("NO");
            }
            return;
        }

        // Standard BFS pathfinding
        if (bfs(startX, startY, finishX, finishY, n, m, traversable)) {
            // If finish cell is not traversable, path is still valid
            if (!traversable[finishX][finishY]) {
                io.wln("YES");
            } else {
                // Count valid neighbors of the finish cell
                int validNeighborCount = countValidFinishNeighbors(finishX, finishY, startX, startY, n, m, traversable);
                io.wln(validNeighborCount > 1 ? "YES" : "NO");
            }
        } else {
            io.wln("NO");
        }
    }

    private boolean hasTraversableNeighbor(int x, int y, int n, int m, boolean[][] traversable) {
        for (int[] dir : DIRECTIONS) {
            int nx = x + dir[0];
            int ny = y + dir[1];
            if (isValid(nx, ny, n, m) && traversable[nx][ny]) {
                return true;
            }
        }
        return false;
    }

    private boolean bfs(int startX, int startY, int finishX, int finishY, int n, int m, boolean[][] traversable) {
        boolean[][] visited = new boolean[n][m];
        Queue<Point> queue = new ArrayDeque<>();
        queue.add(new Point(startX, startY));
        visited[startX][startY] = true;

        while (!queue.isEmpty()) {
            Point current = queue.poll();

            if (current.x == finishX && current.y == finishY) {
                return true;
            }

            for (int[] dir : DIRECTIONS) {
                int nx = current.x + dir[0];
                int ny = current.y + dir[1];

                if (isValid(nx, ny, n, m) && !visited[nx][ny] && (traversable[nx][ny] || (nx == finishX && ny == finishY))) {
                    visited[nx][ny] = true;
                    queue.add(new Point(nx, ny));
                }
            }
        }
        return false;
    }

    private int countValidFinishNeighbors(int fx, int fy, int sx, int sy, int n, int m, boolean[][] traversable) {
        int count = 0;
        for (int[] dir : DIRECTIONS) {
            int nx = fx + dir[0];
            int ny = fy + dir[1];
            if (isValid(nx, ny, n, m) && (traversable[nx][ny] || (nx == sx && ny == sy))) {
                count++;
            }
        }
        return count;
    }

    private boolean isValid(int x, int y, int n, int m) {
        return x >= 0 && x < n && y >= 0 && y < m;
    }

    private static class Point {
        final int x, y;
        Point(int x, int y) {
            this.x = x;
            this.y = y;
        }
    }

    public static void main(String[] args) throws IOException {
        IO.launchSolution(args);
    }
}

class IO {
    private static final String LOCAL_ARG = "master_j";
    private static final String PROBLEM_NAME = "";
    private static final Mode IN_MODE = Mode.STD;
    private static final Mode OUT_MODE = Mode.STD;
    private static final boolean AUTO_FLUSH = false;

    enum Mode { STD, FILE, PROBLEM }

    private final StreamTokenizer st;
    private final BufferedReader br;
    private final Reader reader;
    private final PrintWriter pw;
    private final Writer writer;

    static void launchSolution(String[] args) throws IOException {
        boolean isLocal = args.length == 1 && args[0].equals(LOCAL_ARG);
        IO io = new IO(isLocal);

        long startTime = 0;
        if (isLocal) {
            startTime = System.nanoTime();
            io.wln("<output>");
        }

        io.flush();
        new Solution(io);
        io.flush();

        if (isLocal) {
            io.wln("</output>");
            long elapsed = System.nanoTime() - startTime;
            printTiming(io, elapsed);
        }

        io.close();
    }

    private static void printTiming(IO io, long elapsed) {
        if (elapsed >= 1_000_000_000) {
            io.wf("%d.%d seconds\n", elapsed / 1_000_000_000, elapsed % 1_000_000_000);
        } else if (elapsed >= 1_000_000) {
            io.wf("%d.%d millis\n", elapsed / 1_000_000, elapsed % 1_000_000);
        } else if (elapsed >= 1_000) {
            io.wf("%d.%d micros\n", elapsed / 1_000, elapsed % 1_000);
        } else {
            io.wf("%d nanos\n", elapsed);
        }
    }

    IO(boolean local) throws IOException {
        if (PROBLEM_NAME.isEmpty()) {
            if (IN_MODE == Mode.PROBLEM || OUT_MODE == Mode.PROBLEM) {
                throw new IllegalStateException("PROBLEM_NAME must be set when using PROBLEM mode.");
            }
        }

        Locale.setDefault(Locale.US);

        if (local) {
            reader = new FileReader("input.txt");
            writer = new OutputStreamWriter(System.out);
        } else {
            reader = resolveReader(IN_MODE);
            writer = resolveWriter(OUT_MODE);
        }

        br = new BufferedReader(reader);
        st = new StreamTokenizer(br);

        pw = new PrintWriter(writer, AUTO_FLUSH);

        if (local && AUTO_FLUSH) {
            wln("Note: auto-flush is on.");
        }
    }

    private Reader resolveReader(Mode mode) throws IOException {
        switch (mode) {
            case STD: return new InputStreamReader(System.in);
            case FILE: return new FileReader("input.txt");
            case PROBLEM: return new FileReader(PROBLEM_NAME + ".in");
            default: throw new IllegalStateException("Invalid input mode: " + mode);
        }
    }

    private Writer resolveWriter(Mode mode) throws IOException {
        switch (mode) {
            case STD: return new OutputStreamWriter(System.out);
            case FILE: return new FileWriter("output.txt");
            case PROBLEM: return new FileWriter(PROBLEM_NAME + ".out");
            default: throw new IllegalStateException("Invalid output mode: " + mode);
        }
    }

    // Output methods
    void wln()          { pw.println(); }
    void wln(boolean x) { pw.println(x); }
    void wln(char x)    { pw.println(x); }
    void wln(char x[])  { pw.println(x); }
    void wln(double x)  { pw.println(x); }
    void wln(float x)   { pw.println(x); }
    void wln(int x)     { pw.println(x); }
    void wln(long x)    { pw.println(x); }
    void wln(Object x)  { pw.println(x); }
    void wln(String x)  { pw.println(x); }

    void wf(String format, Object... args) { pw.printf(format, args); }

    void w(boolean x)   { pw.print(x); }
    void w(char x)      { pw.print(x); }
    void w(char x[])    { pw.print(x); }
    void w(double x)    { pw.print(x); }
    void w(float x)     { pw.print(x); }
    void w(int x)       { pw.print(x); }
    void w(long x)      { pw.print(x); }
    void w(Object x)    { pw.print(x); }
    void w(String x)    { pw.print(x); }

    // Input methods
    int nI() throws IOException { st.nextToken(); return (int) st.nval; }
    double nD() throws IOException { st.nextToken(); return st.nval; }
    float nF() throws IOException { st.nextToken(); return (float) st.nval; }
    long nL() throws IOException { st.nextToken(); return (long) st.nval; }
    String nS() throws IOException { st.nextToken(); return st.sval; }

    int[] nIa(int n) throws IOException {
        int[] a = new int[n];
        for (int i = 0; i < n; i++) a[i] = nI();
        return a;
    }
    double[] nDa(int n) throws IOException {
        double[] a = new double[n];
        for (int i = 0; i < n; i++) a[i] = nD();
        return a;
    }
    String[] nSa(int n) throws IOException {
        String[] a = new String[n];
        for (int i = 0; i < n; i++) a[i] = nS();
        return a;
    }

    // StreamTokenizer configuration
    void wc(String x) { wc(x.toCharArray()); }
    void wc(char c1, char c2) { for (char c = c1; c <= c2; c++) wc(c); }
    void wc(char x[]) { for (char c : x) wc(c); }
    void wc(char x) { st.ordinaryChar(x); st.wordChars(x, x); }

    public boolean eof() { return st.ttype == StreamTokenizer.TT_EOF; }
    public boolean eol() { return st.ttype == StreamTokenizer.TT_EOL; }

    void flush() { pw.flush(); }
    void close() throws IOException {
        reader.close();
        br.close();
        flush();
        pw.close();
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

/**
 * Solves a maze pathfinding problem.
 * Reads grid dimensions, the grid layout, start/target coordinates,
 * and determines if a valid path exists based on connectivity rules.
 */
public class MazePathSolver {

    private static final int[] DX = {0, -1, 0, 1};
    private static final int[] DY = {-1, 0, 1, 0};

    private final BufferedReader reader;
    private StringTokenizer tokenizer;

    /**
     * Initializes the solver with either standard input or a file.
     *
     * @param filePath Path to the input file, or null for standard input.
     */
    public MazePathSolver(String filePath) {
        if (filePath == null) {
            this.reader = new BufferedReader(new InputStreamReader(System.in));
        } else {
            try {
                this.reader = new BufferedReader(new InputStreamReader(new java.io.FileInputStream(filePath)));
            } catch (IOException e) {
                throw new RuntimeException("Failed to open input file: " + filePath, e);
            }
        }
    }

    public static void main(String[] args) {
        String filePath = args.length > 0 ? args[0] : null;
        new MazePathSolver(filePath).solve();
    }

    /**
     * Orchestrates input reading, validation, pathfinding, and output.
     */
    public void solve() {
        try {
            int n = nextInt();
            int m = nextInt();

            // Padding with 1 cell on all sides to eliminate boundary checks during traversal
            boolean[][] grid = new boolean[n + 2][m + 2];
            for (int i = 1; i <= n; i++) {
                String line = nextLine();
                for (int j = 1; j <= m; j++) {
                    grid[i][j] = line.charAt(j - 1) == '.';
                }
            }

            int startR = nextInt();
            int startC = nextInt();
            int targetR = nextInt();
            int targetC = nextInt();

            boolean canReach = checkAndFindPath(grid, startR, startC, targetR, targetC, n, m);
            System.out.println(canReach ? "YES" : "NO");
        } catch (Exception e) {
            System.err.println("Error processing input: " + e.getMessage());
        } finally {
            closeReader();
        }
    }

    /**
     * Validates target connectivity conditions and initiates pathfinding.
     */
    private boolean checkAndFindPath(boolean[][] grid, int startR, int startC, 
                                     int targetR, int targetC, int n, int m) {

        if (!grid[targetR][targetC]) {
            return false;
        }

        int openNeighbors = 0;
        for (int d = 0; d < 4; d++) {
            if (grid[targetR + DX[d]][targetC + DY[d]]) {
                openNeighbors++;
            }
        }

        if (openNeighbors < 2) {
            return false;
        } else if (openNeighbors == 1) {
            // If exactly one open neighbor exists, it must be the start position
            for (int d = 0; d < 4; d++) {
                if (targetR + DX[d] == startR && targetC + DY[d] == startC) {
                    return true; // Direct connection, no traversal needed
                }
            }
            return false;
        }

        // Perform DFS to check full connectivity from start to target
        boolean[][] visited = new boolean[n + 2][m + 2];
        return dfs(grid, startR, startC, targetR, targetC, visited);
    }

    /**
     * Recursive Depth-First Search to find a path.
     */
    private boolean dfs(boolean[][] grid, int r, int c, int targetR, int targetC, boolean[][] visited) {
        if (r == targetR && c == targetC) {
            return true;
        }
        visited[r][c] = true;

        for (int d = 0; d < 4; d++) {
            int nr = r + DX[d];
            int nc = c + DY[d];

            if (grid[nr][nc] && !visited[nr][nc]) {
                if (dfs(grid, nr, nc, targetR, targetC, visited)) {
                    return true;
                }
            }
        }
        return false;
    }

    /**
     * Returns the next whitespace-delimited token, automatically reading new lines as needed.
     */
    private String next() {
        while (tokenizer == null || !tokenizer.hasMoreTokens()) {
            try {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            } catch (IOException e) {
                throw new RuntimeException("IO error while reading input", e);
            }
        }
        return tokenizer.nextToken();
    }

    /**
     * Parses the next token as an integer.
     */
    private int nextInt() {
        String token = next();
        if (token == null) {
            throw new IllegalArgumentException("Unexpected end of input");
        }
        return Integer.parseInt(token);
    }

    /**
     * Reads and returns the next full line of input.
     */
    private String nextLine() {
        try {
            String line = reader.readLine();
            if (line == null) {
                throw new IllegalArgumentException("Unexpected end of input");
            }
            return line;
        } catch (IOException e) {
            throw new RuntimeException("IO error while reading line", e);
        }
    }

    /**
     * Safely closes the input reader.
     */
    private void closeReader() {
        try {
            if (reader != null) {
                reader.close();
            }
        } catch (IOException e) {
            System.err.println("Failed to close input reader: " + e.getMessage());
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

/**
 * Refactored version of Task540C.
 * 
 * Improvements made:
 * 1. Encapsulation: Removed static state variables in favor of instance fields.
 * 2. Readability: Replaced hardcoded boundary checks and neighbor logic with 
 *    direction vectors (DR, DC) and helper methods.
 * 3. Efficiency: DFS now returns a boolean and terminates early upon finding a path.
 * 4. Robustness: Improved InputScanner to handle empty lines and EOF gracefully.
 * 5. Naming: Used descriptive variable names (grid, startR, etc.).
 */
public class Task540C {

    // Direction vectors for Up, Down, Left, Right
    private static final int[] DR = {-1, 1, 0, 0};
    private static final int[] DC = {0, 0, -1, 1};

    private int n, m;
    private char[][] grid;
    private boolean[][] visited;
    private int startR, startC, endR, endC;

    public static void main(String[] args) {
        Task540C solver = new Task540C();
        solver.solve();
    }

    public void solve() {
        InputScanner sc = new InputScanner();
        try {
            // Read dimensions
            n = sc.nextInt();
            m = sc.nextInt();

            grid = new char[n][];
            visited = new boolean[n][m];

            // Read grid rows
            for (int i = 0; i < n; i++) {
                grid[i] = sc.next().toCharArray();
            }

            // Read coordinates (convert 1-based to 0-based)
            startR = sc.nextInt() - 1;
            startC = sc.nextInt() - 1;
            endR = sc.nextInt() - 1;
            endC = sc.nextInt() - 1;

            // Ensure start position is traversable
            grid[startR][startC] = '.';

            // Check if start and end are the same position
            if (startR == endR && startC == endC) {
                if (countOpenNeighbors(startR, startC) > 0) {
                    System.out.println("YES");
                    return;
                }
            }

            // Perform DFS from end to start to find a path
            boolean pathFound = dfs(endR, endC, startR, startC);

            if (pathFound) {
                // Logic derived from original code:
                // If end position is 'X', YES.
                // Else if end position has > 1 open neighbors, YES.
                if (grid[endR][endC] == 'X' || countOpenNeighbors(endR, endC) > 1) {
                    System.out.println("YES");
                } else {
                    System.out.println("NO");
                }
            } else {
                System.out.println("NO");
            }

        } catch (IOException e) {
            // In a real application, handle logging properly. 
            // For CP, printing stack trace is acceptable for debugging.
            e.printStackTrace();
        }
    }

    /**
     * Depth First Search to find if a path exists from (r, c) to (targetR, targetC).
     * Returns true if path is found, false otherwise.
     */
    private boolean dfs(int r, int c, int targetR, int targetC) {
        // Base case: Target reached
        if (r == targetR && c == targetC) {
            return true;
        }

        visited[r][c] = true;

        // Explore neighbors using direction vectors
        for (int i = 0; i < 4; i++) {
            int nr = r + DR[i];
            int nc = c + DC[i];

            // Check if neighbor is valid and not visited
            if (isValid(nr, nc) && !visited[nr][nc]) {
                if (dfs(nr, nc, targetR, targetC)) {
                    return true; // Path found, propagate true up
                }
            }
        }
        return false;
    }

    /**
     * Checks if a cell is within bounds and is traversable ('.').
     */
    private boolean isValid(int r, int c) {
        return r >= 0 && r < n && c >= 0 && c < m && grid[r][c] == '.';
    }

    /**
     * Counts the number of open ('.') neighbors for a given cell.
     */
    private int countOpenNeighbors(int r, int c) {
        int count = 0;
        for (int i = 0; i < 4; i++) {
            int nr = r + DR[i];
            int nc = c + DC[i];
            if (isValid(nr, nc)) {
                count++;
            }
        }
        return count;
    }

    /**
     * Helper class for fast input reading.
     */
    static class InputScanner {
        BufferedReader br;
        StringTokenizer st;

        public InputScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        public String next() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) return null;
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

        public int nextInt() throws IOException {
            String s = next();
            if (s == null) throw new IOException("Unexpected end of input");
            return Integer.parseInt(s);
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.OutputStreamWriter;
import java.io.PrintWriter;
import java.util.ArrayDeque;
import java.util.Queue;
import java.util.StringTokenizer;

public class IceMeltingSolver {

    private static final int[][] DIRECTIONS = {{0, 1}, {0, -1}, {1, 0}, {-1, 0}};
    private static final char EMPTY = '.';
    private static final char ICE = 'X';
    private static final String RESULT_YES = "YES";
    private static final String RESULT_NO = "NO";

    private int rows;
    private int cols;
    private char[][] grid;
    private boolean[][] visited;
    private int startRow, startCol, endRow, endCol;

    private BufferedReader in;
    private PrintWriter out;
    private StringTokenizer tokenizer;

    public static void main(String[] args) {
        IceMeltingSolver solver = new IceMeltingSolver();
        try {
            solver.execute();
        } catch (IOException e) {
            e.printStackTrace();
            System.exit(1);
        }
    }

    private void execute() throws IOException {
        in = new BufferedReader(new InputStreamReader(System.in));
        out = new PrintWriter(new OutputStreamWriter(System.out));
        try {
            solve();
        } finally {
            out.flush();
            out.close();
            in.close();
        }
    }

    private void solve() throws IOException {
        rows = nextInt();
        cols = nextInt();
        grid = new char[rows][cols];
        visited = new boolean[rows][cols];

        for (int i = 0; i < rows; i++) {
            grid[i] = next().toCharArray();
        }

        startRow = nextInt() - 1;
        startCol = nextInt() - 1;
        endRow = nextInt() - 1;
        endCol = nextInt() - 1;

        // Ensure start position is treated as walkable water
        if (grid[startRow][startCol] == ICE) {
            grid[startRow][startCol] = EMPTY;
        }

        if (startRow == endRow && startCol == endCol) {
            out.println(isReachable(startRow, startCol, true) ? RESULT_YES : RESULT_NO);
            return;
        }

        bfs(startRow, startCol);
    }

    private void bfs(int startR, int startC) {
        Queue<int[]> queue = new ArrayDeque<>();
        queue.offer(new int[]{startR, startC});
        visited[startR][startC] = true;

        while (!queue.isEmpty()) {
            int[] current = queue.poll();
            int r = current[0];
            int c = current[1];

            for (int[] dir : DIRECTIONS) {
                int nr = r + dir[0];
                int nc = c + dir[1];

                // Boundary check
                if (nr < 0 || nr >= rows || nc < 0 || nc >= cols) {
                    continue;
                }

                // Skip already visited cells
                if (visited[nr][nc]) {
                    continue;
                }

                // Check if destination is reached
                if (nr == endRow && nc == endCol) {
                    if (grid[nr][nc] == EMPTY || isReachable(nr, nc, false)) {
                        out.println(RESULT_YES);
                        return;
                    }
                }
                // Expand to empty/water cells
                else if (grid[nr][nc] == EMPTY) {
                    visited[nr][nc] = true;
                    queue.offer(new int[]{nr, nc});
                }
            }
        }
        out.println(RESULT_NO);
    }

    /**
     * Determines if a cell is reachable based on ice melting rules.
     * Ice melts if it has more than 1 adjacent empty cell.
     * Start position is reachable if it has more than 0 adjacent empty cells.
     */
    private boolean isReachable(int r, int c, boolean requireAtLeastOneNeighbor) {
        int emptyNeighbors = 0;
        for (int[] dir : DIRECTIONS) {
            int nr = r + dir[0];
            int nc = c + dir[1];
            if (nr >= 0 && nr < rows && nc >= 0 && nc < cols && grid[nr][nc] == EMPTY) {
                emptyNeighbors++;
            }
        }
        return requireAtLeastOneNeighbor ? emptyNeighbors > 0 : emptyNeighbors > 1;
    }

    private String next() throws IOException {
        while (tokenizer == null || !tokenizer.hasMoreTokens()) {
            String line = in.readLine();
            if (line == null) {
                return null;
            }
            tokenizer = new StringTokenizer(line);
        }
        return tokenizer.nextToken();
    }

    private int nextInt() throws IOException {
        String token = next();
        if (token == null) {
            throw new IOException("Unexpected end of input");
        }
        return Integer.parseInt(token);
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

/**
 * Solves a grid-based pathfinding problem using Depth-First Search (DFS).
 * Determines reachability and path conditions based on specific grid constraints.
 */
public class GridPathSolver {

    private final int rows;
    private final int cols;
    private final char[][] grid;
    private final int startRow;
    private final int startCol;
    private final int endRow;
    private final int endCol;
    private final char endChar;
    private int pathCount;
    private boolean[][] visited;

    /**
     * Initializes the solver with grid dimensions, layout, and path endpoints.
     *
     * @param rows     Number of rows in the grid
     * @param cols     Number of columns in the grid
     * @param grid     2D character array representing the grid
     * @param startRow Start row (0-indexed)
     * @param startCol Start column (0-indexed)
     * @param endRow   End row (0-indexed)
     * @param endCol   End column (0-indexed)
     * @param endChar  Character at the destination cell
     */
    public GridPathSolver(int rows, int cols, char[][] grid, int startRow, int startCol, 
                          int endRow, int endCol, char endChar) {
        this.rows = rows;
        this.cols = cols;
        this.grid = grid;
        this.startRow = startRow;
        this.startCol = startCol;
        this.endRow = endRow;
        this.endCol = endCol;
        this.endChar = endChar;
        this.pathCount = 0;
        this.visited = new boolean[rows][cols];
    }

    /**
     * Executes the pathfinding algorithm and returns the result.
     *
     * @return true if path conditions are met, false otherwise
     */
    public boolean solve() {
        // Temporarily clear start and end positions to allow traversal
        char originalStart = grid[startRow][startCol];
        char originalEnd = grid[endRow][endCol];
        grid[startRow][startCol] = '.';
        grid[endRow][endCol] = '.';

        dfs(startRow, startCol);

        // Restore grid to its original state
        grid[startRow][startCol] = originalStart;
        grid[endRow][endEnd] = originalEnd;

        // Replicate original evaluation logic with clear semantics
        boolean conditionFirst = pathCount >= 1 && endChar == 'X' && (endCol != startCol || endRow != startRow);
        boolean conditionSecond = pathCount >= 2;
        return conditionFirst || conditionSecond;
    }

    /**
     * Recursively explores the grid using DFS.
     *
     * @param r Current row
     * @param c Current column
     */
    private void dfs(int r, int c) {
        // Base case: reached destination
        if (r == endRow && c == endCol) {
            pathCount++;
            // Preserve original early-return logic for specific target configurations
            if (endChar == 'X' && (startCol != endCol && startRow != endRow)) {
                return;
            }
        }

        // Boundary and visited checks
        if (!isValid(r, c) || visited[r][c]) {
            return;
        }

        // Treat 'X' as a wall/obstacle
        if (grid[r][c] == 'X') {
            visited[r][c] = true;
            return;
        }

        // Mark current cell as visited
        visited[r][c] = true;

        // Explore all four cardinal directions
        int[] dr = {-1, 1, 0, 0};
        int[] dc = {0, 0, -1, 1};

        for (int i = 0; i < 4; i++) {
            int nr = r + dr[i];
            int nc = c + dc[i];
            dfs(nr, nc);
        }
    }

    /**
     * Checks if coordinates are within grid boundaries.
     *
     * @param r Row index
     * @param c Column index
     * @return true if valid, false otherwise
     */
    private boolean isValid(int r, int c) {
        return r >= 0 && c >= 0 && r < rows && c < cols;
    }

    public static void main(String[] args) {
        FastReader reader = new FastReader();
        try {
            int n = reader.nextInt();
            int m = reader.nextInt();

            char[][] grid = new char[n][m];
            for (int i = 0; i < n; i++) {
                grid[i] = reader.next().toCharArray();
            }

            int startRow = reader.nextInt() - 1;
            int startCol = reader.nextInt() - 1;
            int endRow = reader.nextInt() - 1;
            int endCol = reader.nextInt() - 1;

            char endChar = grid[endRow][endCol];

            GridPathSolver solver = new GridPathSolver(n, m, grid, startRow, startCol, endRow, endCol, endChar);
            boolean result = solver.solve();

            System.out.println(result ? "YES" : "NO");
        } catch (Exception e) {
            System.err.println("Error processing input: " + e.getMessage());
        }
    }

    /**
     * Utility class for fast console input reading.
     */
    static class FastReader {
