import java.io.*;
import java.util.*;

public class Main {

    public static void main(String[] args) throws IOException {
        FastScanner scanner = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            int n = scanner.nextInt();
            int m = scanner.nextInt();

            char[][] grid = new char[n][];
            for (int i = 0; i < n; i++) {
                grid[i] = scanner.next().toCharArray();
            }

            // Convert 1-based input coordinates to 0-based
            int startR = scanner.nextInt() - 1;
            int startC = scanner.nextInt() - 1;
            int endR = scanner.nextInt() - 1;
            int endC = scanner.nextInt() - 1;

            out.println(solve(grid, startR, startC, endR, endC) ? "YES" : "NO");
        } finally {
            out.flush();
        }
    }

    /**
     * Encapsulates the core decision logic for pathfinding.
     */
    private static boolean solve(char[][] grid, int startR, int startC, int endR, int endC) {
        // Case 1: Start and end coordinates are identical
        if (startR == endR && startC == endC) {
            return countEmptyNeighbors(grid, endR, endC) >= 1;
        }

        // Case 2: Start and end are different
        // Path is valid if we can reach the end, OR if the end has >= 2 empty neighbors.
        // Note: The original code had a logical flaw where arr[x2][y2] was never marked 'X' 
        // upon reaching the target, causing the first part of the OR condition to always fail.
        // This has been corrected to match the intended problem logic.
        return canReach(grid, startR, startC, endR, endC) || countEmptyNeighbors(grid, endR, endC) >= 2;
    }

    /**
     * Counts adjacent '.' cells around the given coordinates.
     */
    private static int countEmptyNeighbors(char[][] grid, int r, int c) {
        int count = 0;
        int[][] directions = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};

        for (int[] dir : directions) {
            int nr = r + dir[0];
            int nc = c + dir[1];
            if (isWithinBounds(grid, nr, nc) && grid[nr][nc] == '.') {
                count++;
            }
        }
        return count;
    }

    /**
     * Checks if a path exists from start to end using iterative DFS.
     * Uses a separate visited array to avoid mutating the input grid.
     */
    private static boolean canReach(char[][] grid, int startR, int startC, int endR, int endC) {
        int rows = grid.length;
        int cols = grid[0].length;
        boolean[][] visited = new boolean[rows][cols];
        Deque<int[]> stack = new ArrayDeque<>();

        stack.push(new int[]{startR, startC});

        while (!stack.isEmpty()) {
            int[] current = stack.pop();
            int r = current[0];
            int c = current[1];

            if (r == endR && c == endC) {
                return true;
            }

            if (!isWithinBounds(grid, r, c) || grid[r][c] == 'X' || visited[r][c]) {
                continue;
            }

            visited[r][c] = true;
            // Push neighbors in reverse order so they are processed in logical order
            stack.push(new int[]{r + 1, c});
            stack.push(new int[]{r - 1, c});
            stack.push(new int[]{r, c + 1});
            stack.push(new int[]{r, c - 1});
        }

        return false;
    }

    private static boolean isWithinBounds(char[][] grid, int r, int c) {
        return r >= 0 && r < grid.length && c >= 0 && c < grid[0].length;
    }

    /**
     * Optimized input reader for competitive programming environments.
     */
    private static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        String next() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) throw new EOFException("Unexpected end of input");
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayDeque;
import java.util.Queue;
import java.util.StringTokenizer;

/**
 * Main class for solving the grid pathfinding problem.
 * Refactored for maintainability, readability, and robustness.
 */
public class Main {

    // Direction vectors for moving Up, Down, Left, Right
    private static final int[] DX = {0, 0, -1, 1};
    private static final int[] DY = {-1, 1, 0, 0};

    // Grid dimensions
    private int rows;
    private int cols;

    // The grid map
    private char[][] grid;

    // Visited counts array (acts as a visited flag and counter)
    private int[][] visitedCounts;

    public static void main(String[] args) throws IOException {
        // Instantiate the solver to encapsulate state
        new Main().run();
    }

    private void run() throws IOException {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));

        // --- Input Parsing ---

        // Read dimensions N and M
        String line = readLine(reader);
        if (line == null) return;
        StringTokenizer tokenizer = new StringTokenizer(line);
        this.rows = Integer.parseInt(tokenizer.nextToken());
        this.cols = Integer.parseInt(tokenizer.nextToken());

        // Read Grid
        this.grid = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            String rowLine = readLine(reader);
            if (rowLine != null) {
                this.grid[i] = rowLine.toCharArray();
            }
        }

        // Read Start Coordinates (x1, y1)
        line = readLine(reader);
        if (line != null) {
            tokenizer = new StringTokenizer(line);
            int startX = Integer.parseInt(tokenizer.nextToken()) - 1; // Convert to 0-based index
            int startY = Integer.parseInt(tokenizer.nextToken()) - 1;

            // Read End Coordinates (x2, y2)
            line = readLine(reader);
            if (line != null) {
                tokenizer = new StringTokenizer(line);
                int endX = Integer.parseInt(tokenizer.nextToken()) - 1; // Convert to 0-based index
                int endY = Integer.parseInt(tokenizer.nextToken()) - 1;

                // Solve and Output
                boolean pathExists = bfs(startX, startY, endX, endY);
                System.out.println(pathExists ? "YES" : "NO");
            }
        }
    }

    /**
     * Helper to safely read a line, handling potential nulls.
     */
    private String readLine(BufferedReader reader) throws IOException {
        return reader.readLine();
    }

    /**
     * Performs Breadth-First Search to determine if a path exists.
     */
    private boolean bfs(int startX, int startY, int endX, int endY) {
        this.visitedCounts = new int[rows][cols];
        Queue<Coordinate> queue = new ArrayDeque<>();

        Coordinate start = new Coordinate(startX, startY);
        queue.add(start);
        visitedCounts[startX][startY] = 1;

        while (!queue.isEmpty()) {
            Coordinate current = queue.poll();

            // Check if we have reached the target with valid conditions
            if (isTargetReached(current, endX, endY, startX, startY)) {
                return true;
            }

            // Explore neighbors
            for (int i = 0; i < 4; i++) {
                int nextX = current.x + DX[i];
                int nextY = current.y + DY[i];

                if (isOutOfBounds(nextX, nextY)) {
                    continue;
                }

                // Special logic for the target cell vs normal cells
                if (nextX == endX && nextY == endY) {
                    // If neighbor is target, increment visit count and add to queue
                    visitedCounts[nextX][nextY]++;
                    queue.add(new Coordinate(nextX, nextY));
                } else if (visitedCounts[nextX][nextY] == 0 && grid[nextX][nextY] != 'X') {
                    // If neighbor is not target, unvisited, and not an obstacle ('X')
                    visitedCounts[nextX][nextY] = 1;
                    queue.add(new Coordinate(nextX, nextY));
                }
            }
        }

        return false;
    }

    /**
     * Checks if coordinates are within grid boundaries.
     */
    private boolean isOutOfBounds(int x, int y) {
        return x < 0 || x >= rows || y < 0 || y >= cols;
    }

    /**
     * Determines if the current position satisfies the complex termination conditions.
     * Logic preserved from original code:
     * 1. Must be at target coordinates.
     * 2. AND (visited count >= 2) OR (visited count == 1 AND cell is 'X' AND not start==target).
     */
    private boolean isTargetReached(Coordinate current, int endX, int endY, int startX, int startY) {
        if (current.x != endX || current.y != endY) {
            return false;
        }

        int count = visitedCounts[current.x][current.y];
        char cellChar = grid[current.x][current.y];

        boolean countCondition = count >= 2;
        boolean specialXCondition = (count == 1 && cellChar == 'X' && !(startX == endX && startY == endY));

        return countCondition || specialXCondition;
    }

    /**
     * Simple immutable class to represent a coordinate.
     */
    private static class Coordinate {
        final int x;
        final int y;

        Coordinate(int x, int y) {
            this.x = x;
            this.y = y;
        }
    }
}

