/**
 * Handles the core logic for determining path connectivity in the grid.
 */
class Solver {
    /**
     * Reads grid dimensions and contents, then determines if the target is reachable.
     */
    public void solve(InputReader in, PrintWriter out) {
        int rows = in.nextInt();
        int cols = in.nextInt();

        char[][] board = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            String line = in.next();
            board[i] = line.toCharArray();
        }

        // Convert 1-based input coordinates to 0-based
        int startRow = in.nextInt() - 1;
        int startCol = in.nextInt() - 1;
        int targetRow = in.nextInt() - 1;
        int targetCol = in.nextInt() - 1;

        // The starting position is always empty
        board[startRow][startCol] = '.';

        boolean[][] visited = new boolean[rows][cols];
        boolean canReach = dfs(board, visited, startRow, startCol, targetRow, targetCol);

        out.println(canReach ? "YES" : "NO");
    }

    /**
     * Performs Depth-First Search to find a path to the target.
     */
    private boolean dfs(char[][] board, boolean[][] visited, int row, int col, int targetRow, int targetCol) {
        // Boundary checks
        if (row < 0 || row >= board.length || col < 0 || col >= board[0].length) {
            return false;
        }

        // Check if we reached the target coordinates
        if (row == targetRow && col == targetCol) {
            return isTargetReachable(board, targetRow, targetCol);
        }

        // Skip already visited cells or blocked ('X') cells
        if (visited[row][col] || board[row][col] == 'X') {
            return false;
        }

        // Mark current cell as visited
        visited[row][col] = true;

        // Explore all 4 cardinal directions
        if (dfs(board, visited, row - 1, col, targetRow, targetCol) ||
            dfs(board, visited, row + 1, col, targetRow, targetCol) ||
            dfs(board, visited, row, col - 1, targetRow, targetCol) ||
            dfs(board, visited, row, col + 1, targetRow, targetCol)) {
            return true;
        }

        return false;
    }

    /**
     * Determines if the target cell satisfies reachability conditions.
     * A target is reachable if it is already empty, or if any adjacent cell is empty.
     */
    private boolean isTargetReachable(char[][] board, int targetRow, int targetCol) {
        if (board[targetRow][targetCol] == '.') {
            return true;
        }

        if (board[targetRow][targetCol] == 'X') {
            int[][] directions = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};
            for (int[] dir : directions) {
                int r = targetRow + dir[0];
                int c = targetCol + dir[1];
                if (r >= 0 && r < board.length && c >= 0 && c < board[0].length && board[r][c] == '.') {
                    return true;
                }
            }
        }
        return false;
    }
}

