import java.util.LinkedList;
import java.util.Queue;
import java.util.Scanner;

/**
 * Solves the Ice Cave pathfinding problem.
 * Refactored for maintainability, encapsulation, and code quality.
 */
public class IceCave {

    // Grid dimensions
    private int rows;
    private int cols;

    // Grid data
    private char[][] grid;

    // Start and End coordinates
    private Point startPoint;
    private Point endPoint;

    // Directions: Down, Left, Up, Right
    private static final int[][] DIRECTIONS = {
        {1, 0}, {0, -1}, {-1, 0}, {0, 1}
    };

    /**
     * Represents a coordinate in the grid.
     * Encapsulated with private fields and a constructor.
     */
    private static class Point {
        int x;
        int y;

        Point(int x, int y) {
            this.x = x;
            this.y = y;
        }
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        // Check for valid input to prevent exceptions
        if (scanner.hasNextInt()) {
            IceCave solver = new IceCave();
            solver.readInput(scanner);
            System.out.println(solver.solve());
        }

        scanner.close();
    }

    /**
     * Reads grid dimensions, the grid itself, and start/end points from the scanner.
     */
    private void readInput(Scanner scanner) {
        this.rows = scanner.nextInt();
        this.cols = scanner.nextInt();

        this.grid = new char[this.rows][];

        for (int i = 0; i < this.rows; i++) {
            // Using next() handles whitespace skipping automatically
            String line = scanner.next();
            this.grid[i] = line.toCharArray();
        }

        // Adjust 1-based input coordinates to 0-based indexing
        int startRow = scanner.nextInt() - 1;
        int startCol = scanner.nextInt() - 1;
        this.startPoint = new Point(startRow, startCol);

        int endRow = scanner.nextInt() - 1;
        int endCol = scanner.nextInt() - 1;
        this.endPoint = new Point(endRow, endCol);
    }

    /**
     * Checks if the given coordinates are within the grid boundaries.
     */
    private boolean isWithinBounds(int x, int y) {
        return x >= 0 && x < this.rows && y >= 0 && y < this.cols;
    }

    /**
     * Executes the BFS algorithm to determine if the destination is reachable.
     * 
     * @return "YES" if reachable/breakable, "NO" otherwise.
     */
    private String solve() {
        // Basic validation for coordinates
        if (!isWithinBounds(startPoint.x, startPoint.y) || !isWithinBounds(endPoint.x, endPoint.y)) {
            return "NO";
        }

        // Mark start position as visited to prevent infinite loops.
        // We change '.' to 'X' to denote visited status.
        // If the start is already 'X' (and not the destination), we are on ice.
        if (grid[startPoint.x][startPoint.y] == '.') {
            grid[startPoint.x][startPoint.y] = 'X';
        }

        Queue<Point> queue = new LinkedList<>();
        queue.add(startPoint);

        while (!queue.isEmpty()) {
            Point current = queue.poll();

            for (int[] dir : DIRECTIONS) {
                int nextX = current.x + dir[0];
                int nextY = current.y + dir[1];

                if (isWithinBounds(nextX, nextY)) {
                    // Check if this neighbor is the destination
                    if (nextX == endPoint.x && nextY == endPoint.y) {
                        // Logic preserved from original code:
                        // If destination is 'X' (Ice), we can break it -> YES
                        if (grid[nextX][nextY] == 'X') {
                            return "YES";
                        } 
                        // If destination is '.', mark as visited and continue BFS
                        // (Original logic treated '.' destination as a standard cell to traverse)
                        else {
                            grid[nextX][nextY] = 'X'; // Mark visited
                            queue.add(new Point(nextX, nextY));
                        }
                    }
                    // If not destination, check if walkable (and not visited)
                    else if (grid[nextX][nextY] == '.') {
                        grid[nextX][nextY] = 'X'; // Mark visited
                        queue.add(new Point(nextX, nextY));
                    }
                }
            }
        }
        return "NO";
    }
}

import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) {
        FastScanner sc = new FastScanner(System.in);
        // try-with-resources ensures PrintWriter is properly flushed and closed
        try (PrintWriter out = new PrintWriter(System.out)) {
            GridPathSolver solver = new GridPathSolver(sc);
            out.println(solver.solve());
        }
    }

    /**
     * Encapsulates grid state, pathfinding logic, and problem-specific rules.
     * Replaces scattered static fields and improves maintainability.
     */
    static class GridPathSolver {
        private final int rows;
        private final int cols;
        private final char[][] grid;
        private final boolean[][] visited;
        private final int startRow, startCol;
        private final int targetRow, targetCol;

        public GridPathSolver(FastScanner sc) {
            this.rows = sc.nextInt();
            this.cols = sc.nextInt();
            this.grid = new char[rows][cols];
            this.visited = new boolean[rows][cols];

            for (int i = 0; i < rows; i++) {
                String line = sc.next();
                grid[i] = line.toCharArray();
            }

            // Convert 1-based input coordinates to 0-based
            this.startRow = sc.nextInt() - 1;
            this.startCol = sc.nextInt() - 1;
            this.targetRow = sc.nextInt() - 1;
            this.targetCol = sc.nextInt() - 1;
        }

        /**
         * Determines the answer based on the problem's branching logic.
         */
        public String solve() {
            // Case 1: Start and target are the same cell
            if (startRow == targetRow && startCol == targetCol) {
                return countWalkableNeighbors(startRow, startCol) > 0 ? "YES" : "NO";
            }

            // Case 2: Start and target are adjacent
            if (areAdjacent(startRow, startCol, targetRow, targetCol)) {
                if (grid[targetRow][targetCol] == 'X') {
                    return "YES";
                }
                return countWalkableNeighbors(targetRow, targetCol) > 0 ? "YES" : "NO";
            }

            // Case 3: Target is not adjacent; check path reachability
            boolean reachable = bfs(startRow, startCol, targetRow, targetCol);
            if (!reachable) {
                return "NO";
            }

            if (grid[targetRow][targetCol] == 'X') {
                return "YES";
            }
            return countWalkableNeighbors(targetRow, targetCol) >= 2 ? "YES" : "NO";
        }

        /**
         * Checks if a cell is within bounds and walkable ('.').
         */
        private boolean isWalkable(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols && grid[r][c] == '.';
        }

        /**
         * Counts how many adjacent cells are walkable.
         */
        private int countWalkableNeighbors(int r, int c) {
            int count = 0;
            if (isWalkable(r + 1, c)) count++;
            if (isWalkable(r, c + 1)) count++;
            if (isWalkable(r - 1, c)) count++;
            if (isWalkable(r, c - 1)) count++;
            return count;
        }

        /**
         * Checks if two cells are orthogonally adjacent.
         */
        private boolean areAdjacent(int r1, int c1, int r2, int c2) {
            return Math.abs(r1 - r2) + Math.abs(c1 - c2) == 1;
        }

        /**
         * Iterative BFS to determine if target is reachable from start through '.' cells.
         * Safer than recursion for large grids (avoids StackOverflowError).
         */
        private boolean bfs(int startR, int startC, int targetR, int targetC) {
            Queue<int[]> queue = new ArrayDeque<>();
            queue.offer(new int[]{startR, startC});
            visited[startR][startC] = true;

            int[] dr = {1, -1, 0, 0};
            int[] dc = {0, 0, 1, -1};

            while (!queue.isEmpty()) {
                int[] curr = queue.poll();
                for (int i = 0; i < 4; i++) {
                    int nr = curr[0] + dr[i];
                    int nc = curr[1] + dc[i];

                    if (isWalkable(nr, nc) && !visited[nr][nc]) {
                        if (nr == targetR && nc == targetC) {
                            return true;
                        }
                        visited[nr][nc] = true;
                        queue.offer(new int[]{nr, nc});
                    }
                }
            }
            return false;
        }
    }

    /**
     * Fast I/O utility for competitive programming / large input scenarios.
     */
    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) throw new EOFException("Unexpected end of input");
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input", e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.util.LinkedList;
import java.util.Queue;
import java.util.Scanner;

/**
 * Refactored solution for the Ice Cave pathfinding problem.
 * 
 * Improvements made:
 * 1. Naming Conventions: Used descriptive names (Coordinate, ROW_OFFSETS, etc.) instead of single letters.
 * 2. Structure: Separated logic into methods (solveBFS, isValidPosition) for better readability and testing.
 * 3. Resource Management: Used try-with-resources for the Scanner to prevent resource leaks.
 * 4. Logic Safety: Replaced grid mutation with a separate 'visited' array to prevent side effects and potential infinite loops.
 * 5. Input Handling: Added bounds checking during input reading to prevent IndexOutOfBoundsException.
 * 6. Output Consistency: Standardized output to use println.
 */
public class Main {

    /**
     * Represents a coordinate in the 2D grid.
     */
    private static class Coordinate {
        final int row;
        final int col;

        public Coordinate(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    // Direction vectors for Up, Down, Left, Right movements
    private static final int[] ROW_OFFSETS = {-1, 1, 0, 0};
    private static final int[] COL_OFFSETS = {0, 0, -1, 1};

    public static void main(String[] args) {
        // Use try-with-resources to ensure the Scanner is closed automatically
        try (Scanner scanner = new Scanner(System.in)) {

            // Read grid dimensions
            if (!scanner.hasNextInt()) return;
            int rows = scanner.nextInt();
            int columns = scanner.nextInt();
            scanner.nextLine(); // Consume the newline character after reading integers

            // Read the grid data
            char[][] grid = new char[rows][columns];
            for (int i = 0; i < rows; i++) {
                String line = scanner.nextLine().trim();
                // Fill the row safely, handling cases where line length might be shorter than columns
                for (int j = 0; j < columns && j < line.length(); j++) {
                    grid[i][j] = line.charAt(j);
                }
            }

            // Read start and end positions (converting 1-based input to 0-based index)
            int startRow = scanner.nextInt() - 1;
            int startCol = scanner.nextInt() - 1;
            int endRow = scanner.nextInt() - 1;
            int endCol = scanner.nextInt() - 1;

            // Execute BFS and print the result
            boolean pathFound = solveBFS(grid, rows, columns, startRow, startCol, endRow, endCol);
            System.out.println(pathFound ? "YES" : "NO");

        } catch (Exception e) {
            // In a production environment, log the exception. 
            // For algorithmic problems, we assume valid input format.
            e.printStackTrace();
        }
    }

    /**
     * Performs a Breadth-First Search (BFS) to determine if a path exists.
     * 
     * Logic Interpretation:
     * - 'X' represents a target or specific tile.
     * - Non-'X' characters represent walkable paths.
     * - When traversing a walkable path, it is marked as visited (logically equivalent to turning it into 'X').
     * - If a neighbor is 'X', it is checked against the end position.
     */
    private static boolean solveBFS(char[][] grid, int rows, int cols, 
                                    int startRow, int startCol, 
                                    int endRow, int endCol) {

        Queue<Coordinate> queue = new LinkedList<>();
        queue.add(new Coordinate(startRow, startCol));

        // Visited array to track processed cells and prevent cycles.
        // This is cleaner than modifying the grid array directly.
        boolean[][] visited = new boolean[rows][cols];

        // Mark the start position as visited
        visited[startRow][startCol] = true;

        while (!queue.isEmpty()) {
            Coordinate current = queue.poll();
            int r = current.row;
            int c = current.col;

            // Explore all 4 possible directions
            for (int i = 0; i < 4; i++) {
                int newR = r + ROW_OFFSETS[i];
                int newC = c + COL_OFFSETS[i];

                if (isValidPosition(newR, newC, rows, cols)) {

                    // Check if the neighbor is the target 'X'
                    if (grid[newR][newC] == 'X') {
                        if (newR == endRow && newC == endCol) {
                            return true;
                        }
                        // If it is 'X' but not the end, it acts as a wall/obstacle in this logic.
                    } else {
                        // It is a walkable path (not 'X')
                        if (!visited[newR][newC]) {
                            visited[newR][newC] = true;
                            queue.add(new Coordinate(newR, newC));
                        }
                    }
                }
            }
        }

        return false;
    }

    /**
     * Checks if the given coordinates are within the grid boundaries.
     */
    private static boolean isValidPosition(int r, int c, int rows, int cols) {
        return r >= 0 && c >= 0 && r < rows && c < cols;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.ArrayDeque;
import java.util.Objects;
import java.util.Queue;
import java.util.StringTokenizer;

/**
 * A solution for finding a path in a grid with obstacles using Breadth-First Search (BFS).
 * Refactored for maintainability, readability, and robust resource management.
 */
public class PathFinder {

    /**
     * Represents a coordinate in the 2D grid.
     */
    static class Coordinate {
        final int x;
        final int y;

        Coordinate(int x, int y) {
            this.x = x;
            this.y = y;
        }

        @Override
        public boolean equals(Object o) {
            if (this == o) return true;
            if (o == null || getClass() != o.getClass()) return false;
            Coordinate that = (Coordinate) o;
            return x == that.x && y == that.y;
        }

        @Override
        public int hashCode() {
            return Objects.hash(x, y);
        }
    }

    /**
     * Helper class for fast input reading.
     */
    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    e.printStackTrace();
                    return null;
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            String s = next();
            return (s == null) ? 0 : Integer.parseInt(s);
        }
    }

    private final FastScanner scanner;
    private final PrintWriter out;
    private int rows;
    private int cols;
    private char[][] grid;

    public PathFinder(FastScanner scanner, PrintWriter out) {
        this.scanner = scanner;
        this.out = out;
    }

    public void solve() {
        // Read dimensions
        String rowStr = scanner.next();
        if (rowStr == null) return; // Handle empty input gracefully
        rows = Integer.parseInt(rowStr);
        cols = scanner.nextInt();

        grid = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            String row = scanner.next();
            if (row != null) {
                for (int j = 0; j < cols; j++) {
                    grid[i][j] = row.charAt(j);
                }
            }
        }

        // Read start and target coordinates (1-based in input, convert to 0-based)
        int startX = scanner.nextInt() - 1;
        int startY = scanner.nextInt() - 1;
        int targetX = scanner.nextInt() - 1;
        int targetY = scanner.nextInt() - 1;

        Coordinate start = new Coordinate(startX, startY);
        Coordinate target = new Coordinate(targetX, targetY);

        // Perform BFS
        if (bfs(start, target)) {
            out.println("YES");
        } else {
            out.println("NO");
        }
    }

    private boolean bfs(Coordinate start, Coordinate target) {
        // Validation check for start position
        if (!isValid(start.x, start.y)) return false;

        // If start is the target, we are already there
        if (start.x == target.x && start.y == target.y) {
            return true;
        }

        Queue<Coordinate> queue = new ArrayDeque<>();
        boolean[][] visited = new boolean[rows][cols];

        queue.offer(start);
        visited[start.x][start.y] = true;

        // Direction vectors: Right, Left, Down, Up
        int[] dx = {0, 0, 1, -1};
        int[] dy = {1, -1, 0, 0};

        while (!queue.isEmpty()) {
            Coordinate current = queue.poll();

            for (int i = 0; i < dx.length; i++) {
                int nx = current.x + dx[i];
                int ny = current.y + dy[i];

                if (isValid(nx, ny) && !visited[nx][ny]) {
                    boolean isTarget = (nx == target.x && ny == target.y);
                    boolean isObstacle = (grid[nx][ny] == 'X');

                    // Logic: Can move to cell if it's not an obstacle,
                    // OR if it is the target (even if it's an obstacle 'X')
                    if (!isObstacle || isTarget) {
                        if (isTarget) {
                            return true;
                        }
                        visited[nx][ny] = true;
                        queue.offer(new Coordinate(nx, ny));
                    }
                }
            }
        }
        return false;
    }

    private boolean isValid(int x, int y) {
        return x >= 0 && x < rows && y >= 0 && y < cols;
    }

    public static void main(String[] args) {
        // Using try-with-resources ensures streams are closed properly
        try (FastScanner scanner = new FastScanner();
             PrintWriter out = new PrintWriter(System.out)) {

            PathFinder solver = new PathFinder(scanner, out);
            solver.solve();

        } catch (Exception e) {
            e.printStackTrace();
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayDeque;
import java.util.Queue;
import java.util.StringTokenizer;

public class Main {
    // Direction vectors for moving down, up, right, left
    private static final int[] ROW_DIRS = {1, -1, 0, 0};
    private static final int[] COL_DIRS = {0, 0, 1, -1};

    private int rows;
    private int cols;
    private boolean[][] grid;
    private Cell start;
    private Cell end;

    public static void main(String[] args) throws IOException {
        new Main().run();
    }

    private void run() throws IOException {
        // try-with-resources ensures the reader is closed automatically
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(System.in))) {
            FastScanner scanner = new FastScanner(reader);

            rows = scanner.nextInt();
            cols = scanner.nextInt();

            grid = new boolean[rows][cols];
            for (int r = 0; r < rows; r++) {
                String rowStr = scanner.next();
                for (int c = 0; c < cols; c++) {
                    grid[r][c] = rowStr.charAt(c) == '.';
                }
            }

            // Convert 1-based input coordinates to 0-based
            start = new Cell(scanner.nextInt() - 1, scanner.nextInt() - 1);
            end = new Cell(scanner.nextInt() - 1, scanner.nextInt() - 1);

            System.out.println(solve() ? "YES" : "NO");
        }
    }

    private boolean solve() {
        if (start.equals(end)) {
            return hasAdjacentWalkableCell(start);
        }

        if (grid[end.r][end.c]) {
            for (int i = 0; i < 4; i++) {
                int r = end.r + ROW_DIRS[i];
                int c = end.c + COL_DIRS[i];
                if (isInBounds(r, c) && grid[r][c]) {
                    if (canReachFrom(r, c)) {
                        return true;
                    }
                }
            }
            return false;
        } else {
            return canReachFrom(start.r, start.c);
        }
    }

    private boolean hasAdjacentWalkableCell(Cell cell) {
        for (int i = 0; i < 4; i++) {
            int r = cell.r + ROW_DIRS[i];
            int c = cell.c + COL_DIRS[i];
            if (isInBounds(r, c) && grid[r][c]) {
                return true;
            }
        }
        return false;
    }

    private boolean canReachFrom(int startR, int startC) {
        return bfs(new Cell(startR, startC));
    }

    private boolean bfs(Cell startNode) {
        Queue<Cell> queue = new ArrayDeque<>(rows * cols);
        boolean[][] visited = new boolean[rows][cols];

        visited[startNode.r][startNode.c] = true;
        queue.add(startNode);

        while (!queue.isEmpty()) {
            Cell current = queue.poll();

            if (current.r == end.r && current.c == end.c) {
                return true;
            }

            // Expand neighbors if the current cell is walkable or matches the original start position.
            // This preserves the original algorithm's behavior where traversal can begin from a blocked start cell.
            if (grid[current.r][current.c] || current.equals(start)) {
                for (int i = 0; i < 4; i++) {
                    int r = current.r + ROW_DIRS[i];
                    int c = current.c + COL_DIRS[i];
                    if (isInBounds(r, c) && !visited[r][c]) {
                        visited[r][c] = true;
                        queue.add(new Cell(r, c));
                    }
                }
            }
        }
        return false;
    }

    private boolean isInBounds(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /**
     * Lightweight scanner for fast whitespace-delimited input reading.
     */
    private static class FastScanner {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastScanner(BufferedReader reader) {
            this.reader = reader;
            this.tokenizer = new StringTokenizer("");
        }

        public String next() throws IOException {
            while (!tokenizer.hasMoreTokens()) {
                String line = reader.readLine();
                if (line == null) {
                    throw new IOException("Unexpected end of input");
                }
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }

    /**
     * Represents a coordinate in the grid.
     */
    private static class Cell {
        final int r;
        final int c;

        public Cell(int r, int c) {
            this.r = r;
            this.c = c;
        }

        @Override
        public boolean equals(Object o) {
            if (this == o) return true;
            if (!(o instanceof Cell)) return false;
            Cell cell = (Cell) o;
            return r == cell.r && c == cell.c;
        }

        @Override
        public int hashCode() {
            return 31 * r + c;
        }
    }
}

