import java.util.Scanner;

/**
 * Solves a grid pathfinding problem.
 * Determines if a path exists from a start point to a target point.
 * The grid contains walkable cells ('.') and obstacles.
 * Special rules apply for the target cell depending on its content.
 */
public class GridPathSolver {
    private char[][] grid;
    private boolean[][] visited;
    private int rows;
    private int cols;
    private int targetRow;
    private int targetCol;

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        // Basic validation to prevent exceptions on empty input
        if (!scanner.hasNextInt()) {
            scanner.close();
            return;
        }

        int n = scanner.nextInt();
        int m = scanner.nextInt();

        // Initialize solver with grid dimensions
        GridPathSolver solver = new GridPathSolver(n, m);

        // Read grid and coordinates
        solver.readInput(scanner);

        // Execute the logic
        solver.solve();

        scanner.close();
    }

    public GridPathSolver(int rows, int cols) {
        this.rows = rows;
        this.cols = cols;
        this.grid = new char[rows][cols];
        // Visited array size matches grid dimensions (optimized from n+1, m+1)
        this.visited = new boolean[rows][cols];
    }

    private void readInput(Scanner scanner) {
        // Read grid rows
        for (int i = 0; i < rows; i++) {
            String line = scanner.next();
            this.grid[i] = line.toCharArray();
        }

        // Read coordinates (1-based in input, convert to 0-based)
        int startRow = scanner.nextInt() - 1;
        int startCol = scanner.nextInt() - 1;
        this.targetRow = scanner.nextInt() - 1;
        this.targetCol = scanner.nextInt() - 1;

        // Handle the specific case where start position is the same as target
        if (startRow == targetRow && startCol == targetCol) {
            // Check if there is at least one adjacent walkable cell ('.')
            // Original logic: v=true if ANY neighbor is '.'
            int adjacentWalkable = countAdjacentWalkable(startRow, startCol);
            System.out.println(adjacentWalkable > 0 ? "YES" : "NO");
            return;
        }

        // Prepare for DFS: Mark start cell as walkable
        // Original code logic: a[r1][c1] = '.';
        this.grid[startRow][startCol] = '.';

        // Run DFS to find path
        boolean pathFound = dfs(startRow, startCol);
        System.out.println(pathFound ? "YES" : "NO");
    }

    /**
     * Counts the number of adjacent walkable cells ('.').
     */
    private int countAdjacentWalkable(int r, int c) {
        int count = 0;
        int[] dRow = {-1, 1, 0, 0};
        int[] dCol = {0, 0, -1, 1};

        for (int i = 0; i < 4; i++) {
            int nr = r + dRow[i];
            int nc = c + dCol[i];

            if (isValid(nr, nc) && grid[nr][nc] == '.') {
                count++;
            }
        }
        return count;
    }

    /**
     * Checks if coordinates are within grid bounds.
     */
    private boolean isValid(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /**
     * Depth First Search to find a path to the target.
     * 
     * Rules:
     * 1. Can traverse through '.' cells.
     * 2. If target cell is reached:
     *    - If target cell is NOT '.', path is found.
     *    - If target cell IS '.', path is found only if it has >= 2 adjacent '.' cells.
     */
    private boolean dfs(int r, int c) {
        // Check bounds
        if (!isValid(r, c)) {
            return false;
        }

        // Check if already visited to prevent cycles
        if (visited[r][c]) {
            return false;
        }

        // Mark current cell as visited
        visited[r][c] = true;

        // Check if current cell is the target
        if (r == targetRow && c == targetCol) {
            if (grid[r][c] != '.') {
                // Target is an obstacle/special char, but we reached it
                return true;
            } else {
                // Target is a walkable cell, check connectivity requirement
                // Original logic: x=k>=2
                return countAdjacentWalkable(r, c) >= 2;
            }
        }

        // If current cell is not '.', we cannot traverse through it
        // (Unless it was the target, handled above)
        if (grid[r][c] != '.') {
            return false;
        }

        // Explore neighbors
        int[] dRow = {-1, 1, 0, 0};
        int[] dCol = {0, 0, -1, 1};

        for (int i = 0; i < 4; i++) {
            if (dfs(r + dRow[i], c + dCol[i])) {
                return true;
            }
        }

        return false;
    }
}

