            dfs(startX, startY);

            // Preserve original final condition logic
            boolean result = pathFound || (visited[endX][endY] && grid[endX][endY] == 'X');
            System.out.println(result ? "YES" : "NO");
        }

        /**
         * Checks if a cell is within bounds, unvisited, and not an obstacle ('X').
         */
        private boolean isValid(int r, int c) {
            return r >= 0 && r < n && c >= 0 && c < m
                && !visited[r][c]
                && grid[r][c] != 'X';
        }

        /**
         * Checks if any adjacent cell is valid.
         */
        private boolean hasValidAdjacent(int r, int c) {
            return isValid(r + 1, c) || isValid(r - 1, c)
                || isValid(r, c + 1) || isValid(r, c - 1);
        }

        /**
         * Depth-First Search to explore the grid.
         * Uses return-by-reference via instance field to avoid excessive object creation.
         */
        private void dfs(int r, int c) {
            if (pathFound) return;

            visited[r][c] = true;

            if (r == endX && c == endY) {
                // If any adjacent cell is valid, path condition is satisfied
                if (hasValidAdjacent(r, c)) {
                    pathFound = true;
                } else {
                    // Count adjacent empty cells ('.')
                    int adjacentDots = 0;
                    if (r + 1 < n && grid[r + 1][c] == '.') adjacentDots++;
                    if (r - 1 >= 0 && grid[r - 1][c] == '.') adjacentDots++;
                    if (c + 1 < m && grid[r][c + 1] == '.') adjacentDots++;
                    if (c - 1 >= 0 && grid[r][c - 1] == '.') adjacentDots++;

                    pathFound = adjacentDots > 1;
                }
                return;
            }

            // Explore valid neighbors
            if (isValid(r + 1, c)) dfs(r + 1, c);
            if (isValid(r - 1, c)) dfs(r - 1, c);
            if (isValid(r, c + 1)) dfs(r, c + 1);
            if (isValid(r, c - 1)) dfs(r, c - 1);
        }
    }

    /**
     * Fast I/O helper for competitive programming contexts.
     */
    static class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            String s = next();
            return s == null ? 0 : Integer.parseInt(s);
        }
    }
}

import java.util.Arrays;
import java.util.Scanner;

/**
 * Solves a grid pathfinding problem using DFS with memoization.
 * Determines if a valid path exists from a start coordinate to an end coordinate
 * based on specific traversal rules.
 */
public class PathFinder {

    // Constants for movement directions and memoization states
    private static final int[][] DIRECTIONS = {{0, -1}, {-1, 0}, {0, 1}, {1, 0}};
    private static final int UNVISITED = -1;
    private static final int POSSIBLE = 1;
    private static final int IMPOSSIBLE = 0;

    // Instance variables to encapsulate state instead of using static globals
    private final int rows;
    private final int cols;
    private final char[][] grid;
    private final int startRow;
    private final int startCol;
    private final int endRow;
    private final int endCol;
    private final int[][] memo;
    private final boolean[][] visited;

    /**
     * Constructs the PathFinder with grid dimensions, layout, and start/end coordinates.
     */
    public PathFinder(int rows, int cols, char[][] grid, int startRow, int startCol, int endRow, int endCol) {
        this.rows = rows;
        this.cols = cols;
        this.grid = grid;
        this.startRow = startRow;
        this.startCol = startCol;
        this.endRow = endRow;
        this.endCol = endCol;

        // Initialize memoization table
        this.memo = new int[rows][cols];
        for (int[] row : memo) {
            Arrays.fill(row, UNVISITED);
        }
        // Initialize visited tracking
        this.visited = new boolean[rows][cols];
    }

    /**
     * Executes the pathfinding algorithm and returns the result.
     */
    public String solve() {
        // Pre-calculate adjacent empty cells to the destination
        int adjacentEmptyCount = countAdjacentEmptyCells(endRow, endCol);
        boolean possible = dfs(startRow, startCol, 0, adjacentEmptyCount);
        return possible ? "YES" : "NO";
    }

    /**
     * Counts how many adjacent cells to the given coordinate are empty ('.').
     */
    private int countAdjacentEmptyCells(int r, int c) {
        int count = 0;
        for (int[] dir : DIRECTIONS) {
            int nr = r + dir[0];
            int nc = c + dir[1];
            if (isWithinBounds(nr, nc) && grid[nr][nc] == '.') {
                count++;
            }
        }
        return count;
    }

    /**
     * Depth-First Search with memoization to find a valid path.
     */
    private boolean dfs(int r, int c, int depth, int adjacentEmptyCount) {
        // Base case: reached the destination
        if (r == endRow && c == endCol) {
            if (grid[r][c] == 'X' && adjacentEmptyCount > 0) return true;
            if (grid[r][c] == '.' && adjacentEmptyCount > 1) return true;
        }

        // If current cell is 'X' and we've moved at least once, we can only succeed if at destination
        if (grid[r][c] == 'X' && depth > 0) {
            return r == endRow && c == endCol;
        }

        // Check memoization table
        if (memo[r][c] != UNVISITED) {
            return memo[r][c] == POSSIBLE;
        }

        // Mark current cell as visited
        visited[r][c] = true;

        boolean possible = false;
        for (int[] dir : DIRECTIONS) {
            int nr = r + dir[0];
            int nc = c + dir[1];
            if (isWithinBounds(nr, nc) && !visited[nr][nc]) {
                if (dfs(nr, nc, depth + 1, adjacentEmptyCount)) {
                    possible = true;
                    break; // Optimization: exit early once a valid path is found
                }
            }
        }

        // Backtrack: unmark current cell
        visited[r][c] = false;

        // Store result in memoization table
        memo[r][c] = possible ? POSSIBLE : IMPOSSIBLE;
        return possible;
    }

    /**
     * Checks if coordinates are within the grid boundaries.
     */
    private boolean isWithinBounds(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    public static void main(String[] args) {
        // Use try-with-resources to ensure Scanner is properly closed
        try (Scanner sc = new Scanner(System.in)) {
            if (!sc.hasNextInt()) return;

            int r = sc.nextInt();
            int c = sc.nextInt();

            char[][] grid = new char[r][c];
            for (int i = 0; i < r; i++) {
                String line = sc.next();
                for (int j = 0; j < c; j++) {
                    grid[i][j] = line.charAt(j);
                }
            }

            // Convert 1-based input coordinates to 0-based
            int r1 = sc.nextInt() - 1;
            int c1 = sc.nextInt() - 1;
            int r2 = sc.nextInt() - 1;
            int c2 = sc.nextInt() - 1;

            PathFinder finder = new PathFinder(r, c, grid, r1, c1, r2, c2);
            System.out.print(finder.solve());
        }
    }
}

import java.util.Scanner;

/**
 * Refactored solution for the Ice Cave problem.
 * 
 * Improvements made:
 * 1. Encapsulation: Moved global static variables into instance fields.
 * 2. Naming: Renamed variables for semantic clarity (e.g., iceCave -> isBroken, myX -> startRow).
 * 3. Structure: Separated input reading and logic into distinct methods.
 * 4. Resource Management: Used try-with-resources for the Scanner.
 * 5. Readability: Used direction arrays to simplify neighbor traversal logic.
 */
public class IceCave {

    // Instance fields to replace static global state
    private boolean[][] isBroken; // Represents the grid (true = 'X', false = '.')
    private boolean[][] visited;  // Tracks visited cells to prevent cycles and redundant work
    private int rows;             // n (number of rows)
    private int cols;             // m (number of columns)
    private int destRow;          // Destination row index (originally destX)
    private int destCol;          // Destination column index (originally destY)
    private int startRow;         // Start row index (originally myX)
    private int startCol;         // Start column index (originally myY)

    public static void main(String[] args) {
        // Use try-with-resources for automatic resource management
        try (Scanner scanner = new Scanner(System.in)) {
            IceCave solver = new IceCave();
            solver.readInput(scanner);

            boolean canReach = solver.dfs(solver.startRow, solver.startCol);
            System.out.println(canReach ? "YES" : "NO");
        }
    }

    /**
     * Reads input from the Scanner and initializes the grid state.
     */
    private void readInput(Scanner scanner) {
        if (!scanner.hasNextInt()) return;

        this.rows = scanner.nextInt();
        this.cols = scanner.nextInt();

        this.isBroken = new boolean[rows][cols];
        this.visited = new boolean[rows][cols];

        // Read the grid
        for (int i = 0; i < rows; i++) {
            String rowStr = scanner.next();
            for (int j = 0; j < cols; j++) {
                // 'X' indicates broken ice (true), '.' indicates safe ice (false)
                this.isBroken[i][j] = (rowStr.charAt(j) == 'X');
            }
        }

        // Read start and destination coordinates (convert 1-based to 0-based)
        this.startRow = scanner.nextInt() - 1;
        this.startCol = scanner.nextInt() - 1;
        this.destRow = scanner.nextInt() - 1;
        this.destCol = scanner.nextInt() - 1;

        // The starting position is safe (not broken) initially
        this.isBroken[startRow][startCol] = false;
    }

    /**
     * Depth First Search to determine if the destination is reachable.
     * 
     * @param r Current row index
     * @param c Current column index
     * @return true if destination is reachable, false otherwise
     */
    private boolean dfs(int r, int c) {
        // 1. Boundary Check
        if (r < 0 || r >= rows || c < 0 || c >= cols) {
            return false;
        }

        // 2. Destination Check
        if (r == destRow && c == destCol) {
            // If destination is broken ice ('X'), we can step on it.
            if (isBroken[r][c]) {
                return true;
            }
            // If destination is safe ice, check if it has a "good neighbor"
            // (Logic preserved from original code: returns true if at least one neighbor is safe)
            return hasGoodNeighbor(r, c);
        }

        // 3. Visited / Blocked Check
        // Cannot step on broken ice ('X') unless it's the destination (handled above).
        // Cannot step on a cell we've already determined leads to a dead end.
        if (isBroken[r][c] || visited[r][c]) {
            return false;
        }

        // 4. Mark current cell as broken (visited)
        // This simulates cracking the ice under our feet.
        isBroken[r][c] = true;

        // 5. Recursive Step: Try all 4 directions
        // Directions: Down, Up, Right, Left
        int[] dr = {1, -1, 0, 0};
        int[] dc = {0, 0, 1, -1};

        for (int i = 0; i < 4; i++) {
            if (dfs(r + dr[i], c + dc[i])) {
                return true; // Path found
            }
        }

        // 6. Backtracking
        // If no path was found from this cell, restore the ice (it wasn't permanently broken)
        // but mark as visited so we don't check this path again.
        isBroken[r][c] = false;
        visited[r][c] = true;

        return false;
    }

    /**
     * Checks if the destination has at least one safe neighbor.
     * Logic preserved from original: returns true if NOT all valid neighbors are broken.
     * 
     * @param r Row index of the destination
     * @param c Column index of the destination
     * @return true if there is at least one safe neighbor
     */
    private boolean hasGoodNeighbor(int r, int c) {
        boolean allNeighborsBroken = true;

        // Directions: Up, Down, Left, Right
        int[] dr = {-1, 1, 0, 0};
        int[] dc = {0, 0, -1, 1};

        for (int i = 0; i < 4; i++) {
            int nr = r + dr[i];
            int nc = c + dc[i];

            // Check bounds
            if (nr >= 0 && nr < rows && nc >= 0 && nc < cols) {
                // If neighbor is safe (not broken), then not all neighbors are broken
                if (!isBroken[nr][nc]) {
                    allNeighborsBroken = false;
                    break; // Optimization: found a safe neighbor, no need to check others
                }
            }
        }

        // Returns true if there is at least one safe neighbor
        return !allNeighborsBroken;
    }
}

