/**
 * Solver class responsible for determining path existence in a grid.
 */
class GridSolver {

    // Direction vectors for moving Right, Left, Down, Up
    private static final int[] DELTA_ROW = {0, 0, 1, -1};
    private static final int[] DELTA_COL = {1, -1, 0, 0};

    /**
     * Represents a coordinate in the grid.
     */
    static class Point {
        final int r;
        final int c;

        Point(int r, int c) {
            this.r = r;
            this.c = c;
        }
    }

    /**
     * Solves the pathfinding problem.
     *
     * @param scanner Input source
     * @param out     Output destination
     */
    public void solve(Scanner scanner, PrintWriter out) {
        if (!scanner.hasNextInt()) return;

        // Read grid dimensions
        int rows = scanner.nextInt();
        int cols = scanner.nextInt();
        scanner.nextLine(); // Consume the newline character after dimensions

        // Read the grid
        char[][] grid = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            String line = scanner.nextLine();
            // In case the input line is shorter than cols (defensive coding)
            int len = Math.min(line.length(), cols);
            for (int j = 0; j < len; j++) {
                grid[i][j] = line.charAt(j);
            }
        }

        // Read start and end coordinates (1-based in input, convert to 0-based)
        int startR = scanner.nextInt() - 1;
        int startC = scanner.nextInt() - 1;
        int endR = scanner.nextInt() - 1;
        int endC = scanner.nextInt() - 1;

        // Perform BFS
        boolean pathExists = bfs(grid, rows, cols, startR, startC, endR, endC);

        if (pathExists) {
            out.println("YES");
        } else {
            out.println("NO");
        }
    }

    /**
     * Performs Breadth-First Search to find if a path exists.
     *
     * @param grid   The grid map
     * @param rows   Number of rows
     * @param cols   Number of columns
     * @param startR Start row index
     * @param startC Start column index
     * @param endR   End row index
     * @param endC   End column index
     * @return true if a path exists, false otherwise
     */
    private boolean bfs(char[][] grid, int rows, int cols,
                        int startR, int startC, int endR, int endC) {

        // Boundary checks
        if (startR < 0 || startC < 0 || endR < 0 || endC < 0 ||
            startR >= rows || startC >= cols || endR >= rows || endC >= cols) {
            return false;
        }

        // If start is the same as end
        if (startR == endR && startC == endC) {
            return true;
        }

        // Visited array to keep track of explored cells
        // Using a separate array is safer than mutating the input grid
        boolean[][] visited = new boolean[rows][cols];
        Queue<Point> queue = new LinkedList<>();

        // Initialize BFS
        queue.add(new Point(startR, startC));
        visited[startR][startC] = true;

        while (!queue.isEmpty()) {
            Point current = queue.poll();

            // Explore all 4 possible directions
            for (int i = 0; i < 4; i++) {
                int nextR = current.r + DELTA_ROW[i];
                int nextC = current.c + DELTA_COL[i];

                // Check bounds and if already visited
                if (isValid(nextR, nextC, rows, cols) && !visited[nextR][nextC]) {

                    // Check if we reached the target
                    if (nextR == endR && nextC == endC) {
                        return true;
                    }

                    // Mark as visited and add to queue
                    visited[nextR][nextC] = true;
                    queue.add(new Point(nextR, nextC));
                }
            }
        }

        return false;
    }

    /**
     * Checks if coordinates are within grid boundaries.
     */
    private boolean isValid(int r, int c, int rows, int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }
}

