/**
 * Solves the grid pathfinding problem using Breadth-First Search (BFS).
 * Checks if a valid path exists from (startR, startC) to (endR, endC)
 * avoiding cells marked with 'X'.
 */
class PathFinder {
    private static final int[][] DIRECTIONS = {
        {0, 1}, {0, -1}, {1, 0}, {-1, 0}
    };

    public void solve(InputReader in, PrintWriter out) {
        int n = in.nextInt();
        int m = in.nextInt();
        char[][] grid = new char[n][m];
        for (int i = 0; i < n; i++) {
            grid[i] = in.next().toCharArray();
        }

        int startR = in.nextInt() - 1;
        int startC = in.nextInt() - 1;
        int endR = in.nextInt() - 1;
        int endC = in.nextInt() - 1;

        // Edge case: start and end positions are identical
        if (startR == endR && startC == endC) {
            out.println("YES");
            return;
        }

        if (bfs(n, m, grid, startR, startC, endR, endC)) {
            out.println("YES");
        } else {
            out.println("NO");
        }
    }

    private boolean bfs(int n, int m, char[][] grid,
                        int startR, int startC,
                        int endR, int endC) {
        boolean[][] visited = new boolean[n][m];
        Queue<Integer> queue = new ArrayDeque<>();

        // Encode coordinates as a single integer: r * m + c
        queue.offer(startR * m + startC);
        visited[startR][startC] = true;

        while (!queue.isEmpty()) {
            int current = queue.poll();
            int r = current / m;
            int c = current % m;

            for (int[] dir : DIRECTIONS) {
                int nr = r + dir[0];
                int nc = c + dir[1];

                if (isValid(nr, nc, n, m) && !visited[nr][nc] && grid[nr][nc] != 'X') {
                    if (nr == endR && nc == endC) {
                        return true;
                    }
                    visited[nr][nc] = true;
                    queue.offer(nr * m + nc);
                }
            }
        }
        return false;
    }

    private boolean isValid(int r, int c, int n, int m) {
        return r >= 0 && r < n && c >= 0 && c < m;
    }
}

/**
 * Fast input reader for competitive programming and performance-critical applications.
 */
class InputReader {
    private final BufferedReader reader;
    private StringTokenizer tokenizer;

    public InputReader(InputStream stream) {
        this.reader = new BufferedReader(new InputStreamReader(stream));
    }

    public String next() {
        while (tokenizer == null || !tokenizer.hasMoreTokens()) {
            try {
                String line = reader.readLine();
                if (line == null) {
                    throw new IOException("Unexpected end of input");
                }
                tokenizer = new StringTokenizer(line);
            } catch (IOException e) {
                throw new RuntimeException(e);
            }
        }
        return tokenizer.nextToken();
    }

    public int nextInt() {
        return Integer.parseInt(next());
    }
}

import java.util.Scanner;
import java.util.Queue;
import java.util.ArrayDeque;

public class IceCave {

    /**
     * Represents a coordinate point (x, y).
     * x corresponds to the row index, y to the column index.
     */
    static class Point {
        final int x;
        final int y;

        Point(int x, int y) {
            this.x = x;
            this.y = y;
        }

        @Override
        public boolean equals(Object o) {
            if (this == o) return true;
            if (o == null || getClass() != o.getClass()) return false;
            Point point = (Point) o;
            return x == point.x && y == point.y;
        }

        @Override
        public int hashCode() {
            return 31 * x + y;
        }
    }

    public static void main(String[] args) {
        // Use try-with-resources to ensure Scanner is closed properly
        try (Scanner sc = new Scanner(System.in)) {
            if (!sc.hasNext()) return;

            // Read grid dimensions
            int n = sc.nextInt();
            int m = sc.nextInt();

            char[][] grid = new char[n][m];
            for (int i = 0; i < n; i++) {
                // Read row as a string token
                String row = sc.next();
                grid[i] = row.toCharArray();
            }

            // Read start point (1-based index in input, convert to 0-based)
            int r1 = sc.nextInt();
            int c1 = sc.nextInt();
            Point startPoint = new Point(r1 - 1, c1 - 1);

            // Read target point
            int r2 = sc.nextInt();
            int c2 = sc.nextInt();
            Point targetPoint = new Point(r2 - 1, c2 - 1);

            // Validate inputs and solve
            if (isValidCoordinate(startPoint, grid) && isValidCoordinate(targetPoint, grid)) {
                if (canReachDestination(startPoint, targetPoint, grid)) {
                    System.out.println("YES");
                } else {
                    System.out.println("NO");
                }
            } else {
                // If start or target is out of bounds
                System.out.println("NO");
            }
        }
    }

    /**
     * Checks if a point is within the grid boundaries.
     */
    private static boolean isValidCoordinate(Point p, char[][] grid) {
        return p.x >= 0 && p.x < grid.length &&
               p.y >= 0 && p.y < grid[0].length;
    }

    /**
     * Determines if a cell is walkable.
     * Walkable cells are '.' (empty) or 'X' (target/exit).
     */
    private static boolean isWalkable(char[][] grid, Point p) {
        char cell = grid[p.x][p.y];
        return cell == '.' || cell == 'X';
    }

    /**
     * Uses Breadth-First Search (BFS) to determine if the target is reachable from the start.
     */
    private static boolean canReachDestination(Point start, Point target, char[][] grid) {
        // Queue for BFS
        Queue<Point> queue = new ArrayDeque<>();

        // Visited array to keep track of visited cells
        boolean[][] visited = new boolean[grid.length][grid[0].length];

        // Check if start is valid and walkable
        if (!isValidCoordinate(start, grid) || !isWalkable(grid, start)) {
            return false;
        }

        // Initialize BFS
        queue.add(start);
        visited[start.x][start.y] = true;

        // Direction arrays for moving Up, Down, Left, Right
        int[] dx = {-1, 1, 0, 0};
        int[] dy = {0, 0, -1, 1};

        while (!queue.isEmpty()) {
            Point current = queue.poll();

            // Check if we have reached the target
            if (current.equals(target)) {
                // Additional check: ensure the target cell is actually 'X'
                // (Consistent with original logic intent)
                if (grid[target.x][target.y] == 'X') {
                    return true;
                }
            }

            // Explore neighbors
            for (int i = 0; i < dx.length; i++) {
                int nx = current.x + dx[i];
                int ny = current.y + dy[i];
                Point next = new Point(nx, ny);

                // Check bounds, visited status, and walkability
                if (isValidCoordinate(next, grid) && 
                    !visited[nx][ny] && 
                    isWalkable(grid, next)) {

                    // Mark as visited immediately upon adding to queue to prevent duplicates
                    visited[nx][ny] = true;
                    queue.add(next);
                }
            }
        }

        return false;
    }
}

