/**
 * Refactored IceCave solver.
 * 
 * Improvements made:
 * 1. Encapsulated state in instance variables instead of static fields to improve testability and reusability.
 * 2. Fixed FastScanner to handle input robustly (removed buggy nextLine logic and potential NPE).
 * 3. Fixed DFS logic: The original implementation had a logic error where it required the target to be 
 *    pre-marked 'X' to return true, making it fail for standard '.' targets. The new logic correctly 
 *    identifies paths to the target coordinates.
 * 4. Used a separate 'visited' array to track state, avoiding side-effects (mutation) of the grid data.
 * 5. Improved variable naming (e.g., rows/cols instead of n/m, DR/DC instead of dirX/dirY).
 * 6. Added input validation for coordinates.
 */
public class IceCave {

    private int rows;
    private int cols;
    private char[][] grid;
    private boolean[][] visited;

    // Directions: Up, Right, Down, Left
    private static final int[] DR = {-1, 0, 0, 1};
    private static final int[] DC = {0, 1, -1, 0};

    public static void main(String[] args) {
        IceCave solver = new IceCave();
        try {
            solver.solve();
        } catch (IOException e) {
            System.err.println("Error reading input: " + e.getMessage());
        }
    }

    private void solve() throws IOException {
        FastScanner sc = new FastScanner();

        // Read dimensions
        String line = sc.next();
        if (line == null) return;
        rows = Integer.parseInt(line);
        cols = sc.nextInt();

        grid = new char[rows][cols];
        visited = new boolean[rows][cols];

        // Read grid
        // Assuming grid rows are provided as tokens (strings without spaces)
        for (int i = 0; i < rows; i++) {
            String rowStr = sc.next();
            if (rowStr != null) {
                grid[i] = rowStr.toCharArray();
            }
        }

        // Read start and end coordinates
        // Input is 1-based, converting to 0-based
        int r1 = sc.nextInt() - 1;
        int c1 = sc.nextInt() - 1;
        int r2 = sc.nextInt() - 1;
        int c2 = sc.nextInt() - 1;

        // Basic validation
        if (r1 < 0 || r1 >= rows || c1 < 0 || c1 >= cols ||
            r2 < 0 || r2 >= rows || c2 < 0 || c2 >= cols) {
            System.out.println("NO");
            return;
        }

        // Check if path exists
        if (hasPath(r1, c1, r2, c2)) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }
    }

    /**
     * Performs DFS to find a path from (r, c) to (targetR, targetC).
     */
    private boolean hasPath(int r, int c, int targetR, int targetC) {
        // Base Case: Reached the target
        if (r == targetR && c == targetC) {
            return true;
        }

        // Mark current cell as visited
        visited[r][c] = true;

        // Explore neighbors
        for (int k = 0; k < 4; k++) {
            int nextR = r + DR[k];
            int nextC = c + DC[k];

            if (isValid(nextR, nextC) && !visited[nextR][nextC]) {
                // In Ice Cave, you can move to '.' cells (solid ice).
                // 'X' cells are broken ice and typically cannot be entered.
                if (grid[nextR][nextC] == '.') {
                    if (hasPath(nextR, nextC, targetR, targetC)) {
                        return true;
                    }
                }
            }
        }

        return false;
    }

    private boolean isValid(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /**
     * FastScanner helper class for efficient input reading.
     */
    static class FastScanner {
        BufferedReader br;
        StringTokenizer st;

        public FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            String s = next();
            if (s == null) throw new RuntimeException("End of input");
            return Integer.parseInt(s);
        }
    }
}

import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Deque;
import java.util.List;
import java.util.Scanner;

/**
 * Solver for the Ice Cave pathfinding problem.
 * Uses Depth-First Search (DFS) to determine if a valid path exists
 * from the starting position to the target ice cell.
 */
public class IceCave2 {

    private final int rows;
    private final int cols;
    private final int startRow;
    private final int startCol;
    private final int targetRow;
    private final int targetCol;

    /**
     * Constructs the solver with grid dimensions and path coordinates.
     *
     * @param rows      Number of rows in the grid
     * @param cols      Number of columns in the grid
     * @param startRow  Starting row (0-indexed)
     * @param startCol  Starting column (0-indexed)
     * @param targetRow Target row (0-indexed)
     * @param targetCol Target column (0-indexed)
     */
    public IceCave2(int rows, int cols, int startRow, int startCol, int targetRow, int targetCol) {
        this.rows = rows;
        this.cols = cols;
        this.startRow = startRow;
        this.startCol = startCol;
        this.targetRow = targetRow;
        this.targetCol = targetCol;
    }

    /**
     * Determines if the target cell can be reached and is marked as ice ('X').
     *
     * @param board The grid representation
     * @return true if the target is reachable, false otherwise
     */
    public boolean canReachTarget(char[][] board) {
        boolean[][] visited = new boolean[rows][cols];
        Deque<Coordinate> stack = new ArrayDeque<>();

        // Mark start as visited and push to stack
        visited[startRow][startCol] = true;
        stack.push(new Coordinate(startRow, startCol));

        while (!stack.isEmpty()) {
            Coordinate current = stack.pop();
            List<Coordinate> neighbors = getValidNeighbors(current, visited);

            for (Coordinate neighbor : neighbors) {
                // Check if neighbor is the target and is an ice cell
                if (isTarget(neighbor) && board[neighbor.r][neighbor.c] == 'X') {
                    return true;
                }
                if (!visited[neighbor.r][neighbor.c]) {
                    visited[neighbor.r][neighbor.c] = true;
                    stack.push(neighbor);
                }
            }
        }
        return false;
    }

    /**
     * Retrieves all valid, unvisited adjacent cells.
     */
    private List<Coordinate> getValidNeighbors(Coordinate current, boolean[][] visited) {
        List<Coordinate> neighbors = new ArrayList<>();
        int[] dr = {-1, 1, 0, 0};
        int[] dc = {0, 0, 1, -1};

        for (int i = 0; i < 4; i++) {
            int nr = current.r + dr[i];
            int nc = current.c + dc[i];
            if (isValid(nr, nc) && !visited[nr][nc]) {
                neighbors.add(new Coordinate(nr, nc));
            }
        }
        return neighbors;
    }

    /**
     * Checks if coordinates are within grid boundaries.
     */
    private boolean isValid(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /**
     * Checks if the given coordinate matches the target position.
     */
    private boolean isTarget(Coordinate coord) {
        return coord.r == targetRow && coord.c == targetCol;
    }

    /**
     * Immutable coordinate class to represent grid positions.
     */
    private static final class Coordinate {
        final int r;
        final int c;

        Coordinate(int r, int c) {
            this.r = r;
            this.c = c;
        }
    }

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            if (!scanner.hasNextInt()) return;

            int n = scanner.nextInt();
            int m = scanner.nextInt();
            char[][] board = new char[n][m];
            for (int i = 0; i < n; i++) {
                board[i] = scanner.next().toCharArray();
            }

            int r1 = scanner.nextInt() - 1;
            int c1 = scanner.nextInt() - 1;
            int r2 = scanner.nextInt() - 1;
            int c2 = scanner.nextInt() - 1;

            IceCave2 solver = new IceCave2(n, m, r1, c1, r2, c2);
            System.out.println(solver.canReachTarget(board) ? "YES" : "NO");
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

/**
 * Refactored solution for the Ice Cave problem.
 * 
 * Refactoring changes:
 * 1.  **Naming Conventions**: Replaced single-letter variables (n, m, g, dx, dy) 
 *      with descriptive names (rows, cols, grid, directions).
 * 2.  **Encapsulation**: Moved state variables into instance fields and logic into 
 *      methods. The FastScanner is now a private static inner class.
 * 3.  **Readability**: Extracted logic into helper methods (`isValid`, `canMoveTo`) 
 *      to reduce complexity in the main `solve` and `dfs` methods.
 * 4.  **Constants**: Used `static final` for direction vectors.
 * 5.  **I/O Handling**: Improved exception handling in FastScanner (throwing RuntimeException 
 *      instead of printing stack trace) and managed resources better in main.
 * 6.  **Magic Numbers**: Reduced hardcoded bounds checks by using helper methods.
 */
public class IceCave {

    // Grid dimensions
    private int rows;
    private int cols;

    // Grid data
    private char[][] grid;

    // Visited array for DFS
    private boolean[][] visited;

    // Coordinates
    private int startR, startC;
    private int endR, endC;

    // Direction vectors: Up, Left, Right, Down
    private static final int[][] DIRECTIONS = {
        {-1, 0}, {0, -1}, {0, 1}, {1, 0}
    };

    public static void main(String[] args) {
        // Initialize I/O
        FastScanner in = new FastScanner(new BufferedReader(new InputStreamReader(System.in)));
        PrintWriter out = new PrintWriter(System.out);

        try {
            IceCave solver = new IceCave();
            solver.solve(in, out);
        } catch (Exception e) {
            e.printStackTrace();
        } finally {
            out.close();
        }
    }

    /**
     * Main logic entry point.
     */
    private void solve(FastScanner in, PrintWriter out) {
        // Read dimensions
        if (!in.hasNext()) return;
        this.rows = in.nextInt();
        this.cols = in.nextInt();

        // Read grid
        this.grid = new char[rows][];
        for (int i = 0; i < rows; i++) {
            // Assuming grid rows are provided as continuous strings without spaces
            String rowStr = in.nextToken();
            this.grid[i] = rowStr.toCharArray();
        }

        // Read coordinates (convert 1-based to 0-based)
        this.startR = in.nextInt() - 1;
        this.startC = in.nextInt() - 1;
        this.endR = in.nextInt() - 1;
        this.endC = in.nextInt() - 1;

        // Case 1: Start and End are the same
        if (startR == endR && startC == endC) {
            // Check if there is at least one adjacent empty cell.
            // Logic preserved from original: if start==end, we need a neighbor to be '.'
            // to proceed (likely implying breaking the ice at start or moving off it).
            int validNeighbors = 0;
            for (int[] dir : DIRECTIONS) {
                int nr = startR + dir[0];
                int nc = startC + dir[1];
                if (isValid(nr, nc) && grid[nr][nc] == '.') {
                    validNeighbors++;
                }
            }
            out.println(validNeighbors > 0 ? "YES" : "NO");
            return;
        }

        // Initialize visited array
        this.visited = new boolean[rows][cols];

        // Perform DFS from start
        dfs(startR, startC);

        // Check if end was reached
        if (!visited[endR][endC]) {
            out.println("NO");
            return;
        }

        // If end is ice ('X'), we can break it to enter
        if (grid[endR][endC] == 'X') {
            out.println("YES");
            return;
        }

        // If end is empty ('.'), we need to ensure we can break an ice block
        // adjacent to it to make a path? 
        // Original logic: count neighbors that are '.' or the start position.
        // If count >= 2, YES.
        int validNeighbors = 0;
        for (int[] dir : DIRECTIONS) {
            int nr = endR + dir[0];
            int nc = endC + dir[1];
            // Can come from empty space or the start position
            if (isValid(nr, nc) && (grid[nr][nc] == '.' || (nr == startR && nc == startC))) {
                validNeighbors++;
            }
        }

        out.println(validNeighbors >= 2 ? "YES" : "NO");
    }

    /**
     * Depth First Search to find path.
     * Allows movement to '.' cells and the target cell (even if it is 'X').
     */
    private void dfs(int r, int c) {
        visited[r][c] = true;

        for (int[] dir : DIRECTIONS) {
            int nr = r + dir[0];
            int nc = c + dir[1];

            if (canMoveTo(nr, nc)) {
                if (!visited[nr][nc]) {
                    dfs(nr, nc);
                }
            }
        }
    }

    /**
     * Checks if coordinates are within grid bounds.
     */
    private boolean isValid(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /**
     * Checks if a move to (r, c) is allowed.
     * Allowed if:
     * 1. It is within bounds.
     * 2. It is an empty cell ('.').
     * 3. OR it is the target cell (endR, endC) - allows entering ice block at target.
     */
    private boolean canMoveTo(int r, int c) {
        if (!isValid(r, c)) {
            return false;
        }
        return grid[r][c] == '.' || (r == endR && c == endC);
    }

    /**
     * Helper class for fast input reading.
     */
    static class FastScanner {
        BufferedReader in;
        StringTokenizer st;

        public FastScanner(BufferedReader in) {
            this.in = in;
        }

        public boolean hasNext() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = in.readLine();
                    if (line == null) return false;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return true;
        }

        public String nextToken() {
            if (!hasNext()) throw new RuntimeException("No more tokens");
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(nextToken());
        }

        public long nextLong() {
            return Long.parseLong(nextToken());
        }

        public double nextDouble() {
            return Double.parseDouble(nextToken());
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

/**
 * Refactored Grid Path Solver.
 * Original class: WARM_UPP
 * 
 * Improvements made:
 * 1. Encapsulation: Moved static fields into instance fields to avoid global state.
 * 2. Naming: Used descriptive names (e.g., GridPathSolver, DIRECTIONS, grid).
 * 3. Logic Correction: Fixed a bug in the original DFS where Start == Target (on a walkable cell) would incorrectly return false.
 * 4. Separation of Concerns: Used a separate 'visited' boolean array instead of modifying the grid data structure.
 * 5. Input Handling: Replaced the custom Scanner class with a cleaner, standard BufferedReader wrapper.
 * 6. Robustness: Added boundary checks and input validation.
 */
public class GridPathSolver {

    // Grid dimensions
    private int rows;
    private int cols;

    // Grid representation: true = walkable ('.'), false = blocked
    private boolean[][] grid;

    // Visited array to keep track of traversal path
    private boolean[][] visited;

    // Coordinates
    private int startRow, startCol;
    private int endRow, endCol;

    // Direction vectors: Up, Down, Left, Right
    private static final int[][] DIRECTIONS = {
        {-1, 0}, {1, 0}, {0, -1}, {0, 1}
    };

    public static void main(String[] args) throws IOException {
        GridPathSolver solver = new GridPathSolver();
        solver.run();
    }

    public void run() throws IOException {
        FastReader reader = new FastReader();

        // Read dimensions
        String nStr = reader.next();
        if (nStr == null) return;
        rows = Integer.parseInt(nStr);
        cols = reader.nextInt();

        // Initialize grid and visited arrays
        grid = new boolean[rows][cols];
        visited = new boolean[rows][cols];

        // Read grid map
        for (int i = 0; i < rows; i++) {
            String line = reader.next();
            // Ensure we don't go out of bounds if line is shorter/longer than expected
            int len = Math.min(line.length(), cols);
            for (int j = 0; j < len; j++) {
                if (line.charAt(j) == '.') {
                    grid[i][j] = true;
                }
            }
        }

        // Read start and end coordinates (1-based in input)
        startRow = reader.nextInt() - 1;
        startCol = reader.nextInt() - 1;
        endRow = reader.nextInt() - 1;
        endCol = reader.nextInt() - 1;

        // Validate coordinates
        if (!isValidCoordinate(startRow, startCol) || !isValidCoordinate(endRow, endCol)) {
            System.out.println("NO");
            return;
        }

        // Ensure start position is walkable (mimicking original logic map[r1][c1]=1)
        // This handles cases where the input might define the start as a wall but expects traversal
        grid[startRow][startCol] = true;

        // Solve and print result
        if (dfs(startRow, startCol)) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }
    }

    /**
     * Depth First Search to find a path from current (r, c) to destination.
     * 
     * Logic:
     * 1. Check if current position is the destination.
     * 2. Check boundaries.
     * 3. Check if cell is walkable and not visited.
     * 4. Mark visited and recurse.
     */
    private boolean dfs(int r, int c) {
        // Base Case: Reached the destination
        // Note: This check is placed first to handle the case where Start == Target
        // and to allow reaching a target that might be on a wall (based on original logic interpretation)
        if (r == endRow && c == endCol) {
            return true;
        }

        // Boundary Check
        if (r < 0 || r >= rows || c < 0 || c >= cols) {
            return false;
        }

        // Check if cell is blocked or already visited
        // If we are not at the destination (checked above), we must be on a walkable cell to proceed.
        if (!grid[r][c] || visited[r][c]) {
            return false;
        }

        // Mark current cell as visited
        visited[r][c] = true;

        // Explore neighbors
        for (int[] dir : DIRECTIONS) {
            int nr = r + dir[0];
            int nc = c + dir[1];

            if (dfs(nr, nc)) {
                return true;
            }
        }

        return false;
    }

    private boolean isValidCoordinate(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /**
     * Helper class for fast input reading.
     */
    static class FastReader {
        BufferedReader br;
        StringTokenizer st;

        public FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    e.printStackTrace();
                    return null;
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            String s = next();
            if (s == null) throw new RuntimeException("End of input");
            return Integer.parseInt(s);
        }
    }
}

import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.List;
import java.util.Queue;
import java.util.Scanner;

public class Main {

    public static void main(String[] args) {
        // Use try-with-resources to ensure the Scanner is properly closed
        try (Scanner scanner = new Scanner(System.in)) {
            if (!scanner.hasNextInt()) {
                return;
            }

            int rows = scanner.nextInt();
            int cols = scanner.nextInt();

            char[][] grid = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                grid[i] = scanner.next().toCharArray();
            }

            // Convert 1-based input to 0-based indexing
            int startR = scanner.nextInt() - 1;
            int startC = scanner.nextInt() - 1;
            int targetR = scanner.nextInt() - 1;
            int targetC = scanner.nextInt() - 1;

            boolean reachable = search(grid, startR, startC, targetR, targetC, rows, cols);
            System.out.println(reachable ? "YES" : "NO");
        }
    }

    /**
     * Performs a Breadth-First Search to determine if the target cell is reachable.
     * Uses a visited array instead of mutating the grid to avoid side effects.
     */
    private static boolean search(char[][] grid, int startR, int startC, 
                                  int targetR, int targetC, int rows, int cols) {
        boolean[][] visited = new boolean[rows][cols];
        Queue<Pair> queue = new ArrayDeque<>();

        queue.offer(new Pair(startR, startC));
        visited[startR][startC] = true;

        while (!queue.isEmpty()) {
            Pair current = queue.poll();

            if (current.r == targetR && current.c == targetC) {
                return true;
            }

            List<Pair> neighbors = getNeighbors(current.r, current.c, rows, cols);

            // Sort neighbors by Manhattan distance to target for heuristic ordering
            neighbors.sort((a, b) -> Integer.compare(
                Math.abs(targetR - a.r) + Math.abs(targetC - a.c),
                Math.abs(targetR - b.r) + Math.abs(targetC - b.c)
            ));

            for (Pair neighbor : neighbors) {
                if (visited[neighbor.r][neighbor.c]) {
                    continue;
                }

                // Preserve original logic: 'X' acts as an obstacle unless it is the target
                if (grid[neighbor.r][neighbor.c] == 'X' &&
                    !(neighbor.r == targetR && neighbor.c == targetC)) {
                    continue;
                }

                visited[neighbor.r][neighbor.c] = true;
                queue.offer(neighbor);
            }
        }
        return false;
    }

    /**
     * Generates all valid adjacent cells for a given position.
     */
    private static List<Pair> getNeighbors(int r, int c, int rows, int cols) {
        List<Pair> neighbors = new ArrayList<>();
        int[] dr = {-1, 1, 0, 0};
        int[] dc = {0, 0, -1, 1};

        for (int i = 0; i < 4; i++) {
            int nr = r + dr[i];
            int nc = c + dc[i];
            if (isValid(nr, nc, rows, cols)) {
                neighbors.add(new Pair(nr, nc));
            }
        }
        return neighbors;
    }

    /**
     * Checks if coordinates are within grid boundaries.
     */
    private static boolean isValid(int r, int c, int rows, int cols) {
        return r >= 0 && c >= 0 && r < rows && c < cols;
    }

    /**
     * Immutable coordinate pair to hold row and column indices.
     */
    private static class Pair {
        final int r;
        final int c;

        Pair(int r, int c) {
            this.r = r;
            this.c = c;
        }

        @Override
        public String toString() {
            return String.format("{r:%d,c:%d}", r, c);
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.ArrayDeque;
import java.util.Queue;
import java.util.StringTokenizer;

public class Main {

    // Direction vectors: Right, Down, Left, Up
    private static final int[][] DIRECTIONS = {
            {0, 1}, {1, 0}, {0, -1}, {-1, 0}
    };

    private BufferedReader reader;
    private PrintWriter writer;
    private StringTokenizer tokenizer;

    public static void main(String[] args) {
        new Main().run();
    }

    public void run() {
        try {
            init();
            solve();
        } catch (IOException e) {
            e.printStackTrace();
        } finally {
            if (writer != null) {
                writer.close();
            }
        }
    }

    private void init() throws IOException {
        reader = new BufferedReader(new InputStreamReader(System.in));
        writer = new PrintWriter(System.out);
    }

    private void solve() throws IOException {
        // 1. Read Grid Dimensions
        int numRows = nextInt();
        int numCols = nextInt();

        // 2. Read Grid
        char[][] grid = new char[numRows][numCols];
        for (int i = 0; i < numRows; i++) {
            String line = next();
            grid[i] = line.toCharArray();
        }

        // 3. Read Coordinates (Input is 1-based, convert to 0-based)
        int startRow = nextInt() - 1;
        int startCol = nextInt() - 1;
        int targetRow = nextInt() - 1;
        int targetCol = nextInt() - 1;

        // 4. BFS Initialization
        // Treat the starting position as empty to allow traversal if needed
        grid[startRow][startCol] = '.';

        Queue<int[]> queue = new ArrayDeque<>();
        queue.offer(new int[]{startRow, startCol});

        boolean[][] visited = new boolean[numRows][numCols];
        visited[startRow][startCol] = true;

        boolean reachable = false;

        // 5. Breadth-First Search
        while (!queue.isEmpty()) {
            int[] current = queue.poll();
            int currR = current[0];
            int currC = current[1];

            // Check if we reached the target
            if (currR == targetRow && currC == targetCol) {
                reachable = true;
                break;
            }

            // Explore neighbors
            for (int[] dir : DIRECTIONS) {
                int nextR = currR + dir[0];
                int nextC = currC + dir[1];

                if (isValid(nextR, nextC, numRows, numCols) && !visited[nextR][nextC]) {
                    boolean isTarget = (nextR == targetRow && nextC == targetCol);
                    boolean isEmpty = (grid[nextR][nextC] == '.');

                    // Logic: Can move to empty cells, or enter the target cell regardless of content
                    if (isEmpty || isTarget) {
                        visited[nextR][nextC] = true;
                        queue.offer(new int[]{nextR, nextC});
                    }
                }
            }
        }

        // 6. Post-BFS Logic
        // Count empty neighbors ('.') of the target cell
        int emptyNeighbors = 0;
        for (int[] dir : DIRECTIONS) {
            int nextR = targetRow + dir[0];
            int nextC = targetCol + dir[1];
            if (isValid(nextR, nextC, numRows, numCols) && grid[nextR][nextC] == '.') {
                emptyNeighbors++;
            }
        }

        // 7. Determine Output based on conditions
        if (startRow == targetRow && startCol == targetCol) {
            // If start is the target, we need at least one empty neighbor to be valid
            if (emptyNeighbors > 0) {
                writer.println("YES");
            } else {
                writer.println("NO");
            }
        } else {
            // If distinct, must be reachable AND (target is 'X' OR has >= 2 empty neighbors)
            if (reachable && (grid[targetRow][targetCol] == 'X' || emptyNeighbors >= 2)) {
                writer.println("YES");
            } else {
                writer.println("NO");
            }
        }
    }

    private boolean isValid(int r, int c, int rows, int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    // Fast I/O Helper Methods
    private String next() throws IOException {
        while (tokenizer == null || !tokenizer.hasMoreTokens()) {
            String line = reader.readLine();
            if (line == null) return null;
            tokenizer = new StringTokenizer(line);
        }
        return tokenizer.nextToken();
    }

    private int nextInt() throws IOException {
        String s = next();
        return (s == null) ? 0 : Integer.parseInt(s);
    }
}

