import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;

/**
 * Efficiently tracks and updates the number of contiguous '.' segments in a string.
 * Supports O(1) per-update complexity by analyzing local neighborhood changes.
 */
public class Main {
    private final char[] grid;
    private final int n;
    private int segmentCount;

    /**
     * Initializes the grid and calculates the initial number of contiguous '.' segments.
     *
     * @param n               Length of the string
     * @param initialString   The initial string of characters
     */
    public Main(int n, String initialString) {
        if (initialString == null || initialString.length() != n) {
            throw new IllegalArgumentException("Initial string length must match n");
        }
        this.n = n;
        this.grid = initialString.toCharArray();
        this.segmentCount = countInitialSegments();
    }

    /**
     * Counts the initial number of contiguous '.' segments using a state machine.
     *
     * @return The number of contiguous '.' segments
     */
    private int countInitialSegments() {
        int count = 0;
        boolean inSegment = false;
        for (char c : grid) {
            if (c == '.') {
                if (!inSegment) {
                    count++;
                    inSegment = true;
                }
            } else {
                inSegment = false;
            }
        }
        return count;
    }

    /**
     * Updates a character at the specified index and adjusts the segment count accordingly.
     * Indices are 0-based.
     *
     * @param index   The 0-based index to update
     * @param newChar The new character to place at the index
     * @return The updated segment count
     */
    public int update(int index, char newChar) {
        if (index < 0 || index >= n) {
            throw new IndexOutOfBoundsException("Index " + index + " is out of bounds for length " + n);
        }

        boolean wasDot = grid[index] == '.';
        boolean isDot = newChar == '.';

        // Only adjust count if the character type actually changes
        if (wasDot != isDot) {
            if (wasDot && !isDot) {
                // Removing a '.' character
                boolean leftNonDot = (index == 0 || grid[index - 1] != '.');
                boolean rightNonDot = (index == n - 1 || grid[index + 1] != '.');

                // If both neighbors are non-'.' (or boundaries), we removed an entire isolated segment
                if (leftNonDot && rightNonDot) {
                    segmentCount--;
                }
            } else if (!wasDot && isDot) {
                // Adding a '.' character
                boolean leftDot = (index == 0 || grid[index - 1] == '.');
                boolean rightDot = (index == n - 1 || grid[index + 1] == '.');

                if (leftDot && rightDot) {
                    // Merging two existing segments into one
                    segmentCount--;
                } else if (!leftDot && !rightDot) {
                    // Creating a new isolated segment
                    segmentCount++;
                }
                // If exactly one neighbor is '.', we are extending an existing segment -> count unchanged
            }
        }

        grid[index] = newChar;
        return segmentCount;
    }

    public static void main(String[] args) throws IOException {
        // Use buffered I/O for performance
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter out = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)));

        try {
            String line = br.readLine();
            if (line == null) return;

            String[] parts = line.trim().split("\\s+");
            int n = Integer.parseInt(parts[0]);
            int m = Integer.parseInt(parts[1]);

            String initialString = br.readLine();
            if (initialString == null) {
                initialString = "";
            } else {
                initialString = initialString.trim();
            }

            Main solver = new Main(n, initialString);

            for (int i = 0; i < m; i++) {
                line = br.readLine();
                if (line == null) break;

                parts = line.trim().split("\\s+");
                int index = Integer.parseInt(parts[0]) - 1; // Convert 1-based input to 0-based
                char newChar = parts[1].charAt(0);

                out.println(solver.update(index, newChar));
            }
        } finally {
            out.flush();
            out.close();
            br.close();
        }
    }
}

