/**
 * Refactored solution for the Dot Counter problem.
 * 
 * Refactoring Improvements:
 * 1. Class Naming: Renamed 'p3' to 'DotCounter' for better readability.
 * 2. Variable Naming: Replaced single-letter variables (n, m, s, a, x, c) with descriptive names.
 * 3. Data Structure: Replaced the 'a' array (where true meant non-dot) with 'isDot' (where true means dot)
 *    to align the boolean state with the semantic meaning of the character.
 * 4. Logic Simplification: Removed complex boundary checks (n=1, x=0) by using standard bounds checking
 *    (index > 0, index < n - 1). This eliminates magic numbers and edge-case specific blocks.
 * 5. Code Structure: Separated I/O handling from business logic using a 'solve' method.
 * 6. I/O Efficiency: Implemented a clean, standard 'FastScanner' class to replace the verbose 'InputReader'.
 * 7. Removed Unused Imports: Removed 'java.math.*' as it was not used.
 */
public class DotCounter {

    public static void main(String[] args) {
        // Initialize Fast I/O
        FastScanner scanner = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            solve(scanner, out);
        } finally {
            out.flush();
            out.close();
        }
    }

    private static void solve(FastScanner scanner, PrintWriter out) {
        // Read n (length of string) and m (number of queries)
        // Using next() then parseInt() to handle potential nulls gracefully, 
        // though standard CP inputs are usually well-formed.
        String nStr = scanner.next();
        if (nStr == null) return;
        int n = Integer.parseInt(nStr);

        int m = scanner.nextInt();
        String initialString = scanner.next();

        // Array to track the state of each character.
        // true means the character is a dot ('.'), false means it is not.
        // Size is exactly n, removing the need for n+10 padding.
        boolean[] isDot = new boolean[n];
        for (int i = 0; i < n; i++) {
            isDot[i] = (initialString.charAt(i) == '.');
        }

        // Calculate initial count of adjacent dot pairs ("..")
        int adjacentDotsCount = 0;
        for (int i = 0; i < n - 1; i++) {
            if (isDot[i] && isDot[i + 1]) {
                adjacentDotsCount++;
            }
        }

        // Process queries
        for (int i = 0; i < m; i++) {
            int index = scanner.nextInt() - 1; // Convert 1-based input to 0-based index
            String charType = scanner.next();
            boolean shouldBeDot = (charType.charAt(0) == '.');

            // If the character is already in the desired state, count doesn't change
            if (isDot[index] == shouldBeDot) {
                out.println(adjacentDotsCount);
                continue;
            }

            // Update the count based on neighbors
            if (shouldBeDot) {
                // We are changing a non-dot to a dot.
                // Check if it forms pairs with existing dots to the left and right.
                if (index > 0 && isDot[index - 1]) {
                    adjacentDotsCount++;
                }
                if (index < n - 1 && isDot[index + 1]) {
                    adjacentDotsCount++;
                }
            } else {
                // We are changing a dot to a non-dot.
                // Check if it breaks pairs with existing dots to the left and right.
                if (index > 0 && isDot[index - 1]) {
                    adjacentDotsCount--;
                }
                if (index < n - 1 && isDot[index + 1]) {
                    adjacentDotsCount--;
                }
            }

            // Update the state of the current position
            isDot[index] = shouldBeDot;

            // Output the current count
            out.println(adjacentDotsCount);
        }
    }

    /**
     * FastScanner class for efficient input reading.
     * Replaces the original InputReader with a cleaner implementation.
     */
    static class FastScanner {
        BufferedReader reader;
        StringTokenizer tokenizer;

        public FastScanner(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            String s = next();
            if (s == null) throw new RuntimeException("End of input");
            return Integer.parseInt(s);
        }
    }
}

