import java.util.StringTokenizer;

/**
 * Refactored program to track the number of consecutive dot pairs ("..")
 * in a string under a series of character updates.
 * 
 * Improvements:
 * 1. Readability: Meaningful variable names and method extraction.
 * 2. Maintainability: Separation of concerns (I/O vs Logic).
 * 3. Resource Management: Try-with-resources for automatic stream closure.
 * 4. Performance: StringTokenizer for parsing and O(1) updates per query.
 * 5. Robustness: Boundary checks handled cleanly without deep nesting.
 */
public class ConsecutiveDotsCounter {

    public static void main(String[] args) throws IOException {
        // Use try-with-resources to ensure streams are closed automatically
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
             BufferedWriter writer = new BufferedWriter(new OutputStreamWriter(System.out))) {

            // Read N (length) and M (number of queries)
            StringTokenizer st = new StringTokenizer(reader.readLine());
            int n = Integer.parseInt(st.nextToken());
            int m = Integer.parseInt(st.nextToken());

            // Read the initial string
            char[] grid = reader.readLine().toCharArray();

            // Calculate the initial count of consecutive dot pairs ("..")
            int consecutivePairs = calculateInitialPairs(grid);

            // Process each query
            for (int i = 0; i < m; i++) {
                String line = reader.readLine();
                if (line == null || line.trim().isEmpty()) break;

                st = new StringTokenizer(line);
                // Convert 1-based index from input to 0-based index
                int index = Integer.parseInt(st.nextToken()) - 1; 
                char newChar = st.nextToken().charAt(0);

                // Apply update and get the change in the count
                int change = applyUpdate(grid, index, newChar, n);
                consecutivePairs += change;

                // Write the current count to output
                writer.write(String.valueOf(consecutivePairs));
                writer.newLine();
            }

            writer.flush();
        }
    }

    /**
     * Calculates the number of consecutive dot pairs in the initial grid.
     * A pair is defined as two adjacent dots ("..").
     */
    private static int calculateInitialPairs(char[] grid) {
        int count = 0;
        // Iterate from the second character to the end
        for (int i = 1; i < grid.length; i++) {
            if (grid[i] == '.' && grid[i - 1] == '.') {
                count++;
            }
        }
        return count;
    }

    /**
     * Updates the character at the specified index and calculates the change
     * in the number of consecutive dot pairs.
     * 
     * @param grid The character array representing the string
     * @param index The 0-based index to update
     * @param newChar The new character to place
     * @param length The total length of the grid
     * @return The change in the consecutive pairs count (+1, -1, -2, +2, or 0)
     */
    private static int applyUpdate(char[] grid, int index, char newChar, int length) {
        // If the character is already what we want, no change occurs
        if (grid[index] == newChar) {
            return 0;
        }

        int change = 0;

        if (newChar == '.') {
            // We are placing a dot. We check neighbors to see if we form new pairs.
            // Check left neighbor
            if (index > 0 && grid[index - 1] == '.') {
                change++;
            }
            // Check right neighbor
            if (index < length - 1 && grid[index + 1] == '.') {
                change++;
            }
        } else {
            // We are removing a dot (replacing it with a non-dot).
            // We check neighbors to see if we break existing pairs.
            // Check left neighbor
            if (index > 0 && grid[index - 1] == '.') {
                change--;
            }
            // Check right neighbor
            if (index < length - 1 && grid[index + 1] == '.') {
                change--;
            }
        }

        // Commit the change to the grid
        grid[index] = newChar;

        return change;
    }
}

