/**
 * Handles the core problem logic: counting adjacent '.' pairs and processing point updates.
 */
class Task {
    /**
     * Solves the problem by computing the initial count of adjacent '.' pairs,
     * then efficiently updating the count after each character replacement.
     */
    public void solve(FastReader in, PrintWriter out) {
        int len = in.nextInt();
        int nQuery = in.nextInt();
        char[] str = in.next().toCharArray();

        // Initial count of adjacent '.' pairs
        int ans = 0;
        for (int i = 0; i < len - 1; i++) {
            if (str[i] == '.' && str[i + 1] == '.') {
                ans++;
            }
        }

        // Process each query
        for (int i = 0; i < nQuery; i++) {
            int idx = in.nextInt() - 1; // Convert to 0-based index
            char newChar = in.next().charAt(0);

            // 1. Remove contribution of the old character to adjacent pairs
            if (idx > 0 && str[idx - 1] == '.' && str[idx] == '.') ans--;
            if (idx < len - 1 && str[idx] == '.' && str[idx + 1] == '.') ans--;

            // 2. Apply the update
            str[idx] = newChar;

            // 3. Add contribution of the new character to adjacent pairs
            if (idx > 0 && str[idx - 1] == '.' && str[idx] == '.') ans++;
            if (idx < len - 1 && str[idx] == '.' && str[idx + 1] == '.') ans++;

            out.println(ans);
        }
    }
}

