/**
 * Encapsulates the core business logic for processing the dot-string problem.
 */
class DotStringSolver {
    private final FastScanner scanner;
    private final PrintWriter out;
    private SegmentTree segmentTree;
    private boolean[] dotStatus;

    public DotStringSolver(FastScanner scanner, PrintWriter out) {
        this.scanner = scanner;
        this.out = out;
    }

    public void solve() {
        int n = scanner.nextInt();
        int m = scanner.nextInt();
        String initialString = scanner.next();

        dotStatus = new boolean[n];
        for (int i = 0; i < n; i++) {
            dotStatus[i] = initialString.charAt(i) == '.';
        }

        if (n > 0) {
            segmentTree = new SegmentTree(dotStatus);
        }

        for (int i = 0; i < m; i++) {
            int pos = scanner.nextInt() - 1; // Convert to 0-based index
            char newChar = scanner.next().charAt(0);
            boolean isDot = newChar == '.';

            // Only update if the actual state changes
            if (dotStatus[pos] != isDot) {
                segmentTree.update(pos, isDot);
                dotStatus[pos] = isDot;
            }

            out.println(segmentTree.query());
        }
    }
}

/**
 * Segment Tree implementation for counting contiguous '.' segments.
 * Supports point updates and range aggregate queries.
 */
class SegmentTree {
    private static final SegmentTreeNode FALSE_NODE = new SegmentTreeNode(0, false, false);
    private static final SegmentTreeNode TRUE_NODE = new SegmentTreeNode(0, true, true);

    private final SegmentTreeNode[] tree;
    private final int n;

    public SegmentTree(boolean[] dotStatus) {
        this.n = dotStatus.length;
        // Standard segment tree array size: 4 * n
        this.tree = new SegmentTreeNode[4 * n];
        build(dotStatus, 1, 0, n - 1);
    }

    private void build(boolean[] dotStatus, int node, int start, int end) {
        if (start == end) {
            tree[node] = dotStatus[start] ? TRUE_NODE : FALSE_NODE;
        } else {
            int mid = (start + end) / 2;
            build(dotStatus, 2 * node, start, mid);
            build(dotStatus, 2 * node + 1, mid + 1, end);

            SegmentTreeNode left = tree[2 * node];
            SegmentTreeNode right = tree[2 * node + 1];

            int mergedCount = left.count + right.count + (left.isRightDot && right.isLeftDot ? 1 : 0);
            tree[node] = new SegmentTreeNode(mergedCount, left.isLeftDot, right.isRightDot);
        }
    }

    public void update(int pos, boolean isDot) {
        update(1, 0, n - 1, pos, isDot);
    }

    private void update(int node, int start, int end, int pos, boolean isDot) {
        if (start == end) {
            tree[node] = isDot ? TRUE_NODE : FALSE_NODE;
        } else {
            int mid = (start + end) / 2;
            if (pos <= mid) {
                update(2 * node, start, mid, pos, isDot);
            } else {
                update(2 * node + 1, mid + 1, end, pos, isDot);
            }

            SegmentTreeNode left = tree[2 * node];
            SegmentTreeNode right = tree[2 * node + 1];

            int mergedCount = left.count + right.count + (left.isRightDot && right.isLeftDot ? 1 : 0);
            tree[node] = new SegmentTreeNode(mergedCount, left.isLeftDot, right.isRightDot);
        }
    }

    public int query() {
        return tree[1].count;
    }

    /**
     * Immutable node representing a segment in the tree.
     * @param count   Number of contiguous '.' segments in this range
     * @param isLeftDot  True if the leftmost character in this range is '.'
     * @param isRightDot True if the rightmost character in this range is '.'
     */
    private static class SegmentTreeNode {
        final int count;
        final boolean isLeftDot;
        final boolean isRightDot;

        SegmentTreeNode(int count, boolean isLeftDot, boolean isRightDot) {
            this.count = count;
            this.isLeftDot = isLeftDot;
            this.isRightDot = isRightDot;
        }
    }
}

