import java.io.BufferedReader;
import java.io.BufferedOutputStream;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.NavigableSet;
import java.util.Objects;
import java.util.StringTokenizer;
import java.util.TreeSet;

/**
 * Refactored Solution class.
 * 
 * Key Improvements:
 * 1. Removed unnecessary Thread inheritance. Multithreading was not required and 
 *    complicated resource management and exception handling.
 * 2. Fixed resource leaks by using try-with-resources in main().
 * 3. Corrected Segment.compareTo() to be consistent with equals() and work 
 *    predictably with NavigableSet.
 * 4. Fixed off-by-one errors in segment length calculation.
 * 5. Replaced System.exit(666) with standard exception propagation and logging.
 * 6. Improved input parsing to handle whitespace and newlines robustly.
 * 7. Applied consistent naming, immutability (final fields), and defensive 
 *    programming practices.
 */
public class Solution {

    private final BufferedReader input;
    private final PrintWriter output;
    private StringTokenizer tokenizer;

    /**
     * Constructs a Solution with specified input and output streams.
     *
     * @param input  Reader for input data
     * @param output Writer for output data
     */
    public Solution(BufferedReader input, PrintWriter output) {
        this.input = input;
        this.output = output;
    }

    /**
     * Represents an inclusive interval [l, r].
     */
    static class Segment implements Comparable<Segment> {
        final int l;
        final int r;

        public Segment(int l, int r) {
            if (l > r) {
                throw new IllegalArgumentException("Invalid segment: l (" + l + ") > r (" + r + ")");
            }
            this.l = l;
            this.r = r;
        }

        @Override
        public int compareTo(Segment other) {
            if (this.l != other.l) {
                return Integer.compare(this.l, other.l);
            }
            return Integer.compare(this.r, other.r);
        }

        @Override
        public boolean equals(Object o) {
            if (this == o) return true;
            if (!(o instanceof Segment)) return false;
            Segment segment = (Segment) o;
            return l == segment.l && r == segment.r;
        }

        @Override
        public int hashCode() {
            return Objects.hash(l, r);
        }

        /**
         * Returns the number of elements in this inclusive segment.
         */
        public int length() {
            return r - l + 1;
        }
    }

    /**
     * Executes the main algorithm: parses initial segments and processes updates.
     */
    public void solve() throws IOException {
        String nStr = next();
        if (nStr == null) return;

        int n = Integer.parseInt(nStr);
        int m = Integer.parseInt(next());
        char[] str = next().toCharArray();

        int currentDotCount = 0;
        NavigableSet<Segment> segments = new TreeSet<>();

        // Identify initial contiguous segments of '.'
        for (int i = 0; i < n; ) {
            if (str[i] == '.') {
                int start = i;
                while (i < n && str[i] == '.') {
                    i++;
                }
                int end = i - 1;
                segments.add(new Segment(start, end));
                currentDotCount += end - start + 1;
            } else {
                i++;
            }
        }

        // Process update queries
        for (int q = 0; q < m; q++) {
            int index = Integer.parseInt(next()) - 1; // Convert to 0-based
            String cStr = next();
            char c = cStr.charAt(0);

            if (c == '.') {
                Segment pointSegment = new Segment(index, index);
                Segment floor = segments.floor(pointSegment);
                Segment ceiling = segments.ceiling(pointSegment);

                int newL = index;
                int newR = index;

                // Merge with adjacent left segment if it ends exactly before index
                if (floor != null && floor.r == index - 1) {
                    segments.remove(floor);
                    currentDotCount -= floor.length();
                    newL = floor.l;
                }

                // Merge with adjacent right segment if it starts exactly after index
                if (ceiling != null && ceiling.l == index + 1) {
                    segments.remove(ceiling);
                    currentDotCount -= ceiling.length();
                    newR = ceiling.r;
                }

                segments.add(new Segment(newL, newR));
                currentDotCount += newR - newL + 1;

            } else {
                // Find the segment containing the target index
                Segment containing = segments.floor(new Segment(index, index));
                if (containing != null && containing.r >= index) {
                    segments.remove(containing);
                    currentDotCount -= containing.length();

                    // Preserve left portion if it exists
                    if (containing.l < index) {
                        segments.add(new Segment(containing.l, index - 1));
                        currentDotCount += index - containing.l;
                    }
                    // Preserve right portion if it exists
                    if (index < containing.r) {
                        segments.add(new Segment(index + 1, containing.r));
                        currentDotCount += containing.r - index;
                    }
                }
            }
            output.println(currentDotCount);
        }
    }

    /**
     * Reads the next token from input, handling line breaks automatically.
     *
     * @return Next token string, or null if end of input is reached
     */
    private String next() throws IOException {
        while (tokenizer == null || !tokenizer.hasMoreTokens()) {
            String line = input.readLine();
            if (line == null) {
                return null;
            }
            tokenizer = new StringTokenizer(line);
        }
        return tokenizer.nextToken();
    }

    /**
     * Parses the next token as an integer.
     *
     * @return Parsed integer
     * @throws IOException              If an I/O error occurs
     * @throws java.util.NoSuchElementException If end of input is reached unexpectedly
     */
    private int nextInt() throws IOException {
        String token = next();
        if (token == null) {
            throw new java.util.NoSuchElementException("Unexpected end of input");
        }
        return Integer.parseInt(token);
    }

    public static void main(String[] args) {
        // Use try-with-resources to guarantee stream closure
        try (BufferedReader input = new BufferedReader(new InputStreamReader(System.in));
             PrintWriter output = new PrintWriter(new BufferedOutputStream(System.out))) {

            new Solution(input, output).solve();
            output.flush(); // Ensure all buffered output is written
        } catch (IOException e) {
            System.err.println("I/O Error: " + e.getMessage());
            e.printStackTrace();
        } catch (Exception e) {
            System.err.println("Runtime Error: " + e.getMessage());
            e.printStackTrace();
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.OutputStreamWriter;
import java.io.PrintWriter;
import java.util.StringTokenizer;

/**
 * Refactored Solution class.
 * 
 * Changes made:
 * 1. Renamed variables for clarity (e.g., 'tot' -> 'pairCount', 's' -> 'scanner').
 * 2. Encapsulated FastScanner logic to handle input robustly.
 * 3. Separated the core algorithm logic into a dedicated 'solve' method.
 * 4. Optimized the update logic: Instead of re-scanning or complex branching, 
 *    we calculate the change in 'pairCount' based only on the immediate neighbors 
 *    of the modified position. This reduces complexity and code duplication.
 * 5. Used PrintWriter for efficient output.
 * 6. Removed unused imports and static state where possible.
 */
public class Solution {

    /**
     * FastScanner helper class for efficient input reading.
     */
    static class FastScanner {
        BufferedReader br;
        StringTokenizer st;

        public FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    e.printStackTrace();
                    return null;
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            String s = next();
            if (s == null) return 0; // Handle potential EOF
            return Integer.parseInt(s);
        }
    }

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner();
        PrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));

        try {
            Solution solver = new Solution();
            solver.solve(scanner, out);
        } catch (Exception e) {
            e.printStackTrace();
        } finally {
            out.flush();
            out.close();
        }
    }

    /**
     * Solves the problem by processing the initial string and subsequent queries.
     */
    void solve(FastScanner scanner, PrintWriter out) {
        // Read n (length of string) and m (number of queries)
        int n = scanner.nextInt();
        int m = scanner.nextInt();

        String str = scanner.next();
        if (str == null) return;

        char[] arr = str.toCharArray();
        int len = arr.length;

        // Calculate initial count of adjacent dot pairs
        int pairCount = calculateInitialPairs(arr);

        for (int i = 0; i < m; i++) {
            int pos = scanner.nextInt() - 1; // Convert 1-based index to 0-based
            String token = scanner.next();
            char newChar = token.charAt(0);

            // Optimization: If the character is already the same, output current count and continue
            if (pos >= 0 && pos < len && arr[pos] == newChar) {
                out.println(pairCount);
                continue;
            }

            // Safety check for out-of-bounds position
            if (pos < 0 || pos >= len) {
                out.println(pairCount);
                continue;
            }

            char oldChar = arr[pos];

            // 1. Remove contribution of the old character if it was a dot
            // A dot at 'pos' contributes to a pair if its neighbor is also a dot.
            if (oldChar == '.') {
                // Check right neighbor (pair: pos, pos+1)
                if (pos + 1 < len && arr[pos + 1] == '.') {
                    pairCount--;
                }
                // Check left neighbor (pair: pos-1, pos)
                if (pos - 1 >= 0 && arr[pos - 1] == '.') {
                    pairCount--;
                }
            }

            // Update the array with the new character
            arr[pos] = newChar;

            // 2. Add contribution of the new character if it is a dot
            if (newChar == '.') {
                // Check right neighbor (pair: pos, pos+1)
                if (pos + 1 < len && arr[pos + 1] == '.') {
                    pairCount++;
                }
                // Check left neighbor (pair: pos-1, pos)
                if (pos - 1 >= 0 && arr[pos - 1] == '.') {
                    pairCount++;
                }
            }

            out.println(pairCount);
        }
    }

    /**
     * Helper method to count initial adjacent dot pairs in the array.
     * A pair is defined as two adjacent dots (e.g., "..").
     */
    private int calculateInitialPairs(char[] arr) {
        int count = 0;
        // Iterate up to length - 2 to safely access i+1
        for (int i = 0; i < arr.length - 1; i++) {
            if (arr[i] == '.' && arr[i + 1] == '.') {
                count++;
            }
        }
        return count;
    }
}

import java.io.BufferedWriter;
import java.io.IOException;
import java.io.InputStream;
import java.io.OutputStream;
import java.io.OutputStreamWriter;
import java.io.PrintWriter;
import java.util.InputMismatchException;

public class Main {
    public static void main(String[] args) {
        InputReader in = new InputReader(System.in);
        OutputWriter out = new OutputWriter(System.out);
        new TaskC().solve(1, in, out);
        out.close();
    }

    /**
     * Solves the problem by tracking the number of '.' characters (dotCount)
     * and the number of contiguous '.' blocks (dotBlocks).
     * Each update modifies these counts in O(1) time by examining neighbors.
     */
    static class TaskC {
        public void solve(int testNumber, InputReader in, OutputWriter out) {
            int n = in.readInt();
            int m = in.readInt();
            String s = in.readLine();
            char[] c = s.toCharArray();

            // Initial calculation of dots and contiguous blocks
            int dotCount = 0;
            int dotBlocks = 0;
            boolean inBlock = false;

            for (int i = 0; i < n; i++) {
                if (c[i] == '.') {
                    dotCount++;
                    if (!inBlock) {
                        dotBlocks++;
                        inBlock = true;
                    }
                } else {
                    inBlock = false;
                }
            }

            // Process each update
            for (int i = 0; i < m; i++) {
                int index = in.readInt() - 1; // Convert 1-based to 0-based
                char newChar = in.readCharacter();
                char oldChar = c[index];

                if (oldChar != newChar) {
                    boolean leftIsDot = (index > 0 && c[index - 1] == '.');
                    boolean rightIsDot = (index < n - 1 && c[index + 1] == '.');

                    if (oldChar == '.' && newChar != '.') {
                        // Removing a '.'
                        dotCount--;
                        if (leftIsDot && rightIsDot) {
                            dotBlocks++; // Split a block into two
                        } else if (!leftIsDot && !rightIsDot) {
                            dotBlocks--; // Remove an isolated '.'
                        }
                        // Otherwise, removing from the edge of a block doesn't change block count
                    } else if (oldChar != '.' && newChar == '.') {
                        // Adding a '.'
                        dotCount++;
                        if (leftIsDot && rightIsDot) {
                            dotBlocks--; // Merge two blocks into one
                        } else if (!leftIsDot && !rightIsDot) {
                            dotBlocks++; // Create a new isolated '.'
                        }
                        // Otherwise, adding to the edge of a block doesn't change block count
                    }

                    c[index] = newChar;
                }

                out.printLine(dotCount - dotBlocks);
            }
        }
    }

    /**
     * Fast Input Reader for competitive programming environments.
     */
    static class InputReader {
        private final InputStream stream;
        private final byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;
        private SpaceCharFilter filter;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        public int read() {
            if (numChars == -1) {
                throw new InputMismatchException();
            }
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0) {
                    return -1;
                }
            }
            return buf[curChar++];
        }

        public int readInt() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                res *= 10;
                res += c - '0';
                c = read();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public boolean isSpaceChar(int c) {
            return filter != null ? filter.isSpaceChar(c) : isWhitespace(c);
        }

        public static boolean isWhitespace(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        private String readLine0() {
            StringBuilder buf = new StringBuilder();
            int c = read();
            while (c != '\n' && c != -1) {
                if (c != '\r') {
                    buf.appendCodePoint(c);
                }
                c = read();
            }
            return buf.toString();
        }

        public String readLine() {
            String s = readLine0();
            while (s.trim().isEmpty()) {
                s = readLine0();
            }
            return s;
        }

        public char readCharacter() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            return (char) c;
        }

        public interface SpaceCharFilter {
            boolean isSpaceChar(int ch);
        }
    }

    /**
     * Fast Output Writer for competitive programming environments.
     */
    static class OutputWriter {
        private final PrintWriter writer;

        public OutputWriter(OutputStream outputStream) {
            writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(outputStream)));
        }

        public OutputWriter(Writer writer) {
            this.writer = new PrintWriter(writer);
        }

        public void close() {
            writer.close();
        }

        public void printLine(int i) {
            writer.println(i);
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

/**
 * A program to manage a string of characters and count adjacent dot pairs.
 * It processes a series of queries to update characters and reports the
 * updated count of adjacent dot pairs after each change.
 */
public class DotPairCounter {

    public static void main(String[] args) throws IOException {
        // Use BufferedReader for efficient input reading
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));

        // Read the first line containing n (length of string) and m (number of queries)
        String firstLine = reader.readLine();
        if (firstLine == null) return;

        StringTokenizer st = new StringTokenizer(firstLine);
        int length = Integer.parseInt(st.nextToken());
        int queryCount = Integer.parseInt(st.nextToken());

        // Read the string s
        String sLine = reader.readLine();
        if (sLine == null) return;
        char[] data = sLine.toCharArray();

        // Calculate the initial number of adjacent dot pairs
        int ans = 0;
        for (int i = 1; i < length; i++) {
            if (data[i] == '.' && data[i - 1] == '.') {
                ans++;
            }
        }

        // Process each query
        for (int i = 0; i < queryCount; i++) {
            String queryLine = reader.readLine();
            if (queryLine == null) break;

            // Parse index and new character
            // Using StringTokenizer to handle potential whitespace variations robustly
            st = new StringTokenizer(queryLine);
            int index = Integer.parseInt(st.nextToken()) - 1; // Convert 1-based to 0-based
            char newChar = st.nextToken().charAt(0);

            // Update the count and the character array
            ans += updatePairCount(data, index, newChar);

            // Print the current count
            System.out.println(ans);
        }
    }

    /**
     * Updates the character at the specified index and adjusts the pair count accordingly.
     * This method calculates the delta change in the number of adjacent dot pairs
     * resulting from the character change, ensuring O(1) complexity per update.
     *
     * @param data    The character array representing the string.
     * @param index   The 0-based index to update.
     * @param newChar The new character to place at the index.
     * @return The change in the pair count (delta).
     */
    private static int updatePairCount(char[] data, int index, char newChar) {
        char oldChar = data[index];

        // If the character is not changing, the pair count remains the same
        if (oldChar == newChar) {
            return 0;
        }

        int delta = 0;

        // 1. Remove contribution of the OLD character
        // If the old character was '.', it might have been part of pairs with neighbors.
        if (oldChar == '.') {
            // Check Left Neighbor (Pair: index-1, index)
            if (index > 0 && data[index - 1] == '.') {
                delta--;
            }
            // Check Right Neighbor (Pair: index, index+1)
            if (index < data.length - 1 && data[index + 1] == '.') {
                delta--;
            }
        }

        // Update the array with the new character
        data[index] = newChar;

        // 2. Add contribution of the NEW character
        // If the new character is '.', it might form pairs with neighbors.
        if (newChar == '.') {
            // Check Left Neighbor
            if (index > 0 && data[index - 1] == '.') {
                delta++;
            }
            // Check Right Neighbor
            if (index < data.length - 1 && data[index + 1] == '.') {
                delta++;
            }
        }

        return delta;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

/**
 * Refactored program to calculate dot counts and segment changes.
 */
public class Replacement {

    // I/O resources
    private FastScanner in;
    private PrintWriter out;

    public static void main(String[] args) {
        Replacement solution = new Replacement();
        solution.in = new FastScanner(new BufferedReader(new InputStreamReader(System.in)));
        solution.out = new PrintWriter(System.out);
        solution.solve();
        solution.out.close();
    }

    private void solve() {
        // Read n (string length) and m (number of queries)
        int strLength = in.nextInt();
        int numQueries = in.nextInt();

        // Read the initial string
        String inputString = in.nextToken();
        char[] chars = inputString.toCharArray();

        // Calculate initial counts
        int dotCount = 0;
        int segmentCount = 0;

        // Linear scan to count total dots and contiguous segments
        for (int i = 0; i < strLength; i++) {
            if (chars[i] == '.') {
                dotCount++;
                // A new segment starts if it's the first character 
                // or the previous character was not a dot.
                if (i == 0 || chars[i - 1] != '.') {
                    segmentCount++;
                }
            }
        }

        // Process queries
        for (int k = 0; k < numQueries; k++) {
            int queryIndex = in.nextInt() - 1; // Convert to 0-based index
            char newChar = in.nextToken().charAt(0);

            if (newChar == '.' && chars[queryIndex] != '.') {
                // Case 1: Changing a non-dot character to a dot

                dotCount++;
                chars[queryIndex] = '.';

                boolean hasLeftDot = (queryIndex > 0 && chars[queryIndex - 1] == '.');
                boolean hasRightDot = (queryIndex < strLength - 1 && chars[queryIndex + 1] == '.');

                if (hasLeftDot && hasRightDot) {
                    // Merged two existing segments into one
                    segmentCount--;
                } else if (!hasLeftDot && !hasRightDot) {
                    // Created a new isolated segment
                    segmentCount++;
                }
                // If exactly one neighbor is a dot, the segment count remains unchanged 
                // (we just extended an existing segment).

            } else if (newChar != '.' && chars[queryIndex] == '.') {
                // Case 2: Changing a dot to a non-dot character

                dotCount--;
                chars[queryIndex] = newChar; // Update the array

                boolean hasLeftDot = (queryIndex > 0 && chars[queryIndex - 1] == '.');
                boolean hasRightDot = (queryIndex < strLength - 1 && chars[queryIndex + 1] == '.');

                if (hasLeftDot && hasRightDot) {
                    // Split an existing segment into two
                    segmentCount++;
                } else if (!hasLeftDot && !hasRightDot) {
                    // Removed an isolated segment
                    segmentCount--;
                }
                // If exactly one neighbor is a dot, the segment count remains unchanged.
            }

            // Output the result for the current query
            out.println(dotCount - segmentCount);
        }
    }

    /**
     * Utility class for fast input reading.
     */
    static class FastScanner {
        private final BufferedReader in;
        private StringTokenizer st;

        public FastScanner(BufferedReader in) {
            this.in = in;
        }

        public String nextToken() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = in.readLine();
                    if (line == null) {
                        return null;
                    }
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            String token = nextToken();
            if (token == null) throw new RuntimeException("End of input");
            return Integer.parseInt(token);
        }

        public long nextLong() {
            String token = nextToken();
            if (token == null) throw new RuntimeException("End of input");
            return Long.parseLong(token);
        }

        public double nextDouble() {
            String token = nextToken();
            if (token == null) throw new RuntimeException("End of input");
            return Double.parseDouble(token);
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;
import java.util.TreeSet;

public class Main {
    public static void main(String[] args) {
        InputReader in = new InputReader(System.in);
        PrintWriter out = new PrintWriter(System.out);
        new DotSegmentSolver().solve(in, out);
        out.flush();
        out.close();
    }

    /**
     * Solves the dot-segment tracking problem.
     * Maintains a set of contiguous dot segments and calculates the sum of (length - 1)
     * for all segments, updating it efficiently after each character change.
     */
    static class DotSegmentSolver {
        private char[] s;
        private int n;
        private int ans;
        private final TreeSet<Segment> segments = new TreeSet<>();
        private PrintWriter out;

        public void solve(InputReader in, PrintWriter out) {
            this.out = out;
            n = in.nextInt();
            m = in.nextInt();
            s = in.next().toCharArray();

            initializeSegments();

            for (int i = 0; i < m; i++) {
                int x = in.nextInt() - 1; // Convert to 0-based index
                char c = in.next().charAt(0);
                processQuery(x, c);
            }
        }

        /**
         * Scans the initial string and populates the segment set.
         * ans is initialized to the sum of (segmentLength - 1) for all dot sequences.
         */
        private void initializeSegments() {
            int start = -1;
            for (int i = 0; i < n; i++) {
                if (s[i] == '.') {
                    if (start == -1) {
                        start = i;
                    }
                } else {
                    if (start != -1) {
                        addSegment(start, i - 1);
                        start = -1;
                    }
                }
            }
            if (start != -1) {
                addSegment(start, n - 1);
            }
        }

        private void addSegment(int start, int end) {
            segments.add(new Segment(start, end));
            ans += (end - start);
        }

        private void processQuery(int x, char c) {
            if (s[x] == c) {
                out.println(ans);
                return;
            }
            s[x] = c;
            if (c == '.') {
                addDot(x);
            } else {
                removeDot(x);
            }
            out.println(ans);
        }

        /**
         * Handles adding a dot at index x.
         * Checks left and right neighbors to determine if we need to:
         * 1. Merge two existing segments
         * 2. Extend an existing segment
         * 3. Create a new isolated segment
         */
        private void addDot(int x) {
            boolean hasLeft = x > 0 && s[x - 1] == '.';
            boolean hasRight = x < n - 1 && s[x + 1] == '.';

            if (hasLeft && hasRight) {
                Segment leftSeg = getSegmentContaining(x - 1);
                Segment rightSeg = getSegmentContaining(x + 1);

                segments.remove(leftSeg);
                segments.remove(rightSeg);

                // Remove old contributions
                ans -= (leftSeg.end - leftSeg.start);
                ans -= (rightSeg.end - rightSeg.start);

                // Add merged segment contribution
                int newStart = leftSeg.start;
                int newEnd = rightSeg.end;
                ans += (newEnd - newStart);

                segments.add(new Segment(newStart, newEnd));
            } else if (hasLeft) {
                Segment leftSeg = getSegmentContaining(x - 1);
                segments.remove(leftSeg);
                ans -= (leftSeg.end - leftSeg.start);
                segments.add(new Segment(leftSeg.start, x));
                ans += (x - leftSeg.start);
            } else if (hasRight) {
                Segment rightSeg = getSegmentContaining(x + 1);
                segments.remove(rightSeg);
                ans -= (rightSeg.end - rightSeg.start);
                segments.add(new Segment(x, rightSeg.end));
                ans += (rightSeg.end - x);
            } else {
                // Isolated dot: length 1 -> contributes 0 to ans
                segments.add(new Segment(x, x));
            }
        }

        /**
         * Handles removing a dot at index x.
         * Splits the containing segment into left and right parts if they exist.
         */
        private void removeDot(int x) {
            Segment seg = getSegmentContaining(x);
            if (seg == null) return; // Should not occur given problem constraints

            segments.remove(seg);
            ans -= (seg.end - seg.start);

            if (seg.start <= x - 1) {
                segments.add(new Segment(seg.start, x - 1));
                ans += (x - 1 - seg.start);
            }
            if (x + 1 <= seg.end) {
                segments.add(new Segment(x + 1, seg.end));
                ans += (seg.end - (x + 1));
            }
        }

        /**
         * Finds the segment that contains the given index.
         * Uses TreeSet.floor() for O(log N) lookup.
         */
        private Segment getSegmentContaining(int index) {
            Segment probe = new Segment(index, index);
            Segment seg = segments.floor(probe);
            if (seg != null && seg.end >= index) {
                return seg;
            }
            return null;
        }

        /**
         * Represents a contiguous range of dots [start, end].
         * Ordered by start index for efficient TreeSet operations.
         */
        static class Segment implements Comparable<Segment> {
            final int start;
            final int end;

            public Segment(int start, int end) {
                this.start = start;
