import java.io.PrintWriter;
import java.util.StringTokenizer;

/**
 * Solves a problem involving counting adjacent dot ('.') pairs in a string
 * and efficiently updating the count after character modifications.
 * Time Complexity: O(n) initialization, O(1) per query.
 */
public class R316C {

    public static void main(String[] args) {
        InputReader in = new InputReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        int n = in.nextInt();
        int m = in.nextInt();
        char[] s = in.next().toCharArray();

        int f = countAdjacentDotPairs(s);

        for (int q = 0; q < m; q++) {
            int i = in.nextInt() - 1; // Convert to 0-based index
            char newChar = in.next().charAt(0);

            char oldChar = s[i];
            if (oldChar == newChar) {
                out.println(f);
                continue;
            }

            int delta = calculateDelta(oldChar, newChar, i, s);
            f += delta;
            s[i] = newChar;
            out.println(f);
        }

        out.flush();
    }

    /**
     * Counts the number of adjacent dot ('.') pairs in the character array.
     */
    private static int countAdjacentDotPairs(char[] s) {
        int count = 0;
        for (int i = 0; i + 1 < s.length; i++) {
            if (s[i] == '.' && s[i + 1] == '.') {
                count++;
            }
        }
        return count;
    }

    /**
     * Calculates the change in the dot pair count when modifying a single character.
     * Only pairs involving the modified index are affected.
     */
    private static int calculateDelta(char oldChar, char newChar, int index, char[] s) {
        int delta = 0;
        boolean isDot = newChar == '.';
        boolean wasDot = oldChar == '.';

        if (isDot && !wasDot) {
            // Changing non-dot to dot: potential new pairs
            if (index > 0 && s[index - 1] == '.') delta++;
            if (index < s.length - 1 && s[index + 1] == '.') delta++;
        } else if (!isDot && wasDot) {
            // Changing dot to non-dot: potential broken pairs
            if (index > 0 && s[index - 1] == '.') delta--;
            if (index < s.length - 1 && s[index + 1] == '.') delta--;
        }
        return delta;
    }

    /**
     * Fast input reader for competitive programming environments.
     */
    static class InputReader {
        public BufferedReader reader;
        public StringTokenizer tokenizer;

        public InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }
    }
}

