            int m = scanner.nextInt();
            String initialStr = scanner.next();

            Replacement solver = new Replacement();
            solver.solve(n, m, initialStr, scanner, out);
        } finally {
            out.flush();
        }
    }

    /**
     * Handles the core business logic for calculating and updating adjacent dot pairs.
     */
    static class Replacement {
        /**
         * Solves the problem by computing the initial count of adjacent dot pairs,
         * then processing each update query in O(1) time.
         *
         * @param n          Length of the string
         * @param m          Number of update queries
         * @param initialStr The initial string
         * @param scanner    Input reader
         * @param out        Output writer
         */
        public void solve(int n, int m, String initialStr, FastScanner scanner, PrintWriter out) {
            char[] chars = initialStr.toCharArray();
            int adjacentDotPairs = 0;

            // Calculate initial number of adjacent dot pairs
            for (int i = 1; i < n; i++) {
                if (chars[i] == '.' && chars[i - 1] == '.') {
                    adjacentDotPairs++;
                }
            }

            // Process each update query
            for (int q = 0; q < m; q++) {
                int index = scanner.nextInt() - 1; // Convert to 0-based index
                char replacement = scanner.next().charAt(0);

                // Remove contribution of the old character if it was a dot
                if (chars[index] == '.') {
                    if (index > 0 && chars[index - 1] == '.') {
                        adjacentDotPairs--;
                    }
                    if (index < n - 1 && chars[index + 1] == '.') {
                        adjacentDotPairs--;
                    }
                }

                // Apply the replacement
                chars[index] = replacement;

                // Add contribution of the new character if it is a dot
                if (replacement == '.') {
                    if (index > 0 && chars[index - 1] == '.') {
                        adjacentDotPairs++;
                    }
                    if (index < n - 1 && chars[index + 1] == '.') {
                        adjacentDotPairs++;
                    }
                }

                out.println(adjacentDotPairs);
            }
