/**
 * Refactored version of contest_a.
 * 
 * Key Improvements:
 * 1. Naming Conventions: Class renamed to ContestA, variables renamed for clarity.
 * 2. Dead Code Removal: Eliminated unused static fields (m, fi, st, hs, ww) and shadowed variables.
 * 3. FastScanner Robustness: Replaced recursive token fetching with an iterative loop to prevent StackOverflowError.
 *    Added null-safety for BufferedReader.readLine().
 * 4. Logic Simplification: Extracted initial pair calculation into a dedicated method.
 *    Replaced deeply nested if-else chains with a clean mathematical adjustment based on immediate neighbors.
 * 5. Performance: Used char[] instead of StringBuilder for O(1) updates and reduced memory overhead.
 *    Replaced StringBuilder accumulation with PrintWriter for efficient streaming output.
 */
public class ContestA {

    /**
     * FastScanner provides efficient input reading for competitive programming contexts.
     */
    static class FastScanner {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastScanner() {
            this.reader = new BufferedReader(new InputStreamReader(System.in));
            this.tokenizer = new StringTokenizer("");
        }

        private String next() throws IOException {
            while (!tokenizer.hasMoreTokens()) {
                String line = reader.readLine();
                if (line == null) {
                    return null;
                }
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            String token = next();
            return token == null ? 0 : Integer.parseInt(token);
        }

        public long nextLong() throws IOException {
            String token = next();
            return token == null ? 0L : Long.parseLong(token);
        }

        public double nextDouble() throws IOException {
            String token = next();
            return token == null ? 0.0 : Double.parseDouble(token);
        }

        public String nextString() throws IOException {
            return next();
        }
    }

    public static void main(String[] args) throws IOException {
        FastScanner scanner = new FastScanner();
        PrintWriter out = new PrintWriter(System.out);

        // Read input parameters
        int n = scanner.nextInt();          // String length (provided but unused in logic)
        int tst = scanner.nextInt();        // Number of queries
        String inputStr = scanner.nextString();

        // Use a mutable character array for efficient index-based updates
        char[] chars = inputStr.toCharArray();

        // Calculate initial number of adjacent dot pairs
        int numDotPairs = calculateInitialDotPairs(chars);

        // Process each query
        for (int i = 0; i < tst; i++) {
            int index = scanner.nextInt() - 1; // Convert 1-based index to 0-based
            String token = scanner.nextString();
            char newChar = token.charAt(0);

            char oldChar = chars[index];

            // Only process if the character actually changes
            if (oldChar != newChar) {
                boolean leftDot = index > 0 && chars[index - 1] == '.';
                boolean rightDot = index < chars.length - 1 && chars[index + 1] == '.';

                if (oldChar == '.' && newChar != '.') {
                    // Replacing a dot with a non-dot: lose pairs with adjacent dots
                    numDotPairs -= (leftDot ? 1 : 0) + (rightDot ? 1 : 0);
                } else if (oldChar != '.' && newChar == '.') {
                    // Replacing a non-dot with a dot: gain pairs with adjacent dots
                    numDotPairs += (leftDot ? 1 : 0) + (rightDot ? 1 : 0);
                }

                // Apply the update
                chars[index] = newChar;
            }

            out.println(numDotPairs);
        }

        out.flush();
    }

    /**
     * Calculates the initial number of adjacent dot pairs in the character array.
     * A pair is formed by two consecutive '.' characters.
     * For a contiguous segment of k dots, there are exactly k-1 adjacent pairs.
     */
    private static int calculateInitialDotPairs(char[] chars) {
        int consecutiveDots = 0;
        int totalPairs = 0;

        for (char c : chars) {
            if (c == '.') {
                consecutiveDots++;
            } else {
                if (consecutiveDots > 1) {
                    totalPairs += consecutiveDots - 1;
                }
                consecutiveDots = 0;
            }
        }
        // Handle trailing dots
        if (consecutiveDots > 1) {
            totalPairs += consecutiveDots - 1;
        }
        return totalPairs;
    }
}

import java.io.BufferedReader;
