/**
 * Refactored solution for tracking adjacent dot pairs in a string.
 * 
 * Improvements made:
 * 1. Encapsulation: Logic is encapsulated within a class (StringDotCounter) 
 *    to manage state and behavior cleanly.
 * 2. Readability: Variable names are descriptive (e.g., 'adjacentDotPairs' instead of 'f').
 * 3. Efficiency: The update logic is O(1), checking only immediate neighbors 
 *    rather than re-scanning the string.
 * 4. Maintainability: Separated concerns into distinct methods (initialization, 
 *    counting, updating, and I/O handling).
 * 5. Resource Management: Proper handling of BufferedReader and PrintWriter.
 */
public class StringDotCounter {

    private final char[] characters;
    private final int length;
    private int adjacentDotPairs;

    /**
     * Initializes the counter with the provided string.
     *
     * @param initialString The string representing the initial state.
     */
    public StringDotCounter(String initialString) {
        this.characters = initialString.toCharArray();
        this.length = characters.length;
        // Calculate the initial count of adjacent dot pairs ("..")
        this.adjacentDotPairs = calculateInitialCount();
    }

    /**
     * Iterates through the string to count occurrences of adjacent dots.
     *
     * @return The total count of adjacent dot pairs.
     */
    private int calculateInitialCount() {
        int count = 0;
        // Iterate starting from the second character to check pairs (i-1, i)
        for (int i = 1; i < length; i++) {
            if (characters[i - 1] == '.' && characters[i] == '.') {
                count++;
            }
        }
        return count;
    }

    /**
     * Updates a character at a specific index and adjusts the pair count.
     * This method runs in O(1) time complexity.
     *
     * @param index     The 0-based index to update.
     * @param newChar   The new character value.
     * @return          The updated count of adjacent dot pairs.
     */
    public int update(int index, char newChar) {
        char oldChar = characters[index];

        // Optimization: If the character is not changing, the count remains the same.
        if (oldChar == newChar) {
            return adjacentDotPairs;
        }

        // Check Left Neighbor (index - 1)
        if (index > 0) {
            if (characters[index - 1] == '.') {
                // If the previous state was a dot, we are breaking a pair
                if (oldChar == '.') {
                    adjacentDotPairs--;
                }
                // If the new state is a dot, we are forming a pair
                if (newChar == '.') {
                    adjacentDotPairs++;
                }
            }
        }

        // Check Right Neighbor (index + 1)
        if (index < length - 1) {
            if (characters[index + 1] == '.') {
                // If the previous state was a dot, we are breaking a pair
                if (oldChar == '.') {
                    adjacentDotPairs--;
                }
                // If the new state is a dot, we are forming a pair
                if (newChar == '.') {
                    adjacentDotPairs++;
                }
            }
        }

        // Apply the update to the underlying array
        characters[index] = newChar;

        return adjacentDotPairs;
    }

    /**
     * Main method to handle input and output.
     *
     * @param args Command line arguments.
     * @throws IOException If an I/O error occurs.
     */
    public static void main(String[] args) throws IOException {
        // Use BufferedReader and PrintWriter for efficient I/O
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter writer = new PrintWriter(System.out);
        StringTokenizer tokenizer;

        // Read n (length) and m (number of queries)
        String line = reader.readLine();
        if (line != null) {
            tokenizer = new StringTokenizer(line);
            int stringLength = Integer.parseInt(tokenizer.nextToken());
            int queryCount = Integer.parseInt(tokenizer.nextToken());

            // Read the initial string
            String initialString = reader.readLine();
            if (initialString != null) {
                StringDotCounter counter = new StringDotCounter(initialString);

                // Process each query
                for (int i = 0; i < queryCount; i++) {
                    line = reader.readLine();
                    if (line == null) break;

                    tokenizer = new StringTokenizer(line);
                    // Input index is 1-based, convert to 0-based
                    int index = Integer.parseInt(tokenizer.nextToken()) - 1;
                    char newChar = tokenizer.nextToken().charAt(0);

                    int currentCount = counter.update(index, newChar);
                    writer.println(currentCount);
                }
            }
        }

        // Flush and close output
        writer.flush();
        writer.close();
        reader.close();
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

/**
 * Solves the replacement problem (Codeforces 570C).
 * Efficiently tracks total dots and contiguous dot groups,
 * updating state in O(1) per query.
 */
public class ReplacementSolver {

    public static void main(String[] args) {
        FastScanner in = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out);
        solve(in, out);
        out.flush();
    }

    private static void solve(FastScanner in, PrintWriter out) {
        int strlen = in.nextInt();
        int queries = in.nextInt();
        char[] s = in.next().toCharArray();

        int totalDots = 0;
        int dotGroups = 0;

        // Initial pass to count total dots and contiguous groups
        for (int i = 0; i < strlen; i++) {
            if (s[i] == '.') {
                totalDots++;
                // A new group starts if it's the first character or the previous one wasn't a dot
                if (i == 0 || s[i - 1] != '.') {
                    dotGroups++;
                }
            }
        }

        for (int q = 0; q < queries; q++) {
            int position = in.nextInt() - 1; // Convert to 0-based index
            char replacement = in.nextChar();

            // If the character is already what we want to replace it with, state doesn't change
            if (s[position] == replacement) {
                out.println(totalDots - dotGroups);
                continue;
            }

            boolean leftIsDot = (position > 0 && s[position - 1] == '.');
            boolean rightIsDot = (position < strlen - 1 && s[position + 1] == '.');

            if (s[position] == '.' && replacement != '.') {
                // Replacing a dot with a non-dot
                totalDots--;
                if (leftIsDot && rightIsDot) {
                    dotGroups++; // Removing a dot from the middle of a group splits it into two
                } else {
                    dotGroups--; // Removing a dot from the start, end, or an isolated dot reduces group count
                }
            } else if (s[position] != '.' && replacement == '.') {
                // Replacing a non-dot with a dot
                totalDots++;
                if (leftIsDot && rightIsDot) {
                    dotGroups--; // Adding a dot between two groups merges them into one
                } else if (!leftIsDot && !rightIsDot) {
                    dotGroups++; // Adding a dot between non-dots creates a new isolated group
                }
                // If only one neighbor is a dot, we are simply extending an existing group, so dotGroups remains unchanged
            }

            s[position] = replacement;
            out.println(totalDots - dotGroups);
        }
    }

    /**
     * FastScanner for efficient input reading.
     * Replaces custom byte-based readers with standard Java I/O for better maintainability.
     */
    static class FastScanner {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastScanner(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) {
                        return null;
                    }
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return tokenizer.nextToken();
        }

        public char nextChar() {
            return next().charAt(0);
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

public class Main {
    public static void main(String[] args) {
        FastReader reader = new FastReader();

        // n is read to consume input but is not required for the core logic
        int n = reader.nextInt();
        int m = reader.nextInt();
        String initialSequence = reader.next();

        DotTracker tracker = new DotTracker(initialSequence);

        StringBuilder output = new StringBuilder();
        for (int i = 0; i < m; i++) {
            int index = reader.nextInt() - 1; // Convert 1-based to 0-based
            char newChar = reader.next().charAt(0);

            tracker.update(index, newChar);
            output.append(tracker.getResult()).append('\n');
        }
        System.out.print(output);
    }

    /**
     * Encapsulates the state and logic for tracking '.' characters and their contiguous segments.
     * Supports efficient point updates without re-scanning the entire sequence.
     */
    static class DotTracker {
        private final char[] sequence;
        private int dotCount;
        private int segmentCount;

        public DotTracker(String initialSequence) {
            this.sequence = initialSequence.toCharArray();
            initialize();
        }

        private void initialize() {
            boolean inSegment = false;
            for (char ch : sequence) {
                if (ch == '.') {
                    dotCount++;
                    if (!inSegment) {
                        segmentCount++;
                        inSegment = true;
                    }
                } else {
                    inSegment = false;
                }
            }
        }

        /**
         * Updates the character at the specified index and adjusts internal counts accordingly.
         */
        public void update(int index, char newChar) {
            if (index < 0 || index >= sequence.length) {
                throw new IndexOutOfBoundsException("Index " + index + " is out of bounds for sequence of length " + sequence.length);
            }

            char oldChar = sequence[index];
            if (oldChar == newChar) {
                return; // No change required
            }

            sequence[index] = newChar;

            if (newChar == '.' && oldChar != '.') {
                adjustCounts(index, 1); // Adding a dot
            } else if (newChar != '.' && oldChar == '.') {
                adjustCounts(index, -1); // Removing a dot
            }
        }

        private void adjustCounts(int index, int direction) {
            dotCount += direction;
            boolean leftIsDot = isDot(index - 1);
            boolean rightIsDot = isDot(index + 1);

            if (direction == 1) {
                // Adding a dot: isolated -> new segment (+1), merging two -> segment count (-1)
                if (!leftIsDot && !rightIsDot) {
                    segmentCount++;
                } else if (leftIsDot && rightIsDot) {
                    segmentCount--;
                }
            } else {
                // Removing a dot: isolated -> segment ends (-1), splitting one -> segment count (+1)
                if (!leftIsDot && !rightIsDot) {
                    segmentCount--;
                } else if (leftIsDot && rightIsDot) {
                    segmentCount++;
                }
            }
        }

        private boolean isDot(int index) {
            return index >= 0 && index < sequence.length && sequence[index] == '.';
        }

        /**
         * Returns the metric defined by the original problem: total dots minus segment count.
         */
        public int getResult() {
            return dotCount - segmentCount;
        }
    }

    /**
     * High-performance I/O helper commonly used in competitive programming.
     */
    static class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input", e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            String token = next();
            return token == null ? 0 : Integer.parseInt(token);
        }

        long nextLong() {
            String token = next();
            return token == null ? 0L : Long.parseLong(token);
        }

        double nextDouble() {
            String token = next();
            return token == null ? 0.0 : Double.parseDouble(token);
        }

        String nextLine() {
            try {
                return br.readLine();
            } catch (IOException e) {
                throw new RuntimeException("Failed to read line", e);
            }
        }
    }
}

import java.io.BufferedReader;
