import java.io.InputStreamReader;
import java.util.HashSet;
import java.util.Set;
import java.util.StringTokenizer;

/**
 * Tracks the number of adjacent dot pairs in a 1D grid.
 * Supports point updates (placing/removing dots) and returns the current count after each operation.
 */
public class ConsecutiveDotsCounter {

    public static void main(String[] args) throws IOException {
        FastReader reader = new FastReader();

        // Read grid dimensions and number of queries
        String nStr = reader.next();
        if (nStr == null) return; // Handle empty input gracefully

        int n = Integer.parseInt(nStr);
        int m = reader.nextInt();

        // Read the initial grid configuration
        String row = reader.next();
        char[] grid = row.toCharArray();

        int adjacentPairs = 0;
        Set<Integer> dotPositions = new HashSet<>();

        // Initialize state based on the initial configuration
        if (grid[0] == '.') {
            dotPositions.add(1); // Use 1-based indexing for consistency with queries
        }
        for (int i = 1; i < n; i++) {
            if (grid[i] == '.' && grid[i - 1] == '.') {
                adjacentPairs++;
            }
            if (grid[i] == '.') {
                dotPositions.add(i + 1);
            }
        }

        StringBuilder results = new StringBuilder();
        for (int q = 0; q < m; q++) {
            int x = reader.nextInt();
            String typeStr = reader.next();
            char type = typeStr.charAt(0);

            if (type == '.') {
                // Attempt to place a dot at position x
                if (!dotPositions.contains(x)) {
                    if (dotPositions.contains(x - 1)) adjacentPairs++;
                    if (dotPositions.contains(x + 1)) adjacentPairs++;
                    dotPositions.add(x);
                }
            } else {
                // Attempt to remove a dot at position x
                if (dotPositions.contains(x)) {
                    if (dotPositions.contains(x - 1)) adjacentPairs--;
                    if (dotPositions.contains(x + 1)) adjacentPairs--;
                    dotPositions.remove(x);
                }
            }
            results.append(adjacentPairs).append('\n');
        }

        System.out.print(results);
    }

    /**
     * Helper class for fast and robust input reading.
     * Handles whitespace, newlines, and potential empty lines automatically.
     */
    static class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input", e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            String token = next();
            return token == null ? 0 : Integer.parseInt(token);
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

/**
 * Refactored version of the original Major class.
 * 
 * Refactoring Improvements:
 * 1.  **Naming Conventions**: Renamed class and variables to be descriptive (e.g., `grid`, `length`, `adjacentDotPairs`).
 * 2.  **Separation of Concerns**: Extracted logic into helper methods (`calculateInitialConnections` and `updateGridAndCount`) to reduce complexity in `main`.
 * 3.  **DRY Principle**: Eliminated massive nested `if-else` blocks by abstracting the neighbor-checking logic.
 * 4.  **Data Structures**: Used `char[]` for mutable string manipulation instead of `StringBuilder` or `String` concatenation, which is more efficient for character updates.
 * 5.  **Robustness**: Added null checks for input reading and used specific `IOException` instead of generic `Exception`.
 * 6.  **Readability**: Reduced code indentation and clarified the logic for adding/removing dots.
 */
public class DotGridSolver {

    public static void main(String[] args) throws IOException {
        // Initialize fast I/O
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));

        // Read dimensions: n (length of string), m (number of queries)
        String line = br.readLine();
        if (line == null) return;

        StringTokenizer st = new StringTokenizer(line);
        if (!st.hasMoreTokens()) return;

        int length = Integer.parseInt(st.nextToken());
        int numQueries = Integer.parseInt(st.nextToken());

        // Read the initial grid string
        String gridStr = br.readLine();
        if (gridStr == null) return;
        char[] grid = gridStr.toCharArray();

        // Calculate initial number of adjacent dot pairs (connections)
        int adjacentDotPairs = calculateInitialConnections(grid);

        StringBuilder output = new StringBuilder();

        // Process each query
        for (int i = 0; i < numQueries; i++) {
            line = br.readLine();
            if (line == null) break;

            st = new StringTokenizer(line);
            if (!st.hasMoreTokens()) continue;

            // Input index is 1-based, convert to 0-based
            int index = Integer.parseInt(st.nextToken()) - 1; 
            char newChar = st.nextToken().charAt(0);

            // Update grid and get new connection count
            adjacentDotPairs = updateGridAndCount(grid, index, newChar, adjacentDotPairs, length);

            output.append(adjacentDotPairs).append('\n');
        }

        System.out.print(output);
    }

    /**
     * Calculates the initial number of adjacent dot pairs (connections).
     * A connection exists between two indices i and i+1 if both are '.'.
     * For a contiguous run of dots of length L, there are L-1 connections.
     */
    private static int calculateInitialConnections(char[] grid) {
        int connections = 0;
        int runLength = 0;

        for (char c : grid) {
            if (c == '.') {
                runLength++;
            } else {
                if (runLength > 0) {
                    // A run of length L has L-1 connections
                    connections += runLength - 1;
                }
                runLength = 0;
            }
        }
        // Handle a run of dots ending at the last character
        if (runLength > 0) {
            connections += runLength - 1;
        }
        return connections;
    }

    /**
     * Updates the grid at the specified index and recalculates the connection count.
     * 
     * Logic:
     * - If placing a dot ('.'): Check neighbors. If a neighbor is '.', increment count.
     * - If removing a dot (placing non-dot): Check neighbors. If a neighbor is '.', decrement count.
     * - If the character doesn't change, count remains same.
     */
    private static int updateGridAndCount(char[] grid, int index, char newChar, int currentConnections, int length) {
        char oldChar = grid[index];

        // If the character is already what we want to set, no change in connections
        if (oldChar == newChar) {
            return currentConnections;
        }

        // If we are placing a dot
        if (newChar == '.') {
            // Check left neighbor
            if (index > 0 && grid[index - 1] == '.') {
                currentConnections++;
            }
            // Check right neighbor
            if (index < length - 1 && grid[index + 1] == '.') {
                currentConnections++;
            }
        } 
        // If we are removing a dot (replacing with a non-dot character)
        else {
            // Check left neighbor
            if (index > 0 && grid[index - 1] == '.') {
                currentConnections--;
            }
            // Check right neighbor
            if (index < length - 1 && grid[index + 1] == '.') {
                currentConnections--;
            }
        }

        // Apply the update to the grid
        grid[index] = newChar;

        return currentConnections;
    }
}

