        String inputString = br.readLine();
        if (inputString == null) return;
        char[] text = inputString.toCharArray();

        // Calculate initial score.
        // The metric being tracked is the number of adjacent pairs of dots ('..').
        // Original logic: sum of (count - 1) for consecutive dot segments.
        // This is mathematically equivalent to counting indices i where text[i] == '.' and text[i+1] == '.'.
        int dotPairsCount = 0;
        for (int i = 0; i < length - 1; i++) {
            if (text[i] == '.' && text[i + 1] == '.') {
                dotPairsCount++;
            }
        }

        StringBuilder output = new StringBuilder();

        // Process queries
        for (int k = 0; k < queryCount; k++) {
            line = br.readLine();
