            // Convert 1-based index from input to 0-based index for array access
            int queryIndex = Integer.parseInt(tokenizer.nextToken()) - 1;
            char replacementChar = tokenizer.nextToken().charAt(0);

            char currentChar = text[queryIndex];

            // Only process logic if the character is actually changing
            if (currentChar != replacementChar) {
                // 1. Remove contribution of the old character if it was a dot
                if (currentChar == '.') {
                    // Check left neighbor
                    if (queryIndex > 0 && text[queryIndex - 1] == '.') {
                        dotPairsCount--;
                    }
                    // Check right neighbor
                    if (queryIndex < length - 1 && text[queryIndex + 1] == '.') {
                        dotPairsCount--;
                    }
                }

                // 2. Update the character in the array
                text[queryIndex] = replacementChar;

                // 3. Add contribution of the new character if it is a dot
                if (replacementChar == '.') {
                    // Check left neighbor
                    if (queryIndex > 0 && text[queryIndex - 1] == '.') {
                        dotPairsCount++;
                    }
                    // Check right neighbor
                    if (queryIndex < length - 1 && text[queryIndex + 1] == '.') {
                        dotPairsCount++;
                    }
                }
            }

            output.append(dotPairsCount).append('\n');
