import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

/**
 * Refactored solution for tracking contiguous segments of '.' characters.
 * 
 * Changes made:
 * 1. Removed all dead code (Union-Find, BFS, unused classes/imports).
 * 2. Unified I/O to use BufferedReader and PrintWriter consistently.
 * 3. Replaced convoluted and potentially buggy counting logic with a clear, 
 *    standard algorithm for counting contiguous segments.
 * 4. Extracted business logic into well-named, single-responsibility methods.
 * 5. Improved variable naming and added JavaDoc for clarity.
 */
public class Main {

    public static void main(String[] args) throws IOException {
        // Efficient and consistent I/O handling
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter out = new PrintWriter(System.out);

        StringTokenizer st = new StringTokenizer(br.readLine());
        int n = Integer.parseInt(st.nextToken());
        int m = Integer.parseInt(st.nextToken());

        char[] sequence = br.readLine().toCharArray();
        int segmentCount = countSegments(sequence, n);

        for (int i = 0; i < m; i++) {
            String line = br.readLine();
            while (line != null && line.trim().isEmpty()) {
                line = br.readLine();
            }
            if (line == null) break;

            st = new StringTokenizer(line);
            int index = Integer.parseInt(st.nextToken()) - 1; // Convert to 0-based index
            char newChar = st.nextToken().charAt(0);

            // Only update if the character actually changes
            if (sequence[index] != newChar) {
                segmentCount = updateSequence(sequence, index, newChar, n, segmentCount);
                sequence[index] = newChar;
            }
            out.println(segmentCount);
        }

        out.flush();
        out.close();
        br.close();
    }

    /**
     * Counts the number of contiguous segments of '.' in the character array.
     * A segment is defined as one or more consecutive '.' characters.
     */
    private static int countSegments(char[] arr, int n) {
        if (n == 0) return 0;

        int count = 0;
        boolean inSegment = false;

        for (int i = 0; i < n; i++) {
            if (arr[i] == '.') {
                if (!inSegment) {
                    count++;
                    inSegment = true;
                }
            } else {
                inSegment = false;
            }
        }
        return count;
    }

    /**
     * Updates the sequence at the given index and adjusts the segment count accordingly.
     * Handles both insertion and removal of '.' characters efficiently.
     */
    private static int updateSequence(char[] arr, int idx, char newChar, int n, int currentCount) {
        char oldChar = arr[idx];
        if (oldChar == newChar) return currentCount;

        boolean leftNeighborIsDot = (idx > 0 && arr[idx - 1] == '.');
        boolean rightNeighborIsDot = (idx < n - 1 && arr[idx + 1] == '.');

        if (oldChar == '.' && newChar != '.') {
            // Case: Removing a '.'
            if (leftNeighborIsDot && rightNeighborIsDot) {
                // The '.' was sandwiched between two '.'s. The segment remains connected.
                // Segment count does not change.
                return currentCount;
            } else if (leftNeighborIsDot || rightNeighborIsDot) {
                // The '.' was at the boundary of a segment. Removing it shortens the segment.
                // Segment count decreases by 1.
                return currentCount - 1;
            } else {
                // The '.' was isolated. Removing it eliminates a segment.
                return currentCount - 1;
            }
        } else if (oldChar != '.' && newChar == '.') {
            // Case: Adding a '.'
            if (leftNeighborIsDot && rightNeighborIsDot) {
                // The new '.' bridges two separate segments, merging them into one.
                return currentCount - 1;
            } else if (leftNeighborIsDot || rightNeighborIsDot) {
                // The new '.' extends an existing segment without merging separate ones.
                return currentCount;
            } else {
                // The new '.' forms a completely new isolated segment.
                return currentCount + 1;
            }
        }

        return currentCount;
    }
}

