class InputReader {
    private InputStream inputStream;
    private byte[] buffer = new byte[8192];
    private int currentCharIndex;
    private int numCharsRead;
    private SpaceCharFilter spaceCharFilter;

    public InputReader(InputStream inputStream) {
        this.inputStream = inputStream;
    }

    private int readNextChar() {
        if (numCharsRead == -1) {
            throw new InputMismatchException();
        }
        if (currentCharIndex >= numCharsRead) {
            currentCharIndex = 0;
            try {
                numCharsRead = inputStream.read(buffer);
            } catch (IOException e) {
                throw new InputMismatchException();
            }
            if (numCharsRead <= 0) {
                return -1;
            }
        }
        return buffer[currentCharIndex++];
    }

    public int nextInt() {
        int c = readNextChar();
        while (isSpaceChar(c)) {
            c = readNextChar();
        }
        int sign = 1;
        if (c == '-') {
            sign = -1;
            c = readNextChar();
        }
        int result = 0;
        do {
            if (c < '0' || c > '9') {
                throw new InputMismatchException();
            }
            result *= 10;
            result += c - '0';
            c = readNextChar();
        } while (!isSpaceChar(c));
        return result * sign;
    }

    public long nextLong() {
        int c = readNextChar();
        while (isSpaceChar(c)) {
            c = readNextChar();
        }
        int sign = 1;
        if (c == '-') {
            sign = -1;
            c = readNextChar();
        }
        long result = 0;
        do {
            if (c < '0' || c > '9') {
                throw new InputMismatchException();
            }
            result *= 10;
            result += c - '0';
            c = readNextChar();
        } while (!isSpaceChar(c));
        return result * sign;
    }

    public int[] nextIntArray(int n) {
        int[] array = new int[n + 1];
        for (int i = 1; i <= n; i++) {
            array[i] = nextInt();
        }
        return array;
    }

    public String readString() {
        int c = readNextChar();
        while (isSpaceChar(c)) {
            c = readNextChar();
        }
        StringBuilder result = new StringBuilder();
        do {
            result.appendCodePoint(c);
            c = readNextChar();
        } while (!isSpaceChar(c));
        return result.toString();
    }

    public boolean isSpaceChar(int c) {
        if (spaceCharFilter != null) {
            return spaceCharFilter.isSpaceChar(c);
        }
        return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
    }

    public interface SpaceCharFilter {
        boolean isSpaceChar(int ch);
    }
}

