public class Main {
    public static void main(String[] args) throws IOException {
        // Initialize BufferedReader for efficient input handling
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));

        // Read n (string length) and m (number of queries)
        String line = br.readLine();
        if (line == null) return;

        StringTokenizer st = new StringTokenizer(line);
        int n = Integer.parseInt(st.nextToken());
        int m = Integer.parseInt(st.nextToken());

        // Read the initial string
        String strLine = br.readLine();
        if (strLine == null) return;
        char[] str = strLine.trim().toCharArray();

        // Calculate the initial count based on the specific logic
        int count = calculateInitialCount(str, n);

        // Process each query
        for (int k = 0; k < m; k++) {
            line = br.readLine();
            if (line == null) break;

            st = new StringTokenizer(line);
            int index = Integer.parseInt(st.nextToken()) - 1; // Convert to 0-based index
            String charToken = st.nextToken().trim();
            char ch = charToken.charAt(0);

            // Update the count and the character array
            count = updateCount(str, n, index, ch, count);

            // Output the current count
            System.out.println(count);
        }
    }

    /**
     * Calculates the initial count based on the original algorithm's logic.
     * This method preserves the specific counting rules of the original implementation.
     */
    private static int calculateInitialCount(char[] str, int n) {
        int count = 0;
        int begin = 0;
        boolean started = false;

        for (int i = 0; i < n; i++) {
            if (!started && str[i] == '.') {
                started = true;
                begin = i;
            } else if (started && str[i] != '.') {
                started = false;
                count += i - begin - 1;
            } else if (started && i == n - 1) {
                count += i - begin;
            }
        }
        return count;
    }

    /**
     * Updates the count and the character array when a character is modified.
     * 
     * Refactored Logic:
     * The original code used complex nested if-statements to check neighbors.
     * This logic is mathematically equivalent to:
     * 1. If changing '.' to a character: Decrease count by the number of adjacent '.' neighbors.
     * 2. If changing a character to '.': Increase count by the number of adjacent '.' neighbors.
     */
    private static int updateCount(char[] str, int n, int index, char ch, int currentCount) {
        // Optimization: If the character is not changing, return current count
        if (str[index] == ch) {
            return currentCount;
        }

        int dotNeighbors = 0;

        // Check left neighbor
        if (index > 0 && str[index - 1] == '.') {
            dotNeighbors++;
        }

        // Check right neighbor
        if (index < n - 1 && str[index + 1] == '.') {
            dotNeighbors++;
        }

        if (ch != '.') {
            // Changing '.' to a character
            // Original logic: decrements count for each adjacent '.'
            currentCount -= dotNeighbors;
        } else {
            // Changing a character to '.'
            // Original logic: increments count for each adjacent '.'
            currentCount += dotNeighbors;
        }

        // Update the array
        str[index] = ch;

        return currentCount;
    }
}

import java.io.BufferedReader;
import java.io.BufferedOutputStream;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;
import java.util.TreeMap;

public class Main {

    /**
     * FastReader class for efficient input reading.
     */
    public static class FastReader {
        private final BufferedReader br;
        private StringTokenizer tokenizer;

        public FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        /**
         * Reads the next token from input.
         * @return the next token string
         */
        String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) {
                        return null;
                    }
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        int nextInt() {
            String s = next();
            if (s == null) throw new RuntimeException("Unexpected end of input");
            return Integer.parseInt(s);
        }
    }

    public static void main(String[] args) {
        FastReader sc = new FastReader();
        PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out));

        try {
            solve(sc, out);
        } finally {
            out.flush();
            out.close();
        }
    }

    private static void solve(FastReader sc, PrintWriter out) {
        // Read N (length of string) and M (number of queries)
        int n = sc.nextInt();
        int m = sc.nextInt();

        // Read string S
        String sStr = sc.next();
        if (sStr == null) return;
        char[] s = sStr.toCharArray();

        // Map to store intervals of contiguous dots: Key = Start Index, Value = End Index
        // Using TreeMap allows efficient floor/ceiling key lookups for neighbors
        TreeMap<Integer, Integer> intervals = new TreeMap<>();
        int totalLength = 0;

        // Initialize intervals from the initial string state
        int i = 0;
        while (i < s.length) {
            if (s[i] == '.') {
                int start = i;
                while (i < s.length && s[i] == '.') {
                    i++;
                }
                int end = i - 1;
                intervals.put(start, end);
                // Length is inclusive: end - start + 1
                totalLength += (end - start + 1);
            } else {
                i++;
            }
        }

        // Process queries
        for (int k = 0; k < m; k++) {
            int pos = sc.nextInt() - 1; // Convert 1-based index to 0-based
            String charStr = sc.next();
            if (charStr == null) break;
            char c = charStr.charAt(0);

            if (c == '.') {
                // Attempting to place a dot
                if (s[pos] != '.') {
                    // Check for adjacent intervals
                    Integer leftIntervalStart = intervals.floorKey(pos - 1);
                    Integer rightIntervalStart = intervals.ceilingKey(pos + 1);

                    boolean merged = false;

                    // Case 1: Merge Left and Right intervals
                    if (leftIntervalStart != null && rightIntervalStart != null) {
                        int leftEnd = intervals.get(leftIntervalStart);
                        // Check if they are exactly adjacent to pos
                        if (leftEnd == pos - 1 && rightIntervalStart == pos + 1) {
                            int rightEnd = intervals.get(rightIntervalStart);

                            // Update total length: remove old segments, add merged segment
                            totalLength -= (leftEnd - leftIntervalStart + 1);
                            totalLength -= (rightEnd - rightIntervalStart + 1);
                            totalLength += (rightEnd - leftIntervalStart + 1);

                            // Update map
                            intervals.remove(leftIntervalStart);
                            intervals.remove(rightIntervalStart);
                            intervals.put(leftIntervalStart, rightEnd);
                            merged = true;
                        }
                    }

                    if (!merged) {
                        // Case 2: Extend Left interval
                        if (leftIntervalStart != null && intervals.get(leftIntervalStart) == pos - 1) {
                            totalLength++;
                            intervals.put(leftIntervalStart, pos);
                            merged = true;
                        }
                        // Case 3: Extend Right interval
                        else if (rightIntervalStart != null && rightIntervalStart == pos + 1) {
                            int oldEnd = intervals.get(rightIntervalStart);
                            totalLength++;
                            intervals.remove(rightIntervalStart);
                            intervals.put(pos, oldEnd);
                            merged = true;
                        }
                    }

                    if (!merged) {
                        // Case 4: Create new isolated dot segment
                        intervals.put(pos, pos);
                        totalLength++;
                    }
                }
            } else {
                // Attempting to remove a dot (set to non-dot)
                if (s[pos] == '.') {
                    // Find the interval containing pos
                    Integer start = intervals.floorKey(pos);
                    // pos must be within [start, end]
                    int end = intervals.get(start);

                    // Remove the full segment length
                    totalLength -= (end - start + 1);
                    intervals.remove(start);

                    // Add back left part if valid
                    if (start <= pos - 1) {
                        int leftEnd = pos - 1;
                        totalLength += (leftEnd - start + 1);
                        intervals.put(start, leftEnd);
                    }

                    // Add back right part if valid
                    if (pos + 1 <= end) {
                        int rightStart = pos + 1;
                        totalLength += (end - rightStart + 1);
                        intervals.put(rightStart, end);
                    }
                }
            }

            // Update the string state
            s[pos] = c;

            // Output current answer
            out.println(totalLength);
        }
    }
}

import java.io.BufferedReader;
