import java.io.InputStreamReader;
import java.util.StringTokenizer;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());

        int n = Integer.parseInt(st.nextToken());
        int m = Integer.parseInt(st.nextToken());
        char[] chars = br.readLine().toCharArray();

        // Optimization for n=1: count - segcount is always 0
        if (n == 1) {
            StringBuilder sb = new StringBuilder();
            for (int i = 0; i < m; i++) {
                br.readLine(); // Consume query input
                sb.append("0\n");
            }
            System.out.print(sb);
            return;
        }

        // Initialize dot count and contiguous dot segment count
        int[] counts = calculateInitialCounts(chars);
        StringBuilder sb = new StringBuilder();

        for (int i = 0; i < m; i++) {
            st = new StringTokenizer(br.readLine());
            int index = Integer.parseInt(st.nextToken()) - 1; // Convert to 0-based index
            char newChar = st.nextToken().charAt(0);

            // Apply update and maintain counts in O(1)
            updateCounts(chars, index, newChar, counts);

            sb.append(counts[0] - counts[1]).append('\n');
        }
        System.out.print(sb);
    }

    /**
     * Calculates the initial number of '.' characters and contiguous '.' segments.
     * 
     * @param chars The character array representing the string
     * @return int array where [0] = dotCount, [1] = dotSegmentCount
     */
    private static int[] calculateInitialCounts(char[] chars) {
        int dotCount = 0;
        int dotSegmentCount = 0;
        int consecutiveDots = 0;

        for (char c : chars) {
            if (c == '.') {
                dotCount++;
                consecutiveDots++;
            } else {
                if (consecutiveDots > 0) {
                    dotSegmentCount++;
                    consecutiveDots = 0;
                }
            }
        }
        // Handle segment at the end of the array
        if (consecutiveDots > 0) {
            dotSegmentCount++;
        }
        return new int[]{dotCount, dotSegmentCount};
    }

    /**
     * Updates the character array and adjusts dot count/segment count based on the change.
     * Operates in O(1) time by only examining neighbors.
     * 
     * @param chars The character array
     * @param index The position to update
     * @param newChar The new character to place
     * @param counts Mutable array holding [dotCount, dotSegmentCount]
     */
    private static void updateCounts(char[] chars, int index, char newChar, int[] counts) {
        int dotCount = counts[0];
        int dotSegmentCount = counts[1];
        char oldChar = chars[index];

        // No change needed if character remains the same
        if (oldChar == newChar) {
            return;
        }

        if (newChar == '.') {
            dotCount++;
            // Update segment count based on neighbors
            if (index == 0) {
                if (chars[1] != '.') dotSegmentCount++;
            } else if (index == chars.length - 1) {
                if (chars[index - 1] != '.') dotSegmentCount++;
            } else {
                if (chars[index - 1] == '.' && chars[index + 1] == '.') {
                    dotSegmentCount--; // Merging two segments
                } else if (chars[index - 1] != '.' && chars[index + 1] != '.') {
                    dotSegmentCount++; // Creating a new segment
                }
                // Mixed neighbors: extending an existing segment (no change)
            }
        } else {
            dotCount--;
            // Update segment count based on neighbors
            if (index == 0) {
                if (chars[1] != '.') dotSegmentCount--;
            } else if (index == chars.length - 1) {
                if (chars[index - 1] != '.') dotSegmentCount--;
            } else {
                if (chars[index - 1] == '.' && chars[index + 1] == '.') {
                    dotSegmentCount++; // Splitting a segment
                } else if (chars[index - 1] != '.' && chars[index + 1] != '.') {
                    dotSegmentCount--; // Removing an isolated segment
                }
                // Mixed neighbors: shortening an existing segment (no change)
            }
        }

        // Apply changes
        chars[index] = newChar;
        counts[0] = dotCount;
        counts[1] = dotSegmentCount;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.NoSuchElementException;
import java.util.StringTokenizer;

/**
 * Solves a problem tracking the number of '.' characters and contiguous groups of '.'
 * under point-update queries.
 */
public class C {

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner();
        PrintWriter out = new PrintWriter(System.out);

        // Read input dimensions and initial string
        int stringLength = scanner.nextInt();
        int queryCount = scanner.nextInt();
        String inputString = scanner.next();

        // Use 1-based indexing for the boolean array to safely handle boundary checks
        // for left (index-1) and right (index+1) neighbors.
        boolean[] isDot = new boolean[stringLength + 2];
        int dotCount = 0;
        int dotGroupCount = 0;

        // Initialize counts based on the initial string
        for (int i = 0; i < stringLength; i++) {
            if (inputString.charAt(i) == '.') {
                dotCount++;
                // A new group starts if it's the first character or the previous wasn't a dot
                if (i == 0 || inputString.charAt(i - 1) != '.') {
                    dotGroupCount++;
                }
                isDot[i + 1] = true;
            }
        }

        // Process each query
        for (int i = 0; i < queryCount; i++) {
            int queryIndex = scanner.nextInt();
            char newChar = scanner.next().charAt(0);
            boolean wasDot = isDot[queryIndex];
            boolean isNowDot = (newChar == '.');

            // Only update counts if the character actually changes
            if (wasDot != isNowDot) {
                if (wasDot) {
                    // Removing a dot
                    dotCount--;
                    if (isDot[queryIndex - 1] && isDot[queryIndex + 1]) {
                        dotGroupCount++; // Split an existing group
                    } else if (!isDot[queryIndex - 1] && !isDot[queryIndex + 1]) {
                        dotGroupCount--; // Removed an isolated dot
                    }
                } else {
                    // Adding a dot
                    dotCount++;
                    if (isDot[queryIndex - 1] && isDot[queryIndex + 1]) {
                        dotGroupCount--; // Merge two adjacent groups
                    } else if (!isDot[queryIndex - 1] && !isDot[queryIndex + 1]) {
                        dotGroupCount++; // Created a new isolated dot
                    }
                }
                isDot[queryIndex] = isNowDot;
            }

            out.println(dotCount - dotGroupCount);
        }

        out.flush();
        out.close();
    }

    /**
     * A fast input reader for competitive programming and performance-critical applications.
     * Replaces the original implementation with a robust, standard-compliant version.
     */
    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        public String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) {
                        throw new NoSuchElementException("End of input reached");
                    }
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input", e);
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }

        public double nextDouble() {
            return Double.parseDouble(next());
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.NoSuchElementException;
import java.util.StringTokenizer;

/**
 * Solves a problem that tracks the number of adjacent '.' pairs in a string
 * under point update operations.
 * 
 * Refactoring highlights:
 * - Replaced custom byte-level Reader with standard BufferedReader/StringTokenizer for readability.
 * - Extracted repeated neighbor-checking logic into a dedicated helper method.
 * - Simplified initial pair counting with a clear O(n) loop.
 * - Removed unused imports and debug utilities to reduce noise.
 * - Added JavaDoc and meaningful variable names for long-term maintainability.
 */
public class Solution {

    private static final BufferedReader IN = new BufferedReader(new InputStreamReader(System.in));
    private static final PrintWriter OUT = new PrintWriter(System.out);
    private static final FastScanner SCANNER = new FastScanner();

    public static void main(String[] args) {
        final boolean DEBUG = args.length > 0;
        long start = System.currentTimeMillis();

        try {
            solve();
        } finally {
            OUT.flush();
        }

        if (DEBUG) {
            long end = System.currentTimeMillis();
            System.err.println("Execution time: " + (end - start) + "ms");
        }
    }

    private static void solve() {
        int n = SCANNER.nextInt();
        int m = SCANNER.nextInt();
        char[] s = SCANNER.next().toCharArray();

        // Count initial number of adjacent '.' pairs
        int ans = 0;
        for (int i = 0; i < n - 1; i++) {
            if (s[i] == '.' && s[i + 1] == '.') {
                ans++;
            }
        }

        // Process m update queries
        for (int i = 0; i < m; i++) {
            int p = SCANNER.nextInt() - 1; // Convert to 0-based index
            char c = SCANNER.next().charAt(0);

            if (c == '.') {
                // Changing a non-'.' to '.' creates new adjacent pairs
                if (s[p] != '.') {
                    ans += countAdjacentDotNeighbors(s, p, n);
                }
            } else {
                // Changing a '.' to something else removes existing adjacent pairs
                if (s[p] == '.') {
                    ans -= countAdjacentDotNeighbors(s, p, n);
                }
            }

            s[p] = c;
            OUT.println(ans);
        }
    }

    /**
     * Counts how many immediate left/right neighbors of index p are '.'
     */
    private static int countAdjacentDotNeighbors(char[] s, int p, int n) {
        int count = 0;
        if (p > 0 && s[p - 1] == '.') {
            count++;
        }
        if (p < n - 1 && s[p + 1] == '.') {
            count++;
        }
        return count;
    }

    /**
     * FastScanner provides maintainable, standard Java I/O for competitive programming.
     * Replaces complex byte-buffer parsing with BufferedReader and StringTokenizer.
     */
    static class FastScanner {
        private StringTokenizer st;

        public FastScanner() {
            st = null;
        }

        public String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = IN.readLine();
                    if (line == null) {
                        throw new NoSuchElementException();
                    }
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input", e);
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

public class Replacement {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());

        int size = Integer.parseInt(st.nextToken());
        int queryCount = Integer.parseInt(st.nextToken());

        String initialString = br.readLine();
        char[] characters = new char[size];
        for (int i = 0; i < size; i++) {
            characters[i] = initialString.charAt(i);
        }

        // Count initial adjacent '.' pairs
        int adjacentDotsPairs = 0;
        for (int i = 0; i < size - 1; i++) {
            if (characters[i] == '.' && characters[i + 1] == '.') {
                adjacentDotsPairs++;
            }
        }

        StringBuilder output = new StringBuilder();
        for (int q = 0; q < queryCount; q++) {
            String line = br.readLine();
            if (line == null) break;
            st = new StringTokenizer(line);

            int index = Integer.parseInt(st.nextToken()) - 1; // Convert 1-based to 0-based
            char newChar = st.nextToken().charAt(0);

            if (size == 1) {
                output.append("0\n");
                continue;
            }

            // Calculate contribution of affected pairs before the update
            int pairsBefore = 0;
            if (index > 0 && characters[index - 1] == '.' && characters[index] == '.') {
                pairsBefore++;
            }
            if (index < size - 1 && characters[index] == '.' && characters[index + 1] == '.') {
                pairsBefore++;
            }

            // Apply the update
            characters[index] = newChar;

            // Calculate contribution of affected pairs after the update
            int pairsAfter = 0;
            if (index > 0 && characters[index - 1] == '.' && characters[index] == '.') {
                pairsAfter++;
            }
            if (index < size - 1 && characters[index] == '.' && characters[index + 1] == '.') {
                pairsAfter++;
            }

            // Update total count efficiently in O(1)
            adjacentDotsPairs += pairsAfter - pairsBefore;
            output.append(adjacentDotsPairs).append('\n');
        }

        System.out.print(output);
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

/**
 * Refactored Solution class for improved maintainability and code quality.
 * 
 * Key Improvements:
 * 1. Naming Conventions: Renamed class to 'Solution' and variables to descriptive names (e.g., 'grid', 'dotPairCount').
 * 2. Structure: Encapsulated Fast I/O logic into a static inner class 'FastReader' to keep main method clean.
 * 3. Logic Simplification: Replaced complex nested conditionals with a symmetric neighbor-checking approach.
 * 4. Edge Case Handling: Removed explicit 'n=1' special case block; the generalized logic handles it naturally.
 * 5. Readability: Added comments and consistent indentation.
 */
public class Solution {

    // Fast I/O helper class to handle input efficiently
    static class FastReader {
        BufferedReader br;
        StringTokenizer st;

        public FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }
    }

    public static void main(String[] args) {
        FastReader sc = new FastReader();
        PrintWriter out = new PrintWriter(System.out);

        // Read n (length of string) and m (number of queries)
        String nStr = sc.next();
        if (nStr == null) {
            out.flush();
            return;
        }
        int n = Integer.parseInt(nStr);
        int m = sc.nextInt();

        // Read initial string and convert to char array for mutability
        String s = sc.next();
        char[] grid = s.toCharArray();

        // Calculate initial count of adjacent dot pairs ("..")
        long dotPairCount = 0;
        for (int i = 0; i < n - 1; i++) {
            if (grid[i] == '.' && grid[i + 1] == '.') {
                dotPairCount++;
            }
        }

        // Process each query
        for (int i = 0; i < m; i++) {
            int x = sc.nextInt(); // 1-based index from input
            String valStr = sc.next();
            char newChar = valStr.charAt(0);

            int index = x - 1; // Convert to 0-based index
            char oldChar = grid[index];

            // Only process if the character actually changes
            if (oldChar != newChar) {

                // Check Left Neighbor (index - 1)
                // If the neighbor is a dot, the pair status depends on the current character
                if (index > 0 && grid[index - 1] == '.') {
                    if (oldChar == '.') {
                        // Removing a dot that was part of a pair with the left neighbor
                        dotPairCount--;
                    }
                    if (newChar == '.') {
                        // Adding a dot that forms a pair with the left neighbor
                        dotPairCount++;
                    }
                }

                // Check Right Neighbor (index + 1)
                // Similar logic for the right side
                if (index < n - 1 && grid[index + 1] == '.') {
                    if (oldChar == '.') {
                        // Removing a dot that was part of a pair with the right neighbor
                        dotPairCount--;
                    }
                    if (newChar == '.') {
                        // Adding a dot that forms a pair with the right neighbor
                        dotPairCount++;
                    }
                }

                // Update the grid with the new character
                grid[index] = newChar;
            }

            // Output the current count of adjacent dot pairs
            out.println(dotPairCount);
        }

        out.flush();
        out.close();
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;

public class Main {

    // Encapsulate the BufferedReader for efficient and centralized input handling
    private static final BufferedReader BR = new BufferedReader(new InputStreamReader(System.in));

    public static void main(String[] args) throws IOException {
        // Read N (string length) and M (number of updates)
        int[] dimensions = readIntegers(2);
        int n = dimensions[0];
        int m = dimensions[1];

        // Read the initial character sequence
        String line = BR.readLine();
        if (line == null) {
            return;
        }
        char[] sequence = line.toCharArray();

        // Calculate the initial score (number of adjacent dot pairs)
        int dotPairsCount = calculateInitialScore(sequence, n);

        // Process M updates
        for (int i = 0; i < m; i++) {
            String updateLine = BR.readLine();
            if (updateLine == null) break;

            // Split by whitespace to handle multiple spaces robustly
            String[] parts = updateLine.trim().split("\\s+");

            int index = Integer.parseInt(parts[0]) - 1; // Convert 1-based index to 0-based
            char newChar = parts[1].charAt(0);

            char oldChar = sequence[index];

            // Update the score based on the character transition
            if (newChar == '.' && oldChar != '.') {
                // Transition: Non-dot -> Dot
                // Check if we form new pairs with neighbors
                if (index > 0 && sequence[index - 1] == '.') {
                    dotPairsCount++;
                }
                if (index < n - 1 && sequence[index + 1] == '.') {
                    dotPairsCount++;
                }
            } else if (newChar != '.' && oldChar == '.') {
                // Transition: Dot -> Non-dot
                // Check if we break existing pairs with neighbors
                if (index > 0 && sequence[index - 1] == '.') {
                    dotPairsCount--;
                }
                if (index < n - 1 && sequence[index + 1] == '.') {
                    dotPairsCount--;
                }
            }

            // Apply the change to the sequence
            sequence[index] = newChar;

            // Output the current score
            System.out.println(dotPairsCount);
        }
    }

    /**
     * Calculates the initial score of the sequence.
     * The score is defined as the number of pairs of adjacent dots ('..').
     * This is mathematically equivalent to summing (length - 1) for every contiguous block of dots.
     */
    private static int calculateInitialScore(char[] sequence, int n) {
        int count = 0;
        // Iterate through the sequence up to the second-to-last character
        for (int i = 0; i < n - 1; i++) {
            if (sequence[i] == '.' && sequence[i + 1] == '.') {
                count++;
            }
        }
        return count;
    }

    /**
     * Helper method to read a line and parse a specific number of integers from it.
     * Handles whitespace splitting robustly.
     */
    private static int[] readIntegers(int count) throws IOException {
        String line = BR.readLine();
        if (line == null) {
            return new int[count];
        }
        String[] parts = line.trim().split("\\s+");
        int[] result = new int[count];
        for (int i = 0; i < count; i++) {
            if (i < parts.length) {
                result[i] = Integer.parseInt(parts[i]);
            }
        }
        return result;
    }
}

