        // Use try-with-resources to ensure the BufferedReader is properly closed
        try (FastScanner scanner = new FastScanner()) {
            solve(scanner);
        } catch (IOException e) {
            System.err.println("Input error: " + e.getMessage());
        }
    }

    private static void solve(FastScanner scanner) throws IOException {
        int n = scanner.nextInt();
        int m = scanner.nextInt();

        // Use char[] for efficient mutable string representation
        char[] grid = scanner.next().toCharArray();

        // Count initial consecutive dot pairs
        int consecutivePairs = 0;
        for (int i = 0; i < n - 1; i++) {
            if (grid[i] == '.' && grid[i + 1] == '.') {
                consecutivePairs++;
            }
        }

        // Process each update query
        for (int i = 0; i < m; i++) {
            int index = scanner.nextInt() - 1; // Convert to 0-based index
            char newChar = scanner.next().charAt(0);

            // If the character doesn't change, just print the current count
            if (grid[index] == newChar) {
                System.out.println(consecutivePairs);
                continue;
            }

            // Update the consecutive pair count based on neighbors
            if (grid[index] == '.') {
                // Removing a dot: break adjacent pairs
                if (index > 0 && grid[index - 1] == '.') consecutivePairs--;
                if (index < n - 1 && grid[index + 1] == '.') consecutivePairs--;
            } else {
                // Adding a dot: form new adjacent pairs
                if (index > 0 && grid[index - 1] == '.') consecutivePairs++;
                if (index < n - 1 && grid[index + 1] == '.') consecutivePairs++;
            }

            // Apply the update
            grid[index] = newChar;
            System.out.println(consecutivePairs);
        }
    }

    /**
     * Lightweight, efficient input scanner for competitive programming.
     * Replaces the original static tokenizer and multiple read methods.
     */
    static class FastScanner {
