import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) {
        FastReader in = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        ContiguousDotsSolver solver = new ContiguousDotsSolver();
        solver.solve(in, out);

        out.flush();
        out.close();
    }

    /**
     * Solves the contiguous dot segment tracking problem.
     * Maintains a set of disjoint '.' intervals and updates total length on each query.
     */
    static class ContiguousDotsSolver {
        public void solve(FastReader in, PrintWriter out) {
            int n = in.nextInt();
            int m = in.nextInt();
            char[] s = in.next().toCharArray();

            TreeSet<Segment> segments = new TreeSet<>();
            long totalLength = 0;

            // Initialize segments from the initial string
            for (int i = 0; i < n; i++) {
                if (s[i] == '.') {
                    int j = i;
                    while (j < n && s[j] == '.') {
                        j++;
                    }
                    Segment segment = new Segment(i, j - 1);
                    segments.add(segment);
                    totalLength += (j - i); // length = end - start + 1
                    i = j; // Skip processed characters
                }
            }

            // Process each query
            for (int q = 0; q < m; q++) {
                int x = in.nextInt() - 1; // Convert 1-based index to 0-based
                char ch = in.next().charAt(0);

                if (ch == '.' && s[x] != '.') {
                    // === Placing a new dot ===
                    Segment left = segments.floor(new Segment(x, x));
                    Segment right = segments.ceiling(new Segment(x, x));

                    boolean connectsLeft = (left != null && left.end == x - 1);
                    boolean connectsRight = (right != null && right.start == x + 1);

                    if (connectsLeft) {
                        totalLength -= (left.end - left.start + 1);
                        segments.remove(left);
                    }
                    if (connectsRight) {
                        totalLength -= (right.end - right.start + 1);
                        segments.remove(right);
                    }

                    int newStart = connectsLeft ? left.start : x;
                    int newEnd = connectsRight ? right.end : x;
                    segments.add(new Segment(newStart, newEnd));
                    totalLength += (newEnd - newStart + 1);

                } else if (ch != '.' && s[x] == '.') {
                    // === Removing an existing dot ===
                    Segment containing = segments.floor(new Segment(x, x));
                    // containing is guaranteed to exist and cover index x since s[x] == '.'

                    totalLength -= (containing.end - containing.start + 1);
                    segments.remove(containing);

                    if (containing.start != x) {
                        Segment leftPart = new Segment(containing.start, x - 1);
                        segments.add(leftPart);
                        totalLength += (leftPart.end - leftPart.start + 1);
                    }
                    if (containing.end != x) {
                        Segment rightPart = new Segment(x + 1, containing.end);
                        segments.add(rightPart);
                        totalLength += (rightPart.end - rightPart.start + 1);
                    }
                }

                s[x] = ch;
                out.println(totalLength);
            }
        }
    }

    /**
     * Represents a contiguous interval of '.' characters.
     * Ordered by start index to enable efficient TreeSet operations.
     */
    static class Segment implements Comparable<Segment> {
        final int start;
        final int end;

        public Segment(int start, int end) {
            this.start = start;
            this.end = end;
        }

        @Override
        public int compareTo(Segment other) {
            // Segments are guaranteed to be disjoint, so comparing by start index is sufficient
            return Integer.compare(this.start, other.start);
        }

        @Override
        public String toString() {
            return start + " " + end;
        }
    }

    /**
     * Fast I/O helper for competitive programming contexts.
     */
    static class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastReader(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        public String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input", e);
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
