import java.util.StringTokenizer;

public class AdjacentDotsCounter {

    public static void main(String[] args) throws IOException {
        FastScanner scanner = new FastScanner();
        PrintWriter out = new PrintWriter(System.out);

        try {
            int n = scanner.nextInt();
            int m = scanner.nextInt();
            char[] initialGrid = scanner.next().toCharArray();

            DotsCounter counter = new DotsCounter(initialGrid);

            for (int i = 0; i < m; i++) {
                int index = scanner.nextInt() - 1; // Convert 1-based to 0-based
                char newChar = scanner.next().charAt(0);
                out.println(counter.update(index, newChar));
            }
        } finally {
            out.flush();
            out.close();
        }
    }

    /**
     * Fast I/O helper class for performance-critical input reading.
     */
    private static class FastScanner {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastScanner() {
            this.reader = new BufferedReader(new InputStreamReader(System.in));
            this.tokenizer = new StringTokenizer("");
        }

        public String next() throws IOException {
            while (!tokenizer.hasMoreTokens()) {
                String line = reader.readLine();
                if (line == null) {
                    throw new IOException("Unexpected end of input");
                }
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }

    /**
     * Encapsulates the business logic for tracking adjacent dot pairs.
     * Maintains state and provides efficient O(1) updates per query.
     */
    private static class DotsCounter {
        private final char[] grid;
        private int adjacentPairs;

        public DotsCounter(char[] grid) {
            this.grid = grid.clone(); // Defensive copy to prevent external mutation
            this.adjacentPairs = calculateInitialPairs();
        }

        private int calculateInitialPairs() {
            int count = 0;
            for (int i = 0; i < grid.length - 1; i++) {
                if (grid[i] == '.' && grid[i + 1] == '.') {
                    count++;
                }
            }
            return count;
        }

        /**
         * Updates the grid at the given index and returns the new count of adjacent dot pairs.
         * Only checks affected neighbors to maintain O(1) update complexity.
         */
        public int update(int index, char newChar) {
            char oldChar = grid[index];
            if (oldChar == newChar) {
                return adjacentPairs;
            }

            // Check left neighbor
            if (index > 0) {
                if (oldChar == '.' && grid[index - 1] == '.') {
                    adjacentPairs--;
                } else if (newChar == '.' && grid[index - 1] == '.') {
                    adjacentPairs++;
                }
            }

            // Check right neighbor
            if (index < grid.length - 1) {
                if (oldChar == '.' && grid[index + 1] == '.') {
                    adjacentPairs--;
                } else if (newChar == '.' && grid[index + 1] == '.') {
                    adjacentPairs++;
                }
            }

            grid[index] = newChar;
            return adjacentPairs;
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

public class Main {

    public static void main(String[] args) throws IOException {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(reader.readLine());

        int n = Integer.parseInt(st.nextToken());
        int m = Integer.parseInt(st.nextToken());
        String initialString = reader.readLine();

        SegmentTracker tracker = new SegmentTracker(n, initialString);

        StringBuilder output = new StringBuilder();
        for (int i = 0; i < m; i++) {
            String line = reader.readLine();
            if (line == null) break;
            st = new StringTokenizer(line);

            int index = Integer.parseInt(st.nextToken());
            char newChar = st.nextToken().charAt(0);

            tracker.update(index, newChar);
            output.append(tracker.getDotCount() - tracker.getGroupCount()).append('\n');
        }
        System.out.print(output);
    }

    /**
     * Tracks the count of individual dots and contiguous groups of dots.
     * Uses 1-based indexing for external queries, with internal padding for safe neighbor access.
     */
    static class SegmentTracker {
        private final boolean[] isDot;
        private int dotCount;
        private int groupCount;

        public SegmentTracker(int n, String initialString) {
            // Pad array with false at indices 0 and n+1 to safely access neighbors without boundary checks
            isDot = new boolean[n + 2];

            for (int i = 0; i < n; i++) {
                if (initialString.charAt(i) == '.') {
                    isDot[i + 1] = true;
                    dotCount++;
                    // A new group starts if it's the first character or the previous character is not a dot
                    if (i == 0 || initialString.charAt(i - 1) != '.') {
                        groupCount++;
                    }
                }
            }
        }

        /**
         * Updates the character at the given 1-based index and adjusts counts accordingly.
         *
         * @param index 1-based position to update
         * @param newChar The new character ('.' or non-'.')
         */
        public void update(int index, char newChar) {
            boolean isAddingDot = newChar == '.';
            boolean currentlyDot = isDot[index];

            // Early exit if the state doesn't change
            if (isAddingDot == currentlyDot) {
                return;
            }

            boolean leftIsDot = isDot[index - 1];
            boolean rightIsDot = isDot[index + 1];

            if (isAddingDot) {
                dotCount++;
                // Merging two existing groups into one
                if (leftIsDot && rightIsDot) {
                    groupCount--;
                }
                // Creating a new isolated group
                else if (!leftIsDot && !rightIsDot) {
                    groupCount++;
                }
            } else {
                dotCount--;
                // Splitting one group into two
                if (leftIsDot && rightIsDot) {
                    groupCount++;
                }
                // Removing an isolated group entirely
                else if (!leftIsDot && !rightIsDot) {
                    groupCount--;
                }
            }
            // Apply the state change
            isDot[index] = isAddingDot;
        }

        public int getDotCount() {
            return dotCount;
        }

        public int getGroupCount() {
            return groupCount;
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

/**
 * Refactored Period Counter Program.
 * 
 * Improvements made:
 * 1. Readability: Renamed variables (isPeriod -> isDot, total -> totalPairs) and added comments.
 * 2. Maintainability: Encapsulated logic into clear blocks (Initialization, Query Processing).
 * 3. Efficiency: Used StringTokenizer for parsing and PrintWriter for buffered output.
 * 4. Robustness: Simplified boundary checks and removed redundant logic (e.g., explicit length check).
 * 5. Logic Clarity: Unified the update logic into a single delta calculation block.
 */
public class Replacement {
    public static void main(String[] args) throws IOException {
        // Use BufferedReader for efficient input reading
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        // Use PrintWriter for buffered output
        PrintWriter out = new PrintWriter(System.out);

        // Read N and M
        String line = br.readLine();
        if (line != null) {
            StringTokenizer st = new StringTokenizer(line);
            int n = Integer.parseInt(st.nextToken());
            int m = Integer.parseInt(st.nextToken());

            // Read the string S
            String s = br.readLine();
            if (s == null) s = "";

            // State to track if each character is a period
            boolean[] isDot = new boolean[n];
            int totalPairs = 0;

            // 1. Initialization: Parse string and calculate initial score
            // The score represents the number of adjacent pairs of periods ('.')
            int streak = 0;
            for (int i = 0; i < n; i++) {
                boolean currentIsDot = (i < s.length()) && (s.charAt(i) == '.');
                isDot[i] = currentIsDot;

                if (currentIsDot) {
                    streak++;
                } else {
                    if (streak > 0) {
                        totalPairs += streak - 1;
                        streak = 0;
                    }
                }
            }
            // Add the final streak if the string ended with periods
            if (streak > 0) {
                totalPairs += streak - 1;
            }

            // 2. Process Queries
            for (int i = 0; i < m; i++) {
                line = br.readLine();
                if (line == null) break;

                st = new StringTokenizer(line);

                // Input format: index (1-based) char
                int index = Integer.parseInt(st.nextToken()) - 1; // Convert to 0-based
                char newChar = st.nextToken().charAt(0);
                boolean newIsDot = (newChar == '.');

                // Only update if the state actually changes
                if (isDot[index] != newIsDot) {
                    int delta = 0;

                    // Determine neighbors' states safely (treat boundaries as non-periods)
                    boolean leftIsDot = (index > 0) && isDot[index - 1];
                    boolean rightIsDot = (index < n - 1) && isDot[index + 1];

                    if (newIsDot) {
                        // Case: Adding a period
                        if (leftIsDot && rightIsDot) {
                            // Merging two groups: e.g., ".." -> "..."
                            // Creates 2 new adjacent pairs
                            delta = 2;
                        } else if (leftIsDot || rightIsDot) {
                            // Extending a group: e.g., ".a" -> ".."
                            // Creates 1 new adjacent pair
                            delta = 1;
                        } else {
                            // Creating an isolated period: e.g., "a" -> "."
                            // Creates 0 new pairs
                            delta = 0;
                        }
                    } else {
                        // Case: Removing a period
                        if (leftIsDot && rightIsDot) {
                            // Splitting a group: e.g., "..." -> ".."
                            // Destroys 2 adjacent pairs
                            delta = -2;
                        } else if (leftIsDot || rightIsDot) {
                            // Shortening a group: e.g., ".." -> "."
                            // Destroys 1 adjacent pair
                            delta = -1;
                        } else {
                            // Removing an isolated period: e.g., "." -> "a"
                            // Destroys 0 pairs
                            delta = 0;
                        }
                    }

                    totalPairs += delta;
                    isDot[index] = newIsDot;
                }
                out.println(totalPairs);
            }
        }
        out.flush();
    }
}

import java.io.BufferedReader;
import java.io.IOException;
