import java.io.PrintWriter;

public class Substituicao {

    public static void main(String[] args) throws IOException {
        // Local I/O streams to avoid static state pollution and improve testability
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter out = new PrintWriter(System.out);

        // Parse initial configuration
        String[] initialInput = reader.readLine().split("\\s+");
        int sequenceLength = Integer.parseInt(initialInput[0]);
        int numQueries = Integer.parseInt(initialInput[1]);

        // Read the character sequence
        char[] sequence = reader.readLine().toCharArray();

        // Calculate initial count of adjacent '.' pairs
        int adjacentDotPairs = countAdjacentDotPairs(sequence);

        // Process each query
        for (int i = 0; i < numQueries; i++) {
            String[] queryInput = reader.readLine().split("\\s+");
            int queryIndex = Integer.parseInt(queryInput[0]);
            char newChar = queryInput[1].charAt(0);

            adjacentDotPairs = processQuery(sequence, queryIndex, newChar, adjacentDotPairs);
            out.println(adjacentDotPairs);
        }

        out.flush();
    }

    /**
     * Counts the number of adjacent '.' pairs in the sequence.
     */
    private static int countAdjacentDotPairs(char[] sequence) {
        int count = 0;
        for (int i = 0; i < sequence.length - 1; i++) {
            if (sequence[i] == '.' && sequence[i + 1] == '.') {
                count++;
            }
        }
        return count;
    }

    /**
     * Processes a single substitution query and updates the adjacent pair count.
     * Only adjusts the count if the character type ('.' or non-'.') actually changes.
     */
    private static int processQuery(char[] sequence, int queryIndex, char newChar, int currentCount) {
        int idx = queryIndex - 1; // Convert 1-based index to 0-based
        boolean wasDot = sequence[idx] == '.';
        boolean isDot = newChar == '.';

        if (wasDot != isDot) {
            // Check right neighbor
            if (idx + 1 < sequence.length) {
                if (isDot && sequence[idx + 1] == '.') {
                    currentCount++;
                } else if (!isDot && sequence[idx + 1] == '.') {
                    currentCount--;
                }
            }
            // Check left neighbor
            if (idx - 1 >= 0) {
                if (isDot && sequence[idx - 1] == '.') {
                    currentCount++;
                } else if (!isDot && sequence[idx - 1] == '.') {
                    currentCount--;
                }
            }
        }

        // Apply the substitution after checking neighbors
        sequence[idx] = newChar;
        return currentCount;
    }
}

import java.util.Scanner;
import java.io.PrintWriter;

public class Main {
    public static void main(String[] args) {
        // Use Scanner for input and PrintWriter for buffered output
        Scanner in = new Scanner(System.in);
        PrintWriter out = new PrintWriter(System.out);

        // Instantiate solver and execute
        TaskC solver = new TaskC();
        solver.solve(in, out);

        // Ensure all output is written and resources are closed
        out.flush();
        out.close();
    }

    static class TaskC {
        public void solve(Scanner in, PrintWriter out) {
            // Read n (length of string) and m (number of queries)
            if (!in.hasNextInt()) return;
            int n = in.nextInt();
            int m = in.nextInt();

            // Consume the newline character remaining after nextInt()
            in.nextLine();

            // Read the string s
            String s = in.nextLine();

            // Convert to char array for efficient updates
            char[] chars = s.toCharArray();

            // Calculate initial total (count of adjacent dot pairs)
            long total = calculateInitialTotal(chars);

            // Process each query
            for (int i = 0; i < m; i++) {
                int idx = in.nextInt() - 1; // Convert 1-based index to 0-based
                String str = in.next();
                char c = str.charAt(0);

                // Logic to update 'total' based on the change at chars[idx]
                // 'total' represents the number of adjacent dot pairs ("..")

                if (chars[idx] == '.' && c != '.') {
                    // Case: Removing a dot (changing '.' to a non-dot character)
                    // If the dot was connected to a neighbor dot, we lose a pair.

                    // Check left neighbor
                    if (idx > 0 && chars[idx - 1] == '.') {
                        total--;
                    }
                    // Check right neighbor
                    if (idx < chars.length - 1 && chars[idx + 1] == '.') {
                        total--;
                    }
                } else if (chars[idx] != '.' && c == '.') {
                    // Case: Adding a dot (changing a non-dot character to '.')
                    // If the new dot connects to a neighbor dot, we gain a pair.

                    // Check left neighbor
                    if (idx > 0 && chars[idx - 1] == '.') {
                        total++;
                    }
                    // Check right neighbor
                    if (idx < chars.length - 1 && chars[idx + 1] == '.') {
                        total++;
                    }
                }
                // If changing a dot to a dot, or non-dot to non-dot, total remains unchanged.

                // Apply the character update
                chars[idx] = c;

                // Output the current total
                out.println(total);
            }
        }

        /**
         * Calculates the initial number of adjacent dot pairs in the string.
         * A pair is defined as two consecutive dots "..".
         * For a contiguous segment of k dots, there are k-1 pairs.
         */
        private long calculateInitialTotal(char[] chars) {
            long total = 0;
            int currentRun = 0;

            for (char c : chars) {
                if (c == '.') {
                    currentRun++;
                } else {
                    // Segment of dots ended
                    if (currentRun > 1) {
                        total += (currentRun - 1);
                    }
                    currentRun = 0;
                }
            }
            // Check if the string ended with a sequence of dots
            if (currentRun > 1) {
                total += (currentRun - 1);
            }

            return total;
        }
    }
}

