/**
 * Refactored solution for Codeforces 570C - Replacement.
 * 
 * Key Improvements:
 * 1. Simplified Algorithm: Replaced complex segment-tracking logic with a direct 
 *    O(N) initial count and O(1) per-query update by only checking immediate neighbors.
 * 2. Separation of Concerns: Extracted counting and update logic into dedicated 
 *    methods for better readability and testability.
 * 3. Robust I/O: Replaced the buggy custom Scanner with a standard, production-ready 
 *    FastReader that correctly handles whitespace and newlines.
 * 4. Naming & Conventions: Applied camelCase, descriptive variable names, and 
 *     removed unused methods/magic numbers.
 * 5. Performance: Maintains O(N + M) time complexity and O(N) space complexity.
 */
public class ReplacementCF570C {

    public static void main(String[] args) throws IOException {
        FastReader scanner = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        int length = scanner.nextInt();
        int numQueries = scanner.nextInt();
        char[] characters = scanner.next().toCharArray();

        int adjacentDotPairs = countInitialAdjacentPairs(characters);

        for (int q = 0; q < numQueries; q++) {
            int index = scanner.nextInt() - 1; // Convert 1-based input to 0-based array index
            char newChar = scanner.next().charAt(0);

            if (characters[index] != newChar) {
                adjacentDotPairs = updateAdjacentPairs(characters, length, index, newChar, adjacentDotPairs);
            }

            out.println(adjacentDotPairs);
        }

        out.flush();
        out.close();
    }

    /**
     * Calculates the initial number of adjacent '.' pairs in the character array.
     * Time Complexity: O(N)
     */
    private static int countInitialAdjacentPairs(char[] characters) {
        int count = 0;
        for (int i = 0; i < characters.length - 1; i++) {
            if (characters[i] == '.' && characters[i + 1] == '.') {
                count++;
            }
        }
        return count;
    }

    /**
     * Efficiently updates the adjacent pair count when a single character changes.
     * Only the pairs involving the changed index and its immediate neighbors are affected.
     * Time Complexity: O(1)
     */
    private static int updateAdjacentPairs(char[] characters, int length, int index, char newChar, int currentCount) {
        // Remove contributions from the old character with its neighbors
        if (index > 0 && characters[index - 1] == '.' && characters[index] == '.') {
            currentCount--;
        }
        if (index < length - 1 && characters[index] == '.' && characters[index + 1] == '.') {
            currentCount--;
        }

        // Apply the character change
        characters[index] = newChar;

        // Add contributions from the new character with its neighbors
        if (index > 0 && characters[index - 1] == '.' && characters[index] == '.') {
            currentCount++;
        }
        if (index < length - 1 && characters[index] == '.' && characters[index + 1] == '.') {
            currentCount++;
        }

        return currentCount;
    }

    /**
     * High-performance I/O helper class.
     * Replaces java.util.Scanner to avoid TLE on large inputs while handling tokens correctly.
     */
    static class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastReader(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        String next() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) return null;
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

        int nextInt() throws IOException {
            String token = next();
            return token == null ? 0 : Integer.parseInt(token);
        }
    }
}

import java.io.IOException;
import java.util.InputMismatchException;

public class Replacement {
    public static void main(String[] args) {
        FasterScanner scanner = new FasterScanner();

        int stringLength = scanner.nextInt();
        int queryCount = scanner.nextInt();
        String inputString = scanner.nextLine();

        // Pad with '#' to simplify boundary checks for adjacent pairs
        char[] characters = ("#" + inputString + "#").toCharArray();
        int adjacentDotPairsCount = calculateInitialAdjacentDotPairs(characters);

        StringBuilder output = new StringBuilder();
        for (int i = 0; i < queryCount; i++) {
            int updateIndex = scanner.nextInt();
            char newChar = scanner.nextString().charAt(0);

            if (characters[updateIndex] == '.' && newChar != '.') {
                adjacentDotPairsCount -= countAdjacentDotPairsAt(characters, updateIndex);
                characters[updateIndex] = newChar;
            } else if (characters[updateIndex] != '.' && newChar == '.') {
                adjacentDotPairsCount += countAdjacentDotPairsAt(characters, updateIndex);
                characters[updateIndex] = newChar;
            }
            output.append(adjacentDotPairsCount).append('\n');
        }
        System.out.print(output);
    }

    /**
     * Calculates the total number of adjacent dot pairs in the padded character array.
     * Time Complexity: O(N)
     */
    private static int calculateInitialAdjacentDotPairs(char[] chars) {
        int count = 0;
        for (int i = 1; i < chars.length; i++) {
            if (chars[i] == '.' && chars[i - 1] == '.') {
                count++;
            }
        }
        return count;
    }

    /**
     * Counts how many adjacent dot pairs involve the character at the given index.
     * Assumes the array is padded and the index is within the original string bounds.
     * Time Complexity: O(1)
     */
    private static int countAdjacentDotPairsAt(char[] chars, int index) {
        int count = 0;
        if (chars[index - 1] == '.') count++;
        if (chars[index + 1] == '.') count++;
        return count;
    }

    /**
     * Optimized scanner for fast input reading.
     * Extracted to a static nested class for encapsulation and reusability.
     */
    public static class FasterScanner {
        private final byte[] buffer = new byte[1024];
        private int bufferPointer;
        private int bytesRead;

        public int read() {
            if (bytesRead == -1) {
                throw new InputMismatchException();
            }
            if (bufferPointer >= bytesRead) {
                bufferPointer = 0;
                try {
                    bytesRead = System.in.read(buffer);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (bytesRead <= 0) {
                    return -1;
                }
            }
            return buffer[bufferPointer++];
        }

        private boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        private boolean isEndOfLine(int c) {
            return c == '\n' || c == '\r' || c == -1;
        }

        public int nextInt() {
            return (int) nextLong();
        }

        public long nextLong() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            long res = 0;
            do {
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                res = res * 10 + (c - '0');
                c = read();
            } while (!isSpaceChar(c));
            return res * sign;
        }

        public String nextString() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            StringBuilder sb = new StringBuilder();
            do {
                sb.appendCodePoint(c);
                c = read();
            } while (!isSpaceChar(c));
            return sb.toString();
        }

        public String nextLine() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            StringBuilder sb = new StringBuilder();
            do {
                sb.appendCodePoint(c);
                c = read();
            } while (!isEndOfLine(c));
            return sb.toString();
        }
    }
}

