        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);

        TaskC solver = new TaskC();
        solver.solve(in, out);

        out.close();
    }

    /**
     * Solves the problem by calculating the number of adjacent dot pairs
     * and efficiently updating the count during character modifications.
     */
    static class TaskC {
        public void solve(InputReader in, PrintWriter out) {
            int n = in.nextInt();
            int q = in.nextInt();
            char[] s = in.next().toCharArray();

            // moves represents the number of adjacent dot pairs in the string
            int moves = countAdjacentDotPairs(s);

            for (int i = 0; i < q; i++) {
                int idx = in.nextInt() - 1; // Convert to 0-based index
                char newChar = in.next().charAt(0);
                char oldChar = s[idx];

                // Only process if the character actually changes
                if (oldChar != newChar) {
                    int adjacentDots = countAdjacentDots(s, idx);

                    if (oldChar == '.' && newChar != '.') {
                        // Removing a dot breaks adjacent pairs
                        moves -= adjacentDots;
                    } else if (oldChar != '.' && newChar == '.') {
                        // Adding a dot creates new adjacent pairs
                        moves += adjacentDots;
                    }

                    s[idx] = newChar;
                }

                out.println(moves);
            }
