         * Used to determine how many pairs are created or removed during an update.
         */
        private int countAdjacentDots(char[] s, int idx) {
            int count = 0;
            if (idx > 0 && s[idx - 1] == '.') count++;
            if (idx < s.length - 1 && s[idx + 1] == '.') count++;
