        int numChars = reader.nextInt();
        int numQueries = reader.nextInt();
        char[] characters = reader.next().toCharArray();

        // Calculate initial adjacent dot pairs
        int dotPairCount = countInitialDotPairs(characters);

        // Process each query
        for (int q = 0; q < numQueries; q++) {
            int queryIndex = reader.nextInt() - 1; // Convert 1-based to 0-based indexing
            char newChar = reader.next().charAt(0);

            dotPairCount = updateDotPairs(characters, queryIndex, newChar, dotPairCount);
            output.append(dotPairCount).append('\n');
        }

        System.out.println(output);
    }

    /**
     * Counts the initial number of adjacent dot pairs in the array.
     * A pair is formed whenever two '.' characters are adjacent.
     *
     * @param characters the character array to analyze
     * @return total number of adjacent dot pairs
     */
    private static int countInitialDotPairs(char[] characters) {
        int dotPairs = 0;
        int consecutiveDots = 0;

        for (char ch : characters) {
            if (ch == '.') {
                consecutiveDots++;
            } else {
                if (consecutiveDots > 1) {
                    dotPairs += consecutiveDots - 1;
                }
                consecutiveDots = 0;
            }
        }
        // Handle case where the array ends with dots
        if (consecutiveDots > 1) {
            dotPairs += consecutiveDots - 1;
        }
        return dotPairs;
    }

    /**
     * Updates the character at the specified index and adjusts the dot pair count.
     *
     * @param characters      the mutable character array
     * @param index           the 0-based index to update
     * @param newChar         the replacement character
     * @param currentDotPairs the current count of adjacent dot pairs
     * @return the updated dot pair count
     */
    private static int updateDotPairs(char[] characters, int index, char newChar, int currentDotPairs) {
        char oldChar = characters[index];

        // Early exit if the character isn't actually changing
        if (oldChar == newChar) {
            return currentDotPairs;
        }

        if (oldChar == '.' && newChar != '.') {
            // Removing a dot: decrement count for each adjacent dot neighbor
            if (index > 0 && characters[index - 1] == '.') {
                currentDotPairs--;
            }
            if (index < characters.length - 1 && characters[index + 1] == '.') {
                currentDotPairs--;
            }
        } else if (oldChar != '.' && newChar == '.') {
            // Adding a dot: increment count for each adjacent dot neighbor
            if (index > 0 && characters[index - 1] == '.') {
                currentDotPairs++;
            }
            if (index < characters.length - 1 && characters[index + 1] == '.') {
                currentDotPairs++;
            }
        }

        // Apply the update
        characters[index] = newChar;
        return currentDotPairs;
    }

    /**
     * Fast input reader optimized for competitive programming and high-throughput scenarios.
     */
    static class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastReader(InputStream input) {
            this.br = new BufferedReader(new InputStreamReader(input));
        }

