/**
 * A program to process string replacements and track the count of double dots ("..").
 * It reads an initial string and a series of updates, adjusting the count of ".."
 * occurrences after each update.
 */
public class StringReplacements {

    public static void main(String[] args) throws IOException {
        // Initialize efficient input reading
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));

        // Read the first line containing Length (L) and Number of Queries (N)
        // Using StringTokenizer is more robust than split(" ") for whitespace handling
        String firstLine = reader.readLine();
        if (firstLine == null) return;

        StringTokenizer tokenizer = new StringTokenizer(firstLine);
        int length = Integer.parseInt(tokenizer.nextToken());
        int numQueries = Integer.parseInt(tokenizer.nextToken());

        // Read the initial string
        String initialString = reader.readLine();
        // Convert to char array for mutable operations
        char[] charArray = initialString.toCharArray();

        // Calculate the initial count of ".." pairs
        int doubleDotCount = countDoubleDots(charArray, length);

        // Process each query
        for (int i = 0; i < numQueries; i++) {
            String queryLine = reader.readLine();
            if (queryLine == null) break;

            tokenizer = new StringTokenizer(queryLine);
            // Input index is 1-based, convert to 0-based
            int index = Integer.parseInt(tokenizer.nextToken()) - 1;
            char newChar = tokenizer.nextToken().charAt(0);

            // Update the character in the array and recalculate the count
            doubleDotCount = updateCharacterAndCount(charArray, length, index, newChar, doubleDotCount);

            // Output the current count
            System.out.println(doubleDotCount);
        }
    }

    /**
     * Counts the number of occurrences of ".." (two consecutive dots) in the array.
     * 
     * @param chars The character array to scan.
     * @param length The logical length of the string.
     * @return The count of ".." pairs.
     */
    private static int countDoubleDots(char[] chars, int length) {
        int count = 0;
        // Iterate up to length - 2 to safely check index i + 1
        for (int i = 0; i < length - 1; i++) {
            if (chars[i] == '.' && chars[i + 1] == '.') {
                count++;
            }
        }
        return count;
    }

    /**
     * Updates the character at the specified index and adjusts the double dot count.
     * 
     * @param chars The character array.
     * @param length The logical length of the string.
     * @param index The 0-based index to update.
     * @param newChar The character to place at the index.
     * @param currentCount The current count of ".." pairs.
     * @return The updated count of ".." pairs.
     */
    private static int updateCharacterAndCount(char[] chars, int length, int index, char newChar, int currentCount) {
        char oldChar = chars[index];

        // If the character is not actually changing, the count remains the same
        if (oldChar == newChar) {
            return currentCount;
        }

        // Logic to update the count based on neighbors
        // We only care if we are removing a dot or adding a dot.

        // Case 1: Removing a dot (Old was '.', New is not '.')
        // We must decrement count if the removed dot was part of a ".." pair
        if (oldChar == '.') {
            // Check left neighbor
            if (index > 0 && chars[index - 1] == '.') {
                currentCount--;
            }
            // Check right neighbor
            if (index < length - 1 && chars[index + 1] == '.') {
                currentCount--;
            }
        } 
        // Case 2: Adding a dot (Old was not '.', New is '.')
        // We must increment count if the new dot forms a ".." pair with neighbors
        else if (newChar == '.') {
            // Check left neighbor
            if (index > 0 && chars[index - 1] == '.') {
                currentCount++;
            }
            // Check right neighbor
            if (index < length - 1 && chars[index + 1] == '.') {
                currentCount++;
            }
        }

        // Apply the change to the array
        chars[index] = newChar;

        return currentCount;
    }
}

