/**
 * Solves the adjacent dots counting problem.
 * Maintains a running count of adjacent dot pairs ('..') and efficiently
 * updates it upon character modifications.
 */
public class AdjacentDotsSolver {

    public static void main(String[] args) throws IOException {
        FastScanner scanner = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out);

        int n = scanner.nextInt();
        int m = scanner.nextInt();
        char[] s = scanner.next().toCharArray();

        // Calculate initial count of adjacent dot pairs
        int adjacentDotPairs = calculateInitialAdjacentDotPairs(s);

        for (int i = 0; i < m; i++) {
            int index = scanner.nextInt() - 1; // Convert 1-based to 0-based index
            char newChar = scanner.next().charAt(0);

            // If the character doesn't change, just print the current count
            if (s[index] == newChar) {
                out.println(adjacentDotPairs);
                continue;
            }

            // Update the count based on the change and print the new count
            adjacentDotPairs = updateAdjacentDotPairs(index, newChar, s, adjacentDotPairs);
            out.println(adjacentDotPairs);
        }

        out.flush();
    }

    /**
     * Counts the number of adjacent dot pairs in the initial string.
     * Time Complexity: O(n)
     */
    private static int calculateInitialAdjacentDotPairs(char[] s) {
        int count = 0;
        for (int i = 0; i < s.length - 1; i++) {
            if (s[i] == '.' && s[i + 1] == '.') {
                count++;
            }
        }
        return count;
    }

    /**
     * Updates the adjacent dot pair count when a character at a specific index changes.
     * Only neighbors of the changed index can affect the count.
     * Time Complexity: O(1)
     */
    private static int updateAdjacentDotPairs(int index, char newChar, char[] s, int currentCount) {
        s[index] = newChar;

        if (newChar == '.') {
            // Adding a dot: increment count for each adjacent dot neighbor
            if (index > 0 && s[index - 1] == '.') {
                currentCount++;
            }
            if (index < s.length - 1 && s[index + 1] == '.') {
                currentCount++;
            }
        } else {
            // Removing a dot: decrement count for each adjacent dot neighbor
            if (index > 0 && s[index - 1] == '.') {
                currentCount--;
            }
            if (index < s.length - 1 && s[index + 1] == '.') {
                currentCount--;
            }
        }

        return currentCount;
    }

    /**
     * Fast I/O helper class for performance-critical tasks.
     * Replaces the original monolithic Scanner with a focused, robust implementation.
     */
    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        public String next() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) {
                    return null;
                }
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

        public int nextInt() throws IOException {
            String token = next();
            return (token == null) ? 0 : Integer.parseInt(token);
        }
    }
}

import java.io.*;
import java.util.InputMismatchException;

/**
 * Solves the problem of tracking the number of adjacent '.' pairs
 * in a character sequence under point updates.
 * 
 * Time Complexity: O(N + M)
 * Space Complexity: O(N)
 */
public class Main {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);
        solve(reader, out);
        out.flush();
        out.close();
    }

    private static void solve(FastReader reader, PrintWriter out) {
        int n = reader.nextInt();
        int m = reader.nextInt();
        char[] characters = reader.next().toCharArray();

        // Count initial adjacent '.' pairs
        // A run of k consecutive '.' characters contributes (k - 1) pairs
        long adjacentDotPairs = 0;
        for (int i = 1; i < n; i++) {
            if (characters[i] == '.' && characters[i - 1] == '.') {
                adjacentDotPairs++;
            }
        }

        // Process each update query
        for (int i = 0; i < m; i++) {
            int idx = reader.nextInt() - 1; // Convert 1-based index to 0-based
            char newChar = reader.nextChar();

            // Remove contributions from the old character if it was '.'
            if (characters[idx] == '.') {
                if (idx > 0 && characters[idx - 1] == '.') {
                    adjacentDotPairs--;
                }
                if (idx < n - 1 && characters[idx + 1] == '.') {
                    adjacentDotPairs--;
                }
            }

            // Apply the update
            characters[idx] = newChar;

            // Add contributions from the new character if it is '.'
            if (characters[idx] == '.') {
                if (idx > 0 && characters[idx - 1] == '.') {
                    adjacentDotPairs++;
                }
                if (idx < n - 1 && characters[idx + 1] == '.') {
                    adjacentDotPairs++;
                }
            }

            out.println(adjacentDotPairs);
        }
    }

    /**
     * Fast I/O helper class optimized for competitive programming.
     * Replaces Scanner for significantly better performance on large inputs.
     */
    static class FastReader {
        private final InputStream stream;
        private final byte[] buffer = new byte[1024];
        private int bufferPtr = 0;
        private int bytesRead = 0;

        public FastReader(InputStream stream) {
            this.stream = stream;
        }

        private int readByte() {
            if (bufferPtr >= bytesRead) {
                bufferPtr = 0;
                try {
                    bytesRead = stream.read(buffer);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
                if (bytesRead <= 0) {
                    return -1;
                }
            }
            return buffer[bufferPtr++];
        }

        public int nextInt() {
            int c = readByte();
            while (isSpaceChar(c)) {
                c = readByte();
            }
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = readByte();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9') {
                    throw new InputMismatchException("Invalid integer format");
                }
                res = res * 10 + (c - '0');
                c = readByte();
            } while (!isSpaceChar(c));
            return res * sign;
        }

        public String next() {
            int c = readByte();
            while (isSpaceChar(c)) {
                c = readByte();
            }
            StringBuilder sb = new StringBuilder();
            do {
                sb.appendCodePoint(c);
                c = readByte();
            } while (!isSpaceChar(c));
            return sb.toString();
        }

        public char nextChar() {
            int c = readByte();
            while (isSpaceChar(c)) {
                c = readByte();
            }
            return (char) c;
        }

        private boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }
    }
}

