import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

/**
 * Solution class for counting and updating adjacent dot pairs in a string.
 * Refactored for maintainability, readability, and standard Java practices.
 */
public class Solution {

    public static void main(String[] args) {
        new Solution().solve();
    }

    /**
     * Main execution method that handles input, processing, and output.
     */
    public void solve() {
        FastScanner scanner = new FastScanner();
        PrintWriter out = new PrintWriter(System.out);

        try {
            int n = scanner.nextInt();
            int m = scanner.nextInt();
            String s = scanner.next();

            // Create array with padding to avoid boundary checks during pair evaluation
            char[] charArray = new char[n + 2];
            charArray[0] = 'a'; // Left padding
            for (int i = 0; i < n; i++) {
                charArray[i + 1] = s.charAt(i);
            }
            charArray[n + 1] = 'a'; // Right padding

            // Count initial adjacent dot pairs
            int adjacentDotsCount = 0;
            for (int i = 1; i < n; i++) {
                if (charArray[i] == '.' && charArray[i + 1] == '.') {
                    adjacentDotsCount++;
                }
            }

            // Process each update query
            for (int i = 0; i < m; i++) {
                int queryIndex = scanner.nextInt();
                String cStr = scanner.next();
                char newChar = cStr.charAt(0);

                // Adjust count: remove old contributions, update character, add new contributions
                adjacentDotsCount -= countAdjacentDots(charArray, queryIndex);
                charArray[queryIndex] = newChar;
                adjacentDotsCount += countAdjacentDots(charArray, queryIndex);

                out.println(adjacentDotsCount);
            }
        } finally {
            out.flush();
            out.close();
        }
    }

    /**
     * Helper method to count how many adjacent pairs involve a dot at the given index.
     * Checks both left and right neighbors safely.
     */
    private int countAdjacentDots(char[] arr, int idx) {
        int count = 0;
        if (arr[idx] == '.' && idx > 0 && arr[idx - 1] == '.') {
            count++;
        }
        if (arr[idx] == '.' && idx < arr.length - 1 && arr[idx + 1] == '.') {
            count++;
        }
        return count;
    }

    /**
     * Standard, maintainable FastScanner using BufferedReader and StringTokenizer.
     * Replaces the custom byte-buffer scanner for better readability and compatibility.
     */
    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.util.Scanner;

/**
 * Refactored Solution for the Light Switching / Dot Pair problem.
 * 
 * Key Improvements:
 * 1. Readability: Replaced cryptic single-letter variables (n, m, f, s, c, x) 
 *    with descriptive names (numItems, numQueries, adjacentDotPairsCount, etc.).
 * 2. Maintainability: Extracted initialization and update logic into helper methods 
 *    to reduce the complexity of the main method.
 * 3. Logic Clarity: Simplified the logic for counting adjacent dot pairs. 
 *    The variable 'f' now clearly represents 'adjacentDotPairsCount'.
 * 4. Structure: Used a StringBuilder for efficient output concatenation.
 * 5. Safety: Utilized array padding to safely handle boundary checks without 
 *    explicit index validation in the update loop.
 */
public class Solution {

    public static void main(String[] args) {
        // Initialize Scanner for input
        Scanner scanner = new Scanner(System.in);

        // Read number of items (n) and number of queries (m)
        // Check to ensure input exists
        if (!scanner.hasNextInt()) {
            scanner.close();
            return;
        }
        int numItems = scanner.nextInt();
        int numQueries = scanner.nextInt();

        // Initialize the state array. 
        // We use size n + 2 to add padding at indices 0 and n+1.
        // This simplifies boundary checks (no need to check if index is 0 or n).
        char[] currentState = new char[numItems + 2];
        currentState[0] = 'a'; // Padding
        currentState[numItems + 1] = 'a'; // Padding

        // Read the initial configuration string
        String initialStateString = scanner.next();
        for (int i = 0; i < numItems; i++) {
            currentState[i + 1] = initialStateString.charAt(i);
        }

        // Calculate the initial number of adjacent dot pairs
        int adjacentDotPairsCount = calculateInitialDotPairs(currentState, numItems);

        // StringBuilder for efficient output concatenation
        StringBuilder outputBuilder = new StringBuilder();

        // Process each query
        for (int i = 0; i < numQueries; i++) {
            int index = scanner.nextInt();
            String charInput = scanner.next();
            char newChar = charInput.charAt(0);

            // Update the state and the count
            adjacentDotPairsCount = updateState(currentState, index, newChar, adjacentDotPairsCount);

            // Append result to output buffer
            outputBuilder.append(adjacentDotPairsCount).append("\n");
        }

        // Print final output
        System.out.println(outputBuilder);

        scanner.close();
    }

    /**
     * Helper method to calculate the initial count of adjacent dot pairs.
     * A pair is defined as two consecutive '.' characters.
     * For a sequence of k consecutive dots, there are k-1 pairs.
     * 
     * @param state The state array (1-based indexing used for data)
     * @param n The number of actual items
     * @return The count of adjacent dot pairs
     */
    private static int calculateInitialDotPairs(char[] state, int n) {
        int count = 0;
        int consecutiveDots = 0;

        // Iterate through the valid range (1 to n)
        for (int i = 1; i <= n; i++) {
            if (state[i] == '.') {
                consecutiveDots++;
            } else {
                // End of a dot sequence
                // If we had a sequence of dots, add (length - 1) to count
                // e.g., "..." (3 dots) has 2 pairs.
                if (consecutiveDots > 1) {
                    count += (consecutiveDots - 1);
                }
                consecutiveDots = 0;
            }
        }
        // Handle case where the sequence ends with dots
        if (consecutiveDots > 1) {
            count += (consecutiveDots - 1);
        }
        return count;
    }

    /**
     * Helper method to update the state at a specific index and adjust the pair count.
     * 
     * @param state The current state array
     * @param index The 1-based index to update
     * @param newChar The new character to place
     * @param currentCount The current count of pairs
     * @return The updated count of pairs
     */
    private static int updateState(char[] state, int index, char newChar, int currentCount) {
        char oldChar = state[index];

        // If the character is already what we want to set, no change is needed
        if (oldChar == newChar) {
            return currentCount;
        }

        // Check how many neighbors are currently dots.
        // The padding at 0 and n+1 ensures we don't access invalid memory
        // and 'a' is not a dot, so it won't incorrectly count as a pair.
        int neighborsWithDots = 0;
        if (state[index - 1] == '.') {
            neighborsWithDots++;
        }
        if (state[index + 1] == '.') {
            neighborsWithDots++;
        }

        if (oldChar == '.' && newChar != '.') {
            // Case: Turning a dot OFF (removing a dot)
            // We break any pairs formed with adjacent dots.
            state[index] = newChar;
            currentCount -= neighborsWithDots;
        } else if (oldChar != '.' && newChar == '.') {
            // Case: Turning a dot ON (adding a dot)
            // We form new pairs with adjacent dots.
            state[index] = '.';
            currentCount += neighborsWithDots;
        }

        return currentCount;
    }
}

