public class Main {
    public static void main(String[] args) {
        FastScanner sc = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out);

        int n = sc.nextInt();
        int m = sc.nextInt();
        char[] arr = sc.next().toCharArray();

        // Count initial adjacent dot pairs
        int ans = 0;
        for (int i = 0; i < n - 1; i++) {
            if (arr[i] == '.' && arr[i + 1] == '.') {
                ans++;
            }
        }

        // Process queries
        for (int j = 0; j < m; j++) {
            int x = sc.nextInt() - 1; // Convert 1-based to 0-based index
            char c = sc.next().charAt(0);

            // Check neighbors before update
            boolean leftIsDot = (x > 0 && arr[x - 1] == '.');
            boolean rightIsDot = (x < n - 1 && arr[x + 1] == '.');

            if (arr[x] == '.' && c != '.') {
                // Removing a dot: lose adjacent pairs with existing dot neighbors
                ans -= (leftIsDot ? 1 : 0) + (rightIsDot ? 1 : 0);
            } else if (arr[x] != '.' && c == '.') {
                // Adding a dot: gain adjacent pairs with existing dot neighbors
                ans += (leftIsDot ? 1 : 0) + (rightIsDot ? 1 : 0);
            }

            arr[x] = c;
            out.println(ans);
        }

        out.flush();
    }

    /**
     * Efficient input reader for fast I/O operations.
     */
    static class FastScanner {
