import java.util.Scanner;

public class Codechef {
    public static void main(String[] args) {
        // Initialize Scanner for input
        Scanner sc = new Scanner(System.in);

        // Safety check for input availability
        if (!sc.hasNextInt()) {
            return;
        }

        // Read string length and number of queries
        int stringLength = sc.nextInt();
        int queryCount = sc.nextInt();

        // Read the initial string
        String inputString = sc.next();
        char[] characters = inputString.toCharArray();

        // Calculate initial number of adjacent dot pairs
        int adjacentDotPairs = countAdjacentPairs(characters);

        // Use StringBuilder for efficient output concatenation
        StringBuilder output = new StringBuilder();

        // Process each query
        for (int i = 0; i < queryCount; i++) {
            int targetIndex = sc.nextInt();
            String charStr = sc.next();
            char newChar = charStr.charAt(0);

            // Adjust 1-based index from input to 0-based index for array access
            targetIndex--;

            // Update the pair count based on the change
            adjacentDotPairs = updatePairCount(characters, targetIndex, newChar, adjacentDotPairs);

            // Append result to output buffer
            output.append(adjacentDotPairs).append('\n');
        }

        // Print all results at once
        System.out.print(output);

        // Note: Closing System.in is generally not recommended in competitive programming 
        // environments, but included here for strict resource management in standard Java.
        // sc.close(); 
    }

    /**
     * Counts the number of adjacent pairs of dots in the character array.
     * Time Complexity: O(n)
     */
    private static int countAdjacentPairs(char[] chars) {
        int count = 0;
        // Iterate through the array up to the second to last element
        for (int i = 0; i < chars.length - 1; i++) {
            if (chars[i] == '.' && chars[i + 1] == '.') {
                count++;
            }
        }
        return count;
    }

    /**
     * Updates the pair count when a character at a specific index is changed.
     * Time Complexity: O(1)
     * 
     * @param chars The character array representing the string.
     * @param index The index of the character to update.
     * @param newChar The new character value.
     * @param currentCount The current count of adjacent dot pairs.
     * @return The updated count of adjacent dot pairs.
     */
    private static int updatePairCount(char[] chars, int index, char newChar, int currentCount) {
        char oldChar = chars[index];

        // If the character is not changing, the count remains the same
        if (oldChar == newChar) {
            return currentCount;
        }

        // Determine the nature of the change
        boolean isAddingDot = (newChar == '.');
        boolean isRemovingDot = (oldChar == '.');

        // Check Left Neighbor
        if (index > 0) {
            if (chars[index - 1] == '.') {
                if (isAddingDot) {
                    currentCount++;
                } else if (isRemovingDot) {
                    currentCount--;
                }
            }
        }

        // Check Right Neighbor
        if (index < chars.length - 1) {
            if (chars[index + 1] == '.') {
                if (isAddingDot) {
                    currentCount++;
                } else if (isRemovingDot) {
                    currentCount--;
                }
            }
        }

        // Apply the change to the array
        chars[index] = newChar;

        return currentCount;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

public class Replacement {

    public static void main(String[] args) throws IOException {
        // Use try-with-resources to ensure automatic resource cleanup
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
             PrintWriter writer = new PrintWriter(System.out)) {

            // Read n (length) and m (number of queries)
            String line = reader.readLine();
            if (line == null) return;

            StringTokenizer st = new StringTokenizer(line);
            int length = Integer.parseInt(st.nextToken());
            int queryCount = Integer.parseInt(st.nextToken());

            // Read the character sequence
            char[] sequence = reader.readLine().toCharArray();

            // Calculate the initial score based on consecutive dots
            int currentScore = calculateInitialScore(sequence);

            // Process each query
            for (int i = 0; i < queryCount; i++) {
                line = reader.readLine();
                if (line == null) break;

                st = new StringTokenizer(line);
                int index = Integer.parseInt(st.nextToken()) - 1; // Convert 1-based index to 0-based
                char newChar = st.nextToken().charAt(0);

                // Update the sequence and calculate the new score
                currentScore = updateSequenceAndScore(sequence, index, newChar, currentScore);

                // Output the result for the current state
                writer.println(currentScore);
            }

            // Ensure all output is written
            writer.flush();
        }
    }

    /**
     * Calculates the initial score of the sequence.
     * The score is defined as the number of adjacent pairs of dots ('.').
     * For a block of k consecutive dots, it contributes (k-1) to the score.
     */
    private static int calculateInitialScore(char[] sequence) {
        int score = 0;
        int consecutiveDots = 0;

        for (char c : sequence) {
            if (c == '.') {
                consecutiveDots++;
            } else {
                if (consecutiveDots > 0) {
                    score += (consecutiveDots - 1);
                }
                consecutiveDots = 0;
            }
        }
        // Handle trailing dots if the sequence ends with them
        if (consecutiveDots > 0) {
            score += (consecutiveDots - 1);
        }
        return score;
    }

    /**
     * Updates the character at the specified index and adjusts the score.
     * 
     * @param sequence The array of characters
     * @param index The 0-based index to update
     * @param newChar The character to place at the index
     * @param currentScore The current score before the update
     * @return The updated score
     */
    private static int updateSequenceAndScore(char[] sequence, int index, char newChar, int currentScore) {
        char oldChar = sequence[index];

        // If the character is not changing, the score remains the same
        if (oldChar == newChar) {
            return currentScore;
        }

        // Check neighbors to determine how the score changes
        // A neighbor contributes to the score if it is a dot
        boolean leftNeighborIsDot = (index > 0 && sequence[index - 1] == '.');
        boolean rightNeighborIsDot = (index < sequence.length - 1 && sequence[index + 1] == '.');

        if (newChar == '.') {
            // We are placing a dot.
            // We gain a connection (score +1) for each existing adjacent dot neighbor.
            if (leftNeighborIsDot) currentScore++;
            if (rightNeighborIsDot) currentScore++;
        } else {
            // We are removing a dot (replacing with non-dot).
            // We lose a connection (score -1) for each existing adjacent dot neighbor.
            if (leftNeighborIsDot) currentScore--;
            if (rightNeighborIsDot) currentScore--;
        }

        // Apply the change to the array
        sequence[index] = newChar;

        return currentScore;
    }
}

