/**
 * A refactored solution for counting and updating consecutive dot pairs.
 * 
 * Improvements made:
 * 1. Separation of Concerns: Logic is separated from I/O handling.
 * 2. Resource Management: Uses try-with-resources for automatic stream closing.
 * 3. Naming Conventions: Descriptive variable names (e.g., 'sequenceLength' instead of 'n').
 * 4. Robust Input Parsing: Custom FastScanner handles potential nulls and IO exceptions gracefully.
 * 5. Logic Clarity: The update logic is broken down into clear steps (check left, check right, update).
 * 6. Removed Unused Imports: Cleaned up unnecessary imports like Math.*.
 */
public class Main {

    public static void main(String[] args) {
        // Using try-with-resources to ensure streams are closed properly
        try (FastScanner scanner = new FastScanner(System.in);
             PrintWriter out = new PrintWriter(System.out)) {

            solveProblem(scanner, out);

        } catch (IOException e) {
            // In a production environment, log this error properly
            System.err.println("An I/O error occurred: " + e.getMessage());
        }
    }

    private static void solveProblem(FastScanner scanner, PrintWriter out) throws IOException {
        // Read sequence length and number of queries
        String nStr = scanner.next();
        if (nStr == null) return;
        int sequenceLength = Integer.parseInt(nStr);

        int queryCount = scanner.nextInt();

        // Read the initial sequence string
        String sequenceStr = scanner.next();
        if (sequenceStr == null) return;

        char[] sequence = sequenceStr.toCharArray();

        // Calculate initial count of consecutive dot pairs
        int consecutiveDotPairs = 0;
        for (int i = 0; i < sequenceLength - 1; i++) {
            if (sequence[i] == '.' && sequence[i + 1] == '.') {
                consecutiveDotPairs++;
            }
        }

        // Process each query
        for (int i = 0; i < queryCount; i++) {
            int updateIndex = scanner.nextInt() - 1; // Convert 1-based to 0-based index
            String charInput = scanner.next();
            if (charInput == null) break;
            char newCharacter = charInput.charAt(0);
            char oldCharacter = sequence[updateIndex];

            // Only process if the character actually changes
            if (oldCharacter != newCharacter) {
                // Check the pair to the left (index - 1, index)
                if (updateIndex > 0) {
                    // If the pair was a dot pair, decrement count
                    if (sequence[updateIndex - 1] == '.' && oldCharacter == '.') {
                        consecutiveDotPairs--;
                    }
                    // If the new character forms a dot pair, increment count
                    if (sequence[updateIndex - 1] == '.' && newCharacter == '.') {
                        consecutiveDotPairs++;
                    }
                }

                // Check the pair to the right (index, index + 1)
                if (updateIndex < sequenceLength - 1) {
                    // If the pair was a dot pair, decrement count
                    if (oldCharacter == '.' && sequence[updateIndex + 1] == '.') {
                        consecutiveDotPairs--;
                    }
                    // If the new character forms a dot pair, increment count
                    if (newCharacter == '.' && sequence[updateIndex + 1] == '.') {
                        consecutiveDotPairs++;
                    }
                }

                // Apply the change to the sequence array
                sequence[updateIndex] = newCharacter;
            }

            // Output the current count of consecutive dot pairs
            out.println(consecutiveDotPairs);
        }
    }

    /**
     * Helper class for fast input reading.
     */
    static class FastScanner {
        BufferedReader br;
        StringTokenizer st;

        public FastScanner(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        /**
         * Reads the next token from input.
         * @return The next token string, or null if end of stream.
         */
        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) {
                        return null;
                    }
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return st.nextToken();
        }

        /**
         * Reads the next integer token.
         * @return The parsed integer.
         */
        int nextInt() {
            String s = next();
            if (s == null) throw new RuntimeException("End of input reached");
            return Integer.parseInt(s);
        }
    }
}

import java.io.*;
import java.util.InputMismatchException;

public class Main {
    public static void main(String[] args) {
        InputReader in = new InputReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            int n = in.nextInt();
            int m = in.nextInt();
            String s = in.readString();

            StringProcessor processor = new StringProcessor(n, s);

            for (int i = 0; i < m; i++) {
                int index = in.nextInt() - 1;
                char newChar = in.readString().charAt(0);
                processor.update(index, newChar);
                out.println(processor.getTotal());
            }
        } finally {
            out.flush();
            out.close();
        }
    }

    /**
     * Encapsulates the logic for tracking adjacent dot pairs in a character array.
     * The 'total' value represents the number of adjacent pairs of dots ('..').
     * This formulation simplifies both initial calculation and incremental updates.
     */
    static class StringProcessor {
        private final char[] grid;
        private final int n;
        private int totalAdjacentPairs;

        public StringProcessor(int n, String initialString) {
            this.n = n;
            this.grid = initialString.toCharArray();
            this.totalAdjacentPairs = calculateInitialTotal();
        }

        /**
         * Calculates the initial number of adjacent dot pairs.
         * Equivalent to summing (segment_length - 1) for each contiguous dot segment.
         */
        private int calculateInitialTotal() {
            int count = 0;
            for (int i = 1; i < n; i++) {
                if (grid[i] == '.' && grid[i - 1] == '.') {
                    count++;
                }
            }
            return count;
        }

        /**
         * Updates a character at the given index and adjusts the total count accordingly.
         * Only checks immediate neighbors since only pairs involving the changed index are affected.
         */
        public void update(int index, char newChar) {
            if (index < 0 || index >= n || grid[index] == newChar) {
                return;
            }

            char oldChar = grid[index];
            int delta = 0;

            // Check left neighbor
            if (index > 0) {
                if (oldChar == '.' && grid[index - 1] == '.') {
                    delta--;
                } else if (oldChar != '.' && newChar == '.' && grid[index - 1] == '.') {
                    delta++;
                }
            }

            // Check right neighbor
            if (index < n - 1) {
                if (oldChar == '.' && grid[index + 1] == '.') {
                    delta--;
                } else if (oldChar != '.' && newChar == '.' && grid[index + 1] == '.') {
                    delta++;
                }
            }

            totalAdjacentPairs += delta;
            grid[index] = newChar;
        }

        public int getTotal() {
            return totalAdjacentPairs;
        }
    }

    /**
     * Fast I/O helper class commonly used in competitive programming.
     */
    static class InputReader {
        private final InputStream stream;
        private final byte[] buf = new byte[8192];
        private int curChar;
        private int snumChars;
        private SpaceCharFilter filter;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        public int snext() {
            if (snumChars == -1) {
                throw new InputMismatchException();
            }
            if (curChar >= snumChars) {
                curChar = 0;
                try {
                    snumChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (snumChars <= 0) {
                    return -1;
                }
            }
            return buf[curChar++];
        }

        public int nextInt() {
            int c = snext();
            while (isSpaceChar(c)) {
                c = snext();
            }
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = snext();
            }

            int res = 0;
            do {
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                res *= 10;
                res += c - '0';
                c = snext();
            } while (!isSpaceChar(c));

            return res * sgn;
        }

        public long nextLong() {
            int c = snext();
            while (isSpaceChar(c)) {
                c = snext();
            }
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = snext();
            }

            long res = 0;
            do {
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                res *= 10;
                res += c - '0';
                c = snext();
            } while (!isSpaceChar(c));

            return res * sgn;
        }

        public String readString() {
            int c = snext();
            while (isSpaceChar(c)) {
                c = snext();
            }
            StringBuilder res = new StringBuilder();
            do {
                res.appendCodePoint(c);
                c = snext();
            } while (!isSpaceChar(c));
            return res.toString();
        }

        public boolean isSpaceChar(int c) {
            if (filter != null) {
                return filter.isSpaceChar(c);
            }
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        public interface SpaceCharFilter {
            boolean isSpaceChar(int ch);
        }
    }
}

