    /**
     * Counts the number of adjacent dot pairs in the initial string.
     * Assumes padding at indices 0 and n+1.
     */
    private static int countInitialPairs(char[] grid, int n) {
        int count = 0;
        for (int i = 1; i < n; i++) {
            if (grid[i] == '.' && grid[i + 1] == '.') {
                count++;
            }
        }
        return count;
    }

    /**
     * Updates the grid with a new character at the given index and adjusts
     * the adjacent dot pair count accordingly.
     */
    private static int applyUpdate(char[] grid, int index, char newChar, int currentCount) {
        char oldChar = grid[index];
        if (oldChar == newChar) {
            return currentCount;
        }

        // If changing FROM a dot TO a non-dot, we lose adjacent dot pairs
        if (oldChar == '.' && newChar != '.') {
            if (grid[index - 1] == '.') currentCount--;
            if (grid[index + 1] == '.') currentCount--;
        }
        // If changing FROM a non-dot TO a dot, we gain adjacent dot pairs
        else if (oldChar != '.' && newChar == '.') {
            if (grid[index - 1] == '.') currentCount++;
            if (grid[index + 1] == '.') currentCount++;
        }

        grid[index] = newChar;
        return currentCount;
    }
}

