/**
 * Refactored solution for CF570C (Palindrome Reconstruction / String Manipulation).
 * 
 * Improvements made:
 * 1. Variable Naming: Replaced cryptic names (a, ctr, ans, n, m) with descriptive ones.
 * 2. Modularity: Extracted logic into helper methods (calculateInitialPairs, updatePairs).
 * 3. Encapsulation: Wrapped input reading in a FastReader class.
 * 4. Readability: Added comments and structured the code for better flow.
 * 5. Safety: Added boundary checks in update logic (though sentinels make them redundant, 
 *    they make the code more robust and self-documenting).
 */
public class CF570C {

    public static void main(String[] args) throws IOException {
        // Use a dedicated FastReader class for efficient input parsing
        FastReader in = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            // Read dimensions: n (string length) and m (number of queries)
            int n = in.nextInt();
            int m = in.nextInt();

            // Initialize the character array with padding (sentinels)
            // Size is n + 2 to accommodate 1-based indexing and boundary sentinels.
            // Index 0 and n+1 are set to '!' which is not '.', simplifying boundary checks.
            char[] characters = new char[n + 2];
            characters[0] = '!';
            characters[n + 1] = '!';

            // Read the initial string and populate the array (1-based indexing for content)
            String s = in.next();
            for (int i = 0; i < n; i++) {
                characters[i + 1] = s.charAt(i);
            }

            // Calculate the initial number of adjacent dot pairs ("..")
            long pairCount = calculateInitialPairs(characters);

            // Process each query
            for (int i = 0; i < m; i++) {
                int index = in.nextInt(); // 1-based index
                char newChar = in.next().charAt(0);

                // Update the pair count and the array
                pairCount = updatePairs(characters, index, newChar, pairCount);

                // Output the current count
                out.println(pairCount);
            }
        } finally {
            // Ensure output is flushed and closed
            out.flush();
            out.close();
        }
    }

    /**
     * Calculates the total number of adjacent dot pairs in the array.
     * A pair is defined as two consecutive '.' characters.
     * For a block of k consecutive dots, there are k-1 pairs.
     */
    private static long calculateInitialPairs(char[] characters) {
        long count = 0;
        int consecutiveDots = 0;

        for (char c : characters) {
            if (c == '.') {
                consecutiveDots++;
            } else {
                // If we encountered a non-dot, the sequence of dots ends.
                // Add (length - 1) to the count if length > 1.
                // Note: Math.max(consecutiveDots - 1, 0) logic is simplified here.
                if (consecutiveDots > 1) {
                    count += (consecutiveDots - 1);
                }
                consecutiveDots = 0;
            }
        }
        // Note: The loop covers the entire array including the sentinel at the end,
        // so the final block of dots is processed inside the loop.

        return count;
    }

    /**
     * Updates the pair count based on a character modification at a specific index.
     * 
     * @param characters The character array
     * @param index The 1-based index to modify
     * @param newChar The new character value
     * @param currentPairs The current count of pairs
     * @return The updated pair count
     */
    private static long updatePairs(char[] characters, int index, char newChar, long currentPairs) {
        char oldChar = characters[index];

        // Only process if the character actually changes
        if (oldChar != newChar) {
            if (newChar == '.' && oldChar != '.') {
                // Case 1: Inserting a dot
                // Check if it forms a pair with the left neighbor
                if (index > 0 && characters[index - 1] == '.') {
                    currentPairs++;
                }
                // Check if it forms a pair with the right neighbor
                if (index < characters.length - 1 && characters[index + 1] == '.') {
                    currentPairs++;
                }
            } else if (newChar != '.' && oldChar == '.') {
                // Case 2: Removing a dot
                // Check if it breaks a pair with the left neighbor
                if (index > 0 && characters[index - 1] == '.') {
                    currentPairs--;
                }
                // Check if it breaks a pair with the right neighbor
                if (index < characters.length - 1 && characters[index + 1] == '.') {
                    currentPairs--;
                }
            }
            // Update the array with the new character
            characters[index] = newChar;
        }

        return currentPairs;
    }

    /**
     * Helper class for fast input reading.
     */
    public static class FastReader {
        BufferedReader reader;
        StringTokenizer tokenizer;

        public FastReader(InputStream in) {
            reader = new BufferedReader(new InputStreamReader(in));
            tokenizer = new StringTokenizer("");
        }

        public String next() throws IOException {
            while (!tokenizer.hasMoreTokens()) {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            String s = next();
            if (s == null) throw new IOException("Unexpected end of input");
            return Integer.parseInt(s);
        }

        public long nextLong() throws IOException {
            String s = next();
            if (s == null) throw new IOException("Unexpected end of input");
            return Long.parseLong(s);
        }
    }
}

import java.util.Scanner;
import java.io.PrintWriter;

public class DotPairsCounter {

    public static void main(String[] args) {
        // Initialize input and output streams
        Scanner scanner = new Scanner(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        // Read the length of the sequence and the number of queries
        if (!scanner.hasNextInt()) {
            writer.flush();
            return;
        }
        int length = scanner.nextInt();
        int queryCount = scanner.nextInt();

        // Read the sequence string and convert to char array for mutability
        String sequenceStr = scanner.next();
        char[] sequence = sequenceStr.toCharArray();

        // Calculate the initial number of adjacent dot pairs ("..")
        int pairCount = calculateInitialPairs(sequence, length);

        // Process each update query
        for (int i = 0; i < queryCount; i++) {
            int index = scanner.nextInt() - 1; // Convert 1-based index to 0-based
            char newChar = scanner.next().charAt(0);

            // Update the pair count and the sequence
            pairCount = updatePairs(sequence, index, newChar, pairCount, length);

            // Output the current count of pairs
            writer.println(pairCount);
        }

        // Flush the output buffer to ensure all data is written
        writer.flush();
        scanner.close();
    }

    /**
     * Calculates the initial number of adjacent dot pairs ("..") in the array.
     *
     * @param chars The character array representing the sequence.
     * @param n     The length of the sequence.
     * @return      The count of ".." pairs.
     */
    private static int calculateInitialPairs(char[] chars, int n) {
        int count = 0;
        for (int i = 0; i < n - 1; i++) {
            if (chars[i] == '.' && chars[i + 1] == '.') {
                count++;
            }
        }
        return count;
    }

    /**
     * Updates the pair count based on a character change at a specific index.
     * This method runs in O(1) time complexity by only checking neighbors.
     *
     * @param chars          The character array representing the sequence.
     * @param index          The index being updated.
     * @param newChar        The new character value.
     * @param currentPairs   The current count of pairs before update.
     * @param n              The length of the sequence.
     * @return               The updated pair count.
     */
    private static int updatePairs(char[] chars, int index, char newChar, int currentPairs, int n) {
        // If the character isn't changing, the pair count remains the same
        if (chars[index] == newChar) {
            return currentPairs;
        }

        int neighborDotCount = 0;

        // Check left neighbor
        if (index > 0 && chars[index - 1] == '.') {
            neighborDotCount++;
        }

        // Check right neighbor
        if (index < n - 1 && chars[index + 1] == '.') {
            neighborDotCount++;
        }

        // Adjust pair count based on the state transition
        if (chars[index] == '.' && newChar != '.') {
            // Removing a dot: breaks pairs formed with adjacent dots
            currentPairs -= neighborDotCount;
        } else if (chars[index] != '.' && newChar == '.') {
            // Adding a dot: creates pairs with adjacent dots
            currentPairs += neighborDotCount;
        }

        // Apply the change to the array
        chars[index] = newChar;

        return currentPairs;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.OutputStream;
import java.io.PrintWriter;
import java.util.StringTokenizer;

/**
 * Refactored solution for counting consecutive dots ("..") in a string
 * with point updates.
 * 
 * Improvements made:
 * 1. Renamed class and methods for clarity.
 * 2. Replaced StringBuffer with char[] for better performance and mutability.
 * 3. Refactored logic to calculate score changes in O(1) per query.
 * 4. Removed unused imports and cleaned up exception handling.
 */
public class ConsecutiveDotsSolver {

    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        solve(in, out);
        out.close();
    }

    public static void solve(InputReader in, PrintWriter out) {
        int n = in.nextInt();
        int m = in.nextInt();

        // Read the initial string
        String initialString = in.next();

        // Use char array for efficient random access and mutation
        char[] text = initialString.toCharArray();

        // Calculate initial score (count of ".." pairs)
        int currentScore = calculateConsecutiveDots(text);

        for (int i = 0; i < m; ++i) {
            int pos = in.nextInt(); // Input is 1-based
            char newChar = in.next().charAt(0);

            // Apply change and get the new score
            // pos - 1 converts to 0-based index
            currentScore = applyChange(text, pos - 1, newChar, currentScore);

            out.println(currentScore);
        }
    }

    /**
     * Calculates the number of adjacent dot pairs ("..") in the character array.
     * Time Complexity: O(N)
     */
    public static int calculateConsecutiveDots(char[] text) {
        int count = 0;
        // Iterate up to length - 1 to safely access i + 1
        for (int i = 0; i < text.length - 1; ++i) {
            if (text[i] == '.' && text[i + 1] == '.') {
                count++;
            }
        }
        return count;
    }

    /**
     * Updates the character at the specified index and recalculates the score.
     * Instead of recalculating the whole string, it adjusts the score based on
     * the neighbors of the changed position.
     * Time Complexity: O(1)
     * 
     * @param text The character array representing the string
     * @param index The 0-based index to update
     * @param newChar The new character to place at the index
     * @param currentScore The current total score before update
     * @return The new total score after update
     */
    public static int applyChange(char[] text, int index, char newChar, int currentScore) {
        // If the character is not changing, the score remains the same
        if (text[index] == newChar) {
            return currentScore;
        }

        // 1. Remove contributions of the old character to adjacent pairs
        // Check left neighbor (index - 1)
        if (index > 0) {
            if (text[index - 1] == '.' && text[index] == '.') {
                currentScore--;
            }
        }
        // Check right neighbor (index + 1)
        if (index < text.length - 1) {
            if (text[index] == '.' && text[index + 1] == '.') {
                currentScore--;
            }
        }

        // 2. Update the character
        text[index] = newChar;

        // 3. Add contributions of the new character to adjacent pairs
        // Check left neighbor (index - 1)
        if (index > 0) {
            if (text[index - 1] == '.' && text[index] == '.') {
                currentScore++;
            }
        }
        // Check right neighbor (index + 1)
        if (index < text.length - 1) {
            if (text[index] == '.' && text[index + 1] == '.') {
                currentScore++;
            }
        }

        return currentScore;
    }

    /**
     * Fast Input Reader for competitive programming style I/O.
     */
    static class InputReader {
        public BufferedReader reader;
        public StringTokenizer tokenizer;

        public InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) {
                        return null; // Handle End of File gracefully
                    }
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            String s = next();
            if (s == null) throw new RuntimeException("Unexpected end of input");
            return Integer.parseInt(s);
        }

        // Helper to read a single character token
        public char nextChar() {
            return next().charAt(0);
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

/**
 * Refactored solution for tracking dot counts and contiguous '.' segments.
 * 
 * Key Improvements:
 * - Removed unused classes (Tree1, Pair) and methods (round, gcd)
 * - Fixed PrintWriter shadowing and resource management
 * - Unified boundary logic to eliminate heavy duplication
 * - Replaced cryptic variable names with descriptive identifiers
 * - Added comprehensive documentation and comments
 */
public class Main {

    public static void main(String[] args) throws IOException {
        FastScanner scanner = new FastScanner(new InputStreamReader(System.in));
        PrintWriter out = new PrintWriter(System.out);

        try {
            int n = scanner.nextInt();
            int m = scanner.nextInt();

            // Use next() instead of nextLine() to safely skip the trailing newline after m
            char[] chars = scanner.next().toCharArray();

            int dotCount = 0;
            int segmentCount = 0;
            boolean inSegment = false;

            // Initial calculation: count total '.' characters and contiguous '.' segments
            for (char c : chars) {
                if (c == '.') {
                    dotCount++;
                    inSegment = true;
                } else if (inSegment) {
                    segmentCount++;
                    inSegment = false;
                }
            }
            // Handle case where the string ends with a '.'
            if (n > 0 && chars[n - 1] == '.') {
                segmentCount++;
            }

            // Process each query
            for (int i = 0; i < m; i++) {
                int q = scanner.nextInt();
                char newChar = scanner.next().charAt(0);
                int idx = q - 1; // Convert 1-based query index to 0-based array index
                char oldChar = chars[idx];

                if (oldChar == newChar) {
                    // No change in the string
                    out.println(dotCount - segmentCount);
                } else if (newChar == '.') {
                    // Adding a dot
                    dotCount++;
                    boolean leftHasDot = idx > 0 && chars[idx - 1] == '.';
                    boolean rightHasDot = idx < n - 1 && chars[idx + 1] == '.';

                    if (leftHasDot && rightHasDot) {
                        segmentCount--; // Merging two existing segments into one
                    } else if (!leftHasDot && !rightHasDot) {
                        segmentCount++; // Starting a new isolated segment
                    }
                    // If exactly one neighbor is a dot, the segment count remains unchanged
                } else {
                    // Removing a dot
                    dotCount--;
                    boolean leftHasDot = idx > 0 && chars[idx - 1] == '.';
                    boolean rightHasDot = idx < n - 1 && chars[idx + 1] == '.';

                    if (leftHasDot && rightHasDot) {
                        segmentCount++; // Splitting one segment into two
                    } else if (!leftHasDot && !rightHasDot) {
                        segmentCount--; // Removing an isolated segment entirely
                    }
                    // If exactly one neighbor is a dot, the segment count remains unchanged
                }

                chars[idx] = newChar;
                out.println(dotCount - segmentCount);
            }
        } finally {
            out.flush();
            out.close();
        }
    }

    /**
     * FastScanner for efficient input reading.
     * Optimized for competitive programming and large I/O operations.
     */
    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner(InputStreamReader isr) {
            br = new BufferedReader(isr);
        }

        /**
         * Reads the next token from input.
         * @return Next string token, or null if end of stream
         */
        public String next() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) {
                    return null;
                }
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

        public int nextInt() throws IOException {
            String token = next();
            return token == null ? 0 : Integer.parseInt(token);
        }

        public long nextLong() throws IOException {
            String token = next();
            return token == null ? 0L : Long.parseLong(token);
        }

        public double nextDouble() throws IOException {
            String token = next();
            return token == null ? 0.0 : Double.parseDouble(token);
        }

        public String nextLine() throws IOException {
            String line = br.readLine();
            return (line == null) ? "" : line;
        }

        public char nextChar() throws IOException {
            return (char) br.read();
        }
    }
}

import java.io.InputStream;
import java.io.PrintWriter;
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        PrintWriter out = new PrintWriter(System.out);
        TaskA solver = new TaskA();
        solver.solve(new Scanner(inputStream), out);
        out.flush(); // Ensure all buffered output is written
        out.close();
    }

    static class TaskA {
        public void solve(Scanner in, PrintWriter out) {
            int n = in.nextInt();
            int m = in.nextInt();

            // 1-based indexing with padding at 0 and n+1 to simplify boundary checks
            char[] s = new char[n + 2];
            System.arraycopy(in.next().toCharArray(), 0, s, 1, n);

            int totalDots = 0;
            int dotSegments = 0;

            // Initialize dot count and contiguous segment count
            for (int i = 1; i <= n; i++) {
                if (s[i] == '.') {
                    totalDots++;
                    // A new segment starts if it's the first character or the previous one isn't a dot
                    if (i == 1 || s[i - 1] != '.') {
                        dotSegments++;
                    }
                }
            }

            for (int i = 0; i < m; i++) {
                int x = in.nextInt();
                char newChar = in.next().charAt(0);

                // If the character doesn't change, just output the current result
                if (newChar == s[x]) {
                    out.println(totalDots - dotSegments);
                    continue;
                }

                boolean wasDot = (s[x] == '.');
                boolean isDot = (newChar == '.');

                s[x] = newChar;

                if (isDot) {
                    totalDots++;
                    boolean leftDot = (x > 0 && s[x - 1] == '.');
                    boolean rightDot = (x < n + 1 && s[x + 1] == '.');

                    if (!leftDot && !rightDot) {
                        dotSegments++; // Creates a new isolated segment
                    } else if (leftDot && rightDot) {
                        dotSegments--; // Merges two existing segments
                    }
                } else {
                    totalDots--;
                    boolean leftDot = (x > 0 && s[x - 1] == '.');
                    boolean rightDot = (x < n + 1 && s[x + 1] == '.');

                    if (!leftDot && !rightDot) {
                        dotSegments--; // Removes an isolated segment
                    } else if (leftDot && rightDot) {
                        dotSegments++; // Splits an existing segment into two
                    }
                }

                out.println(totalDots - dotSegments);
            }
        }
    }

    /**
     * Utility class for common mathematical and algorithmic operations.
     * Consolidated from scattered methods at the bottom of the original file.
     */
    static class MathUtils {
        /** Computes the Greatest Common Divisor using the iterative Euclidean algorithm. */
        public static long gcd(long a, long b) {
            while (b != 0) {
                long temp = b;
                b = a % b;
                a = temp;
            }
            return a;
        }

        /** Computes (base^exp) % mod efficiently using binary exponentiation. */
        public static long modPow(long base, long exp, long mod) {
            long result = 1;
            base %= mod;
            while (exp > 0) {
                if ((exp & 1) == 1) {
                    result = (result * base) % mod;
                }
                base = (base * base) % mod;
                exp >>= 1;
            }
            return result;
        }

        /** Counts the number of inversions in an array using merge sort. */
        public static long countInversions(int[] arr) {
            int n = arr.length;
            int[] temp = new int[n];
            return mergeSort(arr, temp, 0, n - 1);
        }

        private static long mergeSort(int[] arr, int[] temp, int left, int right) {
            long invCount = 0;
            if (left < right) {
                int mid = left + (right - left) / 2;
                invCount += mergeSort(arr, temp, left, mid);
                invCount += mergeSort(arr, temp, mid + 1, right);
                invCount += merge(arr, temp, left, mid + 1, right);
            }
            return invCount;
        }

        private static long merge(int[] arr, int[] temp, int left, int mid, int right) {
            long invCount = 0;
            int i = left;
            int j = mid;
            int k = left;

            while (i <= mid - 1 && j <= right) {
                if (arr[i] <= arr[j]) {
                    temp[k++] = arr[i++];
                } else {
                    temp[k++] = arr[j++];
                    invCount += (mid - i);
                }
            }

            while (i <= mid - 1) {
                temp[k++] = arr[i++];
            }
            while (j <= right) {
                temp[k++] = arr[j++];
            }

            for (i = left; i <= right; i++) {
                arr[i] = temp[i];
            }
            return invCount;
        }
    }
}

import java.util.Scanner;

/**
 * Handles queries on a string to maintain a count of adjacent dot ('.') pairs
 * after point updates. Optimized for O(1) per query and improved maintainability.
 */
public class DottedStringQueries {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        // Read input dimensions
        if (!scanner.hasNextInt()) {
            scanner.close();
            return;
        }
        int stringLength = scanner.nextInt();
        int queryCount = scanner.nextInt();
        String str = scanner.next();

        // Convert to mutable character array for efficient updates
        char[] chars = str.toCharArray();

        // Calculate initial number of adjacent dot pairs
        long currentTotal = calculateAdjacentDotPairs(chars);

        // Buffer for output to minimize I/O operations
        StringBuilder output = new StringBuilder();

        // Process each query
        for (int i = 0; i < queryCount; i++) {
            int pos = scanner.nextInt();
            char newChar = scanner.next().charAt(0);

            // Convert 1-based index to 0-based
            int index = pos - 1;

            // Update the total and character array in O(1)
            currentTotal = updateTotal(chars, index, newChar, currentTotal);

            // Append result
            output.append(currentTotal).append('\n');
        }

        // Print all results at once
        System.out.print(output);
        scanner.close();
    }

    /**
     * Calculates the initial number of adjacent dot pairs in the string.
     * Two consecutive dots form one pair.
     * 
     * @param chars The character array representing the string
     * @return The total count of adjacent dot pairs
     */
    private static long calculateAdjacentDotPairs(char[] chars) {
        long pairs = 0;
        for (int i = 0; i < chars.length - 1; i++) {
            if (chars[i] == '.' && chars[i + 1] == '.') {
                pairs++;
            }
        }
        return pairs;
    }

    /**
     * Updates the adjacent dot pair count when a character at a specific position changes.
     * Only checks immediate neighbors, making each update O(1).
     * 
     * @param chars The character array
     * @param pos   The 0-based index to update
     * @param newChar The new character to place at pos
     * @param currentTotal The current count of adjacent dot pairs
     * @return The updated count of adjacent dot pairs
     */
    private static long updateTotal(char[] chars, int pos, char newChar, long currentTotal) {
        // Boundary check
        if (pos < 0 || pos >= chars.length) {
            return currentTotal;
        }

        // No change if the character is already the same
        if (chars[pos] == newChar) {
            return currentTotal;
        }

        if (newChar == '.' && chars[pos] != '.') {
            // Changing a non-dot to a dot: can only create new pairs
            if (pos > 0 && chars[pos - 1] == '.') {
                currentTotal++;
            }
            if (pos < chars.length - 1 && chars[pos + 1] == '.') {
                currentTotal++;
            }
        } else if (newChar != '.' && chars[pos] == '.') {
            // Changing a dot to a non-dot: can only destroy existing pairs
            if (pos > 0 && chars[pos - 1] == '.') {
                currentTotal--;
            }
            if (pos < chars.length - 1 && chars[pos + 1] == '.') {
                currentTotal--;
            }
        }

        // Apply the change
        chars[pos] = newChar;
        return currentTotal;
    }
}

