             PrintWriter writer = new PrintWriter(new BufferedOutputStream(System.out))) {

            // Read string length and number of queries
            // Using trim() and \\s+ handles multiple spaces gracefully
            String[] header = reader.readLine().trim().split("\\s+");
            int stringLength = Integer.parseInt(header[0]);
            int queryCount = Integer.parseInt(header[1]);

            // Read the character string and convert to char array efficiently
            char[] charArray = reader.readLine().toCharArray();

            // Calculate initial count of adjacent dot pairs
            int adjacentDotPairs = 0;
            for (int i = 0; i < stringLength - 1; i++) {
                if (charArray[i] == '.' && charArray[i + 1] == '.') {
                    adjacentDotPairs++;
                }
            }

            // Process each query
            for (int i = 0; i < queryCount; i++) {
                String[] queryData = reader.readLine().trim().split("\\s+");
                int index = Integer.parseInt(queryData[0]) - 1; // Convert 1-based index to 0-based
                char newChar = queryData[1].charAt(0);
                char oldChar = charArray[index];

                // Only update if the character actually changes
                if (oldChar != newChar) {

                    // If we are removing a dot ('.' -> other), check neighbors
                    if (oldChar == '.') {
                        if (index > 0 && charArray[index - 1] == '.') {
                            adjacentDotPairs--;
                        }
                        if (index < stringLength - 1 && charArray[index + 1] == '.') {
                            adjacentDotPairs--;
                        }
                    }

                    // If we are adding a dot (other -> '.'), check neighbors
                    if (newChar == '.') {
                        if (index > 0 && charArray[index - 1] == '.') {
                            adjacentDotPairs++;
                        }
                        if (index < stringLength - 1 && charArray[index + 1] == '.') {
                            adjacentDotPairs++;
                        }
                    }

                    // Update the array with the new character
                    charArray[index] = newChar;
                }

                // Write the current pair count to output
                writer.println(adjacentDotPairs);
            }

            // PrintWriter is flushed when closed by try-with-resources
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

/**
 * A program to count adjacent pairs of '.' characters in a string
 * and update the count efficiently as characters are changed.
 */
public class StringPairCounter {

    private char[] str;
    private int pairCount;

    /**
     * Constructs the analyzer with the given string.
     * Calculates the initial number of adjacent dot pairs.
     *
     * @param input The input string
     */
    public StringPairCounter(String input) {
        this.str = input.toCharArray();
        this.pairCount = calculateInitialPairs();
    }

    /**
     * Calculates the initial count of adjacent '.' pairs.
     * A pair is defined as str[i] == '.' and str[i+1] == '.'.
     *
     * @return The number of pairs
     */
    private int calculateInitialPairs() {
        int count = 0;
        // Iterate up to length - 2 to safely access i+1
        for (int i = 0; i < str.length - 1; i++) {
            if (str[i] == '.' && str[i + 1] == '.') {
                count++;
            }
        }
        return count;
    }

    /**
     * Updates the character at the specified index and returns the new pair count.
     * 
     * Logic:
     * 1. Remove contribution of pairs involving the old character.
     * 2. Update the character.
     * 3. Add contribution of pairs involving the new character.
     *
     * @param index The 0-based index to update
     * @param newChar The new character to place at the index
     * @return The updated pair count
     */
    public int updateAndCount(int index, char newChar) {
        // 1. Remove old pairs formed by the character at 'index'

        // Check pair (index-1, index)
        if (index > 0 && str[index - 1] == '.' && str[index] == '.') {
            pairCount--;
        }

        // Check pair (index, index+1)
        if (index < str.length - 1 && str[index] == '.' && str[index + 1] == '.') {
            pairCount--;
        }

        // Update character
        str[index] = newChar;

        // 2. Add new pairs formed by the character at 'index'

        // Check pair (index-1, index)
        if (index > 0 && str[index - 1] == '.' && str[index] == '.') {
            pairCount++;
        }

        // Check pair (index, index+1)
        if (index < str.length - 1 && str[index] == '.' && str[index + 1] == '.') {
            pairCount++;
        }

        return pairCount;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));

        // Read n and m
        String firstLine = br.readLine();
        if (firstLine == null) return;

        StringTokenizer st = new StringTokenizer(firstLine);
        // n is parsed but not strictly used for logic as we derive length from string
        if (st.hasMoreTokens()) {
            int n = Integer.parseInt(st.nextToken()); 
        }
        int m = Integer.parseInt(st.nextToken());

        // Read the string
        String line = br.readLine();
        if (line == null) line = "";

        StringPairCounter analyzer = new StringPairCounter(line);

        StringBuilder out = new StringBuilder();

        for (int i = 0; i < m; i++) {
            String queryLine = br.readLine();
            if (queryLine == null) break;

            // Parse query: index char
            // Using split with whitespace regex to handle potential extra spaces
            String[] parts = queryLine.trim().split("\\s+");
            if (parts.length < 2) continue; // Safety check

            int index = Integer.parseInt(parts[0]) - 1; // Convert 1-based to 0-based
            char newChar = parts[1].charAt(0);

            int currentCount = analyzer.updateAndCount(index, newChar);
            out.append(currentCount).append("\n");
        }

        System.out.print(out);
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

/**
 * Refactored version of the Replacement program.
 * This program counts the number of adjacent dot pairs ("..") in a string
 * and supports point updates.
 */
public class StringDotCounter {

    public static void main(String[] args) throws IOException {
        // Use try-with-resources to ensure the reader is closed automatically
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(System.in))) {

            // Read n (length) and m (number of queries)
            String line = reader.readLine();
            if (line == null) return;

            StringTokenizer st = new StringTokenizer(line);
            int n = Integer.parseInt(st.nextToken());
            int m = Integer.parseInt(st.nextToken());

            // Read the initial string
            String str = reader.readLine();
            if (str == null) return;
            str = str.trim();

            // Build the Segment Tree
            SegmentTree tree = new SegmentTree(str.toCharArray());
            StringBuilder output = new StringBuilder();

            // Process queries
            for (int i = 0; i < m; i++) {
                line = reader.readLine();
                if (line == null) break;

                st = new StringTokenizer(line);
                int index = Integer.parseInt(st.nextToken()) - 1; // Convert to 0-based index
                char c = st.nextToken().charAt(0);

                tree.update(index, c);
                output.append(tree.getScore()).append("\n");
            }

            System.out.print(output);
        }
    }

    /**
     * Segment Tree implementation to count adjacent dot pairs.
     * Optimized to use parallel primitive arrays instead of object arrays.
     */
    static class SegmentTree {
        private final int size; // Power of 2 size for the tree
        private final char[] leftBoundary;
        private final char[] rightBoundary;
        private final int[] score;
        private final int n; // Original array length

        // Sentinel character for padding (anything not '.')
        private static final char PADDING_CHAR = 'X';

        public SegmentTree(char[] arr) {
            this.n = arr.length;
            this.size = calculateTreeSize(arr.length);

            // Arrays are 1-indexed, so size is 2 * powerOf2
            this.leftBoundary = new char[2 * size];
            this.rightBoundary = new char[2 * size];
            this.score = new int[2 * size];

            initializeLeaves(arr);
            buildTree();
        }

        private int calculateTreeSize(int length) {
            int size = 1;
            while (size < length) {
                size <<= 1;
            }
            return size;
        }

        private void initializeLeaves(char[] arr) {
            int offset = size;

            // Initialize leaves with input data
            for (int i = 0; i < n; i++) {
                char c = arr[i];
                leftBoundary[offset + i] = c;
                rightBoundary[offset + i] = c;
                score[offset + i] = 0; // Single character has 0 pairs
            }

            // Initialize padding leaves
            for (int i = n; i < size; i++) {
                leftBoundary[offset + i] = PADDING_CHAR;
                rightBoundary[offset + i] = PADDING_CHAR;
                score[offset + i] = 0;
            }
        }

        private void buildTree() {
            // Build from the last internal node up to the root
            for (int i = size - 1; i > 0; i--) {
                merge(i);
            }
        }

        /**
         * Merges the results of two children into the current node.
         */
        private void merge(int i) {
            int leftChild = 2 * i;
            int rightChild = 2 * i + 1;

            // The range of the current node spans from the left of the left child
            // to the right of the right child.
            leftBoundary[i] = leftBoundary[leftChild];
            rightBoundary[i] = rightBoundary[rightChild];

            // Score is sum of children's scores
            score[i] = score[leftChild] + score[rightChild];

            // If the right end of the left child is '.' and the left end of the right child is '.',
            // we have found a new adjacent pair across the boundary.
            if (rightBoundary[leftChild] == '.' && leftBoundary[rightChild] == '.') {
                score[i]++;
            }
        }

        public int getScore() {
            return score[1];
        }

        public void update(int index, char c) {
            int node = index + size;

            // Optimization: Check if the update actually changes the '.' status.
            // If we change '.' to '.' or non-'.' to non-'.', the score structure remains valid.
            char currentChar = leftBoundary[node];
            if ((currentChar == '.' && c == '.') || (currentChar != '.' && c != '.')) {
                return;
            }

            // Update leaf
            leftBoundary[node] = c;
            rightBoundary[node] = c;

            // Propagate changes up to the root
            node /= 2;
            while (node > 0) {
                merge(node);
                node /= 2;
            }
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.OutputStream;
import java.io.PrintWriter;
import java.util.StringTokenizer;

public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);

        TaskC solver = new TaskC();
        solver.solve(in, out);

        out.close();
    }

    /**
     * Solves the dot-counting problem with point updates.
     */
    static class TaskC {
        public void solve(InputReader in, PrintWriter out) {
            int len = in.nextInt();
            int m = in.nextInt();
            char[] s = in.next().toCharArray();

            // Initial count of consecutive dot pairs
            int count = 0;
            for (int i = 1; i < len; i++) {
                if (s[i] == '.' && s[i - 1] == '.') {
                    count++;
                }
            }

            // Process each update query
            for (int q = 0; q < m; q++) {
                int index = in.nextInt() - 1; // Convert 1-based to 0-based
                char newChar = in.next().charAt(0);

                // Update count based on how the change affects adjacent pairs
                count += calculateDelta(s, index, s[index], newChar, len);
                s[index] = newChar;
                out.println(count);
            }
        }

        /**
         * Calculates the change in the count of consecutive dot pairs 
         * when a character at a specific index is updated.
         * Only adjacent pairs involving the updated index are affected.
         */
        private int calculateDelta(char[] s, int index, char oldChar, char newChar, int len) {
            if (oldChar == newChar) {
                return 0;
            }

            int delta = 0;

            // If removing a dot, check if adjacent pairs are broken
            if (oldChar == '.') {
                if (index > 0 && s[index - 1] == '.') {
                    delta--;
                }
                if (index < len - 1 && s[index + 1] == '.') {
                    delta--;
                }
            } 
            // If adding a dot, check if new adjacent pairs are formed
            else if (newChar == '.') {
                if (index > 0 && s[index - 1] == '.') {
                    delta++;
                }
                if (index < len - 1 && s[index + 1] == '.') {
                    delta++;
                }
            }

            return delta;
        }
    }

    /**
     * Fast input reader for competitive programming / high-throughput scenarios.
     */
    static class InputReader {
        private final BufferedReader br;
        private StringTokenizer st;

        public InputReader(InputStream inputStream) {
            br = new BufferedReader(new InputStreamReader(inputStream));
        }

        public String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) {
                        throw new IOException("Unexpected end of input");
                    }
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input", e);
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

