public class Main {
    public static void main(String[] args) {
        FastScanner scanner = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out));
        try {
            new ConsecutiveDotsProcessor().process(scanner, out);
        } finally {
            out.flush();
            out.close();
        }
    }
}

class ConsecutiveDotsProcessor {
    public void process(FastScanner in, PrintWriter out) {
        int length = in.nextInt();
        int numQueries = in.nextInt();
        char[] grid = in.next().toCharArray();

        int consecutiveDotsCount = countInitialConsecutiveDots(grid);

        for (int i = 0; i < numQueries; i++) {
            int index = in.nextInt() - 1; // Convert 1-based index to 0-based
            String token = in.next();
            char newChar = token.charAt(0);

            consecutiveDotsCount = updateGridAndCount(grid, index, newChar, consecutiveDotsCount);
            out.println(consecutiveDotsCount);
        }
    }

    private int countInitialConsecutiveDots(char[] grid) {
        int count = 0;
        for (int i = 1; i < grid.length; i++) {
            if (grid[i] == '.' && grid[i - 1] == '.') {
                count++;
            }
        }
        return count;
    }

    private int updateGridAndCount(char[] grid, int index, char newChar, int currentCount) {
        char oldChar = grid[index];
        if (oldChar == newChar) {
            return currentCount;
        }

        // Check left neighbor
        if (index > 0) {
            if (oldChar == '.' && grid[index - 1] == '.') {
                currentCount--;
            }
            if (newChar == '.' && grid[index - 1] == '.') {
                currentCount++;
            }
        }

        // Check right neighbor
        if (index < grid.length - 1) {
            if (oldChar == '.' && grid[index + 1] == '.') {
                currentCount--;
            }
            if (newChar == '.' && grid[index + 1] == '.') {
                currentCount++;
            }
        }

        grid[index] = newChar;
        return currentCount;
    }
}

class FastScanner {
    private final BufferedReader br;
    private StringTokenizer st;

    public FastScanner(InputStream stream) {
        br = new BufferedReader(new InputStreamReader(stream));
    }

    private String read() {
        while (st == null || !st.hasMoreTokens()) {
            try {
                String line = br.readLine();
                if (line == null) return null;
                st = new StringTokenizer(line);
            } catch (IOException e) {
                throw new RuntimeException("Failed to read input", e);
            }
        }
        return st.nextToken();
    }

    public String next() {
        String token = read();
        if (token == null) throw new RuntimeException("Unexpected end of input");
        return token;
    }

    public int nextInt() {
        return Integer.parseInt(next());
    }
}

