import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter pw = new PrintWriter(System.out);
        StringTokenizer st = new StringTokenizer("");

        // Read n and m
        while (!st.hasMoreTokens()) {
            String line = br.readLine();
            if (line == null) return;
            st = new StringTokenizer(line);
        }
        int n = Integer.parseInt(st.nextToken());
        int m = Integer.parseInt(st.nextToken());

        char[][] grid = new char[n][];
        for (int i = 0; i < n; i++) {
            while (!st.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) break;
                st = new StringTokenizer(line);
            }
            grid[i] = st.nextToken().toCharArray();
        }

        solve(grid, n, m, pw);

        pw.flush();
        pw.close();
    }

    private static void solve(char[][] grid, int n, int m, PrintWriter out) {
        int[][] componentIds = new int[n][m];
        List<Integer> componentSizes = new ArrayList<>();
        componentSizes.add(0); // Placeholder for 1-based IDs

        boolean[][] visited = new boolean[n][m];
        int currentId = 1;

        // Direction vectors for up, down, left, right
        int[] dr = {1, -1, 0, 0};
        int[] dc = {0, 0, 1, -1};

        // 1. Identify connected components of '.'
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (!visited[i][j] && grid[i][j] == '.') {
                    visited[i][j] = true;
                    componentIds[i][j] = currentId;
                    int size = bfs(grid, visited, componentIds, i, j, currentId, dr, dc);
                    componentSizes.add(size);
                    currentId++;
                }
            }
        }

        // 2. Compute answer grid
        char[][] result = new char[n][m];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == '.') {
                    result[i][j] = '.';
                } else {
                    int sum = 1;
                    Set<Integer> adjacentIds = new HashSet<>();
                    if (i > 0) adjacentIds.add(componentIds[i - 1][j]);
                    if (i < n - 1) adjacentIds.add(componentIds[i + 1][j]);
                    if (j > 0) adjacentIds.add(componentIds[i][j - 1]);
                    if (j < m - 1) adjacentIds.add(componentIds[i][j + 1]);

                    for (int id : adjacentIds) {
                        sum += componentSizes.get(id);
                    }
                    result[i][j] = (char) ((sum % 10) + '0');
                }
            }
        }

        // 3. Output result
        for (char[] row : result) {
            out.println(new String(row));
        }
    }

    private static int bfs(char[][] grid, boolean[][] visited, int[][] componentIds,
                           int startI, int startJ, int id, int[] dr, int[] dc) {
        int size = 1;
        Queue<int[]> queue = new ArrayDeque<>();
        queue.offer(new int[]{startI, startJ});

        while (!queue.isEmpty()) {
            int[] curr = queue.poll();
            for (int k = 0; k < 4; k++) {
                int r = curr[0] + dr[k];
                int c = curr[1] + dc[k];

                if (r >= 0 && c >= 0 && r < grid.length && c < grid[0].length &&
                    !visited[r][c] && grid[r][c] == '.') {
                    visited[r][c] = true;
                    componentIds[r][c] = id;
                    size++;
                    queue.offer(new int[]{r, c});
                }
            }
        }
        return size;
    }
}

import java.io.BufferedWriter;
import java.io.IOException;
import java.io.InputStream;
import java.io.OutputStream;
import java.io.OutputStreamWriter;
import java.io.PrintWriter;
import java.util.InputMismatchException;

public class Main {
    public static void main(String[] args) {
        InputReader in = new InputReader(System.in);
        OutputWriter out = new OutputWriter(System.out);

        int n = in.readInt();
        int m = in.readInt();

        GridSolver solver = new GridSolver(n, m, in);
        solver.solve(out);

        out.close();
    }

    /**
     * Handles grid processing: component building and result printing.
     */
    static class GridSolver {
        private final int rows;
        private final int cols;
        private final boolean[][] isFree;
        private final DSU dsu;

        // Direction vectors for 4-connectivity (Down, Left, Up, Right)
        private static final int[] DR = {1, 0, -1, 0};
        private static final int[] DC = {0, -1, 0, 1};

        public GridSolver(int rows, int cols, InputReader in) {
            this.rows = rows;
            this.cols = cols;
            this.isFree = new boolean[rows][cols];
            this.dsu = new DSU(rows, cols);

            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    isFree[i][j] = in.readCharacter() == '.';
                }
            }
        }

        public void solve(OutputWriter out) {
            buildComponents();
            printResult(out);
        }

        private void buildComponents() {
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (isFree[i][j]) {
                        for (int k = 0; k < 4; k++) {
                            int ni = i + DR[k];
                            int nj = j + DC[k];
                            if (isValid(ni, nj) && isFree[ni][nj]) {
                                dsu.unite(i, j, ni, nj);
                            }
                        }
                    }
                }
            }
        }

        private void printResult(OutputWriter out) {
            // Reuse a small array to track unique component roots around a blocked cell.
            // This avoids the overhead of allocating/clearing a HashSet in a tight loop.
            int[] neighborRoots = new int[4];

            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (isFree[i][j]) {
                        out.print('.');
                    } else {
                        int uniqueCount = 0;
                        for (int k = 0; k < 4; k++) {
                            int ni = i + DR[k];
                            int nj = j + DC[k];
                            if (isValid(ni, nj) && isFree[ni][nj]) {
                                int root = dsu.getRoot(ni, nj);

                                // Manual duplicate check (max 4 neighbors)
                                boolean isDuplicate = false;
                                for (int p = 0; p < uniqueCount; p++) {
                                    if (neighborRoots[p] == root) {
                                        isDuplicate = true;
                                        break;
                                    }
                                }
                                if (!isDuplicate) {
                                    neighborRoots[uniqueCount++] = root;
                                }
                            }
                        }

                        int sum = 1; // +1 for the current blocked cell itself
                        for (int p = 0; p < uniqueCount; p++) {
                            sum += dsu.getSize(neighborRoots[p]);
                        }
                        out.print(sum % 10);
                    }
                }
                out.printLine();
            }
        }

        private boolean isValid(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }
    }

    /**
     * Disjoint Set Union (DSU) implementation for 2D grid coordinates.
     * Uses 1D array mapping with path compression and union by size.
     */
    static class DSU {
        private final int cols;
        private final int[] parent;
        private final int[] size;

        public DSU(int rows, int cols) {
            this.cols = cols;
            int total = rows * cols;
            parent = new int[total];
            size = new int[total];
            for (int i = 0; i < total; i++) {
                parent[i] = i;
                size[i] = 1;
            }
        }

        private int find(int v) {
            if (parent[v] == v) {
                return v;
            }
            return parent[v] = find(parent[v]); // Path compression
        }

        public void unite(int r1, int c1, int r2, int c2) {
            int idx1 = r1 * cols + c1;
            int idx2 = r2 * cols + c2;
            int root1 = find(idx1);
            int root2 = find(idx2);

            if (root1 != root2) {
                parent[root1] = root2;
                size[root2] += size[root1]; // Union by size
            }
        }

        public int getRoot(int r, int c) {
            return find(r * cols + c);
        }

        /**
         * Returns the size of the component rooted at 'root'.
         * Caller must ensure 'root' is already a root index.
         */
        public int getSize(int root) {
            return size[root];
        }
    }

    /**
     * Fast input reader for competitive programming environments.
     */
    static class InputReader {
        private final InputStream stream;
        private final byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        public int read() {
            if (numChars == -1) {
                throw new InputMismatchException();
            }
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0) {
                    return -1;
                }
            }
            return buf[curChar++];
        }

        public int readInt() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                res *= 10;
                res += c - '0';
                c = read();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public char readCharacter() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            return (char) c;
        }

        private boolean isSpaceChar(int c) {
            return isWhitespace(c);
        }

        private static boolean isWhitespace(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }
    }

    /**
     * Fast output writer with buffered printing.
     */
    static class OutputWriter {
        private final PrintWriter writer;

        public OutputWriter(OutputStream outputStream) {
            writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(outputStream)));
        }

        public void printLine() {
            writer.println();
        }

        public void print(char c) {
            writer.print(c);
        }

        public void print(int i) {
            writer.print(i);
        }

        public void close() {
            writer.flush();
            writer.close();
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Refactored Grid Component Analyzer.
 * 
 * This program reads a grid of characters, identifies connected components of '.' cells
 * using a Union-Find data structure, and updates obstacle cells with a digit representing
 * the sum of the sizes of adjacent unique components (modulo 10).
 */
public class GridSolver {

    /**
     * FastScanner for efficient input reading.
     */
    static class FastScanner {
        BufferedReader br;
        StringTokenizer st;

        public FastScanner(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }
    }

    /**
     * Union-Find (Disjoint Set Union) data structure with path compression and union by size.
     */
    static class UnionFind {
        int[] parent;
        int[] size;

        public UnionFind(int n) {
            parent = new int[n];
            size = new int[n];
            for (int i = 0; i < n; i++) {
                parent[i] = i;
                size[i] = 1;
            }
        }

        /**
         * Finds the representative root of the set containing element i with path compression.
         */
        public int find(int i) {
            if (parent[i] == i) {
                return i;
            }
            return parent[i] = find(parent[i]);
        }

        /**
         * Unites the sets containing elements i and j.
         */
        public void union(int i, int j) {
            int rootI = find(i);
            int rootJ = find(j);

            if (rootI != rootJ) {
                // Union by size: attach smaller tree to larger tree
                if (size[rootI] < size[rootJ]) {
                    int temp = rootI;
                    rootI = rootJ;
                    rootJ = temp;
                }
                parent[rootJ] = rootI;
                size[rootI] += size[rootJ];
            }
        }

        /**
         * Returns the size of the component rooted at 'root'.
         */
        public int getSize(int root) {
            return size[root];
        }
    }

    FastScanner in;
    PrintWriter out;

    public static void main(String[] args) {
        new GridSolver().run();
    }

    void run() {
        in = new FastScanner(System.in);
        out = new PrintWriter(System.out);
        solve();
        out.flush();
        out.close();
    }

    void solve() {
        int n = in.nextInt(); // Number of rows
        int m = in.nextInt(); // Number of columns

        char[][] grid = new char[n][m];
        for (int i = 0; i < n; i++) {
            String row = in.next();
            for (int j = 0; j < m; j++) {
                grid[i][j] = row.charAt(j);
            }
        }

        // Initialize Union-Find for n * m cells
        UnionFind unionFind = new UnionFind(n * m);

        // Pass 1: Connect adjacent '.' cells
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == '.') {
                    // Connect with bottom neighbor
                    if (i + 1 < n && grid[i + 1][j] == '.') {
                        unionFind.union(i * m + j, (i + 1) * m + j);
                    }
                    // Connect with right neighbor
                    if (j + 1 < m && grid[i][j + 1] == '.') {
                        unionFind.union(i * m + j, i * m + j + 1);
                    }
                }
            }
        }

        // Directions for neighbors: Down, Up, Right, Left
        int[] dr = {1, -1, 0, 0};
        int[] dc = {0, 0, 1, -1};

        // Pass 2: Process obstacles and calculate adjacent component sizes
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                // Skip empty space ('.')
                if (grid[i][j] == '.') {
                    continue;
                }

                int[] componentRoots = new int[4];
                int uniqueCount = 0;
                int totalSize = 0;

                // Check all 4 neighbors
                for (int k = 0; k < 4; k++) {
                    int nr = i + dr[k];
                    int nc = j + dc[k];

                    // Check bounds and if neighbor is part of a component
                    if (nr >= 0 && nr < n && nc >= 0 && nc < m && grid[nr][nc] == '.') {
                        int root = unionFind.find(nr * m + nc);

                        // Check if this root is already counted
                        boolean isDuplicate = false;
                        for (int u = 0; u < uniqueCount; u++) {
                            if (componentRoots[u] == root) {
                                isDuplicate = true;
                                break;
                            }
                        }

                        if (!isDuplicate) {
                            componentRoots[uniqueCount++] = root;
                            totalSize += unionFind.getSize(root);
                        }
                    }
                }

                // Update the obstacle cell with the calculated digit
                // Logic preserved from original: (totalSize + 1) % 10
                grid[i][j] = (char) ('0' + (totalSize + 1) % 10);
            }
        }

        // Output the modified grid
        for (int i = 0; i < n; i++) {
            out.println(grid[i]);
        }
    }
}

import java.io.*;
import java.util.*;

public class Codechef {
    public static void main(String[] args) throws IOException {
        FastScanner in = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out);
        try {
            GridSolver solver = new GridSolver(in, out);
            solver.solve();
        } finally {
            out.flush();
        }
    }

    /**
     * Encapsulates the core problem logic to avoid static global variables
     * and improve testability and maintainability.
     */
    static class GridSolver {
        private final FastScanner in;
        private final PrintWriter out;
        private int n, m;
        private int[][] grid;
        private int[][] componentId;
        private int[] componentSize;
        private boolean[][] visited;
        private int componentCount = 0;

        GridSolver(FastScanner in, PrintWriter out) {
            this.in = in;
            this.out = out;
        }

        void solve() throws IOException {
            n = in.ni();
            m = in.ni();
            grid = new int[n][m];

            // Read grid input
            for (int i = 0; i < n; i++) {
                String line = in.next();
                for (int j = 0; j < m; j++) {
                    grid[i][j] = (line.charAt(j) == '*') ? 1 : 0;
                }
            }

            componentId = new int[n][m];
            visited = new boolean[n][m];
            // Maximum possible number of connected components is n * m
            componentSize = new int[n * m + 1];

            // Identify connected components of '0's
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    if (!visited[i][j] && grid[i][j] == 0) {
                        componentCount++;
                        dfs(i, j);
                    }
                }
            }

            // Generate output
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    if (grid[i][j] == 0) {
                        out.print('.');
                    } else {
                        // Collect IDs of adjacent components
                        int[] neighborIds = new int[4];
                        int count = 0;

                        if (j + 1 < m && grid[i][j + 1] == 0) neighborIds[count++] = componentId[i][j + 1];
                        if (i + 1 < n && grid[i + 1][j] == 0) neighborIds[count++] = componentId[i + 1][j];
                        if (j - 1 >= 0 && grid[i][j - 1] == 0) neighborIds[count++] = componentId[i][j - 1];
                        if (i - 1 >= 0 && grid[i - 1][j] == 0) neighborIds[count++] = componentId[i - 1][j];

                        // Sum sizes of unique adjacent components + 1 (for the cell itself)
                        int sum = 1;
                        for (int k = 0; k < count; k++) {
                            boolean isDuplicate = false;
                            for (int l = 0; l < k; l++) {
                                if (neighborIds[k] == neighborIds[l]) {
                                    isDuplicate = true;
                                    break;
                                }
                            }
                            if (!isDuplicate) {
                                sum += componentSize[neighborIds[k]];
                            }
                        }
                        out.print(sum % 10);
                    }
                }
                out.println();
            }
        }

        private void dfs(int r, int c) {
            if (visited[r][c]) return;
            visited[r][c] = true;
            componentId[r][c] = componentCount;
            componentSize[componentCount]++;

            int[] dr = {-1, 1, 0, 0};
            int[] dc = {0, 0, -1, 1};
            for (int k = 0; k < 4; k++) {
                int nr = r + dr[k];
                int nc = c + dc[k];
                if (nr >= 0 && nr < n && nc >= 0 && nc < m && grid[nr][nc] == 0) {
                    dfs(nr, nc);
                }
            }
        }
    }

    /**
     * Optimized FastScanner for competitive programming input.
     */
    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer stok;

        FastScanner(InputStream is) {
            br = new BufferedReader(new InputStreamReader(is));
        }

        String next() throws IOException {
            while (stok == null || !stok.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) return null;
                stok = new StringTokenizer(line);
            }
            return stok.nextToken();
        }

        int ni() throws IOException {
            return Integer.parseInt(next());
        }

        long nl() throws IOException {
            return Long.parseLong(next());
        }

        double nd() throws IOException {
            return Double.parseDouble(next());
        }

        char nc() throws IOException {
            return (char) br.read();
        }

        String ns() throws IOException {
            return br.readLine();
        }

        int[] nia(int n) throws IOException {
            int[] a = new int[n];
            for (int i = 0; i < n; i++) a[i] = ni();
            return a;
        }

        long[] nla(int n) throws IOException {
            long[] a = new long[n];
            for (int i = 0; i < n; i++) a[i] = nl();
            return a;
        }

        double[] nda(int n) throws IOException {
            double[] a = new double[n];
            for (int i = 0; i < n; i++) a[i] = nd();
            return a;
        }

        int[][] imat(int n, int m) throws IOException {
            int[][] mat = new int[n][m];
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) mat[i][j] = ni();
            }
            return mat;
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.HashSet;
import java.util.Set;
import java.util.StringTokenizer;

/**
 * Solves a grid-based problem by identifying connected components of '.' cells,
 * then calculating the resulting component size for each '*' cell if it were converted to '.'.
 */
public class ConnectedComponentsGrid {

    // Direction vectors for up, down, left, right
    private static final int[] DELTA_R = {-1, 1, 0, 0};
    private static final int[] DELTA_C = {0, 0, 1, -1};

    private final BufferedReader reader;
    private StringTokenizer tokenizer;

    private int[][] componentGrid;
    private int[] componentSizes;
    private int componentCount;
    private int rows;
    private int cols;

    public ConnectedComponentsGrid() {
        this.reader = new BufferedReader(new InputStreamReader(System.in));
    }

    public static void main(String[] args) {
        try {
            ConnectedComponentsGrid solver = new ConnectedComponentsGrid();
            solver.run();
        } catch (IOException e) {
            System.err.println("Error reading input: " + e.getMessage());
        }
    }

    private void run() throws IOException {
        int n = nextInt();
        int m = nextInt();
        rows = n;
        cols = m;

        // Initialize data structures
        componentGrid = new int[n][m];
        componentSizes = new int[n * m + 1];
        char[][] grid = new char[n][m];

        // Read the grid
        for (int i = 0; i < n; i++) {
            String line = reader.readLine();
            if (line == null) break;
            for (int j = 0; j < m && j < line.length(); j++) {
                grid[i][j] = line.charAt(j);
            }
        }

        // Step 1: Identify and label connected components of '.'
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (componentGrid[i][j] == 0 && grid[i][j] == '.') {
                    componentCount++;
                    componentSizes[componentCount] = dfs(i, j, grid);
                }
            }
        }

        // Step 2: Calculate results for '*' cells
        StringBuilder result = new StringBuilder();
        Set<Integer> adjacentComponents = new HashSet<>();

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == '*') {
                    adjacentComponents.clear();
                    int totalSize = 0;

                    // Check all 4 adjacent cells
                    for (int k = 0; k < 4; k++) {
                        int ni = i + DELTA_R[k];
                        int nj = j + DELTA_C[k];
                        if (isWithinBounds(ni, nj) && grid[ni][nj] == '.') {
                            adjacentComponents.add(componentGrid[ni][nj]);
                        }
                    }

                    // Sum sizes of unique adjacent components
                    for (int compId : adjacentComponents) {
                        totalSize += componentSizes[compId];
                    }

                    result.append((totalSize + 1) % 10);
                } else {
                    result.append('.');
                }
                result.append('\n');
            }
        }
        System.out.print(result);
    }

    private boolean isWithinBounds(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /**
     * Performs Depth-First Search to label a connected component and return its size.
     */
    private int dfs(int r, int c, char[][] grid) {
        if (!isWithinBounds(r, c) || componentGrid[r][c] != 0 || grid[r][c] == '*') {
            return 0;
        }
        componentGrid[r][c] = componentCount;
        int size = 1;
        for (int i = 0; i < 4; i++) {
            size += dfs(r + DELTA_R[i], c + DELTA_C[i], grid);
        }
        return size;
    }

    /**
     * Reads the next token from input, handling line breaks automatically.
     */
    private String next() throws IOException {
        while (tokenizer == null || !tokenizer.hasMoreTokens()) {
            String line = reader.readLine();
            if (line == null) return null;
            tokenizer = new StringTokenizer(line);
        }
        return tokenizer.nextToken();
    }

    /**
     * Parses the next token as an integer.
     */
    private int nextInt() throws IOException {
        String s = next();
        return s == null ? 0 : Integer.parseInt(s);
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayDeque;
import java.util.Deque;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;
import java.util.StringTokenizer;

/**
 * Solves the labyrinth problem by identifying connected open components
 * and replacing walls with the modulo-10 sum of adjacent component sizes.
 */
public class TheLabyrinth {
    private static final char OPEN = '.';
    private static final int WALL = -1;
    private static final int OPEN_CELL = 0;

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line = br.readLine();
        if (line == null) return;

        // Robust parsing of dimensions
        StringTokenizer st = new StringTokenizer(line);
        if (!st.hasMoreTokens()) return;
        int n = Integer.parseInt(st.nextToken());
        int m = Integer.parseInt(st.nextToken());

        char[][] initialMaze = new char[n][];
        for (int i = 0; i < n; i++) {
            String row = br.readLine();
            initialMaze[i] = (row != null) ? row.toCharArray() : new char[0];
        }

        LabyrinthGrid processor = new LabyrinthGrid(initialMaze);
        char[][] result = processor.process();

        // Efficient output construction
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < n; i++) {
            sb.append(result[i]);
            if (i < n - 1) {
                sb.append('\n');
            }
        }
        System.out.print(sb);
    }
}

/**
 * Encapsulates all grid processing logic. Replaces the misleading 'Graph' name
 * with a domain-specific name and separates concerns for maintainability.
 */
class LabyrinthGrid {
    private final int rows;
    private final int cols;
    private final int[][] grid; // 0: open, -1: wall, >0: component ID
    private final Map<Integer, Integer> componentSizes = new HashMap<>();
    private int currentComponentId = 1;

    public LabyrinthGrid(char[][] initialMaze) {
        this.rows = initialMaze.length;
        this.cols = rows > 0 ? initialMaze[0].length : 0;
        this.grid = new int[rows][cols];

        // Initialize grid: convert characters to integer states
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                grid[i][j] = (j < initialMaze[i].length && initialMaze[i][j] == OPEN) ? OPEN_CELL : WALL;
            }
        }
    }

    /**
     * Orchestrates the processing pipeline: component identification followed by output generation.
     */
    public char[][] process() {
        identifyConnectedComponents();
        return generateOutputGrid();
    }

    /**
     * Traverses the grid to label each connected open area with a unique component ID
     * and records its size.
     */
    private void identifyConnectedComponents() {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == OPEN_CELL) {
                    int size = traverseComponent(i, j);
                    componentSizes.put(currentComponentId, size);
                    currentComponentId++;
                }
            }
        }
    }

    /**
     * Iterative DFS to prevent StackOverflowError on large grids.
     * Marks visited cells with the current component ID and counts size.
     */
    private int traverseComponent(int startRow, int startCol) {
        int size = 0;
        Deque<int[]> stack = new ArrayDeque<>();
        stack.push(new int[]{startRow, startCol});
        grid[startRow][startCol] = currentComponentId;
        size++;

        int[] dr = {-1, 1, 0, 0};
        int[] dc = {0, 0, -1, 1};

        while (!stack.isEmpty()) {
            int[] curr = stack.pop();
            for (int k = 0; k < 4; k++) {
                int r = curr[0] + dr[k];
                int c = curr[1] + dc[k];

                if (r >= 0 && r < rows && c >= 0 && c < cols && grid[r][c] == OPEN_CELL) {
                    grid[r][c] = currentComponentId;
                    size++;
                    stack.push(new int[]{r, c});
                }
            }
        }
        return size;
    }

    /**
     * Generates the final grid where walls are replaced by the modulo-10 sum
     * of the sizes of adjacent connected components.
     */
    private char[][] generateOutputGrid() {
        char[][] result = new char[rows][cols];
        int[] dr = {-1, 1, 0, 0};
        int[] dc = {0, 0, -1, 1};

        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == WALL) {
                    Set<Integer> adjacentComponentIds = new HashSet<>();
                    for (int k = 0; k < 4; k++) {
                        int r = i + dr[k];
                        int c = j + dc[k];
                        if (r >= 0 && r < rows && c >= 0 && c < cols && grid[r][c] > 0) {
                            adjacentComponentIds.add(grid[r][c]);
                        }
                    }

                    int totalSize = 1;
                    for (int id : adjacentComponentIds) {
                        totalSize += componentSizes.getOrDefault(id, 0);
                    }
                    result[i][j] = (char) ('0' + (totalSize % 10));
                } else {
                    result[i][j] = OPEN;
                }
            }
        }
        return result;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.LinkedList;
import java.util.List;
import java.util.Queue;
import java.util.Set;
import java.util.StringTokenizer;

public class C {

    private static final int[] DX = {1, -1, 0, 0};
    private static final int[] DY = {0, 0, 1, -1};

    private int rows;
    private int cols;
    private char[][] grid;
    private int[][] componentValues;
    private int[][] componentIds;
    private boolean[][] visited;

    /** Checks if coordinates are within grid bounds. */
    private boolean isValid(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /** Performs BFS to find all cells in a connected component of '.'. */
    private List<int[]> findComponent(int startR, int startC) {
        List<int[]> componentCells = new ArrayList<>();
        Queue<int[]> queue = new LinkedList<>();

        queue.offer(new int[]{startR, startC});
        visited[startR][startC] = true;
        componentCells.add(new int[]{startR, startC});

        while (!queue.isEmpty()) {
            int[] curr = queue.poll();
            for (int d = 0; d < 4; d++) {
                int nr = curr[0] + DX[d];
                int nc = curr[1] + DY[d];

                if (isValid(nr, nc) && grid[nr][nc] == '.' && !visited[nr][nc]) {
                    visited[nr][nc] = true;
                    int[] next = new int[]{nr, nc};
                    componentCells.add(next);
                    queue.offer(next);
                }
            }
        }
        return componentCells;
    }

    /** Orchestrates reading, processing, and outputting the grid. */
    public void process() throws IOException {
        FastReader sc = new FastReader(System.in);
        rows = sc.nextInt();
        cols = sc.nextInt();

        grid = new char[rows][];
        for (int i = 0; i < rows; i++) {
            grid[i] = sc.next().toCharArray();
        }

        componentValues = new int[rows][cols];
        componentIds = new int[rows][cols];
        visited = new boolean[rows][cols];

        // 1. Identify connected components and assign sizes/IDs
        int componentId = 0;
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == '.' && !visited[i][j]) {
                    List<int[]> cells = findComponent(i, j);
                    int size = cells.size();
                    for (int[] cell : cells) {
                        componentValues[cell[0]][cell[1]] = size;
                        componentIds[cell[0]][cell[1]] = componentId;
                    }
                    componentId++;
                }
            }
        }

        // 2. Calculate values for '*' cells based on adjacent components
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == '*') {
                    int sum = 1; // Base value as per original logic
                    Set<Integer> adjacentComponentIds = new HashSet<>();

                    for (int d = 0; d < 4; d++) {
                        int ni = i + DX[d];
                        int nj = j + DY[d];

                        if (isValid(ni, nj) && grid[ni][nj] == '.') {
                            int id = componentIds[ni][nj];
                            // Add component size only once per unique adjacent component
                            if (adjacentComponentIds.add(id)) {
                                sum += componentValues[ni][nj];
                            }
                        }
                    }
                    componentValues[i][j] = sum % 10;
                }
            }
        }

        // 3. Build and print the result
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                sb.append(grid[i][j] == '*' ? componentValues[i][j] : '.');
            }
            sb.append('\n');
        }
        System.out.print(sb);
    }

    public static void main(String[] args) throws IOException {
        new C().process();
    }

    /** Lightweight fast I/O reader tailored for competitive programming style inputs. */
    static class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastReader(InputStream s) {
            br = new BufferedReader(new InputStreamReader(s));
        }

        public String next() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) return null;
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

        public int nextInt() throws IOException {
            String s = next();
            return s == null ? 0 : Integer.parseInt(s);
        }
    }
}

import java.io.*;
import java.util.*;

public class ProblemC {

    // Direction vectors for up, left, right, down
    private static final int[] DR = {-1, 0, 0, 1};
    private static final int[] DC = {0, -1, 1, 0};
    private static final int MOD = 10;

    public static void main(String[] args) {
        // Use try-with-resources for automatic resource cleanup
        try (InputReader in = new InputReader();
             PrintWriter out = new PrintWriter(System.out)) {
            new ProblemC().solve(in, out);
        } catch (IOException e) {
            throw new RuntimeException("Failed to process input/output", e);
        }
    }

    /**
     * Main solving logic: reads grid, identifies components, computes answers, and prints output.
     */
    public void solve(InputReader in, PrintWriter out) {
        int n = in.nextInt();
        int m = in.nextInt();

        char[][] grid = new char[n][m];
        for (int i = 0; i < n; i++) {
            // Use next() instead of nextLine() to safely handle whitespace/newlines in CP inputs
            grid[i] = in.next().toCharArray();
        }

        int[][] componentId = new int[n][m];
        Map<Integer, Integer> componentSizes = new HashMap<>();
        int currentId = 1;

        // Step 1: Identify connected components of '.' and store their sizes
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < m; c++) {
                if (grid[r][c] == '.' && componentId[r][c] == 0) {
                    int size = bfs(grid, n, m, r, c, componentId, currentId);
                    componentSizes.put(currentId, size);
                    currentId++;
                }
            }
        }

        // Step 2: Compute and print the result grid
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < m; c++) {
                if (grid[r][c] == '.') {
                    out.print('.');
                } else {
                    int totalSize = 1; // Count the current '*' cell itself
                    Set<Integer> adjacentIds = new HashSet<>();

                    // Check all 4 neighbors
                    for (int k = 0; k < 4; k++) {
                        int nr = r + DR[k];
                        int nc = c + DC[k];

                        if (isValid(nr, nc, n, m) && grid[nr][nc] == '.') {
                            adjacentIds.add(componentId[nr][nc]);
                        }
                    }

                    // Sum sizes of adjacent distinct components
                    for (int id : adjacentIds) {
                        totalSize += componentSizes.get(id);
                    }

                    // Output only the last digit as per original logic
                    out.print(totalSize % MOD);
                }
            }
            out.println();
        }
    }

    /**
     * Checks if coordinates are within grid bounds.
     */
    private boolean isValid(int r, int c, int n, int m) {
        return r >= 0 && r < n && c >= 0 && c < m;
    }

    /**
     * Performs BFS to find the size of a connected component.
     * Uses coordinate encoding (r * m + c) to avoid creating multiple queue objects.
     */
    private int bfs(char[][] grid, int n, int m, int startR, int startC, 
                    int[][] componentId, int id) {
        int size = 0;
        Queue<Integer> queue = new ArrayDeque<>();

        // Encode starting position
        queue.add(startR * m + startC);
        componentId[startR][startC] = id;
        size++;

        while (!queue.isEmpty()) {
            int pos = queue.poll();
            int r = pos / m;
            int c = pos % m;

            for (int k = 0; k < 4; k++) {
                int nr = r + DR[k];
                int nc = c + DC[k];

                if (isValid(nr, nc, n, m) && grid[nr][nc] == '.' && componentId[nr][nc] == 0) {
                    componentId[nr][nc] = id;
                    queue.add(nr * m + nc);
                    size++;
                }
            }
        }
        return size;
    }

    /**
     * Fast input reader for competitive programming.
     */
    static class InputReader implements AutoCloseable {
        private final BufferedReader br;
        private StringTokenizer st;

        public InputReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        public String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input", e);
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }

        public double nextDouble() {
            return Double.parseDouble(next());
        }

        public String nextLine() {
            try {
                return br.readLine();
            } catch (IOException e) {
                throw new RuntimeException("Failed to read line", e);
            }
        }

        @Override
        public void close() throws IOException {
            br.close();
        }
    }
}

import java.io.*;
import java.util.*;

public class TheLabyrinth {

    public static void main(String[] args) throws IOException {
        // Fast I/O setup
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out));

        // Read dimensions
        String line = br.readLine();
        if (line == null) {
            out.flush();
            return;
        }
        StringTokenizer st = new StringTokenizer(line);
        int rows = Integer.parseInt(st.nextToken());
        int cols = Integer.parseInt(st.nextToken());

        // Read grid
        char[][] grid = new char[rows][];
        for (int i = 0; i < rows; i++) {
            String rowLine = br.readLine();
            // Handle potential null or empty lines gracefully
            grid[i] = (rowLine != null) ? rowLine.toCharArray() : new char[0];
        }

        // Solve using encapsulated logic
        LabyrinthSolver solver = new LabyrinthSolver(rows, cols, grid);
        solver.solve(out);

        out.flush();
    }

    /**
     * Encapsulates the labyrinth solving algorithm.
     * Uses iterative BFS to avoid stack overflow and separates concerns
     * into distinct, testable methods.
     */
    static class LabyrinthSolver {
        private final int rows, cols;
        private final char[][] grid;
        private final int[][] componentIds;
        private final int[][] result;
        private final boolean[][] visited;
        private final int[][] directions = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};
        private final Map<Integer, Integer> componentSizes;

        public LabyrinthSolver(int rows, int cols, char[][] grid) {
            this.rows = rows;
            this.cols = cols;
            this.grid = grid;
            this.componentIds = new int[rows][cols];
            this.result = new int[rows][cols];
            this.visited = new boolean[rows][cols];
            this.componentSizes = new HashMap<>();
        }

        public void solve(PrintWriter out) {
            findConnectedComponents();
            calculateOptimalMoves();
            formatAndPrintOutput(out);
        }

        /**
         * Labels all connected open regions ('.') with unique IDs and records their sizes.
         */
        private void findConnectedComponents() {
            int currentId = 1;
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] == '.' && !visited[r][c]) {
                        int size = bfsLabelComponent(r, c, currentId);
                        componentSizes.put(currentId, size);
                        currentId++;
                    }
                }
            }
        }

        /**
         * Iteratively traverses a connected component, labeling cells and counting size.
         */
        private int bfsLabelComponent(int startR, int startC, int id) {
            Queue<int[]> queue = new ArrayDeque<>();
            queue.offer(new int[]{startR, startC});
            visited[startR][startC] = true;
            componentIds[startR][startC] = id;
            int size = 0;

            while (!queue.isEmpty()) {
                int[] curr = queue.poll();
                size++;
                for (int[] dir : directions) {
                    int nr = curr[0] + dir[0];
                    int nc = curr[1] + dir[1];
                    if (isValid(nr, nc) && !visited[nr][nc] && grid[nr][nc] == '.') {
                        visited[nr][nc] = true;
                        componentIds[nr][nc] = id;
                        queue.offer(new int[]{nr, nc});
                    }
                }
            }
            return size;
        }

        /**
         * For each blocked cell ('*'), calculates the size of the region it would open
         * if converted to open space. Sum of adjacent unique components + 1.
         */
        private void calculateOptimalMoves() {
            // Reuse set to minimize allocation overhead
            Set<Integer> adjacentComponents = new HashSet<>();

            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] != '*') continue;

                    adjacentComponents.clear();
                    for (int[] dir : directions) {
                        int nr = r + dir[0];
                        int nc = c + dir[1];
                        if (isValid(nr, nc) && grid[nr][nc] == '.') {
                            adjacentComponents.add(componentIds[nr][nc]);
                        }
                    }

                    int totalSize = 1; // The cell itself becomes open
                    for (int compId : adjacentComponents) {
                        totalSize += componentSizes.get(compId);
                    }
                    result[r][c] = totalSize;
                }
            }
        }

        /**
         * Formats the result grid according to problem specifications and prints it.
         */
        private void formatAndPrintOutput(PrintWriter out) {
            StringBuilder sb = new StringBuilder();
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (result[r][c] == 0) {
                        sb.append('.');
                    } else {
                        // Problem specification typically requires the last digit
                        sb.append(result[r][c] % 10);
                    }
                }
                sb.append('\n');
            }
            out.print(sb);
        }

        private boolean isValid(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.Arrays;
import java.util.HashSet;
import java.util.Set;
import java.util.StringTokenizer;

/**
 * Refactored Grid Processor.
 * 
 * Improvements made:
 * 1. Encapsulation: Moved static fields into the class and removed global pollution.
 * 2. Naming: Replaced cryptic variable names (c, grp, grpc) with descriptive ones (grid, componentIds, componentSizes).
 * 3. Data Types: Used boolean arrays for the grid to clearly distinguish between walls and empty spaces.
 * 4. Logic Clarity: Replaced the complex array sorting and duplicate removal logic for neighbor calculation 
 *    with a HashSet, which is more readable and robust.
 * 5. I/O Efficiency: Used PrintWriter for buffered output and added basic null checks for input reading.
 * 6. Structure: Organized the code into logical blocks with comments.
 */
public class Test {

    // Grid storage: true represents a wall ('*'), false represents empty space
    private static boolean[][] grid;
    // Stores the component ID for each cell
    private static int[][] componentIds;
    // Stores the size of each component
    private static int[] componentSizes;
    // Counter for the next component ID
    private static int nextComponentId = 0;

    public static void main(String[] args) throws IOException {
        // Use BufferedReader for fast input reading
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        // Use PrintWriter for buffered output
        PrintWriter out = new PrintWriter(System.out);

        // Read dimensions N and M
        String line = br.readLine();
        if (line != null && !line.trim().isEmpty()) {
            StringTokenizer st = new StringTokenizer(line);
            int n = Integer.parseInt(st.nextToken());
            int m = Integer.parseInt(st.nextToken());

            // Initialize grid with padding (size n+2 x m+2)
            // Padding ensures we don't need boundary checks during traversal
            grid = new boolean[n + 2][m + 2];

            // Fill padding with walls (true)
            for (int i = 0; i <= n + 1; i++) {
                Arrays.fill(grid[i], true);
            }

            // Read grid data
            for (int i = 1; i <= n; i++) {
                String row = br.readLine();
                if (row != null) {
                    for (int j = 1; j <= m; j++) {
                        // '*' is a wall (true), anything else is empty (false)
                        // Added bounds check for safety
                        if (j - 1 < row.length()) {
                            grid[i][j] = (row.charAt(j - 1) == '*');
                        }
                    }
                }
            }

            // Initialize component tracking arrays
            componentIds = new int[n + 2][m + 2];
            for (int[] row : componentIds) {
                Arrays.fill(row, -1);
            }
            // Max possible components is n*m. 
            // We allocate slightly more to be safe.
            componentSizes = new int[(n * m) + 1];

            // Identify connected components using DFS
            for (int i = 1; i <= n; i++) {
                for (int j = 1; j <= m; j++) {
                    // If it's not a wall and not yet visited
                    if (!grid[i][j] && componentIds[i][j] == -1) {
                        int currentId = nextComponentId;

                        // Mark start node with current ID
                        componentIds[i][j] = currentId;
                        componentSizes[currentId]++;

                        // Traverse connected cells
                        dfs(i, j);

                        // Move to next component ID
                        nextComponentId++;
                    }
                }
            }

            // Process and print output
            for (int i = 1; i <= n; i++) {
                StringBuilder sb = new StringBuilder();
                for (int j = 1; j <= m; j++) {
                    if (grid[i][j]) {
                        sb.append('*');
                    } else {
                        // Calculate value based on neighbor components
                        // We need the sum of sizes of unique adjacent components
                        Set<Integer> neighborComponents = new HashSet<>();

                        // Check 4 directions: Up, Down, Left, Right
                        // Note: Padding handles boundaries automatically
                        int[] dr = {-1, 1, 0, 0}; 
                        int[] dc = {0, 0, -1, 1}; 

                        for (int k = 0; k < 4; k++) {
                            int r = i + dr[k];
                            int c = j + dc[k];

                            // If neighbor is not a wall, it belongs to a component
                            if (!grid[r][c]) {
                                neighborComponents.add(componentIds[r][c]);
                            }
                        }

                        int sum = 0;
                        for (int id : neighborComponents) {
                            sum += componentSizes[id];
                        }

                        // Modulo 10 and convert to char digit
                        int result = sum % 10;
                        sb.append((char) (result + '0'));
                    }
                }
                out.println(sb.toString());
            }
        }

        out.flush();
    }

    /**
     * Depth First Search to identify and mark connected components.
     * 
     * @param r Current row index
     * @param c Current column index
     */
    private static void dfs(int r, int c) {
        // The ID of the component currently being explored
        int currentId = componentIds[r][c];

        // Check Left Neighbor
        if (!grid[r][c - 1] && componentIds[r][c - 1] == -1) {
            componentIds[r][c - 1] = currentId;
            componentSizes[currentId]++;
            dfs(r, c - 1);
        }

        // Check Up Neighbor
        if (!grid[r - 1][c] && componentIds[r - 1][c] == -1) {
            componentIds[r - 1][c] = currentId;
            componentSizes[currentId]++;
            dfs(r - 1, c);
        }

        // Check Down Neighbor
        if (!grid[r + 1][c] && componentIds[r + 1][c] == -1) {
            componentIds[r + 1][c] = currentId;
            componentSizes[currentId]++;
            dfs(r + 1, c);
        }

        // Check Right Neighbor
        if (!grid[r][c + 1] && componentIds[r][c + 1] == -1) {
            componentIds[r][c + 1] = currentId;
            componentSizes[currentId]++;
            dfs(r, c + 1);
        }
    }
}

import java.io.*;
import java.util.*;

public class Solution {
    private static final int[] DR = {-1, 1, 0, 0};
    private static final int[] DC = {0, 0, -1, 1};

    private final int rows;
    private final int cols;
    private final char[][] grid;
    private final int[][] componentIds;
    private final int[] componentSizes;
    private int componentCount = 0;

    public Solution(int rows, int cols, char[][] grid) {
        this.rows = rows;
        this.cols = cols;
        this.grid = grid;
        this.componentIds = new int[rows][cols];
        // Maximum possible components is (rows * cols + 1) / 2. 
        // We allocate rows * cols + 1 for safety. Index 0 is unused.
        this.componentSizes = new int[rows * cols + 1];
    }

    public int[][] solve() {
        labelConnectedComponents();
        int[][] result = new int[rows][cols];
        computeWallExpansionSizes(result);
        return result;
    }

    private void labelConnectedComponents() {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '.' && componentIds[r][c] == 0) {
                    bfsLabel(r, c);
                }
            }
        }
    }

    private void bfsLabel(int startR, int startC) {
        int currentId = ++componentCount;
        Queue<Point> queue = new ArrayDeque<>();
        queue.offer(new Point(startR, startC));
        componentIds[startR][startC] = currentId;
        int size = 0;

        while (!queue.isEmpty()) {
            Point curr = queue.poll();
            size++;

            for (int i = 0; i < 4; i++) {
                int nr = curr.r + DR[i];
                int nc = curr.c + DC[i];
                if (inBounds(nr, nc) && grid[nr][nc] == '.' && componentIds[nr][nc] == 0) {
                    componentIds[nr][nc] = currentId;
                    queue.offer(new Point(nr, nc));
                }
            }
        }
        componentSizes[currentId] = size;
    }

    private boolean inBounds(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    private void computeWallExpansionSizes(int[][] result) {
        int[] seenIds = new int[4]; // Maximum 4 neighbors
        int seenCount = 0;

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] != '.') {
                    int combinedSize = 1; // The wall cell itself
                    seenCount = 0;
                    for (int i = 0; i < 4; i++) {
                        int nr = r + DR[i];
                        int nc = c + DC[i];
                        if (inBounds(nr, nc)) {
                            int id = componentIds[nr][nc];
                            if (id != 0 && !contains(seenIds, seenCount, id)) {
                                combinedSize += componentSizes[id];
                                seenIds[seenCount++] = id;
                            }
                        }
                    }
                    result[r][c] = combinedSize % 10;
                }
            }
        }
    }

    private boolean contains(int[] arr, int count, int val) {
        for (int i = 0; i < count; i++) {
            if (arr[i] == val) return true;
        }
        return false;
    }

    private static final class Point {
        final int r, c;
        Point(int r, int c) { this.r = r; this.c = c; }
    }

    public static void main(String[] args) {
        MyScanner sc = new MyScanner();
        PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out));
        try {
            int n = sc.nextInt();
            int m = sc.nextInt();
            char[][] maze = new char[n][m];
            for (int i = 0; i < n; i++) {
                maze[i] = sc.next().toCharArray();
            }

            Solution solver = new Solution(n, m, maze);
            int[][] result = solver.solve();

            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    out.print(result[i][j]);
                }
                out.println();
            }
        } catch (Exception e) {
            System.err.println("Error: " + e.getMessage());
            e.printStackTrace();
        } finally {
            out.flush();
            out.close();
        }
    }

    public static class MyScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public MyScanner() {
            this.br = new BufferedReader(new InputStreamReader(System.in));
        }

        public String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            String s = next();
            return (s == null) ? 0 : Integer.parseInt(s);
        }

        public long nextLong() {
            String s = next();
            return (s == null) ? 0L : Long.parseLong(s);
        }

        public double nextDouble() {
            String s = next();
            return (s == null) ? 0.0 : Double.parseDouble(s);
        }

        public String nextLine() {
            String str = "";
            try {
                str = br.readLine();
            } catch (IOException e) {
                throw new RuntimeException(e);
            }
            return str;
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.OutputStream;
import java.io.PrintWriter;
import java.util.ArrayDeque;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Queue;
import java.util.Set;
import java.util.StringTokenizer;

public class Main {

    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        FastScanner in = new FastScanner(inputStream);
        PrintWriter out = new PrintWriter(outputStream);

        GridSolver solver = new GridSolver();
        solver.solve(in, out);

        out.close();
    }

    /**
     * Solver class responsible for processing the grid logic.
     * Encapsulates the algorithm to identify connected components and calculate values.
     */
    static class GridSolver {
        // Direction vectors for moving up, right, down, left
        private static final int[] DR = {-1, 0,  1, 0};
        private static final int[] DC = {0,  1,  0, -1};

        public void solve(FastScanner in, PrintWriter out) {
            int n = in.nextInt();
            int m = in.nextInt();

            char[][] grid = new char[n][m];
            char[][] originalGrid = new char[n][m];

            // Read the grid and store a copy of the original state
            for (int i = 0; i < n; i++) {
                String row = in.next();
                for (int j = 0; j < m; j++) {
                    char c = row.charAt(j);
                    grid[i][j] = c;
                    originalGrid[i][j] = c;
                }
            }

            // Maps cell coordinates to a component ID
            int[][] componentIds = new int[n][m];
            // Maps component ID to its size (number of cells)
            Map<Integer, Integer> componentSizes = new HashMap<>();
            int nextId = 1;

            // Identify connected components of '.' (empty spaces)
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    if (grid[i][j] == '.') {
                        // Perform BFS to find the component and mark it
                        int size = bfs(grid, componentIds, i, j, nextId, n, m);
                        componentSizes.put(nextId, size);
                        nextId++;
                    }
                }
            }

            // Generate the output based on the problem logic
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    if (originalGrid[i][j] == '.') {
                        // If the cell was originally empty, keep it as '.'
                        out.print('.');
                    } else {
                        // If the cell was originally a wall/obstacle, calculate value
                        Set<Integer> neighborIds = new HashSet<>();

                        // Check all 4 neighbors
                        for (int dir = 0; dir < 4; dir++) {
                            int ni = i + DR[dir];
                            int nj = j + DC[dir];

                            if (isValid(ni, nj, n, m)) {
                                int id = componentIds[ni][nj];
                                // If neighbor belongs to a component, add its ID to the set
                                if (id != 0) {
                                    neighborIds.add(id);
                                }
                            }
                        }

                        // Calculate sum of sizes of unique adjacent components + 1
                        int totalSize = 1; 
                        for (int id : neighborIds) {
                            totalSize += componentSizes.get(id);
                        }

                        out.print(totalSize % 10);
                    }
                }
                out.println();
            }
        }

        /**
         * Performs BFS to find the size of the connected component starting at (startR, startC).
         * Marks visited cells in 'grid' by changing them to '#' and assigns their ID in 'componentIds'.
         */
        private int bfs(char[][] grid, int[][] componentIds, int startR, int startC, int id, int n, int m) {
            Queue<Point> queue = new ArrayDeque<>();
            queue.add(new Point(startR, startC));

            // Mark start node as visited
            grid[startR][startC] = '#';
            componentIds[startR][startC] = id;
            int size = 1;

            while (!queue.isEmpty()) {
                Point current = queue.poll();
                int r = current.r;
                int c = current.c;

                for (int dir = 0; dir < 4; dir++) {
                    int nr = r + DR[dir];
                    int nc = c + DC[dir];

                    if (isValid(nr, nc, n, m) && grid[nr][nc] == '.') {
                        // Mark neighbor as visited
                        grid[nr][nc] = '#';
                        componentIds[nr][nc] = id;
                        size++;
                        queue.add(new Point(nr, nc));
                    }
                }
            }
            return size;
        }

        /**
         * Checks if coordinates are within the grid boundaries.
         */
        private boolean isValid(int r, int c, int n, int m) {
            return r >= 0 && r < n && c >= 0 && c < m;
        }

        /**
         * Helper class to represent a coordinate point.
         */
        private static class Point {
            int r, c;

            public Point(int r, int c) {
                this.r = r;
                this.c = c;
            }
        }
    }

    /**
     * FastScanner helper class for efficient input reading.
     */
    static class FastScanner {
        BufferedReader reader;
        StringTokenizer tokenizer;

        public FastScanner(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) {
        new Main().run();
    }

    /**
     * Entry point for I/O setup and execution.
     */
    public void run() {
        FastScanner scanner = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out));
        try {
            solve(scanner, out);
        } finally {
            out.flush();
        }
    }

    /**
     * Core logic: reads grid, identifies connected components, computes answers, and prints output.
     */
    private void solve(FastScanner scanner, PrintWriter out) {
        int rows = scanner.nextInt();
        int cols = scanner.nextInt();

        // Convert to char[][] for O(1) access and better performance
        char[][] grid = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            grid[i] = scanner.next().toCharArray();
        }

        // Tracks which connected component each '.' cell belongs to
        int[][] componentId = new int[rows][cols];
        for (int[] row : componentId) {
            Arrays.fill(row, -1);
        }

        // Stores the size of each component. Max components = rows * cols
        int[] componentSizes = new int[rows * cols];
        int componentCount = 0;

        // Direction vectors for up, down, left, right
        int[] dr = {-1, 1, 0, 0};
        int[] dc = {0, 0, -1, 1};

        // 1. Identify connected components of '.' cells
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '.' && componentId[r][c] == -1) {
                    bfs(grid, componentId, r, c, componentCount, rows, cols, dr, dc, componentSizes);
                    componentCount++;
                }
            }
        }

        // 2. Generate output grid
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '.') {
                    out.print('.');
                } else {
                    // '*' cells: sum sizes of adjacent unique components + 1 (for itself)
                    int totalSize = 1;
                    int[] adjacentIds = new int[4];
                    int adjCount = 0;

                    for (int k = 0; k < 4; k++) {
                        int nr = r + dr[k];
                        int nc = c + dc[k];

                        if (nr >= 0 && nr < rows && nc >= 0 && nc < cols && grid[nr][nc] == '.') {
                            int id = componentId[nr][nc];
                            // Manual deduplication to avoid HashSet overhead
                            boolean exists = false;
                            for (int i = 0; i < adjCount; i++) {
                                if (adjacentIds[i] == id) {
                                    exists = true;
                                    break;
                                }
                            }
                            if (!exists) {
                                adjacentIds[adjCount++] = id;
                            }
                        }
                    }

                    for (int i = 0; i < adjCount; i++) {
                        totalSize += componentSizes[adjacentIds[i]];
                    }
                    out.print(totalSize % 10);
                }
            }
            out.println();
        }
    }

    /**
     * Iterative BFS to find connected component size and assign IDs.
     * Replaces recursive DFS to prevent StackOverflowError on large grids.
     */
    private void bfs(char[][] grid, int[][] componentId, int startR, int startC,
                     int compIdVal, int rows, int cols, int[] dr, int[] dc, int[] componentSizes) {
        Queue<int[]> queue = new ArrayDeque<>();
        queue.add(new int[]{startR, startC});
        componentId[startR][startC] = compIdVal;
        int size = 0;

        while (!queue.isEmpty()) {
            int[] curr = queue.poll();
            size++;
            for (int k = 0; k < 4; k++) {
                int nr = curr[0] + dr[k];
                int nc = curr[1] + dc[k];

                if (nr >= 0 && nr < rows && nc >= 0 && nc < cols &&
                    grid[nr][nc] == '.' && componentId[nr][nc] == -1) {
                    componentId[nr][nc] = compIdVal;
                    queue.add(new int[]{nr, nc});
                }
            }
        }
        componentSizes[compIdVal] = size;
    }

    /**
     * Efficient input reader for competitive programming / large datasets.
     */
    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        public String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            String token = next();
            if (token == null) throw new NoSuchElementException();
            return Integer.parseInt(token);
        }
    }
}

