/**
 * Encapsulates the core logic for processing the grid.
 * Separates concerns into well-named, single-responsibility methods.
 */
class GridProcessor {
    private static final char EMPTY_CHAR = '.';
    private static final char BLOCK_CHAR = '*';
    private static final int DIGIT_BASE = 10;
    private static final char ZERO_CHAR = '0';
    private static final int[][] DIRECTIONS = {{-1, 0}, {0, -1}, {0, 1}, {1, 0}};

    public void process(InputReader in, PrintWriter out) {
        int rows = in.nextInt();
        int cols = in.nextInt();

        char[][] grid = readGrid(in, rows);
        int[][] componentIds = findConnectedComponents(grid, rows, cols);
        int[] componentSizes = computeComponentSizes(componentIds);
        char[][] result = calculateReplacements(grid, componentIds, componentSizes, rows, cols);
        printResult(result, out);
    }

    private char[][] readGrid(InputReader in, int rows) {
        char[][] grid = new char[rows][];
        for (int i = 0; i < rows; i++) {
            grid[i] = in.next().toCharArray();
        }
        return grid;
    }

    private int[][] findConnectedComponents(char[][] grid, int rows, int cols) {
        int[][] componentIds = new int[rows][cols];
        int componentCount = 0;

        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == EMPTY_CHAR && componentIds[i][j] == 0) {
                    componentCount++;
                    traverseComponent(grid, componentIds, i, j, componentCount, rows, cols);
                }
            }
        }
        return componentIds;
    }

    /**
     * Uses iterative DFS to prevent StackOverflowError on large grids.
     */
    private void traverseComponent(char[][] grid, int[][] componentIds, int startI, int startJ, 
                                   int componentCount, int rows, int cols) {
        Deque<int[]> stack = new ArrayDeque<>();
        stack.push(new int[]{startI, startJ});
        componentIds[startI][startJ] = componentCount;

        while (!stack.isEmpty()) {
            int[] current = stack.pop();
            int i = current[0];
            int j = current[1];

            for (int[] dir : DIRECTIONS) {
                int ni = i + dir[0];
                int nj = j + dir[1];
                if (isValid(ni, nj, rows, cols) && grid[ni][nj] == EMPTY_CHAR && componentIds[ni][nj] == 0) {
                    componentIds[ni][nj] = componentCount;
                    stack.push(new int[]{ni, nj});
                }
            }
        }
    }

    private int[] computeComponentSizes(int[][] componentIds) {
        int maxId = 0;
        for (int[] row : componentIds) {
            for (int id : row) {
                if (id > maxId) maxId = id;
            }
        }

        int[] sizes = new int[maxId + 1];
        for (int[] row : componentIds) {
            for (int id : row) {
                if (id > 0) sizes[id]++;
            }
        }
        return sizes;
    }

    private char[][] calculateReplacements(char[][] grid, int[][] componentIds, int[] componentSizes, 
                                           int rows, int cols) {
        char[][] result = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == EMPTY_CHAR) {
                    result[i][j] = EMPTY_CHAR;
                } else {
                    int adjacentSum = calculateAdjacentComponentSum(grid, componentIds, componentSizes, i, j, rows, cols);
                    result[i][j] = (char) ((1 + adjacentSum) % DIGIT_BASE + ZERO_CHAR);
                }
            }
        }
        return result;
    }

    private int calculateAdjacentComponentSum(char[][] grid, int[][] componentIds, int[] componentSizes, 
                                              int i, int j, int rows, int cols) {
        int sum = 0;
        Set<Integer> visitedComponents = new HashSet<>();

        for (int[] dir : DIRECTIONS) {
            int ni = i + dir[0];
            int nj = j + dir[1];
            if (isValid(ni, nj, rows, cols) && grid[ni][nj] != BLOCK_CHAR) {
                int compId = componentIds[ni][nj];
                if (compId > 0 && !visitedComponents.contains(compId)) {
                    visitedComponents.add(compId);
                    sum += componentSizes[compId];
                }
            }
        }
        return sum;
    }

    private void printResult(char[][] result, PrintWriter out) {
        for (char[] row : result) {
            out.println(new String(row));
        }
    }

    private boolean isValid(int i, int j, int rows, int cols) {
        return i >= 0 && i < rows && j >= 0 && j < cols;
    }
}

