import java.io.*;
import java.util.*;

/**
 * Analyzes a character grid to identify connected components of '.' cells,
 * then generates a new grid where non-'.' cells are replaced by the sum of
 * the sizes of their adjacent connected components (modulo 10).
 */
public class GridComponentAnalyzer {

    private final BufferedReader reader;
    private final PrintWriter writer;

    public GridComponentAnalyzer(BufferedReader reader, PrintWriter writer) {
        this.reader = reader;
        this.writer = writer;
    }

    /**
     * Orchestrates the reading, processing, and writing of the grid data.
     */
    public void process() throws IOException {
        String line = reader.readLine();
        if (line == null) return;

        String[] dims = line.trim().split("\\s+");
        int rows = Integer.parseInt(dims[0]);
        int cols = Integer.parseInt(dims[1]);

        // Grid with padding to simplify boundary checks during processing
        char[][] grid = new char[rows + 2][cols + 2];
        Arrays.fill(grid[0], '*');
        Arrays.fill(grid[rows + 1], '*');

        for (int i = 1; i <= rows; i++) {
            String rowLine = reader.readLine();
            if (rowLine == null) break;
            grid[i][0] = '*';
            grid[i][cols + 1] = '*';
            System.arraycopy(rowLine.toCharArray(), 0, grid[i], 1, cols);
        }

        int[][] componentIds = new int[rows + 2][cols + 2];
        int[] componentSizes = new int[(rows * cols) + 1];
        int componentCount = 0;

        // Identify connected components of '.' cells
        for (int i = 1; i <= rows; i++) {
            for (int j = 1; j <= cols; j++) {
                if (grid[i][j] == '.' && componentIds[i][j] == 0) {
                    componentCount++;
                    componentSizes[componentCount] = floodFill(grid, componentIds, i, j, componentCount);
                }
            }
        }

        // Generate the output grid based on adjacent component sizes
        char[][] resultGrid = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i + 1][j + 1] == '.') {
                    resultGrid[i][j] = '.';
                } else {
                    int adjacentSum = calculateAdjacentComponentSizeSum(componentIds, componentSizes, i + 1, j + 1);
                    resultGrid[i][j] = (char) ('0' + (adjacentSum % 10));
                }
            }
        }

        for (char[] row : resultGrid) {
            writer.println(new String(row));
        }
        writer.flush();
    }

    /**
     * Iteratively finds all cells in the same connected component as (startX, startY).
     * Uses BFS to prevent StackOverflowError on large grids.
     */
    private int floodFill(char[][] grid, int[][] componentIds, int startX, int startY, int id) {
        int rows = grid.length;
        int cols = grid[0].length;
        int size = 0;

        int[] qx = new int[rows * cols];
        int[] qy = new int[rows * cols];
        int head = 0;
        int tail = 0;

        qx[tail] = startX;
        qy[tail] = startY;
        tail++;
        componentIds[startX][startY] = id;
        size++;

        int[] dx = {-1, 1, 0, 0};
        int[] dy = {0, 0, -1, 1};

        while (head < tail) {
            int x = qx[head];
            int y = qy[head];
            head++;

            for (int k = 0; k < 4; k++) {
                int nx = x + dx[k];
                int ny = y + dy[k];

                if (nx >= 0 && nx < rows && ny >= 0 && ny < cols &&
                    grid[nx][ny] == '.' && componentIds[nx][ny] == 0) {
                    componentIds[nx][ny] = id;
                    size++;
                    qx[tail] = nx;
                    qy[tail] = ny;
                    tail++;
                }
            }
        }
        return size;
    }

    /**
     * Calculates the sum of sizes of unique connected components adjacent to (x, y).
     * Only orthogonal neighbors are considered.
     */
    private int calculateAdjacentComponentSizeSum(int[][] componentIds, int[] componentSizes, int x, int y) {
        int sum = 0;
        int[] neighborIds = new int[4];
        int count = 0;
        int[] dx = {-1, 1, 0, 0};
        int[] dy = {0, 0, -1, 1};

        for (int k = 0; k < 4; k++) {
            int nx = x + dx[k];
            int ny = y + dy[k];
            int id = componentIds[nx][ny];

            if (id > 0) {
                boolean exists = false;
                for (int m = 0; m < count; m++) {
                    if (neighborIds[m] == id) {
                        exists = true;
                        break;
                    }
                }
                if (!exists) {
                    neighborIds[count++] = id;
                }
            }
        }

        for (int k = 0; k < count; k++) {
            sum += componentSizes[neighborIds[k]];
        }
        return sum;
    }

    public static void main(String[] args) throws IOException {
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
             PrintWriter writer = new PrintWriter(new BufferedOutputStream(System.out))) {
            new GridComponentAnalyzer(reader, writer).process();
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.List;
import java.util.StringTokenizer;

public class TheLabyrinth {

    // Direction vectors for moving up, left, down, right
    private static final int[] DX = {-1, 0, 1, 0};
    private static final int[] DY = {0, -1, 0, 1};

    // Modulo constant for output as per original logic
    private static final int MODULO = 10;

    private int rows;
    private int cols;
    private char[][] grid;
    private int[][] wallScores;
    private boolean[][] visited;

    public static void main(String[] args) {
        // Encapsulate execution in an instance to avoid static state pollution
        // and improve testability/reusability.
        new TheLabyrinth().run();
    }

    public void run() {
        // Use try-with-resources for automatic resource management
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
             PrintWriter out = new PrintWriter(System.out)) {

            // Read dimensions
            String line = br.readLine();
            while (line != null && line.trim().isEmpty()) {
                line = br.readLine();
            }

            if (line != null) {
                StringTokenizer st = new StringTokenizer(line);
                if (st.hasMoreTokens()) {
                    rows = Integer.parseInt(st.nextToken());
                    cols = Integer.parseInt(st.nextToken());
                }
            }

            // Initialize data structures
            grid = new char[rows][cols];
            wallScores = new int[rows][cols];
            visited = new boolean[rows][cols];

            // Read the grid
            for (int i = 0; i < rows; i++) {
                String rowStr = br.readLine();
                if (rowStr != null) {
                    grid[i] = rowStr.toCharArray();
                }
            }

            // Process the grid
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    // Start BFS for unvisited open spaces
                    if (grid[i][j] == '.' && !visited[i][j]) {
                        processComponent(i, j);
                    }
                }
            }

            // Output the result
            for (int i = 0; i < rows; i++) {
                StringBuilder sb = new StringBuilder();
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j] == '*') {
                        sb.append(wallScores[i][j] % MODULO);
                    } else {
                        sb.append('.');
                    }
                }
                out.println(sb);
            }
            out.flush();

        } catch (IOException e) {
            System.err.println("Error reading input: " + e.getMessage());
        }
    }

    /**
     * Performs a BFS starting from (startRow, startCol) to find a connected component
     * of '.' cells. It updates the scores of adjacent '*' cells based on the component size.
     * This method encapsulates the logic previously scattered across main, BFS, and fill methods.
     */
    private void processComponent(int startRow, int startCol) {
        ArrayDeque<Integer> queue = new ArrayDeque<>();
        List<Integer> adjacentWalls = new ArrayList<>();
        int componentSize = 0;

        // Encode coordinates to a single integer (row * cols + col) for efficient storage
        queue.add(encode(startRow, startCol));
        visited[startRow][startCol] = true;
        componentSize++;

        while (!queue.isEmpty()) {
            int current = queue.poll();
            int r = current / cols;
            int c = current % cols;

            for (int k = 0; k < 4; k++) {
                int nr = r + DX[k];
                int nc = c + DY[k];

                if (isValid(nr, nc)) {
                    if (grid[nr][nc] == '.') {
                        if (!visited[nr][nc]) {
                            visited[nr][nc] = true;
                            queue.add(encode(nr, nc));
                            componentSize++;
                        }
                    } else if (grid[nr][nc] == '*') {
                        // If we find a wall, record it and mark as visited to prevent 
                        // duplicate processing within this BFS.
                        // Note: We will reset visited status for walls later to allow 
                        // counting by other disjoint components.
                        if (!visited[nr][nc]) {
                            visited[nr][nc] = true;
                            adjacentWalls.add(encode(nr, nc));
                        }
                    }
                }
            }
        }

        // Update wall scores and reset their visited status.
        // This replicates the logic of the original 'fill' method.
        for (int wallEncoded : adjacentWalls) {
            int wr = wallEncoded / cols;
            int wc = wallEncoded % cols;
            wallScores[wr][wc] += componentSize;
            visited[wr][wc] = false; 
        }
    }

    private boolean isValid(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    private int encode(int r, int c) {
        return r * cols + c;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.ArrayDeque;
import java.util.Queue;
import java.util.StringTokenizer;

/**
 * Processes a grid to identify connected components of '.' characters.
 * Replaces non-'.' characters with the sum of adjacent component sizes + 1, modulo 10.
 */
public class ConnectedComponentGridProcessor {

    private static final int[] DR = {-1, 1, 0, 0};
    private static final int[] DC = {0, 0, -1, 1};

    public static void main(String[] args) throws IOException {
        FastScanner scanner = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out);

        int rows = scanner.nextInt();
        int cols = scanner.nextInt();
        char[][] grid = new char[rows][];
        for (int i = 0; i < rows; i++) {
            grid[i] = scanner.next().toCharArray();
        }

        char[][] result = processGrid(grid, rows, cols);

        for (char[] row : result) {
            out.println(row);
        }
        out.flush();
    }

    /**
     * Identifies connected components and transforms the grid based on adjacent component sizes.
     */
    private static char[][] processGrid(char[][] grid, int rows, int cols) {
        int[][] componentIds = new int[rows][cols];
        int[] componentSizes = new int[rows * cols + 1]; // 1-based indexing for direct mapping
        int componentCount = 0;

        // Step 1: Identify connected components using BFS
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '.' && componentIds[r][c] == 0) {
                    componentCount++;
                    componentSizes[componentCount] = bfs(grid, componentIds, r, c, componentCount, rows, cols);
                }
            }
        }

        // Step 2: Transform the grid based on adjacent component sizes
        char[][] result = new char[rows][cols];
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '.') {
                    result[r][c] = '.';
                } else {
                    int adjacentSum = 0;
                    boolean[] seenComponents = new boolean[componentCount + 1];
                    for (int d = 0; d < 4; d++) {
                        int nr = r + DR[d];
                        int nc = c + DC[d];
                        if (isValid(nr, nc, rows, cols) && grid[nr][nc] == '.') {
                            int compId = componentIds[nr][nc];
                            if (!seenComponents[compId]) {
                                seenComponents[compId] = true;
                                adjacentSum += componentSizes[compId];
                            }
                        }
                    }
                    result[r][c] = (char) ((adjacentSum + 1) % 10 + '0');
                }
            }
        }
        return result;
    }

    /**
     * Performs BFS to find the size of a connected component and assigns component IDs.
     */
    private static int bfs(char[][] grid, int[][] componentIds, int startR, int startC, int compId, int rows, int cols) {
        int size = 0;
        Queue<int[]> queue = new ArrayDeque<>();
        queue.offer(new int[]{startR, startC});
        componentIds[startR][startC] = compId;
        size++;

        while (!queue.isEmpty()) {
            int[] current = queue.poll();
            for (int d = 0; d < 4; d++) {
                int nr = current[0] + DR[d];
                int nc = current[1] + DC[d];
                if (isValid(nr, nc, rows, cols) && grid[nr][nc] == '.' && componentIds[nr][nc] == 0) {
                    componentIds[nr][nc] = compId;
                    size++;
                    queue.offer(new int[]{nr, nc});
                }
            }
        }
        return size;
    }

    private static boolean isValid(int r, int c, int rows, int cols) {
        return r >= 0 && c >= 0 && r < rows && c < cols;
    }

    /**
     * Lightweight fast I/O helper to avoid overhead of java.util.Scanner.
     */
    private static class FastScanner {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastScanner(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
            tokenizer = null;
        }

        public String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                String line = reader.readLine();
                if (line == null) throw new IOException("Unexpected end of input");
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}

import java.io.*;
import java.util.*;

public class Main {
    // Constants for direction vectors and modulo operation
    private static final int[][] DIRECTIONS = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};
    private static final int MODULO = 10;

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner(System.in);
        new Main().run(scanner);
    }

    /**
     * Orchestrates the grid processing logic.
     */
    void run(FastScanner scanner) {
        int n = scanner.nextInt();
        int m = scanner.nextInt();
        char[][] grid = new char[n][];
        for (int i = 0; i < n; i++) {
            grid[i] = scanner.next().toCharArray();
        }

        int[][] componentIds = new int[n][m];
        int currentComponentId = 1;

        // 1. Identify connected components of '.' cells
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == '.' && componentIds[i][j] == 0) {
                    dfs(grid, componentIds, i, j, currentComponentId);
                    currentComponentId++;
                }
            }
        }

        // 2. Count the size of each component
        int[] componentSizes = new int[currentComponentId + 1];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                int id = componentIds[i][j];
                if (id != 0) {
                    componentSizes[id]++;
                }
            }
        }

        // 3. Process '*' cells by summing adjacent component sizes
        boolean[] visitedComponent = new boolean[currentComponentId + 1];
        StringBuilder output = new StringBuilder(n * m + n);

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == '*') {
                    int sum = 1; // Base value as per original logic
                    for (int[] dir : DIRECTIONS) {
                        int ni = i + dir[0];
                        int nj = j + dir[1];
                        if (ni >= 0 && ni < n && nj >= 0 && nj < m) {
                            int compId = componentIds[ni][nj];
                            if (compId != 0 && !visitedComponent[compId]) {
                                sum += componentSizes[compId];
                                visitedComponent[compId] = true;
                            }
                        }
                    }
                    // Reset visited flags for the next '*' cell
                    for (int[] dir : DIRECTIONS) {
                        int ni = i + dir[0];
                        int nj = j + dir[1];
                        if (ni >= 0 && ni < n && nj >= 0 && nj < m) {
                            int compId = componentIds[ni][nj];
                            if (compId != 0) {
                                visitedComponent[compId] = false;
                            }
                        }
                    }
                    grid[i][j] = (char) ((sum % MODULO) + '0');
                }
                output.append(grid[i][j]);
            }
            output.append('\n');
        }
        System.out.print(output);
    }

    /**
     * Iterative DFS to label connected components.
     * Uses an explicit stack to prevent StackOverflowError on large grids.
     */
    private void dfs(char[][] grid, int[][] componentIds, int startR, int startC, int id) {
        int rows = grid.length;
        int cols = grid[0].length;
        int[] stackR = new int[rows * cols];
        int[] stackC = new int[rows * cols];
        int top = 0;

        stackR[top] = startR;
        stackC[top] = startC;
        top++;
        componentIds[startR][startC] = id;

        while (top > 0) {
            top--;
            int r = stackR[top];
            int c = stackC[top];

            for (int[] dir : DIRECTIONS) {
                int nr = r + dir[0];
                int nc = c + dir[1];
                if (nr >= 0 && nr < rows && nc >= 0 && nc < cols
                        && componentIds[nr][nc] == 0 && grid[nr][nc] != '*') {
                    componentIds[nr][nc] = id;
                    stackR[top] = nr;
                    stackC[top] = nc;
                    top++;
                }
            }
        }
    }

    /**
     * Fast I/O helper class for competitive programming style inputs.
     */
    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer stk;

        public FastScanner(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        String next() {
            while (stk == null || !stk.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    stk = new StringTokenizer(line, " ");
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return stk.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.ArrayList;
import java.util.LinkedList;
import java.util.List;
import java.util.Queue;
import java.util.StringTokenizer;

/**
 * Refactored version of the grid processing algorithm.
 * 
 * Improvements made:
 * 1. Encapsulation: Removed static fields; state is now managed within the class instance.
 * 2. Naming: Renamed classes and variables for better semantic clarity (e.g., C3 -> MinesweeperSolver, Index -> Point).
 * 3. DRY Principle: Replaced repetitive neighbor-checking blocks with a direction array loop.
 * 4. Readability: Extracted logic into distinct methods (run, bfs).
 * 5. Resource Management: Added proper closing of IO resources.
 * 6. Safety: Added basic checks for input parsing.
 */
public class MinesweeperSolver {

    /**
     * Represents a coordinate on the grid.
     */
    static class Point {
        int r, c;

        Point(int r, int c) {
            this.r = r;
            this.c = c;
        }
    }

    // Direction vectors for moving Up, Down, Left, Right
    private static final int[] DR = {-1, 1, 0, 0};
    private static final int[] DC = {0, 0, -1, 1};

    private int rows;
    private int cols;
    private char[][] grid;
    private int[][] result;
    private boolean[][] visited;

    public static void main(String[] args) throws IOException {
        MinesweeperSolver solver = new MinesweeperSolver();
        solver.run();
    }

    public void run() throws IOException {
        // Initialize IO
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter out = new PrintWriter(System.out);

        try {
            String line = br.readLine();
            if (line == null) return;

            StringTokenizer st = new StringTokenizer(line);
            if (!st.hasMoreTokens()) return;

            this.rows = Integer.parseInt(st.nextToken());
            this.cols = Integer.parseInt(st.nextToken());

            this.grid = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                String rowStr = br.readLine();
                if (rowStr != null) {
                    for (int j = 0; j < cols; j++) {
                        // Handle potential short lines gracefully
                        if (j < rowStr.length()) {
                            grid[i][j] = rowStr.charAt(j);
                        } else {
                            grid[i][j] = ' '; 
                        }
                    }
                }
            }

            this.result = new int[rows][cols];
            this.visited = new boolean[rows][cols];

            // Iterate through every cell in the grid
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    // Start BFS if cell is empty and not yet visited
                    if (grid[i][j] == '.' && !visited[i][j]) {
                        bfs(i, j);
                    }
                }
            }

            // Build Output
            StringBuilder sb = new StringBuilder();
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j] == '.') {
                        sb.append('.');
                    } else {
                        // Apply logic: (count + 1) % 10
                        sb.append((result[i][j] + 1) % 10);
                    }
                }
                sb.append('\n');
            }
            out.print(sb);

        } finally {
            out.flush();
            out.close();
            br.close();
        }
    }

    /**
     * Performs BFS starting from (startR, startC) to count connected empty cells
     * and identify adjacent mines.
     */
    private void bfs(int startR, int startC) {
        Queue<Point> queue = new LinkedList<>();
        queue.add(new Point(startR, startC));

        int count = 0;
        List<Point> adjacentMines = new ArrayList<>();

        while (!queue.isEmpty()) {
            Point current = queue.poll();
            int r = current.r;
            int c = current.c;

            count++;
            visited[r][c] = true;

            // Explore all 4 neighbors
            for (int k = 0; k < 4; k++) {
                int nr = r + DR[k];
                int nc = c + DC[k];

                // Check boundaries
                if (nr >= 0 && nr < rows && nc >= 0 && nc < cols) {
                    if (!visited[nr][nc]) {
                        visited[nr][nc] = true; // Mark as visited immediately

                        if (grid[nr][nc] == '*') {
                            adjacentMines.add(new Point(nr, nc));
                        } else {
                            queue.add(new Point(nr, nc));
                        }
                    }
                }
            }
        }

        // Update result for adjacent mines and reset their visited status
        // so they can be counted by other components if necessary.
        for (Point mine : adjacentMines) {
            result[mine.r][mine.c] += count;
            visited[mine.r][mine.c] = false;
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;

/**
 * Refactored version of Edu5B.
 * 
 * Improvements made:
 * 1. Encapsulation: Moved static fields to instance fields to allow multiple instances 
 *    and avoid state pollution between runs.
 * 2. Naming: Renamed variables and methods to be descriptive (e.g., 'nX' -> 'DX', 'dfs' -> 'markConnectedRegion').
 * 3. Dead Code Removal: Removed unused 'Num' class and 'Random' instance.
 * 4. Input Parsing: Used robust splitting for integers and try-with-resources for I/O streams.
 * 5. Logic Separation: Split the logic into clear methods: initialization, solving, marking regions, 
 *    propagating counts, and printing results.
 * 6. Constants: Defined direction vectors as constants.
 */
public class Edu5B {

    // Instance fields to encapsulate state
    private int n, m;
    private char[][] grid;
    private int[][] bombValues; // Corresponds to 'ans' in original
    private int[][] bombRegionHistory; // Corresponds to 'visited' in original
    private int currentRegionId;
    private int currentRegionSize;

    // Direction vectors for moving up, down, left, right
    private static final int[] DX = {1, -1, 0, 0};
    private static final int[] DY = {0, 0, 1, -1};

    public static void main(String[] args) throws IOException {
        // Use try-with-resources for automatic resource management
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
             PrintWriter out = new PrintWriter(System.out)) {

            Edu5B solver = new Edu5B();
            solver.init(br);
            solver.solve(br, out);
            solver.printResult(out);
        }
    }

    /**
     * Initializes the solver and reads dimensions.
     */
    private void init(BufferedReader br) throws IOException {
        String line = br.readLine();
        if (line == null) return;

        // Robust parsing of n and m to handle multiple spaces
        String[] parts = line.trim().split("\\s+");
        if (parts.length >= 2) {
            n = Integer.parseInt(parts[0]);
            m = Integer.parseInt(parts[1]);
        } else {
            return; // Invalid input format
        }

        grid = new char[n][m];
        bombValues = new int[n][m];
        bombRegionHistory = new int[n][m];
        currentRegionId = 0;
    }

    /**
     * Reads the grid and processes the logic.
     */
    private void solve(BufferedReader br, PrintWriter out) throws IOException {
        // Read the grid
        for (int i = 0; i < n; i++) {
            String row = br.readLine();
            if (row != null) {
                grid[i] = row.toCharArray();
            }
        }

        // Process the grid
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                // If we find an unvisited empty cell ('.'), start processing the region
                if (grid[i][j] == '.') {
                    currentRegionSize = 0;

                    // Pass 1: Count the size of the connected region and mark cells as 'x'
                    markConnectedRegion(i, j);

                    currentRegionId++;

                    // Pass 2: Propagate the region size to adjacent bombs
                    propagateRegionCounts(i, j);
                }
            }
        }
    }

    /**
     * Checks if coordinates are within grid bounds.
     */
    private boolean isValidCoordinate(int r, int c) {
        return r >= 0 && r < n && c >= 0 && c < m;
    }

    /**
     * Recursive DFS to count connected '.' cells and mark them as 'x'.
     */
    private void markConnectedRegion(int r, int c) {
        grid[r][c] = 'x'; // Mark as visited
        currentRegionSize++;

        for (int k = 0; k < 4; k++) {
            int nr = r + DX[k];
            int nc = c + DY[k];

            if (isValidCoordinate(nr, nc) && grid[nr][nc] == '.') {
                markConnectedRegion(nr, nc);
            }
        }
    }

    /**
     * Recursive DFS to traverse the region (marked 'x') and update adjacent bombs.
     */
    private void propagateRegionCounts(int r, int c) {
        grid[r][c] = 'o'; // Mark as processed for this pass to prevent cycles

        for (int k = 0; k < 4; k++) {
            int nr = r + DX[k];
            int nc = c + DY[k];

            if (!isValidCoordinate(nr, nc)) continue;

            char neighbor = grid[nr][nc];

            if (neighbor == '*') {
                // If this bomb hasn't been updated for the current region
                if (bombRegionHistory[nr][nc] != currentRegionId) {
                    bombRegionHistory[nr][nc] = currentRegionId;
                    bombValues[nr][nc] += currentRegionSize;
                }
            } else if (neighbor == 'x') {
                // If neighbor is part of the region (unvisited in this pass), recurse
                propagateRegionCounts(nr, nc);
            }
        }
    }

    /**
     * Prints the final result grid.
     */
    private void printResult(PrintWriter out) {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == '*') {
                    // Add base value 1 as per original logic
                    bombValues[i][j] += 1;
                    sb.append(bombValues[i][j] % 10);
                } else {
                    sb.append('.');
                }
            }
            sb.append("\n");
        }
        out.print(sb);
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import java.util.StringTokenizer;

/**
 * Calculates connected components of '.' cells in a grid and computes
 * a weighted sum for each '*' cell based on adjacent component sizes.
 * 
 * Refactoring improvements:
 * - Removed static state; encapsulated logic in an instance-based class.
 * - Applied standard Java naming conventions (PascalCase for classes, camelCase for variables/methods).
 * - Separated concerns into distinct, testable methods (I/O, traversal, calculation, output).
 * - Fixed non-idiomatic array declarations and variable shadowing.
 * - Used 0-based component indexing to eliminate hacky placeholder values.
 * - Improved resource management and input validation.
 */
public class GridComponentCalculator {

    private int rows;
    private int cols;
    private char[][] grid;
    private boolean[][] visited;
    private int[][] componentIds;
    private List<Integer> componentSizes;

    private static final int[] DX = {0, 0, 1, -1};
    private static final int[] DY = {1, -1, 0, 0};

    /**
     * Orchestrates the pipeline: read input -> find components -> calculate answers -> print output.
     */
    public void run(FastReader sc, PrintWriter out) throws IOException {
        readInput(sc);
        findConnectedComponents();
        int[][] answers = calculateAnswers();
        printOutput(answers, out);
    }

    private void readInput(FastReader sc) throws IOException {
        rows = sc.nextInt();
        cols = sc.nextInt();
        grid = new char[rows][cols];
        visited = new boolean[rows][cols];
        componentIds = new int[rows][cols];

        for (int i = 0; i < rows; i++) {
            String line = sc.next();
            if (line == null || line.length() != cols) {
                throw new IllegalArgumentException("Invalid grid row at index " + i);
            }
            grid[i] = line.toCharArray();
        }
    }

    private void findConnectedComponents() {
        componentSizes = new ArrayList<>();
        int currentComponentId = 0;

        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == '.' && !visited[i][j]) {
                    int size = dfs(i, j, currentComponentId);
                    componentSizes.add(size);
                    currentComponentId++;
                }
            }
        }
    }

    /**
     * Performs DFS to calculate the size of a connected component of '.' cells.
     * Returns the total number of cells in the component.
     */
    private int dfs(int x, int y, int compId) {
        visited[x][y] = true;
        componentIds[x][y] = compId;
        int size = 1;

        for (int d = 0; d < 4; d++) {
            int nx = x + DX[d];
            int ny = y + DY[d];
            if (isValid(nx, ny) && !visited[nx][ny]) {
                size += dfs(nx, ny, compId);
            }
        }
        return size;
    }

    private boolean isValid(int x, int y) {
        return x >= 0 && x < rows && y >= 0 && y < cols && grid[x][y] == '.';
    }

    private int[][] calculateAnswers() {
        int[][] answers = new int[rows][cols];
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == '*') {
                    Set<Integer> adjacentComponents = new HashSet<>();
                    for (int d = 0; d < 4; d++) {
                        int nx = i + DX[d];
                        int ny = j + DY[d];
                        if (isValid(nx, ny)) {
                            adjacentComponents.add(componentIds[nx][ny]);
                        }
                    }

                    int sum = 1; // Count the '*' cell itself
                    for (int compId : adjacentComponents) {
                        sum += componentSizes.get(compId);
                    }
                    answers[i][j] = sum % 10;
                }
            }
        }
        return answers;
    }

    private void printOutput(int[][] answers, PrintWriter out) {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == '.') {
                    out.print('.');
                } else {
                    out.print(answers[i][j]);
                }
            }
            out.println();
        }
    }

    /**
     * Fast I/O helper class optimized for competitive programming and bulk input.
     */
    public static class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastReader(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        public String next() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) {
                    return null;
                }
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

        public int nextInt() throws IOException {
            String s = next();
            if (s == null) {
                throw new IOException("Unexpected end of input");
            }
            return Integer.parseInt(s);
        }
    }

    public static void main(String[] args) throws IOException {
        FastReader sc = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            GridComponentCalculator calculator = new GridComponentCalculator();
            calculator.run(sc, out);
        } finally {
            out.flush();
            out.close();
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.HashSet;
import java.util.Set;

public class TheLabyrinth {

    private final int rows;
    private final int cols;
    private final String[] grid;
    private final int[] parent;
    private final int[] componentSize;

    public TheLabyrinth(int rows, int cols, String[] grid) {
        this.rows = rows;
        this.cols = cols;
        this.grid = grid;
        int totalCells = rows * cols;
        this.parent = new int[totalCells];
        this.componentSize = new int[totalCells];
        initializeDSU();
        buildConnectedComponents();
    }

    private int toIndex(int r, int c) {
        return r * cols + c;
    }

    private void initializeDSU() {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                int idx = toIndex(i, j);
                if (grid[i].charAt(j) == '.') {
                    parent[idx] = idx;
                    componentSize[idx] = 1;
                } else {
                    parent[idx] = -1;
                    componentSize[idx] = 0;
                }
            }
        }
    }

    /**
     * Finds the root of the set containing index idx with path compression.
     */
    private int find(int idx) {
        if (parent[idx] == idx) {
            return idx;
        }
        return parent[idx] = find(parent[idx]);
    }

    /**
     * Unites the sets containing cells (r1, c1) and (r2, c2).
     */
    private void union(int r1, int c1, int r2, int c2) {
        int idx1 = toIndex(r1, c1);
        int idx2 = toIndex(r2, c2);
        int root1 = find(idx1);
        int root2 = find(idx2);
        if (root1 != root2) {
            parent[root1] = root2;
            componentSize[root2] += componentSize[root1];
        }
    }

    /**
     * Traverses the grid and merges adjacent '.' cells into connected components.
     * Checks only down and right to avoid redundant union operations.
     */
    private void buildConnectedComponents() {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i].charAt(j) == '.') {
                    if (i + 1 < rows && grid[i + 1].charAt(j) == '.') {
                        union(i, j, i + 1, j);
                    }
                    if (j + 1 < cols && grid[i].charAt(j + 1) == '.') {
                        union(i, j, i, j + 1);
                    }
                }
            }
        }
    }

    /**
     * Calculates the connectivity value for a wall cell based on adjacent components.
     * Sums the sizes of unique neighboring components (modulo 10), adds 1, and mods 10.
     */
    private int calculateConnectivity(int r, int c) {
        Set<Integer> visitedRoots = new HashSet<>();
        int totalSize = 0;

        int[] dr = {-1, 1, 0, 0};
        int[] dc = {0, 0, -1, 1};

        for (int k = 0; k < 4; k++) {
            int nr = r + dr[k];
            int nc = c + dc[k];

            if (nr >= 0 && nr < rows && nc >= 0 && nc < cols && grid[nr].charAt(nc) == '.') {
                int root = find(toIndex(nr, nc));
                if (!visitedRoots.contains(root)) {
                    visitedRoots.add(root);
                    totalSize += componentSize[root] % 10;
                }
            }
        }

        return (totalSize + 1) % 10;
    }

    /**
     * Generates the solution grid string.
     */
    public String solve() {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i].charAt(j) == '.') {
                    sb.append('.');
                } else {
                    sb.append(calculateConnectivity(i, j));
                }
            }
            sb.append('\n');
        }
        return sb.toString();
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter out = new PrintWriter(System.out);

        String line = br.readLine();
        if (line != null && !line.trim().isEmpty()) {
            String[] parts = line.trim().split("\\s+");
            int rows = Integer.parseInt(parts[0]);
            int cols = Integer.parseInt(parts[1]);

            String[] grid = new String[rows];
            for (int i = 0; i < rows; i++) {
                grid[i] = br.readLine();
            }

            TheLabyrinth solver = new TheLabyrinth(rows, cols, grid);
            out.print(solver.solve());
        }

        out.flush();
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.HashSet;
import java.util.Set;
import java.util.StringTokenizer;

/**
 * Analyzes a grid to compute the sum of adjacent connected component sizes
 * for each non-walkable cell, modulo 10.
 */
public class GridComponentAnalyzer {

    // Direction vectors for Up, Down, Left, Right
    private static final int[] DX = {-1, 1, 0, 0};
    private static final int[] DY = {0, 0, -1, 1};

    public static void main(String[] args) throws IOException {
        // Use try-with-resources for automatic and safe resource management
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
             PrintWriter pw = new PrintWriter(System.out)) {

            String line = br.readLine();
            if (line == null) return;

            StringTokenizer st = new StringTokenizer(line);
            int rows = Integer.parseInt(st.nextToken());
            int cols = Integer.parseInt(st.nextToken());

            char[][] grid = new char[rows][];
            for (int i = 0; i < rows; i++) {
                grid[i] = br.readLine().toCharArray();
            }

            // groupIds[i][j] stores the component ID for cell (i, j). 0 means unvisited.
            int[][] groupIds = new int[rows][cols];
            // groupSizes[id] stores the total size of the component with the given ID.
            int[] groupSizes = new int[rows * cols + 1];
            int currentGroupId = 1;

            StringBuilder output = new StringBuilder();

            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j] == '.') {
                        output.append('.');
                    } else {
                        Set<Integer> adjacentGroupIds = new HashSet<>();

                        // Check all 4 neighbors
                        for (int dir = 0; dir < 4; dir++) {
                            int ni = i + DX[dir];
                            int nj = j + DY[dir];

                            if (isWithinBounds(ni, nj, rows, cols) && grid[ni][nj] == '.') {
                                // If neighbor hasn't been assigned to a group yet, compute it
                                if (groupIds[ni][nj] == 0) {
                                    groupSizes[currentGroupId] = computeComponentSize(
                                            ni, nj, grid, rows, cols, groupIds, currentGroupId);
                                    currentGroupId++;
                                }
                                adjacentGroupIds.add(groupIds[ni][nj]);
                            }
                        }

                        // Sum sizes of unique adjacent components
                        int totalAdjacentSize = 0;
                        for (int groupId : adjacentGroupIds) {
                            totalAdjacentSize += groupSizes[groupId];
                        }
                        output.append(totalAdjacentSize % 10);
                    }
                    output.append('\n');
                }
            }

            pw.println(output);
        }
    }

    private static boolean isWithinBounds(int x, int y, int rows, int cols) {
        return x >= 0 && x < rows && y >= 0 && y < cols;
    }

    /**
     * Computes the size of a connected component of '.' cells using DFS.
     * Assigns all visited cells to the given groupId.
     */
    private static int computeComponentSize(int startX, int startY, char[][] grid,
                                            int rows, int cols, int[][] groupIds, int groupId) {
        groupIds[startX][startY] = groupId;
        int size = 1;

        for (int dir = 0; dir < 4; dir++) {
            int nx = startX + DX[dir];
            int ny = startY + DY[dir];

            if (isWithinBounds(nx, ny, rows, cols) && grid[nx][ny] == '.' && groupIds[nx][ny] == 0) {
                size += computeComponentSize(nx, ny, grid, rows, cols, groupIds, groupId);
            }
        }
        return size;
    }
}

import java.io.*;
import java.util.*;

public class GridComponentSolver {
    private int rows;
    private int cols;
    private char[][] grid;
    private int[][] componentId;
    private int[][] componentSize;
    private boolean[][] visited;
    private int currentId;
    private int currentSize;

    /**
     * Main entry point for solving the problem.
     */
    public void solve(BufferedReader br, StringTokenizer st, PrintWriter out) throws IOException {
        // Ensure we have tokens for dimensions
        if (!st.hasMoreTokens()) {
            String line = br.readLine();
            if (line != null) st = new StringTokenizer(line);
        }

        rows = Integer.parseInt(st.nextToken());
        cols = Integer.parseInt(st.nextToken());

        // Pad grid by 1 cell on all sides to simplify boundary checks
        grid = new char[rows + 2][cols + 2];
        visited = new boolean[rows + 2][cols + 2];
        componentId = new int[rows + 2][cols + 2];
        // Maximum possible connected components is bounded by total cells
        componentSize = new int[(rows * cols) + 1];

        // Read the grid
        for (int i = 1; i <= rows; i++) {
            String line = br.readLine();
            for (int j = 1; j <= cols; j++) {
                grid[i][j] = line.charAt(j - 1);
            }
        }

        // Identify and label all connected '.' components
        labelComponents();

        // Generate the required output grid
        generateOutput(out);
    }

    private void labelComponents() {
        currentId = 0;
        for (int i = 1; i <= rows; i++) {
            for (int j = 1; j <= cols; j++) {
                if (grid[i][j] == '.' && !visited[i][j]) {
                    currentId++;
                    currentSize = 0;
                    dfs(i, j);
                    componentSize[currentId] = currentSize;
                }
            }
        }
    }

    /**
     * Iterative DFS to traverse and label a connected component.
     * Uses a stack to avoid StackOverflowError on large grids.
     */
    private void dfs(int startR, int startC) {
        Deque<int[]> stack = new ArrayDeque<>();
        stack.push(new int[]{startR, startC});
        visited[startR][startC] = true; // Mark immediately to prevent duplicate pushes

        while (!stack.isEmpty()) {
            int[] curr = stack.pop();
            int r = curr[0];
            int c = curr[1];

            componentId[r][c] = currentId;
            currentSize++;

            // Explore 4-directional neighbors
            int[] dirs = {{r, c + 1}, {r, c - 1}, {r + 1, c}, {r - 1, c}};
            for (int[] dir : dirs) {
                int nr = dir[0];
                int nc = dir[1];

                // Check bounds, grid content, and visited status
                if (nr >= 1 && nr <= rows && nc >= 1 && nc <= cols 
                        && grid[nr][nc] == '.' && !visited[nr][nc]) {
                    visited[nr][nc] = true;
                    stack.push(new int[]{nr, nc});
                }
            }
        }
    }

    private void generateOutput(PrintWriter out) {
        int[] neighborIds = new int[4];
        int[] dr = {-1, 0, 1, 0};
        int[] dc = {0, 1, 0, -1};

        for (int i = 1; i <= rows; i++) {
            for (int j = 1; j <= cols; j++) {
                if (grid[i][j] == '.') {
                    out.print('.');
                } else {
                    int uniqueCount = 0;
                    int sumSizes = 0;
                    int count = 0;

                    // Check 4 adjacent cells
                    for (int k = 0; k < 4; k++) {
                        int nr = i + dr[k];
                        int nc = j + dc[k];
                        int cid = componentId[nr][nc];

                        if (cid != 0) { // 0 indicates out-of-bounds or '*'
                            // Check if this component ID is already counted
                            boolean exists = false;
                            for (int l = 0; l < count; l++) {
                                if (neighborIds[l] == cid) {
                                    exists = true;
                                    break;
                                }
                            }
                            if (!exists) {
                                neighborIds[count++] = cid;
                                sumSizes += componentSize[cid];
                            }
                        }
                    }
                    out.print((sumSizes + 1) % 10);
                }
            }
            out.println();
        }
    }

    public static void main(String[] args) throws IOException {
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
             PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out))) {

            StringTokenizer st = new StringTokenizer(br.readLine());
            new GridComponentSolver().solve(br, st, out);
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.Reader;
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.BitSet;
import java.util.Deque;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import java.util.StringTokenizer;

public class GridProcessor {

    private static final int[][] DIRECTIONS = {
            {0, 1}, {1, 0}, {0, -1}, {-1, 0}
    };

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner(System.in);
        try {
            int rows = scanner.nextInt();
            int cols = scanner.nextInt();
            int totalCells = rows * cols;

            char[][] grid = new char[rows][];
            BitSet emptyCells = new BitSet(totalCells);

            // Read grid rows
            for (int r = 0; r < rows; r++) {
                String line = scanner.next();
                grid[r] = line.toCharArray();
            }

            // Build adjacency graph for empty cells
            List<List<Integer>> adj = buildAdjacencyList(grid, rows, cols, totalCells, emptyCells);

            // Find connected components
            ConnectedComponents cc = new ConnectedComponents(adj, totalCells, emptyCells);

            // Transform '*' cells based on adjacent component sizes
            processGrid(grid, rows, cols, cc);

            // Output result
            printGrid(grid);
        } catch (IOException e) {
            System.err.println("Error reading input: " + e.getMessage());
        }
    }

    private static List<List<Integer>> buildAdjacencyList(char[][] grid, int rows, int cols, int totalCells, BitSet emptyCells) {
        List<List<Integer>> adj = new ArrayList<>(totalCells);
        for (int i = 0; i < totalCells; i++) {
            adj.add(new ArrayList<>(4));
        }

        int cellIndex = 0;
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '.') {
                    emptyCells.set(cellIndex);
                    for (int[] dir : DIRECTIONS) {
                        int nr = r + dir[0];
                        int nc = c + dir[1];
                        if (isValidCell(nr, nc, rows, cols) && grid[nr][nc] == '.') {
                            adj.get(cellIndex).add(cellToIndex(nr, nc, cols));
                        }
                    }
                }
                cellIndex++;
            }
        }
        return adj;
    }

    private static boolean isValidCell(int r, int c, int rows, int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    private static int cellToIndex(int r, int c, int cols) {
        return r * cols + c;
    }

    private static void processGrid(char[][] grid, int rows, int cols, ConnectedComponents cc) {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '*') {
                    int sum = 1;
                    Set<Integer> adjacentComponentIds = new HashSet<>();

                    for (int[] dir : DIRECTIONS) {
                        int nr = r + dir[0];
                        int nc = c + dir[1];
                        if (isValidCell(nr, nc, rows, cols) && grid[nr][nc] == '.') {
                            adjacentComponentIds.add(cc.getId(cellToIndex(nr, nc, cols)));
                        }
                    }

                    for (int id : adjacentComponentIds) {
                        sum += cc.getSize(id);
                    }

                    grid[r][c] = (char) ((sum % 10) + '0');
                }
            }
        }
    }

    private static void printGrid(char[][] grid) {
        StringBuilder sb = new StringBuilder();
        for (char[] row : grid) {
            sb.append(row).append('\n');
        }
        System.out.print(sb);
    }

    /**
     * Computes connected components using iterative DFS.
     * Only considers cells marked as empty in the provided BitSet.
     */
    static class ConnectedComponents {
        private final int[] id;
        private final int[] size;
        private final int count;

        ConnectedComponents(List<List<Integer>> adj, int numVertices, BitSet emptyCells) {
            id = new int[numVertices];
            size = new int[numVertices];
            boolean[] visited = new boolean[numVertices];
            Deque<Integer> stack = new ArrayDeque<>();
            int componentCount = 0;

            for (int v = 0; v < numVertices; v++) {
                if (emptyCells.get(v) && !visited[v]) {
                    componentCount++;
                    int currentSize = 0;
                    stack.push(v);
                    visited[v] = true;

                    while (!stack.isEmpty()) {
                        int u = stack.pop();
                        id[u] = componentCount - 1; // 0-based component ID
                        currentSize++;

                        for (int neighbor : adj.get(u)) {
                            if (!visited[neighbor]) {
                                visited[neighbor] = true;
                                stack.push(neighbor);
                            }
                        }
                    }
                    size[componentCount - 1] = currentSize;
                }
            }

            this.count = componentCount;
            // Trim the size array to exactly match the number of components found
            int[] actualSizes = new int[componentCount];
            System.arraycopy(size, 0, actualSizes, 0, componentCount);
            this.size = actualSizes;
        }

        int getId(int vertex) {
            return id[vertex];
        }

        int getSize(int componentId) {
            return size[componentId];
        }

        int getCount() {
            return count;
        }
    }

    /**
     * Fast I/O utility for competitive programming style input.
     */
    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner(Reader in) {
            this.br = new BufferedReader(in);
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input", e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            String token = next();
            if (token == null) throw new RuntimeException("Unexpected end of input");
            return Integer.parseInt(token);
        }
    }
}

import java.io.*;
import java.util.*;

public class ConnectedComponentsGrid {
    // Directions for 4-connected grid traversal
    private static final int[][] DIRECTIONS = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};
    private static final int SHIFT = 32;

    private int h, w;
    private int[][] componentId;
    private int[][] componentSize;
    private int nextComponentId = 1;

    public static void main(String[] args) {
        long startTime = System.currentTimeMillis();
        new ConnectedComponentsGrid().solve();
        long elapsedTime = System.currentTimeMillis() - startTime;
        System.err.println(String.format("[Time: %d ms]", elapsedTime));
    }

    public void solve() throws IOException {
        FastScanner scanner = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out));

        h = scanner.nextInt();
        w = scanner.nextInt();

        // Grid with padding (index 0 and h+1/w+1 act as boundaries)
        componentId = new int[h + 2][w + 2];
        componentSize = new int[h + 2][w + 2];

        // Initialize boundaries to -1 (representing walls/out-of-bounds)
        for (int y = 0; y <= h + 1; y++) {
            Arrays.fill(componentId[y], -1);
        }

        // Read grid input and mark '*' cells
        for (int y = 1; y <= h; y++) {
            String row = scanner.next();
            for (int x = 1; x <= w; x++) {
                if (row.charAt(x - 1) == '*') {
                    componentId[y][x] = -1;
                }
            }
        }

        // Find and fill connected components of '.'
        for (int y = 1; y <= h; y++) {
            for (int x = 1; x <= w; x++) {
                if (componentId[y][x] == 0) {
                    bfsFill(x, y, nextComponentId++);
                }
            }
        }

        // Generate output grid
        int[] seenComponents = new int[h * w + 2];
        int seenToken = 0;

        for (int y = 1; y <= h; y++) {
            StringBuilder sb = new StringBuilder(w);
            for (int x = 1; x <= w; x++) {
                if (componentId[y][x] != -1) {
                    sb.append('.');
                } else {
                    int adjacentSizeSum = 0;
                    seenToken++; // Increment token to invalidate previous checks

                    for (int[] dir : DIRECTIONS) {
                        int nx = x + dir[0];
                        int ny = y + dir[1];

                        if (componentId[ny][nx] != -1) {
                            int id = componentId[ny][nx];
                            // Check if this component was already counted for the current '*'
                            if (seenComponents[id] != seenToken) {
                                seenComponents[id] = seenToken;
                                adjacentSizeSum += componentSize[ny][nx];
                            }
                        }
                    }
                    sb.append(adjacentSizeSum % 10);
                }
            }
            out.println(sb);
        }

        out.flush();
    }

    /**
     * Performs BFS to identify and fill a connected component of '.' cells.
     */
    private void bfsFill(int startX, int startY, int id) {
        Deque<Long> queue = new ArrayDeque<>();
        List<Long> componentCells = new ArrayList<>();

        queue.add(pack(startX, startY));
        componentId[startY][startX] = id;
        componentCells.add(pack(startX, startY));
        int size = 0;

        while (!queue.isEmpty()) {
            long packed = queue.pollFirst();
            int x = unpackX(packed);
            int y = unpackY(packed);
            size++;

            for (int[] dir : DIRECTIONS) {
                int nx = x + dir[0];
                int ny = y + dir[1];

                if (componentId[ny][nx] == 0) {
                    componentId[ny][nx] = id;
                    long nextPacked = pack(nx, ny);
                    queue.add(nextPacked);
                    componentCells.add(nextPacked);
                }
            }
        }

        // Record the component size for all cells belonging to it
        for (long cell : componentCells) {
            componentSize[unpackY(cell)][unpackX(cell)] = size;
        }
    }

    /** Packs x and y coordinates into a single long for queue storage. */
    private long pack(int x, int y) {
        return ((long) x << SHIFT) | (y & ((1L << SHIFT) - 1));
    }

    /** Extracts x coordinate from packed long. */
    private int unpackX(long packed) {
        return (int) (packed >>> SHIFT);
    }

    /** Extracts y coordinate from packed long. */
    private int unpackY(long packed) {
        return (int) (packed & ((1L << SHIFT) - 1));
    }

    /** Lightweight scanner for fast input reading. */
    private static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input", e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.OutputStreamWriter;
import java.io.PrintWriter;
import java.util.Arrays;
import java.util.HashSet;
import java.util.Set;
import java.util.StringTokenizer;

/**
 * Analyzes a character grid to identify connected components of non-star cells,
 * then replaces each star with the sum of adjacent component sizes (plus 1) modulo 10.
 */
public class GridProcessor {

    private static final int[][] DIRECTIONS = {{0, 1}, {0, -1}, {1, 0}, {-1, 0}};
    private static final char STAR = '*';
    private static final int UNVISITED = -1;

    public static void main(String[] args) throws IOException {
        // Try-with-resources ensures streams are properly closed even if an exception occurs
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
             PrintWriter out = new PrintWriter(new OutputStreamWriter(System.out))) {

            FastScanner scanner = new FastScanner(br);
            int n = scanner.nextInt();
            int m = scanner.nextInt();

            char[][] grid = new char[n][m];
            for (int i = 0; i < n; i++) {
                grid[i] = scanner.next().toCharArray();
            }

            // Tracks component ID for each cell. -1 indicates unvisited or a star cell.
            int[][] componentId = new int[n][m];
            for (int[] row : componentId) {
                Arrays.fill(row, UNVISITED);
            }

            // Stores size of each component. Index corresponds to component ID.
            // Max possible components is n * m, so this array is safely sized.
            int[] componentSizes = new int[n * m];
            int componentCount = 0;

            // 1. Identify connected components of non-star cells
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    if (grid[i][j] != STAR && componentId[i][j] == UNVISITED) {
                        int size = dfs(grid, componentId, i, j, componentCount, n, m);
                        componentSizes[componentCount] = size;
                        componentCount++;
                    }
                }
            }

            // 2. Calculate replacement values for star cells
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    if (grid[i][j] == STAR) {
                        int sum = 1;
                        Set<Integer> adjacentComponentIds = new HashSet<>();

                        for (int[] dir : DIRECTIONS) {
                            int ni = i + dir[0];
                            int nj = j + dir[1];
                            if (isValid(ni, nj, n, m) && grid[ni][nj] != STAR) {
                                adjacentComponentIds.add(componentId[ni][nj]);
                            }
                        }

                        for (int id : adjacentComponentIds) {
                            sum += componentSizes[id];
                        }

                        grid[i][j] = (char) ('0' + (sum % 10));
                    }
                }
                out.println(new String(grid[i]));
            }
        }
    }

    /**
     * Performs DFS to label a connected component and return its size.
     *
     * @param grid        The input character grid
     * @param componentId Array tracking component assignments
     * @param x           Current row
     * @param y           Current column
     * @param id          Component identifier to assign
     * @param n           Grid rows
     * @param m           Grid columns
     * @return Size of the connected component
     */
    private static int dfs(char[][] grid, int[][] componentId, int x, int y, int id, int n, int m) {
        componentId[x][y] = id;
        int count = 1;

        for (int[] dir : DIRECTIONS) {
            int nx = x + dir[0];
            int ny = y + dir[1];
            if (isValid(nx, ny, n, m) && grid[nx][ny] != STAR && componentId[nx][ny] == UNVISITED) {
                count += dfs(grid, componentId, nx, ny, id, n, m);
            }
        }
        return count;
    }

    /**
     * Checks if coordinates are within grid boundaries.
     */
    private static boolean isValid(int x, int y, int n, int m) {
        return x >= 0 && x < n && y >= 0 && y < m;
    }

    /**
     * Lightweight fast I/O helper for competitive programming style inputs.
     * Encapsulated to avoid static state pollution in the main class.
     */
    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer tokenizer;

        FastScanner(BufferedReader br) {
            this.br = br;
        }

        String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) {
                    throw new IOException("Unexpected end of input");
                }
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayDeque;
import java.util.HashSet;
import java.util.Queue;
import java.util.Set;
import java.util.StringTokenizer;

public class Main {
    // Direction vectors for moving up, down, left, right
    private static final int[] DX = {-1, 1, 0, 0};
    private static final int[] DY = {0, 0, -1, 1};

    public static void main(String[] args) throws IOException {
        // Use try-with-resources to guarantee the reader is closed automatically
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(System.in))) {
            String line = reader.readLine();
            if (line == null) return;

            StringTokenizer tokenizer = new StringTokenizer(line);
            int rows = Integer.parseInt(tokenizer.nextToken());
            int cols = Integer.parseInt(tokenizer.nextToken());

            boolean[][] grid = new boolean[rows][cols];
            for (int i = 0; i < rows; i++) {
                String rowLine = reader.readLine();
                for (int j = 0; j < cols; j++) {
                    grid[i][j] = rowLine.charAt(j) == '.';
                }
            }

            int[][] componentIds = new int[rows][cols];
            int[] componentSizes = new int[rows * cols + 1];
            int componentCount = 0;

            // Identify connected components of '.' cells
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j] && componentIds[i][j] == 0) {
                        componentCount++;
                        componentSizes[componentCount] = bfs(grid, componentIds, rows, cols, i, j, componentCount);
                    }
                }
            }

            StringBuilder output = new StringBuilder();
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j]) {
                        output.append('.');
                    } else {
                        int connectedCells = 1;
                        Set<Integer> adjacentComponents = new HashSet<>();

                        // Check all 4 neighboring cells
                        for (int k = 0; k < 4; k++) {
                            int nx = i + DX[k];
                            int ny = j + DY[k];
                            if (isValid(nx, ny, rows, cols) && grid[nx][ny]) {
                                adjacentComponents.add(componentIds[nx][ny]);
                            }
                        }

                        // Sum the sizes of all unique adjacent components
                        for (int id : adjacentComponents) {
                            connectedCells += componentSizes[id];
                        }
                        output.append(connectedCells % 10);
                    }
                }
                output.append('\n');
            }
            System.out.print(output);
        }
    }

    /**
     * Performs BFS to label a connected component and return its size.
     */
    private static int bfs(boolean[][] grid, int[][] componentIds, int rows, int cols,
                           int startX, int startY, int componentId) {
        Queue<int[]> queue = new ArrayDeque<>();
        queue.offer(new int[]{startX, startY});
        componentIds[startX][startY] = componentId;

        int size = 1;
        while (!queue.isEmpty()) {
            int[] current = queue.poll();
            int x = current[0];
            int y = current[1];

            for (int k = 0; k < 4; k++) {
                int nx = x + DX[k];
                int ny = y + DY[k];
                if (isValid(nx, ny, rows, cols) && grid[nx][ny] && componentIds[nx][ny] == 0) {
                    queue.offer(new int[]{nx, ny});
                    componentIds[nx][ny] = componentId;
                    size++;
                }
            }
        }
        return size;
    }

    /**
     * Checks if the given coordinates are within the grid boundaries.
     */
    private static boolean isValid(int x, int y, int rows, int cols) {
        return x >= 0 && x < rows && y >= 0 && y < cols;
    }
}

import java.io.*;
import java.util.*;

public class GridProcessor {
    private static final int[] DR = {-1, 1, 0, 0};
    private static final int[] DC = {0, 0, -1, 1};

    public static void main(String[] args) {
        new GridProcessor().run();
    }

    private void run() {
        // Use try-with-resources for automatic and safe resource management
        try (FastScanner in = new FastScanner(System.in);
             PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out))) {

            int rows = in.nextInt();
            int cols = in.nextInt();
            char[][] grid = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                grid[i] = in.next().toCharArray();
            }

            int[][] componentIds = new int[rows][cols];
            for (int[] row : componentIds) {
                Arrays.fill(row, -1);
            }
            int[] componentSizes = new int[rows * cols];

            identifyComponents(grid, componentIds, componentSizes);
            generateOutput(grid, componentIds, componentSizes, out);

            out.flush();
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    /**
     * Identifies connected components of '.' cells using BFS.
     * Assigns a unique ID to each component and records its size.
     */
    private void identifyComponents(char[][] grid, int[][] componentIds, int[] componentSizes) {
        int rows = grid.length;
        int cols = grid[0].length;
        int componentCount = 0;
        ArrayDeque<Integer> queue = new ArrayDeque<>();

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '.' && componentIds[r][c] == -1) {
                    int currentId = componentCount++;
                    int size = 0;

                    // Pack coordinates into a single integer for efficient queue storage
                    queue.add(r * cols + c);
                    componentIds[r][c] = currentId;

                    while (!queue.isEmpty()) {
                        int packed = queue.poll();
                        int cr = packed / cols;
                        int cc = packed % cols;
                        size++;

                        for (int k = 0; k < 4; k++) {
                            int nr = cr + DR[k];
                            int nc = cc + DC[k];
                            if (isValid(nr, nc, rows, cols) && grid[nr][nc] == '.' && componentIds[nr][nc] == -1) {
                                componentIds[nr][nc] = currentId;
                                queue.add(nr * cols + nc);
                            }
                        }
                    }
                    componentSizes[currentId] = size;
                }
            }
        }
    }

    /**
     * Processes the grid to compute values for '*' cells based on adjacent components.
     * Outputs the final grid to the provided PrintWriter.
     */
    private void generateOutput(char[][] grid, int[][] componentIds, int[] componentSizes, PrintWriter out) {
        int rows = grid.length;
        int cols = grid[0].length;
        int[] seenIds = new int[4]; // Maximum 4 neighbors, so fixed size is optimal

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '.') {
                    out.print('.');
                } else {
                    int sum = 1;
                    int seenCount = 0;

                    for (int k = 0; k < 4; k++) {
                        int nr = r + DR[k];
                        int nc = c + DC[k];
                        if (isValid(nr, nc, rows, cols) && grid[nr][nc] == '.') {
                            int id = componentIds[nr][nc];

                            // Linear scan is O(1) since seenCount <= 4
                            boolean alreadySeen = false;
                            for (int s = 0; s < seenCount; s++) {
                                if (seenIds[s] == id) {
                                    alreadySeen = true;
                                    break;
                                }
                            }

                            if (!alreadySeen) {
                                seenIds[seenCount++] = id;
                            }
                        }
                    }

                    for (int i = 0; i < seenCount; i++) {
                        sum = (sum + componentSizes[seenIds[i]]) % 10;
                    }
                    out.print(sum);
                }
            }
            out.println();
        }
    }

    private boolean isValid(int r, int c, int rows, int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /**
     * Efficient scanner for competitive programming / fast I/O.
     * Made static to avoid holding an implicit reference to the outer class.
     */
    private static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        public String next() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) return null;
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

        public int nextInt() throws IOException {
            String s = next();
            if (s == null) throw new IOException("Unexpected end of input");
            return Integer.parseInt(s);
        }
    }
}

