class GridSolver {
    private static final int[][] DIRECTIONS = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};
    private static final int PADDING = 1;

    private final FastScanner scanner;
    private final PrintWriter out;

    public GridSolver(FastScanner scanner, PrintWriter out) {
        this.scanner = scanner;
        this.out = out;
    }

    public void solve() {
        int n = scanner.nextInt();
        int m = scanner.nextInt();

        // Use padding to safely avoid boundary checks during traversal
        boolean[][] isWalkable = new boolean[n + 2 * PADDING][m + 2 * PADDING];
        for (int y = 1; y <= n; y++) {
            String row = scanner.next();
            for (int x = 1; x <= m; x++) {
                isWalkable[y][x] = (row.charAt(x - 1) == '.');
            }
        }

        int[][] componentId = new int[n + 2 * PADDING][m + 2 * PADDING];
        int[] componentSize = new int[n * m + 1];
        boolean[][] visited = new boolean[n + 2 * PADDING][m + 2 * PADDING];
        int currentComponent = 1;

        // Find connected components using BFS
        for (int y = 1; y <= n; y++) {
            for (int x = 1; x <= m; x++) {
                if (isWalkable[y][x] && !visited[y][x]) {
                    bfs(y, x, isWalkable, visited, componentId, componentSize, currentComponent);
                    currentComponent++;
                }
            }
        }

        // Build result
        StringBuilder result = new StringBuilder();
        for (int y = 1; y <= n; y++) {
            for (int x = 1; x <= m; x++) {
                if (isWalkable[y][x]) {
                    result.append('.');
                } else {
                    result.append(calculateComponentSum(y, x, componentId, componentSize));
                }
            }
            result.append('\n');
        }
        out.println(result);
    }

    private void bfs(int startY, int startX, boolean[][] isWalkable, boolean[][] visited,
                     int[][] componentId, int[] componentSize, int component) {
        ArrayDeque<Integer> yQueue = new ArrayDeque<>();
        ArrayDeque<Integer> xQueue = new ArrayDeque<>();

        yQueue.addLast(startY);
        xQueue.addLast(startX);
        visited[startY][startX] = true;

        while (!yQueue.isEmpty()) {
            int cy = yQueue.pollFirst();
            int cx = xQueue.pollFirst();

            componentId[cy][cx] = component;
            componentSize[component]++;

            for (int[] dir : DIRECTIONS) {
                int ny = cy + dir[0];
                int nx = cx + dir[1];

                if (isWalkable[ny][nx] && !visited[ny][nx]) {
                    visited[ny][nx] = true;
                    yQueue.addLast(ny);
                    xQueue.addLast(nx);
                }
            }
        }
    }

    private int calculateComponentSum(int y, int x, int[][] componentId, int[] componentSize) {
        int sum = 0;
        int[] seenIds = new int[5]; // At most 4 neighbors
        int uniqueCount = 0;

        for (int[] dir : DIRECTIONS) {
            int ny = y + dir[0];
            int nx = x + dir[1];
            int id = componentId[ny][nx];

            if (id != 0) {
                boolean alreadyCounted = false;
                for (int i = 0; i < uniqueCount; i++) {
                    if (seenIds[i] == id) {
                        alreadyCounted = true;
                        break;
                    }
                }
                if (!alreadyCounted) {
                    seenIds[uniqueCount++] = id;
                    sum += componentSize[id];
                }
            }
        }
        return sum % 10;
    }
}

