            grid[i] = rowStr.toCharArray();
        }

        int[][] componentId = new int[rows][cols];
        int[] componentSize = new int[rows * cols + 1]; // 1-based indexing for components
        int currentComponentId = 0;

        // Direction vectors: up, down, left, right
        int[] dr = {-1, 1, 0, 0};
        int[] dc = {0, 0, -1, 1};

        // Step 1: Identify connected components using iterative BFS
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '.' && componentId[r][c] == 0) {
                    currentComponentId++;
                    int size = 0;
                    Queue<int[]> queue = new ArrayDeque<>();

                    queue.offer(new int[]{r, c});
                    componentId[r][c] = currentComponentId;

                    while (!queue.isEmpty()) {
                        int[] curr = queue.poll();
                        int cr = curr[0];
                        int cc = curr[1];
                        size++;

                        for (int d = 0; d < 4; d++) {
                            int nr = cr + dr[d];
                            int nc = cc + dc[d];

                            if (isValid(nr, nc, rows, cols) &&
                                grid[nr][nc] == '.' &&
                                componentId[nr][nc] == 0) {
                                componentId[nr][nc] = currentComponentId;
                                queue.offer(new int[]{nr, nc});
                            }
                        }
                    }
                    componentSize[currentComponentId] = size;
                }
            }
        }

        // Step 2: Process '*' cells and calculate adjacent component sums
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '*') {
                    Set<Integer> adjacentComponents = new HashSet<>();
                    for (int d = 0; d < 4; d++) {
                        int nr = r + dr[d];
                        int nc = c + dc[d];

                        if (isValid(nr, nc, rows, cols) && grid[nr][nc] == '.') {
                            adjacentComponents.add(componentId[nr][nc]);
                        }
                    }

                    int sum = 0;
                    for (int compId : adjacentComponents) {
                        sum = (sum + componentSize[compId]) % 10;
                    }
                    out.print(sum);
                } else {
                    out.print('.');
                }
            }
            out.println();
        }
    }

    /**
     * Checks if coordinates are within grid boundaries.
     */
    private boolean isValid(int r, int c, int rows, int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /**
     * Fast I/O helper class using BufferedReader and StringTokenizer.
     * Replaces the custom byte-buffer scanner for better readability and maintainability.
     */
    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            String s = next();
            if (s == null) throw new NoSuchElementException();
            return Integer.parseInt(s);
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.ArrayDeque;
import java.util.HashSet;
import java.util.Queue;
import java.util.Set;
import java.util.StringTokenizer;

/**
 * A solver for grid component analysis problems.
 * Identifies connected components of empty cells and calculates reachable sizes for blocks.
 */
public class GridComponentSolver {

    // Constants for grid characters
    private static final char EMPTY_CHAR = '.';
    private static final char BLOCK_CHAR = '*';

    // Direction vectors for moving in the grid (Down, Up, Right, Left)
    private static final int[][] DIRECTIONS = {
        {1, 0}, {-1, 0}, {0, 1}, {0, -1}
    };

    public static void main(String[] args) throws Exception {
        // Use try-with-resources for automatic resource management
        try (FastScanner scanner = new FastScanner(System.in);
             PrintWriter out = new PrintWriter(System.out)) {

            int rows = scanner.nextInt();
            int cols = scanner.nextInt();

            // Read grid into a char array for better performance and mutability
            char[][] grid = new char[rows][];
            for (int i = 0; i < rows; i++) {
                grid[i] = scanner.next().toCharArray();
            }

            // Component ID matrix: 0 means unvisited or not part of a processed component
            int[][] componentId = new int[rows][cols];

            // Store size of each component. Index corresponds to component ID.
            // Max possible components is rows * cols.
            int[] componentSizes = new int[rows * cols + 2];

            // Step 1: Identify connected components and calculate their sizes
            identifyComponents(rows, cols, grid, componentId, componentSizes);

            // Step 2: Generate the output based on the problem logic
            printResult(rows, cols, grid, componentId, componentSizes, out);
        }
    }

    /**
     * Iterates through the grid to find connected components of empty cells.
     * Uses BFS to determine the size of each component.
     */
    private static void identifyComponents(int rows, int cols, char[][] grid, int[][] componentId, int[] componentSizes) {
        int currentComponentId = 1;

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                // If it's an empty cell and hasn't been visited yet
                if (grid[r][c] == EMPTY_CHAR && componentId[r][c] == 0) {
                    int size = bfs(r, c, rows, cols, grid, componentId, currentComponentId);
                    componentSizes[currentComponentId] = size;
                    currentComponentId++;
                }
            }
        }
    }

    /**
     * Performs Breadth-First Search to find the size of the connected component
     * starting at (startRow, startCol).
     */
    private static int bfs(int startRow, int startCol, int rows, int cols, char[][] grid, int[][] componentId, int componentIdValue) {
        Queue<int[]> queue = new ArrayDeque<>();
        queue.offer(new int[]{startRow, startCol});
        componentId[startRow][startCol] = componentIdValue;

        int size = 1;

        while (!queue.isEmpty()) {
            int[] current = queue.poll();
            int r = current[0];
            int c = current[1];

            for (int[] dir : DIRECTIONS) {
                int nr = r + dir[0];
                int nc = c + dir[1];

                // Check bounds, if empty, and if not yet visited
                if (isValid(nr, nc, rows, cols) && 
                    grid[nr][nc] == EMPTY_CHAR && 
                    componentId[nr][nc] == 0) {

                    componentId[nr][nc] = componentIdValue;
                    size++;
                    queue.offer(new int[]{nr, nc});
                }
            }
        }
        return size;
    }

    /**
     * Checks if the given coordinates are within the grid boundaries.
     */
    private static boolean isValid(int r, int c, int rows, int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /**
     * Generates the final output grid.
     * For empty cells, prints the character.
     * For blocks, calculates the size of the connected region if the block were removed.
     */
    private static void printResult(int rows, int cols, char[][] grid, int[][] componentId, int[] componentSizes, PrintWriter out) {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == EMPTY_CHAR) {
                    out.print(EMPTY_CHAR);
                } else {
                    // It's a block ('*'), calculate reachable size
                    int reachableSize = 1; // Count the block itself

                    // Use a Set to collect unique component IDs of adjacent empty cells
                    // to avoid double counting the same component
                    Set<Integer> neighborComponentIds = new HashSet<>();

                    for (int[] dir : DIRECTIONS) {
                        int nr = r + dir[0];
                        int nc = c + dir[1];

                        if (isValid(nr, nc, rows, cols) && grid[nr][nc] == EMPTY_CHAR) {
                            neighborComponentIds.add(componentId[nr][nc]);
                        }
                    }

                    for (int id : neighborComponentIds) {
                        reachableSize += componentSizes[id];
                    }

                    out.print(reachableSize % 10);
                }
            }
            out.println();
        }
    }

    /**
     * A robust FastScanner for reading input efficiently.
     */
    private static final class FastScanner implements AutoCloseable {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        FastScanner(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
            tokenizer = null;
        }

        String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        int nextInt() throws IOException {
            String s = next();
            if (s == null) throw new IOException("End of stream");
            return Integer.parseInt(s);
        }

        @Override
        public void close() throws Exception {
            reader.close();
        }
    }
}

import java.io.*;
import java.util.*;

public class Main {
    // Direction vectors for moving up, left, down, right
    private static final int[] DX = {-1, 0, 1, 0};
    private static final int[] DY = {0, -1, 0, 1};

    public static void main(String[] args) {
        FastReader sc = new FastReader();
        // Buffered output for better performance
        PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out));
        try {
            solve(sc, out);
        } finally {
            out.flush();
        }
    }

    private static void solve(FastReader sc, PrintWriter out) {
        // Original code hardcodes testCases to 1. Kept for compatibility.
        int testCases = 1;
        while (testCases-- > 0) {
            int n = sc.nextInt();
            int m = sc.nextInt();

            // Use boolean grid for walls ('*') to save memory and improve clarity
            boolean[][] isWall = new boolean[n][m];
            for (int i = 0; i < n; i++) {
                String row = sc.next();
                for (int j = 0; j < m; j++) {
                    isWall[i][j] = (row.charAt(j) == '*');
                }
            }

            // componentId[i][j] stores the ID of the connected component at (i, j)
            int[][] componentId = new int[n][m];
            // componentSizes[id] stores the size of component with given id
            // Index 0 is reserved for "no component"
            int[] componentSizes = new int[n * m + 1];
            int currentId = 0;

            // Identify connected components of empty cells ('.')
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    if (!isWall[i][j] && componentId[i][j] == 0) {
                        currentId++;
                        int size = iterativeDfs(i, j, n, m, isWall, componentId, currentId);
                        componentSizes[currentId] = size;
                    }
                }
            }

            // Generate the output grid
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    if (isWall[i][j]) {
                        int sum = 0;
                        // Collect unique adjacent component IDs
                        Set<Integer> adjacentIds = new HashSet<>();
                        for (int d = 0; d < 4; d++) {
                            int ni = i + DX[d];
                            int nj = j + DY[d];

                            if (ni >= 0 && ni < n && nj >= 0 && nj < m) {
                                int cid = componentId[ni][nj];
                                if (cid != 0) {
                                    adjacentIds.add(cid);
                                }
                            }
                        }
                        // Sum sizes of adjacent components
                        for (int cid : adjacentIds) {
                            sum += componentSizes[cid];
                        }
                        out.print(sum % 10);
                    } else {
                        out.print('.');
                    }
                }
                out.println();
            }
        }
    }

    /**
     * Iterative DFS to find connected component size and assign component IDs.
     * Replaces recursion to prevent StackOverflowError on large grids (e.g., 1000x1000).
     * Uses an integer array as a stack to avoid object allocation overhead.
     */
    private static int iterativeDfs(int startX, int startY, int n, int m,
                                    boolean[][] isWall, int[][] componentId, int currentId) {
        int count = 1;
        componentId[startX][startY] = currentId;

        // Stack stores encoded coordinates: x * m + y
        int[] stack = new int[n * m];
        int top = 0;
        stack[top++] = startX * m + startY;

        while (top > 0) {
            int pos = stack[--top];
            int x = pos / m;
            int y = pos % m;

            for (int d = 0; d < 4; d++) {
                int nx = x + DX[d];
                int ny = y + DY[d];

                if (nx >= 0 && nx < n && ny >= 0 && ny < m &&
                    !isWall[nx][ny] && componentId[nx][ny] == 0) {
                    componentId[nx][ny] = currentId;
                    count++;
                    stack[top++] = nx * m + ny;
                }
            }
        }
        return count;
    }

    /**
     * Fast I/O helper class for competitive programming and large inputs.
     * Replaces the custom FastInput class with a standard, maintainable implementation.
     */
    static class FastReader {
        BufferedReader br;
        StringTokenizer st;

        public FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            String s = next();
            return s == null ? 0 : Integer.parseInt(s);
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.HashSet;
import java.util.Set;

/**
 * A refactored solution for grid-based problems including labyrinth analysis,
 * numeric string comparison, and matrix row-min optimization.
 * 
 * Key Improvements:
 * - Eliminated static mutable state (removed 'count' field)
 * - Extracted Union-Find into a dedicated, reusable class
 * - Applied consistent naming conventions (PascalCase for classes, camelCase for methods)
 * - Improved error handling and resource management (try-with-resources)
 * - Added input validation and robust parsing
 * - Removed unused imports and consolidated logic
 */
public class LabyrinthSolver {

    /**
     * Union-Find (Disjoint Set Union) data structure with path compression and union by size.
     */
    private static class UnionFind {
        private final int[] parent;
        private final int[] size;

        public UnionFind(int n) {
            parent = new int[n];
            size = new int[n];
            for (int i = 0; i < n; i++) {
                parent[i] = i;
                size[i] = 1;
            }
        }

        public int find(int i) {
            int root = i;
            while (root != parent[root]) {
                root = parent[root];
            }
            // Path compression
            while (i != root) {
                int next = parent[i];
                parent[i] = root;
                i = next;
            }
            return root;
        }

        public void union(int i, int j) {
            int rootI = find(i);
            int rootJ = find(j);
            if (rootI != rootJ) {
                if (size[rootI] >= size[rootJ]) {
                    parent[rootJ] = rootI;
                    size[rootI] += size[rootJ];
                } else {
                    parent[rootI] = rootJ;
                    size[rootJ] += size[rootI];
                }
            }
        }

        public int getSize(int i) {
            return size[find(i)];
        }
    }

    /**
     * Compares two numeric strings, ignoring leading zeros.
     * Prints ">" if a > b, "<" if a < b, and "=" if equal.
     */
    public static void compareNumericStrings(String a, String b) {
        if (a == null || b == null) return;

        int i = skipLeadingZeros(a);
        int j = skipLeadingZeros(b);

        int lenA = a.length() - i;
        int lenB = b.length() - j;

        if (lenA > lenB) {
            System.out.println(">");
            return;
        } else if (lenA < lenB) {
            System.out.println("<");
            return;
        }

        while (i < a.length() && j < b.length()) {
            char charA = a.charAt(i);
            char charB = b.charAt(j);
            if (charA < charB) {
                System.out.println("<");
                return;
            } else if (charA > charB) {
                System.out.println(">");
                return;
            }
            i++;
            j++;
        }
        System.out.println("=");
    }

    private static int skipLeadingZeros(String s) {
        int i = 0;
        while (i < s.length() && s.charAt(i) == '0') {
            i++;
        }
        return i;
    }

    /**
     * Finds the maximum value among the minimum values of each row in a 2D array.
     */
    public static void computeMaxOfRowMins(int[][] grid) {
        if (grid == null || grid.length == 0 || grid[0].length == 0) {
            System.out.println(0);
            return;
        }

        int maxOfMins = Integer.MIN_VALUE;
        for (int[] row : grid) {
            int minInRow = Integer.MAX_VALUE;
            for (int val : row) {
                minInRow = Math.min(minInRow, val);
            }
            maxOfMins = Math.max(maxOfMins, minInRow);
        }
        System.out.println(maxOfMins);
    }

    /**
     * Performs a depth-first search to count connected '.' cells.
     * Marks visited cells as '#' to prevent revisiting.
     * Returns the total count of visited cells.
     */
    public static int countConnectedCells(char[][] board, int row, int col) {
        if (row < 0 || row >= board.length || col < 0 || col >= board[0].length || board[row][col] != '.') {
            return 0;
        }

        board[row][col] = '#';
        int count = 1;
        count += countConnectedCells(board, row - 1, col);
        count += countConnectedCells(board, row + 1, col);
        count += countConnectedCells(board, row, col - 1);
        count += countConnectedCells(board, row, col + 1);
        return count;
    }

    /**
     * Reverts '#' cells back to '.' using depth-first search.
     */
    public static void clearVisitedCells(char[][] board, int row, int col) {
        if (row < 0 || row >= board.length || col < 0 || col >= board[0].length || board[row][col] != '#') {
            return;
        }

        board[row][col] = '.';
        clearVisitedCells(board, row - 1, col);
        clearVisitedCells(board, row + 1, col);
        clearVisitedCells(board, row, col - 1);
        clearVisitedCells(board, row, col + 1);
    }

    /**
     * Solves the labyrinth problem using Union-Find to identify connected components
     * of open cells ('.'). For each wall ('#'), calculates the sum of adjacent 
     * component sizes plus 1, modulo 10.
     */
    public static void solveLabyrinth(char[][] board) {
        if (board == null || board.length == 0 || board[0].length == 0) return;

        int rows = board.length;
        int cols = board[0].length;
        UnionFind uf = new UnionFind(rows * cols);

        // Direction vectors for up, down, left, right
        int[] dRow = {-1, 1, 0, 0};
        int[] dCol = {0, 0, -1, 1};

        // Build Union-Find structure for adjacent '.' cells
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (board[r][c] == '.') {
                    int idx = r * cols + c;
                    if (r > 0 && board[r - 1][c] == '.') {
                        uf.union(idx, (r - 1) * cols + c);
                    }
                    if (c > 0 && board[r][c - 1] == '.') {
                        uf.union(idx, r * cols + (c - 1));
                    }
                }
            }
        }

        // Process each '#' cell
        for (int r = 0; r < rows; r++) {
            StringBuilder lineBuilder = new StringBuilder();
            for (int c = 0; c < cols; c++) {
                if (board[r][c] == '.') {
                    lineBuilder.append('.');
                } else {
                    Set<Integer> uniqueComponents = new HashSet<>();
                    int totalSize = 1; // Count the cell itself

                    for (int k = 0; k < 4; k++) {
                        int nr = r + dRow[k];
                        int nc = c + dCol[k];
                        if (nr >= 0 && nr < rows && nc >= 0 && nc < cols && board[nr][nc] == '.') {
                            int root = uf.find(nr * cols + nc);
                            if (!uniqueComponents.contains(root)) {
                                uniqueComponents.add(root);
                                totalSize += uf.getSize(root);
                            }
                        }
                    }
                    lineBuilder.append(totalSize % 10);
                }
            }
            System.out.println(lineBuilder);
        }
    }

    public static void main(String[] args) {
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            String line = br.readLine();
            if (line == null || line.trim().isEmpty()) return;

            String[] parts = line.trim().split("\\s+");
            if (parts.length < 2) return;

            int rows = Integer.parseInt(parts[0]);
            int cols = Integer.parseInt(parts[1]);
            char[][] board = new char[rows][cols];

            for (int i = 0; i < rows; i++) {
                String rowStr = br.readLine();
                if (rowStr != null) {
                    board[i] = rowStr.trim().toCharArray();
                }
            }
            solveLabyrinth(board);
        } catch (IOException e) {
            System.err.println("Error reading input: " + e.getMessage());
        } catch (NumberFormatException e) {
            System.err.println("Invalid number format in input: " + e.getMessage());
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Queue;
import java.util.Set;
import java.util.StringTokenizer;

/**
 * Processes a grid to identify connected empty components and replaces obstacles
 * with a digit representing the sum of adjacent component sizes modulo 10.
 */
public class GridObstacleProcessor {

    private final BufferedReader reader;
    private final PrintWriter out;
    private StringTokenizer tokenizer;

    public GridObstacleProcessor() {
        this.reader = new BufferedReader(new InputStreamReader(System.in));
        this.out = new PrintWriter(System.out);
    }

    public void solve() throws IOException {
        int n = nextInt();
        int m = nextInt();
        char[][] grid = readGrid(n, m);

        // compID[r][c] stores the component ID. 0 represents walls or unvisited cells.
        int[][] compID = new int[n + 2][m + 2];
        Map<Integer, Integer> compSizes = new HashMap<>();
        compSizes.put(0, 0); // Wall component size is explicitly 0

        List<int[]> obstacles = new ArrayList<>();
        labelComponents(grid, compID, compSizes, obstacles);
        processObstacles(grid, compID, compSizes, obstacles);
        printResult(grid, n, m);
    }

    /**
     * Reads the grid and pads it with '#' walls to simplify boundary checks.
     */
    private char[][] readGrid(int n, int m) throws IOException {
        char[][] grid = new char[n + 2][m + 2];
        Arrays.fill(grid[0], '#');
        Arrays.fill(grid[n + 1], '#');
        for (int i = 1; i <= n; i++) {
            grid[i] = ("#" + next() + "#").toCharArray();
        }
        return grid;
    }

    /**
     * Performs BFS to label connected empty components and collect obstacle positions.
     */
    private void labelComponents(char[][] grid, int[][] compID, Map<Integer, Integer> compSizes, List<int[]> obstacles) {
        int n = grid.length - 2;
        int m = grid[0].length - 2;
        int curComp = 1;
        int[] dr = {1, -1, 0, 0};
        int[] dc = {0, 0, 1, -1};

        for (int r = 1; r <= n; r++) {
            for (int c = 1; c <= m; c++) {
                if (grid[r][c] == '.') {
                    if (compID[r][c] == 0) { // Unvisited empty cell
                        compID[r][c] = curComp;
                        int size = 1;
                        Queue<int[]> queue = new ArrayDeque<>();
                        queue.add(new int[]{r, c});

                        while (!queue.isEmpty()) {
                            int[] curr = queue.poll();
                            for (int k = 0; k < 4; k++) {
                                int nr = curr[0] + dr[k];
                                int nc = curr[1] + dc[k];
                                // Padding ensures nr/nc are always within bounds
                                if (grid[nr][nc] == '.' && compID[nr][nc] == 0) {
                                    compID[nr][nc] = curComp;
                                    size++;
                                    queue.add(new int[]{nr, nc});
                                }
                            }
                        }
                        compSizes.put(curComp, size);
                        curComp++;
                    }
                } else if (grid[r][c] == '*') {
                    obstacles.add(new int[]{r, c});
                }
            }
        }
    }

    /**
     * Replaces each obstacle with the sum of adjacent component sizes modulo 10.
     * The obstacle cell itself contributes 1 to the sum.
     */
    private void processObstacles(char[][] grid, int[][] compID, Map<Integer, Integer> compSizes, List<int[]> obstacles) {
        int[] dr = {1, -1, 0, 0};
        int[] dc = {0, 0, 1, -1};

        for (int[] obs : obstacles) {
            int r = obs[0];
            int c = obs[1];

            Set<Integer> adjacentCompIds = new HashSet<>();
            for (int k = 0; k < 4; k++) {
                adjacentCompIds.add(compID[r + dr[k]][c + dc[k]]);
            }

            long sum = 1; // Obstacle cell itself counts as 1
            for (int compId : adjacentCompIds) {
                sum += compSizes.getOrDefault(compId, 0);
            }
            grid[r][c] = (char) ('0' + (sum % 10));
        }
    }

    /**
     * Outputs the processed grid without the padding.
     */
    private void printResult(char[][] grid, int n, int m) {
        for (int i = 1; i <= n; i++) {
            out.write(grid[i], 1, m);
            out.println();
        }
    }

    /**
     * Reads the next token from input.
     */
    private String next() throws IOException {
        while (tokenizer == null || !tokenizer.hasMoreTokens()) {
            String line = reader.readLine();
            if (line == null) throw new IOException("Unexpected end of input");
            tokenizer = new StringTokenizer(line);
        }
        return tokenizer.nextToken();
    }

    /**
     * Parses the next token as an integer.
     */
    private int nextInt() throws IOException {
        return Integer.parseInt(next());
    }

    public static void main(String[] args) {
        GridObstacleProcessor solver = new GridObstacleProcessor();
        try {
            solver.solve();
        } catch (IOException e) {
            e.printStackTrace();
        } finally {
            solver.out.flush();
            solver.out.close();
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Refactored Grid Solver.
 * 
 * Key Improvements:
 * 1. Renamed class 'c' to 'GridSolver' for clarity.
 * 2. Replaced magic variables (d, a, ans) with descriptive names (grid, componentMap, currentComponentId).
 * 3. Removed static 'out' variable; made it local to main for better encapsulation and thread safety.
 * 4. Encapsulated logic into methods (floodFill, isValid) to reduce cyclomatic complexity in main.
 * 5. Used a HashSet to handle unique neighbor component IDs, replacing verbose conditional checks.
 * 6. Improved FastScanner to handle EOF gracefully.
 * 7. Added JavaDoc comments.
 */
public class GridSolver {

    public static void main(String[] args) {
        // Use local PrintWriter to avoid static state
        PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out));
        FastScanner sc = new FastScanner();

        try {
            // Read dimensions
            int n = sc.nextInt();
            int m = sc.nextInt();

            // Data structures
            char[][] grid = new char[n][m];
            int[][] componentMap = new int[n][m]; // Maps cell coordinates to component ID
            long[] componentSizes = new long[n * m + 1]; // Stores size of each component (1-based index)
            int currentComponentId = 1;

            // Read Grid
            for (int i = 0; i < n; i++) {
                String row = sc.next();
                if (row != null) {
                    grid[i] = row.toCharArray();
                }
            }

            // 1. Identify Connected Components (Flood Fill)
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    // If it's an empty space and not yet visited (componentMap is 0)
                    if (grid[i][j] == '.' && componentMap[i][j] == 0) {
                        // Perform flood fill to find size and mark component
                        long size = floodFill(grid, componentMap, currentComponentId, i, j);
                        componentSizes[currentComponentId] = size;
                        currentComponentId++;
                    }
                }
            }

            // 2. Calculate Bomb Scores
            char[][] resultGrid = new char[n][m];
            // Initialize result grid with '.'
            for (int i = 0; i < n; i++) {
                Arrays.fill(resultGrid[i], '.');
            }

            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    if (grid[i][j] == '*') {
                        long score = 1; // Base score
                        Set<Integer> neighborComponentIds = new HashSet<>();

                        // Check 4 neighbors and collect unique component IDs
                        if (isValid(i - 1, j, n, m)) neighborComponentIds.add(componentMap[i - 1][j]);
                        if (isValid(i, j - 1, n, m)) neighborComponentIds.add(componentMap[i][j - 1]);
                        if (isValid(i + 1, j, n, m)) neighborComponentIds.add(componentMap[i + 1][j]);
                        if (isValid(i, j + 1, n, m)) neighborComponentIds.add(componentMap[i][j + 1]);

                        // Sum sizes of unique adjacent components
                        for (int id : neighborComponentIds) {
                            if (id != 0) { // 0 represents empty space or unassigned
                                score += componentSizes[id];
                            }
                        }

                        resultGrid[i][j] = (char) ((score % 10) + '0');
                    }
                }
            }

            // 3. Output
            for (int i = 0; i < n; i++) {
                out.println(new String(resultGrid[i]));
            }

        } catch (Exception e) {
            e.printStackTrace();
        } finally {
            out.flush();
            out.close();
        }
    }

    /**
     * Recursive Flood Fill algorithm to calculate the size of a connected component.
     * It also marks visited cells in the componentMap to avoid re-processing.
     *
     * @param grid The input grid
     * @param componentMap The map storing component IDs for visited cells
     * @param componentId The ID to assign to the current component
     * @param x Current row index
     * @param y Current column index
     * @return The size of the connected component
     */
    private static long floodFill(char[][] grid, int[][] componentMap, int componentId, int x, int y) {
        // Boundary checks
        if (x < 0 || x >= grid.length || y < 0 || y >= grid[0].length) {
            return 0;
        }
        // If already visited or not an empty space (bomb)
        if (componentMap[x][y] != 0 || grid[x][y] == '*') {
            return 0;
        }

        // Mark as visited with current component ID
        componentMap[x][y] = componentId;

        // Return 1 (current cell) + sum of recursive calls to neighbors
        return 1 
             + floodFill(grid, componentMap, componentId, x + 1, y)
             + floodFill(grid, componentMap, componentId, x, y + 1)
             + floodFill(grid, componentMap, componentId, x - 1, y)
             + floodFill(grid, componentMap, componentId, x, y - 1);
    }

    /**
     * Helper method to check if coordinates are within grid bounds.
     */
    private static boolean isValid(int x, int y, int n, int m) {
        return x >= 0 && x < n && y >= 0 && y < m;
    }

    /**
     * FastScanner class for efficient input reading.
     */
    static class FastScanner {
        BufferedReader br;
        StringTokenizer st;

        public FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    e.printStackTrace();
                    return null;
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            String s = next();
            return s == null ? 0 : Integer.parseInt(s);
        }

        long nextLong() {
            String s = next();
            return s == null ? 0L : Long.parseLong(s);
        }

        double nextDouble() {
            String s = next();
            return s == null ? 0.0 : Double.parseDouble(s);
        }

        String nextLine() {
            String str = "";
            try {
                str = br.readLine();
            } catch (IOException e) {
                e.printStackTrace();
            }
            return str;
        }
    }
}

import java.io.*;
import java.util.*;

public class TheLabyrinth {

    /**
     * A robust FastScanner for efficient input reading.
     */
    public static class FastScanner {
        BufferedReader br;
        StringTokenizer st;

        public FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        public FastScanner(String fileName) {
            try {
                br = new BufferedReader(new FileReader(fileName));
            } catch (FileNotFoundException e) {
                throw new RuntimeException("File not found: " + fileName, e);
            }
        }

        String nextToken() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            String s = nextToken();
            return s == null ? 0 : Integer.parseInt(s);
        }

        long nextLong() {
            String s = nextToken();
            return s == null ? 0L : Long.parseLong(s);
        }

        double nextDouble() {
            String s = nextToken();
            return s == null ? 0.0 : Double.parseDouble(s);
        }
    }

    public static void main(String[] args) {
        FastScanner sc = new FastScanner();

        // Read dimensions
        int n = sc.nextInt();
        int m = sc.nextInt();

        // Read grid
        char[][] grid = new char[n][m];
        for (int i = 0; i < n; ++i) {
            String row = sc.nextToken();
            // Handle cases where row might be split or null, though standard input usually guarantees format
            if (row != null) {
                for (int j = 0; j < m && j < row.length(); ++j) {
                    grid[i][j] = row.charAt(j);
                }
            }
        }

        // Data structures for component analysis
        // componentIds[i][j] stores the ID of the connected component for cell (i, j)
        int[][] componentIds = new int[n][m];
        // componentSizes[id] stores the total size of the component with 'id'
        // Max possible components is n * m, so size n*m + 1 is safe
        int[] componentSizes = new int[n * m + 1];
        int currentComponentId = 1;

        // Identify connected components of '.'
        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < m; ++j) {
                if (grid[i][j] == '.' && componentIds[i][j] == 0) {
                    int size = dfs(grid, componentIds, i, j, currentComponentId, n, m);
                    componentSizes[currentComponentId] = size;
                    currentComponentId++;
                }
            }
        }

        // Process '*' cells to calculate replacement values
        int[] dr = {-1, 1, 0, 0}; // Direction vectors for Up, Down, Left, Right
        int[] dc = {0, 0, -1, 1};

        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < m; ++j) {
                if (grid[i][j] == '*') {
                    int sum = 0;
                    // Store neighbor component IDs to avoid duplicates
                    // Since there are at most 4 neighbors, a fixed size array is efficient
                    int[] neighborIds = new int[4];
                    int count = 0;

                    // Check all 4 neighbors
                    for (int k = 0; k < 4; ++k) {
                        int ni = i + dr[k];
                        int nj = j + dc[k];

                        if (ni >= 0 && ni < n && nj >= 0 && nj < m) {
                            int id = componentIds[ni][nj];
                            if (id != 0) {
                                neighborIds[count++] = id;
                            }
                        }
                    }

                    // Sum sizes of unique components
                    for (int k = 0; k < count; ++k) {
                        int id = neighborIds[k];
                        boolean isDuplicate = false;
                        // Check if this ID was already counted
                        for (int p = 0; p < k; ++p) {
                            if (neighborIds[p] == id) {
                                isDuplicate = true;
                                break;
                            }
                        }
                        if (!isDuplicate) {
                            sum += componentSizes[id];
                        }
                    }

                    // Update the cell with (sum + 1) % 10
                    grid[i][j] = (char) ((sum + 1) % 10 + '0');
                }
            }
        }

        // Output the modified grid
        PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out));
        for (int i = 0; i < n; ++i) {
            out.println(new String(grid[i]));
        }
        out.flush();
    }

    /**
     * Performs Depth First Search to find the size of the connected component.
     *
     * @param grid       The grid of characters.
     * @param componentIds 2D array storing component IDs for visited cells.
     * @param r          Current row index.
     * @param c          Current column index.
     * @param currentId  The ID assigned to the current component.
     * @param n          Number of rows.
     * @param m          Number of columns.
     * @return           The size of the connected component found.
     */
    private static int dfs(char[][] grid, int[][] componentIds, int r, int c, int currentId, int n, int m) {
        // Base cases: Out of bounds, blocked cell, or already visited
        if (r < 0 || r >= n || c < 0 || c >= m || grid[r][c] == '*' || componentIds[r][c] != 0) {
            return 0;
        }

        // Mark as visited and assign component ID
        componentIds[r][c] = currentId;
        int size = 1;

        // Recursively visit neighbors
        size += dfs(grid, componentIds, r - 1, c, currentId, n, m);
        size += dfs(grid, componentIds, r + 1, c, currentId, n, m);
        size += dfs(grid, componentIds, r, c - 1, currentId, n, m);
        size += dfs(grid, componentIds, r, c + 1, currentId, n, m);

        return size;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayDeque;
import java.util.HashSet;
import java.util.Queue;
import java.util.Set;

/**
 * Refactored from P616C for improved maintainability and code quality.
 * Reads a maze grid, identifies connected empty regions, and replaces
 * wall markers with the modulo-10 sum of adjacent region sizes.
 */
public class MazeSolver {
    private static final int[] ROW_OFFSETS = {-1, 1, 0, 0};
    private static final int[] COL_OFFSETS = {0, 0, -1, 1};
    private static final char EMPTY_CHAR = '.';
    private static final char WALL_CHAR = '*';

    private final int rows;
    private final int cols;
    private final char[][] grid;
    private final int[][] componentIds;
    private final int[] componentSizes;
    private int componentCount = 0;

    public MazeSolver(int rows, int cols) {
        this.rows = rows;
        this.cols = cols;
        this.grid = new char[rows][cols];
        this.componentIds = new int[rows][cols];
        // Maximum possible number of components is rows * cols
        this.componentSizes = new int[rows * cols + 1];
    }

    public void readInput(BufferedReader reader) throws IOException {
        for (int i = 0; i < rows; i++) {
            String line = reader.readLine();
            if (line != null) {
                grid[i] = line.toCharArray();
            }
        }
    }

    public void findComponents() {
        boolean[][] visited = new boolean[rows][cols];
        Queue<Integer> queue = new ArrayDeque<>();

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == EMPTY_CHAR && !visited[r][c]) {
                    bfs(r, c, visited, queue);
                    componentCount++;
                }
            }
        }
    }

    private void bfs(int startR, int startC, boolean[][] visited, Queue<Integer> queue) {
        int currentComponentId = componentCount;
        int size = 0;

        // Encode 2D coordinates into a single integer to avoid object allocation
        queue.offer(startR * cols + startC);
        visited[startR][startC] = true;

        while (!queue.isEmpty()) {
            int curr = queue.poll();
            int r = curr / cols;
            int c = curr % cols;
            size++;
            componentIds[r][c] = currentComponentId;

            for (int i = 0; i < 4; i++) {
                int nr = r + ROW_OFFSETS[i];
                int nc = c + COL_OFFSETS[i];

                if (isValid(nr, nc) && grid[nr][nc] == EMPTY_CHAR && !visited[nr][nc]) {
                    visited[nr][nc] = true;
                    queue.offer(nr * cols + nc);
                }
            }
        }
        componentSizes[currentComponentId] = size;
    }

    private boolean isValid(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    public void processWalls() {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == WALL_CHAR) {
                    int sum = 0;
                    Set<Integer> adjacentComponents = new HashSet<>();

                    for (int i = 0; i < 4; i++) {
                        int nr = r + ROW_OFFSETS[i];
                        int nc = c + COL_OFFSETS[i];

                        if (isValid(nr, nc) && grid[nr][nc] == EMPTY_CHAR) {
                            adjacentComponents.add(componentIds[nr][nc]);
                        }
                    }

                    for (int compId : adjacentComponents) {
                        sum += componentSizes[compId];
                    }

                    grid[r][c] = (char) ('0' + (sum % 10));
                }
            }
        }
    }

    public String getOutput() {
        StringBuilder sb = new StringBuilder();
        for (int r = 0; r < rows; r++) {
            sb.append(grid[r]).append('\n');
        }
        return sb.toString();
    }

    public static void main(String[] args) throws IOException {
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            String line = br.readLine();
            if (line == null || line.trim().isEmpty()) {
                return;
            }

            String[] dims = line.trim().split("\\s+");
            int rows = Integer.parseInt(dims[0]);
            int cols = Integer.parseInt(dims[1]);

            MazeSolver solver = new MazeSolver(rows, cols);
            solver.readInput(br);
            solver.findComponents();
            solver.processWalls();
            System.out.print(solver.getOutput());
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Deque;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import java.util.StringTokenizer;

public class Main {
    private static final int MOD = 10;
    private static final int[][] DIRECTIONS = {{0, 1}, {1, 0}, {0, -1}, {-1, 0}};

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out);
        try {
            solve(scanner, out);
        } finally {
            out.flush();
        }
    }

    private static void solve(FastScanner scanner, PrintWriter out) {
        int n = scanner.nextInt();
        int m = scanner.nextInt();

        char[][] grid = new char[n][m];
        for (int i = 0; i < n; i++) {
            String row = scanner.next();
            grid[i] = row.toCharArray();
        }

        // Tracks which connected component each '.' cell belongs to
        int[][] componentId = new int[n][m];
        // Stores the size of each component by its ID
        List<Integer> componentSizes = new ArrayList<>();
        // Prevents re-processing cells during traversal
        boolean[][] visited = new boolean[n][m];

        // Identify connected components of '.' characters
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == '.' && !visited[i][j]) {
                    int currentComponentId = componentSizes.size();
                    componentSizes.add(0);

                    Deque<Point> stack = new ArrayDeque<>();
                    stack.push(new Point(i, j));
                    visited[i][j] = true;

                    while (!stack.isEmpty()) {
                        Point p = stack.pop();
                        componentId[p.x][p.y] = currentComponentId;
                        componentSizes.set(currentComponentId, componentSizes.get(currentComponentId) + 1);

                        for (int[] dir : DIRECTIONS) {
                            int nx = p.x + dir[0];
                            int ny = p.y + dir[1];
                            if (isValid(nx, ny, n, m) && grid[nx][ny] == '.' && !visited[nx][ny]) {
                                visited[nx][ny] = true;
                                stack.push(new Point(nx, ny));
                            }
                        }
                    }
                }
            }
        }

        // Build the result grid
        char[][] result = new char[n][m];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == '.') {
                    result[i][j] = '.';
                } else {
                    int count = 1;
                    Set<Integer> visitedComponents = new HashSet<>();
                    for (int[] dir : DIRECTIONS) {
                        int ni = i + dir[0];
                        int nj = j + dir[1];
                        if (isValid(ni, nj, n, m) && grid[ni][nj] == '.') {
                            int cid = componentId[ni][nj];
                            // Avoid double-counting the same adjacent component
                            if (visitedComponents.add(cid)) {
                                count += componentSizes.get(cid);
                            }
                        }
                    }
                    result[i][j] = (char) ('0' + (count % MOD));
                }
            }
        }

        // Output the result
        for (int i = 0; i < n; i++) {
            out.println(new String(result[i]));
        }
    }

    private static boolean isValid(int r, int c, int n, int m) {
        return r >= 0 && r < n && c >= 0 && c < m;
    }

    /**
     * Immutable coordinate record for grid positions.
     */
    private record Point(int x, int y) {}

    /**
     * Fast input reader for competitive programming and performance-critical tasks.
     */
    private static class FastScanner {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastScanner(InputStream in) {
            this.reader = new BufferedReader(new InputStreamReader(in));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input", e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            String token = next();
            if (token == null) throw new RuntimeException("Unexpected end of input");
            return Integer.parseInt(token);
        }
    }
}

import java.io.*;
import java.util.*;

public class TheLabyrinth {

    /** Represents a coordinate in the grid */
    private static class Point {
        final int r, c;
        Point(int r, int c) {
            this.r = r;
            this.c = c;
        }
    }

    /** High-performance input reader */
    private static class FastReader {
        private final InputStream is;
        private final byte[] buf = new byte[1024];
        private int curChar, numChars;

        public FastReader() {
            this(System.in);
        }

        public FastReader(InputStream is) {
            this.is = is;
        }

        private int read() {
            if (numChars == -1) throw new NoSuchElementException();
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = is.read(buf);
                } catch (IOException e) {
                    throw new NoSuchElementException();
                }
                if (numChars <= 0) return -1;
            }
            return buf[curChar++];
        }

        public String next() {
            int c = read();
            while (isSpaceChar(c)) {
                if (c == -1) throw new NoSuchElementException();
                c = read();
            }
            StringBuilder res = new StringBuilder();
            do {
                res.appendCodePoint(c);
                c = read();
            } while (!isSpaceChar(c));
            return res.toString();
        }

        public int i() {
            int c = read();
            while (isSpaceChar(c)) {
                if (c == -1) throw new NoSuchElementException();
                c = read();
            }
            int sgn = (c == '-') ? -1 : 1;
            if (c == '-') c = read();
            int res = 0;
            do {
                if (c < '0' || c > '9') throw new InputMismatchException();
                res = res * 10 + (c - '0');
                c = read();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        private boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }
    }

    // Direction vectors: Right, Left, Down, Up
    private static final int[] DR = {0, 0, 1, -1};
    private static final int[] DC = {1, -1, 0, 0};

    public static void main(String[] args) {
        FastReader sc = new FastReader();
        // Try-with-resources ensures PrintWriter is properly flushed and closed
        try (PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out))) {
            solve(sc, out);
        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    private static void solve(FastReader sc, PrintWriter out) {
        int rows = sc.i();
        int cols = sc.i();

        // Read grid into char[][] for efficient access
        char[][] grid = new char[rows][];
        for (int i = 0; i < rows; i++) {
            grid[i] = sc.next().toCharArray();
        }

        // DP tables: componentId[r][c] and componentSize[r][c]
        int[][] componentId = new int[rows][cols];
        int[][] componentSize = new int[rows][cols];
        boolean[][] visited = new boolean[rows][cols];
        int componentCount = 0;

        // Step 1: Identify and label connected components of '.' cells
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '.' && !visited[r][c]) {
                    componentCount++;
                    bfs(grid, visited, componentId, componentSize, r, c, componentCount);
                }
            }
        }

        // Step 2: Calculate merged component sizes for '*' cells
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '.') {
                    out.print('.');
                } else {
                    int totalSize = 1; // Base size for the '*' cell itself
                    Set<Integer> seenComponents = new HashSet<>();

                    for (int k = 0; k < 4; k++) {
                        int nr = r + DR[k];
                        int nc = c + DC[k];
                        if (isValid(nr, nc, rows, cols) && grid[nr][nc] == '.') {
                            int id = componentId[nr][nc];
                            // Avoid double-counting if multiple adjacent cells belong to the same component
                            if (seenComponents.add(id)) {
                                totalSize += componentSize[nr][nc];
                            }
                        }
                    }
                    out.print(totalSize % 10);
                }
            }
            out.println();
        }
    }

    /** Performs BFS to find all cells in a connected component and assigns their ID/Size */
    private static void bfs(char[][] grid, boolean[][] visited, int[][] componentId, int[][] componentSize,
                            int startR, int startC, int id) {
        List<Point> componentCells = new ArrayList<>();
        Queue<Point> queue = new ArrayDeque<>();

        queue.add(new Point(startR, startC));
        visited[startR][startC] = true;
        componentId[startR][startC] = id;
        componentCells.add(new Point(startR, startC));

        while (!queue.isEmpty()) {
            Point curr = queue.poll();
            for (int k = 0; k < 4; k++) {
                int nr = curr.r + DR[k];
                int nc = curr.c + DC[k];
                if (isValid(nr, nc, grid.length, grid[0].length) && grid[nr][nc] == '.' && !visited[nr][nc]) {
                    visited[nr][nc] = true;
                    componentId[nr][nc] = id;
                    componentCells.add(new Point(nr, nc));
                    queue.add(new Point(nr, nc));
                }
            }
        }

        // Assign the final component size to all cells in this component
        int size = componentCells.size();
        for (Point p : componentCells) {
            componentSize[p.r][p.c] = size;
        }
    }

    /** Checks if coordinates are within grid bounds */
    private static boolean isValid(int r, int c, int rows, int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }
}

import java.io.*;
import java.util.*;

/**
 * Processes a grid to compute connected components of empty cells.
 * For each obstacle cell ('*'), calculates the sum of sizes of adjacent
 * connected components, modulo 10, and outputs the transformed grid.
 */
public class ConnectedComponentGridProcessor {

    private static final int[][] DIRECTIONS = {
        {1, 0}, {-1, 0}, {0, 1}, {0, -1}
    };

    public static void main(String[] args) throws IOException {
        // Use try-with-resources to ensure streams are properly closed
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
             PrintWriter writer = new PrintWriter(new BufferedOutputStream(System.out))) {

            FastScanner scanner = new FastScanner(reader);

            String nStr = scanner.next();
            if (nStr == null) return; // Handle empty input gracefully

            int rows = Integer.parseInt(nStr);
            int cols = Integer.parseInt(scanner.next());

            // 1. Read and initialize the grid
            int[][] grid = readGrid(scanner, rows, cols);

            // 2. Label connected components and compute their sizes
            int[] componentSizes = computeComponentSizes(grid, rows, cols);

            // 3. Calculate adjacent component sums for obstacle cells
            char[][] resultGrid = calculateResultGrid(grid, componentSizes, rows, cols);

            // 4. Output the transformed grid
            printGrid(writer, resultGrid);
            writer.flush();
        }
    }

    /**
     * Reads the grid from input. Marks obstacles as -1 and empty cells as 0.
     */
    private static int[][] readGrid(FastScanner scanner, int rows, int cols) throws IOException {
        int[][] grid = new int[rows][cols];
        for (int r = 0; r < rows; r++) {
            String line = scanner.next();
            for (int c = 0; c < cols; c++) {
                grid[r][c] = (line.charAt(c) == '*') ? -1 : 0;
            }
        }
        return grid;
    }

    /**
     * Uses BFS to label each connected component of empty cells with a unique ID.
     * Returns an array where index i contains the size of component i.
     */
    private static int[] computeComponentSizes(int[][] grid, int rows, int cols) {
        int[] componentSizes = new int[rows * cols + 1];
        int componentId = 1;

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == 0) {
                    grid[r][c] = componentId;
                    int currentSize = bfs(grid, r, c, componentId, rows, cols);
                    componentSizes[componentId] = currentSize;
                    componentId++;
                }
            }
        }
        return componentSizes;
    }

    /**
     * Performs BFS to find all cells in the same connected component.
     * Encodes (row, col) as row * cols + col for memory efficiency.
     */
    private static int bfs(int[][] grid, int startR, int startC, int componentId, int rows, int cols) {
        int size = 0;
        Queue<Integer> queue = new ArrayDeque<>();
        queue.add(startR * cols + startC);

        while (!queue.isEmpty()) {
            int pos = queue.poll();
            int r = pos / cols;
            int c = pos % cols;
            size++;

            for (int[] dir : DIRECTIONS) {
                int nr = r + dir[0];
                int nc = c + dir[1];

                if (nr >= 0 && nr < rows && nc >= 0 && nc < cols && grid[nr][nc] == 0) {
                    grid[nr][nc] = componentId; // Mark as visited immediately
                    queue.add(nr * cols + nc);
                }
            }
        }
        return size;
    }

    /**
     * Generates the output grid. Replaces '*' with the sum of adjacent component sizes % 10.
     * Keeps '.' cells as '.'.
     */
    private static char[][] calculateResultGrid(int[][] grid, int[] componentSizes, int rows, int cols) {
        char[][] result = new char[rows][cols];

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == -1) {
                    int adjacentSizeSum = 1; // Count the '*' cell itself
                    Set<Integer> adjacentComponents = new HashSet<>();

                    for (int[] dir : DIRECTIONS) {
                        int nr = r + dir[0];
                        int nc = c + dir[1];

                        if (nr >= 0 && nr < rows && nc >= 0 && nc < cols && grid[nr][nc] != -1) {
                            adjacentComponents.add(grid[nr][nc]);
                        }
                    }

                    for (int compId : adjacentComponents) {
                        adjacentSizeSum += componentSizes[compId];
                    }

                    result[r][c] = (char) ('0' + (adjacentSizeSum % 10));
                } else {
                    result[r][c] = '.';
                }
            }
        }
        return result;
    }

    /**
     * Prints the character grid to the provided writer.
     */
    private static void printGrid(PrintWriter writer, char[][] grid) {
        for (char[] row : grid) {
            writer.println(new String(row));
        }
    }

    /**
     * Lightweight fast scanner for competitive programming / fast I/O.
     */
    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner(BufferedReader br) {
            this.br = br;
            this.st = new StringTokenizer("");
        }

        public String next() throws IOException {
            while (!st.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) return null;
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

        public int nextInt() throws IOException {
            String s = next();
            return s == null ? 0 : Integer.parseInt(s);
        }
    }
}

import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        FastReader in = new FastReader();
        PrintWriter out = new PrintWriter(System.out);

        int n = in.nextInt();
        int m = in.nextInt();
        char[][] grid = new char[n][];
        for (int i = 0; i < n; i++) {
            grid[i] = in.next().toCharArray();
        }

        GridSolver solver = new GridSolver(grid, n, m);
        solver.solve(out);
        out.flush();
    }

    /**
     * Encapsulates grid analysis and output generation logic.
     * Avoids global mutable state for better maintainability.
     */
    private static class GridSolver {
        private final char[][] grid;
        private final int n;
        private final int m;
        private final int[][] componentIds;
        private final int[] componentSizes;
        private int currentComponentId;

        // Direction vectors for Up, Left, Right, Down
        private static final int[] DR = {-1, 0, 0, 1};
        private static final int[] DC = {0, -1, 1, 0};

        public GridSolver(char[][] grid, int n, int m) {
            this.grid = grid;
            this.n = n;
            this.m = m;
            this.componentIds = new int[n][m];
            this.componentSizes = new int[n * m + 1]; // 1-based indexing for component IDs
            this.currentComponentId = 0;
        }

        public void solve(PrintWriter out) {
            // Step 1: Identify connected components of '.'
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    if (grid[i][j] == '.' && componentIds[i][j] == 0) {
                        currentComponentId++;
                        componentSizes[currentComponentId] = dfs(i, j);
                    }
                }
            }

            // Step 2: Calculate merged sizes and print output
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    if (grid[i][j] == '.') {
                        out.print('.');
                    } else {
                        Set<Integer> adjacentComponents = new HashSet<>();
                        for (int k = 0; k < 4; k++) {
                            int r = i + DR[k];
                            int c = j + DC[k];
                            if (isValid(r, c) && grid[r][c] == '.') {
                                adjacentComponents.add(componentIds[r][c]);
                            }
                        }

                        int mergedSize = 1; // Account for the current cell becoming '.'
                        for (int compId : adjacentComponents) {
                            mergedSize += componentSizes[compId];
                        }
                        out.print(mergedSize % 10);
                    }
                }
                out.println();
            }
        }

        private boolean isValid(int r, int c) {
            return r >= 0 && r < n && c >= 0 && c < m;
        }

        /**
         * Performs DFS to calculate the size of a connected component.
         * Marks visited cells with the current component ID.
         */
        private int dfs(int r, int c) {
            componentIds[r][c] = currentComponentId;
            int size = 1;
            for (int k = 0; k < 4; k++) {
                int nr = r + DR[k];
                int nc = c + DC[k];
                if (isValid(nr, nc) && grid[nr][nc] == '.' && componentIds[nr][nc] == 0) {
                    size += dfs(nr, nc);
                }
            }
            return size;
        }
    }

    /**
     * Optimized input reader for competitive programming / fast I/O.
     */
    private static class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        public String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            String s = next();
            return s == null ? 0 : Integer.parseInt(s);
        }
    }
}

import java.util.ArrayDeque;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Queue;
import java.util.Scanner;
import java.util.Set;

public class Main {

    // Constants to replace magic numbers and improve readability
    private static final int[][] DIRECTIONS = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};
    private static final int MODULO = 10;
    private static final char OBSTACLE = '*';
    private static final char EMPTY = '.';

    public static void main(String[] args) {
        // Use try-with-resources to ensure Scanner is closed properly
        try (Scanner scanner = new Scanner(System.in)) {
            if (!scanner.hasNextInt()) {
                return;
            }

            int rows = scanner.nextInt();
            int cols = scanner.nextInt();
            scanner.nextLine(); // Consume the newline character after the integers

            char[][] grid = new char[rows][cols];
            for (int r = 0; r < rows; r++) {
                String line = scanner.nextLine();
                // Ensure we handle the input safely, though valid input is assumed
                if (line.length() >= cols) {
                    grid[r] = line.toCharArray();
                } else {
                    // Fallback for short lines if necessary, though unlikely in valid inputs
                    grid[r] = new char[cols];
                    line.getChars(0, line.length(), grid[r], 0);
                }
            }

            processGrid(rows, cols, grid);
        }
    }

    /**
     * Processes the grid to identify regions and calculate the output.
     */
    private static void processGrid(int rows, int cols, char[][] grid) {
        // regionIds[r][c] stores the ID of the region the cell belongs to.
        // 0 indicates the cell is an obstacle or unvisited.
        int[][] regionIds = new int[rows][cols];
        Map<Integer, Integer> regionSizes = new HashMap<>();
        int currentRegionId = 0;

        // 1. Identify and size regions using Iterative BFS to prevent StackOverflow
        // that could occur with deep recursion on large grids.
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                // If cell is empty and not yet visited
                if (grid[r][c] == EMPTY && regionIds[r][c] == 0) {
                    currentRegionId++;
                    int size = bfsFill(grid, regionIds, r, c, currentRegionId, rows, cols);
                    regionSizes.put(currentRegionId, size);
                }
            }
        }

        // 2. Generate the output grid
        StringBuilder output = new StringBuilder();
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == OBSTACLE) {
                    // Calculate sum of adjacent regions + 1 (itself)
                    int sum = 1;
                    Set<Integer> adjacentRegionIds = new HashSet<>();

                    for (int[] dir : DIRECTIONS) {
                        int nr = r + dir[0];
                        int nc = c + dir[1];

                        if (isValid(nr, nc, rows, cols) && grid[nr][nc] != OBSTACLE) {
                            int neighborRegionId = regionIds[nr][nc];
                            // Ensure we don't double count the same region if multiple neighbors belong to it
                            if (!adjacentRegionIds.contains(neighborRegionId)) {
                                adjacentRegionIds.add(neighborRegionId);
                                sum += regionSizes.get(neighborRegionId);
                            }
                        }
                    }
                    output.append((char) ((sum % MODULO) + '0'));
                } else {
                    output.append(EMPTY);
                }
            }
            output.append('\n');
        }
        System.out.print(output);
    }

    /**
     * Performs an iterative Breadth-First Search to fill a region.
     * 
     * @param grid The character grid
     * @param regionIds The 2D array storing region IDs for each cell
     * @param startR Starting row index
     * @param startC Starting column index
     * @param regionId The ID to assign to this new region
     * @param rows Total number of rows
     * @param cols Total number of columns
     * @return The total number of cells in the region
     */
    private static int bfsFill(char[][] grid, int[][] regionIds, int startR, int startC, int regionId, int rows, int cols) {
        int count = 0;
        Queue<int[]> queue = new ArrayDeque<>();

        // Initialize start cell
        queue.offer(new int[]{startR, startC});
        regionIds[startR][startC] = regionId;
        count++;

        while (!queue.isEmpty()) {
            int[] current = queue.poll();
            int r = current[0];
            int c = current[1];

            for (int[] dir : DIRECTIONS) {
                int nr = r + dir[0];
                int nc = c + dir[1];

                if (isValid(nr, nc, rows, cols) && grid[nr][nc] == EMPTY && regionIds[nr][nc] == 0) {
                    regionIds[nr][nc] = regionId;
                    count++;
                    queue.offer(new int[]{nr, nc});
                }
            }
        }
        return count;
    }

    /**
     * Checks if the given coordinates are within the grid boundaries.
     */
    private static boolean isValid(int r, int c, int rows, int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }
}

import java.io.InputStream;
import java.io.IOException;
import java.util.ArrayDeque;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Queue;
import java.util.Set;

public class CF5C {
    // Directions for 4-connectivity: up, down, left, right
    private static final int[] DX = {-1, 1, 0, 0};
    private static final int[] DY = {0, 0, -1, 1};

    public static void main(String[] args) throws IOException {
        FastScanner sc = new FastScanner(System.in);

        // Read grid dimensions
        int n = sc.nextInt();
        int m = sc.nextInt();

        // Read grid and convert '.' to boolean true
        boolean[][] grid = new boolean[n][m];
        for (int i = 0; i < n; i++) {
            String row = sc.next();
            for (int j = 0; j < m; j++) {
                grid[i][j] = row.charAt(j) == '.';
            }
        }

        // Solve and print result
        System.out.println(solve(grid));
    }

    /**
     * Main solver logic. Pure function that takes the grid and returns the formatted output.
     */
    private static String solve(boolean[][] grid) {
        int n = grid.length;
        int m = grid[0].length;

        int[][] componentId = new int[n][m];
        Map<Integer, Integer> componentSizes = new HashMap<>();
        int currentId = 1;

        // 1. Identify connected components of '.' cells using BFS
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] && componentId[i][j] == 0) {
                    int size = traverseComponent(grid, componentId, i, j, currentId);
                    componentSizes.put(currentId, size);
                    currentId++;
                }
            }
        }

        // 2. Generate the output grid
        StringBuilder result = new StringBuilder();
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j]) {
                    // Walkable cells remain '.'
                    result.append('.');
                } else {
                    // Calculate sum of adjacent component sizes + 1
                    int adjacentCount = calculateAdjacentCount(grid, componentId, componentSizes, i, j);
                    result.append(adjacentCount == 0 ? '.' : (adjacentCount % 10));
                }
            }
            result.append('\n');
        }

        return result.toString();
    }

    /**
     * Performs BFS to find all cells in the same connected component.
     * Marks them with the given ID and returns the component size.
     */
    private static int traverseComponent(boolean[][] grid, int[][] componentId,
                                         int startX, int startY, int id) {
        int n = grid.length;
        int m = grid[0].length;
        int count = 0;
        Queue<int[]> queue = new ArrayDeque<>();

        queue.offer(new int[]{startX, startY});
        componentId[startX][startY] = id;
        count++;

        while (!queue.isEmpty()) {
            int[] current = queue.poll();
            for (int d = 0; d < 4; d++) {
                int nx = current[0] + DX[d];
                int ny = current[1] + DY[d];

                if (isValid(nx, ny, n, m) && grid[nx][ny] && componentId[nx][ny] == 0) {
                    componentId[nx][ny] = id;
                    count++;
                    queue.offer(new int[]{nx, ny});
                }
            }
        }
        return count;
    }

    /**
     * Calculates the sum of sizes of unique adjacent components + 1.
     */
    private static int calculateAdjacentCount(boolean[][] grid, int[][] componentId,
                                              Map<Integer, Integer> componentSizes, int x, int y) {
        int count = 1; // Count the cell itself
        Set<Integer> seenComponents = new HashSet<>();

        for (int d = 0; d < 4; d++) {
            int nx = x + DX[d];
            int ny = y + DY[d];

            if (isValid(nx, ny, grid.length, grid[0].length) && grid[nx][ny]) {
                int id = componentId[nx][ny];
                // Avoid double-counting the same component from multiple neighbors
                if (seenComponents.add(id)) {
                    count += componentSizes.get(id);
                }
            }
        }
        return count;
    }

    /**
     * Boundary validation helper.
     */
    private static boolean isValid(int x, int y, int n, int m) {
        return x >= 0 && x < n && y >= 0 && y < m;
    }

    /**
     * Fast input reader optimized for competitive programming.
     */
    private static class FastScanner {
        private final InputStream stream;
        private final byte[] buffer = new byte[1024];
        private int bufferPtr = 0;
        private int bytesRead = 0;

        public FastScanner(InputStream stream) {
            this.stream = stream;
        }

        private int read() throws IOException {
            if (bufferPtr >= bytesRead) {
                bufferPtr = 0;
                bytesRead = stream.read(buffer);
                if (bytesRead <= 0) {
                    return -1;
                }
            }
            return buffer[bufferPtr++];
        }

        public int nextInt() throws IOException {
            return (int) nextLong();
        }

        public long nextLong() throws IOException {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
                if (c == -1) {
                    throw new IOException("Unexpected end of input");
                }
            }
            boolean negative = false;
            if (c == '-') {
                negative = true;
                c = read();
            }
            long res = 0;
            do {
                if (c < '0' || c > '9') {
                    throw new IOException("Invalid number format");
                }
                res *= 10;
                res += (c - '0');
                c = read();
            } while (!isSpaceChar(c));
            return negative ? -res : res;
        }

        public String next() throws IOException {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            StringBuilder sb = new StringBuilder();
            do {
                sb.append((char) c);
                c = read();
            } while (!isSpaceChar(c));
            return sb.toString();
        }

        private boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.ArrayDeque;
import java.util.HashSet;
import java.util.Set;

/**
 * A program to analyze a grid of blocked and empty cells.
 * It identifies connected components of empty cells and calculates
 * a specific value for blocked cells based on their neighbors.
 */
public class GridConnectedComponents {

    // Direction vectors for moving Right, Left, Down, Up
    // DX corresponds to column changes, DY corresponds to row changes
    private static final int[] DX = {1, -1, 0, 0};
    private static final int[] DY = {0, 0, 1, -1};

    public static void main(String[] args) throws IOException {
        // Initialize fast I/O
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter writer = new PrintWriter(System.out);

        try {
            solve(reader, writer);
        } finally {
            // Ensure output is written and resources are closed
            writer.flush();
            writer.close();
        }
    }

    private static void solve(BufferedReader reader, PrintWriter writer) throws IOException {
        // 1. Read Grid Dimensions
        String line = reader.readLine();
        if (line == null) return;

        String[] dimensions = line.trim().split("\\s+");
        if (dimensions.length < 2) return;

        int rows = Integer.parseInt(dimensions[0]);
        int cols = Integer.parseInt(dimensions[1]);

        // 2. Read the Grid
        // Using char[][] to preserve the visual representation of the grid
        char[][] grid = new char[rows][cols];
        for (int r = 0; r < rows; r++) {
            String rowLine = reader.readLine();
            if (rowLine != null) {
                for (int c = 0; c < cols && c < rowLine.length(); c++) {
                    grid[r][c] = rowLine.charAt(c);
                }
            }
        }

        // 3. Identify Connected Components (Regions)
        // componentMap[r][c] stores the ID of the region the cell belongs to.
        // 0 indicates a blocked cell or an unvisited empty cell.
        int[][] componentMap = new int[rows][cols];

        // componentSizes[id] stores the size of region 'id'. 
        // Index 0 is unused as region IDs start at 1.
        int[] componentSizes = new int[rows * cols + 1];

        int currentRegionId = 0;

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                // If cell is not blocked ('*') and not yet visited (0)
                if (grid[r][c] != '*' && componentMap[r][c] == 0) {
                    currentRegionId++;
                    // Perform BFS to find the size of this component
                    int size = bfs(grid, componentMap, rows, cols, r, c, currentRegionId);
                    componentSizes[currentRegionId] = size;
                }
            }
        }

        // 4. Generate Output
        for (int r = 0; r < rows; r++) {
            StringBuilder sb = new StringBuilder();
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '*') {
                    // Calculate value for blocked cell
                    int totalSize = 1; // Count the cell itself

                    // Use a Set to store unique neighbor region IDs
                    Set<Integer> uniqueNeighborRegions = new HashSet<>();

                    for (int i = 0; i < 4; i++) {
                        int nr = r + DY[i];
                        int nc = c + DX[i];

                        if (isValid(nr, nc, rows, cols) && grid[nr][nc] != '*') {
                            // Add neighbor's region ID to set to handle duplicates automatically
                            uniqueNeighborRegions.add(componentMap[nr][nc]);
                        }
                    }

                    // Sum sizes of unique neighbor regions
                    for (int regionId : uniqueNeighborRegions) {
                        totalSize += componentSizes[regionId];
                    }

                    sb.append(totalSize % 10);
                } else {
                    sb.append('.');
                }
            }
            writer.println(sb.toString());
        }
    }

    /**
     * Performs a Breadth-First Search (BFS) to identify all cells in a connected component.
     *
     * @param grid The 2D character grid.
     * @param componentMap The map storing region IDs for each cell.
     * @param rows Number of rows.
     * @param cols Number of columns.
     * @param startR Starting row coordinate.
     * @param startC Starting column coordinate.
     * @param regionId The ID to assign to this component.
     * @return The size (number of cells) of the connected component.
     */
    private static int bfs(char[][] grid, int[][] componentMap, int rows, int cols,
                           int startR, int startC, int regionId) {
        int size = 0;

        // ArrayDeque is preferred over ArrayList for queues as it offers O(1) add/remove
        ArrayDeque<Integer> queue = new ArrayDeque<>();

        // Encode coordinates as a single integer: r * cols + c
        queue.add(startR * cols + startC);
        componentMap[startR][startC] = regionId;
        size++;

        while (!queue.isEmpty()) {
            int current = queue.poll();
            int r = current / cols;
            int c = current % cols;

            for (int i = 0; i < 4; i++) {
                int nr = r + DY[i];
                int nc = c + DX[i];

                // Check bounds, if not blocked, and if not yet visited
                if (isValid(nr, nc, rows, cols) && grid[nr][nc] != '*' && componentMap[nr][nc] == 0) {
                    componentMap[nr][nc] = regionId;
                    queue.add(nr * cols + nc);
                    size++;
                }
            }
        }
        return size;
    }

    /**
     * Checks if the given coordinates are within the grid boundaries.
     */
    private static boolean isValid(int r, int c, int rows, int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.ArrayList;
import java.util.ArrayDeque;
import java.util.List;
import java.util.Queue;

public class CEdu52 {
    // Direction vectors for Up, Down, Left, Right
    private static final int[] DR = {-1, 1, 0, 0};
    private static final int[] DC = {0, 0, -1, 1};

    public static void main(String[] args) throws IOException {
        // Use try-with-resources for automatic and safe resource management
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
             PrintWriter writer = new PrintWriter(System.out)) {

            String[] dims = reader.readLine().split("\\s+");
            int rows = Integer.parseInt(dims[0]);
            int cols = Integer.parseInt(dims[1]);

            char[][] grid = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                grid[i] = reader.readLine().toCharArray();
            }

            // 0 indicates unvisited cells. Component IDs start from 1.
            int[][] componentIds = new int[rows][cols];
            int[][] componentSizes = new int[rows][cols];
            int currentComponentId = 1;

            // Identify connected components of '.' cells
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] == '.') {
                        List<Integer> cells = bfs(r, c, grid, componentIds, currentComponentId, rows, cols);
                        int size = cells.size();

                        // Assign the calculated size to all cells belonging to this component
                        for (int pos : cells) {
                            componentSizes[pos / cols][pos % cols] = size;
                        }
                        currentComponentId++;
                    }
                }
            }

            // Build the result grid
            StringBuilder result = new StringBuilder();
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] == '*') {
                        int adjacentSize = calculateAdjacentSize(r, c, componentIds, componentSizes, currentComponentId, rows, cols);
                        result.append(adjacentSize % 10);
                    } else {
                        result.append('.');
                    }
                }
                result.append('\n');
            }

            writer.print(result);
        }
    }

    /**
     * Performs BFS to find all cells in the connected component.
     * Marks visited cells with the provided componentId and returns their packed coordinates.
     */
    private static List<Integer> bfs(int startR, int startC, char[][] grid, int[][] componentIds, 
                                     int componentId, int rows, int cols) {
        Queue<Integer> queue = new ArrayDeque<>();
        List<Integer> cells = new ArrayList<>();

        queue.add(pack(startR, startC, cols));
        componentIds[startR][startC] = componentId;
        cells.add(pack(startR, startC, cols));

        while (!queue.isEmpty()) {
            int pos = queue.poll();
            int r = pos / cols;
            int c = pos % cols;

            for (int i = 0; i < 4; i++) {
                int nr = r + DR[i];
                int nc = c + DC[i];

                if (isValid(nr, nc, rows, cols) && grid[nr][nc] == '.' && componentIds[nr][nc] == 0) {
                    componentIds[nr][nc] = componentId;
                    queue.add(pack(nr, nc, cols));
                    cells.add(pack(nr, nc, cols));
                }
            }
        }
        return cells;
    }

    /**
     * Calculates the sum of adjacent component sizes plus the '*' cell itself.
     * Uses a boolean array for O(1) duplicate component detection.
     */
    private static int calculateAdjacentSize(int r, int c, int[][] componentIds, int[][] componentSizes, 
                                             int maxComponentId, int rows, int cols) {
        int totalSize = 1; // The '*' cell itself counts as 1
        boolean[] seenComponents = new boolean[maxComponentId + 1];

        for (int i = 0; i < 4; i++) {
            int nr = r + DR[i];
            int nc = c + DC[i];

            if (isValid(nr, nc, rows, cols)) {
                int compId = componentIds[nr][nc];
                if (compId > 0 && !seenComponents[compId]) {
                    totalSize += componentSizes[nr][nc];
                    seenComponents[compId] = true;
                }
            }
        }
        return totalSize;
    }

    /**
     * Checks if coordinates are within grid boundaries.
     */
    private static boolean isValid(int r, int c, int rows, int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /**
     * Packs row and column into a single integer to reduce object allocation overhead.
     */
    private static int pack(int r, int c, int cols) {
        return r * cols + c;
    }
}

import java.io.PrintWriter;
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.HashSet;
import java.util.List;
import java.util.Queue;
import java.util.Scanner;
import java.util.Set;

public class C {
    private static final int[][] DIRECTIONS = {{0, 1}, {0, -1}, {1, 0}, {-1, 0}};

    /**
     * Checks if coordinates are within grid bounds.
     * @param x Column index
     * @param y Row index
     * @param cols Total number of columns
     * @param rows Total number of rows
     * @return true if coordinates are valid, false otherwise
     */
    private static boolean isValid(int x, int y, int cols, int rows) {
        return x >= 0 && x < cols && y >= 0 && y < rows;
    }

    /**
     * Performs BFS to find the size of a connected component of non-blocked cells.
     *
     * @param startCol Starting column index
     * @param startRow Starting row index
     * @param cols Total number of columns
     * @param rows Total number of rows
     * @param isBlocked 2D array marking blocked cells
     * @param componentIds 2D array storing component IDs (-1 if unvisited)
     * @param id Component identifier to assign
     * @return Size of the connected component
     */
    private static int bfs(int startCol, int startRow, int cols, int rows,
                           boolean[][] isBlocked, int[][] componentIds, int id) {
        if (isBlocked[startRow][startCol] || componentIds[startRow][startCol] != -1) {
            return 0;
        }

        Queue<int[]> queue = new ArrayDeque<>();
        queue.add(new int[]{startCol, startRow});
        componentIds[startRow][startCol] = id;
        int count = 1;

        while (!queue.isEmpty()) {
            int[] current = queue.poll();
            int x = current[0];
            int y = current[1];

            for (int[] dir : DIRECTIONS) {
                int nx = x + dir[0];
                int ny = y + dir[1];

                if (isValid(nx, ny, cols, rows) && !isBlocked[ny][nx] && componentIds[ny][nx] == -1) {
                    componentIds[ny][nx] = id;
                    queue.add(new int[]{nx, ny});
                    count++;
                }
            }
        }
        return count;
    }

    public static void main(String[] args) {
        try (Scanner sc = new Scanner(System.in);
             PrintWriter out = new PrintWriter(System.out)) {

            int rows = sc.nextInt();
            int cols = sc.nextInt();

            // Read grid layout
            boolean[][] isBlocked = new boolean[rows][cols];
            for (int i = 0; i < rows; i++) {
                String line = sc.next();
                for (int j = 0; j < cols; j++) {
                    isBlocked[i][j] = line.charAt(j) == '*';
                }
            }

            // Initialize component ID map with -1 (unvisited)
            int[][] componentIds = new int[rows][cols];
            for (int[] row : componentIds) {
                Arrays.fill(row, -1);
            }

            // Identify connected components and store their sizes
            List<Integer> componentSizes = new ArrayList<>();
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (!isBlocked[i][j] && componentIds[i][j] == -1) {
                        componentSizes.add(bfs(j, i, cols, rows, isBlocked, componentIds, componentSizes.size()));
                    }
                }
            }

            // Compute and format output
            StringBuilder sb = new StringBuilder();
            for (int y = 0; y < rows; y++) {
                for (int x = 0; x < cols; x++) {
                    if (!isBlocked[y][x]) {
                        sb.append('.');
                        continue;
                    }

                    long answer = 1;
                    Set<Integer> adjacentIds = new HashSet<>();
                    for (int[] dir : DIRECTIONS) {
                        int nx = x + dir[0];
                        int ny = y + dir[1];

                        if (isValid(nx, ny, cols, rows) && !isBlocked[ny][nx]) {
                            int id = componentIds[ny][nx];
                            // add() returns false if the element already exists, avoiding duplicates
                            if (adjacentIds.add(id)) {
                                answer += componentSizes.get(id);
                            }
                        }
                    }
                    sb.append(answer % 10);
                }
                sb.append('\n');
            }
            out.print(sb);
            out.flush();
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.OutputStreamWriter;
import java.io.PrintWriter;
import java.util.StringTokenizer;

public class Educational5C {
    // Direction vectors for moving up, down, left, right
    private static final int[][] DIRECTIONS = {{0, 1}, {0, -1}, {-1, 0}, {1, 0}};

    public static void main(String[] args) throws IOException {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter writer = new PrintWriter(new OutputStreamWriter(System.out));

        try {
            solve(reader, writer);
        } finally {
            writer.flush();
            writer.close();
        }
    }

    private static void solve(BufferedReader reader, PrintWriter writer) throws IOException {
        String line = reader.readLine();
        if (line == null || line.trim().isEmpty()) {
            return;
        }

        StringTokenizer st = new StringTokenizer(line);
        int n = Integer.parseInt(st.nextToken());
        int m = Integer.parseInt(st.nextToken());

        // Read the grid
        char[][] grid = new char[n][m];
        for (int i = 0; i < n; i++) {
            String row = reader.readLine();
            grid[i] = (row != null) ? row.toCharArray() : new char[m];
        }

        // Arrays to store component ID for each cell and size of each component
        int[][] componentId = new int[n][m];
        int[] componentSizes = new int[n * m + 1]; // 1-based indexing for components
        int numComponents = 0;

        // Iterative BFS queue to prevent StackOverflowError on large grids
        int[] qX = new int[n * m];
        int[] qY = new int[n * m];

        // Step 1: Identify connected components of '.' characters
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == '.' && componentId[i][j] == 0) {
                    numComponents++;
                    componentSizes[numComponents] = 0;

                    int head = 0, tail = 0;
                    qX[tail] = i; qY[tail] = j; tail++;
                    componentId[i][j] = numComponents;
                    componentSizes[numComponents]++;

                    while (head < tail) {
                        int cx = qX[head];
                        int cy = qY[head];
                        head++;

                        for (int[] dir : DIRECTIONS) {
                            int nx = cx + dir[0];
                            int ny = cy + dir[1];
                            if (nx >= 0 && nx < n && ny >= 0 && ny < m && 
                                grid[nx][ny] == '.' && componentId[nx][ny] == 0) {
                                componentId[nx][ny] = numComponents;
                                componentSizes[numComponents]++;
                                qX[tail] = nx; qY[tail] = ny; tail++;
                            }
                        }
                    }
                }
            }
        }

        // Step 2: Construct the output grid
        StringBuilder[] resultRows = new StringBuilder[n];
        for (int i = 0; i < n; i++) {
            resultRows[i] = new StringBuilder();
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == '.') {
                    resultRows[i].append('.');
                } else {
                    int totalSize = 0;
                    boolean[] seenComponents = new boolean[numComponents + 1];

                    for (int[] dir : DIRECTIONS) {
                        int nx = i + dir[0];
                        int ny = j + dir[1];
                        if (nx >= 0 && nx < n && ny >= 0 && ny < m && grid[nx][ny] == '.') {
                            int cid = componentId[nx][ny];
                            if (!seenComponents[cid]) {
                                totalSize += componentSizes[cid];
                                seenComponents[cid] = true;
                            }
                        }
                    }
                    resultRows[i].append(totalSize % 10);
                }
            }
        }

        // Step 3: Output results
        for (int i = 0; i < n; i++) {
            String rowStr = resultRows[i].toString();
            // Preserved original logic that skips the first 4 characters.
            // Guarded against IndexOutOfBoundsException for safety.
            if (rowStr.length() > 4) {
                rowStr = rowStr.substring(4);
            }
            writer.println(rowStr);
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.OutputStream;
import java.io.PrintWriter;
import java.util.Arrays;
import java.util.StringTokenizer;

public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        TaskC solver = new TaskC();
        solver.solve(1, in, out);
        out.close();
    }

    static class TaskC {
        // Direction vectors for moving up, left, down, right
        private static final int[] DX = {-1, 0, 1, 0};
        private static final int[] DY = {0, -1, 0, 1};

        public void solve(int testNumber, InputReader in, PrintWriter out) {
            int n = in.nextInt();
            int m = in.nextInt();
            char[][] grid = new char[n][];
            for (int i = 0; i < n; i++) {
                grid[i] = in.next().toCharArray();
            }

            // Maps each '.' cell to a component ID. -1 means unvisited or not a '.'
            int[][] componentId = new int[n][m];
            for (int[] row : componentId) {
                Arrays.fill(row, -1);
            }
            // Stores the size of each connected component
            int[] componentSize = new int[n * m];
            int componentCount = 0;

            // Reusable BFS queue arrays to avoid repeated allocations
            int[] qX = new int[n * m];
            int[] qY = new int[n * m];

            // Iterative BFS to identify connected components of '.'
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    if (grid[i][j] == '.' && componentId[i][j] == -1) {
                        int head = 0, tail = 0;
                        qX[tail] = i;
                        qY[tail] = j;
                        tail++;
                        componentId[i][j] = componentCount;
                        componentSize[componentCount] = 0;

                        while (head < tail) {
                            int cx = qX[head];
                            int cy = qY[head];
                            head++;
                            componentSize[componentCount]++;

                            for (int k = 0; k < 4; k++) {
                                int nx = cx + DX[k];
                                int ny = cy + DY[k];
                                if (nx >= 0 && nx < n && ny >= 0 && ny < m &&
                                        grid[nx][ny] == '.' && componentId[nx][ny] == -1) {
                                    componentId[nx][ny] = componentCount;
                                    qX[tail] = nx;
                                    qY[tail] = ny;
                                    tail++;
                                }
                            }
                        }
                        componentCount++;
                    }
                }
            }

            // Tracks which components have been counted for the current '*' cell
            boolean[] visitedComponent = new boolean[componentCount];

            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    if (grid[i][j] == '*') {
                        int sum = 1; // Count the cell itself
                        for (int k = 0; k < 4; k++) {
                            int nx = i + DX[k];
                            int ny = j + DY[k];
                            if (nx >= 0 && nx < n && ny >= 0 && ny < m &&
                                    grid[nx][ny] == '.' && componentId[nx][ny] != -1) {
                                int cid = componentId[nx][ny];
                                if (!visitedComponent[cid]) {
                                    visitedComponent[cid] = true;
                                    sum += componentSize[cid];
                                }
                            }
                        }
                        grid[i][j] = (char) ('0' + (sum % 10));

                        // Reset visited flags only for the components we touched
                        for (int k = 0; k < 4; k++) {
                            int nx = i + DX[k];
                            int ny = j + DY[k];
                            if (nx >= 0 && nx < n && ny >= 0 && ny < m &&
                                    grid[nx][ny] == '.' && componentId[nx][ny] != -1) {
                                visitedComponent[componentId[nx][ny]] = false;
                            }
                        }
                    }
                }
                out.println(grid[i]);
            }
        }
    }

    static class InputReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) {
                        return null;
                    }
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            String s = next();
            if (s == null) {
                throw new RuntimeException("Unexpected end of input");
            }
            return Integer.parseInt(s);
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Deque;
import java.util.List;
import java.util.StringTokenizer;

public class Labyrinth {

    private static final int[] DR = {-1, 1, 0, 0};
    private static final int[] DC = {0, 0, -1, 1};

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner();
        String nStr = scanner.next();
        if (nStr == null) return;

        int n = Integer.parseInt(nStr);
        int m = scanner.nextInt();

        char[][] grid = new char[n][];
        for (int i = 0; i < n; i++) {
            grid[i] = scanner.next().toCharArray();
        }

        int[][] componentId = new int[n][m];
        List<Integer> componentSizes = new ArrayList<>();
        boolean[][] visited = new boolean[n][m];

        // Step 1: Find all connected components of '.'
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == '.' && !visited[i][j]) {
                    int id = componentSizes.size();
                    int size = findComponentSize(i, j, id, grid, componentId, visited, n, m);
                    componentSizes.add(size);
                }
            }
        }

        // Step 2: Generate output grid
        StringBuilder output = new StringBuilder();
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == '.') {
                    output.append('.');
                } else {
                    int mergedSize = calculateMergedSize(i, j, grid, componentId, componentSizes, n, m);
                    output.append(mergedSize % 10);
                }
            }
            output.append('\n');
        }
        System.out.print(output);
    }

    /**
     * Iteratively finds the size of the connected component containing (startR, startC).
     */
    private static int findComponentSize(int startR, int startC, int id, char[][] grid, int[][] componentId, 
                                         boolean[][] visited, int n, int m) {
        int size = 0;
        Deque<Integer> stack = new ArrayDeque<>();
        stack.push(startR * m + startC);
        visited[startR][startC] = true;

        while (!stack.isEmpty()) {
            int u = stack.pop();
            int r = u / m;
            int c = u % m;
            componentId[r][c] = id;
            size++;

            for (int k = 0; k < 4; k++) {
                int nr = r + DR[k];
                int nc = c + DC[k];
                if (nr >= 0 && nr < n && nc >= 0 && nc < m && grid[nr][nc] == '.' && !visited[nr][nc]) {
                    visited[nr][nc] = true;
                    stack.push(nr * m + nc);
                }
            }
        }
        return size;
    }

    /**
     * Calculates the total size if a '*' at (r, c) were replaced by '.',
     * including the '*' itself and sizes of all unique adjacent components.
     */
    private static int calculateMergedSize(int r, int c, char[][] grid, int[][] componentId, 
                                           List<Integer> componentSizes, int n, int m) {
        int totalSize = 1; // Count the '*' itself
        int[] seenComponents = new int[4];
        int seenCount = 0;

        for (int k = 0; k < 4; k++) {
            int nr = r + DR[k];
            int nc = c + DC[k];
            if (nr >= 0 && nr < n && nc >= 0 && nc < m && grid[nr][nc] == '.') {
                int compId = componentId[nr][nc];

                // Check if this component ID was already counted
                boolean alreadyCounted = false;
                for (int s = 0; s < seenCount; s++) {
                    if (seenComponents[s] == compId) {
                        alreadyCounted = true;
                        break;
                    }
                }

                if (!alreadyCounted) {
                    seenComponents[seenCount++] = compId;
                    totalSize += componentSizes.get(compId);
                }
            }
        }
        return totalSize;
    }

    /**
     * Fast, robust input scanner for competitive programming style inputs.
     */
    private static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            String token = next();
            return token == null ? 0 : Integer.parseInt(token);
        }
    }
}

import java.io.*;
import java.util.*;

public class CF616C {

    public static void main(String[] args) {
        // Initialize I/O streams
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;

        // Use FastScanner for efficient input reading
        FastScanner in = new FastScanner(inputStream);
        PrintWriter out = new PrintWriter(outputStream);

        // Instantiate solver and execute
        LabyrinthSolver solver = new LabyrinthSolver();
        solver.solve(in, out);

        // Ensure output is flushed and closed
        out.close();
    }

    /**
     * Solver for the Labyrinth problem (Codeforces 616C).
     * Uses BFS to identify connected components of '.' and calculates
     * the required digit for each '*' based on adjacent region sizes.
     */
    static class LabyrinthSolver {

        // Direction arrays for moving up, down, left, right
        private static final int[] DR = {-1, 1, 0, 0};
        private static final int[] DC = {0, 0, -1, 1};

        public void solve(FastScanner in, PrintWriter out) {
            int n = in.nextInt();
            int m = in.nextInt();

            // Read the grid into a mutable 2D char array
            char[][] grid = new char[n][m];
            for (int i = 0; i < n; i++) {
                String row = in.next();
                grid[i] = row.toCharArray();
            }

            // Arrays to store region information
            // regionIds[i][j] stores the ID of the region cell (i, j) belongs to
            int[][] regionIds = new int[n][m];
            // regionSizes stores the size of each region (index 0 is unused)
            List<Integer> regionSizes = new ArrayList<>();

            int currentRegionId = 0;

            // 1. Identify connected components of '.' using BFS
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    if (grid[i][j] == '.' && regionIds[i][j] == 0) {
                        currentRegionId++;
                        int size = bfsFill(grid, regionIds, n, m, i, j, currentRegionId);
                        regionSizes.add(size); // Index corresponds to region ID
                    }
                }
            }

            // 2. Process '*' cells to calculate the replacement digit
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    if (grid[i][j] == '*') {
                        int totalSize = 0;
                        Set<Integer> visitedNeighborRegions = new HashSet<>();

                        // Check all 4 neighbors
                        for (int k = 0; k < 4; k++) {
                            int ni = i + DR[k];
                            int nj = j + DC[k];

                            // Check bounds and if neighbor is part of a region
                            if (isValid(ni, nj, n, m) && grid[ni][nj] == '.') {
                                int neighborRegionId = regionIds[ni][nj];

                                // Add size only if we haven't counted this region yet for this '*'
                                if (!visitedNeighborRegions.contains(neighborRegionId)) {
                                    visitedNeighborRegions.add(neighborRegionId);
                                    totalSize += regionSizes.get(neighborRegionId);
                                }
                            }
                        }

                        // Calculate result: (sum of sizes + 1) % 10
                        int result = (totalSize + 1) % 10;
                        grid[i][j] = (char) ('0' + result);
                    }
                }
            }

            // 3. Output the modified grid
            for (int i = 0; i < n; i++) {
                out.println(grid[i]);
            }
        }

        /**
         * Performs BFS to fill a connected region of '.' cells.
         * Marks cells with the given regionId and returns the count of cells.
         */
        private int bfsFill(char[][] grid, int[][] regionIds, int n, int m, int r, int c, int regionId) {
            Queue<int[]> queue = new ArrayDeque<>();
            queue.offer(new int[]{r, c});

            regionIds[r][c] = regionId;
            int size = 0;

            while (!queue.isEmpty()) {
                int[] curr = queue.poll();
                int cr = curr[0];
                int cc = curr[1];
                size++;

                for (int k = 0; k < 4; k++) {
                    int nr = cr + DR[k];
                    int nc = cc + DC[k];

                    if (isValid(nr, nc, n, m) && grid[nr][nc] == '.' && regionIds[nr][nc] == 0) {
                        regionIds[nr][nc] = regionId;
                        queue.offer(new int[]{nr, nc});
                    }
                }
            }
            return size;
        }

        private boolean isValid(int r, int c, int n, int m) {
            return r >= 0 && r < n && c >= 0 && c < m;
        }
    }

    /**
     * FastScanner class for efficient input reading.
     */
    static class FastScanner {
        BufferedReader reader;
        StringTokenizer tokenizer;

        public FastScanner(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }

        public double nextDouble() {
            return Double.parseDouble(next());
        }
    }
}

import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.ArrayDeque;
import java.util.HashSet;
import java.util.Queue;
import java.util.StringTokenizer;

/**
 * Refactored Grid Component Calculator.
 * 
 * Improvements made:
 * 1. Readability: Renamed variables and methods to be descriptive (e.g., 'rows', 'cols', 'grid').
 * 2. Structure: Extracted logic into helper methods (BFS, Component Calculation) to reduce complexity in main.
 * 3. Performance: Replaced ArrayList with ArrayDeque for Queue operations (O(1) removal vs O(N)).
 * 4. Memory: Removed redundant 'seen' list; used 'componentIds' array for visited tracking.
 * 5. Constants: Moved magic numbers and direction vectors to constants.
 */
public class GridComponentCalculator {

    // Direction vectors for moving up, down, left, right
    private static final int[][] DIRECTIONS = {
        {0, 1}, {0, -1}, {1, 0}, {-1, 0}
    };

    public static void main(String[] args) throws Exception {
        // 1. Input Handling
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line = br.readLine();
        if (line == null) return;

        StringTokenizer st = new StringTokenizer(line);
        int rows = Integer.parseInt(st.nextToken());
        int cols = Integer.parseInt(st.nextToken());

        char[][] grid = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            String rowStr = br.readLine();
            if (rowStr != null) {
                grid[i] = rowStr.toCharArray();
            }
        }

        // 2. Identify Connected Components (Flood Fill)
        // componentIds[r][c] stores the ID of the connected component for cell (r, c)
        int[][] componentIds = new int[rows][cols];
        // componentSizes[id] stores the size of component with ID 'id'
        // Size is rows*cols + 1 to accommodate 1-based indexing
        int[] componentSizes = new int[rows * cols + 1];
        int currentComponentId = 1;

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                // If cell is empty ground and not yet visited
                if (grid[r][c] == '.' && componentIds[r][c] == 0) {
                    currentComponentId = bfs(grid, rows, cols, r, c, componentIds, componentSizes, currentComponentId);
                }
            }
        }

        // 3. Process '*' cells (Calculate connected sizes)
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '*') {
                    int totalSize = calculateConnectedSize(r, c, rows, cols, grid, componentIds, componentSizes);
                    grid[r][c] = (char) ((totalSize % 10) + '0');
                }
            }
        }

        // 4. Output
        PrintWriter out = new PrintWriter(System.out);
        for (int r = 0; r < rows; r++) {
            out.println(grid[r]);
        }
        out.flush();
    }

    /**
     * Performs Breadth-First Search to identify a connected component of '.' cells.
     * 
     * @param grid The map grid
     * @param rows Number of rows
     * @param cols Number of columns
     * @param startR Starting row
     * @param startC Starting column
     * @param componentIds Array to store component IDs for each cell
     * @param componentSizes Array to store size of each component ID
     * @param currentId The ID to assign to the current component
     * @return The next available component ID
     */
    private static int bfs(char[][] grid, int rows, int cols, int startR, int startC,
                           int[][] componentIds, int[] componentSizes, int currentId) {
        int size = 1;
        Queue<Point> queue = new ArrayDeque<>();

        Point start = new Point(startR, startC);
        queue.add(start);
        componentIds[startR][startC] = currentId;

        while (!queue.isEmpty()) {
            Point current = queue.poll();

            for (int[] d : DIRECTIONS) {
                int nextR = current.r + d[0];
                int nextC = current.c + d[1];

                // Check bounds, if it's empty ground, and if not visited
                if (isValid(nextR, nextC, rows, cols) && 
                    grid[nextR][nextC] == '.' && 
                    componentIds[nextR][nextC] == 0) {

                    componentIds[nextR][nextC] = currentId;
                    queue.add(new Point(nextR, nextC));
                    size++;
                }
            }
        }

        componentSizes[currentId] = size;
        return currentId + 1;
    }

    /**
     * Calculates the total size connected to a '*' cell, including the '*' itself.
     * Merges sizes of adjacent unique components.
     */
    private static int calculateConnectedSize(int r, int c, int rows, int cols,
                                              char[][] grid, int[][] componentIds, int[] componentSizes) {
        int totalSize = 1; // The '*' cell itself counts as 1
        HashSet<Integer> visitedComponentIds = new HashSet<>();

        for (int[] d : DIRECTIONS) {
            int nextR = r + d[0];
            int nextC = c + d[1];

            if (isValid(nextR, nextC, rows, cols) &&
                grid[nextR][nextC] == '.') {

                int id = componentIds[nextR][nextC];
                // Add size only if we haven't counted this component yet
                if (visitedComponentIds.add(id)) {
                    totalSize += componentSizes[id];
                }
            }
        }
        return totalSize;
    }

    private static boolean isValid(int r, int c, int rows, int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /**
     * Simple helper class to store coordinates.
     */
    private static class Point {
        int r, c;
        public Point(int r, int c) {
            this.r = r;
            this.c = c;
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayDeque;
import java.util.HashSet;
import java.util.Queue;
import java.util.Set;
import java.util.StringTokenizer;

/**
 * Refactored version of the original program.
 * 
 * Improvements:
 * 1. Descriptive class and variable names (e.g., 'C' -> 'ConnectedComponentSolver', 'fa' -> 'componentIds').
 * 2. Separation of concerns: Logic is broken down into 'solve', 'bfs', and 'isValid' methods.
 * 3. Better resource management: Uses try-with-resources for BufferedReader.
 * 4. Robust input parsing: Uses Integer.parseInt and handles potential nulls gracefully.
 * 5. Readability: Removed redundant casts and verbose parsing logic.
 */
public class ConnectedComponentSolver {

    // Direction vectors for moving Up, Left, Down, Right
    private static final int[][] DIRECTIONS = {{-1, 0}, {0, -1}, {1, 0}, {0, 1}};

    public static void main(String[] args) throws IOException {
        // Use try-with-resources to ensure BufferedReader is closed automatically
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(System.in))) {
            String line = reader.readLine();
            // Basic validation for empty input
            if (line == null || line.trim().isEmpty()) {
                return;
            }

            StringTokenizer tokenizer = new StringTokenizer(line);
            int rows = Integer.parseInt(tokenizer.nextToken());
            int cols = Integer.parseInt(tokenizer.nextToken());

            char[][] grid = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                String rowStr = reader.readLine();
                if (rowStr != null) {
                    // Fill the row, ensuring we don't go out of bounds if input is short
                    int length = Math.min(rowStr.length(), cols);
                    for (int j = 0; j < length; j++) {
                        grid[i][j] = rowStr.charAt(j);
                    }
                }
            }

            solve(grid, rows, cols);
        }
    }

    /**
     * Main logic to process the grid, identify components, and generate output.
     */
    private static void solve(char[][] grid, int rows, int cols) {
        // componentIds[r][c] stores the unique ID of the connected component
        // that cell (r, c) belongs to. 0 indicates unvisited or obstacle.
        int[][] componentIds = new int[rows][cols];

        // componentSizes[id] stores the total count of cells in component 'id'.
        // Using size rows * cols + 1 to accommodate 1-based IDs.
        int[] componentSizes = new int[rows * cols + 1];
        int componentCount = 0;

        // 1. Identify connected components of '.' cells using BFS
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                // If cell is open ('.') and not yet visited
                if (grid[r][c] == '.' && componentIds[r][c] == 0) {
                    componentCount++;
                    componentSizes[componentCount] = bfs(grid, componentIds, r, c, componentCount, rows, cols);
                }
            }
        }

        // 2. Generate the result grid
        char[][] resultGrid = new char[rows][cols];
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '*') {
                    // For '*' cells, calculate the sum of sizes of adjacent components
                    Set<Integer> neighborComponentIds = new HashSet<>();

                    for (int[] dir : DIRECTIONS) {
                        int nr = r + dir[0];
                        int nc = c + dir[1];

                        if (isValid(nr, nc, rows, cols)) {
                            int id = componentIds[nr][nc];
                            // If neighbor is part of a valid component (ID > 0)
                            if (id > 0) {
                                neighborComponentIds.add(id);
                            }
                        }
                    }

                    int count = 1; // Base count as per original logic
                    for (int id : neighborComponentIds) {
                        count += componentSizes[id];
                    }

                    resultGrid[r][c] = (char) ('0' + (count % 10));
                } else {
                    // '.' cells remain '.' in the output
                    resultGrid[r][c] = '.';
                }
            }
        }

        // 3. Print the result
        for (char[] row : resultGrid) {
            System.out.println(new String(row));
        }
    }

    /**
     * Performs Breadth-First Search to find the size of the connected component
     * starting at (startR, startC) and assigns the given ID to all cells in it.
     */
    private static int bfs(char[][] grid, int[][] componentIds, int startR, int startC, int id, int rows, int cols) {
        int count = 0;
        Queue<int[]> queue = new ArrayDeque<>();

        // Mark start cell as visited and add to queue
        componentIds[startR][startC] = id;
        count++;
        queue.add(new int[]{startR, startC});

        while (!queue.isEmpty()) {
            int[] current = queue.poll();
            int r = current[0];
            int c = current[1];

            for (int[] dir : DIRECTIONS) {
                int nr = r + dir[0];
                int nc = c + dir[1];

                if (isValid(nr, nc, rows, cols)) {
                    // If neighbor is open ('.') and not yet visited
                    if (grid[nr][nc] == '.' && componentIds[nr][nc] == 0) {
                        componentIds[nr][nc] = id;
                        count++;
                        queue.add(new int[]{nr, nc});
                    }
                }
            }
        }
        return count;
    }

    /**
     * Checks if the given coordinates are within the grid boundaries.
     */
    private static boolean isValid(int r, int c, int rows, int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.Arrays;
import java.util.HashSet;
import java.util.Set;

public class Solution {
    // Directions for moving in the grid: Up, Right, Down, Left
    private static final int[][] DIRECTIONS = {
        {-1, 0}, {0, 1}, {1, 0}, {0, -1}
    };

    private static final int UNVISITED = -1;
    private static final int BASE_SUM_VALUE = 1;

    public static void main(String[] args) throws IOException {
        // Use BufferedReader for fast I/O
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter out = new PrintWriter(System.out);

        try {
            String line = reader.readLine();
            if (line == null || line.trim().isEmpty()) {
                return;
            }

            // Parse dimensions N and M
            // Using \\s+ to handle multiple spaces if present
            String[] dimensions = line.trim().split("\\s+");
            int n = Integer.parseInt(dimensions[0]);
            int m = Integer.parseInt(dimensions[1]);

            char[][] grid = new char[n][m];
            for (int i = 0; i < n; i++) {
                String rowStr = reader.readLine();
                if (rowStr != null) {
                    grid[i] = rowStr.toCharArray();
                }
            }

            // Execute the core logic
            solve(grid, n, m, out);

        } finally {
            // Ensure resources are closed and output is flushed
            out.flush();
            out.close();
            reader.close();
        }
    }

    private static void solve(char[][] grid, int rows, int cols, PrintWriter out) {
        // Step 1: Identify connected components of '.'
        // componentIds[r][c] stores the ID of the component the cell belongs to
        int[][] componentIds = new int[rows][cols];
        for (int[] row : componentIds) {
            Arrays.fill(row, UNVISITED);
        }

        // componentSizes[id] stores the total number of cells in component with 'id'
        int[] componentSizes = new int[rows * cols];
        int nextComponentId = 0;

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                // If cell is empty and not yet visited, start a new component search
                if (grid[r][c] == '.' && componentIds[r][c] == UNVISITED) {
                    performFloodFill(grid, componentIds, componentSizes, r, c, nextComponentId);
                    nextComponentId++;
                }
            }
        }

        // Step 2: Calculate values for walls ('*')
        char[][] resultGrid = new char[rows][cols];

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '.') {
                    resultGrid[r][c] = '.';
                } else {
                    // It's a wall ('*'), calculate the value based on adjacent components
                    int sum = BASE_SUM_VALUE;
                    Set<Integer> adjacentComponentIds = new HashSet<>();

                    for (int[] dir : DIRECTIONS) {
                        int nr = r + dir[0];
                        int nc = c + dir[1];

                        if (isValid(nr, nc, rows, cols) && grid[nr][nc] == '.') {
                            adjacentComponentIds.add(componentIds[nr][nc]);
                        }
                    }

                    for (int id : adjacentComponentIds) {
                        sum += componentSizes[id];
                    }

                    resultGrid[r][c] = (char) ((sum % 10) + '0');
                }
            }
        }

        // Step 3: Output the result
        for (int r = 0; r < rows; r++) {
            out.println(new String(resultGrid[r]));
        }
    }

    /**
     * Performs a Depth First Search (DFS) to find all connected '.' cells
     * and assigns them to the current component ID.
     */
    private static void performFloodFill(char[][] grid, int[][] componentIds, int[] componentSizes, 
                                         int r, int c, int id) {
        // Check bounds
        if (!isValid(r, c, grid)) return;

        // Check if cell is a wall or already visited
        if (grid[r][c] == '*' || componentIds[r][c] != UNVISITED) return;

        // Mark as visited and increment size
        componentIds[r][c] = id;
        componentSizes[id]++;

        // Recurse in all 4 directions
        for (int[] dir : DIRECTIONS) {
            performFloodFill(grid, componentIds, componentSizes, r + dir[0], c + dir[1], id);
        }
    }

    /**
     * Checks if the given coordinates are within the grid boundaries.
     */
    private static boolean isValid(int r, int c, char[][] grid) {
        return r >= 0 && r < grid.length && c >= 0 && c < grid[0].length;
    }

    /**
     * Overloaded isValid for use in solve method where dimensions are known explicitly.
     */
    private static boolean isValid(int r, int c, int rows, int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }
}

import java.io.*;
import java.util.*;

/**
 * Refactored Grid Component Analyzer.
 * Processes a grid to identify connected components and calculates replacement values.
 */
public class GridProcessor {

    private int rows;
    private int cols;
    private char[][] grid;
    private int[][] componentIds;
    private List<Integer> componentSizes;

    // Directions: Right, Left, Down, Up
    private static final int[] DR = {0, 0, 1, -1};
    private static final int[] DC = {1, -1, 0, 0};

    public static void main(String[] args) {
        // Use BufferedReader for fast input
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        // Use PrintWriter for fast output
        PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out));

        try {
            GridProcessor processor = new GridProcessor();
            processor.init(br);
            processor.process();
            processor.print(out);
        } catch (IOException e) {
            System.err.println("Error reading input: " + e.getMessage());
        } finally {
            out.flush();
            out.close();
        }
    }

    /**
     * Reads the grid dimensions and content from the input stream.
     */
    private void init(BufferedReader br) throws IOException {
        String line = br.readLine();
        if (line == null) return;

        // Robust parsing for N and M (handles spaces)
        String[] parts = line.trim().split("\\s+");
        this.rows = Integer.parseInt(parts[0]);
        this.cols = Integer.parseInt(parts[1]);

        this.grid = new char[rows][cols];
        this.componentIds = new int[rows][cols];
        this.componentSizes = new ArrayList<>();
        this.componentSizes.add(0); // Index 0 is unused (represents no component)

        for (int i = 0; i < rows; i++) {
            String rowStr = br.readLine();
            if (rowStr != null) {
                // Ensure we don't read past the string length if input is malformed
                int limit = Math.min(rowStr.length(), cols);
                for (int j = 0; j < limit; j++) {
                    grid[i][j] = rowStr.charAt(j);
                }
            }
        }
    }

    /**
     * Main processing logic: Identifies components and calculates replacements.
     */
    private void process() {
        int currentComponentId = 0;

        // 1. Identify connected components using BFS
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '.' && componentIds[r][c] == 0) {
                    currentComponentId++;
                    int size = bfs(r, c, currentComponentId);
                    componentSizes.add(size);
                }
            }
        }

        // 2. Calculate replacement values for '#' cells
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '#') {
                    int sum = 1; // The '#' cell itself contributes 1
                    Set<Integer> visitedNeighbors = new HashSet<>();

                    // Check 4 neighbors
                    for (int k = 0; k < 4; k++) {
                        int nr = r + DR[k];
                        int nc = c + DC[k];

                        if (isValid(nr, nc) && grid[nr][nc] == '.') {
                            int id = componentIds[nr][nc];
                            // Add size only if this neighbor component ID hasn't been counted yet
                            if (!visitedNeighbors.contains(id)) {
                                visitedNeighbors.add(id);
                                sum += componentSizes.get(id);
                            }
                        }
                    }
                    // Apply modulo and store result
                    grid[r][c] = (char) ('0' + (sum % 10));
                }
            }
        }
    }

    /**
     * Iterative BFS to find component size and label cells.
     * Safer than recursion for large grids.
     */
    private int bfs(int startR, int startC, int id) {
        int size = 0;
        Queue<int[]> queue = new ArrayDeque<>();

        queue.offer(new int[]{startR, startC});
        componentIds[startR][startC] = id;
        size++;

        while (!queue.isEmpty()) {
            int[] curr = queue.poll();
            int r = curr[0];
            int c = curr[1];

            for (int k = 0; k < 4; k++) {
                int nr = r + DR[k];
                int nc = c + DC[k];

                if (isValid(nr, nc) && grid[nr][nc] == '.' && componentIds[nr][nc] == 0) {
                    componentIds[nr][nc] = id;
                    size++;
                    queue.offer(new int[]{nr, nc});
                }
            }
        }
        return size;
    }

    /**
     * Checks if coordinates are within grid bounds.
     */
    private boolean isValid(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /**
     * Prints the processed grid to the output stream.
     */
    private void print(PrintWriter out) {
        for (int i = 0; i < rows; i++) {
            out.println(grid[i]);
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Deque;
import java.util.List;
import java.util.StringTokenizer;

public class Main {
    private static final int MOD = 10;
    // Direction vectors for 4-connected neighbors (up, down, left, right)
    private static final int[] DR = {-1, 1, 0, 0};
    private static final int[] DC = {0, 0, -1, 1};

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter out = new PrintWriter(System.out);

        // Robust token reading to handle arbitrary whitespace/newlines
        StringTokenizer st = new StringTokenizer("");

        // Read grid dimensions
        while (!st.hasMoreTokens()) {
            String line = br.readLine();
            if (line == null) return;
            st = new StringTokenizer(line);
        }
        int rows = Integer.parseInt(st.nextToken());
        int cols = Integer.parseInt(st.nextToken());

        // Read grid content
        char[][] grid = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            while (!st.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) break;
                st = new StringTokenizer(line);
            }
            grid[i] = st.nextToken().toCharArray();
        }

        // Identify connected components of '.' cells
        int[][] componentId = new int[rows][cols];
        boolean[][] visited = new boolean[rows][cols];
        List<Integer> componentSizes = new ArrayList<>();

        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == '.' && !visited[i][j]) {
                    int size = findComponentSize(grid, visited, componentId, i, j, componentSizes.size());
                    componentSizes.add(size);
                }
            }
        }

        // Calculate values for '*' cells based on adjacent component sizes
        int[][] resultGrid = new int[rows][cols];
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == '*') {
                    int sum = 0;
                    for (int k = 0; k < 4; k++) {
                        int ni = i + DR[k];
                        int nj = j + DC[k];
                        if (ni >= 0 && ni < rows && nj >= 0 && nj < cols && grid[ni][nj] == '.') {
                            sum = (sum + componentSizes.get(componentId[ni][nj])) % MOD;
                        }
                    }
                    resultGrid[i][j] = (sum + 1) % MOD;
                }
            }
        }

        // Output the resulting grid
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                out.print(grid[i][j] == '*' ? resultGrid[i][j] : '.');
            }
            out.println();
        }

        out.flush();
        out.close();
    }

    /**
     * Iteratively finds the size of a connected component of '.' cells.
     * Uses an explicit stack to avoid potential StackOverflowError on large grids.
     */
    private static int findComponentSize(char[][] grid, boolean[][] visited, int[][] componentId,
                                         int startR, int startC, int id) {
        int size = 0;
        Deque<int[]> stack = new ArrayDeque<>();
        stack.push(new int[]{startR, startC});

        while (!stack.isEmpty()) {
            int[] curr = stack.pop();
            int r = curr[0];
            int c = curr[1];

            if (visited[r][c]) continue;

            visited[r][c] = true;
            componentId[r][c] = id;
            size++;

            for (int k = 0; k < 4; k++) {
                int nr = r + DR[k];
                int nc = c + DC[k];
                if (nr >= 0 && nr < grid.length && nc >= 0 && nc < grid[0].length &&
                        !visited[nr][nc] && grid[nr][nc] == '.') {
                    stack.push(new int[]{nr, nc});
                }
            }
        }
        return size;
    }
}

import java.io.BufferedReader;
import java.io.BufferedOutputStream;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.ArrayDeque;
import java.util.Arrays;
import java.util.Deque;
import java.util.StringTokenizer;

/**
 * Analyzes a grid to identify connected components of '.' characters,
 * then calculates the combined size of adjacent components for each '*' character.
 */
public class GridComponentAnalyzer {

    private static final int[] DX = {-1, 0, 1, 0};
    private static final int[] DY = {0, -1, 0, 1};
    private static final int MODULO = 10;

    private int rows;
    private int cols;
    private char[][] grid;
    private int[][] componentIds;
    private int[] componentSizes;
    private int componentCount;

    /**
     * Processes the input grid and writes the result to the output.
     */
    public void process(BufferedReader reader, PrintWriter writer) throws IOException {
        // Read dimensions
        String line = readNonEmptyLine(reader);
        if (line == null) return;

        StringTokenizer st = new StringTokenizer(line);
        rows = Integer.parseInt(st.nextToken());
        cols = Integer.parseInt(st.nextToken());

        // Read grid
        grid = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            String rowLine = readNonEmptyLine(reader);
            if (rowLine != null) {
                grid[i] = rowLine.trim().toCharArray();
            }
        }

        // Initialize component tracking arrays
        componentIds = new int[rows][cols];
        for (int[] row : componentIds) {
            Arrays.fill(row, -1);
        }
        componentSizes = new int[rows * cols];
        componentCount = 0;

        // Identify connected components using iterative DFS
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == '.' && componentIds[i][j] == -1) {
                    componentSizes[componentCount] = 0;
                    findConnectedComponent(i, j);
                    componentCount++;
                }
            }
        }

        // Generate output grid
        for (int i = 0; i < rows; i++) {
            StringBuilder sb = new StringBuilder(cols);
            for (int j = 0; j < coords; j++) {
                if (grid[i][j] == '*') {
                    int totalSize = 1;
                    int[] seenComponentIds = new int[4];
                    int seenCount = 0;

                    for (int d = 0; d < 4; d++) {
                        int ni = i + DY[d];
                        int nj = j + DX[d];

                        if (ni >= 0 && ni < rows && nj >= 0 && nj < cols) {
                            int cid = componentIds[ni][nj];
                            if (cid != -1) {
                                boolean alreadySeen = false;
                                for (int k = 0; k < seenCount; k++) {
                                    if (seenComponentIds[k] == cid) {
                                        alreadySeen = true;
                                        break;
                                    }
                                }
                                if (!alreadySeen) {
                                    totalSize += componentSizes[cid];
                                    seenComponentIds[seenCount++] = cid;
                                }
                            }
                        }
                    }
                    sb.append(totalSize % MODULO);
                } else {
                    sb.append('.');
                }
            }
            writer.println(sb);
        }
    }

    /**
     * Iteratively finds all cells in the connected component starting at (startY, startX).
     * Marks them with the current component ID and updates the component size.
     */
    private void findConnectedComponent(int startY, int startX) {
        Deque<int[]> stack = new ArrayDeque<>();
        stack.push(new int[]{startY, startX});
        componentIds[startY][startX] = componentCount;
        componentSizes[componentCount]++;

        while (!stack.isEmpty()) {
            int[] current = stack.pop();
            int y = current[0];
            int x = current[1];

            for (int d = 0; d < 4; d++) {
                int ny = y + DY[d];
                int nx = x + DX[d];

                if (ny >= 0 && ny < rows && nx >= 0 && nx < cols &&
                    grid[ny][nx] == '.' && componentIds[ny][nx] == -1) {
                    componentIds[ny][nx] = componentCount;
                    componentSizes[componentCount]++;
                    stack.push(new int[]{ny, nx});
                }
            }
        }
    }

    /**
     * Helper to read the next non-empty line from the reader.
     */
    private String readNonEmptyLine(BufferedReader reader) throws IOException {
        String line = reader.readLine();
        while (line != null && line.trim().isEmpty()) {
            line = reader.readLine();
        }
        return line;
    }

    public static void main(String[] args) {
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
             PrintWriter writer = new PrintWriter(new BufferedOutputStream(System.out))) {
            new GridComponentAnalyzer().process(reader, writer);
            writer.flush();
        } catch (IOException e) {
            System.err.println("I/O error occurred: " + e.getMessage());
        }
    }
}

import java.io.*;
import java.util.*;

public class Main {

    public static void main(String[] args) throws IOException {
        FastScanner scanner = new FastScanner(System.in);
        int n = scanner.nextInt();
        int m = scanner.nextInt();

        char[][] grid = new char[n][];
        for (int i = 0; i < n; i++) {
            grid[i] = scanner.next().toCharArray();
        }

        GridProcessor processor = new GridProcessor(grid);
        processor.labelComponents();
        char[] result = processor.calculateResults();

        for (int i = 0; i < n; i++) {
            System.out.println(new String(result, i * m, m));
        }
    }

    /**
     * Encapsulates grid analysis logic. Responsible for component labeling
     * and calculating adjacent component size sums.
     */
    private static class GridProcessor {
        private final char[][] grid;
        private final int[][] componentIds;
        private final int[] componentSizes;
        private final int rows;
        private final int cols;
        private int componentCount = 0;

        private static final int[][] DIRECTIONS = {
            {-1, 0}, {1, 0}, {0, -1}, {0, 1}
        };

        public GridProcessor(char[][] grid) {
            this.grid = grid;
            this.rows = grid.length;
            this.cols = grid[0].length;
            this.componentIds = new int[rows][cols];
            // Maximum possible components equals total cells (checkerboard pattern)
            this.componentSizes = new int[rows * cols + 1];
        }

        /**
         * Traverses the grid and assigns unique IDs to each connected '.' component.
         */
        public void labelComponents() {
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j] == '.' && componentIds[i][j] == 0) {
                        componentCount++;
                        fillComponent(i, j, componentCount);
                    }
                }
            }
        }

        /**
         * Iteratively fills a component using DFS.
         */
        private void fillComponent(int startRow, int startCol, int id) {
            Deque<int[]> stack = new ArrayDeque<>();
            stack.push(new int[]{startRow, startCol});
            componentIds[startRow][startCol] = id;
            componentSizes[id]++;

            while (!stack.isEmpty()) {
                int[] current = stack.pop();
                int r = current[0];
                int c = current[1];

                for (int[] dir : DIRECTIONS) {
                    int nr = r + dir[0];
                    int nc = c + dir[1];

                    if (isValid(nr, nc) && grid[nr][nc] == '.' && componentIds[nr][nc] == 0) {
                        componentIds[nr][nc] = id;
                        componentSizes[id]++;
                        stack.push(new int[]{nr, nc});
                    }
                }
            }
        }

        private boolean isValid(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }

        /**
         * Computes the replacement character for each non-'.' cell.
         * The value is (1 + sum of adjacent component sizes) % 10.
         */
        public char[] calculateResults() {
            char[] result = new char[rows * cols];
            int idx = 0;
            Set<Integer> adjacentIds = new HashSet<>();

            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j] == '.') {
                        result[idx++] = '.';
                    } else {
                        adjacentIds.clear();
                        int sum = 1; // Base count for the cell itself
                        for (int[] dir : DIRECTIONS) {
                            int nr = i + dir[0];
                            int nc = j + dir[1];
                            if (isValid(nr, nc)) {
                                int id = componentIds[nr][nc];
                                if (id != 0 && !adjacentIds.contains(id)) {
                                    adjacentIds.add(id);
                                    sum += componentSizes[id];
                                }
                            }
                        }
                        result[idx++] = (char) ('0' + (sum % 10));
                    }
                }
            }
            return result;
        }
    }

    /**
     * Lightweight fast I/O scanner for competitive programming style inputs.
     */
    private static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        public String next() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) return null;
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

        public int nextInt() throws IOException {
            String s = next();
            if (s == null) throw new IOException("Unexpected end of input");
            return Integer.parseInt(s);
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Solves the labyrinth problem by connecting adjacent '.' cells using a 
 * Disjoint Set Union (DSU) structure, then replacing each '*' with the 
 * modulo-10 sum of the sizes of adjacent connected components plus one.
 * 
 * Refactoring improvements:
 * - Removed static state; solver is now instance-based for testability and reusability.
 * - Applied descriptive naming conventions and consistent formatting.
 * - Separated concerns: input parsing, graph construction, result computation, and output.
 * - Optimized neighbor processing using a HashSet to track unique component roots.
 * - Improved I/O classes with proper exception handling and resource management.
 * - Encapsulated DSU internals and exposed only necessary public methods.
 */
public class TheLabyrinth {

    private final int rows;
    private final int cols;
    private final char[][] grid;

    public TheLabyrinth(int rows, int cols, char[][] grid) {
        this.rows = rows;
        this.cols = cols;
        this.grid = grid;
    }

    /**
     * Executes the full solving pipeline: builds the union-find structure,
     * computes the result grid, and returns it.
     */
    public char[][] solve() {
        UnionFind uf = new UnionFind(rows * cols);
        buildUnionFind(uf);
        return computeResultGrid(uf);
    }

    private void buildUnionFind(UnionFind uf) {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '.') {
                    int u = to1D(r, c);
                    for (int v : getNeighbors(r, c)) {
                        uf.union(u, v);
                    }
                }
            }
        }
    }

    private int to1D(int r, int c) {
        return r * cols + c;
    }

    private boolean isValid(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols && grid[r][c] != '*';
    }

    private List<Integer> getNeighbors(int r, int c) {
        List<Integer> neighbors = new ArrayList<>();
        int[] dr = {-1, 1, 0, 0};
        int[] dc = {0, 0, -1, 1};
        for (int i = 0; i < 4; i++) {
            int nr = r + dr[i];
            int nc = c + dc[i];
            if (isValid(nr, nc)) {
                neighbors.add(to1D(nr, nc));
            }
        }
        return neighbors;
    }

    private char[][] computeResultGrid(UnionFind uf) {
        char[][] result = new char[rows][cols];
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '.') {
                    result[r][c] = '.';
                } else {
                    int totalSize = 1; // Count the '*' cell itself
                    Set<Integer> visitedRoots = new HashSet<>();
                    for (int neighborIdx : getNeighbors(r, c)) {
                        int root = uf.find(neighborIdx);
                        if (!visitedRoots.contains(root)) {
                            visitedRoots.add(root);
                            totalSize += uf.size(neighborIdx);
                        }
                    }
                    result[r][c] = (char) ('0' + (totalSize % 10));
                }
            }
        }
        return result;
    }

    /**
     * Weighted Quick Union with Path Halving for efficient component tracking.
     */
    private static class UnionFind {
        private final int[] parent;
        private final int[] size;
        private int components;

        public UnionFind(int n) {
            parent = new int[n];
            size = new int[n];
            components = n;
            for (int i = 0; i < n; i++) {
                parent[i] = i;
                size[i] = 1;
            }
        }

        public int find(int p) {
            while (p != parent[p]) {
                parent[p] = parent[parent[p]]; // Path halving
                p = parent[p];
            }
            return p;
        }

        public boolean connected(int p, int q) {
            return find(p) == find(q);
        }

        public void union(int p, int q) {
            int rootP = find(p);
            int rootQ = find(q);
            if (rootP == rootQ) return;

            if (size[rootP] < size[rootQ]) {
                parent[rootP] = rootQ;
                size[rootQ] += size[rootP];
            } else {
                parent[rootQ] = rootP;
                size[rootP] += size[rootQ];
            }
            components--;
        }

        public int size(int p) {
            return size[find(p)];
        }

        public int count() {
            return components;
        }
    }

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner(System.in);
        FastWriter writer = new FastWriter(System.out);
        try {
            int rows = scanner.nextInt();
            int cols = scanner.nextInt();
            char[][] grid = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                grid[i] = scanner.next().toCharArray();
            }
            TheLabyrinth solver = new TheLabyrinth(rows, cols, grid);
            char[][] result = solver.solve();
            for (char[] row : result) {
                writer.println(row);
            }
        } finally {
            scanner.close();
            writer.close();
        }
    }

    /**
     * High-performance input scanner for competitive programming and batch processing.
     */
    static class FastScanner {
        private final BufferedReader reader;
        private StringTokenizer st;

        public FastScanner(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
            st = null;
        }

        public String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input", e);
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            String token = next();
            return token == null ? 0 : Integer.parseInt(token);
        }

        public long nextLong() {
            String token = next();
            return token == null ? 0L : Long.parseLong(token);
        }

        public double nextDouble() {
            String token = next();
            return token == null ? 0.0 : Double.parseDouble(token);
        }

        public void close() {
            try {
                reader.close();
            } catch (IOException e) {
                throw new RuntimeException("Failed to close scanner", e);
            }
        }
    }

    /**
     * High-performance output writer for competitive programming and batch processing.
     */
    static class FastWriter {
        private final BufferedWriter writer;

        public FastWriter(OutputStream stream) {
            writer = new BufferedWriter(new OutputStreamWriter(stream));
        }

        public void print(int i) {
            print(Integer.toString(i));
        }

        public void println(int i) {
            print(i);
            println();
        }

        public void print(long i) {
            print(Long.toString(i));
        }

        public void println(long i) {
            print(i);
            println();
        }

        public void print(double i) {
            print(Double.toString(i));
        }

        public void print(boolean i) {
            print(Boolean.toString(i));
        }

        public void print(char i) {
            try {
                writer.write(i);
            } catch (IOException e) {
                throw new RuntimeException("Failed to write output", e);
            }
        }

        public void print(String s) {
            try {
                writer.write(s);
            } catch (IOException e) {
                throw new RuntimeException("Failed to write output", e);
            }
        }

        public void println(String s) {
            print(s);
            println();
        }

        public void println() {
            try {
                writer.write('\n');
            } catch (IOException e) {
                throw new RuntimeException("Failed to write output", e);
            }
        }

        public void println(char[] chars) {
            try {
                writer.write(chars);
                writer.write('\n');
            } catch (IOException e) {
                throw new RuntimeException("Failed to write output", e);
            }
        }

        public void print(int[] arr) {
            for (int i = 0; i < arr.length; i++) {
                print(arr[i]);
                print(' ');
            }
        }

        public void close() {
            try {
                writer.close();
            } catch (IOException e) {
                throw new RuntimeException("Failed to close writer", e);
            }
        }
    }
}

import java.io.PrintWriter;
import java.util.ArrayDeque;
import java.util.Deque;
import java.util.HashSet;
import java.util.Scanner;
import java.util.Set;

public class Edu5C {
    // Centralized direction vectors to avoid magic numbers and duplicated boundary checks
    private static final int[][] DIRECTIONS = {
        {-1, 0}, {1, 0}, {0, -1}, {0, 1}
    };

    public static void main(String[] args) {
        // Try-with-resources ensures proper cleanup of I/O streams
        try (Scanner sc = new Scanner(System.in);
             PrintWriter out = new PrintWriter(System.out)) {

            if (!sc.hasNextInt()) return;
            int n = sc.nextInt();
            int m = sc.nextInt();
            sc.nextLine(); // Consume the newline character after m

            char[][] grid = new char[n][m];
            for (int i = 0; i < n; i++) {
                // Use trim() to safely handle potential trailing whitespace
                grid[i] = sc.nextLine().trim().toCharArray();
            }

            // Early exit for invalid dimensions
            if (n <= 0 || m <= 0) return;

            // Data structures for component tracking
            // 0 indicates an unvisited/unassigned cell
            int[][] componentId = new int[n][m];
            // Stores the size of each connected component. Index = componentId.
            int[] componentSizes = new int[n * m + 1];
            int currentComponentId = 0;

            // 1. Identify connected components of '.' and count their sizes
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    if (grid[i][j] == '.' && componentId[i][j] == 0) {
                        currentComponentId++;
                        int size = 0;

                        // Iterative DFS to prevent StackOverflowError on large grids
                        Deque<int[]> stack = new ArrayDeque<>();
                        stack.push(new int[]{i, j});
                        componentId[i][j] = currentComponentId;

                        while (!stack.isEmpty()) {
                            int[] curr = stack.pop();
                            size++;

                            for (int[] dir : DIRECTIONS) {
                                int ni = curr[0] + dir[0];
                                int nj = curr[1] + dir[1];

                                if (isInBounds(ni, nj, n, m) &&
                                    grid[ni][nj] == '.' &&
                                    componentId[ni][nj] == 0) {
                                    componentId[ni][nj] = currentComponentId;
                                    stack.push(new int[]{ni, nj});
                                }
                            }
                        }
                        componentSizes[currentComponentId] = size;
                    }
                }
            }

            // 2. Calculate results for each '*' cell
            int[][] res = new int[n][m];
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    if (grid[i][j] == '*') {
                        int total = 1;
                        Set<Integer> seenComponents = new HashSet<>();

                        for (int[] dir : DIRECTIONS) {
                            int ni = i + dir[0];
                            int nj = j + dir[1];

                            if (isInBounds(ni, nj, n, m) && grid[ni][nj] == '.') {
                                int compId = componentId[ni][nj];
                                // HashSet.add() returns false if element already exists
                                if (seenComponents.add(compId)) {
                                    total += componentSizes[compId];
                                }
                            }
                        }
                        res[i][j] = total;
                    }
                }
            }

            // 3. Output results
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    if (res[i][j] > 0) {
                        out.print(res[i][j] % 10);
                    } else {
                        out.print('.');
                    }
                }
                out.println();
            }
            out.flush();
        }
    }

    /**
     * Checks if coordinates are within grid boundaries.
     */
    private static boolean isInBounds(int r, int c, int n, int m) {
        return r >= 0 && r < n && c >= 0 && c < m;
    }
}

import java.io.*;
import java.util.*;

public class GridComponentSolver {
    // Direction vectors for moving up, down, left, right
    private static final int[] DR = {-1, 1, 0, 0};
    private static final int[] DC = {0, 0, -1, 1};
    private static final int MOD = 10;

    public static void main(String[] args) {
        new GridComponentSolver().run();
    }

    /**
     * Orchestrates reading input, computing component sizes, 
     * and printing the final result grid.
     */
    public void run() {
        Kattio in = new Kattio(System.in);

        int rows = in.nextInt();
        int cols = in.nextInt();

        char[][] grid = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            grid[i] = in.next().toCharArray();
        }

        // Maps each '.' cell to a unique component ID. 0 means unvisited.
        int[][] componentIds = new int[rows][cols];
        List<Integer> componentSizes = new ArrayList<>();
        componentSizes.add(0); // Index 0 is unused; component IDs start at 1

        // Identify connected components of '.' cells
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '.' && componentIds[r][c] == 0) {
                    int size = traverseConnectedComponent(grid, componentIds, r, c, componentSizes.size());
                    componentSizes.add(size);
                }
            }
        }

        // Calculate and print the result grid
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '.') {
                    in.print('.');
                } else {
                    int totalSize = 1;
                    Set<Integer> neighborComponents = new HashSet<>();

                    // Check all 4 adjacent cells
                    for (int k = 0; k < 4; k++) {
                        int nr = r + DR[k];
                        int nc = c + DC[k];
                        if (nr >= 0 && nr < rows && nc >= 0 && nc < cols && grid[nr][nc] == '.') {
                            neighborComponents.add(componentIds[nr][nc]);
                        }
                    }

                    // Sum sizes of unique adjacent components
                    for (int compId : neighborComponents) {
                        totalSize += componentSizes.get(compId);
                    }

                    in.print(totalSize % MOD);
                }
            }
            in.println();
        }

        in.flush();
        in.close();
    }

    /**
     * Traverses a connected component of '.' cells using iterative DFS.
     * Marks visited cells with the given component ID and returns the component size.
     */
    private int traverseConnectedComponent(char[][] grid, int[][] componentIds, int startR, int startC, int compId) {
        Deque<int[]> stack = new ArrayDeque<>();
        stack.push(new int[]{startR, startC});
        componentIds[startR][startC] = compId;
        int size = 0;

        while (!stack.isEmpty()) {
            int[] curr = stack.pop();
            size++;
            int r = curr[0];
            int c = curr[1];

            for (int k = 0; k < 4; k++) {
                int nr = r + DR[k];
                int nc = c + DC[k];
                if (nr >= 0 && nr < grid.length && nc >= 0 && nc < grid[0].length &&
                    grid[nr][nc] == '.' && componentIds[nr][nc] == 0) {
                    componentIds[nr][nc] = compId;
                    stack.push(new int[]{nr, nc});
                }
            }
        }
        return size;
    }

    /**
     * Fast I/O utility class for competitive programming.
     */
    private static class Kattio extends PrintWriter {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;
        private String token;

        public Kattio(InputStream in) {
            super(new BufferedOutputStream(System.out));
            this.reader = new BufferedReader(new InputStreamReader(in));
        }

        public int nextInt() {
            return Integer.parseInt(nextToken());
        }

        public long nextLong() {
            return Long.parseLong(nextToken());
        }

        public double nextDouble() {
            return Double.parseDouble(nextToken());
        }

        public String next() {
            return nextToken();
        }

        public String nextLine() {
            token = null;
            try {
                return reader.readLine();
            } catch (IOException e) {
                return null;
            }
        }

        private String peekToken() {
            if (token == null) {
                try {
                    while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                        String line = reader.readLine();
                        if (line == null) return null;
                        tokenizer = new StringTokenizer(line);
                    }
                    token = tokenizer.nextToken();
                } catch (IOException e) {
                    return null;
                }
            }
            return token;
        }

        private String nextToken() {
            String ans = peekToken();
            token = null;
            return ans;
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

/**
 * Solves Codeforces Problem 616C: The Labyrinth.
 * Finds connected components of '.' cells and calculates the size of the 
 * component a '*' would join if replaced by '.'.
 */
public class Problem_616_C {

    public static void main(String[] args) {
        FastScanner in = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out);
        new Problem_616_C().solve(in, out);
        out.close();
    }

    /**
     * Core solver logic.
     */
    public void solve(FastScanner in, PrintWriter out) {
        int n = in.nextInt();
        int m = in.nextInt();

        char[][] lab = new char[n][];
        for (int i = 0; i < n; i++) {
            lab[i] = in.next().toCharArray();
        }

        // Initialize DSU for n*m cells
        UnionFind uf = new UnionFind(n * m);

        // Build connected components for '.' cells
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (lab[i][j] == '.') {
                    int idx = i * m + j;
                    if (i > 0 && lab[i - 1][j] == '.') {
                        uf.union(idx, idx - m);
                    }
                    if (j > 0 && lab[i][j - 1] == '.') {
                        uf.union(idx, idx - 1);
                    }
                }
            }
        }

        // Calculate and print the result grid
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (lab[i][j] == '*') {
                    int size = 1; // Count the cell itself
                    int[] roots = new int[4];
                    int rootCount = 0;

                    int[] di = {-1, 1, 0, 0};
                    int[] dj = {0, 0, -1, 1};

                    // Check 4 adjacent cells
                    for (int k = 0; k < 4; k++) {
                        int ni = i + di[k];
                        int nj = j + dj[k];
                        if (ni >= 0 && ni < n && nj >= 0 && nj < m && lab[ni][nj] == '.') {
                            int root = uf.find(ni * m + nj);

                            // Avoid double-counting cells that belong to the same component
                            boolean seen = false;
                            for (int r = 0; r < rootCount; r++) {
                                if (roots[r] == root) {
                                    seen = true;
                                    break;
                                }
                            }

                            if (!seen) {
                                roots[rootCount++] = root;
                                size += uf.getSize(root);
                            }
                        }
                    }
                    out.print((char) (size % 10 + '0'));
                } else {
                    out.print(lab[i][j]);
                }
            }
            out.println();
        }
    }

    /**
     * Disjoint Set Union (DSU) / Union-Find data structure.
     * Uses path compression and union-by-size for near-constant time operations.
     */
    private static class UnionFind {
        private final int[] parent;
        private final int[] size;

        UnionFind(int n) {
            parent = new int[n];
            size = new int[n];
            for (int i = 0; i < n; i++) {
                parent[i] = i;
                size[i] = 1;
            }
        }

        /**
         * Finds the representative root of the set containing x with path compression.
         * Iterative implementation prevents StackOverflowError on large inputs.
         */
        int find(int x) {
            int root = x;
            while (root != parent[root]) {
                root = parent[root];
            }
            // Path compression
            while (x != root) {
                int next = parent[x];
                parent[x] = root;
                x = next;
            }
            return root;
        }

        /**
         * Unites the sets containing a and b using union-by-size.
         */
        void union(int a, int b) {
            int rootA = find(a);
            int rootB = find(b);
            if (rootA == rootB) return;

            // Attach smaller tree to larger tree
            if (size[rootA] < size[rootB]) {
                int temp = rootA;
                rootA = rootB;
                rootB = temp;
            }
            parent[rootB] = rootA;
            size[rootA] += size[rootB];
        }

        /**
         * Returns the size of the component containing x.
         */
        int getSize(int x) {
            return size[find(x)];
        }
    }

    /**
     * Fast input reader for competitive programming.
     */
    private static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) {
                        throw new IOException("Unexpected end of input");
                    }
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.Arrays;
import java.util.InputMismatchException;
import java.util.NoSuchElementException;
import java.util.StringTokenizer;

public class Main {
    // Direction vectors for Up, Right, Down, Left
    private static final int[] DR = {-1, 0, 1, 0};
    private static final int[] DC = {0, 1, 0, -1};
    private static final int MOD = 10;

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out);
        try {
            solve(scanner, out);
        } finally {
            out.flush();
        }
    }

    private static void solve(FastScanner scanner, PrintWriter out) {
        int n = scanner.nextInt();
        int m = scanner.nextInt();
        char[][] grid = new char[n][m];
        for (int i = 0; i < n; i++) {
            grid[i] = scanner.next().toCharArray();
        }

        UnionFind uf = new UnionFind(n * m);

        // Build connected components for '.' cells
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < m; c++) {
                if (grid[r][c] == '.') {
                    int idx = r * m + c;
                    // Only check Right and Down to avoid duplicate union operations
                    for (int dir = 0; dir < 2; dir++) {
                        int nr = r + DR[dir];
                        int nc = c + DC[dir];
                        if (nr >= 0 && nr < n && nc >= 0 && nc < m && grid[nr][nc] == '.') {
                            uf.union(idx, nr * m + nc);
                        }
                    }
                }
            }
        }

        // Process grid and print results
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < m; c++) {
                if (grid[r][c] == '.') {
                    out.print('.');
                } else {
                    int totalSize = 0;
                    int[] adjacentRoots = new int[4];
                    int rootCount = 0;

                    // Find unique adjacent component roots
                    for (int dir = 0; dir < 4; dir++) {
                        int nr = r + DR[dir];
                        int nc = c + DC[dir];
                        if (nr >= 0 && nr < n && nc >= 0 && nc < m && grid[nr][nc] == '.') {
                            int root = uf.find(nr * m + nc);
                            boolean alreadyAdded = false;
                            for (int i = 0; i < rootCount; i++) {
                                if (adjacentRoots[i] == root) {
                                    alreadyAdded = true;
                                    break;
                                }
                            }
                            if (!alreadyAdded) {
                                adjacentRoots[rootCount++] = root;
                            }
                        }
                    }

                    // Sum sizes of unique adjacent components
                    for (int i = 0; i < rootCount; i++) {
                        totalSize += uf.getSize(adjacentRoots[i]);
                    }
                    out.print(totalSize % MOD);
                }
            }
            out.println();
        }
    }

    /**
     * Efficient Union-Find (Disjoint Set Union) with path compression and union by size.
     */
    private static class UnionFind {
        private final int[] parent;
        private final int[] size;

        public UnionFind(int n) {
            parent = new int[n];
            size = new int[n];
            Arrays.fill(parent, -1);
            Arrays.fill(size, 1);
        }

        public int find(int x) {
            if (parent[x] < 0) return x;
            return parent[x] = find(parent[x]); // Path compression
        }

        public void union(int x, int y) {
            int rootX = find(x);
            int rootY = find(y);
            if (rootX == rootY) return;

            // Union by size: attach smaller tree to larger tree
            if (size[rootX] < size[rootY]) {
                int temp = rootX;
                rootX = rootY;
                rootY = temp;
            }
            parent[rootY] = rootX;
            size[rootX] += size[rootY];
        }

        public int getSize(int x) {
            return size[find(x)];
        }
    }

    /**
     * Fast I/O helper using BufferedReader and StringTokenizer.
     */
    private static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        public String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) throw new NoSuchElementException();
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new InputMismatchException(e);
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.util.ArrayDeque;
import java.util.HashMap;
import java.util.Map;
import java.util.Queue;
import java.util.Scanner;

/**
 * Analyzes a character grid to identify connected components of '.' characters.
 * For each '*' character, computes a value based on the sizes of adjacent components.
 */
public class GridComponentAnalyzer {

    private final int rows;
    private final int cols;
    private final char[][] grid;
    private final int[][] componentIds;
    private final boolean[][] visited;
    private final Map<Integer, Integer> componentSizes;
    private int componentCount;

    /**
     * Initializes the analyzer with grid dimensions.
     */
    public GridComponentAnalyzer(int rows, int cols) {
        this.rows = rows;
        this.cols = cols;
        this.grid = new char[rows][cols];
        this.componentIds = new int[rows][cols];
        this.visited = new boolean[rows][cols];
        this.componentSizes = new HashMap<>();
        this.componentCount = 0;
    }

    /**
     * Reads a single row from the scanner into the grid.
     */
    public void readGridRow(Scanner scanner) {
        if (scanner.hasNext()) {
            this.grid[this.componentCount++] = scanner.next().toCharArray();
        }
    }

    /**
     * Identifies all connected '.' components using iterative BFS.
     * Assigns a unique ID to each component and records its size.
     */
    public void process() {
        int[][] directions = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};
        Queue<int[]> queue = new ArrayDeque<>();

        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (!visited[i][j] && grid[i][j] == '.') {
                    componentCount++;
                    queue.offer(new int[]{i, j});
                    visited[i][j] = true;
                    componentIds[i][j] = componentCount;
                    int size = 0;

                    while (!queue.isEmpty()) {
                        int[] current = queue.poll();
                        size++;
                        for (int[] dir : directions) {
                            int ni = current[0] + dir[0];
                            int nj = current[1] + dir[1];
                            if (ni >= 0 && ni < rows && nj >= 0 && nj < cols &&
                                    !visited[ni][nj] && grid[ni][nj] == '.') {
                                visited[ni][nj] = true;
                                componentIds[ni][nj] = componentCount;
                                queue.offer(new int[]{ni, nj});
                            }
                        }
                    }
                    componentSizes.put(componentCount, size);
                }
            }
        }
    }

    /**
     * Generates the output string, replacing '*' cells with computed values.
     */
    public String generateOutput() {
        StringBuilder sb = new StringBuilder();
        int[][] directions = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};

        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == '.') {
                    sb.append('.');
                } else {
                    int count = 1;
                    int[] neighborIds = new int[4];
                    int idCount = 0;

                    for (int[] dir : directions) {
                        int ni = i + dir[0];
                        int nj = j + dir[1];
                        if (ni >= 0 && ni < rows && nj >= 0 && nj < cols) {
                            int id = componentIds[ni][nj];
                            boolean alreadyCounted = false;
                            for (int k = 0; k < idCount; k++) {
                                if (neighborIds[k] == id) {
                                    alreadyCounted = true;
                                    break;
                                }
                            }
                            if (!alreadyCounted) {
                                count = (count + componentSizes.getOrDefault(id, 0)) % 10;
                                neighborIds[idCount++] = id;
                            }
                        }
                    }
                    sb.append(count);
                }
            }
            sb.append('\n');
        }
        return sb.toString();
    }

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            if (!scanner.hasNextInt()) {
                return;
            }
            int n = scanner.nextInt();
            int m = scanner.nextInt();

            GridComponentAnalyzer analyzer = new GridComponentAnalyzer(n, m);
            for (int i = 0; i < n; i++) {
                analyzer.readGridRow(scanner);
            }

            analyzer.process();
            System.out.print(analyzer.generateOutput());
        }
    }
}

