class TaskB {
    private static final int[][] DIRECTIONS = {{0, 1}, {1, 0}, {0, -1}, {-1, 0}};

    public void solve(InputReader in, PrintWriter out) {
        int n = in.nextInt();
        int m = in.nextInt();

        char[][] grid = new char[n][m];
        for (int i = 0; i < n; i++) {
            grid[i] = in.next().toCharArray();
        }

        int[][] componentIds = new int[n][m];
        int[] componentSizes = new int[n * m + 1];
        int componentCount = 1;

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == '.' && componentIds[i][j] == 0) {
                    dfs(i, j, grid, componentIds, componentSizes, n, m, componentCount);
                    componentCount++;
                }
            }
        }

        StringBuilder result = new StringBuilder();
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == '*') {
                    int sum = 1;
                    HashSet<Integer> visitedComponents = new HashSet<>();
                    for (int[] dir : DIRECTIONS) {
                        int r = i + dir[0];
                        int c = j + dir[1];
                        if (r >= 0 && c >= 0 && r < n && c < m && grid[r][c] != '*') {
                            int compId = componentIds[r][c];
                            if (visitedComponents.add(compId)) {
                                sum += componentSizes[compId];
                            }
                        }
                    }
                    result.append(sum % 10);
                } else {
                    result.append('.');
                }
            }
            result.append('\n');
        }
        out.println(result);
    }

    private void dfs(int x, int y, char[][] grid, int[][] componentIds, int[] componentSizes, int n, int m, int currentComponentId) {
        componentSizes[currentComponentId]++;
        componentIds[x][y] = currentComponentId;
        for (int[] dir : DIRECTIONS) {
            int r = x + dir[0];
            int c = y + dir[1];
            if (r >= 0 && c >= 0 && r < n && c < m && componentIds[r][c] == 0 && grid[r][c] == '.') {
                dfs(r, c, grid, componentIds, componentSizes, n, m, currentComponentId);
            }
        }
    }
}

