import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.OutputStreamWriter;
import java.io.PrintWriter;
import java.util.StringTokenizer;

public class Main {
    // Constants for grid values and processing
    private static final int WATER = -1;
    private static final int LAND = 1;
    private static final int MOD = 10;

    public static void main(String[] args) throws IOException {
        // Use BufferedReader and PrintWriter for efficient I/O handling
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));

        try {
            // Read grid dimensions
            String dimLine = br.readLine();
            if (dimLine == null) return;
            StringTokenizer st = new StringTokenizer(dimLine);
            int rows = Integer.parseInt(st.nextToken());
            int cols = Integer.parseInt(st.nextToken());

            // Initialize grid with 1-cell padding to simplify boundary checks
            int[][] grid = new int[rows + 2][cols + 2];
            int[][] componentId = new int[rows + 2][cols + 2];
            // Maximum possible components is rows * cols (checkerboard pattern)
            int[] componentSize = new int[rows * cols + 2];

            // Read grid data
            for (int i = 1; i <= rows; i++) {
                String line = br.readLine();
                if (line != null) {
                    line = line.trim();
                    for (int j = 1; j <= cols; j++) {
                        grid[i][j] = (line.charAt(j - 1) == '.') ? WATER : LAND;
                    }
                }
            }

            // Label connected components of water cells
            int currentComponentId = 1;
            for (int i = 1; i <= rows; i++) {
                for (int j = 1; j <= cols; j++) {
                    if (grid[i][j] == WATER && componentId[i][j] == 0) {
                        floodFill(grid, componentId, componentSize, i, j, currentComponentId);
                        currentComponentId++;
                    }
                }
            }

            // Compute values for land cells and print output
            for (int i = 1; i <= rows; i++) {
                for (int j = 1; j <= cols; j++) {
                    if (grid[i][j] == LAND) {
                        int value = computeLandValue(componentId, componentSize, i, j);
                        out.print(value % MOD);
                    } else {
                        out.print('.');
                    }
                }
                out.println();
            }
        } finally {
            out.flush();
        }
    }

    /**
     * Iteratively performs DFS to label connected water components.
     * Uses an explicit stack to prevent StackOverflowError on large grids.
     */
    private static void floodFill(int[][] grid, int[][] componentId, int[] componentSize,
                                  int startR, int startC, int id) {
        int maxElements = grid.length * grid[0].length;
        int[] stackR = new int[maxElements];
        int[] stackC = new int[maxElements];
        int top = 0;

        stackR[top] = startR;
        stackC[top] = startC;
        top++;

        while (top > 0) {
            top--;
            int r = stackR[top];
            int c = stackC[top];

            // Check boundaries and visitation status
            if (r < 1 || r >= grid.length - 1 || c < 1 || c >= grid[0].length - 1) continue;
            if (componentId[r][c] != 0 || grid[r][c] != WATER) continue;

            // Mark component and increment size counter
            componentId[r][c] = id;
            componentSize[id]++;

            // Push neighbors onto stack
            stackR[top] = r - 1; stackC[top] = c; top++;
            stackR[top] = r + 1; stackC[top] = c; top++;
            stackR[top] = r; stackC[top] = c - 1; top++;
            stackR[top] = r; stackC[top] = c + 1; top++;
        }
    }

    /**
     * Computes the value for a land cell by summing the sizes of unique adjacent water components.
     * Replaces the original complex conditional logic with a clear, maintainable set-based approach.
     */
    private static int computeLandValue(int[][] componentId, int[] componentSize, int r, int c) {
        int sum = 0;
        int[] dr = {-1, 0, 0, 1}; // Up, Left, Right, Down
        int[] dc = {0, -1, 1, 0};
        boolean[] seen = new boolean[componentId.length * componentId[0].length + 1];

        for (int d = 0; d < 4; d++) {
            int nr = r + dr[d];
            int nc = c + dc[d];
            int compId = componentId[nr][nc];

            if (compId != 0 && !seen[compId]) {
                seen[compId] = true;
                sum += componentSize[compId];
            }
        }
        return sum;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.ArrayList;
import java.util.ArrayDeque;
import java.util.HashSet;
import java.util.List;
import java.util.Queue;
import java.util.Set;
import java.util.StringTokenizer;
import java.awt.Point;

/**
 * Solves the labyrinth problem by computing connected components of '.' cells
 * and calculating values for '*' cells based on adjacent component sizes.
 */
public class LabyrinthSolver {

    private final int rows;
    private final int cols;
    private final char[][] grid;
    private final int[][] componentId;
    private final int[] componentSizes;

    /**
     * Initializes the solver with grid dimensions and content.
     * Computes connected components during construction.
     */
    public LabyrinthSolver(int rows, int cols, char[][] grid) {
        this.rows = rows;
        this.cols = cols;
        this.grid = grid;
        this.componentId = new int[rows][cols];
        // Size + 1 to safely accommodate 1-based component IDs
        this.componentSizes = new int[rows * cols + 1];
        computeComponents();
    }

    /**
     * Uses iterative BFS to identify connected components of '.' cells.
     * Assigns a unique ID to each cell and stores the total size of its component.
     */
    private void computeComponents() {
        boolean[][] visited = new boolean[rows][cols];
        int[] dr = {1, 0, -1, 0};
        int[] dc = {0, 1, 0, -1};
        int currentId = 0;

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '.' && !visited[r][c]) {
                    currentId++;
                    Queue<Point> queue = new ArrayDeque<>();
                    List<Point> componentCells = new ArrayList<>();

                    queue.add(new Point(r, c));
                    visited[r][c] = true;
                    componentCells.add(new Point(r, c));
                    componentId[r][c] = currentId;

                    while (!queue.isEmpty()) {
                        Point curr = queue.poll();
                        for (int d = 0; d < 4; d++) {
                            int nr = curr.x + dr[d];
                            int nc = curr.y + dc[d];

                            if (nr >= 0 && nr < rows && nc >= 0 && nc < cols
                                    && grid[nr][nc] == '.' && !visited[nr][nc]) {
                                visited[nr][nc] = true;
                                Point next = new Point(nr, nc);
                                componentCells.add(next);
                                componentId[nr][nc] = currentId;
                                queue.add(next);
                            }
                        }
                    }
                    componentSizes[currentId] = componentCells.size();
                }
            }
        }
    }

    /**
     * Calculates the value for a '*' cell based on adjacent connected components.
     * Sums the sizes of unique adjacent components, adds a base value of 1,
     * and returns the result modulo 10.
     */
    private int calculateStarValue(int r, int c) {
        int sum = 1;
        Set<Integer> visitedComponentIds = new HashSet<>();
        int[] dr = {1, 0, -1, 0};
        int[] dc = {0, 1, 0, -1};

        for (int d = 0; d < 4; d++) {
            int nr = r + dr[d];
            int nc = c + dc[d];

            if (nr >= 0 && nr < rows && nc >= 0 && nc < cols && grid[nr][nc] == '.') {
                int id = componentId[nr][nc];
                if (!visitedComponentIds.contains(id)) {
                    sum += componentSizes[id];
                    visitedComponentIds.add(id);
                }
            }
        }
        return sum % 10;
    }

    /**
     * Processes the grid and prints the transformed output.
     */
    public void solve(PrintWriter out) {
        for (int i = 0; i < rows; i++) {
            StringBuilder rowBuilder = new StringBuilder(cols);
            for (int j = 0; j < cols; j++) {
                rowBuilder.append(grid[i][j] == '*' ? calculateStarValue(i, j) : '.');
            }
            out.println(rowBuilder);
        }
    }

    public static void main(String[] args) {
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
             PrintWriter out = new PrintWriter(System.out)) {

            FastReader reader = new FastReader(br);
            String nStr = reader.next();
            if (nStr != null) {
                int n = Integer.parseInt(nStr);
                int m = reader.nextInt();

                char[][] grid = new char[n][m];
                for (int i = 0; i < n; i++) {
                    String row = reader.next();
                    if (row != null) {
                        grid[i] = row.toCharArray();
                    }
                }

                LabyrinthSolver solver = new LabyrinthSolver(n, m, grid);
                solver.solve(out);
            }
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    /**
     * Lightweight tokenizer for fast input reading.
     */
    private static class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastReader(BufferedReader br) {
            this.br = br;
        }

        public String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            String s = next();
            return s == null ? 0 : Integer.parseInt(s);
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.ArrayDeque;
import java.util.Queue;
import java.util.StringTokenizer;

/**
 * Refactored version of educationalrnd5_C.
 * 
 * Improvements made:
 * 1.  **Encapsulation**: Removed global static variables. Logic is encapsulated within methods.
 * 2.  **Robustness**: Replaced recursive DFS with iterative BFS to prevent StackOverflowError on large grids.
 * 3.  **Performance**: Replaced slow `Scanner` with `BufferedReader` and `StringTokenizer` for fast I/O.
 * 4.  **Readability**: Used descriptive variable names (e.g., `rows`, `cols`, `componentMap`, `componentSizes`).
 * 5.  **Efficiency**: Optimized the neighbor-checking logic to avoid object allocation (HashMap) in tight loops.
 * 6.  **Standards**: Adhered to Java naming conventions (PascalCase for classes, camelCase for variables).
 */
public class EducationalRound5C {

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner();
        PrintWriter out = new PrintWriter(System.out);

        try {
            // Read dimensions n (rows) and m (cols)
            // Using a robust check to handle potential empty inputs gracefully
            String nStr = scanner.next();
            if (nStr == null) {
                out.flush();
                return;
            }
            int rows = Integer.parseInt(nStr);
            int cols = scanner.nextInt();

            // Read the grid
            char[][] grid = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                String line = scanner.next();
                if (line != null) {
                    // Fill row, handling potential length mismatches safely
                    int len = Math.min(cols, line.length());
                    for (int j = 0; j < len; j++) {
                        grid[i][j] = line.charAt(j);
                    }
                }
            }

            // Process the grid and output the result
            solve(grid, rows, cols, out);

        } catch (Exception e) {
            // In a production environment, proper logging would be used here.
            e.printStackTrace();
        } finally {
            out.flush();
        }
    }

    private static void solve(char[][] grid, int rows, int cols, PrintWriter out) {
        // componentMap stores the ID of the connected component for each '.' cell.
        // 0 indicates a wall ('*') or an unvisited cell.
        int[][] componentMap = new int[rows][cols];

        // componentSizes stores the size of each connected component.
        // Index corresponds to component ID.
        int[] componentSizes = new int[rows * cols + 1];
        int componentCount = 0;

        // Directions for traversal (Up, Down, Left, Right)
        int[] dr = {-1, 1, 0, 0};
        int[] dc = {0, 0, -1, 1};

        // 1. Identify connected components of '.' cells using BFS
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '.' && componentMap[r][c] == 0) {
                    componentCount++;
                    int currentSize = 0;

                    // Iterative BFS to find the component
                    Queue<int[]> queue = new ArrayDeque<>();
                    queue.offer(new int[]{r, c});
                    componentMap[r][c] = componentCount;
                    currentSize++;

                    while (!queue.isEmpty()) {
                        int[] curr = queue.poll();
                        int cr = curr[0];
                        int cc = curr[1];

                        for (int k = 0; k < 4; k++) {
                            int nr = cr + dr[k];
                            int nc = cc + dc[k];

                            // Check bounds, if it's a '.' and not yet visited
                            if (nr >= 0 && nr < rows && nc >= 0 && nc < cols
                                    && grid[nr][nc] == '.' && componentMap[nr][nc] == 0) {
                                componentMap[nr][nc] = componentCount;
                                currentSize++;
                                queue.offer(new int[]{nr, nc});
                            }
                        }
                    }
                    componentSizes[componentCount] = currentSize;
                }
            }
        }

        // 2. Calculate replacement values for '*' cells
        // We modify the grid in-place. Since we rely on componentMap (which is static after step 1),
        // updating grid cells does not affect the logic.

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '*') {
                    int sumSizes = 0;

                    // Collect unique component IDs of adjacent neighbors.
                    // Since there are at most 4 neighbors, we store them in a small array.
                    int[] neighborIds = new int[4];
                    int count = 0;

                    for (int k = 0; k < 4; k++) {
                        int nr = r + dr[k];
                        int nc = c + dc[k];

                        if (nr >= 0 && nr < rows && nc >= 0 && nc < cols) {
                            int id = componentMap[nr][nc];
                            if (id != 0) { // 0 means wall or unvisited (though all '.' should be visited)
                                neighborIds[count++] = id;
                            }
                        }
                    }

                    // Sum sizes of unique components
                    for (int i = 0; i < count; i++) {
                        int currentId = neighborIds[i];
                        boolean isDuplicate = false;
                        // Check against previously added IDs in this cell's context
                        for (int j = 0; j < i; j++) {
                            if (neighborIds[j] == currentId) {
                                isDuplicate = true;
                                break;
                            }
                        }
                        if (!isDuplicate) {
                            sumSizes += componentSizes[currentId];
                        }
                    }

                    // Apply formula: (sum + 1) % 10
                    int val = (sumSizes + 1) % 10;
                    grid[r][c] = (char) ('0' + val);
                }
            }
        }

        // 3. Output the modified grid
        for (int r = 0; r < rows; r++) {
            out.println(grid[r]);
        }
    }

    /**
     * Helper class for fast input reading.
     */
    static class FastScanner {
        BufferedReader br;
        StringTokenizer st;

        public FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    e.printStackTrace();
                    return null;
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            String s = next();
            if (s == null) throw new RuntimeException("End of input");
            return Integer.parseInt(s);
        }
    }
}

import java.io.BufferedOutputStream;
import java.io.IOException;
import java.io.InputStream;
import java.io.OutputStream;
import java.io.PrintWriter;
import java.util.HashSet;
import java.util.InputMismatchException;
import java.util.Set;

public class Main {
    public static void main(String[] args) {
        FastScanner in = new FastScanner(System.in);
        FastPrinter out = new FastPrinter(System.out);
        new GridSolver().solve(in, out);
        out.close();
    }

    /**
     * Solves the grid problem by computing connected component sizes
     * and calculating answers for non-'.' cells based on adjacent components.
     */
    static class GridSolver {
        public void solve(FastScanner in, FastPrinter out) {
            int rows = in.nextInt();
            int cols = in.nextInt();
            char[][] grid = new char[rows][];
            for (int r = 0; r < rows; r++) {
                grid[r] = in.next().toCharArray();
            }

            // Build DSU for connected '.' components
            DSU dsu = new DSU(rows * cols);
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] == '.') {
                        int idx = r * cols + c;
                        if (r > 0 && grid[r - 1][c] == '.') {
                            dsu.union(idx, (r - 1) * cols + c);
                        }
                        if (c > 0 && grid[r][c - 1] == '.') {
                            dsu.union(idx, r * cols + (c - 1));
                        }
                    }
                }
            }

            // Precompute component sizes for each '.' cell
            int[][] componentSize = new int[rows][cols];
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] == '.') {
                        componentSize[r][c] = dsu.getSize(r * cols + c);
                    }
                }
            }

            char[][] result = new char[rows][cols];
            int[] dr = {1, 0, -1, 0};
            int[] dc = {0, 1, 0, -1};
            Set<Integer> seenRoots = new HashSet<>();

            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] == '.') {
                        result[r][c] = '.';
                    } else {
                        seenRoots.clear();
                        int sum = 1; // Count the cell itself
                        for (int k = 0; k < 4; k++) {
                            int nr = r + dr[k];
                            int nc = c + dc[k];
                            if (nr >= 0 && nr < rows && nc >= 0 && nc < cols && grid[nr][nc] == '.') {
                                int root = dsu.find(nr * cols + nc);
                                // Avoid double-counting the same component
                                if (seenRoots.add(root)) {
                                    sum += componentSize[nr][nc];
                                }
                            }
                        }
                        result[r][c] = (char) ('0' + (sum % 10));
                    }
                }
            }

            for (char[] row : result) {
                out.printLine(row);
            }
        }
    }

    /**
     * Disjoint Set Union (DSU) with path compression and union by size.
     * Tracks the size of each component for O(1) size queries.
     */
    static class DSU {
        private final int[] parent;
        private final int[] size;

        public DSU(int n) {
            parent = new int[n];
            size = new int[n];
            for (int i = 0; i < n; i++) {
                parent[i] = i;
                size[i] = 1;
            }
        }

        public int find(int i) {
            if (parent[i] != i) {
                parent[i] = find(parent[i]); // Path compression
            }
            return parent[i];
        }

        public void union(int i, int j) {
            int rootI = find(i);
            int rootJ = find(j);
            if (rootI != rootJ) {
                // Union by size
                if (size[rootI] < size[rootJ]) {
                    int temp = rootI;
                    rootI = rootJ;
                    rootJ = temp;
                }
                parent[rootJ] = rootI;
                size[rootI] += size[rootJ];
            }
        }

        public int getSize(int i) {
            return size[find(i)];
        }
    }

    /**
     * Fast input reader for competitive programming style inputs.
     */
    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1024];
        private int ptr = 0;
        private int buflen = 0;

        public FastScanner(InputStream in) {
            this.in = in;
        }

        private byte readByte() throws IOException {
            if (ptr >= buflen) {
                ptr = 0;
                buflen = in.read(buffer);
                if (buflen <= 0) return -1;
            }
            return buffer[ptr++];
        }

        public int nextInt() {
            int c = readByte();
            while (c <= ' ') {
                if (c == -1) throw new InputMismatchException();
                c = readByte();
            }
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = readByte();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9') throw new InputMismatchException();
                res = res * 10 + c - '0';
                c = readByte();
            } while (c > ' ');
            return res * sgn;
        }

        public String next() {
            int c = readByte();
            while (c <= ' ') {
                if (c == -1) throw new InputMismatchException();
                c = readByte();
            }
            StringBuilder sb = new StringBuilder();
            do {
                sb.append((char) c);
                c = readByte();
            } while (c > ' ');
            return sb.toString();
        }
    }

    /**
     * Fast output writer with buffered printing.
     */
    static class FastPrinter {
        private final PrintWriter out;

        public FastPrinter(OutputStream outputStream) {
            out = new PrintWriter(new BufferedOutputStream(outputStream));
        }

        public void printLine(char[] array) {
            out.println(array);
        }

        public void close() {
            out.flush();
            out.close();
        }
    }
}

import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

/**
 * Refactored solution for the Labyrinth problem (Codeforces 616C).
 * 
 * Refactoring Improvements:
 * 1. Separation of Concerns: Logic is broken down into distinct methods (parsing, 
 *    component finding, calculation, output) rather than a monolithic main method.
 * 2. Readability: Variable names are descriptive (e.g., 'rows', 'cols', 'grid', 
 *    'componentSizes').
 * 3. Performance: Replaced the allocation-heavy HashSet inside the calculation loop 
 *    with a primitive array buffer to check for duplicate neighbor IDs.
 * 4. Output Efficiency: Used StringBuilder to construct the output string efficiently 
 *    instead of printing line by line or manipulating char arrays manually.
 * 5. Encapsulation: The solution is encapsulated within a class instance to manage state.
 */
public class LabyrinthSolver {

    public static void main(String[] args) {
        LabyrinthSolver solver = new LabyrinthSolver();
        solver.run();
    }

    /**
     * Orchestrates the execution of the solver.
     */
    public void run() {
        Scanner scanner = new Scanner(System.in);

        // Basic input validation
        if (!scanner.hasNextInt()) {
            return;
        }

        int rows = scanner.nextInt();
        int cols = scanner.nextInt();
        scanner.nextLine(); // Consume the newline character after the integers

        // 1. Parse the input grid
        int[][] grid = parseGrid(scanner, rows, cols);

        // 2. Identify connected components and store their sizes
        List<Integer> componentSizes = findConnectedComponents(grid);

        // 3. Calculate and print the result grid
        printResult(grid, componentSizes, rows, cols);

        scanner.close();
    }

    /**
     * Reads the grid from the scanner.
     * -1 represents an empty space ('.'), 0 represents a wall.
     */
    private int[][] parseGrid(Scanner scanner, int rows, int cols) {
        int[][] grid = new int[rows][cols];
        for (int i = 0; i < rows; i++) {
            String line = scanner.nextLine();
            for (int j = 0; j < cols; j++) {
                grid[i][j] = (line.charAt(j) == '.') ? -1 : 0;
            }
        }
        return grid;
    }

    /**
     * Iterates through the grid to find all connected components of empty spaces.
     * Modifies the grid in-place to replace -1 with component IDs (1, 2, 3...).
     * Returns a list where index i corresponds to the size of component ID (i+1).
     */
    private List<Integer> findConnectedComponents(int[][] grid) {
        List<Integer> componentSizes = new ArrayList<>();
        int currentComponentId = 1;
        int rows = grid.length;
        int cols = grid[0].length;

        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                // If the cell is an unvisited empty space (-1)
                if (grid[i][j] == -1) {
                    int size = dfs(grid, i, j, currentComponentId);
                    componentSizes.add(size);
                    currentComponentId++;
                }
            }
        }
        return componentSizes;
    }

    /**
     * Performs Depth First Search (DFS) to flood-fill a connected component.
     * Marks visited cells with the provided componentId.
     */
    private int dfs(int[][] grid, int x, int y, int componentId) {
        // Boundary checks and visited check
        // grid[x][y] != -1 means it's either a wall (0) or already visited (ID > 0)
        if (x < 0 || y < 0 || x >= grid.length || y >= grid[0].length || grid[x][y] != -1) {
            return 0;
        }

        grid[x][y] = componentId;

        return 1 + dfs(grid, x + 1, y, componentId) +
                   dfs(grid, x - 1, y, componentId) +
                   dfs(grid, x, y + 1, componentId) +
                   dfs(grid, x, y - 1, componentId);
    }

    /**
     * Calculates the resulting grid where walls are replaced by the size of the 
     * region they would connect if converted to empty space.
     */
    private void printResult(int[][] grid, List<Integer> componentSizes, int rows, int cols) {
        StringBuilder output = new StringBuilder();

        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == 0) {
                    // It is a wall. Calculate the size if it were converted to an empty space.
                    int potentialSize = calculatePotentialSize(grid, componentSizes, i, j);
                    output.append((char) ('0' + (potentialSize % 10)));
                } else {
                    // It is an empty space, print '.'
                    output.append('.');
                }
            }
            output.append('\n');
        }
        System.out.print(output);
    }

    /**
     * Calculates the size of the region a wall cell would join if it became empty.
     * Sum = 1 (itself) + sum of sizes of unique adjacent components.
     */
    private int calculatePotentialSize(int[][] grid, List<Integer> componentSizes, int x, int y) {
        int size = 1; // Count the cell itself
        int[] neighborIds = new int[4]; // Buffer to store unique neighbor IDs (max 4 neighbors)
        int uniqueCount = 0;

        // Directions: Down, Up, Right, Left
        int[] dx = {1, -1, 0, 0};
        int[] dy = {0, 0, 1, -1};

        for (int k = 0; k < 4; k++) {
            int nx = x + dx[k];
            int ny = y + dy[k];

            // Check bounds
            if (nx >= 0 && ny >= 0 && nx < grid.length && ny < grid[0].length) {
                int neighborId = grid[nx][ny];

                // Neighbor must be part of a valid component (ID > 0)
                if (neighborId > 0) {
                    // Check if we've already counted this component to avoid double counting
                    if (!isDuplicate(neighborIds, uniqueCount, neighborId)) {
                        size += componentSizes.get(neighborId - 1);
                        neighborIds[uniqueCount++] = neighborId;
                    }
                }
            }
        }
        return size;
    }

    /**
     * Helper method to check if a value exists in the first 'count' elements of an array.
     */
    private boolean isDuplicate(int[] array, int count, int value) {
        for (int i = 0; i < count; i++) {
            if (array[i] == value) {
                return true;
            }
        }
        return false;
    }
}

import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.io.IOException;
import java.util.ArrayDeque;
import java.util.Queue;
import java.util.StringTokenizer;

public class TheLabyrinth {
    // Direction vectors for moving up, down, left, right
    private static final int[] DR = {-1, 1, 0, 0};
    private static final int[] DC = {0, 0, -1, 1};

    public static void main(String[] args) throws IOException {
        // Use try-with-resources for automatic resource management
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
             PrintWriter pw = new PrintWriter(System.out)) {

            String line = br.readLine();
            if (line == null || line.trim().isEmpty()) return;

            StringTokenizer st = new StringTokenizer(line);
            int n = Integer.parseInt(st.nextToken());
            int m = Integer.parseInt(st.nextToken());

            char[][] grid = new char[n][];
            for (int i = 0; i < n; i++) {
                String row = br.readLine();
                grid[i] = (row != null) ? row.toCharArray() : new char[0];
            }

            // Track which component each cell belongs to (0 means unvisited)
            int[][] componentIds = new int[n][m];
            // Store the size of each component (index = componentId)
            int[] componentSizes = new int[n * m + 1];
            int currentId = 1;

            // Identify connected components of open spaces ('.')
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    if (grid[i][j] == '.' && componentIds[i][j] == 0) {
                        componentSizes[currentId] = bfs(grid, componentIds, i, j, currentId++);
                    }
                }
            }

            // Build the output grid
            StringBuilder sb = new StringBuilder(n * (m + 1));
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    if (grid[i][j] == '*') {
                        int sum = 1; // Count the cell itself
                        int[] neighborIds = new int[4];
                        int count = 0;

                        // Check all 4 adjacent cells
                        for (int d = 0; d < 4; d++) {
                            int nr = i + DR[d];
                            int nc = j + DC[d];

                            if (nr >= 0 && nr < n && nc >= 0 && nc < grid[nr].length && grid[nr][nc] == '.') {
                                int id = componentIds[nr][nc];
                                // Avoid counting the same component multiple times
                                boolean exists = false;
                                for (int k = 0; k < count; k++) {
                                    if (neighborIds[k] == id) {
                                        exists = true;
                                        break;
                                    }
                                }
                                if (!exists) {
                                    neighborIds[count++] = id;
                                    sum += componentSizes[id];
                                }
                            }
                        }
                        sb.append(sum % 10);
                    } else {
                        sb.append('.');
                    }
                }
                sb.append('\n');
            }
            pw.println(sb);
        }
    }

    /**
     * Iterative BFS to find the size of a connected component and assign a unique ID to all cells in it.
     */
    private static int bfs(char[][] grid, int[][] componentIds, int startR, int startC, int componentId) {
        int n = grid.length;
        int size = 0;
        Queue<int[]> queue = new ArrayDeque<>();
        queue.offer(new int[]{startR, startC});
        componentIds[startR][startC] = componentId;

        while (!queue.isEmpty()) {
            int[] curr = queue.poll();
            int r = curr[0];
            int c = curr[1];
            size++;

            for (int d = 0; d < 4; d++) {
                int nr = r + DR[d];
                int nc = c + DC[d];
                if (nr >= 0 && nr < n && nc >= 0 && nc < grid[nr].length &&
                    grid[nr][nc] == '.' && componentIds[nr][nc] == 0) {
                    componentIds[nr][nc] = componentId;
                    queue.offer(new int[]{nr, nc});
                }
            }
        }
        return size;
    }
}

import java.io.*;
import java.util.*;

/**
 * Analyzes a grid to identify connected components of empty cells and computes
 * weighted values for star cells based on adjacent component sizes.
 */
public class GridComponentAnalyzer {

    // Constants
    private static final int[] DX = {-1, 1, 0, 0};
    private static final int[] DY = {0, 0, 1, -1};
    private static final int MOD = 10;
    private static final char EMPTY_CELL = '.';
    private static final char STAR_CELL = '*';

    // Instance state (removed static globals for better testability and encapsulation)
    private int rows;
    private int cols;
    private char[][] grid;
    private int[][] regionSizes;
    private int[][] regionIds;
    private int currentRegionId = 0;

    public static void main(String[] args) {
        // Try-with-resources ensures proper cleanup of I/O streams
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
             PrintWriter pr = new PrintWriter(new OutputStreamWriter(System.out))) {

            String header = br.readLine();
            if (header == null) return;

            String[] parts = header.trim().split("\\s+");
            if (parts.length < 2) return;

            GridComponentAnalyzer analyzer = new GridComponentAnalyzer();
            analyzer.rows = Integer.parseInt(parts[0]);
            analyzer.cols = Integer.parseInt(parts[1]);

            analyzer.grid = new char[analyzer.rows][analyzer.cols];
            analyzer.regionSizes = new int[analyzer.rows][analyzer.cols];
            analyzer.regionIds = new int[analyzer.rows][analyzer.cols];
            for (int[] row : analyzer.regionIds) {
                Arrays.fill(row, -1); // -1 indicates unvisited
            }

            for (int i = 0; i < analyzer.rows; i++) {
                String line = br.readLine();
                if (line != null) {
                    analyzer.grid[i] = line.toCharArray();
                }
            }

            analyzer.analyze();
            analyzer.printResult(pr);
        } catch (IOException e) {
            System.err.println("Error processing input: " + e.getMessage());
        }
    }

    /**
     * Traverses the grid to identify and label all connected empty cell regions.
     */
    private void analyze() {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == EMPTY_CELL && regionIds[r][c] == -1) {
                    processConnectedComponent(r, c);
                }
            }
        }
    }

    /**
     * Uses BFS to find all cells in a connected component, assigns them a region ID,
     * and records the component's total size.
     */
    private void processConnectedComponent(int startR, int startC) {
        currentRegionId++;
        List<Point> componentCells = new ArrayList<>();
        Queue<Point> queue = new ArrayDeque<>();

        queue.offer(new Point(startR, startC));
        regionIds[startR][startC] = currentRegionId;
        componentCells.add(new Point(startR, startC));

        while (!queue.isEmpty()) {
            Point current = queue.poll();
            for (int d = 0; d < 4; d++) {
                int nr = current.r + DX[d];
                int nc = current.c + DY[d];
                if (isValid(nr, nc) && grid[nr][nc] == EMPTY_CELL && regionIds[nr][nc] == -1) {
                    regionIds[nr][nc] = currentRegionId;
                    componentCells.add(new Point(nr, nc));
                    queue.offer(new Point(nr, nc));
                }
            }
        }

        int componentSize = componentCells.size();
        for (Point cell : componentCells) {
            regionSizes[cell.r][cell.c] = componentSize;
        }
    }

    /**
     * Generates the output grid. Star cells are replaced with the sum of adjacent
     * region sizes (modulo 10), ensuring each region is only counted once.
     */
    private void printResult(PrintWriter pr) {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == STAR_CELL) {
                    int sum = 1; // Original logic initializes count to 1
                    Set<Integer> adjacentRegions = new HashSet<>();

                    for (int d = 0; d < 4; d++) {
                        int nr = r + DX[d];
                        int nc = c + DY[d];
                        if (isValid(nr, nc)) {
                            int regionId = regionIds[nr][nc];
                            if (regionId != -1 && !adjacentRegions.contains(regionId)) {
                                adjacentRegions.add(regionId);
                                sum = (sum + regionSizes[nr][nc]) % MOD;
                            }
                        }
                    }
                    pr.print(sum);
                } else {
                    pr.print(grid[r][c]);
                }
            }
            pr.println();
        }
    }

    private boolean isValid(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /**
     * Immutable coordinate holder for BFS traversal.
     */
    private static class Point {
        final int r;
        final int c;

        Point(int r, int c) {
            this.r = r;
            this.c = c;
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.ArrayDeque;
import java.util.Deque;
import java.util.HashSet;
import java.util.StringTokenizer;

/**
 * Processes a grid to identify connected components of empty cells ('.'),
 * calculates their sizes, and computes a modulo-10 result for obstacle cells
 * based on adjacent component sizes.
 */
public class GridProcessor {
    private final int rows;
    private final int cols;
    private final int[][] grid;
    private final int[] componentSizes;

    /**
     * @param rows Number of rows in the grid
     * @param cols Number of columns in the grid
     */
    public GridProcessor(int rows, int cols) {
        if (rows <= 0 || cols <= 0) {
            throw new IllegalArgumentException("Grid dimensions must be positive.");
        }
        this.rows = rows;
        this.cols = cols;
        this.grid = new int[rows][cols];
        // Each cell can theoretically be its own component. +2 safely handles 1-based indexing.
        this.componentSizes = new int[rows * cols + 2];
    }

    /**
     * Orchestrates the grid processing pipeline.
     */
    public void process(BufferedReader reader, PrintWriter writer) throws IOException {
        readGrid(reader);
        labelComponents();
        calculateAndPrintResults(writer);
        writer.flush();
    }

    /**
     * Reads the grid from input. '.' becomes 0, any other character becomes -1.
     */
    private void readGrid(BufferedReader reader) throws IOException {
        StringTokenizer st = new StringTokenizer("");
        for (int i = 0; i < rows; i++) {
            while (!st.hasMoreTokens()) {
                String line = reader.readLine();
                if (line == null) break;
                st = new StringTokenizer(line);
            }
            if (st.hasMoreTokens()) {
                String rowStr = st.nextToken();
                for (int j = 0; j < cols && j < rowStr.length(); j++) {
                    grid[i][j] = (rowStr.charAt(j) == '.') ? 0 : -1;
                }
            }
        }
    }

    /**
     * Identifies connected components of '.' cells using iterative DFS.
     * Assigns a unique ID to each component and records its size.
     */
    private void labelComponents() {
        int componentId = 1;
        Deque<int[]> stack = new ArrayDeque<>();
        int[] dr = {1, -1, 0, 0};
        int[] dc = {0, 0, 1, -1};

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == 0) {
                    int size = 0;
                    grid[r][c] = componentId;
                    stack.push(new int[]{r, c});
                    size++;

                    while (!stack.isEmpty()) {
                        int[] curr = stack.pop();
                        for (int k = 0; k < 4; k++) {
                            int nr = curr[0] + dr[k];
                            int nc = curr[1] + dc[k];
                            if (nr >= 0 && nr < rows && nc >= 0 && nc < cols && grid[nr][nc] == 0) {
                                grid[nr][nc] = componentId;
                                stack.push(new int[]{nr, nc});
                                size++;
                            }
                        }
                    }
                    componentSizes[componentId] = size;
                    componentId++;
                }
            }
        }
    }

    /**
     * Computes the required value for each obstacle cell and prints the grid.
     */
    private void calculateAndPrintResults(PrintWriter writer) {
        int[] dr = {1, -1, 0, 0};
        int[] dc = {0, 0, 1, -1};
        HashSet<Integer> seenComponents = new HashSet<>();

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == -1) {
                    int result = 1;
                    seenComponents.clear();
                    for (int k = 0; k < 4; k++) {
                        int nr = r + dr[k];
                        int nc = c + dc[k];
                        // After labeling, any non -1 value is a valid component ID
                        if (nr >= 0 && nr < rows && nc >= 0 && nc < cols && grid[nr][nc] != -1) {
                            int compId = grid[nr][nc];
                            if (!seenComponents.contains(compId)) {
                                seenComponents.add(compId);
                                result += componentSizes[compId];
                            }
                        }
                    }
                    writer.print(result % 10);
                } else {
                    writer.print('.');
                }
            }
            writer.println();
        }
    }

    public static void main(String[] args) throws IOException {
        // Use try-with-resources to ensure proper stream closure and flushing
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
             PrintWriter writer = new PrintWriter(System.out)) {

            StringTokenizer st = new StringTokenizer("");
            while (!st.hasMoreTokens()) {
                String line = reader.readLine();
                if (line == null) return;
                st = new StringTokenizer(line);
            }

            int n = Integer.parseInt(st.nextToken());
            int m = Integer.parseInt(st.nextToken());

            GridProcessor processor = new GridProcessor(n, m);
            processor.process(reader, writer);
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.HashSet;
import java.util.Set;

public class Main {
    // Constants extracted for maintainability and clarity
    private static final int MOD = 10;
    // Direction vectors for up, right, down, left
    private static final int[] DR = {-1, 0, 1, 0};
    private static final int[] DC = {0, 1, 0, -1};

    public static void main(String[] args) throws IOException {
        // Replaced custom fast I/O with standard library for better maintainability
        // and to avoid common pitfalls like nextInt()/nextLine() mismatch bugs.
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter out = new PrintWriter(System.out);

        try {
            // Read dimensions, safely skipping any leading empty lines
            String line = reader.readLine();
            while (line != null && line.trim().isEmpty()) {
                line = reader.readLine();
            }
            if (line == null) return;

            String[] dims = line.trim().split("\\s+");
            int n = Integer.parseInt(dims[0]);
            int m = Integer.parseInt(dims[1]);

            char[][] grid = new char[n][m];
            int[] parent = new int[n * m];
            int[] size = new int[n * m];

            // Initialize DSU structures
            for (int i = 0; i < n * m; i++) {
                parent[i] = i;
                size[i] = 1;
            }

            // Read grid rows
            for (int i = 0; i < n; i++) {
                String row = reader.readLine();
                if (row == null) row = "";
                grid[i] = row.toCharArray();
            }

            // Build connected components using DSU
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    if (grid[i][j] == '.') {
                        int idx = i * m + j;
                        for (int d = 0; d < 4; d++) {
                            int ni = i + DR[d];
                            int nj = j + DC[d];
                            if (ni >= 0 && ni < n && nj >= 0 && nj < m && grid[ni][nj] == '.') {
                                union(parent, size, idx, ni * m + nj);
                            }
                        }
                    }
                }
            }

            // Process each cell and output result
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    if (grid[i][j] == '.') {
                        out.print('.');
                    } else {
                        Set<Integer> adjacentRoots = new HashSet<>();
                        for (int d = 0; d < 4; d++) {
                            int ni = i + DR[d];
                            int nj = j + DC[d];
                            if (ni >= 0 && ni < n && nj >= 0 && nj < m && grid[ni][nj] == '.') {
                                adjacentRoots.add(find(parent, ni * m + nj));
                            }
                        }
                        int connectedSize = 0;
                        for (int root : adjacentRoots) {
                            connectedSize += size[root];
                        }
                        // Simplified modulo operation; original Util.mod was redundant
                        out.print((connectedSize + 1) % MOD);
                    }
                }
                out.println();
            }
        } finally {
            out.flush();
        }
    }

    /**
     * Iterative path compression for DSU find operation.
     * Prevents StackOverflowError on large grids compared to recursive implementation.
     */
    private static int find(int[] parent, int i) {
        int root = i;
        while (root != parent[root]) {
            root = parent[root];
        }
        while (i != root) {
            int next = parent[i];
            parent[i] = root;
            i = next;
        }
        return root;
    }

    /**
     * Union by size for DSU. Attaches the smaller tree to the larger tree
     * to keep the tree flat and operations near O(α(n)).
     */
    private static void union(int[] parent, int[] size, int i, int j) {
        int rootI = find(parent, i);
        int rootJ = find(parent, j);
        if (rootI != rootJ) {
            if (size[rootI] < size[rootJ]) {
                int temp = rootI;
                rootI = rootJ;
                rootJ = temp;
            }
            parent[rootJ] = rootI;
            size[rootI] += size[rootJ];
        }
    }
}

import java.io.*;
import java.util.*;

public class Main {
    /** Directions for moving in the grid: right, down, left, up */
    private static final int[][] DIRECTIONS = {{0, 1}, {1, 0}, {-1, 0}, {0, -1}};

    public static void main(String[] args) throws IOException {
        FastReader reader = new FastReader(System.in);
        FastWriter writer = new FastWriter(System.out);

        try {
            solve(reader, writer);
        } finally {
            writer.close();
            reader.close();
        }
    }

    /**
     * Core logic for grid component analysis and output generation.
     */
    private static void solve(FastReader reader, FastWriter writer) throws IOException {
        int rows = reader.nextInt();
        int cols = reader.nextInt();

        // 1-based indexing for convenience, matching original logic
        int[][] grid = new int[rows + 1][cols + 1];

        // Read input grid: '.' becomes 1 (unvisited empty space), others become 0
        for (int i = 1; i <= rows; i++) {
            String line = reader.next();
            for (int j = 1; j <= cols; j++) {
                if (line.charAt(j - 1) == '.') {
                    grid[i][j] = 1;
                }
            }
        }

        // Track component sizes. IDs start at 2, so size = rows*cols + 2 is safely sufficient.
        int[] componentSizes = new int[rows * cols + 2];
        int currentComponentId = 2;

        // 2. Identify connected components using iterative BFS
        for (int i = 1; i <= rows; i++) {
            for (int j = 1; j <= cols; j++) {
                if (grid[i][j] == 1) {
                    int size = 0;
                    Queue<int[]> queue = new ArrayDeque<>();
                    queue.offer(new int[]{i, j});
                    grid[i][j] = currentComponentId;
                    size++;

                    while (!queue.isEmpty()) {
                        int[] curr = queue.poll();
                        int x = curr[0];
                        int y = curr[1];

                        for (int[] dir : DIRECTIONS) {
                            int nx = x + dir[0];
                            int ny = y + dir[1];

                            if (isValidCell(nx, ny, rows, cols) && grid[nx][ny] == 1) {
                                grid[nx][ny] = currentComponentId;
                                size++;
                                queue.offer(new int[]{nx, ny});
                            }
                        }
                    }
                    componentSizes[currentComponentId] = size;
                    currentComponentId++;
                }
            }
        }

        // 3. Calculate adjacent component sums for non-'.' cells
        int[][] resultGrid = new int[rows + 1][cols + 1];
        int[] neighborIds = new int[4]; // Max 4 neighbors

        for (int i = 1; i <= rows; i++) {
            for (int j = 1; j <= cols; j++) {
                // Skip cells that were originally '.'
                if (grid[i][j] != 0) continue;

                int sum = 0;
                int uniqueCount = 0;

                for (int[] dir : DIRECTIONS) {
                    int nx = i + dir[0];
                    int ny = j + dir[1];

                    if (isValidCell(nx, ny, rows, cols) && grid[nx][ny] != 0) {
                        int compId = grid[nx][ny];

                        // Check if this component was already counted from another neighbor
                        boolean alreadyCounted = false;
                        for (int k = 0; k < uniqueCount; k++) {
                            if (neighborIds[k] == compId) {
                                alreadyCounted = true;
                                break;
                            }
                        }

                        if (!alreadyCounted) {
                            neighborIds[uniqueCount++] = compId;
                            sum += componentSizes[compId];
                        }
                    }
                }
                resultGrid[i][j] = sum;
            }
        }

        // 4. Generate output
        for (int i = 1; i <= rows; i++) {
            for (int j = 1; j <= cols; j++) {
                if (resultGrid[i][j] == 0) {
                    writer.print('.');
                } else {
                    writer.print(resultGrid[i][j] % 10);
                }
            }
            writer.println();
        }
    }

    /** Checks if coordinates are within grid bounds (1-based) */
    private static boolean isValidCell(int x, int y, int rows, int cols) {
        return x >= 1 && x <= rows && y >= 1 && y <= cols;
    }

    /** Fast Input Reader for competitive programming / large I/O */
    static class FastReader {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream inputStream) {
            reader = new BufferedReader(new InputStreamReader(inputStream));
            tokenizer = new StringTokenizer("");
        }

        private String innerNextLine() {
            try {
                return reader.readLine();
            } catch (IOException ex) {
                return null;
            }
        }

        public boolean hasNext() {
            while (!tokenizer.hasMoreTokens()) {
                String nextLine = innerNextLine();
                if (nextLine == null) {
                    return false;
                }
                tokenizer = new StringTokenizer(nextLine);
            }
            return true;
        }

        public String next() {
            hasNext();
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }

    /** Fast Output Writer for competitive programming / large I/O */
    static class FastWriter {
        private BufferedWriter writer;

        public FastWriter(OutputStream outputStream) {
            writer = new BufferedWriter(new OutputStreamWriter(outputStream));
        }

        public void print(Object object) throws IOException {
            writer.write(object.toString());
        }

        public void println() throws IOException {
            writer.newLine();
        }

        public void close() throws IOException {
            writer.close();
        }
    }
}

import java.io.*;
import java.util.*;

public class Main {
    private static final int[][] DIRECTIONS = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};
    private static final char EMPTY_CELL = '.';
    private static final int MODULO = 10;

    public static void main(String[] args) {
        InputReader in = new InputReader(System.in);
        PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out));
        solve(in, out);
        out.flush();
    }

    /**
     * Solves the grid problem for a single test case.
     */
    private static void solve(InputReader in, PrintWriter out) {
        int n = in.nextInt();
        int m = in.nextInt();

        char[][] grid = new char[n][m];
        for (int i = 0; i < n; i++) {
            String line = in.next();
            grid[i] = line.toCharArray();
        }

        int[][] componentIds = new int[n][m];
        int[] componentSizes = new int[n * m + 1];
        int currentComponentId = 0;

        // Identify connected components of empty cells
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == EMPTY_CELL && componentIds[i][j] == 0) {
                    currentComponentId++;
                    dfs(i, j, currentComponentId, n, m, grid, componentIds, componentSizes);
                }
            }
        }

        StringBuilder sb = new StringBuilder();
        Set<Integer> visitedComponents = new HashSet<>(4);

        // Calculate and output results for each cell
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == EMPTY_CELL) {
                    sb.append(EMPTY_CELL);
                } else {
                    visitedComponents.clear();
                    int adjacentSum = 1;
                    for (int[] dir : DIRECTIONS) {
                        int ni = i + dir[0];
                        int nj = j + dir[1];
                        if (isValid(ni, nj, n, m) && componentIds[ni][nj] > 0) {
                            int compId = componentIds[ni][nj];
                            if (visitedComponents.add(compId)) {
                                adjacentSum += componentSizes[compId];
                            }
                        }
                    }
                    sb.append(adjacentSum % MODULO);
                }
            }
            out.println(sb);
            sb.setLength(0); // Clear buffer for the next row
        }
    }

    /**
     * Performs iterative Depth-First Search to label connected components.
     * Uses an explicit stack to prevent StackOverflowError on large grids.
     */
    private static void dfs(int startX, int startY, int compId, int n, int m, char[][] grid,
                            int[][] componentIds, int[] componentSizes) {
        int[] stackX = new int[n * m];
        int[] stackY = new int[n * m];
        int top = 0;

        stackX[top] = startX;
        stackY[top] = startY;
        componentIds[startX][startY] = compId;
        componentSizes[compId]++;
        top++;

        while (top > 0) {
            top--;
            int x = stackX[top];
            int y = stackY[top];

            for (int[] dir : DIRECTIONS) {
                int nx = x + dir[0];
                int ny = y + dir[1];
                if (isValid(nx, ny, n, m) && grid[nx][ny] == EMPTY_CELL && componentIds[nx][ny] == 0) {
                    componentIds[nx][ny] = compId;
                    componentSizes[compId]++;
                    stackX[top] = nx;
                    stackY[top] = ny;
                    top++;
                }
            }
        }
    }

    /**
     * Checks if coordinates are within grid boundaries.
     */
    private static boolean isValid(int x, int y, int n, int m) {
        return x >= 0 && x < n && y >= 0 && y < m;
    }

    /**
     * Fast input reader optimized for competitive programming environments.
     */
    static class InputReader {
        public BufferedReader reader;
        public StringTokenizer tokenizer;

        public InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) {
                        throw new IOException("End of stream reached unexpectedly");
                    }
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Input reading failed", e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.PrintWriter;
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Queue;
import java.util.Scanner;
import java.util.Set;

public class TheLabyrinth {
    // Direction vectors for moving up, down, left, right
    private static final int[] DX = {1, -1, 0, 0};
    private static final int[] DY = {0, 0, 1, -1};

    public static void main(String[] args) {
        // Use try-with-resources for automatic and safe resource management
        try (Scanner sc = new Scanner(System.in);
             PrintWriter out = new PrintWriter(System.out)) {

            if (!sc.hasNextInt()) {
                return;
            }

            int n = sc.nextInt();
            int m = sc.nextInt();
            sc.nextLine(); // Consume the newline character remaining after nextInt()

            char[][] grid = readGrid(sc, n, m);
            int[][] colors = new int[n][m];
            int[][] sizes = new int[n][m];
            int currentColor = 1;

            // Identify connected components, assign colors, and calculate sizes
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    if (grid[i][j] != '*' && colors[i][j] == 0) {
                        bfs(grid, colors, sizes, i, j, currentColor);
                        currentColor++;
                    }
                }
            }

            printResult(grid, colors, sizes, n, m, out);
            out.flush(); // Ensure all output is written before closing
        }
    }

    /**
     * Reads the grid from the scanner input.
     */
    private static char[][] readGrid(Scanner sc, int n, int m) {
        char[][] grid = new char[n][m];
        for (int i = 0; i < n; i++) {
            String line = sc.nextLine();
            // Safely copy characters, handling potential line length mismatches
            for (int j = 0; j < Math.min(m, line.length()); j++) {
                grid[i][j] = line.charAt(j);
            }
        }
        return grid;
    }

    /**
     * Iteratively traverses a connected component using BFS.
     * Assigns a unique color to all cells and records the component size.
     * Using iteration prevents StackOverflowError on large grids.
     */
    private static void bfs(char[][] grid, int[][] colors, int[][] sizes, 
                            int startI, int startJ, int color) {
        int n = grid.length;
        int m = grid[0].length;
        int count = 0;
        List<int[]> componentCells = new ArrayList<>();

        Queue<int[]> queue = new ArrayDeque<>();
        queue.offer(new int[]{startI, startJ});
        colors[startI][startJ] = color;
        componentCells.add(new int[]{startI, startJ});

        while (!queue.isEmpty()) {
            int[] curr = queue.poll();
            count++;

            for (int k = 0; k < 4; k++) {
                int ni = curr[0] + DX[k];
                int nj = curr[1] + DY[k];

                if (ni >= 0 && ni < n && nj >= 0 && nj < m &&
                    grid[ni][nj] != '*' && colors[ni][nj] == 0) {
                    colors[ni][nj] = color;
                    queue.offer(new int[]{ni, nj});
                    componentCells.add(new int[]{ni, nj});
                }
            }
        }

        // Assign the total component size to every cell in this component
        for (int[] cell : componentCells) {
            sizes[cell[0]][cell[1]] = count;
        }
    }

    /**
     * Generates the output grid based on component sizes adjacent to walls.
     */
    private static void printResult(char[][] grid, int[][] colors, int[][] sizes, 
                                    int n, int m, PrintWriter out) {
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == '*') {
                    Set<Integer> adjacentColors = new HashSet<>();
                    int sum = 0;

                    for (int k = 0; k < 4; k++) {
                        int ni = i + DX[k];
                        int nj = j + DY[k];

                        if (ni >= 0 && ni < n && nj >= 0 && nj < m && colors[ni][nj] > 0) {
                            // add() returns true only if the color was not already present
                            if (adjacentColors.add(colors[ni][nj])) {
                                sum += sizes[ni][nj];
                            }
                        }
                    }
                    out.print((sum + 1) % 10);
                } else {
                    out.print('.');
                }
            }
            out.println();
        }
    }
}

import java.io.*;
import java.util.*;

public class Main {
    // State fields
    private int rows;
    private int cols;
    private char[][] grid;
    private int[][] regionIds;
    private int[] regionSizes;
    private int regionCount = 0;

    // Direction vectors for neighbors (Up, Down, Left, Right)
    private static final int[] DR = {-1, 1, 0, 0};
    private static final int[] DC = {0, 0, -1, 1};

    public static void main(String[] args) {
        // Initialize I/O streams
        FastScanner in = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out));

        // Instantiate and run the solver
        new Main(in, out).solve();

        // Ensure all output is written
        out.flush();
        out.close();
    }

    private final FastScanner in;
    private final PrintWriter out;

    public Main(FastScanner in, PrintWriter out) {
        this.in = in;
        this.out = out;
    }

    private void solve() {
        // Read dimensions
        if (!in.hasNext()) return;
        try {
            rows = in.nextInt();
            cols = in.nextInt();
        } catch (Exception e) {
            return;
        }

        // Read Grid
        grid = new char[rows][];
        for (int i = 0; i < rows; i++) {
            grid[i] = in.next().toCharArray();
        }

        // Initialize Data Structures
        // regionIds[r][c] stores the ID of the connected component '.' belongs to
        regionIds = new int[rows][cols];
        // regionSizes[id] stores the size of component with ID 'id'
        // Max possible ID is bounded by rows * cols
        regionSizes = new int[rows * cols + 1];

        // 1. Identify Connected Components (Flood Fill)
        // Using Iterative BFS to prevent StackOverflowError on large grids
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '.' && regionIds[r][c] == 0) {
                    regionCount++;
                    bfs(r, c, regionCount);
                }
            }
        }

        // 2. Generate Output
        // Logic: Print '.' for empty cells, (sum + 1) % 10 for '*' cells
        for (int r = 0; r < rows; r++) {
            StringBuilder sb = new StringBuilder();
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '.') {
                    sb.append('.');
                } else {
                    // Calculate sum of sizes of adjacent regions
                    int sum = calculateAdjacentRegionSum(r, c);
                    sb.append((sum + 1) % 10);
                }
            }
            out.println(sb);
        }
    }

    /**
     * Iterative Breadth-First Search to find connected components of '.' cells.
     * Replaces recursive DFS to handle deep recursion depths safely.
     */
    private void bfs(int startR, int startC, int id) {
        // Queue stores encoded coordinates: r * cols + c
        Queue<Integer> queue = new ArrayDeque<>();
        queue.add(startR * cols + startC);

        regionIds[startR][startC] = id;
        int size = 0;

        while (!queue.isEmpty()) {
            int current = queue.poll();
            int r = current / cols;
            int c = current % cols;
            size++;

            for (int i = 0; i < 4; i++) {
                int nr = r + DR[i];
                int nc = c + DC[i];

                if (isValid(nr, nc) && grid[nr][nc] == '.' && regionIds[nr][nc] == 0) {
                    regionIds[nr][nc] = id;
                    queue.add(nr * cols + nc);
                }
            }
        }
        regionSizes[id] = size;
    }

    /**
     * Calculates the sum of sizes of unique connected regions adjacent to the cell at (r, c).
     * Optimized to avoid object allocation (no HashSet) by using a fixed-size array.
     */
    private int calculateAdjacentRegionSum(int r, int c) {
        int sum = 0;
        // Maximum 4 neighbors, so we can track seen IDs in a small array
        int[] seenIds = new int[4];
        int seenCount = 0;

        for (int i = 0; i < 4; i++) {
            int nr = r + DR[i];
            int nc = c + DC[i];

            if (isValid(nr, nc) && grid[nr][nc] == '.') {
                int neighborRegionId = regionIds[nr][nc];

                // Check if this region ID has already been counted for this cell
                boolean alreadyCounted = false;
                for (int k = 0; k < seenCount; k++) {
                    if (seenIds[k] == neighborRegionId) {
                        alreadyCounted = true;
                        break;
                    }
                }

                if (!alreadyCounted) {
                    seenIds[seenCount++] = neighborRegionId;
                    sum += regionSizes[neighborRegionId];
                }
            }
        }
        return sum;
    }

    /**
     * Checks if coordinates are within grid bounds.
     */
    private boolean isValid(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /**
     * Fast Input Reader to handle large inputs efficiently.
     * Replaces the original InputReader with a more robust implementation.
     */
    public static class FastScanner {
        BufferedReader br;
        StringTokenizer st;

        public FastScanner(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        public boolean hasNext() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return false;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    return false;
                }
            }
            return true;
        }

        public String next() {
            if (hasNext()) return st.nextToken();
            return null;
        }

        public int nextInt() {
            String s = next();
            if (s == null) throw new NoSuchElementException();
            return Integer.parseInt(s);
        }
    }
}

import java.io.BufferedReader;
