import java.util.LinkedList;
import java.util.List;
import java.util.Queue;
import java.util.Set;
import java.util.StringTokenizer;

/**
 * Solves the grid component expansion problem.
 * Reads a grid, identifies connected empty regions, and calculates
 * the combined size of adjacent regions for each obstacle cell.
 */
public class Abood2B {

    private static final int[] DX = {0, 1, 0, -1};
    private static final int[] DY = {1, 0, -1, 0};
    private static final int MODULO = 10;

    public static void main(String[] args) {
        FastScanner sc = new FastScanner(System.in);
        try (PrintWriter out = new PrintWriter(System.out)) {
            String nStr = sc.next();
            if (nStr == null) return;

            int N = Integer.parseInt(nStr);
            int M = sc.nextInt();

            int[][] grid = new int[N][M];
            for (int i = 0; i < N; i++) {
                String row = sc.next();
                for (int j = 0; j < M; j++) {
                    grid[i][j] = (row.charAt(j) == '*') ? 1 : 0;
                }
            }

            int[][] group = new int[N][M];
            for (int[] row : group) {
                Arrays.fill(row, -1);
            }

            List<Integer> componentSizes = new ArrayList<>();
            int componentId = 0;

            // Label connected components of empty cells
            for (int i = 0; i < N; i++) {
                for (int j = 0; j < M; j++) {
                    if (group[i][j] == -1 && grid[i][j] == 0) {
                        int size = bfs(i, j, grid, group, componentId, N, M);
                        componentSizes.add(size);
                        componentId++;
                    }
                }
            }

            // Compute and print results for each obstacle cell
            for (int i = 0; i < N; i++) {
                for (int j = 0; j < M; j++) {
                    if (grid[i][j] == 0) {
                        out.print('.');
                        continue;
                    }

                    int totalSize = 1; // Count the obstacle cell itself
                    Set<Integer> visitedGroups = new HashSet<>();

                    for (int dir = 0; dir < 4; dir++) {
                        int ni = i + DX[dir];
                        int nj = j + DY[dir];
                        if (isValid(ni, nj, N, M) && grid[ni][nj] == 0) {
                            int groupId = group[ni][nj];
                            if (visitedGroups.add(groupId)) {
                                totalSize += componentSizes.get(groupId);
                            }
                        }
                    }
                    out.print(totalSize % MODULO);
                }
                out.println();
            }
        }
    }

    /**
     * Performs BFS to find the size of a connected component.
     * Marks visited cells with the provided component ID.
     */
    private static int bfs(int startX, int startY, int[][] grid, int[][] group, 
                           int componentId, int n, int m) {
        Queue<Point> queue = new LinkedList<>();
        queue.add(new Point(startX, startY));
        group[startX][startY] = componentId;
        int size = 0;

        while (!queue.isEmpty()) {
            Point current = queue.poll();
            size++;
            for (int dir = 0; dir < 4; dir++) {
                int nx = current.x + DX[dir];
                int ny = current.y + DY[dir];
                if (isValid(nx, ny, n, m) && group[nx][ny] == -1 && grid[nx][ny] == 0) {
                    group[nx][ny] = componentId;
                    queue.add(new Point(nx, ny));
                }
            }
        }
        return size;
    }

    private static boolean isValid(int x, int y, int n, int m) {
        return x >= 0 && x < n && y >= 0 && y < m;
    }

    /** Lightweight coordinate class to avoid AWT dependency. */
    private static class Point {
        final int x;
        final int y;
        Point(int x, int y) {
            this.x = x;
            this.y = y;
        }
    }

    /** Fast input reader for competitive programming style tasks. */
    private static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input", e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            String s = next();
            return s == null ? 0 : Integer.parseInt(s);
        }
    }
}

