/**
 * Solves the grid connectivity and component size problem.
 */
class Solution {
    // Directions for moving up, down, left, right
    private static final int[][] DIRECTIONS = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};
    private static final int MODULO = 10;

    public void solve(FastScanner in, FastPrinter out) {
        int rows = in.nextInt();
        int cols = in.nextInt();

        char[][] grid = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            grid[i] = in.next().toCharArray();
        }

        // componentId[r][c] stores the ID of the component if grid[r][c] == '.', else 0
        int[][] componentId = new int[rows][cols];

        // componentSizes.get(id) stores the size of the component with that ID.
        // Index 0 is unused to align IDs (1-based) with list indices.
        List<Integer> componentSizes = new ArrayList<>();
        componentSizes.add(0); 

        int currentId = 1;

        // 1. Identify connected components of '.' cells
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '.' && componentId[r][c] == 0) {
                    int size = bfs(r, c, grid, componentId, currentId, rows, cols);
                    componentSizes.add(size);
                    currentId++;
                }
            }
        }

        // 2. Process '*' cells to calculate connected component sums
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '*') {
                    Set<Integer> neighborComponentIds = new HashSet<>();

                    // Check all 4 neighbors
                    for (int[] dir : DIRECTIONS) {
                        int nr = r + dir[0];
                        int nc = c + dir[1];

                        if (isInside(nr, nc, rows, cols) && grid[nr][nc] == '.') {
                            // Since we processed all '.' before, componentId is already set
                            neighborComponentIds.add(componentId[nr][nc]);
                        }
                    }

                    int total = 1; // Count the '*' cell itself
                    for (int id : neighborComponentIds) {
                        total += componentSizes.get(id);
                    }

                    out.print(total % MODULO);
                } else {
                    out.print(".");
                }
            }
            out.printLine();
        }
    }

    /**
     * Performs BFS to find the size of the connected component starting at (startR, startC).
     */
    private int bfs(int startR, int startC, char[][] grid, int[][] componentId, int id, int rows, int cols) {
        Queue<Point> queue = new ArrayDeque<>();
        queue.add(new Point(startR, startC));

        // Mark as visited by assigning ID immediately to prevent duplicates
        componentId[startR][startC] = id;

        int size = 0;
        while (!queue.isEmpty()) {
            Point current = queue.poll();
            size++;

            for (int[] dir : DIRECTIONS) {
                int nr = current.x + dir[0];
                int nc = current.y + dir[1];

                if (isInside(nr, nc, rows, cols) && grid[nr][nc] == '.' && componentId[nr][nc] == 0) {
                    componentId[nr][nc] = id;
                    queue.add(new Point(nr, nc));
                }
            }
        }
        return size;
    }

    private boolean isInside(int r, int c, int rows, int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }
}

