import java.io.*;
import java.util.*;

/**
 * Analyzes a grid to find connected components and calculates the size of 
 * the merged component if each wall cell were converted to an open cell.
 */
public class Main {
    // Direction vectors for moving up, down, left, right
    private static final int[] DR = {1, -1, 0, 0};
    private static final int[] DC = {0, 0, 1, -1};

    public static void main(String[] args) throws IOException {
        InputReader reader = new InputReader(System.in);

        int rows = Integer.parseInt(reader.next());
        int cols = Integer.parseInt(reader.next());

        boolean[][] grid = new boolean[rows][cols];
        for (int r = 0; r < rows; r++) {
            String line = reader.next();
            for (int c = 0; c < cols; c++) {
                grid[r][c] = line.charAt(c) == '.';
            }
        }

        // Encapsulate algorithm logic in a dedicated solver class
        GridSolver solver = new GridSolver(rows, cols, grid);
        solver.solve();
    }

    /**
     * Encapsulates all state and logic for component analysis and output generation.
     */
    private static class GridSolver {
        private final int rows, cols;
        private final boolean[][] grid;
        private final int[][] componentId;
        private final int[] componentSize;
        private final StringBuilder output;
        private final Set<Integer> adjacentComponents = new HashSet<>(); // Reused to avoid allocation overhead

        public GridSolver(int rows, int cols, boolean[][] grid) {
            this.rows = rows;
            this.cols = cols;
            this.grid = grid;
            this.componentId = new int[rows][cols];
            // Max possible components = total cells. Index 0 is unused.
            this.componentSize = new int[rows * cols + 1];
            this.output = new StringBuilder();
        }

        public void solve() {
            int componentCount = 0;
            // Step 1: Label connected components using BFS
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] && componentId[r][c] == 0) {
                        componentCount++;
                        bfs(r, c, componentCount);
                    }
                }
            }

            // Step 2: Compute output grid
            computeOutput();
            System.out.print(output);
        }

        private void bfs(int startR, int startC, int compId) {
            Queue<Integer> queue = new ArrayDeque<>();
            queue.add(pack(startR, startC));
            componentId[startR][startC] = compId;
            componentSize[compId]++;

            while (!queue.isEmpty()) {
                int curr = queue.poll();
                int r = curr / cols;
                int c = curr % cols;

                for (int i = 0; i < 4; i++) {
                    int nr = r + DR[i];
                    int nc = c + DC[i];
                    // componentId == 0 acts as both visited flag and unassigned marker
                    if (isValid(nr, nc) && grid[nr][nc] && componentId[nr][nc] == 0) {
                        componentId[nr][nc] = compId;
                        componentSize[compId]++;
                        queue.add(pack(nr, nc));
                    }
                }
            }
        }

        private void computeOutput() {
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c]) {
                        output.append('.');
                    } else {
                        int totalSize = 1; // Count the cell itself
                        adjacentComponents.clear();

                        // Identify unique adjacent components
                        for (int i = 0; i < 4; i++) {
                            int nr = r + DR[i];
                            int nc = c + DC[i];
                            if (isValid(nr, nc) && grid[nr][nc]) {
                                adjacentComponents.add(componentId[nr][nc]);
                            }
                        }
                        // Sum sizes of unique adjacent components
                        for (int compId : adjacentComponents) {
                            totalSize += componentSize[compId];
                        }
                        output.append(totalSize % 10);
                    }
                }
                output.append('\n');
            }
        }

        private boolean isValid(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }

        /**
         * Packs 2D coordinates into a single integer to reduce memory and avoid boxing.
         */
        private int pack(int r, int c) {
            return r * cols + c;
        }
    }

    /**
     * Fast I/O utility for reading whitespace-delimited tokens.
     */
    private static class InputReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public InputReader(InputStream stream) {
            this.reader = new BufferedReader(new InputStreamReader(stream), 32768);
            this.tokenizer = new StringTokenizer("");
        }

        public String next() throws IOException {
            while (!tokenizer.hasMoreTokens()) {
                String line = reader.readLine();
                if (line == null) {
                    throw new EOFException("End of input stream reached.");
                }
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }
    }
}

import java.io.BufferedReader;
import java.io.Closeable;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.Arrays;
import java.util.StringTokenizer;

/**
 * Solves the labyrinth problem using Disjoint Set Union (DSU) to manage connected components.
 * Refactored for improved maintainability, readability, and encapsulation.
 */
public class TheLabyrinth implements Closeable {

    private final InputReader in;
    private final PrintWriter out;

    public TheLabyrinth() {
        this.in = new InputReader(System.in);
        this.out = new PrintWriter(System.out);
    }

    public void solve() {
        // Read grid dimensions
        String nStr = in.next();
        if (nStr == null) return;
        int n = Integer.parseInt(nStr);

        String mStr = in.next();
        if (mStr == null) return;
        int m = Integer.parseInt(mStr);

        // Read the grid
        char[][] grid = new char[n][m];
        for (int i = 0; i < n; i++) {
            String row = in.next();
            if (row != null) {
                grid[i] = row.toCharArray();
            }
        }

        // Initialize Disjoint Set Union
        // Each cell is a node in the DSU
        DisjointSet dsu = new DisjointSet(n * m);

        // First pass: Connect adjacent '.' cells
        // We only need to check Right and Down neighbors to cover all edges efficiently
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == '.') {
                    // Check Right neighbor
                    if (j + 1 < m && grid[i][j + 1] == '.') {
                        dsu.union(i * m + j, i * m + j + 1);
                    }
                    // Check Down neighbor
                    if (i + 1 < n && grid[i + 1][j] == '.') {
                        dsu.union(i * m + j, i * m + j + m);
                    }
                }
            }
        }

        // Directions: Up, Down, Left, Right
        int[] dr = {-1, 1, 0, 0};
        int[] dc = {0, 0, -1, 1};

        // Second pass: Calculate values for non-'.' cells (walls)
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == '.') {
                    continue;
                }

                int totalSize = 0;
                int[] neighborRoots = new int[4];
                int uniqueRootCount = 0;

                // Check all 4 neighbors
                for (int d = 0; d < 4; d++) {
                    int r = i + dr[d];
                    int c = j + dc[d];

                    // Check bounds
                    if (r >= 0 && r < n && c >= 0 && c < m) {
                        if (grid[r][c] == '.') {
                            int root = dsu.find(r * m + c);

                            // Check if this root is already counted for the current cell
                            boolean isDuplicate = false;
                            for (int k = 0; k < uniqueRootCount; k++) {
                                if (neighborRoots[k] == root) {
                                    isDuplicate = true;
                                    break;
                                }
                            }

                            if (!isDuplicate) {
                                neighborRoots[uniqueRootCount++] = root;
                                totalSize += dsu.getSize(root);
                            }
                        }
                    }
                }

                // Update the cell character based on the sum of sizes of adjacent components
                // Logic: (1 + totalSize) % 10
                grid[i][j] = (char) ('0' + (1 + totalSize) % 10);
            }
        }

        // Output the resulting grid
        for (int i = 0; i < n; i++) {
            out.println(grid[i]);
        }
    }

    @Override
    public void close() throws IOException {
        in.close();
        out.flush(); // Ensure all output is written
        out.close();
    }

    /**
     * Disjoint Set Union (DSU) implementation with path compression and union by size.
     * Note: The original code used 'rank' but tracked size (initialized to 1, added on union).
     * Renamed to 'size' for semantic correctness.
     */
    static class DisjointSet {
        private final int[] parent;
        private final int[] size;

        public DisjointSet(int n) {
            parent = new int[n];
            size = new int[n];
            for (int i = 0; i < n; i++) {
                parent[i] = i;
                size[i] = 1;
            }
        }

        /**
         * Finds the representative (root) of the set containing x with path compression.
         */
        public int find(int x) {
            if (parent[x] != x) {
                parent[x] = find(parent[x]); // Path compression
            }
            return parent[x];
        }

        /**
         * Unites the sets containing x and y.
         */
        public void union(int x, int y) {
            int rootX = find(x);
            int rootY = find(y);

            if (rootX != rootY) {
                // Union by size: attach smaller tree to larger tree
                if (size[rootX] < size[rootY]) {
                    int temp = rootX;
                    rootX = rootY;
                    rootY = temp;
                }
                parent[rootY] = rootX;
                size[rootX] += size[rootY];
            }
        }

        /**
         * Returns the size of the set containing root.
         */
        public int getSize(int root) {
            return size[root];
        }
    }

    /**
     * Fast Input Reader for efficient reading of large inputs.
     */
    static class InputReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null; // End of input
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            String s = next();
            if (s == null) throw new RuntimeException("Unexpected end of input");
            return Integer.parseInt(s);
        }

        public long nextLong() {
            String s = next();
            if (s == null) throw new RuntimeException("Unexpected end of input");
            return Long.parseLong(s);
        }

        public void close() throws IOException {
            reader.close();
        }
    }

    public static void main(String[] args) {
        try (TheLabyrinth instance = new TheLabyrinth()) {
            instance.solve();
        } catch (IOException e) {
            e.printStackTrace();
        }
    }
}

import java.util.Scanner;

public class Main {

    public static void main(String[] args) {
        try (Scanner sc = new Scanner(System.in)) {
            Point p1 = new Point(sc.nextInt(), sc.nextInt());
            Point p2 = new Point(sc.nextInt(), sc.nextInt());
            Point p3 = new Point(sc.nextInt(), sc.nextInt());

            System.out.println(determineTriangleType(p1, p2, p3));
        }
    }

    /**
     * Determines the classification of the triangle formed by three points.
     * Returns:
     * 1 - Collinear points
     * 2 - Right-angled or obtuse configuration (based on original logic)
     * 3 - Acute configuration (based on original logic)
     */
    private static int determineTriangleType(Point p1, Point p2, Point p3) {
        // 1: All three points are collinear (share the same x or same y coordinate)
        if ((p1.y == p2.y && p2.y == p3.y) || (p1.x == p2.x && p2.x == p3.x)) {
            return 1;
        }

        // 2: Explicit right angle at p1
        if ((p1.x == p2.x && p1.y == p3.y) || (p1.x == p3.x && p1.y == p2.y)) {
            return 2;
        }

        // 3: p1 and p2 share an axis; check if p3 falls outside the segment formed by p1-p2
        if (p1.x == p2.x && p1.x != p3.x && p1.y != p3.y) {
            return isOutsideSegment(p1.y, p2.y, p3.y) ? 2 : 3;
        }
        if (p1.y == p2.y && p1.y != p3.y && p1.x != p3.x) {
            return isOutsideSegment(p1.x, p2.x, p3.x) ? 2 : 3;
        }

        // 4: p1 and p3 share an axis; check if p2 falls outside the segment formed by p1-p3
        if (p1.x == p3.x && p1.x != p2.x && p1.y != p2.y) {
            return isOutsideSegment(p1.y, p3.y, p2.y) ? 2 : 3;
        }
        if (p1.y == p3.y && p1.y != p2.y && p1.x != p2.x) {
            return isOutsideSegment(p1.x, p3.x, p2.x) ? 2 : 3;
        }

        // 5: p2 and p3 are on the same side of p1 in both dimensions
        if ((p2.x > p1.x && p3.x > p1.x && p2.y > p1.y && p3.y > p1.y) ||
            (p2.x < p1.x && p3.x < p1.x && p2.y < p1.y && p3.y < p1.y) ||
            (p2.x > p1.x && p3.x > p1.x && p2.y < p1.y && p3.y < p1.y) ||
            (p2.x < p1.x && p3.x < p1.x && p2.y > p1.y && p3.y > p1.y)) {
            return (p2.x == p3.x || p2.y == p3.y) ? 2 : 3;
        }

        // 6: p2 and p3 are on the same side in at least one dimension
        if ((p2.y > p1.y && p3.y > p1.y) || (p2.y < p1.y && p3.y < p1.y) ||
            (p2.x > p1.x && p3.x > p1.x) || (p2.x < p1.x && p3.x < p1.x)) {
            return 3;
        }

        // Default fallback
        return 3;
    }

    /**
     * Checks if coord3 lies outside or on the boundary of the range defined by coord1 and coord2.
     */
    private static boolean isOutsideSegment(int coord1, int coord2, int coord3) {
        return coord3 <= Math.min(coord1, coord2) || coord3 >= Math.max(coord1, coord2);
    }

    /**
     * Simple immutable data class for 2D coordinates.
     */
    private static class Point {
        final int x, y;
        Point(int x, int y) {
            this.x = x;
            this.y = y;
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

public class Main {
    public static void main(String[] args) {
        FastScanner in = new FastScanner();
        PrintWriter out = new PrintWriter(System.out);
        solve(in, out);
        out.flush();
    }

    private static void solve(FastScanner in, PrintWriter out) {
        int x1 = in.nextInt();
        int y1 = in.nextInt();
        int x2 = in.nextInt();
        int y2 = in.nextInt();
        int x3 = in.nextInt();
        int y3 = in.nextInt();

        int result = 3;
        if (isAllPointsOnSameVerticalLine(x1, y1, x2, y2, x3, y3) ||
            isAllPointsOnSameHorizontalLine(x1, y1, x2, y2, x3, y3)) {
            result = 1;
        } else if (arePointsAlignedOnAxisLine(x1, y1, x2, y2, x3, y3)) {
            result = 2;
        }
        out.println(result);
    }

    private static boolean isAllPointsOnSameVerticalLine(int x1, int y1, int x2, int y2, int x3, int y3) {
        return x1 == x2 && x2 == x3;
    }

    private static boolean isAllPointsOnSameHorizontalLine(int x1, int y1, int x2, int y2, int x3, int y3) {
        return y1 == y2 && y2 == y3;
    }

    private static boolean arePointsAlignedOnAxisLine(int x1, int y1, int x2, int y2, int x3, int y3) {
        // Check vertical alignment for each pair
        if (x1 == x2 && (y3 >= Math.max(y1, y2) || y3 <= Math.min(y1, y2))) return true;
        if (x1 == x3 && (y2 >= Math.max(y1, y3) || y2 <= Math.min(y1, y3))) return true;
        if (x2 == x3 && (y1 >= Math.max(y2, y3) || y1 <= Math.min(y2, y3))) return true;

        // Check horizontal alignment for each pair
        if (y1 == y2 && (x3 >= Math.max(x1, x2) || x3 <= Math.min(x1, x2))) return true;
        if (y1 == y3 && (x2 >= Math.max(x1, x3) || x2 <= Math.min(x1, x3))) return true;
        if (y2 == y3 && (x1 >= Math.max(x2, x3) || x1 <= Math.min(x2, x3))) return true;

        return false;
    }

    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.*;
import java.util.StringTokenizer;

public class MinimumSegmentsCalculator {

    public static void main(String[] args) {
        // Use try-with-resources to guarantee proper resource cleanup
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
             PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out))) {

            FastScanner scanner = new FastScanner(br);
            solve(scanner, out);
            out.flush();

        } catch (IOException e) {
            // Properly handle and log exceptions instead of swallowing them
            e.printStackTrace();
        }
    }

    /**
     * Orchestrates input reading and problem solving.
     */
    private static void solve(FastScanner scanner, PrintWriter out) throws IOException {
        long ax = scanner.nextLong();
        long ay = scanner.nextLong();
        long bx = scanner.nextLong();
        long by = scanner.nextLong();
        long cx = scanner.nextLong();
        long cy = scanner.nextLong();

        out.print(calculateMinSegments(ax, ay, bx, by, cx, cy));
    }

    /**
     * Determines the minimum number of axis-aligned line segments required to connect three points.
     * <p>
     * Returns:
     * 1 - if all three points are collinear (share the same X or Y coordinate)
     * 2 - if two segments are sufficient (two points share an axis and the third lies outside their range)
     * 3 - otherwise
     */
    static int calculateMinSegments(long ax, long ay, long bx, long by, long cx, long cy) {
        // Check if all three points are collinear
        boolean collinearX = (ax == bx && ax == cx);
        boolean collinearY = (ay == by && ay == cy);
        if (collinearX || collinearY) {
            return 1;
        }

        // Check if two points share an axis and the third lies outside their bounding range
        boolean canBeCoveredByTwoSegments = false;

        if (ax == bx) {
            canBeCoveredByTwoSegments |= (cy <= Math.min(ay, by) || cy >= Math.max(ay, by));
        }
        if (ax == cx) {
            canBeCoveredByTwoSegments |= (by <= Math.min(ay, cy) || by >= Math.max(ay, cy));
        }
        if (ay == by) {
            canBeCoveredByTwoSegments |= (cx <= Math.min(ax, bx) || cx >= Math.max(ax, bx));
        }
        if (ay == cy) {
            canBeCoveredByTwoSegments |= (bx <= Math.min(ax, cx) || bx >= Math.max(ax, cx));
        }
        if (bx == cx) {
            canBeCoveredByTwoSegments |= (ay <= Math.min(by, cy) || ay >= Math.max(by, cy));
        }
        if (by == cy) {
            canBeCoveredByTwoSegments |= (ax <= Math.min(bx, cx) || ax >= Math.max(bx, cx));
        }

        return canBeCoveredByTwoSegments ? 2 : 3;
    }

    /**
     * Efficient input scanner for fast I/O scenarios.
     */
    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner(BufferedReader br) {
            this.br = br;
        }

        public String next() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) {
                    throw new IOException("Unexpected end of input stream.");
                }
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

        public long nextLong() throws IOException {
            return Long.parseLong(next());
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Main entry point for the competitive programming solution.
 * Handles input parsing, core logic, and output formatting.
 */
public class Main {
    public static void main(String[] args) {
        // try-with-resources ensures automatic and safe closure of I/O streams
        try (FastScanner in = new FastScanner();
             OutputWriter out = new OutputWriter()) {
            new Main().solve(in, out);
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    /**
     * Core algorithm to determine the minimum number of lines to cover 3 points.
     */
    void solve(FastScanner in, OutputWriter out) throws IOException {
        int[] x = new int[3];
        int[] y = new int[3];
        for (int i = 0; i < 3; i++) {
            x[i] = in.nextInt();
            y[i] = in.nextInt();
        }

        // If all points share the same x or same y coordinate, 1 line suffices
        if (x[0] == x[1] && x[1] == x[2] || y[0] == y[1] && y[1] == y[2]) {
            out.println(1);
            return;
        }

        int res = 3;
        // Check all pairs to see if a second line can cover the third point
        for (int i = 0; i < 3; i++) {
            for (int j = i + 1; j < 3; j++) {
                int k = 3 - i - j;
                if (x[i] == x[j]) {
                    int minY = Math.min(y[i], y[j]);
                    int maxY = Math.max(y[i], y[j]);
                    if (isOutsideSegment(minY, maxY, y[k])) res = 2;
                } else if (y[i] == y[j]) {
                    int minX = Math.min(x[i], x[j]);
                    int maxX = Math.max(x[i], x[j]);
                    if (isOutsideSegment(minX, maxX, x[k])) res = 2;
                }
            }
        }
        out.println(res);
    }

    /**
     * Checks if a value lies strictly outside the closed interval [lower, upper].
     */
    private boolean isOutsideSegment(int lower, int upper, int value) {
        return value <= lower || upper <= value;
    }

    // ==================== UTILITY CLASSES ====================

    /**
     * High-performance input reader for competitive programming.
     */
    class FastScanner {
        private final BufferedReader in;
        private int c = -2;

        public FastScanner() throws IOException {
            in = new BufferedReader(new InputStreamReader(System.in));
        }

        public FastScanner(String filename) throws IOException {
            in = new BufferedReader(new InputStreamReader(new FileInputStream(filename)));
        }

        public String nextToken() throws IOException {
            StringBuilder sb = new StringBuilder();
            while ((c = in.read()) != -1 && Character.isWhitespace(c));
            while (c != -1 && !Character.isWhitespace(c)) {
                sb.append((char) c);
                c = in.read();
            }
            return sb.toString();
        }

        public String readLine() throws IOException {
            StringBuilder sb = new StringBuilder();
            if (c == -2) c = in.read();
            while (c != -1 && c != '\n' && c != '\r') {
                sb.append((char) c);
                c = in.read();
            }
            return sb.toString();
        }

        public long nextLong() throws IOException, NumberFormatException {
            return Long.parseLong(nextToken());
        }

        public int nextInt() throws IOException, NumberFormatException {
            return (int) nextLong();
        }

        public double nextDouble() throws IOException, NumberFormatException {
            return Double.parseDouble(nextToken());
        }

        public void close() throws IOException {
            in.close();
        }
    }

    /**
     * Buffered output writer extending PrintWriter for fast I/O.
     */
    class OutputWriter extends PrintWriter {
        public OutputWriter(String filename) throws IOException {
            super(new BufferedWriter(new FileWriter(filename)));
        }

        public OutputWriter() throws IOException {
            super(System.out);
        }
    }

    /**
     * Generic Segment Tree supporting both minimum and maximum queries.
     * Returns a packed long: (index << 32) | value.
     */
    class SegmentTree<T> {
        private final int size;
        private final T[] tree;
        private final int[] idx;
        private final Comparator<T> comparator;
        private final T identity;

        @SuppressWarnings("unchecked")
        public SegmentTree(int n, T identity, Comparator<T> comparator) {
            this.identity = identity;
            this.comparator = comparator;
            int size = 1;
            while (size < n) size <<= 1;
            this.size = size;
            this.tree = (T[]) new Object[size << 1];
            this.idx = new int[size << 1];
            Arrays.fill(this.tree, identity);
            Arrays.fill(this.idx, -1);
        }

        public void set(int id, T value) {
            int i = id + size;
            tree[i] = value;
            idx[i] = id;
            for (i >>= 1; i > 0; i >>= 1) {
                T left = tree[i << 1];
                T right = tree[(i << 1) + 1];
                if (comparator.compare(left, right) <= 0) {
                    tree[i] = left;
                    idx[i] = idx[i << 1];
                } else {
                    tree[i] = right;
                    idx[i] = idx[(i << 1) + 1];
                }
            }
        }

        public T get(int id) {
            return tree[id + size];
        }

        public long query(int left, int right) {
            T res = identity;
            int resIdx = -1;
            left += size;
            right += size + 1;
            while (left < right) {
                if ((right & 1) == 1) {
                    right--;
                    if (comparator.compare(tree[right], res) < 0) {
                        res = tree[right];
                        resIdx = idx[right];
                    }
                }
                if ((left & 1) == 1) {
                    if (comparator.compare(tree[left], res) < 0) {
                        res = tree[left];
                        resIdx = idx[left];
                    }
                    left++;
                }
                left >>= 1;
                right >>= 1;
            }
            return ((long) resIdx << 32) | (res instanceof Integer ? ((Integer) res) : 0);
        }
    }

    /**
     * Generic MultiSet supporting both HashMap (unordered) and TreeMap (ordered) backends.
     */
    class MultiSet<K> {
        private final Map<K, Integer> map;

        public MultiSet() {
            this.map = new HashMap<>();
        }

        public MultiSet(Comparator<? super K> comparator) {
            this.map = new TreeMap<>(comparator);
        }

        public Integer get(Object key) {
            return map.getOrDefault(key, 0);
        }

        public void add(K key, int v) {
            map.merge(key, v, Integer::sum);
        }

        public void add(K key) {
            add(key, 1);
        }

        public void sub(K key) {
            int v = get(key);
            if (v == 1) map.remove(key);
            else if (v > 1) map.put(key, v - 1);
        }

        public boolean containsKey(K key) {
            return map.containsKey(key);
        }

        public Set<K> keySet() {
            return map.keySet();
        }
    }

    /**
     * Immutable Pair class with correct equals/hashCode implementation.
     */
    class Pair implements Comparable<Pair> {
        final int a, b;

        Pair(int a, int b) {
            this.a = a;
            this.b = b;
        }

        @Override
        public boolean equals(Object obj) {
            if (this == obj) return true;
            if (!(obj instanceof Pair)) return false;
            Pair other = (Pair) obj;
            return a == other.a && b == other.b;
        }

        @Override
        public int hashCode() {
            return Objects.hash(a, b);
        }

        @Override
        public int compareTo(Pair o) {
            if (a != o.a) return Integer.compare(a, o.a);
            return Integer.compare(b, o.b);
        }
    }

    /**
     * Utility class for timing operations.
     */
    class Timer {
        private long startTime;

        public void start() {
            startTime = System.currentTimeMillis();
        }

        public long stop() {
            return System.currentTimeMillis() - startTime;
        }

        public void print() {
            System.out.println("Time: " + stop() + "ms");
        }

        @Override
        public String toString() {
            return "Time: " + stop() + "ms";
        }
    }

    /**
     * Collection of static utility and debugging methods.
     */
    class Utils {
        static void dump(int[] a) {
            for (int val : a) System.out.print(val + " ");
            System.out.println();
        }

        static void dump(int[] a, int width) {
            for (int val : a) System.out.printf("%" + width + "d", val);
            System.out.println();
        }

        static void dump(long[] a) {
            for (long val : a) System.out.print(val + " ");
            System.out.println();
        }

        static void dump(char[] a) {
            for (char c : a) System.out.print(c);
            System.out.println();
        }

        static long pow(long base, int exp) {
            long result = 1;
            while (exp > 0) {
                if ((exp & 1) == 1) result *= base;
                base *= base;
                exp >>= 1;
            }
            return result;
        }

        static String itob(int num, int len) {
            return String.format("%" + len + "s", Integer.toBinaryString(num)).replace(' ', '0');
        }

        static void sort(int[] a) {
            Arrays.sort(a);
        }

        static void swap(int[] a, int i, int j) {
            int temp = a[i];
            a[i] = a[j];
            a[j] = temp;
        }

        static int binarySearchSmallerMax(int[] a, int v) {
            int l = 0, r = a.length - 1, s = 0;
            while (l <= r) {
                int m = (l + r) >>> 1;
                if (a[m] > v) r = m - 1;
                else { l = m + 1; s = m; }
            }
            return a[s] > v ? -1 : s;
        }
    }
}

import java.util.Scanner;

public class Main {
    // Extracted magic number for clarity and maintainability
    private static final long COORDINATE_OFFSET = 1_000_000_000L;

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        // Read coordinates and apply the offset
        long x1 = scanner.nextLong() + COORDINATE_OFFSET;
        long y1 = scanner.nextLong() + COORDINATE_OFFSET;
        long x2 = scanner.nextLong() + COORDINATE_OFFSET;
        long y2 = scanner.nextLong() + COORDINATE_OFFSET;
        long x3 = scanner.nextLong() + COORDINATE_OFFSET;
        long y3 = scanner.nextLong() + COORDINATE_OFFSET;

        System.out.println(determineResult(x1, y1, x2, y2, x3, y3));
    }

    /**
     * Determines the result based on the relative positions of three points.
     * Replaces deeply nested conditionals with early returns and a helper method.
     */
    private static String determineResult(long x1, long y1, long x2, long y2, long x3, long y3) {
        // Check for vertical alignment (same x-coordinate)
        if (x1 == x2) {
            if (x1 == x3) return "1";
            return isBetween(y3, y1, y2) ? "3" : "2";
        }
        if (x1 == x3) {
            return isBetween(y2, y1, y3) ? "3" : "2";
        }
        if (x2 == x3) {
            return isBetween(y1, y2, y3) ? "3" : "2";
        }

        // Check for horizontal alignment (same y-coordinate)
        if (y1 == y2) {
            if (y1 == y3) return "1";
            return isBetween(x3, x1, x2) ? "3" : "2";
        }
        if (y1 == y3) {
            return isBetween(x2, x1, x3) ? "3" : "2";
        }
        if (y2 == y3) {
            return isBetween(x1, x2, x3) ? "3" : "2";
        }

        // Default case when no coordinates align (preserved from original logic)
        return "3";
    }

    /**
     * Checks if a value lies strictly between two other values.
     */
    private static boolean isBetween(long value, long a, long b) {
        long min = Math.min(a, b);
        long max = Math.max(a, b);
        return value > min && value < max;
    }
}

import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            long x1 = scanner.nextLong();
            long y1 = scanner.nextLong();
            long x2 = scanner.nextLong();
            long y2 = scanner.nextLong();
            long x3 = scanner.nextLong();
            long y3 = scanner.nextLong();

            System.out.println(determineRelationship(x1, y1, x2, y2, x3, y3));
        }
    }

    /**
     * Analyzes the geometric relationship between three points.
     * Returns:
     * 1 if all points are collinear (share the same x or y coordinate)
     * 2 if two points share an axis-aligned coordinate but the third is not strictly between them
     * 3 otherwise
     */
    private static int determineRelationship(long x1, long y1, long x2, long y2, long x3, long y3) {
        long[][] points = {{x1, y1}, {x2, y2}, {x3, y3}};

        // Case 1: All points are collinear (share the exact same x or y coordinate)
        if ((x1 == x2 && x1 == x3) || (y1 == y2 && y1 == y3)) {
            return 1;
        }

        // Case 2: Check pairs that share an axis-aligned coordinate
        for (int i = 0; i < 3; i++) {
            for (int j = i + 1; j < 3; j++) {
                int k = 3 - i - j; // Index of the remaining point
                if (points[i][0] == points[j][0]) { // Same x-coordinate
                    return checkBetween(points[i][1], points[j][1], points[k][1]);
                }
                if (points[i][1] == points[j][1]) { // Same y-coordinate
                    return checkBetween(points[i][0], points[j][0], points[k][0]);
                }
            }
        }

        // Case 3: No shared coordinates between any pair
        return 3;
    }

    /**
     * Determines if the target coordinate lies strictly between coord1 and coord2.
     * Returns 3 if strictly between, otherwise returns 2.
     */
    private static int checkBetween(long coord1, long coord2, long target) {
        if (Math.min(coord1, coord2) < target && target < Math.max(coord1, coord2)) {
            return 3;
        }
        return 2;
    }
}

import java.util.Scanner;

public class C339D {

    public static void main(String[] args) {
        // Use try-with-resources to ensure the Scanner is properly closed
        try (Scanner scanner = new Scanner(System.in)) {
            int x1 = scanner.nextInt();
            int y1 = scanner.nextInt();
            int x2 = scanner.nextInt();
            int y2 = scanner.nextInt();
            int x3 = scanner.nextInt();
            int y3 = scanner.nextInt();

            System.out.println(determineMinimumLines(x1, y1, x2, y2, x3, y3));
        }
    }

    /**
     * Determines the minimum number of axis-parallel lines needed to cover three points.
     */
    private static int determineMinimumLines(int x1, int y1, int x2, int y2, int x3, int y3) {
        if (areAllPointsOnSameVerticalLine(x1, x2, x3) || areAllPointsOnSameHorizontalLine(y1, y2, y3)) {
            return 1;
        }

        if (canBeCoveredByTwoLines(x1, y1, x2, y2, x3, y3)) {
            return 2;
        }

        return 3;
    }

    private static boolean areAllPointsOnSameVerticalLine(int x1, int x2, int x3) {
        return x1 == x2 && x2 == x3;
    }

    private static boolean areAllPointsOnSameHorizontalLine(int y1, int y2, int y3) {
        return y1 == y2 && y2 == y3;
    }

    private static boolean canBeCoveredByTwoLines(int x1, int y1, int x2, int y2, int x3, int y3) {
        // Check for L-shape configurations (two points share an axis, the third shares the other axis with one of them)
        if (formsLShape(x1, y1, x2, y2, x3, y3) ||
            formsLShape(x1, y1, x3, y3, x2, y2) ||
            formsLShape(x2, y2, x3, y3, x1, y1)) {
            return true;
        }

        // Check if the third point lies outside or on the boundary of the segment formed by the first two points
        if (x1 == x2 && isThirdPointOutsideOrOnBoundary(y3, y1, y2)) return true;
        if (y1 == y2 && isThirdPointOutsideOrOnBoundary(x3, x1, x2)) return true;

        if (x1 == x3 && isThirdPointOutsideOrOnBoundary(y2, y1, y3)) return true;
        if (y1 == y3 && isThirdPointOutsideOrOnBoundary(x2, x1, x3)) return true;

        if (x2 == x3 && isThirdPointOutsideOrOnBoundary(y1, y2, y3)) return true;
        if (y2 == y3 && isThirdPointOutsideOrOnBoundary(x1, x2, x3)) return true;

        return false;
    }

    private static boolean formsLShape(int xA, int yA, int xB, int yB, int xC, int yC) {
        return xA == xB && xB != xC && (yB == yC || yA == yC);
    }

    private static boolean isThirdPointOutsideOrOnBoundary(int thirdCoord, int coord1, int coord2) {
        int min = Math.min(coord1, coord2);
        int max = Math.max(coord1, coord2);
        return thirdCoord >= max || thirdCoord <= min;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

/**
 * Refactored Main class for geometric point classification.
 * 
 * Improvements made:
 * 1. Resource Management: Used try-with-resources for BufferedReader and PrintWriter.
 * 2. Separation of Concerns: Extracted input parsing and logic evaluation into helper methods.
 * 3. Readability: Introduced a Point class and descriptive variable names.
 * 4. Maintainability: Grouped complex boolean logic into named boolean variables.
 * 5. Cleanup: Removed unused imports and static fields.
 */
public class Main {

    /**
     * Simple immutable class to represent a 2D coordinate point.
     */
    static class Point {
        final int x;
        final int y;

        Point(int x, int y) {
            this.x = x;
            this.y = y;
        }
    }

    public static void main(String[] args) throws IOException {
        // Use try-with-resources to ensure streams are closed automatically
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
             PrintWriter writer = new PrintWriter(System.out)) {

            // Read the three points from standard input
            Point p1 = readPoint(reader);
            Point p2 = readPoint(reader);
            Point p3 = readPoint(reader);

            // Determine the classification based on geometric properties
            int result = classifyPoints(p1, p2, p3);

            // Output the result
            writer.println(result);
            writer.flush(); // Ensure output is written before closing
        }
    }

    /**
     * Reads a single point (x, y) from the input stream.
     * Expects coordinates to be on a single line separated by whitespace.
     */
    private static Point readPoint(BufferedReader reader) throws IOException {
        String line = reader.readLine();
        if (line == null) {
            throw new IOException("Unexpected end of input");
        }

        StringTokenizer tokenizer = new StringTokenizer(line);
        int x = Integer.parseInt(tokenizer.nextToken());
        int y = Integer.parseInt(tokenizer.nextToken());

        return new Point(x, y);
    }

    /**
     * Classifies the geometric relationship between three points.
     * 
     * Logic preserved from original implementation:
     * 1. Returns 1 if all points are collinear vertically or horizontally.
     * 2. Returns 2 if two points share an axis (vertical or horizontal) 
     *    and the third point lies outside the range defined by the pair.
     * 3. Returns 3 otherwise.
     */
    private static int classifyPoints(Point p1, Point p2, Point p3) {
        // Case 1: All x-coordinates are equal OR all y-coordinates are equal
        if ((p1.x == p2.x && p2.x == p3.x) || (p1.y == p2.y && p2.y == p3.y)) {
            return 1;
        }

        // Case 2: Check for specific alignments where the third point is "outside" the range
        // We check pairs of points sharing an axis (x or y)

        // Vertical alignment checks (x coordinates match)
        // Condition: x1==x2 AND y3 is outside [min(y1,y2), max(y1,y2)]
        boolean condV1 = (p1.x == p2.x) && (p3.y >= Math.max(p1.y, p2.y) || p3.y <= Math.min(p1.y, p2.y));
        boolean condV2 = (p1.x == p3.x) && (p2.y >= Math.max(p1.y, p3.y) || p2.y <= Math.min(p1.y, p3.y));
        boolean condV3 = (p2.x == p3.x) && (p1.y >= Math.max(p2.y, p3.y) || p1.y <= Math.min(p2.y, p3.y));

        // Horizontal alignment checks (y coordinates match)
        // Condition: y1==y2 AND x3 is outside [min(x1,x2), max(x1,x2)]
        boolean condH1 = (p1.y == p2.y) && (p3.x >= Math.max(p1.x, p2.x) || p3.x <= Math.min(p1.x, p2.x));
        boolean condH2 = (p1.y == p3.y) && (p2.x >= Math.max(p1.x, p3.x) || p2.x <= Math.min(p1.x, p3.x));
        boolean condH3 = (p2.y == p3.y) && (p1.x >= Math.max(p2.x, p3.x) || p1.x <= Math.min(p2.x, p3.x));

        if (condV1 || condV2 || condV3 || condH1 || condH2 || condH3) {
            return 2;
        }

        return 3;
    }
}

import java.util.Scanner;

public class Main {

    /**
     * Helper class to represent a point with x and y coordinates.
     */
    static class Point {
        int x, y;

        Point(int x, int y) {
            this.x = x;
            this.y = y;
        }
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        // Reading input coordinates
        // Assuming valid input as per standard competitive programming constraints
        if (!scanner.hasNextInt()) {
            scanner.close();
            return;
        }
        int x1 = scanner.nextInt();
        int y1 = scanner.nextInt();
        int x2 = scanner.nextInt();
        int y2 = scanner.nextInt();
        int x3 = scanner.nextInt();
        int y3 = scanner.nextInt();

        Point p1 = new Point(x1, y1);
        Point p2 = new Point(x2, y2);
        Point p3 = new Point(x3, y3);

        int result = classifyTriangle(p1, p2, p3);
        System.out.println(result);

        scanner.close();
    }

    /**
     * Classifies the geometric relationship of three points.
     * 
     * Output Logic:
     * 1: Points are collinear (all on a vertical or horizontal line).
     * 2: Points form a triangle where the third point is outside or on the boundary 
     *    of the projection of an axis-aligned side (Obtuse or Right angle configuration).
     * 3: Points form a triangle where the third point is strictly inside the projection 
     *    of an axis-aligned side (Acute angle configuration), or no axis-aligned sides exist.
     */
    private static int classifyTriangle(Point p1, Point p2, Point p3) {
        // 1. Check for collinearity on axis-aligned lines
        // If all x-coordinates are the same, points are on a vertical line.
        if (p1.x == p2.x && p2.x == p3.x) {
            return 1;
        }
        // If all y-coordinates are the same, points are on a horizontal line.
        if (p1.y == p2.y && p2.y == p3.y) {
            return 1;
        }

        // 2. Check if any pair of points forms an axis-aligned segment.
        // We check pairs (p1, p2), (p2, p3), and (p1, p3).
        // If a segment is axis-aligned, we determine the classification based on 
        // the position of the third point relative to that segment.

        // Check Pair 1: p1 and p2
        int result = checkAxisAlignedSegment(p1, p2, p3);
        if (result != -1) return result;

        // Check Pair 2: p2 and p3
        result = checkAxisAlignedSegment(p2, p3, p1);
        if (result != -1) return result;

        // Check Pair 3: p1 and p3
        result = checkAxisAlignedSegment(p1, p3, p2);
        if (result != -1) return result;

        // 3. If no axis-aligned segments were found, the default output is 3.
        return 3;
    }

    /**
     * Checks if the segment between pA and pB is horizontal or vertical.
     * If so, determines the result based on the position of pC.
     * 
     * Returns:
     * 3 if pC is strictly inside the range defined by the segment.
     * 2 if pC is outside or on the boundary of the range.
     * -1 if the segment is diagonal (neither horizontal nor vertical).
     */
    private static int checkAxisAlignedSegment(Point pA, Point pB, Point pC) {
        // Check for Horizontal Segment (y coordinates are equal)
        if (pA.y == pB.y) {
            int min = Math.min(pA.x, pB.x);
            int max = Math.max(pA.x, pB.x);

            // If pC.x is strictly between min and max, it's an acute configuration (3).
            // If pC.x is outside or on the boundary, it's obtuse/right (2).
            if (pC.x > min && pC.x < max) {
                return 3;
            } else {
                return 2;
            }
        }
        // Check for Vertical Segment (x coordinates are equal)
        else if (pA.x == pB.x) {
            int min = Math.min(pA.y, pB.y);
            int max = Math.max(pA.y, pB.y);

            // If pC.y is strictly between min and max, it's an acute configuration (3).
            // If pC.y is outside or on the boundary, it's obtuse/right (2).
            if (pC.y > min && pC.y < max) {
                return 3;
            } else {
                return 2;
            }
        }

        // Segment is diagonal (neither horizontal nor vertical)
        return -1;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.HashSet;
import java.util.Set;
import java.util.StringTokenizer;

public class Main {

    public static void main(String[] args) {
        InputReader in = new InputReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            int[] x = new int[3];
            int[] y = new int[3];
            for (int i = 0; i < 3; i++) {
                x[i] = in.nextInt();
                y[i] = in.nextInt();
            }

            int result = calculateAnswer(x, y);
            out.println(result);
        } finally {
            out.flush();
            out.close();
        }
    }

    /**
     * Calculates the answer based on the number of distinct x and y coordinates,
     * applying a geometric configuration check when applicable.
     */
    private static int calculateAnswer(int[] x, int[] y) {
        int distinctX = countDistinctValues(x);
        int distinctY = countDistinctValues(y);
        int ans = Math.min(distinctX, distinctY);

        // Apply special condition only when exactly one coordinate axis has 2 distinct values
        if (ans == 2) {
            if ((distinctX == 2 && distinctY != 2) || (distinctX != 2 && distinctY == 2)) {
                if (isStrictlyBetweenConfiguration(x, y)) {
                    ans = 3;
                }
            }
        }
        return ans;
    }

    /**
     * Counts the number of distinct values in the given array.
     */
    private static int countDistinctValues(int[] arr) {
        Set<Integer> distinct = new HashSet<>();
        for (int value : arr) {
            distinct.add(value);
        }
        return distinct.size();
    }

    /**
     * Checks if the three points form a configuration where two share an axis coordinate
     * and the third point's coordinate lies strictly between them.
     */
    private static boolean isStrictlyBetweenConfiguration(int[] x, int[] y) {
        // Check vertical alignment (same x)
        if (x[0] == x[1] && isStrictlyBetween(y[2], y[0], y[1])) return true;
        if (x[0] == x[2] && isStrictlyBetween(y[1], y[0], y[2])) return true;
        if (x[1] == x[2] && isStrictlyBetween(y[0], y[1], y[2])) return true;

        // Check horizontal alignment (same y)
        if (y[0] == y[1] && isStrictlyBetween(x[2], x[0], x[1])) return true;
        if (y[0] == y[2] && isStrictlyBetween(x[1], x[0], x[2])) return true;
        if (y[1] == y[2] && isStrictlyBetween(x[0], x[1], x[2])) return true;

        return false;
    }

    /**
     * Returns true if value is strictly between lower and upper bounds.
     */
    private static boolean isStrictlyBetween(int value, int lower, int upper) {
        return value > Math.min(lower, upper) && value < Math.max(lower, upper);
    }

    /**
     * Fast input reader for competitive programming / large I/O.
     */
    static class InputReader {
        public final BufferedReader reader;
        public StringTokenizer tokenizer;

        public InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) {
                        throw new IOException("End of stream reached unexpectedly");
                    }
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public boolean hasNext() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) {
                        return false;
                    }
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return true;
        }
    }
}

import java.util.Arrays;
import java.util.Scanner;

/**
 * Classifies a triangle formed by three coordinate points into one of three categories.
 * 
 * Output 1: Points are collinear (vertical or horizontal alignment)
 * Output 2: Points form a right-angled triangle, an obtuse-corner configuration, 
 *           or specific axis-aligned L-shapes
 * Output 3: Otherwise (acute or general triangles)
 */
public class TriangleTypeClassifier {

    public static void main(String[] args) {
        // Use try-with-resources to ensure the Scanner is properly closed
        try (Scanner scanner = new Scanner(System.in)) {
            if (!scanner.hasNextInt()) {
                return;
            }

            int x1 = scanner.nextInt();
            int y1 = scanner.nextInt();
            int x2 = scanner.nextInt();
            int y2 = scanner.nextInt();
            int x3 = scanner.nextInt();
            int y3 = scanner.nextInt();

            // Calculate squared distances to avoid floating-point precision issues
            int d1 = distanceSquared(x1, y1, x2, y2);
            int d2 = distanceSquared(x2, y2, x3, y3);
            int d3 = distanceSquared(x1, y1, x3, y3);
            int[] distances = {d1, d2, d3};
            Arrays.sort(distances);

            if (isCollinearVerticalOrHorizontal(x1, y1, x2, y2, x3, y3)) {
                System.out.println(1);
            } else if (meetsOutputTwoCriteria(x1, y1, x2, y2, x3, y3, distances)) {
                System.out.println(2);
            } else {
                System.out.println(3);
            }
        }
    }

    /**
     * Computes the squared Euclidean distance between two points.
     * Using squared distances preserves exact integer arithmetic and avoids
     * floating-point comparison pitfalls present in the original code.
     */
    private static int distanceSquared(int x1, int y1, int x2, int y2) {
        return (x2 - x1) * (x2 - x1) + (y2 - y1) * (y2 - y1);
    }

    /**
     * Checks if all three points lie on the same vertical or horizontal line.
     */
    private static boolean isCollinearVerticalOrHorizontal(int x1, int y1, int x2, int y2, int x3, int y3) {
        return (x1 == x2 && x2 == x3) || (y1 == y2 && y2 == y3);
    }

    /**
     * Evaluates the complex set of conditions that result in output 2.
     * Extracted to keep main logic readable and maintainable.
     */
    private static boolean meetsOutputTwoCriteria(int x1, int y1, int x2, int y2, int x3, int y3, int[] distances) {
        boolean isRightTriangle = distances[0] + distances[1] == distances[2];
        boolean hasSharedCoordinate = (x1 == x2 || x1 == x3 || x2 == x3 ||
                                       y1 == y2 || y1 == y3 || y2 == y3);

        return (isRightTriangle && hasSharedCoordinate)
                || isThirdPointOutsideVerticalBoundingBox(x1, y1, x2, y2, x3, y3)
                || isThirdPointOutsideHorizontalBoundingBox(x1, y1, x2, y2, x3, y3)
                || isAxisAlignedRightTriangleX(x1, y1, x2, y2, x3, y3)
                || isAxisAlignedRightTriangleY(x1, y1, x2, y2, x3, y3);
    }

    /**
     * Checks if the third point lies strictly outside the bounding box of a 
     * vertical segment formed by the other two points.
     */
    private static boolean isThirdPointOutsideVerticalBoundingBox(int x1, int y1, int x2, int y2, int x3, int y3) {
        if (x1 == x2) return isPointOutsideBoundingBox(x3, y3, x1, y1, x2, y2);
        if (x2 == x3) return isPointOutsideBoundingBox(x1, y1, x2, y2, x3, y3);
        if (x1 == x3) return isPointOutsideBoundingBox(x2, y2, x1, y1, x3, y3);
        return false;
    }

    /**
     * Checks if the third point lies strictly outside the bounding box of a 
     * horizontal segment formed by the other two points.
     */
    private static boolean isThirdPointOutsideHorizontalBoundingBox(int x1, int y1, int x2, int y2, int x3, int y3) {
        if (y1 == y2) return isPointOutsideBoundingBox(x3, y3, x1, y1, x2, y2);
        if (y2 == y3) return isPointOutsideBoundingBox(x1, y1, x2, y2, x3, y3);
        if (y1 == y3) return isPointOutsideBoundingBox(x2, y2, x1, y1, x3, y3);
        return false;
    }

    /**
     * Helper to determine if a point is strictly outside the axis-aligned bounding box
     * defined by two segment endpoints.
     */
    private static boolean isPointOutsideBoundingBox(int px, int py, int sx1, int sy1, int sx2, int sy2) {
        int minX = Math.min(sx1, sx2);
        int maxX = Math.max(sx1, sx2);
        int minY = Math.min(sy1, sy2);
        int maxY = Math.max(sy1, sy2);
        return (px > maxX || px < minX) && (py > maxY || py < minY);
    }

    /**
     * Checks for an axis-aligned right triangle where two points share an X coordinate
     * and the third point shares a Y coordinate with one of them (L-shape configuration).
     */
    private static boolean isAxisAlignedRightTriangleX(int x1, int y1, int x2, int y2, int x3, int y3) {
        return (x1 == x2 && (y1 == y3 || y2 == y3))
            || (x2 == x3 && (y2 == y1 || y3 == y1))
            || (x1 == x3 && (y1 == y2 || y3 == y2));
    }

    /**
     * Checks for an axis-aligned right triangle where two points share a Y coordinate
     * and the third point shares an X coordinate with one of them (L-shape configuration).
     */
    private static boolean isAxisAlignedRightTriangleY(int x1, int y1, int x2, int y2, int x3, int y3) {
        return (y1 == y2 && (x1 == x3 || x2 == x3))
            || (y2 == y3 && (x2 == x1 || x3 == x1))
            || (y1 == y3 && (x1 == x2 || x3 == x2));
    }
}

import java.io.*;
import java.util.StringTokenizer;

public class Solution {

    /**
     * Represents a geometric point with x and y coordinates.
     * Fields are final to ensure immutability.
     */
    static class Point {
        final int x;
        final int y;

        public Point(int x, int int y) {
            this.x = x;
            this.y = y;
        }
    }

    /**
     * Checks if all points in the array lie on the same vertical line.
     */
    private static boolean isCollinearVertical(Point[] points) {
        int x = points[0].x;
        for (Point p : points) {
            if (p.x != x) {
                return false;
            }
        }
        return true;
    }

    /**
     * Checks if all points in the array lie on the same horizontal line.
     */
    private static boolean isCollinearHorizontal(Point[] points) {
        int y = points[0].y;
        for (Point p : points) {
            if (p.y != y) {
                return false;
            }
        }
        return true;
    }

    /**
     * Checks if the 'mid' point's Y coordinate is strictly between 
     * the Y coordinates of 'start' and 'end'.
     */
    private static boolean isBetweenY(Point mid, Point start, Point end) {
        int min = Math.min(start.y, end.y);
        int max = Math.max(start.y, end.y);
        return mid.y > min && mid.y < max;
    }

    /**
     * Checks if the 'mid' point's X coordinate is strictly between 
     * the X coordinates of 'start' and 'end'.
     */
    private static boolean isBetweenX(Point mid, Point start, Point end) {
        int min = Math.min(start.x, end.x);
        int max = Math.max(start.x, end.x);
        return mid.x > min && mid.x < max;
    }

    /**
     * Main logic to determine the output based on point configuration.
     */
    static void solve(InputReader in, OutputWriter out) {
        Point[] points = new Point[3];
        for (int i = 0; i < 3; i++) {
            points[i] = new Point(in.nextInt(), in.nextInt());
        }

        // Case 1: All three points are collinear (horizontal or vertical)
        if (isCollinearVertical(points) || isCollinearHorizontal(points)) {
            out.print(1);
            return;
        }

        // Case 2: Two points form a segment, and the third point is NOT strictly between them.
        // This corresponds to an "L" shape configuration (or similar non-T shapes).

        // Check vertical segments (points share X coordinate)
        boolean condV1 = (points[0].x == points[1].x && !isBetweenY(points[2], points[0], points[1]));
        boolean condV2 = (points[0].x == points[2].x && !isBetweenY(points[1], points[0], points[2]));
        boolean condV3 = (points[1].x == points[2].x && !isBetweenY(points[0], points[1], points[2]));

        // Check horizontal segments (points share Y coordinate)
        boolean condH1 = (points[0].y == points[1].y && !isBetweenX(points[2], points[0], points[1]));
        boolean condH2 = (points[0].y == points[2].y && !isBetweenX(points[1], points[0], points[2]));
        boolean condH3 = (points[1].y == points[2].y && !isBetweenX(points[0], points[1], points[2]));

        if (condV1 || condV2 || condV3 || condH1 || condH2 || condH3) {
            out.print(2);
            return;
        }

        // Case 3: Default case (e.g., T-shape configurations where the point is between)
        out.print(3);
    }

    public static void main(String[] args) {
        InputReader in = new InputReader(System.in);
        OutputWriter out = new OutputWriter(System.out);
        solve(in, out);
        in.close();
        out.close();
    }

    /**
     * Fast Input Reader for competitive programming style inputs.
     */
    static class InputReader {
        BufferedReader br;
        StringTokenizer st;

        InputReader(InputStream is) {
            br = new BufferedReader(new InputStreamReader(is));
            st = null;
        }

        String nextLine() {
            String line = null;
            try {
                line = br.readLine();
            } catch (IOException e) {
                e.printStackTrace();
            }
            return line;
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                String line = nextLine();
                if (line == null) return null;
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        long nextLong() {
            return Long.parseLong(next());
        }

        double nextDouble() {
            return Double.parseDouble(next());
        }

        void close() {
            try {
                br.close();
            } catch (IOException e) {
                e.printStackTrace();
            }
        }
    }

    /**
     * Fast Output Writer for competitive programming style outputs.
     */
    static class OutputWriter {
        BufferedWriter bw;

        OutputWriter(OutputStream os) {
            bw = new BufferedWriter(new OutputStreamWriter(os));
        }

        void print(int i) {
            print(Integer.toString(i));
        }

        void println(int i) {
            println(Integer.toString(i));
        }

        void print(long l) {
            print(Long.toString(l));
        }

        void println(long l) {
            println(Long.toString(l));
        }

        void print(double d) {
            print(Double.toString(d));
        }

        void println(double d) {
            println(Double.toString(d));
        }

