    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.Reader;
import java.util.StringTokenizer;

public class Main {

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner(System.in);
        int[] x = new int[3];
        int[] y = new int[3];

        for (int i = 0; i < 3; i++) {
            x[i] = scanner.nextInt();
            y[i] = scanner.nextInt();
        }

        System.out.println(classifyTriangle(x, y));
    }

    /**
     * Classifies the triangle formed by three points.
     * Returns:
     *   1 if all three points are collinear (share the same x or y)
     *   2 if two points share an axis but the third point's coordinate is not strictly between them
     *   3 otherwise (valid non-degenerate triangle)
     */
    private static int classifyTriangle(int[] x, int[] y) {
        if (allEqual(x) || allEqual(y)) {
            return 1;
        }

        if (hasSharedX(x)) {
            return checkThirdPointBetween(x, y) ? 3 : 2;
        } else if (hasSharedY(y)) {
            return checkThirdPointBetween(y, x) ? 3 : 2;
        } else {
            return 3;
        }
    }

    private static boolean allEqual(int[] arr) {
        return arr[0] == arr[1] && arr[1] == arr[2];
    }

    private static boolean hasSharedX(int[] x) {
        return x[0] == x[1] || x[1] == x[2] || x[0] == x[2];
    }

    private static boolean hasSharedY(int[] y) {
        return y[0] == y[1] || y[1] == y[2] || y[0] == y[2];
    }

    private static boolean checkThirdPointBetween(int[] sharedCoords, int[] otherCoords) {
        return (sharedCoords[0] == sharedCoords[1] && isBetween(otherCoords[0], otherCoords[1], otherCoords[2])) ||
               (sharedCoords[1] == sharedCoords[2] && isBetween(otherCoords[1], otherCoords[2], otherCoords[0])) ||
               (sharedCoords[0] == sharedCoords[2] && isBetween(otherCoords[0], otherCoords[2], otherCoords[1]));
    }

    /**
     * Checks if c is strictly between a and b.
     */
    private static boolean isBetween(int a, int b, int c) {
        return (a < c && c < b) || (b < c && c < a);
    }

    /**
     * Lightweight fast input reader for competitive programming.
     */
    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner(Reader in) {
            br = new BufferedReader(in);
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) {
                        return null;
                    }
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

