/**
 * Utility class for array manipulation operations.
 */
class ArrayUtils {
    // Use a static Random instance to avoid re-seeding overhead
    private static final Random RANDOM = new Random();

    /**
     * Shuffles the given int array in place using a Fisher-Yates-like algorithm.
     */
    public static void shuffle(int[] a) {
        int n = a.length;
        for (int i = 0; i < n; i++) {
            int index = RANDOM.nextInt(n - i);
            int temp = a[i];
            a[i] = a[index + i];
            a[index + i] = temp;
        }
    }

    /**
     * Shuffles the given long array in place.
     */
    public static void shuffle(long[] a) {
        int n = a.length;
        for (int i = 0; i < n; i++) {
            int index = RANDOM.nextInt(n - i);
            long temp = a[i];
            a[i] = a[index + i];
            a[index + i] = temp;
        }
    }

    /**
     * Sorts the int array.
     * Note: Performs a shuffle first to potentially avoid worst-case scenarios
     * for certain sorting algorithms, preserving original behavior.
     */
    public static void sort(int[] a) {
        shuffle(a);
        Arrays.sort(a);
    }

    /**
     * Sorts the long array.
     * Note: Performs a shuffle first.
     */
    public static void sort(long[] a) {
        shuffle(a);
        Arrays.sort(a);
    }
}

/**
 * Solver class containing the core logic for the geometry problem.
 * Refactored variable names and logic extraction for clarity.
 */
class GeometrySolver {
    public void solve(FastReader in, PrintWriter out) {
        // Read coordinates for three points
        // P1: (x1, y1), P2: (x2, y2), P3: (x3, y3)
        // Original variables: a, b, c, d, e, f
        int x1 = in.nextInt();
        int y1 = in.nextInt();
        int x2 = in.nextInt();
        int y2 = in.nextInt();
        int x3 = in.nextInt();
        int y3 = in.nextInt();

        int result = 3;

        // Check conditions that set result to 2
        // Logic: Two points share an X or Y coordinate, 
        // and the third point's corresponding coordinate is outside the range [min, max].
        boolean condition2 = false;

        // Check pairs (1,2), (1,3), (2,3)

        // Pair (1, 2)
        if (x1 == x2) {
            if (y3 >= Math.max(y1, y2) || y3 <= Math.min(y1, y2)) condition2 = true;
        }
        if (y1 == y2) {
            if (x3 >= Math.max(x1, x2) || x3 <= Math.min(x1, x2)) condition2 = true;
        }

        // Pair (1, 3)
        if (x1 == x3) {
            if (y2 >= Math.max(y1, y3) || y2 <= Math.min(y1, y3)) condition2 = true;
        }
        if (y1 == y3) {
            if (x2 >= Math.max(x1, x3) || x2 <= Math.min(x1, x3)) condition2 = true;
        }

        // Pair (2, 3)
        if (x2 == x3) {
            if (y1 >= Math.max(y2, y3) || y1 <= Math.min(y2, y3)) condition2 = true;
        }
        if (y2 == y3) {
            if (x1 >= Math.max(x2, x3) || x1 <= Math.min(x2, x3)) condition2 = true;
        }

        if (condition2) {
            result = 2;
        }

        // Check conditions that set result to 1
        // Logic: All X coordinates are equal OR All Y coordinates are equal.
        // Note: This check happens after condition2, effectively overriding it if true.
        boolean condition1 = (x1 == x2 && x2 == x3) || (y1 == y2 && y2 == y3);

        if (condition1) {
            result = 1;
        }

        out.print(result);
    }
}

import java.util.Scanner;

/**
 * Analyzes the arrangement of three 2D points on a Cartesian plane.
 * Outputs:
 * 1 - If all three points are collinear on a horizontal or vertical line.
 * 2 - If one point lies on the axis-aligned segment between the other two.
 * 3 - Otherwise.
 */
public class PointArrangementChecker {

    /** Immutable record representing a 2D point. */
    private record Point(int x, int y) {}

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        try {
            Point p1 = readPoint(scanner);
            Point p2 = readPoint(scanner);
            Point p3 = readPoint(scanner);

            System.out.println(determineArrangement(p1, p2, p3));
        } finally {
            scanner.close();
        }
    }

    /** Reads the next two integers from the scanner as a Point. */
    private static Point readPoint(Scanner scanner) {
        return new Point(scanner.nextInt(), scanner.nextInt());
    }

    /** Determines the arrangement category based on the three points. */
    private static int determineArrangement(Point p1, Point p2, Point p3) {
        if (areCollinearHorizontallyOrVertically(p1, p2, p3)) {
            return 1;
        }
        if (onePointLiesBetweenOthers(p1, p2, p3)) {
            return 2;
        }
        return 3;
    }

    /** Checks if all three points share the same x-coordinate or the same y-coordinate. */
    private static boolean areCollinearHorizontallyOrVertically(Point p1, Point p2, Point p3) {
        return (p1.x == p2.x && p2.x == p3.x) || (p1.y == p2.y && p2.y == p3.y);
    }

    /** Checks if any of the three points lies on the axis-aligned segment formed by the other two. */
    private static boolean onePointLiesBetweenOthers(Point p1, Point p2, Point p3) {
        return liesBetween(p1, p2, p3) || liesBetween(p2, p3, p1) || liesBetween(p1, p3, p2);
    }

    /**
     * Checks if {@code point} lies on the axis-aligned line relative to {@code a} and {@code b}.
     * Preserves the exact logical behavior of the original {@code f} method.
     */
    private static boolean liesBetween(Point a, Point b, Point point) {
        boolean xAligned = (a.x == point.x || b.x == point.x);
        boolean yBetween = isBetween(a.y, b.y, point.y);
        boolean yAligned = (a.y == point.y || b.y == point.y);
        boolean xBetween = isBetween(a.x, b.x, point.x);
        return (xAligned && yBetween) || (yAligned && xBetween);
    }

    /** Checks if {@code val} lies within the inclusive range defined by {@code a} and {@code b}. */
    private static boolean isBetween(int a, int b, int val) {
        return val >= Math.min(a, b) && val <= Math.max(a, b);
    }
}

