class TaskD {

    /**
     * Solves the problem for a single test case.
     * Reads three points and determines their geometric relationship.
     */
    public void solve(InputReader in, PrintWriter out) {
        Point a = in.readPoint();
        Point b = in.readPoint();
        Point c = in.readPoint();

        // Case 1: All three points share the same x or same y (collinear vertical/horizontal)
        if ((a.x == b.x && b.x == c.x) || (a.y == b.y && b.y == c.y)) {
            out.println(1);
            return;
        }

        // Case 2: Any point lies on the axis-aligned segment formed by the other two
        if (isOnAxisAlignedSegment(a, b, c) ||
            isOnAxisAlignedSegment(b, c, a) ||
            isOnAxisAlignedSegment(c, a, b)) {
            out.println(2);
        } else {
            // Case 3: General position
            out.println(3);
        }
    }

    /**
     * Checks if point p3 lies on any of the four axis-aligned segments 
     * connecting p1 and p2 (vertical/horizontal lines through p1 and p2).
     * This consolidates the original 6 permutation checks into a single, 
     * highly readable method.
     */
    private boolean isOnAxisAlignedSegment(Point p1, Point p2, Point p3) {
        // Vertical segment through p1
        if (p3.x == p1.x && isBetween(p3.y, p1.y, p2.y)) return true;
        // Horizontal segment through p1
        if (p3.y == p1.y && isBetween(p3.x, p1.x, p2.x)) return true;
        // Vertical segment through p2
        if (p3.x == p2.x && isBetween(p3.y, p1.y, p2.y)) return true;
        // Horizontal segment through p2
        if (p3.y == p2.y && isBetween(p3.x, p1.x, p2.x)) return true;
        return false;
    }

    /**
     * Helper to check if a value lies within the inclusive range [min, max].
     */
    private boolean isBetween(int val, int min, int max) {
        return val >= Math.min(min, max) && val <= Math.max(min, max);
    }

    /**
     * Represents a 2D coordinate point.
     */
    static class Point {
        int x, y;

        Point() {}

        Point(int x, int y) {
            this.x = x;
            this.y = y;
        }
    }
}

