import java.io.InputStream;
import java.io.IOException;
import java.io.OutputStream;
import java.io.PrintWriter;
import java.util.InputMismatchException;

public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);

        TaskD solver = new TaskD();
        solver.solve(in, out);
        out.close();
    }

    static class TaskD {
        private static final int NUM_POINTS = 3;

        public void solve(InputReader in, PrintWriter out) {
            Point[] points = new Point[NUM_POINTS];
            for (int i = 0; i < NUM_POINTS; i++) {
                points[i] = new Point(in.readInt(), in.readInt());
            }

            if (areOnSameLine(points)) {
                out.println(1);
                return;
            }

            int[] connectionCount = new int[NUM_POINTS];
            for (int i = 0; i < NUM_POINTS; i++) {
                for (int j = i + 1; j < NUM_POINTS; j++) {
                    if (points[i].sharesCoordinate(points[j])) {
                        connectionCount[i]++;
                        connectionCount[j]++;
                    }
                }
            }

            int connectedPointsCount = 0;
            for (int count : connectionCount) {
                if (count > 0) connectedPointsCount++;
            }

            if (connectedPointsCount == NUM_POINTS) {
                out.println(2);
                return;
            }
            if (connectedPointsCount == 0) {
                out.println(3);
                return;
            }

            // Exactly two points are connected, one is isolated
            int isolatedIndex = -1;
            int p1Index = -1, p2Index = -1;
            for (int i = 0; i < NUM_POINTS; i++) {
                if (connectionCount[i] == 0) {
                    isolatedIndex = i;
                } else {
                    if (p1Index == -1) p1Index = i;
                    else p2Index = i;
                }
            }

            Point p1 = points[p1Index];
            Point p2 = points[p2Index];
            Point isolated = points[isolatedIndex];

            int result;
            if (p1.x == p2.x) {
                int minY = Math.min(p1.y, p2.y);
                int maxY = Math.max(p1.y, p2.y);
                result = (isolated.y > minY && isolated.y < maxY) ? 3 : 2;
            } else {
                int minX = Math.min(p1.x, p2.x);
                int maxX = Math.max(p1.x, p2.x);
                result = (isolated.x > minX && isolated.x < maxX) ? 3 : 2;
            }
            out.println(result);
        }

        private boolean areOnSameLine(Point[] points) {
            boolean allSameX = points[0].x == points[1].x && points[1].x == points[2].x;
            boolean allSameY = points[0].y == points[1].y && points[1].y == points[2].y;
            return allSameX || allSameY;
        }
    }

    static class Point {
        public final int x;
        public final int y;

        public Point(int x, int y) {
            this.x = x;
            this.y = y;
        }

        public boolean sharesCoordinate(Point other) {
            return this.x == other.x || this.y == other.y;
        }

        @Override
        public boolean equals(Object obj) {
            if (this == obj) return true;
            if (!(obj instanceof Point)) return false;
            Point other = (Point) obj;
            return x == other.x && y == other.y;
        }

        @Override
        public int hashCode() {
            return 31 * x + y;
        }

        @Override
        public String toString() {
            return x + " " + y;
        }
    }

    static class InputReader {
        private final InputStream stream;
        private final byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;
        private SpaceCharFilter filter;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        public int read() {
            if (numChars == -1) {
                throw new InputMismatchException();
            }
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0) {
                    return -1;
                }
            }
            return buf[curChar++];
        }

        public int readInt() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                res *= 10;
                res += c - '0';
                c = read();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public boolean isSpaceChar(int c) {
            return filter != null ? filter.isSpaceChar(c) : isWhitespace(c);
        }

        public static boolean isWhitespace(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        public interface SpaceCharFilter {
            boolean isSpaceChar(int ch);
        }
    }
}

import java.io.PrintWriter;
import java.util.Scanner;

public class Round340 {

    public static void main(String[] args) {
        // Use try-with-resources for automatic and safe resource cleanup
        try (Scanner sc = new Scanner(System.in);
             PrintWriter out = new PrintWriter(System.out)) {

            Point p1 = readPoint(sc);
            Point p2 = readPoint(sc);
            Point p3 = readPoint(sc);

            out.println(solve(p1, p2, p3));
        }
    }

    private static Point readPoint(Scanner sc) {
        return new Point(sc.nextInt(), sc.nextInt());
    }

    private static int solve(Point p1, Point p2, Point p3) {
        // Case 1: All three points share the same X or Y coordinate (collinear on an axis)
        if (allSameX(p1, p2, p3) || allSameY(p1, p2, p3)) {
            return 1;
        }

        // Check all three pairs: if two share a coordinate, is the third strictly between them?
        Point[] points = {p1, p2, p3};
        for (int i = 0; i < 3; i++) {
            for (int j = i + 1; j < 3; j++) {
                int k = 3 - i - j; // Index of the remaining point
                Point a = points[i];
                Point b = points[j];
                Point c = points[k];

                if (a.x == b.x && isStrictlyBetween(c.y, a.y, b.y)) {
                    return 3;
                }
                if (a.y == b.y && isStrictlyBetween(c.x, a.x, b.x)) {
                    return 3;
                }
            }
        }

        // Case 2: No special axis-aligned relationship found
        return 2;
    }

    private static boolean allSameX(Point a, Point b, Point c) {
        return a.x == b.x && b.x == c.x;
    }

    private static boolean allSameY(Point a, Point b, Point c) {
        return a.y == b.y && b.y == c.y;
    }

    private static boolean isStrictlyBetween(int value, int min, int max) {
        return value > Math.min(min, max) && value < Math.max(min, max);
    }

    /**
     * Simple value object to encapsulate 2D coordinates.
     * Using a dedicated class improves readability and prevents parallel array bugs.
     */
    private static class Point {
        final int x;
        final int y;

        Point(int x, int y) {
            this.x = x;
            this.y = y;
        }
    }
}

