class ProblemSolver {
    // Encapsulated Point class for better readability and object-oriented design
    private static class Point {
        int x, y;

        Point(int x, int y) {
            this.x = x;
            this.y = y;
        }
    }

    void solve(FastReader in, PrintWriter out) {
        Point[] points = new Point[3];
        for (int i = 0; i < 3; i++) {
            points[i] = new Point(in.nextInt(), in.nextInt());
        }

        // 1. Check if all 3 points are collinear (all share same X or all share same Y)
        if (areAllPointsOnSameVerticalLine(points) || areAllPointsOnSameHorizontalLine(points)) {
            out.println(1);
            return;
        }

        // 2. Check if any point lies outside the segment formed by the other two
        // We check all permutations: (0,1) vs 2, (0,2) vs 1, (1,2) vs 0
        if (isPointOutsideSegment(points[0], points[1], points[2]) ||
            isPointOutsideSegment(points[0], points[2], points[1]) ||
            isPointOutsideSegment(points[1], points[2], points[0])) {
            out.println(2);
            return;
        }

        // 3. Default case
        out.println(3);
    }

    private boolean areAllPointsOnSameVerticalLine(Point[] p) {
        return p[0].x == p[1].x && p[1].x == p[2].x;
    }

    private boolean areAllPointsOnSameHorizontalLine(Point[] p) {
        return p[0].y == p[1].y && p[1].y == p[2].y;
    }

    /**
     * Checks if p3 is outside the segment defined by p1 and p2.
     * Logic derived from original checkX/checkY methods:
     * Returns true if p1 and p2 are aligned (vertical or horizontal)
     * AND p3 is outside the range defined by p1 and p2 (inclusive).
     */
    private boolean isPointOutsideSegment(Point p1, Point p2, Point p3) {
        if (p1.x == p2.x) {
            // Vertical alignment check
            int min = Math.min(p1.y, p2.y);
            int max = Math.max(p1.y, p2.y);
            // Original logic: min >= p3.y || max <= p3.y
            // Equivalent to: p3.y <= min || p3.y >= max
            if (p3.y <= min || p3.y >= max) {
                return true;
            }
        } else if (p1.y == p2.y) {
            // Horizontal alignment check
            int min = Math.min(p1.x, p2.x);
            int max = Math.max(p1.x, p2.x);
            // Original logic: min >= p3.x || max <= p3.x
            if (p3.x <= min || p3.x >= max) {
                return true;
            }
        }
        return false;
    }
}

