/**
 * Refactored Main class for improved maintainability and code quality.
 * 
 * Refactoring Improvements:
 * 1.  **Encapsulation:** Created a `Point` class to represent coordinates, replacing raw integer variables.
 * 2.  **Logic Extraction:** Moved the geometric logic into a dedicated `solve()` method.
 * 3.  **Readability:** Simplified complex nested `if-else` blocks using a helper method `isStrictlyBetween()`.
 * 4.  **Robustness:** Improved `InputReader` to handle EOF explicitly and added `out.flush()` for correct output buffering.
 * 5.  **Naming:** Used descriptive variable names and method signatures.
 */
public class Main {

    /**
     * Represents a 2D point with integer coordinates.
     */
    private static class Point {
        final int x;
        final int y;

        Point(int x, int y) {
            this.x = x;
            this.y = y;
        }
    }

    public static void main(String[] args) {
        InputReader in = new InputReader();
        PrintWriter out = new PrintWriter(System.out);

        // Process input until no more tokens are available
        while (in.hasNext()) {
            try {
                // Read 6 integers representing coordinates of 3 points
                int x1 = in.nextInt();
                int y1 = in.nextInt();
                int x2 = in.nextInt();
                int y2 = in.nextInt();
                int x3 = in.nextInt();
                int y3 = in.nextInt();

                // Create Point objects for better readability and logic handling
                Point p1 = new Point(x1, y1);
                Point p2 = new Point(x2, y2);
                Point p3 = new Point(x3, y3);

                // Compute and print result
                out.println(solve(p1, p2, p3));
            } catch (Exception e) {
                // Gracefully handle unexpected input errors or malformed data
                break;
            }
        }

        // Ensure all output is written to the stream
        out.flush();
        out.close();
    }

    /**
     * Determines the classification of the triangle formed by three points
     * based on specific alignment rules derived from the original logic.
     * 
     * @param p1 First point
     * @param p2 Second point
     * @param p3 Third point
     * @return 1 if all points are collinear (vertical/horizontal), 
     *         2 if two points align and third is outside segment, 
     *         3 otherwise (including third point inside segment or no alignment).
     */
    private static int solve(Point p1, Point p2, Point p3) {
        // Case 1: All three points are collinear on a vertical or horizontal line
        boolean allVertical = (p1.x == p2.x && p2.x == p3.x);
        boolean allHorizontal = (p1.y == p2.y && p2.y == p3.y);

        if (allVertical || allHorizontal) {
            return 1;
        }

        // Case 2: Check if any pair of points shares an x or y coordinate
        // We iterate through pairs to check for alignment

        // Pair (p1, p2)
        if (p1.x == p2.x) {
            // Vertical alignment. Check if p3 is strictly between p1 and p2 vertically.
            if (isStrictlyBetween(p3.y, p1.y, p2.y)) return 3;
            return 2;
        }
        if (p1.y == p2.y) {
            // Horizontal alignment. Check if p3 is strictly between p1 and p2 horizontally.
            if (isStrictlyBetween(p3.x, p1.x, p2.x)) return 3;
            return 2;
        }

        // Pair (p1, p3)
        if (p1.x == p3.x) {
            if (isStrictlyBetween(p2.y, p1.y, p3.y)) return 3;
            return 2;
        }
        if (p1.y == p3.y) {
            if (isStrictlyBetween(p2.x, p1.x, p3.x)) return 3;
            return 2;
        }

        // Pair (p2, p3)
        if (p2.x == p3.x) {
            if (isStrictlyBetween(p1.y, p2.y, p3.y)) return 3;
            return 2;
        }
        if (p2.y == p3.y) {
            if (isStrictlyBetween(p1.x, p2.x, p3.x)) return 3;
            return 2;
        }

        // Case 3: No points share coordinates (General case)
        return 3;
    }

    /**
     * Helper method to check if a value is strictly between min and max.
     */
    private static boolean isStrictlyBetween(int val, int min, int max) {
        return (val > min && val < max) || (val > max && val < min);
    }

    /**
     * Fast Input Reader class for efficient token parsing.
     */
    static class InputReader {
        private BufferedReader buf;
        private StringTokenizer tok;

        public InputReader() {
            buf = new BufferedReader(new InputStreamReader(System.in));
        }

        public boolean hasNext() {
            while (tok == null || !tok.hasMoreTokens()) {
                try {
                    String line = buf.readLine();
                    if (line == null) {
