                }
            }
            return true;
        }

        public String next() {
            if (hasNext()) {
                return tok.nextToken();
            }
            return null;
        }

        public int nextInt() {
            String s = next();
            if (s == null) throw new RuntimeException("End of input");
            return Integer.parseInt(s);
        }

