import java.io.*;
import java.util.*;

public class Main {

    /**
     * Immutable data class for point coordinates.
     * Using a simple class with public final fields ensures maximum compatibility
     * while clearly expressing intent.
     */
    static class Node {
        final int x, y;
        Node(int x, int y) {
            this.x = x;
            this.y = y;
        }
    }

    /**
     * Fast I/O helper class. Replaces the original AnotherReader with cleaner
     * exception handling and standard Java conventions.
     */
    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        public FastScanner(File file) {
            try {
                br = new BufferedReader(new FileReader(file));
            } catch (IOException e) {
                throw new UncheckedIOException("Failed to open file: " + file, e);
            }
        }

        public String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }

    public static void main(String[] args) {
        // Preserve original OJ vs local file behavior
        File inputFile = new File("input.txt");
        FastScanner sc = inputFile.exists() ? new FastScanner(inputFile) : new FastScanner();
        PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out));

        try {
            // Original code runs exactly once
            process(sc, out);
        } finally {
            out.flush();
            out.close();
        }
    }

    /**
     * Core business logic. Separated from I/O setup for testability and clarity.
     */
    private static void process(FastScanner sc, PrintWriter out) {
        Node[] points = new Node[3];
        Set<Integer> uniqueX = new HashSet<>();
        Set<Integer> uniqueY = new HashSet<>();

        // Read 3 points
        for (int i = 0; i < 3; i++) {
            points[i] = new Node(sc.nextInt(), sc.nextInt());
            uniqueX.add(points[i].x);
            uniqueY.add(points[i].y);
        }

        // Base answer is the minimum number of unique coordinates in either dimension
        int ans = Math.min(uniqueX.size(), uniqueY.size());

        // Special condition check when exactly two unique values exist in one dimension
        if (ans == 2) {
            if (checkAxisAlignedCondition(points)) {
                out.println(3);
                return;
            }
        }
        out.println(ans);
    }

    /**
     * Checks if the three points satisfy the original complex condition:
     * If two points share an x-coordinate, the third point's y must NOT be strictly between them.
     * If two points share a y-coordinate, the third point's x must NOT be strictly between them.
     * If either condition is violated (i.e., strictly between), returns true.
     */
    private static boolean checkAxisAlignedCondition(Node[] points) {
        // Sort by x ascending, then y ascending
        Arrays.sort(points, Comparator.comparingInt(p -> p.x).thenComparingInt(p -> p.y));

        // Check pairs sharing x-coordinate
        if (points[0].x == points[1].x) {
            if (isStrictlyBetween(points[2].y, points[0].y, points[1].y)) return true;
        }
        if (points[1].x == points[2].x) {
            if (isStrictlyBetween(points[0].y, points[1].y, points[2].y)) return true;
        }

        // Sort by y ascending, then x ascending
        Arrays.sort(points, Comparator.comparingInt(p -> p.y).thenComparingInt(p -> p.x));

        // Check pairs sharing y-coordinate
        if (points[0].y == points[1].y) {
            if (isStrictlyBetween(points[2].x, points[0].x, points[1].x)) return true;
        }
        if (points[1].y == points[2].y) {
            if (isStrictlyBetween(points[0].x, points[1].x, points[2].x)) return true;
        }

        return false;
    }

    /**
     * Returns true if val is strictly between a and b.
     * Replaces the original verbose boolean expression:
     * !((val>=a && val>=b) || (val<=a && val<=b))
     */
    private static boolean isStrictlyBetween(int val, int a, int b) {
        int min = Math.min(a, b);
        int max = Math.max(a, b);
        return val > min && val < max;
    }
}

