            if (hasConnection(points[0], points[2], points[1])) check = true;
            if (hasConnection(points[1], points[2], points[0])) check = true;

            if (check) {
                pw.println(2);
            } else {
                pw.println(3);
            }
        }

        pw.flush();
    }

    /**
     * Checks if point p3 satisfies the condition relative to the segment formed by p1 and p2.
     * Condition: If p1 and p2 share an axis, p3 must be outside or on the boundary 
     * of the range defined by p1 and p2 on the *other* axis.
     */
    private static boolean hasConnection(Point p1, Point p2, Point p3) {
        // Case 1: Vertical alignment (Same X)
        if (p1.x == p2.x) {
            long minY = Math.min(p1.y, p2.y);
            long maxY = Math.max(p1.y, p2.y);
            // Check if p3.y is <= min or >= max
            if (p3.y <= minY || p3.y >= maxY) {
                return true;
            }
        }
        // Case 2: Horizontal alignment (Same Y)
        if (p1.y == p2.y) {
            long minX = Math.min(p1.x, p2.x);
            long maxX = Math.max(p1.x, p2.x);
            // Check if p3.x is <= min or >= max
            if (p3.x <= minX || p3.x >= maxX) {
                return true;
            }
        }
        return false;
    }
}

