public class CF617D {
    public static void main(String[] args) {
        InputReader sc = new InputReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        int x1 = sc.nextInt();
        int y1 = sc.nextInt();
        int x2 = sc.nextInt();
        int y2 = sc.nextInt();
        int x3 = sc.nextInt();
        int y3 = sc.nextInt();

        int result;
        if (areAllCollinear(x1, y1, x2, y2, x3, y3)) {
            result = 1;
        } else if (isThirdOnSegment(x1, y1, x2, y2, x3, y3)) {
            result = 2;
        } else {
            result = 3;
        }

        out.println(result);
        out.close();
    }

    /**
     * Checks if all three points lie on the same horizontal or vertical line.
     */
    private static boolean areAllCollinear(int x1, int y1, int x2, int y2, int x3, int y3) {
        return (x1 == x2 && x2 == x3) || (y1 == y2 && y2 == y3);
    }

    /**
     * Checks if any point lies on the line segment formed by the other two points.
     */
    private static boolean isThirdOnSegment(int x1, int y1, int x2, int y2, int x3, int y3) {
        return isOnSegment(x1, y1, x2, y2, x3, y3) ||
               isOnSegment(x1, y1, x3, y3, x2, y2) ||
               isOnSegment(x2, y2, x3, y3, x1, y1);
    }

    /**
     * Checks if point (px, py) lies on the horizontal/vertical segment between (x1, y1) and (x2, y2).
     */
    private static boolean isOnSegment(int x1, int y1, int x2, int y2, int px, int py) {
        // Only horizontal or vertical segments are valid for this problem
        if (x1 != x2 && y1 != y2) {
            return false;
        }

        if (x1 == x2) {
            return px == x1 && py >= Math.min(y1, y2) && py <= Math.max(y1, y2);
        } else {
            return py == y1 && px >= Math.min(x1, x2) && px <= Math.max(x1, x2);
        }
    }
}

class InputReader {
    private InputStream stream;
    private byte[] buf = new byte[1024];
    private int curChar;
    private int numChars;
    private SpaceCharFilter filter;

    public InputReader(InputStream stream) {
        this.stream = stream;
    }

    public static boolean isWhitespace(int c) {
        return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
    }

    public int read() {
        if (numChars == -1)
            throw new InputMismatchException();
        if (curChar >= numChars) {
            curChar = 0;
            try {
                numChars = stream.read(buf);
            } catch (IOException e) {
                throw new InputMismatchException();
            }
            if (numChars <= 0)
                return -1;
        }
        return buf[curChar++];
    }

    public int nextInt() {
        int c = read();
        while (isSpaceChar(c))
            c = read();
        int sgn = 1;
        if (c == '-') {
            sgn = -1;
            c = read();
        }
        int res = 0;
        do {
            if (c < '0' || c > '9')
                throw new InputMismatchException();
            res *= 10;
            res += c - '0';
            c = read();
        } while (!isSpaceChar(c));
        return res * sgn;
    }

    public long nextLong() {
        int c = read();
        while (isSpaceChar(c))
            c = read();
        int sgn = 1;
        if (c == '-') {
            sgn = -1;
            c = read();
        }
        long res = 0;
        do {
            if (c < '0' || c > '9')
                throw new InputMismatchException();
            res *= 10;
            res += c - '0';
            c = read();
        } while (!isSpaceChar(c));
        return res * sgn;
    }

    public String nextToken() {
        int c = read();
        while (isSpaceChar(c))
            c = read();
        StringBuilder res = new StringBuilder();
        do {
            res.appendCodePoint(c);
            c = read();
        } while (!isSpaceChar(c));
        return res.toString();
    }

    public String nextLine() {
        int c = read();
        while (isSpaceChar(c))
            c = read();
        StringBuilder res = new StringBuilder();
        do {
            res.appendCodePoint(c);
            c = read();
        } while (!isEndOfLine(c));
        return res.toString();
    }

    public int[] nextIntArray(int n) {
        int[] arr = new int[n];
        for (int i = 0; i < n; i++) {
            arr[i] = nextInt();
        }
        return arr;
    }

    public long[] nextLongArray(int n) {
        long[] arr = new long[n];
        for (int i = 0; i < n; i++) {
            arr[i] = nextLong();
        }
        return arr;
    }

    public void pArray(int[] arr) {
        for (int i = 0; i < arr.length; i++) {
            System.out.print(arr[i] + " ");
        }
        System.out.println();
    }

    public void pArray(long[] arr) {
        for (int i = 0; i < arr.length; i++) {
            System.out.print(arr[i] + " ");
        }
        System.out.println();
    }

    public boolean isSpaceChar(int c) {
        if (filter != null)
            return filter.isSpaceChar(c);
        return isWhitespace(c);
    }

    private boolean isEndOfLine(int c) {
        return c == '\n' || c == '\r' || c == -1;
    }

    public interface SpaceCharFilter {
        public boolean isSpaceChar(int ch);
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

public class Main {

    public static void main(String[] args) throws IOException {
        Reader.init(System.in);

        int x1 = Reader.nextInt();
        int y1 = Reader.nextInt();
        int x2 = Reader.nextInt();
        int y2 = Reader.nextInt();
        int x3 = Reader.nextInt();
        int y3 = Reader.nextInt();

        if (areCollinear(x1, y1, x2, y2, x3, y3)) {
            System.out.println(1);
        } else if (canBeCoveredByTwoLines(x1, y1, x2, y2, x3, y3)) {
            System.out.println(2);
        } else {
            System.out.println(3);
        }
    }

    /**
     * Checks if three points are collinear on a horizontal or vertical line.
     */
    private static boolean areCollinear(int x1, int y1, int x2, int y2, int x3, int y3) {
        return (x1 == x2 && x2 == x3) || (y1 == y2 && y2 == y3);
    }

    /**
     * Checks if the three points can be covered by at most two axis-parallel lines.
     * This is true if any two points share the same X or Y coordinate.
     * (The original verbose condition was mathematically equivalent to this check.)
     */
    private static boolean canBeCoveredByTwoLines(int x1, int y1, int x2, int y2, int x3, int y3) {
        return x1 == x2 || x2 == x3 || x1 == x3 ||
               y1 == y2 || y2 == y3 || y1 == y3;
    }

    /**
     * Fast I/O helper class for competitive programming.
     */
    static class Reader {
        private static BufferedReader reader;
        private static StringTokenizer tokenizer;

        static void init(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
            tokenizer = new StringTokenizer("");
        }

        static String next() throws IOException {
            while (!tokenizer.hasMoreTokens()) {
                String line = reader.readLine();
                if (line == null) {
                    return null;
                }
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        static int nextInt() throws IOException {
            String token = next();
            if (token == null) {
                throw new IOException("Unexpected end of input");
            }
            return Integer.parseInt(token);
        }

        static long nextLong() throws IOException {
            String token = next();
            if (token == null) {
                throw new IOException("Unexpected end of input");
            }
            return Long.parseLong(token);
        }

        static double nextDouble() throws IOException {
            String token = next();
            if (token == null) {
                throw new IOException("Unexpected end of input");
            }
            return Double.parseDouble(token);
        }
    }

    /**
     * Utility class containing common algorithmic helper methods.
     */
    final class Tools {
        private Tools() {} // Prevent instantiation

        /**
         * Generates the next lexicographical permutation of the array prefix.
         */
        public static boolean nextPermutation(int[] p, int len) {
            int a = len - 2;
            while (a >= 0 && p[a] >= p[a + 1]) {
                a--;
            }
            if (a == -1) {
                return false;
            }

            int b = len - 1;
            while (p[b] <= p[a]) {
                b--;
            }

            swap(p, a, b);
            reverse(p, a + 1, len - 1);
            return true;
        }

        /**
         * Returns the index of the first element >= key, or -1 if not found.
         */
        public static <T extends Comparable<T>> int lowerBound(T[] arr, T key) {
            int lo = 0;
            int hi = arr.length;
            while (lo < hi) {
                int mid = lo + (hi - lo) / 2;
                if (arr[mid].compareTo(key) >= 0) {
                    hi = mid;
                } else {
                    lo = mid + 1;
                }
            }
            return lo < arr.length ? lo : -1;
        }

        /**
         * Returns the index of the first element > key, or -1 if not found.
         */
        public static <T extends Comparable<T>> int upperBound(T[] arr, T key) {
            int lo = 0;
            int hi = arr.length;
            while (lo < hi) {
                int mid = lo + (hi - lo) / 2;
                if (arr[mid].compareTo(key) <= 0) {
                    lo = mid + 1;
                } else {
                    hi = mid;
                }
            }
            return lo < arr.length ? lo : -1;
        }

        private static void swap(int[] arr, int i, int j) {
            int temp = arr[i];
            arr[i] = arr[j];
            arr[j] = temp;
        }

        private static void reverse(int[] arr, int start, int end) {
            while (start < end) {
                swap(arr, start++, end--);
            }
        }
    }
}

import java.util.Scanner;

/**
 * Solves axis-aligned grid connectivity problems.
 * Determines if a set of points are directly aligned, connected via one intermediate point,
 * or require more steps.
 */
public class GridConnectivitySolver {

    private static final int NUM_POINTS = 3;
    private static final int RESULT_DIRECT = 1;
    private static final int RESULT_ONE_INTERMEDIATE = 2;
    private static final int RESULT_INDIRECT = 3;

    /** Represents a point in a 2D grid. */
    private static class Point {
        final int x;
        final int y;

        Point(int x, int y) {
            this.x = x;
            this.y = y;
        }
    }

    public static void main(String[] args) {
        // try-with-resources ensures the Scanner is closed automatically
        try (Scanner scanner = new Scanner(System.in)) {
            while (scanner.hasNextInt()) {
                Point[] points = readPoints(scanner, NUM_POINTS);
                System.out.println(solve(points));
            }
        }
    }

    /** Reads exactly 'count' points from the scanner. */
    private static Point[] readPoints(Scanner scanner, int count) {
        Point[] points = new Point[count];
        for (int i = 0; i < count; i++) {
            points[i] = new Point(scanner.nextInt(), scanner.nextInt());
        }
        return points;
    }

    /**
     * Determines the connectivity result:
     * 1 - All points share the same x or y coordinate (direct alignment)
     * 2 - Points can be connected via exactly one intermediate point
     * 3 - Otherwise (indirect/no connection)
     */
    private static int solve(Point[] points) {
        if (areAllAligned(points)) {
            return RESULT_DIRECT;
        }
        if (canConnectViaIntermediate(points)) {
            return RESULT_ONE_INTERMEDIATE;
        }
        return RESULT_INDIRECT;
    }

    /** Checks if all points lie on the same vertical or horizontal line. */
    private static boolean areAllAligned(Point[] points) {
        boolean sameX = true;
        boolean sameY = true;
        Point first = points[0];
        for (int i = 1; i < points.length; i++) {
            if (points[i].x != first.x) sameX = false;
            if (points[i].y != first.y) sameY = false;
        }
        return sameX || sameY;
    }

    /** Checks if any two points can be connected through a third point. */
    private static boolean canConnectViaIntermediate(Point[] points) {
        int n = points.length;
        outer:
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (i == j) continue;
                for (int k = 0; k < n; k++) {
                    if (k == i || k == j) continue;
                    if (isBetweenOnAxisAlignedLine(points[i], points[j], points[k])) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Checks if p1 lies on the axis-aligned line segment between p2 and p3.
     * Equivalent to the original gao() logic but significantly more readable.
     */
    private static boolean isBetweenOnAxisAlignedLine(Point p1, Point p2, Point p3) {
        if (p2.y == p3.y) {
            return p1.x >= Math.min(p2.x, p3.x) && p1.x <= Math.max(p2.x, p3.x);
        }
        if (p2.x == p3.x) {
            return p1.y >= Math.min(p2.y, p3.y) && p1.y <= Math.max(p2.y, p3.y);
        }
        return false;
    }
}

import java.io.InputStream;
import java.io.OutputStream;
import java.io.PrintWriter;
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        // Initialize I/O streams
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        Scanner in = new Scanner(inputStream);
        PrintWriter out = new PrintWriter(outputStream);

        // Execute the solver
        GeometrySolver solver = new GeometrySolver();
        solver.solve(in, out);

        // Ensure output is written and resources are closed
        out.flush();
        out.close();
    }

    /**
     * Solver class for handling the geometry logic.
     */
    static class GeometrySolver {
        private static final int NUM_POINTS = 3;

        public void solve(Scanner in, PrintWriter out) {
            int[] x = new int[NUM_POINTS];
            int[] y = new int[NUM_POINTS];

            // Read input coordinates
            for (int i = 0; i < NUM_POINTS; ++i) {
                x[i] = in.nextInt();
                y[i] = in.nextInt();
            }

            // Check Condition 1: All points are collinear on a vertical or horizontal line
            if (areAllCoordinatesEqual(x) || areAllCoordinatesEqual(y)) {
                out.println("1");
                return;
            }

            // Check Condition 2: Check pairs of points for specific geometric alignment
            // Iterate through all unique pairs (i, j)
            for (int i = 0; i < NUM_POINTS; ++i) {
                for (int j = i + 1; j < NUM_POINTS; ++j) {
                    // Determine the index of the third point k.
                    // Since indices are 0, 1, 2, their sum is 3. Thus, k = 3 - i - j.
                    int k = 3 - i - j;

                    // Check if points i and j form a vertical segment (same x)
                    if (x[i] == x[j]) {
                        // Check if point k is outside or on the boundary of the vertical span of i and j
                        if (isOutsideOrOnBoundary(y[k], y[i], y[j])) {
                            out.println("2");
                            return;
                        }
                    }

                    // Check if points i and j form a horizontal segment (same y)
                    if (y[i] == y[j]) {
                        // Check if point k is outside or on the boundary of the horizontal span of i and j
                        if (isOutsideOrOnBoundary(x[k], x[i], x[j])) {
                            out.println("2");
                            return;
                        }
                    }
                }
            }

            // Default Condition 3
            out.println("3");
        }

        /**
         * Checks if all elements in an array of size 3 are equal.
         */
        private boolean areAllCoordinatesEqual(int[] array) {
            return array[0] == array[1] && array[1] == array[2];
        }

        /**
         * Checks if a value is outside or equal to the range defined by min and max.
         * Logic equivalent to: (val >= a && val >= b) || (val <= a && val <= b)
         */
        private boolean isOutsideOrOnBoundary(int val, int a, int b) {
            int min = Math.min(a, b);
            int max = Math.max(a, b);
            return val <= min || val >= max;
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

public class Main {

    public static void main(String[] args) {
        // Try-with-resources ensures proper cleanup of I/O streams
        try (FastScanner scanner = new FastScanner(System.in);
             PrintWriter out = new PrintWriter(System.out)) {

            int x1 = scanner.nextInt();
            int y1 = scanner.nextInt();
            int x2 = scanner.nextInt();
            int y2 = scanner.nextInt();
            int x3 = scanner.nextInt();
            int y3 = scanner.nextInt();

            out.println(calculateResult(x1, y1, x2, y2, x3, y3));
        } catch (IOException e) {
            System.err.println("Input/Output error: " + e.getMessage());
        }
    }

    /**
     * Determines the minimum number of straight lines required to connect three points.
     * 
     * @return 1 if all points are collinear (vertical or horizontal)
     *         2 if any two points share an X or Y coordinate (forms an 'L' or 'V' shape)
     *         3 otherwise (general triangle)
     */
    private static int calculateResult(int x1, int y1, int x2, int y2, int x3, int y3) {
        // Check for vertical or horizontal collinearity
        boolean collinear = (x1 == x2 && x2 == x3) || (y1 == y2 && y2 == y3);
        if (collinear) {
            return 1;
        }

        // Check if any pair of points shares an X or Y coordinate
        boolean shareX = (x1 == x2) || (x1 == x3) || (x2 == x3);
        boolean shareY = (y1 == y2) || (y1 == y3) || (y2 == y3);

        // If they share a coordinate, they can be connected with 2 lines.
        // Otherwise, they form a general triangle requiring 3 lines.
        return (shareX || shareY) ? 2 : 3;
    }

    /**
     * High-performance input scanner for competitive programming and heavy I/O.
     */
    private static class FastScanner implements AutoCloseable {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        public String next() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) {
                    throw new IOException("Unexpected end of input");
                }
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        @Override
        public void close() throws IOException {
            br.close();
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

public class Main {

    /**
     * Immutable value class to hold 2D coordinates.
     * Improves readability and eliminates magic index access like coord[i][0].
     */
    private static class Point {
        final int x, y;

        Point(int x, int y) {
            this.x = x;
            this.y = y;
        }
    }

    private static PrintWriter out;
    private static FastScanner scanner;

    public static void main(String[] args) throws IOException {
        out = new PrintWriter(System.out);
        scanner = new FastScanner(System.in);

        int testCases = 1;
        while (testCases-- > 0) {
            solve();
        }
        out.flush();
    }

    /**
     * Processes a single test case.
     * Reads three points, counts axis-aligned pair matches,
     * and evaluates geometric alignment conditions to determine the output.
     */
    private static void solve() throws IOException {
        Point[] points = new Point[3];
        for (int i = 0; i < 3; i++) {
            points[i] = new Point(scanner.nextInt(), scanner.nextInt());
        }

        int sameXCount = 0;
        int sameYCount = 0;

        // Count how many pairs share the same x or y coordinate
        for (int i = 0; i < 3; i++) {
            for (int j = i + 1; j < 3; j++) {
                if (points[i].x == points[j].x) sameXCount++;
                if (points[i].y == points[j].y) sameYCount++;
            }
        }

        int result = 3;

        // Case 1: All three points are vertically or horizontally aligned
        if (sameXCount == 3 || sameYCount == 3) {
            result = 1;
        } 
        // Case 2: Exactly one pair shares an axis. Check for specific collinearity/alignment.
        else if (sameXCount == 1 || sameYCount == 1) {
            for (int i = 0; i < 3; i++) {
                for (int j = 0; j < 3; j++) {
                    if (i == j) continue;

                    for (int k = 0; k < 3; k++) {
                        if (k == i || k == j) continue;

                        // Check horizontal alignment condition
                        if (points[i].y == points[j].y) {
                            if ((points[k].x <= points[i].x || points[k].x >= points[j].x) && points[i].x < points[j].x) {
                                out.println(2);
                                return;
                            }
                        }

                        // Check vertical alignment condition
                        if (points[i].x == points[j].x) {
                            if ((points[k].y <= points[i].y || points[k].y >= points[j].y) && points[i].y <= points[j].y) {
                                out.println(2);
                                return;
                            }
                        }
                    }
                }
            }
        }

        out.println(result);
    }

    /**
     * Optimized fast I/O scanner for competitive programming.
     * Contains only the methods actually used in the program.
     */
    private static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        public String next() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) throw new IOException("End of input stream");
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}

