            Point first = new Point(scanner.nextLong(), scanner.nextLong());
            Point second = new Point(scanner.nextLong(), scanner.nextLong());
            Point third = new Point(scanner.nextLong(), scanner.nextLong());

            output.println(getResult(first, second, third).getCode());
        }
    }

    /**
     * Determines the geometric relationship between three points.
     */
    private static ResultType getResult(Point p1, Point p2, Point p3) {
        // Check if all three points lie on the same vertical or horizontal line
        if ((p1.x == p2.x && p2.x == p3.x) || (p1.y == p2.y && p2.y == p3.y)) {
            return ResultType.COLLINEAR_SAME_LINE;
        }

        // Check if any point lies on the line segment formed by the other two
        if (isPointOnSegment(p1, p2, p3) ||
            isPointOnSegment(p1, p3, p2) ||
            isPointOnSegment(p2, p3, p1)) {
            return ResultType.POINT_ON_SEGMENT;
        }

        return ResultType.OTHER;
    }

    /**
     * Checks if p3 lies on the line segment between p1 and p2.
     * Returns true only if p1 and p2 share a coordinate (x or y) and p3 falls 
     * within the inclusive bounds of that segment.
     */
    private static boolean isPointOnSegment(Point p1, Point p2, Point p3) {
        if (p1.x == p2.x) {
            return p3.y >= Math.min(p1.y, p2.y) && p3.y <= Math.max(p1.y, p2.y);
        }
        if (p1.y == p2.y) {
            return p3.x >= Math.min(p1.x, p2.x) && p3.x <= Math.max(p1.x, p2.x);
        }
        return false;
    }

    /**
     * Immutable class representing a 2D point with long coordinates.
     */
    private static class Point {
        private final long x;
        private final long y;

        public Point(long x, long y) {
            this.x = x;
            this.y = y;
        }

        public long getX() { return x; }
        public long getY() { return y; }
    }

