            out.println(solve(x1, y1, x2, y2, x3, y3));
            out.flush();
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    /**
     * Determines the result based on the geometric arrangement of three points.
     * Returns:
     *   1 - All three points are collinear (share the same x or same y coordinate).
     *   2 - Two points are aligned, and the third point lies outside or on the boundary of their segment.
     *   3 - Two points are aligned, and the third point lies strictly between them.
     */
    private static int solve(int x1, int y1, int x2, int y2, int x3, int y3) {
        if ((x1 == x2 && x2 == x3) || (y1 == y2 && y2 == y3)) {
            return 1;
        }

        // Check vertical alignments (same x coordinate)
        if (x1 == x2) return checkAlignment(y1, y2, y3);
        if (x1 == x3) return checkAlignment(y1, y3, y2);
        if (x2 == x3) return checkAlignment(y2, y3, y1);

        // Check horizontal alignments (same y coordinate)
        if (y1 == y2) return checkAlignment(x1, x2, x3);
        if (y1 == y3) return checkAlignment(x1, x3, x2);
        if (y2 == y3) return checkAlignment(x2, x3, x1);

        // No alignment found
        return 3;
    }

    /**
     * Evaluates whether the third coordinate falls outside or on the boundary 
     * of the segment defined by the first two coordinates.
     */
    private static int checkAlignment(int coord1, int coord2, int thirdCoord) {
        int min = Math.min(coord1, coord2);
        int max = Math.max(coord1, coord2);
        return (thirdCoord <= min || thirdCoord >= max) ? 2 : 3;
    }

