    public static void solve(InputReader in, PrintWriter out) {
        int[] x = new int[3];
        int[] y = new int[3];

        // Read coordinates for the 3 points
        for (int i = 0; i < 3; i++) {
            x[i] = in.nextInt();
            y[i] = in.nextInt();
        }

        // Case 1: All points lie on a vertical line
        if (x[0] == x[1] && x[1] == x[2]) {
            out.println(1);
            return;
        }

        // Case 2: All points lie on a horizontal line
        if (y[0] == y[1] && y[1] == y[2]) {
            out.println(1);
            return;
        }

        // Case 3: Check for axis-aligned segments formed by pairs
        for (int i = 0; i < 3; i++) {
            for (int j = i + 1; j < 3; j++) {
                int k = 3 - i - j; // Index of the third point

                if (y[i] == y[j]) { // Horizontal segment
                    if (isStrictlyBetween(x[k], x[i], x[j])) {
                        out.println(3);
                    } else {
                        out.println(2);
                    }
                    return;
                }

                if (x[i] == x[j]) { // Vertical segment
                    if (isStrictlyBetween(y[k], y[i], y[j])) {
                        out.println(3);
                    } else {
                        out.println(2);
                    }
                    return;
                }
            }
        }

        // Case 4: No axis-aligned segments found
        out.println(3);
    }

    /**
     * Checks if value lies strictly between a and b, regardless of order.
     */
    private static boolean isStrictlyBetween(int value, int a, int b) {
