    /**
     * Determines the alignment category of three points on a 2D grid.
     * Returns 1 if all three points are collinear on the same vertical or horizontal line.
     * Returns 2 if exactly two points share a vertical or horizontal line.
     * Returns 3 otherwise.
     */
    private int calculateResult(int x1, int y1, int x2, int y2, int x3, int y3) {
        if (areAllOnSameAxis(x1, x2, x3) || areAllOnSameAxis(y1, y2, y3)) {
