public class D617 {

    public static void main(String[] args) {
        // Using Scanner for improved readability and robustness compared to manual IO parsing.
        // Scanner handles whitespace and integer parsing automatically.
        Scanner scanner = new Scanner(System.in);

        if (scanner.hasNextInt()) {
            int x1 = scanner.nextInt();
            int y1 = scanner.nextInt();
            int x2 = scanner.nextInt();
            int y2 = scanner.nextInt();
            int x3 = scanner.nextInt();
            int y3 = scanner.nextInt();

            System.out.println(countLines(x1, y1, x2, y2, x3, y3));
        }
        scanner.close();
    }

    /**
     * Calculates the number of lines based on the coordinates of three points.
     * 
     * Logic preserved from original implementation:
     * 1. Returns 1 if all three points are collinear on a vertical or horizontal line.
     * 2. Returns 2 if any two points form a segment on a vertical or horizontal line,
     *    and the third point lies outside the range of that segment (strictly outside or on boundary).
     * 3. Returns 3 otherwise.
     */
    private static int countLines(int x1, int y1, int x2, int y2, int x3, int y3) {
        // Check if all three points are on the same vertical line (x1=x2=x3)
        // or on the same horizontal line (y1=y2=y3).
        if ((x1 == x2 && x2 == x3) || (y1 == y2 && y2 == y3)) {
            return 1;
        }

        // Check pairs for the condition that results in 2 lines.
        // We check if a pair forms a vertical or horizontal segment,
        // and if the third point is outside the segment's range.

        // Pair (1, 2)
        if (isAlignedAndOutside(x1, y1, x2, y2, x3, y3)) {
            return 2;
        }
        // Pair (1, 3)
        if (isAlignedAndOutside(x1, y1, x3, y3, x2, y2)) {
            return 2;
        }
        // Pair (2, 3)
        if (isAlignedAndOutside(x2, y2, x3, y3, x1, y1)) {
            return 2;
        }

        return 3;
    }

    /**
     * Checks if the segment formed by (x1, y1) and (x2, y2) is axis-aligned,
     * and if the point (x3, y3) lies outside the segment's range.
     * 
     * This method replicates the logic of checking x-equality then y-equality
     * for a pair of points as found in the original code.
     */
    private static boolean isAlignedAndOutside(int x1, int y1, int x2, int y2, int x3, int y3) {
        // Check if points 1 and 2 form a vertical segment
        if (x1 == x2) {
            // Check if point 3's Y coordinate is outside the range [min(y1,y2), max(y1,y2)]
            if (isOutsideRange(y3, Math.min(y1, y2), Math.max(y1, y2))) {
                return true;
            }
        }

        // Check if points 1 and 2 form a horizontal segment
        // Note: We use a separate if block to handle the case where points 1 and 2 are identical.
        // In the original code, x-equality checks were separate from y-equality checks.
        if (y1 == y2) {
            // Check if point 3's X coordinate is outside the range [min(x1,x2), max(x1,x2)]
            if (isOutsideRange(x3, Math.min(x1, x2), Math.max(x1, x2))) {
                return true;
            }
        }

        return false;
    }

    /**
     * Checks if a value is outside or on the boundary of a range [min, max].
     * Equivalent to: val <= min || val >= max
     */
    private static boolean isOutsideRange(int val, int min, int max) {
        return val <= min || val >= max;
    }
}

import java.util.Scanner;

/**
 * Solves the triangle axis alignment problem by analyzing the geometric 
 * relationship between three points and the coordinate axes.
 */
public class TriangleAxisAlignment {

    /** Immutable 2D point representation */
    public static class Point {
        private final long x, y;

        public Point(long x, long y) {
            this.x = x;
            this.y = y;
        }

        public long x() { return x; }
        public long y() { return y; }
    }

    /** Immutable line segment representation */
    public static class Line {
        private final Point p1, p2;

        public Line(Point p1, Point p2) {
            this.p1 = p1;
            this.p2 = p2;
        }

        public Point p1() { return p1; }
        public Point p2() { return p2; }

        public long dx() { return p2.x() - p1.x(); }
        public long dy() { return p2.y() - p1.y(); }

        /**
         * Checks if this line is perpendicular to another line using the dot product 
         * of their direction vectors.
         */
        public boolean isPerpendicularTo(Line other) {
            return this.dx() * other.dx() + this.dy() * other.dy() == 0;
        }
    }

    public static void main(String[] args) {
        // Use try-with-resources to ensure the Scanner is properly closed
        try (Scanner scanner = new Scanner(System.in)) {
            Point a = new Point(scanner.nextLong(), scanner.nextLong());
            Point b = new Point(scanner.nextLong(), scanner.nextLong());
            Point c = new Point(scanner.nextLong(), scanner.nextLong());

            System.out.print(solve(a, b, c));
        }
    }

    /**
     * Determines the classification of the triangle formed by three points 
     * based on axis alignment and projection bounds.
     */
    private static int solve(Point a, Point b, Point c) {
        Line ab = new Line(a, b);
        Line ac = new Line(a, c);
        Line bc = new Line(b, c);

        // Reference lines representing the X and Y axes
        Line xAxis = new Line(new Point(0, 0), new Point(1, 0));
        Line yAxis = new Line(new Point(0, 0), new Point(0, 1));

        // Case 1: AB and AC are both parallel to the same axis (collinear on an axis)
        if ((ab.isPerpendicularTo(xAxis) && ac.isPerpendicularTo(xAxis)) ||
            (ab.isPerpendicularTo(yAxis) && ac.isPerpendicularTo(yAxis))) {
            return 1;
        }

        // Case 2: Any axis-aligned side has the third point outside its bounding projection
        Line[] sides = {ab, ac, bc};
        Point[] thirdPoints = {c, b, a};

        for (int i = 0; i < 3; i++) {
            Line side = sides[i];
            Point third = thirdPoints[i];

            if (side.isPerpendicularTo(xAxis)) { // Vertical side
                if (isPointOutsideBounds(third, side, true)) {
                    return 2;
                }
            } else if (side.isPerpendicularTo(yAxis)) { // Horizontal side
                if (isPointOutsideBounds(third, side, false)) {
                    return 2;
                }
            }
        }

        // Case 3: Default fallback
        return 3;
    }

    /**
     * Checks if a point lies outside or on the boundary of a line segment's 
     * projection along a specific axis.
     *
     * @param point   The point to evaluate
     * @param segment The line segment defining the bounds
     * @param checkY  If true, evaluates the Y-axis range; otherwise evaluates X-axis range
     * @return true if the point is outside the segment's bounds on the specified axis
     */
    private static boolean isPointOutsideBounds(Point point, Line segment, boolean checkY) {
        if (checkY) {
            long minY = Math.min(segment.p1().y(), segment.p2().y());
            long maxY = Math.max(segment.p1().y(), segment.p2().y());
            return point.y() <= minY || point.y() >= maxY;
        } else {
            long minX = Math.min(segment.p1().x(), segment.p2().x());
            long maxX = Math.max(segment.p1().x(), segment.p2().x());
            return point.x() <= minX || point.x() >= maxX;
        }
    }
}

import java.io.BufferedReader;
import java.io.File;
import java.io.FileReader;
import java.io.IOException;
import java.io.InputStreamReader;

/**
 * Determines the minimum score based on coordinate alignment rules for three points.
 * Refactored for improved readability, maintainability, and robustness.
 */
public class PointAlignmentChecker {

    public static void main(String[] args) throws IOException {
        try (BufferedReader reader = createInputReader()) {
            long[] p1 = readPoint(reader);
            long[] p2 = readPoint(reader);
            long[] p3 = readPoint(reader);

            int result = calculateResult(p1, p2, p3);
            System.out.println(result);
        }
    }

    /**
     * Creates a BufferedReader that reads from a file named "in" if it exists,
     * otherwise falls back to standard input.
     */
    private static BufferedReader createInputReader() throws IOException {
        File file = new File("in");
        if (file.exists()) {
            return new BufferedReader(new FileReader(file));
        }
        return new BufferedReader(new InputStreamReader(System.in));
    }

    /**
     * Reads a single line containing two space-separated long values representing coordinates.
     */
    private static long[] readPoint(BufferedReader reader) throws IOException {
        String line = reader.readLine();
        if (line == null) {
            throw new IOException("Unexpected end of input: expected coordinate pair.");
        }
        String[] tokens = line.trim().split("\\s+");
        if (tokens.length < 2) {
            throw new IOException("Invalid format: expected two coordinates per line.");
        }
        return new long[]{Long.parseLong(tokens[0]), Long.parseLong(tokens[1])};
    }

    /**
     * Calculates the minimum value based on coordinate alignment rules.
     * Priority: 1 (all x or all y equal) > 2 (pair aligned, third outside range) > 3 (default).
     */
    private static int calculateResult(long[] p1, long[] p2, long[] p3) {
        long x1 = p1[0], y1 = p1[1];
        long x2 = p2[0], y2 = p2[1];
        long x3 = p3[0], y3 = p3[1];

        // Check for full alignment (result = 1)
        if (x1 == x2 && x1 == x3) return 1;
        if (y1 == y2 && y1 == y3) return 1;

        // Check for partial alignment (result = 2)
        if (hasPartialAlignment(x1, y1, x2, y2, x3, y3)) {
            return 2;
        }

        // Default case
        return 3;
    }

    /**
     * Checks if any pair of points shares a coordinate axis,
     * and the third point's corresponding coordinate lies outside the range of the pair.
     */
    private static boolean hasPartialAlignment(long x1, long y1, long x2, long y2, long x3, long y3) {
        return isPairAlignedAndThirdOutside(x1, y1, x2, y2, x3, y3)
            || isPairAlignedAndThirdOutside(x1, y1, x3, y3, x2, y2)
            || isPairAlignedAndThirdOutside(x2, y2, x3, y3, x1, y1);
    }

    /**
     * Determines if points A and B share an axis, and point C's coordinate on that axis
     * is outside the inclusive range defined by A and B.
     */
    private static boolean isPairAlignedAndThirdOutside(long xA, long yA, long xB, long yB, long xC, long yC) {
        if (xA == xB) {
            return isOutsideRange(yA, yB, yC);
        }
        if (yA == yB) {
            return isOutsideRange(xA, xB, xC);
        }
        return false;
    }

    /**
     * Returns true if c is not strictly between a and b.
     * Equivalent to: c <= min(a, b) || c >= max(a, b)
     */
    private static boolean isOutsideRange(long a, long b, long c) {
        long min = Math.min(a, b);
        long max = Math.max(a, b);
        return c <= min || c >= max;
    }
}

