public class Main {
    public static void main(String[] args) {
        FastReader in = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        TaskD solver = new TaskD();
        solver.solve(1, in, out);

        out.flush(); // Ensure all buffered output is written
        out.close();
    }

    /**
     * Solves Task D. Reads a 3x2 integer grid and determines a result based on 
     * column equality, distinctness, and relative value ordering.
     */
    static class TaskD {
        private static final int ROWS = 3;
        private static final int COLS = 2;

        public void solve(int testNumber, FastReader in, PrintWriter out) {
            int[][] grid = in.nextIntMap(ROWS, COLS);

            // Check if all values in column 0 are equal
            if (areAllEqual(grid, 0)) {
                out.println(1);
                return;
            }
            // Check if all values in column 1 are equal
            if (areAllEqual(grid, 1)) {
                out.println(1);
                return;
            }

            // Check if all values in both columns are strictly distinct
            if (areAllDistinct(grid, 0) && areAllDistinct(grid, 1)) {
                out.println(3);
                return;
            }

            // Check specific relative ordering condition for output 2
            for (int col = 0; col < COLS; col++) {
                for (int i = 0; i < ROWS; i++) {
                    for (int j = i + 1; j < ROWS; j++) {
                        if (grid[i][col] == grid[j][col]) {
                            // Since ROWS = 3, the remaining index is 3 - i - j
                            int k = ROWS - i - j;

                            int valK = grid[k][1 - col];
                            int valI = grid[i][1 - col];
                            int valJ = grid[j][1 - col];

                            int minVal = Math.min(valI, valJ);
                            int maxVal = Math.max(valI, valJ);

                            // Original condition: valK <= min || max <= valK
                            // This is equivalent to checking if valK is NOT strictly between min and max
                            if (valK <= minVal || valK >= maxVal) {
                                out.println(2);
                                return;
                            }
                        }
                    }
                }
            }

            // Fallback result
            out.println(3);
        }

        /**
         * Returns true if all values in the specified column are identical.
         */
        private boolean areAllEqual(int[][] grid, int col) {
            int first = grid[0][col];
            for (int i = 1; i < grid.length; i++) {
                if (grid[i][col] != first) {
                    return false;
                }
            }
            return true;
        }

        /**
         * Returns true if all values in the specified column are strictly distinct.
         */
        private boolean areAllDistinct(int[][] grid, int col) {
            for (int i = 0; i < grid.length; i++) {
                for (int j = i + 1; j < grid.length; j++) {
                    if (grid[i][col] == grid[j][col]) {
                        return false;
                    }
                }
            }
            return true;
        }
    }

    /**
     * Fast I/O utility for competitive programming environments.
     */
    static class FastReader {
        private final InputStream stream;
        private final byte[] buf = new byte[8192];
        private int curChar;
        private int numReadChars;

        public FastReader(InputStream stream) {
            this.stream = stream;
        }

        public int read() {
            if (numReadChars == -1) {
                throw new InputMismatchException();
            }
            if (curChar >= numReadChars) {
                curChar = 0;
                try {
                    numReadChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numReadChars <= 0) {
                    return -1;
                }
            }
            return buf[curChar++];
        }

        public int nextInt() {
            int c = read();
            while (isSpaceChar(c)) {
                if (c == -1) {
                    throw new InputMismatchException("Unexpected end of input");
                }
                c = read();
            }

            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }

            int res = 0;
            do {
                // Skip commas if present between numbers
                if (c == ',') {
                    c = read();
                }
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                res *= 10;
                res += c - '0';
                c = read();
            } while (!isSpaceChar(c));

            return res * sgn;
        }

        public int[] nextIntArray(int n) {
            int[] array = new int[n];
            for (int i = 0; i < n; i++) {
                array[i] = nextInt();
            }
            return array;
        }

        public int[][] nextIntMap(int n, int m) {
            int[][] array = new int[n][];
            for (int i = 0; i < n; i++) {
                array[i] = nextIntArray(m);
            }
            return array;
        }

        public boolean isSpaceChar(int c) {
            return isWhitespace(c);
        }

        public static boolean isWhitespace(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.OutputStream;
import java.io.PrintWriter;
import java.util.StringTokenizer;

public class Main {
    public static void main(String[] args) {
        InputReader in = new InputReader(System.in);
        PrintWriter out = new PrintWriter(System.out);
        TaskD.solve(in, out);
        out.close();
    }

    static class TaskD {
        // Constants for readability and maintainability
        private static final int NUM_POINTS = 3;
        private static final int COORDS_PER_POINT = 2;
        private static final int AXIS_X = 0;
        private static final int AXIS_Y = 1;
        private static final int RESULT_ALIGNED = 1;
        private static final int RESULT_OUTSIDE = 2;
        private static final int RESULT_DEFAULT = 3;

        public static void solve(InputReader in, PrintWriter out) {
            int[][] points = readPoints(in);

            if (isAxisAligned(points)) {
                out.print(RESULT_ALIGNED);
                return;
            }

            int minResult = RESULT_DEFAULT;
            for (int i = 0; i < NUM_POINTS; i++) {
                for (int j = 0; j < NUM_POINTS; j++) {
                    if (i == j) continue;
                    for (int k = 0; k < NUM_POINTS; k++) {
                        if (k == i || k == j) continue;
                        for (int axis = AXIS_X; axis <= AXIS_Y; axis++) {
                            minResult = Math.min(minResult, checkAxisCondition(points, i, j, k, axis));
                        }
                    }
                }
            }
            out.print(minResult);
        }

        private static int[][] readPoints(InputReader in) {
            int[][] points = new int[NUM_POINTS][COORDS_PER_POINT];
            for (int i = 0; i < NUM_POINTS; i++) {
                points[i][AXIS_X] = in.nextInt();
                points[i][AXIS_Y] = in.nextInt();
            }
            return points;
        }

        private static boolean isAxisAligned(int[][] points) {
            int x0 = points[0][AXIS_X], x1 = points[1][AXIS_X], x2 = points[2][AXIS_X];
            int y0 = points[0][AXIS_Y], y1 = points[1][AXIS_Y], y2 = points[2][AXIS_Y];
            return (x0 == x1 && x1 == x2) || (y0 == y1 && y1 == y2);
        }

        private static int checkAxisCondition(int[][] points, int i, int j, int k, int axis) {
            // Points i and j must share the same coordinate on the current axis
            if (points[i][axis] != points[j][axis]) {
                return RESULT_DEFAULT;
            }

            int perpAxis = 1 - axis;
            int minVal = Math.min(points[i][perpAxis], points[j][perpAxis]);
            int maxVal = Math.max(points[i][perpAxis], points[j][perpAxis]);
            int kVal = points[k][perpAxis];

            // If point k lies outside or exactly on the boundary of the segment formed by i and j
            if (kVal <= minVal || kVal >= maxVal) {
                return RESULT_OUTSIDE;
            }
            return RESULT_DEFAULT;
        }
    }

    static class InputReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) {
                        return null;
                    }
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            String token = next();
            if (token == null) {
                throw new RuntimeException("Unexpected end of input");
            }
            return Integer.parseInt(token);
        }
    }
}

