/**
 * Task class containing the solution logic.
 */
class Task {
    /**
     * Solves the problem.
     *
     * @param in  InputReader for reading data
     * @param out PrintWriter for writing output
     */
    public void solve(InputReader in, PrintWriter out) {
        long[] x = new long[3];
        long[] y = new long[3];
        // Use Generics to avoid raw type warnings and ensure type safety
        HashSet<Long> uniqueX = new HashSet<>();
        HashSet<Long> uniqueY = new HashSet<>();

        // Read 3 points (x, y)
        for (int i = 0; i < 3; i++) {
            x[i] = in.nextLong();
            y[i] = in.nextLong();
            uniqueX.add(x[i]);
            uniqueY.add(y[i]);
        }

        // Case 1: All points lie on a vertical line (same x) or horizontal line (same y)
        if (uniqueX.size() == 1 || uniqueY.size() == 1) {
            out.println(1);
            return;
        }

        // Case 2: Check for specific alignment condition
        // We check all permutations of indices (i, j, k) to see if point k is 
        // "aligned" with points i and j.
        boolean found = false;
        for (int i = 0; i < 3; i++) {
            for (int j = 0; j < 3; j++) {
                for (int k = 0; k < 3; k++) {
                    // Indices must be distinct
                    if (i == j || i == k || j == k) {
                        continue;
                    }

                    // Check alignment in standard orientation
                    if (isAligned(x[i], y[i], x[j], y[j], x[k], y[k])) {
                        found = true;
                        break;
                    }
                    // Check alignment in transposed orientation (swap x and y)
                    if (isAligned(y[i], x[i], y[j], x[j], y[k], x[k])) {
                        found = true;
                        break;
                    }
                }
                if (found) break;
            }
            if (found) break;
        }

        if (found) {
            out.println(2);
        } else {
            out.println(3);
        }
    }

    /**
     * Determines if point 2 is aligned with points 0 and 1.
     * Alignment condition:
     * 1. Point 2's x-coordinate is between Point 0's and Point 1's x-coordinates.
     * 2. Point 2's y-coordinate matches either Point 0's or Point 1's y-coordinate.
     *
     * @param x0 X-coordinate of point 0
     * @param y0 Y-coordinate of point 0
     * @param x1 X-coordinate of point 1
     * @param y1 Y-coordinate of point 1
     * @param x2 X-coordinate of point 2
     * @param y2 Y-coordinate of point 2
     * @return true if aligned, false otherwise
     */
    private static boolean isAligned(long x0, long y0, long x1, long y1, long x2, long y2) {
        // Check if x2 is between x0 and x1 (inclusive)
        boolean xBetween = (x0 <= x2 && x2 <= x1) || (x1 <= x2 && x2 <= x0);
        // Check if y2 matches y0 or y1
        boolean yMatch = (y2 == y0) || (y2 == y1);
        return xBetween && yMatch;
    }
}

