import java.util.Scanner;

public class ProblemFTwo {

    public static void main(String[] args) {
        // Use try-with-resources to ensure the Scanner is closed automatically
        try (Scanner scanner = new Scanner(System.in)) {

            // Read the coordinates of the three points
            // Point 1
            int x1 = scanner.nextInt();
            int y1 = scanner.nextInt();
            // Point 2
            int x2 = scanner.nextInt();
            int y2 = scanner.nextInt();
            // Point 3
            int x3 = scanner.nextInt();
            int y3 = scanner.nextInt();

            // Determine the result based on the geometric properties
            int result = solve(x1, y1, x2, y2, x3, y3);

            System.out.println(result);
        }
    }

    /**
     * Solves the problem logic based on the coordinates of three points.
     * 
     * Logic breakdown:
     * 1. If all points are collinear (all x same OR all y same), output 1.
     * 2. If any pair shares an X coordinate (vertical alignment):
     *    - Check if the third point's Y is strictly between the pair's Ys.
     *    - If yes -> 3, else -> 2.
     * 3. If any pair shares a Y coordinate (horizontal alignment):
     *    - Check if the third point's X is strictly between the pair's Xs.
     *    - If yes -> 3, else -> 2.
     * 4. Otherwise, output 3.
     */
    private static int solve(int x1, int y1, int x2, int y2, int x3, int y3) {

        // Case 1: Collinear check (Vertical line x1=x2=x3 OR Horizontal line y1=y2=y3)
        if ((x1 == x2 && x2 == x3) || (y1 == y2 && y2 == y3)) {
            return 1;
        }

        // Case 2: Vertical Alignment (Shared X)
        // Priority order: (1,2), (2,3), (1,3)
        if (x1 == x2) {
            return isStrictlyBetween(y3, y1, y2) ? 3 : 2;
        } else if (x2 == x3) {
            return isStrictlyBetween(y1, y2, y3) ? 3 : 2;
        } else if (x1 == x3) {
            return isStrictlyBetween(y2, y1, y3) ? 3 : 2;
        }

        // Case 3: Horizontal Alignment (Shared Y)
        // Priority order: (1,2), (2,3), (1,3)
        if (y1 == y2) {
            return isStrictlyBetween(x3, x1, x2) ? 3 : 2;
        } else if (y2 == y3) {
            return isStrictlyBetween(x1, x2, x3) ? 3 : 2;
        } else if (y1 == y3) {
            return isStrictlyBetween(x2, x1, x3) ? 3 : 2;
        }

        // Case 4: No specific alignment found
        return 3;
    }

    /**
     * Helper method to check if a value is strictly between two other values.
     */
    private static boolean isStrictlyBetween(int val, int a, int b) {
        int min = Math.min(a, b);
        int max = Math.max(a, b);
        return val > min && val < max;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

/**
 * Main class for solving the geometric coordinate relationship problem.
 */
public class Main {
    private final ConsoleIO io;

    public Main(ConsoleIO io) {
        this.io = io;
    }

    public static void main(String[] args) {
        ConsoleIO io = new ConsoleIO();
        new Main(io).solve();
        io.flush();
    }

    /**
     * Reads three coordinate pairs and determines their geometric relationship.
     */
    public void solve() {
        long[] p1 = readCoordinates();
        long[] p2 = readCoordinates();
        long[] p3 = readCoordinates();

        long x1 = p1[0], y1 = p1[1];
        long x2 = p2[0], y2 = p2[1];
        long x3 = p3[0], y3 = p3[1];

        // Case 1: All three points are collinear on a vertical or horizontal line
        if (x1 == x2 && x2 == x3 || y1 == y2 && y2 == y3) {
            io.writeLine("1");
            return;
        }

        // Case 2: One point lies on the line segment between the other two
        if (isBetweenOnAxis(x1, x2, x3, y1, y2, y3) ||
            isBetweenOnAxis(y1, y2, y3, x1, x2, x3)) {
            io.writeLine("2");
        } else {
            // Case 3: General position (non-collinear or not on segment)
            io.writeLine("3");
        }
    }

    /**
     * Reads a single line of two integers and returns them as a long array.
     */
    private long[] readCoordinates() {
        int[] raw = io.readIntArray();
        return new long[]{raw[0], raw[1]};
    }

    /**
     * Determines if the third point lies between the first two points along a specific axis.
     * This is used to check collinearity and betweenness without floating-point arithmetic.
     */
    private boolean isBetweenOnAxis(long c1, long c2, long c3, long r1, long r2, long r3) {
        if (c1 == c2) {
            return r3 >= Math.min(r1, r2) && r3 <= Math.max(r1, r2);
        } else if (c1 == c3) {
            return r2 >= Math.min(r1, r3) && r2 <= Math.max(r1, r3);
        } else if (c2 == c3) {
            return r1 >= Math.min(r2, r3) && r1 <= Math.max(r2, r3);
        }
        return false;
    }

    /**
     * Handles console input and output operations.
     */
    static class ConsoleIO {
        private final BufferedReader br;
        private final PrintWriter out;
        private StringTokenizer st;

        public ConsoleIO() {
            this.br = new BufferedReader(new InputStreamReader(System.in));
            this.out = new PrintWriter(System.out);
        }

        public void flush() {
            out.flush();
            out.close();
        }

        public void writeLine(String s) {
            out.println(s);
        }

        public int[] readIntArray() {
            try {
                String line = br.readLine();
                if (line == null || line.trim().isEmpty()) {
                    return new int[0];
                }
                st = new StringTokenizer(line);
                int count = st.countTokens();
                int[] result = new int[count];
                for (int i = 0; i < count; i++) {
                    result[i] = Integer.parseInt(st.nextToken());
                }
                return result;
            } catch (IOException e) {
                throw new RuntimeException("Failed to read input from console", e);
            }
        }
    }
}

import java.io.PrintWriter;
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        PrintWriter out = new PrintWriter(System.out);

        solve(scanner, out);

        out.flush();
        out.close();
        scanner.close();
    }

    private static void solve(Scanner scanner, PrintWriter out) {
        int[][] points = new int[3][2];
        for (int i = 0; i < 3; i++) {
            points[i][0] = scanner.nextInt();
            points[i][1] = scanner.nextInt();
        }

        if (areAllPointsCollinear(points)) {
            out.println(1);
        } else if (hasPointOutsideSegment(points)) {
            out.println(2);
        } else {
            out.println(3);
        }
    }

    private static boolean areAllPointsCollinear(int[][] points) {
        return (points[0][0] == points[1][0] && points[1][0] == points[2][0]) ||
               (points[0][1] == points[1][1] && points[1][1] == points[2][1]);
    }

    private static boolean isPointOutsideSegment(int[] p1, int[] p2, int[] p3) {
        // Check if p1 and p2 share the same x-coordinate (vertical alignment)
        if (p1[0] == p2[0]) {
            int minY = Math.min(p1[1], p2[1]);
            int maxY = Math.max(p1[1], p2[1]);
            return p3[1] <= minY || p3[1] >= maxY;
        }
        // Check if p1 and p2 share the same y-coordinate (horizontal alignment)
        if (p1[1] == p2[1]) {
            int minX = Math.min(p1[0], p2[0]);
            int maxX = Math.max(p1[0], p2[0]);
            return p3[0] <= minX || p3[0] >= maxX;
        }
        return false;
    }

    private static boolean hasPointOutsideSegment(int[][] points) {
        // Check all three unique permutations where the third point lies outside 
        // the segment formed by the other two. The first two arguments are symmetric,
        // so checking 3 cases is sufficient and equivalent to the original 6.
        return isPointOutsideSegment(points[0], points[1], points[2]) ||
               isPointOutsideSegment(points[0], points[2], points[1]) ||
               isPointOutsideSegment(points[1], points[2], points[0]);
    }
}

import java.util.Scanner;

public class Polyline {

    /**
     * Helper class to represent a 2D coordinate point.
     * Encapsulating x and y coordinates improves readability and maintainability.
     */
    private static class Point {
        final int x;
        final int y;

        Point(int x, int y) {
            this.x = x;
            this.y = y;
        }
    }

    public static void main(String[] args) {
        // Use try-with-resources to ensure the Scanner is properly closed
        try (Scanner scan = new Scanner(System.in)) {

            // Basic input validation to prevent exceptions on empty input
            if (!scan.hasNextInt()) return;

            int x = scan.nextInt();
            int y = scan.nextInt();
            int x2 = scan.nextInt();
            int y2 = scan.nextInt();
            int x3 = scan.nextInt();
            int y3 = scan.nextInt();

            // Create Point objects to represent the coordinates
            Point p1 = new Point(x, y);
            Point p2 = new Point(x2, y2);
            Point p3 = new Point(x3, y3);

            // Calculate and print the result
            System.out.println(calculateGeometryType(p1, p2, p3));
        }
    }

    /**
     * Determines the geometric relationship between three points based on specific rules.
     * 
     * @return 1 if all three points are collinear (on the same vertical or horizontal line)
     *         2 if exactly two points share an axis, but the third is not strictly between them
     *         3 if the third point is strictly between two aligned points, or if no points are aligned (general triangle)
     */
    private static int calculateGeometryType(Point p1, Point p2, Point p3) {

        // Case 1: All three points are collinear (Vertical line)
        if (p1.x == p2.x && p2.x == p3.x) {
            return 1;
        }
        // Case 1: All three points are collinear (Horizontal line)
        if (p1.y == p2.y && p2.y == p3.y) {
            return 1;
        }

        // Case 2: The third point lies strictly between the other two on a shared axis

        // Check if P3 is strictly between P1 and P2 (Vertical)
        if (p1.x == p2.x && isStrictlyBetween(p3.y, p1.y, p2.y)) {
            return 3;
        }
        // Check if P3 is strictly between P1 and P2 (Horizontal)
        if (p1.y == p2.y && isStrictlyBetween(p3.x, p1.x, p2.x)) {
            return 3;
        }

        // Check if P2 is strictly between P1 and P3 (Vertical)
        if (p1.x == p3.x && isStrictlyBetween(p2.y, p1.y, p3.y)) {
            return 3;
        }
        // Check if P2 is strictly between P1 and P3 (Horizontal)
        if (p1.y == p3.y && isStrictlyBetween(p2.x, p1.x, p3.x)) {
            return 3;
        }

        // Check if P1 is strictly between P2 and P3 (Vertical)
        if (p2.x == p3.x && isStrictlyBetween(p1.y, p2.y, p3.y)) {
            return 3;
        }
        // Check if P1 is strictly between P2 and P3 (Horizontal)
        if (p2.y == p3.y && isStrictlyBetween(p1.x, p2.x, p3.x)) {
            return 3;
        }

        // Case 3: Two points share an axis (Vertical or Horizontal), 
        // but the third point is not strictly between them.
        if (p1.x == p2.x || p1.y == p2.y ||
            p1.x == p3.x || p1.y == p3.y ||
            p2.x == p3.x || p2.y == p3.y) {
            return 2;
        }

        // Case 4: General triangle (no points share an axis)
        // Note: The original code returns 3 for this case as well.
        return 3;
    }

    /**
     * Checks if a value is strictly between two other values.
     * This encapsulates the logic for finding min/max and comparing.
     */
    private static boolean isStrictlyBetween(int val, int v1, int v2) {
        int min = Math.min(v1, v2);
        int max = Math.max(v1, v2);
        return val > min && val < max;
    }
}

