/**
 * Refactored Main class.
 * 
 * Key Improvements:
 * 1. Replaced raw int arrays with a dedicated Point class for semantic clarity.
 * 2. Extracted coordinate reading and transposition into focused methods.
 * 3. Replaced magic numbers with named constants.
 * 4. Improved variable naming and removed confusing index arithmetic.
 * 5. Used Comparator.comparingInt for safer and more readable sorting.
 * 6. Added proper resource flushing with try-finally.
 * 7. Added JavaDoc and structural formatting for better readability.
 */
public class Main {
    private static final int NUM_POINTS = 3;

    public static void main(String[] args) {
        InputReader in = new InputReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            Point[] points = readPoints(in);
            int resultOriginalOrientation = solve(points);

            Point[] transposedPoints = transposePoints(points);
            int resultTransposedOrientation = solve(transposedPoints);

            out.println(Math.min(resultOriginalOrientation, resultTransposedOrientation));
        } finally {
            out.flush();
        }
    }

    /**
     * Reads NUM_POINTS pairs of coordinates from the input stream.
     */
    private static Point[] readPoints(InputReader in) {
        Point[] points = new Point[NUM_POINTS];
        for (int i = 0; i < NUM_POINTS; i++) {
            points[i] = new Point(in.nextInt(), in.nextInt());
        }
        return points;
    }

    /**
     * Creates a new array of points with x and y coordinates swapped.
     */
    private static Point[] transposePoints(Point[] points) {
        Point[] transposed = new Point[points.length];
        for (int i = 0; i < points.length; i++) {
            transposed[i] = new Point(points[i].y, points[i].x);
        }
        return transposed;
    }

    /**
     * Solves the problem based on the geometric arrangement of points.
     * Note: This method sorts the input array internally by x-coordinate.
     */
    private static int solve(Point[] points) {
        Arrays.sort(points, Comparator.comparingInt(p -> p.x));

        // If all points share the same x-coordinate
        if (points[0].x == points[1].x && points[1].x == points[2].x) {
            return 1;
        }

        // Check adjacent pairs after sorting by x-coordinate
        for (int i = 0; i < points.length - 1; i++) {
            if (points[i].x == points[i + 1].x) {
                int minY = Math.min(points[i].y, points[i + 1].y);
                int maxY = Math.max(points[i].y, points[i + 1].y);
                // The third point is the one not included in the current adjacent pair
                int thirdY = points[2 - i].y;

                if (thirdY > minY && thirdY < maxY) {
                    return 3;
                }
                return 2;
            }
        }

        return 3;
    }

    /**
     * Represents a 2D point with integer coordinates.
     */
    static class Point {
        final int x;
        final int y;

        Point(int x, int y) {
            this.x = x;
            this.y = y;
        }

        @Override
        public String toString() {
            return "(" + x + ", " + y + ")";
        }
    }

    /**
     * Fast I/O reader commonly used in competitive programming.
     * Kept largely unchanged to preserve performance characteristics.
     */
    static class InputReader {
        private final InputStream stream;
        private final byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        private int next() {
            if (numChars == -1) {
                throw new InputMismatchException();
            }
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0) {
                    return -1;
                }
            }
            return buf[curChar++];
        }

        public char nextChar() {
            int c = next();
            while (isSpaceChar(c)) {
                c = next();
            }
            if ('a' <= c && c <= 'z') {
                return (char) c;
            }
            if ('A' <= c && c <= 'Z') {
                return (char) c;
            }
            throw new InputMismatchException();
        }

        public String nextToken() {
            int c = next();
            while (isSpaceChar(c)) {
                c = next();
            }
            StringBuilder res = new StringBuilder();
            do {
                res.append((char) c);
                c = next();
            } while (!isSpaceChar(c));
            return res.toString();
        }

        public int nextInt() {
            int c = next();
            while (isSpaceChar(c)) {
                c = next();
            }
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = next();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                res *= 10;
                res += c - '0';
                c = next();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public long nextLong() {
            int c = next();
            while (isSpaceChar(c)) {
                c = next();
            }
            long sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = next();
            }
            long res = 0;
            do {
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                res *= 10;
                res += c - '0';
                c = next();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        @FunctionalInterface
        public interface SpaceCharFilter {
            boolean isSpaceChar(int ch);
        }
    }

    /**
     * Utility method for debugging array contents.
     */
    static void debug(Object... o) {
        System.err.println(Arrays.deepToString(o));
    }
}

import java.io.*;
import java.util.*;

/**
 * Main application class for processing coordinate data.
 * Handles input/output, problem solving logic, and provides a fast scanner.
 */
public class Main {

    private static final boolean DEBUG_FILE_MODE = false;
    private static final String DEBUG_FILE_PATH = "src/T";

    private FastScanner in;
    private PrintWriter out;

    public static void main(String[] args) {
        new Main().run();
    }

    /**
     * Orchestrates execution: initializes I/O, runs the solver, and ensures cleanup.
     */
    public void run() {
        if (DEBUG_FILE_MODE) {
            try {
                in = new FastScanner(new FileInputStream(DEBUG_FILE_PATH));
            } catch (FileNotFoundException e) {
                e.printStackTrace();
                return;
            }
            System.out.println("FILE_INPUT!");
        } else {
            in = new FastScanner(System.in);
        }

        out = new PrintWriter(System.out);
        try {
            solve();
        } finally {
            out.flush();
            out.close();
        }
    }

    /**
     * Core logic to determine the relationship between three points.
     * Prints 1 if all three are collinear (same x or same y),
     * 2 if two points share an axis and the third is outside the segment,
     * 3 otherwise.
     */
    public void solve() {
        int x1 = in.nextInt(), y1 = in.nextInt();
        int x2 = in.nextInt(), y2 = in.nextInt();
        int x3 = in.nextInt(), y3 = in.nextInt();

        if (isCollinearVertical(x1, x2, x3) || isCollinearHorizontal(y1, y2, y3)) {
            out.println(1);
            return;
        }

        if (canFormTwoSegments(x1, y1, x2, y2, x3, y3)) {
            out.println(2);
            return;
        }

        out.println(3);
    }

    private boolean isCollinearVertical(int x1, int x2, int x3) {
        return x1 == x2 && x2 == x3;
    }

    private boolean isCollinearHorizontal(int y1, int y2, int y3) {
        return y1 == y2 && y2 == y3;
    }

    private boolean canFormTwoSegments(int x1, int y1, int x2, int y2, int x3, int y3) {
        return isPointOutsideSegment(x1, y1, x2, y2, x3, y3)
            || isPointOutsideSegment(x1, y1, x3, y3, x2, y2)
            || isPointOutsideSegment(x2, y2, x3, y3, x1, y1);
    }

    /**
     * Checks if point (x3, y3) lies outside or on the line extension of the segment 
     * formed by (x1, y1) and (x2, y2). Assumes the pair shares an axis.
     */
    private boolean isPointOutsideSegment(int x1, int y1, int x2, int y2, int x3, int y3) {
        if (x1 == x2) {
            return Math.max(y1, y2) <= y3 || Math.min(y1, y2) >= y3;
        }
        if (y1 == y2) {
            return Math.max(x1, x2) <= x3 || Math.min(x1, x2) >= x3;
        }
        return false;
    }

    /**
     * A high-performance scanner for reading input tokens.
     */
    static class FastScanner {
        private final InputStream stream;
        private final byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;

        public FastScanner(InputStream stream) {
            this.stream = stream;
        }

        public int read() {
            if (numChars == -1) {
                throw new InputMismatchException();
            }
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0) {
                    return -1;
                }
            }
            return buf[curChar++];
        }

        private boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        private boolean isEndline(int c) {
            return c == '\n' || c == '\r' || c == -1;
        }

        public String next() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            StringBuilder res = new StringBuilder();
            do {
                res.appendCodePoint(c);
                c = read();
            } while (!isSpaceChar(c));
            return res.toString();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public int[] nextIntArray(int n) {
            int[] array = new int[n];
            for (int i = 0; i < n; i++) {
                array[i] = nextInt();
            }
            return array;
        }

        public int[][] nextIntMap(int n, int m) {
            int[][] map = new int[n][m];
            for (int i = 0; i < n; i++) {
                map[i] = nextIntArray(m);
            }
            return map;
        }

        public long nextLong() {
            return Long.parseLong(next());
        }

        public long[] nextLongArray(int n) {
            long[] array = new long[n];
            for (int i = 0; i < n; i++) {
                array[i] = nextLong();
            }
            return array;
        }

        public long[][] nextLongMap(int n, int m) {
            long[][] map = new long[n][m];
            for (int i = 0; i < n; i++) {
                map[i] = nextLongArray(m);
            }
            return map;
        }

        public double nextDouble() {
            return Double.parseDouble(next());
        }

        public double[] nextDoubleArray(int n) {
            double[] array = new double[n];
            for (int i = 0; i < n; i++) {
                array[i] = nextDouble();
            }
            return array;
        }

        public double[][] nextDoubleMap(int n, int m) {
            double[][] map = new double[n][m];
            for (int i = 0; i < n; i++) {
                map[i] = nextDoubleArray(m);
            }
            return map;
        }

        public String nextLine() {
            int c = read();
            while (isEndline(c)) {
                c = read();
            }
            StringBuilder res = new StringBuilder();
            do {
                res.appendCodePoint(c);
                c = read();
            } while (!isEndline(c));
            return res.toString();
        }
    }
}

import java.util.Scanner;

public class Main {

    // Constants for relationship types to replace magic numbers
    private static final int RELATION_VERTICAL = 1;
    private static final int RELATION_HORIZONTAL = 2;
    private static final int RELATION_DIAGONAL = 0;

    // Constants for return scores
    private static final int SCORE_TYPE_1 = 1;
    private static final int SCORE_TYPE_2 = 2;
    private static final int SCORE_TYPE_3 = 3;

    public static void main(String[] args) {
        // Use try-with-resources to ensure the Scanner is properly closed
        try (Scanner scanner = new Scanner(System.in)) {
            Point[] points = new Point[3];

            // Read input coordinates for 3 points
            for (int i = 0; i < points.length; i++) {
                if (scanner.hasNextInt()) {
                    int x = scanner.nextInt();
                    int y = scanner.nextInt();
                    points[i] = new Point(x, y);
                }
            }

            // Initialize minimum score to the maximum possible value
            int minScore = Integer.MAX_VALUE;

            // Define all permutations of indices (0, 1, 2).
            // This iterates through every possible ordering of points,
            // treating the first two as the reference pair and the third as the point to evaluate.
            int[][] permutations = {
                {0, 1, 2}, {0, 2, 1},
                {1, 0, 2}, {1, 2, 0},
                {2, 0, 1}, {2, 1, 0}
            };

            // Evaluate each permutation and find the minimum score
            for (int[] perm : permutations) {
                int currentScore = calculateScore(
                    points[perm[0]], 
                    points[perm[1]], 
                    points[perm[2]]
                );
                if (currentScore < minScore) {
                    minScore = currentScore;
                }
            }

            System.out.println(minScore);

        } catch (Exception e) {
            // In a production environment, handle exceptions appropriately.
            e.printStackTrace();
        }
    }

    /**
     * Calculates the score based on the geometric relationship of three points.
     * 
     * @param p1 The first point in the reference pair
     * @param p2 The second point in the reference pair
     * @param p3 The point being evaluated against the pair
     * @return The calculated score (1, 2, or 3)
     */
    private static int calculateScore(Point p1, Point p2, Point p3) {
        // Check if all three points form a vertical line (same X coordinate)
        if (getRelation(p1, p2) == RELATION_VERTICAL &&
            getRelation(p1, p3) == RELATION_VERTICAL &&
            getRelation(p2, p3) == RELATION_VERTICAL) {
            return SCORE_TYPE_1;
        }

        // Check if all three points form a horizontal line (same Y coordinate)
        if (getRelation(p1, p2) == RELATION_HORIZONTAL &&
            getRelation(p1, p3) == RELATION_HORIZONTAL &&
            getRelation(p2, p3) == RELATION_HORIZONTAL) {
            return SCORE_TYPE_1;
        }

        // Determine the relationship between the reference pair (p1, p2)
        int pairRelation = getRelation(p1, p2);

        // If the pair is diagonal (neither vertical nor horizontal), return 3
        if (pairRelation == RELATION_DIAGONAL) {
            return SCORE_TYPE_3;
        }

        // Evaluate p3 based on the orientation of the pair (p1, p2)
        if (pairRelation == RELATION_VERTICAL) {
            // Pair is vertical (same X). Check if p3 is within the Y-range of p1 and p2.
            int minY = Math.min(p1.y, p2.y);
            int maxY = Math.max(p1.y, p2.y);

            // If p3 is outside or on the boundary of the vertical span, return 2.
            // Otherwise (strictly between), return 3.
            if (p3.y <= minY || p3.y >= maxY) {
                return SCORE_TYPE_2;
            } else {
                return SCORE_TYPE_3;
            }
        } else {
            // Pair is horizontal (same Y). Check if p3 is within the X-range of p1 and p2.
            int minX = Math.min(p1.x, p2.x);
            int maxX = Math.max(p1.x, p2.x);

            // If p3 is outside or on the boundary of the horizontal span, return 2.
            // Otherwise (strictly between), return 3.
            if (p3.x <= minX || p3.x >= maxX) {
                return SCORE_TYPE_2;
            } else {
                return SCORE_TYPE_3;
            }
        }
    }

    /**
     * Determines the relationship between two points.
     * 
     * @param p1 The first point
     * @param p2 The second point
     * @return 1 if vertical (same X), 2 if horizontal (same Y), 0 otherwise (diagonal)
     */
    private static int getRelation(Point p1, Point p2) {
        if (p1.x == p2.x) {
            return RELATION_VERTICAL;
        } else if (p1.y == p2.y) {
            return RELATION_HORIZONTAL;
        } else {
            return RELATION_DIAGONAL;
        }
    }

    /**
     * Represents a 2D geometric point.
     */
    public static class Point {
        int x;
        int y;

        public Point(int x, int y) {
            this.x = x;
            this.y = y;
        }
    }
}

import java.io.*;
import java.util.StringTokenizer;

public class Main {
    private static final String FILE = "";
    private FastScanner in;
    private PrintWriter out;

    public static void main(String[] args) {
        new Main().run();
    }

    public void run() {
        if (FILE.isEmpty()) {
            in = new FastScanner(System.in);
            out = new PrintWriter(System.out);
        } else {
            try {
                in = new FastScanner(new FileInputStream(FILE + ".in"));
                out = new PrintWriter(new FileOutputStream(FILE + ".out"));
            } catch (FileNotFoundException e) {
                throw new RuntimeException("Failed to open file: " + FILE, e);
            }
        }

        try {
            solve();
        } finally {
            out.flush();
            out.close();
        }
    }

    public void solve() {
        long x1 = in.nextLong(), y1 = in.nextLong();
        long x2 = in.nextLong(), y2 = in.nextLong();
        long x3 = in.nextLong(), y3 = in.nextLong();

        // All points share the same x-coordinate -> 1 vertical line covers them
        if (x1 == x2 && x2 == x3) {
            out.print(1);
            return;
        }
        // All points share the same y-coordinate -> 1 horizontal line covers them
        if (y1 == y2 && y2 == y3) {
            out.print(1);
            return;
        }

        // If any two points share an axis and the third lies outside (or on the boundary of) their segment,
        // they can be covered by exactly 2 axis-aligned lines.
        if (canCoverWithTwoLines(x1, y1, x2, y2, x3, y3)) {
            out.print(2);
            return;
        }

        out.print(3);
    }

    private boolean canCoverWithTwoLines(long x1, long y1, long x2, long y2, long x3, long y3) {
        return (y1 == y2 && isOutsideOrOnBoundary(x3, x1, x2)) ||
               (y2 == y3 && isOutsideOrOnBoundary(x1, x2, x3)) ||
               (y1 == y3 && isOutsideOrOnBoundary(x2, x1, x3)) ||
               (x1 == x2 && isOutsideOrOnBoundary(y3, y1, y2)) ||
               (x2 == x3 && isOutsideOrOnBoundary(y1, y2, y3)) ||
               (x1 == x3 && isOutsideOrOnBoundary(y2, y1, y3));
    }

    /**
     * Checks if point p is outside or on the boundary of the closed interval [a, b].
     */
    private boolean isOutsideOrOnBoundary(long p, long a, long b) {
        return p <= Math.min(a, b) || p >= Math.max(a, b);
    }

    /**
     * Fast input reader for competitive programming environments.
     */
    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner(InputStream is) {
            br = new BufferedReader(new InputStreamReader(is));
        }

        public String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) throw new IOException("End of stream reached");
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input", e);
                }
            }
            return st.nextToken();
        }

        public String nextLine() {
            st = null;
            try {
                return br.readLine();
            } catch (IOException e) {
                throw new RuntimeException("Failed to read line", e);
            }
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }

        public double nextDouble() {
            return Double.parseDouble(next());
        }

        public float nextFloat() {
            return Float.parseFloat(next());
        }
    }

    /**
     * Generic pair class for storing two comparable values.
     * Kept static to avoid implicit reference to outer class.
     */
    static class Pair<A extends Comparable<A>, B extends Comparable<B>> implements Comparable<Pair<A, B>> {
        public final A a;
        public final B b;

        public Pair(A a, B b) {
            this.a = a;
            this.b = b;
        }

        @Override
        public int compareTo(Pair<A, B> o) {
            if (o == null || o.getClass() != getClass()) return 1;
            int cmp = a.compareTo(o.a);
            return (cmp != 0) ? cmp : b.compareTo(o.b);
        }

        @Override
        public boolean equals(Object o) {
            if (this == o) return true;
            if (o == null || getClass() != o.getClass()) return false;
            Pair<?, ?> pair = (Pair<?, ?>) o;
            return (a != null ? a.equals(pair.a) : pair.a == null) &&
                   (b != null ? b.equals(pair.b) : pair.b == null);
        }
    }
}

import java.io.*;
import java.util.*;

public class Codeforces {

    /**
     * Helper class to encapsulate point coordinates.
     * This improves readability and eliminates the need for parallel arrays.
     */
    static class Point {
        final int x;
        final int y;

        Point(int x, int y) {
            this.x = x;
            this.y = y;
        }
    }

    public static void main(String[] args) {
        try {
            new Codeforces().solve();
        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    public void solve() {
        FastScanner fs = new FastScanner();
        PrintWriter out = new PrintWriter(System.out);

        // Read 3 points from input
        Point[] points = new Point[3];
        for (int i = 0; i < 3; i++) {
            points[i] = new Point(fs.nextInt(), fs.nextInt());
        }

        // Check if all points are vertically aligned (same x) or horizontally aligned (same y)
        // This corresponds to the condition: x[0]==x[1] && x[1]==x[2] || y[0]==y[1] && y[1]==y[2]
        boolean allXSame = (points[0].x == points[1].x && points[1].x == points[2].x);
        boolean allYSame = (points[0].y == points[1].y && points[1].y == points[2].y);

        if (allXSame || allYSame) {
            out.println("1");
        } else if (isPointOnSegment(points[0], points[1], points[2]) ||
                   isPointOnSegment(points[0], points[2], points[1]) ||
                   isPointOnSegment(points[1], points[2], points[0])) {
            // Checks if any point lies on the axis-aligned path (Manhattan path) between the other two.
            // Corresponds to: ok(0,1,2) || ok(0,2,1) || ok(1,2,0)
            out.println("2");
        } else {
            out.println("3");
        }

        out.flush();
    }

    /**
     * Checks if a value is between min and max (inclusive).
     * Replaces the original 'lies_between' logic.
     */
    private boolean isBetween(int value, int min, int max) {
        return Math.min(min, max) <= value && value <= Math.max(min, max);
    }

    /**
     * Checks if point p3 lies on the segment/path defined by p1 and p2.
     * Logic preserved from the original 'ok' method.
     * 
     * Original Logic:
     * ( (x[i] == x[k] || x[j] == x[k]) && lies_between(y[i], y[j], y[k]) )
     * ||
     * ( (y[i] == y[k] || y[j] == y[k]) && lies_between(x[i], x[j], x[k]) )
     * 
     * Mapping: i -> p1, j -> p2, k -> p3
     */
    private boolean isPointOnSegment(Point p1, Point p2, Point p3) {
        // Check vertical alignment condition
        boolean xAligned = (p1.x == p3.x || p2.x == p3.x);
        boolean yInRange = isBetween(p3.y, p1.y, p2.y);

        // Check horizontal alignment condition
        boolean yAligned = (p1.y == p3.y || p2.y == p3.y);
        boolean xInRange = isBetween(p3.x, p1.x, p2.x);

        return (xAligned && yInRange) || (yAligned && xInRange);
    }

    /**
     * FastScanner class for efficient input reading.
     */
    static class FastScanner {
        BufferedReader br;
        StringTokenizer st;

        public FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
            st = new StringTokenizer("");
        }

        String next() {
            while (!st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) {
                        return null;
                    }
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    e.printStackTrace();
                    return null;
                }
            }
            return st.nextToken();
        }

        String nextLine() {
            String str = "";
            try {
                str = br.readLine();
            } catch (IOException e) {
                e.printStackTrace();
            }
            return str;
        }

        int nextInt() {
            String s = next();
            if (s == null) throw new RuntimeException("End of input");
            return Integer.parseInt(s);
        }

        long nextLong() {
            String s = next();
            if (s == null) throw new RuntimeException("End of input");
            return Long.parseLong(s);
        }
    }
}

