import java.util.StringTokenizer;

/**
 * Determines a result (1, 2, or 3) based on three pairs of integers.
 * 
 * Logic:
 * 1. Returns 1 if all first elements are equal OR all second elements are equal.
 * 2. Returns 2 if a specific geometric/interval condition is met in the original 
 *    orientation or after swapping the two elements in each pair.
 * 3. Returns 3 otherwise.
 */
public class Main {
    private static final int NUM_ROWS = 3;

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            int[][] data = new int[NUM_ROWS][2];
            for (int i = 0; i < NUM_ROWS; i++) {
                data[i][0] = scanner.nextInt();
                data[i][1] = scanner.nextInt();
            }

            int result = solve(data);
            out.println(result);
        } finally {
            out.flush();
        }
    }

    /**
     * Core business logic to determine the result.
     */
    private static int solve(int[][] data) {
        // Check if all values in the first column are identical
        if (areAllEqual(data, 0)) {
            return 1;
        }
        // Check if all values in the second column are identical
        if (areAllEqual(data, 1)) {
            return 1;
        }

        // Check original configuration
        if (isValidConfiguration(data)) {
            return 2;
        }

        // Check swapped configuration (transpose the two columns)
        swapColumns(data);
        if (isValidConfiguration(data)) {
            return 2;
        }

        return 3;
    }

    /**
     * Checks if all rows have the same value in the specified column.
     */
    private static boolean areAllEqual(int[][] data, int colIndex) {
        int firstValue = data[0][colIndex];
        for (int i = 1; i < data.length; i++) {
            if (data[i][colIndex] != firstValue) {
                return false;
            }
        }
        return true;
    }

    /**
     * Evaluates the specific condition that results in 2.
     * Finds two rows with matching first-column values, and checks if the 
     * third row's second-column value falls outside the range spanned by the 
     * first two rows' second-column values.
     */
    private static boolean isValidConfiguration(int[][] data) {
        for (int i = 0; i < NUM_ROWS; i++) {
            for (int j = i + 1; j < NUM_ROWS; j++) {
                if (data[i][0] == data[j][0]) {
                    int min = Math.min(data[i][1], data[j][1]);
                    int max = Math.max(data[i][1], data[j][1]);

                    // The remaining row index when i and j are distinct indices from {0, 1, 2}
                    int k = 3 - i - j;
                    int y = data[k][1];

                    if (y <= min || y >= max) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Swaps the two columns in-place for all rows.
     */
    private static void swapColumns(int[][] data) {
        for (int[] row : data) {
            int temp = row[0];
            row[0] = row[1];
            row[1] = temp;
        }
    }

    /**
     * Fast input reader for competitive programming / high-performance I/O.
     */
    static class FastScanner {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastScanner(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) {
                        throw new IOException("End of input stream");
                    }
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input", e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

/**
 * Solves a competitive programming problem that determines the geometric relationship
 * between three 2D points based on specific alignment conditions.
 */
public class Codeforces {

    public static void main(String[] args) {
        FastReader reader = new FastReader();
        try {
            solve(reader);
        } catch (IOException e) {
            System.err.println("Failed to read input: " + e.getMessage());
        }
    }

    /**
     * Reads three points and prints the result based on their alignment.
     */
    private static void solve(FastReader reader) throws IOException {
        int[] x = new int[3];
        int[] y = new int[3];
        for (int i = 0; i < 3; i++) {
            x[i] = reader.nextInt();
            y[i] = reader.nextInt();
        }

        System.out.println(determineOutput(x, y));
    }

    /**
     * Determines the output value (1, 2, or 3) based on the alignment of three points.
     * Preserves the exact logic from the original implementation.
     */
    private static int determineOutput(int[] x, int[] y) {
        // Case 1: All three points share the same x or same y coordinate
        if ((x[0] == x[1] && x[1] == x[2]) || (y[0] == y[1] && y[1] == y[2])) {
            return 1;
        }

        // Case 2: Two points share an x-coordinate, and the third is not strictly between them in y
        if (x[0] == x[1] && (y[2] >= Math.max(y[0], y[1]) || y[2] <= Math.min(y[0], y[1]))) {
            return 2;
        }
        if (x[0] == x[2] && (y[1] >= Math.max(y[0], y[2]) || y[1] <= Math.min(y[0], y[2]))) {
            return 2;
        }
        if (x[1] == x[2] && (y[0] >= Math.max(y[1], y[2]) || y[0] <= Math.min(y[1], y[2]))) {
            return 2;
        }

        // Case 2: Two points share a y-coordinate, and the third is not strictly between them in x
        if (y[0] == y[1] && (x[2] >= Math.max(x[0], x[1]) || x[2] <= Math.min(x[0], x[1]))) {
            return 2;
        }
        if (y[0] == y[2] && (x[1] >= Math.max(x[0], x[2]) || x[1] <= Math.min(x[0], x[2]))) {
            return 2;
        }
        if (y[1] == y[2] && (x[0] >= Math.max(x[1], x[2]) || x[0] <= Math.min(x[1], x[2]))) {
            return 2;
        }

        // Case 3: No specific alignment matches the above conditions
        return 3;
    }

    /**
     * Optimized Fast I/O helper for competitive programming.
     */
    static class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) {
                        return null;
                    }
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.Arrays;
import java.util.StringTokenizer;

/**
 * Main entry point for the three-point line coverage problem.
 * Reads three 2D points and calculates the minimum number of lines
 * required to cover them based on the original algorithm's logic.
 */
public class Main {

    public static void main(String[] args) {
        FastScanner in = new FastScanner();
        PrintWriter out = new PrintWriter(System.out);

        Point[] points = new Point[3];
        for (int i = 0; i < 3; i++) {
            points[i] = new Point(in.nextInt(), in.nextInt());
        }

        int result = calculateMinimumLines(points);
        out.println(result);
        out.flush();
    }

    /**
     * Calculates the minimum number of lines needed to cover the three points.
     * Preserves the exact logic of the original permutation-based approach.
     */
    private static int calculateMinimumLines(Point[] points) {
        int minLines = 3;
        int[] permutation = {0, 1, 2};

        do {
            // Check if all three points are vertically aligned
            if (points[permutation[0]].x == points[permutation[1]].x &&
                points[permutation[1]].x == points[permutation[2]].x) {
                minLines = 1;
                break;
            }
            // Check if all three points are horizontally aligned
            else if (points[permutation[0]].y == points[permutation[1]].y &&
                     points[permutation[1]].y == points[permutation[2]].y) {
                minLines = 1;
                break;
            }
            // Check if two points share an x-coordinate and the third is outside their y-range
            else if (points[permutation[0]].x == points[permutation[1]].x &&
                     points[permutation[0]].y < points[permutation[1]].y) {
                if (points[permutation[2]].y >= points[permutation[1]].y ||
                    points[permutation[2]].y <= points[permutation[0]].y) {
                    minLines = Math.min(minLines, 2);
                }
            }
            // Check if two points share a y-coordinate and the third is outside their x-range
            else if (points[permutation[0]].y == points[permutation[1]].y &&
                     points[permutation[0]].x < points[permutation[1]].x) {
                if (points[permutation[2]].x >= points[permutation[1]].x ||
                    points[permutation[2]].x <= points[permutation[0]].x) {
                    minLines = Math.min(minLines, 2);
                }
            }
        } while (nextPermutation(permutation));

        return minLines;
    }

    /**
     * Generates the next lexicographical permutation of the given array.
     * Returns false if the array is already at the last permutation.
     */
    private static boolean nextPermutation(int[] data) {
        int i = data.length - 1;
        while (i > 0 && data[i] < data[i - 1]) {
            i--;
        }
        if (i == 0) {
            return false;
        }

        int j = data.length - 1;
        while (data[j] < data[i - 1]) {
            j--;
        }

        swap(data, i - 1, j);
        Arrays.sort(data, i, data.length);
        return true;
    }

    private static void swap(int[] arr, int i, int j) {
        int temp = arr[i];
        arr[i] = arr[j];
        arr[j] = temp;
    }

    /**
     * Represents a 2D point with integer coordinates.
     */
    public static class Point {
        public final int x;
        public final int y;

        public Point(int x, int y) {
            this.x = x;
            this.y = y;
        }
    }

    /**
     * Fast input reader optimized for competitive programming environments.
     */
    public static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        public String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) throw new RuntimeException("End of input");
                    st = new StringTokenizer(line);
                } catch (Exception e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.*;
import java.util.*;

public class Main {

    /**
     * Represents a 2D coordinate point.
     */
    static class Point {
        final int x;
        final int y;

        Point(int x, int y) {
            this.x = x;
            this.y = y;
        }
    }

    public static void main(String[] args) throws IOException {
        // Use try-with-resources for automatic and safe resource cleanup
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
             PrintWriter pw = new PrintWriter(new BufferedOutputStream(System.out))) {

            Point[] points = new Point[3];
            for (int i = 0; i < 3; i++) {
                String line = br.readLine();
                if (line == null || line.trim().isEmpty()) {
                    throw new IllegalArgumentException("Invalid input: expected 3 lines with coordinates");
                }

                String[] parts = line.trim().split("\\s+");
                if (parts.length < 2) {
                    throw new IllegalArgumentException("Invalid input: each line must contain two integers");
                }

                points[i] = new Point(Integer.parseInt(parts[0]), Integer.parseInt(parts[1]));
            }

            int result = determineResult(points[0], points[1], points[2]);
            pw.println(result);
        }
    }

    /**
     * Determines the output value based on the distribution of unique X and Y coordinates.
     * 
     * @param p1 First point
     * @param p2 Second point
     * @param p3 Third point
     * @return 1, 2, or 3 based on the original problem's logic
     */
    private static int determineResult(Point p1, Point p2, Point p3) {
        Set<Integer> uniqueX = new HashSet<>(Arrays.asList(p1.x, p2.x, p3.x));
        Set<Integer> uniqueY = new HashSet<>(Arrays.asList(p1.y, p2.y, p3.y));

        int xCount = uniqueX.size();
        int yCount = uniqueY.size();

        // Case 1: All points share the same X or same Y (collinear vertically/horizontally)
        if (xCount == 1 || yCount == 1) {
            return 1;
        }
        // Case 2: All coordinates are distinct
        if (xCount == 3 && yCount == 3) {
            return 3;
        }
        // Case 3: Exactly two unique X and two unique Y
        if (xCount == 2 && yCount == 2) {
            return 2;
        }

        // Case 4: Mixed scenarios (one dimension has 2 unique values, the other has 3)
        if (xCount == 2) {
            return evaluateBetweenCondition(p1, p2, p3, true);
        }
        if (yCount == 2) {
            return evaluateBetweenCondition(p1, p2, p3, false);
        }

        return 2; // Fallback for any unhandled edge cases
    }

    /**
     * Evaluates whether the point with the unique coordinate lies strictly between
     * the other two points' corresponding coordinates.
     *
     * @param p1 First point
     * @param p2 Second point
     * @param p3 Third point
     * @param checkX If true, evaluates based on X-coordinates; otherwise Y-coordinates
     * @return 3 if strictly between, 2 otherwise
     */
    private static int evaluateBetweenCondition(Point p1, Point p2, Point p3, boolean checkX) {
        Point uniquePoint, sharedPoint1, sharedPoint2;

        if (checkX) {
            if (p1.x == p2.x) { uniquePoint = p3; sharedPoint1 = p1; sharedPoint2 = p2; }
            else if (p2.x == p3.x) { uniquePoint = p1; sharedPoint1 = p2; sharedPoint2 = p3; }
            else { uniquePoint = p2; sharedPoint1 = p1; sharedPoint2 = p3; }
        } else {
            if (p1.y == p2.y) { uniquePoint = p3; sharedPoint1 = p1; sharedPoint2 = p2; }
            else if (p2.y == p3.y) { uniquePoint = p1; sharedPoint1 = p2; sharedPoint2 = p3; }
            else { uniquePoint = p2; sharedPoint1 = p1; sharedPoint2 = p3; }
        }

        // Extract the values to compare
        int sharedVal1 = checkX ? sharedPoint1.y : sharedPoint1.x;
        int sharedVal2 = checkX ? sharedPoint2.y : sharedPoint2.x;
        int uniqueVal = checkX ? uniquePoint.y : uniquePoint.x;

        // Check if the unique value lies strictly between the two shared values
        return (uniqueVal > Math.min(sharedVal1, sharedVal2) && uniqueVal < Math.max(sharedVal1, sharedVal2)) ? 3 : 2;
    }
}

import java.io.*;
import java.util.*;

public class Template {

    public static void main(String[] args) {
        long startTime = System.currentTimeMillis();
        long startMemory = Runtime.getRuntime().totalMemory() - Runtime.getRuntime().freeMemory();

        try {
            solve();
        } catch (IOException e) {
            System.err.println("I/O Error: " + e.getMessage());
            System.exit(1);
        } finally {
            long endTime = System.currentTimeMillis();
            long endMemory = Runtime.getRuntime().totalMemory() - Runtime.getRuntime().freeMemory();

            // Only print performance metrics in local environments
            if (System.getProperty("ONLINE_JUDGE") == null) {
                System.err.println("Time = " + (endTime - startTime) + " ms");
                System.err.println("Memory = " + ((endMemory - startMemory) >> 10) + " KB");
            }
        }
    }

    private static void solve() throws IOException {
        FastScanner sc = new FastScanner();
        PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out));

        Point a = new Point(sc.nextInt(), sc.nextInt());
        Point b = new Point(sc.nextInt(), sc.nextInt());
        Point c = new Point(sc.nextInt(), sc.nextInt());

        if (areCollinear(a, b, c)) {
            out.println(1);
        } else if (isPointOnLineExtension(a, b, c) || isPointOnLineExtension(a, c, b) ||
                   isPointOnLineExtension(b, a, c) || isPointOnLineExtension(b, c, a) ||
                   isPointOnLineExtension(c, a, b) || isPointOnLineExtension(c, b, a)) {
            out.println(2);
        } else {
            out.println(3);
        }

        out.flush();
    }

    /**
     * Checks if three points are collinear on a horizontal or vertical line.
     */
    private static boolean areCollinear(Point a, Point b, Point c) {
        return (a.x == b.x && a.x == c.x) || (a.y == b.y && a.y == c.y);
    }

    /**
     * Checks if point c lies on the axis-aligned line defined by a and b,
     * but outside or on the boundary of the line segment ab.
     */
    private static boolean isPointOnLineExtension(Point a, Point b, Point c) {
        // Points a and b must share an axis to define a horizontal/vertical line
        if (a.x != b.x && a.y != b.y) return false;

        if (a.x == b.x) {
            // Vertical line: verify c shares the x-coordinate and lies outside the segment
            return c.x == a.x && (c.y <= Math.min(a.y, b.y) || c.y >= Math.max(a.y, b.y));
        } else {
            // Horizontal line: verify c shares the y-coordinate and lies outside the segment
            return c.y == a.y && (c.x <= Math.min(a.x, b.x) || c.x >= Math.max(a.x, b.x));
        }
    }

    /**
     * Fast input reader optimized for competitive programming.
     */
    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line, " :");
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input", e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            String s = next();
            if (s == null) throw new RuntimeException("Unexpected end of input");
            return Integer.parseInt(s);
        }
    }

    /**
     * Immutable point class representing coordinates.
     */
    static class Point {
        final long x;
        final long y;

        Point(long x, long y) {
            this.x = x;
            this.y = y;
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.Reader;
import java.util.HashSet;
import java.util.Set;
import java.util.StringTokenizer;

/**
 * Analyzes the coordinate configuration of three points to determine
 * the minimum number of axis-aligned lines required to cover them.
 */
public class PointConfigurationAnalyzer {

    private static final int NUM_POINTS = 3;

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner();
        Set<Long> distinctX = new HashSet<>();
        Set<Long> distinctY = new HashSet<>();

        // Read coordinates and populate distinct sets
        for (int i = 0; i < NUM_POINTS; i++) {
            distinctX.add(scanner.nextLong());
            distinctY.add(scanner.nextLong());
        }

        int result = determineMinimumLineCount(distinctX, distinctY);
        System.out.println(result);
    }

    /**
     * Determines the minimum number of axis-aligned lines needed to cover all points.
     *
     * Logic Simplification:
     * - If all points share the same X or Y coordinate, they are collinear on a single axis-aligned line -> 1
     * - If any two points share an X or Y coordinate, they can be covered by two lines -> 2
     *   (With exactly 3 points, this is mathematically equivalent to having fewer than 3 distinct X or Y values)
     * - If all X and Y coordinates are distinct, three lines are required -> 3
     */
    private static int determineMinimumLineCount(Set<Long> distinctX, Set<Long> distinctY) {
        if (distinctX.size() == 1 || distinctY.size() == 1) {
            return 1;
        }
        if (distinctX.size() < NUM_POINTS || distinctY.size() < NUM_POINTS) {
            return 2;
        }
        return 3;
    }

    /**
     * High-performance input scanner commonly used in competitive programming.
     * Refactored for robustness and maintainability.
     */
    public static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner() {
            this(new InputStreamReader(System.in));
        }

        public FastScanner(Reader in) {
            br = new BufferedReader(in);
        }

        public String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) {
                        throw new IOException("Unexpected end of input");
                    }
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input stream", e);
                }
            }
            return st.nextToken();
        }

        public long nextLong() {
            return Long.parseLong(next());
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

public class Polyline {
    private static final int NUM_POINTS = 3;
    private Point[] points = new Point[NUM_POINTS];

    public static void main(String[] args) {
        FastScanner in = new FastScanner(new BufferedReader(new InputStreamReader(System.in)));
        PrintWriter out = new PrintWriter(System.out);

        new Polyline().solve(in, out);

        out.flush();
        out.close();
    }

    void solve(FastScanner in, PrintWriter out) {
        for (int i = 0; i < NUM_POINTS; i++) {
            points[i] = new Point(in.nextInt(), in.nextInt());
        }
        int result = calculate();
        out.println(result);
    }

    private int calculate() {
        // Check if all points are collinear on a vertical or horizontal line
        if (allSameX() || allSameY()) {
            return 1;
        }

        // Check if any point lies on the axis-aligned segment between the other two
        // Permutations: (0,1,2), (0,2,1), (1,2,0)
        // Meaning: Is point 2 on segment 0-1? Is point 1 on segment 0-2? Is point 0 on segment 1-2?
        if (isPointOnAxisAlignedSegment(0, 1, 2) || 
            isPointOnAxisAlignedSegment(0, 2, 1) || 
            isPointOnAxisAlignedSegment(1, 2, 0)) {
            return 2;
        }

        return 3;
    }

    private boolean allSameX() {
        return points[0].x == points[1].x && points[1].x == points[2].x;
    }

    private boolean allSameY() {
        return points[0].y == points[1].y && points[1].y == points[2].y;
    }

    /**
     * Checks if point k lies on the axis-aligned segment connecting points i and j.
     * This logic assumes segments are restricted to horizontal and vertical lines (Manhattan geometry).
     */
    private boolean isPointOnAxisAlignedSegment(int i, int j, int k) {
        Point p1 = points[i];
        Point p2 = points[j];
        Point p3 = points[k];

        // Check if p3 is vertically aligned with the segment
        if (p3.x == p1.x || p3.x == p2.x) {
            return p3.y >= Math.min(p1.y, p2.y) && p3.y <= Math.max(p1.y, p2.y);
        }
        // Check if p3 is horizontally aligned with the segment
        else if (p3.y == p1.y || p3.y == p2.y) {
            return p3.x >= Math.min(p1.x, p2.x) && p3.x <= Math.max(p1.x, p2.x);
        }

        return false;
    }

    static class Point {
        final int x;
        final int y;

        Point(int x, int y) {
            this.x = x;
            this.y = y;
        }
    }

    static class FastScanner {
        BufferedReader in;
        StringTokenizer st;

        public FastScanner(BufferedReader in) {
            this.in = in;
        }

        public String nextToken() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = in.readLine();
                    if (line == null) {
                        return null;
                    }
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            String token = nextToken();
            if (token == null) throw new RuntimeException("End of input");
            return Integer.parseInt(token);
        }

