import java.util.HashSet;
import java.util.Scanner;
import java.util.Set;

/**
 * Calculates the minimum number of horizontal or vertical line segments
 * required to cover exactly three given points.
 */
public class MinimumLineSegments {

    public static void main(String[] args) {
        // try-with-resources ensures the Scanner is automatically closed
        try (Scanner scanner = new Scanner(System.in)) {
            Point[] points = new Point[3];
            for (int i = 0; i < points.length; i++) {
                points[i] = new Point(scanner.nextInt(), scanner.nextInt());
            }

            int result = calculateMinimumSegments(points[0], points[1], points[2]);
            System.out.println(result);
        }
    }

    /**
     * Determines the minimum number of axis-aligned line segments needed to cover three points.
     *
     * @param p1 First point
     * @param p2 Second point
     * @param p3 Third point
     * @return 1 if all points are collinear (horizontal or vertical),
     *         2 if one point lies on the segment between the other two,
     *         3 otherwise
     */
    private static int calculateMinimumSegments(Point p1, Point p2, Point p3) {
        Set<Integer> xCoordinates = new HashSet<>();
        xCoordinates.add(p1.x);
        xCoordinates.add(p2.x);
        xCoordinates.add(p3.x);

        Set<Integer> yCoordinates = new HashSet<>();
        yCoordinates.add(p1.y);
        yCoordinates.add(p2.y);
        yCoordinates.add(p3.y);

        // If all points share the same X or same Y coordinate, one line covers them all.
        if (xCoordinates.size() == 1 || yCoordinates.size() == 1) {
            return 1;
        }

        // If any point lies on the segment connecting the other two, two lines are sufficient.
        if (p1.liesOnSegment(p2, p3) || p2.liesOnSegment(p1, p3) || p3.liesOnSegment(p1, p2)) {
            return 2;
        }

        // Otherwise, each point requires its own segment.
        return 3;
    }

    /**
     * Represents a point in a 2D Cartesian coordinate system.
     */
    static class Point {
        final int x;
        final int y;

        public Point(int x, int y) {
            this.x = x;
            this.y = y;
        }

        /**
         * Checks if this point lies on the axis-aligned line segment between p1 and p2.
         *
         * @param p1 Start of the segment
         * @param p2 End of the segment
         * @return true if this point is collinear with p1 and p2 and lies within the segment bounds
         */
        public boolean liesOnSegment(Point p1, Point p2) {
            if (p1.y == p2.y) {
                // Horizontal segment check
                return y == p1.y && x >= Math.min(p1.x, p2.x) && x <= Math.max(p1.x, p2.x);
            }
            if (p1.x == p2.x) {
                // Vertical segment check
                return x == p1.x && y >= Math.min(p1.y, p2.y) && y <= Math.max(p1.y, p2.y);
            }
            return false;
        }
    }
}

import java.io.BufferedReader;
import java.io.BufferedOutputStream;
