import java.io.PrintWriter;
import java.util.Arrays;
import java.util.StringTokenizer;

public class Codeforces {

    /**
     * Represents a 2D point with integer coordinates.
     * Immutable and sortable by x-coordinate, then y-coordinate.
     */
    static class Point implements Comparable<Point> {
        final int x;
        final int y;

        Point(int x, int y) {
            this.x = x;
            this.y = y;
        }

        @Override
        public int compareTo(Point other) {
            if (this.x != other.x) {
                return Integer.compare(this.x, other.x);
            }
            return Integer.compare(this.y, other.y);
        }
    }

    public static void main(String[] args) throws IOException {
        // Use try-with-resources to automatically close streams and prevent leaks
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
             PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out))) {

            StringTokenizer st = new StringTokenizer("");
            Point[] points = new Point[3];

            // Read exactly 3 points
            for (int i = 0; i < 3; i++) {
                while (!st.hasMoreTokens()) {
                    String line = reader.readLine();
                    if (line == null) break;
                    st = new StringTokenizer(line);
                }
                int x = Integer.parseInt(st.nextToken());
                int y = Integer.parseInt(st.nextToken());
                points[i] = new Point(x, y);
            }

            // Sort points to ensure consistent ordering before classification
            Arrays.sort(points);

            int result = classifyPoints(points);
            out.println(result);
            // PrintWriter is automatically flushed and closed by try-with-resources
        }
    }

    /**
     * Classifies three sorted points based on their geometric alignment and relative positions.
     * Returns 1, 2, or 3 indicating specific configurations as defined by the original logic.
     *
     * @param points Array of exactly 3 points, assumed to be sorted by x then y
     * @return Classification code (1, 2, or 3)
     */
    private static int classifyPoints(Point[] points) {
        Point p0 = points[0];
        Point p1 = points[1];
        Point p2 = points[2];

        // All points share the same x-coordinate (vertical alignment)
        if (p0.x == p1.x && p1.x == p2.x) {
            return 1;
        }

        // p0 and p1 share x-coordinate
        if (p0.x == p1.x) {
            if (p1.y <= p2.y || p0.y == p2.y) return 2;
            if (p0.y >= p2.y) return 2;
            return 3;
        }

        // p0 and p1 share y-coordinate
        if (p0.y == p1.y) {
            if (p1.y == p2.y) return 1; // All three share y-coordinate (horizontal alignment)
            return 2;
        }

        // p0 and p2 share y-coordinate
        if (p0.y == p2.y) {
            return (p1.x == p2.x) ? 2 : 3;
        }

        // p1 and p2 share x-coordinate
        if (p1.x == p2.x) {
            if ((p1.y > p0.y && p2.y > p0.y) || (p1.y < p0.y && p2.y < p0.y)) {
                return 2;
            }
            return 3;
        }

        // p1 and p2 share y-coordinate
        if (p1.y == p2.y) {
            return 2;
        }

        // Default case: no specific alignment matched
        return 3;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.OutputStream;
import java.io.PrintWriter;
import java.util.StringTokenizer;

public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        TaskD solver = new TaskD();
        solver.solve(in, out);
        out.close();
    }

    static class TaskD {
        // Direction bit constants to replace magic numbers
        private static final int DIR_DOWN  = 1 << 0;
        private static final int DIR_UP    = 1 << 1;
        private static final int DIR_LEFT  = 1 << 2;
        private static final int DIR_RIGHT = 1 << 3;

        public void solve(InputReader in, PrintWriter out) {
            Point a = new Point(in.nextInt(), in.nextInt());
            Point b = new Point(in.nextInt(), in.nextInt());
            Point c = new Point(in.nextInt(), in.nextInt());

            // Check if points are collinear and aligned with an axis
            if (isCollinearAndAxisAligned(a, b, c)) {
                out.println(1);
                return;
            }

            // Search for a reference point 'o' on the Cartesian product of coordinates
            long[] xs = {a.x, b.x, c.x};
            long[] ys = {a.y, b.y, c.y};

            for (long ox : xs) {
                for (long oy : ys) {
                    Point o = new Point(ox, oy);
                    if (isValidReferencePoint(a, b, c, o)) {
                        out.println(2);
                        return;
                    }
                }
            }

            // Default case
            out.print(3);
        }

        private boolean isCollinearAndAxisAligned(Point a, Point b, Point c) {
            Point ab = a.subtract(b);
            Point ac = a.subtract(c);
            // Cross product is zero if collinear
            if (ab.crossProduct(ac) == 0) {
                // Check if the line is horizontal or vertical
                return ab.x == 0 || ab.y == 0;
            }
            return false;
        }

        private boolean isValidReferencePoint(Point p1, Point p2, Point p3, Point o) {
            int distinctDirections = 0;
            Point[] points = {p1, p2, p3};

            for (Point p : points) {
                Point diff = p.subtract(o);

                // Reference point coincides with a given point; skip
                if (diff.x == 0 && diff.y == 0) {
                    continue;
                }
                // Must be axis-aligned (either x or y difference is zero, but not both)
                if (diff.x != 0 && diff.y != 0) {
                    return false;
                }

                int directionBit = getDirectionBit(diff);
                // Track distinct directions
                if ((distinctDirections & directionBit) == 0) {
                    distinctDirections |= directionBit;
                }
            }

            // Exactly two distinct directions among the three points
            return Integer.bitCount(distinctDirections) == 2;
        }

        private int getDirectionBit(Point diff) {
            if (diff.x == 0) {
                return diff.y < 0 ? DIR_DOWN : DIR_UP;
            }
            return diff.x < 0 ? DIR_LEFT : DIR_RIGHT;
        }
    }

    static class Point {
        final long x;
        final long y;

        Point(long x, long y) {
            this.x = x;
            this.y = y;
        }

        Point subtract(Point other) {
            return new Point(this.x - other.x, this.y - other.y);
        }

        long crossProduct(Point other) {
            return this.x * other.y - this.y * other.x;
        }
    }

    static class InputReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public InputReader(InputStream stream) {
            this.reader = new BufferedReader(new InputStreamReader(stream));
            this.tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) {
                        throw new IOException("Unexpected end of input");
                    }
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input", e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

