public class Main {

    public static void main(String[] args) {
        // try-with-resources ensures automatic and safe cleanup of I/O streams
        try (Reader in = new Reader(new InputStreamReader(System.in));
             PrintWriter out = new PrintWriter(new OutputStreamWriter(System.out))) {
            solve(in, out);
        } catch (IOException e) {
            throw new RuntimeException("I/O error occurred", e);
        }
    }

    private static void solve(Reader in, PrintWriter out) {
        final int N = 3;
        Point[] points = new Point[N];
        for (int i = 0; i < N; i++) {
            points[i] = new Point(in.nextInt(), in.nextInt());
        }

        Set<Integer> uniqueX = new HashSet<>();
        Set<Integer> uniqueY = new HashSet<>();
        for (Point p : points) {
            uniqueX.add(p.x);
            uniqueY.add(p.y);
        }

        int minUniqueCount = Math.min(uniqueX.size(), uniqueY.size());
        if (minUniqueCount != 2) {
            out.println(minUniqueCount);
            return;
        }

        // Determine which axis has exactly two unique values and check geometric condition
        if (uniqueX.size() == 2) {
            out.println(checkStrictlyBetween(points, true) ? 3 : 2);
        } else {
            out.println(checkStrictlyBetween(points, false) ? 3 : 2);
        }
    }

    /**
     * Checks if the third point's coordinate lies strictly between the other two points' coordinates.
     * @param points Array of 3 points
     * @param checkX If true, checks X-coordinates for equality and Y-coordinates for strict betweenness
     * @return true if the third point is strictly between, false otherwise
     */
    private static boolean checkStrictlyBetween(Point[] points, boolean checkX) {
        Point p1, p2, p3;

        if (checkX) {
            // Identify the two points sharing an X coordinate
            if (points[0].x == points[1].x) { p1 = points[0]; p2 = points[1]; p3 = points[2]; }
            else if (points[0].x == points[2].x) { p1 = points[0]; p2 = points[2]; p3 = points[1]; }
            else { p1 = points[1]; p2 = points[2]; p3 = points[0]; }

            int minVal = Math.min(p1.y, p2.y);
            int maxVal = Math.max(p1.y, p2.y);
            return p3.y > minVal && p3.y < maxVal;
        } else {
            // Identify the two points sharing a Y coordinate
            if (points[0].y == points[1].y) { p1 = points[0]; p2 = points[1]; p3 = points[2]; }
            else if (points[0].y == points[2].y) { p1 = points[0]; p2 = points[2]; p3 = points[1]; }
            else { p1 = points[1]; p2 = points[2]; p3 = points[0]; }

            int minVal = Math.min(p1.x, p2.x);
            int maxVal = Math.max(p1.x, p2.x);
            return p3.x > minVal && p3.x < maxVal;
        }
    }

    private static class Point {
        final int x;
        final int y;

        public Point(int x, int y) {
            this.x = x;
            this.y = y;
        }
    }

    // Fast I/O Reader class (preserved for competitive programming context)
