/**
 * Handles the core problem-solving logic.
 */
class Solver {
    private final FastScanner sc;
    private final PrintWriter out;

    public Solver(FastScanner sc, PrintWriter out) {
        this.sc = sc;
        this.out = out;
    }

    public void run() {
        Point[] points = new Point[3];
        for (int i = 0; i < 3; i++) {
            points[i] = new Point(sc.nextLong(), sc.nextLong());
        }

        Arrays.sort(points);
        out.println(solve(points));
        out.flush();
    }

    /**
     * Solves the problem based on the geometric configuration of three points.
     * Logic is preserved exactly from the original implementation but structured for readability.
     */
    private int solve(Point[] points) {
        Point a = points[0];
        Point b = points[1];
        Point c = points[2];

        // Case 1: All points are collinear on a horizontal line
        if (a.y == b.y && b.y == c.y) {
            return 1;
        }
        // Case 2: All points are collinear on a vertical line
        if (a.x == b.x && b.x == c.x) {
            return 1;
        }

        // Case 3: Segment AB is vertical
        if (a.x == b.x) {
            return (c.y > a.y && c.y < b.y) ? 3 : 2;
        }

        // Case 4: Segment AB is horizontal
        if (a.y == b.y) {
            return 2;
        }

        // Case 5: Segment AB is slanted. Due to sorting, a.x < b.x.
        // The following conditions check specific geometric relationships.
        if (b.y < a.y) {
            if (c.x == b.x) {
                if (c.y <= a.y) return 2;
                return 3;
            }
            if (c.y == b.y) return 2;
            return 3;
        }

        if (b.y > a.y) {
            if (c.x == b.x) return 2;
            if (c.y == b.y) return 2;
            return 3;
        }

        // Fallback (covers b.y == a.y, though already handled above)
        return 3;
    }
}

