        PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out));

        try {
            // Original code runs exactly one test case. Structured here for potential expansion.
            int testCases = 1;
            for (int i = 1; i <= testCases; i++) {
                solve(i, scanner, out);
            }
        } finally {
            out.flush();
            out.close();
        }
    }

    private static void solve(int testNumber, FastScanner scanner, PrintWriter out) {
        Point[] points = new Point[3];
        for (int i = 0; i < 3; i++) {
            points[i] = new Point(scanner.nextInt(), scanner.nextInt());
        }

        int result = calculateMinimumSegments(points);
        out.println(result);
    }

    /**
     * Calculates the minimum number of axis-aligned line segments required to connect three points.
     * 
     * Algorithm:
     * 1. If all three points share the same x or y coordinate, they are collinear -> 1 segment.
     * 2. If any two points form a line segment, and the third point lies outside that segment's range,
     *    then 2 segments are needed to connect all three.
     * 3. Otherwise, 3 segments are required to connect the points.
     */
    private static int calculateMinimumSegments(Point[] points) {
        // Case 1: Complete collinearity (all x equal or all y equal)
        boolean sameX = (points[0].x == points[1].x) && (points[1].x == points[2].x);
        boolean sameY = (points[0].y == points[1].y) && (points[1].y == points[2].y);
        if (sameX || sameY) {
            return 1;
        }

        // Case 2: Check all pairs to see if the third point lies outside their segment
        for (int i = 0; i < 3; i++) {
            for (int j = i + 1; j < 3; j++) {
                Point p1 = points[i];
                Point p2 = points[j];
                Point p3 = points[3 - i - j]; // The remaining point

                // Vertical alignment check
                if (p1.x == p2.x) {
                    int minY = Math.min(p1.y, p2.y);
                    int maxY = Math.max(p1.y, p2.y);
                    if (p3.y >= maxY || p3.y <= minY) {
                        return 2;
                    }
                }

                // Horizontal alignment check
                if (p1.y == p2.y) {
                    int minX = Math.min(p1.x, p2.x);
                    int maxX = Math.max(p1.x, p2.x);
                    if (p3.x >= maxX || p3.x <= minX) {
                        return 2;
                    }
                }
            }
        }

        // Case 3: General position requiring 3 segments
        return 3;
    }

    /**
     * High-performance input reader optimized for competitive programming.
     */
    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        String next() {
