import java.util.Scanner;

/**
 * Analyzes the arrangement of three points on a 2D plane.
 * Determines a classification based on coordinate alignments and relative positions.
 */
public class PointArrangementChecker {

    public static void main(String[] args) {
        // Using try-with-resources to ensure proper resource cleanup
        try (Scanner scanner = new Scanner(System.in)) {
            if (!scanner.hasNextInt()) {
                return;
            }

            int x1 = scanner.nextInt();
            int y1 = scanner.nextInt();
            int x2 = scanner.nextInt();
            int y2 = scanner.nextInt();
            int x3 = scanner.nextInt();
            int y3 = scanner.nextInt();

            int result = determineArrangement(x1, y1, x2, y2, x3, y3);
            System.out.println(result);
        }
    }

    /**
     * Determines the arrangement classification for three points.
     *
     * @return 1 if all points are collinear (same x or same y)
     *         2 if two points share a coordinate and the third is not strictly between them
     *         3 if two points share a coordinate and the third is strictly between them, or no coordinates are shared
     */
    private static int determineArrangement(int x1, int y1, int x2, int y2, int x3, int y3) {
        // Case 1: All points share the same x-coordinate (vertical alignment)
        if (x1 == x2 && x2 == x3) {
            return 1;
        }
        // Case 2: All points share the same y-coordinate (horizontal alignment)
        if (y1 == y2 && y2 == y3) {
            return 1;
        }

        // Check pairs sharing an x-coordinate
        if (x1 == x2) {
            if (isStrictlyBetween(y3, y1, y2)) return 3;
            return 2;
        }
        if (x2 == x3) {
            if (isStrictlyBetween(y1, y2, y3)) return 3;
            return 2;
        }
        if (x1 == x3) {
            if (isStrictlyBetween(y2, y1, y3)) return 3;
            return 2;
        }

        // Check pairs sharing a y-coordinate
        if (y1 == y2) {
            if (isStrictlyBetween(x3, x1, x2)) return 3;
            return 2;
        }
        if (y2 == y3) {
            if (isStrictlyBetween(x1, x2, x3)) return 3;
            return 2;
        }
        if (y1 == y3) {
            if (isStrictlyBetween(x2, x1, x3)) return 3;
            return 2;
        }

        // Default case: No shared coordinates between any pair
        return 3;
    }

    /**
     * Checks if a value lies strictly between two bounds.
     *
     * @param value The value to check
     * @param a     First bound
     * @param b     Second bound
     * @return true if value is strictly between a and b
     */
    private static boolean isStrictlyBetween(int value, int a, int b) {
        return value > Math.min(a, b) && value < Math.max(a, b);
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

public class Main {

    /**
     * A maintainable, standard-compliant fast I/O scanner.
     * Replaces the custom byte-buffer scanner for better readability, debugging, and extensibility.
     */
    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        public String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input", e);
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            String token = next();
            if (token == null) {
                throw new RuntimeException("Unexpected end of input");
            }
            return Integer.parseInt(token);
        }
    }

    /**
     * Represents a 2D coordinate point.
     */
    static class Point {
        final int x;
        final int y;

        Point(int x, int y) {
            this.x = x;
            this.y = y;
        }
    }

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner();

        // Read coordinates for three points
        Point p1 = new Point(scanner.nextInt(), scanner.nextInt());
        Point p2 = new Point(scanner.nextInt(), scanner.nextInt());
        Point p3 = new Point(scanner.nextInt(), scanner.nextInt());

        // Determine and print the result based on geometric alignment
        System.out.println(calculateResult(p1, p2, p3));
    }

    /**
     * Determines the output value (1, 2, or 3) based on the alignment of three points.
     *
     * @return 1 if all three points are collinear on the same vertical or horizontal line.
     *         2 if two points share a coordinate and the third lies on that same line 
     *            but outside (or on the boundary of) the segment formed by the pair.
     *         3 if no specific alignment condition is met.
     */
    private static int calculateResult(Point p1, Point p2, Point p3) {
        // Case 1: All three points share the exact same x or y coordinate
        if (p1.x == p2.x && p2.x == p3.x) return 1;
        if (p1.y == p2.y && p2.y == p3.y) return 1;

        // Case 2: Check each pair for shared coordinate with the third point outside the segment
        if (checkPairAlignment(p1, p2, p3)) return 2;
        if (checkPairAlignment(p1, p3, p2)) return 2;
        if (checkPairAlignment(p2, p3, p1)) return 2;

        // Case 3: No alignment condition matched
        return 3;
    }

    /**
     * Checks if p1 and p2 share a coordinate (x or y), and if p3 lies on that same line
     * but outside the closed segment defined by p1 and p2.
     *
     * @return true if the alignment condition for output 2 is met, false otherwise.
     */
    private static boolean checkPairAlignment(Point p1, Point p2, Point p3) {
        if (p1.x == p2.x) {
            // Vertical alignment: evaluate y-coordinates
            int min = Math.min(p1.y, p2.y);
            int max = Math.max(p1.y, p2.y);
            return p3.y <= min || p3.y >= max;
        }
        if (p1.y == p2.y) {
            // Horizontal alignment: evaluate x-coordinates
            int min = Math.min(p1.x, p2.x);
            int max = Math.max(p1.x, p2.x);
            return p3.x <= min || p3.x >= max;
        }
        return false;
    }
}

import java.io.BufferedReader;
import java.io.BufferedWriter;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.OutputStreamWriter;
import java.io.PrintWriter;
import java.util.HashMap;
import java.util.Map;
import java.util.StringTokenizer;

public class P617D {
    private static final int NUM_POINTS = 3;

    public static void main(String[] args) throws IOException {
        // Use try-with-resources for automatic and safe resource management
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
             PrintWriter pw = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)))) {

            int[] x = new int[NUM_POINTS];
            int[] y = new int[NUM_POINTS];

            for (int i = 0; i < NUM_POINTS; i++) {
                String line = br.readLine();
                if (line == null) break;

                // StringTokenizer robustly handles multiple spaces/newlines
                StringTokenizer st = new StringTokenizer(line);
                x[i] = Integer.parseInt(st.nextToken());
                y[i] = Integer.parseInt(st.nextToken());
            }

            pw.println(process(x, y));
        }
    }

    private static int process(int[] x, int[] y) {
        Map<Integer, Integer> xFreq = new HashMap<>();
        Map<Integer, Integer> yFreq = new HashMap<>();

        // Modern, concise frequency counting
        for (int i = 0; i < x.length; i++) {
            xFreq.merge(x[i], 1, Integer::sum);
            yFreq.merge(y[i], 1, Integer::sum);
        }

        // Guard clauses for early returns
        if (xFreq.size() == 1 || yFreq.size() == 1) {
            return 1;
        }
        if (xFreq.size() == 2 && yFreq.size() == 2) {
            return 2;
        }
        if (xFreq.size() == 2) {
            return evaluateThirdCoordinate(x, y);
        }
        if (yFreq.size() == 2) {
            return evaluateThirdCoordinate(y, x);
        }

        return 3;
    }

    /**
     * Evaluates the position of the third point relative to the two points
     * that share a coordinate. Returns 3 if strictly between, else 2.
     *
     * @param fixedCoord    The coordinate array with exactly 2 unique values
     * @param variableCoord The corresponding coordinate array to evaluate
     * @return 3 if the third point lies strictly between the min/max of the pair, else 2
     */
    private static int evaluateThirdCoordinate(int[] fixedCoord, int[] variableCoord) {
        // Identify the index of the point with the unique fixed coordinate
        int outlierIdx = (fixedCoord[0] == fixedCoord[1]) ? 2
                       : (fixedCoord[1] == fixedCoord[2]) ? 0
                       : 1;

        int thirdVal = variableCoord[outlierIdx];

        // Determine min/max of the variable coordinate for the pair sharing the fixed coordinate
        int minVal, maxVal;
        if (fixedCoord[0] == fixedCoord[1]) {
            minVal = Math.min(variableCoord[0], variableCoord[1]);
            maxVal = Math.max(variableCoord[0], variableCoord[1]);
        } else if (fixedCoord[1] == fixedCoord[2]) {
            minVal = Math.min(variableCoord[1], variableCoord[2]);
            maxVal = Math.max(variableCoord[1], variableCoord[2]);
        } else {
            minVal = Math.min(variableCoord[0], variableCoord[2]);
            maxVal = Math.max(variableCoord[0], variableCoord[2]);
        }

        return (thirdVal > minVal && thirdVal < maxVal) ? 3 : 2;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

public class Main {

    private static final int NUM_POINTS = 3;

    public static void main(String[] args) {
        // Standard try-with-resources for automatic resource management
        try (PrintWriter out = new PrintWriter(System.out)) {
            FastScanner scanner = new FastScanner(System.in);
            solve(scanner, out);
        } catch (IOException e) {
            throw new RuntimeException("Failed to read input", e);
        }
    }

    /**
     * Core logic for processing the three points and determining the output.
     */
    private static void solve(FastScanner scanner, PrintWriter out) {
        int[][] points = new int[NUM_POINTS][2];
        for (int i = 0; i < NUM_POINTS; i++) {
            points[i][0] = scanner.nextInt();
            points[i][1] = scanner.nextInt();
        }

        // Case 1: All three points are collinear on the X or Y axis
        if ((points[0][0] == points[1][0] && points[1][0] == points[2][0]) ||
            (points[0][1] == points[1][1] && points[1][1] == points[2][1])) {
            out.println(1);
            return;
        }

        // Case 2 & 3: Check if any two points share an X or Y coordinate
        for (int axis = 0; axis < 2; axis++) {
            for (int i = 0; i < NUM_POINTS; i++) {
                for (int j = i + 1; j < NUM_POINTS; j++) {
                    if (points[i][axis] == points[j][axis]) {
                        int k = 3 - i - j; // The index of the third point
                        int otherAxis = 1 - axis;

                        // Check if the third point lies strictly between the pair
                        // on the perpendicular axis. Using comparisons avoids overflow.
                        if (isStrictlyBetween(points[i][otherAxis], points[k][otherAxis], points[j][otherAxis])) {
                            out.println(3);
                        } else {
                            out.println(2);
                        }
                        return;
                    }
                }
            }
        }

        // Default case: No two points share an axis coordinate
        out.println(3);
    }

    /**
     * Checks if 'middle' is strictly between 'start' and 'end'.
     * Replaces the original multiplication check to prevent integer overflow
     * while maintaining identical logical behavior.
     */
    private static boolean isStrictlyBetween(int start, int middle, int end) {
        if (start < end) {
            return start < middle && middle < end;
        }
        return end < middle && middle < start;
    }

    /**
     * Lightweight, standard FastScanner for competitive programming.
     * Replaces the custom byte-buffer reader with a more maintainable approach.
     */
    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) {
                        throw new IOException("Unexpected end of input");
                    }
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            String token = next();
            try {
                return Integer.parseInt(token);
            } catch (NumberFormatException e) {
                throw new IllegalArgumentException("Invalid integer format: " + token);
            }
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

public class ProblemD2 {

    /**
     * Represents a 2D coordinate point.
     */
    private static class Point {
        final int x;
        final int y;

        Point(int x, int y) {
            this.x = x;
            this.y = y;
        }
    }

    public static void main(String[] args) throws IOException {
        // try-with-resources ensures the reader is closed automatically
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            List<Point> points = new ArrayList<>(3);
            for (int i = 0; i < 3; i++) {
                points.add(readPoint(br));
            }
            int result = compute(points);
            System.out.println(result);
        }
    }

    /**
     * Reads a single line containing two integers and returns a Point.
     */
    private static Point readPoint(BufferedReader br) throws IOException {
        String line = br.readLine();
        if (line == null || line.trim().isEmpty()) {
            throw new IOException("Unexpected end of input or empty line");
        }
        String[] parts = line.trim().split("\\s+");
        if (parts.length < 2) {
            throw new IOException("Invalid point format: expected two integers");
        }
        return new Point(Integer.parseInt(parts[0]), Integer.parseInt(parts[1]));
    }

    /**
     * Core business logic to determine the result based on coordinate distribution.
     */
    private static int compute(List<Point> points) {
        Map<Integer, Integer> xCounts = new HashMap<>();
        Map<Integer, Integer> yCounts = new HashMap<>();

        for (Point p : points) {
            xCounts.merge(p.x, 1, Integer::sum);
            yCounts.merge(p.y, 1, Integer::sum);
        }

        if (xCounts.size() == 1 || yCounts.size() == 1) {
            return 1;
        }
        if (xCounts.size() == 2) {
            return checkDegeneracy(points, xCounts, 0);
        }
        if (yCounts.size() == 2) {
            return checkDegeneracy(points, yCounts, 1);
        }
        return 3;
    }

    /**
     * Checks if the third point's coordinate lies strictly between the other two.
     * Fixes a logical bug in the original code where the duplicate coordinate's 
     * counterpart was overwritten instead of properly collected.
     *
     * @param coordIndex 0 for X-axis, 1 for Y-axis
     */
    private static int checkDegeneracy(List<Point> points, Map<Integer, Integer> coordCounts, int coordIndex) {
        int duplicateCoord = coordCounts.entrySet().stream()
                .filter(e -> e.getValue() == 2)
                .mapToInt(Map.Entry::getKey)
                .findFirst()
                .orElseThrow(() -> new IllegalStateException("Expected exactly one coordinate with count 2"));

        int[] matchingCoords = new int[2]; // Coordinates of the two points sharing the duplicate
        int singleCoord = 0;               // Coordinate of the third point
        int matchIdx = 0;

        for (Point p : points) {
            int current = coordIndex == 0 ? p.x : p.y;
            int other = coordIndex == 0 ? p.y : p.x;

            if (current == duplicateCoord) {
                matchingCoords[matchIdx++] = other;
            } else {
                singleCoord = other;
            }
        }

        Arrays.sort(matchingCoords);
        return (singleCoord <= matchingCoords[0] || singleCoord >= matchingCoords[1]) ? 2 : 3;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

public class CF340D {

    private static final int NUM_POINTS = 3;

    private final BufferedReader br;
    private final PrintWriter out;
    private StringTokenizer st;

    public CF340D() throws IOException {
        br = new BufferedReader(new InputStreamReader(System.in));
        out = new PrintWriter(System.out);
        solve();
        out.flush();
        out.close();
    }

    private void solve() throws IOException {
        long[] x = new long[NUM_POINTS];
        long[] y = new long[NUM_POINTS];
        for (int i = 0; i < NUM_POINTS; i++) {
            x[i] = nextLong();
            y[i] = nextLong();
        }

        // If all x-coordinates or all y-coordinates are identical
        if (areAllEqual(x) || areAllEqual(y)) {
            out.println(1);
            return;
        }

        for (int i = 0; i < NUM_POINTS; i++) {
            for (int j = i + 1; j < NUM_POINTS; j++) {
                int thirdIndex = getThirdIndex(i, j);

                if (x[i] == x[j]) {
                    handleSharedCoordinate(y[i], y[j], y[thirdIndex]);
                    return;
                }
                if (y[i] == y[j]) {
                    handleSharedCoordinate(x[i], x[j], x[thirdIndex]);
                    return;
                }
            }
        }
        out.println(3);
    }

    /**
     * Finds the index of the third point given two distinct indices.
     */
    private int getThirdIndex(int i, int j) {
        for (int k = 0; k < NUM_POINTS; k++) {
            if (k != i && k != j) {
                return k;
            }
        }
        throw new IllegalStateException("Could not find third index");
    }

    /**
     * Evaluates the position of the third point relative to two points
     * that share a coordinate on the same axis.
     */
    private void handleSharedCoordinate(long coord1, long coord2, long thirdCoord) {
        long min = Math.min(coord1, coord2);
        long max = Math.max(coord1, coord2);
        if (thirdCoord > min && thirdCoord < max) {
            out.println(3);
        } else {
            out.println(2);
        }
    }

    private boolean areAllEqual(long[] arr) {
        long first = arr[0];
        for (int i = 1; i < arr.length; i++) {
            if (arr[i] != first) {
                return false;
            }
        }
        return true;
    }

    private String nextToken() throws IOException {
        while (st == null || !st.hasMoreTokens()) {
            String line = br.readLine();
            if (line == null) return null;
            st = new StringTokenizer(line);
        }
        return st.nextToken();
    }

    private long nextLong() throws IOException {
        String s = nextToken();
        if (s == null) throw new IOException("Unexpected end of input");
        return Long.parseLong(s);
    }

    private int nextInt() throws IOException {
        String s = nextToken();
        if (s == null) throw new IOException("Unexpected end of input");
        return Integer.parseInt(s);
    }

    public static void main(String[] args) throws IOException {
        new CF340D();
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

public class Main {
    public static void main(String[] args) throws IOException {
        FastScanner scanner = new FastScanner();
        // Try-with-resources ensures PrintWriter is properly flushed and closed
        try (PrintWriter out = new PrintWriter(System.out)) {
            Point p1 = scanner.nextPoint();
            Point p2 = scanner.nextPoint();
            Point p3 = scanner.nextPoint();

            out.println(calculateMinimumLines(p1, p2, p3));
        }
    }

    /**
     * Determines the minimum number of axis-aligned line segments needed to connect three points.
     * 
     * Logic:
     * - 1 segment: All three points are collinear on a horizontal or vertical line.
     * - 2 segments: At least one pair of points shares an x or y coordinate.
     *   This allows connecting the aligned pair with one segment, and the third point 
     *   to that line with a second segment.
     * - 3 segments: No points share an axis, requiring a path through intermediate points.
     */
    private static int calculateMinimumLines(Point p1, Point p2, Point p3) {
        boolean allVerticallyAligned = (p1.x == p2.x && p2.x == p3.x);
        boolean allHorizontallyAligned = (p1.y == p2.y && p2.y == p3.y);

        if (allVerticallyAligned || allHorizontallyAligned) {
            return 1;
        }

        boolean anyAligned = (p1.x == p2.x || p1.x == p3.x || p2.x == p3.x ||
                              p1.y == p2.y || p1.y == p3.y || p2.y == p3.y);

        return anyAligned ? 2 : 3;
    }

    private static final class Point {
        final int x;
        final int y;

        Point(int x, int y) {
            this.x = x;
            this.y = y;
        }
    }

    /**
     * Lightweight, non-static input scanner for competitive programming style inputs.
     * Handles whitespace-separated tokens across multiple lines efficiently.
     */
    private static class FastScanner {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastScanner() {
            this.reader = new BufferedReader(new InputStreamReader(System.in));
            this.tokenizer = null;
        }

        private String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                String line = reader.readLine();
                if (line == null) throw new IOException("End of input");
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        public Point nextPoint() throws IOException {
            return new Point(nextInt(), nextInt());
        }
    }
}

import java.util.Scanner;

public class AimTechTaskC {

    // Constants for output to avoid magic strings
    private static final String OUTPUT_YES = "Yes";
    private static final String OUTPUT_NO = "No";
    private static final char CHAR_A = 'a';
    private static final char CHAR_B = 'b';
    private static final char CHAR_C = 'c';

    // Enum to represent node types, improving readability over boolean arrays
    private enum NodeType {
        A, B, C
    }

    public static void main(String[] args) {
        // Use try-with-resources to ensure the Scanner is closed properly
        try (Scanner scanner = new Scanner(System.in)) {
            if (!scanner.hasNextInt()) {
                return;
            }
            int n = scanner.nextInt();
            int m = scanner.nextInt();

            solve(n, m, scanner);
        }
    }

    /**
     * Orchestrates the logic for the task.
     */
    private static void solve(int n, int m, Scanner scanner) {
        // Special case: If there is only 1 node, the answer is always Yes with type 'a'
        if (n == 1) {
            System.out.println(OUTPUT_YES);
            System.out.println(CHAR_A);
            return;
        }

        // Build the adjacency matrix
        boolean[][] graph = buildGraph(n, m, scanner);

        // Determine the type (A, B, or C) for each node
        NodeType[] nodeTypes = determineNodeTypes(n, graph);

        // Validate if the graph structure matches the required rules
        if (isValidGraph(n, graph, nodeTypes)) {
            System.out.println(OUTPUT_YES);
            System.out.println(buildResultString(nodeTypes));
        } else {
            System.out.println(OUTPUT_NO);
        }
    }

    /**
     * Reads the edges and builds the adjacency matrix.
     */
    private static boolean[][] buildGraph(int n, int m, Scanner scanner) {
        boolean[][] graph = new boolean[n][n];
        for (int i = 0; i < m; i++) {
            // Input is 1-based, convert to 0-based
            int u = scanner.nextInt() - 1;
            int v = scanner.nextInt() - 1;
            graph[u][v] = true;
            graph[v][u] = true;
        }
        return graph;
    }

    /**
     * Classifies nodes into types A, B, and C based on connectivity.
     * Type B: Connected to all other nodes.
     * Type A: Connected to the "pivot" node (first non-B node).
     * Type C: Not connected to the "pivot" node.
     */
    private static NodeType[] determineNodeTypes(int n, boolean[][] graph) {
        NodeType[] types = new NodeType[n];

        // 1. Identify Type B nodes (nodes connected to everyone else)
        for (int i = 0; i < n; i++) {
            boolean connectedToAll = true;
            for (int j = 0; j < n; j++) {
                if (i == j) continue;
                if (!graph[i][j]) {
                    connectedToAll = false;
                    break;
                }
            }
            if (connectedToAll) {
                types[i] = NodeType.B;
            }
        }

        // 2. Find the first "undefined" node (first node that is not Type B)
        // This acts as the pivot for classifying A and C
        int pivotIndex = -1;
        for (int i = 0; i < n; i++) {
            if (types[i] != NodeType.B) {
                pivotIndex = i;
                break;
            }
        }

        // 3. Classify remaining nodes based on connection to the pivot
        if (pivotIndex != -1) {
            // The pivot itself is Type A (since it's not Type B)
            types[pivotIndex] = NodeType.A;

            for (int i = 0; i < n; i++) {
                if (i == pivotIndex) continue;
                if (types[i] == NodeType.B) continue; // Already classified as B

                // If connected to pivot, it's Type A. Otherwise, Type C.
                if (graph[pivotIndex][i]) {
                    types[i] = NodeType.A;
                } else {
                    types[i] = NodeType.C;
                }
            }
        }

        // If pivotIndex is -1, all nodes are Type B (handled in step 1)
        return types;
    }

    /**
     * Validates the graph against the specific rules derived from the original logic.
     */
    private static boolean isValidGraph(int n, boolean[][] graph, NodeType[] types) {
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (i == j) continue;

                NodeType u = types[i];
                NodeType v = types[j];
                boolean isConnected = graph[i][j];

                // Rule 1: An edge between A and C is forbidden.
                // Original: if (graph[i][j] && (isA[i] && isC[j] || isA[j] && isC[i]))
                if (isConnected && ((u == NodeType.A && v == NodeType.C) || (u == NodeType.C && v == NodeType.A))) {
                    return false;
                }

                // Rule 2: A missing edge is forbidden for specific pairs.
                // Original: if (!graph[i][j] && (isA[i] && isA[j] || isA[i] && isB[j] || ...))
                // Missing edges are forbidden for: (A,A), (A,B), (B,A), (B,B), (B,C), (C,B), (C,C)
                if (!isConnected) {
                    if (u == NodeType.A && v == NodeType.A) return false;
                    if (u == NodeType.A && v == NodeType.B) return false;
                    if (u == NodeType.B && v == NodeType.A) return false;
                    if (u == NodeType.B && v == NodeType.B) return false;
                    if (u == NodeType.B && v == NodeType.C) return false;
                    if (u == NodeType.C && v == NodeType.B) return false;
                    if (u == NodeType.C && v == NodeType.C) return false;
                }
            }
        }
        return true;
    }

    /**
     * Converts the node types array into the required output string.
     */
    private static String buildResultString(NodeType[] types) {
        StringBuilder sb = new StringBuilder(types.length);
        for (NodeType type : types) {
            switch (type) {
                case A:
                    sb.append(CHAR_A);
                    break;
                case B:
                    sb.append(CHAR_B);
                    break;
                case C:
                    sb.append(CHAR_C);
                    break;
                default:
                    // Fallback, though logic ensures this isn't reached
                    sb.append(CHAR_C); 
                    break;
            }
        }
        return sb.toString();
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.Arrays;
import java.util.StringTokenizer;

public class Main {
    // Constants for color assignments and defaults
    private static final int COLOR_A = 0;
    private static final int COLOR_B = 1;
    private static final int COLOR_C = 2;
    private static final int UNASSIGNED = -1;
    private static final char BASE_CHAR = 'a';

    public static void main(String[] args) {
        Main solver = new Main();
        try {
            solver.run();
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    /**
     * Entry point for the solution. Initializes I/O and delegates to the solver.
     */
    public void run() throws IOException {
        FastScanner scanner = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out);

        // Read input dimensions
        int numVertices = scanner.nextInt();
        int numEdges = scanner.nextInt();

        // Execute the core algorithm
        solve(numVertices, numEdges, scanner, out);

        out.flush();
    }

    /**
     * Core algorithm to determine valid graph coloring and constraints.
     */
    private void solve(int n, int m, FastScanner scanner, PrintWriter out) {
        int[][] adjacencyMatrix = new int[n + 1][n + 1];
        int[] degrees = new int[n + 1];

        // Read edges and build graph
        for (int i = 0; i < m; i++) {
            int u = scanner.nextInt();
            int v = scanner.nextInt();
            adjacencyMatrix[u][v] = adjacencyMatrix[v][u] = 1;
            degrees[u]++;
            degrees[v]++;
        }

        int[] colorAssignments = new int[n + 1];
        Arrays.fill(colorAssignments, UNASSIGNED);

        // Phase 1: Assign color to nodes with degree n-1
        for (int i = 1; i <= n; i++) {
            if (degrees[i] == n - 1) {
                colorAssignments[i] = COLOR_B;
            }
        }

        // Phase 2: Propagate colors based on non-edges
        for (int i = 1; i <= n; i++) {
            if (colorAssignments[i] != UNASSIGNED) continue;
            colorAssignments[i] = COLOR_A;

            for (int j = i + 1; j <= n; j++) {
                if (adjacencyMatrix[i][j] == 0) { // Non-adjacent nodes
                    if (colorAssignments[j] == UNASSIGNED) {
                        colorAssignments[j] = COLOR_C;
                    } else if (colorAssignments[j] != COLOR_C) {
                        out.println("No");
                        return;
                    }
                }
            }
        }

        // Phase 3: Validate all edge and non-edge constraints
        for (int i = 1; i <= n; i++) {
            for (int j = i + 1; j <= n; j++) {
                boolean isConnected = adjacencyMatrix[i][j] == 1;
                int colorDifference = Math.abs(colorAssignments[i] - colorAssignments[j]);

                if (isConnected) {
                    if (colorDifference > 1) {
                        out.println("No");
                        return;
                    }
                } else {
                    if (colorDifference != 2) {
                        out.println("No");
                        return;
                    }
                }
            }
        }

        // Phase 4: Output valid result
        out.println("Yes");
        StringBuilder result = new StringBuilder(n);
        for (int i = 1; i <= n; i++) {
            result.append((char) (BASE_CHAR + colorAssignments[i]));
        }
        out.println(result.toString());
    }

    /**
     * Fast I/O helper class for competitive programming.
     * Replaces low-level byte parsing with standard, maintainable Java I/O.
     */
    private static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        public String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) {
                        throw new IOException("End of input");
                    }
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

/**
 * Validates and assigns labels to nodes in an undirected graph based on degree
 * and connectivity properties. Outputs "Yes" and the label string if valid,
 * otherwise "No".
 */
public class GraphLabelValidator {

    public static void main(String[] args) {
        // Use try-with-resources to automatically close the Scanner
        try (Scanner scanner = new Scanner(System.in)) {
            if (!scanner.hasNextInt()) {
                return;
            }
            int n = scanner.nextInt();
            int m = scanner.nextInt();

            // Handle edge case of empty graph
            if (n <= 0) {
                System.out.println("No");
                return;
            }

            List<List<Integer>> adjacencyList = buildAdjacencyList(n);
            boolean[][] adjacencyMatrix = new boolean[n][n];
            readEdges(m, scanner, adjacencyList, adjacencyMatrix);

            char[] nodeLabels = assignNodeLabels(n, adjacencyList);
            boolean isValid = validateConfiguration(n, nodeLabels, adjacencyMatrix);

            printResult(isValid, nodeLabels);
        }
    }

    /**
     * Initializes and returns an adjacency list representation of the graph.
     */
    private static List<List<Integer>> buildAdjacencyList(int n) {
        List<List<Integer>> adj = new ArrayList<>(n);
        for (int i = 0; i < n; i++) {
            adj.add(new ArrayList<>());
        }
        return adj;
    }

    /**
     * Reads m edges from input, updates the adjacency list and matrix.
     * Converts 1-based input indices to 0-based internally.
     */
    private static void readEdges(int m, Scanner scanner, List<List<Integer>> adj, boolean[][] matrix) {
        for (int i = 0; i < m; i++) {
            int u = scanner.nextInt() - 1; // Convert 1-based to 0-based
            int v = scanner.nextInt() - 1;

            adj.get(u).add(v);
            adj.get(v).add(u);
            matrix[u][v] = true;
            matrix[v][u] = true;
        }
    }

    /**
     * Assigns labels to nodes based on graph properties:
     * 'b' - Universal node (connected to all other nodes)
     * 'a' - Connected to the first non-universal node found
     * 'c' - Remaining non-universal nodes
     * 'x' - Temporary placeholder, replaced before returning
     */
    private static char[] assignNodeLabels(int n, List<List<Integer>> adj) {
        char[] labels = new char[n];

        // Step 1: Mark universal nodes
        for (int i = 0; i < n; i++) {
            labels[i] = (adj.get(i).size() == n - 1) ? 'b' : 'x';
        }

        // Step 2: Find the first non-universal node
        int firstNonUniversalIndex = -1;
        for (int i = 0; i < n; i++) {
            if (labels[i] == 'x') {
                firstNonUniversalIndex = i;
                break;
            }
        }

        // Step 3: Assign 'a' and 'c' if a non-universal node exists
        if (firstNonUniversalIndex != -1) {
            int idx = firstNonUniversalIndex;
            labels[idx] = 'a';

            // Mark all neighbors of the first non-universal node as 'a'
            for (int neighbor : adj.get(idx)) {
                if (labels[neighbor] == 'x') {
                    labels[neighbor] = 'a';
                }
            }

            // Mark all remaining 'x' nodes as 'c'
            for (int i = 0; i < n; i++) {
                if (labels[i] == 'x') {
                    labels[i] = 'c';
                }
            }
        }

        return labels;
    }

    /**
     * Validates the label configuration against graph edges and non-edges.
     * Rules:
     * 1. If an edge exists between two non-'b' nodes, they must share the same label.
     * 2. If no edge exists between two nodes, they must share a label OR one of them must be 'b'.
     */
    private static boolean validateConfiguration(int n, char[] labels, boolean[][] matrix) {
        for (int i = 0; i < n; i++) {
            if (labels[i] == 'b') continue; // Skip validation for universal nodes

            for (int j = 0; j < n; j++) {
                if (i == j) continue;

                boolean hasEdge = matrix[i][j];
                boolean jIsB = labels[j] == 'b';
                boolean sameLabel = labels[i] == labels[j];

                if (hasEdge) {
                    // Edge exists between different non-b nodes -> Invalid
                    if (!sameLabel && !jIsB) {
                        return false;
                    }
                } else {
                    // No edge exists between same-label nodes or if j is b -> Invalid
                    if (sameLabel || jIsB) {
                        return false;
                    }
                }
            }
        }
        return true;
    }

    /**
     * Prints the result based on validation outcome.
     */
    private static void printResult(boolean isValid, char[] labels) {
        if (isValid) {
            System.out.println("Yes");
            System.out.println(new String(labels));
        } else {
            System.out.println("No");
        }
    }
}

import java.io.*;
import java.util.*;

public class ProblemA {
    // Constants for node colors to improve readability and maintainability
    private static final char UNASSIGNED = '\0';
    private static final char COLOR_A = 'a';
    private static final char COLOR_B = 'b';
    private static final char COLOR_C = 'c';

    public static void main(String[] args) {
        InputReader reader = new InputReader(System.in);
        PrintWriter out = new PrintWriter(System.out);
        try {
            GraphAnalyzer analyzer = new GraphAnalyzer();
            analyzer.analyze(reader, out);
        } finally {
            out.flush();
            out.close();
        }
    }

    /**
     * Stateless analyzer responsible for processing graph data and determining node colors.
     * Replaces the original mutable stateful Solver class.
     */
    static class GraphAnalyzer {
        public void analyze(InputReader reader, PrintWriter out) {
            int numVertices = reader.nextInt();
            int numEdges = reader.nextInt();
            boolean[][] adjacencyMatrix = buildAdjacencyMatrix(numVertices, numEdges, reader);
            String result = determineNodeColors(numVertices, adjacencyMatrix);
            out.println(result);
        }

        private boolean[][] buildAdjacencyMatrix(int n, int m, InputReader reader) {
            boolean[][] matrix = new boolean[n + 1][n + 1];
            for (int i = 0; i < m; i++) {
                int u = reader.nextInt();
                int v = reader.nextInt();
                matrix[u][v] = matrix[v][u] = true;
            }
            return matrix;
        }

        private String determineNodeColors(int n, boolean[][] adjacencyMatrix) {
            char[] colors = new char[n + 1];
            Queue<Integer> queue = new ArrayDeque<>();

            for (int i = 1; i <= n; i++) {
                // Skip nodes that are connected to all others, or already colored
                if (isFullyConnected(i, n, adjacencyMatrix) || colors[i] != UNASSIGNED) {
                    continue;
                }

                colors[i] = COLOR_A;
                queue.add(i);

                while (!queue.isEmpty()) {
                    int current = queue.poll();
                    for (int next = 1; next <= n; next++) {
                        // Skip self and nodes with an existing edge
                        if (current == next || adjacencyMatrix[current][next]) {
                            continue;
                        }

                        // Conflict: same color assigned to nodes connected by a non-edge
                        if (colors[next] == colors[current]) {
                            return "No";
                        }

                        // Already colored
                        if (colors[next] != UNASSIGNED) {
                            continue;
                        }

                        // Assign alternating colors 'a' and 'c'
                        colors[next] = (colors[current] == COLOR_A) ? COLOR_C : COLOR_A;
                        queue.add(next);
                    }
                }
            }

            // Assign 'b' to any remaining uncolored nodes
            for (int i = 1; i <= n; i++) {
                if (colors[i] == UNASSIGNED) {
                    colors[i] = COLOR_B;
                }
            }

            // Validate: no original edge should connect COLOR_A and COLOR_C
            if (!validateColorConstraints(n, adjacencyMatrix, colors)) {
                return "No";
            }

            return "Yes\n" + new String(colors, 1, n);
        }

        private boolean isFullyConnected(int node, int n, boolean[][] adjacencyMatrix) {
            for (int j = 1; j <= n; j++) {
                if (j != node && !adjacencyMatrix[node][j]) {
                    return false;
                }
            }
            return true;
        }

        private boolean validateColorConstraints(int n, boolean[][] adjacencyMatrix, char[] colors) {
            for (int i = 1; i <= n; i++) {
                for (int j = i + 1; j <= n; j++) {
                    if (adjacencyMatrix[i][j]) {
                        if ((colors[i] == COLOR_A && colors[j] == COLOR_C) ||
                            (colors[i] == COLOR_C && colors[j] == COLOR_A)) {
                            return false;
                        }
                    }
                }
            }
            return true;
        }
    }

    static class InputReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            String s = next();
            if (s == null) throw new RuntimeException("Unexpected end of input");
            return Integer.parseInt(s);
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayDeque;
import java.util.Arrays;
import java.util.Queue;
import java.util.StringTokenizer;

public class ProblemC {

    public static void main(String[] args) {
        try {
            run();
        } catch (IOException e) {
            System.err.println("Failed to read input: " + e.getMessage());
        }
    }

    /**
     * Orchestrates input reading, graph construction, solving, and output.
     */
    private static void run() throws IOException {
        FastScanner scanner = new FastScanner();
        String nStr = scanner.next();
        if (nStr == null) return;

        int n = Integer.parseInt(nStr);
        int m = Integer.parseInt(scanner.next());

        boolean[][] adjacencyMatrix = new boolean[n][n];
        for (int i = 0; i < m; i++) {
            int u = Integer.parseInt(scanner.next()) - 1;
            int v = Integer.parseInt(scanner.next()) - 1;
            adjacencyMatrix[u][v] = true;
            adjacencyMatrix[v][u] = true;
        }

        int[] coloring = solve(n, adjacencyMatrix);
        System.out.println(coloring != null ? "Yes" : "No");
        if (coloring != null) {
            System.out.println(formatColoring(coloring));
        }
    }

    /**
     * Solves the problem by performing two passes:
     * 1. BFS on the complement graph to 2-color it (colors 1 and 3).
     * 2. Validates constraints on the original graph. Assigns color 2 to uncolored nodes.
     * Returns the valid coloring array, or null if constraints are violated.
     */
    private static int[] solve(int n, boolean[][] adj) {
        int[] colors = new int[n];
        boolean[] visited = new boolean[n];

        // Pass 1: 2-color the complement graph
        for (int i = 0; i < n; i++) {
            if (visited[i]) continue;

            boolean hasNonEdge = false;
            for (int j = 0; j < n; j++) {
                if (i != j && !adj[i][j]) {
                    hasNonEdge = true;
                    break;
                }
            }
            if (!hasNonEdge) continue;

            colors[i] = 1;
            visited[i] = true;
            Queue<Integer> queue = new ArrayDeque<>();
            queue.add(i);

            while (!queue.isEmpty()) {
                int curr = queue.poll();
                for (int j = 0; j < n; j++) {
                    if (curr != j && !adj[curr][j]) {
                        if (!visited[j]) {
                            visited[j] = true;
                            colors[j] = 4 - colors[curr]; // Toggles between 1 and 3
                            queue.add(j);
                        } else if (colors[j] != 4 - colors[curr]) {
                            return null; // Complement graph is not bipartite
                        }
                    }
                }
            }
        }

        // Pass 2: Validate original graph constraints
        Arrays.fill(visited, false);
        for (int i = 0; i < n; i++) {
            if (visited[i]) continue;

            visited[i] = true;
            if (colors[i] == 0) colors[i] = 2; // Fallback color for uncolored nodes

            Queue<Integer> queue = new ArrayDeque<>();
            queue.add(i);

            while (!queue.isEmpty()) {
                int curr = queue.poll();
                for (int j = 0; j < n; j++) {
                    if (curr != j && adj[curr][j]) {
                        if (colors[j] == 0) colors[j] = 2;
                        // Check if an edge connects nodes colored 1 and 3
                        if (Math.abs(colors[curr] - colors[j]) == 2) {
                            return null; // Invalid edge constraint
                        }
                        if (!visited[j]) {
                            visited[j] = true;
                            queue.add(j);
                        }
                    }
                }
            }
        }

        return colors;
    }

    /**
     * Converts numeric colors to characters ('a' for 1, 'b' for 2, 'c' for 3).
     */
    private static String formatColoring(int[] colors) {
        StringBuilder sb = new StringBuilder(colors.length);
        for (int color : colors) {
            sb.append((char) ('a' + color - 1));
        }
        return sb.toString();
    }

    /**
     * Lightweight fast I/O helper to replace custom parsing logic.
     * Handles whitespace-separated tokens efficiently.
     */
    private static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        public String next() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) return null;
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Solves the graph partitioning problem into up to 3 cliques.
 * Vertices are assigned to cliques labeled 'a', 'b', or 'c'.
 * Universal vertices (connected to all others) are assigned to clique 'b'.
 */
public class CliquePartitionSolver {

    private static final String CLIQUE_LABELS = "abc";
    private static final int UNASSIGNED = -1;
    private static final int CLIQUE_B = 1; // Reserved for universal vertices

    public static void main(String[] args) {
        // Use try-with-resources for automatic and safe resource management
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
             PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out))) {

            FastScanner scanner = new FastScanner(br);
            String nStr = scanner.next();
            if (nStr == null) return; // Handle empty input gracefully

            int n = Integer.parseInt(nStr);
            int m = scanner.nextInt();

            boolean[][] adjacencyMatrix = new boolean[n][n];
            for (int i = 0; i < m; i++) {
                int u = scanner.nextInt() - 1;
                int v = scanner.nextInt() - 1;
                adjacencyMatrix[u][v] = adjacencyMatrix[v][u] = true;
            }

            int[] assignment = solve(n, adjacencyMatrix);
            if (assignment != null) {
                out.println("Yes");
                for (int label : assignment) {
                    out.print(CLIQUE_LABELS.charAt(label));
                }
                out.println();
            } else {
                out.println("No");
            }
            out.flush();
        } catch (IOException e) {
            System.err.println("I/O error occurred: " + e.getMessage());
        }
    }

    /**
     * Core algorithm to determine if the graph can be partitioned into 3 cliques.
     *
     * @param n     Number of vertices
     * @param adj   Adjacency matrix representing the graph
     * @return      Array of clique labels (0, 1, or 2) if a valid partition exists, else null
     */
    private static int[] solve(int n, boolean[][] adj) {
        int[] assignment = new int[n];
        Arrays.fill(assignment, UNASSIGNED);

        // 1. Assign universal vertices (degree == n-1) to clique B (label 1)
        for (int i = 0; i < n; i++) {
            int degree = 0;
            for (boolean isConnected : adj[i]) {
                if (isConnected) degree++;
            }
            if (degree == n - 1) {
                assignment[i] = CLIQUE_B;
            }
        }

        // 2. Find an unassigned vertex to initiate partitioning
        int startNode = -1;
        for (int i = 0; i < n; i++) {
            if (assignment[i] == UNASSIGNED) {
                startNode = i;
                break;
            }
        }

        if (startNode != -1) {
            // Try assigning clique A (label 0)
            if (!tryAssignClique(0, startNode, assignment, adj, n)) {
                // Try assigning clique C (label 2)
                if (!tryAssignClique(2, startNode, assignment, adj, n)) {
                    return null; // Cannot form a valid partition
                }
            }
        }

        // 3. Verify all vertices are successfully assigned
        for (int label : assignment) {
            if (label == UNASSIGNED) {
                return null;
            }
        }
        return assignment;
    }

    /**
     * Attempts to assign a clique to a set of candidate vertices.
     * Candidates are defined as the startNode and its currently unassigned neighbors.
     * Validates the clique property:
     *   - All candidates must be mutually connected.
     *   - No candidate may connect to any other unassigned vertex.
     *
     * @param cliqueId    Target clique label (0 for 'a', 2 for 'c')
     * @param startNode   Seed vertex for candidate selection
     * @param assignment  Current assignment array
     * @param adj         Adjacency matrix
     * @param n           Number of vertices
     * @return            true if the clique is valid and assigned, false otherwise
     */
    private static boolean tryAssignClique(int cliqueId, int startNode, int[] assignment, 
                                           boolean[][] adj, int n) {
        boolean[] isCandidate = new boolean[n];

        // Identify candidates: startNode + its unassigned neighbors
        for (int j = 0; j < n; j++) {
            if (adj[startNode][j] && assignment[j] == UNASSIGNED) {
                isCandidate[j] = true;
            }
        }
        isCandidate[startNode] = true;

        boolean isValid = true;

        // Validate clique constraints
        for (int j = 0; j < n; j++) {
            if (!isCandidate[j]) continue;

            for (int k = 0; k < n; k++) {
                // Skip self and already assigned clique B (universal vertices)
                if (j == k || assignment[k] == CLIQUE_B) continue;

                if (isCandidate[k]) {
                    // Both in candidate set: must be connected
                    if (!adj[j][k]) {
                        isValid = false;
                        break;
                    }
                } else {
                    // One in candidate, one not: must NOT be connected
                    if (adj[j][k]) {
                        isValid = false;
                        break;
                    }
                }
            }
            if (!isValid) break;
        }

        // Only commit assignment if validation passed
        // (Original code had a bug where it assigned unconditionally inside the validation loop)
        if (isValid) {
            for (int j = 0; j < n; j++) {
                if (isCandidate[j]) {
                    assignment[j] = cliqueId;
                }
            }
        }
        return isValid;
    }

    /**
     * Lightweight, maintainable fast input scanner using standard Java I/O.
     */
    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner(BufferedReader br) {
            this.br = br;
        }

        public String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input", e);
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            String token = next();
            if (token == null) throw new NoSuchElementException("Unexpected end of input");
            return Integer.parseInt(token);
        }
    }
}

import java.io.*;
import java.util.Arrays;
import java.util.StringTokenizer;

/**
 * Solves a graph partitioning problem where nodes must be assigned labels 'a', 'b', or 'c'
 * such that:
 * - 'b' nodes are universal (connected to all other nodes)
 * - 'a' nodes form a clique and connect to all 'b' nodes, but NOT to 'c' nodes
 * - 'c' nodes form a clique and connect to all 'b' nodes, but NOT to 'a' nodes
 */
public class GraphPartitionValidator {

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out));

        try {
            int n = scanner.nextInt();
            int m = scanner.nextInt();

            boolean[][] adjacencyMatrix = readGraph(n, m, scanner);
            char[] nodeLabels = assignLabels(n, adjacencyMatrix);

            if (nodeLabels != null && validateGraph(n, adjacencyMatrix, nodeLabels)) {
                out.println("Yes");
                out.println(new String(nodeLabels));
            } else {
                out.println("No");
            }
        } finally {
            out.flush();
        }
    }

    /**
     * Reads the graph from input and builds an adjacency matrix.
     */
    private static boolean[][] readGraph(int n, int m, FastScanner scanner) {
        boolean[][] adj = new boolean[n][n];
        for (int i = 0; i < m; i++) {
            int u = scanner.nextInt() - 1; // Convert 1-based to 0-based
            int v = scanner.nextInt() - 1;
            adj[u][v] = adj[v][u] = true;
        }
        return adj;
    }

    /**
     * Assigns labels to nodes based on the graph structure.
     * Strategy:
     * 1. Mark universal nodes as 'b'
     * 2. Pick the first unmarked node, assign 'a', and mark all its unmarked neighbors as 'a'
     * 3. Assign remaining unmarked nodes as 'c'
     */
    private static char[] assignLabels(int n, boolean[][] adj) {
        if (n == 0) return new char[0];

        char[] labels = new char[n];
        Arrays.fill(labels, 0); // 0 represents unassigned

        // Step 1: Identify universal nodes ('b')
        for (int i = 0; i < n; i++) {
            boolean isUniversal = true;
            for (int j = 0; j < n; j++) {
                if (i != j && !adj[i][j]) {
                    isUniversal = false;
                    break;
                }
            }
            labels[i] = isUniversal ? 'b' : 0;
        }

        // Step 2: Find first non-'b' node, assign 'a', and propagate to neighbors
        int firstNonB = -1;
        for (int i = 0; i < n; i++) {
            if (labels[i] == 0) {
                firstNonB = i;
                break;
            }
        }

        if (firstNonB != -1) {
            labels[firstNonB] = 'a';
            for (int j = 0; j < n; j++) {
                if (j != firstNonB && adj[firstNonB][j] && labels[j] == 0) {
                    labels[j] = 'a';
                }
            }
        }

        // Step 3: Assign remaining unassigned nodes to 'c'
        for (int i = 0; i < n; i++) {
            if (labels[i] == 0) {
                labels[i] = 'c';
            }
        }

        return labels;
    }

    /**
     * Validates whether the assigned labels satisfy the graph constraints.
     */
    private static boolean validateGraph(int n, boolean[][] adj, char[] labels) {
        for (int i = 0; i < n; i++) {
            char currentLabel = labels[i];
            for (int j = 0; j < n; j++) {
                if (i == j) continue;

                char neighborLabel = labels[j];
                boolean shouldConnect = false;

                switch (currentLabel) {
                    case 'b':
                        shouldConnect = true; // Universal nodes connect to everyone
                        break;
                    case 'a':
                        shouldConnect = (neighborLabel == 'a' || neighborLabel == 'b');
                        break;
                    case 'c':
                        shouldConnect = (neighborLabel == 'b' || neighborLabel == 'c');
                        break;
                    default:
                        return false; // Invalid label
                }

                if (adj[i][j] != shouldConnect) {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Lightweight fast I/O utility for competitive programming / high-throughput scenarios.
     */
    private static class FastScanner {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastScanner(InputStream in) {
            reader = new BufferedReader(new InputStreamReader(in));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input", e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            String s = next();
            if (s == null) throw new RuntimeException("Unexpected end of input");
            return Integer.parseInt(s);
        }
    }
}

import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.util.Arrays;
import java.util.LinkedList;
import java.util.StringTokenizer;

public class AIMDiv2C {
    // Constants representing node labels/types
    private static final int UNASSIGNED = -1;
    private static final int TYPE_A = 0;
    private static final int TYPE_B = 1;
    private static final int TYPE_C = 2;

    // Graph and state management
    private int[][] adjacencyMatrix;
    private int[] nodeLabels;
    private boolean conflictDetected;
    private boolean firstComponentProcessed;

    public static void main(String[] args) throws Exception {
        new AIMDiv2C().solve();
    }

    public void solve() throws Exception {
        readInput();
        assignInitialLabels();
        if (validateInitialLabels()) {
            adjustLabels();
            performFinalValidation();
            outputResult();
        } else {
            System.out.println("No");
        }
    }

    private void readInput() throws Exception {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(reader.readLine());
        int n = Integer.parseInt(st.nextToken());
        int m = Integer.parseInt(st.nextToken());

        adjacencyMatrix = new int[n][n];
        nodeLabels = new int[n];
        Arrays.fill(nodeLabels, UNASSIGNED);

        for (int i = 0; i < m; i++) {
            st = new StringTokenizer(reader.readLine());
            int u = Integer.parseInt(st.nextToken()) - 1;
            int v = Integer.parseInt(st.nextToken()) - 1;
            adjacencyMatrix[u][v] = adjacencyMatrix[v][u] = 1;
        }
    }

    private void assignInitialLabels() {
        conflictDetected = false;
        firstComponentProcessed = false;

        for (int i = 0; i < nodeLabels.length; i++) {
            if (nodeLabels[i] == UNASSIGNED) {
                bfs(i);
            }
        }
    }

    private void bfs(int startNode) {
        LinkedList<Integer> queue = new LinkedList<>();
        queue.add(startNode);
        nodeLabels[startNode] = firstComponentProcessed ? TYPE_C : TYPE_A;
        firstComponentProcessed = true;

        while (!queue.isEmpty()) {
            int u = queue.poll();
            // Note: Iteration starts from 1 to preserve original behavioral parity
            for (int v = 1; v < nodeLabels.length; v++) {
                if (adjacencyMatrix[u][v] == 1 && nodeLabels[v] == UNASSIGNED) {
                    queue.add(v);
                    assignLabelBasedOnRules(u, v);
                }
            }
        }
    }

    private void assignLabelBasedOnRules(int u, int v) {
        if (!conflictDetected) {
            if (nodeLabels[u] == TYPE_C) {
                nodeLabels[v] = TYPE_C;
            } else if (isFullyConnectedToType(v, TYPE_A)) {
                nodeLabels[v] = TYPE_A;
            } else {
                nodeLabels[u] = TYPE_B;
                nodeLabels[v] = TYPE_C;
                conflictDetected = true;
            }
        } else {
            if (isFullyConnectedToType(v, TYPE_B)) {
                if (isFullyConnectedToType(v, TYPE_C)) {
                    if (isFullyConnectedToType(v, TYPE_A)) {
                        nodeLabels[v] = TYPE_B;
                    } else {
                        nodeLabels[v] = TYPE_C;
                    }
                } else if (isFullyConnectedToType(v, TYPE_A)) {
                    nodeLabels[v] = TYPE_A;
                } else {
                    nodeLabels[v] = TYPE_B;
                }
            } else {
                conflictDetected = true;
            }
        }
    }

    private boolean isFullyConnectedToType(int node, int targetType) {
        for (int i = 0; i < nodeLabels.length; i++) {
            if (i == node) continue;
            if (nodeLabels[i] == targetType && adjacencyMatrix[node][i] != 1) {
                return false;
            }
        }
        return true;
    }

    private boolean validateInitialLabels() {
        for (int i = 0; i < nodeLabels.length; i++) {
            if (!validateNode(i)) {
                return false;
            }
        }
        return true;
    }

    private boolean validateNode(int i) {
        if (nodeLabels[i] == UNASSIGNED || !isFullyConnectedToType(i, TYPE_B)) {
            return false;
        }
        switch (nodeLabels[i]) {
            case TYPE_A:
                return isFullyConnectedToType(i, TYPE_A);
            case TYPE_B:
                return isFullyConnectedToType(i, TYPE_A) && isFullyConnectedToType(i, TYPE_C);
            case TYPE_C:
                return isFullyConnectedToType(i, TYPE_C);
            default:
                return false;
        }
    }

    private void adjustLabels() {
        for (int i = 0; i < nodeLabels.length; i++) {
            boolean connectedToAllTypes = true;
            for (int type = 0; type <= TYPE_C; type++) {
                if (!isFullyConnectedToType(i, type)) {
                    connectedToAllTypes = false;
                    break;
                }
            }
            if (connectedToAllTypes) {
                nodeLabels[i] = TYPE_B;
            }
        }
    }

    private void performFinalValidation() {
        for (int i = 0; i < nodeLabels.length; i++) {
            if (nodeLabels[i] == TYPE_A) {
                for (int j = 0; j < nodeLabels.length; j++) {
                    if (i != j && nodeLabels[j] == TYPE_C && adjacencyMatrix[j][i] == 1) {
                        System.out.println("No");
                        return;
                    }
                }
            } else if (nodeLabels[i] == TYPE_C) {
                for (int j = 0; j < nodeLabels.length; j++) {
                    if (i != j && nodeLabels[j] == TYPE_A && adjacencyMatrix[j][i] == 1) {
                        System.out.println("No");
                        return;
                    }
                }
            }
        }
    }

    private void outputResult() {
        StringBuilder result = new StringBuilder(nodeLabels.length);
        for (int label : nodeLabels) {
            result.append((char) (label + 'a'));
        }
        System.out.println("Yes");
        System.out.println(result);
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.ArrayList;
import java.util.List;
import java.util.StringTokenizer;

/**
 * Refactored graph processing program.
 * 
 * Original logic:
 * 1. Reads a graph and marks nodes with degree n-1 as 'b'.
 * 2. Attempts to partition remaining nodes into an 'a' clique and a 'c' clique.
 * 3. Validates that each group forms a complete subgraph (clique).
 * 4. Verifies that all nodes are assigned and no edges exist between 'a' and 'c' nodes.
 * 
 * Note: Unused helper methods (getd1, getd2) implementing Manacher's algorithm 
 * were removed as they were never called in the original code.
 */
public class Main {

    public static void main(String[] args) throws IOException {
        // Use try-with-resources to guarantee proper stream closure
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
             PrintWriter writer = new PrintWriter(System.out)) {

            String line = reader.readLine();
            if (line == null) return;

            StringTokenizer tokenizer = new StringTokenizer(line);
            int n = Integer.parseInt(tokenizer.nextToken());
            int m = Integer.parseInt(tokenizer.nextToken());

            // Initialize adjacency list
            List<List<Integer>> adjacencyList = new ArrayList<>(n);
            for (int i = 0; i < n; i++) {
                adjacencyList.add(new ArrayList<>());
            }

            // Read edges
            for (int i = 0; i < m; i++) {
                line = reader.readLine();
                if (line == null) break;
                tokenizer = new StringTokenizer(line);
                int u = Integer.parseInt(tokenizer.nextToken()) - 1;
                int v = Integer.parseInt(tokenizer.nextToken()) - 1;
                adjacencyList.get(u).add(v);
                adjacencyList.get(v).add(u);
            }

            // State array: 'a', 'b', 'c', or 0 (unassigned)
            char[] nodeState = new char[n];

            // Step 1: Mark nodes connected to every other node as 'b'
            markFullyConnectedNodes(n, adjacencyList, nodeState);

            // Step 2: Attempt to form and validate an 'a' clique from non-'b' nodes
            if (!formAndValidateClique(adjacencyList, nodeState, 'a', 'b')) {
                writer.println("No");
                return;
            }

            // Step 3: Attempt to form and validate a 'c' clique from remaining unassigned nodes
            if (!formAndValidateClique(adjacencyList, nodeState, 'c', 'a', 'b')) {
                writer.println("No");
                return;
            }

            // Step 4: Verify final configuration constraints
            if (verifyFinalConfiguration(n, adjacencyList, nodeState)) {
                writer.println("Yes");
                writer.println(new String(nodeState));
            } else {
                writer.println("No");
            }
        }
    }

    /**
     * Marks all nodes that are connected to every other node as 'b'.
     */
    private static void markFullyConnectedNodes(int n, List<List<Integer>> adj, char[] state) {
        for (int i = 0; i < n; i++) {
            if (adj.get(i).size() == n - 1) {
                state[i] = 'b';
            }
        }
    }

    /**
     * Finds the first unassigned node (excluding specified characters),
     * marks it and its compatible neighbors as the target character,
     * and validates that they form a clique.
     */
    private static boolean formAndValidateClique(List<List<Integer>> adj, char[] state, char targetChar, char... excludedChars) {
        // Find first eligible starting node
        int startNode = -1;
        for (int i = 0; i < state.length; i++) {
            if (!isExcluded(state[i], excludedChars)) {
                startNode = i;
                break;
            }
        }

        // If all nodes are already assigned, validation passes trivially
        if (startNode == -1) {
            return true;
        }

        // Mark the clique
        state[startNode] = targetChar;
        int cliqueSize = 1;
        for (int neighbor : adj.get(startNode)) {
            if (!isExcluded(state[neighbor], excludedChars)) {
                state[neighbor] = targetChar;
                cliqueSize++;
            }
        }

        // Validate clique property: every member must have exactly (cliqueSize - 1) 
        // neighbors within the same target group.
        int[] intraGroupDegree = new int[state.length];
        for (int i = 0; i < state.length; i++) {
            if (state[i] == targetChar) {
                for (int neighbor : adj.get(i)) {
                    if (state[neighbor] == targetChar) {
                        intraGroupDegree[neighbor]++;
                    }
                }
            }
        }

        for (int i = 0; i < state.length; i++) {
            if (state[i] == targetChar && intraGroupDegree[i] != cliqueSize - 1) {
                return false;
            }
        }

        return true;
    }

    /**
     * Checks if a character matches any character in the exclusion list.
     */
    private static boolean isExcluded(char current, char[] excluded) {
        for (char ex : excluded) {
            if (current == ex) {
                return true;
            }
        }
        return false;
    }

    /**
     * Verifies that all nodes are assigned and there are no edges between 'a' and 'c' nodes.
     * ASCII difference between 'a' (97) and 'c' (99) is exactly 2.
     */
    private static boolean verifyFinalConfiguration(int n, List<List<Integer>> adj, char[] state) {
        int assignedCount = 0;
        for (char s : state) {
            if (s == 'a' || s == 'b' || s == 'c') {
                assignedCount++;
            }
        }

        int t = assignedCount;
        // Iterate over all edges (undirected graph, so each edge is visited twice)
        for (int i = 0; i < n; i++) {
            for (int neighbor : adj.get(i)) {
                if (Math.abs(state[i] - state[neighbor]) == 2) {
                    t--;
                }
            }
        }

        return t == n;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.OutputStream;
import java.io.PrintWriter;
import java.util.Arrays;
import java.util.StringTokenizer;

public class Main {

    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);

        GraphPartitionSolver solver = new GraphPartitionSolver();
        solver.solve(in, out);

        out.close();
    }

    /**
     * Solver class for the graph partition problem.
     * Encapsulates the logic for reading input, processing the graph, and outputting results.
     */
    static class GraphPartitionSolver {

        // Constants for node types to replace magic numbers
        private static final int TYPE_UNASSIGNED = -1;
        private static final int TYPE_A = 0;
        private static final int TYPE_B = 1;

        public void solve(InputReader in, PrintWriter out) {
            int n = in.nextInt();
            int m = in.nextInt();

            // Adjacency matrix to represent the graph
            // Using boolean matrix for O(1) edge lookup
            boolean[][] adjacencyMatrix = new boolean[n][n];

            // Read edges
            for (int i = 0; i < m; ++i) {
                int u = in.nextInt() - 1; // Convert to 0-based index
                int v = in.nextInt() - 1;
                adjacencyMatrix[u][v] = adjacencyMatrix[v][u] = true;
            }

            // Set self-loops to true (a node is connected to itself)
            for (int i = 0; i < n; ++i) {
                adjacencyMatrix[i][i] = true;
            }

            // Array to store the type of each node
            int[] nodeTypes = new int[n];
            Arrays.fill(nodeTypes, TYPE_UNASSIGNED);

            // Step 1: Identify Type B nodes
            // A node is Type B if it is connected to all other nodes (including itself).
            for (int i = 0; i < n; ++i) {
                boolean isConnectedToAll = true;
                for (int j = 0; j < n; ++j) {
                    if (!adjacencyMatrix[i][j]) {
                        isConnectedToAll = false;
                        break;
                    }
                }
                if (isConnectedToAll) {
                    nodeTypes[i] = TYPE_B;
                }
            }

            // Step 2: Find a connected component among unassigned nodes
            // We perform a DFS starting from the first unassigned node.
            boolean[] visited = new boolean[n];
            for (int i = 0; i < n; ++i) {
                if (nodeTypes[i] == TYPE_UNASSIGNED) {
                    traverseComponent(i, adjacencyMatrix, visited, nodeTypes);
                    break; // We only need to analyze the structure of one component initially
                }
            }

            // Step 3: Validate the partition consistency
            // This checks if the remaining unassigned nodes satisfy the specific constraints
            // relative to the visited component and other unassigned nodes.
            if (!validatePartition(n, adjacencyMatrix, nodeTypes, visited)) {
                out.println("No");
                return;
            }

            // Step 4: Assign final types
            // Nodes in the visited component become Type A.
            // Nodes remaining as TYPE_UNASSIGNED become Type C (implied by output logic).
            for (int i = 0; i < n; ++i) {
                if (visited[i]) {
                    nodeTypes[i] = TYPE_A;
                }
            }

            // Step 5: Output result
            out.println("Yes");
            StringBuilder result = new StringBuilder();
            for (int type : nodeTypes) {
                if (type == TYPE_A) {
                    result.append('a');
                } else if (type == TYPE_B) {
                    result.append('b');
                } else {
                    result.append('c');
                }
            }
            out.println(result.toString());
        }

        /**
         * Performs a Depth First Search to mark nodes in the same connected component.
         * Only traverses nodes that are currently unassigned.
         */
        private void traverseComponent(int currentVertex, boolean[][] graph, boolean[] visited, int[] types) {
            visited[currentVertex] = true;
            for (int neighbor = 0; neighbor < graph.length; ++neighbor) {
                // Traverse if connected, not visited, and unassigned
                if (graph[currentVertex][neighbor] && !visited[neighbor] && types[neighbor] == TYPE_UNASSIGNED) {
                    traverseComponent(neighbor, graph, visited, types);
                }
            }
        }

        /**
         * Validates if the current assignment of types and visited status is consistent.
         * Implements the complex logic required to determine if a valid partition exists.
         */
        private boolean validatePartition(int n, boolean[][] graph, int[] types, boolean[] visited) {
            for (int i = 0; i < n; ++i) {
                // Skip nodes already assigned to Type B
                if (types[i] != TYPE_UNASSIGNED) continue;

                if (visited[i]) {
                    // Node i is part of the visited component (potential Type A)
                    for (int j = 0; j < n; ++j) {
                        if (types[j] == TYPE_UNASSIGNED) { // j is also a candidate
                            // Constraint 1: If i (in component) connects to j (not in component), it's invalid
                            if (graph[i][j] && !visited[j]) {
                                return false;
                            }
                            // Constraint 2: If i (in component) does NOT connect to j (in component), it's invalid
                            if (!graph[i][j] && visited[j]) {
                                return false;
                            }
                        }
                    }
                } else {
                    // Node i is NOT part of the visited component
                    for (int j = 0; j < n; ++j) {
                        if (types[j] == TYPE_UNASSIGNED) {
                            // Constraint 3: If i (not in component) connects to j (in component), it's invalid
                            if (graph[i][j] && visited[j]) {
                                return false;
                            }
                            // Constraint 4: If i (not in component) does NOT connect to j (not in component), it's invalid
                            if (!graph[i][j] && !visited[j]) {
                                return false;
                            }
                        }
                    }
                }
            }
            return true;
        }
    }

    /**
     * Fast Input Reader for efficient input parsing.
     */
    static class InputReader {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            String s = next();
            if (s == null) throw new RuntimeException("End of input");
            return Integer.parseInt(s);
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayList;
import java.util.LinkedList;
import java.util.List;
import java.util.StringTokenizer;

public class Main {
    // Meaningful constants replace magic numbers
    private static final int LABEL_A = 1;
    private static final int LABEL_B = 2;
    private static final int LABEL_C = 3;
    private static final char[] LABEL_TO_CHAR = {'?', 'a', 'b', 'c'};

    public static void main(String[] args) throws IOException {
        // Try-with-resources ensures the stream is properly closed
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(System.in))) {
            String line = reader.readLine();
            if (line == null) return;

            StringTokenizer st = new StringTokenizer(line);
            int n = Integer.parseInt(st.nextToken());
            int m = Integer.parseInt(st.nextToken());

            Graph graph = new Graph(n);
            boolean[][] isConnected = new boolean[n][n];

            for (int i = 0; i < m; i++) {
                line = reader.readLine();
                if (line == null) break;
                st = new StringTokenizer(line);

                int u = Integer.parseInt(st.nextToken()) - 1;
                int v = Integer.parseInt(st.nextToken()) - 1;

                graph.addEdge(u, v);
                isConnected[u][v] = true;
                isConnected[v][u] = true;
            }

            int[] labels = assignLabels(n, graph, isConnected);
            boolean possible = validateLabels(n, isConnected, labels);

            if (possible) {
                System.out.println("Yes");
                printLabels(labels);
            } else {
                System.out.println("No");
            }
        }
    }

    /**
     * Assigns category labels to each node based on connectivity rules.
     */
    private static int[] assignLabels(int n, Graph graph, boolean[][] isConnected) {
        int[] labels = new int[n];
        for (int i = 0; i < n; i++) {
            if (labels[i] == 0) {
                if (graph.getNeighbors(i).size() == n - 1) {
                    labels[i] = LABEL_B;
                } else {
                    labels[i] = LABEL_A;
                    for (int j = 0; j < n; j++) {
                        if (i != j && !isConnected[i][j]) {
                            labels[j] = LABEL_C;
                        }
                    }
                }
            }
        }
        return labels;
    }

    /**
     * Validates if the assigned labels satisfy the graph constraints.
     * Optimized to check only unique pairs (j > i) due to symmetry.
     */
    private static boolean validateLabels(int n, boolean[][] isConnected, int[] labels) {
        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                boolean connected = isConnected[i][j];
                int diff = Math.abs(labels[i] - labels[j]);

                if (connected && diff > 1) return false;
                if (!connected && diff <= 1) return false;
            }
        }
        return true;
    }

    /**
     * Formats and prints the node labels as characters.
     */
    private static void printLabels(int[] labels) {
        StringBuilder sb = new StringBuilder(labels.length);
        for (int label : labels) {
            sb.append(LABEL_TO_CHAR[label]);
        }
        System.out.println(sb);
    }
}

/**
 * Represents an undirected graph using an adjacency list.
 */
class Graph {
    private final int n;
    private final List<List<Integer>> adj;

    public Graph(int n) {
        this.n = n;
        this.adj = new ArrayList<>(n);
        for (int i = 0; i < n; i++) {
            adj.add(new LinkedList<>());
        }
    }

    public int getSize() {
        return n;
    }

    public void addEdge(int u, int v) {
        adj.get(u).add(v);
        adj.get(v).add(u);
    }

    public List<Integer> getNeighbors(int v) {
        return adj.get(v);
    }
}

import java.io.BufferedWriter;
import java.io.IOException;
import java.io.InputStream;
import java.io.OutputStream;
import java.io.OutputStreamWriter;
import java.io.PrintWriter;
import java.io.Writer;
import java.util.Arrays;
import java.util.InputMismatchException;

/**
 * Main entry point for the graph labeling problem solver.
 * Reads a graph, assigns labels ('a', 'b', 'c') to nodes, validates the assignment,
 * and outputs the result.
 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;

        InputReader in = new InputReader(inputStream);
        OutputWriter out = new OutputWriter(outputStream);

        TaskC solver = new TaskC();
        solver.solve(1, in, out);

        out.close();
    }

    /**
     * Solves the graph labeling problem.
     * Constraints:
     * - Connected nodes must have label differences <= 1
     * - Disconnected nodes must have label differences >= 2
     */
    static class TaskC {
        private static final char LABEL_A = 'a';
        private static final char LABEL_B = 'b';
        private static final char LABEL_C = 'c';

        public void solve(int testNumber, InputReader in, OutputWriter out) {
            int n = in.readInt();
            int m = in.readInt();
            boolean[][] adjacencyMatrix = new boolean[n][n];

            for (int i = 0; i < m; i++) {
                int u = in.readInt() - 1; // 0-based indexing
                int v = in.readInt() - 1;
                adjacencyMatrix[u][v] = adjacencyMatrix[v][u] = true;
            }

            int specialNodeIndex = findSpecialNode(n, adjacencyMatrix);
            char[] labels = assignLabels(n, specialNodeIndex, adjacencyMatrix);

            if (isValid(n, labels, adjacencyMatrix)) {
                out.printLine("Yes");
                out.printLine(new String(labels));
            } else {
                out.printLine("No");
            }
        }

        /**
         * Finds the first node that satisfies the condition:
         * connected to j, j connected to k, but i NOT connected to k.
         * This node is designated as the 'a' label anchor.
         */
        private int findSpecialNode(int n, boolean[][] adj) {
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < n; j++) {
                    if (i == j) continue;
                    for (int k = 0; k < n; k++) {
                        if (k == i || k == j) continue;
                        if (adj[i][j] && adj[j][k] && !adj[i][k]) {
                            return i;
                        }
                    }
                }
            }
            // Fallback to 0 if no such node exists (problem constraints typically guarantee one)
            return 0;
        }

        /**
         * Assigns 'a', 'b', or 'c' labels to each node based on connectivity 
         * to the special 'a' node and other 'c' nodes.
         */
        private char[] assignLabels(int n, int specialNodeIndex, boolean[][] adj) {
            char[] labels = new char[n];
            Arrays.fill(labels, LABEL_B);
            labels[specialNodeIndex] = LABEL_A;

            // Nodes not connected to the special 'a' node get 'c'
            for (int i = 0; i < n; i++) {
                if (i == specialNodeIndex) continue;
                if (!adj[specialNodeIndex][i]) {
                    labels[i] = LABEL_C;
                }
            }

            // Refine 'b' nodes: if a 'b' node has NO edges to any 'c' node, promote it to 'a'
            for (int i = 0; i < n; i++) {
                if (labels[i] == LABEL_B) {
                    boolean connectedToC = false;
                    for (int j = 0; j < n; j++) {
                        if (labels[j] == LABEL_C && adj[i][j]) {
                            connectedToC = true;
                            break;
                        }
                    }
                    if (!connectedToC) {
                        labels[i] = LABEL_A;
                    }
                }
            }
            return labels;
        }

        /**
         * Validates the label assignment against the graph constraints.
         */
        private boolean isValid(int n, char[] labels, boolean[][] adj) {
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < n; j++) {
                    if (i == j) continue;

                    boolean isConnected = adj[i][j];
                    int labelDiff = Math.abs(labels[i] - labels[j]);

                    // Valid if: connected & diff <= 1, OR disconnected & diff >= 2
                    boolean condition = (isConnected && labelDiff <= 1) || (!isConnected && labelDiff >= 2);
                    if (!condition) {
                        return false;
                    }
                }
            }
            return true;
        }
    }

    /**
     * Fast input reader for competitive programming scenarios.
     */
    static class InputReader {
        private final InputStream stream;
        private final byte[] buffer = new byte[1024];
        private int bufferPointer;
        private int bytesRead;
        private SpaceCharFilter filter;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        public int read() {
            if (bytesRead == -1) {
                throw new InputMismatchException("End of stream reached unexpectedly.");
            }
            if (bufferPointer >= bytesRead) {
                bufferPointer = 0;
                try {
                    bytesRead = stream.read(buffer);
                } catch (IOException e) {
                    throw new InputMismatchException("I/O error during input reading.", e);
                }
                if (bytesRead <= 0) {
                    return -1;
                }
            }
            return buffer[bufferPointer++];
        }

        public int readInt() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            int result = 0;
            do {
                if (c < '0' || c > '9') {
                    throw new InputMismatchException("Invalid integer format.");
                }
                result = result * 10 + (c - '0');
                c = read();
            } while (!isSpaceChar(c));

            return result * sign;
        }

        public boolean isSpaceChar(int c) {
            return filter != null ? filter.isSpaceChar(c) : isWhitespace(c);
        }

        private static boolean isWhitespace(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        @FunctionalInterface
        public interface SpaceCharFilter {
            boolean isSpaceChar(int ch);
        }
    }

    /**
     * Fast output writer for competitive programming scenarios.
     */
    static class OutputWriter {
        private final PrintWriter writer;

        public OutputWriter(OutputStream outputStream) {
            this.writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(outputStream)));
        }

        public OutputWriter(Writer writer) {
            this.writer = new PrintWriter(writer);
        }

        public void print(Object... objects) {
            for (int i = 0; i < objects.length; i++) {
                if (i > 0) {
                    writer.print(' ');
                }
                writer.print(objects[i]);
            }
        }

        public void printLine(Object... objects) {
            print(objects);
            writer.println();
        }

        public void flush() {
            writer.flush();
        }

        public void close() {
            writer.close();
        }
    }
}

import java.io.*;
import java.util.InputMismatchException;

/**
 * Codeforces Problem C Solution
 * Refactored for maintainability, readability, and separation of concerns.
 */
public class CodeForcesC {

    // Named constants replace magic characters for clarity
    private static final char COLOR_A = 'a';
    private static final char COLOR_B = 'b';
    private static final char COLOR_C = 'c';

    private static final InputReader IN = new InputReader(System.in);
    private static final OutputWriter OUT = new OutputWriter(System.out);

    public static void main(String[] args) throws Exception {
        try {
            solve();
        } finally {
            OUT.close();
        }
    }

    /**
     * Orchestrates the reading, processing, and output phases.
     */
    private static void solve() throws Exception {
        int n = IN.readInt();
        int m = IN.readInt();

        boolean[][] adjacencyMatrix = new boolean[n + 1][n + 1];
        int[] degree = new int[n + 1];

        for (int i = 0; i < m; i++) {
            int u = IN.readInt();
            int v = IN.readInt();
            adjacencyMatrix[u][v] = true;
            adjacencyMatrix[v][u] = true;
            degree[u]++;
            degree[v]++;
        }

        char[] colorAssignment = new char[n + 1];
        boolean isValid = assignAndValidateColors(n, adjacencyMatrix, degree, colorAssignment);

        if (isValid) {
            OUT.println("Yes");
            for (int i = 1; i <= n; i++) {
                OUT.print(colorAssignment[i]);
            }
            OUT.println();
        } else {
            OUT.println("No");
        }
    }

    /**
     * Applies the greedy coloring strategy and validates the result.
     * 
     * Strategy:
     * 1. Nodes connected to all others (degree == n-1) must be COLOR_B.
     * 2. For remaining nodes, assign alternating non-B colors (A/C) based on adjacency.
     * 3. Propagate colors: if connected to current node -> same color, else -> COLOR_B.
     * 4. If a node is not connected to the current pivot, it must take the opposite color.
     */
    private static boolean assignAndValidateColors(int n, boolean[][] adj, int[] degree, char[] colors) {
        int i = 1;
        char lastAssignedColor = COLOR_C;
        boolean continueAssignment = true;

        while (continueAssignment && i <= n) {
            if (degree[i] != n - 1) {
                // Assign current pivot a color different from the last non-B color
                char currentColor = (lastAssignedColor == COLOR_C) ? COLOR_A : COLOR_C;
                colors[i] = currentColor;
                lastAssignedColor = currentColor;

                // Propagate colors to all subsequent nodes based on adjacency to pivot
                for (int j = i + 1; j <= n; j++) {
                    colors[j] = adj[i][j] ? currentColor : COLOR_B;
                }

                // Check if we need to continue assignment from a non-adjacent node
                continueAssignment = false;
                for (int j = i + 1; j <= n; j++) {
                    if (!adj[i][j]) {
                        continueAssignment = true;
                        i = j;
                        break;
                    }
                }
            } else {
                // Universal nodes must be colored 'b'
                colors[i] = COLOR_B;
                i++;
            }
        }

        return validateGraphConstraints(n, adj, colors);
    }

    /**
     * Validates the coloring against the problem constraints:
     * - 'a' and 'c' must NEVER be connected (complementary colors)
     * - All other pairs (same color, or involving 'b') MUST be connected
     */
    private static boolean validateGraphConstraints(int n, boolean[][] adj, char[] colors) {
        for (int i = 1; i <= n; i++) {
            for (int j = i + 1; j <= n; j++) {
                char c1 = colors[i];
                char c2 = colors[j];
                boolean isConnected = adj[i][j];

                // ASCII difference between 'a' (97) and 'c' (99) is 2
                boolean areComplementary = Math.abs(c1 - c2) == 2;

                if (areComplementary) {
                    if (isConnected) return false;
                } else {
                    if (!isConnected) return false;
                }
            }
        }
        return true;
    }

    /**
     * Fast input reader for competitive programming.
     */
    private static class InputReader {
        private final InputStream stream;
        private final byte[] buffer;
        private int currentIndex;
        private int bytesRead;

        public InputReader(InputStream stream) {
            this(stream, 131072);
        }

        public InputReader(InputStream stream, int bufferSize) {
            this.stream = stream;
            this.buffer = new byte[bufferSize];
        }

        private int read() throws IOException {
            if (currentIndex >= bytesRead) {
                currentIndex = 0;
                bytesRead = stream.read(buffer);
                if (bytesRead <= 0) {
                    return -1;
                }
            }
            return buffer[currentIndex++];
        }

        public String readString() throws IOException {
            int c = read();
            while (!isPrintable(c)) {
                c = read();
            }
            StringBuilder result = new StringBuilder();
            do {
                result.appendCodePoint(c);
                c = read();
            } while (isPrintable(c));
            return result.toString();
        }

        public int readInt() throws Exception {
            int c = read();
            int sign = 1;
            while (!isPrintable(c)) {
                c = read();
            }
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int result = 0;
            do {
                if ((c < '0') || (c > '9')) {
                    throw new InputMismatchException();
                }
                result *= 10;
                result += (c - '0');
                c = read();
            } while (isPrintable(c));
            return sign * result;
        }

        public long readLong() throws Exception {
            int c = read();
            int sign = 1;
            while (!isPrintable(c)) {
                c = read();
            }
            if (c == '-') {
                sign = -1;
                c = read();
            }
            long result = 0;
            do {
                if ((c < '0') || (c > '9')) {
                    throw new InputMismatchException();
                }
                result *= 10;
                result += (c - '0');
                c = read();
            } while (isPrintable(c));
            return sign * result;
        }

        public double readDouble() throws Exception {
            int c = read();
            int sign = 1;
            while (!isPrintable(c)) {
                c = read();
            }
            if (c == '-') {
                sign = -1;
                c = read();
            }
            boolean fraction = false;
            double multiplier = 1;
            double result = 0;
            do {
                if ((c == 'e') || (c == 'E')) {
                    return sign * result * Math.pow(10, readInt());
                }
                if ((c < '0') || (c > '9')) {
                    if ((c == '.') && (!fraction)) {
                        fraction = true;
                        c = read();
                        continue;
                    }
                    throw new InputMismatchException();
                }
                if (fraction) {
                    multiplier /= 10;
                    result += (c - '0') * multiplier;
                    c = read();
                } else {
                    result *= 10;
                    result += (c - '0');
                    c = read();
                }
            } while (isPrintable(c));
            return sign * result;
        }

        private boolean isPrintable(int c) {
            return ((c > 32) && (c < 127));
        }
    }

    /**
     * Fast output writer for competitive programming.
     */
    private static class OutputWriter {
        private final PrintWriter writer;

        public OutputWriter(OutputStream outputStream) {
            writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(outputStream)));
        }

        public OutputWriter(Writer writer) {
            this.writer = new PrintWriter(writer);
        }

        public void print(Object... objects) {
            for (int i = 0; i < objects.length; i++) {
                if (i != 0) {
                    writer.print(' ');
                }
                writer.print(objects[i]);
            }
        }

        public void println(Object... objects) {
            print(objects);
            writer.println();
        }

        public void close() {
            writer.close();
        }

        public void flush() {
            writer.flush();
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.OutputStream;
import java.io.PrintWriter;
import java.util.StringTokenizer;

public class Problem_624_C {

    private static final char ROLE_A = 'a';
    private static final char ROLE_B = 'b';
    private static final char ROLE_C = 'c';

    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        FastReader in = new FastReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);

        Problem_624_C solver = new Problem_624_C();
        solver.solve(in, out);

        out.close();
    }

    public void solve(FastReader in, PrintWriter out) {
        int n = in.nextInt();
        int m = in.nextInt();

        boolean[][] adjacencyMatrix = buildAdjacencyMatrix(n, m, in);
        char[] assignment = assignRoles(n, adjacencyMatrix);
        boolean isValid = validateAssignment(n, adjacencyMatrix, assignment);

        if (isValid) {
            out.println("Yes");
            out.println(assignment);
        } else {
            out.println("No");
        }
    }

    private boolean[][] buildAdjacencyMatrix(int n, int m, FastReader in) {
        boolean[][] adj = new boolean[n][n];
        for (int i = 0; i < m; i++) {
            int u = in.nextInt() - 1;
            int v = in.nextInt() - 1;
            adj[u][v] = true;
            adj[v][u] = true;
        }
        return adj;
    }

    private char[] assignRoles(int n, boolean[][] adj) {
        char[] roles = new char[n]; // 0 represents unassigned

        // Step 1: Identify 'b' nodes (connected to every other node)
        for (int i = 0; i < n; i++) {
            int degree = 0;
            for (int j = 0; j < n; j++) {
                if (i != j && adj[i][j]) {
                    degree++;
                }
            }
            if (degree == n - 1) {
                roles[i] = ROLE_B;
            }
        }

        // Step 2: Select an anchor 'a' node from the remaining unassigned nodes
        int anchorA = -1;
        for (int i = 0; i < n; i++) {
            if (roles[i] == 0) {
                roles[i] = ROLE_A;
                anchorA = i;
                break;
            }
        }

        // Step 3: Assign remaining nodes based on their connection to the anchor 'a'
        if (anchorA != -1) {
            for (int i = 0; i < n; i++) {
                if (roles[i] == 0 && i != anchorA) {
                    roles[i] = adj[anchorA][i] ? ROLE_A : ROLE_C;
                }
            }
        }

        return roles;
    }

    private boolean validateAssignment(int n, boolean[][] adj, char[] roles) {
        // Ensure all nodes have been assigned a role
        for (char role : roles) {
            if (role == 0) return false;
        }

        // Validate constraints between 'a' and 'c' nodes
        for (int i = 0; i < n; i++) {
            char roleI = roles[i];
            if (roleI == ROLE_B) continue; // 'b' nodes are fully connected, skip validation

            for (int j = 0; j < n; j++) {
                if (i == j) continue;
                char roleJ = roles[j];
                if (roleJ == ROLE_B) continue;

                boolean connected = adj[i][j];
                if (roleI == ROLE_A) {
                    if (roleJ == ROLE_A && connected) return false; // 'a' cannot connect to 'a'
                    if (roleJ == ROLE_C && !connected) return false; // 'a' must connect to 'c'
                } else if (roleI == ROLE_C) {
                    if (roleJ == ROLE_C && connected) return false; // 'c' cannot connect to 'c'
                    if (roleJ == ROLE_A && !connected) return false; // 'c' must connect to 'a'
                }
            }
        }
        return true;
    }

    /**
     * Fast I/O helper class for competitive programming.
     * Replaces the original MyScanner with a cleaner, focused implementation.
     */
    public static class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastReader(InputStream inputStream) {
            this.br = new BufferedReader(new InputStreamReader(inputStream));
        }

        public String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) {
                        throw new IOException("Unexpected end of input");
                    }
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.util.Scanner;

public class GraphColoring {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        // Read number of nodes (n) and edges (m)
        if (!scanner.hasNextInt()) return;
        int n = scanner.nextInt();
        int m = scanner.nextInt();

        // Adjacency matrix to represent the graph
        boolean[][] adjacencyMatrix = new boolean[n][n];
        // Array to store the degree of each node
        int[] degreeCount = new int[n];

        // Read edges
        for (int i = 0; i < m; i++) {
            // Input is 1-indexed, convert to 0-indexed
            int u = scanner.nextInt() - 1;
            int v = scanner.nextInt() - 1;

            // Ensure indices are within bounds
            if (u >= 0 && u < n && v >= 0 && v < n) {
                adjacencyMatrix[u][v] = adjacencyMatrix[v][u] = true;
                degreeCount[u]++;
                degreeCount[v]++;
            }
        }
        scanner.close();

        // Array to store the assigned colors ('a', 'b', 'c')
        // Default char value is 0 (null character), representing uncolored
        char[] coloring = new char[n];

        // Step 1: Identify universal nodes (degree n-1) and assign color 'b'
        for (int i = 0; i < n; i++) {
            if (degreeCount[i] == n - 1) {
                coloring[i] = 'b';
            }
        }

        boolean possible = true;

        // Step 2: Find the first uncolored node (not 'b') and assign color 'a'
        int firstNotB = findFirstIndex(coloring, 'b');
        if (firstNotB != -1) {
            coloring[firstNotB] = 'a';

            // Assign color 'a' to all neighbors of this node (that are not 'b')
            for (int i = 0; i < n; i++) {
                if (adjacencyMatrix[firstNotB][i] && coloring[i] != 'b') {
                    coloring[i] = 'a';
                }
            }

            // Step 3: Find the first node not colored 'a' or 'b' and assign color 'c'
            int firstNotAB = findFirstIndex(coloring, 'a', 'b');
            if (firstNotAB != -1) {
                coloring[firstNotAB] = 'c';

                // Assign color 'c' to all neighbors of this node (that are not 'a' or 'b')
                for (int i = 0; i < n; i++) {
                    if (adjacencyMatrix[firstNotAB][i] && coloring[i] != 'a' && coloring[i] != 'b') {
                        coloring[i] = 'c';
                    }
                }

                // Step 4: Check if any node remains uncolored
                int firstNotABC = findFirstIndex(coloring, 'a', 'b', 'c');
                if (firstNotABC != -1) {
                    possible = false;
                } else {
                    // Step 5: Validate the coloring
                    if (!isValidColoring(coloring, adjacencyMatrix)) {
                        possible = false;
                    }
                }
            }
            // If firstNotAB == -1, it means all nodes are colored 'a' or 'b'.
            // Based on original logic, validation is skipped in this specific path,
            // so we assume it's valid (or rather, we don't mark it as impossible).
        }
        // If firstNotB == -1, all nodes are 'b'. Validation skipped in original logic.

        // Output result
        if (possible) {
            System.out.println("Yes\n" + new String(coloring));
        } else {
            System.out.println("No");
        }
    }

    /**
     * Finds the first index in the array that does not match any of the forbidden characters.
     *
     * @param array     The char array to search.
     * @param forbidden Characters to exclude.
     * @return The index of the first valid character, or -1 if none found.
     */
    private static int findFirstIndex(char[] array, char... forbidden) {
        for (int i = 0; i < array.length; i++) {
            boolean isForbidden = false;
            for (char f : forbidden) {
                if (array[i] == f) {
                    isForbidden = true;
                    break;
                }
            }
            if (!isForbidden) {
                return i;
            }
        }
        return -1;
    }

    /**
     * Validates the graph coloring based on the problem constraints.
     * 
     * Constraints derived from original code logic:
     * 1. If the color difference between two nodes is <= 1 (same or adjacent colors like 'a'-'b'),
     *    there MUST be an edge between them.
     * 2. If the color difference is == 2 (opposite colors 'a' and 'c'),
     *    there MUST NOT be an edge between them.
     *
     * @param coloring          The array of colors assigned to nodes.
     * @param adjacencyMatrix   The graph structure.
     * @return true if the coloring is valid, false otherwise.
     */
    private static boolean isValidColoring(char[] coloring, boolean[][] adjacencyMatrix) {
        int n = coloring.length;
        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                char c1 = coloring[i];
                char c2 = coloring[j];
                boolean connected = adjacencyMatrix[i][j];

                int diff = Math.abs(c1 - c2);

                // Check Constraint 1: Close colors must be connected
                if (diff <= 1) {
                    if (!connected) {
                        return false;
                    }
                }
                // Check Constraint 2: Far colors must not be connected
                else if (diff == 2) {
                    if (connected) {
                        return false;
                    }
                }
            }
        }
        return true;
    }
}

