/**
 * Handles graph construction, validation, and assignment logic.
 * Replaces custom I/O and utility classes with standard Java libraries
 * for better maintainability and readability.
 */
class Solver {
    private final BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
    private final PrintWriter out = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)));
    private StringTokenizer st;

    /** Reads the next token from standard input. */
    private String nextToken() throws IOException {
        while (st == null || !st.hasMoreTokens()) {
            String line = br.readLine();
            if (line == null) return null;
            st = new StringTokenizer(line);
        }
        return st.nextToken();
    }

    /** Parses the next token as an integer. */
    private int nextInt() throws IOException {
        String token = nextToken();
        if (token == null) throw new EOFException("Unexpected end of input");
        return Integer.parseInt(token);
    }

    /** Main entry point for the algorithm. */
    void solve() {
        try {
            int n = nextInt();
            int m = nextInt();

            // If the graph is already complete, output all 'a's
            if (m == n * (n - 1) / 2) {
                out.println("Yes");
                char[] allA = new char[n];
                Arrays.fill(allA, 'a');
                out.println(new String(allA));
                out.flush();
                return;
            }

            // Build the graph
            GraphNode[] nodes = new GraphNode[n];
            for (int i = 0; i < n; i++) {
                nodes[i] = new GraphNode(i);
            }

            for (int i = 0; i < m; i++) {
                int u = nextInt() - 1;
                int v = nextInt() - 1;
                nodes[u].addNeighbor(nodes[v]);
            }

            char[] assignment = new char[n];

            // Step 1: Identify nodes connected to all other nodes (degree == n-1)
            // Mark them as 'b' and remove them from the graph
            for (int i = 0; i < n; i++) {
                if (nodes[i].degree() == n - 1) {
                    assignment[i] = 'b';
                    for (GraphNode neighbor : nodes[i].neighbors) {
                        nodes[i].removeNeighbor(neighbor);
                    }
                }
            }

            // Step 2: Find the first unassigned connected component
            // Check if it forms a clique. If so, assign 'a'
            for (int i = 0; i < n; i++) {
                if (assignment[i] != 0) continue;
                if (!isClique(nodes[i], nodes)) {
                    out.println("No");
                    out.flush();
                    return;
                }
                assignComponent(nodes[i], 'a', assignment);
                break;
            }

            // Step 3: Find the next unassigned connected component
            // Check if it forms a clique. If so, assign 'c'
            for (int i = 0; i < n; i++) {
                if (assignment[i] != 0) continue;
                if (!isClique(nodes[i], nodes)) {
                    out.println("No");
                    out.flush();
                    return;
                }
                assignComponent(nodes[i], 'c', assignment);
                break;
            }

            // Step 4: Verify all nodes are assigned
            for (int i = 0; i < n; i++) {
                if (assignment[i] == 0) {
                    out.println("No");
                    out.flush();
                    return;
                }
            }

            out.println("Yes");
            out.println(new String(assignment));
        } catch (Exception e) {
            System.err.println("Error during execution: " + e.getMessage());
        } finally {
            out.flush();
        }
    }

    /**
     * Determines if the connected component containing 'start' is a complete graph (clique).
     * Uses BFS to find all nodes in the component, then verifies each node's degree
     * matches the component size minus one.
     */
    private boolean isClique(GraphNode start, GraphNode[] nodes) {
        Set<Integer> component = new HashSet<>();
        Queue<GraphNode> queue = new ArrayDeque<>();
        queue.add(start);
        component.add(start.id);

        while (!queue.isEmpty()) {
            GraphNode current = queue.poll();
            for (GraphNode neighbor : current.neighbors) {
                if (component.add(neighbor.id)) {
                    queue.add(neighbor);
                }
            }
        }

        int size = component.size();
        for (int id : component) {
            // In a clique, every node must be connected to all other nodes in the component
            if (nodes[id].degree() != size - 1) {
                return false;
            }
        }
        return true;
    }

    /**
     * Assigns a label to all nodes in the connected component containing 'start'.
     */
    private void assignComponent(GraphNode start, char label, char[] assignment) {
        Queue<GraphNode> queue = new ArrayDeque<>();
        queue.add(start);
        assignment[start.id] = label;

        while (!queue.isEmpty()) {
            GraphNode current = queue.poll();
            for (GraphNode neighbor : current.neighbors) {
                if (assignment[neighbor.id] == 0) {
                    assignment[neighbor.id] = label;
                    queue.add(neighbor);
                }
            }
        }
    }

    /**
     * Represents a node in the graph with bidirectional neighbor tracking.
     */
    static class GraphNode {
        final int id;
        final Set<GraphNode> neighbors = new HashSet<>();

        GraphNode(int id) {
            this.id = id;
        }

        void addNeighbor(GraphNode other) {
            neighbors.add(other);
            other.neighbors.add(this);
        }

        void removeNeighbor(GraphNode other) {
            neighbors.remove(other);
            other.neighbors.remove(this);
        }

        int degree() {
            return neighbors.size();
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Validates if a graph can be partitioned into:
 * 1. A set of universal nodes (degree n-1), labeled 'b'
 * 2. Up to two clique components, labeled 'a' and 'c'
 * All nodes must be visited and assigned a valid label.
 */
public class GraphComponentValidator {

    public static void main(String[] args) throws Exception {
        InputReader reader = new InputReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        int n = reader.nextInt();
        int m = reader.nextInt();

        boolean[][] adjMatrix = new boolean[n][n];
        int[] degree = new int[n];

        for (int i = 0; i < m; i++) {
            int u = reader.nextInt() - 1;
            int v = reader.nextInt() - 1;
            adjMatrix[u][v] = true;
            adjMatrix[v][u] = true;
            degree[u]++;
            degree[v]++;
        }

        char[] labels = new char[n];
        boolean[] visited = new boolean[n];
        int componentCount = 0;
        boolean possible = true;

        // Step 1: Identify and mark universal nodes ('b')
        for (int i = 0; i < n; i++) {
            if (degree[i] == n - 1) {
                labels[i] = 'b';
                visited[i] = true;
            }
        }

        // Step 2: Find and validate remaining components ('a' and 'c')
        for (int i = 0; i < n && possible; i++) {
            if (!visited[i]) {
                componentCount++;
                if (componentCount > 2) {
                    possible = false;
                    break;
                }

                char type = (componentCount == 1) ? 'a' : 'c';
                List<Integer> componentNodes = new ArrayList<>();

                // BFS to find the connected component
                Queue<Integer> queue = new ArrayDeque<>();
                queue.offer(i);
                visited[i] = true;
                labels[i] = type;
                componentNodes.add(i);

                while (!queue.isEmpty()) {
                    int current = queue.poll();
                    for (int neighbor = 0; neighbor < n; neighbor++) {
                        if (adjMatrix[current][neighbor] && !visited[neighbor]) {
                            visited[neighbor] = true;
                            labels[neighbor] = type;
                            componentNodes.add(neighbor);
                            queue.offer(neighbor);
                        }
                    }
                }

                // Validate that the component forms a clique
                if (!isClique(componentNodes, adjMatrix)) {
                    possible = false;
                }
            }
        }

        // Step 3: Ensure all nodes were visited
        for (int i = 0; i < n; i++) {
            if (!visited[i]) {
                possible = false;
                break;
            }
        }

        // Output result
        if (possible) {
            out.println("Yes");
            out.println(new String(labels));
        } else {
            out.println("No");
        }

        out.flush();
    }

    /**
     * Checks if all nodes in the given list form a complete subgraph (clique).
     * Time Complexity: O(k^2) where k is the number of nodes in the component.
     */
    private static boolean isClique(List<Integer> nodes, boolean[][] adjMatrix) {
        for (int i = 0; i < nodes.size(); i++) {
            for (int j = i + 1; j < nodes.size(); j++) {
                if (!adjMatrix[nodes.get(i)][nodes.get(j)]) {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Fast I/O helper class commonly used in competitive programming.
     */
    static class InputReader {
        private final InputStream stream;
        private final byte[] buf = new byte[8192];
        private int curChar;
        private int snumChars;
        private SpaceCharFilter filter;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        public int snext() {
            if (snumChars == -1) {
                throw new InputMismatchException();
            }
            if (curChar >= snumChars) {
                curChar = 0;
                try {
                    snumChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (snumChars <= 0) {
                    return -1;
                }
            }
            return buf[curChar++];
        }

        public int nextInt() {
            int c = snext();
            while (isSpaceChar(c)) {
                c = snext();
            }
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = snext();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                res *= 10;
                res += c - '0';
                c = snext();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public long nextLong() {
            int c = snext();
            while (isSpaceChar(c)) {
                c = snext();
            }
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = snext();
            }
            long res = 0;
            do {
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                res *= 10;
                res += c - '0';
                c = snext();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public String readString() {
            int c = snext();
            while (isSpaceChar(c)) {
                c = snext();
            }
            StringBuilder res = new StringBuilder();
            do {
                res.appendCodePoint(c);
                c = snext();
            } while (!isSpaceChar(c));
            return res.toString();
        }

        public boolean isSpaceChar(int c) {
            return filter != null ? filter.isSpaceChar(c) : (c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1);
        }

        public interface SpaceCharFilter {
            boolean isSpaceChar(int ch);
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Solves a graph coloring problem by reading a graph, attempting to assign colors,
 * and outputting the result. Refactored for maintainability, type safety, and clarity.
 */
public class Main {

    // Named constants replace magic numbers for better readability and easier maintenance
    private static final int UNVISITED = -1;
    private static final int SPECIAL_NODE = 1;
    private static final int COLOR_A = 0;
    private static final int COLOR_C = 2;
    private static final int UNASSIGNED_COLOR = -2;
    private static final int MATRIX_UNCONNECTED = -5;

    public static void main(String[] args) {
        // Try-with-resources ensures PrintWriter is properly closed and flushed
        try (PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out))) {
            new Main().solve(out);
        } catch (IOException e) {
            e.printStackTrace();
            System.exit(1); // Standard exit code for runtime errors
        }
    }

    /**
     * Orchestrates input reading, graph construction, coloring logic, and output.
     *
     * @param out PrintWriter for formatted output
     * @throws IOException if an I/O error occurs
     */
    public void solve(PrintWriter out) throws IOException {
        FastScanner scanner = new FastScanner();
        int n = scanner.nextInt();
        int m = scanner.nextInt();

        @SuppressWarnings("unchecked")
        ArrayList<Integer>[] adjacencyList = new ArrayList[n];
        int[][] adjacencyMatrix = new int[n][n];

        // Initialize graph structures
        for (int i = 0; i < n; i++) {
            adjacencyList[i] = new ArrayList<>();
            Arrays.fill(adjacencyMatrix[i], MATRIX_UNCONNECTED);
        }

        // Read edges and populate both adjacency list and matrix
        for (int i = 0; i < m; i++) {
            int u = scanner.nextInt() - 1; // Convert to 0-based indexing
            int v = scanner.nextInt() - 1;
            adjacencyList[u].add(v);
            adjacencyList[v].add(u);
            adjacencyMatrix[u][v] = 1;
            adjacencyMatrix[v][u] = 1;
        }

        int[] nodeColors = new int[n];
        Arrays.fill(nodeColors, UNVISITED);

        // Mark nodes connected to all other nodes as special
        for (int i = 0; i < n; i++) {
            if (adjacencyList[i].size() == n - 1) {
                nodeColors[i] = SPECIAL_NODE;
            }
        }

        String result = "Yes";

        // Core coloring algorithm
        for (int i = 0; i < n; i++) {
            if (nodeColors[i] == UNVISITED) {
                int currentColor = UNASSIGNED_COLOR;

                // Check adjacent nodes for color conflicts
                for (int neighbor : adjacencyList[i]) {
                    int neighborColor = nodeColors[neighbor];
                    if (neighborColor == UNVISITED || neighborColor == SPECIAL_NODE) {
                        continue;
                    }
                    if ((neighborColor == COLOR_A && currentColor == COLOR_C) ||
                        (neighborColor == COLOR_C && currentColor == COLOR_A)) {
                        result = "No";
                        break;
                    }
                    currentColor = neighborColor;
                }

                // Check non-adjacent nodes for color constraints
                for (int j = 0; j < n; j++) {
                    if (adjacencyMatrix[i][j] == MATRIX_UNCONNECTED && i != j) {
                        int otherColor = nodeColors[j];
                        if (otherColor != UNVISITED && otherColor != SPECIAL_NODE) {
                            if ((otherColor == COLOR_A && currentColor == COLOR_A) ||
                                (otherColor == COLOR_C && currentColor == COLOR_C)) {
                                result = "No";
                                break;
                            }
                            currentColor = (2 + otherColor) % 4;
                        }
                    }
                }

                // Assign final color to the current node
                nodeColors[i] = (currentColor == UNASSIGNED_COLOR) ? COLOR_A : currentColor;
            }
        }

        // Assign default color to any remaining unvisited nodes
        for (int i = 0; i < n; i++) {
            if (nodeColors[i] == UNVISITED) {
                nodeColors[i] = COLOR_A;
            }
        }

        // Output results
        out.println(result);
        if ("Yes".equals(result)) { // Fixed: Use .equals() instead of == for String comparison
            for (int color : nodeColors) {
                out.print((char) ('a' + color));
            }
        }
        out.flush();
    }

    /**
     * Optimized scanner for fast input reading.
     */
    static class FastScanner {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastScanner() {
            reader = new BufferedReader(new InputStreamReader(System.in));
            tokenizer = null;
        }

        public String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                String line = reader.readLine();
                if (line == null) {
                    throw new EOFException("End of input stream reached unexpectedly.");
                }
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        public long nextLong() throws IOException {
            return Long.parseLong(next());
        }

        public double nextDouble() throws IOException {
            return Double.parseDouble(next());
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.OutputStream;
import java.io.PrintWriter;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import java.util.StringTokenizer;

public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        QuickScanner in = new QuickScanner(inputStream);
        PrintWriter out = new PrintWriter(outputStream);

        GraphSolver solver = new GraphSolver();
        solver.solve(in, out);

        out.close();
    }

    /**
     * Solver class encapsulating the logic for the graph problem.
     * Renamed from TaskC for better maintainability and clarity.
     */
    static class GraphSolver {
        public void solve(QuickScanner in, PrintWriter out) {
            int n = in.nextInt();
            int m = in.nextInt();

            // Use boolean matrix for graph representation
            boolean[][] adjacencyMatrix = new boolean[n][n];
            for (int i = 0; i < m; i++) {
                int u = in.nextInt() - 1;
                int v = in.nextInt() - 1;
                adjacencyMatrix[u][v] = adjacencyMatrix[v][u] = true;
            }

            // 1. Check if there is an independent set of size 3.
            // If such a set exists, the answer is "No".
            if (hasIndependentSetOfThree(adjacencyMatrix, n)) {
                out.println("No");
                return;
            }

            char[] colors = new char[n];

            // nonNeighbors[i] stores the set of nodes NOT connected to node i.
            // Using List<Set> avoids generic array creation warnings.
            List<Set<Integer>> nonNeighbors = new ArrayList<>(n);
            for (int i = 0; i < n; i++) {
                nonNeighbors.add(new HashSet<>());
            }

            // Populate nonNeighbors structure
            for (int i = 0; i < n; i++) {
                for (int j = i + 1; j < n; j++) {
                    if (!adjacencyMatrix[i][j]) {
                        nonNeighbors.get(i).add(j);
                        nonNeighbors.get(j).add(i);
                    }
                }
            }

            // 2. Apply constraints to determine 'b' (blue) nodes.
            // This logic identifies specific structural constraints in the graph.
            if (!applyConstraints(n, adjacencyMatrix, nonNeighbors, colors)) {
                out.println("No");
                return;
            }

            // 3. Finalize coloring for remaining nodes.
            finalizeColors(n, nonNeighbors, colors);

            // 4. Output result
            out.println("Yes");
            out.println(new String(colors));
        }

        /**
         * Checks if the graph contains an independent set of size 3.
         * An independent set of size 3 means 3 nodes with no edges between them.
         */
        private boolean hasIndependentSetOfThree(boolean[][] adj, int n) {
            for (int i = 0; i < n; i++) {
                for (int j = i + 1; j < n; j++) {
                    // If edge (i, j) exists, they cannot be part of an independent set together
                    if (adj[i][j]) continue; 

                    for (int k = j + 1; k < n; k++) {
                        // Check if edges (i, k) or (j, k) exist
                        if (adj[i][k] || adj[j][k]) continue;

                        // If no edges exist between i, j, and k, we found an independent set
                        return true;
                    }
                }
            }
            return false;
        }

        /**
         * Applies constraints to assign 'b' (blue) colors.
         * Logic: For any path i-j-k where i and k are not connected, j must be 'b'.
         * Conflict: If i or k is already 'b', the configuration is invalid.
         */
        private boolean applyConstraints(int n, boolean[][] adj, List<Set<Integer>> nonNeighbors, char[] colors) {
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < n; j++) {
                    // Ensure i and j are connected
                    if (i == j || !adj[i][j]) continue;

                    for (int k = 0; k < n; k++) {
                        if (i == k) continue;

                        // Check path i-j-k where i and k are NOT connected
                        if (adj[j][k] && !adj[i][k]) {
                            if (colors[i] == 'b' || colors[k] == 'b') {
                                return false; // Conflict detected
                            }
                            colors[j] = 'b';

                            // Note: The original code updated nonNeighbors here, but since 
                            // nonNeighbors was fully initialized with all non-neighbors, 
                            // this update was redundant and has been removed for efficiency.
                        }
                    }
                }
            }
            return true;
        }

        /**
         * Assigns remaining colors ('a' and 'c') based on the graph structure.
         * 'a' is assigned to uncolored nodes, and 'c' to their non-neighbors.
         */
        private void finalizeColors(int n, List<Set<Integer>> nonNeighbors, char[] colors) {
            for (int i = 0; i < n; i++) {
                if (colors[i] == '\0') {
                    colors[i] = 'a'; // Assign 'a' (red)

                    // Assign 'c' (green) to all non-neighbors if they are uncolored
                    for (int other : nonNeighbors.get(i)) {
                        if (colors[other] == '\0') {
                            colors[other] = 'c';
                        }
                    }
                }
            }
        }
    }

    /**
     * Fast Scanner for efficient input reading.
     */
    static class QuickScanner {
        private BufferedReader br;
        private StringTokenizer st;

        public QuickScanner(InputStream stream) {
            br = new BufferedReader(new InputStreamReader(stream), 32768);
        }

        String nextToken() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) {
                        return null;
                    }
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            String s = nextToken();
            if (s == null) throw new RuntimeException("Unexpected end of input");
            return Integer.parseInt(s);
        }
    }
}

