/**
 * Main class for the Graph Partition Solver.
 * This program determines if a graph can be partitioned into three sets (A, B, C)
 * satisfying specific connectivity constraints.
 */
public class Main {

    public static void main(String[] args) {
        // Initialize Fast I/O
        FastReader in = new FastReader();
        PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out));

        // Instantiate solver
        Solver solver = new Solver();

        // Execute solver. The original code had a loop for test cases 't', 
        // but 't' was hardcoded to 1. We maintain that structure.
        int t = 1;
        for (int i = 0; i < t; i++) {
            solver.solve(in, out);
        }

        // Ensure all output is flushed and closed
        out.flush();
        out.close();
    }

    /**
     * Inner class containing the logic for the problem.
     */
    static class Solver {
        // Partition constants
        private static final int TYPE_UNASSIGNED = 0;
        private static final int TYPE_A = 1; // Clique component
        private static final int TYPE_B = 2; // Universal component (connects to all)
        private static final int TYPE_C = 3; // Independent Set component

        public void solve(FastReader in, PrintWriter out) {
            int n = in.nextInt();
            int m = in.nextInt();

            // Use List<List<Integer>> for better type safety and generic support
            List<List<Integer>> graph = new ArrayList<>(n + 1);
            for (int i = 0; i <= n; i++) {
                graph.add(new ArrayList<>());
            }

            // Read edges and build the graph
            for (int i = 0; i < m; i++) {
                int u = in.nextInt();
                int v = in.nextInt();
                graph.get(u).add(v);
                graph.get(v).add(u);
            }

            // Array to store the partition type of each node (1-indexed)
            int[] partition = new int[n + 1];

            // Counters for each partition type
            int countA = 0;
            int countB = 0;
            int countC = 0;

            // ---------------------------------------------------------
            // Step 1: Identify Type B (Universal Vertices)
            // Vertices with degree n-1 connect to everyone.
            // ---------------------------------------------------------
            for (int i = 1; i <= n; i++) {
                if (graph.get(i).size() == n - 1) {
                    partition[i] = TYPE_B;
                    countB++;
                }
            }

            // ---------------------------------------------------------
            // Step 2: Identify Type A (Clique)
            // Find the first unassigned node. It must belong to A.
            // Propagate A to its neighbors.
            // ---------------------------------------------------------
            int pivotNode = -1;
            for (int i = 1; i <= n; i++) {
                if (partition[i] == TYPE_UNASSIGNED) {
                    pivotNode = i;
                    break;
                }
            }

            if (pivotNode != -1) {
                partition[pivotNode] = TYPE_A;
                countA++;

                // Propagate Type A to neighbors
                for (int neighbor : graph.get(pivotNode)) {
                    if (partition[neighbor] == TYPE_UNASSIGNED) {
                        partition[neighbor] = TYPE_A;
                        countA++;
                    }
                    // If a neighbor is already Type B, it's fine (A connects to B).
                    // If a neighbor is Type C, it will be handled in Step 3 or cause conflict.
                }
            }

            // ---------------------------------------------------------
            // Step 3: Identify Type C (Independent Set)
            // Find the first remaining unassigned node. It must belong to C.
            // Propagate C to its neighbors.
            // ---------------------------------------------------------
            pivotNode = -1;
            for (int i = 1; i <= n; i++) {
                if (partition[i] == TYPE_UNASSIGNED) {
                    pivotNode = i;
                    break;
                }
            }

            boolean possible = true;
            if (pivotNode != -1) {
                partition[pivotNode] = TYPE_C;
                countC++;

                // Propagate Type C to neighbors
                for (int neighbor : graph.get(pivotNode)) {
                    if (partition[neighbor] == TYPE_UNASSIGNED) {
                        partition[neighbor] = TYPE_C;
                        countC++;
                    } else if (partition[neighbor] == TYPE_A) {
                        // Conflict: Type C node connected to Type A node is invalid
                        possible = false;
                        break;
                    }
                    // Neighbors can be Type B (C connects to B) or Type C.
                }
            }

            // ---------------------------------------------------------
            // Step 4: Validation
            // ---------------------------------------------------------

            // Check if all nodes were assigned a partition
            if (possible && (countA + countB + countC < n)) {
                possible = false;
            }

            // Validate degree constraints for Type A and Type C
            // Type A (Clique): Connects to all other A's and all B's.
            // Expected Degree = (countA - 1) + countB
            // Type C (Ind. Set): Connects to all B's and all other C's.
            // Expected Degree = countB + (countC - 1)
            // Type B (Universal): Connects to everyone. Degree = n - 1 (Already checked).

            if (possible) {
                for (int i = 1; i <= n; i++) {
                    int currentType = partition[i];
                    int degree = graph.get(i).size();

                    if (currentType == TYPE_A) {
                        int expectedDegree = countA + countB - 1;
                        if (degree != expectedDegree) {
                            possible = false;
                            break;
                        }
                    } else if (currentType == TYPE_C) {
                        int expectedDegree = countB + countC - 1;
                        if (degree != expectedDegree) {
                            possible = false;
                            break;
                        }
                    }
                }
            }

            // ---------------------------------------------------------
            // Step 5: Output
            // ---------------------------------------------------------
            if (possible) {
                out.println("Yes");
                StringBuilder result = new StringBuilder();
                for (int i = 1; i <= n; i++) {
                    if (partition[i] == TYPE_A) {
                        result.append('a');
                    } else if (partition[i] == TYPE_B) {
                        result.append('b');
                    } else {
                        result.append('c');
                    }
                }
                out.println(result.toString());
            } else {
                out.println("No");
            }
        }
    }

    /**
     * Fast I/O helper class for competitive programming.
     */
    static class FastReader {
        BufferedReader br;
        StringTokenizer st;

        public FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null; // Handle EOF gracefully
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    e.printStackTrace();
                    return null;
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            String s = next();
            return s == null ? 0 : Integer.parseInt(s);
        }

        long nextLong() {
            String s = next();
            return s == null ? 0L : Long.parseLong(s);
        }

        double nextDouble() {
            String s = next();
            return s == null ? 0.0 : Double.parseDouble(s);
        }

        boolean nextBoolean() {
            String s = next();
            return s == null ? false : Boolean.parseBoolean(s);
        }

        String nextLine() {
            String str = "";
            try {
                str = br.readLine();
            } catch (IOException e) {
                e.printStackTrace();
            }
            return str;
        }
    }
}

import java.io.FileInputStream;
import java.io.FileNotFoundException;
import java.util.Arrays;
import java.util.Scanner;

public class GraphStringSolver {
    private static final String DEBUG_INPUT_PATH = "src/x0001_aim_tech_round_div_1/A_input1.txt";

    private final boolean isDebug;
    private int numNodes;
    private int numEdges;
    private boolean[][] adjacencyMatrix;
    private NodeState[] nodeStates;

    /**
     * Represents the assignment state of each node in the graph.
     * Replaces magic integers (0, 1, 2, 3) for better readability and type safety.
     */
    private enum NodeState {
        UNMARKED, A, B, C
    }

    public GraphStringSolver(boolean isDebug) {
        this.isDebug = isDebug;
    }

    /**
     * Reads input from either a debug file or standard input.
     * Uses try-with-resources to prevent resource leaks.
     */
    public void readInput() {
        Scanner sc;
        if (isDebug) {
            sc = createFileScanner();
            if (sc == null) {
                if (isDebug) {
                    System.err.println("Failed to open debug input file.");
                }
                return;
            }
        } else {
            sc = new Scanner(System.in);
        }

        try (Scanner s = sc) {
            numNodes = s.nextInt();
            numEdges = s.nextInt();
            logDebug("n=%d m=%d", numNodes, numEdges);

            adjacencyMatrix = new boolean[numNodes][numNodes];
            for (int i = 0; i < numEdges; i++) {
                int u = s.nextInt() - 1;
                int v = s.nextInt() - 1;
                logDebug("%d %d", u + 1, v + 1);
                adjacencyMatrix[u][v] = true;
            }

            nodeStates = new NodeState[numNodes];
            Arrays.fill(nodeStates, NodeState.UNMARKED);
        }
    }

    private Scanner createFileScanner() {
        try {
            return new Scanner(new FileInputStream(DEBUG_INPUT_PATH));
        } catch (FileNotFoundException e) {
            e.printStackTrace();
            return null;
        }
    }

    private void logDebug(String format, Object... args) {
        if (isDebug) {
            System.out.printf(format + "%n", args);
        }
    }

    /**
     * Entry point for the solving logic.
     */
    public void solve() {
        if (numEdges == 0) {
            handleZeroEdges();
            return;
        }
        markNodes();
    }

    private void handleZeroEdges() {
        if (numNodes == 1) {
            printOutput(true, "a");
        } else if (numNodes == 2) {
            printOutput(true, "ac");
        } else {
            printOutput(false, null);
        }
    }

    /**
     * Orchestrates the node marking process and validates the final graph configuration.
     */
    private void markNodes() {
        markAllB();
        if (!markAllA()) return;
        if (!markAllC()) return;

        if (isGraphValid()) {
            printOutput(true, buildOutputString());
        } else {
            printOutput(false, null);
        }
    }

    /**
     * Marks all nodes that are connected to every other node in the graph as B.
     */
    private void markAllB() {
        for (int i = 0; i < numNodes; i++) {
            boolean isConnectedToAll = true;
            for (int j = 0; j < numNodes; j++) {
                if (i != j && !isConnected(i, j)) {
                    isConnectedToAll = false;
                    break;
                }
            }
            if (isConnectedToAll) {
                nodeStates[i] = NodeState.B;
            }
        }
    }

    /**
     * Marks the first unmarked node and its forward unmarked neighbors as A.
     * Returns false if all nodes are already marked.
     */
    private boolean markAllA() {
        int firstUnmarked = findFirstUnmarked();
        if (firstUnmarked == -1) {
            printOutput(true, buildStringOf('b', numNodes));
            return false;
        }

        nodeStates[firstUnmarked] = NodeState.A;
        for (int i = firstUnmarked + 1; i < numNodes; i++) {
            if (isConnected(firstUnmarked, i) && nodeStates[i] == NodeState.UNMARKED) {
                nodeStates[i] = NodeState.A;
            }
        }
        return true;
    }

    /**
     * Marks the first unmarked node and its forward unmarked neighbors as C.
     * Validates connectivity constraints during the process.
     * Returns false if constraints are violated or all nodes are marked.
     */
    private boolean markAllC() {
        int firstUnmarked = findFirstUnmarked();
        if (firstUnmarked == -1) {
            if (isGraphValid()) {
                printOutput(true, buildOutputString());
            } else {
                printOutput(false, null);
            }
            return false;
        }

        nodeStates[firstUnmarked] = NodeState.C;
        for (int i = firstUnmarked + 1; i < numNodes; i++) {
            if (nodeStates[i] == NodeState.UNMARKED) {
                if (isConnected(firstUnmarked, i)) {
                    nodeStates[i] = NodeState.C;
                } else {
                    printOutput(false, null);
                    return false;
                }
            }
        }
        return true;
    }

    private int findFirstUnmarked() {
        for (int i = 0; i < numNodes; i++) {
            if (nodeStates[i] == NodeState.UNMARKED) {
                return i;
            }
        }
        return -1;
    }

    /**
     * Validates the graph assignment against the problem's connectivity rules.
     * A nodes must connect to all C nodes and no A/B nodes.
     * C nodes must connect to all A nodes and no A/B nodes.
     * B nodes are fully connected and implicitly satisfy all rules.
     */
    private boolean isGraphValid() {
        for (int i = 0; i < numNodes; i++) {
            NodeState state = nodeStates[i];
            if (state == NodeState.A || state == NodeState.C) {
                NodeState requiredNeighbor = (state == NodeState.A) ? NodeState.C : NodeState.A;
                for (int j = 0; j < numNodes; j++) {
                    if (i == j) continue;
                    NodeState neighborState = nodeStates[j];
                    boolean isConnected = isConnected(i, j);

                    // A/C nodes must NOT be connected to their required counterpart type
                    // A/C nodes MUST be connected to all other types
                    if ((neighborState != requiredNeighbor && !isConnected) ||
                        (neighborState == requiredNeighbor && isConnected)) {
                        return false;
                    }
                }
            }
        }
        return true;
    }

    private boolean isConnected(int u, int v) {
        return adjacencyMatrix[u][v] || adjacencyMatrix[v][u];
    }

    private String buildStringOf(char c, int count) {
        char[] chars = new char[count];
        Arrays.fill(chars, c);
        return new String(chars);
    }

    private String buildOutputString() {
        StringBuilder sb = new StringBuilder(numNodes);
        for (NodeState state : nodeStates) {
            sb.append(state.name().toLowerCase());
        }
        return sb.toString();
    }

    private void printOutput(boolean success, String result) {
        System.out.println(success ? "Yes" : "No");
        if (success && result != null) {
            System.out.print(result);
        }
    }

    public static void main(String[] args) {
        GraphStringSolver solver = new GraphStringSolver(false);
        solver.readInput();
        solver.solve();
    }
}

import java.io.*;
import java.util.*;

public class Main {
    // Clear constants for label types
    private static final char LABEL_A = 'a';
    private static final char LABEL_B = 'b';
    private static final char LABEL_C = 'c';

    private final BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
    private final PrintWriter pw = new PrintWriter(System.out);
    private StringTokenizer st;

    public static void main(String[] args) {
        new Main().run();
    }

    public void run() {
        try {
            solve();
        } catch (IOException e) {
            e.printStackTrace();
        } finally {
            pw.flush();
            pw.close();
        }
    }

    private void solve() throws IOException {
        int n = nextInt();
        int m = nextInt();

        boolean[][] adjMatrix = new boolean[n + 1][n + 1];
        List<List<Integer>> adjList = new ArrayList<>();
        for (int i = 0; i <= n; i++) {
            adjList.add(new ArrayList<>());
        }
        int[] degree = new int[n + 1];

        for (int i = 0; i < m; i++) {
            int u = nextInt();
            int v = nextInt();
            adjMatrix[u][v] = adjMatrix[v][u] = true;
            adjList.get(u).add(v);
            adjList.get(v).add(u);
            degree[u]++;
            degree[v]++;
        }

        char[] labels = assignLabels(n, adjList, degree);
        boolean isValid = validateGraph(n, adjMatrix, labels);

        if (!isValid) {
            pw.println("No");
        } else {
            pw.println("Yes");
            for (int i = 1; i <= n; i++) {
                pw.print(labels[i]);
            }
            pw.println();
        }
    }

    /**
     * Assigns labels to nodes based on degree and adjacency rules.
     * - Nodes with degree n-1 are assigned 'b'
     * - The first non-'b' node and its neighbors are assigned 'a'
     * - All remaining nodes default to 'c'
     */
    private char[] assignLabels(int n, List<List<Integer>> adjList, int[] degree) {
        char[] labels = new char[n + 1];
        Arrays.fill(labels, LABEL_C);

        // Assign 'b' to nodes with degree n-1
        for (int i = 1; i <= n; i++) {
            if (degree[i] == n - 1) {
                labels[i] = LABEL_B;
            }
        }

        // Assign 'a' to the first non-'b' node and its neighbors
        for (int i = 1; i <= n; i++) {
            if (labels[i] != LABEL_B) {
                labels[i] = LABEL_A;
                for (int neighbor : adjList.get(i)) {
                    if (labels[neighbor] != LABEL_B) {
                        labels[neighbor] = LABEL_A;
                    }
                }
                break;
            }
        }
        return labels;
    }

    /**
     * Validates the label assignment against the graph edges.
     * Rules (preserved from original logic):
     * - A-C pairs must NOT be connected
     * - A-A pairs MUST be connected
     * - B-anything pairs MUST be connected
     * - C-C pairs MUST be connected (as per original branching logic)
     */
    private boolean validateGraph(int n, boolean[][] adjMatrix, char[] labels) {
        for (int i = 1; i <= n; i++) {
            for (int j = i + 1; j <= n; j++) {
                boolean isConnected = adjMatrix[i][j];
                char labelI = labels[i];
                char labelJ = labels[j];

                if (labelI == LABEL_A && labelJ == LABEL_C) {
                    if (isConnected) return false;
                } else if (labelI == LABEL_C && labelJ == LABEL_A) {
                    if (isConnected) return false;
                } else if (labelI == LABEL_A && labelJ == LABEL_A) {
                    if (!isConnected) return false;
                } else if (labelI == LABEL_B || labelJ == LABEL_B) {
                    if (!isConnected) return false;
                } else if (labelI == LABEL_C && labelJ == LABEL_C) {
                    if (!isConnected) return false;
                }
            }
        }
        return true;
    }

    private String next() throws IOException {
        while (st == null || !st.hasMoreTokens()) {
            String line = br.readLine();
            if (line == null) return null;
            st = new StringTokenizer(line);
        }
        return st.nextToken();
    }

    private int nextInt() throws IOException {
        String s = next();
        return s == null ? 0 : Integer.parseInt(s);
    }

    private long nextLong() throws IOException {
        String s = next();
        return s == null ? 0L : Long.parseLong(s);
    }

    private double nextDouble() throws IOException {
        String s = next();
        return s == null ? 0.0 : Double.parseDouble(s);
    }
}

import java.io.IOException;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Scanner;
import java.util.Set;

public class Main {

    public static void main(String[] args) throws IOException {
        // Use try-with-resources to guarantee the Scanner is properly closed
        try (Scanner scanner = new Scanner(System.in)) {
            if (!scanner.hasNextInt()) {
                return;
            }
            int n = scanner.nextInt();
            int m = scanner.nextInt();

            boolean[][] adjacencyMatrix = buildAdjacencyMatrix(n, m, scanner);
            String result = solve(n, adjacencyMatrix);
            System.out.println(result);
        }
    }

    /**
     * Builds the adjacency matrix from input.
     * Self-loops are initialized to true to simplify clique validation logic.
     */
    private static boolean[][] buildAdjacencyMatrix(int n, int m, Scanner scanner) {
        boolean[][] matrix = new boolean[n][n];
        for (int i = 0; i < n; i++) {
            matrix[i][i] = true;
        }

        for (int i = 0; i < m; i++) {
            int u = scanner.nextInt() - 1;
            int v = scanner.nextInt() - 1;
            matrix[u][v] = matrix[v][u] = true;
        }
        return matrix;
    }

    /**
     * Core logic: validates if the graph forms a valid tripartite structure
     * and constructs the result string accordingly.
     */
    private static String solve(int n, boolean[][] matrix) {
        if (n < 2) {
            return "Yes\n" + buildAllAString(n);
        }

        // Find two non-adjacent vertices to serve as structural pivots
        int[] pivots = findNonAdjacentPair(n, matrix);
        if (pivots == null) {
            // All vertices are connected (complete graph)
            return "Yes\n" + buildAllAString(n);
        }

        int pivotF = pivots[0];
        int pivotS = pivots[1];

        // Partition vertices into three sets based on adjacency to the pivots
        Set<Integer> setA = new HashSet<>();
        Set<Integer> setC = new HashSet<>();
        Set<Integer> setB = new HashSet<>();

        for (int i = 0; i < n; i++) {
            if (!matrix[pivotF][i]) {
                setC.add(i);
            } else if (!matrix[pivotS][i]) {
                setA.add(i);
            } else {
                setB.add(i);
            }
        }

        // Validate the partition against the required graph properties
        if (!validatePartition(matrix, setA, setC, setB)) {
            return "No";
        }

        return "Yes\n" + buildResultString(n, setA, setB, setC);
    }

    /**
     * Finds the first pair of non-adjacent vertices in the graph.
     * Returns null if the graph is complete.
     */
    private static int[] findNonAdjacentPair(int n, boolean[][] matrix) {
        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                if (!matrix[i][j]) {
                    return new int[]{i, j};
                }
            }
        }
        return null;
    }

    /**
     * Validates that the partitioned sets satisfy the graph constraints:
     * 1. Each set forms a clique.
     * 2. There are no edges between setA and setC.
     * 3. Every vertex in setB connects to all vertices in setA and setC.
     */
    private static boolean validatePartition(boolean[][] matrix, Set<Integer> setA, Set<Integer> setC, Set<Integer> setB) {
        if (!isClique(matrix, setA) || !isClique(matrix, setC) || !isClique(matrix, setB)) {
            return false;
        }
        if (hasEdgesBetween(matrix, setA, setC)) {
            return false;
        }
        for (int vertex : setB) {
            if (!isConnectedToAll(matrix, vertex, setA) || !isConnectedToAll(matrix, vertex, setC)) {
                return false;
            }
        }
        return true;
    }

    /**
     * Checks if all vertices in the given set are mutually connected.
     */
    private static boolean isClique(boolean[][] matrix, Set<Integer> vertices) {
        List<Integer> vertexList = new ArrayList<>(vertices);
        for (int i = 0; i < vertexList.size(); i++) {
            for (int j = i + 1; j < vertexList.size(); j++) {
                if (!matrix[vertexList.get(i)][vertexList.get(j)]) {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Checks if there is at least one edge between two sets.
     */
    private static boolean hasEdgesBetween(boolean[][] matrix, Set<Integer> set1, Set<Integer> set2) {
        for (int u : set1) {
            for (int v : set2) {
                if (matrix[u][v]) {
                    return true;
                }
            }
        }
        return false;
    }

    /**
     * Checks if a vertex is connected to every vertex in the target set.
     */
    private static boolean isConnectedToAll(boolean[][] matrix, int vertex, Set<Integer> targetSet) {
        for (int target : targetSet) {
            if (!matrix[vertex][target]) {
                return false;
            }
        }
        return true;
    }

    /**
     * Constructs the output string based on the vertex partition.
     */
    private static String buildResultString(int n, Set<Integer> setA, Set<Integer> setB, Set<Integer> setC) {
        StringBuilder result = new StringBuilder(n);
        for (int i = 0; i < n; i++) {
            if (setA.contains(i)) {
                result.append('a');
            } else if (setC.contains(i)) {
                result.append('c');
            } else {
                result.append('b');
            }
        }
        return result.toString();
    }

    /**
     * Helper to generate a string of 'a's for complete graphs.
     */
    private static String buildAllAString(int n) {
        StringBuilder sb = new StringBuilder(n);
        for (int i = 0; i < n; i++) {
            sb.append('a');
        }
        return sb.toString();
    }
}

import java.io.*;
import java.util.StringTokenizer;

public class CF19 {

    public static void main(String[] args) throws IOException {
        // Use try-with-resources to ensure BufferedReader is properly closed
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            FastScanner sc = new FastScanner(br);

            int n = sc.nextInt();
            int m = sc.nextInt();

            boolean[][] adj = new boolean[n][n];
            for (int i = 0; i < m; i++) {
                int u = sc.nextInt() - 1;
                int v = sc.nextInt() - 1;
                adj[u][v] = adj[v][u] = true;
            }

            int[] degree = new int[n];
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < n; j++) {
                    if (adj[i][j]) degree[i]++;
                }
            }

            System.out.println(solve(n, adj, degree));
        }
    }

    /**
     * Validates the graph structure and determines the partition of nodes.
     * Expected structure:
     * - Set B: Universal vertices (degree == n-1)
     * - Set A: Clique connected to B
     * - Set C: Clique connected to B
     * - No edges between A and C
     */
    private static String solve(int n, boolean[][] adj, int[] degree) {
        boolean[] isSetA = new boolean[n];
        int countA = 0, countB = 0, countC = 0;

        // 1. Identify and validate Set B (universal vertices)
        for (int i = 0; i < n; i++) {
            if (degree[i] == n - 1) {
                countB++;
                // B must be connected to all other nodes
                for (int j = 0; j < n; j++) {
                    if (i != j && !adj[i][j]) return "No";
                }
            }
        }

        // 2. Identify Set A (first unassigned non-B node and its non-B neighbors)
        for (int i = 0; i < n; i++) {
            if (degree[i] != n - 1) {
                isSetA[i] = true;
                countA++;
                for (int j = 0; j < n; j++) {
                    if (i == j || degree[j] == n - 1 || isSetA[j] || !adj[i][j]) continue;
                    if (degree[j] != degree[i]) return "No"; // Degree mismatch within set
                    isSetA[j] = true;
                    countA++;
                }
                break; // Only one A group is expected
            }
        }

        // 3. Identify Set C (remaining nodes)
        for (int i = 0; i < n; i++) {
            if (degree[i] != n - 1 && !isSetA[i]) {
                countC++;
                for (int j = 0; j < n; j++) {
                    if (i == j || degree[j] == n - 1 || isSetA[j] || !adj[i][j]) continue;
                    if (degree[j] != degree[i]) return "No";
                    countC++;
                }
                break; // Only one C group is expected
            }
        }

        // 4. Verify all nodes are accounted for
        if (countA + countB + countC != n) return "No";

        // 5. Verify internal and cross-set connectivity constraints
        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                boolean inB = (degree[i] == n - 1) || (degree[j] == n - 1);
                boolean inA = isSetA[i] || isSetA[j];
                boolean inC = !inB && !inA; // Remaining nodes form C

                if (inB) {
                    // Universal nodes must connect to everyone
                    if (!adj[i][j]) return "No";
                } else if (inA) {
                    // A must form a clique
                    if (!adj[i][j]) return "No";
                } else if (inC) {
                    // C must form a clique
                    if (!adj[i][j]) return "No";
                } else {
                    // A and C must not have any edges between them
                    if (adj[i][j]) return "No";
                }
            }
        }

        // 6. Construct and return the result string
        StringBuilder sb = new StringBuilder(n);
        for (int i = 0; i < n; i++) {
            if (degree[i] == n - 1) sb.append('b');
            else if (isSetA[i]) sb.append('a');
            else sb.append('c');
        }
        return sb.toString();
    }

    /**
     * Lightweight, standard fast I/O helper for competitive programming.
     */
    private static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner(BufferedReader br) {
            this.br = br;
        }

        String next() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) throw new EOFException("Unexpected end of input");
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.Arrays;
import java.util.StringTokenizer;

public class CodeForces {

    // Constants representing node states
    private static final int STATE_UNASSIGNED = 1;
    private static final int STATE_A = 0;
    private static final int STATE_C = 2;

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out);
        try {
            solve(scanner, out);
        } finally {
            out.flush();
        }
    }

    /**
     * Solves the problem by assigning states to nodes and verifying constraints.
     */
    private static void solve(FastScanner in, PrintWriter out) {
        int n = in.nextInt();
        int m = in.nextInt();

        boolean[][] adjacencyMatrix = new boolean[n][n];
        for (int i = 0; i < m; i++) {
            int u = in.nextInt() - 1;
            int v = in.nextInt() - 1;
            adjacencyMatrix[u][v] = true;
            adjacencyMatrix[v][u] = true;
        }

        int[] assignment = new int[n];
        Arrays.fill(assignment, STATE_UNASSIGNED);

        // Phase 1: Assign states based on non-edges
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (i == j) continue;

                if (!adjacencyMatrix[i][j]) {
                    int stateI = assignment[i];
                    int stateJ = assignment[j];

                    if (stateI == STATE_UNASSIGNED && stateJ == STATE_UNASSIGNED) {
                        assignment[i] = STATE_A;
                        assignment[j] = STATE_C;
                    } else if (stateI == stateJ && stateI != STATE_UNASSIGNED) {
                        out.println("No");
                        return;
                    } else if (stateI != STATE_UNASSIGNED) {
                        assignment[j] = (stateI == STATE_A) ? STATE_C : STATE_A;
                    } else if (stateJ != STATE_UNASSIGNED) {
                        assignment[i] = (stateJ == STATE_C) ? STATE_A : STATE_C;
                    }
                }
            }
        }

        // Phase 2: Verify constraints
        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                boolean hasEdge = adjacencyMatrix[i][j];
                boolean isCrossPair = (assignment[i] == STATE_A && assignment[j] == STATE_C) ||
                                      (assignment[i] == STATE_C && assignment[j] == STATE_A);

                if (hasEdge) {
                    if (!isCrossPair) {
                        out.println("No");
                        return;
                    }
                } else {
                    if (isCrossPair) {
                        out.println("No");
                        return;
                    }
                }
            }
        }

        out.println("Yes");
        for (int i = 0; i < n; i++) {
            out.print((char) (assignment[i] + 'a'));
        }
        out.println();
    }

    /**
     * FastScanner for efficient input reading in competitive programming.
     */
    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner(java.io.InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import java.util.StringTokenizer;

/**
 * Solves a constrained graph coloring problem using backtracking and Union-Find.
 * 
 * Constraints enforced:
 * 1. Nodes with the same color must belong to the same Union-Find equivalence class.
 * 2. Nodes with colors differing by at most 1 must be adjacent in the graph.
 */
public class GraphColoringSolver {

    private static final int NUM_COLORS = 3;
    private static final int UNASSIGNED_COLOR = -1;

    private int n;
    private List<List<Integer>> adjacencyList;
    private List<Set<Integer>> adjacencySet;
    private int[] colorAssignment;
    private boolean[] visited;
    private UnionFind unionFind;
    private boolean solutionFound;

    /**
     * Fast input reader for competitive programming style I/O.
     */
    private static class FastScanner {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastScanner(java.io.InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
            tokenizer = new StringTokenizer("");
        }

        private String next() throws IOException {
            while (!tokenizer.hasMoreTokens()) {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            String token = next();
            return token == null ? 0 : Integer.parseInt(token);
        }
    }

    /**
     * Union-Find data structure with path compression and union by rank.
     */
    private static class UnionFind {
        private final int[] parent;
        private final int[] rank;

        public UnionFind(int size) {
            parent = new int[size];
            rank = new int[size];
            for (int i = 0; i < size; i++) {
                parent[i] = i;
                rank[i] = 1;
            }
        }

        public int find(int i) {
            if (parent[i] != i) {
                parent[i] = find(parent[i]); // Path compression
            }
            return parent[i];
        }

        public void union(int i, int j) {
            int rootI = find(i);
            int rootJ = find(j);
            if (rootI == rootJ) return;

            // Union by rank
            if (rank[rootI] < rank[rootJ]) {
                parent[rootI] = rootJ;
            } else if (rank[rootI] > rank[rootJ]) {
                parent[rootJ] = rootI;
            } else {
                parent[rootJ] = rootI;
                rank[rootI]++;
            }
        }

        public boolean isConnected(int i, int j) {
            return find(i) == find(j);
        }
    }

    /**
     * Validates if assigning 'color' to 'node' satisfies all global constraints.
     */
    private boolean isValidColorAssignment(int node, int color) {
        for (int i = 0; i < n; i++) {
            // Constraint 1: Same color implies same equivalence class
            if (colorAssignment[i] == color && !unionFind.isConnected(node, i)) {
                return false;
            }
            // Constraint 2: Colors differing by <= 1 implies adjacency
            if (Math.abs(colorAssignment[i] - color) <= 1 && !adjacencySet.get(node).contains(i)) {
                return false;
            }
        }
        return true;
    }

    /**
     * Recursive backtracking DFS to assign colors to unvisited neighbors.
     * Returns true if a valid coloring for the entire component is found.
     */
    private boolean dfs(int node, int color) {
        visited[node] = true;
        colorAssignment[node] = color;

        for (int neighbor : adjacencyList.get(node)) {
            if (visited[neighbor]) continue;

            boolean assigned = false;
            // Try colors in order. The original code used a specific preference heuristic,
            // but iterating 0..2 maintains correctness while improving readability.
            for (int nextColor : new int[]{0, 1, 2}) {
                if (isValidColorAssignment(neighbor, nextColor)) {
                    if (dfs(neighbor, nextColor)) {
                        assigned = true;
                        break;
                    }
                }
            }
            if (!assigned) {
                return false;
            }
        }
        return true;
    }

    /**
     * Executes the solver: reads input, builds graph, computes equivalence classes,
     * and attempts to find a valid 3-coloring.
     */
    public boolean solve() throws IOException {
        FastScanner scanner = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            String nStr = scanner.next();
            if (nStr == null) return false;
            n = Integer.parseInt(nStr);
            int m = scanner.nextInt();

            // Initialize graph structures
            adjacencyList = new ArrayList<>(n);
            adjacencySet = new ArrayList<>(n);
            for (int i = 0; i < n; i++) {
                adjacencyList.add(new ArrayList<>());
                adjacencySet.add(new HashSet<>());
            }

            // Read edges
            for (int i = 0; i < m; i++) {
                int u = scanner.nextInt() - 1; // Convert to 0-based
                int v = scanner.nextInt() - 1;
                adjacencyList.get(u).add(v);
                adjacencyList.get(v).add(u);
                adjacencySet.get(u).add(v);
                adjacencySet.get(v).add(u);
            }

            // Compute node equivalence classes using Union-Find
            unionFind = new UnionFind(n);
            for (int i = 0; i < n; i++) {
                for (int j = i + 1; j < n; j++) {
                    if (adjacencyList.get(i).size() != adjacencyList.get(j).size() ||
                        unionFind.isConnected(i, j)) {
                        continue;
                    }

                    boolean isEquivalent = true;
                    for (int neighbor : adjacencyList.get(i)) {
                        if (neighbor == j) continue;
                        if (!adjacencySet.get(j).contains(neighbor)) {
                            isEquivalent = false;
                            break;
                        }
                    }
                    if (isEquivalent) {
                        unionFind.union(i, j);
                    }
                }
            }

            // Initialize state for coloring attempts
            colorAssignment = new int[n];
            visited = new boolean[n];
            solutionFound = false;

            // Try each possible starting color for node 0
            for (int startColor : new int[]{0, 1, 2}) {
                // Reset state for each attempt
                for (int i = 0; i < n; i++) {
                    colorAssignment[i] = UNASSIGNED_COLOR;
                    visited[i] = false;
                }

                if (dfs(0, startColor)) {
                    // Handle disconnected components
                    boolean allComponentsSolved = true;
                    for (int i = 0; i < n; i++) {
                        if (!visited[i]) {
                            boolean componentSolved = false;
                            for (int c : new int[]{0, 1, 2}) {
                                if (isValidColorAssignment(i, c)) {
                                    if (dfs(i, c)) {
                                        componentSolved = true;
                                        break;
                                    }
                                }
                            }
                            if (!componentSolved) {
                                allComponentsSolved = false;
                                break;
                            }
                        }
                    }
                    if (allComponentsSolved) {
                        solutionFound = true;
                        break;
                    }
                }
            }

            // Output result
            if (solutionFound) {
                out.println("Yes");
                for (int i = 0; i < n; i++) {
                    out.print((char) (colorAssignment[i] + 'a'));
                }
                out.println();
            } else {
                out.println("No");
            }
        } finally {
            out.flush();
        }
        return solutionFound;
    }

    public static void main(String[] args) throws IOException {
        new GraphColoringSolver().solve();
    }
}

import java.io.IOException;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.InputMismatchException;
import java.util.List;
import java.util.Set;

public class GraphAndString {

    public static void main(String[] args) {
        FasterScanner scanner = new FasterScanner();
        int n = scanner.nextInt();
        int m = scanner.nextInt();

        // 1. Build the graph representation
        List<Set<Integer>> graph = buildGraph(scanner, n, m);

        // 2. Assign labels based on graph properties
        char[] labels = assignLabels(graph, n);

        // 3. Validate consistency between graph structure and labels
        boolean isValid = validateGraph(graph, labels, n);

        if (isValid) {
            System.out.println("Yes");
            System.out.println(new String(labels));
        } else {
            System.out.println("No");
        }
    }

    /**
     * Constructs an undirected graph from the input stream.
     */
    private static List<Set<Integer>> buildGraph(FasterScanner scanner, int n, int m) {
        List<Set<Integer>> graph = new ArrayList<>(n);
        for (int i = 0; i < n; i++) {
            graph.add(new HashSet<>());
        }
        for (int i = 0; i < m; i++) {
            int u = scanner.nextInt() - 1;
            int v = scanner.nextInt() - 1;
            graph.get(u).add(v);
            graph.get(v).add(u);
        }
        return graph;
    }

    /**
     * Assigns 'a', 'b', or 'c' to each node based on connectivity rules.
     */
    private static char[] assignLabels(List<Set<Integer>> graph, int n) {
        char[] labels = new char[n];

        // Nodes connected to all other nodes receive 'b'
        for (int i = 0; i < n; i++) {
            if (graph.get(i).size() == n - 1) {
                labels[i] = 'b';
            }
        }

        // Unassigned nodes receive 'a'; their non-neighbors receive 'c'
        for (int i = 0; i < n; i++) {
            if (labels[i] == '\0') {
                labels[i] = 'a';
                for (int j = i + 1; j < n; j++) {
                    if (!graph.get(i).contains(j)) {
                        labels[j] = 'c';
                    }
                }
            }
        }
        return labels;
    }

    /**
     * Verifies that every edge corresponds to adjacent/same labels,
     * and every non-edge corresponds to non-adjacent labels.
     */
    private static boolean validateGraph(List<Set<Integer>> graph, char[] labels, int n) {
        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                boolean edgeExists = graph.get(i).contains(j);
                boolean labelsAdjacent = Math.abs(labels[i] - labels[j]) <= 1;

                if (edgeExists != labelsAdjacent) {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Fast I/O utility class commonly used in competitive programming.
     */
    public static class FasterScanner {
        private byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;

        public int read() {
            if (numChars == -1) {
                throw new InputMismatchException();
            }
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = System.in.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0) {
                    return -1;
                }
            }
            return buf[curChar++];
        }

        public String nextLine() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            StringBuilder res = new StringBuilder();
            do {
                res.appendCodePoint(c);
                c = read();
            } while (!isEndOfLine(c));
            return res.toString();
        }

        public String nextString() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            StringBuilder res = new StringBuilder();
            do {
                res.appendCodePoint(c);
                c = read();
            } while (!isSpaceChar(c));
            return res.toString();
        }

        public long nextLong() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            long res = 0;
            do {
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                res *= 10;
                res += c - '0';
                c = read();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public int nextInt() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                res *= 10;
                res += c - '0';
                c = read();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public int[] nextIntArray(int n) {
            int[] arr = new int[n];
            for (int i = 0; i < n; i++) {
                arr[i] = nextInt();
            }
            return arr;
        }

        public long[] nextLongArray(int n) {
            long[] arr = new long[n];
            for (int i = 0; i < n; i++) {
                arr[i] = nextLong();
            }
            return arr;
        }

        private boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        private boolean isEndOfLine(int c) {
            return c == '\n' || c == '\r' || c == -1;
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Main entry point for the program.
 * Refactored to improve structure and readability.
 */
public class Main {
    public static void main(String[] args) {
        // Initialize Input/Output streams
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;

        // Use FastScanner for efficient input reading
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);

        // Instantiate and run the solver
        GraphSolver solver = new GraphSolver();
        solver.solve(1, in, out);

        out.close();
    }

    /**
     * Encapsulates the logic for solving the graph problem.
     */
    static class GraphSolver {
        // Constants for node types to replace magic characters
        private static final char TYPE_A = 'a';
        private static final char TYPE_B = 'b';
        private static final char TYPE_C = 'c';
        private static final char TYPE_UNKNOWN = 0;

        /**
         * Solves the problem for a given test case.
         *
         * @param testNumber The test case number (unused in logic but passed for convention)
         * @param in         Input reader
         * @param out        Output writer
         */
        public void solve(int testNumber, InputReader in, PrintWriter out) {
            int n = in.nextInt();
            int m = in.nextInt();

            // Initialize adjacency list. Index 0 is unused.
            List<List<Integer>> adj = new ArrayList<>(n + 1);
            for (int i = 0; i <= n; i++) {
                adj.add(new ArrayList<>());
            }

            // Read edges
            for (int i = 0; i < m; i++) {
                int u = in.nextInt();
                int v = in.nextInt();
                adj.get(u).add(v);
                adj.get(v).add(u);
            }

            // Array to store node labels. 1-based indexing.
            char[] labels = new char[n + 1];

            // 1. Identify Type B nodes (connected to all other nodes)
            // A node connected to everyone else must have degree n - 1.
            for (int i = 1; i <= n; i++) {
                if (adj.get(i).size() == n - 1) {
                    labels[i] = TYPE_B;
                }
            }

            // 2. Identify Type A nodes
            // Find the first unvisited node and traverse its connected component.
            // Note: Original logic breaks after the first component, implying a specific graph structure.
            for (int i = 1; i <= n; i++) {
                if (labels[i] == TYPE_UNKNOWN) {
                    dfs(adj, labels, i);
                    break;
                }
            }

            // 3. Assign Type C to remaining unvisited nodes
            for (int i = 1; i <= n; i++) {
                if (labels[i] == TYPE_UNKNOWN) {
                    labels[i] = TYPE_C;
                }
            }

            // 4. Validate the assignment
            if (validate(n, adj, labels)) {
                out.println("Yes");
                for (int i = 1; i <= n; i++) {
                    out.print(labels[i]);
                }
                out.println(); // Ensure output ends with a newline
            } else {
                out.println("No");
            }
        }

        /**
         * Performs Depth First Search to label a connected component as Type A.
         */
        private void dfs(List<List<Integer>> adj, char[] labels, int node) {
            labels[node] = TYPE_A;
            for (int neighbor : adj.get(node)) {
                if (labels[neighbor] == TYPE_UNKNOWN) {
                    dfs(adj, labels, neighbor);
                }
            }
        }

        /**
         * Validates the node labeling against the problem constraints.
         *
         * @param n     Number of nodes
         * @param adj   Adjacency list
         * @param labels Node types
         * @return true if valid, false otherwise
         */
        private boolean validate(int n, List<List<Integer>> adj, char[] labels) {
            // We need to verify two conditions for every node i:
            // 1. All neighbors must have a compatible type (distance <= 1).
            // 2. All non-neighbors must have an incompatible type (distance > 1).
            //
            // Types: 'a'=97, 'b'=98, 'c'=99.
            // Compatible pairs: (a,a), (a,b), (b,a), (b,b), (b,c), (c,b), (c,c).
            // Incompatible pairs: (a,c), (c,a).

            for (int i = 1; i <= n; i++) {
                char typeI = labels[i];

                // Mark neighbors for O(1) lookup. 
                // Using a boolean array is more efficient than allocating a HashSet in a loop.
                boolean[] isNeighbor = new boolean[n + 1];
                for (int neighbor : adj.get(i)) {
                    isNeighbor[neighbor] = true;
                }

                for (int j = 1; j <= n; j++) {
                    if (i == j) continue;

                    char typeJ = labels[j];
                    boolean isNeighborOfI = isNeighbor[j];

                    // Calculate distance between types
                    int diff = Math.abs(typeI - typeJ);

                    if (isNeighborOfI) {
                        // Condition: Neighbors must be compatible
                        if (diff > 1) return false;
                    } else {
                        // Condition: Non-neighbors must be incompatible
                        if (diff <= 1) return false;
                    }
                }
            }
            return true;
        }
    }

    /**
     * Helper class for fast input reading.
     */
    static class InputReader {
        private StringTokenizer tokenizer;
        private BufferedReader reader;

        public InputReader(InputStream inputStream) {
            reader = new BufferedReader(new InputStreamReader(inputStream));
        }

        private void fillTokenizer() {
            if (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
        }

        public String next() {
            fillTokenizer();
            return tokenizer != null ? tokenizer.nextToken() : null;
        }

        public int nextInt() {
            String s = next();
            if (s == null) throw new RuntimeException("End of input");
            return Integer.parseInt(s);
        }
    }
}

import java.io.*;
import java.util.*;

public class GraphColoringSolver {

    private FastScanner scanner;
    private PrintWriter output;

    /**
     * Entry point for the solver. Reads input, processes the graph,
     * and writes the result to standard output.
     */
    public void solve() {
        scanner = new FastScanner();
        output = new PrintWriter(new BufferedOutputStream(System.out));

        int numVertices = scanner.nextInt();
        int numEdges = scanner.nextInt();

        // Adjacency matrix: 1 represents an edge, 0 represents no edge
        int[][] adjacencyMatrix = new int[numVertices][numVertices];
        for (int i = 0; i < numEdges; i++) {
            int u = scanner.nextInt() - 1;
            int v = scanner.nextInt() - 1;
            adjacencyMatrix[u][v] = adjacencyMatrix[v][u] = 1;
        }

        int[] colors = new int[numVertices];
        boolean isPossible = true;

        // Attempt to color each connected component
        for (int i = 0; i < numVertices && isPossible; i++) {
            if (colors[i] != 0) continue;

            // The algorithm requires at least one non-neighbor to start coloring
            boolean hasNonNeighbor = false;
            for (int j = 0; j < numVertices; j++) {
                if (i == j) continue;
                if (adjacencyMatrix[i][j] == 0) {
                    hasNonNeighbor = true;
                    break;
                }
            }

            if (hasNonNeighbor) {
                isPossible = tryColor(i, -1, colors, adjacencyMatrix);
            }
        }

        // Validate edge constraints: adjacent nodes must have colors differing by exactly 2
        if (isPossible) {
            for (int i = 0; i < numVertices && isPossible; i++) {
                for (int j = i + 1; j < numVertices && isPossible; j++) {
                    if (adjacencyMatrix[i][j] == 1) {
                        int colorDiff = colors[i] - colors[j];
                        if (Math.abs(colorDiff) != 2) {
                            isPossible = false;
                        }
                    }
                }
            }
        }

        // Output results
        if (isPossible) {
            output.println("Yes");
            for (int i = 0; i < numVertices; i++) {
                // Maps -1 -> 'a', 0 -> 'b', 1 -> 'c'
                output.print((char) ('a' + colors[i] + 1));
            }
            output.println();
        } else {
            output.println("No");
        }

        output.flush();
        output.close();
    }

    /**
     * Recursively assigns colors based on non-edge constraints.
     * Non-adjacent nodes must have different colors. If a node is uncolored,
     * it inherits the opposite color of its non-adjacent colored neighbor.
     *
     * @return true if coloring is valid, false if a conflict is detected
     */
    private boolean tryColor(int currentNode, int currentColor, int[] colors, int[][] adjacencyMatrix) {
        colors[currentNode] = currentColor;

        for (int neighbor = 0; neighbor < colors.length; neighbor++) {
            if (neighbor == currentNode) continue;

            // Constraint: Non-adjacent nodes must have different colors
            if (adjacencyMatrix[currentNode][neighbor] == 0) {
                if (colors[neighbor] == currentColor) {
                    return false; // Conflict: same color on non-adjacent nodes
                }
                if (colors[neighbor] == 0) {
                    // Propagate opposite color to uncolored non-adjacent node
                    if (!tryColor(neighbor, -currentColor, colors, adjacencyMatrix)) {
                        return false;
                    }
                }
            }
        }
        return true;
    }

    public static void main(String[] args) {
        new GraphColoringSolver().solve();
    }

    /**
     * Fast input reader for competitive programming style problems.
     */
    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input", e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.ArrayList;
import java.util.List;

public class GraphAndString {

    public static void main(String[] args) {
        // Use try-with-resources to ensure resources (BufferedReader, PrintWriter) 
        // are closed automatically, preventing resource leaks.
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
             PrintWriter pw = new PrintWriter(System.out)) {

            String line = br.readLine();
            if (line == null) {
                return;
            }

            // Parse number of vertices and edges
            // Using trim() to handle potential leading/trailing whitespace
            String[] tokens = line.trim().split("\\s+");
            int numVertices = Integer.parseInt(tokens[0]);
            int numEdges = Integer.parseInt(tokens[1]);

            // Initialize adjacency list (1-based indexing)
            // Using List interface for better abstraction and flexibility
            List<List<Integer>> adjList = new ArrayList<>(numVertices + 1);
            for (int i = 0; i <= numVertices; i++) {
                adjList.add(new ArrayList<>());
            }

            // Read edges
            for (int i = 0; i < numEdges; i++) {
                line = br.readLine();
                if (line != null) {
                    tokens = line.trim().split("\\s+");
                    int u = Integer.parseInt(tokens[0]);
                    int v = Integer.parseInt(tokens[1]);
                    adjList.get(u).add(v);
                    adjList.get(v).add(u);
                }
            }

            // Process graph and validate
            ValidationResult result = processGraph(numVertices, adjList);

            if (result.isValid) {
                pw.println("Yes");
                pw.println(result.labelString);
            } else {
                pw.println("No");
            }

        } catch (IOException e) {
            System.err.println("I/O Error: " + e.getMessage());
        } catch (Exception e) {
            // Avoid swallowing exceptions; print stack trace for debugging.
            // The original code swallowed exceptions, which is bad practice.
            e.printStackTrace();
        }
    }

    /**
     * Processes the graph to identify node types ('a', 'b', 'c') and validates the structure.
     * 
     * Logic derived from original code:
     * 1. 'b' nodes are connected to all other vertices (degree == V-1).
     * 2. Remaining nodes are split into 'a' and 'c' components.
     * 3. 'a' nodes form a clique and connect to 'b' nodes.
     * 4. 'c' nodes form a clique and connect to 'b' nodes.
     * 5. 'a' and 'c' nodes do not connect to each other.
     */
    private static ValidationResult processGraph(int n, List<List<Integer>> adjList) {
        char[] labels = new char[n + 1]; // 1-based indexing
        boolean isValid = true;

        // 1. Identify 'b' nodes (connected to everyone else)
        // In a graph with n vertices, a 'b' node must have degree n-1.
        for (int i = 1; i <= n; i++) {
            if (adjList.get(i).size() == n - 1) {
                labels[i] = 'b';
            }
        }

        // 2. Identify 'a' component
        // Find the first node that is not 'b'
        int startA = -1;
        for (int i = 1; i <= n; i++) {
            if (labels[i] == 0) { // 0 indicates unassigned (default char value)
                startA = i;
                break;
            }
        }

        if (startA != -1) {
            labels[startA] = 'a';
            // Propagate 'a' to neighbors (excluding 'b' nodes)
            // This matches the original logic where neighbors of the starter become 'a'
            for (int neighbor : adjList.get(startA)) {
                if (labels[neighbor] != 'b') {
                    labels[neighbor] = 'a';
                }
            }
        }

        // 3. Identify 'c' component
        // Find the first node that is not 'a' and not 'b'
        int startC = -1;
        for (int i = 1; i <= n; i++) {
            if (labels[i] == 0) {
                startC = i;
                break;
            }
        }

        if (startC != -1) {
            labels[startC] = 'c';
            // Propagate 'c' to neighbors (excluding 'b' nodes)
            for (int neighbor : adjList.get(startC)) {
                if (labels[neighbor] != 'b') {
                    labels[neighbor] = 'c';
                }
            }
        }

        // 4. Validation Phase

        // Check if all vertices are labeled
        for (int i = 1; i <= n; i++) {
            if (labels[i] == 0) {
                isValid = false;
                break;
            }
        }
        if (!isValid) {
            return new ValidationResult(false, "");
        }

        // Count 'a' and 'c' nodes for strict validation
        int countA = 0;
        int countC = 0;
        for (int i = 1; i <= n; i++) {
            if (labels[i] == 'a') countA++;
            else if (labels[i] == 'c') countC++;
        }

        // Validate connectivity rules
        for (int i = 1; i <= n; i++) {
            char type = labels[i];

            // 'b' nodes connect to everyone, so we don't check their neighbors' types.
            // The constraint is on the node itself: 'a' nodes can only connect to 'a' or 'b'.
            if (type == 'b') {
                continue;
            }

            int sameTypeNeighbors = 0;
            for (int neighbor : adjList.get(i)) {
                char neighborType = labels[neighbor];

                if (neighborType == 'b') {
                    continue; // 'b' is allowed
                }

                if (neighborType != type) {
                    // Invalid connection: 'a' connected to 'c' (or vice versa)
                    isValid = false;
                    break;
                }

                if (neighborType == type) {
                    sameTypeNeighbors++;
                }
            }

            if (!isValid) {
                break;
            }

            // Strict validation: 
            // 'a' nodes must connect to ALL other 'a' nodes (clique property)
            // 'c' nodes must connect to ALL other 'c' nodes (clique property)
            // This matches the original check: validCount != (noOfA-1)
            if (type == 'a' && sameTypeNeighbors != countA - 1) {
                isValid = false;
                break;
            }
            if (type == 'c' && sameTypeNeighbors != countC - 1) {
                isValid = false;
                break;
            }
        }

        String labelString = new String(labels, 1, n);
        return new ValidationResult(isValid, labelString);
    }

    /**
     * Helper class to hold the result of the graph processing.
     */
    private static class ValidationResult {
        boolean isValid;
        String labelString;

        ValidationResult(boolean isValid, String labelString) {
            this.isValid = isValid;
            this.labelString = labelString;
        }
    }
}

import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Scanner;
import java.util.Set;

/**
 * A solver for a graph partitioning problem.
 * The program attempts to partition the graph nodes into three sets (A, B, C)
 * based on specific connectivity rules and validates if such a partition exists.
 */
public class GraphPartitionSolver {

    public static void main(String[] args) {
        // Use try-with-resources to ensure the Scanner is closed properly
        try (Scanner scanner = new Scanner(System.in)) {
            if (!scanner.hasNextInt()) return;

            int n = scanner.nextInt();
            int m = scanner.nextInt();

            // Use List of Lists for adjacency to avoid generic array creation warnings
            // and improve type safety.
            List<List<Integer>> adj = new ArrayList<>(n);
            for (int i = 0; i < n; i++) {
                adj.add(new ArrayList<>());
            }

            for (int i = 0; i < m; i++) {
                int u = scanner.nextInt() - 1;
                int v = scanner.nextInt() - 1;
                adj.get(u).add(v);
                adj.get(v).add(u);
            }

            solve(n, adj);
        }
    }

    private static void solve(int n, List<List<Integer>> adj) {
        // 1. Identify Set B: Nodes connected to everyone (degree n-1)
        Set<Integer> setB = identifyUniversalNodes(n, adj);

        // 2. Identify Set A: A component not connected to B (heuristically)
        // The original logic picks the first node not in B and adds its non-B neighbors.
        Set<Integer> setA = new HashSet<>();
        findComponent(n, adj, setB, setA);

        // 3. Identify Set C: Another component not in B or A
        Set<Integer> setC = new HashSet<>();
        // We must exclude nodes already assigned to A to prevent overlap in the search
        Set<Integer> excludedForC = new HashSet<>(setB);
        excludedForC.addAll(setA);
        findComponent(n, adj, excludedForC, setC);

        // 4. Validate the partition
        if (validatePartition(n, adj, setA, setB, setC)) {
            System.out.println("Yes");
            printResult(n, setA, setB, setC);
        } else {
            System.out.println("No");
        }
    }

    /**
     * Identifies nodes that are connected to all other nodes in the graph.
     * These nodes form the "universal" set B.
     */
    private static Set<Integer> identifyUniversalNodes(int n, List<List<Integer>> adj) {
        Set<Integer> universalNodes = new HashSet<>();
        for (int i = 0; i < n; i++) {
            // A universal node must have degree n-1
            if (adj.get(i).size() == n - 1) {
                universalNodes.add(i);
            }
        }
        return universalNodes;
    }

    /**
     * Finds a component of nodes based on a starting heuristic.
     * It selects the first node not in 'forbidden' and adds it and its 
     * non-forbidden neighbors to the 'target' set.
     *
     * @param n The number of nodes.
     * @param adj The adjacency list.
     * @param forbidden A set of nodes that should not be included in the component.
     * @param target The set to populate with the found component.
     */
    private static void findComponent(int n, List<List<Integer>> adj, 
                                      Set<Integer> forbidden, Set<Integer> target) {
        for (int i = 0; i < n; i++) {
            if (!forbidden.contains(i)) {
                target.add(i);
                for (int neighbor : adj.get(i)) {
                    if (!forbidden.contains(neighbor)) {
                        target.add(neighbor);
                    }
                }
                break; // Found the component, stop searching
            }
        }
    }

    /**
     * Validates if the partition (A, B, C) satisfies the graph constraints.
     * Constraints:
     * - A is a clique connected to all nodes in B.
     * - C is a clique connected to all nodes in B.
     * - No edges between A and C.
     * - All nodes are partitioned.
     */
    private static boolean validatePartition(int n, List<List<Integer>> adj, 
                                             Set<Integer> setA, Set<Integer> setB, Set<Integer> setC) {

        // Check if all nodes are accounted for
        if (setA.size() + setB.size() + setC.size() != n) {
            return false;
        }

        // Validate nodes in Set A
        // Expected degree: (Size of A - 1) + (Size of B)
        int expectedDegreeA = setA.size() + setB.size() - 1;
        for (int u : setA) {
            if (adj.get(u).size() != expectedDegreeA) {
                return false;
            }
            for (int v : adj.get(u)) {
                // Neighbors must be in A or B
                if (!setA.contains(v) && !setB.contains(v)) {
                    return false;
                }
            }
        }

        // Validate nodes in Set C
        // Expected degree: (Size of C - 1) + (Size of B)
        int expectedDegreeC = setC.size() + setB.size() - 1;
        for (int u : setC) {
            if (adj.get(u).size() != expectedDegreeC) {
                return false;
            }
            for (int v : adj.get(u)) {
                // Neighbors must be in C or B
                if (!setC.contains(v) && !setB.contains(v)) {
                    return false;
                }
            }
        }

        return true;
    }

    private static void printResult(int n, Set<Integer> setA, Set<Integer> setB, Set<Integer> setC) {
        StringBuilder sb = new StringBuilder(n);
        for (int i = 0; i < n; i++) {
            if (setA.contains(i)) {
                sb.append('a');
            } else if (setB.contains(i)) {
                sb.append('b');
            } else {
                sb.append('c');
            }
        }
        System.out.println(sb.toString());
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayDeque;
import java.util.Queue;
import java.util.StringTokenizer;

/**
 * Validates whether the complement of a given graph forms a complete bipartite structure.
 * If valid, outputs "Yes" and a valid 2-coloring (with isolated nodes marked as 'c').
 */
public class GraphValidator {

    // Color constants for the complement graph
    private static final int UNCOLORED = 0;
    private static final int PARTITION_A = 1;
    private static final int ISOLATED = 2;
    private static final int PARTITION_B = 3;

    // Mapping from color constants to output characters
    private static final char[] COLOR_TO_CHAR = {'a', 'b', 'c'};

    public static void main(String[] args) throws IOException {
        FastScanner scanner = new FastScanner();

        // Read graph dimensions
        int n = scanner.nextInt();
        int m = scanner.nextInt();

        // Build original adjacency matrix
        boolean[][] adjacencyMatrix = new boolean[n][n];
        for (int i = 0; i < m; i++) {
            int u = scanner.nextInt() - 1; // Convert to 0-indexed
            int v = scanner.nextInt() - 1;
            adjacencyMatrix[u][v] = true;
            adjacencyMatrix[v][u] = true;
        }

        // Compute complement graph and degrees
        boolean[][] complementMatrix = buildComplementMatrix(adjacencyMatrix, n);
        int[] complementDegrees = computeComplementDegrees(complementMatrix, n);

        // Initialize colors: mark isolated nodes in the complement graph
        int[] nodeColors = new int[n];
        for (int i = 0; i < n; i++) {
            if (complementDegrees[i] == 0) {
                nodeColors[i] = ISOLATED;
            }
        }

        // Find a starting node for BFS (must have degree > 0)
        int root = findStartNode(complementDegrees, n);
        boolean isValid = true;

        if (root != -1) {
            isValid = bfsAndValidate(complementMatrix, nodeColors, complementDegrees, root, n);
        }

        // Output results
        if (isValid) {
            System.out.println("Yes");
            System.out.println(formatOutput(nodeColors, n));
        } else {
            System.out.println("No");
        }
    }

    /**
     * Constructs the adjacency matrix of the complement graph.
     */
    private static boolean[][] buildComplementMatrix(boolean[][] original, int n) {
        boolean[][] complement = new boolean[n][n];
        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                boolean isConnected = original[i][j];
                complement[i][j] = !isConnected;
                complement[j][i] = !isConnected;
            }
        }
        return complement;
    }

    /**
     * Computes the degree of each node in the complement graph.
     */
    private static int[] computeComplementDegrees(boolean[][] complement, int n) {
        int[] degrees = new int[n];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (complement[i][j]) {
                    degrees[i]++;
                }
            }
        }
        return degrees;
    }

    /**
     * Finds the first node with a non-zero degree in the complement graph.
     */
    private static int findStartNode(int[] degrees, int n) {
        for (int i = 0; i < n; i++) {
            if (degrees[i] > 0) {
                return i;
            }
        }
        return -1;
    }

    /**
     * Performs BFS to bipartition the graph component and validates structural constraints.
     * Returns false if the graph is not a valid complete bipartite graph or has unvisited nodes.
     */
    private static boolean bfsAndValidate(boolean[][] complement, int[] colors, int[] degrees, 
                                          int root, int n) {
        Queue<Integer> queue = new ArrayDeque<>();
        queue.add(root);
        colors[root] = PARTITION_A;

        int partitionACount = 1;
        int partitionBCount = 0;

        while (!queue.isEmpty()) {
            int current = queue.poll();

            for (int next = 0; next < n; next++) {
                if (next != current && complement[current][next]) {
                    // Conflict: reached an isolated node or same partition
                    if (colors[next] == ISOLATED || colors[next] == colors[current]) {
                        return false;
                    } 
                    // Color unvisited neighbor
                    else if (colors[next] == UNCOLORED) {
                        if (colors[current] == PARTITION_A) {
                            colors[next] = PARTITION_B;
                            partitionBCount++;
                        } else {
                            colors[next] = PARTITION_A;
                            partitionACount++;
                        }
                        queue.add(next);
                    }
                }
            }
        }

        // Validate: all nodes must be colored, and degrees must match opposite partition size
        for (int i = 0; i < n; i++) {
            if (colors[i] == UNCOLORED) {
                return false; // Graph has disconnected components
            }
            if (colors[i] == PARTITION_A && degrees[i] != partitionBCount) {
                return false;
            } else if (colors[i] == PARTITION_B && degrees[i] != partitionACount) {
                return false;
            }
        }

        return true;
    }

    /**
     * Converts the internal color array to the required output string.
     */
    private static String formatOutput(int[] colors, int n) {
        StringBuilder sb = new StringBuilder(n);
        for (int i = 0; i < n; i++) {
            sb.append(COLOR_TO_CHAR[colors[i] - 1]);
        }
        return sb.toString();
    }

    /**
     * Fast input reader for competitive programming / large I/O scenarios.
     */
    private static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            String token = next();
            return token == null ? 0 : Integer.parseInt(token);
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.OutputStream;
import java.io.PrintWriter;
import java.util.Arrays;
import java.util.StringTokenizer;

public class Main {

    // Instance fields to avoid static state and improve maintainability
    private InputReader reader;
    private PrintWriter writer;
    private int n;
    private boolean[][] graph;
    private boolean[] visited;
    private int[] color;
    private int[] degrees;

    public Main(InputReader reader, PrintWriter writer) {
        this.reader = reader;
        this.writer = writer;
    }

    public void solve() {
        n = reader.nextInt();
        int m = reader.nextInt();

        graph = new boolean[n][n];
        visited = new boolean[n];
        color = new int[n];
        degrees = new int[n];

        // Initialize as a complete graph
        for (int i = 0; i < n; i++) {
            Arrays.fill(graph[i], true);
            degrees[i] = n - 1;
        }

        // Remove m edges from the complete graph
        for (int i = 0; i < m; i++) {
            int u = reader.nextInt() - 1;
            int v = reader.nextInt() - 1;
            graph[u][v] = graph[v][u] = false;
            degrees[u]--;
            degrees[v]--;
        }

        // Check if the graph is bipartite using DFS
        for (int i = 0; i < n; i++) {
            if (!visited[i]) {
                if (!dfs(i, i, 0)) {
                    writer.println("No");
                    return;
                }
            }
        }

        // Determine assignment values based on degree and bipartite color
        int[] assignment = new int[n];
        for (int i = 0; i < n; i++) {
            if (degrees[i] == 0) {
                assignment[i] = 1;
            } else if (color[i] == 1) {
                assignment[i] = 2;
            } else {
                assignment[i] = 0;
            }
        }

        // Validate the assignment: count pairs that satisfy the condition
        int compatiblePairs = 0;
        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                if (assignment[i] == assignment[j] || Math.abs(assignment[i] - assignment[j]) == 1) {
                    compatiblePairs++;
                }
            }
        }

        if (compatiblePairs != m) {
            writer.println("No");
        } else {
            writer.println("Yes");
            for (int val : assignment) {
                writer.print((char) (val + 'a'));
            }
            writer.println();
        }
    }

    /**
     * Depth-First Search to check bipartiteness.
     *
     * @param u             Current node
     * @param parent        Parent node in the DFS tree
     * @param currentColor  Color to assign to current node (0 or 1)
     * @return true if bipartite, false otherwise
     */
    private boolean dfs(int u, int parent, int currentColor) {
        visited[u] = true;
        color[u] = currentColor;

        for (int v = 0; v < n; v++) {
            // Skip self, parent, or non-edges
            if (v == parent || v == u || !graph[u][v]) {
                continue;
            }

            // If neighbor is already visited and has the same color, not bipartite
            if (visited[v] && color[v] == currentColor) {
                return false;
            }

            // Recursively visit unvisited neighbors with flipped color
            if (!visited[v] && !dfs(v, u, currentColor ^ 1)) {
                return false;
            }
        }
        return true;
    }

    public static void main(String[] args) {
        // Use try-with-resources for automatic and safe resource management
        try (InputStream inputStream = System.in;
             OutputStream outputStream = System.out) {
            InputReader reader = new InputReader(inputStream);
            PrintWriter writer = new PrintWriter(outputStream);
            new Main(reader, writer).solve();
            writer.flush();
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    /**
     * Fast input reader for competitive programming.
     */
    static class InputReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public InputReader(InputStream inputStream) {
            this.reader = new BufferedReader(new InputStreamReader(inputStream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) {
                        return null;
                    }
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            String s = next();
            if (s == null) throw new RuntimeException("Unexpected end of input");
            return Integer.parseInt(s);
        }

        public long nextLong() {
            String s = next();
            if (s == null) throw new RuntimeException("Unexpected end of input");
            return Long.parseLong(s);
        }
    }
}

import java.io.*;
import java.util.*;

public class Main {

    // Color constants for readability and maintainability
    private static final char UNCOLORED = 'b';
    private static final char COLOR_A = 'a';
    private static final char COLOR_C = 'c';

    public static void main(String[] args) {
        new Main().run();
    }

    /**
     * Entry point for execution. Sets up I/O streams and delegates to the solver.
     */
    public void run() {
        FastScanner scanner = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out);
        try {
            solve(scanner, out);
        } catch (IOException e) {
            e.printStackTrace();
            System.exit(1);
        } finally {
            out.flush();
            out.close();
        }
    }

    /**
     * Core algorithm logic. Reads input, processes graph components, validates constraints, and prints result.
     *
     * @param scanner Fast input reader
     * @param out     Output writer
     * @throws IOException if input/output operations fail
     */
    private void solve(FastScanner scanner, PrintWriter out) throws IOException {
        int n = scanner.nextInt();
        int m = scanner.nextInt();

        // Adjacency matrix: true means connected, false means not connected
        boolean[][] isConnected = new boolean[n][n];
        for (boolean[] row : isConnected) {
            Arrays.fill(row, true);
        }

        for (int i = 0; i < m; i++) {
            int u = scanner.nextInt() - 1;
            int v = scanner.nextInt() - 1;
            isConnected[u][v] = isConnected[v][u] = false;
        }
        // Ensure no self-loops
        for (int i = 0; i < n; i++) {
            isConnected[i][i] = false;
        }

        // 'b' represents uncolored nodes
        char[] coloring = new char[n];
        Arrays.fill(coloring, UNCOLORED);

        int validComponentsCount = 0;

        // Process each connected component
        for (int i = 0; i < n; i++) {
            if (coloring[i] == UNCOLORED) {
                int componentSize = dfsColor(i, COLOR_A, isConnected, coloring);

                if (componentSize == -1) {
                    out.println("No");
                    return;
                }

                // If a component consists of a single node, revert it to uncolored
                if (componentSize == 1) {
                    coloring[i] = UNCOLORED;
                } else {
                    validComponentsCount++;
                }
            }
        }

        // Validation phase: Non-edges cannot connect COLOR_A and COLOR_C
        // Math.abs(color - color) == 2 checks for 'a' (97) and 'c' (99)
        if (validComponentsCount <= 1) {
            boolean hasViolation = false;
            for (int i = 0; i < n; i++) {
                for (int j = i + 1; j < n; j++) {
                    if (!isConnected[i][j]) {
                        if (Math.abs(coloring[i] - coloring[j]) == 2) {
                            hasViolation = true;
                            break;
                        }
                    }
                }
                if (hasViolation) break;
            }

            if (hasViolation) {
                out.println("No");
            } else {
                out.println("Yes");
                out.println(new String(coloring));
            }
        } else {
            out.println("No");
        }
    }

    /**
     * Recursive DFS to assign alternating colors (A/C) to a connected component.
     * Checks for bipartite coloring conflicts.
     *
     * @param node          Current node being visited
     * @param currentColor  Color to assign to the current node
     * @param isConnected   Adjacency matrix
     * @param coloring      Array tracking assigned colors
     * @return              Component size on success, -1 if coloring conflict detected
     */
    private int dfsColor(int node, char currentColor, boolean[][] isConnected, char[] coloring) {
        coloring[node] = currentColor;
        int size = 1;
        char expectedColor = (currentColor == COLOR_A) ? COLOR_C : COLOR_A;

        for (int neighbor = 0; neighbor < isConnected.length; neighbor++) {
            if (isConnected[node][neighbor]) {
                // Conflict: adjacent nodes cannot share the same color
                if (coloring[neighbor] == currentColor) {
                    return -1;
                }
                // Recurse only on uncolored neighbors
                if (coloring[neighbor] == UNCOLORED) {
                    int subSize = dfsColor(neighbor, expectedColor, isConnected, coloring);
                    if (subSize == -1) {
                        return -1;
                    }
                    size += subSize;
                }
                // If neighbor is already colored with expectedColor, it's valid; skip
            }
        }
        return size;
    }

    /**
     * High-performance input scanner for competitive programming / fast I/O.
     */
    private static class FastScanner {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastScanner(InputStream stream) {
            this.reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String nextToken() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                String line = reader.readLine();
                if (line == null) {
                    throw new EOFException("Unexpected end of input");
                }
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(nextToken());
        }
    }
}

import java.io.*;
import java.util.*;

public class GraphPartitionSolver {

    private static final String OUTPUT_YES = "Yes";
    private static final String OUTPUT_NO = "No";

    public static void main(String[] args) {
        // Use try-with-resources for automatic and safe resource cleanup
        try (FastScanner in = new FastScanner(System.in);
             FastWriter out = new FastWriter(System.out)) {
            solve(in, out);
        } catch (IOException e) {
            System.err.println("I/O error occurred: " + e.getMessage());
            e.printStackTrace();
        }
    }

    /**
     * Orchestrates the graph reading, partitioning, validation, and output generation.
     */
    private static void solve(FastScanner in, FastWriter out) {
        int V = in.nextInt();
        int E = in.nextInt();

        // Handle trivial cases with no edges
        if (E == 0) {
            if (V == 1 || V == 2) {
                out.println(OUTPUT_YES);
                out.print(V == 1 ? "a" : "ac");
            } else {
                out.print(OUTPUT_NO);
            }
            return;
        }

        List<Set<Integer>> adj = buildGraph(V, E, in);
        Set<Integer> setA = new HashSet<>();
        Set<Integer> setB = new HashSet<>();
        Set<Integer> setC = new HashSet<>();

        partitionVertices(V, adj, setA, setB, setC);

        if (!validatePartition(V, adj, setA, setB, setC)) {
            out.print(OUTPUT_NO);
            return;
        }

        out.println(OUTPUT_YES);
        out.print(buildResultString(V, setA, setB, setC));
    }

    /**
     * Reads graph input and builds an adjacency list.
     * Uses ArrayList of Sets instead of a generic array for type safety.
     */
    private static List<Set<Integer>> buildGraph(int V, int E, FastScanner in) {
        List<Set<Integer>> adj = new ArrayList<>(V + 1);
        for (int i = 0; i <= V; i++) {
            adj.add(new HashSet<>());
        }
        for (int i = 0; i < E; i++) {
            int u = in.nextInt();
            int v = in.nextInt();
            adj.get(u).add(v);
            adj.get(v).add(u);
        }
        return adj;
    }

    /**
     * Partitions vertices into sets A, B, and C based on degree and connectivity rules.
     */
    private static void partitionVertices(int V, List<Set<Integer>> adj,
                                          Set<Integer> setA, Set<Integer> setB, Set<Integer> setC) {
        // Set B: vertices connected to all other vertices
        for (int i = 1; i <= V; i++) {
            if (adj.get(i).size() == V - 1) {
                setB.add(i);
            }
        }

        // Set A: pick the first non-B vertex and add all its non-B neighbors
        for (int i = 1; i <= V; i++) {
            if (!setB.contains(i)) {
                setA.add(i);
                for (int neighbor : adj.get(i)) {
                    if (!setB.contains(neighbor)) {
                        setA.add(neighbor);
                    }
                }
                break;
            }
        }

        // Set C: remaining vertices
        for (int i = 1; i <= V; i++) {
            if (!setA.contains(i) && !setB.contains(i)) {
                setC.add(i);
            }
        }
    }

    /**
     * Validates the partition against degree and connectivity constraints.
     * Consolidated into a single pass using an assignment array for O(1) lookups.
     */
    private static boolean validatePartition(int V, List<Set<Integer>> adj,
                                             Set<Integer> setA, Set<Integer> setB, Set<Integer> setC) {
        int sizeA = setA.size();
        int sizeB = setB.size();
        int sizeC = setC.size();

        // Map vertex -> set type: 0=none, 1=A, 2=B, 3=C
        int[] vertexSet = new int[V + 1];
        for (int v : setA) vertexSet[v] = 1;
        for (int v : setB) vertexSet[v] = 2;
        for (int v : setC) vertexSet[v] = 3;

        for (int v = 1; v <= V; v++) {
            int type = vertexSet[v];
            if (type == 0) continue; // Should not occur if partition covers all vertices

            int expectedDegree = 0;
            boolean hasForbiddenNeighbor = false;

            switch (type) {
                case 1: // Set A
                    expectedDegree = sizeA + sizeB - 1;
                    for (int neighbor : adj.get(v)) {
                        if (vertexSet[neighbor] == 3) {
                            hasForbiddenNeighbor = true;
                            break;
                        }
                        if (vertexSet[neighbor] == 1 || vertexSet[neighbor] == 2) {
                            expectedDegree--;
                        }
                    }
                    break;
                case 2: // Set B
                    expectedDegree = sizeA + sizeB + sizeC - 1;
                    for (int neighbor : adj.get(v)) {
                        if (vertexSet[neighbor] == 1 || vertexSet[neighbor] == 2 || vertexSet[neighbor] == 3) {
                            expectedDegree--;
                        }
                    }
                    break;
                case 3: // Set C
                    expectedDegree = sizeC + sizeB - 1;
                    for (int neighbor : adj.get(v)) {
                        if (vertexSet[neighbor] == 1) {
                            hasForbiddenNeighbor = true;
                            break;
                        }
                        if (vertexSet[neighbor] == 3 || vertexSet[neighbor] == 2) {
                            expectedDegree--;
                        }
                    }
                    break;
            }

            if (hasForbiddenNeighbor || expectedDegree != 0) {
                return false;
            }
        }
        return true;
    }

    /**
     * Constructs the output character array based on vertex assignments.
     */
    private static String buildResultString(int V, Set<Integer> setA, Set<Integer> setB, Set<Integer> setC) {
        char[] result = new char[V];
        for (int v : setA) result[v - 1] = 'a';
        for (int v : setB) result[v - 1] = 'b';
        for (int v : setC) result[v - 1] = 'c';
        return new String(result);
    }

    /**
     * High-performance input reader for competitive programming / large inputs.
     */
    static class FastScanner implements AutoCloseable {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastScanner(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input", e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }

        public double nextDouble() {
            return Double.parseDouble(next());
        }

        @Override
        public void close() {
            try {
                reader.close();
            } catch (IOException e) {
                throw new RuntimeException("Failed to close scanner", e);
            }
        }
    }

    /**
     * High-performance output writer for competitive programming / large outputs.
     */
    static class FastWriter implements AutoCloseable {
        private final BufferedWriter writer;

        public FastWriter(OutputStream stream) {
            writer = new BufferedWriter(new OutputStreamWriter(stream));
        }

        public void print(int i) {
            print(Integer.toString(i));
        }

        public void print(long i) {
            print(Long.toString(i));
        }

        public void print(double i) {
            print(Double.toString(i));
        }

        public void print(boolean i) {
            print(Boolean.toString(i));
        }

        public void print(char c) {
            try {
                writer.write(c);
            } catch (IOException e) {
                throw new RuntimeException("Failed to write output", e);
            }
        }

        public void print(String s) {
            try {
                writer.write(s);
            } catch (IOException e) {
                throw new RuntimeException("Failed to write output", e);
            }
        }

        public void println() {
            try {
                writer.newLine();
            } catch (IOException e) {
                throw new RuntimeException("Failed to write output", e);
            }
        }

        public void println(String s) {
            print(s);
            println();
        }

        public void println(int i) {
            print(i);
            println();
        }

        public void println(long i) {
            print(i);
            println();
        }

        public void println(double i) {
            print(i);
            println();
        }

        public void println(boolean i) {
            print(i);
            println();
        }

        @Override
        public void close() {
            try {
                writer.close();
            } catch (IOException e) {
                throw new RuntimeException("Failed to close writer", e);
            }
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.Arrays;
import java.util.StringTokenizer;

/**
 * Refactored solution for Codeforces problem.
 * Improvements:
 * 1. Encapsulated Fast I/O logic into a dedicated inner class.
 * 2. Used descriptive variable names (e.g., hasEdge instead of am, colors instead of str).
 * 3. Removed static state where possible to improve testability and readability.
 * 4. Simplified complex nested if-else blocks in the validation phase.
 * 5. Added comments to explain the algorithmic steps.
 */
public class Codeforces {

    /**
     * Helper class for fast input reading.
     * Replaces the fragile static BufferedReader/StringTokenizer logic.
     */
    static class FastScanner {
        BufferedReader br;
        StringTokenizer st;

        public FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    e.printStackTrace();
                    return null;
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            String s = next();
            return s == null ? 0 : Integer.parseInt(s);
        }
    }

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner();
        try {
            solve(scanner);
        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    private static void solve(FastScanner scanner) {
        // Read n (number of nodes) and m (number of edges to remove)
        String nStr = scanner.next();
        if (nStr == null) return;
        int n = Integer.parseInt(nStr);
        int m = scanner.nextInt();

        // Adjacency matrix: hasEdge[i][j] is true if an edge exists between i and j.
        // The problem starts with a complete graph and removes m edges.
        boolean[][] hasEdge = new boolean[n][n];
        for (int i = 0; i < n; i++) {
            Arrays.fill(hasEdge[i], true);
            hasEdge[i][i] = false; // No self-loops
        }

        // Read m edges and remove them from the graph (set to false)
        for (int i = 0; i < m; i++) {
            int u = scanner.nextInt() - 1; // Convert to 0-indexed
            int v = scanner.nextInt() - 1; // Convert to 0-indexed
            if (u >= 0 && u < n && v >= 0 && v < n) {
                hasEdge[u][v] = false;
                hasEdge[v][u] = false;
            }
        }

        // Array to store colors: 'a', 'c', or 'b' (unassigned)
        char[] colors = new char[n];
        Arrays.fill(colors, 'b');

        boolean firstEdgeProcessed = false;

        // First Pass: Assign colors based on edges
        // We iterate through all pairs to propagate colors.
        // If an edge exists, the connected nodes must have different colors ('a' and 'c').
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (hasEdge[i][j]) {
                    if (!firstEdgeProcessed) {
                        // Assign initial colors to the first edge found
                        colors[i] = 'a';
                        colors[j] = 'c';
                        firstEdgeProcessed = true;
                    } else {
                        // Check consistency: if both nodes are colored, they must differ
                        if (colors[i] == colors[j]) {
                            System.out.println("No");
                            return;
                        }

                        // Propagate colors if one node is unassigned ('b')
                        // Logic: If one node is 'a', the other must be 'c', and vice versa.
                        if (colors[i] == 'a') {
                            colors[j] = 'c';
                        } else if (colors[i] == 'c') {
                            colors[j] = 'a';
                        } else if (colors[j] == 'a') {
                            colors[i] = 'c';
                        } else if (colors[j] == 'c') {
                            colors[i] = 'a';
                        }
                    }
                }
            }
        }

        // Second Pass: Validate the coloring against the graph structure
        // Conditions for a valid solution:
        // 1. If an edge exists, endpoints cannot be 'b' and must have different colors.
        // 2. If an edge does not exist, endpoints cannot have different colors (one 'a', one 'c').
        //    (Note: 'b' nodes with no edges are allowed, same color nodes with no edges allowed).

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                boolean edgeExists = hasEdge[i][j];
                char colorI = colors[i];
                char colorJ = colors[j];

                if (colorI == 'b' || colorJ == 'b') {
                    // If any node is unassigned, it cannot have any edges connected to it.
                    if (edgeExists) {
                        System.out.println("No");
                        return;
                    }
                } else {
                    // Both nodes are assigned colors ('a' or 'c')
                    if (colorI == colorJ) {
                        // Same color nodes cannot be connected by an edge.
                        if (edgeExists) {
                            System.out.println("No");
                            return;
                        }
                    } else {
                        // Different color nodes MUST be connected by an edge.
                        if (!edgeExists) {
                            System.out.println("No");
                            return;
                        }
                    }
                }
            }
        }

        // If all checks pass
        System.out.println("Yes");
        StringBuilder sb = new StringBuilder();
        for (char c : colors) {
            sb.append(c);
        }
        System.out.println(sb.toString());
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

public class C624 {

    public static void main(String[] args) throws IOException {
        // Use try-with-resources for automatic resource management
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            String[] firstLine = br.readLine().trim().split("\\s+");
            int n = Integer.parseInt(firstLine[0]);
            int m = Integer.parseInt(firstLine[1]);

            boolean[][] adj = new boolean[n + 1][n + 1];
            int[] degree = new int[n + 1];

            initializeGraph(n, adj);
            buildGraph(m, br, adj, degree);

            List<Integer> bVertices = findDominantVertices(n, degree);
            int nonBVertex = findNonDominantVertex(n, degree);
            Map<String, List<Integer>> groups = classifyVertices(n, adj, degree, nonBVertex);

            if (!validate(groups, adj)) {
                System.out.println("No");
                return;
            }

            generateOutput(n, bVertices, groups);
        }
    }

    private static void initializeGraph(int n, boolean[][] adj) {
        for (int i = 1; i <= n; i++) {
            adj[i][i] = true;
        }
    }

    private static void buildGraph(int m, BufferedReader br, boolean[][] adj, int[] degree) throws IOException {
        for (int i = 0; i < m; i++) {
            String[] edge = br.readLine().trim().split("\\s+");
            int u = Integer.parseInt(edge[0]);
            int v = Integer.parseInt(edge[1]);

            // Avoid double-counting duplicate edges
            if (!adj[u][v]) {
                adj[u][v] = adj[v][u] = true;
                degree[u]++;
                degree[v]++;
            }
        }
    }

    private static List<Integer> findDominantVertices(int n, int[] degree) {
        List<Integer> dominant = new ArrayList<>();
        for (int i = 1; i <= n; i++) {
            if (degree[i] == n - 1) {
                dominant.add(i);
            }
        }
        return dominant;
    }

    private static int findNonDominantVertex(int n, int[] degree) {
        for (int i = 1; i <= n; i++) {
            if (degree[i] != n - 1) {
                return i;
            }
        }
        return -1;
    }

    private static Map<String, List<Integer>> classifyVertices(int n, boolean[][] adj, int[] degree, int nonBVertex) {
        // LinkedHashMap preserves insertion order (1 to n) for deterministic output
        Map<String, List<Integer>> groups = new LinkedHashMap<>();
        if (nonBVertex != -1) {
            for (int i = 1; i <= n; i++) {
                if (degree[i] == n - 1) continue;
                // Group by (degree, connection_to_non_b)
                String key = degree[i] + "," + (adj[i][nonBVertex] ? 1 : 0);
                groups.computeIfAbsent(key, k -> new ArrayList<>()).add(i);
            }
        }
        return groups;
    }

    private static boolean validate(Map<String, List<Integer>> groups, boolean[][] adj) {
        if (groups.size() > 2) {
            return false;
        }

        // Verify each group forms a complete subgraph (clique)
        for (List<Integer> group : groups.values()) {
            for (int i = 0; i < group.size(); i++) {
                for (int j = i + 1; j < group.size(); j++) {
                    if (!adj[group.get(i)][group.get(j)]) {
                        return false;
                    }
                }
            }
        }
        return true;
    }

    private static void generateOutput(int n, List<Integer> bVertices, Map<String, List<Integer>> groups) {
        char[] result = new char[n];
        Arrays.fill(result, '?');

        for (int b : bVertices) {
            result[b - 1] = 'b';
        }

        List<List<Integer>> groupList = new ArrayList<>(groups.values());
        if (groupList.size() >= 1) {
            for (int v : groupList.get(0)) {
                result[v - 1] = 'a';
            }
        }
        if (groupList.size() >= 2) {
            for (int v : groupList.get(1)) {
                result[v - 1] = 'c';
            }
        }

        System.out.println("Yes");
        System.out.println(new String(result));
    }
}

import java.util.*;

/**
 * Validates if a graph can be partitioned into two cliques (A and C)
 * based on specific labeling rules, and verifies edge constraints.
 * 
 * Refactoring improvements:
 * - Meaningful class and method names following Java conventions
 * - Separation of concerns (graph building, labeling, validation)
 * - Efficient data structures (HashSet for O(1) adjacency lookups)
 * - Eliminated magic numbers/characters via constants
 * - Proper resource management with try-with-resources
 * - StringBuilder for efficient string concatenation
 * - Clear, self-documenting variable names
 */
public class GraphPartitionValidator {

    private static final char UNMARKED = 'x';
    private static final char LABEL_B = 'b';
    private static final char LABEL_A = 'a';
    private static final char LABEL_C = 'c';

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            if (!scanner.hasNextInt()) {
                return;
            }

            int n = scanner.nextInt();
            int m = scanner.nextInt();

            List<Set<Integer>> adjacencyList = buildGraph(n, m, scanner);
            char[] nodeLabels = assignNodeLabels(n, adjacencyList);
            List<Integer> groupA = collectGroupA(nodeLabels, adjacencyList);
            List<Integer> groupC = collectGroupC(nodeLabels);

            if (!isClique(groupA, adjacencyList) || !isClique(groupC, adjacencyList)) {
                System.out.println("No");
                return;
            }

            StringBuilder resultLabelString = new StringBuilder();
            boolean isValid = true;

            for (int i = 0; i < n; i++) {
                resultLabelString.append(nodeLabels[i]);
                for (int neighbor : adjacencyList.get(i)) {
                    if (!isValidEdge(nodeLabels[i], nodeLabels[neighbor])) {
                        isValid = false;
                        break;
                    }
                }
                if (!isValid) {
                    break;
                }
            }

            if (isValid) {
                System.out.println("Yes\n" + resultLabelString);
            } else {
                System.out.println("No");
            }
        }
    }

    /**
     * Constructs an undirected graph using an adjacency list.
     */
    private static List<Set<Integer>> buildGraph(int n, int m, Scanner scanner) {
        List<Set<Integer>> adj = new ArrayList<>(n);
        for (int i = 0; i < n; i++) {
            adj.add(new HashSet<>());
        }
        for (int i = 0; i < m; i++) {
            int u = scanner.nextInt() - 1;
            int v = scanner.nextInt() - 1;
            adj.get(u).add(v);
            adj.get(v).add(u);
        }
        return adj;
    }

    /**
     * Assigns labels to nodes based on connectivity rules.
     */
    private static char[] assignNodeLabels(int n, List<Set<Integer>> adj) {
        char[] labels = new char[n];
        Arrays.fill(labels, UNMARKED);

        // Fully connected nodes are labeled 'b'
        for (int i = 0; i < n; i++) {
            if (adj.get(i).size() == n - 1) {
                labels[i] = LABEL_B;
            }
        }

        // Identify the first unmarked node
        int firstUnmarked = -1;
        for (int i = 0; i < n; i++) {
            if (labels[i] == UNMARKED) {
                firstUnmarked = i;
                break;
            }
        }

        // Label the first unmarked node and its unmarked neighbors as 'a'
        if (firstUnmarked != -1) {
            labels[firstUnmarked] = LABEL_A;
            for (int neighbor : adj.get(firstUnmarked)) {
                if (labels[neighbor] == UNMARKED) {
                    labels[neighbor] = LABEL_A;
                }
            }
        }

        // Label remaining unmarked nodes as 'c'
        for (int i = 0; i < n; i++) {
            if (labels[i] == UNMARKED) {
                labels[i] = LABEL_C;
            }
        }
        return labels;
    }

    /**
     * Collects nodes belonging to group A.
     */
    private static List<Integer> collectGroupA(char[] labels, List<Set<Integer>> adj) {
        List<Integer> groupA = new ArrayList<>();
        int firstUnmarked = -1;
        for (int i = 0; i < labels.length; i++) {
            if (labels[i] == UNMARKED) {
                firstUnmarked = i;
                break;
            }
        }

        if (firstUnmarked != -1) {
            groupA.add(firstUnmarked);
            for (int neighbor : adj.get(firstUnmarked)) {
                if (labels[neighbor] == LABEL_A) {
                    groupA.add(neighbor);
                }
            }
        }
        return groupA;
    }

    /**
     * Collects nodes belonging to group C.
     */
    private static List<Integer> collectGroupC(char[] labels) {
        List<Integer> groupC = new ArrayList<>();
        for (int i = 0; i < labels.length; i++) {
            if (labels[i] == LABEL_C) {
                groupC.add(i);
            }
        }
        return groupC;
    }

    /**
     * Verifies if a list of nodes forms a complete subgraph (clique).
     */
    private static boolean isClique(List<Integer> nodes, List<Set<Integer>> adj) {
        for (int i = 0; i < nodes.size(); i++) {
            for (int j = i + 1; j < nodes.size(); j++) {
                if (!adj.get(nodes.get(i)).contains(nodes.get(j))) {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Validates edge constraints between two labeled nodes.
     * Returns false only if one node is 'a' and the other is 'c'.
     */
    private static boolean isValidEdge(char label1, char label2) {
        return !(label1 == LABEL_A && label2 == LABEL_C);
    }
}

import java.io.*;
import java.util.*;

public class CF624C_2 {
    public static void main(String[] args) {
        FastReader in = new FastReader(System.in);
        PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out));

        try {
            int n = in.nextInt();
            int m = in.nextInt();

            // 1. Build adjacency matrix
            int[][] graph = new int[n + 1][n + 1];
            for (int i = 0; i < m; i++) {
                int u = in.nextInt();
                int v = in.nextInt();
                graph[u][v] = graph[v][u] = 1;
            }

            // 2. Initialize coloring and calculate degrees
            char[] coloring = new char[n + 1];
            int[] degree = new int[n + 1];

            for (int i = 1; i <= n; i++) {
                for (int j = 1; j <= n; j++) {
                    if (i != j && graph[i][j] == 1) {
                        degree[i]++;
                    }
                }
                // Mark universal nodes (connected to all others) as 'b'
                if (degree[i] == n - 1) {
                    coloring[i] = 'b';
                }
            }

            boolean[] visited = new boolean[n + 1];
            int componentCounter = 0;

            // 3. First pass: color components starting from 'b' nodes
            for (int i = 1; i <= n; i++) {
                if (!visited[i] && coloring[i] == 'b') {
                    componentCounter++;
                    dfs(i, n, graph, coloring, visited, (componentCounter % 2 == 0) ? 'c' : 'a');
                }
            }

            // 4. Second pass: color remaining unvisited nodes
            for (int i = 1; i <= n; i++) {
                if (!visited[i]) {
                    componentCounter++;
                    dfs(i, n, graph, coloring, visited, (componentCounter % 2 == 0) ? 'c' : 'a');
                }
            }

            // 5. Validate the resulting coloring
            boolean isValid = validateColoring(n, graph, coloring);

            if (!isValid) {
                out.println("No");
            } else {
                out.println("Yes");
                for (int i = 1; i <= n; i++) {
                    out.print(coloring[i]);
                }
                out.println();
            }
        } catch (Exception e) {
            // Graceful failure handling for unexpected I/O or parsing errors
            e.printStackTrace();
        } finally {
            out.flush();
            out.close();
        }
    }

    /**
     * Validates the coloring scheme based on problem constraints:
     * - 'a' nodes must be connected to all 'a' and 'b' nodes.
     * - 'c' nodes must be connected to all 'b' and 'c' nodes.
     */
    private static boolean validateColoring(int n, int[][] graph, char[] coloring) {
        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= n; j++) {
                if (i == j) continue;

                if (coloring[i] == 'a' && (coloring[j] == 'a' || coloring[j] == 'b')) {
                    if (graph[i][j] == 0) return false;
                } else if (coloring[i] == 'c' && (coloring[j] == 'b' || coloring[j] == 'c')) {
                    if (graph[i][j] == 0) return false;
                }
            }
        }
        return true;
    }

    /**
     * Depth-First Search to propagate colors to unvisited neighbors.
     * Alternates between 'a' and 'c' for neighbors of 'b' nodes, 
     * otherwise propagates the current component's color.
     */
    private static void dfs(int node, int n, int[][] graph, char[] coloring, 
                            boolean[] visited, char currentColor) {
        visited[node] = true;
        if (coloring[node] == 0) {
            coloring[node] = currentColor;
        }

        char colorA = 'a';
        char colorB = 'c';
        int neighborIndex = 0;

        for (int neighbor = 1; neighbor <= n; neighbor++) {
            if (graph[node][neighbor] == 1 && !visited[neighbor] && coloring[neighbor] == 0) {
                char assignedColor;
                if (coloring[node] == 'b') {
                    // Alternate colors for neighbors of universal nodes
                    assignedColor = (neighborIndex % 2 == 0) ? colorA : colorB;
                } else {
                    // Propagate the current component's color
                    assignedColor = currentColor;
                }

                coloring[neighbor] = assignedColor;
                dfs(neighbor, n, graph, coloring, visited, currentColor);
                neighborIndex++;
            }
        }
    }

    /**
     * High-performance input reader for competitive programming contexts.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input", e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            String token = next();
            return token == null ? 0 : Integer.parseInt(token);
        }
    }
}

import java.util.Scanner;
import java.util.Arrays;

/**
 * Refactored version of the original C624 program.
 * 
 * This program analyzes a graph to determine if a specific coloring scheme exists
 * based on connectivity rules. It identifies universal nodes, assigns colors to
 * cliques and independent sets, and validates the solution.
 */
public class GraphColoringSolver {

    // Constants representing node colors for better readability
    private static final char COLOR_UNIVERSAL = 'b';
    private static final char COLOR_CLIQUE = 'a';
    private static final char COLOR_INDEPENDENT = 'c';
    private static final char COLOR_UNASSIGNED = 'z';

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        // Read number of nodes (n) and edges (m)
        if (!scanner.hasNextInt()) {
            return;
        }
        int n = scanner.nextInt();
        int m = scanner.nextInt();

        // Build the graph adjacency matrix
        boolean[][] adjacencyMatrix = buildGraph(n, m, scanner);

        // Determine the color assignment for each node
        char[] coloring = determineColoring(n, adjacencyMatrix);

        // Validate if the coloring satisfies the constraints
        boolean isValid = validateColoring(n, adjacencyMatrix, coloring);

        // Output the result
        printResult(isValid, coloring);

        scanner.close();
    }

    /**
     * Constructs the adjacency matrix from input.
     * Inputs are 1-based, converted to 0-based indexing.
     */
    private static boolean[][] buildGraph(int n, int m, Scanner scanner) {
        boolean[][] matrix = new boolean[n][n];

        for (int i = 0; i < m; i++) {
            int u = scanner.nextInt() - 1;
            int v = scanner.nextInt() - 1;

            // Basic bounds check to prevent exceptions
            if (u >= 0 && u < n && v >= 0 && v < n) {
                matrix[u][v] = true;
                matrix[v][u] = true;
            }
        }

        // Mark self-loops as true (reflexive property)
        for (int i = 0; i < n; i++) {
            matrix[i][i] = true;
        }

        return matrix;
    }

    /**
     * Assigns colors to nodes based on connectivity.
     * 1. Nodes connected to all others are 'b' (Universal).
     * 2. The first non-'b' node becomes 'a' (Pivot).
     * 3. Nodes connected to Pivot become 'a'.
     * 4. Nodes not connected to Pivot become 'c'.
     */
    private static char[] determineColoring(int n, boolean[][] adj) {
        char[] result = new char[n];
        Arrays.fill(result, COLOR_UNASSIGNED);

        // Step 1: Identify Universal Nodes (connected to all other nodes)
        for (int i = 0; i < n; i++) {
            boolean isUniversal = true;
            for (int j = 0; j < n; j++) {
                if (!adj[i][j]) {
                    isUniversal = false;
                    break;
                }
            }
            if (isUniversal) {
                result[i] = COLOR_UNIVERSAL;
            }
        }

        // Step 2: Find the first non-universal node (Pivot)
        int pivotIndex = -1;
        for (int i = 0; i < n; i++) {
            if (result[i] != COLOR_UNIVERSAL) {
                pivotIndex = i;
                break;
            }
        }

        // Step 3: Assign colors relative to the Pivot
        if (pivotIndex != -1) {
            result[pivotIndex] = COLOR_CLIQUE;
            for (int j = 0; j < n; j++) {
                // Skip the pivot itself and already colored universal nodes
                if (j == pivotIndex || result[j] == COLOR_UNIVERSAL) {
                    continue;
                }

                // If connected to pivot, it's part of the clique ('a')
                // If not connected, it's in the independent set ('c')
                if (adj[pivotIndex][j]) {
                    result[j] = COLOR_CLIQUE;
                } else {
                    result[j] = COLOR_INDEPENDENT;
                }
            }
        }

        return result;
    }

    /**
     * Validates the coloring against the problem constraints.
     * Constraints apply to pairs of non-universal nodes (i, j):
     * - If connected, they must have the same color.
     * - If not connected, they must have different colors.
     */
    private static boolean validateColoring(int n, boolean[][] adj, char[] coloring) {
        for (int i = 0; i < n; i++) {
            // Universal nodes are excluded from this specific validation check
            if (coloring[i] == COLOR_UNIVERSAL) {
                continue;
            }

            for (int j = 0; j < n; j++) {
                if (coloring[j] == COLOR_UNIVERSAL) {
                    continue;
                }

                boolean isConnected = adj[i][j];
                boolean sameColor = (coloring[i] == coloring[j]);

                // Constraint: Connected nodes must share the same color
                if (isConnected && !sameColor) {
                    return false;
                }

                // Constraint: Disconnected nodes must have different colors
                if (!isConnected && sameColor) {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Prints the final result to standard output.
     */
    private static void printResult(boolean isValid, char[] coloring) {
        if (isValid) {
            System.out.println("Yes");
            System.out.println(new String(coloring).trim());
        } else {
            System.out.println("No");
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.OutputStream;
import java.io.PrintWriter;
import java.util.StringTokenizer;

/**
 * Refactored solution for the graph coloring problem.
 * 
 * Improvements:
 * 1. Readability: Extracted complex logic into helper methods and used descriptive variable names.
 * 2. Maintainability: Replaced magic numbers (1, 2, 3) with named constants for colors.
 * 3. Structure: Separated input reading, logic processing, and output generation.
 * 4. Performance: Optimized validation loop to iterate only necessary pairs.
 * 5. Robustness: Added basic EOF handling in InputReader and removed unused imports.
 */
public class Main {

    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);

        Solver solver = new Solver();
        solver.solve(in, out);

        out.close();
    }

    static class Solver {
        // Named constants for colors to replace magic numbers
        private static final int COLOR_A = 1;
        private static final int COLOR_B = 2;
        private static final int COLOR_C = 3;

        public void solve(InputReader in, PrintWriter out) {
            int n = in.nextInt();
            int m = in.nextInt();

            // Adjacency matrix to store graph connections
            int[][] adjacencyMatrix = new int[n][n];
            for (int i = 0; i < m; i++) {
                int u = in.nextInt() - 1;
                int v = in.nextInt() - 1;
                adjacencyMatrix[u][v] = adjacencyMatrix[v][u] = 1;
            }

            int[] nodeColors = new int[n];

            // Process non-edges (pairs of nodes not connected by an edge)
            // Constraints are applied to non-edges to ensure valid coloring
            for (int i = 0; i < n; i++) {
                for (int j = i + 1; j < n; j++) {
                    if (adjacencyMatrix[i][j] == 0) {
                        if (!assignColorsForNonEdge(nodeColors, i, j)) {
                            out.println("No");
                            return;
                        }
                    }
                }
            }

            // Fill any uncolored nodes with COLOR_B
            for (int i = 0; i < n; i++) {
                if (nodeColors[i] == 0) {
                    nodeColors[i] = COLOR_B;
                }
            }

            // Validate edges: connected nodes must have color difference <= 1
            for (int i = 0; i < n; i++) {
                for (int j = i + 1; j < n; j++) {
                    if (adjacencyMatrix[i][j] == 1) {
                        if (Math.abs(nodeColors[i] - nodeColors[j]) > 1) {
                            out.println("No");
                            return;
                        }
                    }
                }
            }

            // Output result
            out.println("Yes");
            StringBuilder sb = new StringBuilder();
            for (int color : nodeColors) {
                if (color == COLOR_A) sb.append("a");
                else if (color == COLOR_B) sb.append("b");
                else sb.append("c");
            }
            out.println(sb.toString());
        }

        /**
         * Assigns colors to a pair of non-adjacent nodes based on specific constraints.
         * 
         * Constraints logic:
         * - Non-adjacent nodes should ideally be colored A and C (distance 2).
         * - If one is colored B, the other cannot be colored (failure).
         * - If both are colored, they must be far apart (distance > 1).
         */
        private boolean assignColorsForNonEdge(int[] colors, int i, int j) {
            int c1 = colors[i];
            int c2 = colors[j];

            if (c1 == 0 && c2 == 0) {
                // Both uncolored: assign A and C
                colors[i] = COLOR_A;
                colors[j] = COLOR_C;
                return true;
            } else if (c1 == 0) {
                // i uncolored, j colored
                if (c2 == COLOR_B) return false; // Cannot place neighbor of B
                colors[i] = (c2 == COLOR_A) ? COLOR_C : COLOR_A;
                return true;
            } else if (c2 == 0) {
                // j uncolored, i colored
                if (c1 == COLOR_B) return false; // Cannot place neighbor of B
                colors[j] = (c1 == COLOR_A) ? COLOR_C : COLOR_A;
                return true;
            } else {
                // Both colored: check distance constraint
                return Math.abs(c1 - c2) > 1;
            }
        }
    }

    /**
     * Fast Input Reader for competitive programming.
     */
    static class InputReader {
        public BufferedReader reader;
        public StringTokenizer tokenizer;

        public InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            String s = next();
            if (s == null) throw new RuntimeException("End of input");
            return Integer.parseInt(s);
        }

        public long nextLong() {
            String s = next();
            if (s == null) throw new RuntimeException("End of input");
            return Long.parseLong(s);
        }

        public double nextDouble() {
            String s = next();
            if (s == null) throw new RuntimeException("End of input");
            return Double.parseDouble(s);
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Solves a graph partitioning problem by assigning node types based on adjacency constraints.
 * Refactored for maintainability, readability, and robustness.
 */
public class GraphPartitionSolver {

    // Named constants replace magic numbers
    private static final int TYPE_NONE = 0;
    private static final int TYPE_A = 1;
    private static final int TYPE_B = 2;
    private static final int TYPE_C = 4;

    public static void main(String[] args) {
        // Debug mode can be enabled via command line argument or changed here
        boolean debugMode = args.length > 0 && "true".equalsIgnoreCase(args[0]);
        new GraphPartitionSolver().run(debugMode);
    }

    /**
     * Orchestrates input setup, execution, and output cleanup.
     */
    public void run(boolean debugMode) {
        InputStream inputStream = debugMode ? createDebugInputStream() : System.in;

        try (FastScanner in = new FastScanner(inputStream);
             PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out))) {

            solve(in, out);
            out.flush();
        } catch (Exception e) {
            System.err.println("Execution failed: " + e.getMessage());
            e.printStackTrace();
        }
    }

    private InputStream createDebugInputStream() {
        String debugFilePath = "src/T";
        try {
            System.out.println("FILE_INPUT!");
            return new FileInputStream(debugFilePath);
        } catch (FileNotFoundException e) {
            System.err.println("Debug file not found: " + debugFilePath + ". Falling back to System.in.");
            return System.in;
        }
    }

    /**
     * Core logic: reads graph, assigns types, and prints result.
     */
    public void solve(FastScanner in, PrintWriter out) {
        int n = in.nextInt();
        int m = in.nextInt();

        boolean[][] adjacencyMatrix = new boolean[n][n];
        for (int i = 0; i < m; i++) {
            int u = in.nextInt() - 1;
            int v = in.nextInt() - 1;
            adjacencyMatrix[u][v] = adjacencyMatrix[v][u] = true;
        }

        int[] assignment = new int[n];
        boolean isPossible = true;

        // Pass 1: Assign TYPE_B to nodes with degree n-1 (fully connected hubs)
        for (int i = 0; i < n; i++) {
            int degree = 0;
            for (int j = 0; j < n; j++) {
                if (i != j && adjacencyMatrix[i][j]) {
                    degree++;
                }
            }
            if (degree == n - 1) {
                assignment[i] = TYPE_B;
            }
        }

        // Pass 2: Greedily assign TYPE_A or TYPE_C to remaining nodes
        for (int i = 0; i < n; i++) {
            if (assignment[i] != TYPE_NONE) {
                continue;
            }

            if (!tryAssign(assignment, adjacencyMatrix, i, TYPE_A, n)) {
                if (!tryAssign(assignment, adjacencyMatrix, i, TYPE_C, n)) {
                    isPossible = false;
                    break;
                }
            }
        }

        // Output results
        if (isPossible) {
            out.println("Yes");
            StringBuilder result = new StringBuilder(n);
            for (int type : assignment) {
                switch (type) {
                    case TYPE_A -> result.append('a');
                    case TYPE_B -> result.append('b');
                    case TYPE_C -> result.append('c');
                    default -> throw new IllegalStateException("Unexpected assignment type: " + type);
                }
            }
            out.println(result);
        } else {
            out.println("No");
        }
    }

    /**
     * Attempts to assign a type to a node. Validates against previously assigned nodes.
     * Rolls back the assignment if constraints are violated.
     */
    private boolean tryAssign(int[] assignment, boolean[][] adj, int node, int type, int n) {
        assignment[node] = type;
        boolean isValid = true;

        for (int j = 0; j < node; j++) {
            if (assignment[j] == TYPE_NONE) continue;
            if (!checkCompatibility(node, j, type, assignment[j], adj)) {
                isValid = false;
                break;
            }
        }

        if (!isValid) {
            assignment[node] = TYPE_NONE; // Rollback invalid assignment
        }
        return isValid;
    }

    /**
     * Validates compatibility between two nodes based on their types and adjacency.
     */
    private boolean checkCompatibility(int i, int j, int typeI, int typeJ, boolean[][] adj) {
        boolean isConnected = adj[i][j];

        if (isConnected) {
            // Connected nodes cannot be (A, C) or (C, A)
            if ((typeI == TYPE_A && typeJ == TYPE_C) ||
                (typeI == TYPE_C && typeJ == TYPE_A)) {
                return false;
            }
        } else {
            // Disconnected nodes cannot be (A, A), (A, B), (C, C), or (C, B)
            if ((typeI == TYPE_A && (typeJ == TYPE_A || typeJ == TYPE_B)) ||
                (typeI == TYPE_C && (typeJ == TYPE_C || typeJ == TYPE_B))) {
                return false;
            }
        }
        return true;
    }

    // --- Utility Methods (Preserved but cleaned up) ---

    private void printMap(int[][] matrix) {
        System.out.println("--------map display---------");
        for (int[] row : matrix) {
            for (int val : row) {
                System.out.printf("%3d ", val);
            }
            System.out.println();
        }
        System.out.println("----------------------------\n");
    }

    private void debugPrint(Object... objects) {
        System.out.println(Arrays.deepToString(objects));
    }

    /**
     * High-performance input scanner for competitive programming / large inputs.
     */
    public static class FastScanner {
        private final InputStream stream;
        private final byte[] buffer = new byte[1024];
        private int bufferIndex;
        private int bytesRead;

        public FastScanner(InputStream stream) {
            this.stream = stream;
            this.bufferIndex = 0;
            this.bytesRead = 0;
        }

        private int read() {
            if (bytesRead == -1) {
                throw new InputMismatchException();
            }
            if (bufferIndex >= bytesRead) {
                bufferIndex = 0;
                try {
                    bytesRead = stream.read(buffer);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (bytesRead <= 0) {
                    return -1;
                }
            }
            return buffer[bufferIndex++];
        }

        private boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        private boolean isEndline(int c) {
            return c == '\n' || c == '\r' || c == -1;
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public int[] nextIntArray(int n) {
            int[] array = new int[n];
            for (int i = 0; i < n; i++) {
                array[i] = nextInt();
            }
            return array;
        }

        public int[][] nextIntMap(int n, int m) {
            int[][] map = new int[n][m];
            for (int i = 0; i < n; i++) {
                map[i] = nextIntArray(m);
            }
            return map;
        }

        public long nextLong() {
            return Long.parseLong(next());
        }

        public long[] nextLongArray(int n) {
            long[] array = new long[n];
            for (int i = 0; i < n; i++) {
                array[i] = nextLong();
            }
            return array;
        }

        public long[][] nextLongMap(int n, int m) {
            long[][] map = new long[n][m];
            for (int i = 0; i < n; i++) {
                map[i] = nextLongArray(m);
            }
            return map;
        }

        public double nextDouble() {
            return Double.parseDouble(next());
        }

        public double[] nextDoubleArray(int n) {
            double[] array = new double[n];
            for (int i = 0; i < n; i++) {
                array[i] = nextDouble();
            }
            return array;
        }

        public double[][] nextDoubleMap(int n, int m) {
            double[][] map = new double[n][m];
            for (int i = 0; i < n; i++) {
                map[i] = nextDoubleArray(m);
            }
            return map;
        }

        public String next() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            if (c == -1) {
                throw new InputMismatchException();
            }
            StringBuilder res = new StringBuilder();
            do {
                res.appendCodePoint(c);
                c = read();
            } while (!isSpaceChar(c));
            return res.toString();
        }

        public String[] nextStringArray(int n) {
            String[] array = new String[n];
            for (int i = 0; i < n; i++) {
                array[i] = next();
            }
            return array;
        }

        public String nextLine() {
            int c = read();
            while (isEndline(c)) {
                c = read();
            }
            if (c == -1) {
                return "";
            }
            StringBuilder res = new StringBuilder();
            do {
                res.appendCodePoint(c);
                c = read();
            } while (!isEndline(c));
            return res.toString();
        }
    }
}

import java.io.BufferedInputStream;
import java.io.BufferedWriter;
import java.io.EOFException;
import java.io.IOException;
import java.io.InputStream;
import java.io.OutputStream;
import java.io.OutputStreamWriter;
import java.io.UncheckedIOException;
import java.util.Arrays;

public class Main {
    // Constant for thread stack size to prevent StackOverflowError on deep recursion
    private static final int THREAD_STACK_SIZE = 1 << 29; 

    public static void main(String[] args) {
        // Run solver in a dedicated thread with increased stack size
        Thread solverThread = new Thread(null, Main::runSolver, "GraphPartitionSolver", THREAD_STACK_SIZE);
        solverThread.start();
        try {
            solverThread.join();
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
            System.err.println("Solver thread was interrupted.");
        }
    }

    private static void runSolver() {
        FastScanner in = new FastScanner(System.in);
        // Use try-with-resources to ensure output buffer is flushed and stream closed
        try (FastPrinter out = new FastPrinter(System.out)) {
            GraphPartitionSolver solver = new GraphPartitionSolver();
            solver.solve(in, out);
        }
    }

    /**
     * Solves the graph partition problem.
     * Determines if the graph can be partitioned into three sets (A, B, C)
     * such that edges only exist between adjacent sets (A-B, B-C, A-A, B-B, C-C).
     */
    static class GraphPartitionSolver {
        public void solve(FastScanner in, FastPrinter out) {
            int n = in.readInt();
            int m = in.readInt();

            boolean[][] adj = new boolean[n][n];
            for (int i = 0; i < m; i++) {
                int u = in.readInt() - 1; // Convert to 0-based index
                int v = in.readInt() - 1;
                adj[u][v] = adj[v][u] = true;
            }

            // Find the first non-adjacent pair to serve as partition anchors
            int anchorA = -1;
            int anchorC = -1;
            outerLoop:
            for (int i = 0; i < n; i++) {
                for (int j = i + 1; j < n; j++) {
                    if (!adj[i][j]) {
                        anchorA = i;
                        anchorC = j;
                        break outerLoop;
                    }
                }
            }

            // If the graph is complete, all nodes can belong to partition A
            if (anchorA == -1) {
                out.println("Yes");
                for (int i = 0; i < n; i++) out.append('a');
                return;
            }

            // 0: Partition A, 1: Partition B, 2: Partition C
            int[] partition = new int[n];
            Arrays.fill(partition, -1);

            partition[anchorA] = 0;
            partition[anchorC] = 2;

            // Assign remaining nodes based on connectivity to anchors
            for (int i = 0; i < n; i++) {
                if (partition[i] != -1) continue;

                boolean connectedToA = adj[i][anchorA];
                boolean connectedToC = adj[i][anchorC];

                if (connectedToA && connectedToC) {
                    partition[i] = 1; // Must be in B
                } else if (connectedToA) {
                    partition[i] = 0; // Must be in A
                } else if (connectedToC) {
                    partition[i] = 2; // Must be in C
                } else {
                    // Node connected to neither anchor violates partition constraints
                    out.println("No");
                    return;
                }
            }

            // Validate all edges against the partition rules
            for (int i = 0; i < n; i++) {
                for (int j = i + 1; j < n; j++) {
                    int pi = partition[i];
                    int pj = partition[j];

                    // Edges are allowed within same set or between adjacent sets (diff <= 1)
                    boolean expectedEdge = Math.abs(pi - pj) <= 1;

                    if (adj[i][j] != expectedEdge) {
                        out.println("No");
                        return;
                    }
                }
            }

            out.println("Yes");
            for (int p : partition) {
                out.append((char) ('a' + p));
            }
        }
    }

    /**
     * High-performance input scanner for competitive programming.
     * Uses buffered reading to minimize I/O overhead.
     */
    static class FastScanner {
        private final BufferedInputStream in;
        private final byte[] buffer = new byte[1 << 13];
        private int bufferPointer = 0;
        private int bytesRead = 0;

        public FastScanner(InputStream in) {
            this.in = new BufferedInputStream(in);
        }

        private int read() throws IOException {
            if (bufferPointer == bytesRead) {
                bytesRead = in.read(buffer, 0, buffer.length);
                if (bytesRead == -1) {
                    return -1;
                }
                bufferPointer = 0;
            }
            return buffer[bufferPointer++] & 0xFF;
        }

        public int readInt() {
            int c = read();
            while (c <= 32) { // Skip whitespace
                if (c == -1) throw new EOFException();
                c = read();
            }

            boolean negative = false;
            if (c == '-') {
                negative = true;
                c = read();
            }

            int res = 0;
            while (c >= '0' && c <= '9') {
                res = res * 10 + (c - '0');
                c = read();
            }
            return negative ? -res : res;
        }
    }

    /**
     * High-performance output printer with buffering.
     * Implements Appendable for fluent API and AutoCloseable for resource management.
     */
    static class FastPrinter implements AutoCloseable, Appendable {
        private static final int BUFFER_SIZE = 1 << 13;
        private final BufferedWriter writer;
        private final StringBuilder buffer = new StringBuilder(BUFFER_SIZE);

        public FastPrinter(OutputStream out) {
            this.writer = new BufferedWriter(new OutputStreamWriter(out));
        }

        @Override
        public Appendable append(CharSequence csq) {
            buffer.append(csq);
            flushIfFull();
            return this;
        }

        @Override
        public Appendable append(CharSequence csq, int start, int end) {
            buffer.append(csq, start, end);
            flushIfFull();
            return this;
        }

        public FastPrinter append(char c) {
            buffer.append(c);
            flushIfFull();
            return this;
        }

        public FastPrinter append(String s) {
            buffer.append(s);
            flushIfFull();
            return this;
        }

        public FastPrinter println() {
            buffer.append(System.lineSeparator());
            flushIfFull();
            return this;
        }

        public FastPrinter println(String s) {
            return append(s).println();
        }

        private void flushIfFull() {
            if (buffer.length() >= BUFFER_SIZE) {
                flush();
            }
        }

        public FastPrinter flush() {
            try {
                writer.write(buffer.toString());
                writer.flush();
                buffer.setLength(0);
            } catch (IOException e) {
                throw new UncheckedIOException(e);
            }
            return this;
        }

        @Override
        public void close() {
            flush();
            try {
                writer.close();
            } catch (IOException e) {
                throw new UncheckedIOException(e);
            }
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

/**
 * Solves the AIMTech graph labeling problem.
 * Identifies universal nodes, validates triangle constraints, and assigns labels.
 */
public class AIMTechA {

    private int n;
    private int m;
    private boolean[][] adjacencyMatrix;
    private char[] nodeLabels;

    public static void main(String[] args) {
        new AIMTechA().solve();
    }

    /**
     * Orchestrates the solution pipeline.
     */
    private void solve() {
        FastScanner scanner = new FastScanner(System.in);
        readInput(scanner);
        identifyUniversalNodes();

        if (!validateTriangleConditions()) {
            System.out.println("No");
            return;
        }

        assignRemainingCharacters();
        System.out.println("Yes");
        System.out.println(new String(nodeLabels));
    }

    /**
     * Reads graph dimensions and edges from the input stream.
     */
    private void readInput(FastScanner scanner) {
        n = scanner.nextInt();
        m = scanner.nextInt();
        adjacencyMatrix = new boolean[n][n];
        nodeLabels = new char[n];

        for (int i = 0; i < m; i++) {
            int u = scanner.nextInt() - 1; // Convert to 0-based indexing
            int v = scanner.nextInt() - 1;
            adjacencyMatrix[u][v] = adjacencyMatrix[v][u] = true;
        }
    }

    /**
     * Marks nodes that are connected to all other nodes with the label 'b'.
     */
    private void identifyUniversalNodes() {
        for (int i = 0; i < n; i++) {
            boolean isConnectedToAll = true;
            for (int j = 0; j < n; j++) {
                if (i == j) continue;
                if (!adjacencyMatrix[i][j]) {
                    isConnectedToAll = false;
                    break;
                }
            }
            if (isConnectedToAll) {
                nodeLabels[i] = 'b';
            }
        }
    }

    /**
     * Validates that every unassigned triangle contains exactly 1 or 3 edges.
     * Returns false if a triangle with 0 or 2 edges is found.
     */
    private boolean validateTriangleConditions() {
        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                for (int k = j + 1; k < n; k++) {
                    // Skip triangles that already contain assigned nodes
                    if (nodeLabels[i] != '\0' || nodeLabels[j] != '\0' || nodeLabels[k] != '\0') {
                        continue;
                    }

                    int edgeCount = 0;
                    if (adjacencyMatrix[i][j]) edgeCount++;
                    if (adjacencyMatrix[j][k]) edgeCount++;
                    if (adjacencyMatrix[i][k]) edgeCount++;

                    // Original constraint: triangles with 0 or 2 edges are invalid
                    if (edgeCount == 0 || edgeCount == 2) {
                        return false;
                    }
                }
            }
        }
        return true;
    }

    /**
     * Assigns labels to remaining unassigned nodes based on adjacency to already-labeled nodes.
     */
    private void assignRemainingCharacters() {
        char currentChar = 'a';
        for (int i = 0; i < n; i++) {
            if (nodeLabels[i] != '\0') continue;

            boolean assigned = false;
            for (int j = 0; j < n; j++) {
                if (adjacencyMatrix[i][j] && nodeLabels[j] != '\0' && nodeLabels[j] != 'b') {
                    nodeLabels[i] = nodeLabels[j];
                    assigned = true;
                    break;
                }
            }

            if (!assigned) {
                nodeLabels[i] = currentChar;
                // Preserves original behavior: skips 'b' and remains at 'c'
                currentChar = 'c'; 
            }
        }
    }

    /**
     * Fast input reader optimized for competitive programming scenarios.
     */
    private static class FastScanner {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastScanner(InputStream stream) {
            this.reader = new BufferedReader(new InputStreamReader(stream), 32768);
            this.tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) {
                        throw new RuntimeException("Unexpected end of input");
                    }
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.IOException;
import java.io.InputStream;
import java.io.OutputStream;
import java.io.PrintWriter;
import java.util.InputMismatchException;
import java.util.NoSuchElementException;

public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        FastInputReader in = new FastInputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);

        GraphSolver solver = new GraphSolver();
        solver.solve(in, out);

        out.flush();
        out.close();
    }

    static class GraphSolver {
        private static final int UNCOLORED = 0;
        private static final int COLOR_A = 1;
        private static final int COLOR_B = 2; // Reserved for isolated nodes
        private static final int COLOR_C = 3;
        private static final char[] COLOR_MAP = {'a', 'b', 'c'};

        public void solve(FastInputReader in, PrintWriter out) {
            int n = in.nextInt();
            int m = in.nextInt();

            boolean[][] adj = new boolean[n][n];
            for (int i = 0; i < m; i++) {
                int u = in.nextInt() - 1;
                int v = in.nextInt() - 1;
                adj[u][v] = adj[v][u] = true;
            }

            int[] color = new int[n];
            for (int i = 0; i < n; i++) {
                if (color[i] == UNCOLORED) {
                    if (hasColoringConflict(adj, color, i, -1, COLOR_A)) {
                        out.println("No");
                        return;
                    }
                }
            }

            // Assign color 2 to isolated nodes (nodes with no edges)
            for (int i = 0; i < n; i++) {
                if (isIsolated(adj, i)) {
                    color[i] = COLOR_B;
                }
            }

            // Validate final coloring: adjacent nodes cannot have colors differing by 2 (i.e., 1 and 3)
            for (int i = 0; i < n; i++) {
                for (int j = i + 1; j < n; j++) {
                    if (adj[i][j] && Math.abs(color[i] - color[j]) == 2) {
                        out.println("No");
                        return;
                    }
                }
            }

            out.println("Yes");
            for (int i = 0; i < n; i++) {
                out.print(COLOR_MAP[color[i] - 1]);
            }
            out.println();
        }

        private boolean isIsolated(boolean[][] adj, int u) {
            for (int v = 0; v < adj[u].length; v++) {
                if (adj[u][v]) return false;
            }
            return true;
        }

        /**
         * Validates the coloring constraint on non-adjacent nodes.
         * Returns true if a conflict is found (i.e., the coloring is invalid).
         * Uses 4 - currentColor to toggle between COLOR_A (1) and COLOR_C (3).
         */
        private boolean hasColoringConflict(boolean[][] adj, int[] color, int u, int parent, int currentColor) {
            color[u] = currentColor;
            for (int v = 0; v < adj[u].length; v++) {
                if (u == v || v == parent) continue;
                if (!adj[u][v]) { // Check non-edges
                    if (color[v] == UNCOLORED) {
                        if (hasColoringConflict(adj, color, v, u, 4 - currentColor)) {
                            return true;
                        }
                    } else if (color[v] == currentColor) {
                        return true;
                    }
                }
            }
            return false;
        }
    }

    static class FastInputReader {
        private final InputStream is;
        private byte[] buffer;
        private int lenbuf;
        private int ptrbuf;

        public FastInputReader(InputStream stream) {
            this.is = stream;
            this.buffer = new byte[1024];
            this.lenbuf = 0;
            this.ptrbuf = 0;
        }

        private int readByte() {
            if (ptrbuf >= lenbuf) {
                ptrbuf = 0;
                try {
                    lenbuf = is.read(buffer);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input stream", e);
                }
                if (lenbuf <= 0) {
                    return -1;
                }
            }
            return buffer[ptrbuf++];
        }

        public int nextInt() {
            int b = readByte();
            while (b != -1 && !isDigit(b) && b != '-') {
                b = readByte();
            }
            if (b == -1) {
                throw new NoSuchElementException("No more input available");
            }
            boolean minus = false;
            if (b == '-') {
                minus = true;
                b = readByte();
            }
            if (!isDigit(b)) {
                throw new InputMismatchException("Expected integer, got: " + (char) b);
            }
            int num = 0;
            while (isDigit(b)) {
                num = num * 10 + (b - '0');
                b = readByte();
            }
            return minus ? -num : num;
        }

        private boolean isDigit(int b) {
            return b >= '0' && b <= '9';
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.Arrays;
import java.util.StringTokenizer;

/**
 * Refactored solution for graph coloring problem.
 * 
 * Improvements made:
 * 1. Removed unused code (power function, MOD, INF constants).
 * 2. Extracted logic into distinct methods (buildGraph, assignColors, validate).
 * 3. Improved variable naming (N -> numVertices, vals -> vertexColors, etc.).
 * 4. Used constants for magic characters ('a', 'b', 'c').
 * 5. Improved output handling (using String constructor for printing array).
 * 6. Added comments to explain the logic blocks.
 * 7. Enhanced FastScanner robustness.
 */
public class Main {

    // Constants for colors to replace magic characters
    private static final char COLOR_A = 'a';
    private static final char COLOR_C = 'c';
    private static final char COLOR_B = 'b';

    public static void main(String[] args) {
        FastScanner sc = new FastScanner();
        PrintWriter pw = new PrintWriter(System.out);

        try {
            solve(sc, pw);
        } catch (Exception e) {
            e.printStackTrace();
        } finally {
            pw.flush();
            pw.close();
        }
    }

    private static void solve(FastScanner sc, PrintWriter pw) {
        int numVertices = sc.ni();
        int numEdges = sc.ni();

        // 1. Build the graph
        boolean[][] adjacencyMatrix = new boolean[numVertices][numVertices];
        for (int i = 0; i < numEdges; i++) {
            int u = sc.ni() - 1; // 0-indexed
            int v = sc.ni() - 1; // 0-indexed
            adjacencyMatrix[u][v] = true;
            adjacencyMatrix[v][u] = true;
        }

        // 2. Initialize colors
        char[] vertexColors = new char[numVertices];
        Arrays.fill(vertexColors, COLOR_B);

        // 3. Assign colors based on non-edges
        assignColors(numVertices, adjacencyMatrix, vertexColors);

        // 4. Validate the coloring
        if (isValid(numVertices, adjacencyMatrix, vertexColors)) {
            pw.println("Yes");
            pw.println(new String(vertexColors));
        } else {
            pw.println("No");
        }
    }

    /**
     * Assigns colors 'a' and 'c' to vertices connected by non-edges.
     * If a non-edge exists between i and j, they must be colored 'a' and 'c' respectively (or vice versa).
     */
    private static void assignColors(int n, boolean[][] adj, char[] colors) {
        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                if (!adj[i][j]) {
                    // Logic to enforce that non-adjacent vertices have colors 'a' and 'c'
                    if (colors[i] == COLOR_A) {
                        colors[j] = COLOR_C;
                    } else if (colors[i] == COLOR_C) {
                        colors[j] = COLOR_A;
                    } else if (colors[j] == COLOR_A) {
                        colors[i] = COLOR_C;
                    } else if (colors[j] == COLOR_C) {
                        colors[i] = COLOR_A;
                    } else {
                        // Both are currently 'b', assign 'a' to i and 'c' to j
                        colors[i] = COLOR_A;
                        colors[j] = COLOR_C;
                    }
                }
            }
        }
    }

    /**
     * Validates the coloring constraints:
     * 1. If two vertices are connected (adjacent), they cannot be 'a' and 'c' (diff 2).
     * 2. If two vertices are not connected, they must be 'a' and 'c' (diff 2).
     */
    private static boolean isValid(int n, boolean[][] adj, char[] colors) {
        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                boolean isConnected = adj[i][j];
                int colorDiff = Math.abs(colors[i] - colors[j]);

                // Constraint: Edges cannot connect 'a' and 'c'
                if (isConnected && colorDiff == 2) {
                    return false;
                }

                // Constraint: Non-edges must connect 'a' and 'c'
                // Original logic: (!adj[i][j] && diff <= 1) -> invalid.
                // This is equivalent to: (!adj[i][j] && diff != 2) -> invalid.
                if (!isConnected && colorDiff != 2) {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * FastScanner utility class for efficient input reading.
     */
    static class FastScanner {
        BufferedReader br;
        StringTokenizer st;

        public FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    e.printStackTrace();
                    return null;
                }
            }
            return st.nextToken();
        }

