class Task {
    private static final char ROLE_A = 'a';
    private static final char ROLE_B = 'b';
    private static final char ROLE_C = 'c';

    /**
     * Orchestrates the graph processing: reads input, assigns roles, validates, and outputs.
     */
    public void solve(InputReader in, PrintWriter out) {
        int n = in.nextInt();
        int m = in.nextInt();

        int[][] adjacencyMatrix = new int[n + 1][n + 1];
        int[] degree = new int[n + 1];

        // Mark self-connections as per original logic
        for (int i = 1; i <= n; i++) {
            adjacencyMatrix[i][i] = 1;
        }

        // Read edges and compute degrees
        for (int i = 0; i < m; i++) {
            int u = in.nextInt();
            int v = in.nextInt();
            adjacencyMatrix[u][v] = 1;
            adjacencyMatrix[v][u] = 1;
            degree[u]++;
            degree[v]++;
        }

        // Assign roles to nodes
        char[] roles = assignRoles(n, adjacencyMatrix, degree);

        // Validate assignment against graph constraints
        if (validateGraph(n, adjacencyMatrix, roles)) {
            out.println("Yes");
            printResult(out, roles);
        } else {
            out.println("No");
        }
    }

    /**
     * Assigns 'a', 'b', or 'c' to each node based on connectivity rules.
     */
    private char[] assignRoles(int n, int[][] adjacencyMatrix, int[] degree) {
        char[] roles = new char[n + 1];
        Arrays.fill(roles, ' '); // ' ' denotes unassigned

        // Nodes connected to everyone else get role 'b'
        for (int i = 1; i <= n; i++) {
            if (degree[i] == n - 1) {
                roles[i] = ROLE_B;
            }
        }

        // Assign remaining nodes greedily
        for (int i = 1; i <= n; i++) {
            if (roles[i] == ' ') {
                roles[i] = ROLE_A;
                for (int j = 1; j <= n; j++) {
                    if (roles[j] == ' ') {
                        if (adjacencyMatrix[i][j] == 1) {
                            roles[j] = ROLE_A;
                        } else {
                            roles[j] = ROLE_C;
                        }
                    }
                }
            }
        }
        return roles;
    }

    /**
     * Checks if the assigned roles satisfy the graph's edge constraints.
     */
    private boolean validateGraph(int n, int[][] adjacencyMatrix, char[] roles) {
        for (int i = 1; i <= n; i++) {
            for (int j = i + 1; j <= n; j++) {
                if (!isEdgeValid(roles[i], roles[j], adjacencyMatrix[i][j] == 1)) {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Validates a single edge based on the roles of its endpoints.
     * Rules derived from original logic:
     * - If roles are 'a' and 'c' (diff == 2), they MUST NOT be connected.
     * - If roles are 'a'/'b', 'b'/'c', or identical (diff < 2), they MUST be connected.
     */
    private boolean isEdgeValid(char role1, char role2, boolean isConnected) {
        int diff = Math.abs(role1 - role2);
        boolean isFarApart = diff == 2;
        boolean isClose = diff < 2;

        if (isFarApart && isConnected) return false;
        if (isClose && !isConnected) return false;
        return true;
    }

    /**
     * Prints the resulting role assignment to the output stream.
     */
    private void printResult(PrintWriter out, char[] roles) {
        for (int i = 1; i < roles.length; i++) {
            out.print(roles[i]);
        }
    }
}

