public class C624C {
    public static void main(String[] args) {
        FastScanner scanner = new FastScanner();
        PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out));

        int n = scanner.nextInt();
        int m = scanner.nextInt();

        // Adjacency matrix to track edges
        boolean[][] isEdge = new boolean[n][n];
        for (int i = 0; i < m; i++) {
            int u = scanner.nextInt() - 1;
            int v = scanner.nextInt() - 1;
            isEdge[u][v] = true;
            isEdge[v][u] = true;
        }

        // 0 represents unassigned, 'a'/'c' are bipartite colors, 'b' is fallback
        char[] colors = new char[n];
        boolean possible = true;

        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                if (!isEdge[i][j]) {
                    // Non-adjacent vertices must receive different colors from {'a', 'c'}
                    if (colors[i] == 0) {
                        colors[i] = (colors[j] == 'a') ? 'c' : 'a';
                    }
                    if (colors[j] == 0) {
                        colors[j] = (colors[i] == 'a') ? 'c' : 'a';
                    }
                    if (colors[i] != 0 && colors[j] != 0 && colors[i] == colors[j]) {
                        possible = false;
                    }
                } else {
                    // Adjacent vertices must share the same color (if both are assigned)
                    if (colors[i] != 0 && colors[j] != 0 && colors[i] != colors[j]) {
                        possible = false;
                    }
                }
                if (!possible) break;
            }
            if (!possible) break;
        }

        if (!possible) {
            out.println("No");
        } else {
            out.println("Yes");
            for (int i = 0; i < n; i++) {
                if (colors[i] == 0) {
                    colors[i] = 'b';
                }
                out.print(colors[i]);
            }
            out.println();
        }

        out.flush();
    }

