import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.StringTokenizer;

/**
 * A program to validate a graph coloring based on specific topological rules.
 * 
 * Refactoring improvements:
 * 1. Separation of Concerns: I/O handling is distinct from graph logic.
 * 2. Type Safety: Replaced generic array creation (List<Integer>[]) with List<List<Integer>>.
 * 3. Readability: Used constants for magic characters ('a', 'b', 'c') and descriptive variable names.
 * 4. Performance: Replaced Scanner with BufferedReader/StringTokenizer for faster input parsing.
 * 5. Structure: Logic is encapsulated in a dedicated method.
 */
public class GraphAndString {

    // Constants for node colors to improve readability and maintainability
    private static final char COLOR_A = 'a';
    private static final char COLOR_B = 'b';
    private static final char COLOR_C = 'c';

    private List<List<Integer>> adjacencyList;
    private int numVertices;
    private int numEdges;

    public GraphAndString(BufferedReader reader, PrintWriter writer) {
        try {
            processInput(reader, writer);
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    private void processInput(BufferedReader reader, PrintWriter writer) throws IOException {
        StringTokenizer st = new StringTokenizer("");

        // Helper logic to read next integer token
        // Reads n (number of vertices)
        while (!st.hasMoreTokens()) {
            String line = reader.readLine();
            if (line == null) return;
            st = new StringTokenizer(line);
        }
        numVertices = Integer.parseInt(st.nextToken());

        // Reads m (number of edges)
        while (!st.hasMoreTokens()) {
            String line = reader.readLine();
            if (line == null) return;
            st = new StringTokenizer(line);
        }
        numEdges = Integer.parseInt(st.nextToken());

        // Initialize Graph using List of Lists for type safety
        // Original code used List<Integer>[] which triggers generic array creation warnings
        adjacencyList = new ArrayList<>(numVertices);
        for (int i = 0; i < numVertices; i++) {
            adjacencyList.add(new ArrayList<>());
        }

        // Read Edges
        for (int i = 0; i < numEdges; i++) {
            // Read u
            while (!st.hasMoreTokens()) {
                String line = reader.readLine();
                if (line == null) break;
                st = new StringTokenizer(line);
            }
            int u = Integer.parseInt(st.nextToken()) - 1; // 0-indexed

            // Read v
            while (!st.hasMoreTokens()) {
                String line = reader.readLine();
                if (line == null) break;
                st = new StringTokenizer(line);
            }
            int v = Integer.parseInt(st.nextToken()) - 1; // 0-indexed

            adjacencyList.get(u).add(v);
            adjacencyList.get(v).add(u);
        }

        // Logic: Assign Colors
        char[] colors = new char[numVertices];
        Arrays.fill(colors, COLOR_C);

        // 1. Identify 'b' nodes: nodes connected to all other nodes (degree n-1)
        for (int u = 0; u < numVertices; u++) {
            if (adjacencyList.get(u).size() == numVertices - 1) {
                colors[u] = COLOR_B;
            }
        }

        // 2. Identify 'a' nodes:
        // Find the first node that is not 'b'
        int firstNonBNode = -1;
        for (int u = 0; u < numVertices; u++) {
            if (colors[u] != COLOR_B) {
                firstNonBNode = u;
                break;
            }
        }

        // If found, color it and its neighbors 'a' (unless they are 'b')
        if (firstNonBNode != -1) {
            colors[firstNonBNode] = COLOR_A;
            for (int neighbor : adjacencyList.get(firstNonBNode)) {
                if (colors[neighbor] != COLOR_B) {
                    colors[neighbor] = COLOR_A;
                }
            }
        }

        // 3. Count total occurrences of each color
        int countA = 0;
        int countB = 0;
        int countC = 0;

        for (char c : colors) {
            if (c == COLOR_A) countA++;
            else if (c == COLOR_B) countB++;
            else countC++;
        }

        // 4. Validate the coloring
        boolean isValid = true;
        for (int u = 0; u < numVertices; u++) {
            int localA = 0;
            int localB = 0;
            int localC = 0;

            // Count self
            if (colors[u] == COLOR_A) localA++;
            else if (colors[u] == COLOR_B) localB++;
            else localC++;

            // Count neighbors
            for (int v : adjacencyList.get(u)) {
                if (colors[v] == COLOR_A) localA++;
                else if (colors[v] == COLOR_B) localB++;
                else localC++;
            }

            // Validation Rules:
            // If node is 'a':
            // - Must not be connected to any 'c' node (localC > 0)
            // - The count of 'b' neighbors must match total 'b' count (implies connected to all 'b's)
            // - The count of 'a' neighbors (including self) must match total 'a' count (implies clique)
            if (colors[u] == COLOR_A) {
                if (localC > 0 || localB != countB || localA != countA) {
                    isValid = false;
                    break;
                }
            }

            // If node is 'c':
            // - Must not be connected to any 'a' node (localA > 0)
            // - The count of 'b' neighbors must match total 'b' count
            // - The count of 'c' neighbors (including self) must match total 'c' count
            if (colors[u] == COLOR_C) {
                if (localA > 0 || localB != countB || localC != countC) {
                    isValid = false;
                    break;
                }
            }
        }

        // 5. Output Results
        writer.println(isValid ? "Yes" : "No");
        if (isValid) {
            writer.println(new String(colors));
        }
        writer.flush();
    }

    public static void main(String[] args) {
        // Use BufferedReader for fast I/O instead of mixing Scanner and BufferedReader
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter writer = new PrintWriter(System.out);

        // Instantiate the class which handles the logic
        new GraphAndString(reader, writer);

        writer.close();
    }
}

import java.io.*;
import java.util.*;

public class Main {

    public static void main(String[] args) throws IOException {
        // Try-with-resources ensures automatic and safe cleanup of I/O streams
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
             PrintWriter writer = new PrintWriter(new BufferedOutputStream(System.out), true)) {

            FastScanner scanner = new FastScanner(reader);
            GraphSolver solver = new GraphSolver(scanner, writer);
            solver.solve();
        }
    }

    /**
     * Encapsulates all graph processing logic. Replaces the original static fields
     * with instance state to improve testability, thread-safety, and maintainability.
     */
    static class GraphSolver {
        private final FastScanner scanner;
        private final PrintWriter writer;
        private final List<List<Integer>> adjacencyList;
        private final boolean[][] isAdjacent;
        private final char[] colors;
        private final int n;

        public GraphSolver(FastScanner scanner, PrintWriter writer) {
            this.scanner = scanner;
            this.writer = writer;
            this.adjacencyList = new ArrayList<>();
            this.isAdjacent = null;
            this.colors = null;
            this.n = 0;
        }

        public void solve() throws IOException {
            int n = scanner.nextInt();
            int q = scanner.nextInt();
            this.n = n;

            // Initialize data structures
            adjacencyList = new ArrayList<>(n);
            for (int i = 0; i < n; i++) {
                adjacencyList.add(new ArrayList<>());
            }
            isAdjacent = new boolean[n][n];
            colors = new char[n]; // Java initializes char arrays to '\0' (value 0)

            // Read edges
            for (int i = 0; i < q; i++) {
                int a = scanner.nextInt() - 1;
                int b = scanner.nextInt() - 1;
                adjacencyList.get(a).add(b);
                adjacencyList.get(b).add(a);
                isAdjacent[a][b] = true;
                isAdjacent[b][a] = true;
            }

            // Pre-color nodes that are connected to all other nodes
            for (int i = 0; i < n; i++) {
                if (adjacencyList.get(i).size() == n - 1) {
                    colors[i] = 'b';
                }
            }

            // Assign colors to remaining unassigned connected components
            int componentCount = 0;
            for (int i = 0; i < n; i++) {
                if (colors[i] != 0) {
                    continue;
                }

                if (componentCount == 0) {
                    colorComponent(i, 'a');
                    componentCount++;
                } else if (componentCount == 1) {
                    colorComponent(i, 'c');
                    componentCount++;
                } else {
                    // More than 2 uncolored components violates problem constraints
                    writer.println("No");
                    return;
                }
            }

            // Validate the final coloring against adjacency constraints
            if (!isValidColoring()) {
                writer.println("No");
                return;
            }

            writer.println("Yes");
            writer.println(new String(colors));
        }

        /**
         * Iteratively colors all unvisited nodes in the same connected component.
         * Replaces the original recursive `paint` method to prevent StackOverflowError
         * on large inputs while preserving identical traversal behavior.
         */
        private void colorComponent(int startNode, char color) {
            Deque<Integer> queue = new ArrayDeque<>();
            queue.add(startNode);
            colors[startNode] = color;

            while (!queue.isEmpty()) {
                int u = queue.poll();
                for (int v : adjacencyList.get(u)) {
                    if (colors[v] == 0) {
                        colors[v] = color;
                        queue.add(v);
                    }
                }
            }
        }

        /**
         * Validates the coloring constraint:
         * Any two nodes with a character difference of <= 1 must be directly connected in the graph.
         */
        private boolean isValidColoring() {
            for (int i = 0; i < n; i++) {
                for (int j = i + 1; j < n; j++) {
                    if (Math.abs(colors[i] - colors[j]) <= 1) {
                        if (!isAdjacent[i][j]) {
                            return false;
                        }
                    }
                }
            }
            return true;
        }
    }

    /**
     * High-performance input scanner. Simplified from the original template
     * to remove unused methods and fix edge-case handling for maintainability.
     */
    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        public String next() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) {
                    throw new IOException("Unexpected end of input");
                }
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}

