/**
 * Solves the graph labeling problem by assigning nodes to categories 'a', 'b', or 'c'
 * based on connectivity constraints, then validates the assignment.
 */
class GraphLabelingSolver {

    public void solve(int testNumber, FastScanner scanner, PrintWriter output) {
        int n = scanner.nextInt();
        int m = scanner.nextInt();

        boolean[][] adjacencyMatrix = new boolean[n][n];
        int[] degrees = new int[n];

        for (int i = 0; i < m; i++) {
            int u = scanner.nextInt() - 1;
            int v = scanner.nextInt() - 1;
            adjacencyMatrix[u][v] = adjacencyMatrix[v][u] = true;
            degrees[u]++;
            degrees[v]++;
        }

        char[] labels = new char[n];

        // Step 1: Identify nodes connected to all others and assign 'b'
        for (int i = 0; i < n; i++) {
            if (degrees[i] == n - 1) {
                labels[i] = 'b';
            }
        }

        // Step 2: Assign 'a' to the first unassigned node and its neighbors
        for (int i = 0; i < n; i++) {
            if (labels[i] == 0) {
                labels[i] = 'a';
                for (int j = 0; j < n; j++) {
                    if (i != j && adjacencyMatrix[i][j] && labels[j] == 0) {
                        labels[j] = 'a';
                    }
                }
                break; // Only need to initialize one 'a' component
            }
        }

        // Step 3: Assign remaining nodes to 'c'
        for (int i = 0; i < n; i++) {
            if (labels[i] == 0) {
                labels[i] = 'c';
            }
        }

        // Validate the labeling against graph constraints
        if (!isValidLabeling(labels, adjacencyMatrix, n)) {
            output.println("No");
            return;
        }

        output.println("Yes");
        output.println(new String(labels));
    }

    /**
     * Validates the node labeling against the graph's adjacency rules.
     * 
     * Constraint logic (derived from ASCII differences):
     * - Connected nodes must NOT have a label difference of 2 ('a' vs 'c')
     * - Disconnected nodes MUST have a label difference of 2 ('a' vs 'c')
     */
    private boolean isValidLabeling(char[] labels, boolean[][] graph, int n) {
        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                boolean isConnected = graph[i][j];
                int labelDiff = Math.abs(labels[i] - labels[j]);

                if (isConnected && labelDiff == 2) {
                    return false;
                }
                if (!isConnected && labelDiff != 2) {
                    return false;
                }
            }
        }
        return true;
    }
}

