/**
 * Solves a graph connectivity problem by determining if the graph can be 
 * partitioned into at most two cliques, with optional universal nodes.
 * 
 * Refactoring highlights:
 * - Removed global static state; encapsulated logic in a stateless solve method.
 * - Replaced magic numbers (0, 1, 2, 3) with a strongly-typed enum.
 * - Switched from adjacency matrix to adjacency sets for better scalability.
 * - Extracted DFS and clique validation into dedicated, testable methods.
 * - Used try-with-resources and modern I/O for robustness.
 * - Added comprehensive documentation and clear naming conventions.
 */
public class AimFundC {

    /** Represents the classification of each node in the graph. */
    private enum NodeCategory {
        UNIVERSAL,    // Connected to all other nodes
        COMPONENT_A,  // Part of the first connected component
        COMPONENT_C   // Part of the second connected component
    }

    public static void main(String[] args) {
        // Use try-with-resources to ensure streams are properly closed
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
             PrintWriter out = new PrintWriter(System.out)) {

            InputReader scanner = new InputReader(br);
            String nStr = scanner.next();
            if (nStr == null) return; // Empty input

            int n = Integer.parseInt(nStr);
            int m = scanner.nextInt();

            NodeCategory[] categories = solve(n, m, scanner);

            if (categories == null) {
                out.println("No");
            } else {
                out.println("Yes");
                StringBuilder output = new StringBuilder(n);
                for (NodeCategory cat : categories) {
                    switch (cat) {
                        case UNIVERSAL -> output.append('b');
                        case COMPONENT_A -> output.append('a');
                        case COMPONENT_C -> output.append('c');
                    }
                }
                out.println(output);
            }
        } catch (IOException e) {
            // In a real application, log this. For CP-style scripts, fail fast.
            throw new RuntimeException("Input/Output error", e);
        }
    }

    /**
     * Core algorithm to classify nodes and validate graph structure.
     *
     * @param n Number of nodes
     * @param m Number of edges
     * @param scanner Input reader
     * @return Array of node categories, or null if the graph structure is invalid
     */
    private static NodeCategory[] solve(int n, int m, InputReader scanner) {
        List<Set<Integer>> adj = buildGraph(n, m, scanner);
        NodeCategory[] result = new NodeCategory[n];
        Arrays.fill(result, NodeCategory.COMPONENT_C);

        boolean[] isUniversal = identifyUniversalNodes(n, adj, result);

        // If all nodes are universal, the graph is a complete graph -> valid
        if (allNodesUniversal(isUniversal)) {
            return result;
        }

        // Find the first non-universal node to start component exploration
        int startNode = findFirstNonUniversal(isUniversal);

        // Discover the first connected component among non-universal nodes
        List<Integer> componentA = new ArrayList<>();
        boolean[] visited = new boolean[n];
        dfs(startNode, adj, visited, componentA, isUniversal);

        assignCategory(componentA, result, NodeCategory.COMPONENT_A);

        // Validate that the first component forms a complete subgraph (clique)
        if (!isClique(componentA, adj)) {
            return null;
        }

        // Collect remaining non-universal nodes
        List<Integer> componentC = collectRemainingNodes(isUniversal);

        // If no other nodes exist, the graph is valid
        if (componentC.isEmpty()) {
            return result;
        }

        // Validate that the second component also forms a clique
        if (!isClique(componentC, adj)) {
            return null;
        }

        return result;
    }

    private static List<Set<Integer>> buildGraph(int n, int m, InputReader scanner) {
        List<Set<Integer>> adj = new ArrayList<>(n);
        for (int i = 0; i < n; i++) {
            adj.add(new HashSet<>());
        }

        for (int i = 0; i < m; i++) {
            int u = scanner.nextInt() - 1; // Convert 1-based to 0-based
            int v = scanner.nextInt() - 1;
            if (u >= 0 && u < n && v >= 0 && v < n) {
                adj.get(u).add(v);
                adj.get(v).add(u);
            }
        }
        return adj;
    }

    private static boolean[] identifyUniversalNodes(int n, List<Set<Integer>> adj, NodeCategory[] result) {
        boolean[] isUniversal = new boolean[n];
        for (int i = 0; i < n; i++) {
            // A universal node is connected to every other node exactly once
            if (adj.get(i).size() == n - 1) {
                result[i] = NodeCategory.UNIVERSAL;
                isUniversal[i] = true;
            }
        }
        return isUniversal;
    }

    private static boolean allNodesUniversal(boolean[] isUniversal) {
        for (boolean universal : isUniversal) {
            if (!universal) return false;
        }
        return true;
    }

    private static int findFirstNonUniversal(boolean[] isUniversal) {
        for (int i = 0; i < isUniversal.length; i++) {
            if (!isUniversal[i]) return i;
        }
        return -1; // Should not reach here due to allNodesUniversal check
    }

    private static void dfs(int u, List<Set<Integer>> adj, boolean[] visited,
                            List<Integer> component, boolean[] isUniversal) {
        visited[u] = true;
        component.add(u);
        for (int v : adj.get(u)) {
            if (!visited[v] && !isUniversal[v]) {
                dfs(v, adj, visited, component, isUniversal);
            }
        }
    }

    private static void assignCategory(List<Integer> nodes, NodeCategory[] result, NodeCategory category) {
        for (int node : nodes) {
            result[node] = category;
        }
    }

    private static List<Integer> collectRemainingNodes(boolean[] isUniversal) {
        List<Integer> remaining = new ArrayList<>();
        for (int i = 0; i < isUniversal.length; i++) {
            if (!isUniversal[i]) {
                remaining.add(i);
            }
        }
        return remaining;
    }

    /**
     * Checks if a given set of nodes forms a clique (every pair is connected).
     */
    private static boolean isClique(List<Integer> nodes, List<Set<Integer>> adj) {
        if (nodes.size() <= 1) {
            return true;
        }
        for (int i = 0; i < nodes.size(); i++) {
            for (int j = i + 1; j < nodes.size(); j++) {
                if (!adj.get(nodes.get(i)).contains(nodes.get(j))) {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Lightweight, robust input reader for competitive programming and CLI tools.
     */
    private static class InputReader {
        private final BufferedReader br;
        private StringTokenizer st;

        public InputReader(BufferedReader br) {
            this.br = br;
        }

        public String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            String token = next();
            if (token == null) throw new RuntimeException("Unexpected end of input");
            return Integer.parseInt(token);
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.StringTokenizer;

/**
 * Refactored solution for CF_624C.
 * 
 * Improvements made:
 * 1. Performance: Replaced Scanner with BufferedReader for faster I/O.
 * 2. Type Safety: Replaced array of ArrayLists (raw types) with List<List<Integer>>.
 * 3. Readability: Extracted logic into methods (solve, verifyNode) and used descriptive variable names.
 * 4. Maintainability: Introduced constants for magic characters ('a', 'b', 'c', '\0').
 * 5. Cleanliness: Removed debug prints to System.err and consolidated error handling.
 */
public class CF_624C {

    // Constants for node states to replace magic characters
    private static final char STATE_UNASSIGNED = '\0';
    private static final char COLOR_B = 'b';
    private static final char COLOR_A = 'a';
    private static final char COLOR_C = 'c';

    public static void main(String[] args) {
        // Initialize fast I/O
        FastScanner scanner = new FastScanner();

        // Read n (number of nodes) and m (number of edges)
        // Check if input exists to prevent exceptions on empty input
        if (!scanner.hasMoreTokens()) return;

        int n = scanner.nextInt();
        int m = scanner.nextInt();

        // Initialize adjacency list. 
        // Using List<List<Integer>> is safer and cleaner than ArrayList[]
        List<List<Integer>> adjacencyList = new ArrayList<>(n);
        for (int i = 0; i < n; i++) {
            adjacencyList.add(new ArrayList<>());
        }

        int[] degrees = new int[n];

        // Read edges
        for (int i = 0; i < m; i++) {
            int u = scanner.nextInt() - 1; // Convert to 0-based index
            int v = scanner.nextInt() - 1;

            adjacencyList.get(u).add(v);
            adjacencyList.get(v).add(u);
            degrees[u]++;
            degrees[v]++;
        }

        // Solve the problem
        solve(n, adjacencyList, degrees);
    }

    /**
     * Main solving logic.
     */
    private static void solve(int n, List<List<Integer>> adjacencyList, int[] degrees) {
        char[] nodeColors = new char[n];
        Arrays.fill(nodeColors, STATE_UNASSIGNED);

        // Step 1: Identify 'b' nodes.
        // In the original logic, nodes with degree n-1 are marked as 'b' (connectors).
        for (int i = 0; i < n; i++) {
            if (degrees[i] == n - 1) {
                nodeColors[i] = COLOR_B;
            }
        }

        // Track the required degree (count of non-'b' neighbors) for 'a' and 'c' nodes.
        // -1 indicates that the size for this color has not been determined yet.
        int expectedDegreeA = -1;
        int expectedDegreeC = -1;

        // Step 2: Iterate through all nodes to assign or verify colors.
        for (int i = 0; i < n; i++) {
            char currentColor = nodeColors[i];

            // If node is 'b', it acts as a connector and is skipped in this logic.
            if (currentColor == COLOR_B) {
                continue;
            }

            if (currentColor == COLOR_A || currentColor == COLOR_C) {
                // Node is already colored 'a' or 'c'. Verify consistency.
                if (!verifyNode(i, adjacencyList, nodeColors, currentColor, expectedDegreeA, expectedDegreeC)) {
                    System.out.println("No");
                    return;
                }
            } else {
                // Node is unassigned. We must assign it 'a' or 'c'.
                // Logic: 
                // 1. If 'a' target not set, assign 'a'.
                // 2. Else if 'c' target not set, assign 'c'.
                // 3. Else, impossible (No).

                char newColor = STATE_UNASSIGNED;
                if (expectedDegreeA == -1) {
                    newColor = COLOR_A;
                } else if (expectedDegreeC == -1) {
                    newColor = COLOR_C;
                } else {
                    System.out.println("No");
                    return;
                }

                // Assign color to current node
                nodeColors[i] = newColor;
                int currentDegreeCount = 0;

                // Propagate color to neighbors (except 'b' nodes)
                // and count valid neighbors to establish the target degree.
                for (int neighbor : adjacencyList.get(i)) {
                    if (nodeColors[neighbor] == COLOR_B) {
                        continue;
                    }

                    // If neighbor is already assigned, it violates the logic 
                    // (based on original code: "New empty letter is attached to an old letter")
                    if (nodeColors[neighbor] != STATE_UNASSIGNED) {
                        System.out.println("No");
                        return;
                    }

                    nodeColors[neighbor] = newColor;
                    currentDegreeCount++;
                }

                // Update the global expected degree for this color type
                if (newColor == COLOR_A) {
                    expectedDegreeA = currentDegreeCount;
                } else {
                    expectedDegreeC = currentDegreeCount;
                }
            }
        }

        // If all checks pass
        System.out.println("Yes");
        System.out.println(new String(nodeColors));
    }

    /**
     * Verifies that a node's neighbors are consistent with its color and the global constraints.
     */
    private static boolean verifyNode(int u, List<List<Integer>> adjacencyList, char[] colors, 
                                      char color, int expectedDegreeA, int expectedDegreeC) {
        int count = 0;
        for (int v : adjacencyList.get(u)) {
            // 'b' nodes are ignored in the count/check
            if (colors[v] == COLOR_B) {
                continue;
            }

            // Neighbor must have the same color
            if (colors[v] != color) {
                return false;
            }
            count++;
        }

        // Check if the count matches the established target for this color
        int expected = (color == COLOR_A) ? expectedDegreeA : expectedDegreeC;
        return expected == count;
    }

    /**
     * Helper class for fast input reading.
     */
    static class FastScanner {
        BufferedReader br;
        StringTokenizer st;

        public FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        boolean hasMoreTokens() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return false;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    return false;
                }
            }
            return true;
        }

        String next() {
            if (hasMoreTokens()) return st.nextToken();
            return null;
        }

        int nextInt() {
            String s = next();
            if (s == null) return 0; // Should not happen with valid input
            return Integer.parseInt(s);
        }
    }
}

import java.io.BufferedReader;
import java.io.FileInputStream;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.Arrays;
import java.util.StringTokenizer;

public class Main {
    // Constants representing node states
    private static final int STATE_A = 1;
    private static final int STATE_B = 3;
    private static final int STATE_UNASSIGNED = 2;

    public static void main(String[] args) {
        String filePath = args.length > 0 ? args[0] : null;

        // try-with-resources ensures the scanner and underlying streams are closed properly
        try (FastScanner scanner = new FastScanner(filePath)) {
            int testCases = 1; // Original code hardcodes T=1
            StringBuilder output = new StringBuilder();

            for (int t = 0; t < testCases; t++) {
                output.append(solve(scanner));
            }
            System.out.print(output);
        } catch (IOException e) {
            System.err.println("IO Error: " + e.getMessage());
        }
    }

    /**
     * Reads graph parameters and builds the adjacency structure.
     */
    private static String solve(FastScanner scanner) throws IOException {
        int n = scanner.nextInt();
        int m = scanner.nextInt();

        boolean[][] isConnected = new boolean[n][n];
        for (int i = 0; i < n; i++) {
            Arrays.fill(isConnected[i], true);
        }

        for (int i = 0; i < m; i++) {
            int a = scanner.nextInt() - 1;
            int b = scanner.nextInt() - 1;
            isConnected[a][b] = false;
            isConnected[b][a] = false;
        }

        return processGraph(n, isConnected);
    }

    /**
     * Applies constraint propagation and validation to assign states to nodes.
     */
    private static String processGraph(int n, boolean[][] isConnected) {
        int[] states = new int[n];
        boolean isValid = true;

        for (int i = 0; i < n && isValid; i++) {
            if (states[i] == STATE_A) {
                for (int j = i + 1; j < n; j++) {
                    if (isConnected[i][j]) {
                        if (states[j] == STATE_A) isValid = false;
                        else states[j] = STATE_B;
                    } else {
                        if (states[j] == STATE_B) isValid = false;
                    }
                }
            } else if (states[i] == STATE_B) {
                for (int j = i + 1; j < n; j++) {
                    if (isConnected[i][j]) {
                        if (states[j] == STATE_B) isValid = false;
                        else states[j] = STATE_A;
                    } else {
                        if (states[j] == STATE_A) isValid = false;
                    }
                }
            } else {
                // Node is unassigned; deduce required state based on neighbors
                int needs = 0;
                boolean cantA = false;
                boolean cantB = false;

                for (int j = i + 1; j < n; j++) {
                    if (isConnected[i][j]) {
                        if (states[j] == STATE_B) {
                            if (needs == STATE_B) isValid = false;
                            needs = STATE_A;
                        } else {
                            if (needs == STATE_A) isValid = false;
                            needs = STATE_B;
                        }
                        states[j] = (needs == STATE_A) ? STATE_B : STATE_A;
                    } else {
                        if (states[j] == STATE_B) cantA = true;
                        if (states[j] == STATE_A) cantB = true;
                    }
                }

                if (needs > 0) {
                    if (needs == STATE_A && cantA) isValid = false;
                    if (needs == STATE_B && cantB) isValid = false;
                    states[i] = needs;
                } else {
                    states[i] = STATE_UNASSIGNED;
                }
            }
        }

        // Final validation pass over all pairs
        if (isValid) {
            for (int i = 0; i < n; i++) {
                for (int j = i + 1; j < n; j++) {
                    boolean connected = isConnected[i][j];
                    int diff = Math.abs(states[i] - states[j]);
                    if (connected && diff <= 1) {
                        isValid = false;
                        break;
                    }
                    if (!connected && diff > 1) {
                        isValid = false;
                        break;
                    }
                }
                if (!isValid) break;
            }
        }

        if (isValid) {
            StringBuilder result = new StringBuilder("Yes\n");
            for (int state : states) {
                result.append((char) ('a' + state - 1));
            }
            return result.toString();
        }
        return "No";
    }

    /**
     * Efficient, reusable input scanner handling both System.in and file input.
     * Replaces the original fragile readNextLine() and Next*() methods.
     */
    private static class FastScanner implements AutoCloseable {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastScanner(String filePath) throws IOException {
            if (filePath == null) {
                reader = new BufferedReader(new InputStreamReader(System.in));
            } else {
                reader = new BufferedReader(new InputStreamReader(new FileInputStream(filePath)));
            }
            tokenizer = new StringTokenizer("");
        }

        public String next() throws IOException {
            while (!tokenizer.hasMoreTokens()) {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line, " ,\t");
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            String token = next();
            if (token == null) {
                throw new IOException("Unexpected end of input");
            }
            return Integer.parseInt(token);
        }

        @Override
        public void close() throws IOException {
            reader.close();
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.Queue;
import java.util.StringTokenizer;

/**
 * Determines if a graph is bipartite and outputs a valid 2-coloring.
 * Refactored for maintainability, performance, and code clarity.
 */
public class BipartiteGraphColoring {

    // Constants to replace magic numbers
    private static final int UNCOLORED = -1;
    private static final int COLOR_A = 0;
    private static final int COLOR_B = 1;
    private static final char CHAR_A = 'a';
    private static final char CHAR_B = 'b';

    public static void main(String[] args) throws IOException {
        // Use try-with-resources for automatic resource management
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            String line = br.readLine();
            if (line == null || line.trim().isEmpty()) {
                return;
            }

            StringTokenizer st = new StringTokenizer(line);
            int numVertices = Integer.parseInt(st.nextToken());
            int numEdges = Integer.parseInt(st.nextToken());

            // Build graph using adjacency lists for O(V+E) traversal
            List<Integer>[] adjacencyList = buildAdjacencyList(numVertices, numEdges, br);

            // Initialize colors array
            int[] colors = new int[numVertices];
            Arrays.fill(colors, UNCOLORED);

            // Check bipartiteness and perform coloring across all connected components
            if (isBipartiteAndColor(numVertices, adjacencyList, colors)) {
                System.out.println("Yes");
                System.out.println(generateColoringString(colors, numVertices));
            } else {
                System.out.println("No");
            }
        }
    }

    /**
     * Reads edge data and constructs an adjacency list representation of the graph.
     */
    @SuppressWarnings("unchecked")
    private static List<Integer>[] buildAdjacencyList(int v, int e, BufferedReader br) throws IOException {
        List<Integer>[] adj = new ArrayList[v];
        for (int i = 0; i < v; i++) {
            adj[i] = new ArrayList<>();
        }

        for (int i = 0; i < e; i++) {
            line = br.readLine();
            while (line != null && line.trim().isEmpty()) {
                line = br.readLine(); // Skip empty lines if any
            }
            if (line == null) break;

            StringTokenizer st = new StringTokenizer(line);
            int u = Integer.parseInt(st.nextToken()) - 1; // Convert to 0-based index
            int w = Integer.parseInt(st.nextToken()) - 1;

            adj[u].add(w);
            adj[w].add(u);
        }
        return adj;
    }

    /**
     * Iterates over all vertices to handle disconnected components.
     * Returns false if a conflict is found, indicating the graph is not bipartite.
     */
    private static boolean isBipartiteAndColor(int v, List<Integer>[] adj, int[] colors) {
        for (int i = 0; i < v; i++) {
            if (colors[i] == UNCOLORED) {
                if (!bfsColor(i, adj, colors)) {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Performs BFS to color a connected component.
     * Uses two colors (0 and 1). Returns false if an adjacent vertex has the same color.
     */
    private static boolean bfsColor(int start, List<Integer>[] adj, int[] colors) {
        Queue<Integer> queue = new ArrayDeque<>();
        colors[start] = COLOR_A;
        queue.offer(start);

        while (!queue.isEmpty()) {
            int current = queue.poll();
            int nextColor = 2 - colors[current]; // Alternates between 0 and 1

            for (int neighbor : adj[current]) {
                if (colors[neighbor] == UNCOLORED) {
                    colors[neighbor] = nextColor;
                    queue.offer(neighbor);
                } else if (colors[neighbor] != nextColor) {
                    return false; // Bipartite conflict detected
                }
            }
        }
        return true;
    }

    /**
     * Generates the output string based on the computed colors.
     * Note: The original code contained a redundant second loop that attempted to 
     * reassign colors for isolated vertices. This logic was dead code and has been removed.
     * Isolated vertices default to COLOR_A ('a'), which is a valid bipartite assignment.
     */
    private static String generateColoringString(int[] colors, int v) {
        StringBuilder sb = new StringBuilder(v);
        for (int i = 0; i < v; i++) {
            char c = (colors[i] == COLOR_A) ? CHAR_A : CHAR_B;
            sb.append(c);
        }
        return sb.toString();
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.ArrayDeque;
import java.util.Arrays;
import java.util.Queue;
import java.util.StringTokenizer;

public class Main {
    public static void main(String[] args) {
        FastScanner in = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out);
        GraphPartitionSolver solver = new GraphPartitionSolver();
        solver.solve(1, in, out);
        out.close();
    }

    static class GraphPartitionSolver {
        private static final char UNVISITED = 'b';
        private static final char COLOR_A = 'a';
        private static final char COLOR_C = 'c';

        public void solve(int testNumber, FastScanner in, PrintWriter out) {
            int n = in.nextInt();
            int m = in.nextInt();

            boolean[][] adjacencyMatrix = buildCompleteGraph(n);
            removeRemovedEdges(adjacencyMatrix, m, in);

            char[] partition = new char[n];
            Arrays.fill(partition, UNVISITED);

            boolean isBipartite = checkBipartiteAndAssignColors(n, adjacencyMatrix, partition);

            if (!isBipartite) {
                out.println("No");
                return;
            }

            if (isValidCompleteBipartiteGraph(n, adjacencyMatrix, partition)) {
                out.println("Yes");
                out.println(new String(partition));
            } else {
                out.println("No");
            }
        }

        private boolean[][] buildCompleteGraph(int n) {
            boolean[][] adj = new boolean[n][n];
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < n; j++) {
                    if (i != j) {
                        adj[i][j] = true;
                    }
                }
            }
            return adj;
        }

        private void removeRemovedEdges(boolean[][] adj, int m, FastScanner in) {
            for (int i = 0; i < m; i++) {
                int u = in.nextInt() - 1;
                int v = in.nextInt() - 1;
                adj[u][v] = false;
                adj[v][u] = false;
            }
        }

        private boolean checkBipartiteAndAssignColors(int n, boolean[][] adj, char[] partition) {
            Queue<Integer> queue = new ArrayDeque<>();
            for (int i = 0; i < n; i++) {
                if (partition[i] == UNVISITED) {
                    partition[i] = COLOR_A;
                    queue.add(i);
                    while (!queue.isEmpty()) {
                        int u = queue.poll();
                        for (int v = 0; v < n; v++) {
                            if (adj[u][v]) {
                                if (partition[v] == UNVISITED) {
                                    partition[v] = COLOR_C;
                                    queue.add(v);
                                } else if (partition[v] == partition[u]) {
                                    return false;
                                }
                            }
                        }
                    }
                }
            }
            return true;
        }

        private boolean isValidCompleteBipartiteGraph(int n, boolean[][] adj, char[] partition) {
            for (int i = 0; i < n; i++) {
                for (int j = i + 1; j < n; j++) {
                    boolean hasEdge = adj[i][j];
                    boolean shouldHaveEdge = (partition[i] != partition[j]);
                    if (hasEdge != shouldHaveEdge) {
                        return false;
                    }
                }
            }
            return true;
        }
    }

    static class FastScanner {
        private final BufferedReader in;
        private StringTokenizer st;

        public FastScanner(InputStream stream) {
            in = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = in.readLine();
                    if (line == null) {
                        return null;
                    }
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.*;
import java.util.*;

public class Solution {
    // Constants to replace magic numbers and improve readability
    private static final char[] COLORS = {'a', 'b', 'c'};
    private static final int COLOR_INCREMENT = 2;
    private static final int MAX_COLOR_VALUE = 4; // Original logic: k > 4 triggers failure
    private static final int MAX_COMPONENTS = 2;  // Corresponds to k reaching 6

    // Instance fields replace static globals for better encapsulation
    private int n;
    private int m;
    private List<List<Integer>> adjacencyList;
    private Set<Long> edgeSet;
    private int[] colorMap;

    public static void main(String[] args) {
        Solution solver = new Solution();
        FastScanner fs = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out));

        try {
            solver.run(fs, out);
        } finally {
            out.flush();
            out.close();
        }
    }

    void run(FastScanner fs, PrintWriter out) {
        // Original code fixed tt=1, kept loop structure for compatibility
        int testCases = 1;
        while (testCases-- > 0) {
            solve(fs, out);
        }
    }

    private void solve(FastScanner fs, PrintWriter out) {
        try {
            n = fs.nextInt();
            m = fs.nextInt();

            initializeGraph();
            readEdges(fs);
            assignColors();

            if (colorMap == null) {
                out.println("No");
                return;
            }

            if (validateAllPairs()) {
                out.println("Yes");
                printColors(out);
            } else {
                out.println("No");
            }
        } catch (Exception e) {
            // Graceful failure on malformed input or unexpected runtime issues
            out.println("No");
        }
    }

    private void initializeGraph() {
        adjacencyList = new ArrayList<>(n);
        for (int i = 0; i < n; i++) {
            adjacencyList.add(new ArrayList<>());
        }
        edgeSet = new HashSet<>();
        colorMap = new int[n];
        Arrays.fill(colorMap, -1);
    }

    private void readEdges(FastScanner fs) {
        for (int i = 0; i < m; i++) {
            int u = fs.nextInt() - 1;
            int v = fs.nextInt() - 1;
            adjacencyList.get(u).add(v);
            adjacencyList.get(v).add(u);
            edgeSet.add(encodeEdge(u, v));
        }
    }

    private void assignColors() {
        int currentColor = 0;
        int componentsColored = 0;

        for (int i = 0; i < n; i++) {
            if (colorMap[i] == -1) {
                componentsColored++;
                // Original logic: k > 4 triggers failure. k increments by 2.
                // 3rd component would make k = 6, so we cap at 2 components.
                if (componentsColored > MAX_COMPONENTS) {
                    colorMap = null; // Signal invalid state
                    return;
                }
                dfsColor(i, currentColor);
                currentColor += COLOR_INCREMENT;
            }
        }
    }

    private void dfsColor(int node, int color) {
        colorMap[node] = color;
        for (int neighbor : adjacencyList.get(node)) {
            if (colorMap[neighbor] == -1) {
                dfsColor(neighbor, color);
            }
        }
    }

    private boolean validateAllPairs() {
        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                if (!validatePair(i, j)) {
                    return false;
                }
            }
        }
        return true;
    }

    private boolean validatePair(int i, int j) {
        int colorI = colorMap[i];
        int colorJ = colorMap[j];
        boolean hasEdge = edgeSet.contains(encodeEdge(i, j));

        // Original logic: same color or adjacent colors => must have edge
        if (colorI == colorJ || Math.abs(colorI - colorJ) == 1) {
            return hasEdge;
        }
        // Different colors => must not have edge
        return !hasEdge;
    }

    private void printColors(PrintWriter out) {
        StringBuilder sb = new StringBuilder(n);
        for (int color : colorMap) {
            // Safety clamp: Original logic could assign color 4, which would crash arr[4].
            // Clamping ensures robustness while preserving intended output behavior.
            sb.append(COLORS[Math.min(color, COLORS.length - 1)]);
        }
        out.println(sb);
    }

    /**
     * Encodes an undirected edge into a unique long value for O(1) HashSet lookup.
     * Replaces the O(N^2) adjacency matrix for better memory efficiency.
     */
    private long encodeEdge(int u, int v) {
        int min = Math.min(u, v);
        int max = Math.max(u, v);
        return ((long) min << 32) | (max & 0xFFFFFFFFL);
    }

    /**
     * Optimized FastScanner for competitive programming and fast I/O.
     */
    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input", e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            String s = next();
            if (s == null) throw new NoSuchElementException();
            return Integer.parseInt(s);
        }
    }
}

import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Scanner;
import java.util.Set;

/**
 * Refactored Graph Partition Solver.
 * 
 * This program attempts to partition the vertices of an undirected graph into 
 * three sets: A, B, and C, satisfying specific structural properties:
 * 1. Set B contains "universal" vertices (connected to all other vertices).
 * 2. Set A is a clique found among the remaining vertices.
 * 3. Set C is a clique found among the vertices remaining after removing A and B.
 * 4. There must be no edges between any vertex in Set A and any vertex in Set C.
 * 
 * If such a partition exists, it prints "Yes" and the assignment string; otherwise, "No".
 */
public class GraphPartitionSolver {

    private final int numVertices;
    // Using List<Set<Integer>> instead of an array of generics to avoid raw type warnings
    // and improve type safety.
    private final List<Set<Integer>> adjacencyList;

    /**
     * Constructs the solver and builds the graph from input.
     *
     * @param n      Number of vertices.
     * @param m      Number of edges.
     * @param scanner Scanner instance reading input.
     */
    public GraphPartitionSolver(int n, int m, Scanner scanner) {
        this.numVertices = n;
        this.adjacencyList = new ArrayList<>(n);

        // Initialize adjacency list
        for (int i = 0; i < n; i++) {
            adjacencyList.add(new HashSet<>());
        }

        // Read edges (Input is 1-based, converting to 0-based indexing)
        for (int i = 0; i < m; i++) {
            if (scanner.hasNextInt()) {
                int u = scanner.nextInt() - 1;
                int v = scanner.nextInt() - 1;

                // Basic bounds check to prevent runtime errors on malformed input
                if (u >= 0 && u < n && v >= 0 && v < n) {
                    adjacencyList.get(u).add(v);
                    adjacencyList.get(v).add(u);
                }
            }
        }
    }

    /**
     * Executes the partition logic.
     */
    public void solve() {
        // 1. Identify Set B: Vertices connected to all other vertices (Universal Nodes)
        Set<Integer> setB = findUniversalNodes();

        // 2. Identify remaining vertices (Universe \ Set B)
        Set<Integer> remainingVertices = new HashSet<>();
        for (int i = 0; i < numVertices; i++) {
            if (!setB.contains(i)) {
                remainingVertices.add(i);
            }
        }

        // 3. Identify Set A: A clique found among remaining vertices
        // Note: The original implementation uses a greedy approach.
        Set<Integer> setA = findGreedyClique(remainingVertices);

        // 4. Identify Set C: Another clique found in the vertices remaining after removing A
        remainingVertices.removeAll(setA);
        Set<Integer> setC = findGreedyClique(remainingVertices);

        // 5. Validation: Check if the partition covers all vertices
        if (setB.size() + setA.size() + setC.size() == numVertices) {
            // 6. Validation: Check if there are no edges between Set A and Set C
            if (areDisconnected(setA, setC)) {
                printResult(setA, setB, setC);
                return;
            }
        }

        // If conditions are not met
        System.out.println("No");
    }

    /**
     * Finds all universal vertices (connected to every other vertex in the graph).
     * Optimization: In a simple graph, a vertex is universal if its degree is n-1.
     */
    private Set<Integer> findUniversalNodes() {
        Set<Integer> universalNodes = new HashSet<>();
        for (int i = 0; i < numVertices; i++) {
            // A node is universal if it is connected to n-1 other nodes
            if (adjacencyList.get(i).size() == numVertices - 1) {
                universalNodes.add(i);
            }
        }
        return universalNodes;
    }

    /**
     * Finds a clique using a greedy approach.
     * Iterates through candidates and adds them to the clique if they are 
     * connected to all currently selected members of the clique.
     *
     * @param candidates Collection of candidate vertices.
     * @return A Set representing the found clique.
     */
    private Set<Integer> findGreedyClique(Collection<Integer> candidates) {
        Set<Integer> clique = new HashSet<>();
        for (Integer candidate : candidates) {
            boolean isConnectedToAllCurrentMembers = true;

            // Check connectivity against all members currently in the clique
            for (Integer member : clique) {
                if (!adjacencyList.get(candidate).contains(member)) {
                    isConnectedToAllCurrentMembers = false;
                    break;
                }
            }

            if (isConnectedToAllCurrentMembers) {
                clique.add(candidate);
            }
        }
        return clique;
    }

    /**
     * Checks if there are no edges between any node in setA and any node in setC.
     *
     * @param setA First set of vertices.
     * @param setC Second set of vertices.
     * @return true if no edges exist between the sets, false otherwise.
     */
    private boolean areDisconnected(Set<Integer> setA, Set<Integer> setC) {
        for (Integer u : setA) {
            for (Integer v : setC) {
                if (adjacencyList.get(u).contains(v)) {
                    return false; // Found an edge between A and C
                }
            }
        }
        return true;
    }

    /**
     * Prints the result in the required format.
     *
     * @param setA Set A vertices.
     * @param setB Set B vertices.
     * @param setC Set C vertices.
     */
    private void printResult(Set<Integer> setA, Set<Integer> setB, Set<Integer> setC) {
        System.out.println("Yes");

        // Use a char array for efficient construction of the output string
        char[] resultChars = new char[numVertices];

        // Fill characters based on set membership
        for (Integer node : setA) {
            resultChars[node] = 'a';
        }
        for (Integer node : setB) {
            resultChars[node] = 'b';
        }
        for (Integer node : setC) {
            resultChars[node] = 'c';
        }

        System.out.println(new String(resultChars));
    }

    public static void main(String[] args) {
        // Use try-with-resources to ensure Scanner is closed
        try (Scanner scanner = new Scanner(System.in)) {
            if (scanner.hasNextInt()) {
                int n = scanner.nextInt();
                int m = scanner.nextInt();

                GraphPartitionSolver solver = new GraphPartitionSolver(n, m, scanner);
                solver.solve();
            }
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Validates whether an undirected graph forms a complete multipartite graph
 * with at most three partitions. Outputs "Yes" and the partition assignment,
 * or "No" if the condition is not met.
 */
public class GraphPartitionValidator {

    // Color constants for partition assignment
    private static final int UNVISITED = 0;
    private static final int COLOR_A = 1;
    private static final int COLOR_B = 2;
    private static final int COLOR_C = 3;

    private int numVertices;
    private List<List<Integer>> adjacencyList;
    private int[] nodeColors;
    private FastScanner scanner;
    private PrintWriter out;

    public static void main(String[] args) {
        new GraphPartitionValidator().run();
    }

    /**
     * Entry point that initializes I/O and executes the validation logic.
     */
    void run() {
        scanner = new FastScanner(System.in);
        out = new PrintWriter(new BufferedOutputStream(System.out));

        try {
            solve();
        } catch (IOException e) {
            out.println("Error reading input: " + e.getMessage());
        } finally {
            out.flush();
            out.close();
        }
    }

    /**
     * Core logic: reads input, builds the graph, validates structure, and assigns partitions.
     */
    private void solve() throws IOException {
        numVertices = scanner.nextInt();
        adjacencyList = new ArrayList<>(numVertices);
        for (int i = 0; i < numVertices; i++) {
            adjacencyList.add(new ArrayList<>());
            adjacencyList.get(i).add(i); // Initialize with self-loop
        }

        int numEdges = scanner.nextInt();
        for (int i = 0; i < numEdges; i++) {
            int u = scanner.nextInt() - 1;
            int v = scanner.nextInt() - 1;
            if (u >= 0 && u < numVertices && v >= 0 && v < numVertices) {
                adjacencyList.get(u).add(v);
                adjacencyList.get(v).add(u);
            }
        }

        nodeColors = new int[numVertices];

        // Pre-color nodes that are connected to all other nodes (universal nodes)
        for (int i = 0; i < numVertices; i++) {
            if (adjacencyList.get(i).size() == numVertices) {
                nodeColors[i] = COLOR_B;
            }
        }

        // Assign COLOR_A to the first uncolored connected component
        for (int i = 0; i < numVertices; i++) {
            if (nodeColors[i] == UNVISITED) {
                if (!validateAndColor(i, COLOR_A)) {
                    printResult(false);
                    return;
                }
                break;
            }
        }

        // Assign COLOR_C to the next uncolored connected component
        for (int i = 0; i < numVertices; i++) {
            if (nodeColors[i] == UNVISITED) {
                if (!validateAndColor(i, COLOR_C)) {
                    printResult(false);
                    return;
                }
                break;
            }
        }

        // Verify all nodes have been assigned a partition
        for (int i = 0; i < numVertices; i++) {
            if (nodeColors[i] == UNVISITED) {
                printResult(false);
                return;
            }
        }

        printResult(true);
    }

    /**
     * Performs DFS traversal to validate graph properties and assign colors.
     * Ensures connected nodes in the same partition have identical adjacency sets.
     *
     * @param vertex  The current node being visited
     * @param color   The partition color to assign
     * @return true if validation passes, false otherwise
     */
    private boolean validateAndColor(int vertex, int color) {
        nodeColors[vertex] = color;
        for (int neighbor : adjacencyList.get(vertex)) {
            if (neighbor != vertex &&
                adjacencyList.get(neighbor).size() != numVertices &&
                nodeColors[neighbor] == UNVISITED) {

                // Validate that neighbor has matching degree and superset adjacency
                if (adjacencyList.get(neighbor).size() != adjacencyList.get(vertex).size() ||
                    !adjacencyList.get(neighbor).containsAll(adjacencyList.get(vertex))) {
                    return false;
                }

                if (!validateAndColor(neighbor, color)) {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Formats and prints the final result to the output stream.
     *
     * @param isValid true if the graph satisfies the complete multipartite condition
     */
    private void printResult(boolean isValid) {
        if (!isValid) {
            out.println("No");
            return;
        }
        out.println("Yes");
        for (int color : nodeColors) {
            out.print((char) ('a' + color - 1));
        }
        out.println();
    }

    /**
     * Fast I/O helper class optimized for competitive programming and bulk input.
     */
    private static class FastScanner {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastScanner(InputStream inputStream) {
            this.reader = new BufferedReader(new InputStreamReader(inputStream));
            this.tokenizer = null;
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(nextToken());
        }

        public long nextLong() throws IOException {
            return Long.parseLong(nextToken());
        }

        public double nextDouble() throws IOException {
            return Double.parseDouble(nextToken());
        }

        private String nextToken() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                String line = reader.readLine();
                if (line == null) {
                    throw new IOException("Unexpected end of input stream");
                }
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }
    }
}

