class GridProcessor {
    // Instance variables to avoid static state pollution between test cases
    private int n, m, k;
    private char[][] grid;
    private boolean[][] visited;
    private static final int[] DX = {0, 0, -1, 1};
    private static final int[] DY = {1, -1, 0, 0};

    void solve(FastScanner scanner) throws IOException {
        n = scanner.nextInt();
        m = scanner.nextInt();
        k = scanner.nextInt();

        grid = new char[n][m];
        for (int i = 0; i < n; i++) {
            grid[i] = scanner.next().toCharArray();
        }

        visited = new boolean[n][m];

        // 1. Mark all '.' cells connected to the border as visited
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == '.' && isBorder(i, j)) {
                    markBorderConnected(i, j);
                }
            }
        }

        // 2. Identify remaining connected components and store their sizes
        PriorityQueue<Component> components = new PriorityQueue<>();
        int totalComponents = 0;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == '.' && !visited[i][j]) {
                    int size = countComponentSize(i, j);
                    components.add(new Component(i, j, size));
                    totalComponents++;
                }
            }
        }

        // 3. Remove the smallest (totalComponents - k) components
        long totalRemovedSize = 0;
        int componentsToRemove = Math.max(0, totalComponents - k);
        for (int i = 0; i < componentsToRemove; i++) {
            Component comp = components.poll();
            totalRemovedSize += comp.size();
            removeComponent(comp.r, comp.c);
        }

        // 4. Output results
        System.out.println(totalRemovedSize);
        printGrid();
    }

    private boolean isBorder(int r, int c) {
        return r == 0 || r == n - 1 || c == 0 || c == m - 1;
    }

    private void markBorderConnected(int r, int c) {
        visited[r][c] = true;
        for (int d = 0; d < 4; d++) {
            int nr = r + DX[d];
            int nc = c + DY[d];
            if (isValid(nr, nc) && !visited[nr][nc] && grid[nr][nc] == '.') {
                markBorderConnected(nr, nc);
            }
        }
    }

    private int countComponentSize(int r, int c) {
        visited[r][c] = true;
        int count = 1;
        for (int d = 0; d < 4; d++) {
            int nr = r + DX[d];
            int nc = c + DY[d];
            if (isValid(nr, nc) && !visited[nr][nc] && grid[nr][nc] == '.') {
                count += countComponentSize(nr, nc);
            }
        }
        return count;
    }

    private void removeComponent(int r, int c) {
        // Changing '.' to '*' acts as implicit visited tracking, avoiding extra allocation
        grid[r][c] = '*';
        for (int d = 0; d < 4; d++) {
            int nr = r + DX[d];
            int nc = c + DY[d];
            if (isValid(nr, nc) && grid[nr][nc] == '.') {
                removeComponent(nr, nc);
            }
        }
    }

    private boolean isValid(int r, int c) {
        return r >= 0 && r < n && c >= 0 && c < m;
    }

    private void printGrid() {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < n; i++) {
            sb.append(grid[i]).append('\n');
        }
        System.out.print(sb);
    }
}

/**
 * Stores component metadata and defines ascending size ordering for the PriorityQueue.
 */
class Component implements Comparable<Component> {
    final int r, c, size;

    Component(int r, int c, int size) {
        this.r = r;
        this.c = c;
        this.size = size;
    }

    @Override
    public int compareTo(Component other) {
        return Integer.compare(this.size, other.size);
    }
}

/**
 * Fast I/O utility for competitive programming and performance-critical applications.
 */
class FastScanner {
    private final BufferedReader reader;
    private StringTokenizer tokenizer;

    FastScanner(InputStream stream) {
        reader = new BufferedReader(new InputStreamReader(stream), 32768);
        tokenizer = new StringTokenizer("");
    }

    String next() throws IOException {
        while (!tokenizer.hasMoreTokens()) {
            String line = reader.readLine();
            if (line == null) {
                return null;
            }
            tokenizer = new StringTokenizer(line);
        }
        return tokenizer.nextToken();
    }

    int nextInt() throws IOException {
        String s = next();
        if (s == null) throw new IOException("Unexpected end of input");
        return Integer.parseInt(s);
    }

    long nextLong() throws IOException {
        String s = next();
        if (s == null) throw new IOException("Unexpected end of input");
        return Long.parseLong(s);
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedList;
import java.util.List;
import java.util.Queue;
import java.util.StringTokenizer;

/**
 * Refactored version of CF723D.
 * 
 * Improvements made:
 * 1. Encapsulation: Moved state from static fields to instance variables. 
 *    This removes global state, making the class reusable and easier to test.
 * 2. Iterative Algorithm: Replaced recursive DFS with iterative BFS using a Queue. 
 *    This prevents StackOverflowError on large grids (e.g., 1000x1000).
 * 3. Bug Fix: Fixed the boundary check logic in the original DFS which incorrectly 
 *    returned -1 for components touching the grid edge, causing them to be ignored.
 * 4. Magic Numbers: Removed the hardcoded '50' used for ID generation and coordinate 
 *    calculation. Used a dynamic counter and stored coordinates explicitly.
 * 5. Readability: Improved variable names (cc -> grid, aa -> componentIds, L -> Component)
 *    and structured the code into logical methods.
 */
public class CF723D {

    // Inner class to store component details
    static class Component {
        int id;
        int size;
        int startR;
        int startC;

        Component(int id, int size, int startR, int startC) {
            this.id = id;
            this.size = size;
            this.startR = startR;
            this.startC = startC;
        }
    }

    private int n, m;
    private char[][] grid;
    private int[][] componentIds;
    private int currentComponentId = 1;

    public static void main(String[] args) {
        CF723D solver = new CF723D();
        try {
            solver.solve();
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    public void solve() throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter pw = new PrintWriter(System.out);

        try {
            String line = br.readLine();
            if (line == null) return;

            StringTokenizer st = new StringTokenizer(line);
            n = Integer.parseInt(st.nextToken());
            m = Integer.parseInt(st.nextToken());
            int k = Integer.parseInt(st.nextToken());

            grid = new char[n][m];
            for (int i = 0; i < n; i++) {
                String row = br.readLine();
                if (row != null && row.length() >= m) {
                    grid[i] = row.substring(0, m).toCharArray();
                } else if (row != null) {
                    // Handle short lines by padding or just taking what's there
                    char[] temp = new char[m];
                    System.arraycopy(row.toCharArray(), 0, temp, 0, row.length());
                    grid[i] = temp;
                } else {
                    grid[i] = new char[m];
                }
            }

            componentIds = new int[n][m];
            List<Component> components = new ArrayList<>();

            // Identify connected components of '.'
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    // If cell is empty and not yet assigned to a component
                    if (grid[i][j] == '.' && componentIds[i][j] == 0) {
                        int size = bfsCountComponent(i, j, currentComponentId);
                        if (size > 0) {
                            components.add(new Component(currentComponentId, size, i, j));
                            currentComponentId++;
                        }
                    }
                }
            }

            // Sort components by size in ascending order
            Collections.sort(components, (c1, c2) -> Integer.compare(c1.size, c2.size));

            int totalRemoved = 0;
            // Calculate how many smallest components to remove.
            // Original logic: remove l - k components (keep largest k).
            int componentsToRemove = Math.max(0, components.size() - k);

            for (int g = 0; g < componentsToRemove; g++) {
                Component comp = components.get(g);
                totalRemoved += comp.size;
                bfsMarkRemoved(comp.startR, comp.startC, comp.id);
            }

            pw.println(totalRemoved);
            for (int i = 0; i < n; i++) {
                pw.println(grid[i]);
            }

        } finally {
            pw.flush();
            pw.close();
        }
    }

    /**
     * Iterative BFS to count the size of a connected component and assign IDs.
     */
    private int bfsCountComponent(int startR, int startC, int id) {
        Queue<int[]> queue = new LinkedList<>();
        queue.offer(new int[]{startR, startC});
        componentIds[startR][startC] = id;

        int count = 0;
        int[] dr = {-1, 1, 0, 0};
        int[] dc = {0, 0, -1, 1};

        while (!queue.isEmpty()) {
            int[] curr = queue.poll();
            int r = curr[0];
            int c = curr[1];
            count++;

            for (int d = 0; d < 4; d++) {
                int nr = r + dr[d];
                int nc = c + dc[d];

                if (isValid(nr, nc) && grid[nr][nc] == '.' && componentIds[nr][nc] == 0) {
                    componentIds[nr][nc] = id;
                    queue.offer(new int[]{nr, nc});
                }
            }
        }
        return count;
    }

    /**
     * Iterative BFS to mark cells of a specific component as removed ('*').
     */
    private void bfsMarkRemoved(int startR, int startC, int targetId) {
        Queue<int[]> queue = new LinkedList<>();
        queue.offer(new int[]{startR, startC});

        // Mark start node immediately to prevent re-processing
        grid[startR][startC] = '*';

        int[] dr = {-1, 1, 0, 0};
        int[] dc = {0, 0, -1, 1};

        while (!queue.isEmpty()) {
            int[] curr = queue.poll();
            int r = curr[0];
            int c = curr[1];

            for (int d = 0; d < 4; d++) {
                int nr = r + dr[d];
                int nc = c + dc[d];

                // Check bounds, if it's an empty cell belonging to the target component
                if (isValid(nr, nc) && grid[nr][nc] == '.' && componentIds[nr][nc] == targetId) {
                    grid[nr][nc] = '*'; // Mark as visited/removed
                    queue.offer(new int[]{nr, nc});
                }
            }
        }
    }

    private boolean isValid(int r, int c) {
        return r >= 0 && r < n && c >= 0 && c < m;
    }
}

import java.io.BufferedInputStream;
import java.io.BufferedOutputStream;
import java.io.PrintWriter;
import java.util.ArrayDeque;
import java.util.HashSet;
import java.util.PriorityQueue;
import java.util.Queue;
import java.util.Scanner;
import java.util.Set;

public class Main {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(new BufferedInputStream(System.in));
        PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out));

        try {
            if (!scanner.hasNextInt()) return;
            int rows = scanner.nextInt();
            int cols = scanner.nextInt();
            int k = scanner.nextInt();

            char[][] grid = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                grid[i] = scanner.next().toCharArray();
            }

            GridSolver solver = new GridSolver(rows, cols, grid);
            solver.solve(k, out);
        } finally {
            out.flush();
            scanner.close();
        }
    }

    /**
     * Encapsulates grid processing logic to avoid global state and improve maintainability.
     */
    private static class GridSolver {
        private static final int[][] DIRECTIONS = {{-1, 0}, {1, 0}, {0, 1}, {0, -1}};
        private final int rows;
        private final int cols;
        private final char[][] grid;
        private final int[][] visited;
        private int componentIdCounter;
        private final PriorityQueue<ComponentInfo> validComponents;

        public GridSolver(int rows, int cols, char[][] grid) {
            this.rows = rows;
            this.cols = cols;
            this.grid = grid;
            this.visited = new int[rows][cols];
            this.componentIdCounter = 1;
            this.validComponents = new PriorityQueue<>();
        }

        public void solve(int k, PrintWriter out) {
            int validComponentCount = 0;

            // Only start BFS from interior cells to match original logic
            for (int i = 1; i < rows - 1; i++) {
                for (int j = 1; j < cols - 1; j++) {
                    if (visited[i][j] == 0 && grid[i][j] == '.') {
                        componentIdCounter++;
                        int componentSize = bfs(i, j);
                        if (componentSize != -1) {
                            validComponentCount++;
                            validComponents.add(new ComponentInfo(componentSize, componentIdCounter));
                        }
                    }
                }
            }

            if (validComponentCount == k) {
                out.println(0);
                printGrid(out);
            } else {
                int componentsToRemove = validComponentCount - k;
                Set<Integer> removedComponentIds = new HashSet<>();
                int removedCellsCount = 0;

                // Remove the smallest valid components until we reach the target count
                while (componentsToRemove > 0 && !validComponents.isEmpty()) {
                    ComponentInfo component = validComponents.poll();
                    removedComponentIds.add(component.id);
                    removedCellsCount += component.size;
                    componentsToRemove--;
                }

                out.println(removedCellsCount);
                printModifiedGrid(out, removedComponentIds);
            }
        }

        /**
         * Iterative BFS to find connected '.' components.
         * Returns -1 if the component touches the grid boundary, otherwise returns its size.
         */
        private int bfs(int startRow, int startCol) {
            Queue<int[]> queue = new ArrayDeque<>();
            queue.offer(new int[]{startRow, startCol});
            visited[startRow][startCol] = componentIdCounter;

            int size = 0;
            boolean touchesBoundary = false;

            while (!queue.isEmpty()) {
                int[] current = queue.poll();
                int r = current[0];
                int c = current[1];
                size++;

                if (r == 0 || r == rows - 1 || c == 0 || c == cols - 1) {
                    touchesBoundary = true;
                }

                for (int[] dir : DIRECTIONS) {
                    int nr = r + dir[0];
                    int nc = c + dir[1];

                    if (nr >= 0 && nr < rows && nc >= 0 && nc < cols &&
                        visited[nr][nc] == 0 && grid[nr][nc] == '.') {
                        visited[nr][nc] = componentIdCounter;
                        queue.offer(new int[]{nr, nc});
                    }
                }
            }

            return touchesBoundary ? -1 : size;
        }

        private void printGrid(PrintWriter out) {
            for (char[] row : grid) {
                out.println(row);
            }
        }

        private void printModifiedGrid(PrintWriter out, Set<Integer> removedComponentIds) {
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (removedComponentIds.contains(visited[i][j])) {
                        out.print('*');
                    } else {
                        out.print(grid[i][j]);
                    }
                }
                out.println();
            }
        }

        /**
         * Represents a valid interior component with its size and unique ID.
         */
        private static class ComponentInfo implements Comparable<ComponentInfo> {
            final int size;
            final int id;

            ComponentInfo(int size, int id) {
                this.size = size;
                this.id = id;
            }

            @Override
            public int compareTo(ComponentInfo other) {
                return Integer.compare(this.size, other.size);
            }
        }
    }
}

import java.util.*;

public class GridChecker {
    private static final int[] DR = {-1, 1, 0, 0};
    private static final int[] DC = {0, 0, -1, 1};

    private final int rows;
    private final int cols;
    private final int k;
    private char[][] grid;
    private boolean[][] visited;

    /** Simple immutable coordinate holder */
    private static class Coordinate {
        final int row;
        final int col;
        Coordinate(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    public GridChecker(int rows, int cols, int k, char[][] grid) {
        this.rows = rows;
        this.cols = cols;
        this.k = k;
        this.grid = grid;
        this.visited = new boolean[rows][cols];
    }

    /** Checks if a cell is within bounds and is an unmarked path */
    private boolean isValid(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols && grid[r][c] == '.';
    }

    /** Orchestrates the grid processing pipeline */
    public void process() {
        markBorderConnectedComponents();
        List<List<Coordinate>> components = findInteriorComponents();

        // Sort components by size (smallest first)
        Collections.sort(components, Comparator.comparingInt(List::size));

        int componentsToRemove = Math.max(0, components.size() - k);
        int totalRemoved = 0;

        // Mark the smallest components as removed
        for (int i = 0; i < componentsToRemove && i < components.size(); i++) {
            for (Coordinate coord : components.get(i)) {
                grid[coord.row][coord.col] = '*';
                totalRemoved++;
            }
        }

        revertBorderMarks();
        System.out.println(totalRemoved);
        printGrid();
    }

    /** Marks all '.' cells connected to the border with '+' */
    private void markBorderConnectedComponents() {
        // Top and bottom rows
        for (int c = 0; c < cols; c++) {
            if (grid[0][c] == '.') markComponent(0, c);
            if (grid[rows - 1][c] == '.') markComponent(rows - 1, c);
        }
        // Left and right columns
        for (int r = 0; r < rows; r++) {
            if (grid[r][0] == '.') markComponent(r, 0);
            if (grid[r][cols - 1] == '.') markComponent(r, cols - 1);
        }
    }

    /** Iterative DFS to mark a connected component */
    private void markComponent(int r, int c) {
        Deque<Coordinate> stack = new ArrayDeque<>();
        stack.push(new Coordinate(r, c));
        grid[r][c] = '+';

        while (!stack.isEmpty()) {
            Coordinate curr = stack.pop();
            for (int i = 0; i < 4; i++) {
                int nr = curr.row + DR[i];
                int nc = curr.col + DC[i];
                if (isValid(nr, nc)) {
                    grid[nr][nc] = '+';
                    stack.push(new Coordinate(nr, nc));
                }
            }
        }
    }

    /** Finds all remaining interior connected components of '.' */
    private List<List<Coordinate>> findInteriorComponents() {
        List<List<Coordinate>> components = new ArrayList<>();
        // Reset visited array for interior search
        for (int i = 0; i < rows; i++) {
            Arrays.fill(visited[i], false);
        }

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '.' && !visited[r][c]) {
                    List<Coordinate> component = new ArrayList<>();
                    findComponentDFS(r, c, component);
                    components.add(component);
                }
            }
        }
        return components;
    }

    /** Iterative DFS to collect cells belonging to an interior component */
    private void findComponentDFS(int r, int c, List<Coordinate> component) {
        Deque<Coordinate> stack = new ArrayDeque<>();
        stack.push(new Coordinate(r, c));
        visited[r][c] = true;
        component.add(new Coordinate(r, c));

        while (!stack.isEmpty()) {
            Coordinate curr = stack.pop();
            for (int i = 0; i < 4; i++) {
                int nr = curr.row + DR[i];
                int nc = curr.col + DC[i];
                if (nr >= 0 && nr < rows && nc >= 0 && nc < cols &&
                    grid[nr][nc] == '.' && !visited[nr][nc]) {
                    visited[nr][nc] = true;
                    component.add(new Coordinate(nr, nc));
                    stack.push(new Coordinate(nr, nc));
                }
            }
        }
    }

    /** Reverts temporary '+' border marks back to '.' */
    private void revertBorderMarks() {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '+') {
                    grid[r][c] = '.';
                }
            }
        }
    }

    /** Prints the final grid state */
    private void printGrid() {
        for (char[] row : grid) {
            System.out.println(new String(row));
        }
    }

    public static void main(String[] args) {
        try (Scanner sc = new Scanner(System.in)) {
            if (!sc.hasNextInt()) return;
            int n = sc.nextInt();
            int m = sc.nextInt();
            int k = sc.nextInt();

            char[][] grid = new char[n][m];
            for (int i = 0; i < n; i++) {
                grid[i] = sc.next().toCharArray();
            }

            GridChecker checker = new GridChecker(n, m, k, grid);
            checker.process();
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.Queue;
import java.util.StringTokenizer;

public class Main {

    /**
     * FastScanner for efficient and maintainable input reading.
     * Replaces the custom FastInput with a standard, robust implementation.
     */
    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        public String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) {
                        return null;
                    }
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input", e);
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            String token = next();
            return token == null ? 0 : Integer.parseInt(token);
        }
    }

    /**
     * Encapsulates a connected component of '.' cells.
     * Tracks all cells in the component and whether it touches the grid boundary.
     */
    static class Component {
        final List<int[]> cells = new ArrayList<>();
        boolean touchesBoundary = false;
    }

    public static void main(String[] args) {
        Main solver = new Main();
        solver.solve();
    }

    public void solve() {
        FastScanner scanner = new FastScanner();
        int rows = scanner.nextInt();
        int cols = scanner.nextInt();
        int k = scanner.nextInt();

        char[][] grid = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            String rowStr = scanner.next();
            grid[i] = rowStr.toCharArray();
        }

        boolean[][] visited = new boolean[rows][cols];
        List<Component> lakes = new ArrayList<>();

        // Direction vectors for BFS: up, down, left, right
        int[] dr = {-1, 1, 0, 0};
        int[] dc = {0, 0, -1, 1};

        // Iterate over each cell to discover connected components
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '.' && !visited[r][c]) {
                    Component component = new Component();
                    bfs(r, c, rows, cols, grid, visited, component, dr, dc);

                    // A "lake" is defined as a component that does NOT touch the boundary
                    if (!component.touchesBoundary) {
                        lakes.add(component);
                    }
                }
            }
        }

        // Sort lakes by size in ascending order
        lakes.sort(Comparator.comparingInt(c -> c.cells.size()));

        int changedCellCount = 0;
        // Remove the smallest lakes until only k remain
        while (lakes.size() > k) {
            Component smallestLake = lakes.remove(0);
            for (int[] cell : smallestLake.cells) {
                grid[cell[0]][cell[1]] = '*';
                changedCellCount++;
            }
        }

        // Output results
        System.out.println(changedCellCount);
        StringBuilder output = new StringBuilder();
        for (int r = 0; r < rows; r++) {
            output.append(grid[r]).append('\n');
        }
        System.out.print(output);
    }

    /**
     * Performs BFS to find all cells in the connected component starting from (startR, startC).
     * Marks visited cells and updates boundary status.
     */
    private void bfs(int startR, int startC, int rows, int cols,
                     char[][] grid, boolean[][] visited,
                     Component component, int[] dr, int[] dc) {
        Queue<int[]> queue = new ArrayDeque<>();
        queue.add(new int[]{startR, startC});
        visited[startR][startC] = true;
        component.cells.add(new int[]{startR, startC});

        if (isOnBoundary(startR, startC, rows, cols)) {
            component.touchesBoundary = true;
        }

        while (!queue.isEmpty()) {
            int[] current = queue.poll();
            int r = current[0];
            int c = current[1];

            for (int i = 0; i < 4; i++) {
                int nr = r + dr[i];
                int nc = c + dc[i];

                if (nr >= 0 && nr < rows && nc >= 0 && nc < cols &&
                    grid[nr][nc] == '.' && !visited[nr][nc]) {
                    visited[nr][nc] = true;
                    component.cells.add(new int[]{nr, nc});
                    if (isOnBoundary(nr, nc, rows, cols)) {
                        component.touchesBoundary = true;
                    }
                    queue.add(new int[]{nr, nc});
                }
            }
        }
    }

    /**
     * Checks if a cell lies on the boundary of the grid.
     */
    private boolean isOnBoundary(int r, int c, int rows, int cols) {
        return r == 0 || r == rows - 1 || c == 0 || c == cols - 1;
    }
}

import java.util.ArrayList;
import java.util.ArrayDeque;
import java.util.Comparator;
import java.util.Deque;
import java.util.List;
import java.util.Scanner;

public class Main {
    // Direction vectors for moving up, down, left, right
    private static final int[] DX = {-1, 1, 0, 0};
    private static final int[] DY = {0, 0, -1, 1};

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        if (!scanner.hasNextInt()) return;

        int rows = scanner.nextInt();
        int cols = scanner.nextInt();
        int k = scanner.nextInt();
        scanner.nextLine(); // Consume the newline left after reading k

        char[][] grid = readGrid(scanner, rows, cols);
        boolean[][] visited = new boolean[rows][cols];
        List<Lake> lakes = findLakes(grid, visited);

        int transformedCount = removeExcessLakes(grid, lakes, k);

        printResult(transformedCount, grid);
    }

    /**
     * Reads the grid from standard input.
     */
    private static char[][] readGrid(Scanner scanner, int rows, int cols) {
        char[][] grid = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            String line = scanner.nextLine();
            // Handle potential empty lines or shorter lines gracefully
            for (int j = 0; j < cols && j < line.length(); j++) {
                grid[i][j] = line.charAt(j);
            }
        }
        return grid;
    }

    /**
     * Scans the grid to find all connected water components.
     * Identifies which components are "lakes" (do not touch the boundary).
     */
    private static List<Lake> findLakes(char[][] grid, boolean[][] visited) {
        List<Lake> lakes = new ArrayList<>();
        for (int i = 0; i < grid.length; i++) {
            for (int j = 0; j < grid[i].length; j++) {
                if (grid[i][j] == '.' && !visited[i][j]) {
                    List<Point> cells = new ArrayList<>();
                    boolean isLake = dfs(grid, visited, i, j, cells);
                    if (isLake) {
                        lakes.add(new Lake(cells));
                    }
                }
            }
        }
        return lakes;
    }

    /**
     * Iterative DFS to traverse a connected component of '.' cells.
     * Returns true if the component does not touch the grid boundary.
     */
    private static boolean dfs(char[][] grid, boolean[][] visited, int startX, int startY, List<Point> cells) {
        boolean isLake = true;
        Deque<Point> stack = new ArrayDeque<>();
        stack.push(new Point(startX, startY));
        visited[startX][startY] = true;
        cells.add(new Point(startX, startY));

        while (!stack.isEmpty()) {
            Point current = stack.pop();
            for (int d = 0; d < 4; d++) {
                int nx = current.x + DX[d];
                int ny = current.y + DY[d];

                // Check if neighbor is out of bounds
                if (nx < 0 || nx >= grid.length || ny < 0 || ny >= grid[0].length) {
                    isLake = false;
                    continue;
                }

                // Explore unvisited water cells
                if (!visited[nx][ny] && grid[nx][ny] == '.') {
                    visited[nx][ny] = true;
                    cells.add(new Point(nx, ny));
                    stack.push(new Point(nx, ny));
                }
            }
        }
        return isLake;
    }

    /**
     * Removes excess lakes by transforming the smallest ones into land ('*').
     */
    private static int removeExcessLakes(char[][] grid, List<Lake> lakes, int k) {
        int excessCount = lakes.size() - k;
        if (excessCount <= 0) return 0;

        // Sort lakes by size (ascending) to remove the smallest ones first
        lakes.sort(Comparator.comparingInt(lake -> lake.cells.size()));
        int transformedCount = 0;

        for (int i = 0; i < excessCount; i++) {
            Lake lake = lakes.get(i);
            transformedCount += lake.cells.size();
            for (Point p : lake.cells) {
                grid[p.x][p.y] = '*';
            }
        }
        return transformedCount;
    }

    /**
     * Prints the number of transformed cells and the modified grid.
     */
    private static void printResult(int transformedCount, char[][] grid) {
        System.out.println(transformedCount);
        for (char[] row : grid) {
            System.out.println(new String(row));
        }
    }

    /** Represents a coordinate in the grid */
    private static class Point {
        final int x;
        final int y;

        Point(int x, int y) {
            this.x = x;
            this.y = y;
        }
    }

    /** Represents a connected component of water cells */
    private static class Lake {
        final List<Point> cells;

        Lake(List<Point> cells) {
            this.cells = cells;
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.StringTokenizer;

/**
 * Refactored solution for Training2_C.
 * 
 * Improvements made:
 * 1. Encapsulation: Moved logic into a class structure to avoid excessive static state.
 * 2. Data Structures: Replaced parallel arrays (arr, arr1, arr2) with a dedicated 'Island' class 
 *    to group related data (size, coordinates, boundary status).
 * 3. Performance: Removed the inefficient re-allocation of the 'visited' array inside the removal loop.
 * 4. Readability: Renamed variables (e.g., 'ret' -> 'outputGrid', 'oceanCon' -> 'touchesBoundary') 
 *    and added comments to explain the logic.
 * 5. Robustness: Added basic input validation and used StringBuilder for efficient output.
 * 6. Logic Optimization: Sorted inland islands by size to easily select the smallest ones for removal,
 *    replacing the O(N^2) scanning logic of the original code.
 */
public class Training2_C {

    // Grid dimensions
    static int rows, cols;

    // Grid states
    // grid: Original input state (true for '.', false for others)
    static boolean[][] grid;
    // outputGrid: Final state to be printed (true for '.', false for '*')
    static boolean[][] outputGrid;
    // visited: Tracks visited cells during component discovery
    static boolean[][] visited;

    // Direction vectors for moving up, right, down, left
    static final int[] DR = {-1, 0, 0, 1};
    static final int[] DC = {0, 1, -1, 0};

    /**
     * Represents a connected component of water cells (island/lake).
     */
    static class Island {
        int size;
        int startR, startC;
        boolean touchesBoundary;

        public Island(int r, int c) {
            this.startR = r;
            this.startC = c;
            this.size = 0;
            this.touchesBoundary = false;
        }
    }

    public static void main(String[] args) throws IOException {
        // Use BufferedReader for efficient input reading
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st;
        String line;

        // Read N, M, K
        line = br.readLine();
        if (line == null) return;
        st = new StringTokenizer(line);
        if (!st.hasMoreTokens()) return;

        rows = Integer.parseInt(st.nextToken());
        cols = Integer.parseInt(st.nextToken());
        int k = Integer.parseInt(st.nextToken());

        // Initialize grids
        grid = new boolean[rows][cols];
        outputGrid = new boolean[rows][cols];
        visited = new boolean[rows][cols];

        // Read Grid
        for (int i = 0; i < rows; i++) {
            line = br.readLine();
            if (line == null) break;

            // The original code used StringTokenizer to parse the row string.
            // Assuming the row is provided as a single token string (e.g., "....").
            st = new StringTokenizer(line);
            String rowStr = "";
            if (st.hasMoreTokens()) {
                rowStr = st.nextToken();
            }

            for (int j = 0; j < cols; j++) {
                // Safety check to prevent IndexOutOfBounds if rowStr is short
                if (j < rowStr.length()) {
                    char c = rowStr.charAt(j);
                    boolean isWater = (c == '.');
                    grid[i][j] = isWater;
                    outputGrid[i][j] = isWater;
                } else {
                    // Default to non-water if input is malformed/short
                    grid[i][j] = false;
                    outputGrid[i][j] = false;
                }
            }
        }
        br.close();

        // Step 1: Identify all connected components (Islands)
        List<Island> inlandIslands = new ArrayList<>();

        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                // If cell is water and not yet visited
                if (grid[i][j] && !visited[i][j]) {
                    Island island = new Island(i, j);
                    dfsFind(i, j, island);

                    // Only consider inland islands (those not touching the boundary)
                    if (!island.touchesBoundary) {
                        inlandIslands.add(island);
                    }
                }
            }
        }

        // Step 2: Sort inland islands by size (ascending)
        // This allows us to easily remove the smallest ones
        Collections.sort(inlandIslands, (a, b) -> Integer.compare(a.size, b.size));

        // Step 3: Determine how many to remove
        // Logic from original: remove (len - k) smallest islands.
        // If len < k, remove 0.
        int numInland = inlandIslands.size();
        int removeCount = Math.max(0, numInland - k);

        long totalRemovedArea = 0;

        // Step 4: Remove the smallest islands
        for (int i = 0; i < removeCount; i++) {
            Island target = inlandIslands.get(i);
            totalRemovedArea += target.size;
            removeIsland(target.startR, target.startC);
        }

        // Step 5: Output results
        StringBuilder sb = new StringBuilder();
        sb.append(totalRemovedArea).append("\n");

        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (outputGrid[i][j]) {
                    sb.append(".");
                } else {
                    sb.append("*");
                }
            }
            sb.append("\n");
        }
        System.out.println(sb);
    }

    /**
     * DFS to find the size and boundary status of a connected component.
     * Marks cells as visited.
     */
    private static void dfsFind(int r, int c, Island island) {
        visited[r][c] = true;
        island.size++;

        // Check if this cell is on the boundary
        if (r == 0 || r == rows - 1 || c == 0 || c == cols - 1) {
            island.touchesBoundary = true;
        }

        // Explore neighbors
        for (int i = 0; i < 4; i++) {
            int nr = r + DR[i];
            int nc = c + DC[i];

            if (isValid(nr, nc) && grid[nr][nc] && !visited[nr][nc]) {
                dfsFind(nr, nc, island);
            }
        }
    }

    /**
     * Recursively marks a connected component as removed (sets to false in outputGrid).
     * Uses outputGrid state to prevent re-processing (acts as visited check).
     */
    private static void removeIsland(int r, int c) {
        // Base cases: out of bounds or not water (already removed or land)
        if (!isValid(r, c) || !outputGrid[r][c]) {
            return;
        }

        // Mark as removed
        outputGrid[r][c] = false;

        // Recurse neighbors
        for (int i = 0; i < 4; i++) {
            removeIsland(r + DR[i], c + DC[i]);
        }
    }

    /**
     * Checks if coordinates are within grid bounds.
     */
    private static boolean isValid(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }
}

import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;
import java.util.TreeMap;

/**
 * Solves the "Lakes in Berland" problem by identifying lakes in a grid,
 * keeping the k largest ones, and filling the rest with '*' characters.
 */
public final class LakesInBerland {

    private static final char WATER = '.';
    private static final char BORDER_WATER = '$';
    private static final char FILLED = '*';

    /**
     * Processes the grid to keep the k largest lakes and fills the rest.
     *
     * @param matrix The input grid containing water ('.') and land.
     * @param k      The number of largest lakes to preserve.
     * @return A result object containing the modified matrix and the total area of filled lakes.
     */
    public static LakeResult minimalLake(char[][] matrix, int k) {
        if (matrix == null || matrix.length == 0 || matrix[0].length == 0) {
            return new LakeResult(matrix, 0);
        }

        TreeMap<Integer, List<int[]>> lakeSizes = new TreeMap<>();

        // Step 1: Mark all water connected to the border (these are not lakes)
        markBorderConnectedWater(matrix);

        // Step 2: Identify remaining lakes and store their sizes & starting coordinates
        findLakes(matrix, lakeSizes);

        // Step 3: Remove the smallest lakes until only k largest remain
        int totalLakes = lakeSizes.values().stream().mapToInt(List::size).sum();
        int lakesToRemove = Math.max(0, totalLakes - k);
        int totalRemovedArea = 0;

        if (lakesToRemove > 0) {
            totalRemovedArea = removeSmallestLakes(matrix, lakeSizes, lakesToRemove);
        }

        return new LakeResult(matrix, totalRemovedArea);
    }

    private static void markBorderConnectedWater(char[][] matrix) {
        int rows = matrix.length;
        int cols = matrix[0].length;

        for (int i = 0; i < rows; i++) {
            if (matrix[i][0] == WATER) floodFill(matrix, i, 0, BORDER_WATER);
            if (matrix[i][cols - 1] == WATER) floodFill(matrix, i, cols - 1, BORDER_WATER);
        }

        for (int j = 0; j < cols; j++) {
            if (matrix[0][j] == WATER) floodFill(matrix, 0, j, BORDER_WATER);
            if (matrix[rows - 1][j] == WATER) floodFill(matrix, rows - 1, j, BORDER_WATER);
        }
    }

    private static void findLakes(char[][] matrix, TreeMap<Integer, List<int[]>> lakeSizes) {
        int rows = matrix.length;
        int cols = matrix[0].length;
        boolean[][] visited = new boolean[rows][cols];

        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (matrix[i][j] == WATER && !visited[i][j]) {
                    int[] size = new int[1];
                    countLakeSize(matrix, i, j, visited, size);
                    lakeSizes.computeIfAbsent(size[0], sizeKey -> new ArrayList<>())
                             .add(new int[]{i, j});
                }
            }
        }
    }

    private static int removeSmallestLakes(char[][] matrix, TreeMap<Integer, List<int[]>> lakeSizes, int count) {
        int removedArea = 0;
        int toRemove = count;

        // TreeMap iterates keys in ascending order (smallest lakes first)
        for (var entry : lakeSizes.entrySet()) {
            if (toRemove <= 0) break;

            int size = entry.getKey();
            List<int[]> starts = entry.getValue();

            for (int[] start : starts) {
                if (toRemove <= 0) break;
                floodFill(matrix, start[0], start[1], FILLED);
                removedArea += size;
                toRemove--;
            }
        }
        return removedArea;
    }

    /**
     * Recursively fills connected water cells with the target character.
     */
    private static void floodFill(char[][] matrix, int i, int j, char fillChar) {
        if (i < 0 || j < 0 || i >= matrix.length || j >= matrix[0].length || matrix[i][j] != WATER) {
            return;
        }
        matrix[i][j] = fillChar;
        floodFill(matrix, i, j - 1, fillChar);
        floodFill(matrix, i - 1, j, fillChar);
        floodFill(matrix, i, j + 1, fillChar);
        floodFill(matrix, i + 1, j, fillChar);
    }

    /**
     * Recursively counts the size of a lake and marks visited cells.
     */
    private static void countLakeSize(char[][] matrix, int i, int j, boolean[][] visited, int[] size) {
        size[0]++;
        visited[i][j] = true;

        int[] di = {-1, 1, 0, 0};
        int[] dj = {0, 0, -1, 1};
        int rows = matrix.length;
        int cols = matrix[0].length;

        for (int d = 0; d < 4; d++) {
            int ni = i + di[d];
            int nj = j + dj[d];
            if (ni >= 0 && nj >= 0 && ni < rows && nj < cols && matrix[ni][nj] == WATER && !visited[ni][nj]) {
                countLakeSize(matrix, ni, nj, visited, size);
            }
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        if (!sc.hasNextInt()) return;

        int n = sc.nextInt();
        int m = sc.nextInt();
        int k = sc.nextInt();
        sc.nextLine(); // consume the newline after k

        char[][] matrix = new char[n][m];
        for (int i = 0; i < n; i++) {
            String row = sc.nextLine();
            matrix[i] = row.toCharArray();
        }

        LakeResult result = minimalLake(matrix, k);
        System.out.println(result.sum);

        for (char[] row : result.matrix) {
            for (char c : row) {
                System.out.print(c == BORDER_WATER ? WATER : c);
            }
            System.out.println();
        }
    }

    /**
     * Immutable record to encapsulate the method's output.
     */
    public static class LakeResult {
        private final char[][] matrix;
        private final int sum;

        public LakeResult(char[][] matrix, int sum) {
            this.matrix = matrix;
            this.sum = sum;
        }

        public char[][] getMatrix() {
            return matrix;
        }

        public int getSum() {
            return sum;
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.LinkedList;
import java.util.List;
import java.util.Queue;
import java.util.StringTokenizer;

/**
 * Solves the lake removal problem by identifying isolated water bodies (lakes)
 * in a grid and converting the smallest ones to land if their count exceeds a threshold.
 */
public class LakeSolver {

    // Direction vectors for 4-way movement (right, left, down, up)
    private static final int[] DX = {0, 0, 1, -1};
    private static final int[] DY = {1, -1, 0, 0};

    /** Represents a coordinate in the grid. */
    private static class Point {
        final int x, y;
        Point(int x, int y) {
            this.x = x;
            this.y = y;
        }
    }

    /** Represents a connected lake component. */
    private static class Lake {
        final int size;
        final List<Point> coordinates;
        Lake(int size, List<Point> coordinates) {
            this.size = size;
            this.coordinates = coordinates;
        }
    }

    // Instance state replaces static fields for better encapsulation and testability
    private final int rows, cols;
    private final char[][] grid;
    private final boolean[][] visited;

    public LakeSolver(int rows, int cols) {
        this.rows = rows;
        this.cols = cols;
        this.grid = new char[rows][cols];
        this.visited = new boolean[rows][cols];
    }

    /** Reads the grid from the provided BufferedReader. */
    public void readGrid(BufferedReader reader) throws IOException {
        for (int i = 0; i < rows; i++) {
            String line = reader.readLine();
            if (line == null) {
                throw new IOException("Unexpected end of input while reading grid rows.");
            }
            grid[i] = line.toCharArray();
        }
    }

    /** Checks if a point lies on the border of the grid. */
    private boolean isOnBorder(Point p) {
        return p.x == 0 || p.x == rows - 1 || p.y == 0 || p.y == cols - 1;
    }

    /**
     * Performs BFS to find all connected '.' cells starting from 'start'.
     * Populates the component list and marks visited cells.
     */
    private void bfsFindComponent(Point start, List<Point> component) {
        Queue<Point> queue = new LinkedList<>();
        queue.add(start);
        visited[start.x][start.y] = true;
        component.add(start);

        while (!queue.isEmpty()) {
            Point curr = queue.poll();
            for (int i = 0; i < 4; i++) {
                int nx = curr.x + DX[i];
                int ny = curr.y + DY[i];

                if (nx >= 0 && nx < rows && ny >= 0 && ny < cols &&
                    !visited[nx][ny] && grid[nx][ny] == '.') {
                    visited[nx][ny] = true;
                    Point next = new Point(nx, ny);
                    queue.add(next);
                    component.add(next);
                }
            }
        }
    }

    /**
     * Scans the grid to identify all lakes.
     * A lake is a connected component of '.' that does not touch the grid border.
     */
    public List<Lake> findLakes() {
        List<Lake> lakes = new ArrayList<>();
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == '.' && !visited[i][j]) {
                    List<Point> component = new ArrayList<>();
                    bfsFindComponent(new Point(i, j), component);

                    boolean isLake = true;
                    for (Point p : component) {
                        if (isOnBorder(p)) {
                            isLake = false;
                            break;
                        }
                    }

                    if (isLake) {
                        lakes.add(new Lake(component.size(), component));
                    }
                }
            }
        }
        return lakes;
    }

    /**
     * Removes the smallest lakes until the total count equals k.
     * Changes '.' to '*' for removed lake cells and prints the number of modified cells.
     */
    public void removeLakes(List<Lake> lakes, int k) {
        if (lakes.size() <= k) {
            System.out.println(0);
            return;
        }

        int lakesToRemove = lakes.size() - k;
        // Sort lakes by size in ascending order
        lakes.sort(Comparator.comparingInt(l -> l.size));

        int removedCount = 0;
        for (int i = 0; i < lakesToRemove; i++) {
            Lake lake = lakes.get(i);
            for (Point p : lake.coordinates) {
                grid[p.x][p.y] = '*';
                removedCount++;
            }
        }
        System.out.println(removedCount);
    }

    /** Prints the final grid state to standard output. */
    public void printGrid() {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < rows; i++) {
            sb.append(grid[i]).append('\n');
        }
        System.out.print(sb);
    }

    public static void main(String[] args) throws IOException {
        // Use BufferedReader + StringTokenizer for robust and fast I/O
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        String line = reader.readLine();
        if (line == null) return;

        StringTokenizer st = new StringTokenizer(line);
        int rows = Integer.parseInt(st.nextToken());
        int cols = Integer.parseInt(st.nextToken());
        int k = Integer.parseInt(st.nextToken());

        LakeSolver solver = new LakeSolver(rows, cols);
        solver.readGrid(reader);

        List<Lake> lakes = solver.findLakes();
        solver.removeLakes(lakes, k);
        solver.printGrid();
    }
}

import java.util.*;

public class Solution {
    // Direction vectors for moving down, up, right, left
    private static final int[] DR = {1, -1, 0, 0};
    private static final int[] DC = {0, 0, 1, -1};

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        if (!scanner.hasNextInt()) return;

        int rows = scanner.nextInt();
        int cols = scanner.nextInt();
        int k = scanner.nextInt();

        char[][] grid = new char[rows][cols];
        char[][] gridModified = new char[rows][cols];
        boolean[][] visited = new boolean[rows][cols];

        // Read grid input
        for (int i = 0; i < rows; i++) {
            String line = scanner.next();
            for (int j = 0; j < cols; j++) {
                grid[i][j] = line.charAt(j);
                gridModified[i][j] = line.charAt(j);
            }
        }

        // PriorityQueue to store non-boundary components, ordered by size (smallest first)
        PriorityQueue<Component> priorityQueue = new PriorityQueue<>(Comparator.comparingInt(c -> c.size));

        // Find all connected components of '.'
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == '.' && !visited[i][j]) {
                    Component component = new Component();
                    findConnectedComponent(i, j, rows, cols, grid, visited, component);
                    // Only add components that do not touch the grid boundary
                    if (!component.isOnBoundary) {
                        priorityQueue.add(new Component(i, j, component.size));
                    }
                }
            }
        }

        // Remove the smallest k components
        int totalRemoved = 0;
        int componentsToProcess = Math.min(k, priorityQueue.size());

        for (int i = 0; i < componentsToProcess; i++) {
            Component component = priorityQueue.poll();
            totalRemoved += component.size;
            removeConnectedComponent(component.startX, component.startY, rows, cols, grid, gridModified, new boolean[rows][cols]);
        }

        // Output results
        System.out.println(totalRemoved);
        for (int i = 0; i < rows; i++) {
            System.out.println(new String(gridModified[i]));
        }
    }

    /**
     * Iteratively finds a connected component of '.' cells.
     * Populates the Component object with size and boundary status.
     */
    private static void findConnectedComponent(int startR, int startC, int rows, int cols, char[][] grid, boolean[][] visited, Component comp) {
        Deque<int[]> stack = new ArrayDeque<>();
        stack.push(new int[]{startR, startC});
        visited[startR][startC] = true;
        comp.size = 0;
        comp.isOnBoundary = false;

        while (!stack.isEmpty()) {
            int[] current = stack.pop();
            int r = current[0];
            int c = current[1];

            comp.size++;
            if (r == 0 || r == rows - 1 || c == 0 || c == cols - 1) {
                comp.isOnBoundary = true;
            }

            for (int d = 0; d < 4; d++) {
                int nr = r + DR[d];
                int nc = c + DC[d];
                if (isWithinBounds(nr, nc, rows, cols) && !visited[nr][nc] && grid[nr][nc] == '.') {
                    visited[nr][nc] = true;
                    stack.push(new int[]{nr, nc});
                }
            }
        }
    }

    /**
     * Iteratively removes (marks as '*') a connected component in gridModified.
     */
    private static void removeConnectedComponent(int startR, int startC, int rows, int cols, char[][] grid, char[][] gridModified, boolean[][] visited) {
        Deque<int[]> stack = new ArrayDeque<>();
        stack.push(new int[]{startR, startC});
        visited[startR][startC] = true;
        gridModified[startR][startC] = '*';

        while (!stack.isEmpty()) {
            int[] current = stack.pop();
            int r = current[0];
            int c = current[1];

            for (int d = 0; d < 4; d++) {
                int nr = r + DR[d];
                int nc = c + DC[d];
                if (isWithinBounds(nr, nc, rows, cols) && !visited[nr][nc] && grid[nr][nc] == '.') {
                    visited[nr][nc] = true;
                    gridModified[nr][nc] = '*';
                    stack.push(new int[]{nr, nc});
                }
            }
        }
    }

    private static boolean isWithinBounds(int r, int c, int rows, int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /**
     * Represents a connected component of '.' cells.
     */
    private static class Component {
        int startX, startY, size;
        boolean isOnBoundary;

        Component() {}

        Component(int startX, int startY, int size) {
            this.startX = startX;
            this.startY = startY;
            this.size = size;
        }
    }
}

import java.io.*;
import java.util.*;

public class CF732D {

    /**
     * FastScanner for efficient input reading in competitive programming.
     */
    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            String s = next();
            return s == null ? 0 : Integer.parseInt(s);
        }
    }

    /**
     * Immutable coordinate class to replace mutable java.awt.Point.
     */
    static class Coord {
        final int r, c;
        Coord(int r, int c) {
            this.r = r;
            this.c = c;
        }
    }

    public static void main(String[] args) {
        FastScanner sc = new FastScanner();
        PrintWriter out = new PrintWriter(System.out);

        solve(sc, out);
        out.flush();
    }

    private static void solve(FastScanner sc, PrintWriter out) {
        String nStr = sc.next();
        if (nStr == null) return;

        int n = Integer.parseInt(nStr);
        int m = sc.nextInt();
        int k = sc.nextInt();

        char[][] grid = new char[n][m];
        for (int i = 0; i < n; i++) {
            grid[i] = sc.next().toCharArray();
        }

        // 1. Flood fill border-connected water cells
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if ((i == 0 || i == n - 1 || j == 0 || j == m - 1) && grid[i][j] == '.') {
                    floodFill(grid, i, j, n, m, null);
                }
            }
        }

        // 2. Identify remaining lakes (enclosed water)
        List<List<Coord>> lakes = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == '.') {
                    List<Coord> lake = new ArrayList<>();
                    floodFill(grid, i, j, n, m, lake);
                    lakes.add(lake);
                }
            }
        }

        // 3. Sort lakes by size (ascending)
        lakes.sort(Comparator.comparingInt(List::size));

        // 4. Remove the k smallest lakes
        int removedCount = 0;
        int lakesToRemove = Math.min(k, lakes.size());
        for (int i = 0; i < lakesToRemove; i++) {
            for (Coord p : lakes.get(i)) {
                grid[p.r][p.c] = '*';
                removedCount++;
            }
        }

        // 5. Output results
        out.println(removedCount);
        for (int i = 0; i < n; i++) {
            out.println(new String(grid[i]).replace('+', '.'));
        }
    }

    /**
     * Performs BFS to flood fill a connected region of '.' cells.
     * Marks visited cells with '+' to prevent reprocessing.
     * Optionally collects coordinates if lake list is provided.
     */
    private static void floodFill(char[][] grid, int startR, int startC, int n, int m, List<Coord> lake) {
        Deque<Coord> queue = new ArrayDeque<>();
        queue.add(new Coord(startR, startC));
        grid[startR][startC] = '+';
        if (lake != null) lake.add(new Coord(startR, startC));

        int[] dr = {-1, 1, 0, 0};
        int[] dc = {0, 0, -1, 1};

        while (!queue.isEmpty()) {
            Coord curr = queue.poll();
            for (int i = 0; i < 4; i++) {
                int nr = curr.r + dr[i];
                int nc = curr.c + dc[i];

                if (nr >= 0 && nr < n && nc >= 0 && nc < m && grid[nr][nc] == '.') {
                    grid[nr][nc] = '+';
                    if (lake != null) lake.add(new Coord(nr, nc));
                    queue.add(new Coord(nr, nc));
                }
            }
        }
    }
}

import java.io.IOException;
import java.io.PrintWriter;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.InputMismatchException;
import java.util.List;

/**
 * Processes a grid to find enclosed components of '.' characters,
 * removes the k smallest enclosed components, and outputs the result.
 */
public class GridComponentProcessor {

    private int rows;
    private int cols;
    private int k;
    private boolean[][] grid;
    private boolean[][] visited;

    public static void main(String[] args) {
        GridComponentProcessor processor = new GridComponentProcessor();
        processor.run();
    }

    /**
     * Orchestrates the entire processing pipeline.
     */
    private void run() {
        FasterScanner scanner = new FasterScanner();
        PrintWriter out = new PrintWriter(System.out);

        try {
            rows = scanner.nextInt();
            cols = scanner.nextInt();
            k = scanner.nextInt();

            grid = new boolean[rows][cols];
            for (int i = 0; i < rows; i++) {
                String line = scanner.nextLine();
                for (int j = 0; j < cols; j++) {
                    grid[i][j] = line.charAt(j) == '.';
                }
            }

            visited = new boolean[rows][cols];
            List<Component> enclosedComponents = new ArrayList<>();
            int componentId = 0;

            // 1. Identify enclosed connected components
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j] && !visited[i][j]) {
                        List<Point> cells = new ArrayList<>();
                        boolean[] touchesBoundary = {false};
                        dfs(i, j, cells, touchesBoundary);

                        // Only keep components that do not touch the grid boundary
                        if (!touchesBoundary[0]) {
                            enclosedComponents.add(new Component(componentId++, cells));
                        }
                    }
                }
            }

            // 2. Sort components by size (ascending), then by ID (ascending)
            enclosedComponents.sort(Comparator.comparingInt(c -> c.cells.size())
                    .thenComparingInt(c -> c.id));

            // 3. Remove the k smallest enclosed components
            int removedCount = 0;
            for (Component comp : enclosedComponents) {
                if (removedCount >= k) {
                    break;
                }
                for (Point p : comp.cells()) {
                    grid[p.r()][p.c()] = false;
                    removedCount++;
                }
            }

            // 4. Output results
            out.println(removedCount);
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    out.print(grid[i][j] ? '.' : '*');
                }
                out.println();
            }
        } finally {
            out.close();
        }
    }

    /**
     * Performs a depth-first search to collect cells in a connected component.
     * Tracks whether the component touches the grid boundary.
     */
    private void dfs(int r, int c, List<Point> cells, boolean[] touchesBoundary) {
        // Base cases: out of bounds, not a walkable cell, or already visited
        if (r < 0 || r >= rows || c < 0 || c >= cols || !grid[r][c] || visited[r][c]) {
            if (r < 0 || r >= rows || c < 0 || c >= cols) {
                touchesBoundary[0] = true;
            }
            return;
        }

        visited[r][c] = true;
        cells.add(new Point(r, c));

        // Explore all 4 directions
        dfs(r - 1, c, cells, touchesBoundary);
        dfs(r, c + 1, cells, touchesBoundary);
        dfs(r + 1, c, cells, touchesBoundary);
        dfs(r, c - 1, cells, touchesBoundary);
    }

    /**
     * Represents a coordinate in the grid.
     */
    private record Point(int r, int c) {}

    /**
     * Represents a connected component of '.' cells.
     */
    private record Component(int id, List<Point> cells) {}

    /**
     * Fast input scanner for competitive programming environments.
     */
    static class FasterScanner {
        private byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;

        public int read() {
            if (numChars == -1) {
                throw new InputMismatchException();
            }
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = System.in.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0) {
                    return -1;
                }
            }
            return buf[curChar++];
        }

        public String nextLine() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            StringBuilder res = new StringBuilder();
            do {
                res.appendCodePoint(c);
                c = read();
            } while (!isEndOfLine(c));
            return res.toString();
        }

        public String nextString() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            StringBuilder res = new StringBuilder();
            do {
                res.appendCodePoint(c);
                c = read();
            } while (!isSpaceChar(c));
            return res.toString();
        }

        public long nextLong() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            long res = 0;
            do {
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                res *= 10;
                res += c - '0';
                c = read();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public int nextInt() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                res *= 10;
                res += c - '0';
                c = read();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public int[] nextIntArray(int n) {
            int[] arr = new int[n];
            for (int i = 0; i < n; i++) {
                arr[i] = nextInt();
            }
            return arr;
        }

        public long[] nextLongArray(int n) {
            long[] arr = new long[n];
            for (int i = 0; i < n; i++) {
                arr[i] = nextLong();
            }
            return arr;
        }

        private boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        private boolean isEndOfLine(int c) {
            return c == '\n' || c == '\r' || c == -1;
        }
    }
}

import java.io.InputStream;
import java.io.PrintStream;
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Deque;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Scanner;

public class MainD {
    private static final int LAND = -2;
    private static final int OCEAN = -1;

    public static void main(String[] args) {
        run(System.in, System.out);
    }

    public static void run(InputStream in, PrintStream out) {
        try (Scanner sc = new Scanner(in)) {
            if (!sc.hasNextInt()) return;

            int rows = sc.nextInt();
            int cols = sc.nextInt();
            int k = sc.nextInt();
            sc.nextLine(); // Consume the rest of the line

            int[][] grid = new int[rows][cols];
            readGrid(sc, grid);
            markOcean(grid, rows, cols);
            Map<Integer, Integer> lakeSizes = identifyLakes(grid, rows, cols);
            List<Integer> sortedLakeIds = sortLakesBySize(lakeSizes);

            int cellsToFill = fillSmallestLakes(grid, rows, cols, sortedLakeIds, lakeSizes, k);
            out.println(cellsToFill);
            printGrid(grid, out);
        }
    }

    private static void readGrid(Scanner sc, int[][] grid) {
        for (int i = 0; i < grid.length; i++) {
            String line = sc.nextLine();
            for (int j = 0; j < line.length() && j < grid[i].length; j++) {
                if (line.charAt(j) == '*') {
                    grid[i][j] = LAND;
                }
            }
        }
    }

    private static void markOcean(int[][] grid, int rows, int cols) {
        Deque<int[]> stack = new ArrayDeque<>();

        // Mark boundary cells as ocean and push to stack
        for (int i = 0; i < rows; i++) {
            pushIfWater(grid, rows, cols, i, 0, OCEAN, stack);
            pushIfWater(grid, rows, cols, i, cols - 1, OCEAN, stack);
        }
        for (int j = 0; j < cols; j++) {
            pushIfWater(grid, rows, cols, 0, j, OCEAN, stack);
            pushIfWater(grid, rows, cols, rows - 1, j, OCEAN, stack);
        }

        // Propagate ocean to connected water cells
        while (!stack.isEmpty()) {
            int[] curr = stack.pop();
            int r = curr[0], c = curr[1];
            pushIfWater(grid, rows, cols, r - 1, c, OCEAN, stack);
            pushIfWater(grid, rows, cols, r + 1, c, OCEAN, stack);
            pushIfWater(grid, rows, cols, r, c - 1, OCEAN, stack);
            pushIfWater(grid, rows, cols, r, c + 1, OCEAN, stack);
        }
    }

    private static Map<Integer, Integer> identifyLakes(int[][] grid, int rows, int cols) {
        Map<Integer, Integer> lakeSizes = new HashMap<>();
        int lakeId = 0;

        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == 0) {
                    lakeId++;
                    int size = floodFill(grid, rows, cols, i, j, lakeId);
                    lakeSizes.put(lakeId, size);
                }
            }
        }
        return lakeSizes;
    }

    private static int floodFill(int[][] grid, int rows, int cols, int startR, int startC, int targetValue) {
        Deque<int[]> stack = new ArrayDeque<>();
        stack.push(new int[]{startR, startC});
        grid[startR][startC] = targetValue;
        int count = 0;

        while (!stack.isEmpty()) {
            int[] curr = stack.pop();
            int r = curr[0], c = curr[1];
            count++;

            pushIfWater(grid, rows, cols, r - 1, c, targetValue, stack);
            pushIfWater(grid, rows, cols, r + 1, c, targetValue, stack);
            pushIfWater(grid, rows, cols, r, c - 1, targetValue, stack);
            pushIfWater(grid, rows, cols, r, c + 1, targetValue, stack);
        }
        return count;
    }

    private static void pushIfWater(int[][] grid, int rows, int cols, int r, int c, int targetValue, Deque<int[]> stack) {
        if (r >= 0 && r < rows && c >= 0 && c < cols && grid[r][c] == 0) {
            grid[r][c] = targetValue;
            stack.push(new int[]{r, c});
        }
    }

    private static List<Integer> sortLakesBySize(Map<Integer, Integer> lakeSizes) {
        List<Map.Entry<Integer, Integer>> sorted = new ArrayList<>(lakeSizes.entrySet());
        sorted.sort(Map.Entry.comparingByValue());
        List<Integer> result = new ArrayList<>(sorted.size());
        for (Map.Entry<Integer, Integer> entry : sorted) {
            result.add(entry.getKey());
        }
        return result;
    }

    private static int fillSmallestLakes(int[][] grid, int rows, int cols, List<Integer> sortedLakeIds, Map<Integer, Integer> lakeSizes, int k) {
        int cellsToFill = 0;
        int lakesToFill = Math.min(k, sortedLakeIds.size());

        for (int i = 0; i < lakesToFill; i++) {
            int lakeId = sortedLakeIds.get(i);
            int size = lakeSizes.get(lakeId);
            cellsToFill += size;
            floodFillToLand(grid, rows, cols, lakeId);
        }
        return cellsToFill;
    }

    private static void floodFillToLand(int[][] grid, int rows, int cols, int lakeId) {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == lakeId) {
                    grid[i][j] = LAND;
                }
            }
        }
    }

    private static void printGrid(int[][] grid, PrintStream out) {
        StringBuilder sb = new StringBuilder();
        for (int[] row : grid) {
            for (int cell : row) {
                sb.append(cell == LAND ? '*' : '.');
            }
            sb.append('\n');
        }
        out.print(sb);
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayList;
import java.util.LinkedList;
import java.util.List;
import java.util.Queue;
import java.util.StringTokenizer;

public class Main {
    public static void main(String[] args) {
        new Main().run();
    }

    private void run() {
        FastScanner scanner = new FastScanner();

        // Read grid dimensions and target component count
        int n = scanner.nextInt();
        int m = scanner.nextInt();
        int k = scanner.nextInt();

        // Parse grid into a 2D character array
        char[][] grid = new char[n][m];
        for (int i = 0; i < n; i++) {
            String row = scanner.next();
            grid[i] = row.toCharArray();
        }

        // Identify all connected components of '.'
        List<List<Point>> components = new ArrayList<>();
        boolean[][] visited = new boolean[n][m];

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == '.' && !visited[i][j]) {
                    List<Point> component = new ArrayList<>();
                    bfs(i, j, n, m, grid, visited, component);
                    components.add(component);
                }
            }
        }

        // Remove smallest components until only k remain
        int removedCount = 0;
        while (components.size() > k) {
            int minIndex = 0;
            for (int i = 1; i < components.size(); i++) {
                if (components.get(i).size() < components.get(minIndex).size()) {
                    minIndex = i;
                }
            }

            // Mark removed cells as '*' and count them
            for (Point p : components.get(minIndex)) {
                grid[p.r][p.c] = '*';
                removedCount++;
            }
            components.remove(minIndex);
        }

        // Build and print output
        StringBuilder sb = new StringBuilder();
        sb.append(removedCount).append('\n');
        for (int i = 0; i < n; i++) {
            sb.append(grid[i]).append('\n');
        }
        System.out.print(sb);
    }

    /**
     * Iterative BFS to find all cells in the same connected component.
     * Replaces the original recursive `fill` method to prevent StackOverflowError.
     */
    private void bfs(int startR, int startC, int rows, int cols, char[][] grid, 
                     boolean[][] visited, List<Point> component) {
        Queue<Point> queue = new LinkedList<>();
        queue.add(new Point(startR, startC));
        visited[startR][startC] = true;
        component.add(new Point(startR, startC));

        int[] dr = {-1, 1, 0, 0};
        int[] dc = {0, 0, -1, 1};

        while (!queue.isEmpty()) {
            Point current = queue.poll();
            for (int i = 0; i < 4; i++) {
                int nr = current.r + dr[i];
                int nc = current.c + dc[i];

                if (isValid(nr, nc, rows, cols) && grid[nr][nc] == '.' && !visited[nr][nc]) {
                    visited[nr][nc] = true;
                    component.add(new Point(nr, nc));
                    queue.add(new Point(nr, nc));
                }
            }
        }
    }

    /**
     * Checks if coordinates are within grid boundaries.
     * Replaces the inverted and confusing `outOfBounds` method.
     */
    private boolean isValid(int r, int c, int rows, int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /** Simple immutable coordinate holder */
    private static class Point {
        final int r, c;
        Point(int r, int c) { this.r = r; this.c = c; }
    }

    /** Lightweight, standard-compliant fast I/O reader */
    private static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input", e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            String token = next();
            return token == null ? 0 : Integer.parseInt(token);
        }
    }
}

