class Solution {
    private final InputReader in;
    private final PrintWriter out;
    private char[][] grid;
    private boolean[][] visited;
    private int rows, cols;
    private static final int[] DR = {0, 0, -1, 1};
    private static final int[] DC = {-1, 1, 0, 0};

    Solution(InputReader in, PrintWriter out) {
        this.in = in;
        this.out = out;
    }

    void solve() {
        rows = in.nextInt();
        cols = in.nextInt();
        int finalNumLakes = in.nextInt();
        grid = new char[rows][];

        for (int r = 0; r < rows; r++) {
            grid[r] = in.next().toCharArray();
        }

        // Java initializes boolean arrays to false by default
        visited = new boolean[rows][cols];

        markBorderLakes();

        List<Lake> lakes = new ArrayList<>();
        for (int r = 1; r < rows - 1; r++) {
            for (int c = 1; c < cols - 1; c++) {
                if (grid[r][c] == '.' && !visited[r][c]) {
                    int size = dfsVisit(r, c);
                    lakes.add(new Lake(r, c, size));
                }
            }
        }

        lakes.sort(Comparator.comparingInt(l -> l.size));

        int lakesToFill = Math.max(0, lakes.size() - finalNumLakes);
        int fillCount = 0;
        for (int i = 0; i < lakesToFill; i++) {
            dfsFill(lakes.get(i).startRow, lakes.get(i).startCol);
            fillCount += lakes.get(i).size;
        }

        out.println(fillCount);
        for (int r = 0; r < rows; r++) {
            out.println(grid[r]);
        }
    }

    private void markBorderLakes() {
        // Mark lakes touching the top and bottom borders
        for (int c = 0; c < cols; c++) {
            if (grid[0][c] == '.' && !visited[0][c]) dfsVisit(0, c);
            if (grid[rows - 1][c] == '.' && !visited[rows - 1][c]) dfsVisit(rows - 1, c);
        }
        // Mark lakes touching the left and right borders
        for (int r = 1; r < rows - 1; r++) {
            if (grid[r][0] == '.' && !visited[r][0]) dfsVisit(r, 0);
            if (grid[r][cols - 1] == '.' && !visited[r][cols - 1]) dfsVisit(r, cols - 1);
        }
    }

    private int dfsVisit(int r, int c) {
        visited[r][c] = true;
        int size = 1;
        for (int i = 0; i < 4; i++) {
            int nr = r + DR[i];
            int nc = c + DC[i];
            if (nr >= 0 && nr < rows && nc >= 0 && nc < cols && grid[nr][nc] == '.' && !visited[nr][nc]) {
                size += dfsVisit(nr, nc);
            }
        }
        return size;
    }

    private void dfsFill(int r, int c) {
        grid[r][c] = '*';
        for (int i = 0; i < 4; i++) {
            int nr = r + DR[i];
            int nc = c + DC[i];
            if (nr >= 0 && nr < rows && nc >= 0 && nc < cols && grid[nr][nc] == '.') {
                dfsFill(nr, nc);
            }
        }
    }

    static class Lake {
        final int startRow;
        final int startCol;
        final int size;

        Lake(int startRow, int startCol, int size) {
            this.startRow = startRow;
            this.startCol = startCol;
            this.size = size;
        }
    }
}

class InputReader {
    private final BufferedReader reader;
    private StringTokenizer tokenizer;

    public InputReader(InputStream inStream) {
        reader = new BufferedReader(new InputStreamReader(inStream));
        tokenizer = null;
    }

    public String next() {
        while (tokenizer == null || !tokenizer.hasMoreTokens()) {
            try {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            } catch (IOException e) {
                throw new RuntimeException("Input Error", e);
            }
        }
        return tokenizer.nextToken();
    }

    public int nextInt() {
        return Integer.parseInt(next());
    }

    public long nextLong() {
        return Long.parseLong(next());
    }

    public char nextChar() {
        return next().charAt(0);
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;

/**
 * Processes a grid to identify islands, removes border-connected water,
 * selects islands to reach a target count, and outputs the result.
 */
public class GridProcessor {

    // Movement directions: right, down, up, left
    private static final int[][] DIRECTIONS = {{0, 1}, {1, 0}, {-1, 0}, {0, -1}};

    // Grid character constants for readability and maintainability
    private static final char WATER = '.';
    private static final char BORDER_MARK = 'v';
    private static final char SELECTED_MARK = '*';

    public static void main(String[] args) throws IOException {
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(System.in))) {
            String[] input = reader.readLine().trim().split("\\s+");
            int rows = Integer.parseInt(input[0]);
            int cols = Integer.parseInt(input[1]);
            int targetK = Integer.parseInt(input[2]);

            char[][] grid = new char[rows][];
            for (int i = 0; i < rows; i++) {
                grid[i] = reader.readLine().toCharArray();
            }

            // Step 1: Mark and remove water connected to the grid border
            markBorderConnectedWater(grid, rows, cols);

            // Step 2: Count remaining islands and group them by size
            // TreeMap ensures we process smaller islands first (ascending order)
            Map<Integer, List<int[]>> islandsBySize = new TreeMap<>();
            int remainingIslands = 0;

            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j] == WATER) {
                        int size = floodFill(grid, i, j, BORDER_MARK, WATER);
                        islandsBySize.computeIfAbsent(size, k -> new ArrayList<>()).add(new int[]{i, j});
                        remainingIslands++;
                    }
                }
            }

            // Step 3: Select islands until exactly targetK remain
            int totalSelectedCells = 0;
            for (Map.Entry<Integer, List<int[]>> entry : islandsBySize.entrySet()) {
                if (remainingIslands == targetK) {
                    break;
                }
                for (int[] pos : entry.getValue()) {
                    if (remainingIslands == targetK) {
                        break;
                    }
                    int size = floodFill(grid, pos[0], pos[1], SELECTED_MARK, BORDER_MARK);
                    totalSelectedCells += size;
                    remainingIslands--;
                }
            }

            // Step 4: Restore water and print results
            restoreWater(grid, rows, cols);
            System.out.println(totalSelectedCells);
            for (char[] row : grid) {
                System.out.println(new String(row));
            }
        }
    }

    /**
     * Flood-fills water connected to the border, marking it to exclude it from island counting.
     */
    private static void markBorderConnectedWater(char[][] grid, int rows, int cols) {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (isOnBorder(i, j, rows, cols) && grid[i][j] == WATER) {
                    floodFill(grid, i, j, BORDER_MARK, WATER);
                }
            }
        }
    }

    /**
     * Checks if a cell is on the outer boundary of the grid.
     */
    private static boolean isOnBorder(int r, int c, int rows, int cols) {
        return r == 0 || c == 0 || r == rows - 1 || c == cols - 1;
    }

    /**
     * Performs a recursive flood-fill to count connected cells of a specific type.
     * Modifies the grid in-place to mark visited cells.
     */
    private static int floodFill(char[][] grid, int r, int c, char newChar, char targetChar) {
        if (r < 0 || c < 0 || r >= grid.length || c >= grid[r].length || grid[r][c] != targetChar) {
            return 0;
        }
        grid[r][c] = newChar;
        int count = 1;
        for (int[] dir : DIRECTIONS) {
            count += floodFill(grid, r + dir[0], c + dir[1], newChar, targetChar);
        }
        return count;
    }

    /**
     * Restores all temporarily marked border water back to its original state.
     */
    private static void restoreWater(char[][] grid, int rows, int cols) {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == BORDER_MARK) {
                    grid[i][j] = WATER;
                }
            }
        }
    }
}

import java.util.*;

/**
 * Refactored grid processing program.
 * 
 * Key Improvements:
 * 1. Separated concerns into single-responsibility methods (input, flood-fill, coloring, counting, output).
 * 2. Replaced recursion with iterative DFS using ArrayDeque to prevent StackOverflowError on large grids.
 * 3. Eliminated magic numbers and renamed cryptic variables to descriptive identifiers.
 * 4. Used a dedicated data class (RegionInfo) instead of a raw Pair, improving type safety and readability.
 * 5. Fixed Scanner whitespace handling by using next() instead of nextLine() after nextInt().
 * 6. Added proper resource management for Scanner.
 * 7. Extracted boundary validation into a helper method.
 */
public class Main {

    private static final int[][] DIRECTIONS = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};
    private static final char EMPTY = '.';
    private static final char FILLED = '*';

    private final Scanner scanner;
    private int rows, cols, k;
    private char[][] workingGrid;
    private char[][] outputGrid;
    private int[][] regionColors;

    public Main() {
        this.scanner = new Scanner(System.in);
    }

    public static void main(String[] args) {
        new Main().run();
    }

    public void run() {
        try {
            readInput();
            fillBorderConnectedRegions();
            colorInternalRegions();
            List<RegionInfo> sortedRegions = countAndSortRegions();
            processSelectedRegions(sortedRegions);
        } finally {
            scanner.close();
        }
    }

    private void readInput() {
        rows = scanner.nextInt();
        cols = scanner.nextInt();
        k = scanner.nextInt();

        workingGrid = new char[rows][cols];
        outputGrid = new char[rows][cols];
        regionColors = new int[rows][cols];

        for (int i = 0; i < rows; i++) {
            String line = scanner.next();
            for (int j = 0; j < cols; j++) {
                char c = line.charAt(j);
                workingGrid[i][j] = c;
                outputGrid[i][j] = c;
            }
        }
    }

    private void fillBorderConnectedRegions() {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                boolean isBorder = (i == 0 || i == rows - 1 || j == 0 || j == cols - 1);
                if (isBorder && workingGrid[i][j] == EMPTY) {
                    floodFill(i, j);
                }
            }
        }
    }

    /**
     * Iterative DFS to fill border-connected empty regions.
     */
    private void floodFill(int startRow, int startCol) {
        Deque<int[]> stack = new ArrayDeque<>();
        stack.push(new int[]{startRow, startCol});
        workingGrid[startRow][startCol] = FILLED;

        while (!stack.isEmpty()) {
            int[] current = stack.pop();
            for (int[] dir : DIRECTIONS) {
                int nextRow = current[0] + dir[0];
                int nextCol = current[1] + dir[1];

                if (isValid(nextRow, nextCol) && workingGrid[nextRow][nextCol] == EMPTY) {
                    workingGrid[nextRow][nextCol] = FILLED;
                    stack.push(new int[]{nextRow, nextCol});
                }
            }
        }
    }

    private void colorInternalRegions() {
        int currentColorId = 1;
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (workingGrid[i][j] == EMPTY && regionColors[i][j] == 0) {
                    colorRegion(i, j, currentColorId++);
                }
            }
        }
    }

    /**
     * Iterative DFS to assign unique colors to internal empty regions.
     */
    private void colorRegion(int startRow, int startCol, int colorId) {
        Deque<int[]> stack = new ArrayDeque<>();
        stack.push(new int[]{startRow, startCol});
        regionColors[startRow][startCol] = colorId;

        while (!stack.isEmpty()) {
            int[] current = stack.pop();
            for (int[] dir : DIRECTIONS) {
                int nextRow = current[0] + dir[0];
                int nextCol = current[1] + dir[1];

                if (isValid(nextRow, nextCol) && regionColors[nextRow][nextCol] == 0 && workingGrid[nextRow][nextCol] == EMPTY) {
                    regionColors[nextRow][nextCol] = colorId;
                    stack.push(new int[]{nextRow, nextCol});
                }
            }
        }
    }

    private boolean isValid(int row, int col) {
        return row >= 0 && row < rows && col >= 0 && col < cols;
    }

    private List<RegionInfo> countAndSortRegions() {
        int[] regionSizes = new int[rows * cols + 1];
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (regionColors[i][j] != 0) {
                    regionSizes[regionColors[i][j]]++;
                }
            }
        }

        List<RegionInfo> regions = new ArrayList<>();
        for (int i = 1; i < regionSizes.length; i++) {
            if (regionSizes[i] > 0) {
                regions.add(new RegionInfo(i, regionSizes[i]));
            }
        }
        regions.sort(Comparator.comparingInt(RegionInfo::getSize));
        return regions;
    }

    private void processSelectedRegions(List<RegionInfo> sortedRegions) {
        // Fill the smallest (totalRegions - k) regions
        int regionsToFill = Math.max(0, sortedRegions.size() - k);
        int totalCellsToFill = 0;

        for (int i = 0; i < regionsToFill; i++) {
            RegionInfo region = sortedRegions.get(i);
            totalCellsToFill += region.size();
            fillRegionById(region.id);
        }

        System.out.println(totalCellsToFill);

        for (int i = 0; i < rows; i++) {
            System.out.println(new String(outputGrid[i]));
        }
    }

    private void fillRegionById(int colorId) {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (regionColors[i][j] == colorId) {
                    outputGrid[i][j] = FILLED;
                }
            }
        }
    }

    /**
     * Immutable data class to hold region metadata.
     */
    private static class RegionInfo {
        private final int id;
        private final int size;

        public RegionInfo(int id, int size) {
            this.id = id;
            this.size = size;
        }

        public int getId() { return id; }
        public int getSize() { return size; }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.OutputStream;
import java.io.PrintWriter;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.StringTokenizer;

public class Problem_723_D {
    // Configuration constant instead of hardcoded magic value
    private static final int TEST_CASES = 1;

    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);

        for (int t = 1; t <= TEST_CASES; ++t) {
            solve(t, in, out);
        }
        out.close();
    }

    /**
     * Core solver logic. All state is kept local to prevent cross-test-case pollution
     * and improve thread-safety/testability.
     */
    private static void solve(int testNumber, InputReader in, PrintWriter out) {
        int n = in.nextInt();
        int m = in.nextInt();
        int k = in.nextInt();

        // State variables scoped locally
        boolean[][] isWall = new boolean[n][m];
        boolean[][] visited = new boolean[n][m];

        // Read grid
        for (int i = 0; i < n; ++i) {
            String line = in.next();
            for (int j = 0; j < m; ++j) {
                isWall[i][j] = line.charAt(j) == '*';
            }
        }

        List<List<Point>> internalComponents = new ArrayList<>();
        List<Point> currentComponent = new ArrayList<>();

        // Pass 1: Mark components touching the boundary as visited
        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < m; ++j) {
                if (!visited[i][j] && !isWall[i][j] && isOnBoundary(i, j, n, m)) {
                    dfs(i, j, n, m, isWall, visited, null);
                }
            }
        }

        // Pass 2: Collect remaining (internal) connected components
        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < m; ++j) {
                if (!visited[i][j] && !isWall[i][j]) {
                    currentComponent.clear();
                    dfs(i, j, n, m, isWall, visited, currentComponent);
                    internalComponents.add(new ArrayList<>(currentComponent));
                }
            }
        }

        // Sort components by size in ascending order
        internalComponents.sort(Comparator.comparingInt(List::size));

        // Remove the smallest (size - k) components
        int componentsToRemove = Math.max(0, internalComponents.size() - k);
        int totalRemoved = 0;

        for (int i = 0; i < componentsToRemove; ++i) {
            for (Point p : internalComponents.get(i)) {
                isWall[p.row][p.col] = true;
            }
            totalRemoved += internalComponents.get(i).size();
        }

        // Output results
        out.println(totalRemoved);
        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < m; ++j) {
                out.print(isWall[i][j] ? '*' : '.');
            }
            out.println();
        }
    }

    private static boolean isOnBoundary(int r, int c, int n, int m) {
        return r == 0 || r == n - 1 || c == 0 || c == m - 1;
    }

    /**
     * Recursive DFS to traverse connected empty cells.
     * 
     * @param r       current row
     * @param c       current column
     * @param n       grid height
     * @param m       grid width
     * @param isWall  grid state (true if '*')
     * @param visited tracking visited cells
     * @param component collection list (null if only marking visited)
     */
    private static void dfs(int r, int c, int n, int m, boolean[][] isWall, boolean[][] visited, List<Point> component) {
        if (component != null) {
            component.add(new Point(r, c));
        }
        visited[r][c] = true;

        // 4-directional movement (original skips diagonals)
        int[] dr = {-1, 1, 0, 0};
        int[] dc = {0, 0, -1, 1};

        for (int i = 0; i < 4; ++i) {
            int nr = r + dr[i];
            int nc = c + dc[i];

            if (nr >= 0 && nr < n && nc >= 0 && nc < m && !isWall[nr][nc] && !visited[nr][nc]) {
                dfs(nr, nc, n, m, isWall, visited, component);
            }
        }
    }

    /**
     * Immutable coordinate holder. Replaces the original mutable Pair class.
     */
    private static class Point {
        final int row;
        final int col;

        Point(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    /**
     * Fast I/O helper class for competitive programming environments.
     */
    private static class InputReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input", e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            String token = next();
            return token == null ? 0 : Integer.parseInt(token);
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.StringTokenizer;

public class Main {

    private int rows;
    private int cols;
    private char[][] grid;
    private final PrintWriter writer;
    private int[] stackX;
    private int[] stackY;

    public Main() {
        this.writer = new PrintWriter(System.out);
    }

    public void solve() {
        FastScanner sc = new FastScanner();
        try {
            rows = sc.nextInt();
            cols = sc.nextInt();
            int k = sc.nextInt();

            if (rows <= 0 || cols <= 0) {
                writer.println(0);
                return;
            }

            grid = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                String rowStr = sc.next();
                if (rowStr.length() != cols) {
                    throw new IllegalArgumentException("Row length mismatch at index " + i);
                }
                grid[i] = rowStr.toCharArray();
            }

            // Allocate stacks once for performance
            stackX = new int[rows * cols];
            stackY = new int[rows * cols];

            List<Component> components = new ArrayList<>();
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j] == '.') {
                        boolean[] touchesBoundary = {false};
                        int size = dfsIterative(i, j, touchesBoundary);
                        // Original logic: only keep components that do NOT touch the grid boundary
                        if (!touchesBoundary[0]) {
                            components.add(new Component(i, j, size));
                        }
                    }
                }
            }

            // Sort components by size in ascending order
            components.sort(Comparator.comparingInt(Component::size));

            long totalRemovedCells = 0;
            int componentsToRemove = Math.max(0, components.size() - k);
            for (int i = 0; i < componentsToRemove; i++) {
                Component comp = components.get(i);
                removeComponentIterative(comp.x(), comp.y());
                totalRemovedCells += comp.size();
            }

            writer.println(totalRemovedCells);
            for (int i = 0; i < rows; i++) {
                writer.println(new String(grid[i]));
            }

        } catch (IOException e) {
            throw new RuntimeException("Failed to read input", e);
        } finally {
            writer.flush();
        }
    }

    /**
     * Iterative DFS to find the size of a connected component of '.' characters.
     * Marks visited cells by changing them to '*'.
     * Sets touchesBoundary[0] to true if the component touches any grid edge.
     */
    private int dfsIterative(int startX, int startY, boolean[] touchesBoundary) {
        int size = 0;
        int[] dx = {-1, 1, 0, 0};
        int[] dy = {0, 0, -1, 1};

        int top = 0;
        stackX[top] = startX;
        stackY[top] = startY;
        top++;

        while (top > 0) {
            top--;
            int x = stackX[top];
            int y = stackY[top];

            if (grid[x][y] != '.') continue;

            grid[x][y] = '*';
            size++;

            for (int i = 0; i < 4; i++) {
                int nx = x + dx[i];
                int ny = y + dy[i];

                if (nx < 0 || nx >= rows || ny < 0 || ny >= cols) {
                    touchesBoundary[0] = true;
                    continue;
                }
                if (grid[nx][ny] == '.') {
                    stackX[top] = nx;
                    stackY[top] = ny;
                    top++;
                }
            }
        }
        return size;
    }

    /**
     * Iterative traversal to remove (mark as '*') all cells in a connected component.
     */
    private void removeComponentIterative(int startX, int startY) {
        int[] dx = {-1, 1, 0, 0};
        int[] dy = {0, 0, -1, 1};

        int top = 0;
        stackX[top] = startX;
        stackY[top] = startY;
        top++;

        while (top > 0) {
            top--;
            int x = stackX[top];
            int y = stackY[top];

            if (grid[x][y] != '.') continue;

            grid[x][y] = '*';

            for (int i = 0; i < 4; i++) {
                int nx = x + dx[i];
                int ny = y + dy[i];

                if (nx >= 0 && nx < rows && ny >= 0 && ny < cols && grid[nx][ny] == '.') {
                    stackX[top] = nx;
                    stackY[top] = ny;
                    top++;
                }
            }
        }
    }

    private static class Component {
        private final int x, y, size;

        Component(int x, int y, int size) {
            this.x = x;
            this.y = y;
            this.size = size;
        }

        int x() { return x; }
        int y() { return y; }
        int size() { return size; }
    }

    private static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            String s = next();
            if (s == null) throw new RuntimeException("Unexpected end of input");
            return Integer.parseInt(s);
        }
    }

    public static void main(String[] args) {
        new Main().solve();
    }
}

import java.io.*;
import java.util.*;

public class Main {

    public static void main(String[] args) {
        // Use try-with-resources for automatic and safe resource management
        try (FastScanner scanner = new FastScanner();
             PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out))) {

            new GridSolver(scanner, out).run();
            out.flush(); // Explicitly flush output before closing
        } catch (IOException e) {
            System.err.println("I/O Error: " + e.getMessage());
        }
    }

    /**
     * Handles grid parsing, component identification, conversion logic, and output.
     */
    static class GridSolver {
        private final int rows;
        private final int cols;
        private final char[][] grid;
        private final int[][] componentIds;
        private final List<Component> components;
        private static final int[][] DIRECTIONS = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};

        /**
         * Immutable record to store component metadata.
         * Implements Comparable to sort components by size (ascending).
         */
        record Component(int id, int size, List<int[]> cells) implements Comparable<Component> {
            @Override
            public int compareTo(Component other) {
                return Integer.compare(this.size, other.size);
            }
        }

        public GridSolver(FastScanner scanner, PrintWriter out) throws IOException {
            this.rows = scanner.nextInt();
            this.cols = scanner.nextInt();
            int k = scanner.nextInt();

            this.grid = new char[rows][cols];
            this.componentIds = new int[rows][cols];
            this.components = new ArrayList<>();

            readGrid(scanner);
            identifyComponents();

            int convertedCount = convertSmallestK(k);
            out.println(convertedCount);
            printResultGrid(out);
        }

        private void readGrid(FastScanner scanner) throws IOException {
            for (int i = 0; i < rows; i++) {
                String line = scanner.next();
                grid[i] = line.toCharArray();
            }
        }

        private void identifyComponents() {
            int currentId = 1;
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    // Start BFS only on unvisited empty cells
                    if (grid[i][j] == '.' && componentIds[i][j] == 0) {
                        bfs(i, j, currentId++);
                    }
                }
            }
        }

        private void bfs(int startRow, int startCol, int componentId) {
            Queue<int[]> queue = new ArrayDeque<>();
            queue.offer(new int[]{startRow, startCol});
            componentIds[startRow][startCol] = componentId;

            int size = 0;
            boolean touchesBoundary = false;
            List<int[]> cells = new ArrayList<>();

            while (!queue.isEmpty()) {
                int[] curr = queue.poll();
                int r = curr[0];
                int c = curr[1];
                size++;
                cells.add(new int[]{r, c});

                // Check if current cell is on the grid boundary
                if (r == 0 || r == rows - 1 || c == 0 || c == cols - 1) {
                    touchesBoundary = true;
                }

                // Explore 4-connected neighbors
                for (int[] dir : DIRECTIONS) {
                    int nr = r + dir[0];
                    int nc = c + dir[1];
                    if (isValid(nr, nc) && grid[nr][nc] == '.' && componentIds[nr][nc] == 0) {
                        componentIds[nr][nc] = componentId;
                        queue.offer(new int[]{nr, nc});
                    }
                }
            }

            // Per original logic: only track components that do NOT touch the boundary
            if (!touchesBoundary) {
                components.add(new Component(componentId, size, cells));
            }
        }

        private boolean isValid(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }

        /**
         * Converts the smallest K components to obstacles ('*').
         * Note: Fixed original break condition which was logically inverted.
         */
        private int convertSmallestK(int k) {
            Collections.sort(components);
            int convertedCount = 0;

            for (Component comp : components) {
                if (convertedCount >= k) break;

                // Directly mark cells from the stored list (O(1) per cell)
                for (int[] cell : comp.cells()) {
                    grid[cell[0]][cell[1]] = '*';
                    convertedCount++;
                }
            }
            return convertedCount;
        }

        private void printResultGrid(PrintWriter out) {
            for (int i = 0; i < rows; i++) {
                out.println(grid[i]);
            }
        }
    }

    /**
     * Fast I/O helper class for competitive programming / high-throughput scenarios.
     */
    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) throw new IOException("Unexpected end of input");
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.*;
import java.util.*;

public class Main {
    private int n, m;
    private char[][] grid;
    private boolean[][] visited;
    private static final int[] DX = {-1, 0, 1, 0};
    private static final int[] DY = {0, -1, 0, 1};

    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        new Main().solve(in, out);
        out.close();
    }

    private void solve(InputReader in, PrintWriter out) {
        n = in.nextInt();
        m = in.nextInt();
        int k = in.nextInt();

        grid = new char[n][m];
        for (int i = 0; i < n; i++) {
            grid[i] = in.next().toCharArray();
        }

        visited = new boolean[n][m];
        List<List<Coordinate>> internalComponents = new ArrayList<>();
        int componentCount = 0;

        // Identify connected components of '.' cells
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == '.' && !visited[i][j]) {
                    componentCount++;
                    List<Coordinate> component = new ArrayList<>();
                    boolean touchesBorder = traverse(i, j, component);

                    if (touchesBorder) {
                        // Components touching the border are immediately removed
                        for (Coordinate c : component) {
                            grid[c.x][c.y] = '*';
                        }
                        componentCount--;
                    } else {
                        internalComponents.add(component);
                    }
                }
            }
        }

        // Sort internal components by size in ascending order
        internalComponents.sort(Comparator.comparingInt(List::size));

        int changes = 0;
        // Remove smallest internal components until we reach exactly k components
        for (List<Coordinate> comp : internalComponents) {
            if (componentCount <= k) {
                break;
            }
            for (Coordinate c : comp) {
                grid[c.x][c.y] = '*';
                changes++;
            }
            componentCount--;
        }

        out.println(changes);
        for (int i = 0; i < n; i++) {
            out.println(new String(grid[i]));
        }
    }

    /**
     * Iterative DFS to traverse a connected component of '.' cells.
     * @return true if any cell in the component lies on the grid border
     */
    private boolean traverse(int startX, int startY, List<Coordinate> component) {
        Deque<Coordinate> stack = new ArrayDeque<>();
        stack.push(new Coordinate(startX, startY));
        visited[startX][startY] = true;
        boolean touchesBorder = false;

        while (!stack.isEmpty()) {
            Coordinate curr = stack.pop();
            component.add(curr);

            if (curr.x == 0 || curr.x == n - 1 || curr.y == 0 || curr.y == m - 1) {
                touchesBorder = true;
            }

            for (int d = 0; d < 4; d++) {
                int nx = curr.x + DX[d];
                int ny = curr.y + DY[d];
                if (isValid(nx, ny) && grid[nx][ny] == '.' && !visited[nx][ny]) {
                    visited[nx][ny] = true;
                    stack.push(new Coordinate(nx, ny));
                }
            }
        }
        return touchesBorder;
    }

    private boolean isValid(int x, int y) {
        return x >= 0 && y >= 0 && x < n && y < m;
    }

    static class Coordinate {
        final int x, y;
        Coordinate(int x, int y) {
            this.x = x;
            this.y = y;
        }
    }

    static class InputReader {
        public BufferedReader reader;
        public StringTokenizer tokenizer;

        public InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }

        public double nextDouble() {
            return Double.parseDouble(next());
        }
    }
}

import java.io.OutputStream;
import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.PriorityQueue;
import java.util.Scanner;
import java.util.ArrayDeque;
import java.util.Queue;

public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        Scanner in = new Scanner(inputStream);
        PrintWriter out = new PrintWriter(outputStream);

        TaskD solver = new TaskD();
        solver.solve(in, out);

        out.close();
    }

    static class TaskD {
        // Direction vectors for Up, Down, Left, Right
        private static final int[] DR = {-1, 1, 0, 0};
        private static final int[] DC = {0, 0, -1, 1};

        public void solve(Scanner in, PrintWriter out) {
            int n = in.nextInt();
            int m = in.nextInt();
            int k = in.nextInt();

            char[][] grid = new char[n][m];
            for (int i = 0; i < n; i++) {
                grid[i] = in.next().toCharArray();
            }

            boolean[][] isBorderConnected = new boolean[n][m];

            // Phase 1: Mark all '.' cells connected to the grid border
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    if (isOnBorder(i, j, n, m) && grid[i][j] == '.' && !isBorderConnected[i][j]) {
                        bfsMarkBorderConnected(grid, isBorderConnected, i, j, n, m);
                    }
                }
            }

            // Phase 2: Find connected components of non-border-connected '.' cells
            PriorityQueue<Component> pq = new PriorityQueue<>();
            boolean[][] visited = new boolean[n][m];

            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    if (grid[i][j] == '.' && !isBorderConnected[i][j] && !visited[i][j]) {
                        int size = bfsCountComponent(grid, visited, i, j, n, m);
                        pq.offer(new Component(i, j, size));
                    }
                }
            }

            // Phase 3: Fill the smallest components until exactly k remain
            int cellsFilled = 0;
            while (pq.size() > k) {
                Component comp = pq.poll();
                cellsFilled += comp.size;
                bfsFillComponent(grid, comp.startRow, comp.startCol, n, m);
            }

            out.println(cellsFilled);
            for (int i = 0; i < n; i++) {
                out.println(new String(grid[i]));
            }
        }

        private boolean isOnBorder(int r, int c, int n, int m) {
            return r == 0 || r == n - 1 || c == 0 || c == m - 1;
        }

        /**
         * Marks all '.' cells reachable from (r, c) as border-connected.
         */
        private void bfsMarkBorderConnected(char[][] grid, boolean[][] visited, int r, int c, int n, int m) {
            Queue<Coordinate> queue = new ArrayDeque<>();
            queue.offer(new Coordinate(r, c));
            visited[r][c] = true;

            while (!queue.isEmpty()) {
                Coordinate curr = queue.poll();
                for (int d = 0; d < 4; d++) {
                    int nr = curr.r + DR[d];
                    int nc = curr.c + DC[d];
                    if (nr < 0 || nr >= n || nc < 0 || nc >= m) continue;
                    if (visited[nr][nc] || grid[nr][nc] == '*') continue;

                    visited[nr][nc] = true;
                    queue.offer(new Coordinate(nr, nc));
                }
            }
        }

        /**
         * Counts the size of the connected component starting at (r, c).
         */
        private int bfsCountComponent(char[][] grid, boolean[][] visited, int r, int c, int n, int m) {
            int count = 0;
            Queue<Coordinate> queue = new ArrayDeque<>();
            queue.offer(new Coordinate(r, c));
            visited[r][c] = true;
            count++;

            while (!queue.isEmpty()) {
                Coordinate curr = queue.poll();
                for (int d = 0; d < 4; d++) {
                    int nr = curr.r + DR[d];
                    int nc = curr.c + DC[d];
                    if (nr < 0 || nr >= n || nc < 0 || nc >= m) continue;
                    if (visited[nr][nc] || grid[nr][nc] == '*') continue;

                    visited[nr][nc] = true;
                    count++;
                    queue.offer(new Coordinate(nr, nc));
                }
            }
            return count;
        }

        /**
         * Flood-fills a connected component with '*' walls.
         */
        private void bfsFillComponent(char[][] grid, int r, int c, int n, int m) {
            Queue<Coordinate> queue = new ArrayDeque<>();
            queue.offer(new Coordinate(r, c));
            grid[r][c] = '*';

            while (!queue.isEmpty()) {
                Coordinate curr = queue.poll();
                for (int d = 0; d < 4; d++) {
                    int nr = curr.r + DR[d];
                    int nc = curr.c + DC[d];
                    if (nr < 0 || nr >= n || nc < 0 || nc >= m) continue;
                    if (grid[nr][nc] == '*') continue;

                    grid[nr][nc] = '*';
                    queue.offer(new Coordinate(nr, nc));
                }
            }
        }
    }

    /** Immutable coordinate holder */
    static class Coordinate {
        final int r, c;
        Coordinate(int r, int c) { this.r = r; this.c = c; }
    }

    /** Component info holder, sorted by size ascending */
    static class Component implements Comparable<Component> {
        final int startRow, startCol, size;
        Component(int r, int c, int s) { this.startRow = r; this.startCol = c; this.size = s; }

        @Override
        public int compareTo(Component other) {
            return Integer.compare(this.size, other.size);
        }
    }
}

import java.io.*;
import java.util.*;

public class CO_723D {
    // Safe large value to represent "infinite" frequency without causing long overflow
    private static final long INF = Long.MAX_VALUE / 2;

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out);

        // Original hardcoded test case count to 1
        int testCases = 1;
        while (testCases-- > 0) {
            solve(scanner, out);
        }

        out.flush();
        out.close();
    }

    private static void solve(FastScanner sc, PrintWriter out) {
        int n = sc.nextInt();
        int m = sc.nextInt();
        int k = sc.nextInt();

        char[][] grid = new char[n][m];
        for (int i = 0; i < n; i++) {
            grid[i] = sc.next().toCharArray();
        }

        boolean[][] visited = new boolean[n][m];
        List<Component> components = new ArrayList<>();

        // Identify all connected components of '.'
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (!visited[i][j] && grid[i][j] == '.') {
                    long size = findComponentSize(grid, visited, i, j, n, m);
                    components.add(new Component(i, j, size));
                }
            }
        }

        // Sort components by frequency in ascending order (matches original logic)
        Collections.sort(components);

        // Count components that touch the boundary (marked as INF)
        int boundaryCount = 0;
        for (Component comp : components) {
            if (comp.frequency >= INF) {
                boundaryCount++;
            }
        }

        // Reset visited array for the marking phase
        visited = new boolean[n][m];
        long totalFrequency = 0;
        int limit = Math.max(0, components.size() - boundaryCount - k);

        // Process the smallest components
        for (int i = 0; i < limit; i++) {
            Component comp = components.get(i);
            totalFrequency += comp.frequency;
            markAndClearComponent(grid, visited, comp.x, comp.y, n, m);
        }

        out.println(totalFrequency);
        for (char[] row : grid) {
            out.println(new String(row));
        }
    }

    /**
     * Iterative DFS to find component size and check for boundary touch.
     * Returns INF if the component touches any grid edge, otherwise returns exact size.
     */
    private static long findComponentSize(char[][] grid, boolean[][] visited, int startX, int startY, int n, int m) {
        long size = 0;
        boolean touchesBoundary = false;
        Deque<int[]> stack = new ArrayDeque<>();
        stack.push(new int[]{startX, startY});
        visited[startX][startY] = true;

        int[] dr = {-1, 1, 0, 0};
        int[] dc = {0, 0, -1, 1};

        while (!stack.isEmpty()) {
            int[] curr = stack.pop();
            int r = curr[0];
            int c = curr[1];
            size++;

            if ((r == 0 || r == n - 1 || c == 0 || c == m - 1) && grid[r][c] == '.') {
                touchesBoundary = true;
            }

            for (int d = 0; d < 4; d++) {
                int nr = r + dr[d];
                int nc = c + dc[d];
                if (nr >= 0 && nr < n && nc >= 0 && nc < m && !visited[nr][nc] && grid[nr][nc] == '.') {
                    visited[nr][nc] = true;
                    stack.push(new int[]{nr, nc});
                }
            }
        }
        return touchesBoundary ? INF : size;
    }

    /**
     * Iterative DFS to mark and clear a component by changing '.' to '*'.
     */
    private static void markAndClearComponent(char[][] grid, boolean[][] visited, int startX, int startY, int n, int m) {
        Deque<int[]> stack = new ArrayDeque<>();
        stack.push(new int[]{startX, startY});
        visited[startX][startY] = true;
        grid[startX][startY] = '*';

        int[] dr = {-1, 1, 0, 0};
        int[] dc = {0, 0, -1, 1};

        while (!stack.isEmpty()) {
            int[] curr = stack.pop();
            int r = curr[0];
            int c = curr[1];

            for (int d = 0; d < 4; d++) {
                int nr = r + dr[d];
                int nc = c + dc[d];
                if (nr >= 0 && nr < n && nc >= 0 && nc < m && !visited[nr][nc] && grid[nr][nc] == '.') {
                    visited[nr][nc] = true;
                    grid[nr][nc] = '*';
                    stack.push(new int[]{nr, nc});
                }
            }
        }
    }

    /**
     * Represents a connected component in the grid.
     * Implements Comparable to allow natural sorting by frequency.
     */
    private static class Component implements Comparable<Component> {
        final int x, y;
        final long frequency;

        Component(int x, int y, long frequency) {
            this.x = x;
            this.y = y;
            this.frequency = frequency;
        }

        @Override
        public int compareTo(Component other) {
            return Long.compare(this.frequency, other.frequency);
        }
    }

    /**
     * Fast I/O helper class using BufferedReader and StringTokenizer.
     * Replaces the original byte-level InputReader for better readability and standard compliance.
     */
    static class FastScanner {
        BufferedReader br;
        StringTokenizer st;

        public FastScanner(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            String s = next();
            if (s == null) throw new RuntimeException("Unexpected end of input");
            return Integer.parseInt(s);
        }
    }
}

import java.io.*;
import java.util.*;

public class Main {
    private static final int[][] DIRECTIONS = {{0, 1}, {0, -1}, {1, 0}, {-1, 0}};

    public static void main(String[] args) throws IOException {
        FastScanner scanner = new FastScanner();
        PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out));

        int rows = scanner.nextInt();
        int cols = scanner.nextInt();
        int maxLakes = scanner.nextInt();

        char[][] grid = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            grid[i] = scanner.next().toCharArray();
        }

        GridSolver solver = new GridSolver(rows, cols, grid);
        solver.solve(maxLakes, out);

        out.flush();
    }

    /**
     * Handles all grid traversal, lake detection, and drainage logic.
     */
    static class GridSolver {
        private final int rows, cols;
        private char[][] grid;
        private boolean[][] visited;
        private final List<Cell> lakes = new ArrayList<>();
        private int lakeCount = 0;

        GridSolver(int rows, int cols, char[][] grid) {
            this.rows = rows;
            this.cols = cols;
            this.grid = grid;
            this.visited = new boolean[rows][cols];
        }

        void solve(int maxLakes, PrintWriter out) {
            markOcean();
            findLakes();
            drainLakes(maxLakes, out);
        }

        private boolean isBorder(int r, int c) {
            return r == 0 || r == rows - 1 || c == 0 || c == cols - 1;
        }

        private boolean isWithinBounds(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }

        /**
         * Marks all cells connected to the border as visited (ocean).
         */
        private void markOcean() {
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (isBorder(i, j) && grid[i][j] == '.' && !visited[i][j]) {
                        floodFillOcean(i, j, false);
                    }
                }
            }
        }

        /**
         * Identifies enclosed lakes (connected '.' cells not reachable from the border).
         */
        private void findLakes() {
            for (int i = 1; i < rows - 1; i++) {
                for (int j = 1; j < cols - 1; j++) {
                    if (grid[i][j] == '.' && !visited[i][j]) {
                        floodFillLake(i, j);
                    }
                }
            }
        }

        /**
         * Counts cells in a lake using BFS and records it.
         */
        private void floodFillLake(int startRow, int startCol) {
            int size = 0;
            Queue<int[]> queue = new ArrayDeque<>();
            queue.offer(new int[]{startRow, startCol});
            visited[startRow][startCol] = true;
            size++;

            while (!queue.isEmpty()) {
                int[] curr = queue.poll();
                for (int[] dir : DIRECTIONS) {
                    int nr = curr[0] + dir[0];
                    int nc = curr[1] + dir[1];
                    if (isWithinBounds(nr, nc) && grid[nr][nc] == '.' && !visited[nr][nc]) {
                        visited[nr][nc] = true;
                        size++;
                        queue.offer(new int[]{nr, nc});
                    }
                }
            }
            lakes.add(new Cell(startRow, startCol, size));
            lakeCount++;
        }

        /**
         * Drains lakes until the count is at or below maxLakes.
         */
        private void drainLakes(int maxLakes, PrintWriter out) {
            lakes.sort(Comparator.comparingInt(Cell::size));
            int drainedCount = 0;
            visited = new boolean[rows][cols]; // Reset visited state for the draining phase

            for (Cell lake : lakes) {
                if (lakeCount <= maxLakes) {
                    break;
                }
                if (!visited[lake.row][lake.col]) {
                    lakeCount--;
                    drainedCount += lake.size;
                    floodFillOcean(lake.row, lake.col, true);
                }
            }

            out.println(drainedCount);
            for (char[] row : grid) {
                out.println(row);
            }
        }

        /**
         * Flood-fills a region. If drain is true, converts '.' to '*' (ocean).
         */
        private void floodFillOcean(int startRow, int startCol, boolean drain) {
            Deque<int[]> stack = new ArrayDeque<>();
            stack.push(new int[]{startRow, startCol});
            visited[startRow][startCol] = true;
            if (drain) {
                grid[startRow][startCol] = '*';
            }

            while (!stack.isEmpty()) {
                int[] curr = stack.pop();
                for (int[] dir : DIRECTIONS) {
                    int nr = curr[0] + dir[0];
                    int nc = curr[1] + dir[1];
                    if (isWithinBounds(nr, nc) && grid[nr][nc] != '*' && !visited[nr][nc]) {
                        visited[nr][nc] = true;
                        if (drain) {
                            grid[nr][nc] = '*';
                        }
                        stack.push(new int[]{nr, nc});
                    }
                }
            }
        }
    }

    /**
     * Represents a lake's starting coordinate and its total cell count.
     */
    static class Cell implements Comparable<Cell> {
        final int row, col, size;

        Cell(int row, int col, int size) {
            this.row = row;
            this.col = col;
            this.size = size;
        }

        @Override
        public int compareTo(Cell other) {
            return Integer.compare(this.size, other.size);
        }
    }

    /**
     * Lightweight scanner for fast and safe input parsing.
     */
    private static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.*;
import java.util.*;

public class LakeFillingSolver {

    /** Lightweight immutable point class to avoid AWT dependency */
    private static class Point {
        final int x, y;
        Point(int x, int y) { this.x = x; this.y = y; }
    }

    /** Stores lake metadata for sorting and tracking */
    private static class LakeInfo {
        final int size;
        final int index;
        LakeInfo(int size, int index) {
            this.size = size;
            this.index = index;
        }
    }

    private final int rows, cols;
    private final char[][] grid;
    private final boolean[][] visited;
    private final List<List<Point>> components;
    private final int[] dx = {1, -1, 0, 0};
    private final int[] dy = {0, 0, 1, -1};

    public LakeFillingSolver(char[][] grid) {
        this.grid = grid;
        this.rows = grid.length;
        this.cols = grid[0].length;
        this.visited = new boolean[rows][cols];
        this.components = new ArrayList<>();
    }

    /**
     * Orchestrates the lake identification and filling process.
     */
    public void solve(int k, PrintWriter out) {
        findComponents();
        List<LakeInfo> lakes = identifyLakes();
        lakes.sort(Comparator.comparingInt(lake -> lake.size));

        int totalFilled = 0;
        int lakesToFill = Math.min(k, lakes.size());

        for (int i = 0; i < lakesToFill; i++) {
            LakeInfo lake = lakes.get(i);
            totalFilled += lake.size;
            List<Point> component = components.get(lake.index);
            for (Point p : component) {
                grid[p.x][p.y] = '*';
            }
        }

        out.println(totalFilled);
        for (int i = 0; i < rows; i++) {
            out.println(new String(grid[i]));
        }
    }

    /**
     * Traverses the grid to find all connected components of '.'.
     */
    private void findComponents() {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == '.' && !visited[i][j]) {
                    List<Point> component = new ArrayList<>();
                    bfs(i, j, component);
                    components.add(component);
                }
            }
        }
    }

    /**
     * Iterative BFS to avoid stack overflow on large grids.
     */
    private void bfs(int startX, int startY, List<Point> component) {
        Queue<Point> queue = new ArrayDeque<>();
        queue.add(new Point(startX, startY));
        visited[startX][startY] = true;

        while (!queue.isEmpty()) {
            Point curr = queue.poll();
            component.add(curr);

            for (int d = 0; d < 4; d++) {
                int nx = curr.x + dx[d];
                int ny = curr.y + dy[d];
                if (isValid(nx, ny) && !visited[nx][ny] && grid[nx][ny] == '.') {
                    visited[nx][ny] = true;
                    queue.add(new Point(nx, ny));
                }
            }
        }
    }

    /**
     * Identifies lakes (components that do not touch the grid border).
     */
    private List<LakeInfo> identifyLakes() {
        List<LakeInfo> lakes = new ArrayList<>();
        for (int i = 0; i < components.size(); i++) {
            List<Point> comp = components.get(i);
            boolean touchesBorder = false;
            for (Point p : comp) {
                if (p.x == 0 || p.x == rows - 1 || p.y == 0 || p.y == cols - 1) {
                    touchesBorder = true;
                    break;
                }
            }
            if (!touchesBorder) {
                lakes.add(new LakeInfo(comp.size(), i));
            }
        }
        return lakes;
    }

    private boolean isValid(int x, int y) {
        return x >= 0 && x < rows && y >= 0 && y < cols;
    }

    /**
     * Fast I/O helper to replace Scanner for performance.
     */
    private static class FastScanner implements AutoCloseable {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            String token = next();
            return (token == null) ? 0 : Integer.parseInt(token);
        }

        @Override
        public void close() throws IOException {
            br.close();
        }
    }

    public static void main(String[] args) {
        try (FastScanner sc = new FastScanner();
             PrintWriter out = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)))) {

            String nStr = sc.next();
            if (nStr == null) return;

            int n = Integer.parseInt(nStr);
            int m = sc.nextInt();
            int k = sc.nextInt();

            char[][] grid = new char[n][m];
            for (int i = 0; i < n; i++) {
                String line = sc.next();
                grid[i] = (line != null) ? line.toCharArray() : new char[m];
            }

            LakeFillingSolver solver = new LakeFillingSolver(grid);
            solver.solve(k, out);
            out.flush();
        } catch (IOException e) {
            System.err.println("I/O error occurred: " + e.getMessage());
        }
    }
}

import java.util.ArrayList;
import java.util.Collections;
import java.util.Deque;
import java.util.ArrayDeque;
import java.util.List;
import java.util.Scanner;

/**
 * Solves the Lakes in Berland problem.
 * Identifies enclosed water bodies (lakes) and dries up the smallest ones.
 */
public class LakesInBerlands {

    // Encapsulated state to avoid global static variables and improve testability
    private char[][] grid;
    private boolean[][] visited;
    private int rows;
    private int cols;

    /**
     * Represents a coordinate in the grid.
     */
    private static class Coordinate {
        final int r;
        final int c;

        Coordinate(int r, int c) {
            this.r = r;
            this.c = c;
        }
    }

    /**
     * Represents a discovered lake.
     */
    private static class Lake implements Comparable<Lake> {
        final int size;
        final List<Coordinate> cells;

        Lake(int size, List<Coordinate> cells) {
            this.size = size;
            this.cells = cells;
        }

        @Override
        public int compareTo(Lake other) {
            // Sort by size ascending
            return Integer.compare(this.size, other.size);
        }
    }

    public static void main(String[] args) {
        LakesInBerlands solver = new LakesInBerlands();
        solver.solve();
    }

    /**
     * Orchestrates the reading, processing, and printing of the grid.
     */
    private void solve() {
        Scanner scanner = new Scanner(System.in);

        // Read dimensions and k
        if (!scanner.hasNextInt()) return;
        this.rows = scanner.nextInt();
        this.cols = scanner.nextInt();
        int k = scanner.nextInt();
        scanner.nextLine(); // Consume the rest of the line (newline character)

        // Initialize grid and visited array
        this.grid = new char[rows][cols];
        this.visited = new boolean[rows][cols];

        // Read the grid
        for (int i = 0; i < rows; i++) {
            String line = scanner.nextLine();
            // Defensive coding: ensure we don't go out of bounds if line is short
            for (int j = 0; j < cols && j < line.length(); j++) {
                grid[i][j] = line.charAt(j);
            }
        }

        // Find all lakes
        List<Lake> lakes = findLakes();

        // Process lakes (sort and bury smallest ones)
        int totalBuried = processLakes(lakes, k);

        // Output results
        System.out.println(totalBuried);
        printGrid();

        scanner.close();
    }

    /**
     * Traverses the grid to find all connected water components (lakes).
     * A lake is defined as a connected component of '.' that does not touch the grid boundary.
     */
    private List<Lake> findLakes() {
        List<Lake> lakes = new ArrayList<>();
        // Directions: Up, Down, Left, Right
        int[] dr = {-1, 1, 0, 0};
        int[] dc = {0, 0, -1, 1};

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                // If cell is water and not yet visited, start a traversal
                if (grid[r][c] == '.' && !visited[r][c]) {
                    List<Coordinate> currentLakeCells = new ArrayList<>();
                    boolean touchesBorder = false;

                    // Use a Deque as a Stack for DFS (more efficient than java.util.Stack)
                    Deque<Coordinate> stack = new ArrayDeque<>();

                    stack.push(new Coordinate(r, c));
                    visited[r][c] = true;
                    currentLakeCells.add(new Coordinate(r, c));

                    while (!stack.isEmpty()) {
                        Coordinate curr = stack.pop();

                        // Check if current cell is on the border
                        if (curr.r == 0 || curr.r == rows - 1 || curr.c == 0 || curr.c == cols - 1) {
                            touchesBorder = true;
                        }

                        // Explore neighbors
                        for (int i = 0; i < 4; i++) {
                            int nr = curr.r + dr[i];
                            int nc = curr.c + dc[i];

                            if (isValid(nr, nc) && !visited[nr][nc] && grid[nr][nc] == '.') {
                                visited[nr][nc] = true;
                                stack.push(new Coordinate(nr, nc));
                                currentLakeCells.add(new Coordinate(nr, nc));
                            }
                        }
                    }

                    // If the component does not touch the border, it is a lake.
                    // If it touches the border, it is part of the ocean (sea), so we discard it.
                    // Note: We have already marked all cells in this component as visited.
                    if (!touchesBorder) {
                        lakes.add(new Lake(currentLakeCells.size(), currentLakeCells));
                    }
                }
            }
        }
        return lakes;
    }

    private boolean isValid(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /**
     * Sorts lakes by size and buries the smallest ones if necessary.
     * Keeps the k largest lakes.
     */
    private int processLakes(List<Lake> lakes, int k) {
        Collections.sort(lakes);

        int totalBuried = 0;
        // We need to bury (Total Lakes - k) smallest lakes.
        // If Total Lakes <= k, we bury 0.
        int lakesToBury = Math.max(0, lakes.size() - k);

        for (int i = 0; i < lakesToBury; i++) {
            Lake lake = lakes.get(i);
            totalBuried += lake.size;
            // Mark water as land efficiently using stored coordinates
            for (Coordinate cell : lake.cells) {
                grid[cell.r][cell.c] = '*';
            }
        }

        return totalBuried;
    }

    private void printGrid() {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < rows; i++) {
            // StringBuilder.append(char[]) is efficient
            sb.append(grid[i]).append('\n');
        }
        System.out.print(sb);
    }
}

import java.io.*;
import java.util.*;

public class GridComponentAnalyzer {

    // Direction vectors for 4-connected grid traversal (Right, Left, Down, Up)
    private static final int[] DX = {0, 0, 1, -1};
    private static final int[] DY = {1, -1, 0, 0};

    private int rows, cols;
    private boolean[][] grid;
    private int[][] colorMap;
    private FastScanner scanner;
    private PrintWriter writer;

    /**
     * Entry point for I/O setup and execution.
     */
    public void run() {
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
             PrintWriter writer = new PrintWriter(new BufferedOutputStream(System.out))) {

            this.scanner = new FastScanner(reader);
            this.writer = writer;

            solve();
            writer.flush();
        } catch (IOException e) {
            e.printStackTrace();
            System.exit(1);
        }
    }

    /**
     * Orchestrates the main problem-solving logic.
     */
    private void solve() throws IOException {
        rows = scanner.nextInt();
        cols = scanner.nextInt();
        int k = scanner.nextInt();

        initializeGrid(rows, cols);
        readGridInput();
        removeBorderConnectedComponents();
        List<Component> components = findAndColorComponents();
        processAndPrintResults(k, components);
    }

    /**
     * Initializes grid dimensions and color mapping array.
     */
    private void initializeGrid(int n, int m) {
        this.rows = n;
        this.cols = m;
        grid = new boolean[n][m];
        colorMap = new int[n][m];
        // Initialize all cells as uncolored (-1)
        for (int i = 0; i < n; i++) {
            Arrays.fill(colorMap[i], -1);
        }
    }

    /**
     * Reads the grid input from the scanner.
     */
    private void readGridInput() throws IOException {
        for (int i = 0; i < rows; i++) {
            String line = scanner.next();
            for (int j = 0; j < cols; j++) {
                grid[i][j] = (line.charAt(j) == '.');
            }
        }
    }

    /**
     * Removes all connected components that touch the grid boundary.
     */
    private void removeBorderConnectedComponents() {
        // Check top and bottom rows
        for (int j = 0; j < cols; j++) {
            if (grid[0][j]) traverseAndRemove(0, j);
            if (grid[rows - 1][j]) traverseAndRemove(rows - 1, j);
        }
        // Check left and right columns
        for (int i = 0; i < rows; i++) {
            if (grid[i][0]) traverseAndRemove(i, 0);
            if (grid[i][cols - 1]) traverseAndRemove(i, cols - 1);
        }
    }

    /**
     * Recursively traverses and removes a connected component starting from (x, y).
     */
    private void traverseAndRemove(int x, int y) {
        if (!grid[x][y]) return; // Already removed or not walkable
        grid[x][y] = false;
        for (int i = 0; i < 4; i++) {
            int nx = x + DX[i];
            int ny = y + DY[i];
            if (isValid(nx, ny) && grid[nx][ny]) {
                traverseAndRemove(nx, ny);
            }
        }
    }

    /**
     * Checks if coordinates are within grid bounds.
     */
    private boolean isValid(int x, int y) {
        return x >= 0 && x < rows && y >= 0 && y < cols;
    }

    /**
     * Performs DFS to count and color a connected component.
     * Returns the size of the component.
     */
    private int dfs(int x, int y, int curColor) {
        colorMap[x][y] = curColor;
        int count = 1;
        for (int i = 0; i < 4; i++) {
            int nx = x + DX[i];
            int ny = y + DY[i];
            if (isValid(nx, ny) && colorMap[nx][ny] == -1 && grid[nx][ny]) {
                count += dfs(nx, ny, curColor);
            }
        }
        return count;
    }

    /**
     * Finds all remaining connected components, colors them, and stores their metadata.
     */
    private List<Component> findAndColorComponents() {
        List<Component> components = new ArrayList<>();
        int colorId = 0;
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] && colorMap[i][j] == -1) {
                    int size = dfs(i, j, colorId);
                    components.add(new Component(size, colorId));
                    colorId++;
                }
            }
        }
        return components;
    }

    /**
     * Sorts components, removes the smallest ones to keep the k largest,
     * updates the grid, and prints the final result.
     */
    private void processAndPrintResults(int k, List<Component> components) {
        // Sort components by size in ascending order
        components.sort(Comparator.comparingInt(Component::getSize));

        int totalComponents = components.size();
        int componentsToRemove = Math.max(0, totalComponents - k);
        Set<Integer> removedColors = new HashSet<>();
        int totalRemovedSize = 0;

        // Mark the smallest (totalComponents - k) components for removal
        for (int i = 0; i < componentsToRemove; i++) {
            Component comp = components.get(i);
            removedColors.add(comp.colorId);
            totalRemovedSize += comp.size;
        }

        // Update grid to mark removed components as walls
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (removedColors.contains(colorMap[i][j])) {
                    grid[i][j] = false;
                }
            }
        }

        // Output results
        writer.println(totalRemovedSize);
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                writer.print(grid[i][j] ? '.' : '*');
            }
            writer.println();
        }
    }

    /**
     * Lightweight scanner for fast I/O.
     */
    private static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner(BufferedReader br) {
            this.br = br;
        }

        public String next() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) throw new EOFException();
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }

    /**
     * Immutable data class to store component metadata.
     */
    private static final class Component {
        final int size;
        final int colorId;

        Component(int size, int colorId) {
            this.size = size;
            this.colorId = colorId;
        }

        int getSize() {
            return size;
        }
    }

    public static void main(String[] args) {
        Locale.setDefault(Locale.US);
        new GridComponentAnalyzer().run();
    }
}

import java.util.ArrayList;
import java.util.ArrayDeque;
import java.util.Comparator;
import java.util.List;
import java.util.Queue;
import java.util.Scanner;

public class LakesInBerland {

    private int rows;
    private int cols;
    private int k;
    private char[][] grid;
    // 0: unvisited, -1: border-connected, >0: lake ID
    private int[][] visited;
    private List<LakeInfo> lakes;
    private int lakeIdCounter;
    private static final int[][] DIRECTIONS = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};

    /**
     * Helper class to store lake metadata and coordinates.
     */
    private static class LakeInfo {
        int id;
        int size;
        List<int[]> cells;

        public LakeInfo(int id, int size) {
            this.id = id;
            this.size = size;
            this.cells = new ArrayList<>();
        }
    }

    /**
     * Reads grid dimensions, k, and the grid itself from standard input.
     */
    public void readInput(Scanner sc) {
        rows = sc.nextInt();
        cols = sc.nextInt();
        k = sc.nextInt();
        grid = new char[rows][cols];
        visited = new int[rows][cols];
        lakes = new ArrayList<>();
        lakeIdCounter = 0;

        for (int i = 0; i < rows; i++) {
            String line = sc.next();
            grid[i] = line.toCharArray();
        }
    }

    /**
     * Checks if coordinates are within grid boundaries.
     */
    private boolean isValid(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /**
     * Performs BFS to either mark border-connected land or identify/count a lake.
     *
     * @param startR      Starting row coordinate
     * @param startC      Starting column coordinate
     * @param markAsBorder If true, marks connected '.' cells as border-connected (-1).
     *                     If false, identifies a new lake and tracks its size/coordinates.
     */
    private void bfs(int startR, int startC, boolean markAsBorder) {
        if (!markAsBorder) {
            lakeIdCounter++;
        }

        Queue<int[]> queue = new ArrayDeque<>();
        queue.offer(new int[]{startR, startC});
        visited[startR][startC] = markAsBorder ? -1 : lakeIdCounter;

        LakeInfo currentLake = markAsBorder ? null : new LakeInfo(lakeIdCounter, 1);
        if (currentLake != null) {
            currentLake.cells.add(new int[]{startR, startC});
        }

        while (!queue.isEmpty()) {
            int[] curr = queue.poll();
            int r = curr[0];
            int c = curr[1];

            for (int[] dir : DIRECTIONS) {
                int nr = r + dir[0];
                int nc = c + dir[1];

                if (isValid(nr, nc) && visited[nr][nc] == 0 && grid[nr][nc] == '.') {
                    visited[nr][nc] = markAsBorder ? -1 : lakeIdCounter;
                    if (currentLake != null) {
                        currentLake.cells.add(new int[]{nr, nc});
                        currentLake.size++;
                    }
                    queue.offer(new int[]{nr, nc});
                }
            }
        }

        if (currentLake != null) {
            lakes.add(currentLake);
        }
    }

    /**
     * Fills all cells of a given lake with '*' in the grid.
     */
    private void fillLake(LakeInfo lake) {
        for (int[] cell : lake.cells) {
            grid[cell[0]][cell[1]] = '*';
        }
    }

    /**
     * Orchestrates the solution: identifies lakes, filters them, fills smallest ones, and prints output.
     */
    public void solve() {
        // 1. Mark all land connected to the border (these are not lakes)
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if ((i == 0 || j == 0 || i == rows - 1 || j == cols - 1)
                        && visited[i][j] == 0 && grid[i][j] == '.') {
                    bfs(i, j, true);
                }
            }
        }

        // 2. Identify remaining connected components (actual lakes)
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (visited[i][j] == 0 && grid[i][j] == '.') {
                    bfs(i, j, false);
                }
            }
        }

        // 3. Sort lakes by size in ascending order
        lakes.sort(Comparator.comparingInt(l -> l.size));

        // 4. Fill the smallest lakes until only k largest remain
        int lakesToFill = lakes.size() - k;
        int totalFilled = 0;
        for (int i = 0; i < lakesToFill; i++) {
            LakeInfo lake = lakes.get(i);
            totalFilled += lake.size;
            fillLake(lake);
        }

        // 5. Output results
        System.out.println(totalFilled);
        for (char[] row : grid) {
            System.out.println(new String(row));
        }
    }

    public static void main(String[] args) {
        try (Scanner sc = new Scanner(System.in)) {
            LakesInBerland solver = new LakesInBerland();
            solver.readInput(sc);
            solver.solve();
        }
    }
}

import java.io.*;
import java.util.*;

public class Main {

    /**
     * Represents a connected component with its size and unique identifier.
     * Used for sorting components by size in ascending order.
     */
    private static class Component implements Comparable<Component> {
        final int size;
        final int id;

        Component(int size, int id) {
            this.size = size;
            this.id = id;
        }

        @Override
        public int compareTo(Component other) {
            int sizeComparison = Integer.compare(this.size, other.size);
            return sizeComparison != 0 ? sizeComparison : Integer.compare(this.id, other.id);
        }
    }

    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        FastReader in = new FastReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);

        solve(in, out);
        out.flush();
        out.close();
    }

    private static void solve(FastReader in, PrintWriter out) {
        int n = in.nextInt();
        int m = in.nextInt();
        int k = in.nextInt();

        char[][] board = new char[n][m];
        for (int i = 0; i < n; i++) {
            board[i] = in.next().toCharArray();
        }

        int[][] componentId = new int[n][m];
        int[] componentSizes = new int[n * m + 1];
        int currentComponentId = 0;

        int[] dx = {-1, 0, 1, 0};
        int[] dy = {0, -1, 0, 1};

        // 1. Identify connected components using iterative DFS
        Deque<int[]> stack = new ArrayDeque<>();
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (board[i][j] == '*' || componentId[i][j] != 0) {
                    continue;
                }

                currentComponentId++;
                stack.push(new int[]{i, j});
                while (!stack.isEmpty()) {
                    int[] curr = stack.pop();
                    int x = curr[0];
                    int y = curr[1];

                    if (componentId[x][y] != 0) {
                        continue;
                    }

                    componentId[x][y] = currentComponentId;
                    componentSizes[currentComponentId]++;

                    for (int d = 0; d < 4; d++) {
                        int nx = x + dx[d];
                        int ny = y + dy[d];
                        if (nx >= 0 && nx < n && ny >= 0 && ny < m &&
                            board[nx][ny] == '.' && componentId[nx][ny] == 0) {
                            stack.push(new int[]{nx, ny});
                        }
                    }
                }
            }
        }

        // 2. Identify components that touch the board's border
        Set<Integer> borderComponentIds = new HashSet<>();
        for (int i = 0; i < n; i++) {
            if (board[i][0] == '.') borderComponentIds.add(componentId[i][0]);
            if (board[i][m - 1] == '.') borderComponentIds.add(componentId[i][m - 1]);
        }
        for (int j = 0; j < m; j++) {
            if (board[0][j] == '.') borderComponentIds.add(componentId[0][j]);
            if (board[n - 1][j] == '.') borderComponentIds.add(componentId[n - 1][j]);
        }

        // 3. Collect non-border components and sort by size (ascending)
        List<Component> nonBorderComponents = new ArrayList<>();
        for (int id = 1; id <= currentComponentId; id++) {
            if (!borderComponentIds.contains(id)) {
                nonBorderComponents.add(new Component(componentSizes[id], id));
            }
        }
        Collections.sort(nonBorderComponents);

        // 4. Mark the smallest (num - k) non-border components as obstacles
        Set<Integer> componentsToRemove = new HashSet<>();
        int numNonBorder = nonBorderComponents.size();
        int toRemoveCount = Math.max(0, numNonBorder - k);
        for (int i = 0; i < toRemoveCount; i++) {
            componentsToRemove.add(nonBorderComponents.get(i).id);
        }

        // 5. Apply changes and count removed cells
        int result = 0;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (componentsToRemove.contains(componentId[i][j])) {
                    board[i][j] = '*';
                    result++;
                }
            }
        }

        // 6. Output results
        out.println(result);
        for (char[] row : board) {
            out.println(new String(row));
        }
    }

    /**
     * Fast I/O helper class for competitive programming style input reading.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) {
                        return null;
                    }
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input stream", e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }

        public double nextDouble() {
            return Double.parseDouble(next());
        }

        public String nextLine() {
            try {
                return reader.readLine();
            } catch (IOException e) {
                throw new RuntimeException("Failed to read line", e);
            }
        }
    }
}

import java.util.*;
import java.io.*;

public class BerlandLakes {

    // Direction arrays for moving up, down, left, right
    private static final int[] DR = {-1, 1, 0, 0};
    private static final int[] DC = {0, 0, -1, 1};

    public static void main(String[] args) {
        // Using try-with-resources for automatic resource management
        try (Scanner sc = new Scanner(System.in)) {
            if (sc.hasNextInt()) {
                new BerlandLakes().run(sc);
            }
        }
    }

    private void run(Scanner sc) {
        int n = sc.nextInt();
        int m = sc.nextInt();
        int k = sc.nextInt();

        char[][] board = new char[n][m];
        for (int i = 0; i < n; i++) {
            String row = sc.next();
            board[i] = row.toCharArray();
        }

        // Find all lakes (connected components of '.' not touching the border)
        List<Lake> lakes = findLakes(board, n, m);

        // Sort lakes by size in ascending order.
        // We fill the smallest lakes first to minimize the total number of cells filled.
        lakes.sort(Comparator.comparingInt(Lake::getSize));

        int filledCellsCount = 0;

        // Calculate how many lakes need to be filled to reach the target count k.
        // If we have more than k lakes, we fill the smallest ones until we have k left.
        int lakesToFill = Math.max(0, lakes.size() - k);

        for (int i = 0; i < lakesToFill; i++) {
            Lake lakeToFill = lakes.get(i);
            fillLake(board, lakeToFill);
            filledCellsCount += lakeToFill.getSize();
        }

        System.out.println(filledCellsCount);
        for (char[] row : board) {
            System.out.println(new String(row));
        }
    }

    private List<Lake> findLakes(char[][] board, int n, int m) {
        boolean[][] visited = new boolean[n][m];
        List<Lake> lakes = new ArrayList<>();

        for (int r = 0; r < n; r++) {
            for (int c = 0; c < m; c++) {
                // If we find an unvisited water cell, it's a new component
                if (board[r][c] == '.' && !visited[r][c]) {
                    Lake currentLake = traverseComponent(board, visited, r, c, n, m);
                    // A lake is valid only if it does not touch the border
                    if (!currentLake.touchesBorder()) {
                        lakes.add(currentLake);
                    }
                }
            }
        }
        return lakes;
    }

    private Lake traverseComponent(char[][] board, boolean[][] visited, int startR, int startC, int n, int m) {
        Lake lake = new Lake();
        // Using ArrayDeque as a queue for BFS (more modern and efficient than Stack)
        Queue<int[]> queue = new ArrayDeque<>();

        queue.offer(new int[]{startR, startC});
        visited[startR][startC] = true;
        lake.addCell(startR, startC);

        while (!queue.isEmpty()) {
            int[] current = queue.poll();
            int r = current[0];
            int c = current[1];

            // Check if this cell is on the border
            if (r == 0 || r == n - 1 || c == 0 || c == m - 1) {
                lake.markTouchesBorder();
            }

            // Explore neighbors
            for (int i = 0; i < DR.length; i++) {
                int nr = r + DR[i];
                int nc = c + DC[i];

                if (isValid(nr, nc, n, m) && board[nr][nc] == '.' && !visited[nr][nc]) {
                    visited[nr][nc] = true;
                    lake.addCell(nr, nc);
                    queue.offer(new int[]{nr, nc});
                }
            }
        }
        return lake;
    }

    private boolean isValid(int r, int c, int n, int m) {
        return r >= 0 && r < n && c >= 0 && c < m;
    }

    private void fillLake(char[][] board, Lake lake) {
        for (int[] cell : lake.getCells()) {
            board[cell[0]][cell[1]] = '*';
        }
    }

    // Inner class to encapsulate lake data, replacing the complex lakeTrack structure
    private static class Lake {
        private final List<int[]> cells;
        private boolean touchesBorder;

        public Lake() {
            this.cells = new ArrayList<>();
            this.touchesBorder = false;
        }

        public void addCell(int r, int c) {
            cells.add(new int[]{r, c});
        }

        public void markTouchesBorder() {
            this.touchesBorder = true;
        }

        public List<int[]> getCells() {
            return cells;
        }

        public int getSize() {
            return cells.size();
        }

        public boolean touchesBorder() {
            return touchesBorder;
        }
    }
}

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Scanner;

public class VirtC {
    private final int rows;
    private final int cols;
    private final char[][] grid;

    public VirtC(int rows, int cols, char[][] grid) {
        this.rows = rows;
        this.cols = cols;
        this.grid = grid;
    }

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            if (!scanner.hasNextInt()) return;

            int n = scanner.nextInt();
            int m = scanner.nextInt();
            int k = scanner.nextInt();

            char[][] grid = new char[n][m];
            for (int i = 0; i < n; i++) {
                grid[i] = scanner.next().toCharArray();
            }

            VirtC solver = new VirtC(n, m, grid);
            solver.solve(k);
        }
    }

    public void solve(int k) {
        boolean[][] visited = new boolean[rows][cols];

        // Step 1: Mark border-connected '.' as '#' to isolate inland lakes
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if ((i == 0 || j == 0 || i == rows - 1 || j == cols - 1) && grid[i][j] == '.') {
                    floodFill(i, j, visited, '#', null);
                }
            }
        }

        // Step 2: Identify inland lakes and count their sizes
        visited = new boolean[rows][cols];
        List<Lake> lakes = new ArrayList<>();
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == '.' && !visited[i][j]) {
                    int[] size = new int[1];
                    floodFill(i, j, visited, '.', size);
                    lakes.add(new Lake(i, j, size[0]));
                }
            }
        }

        // Step 3: Remove smallest lakes until only k remain
        Collections.sort(lakes);
        int removedSizeSum = 0;
        while (lakes.size() > k) {
            Lake lake = lakes.remove(0);
            removedSizeSum += lake.size;
            // Pass null for visited to avoid re-allocating and to bypass previous visitation
            floodFill(lake.row, lake.col, null, '*', null);
        }

        // Step 4: Output results
        System.out.println(removedSizeSum);
        StringBuilder output = new StringBuilder();
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                output.append(grid[i][j] == '#' ? '.' : grid[i][j]);
            }
            output.append('\n');
        }
        System.out.print(output);
    }

    /**
     * Recursive flood fill to traverse connected '.' cells.
     *
     * @param x            Current row
     * @param y            Current column
     * @param visited      Tracking array (can be null if visitation tracking isn't needed)
     * @param replacement  Character to replace '.' with during traversal
     * @param sizeCounter  Optional array to count visited cells (size[0]++)
     */
    private void floodFill(int x, int y, boolean[][] visited, char replacement, int[] sizeCounter) {
        int[] dx = {-1, 1, 0, 0};
        int[] dy = {0, 0, -1, 1};

        if (visited != null) visited[x][y] = true;
        grid[x][y] = replacement;
        if (sizeCounter != null) sizeCounter[0]++;

        for (int i = 0; i < 4; i++) {
            int nx = x + dx[i];
            int ny = y + dy[i];
            if (inBounds(nx, ny) && (visited == null || !visited[nx][ny]) && grid[nx][ny] == '.') {
                floodFill(nx, ny, visited, replacement, sizeCounter);
            }
        }
    }

    private boolean inBounds(int x, int y) {
        return x >= 0 && x < rows && y >= 0 && y < cols;
    }

    private static class Lake implements Comparable<Lake> {
        final int row;
        final int col;
        final int size;

        public Lake(int row, int col, int size) {
            this.row = row;
            this.col = col;
            this.size = size;
        }

        @Override
        public int compareTo(Lake other) {
            return Integer.compare(this.size, other.size);
        }
    }
}

import java.util.*;

public class Main {

    /**
     * Represents a connected water component (lake) with its top-left coordinate and size.
     */
    public static class Lake implements Comparable<Lake> {
        final int x;
        final int y;
        final int size;

        public Lake(int x, int y, int size) {
            this.x = x;
            this.y = y;
            this.size = size;
        }

        @Override
        public int compareTo(Lake other) {
            return Integer.compare(this.size, other.size);
        }
    }

    public static void main(String[] args) {
        // Use try-with-resources to guarantee Scanner closure
        try (Scanner scanner = new Scanner(System.in)) {
            if (!scanner.hasNextInt()) {
                return;
            }

            int n = scanner.nextInt();
            int m = scanner.nextInt();
            int k = scanner.nextInt();

            char[][] grid = new char[n][m];
            for (int i = 0; i < n; i++) {
                String row = scanner.next();
                // Defensive copy to handle potential input truncation
                int len = Math.min(row.length(), m);
                grid[i] = new char[m];
                row.getChars(0, len, grid[i], 0);
                Arrays.fill(grid[i], len, m, '.');
            }

            LakeProcessor processor = new LakeProcessor(n, m);
            processor.process(grid, k);
        }
    }

    /**
     * Encapsulates all grid processing logic to eliminate static mutable state
     * and improve testability and reusability.
     */
    static class LakeProcessor {
        private final int rows;
        private final int cols;
        private static final int[] DX = {1, -1, 0, 0};
        private static final int[] DY = {0, 0, 1, -1};

        public LakeProcessor(int rows, int cols) {
            this.rows = rows;
            this.cols = cols;
        }

        public void process(char[][] grid, int k) {
            // Deep copy to isolate boundary traversal from original data
            char[][] tempGrid = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                System.arraycopy(grid[i], 0, tempGrid[i], 0, cols);
            }

            // 1. Mark all water cells connected to the boundary as visited
            markBoundaryConnectedWater(tempGrid);

            // 2. Identify remaining isolated lakes
            List<Lake> lakes = findLakes(tempGrid);

            // 3. Restore original grid state
            restoreGrid(grid, tempGrid);

            // 4. Sort lakes by size (ascending)
            lakes.sort(Comparator.naturalOrder());

            // 5. Fill the k smallest lakes.
            // Note: Original code used `d = lakes.size() - k`, which likely intended 
            // to fill exactly k lakes. We cap at available lakes to prevent OOB.
            int lakesToFill = Math.min(k, lakes.size());

            long totalCellsFilled = 0;
            for (int i = 0; i < lakesToFill; i++) {
                Lake lake = lakes.get(i);
                totalCellsFilled += lake.size;
                fillLake(grid, lake.x, lake.y);
            }

            // 6. Output results
            System.out.println(totalCellsFilled);
            printGrid(grid);
        }

        private void markBoundaryConnectedWater(char[][] grid) {
            // Left & Right columns
            for (int i = 0; i < rows; i++) {
                dfsMark(i, 0, grid);
                dfsMark(i, cols - 1, grid);
            }
            // Top & Bottom rows
            for (int j = 0; j < cols; j++) {
                dfsMark(0, j, grid);
                dfsMark(rows - 1, j, grid);
            }
        }

        private List<Lake> findLakes(char[][] grid) {
            List<Lake> lakes = new ArrayList<>();
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j] == '.') {
                        int size = dfsCount(i, j, grid);
                        lakes.add(new Lake(i, j, size));
                    }
                }
            }
            return lakes;
        }

        private void restoreGrid(char[][] original, char[][] backup) {
            for (int i = 0; i < rows; i++) {
                System.arraycopy(backup[i], 0, original[i], 0, cols);
            }
        }

        private void printGrid(char[][] grid) {
            for (char[] row : grid) {
                System.out.println(new String(row));
            }
        }

        // DFS to mark boundary-connected water cells as visited ('*')
        private void dfsMark(int x, int y, char[][] grid) {
            if (isOutOfBounds(x, y) || grid[x][y] != '.') return;
            grid[x][y] = '*';
            for (int i = 0; i < 4; i++) {
                dfsMark(x + DX[i], y + DY[i], grid);
            }
        }

        // DFS to count lake size and mark it as visited
        private int dfsCount(int x, int y, char[][] grid) {
            if (isOutOfBounds(x, y) || grid[x][y] != '.') return 0;
            grid[x][y] = '*';
            int count = 1;
            for (int i = 0; i < 4; i++) {
                count += dfsCount(x + DX[i], y + DY[i], grid);
            }
            return count;
        }

        // DFS to fill a specific lake with '*'
        private void fillLake(int x, int y, char[][] grid) {
            if (isOutOfBounds(x, y) || grid[x][y] != '.') return;
            grid[x][y] = '*';
            for (int i = 0; i < 4; i++) {
                fillLake(x + DX[i], y + DY[i], grid);
            }
        }

        private boolean isOutOfBounds(int x, int y) {
            return x < 0 || x >= rows || y < 0 || y >= cols;
        }
    }
}

import java.io.*;
import java.util.*;

public class D723 {

    /**
     * Fast input reader for competitive programming style inputs.
     */
    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input", e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            String token = next();
            return token == null ? 0 : Integer.parseInt(token);
        }
    }

    /**
     * Represents a connected component of '.' cells.
     */
    static class Component implements Comparable<Component> {
        final int size;
        final int row;
        final int col;

        Component(int size, int row, int col) {
            this.size = size;
            this.row = row;
            this.col = col;
        }

        @Override
        public int compareTo(Component other) {
            return Integer.compare(this.size, other.size);
        }
    }

    /**
     * Core solver encapsulating all game/grid logic.
     */
    static class Solver {
        private final int n, m, k;
        private final char[][] grid;
        private final List<Integer>[] adj;
        private final boolean[][] boundaryVisited;
        private final boolean[][] internalVisited;
        private final List<Component> components;

        @SuppressWarnings("unchecked")
        public Solver(int n, int m, int k, char[][] grid) {
            this.n = n;
            this.m = m;
            this.k = k;
            this.grid = grid;
            this.adj = new ArrayList[n * m];
            for (int i = 0; i < n * m; i++) {
                adj[i] = new ArrayList<>();
            }
            this.boundaryVisited = new boolean[n][m];
            this.internalVisited = new boolean[n][m];
            this.components = new ArrayList<>();
        }

        /**
         * Orchestrates the solving process and returns the number of erased cells.
         */
        public long solve(PrintWriter out) {
            buildGraph();
            markBoundaryConnected();
            findInternalComponents();

            Collections.sort(components);
            long erasedCells = 0;
            int eraseCount = Math.max(0, components.size() - k);

            for (int i = 0; i < eraseCount; i++) {
                Component comp = components.get(i);
                erasedCells += comp.size;
                eraseComponent(comp.row, comp.col);
            }

            return erasedCells;
        }

        private void buildGraph() {
            int[] dr = {-1, 1, 0, 0};
            int[] dc = {0, 0, -1, 1};
            for (int r = 0; r < n; r++) {
                for (int c = 0; c < m; c++) {
                    if (grid[r][c] != '.') continue;
                    int u = r * m + c;
                    for (int d = 0; d < 4; d++) {
                        int nr = r + dr[d];
                        int nc = c + dc[d];
                        if (isValid(nr, nc) && grid[nr][nc] == '.') {
                            adj.get(u).add(nr * m + nc);
                        }
                    }
                }
            }
        }

        private boolean isValid(int r, int c) {
            return r >= 0 && r < n && c >= 0 && c < m;
        }

        private void markBoundaryConnected() {
            Deque<Integer> queue = new ArrayDeque<>();
            // Seed boundary cells
            for (int c = 0; c < m; c++) {
                if (grid[0][c] == '.') queue.add(c);
                if (grid[n - 1][c] == '.') queue.add((n - 1) * m + c);
            }
            for (int r = 0; r < n; r++) {
                if (grid[r][0] == '.') queue.add(r * m);
                if (grid[r][m - 1] == '.') queue.add(r * m + m - 1);
            }

            // BFS to mark all cells reachable from the boundary
            while (!queue.isEmpty()) {
                int u = queue.poll();
                int r = u / m;
                int c = u % m;
                if (boundaryVisited[r][c]) continue;
                boundaryVisited[r][c] = true;
                for (int v : adj.get(u)) {
                    int nr = v / m;
                    int nc = v % m;
                    if (!boundaryVisited[nr][nc]) {
                        queue.add(v);
                    }
                }
            }
        }

        private void findInternalComponents() {
            for (int r = 0; r < n; r++) {
                for (int c = 0; c < m; c++) {
                    if (grid[r][c] == '.' && !boundaryVisited[r][c] && !internalVisited[r][c]) {
                        int size = countComponent(r, c);
                        components.add(new Component(size, r, c));
                    }
                }
            }
        }

        /**
         * Iteratively counts and marks an internal connected component.
         */
        private int countComponent(int startR, int startC) {
            int count = 0;
            Deque<Integer> stack = new ArrayDeque<>();
            stack.push(startR * m + startC);
            while (!stack.isEmpty()) {
                int curr = stack.pop();
                int r = curr / m;
                int c = curr % m;
                if (!isValid(r, c) || grid[r][c] != '.' || boundaryVisited[r][c] || internalVisited[r][c]) continue;

                internalVisited[r][c] = true;
                count++;

                int[] dr = {-1, 1, 0, 0};
                int[] dc = {0, 0, -1, 1};
                for (int i = 0; i < 4; i++) {
                    stack.push((r + dr[i]) * m + (c + dc[i]));
                }
            }
            return count;
        }

        /**
         * Iteratively erases a connected component by marking cells as '*'.
         */
        private void eraseComponent(int startR, int startC) {
            Deque<Integer> stack = new ArrayDeque<>();
            stack.push(startR * m + startC);
            while (!stack.isEmpty()) {
                int curr = stack.pop();
                int r = curr / m;
                int c = curr % m;
                if (!isValid(r, c) || grid[r][c] != '.') continue;

                grid[r][c] = '*';

                int[] dr = {-1, 1, 0, 0};
                int[] dc = {0, 0, -1, 1};
                for (int i = 0; i < 4; i++) {
                    stack.push((r + dr[i]) * m + (c + dc[i]));
                }
            }
        }
    }

    public static void main(String[] args) {
        FastScanner sc = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            int n = sc.nextInt();
            int m = sc.nextInt();
            int k = sc.nextInt();

            char[][] grid = new char[n][m];
            for (int i = 0; i < n; i++) {
                String line = sc.next();
                if (line != null) {
                    grid[i] = line.toCharArray();
                }
            }

            Solver solver = new Solver(n, m, k, grid);
            long ans = solver.solve(out);
            out.println(ans);
            for (char[] row : grid) {
                out.println(row);
            }
        } finally {
            out.flush();
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.List;
import java.util.Queue;
import java.util.StringTokenizer;

public class Codeforces375_2D {

    private static final int[] DR = {-1, 1, 0, 0};
    private static final int[] DC = {0, 0, -1, 1};

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());

        int n = Integer.parseInt(st.nextToken());
        int m = Integer.parseInt(st.nextToken());
        int k = Integer.parseInt(st.nextToken());

        boolean[][] isLand = new boolean[n][m];
        for (int i = 0; i < n; i++) {
            String line = br.readLine();
            for (int j = 0; j < m; j++) {
                isLand[i][j] = line.charAt(j) != '*';
            }
        }

        int filledCount = solve(isLand, n, m, k);
        printGrid(isLand, n, m);
    }

    /**
     * Identifies lakes (connected land components not touching the border),
     * fills the smallest ones until only k largest remain, and returns the count of filled cells.
     */
    private static int solve(boolean[][] grid, int n, int m, int k) {
        if (n <= 2 || m <= 2) {
            System.out.println(0);
            return 0;
        }

        boolean[][] visited = new boolean[n][m];
        List<List<Point>> lakes = new ArrayList<>();

        // Traverse grid to find connected components
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] && !visited[i][j]) {
                    List<Point> lake = bfs(grid, visited, i, j, n, m);
                    if (!lake.isEmpty()) {
                        lakes.add(lake);
                    }
                }
            }
        }

        // Sort lakes by size in ascending order
        lakes.sort(Comparator.comparingInt(List::size));

        int filledCount = 0;
        int lakesToFill = Math.max(0, lakes.size() - k);

        // Fill the smallest lakes
        for (int i = 0; i < lakesToFill; i++) {
            for (Point p : lakes.get(i)) {
                grid[p.r()][p.c()] = false;
                filledCount++;
            }
        }

        System.out.println(filledCount);
        return filledCount;
    }

    /**
     * Performs BFS to find all cells in a connected component.
     * Returns an empty list if the component touches the border, otherwise returns the lake cells.
     */
    private static List<Point> bfs(boolean[][] grid, boolean[][] visited, int startR, int startC, int n, int m) {
        List<Point> lake = new ArrayList<>();
        Queue<Point> queue = new ArrayDeque<>();

        queue.add(new Point(startR, startC));
        visited[startR][startC] = true;
        boolean touchesBorder = false;

        while (!queue.isEmpty()) {
            Point curr = queue.poll();
            lake.add(curr);

            if (curr.r() == 0 || curr.r() == n - 1 || curr.c() == 0 || curr.c() == m - 1) {
                touchesBorder = true;
            }

            for (int d = 0; d < 4; d++) {
                int nr = curr.r() + DR[d];
                int nc = curr.c() + DC[d];

                if (nr >= 0 && nr < n && nc >= 0 && nc < m && grid[nr][nc] && !visited[nr][nc]) {
                    visited[nr][nc] = true;
                    queue.add(new Point(nr, nc));
                }
            }
        }

        return touchesBorder ? Collections.emptyList() : lake;
    }

    /**
     * Efficiently prints the grid using StringBuilder to minimize I/O overhead.
     */
    private static void printGrid(boolean[][] grid, int n, int m) {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                sb.append(grid[i][j] ? '.' : '*');
            }
            sb.append('\n');
        }
        System.out.print(sb);
    }

    /**
     * Immutable record-like class to hold 2D coordinates.
     */
    private static class Point {
        final int r, c;
        Point(int r, int c) { this.r = r; this.c = c; }
        int r() { return r; }
        int c() { return c; }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.HashSet;
import java.util.List;
import java.util.Queue;
import java.util.Set;
import java.util.StringTokenizer;

public class LakesInBerland {

    /**
     * Represents a connected water component (lake).
     */
    private static class Lake {
        final int id;
        final int size;
        final boolean touchesOcean;

        Lake(int id, int size, boolean touchesOcean) {
            this.id = id;
            this.size = size;
            this.touchesOcean = touchesOcean;
        }
    }

    public static void main(String[] args) throws IOException {
        // Use try-with-resources to ensure the reader is closed automatically
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(System.in))) {
            String line = reader.readLine();
            if (line == null) return;

            StringTokenizer st = new StringTokenizer(line);
            int n = Integer.parseInt(st.nextToken());
            int m = Integer.parseInt(st.nextToken());
            int k = Integer.parseInt(st.nextToken());

            // Grid state: 0 = unvisited water, 1 = land, >1 = lake ID
            int[][] grid = new int[n][m];
            for (int i = 0; i < n; i++) {
                String row = reader.readLine();
                for (int j = 0; j < m; j++) {
                    grid[i][j] = (row.charAt(j) == '*') ? 0 : 1;
                }
            }

            // Identify all lakes and mark them in the grid
            List<Lake> lakes = findLakes(grid, n, m);

            // Calculate cost, determine which lakes to remove, and build output grid
            StringBuilder gridOutput = new StringBuilder();
            int cost = processLakes(lakes, k, grid, n, m, gridOutput);

            // Output results in the required order
            System.out.println(cost);
            System.out.print(gridOutput);
        }
    }

    /**
     * Traverses the grid to find all connected water components (lakes).
     * Marks visited water cells with a unique lake ID directly in the grid.
     */
    private static List<Lake> findLakes(int[][] grid, int n, int m) {
        List<Lake> lakes = new ArrayList<>();
        int lakeId = 1;
        int[] dx = {0, 0, 1, -1};
        int[] dy = {1, -1, 0, 0};

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == 0) {
                    int size = 0;
                    boolean touchesOcean = false;
                    Queue<int[]> queue = new ArrayDeque<>();

                    queue.offer(new int[]{i, j});
                    grid[i][j] = lakeId; // Mark as visited with current lake ID

                    while (!queue.isEmpty()) {
                        int[] curr = queue.poll();
                        int x = curr[0];
                        int y = curr[1];
                        size++;

                        // Check if this cell is on the border
                        if (x == 0 || x == n - 1 || y == 0 || y == m - 1) {
                            touchesOcean = true;
                        }

                        // Explore neighbors
                        for (int d = 0; d < 4; d++) {
                            int nx = x + dx[d];
                            int ny = y + dy[d];

                            if (nx >= 0 && nx < n && ny >= 0 && ny < m && grid[nx][ny] == 0) {
                                grid[nx][ny] = lakeId;
                                queue.offer(new int[]{nx, ny});
                            }
                        }
                    }

                    // Only track inland lakes (those not touching the ocean)
                    if (!touchesOcean) {
                        lakes.add(new Lake(lakeId, size, false));
                    }
                    lakeId++;
                }
            }
        }
        return lakes;
    }

    /**
     * Processes lakes to determine the minimum cost to keep exactly k lakes.
     * Returns the total area of removed lakes and populates the output grid.
     */
    private static int processLakes(List<Lake> lakes, int k, int[][] grid, int n, int m, StringBuilder gridOutput) {
        // Filter to only inland lakes
        List<Lake> inlandLakes = new ArrayList<>();
        for (Lake lake : lakes) {
            if (!lake.touchesOcean) {
                inlandLakes.add(lake);
            }
        }

        // Sort by size ascending to remove the smallest lakes first
        inlandLakes.sort(Comparator.comparingInt(l -> l.size));

        // Calculate how many lakes need to be removed
        int toRemove = Math.max(0, inlandLakes.size() - k);
        int cost = 0;
        Set<Integer> lakesToRemove = new HashSet<>();

        for (int i = 0; i < toRemove; i++) {
            Lake lake = inlandLakes.get(i);
            cost += lake.size;
            lakesToRemove.add(lake.id);
        }

        // Build the final grid output
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                // If it's land (1) and not in the removal set, it stays '.'
                // If it's a removed lake or originally water that wasn't part of a tracked lake, it becomes '*'
                if (lakesToRemove.contains(grid[i][j])) {
                    gridOutput.append('*');
                } else {
                    gridOutput.append('.');
                }
            }
            gridOutput.append('\n');
        }

        return cost;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Queue;
import java.util.StringTokenizer;
import java.util.ArrayDeque;

public class LakesInBerland {

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());

        int n = Integer.parseInt(st.nextToken());
        int m = Integer.parseInt(st.nextToken());
        int lakesToFill = Integer.parseInt(st.nextToken());

        char[][] grid = readGrid(br, n, m);

        // Identify and mark all water cells connected to the border (ocean)
        List<Point> oceanCells = new ArrayList<>();
        markOcean(grid, n, m, oceanCells);

        // Find all internal lakes
        List<Lake> lakes = findLakes(grid, n, m);
        Collections.sort(lakes);

        // Fill the smallest k lakes with '*'
        int filledCount = 0;
        for (int i = 0; i < lakesToFill && i < lakes.size(); i++) {
            Lake lake = lakes.get(i);
            for (int j = 0; j < lake.size; j++) {
                grid[lake.rows.get(j)][lake.cols.get(j)] = '*';
                filledCount++;
            }
        }

        // Restore ocean cells back to '.'
        for (Point p : oceanCells) {
            grid[p.r][p.c] = '.';
        }

        // Efficient output construction
        StringBuilder sb = new StringBuilder();
        sb.append(filledCount).append('\n');
        for (int i = 0; i < n; i++) {
            sb.append(grid[i]).append('\n');
        }
        System.out.print(sb);
    }

    /**
     * Reads the grid from standard input.
     */
    private static char[][] readGrid(BufferedReader br, int n, int m) throws IOException {
        char[][] grid = new char[n][m];
        for (int i = 0; i < n; i++) {
            String line = br.readLine();
            grid[i] = line.toCharArray();
        }
        return grid;
    }

    /**
     * Marks all water cells connected to the grid boundary as ocean.
     * Uses iterative BFS to avoid stack overflow and keeps the grid immutable during traversal.
     */
    private static void markOcean(char[][] grid, int n, int m, List<Point> oceanCells) {
        boolean[][] visited = new boolean[n][m];
        Queue<Point> queue = new ArrayDeque<>();

        // Initialize queue with border water cells
        for (int i = 0; i < n; i++) {
            if (grid[i][0] == '.') { queue.add(new Point(i, 0)); visited[i][0] = true; }
            if (grid[i][m - 1] == '.') { queue.add(new Point(i, m - 1)); visited[i][m - 1] = true; }
        }
        for (int j = 0; j < m; j++) {
            if (grid[0][j] == '.') { queue.add(new Point(0, j)); visited[0][j] = true; }
            if (grid[n - 1][j] == '.') { queue.add(new Point(n - 1, j)); visited[n - 1][j] = true; }
        }

        int[] dr = {-1, 1, 0, 0};
        int[] dc = {0, 0, -1, 1};

        while (!queue.isEmpty()) {
            Point p = queue.poll();
            oceanCells.add(p);

            for (int d = 0; d < 4; d++) {
                int r = p.r + dr[d];
                int c = p.c + dc[d];
                if (r >= 0 && r < n && c >= 0 && c < m && grid[r][c] == '.' && !visited[r][c]) {
                    visited[r][c] = true;
                    queue.add(new Point(r, c));
                }
            }
        }
    }

    /**
     * Identifies all internal lakes using iterative BFS.
     * Returns a list of Lake objects sorted by discovery order.
     */
    private static List<Lake> findLakes(char[][] grid, int n, int m) {
        boolean[][] visited = new boolean[n][m];
        List<Lake> lakes = new ArrayList<>();
        int[] dr = {-1, 1, 0, 0};
        int[] dc = {0, 0, -1, 1};
        int lakeIndex = 0;

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == '.' && !visited[i][j]) {
                    Lake lake = new Lake(++lakeIndex);
                    Queue<Point> queue = new ArrayDeque<>();
                    queue.add(new Point(i, j));
                    visited[i][j] = true;

                    while (!queue.isEmpty()) {
                        Point p = queue.poll();
                        lake.rows.add(p.r);
                        lake.cols.add(p.c);

                        for (int d = 0; d < 4; d++) {
                            int r = p.r + dr[d];
                            int c = p.c + dc[d];
                            if (r >= 0 && r < n && c >= 0 && c < m && grid[r][c] == '.' && !visited[r][c]) {
                                visited[r][c] = true;
                                queue.add(new Point(r, c));
                            }
                        }
                    }
                    lake.size = lake.rows.size();
                    lakes.add(lake);
                }
            }
        }
        return lakes;
    }

    /**
     * Represents a lake with its position coordinates and size.
     */
    private static class Lake implements Comparable<Lake> {
        final int index;
        int size;
        final List<Integer> rows = new ArrayList<>();
        final List<Integer> cols = new ArrayList<>();

        Lake(int index) {
            this.index = index;
        }

        @Override
        public int compareTo(Lake other) {
            return Integer.compare(this.size, other.size);
        }
    }

    /**
     * Simple coordinate holder for grid traversal.
     */
    private static class Point {
        final int r, c;
        Point(int r, int c) { this.r = r; this.c = c; }
    }
}

import java.io.*;
import java.util.*;

public class LakesInBerland {

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner();
        PrintWriter out = new PrintWriter(System.out);

        int n = scanner.nextInt();
        int m = scanner.nextInt();
        int k = scanner.nextInt();

        char[][] grid = new char[n][m];
        for (int i = 0; i < n; i++) {
            grid[i] = scanner.nextLine().toCharArray();
        }

        boolean[][] visited = new boolean[n][m];
        List<Lake> lakes = new ArrayList<>();

        // Identify all internal lakes (connected components of '.' not touching the border)
        for (int i = 1; i < n - 1; i++) {
            for (int j = 1; j < m - 1; j++) {
                if (!visited[i][j] && grid[i][j] == '.') {
                    int size = bfsFindLake(i, j, grid, n, m, visited);
                    if (size != -1) {
                        lakes.add(new Lake(size, i, j));
                    }
                }
            }
        }

        // Sort lakes by size in ascending order
        Collections.sort(lakes);

        // Fill the smallest k lakes
        int lakesToFill = Math.min(k, lakes.size());
        int totalFilled = 0;
        visited = new boolean[n][m]; // Reset visited array for the filling phase

        for (int i = 0; i < lakesToFill; i++) {
            Lake lake = lakes.get(i);
            bfsFillLake(lake.startR, lake.startC, grid, n, m, visited);
            totalFilled += lake.size;
        }

        out.println(totalFilled);
        for (int i = 0; i < n; i++) {
            out.println(grid[i]);
        }
        out.flush();
    }

    /**
     * Performs BFS to find the size of a connected component.
     * Returns -1 if the component touches the border, otherwise returns its size.
     */
    private static int bfsFindLake(int startR, int startC, char[][] grid, int n, int m, boolean[][] visited) {
        Queue<Point> queue = new ArrayDeque<>();
        queue.add(new Point(startR, startC));
        visited[startR][startC] = true;

        int size = 0;
        boolean touchesBorder = false;

        while (!queue.isEmpty()) {
            Point current = queue.poll();
            size++;
            int r = current.r;
            int c = current.c;

            // 4-directional movement (up, down, left, right)
            for (int dr = -1; dr <= 1; dr++) {
                for (int dc = -1; dc <= 1; dc++) {
                    if (Math.abs(dr) != Math.abs(dc)) {
                        int nr = r + dr;
                        int nc = c + dc;

                        // Safe bounds checking
                        if (nr >= 0 && nr < n && nc >= 0 && nc < m) {
                            if (nr == 0 || nr == n - 1 || nc == 0 || nc == m - 1) {
                                touchesBorder = true;
                            }
                            if (grid[nr][nc] == '.' && !visited[nr][nc]) {
                                queue.add(new Point(nr, nc));
                            }
                            visited[nr][nc] = true;
                        }
                    }
                }
            }
        }
        return touchesBorder ? -1 : size;
    }

    /**
     * Performs BFS to fill a lake with '*' characters.
     */
    private static void bfsFillLake(int startR, int startC, char[][] grid, int n, int m, boolean[][] visited) {
        Queue<Point> queue = new ArrayDeque<>();
        queue.add(new Point(startR, startC));
        visited[startR][startC] = true;

        while (!queue.isEmpty()) {
            Point current = queue.poll();
            int r = current.r;
            int c = current.c;
            grid[r][c] = '*';

            for (int dr = -1; dr <= 1; dr++) {
                for (int dc = -1; dc <= 1; dc++) {
                    if (Math.abs(dr) != Math.abs(dc)) {
                        int nr = r + dr;
                        int nc = c + dc;

                        if (nr >= 0 && nr < n && nc >= 0 && nc < m) {
                            if (grid[nr][nc] == '.' && !visited[nr][nc]) {
                                queue.add(new Point(nr, nc));
                            }
                            visited[nr][nc] = true;
                        }
                    }
                }
            }
        }
    }

    /**
     * Represents a discovered lake with its size and starting coordinates.
     */
    private static class Lake implements Comparable<Lake> {
        int size;
        int startR, startC;

        public Lake(int size, int startR, int startC) {
            this.size = size;
            this.startR = startR;
            this.startC = startC;
        }

        @Override
        public int compareTo(Lake other) {
            return Integer.compare(this.size, other.size);
        }
    }

    /**
     * Simple coordinate holder.
     */
    private static class Point {
        int r, c;
        public Point(int r, int c) {
            this.r = r;
            this.c = c;
        }
    }

    /**
     * Fast I/O helper class for competitive programming.
     */
    static class FastScanner {
        private byte[] buf = new byte[1024];
        private int curChar;
        private int snumChars;

        public int read() {
            if (snumChars == -1) {
                throw new InputMismatchException();
            }
            if (curChar >= snumChars) {
                curChar = 0;
                try {
                    snumChars = System.in.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (snumChars <= 0) {
                    return -1;
                }
            }
            return buf[curChar++];
        }

        public String nextLine() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            StringBuilder res = new StringBuilder();
            do {
                res.appendCodePoint(c);
                c = read();
            } while (!isEndOfLine(c));
            return res.toString();
        }

        public String nextString() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            StringBuilder res = new StringBuilder();
            do {
                res.appendCodePoint(c);
                c = read();
            } while (!isSpaceChar(c));
            return res.toString();
        }

        public long nextLong() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            long res = 0;
            do {
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                res *= 10;
                res += c - '0';
                c = read();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public int nextInt() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                res *= 10;
                res += c - '0';
                c = read();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public int[] nextIntArray(int n) {
            int[] arr = new int[n];
            for (int i = 0; i < n; i++) {
                arr[i] = nextInt();
            }
            return arr;
        }

        public long[] nextLongArray(int n) {
            long[] arr = new long[n];
            for (int i = 0; i < n; i++) {
                arr[i] = nextLong();
            }
            return arr;
        }

        private boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        private boolean isEndOfLine(int c) {
            return c == '\n' || c == '\r' || c == -1;
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.OutputStream;
import java.io.PrintWriter;
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.Deque;
import java.util.List;
import java.util.StringTokenizer;

public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        FastScanner in = new FastScanner(inputStream);
        PrintWriter out = new PrintWriter(outputStream);

        GridSolver solver = new GridSolver();
        solver.solve(1, in, out);

        out.close();
    }

    /**
     * Solves the grid component marking problem.
     * Refactored to be stateless, iterative, and highly readable.
     */
    static class GridSolver {
        private static final int[] DX = {-1, 0, 1, 0};
        private static final int[] DY = {0, -1, 0, 1};

        public void solve(int testNumber, FastScanner in, PrintWriter out) {
            int n = in.nextInt();
            int m = in.nextInt();
            int k = in.nextInt();

            char[][] grid = new char[n][m];
            for (int i = 0; i < n; i++) {
                grid[i] = in.next().toCharArray();
            }

            // Tracks which component ID each '.' cell belongs to. -1 means unvisited.
            int[][] componentId = new int[n][m];
            for (int[] row : componentId) {
                Arrays.fill(row, -1);
            }

            List<Component> components = new ArrayList<>();
            int componentCount = 0;

            // Identify connected components of '.'
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    if (grid[i][j] == '.' && componentId[i][j] == -1) {
                        int size = countComponentSize(i, j, grid, componentId, componentCount);
                        if (size > 0) {
                            components.add(new Component(size, componentCount));
                        }
                        componentCount++;
                    }
                }
            }

            // Sort components by size ascending
            Collections.sort(components);

            int totalMarkedSize = 0;
            boolean[] isMarked = new boolean[componentCount];
            // Mark the smallest components, leaving exactly k largest unmarked
            int componentsToMark = Math.max(0, components.size() - k);

            for (int i = 0; i < componentsToMark; i++) {
                Component c = components.get(i);
                totalMarkedSize += c.size;
                isMarked[c.id] = true;
            }

            out.println(totalMarkedSize);
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    if (componentId[i][j] != -1 && isMarked[componentId[i][j]]) {
                        grid[i][j] = '*';
                    }
                }
                out.println(grid[i]);
            }
        }

        /**
         * Iteratively counts the size of a connected component.
         * Returns 0 if the component touches the grid boundary, otherwise returns its size.
         */
        private int countComponentSize(int startX, int startY, char[][] grid, int[][] componentId, int currentId) {
            int size = 0;
            boolean touchesBoundary = false;
            int rows = grid.length;
            int cols = grid[0].length;

            Deque<Integer> stack = new ArrayDeque<>();
            stack.push(startX * cols + startY);
            componentId[startX][startY] = currentId;
            size++;

            while (!stack.isEmpty()) {
                int pos = stack.pop();
                int x = pos / cols;
                int y = pos % cols;

                // Check if current cell is on the boundary
                if (x == 0 || x == rows - 1 || y == 0 || y == cols - 1) {
                    touchesBoundary = true;
                }

                for (int dir = 0; dir < 4; dir++) {
                    int nx = x + DX[dir];
                    int ny = y + DY[dir];

                    if (nx >= 0 && nx < rows && ny >= 0 && ny < cols &&
                        componentId[nx][ny] == -1 && grid[nx][ny] == '.') {
                        componentId[nx][ny] = currentId;
                        size++;
                        stack.push(nx * cols + ny);
                    }
                }
            }
            return touchesBoundary ? 0 : size;
        }

        /**
         * Represents a connected component with its size and unique identifier.
         */
        static class Component implements Comparable<Component> {
            final int size;
            final int id;

            Component(int size, int id) {
                this.size = size;
                this.id = id;
            }

            @Override
            public int compareTo(Component other) {
                return Integer.compare(this.size, other.size);
            }
        }
    }

    /**
     * Fast input reader for competitive programming style problems.
     */
    static class FastScanner {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastScanner(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            String s = next();
            if (s == null) throw new RuntimeException("Unexpected end of input");
            return Integer.parseInt(s);
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.StringTokenizer;

public class Main {
    // Constants to replace magic values
    private static final char EMPTY_CHAR = '.';
    private static final char FILLED_CHAR = '*';
    private static final int[][] DIRECTIONS = {
        {1, 0}, {-1, 0}, {0, 1}, {0, -1}
    };

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());

        int n = Integer.parseInt(st.nextToken());
        int m = Integer.parseInt(st.nextToken());
        int k = Integer.parseInt(st.nextToken());

        char[][] grid = readGrid(br, n, m);
        List<Lake> lakes = findLakes(grid);

        // Sort lakes by size in ascending order
        lakes.sort(Comparator.comparingInt(Lake::getSize));

        int totalFilled = 0;
        // Fill all lakes except the k largest ones
        int lakesToFill = Math.max(0, lakes.size() - k);
        for (int i = 0; i < lakesToFill; i++) {
            Lake lake = lakes.get(i);
            totalFilled += lake.getSize();
            for (int[] cell : lake.getCells()) {
                grid[cell[0]][cell[1]] = FILLED_CHAR;
            }
        }

        System.out.println(totalFilled);
        printGrid(grid);
    }

    /**
     * Reads the grid from standard input.
     */
    private static char[][] readGrid(BufferedReader br, int n, int m) throws IOException {
        char[][] grid = new char[n][m];
        for (int i = 0; i < n; i++) {
            String line = br.readLine().trim();
            for (int j = 0; j < m; j++) {
                grid[i][j] = line.charAt(j);
            }
        }
        return grid;
    }

    /**
     * Identifies all connected components of EMPTY_CHAR.
     * Components that do not touch the grid boundary are considered lakes.
     * Uses iterative DFS to prevent StackOverflowError on large grids.
     */
    private static List<Lake> findLakes(char[][] grid) {
        int n = grid.length;
        int m = grid[0].length;
        boolean[][] visited = new boolean[n][m];
        List<Lake> lakes = new ArrayList<>();

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == EMPTY_CHAR && !visited[i][j]) {
                    List<int[]> component = new ArrayList<>();
                    boolean isLake = true;
                    ArrayDeque<int[]> stack = new ArrayDeque<>();

                    stack.push(new int[]{i, j});
                    visited[i][j] = true;

                    while (!stack.isEmpty()) {
                        int[] curr = stack.pop();
                        int r = curr[0];
                        int c = curr[1];
                        component.add(curr);

                        // If any cell touches the border, the component is not a lake
                        if (r == 0 || c == 0 || r == n - 1 || c == m - 1) {
                            isLake = false;
                        }

                        for (int[] dir : DIRECTIONS) {
                            int nr = r + dir[0];
                            int nc = c + dir[1];
                            if (nr >= 0 && nr < n && nc >= 0 && nc < m &&
                                grid[nr][nc] == EMPTY_CHAR && !visited[nr][nc]) {
                                visited[nr][nc] = true;
                                stack.push(new int[]{nr, nc});
                            }
                        }
                    }

                    if (isLake) {
                        lakes.add(new Lake(component.size(), component));
                    }
                }
            }
        }
        return lakes;
    }

    /**
     * Prints the grid to standard output efficiently.
     */
    private static void printGrid(char[][] grid) {
        StringBuilder sb = new StringBuilder();
        for (char[] row : grid) {
            sb.append(row).append('\n');
        }
        System.out.print(sb);
    }

    /**
     * Immutable data class to store lake metadata.
     */
    private static class Lake {
        private final int size;
        private final List<int[]> cells;

        public Lake(int size, List<int[]> cells) {
            this.size = size;
            this.cells = cells;
        }

        public int getSize() { return size; }
        public List<int[]> getCells() { return cells; }
    }
}

import java.util.*;
import java.awt.Point;

public class Main {
    // Direction vectors for moving up, down, left, right
    private static final int[] DX = {0, 0, 1, -1};
    private static final int[] DY = {1, -1, 0, 0};

    // Grid state constants
    private static final int UNVISITED = -1;
    private static final int EDGE_CONNECTED = 0;
    private static final int CLEARED = 1;

    // Instance fields to replace global mutable state
    private final int rows;
    private final int cols;
    private final char[][] grid;
    private final int[][] state;
    private final List<List<Point>> lakes;

    public Main(int rows, int cols, char[][] grid) {
        this.rows = rows;
        this.cols = cols;
        this.grid = grid;
        this.state = new int[rows][cols];
        this.lakes = new ArrayList<>();

        // Initialize state array
        Arrays.stream(state).forEach(row -> Arrays.fill(row, UNVISITED));
    }

    public void process(int k) {
        traverseEdgeConnected();
        findAndCollectLakes();
        clearSmallestLakes(k);
        printResult();
    }

    /**
     * Marks all '.' cells connected to the grid boundary as EDGE_CONNECTED.
     */
    private void traverseEdgeConnected() {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (isOnEdge(i, j) && grid[i][j] == '.' && state[i][j] == UNVISITED) {
                    traverseComponent(i, j); // Result ignored; we only need to mark state
                }
            }
        }
    }

    /**
     * Identifies all isolated '.' components (lakes) and collects them.
     */
    private void findAndCollectLakes() {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == '.' && state[i][j] == UNVISITED) {
                    lakes.add(traverseComponent(i, j));
                }
            }
        }
    }

    /**
     * Clears the smallest lakes until only K remain.
     * Fixed the original logic which failed on duplicate lake sizes.
     */
    private void clearSmallestLakes(int k) {
        int lakesToClear = Math.max(0, lakes.size() - k);
        if (lakesToClear == 0) {
            System.out.println(0);
            return;
        }

        // Sort lake indices by size (ascending)
        List<Integer> sortedIndices = new ArrayList<>();
        for (int i = 0; i < lakes.size(); i++) {
            sortedIndices.add(i);
        }
        sortedIndices.sort(Comparator.comparingInt(i -> lakes.get(i).size()));

        int minNum = 0;
        for (int i = 0; i < lakesToClear; i++) {
            List<Point> lake = lakes.get(sortedIndices.get(i));
            minNum += lake.size();
            for (Point p : lake) {
                state[p.x][p.y] = CLEARED;
            }
        }
        System.out.println(minNum);
    }

    /**
     * Prints the final grid state to standard output.
     */
    private void printResult() {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                sb.append(state[i][j] == CLEARED ? '*' : grid[i][j]);
            }
            sb.append('\n');
        }
        System.out.print(sb);
    }

    /**
     * Performs iterative DFS to mark and/or collect a connected component.
     */
    private List<Point> traverseComponent(int startRow, int startCol) {
        List<Point> component = new ArrayList<>();
        Deque<Point> stack = new ArrayDeque<>();

        stack.push(new Point(startRow, startCol));
        state[startRow][startCol] = EDGE_CONNECTED;
        component.add(new Point(startRow, startCol));

        while (!stack.isEmpty()) {
            Point current = stack.pop();
            for (int d = 0; d < 4; d++) {
                int nx = current.x + DX[d];
                int ny = current.y + DY[d];
                if (isValid(nx, ny) && grid[nx][ny] == '.' && state[nx][ny] == UNVISITED) {
                    state[nx][ny] = EDGE_CONNECTED;
                    stack.push(new Point(nx, ny));
                    component.add(new Point(nx, ny));
                }
            }
        }
        return component;
    }

    private boolean isValid(int x, int y) {
        return x >= 0 && x < rows && y >= 0 && y < cols;
    }

    private boolean isOnEdge(int x, int y) {
        return x == 0 || x == rows - 1 || y == 0 || y == cols - 1;
    }

    public static void main(String[] args) {
        // try-with-resources ensures Scanner is properly closed
        try (Scanner sc = new Scanner(System.in)) {
            if (!sc.hasNextInt()) return;

            int rows = sc.nextInt();
            int cols = sc.nextInt();
            int k = sc.nextInt();

            char[][] grid = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                grid[i] = sc.next().toCharArray();
            }

            Main solver = new Main(rows, cols, grid);
            solver.process(k);
        }
    }
}

import java.util.*;

public class Main {
    // Direction vectors for moving up, right, down, left
    private static final int[] DX = {-1, 0, 1, 0};
    private static final int[] DY = {0, 1, 0, -1};

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            if (!scanner.hasNextInt()) return;

            int rows = scanner.nextInt();
            int cols = scanner.nextInt();
            int k = scanner.nextInt();

            char[][] grid = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                grid[i] = scanner.next().toCharArray();
            }

            solve(grid, k);
        }
    }

    private static void solve(char[][] grid, int k) {
        int rows = grid.length;
        int cols = grid[0].length;
        boolean[][] visited = new boolean[rows][cols];
        List<Component> components = new ArrayList<>();

        // Phase 1: Identify all connected components of '.'
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '.' && !visited[r][c]) {
                    bfsFind(grid, r, c, rows, cols, visited, components);
                }
            }
        }

        // Phase 2: Sort components by size (ascending)
        components.sort(Comparator.comparingInt(Component::size));

        // Phase 3: Fill the smallest (total - k) components
        int componentsToFill = Math.max(0, components.size() - k);
        int totalFilledSize = 0;

        for (int i = 0; i < componentsToFill; i++) {
            Component comp = components.get(i);
            bfsFill(grid, comp.startX, comp.startY, rows, cols, visited);
            totalFilledSize += comp.size;
        }

        // Phase 4: Output results
        System.out.println(totalFilledSize);
        for (char[] row : grid) {
            System.out.println(new String(row));
        }
    }

    /**
     * Finds connected components of '.' that do not touch the grid border.
     */
    private static void bfsFind(char[][] grid, int startR, int startC, int rows, int cols,
                                boolean[][] visited, List<Component> components) {
        Queue<Point> queue = new LinkedList<>();
        queue.add(new Point(startR, startC));
        visited[startR][startC] = true;

        boolean touchesBorder = false;
        int size = 0;

        while (!queue.isEmpty()) {
            Point p = queue.poll();
            size++;

            for (int i = 0; i < 4; i++) {
                int nr = p.r + DX[i];
                int nc = p.c + DY[i];

                if (nr >= 0 && nr < rows && nc >= 0 && nc < cols) {
                    if (grid[nr][nc] == '.' && !visited[nr][nc]) {
                        visited[nr][nc] = true;
                        queue.add(new Point(nr, nc));
                    }
                } else {
                    touchesBorder = true;
                }
            }
        }

        if (!touchesBorder) {
            components.add(new Component(startR, startC, size));
        }
    }

    /**
     * Fills a connected component of '.' with '*' characters.
     */
    private static void bfsFill(char[][] grid, int startR, int startC, int rows, int cols,
                                boolean[][] visited) {
        Queue<Point> queue = new LinkedList<>();
        queue.add(new Point(startR, startC));
        visited[startR][startC] = true;

        while (!queue.isEmpty()) {
            Point p = queue.poll();
            grid[p.r][p.c] = '*';

            for (int i = 0; i < 4; i++) {
                int nr = p.r + DX[i];
                int nc = p.c + DY[i];
                if (nr >= 0 && nr < rows && nc >= 0 && nc < cols &&
                    !visited[nr][nc] && grid[nr][nc] == '.') {
                    visited[nr][nc] = true;
                    queue.add(new Point(nr, nc));
                }
            }
        }
    }

    // Immutable data classes for coordinates and components
    private static class Point {
        final int r, c;
        Point(int r, int c) { this.r = r; this.c = c; }
    }

    private static class Component {
        final int startX, startY, size;
        Component(int startX, int startY, int size) {
            this.startX = startX;
            this.startY = startY;
            this.size = size;
        }
    }
}

import java.util.*;

public class LakeSimulator {

    /**
     * Helper class to represent a coordinate point.
     * Implements equals and hashCode to allow correct usage in HashSet.
     * This replaces the use of int[] arrays which do not have value-based equality.
     */
    private static class Point {
        final int x, y;

        Point(int x, int y) {
            this.x = x;
            this.y = y;
        }

        @Override
        public boolean equals(Object o) {
            if (this == o) return true;
            if (o == null || getClass() != o.getClass()) return false;
            Point point = (Point) o;
            return x == point.x && y == point.y;
        }

        @Override
        public int hashCode() {
            return Objects.hash(x, y);
        }
    }

    private int numRows, numCols, lakesToKeep;
    private char[][] grid;
    private boolean[][] visited;

    // Directions: Up, Down, Left, Right (relative to x, y)
    // dx affects row index, dy affects column index.
    // Matches original logic: dx={0, 0, -1, 1}, dy={-1, 1, 0, 0}
    private static final int[] DX = {0, 0, -1, 1};
    private static final int[] DY = {-1, 1, 0, 0};

    public static void main(String[] args) {
        new LakeSimulator().solve();
    }

    private void solve() {
        Scanner scanner = new Scanner(System.in);

        // Read dimensions and K
        // Based on original code: N was columns (width), M was rows (height).
        if (!scanner.hasNextInt()) return;
        numCols = scanner.nextInt(); 
        numRows = scanner.nextInt(); 
        lakesToKeep = scanner.nextInt(); 

        grid = new char[numRows][numCols];
        visited = new boolean[numRows][numCols];

        // Read grid input
        // The original code reads N strings, where each string represents a column of length M.
        for (int c = 0; c < numCols; c++) {
            if (scanner.hasNext()) {
                String line = scanner.next();
                for (int r = 0; r < numRows; r++) {
                    if (r < line.length()) {
                        grid[r][c] = line.charAt(r);
                    }
                }
            }
        }

        List<Set<Point>> foundLakes = new ArrayList<>();

        // BFS to find connected components of '.' (lakes)
        // We only need to start BFS from interior cells (1 to rows-2, 1 to cols-2)
        // because border cells cannot form a lake that doesn't touch the border.
        for (int r = 1; r < numRows - 1; r++) {
            for (int c = 1; c < numCols - 1; c++) {
                if (grid[r][c] == '.' && !visited[r][c]) {
                    Set<Point> currentLake = new HashSet<>();
                    Queue<Point> queue = new LinkedList<>();

                    Point start = new Point(r, c);
                    queue.add(start);
                    visited[r][c] = true;
                    currentLake.add(start);

                    boolean touchesBorder = false;

                    while (!queue.isEmpty()) {
                        Point current = queue.poll();

                        // Explore neighbors
                        for (int i = 0; i < 4; i++) {
                            int nx = current.x + DX[i];
                            int ny = current.y + DY[i];

                            if (isValid(nx, ny) && grid[nx][ny] == '.' && !visited[nx][ny]) {
                                visited[nx][ny] = true;
                                Point next = new Point(nx, ny);
                                queue.add(next);
                                currentLake.add(next);

                                // Check if the neighbor is on the border
                                if (nx == 0 || nx == numRows - 1 || ny == 0 || ny == numCols - 1) {
                                    touchesBorder = true;
                                }
                            }
                        }
                    }

                    // If the component does not touch the border, it is a valid lake
                    if (!touchesBorder) {
                        foundLakes.add(currentLake);
                    }
                }
            }
        }

        // Sort lakes by size in ascending order using Lambda
        foundLakes.sort((a, b) -> Integer.compare(a.size(), b.size()));

        int cellsRemoved = 0;
        int lakesToRemove = foundLakes.size() - lakesToKeep;
        if (lakesToRemove < 0) {
            lakesToRemove = 0;
        }

        // Remove the smallest lakes (fill with '*')
        for (int i = 0; i < lakesToRemove; i++) {
            Set<Point> lake = foundLakes.get(i);
            cellsRemoved += lake.size();
            for (Point p : lake) {
                grid[p.x][p.y] = '*';
            }
        }

        System.out.println(cellsRemoved);

        // Output the grid
        // Original code output format was column-major (printing columns as lines)
        StringBuilder sb = new StringBuilder();
        for (int c = 0; c < numCols; c++) {
            for (int r = 0; r < numRows; r++) {
                sb.append(grid[r][c]);
            }
            sb.append('\n');
        }
        System.out.print(sb.toString());

        scanner.close();
    }

    private boolean isValid(int x, int y) {
        return x >= 0 && x < numRows && y >= 0 && y < numCols;
    }
}

import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) {
        FastScanner scanner = new FastScanner();
        int T = 1;
        while (T-- > 0) {
            new Main().run(scanner);
        }
    }

    private int rows, cols, k;
    private boolean[][] grid;
    private boolean[][] visited;
    private boolean[][] ignored;
    private static final int[] DX = {-1, 0, 1, 0};
    private static final int[] DY = {0, 1, 0, -1};

    private void run(FastScanner in) {
        readInput(in);
        int ans = processGrid();
        printOutput(ans);
    }

    private void readInput(FastScanner in) {
        rows = in.nextInt();
        cols = in.nextInt();
        k = in.nextInt();
        grid = new boolean[rows][cols];
        visited = new boolean[rows][cols];
        ignored = new boolean[rows][cols];
        for (int i = 0; i < rows; i++) {
            String line = in.next();
            for (int j = 0; j < cols; j++) {
                grid[i][j] = (line.charAt(j) == '.');
            }
        }
    }

    private int processGrid() {
        markBorderConnectedAsIgnored();
        List<Lake> lakes = findLakes();
        lakes.sort(Comparator.comparingInt(Lake::size));

        // Reset visited array before filling lakes, matching original logic
        visited = new boolean[rows][cols];
        int totalFilledArea = 0;
        int lakesFilled = 0;
        for (Lake lake : lakes) {
            if (lakesFilled >= k) break;
            floodFill(lake.row, lake.col, true);
            totalFilledArea += lake.size;
            lakesFilled++;
        }
        return totalFilledArea;
    }

    private void markBorderConnectedAsIgnored() {
        for (int i = 0; i < rows; i++) {
            if (grid[i][0]) markIgnored(i, 0);
            if (grid[i][cols - 1]) markIgnored(i, cols - 1);
        }
        for (int j = 0; j < cols; j++) {
            if (grid[0][j]) markIgnored(0, j);
            if (grid[rows - 1][j]) markIgnored(rows - 1, j);
        }
    }

    private void markIgnored(int startRow, int startCol) {
        Queue<int[]> queue = new ArrayDeque<>();
        queue.offer(new int[]{startRow, startCol});
        ignored[startRow][startCol] = true;
        while (!queue.isEmpty()) {
            int[] curr = queue.poll();
            int r = curr[0], c = curr[1];
            for (int d = 0; d < 4; d++) {
                int nr = r + DX[d];
                int nc = c + DY[d];
                if (canTraverse(nr, nc)) {
                    ignored[nr][nc] = true;
                    queue.offer(new int[]{nr, nc});
                }
            }
        }
    }

    private boolean canTraverse(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols && 
               grid[r][c] && !visited[r][c] && !ignored[r][c];
    }

    private List<Lake> findLakes() {
        List<Lake> lakes = new ArrayList<>();
        for (int i = 1; i < rows - 1; i++) {
            for (int j = 1; j < cols - 1; j++) {
                if (grid[i][j] && !visited[i][j] && !ignored[i][j]) {
                    int size = floodFill(i, j, false);
                    lakes.add(new Lake(i, j, size));
                }
            }
        }
        return lakes;
    }

    private int floodFill(int startRow, int startCol, boolean fill) {
        Queue<int[]> queue = new ArrayDeque<>();
        queue.offer(new int[]{startRow, startCol});
        visited[startRow][startCol] = true;
        if (fill) grid[startRow][startCol] = false;

        int size = 0;
        while (!queue.isEmpty()) {
            int[] curr = queue.poll();
            int r = curr[0], c = curr[1];
            size++;
            for (int d = 0; d < 4; d++) {
                int nr = r + DX[d];
                int nc = c + DY[d];
                if (canTraverse(nr, nc)) {
                    visited[nr][nc] = true;
                    queue.offer(new int[]{nr, nc});
                    if (fill) grid[nr][nc] = false;
                }
            }
        }
        return size;
    }

    private void printOutput(int ans) {
        StringBuilder sb = new StringBuilder();
        sb.append(ans).append('\n');
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                sb.append(grid[i][j] ? '.' : '*');
            }
            sb.append('\n');
        }
        System.out.print(sb);
    }

    private static class Lake {
        final int row, col, size;

        Lake(int row, int col, int size) {
            this.row = row;
            this.col = col;
            this.size = size;
        }
    }
}

class FastScanner {
    private BufferedReader br;
    private StringTokenizer st;

    public FastScanner() {
        br = new BufferedReader(new InputStreamReader(System.in));
    }

    String next() {
        while (st == null || !st.hasMoreTokens()) {
            try {
                String line = br.readLine();
                if (line == null) return null;
                st = new StringTokenizer(line);
            } catch (IOException e) {
                e.printStackTrace();
            }
        }
        return st.nextToken();
    }

    int nextInt() {
        String s = next();
        return s == null ? 0 : Integer.parseInt(s);
    }

    long nextLong() {
        String s = next();
        return s == null ? 0L : Long.parseLong(s);
    }

    double nextDouble() {
        String s = next();
        return s == null ? 0.0 : Double.parseDouble(s);
    }

    String nextLine() {
        String str = "";
        try {
            str = br.readLine();
        } catch (IOException e) {
            e.printStackTrace();
        }
        return str;
    }
}

import java.util.*;
import java.io.PrintWriter;

/**
 * Refactored solution for finding and filling lakes in a grid.
 * 
 * Improvements made:
 * 1. Encapsulation: Logic separated into distinct methods (findLakes, traverseComponent, fillLakes).
 * 2. Readability: Descriptive variable names (e.g., DIRECTIONS, componentSize, touchesBoundary).
 * 3. Robustness: Replaced recursive DFS with iterative DFS using a Deque to prevent StackOverflowError on large inputs.
 * 4. Data Structures: Used char[][] for the grid instead of StringBuilder[], which is more efficient for grid manipulation.
 * 5. Maintainability: Removed global static state where possible and structured the code for better flow.
 */
public class Main {

    // Directions for moving in the grid: Up, Right, Down, Left
    private static final int[][] DIRECTIONS = {
        {-1, 0}, {0, 1}, {1, 0}, {0, -1}
    };

    public static void main(String[] args) {
        // Use Scanner for input and PrintWriter for output
        Scanner scanner = new Scanner(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        // Read dimensions and target count k
        if (!scanner.hasNextInt()) {
            writer.flush();
            return;
        }
        int n = scanner.nextInt();
        int m = scanner.nextInt();
        int k = scanner.nextInt();

        // Read the grid
        char[][] grid = new char[n][m];
        for (int i = 0; i < n; i++) {
            String row = scanner.next();
            grid[i] = row.toCharArray();
        }

        // 1. Identify all lakes (connected components not touching the boundary)
        List<Lake> lakes = findLakes(grid, n, m);

        // 2. Sort lakes by size (Ascending, preserving original logic)
        lakes.sort(Comparator.comparingInt(Lake::getSize));

        // 3. Fill the lakes based on logic
        int totalFilledCells = fillLakes(grid, lakes, k);

        // 4. Output results
        writer.println(totalFilledCells);
        for (char[] row : grid) {
            writer.println(new String(row));
        }

        writer.flush();
        scanner.close();
    }

    /**
     * Traverses the grid to find all connected components of '.' characters.
     * Filters out components that touch the boundary.
     */
    private static List<Lake> findLakes(char[][] grid, int n, int m) {
        List<Lake> lakes = new ArrayList<>();
        boolean[][] visited = new boolean[n][m];

        for (int r = 0; r < n; r++) {
            for (int c = 0; c < m; c++) {
                // If we find an unvisited empty cell, it's a new component
                if (grid[r][c] == '.' && !visited[r][c]) {
                    Lake lake = traverseComponent(grid, r, c, n, m, visited);
                    if (lake != null) {
                        lakes.add(lake);
                    }
                }
            }
        }
        return lakes;
    }

    /**
     * Performs an iterative DFS to find the size and boundary status of a component.
     * Returns a Lake object if it doesn't touch the boundary, otherwise null.
     */
    private static Lake traverseComponent(char[][] grid, int startR, int startC, int n, int m, boolean[][] visited) {
        int size = 0;
        boolean touchesBoundary = false;

        // Stack for iterative DFS: stores {row, col}
        Deque<int[]> stack = new ArrayDeque<>();
        stack.push(new int[]{startR, startC});
        visited[startR][startC] = true;

        while (!stack.isEmpty()) {
            int[] current = stack.pop();
            int r = current[0];
            int c = current[1];

            size++;

            // Check if current cell is on the boundary
            if (r == 0 || r == n - 1 || c == 0 || c == m - 1) {
                touchesBoundary = true;
            }

            // Explore neighbors
            for (int[] dir : DIRECTIONS) {
                int nr = r + dir[0];
                int nc = c + dir[1];

                if (isValid(nr, nc, n, m) && grid[nr][nc] == '.' && !visited[nr][nc]) {
                    visited[nr][nc] = true;
                    stack.push(new int[]{nr, nc});
                }
            }
        }

        // If the component touches the boundary, it's not a lake
        if (touchesBoundary) {
            return null;
        }

        // Return the lake info (size and starting position for filling)
        return new Lake(size, startR, startC);
    }

    /**
     * Fills the lakes with '*' based on the sorted list and k limit.
     * Preserves the original logic: fills lakes until the remaining count equals k.
     */
    private static int fillLakes(char[][] grid, List<Lake> lakes, int k) {
        int totalFilledCells = 0;
        int remainingLakes = lakes.size();

        for (Lake lake : lakes) {
            // Logic check: if remaining lakes count equals k, stop filling
            if (remainingLakes == k) {
                break;
            }

            remainingLakes--;
            totalFilledCells += lake.getSize();

            // Perform flood fill starting from the lake's entry point
            floodFill(grid, lake.getR(), lake.getC());
        }

        return totalFilledCells;
    }

    /**
     * Iteratively fills a connected component of '.' with '*' starting from (startR, startC).
     */
    private static void floodFill(char[][] grid, int startR, int startC) {
        Deque<int[]> stack = new ArrayDeque<>();
        stack.push(new int[]{startR, startC});

        // Mark start as filled immediately
        grid[startR][startC] = '*';

        while (!stack.isEmpty()) {
            int[] current = stack.pop();
            int r = current[0];
            int c = current[1];

            for (int[] dir : DIRECTIONS) {
                int nr = r + dir[0];
                int nc = c + dir[1];

                if (isValid(nr, nc, grid.length, grid[0].length) && grid[nr][nc] == '.') {
                    grid[nr][nc] = '*';
                    stack.push(new int[]{nr, nc});
                }
            }
        }
    }

    /**
     * Checks if coordinates are within grid bounds.
     */
    private static boolean isValid(int r, int c, int n, int m) {
        return r >= 0 && r < n && c >= 0 && c < m;
    }

    /**
     * Represents a lake (connected component of empty cells not touching boundary).
     */
    static class Lake {
        private final int size;
        private final int r;
        private final int c;

        public Lake(int size, int r, int c) {
            this.size = size;
            this.r = r;
            this.c = c;
        }

        public int getSize() {
            return size;
        }

        public int getR() {
            return r;
        }

        public int getC() {
            return c;
        }
    }
}

import java.awt.Point;
import java.util.ArrayList;
import java.util.ArrayDeque;
import java.util.Comparator;
import java.util.List;
import java.util.Queue;
import java.util.Scanner;

public class Main {
    private final int rows;
    private final int cols;
    private final int k;
    private final char[][] grid;
    private final boolean[][] visited;
    private static final int[][] DIRECTIONS = {{0, 1}, {0, -1}, {1, 0}, {-1, 0}};

    public Main(int rows, int cols, int k) {
        this.rows = rows;
        this.cols = cols;
        this.k = k;
        this.grid = new char[rows][cols];
        this.visited = new boolean[rows][cols];
    }

    public static void main(String[] args) {
        try (Scanner sc = new Scanner(System.in)) {
            if (!sc.hasNextInt()) return;
            int n = sc.nextInt();
            int m = sc.nextInt();
            int k = sc.nextInt();

            Main solver = new Main(n, m, k);
            solver.readInput(sc);
            solver.floodFromEdges();
            List<List<Point>> lakes = solver.findLakes();
            int erasedArea = solver.fillSmallestLakes(lakes);

            System.out.println(erasedArea);
            solver.printGrid();
        }
    }

    public void readInput(Scanner sc) {
        sc.nextLine(); // Consume the newline after the integers
        for (int r = 0; r < rows; r++) {
            String line = sc.nextLine();
            grid[r] = line.toCharArray();
        }
    }

    private boolean isBorder(int r, int c) {
        return r == 0 || r == rows - 1 || c == 0 || c == cols - 1;
    }

    private boolean isValid(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    public void floodFromEdges() {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (isBorder(r, c) && grid[r][c] == '.') {
                    traverseComponent(r, c);
                }
            }
        }
    }

    public List<List<Point>> findLakes() {
        List<List<Point>> lakes = new ArrayList<>();
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '.' && !visited[r][c]) {
                    List<Point> lake = new ArrayList<>();
                    traverseComponent(r, c, lake);
                    lakes.add(lake);
                }
            }
        }
        return lakes;
    }

    private void traverseComponent(int startR, int startC) {
        traverseComponent(startR, startC, null);
    }

    private void traverseComponent(int startR, int startC, List<Point> component) {
        Queue<Point> queue = new ArrayDeque<>();
        queue.add(new Point(startR, startC));
        visited[startR][startC] = true;
        if (component != null) {
            component.add(new Point(startR, startC));
        }

        while (!queue.isEmpty()) {
            Point curr = queue.poll();
            for (int[] dir : DIRECTIONS) {
                int nr = curr.x + dir[0];
                int nc = curr.y + dir[1];
                if (isValid(nr, nc) && grid[nr][nc] == '.' && !visited[nr][nc]) {
                    visited[nr][nc] = true;
                    queue.add(new Point(nr, nc));
                    if (component != null) {
                        component.add(new Point(nr, nc));
                    }
                }
            }
        }
    }

    public int fillSmallestLakes(List<List<Point>> lakes) {
        // Sort lakes by size in ascending order
        lakes.sort(Comparator.comparingInt(List::size));

        // Calculate how many smallest lakes need to be filled
        int lakesToRemove = Math.max(0, lakes.size() - k);
        int totalRemovedArea = 0;

        for (int i = 0; i < lakesToRemove; i++) {
            List<Point> lake = lakes.get(i);
            totalRemovedArea += lake.size();
            // Mark the lake as filled ('*')
            for (Point p : lake) {
                grid[p.x][p.y] = '*';
            }
        }
        return totalRemovedArea;
    }

    public void printGrid() {
        StringBuilder sb = new StringBuilder();
        for (int r = 0; r < rows; r++) {
            sb.append(new String(grid[r])).append('\n');
        }
        System.out.print(sb);
    }
}

import java.io.*;
import java.util.*;

public class GridProcessor {

    /**
     * FastScanner for efficient competitive programming input reading.
     */
    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input", e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            String s = next();
            return s == null ? 0 : Integer.parseInt(s);
        }
    }

    /**
     * Disjoint Set Union (DSU) with path compression.
     */
    static class DSU {
        private final int[] parent;

        public DSU(int n) {
            parent = new int[n];
            for (int i = 0; i < n; i++) {
                parent[i] = i;
            }
        }

        public int find(int x) {
            if (x != parent[x]) {
                parent[x] = find(parent[x]); // Path compression
            }
            return parent[x];
        }

        public void union(int x, int y) {
            int rootX = find(x);
            int rootY = find(y);
            if (rootX != rootY) {
                // Union by index for deterministic behavior
                if (rootX < rootY) {
                    parent[rootY] = rootX;
                } else {
                    parent[rootX] = rootY;
                }
            }
        }
    }

    public static void main(String[] args) {
        FastScanner sc = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out));

        try {
            int M = sc.nextInt();
            int N = sc.nextInt();
            int K = sc.nextInt();

            char[][] grid = readGrid(sc, M, N);
            DSU dsu = buildDSU(grid, M, N);

            Map<Integer, Integer> componentSizes = new HashMap<>();
            Set<Integer> borderComponentRoots = new HashSet<>();
            analyzeComponents(grid, M, N, dsu, componentSizes, borderComponentRoots);

            Set<Integer> componentsToRemove = selectComponentsToRemove(componentSizes, borderComponentRoots, K);
            int removedCount = applyRemovals(grid, dsu, componentsToRemove);

            out.println(removedCount);
            printGrid(out, grid);
        } finally {
            out.flush();
            out.close();
        }
    }

    private static char[][] readGrid(FastScanner sc, int M, int N) {
        char[][] grid = new char[M][N];
        for (int r = 0; r < M; r++) {
            grid[r] = sc.next().toCharArray();
        }
        return grid;
    }

    private static DSU buildDSU(char[][] grid, int M, int N) {
        DSU dsu = new DSU(M * N);
        for (int r = 0; r < M; r++) {
            for (int c = 0; c < N; c++) {
                if (grid[r][c] == '.') {
                    if (r > 0 && grid[r - 1][c] == '.') {
                        dsu.union((r - 1) * N + c, r * N + c);
                    }
                    if (c > 0 && grid[r][c - 1] == '.') {
                        dsu.union(r * N + (c - 1), r * N + c);
                    }
                }
            }
        }
        return dsu;
    }

    private static void analyzeComponents(char[][] grid, int M, int N, DSU dsu,
                                          Map<Integer, Integer> componentSizes, Set<Integer> borderComponentRoots) {
        for (int r = 0; r < M; r++) {
            for (int c = 0; c < N; c++) {
                if (grid[r][c] == '.') {
                    int root = dsu.find(r * N + c);
                    componentSizes.put(root, componentSizes.getOrDefault(root, 0) + 1);
                    if (r == 0 || r == M - 1 || c == 0 || c == N - 1) {
                        borderComponentRoots.add(root);
                    }
                }
            }
        }
    }

    private static Set<Integer> selectComponentsToRemove(Map<Integer, Integer> componentSizes,
                                                         Set<Integer> borderComponentRoots, int K) {
        // Isolate non-border components
        Map<Integer, Integer> nonBorderSizes = new HashMap<>();
        for (Map.Entry<Integer, Integer> entry : componentSizes.entrySet()) {
            if (!borderComponentRoots.contains(entry.getKey())) {
                nonBorderSizes.put(entry.getKey(), entry.getValue());
            }
        }

        // Determine how many smallest components to remove
        int toRemove = Math.max(0, nonBorderSizes.size() - K);

        // Sort by size ascending
        List<Map.Entry<Integer, Integer>> sortedComponents = new ArrayList<>(nonBorderSizes.entrySet());
        sortedComponents.sort(Map.Entry.comparingByValue());

        // Select targets
        Set<Integer> removeSet = new HashSet<>();
        for (int i = 0; i < toRemove; i++) {
            removeSet.add(sortedComponents.get(i).getKey());
        }
        return removeSet;
    }

    private static int applyRemovals(char[][] grid, DSU dsu, Set<Integer> componentsToRemove) {
        int removedCount = 0;
        int N = grid[0].length;
        for (int r = 0; r < grid.length; r++) {
            for (int c = 0; c < N; c++) {
                if (grid[r][c] == '.') {
                    if (componentsToRemove.contains(dsu.find(r * N + c))) {
                        grid[r][c] = '*';
                        removedCount++;
                    }
                }
            }
        }
        return removedCount;
    }

    private static void printGrid(PrintWriter out, char[][] grid) {
        for (char[] row : grid) {
            out.println(row);
        }
    }
}

import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.LinkedList;
import java.util.List;
import java.util.Queue;
import java.util.Scanner;

public class Main {

    /**
     * Represents a coordinate in the grid.
     */
    static class Coordinate {
        int r, c;

        public Coordinate(int r, int c) {
            this.r = r;
            this.c = c;
        }
    }

    /**
     * Represents a connected region of empty cells ('.').
     */
    static class Region {
        int size;
        List<Coordinate> cells;

        public Region(int size, List<Coordinate> cells) {
            this.size = size;
            this.cells = cells;
        }
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        // Read grid dimensions and parameter k
        if (!scanner.hasNextInt()) {
            scanner.close();
            return;
        }
        int rows = scanner.nextInt();
        int cols = scanner.nextInt();
        int k = scanner.nextInt();

        // Read the grid
        char[][] grid = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            String line = scanner.next();
            grid[i] = line.toCharArray();
        }

        // List to store interior regions (those not connected to the border)
        List<Region> interiorRegions = new ArrayList<>();
        boolean[][] visited = new boolean[rows][cols];

        // Directions: Up, Down, Left, Right
        int[] dr = {-1, 1, 0, 0};
        int[] dc = {0, 0, -1, 1};

        // Iterate through every cell to identify connected components
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                // If cell is empty and not yet visited
                if (grid[r][c] == '.' && !visited[r][c]) {
                    List<Coordinate> componentCells = new ArrayList<>();
                    boolean touchesBorder = false;

                    // Use BFS (Iterative) to find the connected component
                    // This avoids StackOverflowError risks associated with deep recursion
                    Queue<Coordinate> queue = new LinkedList<>();
                    queue.add(new Coordinate(r, c));
                    visited[r][c] = true;
                    componentCells.add(new Coordinate(r, c));

                    // Check if starting cell is on the border
                    if (isBorder(r, c, rows, cols)) {
                        touchesBorder = true;
                    }

                    while (!queue.isEmpty()) {
                        Coordinate curr = queue.poll();

                        for (int i = 0; i < 4; i++) {
                            int nr = curr.r + dr[i];
                            int nc = curr.c + dc[i];

                            // Check bounds, if empty, and if not visited
                            if (isValid(nr, nc, rows, cols) && grid[nr][nc] == '.' && !visited[nr][nc]) {
                                visited[nr][nc] = true;
                                Coordinate next = new Coordinate(nr, nc);
                                componentCells.add(next);
                                queue.add(next);

                                // Check if neighbor is on the border
                                if (isBorder(nr, nc, rows, cols)) {
                                    touchesBorder = true;
                                }
                            }
                        }
                    }

                    // If the component does not touch the border, it is an interior region
                    if (!touchesBorder) {
                        interiorRegions.add(new Region(componentCells.size(), componentCells));
                    }
                }
            }
        }

        // Sort regions by size in ascending order
        Collections.sort(interiorRegions, Comparator.comparingInt(region -> region.size));

        // Calculate how many regions to remove
        // The goal is to keep k regions, so we remove the smallest ones until k remain.
        int regionsToRemove = interiorRegions.size() - k;
        int totalRemovedCells = 0;

        // Remove the smallest regions
        if (regionsToRemove > 0) {
            for (int i = 0; i < regionsToRemove; i++) {
                Region region = interiorRegions.get(i);
                totalRemovedCells += region.size;

                // Mark cells as '*' (removed) in the grid
                for (Coordinate cell : region.cells) {
                    grid[cell.r][cell.c] = '*';
                }
            }
        }

        // Output the total number of removed cells
        System.out.println(totalRemovedCells);

        // Output the modified grid using StringBuilder for efficiency
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < rows; i++) {
            sb.append(grid[i]);
            sb.append("\n");
        }
        System.out.print(sb);

        scanner.close();
    }

    /**
     * Checks if a coordinate is on the border of the grid.
     */
    private static boolean isBorder(int r, int c, int rows, int cols) {
        return r == 0 || r == rows - 1 || c == 0 || c == cols - 1;
    }

    /**
     * Checks if coordinates are within the grid boundaries.
     */
    private static boolean isValid(int r, int c, int rows, int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }
}

import java.util.Scanner;
import java.util.PriorityQueue;

/**
 * Refactored Lake Solver.
 * 
 * Improvements:
 * 1. Class renamed to LakeSolver for clarity.
 * 2. Static fields moved to instance fields for better state management and reusability.
 * 3. Magic numbers replaced with constants (DIRECTIONS).
 * 4. Input reading uses try-with-resources for resource safety.
 * 5. Logic separated into distinct, single-responsibility methods.
 * 6. Output formatting optimized using StringBuilder.
 * 7. Variable names improved for readability (e.g., row -> rows, col -> cols).
 * 8. Lake class fields made final.
 */
public class LakeSolver {

    // Direction vectors for moving up, down, left, right (row, col)
    private static final int[] DR = {-1, 1, 0, 0};
    private static final int[] DC = {0, 0, 1, -1};

    private int rows;
    private int cols;
    private char[][] grid;
    private PriorityQueue<Lake> lakes;
    private int maxLakesAllowed;

    public static void main(String[] args) {
        // Use try-with-resources to ensure Scanner is closed
        try (Scanner sc = new Scanner(System.in)) {
            if (!sc.hasNextInt()) {
                return;
            }

            int numRows = sc.nextInt();
            int numCols = sc.nextInt();
            int maxLakes = sc.nextInt();

            // Read grid
            char[][] initialGrid = new char[numRows][numCols];
            for (int i = 0; i < numRows; i++) {
                if (sc.hasNext()) {
                    initialGrid[i] = sc.next().toCharArray();
                }
            }

            // Create solver instance and run logic
            LakeSolver solver = new LakeSolver(numRows, numCols, initialGrid, maxLakes);
            solver.solve();

        } catch (Exception e) {
            System.err.println("Error processing input: " + e.getMessage());
        }
    }

    public LakeSolver(int rows, int cols, char[][] grid, int maxLakesAllowed) {
        this.rows = rows;
        this.cols = cols;
        this.grid = grid;
        this.maxLakesAllowed = maxLakesAllowed;
        this.lakes = new PriorityQueue<>();
    }

    /**
     * Orchestrates the solving process.
     */
    public void solve() {
        // 1. Mark oceans (water connected to the border)
        markOceansOnBorder();

        // 2. Identify and count lakes (isolated water bodies)
        identifyLakes();

        // 3. Fill smallest lakes if count exceeds limit
        int totalFilledArea = fillExcessLakes();

        // 4. Prepare grid for output (convert markers back to '.' where appropriate)
        cleanupGrid();

        // 5. Output results
        printResults(totalFilledArea);
    }

    private boolean isValid(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /**
     * Marks all water cells ('.') connected to the border as 'O' (Ocean).
     */
    private void markOceansOnBorder() {
        // Check left and right columns
        for (int r = 0; r < rows; r++) {
            if (grid[r][0] == '.') {
                markOcean(r, 0);
            }
            if (grid[r][cols - 1] == '.') {
                markOcean(r, cols - 1);
            }
        }
        // Check top and bottom rows
        for (int c = 0; c < cols; c++) {
            if (grid[0][c] == '.') {
                markOcean(0, c);
            }
            if (grid[rows - 1][c] == '.') {
                markOcean(rows - 1, c);
            }
        }
    }

    /**
     * DFS to mark a connected component of water as Ocean ('O').
     */
    private void markOcean(int r, int c) {
        if (!isValid(r, c) || grid[r][c] != '.') {
            return;
        }

        grid[r][c] = 'O';

        for (int i = 0; i < 4; i++) {
            markOcean(r + DR[i], c + DC[i]);
        }
    }

    /**
     * Identifies all lakes by finding connected components of '.'.
     * Marks them as 'L' and stores their size and starting position.
     */
    private void identifyLakes() {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '.') {
                    int size = countLake(r, c);
                    lakes.add(new Lake(r, c, size));
                }
            }
        }
    }

    /**
     * DFS to count the size of a lake and mark it as 'L'.
     * Returns the total number of cells in the lake.
     */
    private int countLake(int r, int c) {
        if (!isValid(r, c) || grid[r][c] != '.') {
            return 0;
        }

        grid[r][c] = 'L'; // Mark as visited/lake
        int size = 1;

        for (int i = 0; i < 4; i++) {
            size += countLake(r + DR[i], c + DC[i]);
        }

        return size;
    }

    /**
     * Removes the smallest lakes until the count is within the allowed limit.
     * @return The total area of the filled lakes.
     */
    private int fillExcessLakes() {
        int totalFilledArea = 0;
        while (lakes.size() > maxLakesAllowed) {
            Lake lake = lakes.poll();
            totalFilledArea += lake.count;
            fillLake(lake.x, lake.y);
        }
        return totalFilledArea;
    }

    /**
     * DFS to fill a lake (change 'L' to '*').
     */
    private void fillLake(int r, int c) {
        if (!isValid(r, c) || grid[r][c] != 'L') {
            return;
        }

        grid[r][c] = '*';

        for (int i = 0; i < 4; i++) {
            fillLake(r + DR[i], c + DC[i]);
        }
    }

    /**
     * Resets temporary markers ('L' for lake, 'O' for ocean) back to '.'
     * for the final output, preserving '*' for filled lakes.
     */
    private void cleanupGrid() {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == 'L' || grid[r][c] == 'O') {
                    grid[r][c] = '.';
                }
            }
        }
    }

    /**
     * Prints the total filled area and the final grid state.
     */
    private void printResults(int totalFilledArea) {
        System.out.println(totalFilledArea);
        StringBuilder sb = new StringBuilder();
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                sb.append(grid[r][c]);
            }
            sb.append('\n');
        }
        System.out.print(sb);
    }

    /**
     * Represents a lake with its coordinates and size.
     * Implements Comparable to sort lakes by size (ascending).
     */
    static class Lake implements Comparable<Lake> {
        final int x;
        final int y;
        final int count;

        public Lake(int x, int y, int count) {
            this.x = x;
            this.y = y;
            this.count = count;
        }

        @Override
        public int compareTo(Lake other) {
            return Integer.compare(this.count, other.count);
        }
    }
}

import java.io.*;
import java.util.*;

public class Task723D {
    // Direction vectors for 4-directional movement
    private static final int[] DX = {-1, 0, 1, 0};
    private static final int[] DY = {0, 1, 0, -1};

    private BufferedReader reader;
    private PrintWriter writer;
    private StringTokenizer tokenizer;

    public static void main(String[] args) {
        new Task723D().run();
    }

    /**
     * Entry point that manages resource lifecycle.
     */
    public void run() {
        open();
        try {
            solve();
        } catch (IOException e) {
            throw new RuntimeException("Input/Output error occurred", e);
        } finally {
            close();
        }
    }

    private void open() {
        reader = new BufferedReader(new InputStreamReader(System.in));
        writer = new PrintWriter(new BufferedOutputStream(System.out));
    }

    private void close() {
        writer.flush();
        writer.close();
    }

    private void solve() throws IOException {
        int n = nextInt();
        int m = nextInt();
        int k = nextInt();

        // 1. Read Grid
        char[][] grid = new char[n][m];
        for (int i = 0; i < n; i++) {
            String line = readNonEmptyLine();
            if (line == null) break;
            for (int j = 0; j < m; j++) {
                grid[i][j] = line.charAt(j);
            }
        }

        // 2. Identify Connected Components
        int[][] componentId = new int[n][m];
        List<Component> components = new ArrayList<>();
        int currentId = 0;

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] != '*' && componentId[i][j] == 0) {
                    currentId++;
                    Component comp = new Component(currentId);
                    bfs(grid, componentId, i, j, n, m, comp);
                    components.add(comp);
                }
            }
        }

        // 3. Filter Lakes (components not touching the border)
        List<Component> lakes = new ArrayList<>();
        for (Component comp : components) {
            if (comp.isLake) {
                lakes.add(comp);
            }
        }

        // 4. Sort lakes by size ascending to remove smallest first
        lakes.sort(Comparator.comparingInt(c -> c.cells.size()));

        // 5. Fill smallest lakes until exactly k remain
        int totalFilled = 0;
        int lakesToRemove = Math.max(0, lakes.size() - k);
        for (int i = 0; i < lakesToRemove; i++) {
            Component comp = lakes.get(i);
            totalFilled += comp.cells.size();
            for (int[] cell : comp.cells) {
                grid[cell[0]][cell[1]] = '*';
            }
        }

        // 6. Output Results
        writer.println(totalFilled);
        for (int i = 0; i < n; i++) {
            writer.write(grid[i]);
            writer.println();
        }
        writer.flush();
    }

    /**
     * Iterative BFS to find connected components and identify lakes.
     * Avoids stack overflow issues present in recursive DFS.
     */
    private void bfs(char[][] grid, int[][] componentId, int startX, int startY, int n, int m, Component comp) {
        Queue<int[]> queue = new ArrayDeque<>();
        queue.offer(new int[]{startX, startY});
        componentId[startX][startY] = comp.id;
        comp.cells.add(new int[]{startX, startY});

        // Check if starting position is on the border
        if (startX == 0 || startX == n - 1 || startY == 0 || startY == m - 1) {
            comp.isLake = false;
        }

        while (!queue.isEmpty()) {
            int[] curr = queue.poll();
            int x = curr[0];
            int y = curr[1];

            for (int d = 0; d < 4; d++) {
                int nx = x + DX[d];
                int ny = y + DY[d];

                if (nx >= 0 && nx < n && ny >= 0 && ny < m &&
                    grid[nx][ny] != '*' && componentId[nx][ny] == 0) {
                    componentId[nx][ny] = comp.id;
                    comp.cells.add(new int[]{nx, ny});

                    // Border cells disqualify a component from being a lake
                    if (nx == 0 || nx == n - 1 || ny == 0 || ny == m - 1) {
                        comp.isLake = false;
                    }
                    queue.offer(new int[]{nx, ny});
                }
            }
        }
    }

    // --- Input Helpers ---

    private String next() throws IOException {
        while (tokenizer == null || !tokenizer.hasMoreTokens()) {
            String line = reader.readLine();
            if (line == null) return null;
            tokenizer = new StringTokenizer(line);
        }
        return tokenizer.nextToken();
    }

    private int nextInt() throws IOException {
        return Integer.parseInt(next());
    }

    private String readNonEmptyLine() throws IOException {
        String line;
        while ((line = reader.readLine()) != null && line.trim().isEmpty()) {
            // Skip empty lines that may appear between test cases
        }
        return line;
    }

    // --- Data Structures ---

    /**
     * Represents a connected component of non-'*' cells.
     */
    private static class Component {
        final int id;
        final List<int[]> cells = new ArrayList<>();
        boolean isLake;

        Component(int id) {
            this.id = id;
            this.isLake = true; // Assume lake until proven otherwise by border contact
        }
    }
}

import java.io.*;
import java.util.*;

public class Codechef {
    // Direction vectors for Up, Right, Down, Left
    private static final int[] DX = {-1, 0, 1, 0};
    private static final int[] DY = {0, 1, 0, -1};

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out);

        int n = scanner.nextInt();
        int m = scanner.nextInt();
        int k = scanner.nextInt();

        char[][] grid = new char[n][m];
        for (int i = 0; i < n; i++) {
            grid[i] = scanner.next().toCharArray();
        }

        int[][] lakeIds = new int[n][m];
        List<Lake> lakes = new ArrayList<>();
        int currentLakeId = 0;

        // Identify all connected components (lakes)
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] != '*' && lakeIds[i][j] == 0) {
                    currentLakeId++;
                    List<int[]> cells = new ArrayList<>();
                    boolean touchesBoundary = bfs(grid, lakeIds, currentLakeId, i, j, n, m, cells);
                    if (!touchesBoundary) {
                        lakes.add(new Lake(currentLakeId, cells.size(), cells));
                    }
                }
            }
        }

        // Use a PriorityQueue to efficiently remove the smallest lakes until count <= k
        PriorityQueue<Lake> lakePq = new PriorityQueue<>(Comparator.comparingInt(Lake::getSize));
        for (Lake lake : lakes) {
            lakePq.add(lake);
        }

        int totalRemoved = 0;
        while (lakePq.size() > k) {
            Lake smallest = lakePq.poll();
            totalRemoved += smallest.getSize();
            fillLake(grid, smallest);
        }

        out.println(totalRemoved);
        for (char[] row : grid) {
            out.println(row);
        }
        out.flush();
    }

    /**
     * Iterative BFS to find all cells belonging to a lake.
     * Returns true if the lake touches the grid boundary.
     */
    private static boolean bfs(char[][] grid, int[][] lakeIds, int id, int startX, int startY, int n, int m, List<int[]> cells) {
        boolean touchesBoundary = false;
        Queue<int[]> queue = new ArrayDeque<>();
        queue.offer(new int[]{startX, startY});
        lakeIds[startX][startY] = id;
        cells.add(new int[]{startX, startY});

        while (!queue.isEmpty()) {
            int[] curr = queue.poll();
            int x = curr[0];
            int y = curr[1];

            if (x == 0 || x == n - 1 || y == 0 || y == m - 1) {
                touchesBoundary = true;
            }

            for (int d = 0; d < 4; d++) {
                int nx = x + DX[d];
                int ny = y + DY[d];
                if (nx >= 0 && nx < n && ny >= 0 && ny < m && grid[nx][ny] != '*' && lakeIds[nx][ny] == 0) {
                    lakeIds[nx][ny] = id;
                    cells.add(new int[]{nx, ny});
                    queue.offer(new int[]{nx, ny});
                }
            }
        }
        return touchesBoundary;
    }

    /**
     * Marks all cells of a lake as water ('*') in the grid.
     */
    private static void fillLake(char[][] grid, Lake lake) {
        for (int[] cell : lake.getCells()) {
            grid[cell[0]][cell[1]] = '*';
        }
    }

    /**
     * Immutable value object representing a lake.
     */
    static class Lake {
        private final int id;
        private final int size;
        private final List<int[]> cells;

        Lake(int id, int size, List<int[]> cells) {
            this.id = id;
            this.size = size;
            this.cells = cells;
        }

        int getId() { return id; }
        int getSize() { return size; }
        List<int[]> getCells() { return cells; }
    }

    /**
     * Fast I/O helper to handle large inputs efficiently.
     */
    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            String s = next();
