import java.io.*;
import java.util.*;

/**
 * Processes a character grid to retain exactly k largest connected components.
 * Excess components are removed (filled with '*'), and components touching the
 * grid border are always preserved.
 */
public class GridProcessor {
    private static final int[][] DIRECTIONS = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};

    public static void main(String[] args) {
        // Use try-with-resources for automatic and safe resource management
        try (FastScanner scanner = new FastScanner(System.in);
             PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out))) {
            new GridProcessor().process(scanner, out);
        } catch (IOException e) {
            System.err.println("I/O error occurred: " + e.getMessage());
        }
    }

    /**
     * Core processing logic: reads input, computes connected components,
     * removes excess components, and outputs results.
     */
    private void process(FastScanner in, PrintWriter out) throws IOException {
        int rows = in.nextInt();
        int cols = in.nextInt();
        int targetComponents = in.nextInt();

        char[][] grid = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            grid[i] = in.next().toCharArray();
        }

        DisjointSetUnion dsu = new DisjointSetUnion(rows * cols);

        // Build connected components using DSU
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                int currentId = i * cols + j;
                for (int[] dir : DIRECTIONS) {
                    int ni = i + dir[0];
                    int nj = j + dir[1];
                    if (ni >= 0 && ni < rows && nj >= 0 && nj < cols && grid[i][j] == grid[ni][nj]) {
                        dsu.union(currentId, ni * cols + nj);
                    }
                }
            }
        }

        // Identify components that touch the border (these must be preserved)
        Set<Integer> ignoredRoots = new HashSet<>();
        for (int i = 0; i < rows; i++) {
            ignoredRoots.add(dsu.find(i * cols));
            ignoredRoots.add(dsu.find(i * cols + cols - 1));
        }
        for (int j = 0; j < cols; j++) {
            ignoredRoots.add(dsu.find(j));
            ignoredRoots.add(dsu.find((rows - 1) * cols + j));
        }

        // Collect inner components into a min-heap sorted by size
        PriorityQueue<Integer> componentQueue = new PriorityQueue<>(
                (a, b) -> Integer.compare(dsu.getSize(a), dsu.getSize(b))
        );
        boolean[] visitedRoots = new boolean[rows * cols];

        for (int i = 1; i < rows - 1; i++) {
            for (int j = 1; j < cols - 1; j++) {
                if (grid[i][j] == '*') continue;
                int root = dsu.find(i * cols + j);
                if (visitedRoots[root]) continue;
                if (ignoredRoots.contains(root)) continue;

                visitedRoots[root] = true;
                componentQueue.add(root);
            }
        }

        // Remove smallest components until only targetComponents remain
        while (componentQueue.size() > targetComponents) {
            int root = componentQueue.poll();
            floodFill(grid, root, rows, cols);
        }

        // Count remaining valid cells
        int remainingCount = 0;
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] != '*') {
                    remainingCount++;
                }
            }
        }

        out.println(remainingCount);
        for (int i = 0; i < rows; i++) {
            out.println(new String(grid[i]));
        }
    }

    /**
     * Iteratively flood-fills a connected component starting from its root.
     * Replaces all cells in the component with '*'.
     * Uses an iterative approach to prevent StackOverflowError on large grids.
     */
    private void floodFill(char[][] grid, int root, int rows, int cols) {
        int startNode = root; // root is already a valid linear index
        if (grid[startNode / cols][startNode % cols] == '*') return;

        Deque<Integer> stack = new ArrayDeque<>();
        stack.push(startNode);
        grid[startNode / cols][startNode % cols] = '*';

        while (!stack.isEmpty()) {
            int curr = stack.pop();
            int r = curr / cols;
            int c = curr % cols;

            for (int[] dir : DIRECTIONS) {
                int nr = r + dir[0];
                int nc = c + dir[1];
                if (nr >= 0 && nr < rows && nc >= 0 && nc < cols && grid[nr][nc] != '*') {
                    grid[nr][nc] = '*';
                    stack.push(nr * cols + nc);
                }
            }
        }
    }

    /**
     * Disjoint Set Union (DSU) with path compression and union by size.
     * Optimized to use a single array where roots store negative component sizes.
     */
    private static class DisjointSetUnion {
        private final int[] parent;

        public DisjointSetUnion(int size) {
            parent = new int[size];
            Arrays.fill(parent, -1);
        }

        public int find(int v) {
            if (parent[v] < 0) return v;
            return parent[v] = find(parent[v]);
        }

        public boolean union(int a, int b) {
            int rootA = find(a);
            int rootB = find(b);
            if (rootA == rootB) return false;

            // Union by size: attach smaller tree to larger tree
            if (parent[rootB] < parent[rootA]) {
                int temp = rootA;
                rootA = rootB;
                rootB = temp;
            }
            parent[rootA] += parent[rootB];
            parent[rootB] = rootA;
            return true;
        }

        public int getSize(int v) {
            return -parent[find(v)];
        }
    }

    /**
     * Fast I/O helper for efficient input reading in competitive programming contexts.
     */
    private static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        public String next() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) return null;
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

        public int nextInt() throws IOException {
            String s = next();
            return s == null ? 0 : Integer.parseInt(s);
        }

        public void close() throws IOException {
            br.close();
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayDeque;
import java.util.PriorityQueue;
import java.util.StringTokenizer;

/**
 * Refactored version of ProblemD.
 * 
 * Improvements made:
 * 1. Encapsulation: Removed static fields and methods where possible to allow 
 *    instantiation and reuse.
 * 2. Stack Overflow Prevention: Replaced recursive DFS with iterative DFS using 
 *    ArrayDeque to handle large grids safely.
 * 3. Readability: Extracted logic into named methods (solve, init, floodFillBorder, etc.).
 * 4. Efficiency: Used StringBuilder for output and StringTokenizer for input parsing.
 * 5. Robustness: Added bounds checking helper and better input parsing.
 * 6. Code Quality: Used Integer.compare and standard Java conventions.
 */
public class ProblemD {

    // Instance variables to maintain state per problem instance
    private int n, m, k;
    private char[][] map;
    private boolean[][] visited;

    /**
     * Represents a lake found in the grid.
     */
    private static class Lake implements Comparable<Lake> {
        int r, c, area;

        public Lake(int r, int c, int area) {
            this.r = r;
            this.c = c;
            this.area = area;
        }

        @Override
        public int compareTo(Lake other) {
            // Sort lakes by area in ascending order
            return Integer.compare(this.area, other.area);
        }
    }

    public static void main(String[] args) {
        // Use try-with-resources to ensure BufferedReader is closed
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            ProblemD solver = new ProblemD();
            solver.init(br);
            solver.solve();
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    /**
     * Initializes the grid and reads input.
     */
    private void init(BufferedReader br) throws IOException {
        String line = br.readLine();
        if (line == null) return;

        StringTokenizer st = new StringTokenizer(line);
        n = Integer.parseInt(st.nextToken());
        m = Integer.parseInt(st.nextToken());
        k = Integer.parseInt(st.nextToken());

        map = new char[n][m];
        visited = new boolean[n][m];

        for (int i = 0; i < n; i++) {
            String row = br.readLine();
            if (row != null) {
                map[i] = row.trim().toCharArray();
            }
        }
    }

    /**
     * Core logic to solve the problem.
     */
    private void solve() {
        // 1. Identify and mark water connected to the borders (Ocean)
        // We iterate the perimeter. If a cell is water ('.'), we flood fill it 
        // to mark all connected water as visited.

        // Top and Bottom rows
        for (int j = 0; j < m; j++) {
            if (isValid(0, j) && map[0][j] == '.' && !visited[0][j]) {
                floodFillBorder(0, j);
            }
            if (isValid(n - 1, j) && map[n - 1][j] == '.' && !visited[n - 1][j]) {
                floodFillBorder(n - 1, j);
            }
        }
        // Left and Right columns
        for (int i = 0; i < n; i++) {
            if (isValid(i, 0) && map[i][0] == '.' && !visited[i][0]) {
                floodFillBorder(i, 0);
            }
            if (isValid(i, m - 1) && map[i][m - 1] == '.' && !visited[i][m - 1]) {
                floodFillBorder(i, m - 1);
            }
        }

        // 2. Find isolated lakes in the interior
        PriorityQueue<Lake> lakes = new PriorityQueue<>();
        for (int i = 1; i < n - 1; i++) {
            for (int j = 1; j < m - 1; j++) {
                if (map[i][j] == '.' && !visited[i][j]) {
                    int area = calculateArea(i, j);
                    lakes.add(new Lake(i, j, area));
                }
            }
        }

        // 3. Remove smallest lakes until the number of lakes equals k
        int totalRemovedArea = 0;
        while (lakes.size() > k) {
            Lake lake = lakes.poll();
            fillLake(lake.r, lake.c);
            totalRemovedArea += lake.area;
        }

        // 4. Output results
        System.out.println(totalRemovedArea);
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < n; i++) {
            sb.append(map[i]).append('\n');
        }
        System.out.print(sb);
    }

    /**
     * Iterative DFS to mark border-connected water as visited.
     */
    private void floodFillBorder(int r, int c) {
        ArrayDeque<int[]> stack = new ArrayDeque<>();
        stack.push(new int[]{r, c});
        visited[r][c] = true;

        while (!stack.isEmpty()) {
            int[] curr = stack.pop();
            int[] dr = {-1, 1, 0, 0};
            int[] dc = {0, 0, -1, 1};

            for (int i = 0; i < 4; i++) {
                int nr = curr[0] + dr[i];
                int nc = curr[1] + dc[i];

                if (isValid(nr, nc) && map[nr][nc] == '.' && !visited[nr][nc]) {
                    visited[nr][nc] = true;
                    stack.push(new int[]{nr, nc});
                }
            }
        }
    }

    /**
     * Iterative DFS to calculate area of a lake and mark visited.
     */
    private int calculateArea(int r, int c) {
        int area = 0;
        ArrayDeque<int[]> stack = new ArrayDeque<>();
        stack.push(new int[]{r, c});
        visited[r][c] = true; // Mark immediately to prevent re-processing

        while (!stack.isEmpty()) {
            int[] curr = stack.pop();
            area++;
            int[] dr = {-1, 1, 0, 0};
            int[] dc = {0, 0, -1, 1};

            for (int i = 0; i < 4; i++) {
                int nr = curr[0] + dr[i];
                int nc = curr[1] + dc[i];

                if (isValid(nr, nc) && map[nr][nc] == '.' && !visited[nr][nc]) {
                    visited[nr][nc] = true;
                    stack.push(new int[]{nr, nc});
                }
            }
        }
        return area;
    }

    /**
     * Iterative DFS to fill a specific lake with '*' (land).
     */
    private void fillLake(int r, int c) {
        ArrayDeque<int[]> stack = new ArrayDeque<>();
        stack.push(new int[]{r, c});
        map[r][c] = '*'; // Mark as filled immediately

        while (!stack.isEmpty()) {
            int[] curr = stack.pop();
            int[] dr = {-1, 1, 0, 0};
            int[] dc = {0, 0, -1, 1};

            for (int i = 0; i < 4; i++) {
                int nr = curr[0] + dr[i];
                int nc = curr[1] + dc[i];

                if (isValid(nr, nc) && map[nr][nc] == '.') {
                    map[nr][nc] = '*';
                    stack.push(new int[]{nr, nc});
                }
            }
        }
    }

    /**
     * Checks if coordinates are within grid bounds.
     */
    private boolean isValid(int r, int c) {
        return r >= 0 && r < n && c >= 0 && c < m;
    }
}

import java.io.BufferedReader;
import java.io.BufferedOutputStream;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.Queue;
import java.util.StringTokenizer;

/**
 * Refactored solution for grid lake analysis and filling.
 * 
 * Improvements:
 * 1. Separation of Concerns: Logic moved from main() into specific methods (solve, bfs).
 * 2. Data Structures: Used a Lake class to encapsulate properties (size, validity, cells)
 *    instead of parallel arrays.
 * 3. Performance: Stored coordinates of lake cells during BFS to avoid O(N*M) re-scanning
 *    during the filling phase.
 * 4. Readability: Used descriptive variable names and constants.
 * 5. Robustness: Improved input handling and error checking.
 */
public class LakeSolver {

    // Directions for moving up, down, left, right
    private static final int[][] DIRECTIONS = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};

    public static void main(String[] args) {
        // Initialize fast I/O
        FastScanner scanner = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out));

        try {
            solve(scanner, out);
        } finally {
            out.flush();
            out.close();
        }
    }

    private static void solve(FastScanner scanner, PrintWriter out) {
        // Read dimensions (R, C) and target count K
        String rStr = scanner.next();
        if (rStr == null) return; // End of input
        int rows = Integer.parseInt(rStr);
        int cols = scanner.nextInt();
        int k = scanner.nextInt();

        // Read the grid
        char[][] grid = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            String line = scanner.next();
            if (line != null) {
                // Ensure we handle the row correctly even if length varies slightly
                // though valid input is expected to match cols.
                if (line.length() >= cols) {
                    grid[i] = line.substring(0, cols).toCharArray();
                } else {
                    grid[i] = line.toCharArray();
                }
            } else {
                grid[i] = new char[cols]; // Fallback for missing lines
            }
        }

        // Identify lakes using BFS
        List<Lake> validLakes = new ArrayList<>();
        boolean[][] visited = new boolean[rows][cols];
        int lakeIdCounter = 1;

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                // If cell is empty ('.') and not visited, it's a new lake
                if (grid[r][c] == '.' && !visited[r][c]) {
                    Lake currentLake = bfs(grid, visited, r, c, rows, cols, lakeIdCounter++);
                    // If the lake is bounded (does not touch grid edges), it is valid
                    if (currentLake.isValid) {
                        validLakes.add(currentLake);
                    }
                }
            }
        }

        // Logic to fill lakes if there are more valid lakes than K
        int filledCount = 0;
        if (validLakes.size() > k) {
            // Sort valid lakes by size in ascending order
            validLakes.sort(Comparator.comparingInt(lake -> lake.size));

            int lakesToFill = validLakes.size() - k;
            // Fill the smallest lakes
            for (int i = 0; i < lakesToFill; i++) {
                Lake lakeToFill = validLakes.get(i);
                for (Point p : lakeToFill.cells) {
                    grid[p.r][p.c] = '*';
                    filledCount++;
                }
            }
        }

        // Output results
        out.println(filledCount);
        for (int r = 0; r < rows; r++) {
            out.println(new String(grid[r]));
        }
    }

    /**
     * Performs BFS to find all connected '.' cells starting from (startR, startC).
     * Determines if the lake is bounded (valid) and collects its cells.
     */
    private static Lake bfs(char[][] grid, boolean[][] visited, int startR, int startC, 
                            int rows, int cols, int id) {
        Lake lake = new Lake(id);
        Queue<Point> queue = new ArrayDeque<>();

        queue.add(new Point(startR, startC));
        visited[startR][startC] = true;
        lake.cells.add(new Point(startR, startC));
        lake.size++;

        while (!queue.isEmpty()) {
            Point current = queue.poll();

            for (int[] dir : DIRECTIONS) {
                int nr = current.r + dir[0];
                int nc = current.c + dir[1];

                // Check if neighbor is out of bounds
                if (nr < 0 || nc < 0 || nr >= rows || nc >= cols) {
                    // Touching the grid boundary makes the lake invalid (unbounded)
                    lake.isValid = false;
                    continue;
                }

                // If neighbor is an unvisited empty cell, add to lake
                if (!visited[nr][nc] && grid[nr][nc] == '.') {
                    visited[nr][nc] = true;
                    lake.cells.add(new Point(nr, nc));
                    lake.size++;
                    queue.add(new Point(nr, nc));
                }
            }
        }
        return lake;
    }

    // Helper class to represent a connected component of '.' cells
    private static class Lake {
        final int id;
        int size;
        boolean isValid; // True if the lake is strictly enclosed within the grid
        List<Point> cells;

        Lake(int id) {
            this.id = id;
            this.isValid = true; // Assume valid until proven otherwise (touching edge)
            this.cells = new ArrayList<>();
        }
    }

    // Helper class to store coordinates
    private static class Point {
        int r, c;

        Point(int r, int c) {
            this.r = r;
            this.c = c;
        }
    }

    // Fast Input Reader
    private static class FastScanner {
        BufferedReader br;
        StringTokenizer st;

        public FastScanner(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    e.printStackTrace();
                    return null;
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            String s = next();
            if (s == null) throw new RuntimeException("End of input");
            return Integer.parseInt(s);
        }
    }
}

import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        FastScanner in = new FastScanner(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        LakeSolver solver = new LakeSolver();
        solver.solve(1, in, out);
        out.close();
    }

    static class LakeSolver {
        public void solve(int testNumber, FastScanner in, PrintWriter out) {
            int rows = in.nextInt();
            int cols = in.nextInt();
            int lakesToRetain = in.nextInt();

            char[][] grid = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                String line = in.next();
                grid[i] = line.toCharArray();
            }

            boolean[][] visited = new boolean[rows][cols];
            List<Lake> lakes = new ArrayList<>();

            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j] == '.' && !visited[i][j] && !isOnBoundary(i, j, rows, cols)) {
                        Lake lake = findLake(grid, visited, i, j, rows, cols);
                        if (lake != null) {
                            lakes.add(lake);
                        }
                    }
                }
            }

            lakes.sort(Comparator.comparingInt(l -> l.size));

            int totalRemoved = 0;
            int lakesToRemove = lakes.size() - lakesToRetain;
            for (int i = 0; i < lakesToRemove; i++) {
                Lake lake = lakes.get(i);
                totalRemoved += lake.size;
                fillLake(grid, lake.row, lake.col, rows, cols);
            }

            out.println(totalRemoved);
            for (char[] row : grid) {
                out.println(new String(row));
            }
        }

        private boolean isOnBoundary(int r, int c, int rows, int cols) {
            return r == 0 || r == rows - 1 || c == 0 || c == cols - 1;
        }

        private Lake findLake(char[][] grid, boolean[][] visited, int startR, int startC, int rows, int cols) {
            int size = 0;
            boolean touchesBoundary = false;
            Point first = new Point(startR, startC);

            Deque<Point> stack = new ArrayDeque<>();
            stack.push(new Point(startR, startC));
            visited[startR][startC] = true;

            while (!stack.isEmpty()) {
                Point p = stack.pop();
                size++;

                if (isOnBoundary(p.r, p.c, rows, cols)) {
                    touchesBoundary = true;
                }

                for (Point neighbor : getNeighbors(p, rows, cols)) {
                    if (!visited[neighbor.r][neighbor.c] && grid[neighbor.r][neighbor.c] == '.') {
                        visited[neighbor.r][neighbor.c] = true;
                        stack.push(neighbor);
                    }
                }
            }

            return touchesBoundary ? null : new Lake(first.r, first.c, size);
        }

        private void fillLake(char[][] grid, int startR, int startC, int rows, int cols) {
            Deque<Point> stack = new ArrayDeque<>();
            stack.push(new Point(startR, startC));

            while (!stack.isEmpty()) {
                Point p = stack.pop();
                if (grid[p.r][p.c] == '.') {
                    grid[p.r][p.c] = '*';
                    for (Point neighbor : getNeighbors(p, rows, cols)) {
                        if (grid[neighbor.r][neighbor.c] == '.') {
                            stack.push(neighbor);
                        }
                    }
                }
            }
        }

        private List<Point> getNeighbors(Point p, int rows, int cols) {
            int[] dr = {-1, 1, 0, 0};
            int[] dc = {0, 0, -1, 1};
            List<Point> neighbors = new ArrayList<>(4);
            for (int k = 0; k < 4; k++) {
                int nr = p.r + dr[k];
                int nc = p.c + dc[k];
                if (nr >= 0 && nr < rows && nc >= 0 && nc < cols) {
                    neighbors.add(new Point(nr, nc));
                }
            }
            return neighbors;
        }

        static class Lake {
            final int row, col, size;

            Lake(int row, int col, int size) {
                this.row = row;
                this.col = col;
                this.size = size;
            }
        }

        static class Point {
            final int r, c;

            Point(int r, int c) {
                this.r = r;
                this.c = c;
            }
        }
    }

    static class FastScanner {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastScanner(InputStream stream) {
            this.reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            String s = next();
            if (s == null) throw new NoSuchElementException();
            return Integer.parseInt(s);
        }
    }
}

import java.io.BufferedReader;
