public class LakesInBerlandCodeforces {

    public static void main(String[] args) throws IOException {
        // Use BufferedReader and StringTokenizer for efficient and reliable input parsing
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());

        int rows = Integer.parseInt(st.nextToken());
        int cols = Integer.parseInt(st.nextToken());
        int maxLakes = Integer.parseInt(st.nextToken());

        char[][] grid = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            String line = br.readLine();
            // Skip potential empty lines between inputs
            while (line != null && line.trim().isEmpty()) {
                line = br.readLine();
            }
            if (line != null) {
                grid[i] = line.trim().toCharArray();
            }
        }

        // Group discovered lakes by their size. TreeMap keeps keys sorted in ascending order.
        Map<Integer, List<List<Point>>> lakeGroups = new TreeMap<>();
        int totalLakes = 0;

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '.') {
                    List<Point> lake = findLake(grid, r, c, rows, cols);
                    if (lake != null) {
                        totalLakes++;
                        int size = lake.size();
                        lakeGroups.computeIfAbsent(size, k -> new ArrayList<>()).add(lake);
                    }
                }
            }
        }

        // Create a result grid initialized as a deep copy of the original.
        // This preserves ocean-connected water ('.') while allowing us to fill lakes with '*'.
        char[][] resultGrid = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            resultGrid[i] = grid[i].clone();
        }

        // Remove the smallest lakes until exactly maxLakes remain
        int cellsToFill = 0;
        while (totalLakes > maxLakes && !lakeGroups.isEmpty()) {
            int smallestSize = lakeGroups.firstKey();
            List<List<Point>> smallestLakes = lakeGroups.get(smallestSize);

            while (!smallestLakes.isEmpty() && totalLakes > maxLakes) {
                List<Point> lake = smallestLakes.remove(0);
                cellsToFill += smallestSize;
                totalLakes--;

                // Mark removed lake cells in the result grid
                for (Point p : lake) {
                    resultGrid[p.x][p.y] = '*';
                }

                // Clean up empty groups to keep the map lean
                if (smallestLakes.isEmpty()) {
                    lakeGroups.pollFirstEntry();
                }
            }
        }

        // Build and print the output efficiently using StringBuilder
        StringBuilder sb = new StringBuilder();
        sb.append(cellsToFill).append('\n');
        for (char[] row : resultGrid) {
            sb.append(row).append('\n');
        }
        System.out.print(sb);
    }

    /**
     * Performs iterative DFS to find all cells belonging to a connected water component.
     * Marks visited cells in the grid to avoid reprocessing.
     * Returns null if the component touches the ocean (border), otherwise returns the list of points.
     */
    private static List<Point> findLake(char[][] grid, int startRow, int startCol, int rows, int cols) {
        List<Point> lakePoints = new ArrayList<>();
        Deque<Point> stack = new ArrayDeque<>();
        stack.push(new Point(startRow, startCol));
        grid[startRow][startCol] = '*'; // Mark as visited
        lakePoints.add(new Point(startRow, startCol));

        boolean connectedToOcean = isOnBorder(startRow, startCol, rows, cols);

        int[] dr = {-1, 0, 1, 0};
        int[] dc = {0, 1, 0, -1};

        while (!stack.isEmpty()) {
            Point current = stack.pop();

            if (isOnBorder(current.x, current.y, rows, cols)) {
                connectedToOcean = true;
            }

            for (int i = 0; i < 4; i++) {
                int nr = current.x + dr[i];
                int nc = current.y + dc[i];

                if (isValid(nr, nc, rows, cols) && grid[nr][nc] == '.') {
                    grid[nr][nc] = '*'; // Mark as visited
                    Point next = new Point(nr, nc);
                    stack.push(next);
                    lakePoints.add(next);
                }
            }
        }

        return connectedToOcean ? null : lakePoints;
    }

    private static boolean isValid(int r, int c, int rows, int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    private static boolean isOnBorder(int r, int c, int rows, int cols) {
        return r == 0 || r == rows - 1 || c == 0 || c == cols - 1;
    }

    /**
     * Simple immutable data class to represent a grid coordinate.
     */
    private static class Point {
        final int x;
        final int y;

        Point(int x, int y) {
            this.x = x;
            this.y = y;
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayList;
import java.util.ArrayDeque;
import java.util.Comparator;
import java.util.Deque;
import java.util.List;
import java.util.StringTokenizer;

public class Task2 {

    /**
     * Immutable record to hold connected component metadata.
     * Replaces the original 'Pop' class and global state.
     */
    private record Component(int size, boolean touchesBorder, List<int[]> cells) {}

    private final int rows;
    private final int cols;
    private final int k;
    private final char[][] grid;
    private final int[] dr = {-1, 1, 0, 0};
    private final int[] dc = {0, 0, -1, 1};

    /**
     * Constructs the solver with grid dimensions, target count k, and the initial grid.
     */
    public Task2(int rows, int cols, int k, char[][] grid) {
        this.rows = rows;
        this.cols = cols;
        this.k = k;
        this.grid = grid;
    }

    /**
     * Executes the core algorithm: identifies components, filters, sorts, removes, and outputs.
     */
    public void solve() throws IOException {
        boolean[][] visited = new boolean[rows][cols];
        List<Component> components = new ArrayList<>();

        // 1. Identify all connected components of '.'
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '.' && !visited[r][c]) {
                    List<int[]> cells = new ArrayList<>();
                    Component component = floodFill(r, c, visited, cells);
                    // Only keep components that do NOT touch the border
                    if (!component.touchesBorder()) {
                        components.add(component);
                    }
                }
            }
        }

        // 2. Sort components by size in ascending order
        components.sort(Comparator.comparingInt(Component::size));

        // 3. Determine how many smallest components to remove
        int componentsToRemove = Math.max(0, components.size() - k);
        int totalRemovedArea = 0;

        // 4. Mark removed components as '*' and accumulate their area
        for (int i = 0; i < componentsToRemove; i++) {
            Component component = components.get(i);
            totalRemovedArea += component.size();
            for (int[] cell : component.cells()) {
                grid[cell[0]][cell[1]] = '*';
            }
        }

        // 5. Output results
        System.out.println(totalRemovedArea);
        printGrid();
    }

    /**
     * Iterative DFS flood fill to prevent StackOverflowError on large grids.
     * Tracks size, border contact, and stores coordinates for later mutation.
     */
    private Component floodFill(int startR, int startC, boolean[][] visited, List<int[]> cells) {
        Deque<int[]> stack = new ArrayDeque<>();
        stack.push(new int[]{startR, startC});
        visited[startR][startC] = true;
        cells.add(new int[]{startR, startC});

        int size = 0;
        boolean touchesBorder = false;

        while (!stack.isEmpty()) {
            int[] current = stack.pop();
            size++;
            int r = current[0];
            int c = current[1];

            // Check if current cell is on the grid boundary
            if (r == 0 || r == rows - 1 || c == 0 || c == cols - 1) {
                touchesBorder = true;
            }

            // Explore 4-directional neighbors
            for (int i = 0; i < 4; i++) {
                int nr = r + dr[i];
                int nc = c + dc[i];

                if (nr >= 0 && nr < rows && nc >= 0 && nc < cols &&
                    grid[nr][nc] == '.' && !visited[nr][nc]) {
                    visited[nr][nc] = true;
                    stack.push(new int[]{nr, nc});
                    cells.add(new int[]{nr, nc});
                }
            }
        }

        return new Component(size, touchesBorder, cells);
    }

    /**
     * Efficiently prints the final grid state.
     */
    private void printGrid() {
        StringBuilder sb = new StringBuilder();
        for (char[] row : grid) {
            sb.append(row).append('\n');
        }
        System.out.print(sb);
    }

    public static void main(String[] args) throws IOException {
        // Fast I/O replacement for Scanner
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line = br.readLine();
        if (line == null) return;

        StringTokenizer st = new StringTokenizer(line);
        int n = Integer.parseInt(st.nextToken());
        int m = Integer.parseInt(st.nextToken());
        int k = Integer.parseInt(st.nextToken());

        char[][] grid = new char[n][];
        for (int i = 0; i < n; i++) {
            grid[i] = br.readLine().trim().toCharArray();
        }

        Task2 solver = new Task2(n, m, k, grid);
        solver.solve();
    }
}

import java.io.*;
import java.util.*;

/**
 * Refactored solution for grid-based lake identification and removal.
 * 
 * Key Improvements:
 * 1. Replaced recursive flood-fill with iterative BFS to prevent StackOverflowError on large grids.
 * 2. Eliminated magic numbers (-1, -2, 0) by using a clear boolean grid state and explicit constants.
 * 3. Fixed a logical bug in the original border-marking logic where 'cnt' was inconsistently incremented.
 * 4. Improved input parsing using BufferedReader and StringTokenizer for performance and robustness.
 * 5. Extracted the Lake data structure and made it static to reduce memory overhead.
 * 6. Applied modern Java features (Comparator, try-with-resources, enhanced loops) for readability.
 */
public class Main {
    public static void main(String[] args) {
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
             PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out))) {

            StringTokenizer st = new StringTokenizer(br.readLine());
            int n = Integer.parseInt(st.nextToken());
            int m = Integer.parseInt(st.nextToken());
            int k = Integer.parseInt(st.nextToken());

            boolean[][] isObstacle = new boolean[n][m];
            for (int i = 0; i < n; i++) {
                String line = br.readLine();
                // Skip potential empty lines caused by trailing newlines
                while (line != null && line.trim().isEmpty()) {
                    line = br.readLine();
                }
                if (line == null) break;
                line = line.trim();
                for (int j = 0; j < m && j < line.length(); j++) {
                    isObstacle[i][j] = line.charAt(j) == '*';
                }
            }

            new Solver().solve(n, m, k, isObstacle, out);
            out.flush();

        } catch (IOException e) {
            System.err.println("I/O error occurred: " + e.getMessage());
        }
    }

    static class Solver {
        private static final int[] DR = {-1, 1, 0, 0};
        private static final int[] DC = {0, 0, -1, 1};

        public void solve(int n, int m, int k, boolean[][] isObstacle, PrintWriter out) {
            boolean[][] visited = new boolean[n][m];
            List<Lake> lakes = new ArrayList<>();
            int lakeIdCounter = 0;

            // Identify connected components (lakes)
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    if (!isObstacle[i][j] && !visited[i][j]) {
                        List<int[]> cells = new ArrayList<>();
                        boolean touchesBorder = false;

                        // Iterative BFS to avoid recursion depth limits
                        Queue<int[]> queue = new ArrayDeque<>();
                        queue.offer(new int[]{i, j});
                        visited[i][j] = true;

                        while (!queue.isEmpty()) {
                            int[] curr = queue.poll();
                            cells.add(curr);

                            // Check if this component touches the grid boundary
                            if (curr[0] == 0 || curr[0] == n - 1 || curr[1] == 0 || curr[1] == m - 1) {
                                touchesBorder = true;
                            }

                            // Explore 4-directional neighbors
                            for (int d = 0; d < 4; d++) {
                                int ni = curr[0] + DR[d];
                                int nj = curr[1] + DC[d];
                                if (ni >= 0 && ni < n && nj >= 0 && nj < m && 
                                    !isObstacle[ni][nj] && !visited[ni][nj]) {
                                    visited[ni][nj] = true;
                                    queue.offer(new int[]{ni, nj});
                                }
                            }
                        }

                        // Only consider lakes that do not touch the border
                        if (!touchesBorder) {
                            lakeIdCounter++;
                            lakes.add(new Lake(lakeIdCounter, cells.size(), cells));
                        }
                    }
                }
            }

            int cellsToRemove = 0;
            int lakesToKeep = Math.min(k, lakes.size());

            // Sort lakes by size in ascending order
            lakes.sort(Comparator.comparingInt(l -> l.size));

            // Remove the smallest lakes until only k remain
            for (int i = 0; i < lakes.size() - lakesToKeep; i++) {
                Lake lake = lakes.get(i);
                cellsToRemove += lake.size;
                for (int[] cell : lake.cells) {
                    isObstacle[cell[0]][cell[1]] = true; // Convert removed lake cells to obstacles
                }
            }

            // Output results
            out.println(cellsToRemove);
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    out.print(isObstacle[i][j] ? '*' : '.');
                }
                out.println();
            }
        }
    }

    /**
     * Represents a connected body of water (lake) within the grid.
     */
    static class Lake {
        final int id;
        final int size;
        final List<int[]> cells;

        Lake(int id, int size, List<int[]> cells) {
            this.id = id;
            this.size = size;
            this.cells = cells;
        }
    }
}

import java.io.*;
import java.util.*;

public class Main {
    // Direction vectors for moving up, down, left, right
    private static final int[] DR = {-1, 1, 0, 0};
    private static final int[] DC = {0, 0, -1, 1};

    public static void main(String[] args) {
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
             PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out))) {

            FastScanner scanner = new FastScanner(br);
            int rows = scanner.nextInt();
            int cols = scanner.nextInt();
            int k = scanner.nextInt();

            char[][] grid = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                grid[i] = scanner.next().toCharArray();
            }

            boolean[][] visited = new boolean[rows][cols];
            List<Component> components = new ArrayList<>();

            // 1. Mark all components connected to the border as visited
            markBorderConnected(grid, visited, rows, cols);

            // 2. Identify all interior components (not connected to border)
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] != '*' && !visited[r][c]) {
                        int size = dfs(grid, visited, r, c, rows, cols);
                        components.add(new Component(size, r, c));
                    }
                }
            }

            // 3. Sort components by size in descending order
            components.sort(Comparator.comparingInt(Component::getSize).reversed());

            // 4. Process components starting from index k (the smallest ones)
            int totalSize = 0;
            for (int i = k; i < components.size(); i++) {
                Component comp = components.get(i);
                totalSize += comp.getSize();
                floodFill(grid, comp.getRow(), comp.getCol(), rows, cols);
            }

            // 5. Output results
            out.println(totalSize);
            for (int i = 0; i < rows; i++) {
                out.println(grid[i]);
            }
            out.flush();

        } catch (IOException e) {
            throw new RuntimeException("Input/Output error", e);
        }
    }

    /**
     * Marks all cells belonging to components that touch the grid border.
     */
    private static void markBorderConnected(char[][] grid, boolean[][] visited, int rows, int cols) {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                // Only process border cells as per original logic
                if (r > 0 && r < rows - 1 && c > 0 && c < cols - 1) continue;
                if (grid[r][c] == '*') continue;
                dfs(grid, visited, r, c, rows, cols);
            }
        }
    }

    /**
     * Performs DFS to mark a component as visited and returns its total cell count.
     */
    private static int dfs(char[][] grid, boolean[][] visited, int r, int c, int rows, int cols) {
        visited[r][c] = true;
        int size = 1;
        for (int i = 0; i < 4; i++) {
            int nr = r + DR[i];
            int nc = c + DC[i];
            if (isValid(grid, visited, nr, nc, rows, cols)) {
                size += dfs(grid, visited, nr, nc, rows, cols);
            }
        }
        return size;
    }

    /**
     * Checks if a cell is within bounds, not a wall, and not yet visited.
     */
    private static boolean isValid(char[][] grid, boolean[][] visited, int r, int c, int rows, int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols 
            && grid[r][c] != '*' 
            && !visited[r][c];
    }

    /**
     * Flood fills a component, marking all connected '.' cells as '*' (walls).
     */
    private static void floodFill(char[][] grid, int r, int c, int rows, int cols) {
        grid[r][c] = '*';
        for (int i = 0; i < 4; i++) {
            int nr = r + DR[i];
            int nc = c + DC[i];
            if (isValidForFlood(grid, nr, nc, rows, cols)) {
                floodFill(grid, nr, nc, rows, cols);
            }
        }
    }

    /**
     * Checks if a cell is within bounds and is a traversable '.' cell.
     */
    private static boolean isValidForFlood(char[][] grid, int r, int c, int rows, int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols && grid[r][c] == '.';
    }

    /**
     * Represents a connected component of '.' cells with its size and top-left starting position.
     */
    private static class Component {
        private final int size;
        private final int row;
        private final int col;

        Component(int size, int row, int col) {
            this.size = size;
            this.row = row;
            this.col = col;
        }

        int getSize() { return size; }
        int getRow() { return row; }
        int getCol() { return col; }
    }

    /**
     * Lightweight fast scanner for competitive programming / algorithmic inputs.
     */
    private static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner(BufferedReader br) {
            this.br = br;
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.Deque;
import java.util.List;

/**
 * Refactored solution for the lake drainage problem.
 * 
 * Key Improvements:
 * 1. Encapsulation: State is managed within an instance rather than static fields.
 * 2. Naming: Class and variables follow Java naming conventions (PascalCase/CamelCase).
 * 3. Data Structures: Replaced legacy 'Stack' with 'ArrayDeque' for better performance.
 * 4. Generics: Eliminated raw types in Collections.
 * 5. Modularity: Logic is split into readable methods (findLakes, drainLakes, etc.).
 * 6. Dependencies: Removed 'java.awt.Point' dependency using a lightweight inner class.
 * 7. Robustness: Added input trimming and validation.
 */
public class LakeDrainageSolver {

    private int rows;
    private int cols;
    private char[][] grid;
    private boolean[][] visited;
    private List<List<Point>> lakes;

    /**
     * Lightweight Point class to represent coordinates.
     */
    private static class Point {
        final int x;
        final int y;

        Point(int x, int y) {
            this.x = x;
            this.y = y;
        }
    }

    public static void main(String[] args) throws IOException {
        // Encapsulated logic in an instance for better state management
        LakeDrainageSolver solver = new LakeDrainageSolver();
        solver.solve();
    }

    public void solve() throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));

        // Read dimensions and k
        String line = br.readLine();
        if (line == null) return;

        // Trim to handle potential leading whitespace safely
        String[] parts = line.trim().split("\\s+");
        if (parts.length < 3) return;

        this.rows = Integer.parseInt(parts[0]);
        this.cols = Integer.parseInt(parts[1]);
        int k = Integer.parseInt(parts[2]);

        this.grid = new char[rows][cols];
        this.visited = new boolean[rows][cols];
        this.lakes = new ArrayList<>();

        // Read grid data
        for (int i = 0; i < rows; i++) {
            line = br.readLine();
            if (line != null) {
                this.grid[i] = line.toCharArray();
            }
        }

        // Identify all enclosed lakes
        findLakes();

        // Sort lakes by size in ascending order
        lakes.sort(Comparator.comparingInt(List::size));

        // Drain the smallest lakes
        int count = drainLakes(k);

        // Output results
        System.out.println(count);
        for (int i = 0; i < rows; i++) {
            System.out.println(new String(grid[i]));
        }
    }

    /**
     * Iterates through the grid to find connected components of '.' (lakes).
     * Filters out lakes that touch the border.
     */
    private void findLakes() {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                // Check if current cell is water and not yet visited
                if (grid[i][j] == '.' && !visited[i][j]) {
                    List<Point> currentLake = new ArrayList<>();
                    Deque<Point> stack = new ArrayDeque<>();

                    // Start DFS
                    visited[i][j] = true; // Mark visited immediately to avoid duplicates in stack
                    stack.push(new Point(i, j));

                    dfs(stack, currentLake);

                    // Only add to list if it doesn't touch the border
                    if (!touchesBorder(currentLake)) {
                        lakes.add(currentLake);
                    }
                }
            }
        }
    }

    /**
     * Performs iterative Depth First Search to find all connected water cells.
     */
    private void dfs(Deque<Point> stack, List<Point> currentLake) {
        while (!stack.isEmpty()) {
            Point current = stack.pop();
            currentLake.add(current);

            // Check all 4 directions
            // Up
            if (current.x > 0 && grid[current.x - 1][current.y] == '.' && !visited[current.x - 1][current.y]) {
                visited[current.x - 1][current.y] = true;
                stack.push(new Point(current.x - 1, current.y));
            }
            // Down
            if (current.x < rows - 1 && grid[current.x + 1][current.y] == '.' && !visited[current.x + 1][current.y]) {
                visited[current.x + 1][current.y] = true;
                stack.push(new Point(current.x + 1, current.y));
            }
            // Left
            if (current.y > 0 && grid[current.x][current.y - 1] == '.' && !visited[current.x][current.y - 1]) {
                visited[current.x][current.y - 1] = true;
                stack.push(new Point(current.x, current.y - 1));
            }
            // Right
            if (current.y < cols - 1 && grid[current.x][current.y + 1] == '.' && !visited[current.x][current.y + 1]) {
                visited[current.x][current.y + 1] = true;
                stack.push(new Point(current.x, current.y + 1));
            }
        }
    }

    /**
     * Checks if any point in the lake touches the grid boundary.
     */
    private boolean touchesBorder(List<Point> lake) {
        for (Point p : lake) {
            if (p.x == 0 || p.x == rows - 1 || p.y == 0 || p.y == cols - 1) {
                return true;
            }
        }
        return false;
    }

    /**
     * Drains the smallest lakes until only k lakes remain (or fewer if total lakes < k).
     * Returns the total number of cells drained.
     */
    private int drainLakes(int k) {
        int drainedCount = 0;

        // Calculate how many lakes to drain
        int lakesToDrain = lakes.size() - k;
        if (lakesToDrain < 0) {
            lakesToDrain = 0;
        }

        for (int i = 0; i < lakesToDrain; i++) {
            List<Point> lake = lakes.get(i);
            for (Point p : lake) {
                grid[p.x][p.y] = '*';
                drainedCount++;
            }
        }
        return drainedCount;
    }
}

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Scanner;
import java.util.Stack;

public class LakesInBerland {

    // Grid state
    private static char[][] grid;
    private static boolean[][] visited;
    private static int rows, cols, k;

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        // Read dimensions and target number of lakes to keep
        if (!scanner.hasNextInt()) return;
        rows = scanner.nextInt();
        cols = scanner.nextInt();
        k = scanner.nextInt();

        // Consume the newline character left after nextInt()
        scanner.nextLine();

        grid = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            String line = scanner.nextLine();
            grid[i] = line.toCharArray();
        }

        // 1. Find all lakes (connected components of '.')
        List<Lake> lakes = findLakes();

        // 2. Sort lakes by size (ascending order)
        Collections.sort(lakes);

        // 3. Fill the smallest lakes until only k remain
        int filledArea = 0;
        int lakesToFill = lakes.size() - k;

        for (int i = 0; i < lakesToFill; i++) {
            Lake lake = lakes.get(i);
            // Fill the lake and accumulate the area
            filledArea += fillLake(lake.row, lake.col);
        }

        // 4. Output results
        System.out.println(filledArea);
        printGrid();

        scanner.close();
    }

    /**
     * Traverses the grid to find all connected components (lakes).
     * Uses an iterative DFS approach to prevent StackOverflowError.
     */
    private static List<Lake> findLakes() {
        List<Lake> lakes = new ArrayList<>();
        visited = new boolean[rows][cols];

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                // If we find an unvisited water cell, it's a new lake
                if (grid[r][c] == '.' && !visited[r][c]) {
                    int size = calculateLakeSize(r, c);
                    if (size > 0) {
                        lakes.add(new Lake(size, r, c));
                    }
                }
            }
        }
        return lakes;
    }

    /**
     * Calculates the size of a lake starting from (startRow, startCol)
     * using iterative DFS.
     */
    private static int calculateLakeSize(int startRow, int startCol) {
        int size = 0;
        Stack<int[]> stack = new Stack<>();

        stack.push(new int[]{startRow, startCol});
        visited[startRow][startCol] = true;
        size++;

        while (!stack.isEmpty()) {
            int[] current = stack.pop();
            int r = current[0];
            int c = current[1];

            // Check all 4 directions
            int[] dr = {-1, 1, 0, 0};
            int[] dc = {0, 0, -1, 1};

            for (int i = 0; i < 4; i++) {
                int nr = r + dr[i];
                int nc = c + dc[i];

                // Check bounds explicitly
                if (nr >= 0 && nr < rows && nc >= 0 && nc < cols) {
                    // Check if it's water and not visited
                    if (grid[nr][nc] == '.' && !visited[nr][nc]) {
                        visited[nr][nc] = true;
                        size++;
                        stack.push(new int[]{nr, nc});
                    }
                }
            }
        }
        return size;
    }

    /**
     * Fills a lake starting from (startRow, startCol) with '*' and returns the area filled.
     * Uses iterative DFS. Modifies the grid directly to mark visited cells.
     */
    private static int fillLake(int startRow, int startCol) {
        int area = 0;
        Stack<int[]> stack = new Stack<>();

        stack.push(new int[]{startRow, startCol});
        // Mark as filled immediately
        grid[startRow][startCol] = '*';
        area++;

        while (!stack.isEmpty()) {
            int[] current = stack.pop();
            int r = current[0];
            int c = current[1];

            int[] dr = {-1, 1, 0, 0};
            int[] dc = {0, 0, -1, 1};

            for (int i = 0; i < 4; i++) {
                int nr = r + dr[i];
                int nc = c + dc[i];

                if (nr >= 0 && nr < rows && nc >= 0 && nc < cols) {
                    if (grid[nr][nc] == '.') {
                        grid[nr][nc] = '*';
                        area++;
                        stack.push(new int[]{nr, nc});
                    }
                }
            }
        }
        return area;
    }

    private static void printGrid() {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < rows; i++) {
            sb.append(grid[i]);
            sb.append("\n");
        }
        System.out.print(sb.toString());
    }

    /**
     * Represents a lake with its size and a reference coordinate.
     */
    static class Lake implements Comparable<Lake> {
        int size;
        int row, col;

        public Lake(int size, int row, int col) {
            this.size = size;
            this.row = row;
            this.col = col;
        }

        @Override
        public int compareTo(Lake other) {
            // Sort by size ascending
            return Integer.compare(this.size, other.size);
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.ArrayDeque;
import java.util.Deque;
import java.util.PriorityQueue;
import java.util.StringTokenizer;

/**
 * Refactored Lake Solver.
 * 
 * Improvements:
 * 1. Encapsulation: Moved global static variables into instance fields and helper classes.
 * 2. Naming: Renamed class to 'LakeSolver' and variables for clarity.
 * 3. Robustness: Replaced recursive 'fill' with iterative DFS to prevent StackOverflowError.
 * 4. Logic: Simplified boundary checking logic in DFS.
 * 5. IO: Proper resource management for BufferedReader and PrintWriter.
 * 6. Structure: Separated concerns into 'solve', 'dfs', and 'fill' methods.
 */
public class LakeSolver {

    private int rows;
    private int cols;
    private char[][] grid;
    private boolean[][] visited;

    // Directions: Up, Right, Down, Left
    private static final int[] DR = {-1, 0, 1, 0};
    private static final int[] DC = {0, 1, 0, -1};

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter pw = new PrintWriter(System.out);

        try {
            LakeSolver solver = new LakeSolver();
            solver.solve(br, pw);
        } finally {
            pw.flush();
            pw.close();
            br.close();
        }
    }

    private void solve(BufferedReader br, PrintWriter pw) throws IOException {
        String line = br.readLine();
        if (line == null) return;

        StringTokenizer st = new StringTokenizer(line);
        if (!st.hasMoreTokens()) return;

        rows = Integer.parseInt(st.nextToken());
        cols = Integer.parseInt(st.nextToken());
        int t = Integer.parseInt(st.nextToken());

        grid = new char[rows][cols];
        visited = new boolean[rows][cols];

        for (int i = 0; i < rows; i++) {
            line = br.readLine();
            if (line != null) {
                int len = Math.min(line.length(), cols);
                for (int j = 0; j < len; j++) {
                    grid[i][j] = line.charAt(j);
                }
            }
        }

        PriorityQueue<State> pq = new PriorityQueue<>();
        int lakesCount = 0;

        // Identify all lakes (enclosed components of '.')
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == '.' && !visited[i][j]) {
                    ComponentResult result = dfs(i, j);
                    // A lake is a component that does not touch the grid boundary
                    if (!result.touchesBoundary) {
                        pq.add(new State(i, j, result.size));
                        lakesCount++;
                    }
                }
            }
        }

        int cellsFilled = 0;
        // Fill smallest lakes until only 't' lakes remain
        while (lakesCount > t) {
            if (pq.isEmpty()) break;
            State state = pq.poll();
            fill(state.x, state.y);
            cellsFilled += state.n; 
            lakesCount--;
        }

        pw.println(cellsFilled);
        for (int i = 0; i < rows; i++) {
            pw.println(new String(grid[i]));
        }
    }

    /**
     * DFS to find component size and check if it touches the boundary.
     */
    private ComponentResult dfs(int r, int c) {
        visited[r][c] = true;
        int size = 1;
        // Check if current cell is on the boundary of the grid
        boolean touchesBoundary = (r == 0 || r == rows - 1 || c == 0 || c == cols - 1);

        for (int k = 0; k < 4; k++) {
            int nr = r + DR[k];
            int nc = c + DC[k];

            // Check bounds
            if (nr < 0 || nr >= rows || nc < 0 || nc >= cols) {
                // This implies the current cell is on the boundary.
                // The logic (r == 0...) already handles this, but strictly speaking,
                // stepping out of bounds confirms boundary contact.
                continue;
            }

            if (grid[nr][nc] == '.' && !visited[nr][nc]) {
                ComponentResult neighborResult = dfs(nr, nc);
                size += neighborResult.size;
                if (neighborResult.touchesBoundary) {
                    touchesBoundary = true;
                }
            }
        }
        return new ComponentResult(size, touchesBoundary);
    }

    /**
     * Iterative DFS to flood fill a component with '*'.
     * Using iteration prevents StackOverflowError on large grids.
     */
    private int fill(int r, int c) {
        Deque<int[]> stack = new ArrayDeque<>();
        stack.push(new int[]{r, c});

        // Mark start as visited/filled immediately to avoid duplicates in stack
        grid[r][c] = '*';
        int count = 1;

        while (!stack.isEmpty()) {
            int[] curr = stack.pop();
            int cr = curr[0];
            int cc = curr[1];

            for (int k = 0; k < 4; k++) {
                int nr = cr + DR[k];
                int nc = cc + DC[k];

                if (nr >= 0 && nr < rows && nc >= 0 && nc < cols && grid[nr][nc] == '.') {
                    grid[nr][nc] = '*'; // Mark immediately
                    count++;
                    stack.push(new int[]{nr, nc});
                }
            }
        }
        return count;
    }

    /**
     * Helper class to store DFS result.
     */
    private static class ComponentResult {
        int size;
        boolean touchesBoundary;

        ComponentResult(int size, boolean touchesBoundary) {
            this.size = size;
            this.touchesBoundary = touchesBoundary;
        }
    }

    /**
     * State class for PriorityQueue.
     */
    private static class State implements Comparable<State> {
        int x, y, n;

        State(int x, int y, int n) {
            this.x = x;
            this.y = y;
            this.n = n;
        }

        @Override
        public int compareTo(State other) {
            // Sort by size ascending
            if (this.n != other.n) {
                return Integer.compare(this.n, other.n);
            }
            // Then by row ascending
            if (this.x != other.x) {
                return Integer.compare(this.x, other.x);
            }
            // Then by col ascending
            return Integer.compare(this.y, other.y);
        }
    }
}

import java.io.*;
import java.util.*;

public class Main {
    // Instance fields eliminate problematic static state, enabling testability and reuse
    private int n, m, k;
    private char[][] grid;
    private boolean[][] visited;
    private List<List<Point>> componentCells;
    private Set<Integer> borderComponents;
    private int componentCount;
    private PrintWriter out;

    private static final int[] DR = {-1, 0, 1, 0};
    private static final int[] DC = {0, 1, 0, -1};

    private static class Point {
        final int r, c;
        Point(int r, int c) { this.r = r; this.c = c; }
    }

    private static class Component implements Comparable<Component> {
        final int id;
        final int size;

        Component(int id, int size) {
            this.id = id;
            this.size = size;
        }

        @Override
        public int compareTo(Component other) {
            // Ascending order by size (preserves original algorithmic intent)
            return Integer.compare(this.size, other.size);
        }

        @Override
        public boolean equals(Object o) {
            if (this == o) return true;
            if (!(o instanceof Component)) return false;
            Component comp = (Component) o;
            return id == comp.id;
        }

        @Override
        public int hashCode() {
            return Objects.hash(id);
        }
    }

    public static void main(String[] args) {
        // Increase stack size to prevent StackOverflowError during deep DFS
        new Thread(null, () -> {
            try {
                new Main().solve();
            } catch (Exception e) {
                e.printStackTrace();
            }
        }, "solver", 1 << 26).start();
    }

    public void solve() throws IOException {
        FastScanner sc = new FastScanner();
        n = sc.nextInt();
        m = sc.nextInt();
        k = sc.nextInt();

        grid = new char[n][m];
        for (int i = 0; i < n; i++) {
            grid[i] = sc.next().toCharArray();
        }

        componentCells = new ArrayList<>();
        visited = new boolean[n][m];
        borderComponents = new HashSet<>();
        componentCount = 0;

        // Identify connected components and store their cells during traversal
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == '.' && !visited[i][j]) {
                    componentCells.add(new ArrayList<>());
                    dfs(i, j, componentCount);
                    componentCount++;
                }
            }
        }

        // Priority queue to process components by size (ascending)
        PriorityQueue<Component> pq = new PriorityQueue<>();
        for (int i = 0; i < componentCount; i++) {
            pq.add(new Component(i, componentCells.get(i).size()));
        }

        // Calculate how many non-border components to remove
        int maxRemovals = Math.max(0, componentCount - borderComponents.size() - k);
        int removed = 0;
        int ans = 0;

        while (removed < maxRemovals && !pq.isEmpty()) {
            Component comp = pq.poll();
            if (borderComponents.contains(comp.id)) continue;

            List<Point> cells = componentCells.get(comp.id);
            for (Point p : cells) {
                grid[p.r][p.c] = '*';
            }
            ans += cells.size();
            removed++;
        }

        out = new PrintWriter(new BufferedOutputStream(System.out));
        out.println(ans);
        for (int i = 0; i < n; i++) {
            out.println(new String(grid[i]));
        }
        out.flush();
    }

    private void dfs(int r, int c, int id) {
        visited[r][c] = true;
        componentCells.get(id).add(new Point(r, c));
        if (r == 0 || r == n - 1 || c == 0 || c == m - 1) {
            borderComponents.add(id);
        }
        for (int i = 0; i < 4; i++) {
            int nr = r + DR[i];
            int nc = c + DC[i];
            if (isValid(nr, nc)) {
                dfs(nr, nc, id);
            }
        }
    }

    private boolean isValid(int r, int c) {
        return r >= 0 && r < n && c >= 0 && c < m && !visited[r][c] && grid[r][c] == '.';
    }

    private static class FastScanner {
        BufferedReader br;
        StringTokenizer st;

        public FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) throw new IOException("End of input");
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        long nextLong() {
            return Long.parseLong(next());
        }

        double nextDouble() {
            return Double.parseDouble(next());
        }
    }
}

import java.util.*;

/**
 * Solves the Berland Lakes problem by identifying lakes, 
 * removing the smallest ones to meet a target count, and 
 * converting them to land.
 */
public class BerlandLakes {

    private final int rows;
    private final int cols;
    private final int targetLakes;
    private char[][] grid;
    private boolean[][] visited;
    private static final int[] DX = {0, 0, 1, -1};
    private static final int[] DY = {1, -1, 0, 0};

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        if (!scanner.hasNextInt()) return;

        BerlandLakes solver = new BerlandLakes(
            scanner.nextInt(),
            scanner.nextInt(),
            scanner.nextInt()
        );
        solver.readInput(scanner);
        solver.process();
        scanner.close();
    }

    public BerlandLakes(int rows, int cols, int targetLakes) {
        this.rows = rows;
        this.cols = cols;
        this.targetLakes = targetLakes;
        // Use 1-based indexing with padding to simplify boundary checks
        this.grid = new char[rows + 2][cols + 2];
        this.visited = new boolean[rows + 2][cols + 2];
        initializePadding();
    }

    private void initializePadding() {
        for (int i = 0; i <= rows + 1; i++) {
            grid[i][0] = '*';
        }
        for (int j = 0; j <= cols + 1; j++) {
            grid[0][j] = '*';
        }
    }

    private void readInput(Scanner scanner) {
        for (int i = 1; i <= rows; i++) {
            String line = scanner.next();
            for (int j = 1; j <= cols; j++) {
                grid[i][j] = line.charAt(j - 1);
            }
        }
    }

    private void process() {
        int currentLakeCount = 0;
        Map<Integer, List<Point>> lakesBySize = new TreeMap<>();

        // Identify all lakes and group them by size
        for (int i = 1; i <= rows; i++) {
            for (int j = 1; j <= cols; j++) {
                if (grid[i][j] == '.' && !visited[i][j]) {
                    LakeData lake = findLake(i, j);
                    if (!lake.touchesOcean) {
                        currentLakeCount++;
                        lakesBySize.computeIfAbsent(lake.size(), k -> new ArrayList<>())
                                   .addAll(lake.cells);
                    }
                }
            }
        }

        // Calculate how many lakes need to be removed
        int lakesToRemove = Math.max(0, currentLakeCount - targetLakes);
        int lakesRemoved = 0;
        int totalConvertedArea = 0;
        List<Point> pointsToConvert = new ArrayList<>();

        // Remove lakes starting from the smallest size
        while (lakesRemoved < lakesToRemove && !lakesBySize.isEmpty()) {
            List<Point> smallestLakeCells = lakesBySize.get(lakesBySize.firstKey());
            pointsToConvert.addAll(smallestLakeCells);
            totalConvertedArea += smallestLakeCells.size();
            lakesRemoved++;
            lakesBySize.remove(lakesBySize.firstKey());
        }

        // Convert selected lake cells to land
        for (Point p : pointsToConvert) {
            grid[p.x][p.y] = '*';
        }

        // Output results
        System.out.println(totalConvertedArea);
        for (int i = 1; i <= rows; i++) {
            System.out.println(new String(grid[i], 1, cols));
        }
    }

    /**
     * Performs a BFS to find all connected '.' cells starting from (startR, startC).
     * Returns lake metadata including cells, size, and ocean-touch status.
     */
    private LakeData findLake(int startR, int startC) {
        List<Point> cells = new ArrayList<>();
        Queue<Point> queue = new LinkedList<>();
        queue.add(new Point(startR, startC));
        visited[startR][startC] = true;
        cells.add(new Point(startR, startC));

        boolean touchesOcean = (startR == 1 || startR == rows || startC == 1 || startC == cols);

        while (!queue.isEmpty()) {
            Point current = queue.poll();
            for (int d = 0; d < 4; d++) {
                int r = current.x + DX[d];
                int c = current.y + DY[d];

                if (r >= 1 && r <= rows && c >= 1 && c <= cols &&
                    grid[r][c] == '.' && !visited[r][c]) {
                    visited[r][c] = true;
                    cells.add(new Point(r, c));
                    queue.add(new Point(r, c));

                    if (r == 1 || r == rows || c == 1 || c == cols) {
                        touchesOcean = true;
                    }
                }
            }
        }
        return new LakeData(cells, touchesOcean);
    }

    /**
     * Immutable data class holding information about a discovered lake.
     */
    private static class LakeData {
        final List<Point> cells;
        final boolean touchesOcean;

        LakeData(List<Point> cells, boolean touchesOcean) {
            this.cells = cells;
            this.touchesOcean = touchesOcean;
        }

        int size() {
            return cells.size();
        }
    }

    /**
     * Lightweight coordinate class to avoid heavy AWT dependencies.
     */
    private static class Point {
        final int x;
        final int y;

        Point(int x, int y) {
            this.x = x;
            this.y = y;
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Main class for the Lake Filling problem solution.
 * Refactored for better maintainability, code quality, and performance.
 */
public class Main {

    public static void main(String[] args) {
        // Initialize fast I/O for performance
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        FastScanner in = new FastScanner(inputStream);
        PrintWriter out = new PrintWriter(outputStream);

        // Instantiate and run the solver
        Solution solver = new Solution();
        solver.solve(in, out);

        // Ensure output is flushed and resources closed
        out.flush();
        out.close();
    }

    /**
     * Encapsulates the business logic for solving the problem.
     */
    static class Solution {

        public void solve(FastScanner in, PrintWriter out) {
            // Read grid dimensions and the number of lakes to fill
            int n = in.nextInt();
            int m = in.nextInt();
            int k = in.nextInt();

            // Read the grid
            // Using a boolean array where true represents water ('.') and false represents land ('*')
            boolean[][] grid = new boolean[n][m];
            for (int i = 0; i < n; i++) {
                String row = in.next();
                for (int j = 0; j < m; j++) {
                    grid[i][j] = (row.charAt(j) == '.');
                }
            }

            // Union-Find structure to manage connected components
            // We add a "sink" node at index n*m to represent the outside/border.
            // Any component connected to the sink is considered "open" (not a lake).
            int sink = n * m;
            UnionFind uf = new UnionFind(sink + 1);

            // 1. Process the grid:
            //    - Connect adjacent water cells.
            //    - Connect land cells to the sink.
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    int idx = i * m + j;
                    if (grid[i][j]) {
                        // Connect to Right neighbor
                        if (j + 1 < m && grid[i][j + 1]) {
                            uf.union(idx, idx + 1);
                        }
                        // Connect to Down neighbor
                        if (i + 1 < n && grid[i + 1][j]) {
                            uf.union(idx, idx + m);
                        }
                    } else {
                        // Land is connected to the sink (outside)
                        uf.union(idx, sink);
                    }
                }
            }

            // 2. Connect all border cells to the sink.
            //    Any water connected to the border is part of the ocean, not a lake.
            //    Top and Bottom rows
            for (int j = 0; j < m; j++) {
                uf.union(j, sink);                          // Top row: (0, j)
                uf.union((n - 1) * m + j, sink);            // Bottom row: (n-1, j)
            }
            // Left and Right columns
            for (int i = 0; i < n; i++) {
                uf.union(i * m, sink);                      // Left col: (i, 0)
                uf.union(i * m + (m - 1), sink);            // Right col: (i, m-1)
            }

            // 3. Count the size of each connected component
            int[] componentSizes = new int[sink + 1];
            for (int i = 0; i < n * m; i++) {
                int root = uf.find(i);
                componentSizes[root]++;
            }

            // 4. Identify Lakes
            // A lake is a component of water that is NOT connected to the sink.
            // We store the size of each lake. Key = Root Index, Value = Size.
            Map<Integer, Integer> lakes = new HashMap<>();
            for (int i = 0; i < n * m; i++) {
                int root = uf.find(i);
                // If it's not the sink, it's a potential lake (or a cluster of land not connected to border, 
                // but land is always connected to sink in step 1, so this must be water).
                if (root != sink) {
                    if (!lakes.containsKey(root)) {
                        lakes.put(root, componentSizes[root]);
                    }
                }
            }

            // 5. Sort lakes by size (ascending) to fill the smallest ones first
            List<Map.Entry<Integer, Integer>> sortedLakes = new ArrayList<>(lakes.entrySet());
            sortedLakes.sort(Map.Entry.comparingByValue());

            // 6. Fill the k smallest lakes
            int fills = 0;
            Set<Integer> rootsToFill = new HashSet<>();

            // Identify which component roots need to be filled
            for (int i = 0; i < k && i < sortedLakes.size(); i++) {
                rootsToFill.add(sortedLakes.get(i).getKey());
            }

            // Apply changes to the grid efficiently
            // Optimization: Iterate grid once instead of O(K * N * M)
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    if (rootsToFill.contains(uf.find(i * m + j))) {
                        grid[i][j] = false; // Convert water to land
                        fills++;
                    }
                }
            }

            // 7. Output results
            out.println(fills);
            StringBuilder sb = new StringBuilder();
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    sb.append(grid[i][j] ? '.' : '*');
                }
                sb.append('\n');
            }
            out.print(sb);
        }
    }

    /**
     * Efficient Union-Find (Disjoint Set Union) data structure 
     * with Path Compression and Union by Rank.
     */
    static class UnionFind {
        private int[] parent;
        private int[] rank;

        public UnionFind(int n) {
            parent = new int[n];
            rank = new int[n];
            for (int i = 0; i < n; i++) {
                parent[i] = i;
            }
        }

        public int find(int x) {
            if (parent[x] != x) {
                parent[x] = find(parent[x]); // Path compression
            }
            return parent[x];
        }

        public void union(int x, int y) {
            int rootX = find(x);
            int rootY = find(y);

            if (rootX != rootY) {
                // Union by rank to keep tree flat
                if (rank[rootX] > rank[rootY]) {
                    parent[rootY] = rootX;
                } else if (rank[rootX] < rank[rootY]) {
                    parent[rootX] = rootY;
                } else {
                    parent[rootY] = rootX;
                    rank[rootX]++;
                }
            }
        }
    }

    /**
     * Helper class for fast input reading.
     * Handles whitespace skipping and tokenizing efficiently.
     */
    static class FastScanner {
        BufferedReader br;
        StringTokenizer st;

        public FastScanner(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) {
                        return null;
                    }
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Solves a grid-based lake drainage problem.
 * Identifies connected components of water ('.'), determines which ones touch the boundary,
 * drains the smallest internal lakes until only k remain, and outputs the total volume drained
 * along with the modified grid.
 */
public class LakeDrainageSolver {

    private static final int[][] DIRECTIONS = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};

    /**
     * Represents a lake with its area size. Implements Comparable for min-heap ordering.
     */
    private record Lake(int size) implements Comparable<Lake> {
        @Override
        public int compareTo(Lake other) {
            return Integer.compare(this.size, other.size);
        }
    }

    /**
     * High-performance input scanner for competitive programming / fast I/O.
     */
    private static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        public String next() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) return null;
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

        public int nextInt() throws IOException {
            String token = next();
            if (token == null) throw new EOFException("Unexpected end of input");
            return Integer.parseInt(token);
        }
    }

    /**
     * High-performance output printer.
     */
    private static class FastPrinter {
        private final PrintWriter pw;

        public FastPrinter(OutputStream out) {
            pw = new PrintWriter(new BufferedOutputStream(out));
        }

        public void println(String s) {
            pw.println(s);
        }

        public void flush() {
            pw.flush();
        }
    }

    public static void main(String[] args) {
        long startTime = System.currentTimeMillis();
        try (FastScanner sc = new FastScanner(System.in);
             FastPrinter out = new FastPrinter(System.out)) {
            new LakeDrainageSolver().solve(sc, out);
        } catch (IOException e) {
            System.err.println("I/O Error: " + e.getMessage());
        } finally {
            System.err.println("[Time: " + (System.currentTimeMillis() - startTime) + " ms]");
        }
    }

    /**
     * Core logic to read the grid, identify lakes, drain excess, and print results.
     */
    private void solve(FastScanner sc, FastPrinter out) throws IOException {
        int rows = sc.nextInt();
        int cols = sc.nextInt();
        int k = sc.nextInt();

        // Pad the grid with a border to simplify boundary checks during traversal
        char[][] grid = new char[rows + 2][cols + 2];
        for (char[] row : grid) {
            Arrays.fill(row, '#');
        }

        for (int i = 1; i <= rows; i++) {
            String line = sc.next();
            for (int j = 0; j < cols; j++) {
                grid[i][j + 1] = line.charAt(j);
            }
        }

        PriorityQueue<Lake> lakes = new PriorityQueue<>();

        // Traverse the inner grid to find connected components
        for (int r = 1; r <= rows; r++) {
            for (int c = 1; c <= cols; c++) {
                if (grid[r][c] == '.') {
                    int size = bfs(grid, r, c);
                    // bfs returns negative size if the lake touches the boundary
                    if (size > 0) {
                        lakes.add(new Lake(size));
                    }
                }
            }
        }

        // Drain the smallest lakes until only k remain
        int totalDrained = 0;
        while (lakes.size() > k) {
            totalDrained += lakes.poll().size();
        }

        out.println(totalDrained);
        for (int i = 1; i <= rows; i++) {
            out.println(new String(grid[i], 1, cols));
        }
    }

    /**
     * Performs BFS to find the size of a connected component of '.' cells.
     * Marks visited cells as '*' to prevent re-processing.
     * Returns the component size, or a negative value if it touches the boundary.
     */
    private int bfs(char[][] grid, int startR, int startC) {
        int size = 0;
        boolean touchesBoundary = false;
        Deque<int[]> queue = new ArrayDeque<>();

        queue.offer(new int[]{startR, startC});
        grid[startR][startC] = '*';
        size++;

        while (!queue.isEmpty()) {
            int[] curr = queue.poll();
            for (int[] dir : DIRECTIONS) {
                int nr = curr[0] + dir[0];
                int nc = curr[1] + dir[1];

                if (grid[nr][nc] == '.') {
                    grid[nr][nc] = '*';
                    queue.offer(new int[]{nr, nc});
                    size++;
                } else if (grid[nr][nc] == '#') {
                    touchesBoundary = true;
                }
            }
        }

        return touchesBoundary ? -1 : size;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.StringTokenizer;

/**
 * Processes a grid to identify enclosed water bodies (lakes), 
 * removes the smallest ones until a target count remains, and outputs the result.
 */
public class GridProcessor {

    private int rows, cols, k;
    private char[][] grid;
    private boolean[][] visited;

    // Direction vectors for Up, Down, Left, Right
    private static final int[] DR = {0, 0, -1, 1};
    private static final int[] DC = {-1, 1, 0, 0};

    /**
     * Represents a connected component of water ('.') that does not touch the grid border.
     */
    private static class Lake implements Comparable<Lake> {
        final int size;
        final List<Coordinate> locations;

        Lake(int size, List<Coordinate> locations) {
            this.size = size;
            this.locations = locations;
        }

        @Override
        public int compareTo(Lake other) {
            return Integer.compare(this.size, other.size);
        }
    }

    /**
     * Immutable coordinate holder to replace java.awt.Point.
     * Avoids AWT dependencies and improves type safety.
     */
    private static class Coordinate {
        final int row, col;

        Coordinate(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    public static void main(String[] args) throws IOException {
        // Try-with-resources ensures the BufferedReader is properly closed
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            GridProcessor processor = new GridProcessor(br);
            processor.process();
        }
    }

    public GridProcessor(BufferedReader br) throws IOException {
        String line = br.readLine();
        if (line == null) {
            throw new IllegalArgumentException("Input stream is empty.");
        }

        StringTokenizer st = new StringTokenizer(line);
        this.rows = Integer.parseInt(st.nextToken());
        this.cols = Integer.parseInt(st.nextToken());
        this.k = Integer.parseInt(st.nextToken());

        this.grid = new char[rows][];
        this.visited = new boolean[rows][cols];

        for (int i = 0; i < rows; i++) {
            String rowLine = br.readLine();
            if (rowLine == null) {
                throw new IllegalArgumentException("Unexpected end of input while reading grid.");
            }
            this.grid[i] = rowLine.toCharArray();
        }
    }

    public void process() throws IOException {
        List<Lake> lakes = new ArrayList<>();

        // Traverse the grid to find all connected components
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (!visited[r][c] && grid[r][c] == '.') {
                    List<Coordinate> locations = new ArrayList<>();
                    dfs(r, c, locations);

                    // Only consider enclosed lakes (those not touching the border)
                    if (!touchesBorder(locations)) {
                        lakes.add(new Lake(locations.size(), locations));
                    }
                }
            }
        }

        // Sort lakes by size in ascending order
        Collections.sort(lakes);

        int removedCount = 0;
        // Remove smallest lakes until exactly k lakes remain
        while (lakes.size() > k) {
            Lake smallest = lakes.remove(0);
            removedCount += smallest.size;
            for (Coordinate coord : smallest.locations) {
                grid[coord.row][coord.col] = '*';
            }
        }

        // Build output
        StringBuilder sb = new StringBuilder();
        sb.append(removedCount).append('\n');
        for (int r = 0; r < rows; r++) {
            sb.append(grid[r]).append('\n');
        }
        System.out.print(sb);
    }

    /**
     * Depth-First Search to collect all coordinates of a connected component.
     */
    private void dfs(int r, int c, List<Coordinate> locations) {
        visited[r][c] = true;
        locations.add(new Coordinate(r, c));

        for (int dir = 0; dir < 4; dir++) {
            int nr = r + DR[dir];
            int nc = c + DC[dir];
            if (isValid(nr, nc) && !visited[nr][nc] && grid[nr][nc] == '.') {
                dfs(nr, nc, locations);
            }
        }
    }

    /**
     * Checks if coordinates are within grid boundaries.
     */
    private boolean isValid(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /**
     * Determines if any coordinate in the component touches the grid border.
     */
    private boolean touchesBorder(List<Coordinate> locations) {
        for (Coordinate coord : locations) {
            if (coord.row == 0 || coord.row == rows - 1 ||
                coord.col == 0 || coord.col == cols - 1) {
                return true;
            }
        }
        return false;
    }
}

