/**
 * Handles the core grid processing logic.
 * Designed to be stateless and reusable.
 */
class Solver {
    private static final int[][] DIRECTIONS = {{-1, 0}, {0, -1}, {1, 0}, {0, 1}};

    /**
     * Solves the problem for a single test case.
     *
     * @param n    Number of rows
     * @param m    Number of columns
     * @param k    Number of largest components to preserve
     * @param grid The input/output character grid
     * @param out  Output writer
     */
    void solve(int n, int m, int k, char[][] grid, PrintWriter out) {
        int[][] componentGrid = new int[n][m];

        // Initialize: mark walkable cells ('.') as 1
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == '.') {
                    componentGrid[i][j] = 1;
                }
            }
        }

        // Remove all components that touch the boundary
        clearBoundaryConnectedComponents(n, m, componentGrid);

        // Identify remaining internal components and calculate their sizes
        List<Component> components = new ArrayList<>();
        int currentId = 1;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (componentGrid[i][j] == 1) {
                    int size = bfs(n, m, componentGrid, i, j, currentId);
                    components.add(new Component(currentId, size));
                    currentId++;
                }
            }
        }

        // Sort components by size in ascending order
        components.sort(Comparator.comparingInt(c -> c.size));

        // Determine which component IDs should be replaced with '*'
        // We preserve the k largest, so we change the smallest (total - k)
        int componentsToChange = Math.max(0, components.size() - k);
        Set<Integer> idsToChange = new HashSet<>();
        for (int i = 0; i < componentsToChange; i++) {
            idsToChange.add(components.get(i).id);
        }

        // Apply changes to the original grid and count modifications
        int changedCount = 0;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                int compId = componentGrid[i][j];
                if (compId > 1 && idsToChange.contains(compId)) {
                    grid[i][j] = '*';
                    changedCount++;
                }
            }
        }

        // Output results
        out.println(changedCount);
        for (int i = 0; i < n; i++) {
            out.println(new String(grid[i]));
        }
    }

    /**
     * Clears all connected components that touch the grid boundary.
     */
    private void clearBoundaryConnectedComponents(int n, int m, int[][] grid) {
        // Check first and last column
        for (int i = 0; i < n; i++) {
            if (grid[i][0] == 1) bfs(n, m, grid, i, 0, 0);
            if (grid[i][m - 1] == 1) bfs(n, m, grid, i, m - 1, 0);
        }
        // Check first and last row
        for (int j = 0; j < m; j++) {
            if (grid[0][j] == 1) bfs(n, m, grid, 0, j, 0);
            if (grid[n - 1][j] == 1) bfs(n, m, grid, n - 1, j, 0);
        }
    }

    /**
     * Iterative BFS to traverse a connected component.
     * Sets visited cells to targetId and returns the component size.
     * If targetId is 0, it effectively clears the component.
     */
    private int bfs(int n, int m, int[][] grid, int startR, int startC, int targetId) {
        Queue<int[]> queue = new ArrayDeque<>();
        queue.offer(new int[]{startR, startC});
        grid[startR][startC] = targetId;
        int size = 0;

        while (!queue.isEmpty()) {
            int[] current = queue.poll();
            size++;
            for (int[] dir : DIRECTIONS) {
                int r = current[0] + dir[0];
                int c = current[1] + dir[1];
                if (r >= 0 && r < n && c >= 0 && c < m && grid[r][c] == 1) {
                    grid[r][c] = targetId;
                    queue.offer(new int[]{r, c});
                }
            }
        }
        return size;
    }

    /**
     * Immutable record-like class to store component metadata.
     */
    private static class Component {
        final int id;
        final int size;

        Component(int id, int size) {
            this.id = id;
            this.size = size;
        }
    }
}

