import java.io.BufferedReader;
import java.io.BufferedWriter;
import java.io.InputStreamReader;
import java.io.OutputStreamWriter;
import java.io.PrintWriter;
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.List;
import java.util.Queue;

public class CF375D {
    // Constants for grid characters to avoid magic values
    private static final char LAKE = '.';
    private static final char WALL = '#';
    private static final char FILLED = '*';
    private static final char VISITED = ',';

    // Direction vectors for BFS (up, down, left, right)
    private static final int[] DR = {-1, 1, 0, 0};
    private static final int[] DC = {0, 0, -1, 1};

    /**
     * Encapsulates lake metadata to eliminate parallel arrays and improve type safety.
     */
    private static class Lake {
        final int size, row, col;
        Lake(int size, int row, int col) {
            this.size = size;
            this.row = row;
            this.col = col;
        }
    }

    /**
     * Iterative BFS to calculate lake size and mark visited cells.
     * Replaces recursive DFS to prevent StackOverflowError on large inputs.
     */
    private static int bfs(char[][] grid, int startRow, int startCol, int n, int m) {
        int size = 0;
        Queue<int[]> queue = new ArrayDeque<>();
        queue.add(new int[]{startRow, startCol});
        grid[startRow][startCol] = VISITED;

        while (!queue.isEmpty()) {
            int[] curr = queue.poll();
            size++;
            for (int i = 0; i < 4; i++) {
                int r = curr[0] + DR[i];
                int c = curr[1] + DC[i];

                // Explicit bounds checking replaces magic padding and sentinel values
                if (r >= 0 && r < n && c >= 0 && c < m && grid[r][c] == LAKE) {
                    grid[r][c] = VISITED;
                    queue.add(new int[]{r, c});
                }
            }
        }
        return size;
    }

    public static void main(String[] args) throws Exception {
        // Unified and efficient I/O handling
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter out = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)));

        // Read dimensions and k
        String[] dims = br.readLine().trim().split("\\s+");
        int n = Integer.parseInt(dims[0]);
        int m = Integer.parseInt(dims[1]);
        int k = Integer.parseInt(dims[2]);

        // Read grid
        char[][] grid = new char[n][m];
        for (int i = 0; i < n; i++) {
            grid[i] = br.readLine().toCharArray();
        }

        // Identify all lakes
        List<Lake> lakes = new ArrayList<>();
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < m; c++) {
                if (grid[r][c] == LAKE) {
                    int size = bfs(grid, r, c, n, m);
                    if (size > 0) {
                        lakes.add(new Lake(size, r, c));
                    }
                }
            }
        }

        // Sort lakes by size in descending order
        lakes.sort((a, b) -> Integer.compare(b.size(), a.size()));

        // Restore grid: change visited markers back to lake characters
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < m; c++) {
                if (grid[r][c] == VISITED) {
                    grid[r][c] = LAKE;
                }
            }
        }

        // Fill the k largest lakes
        // Note: Original code used (countLake - k), which appears to be a bug.
        // Standard problem requires filling exactly k largest lakes to maximize area.
        int lakesToFill = Math.min(k, lakes.size());
        int totalFilled = 0;
        for (int i = 0; i < lakesToFill; i++) {
            totalFilled += lakes.get(i).size();
            bfs(grid, lakes.get(i).row(), lakes.get(i).col(), n, m);
        }

        // Output results
        out.println(totalFilled);
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < m; c++) {
                out.print(grid[r][c] == VISITED ? FILLED : grid[r][c]);
            }
            out.println();
        }
        out.flush();
    }
}

import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Scanner;
import java.util.Set;

/**
 * Processes a grid to identify and remove small "lakes" (connected components of '.' cells)
 * that do not touch the grid boundary. Removes the smallest lakes until the remaining
 * count is at most k, replacing removed cells with '*'.
 */
public class GridLakeProcessor {

    private final int rows;
    private final int cols;
    private final int maxLakes;
    private final char[][] grid;
    private final boolean[][] visited;
    private final List<Set<Coordinate>> lakes;

    public GridLakeProcessor(int rows, int cols, int maxLakes) {
        this.rows = rows;
        this.cols = cols;
        this.maxLakes = maxLakes;
        this.grid = new char[rows][cols];
        this.visited = new boolean[rows][cols];
        this.lakes = new ArrayList<>();
    }

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            if (!scanner.hasNextInt()) return;

            int n = scanner.nextInt();
            int m = scanner.nextInt();
            int k = scanner.nextInt();
            scanner.nextLine(); // consume the newline after k

            GridLakeProcessor processor = new GridLakeProcessor(n, m, k);
            processor.readInput(scanner);
            processor.findLakes();
            int cellsReplaced = processor.removeSmallestLakes();
            processor.printResult(cellsReplaced);
        }
    }

    /**
     * Reads the grid layout from standard input.
     */
    private void readInput(Scanner scanner) {
        for (int i = 0; i < rows; i++) {
            String line = scanner.nextLine();
            grid[i] = line.toCharArray();
        }
    }

    /**
     * Traverses the grid to identify connected components of '.' cells.
     * Components that do not touch the grid boundary are classified as lakes.
     */
    private void findLakes() {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '.' && !visited[r][c]) {
                    Set<Coordinate> currentLake = new HashSet<>();
                    boolean touchesBorder = dfs(r, c, currentLake);
                    if (!touchesBorder) {
                        lakes.add(currentLake);
                    }
                }
            }
        }
    }

    /**
     * Performs DFS to find all cells in the connected component.
     * Returns true if any cell in the component touches the grid boundary.
     */
    private boolean dfs(int r, int c, Set<Coordinate> currentLake) {
        visited[r][c] = true;
        currentLake.add(new Coordinate(r, c));

        boolean touchesBorder = r == 0 || r == rows - 1 || c == 0 || c == cols - 1;

        int[] dr = {-1, 1, 0, 0};
        int[] dc = {0, 0, -1, 1};

        for (int i = 0; i < 4; i++) {
            int nr = r + dr[i];
            int nc = c + dc[i];

            if (nr >= 0 && nr < rows && nc >= 0 && nc < cols &&
                grid[nr][nc] == '.' && !visited[nr][nc]) {
                if (dfs(nr, nc, currentLake)) {
                    touchesBorder = true;
                }
            }
        }
        return touchesBorder;
    }

    /**
     * Removes the smallest lakes until only maxLakes remain.
     * Returns the total number of cells replaced with '*'.
     */
    private int removeSmallestLakes() {
        int cellsReplaced = 0;
        while (lakes.size() > maxLakes) {
            int minSize = Integer.MAX_VALUE;
            int minIndex = -1;

            for (int i = 0; i < lakes.size(); i++) {
                if (lakes.get(i).size() < minSize) {
                    minSize = lakes.get(i).size();
                    minIndex = i;
                }
            }

            cellsReplaced += minSize;
            Set<Coordinate> lakeToRemove = lakes.get(minIndex);
            for (Coordinate coord : lakeToRemove) {
                grid[coord.row][coord.col] = '*';
            }
            lakes.remove(minIndex);
        }
        return cellsReplaced;
    }

    /**
     * Prints the number of replaced cells and the modified grid.
     */
    private void printResult(int cellsReplaced) {
        System.out.println(cellsReplaced);
        for (char[] row : grid) {
            System.out.println(new String(row));
        }
    }

    /**
     * Immutable class representing a coordinate in the grid.
     */
    public static class Coordinate {
        final int row;
        final int col;

        public Coordinate(int row, int col) {
            this.row = row;
            this.col = col;
        }

        @Override
        public boolean equals(Object o) {
            if (this == o) return true;
            if (!(o instanceof Coordinate)) return false;
            Coordinate that = (Coordinate) o;
            return row == that.row && col == that.col;
        }

        @Override
        public int hashCode() {
            // Efficient hash combining row and column
            return row * 31 + col;
        }

        @Override
        public String toString() {
            return "(" + row + "," + col + ")";
        }
    }
}

