class TaskLakes {

    public void solve(int taskNumber, InputReader in, PrintWriter out) {
        int n = in.nextInt();
        int m = in.nextInt();
        int k = in.nextInt();

        char[][] grid = new char[n][m];
        for (int i = 0; i < n; i++) {
            grid[i] = in.next().toCharArray();
        }

        boolean[][] visited = new boolean[n][m];
        List<Component> enclosedLakes = new ArrayList<>();

        // Direction vectors: up, down, left, right
        int[] dr = {-1, 1, 0, 0};
        int[] dc = {0, 0, -1, 1};

        // Only need to initiate traversal from inner cells
        for (int i = 1; i < n - 1; i++) {
            for (int j = 1; j < m - 1; j++) {
                if (grid[i][j] == '.' && !visited[i][j]) {
                    Component component = findComponent(i, j, grid, visited, n, m, dr, dc);
                    if (component.isEnclosed) {
                        enclosedLakes.add(component);
                    }
                }
            }
        }

        // Sort lakes by size in ascending order
        enclosedLakes.sort(Comparator.comparingInt(c -> c.size));

        int removedArea = 0;
        int lakesToKeep = Math.min(k, enclosedLakes.size());
        int lakesToRemove = enclosedLakes.size() - lakesToKeep;

        // Remove the smallest lakes
        for (int i = 0; i < lakesToRemove; i++) {
            removedArea += enclosedLakes.get(i).size;
            for (Cell cell : enclosedLakes.get(i).cells) {
                grid[cell.r][cell.c] = '*';
            }
        }

        out.println(removedArea);
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < n; i++) {
            sb.append(grid[i]).append('\n');
        }
        out.print(sb);
        out.flush();
    }

    /**
     * Represents a connected component of lake cells.
     */
    private static class Component {
        final int size;
        final boolean isEnclosed;
        final List<Cell> cells;

        Component(int size, boolean isEnclosed, List<Cell> cells) {
            this.size = size;
            this.isEnclosed = isEnclosed;
            this.cells = cells;
        }
    }

    /**
     * Represents a grid coordinate.
     */
    private static class Cell {
        final int r, c;
        Cell(int r, int c) {
            this.r = r;
            this.c = c;
        }
    }

    /**
     * Performs BFS to find a connected component of '.' cells.
     * Returns component details including size, enclosure status, and cell coordinates.
     */
    private Component findComponent(int startR, int startC, char[][] grid, boolean[][] visited,
                                    int n, int m, int[] dr, int[] dc) {
        List<Cell> cells = new ArrayList<>();
        boolean isEnclosed = true;
        Deque<Cell> queue = new ArrayDeque<>();

        queue.add(new Cell(startR, startC));
        visited[startR][startC] = true;
        cells.add(new Cell(startR, startC));

        while (!queue.isEmpty()) {
            Cell curr = queue.poll();
            for (int d = 0; d < 4; d++) {
                int nr = curr.r + dr[d];
                int nc = curr.c + dc[d];

                // Skip out-of-bounds neighbors
                if (nr < 0 || nr >= n || nc < 0 || nc >= m) {
                    continue;
                }

                // Check if neighbor is on the border and is a lake
                if (nr == 0 || nr == n - 1 || nc == 0 || nc == m - 1) {
                    if (grid[nr][nc] == '.') {
                        isEnclosed = false;
                    }
                }

                // Traverse unvisited lake cells
                if (!visited[nr][nc] && grid[nr][nc] == '.') {
                    visited[nr][nc] = true;
                    Cell next = new Cell(nr, nc);
                    cells.add(next);
                    queue.add(next);
                }
            }
        }
        return new Component(cells.size(), isEnclosed, cells);
    }
}

class InputReader {
    public BufferedReader reader;
    public StringTokenizer tokenizer;

    public InputReader(InputStream stream) {
        reader = new BufferedReader(new InputStreamReader(stream), 32768);
        tokenizer = null;
    }

    public String next() {
        while (tokenizer == null || !tokenizer.hasMoreTokens()) {
            try {
                String line = reader.readLine();
                if (line == null) {
                    return null;
                }
                tokenizer = new StringTokenizer(line);
            } catch (IOException e) {
                throw new RuntimeException("Error reading input", e);
            }
        }
        return tokenizer.nextToken();
    }

    public int nextInt() {
        String s = next();
        if (s == null) throw new RuntimeException("Unexpected end of input");
        return Integer.parseInt(s);
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.StringTokenizer;

/**
 * Refactored solution for problem P11_Div2_723D.
 * 
 * Improvements made:
 * 1. Encapsulation: Removed global static state (arr, cnt, visited, flag) and moved logic into instance methods.
 * 2. I/O Efficiency: Used BufferedReader and StringTokenizer for fast input, and PrintWriter for buffered output.
 * 3. Modularity: Extracted logic into distinct methods (traverseLake, fillLake, solve) for better readability and testing.
 * 4. Safety: Added bounds checking in recursive methods to prevent StackOverflow or ArrayIndexOutOfBoundsException.
 * 5. Naming: Used descriptive variable and method names.
 * 6. Logic Clarity: Clarified the lake detection and filling logic.
 */
public class P11_Div2_723D {

    public static void main(String[] args) throws IOException {
        // Fast I/O setup
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter out = new PrintWriter(System.out);

        String line = br.readLine();
        if (line != null) {
            StringTokenizer st = new StringTokenizer(line);
            if (st.hasMoreTokens()) {
                int n = Integer.parseInt(st.nextToken());
                int m = Integer.parseInt(st.nextToken());
                int k = Integer.parseInt(st.nextToken());

                char[][] grid = new char[n][m];
                for (int i = 0; i < n; i++) {
                    String row = br.readLine();
                    if (row != null) {
                        grid[i] = row.toCharArray();
                    }
                }

                // Instantiate solver and execute logic
                P11_Div2_723D solver = new P11_Div2_723D();
                solver.solve(grid, n, m, k, out);
            }
        }
        out.flush();
    }

    /**
     * Main logic to find lakes, sort them, and fill the smallest ones.
     */
    private void solve(char[][] grid, int n, int m, int k, PrintWriter out) {
        boolean[][] visited = new boolean[n][m];
        List<Lake> lakes = new ArrayList<>();

        // Iterate through the grid, skipping the border cells (1 to n-2)
        // Lakes touching the boundary are not considered valid enclosed lakes.
        for (int i = 1; i < n - 1; i++) {
            for (int j = 1; j < m - 1; j++) {
                if (grid[i][j] == '.' && !visited[i][j]) {
                    // Found a potential lake component
                    int[] size = new int[1];
                    boolean[] touchesBoundary = new boolean[1];

                    // Traverse to count size and check if it touches the grid boundary
                    traverseLake(grid, visited, i, j, size, touchesBoundary);

                    // If the component does not touch the boundary, it is a valid lake
                    if (!touchesBoundary[0]) {
                        lakes.add(new Lake(i, j, size[0]));
                    }
                }
            }
        }

        // Sort lakes by size in ascending order
        Collections.sort(lakes);

        int lakesRemaining = lakes.size();
        int filledSize = 0;
        int idx = 0;

        // Fill lakes until the number of remaining lakes equals k.
        // We fill the smallest lakes first to minimize the cost (though cost here is just size).
        while (k < lakesRemaining && idx < lakes.size()) {
            Lake lake = lakes.get(idx);
            fillLake(grid, lake.i, lake.j);
            filledSize += lake.cn;
            lakesRemaining--;
            idx++;
        }

        // Output results
        out.println(filledSize);
        for (int i = 0; i < n; i++) {
            out.println(new String(grid[i]));
        }
    }

    /**
     * DFS traversal to count the size of the connected component ('.')
     * and determine if it touches the grid boundary.
     * Marks visited cells to prevent reprocessing.
     */
    private void traverseLake(char[][] grid, boolean[][] visited, int r, int c, int[] size, boolean[] touchesBoundary) {
        // Check bounds
        if (r < 0 || r >= grid.length || c < 0 || c >= grid[0].length) {
            touchesBoundary[0] = true;
            return;
        }

        // Check if already visited or is an obstacle
        if (visited[r][c] || grid[r][c] == '*') {
            return;
        }

        visited[r][c] = true;
        size[0]++;

        // Check if current cell is on the boundary of the grid
        if (r == 0 || r == grid.length - 1 || c == 0 || c == grid[0].length - 1) {
            touchesBoundary[0] = true;
        }

        // Recurse to neighbors
        traverseLake(grid, visited, r + 1, c, size, touchesBoundary);
        traverseLake(grid, visited, r - 1, c, size, touchesBoundary);
        traverseLake(grid, visited, r, c + 1, size, touchesBoundary);
        traverseLake(grid, visited, r, c - 1, size, touchesBoundary);
    }

    /**
     * DFS to fill the lake with '*' (obstacles).
     * Fills the connected component of '.' starting at (r, c).
     */
    private void fillLake(char[][] grid, int r, int c) {
        // Bounds check
        if (r < 0 || r >= grid.length || c < 0 || c >= grid[0].length) {
            return;
        }

        // If already filled or obstacle, stop
        if (grid[r][c] == '*') {
            return;
        }

        grid[r][c] = '*';

        fillLake(grid, r + 1, c);
        fillLake(grid, r - 1, c);
        fillLake(grid, r, c + 1);
        fillLake(grid, r, c - 1);
    }

    /**
     * Represents a lake found in the grid.
     */
    static class Lake implements Comparable<Lake> {
        int i, j; // Coordinates
        int cn;   // Size (count)

        public Lake(int i, int j, int cn) {
            this.i = i;
            this.j = j;
            this.cn = cn;
        }

        @Override
        public int compareTo(Lake o) {
            return Integer.compare(this.cn, o.cn);
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Refactored solution for grid component analysis.
 * Uses Disjoint Set Union (DSU) with path compression and union by size
 * to efficiently manage connected components of '.' characters.
 */
public class ConnectedComponentsSolver {

    /**
     * Represents a cell in the grid and participates in the DSU structure.
     */
    static class CellNode {
        int r, c;
        CellNode parent;
        boolean touchesBoundary;
        List<CellNode> members;

        CellNode(int r, int c, int rows, int cols) {
            this.r = r;
            this.c = c;
            this.parent = this;
            // A component touches the boundary if any of its cells are on the edge.
            this.touchesBoundary = (r == 0 || r == rows - 1 || c == 0 || c == cols - 1);
            this.members = new ArrayList<>();
            this.members.add(this);
        }
    }

    public static void main(String[] args) {
        FastScanner sc = new FastScanner();
        PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out));

        // Read dimensions and target count
        // Using FastScanner to handle whitespace/newlines robustly
        String nStr = sc.next();
        if (nStr == null) {
            out.flush();
            return;
        }
        int n = Integer.parseInt(nStr);
        int m = sc.nextInt();
        int k = sc.nextInt();

        // Read grid
        char[][] grid = new char[n][m];
        for (int i = 0; i < n; i++) {
            String row = sc.next();
            if (row != null) {
                grid[i] = row.toCharArray();
            }
        }

        // DSU Grid
        CellNode[][] gridNodes = new CellNode[n][m];

        // Process Grid: Initialize nodes and perform unions
        for (int i = 0; i < n; i++) {
            if (grid[i] == null) continue;
            int rowLen = grid[i].length;

            for (int j = 0; j < m; j++) {
                if (j >= rowLen) break;

                if (grid[i][j] == '.') {
                    CellNode node = new CellNode(i, j, n, m);
                    gridNodes[i][j] = node;

                    // Union with Up neighbor
                    if (i > 0 && gridNodes[i - 1][j] != null) {
                        union(node, gridNodes[i - 1][j]);
                    }
                    // Union with Left neighbor
                    if (j > 0 && gridNodes[i][j - 1] != null) {
                        union(node, gridNodes[i][j - 1]);
                    }
                }
            }
        }

        // Collect unique leaders of components that do not touch the boundary
        Set<CellNode> leaders = new HashSet<>();
        for (int i = 0; i < n; i++) {
            if (grid[i] == null) continue;
            int rowLen = grid[i].length;
            for (int j = 0; j < m; j++) {
                if (j >= rowLen) break;

                if (gridNodes[i][j] != null) {
                    CellNode root = find(gridNodes[i][j]);
                    if (!root.touchesBoundary) {
                        leaders.add(root);
                    }
                }
            }
        }

        // Sort components by size (ascending) to destroy smallest ones first
        List<CellNode> sortedLeaders = new ArrayList<>(leaders);
        Collections.sort(sortedLeaders, (a, b) -> Integer.compare(a.members.size(), b.members.size()));

        int totalComponents = sortedLeaders.size();
        int componentsToDestroy = totalComponents - k;
        int changesCount = 0;

        // Destroy the smallest components
        if (componentsToDestroy > 0) {
            for (int i = 0; i < componentsToDestroy; i++) {
                CellNode root = sortedLeaders.get(i);
                for (CellNode member : root.members) {
                    // Mark cell as destroyed
                    if (member.r < n && member.c < m) {
                        grid[member.r][member.c] = '*';
                        changesCount++;
                    }
                }
            }
        }

        // Output results
        out.println(changesCount);
        for (int i = 0; i < n; i++) {
            if (grid[i] != null) {
                out.println(grid[i]);
            } else {
                out.println();
            }
        }

        out.flush();
    }

    // --- DSU Methods ---

    /**
     * Finds the representative (root) of the set containing node.
     * Implements path compression for efficiency.
     */
    private static CellNode find(CellNode node) {
        CellNode root = node;
        while (root.parent != root) {
            root = root.parent;
        }
        // Path compression
        CellNode curr = node;
        while (curr != root) {
            CellNode next = curr.parent;
            curr.parent = root;
            curr = next;
        }
        return root;
    }

    /**
     * Unites the sets containing nodeA and nodeB.
     * Implements union by size to keep tree height low.
     */
    private static void union(CellNode nodeA, CellNode nodeB) {
        CellNode rootA = find(nodeA);
        CellNode rootB = find(nodeB);

        if (rootA == rootB) return;

        // Attach smaller tree to larger tree
        if (rootA.members.size() < rootB.members.size()) {
            mergeInto(rootA, rootB);
        } else {
            mergeInto(rootB, rootA);
        }
    }

    /**
     * Merges the 'smaller' component into the 'larger' component.
     */
    private static void mergeInto(CellNode smaller, CellNode larger) {
        // Update boundary status
        larger.touchesBoundary |= smaller.touchesBoundary;

        // Move members to the new root
        for (CellNode member : smaller.members) {
            member.parent = larger;
        }
        larger.members.addAll(smaller.members);

        // Clear the old list to free memory
        smaller.members.clear();
    }

    /**
     * Helper class for fast input reading.
     */
    static class FastScanner {
        BufferedReader br;
        StringTokenizer st;

        public FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            String s = next();
            return s == null ? 0 : Integer.parseInt(s);
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayList;
import java.util.Collections;
import java.util.StringTokenizer;

public class D {

    // Direction vectors for moving up, down, left, right
    private static final int[] DR = {-1, 1, 0, 0};
    private static final int[] DC = {0, 0, -1, 1};

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));

        // Read dimensions and k
        String line = br.readLine();
        if (line == null) return;
        StringTokenizer st = new StringTokenizer(line);
        int R = Integer.parseInt(st.nextToken());
        int C = Integer.parseInt(st.nextToken());
        int k = Integer.parseInt(st.nextToken());

        // Read grid
        char[][] grid = new char[R][C];
        for (int i = 0; i < R; i++) {
            String row = br.readLine();
            if (row != null) {
                grid[i] = row.trim().toCharArray();
            }
        }

        // Identify all connected components of '.'
        ArrayList<Component> components = findComponents(grid, R, C);

        // Sort components by size in ascending order
        Collections.sort(components);

        // Calculate sum of sizes for the first k components
        int componentsToRemove = Math.min(k, components.size());
        int sum = 0;
        for (int i = 0; i < componentsToRemove; i++) {
            sum += components.get(i).size;
        }

        // Mark the k smallest components as '*'
        for (int i = 0; i < componentsToRemove; i++) {
            markComponent(grid, components.get(i).r, components.get(i).c, '.', '*');
        }

        // Output results
        System.out.println(sum);
        for (int i = 0; i < R; i++) {
            System.out.println(new String(grid[i]));
        }
    }

    /**
     * Identifies all connected components of the target character using DFS.
     */
    private static ArrayList<Component> findComponents(char[][] grid, int R, int C) {
        ArrayList<Component> components = new ArrayList<>();
        boolean[][] visited = new boolean[R][C];

        for (int i = 0; i < R; i++) {
            for (int j = 0; j < C; j++) {
                if (grid[i][j] == '.' && !visited[i][j]) {
                    int size = floodFill(grid, visited, i, j, '.');
                    components.add(new Component(i, j, size));
                }
            }
        }
        return components;
    }

    /**
     * Counts the size of a connected component using recursive DFS.
     */
    private static int floodFill(char[][] grid, boolean[][] visited, int r, int c, char target) {
        if (r < 0 || r >= grid.length || c < 0 || c >= grid[0].length) {
            return 0;
        }
        if (visited[r][c] || grid[r][c] != target) {
            return 0;
        }

        visited[r][c] = true;
        int count = 1;
        for (int d = 0; d < 4; d++) {
            count += floodFill(grid, visited, r + DR[d], c + DC[d], target);
        }
        return count;
    }

    /**
     * Replaces the target character with the replacement character
     * for a specific connected component.
     */
    private static void markComponent(char[][] grid, int r, int c, char target, char replacement) {
        if (r < 0 || r >= grid.length || c < 0 || c >= grid[0].length) {
            return;
        }
        if (grid[r][c] != target) {
            return;
        }

        grid[r][c] = replacement;
        for (int d = 0; d < 4; d++) {
            markComponent(grid, r + DR[d], c + DC[d], target, replacement);
        }
    }

    /**
     * Represents a connected component in the grid.
     */
    private static class Component implements Comparable<Component> {
        int r, c, size;

        public Component(int r, int c, int size) {
            this.r = r;
            this.c = c;
            this.size = size;
        }

        @Override
        public int compareTo(Component other) {
            return Integer.compare(this.size, other.size);
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.StringTokenizer;

/**
 * Solves the "Lakes" problem by identifying connected components of water cells ('.')
 * that do not touch the grid boundary, and draining the smallest ones to leave exactly k lakes.
 */
public class LakeSolver {

    private final int rows;
    private final int cols;
    private char[][] grid;

    /**
     * Initializes the grid dimensions.
     *
     * @param rows Number of rows in the grid
     * @param cols Number of columns in the grid
     */
    public LakeSolver(int rows, int cols) {
        this.rows = rows;
        this.cols = cols;
        this.grid = new char[rows][cols];
    }

    public static void main(String[] args) throws IOException {
        // BufferedReader provides significantly better performance than Scanner for large inputs
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            String line = br.readLine();
            if (line == null) return;

            StringTokenizer st = new StringTokenizer(line);
            int n = Integer.parseInt(st.nextToken());
            int m = Integer.parseInt(st.nextToken());
            int k = Integer.parseInt(st.nextToken());

            LakeSolver solver = new LakeSolver(n, m);
            for (int i = 0; i < n; i++) {
                String rowStr = br.readLine();
                // Skip empty lines if present
                while (rowStr != null && rowStr.trim().isEmpty()) {
                    rowStr = br.readLine();
                }
                if (rowStr == null) break;

                for (int j = 0; j < m; j++) {
                    solver.grid[i][j] = rowStr.charAt(j);
                }
            }

            solver.solve(k);
        }
    }

    /**
     * Orchestrates the lake detection, sorting, draining, and output.
     *
     * @param k The target number of lakes to preserve
     */
    public void solve(int k) {
        List<Lake> lakes = findLakes();

        // Sort lakes by size in ascending order using efficient built-in sort
        Collections.sort(lakes, (a, b) -> Integer.compare(a.size(), b.size()));

        int lakesToDrain = Math.max(0, lakes.size() - k);
        int totalDrainedCells = 0;

        for (int i = 0; i < lakesToDrain; i++) {
            Lake lake = lakes.get(i);
            for (int[] coord : lake.getCoordinates()) {
                grid[coord[0]][coord[1]] = '*';
                totalDrainedCells++;
            }
        }

        System.out.println(totalDrainedCells);
        printGrid();
    }

    /**
     * Scans the grid interior to find all connected components of '.' cells.
     * Identifies which components are valid lakes (do not touch the boundary).
     *
     * @return List of valid lakes
     */
    private List<Lake> findLakes() {
        boolean[][] visited = new boolean[rows][cols];
        List<Lake> lakes = new ArrayList<>();

        // Lakes cannot start or touch the boundary, so we only scan interior cells
        for (int i = 1; i < rows - 1; i++) {
            for (int j = 1; j < cols - 1; j++) {
                if (grid[i][j] == '.' && !visited[i][j]) {
                    List<int[]> component = new ArrayList<>();
                    boolean isLake = bfs(i, j, visited, component);
                    if (isLake) {
                        lakes.add(new Lake(component));
                    }
                }
            }
        }
        return lakes;
    }

    /**
     * Performs Breadth-First Search to find a connected component of '.' cells.
     *
     * @param startRow Starting row index
     * @param startCol Starting column index
     * @param visited  Tracks visited cells to prevent cycles
     * @param component Accumulates coordinates of the current component
     * @return true if the component is a lake (does not touch the grid boundary), false otherwise
     */
    private boolean bfs(int startRow, int startCol, boolean[][] visited, List<int[]> component) {
        List<int[]> queue = new ArrayList<>();
        queue.add(new int[]{startRow, startCol});
        visited[startRow][startCol] = true;
        boolean touchesBoundary = false;

        int[] dr = {-1, 1, 0, 0};
        int[] dc = {0, 0, -1, 1};

        int head = 0;
        while (head < queue.size()) {
            int[] curr = queue.get(head++);
            int r = curr[0];
            int c = curr[1];
            component.add(curr);

            // Check if current cell is on the grid boundary
            if (r == 0 || r == rows - 1 || c == 0 || c == cols - 1) {
                touchesBoundary = true;
            }

            // Explore 4-directional neighbors
            for (int d = 0; d < 4; d++) {
                int nr = r + dr[d];
                int nc = c + dc[d];

                if (nr >= 0 && nr < rows && nc >= 0 && nc < cols &&
                    !visited[nr][nc] && grid[nr][nc] == '.') {
                    visited[nr][nc] = true;
                    queue.add(new int[]{nr, nc});
                }
            }
        }
        return !touchesBoundary;
    }

    /**
     * Prints the final grid state to standard output.
     */
    private void printGrid() {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                sb.append(grid[i][j]);
            }
            sb.append('\n');
        }
        System.out.print(sb);
    }

    /**
     * Represents a lake (connected component of water cells).
     * Static nested class avoids implicit reference to the outer class instance.
     */
    private static class Lake {
        private final List<int[]> coordinates;

        public Lake(List<int[]> coordinates) {
            this.coordinates = coordinates;
        }

        public List<int[]> getCoordinates() {
            return coordinates;
        }

        public int size() {
            return coordinates.size();
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Solves a grid-based lake removal problem.
 * Finds connected components of '.', filters out those touching the boundary,
 * sorts remaining lakes by size, removes the smallest until k remain,
 * and outputs the number of removed cells plus the modified grid.
 */
public class LakeRemovalSolver {

    private static final int[] DX = {-1, 1, 0, 0};
    private static final int[] DY = {0, 0, -1, 1};

    private final char[][] grid;
    private final int rows;
    private final int cols;
    private final int k;

    public LakeRemovalSolver(int rows, int cols, int k) {
        this.rows = rows;
        this.cols = cols;
        this.k = k;
        this.grid = new char[rows][cols];
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String firstLine = br.readLine();
        if (firstLine == null) return;

        StringTokenizer st = new StringTokenizer(firstLine);
        int n = Integer.parseInt(st.nextToken());
        int m = Integer.parseInt(st.nextToken());
        int k = Integer.parseInt(st.nextToken());

        // Consume the remainder of the first line (including newline)
        br.readLine();

        LakeRemovalSolver solver = new LakeRemovalSolver(n, m, k);
        solver.solve();
    }

    public void solve() throws IOException {
        readInput();
        List<Lake> lakes = findLakes();
        int removedCount = removeSmallestLakes(lakes);
        printResult(removedCount);
    }

    private void readInput() throws IOException {
        for (int i = 0; i < rows; i++) {
            String line = br.readLine();
            // Skip empty lines that may appear due to formatting
            while (line != null && line.trim().isEmpty()) {
                line = br.readLine();
            }
            if (line == null) break;

            for (int j = 0; j < cols && j < line.length(); j++) {
                grid[i][j] = line.charAt(j);
            }
        }
    }

    private List<Lake> findLakes() {
        List<Lake> lakes = new ArrayList<>();
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == '.') {
                    Lake lake = new Lake();
                    boolean touchesBoundary = dfs(i, j, lake);
                    if (!touchesBoundary) {
                        lakes.add(lake);
                    }
                }
            }
        }
        return lakes;
    }

    /**
     * Iterative DFS to find connected '.' cells.
     * Marks visited cells as 'X' to avoid reprocessing.
     * Returns true if the component touches the grid boundary.
     */
    private boolean dfs(int startRow, int startCol, Lake lake) {
        Deque<int[]> stack = new ArrayDeque<>();
        stack.push(new int[]{startRow, startCol});
        grid[startRow][startCol] = 'X'; // Mark as visited immediately
        boolean touchesBoundary = false;

        while (!stack.isEmpty()) {
            int[] current = stack.pop();
            int r = current[0];
            int c = current[1];
            lake.add(r, c);

            if (r == 0 || r == rows - 1 || c == 0 || c == cols - 1) {
                touchesBoundary = true;
            }

            for (int d = 0; d < 4; d++) {
                int nr = r + DX[d];
                int nc = c + DY[d];
                if (isValid(nr, nc) && grid[nr][nc] == '.') {
                    grid[nr][nc] = 'X';
                    stack.push(new int[]{nr, nc});
                }
            }
        }
        return touchesBoundary;
    }

    private boolean isValid(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols && grid[r][c] == '.';
    }

    private int removeSmallestLakes(List<Lake> lakes) {
        Collections.sort(lakes);
        int lakesToRemove = Math.max(0, lakes.size() - k);
        int removedCount = 0;

        for (int i = 0; i < lakesToRemove; i++) {
            Lake lake = lakes.get(i);
            for (Coordinate coord : lake.getCoordinates()) {
                grid[coord.row][coord.col] = '#'; // Mark removed cells
                removedCount++;
            }
        }
        return removedCount;
    }

    private void printResult(int removedCount) throws IOException {
        PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out));
        out.println(removedCount);

        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                char cell = grid[i][j];
                out.print(cell == 'X' ? '.' : cell);
            }
            out.println();
        }
        out.flush();
    }

    /** Represents a connected component of '.' cells */
    static class Lake implements Comparable<Lake> {
        private final List<Coordinate> coordinates = new ArrayList<>();

        void add(int row, int col) {
            coordinates.add(new Coordinate(row, col));
        }

        List<Coordinate> getCoordinates() {
            return coordinates;
        }

        @Override
        public int compareTo(Lake other) {
            return Integer.compare(this.coordinates.size(), other.coordinates.size());
        }
    }

    /** Immutable coordinate holder */
    static class Coordinate {
        final int row;
        final int col;

        Coordinate(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }
}

import java.io.*;
import java.util.*;

public class D723 {

    // Instance state to avoid problematic static globals
    private int n, m, k;
    private char[][] grid;
    private boolean[][] visited;
    private int[][] componentId;
    private List<Set<Coordinate>> componentCells;
    private FastReader reader;
    private PrintWriter writer;

    public static void main(String[] args) {
        // Proper resource management with try-with-resources
        try (FastReader reader = new FastReader(System.in);
             PrintWriter writer = new PrintWriter(new BufferedOutputStream(System.out))) {
            new D723(reader, writer).solve();
        }
    }

    public D723(FastReader reader, PrintWriter writer) {
        this.reader = reader;
        this.writer = writer;
    }

    public void solve() {
        n = reader.nextInt();
        m = reader.nextInt();
        k = reader.nextInt();

        // Dynamically allocate based on actual input size
        grid = new char[n + 1][m + 1];
        visited = new boolean[n + 1][m + 1];
        componentId = new int[n + 1][m + 1];

        // Read grid data
        for (int i = 1; i <= n; i++) {
            String line = reader.next();
            for (int j = 1; j <= m; j++) {
                grid[i][j] = line.charAt(j - 1);
            }
        }

        // Identify connected components using iterative BFS
        int componentCount = 0;
        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= m; j++) {
                if (grid[i][j] == '.' && !visited[i][j]) {
                    componentCount++;
                    bfs(i, j, componentCount);
                }
            }
        }

        // Group cells by their component ID
        componentCells = new ArrayList<>(componentCount + 1);
        for (int i = 0; i <= componentCount; i++) {
            componentCells.add(new HashSet<>());
        }
        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= m; j++) {
                if (grid[i][j] == '.') {
                    componentCells.get(componentId[i][j]).add(new Coordinate(i, j));
                }
            }
        }

        // Identify components that touch the border
        Set<Integer> borderComponentIds = new HashSet<>();
        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= m; j++) {
                if (grid[i][j] == '.' && isBorder(i, j)) {
                    borderComponentIds.add(componentId[i][j]);
                }
            }
        }

        int nonBorderCount = componentCount - borderComponentIds.size();
        int removedCellsCount = 0;

        // Remove smallest non-border components until count <= k
        while (nonBorderCount > k) {
            int targetId = -1;
            int minSize = Integer.MAX_VALUE;

            for (int id = 1; id <= componentCount; id++) {
                if (borderComponentIds.contains(id)) continue;

                Set<Coordinate> cells = componentCells.get(id);
                if (!cells.isEmpty() && cells.size() < minSize) {
                    minSize = cells.size();
                    targetId = id;
                }
            }

            if (targetId == -1) break; // Safety check; should not be reached if logic is sound

            // Mark component cells as blocked
            for (Coordinate coord : componentCells.get(targetId)) {
                grid[coord.r][coord.c] = '*';
            }
            componentCells.get(targetId).clear(); // Free memory/logic

            removedCellsCount += minSize;
            nonBorderCount--;
        }

        // Output results
        writer.println(removedCellsCount);
        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= m; j++) {
                writer.print(grid[i][j]);
            }
            writer.println();
        }
        writer.flush();
    }

    /**
     * Iterative BFS to find connected components.
     * Replaces recursive DFS to prevent StackOverflowError on larger inputs.
     */
    private void bfs(int startR, int startC, int id) {
        Queue<Coordinate> queue = new ArrayDeque<>();
        queue.add(new Coordinate(startR, startC));
        visited[startR][startC] = true;
        componentId[startR][startC] = id;

        int[] dr = {-1, 1, 0, 0};
        int[] dc = {0, 0, -1, 1};

        while (!queue.isEmpty()) {
            Coordinate curr = queue.poll();
            for (int d = 0; d < 4; d++) {
                int nr = curr.r + dr[d];
                int nc = curr.c + dc[d];
                if (isValid(nr, nc) && grid[nr][nc] == '.' && !visited[nr][nc]) {
                    visited[nr][nc] = true;
                    componentId[nr][nc] = id;
                    queue.add(new Coordinate(nr, nc));
                }
            }
        }
    }

    private boolean isValid(int r, int c) {
        return r >= 1 && r <= n && c >= 1 && c <= m;
    }

    private boolean isBorder(int r, int c) {
        return r == 1 || r == n || c == 1 || c == m;
    }

    /**
     * Immutable coordinate class with proper equals/hashCode for HashSet compatibility.
     */
    private static class Coordinate {
        final int r, c;

        Coordinate(int r, int c) {
            this.r = r;
            this.c = c;
        }

        @Override
        public boolean equals(Object o) {
            if (this == o) return true;
            if (!(o instanceof Coordinate)) return false;
            Coordinate that = (Coordinate) o;
            return r == that.r && c == that.c;
        }

        @Override
        public int hashCode() {
            return 31 * r + c;
        }

        @Override
        public String toString() {
            return r + " " + c;
        }
    }

    /**
     * Optimized FastReader for competitive programming / large I/O.
     */
    static class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastReader(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        public String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) throw new IOException("Unexpected end of input");
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input", e);
                }
            }
            return st.nextToken();
        }

        public String nextLine() {
            try {
                return br.readLine();
            } catch (IOException e) {
                throw new RuntimeException("Failed to read line", e);
            }
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }

        public double nextDouble() {
            return Double.parseDouble(next());
        }
    }
}

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Scanner;

/**
 * Solves a grid-based problem by identifying connected components of empty cells,
 * sorting them by size, and filling the selected components with obstacles.
 */
public class Main {
    private final int n, m;
    private char[][] grid;
    private boolean[][] visited;

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            if (!scanner.hasNextInt()) {
                return;
            }
            int n = scanner.nextInt();
            int m = scanner.nextInt();
            int k = scanner.nextInt();
            scanner.nextLine(); // Consume the remaining newline character

            Main solver = new Main(n, m);
            solver.readGrid(scanner);
            solver.process(k);
        }
    }

    public Main(int n, int m) {
        this.n = n;
        this.m = m;
        this.grid = new char[n][m];
        this.visited = new boolean[n][m];
    }

    /**
     * Reads the grid from standard input.
     */
    private void readGrid(Scanner scanner) {
        for (int i = 0; i < n; i++) {
            String line = scanner.nextLine().trim();
            grid[i] = line.toCharArray();
        }
    }

    /**
     * Orchestrates the component detection, sorting, and filling process.
     */
    private void process(int k) {
        List<Component> components = new ArrayList<>();

        // Identify all connected components of '.' cells
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == '.' && !visited[i][j]) {
                    int size = countConnectedCells(i, j);
                    if (size > 0) {
                        components.add(new Component(size, i, j));
                    }
                }
            }
        }

        // Sort components by size in ascending order
        Collections.sort(components);

        // Determine how many components to fill (keep the largest ones)
        int componentsToFill = Math.max(0, components.size() - k);
        int totalFilledCells = 0;

        // Reset visited array for the filling phase
        visited = new boolean[n][m];

        // Fill the selected components
        for (int i = 0; i < componentsToFill; i++) {
            Component comp = components.get(i);
            totalFilledCells += comp.size;
            fillConnectedCells(comp.row, comp.col);
        }

        // Output results
        System.out.println(totalFilledCells);
        for (int i = 0; i < n; i++) {
            System.out.println(new String(grid[i]));
        }
    }

    /**
     * Recursively counts the size of a connected component starting at (i, j).
     * Marks visited cells to prevent double-counting.
     */
    private int countConnectedCells(int i, int j) {
        if (i < 0 || i >= n || j < 0 || j >= m || grid[i][j] == '*' || visited[i][j]) {
            return 0;
        }
        visited[i][j] = true;
        return 1 + countConnectedCells(i + 1, j)
                 + countConnectedCells(i - 1, j)
                 + countConnectedCells(i, j + 1)
                 + countConnectedCells(i, j - 1);
    }

    /**
     * Recursively fills a connected component of '.' cells with '*' obstacles.
     */
    private void fillConnectedCells(int i, int j) {
        if (i < 0 || i >= n || j < 0 || j >= m || grid[i][j] == '*' || visited[i][j]) {
            return;
        }
        visited[i][j] = true;
        grid[i][j] = '*';
        fillConnectedCells(i + 1, j);
        fillConnectedCells(i - 1, j);
        fillConnectedCells(i, j + 1);
        fillConnectedCells(i, j - 1);
    }

    /**
     * Represents a connected component of empty cells.
     */
    private static class Component implements Comparable<Component> {
        final int size;
        final int row;
        final int col;

        public Component(int size, int row, int col) {
            this.size = size;
            this.row = row;
            this.col = col;
        }

        @Override
        public int compareTo(Component other) {
            return Integer.compare(this.size, other.size);
        }
    }
}

import java.util.ArrayList;
import java.util.ArrayDeque;
import java.util.Collections;
import java.util.Comparator;
import java.util.List;
import java.util.Queue;
import java.util.Scanner;

public class Main {

    // Direction vectors for moving up, left, right, down
    private static final int[] DX = {-1, 0, 0, 1};
    private static final int[] DY = {0, -1, 1, 0};

    public static void main(String[] args) {
        // Use try-with-resources for automatic resource management
        try (Scanner scanner = new Scanner(System.in)) {
            if (!scanner.hasNextInt()) return;

            int n = scanner.nextInt();
            int m = scanner.nextInt();
            int k = scanner.nextInt();

            char[][] map = new char[n][m];
            // Working copy for traversal to mark visited cells without affecting the output map immediately
            char[][] scanMap = new char[n][m];

            for (int i = 0; i < n; i++) {
                String row = scanner.next();
                // Initialize rows. We assume the input string length matches m.
                // Using toCharArray creates a new array instance for each row.
                map[i] = row.toCharArray();
                scanMap[i] = row.toCharArray();
            }

            List<Lake> lakes = new ArrayList<>();

            // Identify all connected components (lakes)
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    // If we find an unvisited water cell
                    if (scanMap[i][j] == '.') {
                        Lake lake = findLake(scanMap, i, j, n, m);
                        // Only add enclosed lakes to the list (lakes that do not touch the boundary)
                        if (lake.isEnclosed) {
                            lakes.add(lake);
                        }
                    }
                }
            }

            // Sort lakes by size (ascending)
            Collections.sort(lakes, Comparator.comparingInt(lake -> lake.points.size()));

            // Calculate how many smallest lakes to remove.
            // Logic from original code: remove (total - k) lakes. 
            // This implies keeping the k largest lakes.
            int lakesToRemove = lakes.size() - k;
            if (lakesToRemove < 0) {
                lakesToRemove = 0;
            }

            int totalRemovedWater = 0;
            for (int i = 0; i < lakesToRemove; i++) {
                Lake lake = lakes.get(i);
                totalRemovedWater += lake.points.size();
                // Fill the lake with '*' in the output map
                for (Point point : lake.points) {
                    map[point.x][point.y] = '*';
                }
            }

            // Output results
            System.out.println(totalRemovedWater);
            StringBuilder sb = new StringBuilder();
            for (int i = 0; i < n; i++) {
                sb.append(map[i]);
                sb.append('\n');
            }
            System.out.print(sb);

        } catch (Exception e) {
            // In a production environment, proper logging should be used.
            // e.printStackTrace();
        }
    }

    /**
     * Finds a connected component of water ('.') starting from (startX, startY).
     * Marks visited cells in scanMap as '*' to prevent re-processing.
     * Returns a Lake object containing the points and whether it touches the boundary.
     * Uses BFS (Iterative) to avoid StackOverflowError on large grids.
     */
    private static Lake findLake(char[][] scanMap, int startX, int startY, int n, int m) {
        List<Point> points = new ArrayList<>();
        boolean isEnclosed = true;

        // Use a Queue for BFS
        Queue<Point> bfsQueue = new ArrayDeque<>();

        bfsQueue.add(new Point(startX, startY));
        scanMap[startX][startY] = '*'; // Mark as visited
        points.add(new Point(startX, startY));

        while (!bfsQueue.isEmpty()) {
            Point current = bfsQueue.poll();

            // Check if current point is on the boundary
            // If any part of the lake touches the boundary, it is not an enclosed lake
            if (current.x == 0 || current.x == n - 1 || current.y == 0 || current.y == m - 1) {
                isEnclosed = false;
            }

            // Explore neighbors
            for (int i = 0; i < DX.length; i++) {
                int nx = current.x + DX[i];
                int ny = current.y + DY[i];

                // Check bounds and if it is unvisited water
                if (nx >= 0 && nx < n && ny >= 0 && ny < m && scanMap[nx][ny] == '.') {
                    scanMap[nx][ny] = '*'; // Mark as visited
                    Point neighbor = new Point(nx, ny);
                    bfsQueue.add(neighbor);
                    points.add(neighbor);
                }
            }
        }

        return new Lake(points, isEnclosed);
    }

    // Inner class to represent a coordinate
    private static class Point {
        int x, y;

        public Point(int x, int y) {
            this.x = x;
            this.y = y;
        }
    }

    // Inner class to represent a Lake
    private static class Lake {
        List<Point> points;
        boolean isEnclosed;

        public Lake(List<Point> points, boolean isEnclosed) {
            this.points = points;
            this.isEnclosed = isEnclosed;
        }
    }
}

import java.util.*;

public class BerlandLakes {
    private static final int[] DX = {0, 0, 1, -1};
    private static final int[] DY = {1, -1, 0, 0};

    /** Represents a connected water component */
    private static class Component {
