        }

        int n = scanner.nextInt();
        int m = scanner.nextInt();
        int k = scanner.nextInt();

        char[][] grid = new char[n][m];
        for (int i = 0; i < n; i++) {
            grid[i] = scanner.next().toCharArray();
        }
        scanner.close();

        // Identify and isolate internal water components
        List<Component> components = findComponents(grid);

        // Sort by size to easily pick the smallest ones for filling
        components.sort(Comparator.comparingInt(c -> c.size));

        int toFill = Math.max(0, components.size() - k);
        int filledArea = 0;
        for (int i = 0; i < toFill; i++) {
            filledArea += components.get(i).size;
        }

        // Apply changes to the grid
        for (int i = 0; i < toFill; i++) {
            dfsFill(grid, components.get(i).r, components.get(i).c);
        }

        // Output results
        System.out.println(filledArea);
        printGrid(grid);
    }

    /**
     * Finds all connected water components that do NOT touch the grid boundary.
     * Boundary-connected water is marked as visited and discarded.
     */
    private static List<Component> findComponents(char[][] grid) {
        int n = grid.length;
        int m = grid[0].length;
        boolean[][] visited = new boolean[n][m];
        List<Component> components = new ArrayList<>();

        // Step 1: Remove water connected to the boundary
        for (int i = 0; i < n; i++) {
            if (grid[i][0] == '.' && !visited[i][0]) dfsCount(grid, i, 0, visited);
            if (grid[i][m - 1] == '.' && !visited[i][m - 1]) dfsCount(grid, i, m - 1, visited);
        }
        for (int j = 0; j < m; j++) {
            if (grid[0][j] == '.' && !visited[0][j]) dfsCount(grid, 0, j, visited);
            if (grid[n - 1][j] == '.' && !visited[n - 1][j]) dfsCount(grid, n - 1, j, visited);
        }

        // Step 2: Collect remaining isolated components
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == '.' && !visited[i][j]) {
                    int size = dfsCount(grid, i, j, visited);
                    components.add(new Component(size, i, j));
                }
            }
        }
        return components;
    }

    /**
     * Iteratively counts the size of a water component and marks visited cells.
     */
    private static int dfsCount(char[][] grid, int r, int c, boolean[][] visited) {
        int size = 0;
        Deque<int[]> stack = new ArrayDeque<>();
        stack.push(new int[]{r, c});
        visited[r][c] = true;

        while (!stack.isEmpty()) {
            int[] curr = stack.pop();
            size++;
            for (int i = 0; i < 4; i++) {
                int nr = curr[0] + DX[i];
                int nc = curr[1] + DY[i];
                if (isValid(nr, nc, grid) && grid[nr][nc] == '.' && !visited[nr][nc]) {
                    visited[nr][nc] = true;
                    stack.push(new int[]{nr, nc});
                }
            }
        }
        return size;
    }

    /**
     * Fills a water component with land ('*') using iterative DFS.
     */
    private static void dfsFill(char[][] grid, int r, int c) {
        Deque<int[]> stack = new ArrayDeque<>();
        stack.push(new int[]{r, c});
        grid[r][c] = '*';

        while (!stack.isEmpty()) {
            int[] curr = stack.pop();
            for (int i = 0; i < 4; i++) {
                int nr = curr[0] + DX[i];
                int nc = curr[1] + DY[i];
                if (isValid(nr, nc, grid) && grid[nr][nc] == '.') {
                    grid[nr][nc] = '*';
                    stack.push(new int[]{nr, nc});
                }
            }
        }
    }

    private static boolean isValid(int r, int c, char[][] grid) {
        return r >= 0 && r < grid.length && c >= 0 && c < grid[0].length;
    }

    private static void printGrid(char[][] grid) {
        for (char[] row : grid) {
            System.out.println(new String(row));
        }
    }
}

import java.io.*;
import java.util.*;

public class CO_734D {
    public static void main(String[] args) {
        FastScanner in = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out);

        // The original problem specifies a single test case, but the loop structure is preserved for extensibility.
        int testCases = 1;
        while (testCases-- > 0) {
            solve(in, out);
        }

        out.flush();
    }

    private static void solve(FastScanner in, PrintWriter out) {
        int n = in.nextInt();
        int kingX = in.nextInt();
        int kingY = in.nextInt();

        // Arrays to store the closest piece in each of the 8 directions
        // 0: Up, 1: Down, 2: Left, 3: Right, 4: Top-Left, 5: Top-Right, 6: Bottom-Left, 7: Bottom-Right
        Piece[] closestPieces = new Piece[8];
        int[] minDistances = new int[8];
        Arrays.fill(minDistances, Integer.MAX_VALUE);

        for (int i = 0; i < n; i++) {
            String typeStr = in.next();
            char type = typeStr.charAt(0);
            // Coordinates relative to the king
            int px = in.nextInt() - kingX;
            int py = in.nextInt() - kingY;

            int direction = getDirection(px, py);
            if (direction != -1) {
                // Manhattan distance for orthogonal, absolute x for diagonal
                int distance = (direction < 4) ? Math.max(Math.abs(px), Math.abs(py)) : Math.abs(px);
                if (distance < minDistances[direction]) {
                    minDistances[direction] = distance;
                    closestPieces[direction] = new Piece(type, px, py, i);
                }
            }
        }

        // Check if any closest piece can attack the king
        boolean attacked = false;
        for (int d = 0; d < 8; d++) {
            if (closestPieces[d] != null && canAttack(closestPieces[d], d)) {
                attacked = true;
                break;
            }
        }

        out.println(attacked ? "YES" : "NO");
    }

    /**
     * Determines the direction of a piece relative to the king.
     * Returns -1 if the piece is not aligned in any of the 8 attack directions.
     */
    private static int getDirection(int dx, int dy) {
        if (dx == 0 && dy > 0) return 0;
        if (dx == 0 && dy < 0) return 1;
        if (dx < 0 && dy == 0) return 2;
        if (dx > 0 && dy == 0) return 3;
        if (dx < 0 && dy > 0 && Math.abs(dx) == Math.abs(dy)) return 4;
        if (dx > 0 && dy > 0 && Math.abs(dx) == Math.abs(dy)) return 5;
        if (dx < 0 && dy < 0 && Math.abs(dx) == Math.abs(dy)) return 6;
        if (dx > 0 && dy < 0 && Math.abs(dx) == Math.abs(dy)) return 7;
        return -1;
    }

    /**
     * Checks if a piece can attack the king based on its type and relative direction.
     * Pieces block each other, so only the closest piece in a direction matters.
     */
    private static boolean canAttack(Piece piece, int direction) {
        boolean isOrthogonal = direction < 4;
        boolean isDiagonal = direction >= 4;
        char type = piece.type;

        // Rooks and Queens attack orthogonally
        if (isOrthogonal && (type == 'R' || type == 'Q')) return true;
        // Bishops and Queens attack diagonally
        if (isDiagonal && (type == 'B' || type == 'Q')) return true;
        return false;
    }

    /** Represents a chess piece with its type and relative position */
    private static class Piece {
        char type;
        int x, y, id;

        Piece(char type, int x, int y, int id) {
            this.type = type;
            this.x = x;
            this.y = y;
            this.id = id;
        }
    }

    /** Fast I/O helper class */
    private static class FastScanner {
        BufferedReader br;
        StringTokenizer st;

        public FastScanner(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.HashMap;
import java.util.Map;
import java.util.StringTokenizer;

public class AntonAndChess {

    /**
     * Enum representing the 8 directions relative to the King.
     */
    enum Direction {
        NORTH, NORTH_EAST, EAST, SOUTH_EAST,
        SOUTH, SOUTH_WEST, WEST, NORTH_WEST;

        public boolean isOrthogonal() {
            return this == NORTH || this == SOUTH || this == EAST || this == WEST;
        }

        public boolean isDiagonal() {
            return this == NORTH_EAST || this == SOUTH_EAST ||
                   this == SOUTH_WEST || this == NORTH_WEST;
        }
    }

    /**
     * Helper class to store piece information.
     */
    private static class Piece {
        char type;
        int x, y;

        Piece(char type, int x, int y) {
            this.type = type;
            this.x = x;
            this.y = y;
        }
    }

    public static void main(String[] args) throws IOException {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer tokenizer;

        // Read number of pieces
        String line = reader.readLine();
        if (line == null) return;
        int n = Integer.parseInt(line.trim());

        // Read King's position
        line = reader.readLine();
        if (line == null) return;
        tokenizer = new StringTokenizer(line);
        int xK = Integer.parseInt(tokenizer.nextToken());
        int yK = Integer.parseInt(tokenizer.nextToken());

        // Map to store the closest piece in each of the 8 directions
        Map<Direction, Piece> closestPieces = new HashMap<>();
        for (Direction d : Direction.values()) {
            closestPieces.put(d, null);
        }

        // Process each piece
        for (int i = 0; i < n; i++) {
            line = reader.readLine();
            if (line == null) break;
            tokenizer = new StringTokenizer(line);

            char pC = tokenizer.nextToken().charAt(0);
            int xC = Integer.parseInt(tokenizer.nextToken());
            int yC = Integer.parseInt(tokenizer.nextToken());

            Direction dir = getDirection(xK, yK, xC, yC);

            if (dir != null) {
                Piece existing = closestPieces.get(dir);
                // Update if no piece exists yet or if current piece is strictly closer
                if (existing == null || isCloser(xK, yK, xC, yC, existing.x, existing.y)) {
                    closestPieces.put(dir, new Piece(pC, xC, yC));
                }
            }
        }

        // Check if any closest piece attacks the King
        boolean isCheck = false;
        for (Direction dir : Direction.values()) {
            Piece piece = closestPieces.get(dir);
            if (piece != null && attacksKing(dir, piece.type)) {
                isCheck = true;
                break;
            }
        }

        System.out.println(isCheck ? "YES" : "NO");
    }

    /**
     * Determines the direction from the King to the Piece.
     * Returns null if the piece is not aligned in any of the 8 cardinal/ordinal directions.
     */
    private static Direction getDirection(int kx, int ky, int px, int py) {
        int dx = px - kx;
        int dy = py - ky;

        // Orthogonal directions
        if (dx == 0 && dy > 0) return Direction.NORTH;
        if (dx == 0 && dy < 0) return Direction.SOUTH;
        if (dy == 0 && dx > 0) return Direction.EAST;
        if (dy == 0 && dx < 0) return Direction.WEST;

        // Diagonal directions
        if (Math.abs(dx) == Math.abs(dy)) {
            if (dx > 0 && dy > 0) return Direction.NORTH_EAST;
            if (dx > 0 && dy < 0) return Direction.SOUTH_EAST;
            if (dx < 0 && dy < 0) return Direction.SOUTH_WEST;
            if (dx < 0 && dy > 0) return Direction.NORTH_WEST;
        }

        return null; // Not aligned
    }

    /**
     * Checks if the piece attacks the King based on its type and relative direction.
     */
    private static boolean attacksKing(Direction dir, char pieceType) {
        if (pieceType == 'Q') return true; // Queen attacks in all directions
        if (pieceType == 'R') return dir.isOrthogonal(); // Rook attacks orthogonal
        if (pieceType == 'B') return dir.isDiagonal();   // Bishop attacks diagonal
        return false;
    }

    /**
     * Checks if the new piece is closer to the King than the existing one.
     * Uses squared distance to avoid floating point operations.
     */
    private static boolean isCloser(int kx, int ky, int nx, int ny, int ox, int oy) {
        int newDistSq = (nx - kx) * (nx - kx) + (ny - ky) * (ny - ky);
        int oldDistSq = (ox - kx) * (ox - kx) + (oy - ky) * (oy - ky);
        return newDistSq < oldDistSq;
    }
}

import java.util.Scanner;

public class D {

    /**
     * Represents the 8 cardinal and intercardinal directions relative to the target.
     * Each direction specifies which piece types can attack along it.
     */
    private enum Direction {
        UP("RQ"),
        UP_RIGHT("BQ"),
        RIGHT("RQ"),
        DOWN_RIGHT("BQ"),
        DOWN("RQ"),
        DOWN_LEFT("BQ"),
        LEFT("RQ"),
        UP_LEFT("BQ");

        private final String allowedTypes;

        Direction(String allowedTypes) {
            this.allowedTypes = allowedTypes;
        }

        public boolean canAttack(char pieceType) {
            return allowedTypes.indexOf(pieceType) != -1;
        }
    }

    /**
     * Represents a chess piece with its type and distance to the target.
     */
    private static class Piece {
        private final char type;
        private final long distance;

        Piece(char type, long distance) {
            this.type = type;
            this.distance = distance;
        }
    }

    public static void main(String[] args) {
        // Use try-with-resources to ensure Scanner is properly closed
        try (Scanner sc = new Scanner(System.in)) {
            if (!sc.hasNextLong()) return;

            long n = sc.nextLong();
            long x0 = sc.nextLong();
            long y0 = sc.nextLong();

            // Array to store the closest piece for each of the 8 directions
            Piece[] closestPieces = new Piece[Direction.values().length];

            for (int i = 0; i < n; i++) {
                char type = sc.next().charAt(0);
                long x = sc.nextLong();
                long y = sc.nextLong();

                long dx = x - x0;
                long dy = y - y0;

                Direction dir = resolveDirection(dx, dy);
                if (dir != null) {
                    // For aligned pieces, |dx| equals the Chebyshev distance to the target
                    long dist = Math.abs(dx);
                    int idx = dir.ordinal();

                    // Keep track of the closest piece in this direction
                    if (closestPieces[idx] == null || dist < closestPieces[idx].distance) {
                        closestPieces[idx] = new Piece(type, dist);
                    }
                }
            }

            boolean canAttack = false;
            for (Direction dir : Direction.values()) {
                Piece best = closestPieces[dir.ordinal()];
                if (best != null && dir.canAttack(best.type)) {
                    canAttack = true;
                    break;
                }
            }

            System.out.println(canAttack ? "YES" : "NO");
        }
    }

    /**
     * Determines which of the 8 directions a piece lies in relative to the target.
     * Returns null if the piece does not align with any attack vector.
     */
    private static Direction resolveDirection(long dx, long dy) {
        if (dx == 0 && dy > 0) return Direction.UP;
        if (dx > 0 && dy > 0 && dx == dy) return Direction.UP_RIGHT;
        if (dx > 0 && dy == 0) return Direction.RIGHT;
        if (dx > 0 && dy < 0 && dx == -dy) return Direction.DOWN_RIGHT;
        if (dx == 0 && dy < 0) return Direction.DOWN;
        if (dx < 0 && dy < 0 && dx == dy) return Direction.DOWN_LEFT;
        if (dx < 0 && dy == 0) return Direction.LEFT;
        if (dx < 0 && dy > 0 && dx == -dy) return Direction.UP_LEFT;
        return null;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.OutputStream;
import java.io.PrintWriter;
import java.util.StringTokenizer;

public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        FastScanner in = new FastScanner(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        TaskD solver = new TaskD();
        solver.solve(in, out);
        out.close();
    }

    static class TaskD {
        public void solve(FastScanner in, PrintWriter out) {
            int n = in.nextInt();
            int x0 = in.nextInt();
            int y0 = in.nextInt();

            char[] pieceTypes = new char[n];
            int[] pieceX = new int[n];
            int[] pieceY = new int[n];

            for (int i = 0; i < n; i++) {
                pieceTypes[i] = in.next().charAt(0);
                pieceX[i] = in.nextInt();
                pieceY[i] = in.nextInt();
            }

            // Direction vectors for: Right, Up-Right, Up, Up-Left, Left, Down-Left, Down, Down-Right
            // Corresponds to original indices 0 through 7
            int[] dx = {1, 1, 0, -1, -1, -1, 0, 1};
            int[] dy = {0, 1, 1, 1, 0, -1, -1, -1};

            for (int d = 0; d < 8; d++) {
                int minDist = Integer.MAX_VALUE;
                char closestPiece = 0;

                for (int i = 0; i < n; i++) {
                    int diffX = pieceX[i] - x0;
                    int diffY = pieceY[i] - y0;

                    // Check if the piece lies exactly in the current direction:
                    // 1. Must be in the correct quadrant (diffX and diffY share the sign of dx/dy)
                    // 2. Must be collinear (slope matches the direction vector)
                    if (diffX * dx[d] > 0 && diffY * dy[d] > 0 && diffX * dy[d] == diffY * dx[d]) {
                        int dist = Math.abs(diffX);
                        if (dist < minDist) {
                            minDist = dist;
                            closestPiece = pieceTypes[i];
                        }
                    }
                }

                if (closestPiece != 0) {
                    boolean isOrthogonal = (dx[d] * dy[d] == 0);
                    boolean canAttack = (closestPiece == 'Q') ||
                                        (closestPiece == 'R' && isOrthogonal) ||
                                        (closestPiece == 'B' && !isOrthogonal);

                    if (canAttack) {
                        out.println("YES");
                        return;
                    }
                }
            }

            out.println("NO");
        }
    }

    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        public String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) {
                        return null;
                    }
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            String s = next();
            if (s == null) throw new RuntimeException("Unexpected end of input");
            return Integer.parseInt(s);
        }
    }
}

import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.InputMismatchException;

public class Main {
    // Constants
    private static final long INF = 1_000_000_000_000L;

    // Direction indices: 0=Left, 1=Right, 2=Down, 3=Up
    private static final int DIR_LEFT = 0;
    private static final int DIR_RIGHT = 1;
    private static final int DIR_DOWN = 2;
    private static final int DIR_UP = 3;

    public static void main(String[] args) {
        InputReader in = new InputReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        int n = in.nextInt();
        long x0 = in.nextInt();
        long y0 = in.nextInt();

        char[] pieceTypes = new char[n];
        long[] xs = new long[n];
        long[] ys = new long[n];

        for (int i = 0; i < n; i++) {
            pieceTypes[i] = in.next().charAt(0);
            xs[i] = in.nextInt();
            ys[i] = in.nextInt();
        }

        boolean canReach = false;

        // The algorithm checks two coordinate systems:
        // 1. Original (rep=0)
        // 2. Rotated by 45 degrees and scaled (rep=1)
        // Transformation: x' = x + y, y' = x - y
        for (int rep = 0; rep < 2; rep++) {
            if (checkClosestPieces(n, pieceTypes, xs, ys, x0, y0, rep)) {
                canReach = true;
                break;
            }

            // Update query point for next rotation
            long nextX0 = x0 + y0;
            long nextY0 = x0 - y0;
            x0 = nextX0;
            y0 = nextY0;

            // Update all board points for next rotation
            for (int i = 0; i < n; i++) {
                long nextX = xs[i] + ys[i];
                long nextY = xs[i] - ys[i];
                xs[i] = nextX;
                ys[i] = nextY;
            }
        }

        out.println(canReach ? "YES" : "NO");
        out.flush();
    }

    /**
     * Checks if the closest piece in any of the 4 cardinal directions
     * matches the required type for the current rotation.
     *
     * @param n     Number of pieces
     * @param types Character types of each piece
     * @param xs    X-coordinates of each piece
     * @param ys    Y-coordinates of each piece
     * @param x0    Query X-coordinate
     * @param y0    Query Y-coordinate
     * @param rep   Current rotation iteration (0 or 1)
     * @return true if a matching piece is found in any direction
     */
    private static boolean checkClosestPieces(int n, char[] types, long[] xs, long[] ys,
                                              long x0, long y0, int rep) {
        char[] closestChars = new char[]{' ', ' ', ' ', ' '};
        // 0:L (max), 1:R (min), 2:D (max), 3:U (min)
        long[] minMax = new long[]{-INF, INF, -INF, INF};

        for (int i = 0; i < n; i++) {
            int dir = -1;
            long value = -1;

            // Determine direction relative to (x0, y0)
            if (xs[i] == x0) {
                value = ys[i];
                dir = (ys[i] < y0) ? DIR_DOWN : DIR_UP;
            } else if (ys[i] == y0) {
                value = xs[i];
                dir = (xs[i] < x0) ? DIR_LEFT : DIR_RIGHT;
            }

            if (dir == -1) continue;

            // Even dirs (Left, Down): find maximum value (closest to x0/y0)
            // Odd dirs (Right, Up): find minimum value
            if (dir % 2 == 0) {
                if (minMax[dir] < value) {
                    minMax[dir] = value;
                    closestChars[dir] = types[i];
                }
            } else {
                if (minMax[dir] > value) {
                    minMax[dir] = value;
                    closestChars[dir] = types[i];
                }
            }
        }

        // Check if any closest piece satisfies the condition
        for (int d = 0; d < 4; d++) {
            char piece = closestChars[d];
            if (piece == 'Q' ||
                (piece == 'R' && rep == 0) ||
                (piece == 'B' && rep == 1)) {
                return true;
            }
        }
        return false;
    }

    /**
     * Fast I/O helper class for competitive programming.
     * Removed unused methods to reduce clutter and improve maintainability.
     */
    static class InputReader {
        private final InputStream stream;
        private final byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        public int nextInt() {
            int c = read();
            while (isSpaceChar(c)) c = read();
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9') throw new InputMismatchException();
                res *= 10;
                res += c - '0';
                c = read();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public String next() {
            int c = read();
            while (isSpaceChar(c)) c = read();
            StringBuilder sb = new StringBuilder();
            do {
                sb.append((char) c);
                c = read();
            } while (!isSpaceChar(c));
            return sb.toString();
        }

        private int read() {
            if (numChars == -1) throw new InputMismatchException();
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0) return -1;
            }
            return buf[curChar++];
        }

        private boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }
    }
}

import java.io.*;
import java.util.*;

public class AntonChess {
    public static void main(String[] args) {
        FastScanner in = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out));

        try {
            String nStr = in.next();
            if (nStr == null) return;

            int n = Integer.parseInt(nStr);
            int x0 = in.nextInt();
            int y0 = in.nextInt();

            // Directions mapping (0-7):
            // 0: Top-Left    (dx<0, dy<0) -> Diagonal
            // 1: Left        (dx<0, dy=0) -> Straight
            // 2: Top-Right   (dx<0, dy>0) -> Diagonal
            // 3: Up          (dx=0, dy>0) -> Straight
            // 4: Bottom-Right(dx>0, dy>0) -> Diagonal
            // 5: Right       (dx>0, dy=0) -> Straight
            // 6: Bottom-Left (dx>0, dy<0) -> Diagonal
            // 7: Down        (dx=0, dy<0) -> Straight
            int[] minDist = new int[8];
            boolean[] canAttack = new boolean[8];
            Arrays.fill(minDist, Integer.MAX_VALUE);

            for (int i = 0; i < n; i++) {
                String type = in.next();
                int x = in.nextInt();
                int y = in.nextInt();

                int dx = x - x0;
                int dy = y - y0;

                int dir = getDirection(dx, dy);
                if (dir == -1) continue; // Not aligned horizontally, vertically, or diagonally

                // Distance is the maximum of absolute differences (works for both straight and diagonal)
                int dist = Math.max(Math.abs(dx), Math.abs(dy));

                // Only update if this piece is closer than the current closest in this direction
                if (dist < minDist[dir]) {
                    minDist[dir] = dist;
                    canAttack[dir] = canPieceAttack(type.charAt(0), dir);
                }
            }

            boolean isAttacked = false;
            for (boolean attack : canAttack) {
                if (attack) {
                    isAttacked = true;
                    break;
                }
            }

            out.println(isAttacked ? "YES" : "NO");
        } catch (Exception e) {
            // In competitive programming, input is guaranteed to be well-formed.
            // This catch block is for safety during development/testing.
            e.printStackTrace();
        } finally {
            out.flush();
            out.close();
        }
    }

    /**
     * Determines the direction index (0-7) based on relative coordinates.
     * Returns -1 if the point is not aligned with the starting position.
     */
    private static int getDirection(int dx, int dy) {
        if (dx < 0 && dy < 0) return 0;
        if (dx < 0 && dy == 0) return 1;
        if (dx < 0 && dy > 0) return 2;
        if (dx == 0 && dy > 0) return 3;
        if (dx > 0 && dy > 0) return 4;
        if (dx > 0 && dy == 0) return 5;
        if (dx > 0 && dy < 0) return 6;
        if (dx == 0 && dy < 0) return 7;
        return -1;
    }

    /**
     * Checks if a given piece type can attack along a specific direction.
     * Straight directions are odd indices (1, 3, 5, 7).
     * Diagonal directions are even indices (0, 2, 4, 6).
     */
    private static boolean canPieceAttack(char piece, int dir) {
        boolean isStraight = (dir % 2 != 0);

        if (piece == 'Q') return true; // Queen attacks both straight and diagonal
        if (isStraight && piece == 'R') return true; // Rook attacks straight
        if (!isStraight && piece == 'B') return true; // Bishop attacks diagonal

        return false;
    }

    /**
     * High-performance scanner for competitive programming inputs.
     */
    static class FastScanner {
        BufferedReader br;
        StringTokenizer st;

        public FastScanner(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            String s = next();
            if (s == null) throw new NoSuchElementException("Unexpected end of input");
            return Integer.parseInt(s);
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Solves a chess attack validation problem.
 * Given a starting square and n piece moves, determines if any piece 
 * can attack the starting square based on standard chess movement rules.
 */
public class ChessAttackSolver {

    public static void main(String[] args) {
        FastScanner sc = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out);
        new ChessAttackSolver().solve(sc, out);
        out.flush();
    }

    private void solve(FastScanner sc, PrintWriter out) {
        int n = sc.nextInt();
        int x0 = sc.nextInt();
        int y0 = sc.nextInt();

        // Directions 0-7 map to: NW, N, NE, E, SE, S, SW, W
        // Even indices (0,2,4,6) are diagonal directions (Bishop/Queen)
        // Odd indices (1,3,5,7) are orthogonal directions (Rook/Queen)
        int[] closestX = new int[8];
        int[] closestY = new int[8];
        char[] pieceTypes = new char[8];
        Arrays.fill(closestX, -1); // -1 indicates no piece found in that direction

        for (int i = 0; i < n; i++) {
            char type = sc.next().charAt(0);
            int x1 = sc.nextInt();
            int y1 = sc.nextInt();
            int dx = x1 - x0;
            int dy = y1 - y0;

            // Check if the piece lies on the same rank, file, or diagonal
            if (dx == 0 || dy == 0 || Math.abs(dx) == Math.abs(dy)) {
                int dir = getDirectionIndex(dx, dy);
                long distSq = (long) dx * dx + (long) dy * dy;

                // Keep track of the closest piece in each direction
                if (closestX[dir] == -1 || distSq < getSquaredDistance(closestX[dir], closestY[dir], x0, y0)) {
                    closestX[dir] = x1;
                    closestY[dir] = y1;
                    pieceTypes[dir] = type;
                }
            }
        }

        boolean canAttack = false;
        for (int dir = 0; dir < 8; dir++) {
            if (closestX[dir] != -1) {
                char type = pieceTypes[dir];
                boolean isOrthogonal = (dir % 2 != 0); // N, E, S, W
                boolean isDiagonal = (dir % 2 == 0);   // NW, NE, SE, SW

                // Queen attacks in all directions. Rook attacks orthogonally. Bishop attacks diagonally.
                if (type == 'Q' || (isOrthogonal && type == 'R') || (isDiagonal && type == 'B')) {
                    canAttack = true;
                    break;
                }
            }
        }

        out.println(canAttack ? "YES" : "NO");
    }

    /**
     * Maps dx/dy to a direction index 0-7:
     * 0:NW, 1:N, 2:NE, 3:E, 4:SE, 5:S, 6:SW, 7:W
     */
    private int getDirectionIndex(int dx, int dy) {
        if (dx == 0) return dy > 0 ? 1 : 5; // N, S
        if (dy == 0) return dx > 0 ? 3 : 7; // E, W
        if (dy > 0) return dx > 0 ? 2 : 0;  // NE, NW
        return dx > 0 ? 4 : 6;              // SE, SW
    }

    /**
     * Calculates squared Euclidean distance to avoid floating-point operations.
     */
    private long getSquaredDistance(int x1, int y1, int x0, int y0) {
        int dx = x1 - x0;
        int dy = y1 - y0;
        return (long) dx * dx + (long) dy * dy;
    }

    /**
     * Fast I/O helper for competitive programming environments.
     */
    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in), 32768);
        }

        public String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

