public class D_AntonAndChess {

    // Constants for grid indices to represent the 3x3 area around the King.
    // Rows: 0 = North, 1 = Center, 2 = South
    // Cols: 0 = West, 1 = Center, 2 = East
    // This mapping aligns with the original code's logic (N=0, S=2, W=0, E=2, C=1).
    private static final int NORTH = 0;
    private static final int CENTER = 1;
    private static final int SOUTH = 2;
    private static final int WEST = 0;
    private static final int EAST = 2;

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        // Read the number of pieces
        if (!scanner.hasNextInt()) {
            return;
        }
        int n = scanner.nextInt();

        // Read the King's coordinates
        long kingX = scanner.nextLong();
        long kingY = scanner.nextLong();

        // minDist[row][col] stores the distance to the closest attacking piece
        // in the direction corresponding to that grid cell.
        // Initialized to Long.MAX_VALUE.
        long[][] minDist = new long[3][3];

        // hasTreat[row][col] indicates if the square in that direction is a valid "treat"
        // (i.e., reachable/safe according to the problem logic).
        boolean[][] hasTreat = new boolean[3][3];

        // Initialize distances to infinity
        for (int i = 0; i < 3; i++) {
            for (int j = 0; j < 3; j++) {
                minDist[i][j] = Long.MAX_VALUE;
            }
        }

        // Process each piece
        for (int i = 0; i < n; i++) {
            String typeStr = scanner.next();
            char pieceType = typeStr.charAt(0);
            long pieceX = scanner.nextLong();
            long pieceY = scanner.nextLong();

            // Calculate relative position vector (dx, dy) from King to Piece
            long dx = pieceX - kingX;
            long dy = pieceY - kingY;

            // Check if the piece attacks the King.
            // A piece attacks if it is on the same row (dx=0), same column (dy=0),
            // or same diagonal (|dx| == |dy|).
            boolean attacksKing = (dx == 0) || (dy == 0) || (Math.abs(dx) == Math.abs(dy));

            if (attacksKing) {
                // Determine the grid coordinates (row, col) for this direction.
                // X-axis mapping: West(0) -> Center(1) -> East(2)
                int col = (dx < 0) ? WEST : (dx > 0) ? EAST : CENTER;

                // Y-axis mapping: North(0) -> Center(1) -> South(2)
                // Note: We map North (higher y) to row 0 to match the original logic's orientation.
                int row = (dy > 0) ? NORTH : (dy < 0) ? SOUTH : CENTER;

                // Calculate distance.
                // For axis-aligned moves, distance is the absolute difference in the non-zero axis.
                // For diagonal moves, dx and dy have the same magnitude.
                long distance = Math.abs(dx);
                if (distance == 0) {
                    distance = Math.abs(dy);
                }

                // Update if this piece is closer than the previously recorded closest piece
                // in this specific direction.
                if (distance < minDist[row][col]) {
                    minDist[row][col] = distance;

                    // Determine if this piece makes the square a "treat".
                    // Logic preserved from original code:
                    // - Orthogonal attacks (Vertical/Horizontal): Valid if piece is NOT a Bishop.
                    //   (Bishops cannot attack orthogonally, so this effectively validates Rooks/Queens).
                    // - Diagonal attacks: Valid if piece is NOT a Rook.
                    //   (Rooks cannot attack diagonally, so this effectively validates Bishops/Queens).
                    boolean isTreat;
                    if (dx == 0 || dy == 0) {
                        // Orthogonal direction
                        isTreat = (pieceType != 'B');
                    } else {
                        // Diagonal direction
                        isTreat = (pieceType != 'R');
                    }

                    hasTreat[row][col] = isTreat;
                }
            }
        }

        // Check if any of the 8 surrounding squares is a treat.
        boolean canReachTreat = false;
        searchLoop:
        for (int i = 0; i < 3; i++) {
            for (int j = 0; j < 3; j++) {
                if (hasTreat[i][j]) {
                    canReachTreat = true;
                    break searchLoop;
                }
            }
        }

        System.out.println(canReachTreat ? "YES" : "NO");

        scanner.close();
    }
}

import java.io.*;
import java.util.*;

public class CF734D {
    // King's position on the board
    private static int kingX, kingY;

    public static void main(String[] args) {
        InputReader in = new InputReader(System.in);
        PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out));

        int n = in.nextInt();
        kingX = in.nextInt();
        kingY = in.nextInt();

        // Index 1-8 represent the 8 compass directions around the king
        List<List<Node>> piecesByDirection = new ArrayList<>(9);
        for (int i = 0; i <= 8; i++) {
            piecesByDirection.add(new ArrayList<>());
        }

        for (int i = 0; i < n; i++) {
            char type = in.next().charAt(0);
            int px = in.nextInt();
            int py = in.nextInt();

            int direction = getDirection(kingX, kingY, px, py);
            if (direction != 0) {
                piecesByDirection.get(direction).add(new Node(type, px, py));
            }
        }

        boolean canCapture = false;

        // Check orthogonal directions (1: Up, 3: Right, 5: Down, 7: Left)
        // A Rook or Queen can capture if it's the closest piece in these directions.
        for (int dir : new int[]{1, 3, 5, 7}) {
            if (!piecesByDirection.get(dir).isEmpty()) {
                Node closest = piecesByDirection.get(dir).get(0);
                if (closest.type == 'R' || closest.type == 'Q') {
                    canCapture = true;
                    break;
                }
            }
        }

        // Check diagonal directions (2: Up-Right, 4: Down-Right, 6: Down-Left, 8: Up-Left)
        // A Bishop or Queen can capture if it's the closest piece in these directions.
        if (!canCapture) {
            for (int dir : new int[]{2, 4, 6, 8}) {
                if (!piecesByDirection.get(dir).isEmpty()) {
                    Node closest = piecesByDirection.get(dir).get(0);
                    if (closest.type == 'B' || closest.type == 'Q') {
                        canCapture = true;
                        break;
                    }
                }
            }
        }

        out.println(canCapture ? "YES" : "NO");
        out.flush();
    }

    /**
     * Determines the relative direction of a piece from the king.
     * Returns 1-8 for the 8 compass directions, or 0 if not aligned.
     */
    private static int getDirection(int kx, int ky, int px, int py) {
        if (kx == px) {
            return py > ky ? 1 : 5; // Same column
        }
        if (ky == py) {
            return px > kx ? 3 : 7; // Same row
        }
        int dx = Math.abs(kx - px);
        int dy = Math.abs(ky - py);
        if (dx == dy) {
            if (px > kx && py > ky) return 2;
            if (px > kx && py < ky) return 4;
            if (px < kx && py < ky) return 6;
            return 8;
        }
        return 0; // Not in a direct line or diagonal
    }

    /**
     * Represents a chess piece on the board.
     * Implements Comparable to sort pieces by their distance from the king.
     */
    private static class Node implements Comparable<Node> {
        final char type;
        final int x, y;

        Node(char type, int x, int y) {
            this.type = type;
            this.x = x;
            this.y = y;
        }

        @Override
        public int compareTo(Node other) {
            // Use Chebyshev distance (max of dx, dy) for consistent ordering.
            // Since all pieces are aligned orthogonally or diagonally, this correctly
            // sorts them by their actual distance from the king along that line.
            int distCurrent = Math.max(Math.abs(kingX - x), Math.abs(kingY - y));
            int distOther = Math.max(Math.abs(kingX - other.x), Math.abs(kingY - other.y));
            return Integer.compare(distCurrent, distOther);
        }
    }

    /**
     * Fast input reader optimized for competitive programming.
     */
    static class InputReader {
        public BufferedReader reader;
        public StringTokenizer tokenizer;

        public InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.util.Scanner;

public class Chess {

    /**
     * Represents a chess piece with its type and coordinates.
     * Encapsulating piece data improves readability and maintainability
     * compared to storing raw strings or parallel arrays.
     */
    private static class Piece {
        char type;
        int x;
        int y;

        public Piece(char type, int x, int y) {
            this.type = type;
            this.x = x;
            this.y = y;
        }
    }

    // Direction constants mapping to the logic of the original code:
    // 0: West (x < kx, y == ky)
    // 1: East (x > kx, y == ky)
    // 2: North (x == kx, y > ky)
    // 3: South (x == kx, y < ky)
    // 4: South-West (x < kx, y < ky)
    // 5: North-West (x < kx, y > ky)
    // 6: South-East (x > kx, y < ky)
    // 7: North-East (x > kx, y > ky)
    private static final int WEST = 0;
    private static final int EAST = 1;
    private static final int NORTH = 2;
    private static final int SOUTH = 3;
    private static final int SOUTH_WEST = 4;
    private static final int NORTH_WEST = 5;
    private static final int SOUTH_EAST = 6;
    private static final int NORTH_EAST = 7;

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        // Input validation to prevent exceptions on empty input
        if (!scanner.hasNextInt()) {
            scanner.close();
            return;
        }

        int n = scanner.nextInt();
        int kingX = scanner.nextInt();
        int kingY = scanner.nextInt();

        // Array to store the closest piece found so far in each of the 8 directions.
        // Index corresponds to the direction constants defined above.
        // Initialized to null (meaning no piece found yet).
        Piece[] closestPieces = new Piece[8];

        for (int i = 0; i < n; i++) {
            String typeStr = scanner.next();
            char type = typeStr.charAt(0);
            int x = scanner.nextInt();
            int y = scanner.nextInt();

            // Determine which of the 8 directions the piece is in relative to the king
            int direction = determineDirection(x, y, kingX, kingY);

            // If the piece is aligned (orthogonally or diagonally), check if it's the closest
            if (direction != -1) {
                updateClosestPiece(closestPieces, direction, type, x, y, kingX, kingY);
            }
        }

        // Check if the king is under attack by any of the tracked closest pieces
        boolean isAttacked = checkIfAttacked(closestPieces);
        System.out.println(isAttacked ? "YES" : "NO");

        scanner.close();
    }

    /**
     * Determines the direction index (0-7) of a piece relative to the king.
     * Returns -1 if the piece is not aligned horizontally, vertically, or diagonally.
     */
    private static int determineDirection(int x, int y, int kx, int ky) {
        // Orthogonal directions
        if (x < kx && y == ky) return WEST;
        if (x > kx && y == ky) return EAST;
        if (x == kx && y > ky) return NORTH;
        if (x == kx && y < ky) return SOUTH;

        // Diagonal directions
        if (Math.abs(x - kx) == Math.abs(y - ky)) {
            if (x < kx && y < ky) return SOUTH_WEST;
            if (x < kx && y > ky) return NORTH_WEST;
            if (x > kx && y < ky) return SOUTH_EAST;
            if (x > kx && y > ky) return NORTH_EAST;
        }

        return -1;
    }

    /**
     * Updates the closest piece in a specific direction if the new piece is closer to the king.
     */
    private static void updateClosestPiece(Piece[] closestPieces, int direction, char type, int x, int y, int kx, int ky) {
        Piece existing = closestPieces[direction];

        if (existing == null) {
            // First piece found in this direction
            closestPieces[direction] = new Piece(type, x, y);
        } else {
            double distExisting = calculateDistance(existing.x, existing.y, kx, ky);
            double distNew = calculateDistance(x, y, kx, ky);

            // If the new piece is strictly closer, replace the existing one.
            // This logic preserves the original behavior of keeping the piece 
            // that blocks the line of attack (closest to the king).
            if (distNew < distExisting) {
                closestPieces[direction] = new Piece(type, x, y);
            }
        }
    }

    /**
     * Calculates the Euclidean distance between two points.
     */
    private static double calculateDistance(int x1, int y1, int x2, int y2) {
        return Math.hypot(x1 - x2, y1 - y2);
    }

    /**
     * Checks if the king is under attack by any of the tracked pieces.
     * Rooks and Queens attack orthogonally (indices 0-3).
     * Bishops and Queens attack diagonally (indices 4-7).
     */
    private static boolean checkIfAttacked(Piece[] closestPieces) {
        for (int i = 0; i < 8; i++) {
            Piece piece = closestPieces[i];
            if (piece != null) {
                boolean isOrthogonal = (i >= 0 && i <= 3);
                boolean isDiagonal = (i >= 4 && i <= 7);

                char type = piece.type;

                // Check for Rook or Queen attack in orthogonal directions
                if (isOrthogonal && (type == 'R' || type == 'Q')) {
                    return true;
                }
                // Check for Bishop or Queen attack in diagonal directions
                if (isDiagonal && (type == 'B' || type == 'Q')) {
                    return true;
                }
            }
        }
        return false;
    }
}

import java.io.BufferedReader;
