import java.util.StringTokenizer;

public class Main {
    public static void main(String[] args) throws IOException {
        // Use try-with-resources for automatic resource management
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            // Parse number of pieces
            String line = br.readLine();
            if (line == null) return;
            int n = Integer.parseInt(line.trim());

            // Parse starting position
            StringTokenizer st = new StringTokenizer(br.readLine());
            int startRow = Integer.parseInt(st.nextToken());
            int startCol = Integer.parseInt(st.nextToken());

            // Track the closest piece in each of the 8 directions.
            // Indices 0-3: Diagonals (TL, TR, BL, BR)
            // Indices 4-7: Straights  (Down, Left, Right, Up)
            char[] closestPiece = new char[8];
            int[] minDistance = new int[8];
            for (int i = 0; i < 8; i++) {
                closestPiece[i] = 0;
                minDistance[i] = Integer.MAX_VALUE;
            }

            // Process each piece
            for (int i = 0; i < n; i++) {
                st = new StringTokenizer(br.readLine());
                char pieceType = st.nextToken().charAt(0);
                int r = Integer.parseInt(st.nextToken());
                int c = Integer.parseInt(st.nextToken());

                int dr = r - startRow;
                int dc = c - startCol;

                int direction = -1;
                int distance = 0;

                // Determine direction and Manhattan-like distance along the line
                if (dr == 0) {
                    // Horizontal movement
                    direction = dc > 0 ? 6 : 5; // Right : Left
                    distance = Math.abs(dc);
                } else if (dc == 0) {
                    // Vertical movement
                    direction = dr > 0 ? 4 : 7; // Down : Up
                    distance = Math.abs(dr);
                } else if (Math.abs(dr) == Math.abs(dc)) {
                    // Diagonal movement
                    if (dr < 0 && dc < 0) direction = 0; // Top-Left
                    else if (dr < 0 && dc > 0) direction = 1; // Top-Right
                    else if (dr > 0 && dc < 0) direction = 2; // Bottom-Left
                    else direction = 3; // Bottom-Right
                    distance = Math.abs(dr);
                }

                // Update tracking arrays if this piece is the closest found so far in this direction
                if (direction != -1 && distance < minDistance[direction]) {
                    minDistance[direction] = distance;
                    closestPiece[direction] = pieceType;
                }
            }

            // Evaluate if the starting square is under attack
            boolean isUnderAttack = false;
            for (int i = 0; i < 8; i++) {
                if (closestPiece[i] != 0) {
                    char p = closestPiece[i];
                    // Rooks and Queens attack horizontally/vertically (indices 4-7)
                    // Bishops and Queens attack diagonally (indices 0-3)
                    boolean canAttack = (i >= 4) ? (p == 'R' || p == 'Q') : (p == 'B' || p == 'Q');
                    if (canAttack) {
                        isUnderAttack = true;
                        break;
                    }
                }
            }

            System.out.println(isUnderAttack ? "YES" : "NO");
        }
    }
}

