public class Main {
    // Direction indices for tracking the closest point in each of the 8 directions
    // 0: LEFT, 1: RIGHT, 2: UP, 3: DOWN, 4: NW, 5: SE, 6: SW, 7: NE
    // Sentinel values: MIN_VALUE for "maximize coordinate" directions, MAX_VALUE for "minimize"
    private static final int[] BEST_COORD_INIT = {
        Long.MIN_VALUE, Long.MAX_VALUE, Long.MIN_VALUE, Long.MAX_VALUE,
        Long.MIN_VALUE, Long.MAX_VALUE, Long.MIN_VALUE, Long.MAX_VALUE
    };

