import java.io.*;
import java.util.*;

public class Main {
    private static final String RESULT_YES = "YES";
    private static final String RESULT_NO = "NO";
    private static final char PIECE_ROOK = 'R';
    private static final char PIECE_BISHOP = 'B';
    private static final char PIECE_QUEEN = 'Q';

    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        OutputWriter out = new OutputWriter(outputStream);

        Task solver = new Task();
        solver.solve(in, out);

        out.close();
    }

    /**
     * Solves the chess attack problem.
     * Checks if the king at (kx, ky) is under attack by any rook/queen or bishop/queen.
     */
    static class Task {
        public void solve(InputReader in, OutputWriter out) {
            int n = in.readInt();
            int kx = in.readInt();
            int ky = in.readInt();

            List<Chess> pieces = new ArrayList<>(n);
            for (int i = 0; i < n; i++) {
                char type = in.readCharacter();
                int x = in.readInt();
                int y = in.readInt();
                pieces.add(new Chess(type, x, y));
            }

            boolean attacked = isAttackedByRookOrQueen(kx, ky, pieces) ||
                               isAttackedByBishopOrQueen(kx, ky, pieces);

            out.print(attacked ? RESULT_YES : RESULT_NO);
        }

        /**
         * Checks for attacks along rows and columns.
         * A piece blocks further attacks in that direction, so we only need to check the closest one.
         */
        private boolean isAttackedByRookOrQueen(int kx, int ky, List<Chess> pieces) {
            Chess closestUp = null, closestDown = null;
            Chess closestLeft = null, closestRight = null;

            for (Chess piece : pieces) {
                if (piece.x == kx) {
                    // Same column
                    if (piece.y > ky) {
                        if (closestUp == null || piece.y < closestUp.y) closestUp = piece;
                    } else if (piece.y < ky) {
                        if (closestDown == null || piece.y > closestDown.y) closestDown = piece;
                    }
                } else if (piece.y == ky) {
                    // Same row
                    if (piece.x > kx) {
                        if (closestRight == null || piece.x < closestRight.x) closestRight = piece;
                    } else if (piece.x < kx) {
                        if (closestLeft == null || piece.x > closestLeft.x) closestLeft = piece;
                    }
                }
            }
            return isAttacker(closestUp) || isAttacker(closestDown) ||
                   isAttacker(closestLeft) || isAttacker(closestRight);
        }

        /**
         * Checks for attacks along diagonals.
         * Similar directional tracking as rooks/queens but for diagonal coordinates.
         */
        private boolean isAttackedByBishopOrQueen(int kx, int ky, List<Chess> pieces) {
            Chess closestUpRight = null, closestUpLeft = null;
            Chess closestDownRight = null, closestDownLeft = null;

            for (Chess piece : pieces) {
                // Check if piece lies on any diagonal passing through the king
                if (Math.abs(piece.x - kx) == Math.abs(piece.y - ky)) {
                    if (piece.x > kx && piece.y > ky) {
                        if (closestUpRight == null || piece.x < closestUpRight.x) closestUpRight = piece;
                    } else if (piece.x < kx && piece.y > ky) {
                        if (closestUpLeft == null || piece.x > closestUpLeft.x) closestUpLeft = piece;
                    } else if (piece.x > kx && piece.y < ky) {
                        if (closestDownRight == null || piece.x < closestDownRight.x) closestDownRight = piece;
                    } else if (piece.x < kx && piece.y < ky) {
                        if (closestDownLeft == null || piece.x > closestDownLeft.x) closestDownLeft = piece;
                    }
                }
            }
            return isAttackerBishop(closestUpRight) || isAttackerBishop(closestUpLeft) ||
                   isAttackerBishop(closestDownRight) || isAttackerBishop(closestDownLeft);
        }

        private boolean isAttacker(Chess piece) {
            return piece != null && (piece.type == PIECE_ROOK || piece.type == PIECE_QUEEN);
        }

        private boolean isAttackerBishop(Chess piece) {
            return piece != null && (piece.type == PIECE_BISHOP || piece.type == PIECE_QUEEN);
        }
    }

    /**
     * Immutable representation of a chess piece.
     */
    static class Chess {
        final char type;
        final int x;
        final int y;

        Chess(char type, int x, int y) {
            this.type = type;
            this.x = x;
            this.y = y;
        }
    }

    /**
     * Fast input reader for competitive programming.
     */
    static class InputReader {
        private final InputStream stream;
        private final byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;
        private SpaceCharFilter filter;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        public int read() {
            if (numChars == -1) {
                throw new InputMismatchException();
            }
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0) {
                    return -1;
                }
            }
            return buf[curChar++];
        }

        public int readInt() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                res *= 10;
                res += c - '0';
                c = read();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public boolean isSpaceChar(int c) {
            return filter != null ? filter.isSpaceChar(c) : isWhitespace(c);
        }

        public static boolean isWhitespace(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        public char readCharacter() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            return (char) c;
        }

        public interface SpaceCharFilter {
            boolean isSpaceChar(int ch);
        }
    }

    /**
     * Fast output writer for competitive programming.
     */
    static class OutputWriter {
        private final PrintWriter writer;

        public OutputWriter(OutputStream outputStream) {
            writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(outputStream)));
        }

        public OutputWriter(Writer writer) {
            this.writer = new PrintWriter(writer);
        }

        public void print(Object... objects) {
            for (int i = 0; i < objects.length; i++) {
                if (i != 0) {
                    writer.print(' ');
                }
                writer.print(objects[i]);
            }
        }

        public void close() {
            writer.close();
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayList;
import java.util.List;
import java.util.StringTokenizer;

public class ChessAttackChecker {

    public static void main(String[] args) throws IOException {
        FastScanner scanner = new FastScanner();
        ChessAttackChecker solver = new ChessAttackChecker();
        solver.solve(scanner);
    }

    void solve(FastScanner scanner) {
        int n = scanner.nextInt();
        long x0 = scanner.nextLong();
        long y0 = scanner.nextLong();

        // Categorize pieces by type (mapped from original: B=Slon, R=Lad, F=Ferz)
        List<Piece> slonPieces = new ArrayList<>();
        List<Piece> ladPieces = new ArrayList<>();
        List<Piece> ferzPieces = new ArrayList<>();

        for (int i = 0; i < n; i++) {
            String token = scanner.next();
            long x = scanner.nextLong();
            long y = scanner.nextLong();
            switch (token) {
                case "B" -> slonPieces.add(new Piece(x, y));
                case "R" -> ladPieces.add(new Piece(x, y));
                default  -> ferzPieces.add(new Piece(x, y));
            }
        }

        // Calculate minimum distances in cardinal directions from Slon pieces
        Distances cardDistSlon = calculateCardinalDistances(slonPieces, x0, y0);
        // Calculate minimum distances in diagonal directions from Lad pieces
        Distances diagDistLad = calculateDiagonalDistances(ladPieces, x0, y0);

        boolean attacks = false;

        // Check attacks from Slon (uses diagonal distances from Lad)
        attacks |= checkDiagonalAttacks(slonPieces, x0, y0, diagDistLad);
        // Check attacks from Lad (uses cardinal distances from Slon)
        attacks |= checkCardinalAttacks(ladPieces, x0, y0, cardDistSlon);
        // Check attacks from Ferz (uses both cardinal and diagonal distances)
        attacks |= checkAllAttacks(ferzPieces, x0, y0, cardDistSlon, diagDistLad);

        System.out.println(attacks ? "YES" : "NO");
    }

    /**
     * Calculates the minimum distance to the nearest piece in each cardinal direction.
     */
    private Distances calculateCardinalDistances(List<Piece> pieces, long x0, long y0) {
        long up = Long.MAX_VALUE;
        long down = Long.MAX_VALUE;
        long left = Long.MAX_VALUE;
        long right = Long.MAX_VALUE;

        for (Piece p : pieces) {
            if (p.x == x0) {
                if (p.y > y0) up = Math.min(up, p.y - y0);
                else down = Math.min(down, y0 - p.y);
            }
            if (p.y == y0) {
                if (p.x > x0) right = Math.min(right, p.x - x0);
                else left = Math.min(left, x0 - p.x);
            }
        }
        return new Distances(up, down, left, right, 0, 0, 0, 0);
    }

    /**
     * Calculates the minimum distance to the nearest piece in each diagonal direction.
     */
    private Distances calculateDiagonalDistances(List<Piece> pieces, long x0, long y0) {
        long upLeft = Long.MAX_VALUE;
        long upRight = Long.MAX_VALUE;
        long downLeft = Long.MAX_VALUE;
        long downRight = Long.MAX_VALUE;

        for (Piece p : pieces) {
            if (p.x - p.y == x0 - y0) {
                if (p.x > x0) upRight = Math.min(upRight, p.x - x0);
                else downLeft = Math.min(downLeft, x0 - p.x);
            }
            if (p.x + p.y == x0 + y0) {
                if (p.x > x0) downRight = Math.min(downRight, p.x - x0);
                else upLeft = Math.min(upLeft, x0 - p.x);
            }
        }
        return new Distances(0, 0, 0, 0, upLeft, upRight, downLeft, downRight);
    }

    private boolean checkDiagonalAttacks(List<Piece> pieces, long x0, long y0, Distances diagDist) {
        for (Piece p : pieces) {
            long dx = p.x - x0;
            if ((p.x - p.y == x0 - y0 && -diagDist.downLeft() < dx && dx < diagDist.upRight()) ||
                (p.x + p.y == x0 + y0 && -diagDist.upLeft() < dx && dx < diagDist.downRight())) {
                return true;
            }
        }
        return false;
    }

    private boolean checkCardinalAttacks(List<Piece> pieces, long x0, long y0, Distances cardDist) {
        for (Piece p : pieces) {
            long dx = p.x - x0;
            long dy = p.y - y0;
            if ((p.x == x0 && -cardDist.down() < dy && dy < cardDist.up()) ||
                (p.y == y0 && -cardDist.left() < dx && dx < cardDist.right())) {
                return true;
            }
        }
        return false;
    }

    private boolean checkAllAttacks(List<Piece> pieces, long x0, long y0, Distances cardDist, Distances diagDist) {
        for (Piece p : pieces) {
            long dx = p.x - x0;
            long dy = p.y - y0;
            if ((p.x - p.y == x0 - y0 && -diagDist.downLeft() < dx && dx < diagDist.upRight()) ||
                (p.x + p.y == x0 + y0 && -diagDist.upLeft() < dx && dx < diagDist.downRight()) ||
                (p.x == x0 && -cardDist.down() < dy && dy < cardDist.up()) ||
                (p.y == y0 && -cardDist.left() < dx && dx < cardDist.right())) {
                return true;
            }
        }
        return false;
    }

    /** Immutable data class for piece coordinates */
    private record Piece(long x, long y) {}

    /** Record to hold minimum distances in 8 directions */
    private record Distances(long up, long down, long left, long right,
                             long upLeft, long upRight, long downLeft, long downRight) {}

    /** Efficient console input reader */
    private static class FastScanner {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastScanner() {
            this.reader = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                String line = reader.readLine();
                if (line == null) throw new IOException("Unexpected end of input");
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        int nextInt() throws IOException { return Integer.parseInt(next()); }
        long nextLong() throws IOException { return Long.parseLong(next()); }
        double nextDouble() throws IOException { return Double.parseDouble(next()); }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

public class ChessAttackChecker {

    // Piece types that can attack in orthogonal directions (straight lines)
    private static final char[] ORTHOGONAL_ATTACKERS = {'Q', 'R'};
    // Piece types that can attack in diagonal directions
    private static final char[] DIAGONAL_ATTACKERS = {'Q', 'B'};

    public static void main(String[] args) throws IOException {
        // Use try-with-resources for automatic resource cleanup
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(System.in))) {
            String line = reader.readLine();
            if (line == null) return;
            int n = Integer.parseInt(line.trim());

            StringTokenizer st = new StringTokenizer(reader.readLine());
            int targetX = Integer.parseInt(st.nextToken());
            int targetY = Integer.parseInt(st.nextToken());

            Piece[] pieces = new Piece[n];
            for (int i = 0; i < n; i++) {
                st = new StringTokenizer(reader.readLine());
                pieces[i] = new Piece(st.nextToken().charAt(0),
                                      Integer.parseInt(st.nextToken()),
                                      Integer.parseInt(st.nextToken()));
            }

            boolean canAttack = canReachTarget(pieces, targetX, targetY);
            System.out.println(canAttack ? "YES" : "NO");
        }
    }

    /**
     * Determines if any piece can attack the target position.
     * Only considers the closest piece in each of the 8 directions,
     * as pieces in chess block movement of longer-range pieces.
     */
    private static boolean canReachTarget(Piece[] pieces, int targetX, int targetY) {
        // Track the closest piece in each of the 8 directions
        Piece closestNorth = null, closestSouth = null;
        Piece closestEast = null, closestWest = null;
        Piece closestNorthEast = null, closestSouthWest = null;
        Piece closestSouthEast = null, closestNorthWest = null;

        // Track the coordinate difference to find the minimum distance
        int closestNorthY = Integer.MAX_VALUE, closestSouthY = Integer.MIN_VALUE;
        int closestEastX = Integer.MAX_VALUE, closestWestX = Integer.MIN_VALUE;
        int closestNorthEastX = Integer.MAX_VALUE, closestSouthWestX = Integer.MIN_VALUE;
        int closestSouthEastX = Integer.MAX_VALUE, closestNorthWestX = Integer.MIN_VALUE;

        for (Piece piece : pieces) {
            int dx = piece.x - targetX;
            int dy = piece.y - targetY;

            // Orthogonal directions
            if (dx == 0) {
                if (dy > 0) { // North
                    if (dy < closestNorthY) {
                        closestNorthY = dy;
                        closestNorth = piece;
                    }
                } else if (dy < 0) { // South
                    if (dy > closestSouthY) {
                        closestSouthY = dy;
                        closestSouth = piece;
                    }
                }
            } else if (dy == 0) {
                if (dx > 0) { // East
                    if (dx < closestEastX) {
                        closestEastX = dx;
                        closestEast = piece;
                    }
                } else if (dx < 0) { // West
                    if (dx > closestWestX) {
                        closestWestX = dx;
                        closestWest = piece;
                    }
                }
            }

            // Diagonal directions
            if (dx == dy) {
                if (dx > 0) { // North East
                    if (dx < closestNorthEastX) {
                        closestNorthEastX = dx;
                        closestNorthEast = piece;
                    }
                } else if (dx < 0) { // South West
                    if (dx > closestSouthWestX) {
                        closestSouthWestX = dx;
                        closestSouthWest = piece;
                    }
                }
            } else if (dx == -dy) {
                if (dx > 0) { // South East
                    if (dx < closestSouthEastX) {
                        closestSouthEastX = dx;
                        closestSouthEast = piece;
                    }
                } else if (dx < 0) { // North West
                    if (dx > closestNorthWestX) {
                        closestNorthWestX = dx;
                        closestNorthWest = piece;
                    }
                }
            }
        }

        // Check orthogonal directions for Rook or Queen
        if (canAttack(closestNorth, ORTHOGONAL_ATTACKERS) ||
            canAttack(closestSouth, ORTHOGONAL_ATTACKERS) ||
            canAttack(closestEast, ORTHOGONAL_ATTACKERS) ||
            canAttack(closestWest, ORTHOGONAL_ATTACKERS)) {
            return true;
        }

        // Check diagonal directions for Bishop or Queen
        if (canAttack(closestNorthEast, DIAGONAL_ATTACKERS) ||
            canAttack(closestSouthWest, DIAGONAL_ATTACKERS) ||
            canAttack(closestSouthEast, DIAGONAL_ATTACKERS) ||
            canAttack(closestNorthWest, DIAGONAL_ATTACKERS)) {
            return true;
        }

        return false;
    }

    /**
     * Checks if a given piece matches any of the valid attacker types.
     */
    private static boolean canAttack(Piece piece, char[] validTypes) {
        return piece != null && (piece.type == validTypes[0] || piece.type == validTypes[1]);
    }

    /**
     * Represents a chess piece with its type and coordinates.
     */
    public static class Piece {
        final char type;
        final int x, y;

        Piece(char type, int x, int y) {
            this.type = type;
            this.x = x;
            this.y = y;
        }
    }
}

import java.util.Arrays;
import java.util.Scanner;

public class AntonAndChess {

    private final long kingX;
    private final long kingY;

    // Tracks the closest piece in each of the 8 directions around the king.
    // Indices 0-3 are orthogonal (Right, Down, Left, Up)
    // Indices 4-7 are diagonal (Top-Right, Top-Left, Bottom-Left, Bottom-Right)
    private final long[] closestDistance = new long[8];
    private final char[] closestPiece = new char[8];

    public AntonAndChess(long kingX, long kingY) {
        this.kingX = kingX;
        this.kingY = kingY;
        Arrays.fill(closestDistance, Long.MAX_VALUE);
    }

    /**
     * Processes a piece and updates the closest attacker in its relative direction.
     */
    public void processPiece(char pieceType, long pieceX, long pieceY) {
        long dx = pieceX - kingX;
        long dy = pieceY - kingY;

        int directionIndex = getDirectionIndex(dx, dy);
        if (directionIndex == -1) {
            return; // Piece is not aligned with the king
        }

        // Use Chebyshev distance (max of absolute differences) for consistent comparison
        long distance = Math.max(Math.abs(dx), Math.abs(dy));

        if (distance < closestDistance[directionIndex]) {
            closestDistance[directionIndex] = distance;
            closestPiece[directionIndex] = pieceType;
        }
    }

    /**
     * Determines which of the 8 directions the piece lies relative to the king.
     * Returns -1 if the piece is not on the same row, column, or diagonal.
     */
    private int getDirectionIndex(long dx, long dy) {
        if (dx == 0 && dy == 0) {
            return -1; // Occupies the same square
        }

        // Orthogonal directions
        if (dx == 0) {
            return dy > 0 ? 1 : 3; // Down or Up
        }
        if (dy == 0) {
            return dx > 0 ? 0 : 2; // Right or Left
        }

        // Diagonal directions
        if (Math.abs(dx) == Math.abs(dy)) {
            if (dx > 0 && dy > 0) return 7; // Bottom-Right
            if (dx > 0 && dy < 0) return 4; // Top-Right
            if (dx < 0 && dy > 0) return 6; // Bottom-Left
            if (dx < 0 && dy < 0) return 5; // Top-Left
        }

        return -1; // Not aligned
    }

    /**
     * Checks if any piece is currently attacking the king.
     * Orthogonal pieces must be Rooks or Queens.
     * Diagonal pieces must be Bishops or Queens.
     */
    public boolean isUnderAttack() {
        for (int i = 0; i < 8; i++) {
            if (closestPiece[i] == 0) {
                continue; // No piece in this direction
            }

            boolean isOrthogonal = i < 4;
            if (isOrthogonal && (closestPiece[i] == 'Q' || closestPiece[i] == 'R')) {
                return true;
            }
            if (!isOrthogonal && (closestPiece[i] == 'Q' || closestPiece[i] == 'B')) {
                return true;
            }
        }
        return false;
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        if (!scanner.hasNextInt()) {
            return;
        }

        int numPieces = scanner.nextInt();
        long kingX = scanner.nextLong();
        long kingY = scanner.nextLong();

        AntonAndChess board = new AntonAndChess(kingX, kingY);

        for (int i = 0; i < numPieces; i++) {
            char type = scanner.next().charAt(0);
            long px = scanner.nextLong();
            long py = scanner.nextLong();
            board.processPiece(type, px, py);
        }

        System.out.println(board.isUnderAttack() ? "YES" : "NO");
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.Arrays;
import java.util.StringTokenizer;

public class CF734D {

    /**
     * Helper class to handle fast input reading.
     * This encapsulates the BufferedReader and StringTokenizer logic
     * to make the main method cleaner and more robust.
     */
    static class FastScanner {
        BufferedReader br;
        StringTokenizer st;

        public FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    e.printStackTrace();
                    return null;
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            String s = next();
            if (s == null) return 0;
            return Integer.parseInt(s);
        }
    }

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner();

        // Read number of pieces
        String nStr = scanner.next();
        if (nStr == null) return;
        int n = Integer.parseInt(nStr);

        // Read starting position of the King
        int x0 = scanner.nextInt();
        int y0 = scanner.nextInt();

        // Arrays to store the closest piece in each of the 8 directions.
        // Indices mapping:
        // 0: East  (x > 0, y = 0)
        // 1: North-East (x > 0, y > 0, x == y)
        // 2: North (x = 0, y > 0)
        // 3: North-West (x < 0, y > 0, -x == y)
        // 4: West  (x < 0, y = 0)
        // 5: South-West (x < 0, y < 0, x == y)
        // 6: South (x = 0, y < 0)
        // 7: South-East (x > 0, y < 0, x == -y)
        int[] minDist = new int[8];
        char[] pieceType = new char[8];

        // Initialize distances to Infinity and pieces to empty space
        Arrays.fill(minDist, Integer.MAX_VALUE);
        Arrays.fill(pieceType, ' ');

        for (int i = 0; i < n; i++) {
            char type = scanner.next().charAt(0);
            int x = scanner.nextInt();
            int y = scanner.nextInt();

            int dx = x - x0;
            int dy = y - y0;

            int directionIndex = -1;
            int distance = 0;

            // Determine direction and calculate distance
            // Rook moves (Cardinal directions)
            if (dx == 0 && dy > 0) {
                directionIndex = 2; // North
                distance = dy;
            } else if (dx == 0 && dy < 0) {
                directionIndex = 6; // South
                distance = -dy;
            } else if (dy == 0 && dx > 0) {
                directionIndex = 0; // East
                distance = dx;
            } else if (dy == 0 && dx < 0) {
                directionIndex = 4; // West
                distance = -dx;
            } 
            // Bishop moves (Diagonal directions)
            else if (dx > 0 && dy > 0 && dx == dy) {
                directionIndex = 1; // North-East
                distance = dx;
            } else if (dx < 0 && dy < 0 && dx == dy) {
                directionIndex = 5; // South-West
                distance = -dx;
            } else if (dx < 0 && dy > 0 && -dx == dy) {
                directionIndex = 3; // North-West
                distance = dy;
            } else if (dx > 0 && dy < 0 && dx == -dy) {
                directionIndex = 7; // South-East
                distance = dx;
            }

            // If the piece lies on a valid attack line, update the closest piece found.
            // This implicitly handles blocking: if a closer piece (like a Pawn) exists,
            // it overwrites the distance/char of any further piece.
            if (directionIndex != -1) {
                if (distance < minDist[directionIndex]) {
                    minDist[directionIndex] = distance;
                    pieceType[directionIndex] = type;
                }
            }
        }

        boolean canAttack = false;

        // Check Rook attacks (Cardinal directions: 0, 2, 4, 6)
        // A Rook ('R') or Queen ('Q') in these directions attacks the King.
        if (pieceType[0] == 'R' || pieceType[0] == 'Q' ||
            pieceType[2] == 'R' || pieceType[2] == 'Q' ||
            pieceType[4] == 'R' || pieceType[4] == 'Q' ||
            pieceType[6] == 'R' || pieceType[6] == 'Q') {
            canAttack = true;
        }

        // Check Bishop attacks (Diagonal directions: 1, 3, 5, 7)
        // A Bishop ('B') or Queen ('Q') in these directions attacks the King.
        if (pieceType[1] == 'B' || pieceType[1] == 'Q' ||
            pieceType[3] == 'B' || pieceType[3] == 'Q' ||
            pieceType[5] == 'B' || pieceType[5] == 'Q' ||
            pieceType[7] == 'B' || pieceType[7] == 'Q') {
            canAttack = true;
        }

        System.out.println(canAttack ? "YES" : "NO");
    }
}

import java.io.*;
import java.util.*;

public class P734D {

    private static class Figure implements Comparable<Figure> {
        final int x, y;
        final long distance;
        final char type;

        Figure(char type, int x, int y, int x0, int y0) {
            this.type = type;
            this.x = x;
            this.y = y;
            this.distance = Math.abs(x - x0) + Math.abs(y - y0);
        }

        @Override
        public int compareTo(Figure other) {
            return Long.compare(this.distance, other.distance);
        }

        @Override
        public String toString() {
            return String.format("[x=%d, y=%d, type=%c, dist=%d]", x, y, type, distance);
        }
    }

    public void run() throws IOException {
        int n = FastIO.nextInt();
        int x0 = FastIO.nextInt();
        int y0 = FastIO.nextInt();

        Map<String, List<Figure>> piecesByDirection = new HashMap<>();
        String[] directions = {"R", "L", "U", "D", "RU", "RD", "LU", "LD"};
        for (String dir : directions) {
            piecesByDirection.put(dir, new ArrayList<>());
        }

        for (int i = 0; i < n; i++) {
            char type = FastIO.next().charAt(0);
            int x = FastIO.nextInt();
            int y = FastIO.nextInt();

            int dx = x - x0;
            int dy = y - y0;

            if (dx == 0 && dy == 0) continue;

            String dirKey;
            if (y == y0) {
                dirKey = (dx > 0) ? "R" : "L";
            } else if (x == x0) {
                dirKey = (dy > 0) ? "U" : "D";
            } else if (Math.abs(dx) == Math.abs(dy)) {
                if (dx > 0 && dy > 0) dirKey = "RU";
                else if (dx > 0 && dy < 0) dirKey = "RD";
                else if (dx < 0 && dy > 0) dirKey = "LU";
                else dirKey = "LD";
            } else {
                continue;
            }

            piecesByDirection.get(dirKey).add(new Figure(type, x, y, x0, y0));
        }

        piecesByDirection.values().forEach(list -> list.sort(Comparator.comparingLong(f -> f.distance)));

        boolean canAttack =
                hasAttacker(piecesByDirection.get("R"), 'R', 'Q') ||
                hasAttacker(piecesByDirection.get("L"), 'R', 'Q') ||
                hasAttacker(piecesByDirection.get("U"), 'R', 'Q') ||
                hasAttacker(piecesByDirection.get("D"), 'R', 'Q') ||
                hasAttacker(piecesByDirection.get("RU"), 'B', 'Q') ||
                hasAttacker(piecesByDirection.get("RD"), 'B', 'Q') ||
                hasAttacker(piecesByDirection.get("LU"), 'B', 'Q') ||
                hasAttacker(piecesByDirection.get("LD"), 'B', 'Q');

        FastIO.println(canAttack ? "YES" : "NO");
    }

    private boolean hasAttacker(List<Figure> list, char... allowedTypes) {
        if (list == null || list.isEmpty()) return false;
        char type = list.get(0).type;
        for (char allowed : allowedTypes) {
            if (type == allowed) return true;
        }
        return false;
    }

    public static void main(String[] args) throws IOException {
        new P734D().run();
        FastIO.close();
    }

    static class FastIO {
        static BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        static PrintWriter pw = new PrintWriter(new BufferedOutputStream(System.out));
        static StringTokenizer stok;
        static long startTime = System.currentTimeMillis();

        static String next() throws IOException {
            while (stok == null || !stok.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) return null;
                stok = new StringTokenizer(line);
            }
            return stok.nextToken();
        }

        static int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        static void println(String s) {
            pw.println(s);
        }

        static void close() {
            try {
                br.close();
                pw.close();
                System.err.println("\n[Time : " + (System.currentTimeMillis() - startTime) + " ms]");
            } catch (IOException e) {
                e.printStackTrace();
            }
        }
    }
}

import java.util.Scanner;

public class Solution2 {
    // Direction indices (clockwise from North)
    private static final int DIR_N = 0;
    private static final int DIR_NE = 1;
    private static final int DIR_E = 2;
    private static final int DIR_SE = 3;
    private static final int DIR_S = 4;
    private static final int DIR_SW = 5;
    private static final int DIR_W = 6;
    private static final int DIR_NW = 7;

    private static final int[] DIAGONAL_DIRS = {DIR_NE, DIR_SE, DIR_SW, DIR_NW};
    private static final int[] ORTHOGONAL_DIRS = {DIR_N, DIR_E, DIR_S, DIR_W};

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            if (!scanner.hasNextInt()) return;

            int n = scanner.nextInt();
            int x0 = scanner.nextInt();
            int y0 = scanner.nextInt();

            Piece[] closestPieces = new Piece[8];

            for (int i = 0; i < n; i++) {
                char type = scanner.next().charAt(0);
                int x = scanner.nextInt();
                int y = scanner.nextInt();

                int dir = getDirection(x0, y0, x, y);
                if (dir != -1) {
                    updateClosestPiece(closestPieces, dir, new Piece(type, x - x0, y - y0));
                }
            }

            System.out.println(canAttack(closestPieces) ? "YES" : "NO");
        }
    }

    /**
     * Determines which of the 8 directions a piece lies relative to the starting position.
     * Returns -1 if the piece is not aligned in any of the 8 directions.
     */
    private static int getDirection(int x0, int y0, int x, int y) {
        int dx = x - x0;
        int dy = y - y0;

        if (dx == 0 && dy < 0) return DIR_N;
        if (dx > 0 && dy > 0 && dx == dy) return DIR_NE;
        if (dx > 0 && dy == 0) return DIR_E;
        if (dx > 0 && dy < 0 && dx == -dy) return DIR_SE;
        if (dx == 0 && dy > 0) return DIR_S;
        if (dx < 0 && dy < 0 && dx == dy) return DIR_SW;
        if (dx < 0 && dy == 0) return DIR_W;
        if (dx < 0 && dy > 0 && dx == -dy) return DIR_NW;

        return -1;
    }

    /**
     * Updates the closest piece array if the candidate is closer than the current piece
     * in the specified direction.
     */
    private static void updateClosestPiece(Piece[] closest, int dir, Piece candidate) {
        if (closest[dir] == null || candidate.distanceToOrigin(dir) < closest[dir].distanceToOrigin(dir)) {
            closest[dir] = candidate;
        }
    }

    /**
     * Checks if any closest piece in the relevant direction can attack the starting square.
     */
    private static boolean canAttack(Piece[] closest) {
        for (int dir : DIAGONAL_DIRS) {
            Piece p = closest[dir];
            if (p != null && (p.type == 'B' || p.type == 'Q')) {
                return true;
            }
        }
        for (int dir : ORTHOGONAL_DIRS) {
            Piece p = closest[dir];
            if (p != null && (p.type == 'R' || p.type == 'Q')) {
                return true;
            }
        }
        return false;
    }

    /**
     * Represents a chess piece with its type and relative coordinates.
     */
    private static class Piece {
        final char type;
        final int relX;
        final int relY;

        Piece(char type, int relX, int relY) {
            this.type = type;
            this.relX = relX;
            this.relY = relY;
        }

        /**
         * Calculates the distance from the origin along the given direction.
         * For N/S, distance is based on Y. For all other directions, it's based on X.
         */
        int distanceToOrigin(int dir) {
            return (dir == DIR_N || dir == DIR_S) ? Math.abs(relY) : Math.abs(relX);
        }
    }
}

import java.io.*;
import java.util.*;
import java.util.function.ToIntFunction;

public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        OutputWriter out = new OutputWriter(outputStream);
        TaskD solver = new TaskD();
        solver.solve(in, out);
        out.close();
    }

    static class TaskD {
        private static final String YES = "YES";
        private static final String NO = "NO";

        public void solve(InputReader in, OutputWriter out) {
            int n = in.readInt();
            int kingX = in.readInt();
            int kingY = in.readInt();

            List<Piece> byX = new ArrayList<>();
            List<Piece> byY = new ArrayList<>();
            List<Piece> byXpY = new ArrayList<>();
            List<Piece> byXmY = new ArrayList<>();

            for (int i = 0; i < n; i++) {
                char type = in.readCharacter();
                int x = in.readInt();
                int y = in.readInt();

                if (x == kingX) byX.add(new Piece(type, x, y));
                else if (y == kingY) byY.add(new Piece(type, x, y));
                else if (x + y == kingX + kingY) byXpY.add(new Piece(type, x, y));
                else if (x - y == kingX - kingY) byXmY.add(new Piece(type, x, y));
            }

            // Check vertical, horizontal, and both diagonals for attacking pieces
            if (checkAttack(byX, kingY, 'R', 'Q', p -> p.y)) { out.printLine(YES); return; }
            if (checkAttack(byY, kingX, 'R', 'Q', p -> p.x)) { out.printLine(YES); return; }
            if (checkAttack(byXpY, kingX, 'B', 'Q', p -> p.x)) { out.printLine(YES); return; }
            if (checkAttack(byXmY, kingX, 'B', 'Q', p -> p.x)) { out.printLine(YES); return; }

            out.printLine(NO);
        }

        /**
         * Checks if the closest piece(s) to the king's coordinate along a specific axis/diagonal
         * are of an attacking type.
         */
        private boolean checkAttack(List<Piece> pieces, int kingCoord, char type1, char type2,
                                    ToIntFunction<Piece> coordExtractor) {
            if (pieces.isEmpty()) return false;

            pieces.sort(Comparator.comparingInt(coordExtractor));

            // Find the index of the last piece with coordinate <= kingCoord
            int idx = -1;
            for (int i = 0; i < pieces.size(); i++) {
                if (coordExtractor.applyAsInt(pieces.get(i)) <= kingCoord) idx = i;
            }

            // Check the closest piece from below (idx) and above (idx + 1)
            for (int i = idx; i <= idx + 1 && i < pieces.size(); i++) {
                if (i >= 0 && (pieces.get(i).type == type1 || pieces.get(i).type == type2)) {
                    return true;
                }
            }
            return false;
        }

        static final class Piece {
            final char type;
            final int x;
            final int y;

            Piece(char type, int x, int y) {
                this.type = type;
                this.x = x;
                this.y = y;
            }
        }
    }

    static class OutputWriter {
        private final PrintWriter writer;

        public OutputWriter(OutputStream outputStream) {
            writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(outputStream)));
        }

        public OutputWriter(Writer writer) {
            this.writer = new PrintWriter(writer);
        }

        public void print(Object... objects) {
            for (int i = 0; i < objects.length; i++) {
                if (i != 0) writer.print(' ');
                writer.print(objects[i]);
            }
        }

        public void printLine(Object... objects) {
            print(objects);
            writer.println();
        }

        public void close() {
            writer.close();
        }
    }

    static class InputReader {
        private final InputStream stream;
        private final byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;
        private SpaceCharFilter filter;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        public int read() {
            if (numChars == -1) throw new InputMismatchException();
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0) return -1;
            }
            return buf[curChar++];
        }

        public int readInt() {
            int c = read();
            while (isSpaceChar(c)) c = read();
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9') throw new InputMismatchException();
                res *= 10;
                res += c - '0';
                c = read();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public boolean isSpaceChar(int c) {
            return filter != null ? filter.isSpaceChar(c) : isWhitespace(c);
        }

        public static boolean isWhitespace(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        public char readCharacter() {
            int c = read();
            while (isSpaceChar(c)) c = read();
            return (char) c;
        }

        public interface SpaceCharFilter {
            boolean isSpaceChar(int ch);
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.HashMap;
import java.util.Map;
import java.util.StringTokenizer;

/**
 * Refactored Chess Piece Analyzer.
 * 
 * This version improves maintainability and code quality by:
 * 1. Using descriptive class and variable names (e.g., ChessPieceAnalyzer, startX).
 * 2. Encapsulating input parsing into a clean FastScanner helper class.
 * 3. Using an Enum for directions to replace magic integer indices.
 * 4. Separating logic into distinct steps: Input, Processing, and Validation.
 * 5. Utilizing efficient I/O (BufferedReader) while maintaining readability.
 */
public class ChessPieceAnalyzer {

    /**
     * Represents the 8 possible directions on a chessboard grid.
     */
    enum Direction {
        NORTH, SOUTH, EAST, WEST,
        NORTH_EAST, NORTH_WEST, SOUTH_EAST, SOUTH_WEST
    }

    /**
     * Stores information about the closest piece found in a specific direction.
     */
    private static class PieceRecord {
        char pieceType;
        int distance;

        public PieceRecord(char pieceType, int distance) {
            this.pieceType = pieceType;
            this.distance = distance;
        }
    }

    public static void main(String[] args) throws IOException {
        FastScanner scanner = new FastScanner();

        // Read number of moves and starting position
        // Note: Added basic null check for robustness, though CP inputs are usually well-formed.
        String nStr = scanner.next();
        if (nStr == null) return;

        int moveCount = Integer.parseInt(nStr);
        int startX = scanner.nextInt();
        int startY = scanner.nextInt();

        // Map to store the closest piece found for each of the 8 directions.
        // Key: Direction, Value: The piece type and its distance from start.
        Map<Direction, PieceRecord> closestPieces = new HashMap<>();

        // Initialize all directions with maximum distance
        for (Direction dir : Direction.values()) {
            closestPieces.put(dir, new PieceRecord('\0', Integer.MAX_VALUE));
        }

        // Process each move
        for (int i = 0; i < moveCount; i++) {
            String pieceStr = scanner.next();
            if (pieceStr == null) break;
            char pieceType = pieceStr.charAt(0);

            int targetX = scanner.nextInt();
            int targetY = scanner.nextInt();

            // Calculate relative coordinates
            int dx = targetX - startX;
            int dy = targetY - startY;

            // Determine direction and distance
            Direction direction = getDirection(dx, dy);

            if (direction != null) {
                // Distance is the maximum of absolute differences (Chebyshev distance)
                // This works for both orthogonal (max(0, d) = d) and diagonal (max(d, d) = d).
                int distance = Math.max(Math.abs(dx), Math.abs(dy));

                // Update if this piece is strictly closer than the previously recorded one
                PieceRecord currentBest = closestPieces.get(direction);
                if (distance < currentBest.distance) {
                    closestPieces.put(direction, new PieceRecord(pieceType, distance));
                }
            }
        }

        // Check if any valid capture condition is met
        boolean canCapture = false;

        for (Map.Entry<Direction, PieceRecord> entry : closestPieces.entrySet()) {
            Direction dir = entry.getKey();
            PieceRecord record = entry.getValue();

            // If no piece found in this direction, skip
            if (record.pieceType == '\0') {
                continue;
            }

            // Identify direction type
            boolean isOrthogonal = (dir == Direction.NORTH || dir == Direction.SOUTH || 
                                    dir == Direction.EAST || dir == Direction.WEST);

            boolean isDiagonal = (dir == Direction.NORTH_EAST || dir == Direction.NORTH_WEST || 
                                  dir == Direction.SOUTH_EAST || dir == Direction.SOUTH_WEST);

            // Check conditions based on piece type
            // Rook (R) and Queen (Q) attack orthogonally
            if (isOrthogonal && (record.pieceType == 'R' || record.pieceType == 'Q')) {
                canCapture = true;
                break;
            }

            // Bishop (B) and Queen (Q) attack diagonally
            if (isDiagonal && (record.pieceType == 'B' || record.pieceType == 'Q')) {
                canCapture = true;
                break;
            }
        }

        System.out.println(canCapture ? "YES" : "NO");
    }

    /**
     * Determines the direction from a relative vector (dx, dy).
     * Returns null if the vector does not align with a valid chess move direction (orthogonal or diagonal).
     */
    private static Direction getDirection(int dx, int dy) {
        if (dx == 0) {
            if (dy > 0) return Direction.NORTH;
            if (dy < 0) return Direction.SOUTH;
        } else if (dy == 0) {
            if (dx > 0) return Direction.EAST;
            if (dx < 0) return Direction.WEST;
        } else {
            // Check for diagonal (absolute values must be equal)
            if (Math.abs(dx) == Math.abs(dy)) {
                if (dx > 0 && dy > 0) return Direction.NORTH_EAST;
                if (dx < 0 && dy > 0) return Direction.NORTH_WEST;
                if (dx > 0 && dy < 0) return Direction.SOUTH_EAST;
                if (dx < 0 && dy < 0) return Direction.SOUTH_WEST;
            }
        }
        return null;
    }

    /**
     * A helper class for fast input reading using BufferedReader and StringTokenizer.
     * This replaces the legacy StreamTokenizer used in the original code for better safety and readability.
     */
    static class FastScanner {
        BufferedReader br;
        StringTokenizer st;

        public FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    e.printStackTrace();
                    return null;
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            String s = next();
            if (s == null) return 0; // Should not happen with valid input
            return Integer.parseInt(s);
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.util.Arrays;
import java.util.StringTokenizer;

/**
 * Analyzes board positions to determine if a piece can attack a target.
 * Tracks the closest piece in each of the 8 cardinal/diagonal directions.
 */
public class BoardAnalyzer {

    // Direction indices mapping:
    // 0: Up,    1: Down,  2: Right, 3: Left
    // 4: Top-Left, 5: Top-Right, 6: Bottom-Left, 7: Bottom-Right
    private static final long MAX_DISTANCE = Long.MAX_VALUE;

    public static void main(String[] args) {
        new BoardAnalyzer().run();
    }

    /**
     * Entry point for the analysis logic.
     */
    public void run() {
        FastScanner scanner = new FastScanner(System.in);
        try {
            int n = scanner.nextInt();
            long sx = scanner.nextLong();
            long sy = scanner.nextLong();

            long[] bestDistances = new long[8];
            char[] pieceTypes = new char[8];
            Arrays.fill(bestDistances, MAX_DISTANCE);
            Arrays.fill(pieceTypes, 'P'); // Placeholder for unoccupied directions

            for (int i = 0; i < n; i++) {
                char op = scanner.next().charAt(0);
                long x = scanner.nextLong();
                long y = scanner.nextLong();

                int direction = getDirectionIndex(sx, sy, x, y);
                if (direction != -1) {
                    long dist = Math.abs(x - sx);
                    if (dist < bestDistances[direction]) {
                        bestDistances[direction] = dist;
                        pieceTypes[direction] = op;
                    }
                }
            }

            boolean canAttack = checkAttackPossibility(pieceTypes);
            System.out.println(canAttack ? "YES" : "NO");
        } catch (IOException e) {
            System.err.println("Error reading input: " + e.getMessage());
        } finally {
            scanner.close();
        }
    }

    /**
     * Determines the direction index (0-7) from the start position to the target.
     * Returns -1 if the target is not aligned in any of the 8 directions.
     */
    private int getDirectionIndex(long sx, long sy, long x, long y) {
        long dx = x - sx;
        long dy = y - sy;

        if (dx == 0) return dy > 0 ? 0 : 1;
        if (dy == 0) return dx > 0 ? 2 : 3;
        if (dx + dy == 0) return dx > 0 ? 5 : 4;
        if (dx - dy == 0) return dx > 0 ? 7 : 6;
        return -1;
    }

    /**
     * Checks if any tracked piece in the relevant directions can attack.
     * Orthogonal (0-3): Queen or Rook
     * Diagonal (4-7): Queen or Bishop
     */
    private boolean checkAttackPossibility(char[] pieceTypes) {
        for (int i = 0; i < 4; i++) {
            if (pieceTypes[i] == 'Q' || pieceTypes[i] == 'R') {
                return true;
            }
        }
        for (int i = 4; i < 8; i++) {
            if (pieceTypes[i] == 'Q' || pieceTypes[i] == 'B') {
                return true;
            }
        }
        return false;
    }

    /**
     * Efficient input scanner for fast I/O operations.
     */
    static class FastScanner {
        private BufferedReader br;
        private StringTokenizer st;

        public FastScanner(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
            st = new StringTokenizer("");
        }

        public String next() throws IOException {
            while (!st.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) {
                    throw new IOException("Unexpected end of input");
                }
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        public long nextLong() throws IOException {
            return Long.parseLong(next());
        }

        public void close() throws IOException {
            br.close();
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Refactored solution for CF379Div2D.
 * 
 * Key Improvements:
 * 1. Eliminated magic numbers and hardcoded indices using a Direction enum.
 * 2. Replaced verbose if-else chains with clean array-based state tracking.
 * 3. Simplified I/O with a robust, production-ready FastScanner.
 * 4. Removed unnecessary nested classes (Solver, Vertex) and flattened the structure.
 * 5. Added early exit optimization when an attack is confirmed.
 * 6. Improved naming conventions and added inline documentation.
 */
public class CF379Div2D {

    /**
     * Represents the 8 possible directions from the center point.
     * Indices 0-7 match the original problem's directional mapping.
     */
    enum Direction {
        NORTH(0, -1, true),
        NORTH_EAST(1, -1, false),
        EAST(2, 0, true),
        SOUTH_EAST(3, 1, false),
        SOUTH(4, 1, true),
        SOUTH_WEST(5, 1, false),
        WEST(6, 0, true),
        NORTH_WEST(7, -1, false);

        final int dx, dy;
        final boolean isStraight;

        Direction(int dx, int dy, boolean isStraight) {
            this.dx = dx;
            this.dy = dy;
            this.isStraight = isStraight;
        }
    }

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out));

        try {
            int n = scanner.nextInt();
            int centerX = scanner.nextInt();
            int centerY = scanner.nextInt();

            // Tracks the closest piece character in each direction
            char[] closestPiece = new char[8];
            // Tracks the Chebyshev distance to the closest piece in each direction
            int[] closestDist = new int[8];
            Arrays.fill(closestDist, Integer.MAX_VALUE);

            for (int i = 0; i < n; i++) {
                char pieceType = scanner.next().charAt(0);
                int x = scanner.nextInt();
                int y = scanner.nextInt();

                int dx = x - centerX;
                int dy = y - centerY;

                Direction dir = getDirection(dx, dy);
                if (dir != null) {
                    int dist = Math.max(Math.abs(dx), Math.abs(dy));
                    int idx = dir.ordinal();

                    // Keep only the closest piece in this direction
                    if (dist < closestDist[idx]) {
                        closestDist[idx] = dist;
                        closestPiece[idx] = pieceType;
                    }
                }
            }

            boolean isAttacked = false;
            for (Direction dir : Direction.values()) {
                char piece = closestPiece[dir.ordinal()];
                if (piece == '\0') continue; // No piece in this direction

                if (dir.isStraight) {
                    if (piece == 'R' || piece == 'Q') {
                        isAttacked = true;
                        break; // Early exit: attack confirmed
                    }
                } else {
                    if (piece == 'B' || piece == 'Q') {
                        isAttacked = true;
                        break; // Early exit: attack confirmed
                    }
                }
            }

            out.println(isAttacked ? "YES" : "NO");

        } catch (Exception e) {
            // In competitive programming, input is guaranteed to be well-formed.
            // This catch block is a safety net for unexpected runtime errors.
            e.printStackTrace();
        } finally {
            out.flush();
            out.close();
        }
    }

    /**
     * Determines the Direction enum value from relative coordinates (dx, dy).
     * Returns null if the point does not lie on any of the 8 cardinal/diagonal lines.
     */
    private static Direction getDirection(int dx, int dy) {
        if (dx == 0 && dy < 0) return Direction.NORTH;
        if (dx == 0 && dy > 0) return Direction.SOUTH;
        if (dy == 0 && dx < 0) return Direction.WEST;
        if (dy == 0 && dx > 0) return Direction.EAST;
        if (dx < 0 && dy < 0 && dx == dy) return Direction.NORTH_WEST;
        if (dx > 0 && dy < 0 && dx == -dy) return Direction.NORTH_EAST;
        if (dx < 0 && dy > 0 && dx == -dy) return Direction.SOUTH_WEST;
        if (dx > 0 && dy > 0 && dx == dy) return Direction.SOUTH_EAST;
        return null;
    }

    /**
     * Fast I/O helper to handle large input efficiently.
     */
    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        public String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input", e);
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            String s = next();
            if (s == null) throw new NoSuchElementException();
            return Integer.parseInt(s);
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.Arrays;
import java.util.StringTokenizer;

public class Main {
    // Direction indices mapping:
    // 0: Bottom-Left, 1: Left, 2: Top-Left, 3: Bottom
    // 4: Top, 5: Bottom-Right, 6: Right, 7: Top-Right
    private static final int[] BISHOP_DIRS = {0, 2, 5, 7};
    private static final int[] ROOK_DIRS = {1, 3, 4, 6};

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st;

        // Read number of pieces
        String line = br.readLine();
        if (line == null) return;
        int n = Integer.parseInt(line.trim());

        // Read starting position
        st = new StringTokenizer(br.readLine());
        int startX = Integer.parseInt(st.nextToken());
        int startY = Integer.parseInt(st.nextToken());

        // Track the closest piece type in each of the 8 directions
        char[] closestPiece = new char[8];
        int[] minDist = new int[8];
        Arrays.fill(minDist, Integer.MAX_VALUE);

        for (int i = 0; i < n; i++) {
            st = new StringTokenizer(br.readLine());
            char type = st.nextToken().charAt(0);
            int x = Integer.parseInt(st.nextToken());
            int y = Integer.parseInt(st.nextToken());

            int dx = x - startX;
            int dy = y - startY;

            int dir = getDirectionIndex(dx, dy);
            if (dir != -1) {
                // Distance is simply |dx| (equals |dy| on valid diagonals/axes)
                int dist = Math.abs(dx);
                if (dist < minDist[dir]) {
                    minDist[dir] = dist;
                    closestPiece[dir] = type;
                }
            }
        }

        boolean canAttack = canPieceAttack(closestPiece);
        System.out.println(canAttack ? "YES" : "NO");
    }

    /**
     * Determines the direction index (0-7) relative to the starting position.
     * Returns -1 if the piece is not on a valid attacking line/diagonal.
     */
    private static int getDirectionIndex(int dx, int dy) {
        if (dx < 0 && dy < 0) return 0; // Bottom-Left
        if (dx < 0 && dy == 0) return 1; // Left
        if (dx < 0 && dy > 0) return 2; // Top-Left
        if (dx == 0 && dy < 0) return 3; // Bottom
        if (dx == 0 && dy > 0) return 4; // Top
        if (dx > 0 && dy < 0) return 5; // Bottom-Right
        if (dx > 0 && dy == 0) return 6; // Right
        if (dx > 0 && dy > 0) return 7; // Top-Right
        return -1;
    }

    /**
     * Checks if any tracked piece can attack the starting position based on chess rules.
     */
    private static boolean canPieceAttack(char[] closestPiece) {
        // Bishops and Queens attack diagonally
        for (int dir : BISHOP_DIRS) {
            char p = closestPiece[dir];
            if (p == 'B' || p == 'Q') return true;
        }
        // Rooks and Queens attack horizontally/vertically
        for (int dir : ROOK_DIRS) {
            char p = closestPiece[dir];
            if (p == 'R' || p == 'Q') return true;
        }
        // Queens attack in all 8 directions
        for (char p : closestPiece) {
            if (p == 'Q') return true;
        }
        return false;
    }
}

import java.util.Scanner;
import java.util.EnumMap;
import java.util.Map;

/**
 * Refactored Chess Check Program.
 * 
 * Improvements made:
 * 1. Class Naming: Renamed to 'ChessCheck' following Java conventions.
 * 2. Enums: Used enums for PieceType and Direction to replace magic strings and abbreviations.
 * 3. Data Structures: Replaced 8 separate variables with Maps (EnumMap) for cleaner state management.
 * 4. Magic Numbers: Removed hardcoded large integers (2147483640) in favor of Long.MAX_VALUE.
 * 5. Input Safety: Changed piece coordinate reading from nextInt() to nextLong() to match variable types.
 * 6. Logic Encapsulation: Extracted direction calculation and piece parsing into helper methods.
 * 7. Resource Management: Used try-with-resources for the Scanner.
 */
public class ChessCheck {

    /**
     * Represents the types of chess pieces relevant to the problem.
     */
    enum PieceType {
        ROOK, BISHOP, QUEEN, KING
    }

    /**
     * Represents the 8 cardinal and ordinal directions relative to the King.
     */
    enum Direction {
        NORTH, NORTH_EAST, EAST, SOUTH_EAST, SOUTH, SOUTH_WEST, WEST, NORTH_WEST
    }

    public static void main(String[] args) {
        // Use try-with-resources to ensure Scanner is closed automatically
        try (Scanner scanner = new Scanner(System.in)) {

            // Read number of pieces
            if (!scanner.hasNextLong()) return;
            long numPieces = scanner.nextLong();

            long kingX = scanner.nextLong();
            long kingY = scanner.nextLong();

            // Maps to store the closest piece and its distance for each of the 8 directions.
            // Initialized to null and MAX_VALUE respectively.
            Map<Direction, PieceType> closestPieces = new EnumMap<>(Direction.class);
            Map<Direction, Long> distances = new EnumMap<>(Direction.class);

            for (Direction d : Direction.values()) {
                distances.put(d, Long.MAX_VALUE);
                closestPieces.put(d, null);
            }

            for (long i = 0; i < numPieces; i++) {
                String typeStr = scanner.next();
                // Use nextLong() to safely read coordinates into long variables
                long pieceX = scanner.nextLong();
                long pieceY = scanner.nextLong();

                // Calculate relative coordinates (vector from King to Piece)
                long dx = pieceX - kingX;
                long dy = pieceY - kingY;

                // Determine if the piece lies in one of the 8 attack lines
                Direction direction = getDirection(dx, dy);

                if (direction != null) {
                    // Calculate distance (Chebyshev distance)
                    // For orthogonal: max(|dx|, |dy|) works (one is 0).
                    // For diagonal: |dx| == |dy|, so max is correct.
                    long distance = Math.max(Math.abs(dx), Math.abs(dy));

                    // Update if this piece is closer than the previously recorded one in this direction
                    if (distance < distances.get(direction)) {
                        distances.put(direction, distance);
                        closestPieces.put(direction, parsePieceType(typeStr));
                    }
                }
            }

            boolean inCheck = false;

            // Check if the closest piece in any direction can attack the King
            for (Direction d : Direction.values()) {
                PieceType piece = closestPieces.get(d);
                if (piece == null) continue;

                boolean isOrthogonal = (d == Direction.NORTH || d == Direction.SOUTH || 
                                        d == Direction.EAST || d == Direction.WEST);
                boolean isDiagonal = (d == Direction.NORTH_EAST || d == Direction.NORTH_WEST || 
                                      d == Direction.SOUTH_EAST || d == Direction.SOUTH_WEST);

                boolean canAttack = false;

                // Rooks and Queens attack orthogonally
                if (isOrthogonal && (piece == PieceType.ROOK || piece == PieceType.QUEEN)) {
                    canAttack = true;
                }
                // Bishops and Queens attack diagonally
                else if (isDiagonal && (piece == PieceType.BISHOP || piece == PieceType.QUEEN)) {
                    canAttack = true;
                }

                if (canAttack) {
                    inCheck = true;
                    break;
                }
            }

            System.out.println(inCheck ? "YES" : "NO");

        } catch (Exception e) {
            // In a production environment, log this. 
            // For competitive programming, usually input is guaranteed valid.
            e.printStackTrace();
        }
    }

    /**
     * Determines the direction from the King to the piece based on relative coordinates.
     * Returns null if the piece is not in a direct line (orthogonal or diagonal).
     */
    private static Direction getDirection(long dx, long dy) {
        if (dx == 0) {
            // Vertical alignment
            if (dy == 0) return null; // Same position (should not happen)
            return dy > 0 ? Direction.SOUTH : Direction.NORTH;
        } else if (dy == 0) {
            // Horizontal alignment
            return dx > 0 ? Direction.EAST : Direction.WEST;
        } else if (Math.abs(dx) == Math.abs(dy)) {
            // Diagonal alignment
            if (dx > 0 && dy > 0) return Direction.SOUTH_EAST;
            if (dx > 0 && dy < 0) return Direction.NORTH_EAST;
            if (dx < 0 && dy > 0) return Direction.SOUTH_WEST;
            if (dx < 0 && dy < 0) return Direction.NORTH_WEST;
        }
        return null;
    }

    /**
     * Parses the string representation of a piece type into the PieceType enum.
     */
    private static PieceType parsePieceType(String type) {
        switch (type) {
            case "R": return PieceType.ROOK;
            case "B": return PieceType.BISHOP;
            case "Q": return PieceType.QUEEN;
            case "K": return PieceType.KING;
            default: return null;
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

public class Codechef {

    /**
     * Encapsulates boundary limits for a specific color/type.
     * Uses MIN/MAX_VALUE to represent unbounded edges.
     */
    static class Bounds {
        int leftXMax = Integer.MIN_VALUE;
        int rightXMin = Integer.MAX_VALUE;
        int downYMax = Integer.MIN_VALUE;
        int upYMin = Integer.MAX_VALUE;
        int diag1LeftXMax = Integer.MIN_VALUE;
        int diag1RightXMin = Integer.MAX_VALUE;
        int diag2LeftXMax = Integer.MIN_VALUE;
        int diag2RightXMin = Integer.MAX_VALUE;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter out = new PrintWriter(System.out);

        String line = br.readLine();
        if (line == null) {
            out.flush();
            return;
        }
        int n = Integer.parseInt(line.trim());

        StringTokenizer st = new StringTokenizer(br.readLine());
        int xk = Integer.parseInt(st.nextToken());
        int yk = Integer.parseInt(st.nextToken());

        Bounds bBounds = new Bounds();
        Bounds rBounds = new Bounds();

        for (int i = 0; i < n; i++) {
            line = br.readLine();
            if (line == null) break;
            st = new StringTokenizer(line);

            char type = st.nextToken().charAt(0);
            int x = Integer.parseInt(st.nextToken());
            int y = Integer.parseInt(st.nextToken());

            switch (type) {
                case 'B':
                    updateBounds(bBounds, x, y, xk, yk, true);
                    break;
                case 'R':
                    updateBounds(rBounds, x, y, xk, yk, true);
                    break;
                case 'Q':
                    // Q updates R bounds for horizontal/vertical axes
                    // and B bounds for diagonal axes
                    updateBounds(rBounds, x, y, xk, yk, false);
                    updateBounds(bBounds, x, y, xk, yk, true);
                    break;
                default:
                    // Ignore unexpected input types
                    break;
            }
        }

        // Check if any R bound strictly contains the corresponding B bound
        boolean flag = bBounds.leftXMax < rBounds.leftXMax ||
                       rBounds.rightXMin < bBounds.rightXMin ||
                       rBounds.upYMin < bBounds.upYMin ||
                       bBounds.downYMax < rBounds.downYMax ||
                       bBounds.diag1LeftXMax > rBounds.diag1LeftXMax ||
                       bBounds.diag1RightXMin < rBounds.diag1RightXMin ||
                       bBounds.diag2LeftXMax > rBounds.diag2LeftXMax ||
                       bBounds.diag2RightXMin < rBounds.diag2RightXMin;

        out.println(flag ? "YES" : "NO");
        out.close();
    }

    /**
     * Updates the provided Bounds object based on the new point coordinates.
     * 
     * @param bounds        The Bounds object to update
     * @param x             X coordinate of the new point
     * @param y             Y coordinate of the new point
     * @param xk            Reference X coordinate
     * @param yk            Reference Y coordinate
     * @param updateDiagonals Whether to update diagonal boundaries
     */
    private static void updateBounds(Bounds bounds, int x, int y, int xk, int yk, boolean updateDiagonals) {
        if (y == yk) {
            if (x < xk) {
                bounds.leftXMax = Math.max(bounds.leftXMax, x);
            } else if (x > xk) {
                bounds.rightXMin = Math.min(bounds.rightXMin, x);
            }
        } else if (x == xk) {
            if (y < yk) {
                bounds.downYMax = Math.max(bounds.downYMax, y);
            } else if (y > yk) {
                bounds.upYMin = Math.min(bounds.upYMin, y);
            }
        } else if (updateDiagonals) {
            if (x + y == xk + yk) {
                if (x < xk) {
                    bounds.diag1LeftXMax = Math.max(bounds.diag1LeftXMax, x);
                } else if (x > xk) {
                    bounds.diag1RightXMin = Math.min(bounds.diag1RightXMin, x);
                }
            } else if (x - y == xk - yk) {
                if (x < xk) {
                    bounds.diag2LeftXMax = Math.max(bounds.diag2LeftXMax, x);
                } else if (x > xk) {
                    bounds.diag2RightXMin = Math.min(bounds.diag2RightXMin, x);
                }
            }
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;

public class Main {
    private static final int NUM_DIRECTIONS = 8;

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));

        String line = br.readLine();
        if (line == null) return;
        int numPieces = Integer.parseInt(line.trim());

        String[] kingLine = br.readLine().trim().split("\\s+");
        int kingX = Integer.parseInt(kingLine[0]);
        int kingY = Integer.parseInt(kingLine[1]);

        List<List<PieceCandidate>> candidates = new ArrayList<>(NUM_DIRECTIONS);
        for (int i = 0; i < NUM_DIRECTIONS; i++) {
            candidates.add(new ArrayList<>());
        }

        for (int i = 0; i < numPieces; i++) {
            String[] pieceLine = br.readLine().trim().split("\\s+");
            char pieceType = pieceLine[0].charAt(0);
            int pieceX = Integer.parseInt(pieceLine[1]);
            int pieceY = Integer.parseInt(pieceLine[2]);

            int diffX = kingX - pieceX;
            int diffY = kingY - pieceY;

            int direction = getDirectionIndex(diffX, diffY);
            if (direction == -1) {
                continue;
            }

            int distance = calculateDistance(diffX, diffY);
            boolean isEligible = canAttackAlongDirection(pieceType, direction);

            candidates.get(direction).add(new PieceCandidate(distance, isEligible));
        }

        boolean inCheck = false;
        for (int d = 0; d < NUM_DIRECTIONS && !inCheck; d++) {
            List<PieceCandidate> dirCandidates = candidates.get(d);
            if (!dirCandidates.isEmpty()) {
                dirCandidates.sort(Comparator.comparingInt(PieceCandidate::getDistance));
                if (dirCandidates.get(0).isEligible()) {
                    inCheck = true;
                }
            }
        }

        System.out.println(inCheck ? "YES" : "NO");
    }

    /**
     * Maps the relative position of a piece to the king to a direction index (0-7).
     * 0: Up, 1: Up-Right, 2: Right, 3: Down-Right, 4: Down, 5: Down-Left, 6: Left, 7: Up-Left
     * Returns -1 if the piece is not aligned with the king.
     */
    private static int getDirectionIndex(int diffX, int diffY) {
        if (diffX == 0 && diffY > 0) return 0;
        if (diffX > 0 && diffY > 0) return 1;
        if (diffX > 0 && diffY == 0) return 2;
        if (diffX > 0 && diffY < 0) return 3;
        if (diffX == 0 && diffY < 0) return 4;
        if (diffX < 0 && diffY < 0) return 5;
        if (diffX < 0 && diffY == 0) return 6;
        if (diffX < 0 && diffY > 0) return 7;
        return -1;
    }

    /**
     * Calculates the distance from the piece to the king.
     * For orthogonal directions, it's the absolute difference in X or Y.
     * For diagonal directions, it's the absolute difference in X (or Y, as they are equal).
     */
    private static int calculateDistance(int diffX, int diffY) {
        return Math.max(Math.abs(diffX), Math.abs(diffY));
    }

    /**
     * Determines if a piece can attack along a specific direction.
     * Orthogonal directions (0, 2, 4, 6) are attacked by Rooks (R) and Queens (Q).
     * Diagonal directions (1, 3, 5, 7) are attacked by Bishops (B) and Queens (Q).
     */
    private static boolean canAttackAlongDirection(char pieceType, int direction) {
        boolean isOrthogonal = (direction % 2 == 0);
        if (isOrthogonal) {
            return pieceType == 'R' || pieceType == 'Q';
        }
        return pieceType == 'B' || pieceType == 'Q';
    }

    /**
     * Represents a candidate piece in a specific direction relative to the king.
     */
    private static class PieceCandidate {
        private final int distance;
        private final boolean isEligible;

        public PieceCandidate(int distance, boolean isEligible) {
            this.distance = distance;
            this.isEligible = isEligible;
        }

        public int getDistance() {
            return distance;
        }

        public boolean isEligible() {
            return isEligible;
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.OutputStream;
import java.io.PrintWriter;
import java.util.Arrays;
import java.util.StringTokenizer;

public class Main {

    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);

        TaskD solver = new TaskD();
        // Removed unused testNumber argument for cleaner API
        solver.solve(in, out);

        out.close();
    }

    static class TaskD {
        private static final int NUM_DIRECTIONS = 8;
        private static final int MAX_VALUE = Integer.MAX_VALUE;
        private static final char QUEEN = 'Q';
        private static final char BISHOP = 'B';
        private static final char ROOK = 'R';

        public void solve(InputReader in, PrintWriter out) {
            int n = in.nextInt();
            int x0 = in.nextInt();
            int y0 = in.nextInt();

            // Arrays to store the closest piece type and distance for each of the 8 directions
            char[] closestPiece = new char[NUM_DIRECTIONS];
            int[] minDistance = new int[NUM_DIRECTIONS];
            Arrays.fill(minDistance, MAX_VALUE);

            for (int i = 0; i < n; i++) {
                String typeStr = in.next();
                char pieceType = typeStr.charAt(0);
                int x = in.nextInt();
                int y = in.nextInt();

                int direction = getDirection(x - x0, y - y0);
                if (direction != -1) {
                    // Chebyshev distance: max(|dx|, |dy|)
                    int dist = Math.max(Math.abs(x - x0), Math.abs(y - y0));
                    if (dist < minDistance[direction]) {
                        minDistance[direction] = dist;
                        closestPiece[direction] = pieceType;
                    }
                }
            }

            boolean canAttack = false;
            for (int d = 0; d < NUM_DIRECTIONS; d++) {
                if (canPieceAttack(closestPiece[d], d)) {
                    canAttack = true;
                    break;
                }
            }

            out.println(canAttack ? "YES" : "NO");
        }

        /**
         * Determines the direction index (0-7) for a given vector (dx, dy).
         * 0: Up (0, +)
         * 1: Up-Right (+, +)
         * 2: Right (+, 0)
         * 3: Down-Right (+, -)
         * 4: Down (0, -)
         * 5: Down-Left (-, -)
         * 6: Left (-, 0)
         * 7: Up-Left (-, +)
         * Returns -1 if the vector is (0,0) or not aligned with axes/diagonals.
         */
        private int getDirection(int dx, int dy) {
            if (dx == 0 && dy > 0) return 0;       // Up
            if (dx == dy && dy > 0) return 1;      // Up-Right
            if (dy == 0 && dx > 0) return 2;       // Right
            if (dx == -dy && dy < 0) return 3;     // Down-Right
            if (dx == 0 && dy < 0) return 4;       // Down
            if (dx == dy && dy < 0) return 5;      // Down-Left
            if (dy == 0 && dx < 0) return 6;       // Left
            if (-dx == dy && dy > 0) return 7;     // Up-Left
            return -1;
        }

        /**
         * Checks if a piece of the given type can attack the center from the given direction.
         * - Queen ('Q') attacks in all 8 directions.
         * - Bishop ('B') attacks only in diagonal directions (odd indices: 1, 3, 5, 7).
         * - Rook ('R') attacks only in cardinal directions (even indices: 0, 2, 4, 6).
         */
        private boolean canPieceAttack(char pieceType, int directionIndex) {
            if (pieceType == QUEEN) {
                return true;
            }
            if (pieceType == BISHOP && directionIndex % 2 != 0) {
                return true;
            }
            if (pieceType == ROOK && directionIndex % 2 == 0) {
                return true;
            }
            return false;
        }
    }

    static class InputReader {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public InputReader(InputStream inputStream) {
            reader = new BufferedReader(new InputStreamReader(inputStream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) {
                        throw new IOException("End of input");
                    }
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

public class ChessCheck {

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner(System.in);
        int numPieces = scanner.nextInt();
        int kingX = scanner.nextInt();
        int kingY = scanner.nextInt();

        // Stores the closest piece in each of the 8 directions from the king
        DirectionInfo[] closestPieces = new DirectionInfo[8];

        for (int i = 0; i < numPieces; i++) {
            char pieceType = scanner.next().charAt(0);
            int pieceX = scanner.nextInt();
            int pieceY = scanner.nextInt();

            int deltaX = pieceX - kingX;
            int deltaY = pieceY - kingY;

            // Determine direction index (0-7) or -1 if not in line of sight
            int direction = getDirectionIndex(deltaX, deltaY);
            if (direction == -1) {
                continue;
            }

            // Use squared distance to avoid floating-point arithmetic and legacy AWT classes
            int squaredDistance = deltaX * deltaX + deltaY * deltaY;
            int dirIndex = direction;

            // Keep track of the closest piece in this direction
            if (closestPieces[dirIndex] == null || squaredDistance < closestPieces[dirIndex].squaredDistance) {
                closestPieces[dirIndex] = new DirectionInfo(pieceType, squaredDistance);
            }
        }

        // Check if any closest piece is attacking the king
        boolean isCheck = false;
        for (int dir = 0; dir < 8; dir++) {
            DirectionInfo info = closestPieces[dir];
            if (info != null) {
                // Queens attack in all directions.
                // Rooks attack in orthogonal directions (even indices: 0, 2, 4, 6).
                // Bishops attack in diagonal directions (odd indices: 1, 3, 5, 7).
                boolean isAttacking = info.type == 'Q' ||
                        (dir % 2 == 0 && info.type == 'R') ||
                        (dir % 2 != 0 && info.type == 'B');

                if (isAttacking) {
                    isCheck = true;
                    break;
                }
            }
        }

        System.out.println(isCheck ? "YES" : "NO");
    }

    /**
     * Maps the relative position (deltaX, deltaY) to a direction index 0-7.
     * Returns -1 if the piece is not in a straight line (horizontal, vertical, or diagonal).
     * 
     * Mapping convention:
     * 0: East, 1: SE, 2: South, 3: SW, 4: West, 5: NW, 6: North, 7: NE
     */
    private static int getDirectionIndex(int dx, int dy) {
        if (dx == 0 && dy == 0) {
            return -1; // Same square as king
        }
        if (dy == 0) {
            return dx > 0 ? 0 : 4; // Horizontal
        }
        if (dx == 0) {
            return dy > 0 ? 2 : 6; // Vertical
        }
        if (Math.abs(dx) != Math.abs(dy)) {
            return -1; // Not diagonal
        }
        // Diagonal
        if (dy > 0) {
            return dx > 0 ? 1 : 3; // SE, SW
        } else {
            return dx > 0 ? 7 : 5; // NE, NW
        }
    }

    /**
     * Encapsulates piece type and its squared distance from the king.
     * Replaces parallel arrays for safer, more readable state management.
     */
    private static class DirectionInfo {
        final char type;
        final int squaredDistance;

        DirectionInfo(char type, int squaredDistance) {
            this.type = type;
            this.squaredDistance = squaredDistance;
        }
    }

    /**
     * Fast input reader optimized for competitive programming style problems.
     * Replaces the original FS class with proper exception handling and null safety.
     */
    private static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) {
                        return null;
                    }
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input stream", e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            String token = next();
            return token == null ? 0 : Integer.parseInt(token);
        }
    }
}

import java.util.Scanner;

/**
 * Refactored ChessCheck program.
 * 
 * Improvements made:
 * 1. Readability: Used meaningful variable names and constants.
 * 2. Maintainability: Encapsulated piece data in a class and separated logic into helper methods.
 * 3. Robustness: Used try-with-resources for Scanner and added basic input validation.
 * 4. Performance: Used squared distance for comparisons to avoid floating-point operations.
 * 5. Clarity: Replaced nested if-else chains with clear directional logic.
 */
public class ChessCheck {

    // Constants for the 8 directions around the King
    // 0: East, 1: NE, 2: North, 3: NW, 4: West, 5: SW, 6: South, 7: SE
    private static final int NUM_DIRECTIONS = 8;
    private static final int DIR_EAST = 0;
    private static final int DIR_NORTHEAST = 1;
    private static final int DIR_NORTH = 2;
    private static final int DIR_NORTHWEST = 3;
    private static final int DIR_WEST = 4;
    private static final int DIR_SOUTHWEST = 5;
    private static final int DIR_SOUTH = 6;
    private static final int DIR_SOUTHEAST = 7;

    /**
     * Represents a chess piece on the board.
     */
    private static class Piece {
        char type;
        int x, y;
        int distanceSquared;

        public Piece(char type, int x, int y, int distanceSquared) {
            this.type = type;
            this.x = x;
            this.y = y;
            this.distanceSquared = distanceSquared;
        }
    }

    public static void main(String[] args) {
        // Use try-with-resources to ensure Scanner is closed
        try (Scanner scanner = new Scanner(System.in)) {
            if (!scanner.hasNextInt()) {
                return;
            }

            int numPieces = scanner.nextInt();
            int kingX = scanner.nextInt();
            int kingY = scanner.nextInt();

            // Array to store the closest piece in each of the 8 directions
            Piece[] closestPieces = new Piece[NUM_DIRECTIONS];

            for (int i = 0; i < numPieces; i++) {
                char type = scanner.next().charAt(0);
                int px = scanner.nextInt();
                int py = scanner.nextInt();

                int dx = px - kingX;
                int dy = py - kingY;

                // Determine direction and alignment
                int direction = getDirection(dx, dy);

                if (direction != -1) {
                    int distSq = dx * dx + dy * dy;

                    // Update the closest piece in this direction if none exists or if this one is closer
                    if (closestPieces[direction] == null || distSq < closestPieces[direction].distanceSquared) {
                        closestPieces[direction] = new Piece(type, px, py, distSq);
                    }
                }
            }

            if (isKingInCheck(closestPieces)) {
                System.out.println("YES");
            } else {
                System.out.println("NO");
            }
        }
    }

    /**
     * Determines the direction index (0-7) based on the delta coordinates.
     * Returns -1 if the piece is not aligned with the King (not in check range).
     */
    private static int getDirection(int dx, int dy) {
        // A piece cannot be on the King's square
        if (dx == 0 && dy == 0) {
            return -1;
        }

        // Orthogonal directions
        if (dx == 0) {
            return (dy > 0) ? DIR_NORTH : DIR_SOUTH;
        }
        if (dy == 0) {
            return (dx > 0) ? DIR_EAST : DIR_WEST;
        }

        // Diagonal directions
        if (Math.abs(dx) == Math.abs(dy)) {
            if (dx > 0) {
                return (dy > 0) ? DIR_NORTHEAST : DIR_SOUTHEAST;
            } else {
                return (dy > 0) ? DIR_NORTHWEST : DIR_SOUTHWEST;
            }
        }

        // Not aligned (e.g., Knight move)
        return -1;
    }

    /**
     * Checks if the King is in check based on the closest pieces in each direction.
     */
    private static boolean isKingInCheck(Piece[] closestPieces) {
        for (int i = 0; i < NUM_DIRECTIONS; i++) {
            Piece piece = closestPieces[i];
            if (piece != null) {
                if (canAttackInDirection(piece.type, i)) {
                    return true;
                }
            }
        }
        return false;
    }

    /**
     * Determines if a piece type can attack in a specific direction.
     * Even indices (0, 2, 4, 6) are orthogonal (Rook/Queen).
     * Odd indices (1, 3, 5, 7) are diagonal (Bishop/Queen).
     */
    private static boolean canAttackInDirection(char pieceType, int directionIndex) {
        boolean isOrthogonal = (directionIndex % 2 == 0);
        boolean isDiagonal = (directionIndex % 2 != 0);

        if (pieceType == 'Q') {
            return true; // Queen attacks both
        } else if (pieceType == 'R') {
            return isOrthogonal; // Rook attacks orthogonal
        } else if (pieceType == 'B') {
            return isDiagonal; // Bishop attacks diagonal
        }

        // Other pieces (King, Pawn, Knight) do not attack in this specific logic context
        return false;
    }
}

import java.io.*;
import java.util.*;

/**
 * Analyzes a chess board to determine if any piece attacks a target coordinate.
 * Refactored for maintainability, readability, and adherence to Java best practices.
 */
public class BoardPieceAnalyzer {

    /**
     * Represents a chess piece on the board.
     * Sorted by Manhattan distance from the target coordinate.
     */
    private static class Piece implements Comparable<Piece> {
        final char type;
        final int x;
        final int y;
        final long distance;

        public Piece(char type, int x, int y, long distance) {
            this.type = type;
            this.x = x;
            this.y = y;
            this.distance = distance;
        }

        @Override
        public int compareTo(Piece other) {
            return Long.compare(this.distance, other.distance);
        }
    }

    public static void main(String[] args) {
        new BoardPieceAnalyzer().run();
    }

    private void run() {
        FastScanner scanner = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out));
        try {
            solve(scanner, out);
        } catch (IOException e) {
            out.println("Error processing input: " + e.getMessage());
        } finally {
            out.flush();
        }
    }

    private void solve(FastScanner scanner, PrintWriter out) throws IOException {
        int n = scanner.nextInt();
        long x0 = scanner.nextLong();
        long y0 = scanner.nextLong();

        Piece[] pieces = new Piece[n];
        for (int i = 0; i < n; i++) {
            char type = scanner.nextToken().charAt(0);
            int x = scanner.nextInt();
            int y = scanner.nextInt();
            long dist = Math.abs((long) x - x0) + Math.abs((long) y - y0);
            pieces[i] = new Piece(type, x, y, dist);
        }

        // Process pieces from closest to furthest
        Arrays.sort(pieces);

        // Tracks visited directions around (x0, y0).
        // Index mapping: 0:N, 1:NE, 2:E, 3:SE, 4:S, 5:SW, 6:W, 7:NW
        boolean[] visitedDirections = new boolean[8];

        for (Piece piece : pieces) {
            int dx = piece.x - x0;
            int dy = piece.y - y0;
            int dirIdx = getDirectionIndex(dx, dy);

            // Skip pieces exactly at the target location
            if (dirIdx == -1) continue;

            // If this direction has already been processed, skip
            if (visitedDirections[dirIdx]) continue;

            // Check if the piece lies on a row, column, or diagonal relative to target
            boolean attacks = (dx == 0 || dy == 0) || Math.abs((long) dx) == Math.abs((long) dy);
            if (attacks) {
                visitedDirections[dirIdx] = true;
            }

            // Check specific piece attack conditions
            if (piece.type == 'R' && (dx == 0 || dy == 0)) {
                out.println("YES");
                return;
            }
            if (piece.type == 'B' && Math.abs((long) dx) == Math.abs((long) dy)) {
                out.println("YES");
                return;
            }
        }

        out.println("NO");
    }

    /**
     * Maps relative coordinates (dx, dy) to a direction index (0-7).
     * Returns -1 if the piece is exactly at the origin (x0, y0).
     */
    private int getDirectionIndex(int dx, int dy) {
        if (dx == 0) {
            return dy > 0 ? 0 : 4; // N, S
        } else if (dy == 0) {
            return dx > 0 ? 2 : 6; // E, W
        } else {
            if (dx > 0 && dy > 0) return 1; // NE
            if (dx > 0 && dy < 0) return 3; // SE
            if (dx < 0 && dy < 0) return 5; // SW
            return 7; // NW
        }
    }

    /**
     * High-performance I/O utility for competitive programming and fast data reading.
     */
    private static class FastScanner {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastScanner(InputStream stream) {
            this.reader = new BufferedReader(new InputStreamReader(stream));
            this.tokenizer = null;
        }

        public String nextToken() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                String line = reader.readLine();
                if (line == null) {
                    throw new IOException("Unexpected end of input");
                }
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(nextToken());
        }

        public long nextLong() throws IOException {
            return Long.parseLong(nextToken());
        }
    }
}

import java.io.BufferedReader;
import java.io.FileNotFoundException;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.OutputStream;
import java.io.PrintWriter;
import java.util.StringTokenizer;

public class Main {

    public static void main(String[] args) {
        InputStream inputStream;

        // Handle development testing input redirection
        // Check length > 1 to safely access args[1]
        if (args.length > 1 && "devTesting".equals(args[0])) {
            try {
                inputStream = new FileInputStream(args[1]);
            } catch (FileNotFoundException e) {
                throw new RuntimeException("Input file not found: " + args[1], e);
            }
        } else {
            inputStream = System.in;
        }

        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);

        ChessSolver solver = new ChessSolver();
        solver.solve(in, out);

        out.close();
    }

    /**
     * Solves the chess threat problem.
     * Determines if the position (x0, y0) is under attack by the closest pieces
     * in the 8 cardinal and intercardinal directions.
     */
    static class ChessSolver {

        // Direction constants corresponding to indices 0-7
        // 0: Right, 1: Up-Right, 2: Up, 3: Up-Left, 4: Left, 5: Down-Left, 6: Down, 7: Down-Right
        private static final int DIR_RIGHT = 0;
        private static final int DIR_UP_RIGHT = 1;
        private static final int DIR_UP = 2;
        private static final int DIR_UP_LEFT = 3;
        private static final int DIR_LEFT = 4;
        private static final int DIR_DOWN_LEFT = 5;
        private static final int DIR_DOWN = 6;
        private static final int DIR_DOWN_RIGHT = 7;

        private static final long INF = Long.MAX_VALUE / 2;

        void solve(InputReader in, PrintWriter out) {
            int n = in.nextInt();
            // Use nextLong() to support larger coordinate ranges safely
            long x0 = in.nextLong();
            long y0 = in.nextLong();

            // Arrays to store the closest piece distance and type for each of the 8 directions
            long[] minDistance = new long[8];
            char[] closestPiece = new char[8];

            // Initialize distances to infinity and pieces to null
            for (int i = 0; i < 8; i++) {
                minDistance[i] = INF;
                closestPiece[i] = 0; 
            }

            for (int i = 0; i < n; i++) {
                char pieceType = in.next().charAt(0);
                long xi = in.nextLong();
                long yi = in.nextLong();

                long dx = xi - x0;
                long dy = yi - y0;

                int directionIndex = -1;
                long distance = 0;

                // Determine which of the 8 directions the point (xi, yi) lies in relative to (x0, y0)
                // This replaces the 8 separate if-blocks with a cleaner geometric check
                if (dx == 0) {
                    if (dy > 0) {
                        directionIndex = DIR_UP;
                        distance = dy;
                    } else if (dy < 0) {
                        directionIndex = DIR_DOWN;
                        distance = -dy;
                    }
                } else if (dy == 0) {
                    if (dx > 0) {
                        directionIndex = DIR_RIGHT;
                        distance = dx;
                    } else if (dx < 0) {
                        directionIndex = DIR_LEFT;
                        distance = -dx;
                    }
                } else if (Math.abs(dx) == Math.abs(dy)) {
                    // Diagonal directions
                    if (dx > 0 && dy > 0) {
                        directionIndex = DIR_UP_RIGHT;
                        distance = dx;
                    } else if (dx < 0 && dy > 0) {
                        directionIndex = DIR_UP_LEFT;
                        distance = -dx;
                    } else if (dx < 0 && dy < 0) {
                        directionIndex = DIR_DOWN_LEFT;
                        distance = -dx;
                    } else if (dx > 0 && dy < 0) {
                        directionIndex = DIR_DOWN_RIGHT;
                        distance = dx;
                    }
                }

                // If the point lies on a valid direction ray, update the closest piece info
                if (directionIndex != -1) {
                    if (distance < minDistance[directionIndex]) {
                        minDistance[directionIndex] = distance;
                        closestPiece[directionIndex] = pieceType;
                    }
                }
            }

            boolean isSafe = true;

            // Check Orthogonal directions (0, 2, 4, 6) for Rook/Queen threats
            // Indices: 0 (Right), 2 (Up), 4 (Left), 6 (Down)
            for (int i = 0; i < 8; i += 2) {
                if (closestPiece[i] != 0) {
                    if (closestPiece[i] == 'R' || closestPiece[i] == 'Q') {
                        isSafe = false;
                        break;
                    }
                }
            }

            // Check Diagonal directions (1, 3, 5, 7) for Bishop/Queen threats
            // Indices: 1 (Up-Right), 3 (Up-Left), 5 (Down-Left), 7 (Down-Right)
            if (isSafe) {
                for (int i = 1; i < 8; i += 2) {
                    if (closestPiece[i] != 0) {
                        if (closestPiece[i] == 'B' || closestPiece[i] == 'Q') {
                            isSafe = false;
                            break;
                        }
                    }
                }
            }

            // Output result based on original logic: 
            // If safe (isSafe=true), print "NO". If threat found (isSafe=false), print "YES".
            out.println(isSafe ? "NO" : "YES");
        }
    }

    /**
     * Helper class for fast input reading.
     */
    static class InputReader {
        public BufferedReader reader;
        public StringTokenizer tokenizer;

        public InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return tokenizer.nextToken();
        }

        public String nextLine() {
            try {
                return reader.readLine();
            } catch (IOException e) {
                throw new RuntimeException("Error reading line", e);
            }
        }

        public int nextInt() {
            String s = next();
            if (s == null) throw new RuntimeException("Unexpected end of input");
            return Integer.parseInt(s);
        }

        public long nextLong() {
            String s = next();
            if (s == null) throw new RuntimeException("Unexpected end of input");
            return Long.parseLong(s);
        }

        public double nextDouble() {
            String s = next();
            if (s == null) throw new RuntimeException("Unexpected end of input");
            return Double.parseDouble(s);
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.Arrays;
import java.util.StringTokenizer;

public class Main {
    private static final int NUM_DIRECTIONS = 8;
    private static final long MAX_DISTANCE = Long.MAX_VALUE;

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line = br.readLine();
        if (line == null || line.trim().isEmpty()) {
            return;
        }

        int numOfPieces = Integer.parseInt(line.trim());
        StringTokenizer st = new StringTokenizer(br.readLine());
        int kingX = Integer.parseInt(st.nextToken());
        int kingY = Integer.parseInt(st.nextToken());
        Piece king = new Piece(kingX, kingY, 'K');

        Piece[] nearestPieces = new Piece[NUM_DIRECTIONS];
        long[] nearestDistances = new long[NUM_DIRECTIONS];
        Arrays.fill(nearestDistances, MAX_DISTANCE);

        for (int i = 0; i < numOfPieces; i++) {
            st = new StringTokenizer(br.readLine());
            String typeStr = st.nextToken();
            int pieceX = Integer.parseInt(st.nextToken());
            int pieceY = Integer.parseInt(st.nextToken());
            Piece piece = new Piece(pieceX, pieceY, typeStr.charAt(0));

            int direction = king.getDirection(piece);
            if (direction != -1) {
                long distance = king.getDistance(piece);
                if (nearestPieces[direction] == null || nearestDistances[direction] > distance) {
                    nearestPieces[direction] = piece;
                    nearestDistances[direction] = distance;
                }
            }
        }

        boolean isCheck = false;
        for (int i = 0; i < NUM_DIRECTIONS; i++) {
            Piece nearest = nearestPieces[i];
            if (nearest != null && canAttack(nearest, i)) {
                isCheck = true;
                break;
            }
        }

        System.out.println(isCheck ? "YES" : "NO");
    }

    /**
     * Determines if a piece in a given direction can attack the king.
     * Directions 0, 2, 4, 6 represent cardinal directions (N, E, S, W).
     * Directions 1, 3, 5, 7 represent diagonal directions (NE, SE, SW, NW).
     */
    private static boolean canAttack(Piece piece, int direction) {
        char type = piece.getType();
        boolean isCardinal = (direction % 2) == 0;
        boolean isDiagonal = (direction % 2) != 0;

        if (type == 'Q') return true;
        if (type == 'R' && isCardinal) return true;
        if (type == 'B' && isDiagonal) return true;
        return false;
    }
}

/**
 * Represents a chess piece on the board.
 */
class Piece {
    private final int x;
    private final int y;
    private final char type;

    public Piece(int x, int y, char type) {
        this.x = x;
        this.y = y;
        this.type = type;
    }

    /**
     * Calculates the relative direction from this piece to the target piece.
     * Returns 0-7 for the 8 compass directions, or -1 if not aligned.
     */
    public int getDirection(Piece piece) {
        int dx = piece.x - this.x;
        int dy = piece.y - this.y;

        if (dx == 0 && dy == 1) return 0;       // North
        if (dx == 1 && dy == 1) return 1;       // Northeast
        if (dx == 1 && dy == 0) return 2;       // East
        if (dx == 1 && dy == -1) return 3;      // Southeast
        if (dx == 0 && dy == -1) return 4;      // South
        if (dx == -1 && dy == -1) return 5;     // Southwest
        if (dx == -1 && dy == 0) return 6;      // West
        if (dx == -1 && dy == 1) return 7;      // Northwest

        return -1; // Not in any of the 8 directions
    }

    /**
     * Calculates the Manhattan distance to the target piece.
     */
    public long getDistance(Piece piece) {
        return Math.abs((long) this.x - piece.x) + Math.abs((long) this.y - piece.y);
    }

    public char getType() {
        return type;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

public class Main {
    public static void main(String[] args) {
        FastScanner in = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out);
        new Solver().solve(in, out);
        out.close();
    }

    static class Solver {
        public void solve(FastScanner in, PrintWriter out) {
            int n = in.nextInt();
            int targetX = in.nextInt();
            int targetY = in.nextInt();

            // Track the closest piece in each of the 4 directional lines
            int minVertDist = Integer.MAX_VALUE;
            char closestVertType = ' ';

            int minHorizDist = Integer.MAX_VALUE;
            char closestHorizType = ' ';

            int minDiagMainDist = Integer.MAX_VALUE;
            char closestDiagMainType = ' ';

            int minDiagAntiDist = Integer.MAX_VALUE;
            char closestDiagAntiType = ' ';

            for (int i = 0; i < n; i++) {
                char type = in.next().charAt(0);
                int x = in.nextInt();
                int y = in.nextInt();

                // Check vertical line (same column)
                if (x == targetX) {
                    int dist = Math.abs(y - targetY);
                    if (dist < minVertDist) {
                        minVertDist = dist;
                        closestVertType = type;
                    }
                }
                // Check horizontal line (same row)
                if (y == targetY) {
                    int dist = Math.abs(x - targetX);
                    if (dist < minHorizDist) {
                        minHorizDist = dist;
                        closestHorizType = type;
                    }
                }
                // Check main diagonal (y - x == constant)
                if (y - x == targetY - targetX) {
                    int dist = Math.abs(x - targetX);
                    if (dist < minDiagMainDist) {
                        minDiagMainDist = dist;
                        closestDiagMainType = type;
                    }
                }
                // Check anti-diagonal (y + x == constant)
                if (y + x == targetY + targetX) {
                    int dist = Math.abs(x - targetX);
                    if (dist < minDiagAntiDist) {
                        minDiagAntiDist = dist;
                        closestDiagAntiType = type;
                    }
                }
            }

            // Determine if any closest piece can attack the target
            boolean canAttack = (minVertDist != Integer.MAX_VALUE && isRookOrQueen(closestVertType))
                             || (minHorizDist != Integer.MAX_VALUE && isRookOrQueen(closestHorizType))
                             || (minDiagMainDist != Integer.MAX_VALUE && isBishopOrQueen(closestDiagMainType))
                             || (minDiagAntiDist != Integer.MAX_VALUE && isBishopOrQueen(closestDiagAntiType));

            out.println(canAttack ? "YES" : "NO");
        }

        private boolean isRookOrQueen(char type) {
            return type == 'R' || type == 'Q';
        }

        private boolean isBishopOrQueen(char type) {
            return type == 'B' || type == 'Q';
        }
    }

    static class FastScanner {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastScanner(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            String s = next();
            return s == null ? 0 : Integer.parseInt(s);
        }
    }
}

import java.util.Scanner;
import java.util.Set;

/**
 * Solves a chessboard attack detection problem.
 * Determines if a starting position is threatened by the closest piece 
 * in any of the 8 cardinal/diagonal directions.
 */
public class ChessAttackChecker {

    // Threat types for orthogonal and diagonal directions
    private static final Set<String> ORTHOGONAL_THREATS = Set.of("R", "Q");
    private static final Set<String> DIAGONAL_THREATS = Set.of("B", "Q");

    public static void main(String[] args) {
        // Use try-with-resources to guarantee Scanner closure
        try (Scanner scanner = new Scanner(System.in)) {
            if (!scanner.hasNextLong()) {
                return;
            }

            long numPieces = scanner.nextLong();
            long startX = scanner.nextLong();
            long startY = scanner.nextLong();

            // Track the closest piece type and distance for each of the 8 directions
            String closestNorth = null, closestSouth = null;
            String closestEast = null, closestWest = null;
            String closestNorthEast = null, closestNorthWest = null;
            String closestSouthEast = null, closestSouthWest = null;

            long distNorth = Long.MAX_VALUE, distSouth = Long.MAX_VALUE;
            long distEast = Long.MAX_VALUE, distWest = Long.MAX_VALUE;
            long distNorthEast = Long.MAX_VALUE, distNorthWest = Long.MAX_VALUE;
            long distSouthEast = Long.MAX_VALUE, distSouthWest = Long.MAX_VALUE;

            for (long i = 0; i < numPieces; i++) {
                String pieceType = scanner.next();
                long pieceX = scanner.nextLong();
                long pieceY = scanner.nextLong();

                // Calculate relative position from the starting point
                long dx = pieceX - startX;
                long dy = pieceY - startY;

                // Determine direction and update closest piece if applicable
                if (dx == 0) {
                    // Vertical alignment
                    if (dy > 0 && dy < distNorth) {
                        distNorth = dy;
                        closestNorth = pieceType;
                    } else if (dy < 0 && Math.abs(dy) < distSouth) {
                        distSouth = Math.abs(dy);
                        closestSouth = pieceType;
                    }
                } else if (dy == 0) {
                    // Horizontal alignment
                    if (dx > 0 && dx < distEast) {
                        distEast = dx;
                        closestEast = pieceType;
                    } else if (dx < 0 && Math.abs(dx) < distWest) {
                        distWest = Math.abs(dx);
                        closestWest = pieceType;
                    }
                } else if (Math.abs(dx) == Math.abs(dy)) {
                    // Diagonal alignment
                    if (dx > 0 && dy < 0 && dx < distSouthEast) {
                        distSouthEast = dx;
                        closestSouthEast = pieceType;
                    } else if (dx < 0 && dy < 0 && Math.abs(dx) < distSouthWest) {
                        distSouthWest = Math.abs(dx);
                        closestSouthWest = pieceType;
                    } else if (dx > 0 && dy > 0 && dx < distNorthEast) {
                        distNorthEast = dx;
                        closestNorthEast = pieceType;
                    } else if (dx < 0 && dy > 0 && Math.abs(dx) < distNorthWest) {
                        distNorthWest = Math.abs(dx);
                        closestNorthWest = pieceType;
                    }
                }
            }

            // Check if any closest piece in orthogonal directions is a Rook or Queen
            boolean isOrthogonallyThreatened = isThreatened(closestNorth, ORTHOGONAL_THREATS) ||
                                               isThreatened(closestSouth, ORTHOGONAL_THREATS) ||
                                               isThreatened(closestEast, ORTHOGONAL_THREATS) ||
                                               isThreatened(closestWest, ORTHOGONAL_THREATS);

            // Check if any closest piece in diagonal directions is a Bishop or Queen
            boolean isDiagonallyThreatened = isThreatened(closestNorthEast, DIAGONAL_THREATS) ||
                                             isThreatened(closestNorthWest, DIAGONAL_THREATS) ||
                                             isThreatened(closestSouthEast, DIAGONAL_THREATS) ||
                                             isThreatened(closestSouthWest, DIAGONAL_THREATS);

            System.out.print(isOrthogonallyThreatened || isDiagonallyThreatened ? "YES" : "NO");
        }
    }

    /**
     * Checks if a given piece type is in the set of threat types.
     * Handles null pieces gracefully.
     */
    private static boolean isThreatened(String piece, Set<String> threats) {
        return piece != null && threats.contains(piece);
    }
}

import java.io.*;
import java.util.StringTokenizer;

/**
 * Solves the "Anton and Chess" problem by determining if the king is under attack.
 * Reads piece positions and checks if any piece threatens the king from the closest
 * position in any of the 8 cardinal/diagonal directions.
 */
public class AntonAndChess {

    /**
     * Represents a chess piece on the board.
     */
    private static class Piece {
        final char type;
        final int x;
        final int y;

        Piece(char type, int x, int y) {
            this.type = type;
            this.x = x;
            this.y = y;
        }

        @Override
        public String toString() {
            return String.format("TYPE: %c(%d, %d)", type, x, y);
        }
    }

    /**
     * Solves the problem for a single test case.
     */
    private static void solve(FastScanner scanner, PrintWriter out) {
        int n = scanner.nextInt();
        int kingX = scanner.nextInt();
        int kingY = scanner.nextInt();

        // 3x3 grid representing the 8 directions around the king.
        // [0][0] Top-Left    [0][1] Top    [0][2] Top-Right
        // [1][0] Left        [1][1] King   [1][2] Right
        // [2][0] Bottom-Left [2][1] Bottom [2][2] Bottom-Right
        Piece[][] closestPieces = new Piece[3][3];

        for (int i = 0; i < n; i++) {
            char type = scanner.nextChar();
            int x = scanner.nextInt();
            int y = scanner.nextInt();
            updateClosestPiece(closestPieces, kingX, kingY, type, x, y);
        }

        // Expected piece types for each direction to threaten the king.
        // Preserved exactly from the original logic.
        char[][] expectedTypes = {
            {'R', 'B', 'R'},
            {'B', '*', 'B'},
            {'R', 'B', 'R'}
        };

        boolean isSafe = true;
        for (int row = 0; row < 3; row++) {
            for (int col = 0; col < 3; col++) {
                Piece piece = closestPieces[row][col];
                if (piece != null && piece.type != expectedTypes[row][col]) {
                    isSafe = false;
                }
            }
        }

        out.println(isSafe ? "NO" : "YES");
    }

    /**
     * Determines which direction a piece belongs to relative to the king
     * and updates the board if it's the closest piece in that direction.
     */
    private static void updateClosestPiece(Piece[][] board, int kx, int ky, char type, int x, int y) {
        if (x == kx) {
            if (y > ky) update(board, 1, 2, type, x, y, ky);
            else if (y < ky) update(board, 1, 0, type, x, y, ky);
        } else if (y == ky) {
            if (x > kx) update(board, 2, 1, type, x, y, kx);
            else if (x < kx) update(board, 0, 1, type, x, y, kx);
        } else if (x - y == kx - ky) {
            if (x > kx) update(board, 2, 2, type, x, y, kx);
            else if (x < kx) update(board, 0, 0, type, x, y, kx);
        } else if (x + y == kx + ky) {
            if (x > kx) update(board, 2, 0, type, x, y, kx);
            else if (x < kx) update(board, 0, 2, type, x, y, kx);
        }
    }

    /**
     * Places a piece in the board if it's closer to the king than the existing one.
     */
    private static void update(Piece[][] board, int r, int c, char type, int x, int y, int kingCoord) {
        if (board[r][c] == null) {
            board[r][c] = new Piece(type, x, y);
        } else {
            int currentDist = Math.abs(board[r][c].x - kingCoord) + Math.abs(board[r][c].y - kingCoord);
            int newDist = Math.abs(x - kingCoord) + Math.abs(y - kingCoord);
            if (newDist < currentDist) {
                board[r][c] = new Piece(type, x, y);
            }
        }
    }

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)));
        try {
            solve(scanner, out);
        } finally {
            out.flush();
            scanner.close();
        }
    }

    /**
     * Fast input reader optimized for competitive programming.
     */
    static class FastScanner {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        FastScanner(InputStream stream) {
            this.reader = new BufferedReader(new InputStreamReader(stream));
            this.tokenizer = null;
        }

        String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input", e);
                }
            }
            return tokenizer.nextToken();
        }

        String nextLine() {
            try {
                return reader.readLine();
            } catch (IOException e) {
                throw new RuntimeException("Failed to read line", e);
            }
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        long nextLong() {
            return Long.parseLong(next());
        }

        double nextDouble() {
            return Double.parseDouble(next());
        }

        char nextChar() {
            return next().charAt(0);
        }

        int[] nextIntArray(int n) {
            int[] arr = new int[n];
            for (int i = 0; i < n; i++) arr[i] = nextInt();
            return arr;
        }

        long[] nextLongArray(int n) {
            long[] arr = new long[n];
            for (int i = 0; i < n; i++) arr[i] = nextLong();
            return arr;
        }

        int[] nextIntArrayOneBased(int n) {
            int[] arr = new int[n + 1];
            for (int i = 1; i <= n; i++) arr[i] = nextInt();
            return arr;
        }

        long[] nextLongArrayOneBased(int n) {
            long[] arr = new long[n + 1];
            for (int i = 1; i <= n; i++) arr[i] = nextLong();
            return arr;
        }

        void close() {
            try {
                reader.close();
            } catch (IOException e) {
                throw new RuntimeException("Failed to close scanner", e);
            }
        }
    }
}

import java.io.*;
import java.util.NoSuchElementException;
import java.util.StringTokenizer;

public class Main {

    /**
     * Represents a chess piece with relative coordinates and type.
     */
    static class Piece {
        final long dx, dy;
        final char type;

        Piece(long dx, long dy, char type) {
            this.dx = dx;
            this.dy = dy;
            this.type = type;
        }

        long manhattanDistance() {
            return Math.abs(dx) + Math.abs(dy);
        }
    }

    /**
     * Fast I/O helper using BufferedReader and StringTokenizer.
     * Replaces the verbose custom scanner with a standard, readable, and robust implementation.
     */
    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) throw new NoSuchElementException();
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        long nextLong() {
            return Long.parseLong(next());
        }
    }

    public static void main(String[] args) {
        FastScanner in = new FastScanner();
        PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out));
        new Main().solve(in, out);
        out.flush();
        out.close();
    }

    void solve(FastScanner in, PrintWriter out) {
        int n = in.nextInt();
        long centerX = in.nextLong();
        long centerY = in.nextLong();

        // Rook directions: 0=Left(-x), 1=Right(+x), 2=Down(-y), 3=Up(+y)
        Piece[] rookDirections = new Piece[4];
        // Bishop directions: 0=NE(+x,+y), 1=SE(+x,-y), 2=NW(-x,+y), 3=SW(-x,-y)
        Piece[] bishopDirections = new Piece[4];

        for (int i = 0; i < n; i++) {
            char type = in.next().charAt(0);
            long dx = in.nextLong() - centerX;
            long dy = in.nextLong() - centerY;

            if (dx == 0 || dy == 0) {
                int dirIdx = -1;
                if (dx < 0) dirIdx = 0;
                else if (dx > 0) dirIdx = 1;
                else if (dy < 0) dirIdx = 2;
                else if (dy > 0) dirIdx = 3;

                updateClosest(rookDirections, dirIdx, new Piece(dx, dy, type));
            } else if (Math.abs(dx) == Math.abs(dy)) {
                int dirIdx = -1;
                if (dx > 0 && dy > 0) dirIdx = 0;
                else if (dx > 0 && dy < 0) dirIdx = 1;
                else if (dx < 0 && dy > 0) dirIdx = 2;
                else if (dx < 0 && dy < 0) dirIdx = 3;

                updateClosest(bishopDirections, dirIdx, new Piece(dx, dy, type));
            }
        }

        boolean possible = false;
        for (Piece p : bishopDirections) {
            if (p != null && p.type != 'R') {
                possible = true;
                break;
            }
        }

        if (!possible) {
            for (Piece p : rookDirections) {
                if (p != null && p.type != 'B') {
                    possible = true;
                    break;
                }
            }
        }

        out.println(possible ? "YES" : "NO");
    }

    /**
     * Updates the closest piece in a given direction if the current piece is closer.
     */
    private void updateClosest(Piece[] directions, int idx, Piece current) {
        if (directions[idx] == null || current.manhattanDistance() < directions[idx].manhattanDistance()) {
            directions[idx] = current;
        }
    }
}

import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

/**
 * A program to analyze a chess board and determine if the King is under threat
 * by any of the placed pieces (Rooks, Bishops, or Queens).
 */
public class ChessThreatAnalyzer {

    /**
     * Represents a coordinate on the board.
     * x: Horizontal position
     * y: Vertical position
     */
    private static class Coordinate {
        long x;
        long y;

        Coordinate(long x, long y) {
            this.x = x;
            this.y = y;
        }
    }

    /**
     * Enum representing the type of chess piece.
     */
    private enum PieceType {
        ROOK, BISHOP, QUEEN
    }

    /**
     * Represents a chess piece on the board.
     */
    private static class Piece {
        Coordinate pos;
        PieceType type;

        Piece(long x, long y, PieceType type) {
            this.pos = new Coordinate(x, y);
            this.type = type;
        }
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        // Read the number of pieces
        if (!scanner.hasNextInt()) {
            return;
        }
        int n = scanner.nextInt();

        // Read the King's position
        if (!scanner.hasNextLong()) {
            return;
        }
        long kingX = scanner.nextLong();
        long kingY = scanner.nextLong();
        // Consume the rest of the line after reading longs
        scanner.nextLine();

        Coordinate kingPos = new Coordinate(kingX, kingY);
        List<Piece> pieces = new ArrayList<>();

        // Read each piece
        for (int i = 0; i < n; i++) {
            String line = scanner.nextLine().trim();
            if (line.isEmpty()) {
                continue;
            }

            // Split by whitespace to handle multiple spaces
            String[] parts = line.split("\\s+");
            if (parts.length < 3) {
                continue;
            }

            char typeChar = parts[0].charAt(0);
            long x = Long.parseLong(parts[1]);
            long y = Long.parseLong(parts[2]);

            PieceType type;
            if (typeChar == 'R') {
                type = PieceType.ROOK;
            } else if (typeChar == 'B') {
                type = PieceType.BISHOP;
            } else {
                // Default to Queen for 'Q' or any other character
                type = PieceType.QUEEN;
            }
            pieces.add(new Piece(x, y, type));
        }

        // Check if any piece threatens the King
        boolean isThreatened = false;
        for (Piece piece : pieces) {
            if (isThreateningKing(piece, kingPos, pieces)) {
                isThreatened = true;
                break;
            }
        }

        System.out.println(isThreatened ? "YES" : "NO");
        scanner.close();
    }

    /**
     * Determines if a specific piece threatens the King.
     *
     * @param attacker The piece to check.
     * @param king     The King's position.
     * @param allPieces List of all pieces on the board (to check for blocking).
     * @return true if the King is threatened, false otherwise.
     */
    private static boolean isThreateningKing(Piece attacker, Coordinate king, List<Piece> allPieces) {
        Coordinate pos = attacker.pos;

        // 1. Check Rook/Queen moves (Horizontal and Vertical lines)
        if (attacker.type == PieceType.ROOK || attacker.type == PieceType.QUEEN) {
            // Same horizontal line (x) or same vertical line (y)
            if (pos.x == king.x || pos.y == king.y) {
                if (!isBlocked(pos, king, allPieces)) {
                    return true;
                }
            }
        }

        // 2. Check Bishop/Queen moves (Diagonals)
        if (attacker.type == PieceType.BISHOP || attacker.type == PieceType.QUEEN) {
            // Diagonals: |x1 - x2| == |y1 - y2|
            if (Math.abs(pos.x - king.x) == Math.abs(pos.y - king.y)) {
                if (!isBlocked(pos, king, allPieces)) {
                    return true;
                }
            }
        }

        return false;
    }

    /**
     * Checks if there is any piece strictly between the start and end coordinates.
     *
     * @param start     The attacker's position.
     * @param end       The target's position (King).
     * @param allPieces List of all pieces on the board.
     * @return true if the path is blocked, false if clear.
     */
    private static boolean isBlocked(Coordinate start, Coordinate end, List<Piece> allPieces) {
        for (Piece p : allPieces) {
            // Skip the attacker itself
            if (p.pos.x == start.x && p.pos.y == start.y) {
                continue;
            }
            // Skip the King (though King is not in the list, it's good practice)
            if (p.pos.x == end.x && p.pos.y == end.y) {
                continue;
            }

            // Check if piece p lies strictly between start and end.
            // Since we know they are collinear (checked in caller),
            // we just need to check if p is within the bounding box defined by start and end.

            // Handle Vertical Lines (x is constant)
            if (start.x == end.x) {
                if (p.pos.y > Math.min(start.y, end.y) && p.pos.y < Math.max(start.y, end.y)) {
                    return true;
                }
            } 
            // Handle Horizontal and Diagonal Lines (y varies or x varies)
            else {
                // For horizontal or diagonal lines, checking one coordinate range is sufficient
                // because the points are collinear. We check X here.
                if (p.pos.x > Math.min(start.x, end.x) && p.pos.x < Math.max(start.x, end.x)) {
                    return true;
                }
            }
        }
        return false;
    }
}

import java.util.Scanner;
import java.util.Arrays;

/**
 * Refactored Chess Attack Checker.
 * Determines if a starting position on a chess board is under attack
 * by any of the given pieces.
 */
public class ChessAttackSolver {

    // Enum to represent piece types, replacing magic numbers 0, 1, 2
    enum PieceType {
        ROOK(0),
        BISHOP(1),
        QUEEN(2);

        final int code;

        PieceType(int code) {
            this.code = code;
        }
    }

    // Helper class to store piece details
    static class Piece {
        int row;
        int col;
        int type; // 0: Rook, 1: Bishop, 2: Queen

        Piece(int row, int col, int type) {
            this.row = row;
            this.col = col;
            this.type = type;
        }
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        // Read number of pieces
        String nLine = scanner.nextLine();
        if (nLine == null || nLine.trim().isEmpty()) {
            return;
        }
        int n = Integer.parseInt(nLine.trim());

        // Read starting position (x, y)
        String[] startParts = scanner.nextLine().trim().split("\\s+");
        int startX = Integer.parseInt(startParts[0]);
        int startY = Integer.parseInt(startParts[1]);

        // Arrays to store the closest piece found in each of the 8 directions.
        // Indices 0-7 correspond to the 8 directions.
        Piece[] closestPieces = new Piece[8];
        long[] minDistances = new long[8];
        Arrays.fill(minDistances, Long.MAX_VALUE);

        for (int i = 0; i < n; i++) {
            String pieceLine = scanner.nextLine().trim();
            // Split by one or more whitespace characters to handle irregular spacing
            String[] parts = pieceLine.split("\\s+");

            String typeStr = parts[0];
            int pieceX = Integer.parseInt(parts[1]);
            int pieceY = Integer.parseInt(parts[2]);

            // Map string type to integer code (R->0, B->1, Else->2)
            int typeCode;
            if (typeStr.equals("R")) {
                typeCode = PieceType.ROOK.code;
            } else if (typeStr.equals("B")) {
                typeCode = PieceType.BISHOP.code;
            } else {
                typeCode = PieceType.QUEEN.code;
            }

            // Calculate vector from Piece to Start
            // dx = startX - pieceX
            // dy = startY - pieceY
            int dx = startX - pieceX;
            int dy = startY - pieceY;

            int directionIndex = getDirectionIndex(dx, dy);

            if (directionIndex != -1) {
                // Calculate Chebyshev distance (max of absolute differences)
                long dist = Math.max(Math.abs(dx), Math.abs(dy));

                // Update if this piece is closer than the current closest in this direction
                if (dist < minDistances[directionIndex]) {
                    minDistances[directionIndex] = dist;
                    closestPieces[directionIndex] = new Piece(pieceX, pieceY, typeCode);
                }
            }
        }

        // Check if any of the closest pieces can attack the starting position
        boolean isAttacked = false;
        for (Piece piece : closestPieces) {
            if (piece == null) {
                continue;
            }

            // Calculate relative position from the piece to the start
            int relDx = startX - piece.row;
            int relDy = startY - piece.col;

            boolean isRookOrQueen = (piece.type == PieceType.ROOK.code || piece.type == PieceType.QUEEN.code);
            boolean isBishopOrQueen = (piece.type == PieceType.BISHOP.code || piece.type == PieceType.QUEEN.code);

            // Check if the piece is aligned horizontally/vertically
            boolean isStraightLine = (relDx == 0 || relDy == 0);
            // Check if the piece is aligned diagonally
            boolean isDiagonalLine = (Math.abs(relDx) == Math.abs(relDy));

            if ((isRookOrQueen && isStraightLine) || (isBishopOrQueen && isDiagonalLine)) {
                isAttacked = true;
                break;
            }
        }

        System.out.println(isAttacked ? "YES" : "NO");
        scanner.close();
    }

    /**
     * Determines the direction index (0-7) based on the vector (dx, dy).
     * Returns -1 if the points are identical or not aligned in a straight line.
     *
     * Direction Mapping (based on vector from Piece to Start):
     * 0: (0, 1)   - Positive Y
     * 1: (0, -1)  - Negative Y
     * 2: (1, 0)   - Positive X
     * 3: (-1, 0)  - Negative X
     * 4: (1, 1)   - Positive X, Positive Y (Diagonal)
     * 5: (-1, -1) - Negative X, Negative Y (Diagonal)
     * 6: (1, -1)  - Positive X, Negative Y (Diagonal)
     * 7: (-1, 1)  - Negative X, Positive Y (Diagonal)
     */
    private static int getDirectionIndex(int dx, int dy) {
        int signX = Integer.signum(dx);
        int signY = Integer.signum(dy);

        // If both components are 0, the points are identical
        if (signX == 0 && signY == 0) {
            return -1;
        }

        // Check alignment
        if (signX == 0) {
            // Vertical movement (dx is 0)
            if (signY > 0) return 0;
            else return 1;
        } else if (signY == 0) {
            // Horizontal movement (dy is 0)
            if (signX > 0) return 2;
            else return 3;
        } else {
            // Diagonal movement check
            // For a valid diagonal, absolute values of dx and dy must be equal
            if (Math.abs(dx) == Math.abs(dy)) {
                if (signX > 0 && signY > 0) return 4;
                if (signX < 0 && signY < 0) return 5;
                if (signX > 0 && signY < 0) return 6;
                if (signX < 0 && signY > 0) return 7;
            }
        }

        return -1; // Not aligned
    }
}

import java.io.*;
import java.util.*;

public class Main {
    private FastScanner in;
    private PrintWriter out;

    private void solve() throws IOException {
        int n = in.nextInt();
        int kingX = in.nextInt();
        int kingY = in.nextInt();

        char[] types = new char[n];
        int[] xCoords = new int[n];
        int[] yCoords = new int[n];

        for (int i = 0; i < n; i++) {
            types[i] = in.next().charAt(0);
            xCoords[i] = in.nextInt();
            yCoords[i] = in.nextInt();
        }

        // Check all 4 board orientations (0°, 90°, 180°, 270°)
        for (int rot = 0; rot < 4; rot++) {
            // Create immutable transformed objects for this rotation
            Piece transformedKing = new Piece('K', kingX, kingY);
            Piece[] transformedFigures = new Piece[n];
            for (int i = 0; i < n; i++) {
                transformedFigures[i] = new Piece(types[i], xCoords[i], yCoords[i]);
            }

            // Apply rotation 'rot' times immutably
            for (int r = 0; r < rot; r++) {
                transformedKing = transformedKing.rotated();
                for (int i = 0; i < n; i++) {
                    transformedFigures[i] = transformedFigures[i].rotated();
                }
            }

            // Group pieces by vertical line (same x) and diagonal (same x - y)
            Map<Integer, TreeSet<Piece>> verticalMap = new HashMap<>();
            Map<Integer, TreeSet<Piece>> diagonalMap = new HashMap<>();

            for (Piece p : transformedFigures) {
                verticalMap.computeIfAbsent(p.x, k -> new TreeSet<>((a, b) -> Integer.compare(a.y, b.y))).add(p);
                diagonalMap.computeIfAbsent(p.x - p.y, k -> new TreeSet<>((a, b) -> Integer.compare(a.y, b.y))).add(p);
            }

            // Check vertical attacks (Rook/Queen)
            TreeSet<Piece> verticalPieces = verticalMap.get(transformedKing.x);
            if (verticalPieces != null && 
                (isAttacking(verticalPieces.lower(transformedKing), 'R', 'Q') ||
                 isAttacking(verticalPieces.higher(transformedKing), 'R', 'Q'))) {
                out.println("YES");
                return;
            }

            // Check diagonal attacks (Bishop/Queen)
            TreeSet<Piece> diagonalPieces = diagonalMap.get(transformedKing.x - transformedKing.y);
            if (diagonalPieces != null && 
                (isAttacking(diagonalPieces.lower(transformedKing), 'B', 'Q') ||
                 isAttacking(diagonalPieces.higher(transformedKing), 'B', 'Q'))) {
                out.println("YES");
                return;
            }
        }

        out.println("NO");
    }

    /**
     * Checks if a piece attacks the king based on its type.
     * Returns false if the piece is null (no piece in that direction).
     */
    private boolean isAttacking(Piece piece, char... validTypes) {
        if (piece == null) return false;
        for (char v : validTypes) {
            if (piece.type == v) return true;
        }
        return false;
    }

    private void run() throws IOException {
        in = new FastScanner();
        out = new PrintWriter(System.out, false);
        solve();
        out.close();
    }

    public static void main(String[] args) throws IOException {
        new Main().run();
    }

    /**
     * Immutable representation of a chess piece.
     * Rotation is performed by returning a new instance.
     */
    static class Piece {
        final char type;
        final int x, y;

        Piece(char type, int x, int y) {
            this.type = type;
            this.x = x;
            this.y = y;
        }

        Piece rotated() {
            // 90-degree clockwise rotation: (x, y) -> (-y, x)
            return new Piece(type, -y, x);
        }
    }
}

/**
 * Fast I/O utility for competitive programming.
 * Kept largely unchanged to preserve input parsing behavior.
 */
class FastScanner {
    private final BufferedReader br;
    private StringTokenizer st;
    private String last;

    public FastScanner() {
        br = new BufferedReader(new InputStreamReader(System.in));
    }

    public FastScanner(String path) throws IOException {
        br = new BufferedReader(new FileReader(path));
    }

    public FastScanner(String path, String decoder) throws IOException {
        br = new BufferedReader(new InputStreamReader(new FileInputStream(path), decoder));
    }

    String next() throws IOException {
        while (st == null || !st.hasMoreElements()) {
            String line = br.readLine();
            if (line == null) return null;
            st = new StringTokenizer(line);
        }
        last = null;
        return st.nextToken();
    }

    String nextLine() throws IOException {
        st = null;
        return (last == null) ? br.readLine() : last;
    }

    boolean hasNext() {
        if (st != null && st.hasMoreElements())
            return true;

        try {
            while (st == null || !st.hasMoreElements()) {
                String line = br.readLine();
                if (line == null) return false;
                last = line;
                st = new StringTokenizer(line);
            }
        } catch (Exception e) {
            return false;
        }

        return true;
    }

    String[] nextStrings(int n) throws IOException {
        String[] arr = new String[n];
        for (int i = 0; i < n; i++)
            arr[i] = next();
        return arr;
    }

    String[] nextLines(int n) throws IOException {
        String[] arr = new String[n];
        for (int i = 0; i < n; i++)
            arr[i] = nextLine();
        return arr;
    }

    int nextInt() throws IOException {
        return Integer.parseInt(next());
    }

    int[] nextInts(int n) throws IOException {
        int[] arr = new int[n];
        for (int i = 0; i < n; i++)
            arr[i] = nextInt();
        return arr;
    }

    Integer[] nextIntegers(int n) throws IOException {
        Integer[] arr = new Integer[n];
        for (int i = 0; i < n; i++)
            arr[i] = nextInt();
        return arr;
    }

    int[][] next2Ints(int n, int m) throws IOException {
        int[][] arr = new int[n][m];
        for (int i = 0; i < n; i++)
            for (int j = 0; j < m; j++)
                arr[i][j] = nextInt();
        return arr;
    }

    long nextLong() throws IOException {
        return Long.parseLong(next());
    }

    long[] nextLongs(int n) throws IOException {
        long[] arr = new long[n];
        for (int i = 0; i < n; i++)
            arr[i] = nextLong();
        return arr;
    }

    long[][] next2Longs(int n, int m) throws IOException {
        long[][] arr = new long[n][m];
        for (int i = 0; i < n; i++)
            for (int j = 0; j < m; j++)
                arr[i][j] = nextLong();
        return arr;
    }

    double nextDouble() throws IOException {
        return Double.parseDouble(next().replace(',', '.'));
    }

    double[] nextDoubles(int size) throws IOException {
        double[] arr = new double[size];
        for (int i = 0; i < size; i++)
            arr[i] = nextDouble();
        return arr;
    }

    boolean nextBool() throws IOException {
        String s = next();
        if (s.equalsIgnoreCase("true") || s.equals("1"))
            return true;

        if (s.equalsIgnoreCase("false") || s.equals("0"))
            return false;

        throw new IOException("Boolean expected, String found!");
    }

    public double[][] next2Doubles(int n, int m) throws IOException {
        double[][] arr = new double[n][];
        for (int i = 0; i < n; i++) {
            arr[i] = nextDoubles(m);
        }
        return arr;
    }
}

import java.io.*;
import java.util.*;

public class D_379_div2 {

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out));
        try {
            solve(scanner, out);
        } catch (IOException e) {
            e.printStackTrace();
        } finally {
            out.flush();
            out.close();
        }
    }

    /**
     * Represents the type of chess piece.
     * Renamed from BKR to PieceType for better semantic clarity.
     */
    enum PieceType {
        ROOK, BISHOP, QUEEN
    }

    /**
     * Immutable representation of a chess piece relative to the king's position.
     */
    static class Piece {
        final PieceType type;
        final long dx;
        final long dy;

        Piece(PieceType type, long dx, long dy) {
            this.type = type;
            this.dx = dx;
            this.dy = dy;
        }
    }

    /**
     * Core logic to determine if the king is under attack.
     */
    static void solve(FastScanner in, PrintWriter out) throws IOException {
        int n = in.nextInt();
        long kingX = in.nextLong();
        long kingY = in.nextLong();

        Piece[] pieces = new Piece[n];
        for (int i = 0; i < n; i++) {
            String typeStr = in.next();
            PieceType type = parsePieceType(typeStr);
            // Transform coordinates to be relative to the king (king becomes 0,0)
            long x = in.nextLong() - kingX;
            long y = in.nextLong() - kingY;
            pieces[i] = new Piece(type, x, y);
        }

        // Note: Original code sorted pieces by Manhattan distance but never used the result.
        // Removed to eliminate O(n log n) dead code.

        boolean isAttacked = false;
        for (Piece piece : pieces) {
            long dx = piece.dx;
            long dy = piece.dy;

            // Check if piece lies on an axis or diagonal relative to the king
            boolean onAxis = (dx == 0) || (dy == 0);
            boolean onDiagonal = (Math.abs(dx) == Math.abs(dy));

            if (piece.type == PieceType.ROOK && onAxis) {
                isAttacked = true;
            } else if (piece.type == PieceType.BISHOP && onDiagonal) {
                isAttacked = true;
            } else if (piece.type == PieceType.QUEEN && (onAxis || onDiagonal)) {
                isAttacked = true;
            }
        }

        out.println(isAttacked ? "YES" : "NO");
    }

    private static PieceType parsePieceType(String symbol) {
        switch (symbol) {
            case "R": return PieceType.ROOK;
            case "B": return PieceType.BISHOP;
            case "Q": return PieceType.QUEEN;
            default:
                throw new IllegalArgumentException("Invalid piece symbol: " + symbol);
        }
    }

    /**
     * Fast I/O helper class to replace repetitive static method boilerplate.
     */
    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        String next() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) {
                    throw new EOFException("Unexpected end of input");
                }
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        long nextLong() throws IOException {
            return Long.parseLong(next());
        }
    }
}

import java.util.Scanner;

/**
 * Refactored version of AntonPotions.
 * 
 * Improvements made:
 * 1. Readability: Replaced magic numbers and cryptic variable names (ik, jk, xs, ps) 
 *    with descriptive names (centerX, centerY, closestVal, potionType).
 * 2. Maintainability: Defined constants for the 8 directions (NORTH, SOUTH, etc.) 
 *    to remove magic numbers and clarify the logic.
 * 3. Logic Simplification: Replaced the complex parity-based check (it % 2) with 
 *    explicit checks for Cardinal (Rook) and Diagonal (Bishop) directions.
 * 4. Robustness: Used try-with-resources for Scanner and avoided potential integer 
 *    overflow by using difference checks (dx == -dy) instead of sum checks.
 */
public class AntonPotions {

    // Constants for the 8 directions around the center point
    // 0: North, 1: South, 2: East, 3: West
    // 4: North-East, 5: South-West, 6: North-West, 7: South-East
    private static final int NORTH = 0;
    private static final int SOUTH = 1;
    private static final int EAST = 2;
    private static final int WEST = 3;
    private static final int NORTH_EAST = 4;
    private static final int SOUTH_WEST = 5;
    private static final int NORTH_WEST = 6;
    private static final int SOUTH_EAST = 7;

    public static void main(String[] args) {
        // Use try-with-resources to ensure Scanner is closed properly
        try (Scanner sc = new Scanner(System.in)) {
            if (!sc.hasNextInt()) {
                return;
            }

            int n = sc.nextInt();
            int centerX = sc.nextInt(); // Represents 'ik' in original
            int centerY = sc.nextInt(); // Represents 'jk' in original

            // Arrays to store the closest coordinate value and the potion type for each direction.
            // closestVal stores the coordinate (x or y) of the potion closest to the center in that direction.
            // potionType stores the character ('Q', 'R', 'B') of that potion.
            int[] closestVal = new int[8];
            char[] potionType = new char[8]; // Default char is \u0000, acting as a "null" value

            // Initialize closestVal based on the direction logic:
            // For directions moving in positive axis (N, E, NE, NW), we look for the MINIMUM value (closest to center).
            // For directions moving in negative axis (S, W, SW, SE), we look for the MAXIMUM value (closest to center).
            closestVal[NORTH] = Integer.MAX_VALUE;
            closestVal[SOUTH] = Integer.MIN_VALUE;
            closestVal[EAST] = Integer.MAX_VALUE;
            closestVal[WEST] = Integer.MIN_VALUE;
            closestVal[NORTH_EAST] = Integer.MAX_VALUE;
            closestVal[SOUTH_WEST] = Integer.MIN_VALUE;
            closestVal[NORTH_WEST] = Integer.MAX_VALUE;
            closestVal[SOUTH_EAST] = Integer.MIN_VALUE;

            for (int k = 0; k < n; k++) {
                char type = sc.next().charAt(0);
                int x = sc.nextInt();
                int y = sc.nextInt();

                int dx = x - centerX;
                int dy = y - centerY;

                // Check if the potion lies on one of the 8 lines passing through the center
                if (dx == 0) {
                    // Vertical Line
                    if (dy > 0) {
                        // North
                        if (y < closestVal[NORTH]) {
                            closestVal[NORTH] = y;
                            potionType[NORTH] = type;
                        }
                    } else if (dy < 0) {
                        // South
                        if (y > closestVal[SOUTH]) {
                            closestVal[SOUTH] = y;
                            potionType[SOUTH] = type;
                        }
                    }
                } else if (dy == 0) {
                    // Horizontal Line
                    if (dx > 0) {
                        // East
                        if (x < closestVal[EAST]) {
                            closestVal[EAST] = x;
                            potionType[EAST] = type;
                        }
                    } else if (dx < 0) {
                        // West
                        if (x > closestVal[WEST]) {
                            closestVal[WEST] = x;
                            potionType[WEST] = type;
                        }
                    }
                } else if (dx == dy) {
                    // Diagonal 1 (x - y = constant)
                    if (dx > 0) {
                        // North-East
                        if (x < closestVal[NORTH_EAST]) {
                            closestVal[NORTH_EAST] = x;
                            potionType[NORTH_EAST] = type;
                        }
                    } else if (dx < 0) {
                        // South-West
                        if (x > closestVal[SOUTH_WEST]) {
                            closestVal[SOUTH_WEST] = x;
                            potionType[SOUTH_WEST] = type;
                        }
                    }
                } else if (dx == -dy) {
                    // Diagonal 2 (x + y = constant)
                    if (dx > 0) {
                        // North-West (x increases, y decreases)
                        if (x < closestVal[NORTH_WEST]) {
                            closestVal[NORTH_WEST] = x;
                            potionType[NORTH_WEST] = type;
                        }
                    } else if (dx < 0) {
                        // South-East (x decreases, y increases)
                        if (x > closestVal[SOUTH_EAST]) {
                            closestVal[SOUTH_EAST] = x;
                            potionType[SOUTH_EAST] = type;
                        }
                    }
                }
            }

            // Determine if a threat exists
            boolean threatExists = false;

            // 1. Queen ('Q') threatens in all 8 directions
            for (int i = 0; i < 8; i++) {
                if (potionType[i] == 'Q') {
                    threatExists = true;
                    break;
                }
            }

            // 2. Rook ('R') threatens in cardinal directions (N, S, E, W)
            if (!threatExists) {
                if (potionType[NORTH] == 'R' || potionType[SOUTH] == 'R' ||
                    potionType[EAST] == 'R' || potionType[WEST] == 'R') {
                    threatExists = true;
                }
            }

            // 3. Bishop ('B') threatens in diagonal directions (NE, SW, NW, SE)
            if (!threatExists) {
                if (potionType[NORTH_EAST] == 'B' || potionType[SOUTH_WEST] == 'B' ||
                    potionType[NORTH_WEST] == 'B' || potionType[SOUTH_EAST] == 'B') {
                    threatExists = true;
                }
            }

            System.out.println(threatExists ? "YES" : "NO");
        }
    }
}

import java.util.Scanner;

/**
 * Analyzes chess piece positions relative to a starting point to determine
 * if a Queen, Rook, or Bishop can reach the target in a single valid move.
 */
public class Main {

    private static final int NUM_DIRECTIONS = 8;
    private static final int INVALID_DIRECTION = -1;
    private static final int INITIAL_DISTANCE = Integer.MAX_VALUE;

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            if (!scanner.hasNextInt()) {
                return;
            }

            int n = scanner.nextInt();
            int startX = scanner.nextInt();
            int startY = scanner.nextInt();

            int[] minDistances = new int[NUM_DIRECTIONS];
            char[] nearestPieces = new char[NUM_DIRECTIONS];
            for (int i = 0; i < NUM_DIRECTIONS; i++) {
                minDistances[i] = INITIAL_DISTANCE;
            }

            for (int i = 0; i < n; i++) {
                char pieceType = scanner.next().charAt(0);
                int targetX = scanner.nextInt();
                int targetY = scanner.nextInt();

                int dx = targetX - startX;
                int dy = targetY - startY;
                int directionIndex = determineDirection(dx, dy);

                if (directionIndex != INVALID_DIRECTION) {
                    int distance = calculateDistance(dx, dy);
                    if (distance < minDistances[directionIndex]) {
                        minDistances[directionIndex] = distance;
                        nearestPieces[directionIndex] = pieceType;
                    }
                }
            }

            boolean isValidMove = checkValidPieceTypes(nearestPieces);
            System.out.println(isValidMove ? "YES" : "NO");
        }
    }

    /**
     * Determines the direction index (0-7) for a given delta (dx, dy).
     * Returns INVALID_DIRECTION if the delta does not align with a valid chess move.
     * 
     * Mapping:
     * 0: West, 1: North-West, 2: North, 3: North-East,
     * 4: East, 5: South-East, 6: South, 7: South-West
     */
    private static int determineDirection(int dx, int dy) {
        if (dx == 0) {
            return dy > 0 ? 2 : 6; // North or South
        }
        if (dy == 0) {
            return dx > 0 ? 4 : 0; // East or West
        }
        if (Math.abs(dx) == Math.abs(dy)) {
            if (dx > 0 && dy > 0) return 3; // North-East
            if (dx > 0 && dy < 0) return 5; // South-East
            if (dx < 0 && dy > 0) return 1; // North-West
            return 7; // South-West
        }
        return INVALID_DIRECTION;
    }

    /**
     * Calculates the Chebyshev distance for valid directions.
     * For orthogonal or diagonal moves, this equals max(|dx|, |dy|).
     */
    private static int calculateDistance(int dx, int dy) {
        return Math.max(Math.abs(dx), Math.abs(dy));
    }

    /**
     * Checks if any recorded piece type matches the movement rules for Q, R, or B.
     * Even indices represent orthogonal directions, odd indices represent diagonal.
     */
    private static boolean checkValidPieceTypes(char[] nearestPieces) {
        for (int i = 0; i < NUM_DIRECTIONS; i++) {
            char piece = nearestPieces[i];
            if (piece == 'Q') {
                return true; // Queen moves in all 8 directions
            }
            boolean isOrthogonal = (i % 2 == 0);
            boolean isDiagonal = (i % 2 == 1);
            if (isOrthogonal && piece == 'R') {
                return true; // Rook moves orthogonally
            }
            if (isDiagonal && piece == 'B') {
                return true; // Bishop moves diagonally
            }
        }
        return false;
    }
}

import java.io.IOException;
import java.util.InputMismatchException;

/**
 * Refactored chess attack checker.
 * 
 * Improvements over original:
 * - Removed hardcoded magic values and redundant distance tracking
 * - Simplified attack logic to direct condition checks
 * - Added early exit for performance
 * - Improved naming, structure, and documentation
 * - Removed unused classes and resources
 */
public class ChessAttackChecker {

    public static void main(String[] args) throws IOException {
        FasterScanner scanner = new FasterScanner();

        int n = scanner.nextInt();
        int targetX = scanner.nextInt();
        int targetY = scanner.nextInt();

        boolean canAttack = false;
        for (int i = 0; i < n; i++) {
            String pieceType = scanner.nextString();
            int pieceX = scanner.nextInt();
            int pieceY = scanner.nextInt();

            if (canAttackPiece(pieceType, pieceX, pieceY, targetX, targetY)) {
                canAttack = true;
                break; // Found an attacker, no need to check remaining pieces
            }
        }

        System.out.println(canAttack ? "YES" : "NO");
    }

    /**
     * Determines if a given piece can attack the target square.
     * Supported piece types: R (Rook), B (Bishop), Q (Queen)
     */
    private static boolean canAttackPiece(String pieceType, int pieceX, int pieceY, int targetX, int targetY) {
        int dx = Math.abs(pieceX - targetX);
        int dy = Math.abs(pieceY - targetY);

        boolean isOrthogonal = (dx == 0 || dy == 0);
        boolean isDiagonal = (dx == dy);

        // Rooks and Queens attack orthogonally
        if ("R".equals(pieceType) || "Q".equals(pieceType)) {
            if (isOrthogonal) return true;
        }

        // Bishops and Queens attack diagonally
        if ("B".equals(pieceType) || "Q".equals(pieceType)) {
            if (isDiagonal) return true;
        }

        return false;
    }

    /**
     * Fast I/O scanner optimized for competitive programming and large inputs.
     */
    public static class FasterScanner {
        private byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;

        public int read() {
            if (numChars == -1) {
                throw new InputMismatchException();
            }
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = System.in.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0) {
                    return -1;
                }
            }
            return buf[curChar++];
        }

        public String nextString() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            StringBuilder res = new StringBuilder();
            do {
                res.appendCodePoint(c);
                c = read();
            } while (!isSpaceChar(c));
            return res.toString();
        }

        public int nextInt() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                res *= 10;
                res += c - '0';
                c = read();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public long nextLong() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            long res = 0;
            do {
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                res *= 10;
                res += c - '0';
                c = read();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        private boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

public class ChessAttackChecker {

    // Direction indices: 0-3 are cardinal, 4-7 are diagonal
    private static final int DIR_LEFT = 0;
    private static final int DIR_RIGHT = 1;
    private static final int DIR_UP = 2;
    private static final int DIR_DOWN = 3;
    private static final int DIR_DIAG_1 = 4;
    private static final int DIR_DIAG_2 = 5;
    private static final int DIR_DIAG_3 = 6;
    private static final int DIR_DIAG_4 = 7;

    private static BufferedReader reader;
    private static StringTokenizer tokenizer;

    public static void main(String[] args) {
        try (BufferedReader initializedReader = new BufferedReader(new InputStreamReader(System.in))) {
            reader = initializedReader;
            boolean isAttacked = solve();
            System.out.println(isAttacked ? "YES" : "NO");
        } catch (IOException e) {
            System.err.println("Failed to read input: " + e.getMessage());
            System.exit(1);
        }
    }

    private static boolean solve() throws IOException {
        int n = nextInt();
        int targetX = nextInt();
        int targetY = nextInt();

        Piece[] nearestPieces = new Piece[8];

        for (int i = 0; i < n; i++) {
            char type = next().charAt(0);
            int x = nextInt();
            int y = nextInt();

            Piece piece = new Piece(type, x, y);
            int direction = getDirection(piece, targetX, targetY);

            if (direction != -1) {
                updateNearestPiece(nearestPieces, direction, piece, targetX, targetY);
            }
        }

        return isAttacked(nearestPieces);
    }

    /**
     * Determines which of the 8 directions a piece lies relative to the target.
     * Returns -1 if the piece is not aligned in a straight line or diagonal.
     */
    private static int getDirection(Piece piece, int targetX, int targetY) {
        int dx = piece.x - targetX;
        int dy = piece.y - targetY;

        if (dy == 0) return dx < 0 ? DIR_LEFT : DIR_RIGHT;
        if (dx == 0) return dy < 0 ? DIR_UP : DIR_DOWN;
        if (dx == dy) return dx < 0 ? DIR_DIAG_1 : DIR_DIAG_2;
        if (dx == -dy) return dx < 0 ? DIR_DIAG_3 : DIR_DIAG_4;
        return -1;
    }

    /**
     * Calculates the Chebyshev distance between two points.
     */
    private static int chebyshevDistance(int x1, int y1, int x2, int y2) {
        return Math.max(Math.abs(x1 - x2), Math.abs(y1 - y2));
    }

    /**
     * Updates the nearest piece in a given direction if the new piece is closer.
     */
    private static void updateNearestPiece(Piece[] nearestPieces, int direction, Piece piece, int targetX, int targetY) {
        Piece currentNearest = nearestPieces[direction];
        int currentDist = chebyshevDistance(piece.x, piece.y, targetX, targetY);

        if (currentNearest == null || currentDist < chebyshevDistance(currentNearest.x, currentNearest.y, targetX, targetY)) {
            nearestPieces[direction] = piece;
        }
    }

    /**
     * Checks if the target position is attacked by any nearest piece.
     * Rooks and Queens attack in cardinal directions (0-3).
     * Bishops and Queens attack in diagonal directions (4-7).
     */
    private static boolean isAttacked(Piece[] nearestPieces) {
        for (int i = 0; i < 4; i++) {
            Piece p = nearestPieces[i];
            if (p != null && (p.type == 'R' || p.type == 'Q')) {
                return true;
            }
        }
        for (int i = 4; i < 8; i++) {
            Piece p = nearestPieces[i];
            if (p != null && (p.type == 'B' || p.type == 'Q')) {
                return true;
            }
        }
        return false;
    }

    // --- Fast I/O Methods ---

    private static String next() throws IOException {
        while (tokenizer == null || !tokenizer.hasMoreTokens()) {
            String line = reader.readLine();
            if (line == null) {
                throw new IOException("Unexpected end of input");
            }
            tokenizer = new StringTokenizer(line);
        }
        return tokenizer.nextToken();
    }

    private static int nextInt() throws IOException {
        return Integer.parseInt(next());
    }

    // --- Data Classes ---

    public static class Piece {
        public final char type;
        public final int x;
        public final int y;

        public Piece(char type, int x, int y) {
            this.type = type;
            this.x = x;
            this.y = y;
        }
    }
}

import java.io.*;
import java.util.*;

public class Main {

    /**
     * Represents the 8 possible directions relative to the king.
     * Encapsulates axis-aligned vs diagonal classification and direction resolution.
     */
    enum Direction {
        NORTH(0, 1), SOUTH(0, -1), EAST(1, 0), WEST(-1, 0),
        NORTH_EAST(1, 1), NORTH_WEST(-1, 1), SOUTH_EAST(1, -1), SOUTH_WEST(-1, -1);

        final int dx, dy;

        Direction(int dx, int dy) {
            this.dx = dx;
            this.dy = dy;
        }

        boolean isHorizontalVertical() {
            return dx == 0 || dy == 0;
        }

        boolean isDiagonal() {
            return dx != 0 && dy != 0 && Math.abs(dx) == Math.abs(dy);
        }

        /**
         * Determines the Direction enum constant based on relative coordinates.
         * Returns null if the piece is not on the same row, column, or diagonal.
         */
        static Direction fromDelta(int dx, int dy) {
            if (dx == 0) return dy > 0 ? NORTH : SOUTH;
            if (dy == 0) return dx > 0 ? EAST : WEST;
            if (Math.abs(dx) != Math.abs(dy)) return null; // Not on a valid attack line
            if (dx > 0 && dy > 0) return NORTH_EAST;
            if (dx < 0 && dy > 0) return NORTH_WEST;
            if (dx > 0 && dy < 0) return SOUTH_EAST;
            return SOUTH_WEST;
        }
    }

    /**
     * Represents a chess piece with its type and relative position to the king.
     * Immutable design improves thread-safety and predictability.
     */
    static class Piece {
        final char type;
        final int dx, dy;

        Piece(char type, int dx, int dy) {
            this.type = type;
            this.dx = dx;
            this.dy = dy;
        }

        long manhattanDistance() {
            return Math.abs(dx) + Math.abs(dy);
        }

        boolean canAttackHorizontalVertical() {
            // Matches original logic: type != 'B' && type != 'N'
            return type != 'B' && type != 'N';
        }

        boolean canAttackDiagonal() {
            // Matches original logic: type != 'R' && type != 'N'
            return type != 'R' && type != 'N';
        }
    }

    public static void main(String[] args) {
        FastScanner sc = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            int n = sc.nextInt();
            int kingX = sc.nextInt();
            int kingY = sc.nextInt();

            // Stores the closest piece for each direction. EnumMap provides 
            // type-safe, ordered iteration and efficient lookup.
            Map<Direction, Piece> closestPieces = new EnumMap<>(Direction.class);

            for (int i = 0; i < n; i++) {
                char type = sc.next().charAt(0);
                int x = sc.nextInt();
                int y = sc.nextInt();

                int dx = x - kingX;
                int dy = y - kingY;

                Direction dir = Direction.fromDelta(dx, dy);
                if (dir != null) {
                    updateClosest(closestPieces, dir, new Piece(type, dx, dy));
                }
            }

            boolean canAttack = false;
            for (Direction dir : Direction.values()) {
                Piece piece = closestPieces.get(dir);
                if (piece != null) {
                    if (dir.isHorizontalVertical() && piece.canAttackHorizontalVertical()) {
                        canAttack = true;
                    }
                    if (dir.isDiagonal() && piece.canAttackDiagonal()) {
                        canAttack = true;
                    }
                }
            }

            out.println(canAttack ? "YES" : "NO");
        } finally {
            out.flush();
            out.close();
        }
    }

    /**
     * Updates the closest piece for a given direction if the new piece is closer.
     * Uses Map.merge() for clean, declarative state updates.
     */
    private static void updateClosest(Map<Direction, Piece> closest, Direction dir, Piece piece) {
        closest.merge(dir, piece, (existing, newPiece) ->
            newPiece.manhattanDistance() < existing.manhattanDistance() ? newPiece : existing);
    }

    /**
     * Lightweight Fast I/O class to replace java.util.Scanner for better performance.
     * Stripped down to only the methods required by the problem.
     */
    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.BufferedReader;
import java.io.BufferedOutputStream;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.Arrays;
import java.util.StringTokenizer;

/**
 * Refactored solution for checking chess piece threats from a reference point.
 * Determines if any Rook/Queen is closer than a Bishop/Queen in orthogonal directions,
 * or if any Bishop/Queen is closer than a Rook/Queen in diagonal directions.
 */
public class ChessThreatCheck {

    // Direction indices: 0-3 are orthogonal, 4-7 are diagonal
    private static final int ORTHOGONAL_START = 0;
    private static final int ORTHOGONAL_END = 3;
    private static final int DIAGONAL_START = 4;
    private static final int DIAGONAL_END = 7;
    private static final int MAX_DIRS = 8;
    private static final int MAX_VALUE = Integer.MAX_VALUE;

    public static void main(String[] args) throws IOException {
        FastScanner scanner = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out));

        solve(scanner, out);
        out.flush();
    }

    private static void solve(FastScanner in, PrintWriter out) throws IOException {
        int n = in.nextInt();
        int x0 = in.nextInt();
        int y0 = in.nextInt();

        int[] bishopMinDist = new int[MAX_DIRS];
        int[] rookMinDist = new int[MAX_DIRS];
        Arrays.fill(bishopMinDist, MAX_VALUE);
        Arrays.fill(rookMinDist, MAX_VALUE);

        for (int i = 0; i < n; i++) {
            char type = in.next().charAt(0);
            int x = in.nextInt();
            int y = in.nextInt();

            int dir = getDirectionIndex(x, y, x0, y0);
            if (dir == -1) {
                continue;
            }

            int dist = getChebyshevDistance(x, y, x0, y0);

            // Queens act as Bishops on diagonals (4-7) and Rooks on orthogonal (0-3)
            if (type == 'B' || (type == 'Q' && dir >= DIAGONAL_START)) {
                bishopMinDist[dir] = Math.min(bishopMinDist[dir], dist);
            } else if (type == 'R' || (type == 'Q' && dir < DIAGONAL_START)) {
                rookMinDist[dir] = Math.min(rookMinDist[dir], dist);
            }
        }

        boolean isThreatened = false;
        for (int i = ORTHOGONAL_START; i <= ORTHOGONAL_END; i++) {
            if (rookMinDist[i] < bishopMinDist[i]) {
                isThreatened = true;
            }
        }
        for (int i = DIAGONAL_START; i <= DIAGONAL_END; i++) {
            if (bishopMinDist[i] < rookMinDist[i]) {
                isThreatened = true;
            }
        }

        out.println(isThreatened ? "YES" : "NO");
    }

    /**
     * Determines the direction index from (x0, y0) to (x, y).
     * 0: Right, 1: Left, 2: Up, 3: Down (Orthogonal)
     * 4: Up-Right, 5: Down-Right, 6: Up-Left, 7: Down-Left (Diagonal)
     * Returns -1 if not aligned orthogonally or diagonally.
     */
    private static int getDirectionIndex(int x, int y, int x0, int y0) {
        if (y == y0) {
            return x > x0 ? 0 : 1;
        } else if (x == x0) {
            return y > y0 ? 2 : 3;
        } else if (Math.abs(x - x0) == Math.abs(y - y0)) {
            if (x > x0) {
                return y > y0 ? 4 : 5;
            } else {
                return y > y0 ? 6 : 7;
            }
        }
        return -1;
    }

    /**
     * Calculates the Chebyshev distance (max of absolute differences).
     * Equivalent to the minimum number of king or queen moves to reach the target.
     */
    private static int getChebyshevDistance(int x, int y, int x0, int y0) {
        return Math.max(Math.abs(x - x0), Math.abs(y - y0));
    }

    /**
     * Minimal fast I/O scanner optimized for competitive programming.
     */
    private static class FastScanner {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastScanner(InputStream stream) {
            this.reader = new BufferedReader(new InputStreamReader(stream));
            this.tokenizer = new StringTokenizer("");
        }

        public String next() throws IOException {
            while (!tokenizer.hasMoreTokens()) {
                String line = reader.readLine();
                if (line == null) {
                    return null;
                }
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            String token = next();
            return token == null ? 0 : Integer.parseInt(token);
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

/**
 * Refactored version of AntonChess2.
 * 
 * Improvements made:
 * 1. Encapsulation: Logic is contained within a class with clear responsibilities.
 * 2. Readability: Replaced magic numbers (0-7) with a Direction Enum.
 * 3. Data Structures: Replaced parallel arrays (t, x, y) with a dedicated Piece class.
 * 4. State Management: Removed static mutable state; inputs/outputs are passed as arguments.
 * 5. Error Handling: FastScanner handles IOExceptions gracefully.
 * 6. Naming: Variables and methods have descriptive names.
 */
public class ChessAttackSolver {

    // Enum to represent the 8 directions on a chess board relative to the King.
    // This replaces the magic integers 0-7 used in the original code.
    enum Direction {
        NORTH(0), SOUTH(1), WEST(2), EAST(3),
        NW(4), NE(5), SW(6), SE(7);

        final int index;
        Direction(int index) {
            this.index = index;
        }
    }

    private int kingX, kingY;
    // Array to store the closest piece found in each of the 8 directions.
    // Initialized to null (equivalent to -1 in the original logic).
    private Piece[] closestPieces = new Piece[8];

    // Inner class to represent a chess piece, replacing parallel arrays t, x, y.
    private static class Piece {
        char type;
        int x, y;

        Piece(char type, int x, int y) {
            this.type = type;
            this.x = x;
            this.y = y;
        }
    }

    public static void main(String[] args) {
        // Initialize IO resources
        FastScanner in = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            // Execute the solution logic
            new ChessAttackSolver().solve(in, out);
        } finally {
            // Ensure output is flushed and closed
            out.flush();
            out.close();
        }
    }

    private void solve(FastScanner in, PrintWriter out) {
        // Read number of pieces
        String nStr = in.next();
        if (nStr == null) return;
        int n = Integer.parseInt(nStr);

        // Read King's position
        kingX = in.nextInt();
        kingY = in.nextInt();

        // Process each piece
        for (int i = 0; i < n; i++) {
            String typeStr = in.next();
            if (typeStr == null) break; 
            char type = typeStr.charAt(0);
            int pieceX = in.nextInt();
            int pieceY = in.nextInt();

            // Determine direction relative to King
            Direction dir = getDirection(pieceX, pieceY);

            // If piece is on an attack line, update the closest piece for that direction
            if (dir != null) {
                updateNearest(dir, new Piece(type, pieceX, pieceY));
            }
        }

        // Check if the King is under attack by any of the closest pieces
        boolean isAttacked = false;
        for (Direction dir : Direction.values()) {
            Piece piece = closestPieces[dir.index];
            if (piece != null) {
                if (isAttacking(dir, piece.type)) {
                    isAttacked = true;
                    break;
                }
            }
        }

        out.println(isAttacked ? "YES" : "NO");
    }

    /**
     * Determines the direction from the King to the piece.
     * Returns null if the piece is not on a straight line or diagonal from the King.
     */
    private Direction getDirection(int pieceX, int pieceY) {
        // Check Orthogonal directions (Rook moves)
        if (pieceX == kingX) {
            // Same column
            return pieceY < kingY ? Direction.NORTH : Direction.SOUTH;
        }
        if (pieceY == kingY) {
            // Same row
            return pieceX < kingX ? Direction.WEST : Direction.EAST;
        }

        // Check Diagonal directions (Bishop moves)
        // Diagonal 1: (y - kingY) == (x - kingX)  => Slope 1
        if (pieceY - kingY == pieceX - kingX) {
            // x < kingX implies y < kingY (North-West)
            // x > kingX implies y > kingY (South-East)
            return pieceX < kingX ? Direction.NW : Direction.SE;
        }

        // Diagonal 2: (y - kingY) == -(x - kingX) => Slope -1
        if (pieceY - kingY == -(pieceX - kingX)) {
            // x < kingX implies y > kingY (South-West)
            // x > kingX implies y < kingY (North-East)
            return pieceX < kingX ? Direction.SW : Direction.NE;
        }

        return null; // Not on a valid attack line
    }

    /**
     * Calculates the Chebyshev distance between the King and a piece.
     * Used to determine which piece is closer.
     */
    private int getDistance(int pieceX, int pieceY) {
        return Math.max(Math.abs(pieceX - kingX), Math.abs(pieceY - kingY));
    }

    /**
     * Updates the closest piece found so far for a specific direction.
     */
    private void updateNearest(Direction dir, Piece piece) {
        int currentDist = getDistance(piece.x, piece.y);
        Piece closest = closestPieces[dir.index];

        // If no piece found yet, or current piece is closer to the King
        if (closest == null || currentDist < getDistance(closest.x, closest.y)) {
            closestPieces[dir.index] = piece;
        }
    }

    /**
     * Checks if a piece of a given type can attack in a specific direction.
     */
    private boolean isAttacking(Direction dir, char pieceType) {
        // Rook (R) and Queen (Q) attack Orthogonal directions
        if (pieceType == 'R' || pieceType == 'Q') {
            return dir == Direction.NORTH || dir == Direction.SOUTH ||
                   dir == Direction.WEST || dir == Direction.EAST;
        }
        // Bishop (B) and Queen (Q) attack Diagonal directions
        if (pieceType == 'B' || pieceType == 'Q') {
            return dir == Direction.NW || dir == Direction.NE ||
                   dir == Direction.SW || dir == Direction.SE;
        }
        return false;
    }

    /**
     * Helper class for fast input reading.
     */
    static class FastScanner {
        BufferedReader br;
        StringTokenizer st;

        public FastScanner(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) {
                        return null;
                    }
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            String s = next();
            if (s == null) throw new RuntimeException("Unexpected end of input");
            return Integer.parseInt(s);
        }
    }
}

import java.io.*;
import java.util.StringTokenizer;

/**
 * Solves a chess board attack problem by checking if any piece can attack
 * a target square (x0, y0) considering blocking pieces.
 */
public class ChessAttackSolver {

    public static void main(String[] args) throws IOException {
        FastReader reader = new FastReader(System.in);
        FastWriter writer = new FastWriter(System.out);

        try {
            int n = reader.nextInt();
            long x0 = reader.nextLong();
            long y0 = reader.nextLong();

            // Tracks the closest piece in each of the 8 directions from (x0, y0)
            // Indices: 0:NE, 1:SE, 2:NW, 3:SW, 4:Left, 5:Right, 6:Down, 7:Up
            Piece[] closestPieces = new Piece[8];

            for (int i = 0; i < n; i++) {
                String type = reader.next();
                long x = reader.nextLong();
                long y = reader.nextLong();

                int direction = getDirectionIndex(x, y, x0, y0);
                if (direction != -1) {
                    // Calculate distance along the attack line
                    long distance = (x == x0) ? Math.abs(y - y0) : Math.abs(x - x0);

                    // Keep only the closest piece in each direction (blocking logic)
                    if (closestPieces[direction] == null || distance < closestPieces[direction].distance) {
                        closestPieces[direction] = new Piece(type, distance);
                    }
                }
            }

            boolean canAttack = false;

            // Check diagonal directions for Bishops (B) or Queens (Q)
            for (int i = 0; i < 4; i++) {
                Piece p = closestPieces[i];
                if (p != null && (p.type.equals("B") || p.type.equals("Q"))) {
                    canAttack = true;
                    break;
                }
            }

            // Check orthogonal directions for Rooks (R) or Queens (Q)
            if (!canAttack) {
                for (int i = 4; i < 8; i++) {
                    Piece p = closestPieces[i];
                    if (p != null && (p.type.equals("R") || p.type.equals("Q"))) {
                        canAttack = true;
                        break;
                    }
                }
            }

            writer.println(canAttack ? "YES" : "NO");
        } finally {
            writer.close();
        }
    }

    /**
     * Determines which of the 8 directions a piece lies relative to the target.
     * Returns -1 if the piece is not on an attack line or occupies the target square.
     */
    private static int getDirectionIndex(long x, long y, long x0, long y0) {
        if (x == x0 && y == y0) {
            return -1; // Occupies target square
        }

        if (Math.abs(x - x0) == Math.abs(y - y0)) {
            // Diagonal directions
            if (x > x0 && y > y0) return 0; // North-East
            if (x > x0 && y < y0) return 1; // South-East
            if (x < x0 && y > y0) return 2; // North-West
            if (x < x0 && y < y0) return 3; // South-West
        } else if (y == y0) {
            // Horizontal directions
            if (x < x0) return 4; // Left
            if (x > x0) return 5; // Right
        } else if (x == x0) {
            // Vertical directions
            if (y < y0) return 6; // Down
            if (y > y0) return 7; // Up
        }

        return -1; // Not aligned with target
    }

    /**
     * Immutable value object representing a piece on the board.
     */
    private static class Piece {
        final String type;
        final long distance;

        Piece(String type, long distance) {
            this.type = type;
            this.distance = distance;
        }
    }

    /**
     * Fast input reader for competitive programming / high-throughput scenarios.
     */
    private static class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        FastReader(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        String next() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) {
                    throw new EOFException("Unexpected end of input");
                }
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        long nextLong() throws IOException {
            return Long.parseLong(next());
        }
    }

    /**
     * Fast output writer with buffered streaming.
     */
    private static class FastWriter {
        private final PrintWriter out;

        FastWriter(OutputStream out) {
            this.out = new PrintWriter(new BufferedOutputStream(out));
        }

        void println(Object obj) {
            out.println(obj);
        }

        void flush() {
            out.flush();
        }

        void close() {
            out.close();
        }
    }
}

import java.io.PrintWriter;
import java.util.Arrays;
import java.util.Comparator;
import java.util.Scanner;

public class ChessKingAnalysis {

    public static void main(String[] args) {
        // Use try-with-resources to ensure proper cleanup of I/O streams
        try (Scanner reader = new Scanner(System.in);
             PrintWriter writer = new PrintWriter(System.out)) {
            solve(reader, writer);
        }
    }

    private static void solve(final Scanner reader, final PrintWriter writer) {
        final int n = reader.nextInt();
        final int kingX = reader.nextInt();
        final int kingY = reader.nextInt();
        final Chess whiteKing = new Chess('K', kingX, kingY);

        Chess[] blackPieces = new Chess[n];
        for (int i = 0; i < n; i++) {
            blackPieces[i] = new Chess(
                reader.next().charAt(0),
                reader.nextInt(),
                reader.nextInt()
            );
        }

        // Sort pieces by Manhattan distance from the king, then by x, then by y
        Arrays.sort(blackPieces, Comparator
            .comparingLong((Chess piece) -> Math.abs(piece.x - kingX) + Math.abs(piece.y - kingY))
            .thenComparingInt(piece -> piece.x)
            .thenComparingInt(piece -> piece.y));

        // Track blocked positions around the king (1-8). 
        // Using a boolean array is more efficient and idiomatic than HashMap<Integer, Boolean>.
        boolean[] blockedPositions = new boolean[9];
        boolean isCheckmated = false;

        for (Chess piece : blackPieces) {
            int relativePos = getRelativePosition(whiteKing, piece);
            if (relativePos == 0) {
                continue;
            }

            if (!blockedPositions[relativePos]) {
                if (canAttackKing(piece, whiteKing)) {
                    isCheckmated = true;
                }
                blockedPositions[relativePos] = true;
            }
        }

        writer.println(isCheckmated ? "YES" : "NO");
    }

    /**
     * Determines the relative position of a piece around the king.
     * Returns 1-8 based on compass directions, or 0 if not aligned.
     */
    private static int getRelativePosition(final Chess king, final Chess piece) {
        final int dx = piece.x - king.x;
        final int dy = piece.y - king.y;

        if (dx == 0) {
            return dy > 0 ? 4 : 8; // North / South
        }
        if (dy == 0) {
            return dx > 0 ? 6 : 2; // East / West
        }
        if (Math.abs(dx) == Math.abs(dy)) {
            if (dx > 0) {
                return dy > 0 ? 5 : 7; // South-East / North-East
            } else {
                return dy > 0 ? 3 : 1; // South-West / North-West
            }
        }
        return 0; // Not on the same row, column, or diagonal
    }

    /**
     * Checks if a black piece can attack the white king based on its role.
     */
    private static boolean canAttackKing(final Chess piece, final Chess king) {
        final int dx = Math.abs(piece.x - king.x);
        final int dy = Math.abs(piece.y - king.y);

        switch (piece.role) {
            case 'B': return dx == dy;                 // Bishop: diagonal only
            case 'R': return dx == 0 || dy == 0;       // Rook: straight lines only
            default:  return dx == dy || dx == 0 || dy == 0; // Queen: diagonal or straight
        }
    }

    /**
     * Immutable representation of a chess piece.
     */
    private static final class Chess {
        private final char role;
        private final int x;
        private final int y;

        private Chess(final char role, final int x, final int y) {
            this.role = role;
            this.x = x;
            this.y = y;
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.OutputStream;
import java.io.PrintWriter;
import java.util.Arrays;
import java.util.StringTokenizer;

public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);

        TaskD solver = new TaskD();
        solver.solve(in, out);

        out.close();
    }

    static class TaskD {
        // Directions: [dx, dy] for the 8 possible movement directions
        private static final long[][] DIRECTIONS = {
            {0, -1}, {0, 1}, {1, 0}, {1, 1}, {1, -1}, {-1, 0}, {-1, 1}, {-1, -1}
        };

        private long kingX;
        private long kingY;
        private long[] nearestDist;
        private char[] nearestPiece;

        public void solve(InputReader in, PrintWriter out) {
            // Initialize tracking arrays
            nearestDist = new long[DIRECTIONS.length];
            Arrays.fill(nearestDist, Long.MAX_VALUE);
            nearestPiece = new char[DIRECTIONS.length];

            int n = in.nextInt();
            kingX = in.nextLong();
            kingY = in.nextLong();

            for (int i = 0; i < n; ++i) {
                char type = in.next().charAt(0);
                long x = in.nextLong();
                long y = in.nextLong();

                long[] dir = normalizeDirection(kingX - x, kingY - y);
                int dirIdx = getDirectionIndex(dir);

                if (dirIdx != -1) {
                    long dist = Math.abs(kingX - x) + Math.abs(kingY - y);
                    if (dist < nearestDist[dirIdx]) {
                        nearestDist[dirIdx] = dist;
                        nearestPiece[dirIdx] = type;
                    }
                }
            }

            if (isKingThreatened()) {
                out.println("YES");
            } else {
                out.println("NO");
            }
        }

        /**
         * Normalizes a direction vector to its simplest integer form (-1, 0, or 1).
         * Returns null if the vector is zero (same position).
         */
        private long[] normalizeDirection(long dx, long dy) {
            if (dx == 0 && dy == 0) return null;
            long gcd = Math.abs(NumberTheory.gcd(dx, dy));
            dx /= gcd;
            dy /= gcd;
            return new long[]{dx, dy};
        }

        /**
         * Maps a normalized direction vector to its index in the DIRECTIONS array.
         */
        private int getDirectionIndex(long[] dir) {
            for (int i = 0; i < DIRECTIONS.length; i++) {
                if (DIRECTIONS[i][0] == dir[0] && DIRECTIONS[i][1] == dir[1]) {
                    return i;
                }
            }
            return -1;
        }

        /**
         * Checks if the king is threatened by the nearest piece in any of the 8 directions.
         */
        private boolean isKingThreatened() {
            for (int i = 0; i < DIRECTIONS.length; i++) {
                char piece = nearestPiece[i];
                if (piece == 0) continue; // No piece in this direction

                long dx = DIRECTIONS[i][0];
                long dy = DIRECTIONS[i][1];
                boolean isDiagonal = (dx * dy != 0);
                boolean isOrthogonal = (dx * dy == 0);

                // Bishop threatens diagonally, Rook orthogonally, Queen in any direction
                if ((isDiagonal && piece == 'B') || (isOrthogonal && piece == 'R') || piece == 'Q') {
                    return true;
                }
            }
            return false;
        }
    }

    static class NumberTheory {
        /**
         * Computes the Greatest Common Divisor using the Euclidean algorithm.
         */
        public static long gcd(long a, long b) {
            a = Math.abs(a);
            b = Math.abs(b);
            return b == 0 ? a : gcd(b, a % b);
        }
    }

    static class InputReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }
    }
}

import java.util.Scanner;

public class AntonAndChess {
    public static void main(String[] args) {
        // Use Scanner for cleaner and more maintainable input handling.
        // Note: For extremely large inputs in competitive programming, 
        // BufferedReader/StringTokenizer might be preferred for speed, 
        // but Scanner is standard for general code quality.
        Scanner scanner = new Scanner(System.in);

        // Read the number of pieces
        if (!scanner.hasNextInt()) {
            scanner.close();
            return;
        }
        int n = scanner.nextInt();

        // Read the King's position
        long kingX = scanner.nextLong();
        long kingY = scanner.nextLong();

        // Arrays to track the closest piece in each of the 8 directions.
        // Directions mapping:
        // 0: Up (0, 1)
        // 1: Right (1, 0)
        // 2: Down (0, -1)
        // 3: Left (-1, 0)
        // 4: Top-Right (1, 1)
        // 5: Bottom-Right (1, -1)
        // 6: Top-Left (-1, 1)
        // 7: Bottom-Left (-1, -1)
        long[] minDist = new long[8];
        char[] closestPiece = new char[8];

        // Initialize distances to maximum value to represent "no piece found yet"
        for (int i = 0; i < 8; i++) {
            minDist[i] = Long.MAX_VALUE;
            closestPiece[i] = ' ';
        }

        for (int i = 0; i < n; i++) {
            String typeStr = scanner.next();
            char pieceType = typeStr.charAt(0);
            long pieceX = scanner.nextLong();
            long pieceY = scanner.nextLong();

            // Calculate relative position to the King
            long relX = pieceX - kingX;
            long relY = pieceY - kingY;

            int direction = -1;
            long dist = 0;

            // Determine the direction and validate if it's a valid attack line
            if (relX == 0) {
                // Vertical alignment
                if (relY > 0) direction = 0; // Up
                else if (relY < 0) direction = 2; // Down
            } else if (relY == 0) {
                // Horizontal alignment
                if (relX > 0) direction = 1; // Right
                else if (relX < 0) direction = 3; // Left
            } else {
                // Check for diagonal alignment (slope 1 or -1)
                // A piece attacks diagonally if the absolute difference in X equals absolute difference in Y
                if (Math.abs(relX) == Math.abs(relY)) {
                    if (relX > 0 && relY > 0) direction = 4; // Top-Right
                    else if (relX > 0 && relY < 0) direction = 5; // Bottom-Right
                    else if (relX < 0 && relY > 0) direction = 6; // Top-Left
                    else if (relX < 0 && relY < 0) direction = 7; // Bottom-Left
                }
            }

            // If the piece is on a valid attack line, check distance
            if (direction != -1) {
                // Distance metric: Chebyshev distance (max of abs coords).
                // For orthogonal moves, one coord is 0, so it works.
                // For diagonal moves, coords are equal magnitude, so it works.
                dist = Math.max(Math.abs(relX), Math.abs(relY));

                // Update if this piece is closer than the previously recorded one.
                // This handles the logic that a closer piece blocks a further piece.
                if (dist < minDist[direction]) {
                    minDist[direction] = dist;
                    closestPiece[direction] = pieceType;
                }
            }
        }

        // Determine if the King is under attack
        boolean isAttacked = false;

        // Rooks attack horizontally and vertically (Directions 0, 1, 2, 3)
        if (closestPiece[0] == 'R' || closestPiece[1] == 'R' || 
            closestPiece[2] == 'R' || closestPiece[3] == 'R') {
            isAttacked = true;
        }

        // Bishops attack diagonally (Directions 4, 5, 6, 7)
        // Only check if not already attacked to save a few cycles
        if (!isAttacked && (closestPiece[4] == 'B' || closestPiece[5] == 'B' || 
            closestPiece[6] == 'B' || closestPiece[7] == 'B')) {
            isAttacked = true;
        }

        System.out.println(isAttacked ? "YES" : "NO");

        scanner.close();
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.OutputStreamWriter;
import java.io.PrintWriter;

/**
 * Analyzes chess piece positions relative to an origin and determines
 * if a winning configuration exists within the 8 primary directions.
 */
public class Main {
    private static final int NUM_DIRECTIONS = 8;

    // Stores the closest piece found in each of the 8 primary directions from the origin
    private static Node[] directionBuckets = new Node[NUM_DIRECTIONS];

    public static void main(String[] args) throws IOException {
        // Use try-with-resources for automatic and safe resource management
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
             PrintWriter pw = new PrintWriter(new OutputStreamWriter(System.out))) {

            String line = br.readLine();
            if (line == null) return;

            int n = Integer.parseInt(line.trim());

            String[] originParts = br.readLine().trim().split("\\s+");
            long originX = Long.parseLong(originParts[0]);
            long originY = Long.parseLong(originParts[1]);

            for (int i = 0; i < n; i++) {
                String[] parts = br.readLine().trim().split("\\s+");
                if (parts.length < 3) continue; // Guard against malformed input lines

                String pieceType = parts[0];
                long pieceX = Long.parseLong(parts[1]);
                long pieceY = Long.parseLong(parts[2]);

                // Calculate relative coordinates from the origin
                long dx = pieceX - originX;
                long dy = pieceY - originY;

                int directionIndex = getDirectionIndex(dx, dy);
                if (directionIndex != -1) {
                    updateBucket(directionIndex, dx, dy, pieceType.charAt(0));
                }
            }

            pw.println(checkWinCondition() ? "YES" : "NO");
        }
    }

    /**
     * Maps a relative coordinate (dx, dy) to one of the 8 primary directions.
     * Returns -1 if the point does not align with any primary direction.
     * Mapping: 0=NE, 1=E, 2=SE, 3=S, 4=SW, 5=W, 6=NW, 7=N
     */
    private static int getDirectionIndex(long dx, long dy) {
        if (dx > 0 && dy > 0 && dx == dy) return 0;      // NE
        if (dx > 0 && dy == 0) return 1;                 // E
        if (dx > 0 && dy < 0 && dx == -dy) return 2;     // SE
        if (dx == 0 && dy < 0) return 3;                 // S
        if (dx < 0 && dy < 0 && dx == dy) return 4;      // SW
        if (dx < 0 && dy == 0) return 5;                 // W
        if (dx < 0 && dy > 0 && dx == -dy) return 6;     // NW
        if (dx == 0 && dy > 0) return 7;                 // N
        return -1;
    }

    /**
     * Updates the bucket for a specific direction if the new piece is closer to the origin.
     * A piece is considered closer if either its x or y distance to the origin is smaller.
     */
    private static void updateBucket(int index, long dx, long dy, char pieceType) {
        if (directionBuckets[index] == null) {
            directionBuckets[index] = new Node(dx, dy, pieceType);
        } else {
            Node existing = directionBuckets[index];
            if (Math.abs(dx) < Math.abs(existing.x) || Math.abs(dy) < Math.abs(existing.y)) {
                directionBuckets[index] = new Node(dx, dy, pieceType);
            }
        }
    }

    /**
     * Checks if any piece in the 8 directions satisfies the winning condition:
     * - Queen ('Q') anywhere
     * - Rook ('R') on an axis (x == 0 or y == 0)
     * - Bishop ('B') off-axis (x != 0 and y != 0)
     */
    private static boolean checkWinCondition() {
        for (int i = 0; i < NUM_DIRECTIONS; i++) {
            Node piece = directionBuckets[i];
            if (piece == null) continue;

            if (piece.type == 'Q') return true;
            if (piece.type == 'R' && (piece.x == 0 || piece.y == 0)) return true;
            if (piece.type == 'B' && piece.x != 0 && piece.y != 0) return true;
        }
        return false;
    }

    /**
     * Represents a chess piece at a specific relative coordinate.
     */
    private static class Node {
        final long x;
        final long y;
        final char type;

        public Node(long x, long y, char type) {
            this.x = x;
            this.y = y;
            this.type = type;
        }
    }
}

import java.io.*;
import java.util.*;

public class Main {

    /** Represents chess piece types and their attack patterns */
    enum PieceType {
        ROOK("R"), QUEEN("Q"), BISHOP("B");

        private final String symbol;

        PieceType(String symbol) {
            this.symbol = symbol;
        }

        public static PieceType fromSymbol(String s) {
            for (PieceType type : values()) {
                if (type.symbol.equals(s)) {
                    return type;
                }
            }
            throw new IllegalArgumentException("Unknown piece type: " + s);
        }
    }

    /** Represents a chess piece on the board */
    static class Piece {
        final PieceType type;
        final long x, y;

        Piece(PieceType type, long x, long y) {
            this.type = type;
            this.x = x;
            this.y = y;
        }
    }

    /** Tracks the closest piece found in a specific direction */
    static class DirectionTracker {
        Piece closestPiece;
        long minDistance;

        DirectionTracker() {
            this.closestPiece = null;
            this.minDistance = Long.MAX_VALUE;
        }

        void update(Piece piece, long distance) {
            if (distance < minDistance) {
                this.minDistance = distance;
                this.closestPiece = piece;
            }
        }
    }

    /** Orchestrates the attack check logic */
    private void solve(InputReader in, PrintWriter out) {
        int n = in.nextInt();
        long x0 = in.nextLong();
        long y0 = in.nextLong();

        Piece[] pieces = new Piece[n];
        for (int i = 0; i < n; i++) {
            pieces[i] = new Piece(
                PieceType.fromSymbol(in.next()), 
                in.nextLong(), 
                in.nextLong()
            );
        }

        // Initialize trackers for all 8 directions
        DirectionTracker up = new DirectionTracker();
        DirectionTracker down = new DirectionTracker();
        DirectionTracker left = new DirectionTracker();
        DirectionTracker right = new DirectionTracker();
        DirectionTracker upLeft = new DirectionTracker();
        DirectionTracker upRight = new DirectionTracker();
        DirectionTracker downLeft = new DirectionTracker();
        DirectionTracker downRight = new DirectionTracker();

        // Process each piece and update the closest tracker for its direction
        for (Piece piece : pieces) {
            long dx = piece.x - x0;
            long dy = piece.y - y0;

            if (dx == 0) {
                long dist = Math.abs(dy);
                if (dy > 0) up.update(piece, dist);
                else if (dy < 0) down.update(piece, dist);
            } else if (dy == 0) {
                long dist = Math.abs(dx);
                if (dx > 0) right.update(piece, dist);
                else if (dx < 0) left.update(piece, dist);
            } else if (Math.abs(dx) == Math.abs(dy)) {
                long dist = Math.abs(dx);
                if (dx < 0 && dy < 0) downLeft.update(piece, dist);
                else if (dx < 0 && dy > 0) upLeft.update(piece, dist);
                else if (dx > 0 && dy < 0) downRight.update(piece, dist);
                else if (dx > 0 && dy > 0) upRight.update(piece, dist);
            }
        }

        // Check if any piece can attack the target position
        boolean canAttackCardinal = isAttacking(up, false) || isAttacking(down, false) ||
                                    isAttacking(left, false) || isAttacking(right, false);
        boolean canAttackDiagonal = isAttacking(upLeft, true) || isAttacking(upRight, true) ||
                                    isAttacking(downLeft, true) || isAttacking(downRight, true);

        out.println(canAttackCardinal || canAttackDiagonal ? "YES" : "NO");
    }

    /** Determines if the closest piece in a direction can attack the target */
    private boolean isAttacking(DirectionTracker tracker, boolean isDiagonal) {
        if (tracker.closestPiece == null) {
            return false;
        }
        switch (tracker.closestPiece.type) {
            case QUEEN: return true;
            case ROOK: return !isDiagonal;
            case BISHOP: return isDiagonal;
            default: return false;
        }
    }

    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        new Main().solve(in, out);
        out.close();
    }

    /** Fast I/O helper for competitive programming */
    static class InputReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) {
                        throw new EOFException("Unexpected end of input");
                    }
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

/**
 * Determines if any chess piece can attack a given center coordinate (x, y)
 * on a board based on Rook, Bishop, and Queen movement rules.
 */
public class ChessAttackChecker {

    /**
     * Tracks the closest piece found in a specific direction from the center.
     */
    private static class DirectionTracker {
        char pieceType = 0;
        int x = 0;
        int y = 0;
    }

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner();

        // Read board parameters
        int n = scanner.nextInt();
        int centerX = scanner.nextInt();
        int centerY = scanner.nextInt();

        // Initialize trackers for all 8 directions with sentinel values
        DirectionTracker closestUp = new DirectionTracker();
        initSentinel(closestUp, Integer.MIN_VALUE, Integer.MIN_VALUE);

        DirectionTracker closestDown = new DirectionTracker();
        initSentinel(closestDown, Integer.MAX_VALUE, Integer.MAX_VALUE);

        DirectionTracker closestLeft = new DirectionTracker();
        initSentinel(closestLeft, Integer.MIN_VALUE, Integer.MIN_VALUE);

        DirectionTracker closestRight = new DirectionTracker();
        initSentinel(closestRight, Integer.MAX_VALUE, Integer.MAX_VALUE);

        DirectionTracker closestTopLeft = new DirectionTracker();
        initSentinel(closestTopLeft, Integer.MIN_VALUE, Integer.MAX_VALUE);

        DirectionTracker closestBottomRight = new DirectionTracker();
        initSentinel(closestBottomRight, Integer.MAX_VALUE, Integer.MIN_VALUE);

        DirectionTracker closestBottomLeft = new DirectionTracker();
        initSentinel(closestBottomLeft, Integer.MIN_VALUE, Integer.MIN_VALUE);

        DirectionTracker closestTopRight = new DirectionTracker();
        initSentinel(closestTopRight, Integer.MAX_VALUE, Integer.MAX_VALUE);

        // Process each piece
        for (int i = 0; i < n; i++) {
            String typeStr = scanner.next();
            if (typeStr == null) break;

            char pieceType = typeStr.charAt(0);
            int tx = scanner.nextInt();
            int ty = scanner.nextInt();

            updateClosestPiece(pieceType, tx, ty, centerX, centerY,
                    closestUp, closestDown, closestLeft, closestRight,
                    closestTopRight, closestTopLeft, closestBottomRight, closestBottomLeft);
        }

        // Determine if any piece can attack the center
        boolean rookAttack = canAttack(closestUp.pieceType, true) ||
                             canAttack(closestDown.pieceType, true) ||
                             canAttack(closestLeft.pieceType, true) ||
                             canAttack(closestRight.pieceType, true);

        boolean bishopAttack = canAttack(closestTopLeft.pieceType, false) ||
                               canAttack(closestTopRight.pieceType, false) ||
                               canAttack(closestBottomLeft.pieceType, false) ||
                               canAttack(closestBottomRight.pieceType, false);

        System.out.println(rookAttack || bishopAttack ? "YES" : "NO");
    }

    /**
     * Initializes a direction tracker with boundary sentinel values.
     */
    private static void initSentinel(DirectionTracker tracker, int x, int y) {
        tracker.x = x;
        tracker.y = y;
        tracker.pieceType = 0;
    }

    /**
     * Updates the closest piece tracker for the corresponding direction.
     */
    private static void updateClosestPiece(char pieceType, int tx, int ty, int cx, int cy,
                                           DirectionTracker up, DirectionTracker down,
                                           DirectionTracker left, DirectionTracker right,
                                           DirectionTracker topRight, DirectionTracker topLeft,
                                           DirectionTracker bottomRight, DirectionTracker bottomLeft) {
        if (ty == cy) { // Same row
            if (tx > up.x && tx < cx) {
                up.x = tx; up.y = ty; up.pieceType = pieceType;
            } else if (tx < down.x && tx > cx) {
                down.x = tx; down.y = ty; down.pieceType = pieceType;
            }
        } else if (tx == cx) { // Same column
            if (ty > left.y && ty < cy) {
                left.x = tx; left.y = ty; left.pieceType = pieceType;
            } else if (ty < right.y && ty > cy) {
                right.x = tx; right.y = ty; right.pieceType = pieceType;
            }
        } else if (cx + cy == tx + ty) { // Diagonal \
            if (tx > topLeft.x && ty < topLeft.y && tx < cx && ty > cy) {
                topLeft.x = tx; topLeft.y = ty; topLeft.pieceType = pieceType;
            } else if (tx < bottomRight.x && ty > bottomRight.y && tx > cx && ty < cy) {
                bottomRight.x = tx; bottomRight.y = ty; bottomRight.pieceType = pieceType;
            }
        } else if (cy - cx == ty - tx) { // Diagonal /
            if (tx > bottomLeft.x && ty > bottomLeft.y && tx < cx && ty < cy) {
                bottomLeft.x = tx; bottomLeft.y = ty; bottomLeft.pieceType = pieceType;
            } else if (tx < topRight.x && ty < topRight.y && tx > cx && ty > cy) {
                topRight.x = tx; topRight.y = ty; topRight.pieceType = pieceType;
            }
        }
    }

    /**
     * Checks if a piece type can attack along the specified axis type.
     * @param pieceType The character representing the piece ('R', 'Q', 'B', etc.)
     * @param isRookLike true for horizontal/vertical axes, false for diagonal axes
     */
    private static boolean canAttack(char pieceType, boolean isRookLike) {
        if (pieceType == 0) return false;
        if (isRookLike) {
            return pieceType == 'R' || pieceType == 'Q';
        } else {
            return pieceType == 'B' || pieceType == 'Q';
        }
    }

    /**
     * Standard fast I/O helper for competitive programming and large inputs.
     */
    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            String s = next();
            return s == null ? 0 : Integer.parseInt(s);
        }
    }
}

import java.util.Arrays;
import java.util.Scanner;

/**
 * Refactored solver for the "Anton and Chess" problem.
 * 
 * Refactoring Improvements:
 * 1.  **Naming Conventions**: Renamed variables to be more descriptive (e.g., `antonX`, `minDistance`).
 * 2.  **Magic Numbers**: Replaced hardcoded array size and offset with constants (`DIRECTIONS_COUNT`, `CENTER_INDEX`).
 * 3.  **Readability**: Extracted the direction index calculation into a helper method `getDirectionIndex`.
 * 4.  **Resource Management**: Used try-with-resources for the `Scanner` to ensure proper closure.
 * 5.  **Logic Clarity**: Simplified distance calculation using `Math.max` and clarified the boolean logic assignment.
 * 
 * Note: The boolean logic for determining a "treat" (preserved from original code) checks if the piece is 
 * NOT the type that attacks that specific line. This behavior is maintained to ensure consistency with 
 * the original implementation, though it may be logically inverted for standard chess threat detection.
 */
public class AntonChessSolver {

    private static final int DIRECTIONS_COUNT = 9;
    private static final int CENTER_INDEX = 4;

    public static void main(String[] args) {
        // Use try-with-resources for automatic resource management
        try (Scanner scanner = new Scanner(System.in)) {
            if (!scanner.hasNextInt()) {
                return;
            }

            int n = scanner.nextInt();
            int antonX = scanner.nextInt();
            int antonY = scanner.nextInt();

            // Tracks the minimum distance to a piece in each of the 8 directions (+ center)
            int[] minDistance = new int[DIRECTIONS_COUNT];
            Arrays.fill(minDistance, Integer.MAX_VALUE);

            // Tracks the status of the closest piece in each direction.
            // Based on original logic: true if the piece is NOT the type that attacks that line.
            boolean[] isTreat = new boolean[DIRECTIONS_COUNT];

            for (int i = 0; i < n; i++) {
                String typeStr = scanner.next();
                char pieceType = typeStr.charAt(0);
                int pieceX = scanner.nextInt();
                int pieceY = scanner.nextInt();

                int distX = Math.abs(antonX - pieceX);
                int distY = Math.abs(antonY - pieceY);

                // Check if the piece is on a valid line (Rook move) or diagonal (Bishop move)
                if (pieceX == antonX || pieceY == antonY || distX == distY) {

                    int directionIndex = getDirectionIndex(antonX, antonY, pieceX, pieceY);
                    // Distance is the max of x and y diff for diagonal/orthogonal moves
                    int distance = Math.max(distX, distY);

                    if (distance < minDistance[directionIndex]) {
                        minDistance[directionIndex] = distance;

                        // Determine if this piece constitutes a "treat" based on original logic
                        // Original: diagonal -> (type != 'B'), orthogonal -> (type != 'R')
                        boolean isDiagonal = (distX == distY);

                        // Logic preserved from original code
                        boolean treatCondition = isDiagonal ? (pieceType != 'B') : (pieceType != 'R');
                        isTreat[directionIndex] = treatCondition;
                    }
                }
            }

            boolean isTreatFound = false;
            for (boolean treat : isTreat) {
                if (treat) {
                    isTreatFound = true;
                    break;
                }
            }

            System.out.println(isTreatFound ? "YES" : "NO");
        }
    }

    /**
     * Calculates the index (0-8) representing the direction from Anton to the piece.
     * 
     * Mapping (3x3 grid centered at Anton):
     * 0 1 2
     * 3 4 5
     * 6 7 8
     * 
     * @param antonX Anton's x coordinate
     * @param antonY Anton's y coordinate
     * @param pieceX Piece's x coordinate
     * @param pieceY Piece's y coordinate
     * @return Index in the range [0, 8]
     */
    private static int getDirectionIndex(int antonX, int antonY, int pieceX, int pieceY) {
        int dirX = 0;
        if (pieceX > antonX) dirX = 1;
        else if (pieceX < antonX) dirX = -1;

        int dirY = 0;
        if (pieceY > antonY) dirY = 1;
        else if (pieceY < antonY) dirY = -1;

        // Map 3x3 grid (-1..1) to 0..8
        // Equivalent to: (dirY + 1) * 3 + (dirX + 1)
        // Original formula: dirCodeY * 3 + dirCodeX + 4
        return dirY * 3 + dirX + CENTER_INDEX;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.Arrays;

/**
 * Analyzes chess board moves to determine if a check is possible
 * based on specific movement rules (King-like moves).
 */
public class ChessBoardAnalyzer {

    private static final int MAX_DISTANCE = Integer.MAX_VALUE;
    private static final int DIRECTION_OFFSET = 4;

    public static void main(String[] args) throws IOException {
        // Use try-with-resources to ensure the reader is closed automatically
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(System.in))) {

            // Read number of moves
            String line = reader.readLine();
            if (line == null) return;
            int moveCount = Integer.parseInt(line.trim());

            // Read starting position
            line = reader.readLine();
            if (line == null) return;
            String[] startCoords = line.trim().split("\\s+");
            int currentX = Integer.parseInt(startCoords[0]);
            int currentY = Integer.parseInt(startCoords[1]);

            // Arrays to track state for 8 directions (mapped to indices 0-8)
            // Index mapping logic: dirY * 3 + dirX + 4
            int[] closestDistance = new int[9];
            boolean[] isCheckPossible = new boolean[9];
            Arrays.fill(closestDistance, MAX_DISTANCE);

            // Process each move
            for (int i = 0; i < moveCount; i++) {
                line = reader.readLine();
                if (line == null) break;

                String[] parts = line.trim().split("\\s+");
                char pieceType = parts[0].charAt(0);
                int targetX = Integer.parseInt(parts[1]);
                int targetY = Integer.parseInt(parts[2]);

                processMove(currentX, currentY, targetX, targetY, pieceType, closestDistance, isCheckPossible);
            }

            // Determine result
            if (hasAnyCheckPossible(isCheckPossible)) {
                System.out.println("YES");
            } else {
                System.out.println("NO");
            }
        } catch (NumberFormatException e) {
            System.err.println("Error: Invalid number format in input.");
        }
    }

    /**
     * Processes a single move from current position to target position.
     */
    private static void processMove(int currentX, int currentY, int targetX, int targetY, 
                                    char type, int[] closestDistance, boolean[] isCheckPossible) {

        int distX = Math.abs(currentX - targetX);
        int distY = Math.abs(currentY - targetY);

        // Check if the move is valid (King move: horizontal, vertical, or diagonal)
        if (isValidKingMove(distX, distY)) {

            // Calculate direction vectors
            // Logic preserved from original: (current - target) / distance
            int dirX = getDirectionVector(distX, currentX, targetX);
            int dirY = getDirectionVector(distY, currentY, targetY);

            // Map direction to array index
            int directionIndex = calculateDirectionIndex(dirX, dirY);

            // Distance is the max of x and y difference for King moves
            int distance = Math.max(distX, distY);

            // Update if this is the closest piece found in this direction
            if (distance < closestDistance[directionIndex]) {
                closestDistance[directionIndex] = distance;

                // Determine boolean condition based on piece type and move geometry
                // Original Logic: (distx == disty) ? type != 'R' : type != 'B'
                boolean condition = (distX == distY) ? (type != 'R') : (type != 'B');
                isCheckPossible[directionIndex] = condition;
            }
        }
    }

    private static boolean isValidKingMove(int distX, int distY) {
        // Valid if same column, same row, or diagonal
        return (distX == 0) || (distY == 0) || (distX == distY);
    }

    private static int getDirectionVector(int distance, int current, int target) {
        if (distance == 0) {
            return 0;
        }
        // Replicating original logic: (current - target) / distance
        return (current - target) / distance;
    }

    private static int calculateDirectionIndex(int dirX, int dirY) {
        // Maps direction vectors (-1, 0, 1) to indices 0-8
        return (dirY * 3) + dirX + DIRECTION_OFFSET;
    }

    private static boolean hasAnyCheckPossible(boolean[] isCheckPossible) {
        for (boolean status : isCheckPossible) {
            if (status) {
                return true;
            }
        }
        return false;
    }
}

import java.util.Scanner;

public class InfiniteChess {

    enum PieceType {
        NONE('0', false, false),
        KING('K', false, false),
        QUEEN('Q', true, true),
        ROOK('R', true, false),
        BISHOP('B', false, true);

        private final char symbol;
        private final boolean orthogonal;
        private final boolean diagonal;

        PieceType(char symbol, boolean orthogonal, boolean diagonal) {
            this.symbol = symbol;
            this.orthogonal = orthogonal;
            this.diagonal = diagonal;
        }

        boolean attacks(long fromX, long fromY, long toX, long toY) {
            long dx = toX - fromX;
            long dy = toY - fromY;
            return (orthogonal && (dx == 0 || dy == 0)) ||
                   (diagonal && Math.abs(dx) == Math.abs(dy));
        }

        static PieceType fromSymbol(char symbol) {
            for (PieceType type : values()) {
                if (type.symbol == symbol) return type;
            }
            return null;
        }

        char getSymbol() { return symbol; }
    }

    enum Direction {
        RIGHT(1, 0), LEFT(-1, 0),
        UP(0, 1), DOWN(0, -1),
        UPRIGHT(1, 1), DOWNRIGHT(1, -1),
        UPLEFT(-1, 1), DOWNLEFT(-1, -1);

        private final int dx, dy;

        Direction(int dx, int dy) {
            this.dx = dx;
            this.dy = dy;
        }

        boolean isOnLine(long kingX, long kingY, long pieceX, long pieceY) {
            long diffX = pieceX - kingX;
            long diffY = pieceY - kingY;
            return dx * diffY == dy * diffX;
        }

        boolean isForward(long kingX, long kingY, long pieceX, long pieceY) {
            long diffX = pieceX - kingX;
            long diffY = pieceY - kingY;
            return (dx == 0 || diffX * dx > 0) && (dy == 0 || diffY * dy > 0);
        }

        long distance(long kingX, long kingY, long pieceX, long pieceY) {
            return Math.max(Math.abs(pieceX - kingX), Math.abs(pieceY - kingY));
        }
    }

    static class Piece {
        private final PieceType type;
        private final long x, y;

        Piece(PieceType type, long x, long y) {
            this.type = type;
            this.x = x;
            this.y = y;
        }

        boolean attacks(Piece target) {
            return type.attacks(target.getX(), target.getY(), this.x, this.y);
        }

        PieceType getType() { return type; }
        long getX() { return x; }
        long getY() { return y; }

        @Override
        public String toString() {
            return type.getSymbol() + "(" + x + "," + y + ")";
        }
    }

    static Piece findClosestPieceInDirection(Direction dir, Piece king, Piece[] pieces) {
        Piece closest = null;
        long minDist = Long.MAX_VALUE;
        long kx = king.getX();
        long ky = king.getY();

        for (Piece piece : pieces) {
            if (piece == king) continue;
            long px = piece.getX();
            long py = piece.getY();
            if (dir.isOnLine(kx, ky, px, py) && dir.isForward(kx, ky, px, py)) {
                long dist = dir.distance(kx, ky, px, py);
                if (dist < minDist) {
                    minDist = dist;
                    closest = piece;
                }
            }
        }
        return closest;
    }

    static boolean isKingInCheck(Piece king, Piece[] pieces) {
        for (Direction dir : Direction.values()) {
            Piece closest = findClosestPieceInDirection(dir, king, pieces);
            if (closest != null && closest.attacks(king)) {
                return true;
            }
        }
        return false;
    }

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            if (!scanner.hasNextInt()) return;
            int n = scanner.nextInt();
            long x0 = scanner.nextLong();
            long y0 = scanner.nextLong();
            Piece king = new Piece(PieceType.KING, x0, y0);
            Piece[] pieces = new Piece[n];
            for (int i = 0; i < n; i++) {
                String symbolStr = scanner.next();
                char symbol = symbolStr.charAt(0);
                long x = scanner.nextLong();
                long y = scanner.nextLong();
                PieceType type = PieceType.fromSymbol(symbol);
                pieces[i] = new Piece(type, x, y);
            }

            System.out.println(isKingInCheck(king, pieces) ? "YES" : "NO");
        }
    }
}

import java.io.IOException;
import java.io.InputStream;
import java.util.EnumMap;
import java.util.InputMismatchException;
import java.util.Map;

public class ChessCheckSolver {

    public static void main(String[] args) {
        FastScanner sc = new FastScanner(System.in);
        int n = sc.nextInt();
        int kx = sc.nextInt();
        int ky = sc.nextInt();

        DirectionTracker tracker = new DirectionTracker();

        for (int i = 0; i < n; i++) {
            String typeStr = sc.next();
            char type = typeStr.charAt(0);
            int x = sc.nextInt();
            int y = sc.nextInt();

            int dx = x - kx;
            int dy = y - ky;

            Direction dir = Direction.fromDelta(dx, dy);
            if (dir != Direction.NONE) {
                // For orthogonal and diagonal alignments, |dx| == |dy|
                int dist = Math.abs(dx);
                tracker.update(dir, dist, type);
            }
        }

        System.out.println(tracker.isInCheck() ? "YES" : "NO");
    }

    /**
     * Represents the 8 cardinal and ordinal directions relative to a center point.
     * The exact cardinal naming (e.g., UP vs DOWN) depends on the coordinate system orientation,
     * but the orthogonal/diagonal classification remains mathematically consistent.
     */
    enum Direction {
        UP(0, -1), DOWN(0, 1), LEFT(-1, 0), RIGHT(1, 0),
        UP_RIGHT(1, -1), UP_LEFT(-1, -1), DOWN_RIGHT(1, 1), DOWN_LEFT(-1, 1),
        NONE(0, 0);

        private final int dx, dy;

        Direction(int dx, int dy) {
            this.dx = dx;
            this.dy = dy;
        }

        static Direction fromDelta(int dx, int dy) {
            if (dx == 0 && dy == 0) return NONE;
            if (dx == 0) return dy > 0 ? DOWN : UP;
            if (dy == 0) return dx > 0 ? RIGHT : LEFT;
            if (dx == dy) return dx > 0 ? DOWN_RIGHT : UP_LEFT;
            if (dx == -dy) return dx > 0 ? DOWN_LEFT : UP_RIGHT;
            return NONE;
        }

        boolean isOrthogonal() {
            return dx == 0 || dy == 0;
        }

        boolean isDiagonal() {
            return Math.abs(dx) == Math.abs(dy);
        }
    }

    /**
     * Tracks the closest piece in each of the 8 directions and evaluates check conditions.
     */
    static class DirectionTracker {
        private final Map<Direction, Integer> distances = new EnumMap<>(Direction.class);
        private final Map<Direction, Character> types = new EnumMap<>(Direction.class);

        public DirectionTracker() {
            for (Direction d : Direction.values()) {
                if (d != Direction.NONE) {
                    distances.put(d, Integer.MAX_VALUE);
                    types.put(d, '\0'); // Sentinel for empty direction
                }
            }
        }

        public void update(Direction dir, int dist, char type) {
            if (dist < distances.get(dir)) {
                distances.put(dir, dist);
                types.put(dir, type);
            }
        }

        public boolean isInCheck() {
            for (Direction d : Direction.values()) {
                if (d == Direction.NONE) continue;
                char t = types.get(d);
                if (t == '\0') continue;

                // Rooks and Queens threaten orthogonally
                if (d.isOrthogonal() && (t == 'R' || t == 'Q')) return true;
                // Bishops and Queens threaten diagonally
                if (d.isDiagonal() && (t == 'B' || t == 'Q')) return true;
            }
            return false;
        }
    }

    /**
     * High-performance input scanner for competitive programming.
     */
    static class FastScanner {
        private final InputStream stream;
        private final byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;
        private SpaceCharFilter filter;

        public FastScanner(InputStream stream) {
            this.stream = stream;
        }

        public int read() {
            if (numChars == -1) {
                throw new InputMismatchException();
            }
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0) {
                    return -1;
                }
            }
            return buf[curChar++];
        }

        public int nextInt() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                res *= 10;
                res += c - '0';
                c = read();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public String next() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            StringBuilder res = new StringBuilder();
            do {
                res.appendCodePoint(c);
                c = read();
            } while (!isSpaceChar(c));
            return res.toString();
        }

        public String nextLine() {
            int c = read();
            StringBuilder res = new StringBuilder();
            do {
                res.appendCodePoint(c);
                c = read();
            } while (!isLineEndChar(c));
            return res.toString();
        }

        public double nextDouble() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            double res = 0;
            while (!isSpaceChar(c) && c != '.') {
                if (c == 'e' || c == 'E') {
                    return res * Math.pow(10, nextInt());
                }
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                res *= 10;
                res += c - '0';
                c = read();
            }
            if (c == '.') {
                c = read();
                double m = 1;
                while (!isSpaceChar(c)) {
                    if (c == 'e' || c == 'E') {
                        return res * Math.pow(10, nextInt());
                    }
                    if (c < '0' || c > '9') {
                        throw new InputMismatchException();
                    }
                    m /= 10;
                    res += (c - '0') * m;
                    c = read();
                }
            }
            return res * sgn;
        }

        public long nextLong() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            long res = 0;
            do {
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                res *= 10;
                res += c - '0';
                c = read();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public boolean isSpaceChar(int c) {
            if (filter != null) {
                return filter.isSpaceChar(c);
            }
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        public boolean isLineEndChar(int c) {
            if (filter != null) {
                return filter.isSpaceChar(c);
            }
            return c == '\n' || c == '\r' || c == -1;
        }

        public interface SpaceCharFilter {
            boolean isSpaceChar(int ch);
        }
    }
}

import java.util.Scanner;

/**
 * Determines if a 4x4 grid contains any 3-cell line (row, column, or diagonal)
 * with exactly two 'x' characters. The third character in such a line must be '.'.
 */
public class Main {
    private static final int GRID_SIZE = 4;
    private static final int LINE_LENGTH = 3;

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            char[][] grid = readGrid(scanner);
            System.out.println(hasValidPattern(grid) ? "YES" : "NO");
        }
    }

    /**
     * Reads the 4x4 grid from standard input.
     */
    private static char[][] readGrid(Scanner scanner) {
        char[][] grid = new char[GRID_SIZE][GRID_SIZE];
        for (int i = 0; i < GRID_SIZE; i++) {
            grid[i] = scanner.next().toCharArray();
        }
        return grid;
    }

    /**
     * Checks if any row, column, or diagonal contains the target pattern.
     */
    private static boolean hasValidPattern(char[][] grid) {
        return checkRows(grid) || checkCols(grid) || checkDiagonals(grid);
    }

    /**
     * Checks all horizontal 3-cell segments in the grid.
     */
    private static boolean checkRows(char[][] grid) {
        for (int r = 0; r < GRID_SIZE; r++) {
            for (int c = 0; c <= GRID_SIZE - LINE_LENGTH; c++) {
                if (countXInLine(grid, r, c, 0, 1) == 2) return true;
            }
        }
        return false;
    }

    /**
     * Checks all vertical 3-cell segments in the grid.
     */
    private static boolean checkCols(char[][] grid) {
        for (int c = 0; c < GRID_SIZE; c++) {
            for (int r = 0; r <= GRID_SIZE - LINE_LENGTH; r++) {
                if (countXInLine(grid, r, c, 1, 0) == 2) return true;
            }
        }
        return false;
    }

    /**
     * Checks all diagonal 3-cell segments in the grid.
     */
    private static boolean checkDiagonals(char[][] grid) {
        // Main diagonals (top-left to bottom-right)
        for (int r = 0; r <= GRID_SIZE - LINE_LENGTH; r++) {
            for (int c = 0; c <= GRID_SIZE - LINE_LENGTH; c++) {
                if (countXInLine(grid, r, c, 1, 1) == 2) return true;
            }
        }
        // Anti-diagonals (top-right to bottom-left)
        for (int r = 0; r <= GRID_SIZE - LINE_LENGTH; r++) {
            for (int c = LINE_LENGTH - 1; c < GRID_SIZE; c++) {
                if (countXInLine(grid, r, c, 1, -1) == 2) return true;
            }
        }
        return false;
    }

    /**
     * Counts the number of 'x' characters in a 3-cell line starting at (startRow, startCol)
     * with the given direction vector (dRow, dCol).
     */
    private static int countXInLine(char[][] grid, int startRow, int startCol, int dRow, int dCol) {
        int count = 0;
        for (int i = 0; i < LINE_LENGTH; i++) {
            if (grid[startRow + i * dRow][startCol + i * dCol] == 'x') {
                count++;
            }
        }
        return count;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

public class IlleyaAndTTT {

    public static void main(String[] args) {
        FastReader reader = new FastReader();
        char[][] grid = new char[4][4];

        // Read the 4 rows of the grid
        for (int i = 0; i < 4; i++) {
            String row = reader.next();
            if (row != null) {
                grid[i] = row.toCharArray();
            }
        }

        // Check if the pattern exists and print result
        if (hasPattern(grid)) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }
    }

    /**
     * Checks if the grid contains any sequence of three cells (horizontal,
     * vertical, or diagonal) that matches the pattern: exactly two 'x's and one '.'.
     */
    private static boolean hasPattern(char[][] grid) {
        int n = grid.length;

        // 1. Check horizontal sequences
        for (int r = 0; r < n; r++) {
            for (int c = 0; c <= n - 3; c++) {
                if (matchesPattern(grid[r][c], grid[r][c + 1], grid[r][c + 2])) {
                    return true;
                }
            }
        }

        // 2. Check vertical sequences
        for (int c = 0; c < n; c++) {
            for (int r = 0; r <= n - 3; r++) {
                if (matchesPattern(grid[r][c], grid[r + 1][c], grid[r + 2][c])) {
                    return true;
                }
            }
        }

        // 3. Check diagonal (top-left to bottom-right) sequences
        for (int r = 0; r <= n - 3; r++) {
            for (int c = 0; c <= n - 3; c++) {
                if (matchesPattern(grid[r][c], grid[r + 1][c + 1], grid[r + 2][c + 2])) {
                    return true;
                }
            }
        }

        // 4. Check diagonal (top-right to bottom-left) sequences
        for (int r = 0; r <= n - 3; r++) {
            for (int c = 2; c < n; c++) {
                if (matchesPattern(grid[r][c], grid[r + 1][c - 1], grid[r + 2][c - 2])) {
                    return true;
                }
            }
        }

        return false;
    }

    /**
     * Determines if three characters form the target pattern:
     * exactly two 'x's and one '.'.
     */
    private static boolean matchesPattern(char a, char b, char c) {
        int xCount = (a == 'x' ? 1 : 0) + (b == 'x' ? 1 : 0) + (c == 'x' ? 1 : 0);
        int dotCount = (a == '.' ? 1 : 0) + (b == '.' ? 1 : 0) + (c == '.' ? 1 : 0);
        return xCount == 2 && dotCount == 1;
    }

    /**
     * Optimized input reader for competitive programming.
     */
    static class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return st.nextToken();
        }
    }
}

import java.util.Scanner;

public class TicTacToe {

    // Constants to define the board size and winning pattern parameters
    private static final int BOARD_SIZE = 4;
    private static final int LINE_LENGTH = 3;
    private static final char EMPTY_CELL = '.';
    private static final char PLAYER_MARK = 'x';

    public static void main(String[] args) {
        // Use try-with-resources to ensure the Scanner is closed properly
        try (Scanner scanner = new Scanner(System.in)) {
            char[][] board = new char[BOARD_SIZE][BOARD_SIZE];

            // Read the 4 rows of the board from input
            for (int i = 0; i < BOARD_SIZE; i++) {
                if (scanner.hasNextLine()) {
                    String row = scanner.nextLine();
                    // Fill the board row, handling cases where input might be short
                    for (int j = 0; j < BOARD_SIZE && j < row.length(); j++) {
                        board[i][j] = row.charAt(j);
                    }
                }
            }

            // Check if the specific pattern exists on the board
            boolean hasPattern = checkBoard(board);

            // Output the result
            System.out.println(hasPattern ? "YES" : "NO");
        }
    }

    /**
     * Iterates through all possible lines (rows, columns, diagonals)
     * to check if the target pattern exists.
     */
    private static boolean checkBoard(char[][] board) {
        // 1. Check Rows
        for (int r = 0; r < BOARD_SIZE; r++) {
            for (int c = 0; c <= BOARD_SIZE - LINE_LENGTH; c++) {
                if (checkLine(board[r][c], board[r][c + 1], board[r][c + 2])) {
                    return true;
                }
            }
        }

        // 2. Check Columns
        for (int c = 0; c < BOARD_SIZE; c++) {
            for (int r = 0; r <= BOARD_SIZE - LINE_LENGTH; r++) {
                if (checkLine(board[r][c], board[r + 1][c], board[r + 2][c])) {
                    return true;
                }
            }
        }

        // 3. Check Main Diagonals (Top-Left to Bottom-Right)
        for (int r = 0; r <= BOARD_SIZE - LINE_LENGTH; r++) {
            for (int c = 0; c <= BOARD_SIZE - LINE_LENGTH; c++) {
                if (checkLine(board[r][c], board[r + 1][c + 1], board[r + 2][c + 2])) {
                    return true;
                }
            }
        }

        // 4. Check Anti-Diagonals (Top-Right to Bottom-Left)
        for (int r = 0; r <= BOARD_SIZE - LINE_LENGTH; r++) {
            for (int c = LINE_LENGTH - 1; c < BOARD_SIZE; c++) {
                if (checkLine(board[r][c], board[r + 1][c - 1], board[r + 2][c - 2])) {
                    return true;
                }
            }
        }

        return false;
    }

    /**
     * Checks if a sequence of three characters matches the pattern:
     * Two 'x's and one empty space '.' in any order.
     * Valid patterns: ".xx", "x.x", "xx."
     */
    private static boolean checkLine(char c1, char c2, char c3) {
        return (c1 == EMPTY_CELL && c2 == PLAYER_MARK && c3 == PLAYER_MARK) ||
               (c1 == PLAYER_MARK && c2 == EMPTY_CELL && c3 == PLAYER_MARK) ||
               (c1 == PLAYER_MARK && c2 == PLAYER_MARK && c3 == EMPTY_CELL);
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;

public class Main {
    // Constants for board dimensions and window size
    private static final int BOARD_SIZE = 4;
    private static final int WINDOW_SIZE = 3;

    public static void main(String[] args) throws IOException {
        // Use try-with-resources for automatic resource management
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            char[][] board = readBoard(br);

            if (hasPattern(board)) {
                System.out.println("YES");
            } else {
                System.out.println("NO");
            }
        }
    }

    /**
     * Reads the 4x4 board from standard input.
     */
    private static char[][] readBoard(BufferedReader br) throws IOException {
        char[][] board = new char[BOARD_SIZE][BOARD_SIZE];
        for (int i = 0; i < BOARD_SIZE; i++) {
            String line = br.readLine();
            if (line != null) {
                // Trim whitespace to ensure clean character array
                board[i] = line.trim().toCharArray();
            }
        }
        return board;
    }

    /**
     * Checks if the board contains a valid pattern in any 3x3 window.
     */
    private static boolean hasPattern(char[][] board) {
        // Iterate through all valid top-left corners of the 3x3 window.
        // Valid range is 0 to BOARD_SIZE - WINDOW_SIZE
        int maxIndex = BOARD_SIZE - WINDOW_SIZE;
        for (int r = 0; r <= maxIndex; r++) {
            for (int c = 0; c <= maxIndex; c++) {
                if (checkWindow(board, r, c)) {
                    return true;
                }
            }
        }
        return false;
    }

    /**
     * Checks a specific 3x3 window defined by top-left corner (r, c).
     * Returns true if any row, column, or diagonal within this window
     * satisfies the condition (2 'x's and 1 '.').
     */
    private static boolean checkWindow(char[][] board, int r, int c) {
        // Check horizontal lines within the window
        for (int i = r; i < r + WINDOW_SIZE; i++) {
            if (checkSegment(board, i, c, 0, 1)) return true;
        }

        // Check vertical lines within the window
        for (int j = c; j < c + WINDOW_SIZE; j++) {
            if (checkSegment(board, r, j, 1, 0)) return true;
        }

        // Check main diagonal (top-left to bottom-right)
        if (checkSegment(board, r, c, 1, 1)) return true;

        // Check anti-diagonal (bottom-left to top-right)
        // Starts at (r + WINDOW_SIZE - 1, c) and moves up-right
        if (checkSegment(board, r + WINDOW_SIZE - 1, c, -1, 1)) return true;

        return false;
    }

    /**
     * Checks a line segment of length 3 starting at (startR, startC).
     * Direction is defined by (dRow, dCol).
     * Returns true if the segment contains exactly two 'x's and one '.'.
     */
    private static boolean checkSegment(char[][] board, int startR, int startC, int dRow, int dCol) {
        int xCount = 0;
        int dotCount = 0;

        for (int k = 0; k < WINDOW_SIZE; k++) {
            int row = startR + k * dRow;
            int col = startC + k * dCol;

            // Safety check for array bounds, though logic guarantees validity
            if (row >= 0 && row < BOARD_SIZE && col >= 0 && col < BOARD_SIZE) {
                char cell = board[row][col];
                if (cell == 'x') {
                    xCount++;
                } else if (cell == '.') {
                    dotCount++;
                }
            }
        }

        return xCount == 2 && dotCount == 1;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.math.BigInteger;
import java.util.StringTokenizer;

public class Main {

    // Constant for grid dimensions to avoid magic numbers
    private static final int GRID_SIZE = 4;

    public static void main(String[] args) {
        // Setup I/O
        InputReader reader = new InputReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            // 1. Read the input grid
            char[][] grid = readGrid(reader);

            // 2. Evaluate win condition
            boolean canWin = checkWinCondition(grid);

            // 3. Output result
            out.println(canWin ? "YES" : "NO");

        } catch (Exception e) {
            // In a production app, proper logging would go here.
            e.printStackTrace();
        } finally {
            out.flush();
            out.close();
        }
    }

    /**
     * Reads the 4x4 character grid from the input.
     */
    private static char[][] readGrid(InputReader reader) {
        char[][] grid = new char[GRID_SIZE][GRID_SIZE];
        for (int i = 0; i < GRID_SIZE; i++) {
            String line = reader.next();
            if (line != null) {
                grid[i] = line.toCharArray();
            }
        }
        return grid;
    }

    /**
     * Checks if the grid contains a winning sequence.
     * A winning sequence is defined as 3 consecutive cells (horizontal, vertical, or diagonal)
     * containing exactly two 'x's and one '.'.
     */
    private static boolean checkWinCondition(char[][] grid) {
        // Check Horizontal sequences
        for (int r = 0; r < GRID_SIZE; r++) {
            for (int c = 0; c <= GRID_SIZE - 3; c++) {
                if (isWinningSequence(grid[r][c], grid[r][c + 1], grid[r][c + 2])) {
                    return true;
                }
            }
        }

        // Check Vertical sequences
        for (int r = 0; r <= GRID_SIZE - 3; r++) {
            for (int c = 0; c < GRID_SIZE; c++) {
                if (isWinningSequence(grid[r][c], grid[r + 1][c], grid[r + 2][c])) {
                    return true;
                }
            }
        }

        // Check Diagonal sequences (Top-Left to Bottom-Right)
        for (int r = 0; r <= GRID_SIZE - 3; r++) {
            for (int c = 0; c <= GRID_SIZE - 3; c++) {
                if (isWinningSequence(grid[r][c], grid[r + 1][c + 1], grid[r + 2][c + 2])) {
                    return true;
                }
            }
        }

        // Check Diagonal sequences (Top-Right to Bottom-Left)
        // We iterate rows 0 to 1, and columns 2 to 3 to ensure we have space for 2 steps left
        for (int r = 0; r <= GRID_SIZE - 3; r++) {
            for (int c = 2; c < GRID_SIZE; c++) {
                if (isWinningSequence(grid[r][c], grid[r + 1][c - 1], grid[r + 2][c - 2])) {
                    return true;
                }
            }
        }

        return false;
    }

    /**
     * Determines if a sequence of 3 characters meets the winning criteria.
     * Criteria: Exactly two 'x' characters and one '.' character.
     */
    private static boolean isWinningSequence(char c1, char c2, char c3) {
        int xCount = 0;
        int dotCount = 0;

        if (c1 == 'x') xCount++; else if (c1 == '.') dotCount++;
        if (c2 == 'x') xCount++; else if (c2 == '.') dotCount++;
        if (c3 == 'x') xCount++; else if (c3 == '.') dotCount++;

        return xCount == 2 && dotCount == 1;
    }

    /**
     * Helper class for fast input reading.
     */
    public static class InputReader {
        public BufferedReader reader;
        public StringTokenizer tokenizer;

        public InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            String s = next();
            if (s == null) throw new RuntimeException("Unexpected end of input");
            return Integer.parseInt(s);
        }

        public long nextLong() {
            String s = next();
            if (s == null) throw new RuntimeException("Unexpected end of input");
            return Long.parseLong(s);
        }

        public double nextDouble() {
            String s = next();
            if (s == null) throw new RuntimeException("Unexpected end of input");
            return Double.parseDouble(s);
        }

        public BigInteger nextBigInteger() {
            String s = next();
            if (s == null) throw new RuntimeException("Unexpected end of input");
            return new BigInteger(s);
        }
    }
}

import java.io.*;
import java.math.*;
import java.util.*;

public class R390_Div2_B {
    // Extracted magic numbers into named constants for maintainability
    private static final int GRID_SIZE = 4;
    private static final int LINE_LENGTH = 3;
    private static final int MAX_DOTS = 1;

    public static void main(String[] args) {
        new R390_Div2_B().run();
    }

    public void run() {
        FastReader in = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);
        solve(in, out);
        out.close();
    }

    public void runWithFiles() {
        File inputFile = new File("input.txt");
        File outputFile = new File("output.txt");

        // Try-with-resources ensures streams are properly closed even if exceptions occur
        try (FastReader in = new FastReader(inputFile);
             PrintWriter out = new PrintWriter(outputFile)) {
            solve(in, out);
        } catch (FileNotFoundException e) {
            e.printStackTrace();
        }
    }

    /**
     * Separates I/O handling from the core algorithm.
     */
    private void solve(FastReader in, PrintWriter out) {
        String[] grid = new String[GRID_SIZE];
        for (int i = 0; i < GRID_SIZE; i++) {
            grid[i] = in.next();
        }

        out.println(checkSolution(grid) ? "YES" : "NO");
        out.flush();
    }

    /**
     * Checks if a valid line exists in the grid.
     * Uses direction arrays to simplify the 8-direction iteration.
     */
    private boolean checkSolution(String[] grid) {
        int[] dx = {-1, -1, -1, 0, 0, 1, 1, 1};
        int[] dy = {-1, 0, 1, -1, 1, -1, 0, 1};

        for (int i = 0; i < GRID_SIZE; i++) {
            for (int j = 0; j < GRID_SIZE; j++) {
                for (int d = 0; d < 8; d++) {
                    if (isValidLine(grid, i, j, dx[d], dy[d])) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Validates a potential line starting at (startX, startY) in direction (dx, dy).
     * Returns true if the line fits within bounds, contains no 'o', and has at most MAX_DOTS '.'.
     */
    private boolean isValidLine(String[] grid, int startX, int startY, int dx, int dy) {
        int dotCount = 0;
        for (int k = 0; k < LINE_LENGTH; k++) {
            int x = startX + dx * k;
            int y = startY + dy * k;

            // Boundary check
            if (x < 0 || x >= GRID_SIZE || y < 0 || y >= GRID_SIZE) {
                return false;
            }

            char cell = grid[x].charAt(y);
            if (cell == 'o') {
                return false;
            }
            if (cell == '.') {
                dotCount++;
            }
        }
        return dotCount <= MAX_DOTS;
    }

    /**
     * Static nested class for fast input reading.
     * Improved exception handling and resource management.
     */
    static class FastReader {
        private final BufferedReader br;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            br = new BufferedReader(new InputStreamReader(stream));
        }

        public FastReader(File file) {
            try {
                br = new BufferedReader(new FileReader(file));
            } catch (FileNotFoundException e) {
                throw new RuntimeException("Failed to open file: " + file.getAbsolutePath(), e);
            }
        }

        String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input stream", e);
                }
            }
            return tokenizer.nextToken();
        }

        String nextLine() {
            try {
                return br.readLine();
            } catch (IOException e) {
                throw new RuntimeException("Error reading line", e);
            }
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        long nextLong() {
            return Long.parseLong(next());
        }

        double nextDouble() {
            return Double.parseDouble(next());
        }

        BigInteger nextBigInteger() {
            return new BigInteger(next());
        }

        BigDecimal nextBigDecimal() {
            return new BigDecimal(next());
        }
    }
}

