    private static final int TARGET_SUM = 2;

    // Mapping characters to integer values based on problem logic
    private static final int X_VALUE = 1;
    private static final int O_VALUE = -11;
    private static final int EMPTY_VALUE = 0;

    public static void main(String[] args) {
        // Initialize Input/Output readers
        InputReader in = new InputReader(System.in);
        OutputWriter out = new OutputWriter(System.out);

        // Execute the solver
        new Solver().solve(in, out);

        // Clean up resources
        out.close();
    }

    /**
     * Contains the core logic for solving the problem.
     */
    static class Solver {
        public void solve(InputReader in, OutputWriter out) {
            int[][] board = new int[BOARD_SIZE][BOARD_SIZE];

            // Read the board configuration from input
            for (int r = 0; r < BOARD_SIZE; r++) {
                String line = in.next();
                if (line == null) break; // Handle potential EOF gracefully

                for (int c = 0; c < BOARD_SIZE; c++) {
                    char ch = line.charAt(c);
                    if (ch == 'x') {
                        board[r][c] = X_VALUE;
                    } else if (ch == 'o') {
                        board[r][c] = O_VALUE;
                    } else {
                        board[r][c] = EMPTY_VALUE;
                    }
                }
            }

            boolean found = false;

            // Define directions to check: Horizontal, Vertical, Diagonals
            // Each direction is represented as {row_delta, col_delta}
            int[][] directions = {
                {0, 1},  // Horizontal
                {1, 0},  // Vertical
                {1, 1},  // Diagonal Down-Right
                {1, -1}  // Diagonal Down-Left
            };

            // Iterate through every cell to check if it can be the start of a valid line
            outerLoop:
            for (int r = 0; r < BOARD_SIZE; r++) {
                for (int c = 0; c < BOARD_SIZE; c++) {
                    for (int[] dir : directions) {
                        // Calculate the end coordinates of the line of length LINE_LENGTH
                        int endR = r + (LINE_LENGTH - 1) * dir[0];
                        int endC = c + (LINE_LENGTH - 1) * dir[1];

                        // Check if the line stays within board boundaries
                        if (endR < BOARD_SIZE && endC < BOARD_SIZE && endC >= 0) {
                            int currentSum = 0;
                            // Sum the values in the line
                            for (int k = 0; k < LINE_LENGTH; k++) {
                                currentSum += board[r + k * dir[0]][c + k * dir[1]];
                            }

                            // Check against the target sum
                            if (currentSum == TARGET_SUM) {
                                found = true;
                                break outerLoop; // Found a valid line, exit loops
                            }
                        }
                    }
                }
            }

            // Output the result
            out.println(found ? "YES" : "NO");
        }
    }

    /**
     * Helper class for fast input reading.
     */
    static class InputReader {
        public BufferedReader reader;
        public StringTokenizer tokenizer;

        public InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }
    }

    /**
     * Helper class for fast output writing.
     */
    static class OutputWriter {
        private final PrintWriter writer;

        public OutputWriter(OutputStream outputStream) {
            writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(outputStream)));
        }

        public void println(Object... objects) {
            print(objects);
            writer.println();
        }

        private void print(Object... objects) {
            for (int i = 0; i < objects.length; i++) {
                if (i != 0) writer.print(' ');
                writer.print(objects[i]);
            }
        }

        public void close() {
            writer.close();
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.Set;

public class Main {
    private static final int GRID_SIZE = 4;
    private static final Set<String> REQUIRED_PATTERNS = Set.of(".xx", "xx.", "x.x");

    public static void main(String[] args) throws IOException {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter out = new PrintWriter(System.out);

        try {
            char[][] grid = readGrid(reader);
            boolean found = checkGridForPatterns(grid);
            out.println(found ? "YES" : "NO");
        } catch (IOException e) {
            out.println("ERROR: " + e.getMessage());
        } finally {
            out.flush();
        }
    }

    /**
     * Reads a 4x4 character grid from standard input.
     */
    private static char[][] readGrid(BufferedReader reader) throws IOException {
        char[][] grid = new char[GRID_SIZE][GRID_SIZE];
        for (int i = 0; i < GRID_SIZE; i++) {
            String line = reader.readLine();
            if (line == null) {
                throw new IOException("Unexpected end of input at row " + i);
            }
            line = line.trim();
            if (line.length() < GRID_SIZE) {
                throw new IOException("Row " + i + " has insufficient characters");
            }
            grid[i] = line.toCharArray();
        }
        return grid;
    }

    /**
     * Checks the grid for any required 3-character pattern in all directions.
     */
    private static boolean checkGridForPatterns(char[][] grid) {
        // Directions: Right, Down, Down-Right, Down-Left
        int[] dr = {0, 1, 1, 1};
        int[] dc = {1, 0, 1, -1};

        for (int r = 0; r < GRID_SIZE; r++) {
            for (int c = 0; c < GRID_SIZE; c++) {
                for (int d = 0; d < dr.length; d++) {
                    if (hasRequiredPattern(grid, r, c, dr[d], dc[d])) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Validates if a 3-character segment starting at (r, c) in direction (dr, dc)
     * matches any required pattern. Returns false if the segment goes out of bounds.
     */
    private static boolean hasRequiredPattern(char[][] grid, int r, int c, int dr, int dc) {
        int endR = r + 2 * dr;
        int endC = c + 2 * dc;

        // Ensure the entire 3-character segment stays within grid bounds
        if (endR < 0 || endR >= GRID_SIZE || endC < 0 || endC >= GRID_SIZE) {
            return false;
        }

        String segment = "" + grid[r][c] + grid[r + dr][c + dc] + grid[endR][endC];
        return REQUIRED_PATTERNS.contains(segment);
    }
}

import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

/**
 * Checks a 4x4 grid of strings for specific diagonal, row, and column patterns.
 * Refactored for improved maintainability, readability, and robustness.
 */
public class GridPatternChecker {

    private static final String[] TARGET_PATTERNS = {"x.x", ".xx", "xx."};
    private static final int GRID_SIZE = 4;

    public static void main(String[] args) {
        // Use try-with-resources to automatically close the Scanner
        try (Scanner scanner = new Scanner(System.in)) {
            String[] grid = readGrid(scanner);

            if (hasMatchingPattern(grid)) {
                System.out.println("YES");
            } else {
                System.out.println("NO");
            }
        }
    }

    /**
     * Reads exactly 4 lines of input into a grid array.
     */
    private static String[] readGrid(Scanner scanner) {
        String[] grid = new String[GRID_SIZE];
        for (int i = 0; i < GRID_SIZE; i++) {
            grid[i] = scanner.nextLine();
        }
        return grid;
    }

    /**
     * Checks rows, columns, and all relevant diagonals for target patterns.
     */
    private static boolean hasMatchingPattern(String[] grid) {
        // 1. Check rows
        for (String row : grid) {
            if (matchesPattern(row)) {
                return true;
            }
        }

        // 2. Check columns
        for (int col = 0; col < GRID_SIZE; col++) {
            StringBuilder colBuilder = new StringBuilder(GRID_SIZE);
            for (String row : grid) {
                if (col < row.length()) {
                    colBuilder.append(row.charAt(col));
                }
            }
            if (matchesPattern(colBuilder.toString())) {
                return true;
            }
        }

        // 3. Check diagonals
        List<String> diagonals = extractDiagonals(grid);
        for (String diagonal : diagonals) {
            if (matchesPattern(diagonal)) {
                return true;
            }
        }

        return false;
    }

    /**
     * Extracts all diagonals of length 3 and 4 from the grid.
     */
    private static List<String> extractDiagonals(String[] grid) {
        List<String> diagonals = new ArrayList<>();

        // Main diagonals (top-left to bottom-right)
        diagonals.add(buildDiagonal(grid, 0, 0, 1, 1));
        diagonals.add(buildDiagonal(grid, 1, 0, 1, 1));
        diagonals.add(buildDiagonal(grid, 0, 1, 1, 1));

        // Anti-diagonals (top-right to bottom-left)
        diagonals.add(buildDiagonal(grid, 0, GRID_SIZE - 1, 1, -1));
        diagonals.add(buildDiagonal(grid, 0, GRID_SIZE - 2, 1, -1));
        diagonals.add(buildDiagonal(grid, 1, GRID_SIZE - 1, 1, -1));

        return diagonals;
    }

    /**
     * Builds a string along a diagonal path within the grid bounds.
     */
    private static String buildDiagonal(String[] grid, int startRow, int startCol, int rowStep, int colStep) {
        StringBuilder sb = new StringBuilder(GRID_SIZE);
        for (int i = 0; i < GRID_SIZE; i++) {
            int r = startRow + i * rowStep;
            int c = startCol + i * colStep;

            // Safe bounds checking to prevent IndexOutOfBoundsException
            if (r >= 0 && r < grid.length && c >= 0 && c < grid[r].length()) {
                sb.append(grid[r].charAt(c));
            }
        }
        return sb.toString();
    }

    /**
     * Checks if a string contains any of the target patterns.
     * Equivalent to the original check() method but cleaner and more efficient.
     */
    private static boolean matchesPattern(String s) {
        if (s == null || s.length() < 3) {
            return false;
        }
        for (String pattern : TARGET_PATTERNS) {
            if (s.contains(pattern)) {
                return true;
            }
        }
        return false;
    }
}

