        // Pattern 4: (3,1), (2,2), (1,3)
        if (checkShortLine(board[3][1], board[2][2], board[1][3])) return true;

        return false;
    }

    /**
     * Retrieves a specific row from the board.
     */
    private static int[] getRow(int[][] board, int row) {
        int[] line = new int[BOARD_SIZE];
        for (int j = 0; j < BOARD_SIZE; j++) {
            line[j] = board[row][j];
        }
        return line;
    }

    /**
     * Retrieves a specific column from the board.
     */
    private static int[] getColumn(int[][] board, int col) {
        int[] line = new int[BOARD_SIZE];
        for (int i = 0; i < BOARD_SIZE; i++) {
            line[i] = board[i][col];
        }
        return line;
    }

    /**
     * Retrieves the main diagonal (top-left to bottom-right).
     */
    private static int[] getMainDiagonal(int[][] board) {
        int[] line = new int[BOARD_SIZE];
        for (int i = 0; i < BOARD_SIZE; i++) {
            line[i] = board[i][i];
        }
        return line;
    }

    /**
     * Retrieves the anti-diagonal (top-right to bottom-left).
     */
    private static int[] getAntiDiagonal(int[][] board) {
        int[] line = new int[BOARD_SIZE];
        for (int i = 0; i < BOARD_SIZE; i++) {
            line[i] = board[i][BOARD_SIZE - 1 - i];
        }
        return line;
    }

    /**
     * Checks the specific logic for standard lines (Rows, Cols, Diagonals).
     * Original Logic: (line[0]+line[1]+line[2])==2 || (line[3]+line[1]+line[2])==2
     */
    private static boolean checkStandardLine(int[] line) {
        int sumFirstThree = line[0] + line[1] + line[2];
        int sumLastAndMiddleTwo = line[3] + line[1] + line[2];
        return (sumFirstThree == TARGET_SUM) || (sumLastAndMiddleTwo == TARGET_SUM);
    }

    /**
     * Checks the specific logic for short lines (test1 array).
     * Original Logic: line[0]+line[1]+line[2] == 2
     */
    private static boolean checkShortLine(int a, int b, int c) {
        return (a + b + c) == TARGET_SUM;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

/**
 * Checks a 4x4 grid for a specific pattern of '.' and 'x' characters.
 * The pattern consists of any three collinear cells where exactly one is '.'
 * and the other two are 'x'.
 */
public class GridPatternChecker {

    private static final int GRID_SIZE = 4;
    // Defines the 4 main axes (horizontal, vertical, and two diagonals).
    // Each axis is represented by two opposite direction vectors: [dr1, dc1, dr2, dc2]
    private static final int[][] AXES = {
        {1, 0, -1, 0},      // Horizontal
        {0, 1, 0, -1},      // Vertical
        {1, 1, -1, -1},     // Main Diagonal
        {1, -1, -1, 1}      // Anti-Diagonal
    };

    public static void main(String[] args) throws IOException {
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(System.in))) {
            char[][] grid = readGrid(reader);
            boolean patternFound = checkForPattern(grid);
            System.out.println(patternFound ? "YES" : "NO");
        }
    }

    /**
     * Reads the 4x4 character grid from standard input.
     */
    private static char[][] readGrid(BufferedReader reader) throws IOException {
        char[][] grid = new char[GRID_SIZE][GRID_SIZE];
        StringTokenizer tokenizer = new StringTokenizer("");

        for (int i = 0; i < GRID_SIZE; i++) {
            while (!tokenizer.hasMoreTokens()) {
                String line = reader.readLine();
                if (line == null) break;
                tokenizer = new StringTokenizer(line);
            }
            if (tokenizer.hasMoreTokens()) {
                grid[i] = tokenizer.nextToken().toCharArray();
            }
        }
        return grid;
    }

    /**
     * Iterates through every cell to check if it participates in a valid pattern.
     */
    private static boolean checkForPattern(char[][] grid) {
        for (int row = 0; row < GRID_SIZE; row++) {
            for (int col = 0; col < GRID_SIZE; col++) {
                if (hasPatternAround(grid, row, col)) {
                    return true;
                }
            }
        }
        return false;
    }

    /**
     * Checks the four axes passing through (row, col) for the target pattern.
     */
    private static boolean hasPatternAround(char[][] grid, int row, int col) {
        for (int[] axis : AXES) {
            int r1 = row + axis[0];
            int c1 = col + axis[1];
            int r2 = row + axis[2];
            int c2 = col + axis[3];

            if (!isInsideBounds(grid, r1, c1) || !isInsideBounds(grid, r2, c2)) {
                continue;
            }

            // The original logic checks for exactly one '.' among three collinear cells.
            int dotCount = countDots(grid, r1, c1, row, col, r2, c2);
            if (dotCount == 1) {
                return true;
            }
        }
        return false;
    }

    /**
     * Counts how many of the three specified cells contain '.'.
     */
    private static int countDots(char[][] grid, int r1, int c1, int rMid, int cMid, int r2, int c2) {
        return (grid[r1][c1] == '.' ? 1 : 0) +
               (grid[rMid][cMid] == '.' ? 1 : 0) +
               (grid[r2][c2] == '.' ? 1 : 0);
    }

    /**
     * Validates that coordinates are within the grid boundaries.
     */
    private static boolean isInsideBounds(char[][] grid, int r, int c) {
        return r >= 0 && r < grid.length && c >= 0 && c < grid[0].length;
    }
}

import java.util.Scanner;
import java.io.PrintWriter;

/**
 * Refactored version of SolutionB.
 * 
 * Improvements made:
 * 1. Removed magic numbers (e.g., 4, 2, 0) in favor of named constants.
 * 2. Encapsulated logic into specific methods (readGrid, checkPatterns, checkLine)
 *    to improve readability and separation of concerns.
 * 3. Eliminated code duplication (DRY principle) by using a unified loop structure
 *    with direction vectors to check rows, columns, and diagonals.
 * 4. Removed class-level mutable state (fields like 'ans', 'grid', 'cin', 'cout')
 *    in favor of local variables and method parameters, making the class stateless.
 * 5. Improved resource management for PrintWriter.
 */
public class SolutionB {

    private static final int GRID_SIZE = 4;
    private static final int PATTERN_LENGTH = 3;

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            char[][] grid = readGrid(scanner);
            boolean result = checkPatterns(grid);
            out.println(result ? "YES" : "NO");
        } finally {
            out.flush();
            // Note: Closing scanner on System.in is generally not required 
            // for short-lived programs, but good practice in larger apps.
        }
    }

    /**
     * Reads the 4x4 grid from the input.
     */
    private static char[][] readGrid(Scanner scanner) {
        char[][] grid = new char[GRID_SIZE][GRID_SIZE];
        for (int i = 0; i < GRID_SIZE; i++) {
            if (scanner.hasNext()) {
                String line = scanner.next();
                grid[i] = line.toCharArray();
            }
        }
        return grid;
    }

    /**
     * Checks the grid for the specified pattern in all directions.
     */
    private static boolean checkPatterns(char[][] grid) {
        // Directions: Right, Down, Down-Right, Down-Left
        int[] dr = {0, 1, 1, 1};
        int[] dc = {1, 0, 1, -1};

        for (int r = 0; r < GRID_SIZE; r++) {
            for (int c = 0; c < GRID_SIZE; c++) {
                for (int d = 0; d < 4; d++) {
                    int endR = r + (PATTERN_LENGTH - 1) * dr[d];
                    int endC = c + (PATTERN_LENGTH - 1) * dc[d];

                    // Check if the pattern fits within the grid boundaries
                    if (isWithinBounds(endR, endC)) {
                        if (checkLine(grid, r, c, dr[d], dc[d])) {
                            return true;
                        }
                    }
                }
            }
        }
        return false;
    }

    /**
     * Checks if coordinates are within the grid.
     */
    private static boolean isWithinBounds(int r, int c) {
        return r >= 0 && r < GRID_SIZE && c >= 0 && c < GRID_SIZE;
    }

    /**
     * Checks a specific line of 3 cells starting at (r, c) with step (dr, dc).
     * Valid patterns: x x ., x . x, . x x
     */
    private static boolean checkLine(char[][] grid, int r, int c, int dr, int dc) {
        char c1 = grid[r][c];
        char c2 = grid[r + dr][c + dc];
        char c3 = grid[r + 2 * dr][c + 2 * dc];

        if (c1 == 'x' && c2 == 'x' && c3 == '.') return true;
        if (c1 == 'x' && c2 == '.' && c3 == 'x') return true;
        if (c1 == '.' && c2 == 'x' && c3 == 'x') return true;

        return false;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.OutputStream;
import java.io.PrintWriter;
import java.util.StringTokenizer;

public class Main {
    private static final int GRID_SIZE = 4;
    // Direction vectors for all 8 neighbors (horizontal, vertical, diagonal)
    private static final int[] DR = {-1, -1, -1, 0, 0, 1, 1, 1};
    private static final int[] DC = {-1, 0, 1, -1, 1, -1, 0, 1};

    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        new TaskB().solve(in, out);
        out.close();
    }

    static class TaskB {
        public void solve(InputReader in, PrintWriter out) {
            char[][] grid = new char[GRID_SIZE][GRID_SIZE];
            for (int i = 0; i < GRID_SIZE; i++) {
                String row = in.next();
                grid[i] = row.toCharArray();
            }

            for (int i = 0; i < GRID_SIZE; i++) {
                for (int j = 0; j < GRID_SIZE; j++) {
                    if (grid[i][j] == 'x') {
                        if (hasAdjacentPattern(grid, i, j)) {
                            out.println("YES");
                            return;
                        }
                    }
                }
            }
            out.println("NO");
        }

        /**
         * Checks if the cell at (r, c) is part of the target pattern in any of the 8 directions.
         * The pattern is either "x x ." or "x . x" extending from the current 'x'.
         */
        private boolean hasAdjacentPattern(char[][] grid, int r, int c) {
            for (int dir = 0; dir < 8; dir++) {
                int dr = DR[dir];
                int dc = DC[dir];
                int r1 = r + dr;
                int c1 = c + dc;
                int r2 = r + 2 * dr;
                int c2 = c + 2 * dc;

                if (isValid(grid, r1, c1) && isValid(grid, r2, c2)) {
                    char mid = grid[r1][c1];
                    char far = grid[r2][c2];
                    if ((mid == 'x' && far == '.') || (far == 'x' && mid == '.')) {
                        return true;
                    }
                }
            }
            return false;
        }

        private boolean isValid(char[][] grid, int r, int c) {
            return r >= 0 && r < GRID_SIZE && c >= 0 && c < GRID_SIZE;
        }
    }

    static class InputReader {
        public BufferedReader reader;
        public StringTokenizer tokenizer;

        public InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

public class Main {
    public static void main(String[] args) {
        FastScanner in = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out);
        TaskB solver = new TaskB();
        solver.solve(in, out);
        out.close();
    }

    static class TaskB {
        private static final int GRID_SIZE = 4;

        // Offsets for the third cell in a 3-cell sequence (row, col).
        // Covers all 8 directions: Up, Down, Left, Right, and 4 diagonals.
        private static final int[] DR = {-2, 2, 0, 0, -2, 2, -2, 2};
        private static final int[] DC = {0, 0, -2, 2, 2, 2, -2, -2};

        public void solve(FastScanner in, PrintWriter out) {
            char[][] grid = new char[GRID_SIZE][GRID_SIZE];
            for (int i = 0; i < GRID_SIZE; i++) {
                String line = in.next();
                for (int j = 0; j < GRID_SIZE; j++) {
                    grid[i][j] = line.charAt(j);
                }
            }

            out.println(hasPattern(grid) ? "YES" : "NO");
        }

        private boolean hasPattern(char[][] grid) {
            int n = grid.length;
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < n; j++) {
                    if (grid[i][j] != 'x') {
                        continue;
                    }

                    for (int k = 0; k < DR.length; k++) {
                        int r2 = i + DR[k];
                        int c2 = j + DC[k];

                        // Check bounds for the second cell in the sequence.
                        // If the second cell is in bounds, the first cell (r1, c1) is guaranteed to be in bounds.
                        if (r2 < 0 || r2 >= n || c2 < 0 || c2 >= n) {
                            continue;
                        }

                        int r1 = i + DR[k] / 2;
                        int c1 = j + DC[k] / 2;

                        // Check if the two cells in the direction alternate ('.' and 'x')
                        boolean alternates = (grid[r1][c1] == '.' && grid[r2][c2] == 'x') ||
                                             (grid[r1][c1] == 'x' && grid[r2][c2] == '.');
                        if (alternates) {
                            return true;
                        }
                    }
                }
            }
            return false;
        }
    }

    static class FastScanner {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastScanner(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) {
                        return null;
                    }
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Input reading failed", e);
                }
            }
            return tokenizer.nextToken();
        }
    }
}

import java.util.Scanner;

/**
 * Analyzes a 4x4 grid to detect a specific pattern involving 'x', '.', and 'o' characters.
 * The pattern checks for a sequence of length 3 (starting from an 'x') 
 * where the next two cells contain exactly one 'x' and one '.' in any order.
 */
public class Main {
    // Constants for grid configuration and cell values
    private static final int GRID_SIZE = 4;
    private static final int TYPE_X = 1;
    private static final int TYPE_DOT = 0;
    private static final int TYPE_O = -1;

    public static void main(String[] args) {
        // Use try-with-resources to ensure Scanner is closed properly
        try (Scanner scanner = new Scanner(System.in)) {
            int[][] grid = readGrid(scanner);
            boolean result = hasPattern(grid);
            System.out.println(result ? "YES" : "NO");
        }
    }

    /**
     * Reads the 4x4 grid from standard input.
     */
    private static int[][] readGrid(Scanner scanner) {
        int[][] grid = new int[GRID_SIZE][GRID_SIZE];
        for (int i = 0; i < GRID_SIZE; i++) {
            if (scanner.hasNextLine()) {
                String line = scanner.nextLine();
                // Parse characters into integer values
                // Added length check to prevent IndexOutOfBoundsException on short lines
                for (int j = 0; j < GRID_SIZE && j < line.length(); j++) {
                    char c = line.charAt(j);
                    if (c == 'x') {
                        grid[i][j] = TYPE_X;
                    } else if (c == '.') {
                        grid[i][j] = TYPE_DOT;
                    } else if (c == 'o') {
                        grid[i][j] = TYPE_O;
                    }
                }
            }
        }
        return grid;
    }

    /**
     * Checks if the grid contains the specified pattern.
     * The pattern is defined as: Starting from a cell with 'x', 
     * look in all 8 directions. If the cell at distance 1 and distance 2 
     * form a pair of (X, .) or (., X), return true.
     */
    private static boolean hasPattern(int[][] grid) {
        // Direction vectors for the 8 neighbors (dx, dy)
        // Covers: Horizontal, Vertical, and both Diagonals
        int[] dx = {-1, -1, -1, 0, 0, 1, 1, 1};
        int[] dy = {-1, 0, 1, -1, 1, -1, 0, 1};

        // Iterate over every cell in the grid
        for (int r = 0; r < GRID_SIZE; r++) {
            for (int c = 0; c < GRID_SIZE; c++) {

                // The original logic only checked patterns originating from 'x' cells
                if (grid[r][c] == TYPE_X) {

                    // Check all 8 directions
                    for (int k = 0; k < dx.length; k++) {
                        int dr = dx[k];
                        int dc = dy[k];

                        // Calculate coordinates for distance 1 and distance 2
                        int r1 = r + dr;
                        int c1 = c + dc;
                        int r2 = r + 2 * dr;
                        int c2 = c + 2 * dc;

                        // Check bounds for the furthest point (distance 2).
                        // If distance 2 is within bounds, distance 1 is guaranteed to be within bounds
                        // for a square grid and these step sizes.
                        if (r2 >= 0 && r2 < GRID_SIZE && c2 >= 0 && c2 < GRID_SIZE) {

                            int val1 = grid[r1][c1];
                            int val2 = grid[r2][c2];

                            // Check the specific pattern: (X, .) or (., X)
                            // Note: The current cell (r,c) is known to be X.
                            if ((val1 == TYPE_X && val2 == TYPE_DOT) || 
                                (val1 == TYPE_DOT && val2 == TYPE_X)) {
                                return true;
                            }
                        }
                    }
                }
            }
        }
        return false;
    }
}

import java.util.Scanner;

/**
 * A refactored version of the TicTacToe solver.
 * This version improves maintainability by:
 * 1. Using descriptive class and variable names.
 * 2. Removing magic numbers (like array size 8 and indices 2-6) in favor of clear constants or bounds.
 * 3. Encapsulating the complex winning logic into a helper method.
 * 4. Removing the boolean flag 'fl' and loop breaks in favor of immediate returns.
 * 5. Using a standard 4x4 array instead of a padded 8x8 array, making the logic easier to follow.
 */
public class TicTacToe {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        // The original code used an 8x8 array to handle boundary checks implicitly.
        // We use a standard 4x4 array and handle boundaries explicitly in the logic.
        char[][] board = new char[4][4];

        // Read the 4x4 grid from input
        // The original code expected 4 tokens (strings), each representing a row.
        for (int i = 0; i < 4; i++) {
            if (scanner.hasNext()) {
                String row = scanner.next();
                for (int j = 0; j < 4; j++) {
                    // Safe access to character, preventing IndexOutOfBounds if string is short
                    if (j < row.length()) {
                        board[i][j] = row.charAt(j);
                    }
                }
            }
        }

        // Check if 'x' has a winning move and print the result
        if (canWin(board)) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }

        scanner.close();
    }

    /**
     * Checks if the player 'x' has a winning move.
     * A winning move exists if there is any line of 3 cells (horizontal, vertical, or diagonal)
     * that contains exactly two 'x's and one empty spot ('.').
     */
    private static boolean canWin(char[][] board) {
        // Check horizontal lines
        for (int r = 0; r < 4; r++) {
            for (int c = 0; c <= 1; c++) {
                if (hasWinningPattern(board[r][c], board[r][c + 1], board[r][c + 2])) {
                    return true;
                }
            }
        }

        // Check vertical lines
        for (int r = 0; r <= 1; r++) {
            for (int c = 0; c < 4; c++) {
                if (hasWinningPattern(board[r][c], board[r + 1][c], board[r + 2][c])) {
                    return true;
                }
            }
        }

        // Check main diagonals (top-left to bottom-right)
        for (int r = 0; r <= 1; r++) {
            for (int c = 0; c <= 1; c++) {
                if (hasWinningPattern(board[r][c], board[r + 1][c + 1], board[r + 2][c + 2])) {
                    return true;
                }
            }
        }

        // Check anti-diagonals (top-right to bottom-left)
        for (int r = 0; r <= 1; r++) {
            for (int c = 2; c < 4; c++) {
                if (hasWinningPattern(board[r][c], board[r + 1][c - 1], board[r + 2][c - 2])) {
                    return true;
                }
            }
        }

        return false;
    }

    /**
     * Determines if a line of 3 cells represents a potential win for 'x'.
     * A potential win is defined as having exactly two 'x's and one empty spot ('.').
     */
    private static boolean hasWinningPattern(char c1, char c2, char c3) {
        int xCount = 0;
        int emptyCount = 0;

        if (c1 == 'x') xCount++;
        else if (c1 == '.') emptyCount++;

        if (c2 == 'x') xCount++;
        else if (c2 == '.') emptyCount++;

        if (c3 == 'x') xCount++;
        else if (c3 == '.') emptyCount++;

        return xCount == 2 && emptyCount == 1;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

public class ProbB {

    public static void main(String[] args) {
        // Use try-with-resources for automatic and safe resource management
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
             PrintWriter out = new PrintWriter(System.out)) {

            solve(reader, out);
        } catch (IOException e) {
            // In production code, log this appropriately instead of printing to stderr
            e.printStackTrace();
        }
    }

    /**
     * Orchestrates the reading of input, game state analysis, and output generation.
     */
    private static void solve(BufferedReader reader, PrintWriter out) throws IOException {
        char[][] board = new char[4][4];
        StringTokenizer st = new StringTokenizer("");

        // Read the 4x4 game board, skipping any leading whitespace/empty lines
        for (int i = 0; i < 4; i++) {
            while (!st.hasMoreTokens()) {
                String line = reader.readLine();
                if (line == null) break;
                st = new StringTokenizer(line);
            }
            if (st.hasMoreTokens()) {
                board[i] = st.nextToken().toCharArray();
            }
        }

        int xCount = 0;
        int oCount = 0;

        // Count occurrences to determine whose turn it is
        for (char[] row : board) {
            for (char cell : row) {
                if (cell == 'x') xCount++;
                else if (cell == 'o') oCount++;
            }
        }

        char currentPlayer = (xCount == oCount) ? 'x' : 'o';

        // Check if the current player can win in exactly one move
        boolean canWin = canWinInOneMove(board, currentPlayer);
        out.println(canWin ? "YES" : "NO");
    }

    /**
     * Determines if the given player can form a line of 3 by placing their piece
     * in any empty spot ('.').
     */
    private static boolean canWinInOneMove(char[][] board, char player) {
        // Direction vectors: right, down, down-right (main diagonal), down-left (anti-diagonal)
        int[] dr = {0, 1, 1, 1};
        int[] dc = {1, 0, 1, -1};

        for (int r = 0; r < 4; r++) {
            for (int c = 0; c < 4; c++) {
                if (board[r][c] == '.') {
                    // Check all 4 directions from this empty cell
                    for (int d = 0; d < 4; d++) {
                        if (checksWinningLine(board, r, c, dr[d], dc[d], player)) {
                            return true;
                        }
                    }
                }
            }
        }
        return false;
    }

    /**
     * Checks if placing 'player' at the empty position completes a line of 3
     * in the given direction starting from (r, c).
     */
    private static boolean checksWinningLine(char[][] board, int r, int c, int dr, int dc, char player) {
        int r1 = r;
        int c1 = c;
        int r2 = r + dr;
        int c2 = c + dc;
        int r3 = r + 2 * dr;
        int c3 = c + 2 * dc;

        // Ensure all three positions are within the 4x4 grid boundaries
        if (r3 < 0 || r3 >= 4 || c3 < 0 || c3 >= 4) {
            return false;
        }

        char p1 = board[r1][c1];
        char p2 = board[r2][c2];
        char p3 = board[r3][c3];

        // Valid winning patterns: [player, player, .], [player, ., player], [., player, player]
        return (p1 == player && p2 == player && p3 == '.') ||
               (p1 == player && p2 == '.' && p3 == player) ||
               (p1 == '.' && p2 == player && p3 == player);
    }
}

import java.util.Scanner;

/**
 * Refactored version of Raund_B.
 * 
 * This program checks if a 4x4 grid contains a specific pattern of characters.
 * The pattern consists of a sequence of 3 cells (horizontal, vertical, or diagonal)
 * that contains at least two 'x' characters and at least one '.' character.
 * 
 * Original Logic Analysis:
 * The original code iterated through every cell. If a cell was '.', it checked its 
 * neighbors to see if they formed a triplet with two 'x's (patterns like "x.x", "xx.", ".xx").
 * 
 * Refactored Logic:
 * We iterate through all possible lines of length 3 in the grid (horizontal, vertical, 
 * and diagonal). For each line, we count the occurrences of 'x' and '.'. If a line 
 * contains at least 2 'x's and at least 1 '.', the pattern is found.
 */
public class Raund_B {
    private static final int GRID_SIZE = 4;
    private static final char COCKROACH = 'x';
    private static final char EMPTY = '.';

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        char[][] grid = new char[GRID_SIZE][GRID_SIZE];

        // Read the grid from input
        for (int i = 0; i < GRID_SIZE; i++) {
            if (scanner.hasNext()) {
                String row = scanner.next();
                grid[i] = row.toCharArray();
            }
        }

        // Check for the pattern and print result
        if (hasPattern(grid)) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }

        scanner.close();
    }

    /**
     * Checks if the grid contains a valid pattern of 3 cells (line)
     * with at least two 'x's and one '.'.
     */
    private static boolean hasPattern(char[][] grid) {
        int n = grid.length;

        // Directions to check: Right, Down, Down-Right, Down-Left
        // These 4 directions are sufficient to cover all lines of length 3 
        // starting from any cell (since order doesn't matter for the set of chars).
        int[] dRow = {0, 1, 1, 1};
        int[] dCol = {1, 0, 1, -1};

        for (int r = 0; r < n; r++) {
            for (int c = 0; c < n; c++) {
                for (int k = 0; k < 4; k++) {
                    if (isLineValid(grid, r, c, dRow[k], dCol[k])) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Checks if the line of 3 cells starting at (r, c) in direction (dr, dc)
     * is valid and within bounds.
     */
    private static boolean isLineValid(char[][] grid, int r, int c, int dr, int dc) {
        int n = grid.length;

        // Coordinates of the 3 cells in the line
        int r1 = r;
        int c1 = c;
        int r2 = r + dr;
        int c2 = c + dc;
        int r3 = r + 2 * dr;
        int c3 = c + 2 * dc;

        // Check bounds for all 3 cells
        if (!inBounds(n, r1, c1) || !inBounds(n, r2, c2) || !inBounds(n, r3, c3)) {
            return false;
        }

        char cell1 = grid[r1][c1];
        char cell2 = grid[r2][c2];
        char cell3 = grid[r3][c3];

        int xCount = 0;
        int dotCount = 0;

        // Count 'x' and '.' in the line
        if (cell1 == COCKROACH) xCount++;
        else if (cell1 == EMPTY) dotCount++;

        if (cell2 == COCKROACH) xCount++;
        else if (cell2 == EMPTY) dotCount++;

        if (cell3 == COCKROACH) xCount++;
        else if (cell3 == EMPTY) dotCount++;

        // A valid pattern must have at least 2 'x's and at least 1 '.'
        return xCount >= 2 && dotCount >= 1;
    }

    /**
     * Checks if coordinates are within the grid boundaries.
     */
    private static boolean inBounds(int n, int r, int c) {
        return r >= 0 && r < n && c >= 0 && c < n;
    }
}

import java.io.*;
import java.util.StringTokenizer;

public class Main {
    private static final int GRID_SIZE = 4;
    private static char[][] grid;
    private static boolean found = false;

    public static void main(String[] args) throws IOException {
        FastScanner in = new FastScanner(System.in);
        grid = new char[GRID_SIZE][GRID_SIZE];

        // Read the 4x4 grid
        for (int i = 0; i < GRID_SIZE; i++) {
            grid[i] = in.next().toCharArray();
        }

        // Check patterns in order, short-circuiting once a valid pattern is found
        checkRows();
        if (!found) checkCols();
        if (!found) checkShortDiagonals();
        if (!found) checkLongDiagonals();

        System.out.println(found ? "YES" : "NO");
    }

    /**
     * Checks all rows for a valid pattern.
     */
    private static void checkRows() {
        if (found) return;
        for (int i = 0; i < GRID_SIZE; i++) {
            if (checkLine(grid[i])) {
                found = true;
                return;
            }
        }
    }

    /**
     * Checks all columns for a valid pattern.
     */
    private static void checkCols() {
        if (found) return;
        for (int i = 0; i < GRID_SIZE; i++) {
            char[] col = new char[GRID_SIZE];
            for (int j = 0; j < GRID_SIZE; j++) {
                col[j] = grid[j][i];
            }
            if (checkLine(col)) {
                found = true;
                return;
            }
        }
    }

    /**
     * Validates the standard 4-cell line conditions (rows/cols).
     */
    private static boolean checkLine(char[] line) {
        // Skip if middle cells contain 'o'
        if (line[1] == 'o' || line[2] == 'o') return false;
        // Skip if middle cells don't contain at least one 'x'
        if (line[1] != 'x' && line[2] != 'x') return false;
        // Skip if both ends contain 'o'
        if (line[0] == 'o' && line[3] == 'o') return false;

        int count = 0;
        for (char c : line) {
            if (c == 'x') count++;
        }
        return count >= 2;
    }

    /**
     * Checks all length-3 diagonals for a valid pattern.
     */
    private static void checkShortDiagonals() {
        if (found) return;

        char[][] shortDiags = {
            {grid[0][1], grid[1][2], grid[2][3]},
            {grid[1][0], grid[2][1], grid[3][2]},
            {grid[0][2], grid[1][1], grid[2][0]},
            {grid[1][3], grid[2][2], grid[3][1]}
        };

        for (char[] line : shortDiags) {
            if (checkShortLine(line)) {
                found = true;
                return;
            }
        }
    }

    /**
     * Validates the 3-cell diagonal conditions.
     */
    private static boolean checkShortLine(char[] line) {
        if (line[0] == 'o' || line[1] == 'o' || line[2] == 'o') return false;

        int count = 0;
        for (char c : line) {
            if (c == 'x') count++;
        }
        return count >= 2;
    }

    /**
     * Checks both main and anti-diagonals (length 4) for valid patterns.
     */
    private static void checkLongDiagonals() {
        if (found) return;

        char[] mainDiag = {grid[0][0], grid[1][1], grid[2][2], grid[3][3]};
        char[] antiDiag = {grid[0][3], grid[1][2], grid[2][1], grid[3][0]};

        if (checkLongLine(mainDiag)) found = true;
        if (!found && checkLongLine(antiDiag)) found = true;
    }

    /**
     * Validates the 4-cell diagonal conditions with corner override logic.
     */
    private static boolean checkLongLine(char[] line) {
        // Middle cells must not be 'o'
        if (line[1] == 'o' || line[2] == 'o') return false;
        // At least one middle cell must be 'x'
        if (line[1] != 'x' && line[2] != 'x') return false;

        int count = 0;
        for (char c : line) {
            if (c == 'x') count++;
        }

        boolean isValid = count >= 2;

        // Corner override: if both corners are 'o', the pattern is invalid
        if (line[0] == 'o' && line[3] == 'o') {
            isValid = false;
        }

        return isValid;
    }

    /**
     * Fast input scanner for competitive programming / performance-critical IO.
     */
    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer tokenizer;

        FastScanner(InputStream is) {
            br = new BufferedReader(new InputStreamReader(is));
        }

        FastScanner(String fileName) throws FileNotFoundException {
            this(new FileInputStream(new File(fileName)));
        }

        String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        long nextLong() throws IOException {
            return Long.parseLong(next());
        }

        char nextChar() throws IOException {
            return next().charAt(0);
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;

public class TicTacToe {

    private static final int BOARD_SIZE = 4;
    private char[][] board;

    public static void main(String[] args) {
        TicTacToe game = new TicTacToe();
        try {
            // Attempt to read input and initialize the board
            if (game.initializeBoard()) {
                // Check for the winning pattern
                if (game.hasWinningPattern()) {
                    System.out.println("YES");
                } else {
                    System.out.println("NO");
                }
            }
        } catch (IOException e) {
            System.err.println("An error occurred while reading input.");
            e.printStackTrace();
        }
    }

    /**
     * Reads the 4x4 board from standard input.
     * @return true if input was read successfully, false otherwise.
     * @throws IOException if an I/O error occurs.
     */
    private boolean initializeBoard() throws IOException {
        board = new char[BOARD_SIZE][BOARD_SIZE];
        // Using BufferedReader for efficient input reading
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            for (int i = 0; i < BOARD_SIZE; i++) {
                String line = br.readLine();
                // Basic validation to ensure line is not null and has enough characters
                if (line == null || line.length() < BOARD_SIZE) {
                    return false;
                }
                for (int j = 0; j < BOARD_SIZE; j++) {
                    board[i][j] = line.charAt(j);
                }
            }
        }
        return true;
    }

    /**
     * Checks if the board contains the specific pattern "xx.", "x.x", or ".xx"
     * in any direction (horizontal, vertical, or diagonal).
     * @return true if the pattern is found, false otherwise.
     */
    private boolean hasWinningPattern() {
        // Directions to check: Right, Down, Down-Right, Down-Left.
        // We check these 4 directions from every cell.
        // Since the target patterns ("xx.", "x.x", ".xx") are symmetric with respect to reversal 
        // (e.g., reverse of "xx." is ".xx", which is also a valid pattern), 
        // checking forward directions is sufficient to cover all cases.
        int[][] directions = {
            {0, 1},   // Horizontal Right
            {1, 0},   // Vertical Down
            {1, 1},   // Diagonal Down-Right
            {1, -1}   // Diagonal Down-Left
        };

        for (int i = 0; i < BOARD_SIZE; i++) {
            for (int j = 0; j < BOARD_SIZE; j++) {
                for (int[] dir : directions) {
                    if (checkLine(i, j, dir[0], dir[1])) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Checks a specific line of 3 cells starting at (r, c) in direction (dr, dc).
     * @param r Starting row index.
     * @param c Starting column index.
     * @param dr Row direction increment (-1, 0, 1).
     * @param dc Column direction increment (-1, 0, 1).
     * @return true if the pattern is found in this line, false otherwise.
     */
    private boolean checkLine(int r, int c, int dr, int dc) {
        // Calculate indices for the 3 cells in the sequence
        int r1 = r;
        int c1 = c;
        int r2 = r + dr;
        int c2 = c + dc;
        int r3 = r + 2 * dr;
        int c3 = c + 2 * dc;

        // Check bounds for the last cell (r3, c3).
        // Since dr and dc are in {-1, 0, 1}, checking the furthest point 
        // ensures all points in the sequence are within bounds.
        if (r3 >= 0 && r3 < BOARD_SIZE && c3 >= 0 && c3 < BOARD_SIZE) {
            char c1Val = board[r1][c1];
            char c2Val = board[r2][c2];
            char c3Val = board[r3][c3];

            return matchesPattern(c1Val, c2Val, c3Val);
        }
        return false;
    }

    /**
     * Checks if three characters match the pattern "xx.", "x.x", or ".xx".
     * @param c1 First character.
     * @param c2 Second character.
     * @param c3 Third character.
     * @return true if the pattern matches, false otherwise.
     */
    private boolean matchesPattern(char c1, char c2, char c3) {
        // Matches "xx.", "x.x", ".xx"
        // This logic is equivalent to the original string contains checks
        return (c1 == 'x' && c2 == 'x' && c3 == '.') ||
               (c1 == 'x' && c2 == '.' && c3 == 'x') ||
               (c1 == '.' && c2 == 'x' && c3 == 'x');
    }
}

import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.InputMismatchException;

public class Solution {
    private static final int GRID_SIZE = 4;
    private static final String[] PATTERNS = {".xx", "xx.", "x.x"};

    public static void main(String[] args) {
        InputReader reader = new InputReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        char[][] grid = new char[GRID_SIZE][GRID_SIZE];
        for (int i = 0; i < GRID_SIZE; i++) {
            grid[i] = reader.readLine().toCharArray();
        }

        if (hasMatchingPattern(grid)) {
            writer.println("YES");
        } else {
            writer.println("NO");
        }

        writer.flush();
    }

    private static boolean hasMatchingPattern(char[][] grid) {
        // Check rows
        for (int i = 0; i < GRID_SIZE; i++) {
            if (matchesPattern(new String(grid[i]))) {
                return true;
            }
        }

        // Check columns
        for (int j = 0; j < GRID_SIZE; j++) {
            StringBuilder col = new StringBuilder(GRID_SIZE);
            for (int i = 0; i < GRID_SIZE; i++) {
                col.append(grid[i][j]);
            }
            if (matchesPattern(col.toString())) {
                return true;
            }
        }

        // Check diagonals (both down-right and down-left directions)
        int[][] directions = {{1, 1}, {1, -1}};
        for (int[] dir : directions) {
            for (int i = 0; i < GRID_SIZE; i++) {
                for (int j = 0; j < GRID_SIZE; j++) {
                    StringBuilder diag = new StringBuilder();
                    int r = i, c = j;
                    while (r >= 0 && r < GRID_SIZE && c >= 0 && c < GRID_SIZE) {
                        diag.append(grid[r][c]);
                        r += dir[0];
                        c += dir[1];
                    }
                    if (matchesPattern(diag.toString())) {
                        return true;
                    }
                }
            }
        }

        return false;
    }

    private static boolean matchesPattern(String line) {
        for (String pattern : PATTERNS) {
            if (line.contains(pattern)) {
                return true;
            }
        }
        return false;
    }

    /**
     * Fast input reader commonly used in competitive programming.
     */
    static class InputReader {
        private final InputStream stream;
        private final byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;
        private SpaceCharFilter filter;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        public int read() {
            if (numChars == -1) {
                throw new InputMismatchException();
            }
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0) {
                    return -1;
                }
            }
            return buf[curChar++];
        }

        public int readInt() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                res *= 10;
                res += c - '0';
                c = read();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public String readString() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            StringBuilder res = new StringBuilder();
            do {
                res.appendCodePoint(c);
                c = read();
            } while (!isSpaceChar(c));
            return res.toString();
        }

        public String readLine() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            StringBuilder res = new StringBuilder();
            do {
                res.appendCodePoint(c);
                c = read();
            } while (!isEndOfLine(c));
            return res.toString();
        }

        public double readDouble() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            double res = 0;
            while (!isSpaceChar(c) && c != '.') {
                if (c == 'e' || c == 'E') {
                    return res * Math.pow(10, readInt());
                }
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                res *= 10;
                res += c - '0';
                c = read();
            }
            if (c == '.') {
                c = read();
                double m = 1;
                while (!isSpaceChar(c)) {
                    if (c == 'e' || c == 'E') {
                        return res * Math.pow(10, readInt());
                    }
                    if (c < '0' || c > '9') {
                        throw new InputMismatchException();
                    }
                    m /= 10;
                    res += (c - '0') * m;
                    c = read();
                }
            }
            return res * sgn;
        }

        public long readLong() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            long res = 0;
            do {
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                res *= 10;
                res += c - '0';
                c = read();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public boolean isSpaceChar(int c) {
            if (filter != null) {
                return filter.isSpaceChar(c);
            }
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        public String next() {
            return readString();
        }

        public interface SpaceCharFilter {
            boolean isSpaceChar(int ch);
        }

        public boolean isEndOfLine(int c) {
            return c == '\n' || c == '\r' || c == -1;
        }
    }
}

import java.util.Scanner;
import java.io.PrintWriter;
import java.io.BufferedOutputStream;

public class Acontest {
    // Configuration constants for easy maintenance and scaling
    private static final int GRID_SIZE = 4;
    private static final int PATTERN_LENGTH = 3;
    private static final char TARGET_CHAR = 'x';
    private static final char EMPTY_CHAR = '.';

    public static void main(String[] args) {
        // try-with-resources ensures proper cleanup of I/O streams
        try (Scanner scanner = new Scanner(System.in);
             PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out))) {
            new Acontest().solve(scanner, out);
            out.flush(); // Guarantee output is written to console
        }
    }

    void solve(Scanner in, PrintWriter out) {
        char[][] grid = readGrid(in);
        boolean found = hasTargetPattern(grid);
        out.print(found ? "YES" : "NO");
    }

    // Handles input parsing and validation separately from business logic
    private char[][] readGrid(Scanner in) {
        char[][] grid = new char[GRID_SIZE][GRID_SIZE];
        for (int i = 0; i < GRID_SIZE; i++) {
            String line = in.next();
            if (line.length() != GRID_SIZE) {
                throw new IllegalArgumentException("Invalid grid row length at index " + i);
            }
            grid[i] = line.toCharArray();
        }
        return grid;
    }

    // Checks all horizontal, vertical, and diagonal sequences efficiently
    private boolean hasTargetPattern(char[][] grid) {
        // Directions: right, down, down-right, down-left
        int[][] directions = {
            {0, 1},
            {1, 0},
            {1, 1},
            {-1, 1}
        };

        for (int[] dir : directions) {
            for (int r = 0; r < GRID_SIZE; r++) {
                for (int c = 0; c < GRID_SIZE; c++) {
                    if (matchesPattern(grid, r, c, dir[0], dir[1])) {
                        return true; // Early exit on first match
                    }
                }
            }
        }
        return false;
    }

    // Validates grid bounds and checks the 3-character sequence against target patterns
    private boolean matchesPattern(char[][] grid, int r, int c, int dRow, int dCol) {
        int endRow = r + (PATTERN_LENGTH - 1) * dRow;
        int endCol = c + (PATTERN_LENGTH - 1) * dCol;

        // Ensure the entire pattern fits within the grid boundaries
        if (endRow < 0 || endRow >= GRID_SIZE || endCol < 0 || endCol >= GRID_SIZE) {
            return false;
        }

        char c1 = grid[r][c];
        char c2 = grid[r + dRow][c + dCol];
        char c3 = grid[endRow][endCol];

        // Check against the three valid patterns: xx., .xx, x.x
        return (c1 == TARGET_CHAR && c2 == TARGET_CHAR && c3 == EMPTY_CHAR) ||
               (c1 == EMPTY_CHAR && c2 == TARGET_CHAR && c3 == TARGET_CHAR) ||
               (c1 == TARGET_CHAR && c2 == EMPTY_CHAR && c3 == TARGET_CHAR);
    }
}

import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

/**
 * Analyzes a 4x4 game board to determine if a winning condition is met.
 * Refactored for improved maintainability, type safety, and readability.
 */
public class BoardAnalyzer {

    // Constant for board dimensions to avoid magic numbers
    private static final int BOARD_SIZE = 4;

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        char[][] board = new char[BOARD_SIZE][];

        // Read the board rows from input
        for (int i = 0; i < BOARD_SIZE; i++) {
            if (scanner.hasNext()) {
                board[i] = scanner.next().toCharArray();
            }
        }
        scanner.close();

        // Check for winning condition and print result
        if (analyzeBoard(board)) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }
    }

    /**
     * Orchestrates the checks for rows, columns, and diagonals.
     */
    private static boolean analyzeBoard(char[][] board) {
        return checkRows(board) ||
               checkColumns(board) ||
               checkRightDownDiagonals(board) ||
               checkLeftDownDiagonals(board);
    }

    /**
     * Checks all horizontal rows for a winning sequence.
     */
    private static boolean checkRows(char[][] board) {
        for (char[] row : board) {
            if (isWinningAnswer(toCharacterList(row))) {
                return true;
            }
        }
        return false;
    }

    /**
     * Checks all vertical columns for a winning sequence.
     */
    private static boolean checkColumns(char[][] board) {
        for (int col = 0; col < BOARD_SIZE; col++) {
            List<Character> column = new ArrayList<>();
            for (int row = 0; row < BOARD_SIZE; row++) {
                column.add(board[row][col]);
            }
            if (isWinningAnswer(column)) {
                return true;
            }
        }
        return false;
    }

    /**
     * Checks all diagonals going down-right (Top-Left to Bottom-Right direction).
     * Iterates through every cell to start a diagonal segment.
     */
    private static boolean checkRightDownDiagonals(char[][] board) {
        for (int i = 0; i < BOARD_SIZE; i++) {
            for (int j = 0; j < BOARD_SIZE; j++) {
                List<Character> diagonal = new ArrayList<>();
                int r = i, c = j;
                // Collect diagonal segment starting at (i, j) going down-right
                while (r < BOARD_SIZE && c < BOARD_SIZE) {
                    diagonal.add(board[r][c]);
                    r++;
                    c++;
                }
                if (isWinningAnswer(diagonal)) {
                    return true;
                }
            }
        }
        return false;
    }

    /**
     * Checks all diagonals going down-left (Top-Right to Bottom-Left direction).
     * Iterates through every cell to start a diagonal segment.
     */
    private static boolean checkLeftDownDiagonals(char[][] board) {
        for (int i = 0; i < BOARD_SIZE; i++) {
            for (int j = 0; j < BOARD_SIZE; j++) {
                List<Character> diagonal = new ArrayList<>();
                int r = i, c = j;
                // Collect diagonal segment starting at (i, j) going down-left
                while (r < BOARD_SIZE && c >= 0) {
                    diagonal.add(board[r][c]);
                    r++;
                    c--;
                }
                if (isWinningAnswer(diagonal)) {
                    return true;
                }
            }
        }
        return false;
    }

    /**
     * Determines if a sequence of characters represents a winning answer
     * based on the specific rules provided in the original logic.
     *
     * @param list The sequence of characters to analyze.
     * @return true if the sequence meets the winning criteria, false otherwise.
     */
    private static boolean isWinningAnswer(List<Character> list) {
        // Count occurrences of 'x'
        long xCounter = list.stream().filter(c -> c == 'x').count();

        // Rule: Must have at least two 'x's to be a winning answer
        if (xCounter < 2) {
            return false;
        }

        // Rule 1: Size 3, exactly two 'x's, contains '.'
        if (list.size() == 3 && xCounter == 2 && list.contains('.')) {
            return true;
        }

        // Rule 2 & 3: Size 4 logic
        if (list.size() == 4) {
            boolean hasO = list.contains('o');
            boolean hasDot = list.contains('.');

            if (hasO && hasDot) {
                // Condition: Not 'o' at index 1 AND Not 'o' at index 2
                // Note: Indices are 0-based. list.get(1) is the 2nd element.
                if (list.get(1) != 'o' && list.get(2) != 'o') {
                    return true;
                }
            } else if (!hasO) {
                // Condition: 'x' at index 1 OR 'x' at index 2
                // Note: xCounter >= 2 is guaranteed by the check at the top of this method.
                if (list.get(1) == 'x' || list.get(2) == 'x') {
                    return true;
                }
            }
        }

        return false;
    }

    /**
     * Helper method to convert a char array to a List of Characters.
     */
    private static List<Character> toCharacterList(char[] array) {
        List<Character> list = new ArrayList<>(array.length);
        for (char c : array) {
            list.add(c);
        }
        return list;
    }
}

import java.util.Scanner;

public class GridPatternChecker {

    private static final String[] TARGET_PATTERNS = {"x.x", "xx.", ".xx"};

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            String[] grid = new String[4];
            for (int i = 0; i < 4; i++) {
                grid[i] = scanner.nextLine();
            }

            boolean found = checkHorizontal(grid)
                        || checkVertical(grid)
                        || checkDiagonal(grid);

            System.out.println(found ? "YES" : "NO");
        }
    }

    private static boolean hasPattern(String line) {
        for (String pattern : TARGET_PATTERNS) {
            if (line.contains(pattern)) {
                return true;
            }
        }
        return false;
    }

    private static boolean checkHorizontal(String[] grid) {
        for (String row : grid) {
            if (hasPattern(row)) {
                return true;
            }
        }
        return false;
    }

    private static boolean checkVertical(String[] grid) {
        for (int col = 0; col < 4; col++) {
            StringBuilder column = new StringBuilder();
            for (String row : grid) {
                column.append(row.charAt(col));
            }
            if (hasPattern(column.toString())) {
                return true;
            }
        }
        return false;
    }

    private static boolean checkDiagonal(String[] grid) {
        // All possible diagonals of length >= 3 in a 4x4 grid
        String[] diagonals = {
            getDiagonal(grid, 0, 0, 1, 1), // Main diagonal
            getDiagonal(grid, 0, 3, 1, -1), // Anti-diagonal
            getDiagonal(grid, 0, 1, 1, 1),  // Upper-right sub-diagonal
            getDiagonal(grid, 1, 0, 1, 1),  // Lower-left sub-diagonal
            getDiagonal(grid, 0, 2, 1, -1), // Upper-left sub-anti-diagonal
            getDiagonal(grid, 1, 3, 1, -1)  // Lower-right sub-anti-diagonal
        };

        for (String diag : diagonals) {
            if (hasPattern(diag)) {
                return true;
            }
        }
        return false;
    }

    private static String getDiagonal(String[] grid, int startRow, int startCol, int rowStep, int colStep) {
        StringBuilder sb = new StringBuilder();
        int r = startRow;
        int c = startCol;
        while (r >= 0 && r < 4 && c >= 0 && c < 4) {
            sb.append(grid[r].charAt(c));
            r += rowStep;
            c += colStep;
        }
        return sb.toString();
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

public class Main {
    // Grid dimensions and direction vectors (Down-Right, Down-Left, Down, Right)
    private static final int GRID_SIZE = 4;
    private static final int[] DR = {1, 1, 1, 0};
    private static final int[] DC = {1, -1, 0, 1};

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner();
        PrintWriter out = new PrintWriter(System.out);

        // Original code hardcoded t = 1. Preserved for exact behavior match.
        int t = 1;
        while (t-- > 0) {
            char[][] grid = readGrid(scanner);
            boolean found = hasPattern(grid);
            out.println(found ? "YES" : "NO");
        }

        out.flush();
        out.close();
    }

    /**
     * Reads the 4x4 character grid from input.
     */
    private static char[][] readGrid(FastScanner scanner) {
        char[][] grid = new char[GRID_SIZE][GRID_SIZE];
        for (int i = 0; i < GRID_SIZE; i++) {
            String line = scanner.next();
            if (line != null) {
                grid[i] = line.toCharArray();
            }
        }
        return grid;
    }

    /**
     * Checks if the grid contains the specified alternating or consecutive patterns
     * in any of the 4 cardinal/diagonal directions.
     */
    private static boolean hasPattern(char[][] grid) {
        for (int i = 0; i < GRID_SIZE; i++) {
            for (int j = 0; j < GRID_SIZE; j++) {
                for (int d = 0; d < 4; d++) {
                    int ni1 = i + DR[d];
                    int nj1 = j + DC[d];
                    int ni2 = i + 2 * DR[d];
                    int nj2 = j + 2 * DC[d];

                    // Ensure the 3rd cell in the sequence is within bounds
                    if (ni2 >= 0 && ni2 < GRID_SIZE && nj2 >= 0 && nj2 < GRID_SIZE) {
                        char c0 = grid[i][j];
                        char c1 = grid[ni1][nj1];
                        char c2 = grid[ni2][nj2];

                        if (c0 == 'x') {
                            // Pattern: x-x. or x-.-x
                            if ((c1 == 'x' && c2 == '.') || (c1 == '.' && c2 == 'x')) {
                                return true;
                            }
                        } else if (c0 == '.') {
                            // Pattern: .-x-x
                            if (c1 == 'x' && c2 == 'x') {
                                return true;
                            }
                        }
                    }
                }
            }
        }
        return false;
    }

    /**
     * Lightweight fast I/O helper class using BufferedReader and StringTokenizer.
     */
    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        public String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input", e);
                }
            }
            return st.nextToken();
        }
    }
}

import java.io.BufferedReader;
import java.io.FileInputStream;
import java.io.FileNotFoundException;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

public class Main {
    // Extracted constants to avoid magic numbers and improve configurability
    private static final int GRID_SIZE = 4;
    private static final char EMPTY_CELL = '.';
    private static final char FILLED_CELL = 'x';
    private static final int MIN_PATH_LENGTH = 3; // Original condition: count + 1 > 2  => count >= 3

    public static void main(String[] args) {
        InputStream inputStream = System.in;

        // Handle devTesting mode safely
        if (args.length > 0 && "devTesting".equals(args[0])) {
            if (args.length < 2) {
                System.err.println("Error: File path required for devTesting mode.");
                return;
            }
            try {
                inputStream = new FileInputStream(args[1]);
            } catch (FileNotFoundException e) {
                System.err.println("Error: Input file not found: " + args[1]);
                return;
            }
        }

        PrintWriter out = new PrintWriter(System.out);
        try {
            FastScanner in = new FastScanner(inputStream);
            char[][] grid = readGrid(in);

            GridSolver solver = new GridSolver();
            solver.solve(grid, out);
        } catch (Exception e) {
            System.err.println("Error processing input: " + e.getMessage());
        } finally {
            out.flush();
            out.close();
            if (inputStream != System.in) {
                try { inputStream.close(); } catch (IOException ignored) {}
            }
        }
    }

    private static char[][] readGrid(FastScanner in) {
        char[][] grid = new char[GRID_SIZE][GRID_SIZE];
        for (int i = 0; i < GRID_SIZE; i++) {
            String line = in.next();
            if (line == null || line.length() < GRID_SIZE) {
                throw new IllegalArgumentException("Invalid grid input at row " + i);
            }
            grid[i] = line.toCharArray();
        }
        return grid;
    }

    // Encapsulated solver logic to avoid class-level mutable state
    static class GridSolver {
        void solve(char[][] grid, PrintWriter out) {
            for (int i = 0; i < GRID_SIZE; i++) {
                for (int j = 0; j < GRID_SIZE; j++) {
                    if (grid[i][j] == EMPTY_CELL) {
                        // Temporarily place the cell to test connectivity
                        grid[i][j] = FILLED_CELL;
                        boolean possible = false;

                        // Check all 4 directional axes
                        for (int dir = 0; dir < 4; dir++) {
                            boolean[][] visited = new boolean[GRID_SIZE][GRID_SIZE];
                            if (countConnectedInDirection(grid, visited, i, j, dir) >= MIN_PATH_LENGTH) {
                                possible = true;
                                break;
                            }
                        }

                        // Backtrack to restore original state
                        grid[i][j] = EMPTY_CELL;

                        if (possible) {
                            out.println("YES");
                            return;
                        }
                    }
                }
            }
            out.println("NO");
        }

        private int countConnectedInDirection(char[][] grid, boolean[][] visited, int r, int c, int dirIndex) {
            visited[r][c] = true;
            int count = 1;

            // Direction vectors: 0=Vertical, 1=Main Diagonal, 2=Horizontal, 3=Anti-Diagonal
            int[] dr = {1, 1, 0, -1};
            int[] dc = {0, 1, 1, 1};

            // Traverse in both directions along the axis (-1 and +1)
            for (int sign = -1; sign <= 1; sign += 2) {
                int nr = r + dr[dirIndex] * sign;
                int nc = c + dc[dirIndex] * sign;

                if (isValid(nr, nc) && !visited[nr][nc] && grid[nr][nc] == FILLED_CELL) {
                    count += countConnectedInDirection(grid, visited, nr, nc, dirIndex);
                }
            }
            return count;
        }

        private boolean isValid(int r, int c) {
            return r >= 0 && r < GRID_SIZE && c >= 0 && c < GRID_SIZE;
        }
    }

    // Simplified and robust input reader
    static class FastScanner {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        FastScanner(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
            tokenizer = null;
        }

        String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input", e);
                }
            }
            return tokenizer.nextToken();
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

/**
 * Checks if a 4x4 game board contains any specific 3-cell patterns.
 * Patterns checked: "xx.", ".xx", or "x.x" in horizontal, vertical, or diagonal lines.
 */
public class Main {

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner();
        char[][] board = readBoard(scanner);

        boolean hasPattern = checkForPatterns(board);
        System.out.println(hasPattern ? "YES" : "NO");
    }

    /**
     * Reads the 4x4 board from standard input.
     */
    private static char[][] readBoard(FastScanner scanner) {
        char[][] board = new char[4][4];
        for (int i = 0; i < 4; i++) {
            board[i] = scanner.next().toCharArray();
        }
        return board;
    }

    /**
     * Checks if the board contains any of the target patterns in any direction.
     * Uses direction vectors to generalize the search across rows, columns, and diagonals.
     */
    private static boolean checkForPatterns(char[][] board) {
        // Directions: right, down, down-right, down-left
        int[][] directions = {
            {0, 1},
            {1, 0},
            {1, 1},
            {1, -1}
        };

        for (int[] dir : directions) {
            int dr = dir[0];
            int dc = dir[1];

            for (int r = 0; r < 4; r++) {
                for (int c = 0; c < 4; c++) {
                    // Calculate the end position of the 3-cell sequence
                    int endR = r + 2 * dr;
                    int endC = c + 2 * dc;

                    // Verify bounds before accessing array
                    if (endR >= 0 && endR < 4 && endC >= 0 && endC < 4) {
                        char first = board[r][c];
                        char second = board[r + dr][c + dc];
                        char third = board[endR][endC];

                        if (matchesTargetPattern(first, second, third)) {
                            return true;
                        }
                    }
                }
            }
        }
        return false;
    }

    /**
     * Checks if three characters match any of the target patterns:
     * "xx.", ".xx", or "x.x"
     */
    private static boolean matchesTargetPattern(char a, char b, char c) {
        return (a == 'x' && b == 'x' && c == '.') ||
               (a == '.' && b == 'x' && c == 'x') ||
               (a == 'x' && b == '.' && c == 'x');
    }

    /**
     * Fast I/O utility for competitive programming and performance-critical input.
     */
    public static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner() {
            this(new InputStreamReader(System.in));
        }

        public FastScanner(java.io.Reader in) {
            br = new BufferedReader(in);
        }

        public String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) {
                        throw new IOException("End of input stream");
                    }
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input", e);
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }

        public double nextDouble() {
            return Double.parseDouble(next());
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;

/**
 * A solution class that determines if placing an 'x' in any empty spot on a 4x4 board
 * results in three consecutive 'x's (horizontally, vertically, or diagonally).
 */
public class Solution {

    // Constants for better maintainability and configuration
    private static final int BOARD_SIZE = 4;
    private static final int WIN_LENGTH = 3;
    private static final char MARK = 'x';
    private static final char EMPTY = '.';

    /**
     * Represents the game board state.
     */
    public static class Board {
        private char[][] grid;

        public Board() {
            grid = new char[BOARD_SIZE][BOARD_SIZE];
        }

        /**
         * Loads a row of data into the board.
         * @param rowIndex The index of the row to update.
         * @param rowData The string containing the row data.
         */
        public void loadRow(int rowIndex, String rowData) {
            if (rowData.length() != BOARD_SIZE) {
                throw new IllegalArgumentException("Row data length mismatch");
            }
            grid[rowIndex] = rowData.toCharArray();
        }

        /**
         * Checks if there are 3 consecutive marks on the board.
         * @return true if a winning line exists, false otherwise.
         */
        public boolean hasThreeInRow() {
            // Check Horizontal lines
            for (int r = 0; r < BOARD_SIZE; r++) {
                for (int c = 0; c <= BOARD_SIZE - WIN_LENGTH; c++) {
                    if (checkLine(r, c, 0, 1)) return true;
                }
            }

            // Check Vertical lines
            for (int r = 0; r <= BOARD_SIZE - WIN_LENGTH; r++) {
                for (int c = 0; c < BOARD_SIZE; c++) {
                    if (checkLine(r, c, 1, 0)) return true;
                }
            }

            // Check Diagonal (Down-Right) lines
            for (int r = 0; r <= BOARD_SIZE - WIN_LENGTH; r++) {
                for (int c = 0; c <= BOARD_SIZE - WIN_LENGTH; c++) {
                    if (checkLine(r, c, 1, 1)) return true;
                }
            }

            // Check Diagonal (Down-Left) lines
            for (int r = 0; r <= BOARD_SIZE - WIN_LENGTH; r++) {
                for (int c = WIN_LENGTH - 1; c < BOARD_SIZE; c++) {
                    if (checkLine(r, c, 1, -1)) return true;
                }
            }

            return false;
        }

        /**
         * Helper method to check a specific line of WIN_LENGTH starting at (r, c)
         * in the direction defined by (dr, dc).
         */
        private boolean checkLine(int r, int c, int dr, int dc) {
            for (int i = 0; i < WIN_LENGTH; i++) {
                if (grid[r + i * dr][c + i * dc] != MARK) {
                    return false;
                }
            }
            return true;
        }

        /**
         * Places a mark at specific coordinates.
         */
        public void placeMark(int r, int c) {
            grid[r][c] = MARK;
        }

        /**
         * Removes a mark (resets to empty) at specific coordinates.
         */
        public void removeMark(int r, int c) {
            grid[r][c] = EMPTY;
        }

        /**
         * Checks if a cell is currently empty.
         */
        public boolean isEmpty(int r, int c) {
            return grid[r][c] == EMPTY;
        }
    }

    public static void main(String[] args) throws IOException {
        // Use try-with-resources to ensure the BufferedReader is closed properly
        try (BufferedReader in = new BufferedReader(new InputStreamReader(System.in))) {
            Board board = new Board();

            // Read board state from input
            for (int i = 0; i < BOARD_SIZE; i++) {
                String line = in.readLine();
                if (line != null) {
                    board.loadRow(i, line);
                }
            }

            boolean found = false;

            // Iterate through all cells to find an empty spot
            for (int r = 0; r < BOARD_SIZE; r++) {
                for (int c = 0; c < BOARD_SIZE; c++) {
                    if (board.isEmpty(r, c)) {
                        // Simulate placing 'x'
                        board.placeMark(r, c);

                        // Check if this move creates a winning line
                        if (board.hasThreeInRow()) {
                            found = true;
                            board.removeMark(r, c); // Undo move
                            break;
                        }

                        // Undo move (backtracking)
                        board.removeMark(r, c);
                    }
                }
                if (found) break;
            }

            if (found) {
                System.out.println("YES");
            } else {
                System.out.println("NO");
            }
        }
    }
}

import java.util.Scanner;

public class Main {
    private static final int BOARD_SIZE = 4;

    // Direction vectors for the 8 possible moves (horizontal, vertical, diagonal)
    private static final int[] DX = {0, 0, 1, -1, 1, -1, 1, -1};
    private static final int[] DY = {1, -1, 0, 0, 1, 1, -1, -1};

    public static void main(String[] args) {
        // Use try-with-resources to ensure the scanner is properly closed
        try (Scanner scanner = new Scanner(System.in)) {
            char[][] board = new char[BOARD_SIZE][BOARD_SIZE];

            // Read the 4x4 grid
            for (int i = 0; i < BOARD_SIZE; i++) {
                board[i] = scanner.next().toCharArray();
            }

            boolean isValidMove = false;

            // Check each cell to see if it's a valid target position
            for (int i = 0; i < BOARD_SIZE; i++) {
                for (int j = 0; j < BOARD_SIZE; j++) {
                    if (board[i][j] == '.' && isFlankedByX(board, i, j)) {
                        isValidMove = true;
                        break; // Early exit: condition already satisfied
                    }
                }
                if (isValidMove) break; // Early exit from outer loop
            }

            System.out.println(isValidMove ? "YES" : "NO");
        }
    }

    /**
     * Checks if the cell at (row, col) is flanked by 'x' characters 
     * at distance 1 and 2 in any of the 8 directions.
     */
    private static boolean isFlankedByX(char[][] board, int row, int col) {
        for (int k = 0; k < DX.length; k++) {
            int r1 = row + DX[k];
            int c1 = col + DY[k];
            int r2 = row + 2 * DX[k];
            int c2 = col + 2 * DY[k];

            // Simplified boolean logic (originally used double negatives)
            if (isValid(board, r1, c1) && isValid(board, r2, c2) &&
                board[r1][c1] == 'x' && board[r2][c2] == 'x') {
                return true;
            }
        }
        return false;
    }

    /**
     * Validates that the given coordinates are within the board boundaries.
     */
    private static boolean isValid(char[][] board, int r, int c) {
        return r >= 0 && r < BOARD_SIZE && c >= 0 && c < BOARD_SIZE;
    }
}

import java.util.Scanner;
import java.io.PrintWriter;

public class B390 {
    private static final int GRID_SIZE = 4;
    private static final String[] TARGET_PATTERNS = {".xx", "xx.", "x.x"};

    public static void main(String[] args) {
        // Use try-with-resources to guarantee proper closure of I/O streams
        try (Scanner in = new Scanner(System.in);
             PrintWriter out = new PrintWriter(System.out)) {
            B390 solver = new B390();
            solver.run(in, out);
        }
    }

    private void run(Scanner in, PrintWriter out) {
        String[] grid = readGrid(in);
        boolean found = checkRows(grid) || checkColumns(grid) || checkDiagonals(grid);
        out.println(found ? "YES" : "NO");
    }

    private String[] readGrid(Scanner in) {
        String[] grid = new String[GRID_SIZE];
        for (int i = 0; i < GRID_SIZE; i++) {
            grid[i] = in.next();
        }
        return grid;
    }

    private boolean checkRows(String[] grid) {
        for (String row : grid) {
            if (containsPattern(row)) {
                return true;
            }
        }
        return false;
    }

    private boolean checkColumns(String[] grid) {
        for (int col = 0; col < GRID_SIZE; col++) {
            StringBuilder colStr = new StringBuilder();
            for (int row = 0; row < GRID_SIZE; row++) {
                colStr.append(grid[row].charAt(col));
            }
            if (containsPattern(colStr.toString())) {
                return true;
            }
        }
        return false;
    }

    private boolean checkDiagonals(String[] grid) {
        // Collect all diagonals of length >= 3 in a 4x4 grid
        String[] diagonals = {
            getDiagonal(grid, 0, 0, 1, 1),   // Main diagonal
            getDiagonal(grid, 0, 3, 1, -1),  // Anti-diagonal
            getDiagonal(grid, 1, 0, 1, 1),   // Parallel to main (bottom-left)
            getDiagonal(grid, 0, 1, 1, 1),   // Parallel to main (top-right)
            getDiagonal(grid, 1, 3, 1, -1),  // Parallel to anti (top-right)
            getDiagonal(grid, 0, 2, 1, -1)   // Parallel to anti (bottom-left)
        };

        for (String diag : diagonals) {
            if (containsPattern(diag)) {
                return true;
            }
        }
        return false;
    }

    private String getDiagonal(String[] grid, int startRow, int startCol, int deltaRow, int deltaCol) {
        StringBuilder sb = new StringBuilder();
        for (int r = startRow, c = startCol; r >= 0 && r < GRID_SIZE && c >= 0 && c < GRID_SIZE; r += deltaRow, c += deltaCol) {
            sb.append(grid[r].charAt(c));
        }
        return sb.toString();
    }

    private boolean containsPattern(String s) {
        for (String pattern : TARGET_PATTERNS) {
            if (s.contains(pattern)) {
                return true;
            }
        }
        return false;
    }
}

import java.util.Scanner;

public class PatternChecker {
    private static final int BOARD_SIZE = 4;
    private static final int LINE_LENGTH = 3;
    private static final int X_VALUE = 1;
    private static final int EMPTY_VALUE = 0;

    // Directions to check: Right, Down, Down-Right, Down-Left
    // Iterating over all cells with these forward directions covers every unique 3-cell line exactly once.
    private static final int[][] DIRECTIONS = {
        {0, 1}, {1, 0}, {1, 1}, {1, -1}
    };

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            int[][] board = readBoard(scanner);
            if (hasTargetPattern(board)) {
                System.out.println("YES");
            } else {
                System.out.println("NO");
            }
        }
    }

    /**
     * Reads the board configuration from standard input and converts it to a 2D integer array.
     */
    private static int[][] readBoard(Scanner scanner) {
        int[][] board = new int[BOARD_SIZE][BOARD_SIZE];
        for (int i = 0; i < BOARD_SIZE; i++) {
            if (!scanner.hasNext()) {
                throw new IllegalArgumentException("Insufficient input provided.");
            }
            String row = scanner.next();
            if (row.length() < BOARD_SIZE) {
                throw new IllegalArgumentException("Row " + i + " must be at least " + BOARD_SIZE + " characters long.");
            }
            for (int j = 0; j < BOARD_SIZE; j++) {
                char cell = row.charAt(j);
                switch (cell) {
                    case 'x':
                        board[i][j] = X_VALUE;
                        break;
                    case 'o':
                        board[i][j] = -1;
                        break;
                    case '.':
                        board[i][j] = EMPTY_VALUE;
                        break;
                    default:
                        board[i][j] = 0; // Fallback for unexpected characters
                }
            }
        }
        return board;
    }

    /**
     * Checks if the board contains any 3-cell line (horizontal, vertical, or diagonal)
     * with exactly two 'x' (1) and exactly one '.' (0).
     */
    private static boolean hasTargetPattern(int[][] board) {
        for (int r = 0; r < BOARD_SIZE; r++) {
            for (int c = 0; c < BOARD_SIZE; c++) {
                for (int[] dir : DIRECTIONS) {
                    int dr = dir[0];
                    int dc = dir[1];

                    // Calculate the end position of the 3-cell line
                    int endRow = r + (LINE_LENGTH - 1) * dr;
                    int endCol = c + (LINE_LENGTH - 1) * dc;

                    // Verify the entire line fits within board boundaries
                    if (endRow >= 0 && endRow < BOARD_SIZE && endCol >= 0 && endCol < BOARD_SIZE) {
                        int xCount = 0;
                        int emptyCount = 0;

                        for (int k = 0; k < LINE_LENGTH; k++) {
                            int value = board[r + k * dr][c + k * dc];
                            if (value == X_VALUE) {
                                xCount++;
                            } else if (value == EMPTY_VALUE) {
                                emptyCount++;
                            }
                        }

                        if (xCount == 2 && emptyCount == 1) {
                            return true;
                        }
                    }
                }
            }
        }
        return false;
    }
}

