/**
 * Analyzes a 4x4 grid to determine if placing a piece in any empty cell
 * results in a winning configuration according to the specified rules.
 */
public class GridWinChecker {

    private static final int GRID_SIZE = 4;
    private static final int WIN_LENGTH = 3;
    private static final char EMPTY_CELL = '.';
    private static final char PLAYER_CELL = 'x';

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            System.out.println(solve(scanner));
        }
    }

    /**
     * Reads the grid, attempts to fill each empty cell, and checks for a win.
     */
    private static String solve(Scanner scanner) {
        char[][] board = new char[GRID_SIZE][GRID_SIZE];
        for (int row = 0; row < GRID_SIZE; row++) {
            String line = scanner.next();
            validateInput(line, row);
            board[row] = line.toCharArray();
        }

        for (int row = 0; row < GRID_SIZE; row++) {
            for (int col = 0; col < GRID_SIZE; col++) {
                if (board[row][col] == EMPTY_CELL) {
                    board[row][col] = PLAYER_CELL;
                    if (hasWinningLine(board)) {
                        return "YES";
                    }
                    board[row][col] = EMPTY_CELL; // Backtrack to original state
                }
            }
        }
        return "NO";
    }

    private static void validateInput(String line, int row) {
        if (line.length() != GRID_SIZE) {
            throw new IllegalArgumentException(
                "Invalid input at row " + row + ": expected " + GRID_SIZE + " characters, got " + line.length());
        }
    }

    private static boolean hasWinningLine(char[][] board) {
        // Check rows
        for (int row = 0; row < GRID_SIZE; row++) {
            if (hasConsecutiveCells(board[row], PLAYER_CELL, WIN_LENGTH)) {
                return true;
            }
        }

        // Check columns
        for (int col = 0; col < GRID_SIZE; col++) {
            char[] column = new char[GRID_SIZE];
            for (int row = 0; row < GRID_SIZE; row++) {
                column[row] = board[row][col];
            }
            if (hasConsecutiveCells(column, PLAYER_CELL, WIN_LENGTH)) {
                return true;
            }
        }

        // Check diagonals (logic preserved exactly from original implementation)
        return checkDiagonals(board);
    }

    private static boolean hasConsecutiveCells(char[] line, char target, int length) {
        int count = 0;
        for (char cell : line) {
            if (cell == target) {
                count++;
                if (count == length) {
                    return true;
                }
            } else {
                count = 0;
            }
        }
        return false;
    }

    private static boolean checkDiagonals(char[][] board) {
        // Preserved original diagonal checks for behavioral equivalence.
        // Note: Some index combinations in the original code appear non-contiguous;
        // they are kept as-is to maintain exact original behavior.
        if (board[0][0] == PLAYER_CELL && board[1][1] == PLAYER_CELL && board[2][2] == PLAYER_CELL) return true;
        if (board[1][0] == PLAYER_CELL && board[2][1] == PLAYER_CELL && board[3][2] == PLAYER_CELL) return true;
        if (board[0][1] == PLAYER_CELL && board[1][2] == PLAYER_CELL && board[2][3] == PLAYER_CELL) return true;
        if (board[3][3] == PLAYER_CELL && board[1][1] == PLAYER_CELL && board[2][2] == PLAYER_CELL) return true;
        if (board[0][3] == PLAYER_CELL && board[1][2] == PLAYER_CELL && board[2][1] == PLAYER_CELL) return true;
        if (board[0][2] == PLAYER_CELL && board[1][1] == PLAYER_CELL && board[2][0] == PLAYER_CELL) return true;
        if (board[1][3] == PLAYER_CELL && board[2][2] == PLAYER_CELL && board[3][1] == PLAYER_CELL) return true;
        if (board[3][0] == PLAYER_CELL && board[1][2] == PLAYER_CELL && board[2][1] == PLAYER_CELL) return true;
        return false;
    }
}

import java.util.Scanner;

public class Main {
    // Constants for grid dimensions
    private static final int GRID_SIZE = 4;

    // Constants for cell values to replace magic numbers
    private static final int CELL_X = 1;
    private static final int CELL_EMPTY = 2;
    private static final int CELL_O = 0;

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int[][] grid = new int[GRID_SIZE][GRID_SIZE];

        // 1. Read and parse the grid
        if (readGrid(scanner, grid)) {
            // 2. Analyze the grid for the specific pattern
            if (checkPatternExists(grid)) {
                System.out.println("YES");
            } else {
                System.out.println("NO");
            }
        }

        scanner.close();
    }

    /**
     * Reads the input grid from the scanner.
     * @param scanner The input scanner.
     * @param grid The 2D array to populate.
     * @return true if input was read successfully, false otherwise.
     */
    private static boolean readGrid(Scanner scanner, int[][] grid) {
        for (int i = 0; i < GRID_SIZE; i++) {
            if (scanner.hasNextLine()) {
                String line = scanner.nextLine();
                // Safety check for line length to prevent StringIndexOutOfBoundsException
                int length = Math.min(line.length(), GRID_SIZE);
                for (int j = 0; j < length; j++) {
                    char ch = line.charAt(j);
                    if (ch == 'x') {
                        grid[i][j] = CELL_X;
                    } else if (ch == 'o') {
                        grid[i][j] = CELL_O;
                    } else if (ch == '.') {
                        grid[i][j] = CELL_EMPTY;
                    }
                    // Characters other than x, o, . are left as 0 (default int value)
                }
            }
        }
        return true;
    }

    /**
     * Checks if the specific neighbor pattern exists in the grid.
     * @param grid The 4x4 grid.
     * @return true if pattern found, false otherwise.
     */
    private static boolean checkPatternExists(int[][] grid) {
        // 1. Vertical Checks (Rows 1 to 2, all columns)
        for (int col = 0; col < GRID_SIZE; col++) {
            for (int row = 1; row <= 2; row++) {
                if (checkNeighbors(grid, row, col, -1, 0, 1, 0)) return true;
            }
        }

        // 2. Horizontal Checks (All rows, Cols 1 to 2)
        for (int row = 0; row < GRID_SIZE; row++) {
            for (int col = 1; col <= 2; col++) {
                if (checkNeighbors(grid, row, col, 0, -1, 0, 1)) return true;
            }
        }

        // 3. Diagonal Checks (Top-Left to Bottom-Right)
        // Center must be in rows 1-2, cols 1-2
        for (int row = 1; row <= 2; row++) {
            for (int col = 1; col <= 2; col++) {
                if (checkNeighbors(grid, row, col, -1, -1, 1, 1)) return true;
            }
        }

        // 4. Diagonal Checks (Top-Right to Bottom-Left)
        // Center must be in rows 1-2, cols 1-2
        for (int row = 1; row <= 2; row++) {
            for (int col = 1; col <= 2; col++) {
                if (checkNeighbors(grid, row, col, -1, 1, 1, -1)) return true;
            }
        }

        return false;
    }

    /**
     * Core logic to check if neighbors satisfy the condition relative to the center cell.
     * 
     * Condition derived from original code:
     * If center is X (1): Neighbors must be (X, Empty) or (Empty, X).
     * If center is Empty (2): Neighbors must be (X, X).
     * 
     * @param grid The grid.
     * @param r Row index of the center cell.
     * @param c Column index of the center cell.
     * @param dr1 Delta row for first neighbor.
     * @param dc1 Delta column for first neighbor.
     * @param dr2 Delta row for second neighbor.
     * @param dc2 Delta column for second neighbor.
     * @return true if the pattern matches, false otherwise.
     */
    private static boolean checkNeighbors(int[][] grid, int r, int c, int dr1, int dc1, int dr2, int dc2) {
        int centerVal = grid[r][c];
        int val1 = grid[r + dr1][c + dc1];
        int val2 = grid[r + dr2][c + dc2];

        if (centerVal == CELL_X) {
            // Center is X (1). Neighbors must be mixed (1 and 2).
            return (val1 == CELL_X && val2 == CELL_EMPTY) || (val1 == CELL_EMPTY && val2 == CELL_X);
        } else if (centerVal == CELL_EMPTY) {
            // Center is Empty (2). Neighbors must be both X (1).
            return val1 == CELL_X && val2 == CELL_X;
        }

        // If center is O (0) or default 0, condition is not met based on original logic
        return false;
    }
}

