import java.util.StringTokenizer;

public class CF754B {

    // Constants for grid dimensions
    private static final int GRID_SIZE = 4;

    // Direction vectors: Right, Down, Diagonal (Down-Right), Diagonal (Down-Left)
    // We only check these directions because the nested loops iterate over every cell (r, c),
    // effectively treating every cell as a potential starting point for a line of length 3.
    // Checking Left or Up would be redundant.
    private static final int[][] DIRECTIONS = {
        {0, 1},  // Right
        {1, 0},  // Down
        {1, 1},  // Diagonal Down-Right
        {1, -1}  // Diagonal Down-Left
    };

    public static void main(String[] args) throws IOException {
        // Fast I/O setup
        InputReader in = new InputReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        // Use a local variable for the grid instead of a static field to improve encapsulation
        char[][] grid = new char[GRID_SIZE][];

        // Read the 4x4 grid from input
        for (int i = 0; i < GRID_SIZE; i++) {
            String line = in.next();
            if (line != null) {
                grid[i] = line.toCharArray();
            }
        }

        boolean found = false;

        // Iterate through every cell to act as the starting point of a pattern
        for (int r = 0; r < GRID_SIZE; r++) {
            // Safety check: ensure row exists and has enough columns
            if (grid[r] == null || grid[r].length < GRID_SIZE) continue;

            for (int c = 0; c < GRID_SIZE; c++) {
                // Check if a valid pattern starts at (r, c)
                if (hasValidPattern(grid, r, c)) {
                    found = true;
                    break;
                }
            }
            if (found) break;
        }

        out.println(found ? "YES" : "NO");
        out.flush();
    }

    /**
     * Checks if a valid pattern of length 3 starts at (r, c) in any of the 4 directions.
     */
    private static boolean hasValidPattern(char[][] grid, int r, int c) {
        for (int[] dir : DIRECTIONS) {
            if (isValidLine(grid, r, c, dir[0], dir[1])) {
                return true;
            }
        }
        return false;
    }

    /**
     * Checks if a line of 3 characters starting at (r, c) with direction (dr, dc) is valid.
     * Valid pattern: 3 'x's OR 2 'x's and 1 '.'.
     * 
     * Refactored from original logic:
     * - Removed global mutable state ('count').
     * - Removed hardcoded direction checks in favor of a loop over directions.
     * - Used local variables for better scope and thread safety (though not strictly needed here).
     */
    private static boolean isValidLine(char[][] grid, int r, int c, int dr, int dc) {
        int dotCount = 0;

        // Check 3 cells in the specified direction
        for (int k = 0; k < 3; k++) {
            int nr = r + k * dr;
            int nc = c + k * dc;

            // Boundary check
            if (nr < 0 || nr >= GRID_SIZE || nc < 0 || nc >= GRID_SIZE) {
                return false;
            }

            // Safety check for jagged arrays (in case input string was short)
            if (nc >= grid[nr].length) {
                return false;
            }

            char cell = grid[nr][nc];

            if (cell == '.') {
                dotCount++;
                // Original logic: allows at most one '.' per sequence
                if (dotCount > 1) {
                    return false;
                }
            } else if (cell != 'x') {
                // Original logic: only 'x' and '.' are valid characters
                return false;
            }
        }

        return true;
    }

    /**
     * Helper class for fast input reading (standard in competitive programming).
     */
    static class InputReader {
        public BufferedReader reader;
        public StringTokenizer tokenizer;

        public InputReader(java.io.InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
            tokenizer = null;
        }

        public String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

/**
 * Solves a 4x4 grid problem: determines if placing a single 'x' in any empty cell
 * results in a winning line of 3 consecutive 'x's.
 */
public class Main {
    // Configuration constants to eliminate magic numbers
    private static final int GRID_SIZE = 4;
    private static final int WIN_LENGTH = 3;
    private static final char EMPTY_CELL = '.';
    private static final char PLAYER_CELL = 'x';

    public static void main(String[] args) throws IOException {
        // try-with-resources ensures the reader is properly closed
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(System.in))) {
            new Main().solve(reader);
        }
    }

    /**
     * Orchestrates the solving process: reads input, attempts moves, and prints result.
     */
    public void solve(BufferedReader reader) throws IOException {
        char[][] grid = readGrid(reader, GRID_SIZE, GRID_SIZE);
        if (canPlaceWinningMove(grid)) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }
    }

    /**
     * Attempts to place the player's cell in every empty position.
     * Returns true if any placement results in a winning configuration.
     */
    private boolean canPlaceWinningMove(char[][] grid) {
        for (int r = 0; r < GRID_SIZE; r++) {
            for (int c = 0; c < GRID_SIZE; c++) {
                if (grid[r][c] == EMPTY_CELL) {
                    grid[r][c] = PLAYER_CELL;
                    if (hasWinningLine(grid)) {
                        grid[r][c] = EMPTY_CELL; // Backtrack before returning
                        return true;
                    }
                    grid[r][c] = EMPTY_CELL; // Backtrack
                }
            }
        }
        return false;
    }

    /**
     * Checks if the current grid configuration contains a winning line.
     */
    private boolean hasWinningLine(char[][] grid) {
        // Directions: right, down, down-right, down-left
        // These 4 vectors uniquely cover all possible lines in a grid
        int[][] directions = {{0, 1}, {1, 0}, {1, 1}, {1, -1}};

        for (int r = 0; r < GRID_SIZE; r++) {
            for (int c = 0; c < GRID_SIZE; c++) {
                if (grid[r][c] != PLAYER_CELL) continue;
                for (int[] dir : directions) {
                    if (checkDirection(grid, r, c, dir[0], dir[1])) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Verifies if a line of WIN_LENGTH consecutive cells exists starting from (startR, startC)
     * in the given direction (dr, dc).
     */
    private boolean checkDirection(char[][] grid, int startR, int startC, int dr, int dc) {
        for (int i = 1; i < WIN_LENGTH; i++) {
            int r = startR + i * dr;
            int c = startC + i * dc;
            if (isOutOfBounds(r, c) || grid[r][c] != PLAYER_CELL) {
                return false;
            }
        }
        return true;
    }

    /**
     * Checks if the given coordinates are within the grid boundaries.
     */
    private boolean isOutOfBounds(int r, int c) {
        return r < 0 || r >= GRID_SIZE || c < 0 || c >= GRID_SIZE;
    }

    /**
     * Reads a 2D character grid from the input reader.
     */
    private char[][] readGrid(BufferedReader reader, int rows, int cols) throws IOException {
        char[][] grid = new char[rows][cols];
        StringTokenizer st = new StringTokenizer("");
        for (int i = 0; i < rows; i++) {
            while (!st.hasMoreTokens()) {
                String line = reader.readLine();
                if (line == null) {
                    throw new IOException("Unexpected end of input while reading grid");
                }
                st = new StringTokenizer(line);
            }
            String rowStr = st.nextToken();
            if (rowStr.length() != cols) {
                throw new IllegalArgumentException("Invalid row length at row " + i +
                        ". Expected " + cols + " but got " + rowStr.length());
            }
            grid[i] = rowStr.toCharArray();
        }
        return grid;
    }
}

import java.util.Scanner;

public class Solution {
    private static final int BOARD_SIZE = 4;
    private static final char EMPTY_CELL = '.';
    private static final char TARGET_MARK = 'x';

    /**
     * Safely checks if a cell is within bounds and contains the target mark.
     */
    private static boolean isTargetMark(char[][] board, int row, int col) {
        return row >= 0 && row < BOARD_SIZE && col >= 0 && col < BOARD_SIZE
                && board[row][col] == TARGET_MARK;
    }

    /**
     * Determines if placing a mark at (row, col) would complete a line of 3 marks.
     * Checks horizontal, vertical, and both diagonal directions.
     */
    private static boolean canCompleteLine(char[][] board, int row, int col) {
        // Directions represented as [rowDelta, colDelta]
        // Horizontal, Vertical, Diagonal (top-left to bottom-right), Diagonal (top-right to bottom-left)
        int[][] directions = {
            {0, 1},
            {1, 0},
            {1, 1},
            {1, -1}
        };

        for (int[] dir : directions) {
            int dr = dir[0];
            int dc = dir[1];

            // A 3-in-a-row through the center point (row, col) can be formed in three ways:
            // 1. Two marks in the positive direction
            if (isTargetMark(board, row + dr, col + dc) &&
                isTargetMark(board, row + 2 * dr, col + 2 * dc)) {
                return true;
            }
            // 2. One mark on each side of the center point
            if (isTargetMark(board, row + dr, col + dc) &&
                isTargetMark(board, row - dr, col - dc)) {
                return true;
            }
            // 3. Two marks in the negative direction
            if (isTargetMark(board, row - dr, col - dc) &&
                isTargetMark(board, row - 2 * dr, col - 2 * dc)) {
                return true;
            }
        }
        return false;
    }

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            char[][] board = new char[BOARD_SIZE][BOARD_SIZE];

            // Read the 4x4 board
            for (int i = 0; i < BOARD_SIZE; i++) {
                String line = scanner.nextLine().trim();
                for (int j = 0; j < BOARD_SIZE; j++) {
                    board[i][j] = line.charAt(j);
                }
            }

            // Check each empty cell to see if it completes a line
            for (int i = 0; i < BOARD_SIZE; i++) {
                for (int j = 0; j < BOARD_SIZE; j++) {
                    if (board[i][j] == EMPTY_CELL && canCompleteLine(board, i, j)) {
                        System.out.println("YES");
                        return;
                    }
                }
            }

            System.out.println("NO");
        }
    }
}

