     * in any of the 8 possible directions.
     */
    private static boolean hasThreeInLine(char[][] grid) {
        for (int[] dir : DIRECTIONS) {
            for (int r = 0; r < GRID_SIZE; r++) {
                for (int c = 0; c < GRID_SIZE; c++) {
                    if (isLineOfThree(grid, r, c, dir[0], dir[1])) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Checks if a line of 3 'x's starts at (r, c) in the given direction.
     */
    private static boolean isLineOfThree(char[][] grid, int r, int c, int dr, int dc) {
        return inBounds(r, c) &&
               inBounds(r + dr, c + dc) &&
               inBounds(r + 2 * dr, c + 2 * dc) &&
               grid[r][c] == 'x' &&
               grid[r + dr][c + dc] == 'x' &&
               grid[r + 2 * dr][c + 2 * dc] == 'x';
    }

    /**
     * Checks if the given coordinates are within the grid boundaries.
     */
    private static boolean inBounds(int r, int c) {
        return r >= 0 && r < GRID_SIZE && c >= 0 && c < GRID_SIZE;
    }

    /**
     * Fast input reader optimized for competitive programming.
     */
    static class FastScanner {
        private BufferedReader br;
        private StringTokenizer st;

        public FastScanner(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
            st = new StringTokenizer("");
        }

        public String next() throws IOException {
            while (!st.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) return null;
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        public long nextLong() throws IOException {
            return Long.parseLong(next());
        }
    }
}

