     */
    private static char[][] readGrid(BufferedReader br) throws IOException {
        char[][] grid = new char[GRID_SIZE][GRID_SIZE];
        for (int i = 0; i < GRID_SIZE; i++) {
            String line = br.readLine();
            if (line == null) break;
            for (int j = 0; j < GRID_SIZE && j < line.length(); j++) {
                grid[i][j] = line.charAt(j);
            }
        }
        return grid;
    }

    /**
     * Checks if the grid contains any 3-cell sequence (horizontal, vertical, 
     * or diagonal) matching the patterns: XX., X.X, or .XX
     */
    private static boolean hasWinningPattern(char[][] grid) {
        // Directions: horizontal, vertical, main diagonal, anti-diagonal
        int[][] directions = {{0, 1}, {1, 0}, {1, 1}, {1, -1}};

        for (int[] dir : directions) {
            int dr = dir[0];
            int dc = dir[1];

            for (int r = 0; r < GRID_SIZE; r++) {
                for (int c = 0; c < GRID_SIZE; c++) {
                    // Ensure the 3-cell segment stays within grid bounds
                    if (r + 2 * dr >= 0 && r + 2 * dr < GRID_SIZE &&
                        c + 2 * dc >= 0 && c + 2 * dc < GRID_SIZE) {

                        char c1 = grid[r][c];
                        char c2 = grid[r + dr][c + dc];
                        char c3 = grid[r + 2 * dr][c + 2 * dc];

                        // Check for valid patterns: XX., X.X, .XX
                        if ((c1 == 'x' && c2 == 'x' && c3 == '.') ||
                            (c1 == 'x' && c2 == '.' && c3 == 'x') ||
                            (c1 == '.' && c2 == 'x' && c3 == 'x')) {
                            return true;
                        }
                    }
                }
            }
        }
        return false;
    }
}

import java.util.Scanner;

public class ProblemB {
    // Constants to replace magic numbers and improve maintainability
    private static final int BOARD_SIZE = 4;
    private static final int WIN_LENGTH = 3;

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        char[][] board = new char[BOARD_SIZE][BOARD_SIZE];

        // Read input board
        for (int i = 0; i < BOARD_SIZE; i++) {
            if (scanner.hasNext()) {
                String row = scanner.next();
                board[i] = row.toCharArray();
            }
        }

        boolean canWin = false;

        // Iterate through every cell to find an empty spot ('.')
        for (int r = 0; r < BOARD_SIZE; r++) {
            for (int c = 0; c < BOARD_SIZE; c++) {
                if (board[r][c] == '.') {
                    // Check if placing 'x' at this position results in a win
                    if (canPlaceWinningMove(board, r, c)) {
                        canWin = true;
                        break; // Optimization: Found a winning move, exit loops
                    }
                }
            }
            if (canWin) break;
        }

        System.out.println(canWin ? "YES" : "NO");
        scanner.close();
    }

    /**
     * Checks if placing an 'x' at the specified coordinates (r, c)
     * creates a line of length WIN_LENGTH in any direction.
     */
    private static boolean canPlaceWinningMove(char[][] board, int r, int c) {
        // Directions to check: Horizontal, Vertical, Diagonal 1, Diagonal 2
        // Format: {rowDelta, colDelta}
        int[][] directions = {
            {0, 1},   // Horizontal (Right)
            {1, 0},   // Vertical (Down)
            {1, 1},   // Diagonal (Down-Right)
            {1, -1}   // Diagonal (Down-Left)
        };

        for (int[] dir : directions) {
            if (checkLine(board, r, c, dir[0], dir[1])) {
                return true;
            }
        }
        return false;
    }

    /**
     * Checks if a continuous line of 'x's exists in a specific direction
     * passing through the starting point (r, c).
     * This method assumes the piece at (r, c) is 'x'.
     */
    private static boolean checkLine(char[][] board, int r, int c, int dr, int dc) {
        int count = 1; // Start with 1 for the current cell (r, c)

        // Check in the positive direction (forward)
        int nr = r + dr;
        int nc = c + dc;
        while (isValid(nr, nc) && board[nr][nc] == 'x') {
            count++;
            nr += dr;
            nc += dc;
        }

        // Check in the negative direction (backward)
        nr = r - dr;
        nc = c - dc;
        while (isValid(nr, nc) && board[nr][nc] == 'x') {
            count++;
            nr -= dr;
            nc -= dc;
        }

        return count >= WIN_LENGTH;
    }

    /**
     * Checks if the coordinates are within the board boundaries.
     */
    private static boolean isValid(int r, int c) {
        return r >= 0 && r < BOARD_SIZE && c >= 0 && c < BOARD_SIZE;
    }
}

import java.util.Scanner;

/**
 * Analyzes a 4x4 character grid to detect specific patterns.
 * Prints "YES" if any row, column, or diagonal contains at least two 'x' characters
 * within a 3-character window, otherwise prints "NO".
 */
public class PatternChecker {
    private static final int GRID_SIZE = 4;
    private static final String[] TARGET_PATTERNS = {"xx.", ".xx", "x.x"};

    public static void main(String[] args) {
        char[][] grid = readGrid();
        boolean patternFound = checkGrid(grid);
        System.out.println(patternFound ? "YES" : "NO");
    }

    /**
     * Reads the 4x4 grid from standard input.
     */
    private static char[][] readGrid() {
        try (Scanner scanner = new Scanner(System.in)) {
            char[][] grid = new char[GRID_SIZE][GRID_SIZE];
            for (int i = 0; i < GRID_SIZE; i++) {
                String line = scanner.next();
                for (int j = 0; j < GRID_SIZE; j++) {
                    grid[i][j] = line.charAt(j);
                }
            }
            return grid;
        }
    }

    /**
     * Checks all rows, columns, and diagonals for the target patterns.
     */
    private static boolean checkGrid(char[][] grid) {
        // Check rows
        for (int i = 0; i < GRID_SIZE; i++) {
            if (hasTargetPattern(buildLine(grid, i, 0, 0, 1))) {
                return true;
            }
        }
        // Check columns
        for (int j = 0; j < GRID_SIZE; j++) {
            if (hasTargetPattern(buildLine(grid, 0, j, 1, 0))) {
                return true;
            }
        }
        // Check main and anti-diagonals (length 4)
        if (hasTargetPattern(buildLine(grid, 0, 0, 1, 1))) return true;
        if (hasTargetPattern(buildLine(grid, 0, GRID_SIZE - 1, 1, -1))) return true;

        // Check sub-diagonals (length 3)
        if (hasTargetPattern(buildLine(grid, 1, 0, 1, 1))) return true;
        if (hasTargetPattern(buildLine(grid, 0, 1, 1, 1))) return true;
        if (hasTargetPattern(buildLine(grid, 0, GRID_SIZE - 2, 1, -1))) return true;
        if (hasTargetPattern(buildLine(grid, 1, GRID_SIZE - 1, 1, -1))) return true;

        return false;
    }

    /**
     * Constructs a string from the grid along a specified direction.
     */
    private static String buildLine(char[][] grid, int startRow, int startCol, int dRow, int dCol) {
        StringBuilder sb = new StringBuilder();
        int r = startRow, c = startCol;
        while (r >= 0 && r < GRID_SIZE && c >= 0 && c < GRID_SIZE) {
            sb.append(grid[r][c]);
            r += dRow;
            c += dCol;
        }
        return sb.toString();
    }

    /**
     * Checks if the given string contains any of the target patterns.
     */
    private static boolean hasTargetPattern(String line) {
        for (String pattern : TARGET_PATTERNS) {
            if (line.contains(pattern)) {
                return true;
            }
        }
        return false;
    }
}

import java.io.*;
import java.util.StringTokenizer;

public class Main {
    private static final int GRID_SIZE = 4;
    // Directions to check: top-left, top, top-right, left
    // Checking both positive and negative steps covers all 4 lines through a cell
    private static final int[][] DIRECTIONS = {
        {-1, -1}, {-1, 0}, {-1, 1}, {0, -1}
    };

    public static void main(String[] args) throws IOException {
        // Use try-with-resources for automatic resource management
        try (FastScanner scanner = new FastScanner(System.in);
             PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out))) {

            char[][] board = new char[GRID_SIZE][GRID_SIZE];
            for (int i = 0; i < GRID_SIZE; i++) {
                String line = scanner.next();
                if (line != null) {
                    board[i] = line.toCharArray();
                }
            }

            boolean found = false;
            for (int i = 0; i < GRID_SIZE; i++) {
                for (int j = 0; j < GRID_SIZE; j++) {
                    if (board[i][j] == '.') {
                        board[i][j] = 'x'; // Place candidate
                        if (hasThreeConsecutive(board, i, j)) {
                            found = true;
                            board[i][j] = '.'; // Backtrack for consistency
                            break;
                        }
                        board[i][j] = '.'; // Backtrack
                    }
                }
                if (found) break;
            }

            out.println(found ? "YES" : "NO");
        }
    }

    /**
     * Checks if placing an 'x' at (r, c) creates a sequence of 3 or more consecutive 'x's
     * in any of the 4 primary directions.
     */
    private static boolean hasThreeConsecutive(char[][] board, int r, int c) {
        for (int[] dir : DIRECTIONS) {
            int count = 1; // Start with the 'x' just placed at (r, c)

            // Check forward direction
            for (int step = 1; step <= 2; step++) {
                int nr = r + dir[0] * step;
                int nc = c + dir[1] * step;
                if (isValid(nr, nc) && board[nr][nc] == 'x') {
                    count++;
                } else {
                    break; // Sequence broken by boundary or non-'x'
                }
            }

            // Check backward direction
            for (int step = 1; step <= 2; step++) {
                int nr = r - dir[0] * step;
                int nc = c - dir[1] * step;
                if (isValid(nr, nc) && board[nr][nc] == 'x') {
                    count++;
                } else {
                    break; // Sequence broken by boundary or non-'x'
                }
            }

            if (count >= 3) {
                return true;
            }
        }
        return false;
    }

    private static boolean isValid(int r, int c) {
        return r >= 0 && r < GRID_SIZE && c >= 0 && c < GRID_SIZE;
    }

    /**
     * Fast I/O helper class for competitive programming style inputs.
     */
    static class FastScanner {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastScanner(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
            tokenizer = new StringTokenizer("");
        }

        public String next() throws IOException {
            while (!tokenizer.hasMoreTokens()) {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        public long nextLong() throws IOException {
            return Long.parseLong(next());
        }

        public double nextDouble() throws IOException {
            return Double.parseDouble(next());
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;

public class GridWinChecker {
    private static final int GRID_SIZE = 4;
    private static final int WIN_LENGTH = 3;
    private static final char EMPTY = '.';
    private static final char PLAYER = 'x';

    public static void main(String[] args) throws IOException {
        // Use try-with-resources to ensure streams are properly closed
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
             PrintWriter out = new PrintWriter(System.out)) {

            char[][] grid = readGrid(br);

            boolean canWin = false;
            outerLoop:
            for (int i = 0; i < GRID_SIZE; i++) {
                for (int j = 0; j < GRID_SIZE; j++) {
                    if (grid[i][j] == EMPTY) {
                        grid[i][j] = PLAYER; // Temporarily place 'x'
                        if (hasThreeInARow(grid)) {
                            canWin = true;
                        }
                        grid[i][j] = EMPTY; // Backtrack to restore original state
                        if (canWin) break outerLoop;
                    }
                }
            }

            out.println(canWin ? "YES" : "NO");
            out.flush();
        }
    }

    /**
     * Reads the 4x4 grid from standard input.
     */
    private static char[][] readGrid(BufferedReader br) throws IOException {
        char[][] grid = new char[GRID_SIZE][GRID_SIZE];
        for (int i = 0; i < GRID_SIZE; i++) {
            String line = br.readLine();
            if (line != null) {
                for (int j = 0; j < GRID_SIZE && j < line.length(); j++) {
                    grid[i][j] = line.charAt(j);
                }
            }
        }
        return grid;
    }

    /**
     * Checks if there are exactly WIN_LENGTH consecutive PLAYER characters
     * in any direction (horizontal, vertical, or diagonal).
     */
    private static boolean hasThreeInARow(char[][] grid) {
        int[][] directions = {
            {0, 1},   // Horizontal
            {1, 0},   // Vertical
            {1, 1},   // Diagonal down-right
            {1, -1}   // Diagonal down-left
        };

        for (int r = 0; r < GRID_SIZE; r++) {
            for (int c = 0; c < GRID_SIZE; c++) {
                if (grid[r][c] == PLAYER) {
                    for (int[] dir : directions) {
                        int rEnd = r + (WIN_LENGTH - 1) * dir[0];
                        int cEnd = c + (WIN_LENGTH - 1) * dir[1];

                        // Ensure the third cell stays within grid bounds
                        if (rEnd >= 0 && rEnd < GRID_SIZE && cEnd >= 0 && cEnd < GRID_SIZE) {
                            if (grid[r + dir[0]][c + dir[1]] == PLAYER &&
                                grid[rEnd][cEnd] == PLAYER) {
                                return true;
                            }
                        }
                    }
                }
            }
        }
        return false;
    }
}

import java.util.Scanner;

/**
 * Solves problem R754B: Determines if it's possible to form a line of three 'x's
 * in a 4x4 grid by changing at most one '.' to 'x'.
 * 
 * Refactoring improvements:
 * - Removed unrelated utility methods that cluttered the class
 * - Replaced magic numbers with named constants
 * - Separated I/O, grid parsing, and game logic into distinct methods
 * - Replaced complex, hard-to-read recursion with a clear iterative window check
 * - Used try-with-resources for proper Scanner lifecycle management
 * - Improved variable naming and added JavaDoc for clarity
 */
public class R754B {
    private static final int GRID_SIZE = 4;

    // Check only 4 directions to avoid duplicate checks: right, down, down-right, down-left
    private static final int[] DX = {0, 1, 1, 1};
    private static final int[] DY = {1, 0, 1, -1};

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            char[][] grid = readGrid(scanner);
            boolean canWin = canFormLineOfThree(grid);
            System.out.println(canWin ? "YES" : "NO");
        }
    }

    private static char[][] readGrid(Scanner scanner) {
        char[][] grid = new char[GRID_SIZE][GRID_SIZE];
        for (int i = 0; i < GRID_SIZE; i++) {
            grid[i] = scanner.nextLine().toCharArray();
        }
        return grid;
    }

    private static boolean canFormLineOfThree(char[][] grid) {
        for (int i = 0; i < GRID_SIZE; i++) {
            for (int j = 0; j < GRID_SIZE; j++) {
                // Only need to check directions starting from 'x' or '.' cells
                if (grid[i][j] == 'x' || grid[i][j] == '.') {
                    for (int d = 0; d < DX.length; d++) {
                        if (checkDirection(grid, i, j, DX[d], DY[d])) {
                            return true;
                        }
                    }
                }
            }
        }
        return false;
    }

    /**
     * Checks a line of 3 cells starting from (startRow, startCol) in the given direction.
     * Returns true if the line already contains 3 'x's, or 2 'x's and 1 '.' (which can be replaced).
     */
    private static boolean checkDirection(char[][] grid, int startRow, int startCol, int dr, int dc) {
        int xCount = 0;
        int dotCount = 0;

        for (int k = 0; k < 3; k++) {
            int row = startRow + k * dr;
            int col = startCol + k * dc;

            // Boundary check
            if (row < 0 || row >= GRID_SIZE || col < 0 || col >= GRID_SIZE) {
                return false;
            }

            char cell = grid[row][col];
            if (cell == 'x') {
                xCount++;
            } else if (cell == '.') {
                dotCount++;
            } else {
                // Encountered an invalid character, line is broken
                return false;
            }
        }

        // Valid if we already have 3 'x's, or 2 'x's and 1 '.' (can replace '.')
        return xCount == 3 || (xCount == 2 && dotCount == 1);
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;

public class GridPatternChecker {
    // Configuration constants to eliminate magic numbers
    private static final int GRID_SIZE = 4;
    private static final int CHECK_LENGTH = 3; // Total cells to evaluate in each direction
    private static final int REQUIRED_X_COUNT = 1; // Additional 'x' needed (start cell is already 'x')
    private static final int REQUIRED_DOT_COUNT = 1;

    public static void main(String[] args) {
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(System.in))) {
            char[][] grid = new char[GRID_SIZE][GRID_SIZE];

            // Read and validate input
            for (int i = 0; i < GRID_SIZE; i++) {
                String line = reader.readLine();
                if (line == null || line.length() < GRID_SIZE) {
                    throw new IllegalArgumentException("Invalid input at line " + (i + 1));
                }
                // Fixed original bug: split("") creates an empty string at index 0.
                // toCharArray() directly maps characters to array indices.
                grid[i] = line.substring(0, GRID_SIZE).toCharArray();
            }

            if (hasPattern(grid)) {
                System.out.println("YES");
            } else {
                System.out.println("NO");
            }
        } catch (IOException e) {
            System.err.println("Failed to read input: " + e.getMessage());
            System.exit(1);
        }
    }

    /**
     * Scans the grid for any 'x' that forms the target pattern in any of the 8 directions.
     */
    private static boolean hasPattern(char[][] grid) {
        // Deltas for 8 directions: N, NE, E, SE, S, SW, W, NW
        int[] rowDeltas = {-1, -1, 0, 0, 1, 1, 0, -1};
        int[] colDeltas = {0, 1, 1, -1, 0, -1, 1, -1};

        for (int r = 0; r < GRID_SIZE; r++) {
            for (int c = 0; c < GRID_SIZE; c++) {
                if (grid[r][c] == 'x') {
                    for (int d = 0; d < 8; d++) {
                        if (checkDirection(grid, r, c, rowDeltas[d], colDeltas[d])) {
                            return true; // Early exit on first match
                        }
                    }
                }
            }
        }
        return false;
    }

    /**
     * Checks if a specific direction from the start cell contains exactly
     * REQUIRED_X_COUNT additional 'x's and REQUIRED_DOT_COUNT '.'s.
     */
    private static boolean checkDirection(char[][] grid, int startRow, int startCol, 
                                          int rowDelta, int colDelta) {
        int xCount = 0;
        int dotCount = 0;

        // Check the next (CHECK_LENGTH - 1) cells in the given direction
        for (int step = 1; step < CHECK_LENGTH; step++) {
            int r = startRow + rowDelta * step;
            int c = startCol + colDelta * step;

            // Boundary check replaces the original complex conditional logic
            if (r < 0 || r >= GRID_SIZE || c < 0 || c >= GRID_SIZE) {
                return false;
            }

            char cell = grid[r][c];
            if (cell == 'x') {
                xCount++;
            } else if (cell == '.') {
                dotCount++;
            }
            // Other characters are ignored but will prevent the exact count match
        }

        return xCount == REQUIRED_X_COUNT && dotCount == REQUIRED_DOT_COUNT;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.OutputStream;
import java.io.PrintWriter;
import java.util.StringTokenizer;

/**
 * Main class for the Grid Solver problem.
 * Refactored for better maintainability, readability, and code quality.
 */
public class Main {
    // Constants to replace magic numbers
    private static final int GRID_SIZE = 4;
    private static final char EMPTY_CELL = '.';
    private static final char FILLED_CELL = 'x';

    public static void main(String[] args) {
        // Initialize I/O streams
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;

        FastScanner in = new FastScanner(inputStream);
        PrintWriter out = new PrintWriter(outputStream);

        // Instantiate and run the solver
        GridSolver solver = new GridSolver();
        solver.solve(in, out);

        // Ensure output is flushed and closed
        out.close();
    }

    /**
     * Contains the logic for solving the grid problem.
     */
    static class GridSolver {

        /**
         * Checks if there is a line of 3 'x's in the grid.
         * Optimized to check only necessary directions from each cell.
         *
         * @param grid The 2D character array representing the grid.
         * @return true if a line of 3 'x's exists, false otherwise.
         */
        public boolean checkWin(char[][] grid) {
            for (int r = 0; r < GRID_SIZE; r++) {
                for (int c = 0; c < GRID_SIZE; c++) {
                    // Optimization: Only check lines starting with an 'x'
                    if (grid[r][c] != FILLED_CELL) {
                        continue;
                    }

                    // Check Horizontal (Right)
                    if (c + 2 < GRID_SIZE) {
                        if (grid[r][c + 1] == FILLED_CELL && grid[r][c + 2] == FILLED_CELL) {
                            return true;
                        }
                    }

                    // Check Vertical (Down)
                    if (r + 2 < GRID_SIZE) {
                        if (grid[r + 1][c] == FILLED_CELL && grid[r + 2][c] == FILLED_CELL) {
                            return true;
                        }
                    }

                    // Check Diagonal (Down-Right)
                    if (r + 2 < GRID_SIZE && c + 2 < GRID_SIZE) {
                        if (grid[r + 1][c + 1] == FILLED_CELL && grid[r + 2][c + 2] == FILLED_CELL) {
                            return true;
                        }
                    }

                    // Check Diagonal (Down-Left)
                    if (r + 2 < GRID_SIZE && c - 2 >= 0) {
                        if (grid[r + 1][c - 1] == FILLED_CELL && grid[r + 2][c - 2] == FILLED_CELL) {
                            return true;
                        }
                    }
                }
            }
            return false;
        }

        public void solve(FastScanner in, PrintWriter out) {
            char[][] grid = new char[GRID_SIZE][GRID_SIZE];

            // Read the grid from input
            for (int i = 0; i < GRID_SIZE; i++) {
                String row = in.next();
                if (row != null) {
                    grid[i] = row.toCharArray();
                }
            }

            // Iterate through every cell to find a winning move
            for (int r = 0; r < GRID_SIZE; r++) {
                for (int c = 0; c < GRID_SIZE; c++) {
                    if (grid[r][c] == EMPTY_CELL) {
                        // Hypothesis: Place 'x' in the empty spot
                        grid[r][c] = FILLED_CELL;

                        if (checkWin(grid)) {
                            out.println("YES");
                            return; // Found a winning move, exit early
                        }

                        // Backtrack: Revert the change to try the next spot
                        grid[r][c] = EMPTY_CELL;
                    }
                }
            }

            // If no winning move is found after checking all possibilities
            out.println("NO");
        }
    }

    /**
     * Fast I/O helper class for competitive programming.
     */
    static class FastScanner {
        BufferedReader reader;
        StringTokenizer tokenizer;

        public FastScanner(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) {
                        return null;
                    }
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }
    }
}

import java.io.BufferedReader;
import java.io.File;
import java.io.FileNotFoundException;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.OutputStream;
import java.io.PrintWriter;
import java.util.StringTokenizer;

public class Main {
    private static final int BOARD_SIZE = 4;
    private static final int SEQUENCE_LENGTH = 3;
    private static final char X = 'x';
    private static final char DOT = '.';

    public static void main(String[] args) {
        FastScanner in = new FastScanner(System.in);
        FastPrinter out = new FastPrinter(System.out);
        solve(in, out);
        out.close();
    }

    private static void solve(FastScanner in, FastPrinter out) {
        char[][] board = new char[BOARD_SIZE][BOARD_SIZE];
        for (int i = 0; i < BOARD_SIZE; i++) {
            String row = in.next();
            board[i] = row.toCharArray();
        }

        if (hasPattern(board)) {
            out.println("YES");
        } else {
            out.println("NO");
        }
    }

    private static boolean hasPattern(char[][] board) {
        // Direction vectors: right, up, down-right, up-right, down-left
        int[] dr = {0, -1, 1, -1, 1};
        int[] dc = {1, 0, 1, 1, -1};

        for (int r = 0; r < BOARD_SIZE; r++) {
            for (int c = 0; c < BOARD_SIZE; c++) {
                for (int d = 0; d < dr.length; d++) {
                    int xCount = 0;
                    int dotCount = 0;
                    boolean inBounds = true;

                    for (int k = 0; k < SEQUENCE_LENGTH; k++) {
                        int nr = r + dr[d] * k;
                        int nc = c + dc[d] * k;

                        if (nr < 0 || nr >= BOARD_SIZE || nc < 0 || nc >= BOARD_SIZE) {
                            inBounds = false;
                            break;
                        }

                        char cell = board[nr][nc];
                        if (cell == X) {
                            xCount++;
                        } else if (cell == DOT) {
                            dotCount++;
                        }
                    }

                    if (inBounds && check(xCount, dotCount)) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    private static boolean check(int x, int dot) {
        return (x == 2 && dot == 1) || (x == 3 && dot == 0);
    }

    /**
     * Fast I/O Scanner for competitive programming.
     */
    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner(InputStream is) {
            br = new BufferedReader(new InputStreamReader(is));
        }

        public FastScanner(File f) {
            try {
                br = new BufferedReader(new FileReader(f));
            } catch (FileNotFoundException e) {
                throw new RuntimeException("File not found: " + f.getAbsolutePath(), e);
            }
        }

        public String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return st.nextToken();
        }
    }

    /**
     * Fast I/O Printer wrapping PrintWriter.
     */
    static class FastPrinter extends PrintWriter {
        public FastPrinter(OutputStream out) {
            super(out);
        }

        public FastPrinter(java.io.Writer out) {
            super(out);
        }
    }
}

import java.io.*;
import java.util.StringTokenizer;

public class Main {
    // Constants to improve maintainability and readability
    private static final int BOARD_SIZE = 4;
    private static final char MARKER = 'x';
    private static final char EMPTY = '.';

    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;

        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);

        Solver solver = new Solver();
        solver.solve(in, out);

        out.flush();
        out.close();
    }

    static class Solver {
        public void solve(InputReader in, PrintWriter out) {
            char[][] board = new char[BOARD_SIZE][BOARD_SIZE];

            // Read the board configuration
            for (int i = 0; i < BOARD_SIZE; ++i) {
                String row = in.next();
                if (row != null) {
                    board[i] = row.toCharArray();
                }
            }

            // Iterate through the board to find empty spots
            // We try placing a marker in each empty spot to see if it creates a winning line
            for (int r = 0; r < BOARD_SIZE; ++r) {
                for (int c = 0; c < BOARD_SIZE; ++c) {
                    if (board[r][c] == EMPTY) {
                        // Temporarily place the marker
                        board[r][c] = MARKER;

                        // Check if this move results in a winning line
                        if (hasWinningLine(board)) {
                            out.println("YES");
                            return;
                        }

                        // Backtrack: remove the marker to restore board state
                        board[r][c] = EMPTY;
                    }
                }
            }

            // If no winning move was found after checking all possibilities
            out.println("NO");
        }

        /**
         * Checks if there is any line of three consecutive markers on the board.
         * Checks rows, columns, and both diagonal directions.
         */
        private boolean hasWinningLine(char[][] board) {
            // Check Horizontal Lines
            for (int r = 0; r < BOARD_SIZE; ++r) {
                for (int c = 0; c <= BOARD_SIZE - 3; ++c) {
                    if (checkLine(board, r, c, 0, 1)) return true;
                }
            }

            // Check Vertical Lines
            for (int c = 0; c < BOARD_SIZE; ++c) {
                for (int r = 0; r <= BOARD_SIZE - 3; ++r) {
                    if (checkLine(board, r, c, 1, 0)) return true;
                }
            }

            // Check Diagonal Lines (Top-Left to Bottom-Right)
            for (int r = 0; r <= BOARD_SIZE - 3; ++r) {
                for (int c = 0; c <= BOARD_SIZE - 3; ++c) {
                    if (checkLine(board, r, c, 1, 1)) return true;
                }
            }

            // Check Diagonal Lines (Top-Right to Bottom-Left)
            for (int r = 0; r <= BOARD_SIZE - 3; ++r) {
                for (int c = 2; c < BOARD_SIZE; ++c) {
                    if (checkLine(board, r, c, 1, -1)) return true;
                }
            }

            return false;
        }

        /**
         * Checks if a line of 3 markers exists starting at (r, c) in a specific direction.
         * dr, dc are the deltas for row and column respectively.
         * This avoids string manipulation and is more efficient.
         */
        private boolean checkLine(char[][] board, int r, int c, int dr, int dc) {
            return board[r][c] == MARKER &&
                   board[r + dr][c + dc] == MARKER &&
                   board[r + 2 * dr][c + 2 * dc] == MARKER;
        }
    }

    static class InputReader {
        public BufferedReader reader;
        public StringTokenizer tokenizer;

        public InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            String s = next();
            if (s == null) throw new RuntimeException("End of stream");
            return Integer.parseInt(s);
        }

        public long nextLong() {
            String s = next();
            if (s == null) throw new RuntimeException("End of stream");
            return Long.parseLong(s);
        }

        public double nextDouble() {
            String s = next();
            if (s == null) throw new RuntimeException("End of stream");
            return Double.parseDouble(s);
        }
    }
}

import java.util.Scanner;

public class WinningMoveChecker {
    // Constants replace magic numbers for easier configuration and self-documentation
    private static final int BOARD_SIZE = 4;
    private static final int WIN_LENGTH = 3;

    public static void main(String[] args) {
        // try-with-resources ensures the Scanner is closed automatically, preventing resource leaks
        try (Scanner sc = new Scanner(System.in)) {
            char[][] board = readBoard(sc);
            boolean hasWinningMove = findWinningMove(board);
            System.out.println(hasWinningMove ? "YES" : "NO");
        }
    }

    /**
     * Reads the 4x4 character matrix from standard input.
     */
    private static char[][] readBoard(Scanner sc) {
        char[][] board = new char[BOARD_SIZE][BOARD_SIZE];
        for (int i = 0; i < BOARD_SIZE; i++) {
            String line = sc.next();
            for (int j = 0; j < BOARD_SIZE; j++) {
                board[i][j] = line.charAt(j);
            }
        }
        return board;
    }

    /**
     * Iterates through all empty cells, temporarily places an 'x', 
     * and checks if it results in a winning condition.
     */
    private static boolean findWinningMove(char[][] board) {
        for (int i = 0; i < BOARD_SIZE; i++) {
            for (int j = 0; j < BOARD_SIZE; j++) {
                if (board[i][j] == '.') {
                    board[i][j] = 'x';
                    if (checkWin(board)) {
                        board[i][j] = '.'; // Restore board state before returning
                        return true;
                    }
                    board[i][j] = '.';
                }
            }
        }
        return false;
    }

    /**
     * Checks if the current board configuration contains a winning line of 3 consecutive 'x's.
     */
    private static boolean checkWin(char[][] board) {
        // Check all rows
        for (int i = 0; i < BOARD_SIZE; i++) {
            if (checkLine(board, i, 0, 0, 1)) {
                return true;
            }
        }
        // Check all columns
        for (int i = 0; i < BOARD_SIZE; i++) {
            if (checkLine(board, 0, i, 1, 0)) {
                return true;
            }
        }
        // Check all diagonals (both main and anti-diagonal directions)
        for (int i = 0; i <= BOARD_SIZE - WIN_LENGTH; i++) {
            if (checkLine(board, i, i, 1, 1)) {
                return true;
            }
            if (checkLine(board, i, BOARD_SIZE - 1 - i, 1, -1)) {
                return true;
            }
        }
        return false;
    }

    /**
     * Checks a specific line segment of length WIN_LENGTH starting at (startRow, startCol)
     * in the given direction (rowDir, colDir) for consecutive 'x's.
     */
    private static boolean checkLine(char[][] board, int startRow, int startCol, int rowDir, int colDir) {
        int consecutiveCount = 0;
        for (int k = 0; k < WIN_LENGTH; k++) {
            int row = startRow + k * rowDir;
            int col = startCol + k * colDir;
            if (board[row][col] == 'x') {
                consecutiveCount++;
                if (consecutiveCount == WIN_LENGTH) {
                    return true;
                }
            } else {
                consecutiveCount = 0;
            }
        }
        return false;
    }
}

