/**
 * Analyzes a 4x4 grid to determine if any 3 consecutive cells
 * in a row, column, or diagonal contain exactly two 'x's and one '.'.
 * This pattern indicates a valid move to complete a line.
 */
class GridPatternSolver {
    private static final int GRID_SIZE = 4;

    // Directions to check: horizontal, vertical, diagonal down-right, diagonal down-left
    private static final int[][] DIRECTIONS = {
        {0, 1}, {1, 0}, {1, 1}, {1, -1}
    };

    /**
     * Reads the grid from the provided reader and checks for the target pattern.
     */
    public void solve(BufferedReader br, PrintWriter pw) throws IOException {
        char[][] grid = new char[GRID_SIZE][GRID_SIZE];
        for (int i = 0; i < GRID_SIZE; i++) {
            String line = br.readLine();
            if (line == null) {
                throw new IOException("Unexpected end of input while reading grid row " + i);
            }
            grid[i] = line.trim().toCharArray();
        }

        boolean canPlace = hasValidPattern(grid);
        pw.println(canPlace ? "YES" : "NO");
    }

    /**
     * Iterates through all possible 3-cell sequences in all 4 directions.
     * Returns true if any sequence matches the target pattern.
     */
    private boolean hasValidPattern(char[][] grid) {
        for (int[] dir : DIRECTIONS) {
            int dr = dir[0];
            int dc = dir[1];

            for (int r = 0; r < GRID_SIZE; r++) {
                for (int c = 0; c < GRID_SIZE; c++) {
                    int r2 = r + 2 * dr;
                    int c2 = c + 2 * dc;

                    // Verify the third cell is within grid bounds
                    if (r2 >= 0 && r2 < GRID_SIZE && c2 >= 0 && c2 < GRID_SIZE) {
                        if (matchesTargetPattern(grid, r, c, r + dr, c + dc, r2, c2)) {
                            return true;
                        }
                    }
                }
            }
        }
        return false;
    }

    /**
     * Checks if the three specified cells contain exactly two 'x's and one '.'.
     * This covers all valid permutations: "xx.", "x.x", and ".xx".
     */
    private boolean matchesTargetPattern(char[][] grid, int r1, int c1, int r2, int c2, int r3, int c3) {
        char c1Char = grid[r1][c1];
        char c2Char = grid[r2][c2];
        char c3Char = grid[r3][c3];

        int xCount = (c1Char == 'x' ? 1 : 0) + (c2Char == 'x' ? 1 : 0) + (c3Char == 'x' ? 1 : 0);
        int dotCount = (c1Char == '.' ? 1 : 0) + (c2Char == '.' ? 1 : 0) + (c3Char == '.' ? 1 : 0);

        return xCount == 2 && dotCount == 1;
    }
}

import java.io.*;
import java.util.*;

public class Main {
    // Configuration constants to eliminate magic numbers
    private static final int BOARD_SIZE = 4;
    private static final int WIN_LENGTH = 3;
    private static final int X_VALUE = 1;
    private static final int EMPTY_VALUE = 0;
    private static final int INVALID_VALUE = -10;
    // Note: Original logic checks for sum == 2. Preserved here for exact behavioral match.
    private static final int WIN_SUM = 2;

    public static void main(String[] args) {
        InputReader in = new InputReader(System.in);
        PrintWriter out = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)));
        solve(in, out);
        out.flush();
        out.close();
    }

    private static void solve(InputReader in, PrintWriter out) {
        int testCases = 1;
        StringBuilder result = new StringBuilder();

        while (testCases-- > 0) {
            int[][] board = readBoard(in);
            boolean hasWinner = checkWinningCondition(board);
            result.append(hasWinner ? "YES" : "NO");
        }

        out.println(result.toString());
    }

    private static int[][] readBoard(InputReader in) {
        int[][] board = new int[BOARD_SIZE][BOARD_SIZE];
        for (int i = 0; i < BOARD_SIZE; i++) {
            String line = in.nextLine();
            for (int j = 0; j < BOARD_SIZE; j++) {
                char ch = line.charAt(j);
                if (ch == 'x') {
                    board[i][j] = X_VALUE;
                } else if (ch == '.') {
                    board[i][j] = EMPTY_VALUE;
                } else {
                    board[i][j] = INVALID_VALUE;
                }
            }
        }
        return board;
    }

    private static boolean checkWinningCondition(int[][] board) {
        // Check rows
        for (int i = 0; i < BOARD_SIZE; i++) {
            for (int j = 0; j <= BOARD_SIZE - WIN_LENGTH; j++) {
                if (board[i][j] + board[i][j + 1] + board[i][j + 2] == WIN_SUM) {
                    return true;
                }
            }
        }

        // Check columns
        for (int j = 0; j < BOARD_SIZE; j++) {
            for (int i = 0; i <= BOARD_SIZE - WIN_LENGTH; i++) {
                if (board[i][j] + board[i + 1][j] + board[i + 2][j] == WIN_SUM) {
                    return true;
                }
            }
        }

        // Check diagonals (top-left to bottom-right)
        for (int i = 0; i <= BOARD_SIZE - WIN_LENGTH; i++) {
            for (int j = 0; j <= BOARD_SIZE - WIN_LENGTH; j++) {
                if (board[i][j] + board[i + 1][j + 1] + board[i + 2][j + 2] == WIN_SUM) {
                    return true;
                }
            }
        }

        // Check diagonals (top-right to bottom-left)
        for (int i = 0; i <= BOARD_SIZE - WIN_LENGTH; i++) {
            for (int j = WIN_LENGTH - 1; j < BOARD_SIZE; j++) {
                if (board[i][j] + board[i + 1][j - 1] + board[i + 2][j - 2] == WIN_SUM) {
                    return true;
                }
            }
        }

        return false;
    }

    // Fast I/O template (preserved from original for performance)
    static class InputReader {
        private final InputStream stream;
        private final byte[] buf = new byte[8192];
        private int curChar, snumChars;
        private SpaceCharFilter filter;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        public int snext() {
            if (snumChars == -1) {
                throw new InputMismatchException();
            }
            if (curChar >= snumChars) {
                curChar = 0;
                try {
                    snumChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (snumChars <= 0) {
                    return -1;
                }
            }
            return buf[curChar++];
        }

        public int nextInt() {
            int c = snext();
            while (isSpaceChar(c)) {
                c = snext();
            }
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = snext();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                res *= 10;
                res += c - '0';
                c = snext();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public long nextLong() {
            int c = snext();
            while (isSpaceChar(c)) {
                c = snext();
            }
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = snext();
            }
            long res = 0;
            do {
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                res *= 10;
                res += c - '0';
                c = snext();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public int[] nextIntArray(int n) {
            int[] a = new int[n];
            for (int i = 0; i < n; i++) {
                a[i] = nextInt();
            }
            return a;
        }

        public String readString() {
            int c = snext();
            while (isSpaceChar(c)) {
                c = snext();
            }
            StringBuilder res = new StringBuilder();
            do {
                res.appendCodePoint(c);
                c = snext();
            } while (!isSpaceChar(c));
            return res.toString();
        }

        public String nextLine() {
            int c = snext();
            while (isSpaceChar(c)) {
                c = snext();
            }
            StringBuilder res = new StringBuilder();
            do {
                res.appendCodePoint(c);
                c = snext();
            } while (!isEndOfLine(c));
            return res.toString();
        }

        public boolean isSpaceChar(int c) {
            return filter != null ? filter.isSpaceChar(c) : (c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1);
        }

        private boolean isEndOfLine(int c) {
            return c == '\n' || c == '\r' || c == -1;
        }

        public interface SpaceCharFilter {
            boolean isSpaceChar(int ch);
        }
    }
}

import java.util.Scanner;

public class TicTacToeSolver {
    // Configuration constants to eliminate magic numbers and improve configurability
    private static final int BOARD_SIZE = 4;
    private static final int WIN_LENGTH = 3;

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        char[][] board = new char[BOARD_SIZE][BOARD_SIZE];
        int countX = 0;
        int countO = 0;

        // 1. Read the board and count existing moves
        for (int i = 0; i < BOARD_SIZE; i++) {
            String row = scanner.next();
            for (int j = 0; j < BOARD_SIZE; j++) {
                board[i][j] = row.charAt(j);
                if (board[i][j] == 'x') {
                    countX++;
                } else if (board[i][j] == 'o') {
                    countO++;
                }
            }
        }

        // 2. Determine whose turn it is based on standard game rules
        char currentPlayer = (countX == countO) ? 'x' : 'o';
        boolean canWinInOneMove = false;

        // 3. Simulate placing the current player's piece in every empty cell
        for (int i = 0; i < BOARD_SIZE; i++) {
            for (int j = 0; j < BOARD_SIZE; j++) {
                if (board[i][j] == '.') {
                    board[i][j] = currentPlayer;
                    if (hasWon(board, currentPlayer)) {
                        canWinInOneMove = true;
                    }
                    board[i][j] = '.'; // Backtrack to restore board state
                    if (canWinInOneMove) break; // Early exit optimization
                }
            }
            if (canWinInOneMove) break; // Early exit optimization
        }

        // 4. Output the result
        System.out.println(canWinInOneMove ? "YES" : "NO");
        scanner.close();
    }

    /**
     * Checks if the given player has achieved a winning condition on the board.
     * A win is defined as having WIN_LENGTH consecutive pieces in a row,
     * column, or diagonal.
     */
    private static boolean hasWon(char[][] board, char player) {
        int size = board.length;
        // Directions to check: horizontal, vertical, diagonal down-right, diagonal down-left
        int[][] directions = {{0, 1}, {1, 0}, {1, 1}, {1, -1}};

        for (int r = 0; r < size; r++) {
            for (int c = 0; c < size; c++) {
                if (board[r][c] != player) {
                    continue;
                }

                for (int[] dir : directions) {
                    int dr = dir[0];
                    int dc = dir[1];
                    boolean win = true;

                    // Check the next WIN_LENGTH - 1 cells in the current direction
                    for (int k = 1; k < WIN_LENGTH; k++) {
                        int nr = r + k * dr;
                        int nc = c + k * dc;

                        // Boundary check and piece match validation
                        if (nr < 0 || nr >= size || nc < 0 || nc >= size || board[nr][nc] != player) {
                            win = false;
                            break;
                        }
                    }

                    if (win) {
                        return true;
                    }
                }
            }
        }
        return false;
    }
}

import java.io.InputStream;
import java.io.OutputStream;
import java.io.PrintWriter;
import java.util.Scanner;

public class Main {
    private static final int BOARD_SIZE = 4;
    private static final char X = 'x';
    private static final char EMPTY = '.';

    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        Scanner in = new Scanner(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        new TaskCF390B().solve(in, out);
        out.close();
    }

    static class TaskCF390B {
        // Directions to check: right, down, down-right, down-left
        private static final int[][] DIRECTIONS = {
            {0, 1},
            {1, 0},
            {1, 1},
            {1, -1}
        };

        private boolean isWinning(char[][] board) {
            for (int r = 0; r < BOARD_SIZE; r++) {
                for (int c = 0; c < BOARD_SIZE; c++) {
                    if (board[r][c] != X) {
                        continue;
                    }

                    for (int[] dir : DIRECTIONS) {
                        int r2 = r + 2 * dir[0];
                        int c2 = c + 2 * dir[1];

                        // Check if the second step is within bounds.
                        // Since dir[0] >= 0, r2 >= 0 is guaranteed.
                        if (r2 < BOARD_SIZE && c2 >= 0 && c2 < BOARD_SIZE) {
                            int r1 = r + dir[0];
                            int c1 = c + dir[1];
                            if (board[r1][c1] == X && board[r2][c2] == X) {
                                return true;
                            }
                        }
                    }
                }
            }
            return false;
        }

        public void solve(Scanner in, PrintWriter out) {
            char[][] board = new char[BOARD_SIZE][BOARD_SIZE];
            for (int i = 0; i < BOARD_SIZE; i++) {
                board[i] = in.next().toCharArray();
            }

            for (int r = 0; r < BOARD_SIZE; r++) {
                for (int c = 0; c < BOARD_SIZE; c++) {
                    if (board[r][c] == EMPTY) {
                        board[r][c] = X;
                        if (isWinning(board)) {
                            out.println("YES");
                            return;
                        }
                        board[r][c] = EMPTY;
                    }
                }
            }
            out.println("NO");
        }
    }
}

import java.io.PrintWriter;
import java.util.Scanner;

/**
 * Refactored version of program B.
 * 
 * Improvements made:
 * 1. Readability: Replaced magic numbers (4, 2) with named constants (GRID_SIZE, WIN_LENGTH).
 * 2. Maintainability: Generalized the win-checking logic. Instead of four separate loop blocks 
 *    for horizontal, vertical, and diagonal checks, a unified approach iterates through directions.
 * 3. Resource Management: Used try-with-resources to ensure Scanner and PrintWriter are closed automatically.
 * 4. Variable Naming: Renamed 'f' to 'grid' and 'reader'/'writer' to 'scanner'/'out' for clarity.
 * 5. Modularity: Separated input reading and logic checking into distinct helper methods.
 */
public class B {

    private static final int GRID_SIZE = 4;
    private static final int WIN_LENGTH = 3;

    public static void main(String[] args) {
        // Use try-with-resources for automatic resource management
        try (Scanner scanner = new Scanner(System.in);
             PrintWriter out = new PrintWriter(System.out)) {

            char[][] grid = readGrid(scanner);

            if (canWin(grid)) {
                out.println("YES");
            } else {
                out.println("NO");
            }

            out.flush();
        }
    }

    /**
     * Reads the 4x4 grid from standard input.
     */
    private static char[][] readGrid(Scanner scanner) {
        char[][] grid = new char[GRID_SIZE][GRID_SIZE];
        for (int i = 0; i < GRID_SIZE; i++) {
            String line = scanner.nextLine();
            grid[i] = line.toCharArray();
        }
        return grid;
    }

    /**
     * Determines if the player ('x') can win in one move.
     * A win is possible if there is a line of length 3 containing exactly two 'x's and one '.'.
     */
    private static boolean canWin(char[][] grid) {
        // Define directions: Horizontal, Vertical, Diagonal Down-Right, Diagonal Down-Left
        // Format: {rowChange, colChange}
        int[][] directions = {
            {0, 1},   // Horizontal
            {1, 0},   // Vertical
            {1, 1},   // Diagonal \
            {1, -1}   // Diagonal /
        };

        // Iterate through every cell in the grid
        for (int r = 0; r < GRID_SIZE; r++) {
            for (int c = 0; c < GRID_SIZE; c++) {
                // Check all 4 directions starting from the current cell
                for (int[] dir : directions) {
                    if (checkLine(grid, r, c, dir[0], dir[1])) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Checks a specific line starting at (r, c) with direction (dr, dc).
     * Returns true if the line contains 2 'x's and 1 '.'.
     */
    private static boolean checkLine(char[][] grid, int r, int c, int dr, int dc) {
        // Calculate the coordinates of the last cell in the line
        int lastR = r + (WIN_LENGTH - 1) * dr;
        int lastC = c + (WIN_LENGTH - 1) * dc;

        // Check bounds to ensure the line fits within the grid
        if (lastR < 0 || lastR >= GRID_SIZE || lastC < 0 || lastC >= GRID_SIZE) {
            return false;
        }

        int xCount = 0;
        int dotCount = 0;

        // Inspect the cells in the line
        for (int k = 0; k < WIN_LENGTH; k++) {
            char cell = grid[r + k * dr][c + k * dc];
            if (cell == 'x') {
                xCount++;
            } else if (cell == '.') {
                dotCount++;
            }
        }

        // Winning condition: 2 'x's and 1 '.' (to complete the sequence)
        return xCount == 2 && dotCount == 1;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.OutputStream;
import java.io.PrintWriter;
import java.util.StringTokenizer;

public class Main {

    // Constants for grid dimensions and cell values to replace magic numbers
    private static final int GRID_SIZE = 8;
    private static final int INPUT_SIZE = 4;
    private static final int OFFSET = 2;
    private static final int CELL_X = 1;
    private static final int CELL_O = 2;
    private static final int CELL_EMPTY = 3;

    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);

        TaskB solver = new TaskB();
        solver.solve(in, out);

        out.close();
    }

    static class TaskB {
        public void solve(InputReader in, PrintWriter out) {
            int[][] grid = new int[GRID_SIZE][GRID_SIZE];

            // Read input and populate the grid
            // The input defines a 4x4 area centered in the 8x8 grid (indices 2-5)
            for (int i = 0; i < INPUT_SIZE; i++) {
                String row = in.next();
                if (row == null) break; // Handle potential EOF gracefully
                for (int j = 0; j < INPUT_SIZE; j++) {
                    char c = row.charAt(j);
                    int val;
                    if (c == 'x') {
                        val = CELL_X;
                    } else if (c == 'o') {
                        val = CELL_O;
                    } else {
                        val = CELL_EMPTY;
                    }
                    grid[i + OFFSET][j + OFFSET] = val;
                }
            }

            // Check if the specific pattern exists in the grid
            if (hasPattern(grid)) {
                out.println("YES");
            } else {
                out.println("NO");
            }
        }

        private boolean hasPattern(int[][] grid) {
            // Iterate through the populated area (indices 2 to 5)
            // We only need to check cells that are 'x' (1) as per the original logic
            for (int i = OFFSET; i < GRID_SIZE - OFFSET; i++) {
                for (int j = OFFSET; j < GRID_SIZE - OFFSET; j++) {
                    if (grid[i][j] == CELL_X) {
                        if (checkNeighbors(grid, i, j)) {
                            return true;
                        }
                    }
                }
            }
            return false;
        }

        private boolean checkNeighbors(int[][] grid, int r, int c) {
            // Check 4 axes: Horizontal, Vertical, Diagonal (\), Diagonal (/)
            // Directions are represented as (row_delta, col_delta)
            int[][] directions = {
                {0, 1},  // Horizontal
                {1, 0},  // Vertical
                {1, 1},  // Diagonal \
                {1, -1}  // Diagonal /
            };

            for (int[] dir : directions) {
                int dr = dir[0];
                int dc = dir[1];

                // Check if the current cell is part of a valid triplet in this direction
                if (isValidTriplet(grid, r, c, dr, dc)) {
                    return true;
                }
            }
            return false;
        }

        // Checks if cell (r,c) is part of a valid triplet in direction (dr, dc)
        // A valid triplet consists of the cell (r,c) [which is 1] and two neighbors
        // such that the neighbors are {1, 3} in any order.
        // This covers three cases relative to (r,c):
        // 1. (r,c) is the center of the triplet.
        // 2. (r,c) is the start of the triplet (looking forward).
        // 3. (r,c) is the end of the triplet (looking backward).
        private boolean isValidTriplet(int[][] grid, int r, int c, int dr, int dc) {
            // Case 1: (r,c) is the center. Neighbors are at distance 1 in opposite directions.
            if (isValidPair(grid[r - dr][c - dc], grid[r + dr][c + dc])) {
                return true;
            }

            // Case 2: (r,c) is the start. Neighbors are at distance 1 and 2 in the forward direction.
            if (isValidPair(grid[r + dr][c + dc], grid[r + 2 * dr][c + 2 * dc])) {
                return true;
            }

            // Case 3: (r,c) is the end. Neighbors are at distance 1 and 2 in the backward direction.
            if (isValidPair(grid[r - dr][c - dc], grid[r - 2 * dr][c - 2 * dc])) {
                return true;
            }

            return false;
        }

        // Checks if two values form the required pair {1, 3}
        private boolean isValidPair(int v1, int v2) {
            return (v1 == 1 && v2 == 3) || (v1 == 3 && v2 == 1);
        }
    }

    // Helper class for fast input reading
    static class InputReader {
        private BufferedReader in;
        private StringTokenizer tok;

        public InputReader(InputStream in) {
            this.in = new BufferedReader(new InputStreamReader(in));
        }

        public String next() {
            while (tok == null || !tok.hasMoreTokens()) {
                try {
                    String line = in.readLine();
                    if (line == null) {
                        return null;
                    }
                    tok = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tok.nextToken();
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;

public class GridLineChecker {

    private static final int GRID_SIZE = 4;
    private static final int MIN_LINE_LENGTH = 3;
    private static final int[][] DIRECTIONS = {{0, 1}, {1, 0}, {1, 1}, {-1, 1}};

    private final char[][] grid;
    private final PrintWriter out;

    /**
     * Constructs the solver and reads the 4x4 grid from standard input.
     */
    public GridLineChecker(BufferedReader reader, PrintWriter out) throws IOException {
        this.out = out;
        this.grid = new char[GRID_SIZE][];
        for (int i = 0; i < GRID_SIZE; i++) {
            String line = reader.readLine();
            // Skip potential empty lines and trim whitespace
            while (line != null && line.trim().isEmpty()) {
                line = reader.readLine();
            }
            if (line == null) break;
            this.grid[i] = line.trim().toCharArray();
        }
    }

    /**
     * Executes the main solving logic.
     */
    public void solve() {
        for (int row = 0; row < GRID_SIZE; row++) {
            for (int col = 0; col < GRID_SIZE; col++) {
                if (grid[row][col] == '.' && canFormLine(row, col)) {
                    out.println("YES");
                    return;
                }
            }
        }
        out.println("NO");
    }

    /**
     * Checks if a '.' at (row, col) can form a line of at least MIN_LINE_LENGTH 'x's
     * in any of the four diagonal/orthogonal directions.
     */
    private boolean canFormLine(int row, int col) {
        for (int[] direction : DIRECTIONS) {
            int dRow = direction[0];
            int dCol = direction[1];

            // The '.' itself counts as 1 towards the line length
            int count = 1;

            // Count consecutive 'x's in both directions along the axis
            count += countConsecutiveX(row, col, -dRow, -dCol);
            count += countConsecutiveX(row, col, dRow, dCol);

            if (count >= MIN_LINE_LENGTH) {
                return true;
            }
        }
        return false;
    }

    /**
     * Counts consecutive 'x's starting from (startRow, startCol) moving by (dRow, dCol).
     */
    private int countConsecutiveX(int startRow, int startCol, int dRow, int dCol) {
        int count = 0;
        int r = startRow + dRow;
        int c = startCol + dCol;

        while (isValidCoordinate(r, c) && grid[r][c] == 'x') {
            count++;
            r += dRow;
            c += dCol;
        }
        return count;
    }

    /**
     * Validates that a coordinate is within the bounds of the grid.
     */
    private boolean isValidCoordinate(int row, int col) {
        return row >= 0 && row < GRID_SIZE && col >= 0 && col < GRID_SIZE;
    }

    public static void main(String[] args) throws IOException {
        // try-with-resources ensures streams are properly closed and flushed
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
             PrintWriter out = new PrintWriter(System.out)) {

            GridLineChecker solver = new GridLineChecker(reader, out);
            solver.solve();
            out.flush();
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

/**
 * Refactored version of the grid game solver (originally c390B).
 * 
 * Refactoring Improvements:
 * 1. Naming Conventions: Renamed class to 'GridGameSolver' and loop variables 
 *    to descriptive names (row, col) for better readability.
 * 2. Constants: Replaced the hardcoded magic number '4' with a constant 'GRID_SIZE'.
 * 3. Separation of Concerns: Extracted the win-checking logic into a dedicated 
 *    method 'checkWin', making the main logic cleaner and easier to test.
 * 4. Efficiency: Optimized the win-check logic. Instead of scanning the entire 
 *    board after every move, it only checks the immediate neighbors of the 
 *    placed piece, reducing complexity.
 * 5. Code Structure: Used 'toCharArray()' for cleaner grid initialization and 
 *    implemented an early return strategy upon finding a winning move.
 */
public class GridGameSolver {

    private static final int GRID_SIZE = 4;
    private static final char EMPTY = '.';
    private static final char PLAYER = 'x';

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner();
        char[][] grid = new char[GRID_SIZE][GRID_SIZE];

        // Read the grid input
        for (int i = 0; i < GRID_SIZE; i++) {
            String rowStr = scanner.next();
            if (rowStr != null) {
                grid[i] = rowStr.toCharArray();
            }
        }

        // Iterate through every cell to simulate placing an 'x'
        for (int row = 0; row < GRID_SIZE; row++) {
            for (int col = 0; col < GRID_SIZE; col++) {
                if (grid[row][col] == EMPTY) {
                    // Place 'x'
                    grid[row][col] = PLAYER;

                    // Check if this move creates a win
                    if (checkWin(grid, row, col)) {
                        System.out.println("YES");
                        return; // Found a winning move, exit immediately
                    }

                    // Backtrack: remove 'x' to try next position
                    grid[row][col] = EMPTY;
                }
            }
        }

        System.out.println("NO");
    }

    /**
     * Checks if placing an 'x' at (row, col) completes a line of three 'x's.
     * The logic verifies if the placed piece acts as the center of a horizontal,
     * vertical, or diagonal line of three 'x's.
     */
    private static boolean checkWin(char[][] grid, int row, int col) {
        // Check Vertical: (row-1, col) and (row+1, col)
        if (row > 0 && row < GRID_SIZE - 1) {
            if (grid[row - 1][col] == PLAYER && grid[row + 1][col] == PLAYER) {
                return true;
            }
        }

        // Check Horizontal: (row, col-1) and (row, col+1)
        if (col > 0 && col < GRID_SIZE - 1) {
            if (grid[row][col - 1] == PLAYER && grid[row][col + 1] == PLAYER) {
                return true;
            }
        }

        // Check Diagonal (Top-Left to Bottom-Right): (row-1, col-1) and (row+1, col+1)
        if (row > 0 && row < GRID_SIZE - 1 && col > 0 && col < GRID_SIZE - 1) {
            if (grid[row - 1][col - 1] == PLAYER && grid[row + 1][col + 1] == PLAYER) {
                return true;
            }
        }

        // Check Diagonal (Top-Right to Bottom-Left): (row-1, col+1) and (row+1, col-1)
        if (row > 0 && row < GRID_SIZE - 1 && col > 0 && col < GRID_SIZE - 1) {
            if (grid[row - 1][col + 1] == PLAYER && grid[row + 1][col - 1] == PLAYER) {
                return true;
            }
        }

        return false;
    }

    /**
     * Helper class for fast input reading.
     */
    static class FastScanner {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastScanner() {
            reader = new BufferedReader(new InputStreamReader(System.in));
            tokenizer = new StringTokenizer("");
        }

        String next() {
            while (!tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return tokenizer.nextToken();
        }
    }
}

import java.io.*;
import java.util.*;

public class SolveB {
    // Constants for better maintainability and easier future modifications
    private static final int GRID_SIZE = 4;
    private static final char TARGET_CHAR = 'x';
    private static final char EMPTY_CHAR = '.';

    private final FastReader in;
    private final PrintWriter out;

    public SolveB() throws IOException {
        this.in = new FastReader(System.in);
        this.out = new PrintWriter(System.out);
        solve();
        out.flush();
        out.close();
    }

    private void solve() {
        char[][] grid = new char[GRID_SIZE][GRID_SIZE];
        for (int i = 0; i < GRID_SIZE; i++) {
            grid[i] = in.next().toCharArray();
        }

        // Directions: Right, Down, Down-Right, Down-Left
        int[][] directions = {{0, 1}, {1, 0}, {1, 1}, {1, -1}};

        for (int r = 0; r < GRID_SIZE; r++) {
            for (int c = 0; c < GRID_SIZE; c++) {
                for (int[] d : directions) {
                    int dr = d[0];
                    int dc = d[1];

                    // Verify that the entire 3-cell sequence stays within grid bounds
                    if (r + 2 * dr >= 0 && r + 2 * dr < GRID_SIZE &&
                        c + 2 * dc >= 0 && c + 2 * dc < GRID_SIZE) {

                        if (checkPattern(grid, r, c, dr, dc)) {
                            out.println("YES");
                            return;
                        }
                    }
                }
            }
        }
        out.println("NO");
    }

    /**
     * Checks a sequence of 3 cells starting at (r, c) in the direction (dr, dc).
     * Returns true if the sequence contains exactly two 'x's and one '.'.
     */
    private boolean checkPattern(char[][] grid, int r, int c, int dr, int dc) {
        int xCount = 0;
        int dotCount = 0;
        for (int k = 0; k < 3; k++) {
            char cell = grid[r + k * dr][c + k * dc];
            if (cell == TARGET_CHAR) {
                xCount++;
            } else if (cell == EMPTY_CHAR) {
                dotCount++;
            }
        }
        return xCount == 2 && dotCount == 1;
    }

    public static void main(String[] args) {
        // Standard competitive programming setup for fast I/O with increased stack size
        new Thread(null, () -> {
            try {
                new SolveB();
            } catch (IOException e) {
                e.printStackTrace();
            }
        }, "SolveB", 1 << 26).start();
    }

    /**
     * Optimized Fast I/O helper class
     */
    static class FastReader {
        private BufferedReader br;
        private StringTokenizer st;

        public FastReader(InputStream stream) {
            br = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }
    }
}

import java.io.PrintWriter;
import java.util.Scanner;

public class GridPatternChecker {
    private static final int GRID_SIZE = 4;
    private static final int PATTERN_LENGTH = 3;

    public static void main(String[] args) {
        // Try-with-resources ensures streams are properly closed
        try (Scanner scanner = new Scanner(System.in);
             PrintWriter out = new PrintWriter(System.out)) {

            char[][] grid = readGrid(scanner);
            boolean found = hasTargetPattern(grid);
            out.println(found ? "YES" : "NO");
            out.flush();
        }
    }

    private static char[][] readGrid(Scanner scanner) {
        char[][] grid = new char[GRID_SIZE][GRID_SIZE];
        for (int i = 0; i < GRID_SIZE; i++) {
            grid[i] = scanner.next().toCharArray();
        }
        return grid;
    }

    private static boolean hasTargetPattern(char[][] grid) {
        // Directions: right, down, down-right, down-left
        int[] dr = {0, 1, 1, 1};
        int[] dc = {1, 0, 1, -1};

        for (int d = 0; d < dr.length; d++) {
            for (int r = 0; r < GRID_SIZE; r++) {
                for (int c = 0; c < GRID_SIZE; c++) {
                    int endR = r + (PATTERN_LENGTH - 1) * dr[d];
                    int endC = c + (PATTERN_LENGTH - 1) * dc[d];

                    if (isWithinBounds(endR, endC)) {
                        if (isValidPattern(grid, r, c, dr[d], dc[d])) {
                            return true;
                        }
                    }
                }
            }
        }
        return false;
    }

    private static boolean isWithinBounds(int r, int c) {
        return r >= 0 && r < GRID_SIZE && c >= 0 && c < GRID_SIZE;
    }

    private static boolean isValidPattern(char[][] grid, int startR, int startC, int dr, int dc) {
        int xCount = 0;
        int dotCount = 0;

        for (int k = 0; k < PATTERN_LENGTH; k++) {
            char cell = grid[startR + k * dr][startC + k * dc];
            if (cell == 'x') {
                xCount++;
            } else if (cell == '.') {
                dotCount++;
            } else {
                return false; // Unexpected character in pattern
            }
        }
        return xCount == 2 && dotCount == 1;
    }
}

import java.io.BufferedReader;
