/**
 * Checks a 4x4 character grid for any sequence of 3 consecutive cells 
 * (horizontal, vertical, or diagonal) containing exactly two 'x's and one '.'.
 */
public class GridPatternChecker {

    private static final int GRID_SIZE = 4;
    private static final int WINDOW_SIZE = 3;

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner();
        char[][] grid = new char[GRID_SIZE][];

        for (int i = 0; i < GRID_SIZE; i++) {
            String row = scanner.next();
            if (row == null) {
                throw new IllegalStateException("Insufficient input: expected " + GRID_SIZE + " rows.");
            }
            grid[i] = row.toCharArray();
        }

        System.out.println(hasDesiredPattern(grid) ? "YES" : "NO");
    }

    /**
     * Scans the grid in all four cardinal/diagonal directions to find a 
     * sequence matching the target pattern.
     */
    private static boolean hasDesiredPattern(char[][] grid) {
        // Directions: Right, Down, Down-Right, Down-Left
        int[][] directions = {{0, 1}, {1, 0}, {1, 1}, {1, -1}};

        for (int[] dir : directions) {
            int dr = dir[0];
            int dc = dir[1];

            for (int r = 0; r < GRID_SIZE; r++) {
                for (int c = 0; c < GRID_SIZE; c++) {
                    // Calculate the ending coordinates of the sequence
                    int endR = r + dr * (WINDOW_SIZE - 1);
                    int endC = c + dc * (WINDOW_SIZE - 1);

                    // Verify the sequence stays within grid bounds
                    if (endR >= 0 && endR < GRID_SIZE && endC >= 0 && endC < GRID_SIZE) {
                        if (checkSequence(grid, r, c, dr, dc)) {
                            return true;
                        }
                    }
                }
            }
        }
        return false;
    }

    /**
     * Checks a specific sequence of length WINDOW_SIZE starting at (startRow, startCol)
     * in the given direction. Returns true if exactly 2 'x's and 1 '.' are found.
     */
    private static boolean checkSequence(char[][] grid, int startRow, int startCol, int dRow, int dCol) {
        int xCount = 0;
        int dotCount = 0;

        for (int i = 0; i < WINDOW_SIZE; i++) {
            char c = grid[startRow + i * dRow][startCol + i * dCol];
            if (c == 'x') {
                xCount++;
            } else if (c == '.') {
                dotCount++;
            }
        }

        return xCount == 2 && dotCount == 1;
    }

    /**
     * Lightweight, robust input scanner optimized for competitive programming.
     */
    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner() {
            this(new InputStreamReader(System.in));
        }

        public FastScanner(Reader in) {
            br = new BufferedReader(in);
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input", e);
                }
            }
            return st.nextToken();
        }
    }
}

import java.util.Scanner;
import java.io.PrintWriter;

public class Main {
    private static final int GRID_SIZE = 4;
    private static final int MIN_CONSECUTIVE = 3;

    public static void main(String[] args) {
        // try-with-resources ensures Scanner and PrintWriter are properly closed
        try (Scanner scanner = new Scanner(System.in);
             PrintWriter out = new PrintWriter(System.out)) {

            char[][] grid = new char[GRID_SIZE][GRID_SIZE];
            for (int i = 0; i < GRID_SIZE; i++) {
                String row = scanner.next();
                if (row.length() != GRID_SIZE) {
                    throw new IllegalArgumentException("Each row must contain exactly " + GRID_SIZE + " characters.");
                }
                grid[i] = row.toCharArray();
            }

            if (hasWinningMove(grid)) {
                out.println("YES");
            } else {
                out.println("NO");
            }
        }
    }

    /**
     * Scans the grid for any '.' that could form a line of at least MIN_CONSECUTIVE 'x's
     * when replaced. Checks all 4 primary axes: diagonal \, diagonal /, horizontal, vertical.
     */
    private static boolean hasWinningMove(char[][] grid) {
        for (int r = 0; r < GRID_SIZE; r++) {
            for (int c = 0; c < GRID_SIZE; c++) {
                if (grid[r][c] == '.') {
                    // Check the four independent directions
                    if (checkDirection(grid, r, c, -1, -1) || // Diagonal \
                        checkDirection(grid, r, c, -1, 1)  || // Diagonal /
                        checkDirection(grid, r, c, 0, -1)    || // Horizontal
                        checkDirection(grid, r, c, -1, 0)) {   // Vertical
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Counts consecutive 'x's in both directions along a given axis starting from (r, c).
     * Assumes the cell at (r, c) is effectively 'x' (count starts at 1).
     */
    private static boolean checkDirection(char[][] grid, int r, int c, int dr, int dc) {
        int count = 1; // Account for the current '.' cell being treated as 'x'

        // Count forward in the specified direction
        int nr = r + dr;
        int nc = c + dc;
        while (isValid(nr, nc) && grid[nr][nc] == 'x') {
            count++;
            nr += dr;
            nc += dc;
        }

        // Count backward in the opposite direction
        nr = r - dr;
        nc = c - dc;
        while (isValid(nr, nc) && grid[nr][nc] == 'x') {
            count++;
            nr -= dr;
            nc -= dc;
        }

        return count >= MIN_CONSECUTIVE;
    }

    /**
     * Checks if row and column indices are within grid bounds.
     */
    private static boolean isValid(int r, int c) {
        return r >= 0 && r < GRID_SIZE && c >= 0 && c < GRID_SIZE;
    }
}

import java.io.InputStream;
import java.io.IOException;
import java.io.PrintWriter;
import java.util.InputMismatchException;

public class Main {
    // Configuration constants to replace magic numbers
    private static final int GRID_SIZE = 4;
    private static final int LINE_LENGTH = 3;
    private static final int X_VALUE = 1;
    private static final int EMPTY_VALUE = 0;
    private static final int O_VALUE = 2;

    public static void main(String[] args) {
        InputReader in = new InputReader(System.in);
        PrintWriter out = new PrintWriter(System.out);
        new TaskB().solve(1, in, out);
        out.flush();
        out.close();
    }

    static class TaskB {
        public void solve(int testNumber, InputReader in, PrintWriter out) {
            int[][] grid = readGrid(in);
            boolean found = checkForPattern(grid);
            out.println(found ? "YES" : "NO");
        }

        private int[][] readGrid(InputReader in) {
            int[][] grid = new int[GRID_SIZE][GRID_SIZE];
            for (int i = 0; i < GRID_SIZE; i++) {
                for (int j = 0; j < GRID_SIZE; j++) {
                    char c = in.readCharacter();
                    if (c == 'x') grid[i][j] = X_VALUE;
                    else if (c == 'o') grid[i][j] = O_VALUE;
                    else grid[i][j] = EMPTY_VALUE;
                }
            }
            return grid;
        }

        private boolean checkForPattern(int[][] grid) {
            // Direction vectors: horizontal, vertical, diagonal down-right, diagonal down-left
            int[][] directions = {
                {0, 1}, {1, 0}, {1, 1}, {1, -1}
            };

            for (int[] dir : directions) {
                for (int r = 0; r < GRID_SIZE; r++) {
                    for (int c = 0; c < GRID_SIZE; c++) {
                        int c2 = c + dir[1];
                        int c3 = c + 2 * dir[1];
                        int r2 = r + dir[0];
                        int r3 = r + 2 * dir[0];

                        if (isWithinBounds(r2, c2, r3, c3)) {
                            if (checkLine(grid[r][c], grid[r2][c2], grid[r3][c3])) {
                                return true;
                            }
                        }
                    }
                }
            }
            return false;
        }

        private boolean isWithinBounds(int r2, int c2, int r3, int c3) {
            return r2 >= 0 && r2 < GRID_SIZE && c2 >= 0 && c2 < GRID_SIZE &&
                   r3 >= 0 && r3 < GRID_SIZE && c3 >= 0 && c3 < GRID_SIZE;
        }

        private boolean checkLine(int v1, int v2, int v3) {
            int xCount = 0;
            int emptyCount = 0;
            for (int v : new int[]{v1, v2, v3}) {
                if (v == X_VALUE) xCount++;
                else if (v == EMPTY_VALUE) emptyCount++;
            }
            // Matches original logic: exactly two 'x's and one empty cell
            return xCount == 2 && emptyCount == 1;
        }
    }

    // High-performance input reader (standard competitive programming template)
    static class InputReader {
        private final InputStream stream;
        private final byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        public int read() {
            if (numChars == -1) {
                throw new InputMismatchException();
            }
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0) {
                    return -1;
                }
            }
            return buf[curChar++];
        }

        public static boolean isSpaceChar(int c) {
            return c == 32 || c == 10 || c == 13 || c == 9 || c == -1;
        }

        public char readCharacter() {
            int c;
            do {
                c = read();
            } while (isSpaceChar(c));
            return (char) c;
        }
    }
}

import java.util.Scanner;

/**
 * Refactored solution for problem B390.
 * Improvements:
 * 1. Replaced magic numbers with constants (GRID_SIZE).
 * 2. Extracted logic into descriptive methods (readGrid, solve, checkWinCondition, hasThreeConsecutive).
 * 3. Used a directions array to simplify boundary checks and pattern matching logic.
 * 4. Used try-with-resources for proper Scanner management.
 * 5. Improved variable naming for readability.
 */
public class B390 {

    // Constant for grid size to avoid magic numbers
    private static final int GRID_SIZE = 4;

    public static void main(String[] args) {
        // Use try-with-resources to ensure the Scanner is closed properly
        try (Scanner sc = new Scanner(System.in)) {
            char[][] grid = readGrid(sc);
            boolean result = solve(grid);
            System.out.println(result ? "YES" : "NO");
        }
    }

    /**
     * Reads the 4x4 grid from the input.
     */
    private static char[][] readGrid(Scanner sc) {
        char[][] grid = new char[GRID_SIZE][GRID_SIZE];
        for (int i = 0; i < GRID_SIZE; i++) {
            if (sc.hasNext()) {
                String row = sc.next();
                grid[i] = row.toCharArray();
            }
        }
        return grid;
    }

    /**
     * Attempts to place an 'x' in every empty spot ('.') and checks if it results in a win.
     */
    private static boolean solve(char[][] grid) {
        for (int row = 0; row < GRID_SIZE; row++) {
            for (int col = 0; col < GRID_SIZE; col++) {
                if (grid[row][col] == '.') {
                    // Place 'x'
                    grid[row][col] = 'x';

                    // Check if this move results in a win
                    if (checkWinCondition(grid)) {
                        return true;
                    }

                    // Backtrack: revert the change
                    grid[row][col] = '.';
                }
            }
        }
        return false;
    }

    /**
     * Checks if the current board state contains 3 consecutive 'x's.
     */
    private static boolean checkWinCondition(char[][] grid) {
        // Directions to check: Horizontal (Right), Vertical (Down), Diagonal (Down-Right), Diagonal (Down-Left)
        // We only need to check these 4 directions because iterating through all cells covers all potential lines.
        int[][] directions = {
            {0, 1},  // Right
            {1, 0},  // Down
            {1, 1},  // Down-Right
            {1, -1}  // Down-Left
        };

        for (int i = 0; i < GRID_SIZE; i++) {
            for (int j = 0; j < GRID_SIZE; j++) {
                if (grid[i][j] == 'x') {
                    for (int[] dir : directions) {
                        if (hasThreeConsecutive(grid, i, j, dir[0], dir[1])) {
                            return true;
                        }
                    }
                }
            }
        }
        return false;
    }

    /**
     * Checks if there are 3 consecutive 'x's starting from (r, c) in the direction (dr, dc).
     */
    private static boolean hasThreeConsecutive(char[][] grid, int r, int c, int dr, int dc) {
        // Calculate coordinates of the 3rd cell in the sequence
        int r2 = r + 2 * dr;
        int c2 = c + 2 * dc;

        // Check bounds for the 3rd cell
        if (r2 < 0 || r2 >= GRID_SIZE || c2 < 0 || c2 >= GRID_SIZE) {
            return false;
        }

        // Verify if all 3 cells in the line are 'x'
        return grid[r][c] == 'x' &&
               grid[r + dr][c + dc] == 'x' &&
               grid[r2][c2] == 'x';
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayList;
import java.util.List;

public class Main {
    private static final int GRID_SIZE = 4;
    private static final String[] PATTERNS = {"x.x", "xx.", ".xx"};

    public static void main(String[] args) throws IOException {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        char[][] grid = new char[GRID_SIZE][GRID_SIZE];

        // Read the 4x4 grid
        for (int i = 0; i < GRID_SIZE; i++) {
            String line = reader.readLine();
            if (line == null) break;
            grid[i] = line.toCharArray();
        }

        // Extract all relevant rows, columns, and diagonals
        List<String> linesToCheck = extractLines(grid);
        boolean patternFound = false;

        // Check if any line contains the target patterns
        for (String line : linesToCheck) {
            for (String pattern : PATTERNS) {
                if (line.contains(pattern)) {
                    patternFound = true;
                    break;
                }
            }
            if (patternFound) break;
        }

        System.out.println(patternFound ? "YES" : "NO");
    }

    /**
     * Extracts rows, columns, main/anti-diagonals, and inner sub-diagonals
     * from the grid into a list of strings for pattern matching.
     */
    private static List<String> extractLines(char[][] grid) {
        List<String> lines = new ArrayList<>();

        // Add rows
        for (char[] row : grid) {
            lines.add(new String(row));
        }

        // Add columns
        for (int col = 0; col < GRID_SIZE; col++) {
            StringBuilder sb = new StringBuilder(GRID_SIZE);
            for (int row = 0; row < GRID_SIZE; row++) {
                sb.append(grid[row][col]);
            }
            lines.add(sb.toString());
        }

        // Add main diagonal
        lines.add(extractDiagonal(grid, 0, 0, 1, 1));
        // Add anti-diagonal
        lines.add(extractDiagonal(grid, 0, GRID_SIZE - 1, 1, -1));

        // Add sub-diagonals of length 3 (matching original hardcoded logic)
        lines.add(extractDiagonal(grid, 1, 0, 1, 1));
        lines.add(extractDiagonal(grid, 0, 1, 1, 1));
        lines.add(extractDiagonal(grid, 0, 2, 1, -1));
        lines.add(extractDiagonal(grid, 1, 3, 1, -1));

        return lines;
    }

    /**
     * Extracts a diagonal string starting from (startRow, startCol)
     * moving in the direction defined by (rowStep, colStep).
     */
    private static String extractDiagonal(char[][] grid, int startRow, int startCol, int rowStep, int colStep) {
        StringBuilder sb = new StringBuilder(GRID_SIZE);
        int r = startRow;
        int c = startCol;
        while (r >= 0 && r < GRID_SIZE && c >= 0 && c < GRID_SIZE) {
            sb.append(grid[r][c]);
            r += rowStep;
            c += colStep;
        }
        return sb.toString();
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;

public class B3901 {

    private static final int GRID_SIZE = 4;
    private static final int EMPTY = 0;
    private static final int PLAYER_X = 1;
    private static final int PLAYER_O = 2;

    // Direction vectors: (dr, dc) representing the 8 possible directions
    private static final int[] DR = {0, 1, 1, 1, 0, -1, -1, -1};
    private static final int[] DC = {1, 1, 0, -1, -1, -1, 0, 1};

    public static void main(String[] args) throws IOException {
        // Use try-with-resources for automatic resource management
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
             PrintWriter out = new PrintWriter(System.out)) {

            int[][] grid = new int[GRID_SIZE][GRID_SIZE];

            // Read and parse the 4x4 grid
            for (int i = 0; i < GRID_SIZE; i++) {
                String line = reader.readLine();
                if (line == null) break;
                line = line.trim();
                for (int j = 0; j < GRID_SIZE; j++) {
                    if (j < line.length()) {
                        grid[i][j] = mapChar(line.charAt(j));
                    }
                }
            }

            // Check if any 'x' satisfies the pattern condition
            boolean patternFound = false;
            for (int i = 0; i < GRID_SIZE; i++) {
                for (int j = 0; j < GRID_SIZE; j++) {
                    if (grid[i][j] == PLAYER_X && checkPattern(grid, i, j)) {
                        patternFound = true;
                        break;
                    }
                }
                if (patternFound) break;
            }

            out.println(patternFound ? "YES" : "NO");
        }
    }

    /**
     * Maps input characters to their corresponding integer values.
     */
    private static int mapChar(char ch) {
        if (ch == 'x') return PLAYER_X;
        if (ch == 'o') return PLAYER_O;
        return EMPTY;
    }

    /**
     * Checks if the given cell (row, col) forms the required pattern 
     * with two consecutive cells in any of the 8 directions.
     * The pattern requires the two cells to be (0, 1) or (1, 0).
     */
    private static boolean checkPattern(int[][] grid, int row, int col) {
        for (int d = 0; d < DR.length; d++) {
            int r1 = row + DR[d];
            int c1 = col + DC[d];
            int r2 = row + 2 * DR[d];
            int c2 = col + 2 * DC[d];

            // Both intermediate and final cells must be within bounds
            if (isValid(grid, r1, c1) && isValid(grid, r2, c2)) {
                int val1 = grid[r1][c1];
                int val2 = grid[r2][c2];
                // Equivalent to checking if concatenated string is "01" or "10"
                if ((val1 == EMPTY && val2 == PLAYER_X) || (val1 == PLAYER_X && val2 == EMPTY)) {
                    return true;
                }
            }
        }
        return false;
    }

    /**
     * Validates that coordinates are within the grid boundaries.
     */
    private static boolean isValid(int[][] grid, int r, int c) {
        return r >= 0 && r < GRID_SIZE && c >= 0 && c < GRID_SIZE;
    }
}

import java.util.Scanner;

public class GridSolver {

    private static final int GRID_SIZE = 4;
    private static final char EMPTY_CELL = '.';
    private static final char PLAYER_MARK = 'x';

    public static void main(String[] args) {
        // Use try-with-resources to ensure the Scanner is closed properly
        try (Scanner scanner = new Scanner(System.in)) {
            char[][] grid = readGrid(scanner);

            if (canPlaceWinningMove(grid)) {
                System.out.println("YES");
            } else {
                System.out.println("NO");
            }
        }
    }

    /**
     * Reads the 4x4 grid from the scanner.
     * Handles potential input irregularities gracefully.
     */
    private static char[][] readGrid(Scanner scanner) {
        char[][] grid = new char[GRID_SIZE][];
        for (int i = 0; i < GRID_SIZE; i++) {
            if (scanner.hasNextLine()) {
                grid[i] = scanner.nextLine().toCharArray();
            }
        }
        return grid;
    }

    /**
     * Checks if there is any empty cell where placing a mark results in 3-in-a-row.
     * Iterates through the grid to find a valid move.
     */
    private static boolean canPlaceWinningMove(char[][] grid) {
        for (int r = 0; r < GRID_SIZE; r++) {
            // Safety check for row length (handles jagged arrays or short inputs)
            if (grid[r] == null) continue;

            for (int c = 0; c < grid[r].length; c++) {
                if (grid[r][c] == EMPTY_CELL) {
                    if (wouldResultInWin(grid, r, c)) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Simulates placing a mark at (r, c) and checks if it creates a line of 3.
     * Checks all 4 directions (Horizontal, Vertical, Diagonal, Anti-Diagonal).
     */
    private static boolean wouldResultInWin(char[][] grid, int r, int c) {
        // Directions: Horizontal, Vertical, Diagonal, Anti-Diagonal
        // Represented as {row_delta, col_delta}
        int[][] directions = {
            {0, 1},  // Horizontal
            {1, 0},  // Vertical
            {1, 1},  // Diagonal (Top-Left to Bottom-Right)
            {1, -1}  // Anti-Diagonal (Top-Right to Bottom-Left)
        };

        for (int[] dir : directions) {
            int count = 1; // Count the current cell being placed

            // Check in the positive direction (forward)
            int currR = r + dir[0];
            int currC = c + dir[1];
            while (isValid(grid, currR, currC) && grid[currR][currC] == PLAYER_MARK) {
                count++;
                currR += dir[0];
                currC += dir[1];
            }

            // Check in the negative direction (backward)
            currR = r - dir[0];
            currC = c - dir[1];
            while (isValid(grid, currR, currC) && grid[currR][currC] == PLAYER_MARK) {
                count++;
                currR -= dir[0];
                currC -= dir[1];
            }

            if (count >= 3) {
                return true;
            }
        }
        return false;
    }

    /**
     * Checks if coordinates are within the grid bounds.
     * Handles potential null rows or short rows safely.
     */
    private static boolean isValid(char[][] grid, int r, int c) {
        if (r < 0 || r >= grid.length) return false;
        if (grid[r] == null) return false;
        if (c < 0 || c >= grid[r].length) return false;
        return true;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.OutputStream;
import java.io.PrintWriter;
import java.util.StringTokenizer;

/**
 * Main class for solving the grid pattern problem.
 * Checks if a 4x4 grid contains a specific sequence of 'x' and '.' characters
 * in any of the 8 possible directions, stopping at 'o' or grid boundaries.
 */
public class Main {
    private static final int GRID_SIZE = 4;
    private static final int[] DX = {-1, 0, 1, 0, 1, -1, 1, -1};
    private static final int[] DY = {0, -1, 0, 1, 1, -1, -1, 1};

    public static void main(String[] args) {
        // Use try-with-resources for automatic and safe resource management
        try (InputStream inputStream = System.in;
             OutputStream outputStream = System.out;
             PrintWriter out = new PrintWriter(outputStream)) {

            InputReader in = new InputReader(inputStream);
            solve(in, out);
        } catch (IOException e) {
            throw new RuntimeException("I/O error occurred", e);
        }
    }

    /**
     * Core logic to solve the problem.
     * Reads the grid and checks for valid patterns in all 8 directions.
     */
    private static void solve(InputReader in, PrintWriter out) {
        char[][] grid = new char[GRID_SIZE][GRID_SIZE];
        for (int i = 0; i < GRID_SIZE; i++) {
            grid[i] = in.next().toCharArray();
        }

        for (int x = 0; x < GRID_SIZE; x++) {
            for (int y = 0; y < GRID_SIZE; y++) {
                // Only start scanning from 'x' cells
                if (grid[x][y] == 'x') {
                    for (int k = 0; k < DX.length; k++) {
                        int cx = x;
                        int cy = y;
                        int xCount = 0;
                        int dotCount = 0;

                        // Traverse in the current direction until boundary or 'o' is hit
                        while (isInside(cx, cy) && grid[cx][cy] != 'o') {
                            if (grid[cx][cy] == 'x') {
                                xCount++;
                            } else if (grid[cx][cy] == '.') {
                                dotCount++;
                            }

                            // Check for the target pattern: 
                            // exactly 3 'x's, or exactly 2 'x's and 1 '.'
                            if ((xCount == 2 && dotCount == 1) || (xCount == 3 && dotCount == 0)) {
                                out.println("YES");
                                return;
                            }

                            cx += DX[k];
                            cy += DY[k];
                        }
                    }
                }
            }
        }
        out.println("NO");
    }

    /**
     * Checks if coordinates are within the grid boundaries.
     */
    private static boolean isInside(int x, int y) {
        return x >= 0 && x < GRID_SIZE && y >= 0 && y < GRID_SIZE;
    }

    /**
     * Fast I/O helper class for competitive programming.
     */
    static class InputReader {
        public BufferedReader reader;
        public StringTokenizer tokenizer;

        public InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) {
                        return null;
                    }
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }
    }
}

import java.io.BufferedReader;
