public class IlyaAndTicTacToeGame {
    private static final int GRID_SIZE = 4;
    private static final int WIN_LENGTH = 3;
    private static final char PLAYER = 'x';
    private static final char EMPTY = '.';

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner(System.in);
        char[][] grid = new char[GRID_SIZE][GRID_SIZE];

        for (int i = 0; i < GRID_SIZE; i++) {
            String row = scanner.next();
            if (row != null) {
                grid[i] = row.toCharArray();
            }
        }

        boolean found = false;
        for (int i = 0; i < GRID_SIZE; i++) {
            for (int j = 0; j < GRID_SIZE; j++) {
                if (grid[i][j] == EMPTY) {
                    grid[i][j] = PLAYER;
                    if (hasWinningLine(grid)) {
                        found = true;
                    }
                    grid[i][j] = EMPTY; // Backtrack to restore grid state
                    if (found) break;
                }
            }
            if (found) break;
        }

        System.out.println(found ? "YES" : "NO");
    }

    /**
     * Checks if there is any winning line of WIN_LENGTH consecutive PLAYER characters.
     */
    private static boolean hasWinningLine(char[][] grid) {
        // Directions: Right, Down, Down-Right, Down-Left
        int[] dRow = {0, 1, 1, 1};
        int[] dCol = {1, 0, 1, -1};

        for (int r = 0; r < GRID_SIZE; r++) {
            for (int c = 0; c < GRID_SIZE; c++) {
                for (int dir = 0; dir < 4; dir++) {
                    if (checkDirection(grid, r, c, dRow[dir], dCol[dir])) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Checks if WIN_LENGTH consecutive cells starting at (r, c) in direction (dr, dc) are all PLAYER.
     */
    private static boolean checkDirection(char[][] grid, int r, int c, int dr, int dc) {
        for (int k = 0; k < WIN_LENGTH; k++) {
            int nr = r + k * dr;
            int nc = c + k * dc;
            if (nr < 0 || nr >= GRID_SIZE || nc < 0 || nc >= GRID_SIZE || grid[nr][nc] != PLAYER) {
                return false;
            }
        }
        return true;
    }

    /**
     * Lightweight fast scanner for efficient token-based input reading.
     */
    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner(InputStream in) {
            this.br = new BufferedReader(new InputStreamReader(in));
        }

        public String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) {
                        return null;
                    }
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input", e);
                }
            }
            return st.nextToken();
        }
    }
}

