/**
 * Refactored version of the original grid-sum checker.
 * 
 * Key improvements:
 * 1. Extracted magic numbers/strings into named constants for readability and easy configuration.
 * 2. Replaced repetitive nested loops with a generalized direction-based segment checker.
 * 3. Separated I/O handling from business logic for better testability and maintainability.
 * 4. Removed unused imports and methods to reduce clutter.
 * 5. Improved error handling and resource management.
 */
public class Main {

    // Configuration constants
    private static final int GRID_SIZE = 4;
    private static final int SEGMENT_LENGTH = 3;
    private static final int TARGET_SUM = 286;
    private static final String RESULT_YES = "YES";
    private static final String RESULT_NO = "NO";

    // I/O components
    private BufferedReader br;
    private PrintWriter out;
    private StringTokenizer sc;

    public static void main(String[] args) {
        new Main().run();
    }

    /**
     * Entry point for execution. Sets up I/O streams and handles top-level exceptions.
     */
    public void run() {
        br = new BufferedReader(new InputStreamReader(System.in));
        out = new PrintWriter(System.out);
        try {
            solve();
        } catch (IOException e) {
            out.println("Error: Failed to read input. " + e.getMessage());
        } finally {
            out.flush();
            out.close();
        }
    }

    /**
     * Orchestrates the grid reading and sum-checking logic.
     */
    private void solve() throws IOException {
        int[][] grid = readGrid();
        out.println(hasTargetSum(grid) ? RESULT_YES : RESULT_NO);
    }

    /**
     * Reads the 4x4 grid from standard input.
     */
    private int[][] readGrid() throws IOException {
        int[][] grid = new int[GRID_SIZE][GRID_SIZE];
        for (int i = 0; i < GRID_SIZE; i++) {
            String row = nextToken();
            if (row == null || row.length() < GRID_SIZE) {
                throw new IOException("Invalid input at row " + i);
            }
            for (int j = 0; j < GRID_SIZE; j++) {
                grid[i][j] = row.charAt(j);
            }
        }
        return grid;
    }

    /**
     * Checks if any contiguous segment of length 3 in rows, columns, or diagonals sums to TARGET_SUM.
     */
    private boolean hasTargetSum(int[][] grid) {
        // Directions: right, down, diagonal down-right, diagonal down-left
        int[][] directions = {{0, 1}, {1, 0}, {1, 1}, {1, -1}};

        for (int r = 0; r < GRID_SIZE; r++) {
            for (int c = 0; c < GRID_SIZE; c++) {
                for (int[] dir : directions) {
                    if (isValidSegmentStart(r, c, dir)) {
                        int sum = 0;
                        for (int k = 0; k < SEGMENT_LENGTH; k++) {
                            sum += grid[r + k * dir[0]][c + k * dir[1]];
                        }
                        if (sum == TARGET_SUM) {
                            return true;
                        }
                    }
                }
            }
        }
        return false;
    }

    /**
     * Validates whether a segment of SEGMENT_LENGTH starting at (r, c) in the given direction
     * stays within the bounds of the grid.
     */
    private boolean isValidSegmentStart(int r, int c, int[] dir) {
        int endR = r + (SEGMENT_LENGTH - 1) * dir[0];
        int endC = c + (SEGMENT_LENGTH - 1) * dir[1];
        return endR >= 0 && endR < GRID_SIZE && endC >= 0 && endC < GRID_SIZE;
    }

    /**
     * Fetches the next token from the input stream.
     */
    private String nextToken() throws IOException {
        while (sc == null || !sc.hasMoreTokens()) {
            String line = br.readLine();
            if (line == null) {
                return null;
            }
            sc = new StringTokenizer(line);
        }
        return sc.nextToken();
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;

/**
 * A solver for a 4x4 grid-based game (likely a Tic-Tac-Toe variant).
 * Checks if a winning configuration exists based on specific rules.
 */
public class Tic {

    // Constant for board size to avoid magic numbers
    private static final int BOARD_SIZE = 4;

    public static void main(String[] args) throws IOException {
        // Use try-with-resources to ensure the BufferedReader is closed automatically
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(System.in))) {
            char[][] board = new char[BOARD_SIZE][BOARD_SIZE];

            // Read the board configuration
            for (int i = 0; i < BOARD_SIZE; i++) {
                String line = reader.readLine();
                if (line != null) {
                    board[i] = line.toCharArray();
                }
            }

            // Check if there is a winning configuration
            if (hasWinningConfiguration(board)) {
                System.out.println("YES");
            } else {
                System.out.println("NO");
            }
        }
    }

    /**
     * Iterates through the board to check for any winning lines of length 3.
     * A winning line is defined by the center cell and its two neighbors.
     */
    private static boolean hasWinningConfiguration(char[][] board) {
        for (int row = 0; row < BOARD_SIZE; row++) {
            for (int col = 0; col < BOARD_SIZE; col++) {
                char currentChar = board[row][col];

                // Check Vertical Line (Up and Down)
                // Valid indices for center of a 3-line segment in size 4 are 1 and 2
                if (row > 0 && row < BOARD_SIZE - 1) {
                    if (checkforwin(currentChar, board[row - 1][col], board[row + 1][col])) {
                        return true;
                    }
                }

                // Check Horizontal Line (Left and Right)
                if (col > 0 && col < BOARD_SIZE - 1) {
                    if (checkforwin(currentChar, board[row][col + 1], board[row][col - 1])) {
                        return true;
                    }
                }

                // Check Diagonals
                // Valid if row and col are not on the edge
                if (row > 0 && row < BOARD_SIZE - 1 && col > 0 && col < BOARD_SIZE - 1) {
                    // Diagonal \ (Top-Left to Bottom-Right)
                    if (checkforwin(currentChar, board[row - 1][col - 1], board[row + 1][col + 1])) {
                        return true;
                    }
                    // Diagonal / (Top-Right to Bottom-Left)
                    if (checkforwin(currentChar, board[row - 1][col + 1], board[row + 1][col - 1])) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Determines if a triplet of characters constitutes a win.
     * Logic: Counts 'x' as +1 and 'o' as -1. Returns true if sum >= 2.
     * This effectively checks for a strong presence of 'x' (e.g., 3 'x's or 2 'x's and a neutral).
     */
    public static boolean checkforwin(char... inp) {
        int count = 0;
        for (char c : inp) {
            if (c == 'x') {
                count++;
            } else if (c == 'o') {
                count--;
            }
        }
        return count >= 2;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

public class Main {
    private static final int GRID_SIZE = 4;
    private static final int SEQUENCE_LENGTH = 3;
    private static final int REQUIRED_X_COUNT = 2;
    private static final int REQUIRED_DOT_COUNT = 1;

    public static void main(String[] args) throws IOException {
        FastScanner scanner = new FastScanner();
        PrintWriter out = new PrintWriter(System.out);

        try {
            char[][] grid = readGrid(scanner, GRID_SIZE);
            if (checkGrid(grid, GRID_SIZE, SEQUENCE_LENGTH)) {
                out.println("YES");
            } else {
                out.println("NO");
            }
        } finally {
            out.close();
        }
    }

    private static char[][] readGrid(FastScanner scanner, int size) throws IOException {
        char[][] grid = new char[size][size];
        for (int i = 0; i < size; i++) {
            grid[i] = scanner.next().toCharArray();
        }
        return grid;
    }

    private static boolean checkGrid(char[][] grid, int size, int seqLen) {
        int[][] directions = {{0, 1}, {1, 0}, {1, 1}, {-1, 1}};
        for (int r = 0; r < size; r++) {
            for (int c = 0; c < size; c++) {
                for (int[] dir : directions) {
                    int dr = dir[0];
                    int dc = dir[1];

                    int endR = r + (seqLen - 1) * dr;
                    int endC = c + (seqLen - 1) * dc;

                    // Check if the entire sequence fits within grid bounds
                    if (endR >= 0 && endR < size && endC >= 0 && endC < size) {
                        if (checkSequence(grid, r, c, dr, dc, seqLen)) {
                            return true;
                        }
                    }
                }
            }
        }
        return false;
    }

    private static boolean checkSequence(char[][] grid, int startR, int startC, int dr, int dc, int seqLen) {
        int xCount = 0;
        int dotCount = 0;
        for (int k = 0; k < seqLen; k++) {
            char cell = grid[startR + k * dr][startC + k * dc];
            if (cell == 'x') {
                xCount++;
            } else if (cell == '.') {
                dotCount++;
            }
        }
        return xCount == REQUIRED_X_COUNT && dotCount == REQUIRED_DOT_COUNT;
    }

    static class FastScanner {
        private BufferedReader br;
        private StringTokenizer st;

        public FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) {
                    throw new IOException("Unexpected end of input");
                }
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;

/**
 * Refactored version of LlyaAndTicTacToeGame.
 * 
 * Key Improvements:
 * 1. Removed global mutable state (static arr) to improve encapsulation.
 * 2. Replaced magic numbers (4, 3, 0, 1, -1) with named constants.
 * 3. Extracted logic into separate methods (readGrid, hasWinningPattern, checkSequence)
 *    to adhere to the Single Responsibility Principle.
 * 4. Replaced inefficient string concatenation and pattern matching with integer arithmetic.
 * 5. Generalized loop structures for rows, columns, and diagonals to reduce code duplication.
 * 6. Used try-with-resources for automatic resource management.
 */
public class LlyaAndTicTacToeGame {

    // Constants for grid configuration
    private static final int GRID_SIZE = 4;
    private static final int SEQUENCE_LENGTH = 3;

    // Cell values
    private static final int PLAYER_X = 1;
    private static final int PLAYER_O = -1;
    private static final int EMPTY = 0;

    public static void main(String[] args) throws IOException {
        // Use try-with-resources to ensure the reader is closed properly
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(System.in))) {
            int[][] grid = readGrid(reader);

            if (hasWinningPattern(grid)) {
                System.out.println("YES");
            } else {
                System.out.println("NO");
            }
        }
    }

    /**
     * Reads the 4x4 grid from the input stream.
     */
    private static int[][] readGrid(BufferedReader reader) throws IOException {
        int[][] grid = new int[GRID_SIZE][GRID_SIZE];

        for (int i = 0; i < GRID_SIZE; i++) {
            String line = reader.readLine();
            // Safety check for input length
            if (line == null || line.length() < GRID_SIZE) {
                break;
            }

            for (int j = 0; j < GRID_SIZE; j++) {
                char c = line.charAt(j);
                if (c == 'x') {
                    grid[i][j] = PLAYER_X;
                } else if (c == 'o') {
                    grid[i][j] = PLAYER_O;
                } else {
                    grid[i][j] = EMPTY;
                }
            }
        }
        return grid;
    }

    /**
     * Checks if the grid contains a valid winning sequence.
     * A valid sequence is defined as a line of length 3 containing 
     * exactly two 'x's (1) and one empty space (0), in any order.
     * The presence of 'o' (-1) invalidates the sequence.
     */
    private static boolean hasWinningPattern(int[][] grid) {
        // 1. Check Horizontal sequences
        for (int r = 0; r < GRID_SIZE; r++) {
            for (int c = 0; c <= GRID_SIZE - SEQUENCE_LENGTH; c++) {
                if (checkSequence(grid, r, c, 0, 1)) return true;
            }
        }

        // 2. Check Vertical sequences
        for (int c = 0; c < GRID_SIZE; c++) {
            for (int r = 0; r <= GRID_SIZE - SEQUENCE_LENGTH; r++) {
                if (checkSequence(grid, r, c, 1, 0)) return true;
            }
        }

        // 3. Check Main Diagonals (Top-Left to Bottom-Right)
        for (int r = 0; r <= GRID_SIZE - SEQUENCE_LENGTH; r++) {
            for (int c = 0; c <= GRID_SIZE - SEQUENCE_LENGTH; c++) {
                if (checkSequence(grid, r, c, 1, 1)) return true;
            }
        }

        // 4. Check Anti-Diagonals (Top-Right to Bottom-Left)
        for (int r = 0; r <= GRID_SIZE - SEQUENCE_LENGTH; r++) {
            // Start column must allow moving left for SEQUENCE_LENGTH steps
            for (int c = GRID_SIZE - 1; c >= SEQUENCE_LENGTH - 1; c--) {
                if (checkSequence(grid, r, c, 1, -1)) return true;
            }
        }

        return false;
    }

    /**
     * Checks a specific sequence of cells starting at (startRow, startCol)
     * moving in direction (rowStep, colStep).
     */
    private static boolean checkSequence(int[][] grid, int startRow, int startCol, int rowStep, int colStep) {
        int xCount = 0;
        int emptyCount = 0;
        boolean hasO = false;

        for (int i = 0; i < SEQUENCE_LENGTH; i++) {
            int r = startRow + (i * rowStep);
            int c = startCol + (i * colStep);
            int val = grid[r][c];

            if (val == PLAYER_X) {
                xCount++;
            } else if (val == PLAYER_O) {
                hasO = true;
                break; // 'o' breaks the pattern immediately
            } else {
                emptyCount++;
            }
        }

        if (hasO) return false;

        // The original logic checked for strings "110", "011", "101".
        // These correspond to exactly two 1s (x) and one 0 (empty).
        return xCount == 2 && emptyCount == 1;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.OutputStream;
import java.io.PrintWriter;
import java.util.StringTokenizer;

public class Main {

    // Constants for better maintainability and self-documenting code
    private static final int GRID_SIZE = 4;
    private static final char EMPTY_CELL = '.';
    private static final char TARGET_CHAR = 'x';

    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        solve(in, out);
        out.close();
    }

    private static void solve(InputReader in, PrintWriter out) {
        char[][] board = new char[GRID_SIZE][GRID_SIZE];
        for (int i = 0; i < GRID_SIZE; i++) {
            board[i] = in.next().toCharArray();
        }

        // Try placing 'x' in each empty cell and check for a winning condition
        for (int r = 0; r < GRID_SIZE; r++) {
            for (int c = 0; c < GRID_SIZE; c++) {
                if (board[r][c] == EMPTY_CELL) {
                    board[r][c] = TARGET_CHAR;
                    if (hasFourInRow(board)) {
                        out.print("YES");
                        return;
                    }
                    board[r][c] = EMPTY_CELL; // Backtrack to restore the board state
                }
            }
        }

        out.print("NO");
    }

    /**
     * Checks if there are four consecutive TARGET_CHAR cells in any valid direction.
     * Covers: Right, Down, Down-Right, and Down-Left.
     */
    private static boolean hasFourInRow(char[][] board) {
        int size = board.length;
        // Directions represented as [rowDelta, colDelta]
        int[][] directions = {{0, 1}, {1, 0}, {1, 1}, {1, -1}};

        for (int r = 0; r < size; r++) {
            for (int c = 0; c < size; c++) {
                // Optimization: Only start scanning from existing target characters
                if (board[r][c] != TARGET_CHAR) {
                    continue;
                }
                for (int[] dir : directions) {
                    boolean allMatch = true;
                    // Check the next 3 cells in the current direction to form a line of 4
                    for (int step = 1; step < 4; step++) {
                        int nr = r + dir[0] * step;
                        int nc = c + dir[1] * step;

                        // Validate bounds and character match
                        if (nr < 0 || nr >= size || nc < 0 || nc >= size || board[nr][nc] != TARGET_CHAR) {
                            allMatch = false;
                            break;
                        }
                    }
                    if (allMatch) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Fast input reader optimized for competitive programming style tasks.
     */
    static class InputReader {
        public final BufferedReader reader;
        public StringTokenizer tokenizer;

        public InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input", e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }

        public double nextDouble() {
            return Double.parseDouble(next());
        }
    }
}

import java.util.Scanner;

/**
 * Refactored solution to check for a specific 'x' pattern around '.' cells in a 4x4 grid.
 * 
 * Refactoring changes:
 * 1. Renamed class to 'XPatternChecker' for better semantic meaning.
 * 2. Removed custom 'InputReader' and Thread boilerplate. Used standard 'Scanner' 
 *    as the input size is small (4x4), making the code more readable and maintainable.
 * 3. Replaced magic numbers (4) with a constant 'GRID_SIZE'.
 * 4. Replaced the massive block of 'if' statements with a cleaner directional logic 
 *    using arrays for direction vectors.
 * 5. Improved variable naming (e.g., 'grid', 'hasPattern').
 * 6. Added comments to explain the logic.
 */
public class XPatternChecker {

    // Define grid size as a constant
    private static final int GRID_SIZE = 4;

    // Define direction vectors for 8 neighbors (horizontal, vertical, diagonal)
    // dr represents change in row, dc represents change in column
    private static final int[] DR = {-1, -1, -1, 0, 0, 1, 1, 1};
    private static final int[] DC = {-1, 0, 1, -1, 1, -1, 0, 1};

    public static void main(String[] args) {
        // Use Scanner for standard, readable input handling
        Scanner scanner = new Scanner(System.in);
        char[][] grid = new char[GRID_SIZE][GRID_SIZE];

        // Read the 4x4 grid from input
        // The input format is expected to be 4 strings, each containing 4 characters
        for (int i = 0; i < GRID_SIZE; i++) {
            if (scanner.hasNext()) {
                String row = scanner.next();
                grid[i] = row.toCharArray();
            }
        }

        // Check if the specific pattern exists in the grid
        boolean hasPattern = checkForXPattern(grid);

        // Output the result
        System.out.println(hasPattern ? "YES" : "NO");

        scanner.close();
    }

    /**
     * Iterates through the grid to find if there is a '.' cell 
     * that satisfies the 'x' pattern conditions.
     */
    private static boolean checkForXPattern(char[][] grid) {
        for (int r = 0; r < GRID_SIZE; r++) {
            for (int c = 0; c < GRID_SIZE; c++) {
                // We only care about cells that contain a dot
                if (grid[r][c] == '.') {
                    if (isDotSurroundedByX(grid, r, c)) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Checks if a dot at (r, c) has 'x's in a specific configuration.
     * The pattern requires 'x's at distance 1 and 2 in the same direction,
     * OR 'x's at distance 1 in opposite directions.
     */
    private static boolean isDotSurroundedByX(char[][] grid, int r, int c) {
        // Check all 8 directions
        for (int i = 0; i < 8; i++) {
            int dr = DR[i];
            int dc = DC[i];

            // Check the immediate neighbor in this direction (distance 1)
            int r1 = r + dr;
            int c1 = c + dc;

            if (isValid(r1, c1) && grid[r1][c1] == 'x') {
                // Case 1: Two 'x's in the same direction (Sequence: x, x, .)
                // Check neighbor at distance 2
                int r2 = r + 2 * dr;
                int c2 = c + 2 * dc;
                if (isValid(r2, c2) && grid[r2][c2] == 'x') {
                    return true;
                }

                // Case 2: 'x' on both sides (Sequence: x, ., x)
                // Check neighbor in the opposite direction (distance 1)
                int rOpp = r - dr;
                int cOpp = c - dc;
                if (isValid(rOpp, cOpp) && grid[rOpp][cOpp] == 'x') {
                    return true;
                }
            }
        }
        return false;
    }

    /**
     * Helper method to check if coordinates are within the grid bounds.
     */
    private static boolean isValid(int r, int c) {
        return r >= 0 && r < GRID_SIZE && c >= 0 && c < GRID_SIZE;
    }
}

import java.io.BufferedReader;
import java.io.BufferedWriter;
