public class CF390B {
    // Constants to replace magic numbers and improve readability
    private static final int GRID_SIZE = 10;
    private static final int INPUT_OFFSET = 4;
    private static final int CHECK_LENGTH = 3; // Length of the segment to analyze

    // Direction vectors representing the 8 neighbors (Right, Down-Right, Down, Down-Left, Left, Up-Left, Up, Up-Right)
    // These correspond to the hardcoded indices 0-7 in the original logic
    private static final int[] DR = {0, 1, 1, 1, 0, -1, -1, -1};
    private static final int[] DC = {1, 1, 0, -1, -1, -1, 0, 1};

    public static void main(String[] args) throws Exception {
        // Use BufferedReader and BufferedWriter for efficient I/O
        // Removed unused Scanner instantiation from original code
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        BufferedWriter writer = new BufferedWriter(new OutputStreamWriter(System.out));

        // Initialize the grid
        char[][] grid = new char[GRID_SIZE][GRID_SIZE];

        // Read the 4x4 block of input data located at [4..7][4..7]
        for (int r = INPUT_OFFSET; r < INPUT_OFFSET + 4; r++) {
            String line = reader.readLine();
            if (line != null) {
                for (int c = INPUT_OFFSET; c < INPUT_OFFSET + 4; c++) {
                    grid[r][c] = line.charAt(c - INPUT_OFFSET);
                }
            }
        }

        boolean found = false;

        // Iterate over the 4x4 block where the input was read
        // Original loops: ii from 4 to 7, jj from 4 to 7
        for (int r = INPUT_OFFSET; r < INPUT_OFFSET + 4; r++) {
            for (int c = INPUT_OFFSET; c < INPUT_OFFSET + 4; c++) {

                // Optimization: The original logic only processes cells that are 'x'
                if (grid[r][c] == 'x') {

                    // Check all 8 directions
                    for (int d = 0; d < 8; d++) {
                        int xCount = 0;
                        int dotCount = 0;

                        // Check the segment of length 3 in the current direction
                        // Distances 0, 1, 2 from the center (r, c)
                        // This replaces the nested loop structure and array accumulation in the original code
                        for (int dist = 0; dist < CHECK_LENGTH; dist++) {
                            int nr = r + DR[d] * dist;
                            int nc = c + DC[d] * dist;

                            char cell = grid[nr][nc];
                            if (cell == 'x') {
                                xCount++;
                            } else if (cell == '.') {
                                dotCount++;
                            }
                        }

                        // Logic check from original code:
                        // if (xcounter[kk] == 2 && dotcounter[kk] == 1)
                        // This implies looking for a pattern of 2 'x's and 1 '.' in the segment.
                        // Since the center (dist=0) is guaranteed 'x', this checks for patterns like "xx." or "x.x".
                        if (xCount == 2 && dotCount == 1) {
                            found = true;
                        }
                    }
                }
            }
        }

        // Output the result
        writer.write(found ? "YES" : "NO");
        writer.newLine();
        writer.flush();
    }
}

