import java.io.PrintWriter;
import java.util.StringTokenizer;

public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);

        Solver solver = new Solver();
        solver.solve(in, out);

        out.close();
    }

    static class Solver {
        private static final int GRID_SIZE = 4;
        private static final char WIN_CHAR = 'x';

        public void solve(InputReader in, PrintWriter out) {
            char[][] grid = new char[GRID_SIZE][GRID_SIZE];
            // Read the grid. Assuming input format provides 4 strings per row, 
            // or 4 tokens representing the rows.
            for (int i = 0; i < GRID_SIZE; i++) {
                String row = in.next();
                if (row != null) {
                    grid[i] = row.toCharArray();
                }
            }

            // Try placing 'x' in every empty spot to see if it creates a winning line
            for (int r = 0; r < GRID_SIZE; r++) {
                for (int c = 0; c < GRID_SIZE; c++) {
                    if (grid[r][c] == '.') {
                        grid[r][c] = WIN_CHAR;
                        if (hasWinningLine(grid)) {
                            out.println("YES");
                            return;
                        }
                        grid[r][c] = '.'; // Backtrack
                    }
                }
            }
            out.println("NO");
        }

        /**
         * Checks if there is any line of 3 'x's in the grid.
         * Checks rows, columns, and diagonals (including sub-diagonals).
         */
        private boolean hasWinningLine(char[][] grid) {
            // Directions: Horizontal, Vertical, Diagonal, Anti-Diagonal
            int[] dr = {0, 1, 1, 1};
            int[] dc = {1, 0, 1, -1};

            for (int d = 0; d < 4; d++) {
                for (int r = 0; r < GRID_SIZE; r++) {
                    for (int c = 0; c < GRID_SIZE; c++) {
                        // Calculate the position of the 3rd cell in the sequence
                        int r2 = r + 2 * dr[d];
                        int c2 = c + 2 * dc[d];

                        // Check if the 3rd cell is within bounds
                        if (r2 >= 0 && r2 < GRID_SIZE && c2 >= 0 && c2 < GRID_SIZE) {
                            if (grid[r][c] == WIN_CHAR &&
                                grid[r + dr[d]][c + dc[d]] == WIN_CHAR &&
                                grid[r2][c2] == WIN_CHAR) {
                                return true;
                            }
                        }
                    }
                }
            }
            return false;
        }
    }

    static class InputReader {
        public BufferedReader reader;
        public StringTokenizer tokenizer;

        public InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

public class Main {
    // Configuration constants to avoid magic numbers
    private static final int BOARD_SIZE = 4;
    private static final int WIN_SEQUENCE_LENGTH = 3;
    private static final int MAX_ALLOWED_GAPS = 1;

    public static void main(String[] args) {
        // try-with-resources ensures streams are properly closed and flushed
        try (FastScanner scanner = new FastScanner(System.in);
             PrintWriter out = new PrintWriter(System.out)) {

            Board gameBoard = new Board(BOARD_SIZE, WIN_SEQUENCE_LENGTH, MAX_ALLOWED_GAPS);
            int xCount = 0;
            int oCount = 0;

            // Read and validate input grid
            for (int i = 0; i < BOARD_SIZE; i++) {
                String row = scanner.next();
                if (row == null) {
                    throw new IllegalStateException("Unexpected end of input");
                }
                gameBoard.setRow(i, row);

                for (char c : row.toCharArray()) {
                    if (c == 'x') xCount++;
                    else if (c == 'o') oCount++;
                }
            }

            // Apply game rules: check 'x' if counts are equal, otherwise check 'o'
            boolean winnerExists = (xCount == oCount)
                    ? gameBoard.hasWinningSequence('x')
                    : gameBoard.hasWinningSequence('o');

            out.println(winnerExists ? "YES" : "NO");

        } catch (Exception e) {
            // In production, log this exception. For competitive programming, 
            // we can safely ignore or print to stderr.
            System.err.println("Error processing input: " + e.getMessage());
        }
    }

    /**
     * Encapsulates board state and win-condition evaluation logic.
     */
    static class Board {
        private final char[][] grid;
        private final int size;
        private final int winLength;
        private final int maxGaps;

        public Board(int size, int winLength, int maxGaps) {
            this.size = size;
            this.winLength = winLength;
            this.maxGaps = maxGaps;
            this.grid = new char[size][size];
        }

        public void setRow(int rowIndex, String row) {
            if (row.length() != size) {
                throw new IllegalArgumentException(
                        "Row at index " + rowIndex + " has invalid length. Expected " + size);
            }
            grid[rowIndex] = row.toCharArray();
        }

        /**
         * Checks if the specified player has a valid winning sequence on the board.
         */
        public boolean hasWinningSequence(char player) {
            // Direction vectors: [rowDelta, colDelta]
            int[][] directions = {
                {1, 0},   // Vertical
                {0, 1},   // Horizontal
                {1, 1},   // Main Diagonal
                {1, -1}   // Anti-Diagonal
            };

            for (int r = 0; r < size; r++) {
                for (int c = 0; c < size; c++) {
                    for (int[] dir : directions) {
                        if (checkDirection(r, c, dir[0], dir[1], player)) {
                            return true;
                        }
                    }
                }
            }
            return false;
        }

        /**
         * Validates a sequence of length 'winLength' starting from (startR, startC) 
         * in the direction (dr, dc).
         */
        private boolean checkDirection(int startR, int startC, int dr, int dc, char player) {
            int matches = 0;
            int gaps = 0;

            for (int i = 0; i < winLength; i++) {
                int r = startR + dr * i;
                int c = startC + dc * i;

                // Boundary check
                if (r < 0 || r >= size || c < 0 || c >= size) {
                    return false;
                }

                char cell = grid[r][c];
                if (cell == player) {
                    matches++;
                } else if (cell == '.') {
                    gaps++;
                } else {
                    // Encountered a different player's mark or invalid character
                    return false;
                }
            }

            // Valid if all cells are either the player's mark or empty, 
            // with at most 'maxGaps' empty cells
            return (matches + gaps == winLength) && (gaps <= maxGaps);
        }
    }

    /**
     * Fast input reader optimized for competitive programming and performance-critical I/O.
     */
    static class FastScanner implements AutoCloseable {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastScanner(InputStream stream) {
            this.reader = new BufferedReader(new InputStreamReader(stream));
            this.tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input", e);
                }
            }
            return tokenizer.nextToken();
        }

        @Override
        public void close() throws IOException {
            reader.close();
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;

public class Main {
    // Constants for grid dimensions
    private static final int GRID_SIZE = 4;

    // Directions to check: {rowDelta, colDelta}
    // 1. Horizontal (Right)
    // 2. Vertical (Down)
    // 3. Diagonal (Down-Right)
    // 4. Diagonal (Down-Left)
    private static final int[][] DIRECTIONS = {
        {0, 1},
        {1, 0},
        {1, 1},
        {1, -1}
    };

    public static void main(String[] args) throws IOException {
        // Use try-with-resources for automatic resource management
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            char[][] grid = readGrid(br);

            if (hasTargetPattern(grid)) {
                System.out.println("YES");
            } else {
                System.out.println("NO");
            }
        }
    }

    /**
     * Reads the 4x4 grid from standard input.
     */
    private static char[][] readGrid(BufferedReader br) throws IOException {
        char[][] grid = new char[GRID_SIZE][GRID_SIZE];
        for (int i = 0; i < GRID_SIZE; i++) {
            String line = br.readLine();
            if (line != null) {
                grid[i] = line.trim().toCharArray();
            }
        }
        return grid;
    }

    /**
     * Checks if the grid contains the target pattern in any of the 4 directions.
     * The target pattern consists of 3 characters where two are 'x' and one is '.',
     * specifically: ".xx", "x.x", or "xx.".
     */
    private static boolean hasTargetPattern(char[][] grid) {
        for (int r = 0; r < GRID_SIZE; r++) {
            for (int c = 0; c < GRID_SIZE; c++) {
                for (int[] dir : DIRECTIONS) {
                    if (checkSequence(grid, r, c, dir[0], dir[1])) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Checks a sequence of 3 characters starting at (r, c) in direction (dr, dc).
     */
    private static boolean checkSequence(char[][] grid, int r, int c, int dr, int dc) {
        // Calculate indices for the 3rd character
        int r2 = r + 2 * dr;
        int c2 = c + 2 * dc;

        // Check bounds for the 3rd character. 
        // If the 3rd char is out of bounds, the sequence is invalid.
        if (r2 < 0 || r2 >= GRID_SIZE || c2 < 0 || c2 >= GRID_SIZE) {
            return false;
        }

        char char1 = grid[r][c];
        char char2 = grid[r + dr][c + dc];
        char char3 = grid[r2][c2];

        return matchesPattern(char1, char2, char3);
    }

    /**
     * Determines if the three characters match the specific patterns:
     * ".xx", "x.x", or "xx."
     */
    private static boolean matchesPattern(char a, char b, char c) {
        return (a == '.' && b == 'x' && c == 'x') ||
               (a == 'x' && b == '.' && c == 'x') ||
               (a == 'x' && b == 'x' && c == '.');
    }
}

