import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;

public class Main {
    private static final int BOARD_SIZE = 4;
    private static final int WIN_LENGTH = 3;

    public static void main(String[] args) throws IOException {
        // Use try-with-resources for automatic and safe resource cleanup
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
             PrintWriter out = new PrintWriter(System.out)) {

            // Original code hardcoded t=1 and looped once. Preserving behavior cleanly.
            int testCases = 1;
            for (int t = 0; t < testCases; t++) {
                char[][] board = readBoard(reader);
                boolean hasWin = checkWinningCondition(board);
                out.println(hasWin ? "YES" : "NO");
            }
            out.flush();
        }
    }

    /**
     * Reads a 4x4 character grid from the input.
     */
    private static char[][] readBoard(BufferedReader reader) throws IOException {
        char[][] board = new char[BOARD_SIZE][BOARD_SIZE];
        for (int i = 0; i < BOARD_SIZE; i++) {
            String line = reader.readLine();
            if (line == null) {
                throw new IOException("Unexpected end of input while reading board row " + i);
            }
            board[i] = line.trim().toCharArray();
        }
        return board;
    }

    /**
     * Checks all possible lines of length WIN_LENGTH on the board.
     * Returns true if any line satisfies the winning condition.
     */
    private static boolean checkWinningCondition(char[][] board) {
        // Check all horizontal lines
        for (int row = 0; row < BOARD_SIZE; row++) {
            for (int col = 0; col <= BOARD_SIZE - WIN_LENGTH; col++) {
                if (isWinningLine(board, row, col, 0, 1)) {
                    return true;
                }
            }
        }

        // Check all vertical lines
        for (int col = 0; col < BOARD_SIZE; col++) {
            for (int row = 0; row <= BOARD_SIZE - WIN_LENGTH; row++) {
                if (isWinningLine(board, row, col, 1, 0)) {
                    return true;
                }
            }
        }

        // Check all main diagonals (top-left to bottom-right)
        for (int row = 0; row <= BOARD_SIZE - WIN_LENGTH; row++) {
            for (int col = 0; col <= BOARD_SIZE - WIN_LENGTH; col++) {
                if (isWinningLine(board, row, col, 1, 1)) {
                    return true;
                }
            }
        }

        // Check all anti-diagonals (top-right to bottom-left)
        for (int row = 0; row <= BOARD_SIZE - WIN_LENGTH; row++) {
            for (int col = WIN_LENGTH - 1; col < BOARD_SIZE; col++) {
                if (isWinningLine(board, row, col, 1, -1)) {
                    return true;
                }
            }
        }

        return false;
    }

    /**
     * Evaluates a sequence of cells starting at (startRow, startCol)
     * with the given row and column deltas.
     * 
     * Winning condition: exactly 3 'x's, or 2 'x's and 0 'o's.
     */
    private static boolean isWinningLine(char[][] board, int startRow, int startCol, 
                                         int deltaRow, int deltaCol) {
        int xCount = 0;
        int oCount = 0;

        for (int i = 0; i < WIN_LENGTH; i++) {
            char cell = board[startRow + i * deltaRow][startCol + i * deltaCol];
            if (cell == 'x') {
                xCount++;
            } else if (cell == 'o') {
                oCount++;
            }
        }

        return xCount == 3 || (xCount == 2 && oCount == 0);
    }
}

import java.io.*;
import java.util.NoSuchElementException;
import java.util.StringTokenizer;

public class Main {
    private static final int GRID_SIZE = 4;
    // Directions: Right, Down, Diagonal Down-Right, Diagonal Down-Left
    private static final int[] DX = {1, 0, 1, 1};
    private static final int[] DY = {0, 1, 1, -1};

    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        OutputWriter out = new OutputWriter(outputStream);

        TaskB solver = new TaskB();
        solver.solve(in, out);
        out.close();
    }

    static class TaskB {
        public void solve(InputReader in, OutputWriter out) {
            char[][] grid = new char[GRID_SIZE][];
            int countX = 0;
            int countO = 0;

            for (int i = 0; i < GRID_SIZE; i++) {
                grid[i] = in.nextChars();
                countX += count(grid[i], 'x');
                countO += count(grid[i], 'o');
            }

            char currentPlayer = (countX == countO) ? 'x' : 'o';

            for (int i = 0; i < GRID_SIZE; i++) {
                for (int j = 0; j < GRID_SIZE; j++) {
                    if (grid[i][j] == '.') {
                        if (canWin(grid, i, j, currentPlayer)) {
                            out.println("YES");
                            return;
                        }
                    }
                }
            }
            out.println("NO");
        }

        /**
         * Counts occurrences of a target character in a char array.
         */
        private int count(char[] chars, char target) {
            int count = 0;
            for (char c : chars) {
                if (c == target) {
                    count++;
                }
            }
            return count;
        }

        /**
         * Checks if placing 'player' at (x, y) creates a line of 3 or more consecutive pieces.
         */
        private boolean canWin(char[][] grid, int x, int y, char player) {
            for (int k = 0; k < DX.length; k++) {
                int consecutiveCount = 1; // Start with the placed piece

                // Expand in both directions along the current axis
                for (int direction = -1; direction <= 1; direction += 2) {
                    for (int i = x + direction * DX[k], j = y + direction * DY[k];
                         i >= 0 && i < GRID_SIZE && j >= 0 && j < GRID_SIZE;
                         i += direction * DX[k], j += direction * DY[k]) {

                        if (grid[i][j] == player) {
                            consecutiveCount++;
                        } else {
                            break;
                        }
                    }
                }

                if (consecutiveCount >= 3) {
                    return true;
                }
            }
            return false;
        }
    }

    /**
     * Fast input reader for competitive programming.
     */
    static class InputReader {
        public final BufferedReader reader;
        public StringTokenizer tokenizer = null;

        public InputReader(InputStream inputStream) {
            this.reader = new BufferedReader(new InputStreamReader(inputStream), 32767);
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) throw new NoSuchElementException();
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public char[] nextChars() {
            return next().toCharArray();
        }
    }

    /**
     * Fast output writer for competitive programming.
     */
    static class OutputWriter {
        private final PrintWriter writer;

        public OutputWriter(OutputStream outputStream) {
            this.writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(outputStream), 32767), true);
        }

        public OutputWriter println(String string) {
            writer.println(string);
            return this;
        }

        public void close() {
            writer.close();
        }
    }
}

import java.util.Scanner;

/**
 * Evaluates a 4x4 Tic-Tac-Toe board to determine if player 'x' can win in a single move.
 */
public class IllyaTicTacToe {
    private static final int BOARD_SIZE = 4;
    private static final int WIN_LENGTH = 3;
    private static final char EMPTY = '.';
    private static final char PLAYER = 'x';

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            char[][] board = new char[BOARD_SIZE][BOARD_SIZE];
            for (int i = 0; i < BOARD_SIZE; i++) {
                String row = scanner.next();
                board[i] = row.toCharArray();
            }

            boolean canWin = false;
            for (int r = 0; r < BOARD_SIZE; r++) {
                for (int c = 0; c < BOARD_SIZE; c++) {
                    if (board[r][c] == EMPTY) {
                        board[r][c] = PLAYER; // Simulate placing 'x'
                        if (isWinningMove(board, r, c)) {
                            canWin = true;
                        }
                        board[r][c] = EMPTY; // Backtrack to restore board state
                        if (canWin) break;
                    }
                }
                if (canWin) break;
            }

            System.out.println(canWin ? "YES" : "NO");
        }
    }

    /**
     * Checks if placing the player's mark at (r, c) completes a winning line.
     *
     * @param board The current game board
     * @param r     Row coordinate of the simulated move
     * @param c     Column coordinate of the simulated move
     * @return true if the move results in a win, false otherwise
     */
    private static boolean isWinningMove(char[][] board, int r, int c) {
        int[][] directions = {{0, 1}, {1, 0}, {1, 1}, {1, -1}}; // Horizontal, Vertical, Main Diagonal, Anti-Diagonal

        for (int[] dir : directions) {
            int count = 1; // Start with the placed mark

            // Check positive direction
            for (int i = 1; i < WIN_LENGTH; i++) {
                int nr = r + dir[0] * i;
                int nc = c + dir[1] * i;
                if (isValid(nr, nc) && board[nr][nc] == PLAYER) {
                    count++;
                } else {
                    break;
                }
            }

            // Check negative direction
            for (int i = 1; i < WIN_LENGTH; i++) {
                int nr = r - dir[0] * i;
                int nc = c - dir[1] * i;
                if (isValid(nr, nc) && board[nr][nc] == PLAYER) {
                    count++;
                } else {
                    break;
                }
            }

            if (count >= WIN_LENGTH) {
                return true;
            }
        }
        return false;
    }

    /**
     * Validates whether the given coordinates are within the board boundaries.
     *
     * @param r Row coordinate
     * @param c Column coordinate
     * @return true if coordinates are valid, false otherwise
     */
    private static boolean isValid(int r, int c) {
        return r >= 0 && r < BOARD_SIZE && c >= 0 && c < BOARD_SIZE;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

public class TinkoffB {
    // Named constants replace magic numbers for clarity
    private static final int EMPTY = 0;
    private static final int OBSTACLE = -1;
    private static final int START_RANGE = 1;
    private static final int TARGET_RANGE = 2;

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner();
        int rows = scanner.nextInt();
        int cols = scanner.nextInt();

        int[][] grid = new int[rows][cols];
        int startRow = -1, startCol = -1;
        int targetRow = -1, targetCol = -1;

        // Parse input grid
        for (int r = 0; r < rows; r++) {
            String line = scanner.next();
            for (int c = 0; c < cols; c++) {
                char ch = line.charAt(c);
                switch (ch) {
                    case '.': grid[r][c] = EMPTY; break;
                    case '*': grid[r][c] = OBSTACLE; break;
                    case 'S': grid[r][c] = START_RANGE; startRow = r; startCol = c; break;
                    case 'T': grid[r][c] = TARGET_RANGE; targetRow = r; targetCol = c; break;
                }
            }
        }

        // Mark visible ranges from Start and Target positions
        markRange(grid, startRow, startCol, START_RANGE, rows, cols);
        markRange(grid, targetRow, targetCol, TARGET_RANGE, rows, cols);

        // Check if ranges intersect within the same row or column
        boolean intersects = checkIntersection(grid, rows, cols);
        System.out.println(intersects ? "YES" : "NO");
    }

    /**
     * Marks horizontal and vertical ranges from a given position until an obstacle or boundary is reached.
     */
    private static void markRange(int[][] grid, int r, int c, int rangeType, int rows, int cols) {
        // Mark right
        for (int dc = 0; dc < cols && c + dc < cols && grid[r][c + dc] != OBSTACLE; dc++) {
            grid[r][c + dc] = rangeType;
        }
        // Mark left
        for (int dc = 1; dc < cols && c - dc >= 0 && grid[r][c - dc] != OBSTACLE; dc++) {
            grid[r][c - dc] = rangeType;
        }
        // Mark down
        for (int dr = 0; dr < rows && r + dr < rows && grid[r + dr][c] != OBSTACLE; dr++) {
            grid[r + dr][c] = rangeType;
        }
        // Mark up
        for (int dr = 1; dr < rows && r - dr >= 0 && grid[r - dr][c] != OBSTACLE; dr++) {
            grid[r - dr][c] = rangeType;
        }
    }

    /**
     * Checks if any row or column contains both START_RANGE and TARGET_RANGE 
     * without an obstacle blocking line-of-sight.
     */
    private static boolean checkIntersection(int[][] grid, int rows, int cols) {
        // Check each row
        for (int r = 0; r < rows; r++) {
            if (checkLine(grid, r, true)) return true;
        }
        // Check each column
        for (int c = 0; c < cols; c++) {
            if (checkLine(grid, c, false)) return true;
        }
        return false;
    }

    /**
     * Validates a single row or column for intersecting ranges.
     */
    private static boolean checkLine(int[][] grid, int index, boolean isRow) {
        boolean hasStart = false;
        boolean hasTarget = false;
        int limit = isRow ? grid[0].length : grid.length;

        for (int i = 0; i < limit; i++) {
            int val = isRow ? grid[index][i] : grid[i][index];

            if (val == START_RANGE) {
                hasStart = true;
            } else if (val == TARGET_RANGE) {
                hasTarget = true;
            } else if (val == OBSTACLE) {
                // Obstacle breaks line-of-sight
                if (hasStart && hasTarget) return true;
                hasStart = false;
                hasTarget = false;
            }
        }
        return hasStart && hasTarget;
    }

    /**
     * Optimized input scanner for competitive programming.
     */
    public static class FastScanner {
        BufferedReader br;
        StringTokenizer st;

        public FastScanner() {
            this(new InputStreamReader(System.in));
        }

        public FastScanner(java.io.Reader in) {
            br = new BufferedReader(in);
        }

        String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        long nextLong() {
            return Long.parseLong(next());
        }

        double nextDouble() {
            return Double.parseDouble(next());
        }
    }
}

import java.util.Scanner;

public class ProblemB {
    // Direction vectors: Up, Down, Left, Right
    private static final int[] DX = {-1, 1, 0, 0};
    private static final int[] DY = {0, 0, -1, 1};

    public static void main(String[] args) {
        // Use try-with-resources to ensure Scanner is properly closed
        try (Scanner sc = new Scanner(System.in)) {
            if (!sc.hasNextInt()) {
                return;
            }
            int height = sc.nextInt();
            int width = sc.nextInt();

            char[][] board = new char[height][width];
            int startX = -1, startY = -1;
            int targetX = -1, targetY = -1;

            // Parse the grid and locate start/target positions
            for (int i = 0; i < height; i++) {
                String line = sc.next();
                for (int j = 0; j < width; j++) {
                    board[i][j] = line.charAt(j);
                    if (board[i][j] == 'S') {
                        startX = i;
                        startY = j;
                    } else if (board[i][j] == 'T') {
                        targetX = i;
                        targetY = j;
                    }
                }
            }

            // Visited array to prevent infinite recursion in cycles
            boolean[][] visited = new boolean[height][width];
            boolean canReach = false;

            // Attempt to move in all 4 cardinal directions from the start position
            for (int i = 0; i < 4; i++) {
                int nextX = startX + DX[i];
                int nextY = startY + DY[i];
                if (canReachTarget(board, nextX, nextY, DX[i], DY[i], 2, targetX, targetY, visited)) {
                    canReach = true;
                    break;
                }
            }

            System.out.println(canReach ? "YES" : "NO");
        }
    }

    /**
     * Recursively searches for a path to the target with at most the given number of turns.
     *
     * @param board       The grid map
     * @param x           Current x-coordinate
     * @param y           Current y-coordinate
     * @param prevDirX    X-component of the previous movement direction
     * @param prevDirY    Y-component of the previous movement direction
     * @param turnsLeft   Remaining allowed turns
     * @param targetX     Target x-coordinate
     * @param targetY     Target y-coordinate
     * @param visited     Tracks visited cells to prevent cycles
     * @return true if target is reachable, false otherwise
     */
    private static boolean canReachTarget(char[][] board, int x, int y, int prevDirX, int prevDirY,
                                          int turnsLeft, int targetX, int targetY, boolean[][] visited) {
        // Boundary check
        if (x < 0 || x >= board.length || y < 0 || y >= board[0].length) {
            return false;
        }

        // Target reached
        if (board[x][y] == 'T') {
            return true;
        }

        // Obstacle or already visited cell
        if (board[x][y] == '*' || visited[x][y]) {
            return false;
        }

        // Mark current cell as visited
        visited[x][y] = true;

        if (turnsLeft > 0) {
            // Try moving in all 4 directions
            for (int i = 0; i < 4; i++) {
                int nextX = x + DX[i];
                int nextY = y + DY[i];

                // If moving in the same direction, turns remain the same.
                // Otherwise, we use one turn.
                int newTurns = (prevDirX == DX[i] && prevDirY == DY[i]) ? turnsLeft : turnsLeft - 1;

                if (canReachTarget(board, nextX, nextY, DX[i], DY[i], newTurns, targetX, targetY, visited)) {
                    visited[x][y] = false; // Backtrack
                    return true;
                }
            }
        } else {
            // No turns left: must reach target in a straight line
            boolean straightLineClear = true;

            if (prevDirX != 0) { // Moving vertically
                if (y == targetY) {
                    int step = prevDirX;
                    for (int cx = x + step; cx != targetX; cx += step) {
                        if (board[cx][y] == '*') {
                            straightLineClear = false;
                            break;
                        }
                    }
                    if (straightLineClear && board[targetX][y] == 'T') {
                        visited[x][y] = false;
                        return true;
                    }
                }
            } else { // Moving horizontally
                if (x == targetX) {
                    int step = prevDirY;
                    for (int cy = y + step; cy != targetY; cy += step) {
                        if (board[x][cy] == '*') {
                            straightLineClear = false;
                            break;
                        }
                    }
                    if (straightLineClear && board[x][targetY] == 'T') {
                        visited[x][y] = false;
                        return true;
                    }
                }
            }
        }

        // Backtrack: unmark current cell
        visited[x][y] = false;
        return false;
    }
}

import java.io.*;
import java.util.*;

public class Solution implements Runnable {

    // Direction vectors: Up, Right, Down, Left
    private static final int[][] DIRECTIONS = {{-1, 0}, {0, 1}, {1, 0}, {0, -1}};
    private static final int MAX_TURNS = 2;

    private final FastScanner in;
    private final PrintStream out;

    /**
     * Main solving method. Reads input, processes the grid, and outputs the result.
     */
    public void solve() throws IOException {
        long startTime = System.currentTimeMillis();

        int n = in.nextInt();
        int m = in.nextInt();
        char[][] grid = new char[n][m];
        int startR = -1, startC = -1;
        int targetR = -1, targetC = -1;

        for (int i = 0; i < n; i++) {
            String row = in.next();
            grid[i] = row.toCharArray();
            for (int j = 0; j < m; j++) {
                char c = grid[i][j];
                if (c == 'S') {
                    startR = i;
                    startC = j;
                } else if (c == 'T') {
                    targetR = i;
                    targetC = j;
                } else if (c != '*') {
                    throw new IllegalArgumentException("Invalid character in grid: " + c);
                }
            }
        }

        boolean canReach = canReachTarget(grid, startR, startC, targetR, targetC);
        out.println(canReach ? "YES" : "NO");

        System.err.println("Time: " + (System.currentTimeMillis() - startTime) + " ms");
    }

    /**
     * Determines if the target 'T' is reachable from 'S' with at most MAX_TURNS direction changes.
     * Uses iterative DFS with state tracking (row, col, turns, lastDirection).
     */
    private boolean canReachTarget(char[][] grid, int startR, int startC, int targetR, int targetC) {
        int n = grid.length;
        int m = grid[0].length;

        // visited[turns][directionIndex][row][col]
        boolean[][][][] visited = new boolean[MAX_TURNS + 1][DIRECTIONS.length][n][m];
        Deque<State> stack = new ArrayDeque<>();

        // Initialize with all possible starting directions
        for (int d = 0; d < DIRECTIONS.length; d++) {
            stack.push(new State(startR, startC, 0, d));
            visited[0][d][startR][startC] = true;
        }

        while (!stack.isEmpty()) {
            State current = stack.pop();
            int r = current.r;
            int c = current.c;
            int turns = current.turns;
            int lastDir = current.lastDir;

            if (r == targetR && c == targetC) {
                return true;
            }

            // 1. Continue moving in the same direction (no extra turn)
            int nextR = r + DIRECTIONS[lastDir][0];
            int nextC = c + DIRECTIONS[lastDir][1];
            if (isValidPosition(nextR, nextC, n, m, grid) && !visited[turns][lastDir][nextR][nextC]) {
                visited[turns][lastDir][nextR][nextC] = true;
                stack.push(new State(nextR, nextC, turns, lastDir));
            }

            // 2. Change direction (increment turn count)
            if (turns < MAX_TURNS) {
                for (int d = 0; d < DIRECTIONS.length; d++) {
                    nextR = r + DIRECTIONS[d][0];
                    nextC = c + DIRECTIONS[d][1];
                    if (isValidPosition(nextR, nextC, n, m, grid) && !visited[turns + 1][d][nextR][nextC]) {
                        visited[turns + 1][d][nextR][nextC] = true;
                        stack.push(new State(nextR, nextC, turns + 1, d));
                    }
                }
            }
        }

        return false;
    }

    private boolean isValidPosition(int r, int c, int n, int m, char[][] grid) {
        return r >= 0 && r < n && c >= 0 && c < m && grid[r][c] != '*';
    }

    /**
     * Represents a traversal state in the grid.
     */
    private static class State {
        final int r, c, turns, lastDir;

        State(int r, int c, int turns, int lastDir) {
            this.r = r;
            this.c = c;
            this.turns = turns;
            this.lastDir = lastDir;
        }
    }

    /**
     * Fast I/O helper class to replace manual BufferedReader/StringTokenizer management.
     */
    private static class FastScanner {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastScanner(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
            tokenizer = new StringTokenizer("");
        }

        public String next() throws IOException {
            while (!tokenizer.hasMoreTokens()) {
                String line = reader.readLine();
                if (line == null) {
                    return null;
                }
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            String s = next();
            if (s == null) throw new IOException("Unexpected end of input");
            return Integer.parseInt(s);
        }

        public long nextLong() throws IOException {
            String s = next();
            if (s == null) throw new IOException("Unexpected end of input");
            return Long.parseLong(s);
        }

        public double nextDouble() throws IOException {
            String s = next();
            if (s == null) throw new IOException("Unexpected end of input");
            return Double.parseDouble(s);
        }
    }

    // Public API compatibility methods
    public double nextDouble() throws IOException { return in.nextDouble(); }
    public long nextLong() throws IOException { return in.nextLong(); }
    public int nextInt() throws IOException { return in.nextInt(); }
    public String next() throws IOException { return in.next(); }

    public Solution(String inputFileName) throws IOException {
        Locale.setDefault(Locale.US);
        if (inputFileName == null) {
            in = new FastScanner(System.in);
            out = new PrintStream(new BufferedOutputStream(System.out));
        } else {
            in = new FastScanner(new FileInputStream(inputFileName + ".in"));
            out = new PrintStream(new BufferedOutputStream(new FileOutputStream(inputFileName + ".out")));
        }
    }

    @Override
    public void run() {
        try {
            solve();
        } catch (Exception e) {
            out.println("Error: " + e.getMessage());
            e.printStackTrace();
        } finally {
            out.flush();
            out.close();
        }
    }

    public static void main(String[] args) throws IOException {
        // Running in a separate thread is a common competitive programming trick
        // to increase the default stack size.
        Thread thread = new Thread(new Solution(null), "SolutionThread");
        thread.setUncaughtExceptionHandler((t, e) -> {
            System.err.println("Uncaught exception in " + t.getName() + ": " + e.getMessage());
            e.printStackTrace();
        });
        thread.start();
    }
}

import java.io.*;
import java.util.*;

/**
 * Solves a grid pathfinding problem by checking reachability from 'S' or 'T'.
 * Refactored for maintainability, performance, and adherence to Java best practices.
 */
public class GridPathSolver {

    // Constants replace magic characters/numbers for clarity
    private static final char STATE_EMPTY = '0';
    private static final char STATE_VISITED = '1';
    private static final char STATE_MARKED = '2';
    private static final char STATE_BLOCKED = '*';
    private static final char START = 'S';
    private static final char TARGET = 'T';

    public static void main(String[] args) {
        // try-with-resources ensures proper cleanup of I/O streams
        try (FastScanner sc = new FastScanner(System.in);
             PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out))) {

            int rows = sc.nextInt();
            int cols = sc.nextInt();
            // Consume the newline character left after reading integers
            sc.nextLine();

            char[][] grid = new char[rows][cols];
            int startRow = -1, startCol = -1;
            int targetRow = -1, targetCol = -1;

            // Read grid and locate start/target positions in a single pass
            for (int i = 0; i < rows; i++) {
                String line = sc.nextLine();
                grid[i] = line.toCharArray();
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j] == START) {
                        startRow = i;
                        startCol = j;
                    } else if (grid[i][j] == TARGET) {
                        targetRow = i;
                        targetCol = j;
                    }
                }
            }

            boolean possible = false;

            // Check path starting from 'S'
            if (startRow != -1 && startCol != -1) {
                if (traverseAndMark(grid, startRow, startCol, (char) 0, false, out)) {
                    possible = true;
                }
            }

            // Check path starting from 'T' (original fill2 logic)
            if (!possible && targetRow != -1 && targetCol != -1) {
                if (traverseAndMark(grid, targetRow, targetCol, (char) 2, true, out)) {
                    possible = true;
                }
            }

            out.println(possible ? "YES" : "NO");

        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    /**
     * Traverses the grid in all four cardinal directions from the given position.
     * Marks cells and checks for a target or reachability condition.
     *
     * @param grid            The 2D character grid
     * @param r               Starting row index
     * @param c               Starting column index
     * @param value           Character value to mark cells with
     * @param checkReachable  If true, treats cells <= '1' as success; otherwise searches for 'T'
     * @param out             Output writer (unused here but preserved for potential logging)
     * @return true if the condition is met, false otherwise
     */
    private static boolean traverseAndMark(char[][] grid, int r, int c, char value,
                                           boolean checkReachable, PrintWriter out) {
        // Direction vectors: Down, Up, Right, Left
        int[][] directions = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};

        for (int[] dir : directions) {
            int dr = dir[0];
            int dc = dir[1];
            int currR = r;
            int currC = c;

            while (currR >= 0 && currR < grid.length && currC >= 0 && currC < grid[0].length) {
                char currentCell = grid[currR][currC];

                // Check termination condition based on traversal type
                if (checkReachable) {
                    if (currentCell <= STATE_VISITED) {
                        return true;
                    }
                } else {
                    if (currentCell == TARGET) {
                        return true;
                    }
                }

                // Stop traversal at blocked cells
                if (currentCell == STATE_BLOCKED) {
                    break;
                }

                // Preserve original recursive branching behavior
                if (value == (char) 0 && currentCell == STATE_EMPTY) {
                    traverseAndMark(grid, currR, currC, STATE_VISITED, checkReachable, out);
                }

                // Mark cell if it exceeds the threshold
                if (currentCell > '3') {
                    grid[currR][currC] = value;
                }

                // Advance to next cell in the current direction
                currR += dr;
                currC += dc;
            }
        }
        return false;
    }

    /**
     * Prints the grid state for debugging purposes.
     * Fixed inner loop bound bug (was c.length instead of c[i].length).
     */
    public static void printGrid(char[][] grid) {
        System.out.println();
        for (int i = 0; i < grid.length; i++) {
            for (int j = 0; j < grid[i].length; j++) {
                char cell = grid[i][j];
                if (cell == STATE_EMPTY) {
                    System.out.print(0);
                } else if (cell == STATE_VISITED) {
                    System.out.print(1);
                } else if (cell == STATE_MARKED) {
                    System.out.print(2);
                } else {
                    System.out.print(cell);
                }
            }
            System.out.println();
        }
    }

    /**
     * Fast I/O scanner optimized for competitive programming and bulk input.
     */
    public static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner(InputStream in) {
            this.br = new BufferedReader(new InputStreamReader(in));
        }

        public String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) {
                        throw new EOFException("End of input stream");
                    }
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }

        public double nextDouble() {
            return Double.parseDouble(next());
        }

        public String nextLine() {
            try {
                return br.readLine();
            } catch (IOException e) {
                throw new UncheckedIOException(e);
            }
        }
    }
}

import java.io.*;
import java.util.Arrays;
import java.util.StringTokenizer;

public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);

        GridSolver solver = new GridSolver();
        solver.solve(in, out);

        out.close();
    }

    static class GridSolver {
        // Use half of MAX_VALUE to prevent overflow when adding two distances
        private static final int DISTANCE_INF = Integer.MAX_VALUE / 2;

        public void solve(InputReader in, PrintWriter out) {
            int n = in.nextInt();
            int m = in.nextInt();
            String[] grid = new String[n];
            for (int i = 0; i < n; i++) {
                grid[i] = in.next();
            }

            int[][] tDistances = new int[n][m];
            int[][] sDistances = new int[n][m];

            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    char cell = grid[i].charAt(j);
                    if (cell == 'S') {
                        calculateAxisDistances(grid, sDistances, i, j);
                    } else if (cell == 'T') {
                        calculateManhattanDistances(grid, tDistances, i, j);
                    }
                }
            }

            long minTotalDistance = DISTANCE_INF;
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    long currentDistance = (long) tDistances[i][j] + (long) sDistances[i][j];
                    if (currentDistance < minTotalDistance) {
                        minTotalDistance = currentDistance;
                    }
                }
            }

            if (minTotalDistance >= DISTANCE_INF) {
                out.println("NO");
            } else {
                out.println("YES");
            }
        }

        /**
         * Calculates distances for 'T' cells. Fills Manhattan distance (cross pattern)
         * stopping at obstacles ('*').
         */
        private void calculateManhattanDistances(String[] grid, int[][] dist, int r, int c) {
            int n = grid.length;
            int m = grid[0].length();
            for (int i = 0; i < n; i++) {
                Arrays.fill(dist[i], DISTANCE_INF);
            }
            dist[r][c] = 0;

            // Down
            for (int i = 1; i + r < n; i++) {
                if (grid[i + r].charAt(c) == '*') break;
                dist[i + r][c] = i;
                fillHorizontal(grid, dist, i + r, c, i);
            }
            // Up
            for (int i = 1; i <= r; i++) {
                if (grid[r - i].charAt(c) == '*') break;
                dist[r - i][c] = i;
                fillHorizontal(grid, dist, r - i, c, i);
            }
            // Right
            for (int i = 1; i + c < grid[0].length(); i++) {
                if (grid[r].charAt(c + i) == '*') break;
                dist[r][c + i] = i;
                fillVertical(grid, dist, r, c + i, i);
            }
            // Left
            for (int i = 1; i <= c; i++) {
                if (grid[r].charAt(c - i) == '*') break;
                dist[r][c - i] = i;
                fillVertical(grid, dist, r, c - i, i);
            }
        }

        /**
         * Calculates distances for 'S' cells. Fills only straight line distances
         * stopping at obstacles ('*').
         */
        private void calculateAxisDistances(String[] grid, int[][] dist, int r, int c) {
            int n = grid.length;
            int m = grid[0].length();
            for (int i = 0; i < n; i++) {
                Arrays.fill(dist[i], DISTANCE_INF);
            }
            dist[r][c] = 0;

            // Down
            for (int i = 1; i + r < n; i++) {
                if (grid[i + r].charAt(c) == '*') break;
                dist[i + r][c] = i;
            }
            // Up
            for (int i = 1; i <= r; i++) {
                if (grid[r - i].charAt(c) == '*') break;
                dist[r - i][c] = i;
            }
            // Right
            for (int i = 1; i + c < grid[0].length(); i++) {
                if (grid[r].charAt(c + i) == '*') break;
                dist[r][c + i] = i;
            }
            // Left
            for (int i = 1; i <= c; i++) {
                if (grid[r].charAt(c - i) == '*') break;
                dist[r][c - i] = i;
            }
        }

        private void fillHorizontal(String[] grid, int[][] dist, int row, int centerCol, int baseDist) {
            int m = grid[0].length();
            // Right
            for (int j = 1; centerCol + j < m; j++) {
                if (grid[row].charAt(centerCol + j) == '*') break;
                dist[row][centerCol + j] = baseDist + j;
            }
            // Left
            for (int j = 1; j <= centerCol; j++) {
                if (grid[row].charAt(centerCol - j) == '*') break;
                dist[row][centerCol - j] = baseDist + j;
            }
        }

        private void fillVertical(String[] grid, int[][] dist, int centerRow, int col, int baseDist) {
            int n = grid.length;
            // Down
            for (int j = 1; centerRow + j < n; j++) {
                if (grid[centerRow + j].charAt(col) == '*') break;
                dist[centerRow + j][col] = baseDist + j;
            }
            // Up
            for (int j = 1; j <= centerRow; j++) {
                if (grid[centerRow - j].charAt(col) == '*') break;
                dist[centerRow - j][col] = baseDist + j;
            }
        }
    }

    static class InputReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String nextLine() {
            try {
                return reader.readLine();
            } catch (IOException e) {
                throw new RuntimeException(e);
            }
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                tokenizer = new StringTokenizer(nextLine());
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayDeque;
import java.util.Arrays;
import java.util.Queue;
import java.util.StringTokenizer;

public class Main {
    // Direction constants mapped to array indices
    private static final int UP = 0, RIGHT = 1, DOWN = 2, LEFT = 3;
    // Row and column offsets corresponding to UP, RIGHT, DOWN, LEFT
    private static final int[] DR = {-1, 0, 1, 0};
    private static final int[] DC = {0, 1, 0, -1};
    private static final int MAX_TURNS = 2;

    public static void main(String[] args) throws IOException {
        solve();
    }

    private static void solve() throws IOException {
        // Localized I/O to avoid static state pollution
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line = br.readLine();
        if (line == null || line.trim().isEmpty()) return;

        StringTokenizer st = new StringTokenizer(line);
        int n = Integer.parseInt(st.nextToken());
        int m = Integer.parseInt(st.nextToken());

        char[][] grid = new char[n][m];
        int startRow = 0, startCol = 0;

        for (int i = 0; i < n; i++) {
            String rowLine = br.readLine();
            for (int j = 0; j < m; j++) {
                grid[i][j] = rowLine.charAt(j);
                if (grid[i][j] == 'S') {
                    startRow = i;
                    startCol = j;
                }
            }
        }

        // BFS initialization: start in all 4 directions with 0 turns
        Queue<State> queue = new ArrayDeque<>();
        for (int d = 0; d < 4; d++) {
            queue.offer(new State(startRow, startCol, d, 0));
        }

        // DP array stores the minimum turns to reach each cell in a specific direction
        int[][][] minTurns = new int[n][m][4];
        for (int[][] row : minTurns) {
            for (int[] cell : row) {
                Arrays.fill(cell, Integer.MAX_VALUE);
            }
        }

        boolean found = false;

        while (!queue.isEmpty()) {
            State current = queue.poll();

            // Prune invalid states: exceeded turn limit or hit a wall
            if (current.turns > MAX_TURNS || grid[current.row][current.col] == '*') {
                continue;
            }

            // Skip if we've already found a path to this state with fewer or equal turns
            if (minTurns[current.row][current.col][current.dir] <= current.turns) {
                continue;
            }
            minTurns[current.row][current.col][current.dir] = current.turns;

            // Check if target has been reached
            if (grid[current.row][current.col] == 'T') {
                found = true;
                break;
            }

            // Explore all 4 directions
            for (int nextDir = 0; nextDir < 4; nextDir++) {
                int turnCost = (current.dir == nextDir) ? 0 : 1;
                int newTurns = current.turns + turnCost;

                if (newTurns > MAX_TURNS) continue;

                int newRow = current.row + DR[nextDir];
                int newCol = current.col + DC[nextDir];

                // Check bounds and if this path offers a better turn count
                if (newRow >= 0 && newRow < n && newCol >= 0 && newCol < m) {
                    if (minTurns[newRow][newCol][nextDir] > newTurns) {
                        queue.offer(new State(newRow, newCol, nextDir, newTurns));
                    }
                }
            }
        }

        System.out.println(found ? "YES" : "NO");
    }

    /**
     * Represents a state in the BFS traversal.
     * Immutable to prevent accidental mutation during queue operations.
     */
    private static class State {
        final int row, col, dir, turns;

        State(int row, int col, int dir, int turns) {
            this.row = row;
            this.col = col;
            this.dir = dir;
            this.turns = turns;
        }
    }
}

import java.io.*;
import java.util.*;

public class Main implements Runnable {
    // Grid state constants
    private static final int UNVISITED = -1;
    private static final int OBSTACLE = -2;
    private static final int SIGNAL_S = 0;
    private static final int SIGNAL_T = 1;

    public static void main(String[] args) {
        // Increased stack size to prevent StackOverflowError on deep recursion/large inputs
        new Thread(null, new Main(), "solution", 1 << 26).start();
    }

    @Override
    public void run() {
        FastScanner sc = new FastScanner(System.in);
        PrintWriter pw = new PrintWriter(System.out);
        try {
            solve(sc, pw);
        } finally {
            pw.flush();
            pw.close();
        }
    }

    private void solve(FastScanner sc, PrintWriter pw) {
        int rows = sc.nextInt();
        int cols = sc.nextInt();
        char[][] grid = new char[rows][];
        for (int i = 0; i < rows; i++) {
            grid[i] = sc.next().toCharArray();
        }

        int[][] reachable = new int[rows][cols];
        for (int[] row : reachable) {
            Arrays.fill(row, UNVISITED);
        }

        // Mark obstacles
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == '*') {
                    reachable[i][j] = OBSTACLE;
                }
            }
        }

        // Propagate signals from 'S' and 'T' positions
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == 'S') {
                    propagateSignal(grid, reachable, i, j, SIGNAL_S);
                } else if (grid[i][j] == 'T') {
                    propagateSignal(grid, reachable, i, j, SIGNAL_T);
                }
            }
        }

        // Check if any row or column contains both signals without an obstacle between them
        boolean hasConnection = false;
        for (int i = 0; i < rows; i++) {
            if (checkLine(reachable, true, i)) {
                hasConnection = true;
                break;
            }
        }
        if (!hasConnection) {
            for (int j = 0; j < cols; j++) {
                if (checkLine(reachable, false, j)) {
                    hasConnection = true;
                    break;
                }
            }
        }

        pw.println(hasConnection ? "YES" : "NO");
    }

    /**
     * Checks a single row or column for conflicting signals (S and T) 
     * without an obstacle separating them.
     */
    private boolean checkLine(int[][] reachable, boolean checkRows, int index) {
        int lastSignal = OBSTACLE;
        int limit = checkRows ? reachable[0].length : reachable.length;

        for (int i = 0; i < limit; i++) {
            int current = checkRows ? reachable[index][i] : reachable[i][index];
            if (current == UNVISITED) continue;

            if (current == OBSTACLE) {
                lastSignal = OBSTACLE;
            } else if (current == SIGNAL_S) {
                if (lastSignal == SIGNAL_T) return true;
                lastSignal = SIGNAL_S;
            } else if (current == SIGNAL_T) {
                if (lastSignal == SIGNAL_S) return true;
                lastSignal = SIGNAL_T;
            }
        }
        return false;
    }

    /**
     * Propagates a signal (S or T) horizontally and vertically through empty cells.
     */
    private void propagateSignal(char[][] grid, int[][] reachable, int startX, int startY, int signal) {
        int rows = grid.length;
        int cols = grid[0].length;
        reachable[startX][startY] = signal;

        // Propagate upwards
        for (int r = startX - 1; r >= 0 && grid[r][startY] == '.'; r--) {
            reachable[r][startY] = signal;
        }
        // Propagate downwards
        for (int r = startX + 1; r < rows && grid[r][startY] == '.'; r++) {
            reachable[r][startY] = signal;
        }
        // Propagate leftwards
        for (int c = startY - 1; c >= 0 && grid[startX][c] == '.'; c--) {
            reachable[startX][c] = signal;
        }
        // Propagate rightwards
        for (int c = startY + 1; c < cols && grid[startX][c] == '.'; c++) {
            reachable[startX][c] = signal;
        }
    }

    /**
     * Fast input reader for competitive programming.
     */
    static class FastScanner {
        private BufferedReader br;
        private StringTokenizer st;

        public FastScanner(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        public String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input", e);
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }

        public double nextDouble() {
            return Double.parseDouble(next());
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.OutputStream;
import java.io.OutputStreamWriter;
import java.io.PrintWriter;
import java.util.StringTokenizer;

/**
 * Main entry point for the solution. Sets up fast I/O and delegates to the solver.
 */
public class Main {
    public static void main(String[] args) {
        InputReader in = new InputReader(System.in);
        OutputWriter out = new OutputWriter(System.out);
        new TaskB().solve(in, out);
        out.close();
    }

    /**
     * Solver for the grid visibility/intersection problem.
     */
    static class TaskB {
        // Direction vectors for Up, Left, Down, Right
        private static final int[][] DIRECTIONS = {
            {-1, 0}, {0, -1}, {1, 0}, {0, 1}
        };

        // Grid cell constants
        private static final char START = 'S';
        private static final char TARGET = 'T';
        private static final char WALL = '*';

        /**
         * Solves the problem by marking visible cells from START and TARGET,
         * then checking if any line of sight from START intersects with TARGET's visibility.
         */
        public void solve(InputReader in, OutputWriter out) {
            int n = in.nextInt();
            int m = in.nextInt();
            char[][] grid = new char[n][m];
            for (int i = 0; i < n; i++) {
                grid[i] = in.next().toCharArray();
            }

            // visible[0] tracks cells visible from START, visible[1] from TARGET
            boolean[][][] visible = new boolean[2][n][m];

            // Mark cells visible from both START and TARGET
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    char cell = grid[i][j];
                    if (cell == START || cell == TARGET) {
                        int type = (cell == START) ? 0 : 1;
                        markVisibleCells(grid, visible, type, i, j, n, m);
                    }
                }
            }

            // Check if any cell visible from START has a line of sight to a cell visible from TARGET
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    if (visible[0][i][j]) {
                        if (checkLineOfSightIntersection(grid, visible, i, j, n, m)) {
                            out.println("YES");
                            return;
                        }
                    }
                }
            }
            out.println("NO");
        }

        /**
         * Marks all cells visible in the four cardinal directions from a starting position.
         */
        private void markVisibleCells(char[][] grid, boolean[][][] visible, int type, 
                                      int startRow, int startCol, int n, int m) {
            for (int[] dir : DIRECTIONS) {
                int r = startRow + dir[0];
                int c = startCol + dir[1];
                while (r >= 0 && r < n && c >= 0 && c < m && grid[r][c] != WALL) {
                    visible[type][r][c] = true;
                    r += dir[0];
                    c += dir[1];
                }
            }
        }

        /**
         * Checks if a line of sight from the starting position intersects with any cell
         * marked as visible from TARGET (type 1).
         */
        private boolean checkLineOfSightIntersection(char[][] grid, boolean[][][] visible, 
                                                       int startRow, int startCol, int n, int m) {
            for (int[] dir : DIRECTIONS) {
                int r = startRow + dir[0];
                int c = startCol + dir[1];
                while (r >= 0 && r < n && c >= 0 && c < m && grid[r][c] != WALL) {
                    if (visible[1][r][c]) {
                        return true;
                    }
                    r += dir[0];
                    c += dir[1];
                }
            }
            return false;
        }
    }

    /**
     * Fast input reader using BufferedReader and StringTokenizer for maintainability and performance.
     */
    static class InputReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
            tokenizer = new StringTokenizer("");
        }

        public String next() {
            while (!tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) {
                        throw new IOException("End of stream");
                    }
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input", e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }

    /**
     * Fast output writer using PrintWriter and BufferedWriter.
     */
    static class OutputWriter {
        private final PrintWriter writer;

        public OutputWriter(OutputStream stream) {
            writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(stream)));
        }

        public void println(String message) {
            writer.println(message);
        }

        public void close() {
            writer.flush();
            writer.close();
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayDeque;
import java.util.Queue;
import java.util.StringTokenizer;

public class B7932 {

    // Configuration constants
    private static final int[][] DIRECTIONS = {{1, 0}, {0, 1}, {-1, 0}, {0, -1}};
    private static final int MAX_TURNS = 2;
    private static final char OBSTACLE = '*';
    private static final char START = 'S';
    private static final char TARGET = 'T';

    /**
     * Immutable state representation for BFS traversal.
     * Contains position, current direction, and remaining allowed turns.
     */
    private static final class State {
        final int x, y;
        final int direction; // 0: Down, 1: Right, 2: Up, 3: Left
        final int remainingTurns;

        State(int x, int y, int direction, int remainingTurns) {
            this.x = x;
            this.y = y;
            this.direction = direction;
            this.remainingTurns = remainingTurns;
        }
    }

    /**
     * Efficient input reader that properly handles whitespace and newlines.
     */
    private static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        public String next() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) return null;
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

        public int nextInt() throws IOException {
            String s = next();
            return s == null ? 0 : Integer.parseInt(s);
        }

        public String nextLine() throws IOException {
            String line = br.readLine();
            return line == null ? "" : line;
        }
    }

    public static void main(String[] args) throws IOException {
        FastScanner scanner = new FastScanner();

        // Read grid dimensions
        int n = scanner.nextInt();
        int m = scanner.nextInt();

        char[][] grid = new char[n][m];
        int startX = -1, startY = -1;
        int targetX = -1, targetY = -1;

        // Read grid and locate start/target positions
        for (int i = 0; i < n; i++) {
            // Consume potential empty lines or trailing whitespace from previous reads
            String line = scanner.nextLine();
            while (line != null && line.trim().isEmpty()) {
                line = scanner.nextLine();
            }
            if (line == null) break;

            grid[i] = line.trim().toCharArray();
            for (int j = 0; j < m; j++) {
                char c = grid[i][j];
                if (c == START) {
                    startX = i;
                    startY = j;
                } else if (c == TARGET) {
                    targetX = i;
                    targetY = j;
                }
            }
        }

        // Solve and output result
        boolean canReach = solve(grid, startX, startY, targetX, targetY);
        System.out.println(canReach ? "YES" : "NO");
    }

    /**
     * Performs BFS to determine if the target can be reached from the start
     * with a maximum of MAX_TURNS direction changes.
     */
    private static boolean solve(char[][] grid, int startX, int startY, int targetX, int targetY) {
        int n = grid.length;
        int m = grid[0].length;

        // visited[x][y][direction][remainingTurns]
        boolean[][][][] visited = new boolean[n][m][4][MAX_TURNS + 1];
        Queue<State> queue = new ArrayDeque<>();

        // Initialize BFS with all valid initial moves from the start position
        for (int dir = 0; dir < 4; dir++) {
            int nx = startX + DIRECTIONS[dir][0];
            int ny = startY + DIRECTIONS[dir][1];

            if (isValid(nx, ny, n, m, grid)) {
                visited[nx][ny][dir][MAX_TURNS] = true;
                queue.add(new State(nx, ny, dir, MAX_TURNS));
            }
        }

        while (!queue.isEmpty()) {
            State current = queue.poll();

            // Check if target is reached
            if (current.x == targetX && current.y == targetY) {
                return true;
            }

            // Explore neighbors
            for (int dir = 0; dir < 4; dir++) {
                int nx = current.x + DIRECTIONS[dir][0];
                int ny = current.y + DIRECTIONS[dir][1];

                if (!isValid(nx, ny, n, m, grid)) {
                    continue;
                }

                int newTurns;
                if (dir == current.direction) {
                    // Continue in the same direction: turns remain unchanged
                    newTurns = current.remainingTurns;
                } else if (isOpposite(dir, current.direction)) {
                    // Cannot reverse direction immediately
                    continue;
                } else {
                    // Change direction: consume one turn
                    newTurns = current.remainingTurns - 1;
                }

                // If we have turns left and haven't visited this state, add to queue
                if (newTurns >= 0 && !visited[nx][ny][dir][newTurns]) {
                    visited[nx][ny][dir][newTurns] = true;
                    queue.add(new State(nx, ny, dir, newTurns));
                }
            }
        }

        return false;
    }

    /**
     * Checks if a coordinate is within bounds and not an obstacle.
     */
    private static boolean isValid(int x, int y, int n, int m, char[][] grid) {
        return x >= 0 && x < n && y >= 0 && y < m && grid[x][y] != OBSTACLE;
    }

    /**
     * Checks if two directions are directly opposite (180 degrees apart).
     */
    private static boolean isOpposite(int dir1, int dir2) {
        return (dir1 + 2) % 4 == dir2;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayDeque;
import java.util.Queue;

public class IgorAndHisWayToWork {

    private static final int MAX_TURNS = 2;
    private static final int WALL = '*';

    private int n;
    private int m;
    private char[][] labyrinth;
    private boolean[][] visited;

    // Direction vectors: UP, DOWN, LEFT, RIGHT
    private static final int[] DR = {-1, 1, 0, 0};
    private static final int[] DC = {0, 0, -1, 1};

    public static void main(String[] args) throws IOException {
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            String[] dimensions = br.readLine().trim().split("\\s+");
            int n = Integer.parseInt(dimensions[0]);
            int m = Integer.parseInt(dimensions[1]);

            IgorAndHisWayToWork solver = new IgorAndHisWayToWork(n, m);
            solver.readGrid(br);

            int[] start = solver.findStartPosition();
            boolean result = solver.isTargetReachable(start[0], start[1]);
            System.out.println(result ? "YES" : "NO");
        }
    }

    private IgorAndHisWayToWork(int n, int m) {
        this.n = n;
        this.m = m;
        this.labyrinth = new char[n][m];
        this.visited = new boolean[n][m];
    }

    private void readGrid(BufferedReader br) throws IOException {
        for (int i = 0; i < n; i++) {
            labyrinth[i] = br.readLine().trim().toCharArray();
        }
    }

    private int[] findStartPosition() {
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < m; c++) {
                if (labyrinth[r][c] == 'S') {
                    return new int[]{r, c};
                }
            }
        }
        return new int[]{-1, -1};
    }

    private boolean isTargetReachable(int startRow, int startCol) {
        Queue<int[]> queue = new ArrayDeque<>();
        queue.add(new int[]{startRow, startCol, 0});
        visited[startRow][startCol] = true;

        while (!queue.isEmpty()) {
            int[] current = queue.poll();
            int r = current[0];
            int c = current[1];
            int depth = current[2];

            // Prune paths that exceed the maximum allowed turns
            if (depth > MAX_TURNS) {
                continue;
            }

            // Explore all four directions
            for (int dir = 0; dir < 4; dir++) {
                if (scanInDirection(r, c, DR[dir], DC[dir], depth, queue)) {
                    return true;
                }
            }
        }
        return false;
    }

    /**
     * Scans the grid in a straight line from the starting cell in the given direction.
     * Returns true if 'T' is encountered, otherwise false.
     */
    private boolean scanInDirection(int startRow, int startCol, int dr, int dc, int depth, Queue<int[]> queue) {
        int r = startRow + dr;
        int c = startCol + dc;

        while (r >= 0 && r < n && c >= 0 && c < m) {
            char cell = labyrinth[r][c];

            if (cell == 'T') {
                return true;
            }
            if (cell == WALL) {
                break;
            }

            if (cell == '.' && !visited[r][c]) {
                visited[r][c] = true;
                // Check if a turn is possible from this cell
                if (canTurn(r, c) && depth + 1 <= MAX_TURNS) {
                    queue.add(new int[]{r, c, depth + 1});
                }
            }
            r += dr;
            c += dc;
        }
        return false;
    }

    /**
     * Checks if a turn is possible from the given cell.
     * A turn is possible if at least one perpendicular neighbor is not a wall.
     */
    private boolean canTurn(int r, int c) {
        // Horizontal turns (for vertical movement)
        if (isValid(r - 1, c) && labyrinth[r - 1][c] != WALL) return true;
        if (isValid(r + 1, c) && labyrinth[r + 1][c] != WALL) return true;
        // Vertical turns (for horizontal movement)
        if (isValid(r, c - 1) && labyrinth[r][c - 1] != WALL) return true;
        if (isValid(r, c + 1) && labyrinth[r][c + 1] != WALL) return true;
        return false;
    }

    private boolean isValid(int r, int c) {
        return r >= 0 && r < n && c >= 0 && c < m;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.OutputStream;
import java.io.PrintWriter;
import java.util.LinkedList;
import java.util.Queue;
import java.util.StringTokenizer;

/**
 * Main entry point for the grid path solver.
 */
public class Main {

    // Direction vectors: {dx, dy} for right, left, down, up
    private static final int[][] MOVES = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};
    private static final int MAX_TURNS = 2; // Maximum allowed direction changes

    public static void main(String[] args) {
        FastReader in = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        GridPathSolver solver = new GridPathSolver();
        solver.solve(in, out);

        out.flush();
        out.close();
    }

    /**
     * Solves the grid pathfinding problem using multi-source BFS.
     */
    static class GridPathSolver {
        public void solve(FastReader in, PrintWriter out) {
            int n = in.nextInt();
            int m = in.nextInt();

            char[][] grid = new char[n][];
            for (int i = 0; i < n; i++) {
                grid[i] = in.nextLine().toCharArray();
            }

            // visited[row][col][directionIndex][turnCount]
            boolean[][][][] visited = new boolean[n][m][4][MAX_TURNS + 1];
            Queue<BfsState> queue = new LinkedList<>();

            // Initialize BFS from all 'S' cells simultaneously
            for (int r = 0; r < n; r++) {
                for (int c = 0; c < m; c++) {
                    if (grid[r][c] == 'S') {
                        for (int dir = 0; dir < 4; dir++) {
                            visited[r][c][dir][0] = true;
                            queue.add(new BfsState(c, r, dir, 0));
                        }
                    }
                }
            }

            // Execute BFS
            while (!queue.isEmpty()) {
                BfsState current = queue.poll();

                for (int dir = 0; dir < 4; dir++) {
                    int nextCol = current.col + MOVES[dir][0];
                    int nextRow = current.row + MOVES[dir][1];
                    int nextTurns = current.turnCount + (current.directionIndex == dir ? 0 : 1);

                    if (isValid(nextRow, nextCol, dir, nextTurns, grid, visited)) {
                        visited[nextRow][nextCol][dir][nextTurns] = true;
                        queue.add(new BfsState(nextCol, nextRow, dir, nextTurns));
                    }
                }
            }

            // Check reachability for all 'T' cells
            for (int r = 0; r < n; r++) {
                for (int c = 0; c < m; c++) {
                    if (grid[r][c] == 'T') {
                        boolean reachable = false;
                        for (int dir = 0; dir < 4; dir++) {
                            for (int turns = 0; turns <= MAX_TURNS; turns++) {
                                if (visited[r][c][dir][turns]) {
                                    reachable = true;
                                    break;
                                }
                            }
                            if (reachable) break;
                        }
                        out.println(reachable ? "YES" : "NO");
                    }
                }
            }
        }

        /**
         * Validates boundaries, obstacles, turn limits, and visited states.
         */
        private boolean isValid(int row, int col, int directionIndex, int turnCount, 
                                char[][] grid, boolean[][][][] visited) {
            if (row < 0 || row >= grid.length || col < 0 || col >= grid[0].length) {
                return false;
            }
            if (grid[row][col] == '*') {
                return false;
            }
            if (turnCount > MAX_TURNS) {
                return false;
            }
            if (visited[row][col][directionIndex][turnCount]) {
                return false;
            }
            return true;
        }
    }

    /**
     * Represents a state in the BFS traversal.
     */
    static class BfsState {
        final int col;
        final int row;
        final int directionIndex;
        final int turnCount;

        BfsState(int col, int row, int directionIndex, int turnCount) {
            this.col = col;
            this.row = row;
            this.directionIndex = directionIndex;
            this.turnCount = turnCount;
        }
    }

    /**
     * Fast I/O helper class for competitive programming style input.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        FastReader(InputStream inputStream) {
            this.reader = new BufferedReader(new InputStreamReader(inputStream));
        }

        String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input", e);
                }
            }
            return tokenizer.nextToken();
        }

        int nextInt() {
            String token = next();
            return token == null ? 0 : Integer.parseInt(token);
        }

        String nextLine() {
            try {
                return reader.readLine();
            } catch (IOException e) {
                throw new RuntimeException("Failed to read line", e);
            }
        }
    }
}

