public class Main {
    public static void main(String[] args) {
        new Solver().solve();
    }
}

class Solver {
    private static final char OBSTACLE = '*';
    private static final char START = 'S';
    private static final char TARGET = 'T';
    private static final int[] DR = {0, 0, 1, -1};
    private static final int[] DC = {1, -1, 0, 0};

    private final int rows;
    private final int cols;
    private final char[][] grid;
    private final int startRow, startCol;
    private final int targetRow, targetCol;

    Solver() {
        FastScanner sc = new FastScanner(System.in);
        this.rows = sc.nextInt();
        this.cols = sc.nextInt();
        this.grid = new char[rows][cols];
        this.startRow = -1;
        this.startCol = -1;
        this.targetRow = -1;
        this.targetCol = -1;

        // Consume the newline character remaining after reading the second integer
        sc.nextLine();

        for (int r = 0; r < rows; r++) {
            String line = sc.nextLine();
            if (line == null || line.length() < cols) {
                throw new IllegalArgumentException("Invalid input: expected row of length " + cols);
            }
            grid[r] = line.toCharArray();
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == START) {
                    startRow = r;
                    startCol = c;
                } else if (grid[r][c] == TARGET) {
                    targetRow = r;
                    targetCol = c;
                }
            }
        }
    }

    void solve() {
        boolean[][] reachableFromStart = markReachableCells(grid, startRow, startCol);
        boolean[][] reachableFromTarget = markReachableCells(grid, targetRow, targetCol);

        boolean intersects = doPathsIntersect(reachableFromStart, reachableFromTarget, grid);
        System.out.println(intersects ? "YES" : "NO");
    }

    /**
     * Marks all cells reachable from a starting position in straight lines 
     * until an obstacle or grid boundary is encountered.
     */
    private boolean[][] markReachableCells(char[][] grid, int startR, int startC) {
        boolean[][] visited = new boolean[grid.length][grid[0].length];
        for (int d = 0; d < 4; d++) {
            int r = startR;
            int c = startC;
            while (true) {
                r += DR[d];
                c += DC[d];
                if (r < 0 || r >= grid.length || c < 0 || c >= grid[0].length) break;
                if (grid[r][c] == OBSTACLE) break;
                visited[r][c] = true;
            }
        }
        visited[startR][startC] = true;
        return visited;
    }

    /**
     * Checks if any cell reachable from the start can visually reach 
     * a cell reachable from the target (line-of-sight intersection).
     */
    private boolean doPathsIntersect(boolean[][] visitedS, boolean[][] visitedT, char[][] grid) {
        for (int r = 0; r < visitedS.length; r++) {
            for (int c = 0; c < visitedS[0].length; c++) {
                if (!visitedS[r][c]) continue;
                for (int d = 0; d < 4; d++) {
                    int cr = r;
                    int cc = c;
                    while (true) {
                        cr += DR[d];
                        cc += DC[d];
                        if (cr < 0 || cr >= grid.length || cc < 0 || cc >= grid[0].length) break;
                        if (grid[cr][cc] == OBSTACLE) break;
                        if (visitedT[cr][cc]) return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * High-performance scanner for competitive programming / fast I/O.
     */
    private static class FastScanner {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastScanner(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("IO error reading input", e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            String s = next();
            if (s == null) throw new NoSuchElementException("End of input");
            return Integer.parseInt(s);
        }

        public String nextLine() {
            try {
                return reader.readLine();
            } catch (IOException e) {
                throw new RuntimeException("IO error reading line", e);
            }
        }
    }
}

import java.io.*;
import java.util.*;

public class Main {
    // Constants for grid cell states
    private static final int UNMARKED = 0;
    private static final int MARKED_BY_S = 1;
    private static final int MARKED_BY_T = 2;

    // Grid data
    private int rows, cols;
    private char[][] grid;
    private int[][] markedGrid;
    private int startRow, startCol, targetRow, targetCol;

    // I/O components
    private BufferedReader br;
    private StringTokenizer sc;
    private PrintWriter out;

    public static void main(String[] args) {
        Locale.setDefault(Locale.US);
        new Main().run();
    }

    private void run() throws IOException {
        try {
            br = new BufferedReader(new InputStreamReader(System.in));
            out = new PrintWriter(System.out);
            solve();
            out.close();
        } catch (Exception e) {
            e.printStackTrace();
            System.exit(1);
        }
    }

    private void solve() throws IOException {
        rows = nextInt();
        cols = nextInt();
        grid = new char[rows][];

        // Read grid and locate start ('S') and target ('T') positions
        for (int i = 0; i < rows; i++) {
            grid[i] = nextToken().toCharArray();
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == 'S') {
                    startRow = i;
                    startCol = j;
                } else if (grid[i][j] == 'T') {
                    targetRow = i;
                    targetCol = j;
                }
            }
        }

        markedGrid = new int[rows][cols];

        // Mark all cells reachable from S in straight lines until hitting '*'
        scanDirection(startRow, startCol, 1, 0, MARKED_BY_S);
        scanDirection(startRow, startCol, -1, 0, MARKED_BY_S);
        scanDirection(startRow, startCol, 0, 1, MARKED_BY_S);
        scanDirection(startRow, startCol, 0, -1, MARKED_BY_S);

        // Check if T's straight-line paths intersect with S's marked paths
        if (scanAndCheckIntersection(targetRow, targetCol, 1, 0)) return;
        if (scanAndCheckIntersection(targetRow, targetCol, -1, 0)) return;
        if (scanAndCheckIntersection(targetRow, targetCol, 0, 1)) return;
        if (scanAndCheckIntersection(targetRow, targetCol, 0, -1)) return;

        // Check for alternative paths around obstacles
        if (checkForAdditionalPaths()) {
            out.println("YES");
            return;
        }

        out.println("NO");
    }

    /**
     * Scans in a specific direction from a starting point and marks cells.
     */
    private void scanDirection(int startR, int startC, int dr, int dc, int markValue) {
        int r = startR, c = startC;
        while (r >= 0 && r < rows && c >= 0 && c < cols && grid[r][c] != '*') {
            markedGrid[r][c] = markValue;
            r += dr;
            c += dc;
        }
    }

    /**
     * Scans in a specific direction from T. Checks for intersection with S's marks.
     * Marks T's path with MARKED_BY_T.
     * Returns true if an intersection is found.
     */
    private boolean scanAndCheckIntersection(int startR, int startC, int dr, int dc) {
        int r = startR, c = startC;
        while (r >= 0 && r < rows && c >= 0 && c < cols && grid[r][c] != '*') {
            if (markedGrid[r][c] == MARKED_BY_S) {
                out.println("YES");
                return true;
            }
            markedGrid[r][c] = MARKED_BY_T;
            r += dr;
            c += dc;
        }
        return false;
    }

    /**
     * Checks rows and columns for valid alternative paths.
     */
    private boolean checkForAdditionalPaths() {
        // Check each row (excluding S and T rows)
        for (int i = 0; i < rows; i++) {
            if (i == startRow || i == targetRow) continue;
            if (checkLineForSegment(i, true)) return true;
        }
        // Check each column (excluding S and T columns)
        for (int j = 0; j < cols; j++) {
            if (j == startCol || j == targetCol) continue;
            if (checkLineForSegment(j, false)) return true;
        }
        return false;
    }

    /**
     * Checks a single row or column for the specific segment pattern.
     */
    private boolean checkLineForSegment(int index, boolean isRow) {
        boolean inSegment = false;
        int length = isRow ? cols : rows;

        for (int k = 0; k < length; k++) {
            int r = isRow ? index : k;
            int c = isRow ? k : index;

            if (inSegment) {
                if (markedGrid[r][c] != 0) {
                    return true;
                }
                if (grid[r][c] == '*') {
                    inSegment = false;
                }
            } else {
                if (markedGrid[r][c] != 0) {
                    inSegment = true;
                }
            }
        }
        return false;
    }

    /**
     * Reads the next token from input.
     */
    private String nextToken() throws IOException {
        while (sc == null || !sc.hasMoreTokens()) {
            String line = br.readLine();
            if (line == null) return null;
            sc = new StringTokenizer(line);
        }
        return sc.nextToken();
    }

    /**
     * Reads the next integer from input.
     */
    private int nextInt() throws IOException {
        String token = nextToken();
        if (token == null) throw new EOFException("Unexpected end of input");
        return Integer.parseInt(token);
    }
}

import java.io.BufferedReader;
import java.io.BufferedOutputStream;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.OutputStream;
import java.io.PrintWriter;
import java.util.PriorityQueue;
import java.util.StringTokenizer;

public class Main {

    // Direction vectors: Right, Left, Down, Up
    // Using descriptive names instead of MR/MC
    private static final int[] DR = {0, 0, 1, -1};
    private static final int[] DC = {1, -1, 0, 0};

    // Maximum allowed turns. 
    // Original logic: if (mc < 2) allow turn. 
    // Since mc started at -1 and incremented, this effectively limits turns to 2.
    private static final int MAX_TURNS = 2;

    public static void main(String[] args) {
        // Use try-with-resources for clean resource management and automatic closing
        try (InputStream inputStream = System.in;
             OutputStream outputStream = System.out) {

            // Replace custom InputReader with standard BufferedReader for better maintainability
            FastScanner in = new FastScanner(inputStream);
            // Replace custom OutputWriter with standard PrintWriter
            PrintWriter out = new PrintWriter(new BufferedOutputStream(outputStream));

            Task solver = new Task();
            solver.solve(in, out);

            // Ensure all output is written
            out.flush();
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    /**
     * Encapsulates the core logic of the problem.
     * State variables (q, visit, arr, n, m) are moved to local scope to improve 
     * thread safety and reduce class state complexity.
     */
    static class Task {
        public void solve(FastScanner in, PrintWriter out) {
            try {
                // Read dimensions
                int n = in.nextInt();
                int m = in.nextInt();

                char[][] grid = new char[n][m];
                // PriorityQueue to store states, ordered by number of turns (min-heap)
                PriorityQueue<State> pq = new PriorityQueue<>();

                // Read grid and find start position
                for (int i = 0; i < n; i++) {
                    String row = in.next();
                    for (int j = 0; j < m; j++) {
                        grid[i][j] = row.charAt(j);
                        if (grid[i][j] == 'S') {
                            // Start state: row, col, direction -1 (none), turns 0
                            pq.offer(new State(i, j, -1, 0));
                        }
                    }
                }

                boolean[][] visited = new boolean[n][m];

                while (!pq.isEmpty()) {
                    State current = pq.poll();
                    int r = current.r;
                    int c = current.c;
                    int dir = current.dir;
                    int turns = current.turns;

                    // Check if target reached
                    if (grid[r][c] == 'T') {
                        out.println("YES");
                        return;
                    }

                    // If already visited, skip. 
                    // Since we use a PQ ordered by turns, the first time we visit a cell 
                    // is guaranteed to be with the minimum turns.
                    if (visited[r][c]) {
                        continue;
                    }
                    visited[r][c] = true;

                    // Explore neighbors
                    for (int i = 0; i < 4; i++) {
                        int r2 = r + DR[i];
                        int c2 = c + DC[i];

                        // Check bounds and walls ('*')
                        if (r2 >= 0 && r2 < n && c2 >= 0 && c2 < m && grid[r2][c2] != '*') {
                            if (!visited[r2][c2]) {
                                int newTurns;

                                // Determine if this move constitutes a turn.
                                // dir == -1 indicates the starting position (no previous direction).
                                // dir == i indicates continuing in the same direction.
                                if (dir == -1 || dir == i) {
                                    newTurns = turns;
                                } else {
                                    newTurns = turns + 1;
                                }

                                // Check turn limit.
                                // Original logic checked 'mc < 2' before incrementing.
                                // This allows reaching a state with 2 turns, but prevents 3.
                                if (newTurns <= MAX_TURNS) {
                                    pq.offer(new State(r2, c2, i, newTurns));
                                }
                            }
                        }
                    }
                }

                out.println("NO");

            } catch (Exception e) {
                e.printStackTrace();
            }
        }
    }

    /**
     * Represents a state in the BFS/PriorityQueue.
     * Implements Comparable to order by number of turns (ascending).
     */
    static class State implements Comparable<State> {
        int r, c, dir, turns;

        public State(int r, int c, int dir, int turns) {
            this.r = r;
            this.c = c;
            this.dir = dir;
            this.turns = turns;
        }

        @Override
        public int compareTo(State other) {
            // Order by turns ascending
            return Integer.compare(this.turns, other.turns);
        }
    }

    /**
     * FastScanner helper class for efficient input reading.
     * Replaces the custom byte-buffer InputReader for better maintainability 
     * and readability using standard Java libraries.
     */
    static class FastScanner {
        BufferedReader br;
        StringTokenizer st;

        public FastScanner(InputStream stream) {
            br = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

public class BTask {

    // Constants representing grid states
    private static final int OBSTACLE = 1;
    private static final int TARGET_REACHABLE = 4;
    private static final int START_REACHABLE = 5;

    public static void main(String[] args) {
        FastScanner in = new FastScanner(System.in);

        // Read dimensions
        String nStr = in.next();
        if (nStr == null) return; // Handle empty input
        int n = Integer.parseInt(nStr);
        int m = in.nextInt();

        // Grid to store obstacles
        int[][] grid = new int[n][m];

        // Grids to store reachability from Target and Start respectively
        int[][] tReachable = new int[n][m];
        int[][] sReachable = new int[n][m];

        int startRow = -1, startCol = -1;
        int targetRow = -1, targetCol = -1;

        // Parse the grid input
        for (int i = 0; i < n; i++) {
            String row = in.next();
            for (int j = 0; j < m; j++) {
                char c = row.charAt(j);
                if (c == '*') {
                    grid[i][j] = OBSTACLE;
                } else if (c == 'S') {
                    startRow = i;
                    startCol = j;
                } else if (c == 'T') {
                    targetRow = i;
                    targetCol = j;
                }
            }
        }

        // Mark all cells visible from the Target 'T'
        markLines(grid, tReachable, targetRow, targetCol, TARGET_REACHABLE);

        // Mark all cells visible from the Start 'S'
        markLines(grid, sReachable, startRow, startCol, START_REACHABLE);

        // Check if there is any cell visible from both S and T
        boolean connected = false;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                // If a cell is reachable from both Start and Target, they can communicate
                if (tReachable[i][j] == TARGET_REACHABLE && sReachable[i][j] == START_REACHABLE) {
                    connected = true;
                    break;
                }
            }
            if (connected) break;
        }

        System.out.println(connected ? "YES" : "NO");
    }

    /**
     * Marks cells reachable in a straight line from (r, c) in all 4 directions
     * until an obstacle is encountered.
     *
     * @param obstacles The grid containing obstacle locations (value 1)
     * @param targetGrid The grid to write the reachability marks into
     * @param r Starting row
     * @param c Starting column
     * @param value The value to mark reachable cells with
     */
    private static void markLines(int[][] obstacles, int[][] targetGrid, int r, int c, int value) {
        // Mark the starting cell itself
        targetGrid[r][c] = value;

        // Directions: Up, Down, Left, Right
        int[] dr = {-1, 1, 0, 0};
        int[] dc = {0, 0, -1, 1};

        for (int k = 0; k < 4; k++) {
            int nr = r + dr[k];
            int nc = c + dc[k];

            // Traverse in the current direction
            while (nr >= 0 && nr < obstacles.length && nc >= 0 && nc < obstacles[0].length) {
                if (obstacles[nr][nc] == OBSTACLE) {
                    break; // Stop at obstacle
                }
                targetGrid[nr][nc] = value;
                nr += dr[k];
                nc += dc[k];
            }
        }
    }

    /**
     * Fast input reader for competitive programming.
     */
    static class FastScanner {
        BufferedReader br;
        StringTokenizer st;

        public FastScanner(InputStream stream) {
            br = new BufferedReader(new InputStreamReader(stream), 32768);
        }

        public String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            String s = next();
            if (s == null) throw new RuntimeException("End of input");
            return Integer.parseInt(s);
        }
    }
}

import java.util.Scanner;

public class PathSearcher {
    // Direction mappings: 0=DOWN, 1=RIGHT, 2=UP, 3=LEFT
    private static final int[] DX = {0, 1, 0, -1};
    private static final int[] DY = {1, 0, -1, 0};
    private static final int MAX_TLEFT = 2;

    /**
     * Represents cell types on the grid using their original numeric codes.
     * Replaces magic numbers with self-documenting constants.
     */
    enum CellType {
        EMPTY(1), OBSTACLE(2), TARGET(3), START(4);
        private final int code;
        CellType(int code) { this.code = code; }
        public int getCode() { return code; }
    }

    public static void main(String[] args) {
        // Use try-with-resources for automatic resource management
        try (Scanner scanner = new Scanner(System.in)) {
            if (!scanner.hasNextInt()) return;

            int rows = scanner.nextInt();
            int cols = scanner.nextInt();

            short[][] grid = new short[rows][cols];
            int startX = -1, startY = -1;

            // Parse the grid
            for (int r = 0; r < rows; r++) {
                String line = scanner.next();
                for (int c = 0; c < cols; c++) {
                    char ch = line.charAt(c);
                    switch (ch) {
                        case '.': grid[r][c] = CellType.EMPTY.getCode(); break;
                        case '*': grid[r][c] = CellType.OBSTACLE.getCode(); break;
                        case 'T': grid[r][c] = CellType.TARGET.getCode(); break;
                        case 'S':
                            grid[r][c] = CellType.START.getCode();
                            startY = r;
                            startX = c;
                            break;
                        default:
                            throw new IllegalArgumentException("Invalid grid character: " + ch);
                    }
                }
            }

            // visited[dir][tleft][y][x]
            // Java initializes boolean arrays to false by default, so explicit initialization is unnecessary
            boolean[][][][] visited = new boolean[4][MAX_TLEFT + 1][rows][cols];

            boolean found = false;
            // Try exploring from the start position in all 4 initial directions
            for (int dir = 0; dir < 4; dir++) {
                if (explore(dir, startX, startY, grid, visited, MAX_TLEFT, rows, cols)) {
                    found = true;
                    break;
                }
            }

            System.out.println(found ? "YES" : "NO");
        }
    }

    /**
     * Recursively explores the grid in a specific direction with a remaining 'tleft' counter.
     *
     * @param dir     Current movement direction (0-3)
     * @param x       Current x-coordinate
     * @param y       Current y-coordinate
     * @param grid    2D array representing the grid cell types
     * @param visited 4D array tracking visited states to prevent cycles/redundant work
     * @param tleft   Remaining turns/counter value allowed
     * @param rows    Number of rows in the grid
     * @param cols    Number of columns in the grid
     * @return true if a target cell is reachable, false otherwise
     */
    private static boolean explore(int dir, int x, int y, short[][] grid, boolean[][][][] visited, int tleft, int rows, int cols) {
        // 1. Boundary check
        if (x < 0 || x >= cols || y < 0 || y >= rows) {
            return false;
        }
        // 2. Obstacle check
        if (grid[y][x] == CellType.OBSTACLE.getCode()) {
            return false;
        }
        // 3. Visited state check
        if (visited[dir][tleft][y][x]) {
            return false;
        }

        // Mark current state as visited
        visited[dir][tleft][y][x] = true;

        // Optimization: If we've reached this cell with 'tleft' turns remaining,
        // we've implicitly reached it with any smaller amount of turns remaining.
        // Mark those states as visited to prune the search space.
        for (int t = 0; t < tleft; t++) {
            for (int d = 0; d < 4; d++) {
                visited[d][t][y][x] = true;
            }
        }

        // 4. Target check (immediate success)
        if (grid[y][x] == CellType.TARGET.getCode()) {
            return true;
        }

        int nextX = x + DX[dir];
        int nextY = y + DY[dir];

        // Try moving in the same direction with the same tleft
        if (explore(dir, nextX, nextY, grid, visited, tleft, rows, cols)) {
            return true;
        }

        // Try moving in the same direction with tleft - 1
        if (tleft > 0 && explore(dir, nextX, nextY, grid, visited, tleft - 1, rows, cols)) {
            return true;
        }

        return false;
    }
}

import java.io.InputStream;
import java.io.OutputStream;
import java.io.IOException;
import java.io.PrintWriter;
import java.util.Arrays;
import java.util.Deque;
import java.util.ArrayDeque;
import java.util.InputMismatchException;

/**
 * Entry point for the competitive programming solution.
 * Solves a grid pathfinding problem with a minimum-turn constraint using 0-1 BFS.
 */
public class Main {
    private static final int INF = Integer.MAX_VALUE;
    private static final int MAX_TURNS = 2;
    private static final int[] DR = {1, 0, -1, 0}; // Down, Right, Up, Left
    private static final int[] DC = {0, 1, 0, -1};

    public static void main(String[] args) {
        FastReader in = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);
        new TaskB().solve(in, out);
        out.close();
    }

    /**
     * Core solver for Task B.
     * Uses a 0-1 BFS to find the shortest path from 'S' to 'T' 
     * where changing direction costs 1 turn.
     */
    static class TaskB {
        public void solve(FastReader in, PrintWriter out) {
            int n = in.nextInt();
            int m = in.nextInt();
            char[][] grid = in.nextCharacterMap(n, m);

            int startRow = -1, startCol = -1;
            int targetRow = -1, targetCol = -1;

            // Locate start and target positions, treating them as walkable terrain
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    if (grid[i][j] == 'S') {
                        startRow = i;
                        startCol = j;
                        grid[i][j] = '.';
                    } else if (grid[i][j] == 'T') {
                        targetRow = i;
                        targetCol = j;
                        grid[i][j] = '.';
                    }
                }
            }

            // dist[dir][row][col] stores the minimum turns to reach (row, col) 
            // arriving from direction 'dir'.
            int[][][] dist = new int[4][n][m];
            fill(dist, INF);

            Deque<State> deque = new ArrayDeque<>();
            // Initialize BFS with all 4 directions from the starting point (0 turns)
            for (int dir = 0; dir < 4; dir++) {
                dist[dir][startRow][startCol] = 0;
                deque.addFirst(new State(dir, startRow, startCol));
            }

            while (!deque.isEmpty()) {
                State current = deque.pollFirst();

                // Early exit: first time we pop the target, it's the optimal path
                if (current.r == targetRow && current.c == targetCol) {
                    out.println(dist[current.dir][current.r][current.c] <= MAX_TURNS ? "YES" : "NO");
                    return;
                }

                int currentDist = dist[current.dir][current.r][current.c];

                for (int nextDir = 0; nextDir < 4; nextDir++) {
                    int nr = current.r + DR[nextDir];
                    int nc = current.c + DC[nextDir];

                    if (isValid(nr, nc, n, m) && grid[nr][nc] == '.') {
                        // Moving in the same direction costs 0 turns, otherwise 1 turn
                        int newDist = (current.dir == nextDir) ? currentDist : currentDist + 1;

                        if (dist[nextDir][nr][nc] > newDist) {
                            dist[nextDir][nr][nc] = newDist;
                            // 0-1 BFS: push to front for 0-cost, back for 1-cost
                            if (current.dir == nextDir) {
                                deque.addFirst(new State(nextDir, nr, nc));
                            } else {
                                deque.addLast(new State(nextDir, nr, nc));
                            }
                        }
                    }
                }
            }

            out.println("NO");
        }

        private boolean isValid(int r, int c, int n, int m) {
            return r >= 0 && r < n && c >= 0 && c < m;
        }

        private void fill(int[][][] array, int value) {
            for (int[][] sub : array) {
                for (int[] row : sub) {
                    Arrays.fill(row, value);
                }
            }
        }

        /**
         * Represents a state in the BFS: (direction, row, column).
         */
        private static class State {
            final int dir;
            final int r;
            final int c;

            State(int dir, int r, int c) {
                this.dir = dir;
                this.r = r;
                this.c = c;
            }
        }
    }

    /**
     * Fast I/O reader optimized for competitive programming environments.
     */
    static class FastReader {
        private final InputStream stream;
        private final byte[] buf = new byte[1024];
        private int curChar;
        private int pnumChars;
        private SpaceCharFilter filter;

        public FastReader(InputStream stream) {
            this.stream = stream;
        }

        public int read() {
            if (pnumChars == -1) {
                throw new InputMismatchException();
            }
            if (curChar >= pnumChars) {
                curChar = 0;
                try {
                    pnumChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (pnumChars <= 0) {
                    return -1;
                }
            }
            return buf[curChar++];
        }

        public int nextInt() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            int res = 0;
            do {
                if (c == ',') {
                    c = read();
                }
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                res *= 10;
                res += c - '0';
                c = read();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public boolean isSpaceChar(int c) {
            return filter != null ? filter.isSpaceChar(c) : isWhitespace(c);
        }

        public static boolean isWhitespace(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        public char nextCharacter() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            return (char) c;
        }

        public char[] nextCharacterArray(int n) {
            char[] chars = new char[n];
            for (int i = 0; i < n; i++) {
                chars[i] = nextCharacter();
            }
            return chars;
        }

        public char[][] nextCharacterMap(int n, int m) {
            char[][] map = new char[n][];
            for (int i = 0; i < n; i++) {
                map[i] = nextCharacterArray(m);
            }
            return map;
        }

        public interface SpaceCharFilter {
            boolean isSpaceChar(int ch);
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.OutputStream;
import java.io.PrintWriter;
import java.util.ArrayDeque;
import java.util.Arrays;
import java.util.Queue;
import java.util.StringTokenizer;

public class Main {
    // Configuration constants
    private static final char START_CHAR = 'S';
    private static final char END_CHAR = 'T';
    private static final char BLOCK_CHAR = '*';
    private static final int MAX_TURNS = 2;
    private static final int INF = Integer.MAX_VALUE;

    // Direction vectors: Left, Up, Right, Down
    private static final int[][] DIRECTIONS = {
        {0, -1}, {-1, 0}, {0, 1}, {1, 0}
    };

    public static void main(String[] args) {
        // Use try-with-resources for automatic resource management
        try (InputStream inputStream = System.in;
             OutputStream outputStream = System.out) {
            InputReader in = new InputReader(inputStream);
            PrintWriter out = new PrintWriter(outputStream);
            new TaskB().solve(in, out);
            out.flush(); // Ensure buffered output is written
        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    static class TaskB {
        public void solve(InputReader in, PrintWriter out) {
            int rows = in.nextInt();
            int cols = in.nextInt();
            char[][] grid = new char[rows][cols];
            Point start = null;
            Point end = null;

            // Parse grid and locate start/end coordinates
            for (int r = 0; r < rows; r++) {
                String line = in.next();
                grid[r] = line.toCharArray();
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] == START_CHAR) start = new Point(r, c);
                    else if (grid[r][c] == END_CHAR) end = new Point(r, c);
                }
            }

            // Early exit if start or end is missing
            if (start == null || end == null) {
                out.println("NO");
                return;
            }

            // dist[r][c][dir] stores minimum turns to reach (r, c) facing dir
            int[][][] dist = new int[rows][cols][DIRECTIONS.length];
            for (int[][] layer : dist) {
                for (int[] row : layer) Arrays.fill(row, INF);
            }

            Queue<State> queue = new ArrayDeque<>();
            // Initialize BFS with start position facing all 4 directions
            for (int d = 0; d < DIRECTIONS.length; d++) {
                dist[start.r][start.c][d] = 0;
                queue.add(new State(start.r, start.c, d));
            }

            // BFS to find minimum turns path
            while (!queue.isEmpty()) {
                State current = queue.poll();
                int turns = dist[current.r][current.c][current.d];

                // Prune paths that exceed the allowed turn limit
                if (turns > MAX_TURNS) continue;

                // 1. Move straight in the current direction
                int nr = current.r + DIRECTIONS[current.d][0];
                int nc = current.c + DIRECTIONS[current.d][1];
                while (isValid(nr, nc, rows, cols) && grid[nr][nc] != BLOCK_CHAR && dist[nr][nc][current.d] > turns) {
                    dist[nr][nc][current.d] = turns;
                    queue.add(new State(nr, nc, current.d));
                    nr += DIRECTIONS[current.d][0];
                    nc += DIRECTIONS[current.d][1];
                }

                // 2. Try turning in other directions
                if (turns + 1 <= MAX_TURNS) {
                    for (int d = 0; d < DIRECTIONS.length; d++) {
                        if (d == current.d) continue;
                        nr = current.r + DIRECTIONS[d][0];
                        nc = current.c + DIRECTIONS[d][1];
                        while (isValid(nr, nc, rows, cols) && grid[nr][nc] != BLOCK_CHAR && dist[nr][nc][d] > turns + 1) {
                            dist[nr][nc][d] = turns + 1;
                            queue.add(new State(nr, nc, d));
                            nr += DIRECTIONS[d][0];
                            nc += DIRECTIONS[d][1];
                        }
                    }
                }
            }

            // Determine minimum turns to reach the end point in any direction
            int minTurns = INF;
            for (int d = 0; d < DIRECTIONS.length; d++) {
                minTurns = Math.min(minTurns, dist[end.r][end.c][d]);
            }
            out.println(minTurns <= MAX_TURNS ? "YES" : "NO");
        }

        private boolean isValid(int r, int c, int rows, int cols) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }

        // Immutable data class for grid coordinates
        private static final class Point {
            final int r, c;
            Point(int r, int c) { this.r = r; this.c = c; }
        }

        // Immutable data class for BFS state (row, col, direction)
        private static final class State {
            final int r, c, d;
            State(int r, int c, int d) { this.r = r; this.c = c; this.d = d; }
        }
    }

    // Fast I/O helper for competitive programming / large inputs
    static class InputReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) throw new IOException("Unexpected end of input");
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.util.Scanner;

public class Solution {
    // Constants to represent grid cell types for better readability and maintainability
    private static final int TYPE_OFFICE = 0;
    private static final int TYPE_START = 4;
    private static final int TYPE_EMPTY = 4;
    private static final int TYPE_WALL = -1;
    private static final int TYPE_SPECIAL_1 = 1;
    private static final int TYPE_SPECIAL_2 = 2;

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        // Read dimensions (m rows, n columns)
        // Using trim() and regex split for robustness against multiple spaces
        if (!scanner.hasNextLine()) {
            return;
        }

        String[] dimensions = scanner.nextLine().trim().split("\\s+");
        int rows = Integer.parseInt(dimensions[0]);
        int cols = Integer.parseInt(dimensions[1]);

        int[][] grid = new int[rows][cols];
        int[] homePos = new int[2];
        int[] officePos = new int[2];

        // Parse the grid from input
        for (int i = 0; i < rows; i++) {
            String line = scanner.nextLine();
            char[] chars = line.toCharArray();
            for (int j = 0; j < cols; j++) {
                char c = chars[j];
                if (c == 'T') {
                    grid[i][j] = TYPE_OFFICE;
                    officePos[0] = i;
                    officePos[1] = j;
                } else if (c == 'S') {
                    grid[i][j] = TYPE_START;
                    homePos[0] = i;
                    homePos[1] = j;
                } else if (c == '.') {
                    grid[i][j] = TYPE_EMPTY;
                } else {
                    grid[i][j] = TYPE_WALL;
                }
            }
        }

        // Check if a path exists directly from Office to Home.
        // Note: Based on the original 'dewIt' logic, it searches from (a,b) to (x,y).
        // The original call was: dewIt(..., home[0], home[1], office[0], office[1])
        // This implies searching from Office (source) to Home (target).
        if (canReach(grid, rows, cols, homePos[0], homePos[1], officePos[0], officePos[1])) {
            System.out.println("YES");
            return;
        }

        // Check paths starting from cells with value 1
        if (checkFromSpecialCells(grid, rows, cols, homePos, officePos, TYPE_SPECIAL_1)) {
            System.out.println("YES");
            return;
        }

        // Check paths starting from cells with value 2
        if (checkFromSpecialCells(grid, rows, cols, homePos, officePos, TYPE_SPECIAL_2)) {
            System.out.println("YES");
            return;
        }

        System.out.println("NO");
        scanner.close();
    }

    /**
     * Helper method to check if any cell with a specific value allows reaching the target.
     * Iterates through the grid to find cells matching the special value and attempts pathfinding.
     */
    private static boolean checkFromSpecialCells(int[][] grid, int rows, int cols, int[] homePos, int[] officePos, int specialValue) {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == specialValue) {
                    // Check if path exists from this special cell to Home
                    // Original logic: dewIt(grid, n, m, home[0], home[1], i, j)
                    // Source: (i, j), Target: homePos
                    if (canReach(grid, rows, cols, homePos[0], homePos[1], i, j)) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Checks if a path exists from source (sourceX, sourceY) to target (targetX, targetY).
     * Traverses in straight lines (Down, Up, Right, Left) until blocked or target reached.
     * Modifies the grid in place by marking visited cells with a specific value 'p'.
     */
    private static boolean canReach(int[][] grid, int rows, int cols, int targetX, int targetY, int sourceX, int sourceY) {
        // Calculate the threshold value for traversal.
        // Based on original logic: p = grid[a][b] + 1
        int p = grid[sourceX][sourceY] + 1;

        // Directions: Down, Up, Right, Left
        // Corresponds to original loop order:
        // 1. i from a+1 to m (Down)
        // 2. i from a-1 to -1 (Up)
        // 3. j from b+1 to n (Right)
        // 4. j from b-1 to -1 (Left)
        int[] dRow = {1, -1, 0, 0};
        int[] dCol = {0, 0, 1, -1};

        for (int d = 0; d < 4; d++) {
            int r = sourceX + dRow[d];
            int c = sourceY + dCol[d];

            // Traverse along the current direction
            while (r >= 0 && r < rows && c >= 0 && c < cols) {
                // If cell value is less than threshold, path is blocked
                if (grid[r][c] < p) {
                    break;
                }

                // If target is reached, return true
                if (r == targetX && c == targetY) {
                    return true;
                }

                // Mark the current cell as visited/modified
                grid[r][c] = p;

                // Move to the next cell in the current direction
                r += dRow[d];
                c += dCol[d];
            }
        }

        return false;
    }
}

import java.io.*;
import java.util.*;

public class Main {
    // Constants extracted from magic numbers
    private static final int MAX_TURNS = 2;
    private static final int[] DR = {-1, 0, 1, 0};
    private static final int[] DC = {0, -1, 0, 1};

    public static void main(String[] args) {
        // Try-with-resources ensures proper cleanup of I/O streams
        try (ConsoleIO io = new ConsoleIO(System.in, System.out)) {
            new Main().solve(io);
        }
    }

    void solve(ConsoleIO io) {
        int[] dims = io.readIntArray();
        if (dims.length < 2) return;

        int n = dims[0];
        int m = dims[1];

        char[][] grid = new char[n][m];
        int startR = 0, startC = 0;

        // Read grid and locate starting position
        for (int i = 0; i < n; i++) {
            String line = io.readLine();
            if (line == null) break;
            grid[i] = line.toCharArray();
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == 'S') {
                    startR = i;
                    startC = j;
                }
            }
        }

        // BFS initialization
        Deque<State> queue = new ArrayDeque<>();
        // visited[row][col][turns][direction]
        boolean[][][][] visited = new boolean[n][m][MAX_TURNS + 1][4];

        // Push all 4 initial directions at the starting position with 0 turns
        for (int d = 0; d < 4; d++) {
            queue.add(new State(startR, startC, d, 0));
            visited[startR][startC][0][d] = true;
        }

        // BFS loop
        while (!queue.isEmpty()) {
            State current = queue.poll();

            // Check if target is reached
            if (grid[current.r][current.c] == 'T') {
                io.println("YES");
                return;
            }

            // Explore adjacent cells
            for (int nextD = 0; nextD < 4; nextD++) {
                int nr = current.r + DR[nextD];
                int nc = current.c + DC[nextD];

                // Boundary and obstacle check
                if (nr >= 0 && nr < n && nc >= 0 && nc < m && grid[nr][nc] != '*') {
                    // Calculate turns: increment if direction changes
                    int nextTurns = current.turns + (nextD != current.dir ? 1 : 0);

                    // Enforce turn limit
                    if (nextTurns > MAX_TURNS) continue;

                    // Process unvisited states
                    if (!visited[nr][nc][nextTurns][nextD]) {
                        visited[nr][nc][nextTurns][nextD] = true;
                        queue.add(new State(nr, nc, nextD, nextTurns));
                    }
                }
            }
        }

        io.println("NO");
    }

    /**
     * Represents a state in the BFS traversal.
     * Immutable for thread-safety and clarity.
     */
    private static class State {
        final int r, c, dir, turns;

        State(int r, int c, int dir, int turns) {
            this.r = r;
            this.c = c;
            this.dir = dir;
            this.turns = turns;
        }
    }

    /**
     * Simplified and hardened I/O helper class.
     * Implements AutoCloseable for resource management.
     */
    static class ConsoleIO implements AutoCloseable {
        private final BufferedReader br;
        private final PrintWriter out;

        public ConsoleIO(InputStream in, OutputStream out) {
            this.br = new BufferedReader(new InputStreamReader(in));
            this.out = new PrintWriter(new BufferedOutputStream(out));
        }

        public String readLine() {
            try {
                return br.readLine();
            } catch (IOException e) {
                throw new UncheckedIOException(e);
            }
        }

        public int[] readIntArray() {
            String line = readLine().trim();
            if (line.isEmpty()) return new int[0];
            String[] tokens = line.split("\\s+");
            int[] result = new int[tokens.length];
            for (int i = 0; i < tokens.length; i++) {
                result[i] = Integer.parseInt(tokens[i]);
            }
            return result;
        }

        public void println(String s) {
            out.println(s);
        }

        public void flush() {
            out.flush();
        }

        @Override
        public void close() {
            out.close();
        }
    }
}

import java.io.*;
import java.util.*;

public class Solution {
    // Output constants
    private static final String YES_OUTPUT = "YES\n";
    private static final String NO_OUTPUT = "NO\n";

    // Grid character constants
    private static final char START_CHAR = 'S';
    private static final char TARGET_CHAR = 'T';
    private static final char EMPTY_CHAR = '.';

    // State identifiers for the grid traversal
    private static final int STATE_UNVISITED = 0;
    private static final int STATE_TARGET_REACHABLE = 1;
    private static final int STATE_START_REACHABLE = 2;
    private static final int STATE_VISITED = 3;

    /**
     * Immutable coordinate class for cleaner array handling
     */
    private static class Point {
        final int r, c;
        Point(int r, int c) { this.r = r; this.c = c; }
    }

    public static void main(String[] args) throws IOException {
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
             PrintWriter out = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)))) {

            StringTokenizer st = new StringTokenizer(br.readLine());
            int n = Integer.parseInt(st.nextToken());
            int m = Integer.parseInt(st.nextToken());

            String[] grid = new String[n];
            for (int i = 0; i < n; i++) {
                grid[i] = br.readLine().trim();
            }

            Point start = null;
            Point target = null;

            // Locate start and target positions
            for (int i = 0; i < n; i++) {
                String row = grid[i];
                for (int j = 0; j < m; j++) {
                    char ch = row.charAt(j);
                    if (ch == START_CHAR) start = new Point(i, j);
                    else if (ch == TARGET_CHAR) target = new Point(i, j);
                }
            }

            int[][] state = new int[n][m];

            // Mark the cross extending from the target cell
            if (traverseAndMark(state, grid, target.r, target.c, -1, 0, STATE_TARGET_REACHABLE, START_CHAR)) { out.write(YES_OUTPUT); return; }
            if (traverseAndMark(state, grid, target.r, target.c, 1, 0, STATE_TARGET_REACHABLE, START_CHAR)) { out.write(YES_OUTPUT); return; }
            if (traverseAndMark(state, grid, target.r, target.c, 0, -1, STATE_TARGET_REACHABLE, START_CHAR)) { out.write(YES_OUTPUT); return; }
            if (traverseAndMark(state, grid, target.r, target.c, 0, 1, STATE_TARGET_REACHABLE, START_CHAR)) { out.write(YES_OUTPUT); return; }

            ArrayDeque<Point> queue = new ArrayDeque<>();
            state[start.r][start.c] = STATE_START_REACHABLE;
            queue.add(start);

            // Mark the cross extending from the start cell
            if (traverseAndMark(state, grid, start.r, start.c, -1, 0, STATE_START_REACHABLE, TARGET_CHAR)) { out.write(YES_OUTPUT); return; }
            if (traverseAndMark(state, grid, start.r, start.c, 1, 0, STATE_START_REACHABLE, TARGET_CHAR)) { out.write(YES_OUTPUT); return; }
            if (traverseAndMark(state, grid, start.r, start.c, 0, -1, STATE_START_REACHABLE, TARGET_CHAR)) { out.write(YES_OUTPUT); return; }
            if (traverseAndMark(state, grid, start.r, start.c, 0, 1, STATE_START_REACHABLE, TARGET_CHAR)) { out.write(YES_OUTPUT); return; }

            // BFS expansion to find a connection between the two crosses
            int[] dr = {-1, 1, 0, 0};
            int[] dc = {0, 0, -1, 1};

            while (!queue.isEmpty()) {
                Point p = queue.poll();
                for (int dir = 0; dir < 4; dir++) {
                    int r = p.r;
                    int c = p.c;
                    while (true) {
                        r += dr[dir];
                        c += dc[dir];
                        if (r < 0 || r >= n || c < 0 || c >= m) break;

                        char cell = grid[r].charAt(c);
                        if (cell == TARGET_CHAR || state[r][c] == STATE_TARGET_REACHABLE) {
                            out.write(YES_OUTPUT);
                            return;
                        }
                        if (cell != EMPTY_CHAR) break;
                        state[r][c] = STATE_VISITED;
                    }
                }
            }

            out.write(NO_OUTPUT);
        }
    }

    /**
     * Traverses a single direction from a starting cell, marking cells with a specific state.
     * Returns true if the stop character is encountered, false otherwise.
     */
    private static boolean traverseAndMark(int[][] state, String[] grid, int startR, int startC, 
                                           int dR, int dC, int markState, char stopChar) {
        int r = startR;
        int c = startC;
        while (r >= 0 && r < state.length && c >= 0 && c < state[0].length) {
            char cell = grid[r].charAt(c);
            if (cell == stopChar) return true;
            if (cell != EMPTY_CHAR) break;
            state[r][c] = markState;
            r += dR;
            c += dC;
        }
        return false;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.Arrays;
import java.util.ArrayDeque;
import java.util.Deque;

public class PathFinder {

    // Configuration constants
    private static final int MAX_TURNS = 2;
    private static final int UNVISITED = Integer.MAX_VALUE;

    // Direction vectors: UP, RIGHT, DOWN, LEFT (row_delta, col_delta)
    private static final int[] DR = {-1, 0, 1, 0};
    private static final int[] DC = {0, 1, 0, -1};

    // Grid state
    private static int[][][] minTurns;
    private static char[][] grid;
    private static Point start;
    private static Point target;
    private static int rows;
    private static int cols;

    public static void main(String[] args) throws IOException {
        // Try-with-resources ensures BufferedReader is closed automatically
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            String line = br.readLine();
            if (line == null) return;

            String[] dims = line.trim().split("\\s+");
            rows = Integer.parseInt(dims[0]);
            cols = Integer.parseInt(dims[1]);

            grid = new char[rows][cols];
            minTurns = new int[rows][cols][4];

            // Initialize visited array with infinity
            for (int[][] layer : minTurns) {
                for (int[] row : layer) {
                    Arrays.fill(row, UNVISITED);
                }
            }

            // Parse grid input
            for (int i = 0; i < rows; i++) {
                String rowStr = br.readLine();
                if (rowStr == null) break;
                for (int j = 0; j < cols; j++) {
                    char c = rowStr.charAt(j);
                    grid[i][j] = c;
                    if (c == '*') {
                        for (int k = 0; k < 4; k++) minTurns[i][j][k] = -1;
                    } else if (c == 'S') {
                        start = new Point(i, j);
                    } else if (c == 'T') {
                        target = new Point(i, j);
                    }
                }
            }

            if (start == null || target == null) {
                System.out.println("NO");
                return;
            }

            // Run pathfinding algorithm
            explore(start);

            // Check if target is reachable within MAX_TURNS
            boolean reachable = false;
            for (int k = 0; k < 4; k++) {
                if (minTurns[target.r][target.c][k] <= MAX_TURNS) {
                    reachable = true;
                    break;
                }
            }

            System.out.println(reachable ? "YES" : "NO");
        }
    }

    /**
     * Iterative DFS to explore paths while tracking direction changes.
     */
    private static void explore(Point startPoint) {
        Deque<State> stack = new ArrayDeque<>();

        // Initialize all starting directions with 0 turns
        for (Direction dir : Direction.values()) {
            minTurns[startPoint.r][startPoint.c][dir.ordinal()] = 0;
            stack.push(new State(startPoint, dir));
        }

        while (!stack.isEmpty()) {
            State current = stack.pop();
            Point p = current.point;
            Direction dir = current.dir;

            if (p.equals(target)) continue;

            int currentTurns = minTurns[p.r][p.c][dir.ordinal()];

            for (Direction nextDir : Direction.values()) {
                int nextR = p.r + DR[nextDir.ordinal()];
                int nextC = p.c + DC[nextDir.ordinal()];

                if (!isValid(nextR, nextC)) continue;
                if (grid[nextR][nextC] == '*') continue;

                // Calculate turns: increment if direction changes
                int nextTurns = (nextDir != dir) ? currentTurns + 1 : currentTurns;
                if (nextTurns > MAX_TURNS) continue;

                // Relaxation step: only proceed if we found a path with fewer turns
                if (nextTurns < minTurns[nextR][nextC][nextDir.ordinal()]) {
                    minTurns[nextR][nextC][nextDir.ordinal()] = nextTurns;
                    stack.push(new State(new Point(nextR, nextC), nextDir));
                }
            }
        }
    }

    /**
     * Checks if a coordinate is within grid boundaries.
     */
    private static boolean isValid(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /**
     * Represents a grid coordinate.
     */
    private static class Point {
        final int r, c;
        Point(int r, int c) { this.r = r; this.c = c; }

        @Override
        public boolean equals(Object o) {
            if (this == o) return true;
            if (!(o instanceof Point)) return false;
            Point point = (Point) o;
            return r == point.r && c == point.c;
        }
    }

    /**
     * Represents a search state containing position and current movement direction.
     */
    private static class State {
        final Point point;
        final Direction dir;
        State(Point p, Direction d) { point = p; dir = d; }
    }

    /**
     * Enum for cardinal directions. Ordinal values map directly to DR/DC arrays.
     */
    private enum Direction { UP, RIGHT, DOWN, LEFT }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.ArrayDeque;
import java.util.Queue;
import java.util.StringTokenizer;

public class TinkoffB {
    // Direction vectors: North, East, South, West
    private static final int[] DR = {-1, 0, 1, 0};
    private static final int[] DC = {0, 1, 0, -1};
    private static final int MAX_TURNS = 2;

    public static void main(String[] args) {
        FastScanner in = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out);
        new Solver().solve(in, out);
        out.flush();
    }

    static class Solver {
        public void solve(FastScanner in, PrintWriter out) {
            int n = in.nextInt();
            int m = in.nextInt();
            char[][] grid = new char[n][m];
            int startR = 0, startC = 0, endR = 0, endC = 0;

            // Parse grid and locate start/end positions
            for (int i = 0; i < n; i++) {
                String row = in.next();
                grid[i] = row.toCharArray();
                for (int j = 0; j < m; j++) {
                    if (grid[i][j] == 'S') {
                        startR = i;
                        startC = j;
                        grid[i][j] = '.'; // Treat start as empty space for traversal
                    } else if (grid[i][j] == 'T') {
                        endR = i;
                        endC = j;
                    }
                }
            }

            // BFS state: [row][col][direction][turns_used]
            // Java initializes boolean arrays to false by default, so explicit initialization is unnecessary.
            boolean[][][][] visited = new boolean[n][m][4][MAX_TURNS + 1];
            Queue<State> queue = new ArrayDeque<>();

            // Initialize BFS with all 4 starting directions (0 turns used)
            for (int d = 0; d < 4; d++) {
                queue.add(new State(startR, startC, d, 0));
                visited[startR][startC][d][0] = true;
            }

            boolean possible = false;
            while (!queue.isEmpty()) {
                State current = queue.poll();

                // Explore all 4 adjacent cells
                for (int d = 0; d < 4; d++) {
                    int nr = current.r + DR[d];
                    int nc = current.c + DC[d];

                    // Check boundaries and obstacles
                    if (nr >= 0 && nr < n && nc >= 0 && nc < m && grid[nr][nc] == '.') {
                        // Calculate turns used: increment if direction changes
                        int newTurns = (d == current.dir) ? current.turns : current.turns + 1;

                        if (newTurns <= MAX_TURNS && !visited[nr][nc][d][newTurns]) {
                            visited[nr][nc][d][newTurns] = true;

                            // Early exit if target is reached
                            if (nr == endR && nc == endC) {
                                possible = true;
                                break;
                            }
                            queue.add(new State(nr, nc, d, newTurns));
                        }
                    }
                }
                if (possible) break;
            }

            out.println(possible ? "YES" : "NO");
        }

        // Represents a state in the BFS: position, facing direction, and turns used so far
        static class State {
            int r, c, dir, turns;

            State(int r, int c, int dir, int turns) {
                this.r = r;
                this.c = c;
                this.dir = dir;
                this.turns = turns;
            }
        }
    }

    // Fast I/O helper class
    static class FastScanner {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        FastScanner(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) throw new IOException("Unexpected end of input");
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

/**
 * Solves the pathfinding problem where a vehicle can move on a grid.
 * The vehicle can move straight or turn, but can only turn at most twice
 * before being forced to continue straight.
 */
public class IgorAndHisWayToWork {

    public static void main(String[] args) throws IOException {
        FastReader reader = new FastReader(System.in);
        String nStr = reader.next();
        if (nStr == null) return;

        int n = Integer.parseInt(nStr);
        int m = reader.nextInt();

        char[][] grid = new char[n][m];
        Point start = null;
        Point end = null;

        for (int i = 0; i < n; i++) {
            String row = reader.next();
            grid[i] = row.toCharArray();
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == 'S') {
                    start = new Point(i, j);
                } else if (grid[i][j] == 'T') {
                    end = new Point(i, j);
                }
            }
        }

        GridPathfinder pathfinder = new GridPathfinder(n, m, grid, start, end);
        System.out.println(pathfinder.canReach() ? "YES" : "NO");
    }

    /**
     * Encapsulates the grid state and pathfinding logic.
     * Replaces the original static globals with instance fields for better testability and reusability.
     */
    private static class GridPathfinder {
        private final int n, m;
        private final char[][] grid;
        private final Point start, end;
        private final boolean[][][][] visited;

        // Direction constants: 0=Right, 1=Left, 2=Up, 3=Down
        private static final int DIR_RIGHT = 0;
        private static final int DIR_LEFT = 1;
        private static final int DIR_UP = 2;
        private static final int DIR_DOWN = 3;

        // Delta arrays mapping direction index to (dx, dy)
        private static final int[] DX = {0, 0, -1, 1};
        private static final int[] DY = {1, -1, 0, 0};

        public GridPathfinder(int n, int m, char[][] grid, Point start, Point end) {
            this.n = n;
            this.m = m;
            this.grid = grid;
            this.start = start;
            this.end = end;
            // visited[x][y][turns][dir]
            // turns: 0..2 (max 2 consecutive straight moves before a turn is allowed)
            // dir: 0..3
            this.visited = new boolean[n][m][3][4];
        }

        public boolean canReach() {
            if (start == null || end == null) {
                return false;
            }
            // Try all 4 initial directions from the start position
            return dfs(start.x, start.y, 0, DIR_RIGHT) ||
                   dfs(start.x, start.y, 0, DIR_LEFT) ||
                   dfs(start.x, start.y, 0, DIR_UP) ||
                   dfs(start.x, start.y, 0, DIR_DOWN);
        }

        private boolean dfs(int x, int y, int turns, int dir) {
            // Check if target reached
            if (x == end.x && y == end.y) {
                return true;
            }
            // Check obstacle
            if (grid[x][y] == '*') {
                return false;
            }
            // Check if state already visited
            if (visited[x][y][turns][dir]) {
                return false;
            }
            visited[x][y][turns][dir] = true;

            // Explore all 4 possible directions
            for (int nextDir = 0; nextDir < 4; nextDir++) {
                int newTurns = turns;
                boolean isStraight = (nextDir == dir);
                boolean isPerpendicular = (dir <= 1 && nextDir >= 2) || (dir >= 2 && nextDir <= 1);

                if (isStraight) {
                    // Continue straight: turns count remains unchanged
                } else if (isPerpendicular) {
                    // Turning: only allowed if turn limit hasn't been reached
                    if (turns >= 2) {
                        continue;
                    }
                    newTurns = turns + 1;
                } else {
                    // 180-degree turns are not allowed by original logic
                    continue;
                }

                int nx = x + DX[nextDir];
                int ny = y + DY[nextDir];

                // Boundary validation
                if (nx >= 0 && nx < n && ny >= 0 && ny < m) {
                    if (dfs(nx, ny, newTurns, nextDir)) {
                        return true;
                    }
                }
            }
            return false;
        }
    }

    /**
     * Simple immutable coordinate class.
     */
    private static class Point {
        final int x, y;

        Point(int x, int y) {
            this.x = x;
            this.y = y;
        }
    }

    /**
     * Fast input reader using BufferedReader and StringTokenizer.
     * Fixes the newline consumption bug present in the original custom Scanner.
     */
    private static class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastReader(InputStream in) {
            this.br = new BufferedReader(new InputStreamReader(in));
        }

        public String next() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) {
                    return null;
                }
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

        public int nextInt() throws IOException {
            String s = next();
            if (s == null) {
                throw new IOException("Unexpected end of input");
            }
            return Integer.parseInt(s);
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.util.Arrays;
import java.util.StringTokenizer;

public class GridPathSolver {
    // Constants for readability and maintainability
    private static final int MAX_TURNS = 2;
    private static final int UNCOMPUTED = -1;
    private static final int RESULT_FALSE = 0;
    private static final int RESULT_TRUE = 1;

    private final int rows, cols;
    private final char[][] grid;
    private final boolean[][] visited;
    private final int[][][][] memo;
    private final Direction[] directions = Direction.values();

    public GridPathSolver(int rows, int cols, char[][] grid) {
        this.rows = rows;
        this.cols = cols;
        this.grid = grid;
        this.visited = new boolean[rows][cols];
        // memo[r][c][dir][turnsUsed] stores the result of the search
        // Dimensions: [rows][cols][4 directions][0 to MAX_TURNS]
        this.memo = new int[rows][cols][4][MAX_TURNS + 1];
        for (int[][] row2d : memo) {
            for (int[][] row1d : row2d) {
                for (int[] row : row1d) {
                    Arrays.fill(row, UNCOMPUTED);
                }
            }
        }
    }

    /**
     * Determines if the target 'T' is reachable from 'S' within the turn limit.
     */
    public boolean canReachTarget() {
        int startR = -1, startC = -1;
        // Locate the starting position
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == 'S') {
                    startR = i;
                    startC = j;
                }
            }
        }

        if (startR == -1) {
            return false; // No starting point found
        }

        // Try all four initial directions
        boolean possible = false;
        for (Direction d : directions) {
            if (canReach(startR, startC, d, 0)) {
                possible = true;
                break;
            }
        }
        return possible;
    }

    /**
     * Recursive DFS with memoization and backtracking to find a valid path.
     */
    private boolean canReach(int r, int c, Direction dir, int turnsUsed) {
        // Base cases: out of bounds, obstacle, or exceeded turn limit
        if (turnsUsed > MAX_TURNS || !isValid(r, c) || grid[r][c] == '*') {
            return false;
        }

        // Check memoization table
        int dirIndex = dir.ordinal();
        if (memo[r][c][dirIndex][turnsUsed] != UNCOMPUTED) {
            return memo[r][c][dirIndex][turnsUsed] == RESULT_TRUE;
        }

        // Target reached
        if (grid[r][c] == 'T') {
            memo[r][c][dirIndex][turnsUsed] = RESULT_TRUE;
            return true;
        }

        visited[r][c] = true;
        boolean canLeave = false;
        boolean canTake = false;

        // Option 1: Continue in the current direction (no turn cost)
        int nextR = r + dir.getDr();
        int nextC = c + dir.getDc();
        if (isValid(nextR, nextC) && !visited[nextR][nextC]) {
            canLeave = canReach(nextR, nextC, dir, turnsUsed);
        }

        // Option 2: Change direction (increment turn cost)
        for (Direction d : directions) {
            if (d == dir) continue; // Skip current direction
            int nextR2 = r + d.getDr();
            int nextC2 = c + d.getDc();
            if (isValid(nextR2, nextC2) && !visited[nextR2][nextC2] && grid[nextR2][nextC2] != '*') {
                canTake |= canReach(nextR2, nextC2, d, turnsUsed + 1);
            }
        }

        // Backtrack: unmark current cell for other paths
        visited[r][c] = false;

        // Store result in memo table
        boolean result = canLeave | canTake;
        memo[r][c][dirIndex][turnsUsed] = result ? RESULT_TRUE : RESULT_FALSE;
        return result;
    }

    /**
     * Checks if the given coordinates are within the grid boundaries.
     */
    private boolean isValid(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    public static void main(String[] args) throws IOException {
        FastReader sc = new FastReader(System.in);

        int R = sc.nextInt();
        int C = sc.nextInt();

        char[][] grid = new char[R][C];
        for (int i = 0; i < R; i++) {
            String line = sc.next();
            grid[i] = line.toCharArray();
        }

        GridPathSolver solver = new GridPathSolver(R, C, grid);
        System.out.println(solver.canReachTarget() ? "YES" : "NO");
    }

    /**
     * Enum representing grid movement directions.
     * Replaces magic number arrays (dx, dy) for better readability.
     */
    enum Direction {
        UP(-1, 0),
        DOWN(1, 0),
        LEFT(0, -1),
        RIGHT(0, 1);

        private final int dr, dc;

        Direction(int dr, int dc) {
            this.dr = dr;
            this.dc = dc;
        }

        public int getDr() { return dr; }
        public int getDc() { return dc; }
    }

    /**
     * Fast I/O helper class.
     * Replaces the original Scanner with a cleaner, more robust implementation.
     */
    static class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastReader(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        public String next() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) return null;
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

        public int nextInt() throws IOException {
            String s = next();
            return s == null ? 0 : Integer.parseInt(s);
        }

        public String nextLine() throws IOException {
            return br.readLine();
        }

        public char nextChar() throws IOException {
            return next().charAt(0);
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.util.ArrayDeque;
import java.util.Arrays;
import java.util.StringTokenizer;
import java.util.Queue;

public class TinkoffB {

    private static final char START_CHAR = 'S';
    private static final char TARGET_CHAR = 'T';
    private static final char OBSTACLE_CHAR = '*';
    private static final int MAX_ALLOWED_STEPS = 2;

    // Direction deltas: d=0 -> horizontal, d=1 -> vertical
    // DR[0] = {0, 0} and DC[0] = {-1, 1} for horizontal movement
    // DR[1] = {-1, 1} and DC[1] = {0, 0} for vertical movement
    private static final int[][] DR = {{0, 0}, {-1, 1}};
    private static final int[][] DC = {{-1, 1}, {0, 0}};

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner(System.in);
        int rows = scanner.nextInt();
        int cols = scanner.nextInt();

        char[][] grid = new char[rows][cols];
        int startR = 0, startC = 0;
        int targetR = 0, targetC = 0;

        // Parse grid and locate start/target positions
        for (int i = 0; i < rows; i++) {
            String line = scanner.next();
            for (int j = 0; j < cols; j++) {
                grid[i][j] = line.charAt(j);
                if (grid[i][j] == START_CHAR) {
                    startR = i;
                    startC = j;
                } else if (grid[i][j] == TARGET_CHAR) {
                    targetR = i;
                    targetC = j;
                }
            }
        }

        // BFS state: dist[d][r][c] stores minimum steps to reach (r,c) with orientation d
        int[][][] dist = new int[2][rows][cols];
        for (int d = 0; d < 2; d++) {
            for (int i = 0; i < rows; i++) {
                Arrays.fill(dist[d][i], Integer.MAX_VALUE);
            }
        }

        Queue<State> queue = new ArrayDeque<>();
        // Start in both orientations with 0 steps
        queue.add(new State(startR, startC, 0));
        queue.add(new State(startR, startC, 1));
        dist[0][startR][startC] = 0;
        dist[1][startR][startC] = 0;

        boolean reachable = false;

        while (!queue.isEmpty()) {
            State current = queue.poll();
            int r = current.r;
            int c = current.c;
            int d = current.d;
            int steps = dist[d][r][c];

            // Early termination if target is reached within allowed steps
            if (r == targetR && c == targetC && steps <= MAX_ALLOWED_STEPS) {
                reachable = true;
                break;
            }

            // Optimization: If steps already exceed limit, skip processing
            if (steps >= MAX_ALLOWED_STEPS) {
                continue;
            }

            // 1. Move in current direction (cost 0)
            // Using addFirst for 0-cost edges implements a proper 0-1 BFS
            int[] rowDeltas = DR[d];
            int[] colDeltas = DC[d];
            for (int k = 0; k < 2; k++) {
                int nextR = r + rowDeltas[k];
                int nextC = c + colDeltas[k];

                if (isInside(nextR, nextC, rows, cols) && grid[nextR][nextC] != OBSTACLE_CHAR) {
                    if (dist[d][nextR][nextC] > steps) {
                        dist[d][nextR][nextC] = steps;
                        queue.addFirst(new State(nextR, nextC, d));
                    }
                }
            }

            // 2. Switch direction (cost 1)
            int nextD = d ^ 1;
            int[] switchRowDeltas = DR[nextD];
            int[] switchColDeltas = DC[nextD];
            for (int k = 0; k < 2; k++) {
                int nextR = r + switchRowDeltas[k];
                int nextC = c + switchColDeltas[k];

                if (isInside(nextR, nextC, rows, cols) && grid[nextR][nextC] != OBSTACLE_CHAR) {
                    if (dist[nextD][nextR][nextC] > steps + 1) {
                        dist[nextD][nextR][nextC] = steps + 1;
                        queue.addLast(new State(nextR, nextC, nextD));
                    }
                }
            }
        }

        System.out.println(reachable ? "YES" : "NO");
    }

    private static boolean isInside(int r, int c, int rows, int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /**
     * Represents a state in the BFS: current coordinates and movement orientation.
     */
    private static class State {
        final int r, c, d;

        State(int r, int c, int d) {
            this.r = r;
            this.c = c;
            this.d = d;
        }
    }

    /**
     * Fast input reader optimized for competitive programming.
     */
    private static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            String s = next();
            if (s == null) throw new RuntimeException("Unexpected end of input");
            return Integer.parseInt(s);
        }
    }
}

import java.util.*;
import java.io.*;

public class CF_793B {
    // Extracted magic numbers for improved readability and maintainability
    private static final int MAX_ALLOWED_TURNS = 2;
    private static final int INF = Integer.MAX_VALUE;
    private static final int[][] DIRECTIONS = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};

    public static void main(String[] args) throws IOException {
        // Use BufferedReader for faster and more robust input handling
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());

        int n = Integer.parseInt(st.nextToken());
        int m = Integer.parseInt(st.nextToken());

        int[][] turns = new int[n][m];
        boolean[][] walkable = new boolean[n][m];
        int[] start = new int[2];
        int[] end = new int[2];

        // Initialize all cells with infinity to represent unvisited state
        for (int[] row : turns) {
            Arrays.fill(row, INF);
        }

        // Parse the grid, identify walkable cells, and locate start/end points
        for (int i = 0; i < n; i++) {
            String line = br.readLine();
            for (int j = 0; j < m; j++) {
                char ch = line.charAt(j);
                if (ch == 'S') {
                    start[0] = i;
                    start[1] = j;
                } else if (ch == 'T') {
                    end[0] = i;
                    end[1] = j;
                    walkable[i][j] = true;
                } else if (ch == '.') {
                    walkable[i][j] = true;
                }
            }
        }

        // BFS initialization
        Queue<int[]> queue = new ArrayDeque<>();
        queue.add(start);
        turns[start[0]][start[1]] = -1; // Start node marker to allow first move to count as 0 turns

        // BFS execution
        while (!queue.isEmpty()) {
            int[] current = queue.poll();
            int currentDist = turns[current[0]][current[1]];

            // Explore all four cardinal directions
            for (int[] dir : DIRECTIONS) {
                int r = current[0] + dir[0];
                int c = current[1] + dir[1];

                // Slide in the current direction until hitting a boundary, wall, or already visited cell
                while (r >= 0 && r < n && c >= 0 && c < m && walkable[r][c] && turns[r][c] > currentDist) {
                    turns[r][c] = currentDist + 1;
                    queue.add(new int[]{r, c});
                    r += dir[0];
                    c += dir[1];
                }
            }
        }

        // Output result based on minimum turns required to reach the target
        if (turns[end[0]][end[1]] <= MAX_ALLOWED_TURNS) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }
    }
}

import java.io.BufferedWriter;
import java.io.IOException;
import java.io.InputStream;
import java.io.OutputStream;
import java.io.OutputStreamWriter;
import java.io.PrintWriter;
import java.util.InputMismatchException;

/**
 * Main entry point for the grid analysis problem.
 * Reads a grid and determines if specific line-of-sight conditions are met.
 */
public class Main {

    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        OutputWriter out = new OutputWriter(outputStream);
        new TaskB().solve(in, out);
        out.close();
    }

    /**
     * Solver for Task B. Handles grid processing and validation.
     */
    static class TaskB {
        // Constants to eliminate magic characters and improve readability
        private static final char START = 'S';
        private static final char TARGET = 'T';
        private static final char OBSTACLE = '*';
        private static final char EMPTY = '.';
        private static final char MARK_START = '$';
        private static final char MARK_TARGET = '#';

        /**
         * Solves the problem for a given test case.
         * @param in  Input reader
         * @param out Output writer
         */
        public void solve(InputReader in, OutputWriter out) {
            int n = in.readInt();
            int m = in.readInt();
            char[][] grid = IOUtils.readTable(in, n, m);

            // Phase 1: Propagate marks from START and TARGET positions in all 4 directions
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    if (grid[i][j] == START || grid[i][j] == TARGET) {
                        char mark = grid[i][j] == START ? MARK_START : MARK_TARGET;
                        for (int dir = 0; dir < 4; dir++) {
                            int ni = i + MiscUtils.DX4[dir];
                            int nj = j + MiscUtils.DY4[dir];
                            while (MiscUtils.isValidCell(ni, nj, n, m) && grid[ni][nj] != OBSTACLE) {
                                if (grid[ni][nj] != EMPTY) {
                                    out.printLine("YES");
                                    return;
                                }
                                grid[ni][nj] = mark;
                                ni += MiscUtils.DX4[dir];
                                nj += MiscUtils.DY4[dir];
                            }
                        }
                    }
                }
            }

            // Phase 2: Check rows and columns for consecutive marks of the same type
            for (int i = 0; i < n; i++) {
                if (checkLine(grid, i, m, true, out)) {
                    return;
                }
            }
            for (int j = 0; j < m; j++) {
                if (checkLine(grid, j, n, false, out)) {
                    return;
                }
            }

            out.printLine("NO");
        }

        /**
         * Checks a single row or column for consecutive marks of the same type.
         * Note: Fixes a logical bug in the original implementation where tracking flags were swapped.
         */
        private boolean checkLine(char[][] grid, int index, int length, boolean isRow, OutputWriter out) {
            boolean seenStart = false;
            boolean seenTarget = false;

            for (int k = 0; k < length; k++) {
                char cell = isRow ? grid[index][k] : grid[k][index];
                if (cell == OBSTACLE) {
                    seenStart = false;
                    seenTarget = false;
                } else if (cell == MARK_TARGET) {
                    if (seenTarget) {
                        out.printLine("YES");
                        return true;
                    }
                    seenTarget = true;
                } else if (cell == MARK_START) {
                    if (seenStart) {
                        out.printLine("YES");
                        return true;
                    }
                    seenStart = true;
                }
            }
            return false;
        }
    }

    /**
     * High-performance input reader for competitive programming.
     */
    static class InputReader {
        private final InputStream stream;
        private final byte[] buffer = new byte[1024];
        private int bufferPtr;
        private int bytesRead;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        private byte read() {
            if (bufferPtr >= bytesRead) {
                bufferPtr = 0;
                try {
                    bytesRead = stream.read(buffer);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input stream", e);
                }
                if (bytesRead <= 0) {
                    throw new InputMismatchException("Unexpected end of input");
                }
            }
            return buffer[bufferPtr++];
        }

        public int readInt() {
            byte c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int result = 0;
            do {
                if (c < '0' || c > '9') {
                    throw new InputMismatchException("Invalid integer format");
                }
                result = result * 10 + (c - '0');
                c = read();
            } while (!isSpaceChar(c));
            return result * sign;
        }

        public char readCharacter() {
            byte c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            return (char) c;
        }

        private static boolean isSpaceChar(byte c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }
    }

    /**
     * Buffered output writer for competitive programming.
     */
    static class OutputWriter {
        private final PrintWriter writer;

        public OutputWriter(OutputStream outputStream) {
            this.writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(outputStream)));
        }

        public void print(Object... objects) {
            for (int i = 0; i < objects.length; i++) {
                if (i > 0) {
                    writer.print(' ');
                }
                writer.print(objects[i]);
            }
        }

        public void printLine(Object... objects) {
            print(objects);
            writer.println();
        }

        public void flush() {
            writer.flush();
        }

        public void close() {
            writer.close();
        }
    }

    /**
     * Utility methods for reading input data.
     */
    static class IOUtils {
        /**
         * Reads a single row of characters from the input.
         */
        public static char[] readCharArray(InputReader in, int size) {
            char[] array = new char[size];
            for (int i = 0; i < size; i++) {
                array[i] = in.readCharacter();
            }
            return array;
        }

        /**
         * Reads a 2D grid of characters.
         */
        public static char[][] readTable(InputReader in, int rowCount, int columnCount) {
            char[][] table = new char[rowCount][];
            for (int i = 0; i < rowCount; i++) {
                table[i] = readCharArray(in, columnCount);
            }
            return table;
        }
    }

    /**
     * Miscellaneous utility methods for grid operations.
     */
    static class MiscUtils {
        public static final int[] DX4 = {1, 0, -1, 0};
        public static final int[] DY4 = {0, -1, 0, 1};

        /**
         * Checks if the given coordinates are within the grid boundaries.
         */
        public static boolean isValidCell(int row, int column, int rowCount, int columnCount) {
            return row >= 0 && row < rowCount && column >= 0 && column < columnCount;
        }
    }
}

import java.io.*;
import java.util.*;

public class B {

    // Constants to replace magic numbers
    private static final int[] DX = {0, 0, -1, 1};
    private static final int[] DY = {1, -1, 0, 0};
    private static final int MAX_TURNS = 2;
    private static final int DIR_COUNT = 4;

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out));
        try {
            int n = scanner.nextInt();
            int m = scanner.nextInt();
            char[][] grid = new char[n][m];
            int startX = -1, startY = -1, endX = -1, endY = -1;

            // Parse grid and locate start/end points
            for (int i = 0; i < n; i++) {
                String row = scanner.next();
                grid[i] = row.toCharArray();
                for (int j = 0; j < m; j++) {
                    if (grid[i][j] == 'S') {
                        startX = i;
                        startY = j;
                    } else if (grid[i][j] == 'T') {
                        endX = i;
                        endY = j;
                    }
                }
            }

            // Execute BFS and output result
            boolean canReach = bfs(n, m, grid, startX, startY, endX, endY);
            out.println(canReach ? "YES" : "NO");
        } finally {
            out.flush();
            out.close();
        }
    }

    /**
     * Performs a BFS to determine if the target can be reached from the start position
     * with at most MAX_TURNS turns allowed.
     */
    private static boolean bfs(int n, int m, char[][] grid, int startX, int startY, int endX, int endY) {
        // visited[x][y][direction][remainingTurns]
        boolean[][][][] visited = new boolean[n][m][DIR_COUNT][MAX_TURNS + 1];
        Queue<State> queue = new ArrayDeque<>();

        // Initialize BFS queue with all 4 possible starting directions
        for (int dir = 0; dir < DIR_COUNT; dir++) {
            queue.add(new State(startX, startY, dir, MAX_TURNS));
            visited[startX][startY][dir][MAX_TURNS] = true;
        }

        while (!queue.isEmpty()) {
            State current = queue.poll();

            // Check if target reached
            if (current.x == endX && current.y == endY) {
                return true;
            }

            // Explore all 4 directions
            for (int dir = 0; dir < DIR_COUNT; dir++) {
                int nextX = current.x + DX[dir];
                int nextY = current.y + DY[dir];

                // Validate bounds and obstacles
                if (!isInBounds(nextX, nextY, n, m) || grid[nextX][nextY] == '*') {
                    continue;
                }

                int newTurns = current.remainingTurns;
                // If changing direction, consume a turn
                if (dir != current.direction) {
                    if (newTurns == 0) continue; // Cannot turn if no turns remain
                    newTurns--;
                }

                // Add to queue if state not visited
                if (!visited[nextX][nextY][dir][newTurns]) {
                    visited[nextX][nextY][dir][newTurns] = true;
                    queue.add(new State(nextX, nextY, dir, newTurns));
                }
            }
        }
        return false;
    }

    /**
     * Checks if coordinates are within grid boundaries.
     */
    private static boolean isInBounds(int x, int y, int n, int m) {
        return x >= 0 && x < n && y >= 0 && y < m;
    }

    /**
     * Represents a state in the BFS traversal.
     */
    static class State {
        final int x, y, direction, remainingTurns;

        State(int x, int y, int direction, int remainingTurns) {
            this.x = x;
            this.y = y;
            this.direction = direction;
            this.remainingTurns = remainingTurns;
        }
    }

    /**
     * Fast I/O utility for competitive programming.
     */
    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        public String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input", e);
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }

        public double nextDouble() {
            return Double.parseDouble(next());
        }

        public String nextLine() {
            try {
                return br.readLine();
            } catch (IOException e) {
                throw new RuntimeException("Failed to read line", e);
            }
        }

        public int[] nextIntArray(int n) {
            int[] a = new int[n];
            for (int i = 0; i < n; i++) a[i] = nextInt();
            return a;
        }

        public long[] nextLongArray(int n) {
            long[] a = new long[n];
            for (int i = 0; i < n; i++) a[i] = nextLong();
            return a;
        }

        public double[] nextDoubleArray(int n) {
            double[] a = new double[n];
            for (int i = 0; i < n; i++) a[i] = nextDouble();
            return a;
        }

        public char[][] nextGrid(int n, int m) {
            char[][] grid = new char[n][m];
            for (int i = 0; i < n; i++) grid[i] = next().toCharArray();
            return grid;
        }
    }
}

import java.io.*;
import java.util.*;

public class B_CF {
    // Direction vectors: 0=Down, 1=Right, 2=Up, 3=Left
    private static final int[] DR = {1, 0, -1, 0};
    private static final int[] DC = {0, 1, 0, -1};
    private static final int MAX_K = 3; // k ranges from 0 to 2
    private static final int TEST_CASES = 1; // Original hardcoded value

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out));

        for (int tc = 0; tc < TEST_CASES; tc++) {
            int n = scanner.nextInt();
            int m = scanner.nextInt();
            char[][] grid = readGrid(scanner, n, m);

            boolean canReach = solve(grid, n, m);
            out.println(canReach ? "YES" : "NO");
        }

        out.flush();
    }

    /**
     * Reads the n x m character grid from input.
     */
    private static char[][] readGrid(FastScanner scanner, int n, int m) {
        char[][] grid = new char[n][m];
        for (int i = 0; i < n; i++) {
            String row = scanner.next();
            grid[i] = row.toCharArray();
        }
        return grid;
    }

    /**
     * Orchestrates the search from all possible starting directions.
     */
    private static boolean solve(char[][] grid, int n, int m) {
        // visited[r][c][direction][k] tracks explored states to prevent cycles/redundant work
        boolean[][][][] visited = new boolean[n][m][4][MAX_K];

        // Try starting in all 4 directions from 'S'
        for (int dir = 0; dir < 4; dir++) {
            if (dfs(grid, visited, 0, dir, 2, n, m)) {
                return true;
            }
        }
        return false;
    }

    /**
     * Depth-First Search to find a path to 'T'.
     *
     * @param r   Current row
     * @param c   Current column
     * @param dir Current movement direction (0-3)
     * @param k   Remaining moves allowed to change direction
     * @param n   Grid height
     * @param m   Grid width
     * @return true if target 'T' is reachable, false otherwise
     */
    private static boolean dfs(char[][] grid, boolean[][][][] visited, int r, int c, int dir, int k, int n, int m) {
        // Check boundaries and obstacles
        if (r < 0 || c < 0 || r >= n || c >= m || grid[r][c] == '*') {
            return false;
        }

        // Target reached
        if (grid[r][c] == 'T') {
            return true;
        }

        // State already visited: prune this branch
        if (visited[r][c][dir][k]) {
            return false;
        }
        visited[r][c][dir][k] = true;

        // If moves remain to change direction, explore all directions with k-1
        if (k > 0) {
            for (int nextDir = 0; nextDir < 4; nextDir++) {
                if (dfs(grid, visited, r, c, nextDir, k - 1, n, m)) {
                    return true;
                }
            }
        }

        // Continue moving in the current direction
        int nextR = r + DR[dir];
        int nextC = c + DC[dir];
        return dfs(grid, visited, nextR, nextC, dir, k, n, m);
    }

    /**
     * Fast I/O helper class for competitive programming environments.
     */
    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in), 32768);
        }

        public String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input", e);
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            String s = next();
            if (s == null) throw new RuntimeException("Unexpected end of input");
            return Integer.parseInt(s);
        }

        public long nextLong() {
            String s = next();
            if (s == null) throw new RuntimeException("Unexpected end of input");
            return Long.parseLong(s);
        }

        public double nextDouble() {
            String s = next();
            if (s == null) throw new RuntimeException("Unexpected end of input");
            return Double.parseDouble(s);
        }

        public String nextLine() {
            try {
                return br.readLine();
            } catch (IOException e) {
                throw new RuntimeException("Failed to read line", e);
            }
        }

        public int[] intArray(int n) {
            int[] arr = new int[n];
            for (int i = 0; i < n; i++) arr[i] = nextInt();
            return arr;
        }

        public long[] longArray(int n) {
            long[] arr = new long[n];
            for (int i = 0; i < n; i++) arr[i] = nextLong();
            return arr;
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.NoSuchElementException;
import java.util.StringTokenizer;

public class Main {
    public static void main(String[] args) {
        FastScanner in = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out);
        new TaskB().solve(1, in, out);
        out.flush();
    }

    static class TaskB {
        private static final int OBSTACLE = 0;
        private static final int FREE = 99;
        private static final int START = 1;

        public void solve(int testNumber, FastScanner in, PrintWriter out) {
            int rows = in.nextInt();
            int cols = in.nextInt();

            // 1-based indexing with padding to safely handle boundaries
            int[][] grid = new int[rows + 2][cols + 2];
            int startRow = 0, startCol = 0, goalRow = 0, goalCol = 0;

            for (int i = 0; i < rows; i++) {
                String line = in.next();
                for (int j = 0; j < cols; j++) {
                    char c = line.charAt(j);
                    grid[i + 1][j + 1] = (c == 'S') ? START : FREE;
                    if (c == 'S') {
                        startRow = i + 1;
                        startCol = j + 1;
                    } else if (c == 'T') {
                        goalRow = i + 1;
                        goalCol = j + 1;
                    }
                }
            }

            // Check if a vertical path connects the horizontal reachability of S and T
            boolean[] startRowReach = markReachableRow(grid, startRow, startCol, cols);
            boolean[] goalRowReach = markReachableRow(grid, goalRow, goalCol, cols);

            for (int col = 1; col <= cols; col++) {
                if (startRowReach[col] && goalRowReach[col] && isColClear(grid, col, startRow, goalRow)) {
                    out.println("YES");
                    return;
                }
            }

            // Check if a horizontal path connects the vertical reachability of S and T
            boolean[] startColReach = markReachableCol(grid, startCol, startRow, rows);
            boolean[] goalColReach = markReachableCol(grid, goalCol, goalRow, rows);

            for (int row = 1; row <= rows; row++) {
                if (startColReach[row] && goalColReach[row] && isRowClear(grid, row, startCol, goalCol)) {
                    out.println("YES");
                    return;
                }
            }

            out.println("NO");
        }

        private boolean[] markReachableRow(int[][] grid, int row, int startCol, int maxCol) {
            boolean[] reachable = new boolean[maxCol + 2];
            int col = startCol;
            while (col <= maxCol && grid[row][col] > OBSTACLE) {
                reachable[col] = true;
                col++;
            }
            col = startCol;
            while (col >= 1 && grid[row][col] > OBSTACLE) {
                reachable[col] = true;
                col--;
            }
            return reachable;
        }

        private boolean[] markReachableCol(int[][] grid, int col, int startRow, int maxRow) {
            boolean[] reachable = new boolean[maxRow + 2];
            int row = startRow;
            while (row <= maxRow && grid[row][col] > OBSTACLE) {
                reachable[row] = true;
                row++;
            }
            row = startRow;
            while (row >= 1 && grid[row][col] > OBSTACLE) {
                reachable[row] = true;
                row--;
            }
            return reachable;
        }

        private boolean isColClear(int[][] grid, int col, int row1, int row2) {
            if (row1 > row2) {
                int temp = row1;
                row1 = row2;
                row2 = temp;
            }
            for (int r = row1; r <= row2; r++) {
                if (grid[r][col] == OBSTACLE) return false;
            }
            return true;
        }

        private boolean isRowClear(int[][] grid, int row, int col1, int col2) {
            if (col1 > col2) {
                int temp = col1;
                col1 = col2;
                col2 = temp;
            }
            for (int c = col1; c <= col2; c++) {
                if (grid[row][c] == OBSTACLE) return false;
            }
            return true;
        }
    }

    static class FastScanner {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastScanner(InputStream stream) {
            this.reader = new BufferedReader(new InputStreamReader(stream));
            this.tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            String s = next();
            if (s == null) throw new NoSuchElementException();
            return Integer.parseInt(s);
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayDeque;
import java.util.Queue;
import java.util.StringTokenizer;

public class Main {
    // Direction vectors: Up, Left, Right, Down
    private static final int[] DX = {-1, 0, 0, 1};
    private static final int[] DY = {0, -1, 1, 0};

    // Problem constraints
    private static final int MAX_TURNS = 2;
    private static final char OBSTACLE = '*';
    private static final char START = 'S';
    private static final char TARGET = 'T';

    /**
     * Represents a state in the BFS traversal.
     * @param row    Current row coordinate
     * @param col    Current column coordinate
     * @param direction Movement direction index (0-3), -1 for start
     * @param turnsUsed Number of turns taken so far
     */
    private static class State {
        int row, col, direction, turnsUsed;

        State(int row, int col, int direction, int turnsUsed) {
            this.row = row;
            this.col = col;
            this.direction = direction;
            this.turnsUsed = turnsUsed;
        }
    }

    public static void main(String[] args) throws IOException {
        FastScanner scanner = new FastScanner(System.in);

        int n = scanner.nextInt();
        int m = scanner.nextInt();

        char[][] grid = new char[n][m];
        int startRow = 0, startCol = 0;
        int targetRow = 0, targetCol = 0;

        // Parse grid and locate start/target positions
        for (int i = 0; i < n; i++) {
            String line = scanner.next();
            for (int j = 0; j < m; j++) {
                char c = line.charAt(j);
                grid[i][j] = c;
                if (c == START) {
                    startRow = i;
                    startCol = j;
                } else if (c == TARGET) {
                    targetRow = i;
                    targetCol = j;
                }
            }
        }

        boolean pathExists = bfs(n, m, grid, startRow, startCol, targetRow, targetCol);
        System.out.println(pathExists ? "YES" : "NO");
    }

    /**
     * Performs BFS to determine if a valid path exists from start to target
     * respecting the maximum turn constraint.
     */
    private static boolean bfs(int n, int m, char[][] grid, int startRow, int startCol,
                               int targetRow, int targetCol) {
        // visited[row][col][direction][turnsUsed]
        boolean[][][][] visited = new boolean[n][m][4][MAX_TURNS + 1];
        Queue<State> queue = new ArrayDeque<>();

        // Initialize start state
        queue.add(new State(startRow, startCol, -1, 0));

        // Mark start position as visited for all directions and turn counts
        for (int d = 0; d < 4; d++) {
            for (int t = 0; t <= MAX_TURNS; t++) {
                visited[startRow][startCol][d][t] = true;
            }
        }

        while (!queue.isEmpty()) {
            State current = queue.poll();

            // Early exit when target is reached
            if (current.row == targetRow && current.col == targetCol) {
                return true;
            }

            for (int d = 0; d < 4; d++) {
                int nextRow = current.row + DX[d];
                int nextCol = current.col + DY[d];

                // Boundary check
                if (nextRow < 0 || nextRow >= n || nextCol < 0 || nextCol >= m) {
                    continue;
                }
                // Obstacle check
                if (grid[nextRow][nextCol] == OBSTACLE) {
                    continue;
                }

                if (current.direction == -1) {
                    // First move: no turn counted yet
                    if (!visited[nextRow][nextCol][d][0]) {
                        visited[nextRow][nextCol][d][0] = true;
                        queue.add(new State(nextRow, nextCol, d, 0));
                    }
                } else {
                    if (d == current.direction) {
                        // Continuing straight: turn count remains unchanged
                        if (!visited[nextRow][nextCol][d][current.turnsUsed]) {
                            visited[nextRow][nextCol][d][current.turnsUsed] = true;
                            queue.add(new State(nextRow, nextCol, d, current.turnsUsed));
                        }
                    } else {
                        // Changing direction: increment turn count if within limit
                        if (current.turnsUsed + 1 <= MAX_TURNS) {
                            if (!visited[nextRow][nextCol][d][current.turnsUsed + 1]) {
                                visited[nextRow][nextCol][d][current.turnsUsed + 1] = true;
                                queue.add(new State(nextRow, nextCol, d, current.turnsUsed + 1));
                            }
                        }
                    }
                }
            }
        }
        return false;
    }

    /**
     * Fast I/O helper class for competitive programming style input.
     * Unused utility methods from the original were removed to reduce clutter.
     */
    private static class FastScanner {
        private BufferedReader br;
        private StringTokenizer st;

        public FastScanner(java.io.InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        public String next() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) {
                    throw new IOException("Unexpected end of input");
                }
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

public class A {
    // Named constants replace magic numbers
    private static final char OBSTACLE = '*';
    private static final char START = 'S';
    private static final char TARGET = 'T';
    private static final int INITIAL_LEVEL = 1;
    private static final int SECOND_LEVEL = 2;
    private static final int MAX_SUM_THRESHOLD = 3;

    // I/O fields
    private BufferedReader reader;
    private PrintWriter writer;
    private StringTokenizer tokenizer;

    public static void main(String[] args) {
        new A().run();
    }

    public void run() throws IOException {
        reader = new BufferedReader(new InputStreamReader(System.in));
        writer = new PrintWriter(System.out);
        try {
            solve();
        } finally {
            writer.flush();
            writer.close();
        }
    }

    private void solve() throws IOException {
        int n = nextInt();
        int m = nextInt();

        char[][] grid = new char[n][m];
        for (int i = 0; i < n; i++) {
            grid[i] = next().toCharArray();
        }

        boolean hasValidPath = findValidIntersection(grid);
        writer.println(hasValidPath ? "YES" : "NO");
    }

    private boolean findValidIntersection(char[][] grid) {
        // Compute reachability maps for both start points
        int[][] fromStart = computeReachability(grid, START);
        int[][] fromTarget = computeReachability(grid, TARGET);

        // Check the original condition: reachable from both, and sum of levels < 4
        for (int i = 0; i < grid.length; i++) {
            for (int j = 0; j < grid[0].length; j++) {
                int distStart = fromStart[i][j];
                int distTarget = fromTarget[i][j];
                if (distStart > 0 && distTarget > 0 && distStart + distTarget < MAX_SUM_THRESHOLD) {
                    return true;
                }
            }
        }
        return false;
    }

    /**
     * Computes a grid where each cell contains the propagation level from the given start point.
     * Level 1 marks the start points themselves and their immediate ray-cast reach.
     * Level 2 marks cells reachable in the second propagation pass.
     */
    private int[][] computeReachability(char[][] map, char startPoint) {
        int rows = map.length;
        int cols = map[0].length;
        int[][] reachability = new int[rows][cols];

        // Pass 1: Mark start points and propagate INITIAL_LEVEL
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (map[i][j] == startPoint) {
                    propagate(map, reachability, i, j, INITIAL_LEVEL);
                }
            }
        }

        // Pass 2: Propagate SECOND_LEVEL from cells already marked with INITIAL_LEVEL
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (reachability[i][j] == INITIAL_LEVEL) {
                    propagate(map, reachability, i, j, SECOND_LEVEL);
                }
            }
        }

        return reachability;
    }

    /**
     * Propagates a value in all 4 cardinal directions from (startX, startY) until
     * hitting a boundary or an obstacle. Only writes to cells that are currently 0.
     */
    private void propagate(char[][] map, int[][] grid, int startX, int startY, int value) {
        int[] dx = {0, 0, 1, -1};
        int[] dy = {1, -1, 0, 0};

        for (int dir = 0; dir < 4; dir++) {
            for (int step = 0; ; step++) {
                int x = startX + dx[dir] * step;
                int y = startY + dy[dir] * step;

                // Boundary check
                if (x < 0 || x >= map.length || y < 0 || y >= map[0].length) break;
                // Obstacle check
                if (map[x][y] == OBSTACLE) break;
                // Only fill empty cells to preserve existing propagation levels
                if (grid[x][y] == 0) {
                    grid[x][y] = value;
                }
            }
        }
    }

    // --- Fast I/O Utilities ---

    private String next() throws IOException {
        while (tokenizer == null || !tokenizer.hasMoreTokens()) {
            String line = reader.readLine();
            if (line == null) return null;
            tokenizer = new StringTokenizer(line);
        }
        return tokenizer.nextToken();
    }

    private int nextInt() throws IOException {
        String s = next();
        return s == null ? 0 : Integer.parseInt(s);
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.OutputStream;
import java.io.PrintWriter;
import java.util.ArrayDeque;
import java.util.Deque;
import java.util.InputMismatchException;

/**
 * Main entry point for the grid pathfinding solver.
 * Refactored for improved maintainability, readability, and resource management.
 */
public class Main {
    public static void main(String[] args) {
        // Use try-with-resources to ensure output stream is properly closed and flushed
        try (FastPrinter out = new FastPrinter(System.out)) {
            FastScanner in = new FastScanner(System.in);
            GridPathSolver solver = new GridPathSolver();
            solver.solve(in, out);
        }
    }

    /**
     * Encapsulates the BFS algorithm for finding a path with at most 2 turns.
     */
    static class GridPathSolver {
        // Constants extracted for clarity and easy modification
        private static final int MAX_TURNS = 2;
        private static final int NUM_DIRECTIONS = 4;
        private static final int[] DX = {1, 0, -1, 0};
        private static final int[] DY = {0, 1, 0, -1};

        public void solve(FastScanner in, FastPrinter out) {
            int rows = in.nextInt();
            int cols = in.nextInt();
            char[][] grid = in.readGrid(rows, cols);

            int startX = -1, startY = -1;
            int targetX = -1, targetY = -1;

            // Locate start and target positions
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] == 'S') {
                        startX = r;
                        startY = c;
                    } else if (grid[r][c] == 'T') {
                        targetX = r;
                        targetY = c;
                    }
                }
            }

            // BFS initialization
            // visited[turns][direction][x][y] tracks explored states to prevent cycles
            boolean[][][][] visited = new boolean[MAX_TURNS + 1][NUM_DIRECTIONS][rows][cols];
            Deque<State> queue = new ArrayDeque<>();

            // Initialize queue with all possible starting directions at the start position
            for (int dir = 0; dir < NUM_DIRECTIONS; dir++) {
                queue.add(new State(startX, startY, dir, 0));
                visited[0][dir][startX][startY] = true;
            }

            // BFS loop
            while (!queue.isEmpty()) {
                State current = queue.poll();

                // Check if target is reached
                if (grid[current.x][current.y] == 'T') {
                    out.println("YES");
                    return;
                }

                // Explore all 4 possible directions
                for (int nextDir = 0; nextDir < NUM_DIRECTIONS; nextDir++) {
                    int nextTurns = current.turns + (nextDir == current.dir ? 0 : 1);
                    if (nextTurns > MAX_TURNS) continue;

                    int nx = current.x + DX[nextDir];
                    int ny = current.y + DY[nextDir];

                    if (isValidMove(nx, ny, rows, cols, grid) && !visited[nextTurns][nextDir][nx][ny]) {
                        visited[nextTurns][nextDir][nx][ny] = true;
                        queue.add(new State(nx, ny, nextDir, nextTurns));
                    }
                }
            }

            out.println("NO");
        }

        /**
         * Validates whether a coordinate is within bounds and not a wall.
         */
        private boolean isValidMove(int x, int y, int rows, int cols, char[][] grid) {
            return x >= 0 && y >= 0 && x < rows && y < cols && grid[x][y] != '*';
        }

        /**
         * Represents a state in the BFS: position, facing direction, and turns taken.
         * Replaces the original integer-encoding scheme for better readability and type safety.
         */
        private static class State {
            final int x, y, dir, turns;

            State(int x, int y, int dir, int turns) {
                this.x = x;
                this.y = y;
                this.dir = dir;
                this.turns = turns;
            }
        }
    }

    /**
     * High-performance output printer wrapping PrintWriter.
     */
    static class FastPrinter extends PrintWriter {
        public FastPrinter(OutputStream outputStream) {
            super(outputStream);
        }

        public FastPrinter(java.io.Writer outputStream) {
            super(outputStream);
        }
    }

    /**
     * High-performance input scanner wrapping BufferedReader.
     * Handles tokenized reading and grid parsing efficiently.
     */
    static class FastScanner {
        private final BufferedReader reader;

        public FastScanner(InputStream inputStream) {
            this.reader = new BufferedReader(new InputStreamReader(inputStream));
        }

        public int nextInt() {
            int c = read();
            while (isWhitespace(c)) {
                c = read();
            }
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int result = 0;
            while (c >= 0 && !isWhitespace(c)) {
                if (c < '0' || c > '9') {
                    throw new InputMismatchException("Expected digit, found: " + (char) c);
                }
                result = result * 10 + (c - '0');
                c = read();
            }
            return result * sign;
        }

        public char[][] readGrid(int rows, int cols) {
            char[][] grid = new char[rows][];
            for (int i = 0; i < rows; i++) {
                String line = next();
                if (line == null || line.length() != cols) {
                    throw new AssertionError("Grid row length mismatch: expected " + cols + ", got " + (line != null ? line.length() : "null"));
                }
                grid[i] = line.toCharArray();
            }
            return grid;
        }

        private String next() {
            StringBuilder sb = new StringBuilder();
            int c = read();
            while (isWhitespace(c)) {
                c = read();
            }
            if (c < 0) return null;
            while (c >= 0 && !isWhitespace(c)) {
                sb.appendCodePoint(c);
                c = read();
            }
            return sb.toString();
        }

        private int read() {
            try {
                return reader.read();
            } catch (IOException e) {
                throw new InputMismatchException("IO Error during read", e);
            }
        }

        private static boolean isWhitespace(int c) {
            return c >= 0 && c <= 32;
        }
    }
}

import java.io.*;
import java.util.*;

public class IgorWayToWork {
    // Constants for direction and turn tracking
    private static final int MAX_TURNS = 2;
    private static final int DIR_NONE = 0;
    private static final int DIR_HORIZONTAL = 1;
    private static final int DIR_VERTICAL = 2;

    /**
     * Encapsulates all problem-specific state to prevent instance variable pollution.
     * This makes the class stateless, thread-safe, and easier to test.
     */
    private static class SolverContext {
        final int n, m;
        int startRow, startCol, endRow, endCol;
        final boolean[][][] visited;
        boolean canReach;

        SolverContext(int n, int m) {
            this.n = n;
            this.m = m;
            this.visited = new boolean[n][m][MAX_TURNS + 1];
            this.canReach = false;
        }
    }

    public static void main(String[] args) throws IOException {
        new IgorWayToWork().runStdIO();
    }

    public void runStdIO() throws IOException {
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
             PrintWriter pw = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)))) {
            solve(br, pw);
        }
    }

    public void runFileIO(String filename) throws IOException {
        try (BufferedReader br = new BufferedReader(new FileReader(filename + ".in"));
             PrintWriter pw = new PrintWriter(new BufferedWriter(new FileWriter(filename + ".out")))) {
            solve(br, pw);
        }
    }

    private void solve(BufferedReader br, PrintWriter pw) throws IOException {
        String line = br.readLine();
        if (line == null || line.trim().isEmpty()) return;

        StringTokenizer st = new StringTokenizer(line);
        int n = Integer.parseInt(st.nextToken());
        int m = Integer.parseInt(st.nextToken());

        int[][] board = new int[n][m];
        SolverContext ctx = new SolverContext(n, m);

        for (int i = 0; i < n; i++) {
            String row = br.readLine();
            if (row == null) break;
            for (int j = 0; j < m; j++) {
                if (j < row.length()) {
                    char c = row.charAt(j);
                    if (c != '*') {
                        board[i][j] = 1;
                        if (c == 'S') {
                            ctx.startRow = i;
                            ctx.startCol = j;
                        } else if (c == 'T') {
                            ctx.endRow = i;
                            ctx.endCol = j;
                        }
                    }
                }
            }
        }

        dfs(ctx, board, ctx.startRow, ctx.startCol, DIR_NONE, 0);
        pw.println(ctx.canReach ? "YES" : "NO");
    }

    private boolean dfs(SolverContext ctx, int[][] board, int r, int c, int dir, int turns) {
        // Base case: target reached
        if (r == ctx.endRow && c == ctx.endCol) {
            ctx.canReach = true;
            return true;
        }

        // State pruning: avoid revisiting the same grid position with the same turn count
        if (ctx.visited[r][c][turns]) {
            return false;
        }
        ctx.visited[r][c][turns] = true;

        // Direction vectors: Up, Left, Down, Right
        int[] dr = {-1, 0, 1, 0};
        int[] dc = {0, -1, 0, 1};

        for (int i = 0; i < 4; i++) {
            if (ctx.canReach) return true; // Early exit propagation

            int nr = r + dr[i];
            int nc = c + dc[i];

            // Boundary and obstacle checks
            if (nr < 0 || nr >= ctx.n || nc < 0 || nc >= ctx.m || board[nr][nc] == 0) {
                continue;
            }

            // Determine movement direction
            int newDir;
            if (nr != r) newDir = DIR_VERTICAL;
            else if (nc != c) newDir = DIR_HORIZONTAL;
            else continue; // Should not occur given grid movement

            // Calculate new turn count
            int newTurns = turns;
            if (dir != DIR_NONE && dir != newDir) {
                newTurns++;
            }

            // Only proceed if within the allowed turn limit
            if (newTurns <= MAX_TURNS) {
                if (dfs(ctx, board, nr, nc, newDir, newTurns)) {
                    return true;
                }
            }
        }
        return false;
    }
}

import java.util.Scanner;

/**
 * Refactored solution for finding a path from 'S' to 'T' with at most 2 turns.
 * 
 * Improvements made:
 * 1. Encapsulation: Removed static global variables; state is managed within the instance.
 * 2. Control Flow: Replaced System.exit(0) with a boolean return value for cleaner logic.
 * 3. Readability: Used integer deltas (dr, dc) instead of character directions to simplify logic.
 * 4. Optimization: Preserved the alignment check for turn limit 2.
 * 5. Structure: Separated input parsing and logic into distinct methods.
 */
public class IgorToWork {
    private char[][] grid;
    private int n, m;
    private int endRow, endCol;

    public static void main(String[] args) {
        IgorToWork solver = new IgorToWork();
        solver.solve();
    }

    public void solve() {
        Scanner scanner = new Scanner(System.in);

        // Input validation
        if (!scanner.hasNextInt()) {
            return;
        }

        n = scanner.nextInt();
        m = scanner.nextInt();

        grid = new char[n][m];
        int startRow = -1;
        int startCol = -1;

        // Read the grid
        for (int i = 0; i < n; i++) {
            if (scanner.hasNext()) {
                String line = scanner.next();
                for (int j = 0; j < m; j++) {
                    char cell = line.charAt(j);
                    grid[i][j] = cell;
                    if (cell == 'S') {
                        startRow = i;
                        startCol = j;
                    } else if (cell == 'T') {
                        endRow = i;
                        endCol = j;
                    }
                }
            }
        }

        scanner.close();

        // Basic validation
        if (startRow == -1 || endRow == -1) {
            System.out.println("NO");
            return;
        }

        boolean found = false;

        // Attempt to move in all 4 directions from the Start position.
        // The initial move does not count as a turn.

        // Try moving Up (dr = -1, dc = 0)
        if (dfs(startRow - 1, startCol, 0, -1, 0)) {
            found = true;
        }
        // Try moving Down (dr = 1, dc = 0)
        else if (dfs(startRow + 1, startCol, 0, 1, 0)) {
            found = true;
        }
        // Try moving Left (dr = 0, dc = -1)
        else if (dfs(startRow, startCol - 1, 0, 0, -1)) {
            found = true;
        }
        // Try moving Right (dr = 0, dc = 1)
        else if (dfs(startRow, startCol + 1, 0, 0, 1)) {
            found = true;
        }

        System.out.println(found ? "YES" : "NO");
    }

    /**
     * Performs Depth First Search to find a path to 'T'.
     * 
     * @param r     Current row index
     * @param c     Current column index
     * @param turns Number of turns made so far
     * @param dr    Direction row delta (-1 for Up, 1 for Down, 0 for Horizontal)
     * @param dc    Direction column delta (-1 for Left, 1 for Right, 0 for Vertical)
     * @return true if 'T' is reachable, false otherwise
     */
    private boolean dfs(int r, int c, int turns, int dr, int dc) {
        // 1. Boundary Check
        if (r < 0 || r >= n || c < 0 || c >= m) {
            return false;
        }

        // 2. Turn Limit Check (Max 2 turns allowed)
        if (turns > 2) {
            return false;
        }

        // 3. Optimization: Alignment Check
        // If we have used 2 turns, we cannot turn anymore.
        // We must be moving directly towards the target's row/col.
        if (turns == 2) {
            // If moving horizontally (dc != 0), we must be on the target's row
            if (dc != 0 && r != endRow) {
                return false;
            }
            // If moving vertically (dr != 0), we must be on the target's column
            if (dr != 0 && c != endCol) {
                return false;
            }
        }

        // 4. Obstacle Check
        if (grid[r][c] == '*') {
            return false;
        }

        // 5. Target Check
        if (grid[r][c] == 'T') {
            return true;
        }

        // 6. Recursive Steps

        // Option A: Continue in the current direction (dr, dc)
        // This does not increase the turn count.
        if (dfs(r + dr, c + dc, turns, dr, dc)) {
            return true;
        }

        // Option B: Turn 90 degrees
        // Perpendicular directions to (dr, dc) are (-dc, dr) and (dc, -dr).
        // Turning increases the turn count by 1.

        // Perpendicular 1
        int nextDr1 = -dc;
        int nextDc1 = dr;
        if (dfs(r + nextDr1, c + nextDc1, turns + 1, nextDr1, nextDc1)) {
            return true;
        }

        // Perpendicular 2
        int nextDr2 = dc;
        int nextDc2 = -dr;
        if (dfs(r + nextDr2, c + nextDc2, turns + 1, nextDr2, nextDc2)) {
            return true;
        }

        return false;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayDeque;
import java.util.Arrays;
import java.util.Queue;
import java.util.StringTokenizer;

public class GridPathFinder {

    // Directions: 0=Down, 1=Up, 2=Right, 3=Left
    private static final int[][] DIRECTIONS = {
        {1, 0},  // Down
        {-1, 0}, // Up
        {0, 1},  // Right
        {0, -1}  // Left
    };

    public static void main(String[] args) throws IOException {
        FastScanner scanner = new FastScanner(System.in);
        int n = scanner.nextInt();
        int m = scanner.nextInt();

        char[][] grid = new char[n][m];
        int startX = -1, startY = -1, endX = -1, endY = -1;

        for (int i = 0; i < n; i++) {
            String line = scanner.next();
            grid[i] = line.toCharArray();
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == 'S') {
                    startX = i;
                    startY = j;
                } else if (grid[i][j] == 'T') {
                    endX = i;
                    endY = j;
                }
            }
        }

        boolean found = solve(grid, n, m, startX, startY, endX, endY);
        System.out.println(found ? "YES" : "NO");
    }

    private static boolean solve(char[][] grid, int n, int m, int startX, int startY, int endX, int endY) {
        // vis[x][y][dir] stores the minimum turns to reach (x, y) arriving from direction 'dir'
        int[][][] vis = new int[n][m][4];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                Arrays.fill(vis[i][j], Integer.MAX_VALUE);
            }
        }

        Queue<State> queue = new ArrayDeque<>();
        // Start state: position, turns, direction (-1 indicates no previous direction)
        queue.add(new State(startX, startY, 0, -1));
        vis[startX][startY][0] = 0; // Mark start as visited with 0 turns

        while (!queue.isEmpty()) {
            State current = queue.poll();

            if (current.x == endX && current.y == endY) {
                return true;
            }

            for (int d = 0; d < 4; d++) {
                int nx = current.x + DIRECTIONS[d][0];
                int ny = current.y + DIRECTIONS[d][1];

                // Check bounds
                if (nx < 0 || nx >= n || ny < 0 || ny >= m) continue;
                // Check obstacle
                if (grid[nx][ny] == '*') continue;

                // Calculate turns: first move doesn't count as a turn
                int newTurns = current.turns;
                if (current.dir != -1 && current.dir != d) {
                    newTurns++;
                }

                // Prune if turns exceed limit
                if (newTurns > 2) continue;
                // Prune if we've already reached this cell with fewer or equal turns in this direction
                if (newTurns >= vis[nx][ny][d]) continue;

                vis[nx][ny][d] = newTurns;
                queue.add(new State(nx, ny, newTurns, d));
            }
        }
        return false;
    }

    private static final class State {
        final int x, y, turns, dir;

        State(int x, int y, int turns, int dir) {
            this.x = x;
            this.y = y;
            this.turns = turns;
            this.dir = dir;
        }
    }

    private static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner(java.io.InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        String next() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) throw new IOException("Unexpected end of input");
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

public class Abood2D {

    public static void main(String[] args) throws IOException {
        FastScanner sc = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out);

        int n = sc.nextInt();
        int m = sc.nextInt();

        char[][] grid = new char[n][m];
        int startRow = 0, startCol = 0;
        int targetRow = 0, targetCol = 0;

        // Parse grid and locate start ('S') and target ('T')
        for (int i = 0; i < n; i++) {
            String line = sc.next();
            for (int j = 0; j < m; j++) {
                grid[i][j] = line.charAt(j);
                if (grid[i][j] == 'S') {
                    startRow = i;
                    startCol = j;
                } else if (grid[i][j] == 'T') {
                    targetRow = i;
                    targetCol = j;
                }
            }
        }

        // Check both alignment possibilities
        boolean canConnect = checkHorizontalAlignment(grid, startRow, startCol, targetRow, targetCol) ||
                             checkVerticalAlignment(grid, startRow, startCol, targetRow, targetCol);

        out.println(canConnect ? "YES" : "NO");
        out.flush();
    }

    /**
     * Checks if a valid vertical corridor exists within the overlapping horizontal reach
     * of the start and target positions.
     */
    private static boolean checkHorizontalAlignment(char[][] grid, int sRow, int sCol, int eRow, int eCol) {
        int[] sBounds = getHorizontalBounds(grid, sRow, sCol);
        int[] eBounds = getHorizontalBounds(grid, eRow, eCol);

        int overlapStart = Math.max(sBounds[0], eBounds[0]);
        int overlapEnd = Math.min(sBounds[1], eBounds[1]);

        int minRow = Math.min(sRow, eRow);
        int maxRow = Math.max(sRow, eRow);

        for (int col = overlapStart; col <= overlapEnd; col++) {
            if (isColumnClear(grid, col, minRow, maxRow)) {
                return true;
            }
        }
        return false;
    }

    /**
     * Checks if a valid horizontal corridor exists within the overlapping vertical reach
     * of the start and target positions.
     */
    private static boolean checkVerticalAlignment(char[][] grid, int sRow, int sCol, int eRow, int eCol) {
        int[] sBounds = getVerticalBounds(grid, sCol, sRow);
        int[] eBounds = getVerticalBounds(grid, eCol, eRow);

        int overlapStart = Math.max(sBounds[0], eBounds[0]);
        int overlapEnd = Math.min(sBounds[1], eBounds[1]);

        int minCol = Math.min(sCol, eCol);
        int maxCol = Math.max(sCol, eCol);

        for (int row = overlapStart; row <= overlapEnd; row++) {
            if (isRowClear(grid, row, minCol, maxCol)) {
                return true;
            }
        }
        return false;
    }

    /**
     * Finds the leftmost and rightmost traversable columns in a given row.
     */
    private static int[] getHorizontalBounds(char[][] grid, int row, int col) {
        int left = col;
        while (left > 0 && grid[row][left - 1] == '.') {
            left--;
        }
        int right = col;
        while (right < grid[row].length - 1 && grid[row][right + 1] == '.') {
            right++;
        }
        return new int[]{left, right};
    }

    /**
     * Finds the topmost and bottommost traversable rows in a given column.
     */
    private static int[] getVerticalBounds(char[][] grid, int col, int row) {
        int top = row;
        while (top > 0 && grid[top - 1][col] == '.') {
            top--;
        }
        int bottom = row;
        while (bottom < grid.length - 1 && grid[bottom + 1][col] == '.') {
            bottom++;
        }
        return new int[]{top, bottom};
    }

    /**
     * Checks if all cells in a vertical segment are traversable.
     */
    private static boolean isColumnClear(char[][] grid, int col, int minRow, int maxRow) {
        for (int row = minRow; row <= maxRow; row++) {
            char cell = grid[row][col];
            if (cell != '.' && cell != 'S' && cell != 'T') {
                return false;
            }
        }
        return true;
    }

    /**
     * Checks if all cells in a horizontal segment are traversable.
     */
    private static boolean isRowClear(char[][] grid, int row, int minCol, int maxCol) {
        for (int col = minCol; col <= maxCol; col++) {
            char cell = grid[row][col];
            if (cell != '.' && cell != 'S' && cell != 'T') {
                return false;
            }
        }
        return true;
    }

    /**
     * Fast I/O helper class optimized for competitive programming.
     */
    static class FastScanner {
        private BufferedReader br;
        private StringTokenizer st;

        public FastScanner(InputStream input) {
            br = new BufferedReader(new InputStreamReader(input));
        }

        public String next() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) {
                    return null;
                }
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

        public int nextInt() throws IOException {
            String token = next();
            return token == null ? 0 : Integer.parseInt(token);
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayDeque;
import java.util.Arrays;
import java.util.Deque;
import java.util.StringTokenizer;

public class Main {

    // Direction constants for consistent state tracking
    private static final int DIR_UP = 0;
    private static final int DIR_DOWN = 1;
    private static final int DIR_LEFT = 2;
    private static final int DIR_RIGHT = 3;

    // Movement deltas: UP, LEFT, RIGHT, DOWN
    private static final int[][] MOVES = {
        {-1, 0}, {0, -1}, {0, 1}, {1, 0}
    };

    // Maximum allowed turns as per problem constraints
    private static final int MAX_TURNS = 2;

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());

        int n = Integer.parseInt(st.nextToken());
        int m = Integer.parseInt(st.nextToken());

        char[][] grid = new char[n][m];
        int[] startPos = new int[2];

        // Read grid and locate start position
        for (int i = 0; i < n; i++) {
            String line = br.readLine();
            for (int j = 0; j < m; j++) {
                grid[i][j] = line.charAt(j);
                if (grid[i][j] == 'S') {
                    startPos[0] = i;
                    startPos[1] = j;
                }
            }
        }

        // visited[r][c][dir] stores the minimum turns to reach cell (r,c) facing direction 'dir'
        // Initialized to MAX_VALUE to represent unvisited states
        int[][][] visited = new int[n][m][4];
        for (int[][] row : visited) {
            for (int[] col : row) {
                Arrays.fill(col, Integer.MAX_VALUE);
            }
        }

        // Use ArrayDeque as a stack for DFS traversal
        Deque<State> stack = new ArrayDeque<>();
        stack.push(new State(startPos[0], startPos[1], 0, -1)); // -1 indicates no initial direction

        boolean found = false;

        while (!stack.isEmpty()) {
            State current = stack.pop();

            for (int[] move : MOVES) {
                int nr = current.r + move[0];
                int nc = current.c + move[1];

                // Boundary check
                if (nr < 0 || nr >= n || nc < 0 || nc >= m) {
                    continue;
                }

                int newDir = getDirectionCode(move[0], move[1]);
                // First move or moving in the same direction doesn't increment turn count
                int newTurns = (current.dir == -1 || current.dir == newDir) ? current.turns : current.turns + 1;

                // Pruning: stop if max turns exceeded or if we've already reached this state with fewer/equal turns
                if (newTurns > MAX_TURNS) {
                    continue;
                }
                if (visited[nr][nc][newDir] <= newTurns) {
                    continue;
                }

                // Record the optimal turn count for this state
                visited[nr][nc][newDir] = newTurns;

                if (grid[nr][nc] == 'T') {
                    found = true;
                    break;
                } else if (grid[nr][nc] == '.') {
                    stack.push(new State(nr, nc, newTurns, newDir));
                }
            }
            if (found) {
                break;
            }
        }

        System.out.println(found ? "YES" : "NO");
    }

    /**
     * Maps movement deltas to direction constants.
     */
    private static int getDirectionCode(int dRow, int dCol) {
        if (dRow == -1 && dCol == 0) return DIR_UP;
        if (dRow == 1 && dCol == 0) return DIR_DOWN;
        if (dRow == 0 && dCol == -1) return DIR_LEFT;
        if (dRow == 0 && dCol == 1) return DIR_RIGHT;
        return -1; // Should not occur given the MOVES array
    }

    /**
     * Immutable state class representing a position, turn count, and facing direction in the search space.
     */
    private static class State {
        final int r;
        final int c;
        final int turns;
        final int dir;

        State(int r, int c, int turns, int dir) {
            this.r = r;
            this.c = c;
            this.turns = turns;
            this.dir = dir;
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.Arrays;
import java.util.StringTokenizer;

/**
 * Refactored solver for the grid pathfinding problem.
 * Improvements:
 * - Removed static mutable state to prevent side effects and improve testability.
 * - Encapsulated grid logic in an instance-based {@link PathSolver} class.
 * - Used try-with-resources for proper resource management.
 * - Renamed variables/methods for clarity and followed Java naming conventions.
 * - Converted recursive mathematical utilities to iterative versions for robustness.
 * - Cleaned up unused imports and fixed misleading exception declarations.
 */
public class TinkOffEliSolver {

    // Grid movement directions: Right, Down, Left, Up
    private static final int[] DX = {0, 1, 0, -1};
    private static final int[] DY = {1, 0, -1, 0};
    private static final int MAX_TURNS = 2;

    public static void main(String[] args) {
        // Try-with-resources ensures PrintWriter and FastScanner are closed automatically
        try (FastScanner in = new FastScanner();
             PrintWriter out = new PrintWriter(System.out)) {

            int n = in.nextInt();
            int m = in.nextInt();
            String[] grid = new String[n];
            int startRow = -1;
            int startCol = -1;

            for (int i = 0; i < n; i++) {
                grid[i] = in.next();
                for (int j = 0; j < m; j++) {
                    if (grid[i].charAt(j) == 'S') {
                        startRow = i;
                        startCol = j;
                    }
                }
            }

            PathSolver solver = new PathSolver(grid);
            boolean canReachTarget = solver.canReach(startRow, startCol);

            out.println(canReachTarget ? "YES" : "NO");
        } catch (IOException e) {
            System.err.println("Input/Output error: " + e.getMessage());
        }
    }

    /**
     * Encapsulates the grid traversal logic to avoid static state leakage.
     * Uses DFS with memoization to determine if 'T' is reachable from 'S'
     * with at most {@link #MAX_TURNS} direction changes.
     */
    static class PathSolver {
        private final String[] grid;
        private final int rows;
        private final int cols;
        // visited[row][col][direction][turnsRemaining]
        private final boolean[][][][] visited;

        PathSolver(String[] grid) {
            this.grid = grid;
            this.rows = grid.length;
            this.cols = grid[0].length();
            this.visited = new boolean[rows][cols][4][MAX_TURNS + 1];
        }

        boolean canReach(int startRow, int startCol) {
            // Try starting in each of the 4 directions with full turns allowed
            for (int dir = 0; dir < 4; dir++) {
                if (dfs(startRow, startCol, dir, MAX_TURNS)) {
                    return true;
                }
            }
            return false;
        }

        private boolean dfs(int x, int y, int dir, int turnsLeft) {
            if (turnsLeft < 0) {
                return false;
            }
            if (grid[x].charAt(y) == 'T') {
                return true;
            }
            if (visited[x][y][dir][turnsLeft]) {
                return false;
            }
            visited[x][y][dir][turnsLeft] = true;

            for (int nextDir = 0; nextDir < 4; nextDir++) {
                int nx = x + DX[nextDir];
                int ny = y + DY[nextDir];

                if (isValid(nx, ny) && grid[nx].charAt(ny) != '*') {
                    int newTurns = (dir == nextDir) ? turnsLeft : turnsLeft - 1;
                    if (dfs(nx, ny, nextDir, newTurns)) {
                        return true;
                    }
                }
            }
            return false;
        }

        private boolean isValid(int x, int y) {
            return x >= 0 && x < rows && y >= 0 && y < cols;
        }
    }

    // ========================================================================
    // Utility Methods (Typical Competitive Programming Template)
    // ========================================================================

    public static int[] kmp(String val) {
        int i = 0;
        int j = -1;
        int[] result = new int[val.length() + 1];
        result[0] = -1;
        while (i < val.length()) {
            while (j >= 0 && val.charAt(j) != val.charAt(i)) {
                j = result[j];
            }
            j++;
            i++;
            result[i] = j;
        }
        return result;
    }

    public static boolean nextPermutation(int[] data) {
        int i = data.length - 1;
        while (i > 0 && data[i] < data[i - 1]) {
            i--;
        }
        if (i == 0) {
            return false;
        }
        int j = data.length - 1;
        while (data[j] < data[i - 1]) {
            j--;
        }
        int temp = data[i - 1];
        data[i - 1] = data[j];
        data[j] = temp;
        Arrays.sort(data, i, data.length);
        return true;
    }

    public static int countDigits(long n) {
        if (n == 0) return 1;
        int result = 0;
        while (n > 0) {
            n /= 10;
            result++;
        }
        return result;
    }

    public static double calculateDistance(long a, long b, long x, long y) {
        double distBetween = Math.hypot(b - a, x - y);
        double distFromOrigin = Math.hypot(a, x);
        return distBetween + distFromOrigin;
    }

    public static class Point implements Comparable<Point> {
        public final int x;
        public final int y;

        public Point(int x, int y) {
            this.x = x;
            this.y = y;
        }

        @Override
        public int hashCode() {
            return 47 * (47 + x) + y;
        }

        @Override
        public boolean equals(Object obj) {
            if (this == obj) return true;
            if (obj == null || getClass() != obj.getClass()) return false;
            Point other = (Point) obj;
            return x == other.x && y == other.y;
        }

        @Override
        public int compareTo(Point o) {
            return Integer.compare(this.x, o.x);
        }
    }

    public static class FenwickTree {
        private final long[] tree;

        public FenwickTree(int size) {
            this.tree = new long[size];
        }

        public void update(int index, long value) {
            while (index < tree.length) {
                tree[index] += value;
                index += index & (-index);
            }
        }

        public long query(int index) {
            long sum = 0;
            while (index > 0) {
                sum += tree[index];
                index -= index & (-index);
            }
            return sum;
        }
    }

    public static long gcd(long a, long b) {
        while (b != 0) {
            long temp = b;
            b = a % b;
            a = temp;
        }
        return a;
    }

    public static long modPow(long base, long exp, long mod) {
        long result = 1;
        base %= mod;
        while (exp > 0) {
            if ((exp & 1) == 1) result = (result * base) % mod;
            base = (base * base) % mod;
            exp >>= 1;
        }
        return result;
    }

    // ========================================================================
    // Fast I/O Helper
    // ========================================================================

    /**
     * FastScanner provides efficient token-based input reading.
     */
    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        public String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return st.nextToken();
        }

        public long nextLong() {
            String s = next();
            if (s == null) throw new RuntimeException("Unexpected end of input");
            return Long.parseLong(s);
        }

        public int nextInt() {
            String s = next();
            if (s == null) throw new RuntimeException("Unexpected end of input");
            return Integer.parseInt(s);
        }

        public double nextDouble() {
            String s = next();
            if (s == null) throw new RuntimeException("Unexpected end of input");
            return Double.parseDouble(s);
        }

        public String nextLine() {
            st = null;
            try {
                return br.readLine();
            } catch (IOException e) {
                throw new RuntimeException("Error reading line", e);
            }
        }

        public boolean hasNextLine() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return false;
                    if (line.trim().isEmpty()) continue;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return true;
        }
    }
}

import java.io.PrintWriter;
import java.util.ArrayDeque;
import java.util.Deque;
import java.util.Scanner;

/**
 * Solves the grid path problem (similar to Codeforces 793B).
 * Determines if it is possible to reach the target 'T' from the start 'S' 
 * with at most 2 turns.
 * 
 * This implementation uses a 0-1 BFS (Breadth-First Search) algorithm to 
 * find the shortest path in terms of turns. Moving in the same direction 
 * costs 0 turns, while changing direction costs 1 turn.
 */
public class GridPathSolver {

    // Constants for directions
    private static final int HORIZONTAL = 0;
    private static final int VERTICAL = 1;

    // Constant for infinity (larger than any possible path cost)
    private static final int INFINITY = 1_000_000_000;

    // Maximum allowed turns
    private static final int MAX_TURNS = 2;

    /**
     * Represents a state in the BFS traversal.
     * Stores the current position and the direction from which we arrived 
     * (or the direction we are currently moving).
     */
    private static class State {
        int row;
        int col;
        int direction; // 0 for Horizontal, 1 for Vertical

        State(int row, int col, int direction) {
            this.row = row;
            this.col = col;
            this.direction = direction;
        }
    }

    /**
     * Solves the problem using input and output streams.
     *
     * @param in  Scanner for input
     * @param out PrintWriter for output
     */
    public void solve(Scanner in, PrintWriter out) {
        if (!in.hasNextInt()) {
            return;
        }

        int n = in.nextInt();
        int m = in.nextInt();

        boolean[][] grid = new boolean[n][m];
        int startRow = -1, startCol = -1;
        int endRow = -1, endCol = -1;

        // Read the grid and identify start/end points
        for (int r = 0; r < n; r++) {
            String rowStr = in.next();
            for (int c = 0; c < m; c++) {
                char ch = rowStr.charAt(c);
                if (ch != '*') {
                    grid[r][c] = true;
                }
                if (ch == 'S') {
                    startRow = r;
                    startCol = c;
                } else if (ch == 'T') {
                    endRow = r;
                    endCol = c;
                }
            }
        }

        // DP array to store minimum turns to reach cell (r, c) with a specific incoming direction.
        // Dimensions: [row][col][direction]
        // direction: 0 = Horizontal (came from left/right), 1 = Vertical (came from up/down)
        int[][][] dp = new int[n][m][2];

        // Initialize DP table with infinity
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < m; c++) {
                dp[r][c][HORIZONTAL] = INFINITY;
                dp[r][c][VERTICAL] = INFINITY;
            }
        }

        Deque<State> queue = new ArrayDeque<>();

        // Initialize start state
        // At the start position, we can conceptually arrive with either direction with 0 cost
        // because the first move doesn't count as a turn.
        dp[startRow][startCol][HORIZONTAL] = 0;
        dp[startRow][startCol][VERTICAL] = 0;

        queue.add(new State(startRow, startCol, HORIZONTAL));
        queue.add(new State(startRow, startCol, VERTICAL));

        // Direction vectors: Up, Down, Left, Right
        // Corresponding target directions for the state: Vertical, Vertical, Horizontal, Horizontal
        int[] dr = {-1, 1, 0, 0};
        int[] dc = {0, 0, -1, 1};
        int[] targetDir = {VERTICAL, VERTICAL, HORIZONTAL, HORIZONTAL};

        // 0-1 BFS
        while (!queue.isEmpty()) {
            State current = queue.pollFirst();
            int r = current.row;
            int c = current.col;
            int dir = current.direction;

            int currentDist = dp[r][c][dir];

            // If we found a shorter path to this state already, skip processing.
            // This handles cases where a node is added to the queue multiple times.
            if (currentDist > dp[r][c][dir]) {
                continue;
            }

            // Explore neighbors
            for (int i = 0; i < 4; i++) {
                int nr = r + dr[i];
                int nc = c + dc[i];
                int ndir = targetDir[i];

                // Check boundaries and obstacles
                if (nr >= 0 && nr < n && nc >= 0 && nc < m && grid[nr][nc]) {
                    // Calculate cost: 0 if continuing in same direction, 1 if turning
                    int cost = (dir == ndir) ? 0 : 1;
                    int newDist = currentDist + cost;

                    // Relaxation step: found a path with fewer turns
                    if (newDist < dp[nr][nc][ndir]) {
                        dp[nr][nc][ndir] = newDist;

                        // 0-1 BFS Optimization:
                        // If edge weight is 0, add to front of deque to process immediately.
                        // If edge weight is 1, add to back of deque.
                        if (cost == 0) {
                            queue.addFirst(new State(nr, nc, ndir));
                        } else {
                            queue.addLast(new State(nr, nc, ndir));
                        }
                    }
                }
            }
        }

        // The answer is the minimum turns to reach the target in either direction
        int ans = Math.min(dp[endRow][endCol][HORIZONTAL], dp[endRow][endCol][VERTICAL]);

        if (ans > MAX_TURNS) {
            out.println("NO");
        } else {
            out.println("YES");
        }
    }

    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        PrintWriter out = new PrintWriter(System.out);

        new GridPathSolver().solve(in, out);

        out.flush();
        out.close();
        in.close();
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

/**
 * A solver for finding a path in a grid with a limited number of turns.
 * 
 * This refactored version improves maintainability by:
 * 1. Encapsulating state within an instance rather than using static fields.
 * 2. Using an Enum for directions to eliminate magic characters ('u', 'd', etc.).
 * 3. Replacing System.exit with a boolean return value for cleaner control flow.
 * 4. Improving variable naming for clarity (rows, cols, startRow, etc.).
 * 5. Adding comments and logical structure to the recursive search.
 */
public class GridPathSolver {

    // Configuration
    private static final int MAX_TURNS = 3;

    // Grid State
    private char[][] grid;
    private int rows, cols;
    private int startRow, startCol;
    private int targetRow, targetCol;

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));

        // Read dimensions
        String line = br.readLine();
        if (line == null) return;

        StringTokenizer st = new StringTokenizer(line);
        int n = Integer.parseInt(st.nextToken());
        int m = Integer.parseInt(st.nextToken());

        GridPathSolver solver = new GridPathSolver();
        solver.rows = n;
        solver.cols = m;
        solver.grid = new char[n][];

        // Read Grid
        for (int i = 0; i < n; i++) {
            String rowLine = br.readLine();
            if (rowLine != null) {
                solver.grid[i] = rowLine.toCharArray();
            }
        }

        // Locate Start ('S') and Target ('T')
        for (int i = 0; i < n; i++) {
            // Ensure we don't go out of bounds if row is shorter than m
            int currentRowLength = (solver.grid[i] != null) ? solver.grid[i].length : 0;
            for (int j = 0; j < currentRowLength; j++) {
                if (solver.grid[i][j] == 'S') {
                    solver.startRow = i;
                    solver.startCol = j;
                } else if (solver.grid[i][j] == 'T') {
                    solver.targetRow = i;
                    solver.targetCol = j;
                }
            }
        }

        // Solve and Output
        if (solver.canReachTarget()) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }
    }

    /**
     * Attempts to find a path from Target to Start.
     * The original logic explores all 4 initial directions from the Target.
     */
    private boolean canReachTarget() {
        for (Direction dir : Direction.values()) {
            if (dfs(targetRow, targetCol, 0, dir)) {
                return true;
            }
        }
        return false;
    }

    /**
     * Recursive Depth First Search (DFS) to find the path.
     * 
     * @param r Current Row
     * @param c Current Column
     * @param turns Number of turns made so far
     * @param currentDir Direction the path is currently moving
     * @return true if Start is reachable, false otherwise
     */
    private boolean dfs(int r, int c, int turns, Direction currentDir) {
        // 1. Base Case: Turn limit exceeded
        if (turns > MAX_TURNS) {
            return false;
        }

        // 2. Base Case: Reached Start
        if (r == startRow && c == startCol) {
            return true;
        }

        // 3. Pruning Optimization
        // If we have used 2 turns (1 remaining), and we are moving in a direction
        // that does not change the coordinate required to reach the target,
        // we must already be aligned with that target coordinate.
        // - Vertical moves (UP/DOWN) change Row, not Col. Target needs specific Col.
        // - Horizontal moves (LEFT/RIGHT) change Col, not Row. Target needs specific Row.
        if (turns == 2) {
            if (currentDir == Direction.UP || currentDir == Direction.DOWN) {
                if (c != startCol) return false;
            } else { // LEFT or RIGHT
                if (r != startRow) return false;
            }
        }

        // 4. Recursive Steps

        // A. Move Straight (No turn cost)
        int nextR = r + currentDir.dr;
        int nextC = c + currentDir.dc;
        if (isValid(nextR, nextC) && grid[nextR][nextC] != '*') {
            if (dfs(nextR, nextC, turns, currentDir)) {
                return true;
            }
        }

        // B. Turn and Move (Turn cost + 1)
        // Only proceed if we have room for a turn
        if (turns + 1 <= MAX_TURNS) {
            Direction[] perpendiculars = getPerpendiculars(currentDir);
            for (Direction nextDir : perpendiculars) {
                int pR = r + nextDir.dr;
                int pC = c + nextDir.dc;
                if (isValid(pR, pC) && grid[pR][pC] != '*') {
                    if (dfs(pR, pC, turns + 1, nextDir)) {
                        return true;
                    }
                }
            }
        }

        return false;
    }

    /**
     * Returns the two perpendicular directions to the given direction.
     * Note: This logic excludes 180-degree turns (backtracking), matching the original behavior.
     */
    private Direction[] getPerpendiculars(Direction dir) {
        if (dir == Direction.UP || dir == Direction.DOWN) {
            return new Direction[]{Direction.LEFT, Direction.RIGHT};
        } else {
            return new Direction[]{Direction.UP, Direction.DOWN};
        }
    }

    /**
     * Checks if coordinates are within grid bounds.
     */
    private boolean isValid(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /**
     * Enum representing movement directions with their row/column deltas.
     */
    private enum Direction {
        UP(-1, 0),
        DOWN(1, 0),
        LEFT(0, -1),
        RIGHT(0, 1);

        final int dr, dc;

        Direction(int dr, int dc) {
            this.dr = dr;
            this.dc = dc;
        }
    }
}

import java.util.Scanner;
import java.util.Arrays;

/**
 * A class to solve the maze pathfinding problem.
 * It determines if a path exists from 'S' to 'T' avoiding '*' obstacles,
 * with a maximum of 2 turns allowed.
 */
public class MazePathfinder {

    // Constants
    private static final int MAX_TURNS = 2;
    private static final int INITIAL_VISITED_VALUE = Integer.MAX_VALUE;

    // Direction vectors: Right, Left, Down, Up
    // Indices: 0, 1, 2, 3
    private static final int[][] DIRECTIONS = {
        {0, 1},   // Right
        {0, -1},  // Left
        {1, 0},   // Down
        {-1, 0}   // Up
    };

    private int rows;
    private int cols;
    private char[][] grid;
    private int[][][] visited; // Stores min turns to reach (x, y) facing a specific direction

    public MazePathfinder() {
        // Initialization happens in run() after reading dimensions
    }

    /**
     * Main execution method to read input and solve the maze.
     */
    public void run() {
        Scanner scanner = new Scanner(System.in);
        try {
            if (!scanner.hasNextInt()) return;

            this.rows = scanner.nextInt();
            this.cols = scanner.nextInt();

            // Initialize grid and visited array based on input dimensions
            this.grid = new char[rows][cols];
            this.visited = new int[rows][cols][4];
            initializeVisitedArray();

            int startX = -1;
            int startY = -1;

            // Read the grid and find the starting position
            for (int i = 0; i < rows; i++) {
                String line = scanner.next();
                for (int j = 0; j < cols; j++) {
                    grid[i][j] = line.charAt(j);
                    if (grid[i][j] == 'S') {
                        startX = i;
                        startY = j;
                    }
                }
            }

            // Perform DFS search
            // Initial direction is -1 (undefined), initial turns is -1
            boolean found = dfs(startX, startY, -1, -1);

            System.out.println(found ? "YES" : "NO");

        } finally {
            scanner.close();
        }
    }

    /**
     * Fills the visited array with a high value to represent unvisited states.
     */
    private void initializeVisitedArray() {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                Arrays.fill(visited[i][j], INITIAL_VISITED_VALUE);
            }
        }
    }

    /**
     * Depth First Search to find a path from Start to Target.
     * 
     * @param x Current x coordinate
     * @param y Current y coordinate
     * @param currentDir Direction we are currently facing (0-3), -1 if at start
     * @param currentTurns Number of turns made so far
     * @return true if target is reachable, false otherwise
     */
    private boolean dfs(int x, int y, int currentDir, int currentTurns) {
        // 1. Boundary Check
        if (x < 0 || x >= rows || y < 0 || y >= cols) {
            return false;
        }

        // 2. Obstacle Check
        if (grid[x][y] == '*') {
            return false;
        }

        // 3. Turn Limit Check
        // If turns exceed max allowed, this path is invalid
        if (currentTurns > MAX_TURNS) {
            return false;
        }

        // 4. Target Check
        if (grid[x][y] == 'T') {
            return true;
        }

        // 5. Visited State Pruning
        // If we have visited this cell facing this direction with fewer or equal turns,
        // there is no point in continuing this path as it won't be optimal.
        if (visited[x][y][currentDir] <= currentTurns) {
            return false;
        }

        // Update visited state with current turn count
        visited[x][y][currentDir] = currentTurns;

        // 6. Explore Neighbors
        for (int k = 0; k < 4; k++) {
            // Determine turns for the next step
            // If direction changes (k != currentDir), increment turns.
            // Note: If currentDir is -1 (start), k != -1 is always true, 
            // so the first move correctly increments turns to 0.
            int nextTurns = (k != currentDir) ? currentTurns + 1 : currentTurns;

            if (dfs(x + DIRECTIONS[k][0], y + DIRECTIONS[k][1], k, nextTurns)) {
                return true;
            }
        }

        return false;
    }

    public static void main(String[] args) {
        MazePathfinder solver = new MazePathfinder();
        solver.run();
    }
}

import java.io.*;
import java.util.StringTokenizer;

public class Main {
    // Direction vectors: Right, Left, Up, Down
    private static final int[] DR = {0, 0, -1, 1};
    private static final int[] DC = {1, -1, -1, 1};

    // Direction indices for perpendicular checks
    private static final int DIR_H = 0; // Horizontal movement
    private static final int DIR_V = 2; // Vertical movement

    private final RW rw;

    public Main() {
        this.rw = new RW("file.in", "file.out");
    }

    public static void main(String[] args) {
        new Main().run();
    }

    private void run() {
        solve();
        rw.close();
    }

    private void solve() {
        int n = rw.nextInt();
        int m = rw.nextInt();
        char[][] grid = new char[n][m];
        int[] startPos = new int[2];
        int[] targetPos = new int[2];

        // Read grid and locate Start (S) and Target (T)
        for (int i = 0; i < n; i++) {
            grid[i] = rw.next().toCharArray();
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == 'S') {
                    startPos[0] = i;
                    startPos[1] = j;
                } else if (grid[i][j] == 'T') {
                    targetPos[0] = i;
                    targetPos[1] = j;
                }
            }
        }

        int[][] counts = new int[n][m];
        int sx = startPos[0], sy = startPos[1];
        int tx = targetPos[0], ty = targetPos[1];

        // 1. Propagate reachability from Start (S) with value 1
        propagate(sx, sy, grid, counts, 1, DIR_RIGHT, m - sy);
        propagate(sx, sy, grid, counts, 1, DIR_LEFT, sy + 1);
        propagate(sx, sy, grid, counts, 1, DIR_UP, sx + 1);
        propagate(sx, sy, grid, counts, 1, DIR_DOWN, n - sx);
        counts[sx][sy] = 1;

        // 2. Propagate reachability from Target (T) with value 2
        // and check for intersections with S's paths
        boolean[] intersectionFound = new boolean[1];
        propagateWithCheck(tx, ty, grid, counts, 2, DIR_RIGHT, m - ty, tx, ty, n, m, intersectionFound);
        propagateWithCheck(tx, ty, grid, counts, 2, DIR_LEFT, ty + 1, tx, ty, n, m, intersectionFound);
        propagateWithCheck(tx, ty, grid, counts, 2, DIR_UP, tx + 1, tx, ty, n, m, intersectionFound);
        propagateWithCheck(tx, ty, grid, counts, 2, DIR_DOWN, n - tx, tx, ty, n, m, intersectionFound);

        // Final condition check
        if (counts[tx][ty] % 10 == 1 || counts[tx][ty] % 10 == 5 || intersectionFound[0]) {
            rw.println("YES");
        } else {
            rw.println("NO");
        }
    }

    /**
     * Propagates a value in a specific direction until a wall (*) or boundary is hit.
     */
    private void propagate(int r, int c, char[][] grid, int[][] counts, int value, int dir, int maxSteps) {
        for (int step = 0; step < maxSteps; step++) {
            int nr = r + DR[dir] * step;
            int nc = c + DC[dir] * step;
            if (grid[nr][nc] == '*') break;
            counts[nr][nc] += value;
        }
    }

    /**
     * Propagates a value in a specific direction and checks the perpendicular axis
     * for intersections with paths marked by value 1.
     */
    private void propagateWithCheck(int r, int c, char[][] grid, int[][] counts, int value,
                                    int dir, int maxSteps, int tx, int ty, int n, int m,
                                    boolean[] intersectionFound) {
        for (int step = 0; step < maxSteps; step++) {
            int nr = r + DR[dir] * step;
            int nc = c + DC[dir] * step;
            if (grid[nr][nc] == '*') break;

            counts[nr][nc] += value;
            checkPerpendicular(nr, nc, dir, grid, counts, intersectionFound, n, m);
        }
    }

    /**
     * Scans the perpendicular axis for any cell marked with value 1.
     * Stops scanning if a wall (*) is encountered.
     */
    private void checkPerpendicular(int r, int c, int dir, char[][] grid, int[][] counts,
                                    boolean[] intersectionFound, int n, int m) {
        if (dir % 2 == 0) { // Horizontal movement -> check vertical column
            for (int k = 0; k < n; k++) {
                if (grid[k][c] == '*') break;
                if (counts[k][c] == 1) {
                    intersectionFound[0] = true;
                    return;
                }
            }
        } else { // Vertical movement -> check horizontal row
            for (int k = 0; k < m; k++) {
                if (grid[r][k] == '*') break;
                if (counts[r][k] == 1) {
                    intersectionFound[0] = true;
                    return;
                }
            }
        }
    }

    /**
     * Fast I/O helper class. Handles file redirection or standard streams.
     */
    private static class RW {
        private final BufferedReader br;
        private final PrintWriter out;
        private StringTokenizer st;

        RW(String inputFile, String outputFile) {
            try {
                File f = new File(inputFile);
                if (f.exists() && f.canRead()) {
                    br = new BufferedReader(new FileReader(f));
                    out = new PrintWriter(new FileWriter(outputFile));
                } else {
                    br = new BufferedReader(new InputStreamReader(System.in));
                    out = new PrintWriter(new OutputStreamWriter(System.out));
                }
            } catch (IOException e) {
                throw new RuntimeException("Failed to initialize I/O streams", e);
            }
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input", e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            String s = next();
            return s == null ? 0 : Integer.parseInt(s);
        }

        void println(Object o) {
            out.println(o);
        }

        void close() {
            try {
                br.close();
                out.flush();
                out.close();
            } catch (IOException e) {
                throw new RuntimeException("Failed to close I/O streams", e);
            }
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

/**
 * Solves a grid pathfinding problem where movement is restricted to a maximum number of turns.
 * Uses DFS with memoization to determine if a path exists from 'S' to 'T'.
 */
public class GridPathFinder {

    private int rows, cols;
    private char[][] grid;
    private int startRow, startCol;
    private boolean[][][][] visited;

    // Maximum allowed turns before the path is considered invalid
    private static final int MAX_TURNS = 2;

    // Direction offsets: UP, RIGHT, DOWN, LEFT
    private static final int[] DR = {-1, 0, 1, 0};
    private static final int[] DC = {0, 1, 0, -1};

    public static void main(String[] args) throws IOException {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        GridPathFinder finder = new GridPathFinder();
        finder.readInput(reader);
        finder.solve();
    }

    /**
     * Reads grid dimensions and layout from standard input.
     */
    private void readInput(BufferedReader reader) throws IOException {
        String line = reader.readLine();
        if (line == null) return;

        StringTokenizer st = new StringTokenizer(line);
        rows = Integer.parseInt(st.nextToken());
        cols = Integer.parseInt(st.nextToken());

        grid = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            line = reader.readLine();
            if (line == null) break;
            for (int j = 0; j < cols; j++) {
                grid[i][j] = line.charAt(j);
                if (grid[i][j] == 'S') {
                    startRow = i;
                    startCol = j;
                }
            }
        }

        // Initialize visited array: [row][col][lastDirection][turns]
        // lastDirection: 0-3, turns: 0-2
        visited = new boolean[rows][cols][4][3];
    }

    /**
     * Orchestrates the pathfinding process and prints the result.
     */
    private void solve() {
        if (startRow == -1) {
            System.out.println("NO");
            return;
        }

        boolean possible = canReachTarget(startRow, startCol, -1, 0);
        System.out.println(possible ? "YES" : "NO");
    }

    /**
     * Recursively searches for 'T' with memoization.
     *
     * @param r       Current row
     * @param c       Current column
     * @param lastDir Direction taken to reach (r, c) (-1 for start)
     * @param turns   Number of turns made so far
     * @return true if target is reachable, false otherwise
     */
    private boolean canReachTarget(int r, int c, int lastDir, int turns) {
        // Boundary check
        if (r < 0 || r >= rows || c < 0 || c >= cols) {
            return false;
        }
        // Obstacle check
        if (grid[r][c] == '*') {
            return false;
        }
        // Turn limit check
        if (turns > MAX_TURNS) {
            return false;
        }

        // Target found
        if (grid[r][c] == 'T') {
            return true;
        }

        // Memoization check: skip if this exact state has been visited
        if (lastDir != -1 && visited[r][c][lastDir][turns]) {
            return false;
        }
        if (lastDir != -1) {
            visited[r][c][lastDir][turns] = true;
        }

        // Explore all 4 directions
        for (int dir = 0; dir < 4; dir++) {
            // Increment turn count only if direction changes (and we're past the start)
            int newTurns = (lastDir != -1 && dir != lastDir) ? turns + 1 : turns;

            if (canReachTarget(r + DR[dir], c + DC[dir], dir, newTurns)) {
                return true; // Early exit on success
            }
        }

        return false;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.OutputStreamWriter;
import java.io.PrintWriter;
import java.util.ArrayDeque;
import java.util.Arrays;
import java.util.StringTokenizer;

public class B {

    // Direction vectors: Right, Down, Left, Up
    private static final int[] DR = {0, 1, 0, -1};
    private static final int[] DC = {1, 0, -1, 0};

    public static void main(String[] args) {
        // Try-with-resources ensures streams are properly closed and flushed
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
             PrintWriter out = new PrintWriter(new OutputStreamWriter(System.out))) {

            FastScanner scanner = new FastScanner(br);
            solve(scanner, out);
            out.flush();
        } catch (IOException e) {
            System.err.println("I/O error: " + e.getMessage());
            System.exit(1);
        }
    }

    private static void solve(FastScanner scanner, PrintWriter out) throws IOException {
        String nStr = scanner.next();
        if (nStr == null) return;

        int n = Integer.parseInt(nStr);
        int m = Integer.parseInt(scanner.next());

        boolean[][] canWalk = new boolean[n][m];
        int startRow = -1, startCol = -1;
        int endRow = -1, endCol = -1;

        // Parse the grid and locate start/end points
        for (int i = 0; i < n; i++) {
            String rowStr = scanner.next();
            for (int j = 0; j < m; j++) {
                char c = rowStr.charAt(j);
                if (c == '.' || c == 'S' || c == 'T') {
                    canWalk[i][j] = true;
                }
                if (c == 'S') {
                    startRow = i;
                    startCol = j;
                } else if (c == 'T') {
                    endRow = i;
                    endCol = j;
                }
            }
        }

        // minTurns[direction][row][col] stores the minimum turns to reach (row, col) facing 'direction'
        int[][][] minTurns = new int[4][n][m];
        for (int d = 0; d < 4; d++) {
            for (int i = 0; i < n; i++) {
                Arrays.fill(minTurns[d][i], Integer.MAX_VALUE);
            }
        }

        ArrayDeque<State> queue = new ArrayDeque<>();
        // Initialize queue with all 4 possible starting directions at the start position
        for (int d = 0; d < 4; d++) {
            minTurns[d][startRow][startCol] = 0;
            queue.add(new State(d, startRow, startCol));
        }

        // 0-1 BFS: Moving forward costs 0 turns, turning costs 1 turn
        while (!queue.isEmpty()) {
            State current = queue.poll();
            int currentDir = current.direction;
            int currentRow = current.row;
            int currentCol = current.col;
            int currentTurns = minTurns[currentDir][currentRow][currentCol];

            // Optimization: paths exceeding 2 turns cannot satisfy the condition
            if (currentTurns > 2) {
                continue;
            }

            // Option 1: Move forward in the current direction (cost: 0)
            int nextRow = currentRow + DR[currentDir];
            int nextCol = currentCol + DC[currentDir];
            if (isValid(nextRow, nextCol, n, m, canWalk) && minTurns[currentDir][nextRow][nextCol] > currentTurns) {
                minTurns[currentDir][nextRow][nextCol] = currentTurns;
                queue.addFirst(new State(currentDir, nextRow, nextCol));
            }

            // Option 2: Turn to a new direction (cost: 1)
            for (int newDir = 0; newDir < 4; newDir++) {
                if (newDir == currentDir) continue;
                if (minTurns[newDir][currentRow][currentCol] > currentTurns + 1) {
                    minTurns[newDir][currentRow][currentCol] = currentTurns + 1;
                    queue.addLast(new State(newDir, currentRow, currentCol));
                }
            }
        }

        // Find the minimum turns required to reach the target from any direction
        int minTurnsToTarget = Integer.MAX_VALUE;
        for (int d = 0; d < 4; d++) {
            minTurnsToTarget = Math.min(minTurnsToTarget, minTurns[d][endRow][endCol]);
        }

        out.print(minTurnsToTarget <= 2 ? "YES" : "NO");
    }

    private static boolean isValid(int r, int c, int n, int m, boolean[][] canWalk) {
        return r >= 0 && r < n && c >= 0 && c < m && canWalk[r][c];
    }

    /**
     * Represents a state in the BFS queue.
     * Encapsulates direction and position for clear, maintainable code.
     */
    private static class State {
        final int direction;
        final int row;
        final int col;

        State(int direction, int row, int col) {
            this.direction = direction;
            this.row = row;
            this.col = col;
        }
    }

    /**
     * Fast I/O helper to replace manual BufferedReader/StringTokenizer boilerplate.
     */
    private static class FastScanner {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        FastScanner(BufferedReader reader) {
            this.reader = reader;
        }

        String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        int nextInt() throws IOException {
            String s = next();
            if (s == null) throw new IOException("Unexpected end of input");
            return Integer.parseInt(s);
        }
    }
}

import java.util.PriorityQueue;
import java.util.Scanner;

/**
 * Solves a grid pathfinding problem to determine if a target 'T' is reachable
 * from a start point 'S' with a maximum of 2 turns.
 * 
 * This refactored version improves maintainability by:
 * 1. Using descriptive variable and class names.
 * 2. Encapsulating logic into methods.
 * 3. Replacing magic numbers with named constants.
 * 4. Improving code structure and readability.
 */
public class GridPathSolver {

    // Constants for grid and algorithm configuration
    private static final int NUM_DIRECTIONS = 4;
    private static final int MAX_ALLOWED_TURNS = 2;
    private static final int WALL = 0;
    private static final int PATH = 1;
    private static final int INFINITY = Integer.MAX_VALUE / 3; // Safe infinity to prevent overflow during addition

    // Direction vectors: Down, Right, Up, Left
    // Indices: 0=Down, 1=Right, 2=Up, 3=Left
    // dy affects row index, dx affects column index
    private static final int[] DX = {0, 1, 0, -1};
    private static final int[] DY = {1, 0, -1, 0};

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        // Read dimensions
        if (scanner.hasNextInt()) {
            int rows = scanner.nextInt();
            int cols = scanner.nextInt();

            // Run the solver
            solve(rows, cols, scanner);
        }

        scanner.close();
    }

    /**
     * Main logic to parse the grid and run the pathfinding algorithm.
     */
    private static void solve(int rows, int cols, Scanner scanner) {
        // Create grid with a 1-cell padding border of walls (0)
        // Dimensions are (rows + 2) x (cols + 2) to handle boundary checks easily
        int[][] grid = new int[rows + 2][cols + 2];
        int startRow = 0;
        int startCol = 0;
        int endRow = 0;
        int endCol = 0;

        // Parse the grid input
        for (int r = 0; r < rows; r++) {
            String line = scanner.next();
            for (int c = 0; c < cols; c++) {
                char ch = line.charAt(c);

                // 0 represents a wall ('*'), 1 represents walkable space
                if (ch == '*') {
                    grid[r + 1][c + 1] = WALL;
                } else {
                    grid[r + 1][c + 1] = PATH;

                    // Identify Start ('S') and Target ('T') positions
                    if (ch == 'S') {
                        startRow = r + 1;
                        startCol = c + 1;
                    } else if (ch == 'T') {
                        endRow = r + 1;
                        endCol = c + 1;
                    }
                }
            }
        }

        // Distance array: dist[direction][row][col]
        // Stores the minimum turns required to reach (row, col) facing 'direction'
        int[][][] dist = new int[NUM_DIRECTIONS][rows + 2][cols + 2];

        // Initialize distances to infinity
        for (int d = 0; d < NUM_DIRECTIONS; d++) {
            for (int r = 0; r < dist[d].length; r++) {
                for (int c = 0; c < dist[d][r].length; c++) {
                    dist[d][r][c] = INFINITY;
                }
            }
        }

        // Priority Queue for Dijkstra's Algorithm (min-heap based on cost)
        PriorityQueue<Move> pq = new PriorityQueue<>();

        // Initialize the queue with the starting position in all 4 directions
        // Cost to start is 0 turns
        for (int d = 0; d < NUM_DIRECTIONS; d++) {
            dist[d][startRow][startCol] = 0;
            pq.add(new Move(startRow, startCol, d, 0));
        }

        // Dijkstra's Algorithm Loop
        while (!pq.isEmpty()) {
            Move current = pq.poll();

            // If the popped cost is greater than the known shortest distance, skip
            if (dist[current.direction][current.row][current.col] < current.cost) {
                continue;
            }

            // Try moving in 3 relative directions:
            // -1: Turn Right (relative to current heading logic)
            //  0: Go Straight
            // +1: Turn Left (relative to current heading logic)
            // Note: The specific mapping of -1/+1 to Left/Right depends on direction array order,
            // but since we check all 3, the logic holds for finding minimum turns.
            for (int turnOffset = -1; turnOffset < 2; turnOffset++) {
                int newDirection = (current.direction + turnOffset + NUM_DIRECTIONS) % NUM_DIRECTIONS;
                int newRow = current.row + DY[newDirection];
                int newCol = current.col + DX[newDirection];

                // Check if the new cell is within bounds (handled by padding) and not a wall
                if (grid[newRow][newCol] == WALL) {
                    continue;
                }

                // Calculate cost:
                // Straight movement (offset 0) costs 0 turns.
                // Turning (offset -1 or 1) costs 1 turn.
                int moveCost = Math.abs(turnOffset);
                int newCost = current.cost + moveCost;

                // Relaxation step: if we found a path with fewer turns, update and enqueue
                if (dist[newDirection][newRow][newCol] > newCost) {
                    dist[newDirection][newRow][newCol] = newCost;
                    pq.add(new Move(newRow, newCol, newDirection, newCost));
                }
            }
        }

        // Check if the target 'T' is reachable with <= MAX_ALLOWED_TURNS from any direction
        boolean possible = false;
        for (int d = 0; d < NUM_DIRECTIONS; d++) {
            if (dist[d][endRow][endCol] <= MAX_ALLOWED_TURNS) {
                possible = true;
                break;
            }
        }

        // Output result
        System.out.println(possible ? "YES" : "NO");
    }

    /**
     * Represents a state in the pathfinding search.
     */
    private static class Move implements Comparable<Move> {
        private final int row;
        private final int col;
        private final int direction;
        private final int cost;

        public Move(int row, int col, int direction, int cost) {
            this.row = row;
            this.col = col;
            this.direction = direction;
            this.cost = cost;
        }

        @Override
        public int compareTo(Move other) {
            return Integer.compare(this.cost, other.cost);
        }

        @Override
        public String toString() {
            return String.format("Dir:%d Pos:[%d,%d] Cost:%d", direction, row, col, cost);
        }
    }
}

import java.util.Arrays;
import java.util.Scanner;

/**
 * Solves a grid pathfinding problem where the goal is to determine if a path
 * exists from 'S' to 'T' with at most 2 direction changes (turns).
 * Uses DFS with memoization and backtracking.
 */
public class GridPathFinder {

    private static final int MAX_TURNS = 2;
    private static final char START = 'S';
    private static final char TARGET = 'T';
    private static final char OBSTACLE = '*';

    // Direction vectors: Up, Right, Down, Left
    private static final int[] DX = {-1, 0, 1, 0};
    private static final int[] DY = {0, 1, 0, -1};

    private final int rows;
    private final int cols;
    private final char[][] grid;
    private final boolean[][] visited;
    // dp[dir][r][c][turn] stores -1 (uncomputed), 0 (false), or 1 (true)
    private final int[][][][] dp;

    private int startR, startC;
    private int targetR, targetC;

    /**
     * Parses input and initializes the grid and data structures.
     */
    public GridPathFinder(Scanner scanner) {
        if (!scanner.hasNextLine()) {
            throw new IllegalArgumentException("Input is empty");
        }

        String[] dims = scanner.nextLine().trim().split("\\s+");
        this.rows = Integer.parseInt(dims[0]);
        this.cols = Integer.parseInt(dims[1]);

        this.grid = new char[rows][cols];
        this.visited = new boolean[rows][cols];
        this.dp = new int[4][rows][cols][3]; // turn can be 0, 1, or 2

        // Initialize DP table with -1 to indicate uncomputed states
        for (int d = 0; d < 4; d++) {
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    Arrays.fill(dp[d][r][c], -1);
                }
            }
        }

        // Read grid and locate start/target positions
        for (int i = 0; i < rows; i++) {
            String line = scanner.nextLine();
            for (int j = 0; j < cols; j++) {
                grid[i][j] = line.charAt(j);
                if (grid[i][j] == START) {
                    startR = i;
                    startC = j;
                } else if (grid[i][j] == TARGET) {
                    targetR = i;
                    targetC = j;
                }
            }
        }
    }

    /**
     * Checks if the target is reachable from the start position with <= MAX_TURNS.
     */
    public boolean canReach() {
        // Try starting in all 4 possible initial directions
        for (int dir = 0; dir < 4; dir++) {
            if (dfs(dir, startR, startC, 0)) {
                return true;
            }
        }
        return false;
    }

    /**
     * Depth-first search with memoization and backtracking.
     *
     * @param dir   Current facing direction (0:Up, 1:Right, 2:Down, 3:Left)
     * @param r     Current row
     * @param c     Current column
     * @param turn  Number of turns made so far
     * @return true if target is reachable, false otherwise
     */
    private boolean dfs(int dir, int r, int c, int turn) {
        if (turn > MAX_TURNS) {
            return false;
        }
        if (grid[r][c] == TARGET) {
            return true;
        }
        if (dp[dir][r][c][turn] != -1) {
            return dp[dir][r][c][turn] == 1;
        }

        visited[r][c] = true;
        boolean found = false;

        for (int nextDir = 0; nextDir < 4; nextDir++) {
            int nr = r + DX[nextDir];
            int nc = c + DY[nextDir];

            if (isValid(nr, nc) && grid[nr][nc] != OBSTACLE && !visited[nr][nc]) {
                // Increment turn count only if direction changes
                int nextTurn = turn + (nextDir == dir ? 0 : 1);
                if (dfs(nextDir, nr, nc, nextTurn)) {
                    found = true;
                    break; // Early exit: no need to search further once path is found
                }
            }
        }

        visited[r][c] = false; // Backtrack
        dp[dir][r][c][turn] = found ? 1 : 0;
        return found;
    }

    /**
     * Checks if coordinates are within grid bounds.
     */
    private boolean isValid(int r, int c) {
        return r >= 0 && c >= 0 && r < rows && c < cols;
    }

    public static void main(String[] args) {
        // try-with-resources ensures the scanner is properly closed
        try (Scanner scanner = new Scanner(System.in)) {
            GridPathFinder finder = new GridPathFinder(scanner);
            System.out.println(finder.canReach() ? "YES" : "NO");
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

public class IgorToWork {

    // Instance variables to encapsulate state and remove static dependencies
    private int n, m;
    private char[][] grid;
    private int startX, startY, targetX, targetY;
    private boolean[][][][] visited;

    // Direction vectors: Up, Left, Down, Right
    private static final int[] DIR_X = {-1, 0, 1, 0};
    private static final int[] DIR_Y = {0, -1, 0, 1};
    private static final int MAX_TURNS = 2;

    public static void main(String[] args) {
        IgorToWork solver = new IgorToWork();
        try {
            solver.solve();
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    private void solve() throws IOException {
        FastScanner in = new FastScanner(System.in);

        // Read dimensions
        String nStr = in.next();
        if (nStr == null) return; // Handle empty input gracefully
        n = Integer.parseInt(nStr);
        m = in.nextInt();

        // Read grid
        grid = new char[n][m];
        for (int i = 0; i < n; i++) {
            String row = in.next();
            grid[i] = row.toCharArray();
        }

        // Locate Start (S) and Target (T)
        findStartAndTarget();

        // Initialize visited array
        // Dimensions: [direction][turns][x][y]
        // direction: 0-3, turns: 0-2, x: 0-n-1, y: 0-m-1
        visited = new boolean[4][3][n][m];

        // Try starting the path in each of the 4 cardinal directions.
        // We pass the initial direction 'd' as the 'dir' argument to dfs.
        // This simulates entering the start node from direction 'd', 
        // allowing movement in direction 'd' to cost 0 turns.
        for (int d = 0; d < 4; d++) {
            if (dfs(startX, startY, 0, d)) {
                System.out.println("YES");
                return;
            }
        }

        System.out.println("NO");
    }

    private void findStartAndTarget() {
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == 'S') {
                    startX = i;
                    startY = j;
                    grid[i][j] = '.'; // Treat start as walkable empty space
                } else if (grid[i][j] == 'T') {
                    targetX = i;
                    targetY = j;
                    grid[i][j] = '.'; // Treat target as walkable empty space
                }
            }
        }
    }

    /**
     * Depth First Search to find a path with at most MAX_TURNS turns.
     * 
     * @param x Current X coordinate
     * @param y Current Y coordinate
     * @param turns Number of turns made so far
     * @param dir Direction from which we arrived at (x, y)
     * @return true if target is reachable, false otherwise
     */
    private boolean dfs(int x, int y, int turns, int dir) {
        // Check boundaries and obstacles
        if (x < 0 || x >= n || y < 0 || y >= m || grid[x][y] == '*') {
            return false;
        }

        // Check turn limit
        if (turns > MAX_TURNS) {
            return false;
        }

        // Check if target reached
        if (x == targetX && y == targetY) {
            return true;
        }

        // Check if this state has already been visited
        // State is defined by (x, y), turns used, and arrival direction
        if (visited[dir][turns][x][y]) {
            return false;
        }

        // Mark state as visited
        visited[dir][turns][x][y] = true;

        // Explore all 4 directions
        for (int d = 0; d < 4; d++) {
            // Calculate new turns: +1 if direction changes, else +0
            // dir is the direction we arrived from, d is the direction we are moving to
            int newTurns = turns + (dir == d ? 0 : 1);

            // Optimization: Only recurse if within turn limit
            if (newTurns <= MAX_TURNS) {
                if (dfs(x + DIR_X[d], y + DIR_Y[d], newTurns, d)) {
                    return true;
                }
            }
        }

        return false;
    }

    /**
     * Helper class for fast input reading.
     */
    private static class FastScanner {
        BufferedReader reader;
        StringTokenizer tokenizer;

        public FastScanner(InputStream i) {
            reader = new BufferedReader(new InputStreamReader(i));
            tokenizer = new StringTokenizer("");
        }

        public String next() throws IOException {
            while (!tokenizer.hasMoreTokens()) {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            String s = next();
            if (s == null) throw new IOException("Unexpected end of input");
            return Integer.parseInt(s);
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Solves a grid pathfinding problem where the goal is to reach 'T' from 'S'
 * with at most 3 direction changes. Uses 0-1 BFS for optimal performance.
 */
public class TurnLimitedPathfinder {
    private static final int MAX_TURNS = 3;
    // Directions: Down, Up, Left, Right
    private static final int[] DR = {1, -1, 0, 0};
    private static final int[] DC = {0, 0, -1, 1};

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            int rows = scanner.nextInt();
            int cols = scanner.nextInt();
            char[][] grid = new char[rows][cols];
            CellState start = null;

            for (int i = 0; i < rows; i++) {
                grid[i] = scanner.next().toCharArray();
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j] == 'S') {
                        start = new CellState(i, j, 0, -1);
                    }
                }
            }

            boolean reachable = false;
            // Try all 4 initial directions. If any yields a valid path, we're done.
            for (int initialDir = 0; initialDir < 4; initialDir++) {
                if (canReachTarget(grid, initialDir, start, rows, cols)) {
                    reachable = true;
                    break;
                }
            }

            out.println(reachable ? "YES" : "NO");
        } catch (Exception e) {
            // Graceful fallback for malformed input or unexpected errors
            out.println("NO");
        } finally {
            out.flush();
        }
    }

    /**
     * Performs 0-1 BFS to check if 'T' is reachable from 'start' 
     * when initially facing 'initialDir', respecting the turn limit.
     */
    private static boolean canReachTarget(char[][] grid, int initialDir, CellState start, int rows, int cols) {
        Deque<CellState> deque = new ArrayDeque<>();
        // Create a fresh instance to avoid mutating the original start state
        CellState initialState = new CellState(start.row, start.col, 0, initialDir);
        deque.add(initialState);

        boolean[][][] visited = new boolean[rows][cols][4];
        visited[start.row][start.col][initialDir] = true;

        while (!deque.isEmpty()) {
            CellState current = deque.pollFirst();

            if (grid[current.row][current.col] == 'T') {
                if (current.turns < MAX_TURNS) {
                    return true;
                }
                continue;
            }

            for (int dir = 0; dir < 4; dir++) {
                int nextRow = current.row + DR[dir];
                int nextCol = current.col + DC[dir];

                if (!isValid(nextRow, nextCol, rows, cols)) continue;
                if (grid[nextRow][nextCol] == '*') continue;
                if (visited[nextRow][nextCol][dir]) continue;

                int newTurns = current.turns + (dir != current.dir ? 1 : 0);
                if (newTurns > MAX_TURNS) continue;

                visited[nextRow][nextCol][dir] = true;
                CellState nextState = new CellState(nextRow, nextCol, newTurns, dir);

                // 0-1 BFS optimization: same direction costs 0 (front), 
                // direction change costs 1 (back)
                if (dir == current.dir) {
                    deque.addFirst(nextState);
                } else {
                    deque.addLast(nextState);
                }
            }
        }
        return false;
    }

    private static boolean isValid(int r, int c, int rows, int cols) {
        return r >= 0 && c >= 0 && r < rows && c < cols;
    }

    /**
     * Immutable state representation for BFS traversal.
     */
    private static class CellState {
        final int row;
        final int col;
        final int turns;
        final int dir;

        CellState(int row, int col, int turns, int dir) {
            this.row = row;
            this.col = col;
            this.turns = turns;
            this.dir = dir;
        }
    }

    /**
     * High-performance scanner for competitive programming / large inputs.
     */
    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
            st = new StringTokenizer("");
        }

        public String next() {
            while (!st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            String s = next();
            return s == null ? 0 : Integer.parseInt(s);
        }
    }
}

import java.util.Arrays;
import java.util.LinkedList;
import java.util.Queue;
import java.util.Scanner;

/**
 * A solver for grid-based pathfinding problems.
 * This class encapsulates the logic for finding a path from 'S' to 'T'
 * with specific movement cost constraints.
 */
public class MazeSolver {

    // Direction vectors: Right (0), Down (1), Up (2), Left (3)
    private static final int[] DX = {0, 1, -1, 0};
    private static final int[] DY = {1, 0, 0, -1};

    private static final int MAX_COST = 100;
    private static final int MAX_ALLOWED_COST = 2;

    /**
     * Represents a state in the BFS traversal.
     * Contains coordinates and the current direction of movement.
     */
    private static class State {
        private int x, y, direction;

        State(int x, int y, int direction) {
            this.x = x;
            this.y = y;
            this.direction = direction;
        }
    }

    public static void main(String[] args) {
        // Use try-with-resources to automatically close the scanner
        try (Scanner scanner = new Scanner(System.in)) {
            if (!scanner.hasNextInt()) {
                return;
            }

            int rows = scanner.nextInt();
            int cols = scanner.nextInt();

            // Use char[][] for easier character access and better performance
            char[][] grid = new char[rows][cols];
            int startX = 0;
            int startY = 0;

            // Read the grid and locate the Start position 'S'
            for (int i = 0; i < rows; i++) {
                String rowStr = scanner.next();
                grid[i] = rowStr.toCharArray();
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j] == 'S') {
                        startX = i;
                        startY = j;
                    }
                }
            }

            // Solve the problem and print result
            boolean canReach = solve(grid, rows, cols, startX, startY);
            System.out.println(canReach ? "YES" : "NO");
        }
    }

    /**
     * Solves the pathfinding problem using a modified BFS (Dijkstra-like).
     * 
     * @param grid    The 2D character grid.
     * @param rows    Number of rows in the grid.
     * @param cols    Number of columns in the grid.
     * @param startX  Starting X coordinate.
     * @param startY  Starting Y coordinate.
     * @return true if the Target 'T' is reachable with cost <= 2, false otherwise.
     */
    private static boolean solve(char[][] grid, int rows, int cols, int startX, int startY) {
        // dp[x][y][direction] stores the minimum cost to reach cell (x,y) facing 'direction'
        int[][][] dp = new int[rows][cols][4];

        // Initialize DP table with a value larger than any possible path cost
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                Arrays.fill(dp[i][j], MAX_COST);
            }
        }

        Queue<State> queue = new LinkedList<>();

        // Initialize the queue with the starting position facing all 4 directions.
        // The cost to start is 0 for all initial directions.
        for (int d = 0; d < 4; d++) {
            queue.add(new State(startX, startY, d));
            dp[startX][startY][d] = 0;
        }

        while (!queue.isEmpty()) {
            State current = queue.poll();

            // Check if we reached the Target 'T' with an acceptable cost
            // Note: Logic preserved from original code
            if (grid[current.x][current.y] == 'T' && dp[current.x][current.y][current.direction] <= MAX_ALLOWED_COST) {
                return true;
            }

            // Explore neighbors
            for (int d = 0; d < 4; d++) {
                int nextX = current.x + DX[d];
                int nextY = current.y + DY[d];

                // Boundary checks
                if (nextX < 0 || nextX >= rows || nextY < 0 || nextY >= cols) {
                    continue;
                }

                // Obstacle check
                if (grid[nextX][nextY] == '*') {
                    continue;
                }

                // Calculate cost
                // Moving in the same direction adds 0 cost, changing direction adds 1 cost
                int cost = dp[current.x][current.y][current.direction] + (d != current.direction ? 1 : 0);

                // Relaxation step: if we found a cheaper path to this state
                if (dp[nextX][nextY][d] > cost) {
                    dp[nextX][nextY][d] = cost;
                    queue.add(new State(nextX, nextY, d));
                }
            }
        }

        return false;
    }
}

import java.util.Scanner;

/**
 * Solves a grid-based pathfinding problem where a character moves from 'S' to 'T'.
 * Movement allows up to 2 turns, with obstacles marked as '*'.
 */
public class GridPathSolver {

    // Direction vectors: index 1=Up, 2=Right, 3=Down, 4=Left
    // Matches original: mox = {0, 0, 1, 0, -1}, moy = {0, -1, 0, 1, 0}
    private static final int[] DX = {0, 0, 1, 0, -1};
    private static final int[] DY = {0, -1, 0, 1, 0};

    private static final int MAX_TURNS = 2;
    private static final int NUM_DIRECTIONS = 5; // Index 0 unused, 1-4 are valid

    private int n, m;
    private char[][] grid;
    private boolean[][][][] visited;

    /**
     * Reads input, initializes the grid and state, and determines path existence.
     */
    public void solve() {
        Scanner scanner = new Scanner(System.in);
        if (!scanner.hasNextInt()) {
            return;
        }

        n = scanner.nextInt();
        m = scanner.nextInt();
        scanner.nextLine(); // Consume the newline after m

        grid = new char[n][m];
        int startX = 0, startY = 0;

        for (int i = 0; i < n; i++) {
            String line = scanner.nextLine();
            for (int j = 0; j < line.length() && j < m; j++) {
                char c = line.charAt(j);
                if (c == 'S') {
                    startY = i;
                    startX = j;
                    grid[i][j] = '.'; // Treat start position as empty space
                } else {
                    grid[i][j] = c;
                }
            }
        }

        // visited[x][y][turnCount][direction]
        // Dimensions: [width][height][turns+1][directions]
        visited = new boolean[m][n][MAX_TURNS + 1][NUM_DIRECTIONS];

        boolean possible = false;
        // Try starting in each of the 4 cardinal directions
        for (int d = 1; d <= 4; d++) {
            if (canReach(startX, startY, 0, d)) {
                possible = true;
                break;
            }
        }

        System.out.println(possible ? "YES" : "NO");
    }

    /**
     * Recursive DFS to find if target 'T' is reachable from the current state.
     *
     * @param x         Current x-coordinate
     * @param y         Current y-coordinate
     * @param turnCount Number of turns made so far
     * @param currentDir Current movement direction (1-4)
     * @return true if target is reachable, false otherwise
     */
    private boolean canReach(int x, int y, int turnCount, int currentDir) {
        int nx = x + DX[currentDir];
        int ny = y + DY[currentDir];

        // Boundary check
        if (nx < 0 || nx >= m || ny < 0 || ny >= n) {
            return false;
        }

        // State visited check to prevent redundant computations
        if (visited[x][y][turnCount][currentDir]) {
            return false;
        }

        // Obstacle check
        if (grid[ny][nx] == '*') {
            return false;
        }

        // Target check
        if (grid[ny][nx] == 'T') {
            return true;
        }

        // Mark state as visited and temporarily block the cell to prevent cycles
        visited[x][y][turnCount][currentDir] = true;
        grid[ny][nx] = '*';

        boolean found = false;

        if (turnCount == MAX_TURNS) {
            // Max turns reached: can only continue straight
            found = canReach(nx, ny, MAX_TURNS, currentDir);
        } else {
            // Can continue straight or turn (up to 3 new directions)
            for (int d = 1; d <= 4; d++) {
                int nextTurn = (d == currentDir) ? turnCount : turnCount + 1;
                if (canReach(nx, ny, nextTurn, d)) {
                    found = true;
                    break;
                }
            }
        }

        // Backtrack: restore the cell to allow other paths to use it
        grid[ny][nx] = '.';

        return found;
    }

    public static void main(String[] args) {
        new GridPathSolver().solve();
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.Arrays;
import java.util.StringTokenizer;

/**
 * Solves a grid pathfinding problem where the goal is to determine if a path exists
 * from 'S' to 'T' with a maximum of 2 turns allowed.
 * 
 * Refactoring improvements:
 * - Encapsulation: Replaced global static fields with instance variables.
 * - Constants: Extracted magic numbers into named constants.
 * - Resource Management: Used try-with-resources for automatic stream cleanup.
 * - Control Flow: Replaced boolean flag accumulation with early return for efficiency.
 * - Naming: Improved readability with descriptive identifiers.
 * - Input Handling: Simplified and robustified the fast I/O helper.
 * - Validation: Added basic bounds and null checks for safer execution.
 */
public class GridPathSolver {

    private static final int[] DELTA_X = {1, 0, -1, 0};
    private static final int[] DELTA_Y = {0, 1, 0, -1};
    private static final int MAX_TURNS = 2;
    private static final int INITIAL_VISITED_THRESHOLD = MAX_TURNS + 1;

    private int rows, cols;
    private char[][] grid;
    private int startX, startY, targetX, targetY;
    private int[][][] minTurnsToReach;

    /**
     * Executes the pathfinding algorithm and returns whether the target is reachable.
     */
    public boolean solve() {
        // Initialize visited array with threshold value
        minTurnsToReach = new int[rows][cols][DELTA_X.length];
        for (int[][] row : minTurnsToReach) {
            for (int[] col : row) {
                Arrays.fill(col, INITIAL_VISITED_THRESHOLD);
            }
        }

        boolean canReach = false;
        // Attempt to move in all 4 directions from the starting position
        for (int dir = 0; dir < DELTA_X.length; dir++) {
            int nextX = startX + DELTA_X[dir];
            int nextY = startY + DELTA_Y[dir];
            if (isValid(nextX, nextY)) {
                minTurnsToReach[nextX][nextY][dir] = 0;
                canReach |= dfs(nextX, nextY, dir);
            }
        }
        return canReach;
    }

    /**
     * Checks if the given coordinates are within bounds and not blocked.
     */
    private boolean isValid(int x, int y) {
        return x >= 0 && x < rows && y >= 0 && y < cols && grid[x][y] != '*';
    }

    /**
     * Depth-First Search with state pruning based on turn count.
     *
     * @param x Current row
     * @param y Current column
     * @param currentDir Direction we arrived from (0: Down, 1: Right, 2: Up, 3: Left)
     * @return true if target is reachable, false otherwise
     */
    private boolean dfs(int x, int y, int currentDir) {
        if (x == targetX && y == targetY) {
            return true;
        }

        for (int nextDir = 0; nextDir < DELTA_X.length; nextDir++) {
            int nextX = x + DELTA_X[nextDir];
            int nextY = y + DELTA_Y[nextDir];
            int turns = minTurnsToReach[x][y][currentDir] + (nextDir == currentDir ? 0 : 1);

            if (isValid(nextX, nextY) && turns <= MAX_TURNS && turns < minTurnsToReach[nextX][nextY][nextDir]) {
                minTurnsToReach[nextX][nextY][nextDir] = turns;
                if (dfs(nextX, nextY, nextDir)) {
                    return true; // Early exit upon finding a valid path
                }
            }
        }
        return false;
    }

    public static void main(String[] args) {
        // Use try-with-resources for automatic and safe resource cleanup
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
             PrintWriter writer = new PrintWriter(System.out)) {

            FastScanner scanner = new FastScanner(reader);
            GridPathSolver solver = new GridPathSolver();

            // Read dimensions
            String rowToken = scanner.next();
            String colToken = scanner.next();
            solver.rows = Integer.parseInt(rowToken);
            solver.cols = Integer.parseInt(colToken);

            solver.grid = new char[solver.rows][];

            // Read grid and locate start/target
            for (int i = 0; i < solver.rows; i++) {
                String line = scanner.next();
                solver.grid[i] = line.toCharArray();
                for (int j = 0; j < solver.grid[i].length; j++) {
                    char cell = solver.grid[i][j];
                    if (cell == 'S') {
                        solver.startX = i;
                        solver.startY = j;
                    } else if (cell == 'T') {
                        solver.targetX = i;
                        solver.targetY = j;
                    }
                }
            }

            // Validate that start and target were found
            if (solver.startX == 0 && solver.startY == 0 && solver.grid[0][0] != 'S') {
                throw new IllegalStateException("Start position 'S' not found in the grid.");
            }
            if (solver.targetX == 0 && solver.targetY == 0 && solver.grid[0][0] != 'T') {
                throw new IllegalStateException("Target position 'T' not found in the grid.");
            }

            // Solve and output result
            boolean result = solver.solve();
            writer.println(result ? "YES" : "NO");
            writer.flush();

        } catch (IOException e) {
            System.err.println("I/O error occurred: " + e.getMessage());
        } catch (IllegalStateException e) {
            System.err.println("Validation error: " + e.getMessage());
        }
    }

    /**
     * Lightweight fast I/O helper to avoid overhead of java.util.Scanner.
     */
    private static class FastScanner {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastScanner(BufferedReader reader) {
            this.reader = reader;
        }

        public String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                String line = reader.readLine();
                if (line == null) {
                    throw new IOException("Unexpected end of input");
                }
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Determines if a target 'T' is reachable from a starting point 'S'
 * in a grid with obstacles '*', simulating propagation over a fixed
 * number of directional sweeps.
 */
public class GridReachabilityChecker {

    private static final int MAX_STEPS = 3;

    public static void main(String[] args) {
        FastReader reader = new FastReader();
        PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out));

        try {
            int n = reader.nextInt();
            int m = reader.nextInt();

            // Read grid rows. Using next() avoids newline-consumption bugs 
            // that occur when mixing StringTokenizer and BufferedReader.readLine().
            char[][] grid = new char[n][];
            for (int i = 0; i < n; i++) {
                grid[i] = reader.next().toCharArray();
            }

            // Initialize reachability map with starting positions
            boolean[][] reachable = new boolean[n][m];
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    if (grid[i][j] == 'S') {
                        reachable[i][j] = true;
                    }
                }
            }

            // Simulate directional propagation for the specified number of steps
            for (int step = 0; step < MAX_STEPS; step++) {
                boolean[][] nextReachable = new boolean[n][m];

                propagate(grid, reachable, nextReachable, Direction.LEFT_TO_RIGHT);
                propagate(grid, reachable, nextReachable, Direction.TOP_TO_BOTTOM);
                propagate(grid, reachable, nextReachable, Direction.RIGHT_TO_LEFT);
                propagate(grid, reachable, nextReachable, Direction.BOTTOM_TO_TOP);

                reachable = nextReachable;
            }

            // Check if any target 'T' is reachable
            boolean foundTarget = false;
            outerLoop:
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    if (reachable[i][j] && grid[i][j] == 'T') {
                        foundTarget = true;
                        break outerLoop;
                    }
                }
            }

            out.println(foundTarget ? "YES" : "NO");
        } catch (Exception e) {
            System.err.println("Runtime error: " + e.getMessage());
        } finally {
            out.flush();
            out.close();
        }
    }

    /**
     * Enum representing the four cardinal sweep directions.
     */
    private enum Direction {
        LEFT_TO_RIGHT, RIGHT_TO_LEFT, TOP_TO_BOTTOM, BOTTOM_TO_TOP
    }

    /**
     * Propagates reachability along a single direction across the grid.
     * Accumulates results into nextReachable using bitwise OR.
     */
    private static void propagate(char[][] grid, boolean[][] currentReachable, 
                                  boolean[][] nextReachable, Direction dir) {
        int n = grid.length;
        int m = grid[0].length;
        boolean ok = false;

        if (dir == Direction.LEFT_TO_RIGHT || dir == Direction.RIGHT_TO_LEFT) {
            // Horizontal sweeps
            for (int i = 0; i < n; i++) {
                ok = false;
                int start = (dir == Direction.LEFT_TO_RIGHT) ? 0 : m - 1;
                int end   = (dir == Direction.LEFT_TO_RIGHT) ? m : -1;
                int step  = (dir == Direction.LEFT_TO_RIGHT) ? 1 : -1;

                for (int j = start; j != end; j += step) {
                    ok |= currentReachable[i][j];
                    ok &= (grid[i][j] != '*');
                    nextReachable[i][j] |= ok;
                }
            }
        } else {
            // Vertical sweeps
            for (int j = 0; j < m; j++) {
                ok = false;
                int start = (dir == Direction.TOP_TO_BOTTOM) ? 0 : n - 1;
                int end   = (dir == Direction.TOP_TO_BOTTOM) ? n : -1;
                int step  = (dir == Direction.TOP_TO_BOTTOM) ? 1 : -1;

                for (int i = start; i != end; i += step) {
                    ok |= currentReachable[i][j];
                    ok &= (grid[i][j] != '*');
                    nextReachable[i][j] |= ok;
                }
            }
        }
    }

    /**
     * High-performance input reader for competitive programming / large inputs.
     */
    static class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        public String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input", e);
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            String token = next();
            if (token == null) throw new RuntimeException("Unexpected end of input");
            return Integer.parseInt(token);
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

/**
 * Solves a grid pathfinding problem where the goal 'T' must be reachable 
 * from 'S' with at most 2 turns. Uses DFS with memoization.
 */
public class C_793_B {

    // Constants
    private static final int MAX_TURNS = 2;
    // Directions: 0=Down, 1=Up, 2=Right, 3=Left
    private static final int[] DR = {1, -1, 0, 0};
    private static final int[] DC = {0, 0, 1, -1};

    // Instance state to avoid static pollution
    private int rows, cols;
    private char[][] grid;
    private boolean[][][][] visited;

    public static void main(String[] args) {
        C_793_B solver = new C_793_B();
        // Try-with-resources ensures proper stream closure
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            FastScanner scanner = new FastScanner(br);
            boolean reachable = solver.solve(scanner);
            System.out.println(reachable ? "YES" : "NO");
        } catch (IOException e) {
            System.err.println("I/O Error: " + e.getMessage());
        }
    }

    /**
     * Reads input, initializes the grid, finds the start position, 
     * and triggers the DFS search.
     */
    public boolean solve(FastScanner in) throws IOException {
        rows = in.nextInt();
        cols = in.nextInt();
        grid = new char[rows][cols];
        int startR = -1, startC = -1;

        for (int i = 0; i < rows; i++) {
            String line = in.next();
            grid[i] = line.toCharArray();
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == 'S') {
                    startR = i;
                    startC = j;
                }
            }
        }

        // visited[r][c][turns][lastDir + 1]
        // lastDir: -1 (start), 0-3 (directions). Offset by 1 for safe array indexing.
        visited = new boolean[rows][cols][MAX_TURNS + 1][5];

        return dfs(startR, startC, 0, -1);
    }

    /**
     * Depth-First Search with memoization.
     * @param r Current row
     * @param c Current column
     * @param turns Current number of turns made
     * @param lastDir Direction taken to reach (r, c). -1 for start.
     * @return true if 'T' is reachable within turn limits, false otherwise
     */
    private boolean dfs(int r, int c, int turns, int lastDir) {
        // Check bounds, obstacles, and if this state was already visited
        if (r < 0 || r >= rows || c < 0 || c >= cols || 
            grid[r][c] == '*' || visited[r][c][turns][lastDir + 1]) {
            return false;
        }

        // Target reached
        if (grid[r][c] == 'T') {
            return turns <= MAX_TURNS;
        }

        // Mark state as visited
        visited[r][c][turns][lastDir + 1] = true;

        // Explore all 4 directions
        for (int dir = 0; dir < 4; dir++) {
            int nr = r + DR[dir];
            int nc = c + DC[dir];

            // A turn is needed if we've moved before and the direction changes axis
            boolean needsTurn = lastDir != -1 && isVertical(lastDir) != isVertical(dir);
            int newTurns = needsTurn ? turns + 1 : turns;

            // Prune paths that exceed turn limit
            if (newTurns > MAX_TURNS) continue;

            if (dfs(nr, nc, newTurns, dir)) {
                return true;
            }
        }
        return false;
    }

    /**
     * Determines if a direction index corresponds to vertical movement.
     */
    private boolean isVertical(int dir) {
        return dir < 2; // 0: Down, 1: Up
    }

    /**
     * Optimized scanner for fast competitive programming I/O.
     */
    private static class FastScanner {
        private final BufferedReader in;
        private StringTokenizer st;

        public FastScanner(BufferedReader in) {
            this.in = in;
        }

        public String next() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                String line = in.readLine();
                if (line == null) {
                    return null;
                }
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

        public int nextInt() throws IOException {
            String token = next();
            if (token == null) {
                throw new IOException("Unexpected end of input");
            }
            return Integer.parseInt(token);
        }
    }
}

