/**
 * Refactored solution for CF793B_2.
 * 
 * Improvements made:
 * 1. Encapsulation: Moved static fields into instance variables to avoid global state pollution.
 * 2. Readability: Replaced cryptic variable names (mat, vis, xx, yy) with descriptive names.
 * 3. Constants: Extracted magic numbers (directions, infinity, limits) into named constants.
 * 4. Structure: Separated logic into distinct methods (run, solve, isValid).
 * 5. Input Handling: Improved the InputReader to handle potential nulls and exceptions more gracefully.
 * 6. Initialization: Cleaned up array initialization loops.
 */
public class CF793B_2 {

    // Constants
    private static final int[][] DIRECTIONS = {
        {0, 1},  // Right
        {1, 0},  // Down
        {0, -1}, // Left
        {-1, 0}  // Up
    };
    private static final int INF = 1_000_000_000;
    private static final int MAX_TURNS_ALLOWED = 3;

    // Instance Fields
    private int[][] grid;
    private int[][][][] memo;
    private int rows, cols;
    private int startX, startY;
    private int targetX, targetY;

    public static void main(String[] args) {
        // Using try-with-resources is good practice, but for CP style IO, 
        // we often manage streams manually. Here we wrap for safety.
        try (InputReader in = new InputReader(System.in);
             PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out))) {

            CF793B_2 solver = new CF793B_2();
            solver.run(in, out);

        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    public void run(InputReader in, PrintWriter out) throws Exception {
        // Read dimensions
        if (!in.hasNext()) return;
        rows = in.nextInt();
        cols = in.nextInt();

        // Initialize grid and memoization table
        // Grid dimensions: (rows + 1) x (cols + 1) to accommodate 1-based indexing
        grid = new int[rows + 1][cols + 1];

        // Memo dimensions: [x][y][lastDirection][currentTurns]
        // Directions are 0-3. We use size 5 to accommodate a dummy initial direction (4).
        // Turns can go up to 4 before being rejected (checked by > 3). Size 5 covers 0-4.
        memo = new int[rows + 1][cols + 1][5][5];

        // Initialize memo table with -1 (unvisited)
        for (int i = 0; i <= rows; i++) {
            for (int j = 0; j <= cols; j++) {
                for (int k = 0; k < 5; k++) {
                    Arrays.fill(memo[i][j][k], -1);
                }
            }
        }

        // Read the grid
        for (int i = 1; i <= rows; i++) {
            String line = in.next();
            for (int j = 1; j <= cols; j++) {
                char c = line.charAt(j - 1);
                if (c == 'S') {
                    startX = i;
                    startY = j;
                } else if (c == 'T') {
                    targetX = i;
                    targetY = j;
                } else if (c == '*') {
                    continue; // Wall, remains 0
                }
                // Mark walkable cells (S, T, and empty spaces) as 1
                grid[i][j] = 1;
            }
        }

        // Solve the problem
        // Initial direction 4 is a dummy value since we haven't moved yet.
        // Current turns start at 0.
        int result = solve(startX, startY, 4, 0);

        if (result <= MAX_TURNS_ALLOWED) {
            out.println("YES");
        } else {
            out.println("NO");
        }
    }

    /**
     * Checks if the given coordinates are within bounds and walkable.
     */
    private boolean isValid(int x, int y) {
        return x >= 1 && x <= rows && y >= 1 && y <= cols && grid[x][y] == 1;
    }

    /**
     * Recursive DFS with memoization to find the minimum turns.
     * 
     * @param x Current x coordinate
     * @param y Current y coordinate
     * @param lastDir Direction index (0-3) of the previous move. 4 is dummy.
     * @param currentTurns Number of turns made so far
     * @return Minimum turns to reach target, or INF if impossible/too many turns
     */
    private int solve(int x, int y, int lastDir, int currentTurns) {
        // Pruning: If turns exceed limit, this path is invalid
        if (currentTurns > MAX_TURNS_ALLOWED) {
            return INF;
        }

        // Base Case: Reached target
        if (x == targetX && y == targetY) {
            return currentTurns;
        }

        // Memoization check
        if (memo[x][y][lastDir][currentTurns] != -1) {
            return memo[x][y][lastDir][currentTurns];
        }

        int minTurns = INF;

        // Explore all 4 directions
        for (int dir = 0; dir < 4; dir++) {
            int nextX = x + DIRECTIONS[dir][0];
            int nextY = y + DIRECTIONS[dir][1];

            if (isValid(nextX, nextY)) {
                // If moving in the same direction, turns don't increase.
                // Otherwise, increment turns.
                int newTurns = (dir == lastDir) ? currentTurns : currentTurns + 1;

                int result = solve(nextX, nextY, dir, newTurns);
                if (result < minTurns) {
                    minTurns = result;
                }
            }
        }

        // Store result in memo table
        return memo[x][y][lastDir][currentTurns] = minTurns;
    }

    /**
     * Fast Input Reader for competitive programming.
     */
    static class InputReader {
        public BufferedReader reader;
        public StringTokenizer tokenizer;

        public InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public boolean hasNext() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return false;
                    if (line.trim().isEmpty()) continue;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return true;
        }

        public int nextInt() {
            String s = next();
            if (s == null) throw new RuntimeException("End of input");
            return Integer.parseInt(s);
        }

        public long nextLong() {
            String s = next();
            if (s == null) throw new RuntimeException("End of input");
            return Long.parseLong(s);
        }
    }
}

import java.util.*;

public class Main {
    // Direction vectors: Right(0), Down(1), Left(2), Up(3)
    // Corresponds to (dx, dy)
    private static final int[] DX = {0, 1, 0, -1};
    private static final int[] DY = {1, 0, -1, 0};

    // Grid and tracking arrays
    private static boolean[][] grid;
    private static int[][] minTurns;
    private static int rows, cols;

    // Helper class to represent state in BFS queue
    // Encapsulates position, current direction, and turn count
    private static class State {
        int x, y, dir, turns;

        State(int x, int y, int dir, int turns) {
            this.x = x;
            this.y = y;
            this.dir = dir;
            this.turns = turns;
        }
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        // Read dimensions
        if (!scanner.hasNextInt()) return;
        rows = scanner.nextInt();
        cols = scanner.nextInt();

        // Initialize grid and tracking arrays
        grid = new boolean[rows][cols];
        minTurns = new int[rows][cols];
        for (int[] row : minTurns) {
            Arrays.fill(row, Integer.MAX_VALUE);
        }

        int startX = 0, startY = 0, endX = 0, endY = 0;

        // Read grid data
        for (int i = 0; i < rows; i++) {
            String rowStr = scanner.next();
            for (int j = 0; j < cols; j++) {
                char c = rowStr.charAt(j);
                if (c == 'S') {
                    startX = i;
                    startY = j;
                    grid[i][j] = true;
                } else if (c == 'T') {
                    endX = i;
                    endY = j;
                    grid[i][j] = true;
                } else if (c == '.') {
                    grid[i][j] = true;
                } else {
                    grid[i][j] = false; // Obstacle
                }
            }
        }

        // Run BFS
        bfs(startX, startY, endX, endY);

        scanner.close();
    }

    private static void bfs(int sx, int sy, int ex, int ey) {
        // Use ArrayDeque for better performance than LinkedList
        Queue<State> queue = new ArrayDeque<>();

        // Initialize start position
        // We can reach the start position with 0 turns in any direction
        minTurns[sx][sy] = 0;
        for (int d = 0; d < 4; d++) {
            queue.add(new State(sx, sy, d, 0));
        }

        while (!queue.isEmpty()) {
            State current = queue.poll();

            // Check if we reached the target
            if (current.x == ex && current.y == ey) {
                System.out.println("YES");
                return;
            }

            // 1. Try moving straight (continue in current direction)
            int nx = current.x + DX[current.dir];
            int ny = current.y + DY[current.dir];

            if (isValid(nx, ny, current.turns)) {
                minTurns[nx][ny] = current.turns;
                queue.add(new State(nx, ny, current.dir, current.turns));
            }

            // 2. Try turning (only allowed if current turns < 2)
            // This logic preserves the specific constraint from the original code
            if (current.turns < 2) {
                // Turn Right (Clockwise)
                int newDir = (current.dir + 1) % 4;
                nx = current.x + DX[newDir];
                ny = current.y + DY[newDir];

                if (isValid(nx, ny, current.turns + 1)) {
                    minTurns[nx][ny] = current.turns + 1;
                    queue.add(new State(nx, ny, newDir, current.turns + 1));
                }

                // Turn Left (Counter-Clockwise)
                newDir = (current.dir - 1 + 4) % 4;
                nx = current.x + DX[newDir];
                ny = current.y + DY[newDir];

                if (isValid(nx, ny, current.turns + 1)) {
                    minTurns[nx][ny] = current.turns + 1;
                    queue.add(new State(nx, ny, newDir, current.turns + 1));
                }
            }
        }

        System.out.println("NO");
    }

    // Helper method to check if a move is valid
    // Returns true if the cell is within bounds, walkable, and we found a path 
    // with fewer or equal turns than previously recorded.
    private static boolean isValid(int x, int y, int turns) {
        // Bounds check
        if (x < 0 || x >= rows || y < 0 || y >= cols) {
            return false;
        }

        // Walkable check
        if (!grid[x][y]) {
            return false;
        }

        // Optimization: Only proceed if this path has fewer or equal turns 
        // than the best path found so far to this cell.
        // Original logic: used[x][y] >= count
        if (minTurns[x][y] >= turns) {
            return true;
        }

        return false;
    }
}

import java.io.IOException;
import java.io.InputStream;
import java.io.OutputStream;
import java.io.PrintWriter;
import java.util.InputMismatchException;

public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        TaskB solver = new TaskB();
        solver.solve(1, in, out);
        out.close();
    }

    /**
     * Solver for TaskB. Handles grid pathfinding with turn constraints.
     */
    static class TaskB {
        private static final int NUM_DIRECTIONS = 4;
        private static final int MAX_TURNS = 2;

        // Direction vectors: Right, Down, Left, Up
        private static final int[] DX = {0, 1, 0, -1};
        private static final int[] DY = {1, 0, -1, 0};

        /**
         * Solves the problem for a single test case.
         */
        public void solve(int testNumber, InputReader in, PrintWriter out) {
            int n = in.nextInt();
            int m = in.nextInt();
            char[][] grid = new char[n][m];
            int startRow = -1;
            int startCol = -1;

            // Parse grid and locate start position
            outerLoop:
            for (int i = 0; i < n; i++) {
                String rowStr = in.next();
                grid[i] = rowStr.toCharArray();
                for (int j = 0; j < m; j++) {
                    if (grid[i][j] == 'S') {
                        startRow = i;
                        startCol = j;
                        break outerLoop;
                    }
                }
            }

            // DP state: [row][col][direction][turnsRemaining]
            boolean[][][][] dp = new boolean[n][m][NUM_DIRECTIONS][MAX_TURNS + 1];
            boolean[][][][] visited = new boolean[n][m][NUM_DIRECTIONS][MAX_TURNS + 1];

            boolean possible = false;
            for (int dir = 0; dir < NUM_DIRECTIONS; dir++) {
                if (canReachTarget(startRow, startCol, grid, dir, MAX_TURNS, dp, visited)) {
                    possible = true;
                    break;
                }
            }

            out.println(possible ? "YES" : "NO");
        }

        /**
         * Recursively checks if the target 'T' is reachable from (r, c) 
         * given current direction and remaining allowed turns.
         */
        private boolean canReachTarget(int r, int c, char[][] grid, int currentDir, 
                                       int turnsRemaining, boolean[][][][] dp, 
                                       boolean[][][][] visited) {
            // Boundary check
            if (r < 0 || r >= grid.length || c < 0 || c >= grid[0].length) {
                return false;
            }
            // Obstacle check
            if (grid[r][c] == '*') {
                return false;
            }
            // Turn limit exceeded
            if (turnsRemaining < 0) {
                return false;
            }
            // Target reached
            if (grid[r][c] == 'T') {
                return true;
            }
            // Memoization hit
            if (visited[r][c][currentDir][turnsRemaining]) {
                return dp[r][c][currentDir][turnsRemaining];
            }

            boolean reachable = false;
            for (int i = 0; i < NUM_DIRECTIONS; i++) {
                int nr = r + DX[i];
                int nc = c + DY[i];

                if (nr >= 0 && nr < grid.length && nc >= 0 && nc < grid[0].length) {
                    if (i == currentDir) {
                        // Moving straight: turns remaining unchanged
                        reachable |= canReachTarget(nr, nc, grid, currentDir, turnsRemaining, dp, visited);
                    } else {
                        // Turning: decrement remaining turns
                        reachable |= canReachTarget(nr, nc, grid, i, turnsRemaining - 1, dp, visited);
                    }
                }
                if (reachable) {
                    break;
                }
            }

            visited[r][c][currentDir][turnsRemaining] = true;
            dp[r][c][currentDir][turnsRemaining] = reachable;
            return reachable;
        }
    }

    /**
     * Fast input reader for competitive programming environments.
     */
    static class InputReader {
        private final InputStream stream;
        private final byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        public int read() {
            if (numChars == -1) {
                throw new InputMismatchException();
            }
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0) {
                    return -1;
                }
            }
            return buf[curChar++];
        }

        public int readInt() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                res *= 10;
                res += c - '0';
                c = read();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public String readString() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            StringBuilder res = new StringBuilder();
            do {
                res.appendCodePoint(c);
                c = read();
            } while (!isSpaceChar(c));
            return res.toString();
        }

        private boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        public int nextInt() {
            return readInt();
        }

        public String next() {
            return readString();
        }
    }
}

import java.io.*;
