public class R793B2 {
    // Constants for clarity and easy modification
    private static final int MAX_TURNS = 2;
    private static final int[] DX = {1, 0, -1, 0}; // Right, Down, Left, Up
    private static final int[] DY = {0, 1, 0, -1};

    private FastScanner in;
    private PrintWriter out;
    private int rows, cols;
    private char[][] grid;
    private int[][] minTurns;

    public static void main(String[] args) {
        new R793B2().run();
    }

    public void run() {
        in = new FastScanner(System.in);
        out = new PrintWriter(System.out);
        try {
            solve();
        } finally {
            out.flush();
            out.close();
        }
    }

    private void solve() {
        rows = in.nextInt();
        cols = in.nextInt();

        grid = new char[rows][cols];
        minTurns = new int[rows][cols];
        int startX = -1, startY = -1;

        // Read grid and locate the starting position
        for (int i = 0; i < rows; i++) {
            String line = in.next();
            for (int j = 0; j < cols; j++) {
                grid[i][j] = line.charAt(j);
                minTurns[i][j] = Integer.MAX_VALUE;
                if (grid[i][j] == 'S') {
                    startX = j;
                    startY = i;
                }
            }
        }

        // BFS initialization
        Queue<State> queue = new ArrayDeque<>();
        queue.add(new State(startX, startY, 0, -1));
        minTurns[startY][startX] = 0;

        boolean found = false;
        while (!queue.isEmpty()) {
            State current = queue.poll();

            // Check if target reached
            if (grid[current.y][current.x] == 'T') {
                found = true;
                break;
            }

            // Explore all 4 directions
            for (int d = 0; d < 4; d++) {
                int nx = current.x + DX[d];
                int ny = current.y + DY[d];

                // Boundary and obstacle checks
                if (nx >= 0 && nx < cols && ny >= 0 && ny < rows && grid[ny][nx] != '*') {
                    // Calculate turns: 0 if starting or continuing same direction, else +1
                    int newTurns = (current.dir == -1 || current.dir == d) ? current.turns : current.turns + 1;

                    // Only proceed if within turn limit and we found a strictly better path
                    if (newTurns <= MAX_TURNS && newTurns < minTurns[ny][nx]) {
                        minTurns[ny][nx] = newTurns;
                        queue.add(new State(nx, ny, newTurns, d));
                    }
                }
            }
        }

        out.println(found ? "YES" : "NO");
    }

    /** Represents a state in the BFS traversal */
    private static class State {
        final int x, y, turns, dir;

        State(int x, int y, int turns, int dir) {
            this.x = x;
            this.y = y;
            this.turns = turns;
            this.dir = dir;
        }
    }

    /** High-performance input reader for competitive programming */
    private static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
