        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            String s = next();
            return s == null ? 0 : Integer.parseInt(s);
        }
    }
}

import java.io.*;
import java.util.*;

public class Main {
    // Constants for grid traversal logic
    private static final int MAX_TURNS = 2;
    private static final int DIRECTIONS = 4;
    private static final int STATE_MULTIPLIER = DIRECTIONS * (MAX_TURNS + 1); // 4 * 3 = 12

    // Direction vectors: 0: Right, 1: Left, 2: Up, 3: Down
    private static final int[] DR = {0, 0, -1, 1};
    private static final int[] DC = {1, -1, 0, 0};

    public static void main(String[] args) {
        FastScanner sc = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out));

        try {
            solve(sc, out);
        } catch (Exception e) {
            e.printStackTrace();
        } finally {
            out.flush();
        }
    }

    private static void solve(FastScanner sc, PrintWriter out) throws IOException {
        String nStr = sc.next();
        if (nStr == null) return; // Graceful EOF handling
        int n = Integer.parseInt(nStr);
        int m = sc.nextInt();

        boolean[][] grid = new boolean[n][m];
        int startR = -1, startC = -1, targetR = -1, targetC = -1;

        for (int i = 0; i < n; i++) {
            String row = sc.next();
            for (int j = 0; j < m; j++) {
                char ch = row.charAt(j);
                if (ch == 'S') {
                    startR = i;
                    startC = j;
                } else if (ch == 'T') {
                    targetR = i;
                    targetC = j;
                }
                grid[i][j] = (ch != '*');
            }
        }

        // BFS initialization
        int maxQueueSize = n * m * STATE_MULTIPLIER;
        int[] queue = new int[maxQueueSize];
        boolean[] visited = new boolean[maxQueueSize];
        int head = 0, tail = 0;

        // Enqueue start position with all possible initial directions (0 turns)
        for (int d = 0; d < DIRECTIONS; d++) {
            queue[tail++] = packState(startR, startC, d, 0, m);
        }

        boolean found = false;

        while (head < tail) {
            int state = queue[head++];

            // Unpack state
            int pos = state / STATE_MULTIPLIER;
            int r = pos / m;
            int c = pos % m;
            int dir = (state % STATE_MULTIPLIER) / (MAX_TURNS + 1);
            int turns = state % (MAX_TURNS + 1);

            if (r == targetR && c == targetC) {
                found = true;
                break;
            }

            for (int d = 0; d < DIRECTIONS; d++) {
                int nr = r + DR[d];
                int nc = c + DC[d];
                int nt = turns + (d != dir ? 1 : 0);

                if (nr >= 0 && nr < n && nc >= 0 && nc < m && grid[nr][nc] && nt <= MAX_TURNS) {
                    int nextState = packState(nr, nc, d, nt, m);
                    if (!visited[nextState]) {
                        visited[nextState] = true;
                        queue[tail++] = nextState;
                    }
                }
            }
        }

        out.println(found ? "YES" : "NO");
    }

    /**
     * Encodes the BFS state into a single integer for efficient array indexing.
     * Format: (row * m + col) * 12 + direction * 3 + turns
     */
    private static int packState(int r, int c, int dir, int turns, int m) {
        return ((r * m + c) * STATE_MULTIPLIER) + (dir * (MAX_TURNS + 1)) + turns;
    }

    /**
     * Fast scanner for competitive programming style input parsing.
     * Handles whitespace skipping and EOF gracefully.
     */
    private static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        public String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input", e);
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            String s = next();
            return s == null ? 0 : Integer.parseInt(s);
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Solves a grid pathfinding problem where movement is restricted to straight
 * horizontal or vertical lines without obstacles.
 */
public class GridPathSolver {

    // Direction vectors for down, up, right, left
    private static final int[] DX = {1, -1, 0, 0};
    private static final int[] DY = {0, 0, 1, -1};

    private BufferedReader reader;
    private PrintWriter writer;
    private StringTokenizer tokenizer;

    // Prefix sum arrays for O(1) obstacle counting
    private int[][] rowPrefixSums;
    private int[][] colPrefixSums;

    public static void main(String[] args) {
        new GridPathSolver().run();
    }

    /**
     * Entry point with safe I/O resource management.
     */
    private void run() {
        try (BufferedReader localReader = new BufferedReader(new InputStreamReader(System.in));
             PrintWriter localWriter = new PrintWriter(new OutputStreamWriter(System.out))) {

            Locale.setDefault(Locale.US);
            this.reader = localReader;
            this.writer = localWriter;
            tokenizer = new StringTokenizer("");

            solve();
        } catch (IOException e) {
            e.printStackTrace();
            System.exit(1);
        }
    }

    /**
     * Orchestrates reading input, building data structures, and solving the problem.
     */
    private void solve() throws IOException {
        int n = nextInt();
        int m = nextInt();

        int[][] grid = new int[n][m];
        int[] start = new int[2];
        int[] target = new int[2];

        // Parse grid and locate start/target positions
        for (int i = 0; i < n; i++) {
            String line = next();
            for (int j = 0; j < m; j++) {
                char c = line.charAt(j);
                if (c == '*') {
                    grid[i][j] = 1; // Mark obstacle
                } else if (c == 'S') {
                    start[0] = i;
                    start[1] = j;
                } else if (c == 'T') {
                    target[0] = i;
                    target[1] = j;
                }
            }
        }

        computePrefixSums(n, m, grid);
        findPath(n, m, start, target);
    }

    /**
     * Computes 2D prefix sums for rows and columns to enable O(1) obstacle checks.
     */
    private void computePrefixSums(int n, int m, int[][] grid) {
        rowPrefixSums = new int[n][m];
        colPrefixSums = new int[m][n];

        // Row prefix sums
        for (int i = 0; i < n; i++) {
            rowPrefixSums[i][0] = grid[i][0];
            for (int j = 1; j < m; j++) {
                rowPrefixSums[i][j] = rowPrefixSums[i][j - 1] + grid[i][j];
            }
        }

        // Column prefix sums
        for (int j = 0; j < m; j++) {
            colPrefixSums[j][0] = grid[0][j];
            for (int i = 1; i < n; i++) {
                colPrefixSums[j][i] = colPrefixSums[j][i - 1] + grid[i][j];
            }
        }
    }

    /**
     * Searches for a valid path from start to target using straight line segments.
     */
    private void findPath(int n, int m, int[] start, int[] target) {
        int startX = start[0], startY = start[1];
        int targetX = target[0], targetY = target[1];
        int maxDist = Math.max(n, m);

        // Check all reachable points from start
        for (int dirS = 0; dirS < 4; dirS++) {
            for (int distS = 0; distS < maxDist; distS++) {
                int endX = startX + DX[dirS] * distS;
                int endY = startY + DY[dirS] * distS;

                if (!isValid(endX, endY, n, m)) continue;
                if (!canConnectStraightLine(startX, startY, endX, endY)) continue;

                // Check all reachable points from target
                for (int dirT = 0; dirT < 4; dirT++) {
                    for (int distT = 0; distT < maxDist; distT++) {
                        int meetX = targetX + DX[dirT] * distT;
                        int meetY = targetY + DY[dirT] * distT;

                        if (!isValid(meetX, meetY, n, m)) continue;
                        if (!canConnectStraightLine(targetX, targetY, meetX, meetY)) continue;
                        if (!canConnectStraightLine(endX, endY, meetX, meetY)) continue;

                        // Valid path found
                        writer.println("YES");
                        return;
                    }
                }
            }
        }

        writer.println("NO");
    }

    /**
     * Checks if coordinates are within grid boundaries.
     */
    private boolean isValid(int r, int c, int n, int m) {
        return r >= 0 && r < n && c >= 0 && c < m;
    }

    /**
     * Determines if two points can be connected by a straight horizontal or vertical line
     * without passing through any obstacles.
     */
    private boolean canConnectStraightLine(int r1, int c1, int r2, int c2) {
        int minR = Math.min(r1, r2);
        int maxR = Math.max(r1, r2);
        int minC = Math.min(c1, c2);
        int maxC = Math.max(c1, c2);

        if (minR == maxR) { // Horizontal line
            int sum = rowPrefixSums[minR][maxC];
            int prev = minC > 0 ? rowPrefixSums[minR][minC - 1] : 0;
            return sum == prev; // Sum difference is 0 => no obstacles
        } else if (minC == maxC) { // Vertical line
            int sum = colPrefixSums[minC][maxR];
            int prev = minR > 0 ? colPrefixSums[minC][minR - 1] : 0;
            return sum == prev; // Sum difference is 0 => no obstacles
        }
        return false; // Not a straight line
    }

    /**
     * Reads the next token from input.
     */
    private String next() throws IOException {
        while (tokenizer == null || !tokenizer.hasMoreTokens()) {
            String line = reader.readLine();
            if (line == null) throw new EOFException("Unexpected end of input");
            tokenizer = new StringTokenizer(line);
        }
        return tokenizer.nextToken();
    }

    /**
     * Parses the next integer token.
     */
    private int nextInt() throws IOException {
        return Integer.parseInt(next());
    }
}

import java.io.*;
import java.util.ArrayDeque;
import java.util.Deque;
import java.util.InputMismatchException;

public class Main {
    public static void main(String[] args) {
        InputReader in = new InputReader(System.in);
        OutputWriter out = new OutputWriter(System.out);
        GridPathSolver solver = new GridPathSolver();
        solver.solve(in, out);
        out.close();
    }

    /**
     * Solves the grid pathfinding problem using 0-1 BFS.
     * Determines if a path exists from 'S' to 'T' with at most 1 turn.
     */
    static class GridPathSolver {
        private static final int[] DR = {-1, 0, 1, 0};
        private static final int[] DC = {0, 1, 0, -1};
        private static final char START = 'S';
        private static final char END = 'T';
        private static final char WALL = '*';
        private static final int MAX_TURNS = 1;

        public void solve(InputReader in, OutputWriter out) {
            int rows = in.readInt();
            int cols = in.readInt();
            char[][] grid = new char[rows][cols];
            Point start = null;
            Point end = null;

            // 1. Parse grid and locate start/end points
            for (int r = 0; r < rows; r++) {
                String line = in.next();
                grid[r] = line.toCharArray();
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] == START) start = new Point(r, c);
                    if (grid[r][c] == END) end = new Point(r, c);
                }
            }

            // 2. Compute result and output
            boolean canReach = (start != null && end != null) && hasPath(grid, start, end, rows, cols);
            out.printLine(canReach ? "YES" : "NO");
        }

        /**
         * Uses 0-1 BFS to determine if the destination is reachable within MAX_TURNS.
         * Moving in the same direction costs 0 turns, changing direction costs 1 turn.
         */
        private boolean hasPath(char[][] grid, Point start, Point end, int rows, int cols) {
            // Initialize deque with all 4 directions at the start position
            Deque<State> deque = new ArrayDeque<>();
            for (int dir = 0; dir < 4; dir++) {
                deque.addLast(new State(start.row, start.col, dir, 0));
            }

            boolean[][][] visited = new boolean[rows][cols][4];

            while (!deque.isEmpty()) {
                State current = deque.pollFirst();

                // Check if destination reached
                if (current.row == end.row && current.col == end.col) {
                    return true;
                }

                // Skip if already processed with this direction
                if (visited[current.row][current.col][current.dir]) continue;
                visited[current.row][current.col][current.dir] = true;

                // Explore all 4 directions
                for (int dir = 0; dir < 4; dir++) {
                    int nr = current.row + DR[dir];
                    int nc = current.col + DC[dir];

                    if (isValid(nr, nc, rows, cols) && grid[nr][nc] != WALL) {
                        int newTurns = (dir == current.dir) ? current.turns : current.turns + 1;
                        if (newTurns <= MAX_TURNS) {
                            // Same direction: cost 0 -> add to front
                            // Different direction: cost 1 -> add to back
                            if (dir == current.dir) {
                                deque.addFirst(new State(nr, nc, dir, newTurns));
                            } else {
                                deque.addLast(new State(nr, nc, dir, newTurns));
                            }
                        }
                    }
                }
            }
            return false;
        }

        private boolean isValid(int r, int c, int rows, int cols) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }

        /** Immutable representation of a grid coordinate. */
        static final class Point {
            final int row, col;
            Point(int row, int col) { this.row = row; this.col = col; }
        }

        /** BFS state tracking position, direction, and accumulated turns. */
        static final class State {
            final int row, col, dir, turns;
            State(int row, int col, int dir, int turns) {
                this.row = row; this.col = col; this.dir = dir; this.turns = turns;
            }
        }
    }

    /** Fast input reader optimized for competitive programming. */
    static class InputReader {
        private final InputStream stream;
        private final byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        public int read() {
            if (numChars == -1) {
                throw new InputMismatchException("End of input");
            }
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException("I/O error");
                }
                if (numChars <= 0) {
                    return -1;
                }
            }
            return buf[curChar++];
        }

        public int readInt() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
                if (c == -1) throw new InputMismatchException("Unexpected end of input");
            }
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9') {
                    throw new InputMismatchException("Invalid integer");
                }
                res *= 10;
                res += c - '0';
                c = read();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public String next() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
                if (c == -1) throw new InputMismatchException("Unexpected end of input");
            }
            StringBuilder res = new StringBuilder();
            do {
                res.append((char) c);
                c = read();
            } while (!isSpaceChar(c));
            return res.toString();
        }

        private static boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t';
        }
    }

    /** Fast output writer with buffering and auto-flush. */
    static class OutputWriter {
        private final PrintWriter writer;

        public OutputWriter(OutputStream outputStream) {
            this.writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(outputStream)), true);
        }

        public void print(Object... objects) {
            for (int i = 0; i < objects.length; i++) {
                if (i > 0) writer.print(' ');
                writer.print(objects[i]);
            }
        }

        public void printLine(Object... objects) {
            print(objects);
            writer.println();
        }

        public void close() {
            writer.close();
        }
    }
}

import java.io.*;
import java.util.*;

public class Codechef {

    /**
     * Efficient input scanner for competitive programming.
     */
    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        String next() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) return null;
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

        int nextInt() throws IOException {
            String s = next();
            if (s == null) throw new IOException("Unexpected end of input");
            return Integer.parseInt(s);
        }
    }

    // Grid dimensions
    private static int rows, cols;
    // 0 = empty path, 1 = obstacle
    private static int[][] grid;
    // Start and target coordinates
    private static int startR, startC, targetR, targetC;
    // Flag to signal successful path discovery
    private static boolean pathFound = false;
    // Visited state: [row][col][turns_count]
    private static boolean[][][] visited;

    // Direction vectors: 0=Right, 1=Down, 2=Left, 3=Up
    private static final int[] DR = {0, 1, 0, -1};
    private static final int[] DC = {1, 0, -1, 0};

    public static void main(String[] args) throws IOException {
        FastScanner sc = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            rows = sc.nextInt();
            cols = sc.nextInt();
            grid = new int[rows][cols];

            // Parse the grid
            for (int i = 0; i < rows; i++) {
                String rowStr = sc.next();
                for (int j = 0; j < cols; j++) {
                    char c = rowStr.charAt(j);
                    if (c == '*') {
                        grid[i][j] = 1;
                    } else if (c == 'S') {
                        startR = i;
                        startC = j;
                    } else if (c == 'T') {
                        targetR = i;
                        targetC = j;
                    }
                }
            }

            // Try starting DFS in each of the 4 cardinal directions
            for (int initDir = 0; initDir < 4; initDir++) {
                // Fresh visited array for each initial direction attempt
                visited = new boolean[rows][cols][3];
                dfs(startR, startC, 0, initDir);
                if (pathFound) break;
            }

            out.println(pathFound ? "YES" : "NO");
        } finally {
            out.flush();
            out.close();
        }
    }

    /**
     * Depth-First Search to find a path from (r, c) to the target with at most 2 turns.
     *
     * @param r     Current row
     * @param c     Current column
     * @param turns Number of turns made so far
     * @param dir   Direction we are currently moving in (0-3)
     */
    private static void dfs(int r, int c, int turns, int dir) {
        // Early exit if path already found or turns limit exceeded
        if (pathFound || turns > 2) return;

        // Check if we reached the target
        if (r == targetR && c == targetC) {
            pathFound = true;
            return;
        }

        // Skip if already visited with the same number of turns
        if (visited[r][c][turns]) return;
        visited[r][c][turns] = true;

        // Explore all 4 directions
        for (int nextDir = 0; nextDir < 4; nextDir++) {
            int nr = r + DR[nextDir];
            int nc = c + DC[nextDir];

            // Check bounds and obstacle
            if (nr >= 0 && nr < rows && nc >= 0 && nc < cols && grid[nr][nc] == 0) {
                // Calculate new turns: +1 if direction changes, otherwise same
                int newTurns = (nextDir != dir) ? turns + 1 : turns;
                if (newTurns <= 2) {
                    dfs(nr, nc, newTurns, nextDir);
                    if (pathFound) return; // Short-circuit recursion on success
                }
            }
        }
    }
}

import java.util.Scanner;

public class Main {
    // Maximum allowed turns to reach the target. 
    // Adjust this constant based on specific problem constraints (original logic allowed up to 2).
    private static final int MAX_TURNS = 3;

    // Direction vectors: 0=Left, 1=Up, 2=Right, 3=Down
    // Maintains original mapping for behavioral consistency
    private static final int[][] DIRS = {
        {0, -1},
        {-1, 0},
        {0, 1},
        {1, 0}
    };

    private boolean found;
    private char[][] maze;
    private boolean[][] visited;
    private int rows, cols;
    private int targetR, targetC;

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        while (sc.hasNextInt()) {
            int n = sc.nextInt();
            int m = sc.nextInt();

            // Instantiate a fresh solver per test case to eliminate static state leakage
            Main solver = new Main();
            solver.rows = n;
            solver.cols = m;
            solver.maze = new char[n][m];
            solver.visited = new boolean[n][m];
            solver.found = false;

            for (int i = 0; i < n; i++) {
                String line = sc.next();
                for (int j = 0; j < m; j++) {
                    solver.maze[i][j] = line.charAt(j);
                    if (solver.maze[i][j] == 'S') {
                        solver.dfs(i, j, -1, 0);
                    } else if (solver.maze[i][j] == 'T') {
                        solver.targetR = i;
                        solver.targetC = j;
                    }
                }
            }

            System.out.println(solver.found ? "YES" : "NO");
        }
        sc.close();
    }

    /**
     * Depth-First Search to find a valid path from the start to the target
     * with a limited number of direction changes.
     *
     * @param r       Current row
     * @param c       Current column
     * @param prevDir Direction index of the previous move (-1 for the starting cell)
     * @param turns   Number of turns made so far
     */
    private void dfs(int r, int c, int prevDir, int turns) {
        // Early exit: found path, out of bounds, obstacle, or already visited
        if (found || r < 0 || r >= rows || c < 0 || c >= cols) return;
        if (maze[r][c] == '*' || visited[r][c]) return;
        if (turns > MAX_TURNS) return;

        // Pruning: If we've used all allowed turns, we must be moving straight toward the target
        if (turns == MAX_TURNS) {
            boolean aligned;
            if (prevDir == 0 || prevDir == 2) { // Horizontal movement
                aligned = (r == targetR);
            } else { // Vertical movement
                aligned = (c == targetC);
            }
            if (!aligned) return;
        }

        visited[r][c] = true;

        // Check if target reached
        if (maze[r][c] == 'T') {
            found = true;
            return;
        }

        // Explore all four directions
        for (int nextDir = 0; nextDir < 4; nextDir++) {
            int nr = r + DIRS[nextDir][0];
            int nc = c + DIRS[nextDir][1];

            // Increment turn count only when direction changes from previous move
            int newTurns = (prevDir != -1 && prevDir != nextDir) ? turns + 1 : turns;

            dfs(nr, nc, nextDir, newTurns);
            if (found) return;
        }

        // Backtrack: unmark current cell to allow other paths to use it
        visited[r][c] = false;
    }
}

import java.util.Scanner;

/**
 * A solver to determine if a player can win a game of Gomoku (Five in a Row)
 * in a single move on a 10x10 board.
 * 
 * Refactoring improvements:
 * 1. Removed Magic Numbers: Board size and win length are defined as constants.
 * 2. Improved Readability: Extracted logic into helper methods (hasAdjacentX, checkWin).
 * 3. Optimized Logic: 
 *    - Replaced verbose boundary checks in 'isAlone' with a simple offset loop.
 *    - Replaced the O(N^4) board scan for winning moves with an O(1) check centered on the new move.
 * 4. Resource Management: Used try-with-resources for the Scanner.
 * 5. Naming: Used descriptive variable and method names.
 */
public class GomokuSolver {

    private static final int BOARD_SIZE = 10;
    private static final int WIN_LENGTH = 5;

    public static void main(String[] args) {
        // Use try-with-resources to ensure Scanner is closed automatically
        try (Scanner scanner = new Scanner(System.in)) {
            char[][] board = new char[BOARD_SIZE][BOARD_SIZE];

            // Read the board configuration
            for (int row = 0; row < BOARD_SIZE; row++) {
                if (scanner.hasNextLine()) {
                    String line = scanner.nextLine();
                    // Ensure we don't go out of bounds if input line is short
                    for (int col = 0; col < BOARD_SIZE && col < line.length(); col++) {
                        board[row][col] = line.charAt(col);
                    }
                }
            }

            boolean canWin = false;

            // Iterate through every cell to find a potential winning move
            for (int row = 0; row < BOARD_SIZE; row++) {
                for (int col = 0; col < BOARD_SIZE; col++) {

                    // Optimization: We only care about empty spots ('.')
                    if (board[row][col] == '.') {

                        // Optimization: If the empty spot is not adjacent to any 'X',
                        // placing an 'X' there cannot form a 5-in-a-row.
                        // This replaces the complex 'isAlone' logic from the original code.
                        if (!hasAdjacentX(board, row, col)) {
                            continue;
                        }

                        // Place the move
                        board[row][col] = 'X';

                        // Check if this move creates a winning line.
                        // We only need to check lines passing through the newly placed 'X'.
                        if (checkWin(board, row, col)) {
                            canWin = true;
                            board[row][col] = '.'; // Backtrack (cleanup)
                            break; // Found a winning move
                        }

                        // Backtrack: Remove the move to try next position
                        board[row][col] = '.';
                    }
                }
                if (canWin) break;
            }

            if (canWin) {
                System.out.println("YES");
            } else {
                System.out.println("NO");
            }
        }
    }

    /**
     * Checks if the cell at (row, col) has any adjacent 'X' neighbors.
     * This is an optimization to skip checking isolated empty cells.
     * Replaces the verbose boundary checks of the original 'isAlone' method.
     */
    private static boolean hasAdjacentX(char[][] board, int row, int col) {
        // Check all 8 neighbors using offset loops
        for (int dr = -1; dr <= 1; dr++) {
            for (int dc = -1; dc <= 1; dc++) {
                if (dr == 0 && dc == 0) continue; // Skip the cell itself

                int neighborRow = row + dr;
                int neighborCol = col + dc;

                // Check bounds
                if (neighborRow >= 0 && neighborRow < BOARD_SIZE &&
                    neighborCol >= 0 && neighborCol < BOARD_SIZE) {

                    if (board[neighborRow][neighborCol] == 'X') {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Checks if placing an 'X' at (row, col) results in 5 consecutive 'X's.
     * Replaces the multiple direction methods (hasFiveInHor, etc.) and the 
     * inefficient nested loop scanning the whole board.
     */
    private static boolean checkWin(char[][] board, int row, int col) {
        // Directions: Horizontal, Vertical, Diagonal (Top-Left to Bottom-Right), Diagonal (Top-Right to Bottom-Left)
        int[][] directions = {
            {0, 1},   // Horizontal
            {1, 0},   // Vertical
            {1, 1},   // Diagonal \
            {1, -1}   // Diagonal /
        };

        for (int[] dir : directions) {
            if (countConsecutive(board, row, col, dir[0], dir[1]) >= WIN_LENGTH) {
                return true;
            }
        }
        return false;
    }

    /**
     * Counts the number of consecutive 'X's in a specific direction starting from (row, col).
     * It checks both forward and backward from the starting point to find the total length of the line.
     */
    private static int countConsecutive(char[][] board, int row, int col, int dRow, int dCol) {
        int count = 0;

        // Check forward direction
        for (int i = 0; i < WIN_LENGTH; i++) {
            int r = row + i * dRow;
            int c = col + i * dCol;

            if (r >= 0 && r < BOARD_SIZE && c >= 0 && c < BOARD_SIZE && board[r][c] == 'X') {
                count++;
            } else {
                break;
            }
        }

        // Check backward direction (starting from i=1 to avoid double counting the center cell)
        for (int i = 1; i < WIN_LENGTH; i++) {
            int r = row - i * dRow;
            int c = col - i * dCol;

            if (r >= 0 && r < BOARD_SIZE && c >= 0 && c < BOARD_SIZE && board[r][c] == 'X') {
                count++;
            } else {
                break;
            }
        }

        return count;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

public class Main {
    // Extracted magic numbers into named constants for clarity and easy configuration
    private static final int GRID_SIZE = 10;
    private static final int CHECK_LENGTH = 5;
    private static final int REQUIRED_X_COUNT = 4;

    // Direction vectors covering all 8 compass directions: N, NE, E, SE, S, SW, W, NW
    private static final int[] DR = {-1, -1, 0, 1, 1, 1, 0, -1};
    private static final int[] DC = {0, 1, 1, 1, 0, -1, -1, -1};

    public static void main(String[] args) {
        FastScanner fs = new FastScanner();
        PrintWriter out = new PrintWriter(System.out);

        char[][] grid = new char[GRID_SIZE][GRID_SIZE];
        for (int i = 0; i < GRID_SIZE; i++) {
            String line = fs.next();
            for (int j = 0; j < GRID_SIZE; j++) {
                grid[i][j] = line.charAt(j);
            }
        }

        boolean patternFound = false;
        outerLoop:
        for (int i = 0; i < GRID_SIZE; i++) {
            for (int j = 0; j < GRID_SIZE; j++) {
                for (int d = 0; d < DR.length; d++) {
                    if (checkDirection(grid, i, j, DR[d], DC[d])) {
                        patternFound = true;
                        break outerLoop; // Early exit: pattern found, no need to check further
                    }
                }
            }
        }

        out.println(patternFound ? "YES" : "NO");
        out.flush();
        out.close();
    }

    /**
     * Checks a specific direction from a starting cell for the required pattern.
     * Returns true if exactly REQUIRED_X_COUNT 'X's are found in CHECK_LENGTH cells,
     * and no 'O' is encountered along the path.
     */
    private static boolean checkDirection(char[][] grid, int row, int col, int dRow, int dCol) {
        int xCount = 0;
        for (int step = 0; step < CHECK_LENGTH; step++) {
            // Boundary validation
            if (row < 0 || col < 0 || row >= GRID_SIZE || col >= GRID_SIZE) {
                return false;
            }

            char cell = grid[row][col];
            if (cell == 'X') {
                xCount++;
            } else if (cell == 'O') {
                return false; // 'O' immediately invalidates the sequence
            }

            row += dRow;
            col += dCol;
        }
        return xCount == REQUIRED_X_COUNT;
    }

    /**
     * Optimized input reader for competitive programming and fast I/O scenarios.
     */
    static class FastScanner {
        private final BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        private StringTokenizer st = new StringTokenizer("");

        String next() {
            while (!st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Input stream failed", e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        long nextLong() {
            return Long.parseLong(next());
        }
