/**
 * Solves the grid-based problem by checking if placing a piece at any empty spot
 * would result in a line of 5 consecutive pieces in any direction.
 */
class Answer {
    private static final int GRID_SIZE = 10;
    private static final int TARGET_ADJACENT = 4; // 4 adjacent pieces allow placing 1 to make 5

    /**
     * Reads the grid and checks for any position where placing an 'X' creates a winning line.
     */
    public void solve(InputReader in, PrintWriter out) {
        String[] grid = new String[GRID_SIZE];
        for (int i = 0; i < GRID_SIZE; i++) {
            grid[i] = in.next();
        }

        for (int i = 0; i < GRID_SIZE; i++) {
            for (int j = 0; j < GRID_SIZE; j++) {
                if (grid[i].charAt(j) == '.') {
                    if (hasThreateningLine(grid, i, j)) {
                        out.println("YES");
                        return;
                    }
                }
            }
        }
        out.println("NO");
    }

    /**
     * Checks all four directions to see if placing a piece at (x, y) completes a line.
     */
    private boolean hasThreateningLine(String[] grid, int x, int y) {
        return countConsecutive(grid, x, y, 0, 1, 'X') >= TARGET_ADJACENT ||
               countConsecutive(grid, x, y, 1, 0, 'X') >= TARGET_ADJACENT ||
               countConsecutive(grid, x, y, 1, 1, 'X') >= TARGET_ADJACENT ||
               countConsecutive(grid, x, y, 1, -1, 'X') >= TARGET_ADJACENT;
    }

    /**
     * Counts consecutive target characters in both directions from (x, y) along (dx, dy).
     */
    private int countConsecutive(String[] grid, int x, int y, int dx, int dy, char target) {
        int count = 0;

        // Check forward direction
        int i = x + dx;
        int j = y + dy;
        while (i >= 0 && i < GRID_SIZE && j >= 0 && j < GRID_SIZE && grid[i].charAt(j) == target) {
            count++;
            i += dx;
            j += dy;
        }

        // Check backward direction
        i = x - dx;
        j = y - dy;
        while (i >= 0 && i < GRID_SIZE && j >= 0 && j < GRID_SIZE && grid[i].charAt(j) == target) {
            count++;
            i -= dx;
            j -= dy;
        }

        return count;
    }
}

/**
 * Fast I/O helper class for competitive programming.
 */
class InputReader {
    private final BufferedReader reader;
    private StringTokenizer tokenizer;

    InputReader(InputStream stream) {
        reader = new BufferedReader(new InputStreamReader(stream), 32768);
        tokenizer = null;
    }

    public String next() {
        while (tokenizer == null || !tokenizer.hasMoreTokens()) {
            try {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            } catch (IOException e) {
                throw new RuntimeException("Error reading input", e);
            }
        }
        return tokenizer.nextToken();
    }

    public int nextInt() {
        return Integer.parseInt(next());
    }

    public long nextLong() {
        return Long.parseLong(next());
    }

    public int[] nextArrayInt(int count) {
        int[] a = new int[count];
        for (int i = 0; i < count; i++) {
            a[i] = nextInt();
        }
        return a;
    }

    public long[] nextArrayLong(int count) {
        long[] a = new long[count];
        for (int i = 0; i < count; i++) {
            a[i] = nextLong();
        }
        return a;
    }
}

import java.util.Scanner;

public class GameBoardChecker {
    private static final int GRID_SIZE = 10;
    private static final int WIN_LENGTH = 5;

    public static void main(String[] args) {
        // Use try-with-resources to automatically close the Scanner
        try (Scanner scanner = new Scanner(System.in)) {
            char[][] board = new char[GRID_SIZE][GRID_SIZE];
            for (int i = 0; i < GRID_SIZE; i++) {
                String line = scanner.next();
                board[i] = line.toCharArray();
            }

            boolean won = false;
            // Directions represented as [rowDelta, colDelta]
            int[][] directions = {
                {0, 1},   // Horizontal
                {1, 0},   // Vertical
                {1, 1},   // Main Diagonal (top-left to bottom-right)
                {1, -1}   // Anti-Diagonal (top-right to bottom-left)
            };

            // Check every cell as a potential starting point for each direction
            for (int r = 0; r < GRID_SIZE; r++) {
                for (int c = 0; c < GRID_SIZE; c++) {
                    for (int[] dir : directions) {
                        if (checkLine(board, r, c, dir[0], dir[1])) {
                            won = true;
                            break;
                        }
                    }
                    if (won) break;
                }
                if (won) break;
            }

            System.out.println(won ? "YES" : "NO");
        }
    }

    /**
     * Checks if a contiguous line of WIN_LENGTH cells starting at (startRow, startCol)
     * in the given direction meets the win condition.
     * 
     * Win Condition: Exactly 4 'X's and 1 '.'. The presence of 'O' breaks the sequence.
     */
    private static boolean checkLine(char[][] board, int startRow, int startCol, int dr, int dc) {
        int xCount = 0;
        int dotCount = 0;

        for (int i = 0; i < WIN_LENGTH; i++) {
            int r = startRow + i * dr;
            int c = startCol + i * dc;

            // Out of bounds means this line is invalid
            if (r < 0 || r >= GRID_SIZE || c < 0 || c >= GRID_SIZE) {
                return false;
            }

            char cell = board[r][c];
            if (cell == 'X') {
                xCount++;
            } else if (cell == '.') {
                dotCount++;
            } else if (cell == 'O') {
                // 'O' acts as a blocker, so this line cannot win
                return false;
            }
        }

        return xCount == 4 && dotCount == 1;
    }
}

import java.io.*;

public class Main {
    // Configuration constants
    private static final int GRID_SIZE = 10;
    private static final int WIN_LENGTH = 5;
    private static final int X_VALUE = 1;
    private static final int O_VALUE = -100; // Kept from original; consider 0 if sum check implies 0
    private static final int TARGET_SUM = 4; // Kept from original
    private static final int NUMBER_OF_TESTS = 1;
    private static final boolean USE_FILE_IO = false;
    private static final String INPUT_FILE = "input.in";
    private static final String OUTPUT_FILE = "output.out";

    // Direction vectors: [rowDelta, colDelta] for horizontal, vertical, and both diagonals
    private static final int[][] DIRECTIONS = {
        {0, 1},  // Horizontal
        {1, 0},  // Vertical
        {1, 1},  // Diagonal (top-left to bottom-right)
        {1, -1}  // Diagonal (top-right to bottom-left)
    };

    public static void main(String[] args) throws IOException {
        // Use try-with-resources to guarantee proper stream closure
        try (BufferedReader br = createReader(USE_FILE_IO, INPUT_FILE);
             PrintWriter pw = createWriter(USE_FILE_IO, OUTPUT_FILE)) {

            for (int test = 1; test <= NUMBER_OF_TESTS; test++) {
                int[][] grid = readGrid(br);
                boolean hasWin = checkForWin(grid);
                pw.print(hasWin ? "YES" : "NO");
            }
            pw.flush();
        }
    }

    /**
     * Creates the appropriate BufferedReader based on I/O mode.
     */
    private static BufferedReader createReader(boolean useFile, String path) throws IOException {
        return useFile ? new BufferedReader(new FileReader(path))
                       : new BufferedReader(new InputStreamReader(System.in));
    }

    /**
     * Creates the appropriate PrintWriter based on I/O mode.
     */
    private static PrintWriter createWriter(boolean useFile, String path) throws IOException {
        return useFile ? new PrintWriter(new FileWriter(path))
                       : new PrintWriter(new BufferedOutputStream(System.out));
    }

    /**
     * Reads and parses the 10x10 grid from the input source.
     */
    private static int[][] readGrid(BufferedReader br) throws IOException {
        int[][] grid = new int[GRID_SIZE][GRID_SIZE];
        String line;
        for (int i = 0; i < GRID_SIZE; i++) {
            line = br.readLine();
            if (line == null) break;
            for (int j = 0; j < GRID_SIZE; j++) {
                char c = line.charAt(j);
                grid[i][j] = (c == 'O') ? O_VALUE : (c == 'X') ? X_VALUE : 0;
            }
        }
        return grid;
    }

    /**
     * Checks if there is a winning sequence of length WIN_LENGTH in the grid.
     * A win is detected when the sum of values along any consecutive sequence
     * matches TARGET_SUM.
     */
    private static boolean checkForWin(int[][] grid) {
        for (int[] dir : DIRECTIONS) {
            int dr = dir[0];
            int dc = dir[1];

            // Iterate over all valid starting positions
            for (int r = 0; r < GRID_SIZE; r++) {
                for (int c = 0; c < GRID_SIZE; c++) {
                    // Calculate the ending position of the sequence
                    int endR = r + dr * (WIN_LENGTH - 1);
                    int endC = c + dc * (WIN_LENGTH - 1);

                    // Skip if the sequence would go out of bounds
                    if (endR < 0 || endR >= GRID_SIZE || endC < 0 || endC >= GRID_SIZE) {
                        continue;
                    }

                    int sum = 0;
                    for (int k = 0; k < WIN_LENGTH; k++) {
                        sum += grid[r + dr * k][c + dc * k];
                    }

                    if (sum == TARGET_SUM) {
                        return true;
                    }
                }
            }
        }
        return false;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;

public class Main {
    // Extracted constants for clarity and easy configuration
    private static final int BOARD_SIZE = 10;
    private static final int WINDOW_SIZE = 5;
    private static final int MAX_EMPTY_CELLS = 1; // Equivalent to original: dotCount < 2

    public static void main(String[] args) throws IOException {
        int[][] board = readBoard();
        System.out.println(hasValidLine(board) ? "YES" : "NO");
    }

    /**
     * Reads the 10x10 board from standard input.
     * Uses 0-based indexing for consistency with Java conventions.
     */
    private static int[][] readBoard() throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int[][] board = new int[BOARD_SIZE][BOARD_SIZE];

        for (int i = 0; i < BOARD_SIZE; i++) {
            String line = br.readLine();
            // Skip potential empty lines or whitespace-only lines
            while (line != null && line.trim().isEmpty()) {
                line = br.readLine();
            }
            if (line == null) break;

            String rowStr = line.trim();
            for (int j = 0; j < BOARD_SIZE; j++) {
                char ch = rowStr.charAt(j);
                if (ch == 'X') {
                    board[i][j] = 1;
                } else if (ch == 'O') {
                    board[i][j] = -1;
                }
                // '.' remains 0 by default (Java array initialization)
            }
        }
        return board;
    }

    /**
     * Checks all possible horizontal, vertical, and diagonal lines
     * for a valid sequence of 5 cells.
     */
    private static boolean hasValidLine(int[][] board) {
        // Directions: Right, Down, Down-Right, Down-Left
        int[][] directions = {{0, 1}, {1, 0}, {1, 1}, {1, -1}};

        for (int[] dir : directions) {
            int dr = dir[0];
            int dc = dir[1];

            // Iterate over every possible starting position
            for (int r = 0; r < BOARD_SIZE; r++) {
                for (int c = 0; c < BOARD_SIZE; c++) {
                    // Calculate the end coordinates of the 5-cell window
                    int endR = r + dr * (WINDOW_SIZE - 1);
                    int endC = c + dc * (WINDOW_SIZE - 1);

                    // Verify the entire window stays within board boundaries
                    if (endR >= 0 && endR < BOARD_SIZE && endC >= 0 && endC < BOARD_SIZE) {
                        if (checkWindow(board, r, c, dr, dc)) {
                            return true;
                        }
                    }
                }
            }
        }
        return false;
    }

    /**
     * Evaluates a single 5-cell window along a given direction.
     * Returns true if the window contains exactly 5 non-'O' cells
     * with at most 1 empty cell ('.').
     */
    private static boolean checkWindow(int[][] board, int startR, int startC, int dr, int dc) {
        int xCount = 0;
        int emptyCount = 0;

        for (int i = 0; i < WINDOW_SIZE; i++) {
            int val = board[startR + i * dr][startC + i * dc];
            if (val == 1) {
                xCount++;
            } else if (val == 0) {
                emptyCount++;
            }
        }

        // Original condition: xCount + dotCount == 5 && dotCount < 2
        return (xCount + emptyCount == WINDOW_SIZE) && (emptyCount <= MAX_EMPTY_CELLS);
    }
}

import java.io.IOException;
import java.io.InputStream;
import java.io.OutputStream;
import java.io.PrintWriter;
import java.util.InputMismatchException;

public class Main {
    private static final int BOARD_SIZE = 10;
    private static final int WIN_LENGTH = 5;

    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        BoardSolver solver = new BoardSolver();
        solver.solve(in, out);
        out.close();
    }

    static class BoardSolver {
        public void solve(InputReader in, PrintWriter out) {
            char[][] board = readBoard(in);

            for (int i = 0; i < BOARD_SIZE; i++) {
                for (int j = 0; j < BOARD_SIZE; j++) {
                    if (board[i][j] == '.') {
                        board[i][j] = 'X';
                        if (hasFiveInARow(board)) {
                            out.print("YES");
                            return;
                        }
                        board[i][j] = '.'; // Backtrack
                    }
                }
            }
            out.print("NO");
        }

        private char[][] readBoard(InputReader in) {
            char[][] board = new char[BOARD_SIZE][BOARD_SIZE];
            for (int i = 0; i < BOARD_SIZE; i++) {
                for (int j = 0; j < BOARD_SIZE; j++) {
                    board[i][j] = in.nextCharacter();
                }
            }
            return board;
        }

        private boolean hasFiveInARow(char[][] board) {
            // Check horizontal lines
            for (int r = 0; r < BOARD_SIZE; r++) {
                for (int c = 0; c <= BOARD_SIZE - WIN_LENGTH; c++) {
                    if (isLine(board, r, c, 0, 1)) return true;
                }
            }
            // Check vertical lines
            for (int c = 0; c < BOARD_SIZE; c++) {
                for (int r = 0; r <= BOARD_SIZE - WIN_LENGTH; r++) {
                    if (isLine(board, r, c, 1, 0)) return true;
                }
            }
            // Check main diagonals (top-left to bottom-right)
            for (int r = 0; r <= BOARD_SIZE - WIN_LENGTH; r++) {
                for (int c = 0; c <= BOARD_SIZE - WIN_LENGTH; c++) {
                    if (isLine(board, r, c, 1, 1)) return true;
                }
            }
            // Check anti-diagonals (top-right to bottom-left)
            for (int r = 0; r <= BOARD_SIZE - WIN_LENGTH; r++) {
                for (int c = WIN_LENGTH - 1; c < BOARD_SIZE; c++) {
                    if (isLine(board, r, c, 1, -1)) return true;
                }
            }
            return false;
        }

        private boolean isLine(char[][] board, int r, int c, int dr, int dc) {
            for (int k = 0; k < WIN_LENGTH; k++) {
                if (board[r + k * dr][c + k * dc] != 'X') {
                    return false;
                }
            }
            return true;
        }
    }

    static class InputReader {
        private InputStream stream;
        private byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;
        private SpaceCharFilter filter;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        public int read() {
            if (numChars == -1) {
                throw new InputMismatchException();
            }
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0) {
                    return -1;
                }
            }
            return buf[curChar++];
        }

        public boolean isSpaceChar(int c) {
            return filter != null ? filter.isSpaceChar(c) : isWhitespace(c);
        }

        public static boolean isWhitespace(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        public char nextCharacter() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            return (char) c;
        }

        public interface SpaceCharFilter {
            boolean isSpaceChar(int ch);
        }
    }
}

