    static class FiveInARow {
        public void solve(FastScanner sc, PrintWriter pw) {
            char[][] grid = new char[GRID_SIZE][GRID_SIZE];
            for (int i = 0; i < GRID_SIZE; i++) {
                grid[i] = sc.next().toCharArray();
            }

            // Try placing 'X' in every empty cell
            for (int i = 0; i < GRID_SIZE; i++) {
                for (int j = 0; j < GRID_SIZE; j++) {
                    if (grid[i][j] == '.') {
                        grid[i][j] = 'X';
                        if (hasFiveInARow(grid, i, j)) {
                            pw.println("YES");
                            return;
                        }
                        grid[i][j] = '.'; // Backtrack to restore grid state
                    }
                }
            }
            pw.println("NO");
        }

        /**
         * Checks if placing an 'X' at (r, c) creates a line of 5 or more consecutive 'X's.
         * Checks all 8 possible directions from the placed cell.
         */
        private boolean hasFiveInARow(char[][] grid, int r, int c) {
            int[][] directions = {
                {0, 1}, {0, -1}, {1, 0}, {-1, 0},   // Horizontal & Vertical
                {1, 1}, {1, -1}, {-1, 1}, {-1, -1}  // Diagonals
            };
            for (int[] dir : directions) {
                if (countConsecutive(grid, r, c, dir[0], dir[1]) >= 5) {
                    return true;
                }
            }
            return false;
        }

        /**
         * Counts consecutive 'X's starting from (r, c) in a given direction (dr, dc).
         */
        private int countConsecutive(char[][] grid, int r, int c, int dr, int dc) {
            int count = 0;
            int i = r, j = c;
            while (i >= 0 && i < GRID_SIZE && j >= 0 && j < GRID_SIZE && grid[i][j] == 'X') {
                count++;
                i += dr;
                j += dc;
            }
            return count;
        }
    }

    /**
     * Fast I/O helper class for competitive programming contexts.
     */
    static class FastScanner {
        private BufferedReader br;
        private StringTokenizer st;

        public FastScanner(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        public String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) {
                        throw new RuntimeException("End of input");
                    }
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }
    }
}

import java.io.IOException;
import java.io.InputStream;
import java.io.OutputStream;
import java.io.PrintWriter;
import java.util.InputMismatchException;

public class Main {

    // Constants for grid dimensions and target pattern length
    private static final int GRID_SIZE = 10;
    private static final int TARGET_LENGTH = 5;

    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;

        FastReader in = new FastReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);

        TaskB solver = new TaskB();
        solver.solve(1, in, out);

        out.close();
    }

    /**
     * TaskB encapsulates the logic for solving the specific problem.
     */
    static class TaskB {
        public void solve(int testNumber, FastReader in, PrintWriter out) {
            // Read the 10x10 character map
            char[][] map = in.nextCharacterMap(GRID_SIZE, GRID_SIZE);

            // Check if the winning pattern exists
            if (hasWinningPattern(map)) {
                out.println("YES");
            } else {
                out.println("NO");
            }
        }

        /**
         * Checks if the map contains a line of length TARGET_LENGTH
         * consisting of exactly 4 'X's and 1 '.'.
         */
        private boolean hasWinningPattern(char[][] map) {
            int n = GRID_SIZE;

            // Directions: 8 neighbors (row_delta, col_delta)
            // Covers horizontal, vertical, and both diagonals
            int[] dr = {-1, -1, -1, 0, 0, 1, 1, 1};
            int[] dc = {-1, 0, 1, -1, 1, -1, 0, 1};

            for (int r = 0; r < n; r++) {
                for (int c = 0; c < n; c++) {
                    for (int dir = 0; dir < 8; dir++) {
                        int crossCount = 0;
                        int dotCount = 0;
                        boolean validLine = true;

                        // Check a sequence of length TARGET_LENGTH starting from (r, c) in direction 'dir'
                        for (int step = 0; step < TARGET_LENGTH; step++) {
                            int nr = r + dr[dir] * step;
                            int nc = c + dc[dir] * step;

                            // Check boundaries
                            if (nr < 0 || nr >= n || nc < 0 || nc >= n) {
                                validLine = false;
                                break;
                            }

                            char cell = map[nr][nc];
                            if (cell == 'X') {
                                crossCount++;
                            } else if (cell == '.') {
                                dotCount++;
                            } else {
                                // Found a character that is not 'X' or '.'
                                validLine = false;
                                break;
                            }
                        }

                        // Check condition: exactly 4 'X's and 1 '.' in a valid line of 5
                        if (validLine && crossCount == 4 && dotCount == 1) {
                            return true;
                        }
                    }
                }
            }
            return false;
        }
    }

    /**
     * FastReader utility class for fast input reading.
     */
    static class FastReader {
        private final InputStream stream;
        private final byte[] buf = new byte[8192];
        private int curChar;
        private int pnumChars;

        public FastReader(InputStream stream) {
            this.stream = stream;
        }

        public int read() {
            if (pnumChars == -1) {
                throw new InputMismatchException();
            }
            if (curChar >= pnumChars) {
                curChar = 0;
                try {
                    pnumChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (pnumChars <= 0) {
                    return -1;
                }
            }
            return buf[curChar++];
        }

        public boolean isSpaceChar(int c) {
            return isWhitespace(c);
        }

        public static boolean isWhitespace(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        public char nextCharacter() {
            int c = read();
            while (isSpaceChar(c)) {
                if (c == -1) {
                    // End of stream reached while skipping whitespace
                    throw new InputMismatchException("Unexpected end of input");
                }
                c = read();
            }
            return (char) c;
        }

        public char[] nextCharacterArray(int n) {
            char[] chars = new char[n];
            for (int i = 0; i < n; i++) {
                chars[i] = nextCharacter();
            }
            return chars;
        }

        public char[][] nextCharacterMap(int n, int m) {
            char[][] map = new char[n][];
            for (int i = 0; i < n; i++) {
                map[i] = nextCharacterArray(m);
            }
            return map;
        }
    }
}

