/**
 * Solves a grid puzzle to determine if a sequence of 5 cells contains exactly
 * one '.' and four 'X's in any horizontal, vertical, or diagonal direction.
 */
public class B {

    private static final int GRID_SIZE = 10;
    private static final int SEQUENCE_LENGTH = 5;
    private static final boolean DEBUG = false;
    private static final String FILE_NAME = "input.txt";

    public static void main(String[] args) throws IOException {
        Solver solver = new Solver();
        solver.readData();
        solver.solveAndPrint();
    }

    /**
     * Encapsulates the logic for reading the grid and solving the puzzle.
     */
    private static class Solver {
        private final char[][] grid = new char[GRID_SIZE][GRID_SIZE];

        /**
         * Reads the 10x10 grid from a file or standard input.
         */
        void readData() throws IOException {
            try (Scanner scanner = new Scanner(DEBUG ? new FileInputStream(FILE_NAME) : System.in)) {
                for (int i = 0; i < GRID_SIZE; i++) {
                    String line = scanner.nextLine();
                    grid[i] = line.toCharArray();
                }
            }
        }

        /**
         * Solves the puzzle and prints the result.
         */
        void solveAndPrint() {
            for (int i = 0; i < GRID_SIZE; i++) {
                for (int j = 0; j < GRID_SIZE; j++) {
                    if (grid[i][j] == '.') {
                        if (hasFiveInLine(i, j)) {
                            System.out.println("YES");
                            return;
                        }
                    }
                }
            }
            System.out.println("NO");
        }

        /**
         * Checks if any line of length 5 passing through (row, col) contains exactly 4 'X's.
         */
        private boolean hasFiveInLine(int row, int col) {
            int[][] directions = {{0, 1}, {1, 0}, {1, 1}, {1, -1}};
            for (int[] dir : directions) {
                if (checkLine(row, col, dir[0], dir[1])) {
                    return true;
                }
            }
            return false;
        }

        /**
         * Checks a specific direction for a valid sequence of 5 cells including the target cell.
         */
        private boolean checkLine(int row, int col, int dRow, int dCol) {
            // Iterate through all 5 possible starting positions for a window of length 5 that includes (row, col)
            for (int k = -4; k <= 0; k++) {
                int startRow = row + k * dRow;
                int startCol = col + k * dCol;

                int xCount = 0;
                boolean valid = true;
                for (int step = 0; step < SEQUENCE_LENGTH; step++) {
                    int r = startRow + step * dRow;
                    int c = startCol + step * dCol;

                    if (r < 0 || r >= GRID_SIZE || c < 0 || c >= GRID_SIZE) {
                        valid = false;
                        break;
                    }
                    if (grid[r][c] == 'X') {
                        xCount++;
                    }
                }
                if (valid && xCount == 4) {
                    return true;
                }
            }
            return false;
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;

public class FiveInARow {
    private static final int BOARD_SIZE = 10;
    private static final int LINE_LENGTH = 5;

    // Direction deltas: {rowDelta, colDelta}
    // Covers: Down-Left, Down, Down-Right, Right
    private static final int[][] DIRECTIONS = {
        {1, -1},
        {1,  0},
        {1,  1},
        {0,  1}
    };

    public static void main(String[] args) {
        char[][] board = readBoard();
        System.out.println(hasWinningLine(board) ? "YES" : "NO");
    }

    /**
     * Reads the 10x10 board from standard input.
     */
    private static char[][] readBoard() {
        char[][] board = new char[BOARD_SIZE][];
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            for (int i = 0; i < BOARD_SIZE; i++) {
                String line = br.readLine();
                // Skip empty lines or whitespace-only lines to match competitive programming input expectations
                while (line != null && line.trim().isEmpty()) {
                    line = br.readLine();
                }
                if (line == null) {
                    throw new IOException("Unexpected end of input");
                }
                board[i] = line.toCharArray();
            }
        } catch (IOException e) {
            throw new RuntimeException("Failed to read board from standard input", e);
        }
        return board;
    }

    /**
     * Checks if the board contains any winning line of 5 cells.
     */
    private static boolean hasWinningLine(char[][] board) {
        for (int r = 0; r < BOARD_SIZE; r++) {
            for (int c = 0; c < BOARD_SIZE; c++) {
                for (int[] dir : DIRECTIONS) {
                    char[] line = extractLine(board, r, c, dir[0], dir[1]);
                    if (isWinningLine(line)) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Extracts a sequence of LINE_LENGTH cells starting from (startR, startC)
     * in the given direction. Out-of-bounds cells are filled with a space.
     */
    private static char[] extractLine(char[][] board, int startR, int startC, int dr, int dc) {
        char[] line = new char[LINE_LENGTH];
        for (int i = 0; i < LINE_LENGTH; i++) {
            int r = startR + i * dr;
            int c = startC + i * dc;
            if (r >= 0 && r < BOARD_SIZE && c >= 0 && c < BOARD_SIZE) {
                line[i] = board[r][c];
            } else {
                line[i] = ' '; // Placeholder for out-of-bounds cells
            }
        }
        return line;
    }

    /**
     * Determines if a line of 5 cells constitutes a win.
     * A win is defined as exactly 4 'X's and 1 '.'.
     */
    private static boolean isWinningLine(char[] line) {
        int xCount = 0;
        int dotCount = 0;
        for (char c : line) {
            if (c == 'X') {
                xCount++;
            } else if (c == '.') {
                dotCount++;
            }
        }
        return xCount == 4 && dotCount == 1;
    }
}

import java.util.Scanner;

public class Main {
    private static final int BOARD_SIZE = 10;
    private static final int WIN_LENGTH = 4;
    private static final int[][] DIRECTIONS = {
        {0, 1},  // Horizontal
        {1, 0},  // Vertical
        {1, 1},  // Down-Right Diagonal
        {1, -1}  // Down-Left Diagonal
    };

    public static void main(String[] args) {
        // try-with-resources ensures the Scanner is properly closed
        try (Scanner scanner = new Scanner(System.in)) {
            while (scanner.hasNextLine()) {
                String line = scanner.nextLine().trim();
                if (line.isEmpty()) {
                    continue;
                }

                char[][] board = new char[BOARD_SIZE][BOARD_SIZE];
                board[0] = line.toCharArray();
                for (int i = 1; i < BOARD_SIZE; i++) {
                    if (scanner.hasNextLine()) {
                        board[i] = scanner.nextLine().toCharArray();
                    }
                }

                System.out.println(hasWinningMove(board) ? "YES" : "NO");
            }
        }
    }

    /**
     * Scans the entire board to find if there exists any empty cell
     * where placing an 'X' would result in a winning line.
     */
    private static boolean hasWinningMove(char[][] board) {
        for (int i = 0; i < BOARD_SIZE; i++) {
            for (int j = 0; j < BOARD_SIZE; j++) {
                if (board[i][j] == '.' && canPlaceWinningX(board, i, j)) {
                    return true;
                }
            }
        }
        return false;
    }

    /**
     * Checks if placing an 'X' at (row, col) creates a consecutive line
     * of at least WIN_LENGTH 'X's in any of the four cardinal/diagonal directions.
     */
    private static boolean canPlaceWinningX(char[][] board, int row, int col) {
        for (int[] dir : DIRECTIONS) {
            int count = 1; // Count the X we are placing

            // Check forward direction
            for (int step = 1; step < WIN_LENGTH; step++) {
                int r = row + dir[0] * step;
                int c = col + dir[1] * step;
                if (isWithinBounds(r, c) && board[r][c] == 'X') {
                    count++;
                } else {
                    break;
                }
            }

            // Check backward direction
            for (int step = 1; step < WIN_LENGTH; step++) {
                int r = row - dir[0] * step;
                int c = col - dir[1] * step;
                if (isWithinBounds(r, c) && board[r][c] == 'X') {
                    count++;
                } else {
                    break;
                }
            }

            // If we already have WIN_LENGTH consecutive 'X's (including the placed one), it's a win.
            if (count >= WIN_LENGTH) {
                return true;
            }
        }
        return false;
    }

    /**
     * Validates that the given coordinates are within the board boundaries.
     */
    private static boolean isWithinBounds(int r, int c) {
        return r >= 0 && r < BOARD_SIZE && c >= 0 && c < BOARD_SIZE;
    }
}

import java.io.*;
import java.util.*;

/**
 * Refactored version of Ed_2017_R25_B.
 * Checks a 10x10 grid for any contiguous sequence of exactly 4 'X' characters
 * horizontally, vertically, or diagonally.
 */
public class Ed_2017_R25_B {

    // Configuration constants for easy maintenance
    private static final int GRID_SIZE = 10;
    private static final int TARGET_LENGTH = 4;

    private char[][] grid;
    private FastReader in;
    private PrintWriter out;

    public static void main(String[] args) {
        new Ed_2017_R25_B().run();
    }

    /**
     * Initializes I/O, runs the solution, and ensures resources are closed.
     */
    public void run() {
        in = new FastReader(System.in);
        out = new PrintWriter(System.out);
        solve();
        out.close();
    }

    /**
     * Core logic: reads the grid and checks for consecutive 'X's.
     */
    private void solve() {
        grid = new char[GRID_SIZE][GRID_SIZE];
        for (int i = 0; i < GRID_SIZE; i++) {
            String line = in.next();
            grid[i] = line.toCharArray();
        }

        boolean found = hasConsecutiveXs();
        out.println(found ? "YES" : "NO");
    }

    /**
     * Scans the grid in all four directions to find TARGET_LENGTH consecutive 'X's.
     */
    private boolean hasConsecutiveXs() {
        // Check horizontal rows
        for (int r = 0; r < GRID_SIZE; r++) {
            for (int c = 0; c <= GRID_SIZE - TARGET_LENGTH; c++) {
                if (checkSegment(r, c, 0, 1)) return true;
            }
        }

        // Check vertical columns
        for (int r = 0; r <= GRID_SIZE - TARGET_LENGTH; r++) {
            for (int c = 0; c < GRID_SIZE; c++) {
                if (checkSegment(r, c, 1, 0)) return true;
            }
        }

        // Check main diagonals (top-left to bottom-right)
        for (int r = 0; r <= GRID_SIZE - TARGET_LENGTH; r++) {
            for (int c = 0; c <= GRID_SIZE - TARGET_LENGTH; c++) {
                if (checkSegment(r, c, 1, 1)) return true;
            }
        }

        // Check anti-diagonals (top-right to bottom-left)
        for (int r = 0; r <= GRID_SIZE - TARGET_LENGTH; r++) {
            for (int c = TARGET_LENGTH - 1; c < GRID_SIZE; c++) {
                if (checkSegment(r, c, 1, -1)) return true;
            }
        }

        return false;
    }

    /**
     * Verifies if a segment of length TARGET_LENGTH starting at (r, c) 
     * in direction (dr, dc) contains only 'X'.
     */
    private boolean checkSegment(int r, int c, int dr, int dc) {
        for (int k = 0; k < TARGET_LENGTH; k++) {
            if (grid[r + k * dr][c + k * dc] != 'X') {
                return false;
            }
        }
        return true;
    }

    /**
     * Alternative entry point for file-based testing.
     */
    public void runWithFiles() {
        in = new FastReader(new File("input.txt"));
        try {
            out = new PrintWriter(new File("output.txt"));
        } catch (FileNotFoundException e) {
            e.printStackTrace();
            return;
        }
        solve();
        out.close();
    }

    /**
     * Fast I/O helper class for competitive programming / large inputs.
     */
    static class FastReader {
        private BufferedReader br;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            br = new BufferedReader(new InputStreamReader(stream));
            tokenizer = null;
        }

        public FastReader(File file) {
            try {
                br = new BufferedReader(new FileReader(file));
                tokenizer = null;
            } catch (FileNotFoundException e) {
                e.printStackTrace();
            }
        }

        private String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public String nextLine() {
            try {
                return br.readLine();
            } catch (IOException e) {
                throw new RuntimeException(e);
            }
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }

        public double nextDouble() {
            return Double.parseDouble(next());
        }
    }
}

import java.util.Scanner;

/**
 * Solves the grid problem by checking if there is any empty spot '.' 
 * that, if filled with 'X', would create a sequence of 4 or more consecutive 'X's.
 */
public class GridGameSolver {

    private static final int GRID_SIZE = 10;

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        char[][] grid = new char[GRID_SIZE][GRID_SIZE];

        // Read the 10x10 grid from input
        for (int i = 0; i < GRID_SIZE; i++) {
            if (scanner.hasNext()) {
                String row = scanner.next();
                grid[i] = row.toCharArray();
            }
        }

        // Solve the problem and print the result
        solve(grid);

        scanner.close();
    }

    /**
     * Analyzes the grid to determine if a winning move exists.
     */
    private static void solve(char[][] grid) {
        for (int r = 0; r < grid.length; r++) {
            for (int c = 0; c < grid[r].length; c++) {
                // We are looking for an empty spot '.'
                if (grid[r][c] == '.') {
                    if (checkWinningMove(grid, r, c)) {
                        System.out.println("YES");
                        return;
                    }
                }
            }
        }
        System.out.println("NO");
    }

    /**
     * Checks if placing an 'X' at (r, c) creates a line of 4 or more 'X's.
     */
    private static boolean checkWinningMove(char[][] grid, int r, int c) {
        // Directions to check: Horizontal, Vertical, Diagonal \, Diagonal /
        int[][] directions = {
            {0, 1},  // Horizontal (Right)
            {1, 0},  // Vertical (Down)
            {1, 1},  // Diagonal (Down-Right)
            {1, -1}  // Diagonal (Down-Left)
        };

        for (int[] dir : directions) {
            // Count consecutive 'X's in the positive direction
            int countPositive = countConsecutive(grid, r, c, dir[0], dir[1]);
            // Count consecutive 'X's in the negative direction (opposite)
            int countNegative = countConsecutive(grid, r, c, -dir[0], -dir[1]);

            // If the sum of X's on both sides is 4 or more, it's a winning move
            if (countPositive + countNegative >= 4) {
                return true;
            }
        }
        return false;
    }

    /**
     * Counts consecutive 'X's starting from the neighbor of (r, c) in the given direction.
     * 
     * @param grid The game board
     * @param r Current row
     * @param c Current column
     * @param dr Row direction increment (1, -1, or 0)
     * @param dc Column direction increment (1, -1, or 0)
     * @return Number of consecutive 'X's found
     */
    private static int countConsecutive(char[][] grid, int r, int c, int dr, int dc) {
        int count = 0;
        int currR = r + dr;
        int currC = c + dc;

        // Traverse in the direction while within bounds and finding 'X'
        while (isValid(grid, currR, currC) && grid[currR][currC] == 'X') {
            count++;
            currR += dr;
            currC += dc;
        }
        return count;
    }

    /**
     * Checks if the given coordinates are within the grid boundaries.
     */
    private static boolean isValid(char[][] grid, int r, int c) {
        return r >= 0 && r < grid.length && c >= 0 && c < grid[0].length;
    }
}

import java.io.BufferedReader;
