public class Main {

    // Constants to replace magic numbers for better maintainability
    private static final int GRID_SIZE = 10;
    private static final int TARGET_LENGTH = 5;

    public static void main(String[] args) throws IOException {
        // Use try-with-resources to ensure the BufferedReader is closed automatically
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(System.in))) {
            char[][] grid = new char[GRID_SIZE][GRID_SIZE];

            // Read the grid from input
            for (int i = 0; i < GRID_SIZE; i++) {
                String line = reader.readLine();
                if (line != null) {
                    // Fill the grid row safely, handling potential short lines
                    int len = Math.min(line.length(), GRID_SIZE);
                    for (int j = 0; j < len; j++) {
                        grid[i][j] = line.charAt(j);
                    }
                }
            }

            // Check if the condition is met and print the result
            if (hasWinningSequence(grid)) {
                System.out.println("YES");
            } else {
                System.out.println("NO");
            }
        }
    }

    /**
     * Iterates through the grid to check if there is a sequence of at least
     * TARGET_LENGTH 'X' characters surrounding a '.' in any of the 4 main directions.
     */
    private static boolean hasWinningSequence(char[][] grid) {
        // Directions to check: Horizontal, Vertical, Diagonal (\), Diagonal (/)
        // Represented as {rowDelta, colDelta}
        int[][] directions = {
            {0, 1},  // Horizontal (Right)
            {1, 0},  // Vertical (Down)
            {1, 1},  // Diagonal Down-Right
            {1, -1}  // Diagonal Down-Left
        };

        for (int i = 0; i < GRID_SIZE; i++) {
            for (int j = 0; j < GRID_SIZE; j++) {
                // The original logic only checks neighbors if the current cell is a dot '.'
                if (grid[i][j] == '.') {
                    for (int[] dir : directions) {
                        int count = countConsecutive(grid, i, j, dir[0], dir[1]);
                        if (count >= TARGET_LENGTH) {
                            return true;
                        }
                    }
                }
            }
        }
        return false;
    }

    /**
     * Counts the number of consecutive 'X' characters in both directions
     * from the starting position (r, c), plus 1 (for the center position logic).
     *
     * @param grid The 2D character grid
     * @param r    The starting row
     * @param c    The starting column
     * @param dr   The row direction delta (-1, 0, or 1)
     * @param dc   The column direction delta (-1, 0, or 1)
     * @return The total count of 'X's found in both directions plus 1
     */
    private static int countConsecutive(char[][] grid, int r, int c, int dr, int dc) {
        int count = 0;

        // Scan in the positive direction (k = 1, 2, ...)
        for (int k = 1; ; k++) {
            int nr = r + k * dr;
            int nc = c + k * dc;

            // Check bounds
            if (nr < 0 || nr >= GRID_SIZE || nc < 0 || nc >= GRID_SIZE) {
                break;
            }
            // Check character
            if (grid[nr][nc] != 'X') {
                break;
            }
            count++;
        }

        // Scan in the negative direction (k = 1, 2, ...)
        // This corresponds to moving -dr, -dc
        for (int k = 1; ; k++) {
            int nr = r - k * dr;
            int nc = c - k * dc;

            // Check bounds
            if (nr < 0 || nr >= GRID_SIZE || nc < 0 || nc >= GRID_SIZE) {
                break;
            }
            // Check character
            if (grid[nr][nc] != 'X') {
                break;
            }
            count++;
        }

        // The original logic adds 1 to the count of found 'X's.
        // This likely accounts for the '.' at the center or a specific problem requirement.
        return count + 1;
    }
}

import java.util.Scanner;

/**
 * Analyzes a 10x10 board to determine if there is a winning sequence of 5 cells.
 * A winning sequence consists of 'X' characters, allowing at most one '.' as a wildcard.
 */
public class BoardAnalyzer {
    private static final int BOARD_SIZE = 10;
    private static final int WIN_LENGTH = 5;

    // Directions represented as {rowDelta, colDelta} covering all 8 possible directions
    private static final int[][] DIRECTIONS = {
        {0, 1},   // Right
        {0, -1},  // Left
        {1, 0},   // Down
        {-1, 0},  // Up
        {1, 1},   // Down-Right
        {-1, -1}, // Up-Left
        {1, -1},  // Down-Left
        {-1, 1}   // Up-Right
    };

    private final char[][] board;

    /**
     * Constructs a BoardAnalyzer with the provided game board.
     *
     * @param board 2D character array representing the game grid
     */
    public BoardAnalyzer(char[][] board) {
        this.board = board;
    }

    /**
     * Checks if any winning line of 5 cells exists on the board.
     *
     * @return true if a winning sequence is found, false otherwise
     */
    public boolean hasWinningLine() {
        for (int r = 0; r < BOARD_SIZE; r++) {
            for (int c = 0; c < BOARD_SIZE; c++) {
                for (int[] dir : DIRECTIONS) {
                    if (checkDirection(r, c, dir[0], dir[1])) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Validates a sequence of WIN_LENGTH cells starting from (startRow, startCol)
     * in the specified direction.
     *
     * @param startRow Starting row index
     * @param startCol Starting column index
     * @param dr       Row direction delta
     * @param dc       Column direction delta
     * @return true if the sequence meets the winning criteria, false otherwise
     */
    private boolean checkDirection(int startRow, int startCol, int dr, int dc) {
        int xCount = 0;
        int dotCount = 0;

        for (int i = 0; i < WIN_LENGTH; i++) {
            int r = startRow + i * dr;
            int c = startCol + i * dc;

            // Explicit bounds checking replaces the original try-catch anti-pattern
            if (r < 0 || r >= board.length || c < 0 || c >= board[r].length) {
                return false;
            }

            char cell = board[r][c];
            if (cell == 'X') {
                xCount++;
            } else if (cell == '.') {
                dotCount++;
            }
        }

        // Allows at most one '.' (wildcard) in the sequence of 5 cells
        return xCount + (dotCount > 0 ? 1 : 0) == WIN_LENGTH;
    }

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            char[][] board = new char[BOARD_SIZE][BOARD_SIZE];
            for (int i = 0; i < BOARD_SIZE; i++) {
                if (scanner.hasNext()) {
                    board[i] = scanner.next().toCharArray();
                }
            }

            BoardAnalyzer analyzer = new BoardAnalyzer(board);
            System.out.println(analyzer.hasWinningLine() ? "YES" : "NO");
        }
    }
}

