     * vertical, or diagonal direction.
     */
    private static boolean checkWinCondition(char[][] board) {
        // Direction vectors: right, down, down-right, down-left
        int[][] directions = {{0, 1}, {1, 0}, {1, 1}, {1, -1}};

        for (int row = 0; row < BOARD_SIZE; row++) {
