        if (canWin(grid)) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }

        scanner.close();
    }

    /**
     * Iterates through every cell in the grid to determine if placing an 'X' 
     * in an empty cell ('.') would result in a winning line.
     */
    private static boolean canWin(char[][] grid) {
        for (int r = 0; r < GRID_SIZE; r++) {
            for (int c = 0; c < GRID_SIZE; c++) {
                // We only check empty cells where a move can be made
                if (grid[r][c] == '.') {
                    if (checkMove(r, c, grid)) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Checks if placing an 'X' at coordinates (r, c) creates a sequence 
     * of TARGET_LENGTH consecutive 'X's in any of the 4 directions.
     */
    private static boolean checkMove(int r, int c, char[][] grid) {
        // Directions: Right, Down, Down-Right, Down-Left
        // Represented as {row_change, col_change}
        int[][] directions = {
            {0, 1},  // Horizontal
            {1, 0},  // Vertical
            {1, 1},  // Diagonal (Main)
            {1, -1}  // Diagonal (Anti)
        };

        for (int[] dir : directions) {
            int dr = dir[0];
            int dc = dir[1];

            // Count consecutive 'X's in this direction, including the hypothetical piece
            if (countConsecutive(r, c, dr, dc, grid) >= TARGET_LENGTH) {
                return true;
            }
        }
        return false;
    }

    /**
     * Counts the length of the consecutive sequence of 'X's passing through (r, c)
     * in the direction defined by (dr, dc).
     */
    private static int countConsecutive(int r, int c, int dr, int dc, char[][] grid) {
        int count = 1; // Start with 1 to account for the piece we are hypothetically placing

        // Check forward in the direction
        for (int i = 1; i < TARGET_LENGTH; i++) {
            int nr = r + dr * i;
            int nc = c + dc * i;
            if (isValid(nr, nc) && grid[nr][nc] == 'X') {
                count++;
            } else {
                break; // Sequence broken
            }
        }

        // Check backward in the direction
        for (int i = 1; i < TARGET_LENGTH; i++) {
            int nr = r - dr * i;
            int nc = c - dc * i;
            if (isValid(nr, nc) && grid[nr][nc] == 'X') {
                count++;
            } else {
                break; // Sequence broken
            }
        }

        return count;
    }

    /**
     * Checks if the coordinates are within the grid boundaries.
     */
    private static boolean isValid(int r, int c) {
        return r >= 0 && r < GRID_SIZE && c >= 0 && c < GRID_SIZE;
    }
}

import java.io.BufferedReader;
