import java.io.InputStreamReader;

/**
 * Checks a 10x10 game board for a specific pattern:
 * Exactly four 'X's and one '.' in any horizontal, vertical,
 * diagonal, or reverse diagonal line of 5 cells.
 */
public class FiveInARow {

    private static final int BOARD_SIZE = 10;
    private static final int CHECK_LENGTH = 5;
    private static final char EMPTY_CELL = '0';
    private static final char X = 'X';
    private static final char DOT = '.';

    public static void main(String[] args) throws IOException {
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(System.in))) {
            char[][] board = new char[BOARD_SIZE][BOARD_SIZE];
            for (int i = 0; i < BOARD_SIZE; i++) {
                String line = reader.readLine();
                if (line == null) {
                    throw new IOException("Unexpected end of input");
                }
                board[i] = line.toCharArray();
            }

            if (hasWinningPattern(board)) {
                System.out.println("YES");
            } else {
                System.out.println("NO");
            }
        }
    }

    /**
     * Scans the board to determine if a winning pattern exists.
     */
    private static boolean hasWinningPattern(char[][] board) {
        int[][] directions = {
            {0, 1},   // Horizontal
            {1, 0},   // Vertical
            {1, 1},   // Diagonal
            {1, -1}   // Reverse Diagonal
        };

        for (int i = 0; i < BOARD_SIZE; i++) {
            for (int j = 0; j < BOARD_SIZE; j++) {
                if (board[i][j] != EMPTY_CELL) {
                    for (int[] dir : directions) {
                        if (checkDirection(board, i, j, dir[0], dir[1])) {
                            return true;
                        }
                    }
                }
            }
        }
        return false;
    }

    /**
     * Checks a specific direction from a starting cell for the target pattern.
     */
    private static boolean checkDirection(char[][] board, int row, int col, int dRow, int dCol) {
        int xCount = 0;
        int dotCount = 0;

        for (int k = 0; k < CHECK_LENGTH; k++) {
            int r = row + k * dRow;
            int c = col + k * dCol;

            // Early exit if out of bounds
            if (r < 0 || r >= BOARD_SIZE || c < 0 || c >= BOARD_SIZE) {
                return false;
            }

            char cell = board[r][c];
            if (cell == X) {
                xCount++;
            } else if (cell == DOT) {
                dotCount++;
            }
        }

        return xCount == 4 && dotCount == 1;
    }
}

