public class B {

    private static final int GRID_SIZE = 10;
    private static final int WIN_LENGTH = 5;

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner();
        PrintWriter out = new PrintWriter(System.out);

        char[][] grid = scanner.nextGrid(GRID_SIZE, GRID_SIZE);

        boolean canWin = false;
        for (int r = 0; r < GRID_SIZE; r++) {
            for (int c = 0; c < GRID_SIZE; c++) {
                if (grid[r][c] == '.') {
                    grid[r][c] = 'X'; // Place piece
                    if (checkForWin(grid)) {
                        canWin = true;
                        break; // Early exit on success
                    }
                    grid[r][c] = '.'; // Backtrack
                }
            }
            if (canWin) break;
        }

        out.println(canWin ? "YES" : "NO");
        out.flush();
    }

    /**
     * Checks if there is a sequence of WIN_LENGTH consecutive 'X's
     * in any direction (horizontal, vertical, or diagonal).
     */
    private static boolean checkForWin(char[][] grid) {
        int[][] directions = {{0, 1}, {1, 0}, {1, 1}, {1, -1}};

        for (int[] dir : directions) {
            int dr = dir[0];
            int dc = dir[1];
            for (int r = 0; r < GRID_SIZE; r++) {
                for (int c = 0; c < GRID_SIZE; c++) {
                    if (isConsecutive(grid, r, c, dr, dc, WIN_LENGTH)) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Checks if a sequence of 'X's starts at (r, c) and extends
     * in the direction (dr, dc) for the given length.
     */
    private static boolean isConsecutive(char[][] grid, int r, int c, int dr, int dc, int length) {
        // Verify bounds for the entire sequence before iterating
        if (r + dr * (length - 1) < 0 || r + dr * (length - 1) >= GRID_SIZE ||
            c + dc * (length - 1) < 0 || c + dc * (length - 1) >= GRID_SIZE) {
            return false;
        }

        for (int i = 0; i < length; i++) {
            if (grid[r + dr * i][c + dc * i] != 'X') {
                return false;
            }
        }
        return true;
    }

    /**
     * Simplified and robust FastScanner for competitive programming inputs.
     */
    static class FastScanner {
        private BufferedReader br;
        private StringTokenizer st;

        public FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        public String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    e.printStackTrace();
                    return null;
                }
            }
            return st.nextToken();
        }

        public char[][] nextGrid(int n, int m) {
            char[][] grid = new char[n][m];
            for (int i = 0; i < n; i++) {
                String row = next();
                if (row != null) {
                    grid[i] = row.toCharArray();
                }
            }
            return grid;
        }
    }
}

import java.io.BufferedReader;
