import java.util.StringTokenizer;

/**
 * Refactored version of the original grid-based game solver.
 * 
 * Key Improvements:
 * 1. Removed unused imports, fields (MOD), and the bulky custom InputReader.
 * 2. Replaced custom I/O with standard BufferedReader + StringTokenizer for better maintainability.
 * 3. Extracted magic numbers (BOARD_SIZE, WIN_LENGTH) to named constants.
 * 4. Simplified the validation logic into a clear, readable hasFiveInARow() method.
 * 5. Used labeled breaks for clean early-exit from nested loops.
 * 6. Improved naming conventions and added JavaDoc/comments for clarity.
 */
public class Main {
    private static final int BOARD_SIZE = 10;
    private static final int WIN_LENGTH = 5;

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner();
        PrintWriter out = new PrintWriter(System.out);

        try {
            solve(scanner, out);
        } finally {
            out.flush();
            out.close();
        }
    }

    private static void solve(FastScanner scanner, PrintWriter out) {
        // Original code hardcoded tc = 1. Kept for compatibility but made explicit.
        int testCases = 1;

        for (int t = 1; t <= testCases; t++) {
            char[][] board = new char[BOARD_SIZE][];
            for (int i = 0; i < BOARD_SIZE; i++) {
                String line = scanner.next();
                board[i] = line.toCharArray();
            }

            boolean canWin = false;
            outer:
            for (int r = 0; r < BOARD_SIZE; r++) {
                for (int c = 0; c < BOARD_SIZE; c++) {
                    if (board[r][c] == '.') {
                        board[r][c] = 'X'; // Try placing a piece
                        if (hasFiveInARow(board)) {
                            canWin = true;
                            break outer; // Early exit if winning move found
                        }
                        board[r][c] = '.'; // Backtrack
                    }
                }
            }

            out.println(canWin ? "YES" : "NO");
        }
    }

    /**
     * Checks if there are 5 consecutive 'X's in any row, column, or diagonal.
     */
    private static boolean hasFiveInARow(char[][] board) {
        int n = board.length;

        // Check rows
        for (int r = 0; r < n; r++) {
            int count = 0;
            for (int c = 0; c < n; c++) {
                count = (board[r][c] == 'X') ? count + 1 : 0;
                if (count >= WIN_LENGTH) return true;
            }
        }

        // Check columns
        for (int c = 0; c < n; c++) {
            int count = 0;
            for (int r = 0; r < n; r++) {
                count = (board[r][c] == 'X') ? count + 1 : 0;
                if (count >= WIN_LENGTH) return true;
            }
        }

        // Check diagonals (top-left to bottom-right)
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < n; c++) {
                if (board[r][c] == 'X') {
                    int count = 0;
                    for (int k = 0; r + k < n && c + k < n; k++) {
                        if (board[r + k][c + k] == 'X') {
                            count++;
                        } else {
                            break;
                        }
                    }
                    if (count >= WIN_LENGTH) return true;
                }
            }
        }

        // Check diagonals (top-right to bottom-left)
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < n; c++) {
                if (board[r][c] == 'X') {
                    int count = 0;
                    for (int k = 0; r + k < n && c - k >= 0; k++) {
                        if (board[r + k][c - k] == 'X') {
                            count++;
                        } else {
                            break;
                        }
                    }
                    if (count >= WIN_LENGTH) return true;
                }
            }
        }

        return false;
    }

    /**
     * Lightweight, standard-compliant FastScanner to replace the original complex InputReader.
     */
    private static class FastScanner {
        private final BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        private StringTokenizer st = new StringTokenizer("");

        public String next() {
            while (!st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input", e);
                }
            }
            return st.nextToken();
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

/**
 * Checks if placing a mark in any empty cell of a 10x10 grid creates a winning 
 * line of 5 consecutive marks in any direction.
 */
public class FiveInARowChecker {
    // Board configuration constants to eliminate magic numbers
    private static final int BOARD_SIZE = 10;
    private static final int WIN_LENGTH = 5;
    private static final char EMPTY_CELL = '.';
    private static final char PLAYER_MARK = 'X';

    private final BufferedReader reader;
    private final PrintWriter out;
    private StringTokenizer tokenizer;

    public FiveInARowChecker() {
        this.reader = new BufferedReader(new InputStreamReader(System.in));
        this.out = new PrintWriter(System.out);
    }

    public static void main(String[] args) {
        FiveInARowChecker solver = new FiveInARowChecker();
        solver.solve();
        solver.out.flush();
    }

    /**
     * Orchestrates the solving process: reads input, tests placements, and outputs result.
     */
    public void solve() {
        char[][] board = readBoard();
        boolean canWin = false;

        // Try placing the mark in every empty cell
        for (int row = 0; row < BOARD_SIZE; row++) {
            for (int col = 0; col < BOARD_SIZE; col++) {
                if (board[row][col] == EMPTY_CELL) {
                    board[row][col] = PLAYER_MARK;

                    if (hasWinningLine(board)) {
                        canWin = true;
                    }

                    board[row][col] = EMPTY_CELL; // Backtrack to restore state

                    if (canWin) {
                        break; // Early exit optimization
                    }
                }
            }
            if (canWin) {
                break;
            }
        }

        out.println(canWin ? "YES" : "NO");
    }

    /**
     * Reads the 10x10 character grid from standard input.
     */
    private char[][] readBoard() {
        char[][] board = new char[BOARD_SIZE][BOARD_SIZE];
        for (int i = 0; i < BOARD_SIZE; i++) {
            String line = next();
            if (line == null || line.length() < BOARD_SIZE) {
                throw new IllegalArgumentException("Invalid board input at row " + i);
            }
            board[i] = line.toCharArray();
        }
        return board;
    }

    /**
     * Determines if the current board state contains a winning line of 5 consecutive marks.
     * Uses direction vectors to efficiently check all four possible lines.
     */
    private boolean hasWinningLine(char[][] board) {
        // Directions: Horizontal, Vertical, Diagonal Down-Right, Diagonal Down-Left
        int[][] directions = {{0, 1}, {1, 0}, {1, 1}, {1, -1}};

        for (int r = 0; r < BOARD_SIZE; r++) {
            for (int c = 0; c < BOARD_SIZE; c++) {
                if (board[r][c] != PLAYER_MARK) {
                    continue;
                }

                // Check all 4 directions from this mark
                for (int[] dir : directions) {
                    if (checkDirection(board, r, c, dir[0], dir[1])) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Checks if WIN_LENGTH consecutive marks exist in a specific direction 
     * starting from (r, c).
     */
    private boolean checkDirection(char[][] board, int r, int c, int dr, int dc) {
        int count = 1; // Start with the current mark
        for (int k = 1; k < WIN_LENGTH; k++) {
            int nr = r + dr * k;
            int nc = c + dc * k;

            // Check bounds and if the cell contains the player's mark
            if (nr < 0 || nr >= BOARD_SIZE || nc < 0 || nc >= BOARD_SIZE || board[nr][nc] != PLAYER_MARK) {
                return false;
            }
        }
        return true;
    }

    /**
     * Helper method to read the next token from input, handling whitespace and newlines.
     * Replaces the custom fast I/O boilerplate with standard, readable Java I/O.
     */
    private String next() {
        while (tokenizer == null || !tokenizer.hasMoreTokens()) {
            try {
                String line = reader.readLine();
                if (line == null) {
                    return null;
                }
                tokenizer = new StringTokenizer(line);
            } catch (IOException e) {
                throw new RuntimeException("Failed to read input", e);
            }
        }
        return tokenizer.nextToken();
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

/**
 * Solves a 10x10 grid puzzle by checking if placing an 'X' in any empty cell
 * results in a winning line of 5 consecutive 'X's.
 */
public class ConnectFiveSolver implements Runnable {
    private static final int GRID_SIZE = 10;
    private static final int WIN_LENGTH = 5;

    public static void main(String[] args) {
        // Maintains original thread creation with increased stack size (256MB)
        // to prevent potential StackOverflowError during complex operations.
        Thread solverThread = new Thread(null, new ConnectFiveSolver(), "_cf", 1 << 28);
        solverThread.start();
    }

    @Override
    public void run() {
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
             PrintWriter out = new PrintWriter(System.out)) {

            System.err.println("Go!");

            char[][] grid = new char[GRID_SIZE][GRID_SIZE];
            StringTokenizer tokenizer = new StringTokenizer("");

            // Read grid rows as whitespace-delimited tokens
            for (int i = 0; i < GRID_SIZE; i++) {
                while (!tokenizer.hasMoreTokens()) {
                    String line = reader.readLine();
                    if (line == null) break;
                    tokenizer = new StringTokenizer(line);
                }
                if (tokenizer.hasMoreTokens()) {
                    grid[i] = tokenizer.nextToken().toCharArray();
                }
            }

            boolean winFound = false;
            // Try placing an 'X' in every empty cell
            for (int i = 0; i < GRID_SIZE; i++) {
                for (int j = 0; j < GRID_SIZE; j++) {
                    if (grid[i][j] == '.') {
                        grid[i][j] = 'X';
                        if (hasWinningLine(grid)) {
                            out.println("YES");
                            winFound = true;
                            break;
                        }
                        grid[i][j] = '.'; // Backtrack to restore original state
                    }
                }
                if (winFound) break;
            }

            if (!winFound) {
                out.println("NO");
            }
            out.flush();
        } catch (IOException e) {
            System.err.println("Error reading input: " + e.getMessage());
        }
    }

    /**
     * Checks if the current grid configuration contains a winning line of 5 'X's.
     * Scans rows, columns, and both diagonal directions.
     */
    private boolean hasWinningLine(char[][] grid) {
        // Check rows
        for (int i = 0; i < GRID_SIZE; i++) {
            for (int j = 0; j <= GRID_SIZE - WIN_LENGTH; j++) {
                if (checkLine(grid, i, j, 0, 1)) return true;
            }
        }
        // Check columns
        for (int j = 0; j < GRID_SIZE; j++) {
            for (int i = 0; i <= GRID_SIZE - WIN_LENGTH; i++) {
                if (checkLine(grid, i, j, 1, 0)) return true;
            }
        }
        // Check main diagonals (top-left to bottom-right)
        for (int i = 0; i <= GRID_SIZE - WIN_LENGTH; i++) {
            for (int j = 0; j <= GRID_SIZE - WIN_LENGTH; j++) {
                if (checkLine(grid, i, j, 1, 1)) return true;
            }
        }
        // Check anti-diagonals (top-right to bottom-left)
        for (int i = 0; i <= GRID_SIZE - WIN_LENGTH; i++) {
            for (int j = WIN_LENGTH - 1; j < GRID_SIZE; j++) {
                if (checkLine(grid, i, j, 1, -1)) return true;
            }
        }
        return false;
    }

    /**
     * Verifies if a line of WIN_LENGTH cells starting at (startRow, startCol)
     * in the direction (deltaRow, deltaCol) consists entirely of 'X's.
     */
    private boolean checkLine(char[][] grid, int startRow, int startCol, int deltaRow, int deltaCol) {
        for (int k = 0; k < WIN_LENGTH; k++) {
            if (grid[startRow + k * deltaRow][startCol + k * deltaCol] != 'X') {
                return false;
            }
        }
        return true;
    }
}

import java.io.*;
import java.util.StringTokenizer;

public class Main {
    // Configuration constants to replace magic numbers
    private static final int BOARD_SIZE = 10;
    private static final int WIN_LENGTH = 5;
    private static final char EMPTY_CELL = '.';
    private static final char PLAYER_CELL = 'X';

    // Direction vectors: (dx, dy) for right, down, down-right, down-left
    private static final int[] DIR_X = {1, 0, 1, 1};
    private static final int[] DIR_Y = {0, 1, 1, -1};

    public static void main(String[] args) throws IOException {
        InputReader sc = new InputReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            char[][] board = readBoard(sc, BOARD_SIZE);
            boolean hasWin = checkForWin(board, BOARD_SIZE);
            out.println(hasWin ? "YES" : "NO");
        } finally {
            out.flush();
            out.close();
        }
    }

    /**
     * Reads the grid from the input reader.
     */
    private static char[][] readBoard(InputReader sc, int size) {
        char[][] board = new char[size][size];
        for (int i = 0; i < size; i++) {
            String row = sc.next();
            for (int j = 0; j < size; j++) {
                board[i][j] = row.charAt(j);
            }
        }
        return board;
    }

    /**
     * Checks the entire board for a winning line.
     */
    private static boolean checkForWin(char[][] board, int size) {
        for (int r = 0; r < size; r++) {
            for (int c = 0; c < size; c++) {
                for (int dir = 0; dir < DIR_X.length; dir++) {
                    if (checkLine(board, r, c, DIR_X[dir], DIR_Y[dir])) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Checks if a line of WIN_LENGTH cells starting at (r, c) in direction (dr, dc)
     * satisfies the original condition: exactly 1 empty cell and 4 player cells.
     */
    private static boolean checkLine(char[][] board, int r, int c, int dr, int dc) {
        int emptyCount = 0;
        int playerCount = 0;

        for (int i = 0; i < WIN_LENGTH; i++) {
            int nr = r + i * dr;
            int nc = c + i * dc;

            // Boundary check
            if (nr < 0 || nr >= BOARD_SIZE || nc < 0 || nc >= BOARD_SIZE) {
                return false;
            }

            char cell = board[nr][nc];
            if (cell == PLAYER_CELL) {
                playerCount++;
            } else if (cell == EMPTY_CELL) {
                emptyCount++;
            } else {
                // Unexpected character encountered
                return false;
            }
        }

        // Preserved original business logic: exactly 1 empty and 4 player cells
        return emptyCount == 1 && playerCount == 4;
    }

    /**
     * Fast I/O helper class for competitive programming and large inputs.
     */
    static class InputReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public InputReader(InputStream stream) {
            this.reader = new BufferedReader(new InputStreamReader(stream), 32768);
            this.tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }

        public double nextDouble() {
            return Double.parseDouble(next());
        }

        public String nextLine() throws IOException {
            return reader.readLine();
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;

public class FiveInRow {
    // Constants for board dimensions and symbols
    private static final int BOARD_SIZE = 10;
    private static final char PLAYER_X = 'X';
    private static final char PLAYER_O = 'O';
    private static final char EMPTY = '.';

    public static void main(String[] args) {
        FiveInRow game = new FiveInRow();
        try {
            boolean canWin = game.checkWinCondition();
            System.out.println(canWin ? "YES" : "NO");
        } catch (IOException e) {
            System.err.println("Error reading input: " + e.getMessage());
            e.printStackTrace();
        }
    }

    /**
     * Orchestrates the reading of the board and checks for a winning move.
     */
    public boolean checkWinCondition() throws IOException {
        char[][] board = readBoard();
        return hasWinningMove(board);
    }

    /**
     * Reads the 10x10 board from standard input.
     */
    private char[][] readBoard() throws IOException {
        char[][] board = new char[BOARD_SIZE][BOARD_SIZE];
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(System.in))) {
            for (int y = 0; y < BOARD_SIZE; y++) {
                String line = reader.readLine();
                if (line != null) {
                    // Trim whitespace to handle potential formatting issues
                    line = line.trim();
                    for (int x = 0; x < BOARD_SIZE && x < line.length(); x++) {
                        board[y][x] = line.charAt(x);
                    }
                }
            }
        }
        return board;
    }

    /**
     * Checks if there is a winning move (5 in a row) for player X.
     * A winning move is defined as a sequence of 5 cells containing either:
     * 1. Five 'X's (already won).
     * 2. Four 'X's and one 'Empty' spot (the winning move).
     */
    private boolean hasWinningMove(char[][] board) {
        // Check all possible lines of length 5

        // 1. Horizontal Lines
        for (int y = 0; y < BOARD_SIZE; y++) {
            for (int x = 0; x <= BOARD_SIZE - 5; x++) {
                if (isLineWinning(board, y, x, 0, 1)) {
                    return true;
                }
            }
        }

        // 2. Vertical Lines
        for (int x = 0; x < BOARD_SIZE; x++) {
            for (int y = 0; y <= BOARD_SIZE - 5; y++) {
                if (isLineWinning(board, y, x, 1, 0)) {
                    return true;
                }
            }
        }

        // 3. Diagonal Lines (Down-Right)
        for (int y = 0; y <= BOARD_SIZE - 5; y++) {
            for (int x = 0; x <= BOARD_SIZE - 5; x++) {
                if (isLineWinning(board, y, x, 1, 1)) {
                    return true;
                }
            }
        }

        // 4. Diagonal Lines (Down-Left)
        for (int y = 0; y <= BOARD_SIZE - 5; y++) {
            for (int x = 4; x < BOARD_SIZE; x++) {
                if (isLineWinning(board, y, x, 1, -1)) {
                    return true;
                }
            }
        }

        return false;
    }

    /**
     * Checks a specific sequence of 5 cells starting at (startY, startX)
     * with direction increments (dy, dx).
     * 
     * @param board The game board
     * @param startY Starting row index
     * @param startX Starting column index
     * @param dy Row direction increment
     * @param dx Column direction increment
     * @return true if the line contains 5 'X's or 4 'X's and 1 'Empty'
     */
    private boolean isLineWinning(char[][] board, int startY, int startX, int dy, int dx) {
        int xCount = 0;
        int emptyCount = 0;

        for (int i = 0; i < 5; i++) {
            int r = startY + (i * dy);
            int c = startX + (i * dx);

            // Safety check for bounds
            if (r < 0 || r >= BOARD_SIZE || c < 0 || c >= BOARD_SIZE) {
                return false;
            }

            char cell = board[r][c];

            if (cell == PLAYER_X) {
                xCount++;
            } else if (cell == EMPTY) {
                emptyCount++;
            } else {
                // Hit a Player 'O' or invalid character, line is broken
                return false;
            }
        }

        // Valid win if 5 Xs, or 4 Xs + 1 Empty (potential move)
        return (xCount == 5) || (xCount == 4 && emptyCount == 1);
    }
}

import java.io.*;
import java.util.StringTokenizer;

public class B425 {
    private static final int LINE_LENGTH = 5;

    private char[][] grid;

    public static void main(String[] args) {
        new B425().solve();
    }

    private void solve() {
        IO io = new IO(System.in);
        grid = new char[10][];
        for (int i = 0; i < grid.length; i++) {
            grid[i] = io.next().toCharArray();
        }

        boolean found = checkAllPatterns();
        io.println(found ? "YES" : "NO");
        io.close();
    }

    private boolean checkAllPatterns() {
        int rows = grid.length;
        int cols = grid[0].length;

        // Check horizontal lines
        for (int r = 0; r <= rows - LINE_LENGTH; r++) {
            for (int c = 0; c < cols; c++) {
                if (checkPattern(r, c, 0, 1)) return true;
            }
        }

        // Check vertical lines
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c <= cols - LINE_LENGTH; c++) {
                if (checkPattern(r, c, 1, 0)) return true;
            }
        }

        // Check main diagonals (top-left to bottom-right)
        for (int r = 0; r <= rows - LINE_LENGTH; r++) {
            for (int c = 0; c <= cols - LINE_LENGTH; c++) {
                if (checkPattern(r, c, 1, 1)) return true;
            }
        }

        // Check anti-diagonals (bottom-left to top-right)
        for (int r = LINE_LENGTH - 1; r < rows; r++) {
            for (int c = 0; c <= cols - LINE_LENGTH; c++) {
                if (checkPattern(r, c, -1, 1)) return true;
            }
        }

        return false;
    }

    /**
     * Checks a line of length LINE_LENGTH starting at (startR, startC)
     * in the direction specified by (dr, dc).
     * Returns true if exactly one '.' is found and no 'O' is encountered.
     */
    private boolean checkPattern(int startR, int startC, int dr, int dc) {
        int dotCount = 0;
        for (int i = 0; i < LINE_LENGTH; i++) {
            int r = startR + i * dr;
            int c = startC + i * dc;
            char cell = grid[r][c];

            if (cell == 'O') {
                return false;
            }
            if (cell == '.') {
                dotCount++;
            }
        }
        return dotCount == 1;
    }

    /**
     * Fast I/O helper class for competitive programming.
     */
    static class IO extends PrintWriter {
        private static BufferedReader reader;
        private static StringTokenizer tokenizer;

        public IO(InputStream input) {
            super(new BufferedOutputStream(System.out));
            reader = new BufferedReader(new InputStreamReader(input));
            tokenizer = new StringTokenizer("");
        }

        public String next() throws IOException {
            while (!tokenizer.hasMoreTokens()) {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        public long nextLong() throws IOException {
            return Long.parseLong(next());
        }

        public double nextDouble() throws IOException {
            return Double.parseDouble(next());
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

public class Main {
    // Grid dimensions (Hardcoded as per original logic)
    private static final int ROWS = 10;
    private static final int COLS = 10;

    // Direction vectors for the 4 axes (Vertical, Horizontal, Diagonal 1, Diagonal 2)
    // Each array represents {dr1, dc1, dr2, dc2} for opposite directions.
    // This replaces the complex dx/dy array logic for better readability.
    private static final int[][] AXES = {
        {1, 0, -1, 0},      // Vertical: Down, Up
        {0, 1, 0, -1},      // Horizontal: Right, Left
        {1, 1, -1, -1},     // Diagonal: Down-Right, Up-Left
        {1, -1, -1, 1}      // Diagonal: Down-Left, Up-Right
    };

    public static void main(String[] args) {
        FastScanner in = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out);
        new Main().solve(in, out);
        out.close();
    }

    public void solve(FastScanner in, PrintWriter out) {
        // Read the grid
        // Note: Original code assumed N=10 rows.
        char[][] grid = new char[ROWS][];
        for (int i = 0; i < ROWS; i++) {
            String rowStr = in.next();
            if (rowStr != null) {
                grid[i] = rowStr.toCharArray();
            } else {
                grid[i] = new char[0];
            }
        }

        // Iterate through every cell in the grid
        for (int r = 0; r < ROWS; r++) {
            // Safety check for row length
            int rowLength = (grid[r] != null) ? grid[r].length : 0;

            for (int c = 0; c < rowLength; c++) {

                // We are looking for a '.' to form a line of 5
                if (grid[r][c] != '.') continue;

                // Check all 4 axes passing through this cell
                for (int[] axis : AXES) {
                    int dr1 = axis[0];
                    int dc1 = axis[1];
                    int dr2 = axis[2];
                    int dc2 = axis[3];

                    // Count consecutive 'X's in both directions
                    int count1 = countConsecutive(grid, r, c, dr1, dc1);
                    int count2 = countConsecutive(grid, r, c, dr2, dc2);

                    // If total length (Xs + current dot) is >= 5, we found a valid line
                    // Original logic: cnt[0] + cnt[1] + 1 >= 5
                    if (count1 + count2 + 1 >= 5) {
                        out.println("YES");
                        return;
                    }
                }
            }
        }

        out.println("NO");
    }

    /**
     * Counts consecutive 'X's in a specific direction starting from (r, c).
     * Stops after 4 steps or if a non-'X' is encountered.
     */
    private int countConsecutive(char[][] grid, int r, int c, int dr, int dc) {
        int count = 0;
        int currR = r + dr;
        int currC = c + dc;

        // Check up to 4 steps away (Original loop: c < 5, starting at 1)
        for (int step = 0; step < 4; step++) {
            if (isValid(grid, currR, currC) && grid[currR][currC] == 'X') {
                count++;
                currR += dr;
                currC += dc;
            } else {
                break;
            }
        }
        return count;
    }

    /**
     * Checks if coordinates are within grid bounds.
     */
    private boolean isValid(char[][] grid, int r, int c) {
        return r >= 0 && r < grid.length && c >= 0 && c < grid[r].length;
    }

    // FastScanner utility class for fast input reading
    static class FastScanner {
        BufferedReader br;
        StringTokenizer st;

        public FastScanner(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
            st = null;
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    e.printStackTrace();
                    return null;
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            String s = next();
            return (s == null) ? 0 : Integer.parseInt(s);
        }

        long nextLong() {
            String s = next();
            return (s == null) ? 0L : Long.parseLong(s);
        }
    }
}

import java.util.Scanner;

public class FiveInRow {
    // Constants for better maintainability and readability
    private static final int BOARD_SIZE = 10;
    private static final String[] WINNING_PATTERNS = {
        ".XXXX", "X.XXX", "XX.XX", "XXX.X", "XXXX."
    };

    public static void main(String[] args) {
        // Use try-with-resources to ensure the Scanner is closed properly
        try (Scanner sc = new Scanner(System.in)) {
            String[] board = new String[BOARD_SIZE];

            // Read the 10 lines of input
            for (int i = 0; i < BOARD_SIZE; i++) {
                if (sc.hasNextLine()) {
                    board[i] = sc.nextLine();
                } else {
                    board[i] = ""; // Handle cases with fewer than 10 lines gracefully
                }
            }

            // Check for winning condition
            if (hasFiveInRow(board)) {
                System.out.println("YES");
            } else {
                System.out.println("NO");
            }
        }
    }

    /**
     * Checks rows, columns, and diagonals for a winning pattern.
     */
    private static boolean hasFiveInRow(String[] board) {
        // 1. Check Horizontal Lines (Rows)
        for (String row : board) {
            if (checkLine(row)) {
                return true;
            }
        }

        // 2. Check Vertical Lines (Columns)
        for (int col = 0; col < BOARD_SIZE; col++) {
            StringBuilder colBuilder = new StringBuilder();
            for (int row = 0; row < BOARD_SIZE; row++) {
                // Ensure line is long enough to avoid IndexOutOfBoundsException
                if (row < board.length && col < board[row].length()) {
                    colBuilder.append(board[row].charAt(col));
                }
            }
            if (checkLine(colBuilder.toString())) {
                return true;
            }
        }

        // 3. Check Diagonals
        if (checkDiagonals(board)) {
            return true;
        }

        return false;
    }

    /**
     * Checks all diagonals (both main and anti-diagonals).
     */
    private static boolean checkDiagonals(String[] board) {
        // Check Main Diagonals (Top-Left to Bottom-Right)
        // These are defined by a constant difference between row and column indices (row - col = k)
        for (int diff = -BOARD_SIZE + 1; diff < BOARD_SIZE; diff++) {
            String line = extractDiagonal(board, diff, 1, 1);
            if (checkLine(line)) {
                return true;
            }
        }

        // Check Anti-Diagonals (Top-Right to Bottom-Left)
        // These are defined by a constant sum of row and column indices (row + col = k)
        for (int sum = 0; sum < 2 * BOARD_SIZE - 1; sum++) {
            String line = extractAntiDiagonal(board, sum, 1, -1);
            if (checkLine(line)) {
                return true;
            }
        }

        return false;
    }

    /**
     * Extracts a string representing a diagonal line from the board.
     * 
     * @param board The game board
     * @param diff The constant difference (row - col) for main diagonals
     * @param dr Row increment (usually 1)
     * @param dc Column increment (usually 1)
     * @return String representation of the diagonal
     */
    private static String extractDiagonal(String[] board, int diff, int dr, int dc) {
        StringBuilder sb = new StringBuilder();

        // Calculate starting position based on the difference
        // row - col = diff  =>  col = row - diff
        // We need 0 <= row < SIZE and 0 <= col < SIZE
        int startRow = Math.max(0, diff);
        int startCol = startRow - diff;

        int r = startRow;
        int c = startCol;

        while (r < BOARD_SIZE && c < BOARD_SIZE) {
            if (c < board[r].length()) {
                sb.append(board[r].charAt(c));
            }
            r += dr;
            c += dc;
        }
        return sb.toString();
    }

    /**
     * Extracts a string representing an anti-diagonal line from the board.
     * 
     * @param board The game board
     * @param sum The constant sum (row + col) for anti-diagonals
     * @param dr Row increment (usually 1)
     * @param dc Column decrement (usually -1)
     * @return String representation of the anti-diagonal
     */
    private static String extractAntiDiagonal(String[] board, int sum, int dr, int dc) {
        StringBuilder sb = new StringBuilder();

        // Calculate starting position based on the sum
        // row + col = sum  =>  col = sum - row
        // We need 0 <= row < SIZE and 0 <= col < SIZE
        int startRow = Math.max(0, sum - BOARD_SIZE + 1);
        int startCol = sum - startRow;

        int r = startRow;
        int c = startCol;

        while (r < BOARD_SIZE && c >= 0) {
            if (c < board[r].length()) {
                sb.append(board[r].charAt(c));
            }
            r += dr;
            c += dc;
        }
        return sb.toString();
    }

    /**
     * Checks if the given line contains any of the winning patterns.
     * Preserves original logic: checks for specific 5-character sequences.
     */
    private static boolean checkLine(String line) {
        for (String pattern : WINNING_PATTERNS) {
            if (line.contains(pattern)) {
                return true;
            }
        }
        return false;
    }
}

