        private static final char TARGET_CHAR = 'X';
        private static final char EMPTY_CHAR = '.';

        public void solve(InputReader in, OutputWriter out) {
            char[][] grid = readGrid(in);
            boolean canWin = canPlaceAndCheckWin(grid);
            out.println(canWin ? "YES" : "NO");
        }

        private char[][] readGrid(InputReader in) {
            char[][] grid = new char[GRID_ROWS][];
            for (int i = 0; i < GRID_ROWS; i++) {
                grid[i] = in.next().toCharArray();
            }
            return grid;
        }

        private boolean canPlaceAndCheckWin(char[][] grid) {
            for (int row = 0; row < grid.length; row++) {
                for (int col = 0; col < grid[row].length; col++) {
                    if (grid[row][col] == EMPTY_CHAR) {
                        grid[row][col] = TARGET_CHAR;
                        if (checkWin(grid)) {
                            return true;
                        }
                        grid[row][col] = EMPTY_CHAR; // Backtrack to restore original state
                    }
                }
            }
            return false;
        }

        private boolean checkWin(char[][] grid) {
            for (int row = 0; row < grid.length; row++) {
                for (int col = 0; col < grid[row].length; col++) {
                    if (grid[row][col] == TARGET_CHAR) {
                        for (int dir = 0; dir < 8; dir++) {
                            if (countConsecutive(grid, row, col, dir) >= REQUIRED_LENGTH) {
                                return true;
                            }
                        }
                    }
                }
            }
            return false;
        }

        private int countConsecutive(char[][] grid, int row, int col, int dir) {
            int count = 0;
            int r = row;
            int c = col;
            while (GridHelper.isValidCell(r, c, grid.length, grid[0].length) &&
                   grid[r][c] == TARGET_CHAR) {
                count++;
                r += GridHelper.DX8[dir];
                c += GridHelper.DY8[dir];
            }
            return count;
        }
    }

    static class GridHelper {
        static final int[] DX8 = {1, 1, 1, 0, -1, -1, -1, 0};
        static final int[] DY8 = {-1, 0, 1, 1, 1, 0, -1, -1};

        static boolean isValidCell(int row, int col, int rows, int cols) {
            return row >= 0 && row < rows && col >= 0 && col < cols;
        }
    }

    static class InputReader {
        private final InputStream stream;
        private final byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        public int read() {
            if (numChars == -1) {
                throw new InputMismatchException("End of stream");
            }
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException("IO error", e);
                }
                if (numChars <= 0) {
                    return -1;
                }
            }
            return buf[curChar++];
        }

        public String next() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            StringBuilder res = new StringBuilder();
            do {
                if (c != -1) {
                    res.appendCodePoint(c);
                }
                c = read();
            } while (!isSpaceChar(c));
            return res.toString();
        }

        public boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }
    }

    static class OutputWriter {
        private final PrintWriter writer;

        public OutputWriter(OutputStream outputStream) {
            this.writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(outputStream)));
        }

        public void print(Object... objects) {
            for (int i = 0; i < objects.length; i++) {
                if (i > 0) {
                    writer.print(' ');
                }
                writer.print(objects[i]);
            }
        }

        public void println(Object... objects) {
            print(objects);
            writer.println();
        }

        public void close() {
            writer.flush();
            writer.close();
        }
    }
}

import java.util.Scanner;

public class FiveInARow {
    // Constants to replace magic numbers and improve maintainability
    private static final int GRID_SIZE = 10;
    private static final int SEQUENCE_LENGTH = 5;
    private static final int WINNING_SUM = 398; // Magic number extracted from original logic

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        char[][] grid = new char[GRID_SIZE][GRID_SIZE];

        // Read the grid from input
        for (int i = 0; i < GRID_SIZE; i++) {
            if (scanner.hasNextLine()) {
                String line = scanner.nextLine();
                grid[i] = line.toCharArray();
            }
        }
        scanner.close();

        if (hasWinningSequence(grid)) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }
    }

    /**
     * Checks if there is any winning sequence in the grid.
     * Iterates through every cell and checks 4 possible directions.
     */
    private static boolean hasWinningSequence(char[][] grid) {
        // Directions: Right, Down, Diagonal Down-Right, Diagonal Down-Left
        // Represented as (rowChange, colChange)
        int[][] directions = {
            {0, 1},   // Horizontal
            {1, 0},   // Vertical
            {1, 1},   // Diagonal \
            {1, -1}   // Diagonal /
        };

        for (int r = 0; r < GRID_SIZE; r++) {
            for (int c = 0; c < GRID_SIZE; c++) {
                for (int[] dir : directions) {
                    if (checkLine(grid, r, c, dir[0], dir[1])) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Checks a specific line starting at (r, c) in direction (dr, dc).
     * Verifies bounds and checks if the sum of characters matches the winning condition.
     */
    private static boolean checkLine(char[][] grid, int r, int c, int dr, int dc) {
        // Calculate the end coordinates of the sequence
        int endR = r + (SEQUENCE_LENGTH - 1) * dr;
        int endC = c + (SEQUENCE_LENGTH - 1) * dc;

        // Check if the sequence is within grid boundaries
        // We use grid.length for rows and grid[r].length for columns to handle potential jagged arrays
        if (endR < 0 || endR >= grid.length || endC < 0 || endC >= grid[r].length) {
            return false;
        }

        int currentSum = 0;
        for (int k = 0; k < SEQUENCE_LENGTH; k++) {
            currentSum += grid[r + k * dr][c + k * dc];
        }

        // Original logic: sum of characters must equal 398
        return currentSum == WINNING_SUM;
    }
}

import java.util.Scanner;

/**
 * Checks a 10x10 grid for a line of at least 5 consecutive non-blocked cells.
 * The grid is read from standard input, where '.' represents an empty cell
 * and 'X' represents a blocked cell.
 */
public class GridLineChecker {
    private static final int GRID_SIZE = 10;
    private static final int MIN_LINE_LENGTH = 5;
    private static final char EMPTY_CELL = '.';
    private static final char BLOCKED_CELL = 'X';

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            char[][] grid = new char[GRID_SIZE][GRID_SIZE];
            for (int i = 0; i < GRID_SIZE; i++) {
                if (scanner.hasNextLine()) {
                    grid[i] = scanner.nextLine().toCharArray();
                } else {
                    throw new IllegalStateException("Input grid is incomplete.");
                }
            }

            if (hasLongEnoughLine(grid)) {
                System.out.println("YES");
            } else {
                System.out.println("NO");
            }
        }
    }

    /**
     * Iterates through the grid to find if any '.' cell is part of a line
     * of at least MIN_LINE_LENGTH consecutive non-blocked cells.
     */
    private static boolean hasLongEnoughLine(char[][] grid) {
        for (int i = 0; i < GRID_SIZE; i++) {
            for (int j = 0; j < GRID_SIZE; j++) {
                if (grid[i][j] != EMPTY_CELL) {
                    continue;
                }
                if (countConsecutiveLine(grid, i, j)) {
                    return true;
                }
            }
        }
        return false;
    }

    /**
     * Checks all four axes (vertical, horizontal, and two diagonals) passing
     * through the given cell to see if any axis contains a line of sufficient length.
     */
    private static boolean countConsecutiveLine(char[][] grid, int row, int col) {
        // Define the four axes to check: {dRow, dCol}
        int[][] axes = {
            {1, 0},   // Vertical
            {0, 1},   // Horizontal
            {1, 1},   // Main Diagonal (top-left to bottom-right)
            {1, -1}   // Anti Diagonal (top-right to bottom-left)
        };

        for (int[] axis : axes) {
            // Count consecutive non-blocked cells in both directions from the starting cell
            int count = 1 + countConsecutive(grid, row, col, axis[0], axis[1])
                              + countConsecutive(grid, row, col, -axis[0], -axis[1]);
            if (count >= MIN_LINE_LENGTH) {
                return true;
            }
        }
        return false;
    }

    /**
     * Counts consecutive non-blocked cells starting from (startRow, startCol)
     * in the direction specified by (dRow, dCol).
     */
    private static int countConsecutive(char[][] grid, int startRow, int startCol, int dRow, int dCol) {
        int count = 0;
        int r = startRow + dRow;
        int c = startCol + dCol;

        while (r >= 0 && r < GRID_SIZE && c >= 0 && c < GRID_SIZE && grid[r][c] != BLOCKED_CELL) {
            count++;
            r += dRow;
            c += dCol;
        }
        return count;
    }
}

import java.util.Scanner;

/**
 * A program to determine if a player can place an 'X' on a 10x10 game board
 * to achieve a winning line of 5 consecutive 'X's.
 */
public class WinningMoveFinder {

    // Constants for board configuration to avoid magic numbers
    private static final int BOARD_SIZE = 10;
    private static final int WIN_LENGTH = 5;

    public static void main(String[] args) {
        // Use try-with-resources to ensure the Scanner is closed properly
        try (Scanner scanner = new Scanner(System.in)) {
            char[][] board = new char[BOARD_SIZE][BOARD_SIZE];

            // Read the board state from input
            for (int i = 0; i < BOARD_SIZE; i++) {
                if (scanner.hasNextLine()) {
                    String line = scanner.nextLine();
                    // Fill the row with characters from the input line
                    // Using a safe loop to prevent IndexOutOfBoundsException
                    for (int j = 0; j < BOARD_SIZE && j < line.length(); j++) {
                        board[i][j] = line.charAt(j);
                    }
                }
            }

            // Determine if a winning move is possible
            if (canPlaceWinningMove(board)) {
                System.out.println("YES");
            } else {
                System.out.println("NO");
            }
        }
    }

    /**
     * Iterates through the board to find if placing an 'X' in an empty spot
     * results in a winning line.
     *
     * @param board The current state of the game board.
     * @return true if a winning move exists, false otherwise.
     */
    private static boolean canPlaceWinningMove(char[][] board) {
        for (int r = 0; r < BOARD_SIZE; r++) {
            for (int c = 0; c < BOARD_SIZE; c++) {
                // If the cell is empty, try placing an 'X'
                if (board[r][c] == '.') {
                    board[r][c] = 'X';

                    // Check if this move creates a winning line
                    if (hasWinningLine(board)) {
                        return true;
                    }

                    // Backtrack: revert the change to '.'
                    board[r][c] = '.';
                }
            }
        }
        return false;
    }

    /**
     * Checks if the current board configuration contains a winning line of 5 'X's.
     *
     * @param board The current state of the game board.
     * @return true if a winning line exists, false otherwise.
     */
    private static boolean hasWinningLine(char[][] board) {
        // Directions to check: Right, Down, Diagonal (Down-Right), Diagonal (Down-Left)
        // dr = delta row, dc = delta column
        int[] dr = {0, 1, 1, 1};
        int[] dc = {1, 0, 1, -1};

        for (int r = 0; r < BOARD_SIZE; r++) {
            for (int c = 0; c < BOARD_SIZE; c++) {
                // Optimization: Only check lines starting from an 'X'
                if (board[r][c] == 'X') {
                    for (int k = 0; k < 4; k++) {
                        if (checkLine(board, r, c, dr[k], dc[k])) {
                            return true;
                        }
                    }
                }
            }
        }
        return false;
    }

    /**
     * Checks if there are WIN_LENGTH consecutive 'X's starting at (r, c)
     * in the direction specified by (dr, dc).
     *
     * @param board The game board.
     * @param r     Starting row index.
     * @param c     Starting column index.
     * @param dr    Direction change for row.
     * @param dc    Direction change for column.
     * @return true if a winning line is found in this direction.
     */
    private static boolean checkLine(char[][] board, int r, int c, int dr, int dc) {
        for (int i = 0; i < WIN_LENGTH; i++) {
            int currR = r + (i * dr);
            int currC = c + (i * dc);

            // Check if the coordinate is within the board boundaries
            if (currR < 0 || currR >= BOARD_SIZE || currC < 0 || currC >= BOARD_SIZE) {
                return false;
            }

            // Check if the cell contains 'X'
            if (board[currR][currC] != 'X') {
                return false;
            }
        }
        return true;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

/**
 * Refactored version of the original program.
 * 
 * Improvements made:
 * 1. Descriptive Naming: Renamed class and methods to be more meaningful (e.g., BoardAnalyzer, verifySequence).
 * 2. Constants: Replaced magic numbers (10, 5, 4, 1) with named constants.
 * 3. I/O Handling: Removed the custom inner Scanner class and used standard BufferedReader/StringTokenizer
 *    for better performance and standard practice.
 * 4. Logic Optimization: Removed string concatenation inside loops (O(N^2) effectively) and replaced it
 *    with direct character counting (O(N)).
 * 5. Code Deduplication: Consolidated the four directional checks into a single parameterized method.
 * 6. Resource Management: Used try-finally block to ensure PrintWriter is flushed and closed.
 */
public class BoardAnalyzer {

    // Constants for grid dimensions and winning criteria
    private static final int GRID_SIZE = 10;
    private static final int WIN_LENGTH = 5;
    private static final char TARGET_CHAR = 'X';
    private static final char BLANK_CHAR = '.';

    public static void main(String[] args) throws IOException {
        // Initialize I/O streams
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter out = new PrintWriter(System.out);

        try {
            // Read the grid from input
            char[][] grid = readGrid(reader);

            // Analyze the grid for winning conditions
            boolean canWin = checkWinningCondition(grid);

            // Output result
            out.println(canWin ? "YES" : "NO");
        } finally {
            out.flush();
            out.close();
        }
    }

    /**
     * Reads the 10x10 grid from the input.
     * Assumes input format matches the original logic (tokens representing rows).
     */
    private static char[][] readGrid(BufferedReader reader) throws IOException {
        char[][] grid = new char[GRID_SIZE][GRID_SIZE];
        StringTokenizer tokenizer = null;

        for (int i = 0; i < GRID_SIZE; i++) {
            // Fetch next token similar to original custom Scanner logic
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                String line = reader.readLine();
                if (line == null) break;
                tokenizer = new StringTokenizer(line);
            }

            if (tokenizer != null && tokenizer.hasMoreTokens()) {
                String rowString = tokenizer.nextToken();
                grid[i] = rowString.toCharArray();
            }
        }
        return grid;
    }

    /**
     * Checks if there is any winning sequence in the grid.
     */
    private static boolean checkWinningCondition(char[][] grid) {
        // Iterate through every cell to act as a potential starting point
        for (int r = 0; r < GRID_SIZE; r++) {
            for (int c = 0; c < GRID_SIZE; c++) {

                // Check Horizontal (Right)
                if (c + WIN_LENGTH <= GRID_SIZE) {
                    if (verifySequence(grid, r, c, 0, 1)) return true;
                }

                // Check Vertical (Down)
                if (r + WIN_LENGTH <= GRID_SIZE) {
                    if (verifySequence(grid, r, c, 1, 0)) return true;
                }

                // Check Diagonal (Down-Right)
                if (r + WIN_LENGTH <= GRID_SIZE && c + WIN_LENGTH <= GRID_SIZE) {
                    if (verifySequence(grid, r, c, 1, 1)) return true;
                }

                // Check Diagonal (Down-Left)
                if (r + WIN_LENGTH <= GRID_SIZE && c >= WIN_LENGTH - 1) {
                    if (verifySequence(grid, r, c, 1, -1)) return true;
                }
            }
        }
        return false;
    }

    /**
     * Verifies if a sequence of length WIN_LENGTH starting at (startRow, startCol)
     * in direction (dRow, dCol) meets the winning criteria.
     * Criteria: Exactly 4 'X's and 1 '.'.
     */
    private static boolean verifySequence(char[][] grid, int startRow, int startCol, int dRow, int dCol) {
        int xCount = 0;
        int dotCount = 0;

        for (int k = 0; k < WIN_LENGTH; k++) {
            int row = startRow + k * dRow;
            int col = startCol + k * dCol;

            // Safety check for array bounds, though logic implies valid grid access
            if (row >= 0 && row < GRID_SIZE && col >= 0 && col < grid[row].length) {
                char currentChar = grid[row][col];

                if (currentChar == TARGET_CHAR) {
                    xCount++;
                } else if (currentChar == BLANK_CHAR) {
                    dotCount++;
                }
            }
        }

        return xCount == 4 && dotCount == 1;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

public class PatternFinder {

    private static final int GRID_SIZE = 10;
    private static final int PATTERN_LENGTH = 5;
    private static final char TARGET_CHAR = 'X';
    private static final char EMPTY_CHAR = '.';

    // Directions: Right, Down-Left, Down, Down-Right
    private static final int[][] DIRECTIONS = {
        {0, 1},
        {1, -1},
        {1, 0},
        {1, 1}
    };

    public static void main(String[] args) throws IOException {
        FastScanner sc = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out);

        char[][] grid = readGrid(sc);
        boolean found = findPattern(grid);

        out.println(found ? "YES" : "NO");
        out.close();
    }

    private static char[][] readGrid(FastScanner sc) throws IOException {
        char[][] grid = new char[GRID_SIZE][GRID_SIZE];
        for (int i = 0; i < GRID_SIZE; i++) {
            grid[i] = sc.next().toCharArray();
        }
        return grid;
    }

    private static boolean findPattern(char[][] grid) {
        for (int[] dir : DIRECTIONS) {
            int dirX = dir[0];
            int dirY = dir[1];

            for (int i = 0; i < GRID_SIZE; i++) {
                for (int j = 0; j < GRID_SIZE; j++) {
                    int endX = i + dirX * (PATTERN_LENGTH - 1);
                    int endY = j + dirY * (PATTERN_LENGTH - 1);

                    // Ensure the 5-cell line stays within grid boundaries
                    if (endX >= 0 && endX < GRID_SIZE && endY >= 0 && endY < GRID_SIZE) {
                        if (containsPattern(grid, i, j, dirX, dirY)) {
                            return true;
                        }
                    }
                }
            }
        }
        return false;
    }

    private static boolean containsPattern(char[][] grid, int startX, int startY, int dirX, int dirY) {
        int xCount = 0;
        int emptyCount = 0;
        for (int k = 0; k < PATTERN_LENGTH; k++) {
            char c = grid[startX + dirX * k][startY + dirY * k];
            if (c == TARGET_CHAR) {
                xCount++;
            } else if (c == EMPTY_CHAR) {
                emptyCount++;
            }
        }
        return emptyCount == 1 && xCount == 4;
    }

    /**
     * Lightweight fast I/O scanner for competitive programming and simple CLI tools.
     */
    private static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        public String next() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) {
                    throw new IOException("Unexpected end of input");
                }
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }
    }
}

import java.util.Scanner;

public class BinaryProtocol {
    private static final int GRID_SIZE = 10;
    private static final int REQUIRED_COUNT = 4;

    // Represents the four axes: horizontal, vertical, main diagonal, anti-diagonal
    private static final int[][] DIRECTIONS = {
        {0, 1},   // Horizontal (right)
        {1, 0},   // Vertical (down)
        {1, 1},   // Main diagonal (down-right)
        {1, -1}   // Anti-diagonal (down-left)
    };

    public static void main(String[] args) {
        // try-with-resources ensures the Scanner is closed automatically
        try (Scanner scanner = new Scanner(System.in)) {
            char[][] grid = new char[GRID_SIZE][GRID_SIZE];
            for (int i = 0; i < GRID_SIZE; i++) {
                String line = scanner.next();
                grid[i] = line.toCharArray();
            }

            if (hasConsecutiveXs(grid)) {
                System.out.println("YES");
            } else {
                System.out.println("NO");
            }
        }
    }

    /**
     * Checks if any '.' cell has at least REQUIRED_COUNT 'X's in any straight line direction.
     */
    private static boolean hasConsecutiveXs(char[][] grid) {
        for (int i = 0; i < GRID_SIZE; i++) {
            for (int j = 0; j < GRID_SIZE; j++) {
                if (grid[i][j] == '.') {
                    for (int[] dir : DIRECTIONS) {
                        int dx = dir[0];
                        int dy = dir[1];
                        // Count 'X's in both directions along the current axis
                        int count = countInDirection(grid, i, j, dx, dy) +
                                    countInDirection(grid, i, j, -dx, -dy);
                        if (count >= REQUIRED_COUNT) {
                            return true;
                        }
                    }
                }
            }
        }
        return false;
    }

    /**
     * Counts consecutive 'X's starting from (x, y) moving in direction (dx, dy).
     */
    private static int countInDirection(char[][] grid, int x, int y, int dx, int dy) {
        int count = 0;
        x += dx;
        y += dy;
        while (isWithinBounds(x, y) && grid[x][y] == 'X') {
            count++;
            x += dx;
            y += dy;
        }
        return count;
    }

    private static boolean isWithinBounds(int x, int y) {
        return x >= 0 && x < GRID_SIZE && y >= 0 && y < GRID_SIZE;
    }
}

import java.util.Scanner;

public class BoardChecker {

    private static final int BOARD_SIZE = 10;

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        char[][] board = new char[BOARD_SIZE][BOARD_SIZE];

        // Read the 10x10 grid from input
        for (int i = 0; i < BOARD_SIZE; i++) {
            if (scanner.hasNextLine()) {
                String line = scanner.nextLine();
                // Safely fill the row, handling potential short lines
                for (int j = 0; j < Math.min(line.length(), BOARD_SIZE); j++) {
                    board[i][j] = line.charAt(j);
                }
            }
        }
        scanner.close();

        // Check if the condition is met
        boolean found = checkCondition(board);

        if (found) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }
    }

    /**
     * Iterates through the board to find if any '.' cell satisfies the line condition.
     */
    private static boolean checkCondition(char[][] board) {
        for (int i = 0; i < BOARD_SIZE; i++) {
            for (int j = 0; j < BOARD_SIZE; j++) {
                // Original logic checks if the current cell is a dot '.'
                if (board[i][j] == '.') {
                    if (isLineValid(board, i, j)) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Checks if there are at least 4 consecutive 'X's in any direction passing through the given cell.
     */
    private static boolean isLineValid(char[][] board, int row, int col) {
        // Define the 4 axes to check: Horizontal, Vertical, Diagonal 1, Diagonal 2
        // We check pairs of opposite directions for each axis.
        int[][] directions = {
            {0, 1},   // Horizontal: Right
            {1, 0},   // Vertical: Down
            {1, 1},   // Diagonal: Down-Right
            {1, -1}   // Diagonal: Down-Left
        };

        for (int[] dir : directions) {
            // Count 'X's in the forward direction
            int countForward = countConsecutive(board, row, col, dir[0], dir[1]);
            // Count 'X's in the opposite direction
            int countBackward = countConsecutive(board, row, col, -dir[0], -dir[1]);

            // Original logic: if sum of opposite sides >= 4
            if (countForward + countBackward >= 4) {
                return true;
            }
        }
        return false;
    }

    /**
     * Counts consecutive 'X's starting from (row, col) in the direction (deltaRow, deltaCol).
     */
    private static int countConsecutive(char[][] board, int row, int col, int deltaRow, int deltaCol) {
        int count = 0;
        int currRow = row + deltaRow;
        int currCol = col + deltaCol;

        // Traverse in the specified direction while within bounds
        while (currRow >= 0 && currRow < BOARD_SIZE && 
               currCol >= 0 && currCol < BOARD_SIZE) {

            if (board[currRow][currCol] == 'X') {
                count++;
            } else {
                // Stop counting if we hit a non-'X' character
                break;
            }

            currRow += deltaRow;
            currCol += deltaCol;
        }
        return count;
    }
}

import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

/**
 * A utility class to analyze a character matrix (grid) to determine if it satisfies
 * specific color distribution and geometric constraints across rows or columns.
 */
public class GridColorChecker {

    /**
     * Holds the analysis results for a specific dimension (rows or columns).
     */
    private static class DimensionAnalysis {
        List<Integer> rIndices = new ArrayList<>();
        List<Integer> gIndices = new ArrayList<>();
        List<Integer> bIndices = new ArrayList<>();
        boolean isStructureValid = true;
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        // Read dimensions N and M
        if (!scanner.hasNextInt()) {
            scanner.close();
            return;
        }
        int n = scanner.nextInt();
        int m = scanner.nextInt();

        // Read the matrix
        char[][] matrix = new char[n][m];
        for (int i = 0; i < n; i++) {
            // Assuming input rows are provided as continuous strings without spaces
            String rowStr = scanner.next();
            for (int j = 0; j < m; j++) {
                matrix[i][j] = rowStr.charAt(j);
            }
        }

        // Check Rows first
        DimensionAnalysis rowData = analyzeDimension(matrix, true, n, m);
        if (rowData.isStructureValid && isValidConfiguration(rowData)) {
            System.out.println("YES");
            scanner.close();
            return;
        }

        // If rows check fails, check Columns
        DimensionAnalysis colData = analyzeDimension(matrix, false, n, m);
        if (colData.isStructureValid && isValidConfiguration(colData)) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }

        scanner.close();
    }

    /**
     * Analyzes a specific dimension (rows or columns) of the matrix.
     * Checks if every line in that dimension is uniform (single color) and
     * collects the indices of lines for each color (R, G, B).
     *
     * @param matrix    The character matrix.
     * @param checkRows If true, analyze rows; otherwise analyze columns.
     * @param n         Number of rows.
     * @param m         Number of columns.
     * @return          A DimensionAnalysis object containing indices and validity status.
     */
    private static DimensionAnalysis analyzeDimension(char[][] matrix, boolean checkRows, int n, int m) {
        DimensionAnalysis analysis = new DimensionAnalysis();
        int limit = checkRows ? n : m;

        for (int i = 0; i < limit; i++) {
            char color;
            // Determine the reference color for the current row or column
            if (checkRows) {
                color = matrix[i][0];
            } else {
                color = matrix[0][i];
            }

            // Check if the row/column is uniform (all characters match the reference color)
            int length = checkRows ? m : n;
            for (int j = 0; j < length; j++) {
                char currentChar;
                if (checkRows) {
                    currentChar = matrix[i][j];
                } else {
                    currentChar = matrix[j][i];
                }

                if (currentChar != color) {
                    analysis.isStructureValid = false;
                    return analysis;
                }
            }

            // Categorize the index based on the uniform color
            if (color == 'R') {
                analysis.rIndices.add(i);
            } else if (color == 'G') {
                analysis.gIndices.add(i);
            } else if (color == 'B') {
                analysis.bIndices.add(i);
            } else {
                // Invalid color character found
                analysis.isStructureValid = false;
                return analysis;
            }
        }
        return analysis;
    }

    /**
     * Validates the collected indices against specific geometric and count constraints.
     *
     * @param data The analysis results to validate.
     * @return true if the configuration is valid, false otherwise.
     */
    private static boolean isValidConfiguration(DimensionAnalysis data) {
        // All colors must be present
        if (data.rIndices.isEmpty() || data.gIndices.isEmpty() || data.bIndices.isEmpty()) {
            return false;
        }

        int rStart = data.rIndices.get(0);
        int rEnd = data.rIndices.get(data.rIndices.size() - 1);
        int gStart = data.gIndices.get(0);
        int gEnd = data.gIndices.get(data.gIndices.size() - 1);
        int bStart = data.bIndices.get(0);
        int bEnd = data.bIndices.get(data.bIndices.size() - 1);

        // Check if the span (length of range) is equal for all colors
        int rSpan = rEnd - rStart;
        int gSpan = gEnd - gStart;
        int bSpan = bEnd - bStart;

        if (rSpan != gSpan || gSpan != bSpan) {
            return false;
        }

        // Check intersection constraints
        // The start index of one color's range must not be strictly inside the range of another color.
        // This logic prevents interleaving of color blocks.
        if (!isIndexOutsideInterval(rStart, rEnd, gStart)) return false;
        if (!isIndexOutsideInterval(rStart, rEnd, bStart)) return false;
        if (!isIndexOutsideInterval(bStart, bEnd, rStart)) return false;
        if (!isIndexOutsideInterval(bStart, bEnd, gStart)) return false;
        if (!isIndexOutsideInterval(gStart, gEnd, rStart)) return false;
        if (!isIndexOutsideInterval(gStart, gEnd, bStart)) return false;

        // Check if the count of rows/cols for each color is equal
        if (data.rIndices.size() != data.gIndices.size() || data.gIndices.size() != data.bIndices.size()) {
            return false;
        }

        return true;
    }

    /**
     * Checks if an index 'c' is strictly between 'a' and 'b'.
     * Returns true if 'c' is NOT strictly between 'a' and 'b'.
     *
     * @param a Start of range.
     * @param b End of range.
     * @param c Index to check.
     * @return true if c is outside the open interval (a, b).
     */
    private static boolean isIndexOutsideInterval(int a, int b, int c) {
        return !(a < c && c < b);
    }
}

import java.util.Scanner;

public class ColorGridValidator {

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            if (!scanner.hasNextInt()) return;

            int n = scanner.nextInt();
            int m = scanner.nextInt();

            // Consume the remainder of the first line (newline character)
            scanner.nextLine();

            char[][] grid = new char[n][m];
            for (int i = 0; i < n; i++) {
                String line = scanner.nextLine().trim();
                // Ensure we don't read beyond expected dimensions
                grid[i] = line.substring(0, Math.min(line.length(), m)).toCharArray();
            }

            boolean rowsUniform = areAllRowsUniform(grid);
            boolean colsUniform = areAllColsUniform(grid);

            if (!rowsUniform && !colsUniform) {
                System.out.println("NO");
            } else if (rowsUniform) {
                // Grid has vertical stripes, validate the first column
                char[] column = new char[n];
                for (int i = 0; i < n; i++) {
                    column[i] = grid[i][0];
                }
                System.out.println(isValidColorStrip(column) ? "YES" : "NO");
            } else {
                // Grid has horizontal stripes, validate the first row
                System.out.println(isValidColorStrip(grid[0]) ? "YES" : "NO");
            }
        }
    }

    /**
     * Checks if every row in the grid consists of identical characters.
     */
    private static boolean areAllRowsUniform(char[][] grid) {
        for (char[] row : grid) {
            if (!isUniform(row)) {
                return false;
            }
        }
        return true;
    }

    /**
     * Checks if every column in the grid consists of identical characters.
     */
    private static boolean areAllColsUniform(char[][] grid) {
        int n = grid.length;
        int m = grid[0].length;
        for (int j = 0; j < m; j++) {
            char first = grid[0][j];
            for (int i = 1; i < n; i++) {
                if (grid[i][j] != first) {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Checks if all characters in an array are identical.
     */
    private static boolean isUniform(char[] arr) {
        if (arr.length == 0) return true;
        char first = arr[0];
        for (char c : arr) {
            if (c != first) {
                return false;
            }
        }
        return true;
    }

    /**
     * Validates that a 1D strip follows the pattern of exactly three contiguous 
     * blocks of 'R', 'G', and 'B', each of equal length.
     */
    private static boolean isValidColorStrip(char[] strip) {
        if (strip.length % 3 != 0) {
            return false;
        }

        int expectedLen = strip.length / 3;
        int currentLen = 0;
        char currentChar = 0;
        int blockCount = 0;

        for (char c : strip) {
            if (c != 'R' && c != 'G' && c != 'B') {
                return false;
            }

            if (c != currentChar) {
                // Validate the length of the previous block before switching
                if (currentChar != 0 && currentLen != expectedLen) {
                    return false;
                }
                currentChar = c;
                currentLen = 1;
                blockCount++;
            } else {
                currentLen++;
            }
        }

        // Validate the final block
        if (currentChar == 0 || currentLen != expectedLen) {
            return false;
        }

        // Must contain exactly 3 blocks
        if (blockCount != 3) {
            return false;
        }

        // Ensure exactly one block of each required color exists
        boolean hasR = false, hasG = false, hasB = false;
        for (char c : strip) {
            if (c == 'R') hasR = true;
            else if (c == 'G') hasG = true;
            else if (c == 'B') hasB = true;
        }

        return hasR && hasG && hasB;
    }
}

import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) {
        FastScanner scanner = new FastScanner();
        PrintWriter out = new PrintWriter(System.out);

        try {
            int n = scanner.nextInt();
            int m = scanner.nextInt();

            int[][] grid = new int[n][m];
            for (int i = 0; i < n; i++) {
                String row = scanner.next();
                for (int j = 0; j < m; j++) {
                    grid[i][j] = row.charAt(j) - '0';
                }
            }

            boolean horizontalValid = checkStrips(grid, n, m, true);
            boolean verticalValid = checkStrips(grid, n, m, false);

            out.println((horizontalValid || verticalValid) ? "YES" : "NO");
        } catch (Exception e) {
            out.println("NO");
        } finally {
            out.flush();
            out.close();
        }
    }

    /**
     * Checks if the grid can be divided into 3 uniform strips along the specified dimension.
     * Each strip must contain identical values, and all three strips must have distinct values.
     *
     * @param grid   2D array of digits
     * @param n      number of rows
     * @param m      number of columns
     * @param byRows if true, checks horizontal strips (split rows); else checks vertical strips (split columns)
     * @return true if the condition is met, false otherwise
     */
    private static boolean checkStrips(int[][] grid, int n, int m, boolean byRows) {
        if ((byRows && n % 3 != 0) || (!byRows && m % 3 != 0)) {
            return false;
        }

        int stripLen = byRows ? n / 3 : m / 3;
        int[] stripValues = new int[3];
        int mismatches = 0;

        for (int s = 0; s < 3; s++) {
            int start = s * stripLen;
            // Determine the expected value for this strip from its first cell
            int expected = byRows ? grid[start][0] : grid[0][start];
            stripValues[s] = expected;

            // Verify all cells in this strip match the expected value
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    int stripIdx = byRows ? i / stripLen : j / stripLen;
                    if (stripIdx == s && grid[i][j] != expected) {
                        mismatches++;
                    }
                }
            }
        }

        // Condition 1: No mismatches found
        // Condition 2: All three strips have distinct values
        return mismatches == 0 &&
               stripValues[0] != stripValues[1] &&
               stripValues[0] != stripValues[2] &&
               stripValues[1] != stripValues[2];
    }

    /**
     * Fast I/O helper class for competitive programming.
     */
    static class FastScanner {
        private BufferedReader br;
        private StringTokenizer st;

        public FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            String s = next();
            return s == null ? 0 : Integer.parseInt(s);
        }
    }
}

import java.io.InputStream;
import java.io.OutputStream;
import java.io.IOException;
import java.io.PrintWriter;
import java.util.Arrays;
import java.util.InputMismatchException;

public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;

        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);

        TaskB solver = new TaskB();
        solver.solve(in, out);

        out.flush();
        out.close();
    }

    /**
     * Encapsulates the problem-solving logic for Task B.
     * Checks if the grid can be divided into 3 uniform horizontal or vertical stripes
     * with distinct colors.
     */
    static class TaskB {
        public void solve(InputReader in, PrintWriter out) {
            int N = in.nextInt();
            int M = in.nextInt();
            char[][] flag = in.nextCharMatrix(N, M);

            // Short-circuit evaluation ensures we only check stripes if dimensions are divisible by 3
            boolean horizontalPossible = (N % 3 == 0) && checkStripes(flag, N, M, true);
            boolean verticalPossible = (M % 3 == 0) && checkStripes(flag, N, M, false);

            out.println(horizontalPossible || verticalPossible ? "YES" : "NO");
        }

        /**
         * Checks if the grid can be divided into 3 uniform stripes along the specified axis.
         * Each stripe must be a single color, and all 3 stripes must have distinct colors.
         *
         * @param grid      The character matrix
         * @param rows      Number of rows (N)
         * @param cols      Number of columns (M)
         * @param horizontal true to check horizontal stripes, false for vertical
         * @return true if valid stripes exist, false otherwise
         */
        private boolean checkStripes(char[][] grid, int rows, int cols, boolean horizontal) {
            boolean[] usedColors = new boolean[256]; // Covers extended ASCII safely
            int blockSize = horizontal ? rows / 3 : cols / 3;
            int fixedDim = horizontal ? cols : rows;
            int movingDim = horizontal ? rows : cols;

            for (int i = 0; i < movingDim; i += blockSize) {
                // Determine the representative color for the current stripe
                char color = horizontal ? grid[i][0] : grid[0][i];

                // Check for duplicate stripe colors
                if (usedColors[color]) {
                    return false;
                }
                usedColors[color] = true;

                // Verify all cells in the stripe match the representative color
                for (int j = i; j < i + blockSize; j++) {
                    for (int k = 0; k < fixedDim; k++) {
                        char current = horizontal ? grid[j][k] : grid[k][j];
                        if (current != color) {
                            return false;
                        }
                    }
                }
            }
            return true;
        }
    }

    /**
     * Fast input reader for competitive programming environments.
     */
    static class InputReader {
        private final InputStream in;
        private byte[] inbuf = new byte[1024];
        private int lenbuf = 0;
        private int ptrbuf = 0;

        public InputReader(InputStream in) {
            this.in = in;
        }

        private int readByte() {
            if (lenbuf == -1) {
                throw new InputMismatchException();
            }
            if (ptrbuf >= lenbuf) {
                ptrbuf = 0;
                try {
                    lenbuf = in.read(inbuf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (lenbuf <= 0) {
                    return -1;
                }
            }
            return inbuf[ptrbuf++];
        }

        private boolean isSpaceChar(int c) {
            return !(c >= 33 && c <= 126);
        }

        private int skip() {
            int b;
            while ((b = readByte()) != -1 && isSpaceChar(b)) {
                // skip whitespace
            }
            return b;
        }

        public int nextInt() {
            int num = 0, b;
            boolean minus = false;

            while ((b = readByte()) != -1 && !((b >= '0' && b <= '9') || b == '-')) {
                // skip non-digit characters
            }

            if (b == '-') {
                minus = true;
                b = readByte();
            }

            while (true) {
                if (b >= '0' && b <= '9') {
                    num = num * 10 + (b - '0');
                } else {
                    return minus ? -num : num;
                }
                b = readByte();
            }
        }

        public char[] nextCharArray(int n) {
            char[] buf = new char[n];
            int b = skip(), p = 0;
            while (p < n && !isSpaceChar(b)) {
                buf[p++] = (char) b;
                b = readByte();
            }
            return n == p ? buf : Arrays.copyOf(buf, p);
        }

        public char[][] nextCharMatrix(int n, int m) {
            char[][] map = new char[n][];
            for (int i = 0; i < n; i++) {
                map[i] = nextCharArray(m);
            }
            return map;
        }
    }
}

import java.util.Scanner;

public class FlagofBarland {

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            if (!scanner.hasNextInt()) return;

            int n = scanner.nextInt();
            int m = scanner.nextInt();

            char[][] grid = new char[n][m];
            for (int i = 0; i < n; i++) {
                grid[i] = scanner.next().toCharArray();
            }

            boolean horizontalValid = (n % 3 == 0) && hasThreeStripes(grid, true);
            boolean verticalValid = (m % 3 == 0) && hasThreeStripes(grid, false);

            System.out.println((horizontalValid || verticalValid) ? "YES" : "NO");
        }
    }

    /**
     * Checks if the grid contains three uniform stripes of distinct colors
     * along the specified dimension.
     *
     * @param grid       The character grid representing the flag.
     * @param horizontal If true, checks for horizontal stripes; otherwise, vertical.
     * @return true if the grid satisfies the three-stripe condition, false otherwise.
     */
    private static boolean hasThreeStripes(char[][] grid, boolean horizontal) {
        int blockSize = horizontal ? grid.length / 3 : grid[0].length / 3;
        char[] stripeColors = new char[3];

        for (int stripe = 0; stripe < 3; stripe++) {
            int start = stripe * blockSize;
            int end = start + blockSize;

            // The color of the first cell in the current stripe block determines the expected color
            char currentColor = horizontal ? grid[start][0] : grid[0][start];

            for (int i = start; i < end; i++) {
                for (int j = 0; j < (horizontal ? grid[0].length : grid.length); j++) {
                    char cellColor = horizontal ? grid[i][j] : grid[j][i];
                    if (cellColor != currentColor) {
                        return false; // Stripe is not uniform
                    }
                }
            }
            stripeColors[stripe] = currentColor;
        }

        // All three stripes must have distinct colors
        return stripeColors[0] != stripeColors[1] &&
               stripeColors[1] != stripeColors[2] &&
               stripeColors[0] != stripeColors[2];
    }
}

import java.io.BufferedReader;
