import java.util.HashSet;
import java.util.Set;
import java.util.StringTokenizer;

public class q5 {

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            int n = scanner.nextInt();
            int m = scanner.nextInt();

            char[][] grid = new char[n][m];
            for (int i = 0; i < n; i++) {
                grid[i] = scanner.next().toCharArray();
            }

            boolean isValid = false;

            // Check for valid horizontal stripes
            if (n % 3 == 0) {
                isValid = checkStripes(grid, n, m, true);
            }

            // Check for valid vertical stripes if horizontal check failed
            if (!isValid && m % 3 == 0) {
                isValid = checkStripes(grid, n, m, false);
            }

            out.println(isValid ? "YES" : "NO");
        } catch (Exception e) {
            // Graceful fallback for unexpected input or parsing errors
            out.println("NO");
        } finally {
            out.flush();
        }
    }

    /**
     * Checks if the grid contains three contiguous stripes of uniform color.
     *
     * @param grid       The character grid
     * @param n          Number of rows
     * @param m          Number of columns
     * @param horizontal true to check horizontal stripes, false for vertical
     * @return true if three distinct uniform stripes are found, false otherwise
     */
    private static boolean checkStripes(char[][] grid, int n, int m, boolean horizontal) {
        Set<Character> colors = new HashSet<>();
        int blockSize = horizontal ? n / 3 : m / 3;

        for (int k = 0; k < 3; k++) {
            int start = k * blockSize;
            int end = (k + 1) * blockSize;
            // Determine the reference character for the current stripe
            char firstChar = horizontal ? grid[start][0] : grid[0][start];

            // Verify all cells in this stripe block match the reference character
            for (int i = start; i < end; i++) {
                for (int j = 0; j < (horizontal ? m : n); j++) {
                    char current = horizontal ? grid[i][j] : grid[j][i];
                    if (current != firstChar) {
                        return false; // Early exit on mismatch
                    }
                }
            }
            colors.add(firstChar);
        }

        // Valid only if all three stripes have different colors
        return colors.size() == 3;
    }

    /**
     * Fast input reader optimized for competitive programming and performance-critical applications.
     */
    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) {
                        return null;
                    }
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            String s = next();
            if (s == null) throw new RuntimeException("Unexpected end of input");
            return Integer.parseInt(s);
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.StringTokenizer;

public class FlagOfBerland837B {

    public static void main(String[] args) {
        FastScanner sc = new FastScanner();
        int rows = sc.nextInt();
        int cols = sc.nextInt();

        // A valid flag must have at least 3 rows and 3 columns
        if (rows < 3 || cols < 3) {
            System.out.println("NO");
            return;
        }

        // Read grid rows
        List<String> grid = new ArrayList<>(rows);
        for (int i = 0; i < rows; i++) {
            grid.add(sc.next());
        }

        // Construct grid columns efficiently using StringBuilder
        List<String> columns = new ArrayList<>(cols);
        for (int j = 0; j < cols; j++) {
            StringBuilder colBuilder = new StringBuilder(rows);
            for (int i = 0; i < rows; i++) {
                colBuilder.append(grid.get(i).charAt(j));
            }
            columns.add(colBuilder.toString());
        }

        // Check validity for both orientations
        boolean isHorizontalValid = validateUniformity(grid);
        boolean isVerticalValid = validateUniformity(columns);

        System.out.println((isHorizontalValid || isVerticalValid) ? "YES" : "NO");
    }

    /**
     * Validates if a list of strings (rows or columns) forms a valid uniform color pattern.
     * Conditions:
     * 1. Each string must contain only one unique character.
     * 2. Exactly three colors (R, G, B) must be present.
     * 3. Each color must appear the same number of times.
     * 4. Each color's occurrences must form a contiguous block.
     */
    private static boolean validateUniformity(List<String> lines) {
        int[] counts = new int[3];
        int[] minIdx = new int[3];
        int[] maxIdx = new int[3];
        Arrays.fill(minIdx, Integer.MAX_VALUE);
        Arrays.fill(maxIdx, Integer.MIN_VALUE);

        for (int i = 0; i < lines.size(); i++) {
            char type = getLineType(lines.get(i));
            if (type == 'M') {
                return false; // Mixed characters in a line
            }

            int colorIdx = getColorIndex(type);
            counts[colorIdx]++;
            minIdx[colorIdx] = Math.min(minIdx[colorIdx], i);
            maxIdx[colorIdx] = Math.max(maxIdx[colorIdx], i);
        }

        // All three colors must be present
        for (int count : counts) {
            if (count == 0) {
                return false;
            }
        }

        // All colors must appear the same number of times
        int baseCount = counts[0];
        for (int count : counts) {
            if (count != baseCount) {
                return false;
            }
        }

        // Each color must occupy a contiguous range of indices
        for (int c = 0; c < 3; c++) {
            if ((maxIdx[c] - minIdx[c]) != (counts[c] - 1)) {
                return false;
            }
        }

        return true;
    }

    /**
     * Determines if a line contains only one repeated character.
     * Returns the character if uniform, or 'M' (Mixed) if not.
     */
    private static char getLineType(String line) {
        if (line.isEmpty()) {
            return 'M';
        }
        char first = line.charAt(0);
        for (int i = 1; i < line.length(); i++) {
            if (line.charAt(i) != first) {
                return 'M';
            }
        }
        return first;
    }

    /**
     * Maps color characters to array indices.
     */
    private static int getColorIndex(char color) {
        switch (color) {
            case 'R': return 0;
            case 'G': return 1;
            case 'B': return 2;
            default: return -1;
        }
    }

    /**
     * Fast I/O helper class to handle large inputs efficiently.
     */
    private static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) {
                        return null;
                    }
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            String s = next();
            if (s == null) {
                throw new RuntimeException("Unexpected end of input");
            }
            return Integer.parseInt(s);
        }
    }
}

