class Solver {
    /**
     * Processes a single test case.
     * Reads grid dimensions and content, then checks for valid horizontal or vertical stripes.
     */
    void solve(int testNumber, FastScanner in, PrintWriter out) {
        int rows = in.nextInt();
        int cols = in.nextInt();
        char[][] grid = new char[rows][cols];

        for (int i = 0; i < rows; i++) {
            String line = in.next();
            grid[i] = line.toCharArray();
        }

        boolean horizontalValid = hasThreeDistinctStripes(grid, true);
        boolean verticalValid = hasThreeDistinctStripes(grid, false);

        out.println(horizontalValid || verticalValid ? "YES" : "NO");
    }

    /**
     * Checks if the grid consists of three equal-sized stripes (horizontal or vertical)
     * where each stripe is a solid color and all three stripes have distinct colors.
     *
     * @param grid       The character grid representing the board.
     * @param horizontal True to check horizontal stripes, false for vertical.
     * @return True if the grid satisfies the condition, false otherwise.
     */
    private boolean hasThreeDistinctStripes(char[][] grid, boolean horizontal) {
        int dim = horizontal ? grid.length : grid[0].length;
        if (dim % 3 != 0) {
            return false;
        }

        int stripeSize = dim / 3;
        char[] stripeColors = new char[3];

        for (int k = 0; k < 3; k++) {
            int start = k * stripeSize;
            // Reference cell for the current stripe
            char refColor = horizontal ? grid[start][0] : grid[0][start];
            stripeColors[k] = refColor;

            // Validate all cells in the current stripe match the reference color
            for (int i = start; i < start + stripeSize; i++) {
                for (int j = 0; j < grid[0].length; j++) {
                    if (horizontal) {
                        if (grid[i][j] != refColor) {
                            return false;
                        }
                    } else {
                        if (grid[j][i] != refColor) {
                            return false;
                        }
                    }
                }
            }

            // Adjacent stripes must have different colors
            if (k > 0 && stripeColors[k] == stripeColors[k - 1]) {
                return false;
            }
        }

        return true;
    }
}

/**
 * A robust, high-performance scanner for competitive programming and fast I/O.
 * Replaces the original InputReader with proper exception handling and token management.
 */
class FastScanner {
    private BufferedReader br;
    private StringTokenizer st;

    public FastScanner() {
        br = new BufferedReader(new InputStreamReader(System.in));
    }

    public boolean hasNext() {
        while (st == null || !st.hasMoreTokens()) {
            try {
                String line = br.readLine();
                if (line == null) {
                    return false;
                }
                st = new StringTokenizer(line);
            } catch (IOException e) {
                throw new RuntimeException("Failed to read input", e);
            }
        }
        return true;
    }

    public String next() {
        if (hasNext()) {
            return st.nextToken();
        }
        throw new NoSuchElementException("No more tokens available");
    }

    public int nextInt() {
        return Integer.parseInt(next());
    }
}

