public class Main {
    public static void main(String[] args) {
        FastScanner scanner = new FastScanner();
        PrintWriter out = new PrintWriter(System.out);
        solve(scanner, out);
        out.close();
    }

    private static void solve(FastScanner scanner, PrintWriter out) {
        int n = scanner.nextInt();
        int m = scanner.nextInt();
        char[][] grid = new char[n][m];
        for (int i = 0; i < n; i++) {
            grid[i] = scanner.next().toCharArray();
        }

        boolean isFlag = checkStripes(grid, n, m, true) || checkStripes(grid, n, m, false);
        out.println(isFlag ? "YES" : "NO");
    }

    /**
     * Checks if the grid forms a flag with three equal-width/height stripes of distinct colors.
     *
     * @param grid      The character grid representing the flag.
     * @param rows      Number of rows in the grid.
     * @param cols      Number of columns in the grid.
     * @param horizontal If true, checks for horizontal stripes; otherwise checks vertical stripes.
     * @return true if the grid matches the flag pattern, false otherwise.
     */
    private static boolean checkStripes(char[][] grid, int rows, int cols, boolean horizontal) {
        int size = horizontal ? rows : cols;
        if (size % 3 != 0) {
            return false;
        }

        int third = size / 3;
        char c1, c2, c3;
        if (horizontal) {
            c1 = grid[0][0];
            c2 = grid[third][0];
            c3 = grid[2 * third][0];
        } else {
            c1 = grid[0][0];
            c2 = grid[0][third];
            c3 = grid[0][2 * third];
        }

        // All three stripe colors must be distinct
        if (c1 == c2 || c2 == c3 || c1 == c3) {
            return false;
        }

        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                char expected;
                if (horizontal) {
                    int stripe = i / third;
                    expected = (stripe == 0) ? c1 : (stripe == 1) ? c2 : c3;
                } else {
                    int stripe = j / third;
                    expected = (stripe == 0) ? c1 : (stripe == 1) ? c2 : c3;
                }
                if (grid[i][j] != expected) {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Fast input reader using BufferedReader and StringTokenizer for maintainability
     * and performance without low-level byte manipulation.
     */
    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        public String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) {
                        return null;
                    }
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            String s = next();
            if (s == null) {
                throw new RuntimeException("Unexpected end of input");
            }
            return Integer.parseInt(s);
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

/**
 * Analyzes a character grid to determine if it can be divided into three 
 * equal uniform color bands either horizontally or vertically.
 */
public class ColorGridAnalyzer {

    private static final char COLOR_BLUE = 'B';
    private static final char COLOR_RED = 'R';
    private static final char COLOR_GREEN = 'G';

    public static void main(String[] args) throws IOException {
        BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter out = new PrintWriter(System.out);

        String line;
        while ((line = in.readLine()) != null && !line.trim().isEmpty()) {
            StringTokenizer tokenizer = new StringTokenizer(line);
            if (!tokenizer.hasMoreTokens()) continue;

            int rows = Integer.parseInt(tokenizer.nextToken());
            int cols = Integer.parseInt(tokenizer.nextToken());

            char[][] grid = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                String rowStr = in.readLine();
                if (rowStr != null) {
                    for (int j = 0; j < cols && j < rowStr.length(); j++) {
                        grid[i][j] = rowStr.charAt(j);
                    }
                }
            }

            boolean horizontalValid = evaluateGrid(grid, rows, cols, true);
            boolean verticalValid = evaluateGrid(grid, rows, cols, false);

            out.print((horizontalValid || verticalValid) ? "YES" : "NO");
            out.println();
        }
        out.flush();
        out.close();
    }

    /**
     * Evaluates if the grid meets the uniform color band condition along rows or columns.
     *
     * @param grid      The character matrix to analyze
     * @param dim1      The dimension to iterate over (rows for horizontal, cols for vertical)
     * @param dim2      The other dimension (used for inner checks)
     * @param horizontal True to check horizontal bands, false for vertical
     * @return True if the condition is met, false otherwise
     */
    private static boolean evaluateGrid(char[][] grid, int dim1, int dim2, boolean horizontal) {
        int[] counts = getUniformSequenceCounts(grid, horizontal);
        int blueCount = counts[0];
        int redCount = counts[1];
        int greenCount = counts[2];

        // Original condition: (B==R && R==G && G!=0 && ((dim1/(dim1/G))*3==dim1))
        // Simplified to: All three colors appear exactly dim1/3 times as uniform sequences.
        // This ensures the grid is perfectly divided into 3 equal parts of the same color.
        return (blueCount == redCount && redCount == greenCount
                && greenCount > 0
                && dim1 == 3 * greenCount);
    }

    /**
     * Scans rows or columns to count uniform color sequences.
     * Returns an array where index 0 is Blue, 1 is Red, 2 is Green.
     */
    private static int[] getUniformSequenceCounts(char[][] grid, boolean horizontal) {
        int[] counts = new int[3];
        char prevColor = '.';
        int currentRun = 0;
        int limit = horizontal ? grid.length : grid[0].length;

        for (int i = 0; i < limit; i++) {
            char color;
            boolean isUniform = isUniformSequence(grid, i, horizontal);
            color = isUniform ? (horizontal ? grid[i][0] : grid[0][i]) : '.';

            if (isUniform) {
                if (prevColor == '.' || prevColor == color) {
                    currentRun++;
                } else {
                    applySequenceCount(prevColor, currentRun, counts);
                    currentRun = 1;
                }
                prevColor = color;
            } else {
                applySequenceCount(prevColor, currentRun, counts);
                currentRun = 0;
                prevColor = '.';
            }
        }
        applySequenceCount(prevColor, currentRun, counts);
        return counts;
    }

    /**
     * Checks if a specific row or column consists of identical characters.
     */
    private static boolean isUniformSequence(char[][] grid, int index, boolean horizontal) {
        char firstChar = horizontal ? grid[index][0] : grid[0][index];
        int length = horizontal ? grid[index].length : grid.length;
        for (int i = 1; i < length; i++) {
            char currentChar = horizontal ? grid[index][i] : grid[i][index];
            if (currentChar != firstChar) {
                return false;
            }
        }
        return true;
    }

    /**
     * Updates the count for a specific color based on the original algorithm's logic:
     * If the count is 0, set it to the run length. Otherwise, reset to 0.
     * This preserves the original behavior of capturing only the first occurrence of each color's sequence.
     */
    private static void applySequenceCount(char color, int run, int[] counts) {
        if (run == 0) return;
        int colorIndex = getColorIndex(color);
        if (colorIndex != -1) {
            counts[colorIndex] = (counts[colorIndex] == 0) ? run : 0;
        }
    }

    private static int getColorIndex(char color) {
        if (color == COLOR_BLUE) return 0;
        if (color == COLOR_RED) return 1;
        if (color == COLOR_GREEN) return 2;
        return -1;
    }
}

import java.util.Scanner;

/**
 * Main class to determine if a grid of characters can be partitioned into 
 * three equal sections of uniform characters, either horizontally or vertically.
 */
public class Main {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        // Read dimensions n (rows) and m (columns)
        if (!scanner.hasNextInt()) {
            scanner.close();
            return;
        }
        int n = scanner.nextInt();
        int m = scanner.nextInt();

        // Read the grid data
        String[] grid = new String[n];
        for (int i = 0; i < n; i++) {
            grid[i] = scanner.next();
        }

        // Solve the problem and print the result
        boolean isPossible = solve(n, m, grid);
        System.out.println(isPossible ? "YES" : "NO");

        scanner.close();
    }

    /**
     * Orchestrates the checking logic. Returns true if the grid can be 
     * partitioned into 3 uniform sections either horizontally or vertically.
     */
    private static boolean solve(int n, int m, String[] grid) {
        // Check horizontal partition first
        if (checkHorizontal(n, m, grid)) {
            return true;
        }

        // Check vertical partition only if horizontal check failed
        // (Logic preserved from original: if rows work, we don't need to check cols)
        if (checkVertical(n, m, grid)) {
            return true;
        }

        return false;
    }

    /**
     * Checks if the grid can be divided into 3 horizontal strips of equal height.
     * Each strip must consist of a single distinct character.
     */
    private static boolean checkHorizontal(int n, int m, String[] grid) {
        if (n % 3 != 0) {
            return false;
        }

        int blockHeight = n / 3;

        // Identify the required characters for each block based on the first row of the block
        char char1 = grid[0].charAt(0);
        char char2 = grid[blockHeight].charAt(0);
        char char3 = grid[2 * blockHeight].charAt(0);

        // Characters must be distinct for a valid partition
        if (char1 == char2 || char1 == char3 || char2 == char3) {
            return false;
        }

        // Verify Block 1 (Rows 0 to blockHeight-1)
        for (int i = 0; i < blockHeight; i++) {
            if (!isUniform(grid[i], char1)) {
                return false;
            }
        }

        // Verify Block 2 (Rows blockHeight to 2*blockHeight-1)
        for (int i = blockHeight; i < 2 * blockHeight; i++) {
            if (!isUniform(grid[i], char2)) {
                return false;
            }
        }

        // Verify Block 3 (Rows 2*blockHeight to 3*blockHeight-1)
        for (int i = 2 * blockHeight; i < 3 * blockHeight; i++) {
            if (!isUniform(grid[i], char3)) {
                return false;
            }
        }

        return true;
    }

    /**
     * Checks if the grid can be divided into 3 vertical strips of equal width.
     * Each strip must consist of a single distinct character.
     */
    private static boolean checkVertical(int n, int m, String[] grid) {
        if (m % 3 != 0) {
            return false;
        }

        int blockWidth = m / 3;

        // Identify the required characters for each block based on the first column of the block
        char char1 = grid[0].charAt(0);
        char char2 = grid[0].charAt(blockWidth);
        char char3 = grid[0].charAt(2 * blockWidth);

        // Characters must be distinct for a valid partition
        if (char1 == char2 || char1 == char3 || char2 == char3) {
            return false;
        }

        // Iterate through every row to check column segments
        for (int i = 0; i < n; i++) {
            String row = grid[i];

            // Check Block 1 (Cols 0 to blockWidth-1)
            if (!isSubstringUniform(row, 0, blockWidth, char1)) {
                return false;
            }

            // Check Block 2 (Cols blockWidth to 2*blockWidth-1)
            if (!isSubstringUniform(row, blockWidth, 2 * blockWidth, char2)) {
                return false;
            }

            // Check Block 3 (Cols 2*blockWidth to 3*blockWidth-1)
            if (!isSubstringUniform(row, 2 * blockWidth, 3 * blockWidth, char3)) {
                return false;
            }
        }

        return true;
    }

    /**
     * Checks if a string consists entirely of a specific character.
     */
    private static boolean isUniform(String str, char target) {
        for (int k = 0; k < str.length(); k++) {
            if (str.charAt(k) != target) {
                return false;
            }
        }
        return true;
    }

    /**
     * Checks if a substring of a string (from start inclusive to end exclusive)
     * consists entirely of a specific character.
     */
    private static boolean isSubstringUniform(String str, int start, int end, char target) {
        for (int k = start; k < end; k++) {
            if (str.charAt(k) != target) {
                return false;
            }
        }
        return true;
    }
}

import java.util.Scanner;

public class FlagChecker {

    public static void main(String[] args) {
        // Use try-with-resources to ensure the Scanner is properly closed
        try (Scanner scanner = new Scanner(System.in)) {
            if (!scanner.hasNextInt()) {
                return;
            }

            int rows = scanner.nextInt();
            int cols = scanner.nextInt();
            scanner.nextLine(); // Consume the newline character after the integers

            char[][] grid = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                grid[i] = scanner.nextLine().toCharArray();
            }

            boolean isRowFlag = checkRowPattern(grid, rows, cols);
            boolean isColFlag = checkColPattern(grid, rows, cols);

            System.out.println(isRowFlag || isColFlag ? "YES" : "NO");
        }
    }

    /**
     * Checks if the grid forms a flag pattern with three horizontal stripes 
     * of equal height and different colors.
     */
    private static boolean checkRowPattern(char[][] grid, int rows, int cols) {
        if (rows % 3 != 0) {
            return false;
        }

        int third = rows / 3;

        // Validate each horizontal third has a uniform color
        char color1 = getUniformColor(grid, 0, 0, third, cols);
        if (color1 == '\0') return false;

        char color2 = getUniformColor(grid, third, 0, third, cols);
        if (color2 == '\0') return false;

        char color3 = getUniformColor(grid, third * 2, 0, third, cols);
        if (color3 == '\0') return false;

        // All three colors must be distinct
        return color1 != color2 && color1 != color3 && color2 != color3;
    }

    /**
     * Checks if the grid forms a flag pattern with three vertical stripes 
     * of equal width and different colors.
     */
    private static boolean checkColPattern(char[][] grid, int rows, int cols) {
        if (cols % 3 != 0) {
            return false;
        }

        int third = cols / 3;

        // Validate each vertical third has a uniform color
        char color1 = getUniformColor(grid, 0, 0, rows, third);
        if (color1 == '\0') return false;

        char color2 = getUniformColor(grid, 0, third, rows, third);
        if (color2 == '\0') return false;

        char color3 = getUniformColor(grid, 0, third * 2, rows, third);
        if (color3 == '\0') return false;

        // All three colors must be distinct
        return color1 != color2 && color1 != color3 && color2 != color3;
    }

    /**
     * Verifies if a rectangular region in the grid is uniform (all characters match).
     * Returns the character if uniform, otherwise returns '\0'.
     *
     * @param grid The 2D character array
     * @param startRow Starting row index (inclusive)
     * @param startCol Starting column index (inclusive)
     * @param height   Number of rows to check
     * @param width    Number of columns to check
     * @return The uniform character, or '\0' if not uniform
     */
    private static char getUniformColor(char[][] grid, int startRow, int startCol, int height, int width) {
        if (height <= 0 || width <= 0) {
            return '\0';
        }

        char target = grid[startRow][startCol];
        for (int i = 0; i < height; i++) {
            for (int j = 0; j < width; j++) {
                if (grid[startRow + i][startCol + j] != target) {
                    return '\0';
                }
            }
        }
        return target;
    }
}

import java.util.Scanner;

public class Main {
    // Constants replace magic numbers for clarity and easy future modifications
    private static final int BLOCK_COUNT = 3;
    private static final char[] COLORS = {'R', 'G', 'B'};

    public static void main(String[] args) {
        // try-with-resources ensures the Scanner is closed automatically
        try (Scanner scanner = new Scanner(System.in)) {
            if (!scanner.hasNextInt()) {
                return;
            }
            int n = scanner.nextInt();
            int m = scanner.nextInt();

            // Early exit for invalid dimensions
            if (n == 0 || m == 0) {
                System.out.println("NO");
                return;
            }

            String[] gridRows = new String[n];
            for (int i = 0; i < n; i++) {
                gridRows[i] = scanner.next();
            }

            // Extract complex transformations and pattern generation into dedicated methods
            String[] gridCols = transpose(gridRows);
            String[] rowPatterns = generatePatterns(m);
            String[] colPatterns = generatePatterns(n);

            // Simplified condition evaluation
            if (isValid(gridRows, rowPatterns) || isValid(gridCols, colPatterns)) {
                System.out.println("YES");
            } else {
                System.out.println("NO");
            }
        }
    }

    /**
     * Transposes the 2D grid represented as an array of strings.
     * Rows become columns and vice versa.
     */
    private static String[] transpose(String[] rows) {
        if (rows.length == 0) {
            return new String[0];
        }
        int m = rows[0].length();
        String[] cols = new String[m];
        for (int i = 0; i < m; i++) {
            StringBuilder sb = new StringBuilder(rows.length);
            for (String row : rows) {
                sb.append(row.charAt(i));
            }
            cols[i] = sb.toString();
        }
        return cols;
    }

    /**
     * Generates the three expected patterns (all 'R', all 'G', all 'B') for a given length.
     */
    private static String[] generatePatterns(int length) {
        String[] patterns = new String[BLOCK_COUNT];
        for (int i = 0; i < BLOCK_COUNT; i++) {
            char c = COLORS[i];
            StringBuilder sb = new StringBuilder(length);
            for (int j = 0; j < length; j++) {
                sb.append(c);
            }
            patterns[i] = sb.toString();
        }
        return patterns;
    }

    /**
     * Validates whether an array of strings satisfies the problem constraints:
     * 1. Length is divisible by 3
     * 2. The first string of each block matches one of the expected patterns
     * 3. The first characters of the three block representatives are distinct
     * 4. All strings within each block are identical to their block's representative
     */
    private static boolean isValid(String[] array, String[] patterns) {
        if (array.length == 0 || array.length % BLOCK_COUNT != 0) {
            return false;
        }

        int blockSize = array.length / BLOCK_COUNT;
        if (blockSize == 0) {
            return false; // Prevents index out of bounds on empty blocks
        }

        int[] blockStarts = {0, blockSize, blockSize * 2};
        char[] startChars = new char[BLOCK_COUNT];

        // 1. Verify block representatives match patterns and capture their first characters
        for (int i = 0; i < BLOCK_COUNT; i++) {
            String rep = array[blockStarts[i]];
            boolean matchesPattern = false;
            for (String p : patterns) {
                if (rep.equals(p)) {
                    matchesPattern = true;
                    break;
                }
            }
            if (!matchesPattern) {
                return false;
            }
            startChars[i] = rep.charAt(0);
        }

        // 2. Ensure the first characters of the three blocks are distinct
        for (int i = 0; i < BLOCK_COUNT; i++) {
            for (int j = i + 1; j < BLOCK_COUNT; j++) {
                if (startChars[i] == startChars[j]) {
                    return false;
                }
            }
        }

        // 3. Verify all strings within each block match the block's representative
        for (int i = 0; i < BLOCK_COUNT; i++) {
            String rep = array[blockStarts[i]];
            for (int k = blockStarts[i]; k < blockStarts[i] + blockSize; k++) {
                if (!array[k].equals(rep)) {
                    return false;
                }
            }
        }

        return true;
    }
}

import java.util.Scanner;

public class Main {

    public static void main(String[] args) {
        // Use try-with-resources to ensure the Scanner is properly closed
        try (Scanner scanner = new Scanner(System.in)) {
            if (!scanner.hasNextInt()) return;

            int n = scanner.nextInt();
            int m = scanner.nextInt();

            char[][] grid = new char[n][m];
            for (int i = 0; i < n; i++) {
                String row = scanner.next();
                grid[i] = row.toCharArray();
            }

            // The grid is valid if it forms either 3 horizontal stripes or 3 vertical stripes
            boolean isValid = checkHorizontalStripes(grid, n, m) || checkVerticalStripes(grid, n, m);
            System.out.println(isValid ? "YES" : "NO");
        }
    }

    /**
     * Checks if the grid consists of three horizontal stripes of equal height,
     * each filled with a uniform character. The first and third stripe characters must differ.
     */
    private static boolean checkHorizontalStripes(char[][] grid, int n, int m) {
        if (n % 3 != 0) {
            return false;
        }

        int stripeHeight = n / 3;

        char c1 = grid[0][0];
        if (!isUniformBlock(grid, 0, 0, stripeHeight, m, c1)) {
            return false;
        }

        char c2 = grid[stripeHeight][0];
        if (!isUniformBlock(grid, stripeHeight, 0, stripeHeight, m, c2)) {
            return false;
        }

        char c3 = grid[2 * stripeHeight][0];
        if (!isUniformBlock(grid, 2 * stripeHeight, 0, stripeHeight, m, c3)) {
            return false;
        }

        // Original logic only enforces that the first and last stripe characters differ
        return c1 != c3;
    }

    /**
     * Checks if the grid consists of three vertical stripes of equal width,
     * each filled with a uniform character. The first and third stripe characters must differ.
     */
    private static boolean checkVerticalStripes(char[][] grid, int n, int m) {
        if (m % 3 != 0) {
            return false;
        }

        int stripeWidth = m / 3;

        char c1 = grid[0][0];
        if (!isUniformBlock(grid, 0, 0, n, stripeWidth, c1)) {
            return false;
        }

        char c2 = grid[0][stripeWidth];
        if (!isUniformBlock(grid, 0, stripeWidth, n, stripeWidth, c2)) {
            return false;
        }

        char c3 = grid[0][2 * stripeWidth];
        if (!isUniformBlock(grid, 0, 2 * stripeWidth, n, stripeWidth, c3)) {
            return false;
        }

        return c1 != c3;
    }

    /**
     * Verifies if a rectangular block in the grid contains only the target character.
     *
     * @param grid       The 2D character array
     * @param startRow   Starting row index (inclusive)
     * @param startCol   Starting column index (inclusive)
     * @param height     Number of rows in the block
     * @param width      Number of columns in the block
     * @param targetChar The character to check for uniformity
     * @return true if all cells in the block match targetChar, false otherwise
     */
    private static boolean isUniformBlock(char[][] grid, int startRow, int startCol, int height, int width, char targetChar) {
        for (int i = startRow; i < startRow + height; i++) {
            for (int j = startCol; j < startCol + width; j++) {
                if (grid[i][j] != targetChar) {
                    return false;
                }
            }
        }
        return true;
    }
}

import java.io.InputStream;
import java.io.OutputStream;
import java.io.IOException;
import java.io.PrintWriter;
import java.util.InputMismatchException;

public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        TaskB solver = new TaskB();
        solver.solve(1, in, out);
        out.close();
    }

    static class TaskB {
        private static final int THREE = 3;

        public void solve(int testNumber, InputReader sc, PrintWriter w) {
            int n = sc.nextInt();
            int m = sc.nextInt();
            char[][] grid = new char[n][m];
            int rCount = 0, bCount = 0, gCount = 0;

            // Read grid and count character frequencies in a single pass
            for (int i = 0; i < n; i++) {
                String row = sc.next();
                grid[i] = row.toCharArray();
                for (char ch : grid[i]) {
                    if (ch == 'R') rCount++;
                    else if (ch == 'B') bCount++;
                    else if (ch == 'G') gCount++;
                }
            }

            int totalCells = n * m;
            // If total cells aren't divisible by 3 or counts aren't equal, it's impossible
            if (totalCells % THREE != 0 || rCount != bCount || bCount != gCount) {
                w.println("NO");
                return;
            }

            int req = totalCells / THREE;

            // Check if the grid can be split into horizontal strips
            if (req % m == 0) {
                int blockRows = req / m;
                if (canSplitIntoHorizontalStrips(grid, n, m, blockRows, req)) {
                    w.println("YES");
                    return;
                }
            }

            // Check if the grid can be split into vertical strips
            if (req % n == 0) {
                int blockCols = req / n;
                if (canSplitIntoVerticalStrips(grid, n, m, blockCols, req)) {
                    w.println("YES");
                    return;
                }
            }

            w.println("NO");
        }

        private boolean canSplitIntoHorizontalStrips(char[][] grid, int n, int m, int blockRows, int req) {
            int targetCount = blockRows * m;
            char expected1 = grid[0][0];
            char expected2 = grid[blockRows][0];
            char expected3 = grid[2 * blockRows][0];

            return countMatchingCells(grid, 0, blockRows, 0, m, expected1) == targetCount &&
                   countMatchingCells(grid, blockRows, 2 * blockRows, 0, m, expected2) == targetCount &&
                   countMatchingCells(grid, 2 * blockRows, n, 0, m, expected3) == targetCount;
        }

        private boolean canSplitIntoVerticalStrips(char[][] grid, int n, int m, int blockCols, int req) {
            int targetCount = blockCols * n;
            char expected1 = grid[0][0];
            char expected2 = grid[0][blockCols];
            char expected3 = grid[0][2 * blockCols];

            return countMatchingCells(grid, 0, n, 0, blockCols, expected1) == targetCount &&
                   countMatchingCells(grid, 0, n, blockCols, 2 * blockCols, expected2) == targetCount &&
                   countMatchingCells(grid, 0, n, 2 * blockCols, m, expected3) == targetCount;
        }

        private int countMatchingCells(char[][] grid, int rStart, int rEnd, int cStart, int cEnd, char target) {
            int count = 0;
            for (int r = rStart; r < rEnd; r++) {
                for (int c = cStart; c < cEnd; c++) {
                    if (grid[r][c] == target) count++;
                }
            }
            return count;
        }
    }

    static class InputReader {
        private InputStream stream;
        private byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;
        private SpaceCharFilter filter;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        public int read() {
            if (numChars == -1)
                throw new InputMismatchException();

            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }

                if (numChars <= 0)
                    return -1;
            }
            return buf[curChar++];
        }

        public int nextInt() {
            int c = read();
            while (isSpaceChar(c))
                c = read();

            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }

            int res = 0;
            do {
                if (c < '0' || c > '9')
                    throw new InputMismatchException();
                res *= 10;
                res += c - '0';
                c = read();
            } while (!isSpaceChar(c));

            return res * sgn;
        }

        public String readString() {
            int c = read();
            while (isSpaceChar(c))
                c = read();
            StringBuilder res = new StringBuilder();
            do {
                res.appendCodePoint(c);
                c = read();
            } while (!isSpaceChar(c));

            return res.toString();
        }

        public boolean isSpaceChar(int c) {
            if (filter != null)
                return filter.isSpaceChar(c);
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        public String next() {
            return readString();
        }

        public interface SpaceCharFilter {
            boolean isSpaceChar(int ch);
        }
    }
}

import java.util.Scanner;

public class FlagOfBerland {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        // Read dimensions n (rows) and m (columns)
        if (!scanner.hasNextInt()) {
            return;
        }
        int n = scanner.nextInt();
        int m = scanner.nextInt();
        scanner.nextLine(); // Consume the newline character after the integers

        // Read the grid
        char[][] grid = new char[n][m];
        for (int i = 0; i < n; i++) {
            String line = scanner.nextLine();
            grid[i] = line.toCharArray();
        }

        // Check if the grid forms a valid horizontal or vertical flag
        boolean isHorizontalFlag = checkHorizontalFlag(grid, n, m);
        boolean isVerticalFlag = checkVerticalFlag(grid, n, m);

        if (isHorizontalFlag || isVerticalFlag) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }

        scanner.close();
    }

    /**
     * Checks if the grid represents a valid horizontal flag.
     * A valid horizontal flag consists of three horizontal stripes of equal height.
     * Each stripe must be a single solid color, and all three colors must be distinct.
     */
    private static boolean checkHorizontalFlag(char[][] grid, int n, int m) {
        // If there are no rows, it cannot be a flag
        if (n == 0) return false;

        // Height must be divisible by 3
        if (n % 3 != 0) {
            return false;
        }

        int stripeHeight = n / 3;

        // Identify the colors of the three stripes
        // We pick the first character of the first row of each stripe
        char color1 = getChar(grid, 0, 0);
        char color2 = getChar(grid, stripeHeight, 0);
        char color3 = getChar(grid, 2 * stripeHeight, 0);

        // Colors must be distinct
        if (!areDistinct(color1, color2, color3)) {
            return false;
        }

        // Check if each stripe is a solid block of its respective color
        // Stripe 1: Rows 0 to stripeHeight - 1
        if (!isSolidBlock(grid, 0, stripeHeight, 0, m, color1)) {
            return false;
        }

        // Stripe 2: Rows stripeHeight to 2*stripeHeight - 1
        if (!isSolidBlock(grid, stripeHeight, 2 * stripeHeight, 0, m, color2)) {
            return false;
        }

        // Stripe 3: Rows 2*stripeHeight to 3*stripeHeight - 1
        if (!isSolidBlock(grid, 2 * stripeHeight, 3 * stripeHeight, 0, m, color3)) {
            return false;
        }

        return true;
    }

    /**
     * Checks if the grid represents a valid vertical flag.
     * A valid vertical flag consists of three vertical stripes of equal width.
     * Each stripe must be a single solid color, and all three colors must be distinct.
     */
    private static boolean checkVerticalFlag(char[][] grid, int n, int m) {
        // If there are no columns, it cannot be a flag
        if (m == 0) return false;

        // Width must be divisible by 3
        if (m % 3 != 0) {
            return false;
        }

        int stripeWidth = m / 3;

        // Identify the colors of the three stripes
        // We pick the first character of the first column of each stripe
        char color1 = getChar(grid, 0, 0);
        char color2 = getChar(grid, 0, stripeWidth);
        char color3 = getChar(grid, 0, 2 * stripeWidth);

        // Colors must be distinct
        if (!areDistinct(color1, color2, color3)) {
            return false;
        }

        // Check if each stripe is a solid block of its respective color
        // Stripe 1: Cols 0 to stripeWidth - 1
        if (!isSolidBlock(grid, 0, n, 0, stripeWidth, color1)) {
            return false;
        }

        // Stripe 2: Cols stripeWidth to 2*stripeWidth - 1
        if (!isSolidBlock(grid, 0, n, stripeWidth, 2 * stripeWidth, color2)) {
            return false;
        }

        // Stripe 3: Cols 2*stripeWidth to 3*stripeWidth - 1
        if (!isSolidBlock(grid, 0, n, 2 * stripeWidth, 3 * stripeWidth, color3)) {
            return false;
        }

        return true;
    }

    /**
     * Checks if a rectangular block in the grid is filled with a specific color.
     * 
     * @param grid The 2D character array
     * @param rStart Start row index (inclusive)
     * @param rEnd   End row index (exclusive)
     * @param cStart Start column index (inclusive)
     * @param cEnd   End column index (exclusive)
     * @param color  The expected color for the block
     * @return true if the block is solid, false otherwise
     */
    private static boolean isSolidBlock(char[][] grid, int rStart, int rEnd, int cStart, int cEnd, char color) {
        // Safety check for array bounds
        if (rStart >= grid.length || cStart >= grid[0].length) {
            return false;
        }

        for (int r = rStart; r < rEnd; r++) {
            // Check if the row is long enough
            if (cEnd > grid[r].length) {
                return false;
            }

            for (int c = cStart; c < cEnd; c++) {
                if (grid[r][c] != color) {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Helper to safely get a character from the grid.
     */
    private static char getChar(char[][] grid, int r, int c) {
        if (r >= grid.length || c >= grid[0].length) {
            return 0; // Should not happen with valid logic checks
        }
        return grid[r][c];
    }

    /**
     * Checks if three characters are all distinct from each other.
     */
    private static boolean areDistinct(char c1, char c2, char c3) {
        return c1 != c2 && c2 != c3 && c1 != c3;
    }
}

import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) {
        ConsoleIO io = new ConsoleIO(new InputStreamReader(System.in), new PrintWriter(System.out));
        new Main(io).solve();
        io.close();
    }

    private final ConsoleIO io;

    public Main(ConsoleIO io) {
        this.io = io;
    }

    /**
     * Entry point for problem solving.
     * Reads dimensions and grid, then checks for valid horizontal or vertical stripe patterns.
     */
    public void solve() {
        int[] dims = io.readIntArray();
        if (dims.length < 2) return;

        int n = dims[0];
        int m = dims[1];

        char[][] grid = new char[n][];
        for (int i = 0; i < n; i++) {
            String line = io.readLine();
            grid[i] = (line != null) ? line.trim().toCharArray() : new char[0];
        }

        // If either horizontal or vertical pattern matches, output YES
        if (checkHorizontal(grid, n, m) || checkVertical(grid, n, m)) {
            io.writeLine("YES");
        } else {
            io.writeLine("NO");
        }
    }

    /**
     * Checks if the grid is partitioned into 3 horizontal uniform bands
     * with distinct identifier characters in the first column.
     * 
     * Complexity: O(n * m) compared to original O(n^2 * m)
     */
    private boolean checkHorizontal(char[][] grid, int n, int m) {
        if (n % 3 != 0 || n < 3 || m < 1) return false;
        int t = n / 3;

        char top = grid[0][0];
        char mid = grid[t][0];
        char bot = grid[2 * t][0];

        // The three bands must have distinct characters in the first column
        if (top == mid || mid == bot || top == bot) return false;

        // Every cell must match its band's identifier character
        for (int i = 0; i < n; i++) {
            char expected = grid[i / t][0];
            for (int j = 0; j < m; j++) {
                if (grid[i][j] != expected) return false;
            }
        }
        return true;
    }

    /**
     * Checks if the grid is partitioned into 3 vertical uniform bands
     * with distinct identifier characters in the first row.
     * 
     * Complexity: O(n * m) compared to original O(n * m^2)
     */
    private boolean checkVertical(char[][] grid, int n, int m) {
        if (m % 3 != 0 || m < 3 || n < 1) return false;
        int t = m / 3;

        char left = grid[0][0];
        char center = grid[0][t];
        char right = grid[0][2 * t];

        // The three bands must have distinct characters in the first row
        if (left == center || center == right || left == right) return false;

        // Every cell must match its band's identifier character
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                char expected = grid[0][j / t];
                if (grid[i][j] != expected) return false;
            }
        }
        return true;
    }
}

/**
 * Simplified and cleaned I/O helper class.
 * Removed unused methods and redundant parsing logic to improve maintainability.
 * Uses standard BufferedReader/PrintWriter pattern for competitive programming.
 */
class ConsoleIO {
    private final BufferedReader br;
    private final PrintWriter out;

    public ConsoleIO(Reader reader, PrintWriter writer) {
        this.br = new BufferedReader(reader);
        this.out = writer;
    }

    public void flush() { out.flush(); }
    public void close() { out.close(); }
    public void writeLine(String s) { out.println(s); }
    public void writeInt(int a) { out.print(a); out.print(' '); }

    public String readLine() {
        try { return br.readLine(); } catch (IOException e) { return ""; }
    }

    public int[] readIntArray() {
        String line = readLine();
        if (line == null || line.trim().isEmpty()) return new int[0];
        String[] tokens = line.trim().split("\\s+");
        int[] result = new int[tokens.length];
        for (int i = 0; i < tokens.length; i++) {
            result[i] = Integer.parseInt(tokens[i]);
        }
        return result;
    }
}

import java.util.Scanner;

public class BEdu {
    public static void main(String[] args) {
        // Use try-with-resources for automatic resource management
        try (Scanner scanner = new Scanner(System.in)) {
            if (!scanner.hasNextInt()) return;

            int n = scanner.nextInt();
            int m = scanner.nextInt();
            String[] grid = new String[n];

            // Read the grid. Using next() avoids common nextLine() newline-consumption bugs.
            for (int i = 0; i < n; i++) {
                grid[i] = scanner.next();
            }

            boolean rowsConditionMet = checkRows(grid, n, m);
            boolean colsConditionMet = checkColumns(grid, n, m);

            System.out.println((rowsConditionMet || colsConditionMet) ? "YES" : "NO");
        }
    }

    /**
     * Checks if all rows are monochromatic, have equal counts of R, G, B,
     * and are grouped contiguously by color.
     */
    private static boolean checkRows(String[] grid, int n, int m) {
        if (n % 3 != 0) return false;
        int expectedBlockLength = n / 3;
        int rCount = 0, gCount = 0, bCount = 0;
        char currentColor = 0;
        int consecutiveCount = 0;

        for (String row : grid) {
            char rowColor = row.charAt(0);

            // Verify row uniformity
            for (int j = 1; j < m; j++) {
                if (row.charAt(j) != rowColor) {
                    return false;
                }
            }

            if (currentColor == 0) {
                currentColor = rowColor;
            }

            if (rowColor == currentColor) {
                consecutiveCount++;
            } else {
                // Color changed: verify previous block size
                if (consecutiveCount != expectedBlockLength) return false;
                currentColor = rowColor;
                consecutiveCount = 1;
            }

            switch (rowColor) {
                case 'R': rCount++; break;
                case 'G': gCount++; break;
                case 'B': bCount++; break;
            }
        }
        // Verify last block size and color counts
        return consecutiveCount == expectedBlockLength && rCount == gCount && gCount == bCount;
    }

    /**
     * Checks if all columns are monochromatic, have equal counts of R, G, B,
     * and are grouped contiguously by color.
     */
    private static boolean checkColumns(String[] grid, int n, int m) {
        if (m % 3 != 0) return false;
        int expectedBlockLength = m / 3;
        int rCount = 0, gCount = 0, bCount = 0;
        char currentColor = 0;
        int consecutiveCount = 0;

        for (int col = 0; col < m; col++) {
            char colColor = grid[0].charAt(col);

            // Verify column uniformity
            for (int row = 1; row < n; row++) {
                if (grid[row].charAt(col) != colColor) {
                    return false;
                }
            }

            if (currentColor == 0) {
                currentColor = colColor;
            }

            if (colColor == currentColor) {
                consecutiveCount++;
            } else {
                // Color changed: verify previous block size
                if (consecutiveCount != expectedBlockLength) return false;
                currentColor = colColor;
                consecutiveCount = 1;
            }

            switch (colColor) {
                case 'R': rCount++; break;
                case 'G': gCount++; break;
                case 'B': bCount++; break;
            }
        }
        // Verify last block size and color counts
        return consecutiveCount == expectedBlockLength && rCount == gCount && gCount == bCount;
    }
}

import java.util.Scanner;

/**
 * A validator for grid flags. Checks if a grid can be split into 3 horizontal
 * or 3 vertical strips of equal size, where each strip has a uniform color
 * and all three strips have distinct colors.
 */
public class FlagValidator {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        // Ensure there is input to read
        if (!scanner.hasNextInt()) {
            return;
        }

        int n = scanner.nextInt();
        int m = scanner.nextInt();

        String[] grid = new String[n];
        for (int i = 0; i < n; i++) {
            grid[i] = scanner.next();
        }

        // Check for valid horizontal split (3 horizontal bands)
        if (n % 3 == 0 && checkHorizontal(grid, n, m)) {
            System.out.println("YES");
            return;
        }

        // Check for valid vertical split (3 vertical bands)
        if (m % 3 == 0 && checkVertical(grid, n, m)) {
            System.out.println("YES");
            return;
        }

        System.out.println("NO");
    }

    /**
     * Checks if the grid can be divided into 3 horizontal strips of equal height
     * with distinct uniform colors.
     *
     * @param grid The 2D grid represented as an array of strings.
     * @param n    Number of rows.
     * @param m    Number of columns.
     * @return true if a valid horizontal split exists, false otherwise.
     */
    private static boolean checkHorizontal(String[] grid, int n, int m) {
        int h = n / 3;

        // Determine the required colors for each strip based on the first column
        char color1 = grid[0].charAt(0);
        char color2 = grid[h].charAt(0);
        char color3 = grid[2 * h].charAt(0);

        // Colors must be distinct
        if (color1 == color2 || color1 == color3 || color2 == color3) {
            return false;
        }

        // Verify the top strip (rows 0 to h-1)
        for (int r = 0; r < h; r++) {
            for (int c = 0; c < m; c++) {
                if (grid[r].charAt(c) != color1) {
                    return false;
                }
            }
        }

        // Verify the middle strip (rows h to 2h-1)
        for (int r = h; r < 2 * h; r++) {
            for (int c = 0; c < m; c++) {
                if (grid[r].charAt(c) != color2) {
                    return false;
                }
            }
        }

        // Verify the bottom strip (rows 2h to n-1)
        for (int r = 2 * h; r < n; r++) {
            for (int c = 0; c < m; c++) {
                if (grid[r].charAt(c) != color3) {
                    return false;
                }
            }
        }

        return true;
    }

    /**
     * Checks if the grid can be divided into 3 vertical strips of equal width
     * with distinct uniform colors.
     *
     * @param grid The 2D grid represented as an array of strings.
     * @param n    Number of rows.
     * @param m    Number of columns.
     * @return true if a valid vertical split exists, false otherwise.
     */
    private static boolean checkVertical(String[] grid, int n, int m) {
        int w = m / 3;

        // Determine the required colors for each strip based on the first row
        char color1 = grid[0].charAt(0);
        char color2 = grid[0].charAt(w);
        char color3 = grid[0].charAt(2 * w);

        // Colors must be distinct
        if (color1 == color2 || color1 == color3 || color2 == color3) {
            return false;
        }

        // Verify the left strip (cols 0 to w-1)
        // Using row-major iteration (r outer, c inner) is generally more cache-friendly
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < w; c++) {
                if (grid[r].charAt(c) != color1) {
                    return false;
                }
            }
        }

        // Verify the middle strip (cols w to 2w-1)
        for (int r = 0; r < n; r++) {
            for (int c = w; c < 2 * w; c++) {
                if (grid[r].charAt(c) != color2) {
                    return false;
                }
            }
        }

        // Verify the right strip (cols 2w to m-1)
        for (int r = 0; r < n; r++) {
            for (int c = 2 * w; c < m; c++) {
                if (grid[r].charAt(c) != color3) {
                    return false;
                }
            }
        }

        return true;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;

public class BerlandFlag {
    public static void main(String[] args) throws IOException {
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(System.in))) {
            String[] dimensions = reader.readLine().trim().split("\\s+");
            int rows = Integer.parseInt(dimensions[0]);
            int cols = Integer.parseInt(dimensions[1]);

            char[][] grid = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                String line = reader.readLine();
                grid[i] = (line != null) ? line.trim().toCharArray() : new char[cols];
            }

            boolean isValid = solve(rows, cols, grid);
            System.out.println(isValid ? "YES" : "NO");
        }
    }

    /**
     * Determines if the grid can be divided into three equal, uniform-color sections
     * either horizontally or vertically.
     */
    private static boolean solve(int rows, int cols, char[][] grid) {
        if (rows % 3 != 0 && cols % 3 != 0) {
            return false;
        }

        // Check both directions independently and return true if either is valid
        boolean horizontalValid = rows % 3 == 0 && checkSections(grid, rows, cols, true);
        boolean verticalValid = cols % 3 == 0 && checkSections(grid, rows, cols, false);

        return horizontalValid || verticalValid;
    }

    /**
     * Validates that the grid can be split into 3 equal sections along the specified axis,
     * where each section is uniformly filled with a single color, and all 3 sections 
     * have distinct colors.
     */
    private static boolean checkSections(char[][] grid, int rows, int cols, boolean horizontal) {
        int sectionSize = horizontal ? rows / 3 : cols / 3;
        boolean foundRed = false, foundGreen = false, foundBlue = false;

        for (int i = 0; i < 3; i++) {
            int start = i * sectionSize;
            char currentColor = horizontal ? grid[start][0] : grid[0][start];

            // Verify that every cell in this section matches the section's color
            for (int j = 0; j < sectionSize; j++) {
                int base = start + j;
                for (int k = 0; k < (horizontal ? cols : rows); k++) {
                    char cell = horizontal ? grid[base][k] : grid[k][base];
                    if (cell != currentColor) {
                        return false;
                    }
                }
            }

            // Track which colors have been found across the three sections
            if (currentColor == 'R') foundRed = true;
            else if (currentColor == 'G') foundGreen = true;
            else if (currentColor == 'B') foundBlue = true;
        }

        // All three sections must contain distinct colors
        return foundRed && foundGreen && foundBlue;
    }
}

import java.io.BufferedReader;
import java.io.BufferedWriter;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.OutputStreamWriter;
import java.io.PrintWriter;
import java.util.StringTokenizer;

public class BerlandFlag {

    public static void main(String[] args) throws IOException {
        // Use try-with-resources to ensure proper resource cleanup
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
             PrintWriter writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)))) {

            String line = reader.readLine();
            if (line == null) return;

            StringTokenizer tokenizer = new StringTokenizer(line);
            int n = Integer.parseInt(tokenizer.nextToken());
            int m = Integer.parseInt(tokenizer.nextToken());

            // A valid flag must have at least 3 rows and 3 columns to form 3 stripes
            if (n < 3 || m < 3) {
                writer.println("NO");
                return;
            }

            char[][] grid = new char[n][m];
            for (int i = 0; i < n; i++) {
                String rowStr = reader.readLine();
                if (rowStr == null || rowStr.length() != m) {
                    writer.println("NO");
                    return;
                }
                for (int j = 0; j < m; j++) {
                    char c = rowStr.charAt(j);
                    if (!isValidColor(c)) {
                        writer.println("NO");
                        return;
                    }
                    grid[i][j] = c;
                }
            }

            // Check if the grid matches either horizontal or vertical stripe pattern
            boolean isHorizontalValid = checkHorizontalStripes(grid);
            boolean isVerticalValid = checkVerticalStripes(grid);

            writer.println((isHorizontalValid || isVerticalValid) ? "YES" : "NO");
        }
    }

    private static boolean isValidColor(char c) {
        return c == 'R' || c == 'B' || c == 'G';
    }

    private static boolean checkHorizontalStripes(char[][] grid) {
        int n = grid.length;
        int m = grid[0].length;

        if (n % 3 != 0) return false;

        int stripeHeight = n / 3;
        char color1 = grid[0][0];
        char color2 = grid[stripeHeight][0];
        char color3 = grid[2 * stripeHeight][0];

        if (!areColorsDistinct(color1, color2, color3)) return false;

        return isUniformRegion(grid, color1, 0, 0, stripeHeight, m) &&
               isUniformRegion(grid, color2, stripeHeight, 0, 2 * stripeHeight, m) &&
               isUniformRegion(grid, color3, 2 * stripeHeight, 0, n, m);
    }

    private static boolean checkVerticalStripes(char[][] grid) {
        int n = grid.length;
        int m = grid[0].length;

        if (m % 3 != 0) return false;

        int stripeWidth = m / 3;
        char color1 = grid[0][0];
        char color2 = grid[0][stripeWidth];
        char color3 = grid[0][2 * stripeWidth];

        if (!areColorsDistinct(color1, color2, color3)) return false;

        return isUniformRegion(grid, color1, 0, 0, n, stripeWidth) &&
               isUniformRegion(grid, color2, 0, stripeWidth, n, 2 * stripeWidth) &&
               isUniformRegion(grid, color3, 0, 2 * stripeWidth, n, m);
    }

    private static boolean areColorsDistinct(char c1, char c2, char c3) {
        return c1 != c2 && c1 != c3 && c2 != c3;
    }

    /**
     * Checks if the rectangular region [r1, r2) x [c1, c2) is uniformly filled with targetColor.
     * Boundaries are exclusive on the upper/right side.
     */
    private static boolean isUniformRegion(char[][] grid, char targetColor, int r1, int c1, int r2, int c2) {
        for (int i = r1; i < r2; i++) {
            for (int j = c1; j < c2; j++) {
                if (grid[i][j] != targetColor) {
                    return false;
                }
            }
        }
        return true;
    }
}

import java.io.*;
import java.util.*;

public class Main {

    public static void main(String[] args) throws IOException {
        // Use try-with-resources for automatic and safe resource cleanup
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
             PrintWriter pw = new PrintWriter(new BufferedOutputStream(System.out))) {
            pw.println(solve(br));
        }
    }

    /**
     * Reads the grid and validates whether it forms exactly 3 uniform color stripes.
     *
     * @param br BufferedReader connected to standard input
     * @return "YES" if valid, "NO" otherwise
     */
    private static String solve(BufferedReader br) throws IOException {
        String line = br.readLine();
        if (line == null || line.trim().isEmpty()) {
            return "NO";
        }

        StringTokenizer st = new StringTokenizer(line);
        int n = Integer.parseInt(st.nextToken());
        int m = Integer.parseInt(st.nextToken());

        char[][] grid = new char[n][];
        for (int i = 0; i < n; i++) {
            String rowStr = br.readLine();
            // Basic validation to prevent IndexOutOfBounds on malformed input
            if (rowStr == null || rowStr.length() != m) {
                return "NO";
            }
            grid[i] = rowStr.toCharArray();
        }

        // 1. Determine dimensions of the first stripe (top-left corner)
        int stripeRowExtent = 0;
        while (stripeRowExtent < n && grid[stripeRowExtent][0] == grid[0][0]) {
            stripeRowExtent++;
        }

        int stripeColExtent = 0;
        while (stripeColExtent < m && grid[0][stripeColExtent] == grid[0][0]) {
            stripeColExtent++;
        }

        // 2. The first stripe must span the entire width OR the entire height
        boolean spansFullWidth = (stripeColExtent == m);
        boolean spansFullHeight = (stripeRowExtent == n);

        if (!spansFullWidth && !spansFullHeight) {
            return "NO";
        }

        // 3. Total area must be exactly 3 times the area of one stripe
        if ((long) stripeRowExtent * stripeColExtent * 3 != (long) n * m) {
            return "NO";
        }

        // 4. Validate color uniqueness and stripe uniformity
        Set<Character> colors = new HashSet<>();
        int step = spansFullWidth ? stripeRowExtent : stripeColExtent;
        int row = 0;
        int col = 0;

        for (int i = 0; i < 3; i++) {
            char color = grid[row][col];
            // Set.add() returns false if the element already exists
            if (!colors.add(color)) {
                return "NO"; // Duplicate color detected
            }

            // Define boundaries of the current stripe
            int endRow = spansFullWidth ? row + stripeRowExtent : row;
            int endCol = spansFullWidth ? col : col + stripeColExtent;

            // Ensure the entire stripe region matches the expected color
            for (int r = row; r < endRow; r++) {
                for (int c = col; c < endCol; c++) {
                    if (grid[r][c] != color) {
                        return "NO";
                    }
                }
            }

            // Advance to the next stripe
            row = spansFullWidth ? row + step : 0;
            col = spansFullWidth ? 0 : col + step;
        }

        return "YES";
    }
}

import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            if (!scanner.hasNextInt()) return;
            int n = scanner.nextInt();
            int m = scanner.nextInt();
            scanner.nextLine(); // Consume the newline character after the integers

            char[][] grid = new char[n][];
            for (int i = 0; i < n; i++) {
                grid[i] = scanner.nextLine().toCharArray();
            }

            ColorCounts counts = countColors(grid);
            boolean rowsUniform = areRowsUniform(grid);
            boolean colsUniform = areColsUniform(grid);

            boolean isValid = evaluate(grid, n, m, rowsUniform, colsUniform, counts);
            System.out.println(isValid ? "YES" : "NO");
        }
    }

    /**
     * Evaluates whether the grid satisfies all problem conditions.
     */
    private static boolean evaluate(char[][] grid, int n, int m, boolean rowsUniform, boolean colsUniform, ColorCounts counts) {
        boolean countsEqual = counts.r == counts.g && counts.g == counts.b;
        if (!countsEqual) {
            return false;
        }

        if (rowsUniform) {
            // When rows are uniform, check grouping along the first column
            char[] firstColumn = new char[n];
            for (int i = 0; i < n; i++) {
                firstColumn[i] = grid[i][0];
            }
            List<Integer> groups = getConsecutiveGroupSizes(firstColumn);
            return groups.size() == 3 && areAllGroupSizesEqual(groups);
        } else {
            // When rows are not uniform, columns must be uniform
            if (!colsUniform) {
                return false;
            }

            // Check grouping along the first row
            char[] firstRow = new char[m];
            for (int j = 0; j < m; j++) {
                firstRow[j] = grid[0][j];
            }
            List<Integer> groups = getConsecutiveGroupSizes(firstRow);
            return groups.size() == 3 && areAllGroupSizesEqual(groups);
        }
    }

    /**
     * Checks if every row consists of identical characters.
     */
    private static boolean areRowsUniform(char[][] grid) {
        for (char[] row : grid) {
            for (int j = 0; j < row.length - 1; j++) {
                if (row[j] != row[j + 1]) {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Checks if every column consists of identical characters.
     */
    private static boolean areColsUniform(char[][] grid) {
        int n = grid.length;
        if (n == 0) return true;
        int m = grid[0].length;

        for (int j = 0; j < m; j++) {
            for (int i = 0; i < n - 1; i++) {
                if (grid[i][j] != grid[i + 1][j]) {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Calculates the sizes of consecutive identical character groups in a line.
     */
    private static List<Integer> getConsecutiveGroupSizes(char[] line) {
        List<Integer> groups = new ArrayList<>();
        if (line.length == 0) return groups;

        int count = 1;
        for (int i = 1; i < line.length; i++) {
            if (line[i] == line[i - 1]) {
                count++;
            } else {
                groups.add(count);
                count = 1;
            }
        }
        groups.add(count);
        return groups;
    }

    /**
     * Verifies that all group sizes in the list are identical.
     */
    private static boolean areAllGroupSizesEqual(List<Integer> groups) {
        if (groups.isEmpty()) return true;
        int first = groups.get(0);
        for (int size : groups) {
            if (size != first) {
                return false;
            }
        }
        return true;
    }

    /**
     * Counts the occurrences of 'R', 'G', and 'B' across the entire grid.
     */
    private static ColorCounts countColors(char[][] grid) {
        int r = 0, g = 0, b = 0;
        for (char[] row : grid) {
            for (char c : row) {
                if (c == 'R') r++;
                else if (c == 'G') g++;
                else if (c == 'B') b++;
            }
        }
        return new ColorCounts(r, g, b);
    }

    /**
     * Simple data holder for color counts.
     */
    private static class ColorCounts {
        final int r, g, b;

        ColorCounts(int r, int g, int b) {
            this.r = r;
            this.g = g;
            this.b = b;
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

/**
 * Refactored solution for grid color pattern validation.
 * Checks if 'R', 'G', and 'B' characters form valid contiguous patterns 
 * in either row-major or column-major order.
 */
public class GridColorPatternChecker {

    public static void main(String[] args) throws IOException {
        FastReader reader = new FastReader();

        String nStr = reader.next();
        if (nStr == null) return;
        int n = Integer.parseInt(nStr);
        int m = reader.nextInt();

        char[][] grid = new char[n][];
        int countR = 0, countG = 0, countB = 0;

        // Read grid and count occurrences of each color
        for (int i = 0; i < n; i++) {
            String line = reader.next();
            grid[i] = line.toCharArray();
            for (char c : grid[i]) {
                switch (c) {
                    case 'R': countR++; break;
                    case 'G': countG++; break;
                    case 'B': countB++; break;
                }
            }
        }

        // All colors must appear exactly the same number of times
        if (countR != countG || countG != countB) {
            System.out.println("NO");
            return;
        }

        int targetCount = countR;

        // Find first occurrence coordinates for each color
        int[] rPos = findFirstOccurrence(grid, 'R');
        int[] gPos = findFirstOccurrence(grid, 'G');
        int[] bPos = findFirstOccurrence(grid, 'B');

        // Check if a valid row-based or column-based pattern exists
        boolean isValid = checkColumns(grid, rPos, gPos, bPos, targetCount) ||
                          checkRows(grid, rPos, gPos, bPos, targetCount);
        System.out.println(isValid ? "YES" : "NO");
    }

    /**
     * Finds the first occurrence of a target character in the grid.
     * @return int array {row, col} or null if not found
     */
    private static int[] findFirstOccurrence(char[][] grid, char target) {
        for (int i = 0; i < grid.length; i++) {
            for (int j = 0; j < grid[i].length; j++) {
                if (grid[i][j] == target) {
                    return new int[]{i, j};
                }
            }
        }
        return null;
    }

    /**
     * Validates row-based patterns for all colors.
     * Requires all colors to start at column 0.
     */
    private static boolean checkRows(char[][] grid, int[] rPos, int[] gPos, int[] bPos, int targetCount) {
        if (rPos[1] != 0 || gPos[1] != 0 || bPos[1] != 0) {
            return false;
        }
        return verifyColorPatterns(grid, rPos, gPos, bPos, targetCount, true);
    }

    /**
     * Validates column-based patterns for all colors.
     * Requires all colors to start at row 0.
     */
    private static boolean checkColumns(char[][] grid, int[] rPos, int[] gPos, int[] bPos, int targetCount) {
        if (rPos[0] != 0 || gPos[0] != 0 || bPos[0] != 0) {
            return false;
        }
        return verifyColorPatterns(grid, rPos, gPos, bPos, targetCount, false);
    }

    /**
     * Verifies that R, G, and B each form a valid pattern starting from their respective positions.
     */
    private static boolean verifyColorPatterns(char[][] grid, int[] rPos, int[] gPos, int[] bPos,
                                               int targetCount, boolean rowMajor) {
        return checkColorPattern(grid, rPos, 'R', targetCount, rowMajor) &&
               checkColorPattern(grid, gPos, 'G', targetCount, rowMajor) &&
               checkColorPattern(grid, bPos, 'B', targetCount, rowMajor);
    }

    /**
     * Checks if a specific color forms a valid contiguous pattern starting from startPos.
     * Scans in row-major or column-major order depending on the rowMajor flag.
     * Returns true when exactly targetCount occurrences are found before encountering a different character.
     */
    private static boolean checkColorPattern(char[][] grid, int[] startPos, char target,
                                             int targetCount, boolean rowMajor) {
        int count = 0;
        int startRow = startPos[0];
        int startCol = startPos[1];

        if (rowMajor) {
            for (int i = startRow; i < grid.length; i++) {
                for (int j = 0; j < grid[i].length; j++) {
                    if (grid[i][j] == target) {
                        count++;
                    } else if (count == targetCount) {
                        return true;
                    } else {
                        return false;
                    }
                }
            }
        } else {
            for (int j = startCol; j < grid[0].length; j++) {
                for (int i = 0; i < grid.length; i++) {
                    if (grid[i][j] == target) {
                        count++;
                    } else if (count == targetCount) {
                        return true;
                    } else {
                        return false;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Standard I/O helper class replacing the custom byte-based scanner.
     * Uses BufferedReader and StringTokenizer for reliable, maintainable input reading.
     */
    static class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            String s = next();
            return s == null ? 0 : Integer.parseInt(s);
        }
    }
}

import java.io.*;
import java.util.StringTokenizer;

public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);

        Task solver = new Task();
        solver.solve(in, out);

        out.close();
    }

    static class Task {
        public void solve(InputReader in, PrintWriter out) {
            int n = in.nextInt();
            int m = in.nextInt();

            char[][] grid = new char[n][m];
            for (int i = 0; i < n; i++) {
                String row = in.next();
                grid[i] = row.toCharArray();
            }

            // Check if horizontal tiling pattern is valid
            boolean isHorizontalValid = checkPattern(grid, n, m, true);
            // Check if vertical tiling pattern is valid
            boolean isVerticalValid = checkPattern(grid, n, m, false);

            // Output based on original logic: NO only if both conditions are met
            if (isHorizontalValid && isVerticalValid) {
                out.println("NO");
            } else {
                out.println("YES");
            }
        }

        /**
         * Checks if a valid repeating pattern exists along a given axis.
         * Returns true if the pattern condition is met.
         *
         * @param checkCols if true, checks patterns along columns (horizontal tiling)
         *                  if false, checks patterns along rows (vertical tiling)
         */
        private boolean checkPattern(char[][] grid, int n, int m, boolean checkCols) {
            boolean conditionMet = false;
            int rCount = 0, gCount = 0, bCount = 0;
            int patternLength = checkCols ? n : m;
            char[] basePattern = new char[patternLength];

            // 1. Extract base pattern (first column or first row) and count colors
            for (int i = 0; i < patternLength; i++) {
                char c = checkCols ? grid[i][0] : grid[0][i];
                basePattern[i] = c;
                if (c == 'R') rCount++;
                else if (c == 'G') gCount++;
                else if (c == 'B') bCount++;
            }

            // Condition A: Base line contains all three colors
            if (rCount > 0 && gCount > 0 && bCount > 0) {
                conditionMet = true;
            } else {
                // Condition B: Verify entire grid matches the base pattern
                for (int i = 0; i < n; i++) {
                    for (int j = 0; j < m; j++) {
                        char expected = checkCols ? basePattern[i] : basePattern[j];
                        if (grid[i][j] != expected) {
                            conditionMet = true;
                            break;
                        }
                    }
                    if (conditionMet) break;
                }
            }

            // Condition C: Counts of R, G, B in the base line must be equal
            if (rCount != gCount || rCount != bCount) {
                conditionMet = true;
            }

            return conditionMet;
        }
    }

    static class InputReader {
        public BufferedReader reader;
        public StringTokenizer tokenizer;

        public InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.*;
