public class E26_B {
    private FastScanner scanner;
    private PrintWriter writer;

    public void solve() {
        int n = scanner.nextInt();
        int m = scanner.nextInt();

        // Guard against empty grid
        if (n == 0 || m == 0) {
            writer.println("NO");
            return;
        }

        String[] grid = new String[n];
        for (int i = 0; i < n; i++) {
            grid[i] = scanner.next();
        }

        boolean isRowsUniform = areRowsUniform(grid);
        boolean isColsUniform = areColsUniform(grid);

        if (isRowsUniform) {
            writer.println(canDivideIntoThreeUniformSections(grid, true) ? "YES" : "NO");
        } else if (isColsUniform) {
            writer.println(canDivideIntoThreeUniformSections(grid, false) ? "YES" : "NO");
        } else {
            writer.println("NO");
        }
    }

    /**
     * Checks if every row consists of the same character repeated.
     */
    private boolean areRowsUniform(String[] grid) {
        for (String row : grid) {
            char firstChar = row.charAt(0);
            for (int j = 1; j < row.length(); j++) {
                if (row.charAt(j) != firstChar) {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Checks if every column consists of the same character repeated.
     */
    private boolean areColsUniform(String[] grid) {
        int n = grid.length;
        int m = grid[0].length();
        for (int j = 0; j < m; j++) {
            char firstChar = grid[0].charAt(j);
            for (int i = 1; i < n; i++) {
                if (grid[i].charAt(j) != firstChar) {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Checks if the grid can be divided into three equal sections
     * where each section is uniform and all three sections have different characters.
     * 
     * @param isHorizontal true if checking row-wise sections, false for column-wise
     */
    private boolean canDivideIntoThreeUniformSections(String[] grid, boolean isHorizontal) {
        int size = isHorizontal ? grid.length : grid[0].length();
        if (size % 3 != 0) {
            return false;
        }

        int sectionSize = size / 3;
        boolean[] usedCharacters = new boolean[26];

        for (int start = 0; start < size; start += sectionSize) {
            // Determine the reference character for the current section
            char referenceChar = isHorizontal ? grid[start].charAt(0) : grid[0].charAt(start);

            // If this character was already used in a previous section, it's invalid
            if (usedCharacters[referenceChar - 'A']) {
                return false;
            }

            // Verify all elements in this section match the reference character
            for (int k = 0; k < sectionSize; k++) {
                int currentIdx = start + k;
                char currentChar = isHorizontal ? grid[currentIdx].charAt(0) : grid[0].charAt(currentIdx);
                if (currentChar != referenceChar) {
                    return false;
                }
            }

            // Mark the character as used
            usedCharacters[referenceChar - 'A'] = true;
        }

        return true;
    }

    public void run() {
        scanner = new FastScanner();
        writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)));
        solve();
        writer.flush();
        writer.close();
    }

    /**
     * Optimized input reader for competitive programming environments.
     */
    private static class FastScanner {
        private BufferedReader br;
        private StringTokenizer st;

        public FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        public String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) {
                        throw new IOException("Unexpected end of input");
                    }
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input", e);
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }

        public double nextDouble() {
            return Double.parseDouble(next());
        }
    }

    public static void main(String[] args) {
        new E26_B().run();
    }
}

import java.util.Scanner;

public class Class2 {
    private static final String RESULT_YES = "YES";
    private static final String RESULT_NO = "NO";

    public static void main(String[] args) {
        // Use try-with-resources to automatically close the Scanner
        try (Scanner scanner = new Scanner(System.in)) {
            if (!scanner.hasNextInt()) {
                System.out.println(RESULT_NO);
                return;
            }

            int n = scanner.nextInt();
            scanner.nextLine(); // Consume the newline character after the integer

            String[] flags = new String[n];
            for (int i = 0; i < n; i++) {
                flags[i] = scanner.nextLine();
            }

            System.out.println(areFlagsValid(flags) ? RESULT_YES : RESULT_NO);
        }
    }

    /**
     * Orchestrates validation checks for the input flags.
     */
    private static boolean areFlagsValid(String[] flags) {
        if (flags == null || flags.length == 0) {
            return false;
        }

        int flagLength = flags[0].length();
        if (flagLength == 0) {
            return false;
        }

        // 1. All flags must have the same length and consist of a single color
        for (String flag : flags) {
            if (flag.length() != flagLength || !isSingleColor(flag)) {
                return false;
            }
        }

        // 2. Determine orientation (horizontal stripes vs vertical stripes)
        boolean isHorizontal = isHorizontalOrientation(flags);

        // 3. Extract the sequence of colors along the direction of arrangement
        char[] colorSequence = extractColorSequence(flags, isHorizontal);

        // 4. Validate the color sequence: at most 3 contiguous blocks of equal size
        return validateColorBlocks(colorSequence);
    }

    /**
     * Determines if the flags are arranged horizontally.
     * If the first column contains different colors, they represent horizontal stripes.
     * Otherwise, they represent vertical stripes.
     */
    private static boolean isHorizontalOrientation(String[] flags) {
        char firstColor = flags[0].charAt(0);
        for (int i = 1; i < flags.length; i++) {
            if (flags[i].charAt(0) != firstColor) {
                return true;
            }
        }
        return false;
    }

    /**
     * Checks if a flag consists of a single repeated character.
     */
    private static boolean isSingleColor(String flag) {
        char firstChar = flag.charAt(0);
        for (int i = 1; i < flag.length(); i++) {
            if (flag.charAt(i) != firstChar) {
                return false;
            }
        }
        return true;
    }

    /**
     * Extracts the sequence of colors along the primary direction of arrangement.
     */
    private static char[] extractColorSequence(String[] flags, boolean isHorizontal) {
        char[] sequence;
        if (isHorizontal) {
            sequence = new char[flags.length];
            for (int i = 0; i < flags.length; i++) {
                sequence[i] = flags[i].charAt(0);
            }
        } else {
            sequence = new char[flags[0].length()];
            for (int i = 0; i < flags[0].length(); i++) {
                sequence[i] = flags[0].charAt(i);
            }
        }
        return sequence;
    }

    /**
     * Validates that the color sequence consists of at most 3 contiguous blocks of equal length.
     * Replaces the original throw-null control flow and redundant equality checks.
     */
    private static boolean validateColorBlocks(char[] sequence) {
        if (sequence.length == 0) {
            return false;
        }

        int blockSize = 0;
        int blockCount = 0;
        char currentColor = sequence[0];
        Integer expectedBlockSize = null;

        for (char color : sequence) {
            if (color == currentColor) {
                blockSize++;
            } else {
                blockCount++;
                // Ensure all blocks have the same size
                if (expectedBlockSize != null && blockSize != expectedBlockSize) {
                    return false;
                }
                expectedBlockSize = blockSize;
                currentColor = color;
                blockSize = 1;
            }
        }
        // Check the final block
        blockCount++;
        if (expectedBlockSize != null && blockSize != expectedBlockSize) {
            return false;
        }

        // The original logic enforced exactly 3 blocks. Using <= 3 is more robust,
        // but change to (blockCount == 3) if strict original behavior is required.
        return blockCount <= 3;
    }
}

import java.util.Scanner;

public class Solution {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        // Read input dimensions
        if (!scanner.hasNextInt()) {
            return;
        }
        int rows = scanner.nextInt();
        int cols = scanner.nextInt();

        // Read the grid strings
        String[] grid = new String[rows];
        for (int i = 0; i < rows; i++) {
            grid[i] = scanner.next();
        }

        // Determine if the grid satisfies the condition horizontally or vertically
        boolean isHorizontalValid = checkHorizontalDivision(rows, cols, grid);
        boolean isVerticalValid = checkVerticalDivision(rows, cols, grid);

        // Output result
        if (isHorizontalValid || isVerticalValid) {
            System.out.print("YES");
        } else {
            System.out.print("NO");
        }

        scanner.close();
    }

    /**
     * Checks if the grid can be divided into three equal horizontal sections
     * where each section consists of a single repeated character.
     *
     * @param rows Number of rows
     * @param cols Number of columns
     * @param grid The grid of strings
     * @return true if the horizontal division is valid
     */
    private static boolean checkHorizontalDivision(int rows, int cols, String[] grid) {
        // Must be divisible by 3
        if (rows % 3 != 0) {
            return false;
        }

        int sectionSize = rows / 3;

        // Identify anchor characters. 
        // The original logic picked the character at the last row of each section.
        // Section 1: rows 0 to sectionSize-1. Anchor at sectionSize-1.
        // Section 2: rows sectionSize to 2*sectionSize-1. Anchor at 2*sectionSize-1.
        // Section 3: rows 2*sectionSize to 3*sectionSize-1. Anchor at 3*sectionSize-1.
        char anchor1 = grid[sectionSize - 1].charAt(0);
        char anchor2 = grid[2 * sectionSize - 1].charAt(0);
        char anchor3 = grid[3 * sectionSize - 1].charAt(0);

        // Anchors must be distinct
        if (anchor1 == anchor2 || anchor2 == anchor3 || anchor1 == anchor3) {
            return false;
        }

        // Verify that every character in Section 1 matches anchor1
        if (!isSectionUniform(grid, 0, sectionSize, 0, cols, anchor1)) {
            return false;
        }

        // Verify that every character in Section 2 matches anchor2
        if (!isSectionUniform(grid, sectionSize, 2 * sectionSize, 0, cols, anchor2)) {
            return false;
        }

        // Verify that every character in Section 3 matches anchor3
        if (!isSectionUniform(grid, 2 * sectionSize, 3 * sectionSize, 0, cols, anchor3)) {
            return false;
        }

        return true;
    }

    /**
     * Checks if the grid can be divided into three equal vertical sections
     * where each section consists of a single repeated character.
     *
     * @param rows Number of rows
     * @param cols Number of columns
     * @param grid The grid of strings
     * @return true if the vertical division is valid
     */
    private static boolean checkVerticalDivision(int rows, int cols, String[] grid) {
        // Must be divisible by 3
        if (cols % 3 != 0) {
            return false;
        }

        int sectionSize = cols / 3;

        // Identify anchor characters from the first row.
        // Section 1: cols 0 to sectionSize-1. Anchor at sectionSize-1.
        // Section 2: cols sectionSize to 2*sectionSize-1. Anchor at 2*sectionSize-1.
        // Section 3: cols 2*sectionSize to 3*sectionSize-1. Anchor at 3*sectionSize-1.
        char anchor1 = grid[0].charAt(sectionSize - 1);
        char anchor2 = grid[0].charAt(2 * sectionSize - 1);
        char anchor3 = grid[0].charAt(3 * sectionSize - 1);

        // Anchors must be distinct
        if (anchor1 == anchor2 || anchor2 == anchor3 || anchor1 == anchor3) {
            return false;
        }

        // Verify that every character in Section 1 matches anchor1
        if (!isSectionUniform(grid, 0, rows, 0, sectionSize, anchor1)) {
            return false;
        }

        // Verify that every character in Section 2 matches anchor2
        if (!isSectionUniform(grid, 0, rows, sectionSize, 2 * sectionSize, anchor2)) {
            return false;
        }

        // Verify that every character in Section 3 matches anchor3
        if (!isSectionUniform(grid, 0, rows, 2 * sectionSize, 3 * sectionSize, anchor3)) {
            return false;
        }

        return true;
    }

    /**
     * Helper method to check if a rectangular subgrid is uniform (contains only targetChar).
     *
     * @param grid The grid of strings
     * @param startRow Inclusive start row index
     * @param endRow Exclusive end row index
     * @param startCol Inclusive start column index
     * @param endCol Exclusive end column index
     * @param targetChar The character that must fill the section
     * @return true if all characters in the specified range equal targetChar
     */
    private static boolean isSectionUniform(String[] grid, int startRow, int endRow,
                                            int startCol, int endCol, char targetChar) {
        for (int r = startRow; r < endRow; r++) {
            for (int c = startCol; c < endCol; c++) {
                if (grid[r].charAt(c) != targetChar) {
                    return false;
                }
            }
        }
        return true;
    }
}

import java.util.Scanner;

public class HelloWorld {
    public static void main(String[] args) {
        // Use try-with-resources to ensure the Scanner is properly closed
        try (Scanner scanner = new Scanner(System.in)) {
            if (!scanner.hasNextInt()) return;

            int rows = scanner.nextInt();
            int cols = scanner.nextInt();

            char[][] grid = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                grid[i] = scanner.next().toCharArray();
            }

            boolean isValid = solve(grid, rows, cols);
            System.out.println(isValid ? "YES" : "NO");
        }
    }

    /**
     * Determines if the grid matches the required pattern.
     * The pattern requires the grid to be partitioned into 3 contiguous sections 
     * (either horizontally or vertically) where each section is uniform and 
     * the sections have distinct characters.
     */
    private static boolean solve(char[][] grid, int rows, int cols) {
        // Quick fail: if neither dimension is divisible by 3, partitioning is impossible
        if (rows % 3 != 0 && cols % 3 != 0) {
            return false;
        }

        // Check if the grid satisfies either the horizontal or vertical pattern
        return isHorizontalPattern(grid, rows, cols) || isVerticalPattern(grid, rows, cols);
    }

    /**
     * Validates if the grid consists of 3 horizontal bands.
     * Each band must be uniform, and the bands must have distinct characters.
     */
    private static boolean isHorizontalPattern(char[][] grid, int rows, int cols) {
        if (rows % 3 != 0) return false;
        int sectionSize = rows / 3;

        // 1. Verify that every row is uniform (all characters in a row are identical)
        for (int r = 0; r < rows; r++) {
            char rowChar = grid[r][0];
            for (int c = 1; c < cols; c++) {
                if (grid[r][c] != rowChar) {
                    return false;
                }
            }
        }

        // 2. Verify that the three horizontal sections have distinct characters
        char char1 = grid[sectionSize - 1][0];
        char char2 = grid[2 * sectionSize - 1][0];
        char char3 = grid[3 * sectionSize - 1][0];
        if (char1 == char2 || char1 == char3 || char2 == char3) {
            return false;
        }

        // 3. Verify that all rows within each section share the same character
        for (int band = 0; band < 3; band++) {
            char bandChar = grid[band * sectionSize][0];
            for (int r = band * sectionSize; r < (band + 1) * sectionSize; r++) {
                if (grid[r][0] != bandChar) {
                    return false;
                }
            }
        }

        return true;
    }

    /**
     * Validates if the grid consists of 3 vertical columns.
     * Each column must be uniform, and the columns must have distinct characters.
     */
    private static boolean isVerticalPattern(char[][] grid, int rows, int cols) {
        if (cols % 3 != 0) return false;
        int sectionSize = cols / 3;

        // 1. Verify that every column is uniform (all characters in a column are identical)
        for (int c = 0; c < cols; c++) {
            char colChar = grid[0][c];
            for (int r = 1; r < rows; r++) {
                if (grid[r][c] != colChar) {
                    return false;
                }
            }
        }

        // 2. Verify that the three vertical sections have distinct characters
        char char1 = grid[0][sectionSize - 1];
        char char2 = grid[0][2 * sectionSize - 1];
        char char3 = grid[0][3 * sectionSize - 1];
        if (char1 == char2 || char1 == char3 || char2 == char3) {
            return false;
        }

        // 3. Verify that all columns within each section share the same character
        for (int band = 0; band < 3; band++) {
            char bandChar = grid[0][band * sectionSize];
            for (int c = band * sectionSize; c < (band + 1) * sectionSize; c++) {
                if (grid[0][c] != bandChar) {
                    return false;
                }
            }
        }

        return true;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.OutputStream;
import java.io.PrintWriter;
import java.util.StringTokenizer;

public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        FastScanner in = new FastScanner(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        Solution solver = new Solution();
        solver.solve(in, out);
        out.close();
    }

    static class Solution {
        public void solve(FastScanner in, PrintWriter out) {
            int n = in.nextInt();
            int m = in.nextInt();
            char[][] grid = in.nextCharTable(n, m);

            boolean possible = false;
            if (n % 3 == 0 && checkHorizontal(grid, n, m)) {
                possible = true;
            } else if (m % 3 == 0 && checkVertical(grid, n, m)) {
                possible = true;
            }

            out.print(possible ? "YES" : "NO");
        }

        private boolean checkHorizontal(char[][] grid, int n, int m) {
            char[] colors = new char[3];
            colors[0] = grid[0][0];
            colors[1] = grid[n / 3][0];
            colors[2] = grid[2 * n / 3][0];

            if (!areDistinct(colors)) {
                return false;
            }

            for (int i = 0; i < 3; i++) {
                int startRow = i * (n / 3);
                int endRow = (i + 1) * (n / 3);
                for (int r = startRow; r < endRow; r++) {
                    for (int c = 0; c < m; c++) {
                        if (grid[r][c] != colors[i]) {
                            return false;
                        }
                    }
                }
            }
            return true;
        }

        private boolean checkVertical(char[][] grid, int n, int m) {
            char[] colors = new char[3];
            colors[0] = grid[0][0];
            colors[1] = grid[0][m / 3];
            colors[2] = grid[0][2 * m / 3];

            if (!areDistinct(colors)) {
                return false;
            }

            for (int i = 0; i < 3; i++) {
                int startCol = i * (m / 3);
                int endCol = (i + 1) * (m / 3);
                for (int r = 0; r < n; r++) {
                    for (int c = startCol; c < endCol; c++) {
                        if (grid[r][c] != colors[i]) {
                            return false;
                        }
                    }
                }
            }
            return true;
        }

        private boolean areDistinct(char[] colors) {
            return colors[0] != colors[1] && colors[1] != colors[2] && colors[0] != colors[2];
        }
    }

    static class FastScanner {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastScanner(InputStream in) {
            reader = new BufferedReader(new InputStreamReader(in));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                String line = readLine();
                if (line == null) {
                    return null;
                }
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            String s = next();
            return s == null ? 0 : Integer.parseInt(s);
        }

        public char[][] nextCharTable(int rows, int columns) {
            char[][] table = new char[rows][];
            for (int i = 0; i < rows; i++) {
                String row = next();
                if (row == null || row.length() != columns) {
                    throw new IllegalArgumentException("Invalid grid input at row " + i);
                }
                table[i] = row.toCharArray();
            }
            return table;
        }

        private String readLine() {
            try {
                return reader.readLine();
            } catch (IOException e) {
                throw new RuntimeException(e);
            }
        }
    }
}

import java.io.BufferedReader;
