/**
 * Main class for the solution.
 */
public class Main {
    public static void main(String[] args) {
        // Initialize input and output streams
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;

        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);

        // Instantiate solver and run
        TaskB solver = new TaskB();
        solver.solve(in, out);

        out.close();
    }

    /**
     * Solver class for Task B.
     */
    static class TaskB {
        private int rowCount;
        private int colCount;
        private char[][] grid;

        /**
         * Solves the problem by reading input and checking conditions.
         */
        public void solve(InputReader in, PrintWriter out) {
            rowCount = in.nextInt();
            colCount = in.nextInt();
            grid = new char[rowCount][];
            for (int i = 0; i < rowCount; i++) {
                grid[i] = in.next().toCharArray();
            }

            // Check for valid vertical stripes
            if (checkVerticalStripes(out)) {
                return;
            }

            // Check for valid horizontal stripes
            if (checkHorizontalStripes(out)) {
                return;
            }

            out.println("NO");
        }

        /**
         * Checks if the grid can be divided into 3 vertical stripes of distinct colors.
         */
        private boolean checkVerticalStripes(PrintWriter out) {
            if (colCount % 3 != 0) {
                return false;
            }

            int stripeWidth = colCount / 3;
            // Determine the required colors for each stripe based on the first row
            char color1 = grid[0][0];
            char color2 = grid[0][stripeWidth];
            char color3 = grid[0][2 * stripeWidth];

            // All three stripes must have distinct colors
            if (color1 == color2 || color2 == color3 || color1 == color3) {
                return false;
            }

            // Verify that all columns in the first stripe are color1
            for (int j = 0; j < stripeWidth; j++) {
                if (!isColSolid(j, color1)) {
                    return false;
                }
            }
            // Verify that all columns in the second stripe are color2
            for (int j = stripeWidth; j < 2 * stripeWidth; j++) {
                if (!isColSolid(j, color2)) {
                    return false;
                }
            }
            // Verify that all columns in the third stripe are color3
            for (int j = 2 * stripeWidth; j < 3 * stripeWidth; j++) {
                if (!isColSolid(j, color3)) {
                    return false;
                }
            }

            out.println("YES");
            return true;
        }

        /**
         * Checks if the grid can be divided into 3 horizontal stripes of distinct colors.
         */
        private boolean checkHorizontalStripes(PrintWriter out) {
            if (rowCount % 3 != 0) {
                return false;
            }

            int stripeHeight = rowCount / 3;
            // Determine the required colors for each stripe based on the first column
            char color1 = grid[0][0];
            char color2 = grid[stripeHeight][0];
            char color3 = grid[2 * stripeHeight][0];

            // All three stripes must have distinct colors
            if (color1 == color2 || color2 == color3 || color1 == color3) {
                return false;
            }

            // Verify that all rows in the first stripe are color1
            for (int i = 0; i < stripeHeight; i++) {
                if (!isRowSolid(i, color1)) {
                    return false;
                }
            }
            // Verify that all rows in the second stripe are color2
            for (int i = stripeHeight; i < 2 * stripeHeight; i++) {
                if (!isRowSolid(i, color2)) {
                    return false;
                }
            }
            // Verify that all rows in the third stripe are color3
            for (int i = 2 * stripeHeight; i < 3 * stripeHeight; i++) {
                if (!isRowSolid(i, color3)) {
                    return false;
                }
            }

            out.println("YES");
            return true;
        }

        /**
         * Checks if a specific row is filled entirely with the given color.
         */
        private boolean isRowSolid(int row, char color) {
            for (int col = 0; col < colCount; col++) {
                if (grid[row][col] != color) {
                    return false;
                }
            }
            return true;
        }

        /**
         * Checks if a specific column is filled entirely with the given color.
         */
        private boolean isColSolid(int col, char color) {
            for (int row = 0; row < rowCount; row++) {
                if (grid[row][col] != color) {
                    return false;
                }
            }
            return true;
        }
    }

    /**
     * Helper class for fast input reading.
     */
    static class InputReader {
        public BufferedReader reader;
        public StringTokenizer tokenizer;

        public InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) {
                        return null;
                    }
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            String s = next();
            if (s == null) {
                throw new RuntimeException("Unexpected end of input");
            }
            return Integer.parseInt(s);
        }
    }
}

import java.util.Scanner;

public class FlagOfBerland {

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            if (!scanner.hasNextInt()) {
                return;
            }

            int rows = scanner.nextInt();
            int cols = scanner.nextInt();

            char[][] grid = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                grid[i] = scanner.next().toCharArray();
            }

            boolean isValidHorizontal = checkHorizontalStripes(grid, rows, cols);
            boolean isValidVertical = checkVerticalStripes(grid, rows, cols);

            System.out.println((isValidHorizontal || isValidVertical) ? "YES" : "NO");
        }
    }

    /**
     * Checks if the grid forms a flag with three equal horizontal stripes.
     * Each stripe must be a single uniform color, and all three colors must be distinct.
     */
    private static boolean checkHorizontalStripes(char[][] grid, int rows, int cols) {
        if (rows % 3 != 0) {
            return false;
        }

        int stripeHeight = rows / 3;
        char colorTop = grid[0][0];
        char colorMiddle = grid[stripeHeight][0];
        char colorBottom = grid[2 * stripeHeight][0];

        // All three stripes must have different colors
        if (colorTop == colorMiddle || colorTop == colorBottom || colorMiddle == colorBottom) {
            return false;
        }

        // Verify each stripe consists entirely of its designated color
        for (int i = 0; i < 3; i++) {
            char currentColor = grid[i * stripeHeight][0];
            for (int r = i * stripeHeight; r < (i + 1) * stripeHeight; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] != currentColor) {
                        return false;
                    }
                }
            }
        }

        return true;
    }

    /**
     * Checks if the grid forms a flag with three equal vertical stripes.
     * Each stripe must be a single uniform color, and all three colors must be distinct.
     */
    private static boolean checkVerticalStripes(char[][] grid, int rows, int cols) {
        if (cols % 3 != 0) {
            return false;
        }

        int stripeWidth = cols / 3;
        char colorLeft = grid[0][0];
        char colorMiddle = grid[0][stripeWidth];
        char colorRight = grid[0][2 * stripeWidth];

        // All three stripes must have different colors
        if (colorLeft == colorMiddle || colorLeft == colorRight || colorMiddle == colorRight) {
            return false;
        }

        // Verify each stripe consists entirely of its designated color
        for (int i = 0; i < 3; i++) {
            char currentColor = grid[0][i * stripeWidth];
            for (int c = i * stripeWidth; c < (i + 1) * stripeWidth; c++) {
                for (int r = 0; r < rows; r++) {
                    if (grid[r][c] != currentColor) {
                        return false;
                    }
                }
            }
        }

        return true;
    }
}

import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        // Use try-with-resources to ensure the Scanner is properly closed
        try (Scanner scanner = new Scanner(System.in)) {
            if (!scanner.hasNextInt()) {
                return;
            }
            int n = scanner.nextInt();
            int m = scanner.nextInt();

            char[][] grid = new char[n][m];
            for (int i = 0; i < n; i++) {
                grid[i] = scanner.next().toCharArray();
            }

            // Check if either rows or columns satisfy the uniformity condition
            if (checkUniformity(grid, n, m, true) || checkUniformity(grid, n, m, false)) {
                System.out.println("YES");
            } else {
                System.out.println("NO");
            }
        }
    }

    /**
     * Determines if all rows (or columns) consist of a single repeated character,
     * and if the total counts of 'R', 'B', and 'G' are equal.
     *
     * @param grid      The 2D character array representing the grid.
     * @param n         Number of rows in the grid.
     * @param m         Number of columns in the grid.
     * @param checkRows True to validate rows; false to validate columns.
     * @return true if the condition is met, false otherwise.
     */
    private static boolean checkUniformity(char[][] grid, int n, int m, boolean checkRows) {
        int rCount = 0;
        int bCount = 0;
        int gCount = 0;

        int limit = checkRows ? n : m;
        int innerLimit = checkRows ? m : n;

        for (int i = 0; i < limit; i++) {
            // Get the first character of the current row/column
            char firstChar = checkRows ? grid[i][0] : grid[0][i];

            // Verify all characters in the row/column match the first one
            for (int j = 0; j < innerLimit; j++) {
                char currentChar = checkRows ? grid[i][j] : grid[j][i];
                if (currentChar != firstChar) {
                    return false; // Line is not uniform
                }
            }

            // Count the uniform line by its character type
            switch (firstChar) {
                case 'R': rCount++; break;
                case 'B': bCount++; break;
                case 'G': gCount++; break;
                default: return false; // Invalid character encountered
            }
        }

        // All lines must be uniform, and counts of R, B, and G must be equal
        return rCount == bCount && bCount == gCount;
    }
}

import java.util.Scanner;

/**
 * Validates whether a given grid can be divided into three equal uniform strips
 * either horizontally or vertically. Each strip must consist of a single character,
 * and all three strips must have distinct characters.
 */
public class GridPatternValidator {

    public static void main(String[] args) {
        // try-with-resources ensures the Scanner is properly closed
        try (Scanner scanner = new Scanner(System.in)) {
            if (!scanner.hasNextInt()) {
                return;
            }

            int rows = scanner.nextInt();
            int cols = scanner.nextInt();

            char[][] grid = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                if (!scanner.hasNext()) break;
                grid[i] = scanner.next().toCharArray();
            }

            if (isValid(grid)) {
                System.out.println("YES");
            } else {
                System.out.println("NO");
            }
        }
    }

    /**
     * Determines if the grid satisfies the pattern requirements.
     */
    private static boolean isValid(char[][] grid) {
        if (grid == null || grid.length == 0 || grid[0].length == 0) {
            return false;
        }

        int rows = grid.length;
        int cols = grid[0].length;

        // Priority: Check horizontal strips first, then vertical
        if (rows % 3 == 0 && checkHorizontalStrips(grid, rows, cols)) {
            return true;
        }
        if (cols % 3 == 0 && checkVerticalStrips(grid, rows, cols)) {
            return true;
        }

        return false;
    }

    /**
     * Checks if the grid can be divided into three horizontal strips,
     * each consisting of a single uniform character, with all three characters being distinct.
     */
    private static boolean checkHorizontalStrips(char[][] grid, int rows, int cols) {
        int stripHeight = rows / 3;
        char char1 = grid[0][0];
        char char2 = grid[stripHeight][0];
        char char3 = grid[2 * stripHeight][0];

        // All three strips must have different characters
        if (char1 == char2 || char1 == char3 || char2 == char3) {
            return false;
        }

        for (int i = 0; i < rows; i++) {
            char expected = (i < stripHeight) ? char1 : (i < 2 * stripHeight) ? char2 : char3;
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] != expected) {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Checks if the grid can be divided into three vertical strips,
     * each consisting of a single uniform character, with all three characters being distinct.
     */
    private static boolean checkVerticalStrips(char[][] grid, int rows, int cols) {
        int stripWidth = cols / 3;
        char char1 = grid[0][0];
        char char2 = grid[0][stripWidth];
        char char3 = grid[0][2 * stripWidth];

        // All three strips must have different characters
        if (char1 == char2 || char1 == char3 || char2 == char3) {
            return false;
        }

        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                char expected = (j < stripWidth) ? char1 : (j < 2 * stripWidth) ? char2 : char3;
                if (grid[i][j] != expected) {
                    return false;
                }
            }
        }
        return true;
    }
}

import java.util.Scanner;

public class ColorGridChecker {

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            int height = scanner.nextInt();
            int width = scanner.nextInt();
            char[][] grid = new char[height][width];

            for (int i = 0; i < height; i++) {
                grid[i] = scanner.next().toCharArray();
            }

            boolean isVerticalStripes = checkUniformStripes(grid, width, height, true);
            boolean isHorizontalStripes = checkUniformStripes(grid, width, height, false);

            System.out.println(isVerticalStripes || isHorizontalStripes ? "YES" : "NO");
        }
    }

    /**
     * Checks if the grid consists of uniform vertical or horizontal stripes.
     * Each stripe must contain exactly three contiguous blocks of colors 'R', 'G', and 'B',
     * with each color appearing the same number of times.
     *
     * @param grid        The 2D character array representing the grid
     * @param width       Number of columns in the grid
     * @param height      Number of rows in the grid
     * @param checkColumns If true, checks vertical stripes; otherwise checks horizontal stripes
     * @return true if the grid satisfies the stripe conditions, false otherwise
     */
    private static boolean checkUniformStripes(char[][] grid, int width, int height, boolean checkColumns) {
        // 1. Verify that every column/row is uniform
        for (int i = 0; i < width; i++) {
            for (int j = 0; j < height; j++) {
                char expected = checkColumns ? grid[0][i] : grid[i][0];
                char actual = checkColumns ? grid[j][i] : grid[i][j];
                if (expected != actual) {
                    return false;
                }
            }
        }

        // 2. Extract the sequence of colors for the first column/row
        int stripeLength = checkColumns ? width : height;
        char[] stripe = new char[stripeLength];
        for (int i = 0; i < stripeLength; i++) {
            stripe[i] = checkColumns ? grid[0][i] : grid[i][0];
        }

        // 3. Analyze the stripe: count contiguous blocks and color frequencies
        int blockCount = 0;
        int rCount = 0, gCount = 0, bCount = 0;
        char previousColor = 0;

        for (char currentColor : stripe) {
            if (currentColor != previousColor) {
                blockCount++;
                previousColor = currentColor;
            }

            switch (currentColor) {
                case 'R': rCount++; break;
                case 'G': gCount++; break;
                case 'B': bCount++; break;
                default: return false; // Invalid character encountered
            }
        }

        // 4. Validate conditions: exactly 3 contiguous blocks, each color appears equally
        return blockCount == 3 && rCount == gCount && gCount == bCount;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.HashSet;
import java.util.Set;

public class FlagOfBerland {

    public static void main(String[] args) throws IOException {
        // Use try-with-resources for automatic resource management
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            String[] firstLine = br.readLine().trim().split("\\s+");
            int n = Integer.parseInt(firstLine[0]);
            int m = Integer.parseInt(firstLine[1]);

            String[] grid = new String[n];
            for (int i = 0; i < n; i++) {
                grid[i] = br.readLine().trim();
            }

            System.out.println(canFormFlag(n, m, grid) ? "YES" : "NO");
        }
    }

    /**
     * Determines if the grid can be divided into three equal monochromatic stripes
     * either horizontally or vertically, with all three stripes having distinct colors.
     */
    private static boolean canFormFlag(int n, int m, String[] grid) {
        if (n % 3 == 0 && checkHorizontal(n, m, grid)) {
            return true;
        }
        if (m % 3 == 0 && checkVertical(n, m, grid)) {
            return true;
        }
        return false;
    }

    /**
     * Checks if the grid can be split into 3 horizontal monochromatic stripes
     * with distinct colors.
     */
    private static boolean checkHorizontal(int n, int m, String[] grid) {
        int stripeSize = n / 3;
        Set<Character> colors = new HashSet<>();

        for (int i = 0; i < n; i += stripeSize) {
            char currentColor = grid[i].charAt(0);

            // Verify the entire stripe is monochromatic
            for (int row = i; row < i + stripeSize; row++) {
                for (int col = 0; col < m; col++) {
                    if (grid[row].charAt(col) != currentColor) {
                        return false;
                    }
                }
            }

            // Ensure all three stripes have different colors
            if (!colors.add(currentColor)) {
                return false; // Duplicate color detected
            }
        }
        // Must have exactly 3 distinct colors
        return colors.size() == 3;
    }

    /**
     * Checks if the grid can be split into 3 vertical monochromatic stripes
     * with distinct colors.
     */
    private static boolean checkVertical(int n, int m, String[] grid) {
        int stripeSize = m / 3;
        Set<Character> colors = new HashSet<>();

        for (int j = 0; j < m; j += stripeSize) {
            char currentColor = grid[0].charAt(j);

            // Verify the entire stripe is monochromatic
            for (int col = j; col < j + stripeSize; col++) {
                for (int row = 0; row < n; row++) {
                    if (grid[row].charAt(col) != currentColor) {
                        return false;
                    }
                }
            }

            // Ensure all three stripes have different colors
            if (!colors.add(currentColor)) {
                return false; // Duplicate color detected
            }
        }
        // Must have exactly 3 distinct colors
        return colors.size() == 3;
    }
}

import java.util.Scanner;
import java.io.PrintWriter;

public class Main {

    public static void main(String[] args) {
        // Initialize input and output streams
        Scanner scanner = new Scanner(System.in);
        PrintWriter out = new PrintWriter(System.out);

        // Instantiate the solver
        TaskB solver = new TaskB();

        // Execute the solution logic
        solver.solve(scanner, out);

        // Ensure output is flushed and closed
        out.flush();
        out.close();
    }

    /**
     * TaskB encapsulates the logic for solving the specific grid problem.
     */
    static class TaskB {

        /**
         * Solves the problem by reading input dimensions and grid data,
         * then checking for valid horizontal or vertical bands.
         *
         * @param in  Scanner for reading input
         * @param out PrintWriter for writing output
         */
        public void solve(Scanner in, PrintWriter out) {
            // Basic validation to ensure input exists
            if (!in.hasNextInt()) return;

            int n = in.nextInt();
            int m = in.nextInt();
            in.nextLine(); // Consume the newline character left after nextInt()

            // Read the grid into a 2D character array
            char[][] grid = new char[n][m];
            for (int i = 0; i < n; i++) {
                String line = in.nextLine();
                // Using toCharArray is cleaner and more efficient than charAt loops
                grid[i] = line.toCharArray();
            }

            // Check if the grid satisfies the condition for horizontal bands OR vertical bands
            boolean isPossible = checkHorizontalBands(grid, n, m) 
                               || checkVerticalBands(grid, n, m);

            // Output the result
            out.println(isPossible ? "YES" : "NO");
        }

        /**
         * Checks if the grid can be divided into 3 horizontal bands of uniform characters.
         * Each band must consist of a single distinct character, and the characters 
         * of the three bands must be unique.
         *
         * @param grid The character grid
         * @param n    Number of rows
         * @param m    Number of columns
         * @return true if valid horizontal bands exist, false otherwise
         */
        private boolean checkHorizontalBands(char[][] grid, int n, int m) {
            // The number of rows must be divisible by 3
            if (n % 3 != 0) {
                return false;
            }

            int segmentSize = n / 3;

            // Identify the characters defining the three horizontal bands
            // Band 1: Rows 0 to segmentSize-1
            // Band 2: Rows segmentSize to 2*segmentSize-1
            // Band 3: Rows 2*segmentSize to n-1
            char band1Char = grid[0][0];
            char band2Char = grid[segmentSize][0];
            char band3Char = grid[2 * segmentSize][0];

            // The characters defining the bands must be distinct
            if (band1Char == band2Char || band2Char == band3Char || band1Char == band3Char) {
                return false;
            }

            // Verify that every cell in the grid matches its expected band character
            for (int i = 0; i < n; i++) {
                char expectedChar;
                if (i < segmentSize) {
                    expectedChar = band1Char;
                } else if (i < 2 * segmentSize) {
                    expectedChar = band2Char;
                } else {
                    expectedChar = band3Char;
                }

                for (int j = 0; j < m; j++) {
                    if (grid[i][j] != expectedChar) {
                        return false;
                    }
                }
            }

            return true;
        }

        /**
         * Checks if the grid can be divided into 3 vertical bands of uniform characters.
         * Each band must consist of a single distinct character, and the characters 
         * of the three bands must be unique.
         *
         * @param grid The character grid
         * @param n    Number of rows
         * @param m    Number of columns
         * @return true if valid vertical bands exist, false otherwise
         */
        private boolean checkVerticalBands(char[][] grid, int n, int m) {
            // The number of columns must be divisible by 3
            if (m % 3 != 0) {
                return false;
            }

            int segmentSize = m / 3;

            // Identify the characters defining the three vertical bands
            // Band 1: Cols 0 to segmentSize-1
            // Band 2: Cols segmentSize to 2*segmentSize-1
            // Band 3: Cols 2*segmentSize to m-1
            char band1Char = grid[0][0];
            char band2Char = grid[0][segmentSize];
            char band3Char = grid[0][2 * segmentSize];

            // The characters defining the bands must be distinct
            if (band1Char == band2Char || band2Char == band3Char || band1Char == band3Char) {
                return false;
            }

            // Verify that every cell in the grid matches its expected band character
            for (int j = 0; j < m; j++) {
                char expectedChar;
                if (j < segmentSize) {
                    expectedChar = band1Char;
                } else if (j < 2 * segmentSize) {
                    expectedChar = band2Char;
                } else {
                    expectedChar = band3Char;
                }

                for (int i = 0; i < n; i++) {
                    if (grid[i][j] != expectedChar) {
                        return false;
                    }
                }
            }

            return true;
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.HashSet;
import java.util.Set;
import java.util.StringTokenizer;

public class FlagOfBerland {

    public static void main(String[] args) throws IOException {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer tokenizer = new StringTokenizer(reader.readLine());

        int n = Integer.parseInt(tokenizer.nextToken());
        int m = Integer.parseInt(tokenizer.nextToken());

        char[][] grid = new char[n][];
        for (int i = 0; i < n; i++) {
            grid[i] = reader.readLine().toCharArray();
        }

        System.out.println(isValidFlag(grid, n, m) ? "YES" : "NO");
    }

    /**
     * Checks if the grid forms a valid flag either horizontally or vertically.
     */
    private static boolean isValidFlag(char[][] grid, int n, int m) {
        return checkStripes(grid, n, m, true) || checkStripes(grid, n, m, false);
    }

    /**
     * Validates if the grid can be split into 3 equal, uniform, and distinct colored stripes.
     *
     * @param horizontal true for horizontal stripes, false for vertical stripes
     */
    private static boolean checkStripes(char[][] grid, int n, int m, boolean horizontal) {
        int dim = horizontal ? n : m;
        if (dim % 3 != 0) {
            return false;
        }

        int partSize = dim / 3;
        Set<Character> colors = new HashSet<>();

        for (int k = 0; k < 3; k++) {
            int start = k * partSize;
            // Determine the expected color for this stripe
            char color = horizontal ? grid[start][0] : grid[0][start];

            // Validate color is one of the allowed flag colors
            if (color != 'R' && color != 'G' && color != 'B') {
                return false;
            }

            // Verify the entire stripe is filled with the same color
            for (int i = start; i < start + partSize; i++) {
                for (int j = 0; j < (horizontal ? m : n); j++) {
                    if (horizontal ? grid[i][j] : grid[j][i] != color) {
                        return false;
                    }
                }
            }

            // Ensure all three stripes have distinct colors
            if (!colors.add(color)) {
                return false;
            }
        }

        return true;
    }
}

import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) {
        // Run in a dedicated thread with increased stack size to prevent StackOverflowError
        // and optimize I/O throughput, a common practice in competitive programming.
        new Thread(null, () -> {
            try {
                solve();
            } catch (IOException e) {
                throw new RuntimeException("I/O error during execution", e);
            }
        }, "solve", 1 << 26).start();
    }

    private static void solve() throws IOException {
        FastReader reader = new FastReader();
        PrintWriter out = new PrintWriter(System.out);

        int n = reader.nextInt();
        int m = reader.nextInt();

        char[][] grid = new char[n][m];
        for (int i = 0; i < n; i++) {
            grid[i] = reader.next().toCharArray();
        }

        // Bounding box tracking: [minCol, maxCol, minRow, maxRow] for each color
        int[] minCol = new int[3];
        int[] maxCol = new int[3];
        int[] minRow = new int[3];
        int[] maxRow = new int[3];

        // Initialize bounds
        Arrays.fill(minCol, m);
        Arrays.fill(minRow, n);
        Arrays.fill(maxCol, -1);
        Arrays.fill(maxRow, -1);

        // Scan grid to find bounding boxes for each color
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                int colorIdx = getColorIndex(grid[i][j]);
                minCol[colorIdx] = Math.min(minCol[colorIdx], j);
                maxCol[colorIdx] = Math.max(maxCol[colorIdx], j);
                minRow[colorIdx] = Math.min(minRow[colorIdx], i);
                maxRow[colorIdx] = Math.max(maxRow[colorIdx], i);
            }
        }

        // Calculate dimensions (difference between max and min coordinates)
        int h0 = maxRow[0] - minRow[0];
        int w0 = maxCol[0] - minCol[0];
        int h1 = maxRow[1] - minRow[1];
        int w1 = maxCol[1] - minCol[1];
        int h2 = maxRow[2] - minRow[2];
        int w2 = maxCol[2] - minCol[2];

        // Check for missing colors or invalid dimensions
        if (h0 < 0 || w0 < 0 || h1 < 0 || w1 < 0 || h2 < 0 || w2 < 0) {
            out.println("NO");
        } 
        // Check if all bounding boxes have identical dimensions
        else if (h0 != h1 || h0 != h2 || w0 != w1 || w0 != w2) {
            out.println("NO");
        } 
        // Verify that each bounding box contains only its corresponding color
        else {
            boolean isValid = true;
            for (int c = 0; c < 3; c++) {
                if (!isUniformColor(grid, minRow[c], maxRow[c], minCol[c], maxCol[c])) {
                    isValid = false;
                    break;
                }
            }
            out.println(isValid ? "YES" : "NO");
        }

        out.flush();
    }

    /**
     * Checks if all cells within the specified rectangular region contain the same character.
     */
    private static boolean isUniformColor(char[][] grid, int rStart, int rEnd, int cStart, int cEnd) {
        char target = grid[rStart][cStart];
        for (int r = rStart; r <= rEnd; r++) {
            for (int c = cStart; c <= cEnd; c++) {
                if (grid[r][c] != target) {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Maps character to color index: R -> 0, B -> 1, G -> 2.
     */
    private static int getColorIndex(char ch) {
        return switch (ch) {
            case 'R' -> 0;
            case 'B' -> 1;
            case 'G' -> 2;
            default -> throw new IllegalArgumentException("Invalid character: " + ch);
        };
    }

    /**
     * Optimized Fast I/O reader for competitive programming.
     */
    static class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input", e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

public class Main {

    public static void main(String[] args) throws IOException {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        String line = reader.readLine();
        if (line == null) {
            return;
        }

        StringTokenizer tokenizer = new StringTokenizer(line);
        int rows = Integer.parseInt(tokenizer.nextToken());
        int cols = Integer.parseInt(tokenizer.nextToken());

        String[] grid = new String[rows];
        for (int i = 0; i < rows; i++) {
            grid[i] = reader.readLine();
        }

        boolean isValid = false;
        if (rows % 3 == 0) {
            isValid = checkHorizontalStrips(grid, rows, cols);
        }
        if (!isValid && cols % 3 == 0) {
            isValid = checkVerticalStrips(grid, rows, cols);
        }

        System.out.println(isValid ? "YES" : "NO");
    }

    /**
     * Checks if the grid can be divided into 3 equal horizontal strips,
     * each filled with a single distinct color ('R', 'G', or 'B').
     */
    private static boolean checkHorizontalStrips(String[] grid, int rows, int cols) {
        int stripHeight = rows / 3;
        boolean[] usedColors = new boolean[3]; // Maps to R, G, B indices

        for (int i = 0; i < 3; i++) {
            char color = grid[i * stripHeight].charAt(0);
            int colorIndex = getColorIndex(color);

            if (colorIndex == -1 || usedColors[colorIndex]) {
                return false;
            }
            usedColors[colorIndex] = true;

            for (int r = i * stripHeight; r < (i + 1) * stripHeight; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r].charAt(c) != color) {
                        return false;
                    }
                }
            }
        }
        return true;
    }

    /**
     * Checks if the grid can be divided into 3 equal vertical strips,
     * each filled with a single distinct color ('R', 'G', or 'B').
     */
    private static boolean checkVerticalStrips(String[] grid, int rows, int cols) {
        int stripWidth = cols / 3;
        boolean[] usedColors = new boolean[3]; // Maps to R, G, B indices

        for (int i = 0; i < 3; i++) {
            char color = grid[0].charAt(i * stripWidth);
            int colorIndex = getColorIndex(color);

            if (colorIndex == -1 || usedColors[colorIndex]) {
                return false;
            }
            usedColors[colorIndex] = true;

            for (int c = i * stripWidth; c < (i + 1) * stripWidth; c++) {
                for (int r = 0; r < rows; r++) {
                    if (grid[r].charAt(c) != color) {
                        return false;
                    }
                }
            }
        }
        return true;
    }

    /**
     * Maps color characters to array indices: R->0, G->1, B->2.
     * Returns -1 for invalid characters.
     */
    private static int getColorIndex(char color) {
        if (color == 'R') return 0;
        if (color == 'G') return 1;
        if (color == 'B') return 2;
        return -1;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

public class Main {

    public static void main(String[] args) {
        FastScanner in = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out);
        try {
            solve(in, out);
        } catch (Exception e) {
            e.printStackTrace();
        } finally {
            out.flush();
            out.close();
        }
    }

    static void solve(FastScanner in, PrintWriter out) {
        int n = in.nextInt();
        int m = in.nextInt();
        char[][] grid = new char[n][m];

        for (int i = 0; i < n; i++) {
            grid[i] = in.next().toCharArray();
        }

        boolean valid = isValid(grid) || isValid(transpose(grid));
        out.println(valid ? "YES" : "NO");
    }

    /**
     * Checks if the grid satisfies the problem constraints:
     * 1. Every row consists of identical characters.
     * 2. Every column consists of identical characters.
     * 3. The number of rows starting with 'R', 'G', and 'B' are all equal.
     */
    static boolean isValid(char[][] grid) {
        int n = grid.length;
        int m = grid[0].length;
        int[] counts = new int[3]; // Indices: 0='R', 1='G', 2='B'

        // 1. Validate row uniformity and count row-start characters
        for (int i = 0; i < n; i++) {
            char firstChar = grid[i][0];
            int type = getCharType(firstChar);
            counts[type]++;

            for (int j = 1; j < m; j++) {
                if (grid[i][j] != firstChar) {
                    return false;
                }
            }
        }

        // 2. Validate that each character type appears exactly n/3 times
        if (n % 3 != 0 || counts[0] != n / 3 || counts[1] != n / 3 || counts[2] != n / 3) {
            return false;
        }

        // 3. Validate column uniformity
        for (int j = 0; j < m; j++) {
            char firstChar = grid[0][j];
            for (int i = 1; i < n; i++) {
                if (grid[i][j] != firstChar) {
                    return false;
                }
            }
        }

        return true;
    }

    /**
     * Transposes a 2D character array.
     */
    static char[][] transpose(char[][] grid) {
        int n = grid.length;
        int m = grid[0].length;
        char[][] transposed = new char[m][n];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                transposed[j][i] = grid[i][j];
            }
        }
        return transposed;
    }

    /**
     * Maps characters to indices: 'R' -> 0, 'G' -> 1, 'B' -> 2.
     */
    static int getCharType(char c) {
        return switch (c) {
            case 'R' -> 0;
            case 'G' -> 1;
            case 'B' -> 2;
            default -> throw new IllegalArgumentException("Invalid character: " + c);
        };
    }

    /**
     * Fast input reader for competitive programming / performance-critical IO.
     */
    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input", e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        long nextLong() {
            return Long.parseLong(next());
        }

        double nextDouble() {
            return Double.parseDouble(next());
        }
    }
}

import java.util.HashSet;
import java.util.Scanner;
import java.util.Set;

public class A {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        if (!scanner.hasNextInt()) {
            scanner.close();
            return;
        }

        int rows = scanner.nextInt();
        int cols = scanner.nextInt();
        char[][] grid = new char[rows][cols];

        for (int i = 0; i < rows; i++) {
            grid[i] = scanner.next().toCharArray();
        }

        boolean rowsDivBy3 = rows % 3 == 0;
        boolean colsDivBy3 = cols % 3 == 0;

        String result;

        // Determine processing direction based on dimension divisibility
        if (!rowsDivBy3 && !colsDivBy3) {
            System.out.println("NO");
            scanner.close();
            return;
        } else if (rowsDivBy3 && !colsDivBy3) {
            result = processStrips(grid, true);
        } else if (!rowsDivBy3 && colsDivBy3) {
            result = processStrips(grid, false);
        } else {
            // Both divisible by 3: process rows first, fallback to columns if needed
            result = processStrips(grid, true);
            if (result.length() > 3) {
                result = processStrips(grid, false);
            }
        }

        if (isRgbPermutation(result) && result.length() == 3) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }
        scanner.close();
    }

    /**
     * Processes the grid in strips of 3 (either horizontal or vertical).
     * For each strip, collects unique characters in order of appearance
     * and appends them to the result string.
     *
     * @param grid      The 2D character array
     * @param horizontal true for horizontal strips (rows), false for vertical (columns)
     * @return Concatenated string of unique characters per strip
     */
    private static String processStrips(char[][] grid, boolean horizontal) {
        int limit = horizontal ? grid.length : grid[0].length;
        int crossLimit = horizontal ? grid[0].length : grid.length;
        StringBuilder result = new StringBuilder();

        for (int start = 0; start < limit; start += 3) {
            Set<Character> seen = new HashSet<>();
            for (int i = start; i < start + 3; i++) {
                for (int j = 0; j < crossLimit; j++) {
                    char ch = horizontal ? grid[i][j] : grid[j][i];
                    if (seen.add(ch)) {
                        result.append(ch);
                    }
                }
            }
        }
        return result.toString();
    }

    /**
     * Checks if the string is exactly a permutation of "RGB".
     *
     * @param s The string to validate
     * @return true if s contains exactly one 'R', one 'G', and one 'B'
     */
    private static boolean isRgbPermutation(String s) {
        if (s.length() != 3) {
            return false;
        }
        return s.contains("R") && s.contains("G") && s.contains("B");
    }
}

import java.util.Scanner;

/**
 * Validates if a grid of characters can be divided into three horizontal strips
 * of uniform, distinct characters. It checks both the original orientation
 * and the transposed orientation.
 */
public class GridValidator {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        // Read dimensions N (rows) and M (columns)
        if (!scanner.hasNextInt()) {
            return;
        }
        int rows = scanner.nextInt();
        int cols = scanner.nextInt();

        // Read the grid data
        char[][] grid = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            if (scanner.hasNext()) {
                grid[i] = scanner.next().toCharArray();
            }
        }

        // Check if the grid satisfies the condition in its original orientation
        if (isValid(grid, rows, cols)) {
            System.out.println("YES");
            return;
        }

        // Check if the grid satisfies the condition after being transposed (rotated 90 degrees)
        char[][] transposedGrid = transpose(grid, rows, cols);
        // Note: Dimensions swap when transposed (rows become cols, cols become rows)
        if (isValid(transposedGrid, cols, rows)) {
            System.out.println("YES");
            return;
        }

        // If neither orientation works
        System.out.println("NO");

        scanner.close();
    }

    /**
     * Validates if the grid can be divided into three horizontal strips
     * of uniform characters, where all three strip characters are distinct.
     * 
     * @param grid The 2D character array representing the grid.
     * @param height The number of rows in the grid.
     * @param width The number of columns in the grid.
     * @return true if valid, false otherwise.
     */
    private static boolean isValid(char[][] grid, int height, int width) {
        // The height must be divisible by 3 to form three equal horizontal strips
        if (height % 3 != 0) {
            return false;
        }

        int stripHeight = height / 3;
        char[] stripCharacters = new char[3];
        boolean[] stripsFilled = new boolean[3];

        // Iterate through every cell in the grid
        for (int r = 0; r < height; r++) {
            // Determine which strip (0, 1, or 2) the current row belongs to
            int stripIndex = r / stripHeight;

            for (int c = 0; c < width; c++) {
                char currentChar = grid[r][c];

                if (!stripsFilled[stripIndex]) {
                    // First time encountering this strip: record the character
                    stripCharacters[stripIndex] = currentChar;
                    stripsFilled[stripIndex] = true;
                } else if (stripCharacters[stripIndex] != currentChar) {
                    // Mismatch found within the same strip: invalid configuration
                    return false;
                }
            }
        }

        // Verify that the characters of the three strips are distinct
        // Strip 0 != Strip 1 AND Strip 1 != Strip 2 AND Strip 0 != Strip 2
        return (stripCharacters[0] != stripCharacters[1] &&
                stripCharacters[1] != stripCharacters[2] &&
                stripCharacters[0] != stripCharacters[2]);
    }

    /**
     * Transposes a 2D character array (swaps rows and columns).
     * 
     * @param original The original grid.
     * @param rows Number of rows in original.
     * @param cols Number of columns in original.
     * @return The transposed grid.
     */
    private static char[][] transpose(char[][] original, int rows, int cols) {
        char[][] transposed = new char[cols][rows];
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                transposed[j][i] = original[i][j];
            }
        }
        return transposed;
    }
}

import java.io.*;
import java.util.*;

/**
 * Determines if the given grid forms a valid flag consisting of three
 * disjoint rectangles of 'R', 'G', and 'B' with identical dimensions.
 */
public class FlagofBerland {

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)));

        try {
            int n = scanner.nextInt();
            int m = scanner.nextInt();

            char[][] grid = new char[n][];
            for (int i = 0; i < n; i++) {
                // next() safely skips whitespace/newlines left by previous reads
                grid[i] = scanner.next().toCharArray();
            }

            int[] rDims = findRectangle(grid, 'R');
            int[] gDims = findRectangle(grid, 'G');
            int[] bDims = findRectangle(grid, 'B');

            if (isValidFlag(rDims, gDims, bDims)) {
                out.println("YES");
            } else {
                out.println("NO");
            }
        } finally {
            out.flush();
        }
    }

    /**
     * Validates that all three color rectangles exist, are well-formed, 
     * and share identical dimensions.
     */
    private static boolean isValidFlag(int[] rDims, int[] gDims, int[] bDims) {
        return rDims != null && gDims != null && bDims != null
                && Arrays.equals(rDims, gDims) && Arrays.equals(gDims, bDims);
    }

    /**
     * Finds the bounding box of a specific character in the grid.
     * Returns {height, width} if it forms a solid rectangle with no occurrences outside,
     * otherwise returns null.
     */
    private static int[] findRectangle(char[][] grid, char target) {
        int rows = grid.length;
        int cols = grid[0].length;
        int top = rows, left = cols, bottom = -1, right = -1;

        // Pass 1: Determine the bounding box of the target character
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == target) {
                    top = Math.min(top, r);
                    left = Math.min(left, c);
                    bottom = Math.max(bottom, r);
                    right = Math.max(right, c);
                }
            }
        }

        // If the character is not found, the flag is invalid
        if (top == rows) {
            return null;
        }

        // Pass 2: Validate that the rectangle is solid and contains no extra characters
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                boolean inside = (r >= top && r <= bottom && c >= left && c <= right);
                boolean isTarget = (grid[r][c] == target);

                if (inside && !isTarget) return null;
                if (!inside && isTarget) return null;
            }
        }

        return new int[]{bottom - top, right - left};
    }

    /**
     * Efficient, thread-safe input reader for fast I/O operations.
     */
    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input", e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            String token = next();
            if (token == null) throw new NoSuchElementException("Unexpected end of input");
            return Integer.parseInt(token);
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.OutputStream;
import java.io.PrintWriter;
import java.util.HashSet;
import java.util.Set;
import java.util.StringTokenizer;

public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);

        FlagSolver solver = new FlagSolver();
        solver.solve(in, out);

        out.close();
    }

    static class FlagSolver {
        public void solve(InputReader in, PrintWriter out) {
            int rows = in.nextInt();
            int cols = in.nextInt();

            char[][] grid = new char[rows][cols];
            for (int r = 0; r < rows; r++) {
                grid[r] = in.next().toCharArray();
            }

            if (isHorizontalFlag(grid) || isVerticalFlag(grid)) {
                out.println("YES");
            } else {
                out.println("NO");
            }
        }

        private boolean isHorizontalFlag(char[][] grid) {
            return checkStripes(grid, true);
        }

        private boolean isVerticalFlag(char[][] grid) {
            return checkStripes(grid, false);
        }

        /**
         * Checks if the grid forms a valid flag pattern with stripes 
         * running in the specified direction.
         * 
         * @param grid The character grid representing the flag
         * @param horizontal true for horizontal stripes, false for vertical
         * @return true if the grid matches the flag pattern, false otherwise
         */
        private boolean checkStripes(char[][] grid, boolean horizontal) {
            if (grid.length == 0 || grid[0].length == 0) {
                return false;
            }

            int dim = horizontal ? grid.length : grid[0].length;
            int otherDim = horizontal ? grid[0].length : grid.length;

            // A valid flag must have the stripe direction divisible by 3
            if (dim % 3 != 0) {
                return false;
            }

            int expectedBandSize = dim / 3;
            Set<Character> colors = new HashSet<>();
            int currentBandSize = 0;
            char prevColor = 0;

            for (int i = 0; i < dim; i++) {
                char color = horizontal ? grid[i][0] : grid[0][i];

                // Verify the entire row/column is monochromatic
                for (int j = 1; j < otherDim; j++) {
                    char cell = horizontal ? grid[i][j] : grid[j][i];
                    if (cell != color) {
                        return false;
                    }
                }

                if (color != prevColor) {
                    // Transition to a new band
                    if (i > 0 && currentBandSize != expectedBandSize) {
                        return false;
                    }
                    currentBandSize = 1;
                    prevColor = color;
                    colors.add(color);
                } else {
                    currentBandSize++;
                }
            }

            // Verify the last band's size matches the expected size
            if (currentBandSize != expectedBandSize) {
                return false;
            }

            // Ensure exactly 3 distinct colors (R, G, B) are used
            return colors.size() == 3 && colors.contains('R') && colors.contains('G') && colors.contains('B');
        }
    }

    static class InputReader {
        public BufferedReader reader;
        public StringTokenizer tokenizer;

        public InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            String s = next();
            return s == null ? 0 : Integer.parseInt(s);
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

public class Main {
    private static final int STRIPE_COUNT = 3;

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out);
        try {
            boolean result = solve(scanner);
            out.println(result ? "YES" : "NO");
        } finally {
            out.flush();
        }
    }

    /**
     * Reads the grid and checks if it satisfies either horizontal or vertical stripe conditions.
     */
    private static boolean solve(FastScanner in) {
        int n = in.nextInt();
        int m = in.nextInt();
        char[][] grid = new char[n][];
        for (int i = 0; i < n; i++) {
            grid[i] = in.next().toCharArray();
        }

        // Short-circuit OR ensures vertical check is skipped if horizontal already passes
        return checkHorizontal(grid, n, m) || checkVertical(grid, n, m);
    }

    /**
     * Checks if the grid can be divided into STRIPE_COUNT horizontal stripes,
     * where each stripe is uniform and all stripes have different characters.
     */
    private static boolean checkHorizontal(char[][] grid, int n, int m) {
        if (n % STRIPE_COUNT != 0) return false;

        int stripeHeight = n / STRIPE_COUNT;
        char[] stripeChars = new char[STRIPE_COUNT];

        for (int i = 0; i < STRIPE_COUNT; i++) {
            int rowStart = i * stripeHeight;
            char expected = grid[rowStart][0];
            stripeChars[i] = expected;

            // Verify that the entire stripe contains only the expected character
            for (int r = rowStart; r < rowStart + stripeHeight; r++) {
                for (int c = 0; c < m; c++) {
                    if (grid[r][c] != expected) {
                        return false;
                    }
                }
            }
        }

        // Verify that all three stripes have distinct characters
        return stripeChars[0] != stripeChars[1] &&
               stripeChars[0] != stripeChars[2] &&
               stripeChars[1] != stripeChars[2];
    }

    /**
     * Checks if the grid can be divided into STRIPE_COUNT vertical stripes,
     * where each stripe is uniform and all stripes have different characters.
     */
    private static boolean checkVertical(char[][] grid, int n, int m) {
        if (m % STRIPE_COUNT != 0) return false;

        int stripeWidth = m / STRIPE_COUNT;
        char[] stripeChars = new char[STRIPE_COUNT];

        for (int i = 0; i < STRIPE_COUNT; i++) {
            int colStart = i * stripeWidth;
            char expected = grid[0][colStart];
            stripeChars[i] = expected;

            // Verify that the entire stripe contains only the expected character
            for (int c = colStart; c < colStart + stripeWidth; c++) {
                for (int r = 0; r < n; r++) {
                    if (grid[r][c] != expected) {
                        return false;
                    }
                }
            }
        }

        // Verify that all three stripes have distinct characters
        return stripeChars[0] != stripeChars[1] &&
               stripeChars[0] != stripeChars[2] &&
               stripeChars[1] != stripeChars[2];
    }

    /**
     * Fast I/O helper for competitive programming environments.
     */
    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input", e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        long nextLong() {
            return Long.parseLong(next());
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Solution for problem P837B.
 * Checks if a grid can be divided into 3 equal horizontal or vertical sections,
 * each filled with a single distinct color from {'R', 'G', 'B'}.
 */
public class P837B {

    private static final Set<Character> VALID_COLORS = new HashSet<>(Arrays.asList('R', 'G', 'B'));

    /**
     * Checks if the grid satisfies the RGB block condition.
     * The grid must be divisible into 3 equal horizontal strips,
     * each filled with a single distinct color.
     */
    private boolean isGridValid(char[][] grid) {
        int rows = grid.length;
        if (rows == 0 || grid[0].length == 0) return false;
        int cols = grid[0].length;

        if (rows % 3 != 0) return false;

        int sectionHeight = rows / 3;
        Set<Character> usedColors = new HashSet<>();

        for (int i = 0; i < 3; i++) {
            int startRow = i * sectionHeight;
            char color = grid[startRow][0];

            // Validate color is allowed
            if (!VALID_COLORS.contains(color)) return false;
            // Ensure all three sections have distinct colors
            if (!usedColors.add(color)) return false;

            // Verify entire section matches the color
            for (int r = startRow; r < startRow + sectionHeight; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] != color) return false;
                }
            }
        }
        return true;
    }

    /**
     * Returns a new transposed version of the input grid.
     */
    private char[][] transpose(char[][] grid) {
        int rows = grid.length;
        int cols = grid[0].length;
        char[][] transposed = new char[cols][rows];
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                transposed[j][i] = grid[i][j];
            }
        }
        return transposed;
    }

    /**
     * Reads input, evaluates the grid, and prints the result.
     */
    public void solve() throws IOException {
        int n = nextInt();
        int m = nextInt(); // m is read for compatibility but unused in logic
        char[][] grid = new char[n][];
        for (int i = 0; i < n; i++) {
            grid[i] = next().toCharArray();
        }

        boolean result = isGridValid(grid) || isGridValid(transpose(grid));
        println(result ? "YES" : "NO");
    }

    public static void main(String[] args) throws IOException {
        long startTime = System.currentTimeMillis();
        br = new BufferedReader(new InputStreamReader(System.in));
        pw = new PrintWriter(new BufferedOutputStream(System.out));
        stok = new StringTokenizer(""); // Initialize to avoid NPE on first call

        new P837B().solve();

        pw.flush();
        pw.close();
        br.close();

        System.err.println("\n[Time : " + (System.currentTimeMillis() - startTime) + " ms]");
    }

    // ================= I/O HELPERS =================
    static BufferedReader br;
    static PrintWriter pw;
    static StringTokenizer stok;

    String nextToken() throws IOException {
        while (stok == null || !stok.hasMoreTokens()) {
            String line = br.readLine();
            if (line == null) return null;
            stok = new StringTokenizer(line);
        }
        return stok.nextToken();
    }

    int nextInt() throws IOException { return Integer.parseInt(nextToken()); }
    long nextLong() throws IOException { return Long.parseLong(nextToken()); }
    double nextDouble() throws IOException { return Double.parseDouble(nextToken()); }
    String next() throws IOException { return nextToken(); }
    String nextLine() throws IOException { return br.readLine(); }
    char nextChar() throws IOException { return (char) br.read(); }

    int[] readInt(int size) throws IOException {
        int[] array = new int[size];
        for (int i = 0; i < size; i++) array[i] = nextInt();
        return array;
    }

    long[] readLong(int size) throws IOException {
        long[] array = new long[size];
        for (int i = 0; i < size; i++) array[i] = nextLong();
        return array;
    }

    double[] readDouble(int size) throws IOException {
        double[] array = new double[size];
        for (int i = 0; i < size; i++) array[i] = nextDouble();
        return array;
    }

    String[] readLines(int size) throws IOException {
        String[] array = new String[size];
        for (int i = 0; i < size; i++) array[i] = nextLine();
        return array;
    }

    // Simplified print/println methods. Delegating to PrintWriter directly
    // avoids redundant string conversions and instanceof chains.
    void print(Object o) { pw.print(String.valueOf(o)); }
    void println(Object o) { println(String.valueOf(o)); }
    void println() { pw.println(); }
    void println(String s) { pw.println(s); }

    // ================= MATH HELPERS =================
    int gcd(int a, int b) {
        while (b != 0) {
            int temp = b;
            b = a % b;
            a = temp;
        }
        return Math.abs(a);
    }

    long gcd(long a, long b) {
        while (b != 0) {
            long temp = b;
            b = a % b;
            a = temp;
        }
        return Math.abs(a);
    }
}

import java.io.IOException;
import java.io.InputStream;
import java.io.OutputStream;
import java.io.PrintWriter;
import java.util.InputMismatchException;

public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        new TaskB().solve(in, out);
        out.close();
    }

    static class TaskB {
        public void solve(InputReader in, PrintWriter out) {
            int n = in.readInt();
            int m = in.readInt();

            char[][] data = new char[n][m];
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    data[i][j] = in.readCharacter();
                }
            }

            char[][] rev = new char[m][n];
            for (int i = 0; i < m; i++) {
                for (int j = 0; j < n; j++) {
                    rev[i][j] = data[j][i];
                }
            }

            if (isVertical(data, n, m) || isVertical(rev, m, n)) {
                out.println("YES");
            } else {
                out.println("NO");
            }
        }

        private static boolean isVertical(char[][] grid, int rows, int cols) {
            if (rows == 0 || rows % 3 != 0) {
                return false;
            }

            int blockHeight = rows / 3;
            char[] blockChars = new char[3];

            for (int i = 0; i < 3; i++) {
                char src = grid[i * blockHeight][0];
                blockChars[i] = src;
                for (int r = i * blockHeight; r < (i + 1) * blockHeight; r++) {
                    for (int c = 0; c < cols; c++) {
                        if (grid[r][c] != src) {
                            return false;
                        }
                    }
                }
            }

            boolean hasR = false, hasG = false, hasB = false;
            for (char ch : blockChars) {
                if (ch == 'R') hasR = true;
                else if (ch == 'G') hasG = true;
                else if (ch == 'B') hasB = true;
            }

            return hasR && hasG && hasB;
        }
    }

    static class InputReader {
        private final InputStream stream;
        private final byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        public int read() {
            if (numChars == -1) {
                throw new InputMismatchException();
            }
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0) {
                    return -1;
                }
            }
            return buf[curChar++];
        }

        public int readInt() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                res *= 10;
                res += c - '0';
                c = read();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public static boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        public char readCharacter() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            return (char) c;
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.HashSet;
import java.util.Set;
import java.util.StringTokenizer;

public class Major {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line = br.readLine();
        if (line == null) return;

        StringTokenizer st = new StringTokenizer(line);
        int rows = Integer.parseInt(st.nextToken());
        int cols = Integer.parseInt(st.nextToken());

        char[][] grid = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            String rowStr = br.readLine();
            for (int j = 0; j < cols && j < rowStr.length(); j++) {
                grid[i][j] = rowStr.charAt(j);
            }
        }

        // If neither dimension is divisible by 3, it's impossible to divide into 3 equal parts
        if (rows % 3 != 0 && cols % 3 != 0) {
            System.out.println("NO");
            return;
        }

        boolean isPossible = false;
        if (rows % 3 == 0) {
            isPossible = checkHorizontalBands(grid, rows, cols);
        }

        if (!isPossible && cols % 3 == 0) {
            isPossible = checkVerticalBands(grid, rows, cols);
        }

        System.out.println(isPossible ? "YES" : "NO");
    }

    /**
     * Checks if the grid can be divided into 3 horizontal bands of equal height,
     * where each band is monochromatic and the set of colors is exactly {'R', 'G', 'B'}.
     */
    private static boolean checkHorizontalBands(char[][] grid, int rows, int cols) {
        Set<Character> foundChars = new HashSet<>();
        int bandHeight = rows / 3;

        for (int i = 0; i < 3; i++) {
            int startRow = i * bandHeight;
            char bandChar = grid[startRow][0];

            // Verify that all cells in this band match the first character
            for (int r = startRow; r < startRow + bandHeight; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] != bandChar) {
                        return false;
                    }
                }
            }
            foundChars.add(bandChar);
        }

        // Ensure the three bands contain exactly R, G, and B
        return foundChars.contains('R') && foundChars.contains('G') && foundChars.contains('B');
    }

    /**
     * Checks if the grid can be divided into 3 vertical bands of equal width,
     * where each band is monochromatic and the set of colors is exactly {'R', 'G', 'B'}.
     */
    private static boolean checkVerticalBands(char[][] grid, int rows, int cols) {
        Set<Character> foundChars = new HashSet<>();
        int bandWidth = cols / 3;

        for (int i = 0; i < 3; i++) {
            int startCol = i * bandWidth;
            char bandChar = grid[0][startCol];

            // Verify that all cells in this band match the first character
            for (int c = startCol; c < startCol + bandWidth; c++) {
                for (int r = 0; r < rows; r++) {
                    if (grid[r][c] != bandChar) {
                        return false;
                    }
                }
            }
            foundChars.add(bandChar);
        }

        // Ensure the three bands contain exactly R, G, and B
        return foundChars.contains('R') && foundChars.contains('G') && foundChars.contains('B');
    }
}

import java.util.Arrays;
import java.util.Scanner;

public class Works {
    // Extracted constants for readability and easy maintenance
    private static final char COLOR_RED = 'R';
    private static final char COLOR_GREEN = 'G';
    private static final char COLOR_BLUE = 'B';
    private static final int NUM_COLORS = 3;

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        if (!scanner.hasNextInt()) {
            return;
        }

        int n = scanner.nextInt();
        int m = scanner.nextInt();

        // Use a 2D character array for clear grid representation
        char[][] grid = new char[n][m];
        for (int i = 0; i < n; i++) {
            String line = scanner.next();
            grid[i] = line.toCharArray();
        }

        boolean isValid = isValidColors(grid) && (isHorizontalFlag(grid) || isVerticalFlag(grid));
        System.out.println(isValid ? "YES" : "NO");

        scanner.close();
    }

    /**
     * Validates that the grid only contains R, G, B characters
     * and that each color appears exactly 1/3 of the total cells.
     */
    private static boolean isValidColors(char[][] grid) {
        int totalCells = grid.length * grid[0].length;
        if (totalCells % NUM_COLORS != 0) {
            return false;
        }
        int targetCount = totalCells / NUM_COLORS;
        int rCount = 0, gCount = 0, bCount = 0;

        for (char[] row : grid) {
            for (char c : row) {
                switch (c) {
                    case COLOR_RED: rCount++; break;
                    case COLOR_GREEN: gCount++; break;
                    case COLOR_BLUE: bCount++; break;
                    default: return false; // Reject invalid characters immediately
                }
            }
        }
        return rCount == targetCount && gCount == targetCount && bCount == targetCount;
    }

    /**
     * Checks if the grid forms a horizontal flag:
     * 1. All rows must be identical.
     * 2. Each row must consist of three equal-length uniform color segments.
     */
    private static boolean isHorizontalFlag(char[][] grid) {
        int rows = grid.length;
        int cols = grid[0].length;

        if (cols % NUM_COLORS != 0) {
            return false;
        }
        int segmentLength = cols / NUM_COLORS;

        // Verify all rows are identical
        for (int r = 1; r < rows; r++) {
            if (!Arrays.equals(grid[0], grid[r])) {
                return false;
            }
        }

        // Verify the first row has three uniform color segments
        char c1 = grid[0][0];
        char c2 = grid[0][segmentLength];
        char c3 = grid[0][2 * segmentLength];

        for (int i = 0; i < cols; i++) {
            char expected = (i < segmentLength) ? c1 : (i < 2 * segmentLength) ? c2 : c3;
            if (grid[0][i] != expected) {
                return false;
            }
        }
        return true;
    }

    /**
     * Checks if the grid forms a vertical flag:
     * 1. All columns must be identical.
     * 2. Each column must consist of three equal-length uniform color segments.
     */
    private static boolean isVerticalFlag(char[][] grid) {
        int rows = grid.length;
        int cols = grid[0].length;

        if (rows % NUM_COLORS != 0) {
            return false;
        }
        int segmentLength = rows / NUM_COLORS;

        // Verify all columns are identical to the first column
        for (int c = 1; c < cols; c++) {
            for (int r = 0; r < rows; r++) {
                if (grid[r][0] != grid[r][c]) {
                    return false;
                }
            }
        }

        // Verify the first column has three uniform color segments
        char c1 = grid[0][0];
        char c2 = grid[segmentLength][0];
        char c3 = grid[2 * segmentLength][0];

        for (int r = 0; r < rows; r++) {
            char expected = (r < segmentLength) ? c1 : (r < 2 * segmentLength) ? c2 : c3;
            if (grid[r][0] != expected) {
                return false;
            }
        }
        return true;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.HashSet;
import java.util.Set;
import java.util.StringTokenizer;

public class Main {
    public static void main(String[] args) {
        FastScanner scanner = new FastScanner();
        int n = scanner.nextInt();
        int m = scanner.nextInt();

        char[][] grid = new char[n][];
        for (int i = 0; i < n; i++) {
            grid[i] = scanner.next().toCharArray();
        }

        boolean horizontalPossible = canDivideIntoThreeUniformStrips(grid, n, true);
        boolean verticalPossible = canDivideIntoThreeUniformStrips(grid, m, false);

        System.out.println(horizontalPossible || verticalPossible ? "YES" : "NO");
    }

    /**
     * Checks if the grid can be divided into three equal strips (rows or columns)
     * where each strip contains exactly one unique character, and all three characters are distinct.
     */
    private static boolean canDivideIntoThreeUniformStrips(char[][] grid, int dimension, boolean byRows) {
        if (dimension % 3 != 0) {
            return false;
        }
        int step = dimension / 3;

        Set<Character> firstStrip = collectUniqueChars(grid, 0, step, byRows);
        Set<Character> secondStrip = collectUniqueChars(grid, step, 2 * step, byRows);
        Set<Character> thirdStrip = collectUniqueChars(grid, 2 * step, dimension, byRows);

        if (firstStrip.size() != 1 || secondStrip.size() != 1 || thirdStrip.size() != 1) {
            return false;
        }

        char char1 = firstStrip.iterator().next();
        char char2 = secondStrip.iterator().next();
        char char3 = thirdStrip.iterator().next();

        return char1 != char2 && char1 != char3 && char2 != char3;
    }

    /**
     * Collects all unique characters within a specified range of rows or columns.
     */
    private static Set<Character> collectUniqueChars(char[][] grid, int start, int end, boolean byRows) {
        Set<Character> uniqueChars = new HashSet<>();
        if (byRows) {
            for (int r = start; r < end; r++) {
                for (char ch : grid[r]) {
                    uniqueChars.add(ch);
                }
            }
        } else {
            for (int c = start; c < end; c++) {
                for (char[] row : grid) {
                    uniqueChars.add(row[c]);
                }
            }
        }
        return uniqueChars;
    }

    /**
     * Fast I/O helper class for competitive programming environments.
     */
    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            String token = next();
            if (token == null) throw new RuntimeException("Unexpected end of input");
            return Integer.parseInt(token);
        }
    }
}

import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.InputMismatchException;

/**
 * Solution for problem B837.
 * Determines if a grid of strings can be divided into three equal contiguous blocks
 * (either horizontally or vertically) where each block consists of identical strings,
 * and the three blocks have distinct string values. Each string must also be uniform.
 */
public class B837 {
    public static void main(String[] args) {
        InputReader in = new InputReader();
        PrintWriter out = new PrintWriter(System.out);
        new Task().solve(in, out);
        out.close();
    }

    static class Task {
        public void solve(InputReader in, PrintWriter out) {
            int n = in.nextInt();
            int m = in.nextInt();

            String[] rows = new String[n];
            for (int i = 0; i < n; i++) {
                rows[i] = in.next();
            }

            boolean possible = false;

            // Check horizontal split
            if (n % 3 == 0 && canDivideIntoThreeBlocks(rows)) {
                possible = true;
            }
            // Check vertical split
            else if (m % 3 == 0) {
                String[] cols = new String[m];
                for (int j = 0; j < m; j++) {
                    StringBuilder sb = new StringBuilder(n);
                    for (int i = 0; i < n; i++) {
                        sb.append(rows[i].charAt(j));
                    }
                    cols[j] = sb.toString();
                }
                if (canDivideIntoThreeBlocks(cols)) {
                    possible = true;
                }
            }

            out.println(possible ? "YES" : "NO");
        }

        /**
         * Checks if an array of strings can be divided into three equal contiguous blocks.
         * Conditions:
         * 1. Array length must be divisible by 3.
         * 2. All strings within each block must be identical.
         * 3. Each string must be uniform (all characters identical).
         * 4. The three block representatives must be distinct.
         */
        private boolean canDivideIntoThreeBlocks(String[] array) {
            int size = array.length;
            int blockSize = size / 3;

            String rep1 = array[0];
            String rep2 = array[blockSize];
            String rep3 = array[2 * blockSize];

            // Representatives must be uniform
            if (!isUniform(rep1) || !isUniform(rep2) || !isUniform(rep3)) {
                return false;
            }

            // All strings in each block must match their representative
            for (int i = 0; i < size; i++) {
                String expected;
                if (i < blockSize) expected = rep1;
                else if (i < 2 * blockSize) expected = rep2;
                else expected = rep3;

                if (!array[i].equals(expected)) {
                    return false;
                }
            }

            // The three block representatives must be distinct
            return !rep1.equals(rep2) && !rep2.equals(rep3) && !rep3.equals(rep1);
        }

        /**
         * Checks if a string consists of only one unique character.
         */
        private boolean isUniform(String s) {
            if (s.isEmpty()) return true;
            char first = s.charAt(0);
            for (int i = 1; i < s.length(); i++) {
                if (s.charAt(i) != first) {
                    return false;
                }
            }
            return true;
        }
    }

    /**
     * Fast input reader for competitive programming environments.
     */
    static class InputReader {
        final InputStream stream;
        final byte[] buf = new byte[8192];
        int curChar, numChars;
        SpaceCharFilter filter;

        public InputReader() {
            this.stream = System.in;
        }

        public int read() {
            if (numChars == -1) throw new InputMismatchException();
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0) return -1;
            }
            return buf[curChar++];
        }

        public int nextInt() {
            int c = read();
            while (isSpaceChar(c)) c = read();
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9') throw new InputMismatchException();
                res *= 10;
                res += c - '0';
                c = read();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public long nextLong() {
            int c = read();
            while (isSpaceChar(c)) c = read();
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            long res = 0;
            do {
                if (c < '0' || c > '9') throw new InputMismatchException();
                res *= 10;
                res += c - '0';
                c = read();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public String next() {
            int c = read();
            while (isSpaceChar(c)) c = read();
            StringBuilder res = new StringBuilder();
            do {
                res.appendCodePoint(c);
                c = read();
            } while (!isSpaceChar(c));
            return res.toString();
        }

        public boolean isSpaceChar(int c) {
            if (filter != null) return filter.isSpaceChar(c);
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        @FunctionalInterface
        public interface SpaceCharFilter {
            boolean isSpaceChar(int ch);
        }
    }
}

import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        if (!scanner.hasNextInt()) {
            return;
        }

        int rows = scanner.nextInt();
        int cols = scanner.nextInt();
        scanner.nextLine(); // Consume the newline after the second integer

        char[][] grid = new char[rows][cols];
        int[] charCounts = new int[3]; // Index 0: R, 1: G, 2: B

        for (int i = 0; i < rows; i++) {
            String line = scanner.nextLine().trim();
            grid[i] = line.toCharArray();
            for (char c : grid[i]) {
                if (c == 'R') charCounts[0]++;
                else if (c == 'G') charCounts[1]++;
                else if (c == 'B') charCounts[2]++;
            }
        }

        // Condition 1: The counts of 'R', 'G', and 'B' must be equal
        if (charCounts[0] != charCounts[1] || charCounts[1] != charCounts[2]) {
            System.out.println("NO");
            return;
        }

        // Condition 2: The grid must be perfectly partitionable into 3 equal monochromatic rectangles
        if (canPartitionIntoThree(grid, rows, cols)) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }
    }

    /**
     * Determines if the grid can be split into exactly three equal-sized, monochromatic rectangles.
     * Checks both horizontal (side-by-side) and vertical (stacked) orientations.
     */
    private static boolean canPartitionIntoThree(char[][] grid, int rows, int cols) {
        char firstChar = grid[0][0];

        // Determine the dimensions of the first contiguous block starting at (0, 0)
        int blockWidth = 0;
        while (blockWidth < cols && grid[0][blockWidth] == firstChar) {
            blockWidth++;
        }

        int blockHeight = 0;
        while (blockHeight < rows && grid[blockHeight][0] == firstChar) {
            blockHeight++;
        }

        // Check for horizontal stacking (3 blocks side-by-side)
        if (cols == 3 * blockWidth && rows == blockHeight) {
            return isThreeMonochromaticBlocks(grid, blockHeight, blockWidth, Orientation.HORIZONTAL);
        }

        // Check for vertical stacking (3 blocks stacked vertically)
        if (rows == 3 * blockHeight && cols == blockWidth) {
            return isThreeMonochromaticBlocks(grid, blockHeight, blockWidth, Orientation.VERTICAL);
        }

        return false;
    }

    private enum Orientation {
        HORIZONTAL, VERTICAL
    }

    /**
     * Verifies that three blocks of the specified size and orientation are monochromatic.
     */
    private static boolean isThreeMonochromaticBlocks(char[][] grid, int blockHeight, int blockWidth,
                                                      Orientation orientation) {
        // Define starting coordinates for the three blocks based on orientation
        int[][] startPositions;
        if (orientation == Orientation.HORIZONTAL) {
            startPositions = new int[][]{
                {0, 0},
                {0, blockWidth},
                {0, 2 * blockWidth}
            };
        } else {
            startPositions = new int[][]{
                {0, 0},
                {blockHeight, 0},
                {2 * blockHeight, 0}
            };
        }

        // Verify each block is monochromatic
        for (int[] pos : startPositions) {
            if (!isMonochromatic(grid, pos[0], pos[1], blockHeight, blockWidth)) {
                return false;
            }
        }
        return true;
    }

    /**
     * Checks if a rectangular region in the grid contains only the character at its top-left corner.
     */
    private static boolean isMonochromatic(char[][] grid, int r, int c, int h, int w) {
        char first = grid[r][c];
        for (int i = r; i < r + h; i++) {
            for (int j = c; j < c + w; j++) {
                if (grid[i][j] != first) {
                    return false;
                }
            }
        }
        return true;
    }
}

