public class ColorGridChecker {

    public static void main(String[] args) throws IOException {
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
             PrintWriter out = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)))) {

            FastScanner scanner = new FastScanner(br);
            int n = scanner.nextInt();
            int m = scanner.nextInt();

            char[][] grid = new char[n][m];
            int rCount = 0, gCount = 0, bCount = 0;

            // Read grid and count character frequencies in a single pass
            for (int i = 0; i < n; i++) {
                String row = scanner.next();
                grid[i] = row.toCharArray();
                for (char c : grid[i]) {
                    if (c == 'R') rCount++;
                    else if (c == 'G') gCount++;
                    else bCount++;
                }
            }

            // Check frequency constraint first
            if (rCount != gCount || gCount != bCount) {
                out.println("NO");
            } else if (n % 3 == 0 && isUniformBands(grid, n, m, true)) {
                out.println("YES");
            } else if (m % 3 == 0 && isUniformBands(grid, n, m, false)) {
                out.println("YES");
            } else {
                out.println("NO");
            }
        }
        // PrintWriter and BufferedReader are automatically closed and flushed here
    }

    /**
     * Checks if the grid is divided into 3 uniform bands either horizontally or vertically.
     *
     * @param grid      The character grid
     * @param n         Number of rows
     * @param m         Number of columns
     * @param horizontal true for horizontal bands, false for vertical bands
     * @return true if all cells in each band match the band's reference character
     */
    private static boolean isUniformBands(char[][] grid, int n, int m, boolean horizontal) {
        int blockSize = horizontal ? n / 3 : m / 3;

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                // Determine the reference cell for the current band
                int refI = horizontal ? i / blockSize * blockSize : 0;
                int refJ = horizontal ? 0 : j / blockSize * blockSize;

                if (grid[i][j] != grid[refI][refJ]) {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Fast input scanner for competitive programming / performance-critical I/O.
     */
    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner(BufferedReader br) {
            this.br = br;
        }

        public String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }

        public double nextDouble() {
            return Double.parseDouble(next());
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

public class GridValidator {
    private static final int NUM_BANDS = 3;

    public static void main(String[] args) throws IOException {
        // Use try-with-resources for automatic resource management
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(System.in))) {
            String line = reader.readLine();
            if (line == null || line.trim().isEmpty()) {
                return;
            }

            StringTokenizer tokenizer = new StringTokenizer(line);
            int rows = Integer.parseInt(tokenizer.nextToken());
            int cols = Integer.parseInt(tokenizer.nextToken());

            char[][] grid = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                String rowLine = reader.readLine();
                if (rowLine != null) {
                    grid[i] = rowLine.toCharArray();
                }
            }

            boolean isValidRowWise = validateUniformBands(grid, rows, cols, true);
            boolean isValidColumnWise = validateUniformBands(grid, rows, cols, false);

            System.out.println((isValidRowWise || isValidColumnWise) ? "YES" : "NO");
        }
    }

    /**
     * Validates if the grid consists of NUM_BANDS uniform horizontal or vertical bands
     * where each band contains a single repeated character and all bands have distinct characters.
     *
     * @param grid          The 2D character grid to validate
     * @param rows          Number of rows in the grid
     * @param cols          Number of columns in the grid
     * @param checkHorizontal True to check horizontal bands, false for vertical bands
     * @return true if the grid satisfies the band condition, false otherwise
     */
    private static boolean validateUniformBands(char[][] grid, int rows, int cols, boolean checkHorizontal) {
        if (rows <= 0 || cols <= 0) {
            return false;
        }

        int bandDimension = checkHorizontal ? rows : cols;

        // Grid dimension must be divisible by NUM_BANDS and at least NUM_BANDS
        if (bandDimension < NUM_BANDS || bandDimension % NUM_BANDS != 0) {
            return false;
        }

        int bandSize = bandDimension / NUM_BANDS;

        // Identify the representative character for each of the three bands
        char[] bandReps = new char[NUM_BANDS];
        for (int i = 0; i < NUM_BANDS; i++) {
            int startIndex = i * bandSize;
            bandReps[i] = checkHorizontal ? grid[startIndex][0] : grid[0][startIndex];
        }

        // Ensure all three bands have distinct representative characters
        if (bandReps[0] == bandReps[1] || bandReps[0] == bandReps[2] || bandReps[1] == bandReps[2]) {
            return false;
        }

        // Verify that every cell within each band matches its representative character
        for (int b = 0; b < NUM_BANDS; b++) {
            int start = b * bandSize;
            int end = (b + 1) * bandSize;

            for (int i = start; i < end; i++) {
                for (int j = 0; j < (checkHorizontal ? cols : rows); j++) {
                    char currentChar = checkHorizontal ? grid[i][j] : grid[j][i];
                    if (currentChar != bandReps[b]) {
                        return false;
                    }
                }
            }
        }

        return true;
    }
}

