    /**
     * Validates if all rows are uniform and the counts of 'R', 'G', and 'B' are equal.
     */
    private static boolean validateRows(int n, int m, char[][] grid) {
        int[] charCounts = new int[26];
        for (int i = 0; i < n; i++) {
            char firstChar = grid[i][0];
            for (int j = 1; j < m; j++) {
                if (grid[i][j] != firstChar) {
                    return false; // Row contains mixed characters
                }
            }
            charCounts[firstChar - 'A']++;
        }
        return charCounts['R' - 'A'] == charCounts['G' - 'A'] &&
               charCounts['G' - 'A'] == charCounts['B' - 'A'];
    }

    /**
     * Validates if all columns are uniform and the counts of 'R', 'G', and 'B' are equal.
     */
    private static boolean validateColumns(int n, int m, char[][] grid) {
        int[] charCounts = new int[26];
        for (int j = 0; j < m; j++) {
            char firstChar = grid[0][j];
            for (int i = 1; i < n; i++) {
                if (grid[i][j] != firstChar) {
                    return false; // Column contains mixed characters
                }
            }
            charCounts[firstChar - 'A']++;
        }
        return charCounts['R' - 'A'] == charCounts['G' - 'A'] &&
               charCounts['G' - 'A'] == charCounts['B' - 'A'];
    }

