import java.io.PrintWriter;
import java.util.HashSet;
import java.util.Scanner;
import java.util.Set;

/**
 * Refactored version of the original Tester program.
 * 
 * Key Improvements:
 * 1. Removed dead code: `mod`, `debug`, `exp`, `Pair`, and unused imports.
 * 2. Replaced custom `InputReader` with standard `java.util.Scanner` for better maintainability.
 * 3. Renamed `rotate` to `transpose` to accurately reflect the matrix operation.
 * 4. Simplified `check` into `isValid` using direct character comparison, eliminating redundant 
 *    `HashSet`/`TreeSet` overhead and reducing time/space complexity.
 * 5. Applied try-with-resources for automatic stream management.
 * 6. Improved naming conventions and added JavaDoc comments for clarity.
 */
public class Tester {
    private static final int STRIP_COUNT = 3;

    public static void main(String[] args) {
        // Auto-close scanner and PrintWriter when done
        try (Scanner scanner = new Scanner(System.in);
             PrintWriter out = new PrintWriter(System.out)) {

            if (!scanner.hasNextInt()) {
                return;
            }
            int n = scanner.nextInt();
            int m = scanner.nextInt();
            scanner.nextLine(); // Consume the newline after the second integer

            char[][] grid = new char[n][m];
            for (int i = 0; i < n; i++) {
                String line = scanner.nextLine().trim();
                // Skip potential empty lines caused by trailing newlines or formatting
                while (line.isEmpty() && scanner.hasNextLine()) {
                    line = scanner.nextLine().trim();
                }
                grid[i] = line.toCharArray();
            }

            // Check original grid and its transposed version
            if (isValid(grid) || isValid(transpose(grid))) {
                out.println("YES");
            } else {
                out.println("NO");
            }
        }
    }

    /**
     * Transposes the given 2D character array.
     * Note: The original implementation performed a matrix transpose, not a 90-degree rotation.
     */
    private static char[][] transpose(char[][] grid) {
        int n = grid.length;
        int m = grid[0].length;
        char[][] result = new char[m][n];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                result[j][i] = grid[i][j];
            }
        }
        return result;
    }

    /**
     * Validates if the grid can be divided into 3 equal horizontal strips,
     * where each strip contains only a single repeated character, and all 3
     * characters are distinct.
     */
    private static boolean isValid(char[][] grid) {
        int n = grid.length;
        if (n % STRIP_COUNT != 0) {
            return false;
        }

        int stripHeight = n / STRIP_COUNT;
        Set<Character> distinctChars = new HashSet<>();

        for (int i = 0; i < STRIP_COUNT; i++) {
            int startRow = i * stripHeight;
            char firstChar = grid[startRow][0];

            // Verify that every character in the current strip matches the first one
            for (int row = startRow; row < startRow + stripHeight; row++) {
                for (char c : grid[row]) {
                    if (c != firstChar) {
                        return false;
                    }
                }
            }
            distinctChars.add(firstChar);
        }

        // All 3 strips must have different characters
        return distinctChars.size() == STRIP_COUNT;
    }
}

import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        if (!scanner.hasNextInt()) return;

        int n = scanner.nextInt();
        int m = scanner.nextInt();
        scanner.nextLine(); // Consume the newline character left by nextInt()

        String[] grid = new String[n];
        for (int i = 0; i < n; i++) {
            grid[i] = scanner.nextLine();
        }

        boolean rowsUniform = areAllRowsUniform(grid);

        if (!rowsUniform) {
            boolean colsUniform = areAllColsUniform(grid, m);
            if (!colsUniform) {
                System.out.println("NO");
            } else {
                System.out.println(checkPattern(grid[0]) ? "YES" : "NO");
            }
        } else {
            System.out.println(checkPattern(getFirstColumn(grid)) ? "YES" : "NO");
        }
    }

    /**
     * Checks if every row in the grid consists of identical characters.
     */
    private static boolean areAllRowsUniform(String[] grid) {
        for (String row : grid) {
            if (!isUniform(row)) {
                return false;
            }
        }
        return true;
    }

    /**
     * Checks if every column in the grid consists of identical characters.
     */
    private static boolean areAllColsUniform(String[] grid, int m) {
        for (int j = 0; j < m; j++) {
            StringBuilder col = new StringBuilder();
            for (String row : grid) {
                col.append(row.charAt(j));
            }
            if (!isUniform(col.toString())) {
                return false;
            }
        }
        return true;
    }

    /**
     * Extracts the first column of the grid as a single string.
     */
    private static String getFirstColumn(String[] grid) {
        StringBuilder col = new StringBuilder();
        for (String row : grid) {
            col.append(row.charAt(0));
        }
        return col.toString();
    }

    /**
     * Determines if all characters in the string are identical.
     */
    private static boolean isUniform(String s) {
        if (s.isEmpty()) {
            return true;
        }
        char first = s.charAt(0);
        for (int i = 1; i < s.length(); i++) {
            if (s.charAt(i) != first) {
                return false;
            }
        }
        return true;
    }

    /**
     * Validates the pattern sequence: each of 'R', 'G', 'B' appears at most once,
     * and they appear in equal quantities.
     */
    private static boolean checkPattern(String sequence) {
        int countR = 0, countG = 0, countB = 0;
        boolean seenR = false, seenG = false, seenB = false;

        for (int i = 0; i < sequence.length(); i++) {
            char c = sequence.charAt(i);
            if (c == 'R') {
                if (seenR) return false;
                seenR = true;
                countR++;
            } else if (c == 'G') {
                if (seenG) return false;
                seenG = true;
                countG++;
            } else if (c == 'B') {
                if (seenB) return false;
                seenB = true;
                countB++;
            }
        }
        return countR == countG && countG == countB;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.HashSet;
import java.util.Set;
import java.util.StringTokenizer;

public class CFEdu26B {

    public static void main(String[] args) {
        FastScanner sc = new FastScanner();
        PrintWriter out = new PrintWriter(System.out);

        try {
            int n = sc.nextInt();
            int m = sc.nextInt();
            char[][] grid = new char[n][m];

            for (int i = 0; i < n; i++) {
                grid[i] = sc.next().toCharArray();
            }

            boolean possible = checkRGBStripes(grid, true) || checkRGBStripes(grid, false);
            out.println(possible ? "YES" : "NO");
        } finally {
            out.flush();
        }
    }

    /**
     * Checks if the grid can be divided into three equal stripes along the specified axis,
     * where each stripe contains exactly one unique character, and the three characters
     * form a permutation of {'R', 'G', 'B'}.
     *
     * @param grid      The input character matrix
     * @param horizontal true to check horizontal stripes, false for vertical
     * @return true if the condition is met, false otherwise
     */
    private static boolean checkRGBStripes(char[][] grid, boolean horizontal) {
        int n = grid.length;
        int m = grid[0].length;
        int chunkSize = horizontal ? n : m;

        if (chunkSize % 3 != 0) {
            return false;
        }
        chunkSize /= 3;

        Set<Character> set1 = new HashSet<>();
        Set<Character> set2 = new HashSet<>();
        Set<Character> set3 = new HashSet<>();

        for (int k = 0; k < 3; k++) {
            Set<Character> target = (k == 0) ? set1 : (k == 1) ? set2 : set3;
            int start = k * chunkSize;
            int end = (k + 1) * chunkSize;

            for (int i = start; i < end; i++) {
                if (horizontal) {
                    for (char c : grid[i]) {
                        target.add(c);
                    }
                } else {
                    for (int j = 0; j < n; j++) {
                        target.add(grid[j][i]);
                    }
                }
            }
        }

        // Each stripe must contain exactly one unique character type
        if (set1.size() != 1 || set2.size() != 1 || set3.size() != 1) {
            return false;
        }

        // Verify the three characters form the set {'R', 'G', 'B'}
        Set<Character> foundColors = new HashSet<>();
        foundColors.add(set1.iterator().next());
        foundColors.add(set2.iterator().next());
        foundColors.add(set3.iterator().next());

        return foundColors.contains('R') && foundColors.contains('G') && foundColors.contains('B');
    }

    /**
     * Fast I/O helper class for competitive programming.
     * Fixes the tokenization bug present in the original InputReader.
     */
    private static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        public String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            String s = next();
            if (s == null) throw new RuntimeException("Unexpected end of input");
            return Integer.parseInt(s);
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

public class ColorGridValidator {

    public static void main(String[] args) throws IOException {
        // Use try-with-resources to ensure the stream is closed automatically
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            String line = br.readLine();
            if (line == null || line.trim().isEmpty()) {
                return;
            }

            // StringTokenizer is more robust than split(" ") for whitespace handling
            StringTokenizer st = new StringTokenizer(line);
            int n = Integer.parseInt(st.nextToken());
            int m = Integer.parseInt(st.nextToken());

            char[][] grid = new char[n][m];
            for (int i = 0; i < n; i++) {
                String row = br.readLine();
                if (row != null) {
                    grid[i] = row.toCharArray();
                }
            }

            // If neither dimension is divisible by 3, it's impossible to form 3 equal stripes
            if (n % 3 != 0 && m % 3 != 0) {
                System.out.println("NO");
                return;
            }

            // Simplified boolean logic: valid if either orientation passes
            boolean isValid = checkStripes(grid, true) || checkStripes(grid, false);
            System.out.println(isValid ? "YES" : "NO");
        }
    }

    /**
     * Validates if the grid forms valid horizontal or vertical stripes.
     * Each stripe must consist of a single color, each color (R, G, B) must appear exactly once,
     * and all stripes must be of equal size.
     */
    private static boolean checkStripes(char[][] grid, boolean horizontal) {
        int[] colorCounts = new int[3]; // 0: R, 1: G, 2: B
        boolean[] colorSeen = new boolean[3];
        char previousColor = 0;

        if (horizontal) {
            for (int i = 0; i < grid.length; i++) {
                char currentColor = grid[i][0];
                int colorIndex = getColorIndex(currentColor);
                if (colorIndex == -1) return false; // Invalid character encountered

                if (currentColor != previousColor) {
                    if (colorSeen[colorIndex]) {
                        return false; // Color already used in a previous stripe
                    }
                    colorSeen[colorIndex] = true;
                    previousColor = currentColor;
                }

                // Verify the entire row consists of the same color
                for (int j = 1; j < grid[i].length; j++) {
                    if (grid[i][j] != currentColor) {
                        return false;
                    }
                }

                colorCounts[colorIndex]++;
            }
        } else {
            for (int j = 0; j < grid[0].length; j++) {
                char currentColor = grid[0][j];
                int colorIndex = getColorIndex(currentColor);
                if (colorIndex == -1) return false;

                if (currentColor != previousColor) {
                    if (colorSeen[colorIndex]) {
                        return false;
                    }
                    colorSeen[colorIndex] = true;
                    previousColor = currentColor;
                }

                // Verify the entire column consists of the same color
                for (int i = 1; i < grid.length; i++) {
                    if (grid[i][j] != currentColor) {
                        return false;
                    }
                }

                colorCounts[colorIndex]++;
            }
        }

        // All three colors must appear exactly the same number of times
        return colorCounts[0] == colorCounts[1] && colorCounts[1] == colorCounts[2];
    }

    /**
     * Maps color characters to array indices for fast lookup.
     */
    private static int getColorIndex(char c) {
        switch (c) {
            case 'R': return 0;
            case 'G': return 1;
            case 'B': return 2;
            default: return -1;
        }
    }
}

import java.util.Scanner;

/**
 * A program to determine if a given grid represents a flag with 3 distinct stripes.
 * The stripes can be arranged either vertically (splitting columns) or horizontally (splitting rows).
 */
public class FlagChecker {

    /**
     * Checks if a rectangular region of the grid is uniform (all characters are the same).
     *
     * @param grid   The 2D character array representing the grid.
     * @param rStart The starting row index (inclusive).
     * @param rEnd   The ending row index (exclusive).
     * @param cStart The starting column index (inclusive).
     * @param cEnd   The ending column index (exclusive).
     * @return true if all characters in the specified region are identical, false otherwise.
     */
    private static boolean isUniform(char[][] grid, int rStart, int rEnd, int cStart, int cEnd) {
        // Handle invalid or empty ranges
        if (rStart >= rEnd || cStart >= cEnd) {
            return true;
        }

        // The target character is the first character in the region
        char target = grid[rStart][cStart];

        // Iterate through the region to check for uniformity
        for (int r = rStart; r < rEnd; r++) {
            for (int c = cStart; c < cEnd; c++) {
                if (grid[r][c] != target) {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Checks if three characters are distinct from each other.
     *
     * @param a First character.
     * @param b Second character.
     * @param c Third character.
     * @return true if a, b, and c are all different, false otherwise.
     */
    private static boolean areDistinct(char a, char b, char c) {
        return a != b && a != c && b != c;
    }

    /**
     * Checks if the grid forms 3 vertical stripes (splitting the columns into 3 equal parts).
     *
     * @param grid The 2D character array.
     * @param rows Number of rows in the grid.
     * @param cols Number of columns in the grid.
     * @return true if the grid has 3 vertical stripes, false otherwise.
     */
    private static boolean hasVerticalStripes(char[][] grid, int rows, int cols) {
        // A vertical split is only possible if the number of columns is divisible by 3
        if (cols % 3 != 0) {
            return false;
        }

        int width = cols / 3;

        // Check if the top row has 3 distinct colors for the stripes
        // We check indices 0, width, and 2*width in the first row
        if (!areDistinct(grid[0][0], grid[0][width], grid[0][2 * width])) {
            return false;
        }

        // Check if each vertical band is uniform in color
        // Band 1: Cols 0 to width
        boolean stripe1 = isUniform(grid, 0, rows, 0, width);
        // Band 2: Cols width to 2*width
        boolean stripe2 = isUniform(grid, 0, rows, width, 2 * width);
        // Band 3: Cols 2*width to 3*width (which is cols)
        boolean stripe3 = isUniform(grid, 0, rows, 2 * width, 3 * width);

        return stripe1 && stripe2 && stripe3;
    }

    /**
     * Checks if the grid forms 3 horizontal stripes (splitting the rows into 3 equal parts).
     *
     * @param grid The 2D character array.
     * @param rows Number of rows in the grid.
     * @param cols Number of columns in the grid.
     * @return true if the grid has 3 horizontal stripes, false otherwise.
     */
    private static boolean hasHorizontalStripes(char[][] grid, int rows, int cols) {
        // A horizontal split is only possible if the number of rows is divisible by 3
        if (rows % 3 != 0) {
            return false;
        }

        int height = rows / 3;

        // Check if the first column has 3 distinct colors for the stripes
        // We check indices 0, height, and 2*height in the first column
        if (!areDistinct(grid[0][0], grid[height][0], grid[2 * height][0])) {
            return false;
        }

        // Check if each horizontal band is uniform in color
        // Band 1: Rows 0 to height
        boolean stripe1 = isUniform(grid, 0, height, 0, cols);
        // Band 2: Rows height to 2*height
        boolean stripe2 = isUniform(grid, height, 2 * height, 0, cols);
        // Band 3: Rows 2*height to 3*height (which is rows)
        boolean stripe3 = isUniform(grid, 2 * height, 3 * height, 0, cols);

        return stripe1 && stripe2 && stripe3;
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        // Check if input is available
        if (!scanner.hasNextInt()) {
            scanner.close();
            return;
        }

        int rows = scanner.nextInt();
        int cols = scanner.nextInt();

        char[][] grid = new char[rows][cols];

        // Read the grid
        for (int i = 0; i < rows; i++) {
            if (scanner.hasNext()) {
                String line = scanner.next();
                // Fill the row. Assuming valid input where line length matches cols,
                // but checking length prevents IndexOutOfBoundsException.
                for (int j = 0; j < cols && j < line.length(); j++) {
                    grid[i][j] = line.charAt(j);
                }
            }
        }

        // Determine if the grid is a valid flag (either vertical or horizontal stripes)
        boolean isFlag = hasVerticalStripes(grid, rows, cols) || hasHorizontalStripes(grid, rows, cols);

        System.out.println(isFlag ? "YES" : "NO");

        scanner.close();
    }
}

import java.io.InputStream;
import java.io.OutputStream;
import java.io.PrintWriter;
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        Scanner in = new Scanner(inputStream);
        PrintWriter out = new PrintWriter(outputStream);

        TaskB solver = new TaskB();
        solver.solve(in, out);

        out.close();
    }

    static class TaskB {
        public void solve(Scanner in, PrintWriter out) {
            if (!in.hasNextInt()) return;

            int n = in.nextInt();
            int m = in.nextInt();

            char[][] grid = new char[n][m];
            for (int i = 0; i < n; i++) {
                String line = in.next();
                for (int j = 0; j < m; j++) {
                    grid[i][j] = line.charAt(j);
                }
            }

            // Check if the grid satisfies the condition for vertical strips
            // This requires n to be divisible by 3
            if (n % 3 == 0 && checkVerticalStrips(grid, n, m)) {
                out.println("YES");
                return;
            }

            // Check if the grid satisfies the condition for horizontal strips
            // This requires m to be divisible by 3
            if (m % 3 == 0 && checkHorizontalStrips(grid, n, m)) {
                out.println("YES");
                return;
            }

            out.println("NO");
        }

        /**
         * Checks if the grid is composed of 3 horizontal strips (rows)
         * where each strip is monochromatic and the strips have distinct colors.
         */
        private boolean checkVerticalStrips(char[][] grid, int rows, int cols) {
            int blockSize = rows / 3;

            // Identify the character for each of the 3 blocks from the first column
            // Block 0 starts at row 0
            // Block 1 starts at row blockSize
            // Block 2 starts at row 2 * blockSize
            char c0 = grid[0][0];
            char c1 = grid[blockSize][0];
            char c2 = grid[2 * blockSize][0];

            // Check if the 3 blocks have distinct characters
            if (c0 == c1 || c0 == c2 || c1 == c2) {
                return false;
            }

            // Verify that every cell in the grid matches the character of its block
            for (int r = 0; r < rows; r++) {
                char expectedChar;
                if (r < blockSize) expectedChar = c0;
                else if (r < 2 * blockSize) expectedChar = c1;
                else expectedChar = c2;

                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] != expectedChar) {
                        return false;
                    }
                }
            }
            return true;
        }

        /**
         * Checks if the grid is composed of 3 vertical strips (columns)
         * where each strip is monochromatic and the strips have distinct colors.
         */
        private boolean checkHorizontalStrips(char[][] grid, int rows, int cols) {
            int blockSize = cols / 3;

            // Identify the character for each of the 3 blocks from the first row
            // Block 0 starts at col 0
            // Block 1 starts at col blockSize
            // Block 2 starts at col 2 * blockSize
            char c0 = grid[0][0];
            char c1 = grid[0][blockSize];
            char c2 = grid[0][2 * blockSize];

            // Check if the 3 blocks have distinct characters
            if (c0 == c1 || c0 == c2 || c1 == c2) {
                return false;
            }

            // Verify that every cell in the grid matches the character of its block
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    char expectedChar;
                    if (c < blockSize) expectedChar = c0;
                    else if (c < 2 * blockSize) expectedChar = c1;
                    else expectedChar = c2;

                    if (grid[r][c] != expectedChar) {
                        return false;
                    }
                }
            }
            return true;
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Refactored version of the original grid checker program.
 * 
 * Key Improvements:
 * 1. Removed unused fields (inf, mod, eps, maxn, g) and classes (Pair, Item, Reader) to eliminate dead code.
 * 2. Replaced the fragile try-catch file fallback with clean try-with-resources for automatic stream management.
 * 3. Fixed inconsistent output streams (original mixed System.out.println and PrintWriter without flushing).
 * 4. Extracted core logic into single-responsibility methods with descriptive names.
 * 5. Eliminated redundant cumulative count checks and variable shadowing (m, k).
 * 6. Added comprehensive JavaDoc and inline comments for better readability and maintainability.
 */
public class Main {

    public static void main(String[] args) {
        new Main().solve();
    }

    private void solve() {
        // Use try-with-resources to guarantee proper closure of I/O streams
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
             PrintWriter out = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)))) {

            String headerLine = br.readLine();
            if (headerLine == null || headerLine.trim().isEmpty()) {
                out.flush();
                return;
            }

            StringTokenizer st = new StringTokenizer(headerLine);
            int n = Integer.parseInt(st.nextToken());
            int m = Integer.parseInt(st.nextToken());

            char[][] grid = new char[n][];
            for (int i = 0; i < n; i++) {
                String row = br.readLine();
                // Skip potential blank lines between inputs
                while (row != null && row.trim().isEmpty()) {
                    row = br.readLine();
                }
                if (row == null) break;
                grid[i] = row.trim().toCharArray();
            }

            boolean horizontalValid = checkHorizontalStripes(grid, n, m);
            boolean verticalValid = checkVerticalStripes(grid, n, m);

            out.println(horizontalValid || verticalValid ? "YES" : "No");
            out.flush();

        } catch (IOException e) {
            // In a production environment, route this to a proper logging framework
            System.err.println("I/O Error: " + e.getMessage());
        }
    }

    /**
     * Checks if the grid can be divided into 3 equal horizontal monochromatic stripes.
     */
    private boolean checkHorizontalStripes(char[][] grid, int n, int m) {
        if (n % 3 != 0) {
            return false;
        }

        int stripHeight = n / 3;
        int cellsPerStrip = m * stripHeight;

        for (int k = 0; k < 3; k++) {
            int countR = 0, countG = 0, countB = 0;
            int startRow = k * stripHeight;

            for (int i = startRow; i < startRow + stripHeight; i++) {
                for (int j = 0; j < m; j++) {
                    char c = grid[i][j];
                    if (c == 'R') countR++;
                    else if (c == 'G') countG++;
                    else if (c == 'B') countB++;
                }
            }

            if (!isMonochromatic(countR, countG, countB, cellsPerStrip)) {
                return false;
            }
        }
        return true;
    }

    /**
     * Checks if the grid can be divided into 3 equal vertical monochromatic stripes.
     */
    private boolean checkVerticalStripes(char[][] grid, int n, int m) {
        if (m % 3 != 0) {
            return false;
        }

        int stripWidth = m / 3;
        int cellsPerStrip = n * stripWidth;

        for (int k = 0; k < 3; k++) {
            int countR = 0, countG = 0, countB = 0;
            int startCol = k * stripWidth;

            for (int i = 0; i < n; i++) {
                for (int j = startCol; j < startCol + stripWidth; j++) {
                    char c = grid[i][j];
                    if (c == 'R') countR++;
                    else if (c == 'G') countG++;
                    else if (c == 'B') countB++;
                }
            }

            if (!isMonochromatic(countR, countG, countB, cellsPerStrip)) {
                return false;
            }
        }
        return true;
    }

    /**
     * Determines if a stripe contains exactly one color type filling all its cells.
     */
    private boolean isMonochromatic(int countR, int countG, int countB, int totalCells) {
        return (countR == totalCells && countG == 0 && countB == 0) ||
               (countG == totalCells && countR == 0 && countB == 0) ||
               (countB == totalCells && countR == 0 && countG == 0);
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.OutputStream;
import java.io.PrintWriter;
import java.util.StringTokenizer;

public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        FastReader in = new FastReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);

        Solver solver = new Solver();
        solver.solve(1, in, out);

        out.close();
    }

    /**
     * Solver class handling the logic for Task B.
     * Refactored from 'TaskB' for better generic naming.
     */
    static class Solver {

        /**
         * Solves the problem for a given test case.
         * 
         * @param testNumber The test case number (unused in this logic).
         * @param in         FastReader for input.
         * @param out        PrintWriter for output.
         */
        public void solve(int testNumber, FastReader in, PrintWriter out) {
            int n = in.nextInt();
            int m = in.nextInt();
            char[][] grid = new char[n][m];

            for (int i = 0; i < n; i++) {
                grid[i] = in.next().toCharArray();
            }

            // Check if the first row is uniform (all characters are the same)
            boolean firstRowUniform = true;
            char firstChar = grid[0][0];
            for (int j = 1; j < m; j++) {
                if (grid[0][j] != firstChar) {
                    firstRowUniform = false;
                    break;
                }
            }

            if (firstRowUniform) {
                // Case 1: First row is uniform.
                // The grid must consist of identical columns.
                // The height (n) must be divisible by 3.
                // The first column must form a valid pattern (blocks of R, G, B).

                if (n % 3 != 0) {
                    out.print("NO");
                    return;
                }

                // Extract the first column to check its pattern
                // Using StringBuilder for O(N) performance instead of string concatenation
                StringBuilder colBuilder = new StringBuilder(n);
                for (int i = 0; i < n; i++) {
                    colBuilder.append(grid[i][0]);
                }
                String firstColumnPattern = colBuilder.toString();

                if (!isValidPattern(firstColumnPattern)) {
                    out.print("NO");
                    return;
                }

                // Verify that all other columns are identical to the first column
                for (int j = 1; j < m; j++) {
                    for (int i = 0; i < n; i++) {
                        if (grid[i][j] != grid[i][0]) {
                            out.print("NO");
                            return;
                        }
                    }
                }
            } else {
                // Case 2: First row is not uniform.
                // The grid must consist of identical rows.
                // The width (m) must be divisible by 3.
                // The first row must form a valid pattern.

                if (m % 3 != 0) {
                    out.print("NO");
                    return;
                }

                // Extract the first row to check its pattern
                StringBuilder rowBuilder = new StringBuilder(m);
                for (int j = 0; j < m; j++) {
                    rowBuilder.append(grid[0][j]);
                }
                String firstRowPattern = rowBuilder.toString();

                if (!isValidPattern(firstRowPattern)) {
                    out.print("NO");
                    return;
                }

                // Verify that all other rows are identical to the first row
                for (int i = 1; i < n; i++) {
                    for (int j = 0; j < m; j++) {
                        if (grid[i][j] != grid[0][j]) {
                            out.print("NO");
                            return;
                        }
                    }
                }
            }
            out.print("YES");
        }

        /**
         * Checks if a string represents a valid pattern consisting of contiguous blocks
         * of 'R', 'G', and 'B', each occupying exactly 1/3 of the string length.
         * 
         * @param s The string to validate.
         * @return true if valid, false otherwise.
         */
        private boolean isValidPattern(String s) {
            int len = s.length();
            int expectedSpan = len / 3;

            // The logic checks if the span between the first and last occurrence 
            // of each character (R, G, B) equals exactly 1/3 of the length.
            // If a character is missing, indexOf/lastIndexOf return -1, 
            // resulting in a span of 1 (-1 - -1 + 1). This passes only if expectedSpan is 1.

            int rSpan = s.lastIndexOf('R') - s.indexOf('R') + 1;
            int gSpan = s.lastIndexOf('G') - s.indexOf('G') + 1;
            int bSpan = s.lastIndexOf('B') - s.indexOf('B') + 1;

            return (rSpan == expectedSpan) && (gSpan == expectedSpan) && (bSpan == expectedSpan);
        }
    }

    /**
     * Fast I/O helper class.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer token;

        public FastReader(InputStream in) {
            reader = new BufferedReader(new InputStreamReader(in), 1 << 20);
        }

        String next() {
            while (token == null || !token.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) {
                        return null;
                    }
                    token = new StringTokenizer(line);
                } catch (IOException e) {
                    // In a maintainable application, we might wrap this in a custom exception
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return token.nextToken();
        }

        int nextInt() {
            String s = next();
            if (s == null) {
                throw new RuntimeException("Unexpected end of input");
            }
            return Integer.parseInt(s);
        }
    }
}

import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

/**
 * Solution for Flag of Berland problem.
 * Checks if a grid of characters forms a valid flag pattern 
 * (either uniform rows or uniform columns with valid color distribution).
 */
public class FlagOfBerland {

    public static void main(String[] args) {
        // Use try-with-resources to ensure Scanner is closed automatically
        try (Scanner scanner = new Scanner(System.in)) {
            if (!scanner.hasNextInt()) {
                return;
            }

            int rows = scanner.nextInt();
            int cols = scanner.nextInt();

            String[] grid = new String[rows];
            for (int i = 0; i < rows; i++) {
                grid[i] = scanner.next();
            }

            // Check if all rows are identical
            boolean rowsUniform = isRowsUniform(grid);

            // Check if all columns are identical
            boolean colsUniform = isColsUniform(grid);

            if (!rowsUniform && !colsUniform) {
                System.out.println("NO");
            } else if (rowsUniform) {
                // If rows are uniform, check the pattern of the first row
                validatePattern(grid[0]);
            } else {
                // If columns are uniform, check the pattern of the first column
                StringBuilder firstColumn = new StringBuilder();
                for (String row : grid) {
                    firstColumn.append(row.charAt(0));
                }
                validatePattern(firstColumn.toString());
            }
        }
    }

    /**
     * Checks if all strings in the array are identical.
     */
    private static boolean isRowsUniform(String[] grid) {
        if (grid.length == 0) {
            return true;
        }
        String firstRow = grid[0];
        for (int i = 1; i < grid.length; i++) {
            if (!grid[i].equals(firstRow)) {
                return false;
            }
        }
        return true;
    }

    /**
     * Checks if all columns in the grid are identical.
     * A column is identical if grid[r][c] == grid[r+1][c] for all r.
     */
    private static boolean isColsUniform(String[] grid) {
        if (grid.length == 0 || grid[0].length() == 0) {
            return true;
        }
        int cols = grid[0].length();
        for (int c = 0; c < cols; c++) {
            char firstChar = grid[0].charAt(c);
            for (int r = 1; r < grid.length; r++) {
                if (grid[r].charAt(c) != firstChar) {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Validates if the pattern string contains equal counts of R, G, B
     * and that indices for each color are contiguous.
     */
    private static void validatePattern(String pattern) {
        List<Integer> redIndices = new ArrayList<>();
        List<Integer> greenIndices = new ArrayList<>();
        List<Integer> blueIndices = new ArrayList<>();

        for (int i = 0; i < pattern.length(); i++) {
            char c = pattern.charAt(i);
            if (c == 'R') {
                redIndices.add(i);
            } else if (c == 'G') {
                greenIndices.add(i);
            } else if (c == 'B') {
                blueIndices.add(i);
            }
        }

        // Check if counts are equal
        if (redIndices.size() != greenIndices.size() || 
            greenIndices.size() != blueIndices.size()) {
            System.out.println("NO");
            return;
        }

        // Check if indices are contiguous (no gaps) for each color
        if (!isContiguous(redIndices) || 
            !isContiguous(greenIndices) || 
            !isContiguous(blueIndices)) {
            System.out.println("NO");
        } else {
            System.out.println("YES");
        }
    }

    /**
     * Checks if a list of integer indices represents a contiguous sequence.
     */
    private static boolean isContiguous(List<Integer> indices) {
        for (int i = 1; i < indices.size(); i++) {
            if (indices.get(i) - indices.get(i - 1) != 1) {
                return false;
            }
        }
        return true;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.OutputStream;
import java.io.PrintWriter;
import java.util.StringTokenizer;

/**
 * Refactored solution for FlagOfBerland.
 * 
 * Improvements made:
 * 1. Separation of Concerns: Logic for checking grid patterns is separated from I/O operations.
 * 2. Naming Conventions: Variable names are descriptive (e.g., 'rows', 'cols', 'stripeHeight' instead of 'n', 'm', 'limit').
 * 3. Constants: Magic number '3' is replaced with a named constant 'NUM_STRIPES'.
 * 4. Readability: The nested loop logic for checking stripes is replaced with clearer range-based logic.
 * 5. Resource Management: Used try-with-resources and implemented AutoCloseable for clean resource handling.
 * 6. Robustness: Added basic null/empty checks and improved exception handling.
 */
public class FlagOfBerland implements AutoCloseable {

    private static final int NUM_STRIPES = 3;

    private final BufferedReader reader;
    private final PrintWriter writer;
    private StringTokenizer tokenizer;

    /**
     * Constructor initializing I/O streams.
     */
    public FlagOfBerland(InputStream inputStream, OutputStream outputStream) {
        this.reader = new BufferedReader(new InputStreamReader(inputStream));
        this.writer = new PrintWriter(outputStream);
    }

    /**
     * Main entry point for the logic.
     */
    public void solve() {
        try {
            int rows = nextInt();
            int cols = nextInt();
            char[][] grid = new char[rows][cols];

            for (int i = 0; i < rows; i++) {
                String line = next();
                if (line != null) {
                    grid[i] = line.toCharArray();
                }
            }

            boolean isFlag = checkHorizontal(grid) || checkVertical(grid);
            writer.println(isFlag ? "YES" : "NO");
        } catch (IOException e) {
            throw new RuntimeException("Error reading input", e);
        }
    }

    /**
     * Checks if the grid represents a flag with horizontal stripes.
     * The grid must be divisible by NUM_STRIPES rows.
     */
    private boolean checkHorizontal(char[][] grid) {
        int rows = grid.length;
        if (rows == 0 || rows % NUM_STRIPES != 0) {
            return false;
        }

        int stripeHeight = rows / NUM_STRIPES;

        // Identify the colors of the three stripes based on the first column
        char colorTop = grid[0][0];
        char colorMiddle = grid[stripeHeight][0];
        char colorBottom = grid[2 * stripeHeight][0];

        // Colors must be distinct
        if (colorTop == colorMiddle || colorMiddle == colorBottom || colorTop == colorBottom) {
            return false;
        }

        // Validate that every cell matches the color of its stripe
        for (int r = 0; r < rows; r++) {
            char expectedColor;
            if (r < stripeHeight) {
                expectedColor = colorTop;
            } else if (r < 2 * stripeHeight) {
                expectedColor = colorMiddle;
            } else {
                expectedColor = colorBottom;
            }

            for (int c = 0; c < grid[r].length; c++) {
                if (grid[r][c] != expectedColor) {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Checks if the grid represents a flag with vertical stripes.
     * The grid must be divisible by NUM_STRIPES columns.
     */
    private boolean checkVertical(char[][] grid) {
        if (grid.length == 0 || grid[0].length == 0) {
            return false;
        }

        int cols = grid[0].length;
        if (cols % NUM_STRIPES != 0) {
            return false;
        }

        int stripeWidth = cols / NUM_STRIPES;

        // Identify the colors of the three stripes based on the first row
        char colorLeft = grid[0][0];
        char colorMiddle = grid[0][stripeWidth];
        char colorRight = grid[0][2 * stripeWidth];

        // Colors must be distinct
        if (colorLeft == colorMiddle || colorMiddle == colorRight || colorLeft == colorRight) {
            return false;
        }

        // Validate that every cell matches the color of its stripe
        for (int r = 0; r < grid.length; r++) {
            for (int c = 0; c < cols; c++) {
                char expectedColor;
                if (c < stripeWidth) {
                    expectedColor = colorLeft;
                } else if (c < 2 * stripeWidth) {
                    expectedColor = colorMiddle;
                } else {
                    expectedColor = colorRight;
                }

                if (grid[r][c] != expectedColor) {
                    return false;
                }
            }
        }
        return true;
    }

    // --- Fast I/O Helpers ---

    private String next() throws IOException {
        while (tokenizer == null || !tokenizer.hasMoreTokens()) {
            String line = reader.readLine();
            if (line == null) {
                return null;
            }
            tokenizer = new StringTokenizer(line);
        }
        return tokenizer.nextToken();
    }

    private int nextInt() {
        try {
            String s = next();
            if (s == null) {
                throw new RuntimeException("Unexpected end of input");
            }
            return Integer.parseInt(s);
        } catch (IOException e) {
            throw new RuntimeException("Error reading integer", e);
        }
    }

    @Override
    public void close() throws IOException {
        reader.close();
        writer.flush();
        writer.close();
    }

    public static void main(String[] args) {
        // Using try-with-resources for automatic resource management
        try (FlagOfBerland solver = new FlagOfBerland(System.in, System.out)) {
            solver.solve();
        } catch (IOException e) {
            System.err.println("An I/O error occurred: " + e.getMessage());
        }
    }
}

