        InputReader in = new InputReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        // testNumber is unused in the original implementation; removed from signature for cleanliness.
        TaskB.solve(in, out);

        out.flush();
        out.close();
    }

    /**
     * Contains the core logic for solving the problem.
     * Refactored to be stateless (no instance fields) for better testability and thread safety.
     */
    static class TaskB {
        /**
         * Solves a single test case.
         * Validates that 'R', 'G', and 'B' characters each form a solid rectangle of identical dimensions.
         */
        public static void solve(InputReader in, PrintWriter out) {
            int n = in.nextInt();
            int m = in.nextInt();
            char[][] grid = new char[n][m];

            for (int i = 0; i < n; i++) {
                grid[i] = in.next().toCharArray();
            }

            int[] redBox = calculateBoundingBox(grid, n, m, 'R');
            int[] greenBox = calculateBoundingBox(grid, n, m, 'G');
            int[] blueBox = calculateBoundingBox(grid, n, m, 'B');

            boolean isValid = areIdenticalSolidRectangles(redBox, greenBox, blueBox);
            out.println(isValid ? "YES" : "NO");
        }

        /**
         * Computes the bounding box dimensions for a specific character in the grid.
         * Returns {-1, -1} if the character is absent or does not form a solid rectangle.
         *
         * @param grid The input character grid
         * @param n    Number of rows
         * @param m    Number of columns
         * @param targetChar The character to search for
         * @return int array [height, width], or {-1, -1} if invalid
         */
        private static int[] calculateBoundingBox(char[][] grid, int n, int m, char targetChar) {
            int count = 0;
            int minRow = n, maxRow = -1;
            int minCol = m, maxCol = -1;

            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    if (grid[i][j] == targetChar) {
                        count++;
                        if (i < minRow) minRow = i;
                        if (i > maxRow) maxRow = i;
                        if (j < minCol) minCol = j;
                        if (j > maxCol) maxCol = j;
                    }
                }
            }

            // If the character doesn't appear in the grid, it cannot form a valid rectangle
            if (count == 0) {
                return new int[]{-1, -1};
            }

            int height = maxRow - minRow + 1;
            int width = maxCol - minCol + 1;

            // If the bounding box area doesn't match the character count,
            // it indicates gaps within the bounding box (not a solid rectangle)
            if (height * width != count) {
                return new int[]{-1, -1};
            }

            return new int[]{height, width};
        }

        /**
         * Verifies that three bounding boxes are identical and valid.
         */
        private static boolean areIdenticalSolidRectangles(int[] box1, int[] box2, int[] box3) {
            if (box1[0] == -1 || box2[0] == -1 || box3[0] == -1) {
                return false;
            }
            return box1[0] == box2[0] && box2[0] == box3[0] &&
                   box1[1] == box2[1] && box2[1] == box3[1];
        }
    }

    /**
     * Fast input reader for competitive programming environments.
     * Encapsulates BufferedReader and StringTokenizer for efficient token parsing.
     */
    static class InputReader {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

public class Main {
    // Extracted constants to avoid magic strings/numbers
    private static final String ANSWER_YES = "YES";
    private static final String ANSWER_NO = "NO";
    private static final int BAND_COUNT = 3;

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner(System.in);
        // try-with-resources ensures PrintWriter is properly closed
        try (PrintWriter writer = new PrintWriter(System.out)) {
            solve(scanner, writer);
        }
    }

    private static void solve(FastScanner scanner, PrintWriter writer) {
        int n = scanner.nextInt();
        scanner.next(); // Consumes the second input token (often unused or represents string dimensions)

        char[][] grid = new char[n][];
        for (int i = 0; i < n; i++) {
            grid[i] = scanner.next().toCharArray();
        }

        // Check if either rows or columns form valid uniform bands
        if (isValidUniformBands(grid, true) || isValidUniformBands(grid, false)) {
            writer.println(ANSWER_YES);
        } else {
            writer.println(ANSWER_NO);
        }
    }

    /**
     * Validates if the grid is composed of 3 uniform bands (horizontal or vertical).
     * Each band must consist of a single repeated character, and the 3 characters must be distinct.
     *
     * @param grid      The 2D character grid
     * @param checkRows If true, checks horizontal bands; otherwise, checks vertical bands
     * @return true if the condition is met, false otherwise
     */
    private static boolean isValidUniformBands(char[][] grid, boolean checkRows) {
        int length = checkRows ? grid.length : grid[0].length;
        int width = checkRows ? grid[0].length : grid.length;

        if (length % BAND_COUNT != 0) {
            return false;
        }

        int bandSize = length / BAND_COUNT;
        char[] bandCharacters = new char[BAND_COUNT];

        // Extract the representative character for each band
        for (int i = 0; i < BAND_COUNT; i++) {
            int bandStartIndex = i * bandSize;
            bandCharacters[i] = checkRows ? grid[bandStartIndex][0] : grid[0][bandStartIndex];
        }

        // Ensure all band characters are distinct
        for (int i = 0; i < BAND_COUNT; i++) {
            for (int j = i + 1; j < BAND_COUNT; j++) {
                if (bandCharacters[i] == bandCharacters[j]) {
                    return false;
                }
            }
        }

        // Verify every cell matches its corresponding band's character
        for (int r = 0; r < grid.length; r++) {
            for (int c = 0; c < grid[r].length; c++) {
                int bandIndex = checkRows ? (r / bandSize) : (c / bandSize);
                if (grid[r][c] != bandCharacters[bandIndex]) {
                    return false;
                }
            }
        }

        return true;
    }

    /**
     * Fast I/O utility class optimized for competitive programming environments.
     */
    static class FastScanner {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastScanner(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) {
                        return null;
                    }
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            String token = next();
            if (token == null) {
                throw new RuntimeException("Unexpected end of input");
            }
            return Integer.parseInt(token);
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.HashSet;
import java.util.Set;

public class ColorGridChecker {
    private static final int REQUIRED_PARTS = 3;
    private static final char COLOR_R = 'R';
    private static final char COLOR_G = 'G';
    private static final char COLOR_B = 'B';

    public static void main(String[] args) throws IOException {
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(System.in))) {
            String line = reader.readLine();
            if (line == null || line.trim().isEmpty()) {
                System.out.println("NO");
                return;
            }

            String[] parts = line.trim().split("\\s+");
            if (parts.length < 2) {
                System.out.println("NO");
                return;
            }

            int rows = Integer.parseInt(parts[0]);
            int cols = Integer.parseInt(parts[1]);

            // Total cells must be divisible by 3
            if ((rows * cols) % REQUIRED_PARTS != 0) {
                System.out.println("NO");
                return;
            }

            char[][] grid = new char[rows][];
            for (int i = 0; i < rows; i++) {
                String rowLine = reader.readLine();
                if (rowLine == null) {
                    System.out.println("NO");
                    return;
                }
                grid[i] = rowLine.toCharArray();
            }

            // Determine split orientation based on the first row's uniformity
            boolean splitAlongHeight = isFirstRowUniform(grid, cols);

            if (splitAlongHeight) {
                if (rows % REQUIRED_PARTS != 0) {
                    System.out.println("NO");
                } else {
                    System.out.println(checkGridSplit(grid, rows, cols, true) ? "YES" : "NO");
                }
            } else {
                if (cols % REQUIRED_PARTS != 0) {
                    System.out.println("NO");
                } else {
                    System.out.println(checkGridSplit(grid, rows, cols, false) ? "YES" : "NO");
                }
            }
        }
    }

    /**
     * Checks if the first row of the grid contains identical characters.
     */
    private static boolean isFirstRowUniform(char[][] grid, int cols) {
        if (grid.length == 0 || grid[0].length == 0) {
            return false;
        }
        char firstChar = grid[0][0];
        for (int j = 1; j < cols; j++) {
            if (grid[0][j] != firstChar) {
                return false;
            }
        }
        return true;
    }

    /**
     * Validates if the grid can be split into three uniform parts containing R, G, and B.
     */
    private static boolean checkGridSplit(char[][] grid, int rows, int cols, boolean splitAlongHeight) {
        int partSize = splitAlongHeight ? rows / REQUIRED_PARTS : cols / REQUIRED_PARTS;
        Set<Character> foundColors = new HashSet<>();

        for (int i = 0; i < REQUIRED_PARTS; i++) {
            int start = i * partSize;
            int end = start + partSize;
            char color = getUniformColor(grid, rows, cols, splitAlongHeight, start, end);
            if (color == '-') {
                return false;
            }
            foundColors.add(color);
        }

        return foundColors.contains(COLOR_R) && foundColors.contains(COLOR_G) && foundColors.contains(COLOR_B);
    }

    /**
     * Checks if a specific sub-region of the grid is uniform.
     * Returns the character if uniform, otherwise returns '-'.
     */
    private static char getUniformColor(char[][] grid, int rows, int cols, boolean splitAlongHeight, int start, int end) {
        char testColor = splitAlongHeight ? grid[start][0] : grid[0][start];

        if (splitAlongHeight) {
            // Check each column in the row range (horizontal bands)
            for (int r = start; r < end; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] != testColor) {
                        return '-';
                    }
                }
            }
        } else {
            // Check each row in the column range (vertical bands)
            for (int c = start; c < end; c++) {
                for (int r = 0; r < rows; r++) {
                    if (grid[r][c] != testColor) {
                        return '-';
                    }
                }
            }
        }
        return testColor;
    }
}

import java.io.*;
import java.util.*;

public class SPOJANDCC {
    private static final int PART_COUNT = 3;
    private final PrintWriter out = new PrintWriter(System.out);
    private final FastReader in = new FastReader();

    public void run() {
        solve();
        out.flush();
    }

    public void solve() {
        int rows = in.nextInt();
        int cols = in.nextInt();
        String[] grid = new String[rows];
        for (int i = 0; i < rows; i++) {
            grid[i] = in.next();
        }

        if (checkRows(rows, cols, grid)) {
            out.println("YES");
        } else if (checkColumns(rows, cols, grid)) {
            out.println("YES");
        } else {
            out.println("NO");
        }
    }

    /**
     * Checks if the grid can be divided into three equal horizontal strips,
     * each containing an equal number of 'R', 'G', and 'B' characters.
     */
    private boolean checkRows(int rows, int cols, String[] grid) {
        if (rows % PART_COUNT != 0) return false;

        int expectedCount = (rows * cols) / PART_COUNT;
        int partHeight = rows / PART_COUNT;

        for (int part = 0; part < PART_COUNT; part++) {
            int rCount = 0, gCount = 0, bCount = 0;
            int startRow = part * partHeight;

            for (int r = startRow; r < startRow + partHeight; r++) {
                String rowStr = grid[r];
                for (int c = 0; c < cols; c++) {
                    char ch = rowStr.charAt(c);
                    if (ch == 'R') rCount++;
                    else if (ch == 'G') gCount++;
                    else if (ch == 'B') bCount++;
                }
            }

            if (rCount != expectedCount || gCount != expectedCount || bCount != expectedCount) {
                return false;
            }
        }
        return true;
    }

    /**
     * Checks if the grid can be divided into three equal vertical strips,
     * each containing an equal number of 'R', 'G', and 'B' characters.
     */
    private boolean checkColumns(int rows, int cols, String[] grid) {
        if (cols % PART_COUNT != 0) return false;

        int expectedCount = (rows * cols) / PART_COUNT;
        int partWidth = cols / PART_COUNT;

        for (int part = 0; part < PART_COUNT; part++) {
            int rCount = 0, gCount = 0, bCount = 0;
            int startCol = part * partWidth;

            for (int c = startCol; c < startCol + partWidth; c++) {
                for (int r = 0; r < rows; r++) {
                    char ch = grid[r].charAt(c);
                    if (ch == 'R') rCount++;
                    else if (ch == 'G') gCount++;
                    else if (ch == 'B') bCount++;
                }
            }

            if (rCount != expectedCount || gCount != expectedCount || bCount != expectedCount) {
                return false;
            }
        }
        return true;
    }

    /**
     * Optimized Fast I/O reader for competitive programming contexts.
     */
    private static class FastReader {
        private final InputStream is = System.in;
        private final byte[] buffer = new byte[1024];
        private int bufferLength = 0;
        private int bufferPointer = 0;

        private int readByte() {
            if (bufferLength == -1) throw new InputMismatchException();
            if (bufferPointer >= bufferLength) {
                bufferPointer = 0;
                try {
                    bufferLength = is.read(buffer);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (bufferLength <= 0) return -1;
            }
            return buffer[bufferPointer++];
        }

        private boolean isSpaceChar(int c) {
            return !(c >= 33 && c <= 126);
        }

        private int skip() {
            int c;
            while ((c = readByte()) != -1 && isSpaceChar(c)) ;
            return c;
        }

        public String next() {
            int c = skip();
            StringBuilder sb = new StringBuilder();
            while (!isSpaceChar(c)) {
                sb.appendCodePoint(c);
                c = readByte();
            }
            return sb.toString();
        }

        public int nextInt() {
            int c = skip();
            int num = 0;
            boolean minus = false;
            if (c == '-') {
                minus = true;
                c = readByte();
            }
            while (c >= '0' && c <= '9') {
                num = num * 10 + (c - '0');
                c = readByte();
            }
            return minus ? -num : num;
        }
    }

    public static void main(String[] args) {
        new SPOJANDCC().run();
    }
}

import java.util.Scanner;
import java.io.PrintWriter;

/**
 * Determines if a character grid can be divided into three equal horizontal or vertical strips,
 * where each strip consists of a single uniform character, and all three strips have distinct characters.
 */
public class Main {

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            if (!sc.hasNextInt()) {
                return;
            }

            int n = sc.nextInt();
            int m = sc.nextInt();

            char[][] grid = new char[n][m];
            for (int i = 0; i < n; i++) {
                grid[i] = sc.next().toCharArray();
            }

            boolean isHorizontalValid = checkStrips(grid, n, m, true);
            boolean isVerticalValid = checkStrips(grid, n, m, false);

            if (isHorizontalValid || isVerticalValid) {
                out.println("YES");
            } else {
                out.println("NO");
            }
        } finally {
            out.flush();
            out.close();
            sc.close();
        }
    }

    /**
     * Checks if the grid can be divided into three equal strips along the specified axis.
     *
     * @param grid       The 2D character array representing the grid.
     * @param rows       Number of rows in the grid.
     * @param cols       Number of columns in the grid.
     * @param horizontal true to check horizontal strips, false for vertical strips.
     * @return true if the grid satisfies the strip conditions, false otherwise.
     */
    private static boolean checkStrips(char[][] grid, int rows, int cols, boolean horizontal) {
        int dimension = horizontal ? rows : cols;

        // Each strip must have an equal number of rows/columns
        if (dimension % 3 != 0) {
            return false;
        }

        int partSize = dimension / 3;
        char c1, c2, c3;

        // Identify the representative character for each of the three strips
        if (horizontal) {
            c1 = grid[0][0];
            c2 = grid[partSize][0];
            c3 = grid[2 * partSize][0];
        } else {
            c1 = grid[0][0];
            c2 = grid[0][partSize];
            c3 = grid[0][2 * partSize];
        }

        // All three strips must have distinct characters
        if (c1 == c2 || c1 == c3 || c2 == c3) {
            return false;
        }

        // Verify that every cell in each strip matches its corresponding character
        for (int i = 0; i < 3; i++) {
            char target = (i == 0) ? c1 : (i == 1 ? c2 : c3);
            int startIdx = i * partSize;

            for (int k = startIdx; k < startIdx + partSize; k++) {
                for (int j = 0; j < cols; j++) {
                    char currentChar = horizontal ? grid[k][j] : grid[j][k];
                    if (currentChar != target) {
                        return false;
                    }
                }
            }
        }

        return true;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.HashSet;
import java.util.Set;
import java.util.StringTokenizer;

public class FlagOfBerland {

    public static void main(String[] args) throws IOException {
        // Initialize BufferedReader locally to avoid static state issues
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));

        // Read dimensions r (rows) and c (columns)
        String line = br.readLine();
        if (line == null) return;

        StringTokenizer st = new StringTokenizer(line);
        int r = Integer.parseInt(st.nextToken());
        int c = Integer.parseInt(st.nextToken());

        // Read the grid rows
        String[] grid = new String[r];
        for (int i = 0; i < r; i++) {
            grid[i] = br.readLine();
        }

        // Determine if the grid is a valid flag
        boolean isValid = isFlag(grid, r, c);

        System.out.println(isValid ? "YES" : "NO");
    }

    /**
     * Checks if the grid represents a valid flag.
     * A valid flag is composed of either 3 horizontal stripes or 3 vertical stripes.
     * Each stripe must be a solid block of a single color (R, G, or B).
     * The set of colors used in the stripes must be exactly {R, G, B}.
     */
    private static boolean isFlag(String[] grid, int r, int c) {
        return checkHorizontal(grid, r, c) || checkVertical(grid, r, c);
    }

    /**
     * Checks if the grid can be divided into 3 valid horizontal stripes.
     */
    private static boolean checkHorizontal(String[] grid, int r, int c) {
        // Horizontal stripes require the number of rows to be divisible by 3
        if (r % 3 != 0) {
            return false;
        }

        int step = r / 3;
        Set<Character> colors = new HashSet<>();

        // Iterate through the 3 horizontal blocks
        for (int i = 0; i < 3; i++) {
            int startRow = i * step;
            char color = getStripeColorHorizontal(grid, startRow, step, c);

            // If a stripe is invalid (not uniform), the configuration fails
            if (color == 0) {
                return false;
            }
            colors.add(color);
        }

        // The flag must contain Red, Green, and Blue stripes
        return colors.contains('R') && colors.contains('G') && colors.contains('B');
    }

    /**
     * Checks if the grid can be divided into 3 valid vertical stripes.
     */
    private static boolean checkVertical(String[] grid, int r, int c) {
        // Vertical stripes require the number of columns to be divisible by 3
        if (c % 3 != 0) {
            return false;
        }

        int step = c / 3;
        Set<Character> colors = new HashSet<>();

        // Iterate through the 3 vertical blocks
        for (int i = 0; i < 3; i++) {
            int startCol = i * step;
            char color = getStripeColorVertical(grid, startCol, step, r);

            // If a stripe is invalid, the configuration fails
            if (color == 0) {
                return false;
            }
            colors.add(color);
        }

        // The flag must contain Red, Green, and Blue stripes
        return colors.contains('R') && colors.contains('G') && colors.contains('B');
    }

    /**
     * Checks if a horizontal stripe starting at startRow with given height is uniform.
     * Returns the color character if valid, or 0 if invalid.
     */
    private static char getStripeColorHorizontal(String[] grid, int startRow, int height, int width) {
        String firstRow = grid[startRow];

        // Safety check for string length
        if (firstRow.length() < width) {
            return 0;
        }

        char color = firstRow.charAt(0);

        // 1. Check if the first row is uniform (all characters are the same)
        for (int j = 1; j < width; j++) {
            if (firstRow.charAt(j) != color) {
                return 0;
            }
        }

        // 2. Check if all other rows in the stripe match the first row
        for (int i = 1; i < height; i++) {
            if (!grid[startRow + i].equals(firstRow)) {
                return 0;
            }
        }

        return color;
    }

    /**
     * Checks if a vertical stripe starting at startCol with given width is uniform.
     * Returns the color character if valid, or 0 if invalid.
     */
    private static char getStripeColorVertical(String[] grid, int startCol, int width, int height) {
        // 1. Check if the first column of the stripe is uniform
        // We assume grid[0] has enough length based on input validity
        char color = grid[0].charAt(startCol);
        for (int i = 1; i < height; i++) {
            if (grid[i].charAt(startCol) != color) {
                return 0;
            }
        }

        // 2. Check if all columns in the stripe match the first column.
        // Since the first column is uniform 'color', we verify that every cell 
        // in the stripe block is equal to 'color'.
        for (int offset = 1; offset < width; offset++) {
            for (int i = 0; i < height; i++) {
                // Check bounds to prevent IndexOutOfBoundsException
                if (startCol + offset >= grid[i].length()) {
                    return 0; 
                }
                if (grid[i].charAt(startCol + offset) != color) {
                    return 0;
                }
            }
        }

        return color;
    }
}

import java.util.Scanner;
import java.io.PrintWriter;

public class GridChecker {
    private static final int NUM_STrips = 3;

    public static void main(String[] args) {
        // try-with-resources ensures proper closure of I/O streams
        try (Scanner sc = new Scanner(System.in);
             PrintWriter out = new PrintWriter(System.out)) {

            if (!sc.hasNextInt()) return;
            int n = sc.nextInt();
            int m = sc.nextInt();

            // Use char[][] for better performance and semantic correctness
            char[][] grid = new char[n][m];
            for (int i = 0; i < n; i++) {
                String row = sc.next();
                grid[i] = row.toCharArray();
            }

            boolean nDivisible = n % NUM_STrips == 0;
            boolean mDivisible = m % NUM_STrips == 0;

            // If neither dimension is divisible by 3, the condition can never be met
            if (!nDivisible && !mDivisible) {
                out.println("NO");
            } else {
                // Evaluate conditions only when the dimension allows it
                boolean horizontalValid = nDivisible && checkStrips(grid, n, m, true);
                boolean verticalValid = mDivisible && checkStrips(grid, n, m, false);

                out.println((horizontalValid || verticalValid) ? "YES" : "NO");
            }
        }
    }

    /**
     * Checks if the grid can be divided into NUM_STrips equal strips
     * where each strip is uniformly filled with a single character,
     * and all strips contain distinct characters.
     *
     * @param horizontal true to check horizontal strips, false for vertical
     */
    private static boolean checkStrips(char[][] grid, int n, int m, boolean horizontal) {
        int stripSize = horizontal ? n / NUM_STrips : m / NUM_STrips;
        char[] stripColors = new char[NUM_STrips];

        for (int s = 0; s < NUM_STrips; s++) {
            int start = s * stripSize;
            int end = start + stripSize;

            // Determine the reference character for the current strip
            char color = horizontal ? grid[start][0] : grid[0][start];

            // Verify that every cell in the strip matches the reference character
            for (int i = start; i < end; i++) {
                for (int j = 0; j < (horizontal ? m : n); j++) {
                    if (horizontal ? grid[i][j] != color : grid[j][i] != color) {
                        return false;
                    }
                }
            }
            stripColors[s] = color;
        }

        // Ensure all three strips have different characters
        return stripColors[0] != stripColors[1] &&
               stripColors[1] != stripColors[2] &&
               stripColors[0] != stripColors[2];
    }
}

