/**
 * Handles the core logic for determining if a grid satisfies the three-band condition
 * either in its original orientation or transposed.
 */
class Solver {
    public void solve(InputReader in, PrintWriter out) {
        int n = in.nextInt();
        int m = in.nextInt();
        char[][] matrix = new char[n][m];
        for (int i = 0; i < n; i++) {
            matrix[i] = in.next().toCharArray();
        }

        boolean originalValid = isThreeUniformBands(matrix, n, m);
        boolean transposedValid = isThreeUniformBands(transpose(matrix, n, m), m, n);

        out.println(originalValid || transposedValid ? "YES" : "NO");
    }

    /**
     * Checks if the grid consists of three horizontal bands of uniform characters,
     * where each band has a distinct character.
     */
    private boolean isThreeUniformBands(char[][] grid, int rows, int cols) {
        if (rows % 3 != 0) {
            return false;
        }

        int bandHeight = rows / 3;
        char band1Char = grid[0][0];
        char band2Char = grid[bandHeight][0];
        char band3Char = grid[2 * bandHeight][0];

        // All three bands must have distinct characters
        if (band1Char == band2Char || band1Char == band3Char || band2Char == band3Char) {
            return false;
        }

        // Verify each band consists of a single repeated character
        for (int i = 0; i < bandHeight; i++) {
            if (!isUniformRow(grid[i], band1Char, cols)) {
                return false;
            }
        }
        for (int i = bandHeight; i < 2 * bandHeight; i++) {
            if (!isUniformRow(grid[i], band2Char, cols)) {
                return false;
            }
        }
        for (int i = 2 * bandHeight; i < rows; i++) {
            if (!isUniformRow(grid[i], band3Char, cols)) {
                return false;
            }
        }

        return true;
    }

    /**
     * Checks if a row contains only the expected character.
     */
    private boolean isUniformRow(char[] row, char expected, int length) {
        for (int j = 0; j < length; j++) {
            if (row[j] != expected) {
                return false;
            }
        }
        return true;
    }

    /**
     * Transposes a 2D character matrix.
     */
    private char[][] transpose(char[][] matrix, int rows, int cols) {
        char[][] transposed = new char[cols][rows];
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                transposed[j][i] = matrix[i][j];
            }
        }
        return transposed;
    }
}

/**
 * Fast input reader optimized for competitive programming and large I/O operations.
 */
class InputReader {
    private final BufferedReader reader;
    private StringTokenizer tokenizer;

    public InputReader(InputStream stream) {
        this.reader = new BufferedReader(new InputStreamReader(stream), 32768);
        this.tokenizer = null;
    }

    public String next() {
        while (tokenizer == null || !tokenizer.hasMoreTokens()) {
            try {
                String line = reader.readLine();
                if (line == null) {
                    return null;
                }
                tokenizer = new StringTokenizer(line);
            } catch (IOException e) {
                throw new RuntimeException("Error reading input", e);
            }
        }
        return tokenizer.nextToken();
    }

    public int nextInt() {
        return Integer.parseInt(next());
    }

    public long nextLong() {
        return Long.parseLong(next());
    }

    public int[] nextIntArray(int count) {
        int[] arr = new int[count];
        for (int i = 0; i < count; i++) {
            arr[i] = nextInt();
        }
        return arr;
    }

    public long[] nextLongArray(int count) {
        long[] arr = new long[count];
        for (int i = 0; i < count; i++) {
            arr[i] = nextLong();
        }
        return arr;
    }
}

import java.util.Scanner;

public class Main {
    private static final char COLOR_RED = 'R';
    private static final char COLOR_GREEN = 'G';
    private static final char COLOR_BLUE = 'B';

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        if (!scanner.hasNextInt()) return;

        int rows = scanner.nextInt();
        int cols = scanner.nextInt();

        char[][] grid = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            grid[i] = scanner.next().toCharArray();
        }

        boolean isHorizontalValid = hasUniformHorizontalBands(grid, rows, cols);
        boolean isVerticalValid = hasUniformVerticalBands(grid, rows, cols);

        System.out.println((isHorizontalValid || isVerticalValid) ? "YES" : "NO");
    }

    /**
     * Maps color characters to indices 0, 1, 2 for array tracking.
     */
    private static int getColorIndex(char c) {
        if (c == COLOR_RED) return 0;
        if (c == COLOR_GREEN) return 1;
        return 2; // Implicitly 'B' based on problem constraints
    }

    private static boolean hasUniformHorizontalBands(char[][] grid, int rows, int cols) {
        return validateBands(grid, rows, cols, true);
    }

    private static boolean hasUniformVerticalBands(char[][] grid, int rows, int cols) {
        return validateBands(grid, rows, cols, false);
    }

    /**
     * Validates that the grid is partitioned into exactly 3 contiguous bands of equal length,
     * where each band consists of a single uniform color.
     *
     * @param checkRows If true, checks horizontal bands (rows). If false, checks vertical bands (columns).
     */
    private static boolean validateBands(char[][] grid, int numBands, int bandWidth, boolean checkRows) {
        int[] segmentCounts = new int[3];
        int[] bandLengths = new int[3];
        char currentColor = 0;
        int currentBandLength = 0;
        boolean isFirstBand = true;

        for (int i = 0; i < numBands; i++) {
            char firstCell = checkRows ? grid[i][0] : grid[0][i];

            if (isFirstBand) {
                currentColor = firstCell;
                isFirstBand = false;
            } else if (firstCell != currentColor) {
                // Transition to a new color band
                segmentCounts[getColorIndex(currentColor)]++;
                bandLengths[getColorIndex(currentColor)] += currentBandLength;
                currentColor = firstCell;
                currentBandLength = 0;
            }

            currentBandLength++;

            // Verify uniformity within the current band
            for (int j = 1; j < bandWidth; j++) {
                char cell = checkRows ? grid[i][j] : grid[j][i];
                if (cell != currentColor) {
                    return false;
                }
            }
        }

        // Process the final band after the loop completes
        segmentCounts[getColorIndex(currentColor)]++;
        bandLengths[getColorIndex(currentColor)] += currentBandLength;

        // Each color must form exactly one contiguous segment
        for (int k = 0; k < 3; k++) {
            if (segmentCounts[k] != 1) {
                return false;
            }
        }

        // All three bands must have equal length
        return bandLengths[0] == bandLengths[1] && bandLengths[1] == bandLengths[2];
    }
}

import java.util.Scanner;

public class B837 {
    private static final int PARTS = 3;

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        if (!scanner.hasNextInt()) {
            return;
        }

        int rows = scanner.nextInt();
        int cols = scanner.nextInt();
        scanner.nextLine(); // Consume the newline after the dimensions

        String[] grid = new String[rows];
        for (int i = 0; i < rows; i++) {
            grid[i] = scanner.nextLine();
        }

        boolean isValid = checkGrid(grid, rows, cols);
        System.out.println(isValid ? "YES" : "NO");
    }

    /**
     * Validates the grid by checking for valid horizontal or vertical stripe patterns.
     */
    private static boolean checkGrid(String[] grid, int rows, int cols) {
        if (rows <= 0 || cols <= 0) {
            return false;
        }

        int validPatterns = 0;

        if (rows % PARTS == 0) {
            if (checkHorizontalStripes(grid, rows, cols)) {
                validPatterns++;
            }
        }

        if (cols % PARTS == 0) {
            if (checkVerticalStripes(grid, rows, cols)) {
                validPatterns++;
            }
        }

        // Original logic: if (x > 0) YES else NO
        return validPatterns > 0;
    }

    /**
     * Checks if the grid can be divided into horizontal bands where each band
     * is uniformly filled with a single character, and all bands have distinct characters.
     */
    private static boolean checkHorizontalStripes(String[] grid, int rows, int cols) {
        int partHeight = rows / PARTS;
        char[] topChars = new char[PARTS];
        topChars[0] = grid[0].charAt(0);
        topChars[1] = grid[partHeight].charAt(0);
        topChars[2] = grid[2 * partHeight].charAt(0);

        if (!areDistinct(topChars)) {
            return false;
        }

        for (int i = 0; i < PARTS; i++) {
            int rowStart = i * partHeight;
            int rowEnd = (i + 1) * partHeight - 1;
            if (!isUniformSection(grid, rowStart, rowEnd, 0, cols - 1, topChars[i])) {
                return false;
            }
        }
        return true;
    }

    /**
     * Checks if the grid can be divided into vertical bands where each band
     * is uniformly filled with a single character, and all bands have distinct characters.
     */
    private static boolean checkVerticalStripes(String[] grid, int rows, int cols) {
        int partWidth = cols / PARTS;
        char[] leftChars = new char[PARTS];
        leftChars[0] = grid[0].charAt(0);
        leftChars[1] = grid[0].charAt(partWidth);
        leftChars[2] = grid[0].charAt(2 * partWidth);

        if (!areDistinct(leftChars)) {
            return false;
        }

        for (int i = 0; i < PARTS; i++) {
            int colStart = i * partWidth;
            int colEnd = (i + 1) * partWidth - 1;
            if (!isUniformSection(grid, 0, rows - 1, colStart, colEnd, leftChars[i])) {
                return false;
            }
        }
        return true;
    }

    /**
     * Verifies that all three characters are pairwise distinct.
     */
    private static boolean areDistinct(char[] chars) {
        return chars[0] != chars[1] && chars[1] != chars[2] && chars[0] != chars[2];
    }

    /**
     * Checks if all cells within the specified rectangular region contain the target character.
     */
    private static boolean isUniformSection(String[] grid, int rowStart, int rowEnd, int colStart, int colEnd, char target) {
        for (int r = rowStart; r <= rowEnd; r++) {
            String row = grid[r];
            for (int c = colStart; c <= colEnd; c++) {
                if (row.charAt(c) != target) {
                    return false;
                }
            }
        }
        return true;
    }
}

