    private static boolean checkHorizontalStrips(List<String> grid, int rows, int cols) {
        // If rows are not divisible by 3, we cannot form 3 equal strips
        if (rows % REQUIRED_STRIP_COUNT != 0) {
            return false;
        }

        int stripHeight = rows / REQUIRED_STRIP_COUNT;
        Set<Character> distinctChars = new HashSet<>();

        // Iterate over the 3 horizontal strips
        for (int i = 0; i < REQUIRED_STRIP_COUNT; i++) {
            int startRow = i * stripHeight;
            int endRow = startRow + stripHeight;

            // Identify the character that must fill this entire strip.
            // Based on original logic: input[i].charAt(0)
            char stripChar = grid.get(startRow).charAt(0);

            // Validate that every cell in this strip matches the identified character
            for (int r = startRow; r < endRow; r++) {
                String rowStr = grid.get(r);
                for (int c = 0; c < cols; c++) {
                    if (rowStr.charAt(c) != stripChar) {
                        return false;
                    }
                }
            }
            distinctChars.add(stripChar);
        }

        // Ensure all 3 strips have different characters
        return distinctChars.size() == REQUIRED_STRIP_COUNT;
    }

    /**
     * Checks if the grid is divided into 3 vertical strips.
     * Each strip must consist of a single repeating character,
     * and all three strips must have distinct characters.
     */
    private static boolean checkVerticalStrips(List<String> grid, int rows, int cols) {
        // If columns are not divisible by 3, we cannot form 3 equal strips
        if (cols % REQUIRED_STRIP_COUNT != 0) {
            return false;
        }

        int stripWidth = cols / REQUIRED_STRIP_COUNT;
        Set<Character> distinctChars = new HashSet<>();

        // Iterate over the 3 vertical strips
        for (int j = 0; j < REQUIRED_STRIP_COUNT; j++) {
            int startCol = j * stripWidth;
            int endCol = startCol + stripWidth;

            // Identify the character that must fill this entire strip.
            // Based on original logic: input[0].charAt(j)
            char stripChar = grid.get(0).charAt(startCol);

            // Validate that every cell in this strip matches the identified character
            for (int c = startCol; c < endCol; c++) {
