import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Scanner;
import java.util.Set;

public class Codeforces {

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        // Read the number of sets (n)
        if (!sc.hasNextInt()) {
            return;
        }
        int n = sc.nextInt();

        // List to hold the sets of digits available
        List<Set<Integer>> sets = new ArrayList<>();

        // Read n sets, each containing 6 integers
        // The problem context implies reading 6 integers per set
        for (int i = 0; i < n; i++) {
            Set<Integer> currentSet = new HashSet<>();
            for (int j = 0; j < 6; j++) {
                if (sc.hasNextInt()) {
                    currentSet.add(sc.nextInt());
                }
            }
            sets.add(currentSet);
        }

        // Find the smallest positive integer that cannot be formed.
        // The original logic prints (missing_number - 1).
        int number = 1;
        while (true) {
            if (!canForm(number, sets)) {
                System.out.println(number - 1);
                break;
            }
            number++;
        }

        sc.close();
    }

    /**
     * Determines if a given number can be formed using digits from the available sets.
     * Each digit of the number must be assigned to a unique set that contains that digit.
     *
     * @param number The number to check
     * @param sets   The list of available sets
     * @return true if the number can be formed, false otherwise
     */
    private static boolean canForm(int number, List<Set<Integer>> sets) {
        // Extract digits from the number
        List<Integer> digits = new ArrayList<>();
        int temp = number;

        // Handle 0 case, though the loop starts at 1
        if (temp == 0) {
            digits.add(0);
        } else {
            while (temp > 0) {
                digits.add(temp % 10);
                temp /= 10;
            }
        }

        // If the number has more digits than available sets, it's impossible to form
        // because each digit requires a distinct set.
        if (digits.size() > sets.size()) {
            return false;
        }

        // Use backtracking to find a valid assignment of digits to sets
        boolean[] usedSets = new boolean[sets.size()];
        return solve(digits, 0, sets, usedSets);
    }

    /**
     * Recursive backtracking helper to match digits to sets.
     *
     * @param digits     List of digits to match
     * @param digitIndex Current index in the digits list
     * @param sets       List of available sets
     * @param usedSets   Boolean array tracking which sets are currently used
     * @return true if a valid assignment is found, false otherwise
     */
    private static boolean solve(List<Integer> digits, int digitIndex, List<Set<Integer>> sets, boolean[] usedSets) {
        // Base case: All digits have been successfully assigned
        if (digitIndex == digits.size()) {
            return true;
        }

        int currentDigit = digits.get(digitIndex);

        // Try to assign the current digit to any unused set that contains it
        for (int i = 0; i < sets.size(); i++) {
            if (!usedSets[i] && sets.get(i).contains(currentDigit)) {
                usedSets[i] = true; // Mark set as used

                // Recursively attempt to match the next digit
                if (solve(digits, digitIndex + 1, sets, usedSets)) {
                    return true;
                }

                usedSets[i] = false; // Backtrack: unmark set
            }
        }

        return false;
    }
}

