public class Main {
    public static void main(String[] args) {
        // Using Scanner for better maintainability and readability compared to custom FastScanner
        Scanner scanner = new Scanner(System.in);
        if (!scanner.hasNextInt()) {
            return;
        }

        int n = scanner.nextInt();
        List<Set<Integer>> digitLists = new ArrayList<>();

        // Read n lists, each containing exactly 6 integers
        for (int i = 0; i < n; i++) {
            Set<Integer> list = new HashSet<>();
            for (int j = 0; j < 6; j++) {
                if (scanner.hasNextInt()) {
                    list.add(scanner.nextInt());
                }
            }
            digitLists.add(list);
        }

        // Find and print the smallest missing number
        System.out.println(findSmallestMissingNumber(n, digitLists));
    }

    /**
     * Iteratively checks positive integers starting from 1 to find the smallest
     * number that cannot be formed using the provided digit lists.
     */
    private static int findSmallestMissingNumber(int n, List<Set<Integer>> digitLists) {
        int candidate = 1;
        while (true) {
            if (!canFormNumber(candidate, digitLists)) {
                break;
            }
            candidate++;
        }
        return candidate - 1;
    }

    /**
     * Determines if a number can be formed by assigning each of its digits
     * to a distinct list that contains that digit.
     */
    private static boolean canFormNumber(int number, List<Set<Integer>> digitLists) {
        String numberStr = String.valueOf(number);

        // A number cannot be formed if it has more digits than available lists
        if (numberStr.length() > digitLists.size()) {
            return false;
        }

        int[] digits = new int[numberStr.length()];
        for (int i = 0; i < numberStr.length(); i++) {
            digits[i] = numberStr.charAt(i) - '0';
        }

        return canAssignDigits(digits, 0, new boolean[digitLists.size()], digitLists);
    }

    /**
     * Uses backtracking to assign each digit to an unused list that contains it.
     */
    private static boolean canAssignDigits(int[] digits, int digitIndex, boolean[] usedLists, List<Set<Integer>> digitLists) {
        // Base case: All digits have been successfully assigned
        if (digitIndex == digits.length) {
            return true;
        }

        // Try to assign the current digit to any available list that contains it
        for (int i = 0; i < digitLists.size(); i++) {
            if (!usedLists[i] && digitLists.get(i).contains(digits[digitIndex])) {
                usedLists[i] = true;
                if (canAssignDigits(digits, digitIndex + 1, usedLists, digitLists)) {
                    return true;
                }
                usedLists[i] = false; // Backtrack
            }
        }
        return false;
    }
}

