        // Read input data
        // Original code: c[i][j] = in.nextInt(); set[i].add(c[i][j]);
        // Refactored: Removed the unused 'c' array to save memory.
        // Added a bounds check (i < sets.size()) to prevent ArrayIndexOutOfBoundsException
        // if the input 'n' exceeds the number of available sets (3).
        for (int i = 0; i < n; i++) {
            if (i >= sets.size()) {
                // If input exceeds available sets, stop reading to avoid crash.
                // In a strict CP context, input usually respects constraints.
                break; 
            }
            for (int j = 0; j < 6; j++) {
                int val = in.nextInt();
                sets.get(i).add(val);
            }
        }

        // Find the largest number x such that isPossible(x) is true.
        // The original code starts checking from 1.
        int i = 1;
        while (isPossible(i)) {
            i++;
        }

        // Output the last possible number
        System.out.println(i - 1);
    }

    /**
     * Checks if the number x can be formed by assigning each of its digits
     * to a unique set (from the 3 available sets) such that the digit 
     * exists in the assigned set.
     * 
     * Logic derived from original code:
     * 1. 1-digit numbers: digit must be in any of the 3 sets.
     * 2. 2-digit numbers: ones digit in Set A, tens digit in Set B (A != B).
     * 3. 3-digit numbers: ones in A, tens in B, hundreds in C (A, B, C distinct).
     * 4. Numbers > 3 digits are impossible with 3 distinct sets.
     */
    public static boolean isPossible(int x) {
        if (x < 0) return false; // Negative numbers are not valid in this context

        // Extract digits. Order: ones, tens, hundreds... (LSB first)
        List<Integer> digits = new ArrayList<>();
        int temp = x;
        if (temp == 0) {
            digits.add(0);
        } else {
            while (temp > 0) {
                digits.add(temp % 10);
                temp /= 10;
            }
        }

        // If the number has more digits than available sets (3), it's impossible
        // because we need distinct sets for each digit position based on original logic.
        if (digits.size() > 3) {
            return false;
        }

        // Use backtracking to check if there is a valid assignment of sets to digits.
        // This replaces the verbose if/else blocks for 1, 2, and 3-digit checks.
        boolean[] usedSets = new boolean[3]; // Tracks which set indices (0, 1, 2) are currently in use
        return canAssignDigits(0, digits, usedSets);
    }

    /**
     * Recursive helper to assign sets to digits using backtracking.
     * 
     * @param digitIndex The current digit position we are trying to assign (0 = ones, 1 = tens...)
     * @param digits List of digits of the number x
     * @param usedSets Boolean array tracking which set indices are currently in use
     * @return true if a valid assignment is found, false otherwise
     */
    private static boolean canAssignDigits(int digitIndex, List<Integer> digits, boolean[] usedSets) {
        // Base case: All digits have been successfully assigned
        if (digitIndex == digits.size()) {
            return true;
        }

        int currentDigit = digits.get(digitIndex);

        // Try to assign the current digit to any unused set
        for (int setIdx = 0; setIdx < 3; setIdx++) {
            if (!usedSets[setIdx]) {
                // Check if the set contains the required digit
                if (sets.get(setIdx).contains(currentDigit)) {
                    // Mark set as used and move to next digit
                    usedSets[setIdx] = true;
                    if (canAssignDigits(digitIndex + 1, digits, usedSets)) {
                        return true;
                    }
                    // Backtrack: unmark the set to try other possibilities
                    usedSets[setIdx] = false;
                }
            }
        }

        return false;
    }

    // FastReader class for efficient input reading (standard for Competitive Programming)
    static class FastReader {
        BufferedReader br;
        StringTokenizer st;

        public FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    e.printStackTrace();
                    return null;
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            String s = next();
            return (s == null) ? 0 : Integer.parseInt(s);
        }

        long nextLong() {
            String s = next();
            return (s == null) ? 0L : Long.parseLong(s);
        }

        double nextDouble() {
            String s = next();
            return (s == null) ? 0.0 : Double.parseDouble(s);
        }

        String nextLine() {
            String str = "";
            try {
                str = br.readLine();
            } catch (IOException e) {
                e.printStackTrace();
            }
            return str;
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayList;
import java.util.List;
import java.util.StringTokenizer;

public class Main {

    private static final int MAX_CHECK_LIMIT = 10000;
    private static final int DIGITS_PER_GROUP = 6;

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner();
        if (!scanner.hasNext()) {
            return;
        }

        int n = scanner.nextInt();
        boolean[] isReachable = new boolean[MAX_CHECK_LIMIT + 1];
        List<Integer> reachableNumbers = new ArrayList<>();

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < DIGITS_PER_GROUP; j++) {
                int digit = scanner.nextInt();
                List<Integer> newCandidates = new ArrayList<>();

                // The digit itself forms a new reachable number
                newCandidates.add(digit);

                // Generate new numbers by inserting the digit into all currently reachable numbers
                for (int num : reachableNumbers) {
                    generateCombinations(num, digit, newCandidates);
                }

                // Mark newly found numbers and update the reachable list
                for (int num : newCandidates) {
                    if (num <= MAX_CHECK_LIMIT && !isReachable[num]) {
                        isReachable[num] = true;
                        reachableNumbers.add(num);
                    }
                }
            }
        }

        int consecutiveCount = 0;
        for (int i = 1; i <= MAX_CHECK_LIMIT; i++) {
            if (isReachable[i]) {
                consecutiveCount++;
            } else {
                break;
            }
        }

        System.out.println(consecutiveCount);
    }

    /**
     * Generates new numbers by inserting a digit at every possible position
     * within the string representation of the base number.
     */
    private static void generateCombinations(int baseNumber, int digit, List<Integer> results) {
        String baseStr = String.valueOf(baseNumber);
        for (int pos = 0; pos <= baseStr.length(); pos++) {
            String newStr = baseStr.substring(0, pos) + digit + baseStr.substring(pos);
            try {
                int newNumber = Integer.parseInt(newStr);
                if (newNumber <= MAX_CHECK_LIMIT) {
                    results.add(newNumber);
                }
            } catch (NumberFormatException e) {
                // Ignore numbers that exceed integer range or are malformed
            }
        }
    }

    /**
     * Fast I/O helper class for efficient console input.
     */
    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        boolean hasNext() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) {
                        return false;
                    }
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input", e);
                }
            }
            return true;
        }

        String next() {
            if (hasNext()) {
                return st.nextToken();
            }
            throw new RuntimeException("No more tokens available");
        }

        int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.util.Scanner;

/**
 * Finds the maximum consecutive integer starting from 1 that can be formed
 * using the faces of a given set of cubes.
 */
public class CubeConsecutiveNumbers {

    private static final int NUM_FACES = 6;

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            if (!scanner.hasNextInt()) {
                return;
            }

            int n = scanner.nextInt();
            int[][] cubes = readCubes(scanner, n);

            int maxConsecutive = findMaxConsecutiveNumber(n, cubes);
            System.out.println(maxConsecutive);
        }
    }

    /**
     * Reads the cube faces from standard input.
     */
    private static int[][] readCubes(Scanner scanner, int n) {
        int[][] cubes = new int[n][NUM_FACES];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < NUM_FACES; j++) {
                cubes[i][j] = scanner.nextInt();
            }
        }
        return cubes;
    }

    /**
     * Finds the largest consecutive integer starting from 1 that can be formed
     * using the provided cubes.
     */
    private static int findMaxConsecutiveNumber(int n, int[][] cubes) {
        int consecutiveNumber = 1;
        while (canFormNumber(consecutiveNumber, cubes)) {
            consecutiveNumber++;
        }
        return consecutiveNumber - 1;
    }

    /**
     * Checks if a given number can be formed using distinct cubes.
     */
    private static boolean canFormNumber(int number, int[][] cubes) {
        String digits = String.valueOf(number);
        boolean[] usedCubes = new boolean[cubes.length];
        return backtrack(digits, 0, usedCubes, cubes);
    }

    /**
     * Backtracking algorithm to assign each digit of the number to an available cube.
     */
    private static boolean backtrack(String digits, int index, boolean[] usedCubes, int[][] cubes) {
        // Base case: all digits have been successfully assigned
        if (index == digits.length()) {
            return true;
        }

        int digit = digits.charAt(index) - '0';
        for (int cubeIndex = 0; cubeIndex < usedCubes.length; cubeIndex++) {
            if (!usedCubes[cubeIndex] && hasDigitOnCube(cubes[cubeIndex], digit)) {
                usedCubes[cubeIndex] = true;
                if (backtrack(digits, index + 1, usedCubes, cubes)) {
                    return true;
                }
                usedCubes[cubeIndex] = false; // Backtrack: unmark cube for other possibilities
            }
        }
        return false;
    }

    /**
     * Checks if a specific digit exists on a cube's faces.
     */
    private static boolean hasDigitOnCube(int[] faces, int digit) {
        for (int face : faces) {
            if (face == digit) {
                return true;
            }
        }
        return false;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

public class Main {
    public static void main(String[] args) throws IOException {
        FastScanner sc = new FastScanner(System.in);

        String nStr = sc.next();
        if (nStr == null) return;
        int n = Integer.parseInt(nStr);

        // Use boolean array for semantic clarity: dice[i][face] indicates if die i has face
        boolean[][] dice = new boolean[n][10];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < 6; j++) {
                int face = sc.nextInt();
                if (face >= 1 && face <= 9) {
                    dice[i][face] = true;
                }
            }
        }

        // Find the smallest positive integer that cannot be formed by the dice
        // The problem asks to print (first_unformable - 1)
        for (int i = 1; ; i++) {
            if (!canForm(dice, i)) {
                System.out.println(i - 1);
                break;
            }
        }
    }

    /**
     * Checks if the given number can be formed by assigning each of its digits
     * to a distinct die that contains that digit.
     */
    private static boolean canForm(boolean[][] dice, int number) {
        String s = Integer.toString(number);
        int len = s.length();
        int[] digits = new int[len];
        for (int i = 0; i < len; i++) {
            digits[i] = s.charAt(i) - '0';
        }

        boolean[] usedDice = new boolean[dice.length];
        return backtrack(digits, 0, len, usedDice, dice);
    }

    /**
     * Backtracking to find a valid assignment of digits to dice.
     */
    private static boolean backtrack(int[] digits, int idx, int len, boolean[] usedDice, boolean[][] dice) {
        if (idx == len) {
            return true; // All digits successfully assigned
        }

        int digit = digits[idx];
        for (int d = 0; d < dice.length; d++) {
            if (!usedDice[d] && dice[d][digit]) {
                usedDice[d] = true;
                if (backtrack(digits, idx + 1, len, usedDice, dice)) {
                    return true;
                }
                usedDice[d] = false; // Backtrack
            }
        }
        return false;
    }

    /**
     * Lightweight, efficient input scanner for competitive programming / IO-heavy tasks.
     */
    static class FastScanner {
        private BufferedReader br;
        private StringTokenizer st;

        public FastScanner(InputStream stream) {
            br = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) return null;
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

        public int nextInt() throws IOException {
            String s = next();
            if (s == null) throw new IOException("Unexpected end of input");
            return Integer.parseInt(s);
        }
    }
}

import java.io.InputStream;
import java.io.OutputStream;
import java.io.PrintWriter;
import java.util.Scanner;

public class Main {
    private static final int MAX_DIGITS_PER_CUBE = 6;
    private static final int MAX_NUMBER = 1000; // Covers all numbers up to 3 digits (0-999)

    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        Scanner in = new Scanner(inputStream);
        PrintWriter out = new PrintWriter(outputStream);

        solve(in, out);

        out.close();
    }

    private static void solve(Scanner in, PrintWriter out) {
        if (!in.hasNextInt()) return;
        int n = in.nextInt();
        int[][] cubes = new int[n][MAX_DIGITS_PER_CUBE];

        // Read cube faces
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < MAX_DIGITS_PER_CUBE; j++) {
                cubes[i][j] = in.nextInt();
            }
        }

        boolean[] possibleNumbers = new boolean[MAX_NUMBER];

        // Mark all possible numbers of length 1 to n using distinct cubes
        for (int len = 1; len <= n; len++) {
            boolean[] usedCubes = new boolean[n];
            generateNumbersOfLength(len, 0, 0, usedCubes, n, cubes, possibleNumbers);
        }

        // Find the smallest missing positive integer
        for (int i = 1; i < MAX_NUMBER; i++) {
            if (!possibleNumbers[i]) {
                out.print(i - 1);
                return;
            }
        }

        // If all numbers up to 999 are possible, output the maximum for n digits
        out.print((int) Math.pow(10, n) - 1);
    }

    /**
     * Recursively generates all numbers of a specific length using distinct cubes.
     *
     * @param targetLen  The desired number length
     * @param currentLen The length of the number built so far
     * @param currentVal The numeric value built so far
     * @param usedCubes  Tracks which cubes have already been used in the current permutation
     * @param n          Total number of cubes available
     * @param cubes      2D array of cube faces
     * @param nos        Boolean array to mark achievable numbers
     */
    private static void generateNumbersOfLength(int targetLen, int currentLen, int currentVal, 
                                                boolean[] usedCubes, int n, int[][] cubes, boolean[] nos) {
        if (currentLen == targetLen) {
            nos[currentVal] = true;
            return;
        }

        for (int i = 0; i < n; i++) {
            if (!usedCubes[i]) {
                usedCubes[i] = true;
                for (int face : cubes[i]) {
                    generateNumbersOfLength(targetLen, currentLen + 1, currentVal * 10 + face, 
                                            usedCubes, n, cubes, nos);
                }
                usedCubes[i] = false; // Backtrack
            }
        }
    }
}

import java.util.Scanner;

/**
 * Solves the "Cubes for Masha" problem.
 * Finds the smallest positive integer that can be formed using exactly 3 distinct cubes.
 * Refactored from B_KubikiDlyaMashi for maintainability and correctness.
 */
public class CubeForMasha {
    private final int[][] cubes;
    private final int numCubes;

    public CubeForMasha(int[][] cubes) {
        this.cubes = cubes;
        this.numCubes = cubes.length;
    }

    /**
     * Finds the smallest positive integer that can be formed using 3 distinct cubes.
     * Returns 0 if no such number can be formed (or exceeds a safety limit).
     */
    public int findSmallestFormableNumber() {
        int number = 1;
        // Safety limit added for robustness; competitive programming problems 
        // typically guarantee a solution within reasonable bounds.
        while (number <= 10000) {
            if (canFormNumber(number)) {
                return number;
            }
            number++;
        }
        return 0;
    }

    private boolean canFormNumber(int number) {
        int[] digits = extractDigits(number);
        // Original implementation only checked 3 cubes, so numbers with >3 digits are invalid
        if (digits.length > 3) {
            return false;
        }
        boolean[] usedCubes = new boolean[numCubes];
        return matchDigits(digits, 0, usedCubes);
    }

    /**
     * Recursively tries to assign each digit to a distinct available cube.
     */
    private boolean matchDigits(int[] digits, int digitIndex, boolean[] usedCubes) {
        if (digitIndex == digits.length) {
            return true; // All digits successfully matched
        }

        int targetDigit = digits[digitIndex];
        for (int i = 0; i < numCubes; i++) {
            if (!usedCubes[i] && hasFace(cubes[i], targetDigit)) {
                usedCubes[i] = true;
                if (matchDigits(digits, digitIndex + 1, usedCubes)) {
                    return true;
                }
                usedCubes[i] = false; // Backtrack
            }
        }
        return false;
    }

    private boolean hasFace(int[] cubeFaces, int faceValue) {
        for (int face : cubeFaces) {
            if (face == faceValue) {
                return true;
            }
        }
        return false;
    }

    private int[] extractDigits(int number) {
        if (number == 0) {
            return new int[]{0};
        }
        String numStr = Integer.toString(number);
        int[] digits = new int[numStr.length()];
        for (int i = 0; i < numStr.length(); i++) {
            digits[i] = numStr.charAt(i) - '0';
        }
        return digits;
    }

    public static void main(String[] args) {
        try (Scanner sc = new Scanner(System.in)) {
            if (!sc.hasNextInt()) {
                System.out.println(0);
                return;
            }

            int n = sc.nextInt();
            int[][] cubes = new int[n][6];
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < 6; j++) {
                    cubes[i][j] = sc.nextInt();
                }
            }

            CubeForMasha solver = new CubeForMasha(cubes);
            System.out.println(solver.findSmallestFormableNumber());
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Solves a dice combination problem by tracking achievable values
 * using a BitSet and finding the smallest missing non-negative integer.
 */
public class DiceCombinationsSolver {

    private static final int DICE_FACES = 6;
    private static final int INITIAL_BITSET_CAPACITY = 1001;

    public static void main(String[] args) {
        // Use try-with-resources to guarantee proper resource cleanup
        try (FastScanner in = new FastScanner(System.in);
             PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out))) {
            new DiceCombinationsSolver().solve(in, out);
        }
    }

    /**
     * Orchestrates the solving process: reads input, computes possible values,
     * and outputs the result.
     */
    void solve(FastScanner in, PrintWriter out) {
        int n = in.nextInt();
        int[][] dice = readDiceFaces(in, n);

        BitSet possibleValues = new BitSet(INITIAL_BITSET_CAPACITY);
        possibleValues.set(0); // Preserve original behavior: 0 is always considered present
        populateSingleFaces(possibleValues, dice);

        if (n >= 2) {
            populateTwoDiceCombinations(possibleValues, dice);
        }
        if (n == 3) {
            populateThreeDiceCombinations(possibleValues, dice);
        }

        // Find the smallest non-negative integer not in the set, then subtract 1
        int smallestMissing = possibleValues.nextClearBit(0);
        out.println(smallestMissing - 1);
    }

    /**
     * Reads n dice, each with 6 faces, from the input stream.
     */
    private int[][] readDiceFaces(FastScanner in, int n) {
        int[][] dice = new int[n][DICE_FACES];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < DICE_FACES; j++) {
                dice[i][j] = in.nextInt();
            }
        }
        return dice;
    }

    /**
     * Marks all individual die faces as achievable values.
     */
    private void populateSingleFaces(BitSet bs, int[][] dice) {
        for (int[] die : dice) {
            for (int face : die) {
                bs.set(face);
            }
        }
    }

    /**
     * Generates and marks all two-digit combinations formed by the first two dice.
     */
    private void populateTwoDiceCombinations(BitSet bs, int[][] dice) {
        for (int a = 0; a < DICE_FACES; a++) {
            for (int b = 0; b < DICE_FACES; b++) {
                bs.set(dice[0][a] * 10 + dice[1][b]);
                bs.set(dice[1][b] * 10 + dice[0][a]);
            }
        }
    }

    /**
     * Generates and marks all two-digit combinations formed by the third die
     * paired with the first and second dice.
     */
    private void populateThreeDiceCombinations(BitSet bs, int[][] dice) {
        for (int a = 0; a < DICE_FACES; a++) {
            for (int b = 0; b < DICE_FACES; b++) {
                bs.set(dice[2][a] * 10 + dice[1][b]);
                bs.set(dice[2][a] * 10 + dice[0][b]);
                bs.set(dice[0][b] * 10 + dice[2][a]);
                bs.set(dice[1][b] * 10 + dice[2][a]);
            }
        }
    }

    /**
     * Fast input reader using BufferedReader and StringTokenizer.
     * Replaces the custom byte-level reader for better maintainability,
     * correctness, and standard library compliance.
     */
    static class FastScanner {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastScanner(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) {
                        throw new EOFException("End of input reached");
                    }
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input", e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }

        public double nextDouble() {
            return Double.parseDouble(next());
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;

public class ProblemB {
    private static final int[][] PERMUTATIONS = {
        {0, 1, 2}, {0, 2, 1}, {1, 0, 2}, {1, 2, 0}, {2, 0, 1}, {2, 1, 0}
    };

    private final BufferedReader reader;

    public static void main(String[] args) {
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(System.in))) {
            new ProblemB(reader).run();
        } catch (IOException e) {
            System.err.println("Error reading input: " + e.getMessage());
        }
    }

    public ProblemB(BufferedReader reader) {
        this.reader = reader;
    }

    private void run() throws IOException {
        int n = readInt();
        int[][] constraints = new int[n][];
        for (int i = 0; i < n; i++) {
            constraints[i] = readIntArray();
        }

        int limit = 1;
        for (int i = 0; i < n; i++) {
            limit *= 10;
        }

        int maxValidNumber = 0;
        for (int candidate = 1; candidate < limit; candidate++) {
            if (isValid(candidate, constraints)) {
                maxValidNumber = candidate;
            }
        }
        System.out.println(maxValidNumber);
    }

    private int readInt() throws IOException {
        return Integer.parseInt(reader.readLine().trim());
    }

    private int[] readIntArray() throws IOException {
        String[] parts = reader.readLine().trim().split("\\s+");
        int[] result = new int[parts.length];
        for (int i = 0; i < parts.length; i++) {
            result[i] = Integer.parseInt(parts[i]);
        }
        return result;
    }

    private boolean isValid(int number, int[][] constraints) {
        String numberStr = Integer.toString(number);
        int length = numberStr.length();
        int[] digits = new int[length];
        for (int i = 0; i < length; i++) {
            digits[i] = numberStr.charAt(i) - '0';
        }

        for (int[] permutation : PERMUTATIONS) {
            if (matchesConstraints(digits, permutation, constraints)) {
                return true;
            }
        }
        return false;
    }

    private boolean matchesConstraints(int[] digits, int[] permutation, int[][] constraints) {
        for (int i = 0; i < digits.length; i++) {
            int constraintIndex = permutation[i];
            if (constraintIndex >= constraints.length) {
                return false;
            }
            if (!contains(constraints[constraintIndex], digits[i])) {
                return false;
            }
        }
        return true;
    }

    private boolean contains(int[] array, int value) {
        for (int element : array) {
            if (element == value) {
                return true;
            }
        }
        return false;
    }
}

import java.util.Scanner;
import java.util.Arrays;

/**
 * A class to solve the number combination problem.
 * It finds the largest integer that can be formed using digits selected from a matrix,
 * subject to specific constraints on digit usage and number length.
 */
public class NumberCombinator {

    // Constant for the number of columns in the matrix
    private static final int MATRIX_COLUMNS = 6;

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        // Read n (number of rows)
        if (!scanner.hasNextInt()) {
            return;
        }
        int n = scanner.nextInt();

        // Read the n x 6 matrix
        int[][] matrix = new int[n][MATRIX_COLUMNS];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < MATRIX_COLUMNS; j++) {
                if (scanner.hasNextInt()) {
                    matrix[i][j] = scanner.nextInt();
                }
            }
        }
        scanner.close();

        // Array to store the current combination of column indices (0 to 5)
        int[] indices = new int[n];
        // Array to store the digits selected from the matrix based on indices
        int[] selectedDigits = new int[n];

        int currentNumber = 1;
        // Calculate limit. Note: For n > 9, this overflows int.
        // Original code used int, so we maintain that behavior.
        int limit = (int) Math.pow(10, n);

        // Iterate through numbers starting from 1 to find the first one that cannot be formed
        while (currentNumber < limit) {
            boolean canForm = false;

            // Reset indices to start from the first combination (0, 0, ..., 0)
            Arrays.fill(indices, 0);

            // Try all valid combinations of indices to form the number
            do {
                // Populate selectedDigits based on current indices
                for (int i = 0; i < n; i++) {
                    selectedDigits[i] = matrix[i][indices[i]];
                }

                // Check if the current number can be formed by these digits
                if (canFormNumber(currentNumber, selectedDigits)) {
                    canForm = true;
                }

                // Move to the next combination
                // Continue only if a valid combination exists AND we haven't found the number yet
            } while (incrementCombination(indices, MATRIX_COLUMNS - 1) && !canForm);

            // If we exhausted all combinations and still couldn't form the number,
            // then currentNumber is the first impossible number.
            if (!canForm) {
                break;
            }

            currentNumber++;
        }

        // Output the largest number that could be formed (which is currentNumber - 1)
        System.out.println(currentNumber - 1);
    }

    /**
     * Checks if the target number can be formed using the available digits.
     * Logic preserved from original code:
     * - 1 digit: Check if digit exists.
     * - 2 digits: Check if formed by 2 distinct digits.
     * - 3+ digits: Check if formed by 3 distinct digits (Original code limit).
     */
    private static boolean canFormNumber(int target, int[] digits) {
        if (target < 10) {
            // Check for single digit match
            for (int d : digits) {
                if (d == target) {
                    return true;
                }
            }
        } else if (target < 100) {
            // Check for 2-digit number formed by distinct digits
            for (int i = 0; i < digits.length; i++) {
                for (int j = 0; j < digits.length; j++) {
                    if (i != j && (digits[i] * 10 + digits[j] == target)) {
                        return true;
                    }
                }
            }
        } else {
            // Check for 3-digit number formed by distinct digits
            // Note: Original code logic falls through to here for x >= 100.
            // It does not handle numbers >= 1000.
            for (int i = 0; i < digits.length; i++) {
                for (int j = 0; j < digits.length; j++) {
                    if (i == j) continue;
                    for (int k = 0; k < digits.length; k++) {
                        if (k == i || k == j) continue;

                        int formedNumber = digits[i] * 100 + digits[j] * 10 + digits[k];
                        if (formedNumber == target) {
                            return true;
                        }
                    }
                }
            }
        }
        return false;
    }

    /**
     * Increments the combination array as if it were a number in base (maxValue + 1).
     * Resets digits to 0 when they overflow.
     *
     * @param indices The array of indices to increment.
     * @param maxValue The maximum allowed value for an index (exclusive upper bound for increment check).
     * @return true if increment was successful, false if overflow occurred.
     */
    private static boolean incrementCombination(int[] indices, int maxValue) {
        int i = indices.length - 1;
        while (i >= 0 && indices[i] == maxValue) {
            indices[i] = 0;
            i--;
        }

        if (i < 0) {
            return false; // Overflow
        }

        indices[i]++;
        return true;
    }
}

import java.io.BufferedReader;
import java.io.BufferedOutputStream;
import java.io.Closeable;
import java.io.Flushable;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.OutputStream;
import java.util.InputMismatchException;
import java.util.StringTokenizer;

public class Main {

    // Constants to replace magic numbers
    private static final int MAX_NUMBER = 1000;
    private static final int THREAD_STACK_SIZE = 1 << 29;
    private static final int OUTPUT_BUFFER_SIZE = 1 << 16;
    private static final int INPUT_BUFFER_SIZE = 1 << 20;
    private static final int OUTPUT_STREAM_BUFFER_SIZE = 1 << 17;

    public static void main(String[] args) {
        Thread thread = new Thread(null, new SolverTask(), "CubeSolverThread", THREAD_STACK_SIZE);
        thread.start();
        try {
            thread.join();
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
    }

    static class SolverTask implements Runnable {
        @Override
        public void run() {
            try (FastInput in = new FastInput(System.in);
                 FastOutput out = new FastOutput(System.out)) {
                new CubeSolver().solve(1, in, out);
            } catch (Exception e) {
                // In competitive programming, uncaught exceptions typically cause a Runtime Error.
                // We wrap checked exceptions to keep the signature clean.
                throw new RuntimeException(e);
            }
        }
    }

    static class CubeSolver {
        public void solve(int testNumber, FastInput in, FastOutput out) {
            int n = in.nextInt();
            int[][] cubes = new int[n][6];
            boolean[] possible = new boolean[MAX_NUMBER];
            possible[0] = true;

            // Read cube faces and mark single-digit possibilities
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < 6; j++) {
                    int faceValue = in.nextInt();
                    cubes[i][j] = faceValue;
                    if (faceValue < MAX_NUMBER) {
                        possible[faceValue] = true;
                    }
                }
            }

            // Mark 2-digit combinations from pairs of cubes
            if (n > 1) {
                for (int i = 0; i < n; i++) {
                    for (int j = i + 1; j < n; j++) {
                        for (int k = 0; k < 6; k++) {
                            for (int l = 0; l < 6; l++) {
                                int val1 = cubes[i][k] * 10 + cubes[j][l];
                                int val2 = cubes[j][l] * 10 + cubes[i][k];
                                if (val1 < MAX_NUMBER) possible[val1] = true;
                                if (val2 < MAX_NUMBER) possible[val2] = true;
                            }
                        }
                    }
                }
            }

            // Mark 3-digit combinations from triplets of cubes
            if (n > 2) {
                int[] cubeIndices = {0, 1, 2};
                do {
                    for (int i = 0; i < 6; i++) {
                        for (int j = 0; j < 6; j++) {
                            for (int k = 0; k < 6; k++) {
                                int val = cubes[cubeIndices[0]][i] * 100 +
                                          cubes[cubeIndices[1]][j] * 10 +
                                          cubes[cubeIndices[2]][k];
                                if (val < MAX_NUMBER) {
                                    possible[val] = true;
                                }
                            }
                        }
                    }
                } while (PermutationUtils.nextPermutation(cubeIndices));
            }

            // Find the smallest non-negative integer that cannot be formed
            for (int i = 0; i < MAX_NUMBER; i++) {
                if (!possible[i]) {
                    out.println(i - 1);
                    return;
                }
            }
        }
    }

    /**
     * Fast buffered output writer optimized for competitive programming.
     */
    static class FastOutput implements Closeable, Flushable {
        private final OutputStream os;
        private final StringBuilder sb;
        private final int bufferSize;
        private final String lineSeparator;

        public FastOutput(OutputStream os) {
            this(os, OUTPUT_BUFFER_SIZE);
        }

        public FastOutput(OutputStream os, int bufferSize) {
            this.os = new BufferedOutputStream(os, OUTPUT_STREAM_BUFFER_SIZE);
            this.bufferSize = bufferSize;
            this.sb = new StringBuilder(bufferSize);
            this.lineSeparator = System.lineSeparator();
        }

        public void println(int i) {
            println(String.valueOf(i));
        }

        public void println(String s) {
            sb.append(s).append(lineSeparator);
            // Auto-flush when buffer reaches half capacity to balance memory and I/O ops
            if (sb.length() > bufferSize / 2) {
                flush();
            }
        }

        @Override
        public void flush() {
            try {
                os.write(sb.toString().getBytes());
                os.flush();
                sb.setLength(0); // Reuse buffer instead of allocating new instance
            } catch (IOException e) {
                throw new RuntimeException(e);
            }
        }

        @Override
        public void close() {
            flush();
            try {
                os.close();
            } catch (IOException e) {
                throw new RuntimeException(e);
            }
        }
    }

    /**
     * Fast buffered input reader optimized for competitive programming.
     */
    static class FastInput {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastInput(InputStream is) {
            this(is, INPUT_BUFFER_SIZE);
        }

        public FastInput(InputStream is, int bufferSize) {
            this.br = new BufferedReader(new InputStreamReader(is), bufferSize);
            this.st = null;
        }

        public boolean hasNext() {
            try {
                while (st == null || !st.hasMoreTokens()) {
                    String line = br.readLine();
                    if (line == null) {
                        return false;
                    }
                    st = new StringTokenizer(line);
                }
                return true;
            } catch (IOException e) {
                throw new RuntimeException(e);
            }
        }

        public String next() {
            if (!hasNext()) {
                throw new InputMismatchException();
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }

    /**
     * Utility methods for array permutations and manipulations.
     */
    static class PermutationUtils {
        static void swap(int[] arr, int i, int j) {
            int temp = arr[i];
            arr[i] = arr[j];
            arr[j] = temp;
        }

        static void reverse(int[] arr, int i, int j) {
            while (i < j) {
                int temp = arr[i];
                arr[i++] = arr[j];
                arr[j--] = temp;
            }
        }

        static boolean nextPermutation(int[] data) {
            if (data.length <= 1) {
                return false;
            }
            int last = data.length - 2;
            while (last >= 0) {
                if (data[last] < data[last + 1]) {
                    break;
                }
                last--;
            }
            if (last < 0) {
                return false;
            }
            int nextGreater = data.length - 1;
            for (int i = data.length - 1; i > last; i--) {
                if (data[i] > data[last]) {
                    nextGreater = i;
                    break;
                }
            }
            swap(data, nextGreater, last);
            reverse(data, last + 1, data.length - 1);
            return true;
        }
    }
}

import java.io.*;
import java.util.StringTokenizer;

/**
 * Finds the smallest positive integer that cannot be formed by concatenating
 * single digits from the given n strings, where each digit must come from a
 * distinct string.
 */
public class DigitSequenceChecker {

    public static void main(String[] args) {
        // try-with-resources ensures proper cleanup of I/O streams
        try (FastScanner scanner = new FastScanner(System.in);
             PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out))) {

            new DigitSequenceChecker().run(scanner, out);
        } catch (IOException e) {
            System.err.println("I/O error: " + e.getMessage());
        }
    }

    /**
     * Orchestrates the execution flow: reads input, processes data, and prints result.
     */
    void run(FastScanner scanner, PrintWriter out) throws IOException {
        int n = scanner.nextInt();
        String[] strings = readAndConvertToStrings(scanner, n);
        int result = findSmallestMissingNumber(strings);
        out.println(result);
    }

    /**
     * Reads the n x 6 integer matrix and converts each row into a concatenated string.
     * Uses a single StringBuilder instance to avoid excessive object creation.
     */
    private String[] readAndConvertToStrings(FastScanner scanner, int n) throws IOException {
        String[] strings = new String[n];
        StringBuilder sb = new StringBuilder(6);
        for (int i = 0; i < n; i++) {
            sb.setLength(0); // Reuse buffer efficiently
            for (int j = 0; j < 6; j++) {
                sb.append(scanner.nextInt());
            }
            strings[i] = sb.toString();
        }
        return strings;
    }

    /**
     * Iterates from 1 to 999 and returns the largest consecutive number that can be formed.
     * If 1 cannot be formed, returns 0.
     */
    private int findSmallestMissingNumber(String[] strings) {
        for (int i = 1; i <= 999; i++) {
            if (!canFormNumber(i, strings)) {
                return i - 1;
            }
        }
        return 999; // Fallback (should theoretically be unreachable given problem constraints)
    }

    /**
     * Checks if a number can be formed by picking distinct strings that contain each digit in order.
     * Uses backtracking for clean, uniform handling of 1, 2, and 3-digit numbers.
     */
    private boolean canFormNumber(int number, String[] strings) {
        String numStr = String.valueOf(number);
        boolean[] used = new boolean[strings.length];
        return canFormDigits(numStr, 0, strings, used);
    }

    /**
     * Recursive helper to assign each digit of numStr to a distinct string.
     */
    private boolean canFormDigits(String numStr, int idx, String[] strings, boolean[] used) {
        if (idx == numStr.length()) {
            return true; // All digits successfully assigned
        }

        char target = numStr.charAt(idx);
        for (int i = 0; i < strings.length; i++) {
            if (!used[i] && strings[i].indexOf(target) != -1) {
                used[i] = true;
                if (canFormDigits(numStr, idx + 1, strings, used)) {
                    return true;
                }
                used[i] = false; // Backtrack
            }
        }
        return false;
    }

    /**
     * Fast I/O helper class to handle tokenized input efficiently.
     */
    static class FastScanner implements AutoCloseable {
        private final BufferedReader br;
        private StringTokenizer stok;

        FastScanner(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        String nextToken() throws IOException {
            while (stok == null || !stok.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) {
                    return null;
                }
                stok = new StringTokenizer(line);
            }
            return stok.nextToken();
        }

        int nextInt() throws IOException {
            String token = nextToken();
            if (token == null) {
                throw new IOException("Unexpected end of input");
            }
            return Integer.parseInt(token);
        }

        @Override
        public void close() throws IOException {
            br.close();
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.OutputStream;
import java.io.PrintWriter;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.StringTokenizer;

public class Template {

    /** Number of digits per input group */
    private static final int NUM_DIGITS_PER_GROUP = 6;
    /** Maximum positive integer to search for consecutive presence */
    private static final int MAX_SEARCH = 100;

    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);

        Solver solver = new Solver();
        solver.solve(in, out);

        out.close();
    }

    /**
     * Handles the core problem-solving logic.
     */
    static class Solver {
        public void solve(InputReader in, PrintWriter out) {
            int numGroups = in.nextInt();
            int totalDigits = numGroups * NUM_DIGITS_PER_GROUP;
            List<Integer> digits = new ArrayList<>(totalDigits);

            // Read initial digits
            for (int i = 0; i < totalDigits; i++) {
                digits.add(in.nextInt());
            }

            // Generate all two-digit combinations from pairs of groups
            generateCombinations(digits, numGroups);

            // Sort to enable efficient sequential search
            Collections.sort(digits);

            // Find the length of the longest consecutive sequence starting from 1
            int result = findConsecutiveSequenceLength(digits, MAX_SEARCH);
            out.print(result);
        }

        /**
         * Generates all possible two-digit numbers by concatenating digits 
         * from every unique pair of groups. Assumes input digits are single-digit (0-9).
         */
        private void generateCombinations(List<Integer> digits, int numGroups) {
            for (int g1 = 0; g1 < numGroups; g1++) {
                for (int g2 = g1 + 1; g2 < numGroups; g2++) {
                    int start1 = g1 * NUM_DIGITS_PER_GROUP;
                    int end1 = start1 + NUM_DIGITS_PER_GROUP;
                    int start2 = g2 * NUM_DIGITS_PER_GROUP;
                    int end2 = start2 + NUM_DIGITS_PER_GROUP;

                    for (int i = start1; i < end1; i++) {
                        for (int j = start2; j < end2; j++) {
                            int d1 = digits.get(i);
                            int d2 = digits.get(j);
                            // Concatenate digits: d1*10 + d2 and d2*10 + d1
                            digits.add(d1 * 10 + d2);
                            digits.add(d2 * 10 + d1);
                        }
                    }
                }
            }
        }

        /**
         * Finds the length of the longest consecutive sequence of positive integers 
         * starting from 1 that are present in the sorted list.
         * Returns 0 if 1 is missing.
         */
        private int findConsecutiveSequenceLength(List<Integer> sortedList, int limit) {
            int candidate = 1;
            for (int val : sortedList) {
                if (val == candidate) {
                    candidate++;
                } else if (val > candidate) {
                    // Since the list is sorted, we won't find 'candidate' later
                    break;
                }
                // Cap the search at the defined limit
                if (candidate > limit) {
                    break;
                }
            }
            // candidate - 1 gives the count of consecutive numbers found starting from 1
            return candidate - 1;
        }
    }

    /**
     * Fast input reader for competitive programming / large inputs.
     */
    static class InputReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) {
                        throw new RuntimeException("Unexpected end of input");
                    }
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading from input stream", e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashSet;
import java.util.List;
import java.util.Scanner;
import java.util.Set;

public class NumberPatternSolver {

    /**
     * Represents a collection of 6 integers used to match digits.
     */
    public static class DigitSet {
        private final Set<Integer> numbers;

        public DigitSet(int[] numbers) {
            this.numbers = new HashSet<>(Arrays.asList(numbers));
        }

        public boolean contains(int num) {
            return numbers.contains(num);
        }
    }

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            if (!scanner.hasNextInt()) {
                return;
            }
            int n = scanner.nextInt();
            List<DigitSet> sets = new ArrayList<>(n);

            for (int i = 0; i < n; i++) {
                int[] numbers = new int[6];
                for (int j = 0; j < 6; j++) {
                    if (scanner.hasNextInt()) {
                        numbers[j] = scanner.nextInt();
                    }
                }
                sets.add(new DigitSet(numbers));
            }

            int maxConsecutive = findMaxConsecutiveNumber(sets);
            System.out.println(maxConsecutive);
        }
    }

    /**
     * Finds the largest consecutive integer starting from 1 that can be formed.
     */
    private static int findMaxConsecutiveNumber(List<DigitSet> sets) {
        int k = 1;
        while (canBeFormed(k, sets)) {
            k++;
        }
        return k - 1;
    }

    /**
     * Determines if a number can be formed using distinct DigitSets.
     * Each digit of the number must be contained in a separate set.
     */
    private static boolean canBeFormed(int number, List<DigitSet> sets) {
        // Original logic caps valid numbers at 3 digits (1-999)
        if (number < 1 || number >= 1000) {
            return false;
        }

        List<Integer> digits = extractDigits(number);
        if (digits.size() > sets.size()) {
            return false;
        }

        boolean[] usedSets = new boolean[sets.size()];
        return backtrack(digits, 0, sets, usedSets, 0);
    }

    /**
     * Efficiently extracts digits from a number without string conversion.
     */
    private static List<Integer> extractDigits(int number) {
        List<Integer> digits = new ArrayList<>();
        if (number == 0) {
            digits.add(0);
            return digits;
        }
        while (number > 0) {
            digits.add(number % 10);
            number /= 10;
        }
        Collections.reverse(digits);
        return digits;
    }

    /**
     * Backtracking helper to assign each digit to a distinct set.
     * Replaces hardcoded permutation logic with a scalable, generic approach.
     */
    private static boolean backtrack(List<Integer> digits, int digitIndex,
                                     List<DigitSet> sets, boolean[] usedSets, int setIndex) {
        if (digitIndex == digits.size()) {
            return true;
        }

        int targetDigit = digits.get(digitIndex);
        for (int i = setIndex; i < sets.size(); i++) {
            if (!usedSets[i] && sets.get(i).contains(targetDigit)) {
                usedSets[i] = true;
                if (backtrack(digits, digitIndex + 1, sets, usedSets, i + 1)) {
                    return true;
                }
                usedSets[i] = false;
            }
        }
        return false;
    }
}

import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;
import java.util.stream.IntStream;

public class CubeNumberFinder {

    private static final int MAX_NUMBER = 999;
    private static final int FACES_PER_CUBE = 6;

    public static void main(String[] args) {
        // Use try-with-resources to automatically close the scanner
        try (Scanner scanner = new Scanner(System.in)) {
            if (!scanner.hasNextInt()) {
                return;
            }

            int n = scanner.nextInt();
            int[][] cubes = new int[n][FACES_PER_CUBE];
            boolean hasOneFace = false;

            // Read cube faces
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < FACES_PER_CUBE; j++) {
                    if (scanner.hasNextInt()) {
                        cubes[i][j] = scanner.nextInt();
                        if (cubes[i][j] == 1) {
                            hasOneFace = true;
                        }
                    }
                }
            }

            // Early exit if no cube contains a '1'
            if (!hasOneFace) {
                System.out.println(0);
                return;
            }

            int maxValidNumber = 0;
            // Pre-generate all valid cube index permutations
            List<int[]> permutations = generatePermutations(n);

            // Check numbers from 1 to 999
            for (int num = 1; num <= MAX_NUMBER; num++) {
                List<Integer> digits = extractDigits(num);

                // A number with more digits than cubes cannot be formed
                if (digits.size() > n) {
                    continue;
                }

                if (isValidNumber(digits, cubes, permutations)) {
                    maxValidNumber = num;
                }
            }

            System.out.println(maxValidNumber);
        }
    }

    /**
     * Extracts digits from a number in reverse order (least significant first).
     * Matches the original logic's digit extraction behavior.
     */
    private static List<Integer> extractDigits(int number) {
        List<Integer> digits = new ArrayList<>();
        while (number > 0) {
            digits.add(number % 10);
            number /= 10;
        }
        return digits;
    }

    /**
     * Generates all permutations of indices [0, n-1] using backtracking.
     * Replaces the original hardcoded permutation logic for n=1,2,3.
     */
    private static List<int[]> generatePermutations(int n) {
        List<int[]> permutations = new ArrayList<>();
        int[] indices = IntStream.range(0, n).toArray();
        permute(indices, 0, permutations);
        return permutations;
    }

    private static void permute(int[] array, int k, List<int[]> permutations) {
        if (k == array.length) {
            permutations.add(array.clone());
        } else {
            for (int i = k; i < array.length; i++) {
                swap(array, i, k);
                permute(array, k + 1, permutations);
                swap(array, i, k);
            }
        }
    }

    private static void swap(int[] array, int i, int j) {
        int temp = array[i];
        array[i] = array[j];
        array[j] = temp;
    }

    /**
     * Checks if the given digits can be matched to distinct cubes via any permutation.
     */
    private static boolean isValidNumber(List<Integer> digits, int[][] cubes, List<int[]> permutations) {
        for (int[] permutation : permutations) {
            boolean allMatch = true;
            for (int i = 0; i < digits.size(); i++) {
                int cubeIndex = permutation[i];
                int targetDigit = digits.get(i);
                boolean found = false;

                // Check if the selected cube has the required digit on any face
                for (int face : cubes[cubeIndex]) {
                    if (face == targetDigit) {
                        found = true;
                        break;
                    }
                }

                if (!found) {
                    allMatch = false;
                    break;
                }
            }

            // If a valid assignment is found, the number is valid
            if (allMatch) {
                return true;
            }
        }
        return false;
    }
}

import java.io.*;
import java.util.StringTokenizer;

/**
 * Main class to find the largest integer i (1 <= i < 1000) such that
 * each digit of i can be uniquely matched to a distinct row in the input array
 * that contains that digit. Uses backtracking for bipartite matching.
 */
public class Main {
    private static final int MAX_ITERATION = 1000;
    private static final int ARRAY_COLUMNS = 6;

    public static void main(String[] args) throws IOException {
        // Use try-with-resources to ensure proper cleanup of the scanner
        try (MyScanner scanner = new MyScanner()) {
            int n = scanner.nextInt();
            int[][] arr = scanner.next2Ints(n, ARRAY_COLUMNS);

            int result = findLargestValidNumber(n, arr);
            System.out.println(result);
        }
    }

    /**
     * Iterates from 1 up to MAX_ITERATION to find the largest number
     * where all its digits can be assigned to distinct rows in arr.
     */
    private static int findLargestValidNumber(int n, int[][] arr) {
        for (int i = 1; i < MAX_ITERATION; i++) {
            if (!canAssignDigitsToRows(n, arr, i)) {
                return i - 1;
            }
        }
        return MAX_ITERATION - 1;
    }

    /**
     * Constructs a boolean matrix representing which rows contain each digit
     * of the given number, then checks if a valid assignment exists via backtracking.
     */
    private static boolean canAssignDigitsToRows(int n, int[][] arr, int number) {
        int temp = number;
        int digitCount = 0;
        while (temp > 0) {
            temp /= 10;
            digitCount++;
        }
        // Fallback for 0, though the loop starts at 1
        if (digitCount == 0) digitCount = 1;

        boolean[][] digitRowMap = new boolean[n][digitCount];

        temp = number;
        int position = 0;
        while (temp > 0) {
            int digit = temp % 10;
            temp /= 10;
            for (int row = 0; row < n; row++) {
                digitRowMap[row][position] = arrayContains(arr[row], digit);
            }
            position++;
        }

        return backtrackMatch(digitRowMap, 0, new boolean[n], digitCount);
    }

    /**
     * Checks if a target value exists in the given array.
     */
    private static boolean arrayContains(int[] arr, int target) {
        for (int val : arr) {
            if (val == target) {
                return true;
            }
        }
        return false;
    }

    /**
     * Backtracking algorithm to determine if each digit position can be
     * uniquely assigned to a distinct row that contains it.
     */
    private static boolean backtrackMatch(boolean[][] digitRowMap, int pos, boolean[] rowUsed, int totalPositions) {
        if (pos == totalPositions) {
            return true;
        }

        for (int row = 0; row < digitRowMap.length; row++) {
            if (digitRowMap[row][pos] && !rowUsed[row]) {
                rowUsed[row] = true;
                if (backtrackMatch(digitRowMap, pos + 1, rowUsed, totalPositions)) {
                    return true;
                }
                rowUsed[row] = false; // Backtrack
            }
        }
        return false;
    }
}

/**
 * High-performance input scanner for competitive programming and fast I/O.
 */
class MyScanner implements AutoCloseable {
    private final BufferedReader br;
    private StringTokenizer st;
    private String lastLine;

    public MyScanner() {
        this.br = new BufferedReader(new InputStreamReader(System.in));
    }

    public MyScanner(String path) throws IOException {
        this.br = new BufferedReader(new FileReader(path));
    }

    public MyScanner(String path, String decoder) throws IOException {
        this.br = new BufferedReader(new InputStreamReader(new FileInputStream(path), decoder));
    }

    @Override
    public void close() throws IOException {
        br.close();
    }

    public String next() throws IOException {
        while (st == null || !st.hasMoreTokens()) {
            String line = br.readLine();
            if (line == null) {
                return null;
            }
            st = new StringTokenizer(line);
        }
        return st.nextToken();
    }

    public String next(String delim) throws IOException {
        while (st == null || !st.hasMoreTokens()) {
            String line = br.readLine();
            if (line == null) {
                return null;
            }
            st = new StringTokenizer(line, delim);
        }
        return st.nextToken(delim);
    }

    public String nextLine() throws IOException {
        st = null;
        return (lastLine == null) ? br.readLine() : lastLine;
    }

    public boolean hasNext() {
        if (st != null && st.hasMoreTokens()) {
            return true;
        }
        try {
            while (st == null || !st.hasMoreTokens()) {
                lastLine = br.readLine();
                if (lastLine == null) {
                    return false;
                }
                st = new StringTokenizer(lastLine);
            }
        } catch (IOException e) {
            return false;
        }
        return true;
    }

    public String[] nextStrings(int n) throws IOException {
        String[] arr = new String[n];
        for (int i = 0; i < n; i++) {
            arr[i] = next();
        }
        return arr;
    }

    public String[] nextLines(int n) throws IOException {
        String[] arr = new String[n];
        for (int i = 0; i < n; i++) {
            arr[i] = nextLine();
        }
        return arr;
    }

    public int nextInt() throws IOException {
        String s = next();
        return (s == null) ? 0 : Integer.parseInt(s);
    }

    public int[] nextInts(int n) throws IOException {
        int[] arr = new int[n];
        for (int i = 0; i < n; i++) {
            arr[i] = nextInt();
        }
        return arr;
    }

    public Integer[] nextIntegers(int n) throws IOException {
        Integer[] arr = new Integer[n];
        for (int i = 0; i < n; i++) {
            arr[i] = nextInt();
        }
        return arr;
    }

    public int[][] next2Ints(int n, int m) throws IOException {
        int[][] arr = new int[n][m];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                arr[i][j] = nextInt();
            }
        }
        return arr;
    }

    public long nextLong() throws IOException {
        String s = next();
        return (s == null) ? 0L : Long.parseLong(s);
    }

    public long[] nextLongs(int n) throws IOException {
        long[] arr = new long[n];
        for (int i = 0; i < n; i++) {
            arr[i] = nextLong();
        }
        return arr;
    }

    public long[][] next2Longs(int n, int m) throws IOException {
        long[][] arr = new long[n][m];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                arr[i][j] = nextLong();
            }
        }
        return arr;
    }

    public double nextDouble() throws IOException {
        String s = next();
        if (s == null) return 0.0;
        return Double.parseDouble(s.replace(',', '.'));
    }

    public double[] nextDoubles(int size) throws IOException {
        double[] arr = new double[size];
        for (int i = 0; i < size; i++) {
            arr[i] = nextDouble();
        }
        return arr;
    }

    public double[][] next2Doubles(int n, int m) throws IOException {
        double[][] arr = new double[n][m];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                arr[i][j] = nextDouble();
            }
        }
        return arr;
    }

    public boolean nextBool() throws IOException {
        String s = next();
        if (s == null) return false;
        if (s.equalsIgnoreCase("true") || s.equals("1")) {
            return true;
        }
        if (s.equalsIgnoreCase("false") || s.equals("0")) {
            return false;
        }
        throw new IOException("Boolean expected, String found: " + s);
    }
}

import java.util.Scanner;
import java.util.HashSet;
import java.util.Set;

public class Solution {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        // Ensure there is input to read
        if (!scanner.hasNextInt()) {
            scanner.close();
            return;
        }

        int n = scanner.nextInt();

        // Store digits in a 2D array. 
        // groups[0] corresponds to 'a', [1] to 'b', [2] to 'c'.
        // The problem specifies arrays of size 6.
        int[][] groups = new int[3][6];

        // Read input based on N.
        // N=1: Reads 6 integers into groups[0]
        // N=2: Reads 12 integers into groups[0] and groups[1]
        // N=3: Reads 18 integers into groups[0], groups[1], and groups[2]
        for (int g = 0; g < n; g++) {
            for (int k = 0; k < 6; k++) {
                if (scanner.hasNextInt()) {
                    groups[g][k] = scanner.nextInt();
                }
            }
        }

        Set<Integer> set = new HashSet<>();

        // 1. Add 1-digit numbers from available groups
        // Non-zero digits are added to the set.
        for (int g = 0; g < n; g++) {
            for (int digit : groups[g]) {
                if (digit != 0) {
                    set.add(digit);
                }
            }
        }

        // 2. Special case for N=1: Check for missing number and exit early.
        // If N=1, we only consider 1-digit numbers.
        if (n == 1) {
            for (int i = 1; i <= 999; i++) {
                if (!set.contains(i)) {
                    System.out.println(i - 1);
                    return;
                }
            }
        }

        // 3. Add 2-digit numbers (if N >= 2)
        // Formed by combining a digit from group g1 and a digit from group g2.
        // g1 and g2 must be distinct groups (e.g., a with b, but not a with a).
        // The leading digit (from g1) cannot be 0.
        if (n >= 2) {
            for (int g1 = 0; g1 < n; g1++) {
                for (int g2 = 0; g2 < n; g2++) {
                    if (g1 == g2) continue; // Must be distinct groups

                    for (int d1 : groups[g1]) {
                        if (d1 == 0) continue; // Leading digit cannot be 0

                        for (int d2 : groups[g2]) {
                            set.add(d1 * 10 + d2);
                        }
                    }
                }
            }
        }

        // 4. Add 3-digit numbers (if N == 3)
        // Formed by permutations of 3 distinct groups.
        // The leading digit (from the first group in the permutation) cannot be 0.
        if (n == 3) {
            for (int g1 = 0; g1 < 3; g1++) {
                for (int g2 = 0; g2 < 3; g2++) {
                    for (int g3 = 0; g3 < 3; g3++) {
                        // Check if groups are distinct (permutation requirement)
                        if (g1 == g2 || g1 == g3 || g2 == g3) continue;

                        for (int d1 : groups[g1]) {
                            if (d1 == 0) continue; // Leading digit cannot be 0

                            for (int d2 : groups[g2]) {
                                for (int d3 : groups[g3]) {
                                    set.add(d1 * 100 + d2 * 10 + d3);
                                }
                            }
                        }
                    }
                }
            }
        }

        // 5. Final scan for missing number
        // If N > 1, we check 1..999 after populating the set with 1, 2, and 3-digit numbers.
        for (int i = 1; i <= 999; i++) {
            if (!set.contains(i)) {
                System.out.println(i - 1);
                return;
            }
        }

        scanner.close();
    }
}

