/**
 * Solution for a competitive programming problem.
 * Reads an n x 6 matrix of digits, forms all possible 1-, 2-, and 3-digit 
 * numbers by concatenating digits from different rows, and finds the 
 * largest consecutive integer starting from 1 that can be formed.
 */
public class Codeforces {

    private static final int MAX_POSSIBLE_VALUE = 10000;

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner();
        PrintWriter out = new PrintWriter(System.out);

        try {
            // Standard CP format: first line contains number of test cases
            int t = scanner.nextInt();
            while (t-- > 0) {
                solve(scanner, out);
            }
        } catch (Exception e) {
            // Gracefully handle malformed input or unexpected EOF
        } finally {
            out.flush();
        }
    }

    private static void solve(FastScanner scanner, PrintWriter out) {
        int n = scanner.nextInt();
        int[][] digits = new int[n][6];

        // Read the n x 6 matrix
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < 6; j++) {
                digits[i][j] = scanner.nextInt();
            }
        }

        // Boolean array to mark which numbers can be formed
        boolean[] present = new boolean[MAX_POSSIBLE_VALUE];

        // Mark all valid 1-, 2-, and 3-digit combinations
        markSingleDigitNumbers(digits, present);
        markTwoDigitNumbers(digits, present);
        markThreeDigitNumbers(digits, present);

        // Find the smallest positive integer that is NOT present
        int smallestMissing = 1;
        while (smallestMissing < MAX_POSSIBLE_VALUE && present[smallestMissing]) {
            smallestMissing++;
        }

        // Output the largest consecutive integer starting from 1
        out.println(smallestMissing - 1);
    }

    /**
     * Marks all single-digit numbers found in the matrix.
     */
    private static void markSingleDigitNumbers(int[][] digits, boolean[] present) {
        for (int[] row : digits) {
            for (int val : row) {
                if (isValid(val, present)) {
                    present[val] = true;
                }
            }
        }
    }

    /**
     * Marks all valid 2-digit numbers formed by concatenating digits 
     * from two different rows.
     */
    private static void markTwoDigitNumbers(int[][] digits, boolean[] present) {
        int n = digits.length;
        for (int i = 0; i < n; i++) {
            for (int d1 : digits[i]) {
                for (int j = 0; j < n; j++) {
                    if (i == j) continue;
                    for (int d2 : digits[j]) {
                        int num = d1 * 10 + d2;
                        if (isValid(num, present)) {
                            present[num] = true;
                        }
                    }
                }
            }
        }
    }

    /**
     * Marks all valid 3-digit numbers formed by concatenating digits 
     * from three distinct rows.
     */
    private static void markThreeDigitNumbers(int[][] digits, boolean[] present) {
        int n = digits.length;
        for (int i = 0; i < n; i++) {
            for (int d1 : digits[i]) {
                for (int j = 0; j < n; j++) {
                    if (i == j) continue;
                    for (int d2 : digits[j]) {
                        for (int k = 0; k < n; k++) {
                            if (i == k || j == k) continue;
                            for (int d3 : digits[k]) {
                                int num = d1 * 100 + d2 * 10 + d3;
                                if (isValid(num, present)) {
                                    present[num] = true;
                                }
                            }
                        }
                    }
                }
            }
        }
    }

    /**
     * Checks if a number is within valid bounds for the present array.
     */
    private static boolean isValid(int num, boolean[] present) {
        return num >= 0 && num < present.length;
    }

    /**
     * FastScanner class for efficient input reading.
     * Replaces the original buggy custom reader with a standard, 
     * maintainable implementation.
     */
    static class FastScanner {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastScanner() {
            reader = new BufferedReader(new InputStreamReader(System.in));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            String token = next();
            if (token == null) {
                throw new RuntimeException("Unexpected end of input");
            }
            return Integer.parseInt(token);
        }
    }
}

import java.io.OutputStream;
import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.io.DataInputStream;
import java.io.FileInputStream;
import java.io.FileNotFoundException;

public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        FastIO in = new FastIO(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        TaskB solver = new TaskB();
        solver.solve(1, in, out);
        out.close();
    }

    static class TaskB {
        public void solve(int testNumber, FastIO in, PrintWriter out) {
            int n = in.nextInt();
            // Refactored: Use dynamic size based on n, ensuring minimum size of 3 for logic checks.
            // Original code used a hardcoded size of 3 which could cause ArrayIndexOutOfBoundsException
            // if n > 3, or crash in check loop if n < 3.
            boolean[][] digitPresence = new boolean[10][Math.max(3, n)];

            for (int i = 0; i < n; i++) {
                for (int j = 0; j < 6; j++) {
                    int val = in.nextInt();
                    // Safety check to ensure digit is within bounds [0, 9]
                    if (val >= 0 && val < 10) {
                        digitPresence[val][i] = true;
                    }
                }
            }

            for (int i = 1; i < 100; i++) {
                if (i < 10) {
                    // Check if digit i is missing from the first 3 inputs
                    if (!digitPresence[i][0] && !digitPresence[i][1] && !digitPresence[i][2]) {
                        out.println(i - 1);
                        return;
                    }
                } else {
                    int unitsDigit = i % 10;
                    int tensDigit = i / 10;

                    // Logic preserved from original code
                    if ((!digitPresence[unitsDigit][0] || !digitPresence[tensDigit][1]) &&
                        (!digitPresence[unitsDigit][0] || !digitPresence[tensDigit][2]) &&
                        (!digitPresence[unitsDigit][1] || !digitPresence[tensDigit][0]) &&
                        (!digitPresence[unitsDigit][1] || !digitPresence[tensDigit][2]) &&
                        (!digitPresence[unitsDigit][2] || !digitPresence[tensDigit][1]) &&
                        (!digitPresence[unitsDigit][2] || !digitPresence[tensDigit][0])) {
                        out.println(i - 1);
                        return;
                    }
                }
            }
            out.println(99);
        }
    }

    static class FastIO {
        private static final int BUFFER_SIZE = 1 << 16;
        private InputStream din;
        private byte[] buffer;
        private int bufferPointer;
        private int bytesRead;

        public FastIO() {
            buffer = new byte[BUFFER_SIZE];
            bufferPointer = bytesRead = 0;
        }

        public FastIO(InputStream inputStream) {
            this();
            din = new DataInputStream(inputStream);
        }

        public int nextInt() {
            int ret = 0;
            try {
                byte c = read();
                while (c <= ' ') {
                    c = read();
                }
                boolean neg = (c == '-');
                if (neg) {
                    c = read();
                }
                do {
                    ret = ret * 10 + c - '0';
                } while ((c = read()) >= '0' && c <= '9');

                if (neg) {
                    return -ret;
                }
            } catch (Exception e) {
                e.printStackTrace();
            }
            return ret;
        }

        private void fillBuffer() {
            try {
                bytesRead = din.read(buffer, bufferPointer = 0, BUFFER_SIZE);
                if (bytesRead == -1) {
                    buffer[0] = -1;
                }
            } catch (IOException e) {
                e.printStackTrace();
            }
        }

        private byte read() {
            if (bytesRead == -1) {
                return -1;
            }
            if (bufferPointer == bytesRead) {
                fillBuffer();
            }
            return buffer[bufferPointer++];
        }
    }
}

