/**
 * Encapsulates the core business logic for solving the cubes problem.
 * Separated from I/O and main execution for better testability and maintainability.
 */
class CubesSolver {
    private static final int MAX_NUMBER = 1000;
    private static final int FACES_PER_CUBE = 6;

    public void solve(FastScanner in, PrintWriter out) {
        int n = in.nextInt();
        int[][] cubes = new int[n][FACES_PER_CUBE];

        // Read cube faces
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < FACES_PER_CUBE; j++) {
                cubes[i][j] = in.nextInt();
            }
        }

        // Track which numbers (1-999) can be formed
        boolean[] seen = new boolean[MAX_NUMBER];
        generateAllNumbers(cubes, seen);

        // Find the smallest positive integer that cannot be formed
        for (int i = 1; i < MAX_NUMBER; i++) {
            if (!seen[i]) {
                out.println(i);
                break;
            }
        }
    }

    /**
     * Generates all possible numbers of length 1 to n using permutations of cubes.
     */
    private void generateAllNumbers(int[][] cubes, boolean[] seen) {
        int n = cubes.length;
        int[] currentDigits = new int[n];
        boolean[] usedCubes = new boolean[n];

        // Iterate through all possible number lengths (1-digit, 2-digit, up to n-digit)
        for (int length = 1; length <= n; length++) {
            backtrack(cubes, length, currentDigits, usedCubes, 0, seen);
        }
    }

    /**
     * Recursive backtracking to generate permutations of cubes and assign faces.
     */
    private void backtrack(int[][] cubes, int targetLength, int[] currentDigits, 
                           boolean[] usedCubes, int idx, boolean[] seen) {
        if (idx == targetLength) {
            int number = 0;
            for (int digit : currentDigits) {
                number = number * 10 + digit;
            }
            seen[number] = true;
            return;
        }

        // Try each unused cube for the current position
        for (int cubeIndex = 0; cubeIndex < cubes.length; cubeIndex++) {
            if (!usedCubes[cubeIndex]) {
                usedCubes[cubeIndex] = true;

                // Try each face on the selected cube
                for (int face : cubes[cubeIndex]) {
                    currentDigits[idx] = face;
                    backtrack(cubes, targetLength, currentDigits, usedCubes, idx + 1, seen);
                }

                usedCubes[cubeIndex] = false; // Backtrack
            }
        }
    }
}

