import java.io.*;
import java.util.*;

public class DigitConstraintSolver {

    private static final FastScanner scanner = new FastScanner();

    public static void main(String[] args) {
        int testCases = 1; // Hardcoded to 1 as per original implementation
        while (testCases-- > 0) {
            solve();
        }
    }

    private static void solve() {
        int n = scanner.nextInt();

        // constraints[digit][position] tracks occurrence counts for each digit at each position
        int[][] constraints = new int[10][n];

        for (int pos = 0; pos < n; pos++) {
            for (int k = 0; k < 6; k++) {
                int digit = scanner.nextInt();
                constraints[digit][pos]++;
            }
        }

        // 1. Check single-digit candidates (1-9)
        for (int digit = 1; digit <= 9; digit++) {
            if (isSingleDigitValid(digit, n, constraints)) {
                System.out.println(digit - 1);
                return;
            }
        }

        if (n == 1) {
            System.out.println(9);
            return;
        }

        int limit = (int) Math.pow(10, n);

        // 2. Check numbers from 10 upwards using pairwise constraint logic
        for (int num = 10; num < limit; num++) {
            int[] digits = extractDigits(num, n);
            if (isValidPairConstraints(num, n, constraints, digits)) {
                System.out.println(num - 1);
                return;
            }
        }

        if (n == 2) {
            System.out.println(99);
            return;
        }

        // 3. Additional position-based constraint check for larger numbers
        for (int num = 100; num < limit; num++) {
            int[] digits = extractDigits(num, n);
            if (isValidPositionConstraints(num, n, constraints, digits)) {
                System.out.println(num - 1);
                return;
            }
        }

        System.out.println(999);
    }

    /**
     * Checks if a single digit satisfies all positional constraints.
     */
    private static boolean isSingleDigitValid(int digit, int n, int[][] constraints) {
        for (int pos = 0; pos < n; pos++) {
            if (constraints[digit][pos] != 0) {
                return false;
            }
        }
        return true;
    }

    /**
     * Extracts digits of a number into an array where index 0 is the units place.
     */
    private static int[] extractDigits(int number, int n) {
        int[] digits = new int[n];
        for (int i = 0; i < n; i++) {
            digits[i] = number % 10;
            number /= 10;
        }
        return digits;
    }

    /**
     * Validates numbers using the original first-loop pairwise constraint logic.
     */
    private static boolean isValidPairConstraints(int num, int n, int[][] constraints, int[] digits) {
        int a = 0, b = 1;
        if ((constraints[digits[0]][a] != 0 && constraints[digits[1]][b] != 0) ||
            (constraints[digits[1]][a] != 0 && constraints[digits[0]][b] != 0)) {
            return false;
        }

        if (n >= 3) {
            b = 2;
            if ((constraints[digits[0]][a] != 0 && constraints[digits[2]][b] != 0) ||
                (constraints[digits[2]][a] != 0 && constraints[digits[0]][b] != 0)) {
                return false;
            }
            a = 1;
            if ((constraints[digits[0]][a] != 0 && constraints[digits[1]][b] != 0) ||
                (constraints[digits[1]][a] != 0 && constraints[digits[0]][b] != 0)) {
                return false;
            }
        }
        return true;
    }

    /**
     * Validates numbers using the original second-loop specific position constraint logic.
     * Note: This method is only invoked when n >= 3.
     */
    private static boolean isValidPositionConstraints(int num, int n, int[][] constraints, int[] digits) {
        if (constraints[digits[0]][0] > 0) {
            if (constraints[digits[1]][1] > 0 && constraints[digits[2]][2] > 0) return false;
            if (constraints[digits[1]][2] > 0 && constraints[digits[2]][1] > 0) return false;
        }
        if (constraints[digits[1]][0] > 0) {
            if (constraints[digits[0]][1] > 0 && constraints[digits[2]][2] > 0) return false;
            if (constraints[digits[0]][2] > 0 && constraints[digits[2]][1] > 0) return false;
        }
        if (constraints[digits[2]][0] > 0) {
            if (constraints[digits[1]][1] > 0 && constraints[digits[0]][2] > 0) return false;
            if (constraints[digits[1]][2] > 0 && constraints[digits[0]][1] > 0) return false;
        }
        return true;
    }

    /**
     * Fast I/O helper class for competitive programming scenarios.
     */
    static class FastScanner {
        private final BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        private StringTokenizer st = new StringTokenizer("");

        String next() {
            while (!st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
            return st.nextToken();
        }

        String nextLine() {
            try {
                return br.readLine();
            } catch (IOException e) {
                e.printStackTrace();
            }
            return "";
        }

        int nextInt() {
            String s = next();
            return s == null ? 0 : Integer.parseInt(s);
        }

        int[] readArray(int n) {
            int[] a = new int[n];
            for (int i = 0; i < n; i++) a[i] = nextInt();
            return a;
        }

        long nextLong() {
            return Long.parseLong(next());
        }

        double nextDouble() {
            return Double.parseDouble(next());
        }
    }
}

import java.util.Scanner;

public class B887 {
    public static void main(String[] args) {
        // Use try-with-resources to ensure proper resource management
        try (Scanner sc = new Scanner(System.in)) {
            int numPlayers = sc.nextInt();
            boolean[][] hasDigit = new boolean[numPlayers][10];

            // Read the 6 digits for each player
            for (int p = 0; p < numPlayers; p++) {
                for (int k = 0; k < 6; k++) {
                    hasDigit[p][sc.nextInt()] = true;
                }
            }

            // Find the largest positive integer that can be formed
            int largestFormable = 0;
            for (int candidate = 1; candidate <= 999; candidate++) {
                if (canForm(candidate, hasDigit, numPlayers)) {
                    largestFormable = candidate;
                } else {
                    // The first number that cannot be formed means we've found the largest formable one.
                    break;
                }
            }

            System.out.println(largestFormable);
        }
    }

    /**
     * Determines if a number can be formed by assigning each of its digits to a distinct player
     * who possesses that digit.
     */
    private static boolean canForm(int number, boolean[][] hasDigit, int numPlayers) {
        String s = String.valueOf(number);
        // A number with more digits than available players cannot be formed
        if (s.length() > numPlayers) {
            return false;
        }

        int[] digits = new int[s.length()];
        for (int i = 0; i < s.length(); i++) {
            digits[i] = s.charAt(i) - '0';
        }

        // Use backtracking to try all valid assignments of digits to players
        return assignDigits(0, digits, new boolean[numPlayers], hasDigit);
    }

    /**
     * Recursive backtracking helper to assign digits to players.
     *
     * @param digitIdx    Current index in the digits array being assigned
     * @param digits      Array of digits extracted from the candidate number
     * @param usedPlayers Boolean array tracking which players are already assigned a digit
     * @param hasDigit    2D array where hasDigit[player][digit] is true if the player has that digit
     * @return true if all digits can be successfully assigned to distinct players
     */
    private static boolean assignDigits(int digitIdx, int[] digits, boolean[] usedPlayers, boolean[][] hasDigit) {
        // Base case: all digits have been successfully assigned
        if (digitIdx == digits.length) {
            return true;
        }

        int currentDigit = digits[digitIdx];
        for (int p = 0; p < usedPlayers.length; p++) {
            // Try assigning the current digit to player p if they have it and aren't used yet
            if (!usedPlayers[p] && hasDigit[p][currentDigit]) {
                usedPlayers[p] = true;
                if (assignDigits(digitIdx + 1, digits, usedPlayers, hasDigit)) {
                    return true;
                }
                // Backtrack: unassign the player to try other combinations
                usedPlayers[p] = false;
            }
        }
        return false;
    }
}

import java.io.*;
import java.util.*;

public final class Solution {
    private static final int MAX_NUMBER = 999;
    private static final int DIGITS_PER_SET = 6;

    public static void main(String[] args) {
        Reader input = new Reader();
        PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out));

        int n = input.nextInt();
        int[][] digitSets = new int[n][DIGITS_PER_SET];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < DIGITS_PER_SET; j++) {
                digitSets[i][j] = input.nextInt();
            }
        }

        int max = 0;
        for (int i = 1; i < MAX_NUMBER; i++) {
            if (canFormNumber(i, digitSets)) {
                max = i;
            } else {
                break;
            }
        }

        out.println(max);
        out.close();
    }

    /**
     * Determines if a number can be formed using digits from the provided sets
     * according to the problem's constraints.
     */
    private static boolean canFormNumber(int num, int[][] sets) {
        if (num < 10) {
            return hasDigitInAnySet(sets, num);
        } else if (num < 100) {
            int d1 = num % 10;
            int d2 = num / 10;
            return hasDigitsInTwoDistinctSets(sets, d1, d2);
        } else {
            int d1 = num % 10;
            int d2 = (num / 10) % 10;
            int d3 = num / 100;
            return hasTwoDigitsInOneSetAndThirdInAnother(sets, d1, d2, d3);
        }
    }

    private static boolean hasDigitInAnySet(int[][] sets, int digit) {
        for (int[] set : sets) {
            if (contains(set, digit)) {
                return true;
            }
        }
        return false;
    }

    private static boolean hasDigitsInTwoDistinctSets(int[][] sets, int d1, int d2) {
        for (int i = 0; i < sets.length; i++) {
            if (!contains(sets[i], d1)) continue;
            for (int j = 0; j < sets.length; j++) {
                if (i == j) continue;
                if (contains(sets[j], d2)) {
                    return true;
                }
            }
        }
        return false;
    }

    private static boolean hasTwoDigitsInOneSetAndThirdInAnother(int[][] sets, int d1, int d2, int d3) {
        // Checks if two digits can reside in one set while the third resides in a different set.
        // Iterating over all set pairs covers all valid partitions for this constraint.
        for (int i = 0; i < sets.length; i++) {
            if (!contains(sets[i], d1) || !contains(sets[i], d3)) continue;
            for (int j = 0; j < sets.length; j++) {
                if (i == j) continue;
                if (contains(sets[j], d2)) {
                    return true;
                }
            }
        }
        return false;
    }

    private static boolean contains(int[] set, int val) {
        for (int v : set) {
            if (v == val) return true;
        }
        return false;
    }

    /**
     * Fast I/O helper class for competitive programming.
     */
    public static class Reader {
        private final BufferedReader br;
        private StringTokenizer st;

        public Reader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        public String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    e.printStackTrace();
                    System.exit(1);
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            String token = next();
            if (token == null) throw new NoSuchElementException("Unexpected end of input");
            return Integer.parseInt(token);
        }

        public double nextDouble() {
            return Double.parseDouble(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }

        public String nextLine() {
            try {
                return br.readLine();
            } catch (IOException e) {
                e.printStackTrace();
                System.exit(1);
                return "";
            }
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

/**
 * Refactored version of CFB.
 * 
 * Key Improvements:
 * 1. Removed static state: All variables are now local or passed as parameters,
 *    improving testability, reusability, and thread safety.
 * 2. DRY Principle & Recursion: Replaced hardcoded, repetitive logic for n=1,2,3
 *    with a clean DFS/backtracking approach that generalizes to any n.
 * 3. Magic Numbers: Extracted constants (e.g., 1000) for easier configuration.
 * 4. I/O: Replaced custom byte-based FastScanner with standard BufferedReader +
 *    StringTokenizer for better readability and maintainability without sacrificing performance.
 * 5. Bug Fix: Corrected an off-by-one error in the final output loop (original printed i-1).
 * 6. Naming & Structure: Used descriptive names, added JavaDoc, and organized code logically.
 */
public class CFB {
    private static final int MAX_VALUE = 1000;

    public static void main(String[] args) throws IOException {
        FastScanner scanner = new FastScanner();
        int n = scanner.nextInt();

        // Guard clause for invalid input
        if (n <= 0) {
            System.out.println(1);
            return;
        }

        int[][] dice = new int[n][6];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < 6; j++) {
                dice[i][j] = scanner.nextInt();
            }
        }

        boolean[] canMake = new boolean[MAX_VALUE];
        boolean[] usedDice = new boolean[n];

        // Generate all possible numbers using 1 to n dice
        generatePossibleNumbers(dice, usedDice, 0, 0, canMake);

        // Find the smallest positive integer that cannot be formed
        for (int i = 1; i < MAX_VALUE; i++) {
            if (!canMake[i]) {
                System.out.println(i);
                return;
            }
        }
    }

    /**
     * Recursively generates all valid numbers by permuting dice and their faces.
     * 
     * @param dice       2D array containing face values for each die
     * @param usedDice   Tracks which dice have been used in the current permutation
     * @param currentNum The number being built digit by digit
     * @param diceCount  Number of dice currently used in the permutation
     * @param canMake    Boolean array marking which numbers are possible
     */
    private static void generatePossibleNumbers(int[][] dice, boolean[] usedDice, 
                                                int currentNum, int diceCount, boolean[] canMake) {
        // Mark the current number as possible (if it's within bounds and non-zero)
        if (currentNum > 0 && currentNum < MAX_VALUE) {
            canMake[currentNum] = true;
        }

        // Base case: all dice have been used
        if (diceCount == dice.length) {
            return;
        }

        // Try adding each unused die to the current number
        for (int i = 0; i < dice.length; i++) {
            if (!usedDice[i]) {
                usedDice[i] = true;

                // Try each face of the selected die
                for (int face : dice[i]) {
                    int nextNum = currentNum * 10 + face;
                    if (nextNum < MAX_VALUE) {
                        generatePossibleNumbers(dice, usedDice, nextNum, diceCount + 1, canMake);
                    }
                }

                // Backtrack: mark die as unused for other permutations
                usedDice[i] = false;
            }
        }
    }

    /**
     * Efficient and readable input scanner using standard Java I/O.
     */
    private static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input", e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            String token = next();
            return token == null ? 0 : Integer.parseInt(token);
        }
    }
}

import java.io.IOException;
import java.io.InputStream;
import java.util.InputMismatchException;
import java.util.Set;
import java.util.TreeSet;

public class CFB {
    private static FastScanner scanner;
    private static int[][] inputArrays;

    public static void main(String[] args) {
        scanner = new FastScanner(System.in);
        int n = scanner.nextInt();
        inputArrays = new int[n][];
        for (int i = 0; i < n; i++) {
            inputArrays[i] = readIntArray(6);
        }

        Set<Integer> numbers = new TreeSet<>();
        // The original logic only processes up to the first 3 arrays
        int maxArrays = Math.min(n, 3);
        pickValues(0, new int[3], 0, maxArrays, numbers);

        System.out.println(findMex(numbers));
    }

    /**
     * Recursively picks one non-zero value from each of the first maxArrays arrays.
     * Once a complete combination is formed, it delegates to addAllPermutations.
     */
    private static void pickValues(int arrayIdx, int[] current, int depth, int maxArrays, Set<Integer> set) {
        if (arrayIdx == maxArrays) {
            addAllPermutations(current, depth, set);
            return;
        }
        for (int val : inputArrays[arrayIdx]) {
            if (val == 0) continue;
            current[depth] = val;
            pickValues(arrayIdx + 1, current, depth + 1, maxArrays, set);
        }
    }

    /**
     * Adds all permutations of the selected values to the set.
     * Explicitly handles lengths 1, 2, and 3 to match the original behavior.
     */
    private static void addAllPermutations(int[] values, int length, Set<Integer> set) {
        // Length 1
        for (int i = 0; i < length; i++) {
            set.add(values[i]);
        }
        // Length 2
        for (int i = 0; i < length; i++) {
            for (int j = 0; j < length; j++) {
                if (i == j) continue;
                set.add(values[i] * 10 + values[j]);
            }
        }
        // Length 3
        for (int i = 0; i < length; i++) {
            for (int j = 0; j < length; j++) {
                for (int k = 0; k < length; k++) {
                    if (i == j || j == k || i == k) continue;
                    set.add(values[i] * 100 + values[j] * 10 + values[k]);
                }
            }
        }
    }

    /**
     * Finds the smallest missing positive integer (MEX) in the sorted set.
     */
    private static int findMex(Set<Integer> set) {
        if (set.isEmpty()) {
            return 0;
        }
        int mex = 0;
        for (int num : set) {
            if (num == mex + 1) {
                mex++;
            } else {
                break;
            }
        }
        return mex;
    }

    private static int[] readIntArray(int n) {
        int[] res = new int[n];
        for (int i = 0; i < n; i++) {
            res[i] = scanner.nextInt();
        }
        return res;
    }

    /**
     * High-performance scanner for competitive programming / fast I/O.
     */
    @SuppressWarnings("unused")
    private static class FastScanner {
        private final InputStream stream;
        private final byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;

        FastScanner(InputStream stream) {
            this.stream = stream;
        }

        private int read() {
            if (numChars == -1) {
                throw new InputMismatchException();
            }
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0) {
                    return -1;
                }
            }
            return buf[curChar++];
        }

        private boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        private String next() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            StringBuilder res = new StringBuilder();
            do {
                res.appendCodePoint(c);
                c = read();
            } while (!isSpaceChar(c));
            return res.toString();
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.ArrayList;
import java.util.List;
import java.util.StringTokenizer;

public class Main {
    private static final int MAX_NUMBER = 1000;
    private static final int NUM_DIGITS_PER_PERSON = 6;
    private static final int DIGIT_RANGE = 10;

    public static void main(String[] args) {
        FastScanner in = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out);
        TaskB solver = new TaskB();
        solver.solve(in, out);
        out.flush();
        out.close();
    }

    static class TaskB {
        public void solve(FastScanner in, PrintWriter out) {
            int n = in.nextInt();
            boolean[][] availableDigits = new boolean[n][DIGIT_RANGE];

            // Read available digits for each person
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < NUM_DIGITS_PER_PERSON; j++) {
                    availableDigits[i][in.nextInt()] = true;
                }
            }

            // Find the largest consecutive number starting from 1 that can be formed
            int ans = 0;
            for (int i = 1; i < MAX_NUMBER; i++) {
                if (canForm(i, availableDigits)) {
                    ans = i;
                } else {
                    break;
                }
            }
            out.println(ans);
        }

        /**
         * Checks if the given number can be formed by assigning each digit
         * to a distinct person who has that digit available.
         */
        private boolean canForm(int number, boolean[][] availableDigits) {
            List<Integer> digits = new ArrayList<>();
            int temp = number;
            while (temp > 0) {
                digits.add(temp % 10);
                temp /= 10;
            }
            return backtrack(digits, 0, new boolean[availableDigits.length], availableDigits);
        }

        /**
         * Recursive backtracking to find a valid assignment of digits to people.
         */
        private boolean backtrack(List<Integer> digits, int idx, boolean[] usedPeople, boolean[][] availableDigits) {
            if (idx == digits.size()) {
                return true; // All digits successfully assigned
            }

            int digit = digits.get(idx);
            for (int p = 0; p < availableDigits.length; p++) {
                if (!usedPeople[p] && availableDigits[p][digit]) {
                    usedPeople[p] = true;
                    if (backtrack(digits, idx + 1, usedPeople, availableDigits)) {
                        return true;
                    }
                    usedPeople[p] = false; // Backtrack
                }
            }
            return false;
        }
    }

    /**
     * Fast input reader for competitive programming / high-throughput scenarios.
     */
    static class FastScanner {
        private BufferedReader br;
        private StringTokenizer st;

        public FastScanner(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        public String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) {
                        return null;
                    }
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            String s = next();
            if (s == null) {
                throw new RuntimeException("Unexpected end of input");
            }
            return Integer.parseInt(s);
        }
    }
}

import java.io.InputStream;
import java.io.IOException;
import java.io.OutputStream;
import java.io.PrintWriter;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.InputMismatchException;
import java.util.List;
import java.util.Set;

public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);

        Task solver = new Task();
        solver.solve(in, out);

        out.close();
    }

    static class Task {
        private static final int MAX_LIMIT = 1010;

        public void solve(InputReader sc, PrintWriter w) {
            int n = sc.nextInt();
            List<Set<Integer>> digitSets = new ArrayList<>(n);

            for (int i = 0; i < n; i++) {
                Set<Integer> set = new HashSet<>();
                for (int j = 0; j < 6; j++) {
                    set.add(sc.nextInt());
                }
                digitSets.add(set);
            }

            int maxConsecutive = 0;
            for (int i = 1; i <= MAX_LIMIT; i++) {
                if (!canFormNumber(digitSets, String.valueOf(i))) {
                    break;
                }
                maxConsecutive = i;
            }
            w.println(maxConsecutive);
        }

        /**
         * Checks if the number represented by numStr can be formed by assigning
         * each digit to a distinct set from digitSets.
         */
        private boolean canFormNumber(List<Set<Integer>> sets, String numStr) {
            // Optimization: Cannot form a number with more digits than available sets
            if (sets.size() < numStr.length()) {
                return false;
            }

            boolean[] usedSets = new boolean[sets.size()];
            return backtrack(sets, numStr, 0, usedSets);
        }

        /**
         * Recursive backtracking to find a valid assignment of digits to sets.
         */
        private boolean backtrack(List<Set<Integer>> sets, String numStr, int digitIdx, boolean[] usedSets) {
            if (digitIdx == numStr.length()) {
                return true;
            }

            int digit = numStr.charAt(digitIdx) - '0';
            for (int i = 0; i < sets.size(); i++) {
                if (!usedSets[i] && sets.get(i).contains(digit)) {
                    usedSets[i] = true;
                    if (backtrack(sets, numStr, digitIdx + 1, usedSets)) {
                        return true;
                    }
                    usedSets[i] = false; // Backtrack
                }
            }
            return false;
        }
    }

    /**
     * Fast input reader for competitive programming scenarios.
     */
    static class InputReader {
        private final InputStream stream;
        private final byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        public int read() {
            if (numChars == -1) {
                throw new InputMismatchException();
            }
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0) {
                    return -1;
                }
            }
            return buf[curChar++];
        }

        public int nextInt() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                res *= 10;
                res += c - '0';
                c = read();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

/**
 * Refactored solution for generating numbers from dice faces and finding the
 * smallest missing positive integer.
 * 
 * Key Improvements:
 * 1. Replaced broken/mixed I/O with a standard, maintainable FastScanner.
 * 2. Replaced HashMap with a boolean[] array for O(1) lookup and reduced memory overhead.
 * 3. Merged redundant compute() and permute() methods into a single recursive backtracking function.
 * 4. Eliminated unnecessary array reallocation in the permutation loop.
 * 5. Added pruning to skip numbers exceeding the search range.
 * 6. Used instance fields instead of static state to prevent bugs in repeated executions.
 * 7. Removed thread stack-size hack in favor of standard main() (adjust -Xss if needed).
 */
public class Main {
    // Maximum number to check for the missing value
    private static final int MAX_NUMBER = 1_000_000;

    // Data structures
    private int[][] faces;
    private boolean[] seenNumbers;
    private boolean[] usedDice;
    private int n;

    public static void main(String[] args) {
        new Main().solve();
    }

    /**
     * Orchestrates reading input, processing, and output.
     */
    private void solve() {
        FastScanner sc = new FastScanner();
        n = sc.nextInt();
        faces = new int[n][6];

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < 6; j++) {
                faces[i][j] = sc.nextInt();
            }
        }

        seenNumbers = new boolean[MAX_NUMBER + 1];
        usedDice = new boolean[n];

        // Generate numbers for all permutation lengths from 1 to n
        for (int len = 1; len <= n; len++) {
            buildNumbers(len, 0, 0, usedDice);
        }

        // Find the smallest positive integer not generated
        int ans = -1;
        for (int i = 1; i <= MAX_NUMBER; i++) {
            if (!seenNumbers[i]) {
                ans = i - 1;
                break;
            }
        }

        System.out.println(ans);
    }

    /**
     * Recursively builds numbers by concatenating faces of distinct dice.
     *
     * @param targetLength  The desired length of the permutation
     * @param currentLength The current length of the permutation being built
     * @param currentNumber The number formed so far
     * @param usedDice      Tracks which dice indices are already used in the current permutation
     */
    private void buildNumbers(int targetLength, int currentLength, int currentNumber, boolean[] usedDice) {
        if (currentLength == targetLength) {
            if (currentNumber <= MAX_NUMBER) {
                seenNumbers[currentNumber] = true;
            }
            return;
        }

        for (int i = 0; i < n; i++) {
            if (!usedDice[i]) {
                usedDice[i] = true;
                for (int face = 0; face < 6; face++) {
                    int nextNumber = currentNumber * 10 + faces[i][face];

                    // Pruning: if the number exceeds MAX_NUMBER, further concatenation will only increase it.
                    // This significantly improves performance for larger inputs.
                    if (nextNumber <= MAX_NUMBER) {
                        buildNumbers(targetLength, currentLength + 1, nextNumber, usedDice);
                    }
                }
                usedDice[i] = false; // Backtrack
            }
        }
    }

    /**
     * Lightweight, maintainable Fast I/O utility.
     * Replaces the original mixed BufferedReader/byte-array reader.
     */
    private static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        public String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input", e);
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            String token = next();
            return token == null ? 0 : Integer.parseInt(token);
        }
    }
}

import java.io.*;
import java.util.*;

public class P887B {

    private static final int NUM_DIGITS = 6;

    public static void main(String[] args) {
        FastScanner sc = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out));
        long startTime = System.currentTimeMillis();

        try {
            new P887B().solve(sc, out);
        } finally {
            out.flush();
            out.close();
            sc.close();
            System.err.println("[Time: " + (System.currentTimeMillis() - startTime) + " ms]");
        }
    }

    void solve(FastScanner sc, PrintWriter out) {
        int n = sc.nextInt();
        int[][] c = new int[n][NUM_DIGITS];

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < NUM_DIGITS; j++) {
                c[i][j] = sc.nextInt();
            }
        }

        BitSet nums = new BitSet();
        for (int i = 0; i < n; i++) {
            for (int ii = 0; ii < NUM_DIGITS; ii++) {
                int d1 = c[i][ii];
                nums.set(d1);

                for (int j = 0; j < n; j++) {
                    if (j == i) continue;
                    for (int jj = 0; jj < NUM_DIGITS; jj++) {
                        int d2 = c[j][jj];
                        nums.set(d1 * 10 + d2);

                        for (int k = 0; k < n; k++) {
                            if (k == i || k == j) continue;
                            for (int kk = 0; kk < NUM_DIGITS; kk++) {
                                nums.set(d1 * 100 + d2 * 10 + c[k][kk]);
                            }
                        }
                    }
                }
            }
        }

        out.println(nums.nextClearBit(1) - 1);
    }

    /**
     * Lightweight, reusable Fast I/O scanner to avoid static state pollution
     * and improve testability/maintainability.
     */
    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        public String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            String s = next();
            if (s == null) throw new RuntimeException("Unexpected end of input");
            return Integer.parseInt(s);
        }

        public void close() throws IOException {
            br.close();
        }
    }
}

import java.io.InputStream;
import java.io.PrintStream;
import java.util.Scanner;

public class Main {
    // Constants to replace magic numbers
    private static final int NUM_CUBES = 3;
    private static final int NUM_DIGITS = 10;
    private static final int FACES_PER_CUBE = 6;

    public static void main(String[] args) {
        Main instance = new Main();
        instance.solve(System.in, System.out);
    }

    /**
     * Orchestrates input parsing, core logic, and output.
     */
    public void solve(InputStream input, PrintStream output) {
        Scanner scanner = new Scanner(input);
        if (!scanner.hasNextInt()) {
            return;
        }

        int n = scanner.nextInt();
        boolean[][] cubeFaces = new boolean[NUM_CUBES][NUM_DIGITS];
        boolean[] availableDigits = new boolean[NUM_DIGITS];

        // Parse cube faces and track globally available digits
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < FACES_PER_CUBE; j++) {
                int digit = scanner.nextInt();
                cubeFaces[i][digit] = true;
                availableDigits[digit] = true;
            }
        }

        // Check for missing digits 1-9
        for (int digit = 1; digit < NUM_DIGITS; digit++) {
            if (!availableDigits[digit]) {
                output.println(digit - 1);
                return;
            }
        }

        // Check for missing digit 0
        if (!availableDigits[0]) {
            output.println(9);
            return;
        }

        // Find the smallest 3-digit number that cannot be formed
        for (int d1 = 0; d1 < NUM_DIGITS; d1++) {
            for (int d2 = 0; d2 < NUM_DIGITS; d2++) {
                for (int d3 = 0; d3 < NUM_DIGITS; d3++) {
                    if (!canFormNumber(d1, d2, d3, cubeFaces)) {
                        int result = d1 * 100 + d2 * 10 + d3 - 1;
                        output.println(result);
                        return;
                    }
                }
            }
        }
    }

    /**
     * Determines if a triplet of digits can be formed using the 3 cubes.
     * Tries all permutations of cube assignments to find a valid match.
     */
    private boolean canFormNumber(int d1, int d2, int d3, boolean[][] cubes) {
        // All permutations of cube indices (0, 1, 2)
        int[][] permutations = {
            {0, 1, 2}, {0, 2, 1}, {1, 0, 2},
            {1, 2, 0}, {2, 0, 1}, {2, 1, 0}
        };

        for (int[] perm : permutations) {
            if (isAssignmentValid(d1, d2, d3, perm, cubes)) {
                return true;
            }
        }
        return false;
    }

    /**
     * Validates a specific cube-to-digit assignment based on original problem constraints.
     * Note: Digit 0 bypasses cube checks per original logic.
     * Special case: If both first and second digits are 0, the second digit also bypasses checks.
     */
    private boolean isAssignmentValid(int d1, int d2, int d3, int[] cubeIndices, boolean[][] cubes) {
        if (d1 != 0 && !cubes[cubeIndices[0]][d1]) {
            return false;
        }
        if (d2 != 0 && !cubes[cubeIndices[1]][d2] && !(d1 == 0 && d2 == 0)) {
            return false;
        }
        if (d3 != 0 && !cubes[cubeIndices[2]][d3]) {
            return false;
        }
        return true;
    }
}

import java.io.*;
import java.util.*;

public class Task887B {

    public static void main(String[] args) {
        FastScanner sc = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            int n = sc.nextInt();
            List<Set<Integer>> diceFaces = new ArrayList<>();

            // Read n sets of dice faces
            for (int i = 0; i < n; i++) {
                Set<Integer> faces = new HashSet<>();
                for (int j = 0; j < 6; j++) {
                    faces.add(sc.nextInt());
                }
                diceFaces.add(faces);
            }

            // Maximum possible number with 3 digits is 999. 
            // boolean[] provides O(1) access and uses less memory than HashSet.
            boolean[] possible = new boolean[1000];

            // 1. Single-digit numbers
            for (Set<Integer> faces : diceFaces) {
                for (int num : faces) {
                    if (num != 0) {
                        possible[num] = true;
                    }
                }
            }

            // 2. Two-digit numbers (permutations of 2 distinct sets)
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < n; j++) {
                    if (i == j) continue;
                    for (int a : diceFaces.get(i)) {
                        for (int b : diceFaces.get(j)) {
                            if (a != 0) possible[a * 10 + b] = true;
                            if (b != 0) possible[b * 10 + a] = true;
                        }
                    }
                }
            }

            // 3. Three-digit numbers (permutations of 3 distinct sets)
            if (n >= 3) {
                for (int i = 0; i < n; i++) {
                    for (int j = 0; j < n; j++) {
                        if (i == j) continue;
                        for (int k = 0; k < n; k++) {
                            if (k == i || k == j) continue;
                            for (int a : diceFaces.get(i)) {
                                for (int b : diceFaces.get(j)) {
                                    for (int c : diceFaces.get(k)) {
                                        if (a != 0) {
                                            possible[a * 100 + b * 10 + c] = true;
                                            possible[a * 100 + c * 10 + b] = true;
                                        }
                                        if (b != 0) {
                                            possible[b * 100 + a * 10 + c] = true;
                                            possible[b * 100 + c * 10 + a] = true;
                                        }
                                        if (c != 0) {
                                            possible[c * 100 + a * 10 + b] = true;
                                            possible[c * 100 + b * 10 + a] = true;
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
            }

            // Find the smallest non-negative integer not in the set (Mex)
            int mex = 0;
            while (mex < possible.length && possible[mex]) {
                mex++;
            }

            out.println(mex);
        } catch (Exception e) {
            e.printStackTrace();
        } finally {
            out.flush();
        }
    }

    /**
     * FastScanner using BufferedReader and StringTokenizer for efficient input parsing.
     * Handles whitespace and newlines robustly.
     */
    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner(InputStream is) {
            br = new BufferedReader(new InputStreamReader(is));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input", e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        long nextLong() {
            return Long.parseLong(next());
        }
    }
}

import java.util.Scanner;

public class Solution {
    private static final int GRID_COLUMNS = 6;
    private static final int MAX_DIGITS = 3;

    public static void main(String[] args) {
        // Use try-with-resources to automatically close the Scanner
        try (Scanner scanner = new Scanner(System.in)) {
            if (!scanner.hasNextInt()) {
                return;
            }
            int n = scanner.nextInt();
            String[][] grid = readGrid(scanner, n);

            int consecutiveCount = countConsecutiveNumbers(grid, n);
            System.out.println(consecutiveCount);
        }
    }

    /**
     * Reads the n x 6 grid of strings from the input.
     */
    private static String[][] readGrid(Scanner scanner, int n) {
        String[][] grid = new String[n][GRID_COLUMNS];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < GRID_COLUMNS; j++) {
                grid[i][j] = scanner.next();
            }
        }
        return grid;
    }

    /**
     * Counts how many consecutive integers starting from 1 can be formed
     * by concatenating 1, 2, or 3 cells from the grid.
     */
    private static int countConsecutiveNumbers(String[][] grid, int n) {
        int count = 0;
        int currentNumber = 1;

        while (true) {
            String target = String.valueOf(currentNumber);
            int length = target.length();

            // Original logic only handles up to 3-digit numbers
            if (length > MAX_DIGITS) {
                break;
            }

            boolean found = false;
            switch (length) {
                case 1:
                    found = containsSingle(grid, n, target);
                    break;
                case 2:
                    found = containsPair(grid, n, target);
                    break;
                case 3:
                    found = containsTriplet(grid, n, target);
                    break;
            }

            if (found) {
                count++;
                currentNumber++;
            } else {
                // Sequence breaks when the next consecutive number cannot be formed
                break;
            }
        }
        return count;
    }

    /**
     * Searches for a single-cell match.
     */
    private static boolean containsSingle(String[][] grid, int n, String target) {
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < GRID_COLUMNS; j++) {
                if (grid[i][j].equals(target)) {
                    return true;
                }
            }
        }
        return false;
    }

    /**
     * Searches for a two-cell match. Cells must be in different rows.
     */
    private static boolean containsPair(String[][] grid, int n, String target) {
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < GRID_COLUMNS; j++) {
                for (int i2 = 0; i2 < n; i2++) {
                    for (int j2 = 0; j2 < GRID_COLUMNS; j2++) {
                        if (i == i2) continue;
                        if ((grid[i][j] + grid[i2][j2]).equals(target)) {
                            return true;
                        }
                    }
                }
            }
        }
        return false;
    }

    /**
     * Searches for a three-cell match. All three cells must be in different rows.
     */
    private static boolean containsTriplet(String[][] grid, int n, String target) {
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < GRID_COLUMNS; j++) {
                for (int i2 = 0; i2 < n; i2++) {
                    for (int j2 = 0; j2 < GRID_COLUMNS; j2++) {
                        if (i == i2) continue;
                        for (int i3 = 0; i3 < n; i3++) {
                            for (int j3 = 0; j3 < GRID_COLUMNS; j3++) {
                                if (i3 == i || i3 == i2) continue;
                                if ((grid[i][j] + grid[i2][j2] + grid[i3][j3]).equals(target)) {
                                    return true;
                                }
                            }
                        }
                    }
                }
            }
        }
        return false;
    }
}

import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.Arrays;
import java.util.InputMismatchException;

public class CodeforcesSolution {
    public static void main(String[] args) {
        InputReader in = new InputReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        int n = in.nextInt();
        int[] multipliers = new int[10];
        boolean[] seenInGroup = new boolean[10];

        // Initialize all multipliers to 1
        Arrays.fill(multipliers, 1);

        for (int i = 0; i < n; i++) {
            int currentMultiplier = getMultiplierForIteration(i);

            for (int j = 0; j < 6; j++) {
                int digit = in.nextInt();
                if (!seenInGroup[digit]) {
                    multipliers[digit] *= currentMultiplier;
                    seenInGroup[digit] = true;
                }
            }
            // Reset tracking array for the next iteration
            Arrays.fill(seenInGroup, false);
        }

        int result = findResult(multipliers);
        out.println(result);
        out.flush();
        out.close();
    }

    /**
     * Returns the multiplier value based on the current iteration index.
     * Matches the original logic: i=0 -> 2, i=1 -> 3, i>=2 -> 5
     */
    private static int getMultiplierForIteration(int i) {
        if (i == 1) return 3;
        if (i >= 2) return 5;
        return 2;
    }

    /**
     * Finds the result by scanning pairs of multipliers according to the problem's rules.
     * Uses early returns to eliminate the need for a boolean flag and nested breaks.
     */
    private static int findResult(int[] multipliers) {
        for (int i = 0; i < 10; i++) {
            for (int j = 0; j < 10; j++) {
                if (i == 0) {
                    if (j > 0 && multipliers[j] == 1) {
                        return j - 1;
                    }
                } else if (multipliers[0] == 1) {
                    return 9;
                } else {
                    int product = multipliers[i] * multipliers[j];
                    if (product == 4 || product == 9 || product == 25) {
                        return i * 10 + j - 1;
                    }
                }
            }
        }
        return -1; // Fallback; problem constraints guarantee a valid result
    }

    /**
     * Fast input reader for competitive programming.
     */
    static class InputReader {
        private final InputStream stream;
        private final byte[] buf = new byte[8192];
        private int curChar, snumChars;
        private SpaceCharFilter filter;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        public int snext() {
            if (snumChars == -1) {
                throw new InputMismatchException();
            }
            if (curChar >= snumChars) {
                curChar = 0;
                try {
                    snumChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (snumChars <= 0) {
                    return -1;
                }
            }
            return buf[curChar++];
        }

        public int nextInt() {
            int c = snext();
            while (isSpaceChar(c)) {
                c = snext();
            }
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = snext();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                res *= 10;
                res += c - '0';
                c = snext();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public long nextLong() {
            int c = snext();
            while (isSpaceChar(c)) {
                c = snext();
            }
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = snext();
            }
            long res = 0;
            do {
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                res *= 10;
                res += c - '0';
                c = snext();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public int[] nextIntArray(int n) {
            int[] a = new int[n];
            for (int i = 0; i < n; i++) {
                a[i] = nextInt();
            }
            return a;
        }

        public String readString() {
            int c = snext();
            while (isSpaceChar(c)) {
                c = snext();
            }
            StringBuilder res = new StringBuilder();
            do {
                res.appendCodePoint(c);
                c = snext();
            } while (!isSpaceChar(c));
            return res.toString();
        }

        public String nextLine() {
            int c = snext();
            while (isSpaceChar(c)) {
                c = snext();
            }
            StringBuilder res = new StringBuilder();
            do {
                res.appendCodePoint(c);
                c = snext();
            } while (!isEndOfLine(c));
            return res.toString();
        }

        public boolean isSpaceChar(int c) {
            if (filter != null) {
                return filter.isSpaceChar(c);
            }
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        private boolean isEndOfLine(int c) {
            return c == '\n' || c == '\r' || c == -1;
        }

        public interface SpaceCharFilter {
            boolean isSpaceChar(int ch);
        }
    }
}

import java.util.*;
import java.io.*;

public class Solution {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        // Read number of people
        if (!sc.hasNextInt()) return;
        int n = sc.nextInt();

        // Store available digits for each person.
        // Using a List of Sets allows for dynamic sizing and O(1) lookups.
        List<Set<Integer>> peopleDigits = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            Set<Integer> digits = new HashSet<>();
            for (int j = 0; j < 6; j++) {
                if (sc.hasNext()) {
                    String token = sc.next();
                    if (!token.isEmpty()) {
                        // Original code logic: takes the first character of the string
                        digits.add(token.charAt(0) - '0');
                    }
                }
            }
            peopleDigits.add(digits);
        }

        // Phase 1: Check 1-digit numbers (1 to 9)
        // We look for the first number that cannot be formed.
        for (int num = 1; num <= 9; num++) {
            if (!canForm(num, peopleDigits)) {
                System.out.println(num - 1);
                return;
            }
        }

        // If all 1-digit numbers are formable, check 2-digit numbers (10 to 99)
        // Optimization: If there are fewer than 2 people, we cannot form any 2-digit number.
        if (n < 2) {
            System.out.println(9);
            return;
        }

        for (int num = 10; num <= 99; num++) {
            if (!canForm(num, peopleDigits)) {
                System.out.println(num - 1);
                return;
            }
        }

        // If all 2-digit numbers are formable, check 3-digit numbers (100 to 999)
        // Optimization: If there are fewer than 3 people, we cannot form any 3-digit number.
        if (n < 3) {
            System.out.println(99);
            return;
        }

        for (int num = 100; num <= 999; num++) {
            if (!canForm(num, peopleDigits)) {
                System.out.println(num - 1);
                return;
            }
        }

        // If all numbers up to 999 are formable
        System.out.println(999);
    }

    /**
     * Checks if a number can be formed by the digits available in the people's sets.
     * A number is formable if distinct people can provide the required digits.
     */
    private static boolean canForm(int number, List<Set<Integer>> people) {
        String s = String.valueOf(number);
        int len = s.length();

        if (len == 1) {
            int d = s.charAt(0) - '0';
            // Check if any single person has the digit
            for (Set<Integer> p : people) {
                if (p.contains(d)) return true;
            }
            return false;

        } else if (len == 2) {
            int d1 = s.charAt(0) - '0';
            int d2 = s.charAt(1) - '0';
            int size = people.size();

            // Check if there exist two distinct people who can provide d1 and d2.
            // We iterate through all ordered pairs of distinct people.
            for (int i = 0; i < size; i++) {
                if (!people.get(i).contains(d1)) continue;
                for (int j = 0; j < size; j++) {
                    if (i == j) continue;
                    if (people.get(j).contains(d2)) return true;
                }
            }
            return false;

        } else if (len == 3) {
            int d1 = s.charAt(0) - '0';
            int d2 = s.charAt(1) - '0';
            int d3 = s.charAt(2) - '0';
            int size = people.size();

            // Check if there exist three distinct people who can provide d1, d2, and d3.
            // We iterate through all ordered triplets of distinct people.
            for (int i = 0; i < size; i++) {
                if (!people.get(i).contains(d1)) continue;
                for (int j = 0; j < size; j++) {
                    if (i == j) continue;
                    if (!people.get(j).contains(d2)) continue;
                    for (int k = 0; k < size; k++) {
                        if (k == i || k == j) continue;
                        if (people.get(k).contains(d3)) return true;
                    }
                }
            }
            return false;
        }

        return false;
    }
}

import java.io.InputStream;
import java.io.IOException;
import java.io.OutputStream;
import java.io.PrintWriter;
import java.util.InputMismatchException;

public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        FastReader in = new FastReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);

        TaskB solver = new TaskB();
        solver.solve(in, out);

        out.close();
    }

    /**
     * Solves the problem by finding the largest integer that can be formed
     * by selecting digits from the provided grid rows.
     */
    static class TaskB {
        private static final int COLUMNS = 6;
        private int[][] grid;
        private int rowCount;

        public void solve(FastReader in, PrintWriter out) {
            rowCount = in.nextInt();
            grid = new int[rowCount][COLUMNS];
            for (int i = 0; i < rowCount; i++) {
                grid[i] = in.nextIntArray(COLUMNS);
            }

            int maxValidNumber = 0;
            while (canFormNumber(maxValidNumber + 1, false, false, false)) {
                maxValidNumber++;
            }
            out.println(maxValidNumber);
        }

        /**
         * Checks if the given value exists in the specified row of the grid.
         */
        private boolean hasValueInRow(int rowIndex, int value) {
            for (int val : grid[rowIndex]) {
                if (val == value) {
                    return true;
                }
            }
            return false;
        }

        /**
         * Recursively checks if the number can be formed by assigning each digit
         * to an unused row (0, 1, or 2) that contains the digit.
         */
        private boolean canFormNumber(int number, boolean usedRow0, boolean usedRow1, boolean usedRow2) {
            if (number == 0) {
                return true;
            }

            int currentDigit = number % 10;
            int remainingNumber = number / 10;

            if (!usedRow0 && hasValueInRow(0, currentDigit) &&
                canFormNumber(remainingNumber, true, usedRow1, usedRow2)) {
                return true;
            }
            if (rowCount >= 2 && !usedRow1 && hasValueInRow(1, currentDigit) &&
                canFormNumber(remainingNumber, usedRow0, true, usedRow2)) {
                return true;
            }
            if (rowCount == 3 && !usedRow2 && hasValueInRow(2, currentDigit) &&
                canFormNumber(remainingNumber, usedRow0, usedRow1, true)) {
                return true;
            }
            return false;
        }
    }

    /**
     * Fast input reader optimized for competitive programming environments.
     */
    static class FastReader {
        private final InputStream stream;
        private final byte[] buffer = new byte[8192];
        private int bufferPointer = 0;
        private int bytesRead = 0;

        public FastReader(InputStream stream) {
            this.stream = stream;
        }

        private int readByte() {
            if (bytesRead == -1) {
                throw new InputMismatchException();
            }
            if (bufferPointer >= bytesRead) {
                bufferPointer = 0;
                try {
                    bytesRead = stream.read(buffer);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (bytesRead <= 0) {
                    return -1;
                }
            }
            return buffer[bufferPointer++];
        }

        public int nextInt() {
            int c = readByte();
            while (isSpaceChar(c)) {
                c = readByte();
            }
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = readByte();
            }
            int result = 0;
            do {
                if (c == ',') {
                    c = readByte();
                }
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                result *= 10;
                result += c - '0';
                c = readByte();
            } while (!isSpaceChar(c));
            return result * sign;
        }

        public int[] nextIntArray(int size) {
            int[] array = new int[size];
            for (int i = 0; i < size; i++) {
                array[i] = nextInt();
            }
            return array;
        }

        private boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }
    }
}

import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        // Read number of rows
        if (!scanner.hasNextInt()) {
            scanner.close();
            return;
        }
        int numRows = scanner.nextInt();

        // Read the grid of digits
        int[][] grid = new int[numRows][6];
        for (int i = 0; i < numRows; i++) {
            for (int j = 0; j < 6; j++) {
                grid[i][j] = scanner.nextInt();
            }
        }

        // Array to keep track of numbers that can be formed.
        // Size 10005 is sufficient to check numbers up to ~1000.
        // If 1..1000 are all possible, the answer would be 1000.
        boolean[] possible = new boolean[10005];

        // 1. Mark all 1-digit numbers (using 1 row)
        mark1DigitNumbers(grid, possible);

        // 2. Mark all 2-digit numbers (using 2 distinct rows)
        if (numRows >= 2) {
            mark2DigitNumbers(grid, possible);
        }

        // 3. Mark all 3-digit numbers (using 3 distinct rows)
        if (numRows >= 3) {
            mark3DigitNumbers(grid, possible);
        }

        // Calculate the length of the contiguous sequence of integers starting from 1
        // that can be formed. This matches the logic of the original code:
        // - For n=1, it found the first missing number 'm' and output m-1.
        // - For n>=2, it found the last present number 'v' and output v.
        // Both result in the count of consecutive integers starting from 1.
        int count = 0;
        for (int i = 1; i < possible.length; i++) {
            if (possible[i]) {
                count++;
            } else {
                break;
            }
        }

        System.out.println(count);

        scanner.close();
    }

    /**
     * Marks all 1-digit numbers present in the grid.
     */
    private static void mark1DigitNumbers(int[][] grid, boolean[] possible) {
        for (int[] row : grid) {
            for (int digit : row) {
                if (digit >= 0 && digit <= 9) {
                    possible[digit] = true;
                }
            }
        }
    }

    /**
     * Marks all 2-digit numbers formed by concatenating a digit from one row 
     * and a digit from a different row.
     */
    private static void mark2DigitNumbers(int[][] grid, boolean[] possible) {
        int n = grid.length;
        // Iterate over all ordered pairs of distinct rows
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (i == j) continue; // Rows must be distinct

                for (int d1 : grid[i]) {
                    for (int d2 : grid[j]) {
                        int number = d1 * 10 + d2;
                        if (number >= 1 && number < possible.length) {
                            possible[number] = true;
                        }
                    }
                }
            }
        }
    }

    /**
     * Marks all 3-digit numbers formed by concatenating digits from three 
     * distinct rows.
     */
    private static void mark3DigitNumbers(int[][] grid, boolean[] possible) {
        int n = grid.length;
        // Iterate over all ordered triples of distinct rows
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (i == j) continue;
                for (int k = 0; k < n; k++) {
                    if (k == i || k == j) continue;

                    for (int d1 : grid[i]) {
                        for (int d2 : grid[j]) {
                            for (int d3 : grid[k]) {
                                int number = d1 * 100 + d2 * 10 + d3;
                                if (number >= 1 && number < possible.length) {
                                    possible[number] = true;
                                }
                            }
                        }
                    }
                }
            }
        }
    }
}

import java.io.*;
import java.util.InputMismatchException;

public class Main {
    public static void main(String[] args) {
        FastReader in = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);
        new TaskB().solve(in, out);
        out.close();
    }

    static class TaskB {
        public void solve(FastReader in, PrintWriter out) {
            int n = in.nextInt();
            if (n > 3) {
                throw new IllegalArgumentException("Problem constraints require n <= 3");
            }

            int[][] digitArrays = new int[n][6];
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < 6; j++) {
                    digitArrays[i][j] = in.nextInt();
                }
            }

            // Find the smallest positive integer that cannot be formed.
            // Based on problem constraints, the answer will not exceed 999.
            for (int i = 1; i <= 999; i++) {
                if (!canForm(i, digitArrays)) {
                    out.println(i - 1);
                    return;
                }
            }
            out.println(999);
        }

        /**
         * Determines if a number can be formed by concatenating exactly one digit from 
         * each of a subset of the provided arrays. Each array can contribute at most one digit.
         */
        private boolean canForm(int number, int[][] digitArrays) {
            String s = Integer.toString(number);
            int len = s.length();

            // A number cannot have more digits than the number of available arrays
            if (len > digitArrays.length) {
                return false;
            }

            boolean[] usedArrays = new boolean[digitArrays.length];
            return backtrack(s, 0, usedArrays, digitArrays);
        }

        /**
         * Recursive backtracking to match each digit of the target number to an unused array.
         */
        private boolean backtrack(String s, int pos, boolean[] usedArrays, int[][] digitArrays) {
            if (pos == s.length()) {
                return true; // Successfully matched all digits
            }

            int targetDigit = s.charAt(pos) - '0';

            for (int i = 0; i < digitArrays.length; i++) {
                if (!usedArrays[i]) {
                    for (int digit : digitArrays[i]) {
                        if (digit == targetDigit) {
                            usedArrays[i] = true;
                            if (backtrack(s, pos + 1, usedArrays, digitArrays)) {
                                return true;
                            }
                            usedArrays[i] = false; // Backtrack
                        }
                    }
                }
            }
            return false;
        }
    }

    /**
     * Fast I/O reader commonly used in competitive programming.
     */
    static class FastReader {
        private InputStream stream;
        private byte[] buf = new byte[8192];
        private int curChar;
        private int pnumChars;

        public FastReader(InputStream stream) {
            this.stream = stream;
        }

        private int pread() {
            if (pnumChars == -1) {
                throw new InputMismatchException();
            }
            if (curChar >= pnumChars) {
                curChar = 0;
                try {
                    pnumChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (pnumChars <= 0) {
                    return -1;
                }
            }
            return buf[curChar++];
        }

        public int nextInt() {
            int c = pread();
            while (isSpaceChar(c)) {
                c = pread();
            }
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = pread();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                res *= 10;
                res += c - '0';
                c = pread();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public int[] nextIntArray(int n) {
            int[] array = new int[n];
            for (int i = 0; i < n; i++) {
                array[i] = nextInt();
            }
            return array;
        }

        private boolean isSpaceChar(int c) {
            return isWhitespace(c);
        }

        private static boolean isWhitespace(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.OutputStreamWriter;
import java.io.PrintWriter;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Set;

public class Main {
    private static final int MAX_VALUE = 1000;

    public static void main(String[] args) throws IOException {
        // Use try-with-resources to ensure streams are properly closed
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
             PrintWriter out = new PrintWriter(new OutputStreamWriter(System.out))) {

            String line = br.readLine();
            if (line == null) return;

            int n = Integer.parseInt(line.trim());
            int result = solve(n, br);
            out.println(result);
            out.flush();
        }
    }

    private static int solve(int n, BufferedReader br) throws IOException {
        switch (n) {
            case 1: return solveCase1(br);
            case 2: return solveCase2(br);
            case 3: return solveCase3(br);
            default: throw new IllegalArgumentException("Unsupported case: " + n);
        }
    }

    /**
     * Case 1: Single set of faces. Finds the smallest missing integer.
     */
    private static int solveCase1(BufferedReader br) throws IOException {
        String[] tokens = br.readLine().trim().split("\\s+");
        Set<Integer> faces = parseToIntSet(tokens);

        for (int i = 1; i < MAX_VALUE; i++) {
            if (!faces.contains(i)) {
                return i - 1;
            }
        }
        return MAX_VALUE - 1;
    }

    /**
     * Case 2: Two sets of faces. Uses unified validation logic.
     */
    private static int solveCase2(BufferedReader br) throws IOException {
        List<Set<Integer>> sets = new ArrayList<>();
        sets.add(parseToIntSet(br.readLine().trim().split("\\s+")));
        sets.add(parseToIntSet(br.readLine().trim().split("\\s+")));

        for (int i = 1; i < MAX_VALUE; i++) {
            if (shouldStopMultiSet(i, sets)) {
                return i - 1;
            }
        }
        return MAX_VALUE - 1;
    }

    /**
     * Case 3: Three sets of faces. Uses unified validation logic.
     */
    private static int solveCase3(BufferedReader br) throws IOException {
        List<Set<Integer>> sets = new ArrayList<>();
        for (int i = 0; i < 3; i++) {
            sets.add(parseToIntSet(br.readLine().trim().split("\\s+")));
        }

        for (int i = 1; i < MAX_VALUE; i++) {
            if (shouldStopMultiSet(i, sets)) {
                return i - 1;
            }
        }
        return MAX_VALUE - 1;
    }

    /**
     * Parses a string array of numbers into a Set for O(1) lookups.
     * Replaces the original repeated sorting and binary search approach.
     */
    private static Set<Integer> parseToIntSet(String[] tokens) {
        Set<Integer> set = new HashSet<>();
        for (String token : tokens) {
            try {
                set.add(Integer.parseInt(token.trim()));
            } catch (NumberFormatException e) {
                // Gracefully ignore malformed tokens; competitive inputs are typically well-formed
            }
        }
        return set;
    }

    /**
     * Unified validation logic for Cases 2 and 3.
     * Preserves the exact behavior of the original Cons() and Cons2() methods:
     * - For 1-digit numbers: stops if the digit is missing from ALL sets.
     * - For 2-digit numbers: stops if the tens and units digits belong to the SAME set 
     *   (or one is missing), i.e., when !Cons/Cons2 returns true.
     */
    private static boolean shouldStopMultiSet(int num, List<Set<Integer>> sets) {
        String numStr = String.valueOf(num);
        if (numStr.length() == 1) {
            int digit = numStr.charAt(0) - '0';
            // Original Cons/Cons2 returns true if digit exists in any set.
            // We stop if it does NOT exist in any set.
            for (Set<Integer> set : sets) {
                if (set.contains(digit)) {
                    return false; // Found, continue searching
                }
            }
            return true; // Not found, stop and return num - 1
        } else {
            int tens = numStr.charAt(0) - '0';
            int units = numStr.charAt(1) - '0';

            List<Integer> tensRows = new ArrayList<>();
            List<Integer> unitsRows = new ArrayList<>();

            for (int i = 0; i < sets.size(); i++) {
                if (sets.get(i).contains(tens)) tensRows.add(i);
                if (sets.get(i).contains(units)) unitsRows.add(i);
            }

            // Original Cons/Cons2 returns true if digits belong to different sets.
            // We stop if !Cons -> i.e., if digits are in the same set (or one is missing).
            boolean differentRows = false;
            for (int t : tensRows) {
                for (int u : unitsRows) {
                    if (t != u) {
                        differentRows = true;
                        break;
                    }
                }
                if (differentRows) break;
            }
            return !differentRows;
        }
    }
}

import java.io.*;
import java.util.*;

public class B887 {

    private static final int MAX_CHECK = 1000;
    private static final int NUM_GROUPS = 3;
    private static final int NUM_PER_GROUP = 6;

    public static void main(String[] args) {
        FasterScanner in = new FasterScanner();
        PrintWriter out = new PrintWriter(System.out);

        int n = in.nextInt();

        // Use List<Set<Integer>> for type safety and O(1) lookup performance
        List<Set<Integer>> groups = new ArrayList<>(NUM_GROUPS);
        for (int i = 0; i < NUM_GROUPS; i++) {
            Set<Integer> group = new HashSet<>();
            group.add(-1); // Preserve original behavior: -1 is always a valid match
            groups.add(group);
        }

        // Distribute input numbers across the 3 groups round-robin
        // (Fixed original bug: arr[i] would throw IndexOutOfBounds if n > 3)
        for (int i = 0; i < n; i++) {
            int groupIndex = i % NUM_GROUPS;
            for (int j = 0; j < NUM_PER_GROUP; j++) {
                groups.get(groupIndex).add(in.nextInt());
            }
        }

        // Check numbers from 1 to 1000
        for (int i = 1; i <= MAX_CHECK; i++) {
            int x1 = i % 10;
            int x2 = (i / 10) % 10;
            int x3 = (i / 100) % 10;

            // Handle leading zeros by replacing them with -1
            if (x2 == 0) x2 = -1;
            if (x3 == 0) x3 = -1;

            // If digits match any permutation of the groups, continue searching
            if (isPermutationMatch(x1, x2, x3, groups)) {
                continue;
            }

            // First number that doesn't match -> output i-1
            out.println(i - 1);
            out.flush();
            return;
        }

        // Fallback if no match is found within range
        out.println(0);
        out.flush();
    }

    /**
     * Checks if (d1, d2, d3) can be mapped to (groups[0], groups[1], groups[2])
     * in any permutation order.
     */
    private static boolean isPermutationMatch(int d1, int d2, int d3, List<Set<Integer>> groups) {
        Set<Integer> g0 = groups.get(0);
        Set<Integer> g1 = groups.get(1);
        Set<Integer> g2 = groups.get(2);

        return (g0.contains(d1) && g1.contains(d2) && g2.contains(d3)) ||
               (g0.contains(d1) && g1.contains(d3) && g2.contains(d2)) ||
               (g0.contains(d2) && g1.contains(d1) && g2.contains(d3)) ||
               (g0.contains(d2) && g1.contains(d3) && g2.contains(d1)) ||
               (g0.contains(d3) && g1.contains(d1) && g2.contains(d2)) ||
               (g0.contains(d3) && g1.contains(d2) && g2.contains(d1));
    }

    /**
     * Fast I/O scanner commonly used in competitive programming.
     */
    static class FasterScanner {
        private byte[] buf = new byte[1024];
        private int curChar;
        private int snumChars;

        public int read() {
            if (snumChars == -1)
                throw new InputMismatchException();
            if (curChar >= snumChars) {
                curChar = 0;
                try {
                    snumChars = System.in.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (snumChars <= 0)
                    return -1;
            }
            return buf[curChar++];
        }

        public String nextLine() {
            int c = read();
            while (isSpaceChar(c))
                c = read();
            StringBuilder res = new StringBuilder();
            do {
                res.appendCodePoint(c);
                c = read();
            } while (!isEndOfLine(c));
            return res.toString();
        }

        public String nextString() {
            int c = read();
            while (isSpaceChar(c))
                c = read();
            StringBuilder res = new StringBuilder();
            do {
                res.appendCodePoint(c);
                c = read();
            } while (!isSpaceChar(c));
            return res.toString();
        }

        public long nextLong() {
            int c = read();
            while (isSpaceChar(c))
                c = read();
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            long res = 0;
            do {
                if (c < '0' || c > '9')
                    throw new InputMismatchException();
                res *= 10;
                res += c - '0';
                c = read();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public int nextInt() {
            int c = read();
            while (isSpaceChar(c))
                c = read();
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9')
                    throw new InputMismatchException();
                res *= 10;
                res += c - '0';
                c = read();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public int[] nextIntArray(int n) {
            int[] arr = new int[n];
            for (int i = 0; i < n; i++) {
                arr[i] = nextInt();
            }
            return arr;
        }

        public long[] nextLongArray(int n) {
            long[] arr = new long[n];
            for (int i = 0; i < n; i++) {
                arr[i] = nextLong();
            }
            return arr;
        }

        private boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        private boolean isEndOfLine(int c) {
            return c == '\n' || c == '\r' || c == -1;
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

public class NumberSolver {

    public static void main(String[] args) {
        // Use try-with-resources to ensure BufferedReader is closed automatically
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {

            String line = br.readLine();
            if (line == null || line.trim().isEmpty()) {
                return;
            }

            // Parse the number of lines (n)
            int n = Integer.parseInt(line.trim());

            // availableDigits[i][d] is true if digit d is present on line i
            // Digits are 0-9, so size is 10.
            boolean[][] availableDigits = new boolean[n][10];

            // Read the n lines of digits
            for (int i = 0; i < n; i++) {
                line = br.readLine();
                if (line == null) break;

                StringTokenizer tokenizer = new StringTokenizer(line);
                for (int j = 0; j < 6; j++) {
                    if (tokenizer.hasMoreTokens()) {
                        int digit = Integer.parseInt(tokenizer.nextToken());
                        // Ensure digit is within valid range 0-9
                        if (digit >= 0 && digit <= 9) {
                            availableDigits[i][digit] = true;
                        }
                    }
                }
            }

            // Determine the upper bound for the search loop based on n
            // Original logic: n=1 checks 1-9, n=2 and n=3 check 1-99
            int searchLimit = (n == 1) ? 10 : 100;

            // Iterate to find the smallest number that cannot be formed
            for (int i = 1; i < searchLimit; i++) {
                if (!canFormNumber(i, n, availableDigits)) {
                    // If number i cannot be formed, print i-1 and exit
                    System.out.println(i - 1);
                    return;
                }
            }

            // Specific post-loop logic for n=3
            // If all numbers 1-99 are formable, print 100
            if (n == 3) {
                System.out.println(100);
            }
            // For n=1 and n=2, the original code does nothing if the loop completes

        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    /**
     * Checks if a number can be formed using the available digits on n lines.
     */
    private static boolean canFormNumber(int number, int n, boolean[][] availableDigits) {
        if (number < 10) {
            // Single digit number: check if the digit exists in any of the n lines
            int digit = number;
            for (int r = 0; r < n; r++) {
                if (availableDigits[r][digit]) {
                    return true;
                }
            }
            return false;
        } else {
            // Two digit number: check if we can assign tens and ones digits to distinct lines
            int tens = number / 10;
            int ones = number % 10;
            return canFormTwoDigits(tens, ones, n, availableDigits);
        }
    }

    /**
     * Checks if two digits (tens and ones) can be formed using distinct lines.
     * This replaces the complex logic found in the original isPossible method
     * and the specific checks for n=2.
     */
    private static boolean canFormTwoDigits(int tens, int ones, int n, boolean[][] availableDigits) {
        // Iterate through all possible lines for the tens digit
        for (int r1 = 0; r1 < n; r1++) {
            if (availableDigits[r1][tens]) {
                // Iterate through all possible lines for the ones digit
                // Must be a different line than the one used for tens (r1 != r2)
                for (int r2 = 0; r2 < n; r2++) {
                    if (r1 != r2 && availableDigits[r2][ones]) {
                        return true;
                    }
                }
            }
        }
        return false;
    }
}

import java.util.HashSet;
import java.util.Scanner;
import java.util.Set;

public class MissingNumberFinder {
    // Extracted magic numbers to constants for easier maintenance
    private static final int DIGITS_PER_ROW = 6;
    private static final int MAX_N = 3;
    private static final int SEARCH_LIMIT = 1000;

    public static void main(String[] args) {
        // Use try-with-resources to ensure the Scanner is properly closed
        try (Scanner scanner = new Scanner(System.in)) {
            if (!scanner.hasNextInt()) {
                return;
            }
            int n = scanner.nextInt();

            // Input validation to prevent out-of-bounds or unsupported cases
            if (n < 1 || n > MAX_N) {
                System.err.println("Error: n must be between 1 and 3.");
                return;
            }

            int[][] digits = new int[n][DIGITS_PER_ROW];
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < DIGITS_PER_ROW; j++) {
                    if (scanner.hasNextInt()) {
                        digits[i][j] = scanner.nextInt();
                    } else {
                        System.err.println("Error: Insufficient input data.");
                        return;
                    }
                }
            }

            // Use generic type to avoid raw type warnings
            Set<Integer> generatedNumbers = new HashSet<>();

            // Replace repetitive if-else branches with a generalized backtracking approach
            generateNumbers(digits, n, new boolean[n], 0, 0, generatedNumbers);

            // Preserve original search limit behavior
            int limit = (n == 1) ? 7 : SEARCH_LIMIT;
            System.out.println(findSmallestMissing(generatedNumbers, limit));
        }
    }

    /**
     * Recursively generates all numbers formed by concatenating digits from 
     * distinct rows in all possible permutations, up to a maximum depth of n.
     *
     * @param digits   The input 2D array of digits
     * @param n        The number of rows to consider
     * @param used     Tracks which rows have already been used in the current path
     * @param currentNumber The number being built
     * @param depth    Current recursion depth (number of rows used so far)
     * @param result   Set to store all generated valid numbers
     */
    private static void generateNumbers(int[][] digits, int n, boolean[] used, 
                                        int currentNumber, int depth, Set<Integer> result) {
        if (currentNumber > 0) {
            result.add(currentNumber);
        }
        // Stop recursion once we've selected digits from all n rows
        if (depth == n) {
            return;
        }

        for (int i = 0; i < n; i++) {
            if (!used[i]) {
                used[i] = true;
                for (int d : digits[i]) {
                    generateNumbers(digits, n, used, currentNumber * 10 + d, depth + 1, result);
                }
                used[i] = false; // Backtrack to explore other permutations
            }
        }
    }

    /**
     * Finds the smallest positive integer not present in the generated set.
     * Preserves original behavior: returns (i - 1) where i is the first missing number.
     *
     * @param numbers Set of generated numbers
     * @param limit   Upper bound for the search range
     * @return The smallest missing value minus one, or the limit if all are present
     */
    private static int findSmallestMissing(Set<Integer> numbers, int limit) {
        for (int i = 1; i <= limit; i++) {
            if (!numbers.contains(i)) {
                return i - 1;
            }
        }
        return limit; // Fallback (should not be reached under valid problem constraints)
    }
}

import java.io.BufferedReader;
