import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Scanner;
import java.util.Set;

public class B {

    public static void main(String[] args) {
        // Using try-with-resources to ensure streams are closed properly
        try (Scanner in = new Scanner(new BufferedReader(new InputStreamReader(System.in)));
                PrintWriter out = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)))) {

            // Read the number of sets
            if (!in.hasNextInt()) return;
            final int numSets = in.nextInt();

            // Read the sets of integers
            final List<Set<Integer>> sets = new ArrayList<>();
            for (int i = 0; i < numSets; i++) {
                Set<Integer> currentSet = new HashSet<>();
                for (int j = 0; j < 6; j++) {
                    if (in.hasNextInt()) {
                        currentSet.add(in.nextInt());
                    }
                }
                sets.add(currentSet);
            }

            // Compute and print the result
            out.println(solve(sets));

        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    /**
     * Solves the problem by finding the smallest integer X >= 0 such that X+1 
     * cannot be formed by the given sets.
     * 
     * A number can be formed if its digits can be mapped to distinct sets 
     * from the input list such that each digit exists in its assigned set.
     * 
     * The search space is limited to numbers with length equal to or less than 
     * the number of sets (e.g., for 1 set, check 1-9; for 2 sets, check 1-99, etc.).
     */
    private static int solve(List<Set<Integer>> sets) {
        int n = sets.size();

        // Iterate through lengths 1 to n
        for (int len = 1; len <= n; len++) {
            int start = (int) Math.pow(10, len - 1);
            int end = (int) Math.pow(10, len);

            // Check every number of this length
            for (int num = start; num < end; num++) {
                if (!canForm(num, sets)) {
                    // Found the first number that cannot be formed
                    return num - 1;
                }
            }
        }

        // If all numbers in the valid range are formable, return 0
        return 0;
    }

    /**
     * Checks if a number can be formed by mapping its digits to distinct sets.
     */
    private static boolean canForm(int number, List<Set<Integer>> sets) {
        // Extract digits. 
        // We store them in an array. The order (LSB first) is handled by the backtracking logic.
        int temp = number;
        int len = 0;
        int[] digits = new int[3]; // Maximum 3 digits for N=3

        while (temp > 0) {
            digits[len++] = temp % 10;
            temp /= 10;
        }

        // Use backtracking to find a valid assignment
        return backtrack(digits, len, 0, new boolean[sets.size()], sets);
    }

    /**
     * Recursive backtracking method to match digits to sets.
     * 
     * @param digits Array of digits to match
     * @param totalDigits Total number of digits in the number
     * @param digitIdx Current index in the digits array being processed
     * @param usedSets Boolean array tracking which sets are currently used
     * @param sets List of available sets
     * @return true if a valid mapping is found, false otherwise
     */
    private static boolean backtrack(int[] digits, int totalDigits, int digitIdx, boolean[] usedSets, List<Set<Integer>> sets) {
        // Base case: all digits have been successfully mapped to distinct sets
        if (digitIdx == totalDigits) {
            return true;
        }

        int digit = digits[digitIdx];

        // Try to map the current digit to any available set
        for (int i = 0; i < sets.size(); i++) {
            if (!usedSets[i]) {
                if (sets.get(i).contains(digit)) {
                    usedSets[i] = true; // Mark set as used

                    // Recurse to check the next digit
                    if (backtrack(digits, totalDigits, digitIdx + 1, usedSets, sets)) {
                        return true;
                    }

                    usedSets[i] = false; // Backtrack: unmark set for next iteration
                }
            }
        }

        return false;
    }
}

import java.io.*;
import java.util.*;

/**
 * Refactored solution to find the largest number X such that all numbers 1..X
 * can be formed using digits from n given sets.
 * 
 * Refactoring Improvements:
 * 1. Generalized Logic: Replaced hardcoded if-else blocks for n=1, 2, 3 with a 
 *    generic algorithm that works for any number of sets.
 * 2. Separation of Concerns: Moved logic into specific methods (canForm, getPermutations).
 * 3. Robust Input Handling: Improved FastScanner to handle exceptions gracefully.
 * 4. Resource Management: Properly managed PrintWriter and BufferedReader.
 * 5. Readability: Used descriptive variable names and added comments.
 */
public class DigitFormingSolver {

    // FastScanner class for efficient input reading
    static class FastScanner {
        BufferedReader br;
        StringTokenizer st;

        public FastScanner(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            String s = next();
            if (s == null) throw new RuntimeException("Unexpected end of input");
            return Integer.parseInt(s);
        }
    }

    public static void main(String[] args) {
        // Initialize output writer
        PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out));
        FastScanner sc = new FastScanner(System.in);

        try {
            // Read number of sets
            String nStr = sc.next();
            if (nStr == null) return;
            int n = Integer.parseInt(nStr);

            // Read the sets of digits
            // Original code assumed 6 digits per set
            List<Set<Integer>> sets = new ArrayList<>();
            int digitsPerSet = 6; 

            for (int i = 0; i < n; i++) {
                Set<Integer> set = new HashSet<>();
                for (int j = 0; j < digitsPerSet; j++) {
                    set.add(sc.nextInt());
                }
                sets.add(set);
            }

            // Find the smallest number that cannot be formed
            // We iterate starting from 1.
            // Since n is small (1-3), the answer is bounded (max 999).
            // We use a safe upper bound.
            int result = 0;
            for (int i = 1; i <= 10000; i++) {
                if (!canForm(i, sets)) {
                    result = i - 1;
                    break;
                }
            }

            out.println(result);

        } catch (Exception e) {
            e.printStackTrace();
        } finally {
            out.flush();
            out.close();
        }
    }

    /**
     * Determines if a number can be formed using the available digit sets.
     * Logic: Each digit of the number must be assigned to a distinct set
     * such that the digit exists in that set.
     */
    private static boolean canForm(int num, List<Set<Integer>> sets) {
        String s = String.valueOf(num);
        int len = s.length();

        // If the number has more digits than available sets, it's impossible
        // (Assuming 1-to-1 mapping constraint implied by original logic for n >= 2)
        if (len > sets.size()) {
            return false;
        }

        // We need to check if there is a valid assignment of digits to sets.
        // Since the order of digits in the number is fixed (e.g., tens, units),
        // but the sets are interchangeable, we check all permutations of the sets.
        // If any permutation allows the digits to be covered, the number is formable.

        List<List<Set<Integer>>> permutations = getPermutations(sets);

        for (List<Set<Integer>> perm : permutations) {
            boolean match = true;
            for (int k = 0; k < len; k++) {
                int digit = s.charAt(k) - '0';
                // Check if the k-th digit is present in the k-th set of the permutation
                if (!perm.get(k).contains(digit)) {
                    match = false;
                    break;
                }
            }
            if (match) {
                return true;
            }
        }

        return false;
    }

    /**
     * Generates all permutations of a list.
     */
    private static <T> List<List<T>> getPermutations(List<T> list) {
        List<List<T>> result = new ArrayList<>();
        if (list.isEmpty()) {
            result.add(new ArrayList<>());
            return result;
        }
        permute(list, 0, result);
        return result;
    }

    private static <T> void permute(List<T> list, int k, List<List<T>> result) {
        if (k == list.size() - 1) {
            result.add(new ArrayList<>(list));
        } else {
            for (int i = k; i < list.size(); i++) {
                Collections.swap(list, i, k);
                permute(list, k + 1, result);
                Collections.swap(list, i, k); // backtrack
            }
        }
    }
}

import java.util.ArrayList;
import java.util.Collections;
import java.util.HashSet;
import java.util.List;
import java.util.Scanner;
import java.util.Set;

/**
 * Refactored version of B_444_2.
 * 
 * Key Improvements:
 * 1. Replaced HashMap<Integer, Boolean> with Set<Integer> for O(1) lookups and semantic clarity.
 * 2. Fixed a critical bug where String.valueOf(n) caused IndexOutOfBoundsException for numbers < 100.
 * 3. Extracted repetitive input reading and number-checking logic into focused methods.
 * 4. Used backtracking to cleanly handle digit-to-cube assignment for 1, 2, or 3 cubes.
 * 5. Added try-with-resources for automatic Scanner cleanup.
 * 6. Applied descriptive naming and added JavaDoc for maintainability.
 */
public class CubeNumberCalculator {

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            if (!scanner.hasNextInt()) {
                return;
            }
            int numCubes = scanner.nextInt();
            List<Set<Integer>> cubeFaces = readCubeFaces(scanner, numCubes);

            int result = findMaxConsecutiveNumber(numCubes, cubeFaces);
            System.out.println(result);
        }
    }

    /**
     * Reads the 6 face values for each cube from the scanner.
     */
    private static List<Set<Integer>> readCubeFaces(Scanner scanner, int numCubes) {
        List<Set<Integer>> cubes = new ArrayList<>();
        for (int i = 0; i < numCubes; i++) {
            Set<Integer> faces = new HashSet<>();
            for (int j = 0; j < 6; j++) {
                faces.add(scanner.nextInt());
            }
            cubes.add(faces);
        }
        return cubes;
    }

    /**
     * Finds the maximum consecutive integer starting from 1 that can be formed.
     * Stops and returns the last successfully formed number when a gap is encountered.
     */
    private static int findMaxConsecutiveNumber(int numCubes, List<Set<Integer>> cubes) {
        int maxNumber = 0;
        for (int n = 1; n <= 999; n++) {
            if (!canFormNumber(n, numCubes, cubes)) {
                break;
            }
            maxNumber = n;
        }
        return maxNumber;
    }

    /**
     * Determines if a number can be formed using the available cubes.
     * - For 1 cube: all digits must be present on that single cube.
     * - For 2+ cubes: each digit must be assigned to a distinct cube.
     */
    private static boolean canFormNumber(int number, int numCubes, List<Set<Integer>> cubes) {
        List<Integer> digits = extractDigits(number);

        // Special case: single cube must contain all digits
        if (numCubes == 1) {
            Set<Integer> faces = cubes.get(0);
            for (int d : digits) {
                if (!faces.contains(d)) {
                    return false;
                }
            }
            return true;
        }

        // Multiple cubes: need distinct cubes for each digit
        if (digits.size() > numCubes) {
            return false;
        }
        return tryAssignDigits(digits, 0, new boolean[numCubes], cubes);
    }

    /**
     * Safely extracts digits from an integer in left-to-right order.
     */
    private static List<Integer> extractDigits(int number) {
        List<Integer> digits = new ArrayList<>();
        if (number == 0) {
            digits.add(0);
        } else {
            while (number > 0) {
                digits.add(number % 10);
                number /= 10;
            }
            Collections.reverse(digits);
        }
        return digits;
    }

    /**
     * Backtracking helper to assign digits to distinct cubes.
     */
    private static boolean tryAssignDigits(List<Integer> digits, int digitIndex, boolean[] usedCubes, List<Set<Integer>> cubes) {
        if (digitIndex == digits.size()) {
            return true;
        }

        int currentDigit = digits.get(digitIndex);
        for (int i = 0; i < cubes.size(); i++) {
            if (!usedCubes[i] && cubes.get(i).contains(currentDigit)) {
                usedCubes[i] = true;
                if (tryAssignDigits(digits, digitIndex + 1, usedCubes, cubes)) {
                    return true;
                }
                usedCubes[i] = false; // Backtrack
            }
        }
        return false;
    }
}

import java.util.Scanner;
import java.util.Set;
import java.util.HashSet;

/**
 * Refactored version of probB.
 * 
 * This program reads n dice, generates all possible integers that can be formed
 * by concatenating digits from the dice (using each die at most once per number),
 * and finds the longest consecutive sequence of integers starting from 1.
 * 
 * Key Improvements:
 * 1.  **Readability & Maintainability**: Replaced nested loops and magic numbers 
 *     with a recursive helper method and a constant for dice faces.
 * 2.  **Logic Generalization**: The original code had hardcoded logic for n=1, n=2, 
 *     and n=3. The refactored version uses a generic backtracking approach that 
 *     works for any n (within integer limits), making it scalable.
 * 3.  **Data Structures**: Used a HashSet to automatically handle duplicates and 
 *     improve lookup performance.
 * 4.  **Robustness**: Added overflow checks and input validation.
 */
public class probB {

    // Constant for the number of faces on a standard die
    private static final int DICE_FACES = 6;

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        // Check if input exists
        if (!sc.hasNextInt()) {
            sc.close();
            return;
        }

        int n = sc.nextInt();
        int[][] dice = new int[n][DICE_FACES];

        // Read dice faces
        for (int i = 0; i < n; i++) {
            for (int k = 0; k < DICE_FACES; k++) {
                if (sc.hasNextInt()) {
                    dice[i][k] = sc.nextInt();
                }
            }
        }

        // Set to store unique generated numbers
        Set<Integer> possibleNumbers = new HashSet<>();
        boolean[] usedDice = new boolean[n];

        // Generate all possible numbers
        // We iterate through each die to start a number (first digit)
        for (int i = 0; i < n; i++) {
            usedDice[i] = true;
            for (int face : dice[i]) {
                // Start recursion with the first digit
                generateNumbers(face, n, dice, usedDice, possibleNumbers);
            }
            usedDice[i] = false;
        }

        // Find the longest consecutive sequence starting from 1
        int maxConsecutive = 0;
        int current = 1;

        // Check 1, 2, 3... sequentially
        while (possibleNumbers.contains(current)) {
            maxConsecutive = current;
            current++;
        }

        System.out.println(maxConsecutive);

        sc.close();
    }

    /**
     * Recursively generates all valid numbers by appending faces from unused dice.
     * This approach covers all permutations of distinct dice and all face combinations.
     * 
     * @param currentVal The number formed by the sequence of digits so far.
     * @param n The total number of dice available.
     * @param dice The 2D array of dice faces.
     * @param usedDice Boolean array tracking which dice indices have been used in the current sequence.
     * @param numbers The Set to store all generated unique numbers.
     */
    private static void generateNumbers(int currentVal, int n, int[][] dice, boolean[] usedDice, Set<Integer> numbers) {
        // Add the current number to the set
        numbers.add(currentVal);

        // Attempt to extend the number by appending a face from an unused die
        for (int i = 0; i < n; i++) {
            if (!usedDice[i]) {
                usedDice[i] = true;
                // Iterate through all faces of the chosen die
                for (int face : dice[i]) {
                    // Calculate next value. 
                    // Use long to prevent overflow before casting, ensuring safety.
                    long nextValLong = (long) currentVal * 10 + face;
                    if (nextValLong <= Integer.MAX_VALUE) {
                        generateNumbers((int) nextValLong, n, dice, usedDice, numbers);
                    }
                }
                usedDice[i] = false; // Backtrack to allow this die to be used in other sequences
            }
        }
    }
}

import java.io.PrintWriter;
import java.util.Scanner;

/**
 * Finds the smallest number (1 to 3 digits) such that all its digits appear
 * in exactly one common row of the input matrix. Returns (number - 1).
 */
public class Main {

    public static void main(String[] args) {
        // Use try-with-resources to ensure streams are properly closed
        try (Scanner scanner = new Scanner(System.in);
             PrintWriter out = new PrintWriter(System.out)) {

            if (!scanner.hasNextInt()) {
                return;
            }
            int n = scanner.nextInt();

            // Precompute digit presence: hasDigit[row][digit]
            // Using a boolean matrix provides O(1) lookups and reduces memory overhead
            boolean[][] hasDigit = new boolean[n][10];
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < 6; j++) {
                    int val = scanner.nextInt();
                    // Safeguard against out-of-bounds, though problem constraints imply 0-9
                    if (val >= 0 && val <= 9) {
                        hasDigit[i][val] = true;
                    }
                }
            }

            out.print(findSmallestValidNumber(n, hasDigit));
        }
    }

    /**
     * Searches for the smallest valid number following the original search order:
     * 1-digit (1-9) -> 2-digit (10-99) -> 3-digit (100-999)
     */
    private static int findSmallestValidNumber(int n, boolean[][] hasDigit) {
        // Check 1-digit numbers
        for (int x = 1; x <= 9; x++) {
            if (isValid(n, hasDigit, x)) {
                return x - 1;
            }
        }

        // Check 2-digit numbers
        for (int x = 1; x <= 9; x++) {
            for (int y = 0; y <= 9; y++) {
                if (isValid(n, hasDigit, x, y)) {
                    return 10 * x + y - 1;
                }
            }
        }

        // Check 3-digit numbers
        for (int x = 1; x <= 9; x++) {
            for (int y = 0; y <= 9; y++) {
                for (int z = 0; z <= 9; z++) {
                    if (isValid(n, hasDigit, x, y, z)) {
                        return 100 * x + 10 * y + z - 1;
                    }
                }
            }
        }

        // Fallback: Should not be reached given typical problem constraints
        return -1;
    }

    /**
     * Validates whether a combination of digits satisfies the original condition:
     * "There do not exist two distinct rows where one contains the first digit
     * and another contains the second digit (and so on for more digits)."
     *
     * This is logically equivalent to requiring that ALL digits in the combination
     * appear in exactly the same single row index.
     */
    private static boolean isValid(int n, boolean[][] hasDigit, int... digits) {
        Integer commonRow = null;

        for (int d : digits) {
            int rowIdx = -1;
            // Find which row contains this digit
            for (int r = 0; r < n; r++) {
                if (hasDigit[r][d]) {
                    // If digit appears in more than one row, the combination is invalid
                    if (rowIdx != -1) {
                        return false;
                    }
                    rowIdx = r;
                }
            }
            // If digit is not found in any row, combination is invalid
            if (rowIdx == -1) {
                return false;
            }
            // Ensure all digits share the exact same row index
            if (commonRow == null) {
                commonRow = rowIdx;
            } else if (!commonRow.equals(rowIdx)) {
                return false;
            }
        }
        return true;
    }
}

import java.io.*;
