/**
 * Refactored solution for problem B887.
 * Improves maintainability by extracting logic, fixing a critical array bounds bug,
 * using standard I/O practices, and applying clear naming conventions.
 */
public class Main {
    private static final int MAX_CHECK = 1001; // Covers indices 0 to 1000 safely
    private static final int DIGITS_PER_ROW = 6;

    public static void main(String[] args) {
        solve();
    }

    private static void solve() {
        // Use try-with-resources for automatic and safe resource cleanup
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
             PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out))) {

            FastScanner scanner = new FastScanner(reader);
            int n = scanner.nextInt();

            int[][] numbers = new int[n][DIGITS_PER_ROW];
            boolean[] reachable = new boolean[MAX_CHECK];

            // Read input and mark single digits as reachable
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < DIGITS_PER_ROW; j++) {
                    numbers[i][j] = scanner.nextInt();
                    reachable[numbers[i][j]] = true;
                }
            }

            // Generate and mark all valid 2-digit combinations
            markTwoDigitCombinations(numbers, reachable);

            // Generate and mark all valid 3-digit combinations
            markThreeDigitCombinations(numbers, reachable);

            // Count the longest consecutive sequence of reachable numbers starting from 1
            int consecutiveCount = 0;
            for (int i = 1; i < MAX_CHECK; i++) {
                if (reachable[i]) {
                    consecutiveCount++;
                } else {
                    break;
                }
            }

            out.println(consecutiveCount);
            out.flush();

        } catch (IOException e) {
            System.err.println("I/O error occurred: " + e.getMessage());
        }
    }

    /**
     * Marks all valid 2-digit numbers formed by picking one digit from each of two different rows.
     */
    private static void markTwoDigitCombinations(int[][] numbers, boolean[] reachable) {
        int n = numbers.length;
        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                for (int d1 : numbers[i]) {
                    for (int d2 : numbers[j]) {
                        reachable[d1 * 10 + d2] = true;
                        reachable[d2 * 10 + d1] = true;
                    }
                }
            }
        }
    }

    /**
     * Marks all valid 3-digit numbers formed by picking one digit from each of three different rows.
     */
    private static void markThreeDigitCombinations(int[][] numbers, boolean[] reachable) {
        int n = numbers.length;
        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                for (int k = j + 1; k < n; k++) {
                    for (int d1 : numbers[i]) {
                        for (int d2 : numbers[j]) {
                            for (int d3 : numbers[k]) {
                                markPermutations(d1, d2, d3, reachable);
                            }
                        }
                    }
                }
            }
        }
    }

    /**
     * Marks all 6 permutations of three digits as reachable 3-digit numbers.
     */
    private static void markPermutations(int d1, int d2, int d3, boolean[] reachable) {
        reachable[d1 * 100 + d2 * 10 + d3] = true;
        reachable[d1 * 100 + d3 * 10 + d2] = true;
        reachable[d2 * 100 + d1 * 10 + d3] = true;
        reachable[d2 * 100 + d3 * 10 + d1] = true;
        reachable[d3 * 100 + d1 * 10 + d2] = true;
        reachable[d3 * 100 + d2 * 10 + d1] = true;
    }

    /**
     * A robust and maintainable FastScanner using BufferedReader and StringTokenizer.
     */
    private static class FastScanner {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastScanner(BufferedReader reader) {
            this.reader = reader;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input", e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            String token = next();
            if (token == null) throw new RuntimeException("Unexpected end of input");
            return Integer.parseInt(token);
        }
    }
}

import java.io.InputStream;
import java.io.OutputStream;
import java.io.IOException;
import java.io.PrintWriter;
import java.util.HashSet;
import java.util.InputMismatchException;
import java.util.List;
import java.util.ArrayList;

public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        Solver solver = new Solver();
        solver.solve(in, out);
        out.close();
    }

    static class Solver {
        public void solve(InputReader in, PrintWriter out) {
            int n = in.nextInt();
            List<HashSet<Integer>> sets = new ArrayList<>();

            // Read n sets, each containing 6 integers
            for (int i = 0; i < n; i++) {
                HashSet<Integer> set = new HashSet<>();
                for (int j = 0; j < 6; j++) {
                    set.add(in.nextInt());
                }
                sets.add(set);
            }

            int ctr = 0;
            // Process 1-digit, 2-digit, and 3-digit numbers sequentially
            int[] maxNumbers = {9, 99, 999};
            for (int k = 0; k < n && k < 3; k++) {
                int start = k == 0 ? 1 : maxNumbers[k - 1] + 1;
                int end = maxNumbers[k];

                for (int i = start; i <= end; i++) {
                    if (!canForm(i, sets)) {
                        break;
                    }
                    ctr++;
                }
            }
            out.println(ctr);
        }

        /**
         * Checks if a number can be formed by assigning each of its digits
         * to a distinct set from the provided list of sets.
         */
        private boolean canForm(int number, List<HashSet<Integer>> sets) {
            int[] digits = new int[3];
            int len = 0;
            int temp = number;

            // Extract digits using integer arithmetic (more efficient than string conversion)
            while (temp > 0) {
                digits[len++] = temp % 10;
                temp /= 10;
            }

            boolean[] used = new boolean[sets.size()];
            return assignDigits(digits, 0, sets, used);
        }

        /**
         * Recursively attempts to assign each digit to an unused set that contains it.
         */
        private boolean assignDigits(int[] digits, int idx, List<HashSet<Integer>> sets, boolean[] used) {
            if (idx == digits.length) {
                return true;
            }

            for (int i = 0; i < sets.size(); i++) {
                if (!used[i] && sets.get(i).contains(digits[idx])) {
                    used[i] = true;
                    if (assignDigits(digits, idx + 1, sets, used)) {
                        return true;
                    }
                    used[i] = false; // Backtrack
                }
            }
            return false;
        }
    }

    // Standard fast I/O reader (preserved for performance)
    static class InputReader {
        private final InputStream stream;
        private final byte[] buf = new byte[8192];
        private int curChar;
        private int snumChars;

        public InputReader(InputStream st) {
            this.stream = st;
        }

        public int read() {
            if (snumChars == -1)
                throw new InputMismatchException();
            if (curChar >= snumChars) {
                curChar = 0;
                try {
                    snumChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (snumChars <= 0)
                    return -1;
            }
            return buf[curChar++];
        }

        public int nextInt() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            int res = 0;
            do {
                res *= 10;
                res += c - '0';
                c = read();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }
    }
}

import java.io.BufferedReader;
