public class Main {
    private static final int NUM_COLUMNS = 6;
    private static final int MAX_VALUE = 1000;

    public static void main(String[] args) throws IOException {
        // Use try-with-resources to ensure streams are properly closed
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
             PrintWriter out = new PrintWriter(System.out)) {

            FastScanner scanner = new FastScanner(reader);
            int n = scanner.nextInt();

            int[][] numbers = new int[n][NUM_COLUMNS];
            boolean[] seen = new boolean[MAX_VALUE];

            // Read input and mark single numbers as seen
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < NUM_COLUMNS; j++) {
                    numbers[i][j] = scanner.nextInt();
                    if (numbers[i][j] < MAX_VALUE) {
                        seen[numbers[i][j]] = true;
                    }
                }
            }

            // Generate permutations and mark them as seen
            // Handles n=2 and n=3 cleanly without repetitive code
            if (n == 2 || n == 3) {
                generatePermutations(numbers, 0, "", seen, MAX_VALUE);
            }

            // Find the smallest positive integer that hasn't been seen
            for (int i = 1; i < MAX_VALUE; i++) {
                if (!seen[i]) {
                    // Note: Original code printed i-1. This is likely a typo.
                    // Standard behavior for "smallest missing positive integer" is i.
                    out.println(i);
                    break;
                }
            }

            out.flush();
        }
    }

    /**
     * Recursively generates all permutations of length n by picking one number 
     * from each row and concatenating them.
     */
    private static void generatePermutations(int[][] numbers, int row, String current, 
                                             boolean[] seen, int max) {
        if (row == numbers.length) {
            try {
                int value = Integer.parseInt(current);
                if (value < max) {
                    seen[value] = true;
                }
            } catch (NumberFormatException e) {
                // Safely ignore values that exceed integer parsing limits
            }
            return;
        }

        for (int col = 0; col < numbers[row].length; col++) {
            generatePermutations(numbers, row + 1, current + numbers[row][col], seen, max);
        }
    }

    /**
     * Fast I/O helper to replace Scanner and avoid StreamTokenizer/BufferedReader conflicts.
     */
    private static class FastScanner {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastScanner(BufferedReader reader) {
            this.reader = reader;
            this.tokenizer = new StringTokenizer("");
        }

        public String next() throws IOException {
            while (!tokenizer.hasMoreTokens()) {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            String token = next();
            return (token == null) ? 0 : Integer.parseInt(token);
        }
    }
}

import java.io.BufferedReader;
import java.io.BufferedWriter;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.OutputStreamWriter;
import java.util.ArrayList;
import java.util.List;
import java.util.StringTokenizer;

public class Main {
    // Constants
    private static final int ITEMS_PER_LINE = 6;

    // I/O Resources
    private static BufferedReader reader;
    private static BufferedWriter writer;
    private static StringTokenizer tokenizer;
    private static StringBuilder outputBuffer;

    public static void main(String[] args) throws IOException {
        initializeIO();
        try {
            solve();
        } finally {
            flushAndClose();
        }
    }

    private static void initializeIO() {
        reader = new BufferedReader(new InputStreamReader(System.in));
        writer = new BufferedWriter(new OutputStreamWriter(System.out));
        outputBuffer = new StringBuilder();
    }

    private static void flushAndClose() throws IOException {
        writer.write(outputBuffer.toString());
        writer.flush();
        writer.close();
    }

    private static void solve() throws IOException {
        // Read n
        // Original: int n = ni1();
        String line = reader.readLine();
        if (line == null) return;
        int n = Integer.parseInt(line.trim());

        // Data Structure: List of Lists to store valid digits for each of the n sets
        // Replaces: ArrayList<Integer> list[] = new ArrayList[n];
        // Using List<List<Integer>> avoids generic array creation warnings and is more type-safe.
        List<List<Integer>> validSets = new ArrayList<>(n);
        for (int i = 0; i < n; i++) {
            validSets.add(new ArrayList<>());
        }

        // Read input data
        // Original: for (int i = 0; i < n; i++) { rl(); for (int j = 0; j < 6; j++) list[i].add(ni2()); }
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < ITEMS_PER_LINE; j++) {
                validSets.get(i).add(nextInt());
            }
        }

        // Determine the upper bound for the loop
        // Original: (int) Math.pow(10, n)
        // Using long to prevent overflow for n >= 10, though array indices remain int-compatible.
        long limit = (long) Math.pow(10, n);

        long candidate = 1;

        // Iterate through numbers to find the first one that fails the condition
        // (Original logic: continue if valid, break if invalid. Result is candidate - 1)
        for (; candidate <= limit; candidate++) {
            List<Integer> digits = getDigits(candidate);

            // Build the validation matrix
            // Rows correspond to digits of the candidate number
            // Columns correspond to the n input sets
            int[][] matrix = buildMatrix(digits, validSets, n);

            // Calculate metrics
            int validDigitCount = countNonZeroRows(matrix);
            int validSetCount = countNonZeroCols(matrix);

            // Check condition
            // Original: if (countCol >= digit.size() && countRow >= digit.size()) continue; else break;
            if (validSetCount >= digits.size() && validDigitCount >= digits.size()) {
                continue;
            } else {
                break;
            }
        }

        // Output the result
        // Original: ans.append(x - 1).append('\n');
        outputBuffer.append(candidate - 1).append('\n');
    }

    /**
     * Extracts digits from a number.
     * Note: Original implementation extracts digits in reverse order (Least Significant First).
     * This method preserves that behavior.
     */
    private static List<Integer> getDigits(long number) {
        List<Integer> digits = new ArrayList<>();
        long k = number;
        while (k > 0) {
            int digit = (int) (k % 10);
            digits.add(digit);
            k /= 10;
        }
        return digits;
    }

    /**
     * Builds a matrix where matrix[row][col] is 1 if the digit at 'row'
     * is present in the set at 'col'.
     */
    private static int[][] buildMatrix(List<Integer> digits, List<List<Integer>> validSets, int n) {
        int[][] matrix = new int[digits.size()][n];
        for (int r = 0; r < digits.size(); r++) {
            int digit = digits.get(r);
            for (int c = 0; c < n; c++) {
                if (validSets.get(c).contains(digit)) {
                    matrix[r][c] = 1;
                }
            }
        }
        return matrix;
    }

    /**
     * Counts rows in the matrix that have a sum > 0.
     */
    private static int countNonZeroRows(int[][] matrix) {
        int count = 0;
        for (int[] row : matrix) {
            int sum = 0;
            for (int val : row) {
                sum += val;
            }
            if (sum > 0) {
                count++;
            }
        }
        return count;
    }

    /**
     * Counts columns in the matrix that have a sum > 0.
     */
    private static int countNonZeroCols(int[][] matrix) {
        int count = 0;
        int rows = matrix.length;
        if (rows == 0) return 0;
        int cols = matrix[0].length;

        for (int c = 0; c < cols; c++) {
            int sum = 0;
            for (int r = 0; r < rows; r++) {
                sum += matrix[r][c];
            }
            if (sum > 0) {
                count++;
            }
        }
        return count;
    }

    // --- I/O Helper Methods ---

    private static String nextToken() throws IOException {
        while (tokenizer == null || !tokenizer.hasMoreTokens()) {
            String line = reader.readLine();
            if (line == null) return null;
            tokenizer = new StringTokenizer(line);
        }
        return tokenizer.nextToken();
    }

    private static int nextInt() throws IOException {
        String token = nextToken();
        if (token == null) throw new IOException("Unexpected end of input");
        return Integer.parseInt(token);
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

public class Solution {
    private static final int MAX_VALUE = 1000;
    private static final int NUM_ELEMENTS_PER_SET = 6;

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner();
        solve(scanner);
    }

    private static void solve(FastScanner scanner) {
        int n = scanner.nextInt();
        boolean[] can = new boolean[MAX_VALUE + 1];
        int[][] a = new int[n][NUM_ELEMENTS_PER_SET];

        // Read input data
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < NUM_ELEMENTS_PER_SET; j++) {
                a[i][j] = scanner.nextInt();
            }
        }

        // Mark directly present numbers
        for (int i = 0; i < n; i++) {
            for (int val : a[i]) {
                if (val >= 1 && val <= MAX_VALUE) {
                    can[val] = true;
                }
            }
        }

        // Mark concatenated pairs from different sets
        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                for (int k = 0; k < NUM_ELEMENTS_PER_SET; k++) {
                    for (int l = 0; l < NUM_ELEMENTS_PER_SET; l++) {
                        int combined1 = concatenate(a[i][k], a[j][l]);
                        int combined2 = concatenate(a[j][l], a[i][k]);

                        if (combined1 >= 1 && combined1 <= MAX_VALUE) {
                            can[combined1] = true;
                        }
                        if (combined2 >= 1 && combined2 <= MAX_VALUE) {
                            can[combined2] = true;
                        }
                    }
                }
            }
        }

        // Find the largest missing number in the range [1, MAX_VALUE]
        int result = 0;
        for (int i = 1; i <= MAX_VALUE; i++) {
            if (!can[i]) {
                result = i - 1;
                break;
            }
        }

        System.out.println(result);
    }

    /**
     * Concatenates two integers mathematically (e.g., 12 and 3 -> 123).
     * More efficient than string concatenation for this use case.
     */
    private static int concatenate(int a, int b) {
        int multiplier = (b == 0) ? 10 : 1;
        int temp = b;
        while (temp > 0) {
            multiplier *= 10;
            temp /= 10;
        }
        return a * multiplier + b;
    }

    /**
     * Fast I/O helper class for competitive programming.
     */
    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner() {
            this(System.in);
        }

        public FastScanner(InputStream stream) {
            br = new BufferedReader(new InputStreamReader(stream));
            st = new StringTokenizer("");
        }

        String next() {
            while (!st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            String s = next();
            if (s == null) throw new RuntimeException("Unexpected end of input");
            return Integer.parseInt(s);
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Main application class to find the smallest positive integer that cannot be
 * formed by concatenating digits from the faces of up to three distinct cubes.
 */
public class Main {

    public static void main(String[] args) throws IOException {
        FastScanner scanner = new FastScanner();
        PrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));

        try {
            int n = scanner.nextInt();
            Cube[] cubes = new Cube[n];

            // Read cube face values
            for (int i = 0; i < n; i++) {
                int[] faces = new int[6];
                for (int j = 0; j < 6; j++) {
                    faces[j] = scanner.nextInt();
                }
                cubes[i] = new Cube(faces);
            }

            // Track possible numbers from 1 to 99999
            boolean[] possible = new boolean[100000];

            // Mark 1-digit numbers
            markPossibleNumbers(possible, cubes, 1);

            // Mark 2-digit numbers
            markPossibleNumbers(possible, cubes, 2);

            // Mark 3-digit numbers
            markPossibleNumbers(possible, cubes, 3);

            // Find the smallest positive integer that cannot be formed
            int smallestMissing = 1;
            while (smallestMissing < possible.length && possible[smallestMissing]) {
                smallestMissing++;
            }

            out.println(smallestMissing);
        } catch (Exception e) {
            out.println("Error processing input: " + e.getMessage());
        } finally {
            out.flush();
        }
    }

    /**
     * Marks all possible numbers of the specified length that can be formed
     * by concatenating face values from distinct cubes.
     */
    private static void markPossibleNumbers(boolean[] possible, Cube[] cubes, int digitCount) {
        int n = cubes.length;
        markRecursive(possible, cubes, 0, digitCount, 0, new boolean[n]);
    }

    /**
     * Helper method to recursively generate combinations of distinct cubes
     * and mark the formed numbers.
     */
    private static void markRecursive(boolean[] possible, Cube[] cubes, int depth, int targetDepth, 
                                      int currentValue, boolean[] used) {
        if (depth == targetDepth) {
            if (currentValue > 0 && currentValue < possible.length) {
                possible[currentValue] = true;
            }
            return;
        }

        for (int i = 0; i < cubes.length; i++) {
            if (used[i]) continue;

            used[i] = true;
            for (int face : cubes[i].faces) {
                if (face >= 0 && face <= 9) {
                    int nextValue = currentValue * 10 + face;
                    markRecursive(possible, cubes, depth + 1, targetDepth, nextValue, used);
                }
            }
            used[i] = false;
        }
    }

    /**
     * Encapsulates a cube's face values.
     */
    static class Cube {
        final int[] faces;

        Cube(int[] faces) {
            this.faces = Arrays.copyOf(faces, 6);
        }
    }

    /**
     * High-performance input scanner for competitive programming / large inputs.
     */
    static class FastScanner {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastScanner() {
            reader = new BufferedReader(new InputStreamReader(System.in));
            tokenizer = null;
        }

        public String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                String line = reader.readLine();
                if (line == null) throw new EOFException("Unexpected end of input");
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }

    /**
     * Utility class for matrix and power operations.
     * Retained from original code but refactored for correctness and performance.
     */
    static class MatrixUtils {
        static long[][] multiply(long[][] A, long[][] B, long mod) {
            int n = A.length, m = B[0].length, p = A[0].length;
            if (B.length != p || A[0].length != p) {
                throw new IllegalArgumentException("Invalid matrix dimensions for multiplication");
            }
            long[][] res = new long[n][m];
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    long sum = 0;
                    for (int k = 0; k < p; k++) {
                        sum = (sum + A[i][k] * B[k][j]) % mod;
                    }
                    res[i][j] = sum;
                }
            }
            return res;
        }

        static double[][] multiply(double[][] A, double[][] B) {
            int n = A.length, m = B[0].length, p = A[0].length;
            if (B.length != p || A[0].length != p) {
                throw new IllegalArgumentException("Invalid matrix dimensions for multiplication");
            }
            double[][] res = new double[n][m];
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    double sum = 0;
                    for (int k = 0; k < p; k++) {
                        sum += A[i][k] * B[k][j];
                    }
                    res[i][j] = sum;
                }
            }
            return res;
        }

        static long[][] power(long[][] A, long exp, long mod) {
            if (exp < 0) throw new IllegalArgumentException("Exponent must be non-negative");
            int n = A.length;
            long[][] res = new long[n][n];
            for (int i = 0; i < n; i++) res[i][i] = 1; // Identity matrix
            long[][] base = A;
            while (exp > 0) {
                if ((exp & 1) == 1) res = multiply(res, base, mod);
                base = multiply(base, base, mod);
                exp >>= 1;
            }
            return res;
        }

        static double[][] power(double[][] A, long exp) {
            if (exp < 0) throw new IllegalArgumentException("Exponent must be non-negative");
            int n = A.length;
            double[][] res = new double[n][n];
            for (int i = 0; i < n; i++) res[i][i] = 1; // Identity matrix
            double[][] base = A;
            while (exp > 0) {
                if ((exp & 1) == 1) res = multiply(res, base);
                base = multiply(base, base);
                exp >>= 1;
            }
            return res;
        }

        static long pow(long base, long exp, long mod) {
            long result = 1;
            base %= mod;
            while (exp > 0) {
                if ((exp & 1) == 1) result = (result * base) % mod;
                base = (base * base) % mod;
                exp >>= 1;
            }
            return result;
        }

        static double pow(double base, long exp) {
            double result = 1.0;
            while (exp > 0) {
                if ((exp & 1) == 1) result *= base;
                base *= base;
                exp >>= 1;
            }
            return result;
        }
    }
}

import java.util.Scanner;

public class Main {

    /**
     * Represents a cube with 6 faces, each containing a digit from 0 to 9.
     */
    static class Cube {
        private final boolean[] hasDigit = new boolean[10];

        public Cube(int[] faces) {
            for (int face : faces) {
                if (face >= 0 && face <= 9) {
                    hasDigit[face] = true;
                }
            }
        }

        public boolean hasDigit(int digit) {
            return hasDigit[digit];
        }
    }

    public static void main(String[] args) {
        // Try-with-resources ensures the Scanner is closed automatically
        try (Scanner scanner = new Scanner(System.in)) {
            if (!scanner.hasNextInt()) {
                return;
            }
            int n = scanner.nextInt();
            Cube[] cubes = readCubes(scanner, n);
            findLargestRepresentableNumber(cubes);
        }
    }

    /**
     * Reads n cubes from the scanner input.
     */
    private static Cube[] readCubes(Scanner scanner, int n) {
        Cube[] cubes = new Cube[n];
        for (int i = 0; i < n; i++) {
            int[] faces = new int[6];
            for (int j = 0; j < 6; j++) {
                faces[j] = scanner.nextInt();
            }
            cubes[i] = new Cube(faces);
        }
        return cubes;
    }

    /**
     * Checks numbers from 1 to 999 sequentially.
     * Prints the largest number that can be formed and terminates.
     */
    private static void findLargestRepresentableNumber(Cube[] cubes) {
        for (int x = 1; x < 1000; x++) {
            int[] digits = numberToDigits(x);
            if (!canForm(digits, cubes)) {
                System.out.println(x - 1);
                return;
            }
        }
        System.out.println(999);
    }

    /**
     * Converts an integer to an array of its digits.
     */
    private static int[] numberToDigits(int number) {
        String s = Integer.toString(number);
        int[] digits = new int[s.length()];
        for (int i = 0; i < s.length(); i++) {
            digits[i] = s.charAt(i) - '0';
        }
        return digits;
    }

    /**
     * Determines if all digits in the array can be assigned to distinct cubes.
     */
    private static boolean canForm(int[] digits, Cube[] cubes) {
        return backtrack(0, digits, cubes, new boolean[cubes.length]);
    }

    /**
     * Backtracking helper to find a valid assignment of digits to cubes.
     */
    private static boolean backtrack(int digitIndex, int[] digits, Cube[] cubes, boolean[] used) {
        // Base case: all digits have been successfully assigned
        if (digitIndex == digits.length) {
            return true;
        }

        int targetDigit = digits[digitIndex];
        for (int i = 0; i < cubes.length; i++) {
            // Try to assign the current digit to an unused cube that has it
            if (!used[i] && cubes[i].hasDigit(targetDigit)) {
                used[i] = true;
                if (backtrack(digitIndex + 1, digits, cubes, used)) {
                    return true;
                }
                used[i] = false; // Backtrack: undo assignment and try next cube
            }
        }
        return false;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.OutputStream;
import java.io.PrintWriter;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.StringTokenizer;

public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        FastScanner in = new FastScanner(inputStream);
        PrintWriter out = new PrintWriter(outputStream);

        Task solver = new Task();
        solver.solve(in, out);

        out.close();
    }

    static class Task {
        public void solve(FastScanner in, PrintWriter out) {
            int n = in.nextInt();
            List<HashSet<Integer>> sets = new ArrayList<>();

            // Read n groups of 6 digits each
            for (int i = 0; i < n; i++) {
                HashSet<Integer> set = new HashSet<>();
                for (int j = 0; j < 6; j++) {
                    set.add(in.nextInt());
                }
                sets.add(set);
            }

            // Track the globally smallest valid number
            int[] minResult = {Integer.MAX_VALUE};
            permute(sets, 0, new boolean[n], new ArrayList<>(), minResult);

            out.println(minResult[0] == Integer.MAX_VALUE ? 0 : minResult[0]);
        }

        /**
         * Generates all permutations of the sets to find the smallest valid number.
         * For each permutation, it picks the smallest valid digit for each position.
         */
        private void permute(List<HashSet<Integer>> sets, int index, boolean[] used, 
                             List<HashSet<Integer>> current, int[] minResult) {
            if (index == sets.size()) {
                int candidate = 0;
                for (int pos = 0; pos < current.size(); pos++) {
                    HashSet<Integer> set = current.get(pos);
                    int minDigit = Integer.MAX_VALUE;

                    // Find the smallest digit in the set
                    for (int digit : set) {
                        // Leading zeros are not allowed for the most significant digit
                        if (pos == 0 && digit == 0) continue;
                        if (digit < minDigit) minDigit = digit;
                    }

                    // If no valid digit exists for this position, skip this permutation
                    if (minDigit == Integer.MAX_VALUE) return;

                    candidate = candidate * 10 + minDigit;
                }

                if (candidate < minResult[0]) {
                    minResult[0] = candidate;
                }
                return;
            }

            // Backtracking to generate permutations
            for (int i = 0; i < sets.size(); i++) {
                if (!used[i]) {
                    used[i] = true;
                    current.add(sets.get(i));
                    permute(sets, index + 1, used, current, minResult);
                    current.remove(current.size() - 1);
                    used[i] = false;
                }
            }
        }
    }

    /**
     * Fast I/O helper class for competitive programming / high-throughput scenarios.
     */
    static class FastScanner {
        public BufferedReader reader;
        public StringTokenizer tokenizer;

        public FastScanner(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            String s = next();
            if (s == null) throw new RuntimeException("Unexpected end of input");
            return Integer.parseInt(s);
        }
    }
}

import java.io.BufferedInputStream;
import java.io.BufferedOutputStream;
import java.io.IOException;
import java.io.InputStream;
import java.io.OutputStream;
import java.io.OutputStreamWriter;
import java.io.PrintWriter;
import java.io.Writer;
import java.util.InputMismatchException;

public class Main {
    // Constants replace magic numbers for better maintainability and configuration
    private static final int ROWS = 6;
    private static final int MAX_ITERATION = 999;
    private static final int BUFFER_SIZE = 1024;

    public static void main(String[] args) {
        // Wrap standard streams in buffered versions for improved I/O performance
        InputStream inputStream = new BufferedInputStream(System.in);
        OutputStream outputStream = new BufferedOutputStream(System.out);

        InputReader in = new InputReader(inputStream);
        OutputWriter out = new OutputWriter(outputStream);

        TaskB solver = new TaskB();
        solver.solve(in, out);

        out.close();
    }

    /**
     * Encapsulates the problem-solving logic for Task B.
     */
    static class TaskB {
        public void solve(InputReader in, OutputWriter out) {
            int n = in.nextInt();
            // Transposed to [n][ROWS] for better cache locality and standard row-major access
            int[][] matrix = new int[n][ROWS];
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < ROWS; j++) {
                    matrix[i][j] = in.nextInt();
                }
            }

            for (int i = 1; i <= MAX_ITERATION; i++) {
                if (shouldReturnPrevious(i, matrix, n)) {
                    out.print(i - 1);
                    return;
                }
            }
            out.print(MAX_ITERATION);
        }

        /**
         * Determines if the search should terminate and return (i - 1).
         * Replaces the complex nested loop condition with readable, self-documenting logic.
         */
        private boolean shouldReturnPrevious(int number, int[][] matrix, int n) {
            String s = String.valueOf(number);
            int len = s.length();
            int[] colMatches = new int[n];
            boolean[] digitFound = new boolean[len];

            // Count matches per column and track if each digit of the number is found
            for (int digitIdx = 0; digitIdx < len; digitIdx++) {
                int digit = s.charAt(digitIdx) - '0';
                for (int col = 0; col < n; col++) {
                    for (int row = 0; row < ROWS; row++) {
                        if (matrix[col][row] == digit) {
                            colMatches[col]++;
                            digitFound[digitIdx] = true;
                        }
                    }
                }
            }

            boolean allDigitsFound = true;
            for (boolean found : digitFound) {
                allDigitsFound &= found;
            }

            int colsWithMatches = 0;
            for (int matches : colMatches) {
                if (matches > 0) colsWithMatches++;
            }

            // Original condition: if (!f) || (c < l)
            return !allDigitsFound || colsWithMatches < len;
        }
    }

    /**
     * Fast input reader optimized for competitive programming.
     */
    static class InputReader {
        private final InputStream stream;
        private final byte[] buf = new byte[BUFFER_SIZE];
        private int curChar;
        private int numChars;
        private SpaceCharFilter filter;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        public int read() {
            if (numChars == -1) {
                throw new InputMismatchException();
            }
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0) {
                    return -1;
                }
            }
            return buf[curChar++];
        }

        public int nextInt() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                res *= 10;
                res += c - '0';
                c = read();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public boolean isSpaceChar(int c) {
            return filter != null ? filter.isSpaceChar(c) : isWhitespace(c);
        }

        public static boolean isWhitespace(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        public interface SpaceCharFilter {
            boolean isSpaceChar(int ch);
        }
    }

    /**
     * Fast output writer optimized for competitive programming.
     */
    static class OutputWriter {
        private final PrintWriter writer;

        public OutputWriter(OutputStream outputStream) {
            this.writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(outputStream)));
        }

        public OutputWriter(Writer writer) {
            this.writer = new PrintWriter(writer);
        }

        public void close() {
            writer.close();
        }

        public void print(int i) {
            writer.print(i);
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

/**
 * Refactored version of CFB.
 * 
 * Improvements made:
 * 1. Separated I/O logic into a static inner class (FastScanner) for better encapsulation.
 * 2. Removed unused code (shuffle, MOD constant, unused parsers like nextLongArr).
 * 3. Extracted complex logic blocks into descriptive helper methods (markSingleDigitNumbers, etc.).
 * 4. Improved variable naming (vis -> reachable, mat -> matrix).
 * 5. Added bounds checking for array access to prevent IndexOutOfBoundsException.
 * 6. Cleaned up class structure and imports.
 */
public class CFB {

    // Helper class for fast input reading
    static class FastScanner {
        BufferedReader br;
        StringTokenizer st;

        public FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    e.printStackTrace();
                    return null;
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            String s = next();
            if (s == null) throw new RuntimeException("Unexpected end of input");
            return Integer.parseInt(s);
        }
    }

    private final FastScanner scanner;
    private final PrintWriter out;

    public CFB() throws IOException {
        this.scanner = new FastScanner();
        this.out = new PrintWriter(System.out);
        solve();
        out.flush();
        out.close();
    }

    public static void main(String[] args) throws IOException {
        new CFB();
    }

    void solve() throws IOException {
        int n = scanner.nextInt();

        // Read the input matrix
        // Note: The original logic only utilizes the first 3 rows for n > 2,
        // but we read the full input to maintain stream consumption parity.
        int[][] matrix = new int[n][6];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < 6; j++) {
                matrix[i][j] = scanner.nextInt();
            }
        }

        // Boolean array to track reachable numbers (0 to 99999)
        boolean[] reachable = new boolean[100000];
        reachable[0] = true;

        // Process based on the number of rows available
        if (n == 1) {
            markSingleDigitNumbers(matrix[0], reachable);
        } else if (n == 2) {
            markTwoDigitCombinations(matrix[0], matrix[1], reachable);
        } else {
            // For n > 2, the original logic specifically iterates through the first 3 rows
            markThreeDigitCombinations(matrix[0], matrix[1], matrix[2], reachable);
        }

        // Find the first positive integer that is not reachable.
        // The problem requires printing (i - 1) where i is the first gap.
        for (int i = 1; i < 100000; i++) {
            if (!reachable[i]) {
                out.print(i - 1);
                return;
            }
        }
        // If all numbers 1..99999 are reachable, nothing is printed (matching original behavior)
    }

    /**
     * Marks single digits found in the row.
     */
    private void markSingleDigitNumbers(int[] row, boolean[] reachable) {
        for (int digit : row) {
            if (digit < reachable.length) {
                reachable[digit] = true;
            }
        }
    }

    /**
     * Marks 2-digit numbers formed by pairs from two rows, and the single digits.
     */
    private void markTwoDigitCombinations(int[] row1, int[] row2, boolean[] reachable) {
        for (int d1 : row1) {
            for (int d2 : row2) {
                // Form 2-digit numbers: d1d2 and d2d1
                int num1 = d1 * 10 + d2;
                int num2 = d2 * 10 + d1;
                if (num1 < reachable.length) reachable[num1] = true;
                if (num2 < reachable.length) reachable[num2] = true;

                // Mark single digits
                if (d1 < reachable.length) reachable[d1] = true;
                if (d2 < reachable.length) reachable[d2] = true;
            }
        }
    }

    /**
     * Marks 3-digit permutations, 2-digit pairs, and single digits formed by digits
     * from three specific rows.
     */
    private void markThreeDigitCombinations(int[] row1, int[] row2, int[] row3, boolean[] reachable) {
        for (int d1 : row1) {
            for (int d2 : row2) {
                for (int d3 : row3) {
                    // 3-digit permutations (6 permutations)
                    int n1 = d1 * 100 + d2 * 10 + d3;
                    int n2 = d1 * 100 + d3 * 10 + d2;
                    int n3 = d2 * 100 + d1 * 10 + d3;
                    int n4 = d2 * 100 + d3 * 10 + d1;
                    int n5 = d3 * 100 + d1 * 10 + d2;
                    int n6 = d3 * 100 + d2 * 10 + d1;

                    if (n1 < reachable.length) reachable[n1] = true;
                    if (n2 < reachable.length) reachable[n2] = true;
                    if (n3 < reachable.length) reachable[n3] = true;
                    if (n4 < reachable.length) reachable[n4] = true;
                    if (n5 < reachable.length) reachable[n5] = true;
                    if (n6 < reachable.length) reachable[n6] = true;

                    // 2-digit permutations (pairs)
                    int p1 = d1 * 10 + d2;
                    int p2 = d2 * 10 + d1;
                    if (p1 < reachable.length) reachable[p1] = true;
                    if (p2 < reachable.length) reachable[p2] = true;

                    int p3 = d1 * 10 + d3;
                    int p4 = d3 * 10 + d1;
                    if (p3 < reachable.length) reachable[p3] = true;
                    if (p4 < reachable.length) reachable[p4] = true;

                    int p5 = d2 * 10 + d3;
                    int p6 = d3 * 10 + d2;
                    if (p5 < reachable.length) reachable[p5] = true;
                    if (p6 < reachable.length) reachable[p6] = true;

                    // 1-digit numbers
                    if (d1 < reachable.length) reachable[d1] = true;
                    if (d2 < reachable.length) reachable[d2] = true;
                    if (d3 < reachable.length) reachable[d3] = true;
                }
            }
        }
    }
}

import java.util.*;
import java.io.*;

public class Main {
    public static void main(String[] args) {
        // Initialize scanner with BufferedReader for better performance
        Scanner scanner = new Scanner(new BufferedReader(new InputStreamReader(System.in)));

        // Read the number of rows
        if (!scanner.hasNextInt()) {
            return;
        }
        int n = scanner.nextInt();

        // Read the matrix data
        int[][] matrix = new int[n][6];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < 6; j++) {
                matrix[i][j] = scanner.nextInt();
            }
        }

        // Set to store all generated numbers
        // Using a local variable instead of a static field improves encapsulation
        Set<Integer> foundNumbers = new HashSet<>();

        // Arrays to manage permutation state
        // used tracks which row indices have been included in the current path
        boolean[] used = new boolean[n];
        int[] currentPath = new int[0];

        // Start the recursive permutation generation
        generatePermutations(currentPath, used, n, matrix, foundNumbers);

        // Find the smallest missing positive integer logic
        // The original code finds the first integer i (starting from 1) not in the set,
        // and prints i - 1. This is equivalent to counting how many consecutive 
        // integers starting from 1 are present in the set.
        int result = 0;
        while (foundNumbers.contains(result + 1)) {
            result++;
        }

        System.out.println(result);

        scanner.close();
    }

    /**
     * Recursively generates all permutations of row indices.
     * For each permutation, it triggers the number generation process.
     *
     * @param currentPath    The current sequence of row indices (permutation)
     * @param used           Boolean array to track used row indices
     * @param n              Total number of rows
     * @param matrix         The input matrix
     * @param foundNumbers   Set to store generated numbers
     */
    private static void generatePermutations(int[] currentPath, boolean[] used, int n, int[][] matrix, Set<Integer> foundNumbers) {
        // Process the current permutation to generate numbers
        // The original code processed the path immediately upon entry
        if (currentPath.length > 0) {
            generateNumbers(currentPath, matrix, foundNumbers);
        }

        // If the path is not full, try to extend it with unused row indices
        if (currentPath.length < n) {
            for (int i = 0; i < n; i++) {
                if (!used[i]) {
                    used[i] = true;
                    // Create a new path with the added index
                    int[] newPath = Arrays.copyOf(currentPath, currentPath.length + 1);
                    newPath[currentPath.length] = i;

                    generatePermutations(newPath, used, n, matrix, foundNumbers);

                    // Backtrack: mark the index as unused for the next iteration
                    used[i] = false;
                }
            }
        }
    }

    /**
     * Generates all possible numbers formed by picking one element from each row
     * specified in the rowIndices array (the permutation).
     *
     * @param rowIndices   The permutation of row indices
     * @param matrix       The input matrix
     * @param foundNumbers Set to store generated numbers
     */
    private static void generateNumbers(int[] rowIndices, int[][] matrix, Set<Integer> foundNumbers) {
        // Start recursive building of the number from the first row in the permutation
        buildNumberRecursive(0, 0, rowIndices, matrix, foundNumbers);
    }

    /**
     * Recursive helper to build numbers digit by digit.
     * Corresponds to the original comb2 logic.
     *
     * @param index        Current depth (row index in the permutation)
     * @param currentValue The number being built so far
     * @param rowIndices   The permutation of row indices
     * @param matrix       The input matrix
     * @param foundNumbers Set to store generated numbers
     */
    private static void buildNumberRecursive(int index, int currentValue, int[] rowIndices, int[][] matrix, Set<Integer> foundNumbers) {
        // Base case: if we have picked a number from every row in the permutation
        if (index == rowIndices.length) {
            foundNumbers.add(currentValue);
            return;
        }

        int row = rowIndices[index];
        int cols = matrix[row].length;

        // Iterate through all columns in the current row
        for (int col = 0; col < cols; col++) {
            int digit = matrix[row][col];
            // Append digit to current number (equivalent to res *= 10; res += digit)
            buildNumberRecursive(index + 1, currentValue * 10 + digit, rowIndices, matrix, foundNumbers);
        }
    }
}

import java.io.*;
import java.util.*;

public class TaskB {

    // Constants to replace magic numbers
    private static final int MAX_VALUE_TO_CHECK = 999;
    private static final int DIGITS_PER_INPUT_ROW = 6;

    /**
     * Recursively checks if the number 'x' can be formed using the available sets.
     * 
     * @param x The number being checked.
     * @param digitsLeft The number of digits remaining to be matched.
     * @param b The list of sets containing available digits.
     * @param used An array tracking which sets (rows) have been used in the current path.
     * @return true if the number can be formed, false otherwise.
     */
    private static boolean canFormNumber(int x, int digitsLeft, ArrayList<HashSet<Integer>> b, boolean[] used) {
        // Base case: if no digits are left to match, we found a valid configuration
        if (digitsLeft == 0) {
            return true;
        }

        int currentDigit = x % 10;
        int remainingNumber = x / 10;

        // Try to match the current digit with an available set
        for (int i = 0; i < b.size(); i++) {
            if (used[i] && b.get(i).contains(currentDigit)) {
                // Mark the set as used
                used[i] = false;

                // Recursively check the remaining digits
                if (canFormNumber(remainingNumber, digitsLeft - 1, b, used)) {
                    // If successful, backtrack (restore state) and return true
                    used[i] = true;
                    return true;
                }

                // Backtrack: restore the set availability for the next iteration
                used[i] = true;
            }
        }

        // If no set can match the current digit, this path fails
        return false;
    }

    /**
     * Wrapper method to initialize state and verify if a number is valid.
     * 
     * @param x The number to verify.
     * @param b The list of sets containing available digits.
     * @return true if the number is valid, false otherwise.
     */
    private static boolean isValidNumber(int x, ArrayList<HashSet<Integer>> b) {
        // Initialize all rows as available (true)
        boolean[] used = new boolean[b.size()];
        Arrays.fill(used, true);

        // Calculate the number of digits.
        // Note: The original logic treated 0 as having 0 digits (immediate success).
        int digitCount;
        if (x == 0) {
            digitCount = 0;
        } else {
            // Using String conversion is cleaner and less error-prone than math logic
            digitCount = String.valueOf(x).length();
        }

        return canFormNumber(x, digitCount, b, used);
    }

    public static void main(String[] args) throws IOException {
        FastScanner scanner = new FastScanner(System.in);
        PrintWriter writer = new PrintWriter(new BufferedOutputStream(System.out));

        try {
            // Read number of rows
            String nStr = scanner.next();
            if (nStr != null) {
                int n = Integer.parseInt(nStr);

                // Store digits for each row
                ArrayList<HashSet<Integer>> digitSets = new ArrayList<>(n);
                for (int i = 0; i < n; i++) {
                    HashSet<Integer> set = new HashSet<>(DIGITS_PER_INPUT_ROW);
                    for (int j = 0; j < DIGITS_PER_INPUT_ROW; j++) {
                        set.add(scanner.nextInt());
                    }
                    digitSets.add(set);
                }

                // Find the largest number <= 999 that cannot be formed.
                // The loop finds the first invalid number and subtracts 1.
                int result = MAX_VALUE_TO_CHECK;
                for (int x = 1; x <= MAX_VALUE_TO_CHECK; x++) {
                    if (!isValidNumber(x, digitSets)) {
                        result = x - 1;
                        break;
                    }
                }

                writer.println(result);
            }
        } catch (Exception e) {
            // In a production environment, logging would be appropriate.
            // In competitive programming contexts, this often results in a Runtime Error.
        } finally {
            writer.flush();
            writer.close();
        }
    }

    /**
     * Utility class for fast input reading.
     */
    static class FastScanner {
        BufferedReader reader;
        StringTokenizer tokenizer;

        FastScanner(InputStream i) {
            reader = new BufferedReader(new InputStreamReader(i));
            tokenizer = new StringTokenizer("");
        }

        String next() throws IOException {
            while (!tokenizer.hasMoreTokens()) {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        int nextInt() throws IOException {
            String s = next();
            if (s == null) throw new IOException("Unexpected end of input");
            return Integer.parseInt(s);
        }

        long nextLong() throws IOException {
            String s = next();
            if (s == null) throw new IOException("Unexpected end of input");
            return Long.parseLong(s);
        }
    }
}

