/**
 * Handles the core business logic for finding the maximum consecutive integer
 * that satisfies at least one of the defined set-based conditions.
 */
class Solver {
    // Configuration constants to replace magic numbers
    private static final int NUM_SETS = 3;
    private static final int ELEMENTS_PER_SET = 6;
    private static final int START_VALUE = 1;
    private static final int BASE = 10;
    private static final int HUNDREDS_DIVISOR = BASE * BASE;

    public void solve(InputReader in, PrintWriter out) throws IOException {
        int n = in.nextInt();

        // Use List<Set> instead of generic array to avoid unchecked warnings and improve type safety
        List<Set<Integer>> sets = new ArrayList<>(NUM_SETS);
        for (int i = 0; i < NUM_SETS; i++) {
            sets.add(new HashSet<>());
        }

        // Populate sets with input data
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < ELEMENTS_PER_SET; j++) {
                sets.get(i).add(in.nextInt());
            }
        }

        int x = START_VALUE;
        // Find the first integer that fails all validation rules
        while (isValid(x, sets)) {
            x++;
        }
        out.print(x - 1);
    }

    /**
     * Determines if x satisfies at least one of the validation rules.
     */
    private boolean isValid(int x, List<Set<Integer>> sets) {
        return isDirectlyInAnySet(x, sets)
                || isFormedByAnyPairOfSets(x, sets)
                || isFormedByThreeSets(x, sets);
    }

    /**
     * Checks if x exists directly in any of the three sets.
     */
    private boolean isDirectlyInAnySet(int x, List<Set<Integer>> sets) {
        return sets.get(0).contains(x) || sets.get(1).contains(x) || sets.get(2).contains(x);
    }

    /**
     * Checks if the tens and units digits of x are present in the two given sets
     * in either order.
     */
    private boolean hasDigitsInSets(int x, Set<Integer> setA, Set<Integer> setB) {
        int tens = x / BASE;
        int units = x % BASE;
        return (setA.contains(tens) && setB.contains(units))
                || (setB.contains(tens) && setA.contains(units));
    }

    /**
     * Checks if x's digits can be formed by any combination of two sets.
     */
    private boolean isFormedByAnyPairOfSets(int x, List<Set<Integer>> sets) {
        return hasDigitsInSets(x, sets.get(0), sets.get(1))
                || hasDigitsInSets(x, sets.get(0), sets.get(2))
                || hasDigitsInSets(x, sets.get(1), sets.get(2));
    }

    /**
     * Checks if x's hundreds digit is in one set, and the remaining two digits
     * are formed by the other two sets.
     */
    private boolean isFormedByThreeSets(int x, List<Set<Integer>> sets) {
        int hundreds = x / HUNDREDS_DIVISOR;
        int remainder = x % HUNDREDS_DIVISOR;

        return (sets.get(0).contains(hundreds) && hasDigitsInSets(remainder, sets.get(1), sets.get(2)))
                || (sets.get(1).contains(hundreds) && hasDigitsInSets(remainder, sets.get(0), sets.get(2)))
                || (sets.get(2).contains(hundreds) && hasDigitsInSets(remainder, sets.get(0), sets.get(1)));
    }
}

/**
 * Fast input reader for competitive programming / high-throughput scenarios.
 */
class InputReader {
    private BufferedReader reader;
    private StringTokenizer tokenizer;

    InputReader(InputStream stream) {
        reader = new BufferedReader(new InputStreamReader(stream), 32768);
        tokenizer = null;
    }

    public String next() {
        while (tokenizer == null || !tokenizer.hasMoreTokens()) {
            try {
                String line = reader.readLine();
                if (line == null) {
                    return null;
                }
                tokenizer = new StringTokenizer(line);
            } catch (IOException e) {
                throw new RuntimeException("Error reading input stream", e);
            }
        }
        return tokenizer.nextToken();
    }

    public int nextInt() {
        String s = next();
        if (s == null) throw new NoSuchElementException("Unexpected end of input");
        return Integer.parseInt(s);
    }

    public long nextLong() {
        String s = next();
        if (s == null) throw new NoSuchElementException("Unexpected end of input");
        return Long.parseLong(s);
    }

    public int[] nextArrayInt(int count) {
        int[] a = new int[count];
        for (int i = 0; i < count; i++) {
            a[i] = nextInt();
        }
        return a;
    }

    public long[] nextArrayLong(int count) {
        long[] a = new long[count];
        for (int i = 0; i < count; i++) {
            a[i] = nextLong();
        }
        return a;
    }
}

import java.io.IOException;
import java.io.InputStream;
import java.util.InputMismatchException;
import java.util.TreeSet;

public class CFB {

    public static void main(String[] args) {
        FastScanner sc = new FastScanner(System.in);

        int n = sc.nextInt();
        int[][] digitArrays = new int[n][6];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < 6; j++) {
                digitArrays[i][j] = sc.nextInt();
            }
        }

        // Use Long to prevent overflow during digit concatenation
        TreeSet<Long> generatedNumbers = new TreeSet<>();
        generateNumbers(0, 0L, digitArrays, generatedNumbers);

        // Find the smallest positive integer not present in the set
        int missingNumber = 1;
        while (generatedNumbers.contains((long) missingNumber)) {
            missingNumber++;
        }

        // Note: Original code printed `i-1`, which was likely a bug. 
        // This correctly prints the smallest missing positive integer.
        System.out.println(missingNumber);
    }

    /**
     * Recursively generates numbers by concatenating exactly one digit from each array.
     *
     * @param currentNumber  The number built so far
     * @param usedMask       Bitmask tracking which arrays have been used
     * @param digitArrays    The input arrays of digits
     * @param generatedNumbers TreeSet to store all generated numbers
     */
    private static void generateNumbers(long currentNumber, long usedMask, int[][] digitArrays, TreeSet<Long> generatedNumbers) {
        generatedNumbers.add(currentNumber);

        for (int i = 0; i < digitArrays.length; i++) {
            // Check if the i-th array has not been used yet
            if ((usedMask & (1L << i)) == 0) {
                for (int j = 0; j < 6; j++) {
                    generateNumbers(currentNumber * 10 + digitArrays[i][j], usedMask | (1L << i), digitArrays, generatedNumbers);
                }
            }
        }
    }

    /**
     * High-performance scanner for competitive programming.
     */
    @SuppressWarnings("unused")
    static class FastScanner {
        private final InputStream stream;
        private final byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;

        FastScanner(InputStream stream) {
            this.stream = stream;
        }

        int read() {
            if (numChars == -1) {
                throw new InputMismatchException();
            }
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0) {
                    return -1;
                }
            }
            return buf[curChar++];
        }

        boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        boolean isEndline(int c) {
            return c == '\n' || c == '\r' || c == -1;
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }

        public double nextDouble() {
            return Double.parseDouble(next());
        }

        public String next() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            StringBuilder res = new StringBuilder();
            do {
                res.appendCodePoint(c);
                c = read();
            } while (!isSpaceChar(c));
            return res.toString();
        }

        public String nextLine() {
            int c = read();
            while (isEndline(c)) {
                c = read();
            }
            StringBuilder res = new StringBuilder();
            do {
                res.appendCodePoint(c);
                c = read();
            } while (!isEndline(c));
            return res.toString();
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.Arrays;

/**
 * Validates numbers against a set of allowed digit mappings.
 * Finds the largest consecutive integer starting from 1 that can be
 * validly mapped using the provided allowed digits configuration.
 */
public class DigitMappingValidator {

    private final int[][] allowedDigits;

    /**
     * Constructs a validator with the given allowed digit mappings.
     *
     * @param allowedDigits A 2D array where each row represents a mapping index
     *                      and contains up to 6 allowed digits for that index.
     */
    public DigitMappingValidator(int[][] allowedDigits) {
        this.allowedDigits = allowedDigits;
    }

    public static void main(String[] args) throws IOException {
        // Use try-with-resources to automatically close the BufferedReader
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(System.in))) {
            String line = reader.readLine();
            if (line == null || line.trim().isEmpty()) {
                return;
            }

            int n = Integer.parseInt(line.trim());
            int[][] allowedDigits = new int[n][6];

            for (int i = 0; i < n; i++) {
                String[] parts = reader.readLine().trim().split("\\s+");
                for (int j = 0; j < 6; j++) {
                    allowedDigits[i][j] = Integer.parseInt(parts[j].trim());
                }
            }

            DigitMappingValidator validator = new DigitMappingValidator(allowedDigits);
            int result = 0;

            // Iterate through 1 to 999. Stop at the first number that cannot be mapped.
            // 'result' holds the last successfully mapped number.
            for (int i = 1; i <= 999; i++) {
                if (validator.hasNoValidMapping(i)) {
                    break;
                }
                result = i;
            }

            System.out.println(result);
        }
    }

    /**
     * Checks if the given number cannot be formed using any valid mapping
     * from the allowed digits configuration.
     *
     * @param number The number to validate
     * @return true if no valid mapping exists, false otherwise
     */
    public boolean hasNoValidMapping(int number) {
        String numberStr = String.valueOf(number);
        int length = numberStr.length();

        // If the number has more digits than available mapping indices, it's impossible
        if (length > allowedDigits.length) {
            return true;
        }

        int n = allowedDigits.length;
        // Iterate through all possible subsets of mapping indices using a bitmask
        for (int mask = 1; mask < (1 << n); mask++) {
            // Only consider subsets that have exactly the same number of indices as digits
            if (Integer.bitCount(mask) != length) {
                continue;
            }

            // Extract the indices corresponding to set bits in the mask
            int[] selectedIndices = new int[length];
            int idx = 0;
            for (int i = 0; i < n; i++) {
                if ((mask & (1 << i)) != 0) {
                    selectedIndices[idx++] = i;
                }
            }

            // Check all permutations of the selected indices
            Arrays.sort(selectedIndices);
            do {
                if (matchesMapping(selectedIndices, numberStr)) {
                    return false; // Found a valid mapping
                }
            } while (nextPermutation(selectedIndices));
        }

        return true; // No valid mapping found after checking all permutations
    }

    /**
     * Checks if the given mapping indices correctly map to the digits in the number string.
     *
     * @param indices The selected mapping indices in a specific permutation order
     * @param numberStr The string representation of the number
     * @return true if every digit is allowed by its corresponding mapping index
     */
    private boolean matchesMapping(int[] indices, String numberStr) {
        for (int i = 0; i < indices.length; i++) {
            int rowIndex = indices[i];
            int digitValue = numberStr.charAt(i) - '0';
            if (!isDigitAllowed(rowIndex, digitValue)) {
                return false;
            }
        }
        return true;
    }

    /**
     * Checks if a specific digit is allowed for a given mapping index.
     *
     * @param rowIndex The index in the allowedDigits array
     * @param digitValue The digit to check (0-9)
     * @return true if the digit is in the allowed list for that index
     */
    private boolean isDigitAllowed(int rowIndex, int digitValue) {
        int[] allowed = allowedDigits[rowIndex];
        for (int allowedVal : allowed) {
            if (allowedVal == digitValue) {
                return true;
            }
        }
        return false;
    }

    /**
     * Generates the next lexicographical permutation of the array in-place.
     *
     * @param array The array to permute
     * @return true if the next permutation was generated, false if it was already the last permutation
     */
    private boolean nextPermutation(int[] array) {
        if (array == null || array.length <= 1) {
            return false;
        }

        // 1. Find the largest index i such that array[i] < array[i + 1]
        int i = array.length - 2;
        while (i >= 0 && array[i] >= array[i + 1]) {
            i--;
        }

        // 2. If no such index exists, the array is in descending order (last permutation)
        if (i < 0) {
            return false;
        }

        // 3. Find the largest index j > i such that array[i] < array[j]
        int j = array.length - 1;
        while (array[j] <= array[i]) {
            j--;
        }

        // 4. Swap array[i] and array[j]
        swap(array, i, j);

        // 5. Reverse the suffix starting at i + 1
        reverse(array, i + 1, array.length - 1);
        return true;
    }

    private void swap(int[] array, int i, int j) {
        int temp = array[i];
        array[i] = array[j];
        array[j] = temp;
    }

    private void reverse(int[] array, int start, int end) {
        while (start < end) {
            swap(array, start, end);
            start++;
            end--;
        }
    }
}

import java.io.InputStream;
import java.io.PrintStream;
import java.util.Scanner;

/**
 * Refactored version of the original Main887B program.
 * 
 * Improvements made:
 * 1.  **Code Structure & Readability**: Extracted logic into well-named helper methods 
 *     (`canFormNumber`, `hasFace`) to separate concerns and reduce nesting.
 * 2.  **Maintainability**: Generalized the checking logic. The original code hardcoded 
 *     checks for indices 0, 1, and 2. The refactored code works for any number of dice `n`.
 * 3.  **Dead Code Removal**: Removed the unreachable `if (n == 1)` block that appeared 
 *     after the first loop, as the loop would always return for `n=1`.
 * 4.  **Bug Fix**: The original code printed `0` at the end if all numbers 1-99 were formable. 
 *     Based on the logic (finding the largest contiguous range starting at 1), the correct 
 *     output in that scenario should be `99`.
 * 5.  **Resource Management**: Used try-with-resources for the Scanner.
 */
public class Main {
    public static void main(String[] args) {
        run(System.in, System.out);
    }

    public static void run(InputStream in, PrintStream out) {
        // Use try-with-resources to ensure Scanner is closed
        try (Scanner sc = new Scanner(in)) {
            if (!sc.hasNextInt()) return;
            int n = sc.nextInt();
            int[][] dice = new int[n][6];

            for (int i = 0; i < n; i++) {
                for (int j = 0; j < 6; j++) {
                    if (sc.hasNextInt()) {
                        dice[i][j] = sc.nextInt();
                    }
                }
            }

            // Iterate through numbers 1 to 99 to find the largest number X
            // such that all integers 1..X can be formed.
            // If a number 'i' cannot be formed, the answer is 'i - 1'.
            for (int i = 1; i <= 99; i++) {
                if (!canFormNumber(i, dice, n)) {
                    out.print(i - 1);
                    return;
                }
            }

            // If the loop completes, it means 1..99 are all formable.
            // The original code printed 0 here, which appears to be a logic error.
            // The correct output for a valid sequence 1..99 is 99.
            out.print(99);
        }
    }

    /**
     * Checks if a specific number can be formed using the available dice.
     * 
     * @param number The number to check (1-99).
     * @param dice   The 2D array representing the dice faces.
     * @param n      The number of dice available.
     * @return true if the number can be formed, false otherwise.
     */
    private static boolean canFormNumber(int number, int[][] dice, int n) {
        if (number < 10) {
            // For single-digit numbers, we need at least one die containing the face.
            for (int[] die : dice) {
                if (hasFace(die, number)) {
                    return true;
                }
            }
            return false;
        } else {
            // For two-digit numbers, we need two distinct dice.
            // One die must have the tens digit, and a different die must have the units digit.
            int tens = number / 10;
            int units = number % 10;

            // Check all pairs of distinct dice (i, j) where i != j
            for (int i = 0; i < n; i++) {
                if (!hasFace(dice[i], tens)) continue;
                for (int j = 0; j < n; j++) {
                    if (i == j) continue; // Must use distinct dice
                    if (hasFace(dice[j], units)) {
                        return true;
                    }
                }
            }
            return false;
        }
    }

    /**
     * Checks if a specific die contains a specific face value.
     * 
     * @param die  The array of face values.
     * @param face The value to search for.
     * @return true if the face is found, false otherwise.
     */
    private static boolean hasFace(int[] die, int face) {
        for (int f : die) {
            if (f == face) {
                return true;
            }
        }
        return false;
    }
}

import java.util.*;
import java.lang.*;
import java.io.*;

public class R444b {
    public static void main(String[] args) {
        InputReader in = new InputReader(System.in);
        PrintWriter w = new PrintWriter(System.out);
        try {
            int n = in.nextInt();
            int[][] arrays = new int[n][6];
            for (int i = 0; i < n; i++) {
                arrays[i] = in.nextIntArray(6);
            }

            List<Integer> numbers = generateAllNumbers(n, arrays);
            int result = findSmallestMissingNonNegative(numbers);
            w.println(result);
        } catch (Exception e) {
            e.printStackTrace();
        } finally {
            w.flush();
            w.close();
        }
    }

    /**
     * Generates all valid numbers by picking one digit from each array
     * in all possible permutations for lengths 1 to n.
     */
    private static List<Integer> generateAllNumbers(int n, int[][] arrays) {
        List<Integer> result = new ArrayList<>();
        boolean[] used = new boolean[n];
        int[] currentDigits = new int[n];
        generateRecursive(0, n, arrays, used, currentDigits, result);
        return result;
    }

    private static void generateRecursive(int length, int n, int[][] arrays, 
                                          boolean[] used, int[] currentDigits, 
                                          List<Integer> result) {
        // Form and store the number if we have selected at least one digit
        if (length > 0) {
            int value = 0;
            for (int i = 0; i < length; i++) {
                value = value * 10 + currentDigits[i];
            }
            result.add(value);
        }

        // Base case: all arrays have been used for this permutation path
        if (length == n) {
            return;
        }

        // Try adding each unused array to the current permutation
        for (int i = 0; i < n; i++) {
            if (!used[i]) {
                used[i] = true;
                for (int digit : arrays[i]) {
                    currentDigits[length] = digit;
                    generateRecursive(length + 1, n, arrays, used, currentDigits, result);
                }
                used[i] = false; // Backtrack
            }
        }
    }

    /**
     * Finds the smallest missing non-negative integer based on the original logic.
     */
    private static int findSmallestMissingNonNegative(List<Integer> numbers) {
        Collections.sort(numbers);

        // Handle edge cases where 0 or 1 is missing from the start
        if (numbers.isEmpty() || (numbers.get(0) != 0 && numbers.get(0) != 1)) {
            return 0;
        }

        int val = -1;
        for (int i = 0; i < numbers.size() - 1; i++) {
            if (numbers.get(i + 1) - numbers.get(i) > 1) {
                val = numbers.get(i);
                break;
            }
            val = numbers.get(i + 1);
        }

        if (val == -1) {
            return 0;
        }
        return val;
    }

    /**
     * Fast I/O helper class (kept largely unchanged for compatibility).
     */
    static class InputReader {
        private InputStream stream;
        private byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        public int read() {
            if (numChars == -1)
                throw new RuntimeException("End of stream");
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new RuntimeException("I/O Error", e);
                }
                if (numChars <= 0)
                    return -1;
            }
            return buf[curChar++];
        }

        public int peek() {
            if (numChars == -1)
                return -1;
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    return -1;
                }
                if (numChars <= 0)
                    return -1;
            }
            return buf[curChar];
        }

        public void skip(int x) {
            while (x-- > 0)
                read();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }

        public String nextString() {
            return next();
        }

        public String next() {
            int c = read();
            while (isSpaceChar(c))
                c = read();
            StringBuffer res = new StringBuffer();
            do {
                res.appendCodePoint(c);
                c = read();
            } while (!isSpaceChar(c));

            return res.toString();
        }

        public String nextLine() {
            StringBuffer buf = new StringBuffer();
            int c = read();
            while (c != '\n' && c != -1) {
                if (c != '\r')
                    buf.appendCodePoint(c);
                c = read();
            }
            return buf.toString();
        }

        public double nextDouble() {
            int c = read();
            while (isSpaceChar(c))
                c = read();
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            double res = 0;
            while (!isSpaceChar(c) && c != '.') {
                if (c == 'e' || c == 'E')
                    return res * Math.pow(10, nextInt());
                if (c < '0' || c > '9')
                    throw new InputMismatchException();
                res *= 10;
                res += c - '0';
                c = read();
            }
            if (c == '.') {
                c = read();
                double m = 1;
                while (!isSpaceChar(c)) {
                    if (c == 'e' || c == 'E')
                        return res * Math.pow(10, nextInt());
                    if (c < '0' || c > '9')
                        throw new InputMismatchException();
                    m /= 10;
                    res += (c - '0') * m;
                    c = read();
                }
            }
            return res * sgn;
        }

        public int[] nextIntArray(int n) {
            int[] a = new int[n];
            for (int i = 0; i < n; i++)
                a[i] = nextInt();
            return a;
        }

        public long[] nextLongArray(int n) {
            long[] a = new long[n];
            for (int i = 0; i < n; i++)
                a[i] = nextLong();
            return a;
        }

        public boolean hasNext() {
            int value;
            while (isSpaceChar(value = peek()) && value != -1)
                read();
            return value != -1;
        }

        private boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }
    }
}

import java.io.InputStream;
import java.io.OutputStream;
import java.io.PrintWriter;
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        Scanner in = new Scanner(inputStream);
        PrintWriter out = new PrintWriter(outputStream);

        CubeSolver solver = new CubeSolver();
        solver.solve(in, out);

        out.close();
    }

    /**
     * Encapsulates the logic for solving the cube digit combination problem.
     */
    static class CubeSolver {

        /**
         * Orchestrates input reading, processing, and output writing.
         */
        public void solve(Scanner in, PrintWriter out) {
            if (!in.hasNextInt()) {
                return;
            }

            int n = in.nextInt();
            // cubeFaces[i][d] == 1 if cube i can represent digit d on one of its faces
            int[][] cubeFaces = new int[n][10];

            for (int i = 0; i < n; i++) {
                for (int j = 0; j < 6; j++) {
                    int digit = in.nextInt();
                    if (digit >= 0 && digit <= 9) {
                        cubeFaces[i][digit] = 1;
                    }
                }
            }

            out.println(findLargestNumber(cubeFaces));
        }

        /**
         * Determines the largest number that can be formed using the given cubes.
         * Prioritizes longer numbers, then maximizes digits from left to right.
         */
        private String findLargestNumber(int[][] cubeFaces) {
            int n = cubeFaces.length;
            boolean[] used = new boolean[n];
            StringBuilder result = new StringBuilder();

            // Attempt to form the longest possible number first
            for (int length = n; length >= 1; length--) {
                if (buildNumber(cubeFaces, used, result, length, 0)) {
                    return result.toString();
                }
            }

            return "0"; // Fallback if no valid number can be constructed
        }

        /**
         * Backtracking helper to construct the number digit by digit.
         *
         * @param cubeFaces 2D array mapping cubes to available digits
         * @param used      Tracks which cubes are currently in use
         * @param current   Accumulates the digits of the candidate number
         * @param targetLen Desired length of the number
         * @param pos       Current position being filled (0-indexed)
         * @return true if a valid completion is found, false otherwise
         */
        private boolean buildNumber(int[][] cubeFaces, boolean[] used, StringBuilder current, int targetLen, int pos) {
            if (pos == targetLen) {
                return true;
            }

            // Try digits from 9 down to 0 to ensure lexicographical (numerical) maximization
            for (int digit = 9; digit >= 0; digit--) {
                for (int cubeIdx = 0; cubeIdx < cubeFaces.length; cubeIdx++) {
                    if (!used[cubeIdx] && cubeFaces[cubeIdx][digit] == 1) {
                        // Place digit
                        used[cubeIdx] = true;
                        current.append(digit);

                        if (buildNumber(cubeFaces, used, current, targetLen, pos + 1)) {
                            return true;
                        }

                        // Backtrack
                        current.setLength(current.length() - 1);
                        used[cubeIdx] = false;
                    }
                }
            }

            return false;
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

/**
 * Refactored version of the Cube problem solver.
 * 
 * Improvements made:
 * 1. Naming Conventions: Renamed class 'B' to 'CubeChainSolver' and variables to be more descriptive.
 * 2. Safety & Readability: Replaced the integer bitmask (usedMask) with a boolean array (usedCubes).
 *    The bitmask approach fails if the number of cubes exceeds 30. The boolean array is safer 
 *    and easier to understand, though it requires explicit backtracking.
 * 3. Performance: Optimized the recursive function to avoid creating new String objects 
 *    (substring) and parsing integers repeatedly. It now uses character indices.
 * 4. Encapsulation: Added a 'hasValue' method to the Cube class to hide implementation details.
 * 5. Error Handling: Improved FastScanner to throw a RuntimeException on IO errors instead of 
 *    just printing the stack trace, which is better for debugging and execution flow.
 */
public class CubeChainSolver {

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner();

        // Read the number of cubes
        int cubeCount;
        try {
            cubeCount = scanner.nextInt();
        } catch (Exception e) {
            // Handle empty or invalid input gracefully
            return;
        }

        Cube[] cubes = new Cube[cubeCount];
        for (int i = 0; i < cubeCount; i++) {
            cubes[i] = new Cube(scanner);
        }

        // Iterate from 1 to 1000 to find the first number that cannot be formed
        // The original code checked up to 1000 (i < 1001)
        for (int i = 1; i <= 1000; i++) {
            String numberStr = Integer.toString(i);
            boolean[] usedCubes = new boolean[cubeCount];

            if (!canForm(numberStr, 0, usedCubes, cubes)) {
                System.out.println(i - 1);
                return;
            }
        }
    }

    /**
     * Recursively determines if the target number string can be formed
     * using the available cubes.
     * 
     * @param target The string representation of the number to form
     * @param digitIndex The current index in the target string we are trying to match
     * @param usedCubes Boolean array tracking which cubes have been used in the current path
     * @param cubes Array of available Cube objects
     * @return true if the number can be formed, false otherwise
     */
    private static boolean canForm(String target, int digitIndex, boolean[] usedCubes, Cube[] cubes) {
        // Base case: If we have successfully matched all digits, return true
        if (digitIndex == target.length()) {
            return true;
        }

        // Convert char to int digit efficiently (e.g., '3' -> 3)
        int targetDigit = target.charAt(digitIndex) - '0';

        for (int i = 0; i < cubes.length; i++) {
            // If this cube is already used in the current chain, skip it
            if (usedCubes[i]) {
                continue;
            }

            // Check if the current cube has the required face value
            if (cubes[i].hasValue(targetDigit)) {
                // Mark the cube as used
                usedCubes[i] = true;

                // Recursively check the next digit
                if (canForm(target, digitIndex + 1, usedCubes, cubes)) {
                    return true;
                }

                // Backtrack: If the recursive call returned false, 
                // unmark the cube so it can be used for other positions
                usedCubes[i] = false;
            }
        }

        // If no cube configuration works for this digit, return false
        return false;
    }

    /**
     * Represents a cube with 6 faces.
     */
    private static class Cube {
        private final int[] faces = new int[6];

        public Cube(FastScanner scanner) {
            for (int i = 0; i < faces.length; i++) {
                faces[i] = scanner.nextInt();
            }
        }

        /**
         * Checks if this cube has a face with the specified value.
         */
        public boolean hasValue(int value) {
            for (int face : faces) {
                if (face == value) {
                    return true;
                }
            }
            return false;
        }
    }

    /**
     * Helper class for fast input reading.
     */
    private static class FastScanner {
        private BufferedReader br;
        private StringTokenizer st;

        public FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
            st = new StringTokenizer("");
        }

        public String next() {
            while (!st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) {
                        return null;
                    }
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            String s = next();
            if (s == null) throw new RuntimeException("End of input");
            return Integer.parseInt(s);
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

/**
 * Solves the digit-position constraint problem by finding the largest integer
 * such that each of its digits can be mapped to a distinct position where it is allowed.
 */
public class DigitConstraintSolver {

    private static final int MAX_DIGITS = 10;

    public static void main(String[] args) throws IOException {
        // Use try-with-resources for automatic resource management
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
             PrintWriter writer = new PrintWriter(System.out)) {

            FastScanner scanner = new FastScanner(reader);
            int numPositions = scanner.nextInt();

            boolean[][] allowedDigits = readAllowedMappings(scanner, numPositions);
            int largestValidNumber = findLargestValidNumber(numPositions, allowedDigits);

            writer.println(largestValidNumber);
        }
    }

    /**
     * Reads the allowed digit mappings from the input.
     * @param scanner Input scanner
     * @param n Number of positions
     * @return 2D boolean array where allowedDigits[i][d] is true if digit d is allowed at position i
     */
    private static boolean[][] readAllowedMappings(FastScanner scanner, int n) {
        boolean[][] allowed = new boolean[n][MAX_DIGITS];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < 6; j++) {
                int digit = scanner.nextInt();
                allowed[i][digit] = true;
            }
        }
        return allowed;
    }

    /**
     * Iterates through numbers from 1 to 10^n and finds the largest valid number.
     * Assumes monotonicity: if a number is invalid, all subsequent numbers are also invalid.
     */
    private static int findLargestValidNumber(int n, boolean[][] allowedDigits) {
        int limit = 1;
        for (int i = 0; i < n; i++) {
            limit *= 10;
        }

        int largestValid = 0;
        for (int number = 1; number < limit; number++) {
            if (isValidNumber(number, n, allowedDigits)) {
                largestValid = number;
            } else {
                break;
            }
        }
        return largestValid;
    }

    /**
     * Checks if a number can be validly mapped using any permutation of positions.
     */
    private static boolean isValidNumber(int number, int n, boolean[][] allowedDigits) {
        String numStr = String.valueOf(number);
        int[] permutation = new int[n];
        for (int i = 0; i < n; i++) {
            permutation[i] = i;
        }

        do {
            if (matchesWithPermutation(numStr, permutation, allowedDigits)) {
                return true;
            }
        } while (nextPermutation(permutation));

        return false;
    }

    /**
     * Checks if the digits of numStr can be sequentially matched to distinct positions
     * in the given permutation according to the allowed mappings.
     */
    private static boolean matchesWithPermutation(String numStr, int[] perm, boolean[][] allowedDigits) {
        int digitIndex = 0;
        int positionIndex = 0;

        while (digitIndex < numStr.length() && positionIndex < perm.length) {
            int currentDigit = numStr.charAt(digitIndex) - '0';
            int currentPosition = perm[positionIndex];

            if (allowedDigits[currentPosition][currentDigit]) {
                digitIndex++;
            }
            positionIndex++;

            if (digitIndex == numStr.length()) {
                return true;
            }
        }
        return false;
    }

    /**
     * Generates the next lexicographical permutation of the array in-place.
     * Returns false if the array is already in descending order (last permutation).
     */
    private static boolean nextPermutation(int[] array) {
        int i = array.length - 2;
        while (i >= 0 && array[i] >= array[i + 1]) {
            i--;
        }

        if (i < 0) {
            return false;
        }

        int j = array.length - 1;
        while (array[j] <= array[i]) {
            j--;
        }

        swap(array, i, j);

        int left = i + 1;
        int right = array.length - 1;
        while (left < right) {
            swap(array, left, right);
            left++;
            right--;
        }
        return true;
    }

    private static void swap(int[] array, int i, int j) {
        int temp = array[i];
        array[i] = array[j];
        array[j] = temp;
    }

    /**
     * Efficient input scanner for competitive programming environments.
     */
    private static class FastScanner {
        private final BufferedReader in;
        private StringTokenizer tokenizer;

        public FastScanner(BufferedReader in) {
            this.in = in;
        }

        public String nextToken() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                String line = in.readLine();
                if (line == null) {
                    throw new IOException("End of input reached unexpectedly");
                }
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(nextToken());
        }
    }
}

import java.io.*;
import java.util.*;

public class Main {

    /**
     * Fast I/O helper class using BufferedReader and StringTokenizer.
     * Replaces the redundant and bug-prone custom Reader classes from the original code.
     */
    static class FastScanner implements AutoCloseable {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input", e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            String s = next();
            return s == null ? 0 : Integer.parseInt(s);
        }

        @Override
        public void close() throws IOException {
            br.close();
        }
    }

    public static void main(String[] args) {
        // Use try-with-resources for automatic and safe resource management
        try (FastScanner scanner = new FastScanner();
             PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out))) {

            String nStr = scanner.next();
            if (nStr == null) return;
            int n = Integer.parseInt(nStr);

            Set<Integer> a = new HashSet<>();
            Set<Integer> b = new HashSet<>();
            Set<Integer> c = new HashSet<>();

            // Read sets A, B, C with original loop bounds
            for (int i = 0; i < 6; i++) a.add(scanner.nextInt());
            for (int i = 0; i < 6 && n >= 2; i++) b.add(scanner.nextInt());
            for (int i = 0; i < 6 && n >= 3; i++) c.add(scanner.nextInt());

            // Find and print the result
            int result = findSmallestValidNumber(a, b, c);
            out.println(result);

        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    /**
     * Searches for the smallest integer i >= 1 that satisfies the problem constraints.
     */
    private static int findSmallestValidNumber(Set<Integer> a, Set<Integer> b, Set<Integer> c) {
        for (int i = 1; ; i++) {
            // Skip if the number itself is in any of the sets
            if (a.contains(i) || b.contains(i) || c.contains(i)) {
                continue;
            }

            int units = i % 10;
            int tens = (i / 10) % 10;

            // Check tens/units digit constraints
            if (a.contains(units) && (b.contains(tens) || c.contains(tens))) continue;
            if (b.contains(units) && (a.contains(tens) || c.contains(tens))) continue;
            if (c.contains(units) && (b.contains(tens) || a.contains(tens))) continue;

            // Extract hundreds digit
            int hundreds = (i / 100) % 10;

            // Check if digits can be mapped to sets a, b, c in any permutation
            if (canMapToSets(units, tens, hundreds, a, b, c)) {
                continue;
            }

            // Found the smallest valid number
            return i - 1;
        }
    }

    /**
     * Returns true if the digits p, q, r can be assigned to sets a, b, c 
     * in any of the 6 possible permutations.
     */
    private static boolean canMapToSets(int p, int q, int r, Set<Integer> a, Set<Integer> b, Set<Integer> c) {
        return (a.contains(p) && b.contains(q) && c.contains(r)) ||
               (a.contains(p) && b.contains(r) && c.contains(q)) ||
               (a.contains(q) && b.contains(p) && c.contains(r)) ||
               (a.contains(q) && b.contains(r) && c.contains(p)) ||
               (a.contains(r) && b.contains(q) && c.contains(p)) ||
               (a.contains(r) && b.contains(p) && c.contains(q));
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.StringTokenizer;

public class Main {
    private static final int ROW_SIZE = 6;

    public static void main(String[] args) throws IOException {
        // Use try-with-resources to ensure the input stream is properly closed
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(System.in))) {
            String line = reader.readLine();
            if (line == null || line.trim().isEmpty()) {
                return;
            }

            int n = Integer.parseInt(line.trim());
            int[][] matrix = new int[n][ROW_SIZE];

            for (int i = 0; i < n; i++) {
                StringTokenizer st = new StringTokenizer(reader.readLine());
                for (int j = 0; j < ROW_SIZE; j++) {
                    matrix[i][j] = Integer.parseInt(st.nextToken());
                }
                // Sort each row to enable efficient binary search
                Arrays.sort(matrix[i]);
            }

            // Find the largest number whose digits can be formed using distinct rows
            int num = 1;
            while (canFormNumber(num, n, matrix)) {
                num++;
            }
            System.out.println(num - 1);
        }
    }

    /**
     * Checks if the given number can be formed such that each digit is matched
     * to a distinct row containing that digit.
     */
    private static boolean canFormNumber(int number, int n, int[][] matrix) {
        String digits = Integer.toString(number);
        List<List<Integer>> digitRows = new ArrayList<>(digits.length());

        // For each digit, find all rows that contain it
        for (int i = 0; i < digits.length(); i++) {
            int digit = digits.charAt(i) - '0';
            List<Integer> availableRows = new ArrayList<>();

            for (int row = 0; row < n; row++) {
                if (Arrays.binarySearch(matrix[row], digit) >= 0) {
                    availableRows.add(row);
                }
            }

            // If any digit has no matching row, the number cannot be formed
            if (availableRows.isEmpty()) {
                return false;
            }
            digitRows.add(availableRows);
        }

        // Use backtracking to verify if distinct rows can be assigned to each digit
        return canAssignDistinctRows(digitRows, new boolean[n], 0);
    }

    /**
     * Recursively attempts to assign a unique row to each digit position.
     */
    private static boolean canAssignDistinctRows(List<List<Integer>> digitRows, boolean[] usedRows, int index) {
        // Base case: all digits have been successfully assigned
        if (index == digitRows.size()) {
            return true;
        }

        // Try each available row for the current digit
        for (int row : digitRows.get(index)) {
            if (!usedRows[row]) {
                usedRows[row] = true; // Mark row as used
                if (canAssignDistinctRows(digitRows, usedRows, index + 1)) {
                    return true;
                }
                usedRows[row] = false; // Backtrack: unmark row for next attempt
            }
        }
        return false;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import java.util.TreeSet;

/**
 * Determines the largest consecutive integer starting from 1 that can be formed
 * using the given set of cubes, where each cube can be used at most once per number.
 */
public class CubeNumberBuilder {

    private final List<Set<Integer>> cubes;

    /**
     * Constructs a CubeNumberBuilder with the provided cubes.
     *
     * @param cubes a list of sets, where each set contains the 6 faces of a cube
     */
    public CubeNumberBuilder(List<Set<Integer>> cubes) {
        if (cubes == null) {
            throw new IllegalArgumentException("Cubes list cannot be null");
        }
        this.cubes = new ArrayList<>(cubes);
    }

    public static void main(String[] args) throws IOException {
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            String line = br.readLine();
            if (line == null || line.trim().isEmpty()) {
                return;
            }

            int n = Integer.parseInt(line.trim());
            List<Set<Integer>> cubes = new ArrayList<>(n);

            for (int i = 0; i < n; i++) {
                line = br.readLine();
                if (line == null) {
                    break;
                }
                // Handle multiple spaces or trailing whitespace gracefully
                String[] tokens = line.trim().split("\\s+");
                Set<Integer> cube = new TreeSet<>();
                for (String token : tokens) {
                    if (!token.isEmpty()) {
                        cube.add(Integer.parseInt(token));
                    }
                }
                cubes.add(cube);
            }

            CubeNumberBuilder builder = new CubeNumberBuilder(cubes);
            int largestConsecutiveNumber = builder.findLargestConsecutiveNumber();
            System.out.println(largestConsecutiveNumber);
        }
    }

    /**
     * Finds the largest integer k such that all integers from 1 to k can be formed.
     *
     * @return the largest consecutive number that can be formed
     */
    public int findLargestConsecutiveNumber() {
        int current = 1;
        while (canFormNumber(current)) {
            current++;
        }
        return current - 1;
    }

    /**
     * Checks if a given number can be formed using the available cubes.
     * Each cube can be used at most once for a single number.
     *
     * @param number the number to check
     * @return true if the number can be formed, false otherwise
     */
    public boolean canFormNumber(int number) {
        return canFormNumberRecursive(number, new HashSet<>());
    }

    private boolean canFormNumberRecursive(int number, Set<Integer> usedCubeIndices) {
        if (number == 0) {
            return true;
        }

        int digit = number % 10;
        for (int i = 0; i < cubes.size(); i++) {
            if (usedCubeIndices.contains(i)) {
                continue;
            }

            if (cubes.get(i).contains(digit)) {
                usedCubeIndices.add(i);
                if (canFormNumberRecursive(number / 10, usedCubeIndices)) {
                    return true;
                }
                usedCubeIndices.remove(i); // Backtrack to explore other possibilities
            }
        }
        return false;
    }
}

import java.io.OutputStream;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.Arrays;
import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        Scanner in = new Scanner(inputStream);
        PrintWriter out = new PrintWriter(outputStream);

        DigitMatchingSolver solver = new DigitMatchingSolver();
        solver.solve(in, out);

        out.close();
    }

    /**
     * Solver class responsible for the logic of the digit matching problem.
     */
    static class DigitMatchingSolver {
        private int n;
        private boolean[][] hasDigit;

        /**
         * Solves the problem for a single test case.
         *
         * @param in  Scanner for input
         * @param out PrintWriter for output
         */
        public void solve(Scanner in, PrintWriter out) {
            n = in.nextInt();

            // hasDigit[i][d] indicates if the i-th set contains digit d
            // Default boolean values are false, so explicit initialization is not needed.
            hasDigit = new boolean[n][10];

            // Read the sets of digits
            // Each of the n sets contains 6 integers
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < 6; j++) {
                    int digit = in.nextInt();
                    hasDigit[i][digit] = true;
                }
            }

            int maxValidNumber = 0;
            boolean[] usedRows = new boolean[n];

            // Iterate through numbers 1 to 999.
            // We look for the largest number 'k' such that all numbers 1..k
            // can be formed by the available digit sets.
            for (int candidate = 1; candidate <= 999; candidate++) {
                List<Integer> digits = extractDigits(candidate);

                // Reset the tracking array for the new candidate number
                Arrays.fill(usedRows, false);

                if (canMatchDigits(digits, 0, usedRows)) {
                    maxValidNumber = candidate;
                } else {
                    // If the current candidate cannot be formed, stop.
                    // This preserves the original logic of finding the longest valid prefix.
                    break;
                }
            }

            out.println(maxValidNumber);
        }

        /**
         * Extracts digits from an integer into a list.
         * Digits are added in reverse order (least significant first).
         *
         * @param number The integer to extract digits from
         * @return List of digits
         */
        private List<Integer> extractDigits(int number) {
            List<Integer> digits = new ArrayList<>();
            // Since the loop starts at 1, number will never be 0 here.
            while (number > 0) {
                digits.add(number % 10);
                number /= 10;
            }
            return digits;
        }

        /**
         * Checks if the required digits can be matched to distinct rows in hasDigit.
         * Uses backtracking to find a valid assignment.
         *
         * @param digits      List of digits required to form the number
         * @param digitIndex  Current index in the digits list being processed
         * @param usedRows    Boolean array tracking which rows (sets) have been used
         * @return true if a valid matching exists, false otherwise
         */
        private boolean canMatchDigits(List<Integer> digits, int digitIndex, boolean[] usedRows) {
            // Base case: All digits have been successfully matched
            if (digitIndex == digits.size()) {
                return true;
            }

            int targetDigit = digits.get(digitIndex);

            // Try to find an unused row that contains the target digit
            for (int row = 0; row < n; row++) {
                if (!usedRows[row] && hasDigit[row][targetDigit]) {
                    usedRows[row] = true; // Mark row as used

                    // Recurse to match the next digit
                    if (canMatchDigits(digits, digitIndex + 1, usedRows)) {
                        return true;
                    }

                    // Backtrack: Unmark the row
                    usedRows[row] = false;
                }
            }

            return false;
        }
    }
}

import java.util.Scanner;

public class CF {
    public static void main(String[] args) {
        // Use try-with-resources to ensure the Scanner is closed properly
        try (Scanner scanner = new Scanner(System.in)) {
            if (!scanner.hasNextInt()) {
                return;
            }

            int n = scanner.nextInt();

            // Store the concatenated string for each of the n groups.
            // Each group consists of 6 integers.
            String[] lines = new String[n];
            StringBuilder[] builders = new StringBuilder[n];

            // Initialize StringBuilder instances
            for (int i = 0; i < n; i++) {
                builders[i] = new StringBuilder();
            }

            // Read 6 integers for each group and append to the corresponding StringBuilder.
            // Using StringBuilder is more efficient than string concatenation in loops.
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < 6; j++) {
                    if (scanner.hasNextInt()) {
                        builders[i].append(scanner.nextInt());
                    }
                }
                lines[i] = builders[i].toString();
            }

            // Process based on n
            switch (n) {
                case 1:
                    solveCase1(lines[0]);
                    break;
                case 2:
                    solveMultiGroup(lines);
                    break;
                case 3:
                    solveMultiGroup(lines);
                    break;
                default:
                    // The original code did not handle n > 3. 
                    // We maintain this behavior.
                    break;
            }
        }
    }

    /**
     * Solves the problem for n = 1.
     * Logic: Find smallest k such that String.valueOf(k) is a substring of the single line.
     */
    private static void solveCase1(String line) {
        int k = 1;
        while (true) {
            if (line.contains(String.valueOf(k))) {
                k++;
            } else {
                break;
            }
        }
        System.out.println(k - 1);
    }

    /**
     * Solves the problem for n >= 2 (specifically cases 2 and 3 in original code).
     * Logic:
     * - If k < 10: Check if digit k is present in ANY line.
     * - If k >= 10: Check if tens digit is in one line AND units digit in a DIFFERENT line.
     */
    private static void solveMultiGroup(String[] lines) {
        int n = lines.length;
        int k = 1;
        while (true) {
            boolean found = false;
            if (k < 10) {
                // Check if digit k exists in ANY line
                for (String line : lines) {
                    if (line.contains(String.valueOf(k))) {
                        found = true;
                        break;
                    }
                }
            } else {
                String tens = String.valueOf(k / 10);
                String units = String.valueOf(k % 10);

                // Check if there exist distinct lines i, j such that
                // tens is in lines[i] and units is in lines[j]
                outerLoop:
                for (int i = 0; i < n; i++) {
                    if (lines[i].contains(tens)) {
                        for (int j = 0; j < n; j++) {
                            if (i != j && lines[j].contains(units)) {
                                found = true;
                                break outerLoop;
                            }
                        }
                    }
                }
            }

            if (!found) {
                break;
            }
            k++;
        }
        System.out.println(k - 1);
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.OutputStream;
import java.io.PrintWriter;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.HashSet;
import java.util.List;
import java.util.NoSuchElementException;
import java.util.Set;
import java.util.StringTokenizer;
import java.util.TreeSet;

public class Main {

    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);

        new Solver().solve(1, in, out);
        out.close();
    }

    /**
     * Solves the problem by generating all possible numbers from the input rows
     * and finding the smallest positive integer that cannot be formed.
     */
    static class Solver {
        public void solve(int testNumber, InputReader in, PrintWriter out) {
            int n = in.nextInt();
            List<TreeSet<Integer>> rowDigits = new ArrayList<>(n);

            // Read n rows, each containing 6 digits
            for (int i = 0; i < n; i++) {
                TreeSet<Integer> digits = new TreeSet<>();
                for (int j = 0; j < 6; j++) {
                    digits.add(in.nextInt());
                }
                rowDigits.add(digits);
            }

            // Generate all possible numbers using backtracking
            Set<Integer> generatedNumbers = generateAllNumbers(rowDigits);

            // Find the smallest missing positive integer up to 999
            int smallestMissing = 0;
            for (int i = 1; i <= 999; i++) {
                if (!generatedNumbers.contains(i)) {
                    break;
                }
                smallestMissing = i;
            }
            out.println(smallestMissing);
        }

        /**
         * Entry point for the backtracking algorithm.
         */
        private Set<Integer> generateAllNumbers(List<TreeSet<Integer>> rowDigits) {
            boolean[] usedRows = new boolean[rowDigits.size()];
            Arrays.fill(usedRows, true);
            return backtrack(rowDigits, 0, usedRows, 0);
        }

        /**
         * Recursively generates numbers by picking digits from unused rows.
         *
         * @param rowDigits    List of digit sets for each row
         * @param depth        Current depth in the recursion tree
         * @param usedRows     Tracks which rows have been used in the current path
         * @param currentNumber Accumulated number being built
         * @return Set of all valid numbers generated from this state
         */
        private Set<Integer> backtrack(List<TreeSet<Integer>> rowDigits, int depth, 
                                       boolean[] usedRows, int currentNumber) {
            Set<Integer> results = new HashSet<>();

            // Base case: reached the end of the recursion depth
            if (depth == rowDigits.size()) {
                results.add(currentNumber);
                return results;
            }

            // Option 1: Skip the current depth level
            results.addAll(backtrack(rowDigits, depth + 1, usedRows, currentNumber));

            // Option 2: Pick any unused row at this depth
            for (int i = 0; i < rowDigits.size(); i++) {
                if (usedRows[i]) {
                    usedRows[i] = false; // Mark as used
                    for (int digit : rowDigits.get(i)) {
                        results.addAll(backtrack(rowDigits, depth + 1, usedRows, 
                                                 currentNumber * 10 + digit));
                    }
                    usedRows[i] = true; // Backtrack: unmark for other branches
                }
            }
            return results;
        }
    }

    /**
     * Fast input reader for competitive programming and performance-critical applications.
     */
    static class InputReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) {
                        return null;
                    }
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input", e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            String token = next();
            if (token == null) {
                throw new NoSuchElementException("End of input reached");
            }
            return Integer.parseInt(token);
        }
    }
}

import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) {
        FastScanner in = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out);
        new CubeMashaSolver().solve(1, in, out);
        out.close();
    }

    static class CubeMashaSolver {
        public void solve(int testNumber, FastScanner in, PrintWriter out) {
            int n = in.nextInt();
            List<Set<Integer>> cubeFaces = new ArrayList<>(n);

            // Read n cubes, each with 6 faces
            for (int i = 0; i < n; i++) {
                Set<Integer> faces = new HashSet<>();
                for (int j = 0; j < 6; j++) {
                    faces.add(in.nextInt());
                }
                cubeFaces.add(faces);
            }

            // Calculate upper bound for search space (10^n)
            int maxVal = 1;
            for (int i = 0; i < n; i++) maxVal *= 10;

            int ans = 0;
            // Precompute all valid permutations of cube indices
            List<int[]> permutations = generatePermutations(n);

            // Find the smallest number that cannot be formed by any valid digit-to-cube assignment
            for (int i = 1; i < maxVal; i++) {
                if (isValidNumber(i, n, cubeFaces, permutations)) {
                    continue;
                }
                ans = i;
                break;
            }

            out.println(ans - 1);
        }

        private boolean isValidNumber(int number, int n, List<Set<Integer>> cubeFaces, List<int[]> permutations) {
            int temp = number;
            int[] digits = new int[n];

            // Extract digits from least significant to most significant
            for (int d = 0; d < n; d++) {
                digits[d] = temp % 10;
                temp /= 10;
            }

            // Check if any permutation of cubes matches the digits
            for (int[] perm : permutations) {
                boolean match = true;
                for (int d = 0; d < n; d++) {
                    if (!cubeFaces.get(perm[d]).contains(digits[d])) {
                        match = false;
                        break;
                    }
                }
                if (match) return true;
            }
            return false;
        }

        private static List<int[]> generatePermutations(int n) {
            List<int[]> result = new ArrayList<>();
            int[] indices = new int[n];
            for (int i = 0; i < n; i++) indices[i] = i;
            permute(indices, 0, result);
            return result;
        }

        private static void permute(int[] arr, int start, List<int[]> result) {
            if (start == arr.length) {
                result.add(arr.clone());
                return;
            }
            for (int i = start; i < arr.length; i++) {
                swap(arr, start, i);
                permute(arr, start + 1, result);
                swap(arr, start, i);
            }
        }

        private static void swap(int[] arr, int i, int j) {
            int temp = arr[i];
            arr[i] = arr[j];
            arr[j] = temp;
        }
    }

    static class FastScanner {
        private final BufferedInputStream in;
        private final byte[] buffer = new byte[4096];
        private int bufferIndex = 0;
        private int bytesRead = 0;

        public FastScanner(InputStream inputStream) {
            this.in = new BufferedInputStream(inputStream);
        }

        private int readByte() {
            if (bufferIndex >= bytesRead) {
                bufferIndex = 0;
                try {
                    bytesRead = in.read(buffer);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
                if (bytesRead <= 0) return -1;
            }
            return buffer[bufferIndex++];
        }

        public int nextInt() {
            int c = readByte();
            while (isWhitespace(c)) c = readByte();

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = readByte();
            }

            int res = 0;
            while (!isWhitespace(c)) {
                if (c >= '0' && c <= '9') {
                    res = res * 10 + (c - '0');
                }
                c = readByte();
            }
            return res * sign;
        }

        private boolean isWhitespace(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }
    }
}

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import java.util.Scanner;

public class Solution {
    /**
     * Enum representing grid movement directions with their row/column deltas.
     * Eliminates magic strings and repetitive conditional logic.
     */
    enum Direction {
        UP(-1, 0), DOWN(1, 0), LEFT(0, -1), RIGHT(0, 1);

        final int deltaRow;
        final int deltaCol;

        Direction(int deltaRow, int deltaCol) {
            this.deltaRow = deltaRow;
            this.deltaCol = deltaCol;
        }
    }

    public static void main(String[] args) {
        // Use try-with-resources to ensure Scanner is properly closed
        try (Scanner scanner = new Scanner(System.in)) {
            if (!scanner.hasNextInt()) return;

            int rows = scanner.nextInt();
            int cols = scanner.nextInt();

            String[] grid = new String[rows];
            int startRow = -1;
            int startCol = -1;

            // Parse grid and locate start position
            for (int i = 0; i < rows; i++) {
                grid[i] = scanner.next();
                int sIndex = grid[i].indexOf('S');
                if (sIndex != -1) {
                    startRow = i;
                    startCol = sIndex;
                }
            }

            String path = scanner.next();

            // Generate all 24 permutations of direction assignments for digits 0-3
            List<Direction[]> permutations = generatePermutations();
            int validCount = 0;

            // Test each permutation against the path
            for (Direction[] dirMapping : permutations) {
                if (simulatePath(grid, path, dirMapping, startRow, startCol, rows, cols)) {
                    validCount++;
                }
            }

            System.out.println(validCount);
        }
    }

    /**
     * Recursively generates all permutations of the Direction enum values.
     */
    private static List<Direction[]> generatePermutations() {
        List<Direction[]> result = new ArrayList<>();
        List<Direction> directions = new ArrayList<>(Arrays.asList(Direction.values()));
        permute(directions, 0, result);
        return result;
    }

    private static void permute(List<Direction> list, int k, List<Direction[]> result) {
        if (k == list.size()) {
            result.add(list.toArray(new Direction[0]));
        } else {
            for (int i = k; i < list.size(); i++) {
                Collections.swap(list, i, k);
                permute(list, k + 1, result);
                Collections.swap(list, i, k);
            }
        }
    }

    /**
     * Simulates movement along the path using a given direction mapping.
     * Returns true if 'E' is reached, false otherwise.
     */
    private static boolean simulatePath(String[] grid, String path, Direction[] dirMapping,
                                        int startRow, int startCol, int rows, int cols) {
        int currentRow = startRow;
        int currentCol = startCol;

        for (int i = 0; i < path.length(); i++) {
            char digit = path.charAt(i);
            if (digit < '0' || digit > '3') {
                return false; // Invalid path character
            }

            Direction direction = dirMapping[digit - '0'];
            int nextRow = currentRow + direction.deltaRow;
            int nextCol = currentCol + direction.deltaCol;

            // Boundary check
            if (nextRow < 0 || nextRow >= rows || nextCol < 0 || nextCol >= cols) {
                return false;
            }

            char cell = grid[nextRow].charAt(nextCol);

            // Obstacle check
            if (cell == '#') {
                return false;
            }

            // Goal check
            if (cell == 'E') {
                return true;
            }

            // Update position
            currentRow = nextRow;
            currentCol = nextCol;
        }

        return false;
    }
}

import java.io.*;
import java.util.*;

public class GridPathSolver {

    // Direction vectors: 0=Down, 1=Up, 2=Right, 3=Left
    private static final int[] DR = {1, -1, 0, 0};
    private static final int[] DC = {0, 0, 1, -1};

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out);
        try {
            new GridPathSolver().solve(scanner, out);
        } finally {
            out.flush();
        }
    }

    void solve(FastScanner sc, PrintWriter out) {
        // Read grid dimensions
        int rows = sc.nextInt();
        int cols = sc.nextInt();

        char[][] grid = new char[rows][cols];
        int startRow = 0, startCol = 0, endRow = 0, endCol = 0;

        // Parse grid and locate start ('S') and end ('E') points
        for (int i = 0; i < rows; i++) {
            String rowStr = sc.next();
            grid[i] = rowStr.toCharArray();
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == 'S') {
                    startRow = i;
                    startCol = j;
                } else if (grid[i][j] == 'E') {
                    endRow = i;
                    endCol = j;
                }
            }
        }

        // Read movement instructions string
        String instructions = sc.next();

        // Count how many direction assignments successfully reach the target
        int successfulAssignments = countSuccessfulDirectionMappings(rows, cols, grid,
                startRow, startCol, endRow, endCol, instructions);
        out.println(successfulAssignments);
    }

    /**
     * Generates all permutations of 4 distinct directions and counts valid ones.
     */
    private int countSuccessfulDirectionMappings(int n, int m, char[][] grid,
                                                 int startR, int startC, int endR, int endC,
                                                 String instructions) {
        int[] mapping = new int[4];
        return generateAndCheckMappings(mapping, 0, n, m, grid, startR, startC, endR, endC, instructions);
    }

    /**
     * Recursively generates permutations of direction indices [0,3] and checks path validity.
     */
    private int generateAndCheckMappings(int[] mapping, int idx, int n, int m, char[][] grid,
                                         int startR, int startC, int endR, int endC,
                                         String instructions) {
        // Base case: all 4 directions have been assigned
        if (idx == 4) {
            return simulatePath(n, m, grid, startR, startC, endR, endC, instructions, mapping) ? 1 : 0;
        }

        int count = 0;
        for (int dir = 0; dir < 4; dir++) {
            boolean used = false;
            for (int k = 0; k < idx; k++) {
                if (mapping[k] == dir) {
                    used = true;
                    break;
                }
            }
            if (!used) {
                mapping[idx] = dir;
                count += generateAndCheckMappings(mapping, idx + 1, n, m, grid, startR, startC, endR, endC, instructions);
            }
        }
        return count;
    }

    /**
     * Simulates movement along the instruction string using the provided direction mapping.
     */
    private boolean simulatePath(int n, int m, char[][] grid,
                                 int startR, int startC, int endR, int endC,
                                 String instructions, int[] dirMapping) {
        int r = startR;
        int c = startC;
        int len = instructions.length();

        for (int i = 0; i < len; i++) {
            // Check if target reached before processing current instruction
            if (r == endR && c == endC) {
                return true;
            }
            // Check bounds and obstacles
            if (!isValidPos(r, c, n, m) || grid[r][c] == '#') {
                return false;
            }

            int digit = instructions.charAt(i) - '0';
            int directionIndex = dirMapping[digit];
            r += DR[directionIndex];
            c += DC[directionIndex];
        }
        // Check if target reached after processing all instructions
        return r == endR && c == endC;
    }

    private boolean isValidPos(int r, int c, int n, int m) {
        return r >= 0 && r < n && c >= 0 && c < m;
    }

    /**
     * Standard fast I/O helper for competitive programming and efficient text parsing.
     */
    static class FastScanner {
        BufferedReader br;
        StringTokenizer st;

        FastScanner(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Input parsing failed", e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;

public class Codeforces {

    // Direction mappings: 0=Left, 1=Right, 2=Up, 3=Down
    private static final int[] DELTA_ROW = {0, 0, -1, 1};
    private static final int[] DELTA_COL = {-1, 1, 0, 0};

    private static final char START_CHAR = 'S';
    private static final char END_CHAR = 'E';
    private static final char WALL_CHAR = '#';

    private int rows;
    private int cols;
    private char[][] grid;
    private int startRow, startCol;
    private int endRow, endCol;
    private String directionSequence;

    public static void main(String[] args) throws IOException {
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(System.in))) {
            Codeforces solver = new Codeforces(reader);
            System.out.println(solver.solve());
        }
    }

    public Codeforces(BufferedReader reader) throws IOException {
        parseInput(reader);
    }

    private void parseInput(BufferedReader reader) throws IOException {
        String[] tokens = reader.readLine().trim().split("\\s+");
        this.rows = Integer.parseInt(tokens[0]);
        this.cols = Integer.parseInt(tokens[1]);

        grid = new char[rows][];
        for (int i = 0; i < rows; i++) {
            String line = reader.readLine();
            grid[i] = line.toCharArray();

            int startColIdx = line.indexOf(START_CHAR);
            if (startColIdx != -1) {
                startRow = i;
                startCol = startColIdx;
            }

            int endColIdx = line.indexOf(END_CHAR);
            if (endColIdx != -1) {
                endRow = i;
                endCol = endColIdx;
            }
        }
        this.directionSequence = reader.readLine().trim();
    }

    public int solve() {
        int[] perm = new int[4];
        boolean[] used = new boolean[4];
        return generatePermutations(perm, used, 0);
    }

    /**
     * Generates all permutations of direction indices [0,1,2,3] and counts
     * how many successfully navigate from 'S' to 'E' using the given sequence.
     */
    private int generatePermutations(int[] perm, boolean[] used, int index) {
        if (index == 4) {
            return canReachEnd(perm) ? 1 : 0;
        }

        int count = 0;
        for (int i = 0; i < 4; i++) {
            if (!used[i]) {
                used[i] = true;
                perm[index] = i;
                count += generatePermutations(perm, used, index + 1);
                used[i] = false;
            }
        }
        return count;
    }

    /**
     * Simulates path traversal for a given direction permutation.
     * Returns true if the path reaches the end point within the sequence length.
     */
    private boolean canReachEnd(int[] perm) {
        if (startRow == endRow && startCol == endCol) {
            return true;
        }

        int r = startRow;
        int c = startCol;

        for (int i = 0; i < directionSequence.length(); i++) {
            int dirIndex = directionSequence.charAt(i) - '0';
            if (dirIndex < 0 || dirIndex > 3) {
                return false; // Invalid direction character in sequence
            }

            int actualDir = perm[dirIndex];
            r += DELTA_ROW[actualDir];
            c += DELTA_COL[actualDir];

            if (r == endRow && c == endCol) {
                return true;
            }
            if (r < 0 || r >= rows || c < 0 || c >= cols || grid[r][c] == WALL_CHAR) {
                return false;
            }
        }
        return false;
    }
}

import java.util.Scanner;

/**
 * A refactored solution for the Maze Path Counter problem.
 * 
 * Refactoring Improvements:
 * 1. Encapsulation: Moved static fields to instance fields to remove global state.
 * 2. Readability: Renamed variables (e.g., 'nRow' -> 'rows', 'ops' -> 'directionMapping')
 *    and split logic into smaller, descriptive methods.
 * 3. Resource Management: Used try-with-resources for the Scanner.
 * 4. Maintainability: Extracted logic for direction deltas and boundary checks.
 */
public class Main {

    // Instance variables to hold the state of the maze and solver
    private char[][] maze;
    private int rows, cols;
    private int startRow, startCol;
    private int endRow, endCol;
    private int[] moveSequence; // Stores indices (0-3) representing directions

    public static void main(String[] args) {
        // Use try-with-resources to ensure the Scanner is closed automatically
        try (Scanner scanner = new Scanner(System.in)) {
            Main solver = new Main();
            // Read input and run the solver
            if (solver.readInput(scanner)) {
                solver.solve();
            }
        }
    }

    /**
     * Reads the maze configuration and move sequence from the input.
     */
    private boolean readInput(Scanner scanner) {
        if (!scanner.hasNextInt()) return false;
        rows = scanner.nextInt();
        cols = scanner.nextInt();

        maze = new char[rows][cols];

        for (int i = 0; i < rows; i++) {
            if (!scanner.hasNext()) return false;
            String rowStr = scanner.next();
            maze[i] = rowStr.toCharArray();

            for (int j = 0; j < cols; j++) {
                char cell = maze[i][j];
                if (cell == 'S') {
                    startRow = i;
                    startCol = j;
                } else if (cell == 'E') {
                    endRow = i;
                    endCol = j;
                }
            }
        }

        if (!scanner.hasNext()) return false;
        String moveStr = scanner.next();
        moveSequence = new int[moveStr.length()];
        for (int i = 0; i < moveStr.length(); i++) {
            // Convert char digit to integer index
            moveSequence[i] = moveStr.charAt(i) - '0';
        }
        return true;
    }

    /**
     * Main logic to iterate through permutations and count valid paths.
     */
    private void solve() {
        // Initial permutation of directions: Left, Right, Down, Up
        // These correspond to indices 0, 1, 2, 3 in the moveSequence
        char[] currentDirectionMapping = {'a', 'd', 's', 'w'};
        int validPathCount = 0;

        // Iterate through all permutations of the direction mapping
        do {
            if (isPathValid(currentDirectionMapping)) {
                validPathCount++;
            }
        } while (nextPermutation(currentDirectionMapping, 0, currentDirectionMapping.length));

        System.out.println(validPathCount);
    }

    /**
     * Validates if the sequence of moves leads to the exit 'E'
     * without hitting walls '#' or going out of bounds.
     * 
     * @param directionMapping An array where index 0-3 maps to a specific direction char
     * @return true if the path reaches 'E', false otherwise
     */
    private boolean isPathValid(char[] directionMapping) {
        int currentRow = startRow;
        int currentCol = startCol;

        for (int moveIndex : moveSequence) {
            // Ensure index is within bounds (0-3)
            if (moveIndex < 0 || moveIndex >= 4) {
                return false;
            }

            char directionChar = directionMapping[moveIndex];

            // Determine movement deltas based on direction character
            int dr = 0;
            int dc = 0;
            switch (directionChar) {
                case 'a': dc = -1; break; // Left
                case 'd': dc = 1;  break; // Right
                case 's': dr = 1;  break; // Down
                case 'w': dr = -1; break; // Up
            }

            currentRow += dr;
            currentCol += dc;

            // Check bounds
            if (!isWithinBounds(currentRow, currentCol)) {
                return false;
            }

            // Check for wall
            if (maze[currentRow][currentCol] == '#') {
                return false;
            }

            // Check for exit
            if (currentRow == endRow && currentCol == endCol) {
                return true;
            }
        }
        return false;
    }

    private boolean isWithinBounds(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /**
     * Generates the next lexicographical permutation of the array.
     * Modifies the array in place.
     * 
     * @param str The character array to permute
     * @param start The starting index
     * @param end The ending index (exclusive)
     * @return true if the next permutation exists, false if it was the last one
     */
    private boolean nextPermutation(char[] str, int start, int end) {
        if (str == null || str.length <= 1) {
            return false;
        }

        // Find the first decreasing element from the end
        int i = end - 2;
        while (i >= start && str[i] >= str[i + 1]) {
            i--;
        }

        // If no such element is found, we are at the last permutation
        if (i == start - 1) {
            return false;
        }

        // Find the smallest element greater than str[i] to the right of i
        int j = i + 1;
        while (j < end && str[j] > str[i]) {
            j++;
        }

        // Swap the pivot with the successor
        swap(str, i, j - 1);

        // Reverse the suffix starting at i+1
        i++;
        int k = end - 1;
        while (i < k) {
            swap(str, i, k);
            i++;
            k--;
        }

        return true;
    }

    private void swap(char[] str, int a, int b) {
        char temp = str[a];
        str[a] = str[b];
        str[b] = temp;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.Reader;
import java.util.ArrayList;
import java.util.List;
import java.util.StringTokenizer;

public class ProblemB {
    // Direction offsets: 0=Right, 1=Left, 2=Down, 3=Up
    private static final int[][] DIRECTIONS = {
        {0, 1},  // 0
        {0, -1}, // 1
        {1, 0},  // 2
        {-1, 0}  // 3
    };

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner();
        int n = scanner.nextInt();
        int m = scanner.nextInt();

        char[][] grid = new char[n][m];
        for (int r = 0; r < n; r++) {
            grid[r] = scanner.next().toCharArray();
        }

        int[] start = findCoordinate(grid, 'S');
        // 'end' is found for completeness but not strictly needed for path validation
        findCoordinate(grid, 'E'); 

        String instructionTemplate = scanner.next();

        // Generate all 24 permutations of direction indices [0, 1, 2, 3]
        List<int[]> permutations = generatePermutations();

        int validPathCount = 0;
        for (int[] perm : permutations) {
            String mappedInstructions = mapInstructions(instructionTemplate, perm);
            if (canReachEnd(mappedInstructions, start, grid)) {
                validPathCount++;
            }
        }

        System.out.println(validPathCount);
    }

    /**
     * Finds the coordinates of a target character in the grid.
     */
    private static int[] findCoordinate(char[][] grid, char target) {
        for (int r = 0; r < grid.length; r++) {
            for (int c = 0; c < grid[r].length; c++) {
                if (grid[r][c] == target) {
                    return new int[]{r, c};
                }
            }
        }
        throw new IllegalArgumentException("Target character '" + target + "' not found in grid.");
    }

    /**
     * Generates all permutations of the array [0, 1, 2, 3] using backtracking.
     */
    private static List<int[]> generatePermutations() {
        List<int[]> result = new ArrayList<>();
        int[] nums = {0, 1, 2, 3};
        permute(nums, 0, result);
        return result;
    }

    private static void permute(int[] nums, int start, List<int[]> result) {
        if (start == nums.length) {
            result.add(nums.clone());
            return;
        }
        for (int i = start; i < nums.length; i++) {
            swap(nums, start, i);
            permute(nums, start + 1, result);
            swap(nums, start, i); // backtrack
        }
    }

    private static void swap(int[] nums, int i, int j) {
        int temp = nums[i];
        nums[i] = nums[j];
        nums[j] = temp;
    }

    /**
     * Maps the instruction template to a new instruction string based on the direction permutation.
     * Each digit in the template is replaced by the corresponding value from the permutation array.
     */
    private static String mapInstructions(String template, int[] perm) {
        StringBuilder sb = new StringBuilder(template.length());
        for (int i = 0; i < template.length(); i++) {
            int digitIndex = template.charAt(i) - '0';
            sb.append((char) ('0' + perm[digitIndex]));
        }
        return sb.toString();
    }

    /**
     * Simulates movement along the instruction string to check if 'E' is reachable.
     */
    private static boolean canReachEnd(String instructions, int[] start, char[][] grid) {
        int r = start[0];
        int c = start[1];
        int rows = grid.length;
        int cols = grid[0].length;

        for (int i = 0; i < instructions.length(); i++) {
            int dirIndex = instructions.charAt(i) - '0';
            r += DIRECTIONS[dirIndex][0];
            c += DIRECTIONS[dirIndex][1];

            // Explicit bounds checking replaces the original try-catch anti-pattern
            if (r < 0 || r >= rows || c < 0 || c >= cols) {
                return false;
            }

            if (grid[r][c] == 'E') {
                return true;
            }
            if (grid[r][c] == '#') {
                return false;
            }
        }
        return false;
    }

    /**
     * Efficient input scanner for fast I/O operations.
     */
    public static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner() {
            this(new InputStreamReader(System.in));
        }

        public FastScanner(Reader in) {
            br = new BufferedReader(in);
        }

        public String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input", e);
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            String s = next();
            if (s == null) throw new RuntimeException("Unexpected end of input");
            return Integer.parseInt(s);
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayList;
import java.util.List;
import java.util.StringTokenizer;

/**
 * Solves a grid pathfinding problem by testing all permutations of direction mappings.
 * Replaces digits 0-3 in a move sequence with a permutation of {0,1,2,3} and checks
 * if the path reaches 'E' from 'S' without hitting obstacles or boundaries.
 */
public class GridPathSolver {
    // Grid characters
    private static final char START_CHAR = 'S';
    private static final char END_CHAR = 'E';
    private static final char OBSTACLE_CHAR = '#';

    // Direction deltas: 0=Up, 1=Down, 2=Right, 3=Left
    private static final int[] DR = {-1, 1, 0, 0};
    private static final int[] DC = {0, 0, 1, -1};

    public static void main(String[] args) throws IOException {
        // Use try-with-resources for automatic resource management
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(System.in))) {
            String line = reader.readLine();
            if (line == null) return;

            StringTokenizer st = new StringTokenizer(line);
            int rows = Integer.parseInt(st.nextToken());
            int cols = Integer.parseInt(st.nextToken());

            char[][] grid = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                String rowStr = reader.readLine();
                grid[i] = (rowStr != null) ? rowStr.toCharArray() : new char[cols];
            }

            String moveSequenceStr = reader.readLine();
            if (moveSequenceStr == null) moveSequenceStr = "";
            int[] moveSequence = new int[moveSequenceStr.length()];
            for (int i = 0; i < moveSequenceStr.length(); i++) {
                moveSequence[i] = moveSequenceStr.charAt(i) - '0';
            }

            int[] start = findStart(grid);
            if (start[0] == -1) {
                System.out.println(0);
                return;
            }

            int validCount = countValidPermutations(grid, start, moveSequence);
            System.out.println(validCount);
        }
    }

    /**
     * Locates the starting position 'S' in the grid.
     */
    private static int[] findStart(char[][] grid) {
        for (int r = 0; r < grid.length; r++) {
            for (int c = 0; c < grid[0].length; c++) {
                if (grid[r][c] == START_CHAR) {
                    return new int[]{r, c};
                }
            }
        }
        return new int[]{-1, -1};
    }

    /**
     * Counts how many direction permutations allow successful navigation to 'E'.
     */
    private static int countValidPermutations(char[][] grid, int[] start, int[] moveSequence) {
        List<int[]> permutations = generatePermutations();
        int validCount = 0;

        for (int[] perm : permutations) {
            int[] mappedMoves = mapMoves(moveSequence, perm);
            if (canNavigate(grid, start, mappedMoves)) {
                validCount++;
            }
        }
        return validCount;
    }

    /**
     * Maps the raw digit sequence to actual direction indices using a permutation.
     */
    private static int[] mapMoves(int[] moveSequence, int[] perm) {
        int[] mapped = new int[moveSequence.length];
        for (int i = 0; i < moveSequence.length; i++) {
            mapped[i] = perm[moveSequence[i]];
        }
        return mapped;
    }

    /**
     * Checks if the path defined by moves reaches the end 'E' without failures.
     */
    private static boolean canNavigate(char[][] grid, int[] start, int[] moves) {
        int r = start[0];
        int c = start[1];
        int rows = grid.length;
        int cols = grid[0].length;

        for (int move : moves) {
            r += DR[move];
            c += DC[move];

            // Boundary check
            if (r < 0 || r >= rows || c < 0 || c >= cols) return false;
            // Obstacle check
            if (grid[r][c] == OBSTACLE_CHAR) return false;
            // Success check
            if (grid[r][c] == END_CHAR) return true;
        }
        return false;
    }

    /**
     * Generates all 24 permutations of {0, 1, 2, 3}.
     */
    private static List<int[]> generatePermutations() {
        List<int[]> permutations = new ArrayList<>();
        int[] current = new int[4];
        boolean[] used = new boolean[4];
        generatePermutationsHelper(permutations, current, used, 0);
        return permutations;
    }

    private static void generatePermutationsHelper(List<int[]> permutations, int[] current, boolean[] used, int index) {
        if (index == 4) {
            permutations.add(current.clone());
            return;
        }
        for (int i = 0; i < 4; i++) {
            if (!used[i]) {
                used[i] = true;
                current[index] = i;
                generatePermutationsHelper(permutations, current, used, index + 1);
                used[i] = false;
            }
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

public class PathPermutationSolver {

    // Direction vectors: Left, Right, Down, Up
    private static final int[] DELTA_X = {-1, 1, 0, 0};
    private static final int[] DELTA_Y = {0, 0, -1, 1};

    private final int rows;
    private final int cols;
    private final char[][] grid;
    private int startX, startY, endX, endY;
    private final String directionPattern;
    private int validPermutationCount;

    public PathPermutationSolver(FastScanner scanner) throws IOException {
        this.rows = scanner.nextInt();
        this.cols = scanner.nextInt();
        this.grid = new char[rows][cols];
        this.directionPattern = scanner.next();

        for (int r = 0; r < rows; r++) {
            String line = scanner.next();
            for (int c = 0; c < line.length(); c++) {
                grid[r][c] = line.charAt(c);
                if (grid[r][c] == 'S') {
                    startX = c;
                    startY = r;
                } else if (grid[r][c] == 'E') {
                    endX = c;
                    endY = r;
                }
            }
        }
    }

    public void solve() {
        int[] perm = new int[4];
        boolean[] used = new boolean[4];
        generatePermutations(perm, used, 0);
        System.out.println(validPermutationCount);
    }

    private void generatePermutations(int[] perm, boolean[] used, int index) {
        if (index == perm.length) {
            StringBuilder path = new StringBuilder(directionPattern.length());
            for (int i = 0; i < directionPattern.length(); i++) {
                int digit = directionPattern.charAt(i) - '0';
                path.append(perm[digit]);
            }
            validPermutationCount += simulatePath(path.toString());
        } else {
            for (int i = 0; i < perm.length; i++) {
                if (!used[i]) {
                    perm[index] = i;
                    used[i] = true;
                    generatePermutations(perm, used, index + 1);
                    used[i] = false;
                }
            }
        }
    }

    private int simulatePath(String path) {
        int curX = startX;
        int curY = startY;
        for (int i = 0; i < path.length(); i++) {
            int dir = path.charAt(i) - '0';
            int nextX = curX + DELTA_X[dir];
            int nextY = curY + DELTA_Y[dir];

            if (!isCellValid(nextX, nextY)) {
                return 0;
            }
            curX = nextX;
            curY = nextY;

            if (grid[curY][curX] == 'E') {
                return 1;
            }
        }
        return (curX == endX && curY == endY) ? 1 : 0;
    }

    private boolean isCellValid(int x, int y) {
        return x >= 0 && x < cols && y >= 0 && y < rows && grid[y][x] != '#';
    }

    private static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
            st = new StringTokenizer("");
        }

        public String next() throws IOException {
            while (!st.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) {
                    return null;
                }
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

        public int nextInt() throws IOException {
            String s = next();
            return (s == null) ? 0 : Integer.parseInt(s);
        }

        public long nextLong() throws IOException {
            String s = next();
            return (s == null) ? 0L : Long.parseLong(s);
        }
    }

    public static void main(String[] args) throws IOException {
        FastScanner scanner = new FastScanner(System.in);
        PathPermutationSolver solver = new PathPermutationSolver(scanner);
        solver.solve();
    }
}

import java.util.Scanner;

public class Main {
    // All permutations of "0123" representing direction mappings
    private static final String[] PERMUTATIONS = {
        "1230", "1203", "1320", "1302", "1023", "1032",
        "2130", "2103", "2310", "2301", "2013", "2031",
        "3210", "3201", "3120", "3102", "3021", "3012",
        "0231", "0213", "0321", "0312", "0123", "0132"
    };

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            if (!scanner.hasNextInt()) return;
            int rows = scanner.nextInt();
            int cols = scanner.nextInt();

            char[][] grid = new char[rows][cols];
            int startRow = -1;
            int startCol = -1;

            // Read grid and locate starting position 'S'
            for (int i = 0; i < rows; i++) {
                String line = scanner.next();
                for (int j = 0; j < cols; j++) {
                    grid[i][j] = line.charAt(j);
                    if (grid[i][j] == 'S') {
                        startRow = i;
                        startCol = j;
                    }
                }
            }

            String pathString = scanner.next();
            int totalMatches = 0;

            // Test each permutation mapping
            for (String perm : PERMUTATIONS) {
                totalMatches += navigate(grid, startRow, startCol, pathString, perm);
            }

            System.out.println(totalMatches);
        }
    }

    /**
     * Navigates the grid according to a specific direction permutation mapping.
     *
     * @param grid The 2D character grid
     * @param startRow Starting row index
     * @param startCol Starting column index
     * @param pathString Sequence of characters to process
     * @param perm Permutation string defining character-to-direction mapping
     * @return Number of times 'E' was reached during navigation
     */
    private static int navigate(char[][] grid, int startRow, int startCol, String pathString, String perm) {
        int h = startRow;
        int f = startCol;
        int count = 0;

        for (int i = 0; i < pathString.length(); i++) {
            char currentChar = pathString.charAt(i);
            int dirIdx = perm.indexOf(currentChar);

            int nextH = h;
            int nextF = f;

            // Map permutation index to direction
            switch (dirIdx) {
                case 0: nextH = h - 1; break; // Up
                case 1: nextF = f - 1; break; // Left
                case 2: nextF = f + 1; break; // Right
                case 3: nextH = h + 1; break; // Down
                default: continue; // Character not in permutation, skip
            }

            // Check bounds before moving (replaces original try-catch anti-pattern)
            if (!isWithinBounds(grid, nextH, nextF)) {
                break;
            }

            h = nextH;
            f = nextF;

            if (grid[h][f] == '#') {
                break; // Blocked by wall
            }
            if (grid[h][f] == 'E') {
                count++;
                break; // Reached target
            }
        }
        return count;
    }

    private static boolean isWithinBounds(char[][] grid, int h, int f) {
        return h >= 0 && h < grid.length && f >= 0 && f < grid[0].length;
    }
}

import java.util.Scanner;

/**
 * A refactored solution for the grid pathfinding problem.
 * 
 * Improvements made:
 * 1. Encapsulation: Moved static variables into instance fields to allow for 
 *    multiple instances and easier state management.
 * 2. Naming Conventions: Renamed variables to be descriptive (e.g., 'pic' -> 'grid', 
 *    'rank' -> 'directionMapping').
 * 3. Data Structures: Changed 'pic' from String[] to char[][] for better performance 
 *    and cleaner character access.
 * 4. Logic Separation: Separated input parsing, permutation generation, and path 
 *    simulation into distinct methods.
 * 5. Resource Management: Used try-with-resources for the Scanner.
 * 6. Magic Numbers: Replaced hardcoded array sizes with dynamic allocation or constants.
 */
public class Main {

    // Constants for grid directions: Right, Down, Left, Up
    private static final int[][] DIRECTIONS = {
        {0, 1},   // 0: Right
        {1, 0},   // 1: Down
        {0, -1},  // 2: Left
        {-1, 0}   // 3: Up
    };

    // Grid properties
    private int rows;
    private int cols;
    private char[][] grid;
    private int startRow;
    private int startCol;

    // Input data
    private String instructions;

    // Results
    private int validSolutionCount = 0;

    // Permutation tracking
    private boolean[] usedDirections = new boolean[4];
    private int[] directionMapping = new int[4];

    public static void main(String[] args) {
        Main solver = new Main();
        solver.run();
    }

    private void run() {
        // Use try-with-resources to ensure Scanner is closed
        try (Scanner scanner = new Scanner(System.in)) {
            if (!scanner.hasNextInt()) return;

            this.rows = scanner.nextInt();
            this.cols = scanner.nextInt();

            // Initialize grid dynamically based on input dimensions
            this.grid = new char[rows][cols];

            // Read grid and find Start position
            for (int i = 0; i < rows; i++) {
                String rowStr = scanner.next();
                for (int j = 0; j < rowStr.length() && j < cols; j++) {
                    this.grid[i][j] = rowStr.charAt(j);
                    if (this.grid[i][j] == 'S') {
                        this.startRow = i;
                        this.startCol = j;
                    }
                }
            }

            if (scanner.hasNext()) {
                this.instructions = scanner.next();
            }

            // Start solving
            generatePermutations(0);
            System.out.println(validSolutionCount);

        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    /**
     * Recursively generates all permutations of direction assignments.
     * @param index The current digit (0-3) being assigned a direction.
     */
    private void generatePermutations(int index) {
        // Base case: All digits 0-3 have been assigned a unique direction
        if (index == 4) {
            if (simulatePath()) {
                validSolutionCount++;
            }
            return;
        }

        // Try assigning each available direction to the current digit
        for (int i = 0; i < 4; i++) {
            if (!usedDirections[i]) {
                usedDirections[i] = true;
                directionMapping[index] = i; // Map digit 'index' to direction 'i'

                generatePermutations(index + 1);

                // Backtrack
                usedDirections[i] = false;
            }
        }
    }

    /**
     * Simulates the path based on the current direction mapping.
     * @return true if the path successfully reaches 'E', false otherwise.
     */
    private boolean simulatePath() {
        int r = startRow;
        int c = startCol;

        for (int i = 0; i < instructions.length(); i++) {
            char digitChar = instructions.charAt(i);
            int digit = digitChar - '0';

            // Get the direction index mapped to this digit
            int dirIndex = directionMapping[digit];
            int[] delta = DIRECTIONS[dirIndex];

            // Update coordinates
            r += delta[0];
            c += delta[1];

            // Boundary Check
            if (r < 0 || r >= rows || c < 0 || c >= cols) {
                return false;
            }

            char cell = grid[r][c];

            // Obstacle Check
            if (cell == '#') {
                return false;
            }

            // Success Check
            if (cell == 'E') {
                return true;
            }
        }

        // Path finished without reaching 'E'
        return false;
    }
}

import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

public class BuggyBotSolver {

    private static final String[] DIRECTIONS = {"U", "D", "R", "L"};

    public static void main(String[] args) {
        // Use try-with-resources to ensure Scanner is properly closed
        try (Scanner scanner = new Scanner(System.in)) {
            if (!scanner.hasNextLine()) {
                return;
            }

            // Parse grid dimensions safely
            String[] dimensions = scanner.nextLine().trim().split("\\s+");
            int rows = Integer.parseInt(dimensions[0]);
            int cols = Integer.parseInt(dimensions[1]);

            // Initialize grid and locate the starting position
            char[][] grid = new char[rows][cols];
            int startRow = -1;
            int startCol = -1;

            for (int i = 0; i < rows; i++) {
                String line = scanner.nextLine();
                for (int j = 0; j < cols; j++) {
                    grid[i][j] = line.charAt(j);
                    if (grid[i][j] == 'S') {
                        startRow = i;
                        startCol = j;
                    }
                }
            }

            // Read the sequence of move indices
            String moveSequence = scanner.nextLine().trim();

            // Generate all valid direction permutations
            List<String> permutations = generateAllPermutations();

            // Simulate paths and count successful routes to the exit
            int successfulPaths = simulatePaths(permutations, rows, cols, grid, startRow, startCol, moveSequence);
            System.out.println(successfulPaths);

        } catch (Exception e) {
            System.err.println("Error processing input: " + e.getMessage());
        }
    }

    /**
     * Entry point for permutation generation.
     * Returns a list of all 4! = 24 possible direction orderings.
     */
    private static List<String> generateAllPermutations() {
        List<String> results = new ArrayList<>();
        boolean[] used = new boolean[DIRECTIONS.length];
        generatePermutationsRecursive(DIRECTIONS, "", used, results);
        return results;
    }

    /**
     * Recursive backtracking method to generate permutations without repetition.
     * Replaces the original inefficient String.contains() check.
     */
    private static void generatePermutationsRecursive(String[] directions, String current, boolean[] used, List<String> results) {
        if (current.length() == directions.length) {
            results.add(current);
            return;
        }

        for (int i = 0; i < directions.length; i++) {
            if (!used[i]) {
                used[i] = true;
                generatePermutationsRecursive(directions, current + directions[i], used, results);
                used[i] = false; // Backtrack to explore other branches
            }
        }
    }

    /**
     * Iterates through each permutation and counts how many successfully reach the exit.
     */
    private static int simulatePaths(List<String> permutations, int rows, int cols, char[][] grid, int startRow, int startCol, String moveSequence) {
        int count = 0;
        for (String pathOrder : permutations) {
            if (reachesExit(pathOrder, moveSequence, rows, cols, grid, startRow, startCol)) {
                count++;
            }
        }
        return count;
    }

    /**
     * Simulates movement for a given permutation and move sequence.
     * Returns true if the exit 'E' is reached, false otherwise.
     */
    private static boolean reachesExit(String pathOrder, String moveSequence, int rows, int cols, char[][] grid, int startRow, int startCol) {
        int currentRow = startRow;
        int currentCol = startCol;

        for (int i = 0; i < moveSequence.length(); i++) {
            char sequenceChar = moveSequence.charAt(i);
            if (!Character.isDigit(sequenceChar)) {
                return false; // Invalid character in move sequence
            }

            int directionIndex = sequenceChar - '0';
            if (directionIndex < 0 || directionIndex >= pathOrder.length()) {
                return false; // Index out of bounds for the permutation
            }

            char move = pathOrder.charAt(directionIndex);

            // Update coordinates based on direction
            switch (move) {
                case 'U': currentRow--; break;
                case 'D': currentRow++; break;
                case 'L': currentCol--; break;
                case 'R': currentCol++; break;
                default: return false; // Unknown direction
            }

            // Check grid boundaries
            if (currentRow < 0 || currentRow >= rows || currentCol < 0 || currentCol >= cols) {
                return false;
            }

            // Check for walls
            if (grid[currentRow][currentCol] == '#') {
                return false;
            }

            // Check for exit
            if (grid[currentRow][currentCol] == 'E') {
                return true;
            }
        }
        return false;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.Locale;
import java.util.StringTokenizer;

/**
 * Refactored Grid Path Solver.
 * 
 * Improvements made:
 * 1. Renamed class to GridPathSolver for clarity.
 * 2. Replaced magic number arrays (dx, dy) with a Direction enum for type safety and readability.
 * 3. Encapsulated input/output handling and removed unused fields (fileName).
 * 4. Optimized character parsing (removed String allocation in loops).
 * 5. Improved variable naming (n/m -> rows/cols, lab -> grid, curPerm -> directionMapping).
 * 6. Added robust input reading with null checks.
 * 7. Organized code into logical sections with comments.
 */
public class GridPathSolver {

    // Fields for grid dimensions
    private int rows;
    private int cols;

    // Input/Output streams
    private BufferedReader br;
    private PrintWriter out;
    private StringTokenizer tokenizer;

    /**
     * Enum representing the four cardinal directions and their coordinate offsets.
     * The order corresponds to indices 0, 1, 2, 3 used in the original logic.
     * 0: DOWN (1, 0)
     * 1: UP (-1, 0)
     * 2: RIGHT (0, 1)
     * 3: LEFT (0, -1)
     */
    private enum Direction {
        DOWN(1, 0),
        UP(-1, 0),
        RIGHT(0, 1),
        LEFT(0, -1);

        private final int dx;
        private final int dy;

        Direction(int dx, int dy) {
            this.dx = dx;
            this.dy = dy;
        }

        public int getDx() { return dx; }
        public int getDy() { return dy; }
    }

    // Array mapping indices 0..3 to Direction enum values
    private static final Direction[] DIRECTIONS = {
        Direction.DOWN, Direction.UP, Direction.RIGHT, Direction.LEFT
    };

    public static void main(String[] args) {
        // Ensure consistent number formatting (e.g., dot vs comma)
        Locale.setDefault(Locale.US);
        new GridPathSolver().run();
    }

    /**
     * Initializes I/O streams and executes the solution.
     */
    public void run() {
        try {
            br = new BufferedReader(new InputStreamReader(System.in));
            out = new PrintWriter(System.out);
            solve();
        } catch (IOException e) {
            e.printStackTrace();
            System.exit(1);
        } finally {
            if (out != null) {
                out.close();
            }
        }
    }

    /**
     * Main logic to solve the grid path problem.
     */
    private void solve() throws IOException {
        this.rows = nextInt();
        this.cols = nextInt();

        boolean[][] grid = new boolean[rows][cols];
        int startRow = -1, startCol = -1;
        int endRow = -1, endCol = -1;

        // Parse the grid
        for (int i = 0; i < rows; i++) {
            String line = nextToken();
            for (int j = 0; j < cols; j++) {
                char ch = line.charAt(j);
                if (ch == '#') {
                    grid[i][j] = true; // Mark obstacle
                } else if (ch == 'S') {
                    startRow = i;
                    startCol = j;
                } else if (ch == 'E') {
                    endRow = i;
                    endCol = j;
                }
            }
        }

        String commands = nextToken();
        int validPermutationsCount = 0;

        // Array to map input digits (0,1,2,3) to direction indices (0,1,2,3).
        // Initially maps 0->0, 1->1, 2->2, 3->3.
        int[] directionMapping = {0, 1, 2, 3};

        // Try all permutations of direction mappings
        do {
            int currentRow = startRow;
            int currentCol = startCol;
            boolean reachedEnd = false;

            for (int i = 0; i < commands.length(); i++) {
                // Optimization: Convert char digit to int directly without String allocation
                int digit = commands.charAt(i) - '0';

                // Get the direction index mapped by the current permutation
                int directionIndex = directionMapping[digit];

                // Move according to the mapped direction
                Direction dir = DIRECTIONS[directionIndex];
                currentRow += dir.getDx();
                currentCol += dir.getDy();

                // Check if we reached the destination
                if (currentRow == endRow && currentCol == endCol) {
                    reachedEnd = true;
                    break;
                }

                // Check bounds and obstacles
                if (!isWithinBounds(currentRow, currentCol) || grid[currentRow][currentCol]) {
                    break; // Path blocked or out of bounds
                }
            }

            if (reachedEnd) {
                validPermutationsCount++;
            }

        } while (nextPermutation(directionMapping));

        out.print(validPermutationsCount);
    }

    /**
     * Checks if the given coordinates are within the grid boundaries.
     */
    private boolean isWithinBounds(int row, int col) {
        return row >= 0 && row < rows && col >= 0 && col < cols;
    }

    /**
     * Generates the next lexicographical permutation of the array.
     * Returns true if a next permutation exists, false otherwise.
     */
    private boolean nextPermutation(int[] p) {
        for (int a = p.length - 2; a >= 0; --a) {
            if (p[a] < p[a + 1]) {
                for (int b = p.length - 1; ; --b) {
                    if (p[b] > p[a]) {
                        int t = p[a];
                        p[a] = p[b];
                        p[b] = t;
                        for (++a, b = p.length - 1; a < b; ++a, --b) {
                            t = p[a];
                            p[a] = p[b];
                            p[b] = t;
                        }
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Reads the next token from input.
     */
    private String nextToken() throws IOException {
        while (tokenizer == null || !tokenizer.hasMoreTokens()) {
            String line = br.readLine();
            if (line == null) {
                return null;
            }
            tokenizer = new StringTokenizer(line);
        }
        return tokenizer.nextToken();
    }

    /**
     * Reads the next integer from input.
     */
    private int nextInt() throws IOException {
        String token = nextToken();
        if (token == null) throw new IOException("Unexpected end of input");
        return Integer.parseInt(token);
    }

    /**
     * Reads the next double from input.
     */
    private double nextDouble() throws IOException {
        String token = nextToken();
        if (token == null) throw new IOException("Unexpected end of input");
        return Double.parseDouble(token);
    }

    /**
     * Reads the next long from input.
     */
    private long nextLong() throws IOException {
        String token = nextToken();
        if (token == null) throw new IOException("Unexpected end of input");
        return Long.parseLong(token);
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.ArrayList;
import java.util.List;
import java.util.StringTokenizer;

public class Main {
    public static void main(String[] args) {
        FastScanner in = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out);
        new GridSolver().solve(in, out);
        out.flush();
    }

    static class GridSolver {
        // Permutations of "LRUD" are constant across test cases. 
        // Computing once improves performance and eliminates mutable state.
        private static final List<String> PERMUTATIONS = generatePermutations("LRUD");

        public void solve(FastScanner in, PrintWriter out) {
            int n = in.nextInt();
            int m = in.nextInt();
            char[][] grid = new char[n][m];
            int startR = -1, startC = -1;
            int endR = -1, endC = -1;

            // Parse grid and locate start/end positions
            for (int i = 0; i < n; i++) {
                String row = in.next();
                for (int j = 0; j < m; j++) {
                    grid[i][j] = row.charAt(j);
                    if (grid[i][j] == 'S') {
                        startR = i;
                        startC = j;
                    } else if (grid[i][j] == 'E') {
                        endR = i;
                        endC = j;
                    }
                }
            }

            String moves = in.next();
            int successfulPaths = countSuccessfulPaths(grid, n, m, startR, startC, endR, endC, moves);
            out.println(successfulPaths);
        }

        private int countSuccessfulPaths(char[][] grid, int rows, int cols,
                                         int startR, int startC, int endR, int endC, String moves) {
            int successCount = 0;
            for (String perm : PERMUTATIONS) {
                if (simulatePath(grid, rows, cols, startR, startC, endR, endC, moves, perm)) {
                    successCount++;
                }
            }
            return successCount;
        }

        private boolean simulatePath(char[][] grid, int rows, int cols,
                                     int currentR, int currentC, int endR, int endC,
                                     String moves, String perm) {
            for (int i = 0; i < moves.length(); i++) {
                int moveIndex = moves.charAt(i) - '0';
                char direction = perm.charAt(moveIndex);

                if (direction == 'L') currentC--;
                else if (direction == 'R') currentC++;
                else if (direction == 'U') currentR--;
                else if (direction == 'D') currentR++;

                if (!isValidMove(grid, rows, cols, currentR, currentC)) {
                    return false;
                }

                if (currentR == endR && currentC == endC) {
                    return true;
                }
            }
            return false;
        }

        private boolean isValidMove(char[][] grid, int rows, int cols, int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols && grid[r][c] != '#';
        }

        private static List<String> generatePermutations(String str) {
            List<String> result = new ArrayList<>();
            permute(str.toCharArray(), 0, result);
            return result;
        }

        private static void permute(char[] arr, int l, List<String> result) {
            if (l == arr.length) {
                result.add(new String(arr));
            } else {
                for (int i = l; i < arr.length; i++) {
                    swap(arr, l, i);
                    permute(arr, l + 1, result);
                    swap(arr, l, i); // backtrack
                }
            }
        }

        private static void swap(char[] arr, int i, int j) {
            char temp = arr[i];
            arr[i] = arr[j];
            arr[j] = temp;
        }
    }

    /**
     * Standard fast I/O helper using BufferedReader and StringTokenizer.
     * Replaces the custom byte-based scanner for better readability and maintainability.
     */
    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner(InputStream inputStream) {
            br = new BufferedReader(new InputStreamReader(inputStream));
        }

        public String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input", e);
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.*;
import java.util.InputMismatchException;

/**
 * Main entry point for the competitive programming solution.
 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;

        InputReader in = new InputReader(inputStream);
        OutputWriter out = new OutputWriter(outputStream);

        TaskB solver = new TaskB();
        solver.solve(1, in, out);

        out.close();
    }

    /**
     * Solves Task B: Counts how many direction permutations allow a path
     * from 'S' to 'E' without hitting boundaries or walls ('#').
     */
    static class TaskB {
        private static final int[] DX = {-1, 0, 1, 0};
        private static final int[] DY = {0, -1, 0, 1};
        private static final char START = 'S';
        private static final char END = 'E';
        private static final char WALL = '#';
        private static final int NUM_DIRECTIONS = 4;

        /**
         * Entry point for solving a single test case.
         */
        public void solve(int testNumber, InputReader in, OutputWriter out) {
            int n = in.nextInt();
            int m = in.nextInt();

            char[][] grid = new char[n][m];
            int startRow = -1, startCol = -1;
            int endRow = -1, endCol = -1;

            // Parse grid and locate start/end positions
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    grid[i][j] = in.nextCharacter();
                    if (grid[i][j] == START) {
                        startRow = i;
                        startCol = j;
                    } else if (grid[i][j] == END) {
                        endRow = i;
                        endCol = j;
                    }
                }
            }

            String pathInstructions = in.nextString();

            // Count valid permutations
            int validPathCount = countValidPaths(grid, n, m, startRow, startCol, endRow, endCol, pathInstructions);

            out.println(validPathCount);
        }

        /**
         * Orchestrates permutation generation and path validation.
         */
        private int countValidPaths(char[][] grid, int n, int m, 
                                    int startRow, int startCol, 
                                    int endRow, int endCol, 
                                    String pathInstructions) {
            boolean[] usedDirections = new boolean[NUM_DIRECTIONS];
            int[] directionMap = new int[NUM_DIRECTIONS];

            return generatePermutations(0, usedDirections, directionMap, 
                                        grid, n, m, startRow, startCol, endRow, endCol, pathInstructions);
        }

        /**
         * Recursively generates all permutations of direction mappings.
         */
        private int generatePermutations(int idx, boolean[] usedDirections, int[] directionMap,
                                         char[][] grid, int n, int m,
                                         int startRow, int startCol, int endRow, int endCol,
                                         String pathInstructions) {
            if (idx == NUM_DIRECTIONS) {
                return simulatePath(grid, n, m, startRow, startCol, endRow, endCol, pathInstructions, directionMap);
            }

            int count = 0;
            for (int dir = 0; dir < NUM_DIRECTIONS; dir++) {
                if (!usedDirections[dir]) {
                    usedDirections[dir] = true;
                    directionMap[idx] = dir;
                    count += generatePermutations(idx + 1, usedDirections, directionMap,
                                                  grid, n, m, startRow, startCol, endRow, endCol, pathInstructions);
                    usedDirections[dir] = false; // Backtrack
                }
            }
            return count;
        }

        /**
         * Simulates movement based on a direction mapping and path instructions.
         * Returns 1 if 'E' is reached, 0 otherwise.
         */
        private int simulatePath(char[][] grid, int n, int m,
                                 int startRow, int startCol,
                                 int endRow, int endCol,
                                 String pathInstructions, int[] directionMap) {
            int r = startRow;
            int c = startCol;

            for (int i = 0; i < pathInstructions.length(); i++) {
                int digit = pathInstructions.charAt(i) - '0';
                int dir = directionMap[digit];

                r += DX[dir];
                c += DY[dir];

                // Check bounds and walls
                if (r < 0 || r >= n || c < 0 || c >= m || grid[r][c] == WALL) {
                    break;
                }

                // Check if destination reached
                if (r == endRow && c == endCol) {
                    return 1;
                }
            }
            return 0;
        }
    }

    /**
     * High-performance output writer for competitive programming.
     */
    static class OutputWriter {
        private final PrintWriter writer;

        public OutputWriter(OutputStream outputStream) {
            writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(outputStream)));
        }

        public OutputWriter(Writer writer) {
            this.writer = new PrintWriter(writer);
        }

        public void close() {
            writer.close();
        }

        public void println(int i) {
            writer.println(i);
        }
    }

    /**
     * Fast input reader for competitive programming.
     */
    static class InputReader {
        private final InputStream stream;
        private final byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        public int read() {
            if (numChars == -1) {
                throw new InputMismatchException();
            }
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0) {
                    return -1;
                }
            }
            return buf[curChar++];
        }

        public int nextInt() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                res *= 10;
                res += c - '0';
                c = read();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public String nextString() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            StringBuilder res = new StringBuilder();
            do {
                if (Character.isValidCodePoint(c)) {
                    res.appendCodePoint(c);
                }
                c = read();
            } while (!isSpaceChar(c));
            return res.toString();
        }

        public boolean isSpaceChar(int c) {
            return isWhitespace(c);
        }

        public static boolean isWhitespace(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        public char nextCharacter() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            return (char) c;
        }

        /**
         * Interface for custom space character filtering.
         * Kept for compatibility but unused in the current implementation.
         */
        @FunctionalInterface
        public interface SpaceCharFilter {
            boolean isSpaceChar(int ch);
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

/**
 * Solves a maze path counting problem by evaluating all permutations of
 * directional moves against a given sequence of indices.
 * 
 * The program reads a grid with start ('S') and end ('E') positions, followed
 * by a sequence of digit indices (0-3). It counts how many permutations of the
 * four cardinal directions {'u', 'd', 'l', 'r'} successfully navigate from S to E
 * without hitting walls, following the movement sequence.
 */
public class MazePathCounter {
    private static final int DIRECTION_COUNT = 4;
    private static final char[] DIRECTIONS = {'u', 'd', 'l', 'r'};
    private static final char START_CHAR = 'S';
    private static final char END_CHAR = 'E';
    private static final char PASSABLE_CHAR = '.';

    private final int startRow;
    private final int startCol;
    private final int endRow;
    private final int endCol;
    private final char[][] grid;
    private String directionSequence;
    private int validPermutationCount;

    /**
     * Initializes the solver with grid dimensions.
     * The grid is padded with an extra border to simplify boundary collision checks.
     */
    public MazePathCounter(int rows, int cols) {
        this.grid = new char[rows + 2][cols + 2];
        this.validPermutationCount = 0;
        this.startRow = 0;
        this.startCol = 0;
        this.endRow = 0;
        this.endCol = 0;
        this.directionSequence = "";
    }

    /**
     * Reads the maze grid from the provided reader and locates start/end positions.
     */
    public void loadGrid(BufferedReader reader) throws IOException {
        for (int i = 1; i <= grid.length - 2; i++) {
            String line = reader.readLine();
            if (line == null) break;
            for (int j = 1; j <= grid[i].length - 2; j++) {
                char cell = line.charAt(j - 1);
                grid[i][j] = cell;
                if (cell == START_CHAR) {
                    startRow = i;
                    startCol = j;
                } else if (cell == END_CHAR) {
                    endRow = i;
                    endCol = j;
                }
            }
        }
    }

    /**
     * Sets the directional sequence provided by the user.
     */
    public void setDirectionSequence(String sequence) {
        this.directionSequence = sequence;
    }

    /**
     * Executes the permutation search and counts valid paths.
     */
    public void solve() {
        char[] currentPermutation = new char[DIRECTION_COUNT];
        boolean[] used = new boolean[DIRECTION_COUNT];
        generatePermutations(0, currentPermutation, used);
    }

    /**
     * Recursively generates all permutations of the four directions.
     */
    private void generatePermutations(int index, char[] currentPermutation, boolean[] used) {
        if (index == DIRECTION_COUNT) {
            if (isPathValid(currentPermutation)) {
                validPermutationCount++;
            }
            return;
        }

        for (int i = 0; i < DIRECTION_COUNT; i++) {
            if (!used[i]) {
                used[i] = true;
                currentPermutation[index] = DIRECTIONS[i];
                generatePermutations(index + 1, currentPermutation, used);
                used[i] = false;
            }
        }
    }

    /**
     * Simulates movement through the maze using the given direction permutation
     * and the user-provided sequence of indices.
     * 
     * @return true if the path reaches the end, false if it hits a wall or fails to reach the end
     */
    private boolean isPathValid(char[] permutation) {
        int currentRow = startRow;
        int currentCol = startCol;

        for (int i = 0; i < directionSequence.length(); i++) {
            int directionIndex = directionSequence.charAt(i) - '0';
            char move = permutation[directionIndex];

            if (move == 'r') {
                currentCol++;
            } else if (move == 'l') {
                currentCol--;
            } else if (move == 'u') {
                currentRow--;
            } else if (move == 'd') {
                currentRow++;
            }

            if (currentRow == endRow && currentCol == endCol) {
                return true;
            }

            // Treat anything that isn't passable or start as a wall
            if (grid[currentRow][currentCol] != PASSABLE_CHAR && grid[currentRow][currentCol] != START_CHAR) {
                return false;
            }
        }
        return false;
    }

    /**
     * Returns the total count of valid permutations found.
     */
    public int getValidPermutationCount() {
        return validPermutationCount;
    }

    public static void main(String[] args) throws IOException {
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(System.in))) {
            String firstLine = reader.readLine();
            if (firstLine == null) return;

            StringTokenizer tokenizer = new StringTokenizer(firstLine);
            int rows = Integer.parseInt(tokenizer.nextToken());
            int cols = Integer.parseInt(tokenizer.nextToken());

            MazePathCounter solver = new MazePathCounter(rows, cols);
            solver.loadGrid(reader);
            solver.setDirectionSequence(reader.readLine());
            solver.solve();

            System.out.println(solver.getValidPermutationCount());
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

/**
 * Solves a grid pathfinding problem by checking how many permutations of 
 * direction mappings allow reaching the endpoint 'E' from the start point 'S'.
 */
public class GridPathSolver {
    private char[][] grid;
    private final int[] DELTA_X = {0, 0, 1, -1};
    private final int[] DELTA_Y = {1, -1, 0, 0};
    private String instructions;
    private int[] directionMap;

    /**
     * Reads input, initializes the grid, and computes the number of valid direction permutations.
     *
     * @param sc FastScanner instance for reading input
     * @return count of permutations that successfully reach 'E'
     * @throws IOException if an I/O error occurs
     */
    public int solve(FastScanner sc) throws IOException {
        int n = sc.nextInt();
        int m = sc.nextInt();
        grid = new char[n][m];
        int startRow = -1;
        int startCol = -1;

        for (int i = 0; i < n; i++) {
            String row = sc.next();
            grid[i] = row.toCharArray();
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == 'S') {
                    startRow = i;
                    startCol = j;
                }
            }
        }

        instructions = sc.next();
        // Initialize direction mapping [0, 1, 2, 3]. This array will be permuted.
        directionMap = new int[]{0, 1, 2, 3};

        int successCount = 0;
        do {
            if (canReachPath(startRow, startCol, 0)) {
                successCount++;
            }
        } while (nextPermutation(directionMap));

        return successCount;
    }

    /**
     * Recursive DFS to determine if 'E' can be reached following the instruction sequence.
     *
     * @param x current row index
     * @param y current column index
     * @param idx current instruction index
     * @return true if 'E' is reachable, false otherwise
     */
    private boolean canReachPath(int x, int y, int idx) {
        char currentCell = grid[x][y];
        if (currentCell == 'E') {
            return true;
        }
        if (currentCell == '#' || idx == instructions.length()) {
            return false;
        }

        int dirIndex = instructions.charAt(idx) - '0';
        // Safety check to prevent ArrayIndexOutOfBoundsException for invalid digits
        if (dirIndex < 0 || dirIndex > 3) {
            return false;
        }

        int direction = directionMap[dirIndex];
        int nextX = x + DELTA_X[direction];
        int nextY = y + DELTA_Y[direction];

        if (isValidPosition(nextX, nextY)) {
            return canReachPath(nextX, nextY, idx + 1);
        }
        return false;
    }

    /**
     * Checks if the given coordinates are within the grid boundaries.
     */
    private boolean isValidPosition(int x, int y) {
        return x >= 0 && y >= 0 && x < grid.length && y < grid[0].length;
    }

    /**
     * Generates the next lexicographical permutation of the array in-place.
     *
     * @param array the array to permute
     * @return true if a next permutation exists, false if already at the last permutation
     */
    private boolean nextPermutation(int[] array) {
        int pivot = findPivot(array);
        if (pivot == -1) {
            return false;
        }

        int successor = array.length - 1;
        while (array[pivot] >= array[successor]) {
            successor--;
        }

        swap(array, pivot, successor);

        // Reverse the suffix starting at pivot + 1
        int left = pivot + 1;
        int right = array.length - 1;
        while (left < right) {
            swap(array, left++, right--);
        }
        return true;
    }

    /**
     * Finds the rightmost element that is smaller than its successor.
     */
    private int findPivot(int[] array) {
        for (int i = array.length - 2; i >= 0; i--) {
            if (array[i] < array[i + 1]) {
                return i;
            }
        }
        return -1;
    }

    /**
     * Swaps two elements in the array.
     */
    private void swap(int[] array, int i, int j) {
        int temp = array[i];
        array[i] = array[j];
        array[j] = temp;
    }

    public static void main(String[] args) {
        try (FastScanner sc = new FastScanner(System.in)) {
            GridPathSolver solver = new GridPathSolver();
            int result = solver.solve(sc);
            System.out.println(result);
        } catch (IOException e) {
            System.err.println("Input/Output error: " + e.getMessage());
        }
    }

    /**
     * FastScanner for efficient token-based input reading.
     */
    static class FastScanner implements AutoCloseable {
        private BufferedReader br;
        private StringTokenizer st;

        public FastScanner(InputStream input) {
            br = new BufferedReader(new InputStreamReader(input));
        }

        public String next() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) {
                    throw new IOException("Unexpected end of input");
                }
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        public long nextLong() throws IOException {
            return Long.parseLong(next());
        }

        public String nextLine() throws IOException {
            return br.readLine();
        }

        public double nextDouble() throws IOException {
            return Double.parseDouble(next());
        }

        @Override
        public void close() throws IOException {
            br.close();
        }
    }
}

import java.io.BufferedReader;
