import java.util.HashSet;
import java.util.Set;
import java.util.StringTokenizer;

public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        OutputWriter out = new OutputWriter(outputStream);

        PathSolver solver = new PathSolver();
        solver.solve(in, out);

        out.close();
    }

    static class PathSolver {
        // Direction vectors: Up, Right, Down, Left
        private static final int[] DX = {-1, 0, 1, 0};
        private static final int[] DY = {0, 1, 0, -1};

        public void solve(InputReader in, OutputWriter out) {
            int n = in.nextInt();
            int m = in.nextInt();

            char[][] grid = new char[n][m];
            int startRow = -1, startCol = -1;

            for (int i = 0; i < n; i++) {
                String line = in.next();
                for (int j = 0; j < line.length(); j++) {
                    grid[i][j] = line.charAt(j);
                    if (grid[i][j] == 'S') {
                        startRow = i;
                        startCol = j;
                    }
                }
            }

            String pathMapping = in.next();
            Set<String> permutations = PermutationUtils.getPermutations("0123");
            int validCount = 0;

            for (String perm : permutations) {
                if (canReachEnd(grid, startRow, startCol, pathMapping, perm)) {
                    validCount++;
                }
            }

            out.printLine(validCount);
        }

        private boolean canReachEnd(char[][] grid, int startRow, int startCol, 
                                    String pathMapping, String perm) {
            int x = startRow;
            int y = startCol;
            int length = pathMapping.length();

            for (int index = 0; index < length; index++) {
                // Check boundaries and obstacles before moving
                if (x < 0 || y < 0 || x >= grid.length || y >= grid[0].length) {
                    return false;
                }
                if (grid[x][y] == '#') {
                    return false;
                }
                if (grid[x][y] == 'E') {
                    return true;
                }

                // Map the current path character to a direction index using the permutation
                int dirIndex = perm.indexOf(pathMapping.charAt(index));
                x += DX[dirIndex];
                y += DY[dirIndex];
            }

            // Verify the final position after exhausting all moves
            if (x < 0 || y < 0 || x >= grid.length || y >= grid[0].length) {
                return false;
            }
            if (grid[x][y] == '#') {
                return false;
            }
            return grid[x][y] == 'E';
        }
    }

    static class OutputWriter {
        private final PrintWriter writer;

        public OutputWriter(OutputStream outputStream) {
            this.writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(outputStream)));
        }

        public OutputWriter(Writer writer) {
            this.writer = new PrintWriter(writer);
        }

        public void print(Object... objects) {
            for (int i = 0; i < objects.length; i++) {
                if (i != 0) {
                    writer.print(' ');
                }
                writer.print(objects[i]);
            }
        }

        public void printLine(Object... objects) {
            print(objects);
            writer.println();
        }

        public void close() {
            writer.close();
        }
    }

    static class InputReader {
        private BufferedReader in;
        private StringTokenizer tokenizer;

        public InputReader(InputStream inputStream) {
            this.in = new BufferedReader(new InputStreamReader(inputStream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = in.readLine();
                    if (line == null) {
                        return null;
                    }
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            String s = next();
            if (s == null) {
                throw new RuntimeException("Unexpected end of input");
            }
            return Integer.parseInt(s);
        }
    }

    static class PermutationUtils {
        static Set<String> getPermutations(String s) {
            Set<String> result = new HashSet<>();
            char[] chars = s.toCharArray();
            generatePerms(chars.length, chars, result);
            return result;
        }

        private static void generatePerms(int n, char[] ch, Set<String> result) {
            if (n == 1) {
                result.add(new String(ch));
                return;
            }
            for (int i = 0; i < n; i++) {
                if (i == n - 1 || ch[i] != ch[n - 1]) {
                    swap(ch, i, n - 1);
                    generatePerms(n - 1, ch, result);
                    swap(ch, i, n - 1);
                }
            }
        }

        private static void swap(char[] ch, int i, int j) {
            char temp = ch[i];
            ch[i] = ch[j];
            ch[j] = temp;
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.OutputStream;
import java.io.PrintWriter;
import java.util.StringTokenizer;

public class Main {
    public static void main(String[] args) {
        FastScanner in = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out);

        new Solution().solve(in, out);

        out.flush();
        out.close();
    }

    static class Solution {
        private int n, m;
        private char[][] grid;
        private String directionSequence;
        private int startX, startY;
        private int validConfigurations;

        /**
         * Reads input, initializes state, and computes the number of valid direction mappings.
         */
        public void solve(FastScanner in, PrintWriter out) {
            n = in.nextInt();
            m = in.nextInt();

            grid = new char[n][m];
            for (int i = 0; i < n; i++) {
                String row = in.next();
                for (int j = 0; j < m; j++) {
                    grid[i][j] = row.charAt(j);
                    if (grid[i][j] == 'S') {
                        startX = i;
                        startY = j;
                    }
                }
            }
            directionSequence = in.next();

            validConfigurations = 0;
            int[] perm = new int[4];
            boolean[] used = new boolean[4];
            generatePermutations(perm, used, 0);

            out.println(validConfigurations);
        }

        /**
         * Generates all permutations of [0, 1, 2, 3] to assign digits to directions.
         * perm[0] -> UP, perm[1] -> DOWN, perm[2] -> LEFT, perm[3] -> RIGHT
         */
        private void generatePermutations(int[] perm, boolean[] used, int depth) {
            if (depth == 4) {
                if (dfs(startX, startY, 0, perm)) {
                    validConfigurations++;
                }
                return;
            }
            for (int i = 0; i < 4; i++) {
                if (!used[i]) {
                    used[i] = true;
                    perm[depth] = i;
                    generatePermutations(perm, used, depth + 1);
                    used[i] = false;
                }
            }
        }

        /**
         * Recursively checks if a path exists following the current direction mapping.
         */
        private boolean dfs(int r, int c, int pos, int[] perm) {
            char cell = grid[r][c];

            // Reached destination
            if (cell == 'E') return true;
            // Hit obstacle
            if (cell == '#') return false;
            // Ran out of direction instructions without reaching 'E'
            if (pos == directionSequence.length()) return false;

            int digit = directionSequence.charAt(pos) - '0';
            int nr = r, nc = c;

            // Map digit to direction based on current permutation
            if (digit == perm[0]) nr = r - 1;          // UP
            else if (digit == perm[1]) nr = r + 1;     // DOWN
            else if (digit == perm[2]) nc = c - 1;     // LEFT
            else if (digit == perm[3]) nc = c + 1;     // RIGHT
            else return false; // Digit doesn't match any mapped direction

            // Boundary check
            if (nr < 0 || nr >= n || nc < 0 || nc >= m) {
                return false;
            }

            return dfs(nr, nc, pos + 1, perm);
        }
    }

    /**
     * Fast I/O helper class for competitive programming and performance-critical applications.
     */
    static class FastScanner {
        private BufferedReader br;
        private StringTokenizer st;

        public FastScanner(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        public String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input", e);
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            String token = next();
            return token == null ? 0 : Integer.parseInt(token);
        }
    }
}

import java.io.BufferedReader;
