public class Main {
    // Direction mappings: 0: Right, 1: Left, 2: Up, 3: Down
    private static final int[] DX = {0, 0, -1, 1};
    private static final int[] DY = {1, -1, 0, 0};

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner();
        PrintWriter out = new PrintWriter(System.out);

        int n = scanner.nextInt();
        int m = scanner.nextInt();
        char[][] grid = scanner.nextGrid(n, m);

        // Locate the starting position 'S'
        int startRow = -1;
        int startCol = -1;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == 'S') {
                    startRow = i;
                    startCol = j;
                }
            }
        }

        String moves = scanner.next();
        int[] perm = {0, 1, 2, 3}; // Represents the 4 possible directions
        int[] validCount = new int[1];

        // Generate all permutations of directions and count valid paths
        generatePermutations(perm, 0, moves, grid, n, m, startRow, startCol, validCount);

        out.println(validCount[0]);
        out.flush();
    }

    /**
     * Generates all permutations of the direction array using backtracking.
     */
    private static void generatePermutations(int[] perm, int idx, String moves, char[][] grid,
                                             int n, int m, int startRow, int startCol, int[] count) {
        if (idx == perm.length) {
            if (simulatePath(perm, moves, grid, n, m, startRow, startCol)) {
                count[0]++;
            }
            return;
        }

        for (int i = idx; i < perm.length; i++) {
            swap(perm, idx, i);
            generatePermutations(perm, idx + 1, moves, grid, n, m, startRow, startCol, count);
            swap(perm, idx, i); // Backtrack to restore state
        }
    }

    /**
     * Simulates the path based on the current direction permutation.
     * Returns true if the path reaches 'E' without going out of bounds or hitting a wall.
     */
    private static boolean simulatePath(int[] perm, String moves, char[][] grid, int n, int m,
                                        int startRow, int startCol) {
        int r = startRow;
        int c = startCol;

        for (int k = 0; k < moves.length(); k++) {
            int directionIndex = perm[moves.charAt(k) - '0'];
            r += DX[directionIndex];
            c += DY[directionIndex];

            // Check boundaries and walls
            if (r < 0 || r >= n || c < 0 || c >= m || grid[r][c] == '#') {
                return false;
            }

            // Check if destination is reached
            if (grid[r][c] == 'E') {
                return true;
            }
        }
        return false;
    }

    /**
     * Swaps two elements in an array.
     */
    private static void swap(int[] arr, int i, int j) {
        int temp = arr[i];
        arr[i] = arr[j];
        arr[j] = temp;
    }

    /**
     * Fast input scanner optimized for competitive programming.
     */
    static class FastScanner {
        BufferedReader br;
        StringTokenizer st;

        public FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        char[][] nextGrid(int n, int m) {
            char[][] grid = new char[n][m];
            for (int i = 0; i < n; i++) {
                grid[i] = next().toCharArray();
            }
            return grid;
        }
    }
