/**
 * Main entry point for the grid path counter application.
 * Reads a grid, start/end positions, and a direction sequence,
 * then counts valid permutations that lead from start to end.
 */
public class GridPathCounter {
    public static void main(String[] args) {
        // Use buffered I/O for performance-critical input/output
        FastScanner scanner = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out));

        try {
            GridSolver solver = new GridSolver(scanner, out);
            solver.solve();
        } catch (IOException e) {
            System.err.println("I/O Error: " + e.getMessage());
        } finally {
            out.flush();
        }
