/**
 * Handles the core logic for finding valid permutations of directions
 * that lead from the start to the end position on a grid.
 */
class GridSolver {
    // Direction mappings based on problem specification
    private static final int DIR_UP = 0;
    private static final int DIR_RIGHT = 1;
    private static final int DIR_DOWN = 2;
    private static final int DIR_LEFT = 3;

    // The permutation array size is fixed by the problem constraints
    private static final int PERMUTATION_SIZE = 4;

    private final FastScanner scanner;
    private final PrintWriter out;

    private int rows, cols;
    private char[][] grid;
    private char[] pathSequence;
    private int[] currentPermutation;
    private boolean[] used;
    private long validPathCount = 0;

    private int startX, startY, endX, endY;

    public GridSolver(FastScanner scanner, PrintWriter out) {
        this.scanner = scanner;
        this.out = out;
    }

    /**
     * Orchestrates the reading of input, grid parsing, and path validation.
     */
    public void solve() throws IOException {
        rows = scanner.nextInt();
        cols = scanner.nextInt();

        grid = new char[rows][];
        for (int i = 0; i < rows; i++) {
            grid[i] = scanner.next().toCharArray();
        }

        // Locate start and end positions
        startX = startY = endX = endY = -1;
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                char cell = grid[i][j];
                if (cell == 'S') {
                    startX = i;
                    startY = j;
                } else if (cell == 'E') {
                    endX = i;
                    endY = j;
                }
            }
        }

        pathSequence = scanner.next().toCharArray();
        currentPermutation = new int[PERMUTATION_SIZE];
        used = new boolean[PERMUTATION_SIZE];

        // Generate all permutations and count valid paths
        generatePermutations(0);

        out.println(validPathCount);
    }

    /**
     * Checks if a given coordinate is within bounds and not a wall.
     */
    private boolean isValid(int x, int y) {
        return x >= 0 && x < rows && y >= 0 && y < cols && grid[x][y] != '#';
    }

    /**
     * Checks if a given coordinate matches the destination.
     */
    private boolean isAtDestination(int x, int y) {
        return x == endX && y == endY;
    }

    /**
     * Simulates movement along a permutation of directions.
     * Returns true if the destination is reached without hitting walls or boundaries.
     * Note: Matches original logic where pathSequence digits index into the permutation array.
     */
    private boolean canReachWithPath(int[] perm) {
        int x = startX;
        int y = startY;

        for (char dirChar : pathSequence) {
            int dirCode = perm[dirChar - '0'];
            switch (dirCode) {
                case DIR_UP -> x--;
                case DIR_RIGHT -> y++;
                case DIR_DOWN -> x++;
                case DIR_LEFT -> y--;
            }

            if (!isValid(x, y)) {
                return false;
            }
            if (isAtDestination(x, y)) {
                return true;
            }
        }
        return isAtDestination(x, y);
    }

    /**
     * Recursively generates all permutations of the direction indices [0,1,2,3].
     */
    private void generatePermutations(int index) {
        if (index == PERMUTATION_SIZE) {
            if (canReachWithPath(currentPermutation)) {
                validPathCount++;
            }
            return;
        }

        for (int i = 0; i < PERMUTATION_SIZE; i++) {
            if (!used[i]) {
                used[i] = true;
                currentPermutation[index] = i;
                generatePermutations(index + 1);
                used[i] = false;
            }
        }
    }
}

/**
 * Fast I/O utility class for competitive programming and performance-critical applications.
 */
class FastScanner {
    private final BufferedReader reader;
    private StringTokenizer tokenizer;

    public FastScanner(InputStream input) {
