    }

    public String next() throws IOException {
        while (!tokenizer.hasMoreTokens()) {
            String line = reader.readLine();
            if (line == null) {
                return null;
            }
            tokenizer = new StringTokenizer(line);
        }
        return tokenizer.nextToken();
    }

    public int nextInt() throws IOException {
        String token = next();
        return token == null ? 0 : Integer.parseInt(token);
    }

    public long nextLong() throws IOException {
        String token = next();
        return token == null ? 0L : Long.parseLong(token);
    }

    public double nextDouble() throws IOException {
        String token = next();
        return token == null ? 0.0 : Double.parseDouble(token);
    }
}

import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Scanner;
import java.util.Set;

public class Main {
    // Direction offsets: Right, Up, Left, Down
    private static final int[] DX = {1, 0, -1, 0};
    private static final int[] DY = {0, 1, 0, -1};

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        if (!scanner.hasNextInt()) {
            return;
        }

        int n = scanner.nextInt();
        int m = scanner.nextInt();
        scanner.nextLine(); // Consume the newline after m
        String instructions = scanner.nextLine().trim();

        char[][] grid = new char[n][m];
        int[] startPos = new int[2];
        int[] endPos = new int[2];

        // Parse the maze grid and locate start/end positions
        for (int i = 0; i < n; i++) {
            String line = scanner.nextLine().trim();
            for (int j = 0; j < m; j++) {
                grid[i][j] = line.charAt(j);
                if (grid[i][j] == 'S') {
                    startPos[0] = i;
                    startPos[1] = j;
                } else if (grid[i][j] == 'E') {
                    endPos[0] = i;
                    endPos[1] = j;
                }
            }
        }

        // Extract the 4 unique instruction characters
        List<Character> uniqueChars = extractUniqueCharacters(instructions);

        // Generate all 24 permutations of these characters
        List<List<Character>> permutations = generatePermutations(uniqueChars);

        int possibilities = 0;
        for (List<Character> perm : permutations) {
            if (simulateMaze(grid, n, m, instructions, startPos, endPos, perm)) {
                possibilities++;
            }
        }

        System.out.println(possibilities);
        scanner.close();
    }

    /**
     * Extracts unique characters from the instruction string while preserving order.
     */
    private static List<Character> extractUniqueCharacters(String text) {
        List<Character> unique = new ArrayList<>();
        Set<Character> seen = new HashSet<>();
        for (char c : text.toCharArray()) {
            if (seen.add(c)) {
                unique.add(c);
            }
        }
        return unique;
    }

    /**
     * Recursively generates all permutations of a list of characters.
     */
    private static List<List<Character>> generatePermutations(List<Character> elements) {
        List<List<Character>> result = new ArrayList<>();
        if (elements.isEmpty()) {
            result.add(new ArrayList<>());
            return result;
        }

        for (int i = 0; i < elements.size(); i++) {
            char current = elements.get(i);
            List<Character> remaining = new ArrayList<>(elements);
            remaining.remove(i);

            for (List<Character> perm : generatePermutations(remaining)) {
                List<Character> newPerm = new ArrayList<>();
                newPerm.add(current);
                newPerm.addAll(perm);
                result.add(newPerm);
            }
        }
        return result;
    }

    /**
     * Simulates the maze for a given direction mapping permutation.
     * Returns true if the end position is reached, false otherwise.
     */
    private static boolean simulateMaze(char[][] grid, int rows, int cols, String instructions,
                                        int[] start, int[] end, List<Character> perm) {
        int x = start[0];
        int y = start[1];

        // Map permutation indices to directions: 0->Right, 1->Up, 2->Left, 3->Down
        char[] dirMap = new char[4];
        dirMap[0] = perm.get(0);
        dirMap[1] = perm.get(1);
        dirMap[2] = perm.get(2);
        dirMap[3] = perm.get(3);

        for (int i = 0; i < instructions.length(); i++) {
            char moveChar = instructions.charAt(i);
            int directionIndex = -1;

            if (moveChar == dirMap[0]) directionIndex = 0;
            else if (moveChar == dirMap[1]) directionIndex = 1;
            else if (moveChar == dirMap[2]) directionIndex = 2;
            else if (moveChar == dirMap[3]) directionIndex = 3;

            // Should not occur if input contains exactly 4 unique characters
            if (directionIndex == -1) continue;

            x += DX[directionIndex];
            y += DY[directionIndex];

            // Check bounds
            if (x < 0 || x >= rows || y < 0 || y >= cols) {
                return false;
            }
            // Check walls
            if (grid[x][y] == '#') {
                return false;
            }
            // Check win condition
            if (x == end[0] && y == end[1]) {
                return true;
            }
        }
        return false;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.OutputStream;
import java.io.PrintWriter;
import java.util.StringTokenizer;

public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);

        GridPathSolver solver = new GridPathSolver();
        solver.solve(in, out);

        out.close();
    }

    /**
     * Solves the grid pathfinding problem by checking all permutations of directions.
     */
    static class GridPathSolver {
        private static final int[] DX = {0, 0, 1, -1};
        private static final int[] DY = {1, -1, 0, 0};

        public void solve(InputReader in, PrintWriter out) {
            int n = in.nextInt();
            int m = in.nextInt();
            char[][] grid = new char[n][m];
            int startRow = -1, startCol = -1;
            int endRow = -1, endCol = -1;

            // Read grid and locate start/end positions
            for (int i = 0; i < n; i++) {
                String line = in.next();
                grid[i] = line.toCharArray();
                for (int j = 0; j < m; j++) {
                    if (grid[i][j] == 'S') {
                        startRow = i;
                        startCol = j;
                    } else if (grid[i][j] == 'E') {
                        endRow = i;
                        endCol = j;
                    }
                }
            }

            String sequence = in.next();
            int validPermutationCount = countValidPermutations(
                grid, n, m, startRow, startCol, endRow, endCol, sequence
            );

            out.println(validPermutationCount);
        }

        private int countValidPermutations(char[][] grid, int n, int m, 
                                         int startRow, int startCol, 
                                         int endRow, int endCol, 
                                         String sequence) {
            int[] permutation = {0, 1, 2, 3};
            int count = canReach(grid, n, m, startRow, startCol, endRow, endCol, sequence, permutation) ? 1 : 0;

            while (nextPermutation(permutation)) {
                if (canReach(grid, n, m, startRow, startCol, endRow, endCol, sequence, permutation)) {
                    count++;
                }
            }
            return count;
        }

        /**
         * Simulates movement according to the direction sequence and a given permutation.
         * Returns true if the end position is reached without leaving the grid or hitting obstacles.
         */
        private boolean canReach(char[][] grid, int n, int m, 
                                int startRow, int startCol, 
                                int endRow, int endCol, 
                                String sequence, int[] permutation) {
            int r = startRow;
            int c = startCol;

            for (int i = 0; i < sequence.length(); i++) {
                int dirIndex = sequence.charAt(i) - '0';
                r += DX[permutation[dirIndex]];
                c += DY[permutation[dirIndex]];

                // Check bounds first
                if (r < 0 || r >= n || c < 0 || c >= m) {
                    return false;
                }
                // Check obstacles
                if (grid[r][c] == '#') {
                    return false;
                }
                // Check if destination reached
                if (r == endRow && c == endCol) {
                    return true;
                }
            }
            return false;
        }

        /**
         * Generates the next lexicographical permutation in-place.
         * Returns false if the array is already in descending order.
         */
        private boolean nextPermutation(int[] arr) {
            int n = arr.length;
            int i = n - 1;
            while (i > 0 && arr[i - 1] >= arr[i]) {
                i--;
            }
            if (i == 0) {
                return false;
            }

            int j = n - 1;
            while (arr[j] <= arr[i - 1]) {
                j--;
            }

            swap(arr, i - 1, j);
            reverse(arr, i, n - 1);
            return true;
        }

        private void swap(int[] arr, int i, int j) {
            int temp = arr[i];
            arr[i] = arr[j];
            arr[j] = temp;
        }

        private void reverse(int[] arr, int start, int end) {
            while (start < end) {
                swap(arr, start++, end--);
            }
        }
    }

    /**
     * Fast input reader for competitive programming environments.
     */
    static class InputReader {
        private final BufferedReader br;
        private StringTokenizer st;

        public InputReader(InputStream is) {
            br = new BufferedReader(new InputStreamReader(is));
        }

        public String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) {
                        throw new IOException("Unexpected end of input");
                    }
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input", e);
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.BufferedReader;
import java.io.BufferedOutputStream;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

public class Solution {

    // Defines the 4 cardinal directions: right, left, down, up
    private static final int[][] DIRECTION_OFFSETS = {
        {0, 1},  // right
        {0, -1}, // left
        {1, 0},  // down
        {-1, 0}  // up
    };

    // All 24 permutations mapping digits 0-3 to direction indices 0-3.
    // Each row represents one hypothesis of what digits 0,1,2,3 mean.
    private static final int[][] DIRECTION_MAPPINGS = {
        {0, 1, 2, 3}, {0, 1, 3, 2}, {0, 2, 1, 3}, {0, 2, 3, 1}, {0, 3, 1, 2}, {0, 3, 2, 1},
        {1, 0, 2, 3}, {1, 0, 3, 2}, {1, 2, 0, 3}, {1, 2, 3, 0}, {1, 3, 0, 2}, {1, 3, 2, 0},
        {2, 0, 1, 3}, {2, 0, 3, 1}, {2, 1, 0, 3}, {2, 1, 3, 0}, {2, 3, 0, 1}, {2, 3, 1, 0},
        {3, 0, 1, 2}, {3, 0, 2, 1}, {3, 1, 0, 2}, {3, 1, 2, 0}, {3, 2, 0, 1}, {3, 2, 1, 0}
    };

    public static void main(String[] args) {
        new Solution().solve();
    }

    public void solve() {
        // Use try-with-resources to ensure proper flushing and closing of output
        try (InputReader in = new InputReader(System.in);
             PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out))) {

            int n = in.nextInt();
            int m = in.nextInt();

            char[][] grid = new char[n][m];
            int startRow = -1, startCol = -1;
            int endRow = -1, endCol = -1;

            // Read maze layout and locate start/end points
            for (int i = 0; i < n; i++) {
                String line = in.next();
                grid[i] = line.toCharArray();
                for (int j = 0; j < m; j++) {
                    if (grid[i][j] == 'S') {
                        startRow = i;
                        startCol = j;
                    } else if (grid[i][j] == 'E') {
                        endRow = i;
                        endCol = j;
                    }
                }
            }

            // Read direction sequence
            String directionSequence = in.next();
            int[] directionDigits = new int[directionSequence.length()];
            for (int i = 0; i < directionSequence.length(); i++) {
                directionDigits[i] = directionSequence.charAt(i) - '0';
            }

            // Simulate movement using all 24 possible direction mappings
            int successfulPaths = 0;
            for (int[][] mapping : DIRECTION_MAPPINGS) {
                int currentRow = startRow;
                int currentCol = startCol;
                boolean reachedEnd = false;

                for (int digit : directionDigits) {
                    int dirIndex = mapping[digit];
                    int[] offset = DIRECTION_OFFSETS[dirIndex];

                    currentRow += offset[0];
                    currentCol += offset[1];

                    // Check bounds and obstacles
                    if (currentRow < 0 || currentRow >= n || 
                        currentCol < 0 || currentCol >= m || 
                        grid[currentRow][currentCol] == '#') {
                        break;
                    }

                    if (grid[currentRow][currentCol] == 'E') {
                        successfulPaths++;
                        reachedEnd = true;
                        break;
                    }
                }
            }

            out.println(successfulPaths);
        }
    }

    /**
     * Fast input reader for competitive programming / large I/O scenarios.
     */
    static class InputReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public InputReader(InputStream stream) {
            this.reader = new BufferedReader(new InputStreamReader(stream), 32768);
            this.tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input stream", e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            String s = next();
            if (s == null) throw new RuntimeException("Unexpected end of input");
            return Integer.parseInt(s);
        }
    }
}

import java.io.*;
import java.util.*;

public class Solution {
    // Output stream for fast output
    private static PrintWriter out;
    // Counter for valid paths
    private static int validPathsCount = 0;

    public static void main(String[] args) {
        MyScanner sc = new MyScanner();
        out = new PrintWriter(new BufferedOutputStream(System.out));

        // Read grid dimensions
        int rows = sc.nextInt();
        int cols = sc.nextInt();

        // Read grid and find starting position 'S'
        String[] grid = new String[rows];
        int startRow = 0;
        int startCol = 0;

        for (int i = 0; i < rows; i++) {
            grid[i] = sc.next();
            // Find 'S' in the current row string
            int rowIdx = grid[i].indexOf('S');
            if (rowIdx != -1) {
                startRow = i;
                startCol = rowIdx;
            }
        }

        // Read the sequence of moves
        String moves = sc.next();

        // d array maps Direction Index -> Digit
        // Direction Indices: 0=Left, 1=Right, 2=Up, 3=Down
        // Initially, Digit 0 -> Left, 1 -> Right, 2 -> Up, 3 -> Down
        // d[i] holds the digit that triggers direction i
        int[] d = {0, 1, 2, 3};

        // Generate all permutations of the digit-to-direction mapping
        permute(d, 0, grid, rows, cols, moves, startRow, startCol);

        // Output the result
        out.println(validPathsCount);
        out.flush();
        out.close();
    }

    /**
     * Recursively generates all permutations of the array d.
     * d represents the mapping where d[directionIndex] is the digit that triggers that direction.
     */
    private static void permute(int[] d, int index, String[] grid, int rows, int cols, String moves, int startRow, int startCol) {
        // Base case: permutation complete (all 4 directions assigned a unique digit)
        if (index == 4) {
            if (simulate(d, grid, rows, cols, moves, startRow, startCol)) {
                validPathsCount++;
            }
            return;
        }

        // Try all remaining digits for the current direction index
        for (int i = index; i < 4; i++) {
            swap(d, index, i);
            permute(d, index + 1, grid, rows, cols, moves, startRow, startCol);
            swap(d, index, i); // Backtrack
        }
    }

    private static void swap(int[] arr, int i, int j) {
        int temp = arr[i];
        arr[i] = arr[j];
        arr[j] = temp;
    }

    /**
     * Simulates the path based on the current direction mapping (d).
     * Returns true if the path reaches 'E' without hitting walls or going out of bounds.
     */
    private static boolean simulate(int[] d, String[] grid, int rows, int cols, String moves, int startRow, int startCol) {
        int r = startRow;
        int c = startCol;

        // Precompute mapping from Digit -> Direction for faster lookup
        // d[dir] = digit, so digitToDir[digit] = dir
        int[] digitToDir = new int[4];
        for (int dir = 0; dir < 4; dir++) {
            digitToDir[d[dir]] = dir;
        }

        for (int k = 0; k < moves.length(); k++) {
            int digit = moves.charAt(k) - '0';
            int dir = digitToDir[digit];

            // Apply move based on direction
            // 0: Left, 1: Right, 2: Up, 3: Down
            if (dir == 0) c--;
            else if (dir == 1) c++;
            else if (dir == 2) r--;
            else if (dir == 3) r++;

            // Check bounds
            if (r < 0 || r >= rows || c < 0 || c >= cols) {
                return false;
            }

            // Check for wall
            if (grid[r].charAt(c) == '#') {
                return false;
            }

            // Check for End point
            if (grid[r].charAt(c) == 'E') {
                break; // Reached destination, stop moving
            }
        }

        // The path is valid only if we end exactly on 'E'
        return grid[r].charAt(c) == 'E';
    }

    /**
     * Fast I/O Scanner class
     */
    public static class MyScanner {
        BufferedReader br;
        StringTokenizer st;

        public MyScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    e.printStackTrace();
                    return null;
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            String s = next();
            return (s == null) ? 0 : Integer.parseInt(s);
        }

        long nextLong() {
            String s = next();
            return (s == null) ? 0L : Long.parseLong(s);
        }

        double nextDouble() {
            String s = next();
            return (s == null) ? 0.0 : Double.parseDouble(s);
        }

        String nextLine() {
            String str = "";
            try {
                str = br.readLine();
            } catch (IOException e) {
                e.printStackTrace();
            }
            return str;
        }
    }
}

import java.util.Scanner;

/**
 * Solves a grid navigation problem by testing multiple movement patterns
 * against a set of index-based instructions.
 */
public class GridNavigationSolver {

    /** All permutations of the four movement directions. */
    private static final String[] MOVES = {
        "><^v", "><v^", ">^<v", ">^v<", ">v^<", ">v<^", "<>^v",
        "<>v^", "<^>v", "<^v>", "<v^>", "<v>^", "^<>v", "^<v>", "^><v",
        "^>v<", "^v><", "^v<>", "v<^>", "v<>^", "v^<>", "v^><", "v>^<", "v><^"
    };

    private int rows;
    private int cols;
    private char[][] grid;
    private Position startPosition;
    private String instructionSequence;
    private final Scanner scanner;

    /**
     * Constructs the solver with an external Scanner.
     * @param scanner Scanner bound to the input source
     */
    public GridNavigationSolver(Scanner scanner) {
        this.scanner = scanner;
    }

    /** Reads the grid dimensions and layout from input. */
    private void loadGrid() {
        rows = scanner.nextInt();
        cols = scanner.nextInt();
        grid = new char[rows][cols];

        for (int i = 0; i < rows; i++) {
            String line = scanner.next();
            for (int j = 0; j < cols; j++) {
                grid[i][j] = line.charAt(j);
                if (grid[i][j] == 'S') {
                    startPosition = new Position(i, j);
                }
            }
        }
    }

    /**
     * Simulates a movement pattern against the instruction sequence.
     * Returns true if the robot reaches 'E' during the sequence.
     *
     * @param movePattern        A string of 4 distinct direction characters
     * @param indexSequence      A string of digits (0-3) that index into movePattern
     * @return true if 'E' is reached, false otherwise (or on collision/out-of-bounds)
     */
    private boolean simulateMove(String movePattern, String indexSequence) {
        Position current = new Position(startPosition.row, startPosition.col);

        for (int i = 0; i < indexSequence.length(); i++) {
            int index = indexSequence.charAt(i) - '0';
            char direction = movePattern.charAt(index);

            // Note: Direction mapping preserves original behavior:
            // '>' increases row index, '<' decreases row index
            // '^' increases column index, 'v' decreases column index
            switch (direction) {
                case '>': current.row++; break;
                case '<': current.row--; break;
                case '^': current.col++; break;
                case 'v': current.col--; break;
            }

            // Boundary check
            if (current.row < 0 || current.row >= rows || current.col < 0 || current.col >= cols) {
                return false;
            }

            char cell = grid[current.row][current.col];
            if (cell == '#') {
                return false; // Wall collision
            }
            if (cell == 'E') {
                return true; // Target reached
            }
        }
        return false; // Sequence completed without reaching 'E'
    }

    /** Orchestrates input reading and pattern evaluation. */
    public int solve() {
        loadGrid();
        instructionSequence = scanner.next();

        int successCount = 0;
        for (String move : MOVES) {
            if (simulateMove(move, instructionSequence)) {
                successCount++;
            }
        }
        return successCount;
    }

    public static void main(String[] args) {
        // try-with-resources ensures the Scanner is properly closed
        try (Scanner scanner = new Scanner(System.in)) {
            GridNavigationSolver solver = new GridNavigationSolver(scanner);
            System.out.println(solver.solve());
        }
    }

    /** Immutable representation of a grid coordinate. */
    private static class Position {
        final int row;
        final int col;

        Position(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }
}

import java.io.InputStream;
import java.io.IOException;
import java.io.OutputStream;
import java.io.PrintWriter;
import java.util.InputMismatchException;

public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        FastScanner in = new FastScanner(inputStream);
        PrintWriter out = new PrintWriter(outputStream);

        GridSolver solver = new GridSolver();
        solver.solve(in, out);

        out.close();
    }

    /**
     * Handles the core logic for finding valid direction permutations.
     * Designed to be stateless and reentrant.
     */
    static class GridSolver {
        private static final int NUM_DIRECTIONS = 4;
        private static final int COMMAND_CHAR_OFFSET = '0';

        public void solve(FastScanner in, PrintWriter out) {
            int n = in.nextInt();
            int m = in.nextInt();
            char[][] grid = new char[n][m];
            int startX = -1;
            int startY = -1;

            // Read grid and locate start position
            for (int i = 0; i < n; i++) {
                String row = in.readString();
                grid[i] = row.toCharArray();
                for (int j = 0; j < m; j++) {
                    if (grid[i][j] == 'S') {
                        startX = i;
                        startY = j;
                    }
                }
            }

            String commands = in.readString();

            // Generate permutations and count valid ones
            int[] currentPerm = new int[NUM_DIRECTIONS];
            boolean[] used = new boolean[NUM_DIRECTIONS];
            int validCount = countValidPermutations(currentPerm, used, 0, n, m, grid, commands, startX, startY);

            out.print(validCount);
        }

        /**
         * Recursively generates all permutations of [0,1,2,3] and checks each one.
         */
        private int countValidPermutations(int[] currentPerm, boolean[] used, int index, 
                                           int n, int m, char[][] grid, String commands, 
                                           int startX, int startY) {
            if (index == NUM_DIRECTIONS) {
                return canReachEnd(grid, n, m, commands, startX, startY, currentPerm) ? 1 : 0;
            }

            int validCount = 0;
            for (int i = 0; i < NUM_DIRECTIONS; i++) {
                if (!used[i]) {
                    used[i] = true;
                    currentPerm[index] = i;
                    validCount += countValidPermutations(currentPerm, used, index + 1, 
                                                         n, m, grid, commands, startX, startY);
                    used[i] = false;
                }
            }
            return validCount;
        }

        /**
         * Entry point for path validation using a specific direction permutation.
         */
        private boolean canReachEnd(char[][] grid, int n, int m, String commands, 
                                    int x, int y, int[] perm) {
            return solvePath(grid, n, m, commands, x, y, 0, perm);
        }

        /**
         * Recursively follows the command string using the provided direction mapping.
         */
        private boolean solvePath(char[][] grid, int n, int m, String commands, 
                                  int x, int y, int cmdIdx, int[] perm) {
            // Boundary check
            if (x < 0 || x >= n || y < 0 || y >= m) {
                return false;
            }
            // Obstacle check
            if (grid[x][y] == '#') {
                return false;
            }
            // Success check
            if (grid[x][y] == 'E') {
                return true;
            }
            // Command exhaustion check
            if (cmdIdx >= commands.length()) {
                return false;
            }

            // Map command character to direction index using the current permutation
            int dirIndex = perm[commands.charAt(cmdIdx) - COMMAND_CHAR_OFFSET];
            int dx = 0;
            int dy = 0;

            switch (dirIndex) {
                case 0: dx = 1;  break; // DOWN
                case 1: dy = -1; break; // LEFT
                case 2: dx = -1; break; // UP
                case 3: dy = 1;  break; // RIGHT
            }

            return solvePath(grid, n, m, commands, x + dx, y + dy, cmdIdx + 1, perm);
        }
    }

    /**
     * Fast I/O utility for competitive programming environments.
     */
    static class FastScanner {
        private final InputStream stream;
        private final byte[] buf = new byte[8192];
        private int curChar;
        private int snumChars;

        public FastScanner(InputStream stream) {
            this.stream = stream;
        }

        public int read() {
            if (snumChars == -1) {
                throw new InputMismatchException();
            }
            if (curChar >= snumChars) {
                curChar = 0;
                try {
                    snumChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (snumChars <= 0) {
                    return -1;
                }
            }
            return buf[curChar++];
        }

        public int nextInt() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            int res = 0;
            do {
                res *= 10;
                res += c - '0';
                c = read();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public String readString() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            StringBuilder res = new StringBuilder();
            do {
                res.appendCodePoint(c);
                c = read();
            } while (!isSpaceChar(c));
            return res.toString();
        }

        public boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }
    }
}

import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.InputMismatchException;

public class GridPathPermutationSolver {

    /**
     * Direction mappings corresponding to indices 0, 1, 2, 3.
     * 0: Down (1, 0), 1: Left (0, -1), 2: Up (-1, 0), 3: Right (0, 1)
     */
    private static final int[][] DIRECTIONS = {
        {1, 0},  // 0
        {0, -1}, // 1
        {-1, 0}, // 2
        {0, 1}   // 3
    };

    public static void main(String[] args) {
        new GridPathPermutationSolver().run();
    }

    public void run() {
        FastScanner scanner = new FastScanner();
        FastPrinter printer = new FastPrinter();
        try {
            solve(scanner, printer);
        } finally {
            printer.flush();
        }
    }

    private void solve(FastScanner scanner, FastPrinter printer) {
        int rows = scanner.nextInt();
        int cols = scanner.nextInt();
        char[][] grid = scanner.readCharGrid(rows);
        String moveSequence = scanner.readString();

        int[] startEnd = findStartAndEnd(grid);
        int startX = startEnd[0];
        int startY = startEnd[1];
        int endX = startEnd[2];
        int endY = startEnd[3];

        // Permutation array mapping character '0'-'3' to direction indices
        int[] moveOrder = {0, 1, 2, 3};
        char[] pathChars = moveSequence.toCharArray();
        int validPermutationCount = 0;

        do {
            if (canReachDestination(grid, moveOrder, pathChars, startX, startY, endX, endY)) {
                validPermutationCount++;
            }
        } while (generateNextPermutation(moveOrder));

        printer.println(validPermutationCount);
    }

    private int[] findStartAndEnd(char[][] grid) {
        int startX = -1, startY = -1, endX = -1, endY = -1;
        for (int i = 0; i < grid.length; i++) {
            for (int j = 0; j < grid[i].length; j++) {
                if (grid[i][j] == 'S') {
                    startX = i;
                    startY = j;
                } else if (grid[i][j] == 'E') {
                    endX = i;
                    endY = j;
                }
            }
        }
        return new int[]{startX, startY, endX, endY};
    }

    private boolean canReachDestination(char[][] grid, int[] moveOrder, char[] pathChars,
                                        int startX, int startY, int endX, int endY) {
        int currentX = startX;
        int currentY = startY;

        for (char moveChar : pathChars) {
            int moveIndex = moveChar - '0';
            if (moveIndex < 0 || moveIndex > 3) {
                throw new IllegalArgumentException("Invalid move character: " + moveChar);
            }

            // Apply permutation mapping: character -> direction index
            int[] direction = DIRECTIONS[moveOrder[moveIndex]];
            currentX += direction[0];
            currentY += direction[1];

            if (!isWithinBoundsAndNotWall(grid, currentX, currentY)) {
                return false;
            }
            if (currentX == endX && currentY == endY) {
                return true;
            }
        }
        return false;
    }

    private boolean isWithinBoundsAndNotWall(char[][] grid, int x, int y) {
        return x >= 0 && x < grid.length && y >= 0 && y < grid[0].length && grid[x][y] != '#';
    }

    /**
     * Generates the next lexicographical permutation of the array.
     * Returns false if the array is already in descending order.
     */
    private boolean generateNextPermutation(int[] array) {
        int n = array.length;
        int i = n - 2;
        while (i >= 0 && array[i] >= array[i + 1]) {
            i--;
        }
        if (i < 0) {
            return false;
        }

        int j = n - 1;
        while (array[i] < array[j]) {
            j--;
        }

        swap(array, i, j);
        reverse(array, i + 1, n - 1);
        return true;
    }

    private void swap(int[] array, int i, int j) {
        int temp = array[i];
        array[i] = array[j];
        array[j] = temp;
    }

    private void reverse(int[] array, int start, int end) {
        while (start < end) {
            swap(array, start, end);
            start++;
            end--;
        }
    }

    // -----------------------------------------------------------------------
    // Fast I/O Utilities
    // -----------------------------------------------------------------------

    private static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1024];
        private int bufferPointer = 0;
        private int bytesRead = 0;

        public FastScanner() {
            this.in = System.in;
        }

        private byte readByte() {
            if (bufferPointer >= bytesRead) {
                bufferPointer = 0;
                try {
                    bytesRead = in.read(buffer);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (bytesRead <= 0) {
                    return -1;
                }
            }
            return buffer[bufferPointer++];
        }

        private boolean isSpaceChar(int b) {
            return b < 33 || b > 126;
        }

        public int nextInt() {
            long result = nextLong();
            if (result < Integer.MIN_VALUE || result > Integer.MAX_VALUE) {
                throw new InputMismatchException("Integer out of range");
            }
            return (int) result;
        }

        public long nextLong() {
            long result = 0;
            boolean negative = false;
            int b = readByte();
            while (b != -1 && isSpaceChar(b)) {
                b = readByte();
            }
            if (b == '-') {
                negative = true;
                b = readByte();
            }
            while (b != -1 && !isSpaceChar(b)) {
                if (b < '0' || b > '9') {
                    throw new InputMismatchException();
                }
                result = result * 10 + (b - '0');
                b = readByte();
            }
            return negative ? -result : result;
        }

        public String readString() {
            StringBuilder sb = new StringBuilder();
            int b = readByte();
            while (b != -1 && isSpaceChar(b)) {
                b = readByte();
            }
            while (b != -1 && !isSpaceChar(b)) {
                sb.append((char) b);
                b = readByte();
            }
            return sb.toString();
        }

        public char[][] readCharGrid(int rows) {
            char[][] grid = new char[rows][];
            for (int i = 0; i < rows; i++) {
                grid[i] = readString().toCharArray();
            }
            return grid;
        }
    }

    private static class FastPrinter {
        private final PrintWriter out;

        public FastPrinter() {
            this.out = new PrintWriter(System.out);
        }

        public void println(Object obj) {
            out.println(obj);
        }

        public void flush() {
            out.flush();
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.util.Arrays;
import java.util.StringTokenizer;

/**
 * Solves a grid path problem by counting valid direction permutations.
 * Refactored for maintainability, testability, and code quality.
 */
public class GridPathSolver {

    // Direction vectors: Left, Right, Up, Down
    private static final int[][] DIRECTIONS = {
        {0, -1}, // Left
        {0, 1},  // Right
        {-1, 0}, // Up
        {1, 0}   // Down
    };

    // Instance state instead of static fields for better encapsulation
    private char[][] grid;
    private int rows, cols;
    private int startX, startY;
    private String path;

    public static void main(String[] args) {
        GridPathSolver solver = new GridPathSolver();
        try {
            solver.run();
        } catch (IOException e) {
            System.err.println("I/O error occurred: " + e.getMessage());
        }
    }

    /**
     * Orchestrates input reading, grid initialization, and computation.
     */
    public void run() throws IOException {
        FastScanner scanner = new FastScanner(System.in);

        String rowStr = scanner.next();
        if (rowStr == null) return; // Handle empty input gracefully

        rows = Integer.parseInt(rowStr);
        cols = Integer.parseInt(scanner.next());

        // Initialize grid with padded walls to simplify boundary checks
        grid = new char[rows + 2][cols + 2];
        char[] wallRow = new char[cols + 2];
        Arrays.fill(wallRow, '#');
        grid[0] = wallRow;
        grid[rows + 1] = wallRow;

        // Read grid content and locate starting position
        for (int i = 1; i <= rows; i++) {
            String line = scanner.next();
            grid[i][0] = '#';
            grid[i][cols + 1] = '#';
            for (int j = 0; j < line.length(); j++) {
                grid[i][j + 1] = line.charAt(j);
                if (line.charAt(j) == 'S') {
                    startX = i;
                    startY = j + 1;
                }
            }
        }

        // Read movement path
        path = scanner.next();
        if (path == null) path = "";

        int validPermutations = countValidPermutations();
        System.out.println(validPermutations);
    }

    /**
     * Counts how many permutations of the 4 directions result in a valid path.
     */
    private int countValidPermutations() {
        int[] permutation = {0, 1, 2, 3};
        return generatePermutations(permutation, 0);
    }

    /**
     * Generates all permutations using backtracking and counts valid paths.
     */
    private int generatePermutations(int[] p, int start) {
        if (start == p.length) {
            return isValidPath(p) ? 1 : 0;
        }

        int count = 0;
        for (int i = start; i < p.length; i++) {
            swap(p, start, i);
            count += generatePermutations(p, start + 1);
            swap(p, start, i); // Backtrack to restore state
        }
        return count;
    }

    private void swap(int[] arr, int i, int j) {
        int temp = arr[i];
        arr[i] = arr[j];
        arr[j] = temp;
    }

    /**
     * Validates a given direction order against the grid and path.
     * Returns true if the path reaches 'E' without hitting a wall.
     */
    private boolean isValidPath(int[] directionOrder) {
        int x = startX;
        int y = startY;

        for (int i = 0; i < path.length(); i++) {
            char c = path.charAt(i);
            if (c < '0' || c > '3') {
                return false; // Invalid direction character in path
            }
            int dirIndex = c - '0';
            int[] dir = directionOrder[dirIndex];

            x += dir[0];
            y += dir[1];

            // Explicit bounds check for safety (walls handle most cases)
            if (x < 0 || x >= grid.length || y < 0 || y >= grid[0].length) {
                return false;
            }

            if (grid[x][y] == '#') {
                return false; // Hit a wall
            }
            if (grid[x][y] == 'E') {
                return true; // Reached the exit
            }
        }
        return false; // Path ended without reaching exit
    }

    /**
     * Lightweight fast I/O utility for competitive programming scenarios.
     */
    private static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        public String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input", e);
                }
            }
            return st.nextToken();
        }
    }
}

import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

public class MazePathSolver {

    private static final int PERMUTATION_LENGTH = 4;
    private static final char START_CHAR = 'S';
    private static final char END_CHAR = 'E';
    private static final char WALL_CHAR = '#';

    // Directions: Up, Down, Right, Left
    private static final int[][] DIRECTIONS = {
        {-1,  0},
        { 1,  0},
        { 0,  1},
        { 0, -1}
    };

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            if (!scanner.hasNextLine()) {
                return;
            }

            String[] dimensions = scanner.nextLine().trim().split("\\s+");
            int rows = Integer.parseInt(dimensions[0]);
            int cols = Integer.parseInt(dimensions[1]);

            char[][] grid = new char[rows][cols];
            Coordinate start = null;
            Coordinate end = null;

            for (int i = 0; i < rows; i++) {
                String line = scanner.nextLine();
                grid[i] = line.toCharArray();
                for (int j = 0; j < line.length(); j++) {
                    char ch = line.charAt(j);
                    if (ch == START_CHAR) {
                        start = new Coordinate(i, j);
                    } else if (ch == END_CHAR) {
                        end = new Coordinate(i, j);
                    }
                }
            }

            String process = scanner.nextLine().trim();

            List<String> permutations = generatePermutations();
            int successfulCount = 0;

            for (String perm : permutations) {
                if (canReachEnd(grid, perm, process, start)) {
                    successfulCount++;
                }
            }

            System.out.println(successfulCount);
        }
    }

    /**
     * Generates all permutations of the digits "0123".
     */
    private static List<String> generatePermutations() {
        List<String> result = new ArrayList<>();
        char[] current = new char[PERMUTATION_LENGTH];
        boolean[] used = new boolean[PERMUTATION_LENGTH];
        buildPermutations(0, current, used, result);
        return result;
    }

    private static void buildPermutations(int index, char[] current, boolean[] used, List<String> result) {
        if (index == PERMUTATION_LENGTH) {
            result.add(new String(current));
            return;
        }
        for (int i = 0; i < PERMUTATION_LENGTH; i++) {
            if (!used[i]) {
                used[i] = true;
                current[index] = (char) ('0' + i);
                buildPermutations(index + 1, current, used, result);
                used[i] = false;
            }
        }
    }

    /**
     * Simulates movement from the start position following the process string.
     * The permutation string reorders how step indices map to directions.
     */
    private static boolean canReachEnd(char[][] grid, String perm, String process, Coordinate start) {
        int r = start.row;
        int c = start.col;

        for (char stepChar : process.toCharArray()) {
            int stepIndex = stepChar - '0';
            // The permutation maps the current step index to a direction index
            int dirIndex = perm.charAt(stepIndex) - '0';
            int[] dir = DIRECTIONS[dirIndex];

            int nextR = r + dir[0];
            int nextC = c + dir[1];

            // Boundary check
            if (nextR < 0 || nextR >= grid.length || nextC < 0 || nextC >= grid[0].length) {
                return false;
            }

            char cell = grid[nextR][nextC];
            if (cell == WALL_CHAR) {
                return false;
            }
            if (cell == END_CHAR) {
                return true;
            }

            r = nextR;
            c = nextC;
        }
        return false;
    }

    /**
     * Simple immutable data class to hold grid coordinates.
     */
    private static class Coordinate {
        final int row;
        final int col;

        Coordinate(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }
}

import java.io.InputStream;
import java.io.IOException;
import java.io.OutputStream;
import java.io.PrintWriter;
import java.util.InputMismatchException;

public class Main {
    public static void main(String[] args) {
        FastScanner in = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out);
        new B908().solve(in, out);
        out.close();
    }

    static class B908 {
        public void solve(FastScanner s, PrintWriter out) {
            int n = s.nextInt();
            int m = s.nextInt();
            boolean[][] grid = new boolean[n][m];
            int startR = 0, startC = 0, endR = 0, endC = 0;

            for (int i = 0; i < n; i++) {
                String row = s.next();
                for (int j = 0; j < m; j++) {
                    char ch = row.charAt(j);
                    if (ch == '#') continue;
                    grid[i][j] = true;
                    if (ch == 'S') {
                        startR = i;
                        startC = j;
                    } else if (ch == 'E') {
                        endR = i;
                        endC = j;
                    }
                }
            }

            String cinst = s.next();
            int[] instructions = new int[cinst.length()];
            for (int i = 0; i < instructions.length; i++) {
                instructions[i] = cinst.charAt(i) - '0';
            }

            SolverContext context = new SolverContext(n, m, grid, startR, startC, endR, endC, instructions);
            int[] perm = {0, 1, 2, 3};
            int validCount = permute(perm, 0, context);
            out.println(validCount);
        }

        /**
         * Recursively generates all permutations of the direction indices.
         * Backtracking ensures each permutation is tested without extra allocations.
         */
        private int permute(int[] arr, int start, SolverContext ctx) {
            if (start == arr.length) {
                return canReachEnd(arr, ctx) ? 1 : 0;
            }
            int count = 0;
            for (int i = start; i < arr.length; i++) {
                swap(arr, start, i);
                count += permute(arr, start + 1, ctx);
                swap(arr, start, i); // backtrack
            }
            return count;
        }

        private void swap(int[] arr, int i, int j) {
            int temp = arr[i];
            arr[i] = arr[j];
            arr[j] = temp;
        }

        /**
         * Simulates movement using a specific direction permutation.
         * Returns true if the destination is reached within the instruction sequence.
         */
        private boolean canReachEnd(int[] perm, SolverContext ctx) {
            int r = ctx.startR, c = ctx.startC;

            // Map instruction value (0-3) to direction index (0:UP, 1:LEFT, 2:RIGHT, 3:DOWN)
            int[] dirMap = new int[4];
            dirMap[perm[0]] = 0; // UP
            dirMap[perm[1]] = 1; // LEFT
            dirMap[perm[2]] = 2; // RIGHT
            dirMap[perm[3]] = 3; // DOWN

            for (int cmd : ctx.instructions) {
                int dir = dirMap[cmd];
                if (dir == 0) r--;
                else if (dir == 1) c--;
                else if (dir == 2) c++;
                else if (dir == 3) r++;

                // Boundary and obstacle check
                if (r < 0 || r >= ctx.n || c < 0 || c >= ctx.m || !ctx.grid[r][c]) {
                    return false;
                }
                // Destination check
                if (r == ctx.endR && c == ctx.endC) {
                    return true;
                }
            }
            return false;
        }

        /**
         * Bundles all solver state into a single immutable context object.
         * Improves readability and eliminates shared mutable state.
         */
        private static class SolverContext {
            final int n, m;
            final boolean[][] grid;
            final int startR, startC, endR, endC;
            final int[] instructions;

            SolverContext(int n, int m, boolean[][] grid, int startR, int startC, 
                          int endR, int endC, int[] instructions) {
                this.n = n;
                this.m = m;
                this.grid = grid;
                this.startR = startR;
                this.startC = startC;
                this.endR = endR;
                this.endC = endC;
                this.instructions = instructions;
            }
        }
    }

    /**
     * High-performance input scanner for competitive programming.
     * Kept largely intact as it's a standard utility, with minor cleanup.
     */
    static class FastScanner {
        private final InputStream stream;
        private final byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;

        public FastScanner(InputStream stream) {
            this.stream = stream;
        }

        int read() {
            if (numChars == -1) throw new InputMismatchException();
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0) return -1;
            }
            return buf[curChar++];
        }

        boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public String next() {
            int c = read();
            while (isSpaceChar(c)) c = read();
            StringBuilder res = new StringBuilder();
            do {
                res.appendCodePoint(c);
                c = read();
            } while (!isSpaceChar(c));
            return res.toString();
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Refactored version of the original 'scorify' program.
 * Improvements:
 * 1. Renamed class to follow Java naming conventions (GridPathCounter).
 * 2. Replaced the convoluted queue-based permutation logic with a clean recursive backtracking approach.
 * 3. Extracted path simulation into a dedicated, readable method.
 * 4. Used meaningful variable names and constants.
 * 5. Preserved utility methods (radixSort, FastScanner) with improved formatting and comments.
 */
public class GridPathCounter {

    private static final char[] DIRECTIONS = {'D', 'U', 'R', 'L'};

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner(System.in);

        int n = scanner.nextInt();
        int m = scanner.nextInt();

        char[][] grid = new char[n][m];
        int startR = 0, startC = 0, endR = 0, endC = 0;

        for (int i = 0; i < n; i++) {
            String line = scanner.next();
            grid[i] = line.toCharArray();

            int sIdx = line.indexOf('S');
            if (sIdx != -1) {
                startR = i;
                startC = sIdx;
            }

            int eIdx = line.indexOf('E');
            if (eIdx != -1) {
                endR = i;
                endC = eIdx;
            }
        }

        String moveIndices = scanner.next();
        int[] validCount = new int[1];
        char[] currentPath = new char[4];
        boolean[] used = new boolean[4];

        generatePermutations(0, n, m, grid, startR, startC, endR, endC, moveIndices, validCount, currentPath, used);
        System.out.println(validCount[0]);
    }

    /**
     * Recursively generates all permutations of 4 directions.
     */
    private static void generatePermutations(int idx, int n, int m, char[][] grid, 
                                             int startR, int startC, int endR, int endC, 
                                             String moveIndices, int[] validCount, 
                                             char[] currentPath, boolean[] used) {
        if (idx == 4) {
            if (simulatePath(n, m, grid, startR, startC, endR, endC, moveIndices, currentPath)) {
                validCount[0]++;
            }
            return;
        }

        for (int i = 0; i < 4; i++) {
            if (!used[i]) {
                used[i] = true;
                currentPath[idx] = DIRECTIONS[i];
                generatePermutations(idx + 1, n, m, grid, startR, startC, endR, endC, moveIndices, validCount, currentPath, used);
                used[i] = false;
            }
        }
    }

    /**
     * Simulates movement on the grid based on a direction mapping and move sequence.
     * Returns true if the destination 'E' is reached, false otherwise.
     */
    private static boolean simulatePath(int n, int m, char[][] grid, int r, int c, 
                                        int targetR, int targetC, String moveIndices, char[] pathMap) {
        for (int k = 0; k < moveIndices.length(); k++) {
            int moveIdx = moveIndices.charAt(k) - '0';
            if (moveIdx < 0 || moveIdx >= 4) continue; // Safety check for invalid indices

            char move = pathMap[moveIdx];
            switch (move) {
                case 'D': r++; break;
                case 'U': r--; break;
                case 'R': c++; break;
                case 'L': c--; break;
            }

            if (r < 0 || r >= n || c < 0 || c >= m || grid[r][c] == '#') {
                return false; // Out of bounds or hit a wall
            }

            if (r == targetR && c == targetC) {
                return true; // Reached destination
            }
        }
        return false;
    }

    /**
     * Utility: Radix sort for integer arrays. Preserved from original code.
     */
    public static int[] radixSort(int[] f) {
        return radixSort(f, f.length);
    }

    public static int[] radixSort(int[] f, int n) {
        int[] to = new int[n];

        // Sort by lower 16 bits
        int[] count = new int[65537];
        for (int i = 0; i < n; i++) {
            count[1 + (f[i] & 0xffff)]++;
        }
        for (int i = 1; i <= 65536; i++) {
            count[i] += count[i - 1];
        }
        for (int i = 0; i < n; i++) {
            to[count[f[i] & 0xffff]++] = f[i];
        }
        swap(f, to);

        // Sort by upper 16 bits
        count = new int[65537];
        for (int i = 0; i < n; i++) {
            count[1 + (f[i] >>> 16)]++;
        }
        for (int i = 1; i <= 65536; i++) {
            count[i] += count[i - 1];
        }
        for (int i = 0; i < n; i++) {
            to[count[f[i] >>> 16]++] = f[i];
        }
        swap(f, to);

        return f;
    }

    private static void swap(int[] a, int[] b) {
        int[] temp = a;
        a = b;
        b = temp;
    }

    /**
     * Utility: Fast I/O scanner for competitive programming.
     */
    private static class FastScanner {
        private final InputStream stream;
        private final byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;

        public FastScanner(InputStream stream) {
            this.stream = stream;
        }

        int read() {
            if (numChars == -1) {
                throw new InputMismatchException();
            }
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0) {
                    return -1;
                }
            }
            return buf[curChar++];
        }

        boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        boolean isEndline(int c) {
            return c == '\n' || c == '\r' || c == -1;
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public int[] nextArrayInt(int n) {
            int[] tab = new int[n];
            for (int i = 0; i < n; i++) {
                tab[i] = nextInt();
            }
            return tab;
        }

        public String[] nextArrayString(int n) {
            String[] tab = new String[n];
            for (int i = 0; i < n; i++) {
                tab[i] = next();
            }
            return tab;
        }

        public long nextLong() {
            return Long.parseLong(next());
        }

        public double nextDouble() {
            return Double.parseDouble(next());
        }

        public String next() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            StringBuilder res = new StringBuilder();
            do {
                res.appendCodePoint(c);
                c = read();
            } while (!isSpaceChar(c));
            return res.toString();
        }

        public String nextLine() {
            int c = read();
            while (isEndline(c)) {
                c = read();
            }
            StringBuilder res = new StringBuilder();
            do {
                res.appendCodePoint(c);
                c = read();
            } while (!isEndline(c));
            return res.toString();
        }
    }
}

import java.io.*;
import java.util.*;

public class Codechef {
    // Constants for grid characters
    private static final char START = 'S';
    private static final char EXIT = 'E';
    private static final char WALL = '#';

    // Direction deltas: index 0=Left, 1=Right, 2=Up, 3=Down
    private static final int[][] DEFAULT_DIRECTIONS = {
        {0, -1},
        {0, 1},
        {-1, 0},
        {1, 0}
    };

    public static void main(String[] args) {
        FastReader sc = new FastReader();
        PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out));

        try {
            // Read number of test cases. Fallback to 1 if not provided.
            int t = 1;
            try {
                t = sc.nextInt();
            } catch (Exception e) {
                // Input may not contain explicit test case count
            }

            while (t-- > 0) {
                solve(sc, out);
            }
        } finally {
            out.flush();
            out.close();
        }
    }

    private static void solve(FastReader sc, PrintWriter out) {
        int n = sc.nextInt();
        int m = sc.nextInt(); // Grid width, typically equals n
        char[][] grid = new char[n][n];
        int startX = -1, startY = -1;

        for (int i = 0; i < n; i++) {
            String row = sc.next();
            grid[i] = row.toCharArray();
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == START) {
                    startX = i;
                    startY = j;
                }
            }
        }

        String instructions = sc.next();

        // Generate all permutations of [0, 1, 2, 3] and count valid paths
        int[] permutation = {0, 1, 2, 3};
        int validPaths = countValidPermutations(permutation, 0, grid, startX, startY, instructions);
        out.println(validPaths);
    }

    // Generates all permutations using backtracking and counts valid ones
    private static int countValidPermutations(int[] p, int index, char[][] grid, int startX, int startY, String instructions) {
        if (index == p.length) {
            return simulatePath(grid, startX, startY, instructions, p) ? 1 : 0;
        }

        int count = 0;
        for (int i = index; i < p.length; i++) {
            swap(p, index, i);
            count += countValidPermutations(p, index + 1, grid, startX, startY, instructions);
            swap(p, index, i); // Backtrack to restore state
        }
        return count;
    }

    private static void swap(int[] arr, int i, int j) {
        int temp = arr[i];
        arr[i] = arr[j];
        arr[j] = temp;
    }

    private static boolean simulatePath(char[][] grid, int startX, int startY, String instructions, int[] permutation) {
        int x = startX;
        int y = startY;

        for (int k = 0; k < instructions.length(); k++) {
            // Efficiently convert char '0'-'3' to int 0-3
            int dirIndex = instructions.charAt(k) - '0';
            int[] dir = DEFAULT_DIRECTIONS[permutation[dirIndex]];

            x += dir[0];
            y += dir[1];

            if (x < 0 || x >= grid.length || y < 0 || y >= grid[0].length) {
                return false; // Out of bounds
            }
            if (grid[x][y] == WALL) {
                return false; // Hit obstacle
            }
            if (grid[x][y] == EXIT) {
                return true; // Reached exit
            }
        }
        return false;
    }

    // Fast I/O helper class
    public static class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        public String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            String s = next();
            return s == null ? 0 : Integer.parseInt(s);
        }

        public long nextLong() {
            String s = next();
            return s == null ? 0L : Long.parseLong(s);
        }

        public double nextDouble() {
            String s = next();
            return s == null ? 0.0 : Double.parseDouble(s);
        }
    }
}

import java.io.*;
import java.util.*;

public class Solution {
    public static void main(String[] args) {
        FastReader reader = new FastReader();
        PrintWriter out = new PrintWriter(System.out);
        solve(reader, out);
        out.flush();
    }

    private static void solve(FastReader reader, PrintWriter out) {
        int n = reader.nextInt();
        int m = reader.nextInt();
        char[][] grid = new char[n][m];
        int startI = -1, startJ = -1;

        // Read grid and locate starting position 'S'
        for (int i = 0; i < n; i++) {
            String row = reader.next();
            grid[i] = row.toCharArray();
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == 'S') {
                    startI = i;
                    startJ = j;
                }
            }
        }

        String path = reader.next();
        int validPaths = 0;

        // Direction offsets: 0=Up, 1=Down, 2=Left, 3=Right
        int[] dx = {-1, 1, 0, 0};
        int[] dy = {0, 0, -1, 1};

        // Generate all 24 permutations of {0, 1, 2, 3} to map input digits to physical directions
        int[] perm = {0, 1, 2, 3};
        int[][] permutations = new int[24][4];
        int[] permCount = {0};
        generatePermutations(perm, 0, 3, permutations, permCount);

        // Simulate movement for each direction mapping
        for (int[] p : permutations) {
            int curI = startI;
            int curJ = startJ;
            boolean reached = false;

            for (int k = 0; k < path.length(); k++) {
                int dirIdx = p[path.charAt(k) - '0'];
                curI += dx[dirIdx];
                curJ += dy[dirIdx];

                // Check bounds and obstacles
                if (!isValid(curI, curJ, n, m) || grid[curI][curJ] == '#') {
                    break;
                }
                // Check if destination reached
                if (grid[curI][curJ] == 'E') {
                    reached = true;
                    break;
                }
            }
            if (reached) {
                validPaths++;
            }
        }

        out.println(validPaths);
    }

    private static boolean isValid(int i, int j, int n, int m) {
        return i >= 0 && j >= 0 && i < n && j < m;
    }

    private static void generatePermutations(int[] arr, int l, int r, int[][] results, int[] count) {
        if (l == r) {
            System.arraycopy(arr, 0, results[count[0]++], 0, 4);
        } else {
            for (int i = l; i <= r; i++) {
                swap(arr, l, i);
                generatePermutations(arr, l + 1, r, results, count);
                swap(arr, l, i);
            }
        }
    }

    private static void swap(int[] arr, int i, int j) {
        int temp = arr[i];
        arr[i] = arr[j];
        arr[j] = temp;
    }

    /**
     * Fast I/O helper class for competitive programming.
     */
    static class FastReader {
        BufferedReader br;
        StringTokenizer st;

        public FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

/**
 * Solves a grid path problem by counting how many permutations of direction mappings
 * allow a successful path from 'S' (start) to 'E' (end) without hitting walls or bounds.
 */
public class GridPathPermutationSolver {

    // Direction deltas for u, d, l, r respectively
    private static final int[] DR = {-1, 1, 0, 0};
    private static final int[] DC = {0, 0, -1, 1};

    public static void main(String[] args) {
        // Use try-with-resources for proper resource management
        try (FastScanner scanner = new FastScanner(System.in)) {
            int n = scanner.nextInt();
            int m = scanner.nextInt();

            char[][] grid = new char[n][m];
            int startR = 0, startC = 0, endR = 0, endC = 0;

            // Parse grid and locate start/end points
            for (int i = 0; i < n; i++) {
                String row = scanner.next();
                for (int j = 0; j < m; j++) {
                    grid[i][j] = row.charAt(j);
                    if (grid[i][j] == 'S') {
                        startR = i;
                        startC = j;
                    } else if (grid[i][j] == 'E') {
                        endR = i;
                        endC = j;
                    }
                }
            }

            String instructions = scanner.next();

            // Backtracking setup to generate all permutations of [0, 1, 2, 3]
            int[] dirOrder = new int[4];
            boolean[] used = new boolean[4];
            int[] validCount = new int[1]; // Wrapper to allow modification inside recursion

            generatePermutations(dirOrder, used, 0, grid, n, m, 
                                 startR, startC, endR, endC, 
                                 instructions, validCount);

            System.out.println(validCount[0]);
        } catch (IOException e) {
            System.err.println("Failed to read input: " + e.getMessage());
        }
    }

    /**
     * Recursively generates all permutations of direction indices.
     */
    private static void generatePermutations(int[] dirOrder, boolean[] used, int index,
                                             char[][] grid, int n, int m,
                                             int startR, int startC, int endR, int endC,
                                             String instructions, int[] validCount) {
        // Base case: permutation complete, simulate the path
        if (index == 4) {
            if (simulatePath(grid, n, m, startR, startC, endR, endC, dirOrder, instructions)) {
                validCount[0]++;
            }
            return;
        }

        // Try each unused direction index
        for (int i = 0; i < 4; i++) {
            if (!used[i]) {
                used[i] = true;
                dirOrder[index] = i;
                generatePermutations(dirOrder, used, index + 1, grid, n, m,
                                     startR, startC, endR, endC, instructions, validCount);
                used[i] = false; // Backtrack
            }
        }
    }

    /**
     * Simulates movement according to the current direction mapping and instruction string.
     * Returns true if the path successfully reaches the destination.
     */
    private static boolean simulatePath(char[][] grid, int n, int m, int startR, int startC,
                                        int endR, int endC, int[] dirOrder, String instructions) {
        int r = startR;
        int c = startC;

        for (int i = 0; i < instructions.length(); i++) {
            char instr = instructions.charAt(i);
            int dirIdx;

            // Map instruction digit to the corresponding direction index in the current permutation
            switch (instr) {
                case '0': dirIdx = dirOrder[0]; break;
                case '1': dirIdx = dirOrder[1]; break;
                case '2': dirIdx = dirOrder[2]; break;
                case '3': dirIdx = dirOrder[3]; break;
                default: throw new IllegalArgumentException("Invalid instruction character: " + instr);
            }

            r += DR[dirIdx];
            c += DC[dirIdx];

            // Check bounds and walls
            if (r < 0 || r >= n || c < 0 || c >= m || grid[r][c] == '#') {
                return false;
            }
            // Early exit on success
            if (r == endR && c == endC) {
                return true;
            }
        }
        return false;
    }

    /**
     * Fast I/O utility for competitive programming and performance-critical applications.
     */
    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input stream", e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            String token = next();
            if (token == null) throw new RuntimeException("Unexpected end of input");
            return Integer.parseInt(token);
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

/**
 * Solves a grid pathfinding problem where a string of digits dictates movement.
 * Tries all permutations of direction mappings to count valid paths from 'S' to 'E'.
 */
public class Main {

    public static void main(String[] args) throws Exception {
        FastScanner sc = new FastScanner();
        PrintWriter out = new PrintWriter(System.out);

        int n = sc.nextInt();
        int m = sc.nextInt();
        char[][] grid = new char[n][m];
        int startR = -1;
        int startC = -1;

        // Read grid and locate starting position
        for (int i = 0; i < n; i++) {
            String row = sc.next();
            grid[i] = row.toCharArray();
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == 'S') {
                    startR = i;
                    startC = j;
                }
            }
        }

        String path = sc.next();
        int[] validCount = new int[1];
        findValidPermutations(grid, path, startR, startC, validCount);

        out.println(validCount[0]);
        out.flush();
    }

    /**
     * Generates all permutations of direction mappings and checks each against the grid.
     */
    private static void findValidPermutations(char[][] grid, String path, int startR, int startC, int[] validCount) {
        int[] dirMap = {0, 1, 2, 3};
        permute(dirMap, 0, grid, path, startR, startC, validCount);
    }

    /**
     * Recursively generates permutations of the given array.
     */
    private static void permute(int[] arr, int idx, char[][] grid, String path, int startR, int startC, int[] validCount) {
        if (idx == arr.length) {
            if (canReachEnd(grid, path, arr, startR, startC, 0)) {
                validCount[0]++;
            }
            return;
        }
        for (int i = idx; i < arr.length; i++) {
            swap(arr, idx, i);
            permute(arr, idx + 1, grid, path, startR, startC, validCount);
            swap(arr, idx, i); // backtrack
        }
    }

    private static void swap(int[] arr, int i, int j) {
        int temp = arr[i];
        arr[i] = arr[j];
        arr[j] = temp;
    }

    /**
     * Checks if a path following the current direction mapping reaches 'E'.
     * Preserves original logic: reaching 'E' early returns true; reaching end of path 
     * without 'E' returns false.
     */
    private static boolean canReachEnd(char[][] grid, String path, int[] dirMap, int r, int c, int idx) {
        // Boundary checks
        if (r < 0 || c < 0 || r >= grid.length || c >= grid[0].length) {
            return false;
        }

        char cell = grid[r][c];
        if (cell == '#') {
            return false;
        }

        // If we reach 'E', return true immediately (matches original behavior)
        if (cell == 'E') {
            return true;
        }

        // If path is exhausted but we haven't reached 'E'
        if (idx == path.length()) {
            return false;
        }

        int moveDigit = path.charAt(idx) - '0';
        int direction = dirMap[moveDigit];

        // Directions mapping: 0=Up, 1=Down, 2=Right, 3=Left
        int[] dr = {-1, 1, 0, 0};
        int[] dc = {0, 0, 1, -1};

        return canReachEnd(grid, path, dirMap, r + dr[direction], c + dc[direction], idx + 1);
    }

    /**
     * Fast I/O helper for competitive programming style input parsing.
     */
    private static class FastScanner {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastScanner() {
            reader = new BufferedReader(new InputStreamReader(System.in), 32768);
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Input stream closed unexpectedly", e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            String s = next();
            return s == null ? 0 : Integer.parseInt(s);
        }

        public long nextLong() {
            String s = next();
            return s == null ? 0L : Long.parseLong(s);
        }

        public double nextDouble() {
            String s = next();
            return s == null ? 0.0 : Double.parseDouble(s);
        }
    }
}

import java.io.*;
import java.util.*;

public class CFB {
    // Direction deltas: 0=Down, 1=Right, 2=Left, 3=Up
    // Matches original logic: 0->x++, 1->y++, 2->y--, 3->x--
    private static final int[] DR = {1, 0, 0, -1};
    private static final int[] DC = {0, 1, -1, 0};

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner(System.in);

        int rows = scanner.nextInt();
        int cols = scanner.nextInt();

        boolean[][] isObstacle = new boolean[rows][cols];
        int startRow = -1, startCol = -1;
        int endRow = -1, endCol = -1;

        for (int i = 0; i < rows; i++) {
            String line = scanner.next();
            for (int j = 0; j < cols; j++) {
                char c = line.charAt(j);
                if (c == '#') {
                    isObstacle[i][j] = true;
                } else if (c == 'S') {
                    startRow = i;
                    startCol = j;
                } else if (c == 'E') {
                    endRow = i;
                    endCol = j;
                }
            }
        }

        String directionSequence = scanner.next();
        int validCount = countValidPermutations(rows, cols, isObstacle, 
                                                startRow, startCol, endRow, endCol, 
                                                directionSequence);
        System.out.println(validCount);
    }

    /**
     * Entry point for permutation generation. Initializes tracking arrays and starts recursion.
     */
    private static int countValidPermutations(int rows, int cols, boolean[][] isObstacle,
                                              int startRow, int startCol, int endRow, int endCol,
                                              String directionSequence) {
        int[] mapping = new int[4];
        boolean[] used = new boolean[4];
        return generatePermutations(0, mapping, used, rows, cols, isObstacle,
                                    startRow, startCol, endRow, endCol, directionSequence);
    }

    /**
     * Recursively generates all permutations of direction mappings [0,1,2,3].
     */
    private static int generatePermutations(int index, int[] mapping, boolean[] used,
                                            int rows, int cols, boolean[][] isObstacle,
                                            int startRow, int startCol, int endRow, int endCol,
                                            String directionSequence) {
        if (index == 4) {
            return simulatePath(mapping, rows, cols, isObstacle, startRow, startCol, endRow, endCol, directionSequence) ? 1 : 0;
        }

        int count = 0;
        for (int d = 0; d < 4; d++) {
            if (!used[d]) {
                used[d] = true;
                mapping[index] = d;
                count += generatePermutations(index + 1, mapping, used, rows, cols, isObstacle,
                                              startRow, startCol, endRow, endCol, directionSequence);
                used[d] = false; // Backtrack
            }
        }
        return count;
    }

    /**
     * Simulates movement on the grid using a specific direction mapping.
     * Returns true if the path successfully reaches the destination.
     */
    private static boolean simulatePath(int[] mapping, int rows, int cols, boolean[][] isObstacle,
                                        int startRow, int startCol, int endRow, int endCol,
                                        String directionSequence) {
        int r = startRow;
        int c = startCol;

        for (int i = 0; i < directionSequence.length(); i++) {
            int originalDir = directionSequence.charAt(i) - '0';
            int actualDir = mapping[originalDir];

            int nr = r + DR[actualDir];
            int nc = c + DC[actualDir];

            // Check boundaries and obstacles
            if (nr < 0 || nr >= rows || nc < 0 || nc >= cols || isObstacle[nr][nc]) {
                return false;
            }

            r = nr;
            c = nc;

            // Early exit if destination is reached
            if (r == endRow && c == endCol) {
                return true;
            }
        }
        return false;
    }

    /**
     * High-performance input scanner for competitive programming scenarios.
     */
    private static class FastScanner {
        private final InputStream stream;
        private final byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;

        public FastScanner(InputStream stream) {
            this.stream = stream;
        }

        private int read() {
            if (numChars == -1) {
                throw new InputMismatchException();
            }
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0) {
                    return -1;
                }
            }
            return buf[curChar++];
        }

        private boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        public String next() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
                if (c == -1) throw new InputMismatchException();
            }
            StringBuilder res = new StringBuilder();
            do {
                res.appendCodePoint(c);
                c = read();
            } while (!isSpaceChar(c));
            return res.toString();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }

        public double nextDouble() {
            return Double.parseDouble(next());
        }
    }
}

import java.util.Scanner;

/**
 * A solver for grid pathfinding problems where direction mappings are permuted.
 * It determines how many permutations of digit-to-direction mappings allow a path
 * from 'S' to 'E' without hitting walls or boundaries.
 */
public class GridPathSolver {

    // Direction constants and their coordinate deltas (row, col)
    // 0: UP, 1: DOWN, 2: LEFT, 3: RIGHT
    private static final int[][] MOVEMENTS = {
        {-1, 0}, // UP
        {1, 0},  // DOWN
        {0, -1}, // LEFT
        {0, 1}   // RIGHT
    };

    public static void main(String[] args) {
        // Use try-with-resources for automatic resource management of Scanner
        try (Scanner scanner = new Scanner(System.in)) {
            // Read grid dimensions
            if (!scanner.hasNextInt()) {
                return;
            }
            int rows = scanner.nextInt();
            int cols = scanner.nextInt();
            scanner.nextLine(); // Consume the newline character after integers

            char[][] grid = new char[rows][];
            int startRow = -1;
            int startCol = -1;
            int endRow = -1;
            int endCol = -1;

            // Read the grid and locate Start ('S') and End ('E')
            for (int i = 0; i < rows; i++) {
                if (scanner.hasNextLine()) {
                    String line = scanner.nextLine();
                    grid[i] = line.toCharArray();

                    for (int j = 0; j < line.length(); j++) {
                        if (grid[i][j] == 'S') {
                            startRow = i;
                            startCol = j;
                        } else if (grid[i][j] == 'E') {
                            endRow = i;
                            endCol = j;
                        }
                    }
                }
            }

            // Read the path sequence
            String pathSequence = "";
            if (scanner.hasNextLine()) {
                pathSequence = scanner.nextLine();
            }

            // Basic validation
            if (startRow == -1 || endRow == -1 || rows == 0 || cols == 0) {
                System.out.println(0);
                return;
            }

            // Solve the problem
            int validPermutationsCount = solve(grid, pathSequence, startRow, startCol, endRow, endCol);
            System.out.println(validPermutationsCount);

        } catch (Exception e) {
            // In a production environment, use a logging framework
            e.printStackTrace();
        }
    }

    /**
     * Orchestrates the permutation generation and path simulation.
     */
    private static int solve(char[][] grid, String pathSequence, int startRow, int startCol, int endRow, int endCol) {
        // directionToDigit[d] stores the digit (0-3) that triggers direction d
        // d=0 (UP), d=1 (DOWN), d=2 (LEFT), d=3 (RIGHT)
        int[] directionToDigit = new int[4]; 
        boolean[] usedDigits = new boolean[4];

        // Start recursive permutation generation
        return generatePermutations(grid, pathSequence, startRow, startCol, endRow, endCol, 
                                    directionToDigit, usedDigits, 0);
    }

    /**
     * Recursively generates all permutations of digit assignments for the 4 directions.
     * 
     * @param directionIndex The current direction index (0-3) being assigned a digit
     * @return The count of valid permutations found in this branch
     */
    private static int generatePermutations(char[][] grid, String pathSequence, 
                                            int startRow, int startCol, int endRow, int endCol,
                                            int[] directionToDigit, boolean[] usedDigits, 
                                            int directionIndex) {

        // Base case: All 4 directions have been assigned a unique digit
        if (directionIndex == 4) {
            // Check if the current mapping allows a successful path
            if (simulatePath(grid, pathSequence, startRow, startCol, endRow, endCol, directionToDigit)) {
                return 1;
            }
            return 0;
        }

        int validCount = 0;
        // Try assigning each unused digit (0, 1, 2, 3) to the current direction
        for (int digit = 0; digit < 4; digit++) {
            if (!usedDigits[digit]) {
                usedDigits[digit] = true;
                directionToDigit[directionIndex] = digit; // Assign 'digit' to 'directionIndex'

                validCount += generatePermutations(grid, pathSequence, startRow, startCol, endRow, endCol,
                                                   directionToDigit, usedDigits, directionIndex + 1);

                // Backtrack: unassign digit
                usedDigits[digit] = false;
            }
        }
        return validCount;
    }

    /**
     * Simulates the path based on the current digit-to-direction mapping.
     * 
     * @param directionToDigit Array where index is direction (0-3) and value is the digit (0-3)
     * @return true if the path reaches the End point, false otherwise
     */
    private static boolean simulatePath(char[][] grid, String pathSequence, 
                                        int startRow, int startCol, int endRow, int endCol,
                                        int[] directionToDigit) {

        int currentRow = startRow;
        int currentCol = startCol;

        for (int i = 0; i < pathSequence.length(); i++) {
            char c = pathSequence.charAt(i);
            // Convert char digit to integer value (e.g., '0' -> 0)
            int digit = c - '0'; 

            // Find which direction corresponds to this digit
            int direction = -1;
            for (int d = 0; d < 4; d++) {
                if (directionToDigit[d] == digit) {
                    direction = d;
                    break;
                }
            }

            // If digit is not in our mapping (invalid input char), skip or fail
            if (direction == -1) continue; 

            // Apply movement based on direction
            currentRow += MOVEMENTS[direction][0];
            currentCol += MOVEMENTS[direction][1];

            // Check if reached End
            if (currentRow == endRow && currentCol == endCol) {
                return true;
            }

            // Check bounds
            if (currentRow < 0 || currentRow >= grid.length || 
                currentCol < 0 || currentCol >= grid[0].length) {
                return false; // Out of bounds
            }

            // Check walls
            if (grid[currentRow][currentCol] == '#') {
                return false; // Hit wall
            }
        }
        return false; // Path ended without reaching End
    }
}

import java.util.Scanner;

public class MazeSolver {
    // Direction deltas: 0=Up, 1=Down, 2=Left, 3=Right
    private static final int[] DR = {-1, 1, 0, 0};
    private static final int[] DC = {0, 0, -1, 1};

    private char[][] grid;
    private int rows, cols;
    private int startRow, startCol;
    private String directions;

    public static void main(String[] args) {
        MazeSolver solver = new MazeSolver();
        solver.solve();
    }

    public void solve() {
        try (Scanner sc = new Scanner(System.in)) {
            if (!sc.hasNextInt()) return;

            this.rows = sc.nextInt();
            this.cols = sc.nextInt();
            this.grid = new char[this.rows][this.cols];

            for (int i = 0; i < this.rows; i++) {
                String line = sc.next();
                for (int j = 0; j < line.length(); j++) {
                    this.grid[i][j] = line.charAt(j);
                    if (this.grid[i][j] == 'S') {
                        this.startRow = i;
                        this.startCol = j;
                    }
                }
            }

            this.directions = sc.next();
            int validCount = countValidPermutations();
            System.out.println(validCount);
        }
    }

    private boolean isValidPosition(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols && grid[r][c] != '#';
    }

    private boolean simulatePath(int[] directionMapping) {
        int r = startRow;
        int c = startCol;

        for (char moveChar : directions.toCharArray()) {
            int dirIndex = moveChar - '0';
            // Guard against unexpected input characters
            if (dirIndex < 0 || dirIndex > 3) {
                return false;
            }

            int dr = DR[dirIndex];
            int dc = DC[dirIndex];
            r += dr;
            c += dc;

            if (!isValidPosition(r, c)) {
                return false;
            }
            if (grid[r][c] == 'E') {
                return true;
            }
        }
        return false;
    }

    private int countValidPermutations() {
        int[] perm = {0, 1, 2, 3};
        return generatePermutations(perm, 0);
    }

    private int generatePermutations(int[] perm, int start) {
        if (start == perm.length) {
            return simulatePath(perm) ? 1 : 0;
        }

        int count = 0;
        for (int i = start; i < perm.length; i++) {
            swap(perm, start, i);
            count += generatePermutations(perm, start + 1);
            swap(perm, start, i); // backtrack
        }
        return count;
    }

    private void swap(int[] arr, int i, int j) {
        int temp = arr[i];
        arr[i] = arr[j];
        arr[j] = temp;
    }
}

import java.io.*;
import java.util.*;

public class Solution {
    private int rows, cols;
    private char[][] board;
    private char[] path;
    private int startRow, startCol;
    private int validPermutationCount;

    public static void main(String[] args) {
        // try-with-resources ensures PrintWriter is properly flushed and closed
        try (PrintWriter out = new PrintWriter(System.out)) {
            FastScanner sc = new FastScanner(System.in);
            new Solution().solve(sc, out);
        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    public void solve(FastScanner sc, PrintWriter out) {
        // Read grid dimensions
        rows = sc.nextInt();
        cols = sc.nextInt();

        // Read the board
        board = new char[rows][];
        for (int i = 0; i < rows; i++) {
            board[i] = sc.next().toCharArray();
        }

        // Read the movement path
        path = sc.next().toCharArray();

        // Locate the starting position
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (board[i][j] == 'S') {
                    startRow = i;
                    startCol = j;
                }
            }
        }

        // Generate all permutations of directions {1, 2, 3, 4} and count valid paths
        int[] directions = {1, 2, 3, 4};
        validPermutationCount = 0;
        generatePermutations(directions, 0);

        out.println(validPermutationCount);
    }

    /**
     * Recursively generates all permutations of the directions array.
     * When a complete permutation is formed, it checks if it yields a valid path.
     */
    private void generatePermutations(int[] dirs, int idx) {
        if (idx == dirs.length) {
            if (isValidPath(dirs[0], dirs[1], dirs[2], dirs[3])) {
                validPermutationCount++;
            }
            return;
        }

        for (int i = idx; i < dirs.length; i++) {
            swap(dirs, idx, i);
            generatePermutations(dirs, idx + 1);
            swap(dirs, idx, i); // Backtrack
        }
    }

    /**
     * Simulates movement based on a direction mapping.
     * Returns true if the path successfully reaches 'E', false otherwise.
     */
    private boolean isValidPath(int upDir, int downDir, int leftDir, int rightDir) {
        int r = startRow;
        int c = startCol;

        for (char move : path) {
            int dirCode = move - '0'; // Use character literal instead of magic number 48

            if (dirCode == upDir) r--;
            else if (dirCode == downDir) r++;
            else if (dirCode == leftDir) c--;
            else if (dirCode == rightDir) c++;
            else return false; // Invalid direction character in path

            // Boundary check
            if (r < 0 || r >= rows || c < 0 || c >= cols) return false;
            // Obstacle check
            if (board[r][c] == '#') return false;
            // Success check
            if (board[r][c] == 'E') return true;
        }
        return false;
    }

    private void swap(int[] arr, int i, int j) {
        int temp = arr[i];
        arr[i] = arr[j];
        arr[j] = temp;
    }

    /**
     * FastScanner for efficient input parsing.
     * Replaces custom byte-buffering with standard BufferedReader + StringTokenizer
     * for better readability and maintainability while retaining performance.
     */
    private static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        public String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) throw new NoSuchElementException();
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

public class BuggyBot {
    private static final char[] DIRECTIONS = {'l', 'r', 'u', 'd'};

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        if (!scanner.hasNextInt()) {
            return;
        }

        int rows = scanner.nextInt();
        int cols = scanner.nextInt();
        scanner.nextLine(); // Consume the newline left by nextInt()

        char[][] maze = new char[rows][cols];
        int startRow = -1, startCol = -1;
        int endRow = -1, endCol = -1;

        // Read maze and locate start/end positions
        for (int i = 0; i < rows; i++) {
            String line = scanner.hasNextLine() ? scanner.nextLine() : "";
            // Ensure we don't exceed array bounds if input line is shorter than expected
            int len = Math.min(line.length(), cols);
            for (int j = 0; j < len; j++) {
                maze[i][j] = line.charAt(j);
                if (maze[i][j] == 'S') {
                    startRow = i;
                    startCol = j;
                } else if (maze[i][j] == 'E') {
                    endRow = i;
                    endCol = j;
                }
            }
        }

        // Read movement commands
        String commands = scanner.hasNextLine() ? scanner.nextLine().trim() : "";

        // Generate all permutations of "0123" programmatically
        List<String> permutations = generatePermutations("0123");

        int successfulPaths = 0;
        for (String perm : permutations) {
            if (simulate(maze, rows, cols, startRow, startCol, endRow, endCol, commands, perm)) {
                successfulPaths++;
            }
        }

        System.out.println(successfulPaths);
        scanner.close();
    }

    /**
     * Generates all permutations of the given string.
     */
    private static List<String> generatePermutations(String str) {
        List<String> result = new ArrayList<>();
        permute(str.toCharArray(), 0, result);
        return result;
    }

    private static void permute(char[] arr, int k, List<String> result) {
        if (k == arr.length - 1) {
            result.add(new String(arr));
        } else {
            for (int i = k; i < arr.length; i++) {
                swap(arr, i, k);
                permute(arr, k + 1, result);
                swap(arr, i, k);
            }
        }
    }

    private static void swap(char[] arr, int i, int j) {
        char temp = arr[i];
        arr[i] = arr[j];
        arr[j] = temp;
    }

    /**
     * Simulates bot movement for a given direction mapping permutation.
     * Returns true if the bot successfully reaches 'E', false otherwise.
     */
    private static boolean simulate(char[][] maze, int rows, int cols,
                                    int startRow, int startCol,
                                    int endRow, int endCol,
                                    String commands, String perm) {
        // Build fast lookup: command char ('0'-'3') -> direction char ('l','r','u','d')
        char[] commandToDir = new char[256];
        for (int k = 0; k < 4; k++) {
            commandToDir[perm.charAt(k)] = DIRECTIONS[k];
        }

        int r = startRow;
        int c = startCol;

        for (int i = 0; i < commands.length(); i++) {
            char cmd = commands.charAt(i);
            if (cmd < 0 || cmd >= 256 || commandToDir[cmd] == 0) {
                return false; // Invalid command encountered
            }
            char dir = commandToDir[cmd];

            // Validate current cell before moving (matches original intent)
            if (maze[r][c] != '.' && maze[r][c] != 'S') {
                return false;
            }

            // Apply movement based on direction
            switch (dir) {
                case 'l': c--; break;
                case 'r': c++; break;
                case 'u': r--; break;
                case 'd': r++; break;
            }

            // Check boundaries
            if (r < 0 || r >= rows || c < 0 || c >= cols) {
                return false;
            }

            // Check for wall
            if (maze[r][c] == '#') {
                return false;
            }

            // Check if destination reached
            if (maze[r][c] == 'E') {
                return true;
            }
        }
        return false;
    }
}

import java.io.*;
import java.util.StringTokenizer;

/**
 * Refactored solution for TaskB.
 * Improvements:
 * 1. Removed duplicate imports and consolidated IO imports.
 * 2. Extracted direction constants for readability and maintainability.
 * 3. Separated concerns: permutation generation, path simulation, and I/O handling.
 * 4. Replaced deeply nested loops with a clean recursive permutation generator.
 * 5. Improved variable naming (e.g., startX, startY, directionMap, DX/DY).
 * 6. Added JavaDoc and inline comments for future maintainers.
 * 7. Fixed silent exception swallowing in the fast I/O helper.
 */
public class Main {

    // Direction offsets: UP, DOWN, LEFT, RIGHT
    private static final int[] DX = {-1, 1, 0, 0};
    private static final int[] DY = {0, 0, -1, 1};

    public static void main(String[] args) {
        Kattio in = new Kattio(System.in);
        PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out));
        solve(in, out);
        out.flush();
        out.close();
    }

    /**
     * Entry point for the problem solver.
     */
    private static void solve(Kattio in, PrintWriter out) {
        int n = in.nextInt();
        int m = in.nextInt();

        char[][] maze = new char[n][m];
        int startX = 0, startY = 0;
        int endX = 0, endY = 0;

        // Read maze grid and locate start/end positions
        for (int i = 0; i < n; i++) {
            String row = in.next();
            maze[i] = row.toCharArray();
            for (int j = 0; j < m; j++) {
                char cell = maze[i][j];
                if (cell == 'S') {
                    startX = i;
                    startY = j;
                } else if (cell == 'E') {
                    endX = i;
                    endY = j;
                }
            }
        }

        char[] moves = in.next().toCharArray();

        // Generate all permutations of direction mappings and count valid paths
        int[] directionMap = {0, 1, 2, 3};
        int validCount = generatePermutations(directionMap, 0, maze, n, m, startX, startY, endX, endY, moves);
        out.println(validCount);
    }

    /**
     * Recursively generates all permutations of the direction mapping array.
     * Counts how many permutations result in a valid path from Start to End.
     */
    private static int generatePermutations(int[] mapping, int index, char[][] maze, int n, int m,
                                            int startX, int startY, int endX, int endY, char[] moves) {
        // Base case: all positions filled, simulate the path
        if (index == mapping.length) {
            return simulatePath(maze, n, m, startX, startY, endX, endY, mapping, moves) ? 1 : 0;
        }

        int count = 0;
        for (int i = index; i < mapping.length; i++) {
            swap(mapping, index, i);
            count += generatePermutations(mapping, index + 1, maze, n, m, startX, startY, endX, endY, moves);
            swap(mapping, index, i); // backtrack to restore array for next iteration
        }
        return count;
    }

    private static void swap(int[] arr, int i, int j) {
        int temp = arr[i];
        arr[i] = arr[j];
        arr[j] = temp;
    }

    /**
     * Simulates movement through the maze based on the current direction mapping.
     * Returns true if the end position is reached, false otherwise.
     */
    private static boolean simulatePath(char[][] maze, int n, int m, int startX, int startY,
                                        int endX, int endY, int[] mapping, char[] moves) {
        int x = startX;
        int y = startY;

        for (char move : moves) {
            int digit = move - '0';
            int dirIndex = mapping[digit];

            x += DX[dirIndex];
            y += DY[dirIndex];

            // Check if end position is reached
            if (x == endX && y == endY) {
                return true;
            }

            // Check bounds
            if (x < 0 || x >= n || y < 0 || y >= m) {
                return false;
            }

            // Check for walls
            if (maze[x][y] == '#') {
                return false;
            }
        }
        return false;
    }

    /**
     * Fast I/O helper class tailored for competitive programming.
     * Extends PrintWriter to allow direct printing while buffering output.
     */
    static class Kattio extends PrintWriter {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public Kattio(InputStream in) {
            this(in, System.out);
        }

        public Kattio(InputStream in, OutputStream out) {
            super(new BufferedOutputStream(out));
            this.reader = new BufferedReader(new InputStreamReader(in));
        }

        public String next() {
            return nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(nextToken());
        }

        private String nextToken() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return tokenizer.nextToken();
        }
    }
}

