            int x = startX;
            int y = startY;

            for (int i = 0; i < moveSequence.length(); i++) {
                char move = sequence[moveSequence.charAt(i) - '0'];

                // Fixed critical bug: replaced reference equality (==) with switch on char
                switch (move) {
                    case 'R': y++; break;
                    case 'L': y--; break;
                    case 'U': x++; break; // Preserved original coordinate mapping
                    case 'D': x--; break;
                }

                // Combined boundary and obstacle checks
                if (x < 0 || y < 0 || x >= rows || y >= cols || grid[x][y] == '#') {
                    return false;
                }
                if (grid[x][y] == 'E') {
                    return true;
                }
            }
            return false;
        }
    }

    static class InputReader {
        private final InputStream stream;
        private final byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;
        private SpaceCharFilter filter;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        public int read() {
            if (numChars == -1) {
                throw new InputMismatchException();
            }
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0) {
                    return -1;
                }
            }
            return buf[curChar++];
        }

        public int nextInt() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                res *= 10;
                res += c - '0';
                c = read();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public boolean isSpaceChar(int c) {
            return filter != null ? filter.isSpaceChar(c) : isWhitespace(c);
        }

        public static boolean isWhitespace(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        private String readLine0() {
            StringBuilder buf = new StringBuilder();
            int c = read();
            while (c != '\n' && c != -1) {
                if (c != '\r') {
                    buf.appendCodePoint(c);
                }
                c = read();
            }
            return buf.toString();
        }

        public String readLine() {
            String s = readLine0();
            while (s != null && s.trim().isEmpty()) {
                s = readLine0();
            }
            return s;
        }

        public interface SpaceCharFilter {
            boolean isSpaceChar(int ch);
        }
    }

    static class OutputWriter {
        private final PrintWriter writer;

        public OutputWriter(OutputStream outputStream) {
            writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(outputStream)));
        }

        public OutputWriter(Writer writer) {
            this.writer = new PrintWriter(writer);
        }

        public void close() {
            writer.close();
        }

        public void println(int i) {
            writer.println(i);
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

/**
 * Simulates robot movement on a grid and counts how many direction permutations
 * successfully guide the robot from 'S' to 'E' following a given command sequence.
 */
public class RobotPathCounter {

    // Direction offsets: 0=Right, 1=Left, 2=Down, 3=Up
    private static final int[][] DIRECTIONS = {
        {0, 1},   // Right
        {0, -1},  // Left
        {1, 0},   // Down
        {-1, 0}   // Up
    };

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner();

        String nStr = scanner.next();
        if (nStr == null) return;
        int n = Integer.parseInt(nStr);
        int m = scanner.nextInt();

        char[][] grid = new char[n][m];
        int startRow = -1;
        int startCol = -1;

        // Parse grid and locate start position
        for (int i = 0; i < n; i++) {
            String line = scanner.next();
            grid[i] = line.toCharArray();
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == 'S') {
                    startRow = i;
                    startCol = j;
                }
            }
        }

        // Read movement commands
        char[] commands = scanner.next().toCharArray();

        // Generate all permutations of directions and count valid paths
        int[] currentPermutation = new int[4];
        boolean[] used = new boolean[4];
        int validPathCount = generatePermutations(
            currentPermutation, used, 0, n, m, grid, startRow, startCol, commands
        );

        System.out.println(validPathCount);
    }

    /**
     * Recursively generates all permutations of direction indices [0,1,2,3]
     * and counts how many result in a valid path to 'E'.
     */
    private static int generatePermutations(int[] current, boolean[] used, int depth,
                                            int n, int m, char[][] grid,
                                            int startRow, int startCol, char[] commands) {
        if (depth == 4) {
            return simulatePath(grid, startRow, startCol, current, commands, n, m) ? 1 : 0;
        }

        int count = 0;
        for (int i = 0; i < 4; i++) {
            if (!used[i]) {
                used[i] = true;
                current[depth] = i;
                count += generatePermutations(current, used, depth + 1, n, m, grid, startRow, startCol, commands);
                used[i] = false;
            }
        }
        return count;
    }

    /**
     * Simulates the robot's movement based on a specific direction permutation
     * and the given command sequence.
     * Returns true if the robot reaches 'E' without going out of bounds or hitting obstacles.
     */
    private static boolean simulatePath(char[][] grid, int startRow, int startCol,
                                        int[] path, char[] commands, int n, int m) {
        int curRow = startRow;
        int curCol = startCol;

        for (char command : commands) {
            int dirIndex = command - '0';
            if (dirIndex < 0 || dirIndex > 3) {
                return false; // Invalid command digit
            }

            int[] direction = DIRECTIONS[path[dirIndex]];
            curRow += direction[0];
            curCol += direction[1];

            if (curRow < 0 || curRow >= n || curCol < 0 || curCol >= m) {
                return false; // Out of bounds
            }
            if (grid[curRow][curCol] == '#') {
                return false; // Obstacle hit
            }
            if (grid[curRow][curCol] == 'E') {
                return true; // Reached destination
            }
        }
        return false;
    }

    /**
     * Fast input reader for competitive programming and performance-critical I/O.
     */
    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input", e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            String s = next();
            return s == null ? 0 : Integer.parseInt(s);
        }

        long nextLong() {
            String s = next();
            return s == null ? 0L : Long.parseLong(s);
        }

        double nextDouble() {
            String s = next();
            return s == null ? 0.0 : Double.parseDouble(s);
        }

        String nextLine() {
            String str = "";
            try {
                str = br.readLine();
            } catch (IOException e) {
                throw new RuntimeException("Failed to read line", e);
            }
            return str;
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

/**
 * Solves a maze navigation problem by testing all permutations of direction mappings.
 * The input provides a grid with start ('S') and end ('E') positions, and a command string
 * consisting of digits '0'-'3'. Each digit represents a direction, but the actual mapping
 * (which digit corresponds to UP/DOWN/LEFT/RIGHT) is unknown. The program counts how many
 * valid permutations allow the path from 'S' to 'E' without hitting walls or boundaries.
 */
public class MazeSolver {

    // Direction deltas: UP, DOWN, LEFT, RIGHT
    private static final int[] DX = {0, 0, -1, 1};
    private static final int[] DY = {-1, 1, 0, 0};

    public static void main(String[] args) {
        FastScanner sc = new FastScanner();
        int rows = sc.nextInt();
        int cols = sc.nextInt();

        boolean[][] isWall = new boolean[rows][cols];
        int startX = -1, startY = -1, endX = -1, endY = -1;

        for (int r = 0; r < rows; r++) {
            String line = sc.next();
            for (int c = 0; c < cols; c++) {
                char ch = line.charAt(c);
                if (ch == '#') {
                    isWall[r][c] = true;
                } else if (ch == 'S') {
                    startX = c;
                    startY = r;
                } else if (ch == 'E') {
                    endX = c;
                    endY = r;
                }
                // '.' represents an empty walkable cell (default false)
            }
        }

        String commands = sc.next();
        int validMappings = 0;

        // Iterate over all permutations of direction assignments for command digits '0'-'3'
        for (int map0 = 0; map0 < 4; map0++) {
            for (int map1 = 0; map1 < 4; map1++) {
                if (map1 == map0) continue;
                for (int map2 = 0; map2 < 4; map2++) {
                    if (map2 == map0 || map2 == map1) continue;
                    for (int map3 = 0; map3 < 4; map3++) {
                        if (map3 == map0 || map3 == map1 || map3 == map2) continue;

                        if (simulate(isWall, rows, cols, startX, startY, endX, endY, commands, map0, map1, map2, map3)) {
                            validMappings++;
                        }
                    }
                }
            }
        }

        System.out.println(validMappings);
    }

    /**
     * Simulates the path through the maze given a specific direction mapping.
     *
     * @param isWall     2D boolean array representing maze walls
     * @param rows       Number of rows in the maze
     * @param cols       Number of columns in the maze
     * @param startX     Starting column index
     * @param startY     Starting row index
     * @param endX       Target column index
     * @param endY       Target row index
     * @param commands   String of command digits ('0'-'3')
     * @param map0       Direction code assigned to command '0'
     * @param map1       Direction code assigned to command '1'
     * @param map2       Direction code assigned to command '2'
     * @param map3       Direction code assigned to command '3'
     * @return true if the path reaches the end, false otherwise
     */
    private static boolean simulate(boolean[][] isWall, int rows, int cols,
                                    int startX, int startY, int endX, int endY,
                                    String commands, int map0, int map1, int map2, int map3) {
        int[] commandToDirection = {map0, map1, map2, map3};
        int x = startX;
        int y = startY;

        for (int i = 0; i < commands.length(); i++) {
            int cmd = commands.charAt(i) - '0';
            int direction = commandToDirection[cmd];

            x += DX[direction];
            y += DY[direction];

            // Check boundaries
            if (x < 0 || x >= cols || y < 0 || y >= rows) {
                return false;
            }
            // Check walls
            if (isWall[y][x]) {
                return false;
            }
            // Check goal
            if (x == endX && y == endY) {
                return true;
            }
        }
        return false;
    }

    /**
     * Helper class for fast and safe input reading.
     */
    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
            st = new StringTokenizer("");
        }

        public String next() {
            while (!st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            String token = next();
            if (token == null) throw new RuntimeException("Unexpected end of input");
            return Integer.parseInt(token);
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

public class GB17B {
    // Direction constants mapping command values to cardinal directions
    private static final int UP = 1;
    private static final int DOWN = 2;
    private static final int LEFT = 3;
    private static final int RIGHT = 4;

    public static void main(String[] args) throws IOException {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));

        // 1. Parse grid dimensions
        StringTokenizer dimTokenizer = new StringTokenizer(reader.readLine());
        int rows = Integer.parseInt(dimTokenizer.nextToken());
        int cols = Integer.parseInt(dimTokenizer.nextToken());

        // 2. Read grid and locate start position
        char[][] grid = new char[rows][cols];
        int[] startPos = new int[2];

        for (int r = 0; r < rows; r++) {
            String line = reader.readLine();
            for (int c = 0; c < cols; c++) {
                grid[r][c] = line.charAt(c);
                if (grid[r][c] == 'S') {
                    startPos[0] = r;
                    startPos[1] = c;
                }
            }
        }

        // 3. Parse movement commands (handles multiple spaces safely)
        String commandLine = reader.readLine();
        StringTokenizer cmdTokenizer = new StringTokenizer(commandLine);
        int[] commands = new int[cmdTokenizer.countTokens()];
        for (int i = 0; i < commands.length; i++) {
            commands[i] = Integer.parseInt(cmdTokenizer.nextToken());
        }

        int validPermutationCount = 0;

        // 4. Iterate through all permutations of directions for commands 1, 2, 3, 4
        for (int d1 = UP; d1 <= RIGHT; d1++) {
            for (int d2 = UP; d2 <= RIGHT; d2++) {
                if (d2 == d1) continue;
                for (int d3 = UP; d3 <= RIGHT; d3++) {
                    if (d3 == d1 || d3 == d2) continue;
                    for (int d4 = UP; d4 <= RIGHT; d4++) {
                        if (d4 == d1 || d4 == d2 || d4 == d3) continue;

                        if (simulatePath(grid, rows, cols, startPos, commands, d1, d2, d3, d4)) {
                            validPermutationCount++;
                        }
                    }
                }
            }
        }

        System.out.println(validPermutationCount);
    }

    /**
     * Simulates movement based on a specific direction mapping for commands 1-4.
     * Returns true if the path reaches the exit 'E' without crashing.
     */
    private static boolean simulatePath(char[][] grid, int rows, int cols, int[] startPos,
                                        int[] commands, int d1, int d2, int d3, int d4) {
        int r = startPos[0];
        int c = startPos[1];

        for (int cmd : commands) {
            switch (cmd) {
                case UP:    r -= 1; break;
                case DOWN:  r += 1; break;
                case LEFT:  c -= 1; break;
                case RIGHT: c += 1; break;
                default:    return false; // Invalid command encountered
            }

            // Check boundary conditions
            if (r < 0 || r >= rows || c < 0 || c >= cols) {
                return false;
            }

            char currentCell = grid[r][c];
            if (currentCell == '#') {
                return false; // Obstacle collision
            }
            if (currentCell == 'E') {
                return true; // Successfully reached exit
            }
        }

        // Commands exhausted without reaching exit
        return false;
    }
}

import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

public class Main {

    // Directions: Left, Right, Down, Up
    // Mapped to indices 0, 1, 2, 3 respectively
    // Format: {row_change, col_change}
    private static final int[][] DIRECTIONS = {
        {0, -1}, // Left (y--)
        {0, 1},  // Right (y++)
        {1, 0},  // Down (x++)
        {-1, 0}  // Up (x--)
    };

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        // 1. Read Grid Dimensions
        if (!scanner.hasNextInt()) {
            scanner.close();
            return;
        }
        int rows = scanner.nextInt();
        int cols = scanner.nextInt();
        scanner.nextLine(); // Consume the newline character after dimensions

        // 2. Read Grid and Find Start/End Points
        char[][] grid = new char[rows][cols];
        int startX = -1, startY = -1;
        int endX = -1, endY = -1;

        for (int i = 0; i < rows; i++) {
            String line = scanner.nextLine();
            // Safety check for line length to prevent IndexOutOfBoundsException
            int length = Math.min(line.length(), cols);
            for (int j = 0; j < length; j++) {
                grid[i][j] = line.charAt(j);
                if (grid[i][j] == 'S') {
                    startX = i;
                    startY = j;
                } else if (grid[i][j] == 'E') {
                    endX = i;
                    endY = j;
                }
            }
        }

        // 3. Read Instructions
        String instructionLine = "";
        if (scanner.hasNextLine()) {
            instructionLine = scanner.nextLine();
        }
        char[] instructions = instructionLine.toCharArray();

        // 4. Permutations of Directions
        // We generate all permutations of the 4 direction indices [0, 1, 2, 3].
        // Each permutation represents a mapping of digits 1, 2, 3, 4 to directions.
        // Index 0 of permutation -> Direction for Digit '1'
        // Index 1 of permutation -> Direction for Digit '2'
        // ...

        int[] count = new int[1];
        List<Integer> currentPermutation = new ArrayList<>();
        boolean[] used = new boolean[4];

        // Start permutation generation
        generatePermutations(0, 4, currentPermutation, used, rows, cols, grid, 
                             startX, startY, endX, endY, instructions, count);

        System.out.println(count[0]);
        scanner.close();
    }

    /**
     * Recursively generates permutations of direction indices.
     * 
     * @param index Current depth of recursion
     * @param n Size of the permutation (4)
     * @param currentPermutation List holding the current permutation
     * @param used Boolean array to track used indices
     * @param rows Number of rows in grid
     * @param cols Number of columns in grid
     * @param grid The map
     * @param startX Start X coordinate
     * @param startY Start Y coordinate
     * @param endX End X coordinate
     * @param endY End Y coordinate
     * @param instructions The sequence of moves
     * @param count Array to store the result count (mutable reference)
     */
    private static void generatePermutations(int index, int n, List<Integer> currentPermutation, 
                                             boolean[] used, int rows, int cols, char[][] grid,
                                             int startX, int startY, int endX, int endY,
                                             char[] instructions, int[] count) {
        if (index == n) {
            // A full permutation is ready.
            // currentPermutation contains a permutation of [0, 1, 2, 3].
            // We map: Digit '1' -> direction at index 0, Digit '2' -> direction at index 1, etc.
            if (simulatePath(rows, cols, grid, startX, startY, endX, endY, instructions, currentPermutation)) {
                count[0]++;
            }
            return;
        }

        for (int i = 0; i < n; i++) {
            if (!used[i]) {
                used[i] = true;
                currentPermutation.add(i);

                generatePermutations(index + 1, n, currentPermutation, used, rows, cols, grid,
                                     startX, startY, endX, endY, instructions, count);

                // Backtrack
                currentPermutation.remove(currentPermutation.size() - 1);
                used[i] = false;
            }
        }
    }

    /**
     * Simulates the path based on the current direction mapping.
     * 
     * @param rows Number of rows
     * @param cols Number of columns
     * @param grid The map
     * @param startX Start X coordinate
     * @param startY Start Y coordinate
     * @param endX End X coordinate
     * @param endY End Y coordinate
     * @param instructions The sequence of moves
     * @param directionMap Mapping from digit index (0 for '1', 1 for '2'...) to direction index
     * @return true if path reaches destination, false otherwise
     */
    private static boolean simulatePath(int rows, int cols, char[][] grid, 
                                        int startX, int startY, int endX, int endY,
                                        char[] instructions, List<Integer> directionMap) {
        int x = startX;
        int y = startY;

        for (char c : instructions) {
            int dirIndex = -1;
            if (c == '1') dirIndex = directionMap.get(0);
            else if (c == '2') dirIndex = directionMap.get(1);
            else if (c == '3') dirIndex = directionMap.get(2);
            else if (c == '4') dirIndex = directionMap.get(3);
            else continue; // Ignore invalid characters

            int[] move = DIRECTIONS[dirIndex];
            int nextX = x + move[0];
            int nextY = y + move[1];

            // Check boundaries
            if (nextX < 0 || nextX >= rows || nextY < 0 || nextY >= cols) {
                return false;
            }

            // Check obstacle
            if (grid[nextX][nextY] == '#') {
                return false;
            }

            x = nextX;
            y = nextY;

            // Check if reached destination
            if (x == endX && y == endY) {
                return true;
            }
        }
        return false;
    }
}

import java.io.*;
import java.util.*;

public class Main {
    /** Direction vectors: Down, Right, Up, Left */
    private static final int[][] DIRECTIONS = {
        {1, 0}, {0, 1}, {-1, 0}, {0, -1}
    };

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out);

        int rowCount = scanner.nextInt();
        int colCount = scanner.nextInt();

        char[][] maze = new char[rowCount][colCount];
        int startRow = -1;
        int startCol = -1;

        // Read maze and locate starting position
        for (int i = 0; i < rowCount; i++) {
            String line = scanner.next();
            maze[i] = line.toCharArray();
            for (int j = 0; j < colCount; j++) {
                if (maze[i][j] == 'S') {
                    startRow = i;
                    startCol = j;
                }
            }
        }

        String path = scanner.next();

        // Generate all permutations of direction mappings and count valid ones
        int[] directionPermutation = {0, 1, 2, 3};
        int validMappingCount = countValidMappings(
            directionPermutation, 0, maze, rowCount, colCount, startRow, startCol, path
        );

        out.println(validMappingCount);
        out.flush();
    }

    /**
     * Recursively generates all permutations of the direction mapping array
     * and counts how many successfully navigate the path to 'E'.
     */
    private static int countValidMappings(int[] permutation, int index, char[][] maze, 
                                          int rowCount, int colCount, int startRow, int startCol, String path) {
        if (index == permutation.length) {
            return canReachEnd(permutation, maze, rowCount, colCount, startRow, startCol, path) ? 1 : 0;
        }

        int count = 0;
        for (int i = index; i < permutation.length; i++) {
            swap(permutation, index, i);
            count += countValidMappings(permutation, index + 1, maze, rowCount, colCount, startRow, startCol, path);
            swap(permutation, index, i); // backtrack
        }
        return count;
    }

    /**
     * Simulates movement through the maze according to the current direction mapping.
     * Returns true if the path reaches 'E' without hitting walls or going out of bounds.
     */
    private static boolean canReachEnd(int[] directionMapping, char[][] maze, int rowCount, 
                                       int colCount, int startRow, int startCol, String path) {
        int row = startRow;
        int col = startCol;

        for (int k = 0; k < path.length(); k++) {
            char stepChar = path.charAt(k);
            int dirIndex = directionMapping[stepChar - '0'];

            row += DIRECTIONS[dirIndex][0];
            col += DIRECTIONS[dirIndex][1];

            // Check bounds
            if (row < 0 || row >= rowCount || col < 0 || col >= colCount) {
                return false;
            }
            // Check obstacle
            if (maze[row][col] == '#') {
                return false;
            }
            // Check target
            if (maze[row][col] == 'E') {
                return true;
            }
        }
        return false;
    }

    /** Swaps two elements in an array */
    private static void swap(int[] arr, int i, int j) {
        int temp = arr[i];
        arr[i] = arr[j];
        arr[j] = temp;
    }

    /**
     * Fast I/O utility class for competitive programming and performance-critical applications.
     */
    static class FastScanner {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        FastScanner(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
            tokenizer = null;
        }

        String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line, " \t\n\r\f,");
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        long nextLong() {
            return Long.parseLong(next());
        }

