public class Main {
    // Direction mappings: 0 -> Down, 1 -> Up, 2 -> Right, 3 -> Left
    private static final int[][] DIRECTIONS = {
        {1, 0},  // Down
        {-1, 0}, // Up
        {0, 1},  // Right
        {0, -1}  // Left
    };
    private static final int DIR_COUNT = 4;

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
